INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10001, '临江仙 · 夜归临皋', NULL, 1060, 3406, 2, 2, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/866713.htm', '', '夜饮东坡醒复醉，归来仿佛三更。家童鼻息已雷鸣，敲门都不应，倚杖听江声。
长恨此身非我有，何时忘却营营？夜阑风静縠纹平，小舟从此逝，江海寄余生。', '这首词作于神宗元豐五年，即东坡黄州之贬的第三年，写作者深秋之夜在东坡雪堂开怀畅饮，醉後返归临皋住所的情景，表达了词人退避社会的生活态度和希望彻底解脱的出世意念。词人静夜沉思，豁然有悟，既然自己无法掌握命运，不如全身免祸。是夜风静纹平，心与景会，神与物游。他要趁此良辰美景，驾一叶扁舟，随波流逝，任意东西，将自己的有限生命融化在无限的大自然之中。', '临江仙：词牌名，原是唐教坊曲，後用作词牌。《乐章集》入「仙吕调」，《张子野词》入「高平调」，元高拭词注「南吕调」。李後主词名《谢新恩》。贺方回词有「人归落雁後」句，名《雁後归》。韩涧泉词有「罗帐画屏新梦悄」句，名《画屏春》。李易安词有「庭院深深深几许」句，名《庭院深深》。《临江仙》源起颇多歧说。南宋黄叔旸《花庵词选》注，「唐词多缘题所赋，《临江仙》之言水仙，亦其一也。」明董逢元《唐词纪》认为，此调「多赋水媛江妃」，即多为咏水中的女神。调名本意即咏临江凭吊水仙女神。近代学者任半塘先生据敦煌词有句云「岸阔临江底见沙」谓词意涉及临江。「临」本意是俯身看物；临江而看的自是水仙。但中国历代所祭的水仙并不确定。像东汉袁康、吴平《越绝书》所记的春秋吴国功勋伍子胥受谗而死成为长江水仙，东晋王子年《拾遗记》称战国楚大夫屈原为湘江水仙。此外，还有琴高、郭景纯、陶岘（Xiàn）各为不同水仙的记载。另外，投湘江而死的舜之二妃、三国魏曹子建笔下的洛河女神，都是人们祭祀的对象。按《临江仙》调起于唐时，惟以前後阕起句、结句辨体，其前後两起句七字、两结句七字者，以和成绩词为主，无别家可校。其前後两起句七字、两结句四字、五字者，以张子澄词为主，而以牛希济词之起句用韵、李後主词之前後换韵、顾夐（Xiòng）词之结句添字类列。其前後两起句俱六字、两结俱五字两句者，以徐昌图词为主，而以向芗林词之第四句减字类列。其前後两起句俱七字、两结俱五字两句者，以贺方回词为主，而以晏小山词之第二句添字、冯正中词之前後换韵、後阕第四句减字、王逐客词之後阕第四句减字类列。盖词谱专主辨体，原以创始之词、正体者列前，减字、添字者列後，兹从体制编次，稍诠世代，故不能仍按字数多寡也。他调准此。双调小令，五十八字，上下阕各三平韵。约有三格，第三格增二字。此调唱时音节需流丽谐婉，声情掩抑。柳耆卿演为慢曲，《乐章集》又有七十四字一体，九十三字一体，汲古阁本俱刻《临江仙》，今照《花草粹编》校定，一作《临江仙引》，一作《临江仙慢》。
「夜归临皋」：诸本皆无题，唯《东坡外集》注云：「在黄州作。」
鼻息已雷鸣：傅子立注：「韩退之《石鼎联句诗序》：『衡山道士轩辕弥明，与进士刘师服、校书郎侯喜，联《石鼎诗》已毕。道士曰：「此皆不足与语，吾闭口矣。」即倚墙睡，鼻息如雷鸣。』」刘尚荣按：「详见《五百家注〈昌黎文集〉·卷二十一》。按傅注乃引述其大意，未遵原句。」已，《苏长公二妙集》本作「如」。
倚杖：元延祐本原校：「一作『久立』」。
此身非我有：傅子立注引《庄子·卷二十二·〈外篇·知北游〉》：「舜问乎丞曰：『道可得而有乎？』曰：『汝身非汝有也，汝何得有夫道？』舜曰：『吾身非吾有也，孰有之哉？』曰：『是天地之委形也；』」
营营：傅子立注引《庄子·卷二十三·〈杂篇·庚桑楚〉》：「无使汝思虑营营。」
縠（hú）纹：傅子立注：「风息浪平，水纹如縠。《选》诗：『风浪吹纹縠。』」刘尚荣按：「《文选》无此句。疑是王逢《进酒歌》『风过细浪生纹縠』之误引。」
「小舟从此逝，江海寄余生」句："余"一作："馀"。傅子立注：「魏草堂：『何日扁舟去，江上负烟蓑。』杜子美：『张公一生江海客。』」刘尚荣按：「魏句见《宋百家诗》存本《东观集》，题作《暮春闲望》，前句原作『扁舟何日去』，疑傅注误倒。杜句出《洗兵马》，见《九家集注杜诗·卷四》。」', '夜里在东坡饮酒，醉而复醒，醒了又饮。归来时好像已经是夜半三更了。家童鼾声如雷，反复叫门也不应。衹好拄杖伫立江边聆听江水奔流的声音。
深遗憾身在宦途，我已身不由己。什么时候才能够忘却追逐功名？夜深风静，水波不兴。真想乘上小船从此消逝，在烟波江湖中了却馀生。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b17d0ac1145494bb7a", "shortContent": "宋神宗元丰三年（1080），苏轼因乌台诗案，谪贬黄州（今湖北黄冈），住在城南长江边上的临皋亭。后来，又在不远处开垦了一片荒地，种上庄稼树木，名之曰东坡，自号东坡居士。还在这里筑屋名雪堂。对于经受了一场严重政治迫害的苏轼来说，此时是劫后余生，内心是忿懑而痛苦的。但他没有被痛苦压倒，而是表现出一种超人的旷达，一种不以世事萦怀的恬淡精神。有时布衣芒屩，出入于阡陌之上，有时月夜泛舟，放浪于山水之间，他要从...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b7d635634aee3e9a7b", "shortContent": "宋神宗元丰三年（1080），苏轼因乌台诗案，谪贬黄州（今湖北黄冈），住在城南长江边上的临皋亭。后来，又在不远处开垦了一片荒地，种上庄稼树木，名之曰东坡，自号东坡居士。还在这里筑屋名雪堂。对于经受了一场严重政治迫害的苏轼来说，此时是劫后馀生，内心是忿懑而痛苦的。但他没有被痛苦压倒，而是表现出一种超人的旷达，一种不以世事萦怀的恬淡精神。有时布衣芒屩，出入于阡陌之上，有时月夜泛舟，放浪于山水之间，他要从...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253f534825dee9fd6e0", "shortContent": "宋神宗元丰三年（1080），苏轼因乌台诗案，谪贬黄州（今湖北黄冈），住在城南长江边上的临皋亭。后来，又在不远处开垦了一片荒地，种上庄稼树木，名之曰东坡，自号东坡居士。还在这里筑屋名雪堂。对于经受了一场严重政治迫害的苏轼来说，此时是劫后余生，内心是忿懑而痛苦的。但他没有被痛苦压倒，而是表现出一种超人的旷达，一种不以世事萦怀的恬淡精神。有时布衣芒%，出入于阡陌之上，有时月夜泛舟，放浪于山水之间，他要从...", "authors": ["高　原"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7b7ccdb86c49f28f7a", "shortContent": "《苏诗总案》根据叶梦得《避暑录话》编于元丰五年（1082）九月，作于黄州，朱本、龙本、曹本、薛本从之。石唐本认为《总案》“误推早了一年”、“当作于元丰六年（1083）四月以前”。孔《谱》、邹王本也都认为作于元丰六年四月。保苅佳昭《苏轼词编年考》分析说，从《避暑录话》的记述可见，苏轼在黄州之时，先有他已死的讹传，“未几”，还有他“挂冠服江边，拏舟长哺去”的讹传。苏轼《书谤》（《苏轼文集》卷七十一）云...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3d73206168b2e020c9", "shortContent": "宋神宗元丰三年（1080），苏轼因乌台诗案，谪贬黄州（今湖北黄冈），住在城南长江边上的临皋亭。后来，又在不远处开垦了一片荒地，种上庄稼树木，名之曰东坡，自号东坡居士，还在这里筑屋名“雪堂”。本词正是作于谪居黄州时期，雪堂夜饮醉归，是一首即事抒情之作。\n上阕写东坡醉酒夜归临皋的情景。首句“夜饮东坡醒复醉”交代了酣醉的时间与地点，“复”字写出了作者纵情饮酒，豪兴淋漓，醉了又醒，醒来再醉，如此反复。醉意...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702f7ccdb86c49f291f9", "shortContent": "宋神宗元丰三年（1080），苏轼因乌台诗案，谪贬黄州（今湖北黄冈），住在城南长江边上的临皋亭。后来，又在不远处开垦了一片荒地，种上庄稼树木，名之曰东坡，自号东坡居士，还在这里筑屋名“雪堂”。本词正是作于谪居黄州时期，雪堂夜饮醉归，是一首即事抒情之作。\n\n上阕写东坡醉酒夜归临皋的情景。首句“夜饮东坡醒复醉”交代了酣醉的时间与地点，“复”字写出了作者纵情饮酒，豪兴淋漓，醉了又醒，醒来再醉，如此反复。醉...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271abc9ebcc6fbea1a4ed", "shortContent": "宋神宗元丰三年（1080），苏轼因乌台诗案，谪贬黄州（今湖北黄冈），住在城南长江边上的临皋亭。后来，又在不远处开垦了一片荒地，种上庄稼树木，名之曰东坡，自号东坡居士，还在这里筑屋名“雪堂”。本词正是作于谪居黄州时期，雪堂夜饮醉归，是一首即事抒情之作。\n上阕写东坡醉酒夜归临皋的情景。首句“夜饮东坡醒复醉”交代了酣醉的时间与地点，“复”字写出了作者纵情饮酒，豪兴淋漓，醉了又醒，醒来再醉，如此反复。醉意...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "64683000b6a81d0c5301c938", "shortContent": "宋神宗元丰三年（1080），苏轼因乌台诗案，谪贬黄州（今湖北黄冈），住在城南长江边上的临皋亭。后来，又在不远处开垦了一片荒地，种上庄稼树木，名之曰东坡，自号东坡居士。还在这里筑屋名雪堂。对于经受了一场严重政治迫害的苏轼来说，此时是劫后余生，内心是忿懑而痛苦的。但他没有被痛苦压倒，而是表现出一种超人的旷达，一种不以世事萦怀的恬淡精神。有时布衣芒[插图]，出入于阡陌之上，有时月夜泛舟，放浪于山水之间，...", "authors": ["高原"], "pressName": "上海辞书出版社"}]', '宋·葉石林《避暑录话·巻上》：子瞻在黄州，病赤眼，逾月不出。或疑有他疾，过客遂传以为死矣。有语范景仁于许昌者，景仁绝不置疑，即举袂大恸，召子弟具金帛，遣人赒其家。子弟徐言此传闻未审，当先书以问其安否，得实吊恤之未晚。乃走仆以往，子瞻发书大笑，故後量移汝州，谢表有云：「疾病连年，人皆相传为已死。」未几，复与数客饮江上，夜归，江面际天，风露浩然，有当其意，乃作歌辞，所谓「夜阑风静縠纹平，小舟从此逝，江海寄余生」者，与客大歌数过而散。翌日，喧传子瞻夜作此辞，挂冠服江边，拿舟长啸去矣。郡守徐君猷闻之，惊且惧，以为州失罪人，急命驾往谒，则子瞻鼻鼾如雷，犹未兴也。然此语卒传至京师，虽裕陵亦闻而疑之。', 'indent', 1357749647, '57ae79400a2b580063150e39', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10015, '江城子 · 密州出猎', NULL, 1319, 3406, 4, 13, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/168012.htm', '', '老夫聊发少年狂，左牵黄，右擎苍，锦帽貂裘，千骑卷平冈。为报倾城随太守，亲射虎，看孙郎。
酒酣胸胆尚开张。鬓微霜，又何妨！持节云中，何日遣冯唐？会挽雕弓如满月，西北望，射天狼。', '此词做于熙宁八年（西元一〇七五年）作者任密州太守时，通过平冈围猎壮阔场面的描写，抒发了渴望报国立功的豪情壮志。作者在《与鲜于子骏书》中曾云：「近确颇作小词，虽无柳七郎风味，亦自是一家，呵呵。数日前猎于郊外，所获颇多。做得一阙，令东州壮士抵掌顿足而歌之，吹笛击鼓以为节，颇壮观也。」可见此词乃作者得意之作。', '江城子：词牌名。据唐·崔令钦《教坊记》、敦煌曲子词与现存晚唐前文人词，均无载录《江城子》，故是调当兴于晚唐。王昆吾《唐代酒令艺术》谓是调源自唐著词曲调，即唐时酒令，知是调始流行于晚唐酒筵上，经文人加工，遂成小令词调。唐五代时为单调，始见《花间集》韦端己词，单调三十五字，七句五平韵，间有三十六字、三十七字诸格。可见唐五代《江城子》调兴之初，格式尚未定型。全唐五代以《江城子》词约十六首，由七位词人所作，以端己最长，当为最早依调填词者。五代时，欧阳炯单调词添一衬字变尾二句为七言句，开宋词「衬字法」。牛松卿单调词添二字于第二句，开宋词「添字法」。尹参卿单调词摊破首句为两三言句，开宋词「减字法」、「摊破法」。北宋初，是调作者甚少，晏同叔、柳耆卿、欧阳文忠诸大家均无《江城子》传世，唯张子野有两首《江城子》。至东坡始变双调，由是词格渐定。薛瑞生《东坡词编年笺證》中考东坡首用是调约于熙宁年间，《江神子·湖上与张先同赋，时闻弹筝》与《江神子·孤山竹阁送述古》即东坡初创之作，仍承唐五代词柔婉细腻之风。元丰间，《江神子·乙卯正月二十日夜记梦》和《江神子·密州出猎》开一代词风，引时人乃至後代追和。是调衰于金元，近三分之一为道士所作，内容多涉道教。《钦定词谱》：「晁无咎改名《江神子》，韩涧泉词有『腊後春前邨意远』句，更名《邨意远》。」严建文《词牌释例》：「《江城子》，又名《江神子》、《邨意远》、《水晶帘》，……清李符曾《词家辨證》云：『南唐人张泌有《江城子》二阕，五代欧阳炯用此调填词有『如西子镜，照江城』句，含本意……」《唐圭璋推荐唐宋词》注：「《江城子》调应由咏江城事而得名。『子』为曲名後缀。本篇用原始题意咏扬子江畔古城金陵。」可知调因欧词「如西子镜，照江城」句得名。欧词虽非现存《江城子》首作，然咏江城金陵事而归本意。有单调四体，分三十五字、三十六字、三十七字三种；双调一体，七十字，上下阕各七句，五平韵。格律多为平韵格，双调体偶有填仄韵者。
「密州出猎」：明吴讷钞本、《苏长公二妙集》本、毛本作「猎词」。《东坡外集》作「徐州行猎」。
密州：龙榆生笺引《钦定大清一统志·卷一百三十四·〈青州府·诸城县〉》：「诸城县，在府东南二百八十里，东西距九十里，南北距一百八十里。东至莱州府胶州界四十里，西至沂州府莒州界五十里，南至沂州府日照县界一百二十里，北至安邱县界六十里，东南至海一百五十里，西南至日照县界七十里，东北至莱州府高密县界五十里，西北至安邱县界九十里。本春秋时，鲁诸邑及齐琅邪邑地。秦置琅邪郡。汉初置东武县，为郡治并领琅邪诸县，後汉改置琅邪国，于开阳以东武等三县为属。三国魏因之。晋初省琅邪县，以东武诸县属城阳郡，太康十年属东莞郡。宋以东武县分属平昌郡。後魏永安二年，置东武郡兼置胶州。北齐改置高密郡，仍置胶州省诸县入之。隋开皇初，郡废，五年改州曰密州，十八年改东武县曰诸城，大业初州废为高密郡。唐武德五年，复曰密州。天宝元年，复曰高密郡。乾元元年，复曰密州，属河南道。宋曰密州高密郡，开宝五年升安化军节度，属京东东路。金曰密州，属山东东路。明洪武元年，始废密州以县，属青州府。本朝因之。按青州府属旧有安东卫，一本从沂州府日照县分置日照，旧隶青州後为沂属而安东未经改归。本朝乾隆七年裁卫，以所辖村庄归入诸城、日照二县，但计其道里，究与日照为近，应将安东废卫列入沂州，附识于此。」
牵黄、擎苍：傅子立注：「《南史》：『张充少好逸游。张绪尝告归至吴，始入西郭，时充方出猎，左臂鹰，右牵狗。遇绪船至，便放绁脱韝（gōu），拜于水次。』『黄』，黄狗也；『苍』，苍鹰也。」刘尚荣按：「详见《南史·卷三十一·〈张裕传·（孙）张充传〉》。《南史》原文作『右臂鹰，左牵狗』。《梁书·卷二十一·张充传》文字稍异，作『左手臂鹰，右手牵狗。』」龙榆生笺引《梁书·卷二十一·张充传》：「张充字延符，吴郡人。父绪，齐特进、金紫光禄大夫，有名前代。充少时，不持操行，好逸游。绪尝请假还吴，始入西郭，值充出猎，左手臂鹰，右手牵狗，遇绪船至，便放绁脱韝，拜于水次。绪曰：『一身两役，无乃劳乎？』充跪对曰：『充闻三十而立，今二十九矣，请至来岁而敬易之。』绪曰：『过而能改，颜氏子有焉。』」
锦帽貂裘：傅子立注：「『锦帽』，锦蒙帽也；『貂裘』，貂鼠裘也。李太白：『绣衣貂裘明积雪。』古者诸侯千乘，今太守，古诸侯也，故出拥千骑。」刘尚荣按：「李句出《送程刘二侍郎兼独孤判官赴安西幕府》。」
倾城：龙榆生笺引《汉书·卷九十七上·〈外戚列传·孝武李夫人传〉》：「孝武李夫人，本以倡进。初，夫人兄延年性知音，善歌舞，武帝爱之。每为新声变曲，闻者莫不感动。延年侍上，起舞，歌曰：『北方有佳人，绝世而独立，一顾倾人城，再顾倾人国。宁不知倾城与倾国，佳人难再得！』上叹息曰：『善！世岂有此人乎？』平阳主因言延年有女弟，上乃召见之，实妙丽善舞。由是得幸，生一男，是为昌邑哀王。」
随太守：明吴讷钞本作「贤太守」。
孙郎：傅子立注：「《吴志》：『孙仲谋尝亲乘马，射虎于庱（Chěng）亭。马为虎所伤，仲谋投以双戟，虎却废。常从张世击以戈，获之。』按《吴志》，『庱』，摅陵反。」刘尚荣按：「见《三国志·卷四十七·〈吴书·吴主传〉》裴世期注。」龙榆生笺引《三国志·卷四十七·〈吴书·吴主传〉》：「（建安）二十三年十月，权将如吴，亲乘马射虎于庱亭。马为虎所伤，权投以双戟，虎却废。常从张世击以戈，获之。」
鬓微霜：傅子立注：「王黄州《老将》诗：『归来两鬓霜。』」刘尚荣按：「王黄州《小畜集·卷十·送史馆学士杨亿闽中迎侍》：『莫笑蹉跎两鬓霜。』晁无咎《鸡肋集·卷十·赵开祖挽歌辞》：『万里归来两鬓霜。』傅子立似将两人诗讹混。无王黄州《老将》诗。」
冯唐：傅子立注：「汉冯唐，文帝时老为郎。後因言云中太守魏尚事，悟帝，帝悦，遣唐持节云中，赦尚，而拜唐为车骑都尉。」刘尚荣按：「事见《汉书·卷五十·冯唐传》。」龙榆生笺引《汉书·卷五十·冯唐传》：「冯唐，祖父赵人也。父徙代。汉兴徙安陵。唐以孝著，为郎中署长，事文帝。帝辇过，问唐曰：『父老何自为郎？家安在？』具以实言。文帝曰：『吾居代时，吾尚食监高祛数为我言赵将李齐之贤，战于钜鹿下。吾每饮食，意未尝不在钜鹿也。父老知之乎？』唐对曰：『齐尚不如廉颇、李牧之为将也。』上曰：『何已？』唐曰：『臣大父在赵时，为官帅将，善李牧。臣父故为代相，善李齐，知其为人也。』上既闻廉颇、李牧为人，良说，乃拊髀曰：『嗟乎！吾独不得廉颇、李牧为将，岂忧匈奴哉！』唐曰：『主臣！陛下虽有廉颇、李牧，不能用也。』」上怒，起入禁中。良久，召唐让曰：『公众辱我，独亡间处虖？』唐谢曰：『鄙人不知忌讳。』当是时，匈奴新大入朝那，杀北地都尉卬。上以胡寇为意，乃卒复问唐曰：『公何以言吾不能用颇、牧也？』唐对曰：『臣闻上古王者遣将也，跪而推毂，曰：「闑以内寡人制之，闑以外将军制之；军功爵赏，皆决于外，归而奏之。」此非空言也。臣大父言李牧之为赵将居边，军市之租皆自用飨士，赏赐决于外，不从中覆也。委任而责成功，故李牧乃得尽其知能，选车千三百乘，彀骑万三千匹，百金之士十万，是以北逐单于，破东胡，灭澹林，西抑彊秦，南支韩、魏。当是时，赵几伯。後会赵王迁立，其母倡也，用郭开谗，而诛李牧，令颜聚代之。是以为秦所灭。今臣窃闻魏尚为云中守，军市租尽以给士卒，出私养钱，五日壹杀牛，以飨宾客军吏舍人，是以匈奴远避，不近云中之塞。虏尝一入，尚帅车骑击之，所杀甚众。夫士卒尽家人子，起田中从军，安知尺籍伍符？终日力战，斩首捕虏，上功莫府，一言不相应，文吏以法绳之。其赏不行，吏奉法必用。愚以为陛下法太明，赏太轻，罚太重。且云中守尚坐上功首虏差六级，陛下下之吏，削其爵，罚作之。繇此言之，陛下虽得李牧，不能用也。臣诚愚，触忌讳，死罪！』文帝说。是日，令唐持节赦魏尚，复以为云中守，而拜唐为车骑都尉，主中尉及郡国车士。十年，景帝立，以唐为楚相。武帝即位，求贤良，举唐。唐时年九十馀，不能为官，乃以子遂为郎。遂字王孙，亦奇士。魏尚，槐里人也。」
「会挽雕弓如满月，西北望，射天狼」：以上三句凡十三字，傅注本残佚，今据元延祐本补。
天狼：龙榆生笺：「《楚辞·九歌·东君》：『举长矢兮射天狼。』王叔师注：『天狼，星名，以喻贪残。』《晋书·天文志》：『狼一星在东井南，为野将，主侵掠。』」词中以之隐喻犯宋边之西夏。', '我姑且抒发一下少年人的狂傲之气，左手牵着黄狗，右手托着苍鹰。随从的将士们头戴华美艳丽的帽子，身穿貂皮做的衣服，浩浩荡荡的大部队像疾风一样，席卷平坦的山冈。为报答全城的百姓都来追随我，我一定要像孙权一样射杀一头老虎给大家看看。
喝酒喝到正高兴时，我的胸怀更加开阔，我的胆气更加张扬。即使头髮微白，又有什么关系呢？朝廷什么时候才能派人拿着符节来密州赦免我的罪呢？那时我定当拉开弓箭，使之呈现满月的形状，瞄准西北，把代表西夏的天狼星射下来。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b32cee9a0c24ec7c8c", "shortContent": "苏东坡是北宋词坛的大革新家，他作词时，正当柳永词风靡一世之际。他有志于改变《花间》以来柔媚的词风，就以柳永为对手。宋神宗熙宁八年，东坡任密州知州，曾因旱去常山祈雨，归途中与同官梅户曹会猎于铁沟，写了一首出猎词。他致书鲜于子骏说：“近却颇作小词，虽无柳七郎风味，亦自是一家，呵呵。数日前猎于郊外，所获颇多。作得一阕，令东州壮士抵掌顿足而歌之，吹笛击鼓以为节，颇壮观也。”他树起了“自是一家”的旗帜，并对...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ba03048e64fbd9bd30", "shortContent": "苏东坡是北宋词坛的大革新家，他作词时，正当柳永词风靡一世之际。他有志于改变花间以来柔媚的词风，就以柳永为对手。宋神宗熙宁八年，东坡任密州知州，曾因旱去常山祈雨，归途中与同官梅户曹会猎于铁沟，写了一首出猎词。他致书鲜于子骏说：“近却颇作小词，虽无柳七郎风味，亦自是一家，呵呵。数日前猎于郊外，所获颇多。作得一阕，令东州壮士抵掌顿足而歌之，吹笛击鼓以为节，颇壮观也。”他树起了“自是一家”的旗帜，并对于自...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253f534825dee9fd6e8", "shortContent": "苏东坡是北宋词坛的大革新家，他作词时，正当柳永词风靡一世之际。他有志于改变花间以来柔媚的词风，就以柳永为对手。宋神宗熙宁八年，东坡任密州知州，曾因旱去常山祈雨，归途中与同官梅户曹会猎于铁沟，写了一首出猎词。他致书鲜于子骏说：“近却颇作小词，虽无柳七郎风味，亦自是一家，呵呵。数日前猎于郊外，所获颇多。作得一阕，令东州壮士抵掌顿足而歌之，吹笛击鼓以为节，颇壮观也。”他树起了“自是一家”的旗帜，并对于自...", "authors": ["高　原"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e79f2af4e09d55b6524", "shortContent": "《苏轼文集》卷五十三《与鲜于子骏》：“近却颇作小词，虽无柳七风味，亦自是一家。呵呵。数日前，猎于郊外，所获颇多。作得一阕，令东州壮士抵掌顿足而歌之，吹笛击鼓以为节，颇壮观也。写呈取笑。”傅藻《东坡纪年录》：“熙宁八年乙卯（1075）冬，祭常山回，与同官习射放鹰，作诗《和梅户曹会猎铁沟行》，又作《江神子》。”", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646838ea30675327e1979888", "shortContent": "苏东坡是北宋词坛的大革新家，他作词时，正当柳永词风靡一世之际。他有志于改变《花间》以来柔媚的词风，就以柳永为对手。宋神宗熙宁八年，东坡任密州知州，曾因旱去常山祈雨，归途中与同官梅户曹会猎于铁沟，写了一首出猎词。他致书鲜于子骏说：“近却颇作小词，虽无柳七郎风味，亦自是一家，呵呵。数日前猎于郊外，所获颇多。作得一阕，令东州壮士抵掌顿足而歌之，吹笛击鼓以为节，颇壮观也。”他树起了“自是一家”的旗帜，并对...", "authors": ["高原"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471ff72b5420e27678fa152", "shortContent": "出猎，对于东坡这样的文人来说，或许是偶然的一时豪兴，所以开篇便日：“老夫聊发少年狂。”狂者，豪情也。这首词通篇纵情放笔，气概豪迈，一个“狂”字贯穿全篇。看，今日词人左手牵黄犬，右臂驾苍鹰，好一副出猎的雄姿！随从武士个个也是“锦帽貂裘”，打猎装束。“千骑卷平冈”，千骑奔驰，腾空越野，好一幅壮观的出猎场面！“为报倾城随太守，亲射虎，看孙郎”，更是显出东坡“狂”劲儿来了。“太守”，东坡也。他说：快告诉全...", "authors": ["弓劲射的英雄形象，英武豪迈，气概非凡。"], "pressName": "上海辞书出版社"}]', '', 'indent', 1359630393, '57b8eab8d342d3005ac6a80c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10019, '项脊轩志', NULL, 416, 137, 2, 12, '归有光', NULL, 10004, '57b940198ac2470062e1af28', '明', 'wen', '文', 'http://baike.baidu.com/view/67687.htm', '', '项脊轩，旧南阁子也。室仅方丈，可容一人居。百年老屋，尘泥渗漉，雨泽下注；每移案，顾视无可置者。又北向，不能得日，日过午已昏。余稍为修葺，使不上漏。前辟四窗，垣墙周庭，以当南日，日影反照，室始洞然。又杂植兰桂竹木于庭，旧时栏楯，亦遂增胜。借书满架，偃仰啸歌，冥然兀坐，万籁有声；而庭阶寂寂，小鸟时来啄食，人至不去。三五之夜，明月半墙，桂影斑驳，风移影动，珊珊可爱。
然余居于此，多可喜，亦多可悲。先是，庭中通南北为一。迨诸父异爨，内外多置小门墙，往往而是，东犬西吠，客逾庖而宴，鸡栖于厅。庭中始为篱，已为墙，凡再变矣。家有老妪，尝居于此。妪，先大母婢也，乳二世，先妣抚之甚厚。室西连于中闺，先妣尝一至。妪每谓余曰：「某所，而母立于兹。」妪又曰：「汝姊在吾怀，呱呱而泣；娘以指叩门扉曰：‘儿寒乎？欲食乎？’吾从板外相为应答。」语未毕，余泣，妪亦泣。余自束发读书轩中，一日，大母过余曰：「吾儿，久不见若影，何竟日默默在此，大类女郎也？」比去，以手阖门，自语曰：「吾家读书久不效，儿之成，则可待乎！」顷之，持一象笏至，曰：「此吾祖太常公宣德间执此以朝，他日汝当用之！」瞻顾遗迹，如在昨日，令人长号不自禁。
轩东故尝为厨，人往，从轩前过。余扃牖而居，久之，能以足音辨人。轩凡四遭火，得不焚，殆有神护者。
（项脊生曰：「蜀清守丹穴，利甲天下，其后秦皇帝筑女怀清台；刘玄德与曹操争天下，诸葛孔明起陇中。方二人之昧昧于一隅也，世何足以知之，余区区处败屋中，方扬眉、瞬目，谓有奇景。人知之者，其谓与坎井之蛙何异？」）
余既为此志，后五年，吾妻来归，时至轩中，从余问古事，或凭几学书。吾妻归宁，述诸小妹语曰：「闻姊家有阁子，且何谓阁子也？」其后六年，吾妻死，室坏不修。其后二年，余久卧病无聊，乃使人复葺南阁子，其制稍异于前。然自后余多在外，不常居。
庭有枇杷树，吾妻死之年所手植也，今已亭亭如盖矣。', '本文是一篇借记物以叙事、抒情的散文。文章通过记作者青年时代的书斋，着重叙述与项脊轩有关的人事变迁，借「百年老屋」的几经兴废，回忆家庭琐事，抒發了物在人亡、三世变迁的感慨。文章紧扣项脊轩来写，又用或喜或悲的感情作为贯穿全文的意脉，将生活琐碎事串为一个整体。撷取生活中的细节和场面来表现人物，不言情而情无限，言有尽而意无穷。', '项脊轩：归有光家的一间小屋。轩，小的房室。
旧：旧日的，原来的。
方丈：一丈见方。
尘泥渗漉（shènlù）：（屋顶墙头上的）泥土漏下。渗，透过；漉，漏下；渗漉，从小孔慢慢漏下。
雨泽下注：雨水往下倾泻。下，往下；雨泽，雨水。
案：几案，桌子。
顾视：环看四周。顾，环视也。（许慎《说文解字》）
不能得日：得日，照到阳光。
日过午已昏：昏，光线不明。
为（wéi）修葺（qì）：稍稍修理了一下。修葺，修缮、修理，修补。
辟：开。
垣墙周庭：庭院四周砌上围墙。垣，在这里名词作动词，指砌矮墙；垣墙，砌上围墙；周庭，（于）庭子周围。
当：挡住
洞然：明亮的样子。
栏楯（shǔn）：栏杆。纵的叫栏，横的叫楯。
增胜：增添了光彩。胜，美景。
偃仰：偃，伏下。仰，仰起；偃仰，安居。
啸歌：长啸或吟唱。这里指吟咏诗文，显示豪放自若。啸，口里發出长而清越的声音。
冥然兀坐：静静地独自端坐着。兀坐，端坐。
万籁有声：自然界的一切声音都能听到。万籁，指自然界的一切声响；籁，孔穴里發出的声音，也指一般的声响。
三五之夜：农历每月十五的夜晚。
珊珊：树影摇动的样子。
迨（dài）诸父异爨（cuàn）：等到伯、叔们分了家。迨，及，等到；诸父，伯父、叔父的统称；异爨，分灶做饭，意思是分了家。
往往：指到处，处处。
而：修饰关系连词。
是：这（样）。
东犬西吠：东边的狗对着西边叫。意思是分家后，狗把原住同一庭院的人当作陌生人。
逾庖（yúpáo）而宴：越过厨房而去吃饭。庖，厨房
已：已而，随后不久。
凡再变矣：凡，总共；再，两次。
而母立于兹：“而”通“尔”
相为应答：一一回答。相，偏义復词，指她（先母）。
束发：古代男孩成年时束发为髻，十五岁前指儿童时代。
竟日：一天到晚。竟，从头到尾。
阖（hé）：通「合」，合上。
瞻顾遗迹：回忆旧日事物。瞻，向前看；顾，向后看；瞻顾，泛指看，有瞻仰、回忆的意思。
扃牖（jiōngyǒu）：关着窗户。扃，（从内）关闭；牖，窗户。
殆：恐怕，大概，表示揣测的语气。
来归：嫁到我家来。归，古代女子出嫁。
凭几学书：伏在几案上学写字。几，小或矮的桌子；书，写字。
归宁：出嫁的女儿回娘家省亲。
制：指建造的格式和样子。
手植：亲手种植。手，亲手。
亭亭如盖：高高挺立，树冠像伞盖一样。亭亭，直立的样子；盖，古称伞。', '项脊轩，是过去的南阁楼。屋里只有一丈见方，可以容纳一个人居住。这座百年老屋，（屋顶墙上的）泥土从上边漏下来，积聚的流水一直往下流淌；我每次动书桌，环视四周没有可以安置桌案的地方。屋子又朝北，不能被阳光照到，白天过了中午（屋内）就已昏暗。我稍稍修理了一下，使它不从上面漏土漏雨。在前面开了四扇窗子，在院子四周砌上围墙，用来挡住南面射来的日光，日光反射照耀，室内才明亮起来。我在庭院里随意地种上兰花、桂树、竹子等草木，往日的栏杆，也增加了新的光彩。家中的书摆满了书架，我仰头高声吟诵诗歌，有时又静静地独自端坐，自然界的万物皆有声音；庭院、台阶前静悄悄的，小鸟不时飞下来啄食，人走到它跟前也不离开。农历十五的夜晚，明月高悬，照亮半截墙壁，桂树的影子交杂错落，微风吹过影子摇动，可爱极了。
然而我住在这里，有许多值得高兴的事，也有许多值得悲伤的事。在这以前，庭院南北相通成为一体。等到伯父叔父们分了家，在室内外设置了许多小门，墙壁到处都是。分家后，狗把原住同一庭院的人当作陌生人，客人得越过厨房去吃饭，鸡在厅堂里栖息。庭院中开始是篱笆隔开，然后又砌成了墙，一共变了两次。家中有个老婆婆，曾经在这里居住过。这个老婆婆，是我死去的祖母的婢女，给两代人喂过奶，先母对她很好。房子的西边和内室相连，先母曾经常来。老婆婆常常对我说：「这个地方，你母亲曾经站在这儿。」老婆婆又说：「你姐姐在我怀中，呱呱地哭泣；你母亲用手指敲着房门说：‘孩子是冷呢，还是想吃东西呢？’我隔着门一一回答……」话还没有说完，我就哭起来，老婆婆也流下了眼泪。我从十五岁起就在轩内读书，有一天，祖母来看我，说：「我的孩子，好久没有见到你的身影了，为什么整天默默地呆在这里，真像个女孩子呀？」等到离开时，用手关上门，自言自语地说：「我们家读书人很久没有得到功名了，（我）孩子的成功，就指日可待了啊！」不一会，拿着一个象笏过来，说：「这是我祖父太常公宣德年间拿着去朝见皇帝用的，以后你一定会用到它！」瞻仰回顾旧日遗物，就像在昨天一样，真让人忍不住放声大哭。
项脊轩的东边曾经是厨房，人们到那里去，必须从轩前经过。我关着窗子住在里面，时间长了，能够根据脚步声辨别是谁。项脊轩一共遭过四次火灾，能够不被焚毁，大概是有神灵在保护着吧。
项脊生说：巴蜀地方有个名叫清的寡妇，她继承了丈夫留下的朱砂矿，采矿获利为天下第一，后来秦始皇筑「女怀清台」纪念她。刘备与曹操争夺天下，诸葛亮出身陇中由务农出而建立勋业。当这两个人还待在不为人所知的偏僻角落时，世人又怎么能知道他们呢？我今天居住在这破旧的小屋里，却自得其乐，以为有奇景异致。如果有知道我这种境遇的人，恐怕会把我看作目光短浅的井底之蛙吧！
我作了这篇文章之后，过了五年，我的妻子嫁到我家来，她时常来到轩中，向我问一些旧时的事情，有时伏在桌旁学写字。我妻子回娘家探亲，回来转述她的小妹妹们的话说：「听说姐姐家有个小阁楼，那么，什么叫小阁楼呢？」这以后六年，我的妻子去世，项脊轩破败没有整修。又过了两年，我很长时间生病卧床没有什么（精神上的）寄托，就派人再次修缮南阁子，格局跟过去稍有不同。然而这之后我多在外边，不常住在这里。
庭院中有一株枇杷树，是我妻子去世那年我亲手种植的，如今已经高高挺立着，枝叶繁茂像伞一样了。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed2042cee9a0c24edaeae", "shortContent": "以斋室为描写对象，展开叙事抒情，前已有刘禹锡《陋室铭》。《陋室铭》用韵文形式，主要抒发个人情志，体格短小。归有光的《项脊轩志》虽也有近似的感想（“项脊轩”在某种意义上说也是“陋室”），但作者却用散文形式，多叙家常，故别具风味。作者因远祖归道隆住在太仓（今属江苏）的项脊泾，遂将自己的书斋命名为“项脊轩”。《项脊轩志》这篇文章，是分两次写成的。前三段写于十九岁时，是本文；“余既为此志”以下一段则是十馀...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8f0f8fda556506e481", "shortContent": "许宣平是神仙，在后世颇有知名度，这正是受沈汾《续仙传》中这篇传记的影响。然而传中明明说他“隐于城阳山南坞”，可见他实在是一位隐士。他的异迹，不过是“但见不食，颜色若四十许人，行如奔马”，以及留下数首“仙诗”而已。百余年后他再次亮相，但那是老妪“归家言之”的独家新闻。从行文来看，这位老妪事实上成了后半部的主角，很像是两段独立故事的缀合。\n唐睿宗的登基，是在武氏余党毒杀中宗，随即李氏势力又政变废黜少帝...", "authors": ["穆", "俦"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "64717c16b5420e27678d1687", "shortContent": "以斋室为描写对象，展开叙事抒情，前已有刘禹锡《陋室铭》。《陋室铭》用韵文形式，主要抒发个人情志，体格短小。归有光的《项脊轩志》虽也有近似的感想（“项脊轩”在某种意义上说也是“陋室”），但作者却用散文形式，多叙家常，故别具风味。作者因远祖归道隆住在太仓（今属江苏）的项脊泾，遂将自己的书斋命名为“项脊轩”。《项脊轩志》这篇文章，是分两次写成的。前两段写于十九岁时，是本文；“余既为此志”以下一段则是十余...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '', 'indent', 1359647893, '57b91bcf8ac2470062e076a0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10020, '问刘十九', NULL, 1671, 2952, 2, 5, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', 'http://baike.baidu.com/view/33443.htm', '', '绿蚁新醅酒，红泥小火炉。
晚来天欲雪，能饮一杯无？', '此诗描写诗人在一个风雪飘飞的傍晚邀请朋友前来喝酒、共叙衷肠的情景。以家常的语气，朴素亲切的语言，体现了朋友间真诚亲密的感情。全诗简练含蓄，轻松洒脱，而诗句之间意脉相通，一气贯之。', '刘十九：白居易留下的诗作中，提到刘十九的不多，仅两首。但提到刘二十八、二十八使君的，就很多了。刘二十八就是刘禹锡。刘十九乃其堂兄刘禹铜，係洛阳一富商，与白居易常有应酬。
绿蚁：指浮在新酿的没有过滤的米酒上的绿色泡沫。
醅（pēi）：酿造。
绿蚁新醅酒：酒是新酿的酒。新酿酒未滤清时，酒面浮起酒渣，色微绿，细如蚁，称为「绿蚁」。
雪：下雪，这里作动词用。
无：表示疑问的语气词，相当于「么」或「吗」。', '酿好了淡绿的米酒，烧旺了小小的火炉。
天色将晚雪意渐浓，能否一顾寒舍共饮一杯酒？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c90ce818559d05881d", "shortContent": "这首诗可以说是邀请朋友前来小饮的劝酒词。给友人备下的酒，当然是可以使对方致醉的，但这首诗本身却是比酒还要醇浓。\n“绿蚁新醅酒，红泥小火炉。”酒是新酿的酒（未滤清时，酒面浮起酒渣，色微绿，细如蚁，称为“绿蚁”），炉火又正烧得通红。这新酒红火，大约已经摆在席上了，泥炉既小巧又朴素；嫣红的火，映着浮动泡沫的绿酒，是那样地诱人，那样地叫人口馋，正宜于跟一二挚友小饮一场。\n酒，是如此吸引人。但备下这酒与炉火...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad4797a92d5e4fd904", "shortContent": "这首诗可以说是邀请朋友前来小饮的劝酒词。给友人备下的酒，当然是可以使对方致醉的，但这首诗本身却是比酒还要醇浓。\n\n“绿蚁新醅酒，红泥小火炉。”酒是新酿的酒（未滤清时，酒面浮起酒渣，色微绿，细如蚁，称为“绿蚁”），炉火又正烧得通红。这新酒红火，大约已经摆在席上了，泥炉既小巧又朴素；嫣红的火，映着浮动泡沫的绿酒，是那样地诱人，那样地叫人口馋，正宜于跟一二挚友小饮一场。\n\n酒，是如此吸引人。但备下这酒与...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e9039f", "shortContent": "这首小诗无疑是邀友人前来小饮的劝酒词。所谓酒不醉人人自醉，在未饮酒之先，这首小诗已足让人感到八九分醉意了。这首醇浓的诗作，以其诱人的酒色、感人的氛围、动人的情感，营构了醉人的诗味，让读者飞腾想象的翅膀，反复回味这酒与情的真醇！\n\n先是酒色诱人。劝人饮酒，先以酒色打动人，看，“绿蚁新醅酒”。新酿的酒，在尚未滤清时，酒面浮起一层薄薄的酒渣，其色微绿，细如蚁，故称“绿蚁”。还没来得及滤清新酒，即迫不及待...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645d09bbec56251f2eeb5b78", "bookTitle": "白居易诗文鉴赏辞典", "articleId": "6462d5e17da2f75ac7df8c14", "shortContent": "这首诗可以说是邀请朋友前来小饮的劝酒词。给友人备下的酒，当然是可以使对方致醉的，但这首诗本身却是比酒还要醇浓。\n\n“绿蚁新醅酒，红泥小火炉。”酒是新酿的酒（未滤清时，酒面浮起酒渣，色微绿，细如蚁，称为“绿蚁”），炉火又正烧得通红。这新酒红火，大约已经摆在席上了，泥炉既小巧又朴素；嫣红的火，映着浮动泡沫的绿酒，是那样地诱人，那样地叫人口馋，正宜于跟一二挚友小饮一场。\n\n酒，是如此吸引人。但备下这酒与...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}]', '《唐诗快》：岂非天下第一快活人。
《精选评注五朝诗学津梁》：气盛言直，所谓白诗「妇孺都解」也。
《唐诗三百首》：信手拈来，都成妙谛，诗家三昧，如是如是。
《唐诗评注读本》：用土语不见俗，乃是点铁成金手段。
《诗境浅说续编》：寻常之事，人人意中所有，而笔不能达者，得生花江管写之，便成绝唱，此等诗是也。末句之「无」字，妙作问语，千载下如闻声口也。
《唐人绝句精华》：读此二诗（按指本诗与《招东邻》），知白居易之好客，有酒则呼友同饮。', 'center', 1359648126, '57b916330a2b58005c92f138', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10021, '道德经（第十二章）', NULL, 407, 81, 1, 1, '老子', NULL, 10006, '57b9028d5bbb50005b783385', '周', 'wen', '文', 'http://baike.baidu.com/view/16516.htm', '', '五色令人目盲；五音令人耳聋；五味令人口爽；驰骋畋猎，令人心发狂；难得之货，令人行妨。是以圣人为腹不为目，故去彼取此。', '老子生活的时代，正处于新旧制度相交替、社会动荡不安之际，奴隶主贵族生活日趋腐朽糜烂。他目击了上层社会的生活状况，因而他认为社会的正常生活应当是为「腹」不为「目」，务内而不逐外，但求安饱，不求纵情声色之娱。在此，老子所反对的是奴隶主贵族的腐朽生活方式，并不是普通劳动民众的，因为「五色」、「五味」、「五声」、打猎游戏、珍贵物品并不是一般劳动者可以拥有的，而是贵族生活的组成部分。因此，我们认为老子的观点并不是要把精神文明与物质文明对立起来，并不是否定发展文化，不像有些学者所言，认为老子的这些观点是他对人类社会现实和历史发展所持的狭隘庸俗的反历史观点。他希望人们能够丰衣足食，建立内在宁静恬淡的生活方式，而不是外在贪俗的生活。一个人越是投入外在化的漩涡里，则越会流连忘返，产生自我疏离感，而心灵则会日益空虚。所以，老子才提醒人们要摒弃外界物欲的诱惑，保持内心的安足清静，确保固有的天性。', '五色：指青、黄、赤、白、黑。此指色彩多样。
目盲：比喻眼花缭乱。
五音：指宫、商、角、徵、羽。这里指多种多样的音乐声。
耳聋：比喻听觉不灵敏，分不清五音。
五味：指酸、苦、甘、辛、鹹，这里指多种多样的美味。
口爽：意思是味觉失灵，生了口病。古代以「爽」为口病的专用名词。
驰骋：纵横奔走，比喻纵情放荡。
畋（tián）猎：打猎获取动物。畋，打猎的意思。
心发狂：心旌放荡而不可制止。
行妨：伤害操行。妨，妨害、伤害。
为腹不为目：只求温饱安宁，而不为纵情声色之娱。「腹」在这里代表一种简朴宁静的生活方式；「目」代表一种巧伪多欲的生活方式。
去彼取此：摒弃物欲的诱惑，而保持安定知足的生活。「彼」指「为目」的生活；「此」指「为腹」的生活。', '缤纷的色彩，使人眼花缭乱；嘈杂的音调，使人听觉失灵；豐盛的食物，使人舌不知味；纵情狩猎，使人心情放荡发狂；稀有的物品，使人行为不轨。因此，圣人但求吃饱肚子而不追逐声色之娱，所以摒弃物欲的诱惑而保持安定知足的生活方式。', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70030a1d3054c75735f", "shortContent": "“五色令人目盲”这句话出自《老子·十二章》，它的意思是说：缤纷缭乱的颜色使人丧失分辨色彩的能力，如同盲人一般。一般讲来，这个大千世界就是色彩斑斓、绚丽多姿的，如果人们的眼睛功能正常，那么就应该可以分辨出各种颜色，也就应该能欣赏这个世界的各种美景。但是，为什么老子会说人会因色彩的缤纷而“目盲”呢？在这里，我们似乎可以从两个角度来解读这句话。\n\n首先，我们可以从“五色”二字说起。“五色”，原指青、黄、...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fbe43cd12b001c6d1f33c", "bookTitle": "老子鉴赏辞典", "articleId": "646ccc0d30675327e1abf9fb", "shortContent": "本章老子继续阐发治身修性去奢无欲之道，故此章又被河上公题为“检欲章”。老子提醒人们对于声色货利乃至口腹之欲，要加以节制，不可纵情任性、流逸奔竞而导致目盲、耳聋、口爽、心狂这些后果发生。所以道家治身修性强调的是“为腹不为目”，去奢泰、存俭朴。\n老子之“检欲”，由《十章》提倡检束自我“营魄抱一，能无离乎”，具体到本章提倡检束自我感官游离身外，追逐流逸淫佚否。为什么如此反复强调检束自我（心灵乃至感官）？...", "authors": ["刘康德"], "pressName": "上海辞书出版社"}, {"bookId": "645fbe43cd12b001c6d1f33c", "bookTitle": "老子鉴赏辞典", "articleId": "646dfc8282772d459417e628", "shortContent": "“五色令人目盲”这句话出自《十二章》，它的意思是说：缤纷缭乱的颜色使人丧失分辨色彩的能力，如同盲人一般。一般讲来，这个大千世界就是色彩斑斓、绚丽多姿的，如果人们的眼睛功能正常，那么就应该可以分辨出各种颜色，也就应该能欣赏这个世界的各种美景。但是，为什么老子会说人会因色彩的缤纷而“目盲”呢？在这里，我们似乎可以从两个角度来解读这句话。\n首先，我们可以从“五色”二字说起。“五色”，原指青、黄、赤、白、...", "authors": ["张锦波"], "pressName": "上海辞书出版社"}]', '', 'indent', 1359648445, '57b90a02c4c97100558f6c32', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10406, '飞来洞避暑', NULL, 4, 253, 0, 1, '高濂', NULL, 10013, '57ba82a88ac2470063045693', '明', 'wen', '文', 'http://baike.baidu.com/view/126452.htm', '', '灵鹫山下，岩洞玲珑，周回虚敞，指为西域飞来一小岩也。气凉石冷，入径凛然。洞中陡处，高空若堂，窄处方斗若室，俱可人行无碍顶处。三伏熏人，燎肌燔骨，坐此披襟散发，把酒放歌，俾川呜谷应，清冷洒然，不知人世今为何月。顾我絺綌，不胜秋尽矣。初入体凉，再入心凉，深入毛骨俱凉哉。人间抱暑焦烁，虽啖冰雪不解，而严冬犹然者，勿令知此清凉乐国。', '', NULL, NULL, NULL, NULL, 'indent', 1468668989, '57bc2fcba633bd005d40caff', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10022, '陶庵梦忆 · 卷三 · 湖心亭看雪', NULL, 583, 227, 1, 13, '张岱', NULL, 10007, '57ba82be165abd0066234de7', '明', 'wen', '文', 'http://baike.baidu.com/view/403502.htm', '', '崇祯五年十二月，余住西湖。大雪三日，湖中人鸟声俱绝。是日更定矣，余拏一小舟，拥毳衣炉火，独往湖心亭看雪。雾凇沆砀，天与云与山与水，上下一白。湖上影子，惟长堤一痕，湖心亭一点，与余舟一芥，舟中人两三粒而已。
到亭上，有两人铺毡对坐，一童子烧酒，炉正沸。见余，大喜曰：“湖中焉得更有此人！”拉余同饮。余强饮三大白而别。问其姓氏，是金陵人，客此。及下船，舟子喃喃曰：“莫说相公痴，更有痴似相公者！”', '此文选自《陶庵梦忆》，是明末清初文学家张陶菴代表作。作者出身官僚家庭，但一生未做官。此文以精炼的笔墨，记叙了作者自己在湖心亭看雪的经过，描绘了幽静深远、洁白广阔的雪景图，体现出作者幽远脱俗的闲情雅致。', '崇祯五年：西元一六三二年。
更定：初更以後，晚上八点左右。定，开始。
拥毳（cuì）衣炉火：穿着细毛皮衣，带着火炉。毳衣，细毛皮衣；毳，鸟兽的细毛。
雾凇沆砀：冰花一片弥漫。雾，从天上下罩湖面的云气。凇，从湖面蒸发的水汽。沆砀，白汽弥漫的样子。曾南豐《冬夜即事诗》自注：「齐寒甚，夜气如雾，凝于水上，旦视如雪，日出飘满阶庭，齐人谓之雾凇。
长堤一痕：形容西湖长堤在雪中衹隐隐露出一道痕迹。
一芥：一棵小草。芥，小草，喩轻微纤细的事物。
毡：毛毯。
大惊喜：一作“大喜”。
焉得更有此人：想不到还会有这样的人。焉得，哪能。
拉：邀请。
强（qiǎng）饮：尽情喝。强，尽力、勉力、竭力。一说，高兴地，兴奋地。
大白：大酒杯。白，古人罚酒时用的酒杯，也泛指一般的酒杯，这里的意思是三杯酒。
客此：客，做客，名词作动词。在此地客居。
舟子：船夫。
喃喃：低声嘟哝。
相公：原意是对宰相的尊称，後转为对年轻人的敬称及对士人的尊称。
痴似：痴于，痴过。痴，特有的感受，来展示他钟情山水，淡泊孤寂的独特个性。', '崇祯五年（西元一六三二年）十二月，我住在西湖边。大雪接连下了多天，湖中的行人、飞鸟的声音都消失了。这一天晚上八点左右，我撑着一叶小舟，穿着毛皮衣，带着火炉，独自前往湖心亭看雪。（湖面上）冰花一片弥漫，天和云和山和水，天光湖色全是白皑皑的。湖上的影子，只有一道长堤的痕迹，一点湖心亭的轮廓，和我的一叶小舟，舟中的两三粒人影罢了。
到了湖心亭上，看见有两个人铺好毡子，相对而坐，一个小孩正把酒炉（里的酒）烧得滚沸。（他们）看见我，非常高兴地说：「想不到在湖中还会有您这样的人！」（他们）拉着我一同饮酒。我尽力喝了三大杯酒，然後和他们道别。（我）问他们的姓氏，（得知他们）是南京人，在此地客居。等到了下船的时候，船夫喃喃地说：「不要说相公您痴，还有像相公您一样痴的人啊！」', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed2080f8fda55650615f6", "shortContent": "张岱的小品可谓名副其实的小品，长者不过千把字，短者仅一二百字，笔墨精练，风神绰约，洋溢着诗的意趣。如果拿诗来作比，颇似唐人绝句。它以隽永见长，寥寥几笔，意在言外，有一唱三叹之致，《湖心亭看雪》就是如此。\n开头二句点明时间、地点。张岱文集中凡纪昔年游踪之作，大多标明朝纪年，以示不忘故国。这里标“崇祯五年”，也是如此。“十二月”，正当隆冬多雪之时；“余住西湖”，则点明所居邻西湖。这开头的闲闲二句，却从...", "authors": ["吴战垒"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "64720c2745e4710056fc8339", "shortContent": "张岱的小品可谓名副其实的小品，长者不过千把字，短者仅一二百字，笔墨精练，风神绰约，洋溢着诗的意趣。如果拿诗来作比，颇似唐人绝句。它以隽永见长，寥寥几笔，意在言外，有一唱三叹之致，《湖心亭看雪》就是如此。\n请看作者以何等空灵之笔来写湖中雪景：“雾淞沆砀，天与云与山与水，上下一白，湖上影子，惟长堤一痕、湖心亭一点与余舟一芥、舟中人两三粒而已。”这真是一幅水墨模糊的湖山夜雪图！“雾淞沆砀”是形容湖上雪光...", "authors": ["吴战垒"], "pressName": "上海辞书出版社"}]', '当代文学研究者莫山洪：不拘骈散，融合骈散，这可以说是此文在语言形式上的一大特点。小品文语言极其精炼简洁，体现出个性化的特征，具有了更强的生命力，也才能表现出个人心中最真实的情感。
明末戏曲家祁彪佳在《古今义列传序》：其点染之妙，凡当要害，在余子宜一二百言者，宗子能数十字辄尽情状，乃穷事际，反若有千百言在笔下。', 'indent', 1359648665, '57aeffe96be3ff006ba01791', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10023, '浮生六记· 卷一 · 闺房记乐（节选）', NULL, 99, 5, 2, 0, '沈复', NULL, 10008, '57b9c0a079bc4400639c8182', '清', 'wen', '文', 'http://baike.baidu.com/view/1124865.htm', '', '余幼聘金沙于氏，八龄而夭。娶陈氏。陈名芸，字淑珍，舅氏心余先生女也，生而颖慧，学语时，口授《琵琶行》，即能成诵。四龄失怙，母金氏，弟克昌，家徒壁立。芸既长，娴女红，三口仰其十指供给，克昌从师，修脯无缺。一日，于书簏中得《琵琶行》，挨字而认，始识字。刺绣之暇，渐通吟咏，有“秋侵人影瘦，霜染菊花肥”之句。余年一十三，随母归宁，两小无嫌，得见所作，虽叹其才思隽秀，窃恐其福泽不深，然心注不能释，告母曰：“若为儿择妇，非淑姊不娶。”母亦爱其柔和，即脱金约指缔姻焉。此乾隆乙未七月十六日也。
是中冬，值其堂姊出阁，余又随母往。芸与余同齿而长余十月，自幼姊弟相呼，故仍呼之曰淑姊。时但见满室鲜衣，芸独通体素淡，仅新其鞋而已。见其绣制精巧，询为己作，始知其慧心不仅在笔墨也。其形削肩长项，瘦不露骨，眉弯目秀，顾盼神飞，唯两齿微露；似非佳相。一种缠绵之态，令人之意也消。索观诗稿，有仅一联，或三四句，多未成篇者，询其故，笑曰：“无师之作，愿得知己堪师者敲成之耳。”余戏题其签曰“锦囊佳句”。不知夭寿之机此已伏矣。是夜送亲城外，返已漏三下，腹饥索饵，婢妪以枣脯进，余嫌其甜。芸暗牵余袖，随至其室，见藏有暖粥并小菜焉，余欣然举箸。忽闻芸堂兄玉衡呼曰：“淑妹速来！”芸急闭门曰：“已疲乏，将卧矣。”玉衡挤身而入，见余将吃粥，乃笑睨芸曰：“顷我索粥，汝曰‘尽矣’，乃藏此专待汝婿耶？”芸大窘避去，上下哗笑之。余亦负气，挈老仆先归。自吃粥被嘲，再往，芸即避匿，余知其恐贻人笑也。
至乾隆庚子正月二十二日花烛之夕，见瘦怯身材依然如昔，头巾既揭，相视嫣然。合卺后，并肩夜膳，余暗于案下握其腕，暖尖滑腻，胸中不觉抨抨作跳。让之食，适逢斋期，已数年矣。暗计吃斋之初，正余出痘之期，因笑调曰：“今我光鲜无恙，姊可从此开戒否？”芸笑之以目，点之以首。
廿四日为余姊于归，廿三国忌不能作乐，故廿二之夜即为余婉款嫁。芸出堂陷宴，余在洞房与伴娘对酌，拇战辄北，大醉而卧，醒则芸正晓妆未竟也。是日亲朋络绎，上灯后始作乐。廿四子正，余作新舅送嫁，丑末归来，业已灯残人静，悄然入室，伴妪盹于床下，芸卸妆尚未卧，高烧银烛，低垂粉颈，不知观何书而出神若此，因抚其肩曰：“姊连日辛苦，何犹孜孜不倦耶？”芸忙回首起立曰：“顷正欲卧，开橱得此书，不觉阅之忘倦。《西厢》之名闻之熟矣，今始得见，莫不傀才子之名，但未免形容尖薄耳。”余笑曰：“唯其才子，笔墨方能尖薄。”伴妪在旁促卧，令其闭门先去。遂与比肩调笑，恍同密友重逢。戏探其怀，亦怦怦作跳，因俯其耳曰：“姊何心舂乃尔耶？”芸回眸微笑。便觉一缕情丝摇人魂魄，拥之入帐，不知东方之既白。
芸作新妇，初甚缄默，终日无怒容，与之言，微笑而已。事上以敬，处下以和，井井然未尝稍失。每见朝暾上窗，即披衣急起，如有人呼促者然。余笑曰：“今非吃粥比矣，何尚畏人嘲耶？”芸曰：“曩之藏粥待君，传为话柄，今非畏嘲，恐堂上道新娘懒惰耳。”余虽恋其卧而德其正，因亦随之早起。自此耳鬓相磨，亲同形影，爱恋之情有不可以言语形容者。', '本文节选自《浮生六记·卷一·闺房记乐》，作者以深情直率的笔调叙了夫妻闺房之乐，写出了夫妻间至诚至爱的真情。在中国文学史上，描写情爱的诗文很多，但大多或写宫廷艳史，或写权势礼法淫威下的爱情悲剧，或写风尘知己及少男少女之间的缠绵，很少涉及夫妻之情。别具慧眼的陈寅恪指出：“吾国文学，自来以礼法顾忌之故，不敢多言男女间关系，而于正式男女关系如夫妇者，尤少涉及。盖闺房燕昵之情意，家庭迷盐之琐屑，大抵不列于篇章，惟以笼统之词，概括言之而已。此后来沈三白《浮生六记》之《闺房记乐》，所以为例外创作。”', '', '', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed210d635634aee3eab9a", "shortContent": "本篇为《浮生六记》之《闺房记乐》的节选。诚如史家陈寅恪先生所言，我国文学因礼法顾忌之故，记夫妻生活的不多，“盖闺房燕昵之情事，家庭米盐之琐屑，大抵不列于篇章”。但《浮生六记》是个例外。\n《浮生六记》共六篇，现存《闺房记乐》、《闲情记趣》、《坎坷记愁》、《浪游记快》，作者沈复，清乾嘉年间苏州人，是个较有修养的小知识分子，没有功名。《闺房记乐》记叙了他和妻子芸娘之间简单平淡，却情投意合的生活故事。\n芸...", "authors": ["严", "明"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa8911759740c9ca3d2", "shortContent": "本篇故事名为“赤壁雅鬼”，其实更确切的题目应该是“赤壁酸鬼”。不是吗，这偶然相聚于赤壁之夜的两鬼一人，都自命清雅不凡，似乎满腹经纶，出言作诗，动辄引经据典，旁征博引，上追天文，下穷地理，名人名言，或者非名人的非名言，无不搜罗殆尽，又曲尽其意地将其穿插进自己的诗中，好像无此便不足以显示其“雅”、显示其渊博的学问一样。不过事实恰恰相反，府学司马生和靳水谢生所吟之诗，不过自鸣得意而已，撇开其平白无聊的内...", "authors": ["欧阳云飞"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fad0ce818559d0712a7", "shortContent": "如果说有“好看不好讲”的文章，那么这篇《海棠词》就是。\n文章写一个沈秀才日走荒山迷了路，黄昏时发现近处有所不知名的楼台，于是趋前准备投宿。临近楼台，听见里面有一群少女在谈天，在做诗，在嬉闹。秀才囿于礼教，认为投宿不便；但少女所谈使自己陡然兴起，于是便潜伏左近，一直偷听到次日黎明。天亮之后，秀才放胆走进楼台，观察了室内十分雅致的摆设，同时也听见少女从闺阁传来的鼾声。秀才激动了，终又依依不舍告别了这一...", "authors": ["徐城北"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42c703572034f65b6afb", "shortContent": "本篇采自沈复所著笔记小说《浮生六记》。书名取李白《春夜宴季弟桃李园序》“浮生若梦，为欢几何”之意。全书共六卷，现存前四卷。其前三卷内容连贯，主要写作者与妻子陈芸的日常生活，可以说是二人的合传。本篇系第一卷，主要写二人的闺房之乐，极见情投意合、心心相印、鱼水相得之状。文章恬淡自然，虽不像近现代以来的许多小说那样具有明显而强烈的反封建思想，作品中的人物也不是什么封建叛逆者，更谈不上什么民主斗士，但许多...", "authors": ["王恒展"], "pressName": "上海辞书出版社"}]', '', 'indent', 1359648887, '57b8f1a58ac2470062df35a5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10024, '夜雨寄北', NULL, 2649, 603, 1, 18, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/view/4412.htm', '', '君问归期未有期，巴山夜雨涨秋池。
何当共剪西窗烛，却话巴山夜雨时。', '《夜雨寄北》是晚唐诗人李商隐身居异乡巴蜀，写给远在长安的妻子（一说友人）的一首抒情七言绝句，是诗人给对方的复信。诗的开头两句以问答和对眼前环境的抒写，阐发了孤寂的情怀和对妻子深深的思念。后两句即设想来日重逢谈心的欢悦，反衬今夜的孤寂。这首诗即兴写来，写出了诗人刹那间情感的曲折变化。语言朴实，在遣词、造句上看不出修饰的痕迹。与李商隐的大部分诗词表现出来的辞藻华美，用典精巧，长于象征、暗示的风格不同，这首诗却质朴、自然，同样也具有“寄托深而措辞婉”的艺术特色。', '寄北：写诗寄给北方的人。诗人当时在巴蜀（现在四川省），他的亲友在长安，所以说“寄北”。这首诗表达了诗人对亲友的深刻怀念。
君：对对方的尊称，等于现代汉语中的“您”。
归期：指回家的日期。
巴山：指大巴山，在陕西南部和四川东北交界处。这里泛指巴蜀一带。
秋池：秋天的池塘。
何当：什么时候
剪西窗烛：剪烛，剪去燃焦的烛芯，使灯光明亮。这里形容深夜秉烛长谈。“西窗话雨”“西窗剪烛”用作成语，所指也不限于夫妇，有时也用以写朋友间的思念之情。
却话：回头说，追述。', '你问我什么时候回去，我还没有确定的日子。此刻巴山的夜雨淅淅沥沥，雨水涨满了秋天的河池。
什么时候我才能回到家乡，在西窗下我们一边剪烛一边谈心，那时我再对你说说，今晚在巴山作客听着绵绵夜雨的心情。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92db5914587d02f4e940", "shortContent": "这首诗，宋洪迈《万首唐人绝句》题作《夜雨寄内》，“内”就是“内人”——妻子；今传李诗各本题作《夜雨寄北》，“北”就是北方的人，可以指妻子，也可以指朋友。有人经过考证，认为它作于作者的妻子王氏去世之后，因而不是“寄内”诗，而是写赠长安友人的。但从诗的内容看，按“寄内”理解，似乎更确切一些。\n第一句一问一答，先停顿，后转折，跌宕有致，极富表现力。翻译一下，那就是：“你问我回家的日期；唉，回家的日期嘛，...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9820695e6503fff5", "shortContent": "这首诗，宋洪迈《万首唐人绝句》题作《夜雨寄内》，“内”就是“内人”——妻子；今传李诗各本题作《夜雨寄北》，“北”就是北方的人，可以指妻子，也可以指朋友。有人经过考证，认为它作于作者的妻子王氏去世之后，因而不是“寄内”诗，而是写赠长安友人的。但从诗的内容看，按“寄内”理解，似乎更确切一些。\n\n第一句一问一答，先停顿，后转折，跌宕有致，极富表现力。翻译一下，那就是：“你问我回家的日期；唉，回家的日期嘛...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d86c9ebcc6fbea1a113", "shortContent": "一、二句谓妻问我何日回家，我还回答不上；巴山一夜的秋雨涨满了池塘。三、四句说何时还乡与妻在西窗下挑灯夜话？再聊叙巴山夜雨时的九曲回肠。语浅情深，是寄内之作。此夜羁情无处说，转从他日话今宵。", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4dc26cbf3417f09393", "shortContent": "这首诗是作者在四川梓州做幕僚时怀念妻子之作。首句点题，说明这首诗是以诗代书。是妻子在分手时“尚未登程，先问归期”呢，还是在诗人到达任所后来信询问——诗中没有交代，但“问归期”说明她盼他回去心切；诗一开头就提归期，也说明诗中人同样把归期时时在念，他也在思念妻子。非常遗憾的是这封代书诗却带给妻子以“未有期”的坏消息。抱歉而又无可奈何之情，欲归不能的无限愁苦跃然纸上。七个字先停顿，后转折，跌宕有致。\n\n...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707a73206168b2e02224", "shortContent": "这首诗是作者在四川梓州做幕僚时怀念妻子之作。首句点题，说明这首诗是以诗代书。是妻子在分手时“尚未登程，先问归期”呢，还是在诗人到达任所后来信询问——诗中没有交代，但“问归期”说明她盼他回去心切；诗一开头就提归期，也说明诗中人同样把归期时时在念，他也在思念妻子。非常遗憾的是这封代书诗却带给妻子以“未有期”的坏消息。抱歉而又无可奈何之情，欲归不能的无限愁苦跃然纸上。七个字先停顿，后转折，跌宕有致。\n\n...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312714a77683d193301546f", "shortContent": "这首诗是作者在四川梓州做幕僚时怀念妻子之作。首句点题，说明这首诗是以诗代书。是妻子在分手时“尚未登程，先问归期”呢，还是在诗人到达任所后来信询问——诗中没有交代，但“问归期”说明她盼他回去心切；诗一开头就提归期，也说明诗中人同样把归期时时在念，他也在思念妻子。非常遗憾的是这封代书诗却带给妻子以“未有期”的坏消息。抱歉而又无可奈何之情，欲归不能的无限愁苦跃然纸上。七个字先停顿，后转折，跌宕有致。\n第...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64630f1e5e6bb82b8cbce8f0", "shortContent": "这首诗，宋洪迈《万首唐人绝句》题作《夜雨寄内》，“内”就是“内人”——妻子；今传李诗各本题作《夜雨寄北》，“北”就是北方的人，可以指妻子，也可以指朋友。有人经过考证，认为它作于作者的妻子王氏去世之后，因而不是“寄内”诗，而是写赠长安友人的。但从诗的内容看，按“寄内”理解，似乎更确切一些。\n\n第一句一问一答，先停顿，后转折，跌宕有致，极富表现力。翻译一下，那就是：“你问我回家的日期；唉，回家的日期嘛...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f9f782772d459428042a", "shortContent": "这首诗，宋洪迈《万首唐人绝句》题作《夜雨寄内》，“内”就是“内人”———妻子；今传李诗各本题作《夜雨寄北》，“北”就是北方的人，可以指妻子，也可以指朋友。有人经过考证，认为它作于作者的妻子王氏去世之后，因而不是“寄内”诗，而是写赠长安友人的。但从诗的内容看，按“寄内”理解，似乎更确切一些。\n第一句一问一答，先停顿，后转折，跌宕有致，极富表现力。翻译一下，那就是：“你问我回家的日期；唉，回家的日期嘛...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '俞陛云《诗境浅说》：清空如话，一气循环，绝句中最为擅胜。诗本寄友，如闻娓娓清谈，深情弥见。
纪昀：作不尽语，不免有做作态，此诗含蓄不露，却只似一气说完，故为高唱。
桂馥《札朴》卷六：眼前景反作后日怀想，此意更深。
徐德泓《李义山诗疏》：翻从他日而话今宵，则此时羁情，不写而自深矣。
姚培谦《李义山诗集笺》：“料得闺中夜深坐，多应说着远行人”（白居易《邯郸冬至夜思家》），是魂飞到家里去。此诗则又预飞到归家后也，奇绝！', 'center', 1359673195, '57b1670da633bd00570a3147', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10025, '登乐游原', NULL, 810, 603, 1, 4, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/87250/10296514.htm', '', '向晚意不适，驱车登古原。
夕阳无限好，只是近黄昏。', '此诗赞美黄昏前的原野风光，表达自己的感受。前两句点出登原游览的原因：由于黄昏日暮心情不适，便驱车登上古原；後两句极力赞叹晚景之美：在夕阳馀晖照耀下，涂抹上一层金色的世界。後两句诗历来脍炙人口，其意蕴非常丰富，具有极高的美学价值和思想价值。全诗语言明白如话，毫无雕饰，节奏明快，感喟深沉，富于哲理。', '乐游原：在长安（今西安）城南，是唐代长安城内地势最高地。汉宣帝立乐游庙，又名乐游苑。登上它可望长安城。乐游原在秦代属宜春苑的一部分，得名于西汉初年。《汉书·宣帝纪》载，「神爵三年，起乐游苑」。汉宣帝第一个皇后许氏产後死去葬于此，因「苑」与「原」谐音，乐游苑即被传为「乐游原」。对此《关中记》有记载：「宣帝许后葬长安县乐游里，立庙于曲江池北，曰乐游庙，因苑（《长安志》误作葬字）为名。」
向晚：傍晚。
不适：不悦，不快。
古原：指乐游原。
近：快要。', '傍晚时心情不快，驾着车登上古原。
夕阳啊无限美好，只不过接近黄昏。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dbd635634aee3deee4", "shortContent": "诗人玉谿，另有一首七言绝句，写道是：“万树鸣蝉隔断虹，乐游原上有西风；羲和自趁虞泉〔渊〕宿，不放斜阳更向东！”（《乐游原》）那也是登上古原，触景萦怀，抒写情志之作。看来，乐游原是他素所深喜、不时来赏之地。这一天的傍晚，不知由于何故，玉谿意绪不佳，难以排遣，他就又决意游观消散，命驾驱车，前往乐游原而去。\n乐游原之名，我们并不陌生，原因之一是有一篇千古绝唱《忆秦娥》深深印在我们的“诗的摄像”宝库中，那...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9820695e6503fff3", "shortContent": "诗人玉谿，另有一首七言绝句，写道是：“万树鸣蝉隔断虹，乐游原上有西风；羲和自趁虞泉〔渊〕宿，不放斜阳更向东！”（《乐游原》）那也是登上古原，触景萦怀，抒写情志之作。看来，乐游原是他素所深喜、不时来赏之地。这一天的傍晚，不知由于何故，玉谿意绪不佳，难以排遣，他就又决意游观消散，命驾驱车，前往乐游原而去。\n\n乐游原之名，我们并不陌生，原因之一是有一篇千古绝唱《忆秦娥》深深印在我们的“诗的摄像”宝库中，...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d8bc26cbf3417f090df", "shortContent": "乐游原是京城郊外的高地，自秦汉以来一直是著名的风景区，登高望远的好去处。义山多次登此古原，写下多首以乐游原为题的诗篇，都写得好，而以本篇流传最广，脍炙人口，家喻户晓。诗的前两句说得很明白，诗人因为心情不愉快，于是在黄昏之时驱车到郊外的乐游原排遣愁闷，原因和目的都很清楚。后二句将诗人登高所见所感用最精辟的语言作了绝妙的表达。“夕阳无限好，只是近黄昏。”这两句诗真可谓千古绝唱，可谓惊心动魄，一字千金。...", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e903a1", "shortContent": "时间已是傍晚，天色开始渐渐黯淡了，诗人突然觉得心情不舒畅，于是就乘车来到了长安城东南的乐游原。诗人为什么觉得心情不畅呢？作品中没有任何的交代。但联想到作者一生沉沦下僚，漂泊薄宦，长期艰难地挣扎在牛李党争的漩涡里，那么致使作者郁闷的因素自是可以想见的，只是难以确指罢了。\n\n乐游原是长安城附近著名的古迹。据记载，它原是秦朝的宜春苑，在汉宣帝时因修乐游庙，故改名乐游原。武后执政期间，太平公主曾于此修造亭...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707a73206168b2e02222", "shortContent": "时间已是傍晚，天色开始渐渐黯淡了，诗人突然觉得心情不舒畅，于是就乘车来到了长安城东南的乐游原。诗人为什么觉得心情不畅呢？作品中没有任何的交代，但联想到作者一生沉沦下僚，漂泊薄宦，长期艰难地挣扎在牛李党争的漩涡里，那么可以想见，致使作者郁闷的因素自然很多，只是难以鲜明地确指罢了。\n\n乐游原是长安城附近著名的古迹。据记载，它原是秦朝的宜春苑，在汉宣帝时因修乐游庙，故改名乐游原。武后执政期间，太平公主曾...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312714a77683d193301546e", "shortContent": "乐游原是长安城附近著名的古迹。据记载，它原是秦朝的宜春苑，在汉宣帝时因修乐游庙，故改名乐游原。武后执政期间，太平公主曾于此修造亭阁，每到正月三十、三月三日、重阳佳节，长安士女常到此观赏，因此也是一处有名的旅游景点。唐代诗人们在乐游原留下了近百首珠玑绝句，历来为人所称道，诗人李商隐便是其中之一。\n此诗一、二句点明登古原的时间和原因。时间已是傍晚，天色开始渐渐黯淡了。诗人心情不悦，于是就乘车来到了长安...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64630e967f27182da34cd64f", "shortContent": "诗人玉谿，另有一首七言绝句，写道是：“万树鸣蝉隔断虹，乐游原上有西风；羲和自趁虞泉〔渊〕宿，不放斜阳更向东！”（《乐游原》）那也是登上古原，触景萦怀，抒写情志之作。看来，乐游原是他素所深喜、不时来赏之地。这一天的傍晚，不知由于何故，玉谿意绪不佳，难以排遣，他就又决意游观消散，命驾驱车，前往乐游原而去。\n\n乐游原之名，我们并不陌生，原因之一是有一篇千古绝唱《忆秦娥》深深印在我们的“诗的摄像”宝库中，...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}]', '《彦周诗话》：觉范作《冷斋夜话》，有曰：「诗至李义山，为文章一厄。」仆读至此，蹙额无语，渠再三穷诘，仆不得已曰：「夕阳无限好，只是近黄昏。」觉范曰：「我解子意矣！」即时删去。今印本犹存之，盖已前传出者。
《唐诗品汇》：杨诚斋云：此诗忧唐祚将衰也。
《删订唐诗解》：吴昌祺云：二句似诗馀，然亦首选。宋人谓喻唐祚，亦不必也。
《李义山诗集辑评》：何焯曰：迟暮之感，沉沦之痛，触绪纷来，悲凉无限。又曰：又叹时无宣帝可致中兴，唐祚将沦也。朱彝尊曰：言值唐家衰晚也。纪昀曰：百感茫茫，一时交集，谓之悲身世可，谓之忧时事亦可。又曰：末二句向来所赏，实妙在第一句倒装而入，乃字字有根。或谓「夕阳」二句近小词，此充类至义之尽语，要不为无见，赖起二句苍劲足相救耳。
《李义山诗集笺注》：姚培谦曰：销魂之语，不堪多诵。
《玉溪生诗意》：时事遇合，俱在个中，抑扬尽致。
《诗法易简录》：以末句收足「向晚」意，言外有身世迟暮之感。
《唐贤小三昧集续集》：怆怀欲绝（末二句下）。
《读雪山房唐诗钞序例》：李义山《乐游原》诗，消息甚大，为绝句中所未有。
《网师园唐诗笺》：爱惜景光，仍收到「不适」（末二句下）。
《岘佣说诗》：义山「向晚意不适……」叹老之意极矣，然只说夕阳，并不说自己，所以为妙。五绝、七绝，均须如此，此亦比兴也。
《小匏庵诗话》：李义山诗「夕阳无限好，只是近黄昏」，宋程伯子诗「未须愁日暮，天际是轻阴」，寥寥十字，两朝兴废之迹寓焉……孰谓诗人吟风嘲月，无当于輶轩之采乎？
《选玉溪生诗补说》：「向晚」二字，领起全神。
《诗境浅说续编》：诗言薄暮无聊，藉登眺以舒怀抱。烟树人家，在微明夕照中，如天开图画；方吟赏不置，而无情暮景，已逐步逼人而来，一入黄昏，万象都灭，玉溪生若有深感者。
《唐人绝句精华》：作者因晚登古原，见夕阳虽好而黄昏将至，遂有美景不常之感。此美景不常之感，久蕴积在诗人意中，今外境适与相合，故虽未明指所感，而所感之事即在其中。
《唐诗鉴赏辞典》：周汝昌：玉谿此诗却久被前人误解，他们把「只是」解成了後世的「只不过」、「但是」之义，以为玉谿是感伤哀叹，好景无多，是一种「没落消极的心境的反映」，云云。殊不知，古代「只是」，原无此义，它本来写作「祗是」，意即「止是」、「仅是」，因而乃有「就是」、「正是」之意了。别家之例，且置不举，单是玉谿自己，就有好例，他在《锦瑟》篇中写道：「此情可待（义即何待）成追忆，只是当时已惘然！」其意正谓：就是（正是）在那当时之下，已然是怅惘难名了。有将这个「只是当时」解为「即使是在当时」的，此乃成为假设语词了，而「只是」是从无此义的，恐难相混。', 'center', 1417610605, '57b914515bbb50005b78c8ed', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10027, '锦瑟', NULL, 3408, 603, 4, 10, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/17583/5000399.htm', '', '锦瑟无端五十弦，一弦一柱思华年。
庄生晓梦迷蝴蝶，望帝春心托杜鹃。
沧海月明珠有泪，蓝田日暖玉生烟。
此情可待成追忆？只是当时已惘然。', '《锦瑟》是唐朝诗人李商隐的代表作。诗题「锦瑟」，但并非咏物，不过是按古诗的惯例以篇首二字为题，实是借瑟以隐题的一首无题诗。
诗人一生经历，有难言之痛，至苦之情，郁结中怀，发为诗句，往复低回。如谓锦瑟之诗中有生离死别之恨，恐怕也并非臆断。诗人追忆了自己的青春年华，伤感自己不幸的遭遇，寄托了悲慨、愤懑的心情。全诗运用比兴，善用典故，词藻华美，含蓄深沉，情真意长，感人至深。', '锦瑟：装饰华美的瑟。瑟，拨弦乐器，通常二十五弦。
无端：犹何故。怨怪之词。
五十弦：这里是托古之词。作者的原意，当也是说锦瑟本应是二十五弦。
「庄生晓梦迷蝴蝶」句：《庄子·齐物论》：「庄周梦为蝴蝶，栩栩然蝴蝶也；自喻适志与！不知周也。俄然觉，则蘧蘧然周也。不知周之梦为蝴蝶与？蝴蝶之梦为周与。」李商隐此引庄周梦蝶故事，以言人生如梦，往事如烟之意。
「望帝春心托杜鹃」句：《华阳国志·蜀志》：「杜宇称帝，号曰望帝。……其相开明，决玉垒山以除水害，帝遂委以政事，法尧舜禅授之义，遂禅位于开明。帝升西山隐焉。时适二月，子鹃鸟鸣，故蜀人悲子鹃鸟鸣也。」子鹃即杜鹃，又名子规。
珠有泪：《博物志》：「南海外有鲛人，水居如鱼，不废绩织，其眼泣则能出珠。」
蓝田：《元和郡县志》：「关内道京兆府蓝田县：蓝田山，一名玉山，在县东二十八里。」
只是：犹「止是」、「仅是」，有「就是」、「正是」之意。', '精美的瑟为什么竟有五十根弦，一弦一柱都叫我追忆青春年华。
庄周翩翩起舞睡梦中化为蝴蝶，望帝把自己的哀怨托身于杜鹃。
明月沧海鲛人流下了滴滴眼泪，蓝田日暖玉石才能够化作青烟。
此时此景为什么要现在才追忆？只因为当时心中只是一片茫然。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92db911759740c9b1cb2", "shortContent": "这首《锦瑟》，是李商隐的代表作，爱诗的无不乐道喜吟，堪称最享盛名；然而它又是最不易讲解的一篇难诗，自宋元以来，揣测纷纷，莫衷一是。\n诗题“锦瑟”，是用了起句的头二个字。旧说中，原有认为这是咏物诗的，但近来注解家似乎都主张：这首诗与瑟事无关，实是一篇借瑟以隐题的“无题”之作。我以为，它确是不同于一般的咏物体，可也并非只是单纯“截取首二字”以发端比兴而与字面毫无交涉的无题诗。它所写的情事分明是与瑟相关...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9820695e6503fff1", "shortContent": "这首《锦瑟》，是李商隐的代表作，爱诗的无不乐道喜吟，堪称最享盛名；然而它又是最不易讲解的一篇难诗，自宋元以来，揣测纷纷，莫衷一是。\n\n诗题“锦瑟”，是用了起句的头二个字。旧说中，原有认为这是咏物诗的，但近来注解家似乎都主张：这首诗与瑟事无关，实是一篇借瑟以隐题的“无题”之作。我以为，它确是不同于一般的咏物体，可也并非只是单纯“截取首二字”以发端比兴而与字面毫无交涉的无题诗。它所写的情事分明是与瑟相...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d8b9761253910e901cb", "shortContent": "《锦瑟》一诗是义山的压卷之作，历来对它的解释分歧很大。元好问《论诗》绝句曰：“望帝春心托杜鹃，佳人锦瑟怨华年。诗家总爱西昆好，独恨无人作郑笺。”王渔洋也有“一篇锦瑟解人难”的慨叹。北宋刘放的《中山诗话》谓锦瑟是令狐楚家婢女的名字，义山与她有过秘密恋爱，故借其名字为题，追忆旧情。接着黄朝英的《缃素杂记》托言黄庭坚与苏轼的问答谓本诗专为咏瑟，表达瑟声具有适、怨、清、和的情趣。清代朱鹤龄、冯浩等多人认为...", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f09354", "shortContent": "这首诗当是李商隐晚年回顾平生遭遇，感慨身世的作品。句意隐晦，故素称难解，歧说纷纷。然首联云“思华年”，故揣度全篇应是表达对逝去的美好年华不胜伤感之情。\n\n全诗由见锦瑟而心生怨恨写起，起得突兀。传说古瑟本为五十根弦，后改为二十五弦。诗人听到弦柱之间所奏出的悲声，引起了对往日美好年华的追思，顿觉年华易逝，身世飘零，故而触物生悲，埋怨锦瑟没来由地却有这么多弦，奏出如此悲声，引逗身世之感。又或以锦瑟的五十...", "authors": ["张力"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707a73206168b2e02225", "shortContent": "这首诗当是李商隐晚年回顾平生遭遇，感慨身世的作品。句意隐晦，故素称难解，歧说纷纷。然首联云“思华年”，故揣度全篇应是表达对逝去的美好年华不胜伤感之情。\n\n全诗由见锦瑟而心生怨恨写起，起得突兀。传说古瑟本为五十根弦，后改为二十五弦。诗人听到弦柱之间所奏出的悲声，引起了对往日美好年华的追思，顿觉年华易逝，身世飘零，故而触物生悲，埋怨锦瑟没来由地却有这么多弦，奏出如此悲声，引逗身世之感。又或以锦瑟的五十...", "authors": ["张力"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312714a77683d1933015470", "shortContent": "这首诗当是李商隐晚年回顾平生遭遇，感慨身世的作品。句意隐晦，故素称难解，歧说纷纷。然首联云“思华年”，故揣度全篇应是表达对逝去的美好年华不胜伤感之情。\n全诗由见锦瑟而心生怨恨写起，起得突兀。传说古瑟本为五十根弦，后改为二十五弦。诗人听到弦柱之间所奏出的悲声，引起了对往日美好年华的追思，顿觉年华易逝，身世飘零，故而触物生悲，埋怨锦瑟没来由地却有这么多弦，奏出如此悲声，引逗身世之感。又或以锦瑟的五十根...", "authors": ["张力"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64630c1130675327e181e32e", "shortContent": "这首《锦瑟》，是李商隐的代表作，爱诗的无不乐道喜吟，堪称最享盛名；然而它又是最不易讲解的一篇难诗，自宋元以来，揣测纷纷，莫衷一是。\n\n诗题“锦瑟”，是用了起句的头二个字。旧说中，原有认为这是咏物诗的，但近来注解家似乎都主张：这首诗与瑟事无关，实是一篇借瑟以隐题的“无题”之作。我以为，它确是不同于一般的咏物体，可也并非只是单纯“截取首二字”以发端比兴而与字面毫无交涉的无题诗。它所写的情事分明是与瑟相...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f31b930675327e1b5da6c", "shortContent": "这首《锦瑟》，是李商隐的代表作，爱诗的无不乐道喜吟，堪称最享盛名；然而它又是最不易讲解的一篇难诗，自宋元以来，揣测纷纷，莫衷一是。\n诗题“锦瑟”，是用了起句的头两个字。旧说中，原有认为这是咏物诗的，但近来注解家似乎都主张：这首诗与瑟事无关，实是一篇借瑟以隐题的“无题”之作。我以为，它确是不同于一般的咏物体，可也并非只是单纯“截取首二字”以发端比兴而与字面毫无交涉的无题诗。它所写的情事分明是与瑟相关...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}]', '刘攽《中山诗话》：李商隐有《锦瑟》诗，人莫晓其意，或谓是令狐楚家青衣名也。
黄朝英《缃素杂记》：东坡云：此出《古今乐志》，云：「锦瑟之为器也，其弦五十，其柱如之，其声也适、怨、清、和。」案李诗，「庄生晓梦迷蝴蝶」，适也；「望帝春心托杜鹃」，怨也；「沧海月明珠有泪」，清也；「蓝田日暖玉生烟」，和也。一篇之中，曲尽其意。
王世贞《艺苑巵言》：中二联是丽语，作「适、怨、清、和」解甚通。然不解则涉无谓，既解则意味都尽，以此知诗之难也。
杨士弘、顾璘《批点唐音》：此诗自是闺情，恐不泥在锦瑟耳。
胡应麟《诗薮》：锦瑟是青衣名，见唐人小说，谓义山有感作者。观此诗结句及晓梦、春心、蓝田、珠泪等，大概无题中语，但首句略用锦瑟引起耳。宋人认作咏物，以适、怨、清、和字面附会穿凿，遂令本意懵然。且至「此情可待成追忆」处，更说不通。学者试尽屏此等议论，只将题面作青衣，诗意作追忆读之，自当踊跃。
胡震亨《唐音癸签》：以锦瑟为真瑟者痴。以为令狐楚青衣，以为商隐庄事楚，狎绹，必绹青衣，亦痴。商隐情诗，借诗中两字为题者尽多，不独《锦瑟》。
陆次云《五朝诗善鸣集》：义山晚唐佳手，佳莫佳于此矣。意致迷离，在可解不可解之间，于初盛诸家中得未曾有。三楚精神，笔端独得。
钱谦益、何焯《唐诗鼓吹评注》：此义山有托而咏也……顾其意言所指，或忆少年之艳冶，而伤美人之迟暮，或感身世之阅历，而悼壮夫之晼晚，则未可以一辞定也。
何焯《义门读书记》：此悼亡诗也。首特借素女鼓五十弦之瑟而悲，泰帝禁不可止，发端言悲思之情有不可得而止者。次联则悲其遽化为异物。腹联又悲其不能复起之九泉也。曰「思华年」，曰「追忆」，旨趣晓然，何事纷纷附会乎？
沈厚塽《李义山诗集辑评》：朱彝尊曰：此悼亡诗也。意亡者善弹此，故睹物思人，因而托物起兴也。瑟本二十五弦，一断而为五十弦矣，故曰「无端」也，取断弦之意也。「一弦一柱」而接「思华年」三字，意其人年二十五而殁也。胡蝶、杜鹃，言已化去也；「珠有泪」，哭之也；「玉生烟」，葬之也，犹言埋香瘗玉也。此情岂待今日「追忆」乎？只是当时生存之日，已常忧其至此，而预为之「惘然」，意其人必婉然多病，故云然也。何焯曰：此篇乃自伤之词，骚人所谓美人迟暮也。「庄生」句言付之梦寐，「望帝」句言待之来世；「沧海」、「蓝田」言埋而不得自见；「月明」、「日暖」则清时而独为不遇之人，尤可悲也。又：感年华之易迈，借锦瑟以发端。「思华年」三字，一篇之骨。三四赋「思」也。五六赋「华年」也。末仍结归思之。纪昀曰：以「思华年」领起，以「此情」二字总承。盖始有所欢，中有所恨，故追忆之而作。中四句迷离惝恍，所谓「惘然」也。韩致光《五更》诗云：「光景旋消惆怅在，一生赢得是凄凉。」即是此意，别无深解。
吴乔《围炉诗话》：诗意大抵出侧面。郑仲贤《送别》云：「亭亭画舸系春潭，只待行人酒半酣。不管烟波与风雨，载将离恨过江南。」人自别离，却怨画舸。义山忆往事而怨锦瑟，亦然。
杜诏、杜庭珠《中晚唐诗叩弹集》：杜诏云：诗以锦瑟起兴，「无端」二字便有自讶自怜之意，此瑟之弦遂五十邪？瑟之柱如其弦，而人之年已历历如其柱矣。
查慎行《初白庵诗评》：此诗借题寓感，解者必从锦瑟着题，遂苦苦牵合。读到结句，如何通得去？
朱鹤龄《重订李义山诗集笺注》：程梦星曰：旧说适、怨、清、和之穿凿，令狐青衣之附会，前人已辞而辟之。朱长孺定为悼亡，归于一是矣……三四谓生者辗转结想，唯有迷晓梦于蝴蝶；死者魂魄能归，不过托春心于杜鹃。五六谓其容仪端妍，如沧海之珠，今深沉泉路，空作鲛人之泪矣；性情温润如蓝田之玉，今销亡冥漠，不啻紫玉之烟矣……「此情」二字，紧承上二句，谓不堪追忆其人亡事在。「当时」二字，缴回「华年」，谓不堪悲悼其年远日湮。起「思」字，结「忆」字，一篇之呼应也。
屈复《玉溪生诗意》：以「无端」吊动「思华年」。中四紧承。七「此情」紧收「可待」字、「只是」字，遥应「无端」字。一，兴也。二，一篇主句。中四皆承「思华年」。七八总结。诗面与「无题」同，其意或在君臣朋友间，不可知也。
薛雪《一瓢诗话》：此诗全在起句「无端」二字，通体妙处，俱从此出。意云：锦瑟一弦一柱，已足令人怅望年华，不知何故有此许多弦柱，令人怅望不尽；全似埋怨锦瑟无端有此弦柱，遂使无端有此怅望。即达若庄生，亦迷晓梦；魂为杜宇，犹托春心。沧海珠光，无非是泪；蓝田玉气，恍若生烟。触此情怀，垂垂迫溯，当时种种，尽付惘然。对锦瑟而兴悲，叹无端而感切。如此体会，则诗神诗旨，跃然纸上。
周咏棠《唐贤小三昧集续集》：得此结语，全首翻作烟波（末二句下）。
黄叔灿《唐诗笺注》：此义山年登五十，追溯平生而作也。
吴瑞荣《唐诗笺要》：即用黄帝命素女鼓五十弦，悲不自止之意。中四句曲尽情致。
叶矫然《龙性堂诗话》：细味此诗，起句说「无端」，结句说「惘然」，分明是义山自悔其少年场中，风流摇荡，到今始知其有情皆幻，有色皆空也。次句说「思华年」，懊悔之意毕露矣。此与香山《和微之梦游》诗同意。「晓梦」、「春心」、「月」、「明」、「日暖」，俱是形容其风流摇荡处，着解不得。义山用事写意，皆此类也。义山《锦瑟》诗之佳，在「一弦一柱」中思其「华年」，心绪紊乱，故中联不伦不次，没首没尾，正所谓「无端」也。而以「清和适怨」当之，不亦拘乎？
汪师韩《诗学纂闻》：《锦瑟》乃是以古瑟自况……世所用者，二十五弦之瑟，而此乃五十弦之古制，不为时尚。成此才学，有此文章，即己亦不解其故，故曰「无端」，犹言无谓也。
洪亮吉《北江诗话》：《锦瑟》一篇，皆比体也。
吴汝纶《桐城吴先生评点唐诗鼓吹》：此诗疑为感国祚兴衰而作。
岑仲勉《隋唐史》：余颇疑此诗是伤唐室之残破，与恋爱无关。（元）好问金之遗民，宜其特取此诗以立说。
姜炳璋《选玉溪生补说》：心华结撰，工巧天成，不假一毫凑泊。', 'center', 1415644786, '57b8ab8bd342d3005ac608cd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (11056, '入常山界二首（其二）', NULL, 89, 4331, 1, 1, '杨万里', NULL, 10248, '57b9ba230a2b58006cb02657', '宋', 'shi', '诗', 'http://baike.baidu.com/view/11715122.htm', '', '昨日愁霖今喜晴，好山夹路玉亭亭。
一峰忽被云偷去，留得峥嵘半截青。', '', NULL, NULL, NULL, NULL, 'center', 1445529709, '57ba9f667db2a20068c4d8e2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (42720, '菜薖为永嘉余唐卿右司赋', NULL, 2, 648, 0, 1, '徐贲', NULL, 11077, '5858e61c61ff4b006875bf94', '元', 'shi', '诗', '', '', '远辞华盖居，来卜山阴宅。
乍到俗未谙，久住地旋辟。
屋庐尚朴纯，楹桷谢雕饰。
高营踞山跗，深甃逗泉脉。
檐将狼尾苫，门用鼠筦织。
缺垣唯补萝，圮砌总蒙虉。
编篱限迩邻，树蘖表殊埸。
本来是野性，岂是耽地僻。
学圃欲拟樊，为功敢侔稷。
宁惜劳外形，自甘食馀力。
耕锄限儿课，灌溉当仆役。
破块何畇畇，陈器亦畟畟。
驾许俗士回，屐向邻翁借。
筐筥织湘材，锹锸铸棠液。
卓钁鹰觜利，负蓑猬毛磔。
俯仰疲桔槔，沾洒渍袯襫。
循畦行策镵，偃林卧欹石。
镰披欲芟丘，刈削竟驱砾。
值埠即为坡，遇凹就成洫。
堤崩防密葭，窦隙拒乱棘。
地同农亩计，区学井田画。
长畛纵复横，曲渠广还窄。
接流引馀清，疏沼汇深碧。
架桁秋实垂，篱落夏蔓幂。
雨露加膏腴，粪土发硗瘠。
识种题裹藏，辨类分行植。
莳法常按谱，候时即看历。
蕨芽拳握紫，姜{艹挚}拇骈赤。
两合怜蘮蒘，丛生爱铫芅。
初{艹矜}迸蛰雷，新薹长春{艹涑}。
雀弁萒叶峨，马帚荓茎直。
蔩繁微瓞绵，瓠老枯瓣拆。
芍苗卷龙须，药干拥牛膝。
黄独雪晴收，紫藄露晞摘。
阴阶茂菧苨，下田丰菲蒠。
卷轮木耳垂，攒刺菱角射。
秋茄采更稀，夜韭剪仍殖。
芝芳凝海琼，茭郁点池墨。
枸杞香可醪，竹{⺮姑}熟堪腊。
石皮被柔藫，土酥脍肥菂。
细莼入馔鲈，鲜蒌杂羹鲫。
荼苦蘖与俦，菘脆冰为敌。
菌栌西蜀致，苜蓿大宛得。
长萦荇带流，乱簇蔯丝绎。
芹效野人献，瓜为天子副。
决明才一方，莴苣连数席。
璚縻慰渴心，玉延起羸疾。
蕈毒笑非喜，芥心泣讵戚。
盘根芽埋壤，脱颖笋穿壁。
撷香怜鸡苏，折甘嗜燕麦。
粟腐切方圭，乳饼斫圆璧。
孕子棕受刳，赘聃石被馘。
兔目淘夏槐，鹿角芼腊炙。
菁托诸葛呼，巢以元修斥。
苋褒蔡守清，薇怨周节逆。
邪蒿义所攘，秽荽理堪哑。
薄利嘉拔葵，省谤恶遗薏。
穷餐齑酸黄，俭啖薤留白。
闲情付田园，生意仰膏泽。
荚齐翠疑剪，甲拆绿讶擘。
掩冉烟际姿，葱茜雨馀色。
始掇惜滓染，载涤畏虫螫。
新荐或在笾，薄湘亦须鬲。
求久渐投醝，致爽遽沃醷。
不烦僚友送，敬向先圣释。
对屠夸大嚼，燕客欣小摘。
盘羞不过三，瓮菹当饫百。
未能著蔬经，安敢逾食籍。
旨蓄足山厨，素供过香积。
用兹卒岁年，庶得勤朝夕。
宾魏徐见厌，厄陈颜自怿。
洁畚士耻污，造桥盗怀恤。
抱瓮忿设机，授书诮求益。
纵马因致忧，合蛭遂亡谪。
万钱柳复乞，片金华还掷。
仕知吕侄妄，居味郑人识。
枕肱仲尼乐，伤指范宣阨。
鼎臑固云嘉，食箪亦足适。
敷淡分所安，堪味欲易极。
毋因口体累，遂使愆民德。', '', '', '', NULL, '', 'center', 1525432846, '585ce83d128fe1006de4b35a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10028, '南乡子 · 黄州临皋亭作', NULL, 169, 3406, 3, 2, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/865019.htm', '', '晚景落琼杯，照眼云山翠作堆。认得岷峨春雪浪，初来，万顷蒲萄涨绿醅。
暮雨暗阳台，乱洒歌楼湿粉腮。一阵东风来卷地，吹回，落照江天一半开。', '此词作于元丰四年（1081年），係作者在黄州临皋亭所作，描写一个春日傍晚的即景。
词的上阕写春日晩景，由酒杯而云山，而江水，而岷峨，这是词人形象思维的过程，也是词外在的逻辑。艺术联想和想象的动力是情感。罪系黄州的苏东坡，端起酒杯，思乡之情便油然而生。正是这种情感作为动力，他的联想才最终指向故乡岷峨即蜀中，才产生了杯中之酒是岷峨的雪水这种奇特的心理。思乡之情是词的上阕的内在逻辑。词的下阕写雨降复晴，描绘倏忽变化的自然景观，给人动荡不定、神奇瑰丽的感觉。在政治斗争中遭到挫折的苏东坡，对自然界倏忽变化的敏感，由此可见一斑。整个一首词神气贯通、融为一体。思乡与人生的感慨尽得表现，正所谓「不着一字」而「尽得风流」。', '南乡子：唐教坊曲名，后用作词牌。又名《好离乡》、《蕉叶怨》。《金奁集》入「黄钟宫」。原为单调，有二十七字、二十八字、三十字各体，两平韵，三仄韵，平仄换韵。单调始自后蜀欧阳炯，此词牌即以欧阳炯《南乡子》为正体。冯正中、李珣（Xún）俱本此添字。双调者始自南唐冯正中词。冯词平韵五十六字，十句，上下阕各四句用韵。另有五十八字体者。其定格为双调五十六字，上下阕各四平韵，一韵到底。此调唱时音节需流丽谐婉，声情掩抑。
「黄州临皋亭作」：吴讷钞本、《二妙集》本、毛本作「春情」。
琼杯：傅子立注：「《杨妃外传》：『贵妃进见，初夕处即授以合欢条脱紫琼杯。』」按，初夕，龙榆生笺引傅注作「初处」，沈钞本作「初处」，清钞本、晒蓝本作「初次」，今从珍重阁本改。按，宋·曾至游《类说·卷一·〈杨妃外传·霓裳羽衣曲〉》引《逸史》作「是夕」。
「晚景落琼杯」句：此句应理解为景色倒影在酒杯当中。晚景，夕阳之景；景，日光。
照眼：耀眼。唐·杜少陵《酬郭十五判官》诗：「药裹关心诗总废，花枝照眼句还成。」
翠作堆：状绿色之盛。《二妙集》本作「翠竹堆」。
岷峨：龙榆生笺：「岷山在今四川松潘县北。峨嵋山在今四川峨嵋县西南。两山相对如蛾眉，故意又名蛾眉。」眉山距峨眉甚近，故作者常以之代指家乡。
蒲萄涨绿醅：傅子立注：「李太白：『遥看汉水鸭头绿，恰似葡萄初泼醅。』盖西域人每以葡萄酿酒。」刘尚荣按：「句出《襄阳歌》，『泼』原作『酦』，见《李太白诗集·卷七》。」此喻江水澄澈碧绿。绿醅，元延祐本、吴讷钞本、《二妙集》本、毛本作「渌醅」。
暮雨：元延祐本作「春雨」。
阳台：传在四川巫山。傅子立注：「宋玉《高唐赋》：『旦为朝云，暮为行雨。朝朝暮暮，阳台之下。』」此指歌女所处之所，亦即下句之「歌楼」。
乱洒歌楼：傅子立注：「郑谷《雪》诗：『乱飘僧舍茶烟湿，密洒歌楼酒力微。』」刘尚荣按：「《云台集·卷中》及《全唐诗·卷六百七十五》题作《雪中偶题》」歌楼：吴讷钞本、《二妙集》本、毛本作「高楼」。', '夕阳美丽的景色倒影在手中的玉杯里，青山绿树把一杯的玉液都染绿了。认得这杯中琼浆是故乡岷山和峨眉山上的积雪融化而来。初次看来，万顷的江水都好像那尚未过滤的酒。
阳台山上春雨忽至，胡乱地洒在歌楼打湿了美人的粉腮。忽然一阵东风卷地而来，吹散了云雨，落日的馀晖从乌云缝隙中斜射出来，染红了半边天。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b1911759740c9aa32b", "shortContent": "苏东坡似乎对自然界阴晴不定、倏忽变化的现象非常敏感。在三百数十首苏词中，写乍雨乍晴的奇丽景色的竟有二十多首。并且，首首风貌不同，使人不得不赞叹词人观察入微，感受细腻，表现技巧高超。\n这首词作于元丰四年（1081），傅榦注本的题目为“黄州临皋亭作”。苏轼因为写诗揭露新法的弊端，被贬为黄州团练副使本州安置不得签书公事，成为失去自由的罪人。到黄州后，他开始住在定惠院，以后又迁到长江边上的临皋亭。本词即描...", "authors": ["陈华昌"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b803048e64fbd9bd28", "shortContent": "苏东坡似乎对自然界阴晴不定、倏忽变化的现象非常敏感。在三百数十首苏词中，写乍雨乍晴的奇丽景色的竟有二十多首。并且，首首风貌不同，使人不得不赞叹词人观察入微，感受细腻，表现技巧高超。\n这首词作于元丰四年（1081），傅榦注本的题目为“黄州临皋亭作”。苏轼因为写诗揭露新法的弊端，被贬为黄州团练副使本州安置不得签书公事，成为失去自由的罪人。到黄州后，他开始住在定惠院，以后又迁到长江边上的临皋亭。本词即描...", "authors": ["陈华昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7ac305cf0801816ca9", "shortContent": "朱本卷一据《纪年录》编熙宁七年甲寅（1074），作于润州。龙本卷一从之，然附考云：“此词傅注本既作黄州临皋亭作，则当编辛酉（元丰四年，1081年），时先生年四十六，方寓居临皋亭也。”孔《谱》卷二十、薛本也均编于是年春。曹本、刘尚荣《钞本〈注坡词〉考辨》则编于元丰三年（1080）。今从龙、孔、薛之说，苏轼于元丰三年五月由定惠院迁居临皋亭，第二年春作此词。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646832195e6bb82b8cd26dca", "shortContent": "苏东坡似乎对自然界阴晴不定、倏忽变化的现象非常敏感。在三百数十首苏词中，写乍雨乍晴的奇丽景色的竟有二十多首。并且，首首风貌不同，使人不得不赞叹词人观察入微，感受细腻，表现技巧高超。\n\n这首词作于元丰四年（1081），傅榦注本的题目为“黄州临皋亭作”。苏轼因为写诗揭露新法的弊端，被贬为黄州团练副使本州安置不得签书公事，成为失去自由的罪人。到黄州后，他开始住在定惠院，以后又迁到长江边上的临皋亭。本词即...", "authors": ["陈华昌"], "pressName": "上海辞书出版社"}]', '清·王文诰《苏文忠公诗编注集成总案》：公居亭中，酒醉饭饱，倚于几上，白云左绕，清江右洄，重门洞开，林峦坌入。若有所思而无所思，以受万物之备。', 'indent', 1359758193, '57b90a33df0eea00633528c5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10029, '青玉案 · 元夕', NULL, 2602, 793, 5, 5, '辛弃疾', NULL, 10003, '57b8ed682e958a005fa4d096', '宋', 'ci', '词', 'http://baike.baidu.com/view/143077.htm', '', '东风夜放花千树，更吹落、星如雨。宝马雕车香满路，凤箫声动，玉壶光转，一夜鱼龙舞。
蛾儿雪柳黄金缕，笑语盈盈暗香去。众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。', '这首词是都城元夕观灯所作，宋人习俗，元夕放灯，从正月十四日夜开始，至十六日夜结束。南宋都城临安（今浙江杭州）同汴（biàn）京一样，无论是皇宫、官署、贵臣府第还是普通百姓，都制作灯山，悬放灯火，杂陈百戏，供遊人士女观看。本词应当是作者乾道七年（西元一一七一年）正月居官临安人司农寺主簿时所作。
此词从极力渲染元宵节绚丽多彩的热闹场面入手，反衬出一个孤高淡泊、超群拔俗、不同于金翠脂粉的女性形象，寄托着作者政治失意後，不愿与世俗同流合污的孤高品格。全词采用对比手法，上阕极写花灯耀眼、乐声盈耳的元夕盛况，下阕着意描写主人公在人群之中寻觅一位立于灯火零落处的孤高女子，构思精妙，语言精致，含蓄婉转，馀味无穷。', '青玉案（àn/wǎn）：词牌名。名本汉代张衡《四愁诗》「何以报之青玉案。」此调一般以宋代贺铸所作「凌波不过横塘路」一阕为正格，故又名《横塘路》。双调，六十七字，前後阕各六句，五仄韵。明·杨慎：「古诗青玉案，即盘也。今以案为卓，非。孟光举案即盘也。若今之卓子，岂可举手？」明·王世贞：「孟光举案齐眉，按《说文》‘几属也’。杨用修引张平子『何以报之青玉案』，谓以为青玉碗，且云一妇人安能举案，则用修以案为今之案卓耳。以案作碗，尤无据。」
元夕：夏历正月十五日为上元节，元宵节，此夜称元夕或元夜。
花千树、星如雨：花灯多如千树开花，焰火如乱落纷雨。南宋·孟元老《东京梦华录·卷六·十六日》谓正月十六日京城各坊巷「各以竹竿出灯毬于半空，远近高低，若飞星然。」《左传·庄七年》：「星殒如雨。」唐·苏味道《正月十五日夜》诗：「火树银花合，星桥铁锁开。」
「东风夜放花千树，更吹落、星如雨。」句：形容元宵夜花灯繁多。
宝马雕车：豪华的马车。唐·郭利贞《上元》诗：「九陌连灯影，千门度月华。倾城出宝骑，匝路转香车。」
凤箫声动：指笙、箫等乐器演奏。凤箫，箫的美称。
玉壶：指月，故继之「光转」二字，亦或指灯。宋·周密《武林旧事·卷二·元夕》：「灯之品极多，每以‘苏灯’为最，……福州所进，则纯用白玉，晃耀夺目，如清冰玉壶，爽彻心目。」
鱼龙舞：指舞动鱼形、龙形的彩灯，如鱼龙闹海一样。《汉书·卷九十六下·西域传》赞「漫衍鱼龙、角牴之戏」句下师古注云：「鱼龙者为舍利之兽，先戏于庭极毕，乃入殿前，激水化为比目鱼，跳跃漱水，作雾障日，毕，化成黄龙八丈，出水敖戏于庭，炫耀日光。」北宋·夏竦《奉和御制上元观灯》诗：「鱼龙漫衍六街里，金锁通宵启玉京。」
蛾儿、雪柳、黄金缕：皆古代妇女元宵节时头上佩戴的各种装饰品。这里指盛装的妇女。
「蛾儿雪柳黄金缕」句：写元夕的妇女装饰。南宋·孟元老《东京梦华录·卷六·十六日》：「市人卖玉梅、夜蛾、蜂儿、雪柳、菩提叶、科头圆子、拍头焦半。」《大宋宣和遗事·亨集》：「宣和六年正月十四日夜，……奉圣旨‘宣万姓’。有快行家手中把著金字牌，喝道：‘宣万姓！’少刻，京师民有似云浪，尽头上戴著玉梅、雪柳、闹鹅儿，直到鳌山下看灯。」南宋·陈元靓《岁时广记·卷十一》引《岁时杂记》：「都城仕女有插戴灯毬灯笼，大如枣栗，如珠茸之类。又卖玉梅、雪柳、菩提叶及蛾蜂儿等，皆缯楮为之。」
盈盈：声音轻盈悦耳，亦指仪态娇美的样子。
暗香：本指花香，此指女性们身上散发出来的香气。
他：泛指第三人称，古时就包括「她」。
千百度：千百遍。
蓦然：突然、猛然。
阑珊：零落稀疏的样子。', '像东风吹散千树繁花一样，又吹得乱落如雨。豪华的马车满路芳香。悠扬的凤箫声四处回荡，玉壶般的明月渐渐西斜，一夜鱼龙灯飞舞笑语喧哗。
美人头上都戴着亮丽的饰物，笑语盈盈地随人群走过，身上香气飘洒。我在人群中寻找她千百回，猛然一回头，不经意间却在灯火零落之处发现了她。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74e82cee9a0c24ec7d91", "shortContent": "写上元灯节的词，不计其数，稼轩的这一首，却谁也不能视为可有可无，即此亦可谓豪杰了。然究其实际，上片也不过渲染那一片热闹景况，并无特异独出之处。看他写火树，固定的灯彩也。写“星雨”，流动的烟火也。若说好，就好在想象：是东风还未催开百花，却先吹放了元宵的火树银花。它不但吹开地上的灯花，而且还又从天上吹落了如雨的彩星———燃放烟火，先冲上云霄，复自空而落，真似陨星雨。然后写车马，写鼓乐，写灯月交辉的人间...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ea0f8fda5565060518", "shortContent": "写上元灯节的词，不计其数，稼轩的这一首，却谁也不能视为可有可无，即此亦可谓豪杰了。然究其实际，上片也不过渲染那一片热闹景况，并无特异独出之处。看他写火树，固定的灯彩也。写“星雨”，流动的烟火也。若说好，就好在想象：是东风还未催开百花，却先吹放了元宵的火树银花。它不但吹开地上的灯花，而且还又从天上吹落了如雨的彩星———燃放烟火，先冲上云霄，复自空而落，真似陨星雨。然后写车马，写鼓乐，写灯月交辉的人间...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255eebf5e0fdea508e6", "shortContent": "写上元灯节的词，不计其数，稼轩的这一首，却谁也不能视为可有可无，即此亦可谓豪杰了。然究其实际，上片也不过渲染那一片热闹景况，并无特异独出之处。看他写火树，固定的灯彩也。写“星雨”，流动的烟火也。若说好，就好在想象：是东风还未催开百花，却先吹放了元宵的火树银花。它不但吹开地上的灯花，而且还又从天上吹落了如雨的彩星——燃放烟火，先冲上云霄，复自空而落，真似陨星雨。然后写车马，写鼓乐，写灯月交辉的人间仙...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f4f73206168b2e02100", "shortContent": "元宵节，作为中国古代重要的传统节日，一直是诗人们偏爱的创作题材，亦留下脍炙人口的千古佳句，如唐代苏味道的“灯树千光照，明月逐人来”（《正月十五夜》），崔液的“谁家见月能闲坐，何处闻灯不看来”（《上元夜》），以及宋代欧阳修的“去年元夜时，花市灯如昼。月到柳梢头，人约黄昏后”（《生查子》）等。不过，如果给古代元夕词排座次的话，辛弃疾的这首《青玉案·元夕》当之无愧第一。\n上片以生花妙笔写景，极尽铺叙元宵...", "authors": ["乐　云"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312704773206168b2e021d0", "shortContent": "元宵节，作为中国古代重要的传统节日，一直是诗人们偏爱的创作题材，亦留下脍炙人口的千古佳句，如唐代苏味道的“灯树千光照，明月逐人来”（《正月十五夜》），崔液的“谁家见月能闲坐，何处闻灯不看来”（《上元夜》），以及宋代欧阳修的“去年元夜时，花市灯如昼。月到柳梢头，人约黄昏后”（《生查子》）等。不过，如果给古代元夕词排座次的话，辛弃疾的这首《青玉案·元夕》当之无愧第一。\n\n上片以生花妙笔写景，极尽铺叙元...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631272067ccdb86c49f2939b", "shortContent": "元宵节，作为中国古代重要的传统节日，一直是诗人们偏爱的创作题材，亦留下脍炙人口的千古佳句，如唐代苏味道的“灯树千光照，明月逐人来”（《正月十五夜》）、崔液的“谁家见月能闲坐，何处闻灯不看来”（《上元夜》），以及宋代欧阳修的“去年元夜时，花市灯如昼。月到柳梢头，人约黄昏后”（《生查子》）等。不过，如果给古代元夕词排座次的话，辛弃疾的这首《青玉案·元夕》当之无愧第一。\n上片以生花妙笔写景，极尽铺叙元宵...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "64688f9830675327e19962ff", "bookTitle": "辛弃疾词鉴赏辞典（珍藏本）", "articleId": "6468d8dc5fc8182fe9afd9d2", "shortContent": "写上元灯节的词，不计其数，稼轩的这一首，却谁也不能视为可有可无，即此亦可谓豪杰了。然究其实际，上片也不过渲染那一片热闹景况，并无特异独出之处。看他写火树，固定的灯彩也。写“星雨”，流动的烟火也。若说好，就好在想象：是东风还未催开百花，却先吹放了元宵的火树银花。它不但吹开地上的灯花，而且还又从天上吹落了如雨的彩星——燃放烟火，先冲上云霄，复自空而落，真似陨星雨。然后写车马，写鼓乐，写灯月交辉的人间仙...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "6471757a82772d4594256f93", "shortContent": "写上元灯节的词，不计其数，稼轩的这一首，却谁也不能视为可有可无，即此亦可谓豪杰了。然究其实际，上片也不过渲染那一片热闹景况，并无特异独出之处。看他写火树，固定的灯彩也。写“星雨”，流动的烟火也。若说好，就好在想象：是东风还未催开百花，却先吹放了元宵的火树银花。它不但吹开地上的灯花，而且还又从天上吹落了如雨的彩星——燃放烟火，先冲上云霄，复自空而落，真似陨星雨。然后写车马，写鼓乐，写灯月交辉的人间仙...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}]', '清·彭羡门《金粟词话》：稼轩：「蓦然回首，那人却在，灯火阑珊处。」秦、周之佳境也。
清·梁任公《艺蘅馆词选·丙卷》：自怜幽独，伤心人别有怀抱。
清·王静安《人间词话》：古今之成大事业、大学问者，必经过三种之境界：「昨夜西风凋碧树。独上高楼，望尽天涯路。」此第一境也。「衣带渐宽终不悔，为伊消得人憔悴。」此第二境也。「众里寻他千百度，蓦然回首，那人却在灯火阑珊处。」此第三境也。此等语皆非大词人不能道。', 'indent', 1359758556, '57b14b360a2b5800632b7d20', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10030, '饮酒（其五）', NULL, 2141, 99, 5, 21, '陶渊明', NULL, 10011, '57b8fa07c4c97100558ef104', '晋', 'shi', '诗', 'http://baike.baidu.com/view/2232803.htm', '', '结庐在人境，而无车马喧。
问君何能尔？心远地自偏。
采菊东篱下，悠然见南山。
山气日夕佳，飞鸟相与还。
此中有真意，欲辨已忘言。​', '本篇是《饮酒》二十首中的第五首。诗中写了悠然自得的情，也写了幽美淡远的景，在情景交融的境界中蕴含着万物各得其所、委运任化的哲理；这哲理又被诗人提炼、浓缩到“心远地自偏”、“此中有真意”等警句，整首诗的韵调也更显得隽秀深长。', '结庐：构筑房屋。结，建造、构筑。庐：简陋的房屋。
人境：人聚居的地方。
尔：这样。
日夕：傍晚。
相与：相伴。', '居住在人世间，却没有车马的喧嚣。
问我为何能如此，只要心志高远，自然就会觉得所处地方僻静了。
在东篱之下采摘菊花，悠然间，那远处的南山映入眼帘。
山中的气息与傍晚的景色十分好，有飞鸟结着伴儿归来。
这里面蕴含着人生的真正意义，想要辨识，却不知怎样表达。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccacd635634aee3ea585", "shortContent": "大致在魏晋以前，以儒家学说为核心，中国人一直相信人类和自然界都处于有意志的“天”的支配下。这一种外于而又高于人的个体生命的权威，在东汉末开始遭到强烈的怀疑。于是就迎来了个性觉醒的时代；在文学创作中，相应地有了所谓“人的主题”的兴起。但个性觉醒，既是旧的困境与背谬的结束，又是新的困境与背谬的发现与开始。首先，也是最基本的，就是有限的个体生命与永恒的宇宙的对立。诗人们不断发出哀伤的感叹：“人生天地间，...", "authors": ["骆玉明"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471eab8902ee364cc951621", "shortContent": "另一种版本，“见南山”的“见”字作“望”。最崇拜陶渊明的苏东坡批评说：如果是“望”字，这诗就变得兴味索然了。东坡先生非常聪明，也很懂得喝酒的妙处，他的话说得不错。为什么不能作“望”？因为“望”是有意识的注视，缺乏“悠然”的情味。还可以深一步说：在陶渊明的哲学观中，自然是自在自足无外求的存在，所以才能具足而自由；人生之所以有缺损，全在于人有着外在的追求。外在的追求，必然带来得之惊、失之忧，根本上破坏...", "authors": ["骆玉明"], "pressName": "上海辞书出版社"}]', '叶梦得《石林诗话》：晋人多言饮酒，有至沉醉者，此未必意真在酒。盖时方艰难，人各罹祸，惟托于醉，可以粗远世故。
谭元春《古诗归》：妙在题是饮酒，只当感遇诗、杂诗，所以为远。
黄文焕《陶诗析义》：陶诗凡数首相连者，章法必深于布置。《饮酒》二十首尤为淋漓变化，义多对竖，意则环应。
康发祥：《饮酒》诗，昌黎谓其有托而逃，盖靖节退归后，世变日甚，故得酒必尽醉。其卒章曰：“但恨多谬误，君当恕醉人。”观此二语，则以醉而逃世网，洵可知也。', 'center', 1359758777, '57b8d8b4c4c97100558e5a37', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10031, '西江月 · 夜行黄沙道中', NULL, 1370, 793, 3, 11, '辛弃疾', NULL, 10003, '57b8ed682e958a005fa4d096', '宋', 'ci', '词', 'http://baike.baidu.com/view/383874.htm', '', '明月别枝惊鹊，清风半夜鸣蝉。稻花香里说丰年，听取蛙声一片。
七八个星天外，两三点雨山前。旧时茅店社林边，路转溪桥忽见。', '辛稼轩在南宋做到封疆大吏，但他英伟磊落的议论和果断干练的作风，特别是力主抗战的政治主张，却遭到同僚的嫉恨和最高统治阶层的打击。宋孝宗淳熙八年（公元1181年），他被弹劾罢官，回到带湖家居，过着投闲置散的退隐生活。辛弃疾一直重视农业生产和同情民间疾苦，这首词正作于辛稼轩闲居上饶带湖期间。
此词着意描写黄沙岭的夜景。明月清风，疏星稀雨，鹊惊蝉鸣，稻花飘香，蛙声一片。词从视觉、听觉和嗅觉三方面抒写夏夜的山村风光。情景交融，优美如画。恬静自然，生动逼真。是宋词中以农村生活为题材的佳作。', '西江月：唐教坊曲名，后用作词牌名。调名取自李白《苏台览古》“只今唯有西江月，曾照吴王宫里人”。西江是长江的别称，调咏吴王西施的故事。又名《白蘋香》、《步虚词》、《晚香时候》、《玉炉三涧雪》、《江月令》。双调五十字，平仄两协。后阕字句作法与前阕相同。
黄沙道：指的是从江西省上饶县黄沙岭黄沙村的茅店到大屋村的黄沙岭之间约二十公里的乡村道路，南宋时是一条直通上饶古城的比较繁华的官道，东到上饶，西通江西省铅（yán）山县。
“明月别枝惊鹊”句：明亮的月光惊醒了睡在树枝上的喜鹊。语出宋·苏轼《杭州牡丹开时，仆犹在常、润，周令作诗见寄，次其韵，复次一首送赴阙·其二》诗：“天静伤鸿犹戢翼，月明惊鹊未安枝”。别枝，斜枝。
“七八个星天外，两三点雨山前”句：五代十国后蜀·何光远《鉴诫录·卷五·容易格》：“王蜀卢侍郎延让吟诗，多著寻常容易言语，时辈称之为高格。……然于数篇见境尤妙，有《松门寺》云：‘山寺取凉当夏夜，共僧蹲坐石阶前。两三条电欲为雨，七八个星犹在天。衣汗稍停床上扇，茶香时拨涧中泉。通宵听论莲华义，不藉松窗一觉眠。’”
茅店：茅草盖的乡村客店。
社：土地神庙。
社林：土地庙附近的树林。古时，村有社树，为祀神处，故曰“社林”。
溪桥：一作“溪头”。
忽见（xiàn）：忽然出现。见，同“现”，显现、出现。', '天边的明月升上了树梢，惊飞了栖息在枝头的喜鹊。清凉的晚风仿佛传来了远处的蝉叫声。在稻花的香气里，人们谈论着丰收的年景，耳边传来一阵阵青蛙的叫声，好像在说着丰收年。
天空中轻云漂浮，闪烁的星星时隐时现，山前下起了淅淅沥沥的小雨，从前那熟悉的茅店小屋依然坐落在土地庙附近的树林中，山路一转，曾经那记忆深刻的溪流小桥呈现在眼前。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74e90f8fda556504daac", "shortContent": "辛弃疾是南宋杰出的豪放派词人。他的风格以沉雄激越著称，但又不拘一格，在慷慨纵横之外，还有淡泊潇洒的一面。\n这首词是辛弃疾中年时代经过黄沙岭道上写的几篇作品之一。黄沙岭在江西上饶县西四十里，岭高约十五丈，深而敞豁，可容百人。下有两泉，水自石中流出，可溉田十余亩（见《上饶县志》）。宋孝宗淳熙八年（1181）冬，词人被奸佞中伤、弹劾以致罢官后，就开始在上饶家居，一直住了十五年左右。这中间虽然曾短期出仕，...", "authors": ["吴调公"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ebdbb8b379ee0a0314", "shortContent": "辛弃疾是南宋一位杰出的豪放派词人。他的风格以沉雄激越著称。但人生道路既然多歧，作家的巨大艺术熔炉又丰富多彩，这就必然出现卓越作家不拘一格的艺术风格，既有其主调而又有其变调的风格。因此辛弃疾在慷慨纵横之外，还有其淡泊潇洒的一面。\n这一首词是辛弃疾中年时代经过黄沙岭道上写的几篇作品之一。黄沙岭在江西上饶县西四十里，岭高约十五丈，深而敞豁，可容百人。下有两泉，水自石中流出，可溉田十余亩（见《上饶县志》）...", "authors": ["吴调公"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255eebf5e0fdea508e8", "shortContent": "辛弃疾是南宋一位杰出的豪放派词人。他的风格以沉雄激越著称。但人生道路既然多歧，作家的巨大艺术熔炉又丰富多彩，这就必然出现卓越作家不拘一格的艺术风格，既有其主调而又有其变调的风格。因此辛弃疾在慷慨纵横之外，还有其淡泊潇洒的一面。\n\n这一首词是辛弃疾中年时代经过黄沙岭道上写的几篇作品之一。黄沙岭在江西上饶县西四十里，岭高约十五丈，深而敞豁，可容百人。下有两泉，水自石中流出，可溉田十余亩（见《上饶县志》...", "authors": ["吴调公"], "pressName": "上海辞书出版社"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312704773206168b2e021cb", "shortContent": "这首词是辛弃疾被贬官闲居江西上饶时所作，他描写的是黄沙岭的夜景。黄沙岭位于上饶县城西四十里，岭高约十五丈，岭下有两泉，泉水从石中流出，可灌溉农田十余亩，辛弃疾谪居上饶期间，曾多次来此游览。\n\n词的上片，写夏夜的农村景象。“明月别枝惊鹊，清风半夜鸣蝉”，天边的明月慢慢地升到了树梢，月光之下，栖息在枝头的喜鹊受惊飞走，清凉的晚风中传来了欢悦的蝉鸣声。风、月、鹊、蝉，这些再平常不过的夏日景物，经过词人的...", "authors": ["陈庆之"], "pressName": "崇文书局"}, {"bookId": "64688f9830675327e19962ff", "bookTitle": "辛弃疾词鉴赏辞典（珍藏本）", "articleId": "64697799e49f46528ab8d328", "shortContent": "辛弃疾是南宋杰出的豪放派词人。他的风格以沉雄激越著称，但又不拘一格，在慷慨纵横之外，还有淡泊潇洒的一面。\n这首词是辛弃疾中年时代经过黄沙岭道上写的几篇作品之一。黄沙岭在江西上饶西四十里，岭高约十五丈，深而敞豁，可容百人。下有两泉，水自石中流出，可溉田十余亩（见《上饶县志》）。宋孝宗淳熙八年(1181)冬，词人被奸佞中伤、弹劾以致罢官后，就开始在上饶家居，一直住了十五年左右。这中间虽然曾短期出仕，但...", "authors": ["吴调公"], "pressName": "上海辞书出版社"}]', '唐圭璋《唐宋词选注》：作者以宁静的笔调描写了充满着活跃气氛的夏夜。一路行来，有清风、明月、疏星、微雨，也有鹊声、蝉声，还闻到了稻花香。走得久了，忽然看到那家熟识的小店，可以进去歇歇脚，愉悦之情，油然而生。
艾治平《宋词名篇赏析》：这是一首笔调灵活，不假雕琢，不事堆砌，语浅味永，摹写逼真的佳作，是一幅颇有审美价值的淡墨画，充满着农村生活气息的夏夜素描。
杨忠《辛弃疾词选译》：词中围绕着夜行的特点，展现出夏夜乡村田野的幽美景色及作者对丰收年景的由衷喜悦。', 'indent', 1413206321, '57b8fe02128fe10054c97529', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10415, '西江月', NULL, 94, 4, 2, 0, '宋江', NULL, 10106, '57eb451d0e3dd900583b5e4a', '宋', 'ci', '词', 'http://baike.baidu.com/view/4765118.htm', '', '自幼曾攻经史，长成亦有权谋。恰如猛虎卧荒丘，潜伏爪牙忍受。
不幸刺文双颊，那堪配在江州。他年若得报冤仇，血染浔阳江口。', '宋江是北宋农民起义的领袖。在《全宋词》中，宋江词存二首，一首是感伤、惆怅的《念奴娇》，另一就是这首充满豪情的《西江月》。该词格调高昂激越。写作手法是由低到高、由柔到刚循序渐进地陈述与抒发，虽然语言通俗明白如话，毫无文饰，但难得的是真情实志发自心底，没有丝毫矫揉之气，读其词如见其人。', '刺文：古代刑罚的一种，在犯人脸上刺刻文字或标记，押送边疆服役或充军。', '', NULL, '', 'indent', 1364242184, '57b8be707db2a2005425a8eb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10032, '步出夏门行 · 其四 · 龟虽寿', NULL, 585, 29, 2, 11, '曹操', NULL, 10012, '57b902df5bbb50005b7835f1', '汉', 'shi', '诗', 'http://baike.baidu.com/view/130633.htm', '', '神龟虽寿，犹有竟时；
腾蛇乘雾，终为土灰。
老骥伏枥，志在千里；
烈士暮年，壮心不已。
盈缩之期，不但在天；
养怡之福，可得永年。
幸甚至哉！歌以咏志。', '《龟虽寿》是东汉曹操的《步出夏门行》四章中的最后一章。作品富于哲理，阐发了诗人的人生态度。曹操刚击败袁绍、袁术兄弟二人，充满建功立业的豪情壮志。', '「神龟虽寿，犹有竟时」句：神龟虽能长寿，但也有死亡的时候。神龟，传说中的通灵之龟，能活几千岁。寿，长寿。
竟：终结，这里指死亡。
「腾蛇乘雾，终为土灰」句：腾蛇即使能乘雾升天，最终也得死亡，变成灰土。腾蛇，一作“螣蛇”，传说中与龙同类的神物，能乘云雾升天。
骥（jì）：良马，千里马。
伏：趴，卧。
枥（lì）：马槽。
烈士：有远大抱负的人。
暮年：晚年。
已：停止。
盈缩：指人的寿命长短。盈，满，引申为长。缩，亏，引申为短。
但：仅，只。
养怡：指调养身心，保持身心健康。怡，愉快、和乐。
永年：长寿，活得长。永，长久。
幸甚至哉，歌以咏志：两句是附文，跟正文没关系，只是抒发作者感情，是乐府诗的一种形式性结尾。', '神龟虽然十分长寿，但生命终究会有结束的一天；腾蛇尽管能腾云乘雾飞行，但终究也会死亡化为土灰。年老的千里马虽然伏在马槽旁，雄心壮志仍是驰骋千里；壮志凌云的人士即便到了晚年，奋发思进的心也永不止息。人寿命长短，不只是由上天决定；调养好身心，就定可以益寿延年。真是幸运极了，用歌唱来表达自己的志向吧。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecc9903572034f65a94e1", "shortContent": "南朝钟嵘写了一部《诗品》，品评诗人，区分第等，把曹操的诗置于下品。可是，曹操的诗却有一种震撼人心的巨大力量，使后代无数英雄志士为之倾倒若狂。据《世说新语》记载：东晋时代重兵在握的大将军王敦，每酒后辄咏曹操“老骥伏枥，志在千里。烈士暮年，壮心不已”。以如意击打唾壶为节，壶口尽缺。为什么理论家的眼光同读者的赏爱如此大不相同呢？这是一个颇为发人深思的问题。\n王大将军击节赞赏的诗，是曹操乐府诗《步出夏门行...", "authors": ["张铁明"], "pressName": "上海辞书出版社"}, {"bookId": "64605c895b7b0d4f45fe6e6e", "bookTitle": "三曹诗文鉴赏辞典", "articleId": "646df3fe30675327e1b09d24", "shortContent": "南朝钟嵘写了一部《诗品》，品评诗人，区分第等，把曹操的诗置于下品。可是，曹操的诗却有一种震撼人心的巨大力量，使后代无数英雄志士为之倾倒若狂。据《世说新语》记载：东晋时代重兵在握的大将军王敦，每酒后辄咏曹操“老骥伏枥，志在千里。烈士暮年，壮心不已”，以如意击打唾壶为节，壶口尽缺。为什么理论家的眼光同读者的赏爱如此大不相同呢？这是一个颇为发人深思的问题。\n王大将军击节赞赏的诗，是曹操乐府诗《步出夏门行...", "authors": ["张铁明"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f633d45e4710056f1ec07", "shortContent": "南朝钟嵘写了一部《诗品》，品评诗人，区分第等，把曹操的诗置于下 品。可是，曹操的诗却有一种震撼人心的巨大力量，使后代无数英雄志士 为之倾倒若狂。据《世说新语》记载:东晋时代重兵在握的大将军王敦， 每酒后辄咏曹操“老骥伏枥，志在千里。烈士暮年，壮心不已”。以如意击 打唾壶为节，壶口尽缺。为什么理论家的眼光同读者的赏爱如此大不相 同呢?这是一个颇为发人深思的问题。\n\n王大将军击节赞赏的诗，是曹操乐府诗...", "authors": ["张铁明"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6471f5c37f27182da38bfba9", "shortContent": "曹操的诗有一种震撼人心的巨大力量，使后代无数英雄志士为之倾倒若狂。据《世说新语》记载：东晋时代重兵在握的大将军王敦，每酒后辄咏曹操“老骥伏枥，志在千里；烈士暮年，壮心不已”，以如意击打唾壶为节，壶口尽缺。\n\n王大将军击节赞赏的诗，是曹操乐府诗《步出夏门行》的第四章——《龟虽寿》。曹操当时击败袁绍父子，平定北方乌桓，踌躇满志，乐观自信，便写下这一组诗，抒写胸怀建功立业的豪情壮志。此时曹操已经五十三岁...", "authors": ["张铁明"], "pressName": "上海辞书出版社"}]', '', 'center', 1413196194, '57b4545a7db2a200546caec8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10033, '山窗听雪敲竹', NULL, 209, 253, 1, 2, '高濂', NULL, 10013, '57ba82a88ac2470063045693', '明', 'wen', '文', 'http://baike.baidu.com/view/632486.htm', '', '飞雪有声，惟在竹间最雅。山窗寒夜时，听雪洒竹林，淅沥萧萧，连翩瑟瑟，声韵悠然，逸我清听。忽尔回风交急，折竹一声，使我寒毡增冷。暗想金屋人欢，玉笙声醉，恐此非尔所欢。', '', NULL, NULL, NULL, NULL, 'indent', 1448022892, '57b959a50a2b58005c95590e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10036, '桃花源记', NULL, 976, 99, 1, 15, '陶渊明', NULL, 10011, '57b8fa07c4c97100558ef104', '晋', 'wen', '文', 'http://baike.baidu.com/subview/94220/4881993.htm', '《桃源经》曰：桃源山在县南一十里，西北乃沅水曲流，而南有障山，东带钞锣溪，周回三十有二里，所谓桃花源也。', '晋太元中，武陵人捕鱼为业。缘溪行，忘路之远近。忽逢桃花林，夹岸数百步，中无杂树，芳草鲜美，落英缤纷。渔人甚异之，复前行，欲穷其林。
林尽水源，便得一山。山有小口，仿佛若有光。便舍船，从口入。初极狭，才通人。复行数十步，豁然开朗。土地平旷，屋舍俨然，有良田、美池、桑竹之属。阡陌交通，鸡犬相闻。其中往来种作，男女衣着，悉如外人。黄发垂髫，并怡然自乐。
见渔人，乃大惊，问所从来。具答之。便要还家，设酒杀鸡作食。村中闻有此人，咸来问讯。自云先世避秦时乱，率妻子邑人来此绝境，不复出焉，遂与外人间隔。问今是何世，乃不知有汉，无论魏晋。此人一一为具言所闻，皆叹惋。余人各复延至其家，皆出酒食。停数日，辞去。此中人语云：“不足为外人道也。”
既出，得其船，便扶向路，处处志之。及郡下，诣太守，说如此。太守即遣人随其往，寻向所志，遂迷，不复得路。
南阳刘子骥，高尚士也，闻之，欣然规往。未果，寻病终。后遂无问津者。', '本文选自《陶渊明集》，是陶渊明的代表作之一，也是《桃花源诗》的序言。借武陵渔人行踪这一线索，把现实和理想境界联系起来，通过对桃花源的安宁和乐、自由平等生活的描绘，表现了作者追求美好生活的理想和对现实社会的不满。', '太元：东晋孝武帝的年号（公元376年-公元397年）。
武陵：郡名，今武陵山区或湖南常德一带。
为业：把……作为职业，以……为生。为，作为。
缘：顺着、沿着。
行：行走这里指划船。
远近：偏义复词，仅指远。
忽逢：忽然遇到。逢，遇见。
夹岸：两岸。
杂：别的，其他的。
鲜美：鲜艳美丽。
落英：落花。一说，初开的花。
缤纷：繁多而纷乱的样子。
异之：以之为异，即对此感到诧异。异，意动用法，形作动，以……为异，对……感到诧异，认为……是奇异的。之，代词，指见到的景象。
复：又、再。
前：名词活用为状语，向前。
欲：想要。
穷：尽，形容词用做动词，这里是“走到……的尽头”的意思。
林尽水源：林尽于水源，桃花林在溪水发源的地方就没有了。尽，完、没有了。
便：于是、就。
得：看到。
仿佛：隐隐约约，形容看得不真切的样子。
若：好像。
舍：舍弃，丢弃，
初：起初，刚开始。
才通人：仅容一人通过。才，副词，只。
行：行走。
豁然开朗：形容由狭窄幽暗突然变得宽阔明亮的样子。然，……的样子。豁然，形容开阔敞亮的样子；开朗，开阔明亮。
平：平坦。
旷：空阔；宽阔。
屋舍：房屋。
俨（yǎn）然：整齐的样子。
之：这。
属：类。
阡陌：田间小路。南北走向的叫阡，东西走向的叫陌。
交通：交错相通。
阡陌交通：田间小路交错相通。
鸡犬相闻：（村落间）能相互听见鸡鸣狗叫的声音。相闻，可以互相听到。
种作：耕种劳作的人。
衣着：穿着打扮，穿戴。
悉：全、都。
外人：桃花源以外的世人，下同。
黄发：旧说是长寿的象征，用以指老人。
垂髫（tiáo）：垂下来的头髮，用来指小孩子。髫，小孩垂下的短髮。
黄发垂髫：老人和小孩。
并：都。
怡然：愉快、高兴的样子。
乃大惊：就很惊讶。乃，于是、就；大，很，非常。
从来：从……地方来。
具：详细。
之：代词，指代桃源人所问问题。
要：通“邀”，邀请。
咸：副词，都、全。
问讯：询问消息、打听消息。
云：说。
先世：祖先。
率：率领。
妻子：指妻室子女，“妻”“子”是两个词。妻，指男子配偶；子，指子女。
邑人：同乡（县）的人。邑，古代区域单位。《周礼·地官·小司徒》：“九夫为井，四井为邑。”
绝境：与人世隔绝的地方。绝，绝处。
复：再、又。
焉：兼词，相当于“于之”，“于此”，从这里。
遂：就。
间隔：隔断，隔绝。
世：朝代。
乃：竟、竟然。
无论：不要说，（更）不必说。“无”“论”是两个词，不同于现代汉语里的“无论”。
为：对、向。
具言：详细地说出。
所闻：指渔人所知道的世事。闻，知道、听说。
叹惋：感叹、惋惜。惋，惊讶、惊奇。
余：其余，剩余。
延至：邀请到。延，邀请；至，到。
去：离开。
语：告诉。
不足：不必、不值得。
为：介词，向、对。
既：已经。
便扶向路：就顺着旧的路（回去）。扶，沿着、顺着；向，从前的、旧的。
处处志之：处处都做了标记。志，做标记；处处，到处。
及郡下：到了郡城。及，到达；郡，太守所在地，指武陵郡。
诣（yì）：拜访。
如此：像这样，指在桃花源的见闻。
寻向所志：寻找以前所做的标记。寻，寻找；向，先前；志，标记。
遂：终于。
得：取得、获得，文中是找到的意思。
高尚：品德高尚。
士：人士。
也：表判断。
欣然：高兴的样子。
规：计划。
未果：没有实现。果，实现。
寻：随即、不久。
终：死亡。
问津：问路，这里是访求、探求的意思。津，渡口。', '东晋太元年间，武陵郡有个人以打渔为生。一天，他顺着溪水行船，忘记了路程的远近。忽然遇到一片桃花林，生长在溪水的两岸，长达几百步，中间没有别的树，花草鲜嫩美丽，落花纷纷的散在地上。渔人对此（眼前的景色）感到十分诧异，继续往前行船，想走到林子的尽头。
桃林的尽头就是溪水的发源地，于是便出现一座山，山上有个小洞口，洞里隐隐约约有点光亮。于是他下了船，从洞口进去了。起初洞口很狭窄，仅容一人通过。又走了几十步，突然变得开阔明亮了。（呈现在他眼前的是）一片平坦宽广的土地，一排排整齐的房舍。还有肥沃的田地、美丽的池沼，桑树竹林之类的。田间小路交错相通，鸡鸣狗叫到处可以听到。人们在田野里来来往往耕种劳作，男女的穿戴跟桃花源以外的世人完全一样。老人和小孩们个个都安适愉快，自得其乐。
村里的人看到渔人，感到非常惊讶，问他是从哪儿来的。渔人详细地做了回答。村里有人就邀请他到自己家里去（做客）。设酒杀鸡做饭来款待他。村里的人听说来了这么一个人，就都来打听消息。他们自己说他们的祖先为了躲避秦时的战乱，领着妻子儿女和乡邻来到这个与人世隔绝的地方，不再出去，因而跟外面的人断绝了来往。他们问渔人现在是什么朝代，他们竟然不知道有过汉朝，更不必说魏晋两朝了。渔人把自己知道的事一一详尽地告诉了他们，听完以后，他们都感叹惋惜。其余的人各自又把渔人请到自己家中，都拿出酒饭来款待他。渔人停留了几天，向村里人告辞离开。村里的人对他说：“我们这个地方不值得对外面的人说啊！”
渔人出来以后，找到了他的船，就顺着旧路回去，处处都做了标记。到了郡城，到太守那里去，报告了这番经历。太守立即派人跟着他去，寻找以前所做的标记，终于迷失了方向，再也找不到通往桃花源的路了。
南阳人刘子骥是个志向高洁的隐士，听到这件事后，高兴地计划前往。但没有实现，不久因病去世了。此后就再也没有问桃花源路的人了。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccaa0ce818559d06469d", "shortContent": "《桃花源诗并记》，表现高尚美好的人类社会理想，是陶渊明晚年的代表作品。了解传统文化，这是必读之作。\n先读《记》文。从“晋太元中”到“豁然开朗”，可谓引子，叙述桃花源之被发现。此节文字已带出传奇色彩。“忘路之远近”，“忽逢桃花林”，“仿佛若有光”，“豁然开朗”等语，尤能状出奇异之感。间或写景亦很优美，“夹岸数百步，中无杂树，芳草鲜美，落英缤纷”，颇能引人入胜。从“土地平旷”到“不足为外人道也”，是中...", "authors": ["邓小军"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1df0f8fda5565061598", "shortContent": "在中国，素有“山川以人而胜”的传统，所谓“美不自美，因人而彰”，“地不自胜，惟人则鸣”。王勃之于滕王阁，李白之于敬亭山，崔颢之于黄鹤楼，柳宗元之于永州，范仲淹之于岳阳楼，欧阳修之于醉翁亭，苏轼之于黄冈赤壁，莫不如此。但他们写的都是实景，而桃源仙境却是虚构出来的。以一篇诗文虚构一个仙境而令游人神魂颠倒，在中外都是少有的。武陵桃源，原是鲜为人知的荒僻之地，自陶渊明作《桃花源诗并记》以后，始为文人墨客所...", "authors": ["臧维熙"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4547f27182da33f706b", "bookTitle": "陶渊明诗文鉴赏辞典", "articleId": "646aac82b6a81d0c530b9f2c", "shortContent": "在中国，素有“山川以人而胜”的传统，所谓“美不自美，因人而彰”，“地不自胜，惟人则鸣”。王勃之于滕王阁，李白之于敬亭山，崔颢之于黄鹤楼，柳宗元之于永州，范仲淹之于岳阳楼，欧阳修之于醉翁亭，苏轼之于黄冈赤壁，莫不如此。但他们写的都是实景，而桃源仙境却是虚构出来的。以一篇诗文虚构一个仙境而令游人神魂颠倒，在中外都是少有的。武陵桃源，原是鲜为人知的荒僻之地，自陶渊明作《桃花源诗并记》以后，始为文人墨客所...", "authors": ["臧维熙"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "647207425e6bb82b8cfc16f1", "shortContent": "陶渊明作诗，擅长白描，文体省净，语出自然，如大匠运斤，毫无斧凿之痕。金元好问谓之“一语天然万古新，豪华落尽见真醇”。《桃花源记》也具有这种艺术风格。它虽是虚构的世外仙境，但由于采用写实手法，虚景实写，给人以真实感，仿佛实有其人，真有其事。全文以武陵渔人行踪为线索，像小说一样描述了溪行捕鱼、桃源仙境、重寻迷路三段故事。第一段以“忘”“忽逢”“甚异”“欲穷”四个相承续的词语生动揭示出武陵渔人一连串的心...", "authors": ["臧维熙"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "6470a44ab5420e27678a6673", "shortContent": "《桃花源诗并记》，表现高尚美好的人类社会理想，是渊明晚年的代表 作品。了解传统文化，这是必读之作。\n\n先读《记》文。从“晋太元中”到“豁然开朗”，可谓引子，叙述桃花源之 被发现。此节文字已带出传奇色彩。“忘路之远近”，“忽逢桃花林”，“仿 佛若有光”，“豁然开朗”等语，尤能状出奇异之感。间或写景亦很优美， “夹岸数百步，中无杂树，芳草鲜美，落英缤纷”，颇能引人入胜。从“土地 平旷”到“不足为外人道...", "authors": ["邓小军"], "pressName": "上海辞书出版社"}]', '方东树《昭昧詹言》：情融乎内而深且长，景耀于外而真且实。
尤桐《西堂杂俎·三集·卷三·苍梧词序》：文生于情，情生于境。
钟嵘《诗品》：文体省净，殆无长语。笃意真古，辞兴婉惬，每观其文，想其人德。
刘熙载《艺概·书概》：笔性墨情，皆以其人之性情为本。', 'indent', 1359764014, '57b8e22c79bc44005b9df7ef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10037, '塞下曲 其二', NULL, 502, 341, 2, 8, '卢纶', NULL, 10014, '57b9c2f6c4c97100614832f4', '唐', 'shi', '诗', 'http://baike.baidu.com/view/11751679.htm', '', '林暗草惊风，将军夜引弓。
平明寻白羽，没在石棱中。', '此诗为卢纶组诗《塞下曲》第二首，写将军夜猎，见林深处风吹草动，以为是虎，便弯弓猛射。天亮一看，箭竟然射进一块石头中去了。通过这一典型情节，表现了将军的勇武。
首句写将军夜猎场所是幽暗的深林；当时天色已晚，一阵阵疾风刮来，草木为之纷披。这不但交代了具体的时间、地点，而且制造了一种气氛。右北平是多虎地区，深山密林是百兽之王的猛虎藏身之所，而虎又多在黄昏夜分出山，“林暗草惊风”，着一“惊”字，就不仅令人自然联想到其中有虎，呼之欲出，渲染出一片紧张异常的气氛，而且也暗示将军是何等警惕，为下文“引弓”作了铺垫。次句即续写射。但不言“射”而言“引弓”，这不仅是因为诗要押韵的缘故，而且因为“引”是“发”的准备动作，这样写能启示读者从中想象、体味将军临险是何等镇定自若，从容不迫。在一“惊”之后，将军随即搭箭开弓，动作敏捷有力而不仓皇，既具气势，而形象也益鲜明。
后二句写“没石饮羽”的奇迹，把时间推迟到翌日清晨（“平明”），将军搜寻猎物，发现中箭者并非猛虎，而是蹲石，令人读之，始而惊异，既而嗟叹，原来箭杆尾部装臵着白色羽毛的箭，竟“没在石棱中”，入石三分。这样写不仅更为曲折，有时间、场景变化，而且富于戏剧性。“石棱”为石的突起部分，箭头要钻入殊不可想象。神话般的夸张，为诗歌形象涂上一层浪漫色彩，读来特别尽情够味，只觉其妙，不以为非。', '惊风：突然被风吹动。
引弓：拉弓，开弓，这里包含下一步的射箭。
平明：天刚亮的时候。白羽：箭杆后部的白色羽毛，这里指箭。
没（mò）：陷入，这里是钻进的意思。石棱：石头的棱角。也指多棱的山石。', '林中昏暗风吹草动令人惊，将军夜中搭箭拉弓显神勇。
天明寻找昨晚射的白羽箭，箭头深深插入巨大石块中。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ba03572034f659e4fa", "shortContent": "卢纶《塞下曲》共六首一组，分别写发号施令、射猎破敌、奏凯庆功等等军营生活。因为是和张仆射之作（诗题一作“和张仆射塞下曲”），语多赞美之意。\n此为组诗的第二首，写将军夜猎，见林深处风吹草动，以为是虎，便弯弓猛射。天亮一看，箭竟然射进一块石头中去了。通过这一典型情节，表现了将军的勇武。诗的取材，出自《史记·李将军列传》。据载，汉代名将李广猿臂善射，在任右北平太守时，就有这样一次富于戏剧性的经历：“广出...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a92", "shortContent": "卢纶《塞下曲》共六首一组，分别写发号施令、射猎破敌、奏凯庆功等等军营生活。因为是和张仆射之作（诗题一作“和张仆射塞下曲”），语多赞美之意。\n\n此为组诗的第二首，写将军夜猎，见林深处风吹草动，以为是虎，便弯弓猛射。天亮一看，箭竟然射进一块石头中去了。通过这一典型情节，表现了将军的勇武。诗的取材，出自《史记·李将军列传》。据载，汉代名将李广猿臂善射，在任右北平太守时，就有这样一次富于戏剧性的经历：“广...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270f7f2af4e09d55b6826", "shortContent": "“塞下曲”是唐代诗人写得很多的乐府旧题。卢纶《塞下曲》组诗共六首，有说是题目应为《和张仆射塞下曲》，这是第二首。首句交代了具体的时间、地点。在夜暗星稀的晚上，树林里的光线更加黯淡，忽然一阵疾风吹来，草木为之惊颤。密林中有可能是隐藏着猛虎，也有可能是埋伏着敌军，总之是周围有危险存在，随时都有可能发生。明写“草惊”，其实是人惊，渲染了一种异常紧张的气氛。面对这种危急情况，将军没有表现出丝毫惊慌，而是立...", "authors": ["陈鹏"], "pressName": "崇文书局"}]', '《载酒园诗话又编》：《塞下曲》六首俱有盛唐之音，“平明寻白羽，没在石棱中”一章尤佳。人顾称“欲将轻骑逐，大雪满弓刀”，虽亦矫健，然殊有逗遛之态，何如前语雄壮！
《诗法易简录》：暗用李广事，言外有边防严肃、军威远振之意。
《养一斋诗话》：诗之妙全以先天神运，不在后天迹象。……卢纶“林暗草惊风”，起句便全是黑夜射虎之神，不至“将军夜引弓”句矣。大抵能诗者无不知此妙，低手遇题，乃写实迹，故极求清脱，而终欠浑成。', 'center', 1417644092, '57b916c7df0eea00633596b6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10038, '水龙吟 · 登建康赏心亭', NULL, 623, 793, 7, 7, '辛弃疾', NULL, 10003, '57b8ed682e958a005fa4d096', '宋', 'ci', '词', 'http://baike.baidu.com/view/384027.htm', '', '楚天千里清秋，水随天去秋无际。遥岑远目，献愁供恨，玉簪螺髻。落日楼头，断鸿声里，江南游子。把吴钩看了，栏杆拍遍，无人会，登临意。
休说鲈鱼堪脍，尽西风，季鹰归未？求田问舍，怕应羞见，刘郎才气。可惜流年，忧愁风雨，树犹如此！倩何人唤取，红巾翠袖，揾英雄泪？', '赏心亭是南宋建康城上的一座亭子。本词作于淳熙元年的秋季，作者南归十二年后，沉滞下僚，满腹牢骚，无处宣泄，遂于再登赏心亭之际，眺望楚地大好河山，慷慨悲歌。
全词就登临所见挥发，由写景进而抒情，情和景融合无间，将内心的感情写得既含蓄而又淋漓尽致。虽然出语沉痛悲愤，但整首词的基调还是激昂慷慨的，表现出辛词豪放的风格特色。', '登建康赏心亭：《花菴词选》作「赏心亭」。
建康：六朝时期的京城，今江苏南京市。南宋为府名，建炎三年（西元一一二九年）改江宁府置，治所在今南京市。
赏心亭：《景定建康志·卷二十二》：「赏心亭在下水门之城上，下临秦淮，尽观览之胜。丁晋公谓建。景定元年，亭燬。马公光祖重建。」
遥岑（cén）远目：唐·韩愈《城南联句》：「遥岑出寸碧，远目增双明。」远目，四卷本甲集作「远日」。
玉簪（zān）螺髻（jì）：玉做的簪子，像海螺形状的发髻，这里比喻高矮和形状各不相同的山岭。唐·韩愈《送桂州严大夫同用南字》：「江作青罗带，山如碧玉簪。」唐·皮日休《缥缈峰》诗：「似将青螺髻，撒在明月中。」
落日楼头：唐·杜甫《越王楼歌》：「山头落日半轮明。」宋·柳永《玉蝴蝶》词：「断鸿声里，立尽残阳。」
断鸿：失群的孤雁。
吴钩：古代吴地制造的一种宝刀。这里应该是以吴钩自喻，空有一身才华，但是得不到重用。东汉·赵晔《吴越春秋·卷四·阖闾内传·阖闾元年》：「阖闾既宝莫耶，复命于国中作金钩。令曰：『能为善钩者，赏之百金。』吴作钩者甚众。而有人贪王之重赏也，杀其二子，以血舋金，遂成二钩，献于阖闾，诣宫门而求赏。王曰：『为钩者众而子独求赏，何以异于众夫子之钩乎？』作钩者曰：『吾之作钩也，贪而杀二子，舋成二钩。』王乃举众钩以示之：『何者是也？』王钩甚多，形体相类，不知其所在。于是钩师向钩而呼二子之名：『吴鸿，扈稽，我在于此，王不知汝之神也。』声绝于口，两钩俱飞著父之胸。吴王大惊，曰：『嗟乎！寡人诚负于子。』乃赏百金。遂服而不离身。」宋·沈括《梦溪笔谈·卷十九·器用》：「唐人诗多有言吴钩者。吴钩，刀名也，刃弯。今南蛮用之，谓之『葛党刀』。」唐·杜甫《后出塞》诗：「少年别有赠，含笑看吴钩。」唐·李贺《南园》：「男儿何不带吴钩，收取关山五十州。」
栏杆拍遍：北宋·王辟之《渑水燕谈录·卷四·忠孝》：「刘孟节先生概，青州寿光人。少师种放。笃古好学，酷嗜山水，而天姿绝俗，与世相龃龉，故久不仕。晚得一名，亦不去为吏。庆历中，朝廷以海上岠嵎山地震逾年不止，遣使访遗逸。安抚使以先生名闻，诏命之官，先生亦不受就。青之南有冶原，昔欧冶子铸剑之地，山奇水清，旁无人烟，丛筠古木，气象幽绝。富韩公之镇青也，知先生久欲居其间，为筑室泉上，为诗并序以饯之曰：『先生已归隐，山东人物空。』且言先生有志于名，不幸无位，不克施于时，著书以见志。谓先生虽隐，其道与日月雷霆相震耀。其后，范文正公、文潞公皆优礼之，欲荐之朝廷，先生恳祈，亦不敢强，以成其高。先生少时，多寓居龙兴僧舍之西轩，往往凭栏静立，怀想世事，吁唏独语，或以手拍栏干。尝有诗曰：『读书误我四十年，几回醉把栏干拍。』司马温公《诗话》所载者是也。」
「无人会、登临意。」句：北宋僧文瑩《湘山野录·卷上》：「金陵赏心亭，丁晋公出镇日重建也。秦淮绝致，清在轩槛。取家箧所宝《袁安卧雪图》张于亭之屏，乃唐周昉绝笔。凡经十四守，虽极爱而不敢辄觊（jì）。偶一帅遂窃去，以市画芦雁掩之。后君玉王公琪复守是郡，登亭，留诗曰：『千里秦淮在玉壶，江山清丽壮吴都。昔人已化辽天鹤，旧画难寻《卧雪图》。冉冉流年去京国，萧萧华发老江湖。残蝉不会登临意，又噪西风入座隅。』此诗与江山相表里，为贸画者之萧斧也。」
「休说鲈鱼堪脍，尽西风、季鹰归未？」句：用西晋张翰典。《晋书·卷九十二·〈文苑·张翰传〉》：「张翰，字季鹰，吴郡吴人也。……翰有清才，善属文，而纵任不拘，时人号为『江东步兵。』……翰因见秋风起，乃思吴中菰菜、莼羹、鲈鱼脍，曰：「人生贵得适志，何能羁宦数千里以要名爵乎！」遂命驾而归。」《世说新语·识鉴》：「张季鹰辟齐王东曹掾，在洛，见秋风起，因思吴中菰菜、莼羹、鲈鱼脍，曰：『人生贵得适意尔，何能羁宦数千里以要名爵？』遂命驾便归。俄而齐王败，时人皆谓见机。」后来的文人将思念家乡称为莼鲈之思。
「求田问舍，怕应羞见，刘郎才气。」句：《三国志·卷七·〈魏书·陈登传〉》：「陈登者，字元龙，在广陵有威名。又掎角吕布有功，加伏波将军，年三十九卒。后许汜与刘备并在荆州牧刘表坐，表与备共论天下人，汜曰：『陈元龙湖海之士，豪气不除。』备谓表曰：『许君论是非？』表曰：『欲言非，此君为善士，不宜虚言；欲言是，元龙名重天下。』备问汜：『君言豪，宁有事邪？』汜曰：『昔遭乱，过下邳，见元龙。元龙无客主之意，久不相与语，自上大床卧，使客卧下床。』备曰：『君有国士之名，今天下大乱，帝主失所，望君忧国忘家，有救世之意，而君求田问舍，言无可采，是元龙所讳也，何缘当与君语？如小人：欲卧百尺楼上，卧君于地，何但上下床之间邪？』表大笑。备因言曰：『若元龙文武胆志，当求之于古耳，造次难得比也。』」求田问舍，置地买房；刘郎，刘备；才气，胸怀、气魄。
流年：流逝的时光。
忧愁风雨：宋·苏轼《满庭芳》词：「百年里，浑教是醉，三万六千场。思量，能几许，忧愁风雨，一半相妨」。风雨，比喻飘摇的国势。
树犹如此：出自北周诗人庾信《枯树赋》：「树犹如此，人何以堪！」又典出《世说新语·言语》：「桓公北征，经金城，见前为琅邪时种柳，皆已十围，慨然曰：『木犹如此，人何以堪！』攀枝执条，泫然流泪。」此处以「树」代「木」，抒发自己不能抗击敌人、收复失地，虚度时光的感慨。
倩（qìng）：请托。
红巾翠袖：女子装饰，代指女子。红巾，四卷本作「盈盈」。
揾（wèn）：擦拭。', '楚天千里辽阔一派凄清秋色，长江水随天流去秋色无边际。极目眺望北国崇山峻岭的风景，他们仿佛都在传送忧怨仇恨，就好似碧玉发簪和螺形发髻。夕阳西下之时落日斜挂楼头，孤雁悲啼声里游子悲愤压抑，吴钩把玩不已拍遍九曲栏杆，没人能理会我登楼远眺之心。
别提家乡的鲈鱼肉精细味美，尽管秋风吹不会像季鹰不归？更不想许汜只顾谋私利。那将羞于见雄才大气的刘备。借时光如水忧愁国势如风雨，树犹如此。请何人人去换来啊？就让那红巾翠袖多情歌女，为我擦去英雄失志时的热泪。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74e634a8757d5a0d9ed5", "shortContent": "这首词作于乾道四年至六年（1168—1170）间建康通判任上。这时作者南归已八九年了，却投闲置散，不得一遂报国之愿。值此登临周览之际，一抒郁结心头的悲愤之情。\n建康（今江苏南京）是东吴、东晋、宋、齐、梁、陈六个朝代的都城。赏心亭是南宋建康城上的亭子。据《景定建康志》记载：“赏心亭在（城西）下水门城上，下临秦淮，尽观赏之胜。”\n这首词，上片大段写景：由水写到山，由无情之景写到有情之景，很有层次。开头...", "authors": ["夏承焘", "吴无闻"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5e80ce818559d063bfe", "shortContent": "这首词作于乾道四年至六年（1168—1170）间建康通判任上。这时作者南归已八九年了，却投闲置散，不得一遂报国之愿。值此登临周览之际，一抒郁结心头的悲愤之情。\n建康（今江苏南京）是东吴、东晋、宋、齐、梁、陈六个朝代的都城。赏心亭是南宋建康城上的亭子。据《景定建康志》记载：“赏心亭在（城西）下水门城上，下临秦淮，尽观赏之胜。”\n这首词，上片大段写景：由水写到山，由无情之景写到有情之景，很有层次。开头...", "authors": ["夏承焘", "吴无闻"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255eebf5e0fdea508e2", "shortContent": "这首词作于乾道四年至六年（1168—1170）间建康通判任上。这时作者南归已八、九年了，却投闲置散，不得一遂报国之愿。值此登临周览之际，一抒郁结心头的悲愤之情。\n\n建康（今江苏南京）是东吴、东晋、宋、齐、梁、陈六个朝代的都城。赏心亭是南宋建康城上的亭子。据《景定建康志》记载：“赏心亭在（城西）下水门城上，下临秦淮，尽观赏之胜。”\n\n这首词，上片大段写景：由水写到山，由无情之景写到有情之景，很有层次...", "authors": ["夏承焘", "吴无闻"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f4e73206168b2e020fa", "shortContent": "历史上的辛弃疾是一位奇人，更是一位英雄。他将生命的全部热情投入收复故土、北伐中原的宏大志业之中，最终收获的却只是英雄失志、报国无门的极度苦闷。在岁月流逝、壮志难酬的压抑与不平中，他将自己的一腔幽愤付诸手中的那支笔。\n这首《水龙吟》所曲折呈现的，正是一位失路英雄的抑郁与不平。一般认为，这首词创作于宋孝宗乾道五年（1169）辛弃疾任建康府通判时。也有人认为，该词作于孝宗淳熙元年（1174）辛弃疾任江东...", "authors": ["江俊伟"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312704773206168b2e021c6", "shortContent": "历史上的辛弃疾是一位奇人，更是一位英雄。他将生命的全部热情投入收复故土、北伐中原的宏大志业之中，最终收获的却只是英雄失志、报国无门的极度苦闷。在岁月流逝、壮志难酬的压抑与不平中，他将自己的一腔幽愤付诸手中的那支笔。\n\n这首《水龙吟》所曲折呈现的，正是一位失路英雄的抑郁与不平。一般认为，这首词创作于宋孝宗乾道五年（1169）辛弃疾任建康府通判时。也有人认为，该词作于孝宗淳熙元年（1174）辛弃疾任江...", "authors": ["江俊伟"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271ffc305cf080181711c", "shortContent": "历史上的辛弃疾是一位奇人，更是一位英雄。他将生命的全部热情投入收复故土、北伐中原的宏大志业之中，最终收获的却只是英雄失志、报国无门的极度苦闷。在岁月流逝、壮志难酬的压抑与不平中，他将自己的一腔幽愤付诸手中的那支笔。\n这首《水龙吟》所曲折呈现的，正是一位失路英雄的抑郁与不平。一般认为，这首词创作于宋孝宗乾道五年（1169）辛弃疾任建康府通判时。也有人认为，该词作于孝宗淳熙元年（1174）辛弃疾任江东...", "authors": ["江俊伟"], "pressName": "崇文书局"}, {"bookId": "64688f9830675327e19962ff", "bookTitle": "辛弃疾词鉴赏辞典（珍藏本）", "articleId": "6468ab4945e4710056d50c2b", "shortContent": "这首词作于乾道四年至六年(1168—1170)间建康通判任上。这时作者南归已八九年了，却投闲置散，不得一遂报国之愿。值此登临周览之际，一抒郁结心头的悲愤之情。\n\n建康（今江苏南京）是东吴、东晋、宋、齐、梁、陈六个朝代的都城。赏心亭是南宋建康城上的亭子。据《景定建康志》记载：“赏心亭在（城西）下水门城上，下临秦淮，尽观赏之胜。”\n\n这首词，上片大段写景：由水写到山，由无情之景写到有情之景，很有层次。...", "authors": ["夏承焘　吴无闻"], "pressName": "上海辞书出版社"}]', '黄梨庄：辛稼轩当弱宋末造，负管、乐之才，不能尽展其用，一腔忠愤，无处发泄；观其与陈同父抵掌谈论，是何等人物？故其悲歌慷慨、抑郁无聊之气，一寄之于其词。
谭復堂《谭评词辩》：裂竹之声，何尝不潜气内转。
陈亦峰《白雨斋词话》：落落数语，不数王粲《登楼赋》。', 'indent', 1359764642, '57aca131d342d30057fdc441', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10039, '观书有感', NULL, 611, 1475, 2, 16, '朱熹', NULL, 10015, '57b936ccc4c971005590f2c8', '宋', 'shi', '诗', 'http://baike.baidu.com/view/94914.htm', '', '【其一】
半亩方塘一鉴开，天光云影共徘徊。
问渠那得清如许？为有源头活水来。
【其二】
昨夜江边春水生，艨艟巨舰一毛轻。
向来枉费推移力，此日中流自在行。', '这是一首借景喻理的名诗。全诗以方塘作比喻，形象地表达了一种微妙难言的读书感受。池塘并不是一泓死水，而是常有活水注入，因此像明镜一样，清澈见底，映照着天光云影。这种情景，同一个人在读书中搞通问题、获得新知而大有收益、提高认识时的情形颇为相似。这首诗所表现的读书有悟、有得时的那种灵气流动、思路明畅、精神清新活泼而自得自在的境界，正是作者作为一位大学问家的切身的读书感受。
诗中所表达的这种感受虽然仅就读书而言，却寓意深刻，内涵丰富，可以做广泛的理解。特别是“问渠那得清如许，为有源头活水来”两句，借水之清澈，是因为有源头活水不断注入，暗示人要心灵澄明，就得认真读书，时时补充新知识。因此人们常常用来比喻不断学习新知识，才能达到新境界。', '方塘：又称半亩塘，在福建尤溪城南郑义斋馆舍（后为南溪书院）内。朱熹父亲朱松与郑交好，故尝有《蝶恋花·醉宿郑氏别墅》词云：“清晓方塘开一境。落絮如飞，肯向春风定。”
鉴：一说为古代用来盛水或冰的青铜大盆。镜子；也有学者认为镜子。指像鉴（镜子）一样可以照人。
天光云影共徘徊：天的光和云的影子反映在塘水之中，不停地变动，犹如人在徘徊。
徘徊：来回移动。
为：因为。
渠：它，第三人称代词，这里指方塘之水。
那得：怎么会。那，怎么。
清如许：这样清澈。
如：如此、这样。
清：清澈。
源头活水：比喻知识是不断更新和发展的，从而不断积累，只有在人生的学习中不断地学习、运用和探索，才能使自己永保先进和活力，就像水源头一样。
艨艟:也作古代攻击性很强的战舰名，这里指大船。
一毛轻：像一片羽毛一般轻盈。
向来：原先，指春水上涨之前。
推移力：指浅水时行船困难，需人推挽而行。
中流：河流的中心。', '【其一】
半亩大的方形池塘像一面镜子一样打开，清澈明净，
天光、云影在水面上闪耀浮动。
要问池塘里的水为何这样清澈呢？
是因为有永不枯竭的源头源源不断地为它输送活水。
【其二】
昨天夜晚江边的春水大涨，那艘庞大的船就像一根羽毛一样轻。
以往花费许多力量也不能推动它，今天在水中间却能自在地移动。', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea7380ce818559d05e4b1", "shortContent": "从题目看，这两首诗是谈“观书”体会的，意在讲道理、发议论；弄不好，很可能写成“语录讲义之押韵者”。但作者写的却是诗，因为是从自然界和社会生活中捕捉了形象，让形象本身来说话。\n先看第一首。\n“半亩方塘一鉴开，天光云影共徘徊”，这景象就很喜人。“半亩方塘”，不算大，但它像一面镜子那样澄澈明净，天光云影，都被它反映出来，闪耀浮动，情态毕见。作为景物描写，这也是成功的。这两句展示的形象本身，能给人以美感，...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646b79f430675327e1a5f94b", "shortContent": "从题目看，这两首诗是谈“观书”体会的，意在讲道理、发议论；弄不好，很可能写成“语录讲义之押韵者”。但作者写的却是诗，因为是从自然界和社会生活中捕捉了形象，让形象本身来说话。\n\n先看第一首。\n\n“半亩方塘一鉴开，天光云影共徘徊”，这景象就很喜人。“半亩方塘”，不算大，但它像一面镜子那样澄澈明净，天光云影，都被它反映出来，闪耀浮动，情态毕见。作为景物描写，这也是成功的。这两句展示的形象本身，能给人以美...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471e525b5420e27678f2449", "shortContent": "“半亩方塘一鉴开，天光云影共徘徊”，这景象就很喜人。“半亩方塘”，不算大，但它像一面镜子那样澄澈明净，天光云影，都被它反映出来，闪耀浮动，情态毕见。作为景物描写，这也是成功的。这两句展示的形象本身，能给人以美感，能使人心情澄净，心胸开朗。\n这感性形象本身还蕴含着理性的东西，最明显的一点就是：“半亩方塘”里的水很深很清，所以能够反映天光云影；反之，如果很浅、很污浊，就不能反映，或者不能准确地反映。诗...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '', 'center', 1415637680, '57b90fd02e958a005fa5c5d1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10416, '七绝', NULL, 56, 124, 1, 0, '施耐庵', NULL, 10333, '57b9ebb3a633bd005d30998b', '明', 'shi', '诗', 'http://baike.baidu.com/view/1025149.htm', '', '心在山东身在吴，飘蓬江海谩嗟吁。
他时若遂凌云志，敢笑黄巢不丈夫。', '此诗是小说《水浒传》第三十九回中，宋江酒醉后在浔阳楼上题写的诗作。该诗抒发了宋江被发配到江州后的忧郁心情，表达了他想要实现其“凌云志”的迫切愿望。该诗也被认为是宋江所题的反诗。', '', '', NULL, '', 'center', 1415637441, '57b9a9767db2a20068bdb4ee', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10040, '江城子 · 乙卯正月二十日夜记梦', NULL, 3580, 3406, 5, 6, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/403217.htm', '', '十年生死两茫茫。不思量，自难忘。千里孤坟，无处话凄凉。纵使相逢应不识，尘满面，鬓如霜。
夜来幽梦忽还乡。小轩窗，正梳妆。相顾无言，惟有泪千行。料得年年肠断处，明月夜，短松冈。', '苏东坡原配夫人王弗卒于宋英宗治平二年（公元一〇六五年），葬于四川彭山县。写此词时作者在密州（今山东诸城）任职，距王氏去世正好十年。此词情意缠绵，字字血泪，表现了绵绵不尽的哀伤和思念。', '江城子：词牌名。据唐·崔令钦《教坊记》、敦煌曲子词与现存晚唐前文人词，均无载录《江城子》，故是调当兴于晚唐。王昆吾《唐代酒令艺术》谓是调源自唐著词曲调，即唐时酒令，知是调始流行于晚唐酒筵上，经文人加工，遂成小令词调。唐五代时为单调，始见《花间集》韦端己词，单调三十五字，七句五平韵，间有三十六字、三十七字诸格。可见唐五代《江城子》调兴之初，格式尚未定型。全唐五代以《江城子》词约十六首，由七位词人所作，以端己最长，当为最早依调填词者。五代时，欧阳炯单调词添一衬字变尾二句为七言句，开宋词「衬字法」。牛松卿单调词添二字于第二句，开宋词「添字法」。尹参卿单调词摊破首句为两三言句，开宋词「减字法」、「摊破法」。北宋初，是调作者甚少，晏同叔、柳耆卿、欧阳文忠诸大家均无《江城子》传世，唯张子野有两首《江城子》。至东坡始变双调，由是词格渐定。薛瑞生《东坡词编年笺证》中考东坡首用是调约于熙宁年间，《江神子·湖上与张先同赋，时闻弹筝》与《江神子·孤山竹阁送述古》即东坡初创之作，仍承唐五代词柔婉细腻之风。元丰间，《江神子·乙卯正月二十日夜记梦》和《江神子·密州出猎》开一代词风，引时人乃至后代追和。是调衰于金元，近三分之一为道士所作，内容多涉道教。《钦定词谱》：「晁无咎改名《江神子》，韩涧泉词有『腊后春前村意远』句，更名《村意远》。」严建文《词牌释例》：「《江城子》，又名《江神子》、《村意远》、《水晶帘》，……清李符曾《词家辨证》云：『南唐人张泌有《江城子》二阕，五代欧阳炯用此调填词有『如西子镜，照江城』句，含本意……」《唐圭璋推荐唐宋词》注：「《江城子》调应由咏江城事而得名。『子』为曲名后缀。本篇用原始题意咏扬子江畔古城金陵。」可知调因欧词「如西子镜，照江城」句得名。欧词虽非现存《江城子》首作，然咏江城金陵事而归本意。有单调四体，分三十五字、三十六字、三十七字三种；双调一体，七十字，上下阕各七句，五平韵。格律多为平韵格，双调体偶有填仄韵者。
「乙卯正月二十日夜记梦」：《东坡外集》作「梦初室王氏，乙卯正月二十日」。茅维《苏集》本题同元延祐本，别有题注云：「公之夫人王氏先卒。味此词，盖悼亡也。」毛本无题。
十年：清·朱彊邨引清·王文诰《苏文忠公诗编注集成总案》：「词注谓公悼亡之作，考通义君卒于治平二年乙巳，至是熙宁八年乙卯，正十年也。」又引《东坡全集·卷二百十六·亡妻王氏墓誌铭》：「治平二年五月丁亥，赵郡苏轼之妻王氏，卒于京师。六月甲午，殡于京城之西。其明年六月壬午，葬于眉之东北彭山县安镇乡可龙里先君先夫人墓之西北八步。」
千里：王弗葬地四川眉山与东坡任所山东密州，相隔遥远，故称「千里」。
孤坟：唐·孟初中《本事诗·徵异》：「开元中，有幽州衙将姓张者，妻孔氏，生五子，不幸去世。复娶妻李氏，悍怒狠戾，虐遇五子，日鞭棰之。五子不堪其苦，哭于其葬。母忽于冢中出，抚其子，悲恸久之，因以白布巾题诗赠张曰：『不忿成故人，掩涕每盈巾。死生今有隔，相见永无因。匣里残妆粉，留将与後人。黄泉无用处，恨作冢中尘。有意怀男女，无情亦任君。欲知肠断处，明月照孤坟。』五子得诗，以呈其父。其父恸哭，诉于连帅。帅上闻，敕李氏杖一百，流岭南，张停所职。」其妻王氏之墓。
肠断：明吴讷钞本、茅维《苏集》本作「断肠」。
冈：诸本皆作「岗」。按「岗」同「冈」，「岗」後起字也。', '你我夫妻诀别已经整整十年，强忍不去思念可终究难相忘。千里之外那座遥远的孤坟啊，竟无处向你倾诉满腹的悲凉。纵然夫妻相逢你也认不出我，我已经是灰尘满面两鬓如霜。
昨夜我在梦中又回到了从前，在小屋窗口你正在打扮梳妆。你我二人默默相对惨然不语，只有流出淋漓热泪洒下千行。料想得到我当年想她的地方，就在明月的夜晚矮松的山冈。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b303048e64fbd89337", "shortContent": "苏东坡十九岁时，与年方十六的王弗结婚。王弗年轻美貌，侍翁姑恭谨，对词人温柔贤惠，恩爱情深。可惜恩爱夫妻不到头，王弗活到二十七岁就年轻殂谢了。东坡丧失了这样一位爱侣，心中的沉痛，精神上所受到的打击，是难以言说的。父亲对他说：“妇从汝于艰难，不可忘也。”（《亡妻王氏墓志铭》）熙宁八年（1075），东坡来到密州，这一年正月二十日，他梦见爱妻王氏，便写下了这首传诵千古的悼亡词。\n文学史上，悼亡诗写得最好的...", "authors": ["臧克家"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5bac6e67846a92190b9", "shortContent": "苏东坡十九岁时，与年方十六的王弗结婚。王弗年轻美貌，侍翁姑恭谨，对词人温柔贤惠，恩爱情深。可惜恩爱夫妻不到头，王弗活到二十七岁就年轻殂谢了。东坡丧失了这样一位爱侣，心中的沉痛，精神上所受到的打击，是难以言说的。父亲对他说：“妇从汝于艰难，不可忘也。”（《亡妻王氏墓志铭》）熙宁八年（1075），东坡来到密州，这一年正月二十日，他梦见爱妻王氏，便写下了这首传诵千古的悼亡词。\n文学史上，悼亡诗写得最好的...", "authors": ["臧克家"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253f534825dee9fd6e9", "shortContent": "苏东坡十九岁时，与年方十六的王弗结婚。王弗年轻美貌，侍翁姑恭谨，对词人温柔贤惠，恩爱情深。可惜恩爱夫妻不到头，王弗活到二十七岁就年轻殂谢了。东坡丧失了这样一位爱侣，心中的沉痛，精神上所受到的打击，是难以言说的。父亲对他说：“妇从汝于艰难，不可忘也。”（《亡妻王氏墓志铭》）熙宁八年（1075），东坡来到密州，这一年正月二十日，他梦见爱妻王氏，便写下了这首传诵千古的悼亡词。\n\n文学史上，悼亡诗写得最好...", "authors": ["臧克家"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e79f2af4e09d55b6523", "shortContent": "傅藻《东坡纪年录》：“熙宁八年乙卯（1075），（正月）二十日，记梦作《江神子》。”王文诰《苏诗总案》卷一三：“词注谓公悼亡之作，考通义君卒于治平二年乙巳（1065），至是熙宁八年乙卯正十年也。”苏轼妻王弗，眉州青神人，治平二年五月卒于京师，时年二十七岁。次年六月，归葬于眉州彭山县安镇乡可龙里苏轼父母墓侧。见《苏轼文集》卷六十五《亡妻王氏墓志铭》。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3d73206168b2e020cb", "shortContent": "本词作于北宋熙宁八年（1075），是词人悼念离世十年的亡妻王弗之作。王弗是乡贡进士王方之女，秀外慧中，十六岁时嫁于十九岁的苏轼。可惜恩爱夫妻不到头，治平二年（1065）王弗就撒手人寰，夫妻情分仅十有一年。苏轼哀痛不已，直至十年后仍然对爱妻哀思万分，甚至还在梦中看到了日思夜想的妻子。该词就写于这个感伤的梦醒之后。作品借虚境抒真情，让人不仅在对梦境的白描之中感受到了词人的一片痴情，更看到了清醒时分词人...", "authors": ["黄晓鋆"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702e7ccdb86c49f291f1", "shortContent": "本词为送别妻弟王缄所作，情感丰富，夹叙夹议，为苏轼极度伤感之代表作。上片首句直陈词人情感波动的起因：遇见妻弟王缄而引发对亡妻的思念。从追忆亡妻的思愁到送王缄离开的离愁，再联想到自己的官场失意之苦，感情上层层推进，其悲痛、伤感、思念、失意等情感缠绕叠加，引发读者的强烈共鸣。\n\n“忘却成都来十载，因君未免思量。”词人忘记成都那些事已经有十年了，如今因为看见你而再次勾起思念。该句交代了词的写作背景，也是...", "authors": ["周嘉怡　乐云"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702f7ccdb86c49f291fc", "shortContent": "本词作于北宋熙宁八年（1075），是词人悼念离世十年的亡妻王弗之作。王弗是乡贡进士王方之女，秀外慧中，十六岁时嫁于十九岁的苏轼。可惜恩爱夫妻不到头，治平二年（1065）王弗就撒手人寰，夫妻情分仅十有一年。苏轼哀痛不已，直至十年后仍然对爱妻哀思万分，甚至还在梦中看到了日思夜想的妻子。该词就写于这个感伤的梦醒之后。作品借虚境抒真情，让人不仅在对梦境的白描之中感受到了词人的一片痴情，更看到了清醒时分词人...", "authors": ["黄晓鋆"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271abc9ebcc6fbea1a4f1", "shortContent": "本词作于北宋熙宁八年（1075），是词人悼念离世十年的亡妻王弗之作。王弗是乡贡进士王方之女，秀外慧中，十六岁时嫁于十九岁的苏轼。可惜恩爱夫妻不到头，治平二年（1065）王弗就撒手人寰，夫妻情分仅十有一年。苏轼哀痛不已，直至十年后仍然对爱妻哀思万分，甚至还在梦中看到了日思夜想的妻子。该词就写于这个感伤的梦醒之后。作品借虚境抒真情，让人不仅在对梦境的白描之中感受到了词人的一片痴情，更看到了清醒时分词人...", "authors": ["黄晓鋆"], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646839b35fc8182fe9ac9878", "shortContent": "苏东坡十九岁时，与年方十六的王弗结婚。王弗年轻美貌，侍翁姑恭谨，对词人温柔贤惠，恩爱情深。可惜恩爱夫妻不到头，王弗活到二十七岁就年轻殂谢了。东坡丧失了这样一位爱侣，心中的沉痛，精神上所受到的打击，是难以言说的。父亲对他说：“妇从汝于艰难，不可忘也。”（《亡妻王氏墓志铭》）熙宁八年（1075），东坡来到密州，这一年正月二十日，他梦见爱妻王氏，便写下了这首传诵千古的悼亡词。\n\n文学史上，悼亡诗写得最好...", "authors": ["臧克家"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f338ab6a81d0c5320231e", "shortContent": "苏东坡十九岁时，与年方十六的王弗结婚。王弗年轻美貌，侍翁姑恭谨，对词人温柔贤惠，恩爱情深。可惜恩爱夫妻不到头，王弗活到二十七岁就年轻殂谢了。东坡丧失了这样一位爱侣，心中的沉痛，精神上所受到的打击，是难以言说的。父亲对他说：“妇从汝于艰难，不可忘也。”（《亡妻王氏墓志铭》）熙宁八年（1075），东坡来到密州，这一年正月二十日，他梦见爱妻王氏，便写下了这首传诵千古的悼亡词。\n文学史上，悼亡诗写得最好的...", "authors": ["臧克家"], "pressName": "上海辞书出版社"}]', '', 'indent', 1359824799, '57ad64f01532bc00616dce2a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10041, '拟挽歌辞三首', NULL, 70, 99, 4, 0, '陶渊明', NULL, 10011, '57b8fa07c4c97100558ef104', '晋', 'shi', '诗', 'http://baike.baidu.com/view/3548732htm', '', '【其一】
有生必有死，早终非命促。
昨暮同为人，今旦在鬼录。
魂气散何之，枯形寄空木。
娇儿索父啼，良友抚我哭。
得失不复知，是非安能觉！
千秋万岁后，谁知荣与辱？
但恨在世时，饮酒不得足。
【其二】
在昔无酒饮，今但湛空觞。
春醪生浮蚁，何时更能尝！
肴案盈我前，亲旧哭我傍。
欲语口无音，欲视眼无光。
昔在高堂寝，今宿荒草乡；
一朝出门去，归来良未央。
【其三】
荒草何茫茫，白杨亦萧萧。
严霜九月中，送我出远郊。
四面无人居，高坟正嶕峣。
马为仰天鸣，风为自萧条。
幽室一已闭，千年不复朝。
千年不复朝，贤达无奈何。
向来相送人，各自还其家。
亲戚或余悲，他人亦已歌。
死去何所道，托体同山阿。', '这组组诗作品是诗人假设自己死后的情况，表达了自己对生死的看法，又安慰亲友不必过于悲伤。第一首诗是说死后收殓的情况，描述儿女朋友痛哭。诗人豁达地说死后便没有荣誉与羞辱，只觉得酒还未喝够便死了，有些遗憾。第二首诗是写出殡前的祭祀。诗人描述亲人的哀伤，自己虽感到不能饮酒的遗憾，但已为离开家园而有些黯然。第三首诗是写下葬的情形。诗人对下葬后的幽冥世界不猜测，也认为贤达也不能逃避死亡，与当时追求神仙得道的风气迥异。全诗艺术构思极有新意，以形象化的语言设想自己离开人世之后发生的主客观情状，表现了诗人对生死极其坦然的态度，显示了他极其明彻达观的思想。', '挽歌：挽柩者所唱哀悼死者的歌，泛指对死者悼念的诗歌或哀叹旧事物灭亡的文辞。
非命促：并非生命短促。意谓生死属于自然规律，故生命并无长短之分。
昨暮：昨晚。
同为人：指还活在世上。
今旦：今晨。
在鬼录：列入鬼的名册，指死去。
魂气：指人的精神意识。《左传·昭公七年》疏：「附形之灵为魄，附气之神为魂。」
散何之：散归何处。
枯形：枯槁的屍体。
寄空木：安放于棺木之中。
索：寻找。
千秋万岁：千年万年，形容岁月长久。
湛（zhàn）空觞：是说往日的空酒杯中，如今盛满了澄清的奠酒。
春醪（lǎo）：春酒。
浮蚁：酒面上的泡沫。《文选·张衡〈南都赋〉》：「醪敷径寸，浮蚁若萍。」刘良注：「酒膏径寸，布于酒上，亦有浮蚁如水萍也。」
肴（yáo）案：指摆在供桌上的盛满肉食的木盘。肴，荤菜；案，古代进食用的一种短脚木盘。
盈：指摆满。
傍：即「旁」。
荒草乡：指荒草丛生的坟地。按：逯本据《乐府诗集》于此句後校增「荒草无人眠，极视正茫茫」二句，为诸本所无。然此二句与第三首「四面无人居」、「荒草何茫茫」等句重复，故当删去。
出门去：指出殡。
良未央：未有尽头，遥遥无期。良，确，诚。此句一本作「归来夜未央」。
何：何其，多么。
茫茫：无边无际的样子。
萧萧：风吹树木声。
严霜：寒霜，浓霜。
送我出远郊：指出殡送葬。
无人居：指荒无人烟。
嶕峣（jiāo yáo）：高耸的样子。
马：指拉灵枢丧车的马。
幽室：指墓穴。
朝（zhāo）：早晨，天亮。
贤达：古时指有道德学问的人。
无奈何：无可奈何，没有办法。指皆不免此运。
向：先时，刚纔。
各自还其家：《文选》作「各已归其家」，兹从逯本。
已歌：已经在欢快地歌了。是说人们早已忘了死者，不再有悲哀。
何所道：还有什么可说的呢。', '【其一】
人命有生必有死，早终不算生命短。
昨晚生存在世上，今晨命丧赴黄泉。
游魂飘散在何处？枯稿屍身存木棺。
娇儿找父伤心啼，好友痛哭灵柩前。
死去不知得与失，哪还会有是非感？
千秋万岁身后事，荣辱怎能记心间？
衹恨今生在世时，饮酒不足太遗憾。
【其二】
生前贫困无酒饮，今日奠酒盛满觞。
春酒清香浮泡沫，何时能再得品尝！
佳肴满案摆面前，亲友痛哭在我旁。
想要发言口无声，想要睁眼目无光。
往日安寝在高堂，如今长眠荒草乡。
一朝归葬出门去，想再归来没指望。
【其三】
茫茫荒野草枯黄，萧瑟秋风抖白杨。
已是寒霜九月中。亲人送我远郊葬。
四周寂寞无人烟，坟墓高高甚凄凉。
马为仰天长悲鸣，风为萧瑟作哀响。
墓穴已闭成幽暗，永远不能见曙光。
永远不能见曙光，贤达同样此下场。
刚才送葬那些人，各自还家入其房。
亲戚或许还悲哀，他人早忘已欢唱。
死去还有何话讲，寄托此身在山冈。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccae5e272d4b2254ea8a", "shortContent": "多年来我一直坚持一种看法，即陶渊明诗文应读全集，无须遴选；而陶诗明白如话，尤不必加以评论和赏析。至于陶之为人，亦久有定论，再施品评，尽属辞费。近时重读陶诗，觉得他的三首《挽歌诗》（本集题作《拟挽歌辞》，此据《文选》）极有新意。于是泚笔略陈心得，算是填补我几十年来不谈陶诗的空白吧。\n陶诗一大特点，便是他怎么想就怎么说，基本上是直陈其事的“赋”笔，运用比兴手法的地方是不多的。故造语虽浅而含义实深，虽出...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4547f27182da33f706b", "bookTitle": "陶渊明诗文鉴赏辞典", "articleId": "646aaa7a30675327e1a16596", "shortContent": "多年来我一直坚持一种看法，即陶渊明诗文应读全集，无须遴选；而陶诗明白如话，尤不必加以评论和赏析。至于陶之为人，亦久有定论，再施品评，尽属辞费。近时重读陶诗，觉得他的三首《挽歌诗》（本集题作《拟挽歌辞》，此据《文选》）极有新意。于是泚笔略陈心得，算是填补我几十年来不谈陶诗的空白吧。\n陶诗一大特点，便是他怎么想就怎么说，基本上是直陈其事的“赋”笔，运用比兴手法的地方是不多的。故造语虽浅而涵义实深，虽出...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}]', '龚望《陶渊明集评议》引胡仔：渊明自作挽歌词凡三首，秦太虚亦效之，余谓渊明之词了达，太虚之词哀怨，有不同耳。
清代邱嘉穗《东山草堂陶诗笺》：首篇乍死而殓，次篇奠而出殡，三篇送而葬之，次第秩然。
清代吴淇《六朝选诗定论·卷十一》：挽歌昉于缪袭，以此歌比而校之，其旷达处相同，而哀惨过之，陆机三章虽佳，风骨则减矣。', 'center', 1423166563, '57b8fc0c2e958a005fa5267f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10042, '满江红  写怀', NULL, 2203, 24, 8, 9, '岳飞', NULL, 10016, '57b98e6fc4c9710055944170', '宋', 'ci', '词', 'http://baike.baidu.com/view/1231195.htm', '', '怒发冲冠，凭栏处、潇潇雨歇。抬望眼，仰天长啸，壮怀激烈。三十功名尘与土，八千里路云和月。莫等闲，白了少年头，空悲切！
靖康耻，犹未雪。臣子恨，何时灭？驾长车、踏破贺兰山缺！壮志饥餐胡虏肉，笑谈渴饮匈奴血。待从头、收拾旧山河，朝天阙！', '这首词代表了岳武穆「精忠报国」的英雄之志，表现出一种浩然正气、英雄气质，表现了报国立功的信心和乐观主义精神。词里句中无不透出雄壮之气，充分表现作者忧国报国的壮志胸怀。这首爱国将领的抒怀之作，情调激昂，慷慨壮烈，充分表现的中华民族不甘屈辱，奋发图强，雪耻若渴的神威，从而成为反侵略战争的名篇。', '怒发冲冠：气得头发竖起，以至于将帽子顶起。形容愤怒至极，冠是指帽子而不是头发竖起。
潇潇：形容雨势急骤。
长啸：大声呼叫。汉·司马长卿《上林赋》：「长啸哀鸣，翩幡互经。」
「三十功名尘与土」句：三十年来，建立了一些功名，如同尘土。
「八千里路云和月」句：形容南征北战、路途遥远、披星戴月。
等闲：轻易，随便。
靖康耻：宋钦宗靖康二年（西元一一二七年），金兵攻陷汴京，虏走徽、钦二帝。
贺兰山：贺兰山脉位于宁夏回族自治区与内蒙古自治区交界处。一说是位于邯郸市磁县境内的贺兰山。
朝天阙：朝见皇帝。天阙：本指宫殿前的楼观，此指皇帝生活的地方。又，明·王熙书《满江红》词碑作「朝金阙」。', '我怒发冲冠登高倚栏杆，一场潇潇细雨刚刚停歇。抬头望眼四望辽阔一片，仰天长声啸叹。壮怀激烈，三十年勋业如今成尘土，征战千里衹有浮云明月。莫虚度年华白了少年头，只有独自悔恨悲悲切切。
靖康年的奇耻尚未洗雪，臣子愤恨何时才能泯灭。我只想驾驭着一辆辆战车踏破贺兰山敌人营垒。壮志同仇饿吃敌军的肉，笑谈蔑敌渴饮敌军的血。我要从头再来收复旧日河山，朝拜故都京阙。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74d9d635634aee3d7267", "shortContent": "岳将军此词，激励着千古中华民族的爱国心。抗日战争时期，这首词曲低沉而雄壮的歌音，更使人们领受到它的伟大的感染力量。\n上来一句四个字，即用太史公写蔺相如“怒发上冲冠”的奇语，表明这是不共戴天的深仇大恨。此仇此恨，因何愈思愈不可忍？正缘高楼独上，栏杆自倚，纵目乾坤，俯仰六合，不禁满怀热血、激荡沸腾。———而当此之时，愁霖乍止，风烟澄净，光景自佳，翻助郁勃之怀，于是仰天长啸，以抒此万斛英雄壮气。着“潇潇...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5dd0f8fda55650604f2", "shortContent": "岳将军此词，激励着千古中华民族的爱国心。抗日战争时期，这首词曲低沉而雄壮的歌音，更使人们领受到它的伟大的感染力量。\n上来一句四个字，即用太史公写蔺相如“怒发上冲冠”的奇语，表明这是不共戴天的深仇大恨。此仇此恨，因何愈思愈不可忍？正缘高楼独上，栏杆自倚，纵目乾坤，俯仰六合，不禁满怀热血、激荡沸腾。———而当此之时，愁霖乍止，风烟澄净，光景自佳，翻助郁勃之怀，于是仰天长啸，以抒此万斛英雄壮气。着“潇潇...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255e8f18b220af461f0", "shortContent": "岳将军此词，激励着千古中华民族的爱国心。抗日战争时期，这首词曲低沉而雄壮的歌音，更使人们领受到它的伟大的感染力量。\n\n上来一句四个字，即用太史公写蔺相如“怒发上冲冠”的奇语，表明这是不共戴天的深仇大恨。此仇此恨，因何愈思愈不可忍？正缘高楼独上，栏杆自倚，纵目乾坤，俯仰六合，不禁满怀热血、激荡沸腾。——而当此之时，愁霖乍止，风烟澄净，光景自佳，翻助郁勃之怀，于是仰天长啸，以抒此万斛英雄壮气。着“潇潇...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f4df2af4e09d55b664c", "shortContent": "二十世纪三十年代末，余嘉锡先生在《四库提要辨证》中提出了对于这阕《满江红》的质疑：“其词莫知所从来……吾何为不可疑之哉？疑之而其词不因我而废，听其流行可矣。至其为岳珂所未见，《鄂王家集》所未有，突出于明之中叶，则学者不可不知也。”于是多有附和者，考证这首词非岳飞所作，而是明代人写的。但据张清华先生的考证，则坐实了其确为岳飞所作。\n\n宋高宗绍兴六年（1136）七月，岳飞奉诏开始第二次北伐，节节胜利，...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127040c26cbf3417f09489", "shortContent": "二十世纪三十年代末，余嘉锡先生在《四库提要辨证》中提出了对于这阕《满江红》的质疑：“其词莫知所从来……吾何为不可疑之哉？疑之而其词不因我而废，听其流行可矣。至其为岳珂所未见，《鄂王家集》所未有，突出于明之中叶，则学者不可不知也。”于是多有附和者，考证这首词非岳飞所作，而是明代人写的。但据张清华先生的考证，则坐实了其确为岳飞所作。\n\n宋高宗绍兴六年（1136）七月，岳飞奉诏开始第二次北伐，节节胜利，...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271f2c26cbf3417f095d1", "shortContent": "20世纪30年代末，余嘉锡先生在《四库提要辨证》中提出了对于这阕《满江红》的质疑：“其词莫知所从来，……吾何为不可疑之哉？疑之而其词不因我而废，听其流行可矣。至其为岳珂所未见，《鄂王家集》所未有，突出于明之中叶，则学者不可不知也。”于是多有附和者，考证这首词非岳飞所作，而是明代人写的。但据张清华先生考证，则坐实了其确为岳飞所作。\n宋高宗绍兴六年（1136）七月，岳飞奉诏开始第二次北伐，节节胜利，八...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472c41aa5f1e74f958a14f1", "shortContent": "这首词较同调“怒发冲冠”之作时代略早，当作于绍兴四年（1134）作者收复襄阳六州驻节鄂州（今湖北武昌）时。\n\n绍兴三年（1133）十月，金人傀儡刘豫军队占领襄阳、唐、邓、随、郢诸州府及信阳军，切断了南宋朝廷通向川陕的交通，也直接威胁到湖南、湖北百姓的安全。岳飞即接连上书奏请进兵中原，收复襄阳等六州。次年五月朝廷任命岳飞兼黄、复二州、汉阳军（湖北汉阳）、德安府（湖北安陆）制置使，领兵出征。由于军纪严...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472c46ee49f46528ae015e7", "shortContent": "岳将军此词，激励着千古中华民族的爱国心。抗日战争时期，这首词曲低沉而雄壮的歌音，更使人们领受到它的伟大的感染力量。\n\n上来一句四个字，即用太史公写蔺相如“怒发上冲冠”的奇语，表明这是不共戴天的深仇大恨。此仇此恨，因何愈思愈不可忍？正缘高楼独上，阑干自倚，纵目乾坤，俯仰六合，不禁满怀热血，激荡沸腾。——而当此之时，愁霖乍止，风烟澄净，光景自佳，翻助郁勃之怀，于是仰天长啸，以抒此万斛英雄壮气。着“潇潇...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}]', '沈震峰《草堂诗馀正集》：胆量、意见、文章悉无今古。又云：有此愿力，是大圣贤、大菩萨。
刘蒲菴《七颂堂诗绎》：词有与古诗同义者，「潇潇雨歇」，《易水》之歌也。
陈廷焯《白雨斋词话》：何等气概！何等志向！千载下读之，凛凛有生气焉。「莫等闲」二语，当为千古箴铭。
张清音《词征·卷一》：岳忠武「收拾山河」，《无衣》修矛戟也。', 'indent', 1413469740, '57acb6aa79bc440058c317ee', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10043, '小重山', NULL, 405, 24, 3, 2, '岳飞', NULL, 10016, '57b98e6fc4c9710055944170', '宋', 'ci', '词', 'http://baike.baidu.com/view/2518222.htm', '', '昨夜寒蛩不住鸣。惊回千里梦，已三更。起来独自绕阶行。人悄悄，帘外月胧明。
白首为功名。旧山松竹老，阻归程。欲将心事付瑶琴，知音少，弦断有谁听？', '南宋绍兴七年（公元1137年），正当抗金前线捷报频传，凯歌高奏，士气民心大振，收复中原失地胜利在望的时刻。宋高宗赵构不顾朝野上下的反对，再次起用汉奸秦桧为枢密使。次年又拜右仆射、同中书门下平章事兼枢密使。从此秦桧独揽大权，极力推行投降卖国政策。广大军民抗金救国的积极性受到严重的压抑和摧残，主战派赵鼎、王庶、张戒、曾开、胡铨等人都因反对“议和”，触怒秦桧，相继被排斥出朝廷，遭到贬谪、流放和编管。岳飞和许多爱国志士一样，受到投降派的压制和阻挠，深感自己杀敌报国的理想难以实现，内心充满了忧愤和抑郁。
此词上半阕写出忧深思远之情，与阮籍《咏怀》诗第一首“夜中不能寐，起坐弹鸣琴”意境相似。下半阕“白首”二句，表面低沉消极，但实际上正是壮志难酬的孤愤。“欲将”三句，用比兴手法点出“知音”难遇的凄凉情怀，甚为悲伤忧郁。', '寒蛩（qióng）：秋天的蟋蟀。
千里梦：指赴千里外杀敌报国的梦。
三更：指半夜十一时至翌晨一时。
月胧明：月光不明。胧，朦胧。
功名：此指为驱逐金兵的入侵，收复失地而建功立业。
旧山：家乡的山。
付：付与。
瑶（yáo）琴：饰以美玉的琴。', '昨夜，寒秋蟋蟀不住哀鸣，梦回故乡，千里燃战火，被惊醒，已三更。站起身，独绕台阶踽踽行。四周静悄悄，帘外，一轮淡月正朦胧。
为国建功留青史，未老满头霜星星。家山松竹苍老，无奈议和声起、阻断了归程。想把满腹心事，付与瑶琴弹一曲。可是高山流水知音稀，纵然絃弹断，又有谁来听？', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74d95e272d4b2253bc0b", "shortContent": "岳飞的《满江红》（怒发冲冠）词，壮怀激烈，是脍炙人口的佳作。这首《小重山》词，是用另一种艺术手法表达他抗金报国的壮怀。岳飞抗金的志业，不但受到赵构、秦桧君臣的忌恨迫害，而同时其他的人，如大臣张浚，诸将张俊、杨沂中、刘光世等，亦进行阻挠，故岳飞有曲高和寡、知音难遇之叹。《小重山》词就是抒写这种心情的。此词上半阕写出忧深思远之情，与阮籍《咏怀》诗第一首“夜中不能寐，起坐弹鸣琴”意境相近。下半阕“白首”...", "authors": ["缪", "钺"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5dd03572034f65a8bd1", "shortContent": "岳飞的《满江红》（怒发冲冠）词，壮怀激烈，是脍炙人口的佳作。这首《小重山》词，是用另一种艺术手法表达他抗金报国的壮怀。岳飞抗金的志业，不但受到赵构、秦桧君臣的忌恨迫害，而同时其他的人，如大臣张浚，诸将张俊、杨沂中、刘光世等，亦进行阻挠，故岳飞有曲高和寡、知音难遇之叹。《小重山》词就是抒写这种心情的。此词上半阕写出忧深思远之情，与阮籍《咏怀》诗第一首“夜中不能寐，起坐弹鸣琴”意境相近。下半阕“白首”...", "authors": ["缪", "钺"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255e8f18b220af461ef", "shortContent": "岳飞的《满江红》（怒发冲冠）词，壮怀激烈，是脍炙人口的佳作。这首《小重山》词，是用另一种艺术手法表达他抗金报国的壮怀。岳飞抗金的志业，不但受到赵构、秦桧君臣的忌恨迫害，而同时其他的人，如大臣张浚，诸将张俊、杨沂中、刘光世等，亦进行阻挠，故岳飞有曲高和寡、知音难遇之叹。《小重山》词就是抒写这种心情的。此词上半阕写出忧深思远之情，与阮籍《咏怀》诗第一首“夜中不能寐，起坐弹鸣琴”意境相近。下半阕“白首”...", "authors": ["缪　钺"], "pressName": "上海辞书出版社"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127040c26cbf3417f0948a", "shortContent": "从词中情调看，这首词应该写于秦桧当权后。绍兴七年（1137），宋高宗不顾抗金前线的大好局势，起用主和的秦桧为枢密使。第二年又升秦为右仆射、同中书门下平章事兼枢密使，积极与金人议和投降。岳飞曾公开批评说：“金人不可信，和好不可恃，相臣谋国不臧，恐贻后世讥。”（《宋史·岳飞传》）但宋高宗赵构与秦桧一心“屈己求和”，主战派纷纷被排斥。岳飞深感抗金成果即将付之流水，自己收复河山的抱负难以实现，内心愤懑抑塞...", "authors": ["冯丽霞"], "pressName": "崇文书局"}]', '沈雄《古今词话·词话·上卷》：《话腴》曰：武穆收复河南罢兵表云：“莫守金石之约，难充溪壑之求。暂图安而解倒悬，犹之可也。欲远虑而尊中国，岂其然乎。”故作《小重山》云：“欲将心事付瑶琴。知音少，絃断有谁听。”指主和议者。又作《满江红》，忠愤可见，其不欲“等闲白了少年头”，可以明其心事。
王弈清《历代词话·卷七》引《古今词话》：岳侯，忠孝人也。其《小重山》词，梦想旧山，悲凉悱恻之至。
王弈清《历代词话·卷七》引《话腴》：武穆贺讲和赦表云：“莫守金石之约，难充溪壑之求。”故作词云：“欲将心事付瑶琴。知音少，絃断有谁听。”盖指和议之事也。又作《满江红》，忠愤可见，其不欲“等闲白了少年头”，足以明其心事。
陈廷焯《词则·放歌集·卷一》：苍凉悲壮中亦复风流儒雅。
龙榆生《唐五代宋词选》：一种激昂忠愤之气，读之使人慷慨。推其志，虽与日月争光可也。
詹安泰《词学讲义》：岳鹏举《满江红》，悲愤之怀，壮烈之志，和盘托出，绝无隐蓄，此不关乎寄托也。至其《小重山》词，则真有寄托之作也。故国怕回首，而托诸惊梦；所愿不得偿，则托诸空阶明月；咎忠贞不见谅于当轴，致坐失机宜，而托诸瑶琴独奏，赏音无人。盖托体比兴也。陈藏一《话腴》谓：“‘欲将心事付瑶琴，知音少，絃断有谁听。’盖指和议之非。”斯言得之。故求寄托于词中者，当在此而不在彼。岳鹏举《满江红》词一阕，非不慷慨激昂，可歌可泣。顾其耐人寻味之程度，殊不若其《小重山》也，故从词之本身论，则以《小重山》为高格。', 'indent', 1359825392, '57b902b75bbb50005b7834c9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10045, '南乡子 · 送述古', NULL, 298, 3406, 3, 1, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/1069516.htm', '', '回首乱山横，不见居人只见城。谁似临平山上塔，亭亭，迎客西来送客行。
归路晚风清，一枕初寒梦不成。今夜残灯斜照处，荧荧，秋雨晴时泪不晴。', '这是一首送别之作，清新中有深意，自然中寓浓情，也颇耐人寻味。词的上阕回叙分手后回望离别之地临平镇和临平山，抒写了对往事无限美好的回忆和对友人的依恋之情，下阕则述归来怀念之情。友人既已远逝，回家的路上晚风凄清，表达了词人情真意切的送别之情。', '南乡子：唐教坊曲名，后用作词牌。又名《好离乡》、《蕉叶怨》。《金奁集》入「黄钟宫」。原为单调，有二十七字、二十八字、三十字各体，两平韵，三仄韵，平仄换韵。单调始自后蜀欧阳炯，此词牌即以欧阳炯《南乡子》为正体。冯正中、李德润俱本此添字。双调者始自南唐冯正中词。冯词平韵五十六字，十句，上下阕各四句用韵。另有五十八字体者。其定格为双调五十六字，上下阕各四平韵，一韵到底。此调唱时音节需流丽谐婉，声情掩抑。
述古：陈襄，宋福州侯官（今福建福州）人，字述古，因家在古灵村，人称古灵先生。宋仁宗、宋神宗时名臣。倡理学，与陈季甫、周希孟、郑穆友称「海滨四先生」。宋仁宗庆历二年（西元一〇四二年）进士。初仕浦城主簿，历知仙居、河阳、濛阳诸县。嘉祐二年（西元一〇五七年），入为秘阁校理、判祠部事。嘉祐六年（西元一〇六一年），出知常州。宋英宗治平初，复为开封府推官、三司盐铁判官。宋神宗即位，出知明州。熙宁二年（西元一〇六九年），同修起居注，知谏院、改知制诰。寻直学士院。熙宁四年（西元一〇七一年），因与王介甫政见不合，论青苗法不便，出知陈州。熙宁五年（西元一〇七二年），知杭州。熙宁七年（西元一〇七四年），复知陈州。熙宁八年（西元一〇七五年），召还，知通进、银台司兼侍读，判尚书都省。元丰三年（西元一〇八〇年）卒，年六十四。尝荐司马温公、苏东坡等三十三人。有《古灵先生文集》。事见宋·陈晔《古灵先生年谱》（《永乐大典·卷三一四二》），《宋史·卷三百二十一·陈襄传》。
「不见居人只见城」句：取自唐·欧阳行周《初发太原途中寄太原所思》诗：「驱马觉渐远，回头长路尘。高城已不见，况复城中人。」谓城、人皆不可见。此谓见城不见人（指述古），稍作变化。
临平山：傅子立注：「临平山在杭州。」刘尚荣按：「南宋·潜君高《咸淳临安志·卷二十四·临平山》：『《祥符志》云：「（临平山）去仁和县旧治五十四里，山高五十三丈，周回十八里，上有塔。有龙洞、砺洞事具诸洞，有天井在山之顶。旧志云：『方阔约二丈，积水深八尺，虽旱未尝涸』，下有东岳庙、景星观峙立两旁，又有藕花洲，即鼎湖也。」』东坡《次韵杭人裴惟甫》诗：『馀杭门外叶飞秋，尚记居人挽去舟。一别临平山上塔，五年云梦泽南州。』」龙榆生笺引查注《东坡诗集》：「《九域志》：『仁和县有临平镇。』」临平塔时为送别之标志。
亭亭：直立貌。
归路：《二妙集》本、茅维《苏集》本、毛本作「临路」。
荧荧：即指「残灯斜照」，又指泪光，喻贴切新颖。此指残灯照射泪珠之闪光。', '回头看横亘的远山，已看不见城中的人影，只隐隐看见一座城。谁像那临平山上的高塔，亭亭伫立，迎送往来的客人。
回家的路上，晚风凄清，枕上初寒，难以入眠。今夜残灯斜照，微光闪烁，秋雨虽停但泪还未尽。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b12e6a6b501f9542b8", "shortContent": "苏轼这首词善于从社会人生常见的聚散之中展现出特定环境中的真情挚意。送别之作，牵涉到送行与被送行双方，联系双方的感情纽带是作品好坏的决定性因素。只有在二者深厚情谊的基础上，才说得上如何运用艺术的手段把它表现出来，而不致仅流于应酬而已。苏轼与陈述古交谊较深。述古名襄，比苏轼年长。当他还在朝时，便曾向宋神宗推荐苏轼是难得的人才。以后二人都因反对新法离朝外任，述古于熙宁五年（1072）五月由陈州移知杭州时...", "authors": ["邱俊鹏"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b8d635634aee3e9a7e", "shortContent": "苏轼这首词善于从社会人生常见的聚散之中展现出特定环境中的真情挚意。送别之作，牵涉到送行与被送行双方，联系双方的感情纽带是作品好坏的决定性因素。只有在二者深厚情谊的基础上，才说得上如何运用艺术的手段把它表现出来，而不致仅流于应酬而已。苏轼与陈述古交谊较深。述古名襄，比苏轼年长。当他还在朝时，便曾向宋神宗推荐苏轼是难得的人才。以后二人都因反对新法离朝外任，述古于熙宁五年（1072）五月由陈州移知杭州时...", "authors": ["邱俊鹏"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e79f2af4e09d55b6507", "shortContent": "傅藻《东坡纪年录》：“熙宁七年甲寅（1074），送述古赴南都作《南乡子》。”王文诰《苏诗总案》卷一二：“熙宁七年甲寅，七月，追送陈襄移守南都，别于临平舟中，作《南乡子》。”薛本、邹王本从之。孔《谱》编熙宁七年八月十三日，追送陈襄至临平，再赋词赠别。", "authors": [], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702e7ccdb86c49f291f3", "shortContent": "这是一首送别怀人词，作于北宋熙宁七年（1074）七月，其时苏轼好友陈襄奉旨移守南都（今河南商丘）。苏轼追送友人至临平（今余杭），昼间目送挚友远去，夜里对灯不眠，愁思难了，故写下此词，表达对故人的思念与祝福。\n\n上片写追送故人途中一路所见之景。以“回首乱山横”开头，从远景描绘山色，重点突出一个“乱”字——临平山景色秀丽温婉，在词人眼中却好似突兀的乱石一般，只恨它阻挡了自己送别友人的急切目光。相由心生...", "authors": ["张哲人　乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271aac9ebcc6fbea1a4e8", "shortContent": "这是一首送别怀人词，作于北宋熙宁七年（1074）年七月，其时苏轼好友陈襄奉旨移守南都（今河南商丘）。苏轼追送友人至临平（今余杭），昼间目送挚友远去，夜里对灯不眠，愁思难了，故写下此词，表达对故人的思念与祝福。\n上片写追送故人途中一路所见之景，以“回首乱山横”开头，从远景描绘山色，重点突出一个“乱”字——平临山景色秀丽温婉，在词人眼中却好似突兀的乱石一般，只恨它阻挡了自己送别友人的急切目光。相由心生...", "authors": ["张哲人　乐云"], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "6468333bb6a81d0c5301db5b", "shortContent": "苏轼这首词善于从社会人生常见的聚散之中展现出特定环境中的真情挚意。送别之作，牵涉到送行与被送行双方，联系双方的感情纽带是作品好坏的决定性因素。只有在二者深厚情谊的基础上，才说得上如何运用艺术的手段把它表现出来，而不致仅流于应酬而已。苏轼与陈述古交谊较深。述古名襄，比苏轼年长。当他还在朝时，便曾向宋神宗推荐苏轼是难得的人才。以后二人都因反对新法离朝外任，述古于熙宁五年（1072）五月由陈州移知杭州时...", "authors": ["邱俊鹏"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413387222, '57b8eea8d342d3005ac6ba87', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10073, '七律 · 长征', NULL, 501, 106, 4, 2, '毛泽东', NULL, 10025, '57b8fb582e958a005fa52193', '当代', 'shi', '诗', 'http://baike.baidu.com/view/65597.htm', '', '红军不怕远征难，万水千山只等闲。
五岭逶迤腾细浪，乌蒙磅礴走泥丸。
金沙水拍云崖暖，大渡桥横铁索寒。
更喜岷山千里雪，三军过后尽开颜。', '此诗是一首七言律诗，选自《毛泽东诗词集》。本诗写于1935年10月6日，红军攻占腊子口之后、在六盘山前。共8句56个字，负载着长征路上的种种艰难险阻，饱含无产阶级革命者的万般豪情壮志。它是中国革命的壮烈史诗，也是中国诗歌宝库中的灿烂明珠。无论对革命史而言，抑或对诗歌史而论，它都是里程碑之作。', '等闲：不怕困难，不可阻止。
五岭：大庾岭，骑田岭，都庞岭，萌渚岭，越城岭，横亘在江西、湖南、两广之间。
逶迤：形容道路、山脉、河流等弯弯曲曲，连绵不断的样子。
细浪：作者自释：“把山比作‘细浪’、‘泥丸’，是‘等闲’之意。”
乌蒙：山名。乌蒙山，在贵州西部与云南东北部的交界处，北临金沙江，山势陡峭。1935年4月，红军长征经过此地。
泥丸：小泥球，整句意思说险峻的乌蒙山在红军战士的脚下，就像是一个小泥球一样。
金沙：金沙江，指长江上游自青海省玉树县至四川省宜宾市的一段，云南等地也有支流。1935年5月，红军曾强渡云南省禄劝县皎平渡渡口。
云崖暖：是指浪花拍打悬崖峭壁，溅起阵阵雾水，在红军的眼中像是冒出的蒸汽一样。（云崖：高耸入云的山崖。暖：被一些学者指为红军巧渡金沙江后的欢快心情，也有学者说意思为直译后的温暖。）
大渡桥：指四川省西部泸定县大渡河上的泸定桥。
铁索：大渡河上泸定桥，它是用十三根铁索组成的桥。
寒：影射敌人的冷酷与形势的严峻。
岷（mín）山：中国西部大山。位于甘肃省西南、四川省北部。西北-东南走向。西北接西倾山，南与邛崃山相连。包括甘肃南部的迭山，甘肃、四川边境的摩天岭。
三军：作者自注：“红军一方面军，二方面军，四方面军。”
尽开颜：红军的长征到达目的地了，他们取得了胜利，所以个个都笑逐颜开。', '红军不怕万里长征路上的一切艰难困苦，把千山万水都看得极为平常。绵延不断的五岭，在红军看来只不过是微波细浪在起伏，而气势雄伟的乌蒙山，在红军眼里也不过是一颗泥丸。
金沙江浊浪滔天，拍击着高耸入云的峭壁悬崖，热气腾腾。大渡河险桥横架，晃动着凌空高悬的根根铁索，寒意阵阵。
更加令人喜悦的是踏上千里积雪的岷山，红军翻越过去以后个个笑逐颜开。', '[{"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88b97ccdb86c49e7aa0f", "shortContent": "这首诗最早发表在《诗刊》一九五七年一月号。\n\n在中国现代革命史上，发生了一件惊天动地，震撼中外的重大历史事件，这就是中国工农红军所进行的二万五千里长征。\n\n1933年10月间，蒋介石调集约一百万人的兵力，采取“堡垒主义”的新战略，对中央革命根据地及其邻近的革命根据地进行大规模“围剿”。这时，王明“左”倾冒险主义路线已在红军中取得了完全的统治，用阵地战代替游击战和运动战，用所谓“正规”战争代替人民战...", "authors": ["邓先正"], "pressName": "上海辞书出版社"}]', '', 'center', 1415644915, '57b93f902e958a005fa76aa5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10046, '清平乐 · 忆别', NULL, 575, 87, 2, 4, '李煜', NULL, 10017, '57b8af7c5bbb50005b770fdd', '五代十国', 'ci', '词', 'http://baike.baidu.com/view/652800.htm', '', '别来春半。触目柔肠断。砌下落梅如雪乱，拂了一身还满。
雁来音信无凭，路遥归梦难成。离恨恰如春草，更行更远还生。', '全词写怀人念远、忧思难禁之情，或为作者牵记其弟李从善入宋不得归，故触景生情而作。上片点出春暮及相别时间，落了一身还满的雪梅正像愁之欲去还来；而下片由彼方措意，说从善留宋难归，托雁捎信无凭，心中所怀的离恨，就好比越走越远还生的春草那样无边无际。两者相形，倍觉愁肠寸断的凄苦和离恨常伴的幽怨。歇拍两句从动态写出离恨的随人而远，尤显生动，为人所称。', '清平乐（yuè）：原唐教坊曲名，后用为词牌名。调名取用汉乐府“清乐”“平乐”两乐调命名。双调，四十六字，八句，上片四仄韵，下片三平韵。
春半：即半春，春天的一半。唐代柳宗元《柳州二日》诗中有句：“宦情羁思共凄凄，春半如秋意转迷“。别来春半，指自分别以来，春天已过去一半，说明时光过得很快。
柔：吕本二主词、吴本二主词、侯本二主词、《尊前集》、《全唐诗》、《词综》等本中均作“愁”。柔肠，原指温柔的心肠，此指绵软情怀。
“砌下”句：指台阶下飘落的白梅花犹如雪片纷飞。砌（qì）下：台阶下。砌，台阶。落梅：指白梅花，开放较晚。
“拂了”句：指把满身的落梅拂去了又落了满身。
“雁来”句：是说鸿雁虽然来了，却没将书信传来。古代有凭借雁足传递书信的故事。《汉书·苏武传》中记载：“天子射上林中，得雁，足有系帛书。”故见雁就联想到了所思之人的音信。无凭：没有凭证，指没有书信。
遥：远。归梦难成：指有家难回。
恰如：正像。《全唐诗》《古今词统》《古今诗余醉》等本中均作”却如”；毛本《尊前集》中作“怯如”。
更行更远：指行程越远。更，越。还生：还是生得很多。还，仍然，还是。', '离别以来，春天已经过去一半，映入目中的景色掠起柔肠寸断。阶下落梅就像飘飞的白雪一样零乱，把它拂去了又飘洒得满满一身。
鸿雁已经飞回而音信毫无依凭，路途遥远，回去的梦也难形成。离别的愁恨正像春天的野草，越行越远越生。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749303572034f6596219", "shortContent": "这首小令相传是李煜亡国之前的作品。有的研究者甚而指实说，它是李煜请求宋太祖放还他的七弟从善而不可得的时候写的。如果把作者的《却登高文》等联系起来看，这种说法是有其可信之处的。但是，从作品本身所具有的深远境界和美学价值出发，却宁可把它的内容和含义理解得宽泛一些。这是一首代离人抒发愁恨的名篇。从作者的创作动因来讲，的确很可能是对景伤怀，枨触了内心深处对某一亲近者的想念之情，因而提笔成章的。不过，在创作...", "authors": ["刘扬忠"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892d9820695e6503fd74", "shortContent": "这首小令相传是李煜亡国之前的作品。有的研究者甚而指实说，它是李煜请求宋太祖放还他的七弟从善而不可得的时候写的。如果把作者的《却登高文》等联系起来看，这种说法是有其可信之处的。但是，从作品本身所具有的深远境界和美学价值出发，却宁可把它的内容和含义理解得宽泛一些。这是一首代离人抒发愁恨的名篇。从作者的创作动因来讲，的确很可能是对景伤怀，枨触了内心深处对某一亲近者的想念之情，因而提笔成章的。不过，在创作...", "authors": ["刘扬忠"], "pressName": "上海辞书出版社"}, {"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126df6c305cf0801816c27", "shortContent": "此词在《草堂诗余续集》、《古今诗余醉》调下有题“忆别”，词也是怀人之作。作者构造了一幅落梅如雪，芳草萋萋的春景，表达了他思念远人的缭乱心情以及绵长的离恨。这首词又传为宋曹勋作，见《松隐文集》卷四十，王仲闻已辨其非。\n\n清平乐，原为唐代教坊曲名，后用为词牌。双调，四十六字。又名“清平乐令”、“醉东风”、“忆萝月”。", "authors": [], "pressName": "崇文书局"}]', '俞平伯《唐宋词简释》：（“路遥”句）梦的成否原不在乎路的远近，却说路远以至归梦难成，语婉而意悲。
俞平伯《论诗词曲杂著》：于愁则喻春水，于恨则喻春草，颇似重复，而“恰似一江春水向东流”，以长句一气直下，“更行更远还生”，以短语一波三折，句法之变换，直与春水春草之姿态韵味融成一片，外体物情，内抒心象，岂独妙肖，谓之入神也。虽同一无尽，而千里长江，滔滔一往，绵绵芳草，寸接天涯，其所以无尽则不同尽也。词情调情之吻合，词之至者也。', 'indent', 1359922735, '57b935c68ac2470062e14ed3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10047, '浪淘沙', NULL, 980, 1229, 3, 5, '欧阳修', NULL, 10018, '57b98d625bbb50005347ace1', '宋', 'ci', '词', 'http://baike.baidu.com/view/328714.htm', '', '把酒祝东风，且共从容。垂杨紫陌洛城东，总是当时携手处，游遍芳丛。
聚散苦匆匆，此恨无穷。今年花胜去年红，可惜明年花更好，知与谁同？', '此词为春日与友人在洛阳城东旧地同游，有感而作。上片叙事，回忆昔日洛城游春赏花之欢聚。“把酒”二句从游宴起笔，特别提出词人的祝愿：祝愿春风长在，春光明媚，春花娇艳，让朋友“且共从容”，即一道悠闲地游赏春色，尽兴地聚宴欢畅，显示出洛阳春色之美妙、游宴之难遇、聚会之难得。“垂杨”三句补充交待了朋友聚宴的地点、环境，方始揭明此次“从容”乃是“洛城”之聚宴、赏花，“游遍芳丛”。今日游赏后朋友又将分手，谁能预料明年今日又将如何？遂生发出下片的抒发感慨。
“聚散”二句以“苦”、“恨”二字概括了宦海中人总是无穷无尽的匆匆而来，匆匆而去，苦恨交加、聚散无常的人生感受。最后，更以今年花胜去年，预期“明年花更好”，映衬明年朋友聚散之难卜，不知与谁一道重来洛城游芳，更进一层地深化了这种人生聚散无常之感。把别情熔铸于赏花中，将三年的花加以比较，层层推进，以惜花写惜别，构思新颖，富有诗意，是篇中的绝妙之笔，而别情之重，亦说明同友人的情谊之深。', '浪淘沙：又名《卖花声》、《曲入冥》、《过龙门》、《炼丹砂》。正体双调五十四字，前后片各五句、四平韵，多作激越凄壮之音。
把酒：端着酒杯。
从容：留恋，不舍。
紫陌：紫路。洛阳曾是东周、东汉的都城，据说当时曾用紫色土铺路，故名。此指洛阳的道路。洛城：指洛阳。
总是：大多是，都是。
匆匆：形容时间匆促。
“可惜”两句：杜甫《九日蓝田崔氏庄》诗：“明年此会知谁健，醉把茱萸仔细看。”', '端起酒杯向东方祈祷，请你再留些时日不要一去匆匆。洛阳城东垂柳婆娑的郊野小道，就是我们去年携手同游的地方，我们游遍了姹紫嫣红的花丛。
欢聚和离散都是这样匆促，心中的遗恨却无尽无穷。今年的花红胜过去年，明年的花儿将更美好，可惜不知那时将和谁相从？', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74a77d0ac1145494bb4c", "shortContent": "此词为春日与友人在洛阳城东旧地同游有感而作。据词意，在写作此词的去年春，友人亦曾同作者在洛城东同游。仁宗天圣九年（1031）三月，欧阳修至洛阳西京留守钱惟演幕作推官，与同僚尹洙和河南县（治所即在洛阳）主簿梅尧臣等诗文唱和，相得甚欢，这年秋后，梅尧臣调河阳（治所在今河南孟州市南）主簿，次年（明道元年，1032）春，曾再至洛阳，写有《再至洛中寒食》和《依韵和欧阳永叔同游近郊》等诗。欧阳修在西京留守幕前...", "authors": ["王思宇"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ae03048e64fbd9bd15", "shortContent": "此词为春日与友人在洛阳城东旧地同游有感而作。据词意，在写作此词的去年春，友人亦曾同作者在洛城东同游。仁宗天圣九年（1031）三月，欧阳修至洛阳西京留守钱惟演幕作推官，与同僚尹洙和河南县（治所即在洛阳）主簿梅尧臣等诗文唱和，相得甚欢，这年秋后，梅尧臣调河阳（治所在今河南孟县南）主簿，次年（明道元年，1032）春，曾再至洛阳，写有《再至洛中寒食》和《依韵和欧阳永叔同游近郊》等诗。欧阳修在西京留守幕前后...", "authors": ["王思宇"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3c7f0b9738b369b0f7", "shortContent": "此词为春日与友人在洛阳城东旧地同游有感而作。宋仁宗天圣九年（1031）三月，欧阳修至洛阳做推官，与同僚尹洙和河南县主簿梅尧臣等诗文唱和，相得甚欢。次年春，再至洛阳，此词应为此年所作。词中同游之人当指梅尧臣。\n\n上阕开篇即写与朋友开宴之情景。然而不同于以往，词人对宴会中觥筹交错、把酒言欢之景一字不提，开笔便直言举起酒杯，向东风祷告，希望它也能停下脚步，加入这故友相逢的宴会，与他们一道欣赏大好春光。虽...", "authors": ["马　瑶"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702d77683d193301533d", "shortContent": "此词为春日与友人在洛阳城东旧地同游有感而作。宋仁宗天圣九年（1031）三月，欧阳修至洛阳做推官，与同僚尹洙和河南县主簿梅尧臣等诗文唱和，相得甚欢。次年春，再至洛阳，此词应为此年所作。词中同游之人当指梅尧臣。\n\n上阕开篇即写与朋友开宴之情景。然而不同于以往，词人对宴会中觥筹交错、把酒言欢之景一字不提，开笔便直言举起酒杯，向东风祷告，希望它也能停下脚步，加入这故友相逢的宴会，与他们一道欣赏大好春光。虽...", "authors": ["马瑶"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312718cc26cbf3417f09583", "shortContent": "此词为春日与友人在洛阳城东旧地同游有感而作。宋仁宗天圣九年（1031）三月，欧阳修至洛阳做推官，与同僚尹洙和河南县主簿梅尧臣等诗文唱和，相得甚欢。次年春，再至洛阳，此词应为此年所作。词中同游之人当指梅尧臣。\n上阕开篇即写与朋友开宴之情景。然而不同于以往，词人对宴会中觥筹交错、把酒言欢之景一字不提，开笔便直言举起酒杯，向东风祷告，希望它也能停下脚步，加入这故友相逢的宴会，与他们一道欣赏大好春光。虽未...", "authors": ["马瑶"], "pressName": "崇文书局"}, {"bookId": "646a05a345e4710056dab21f", "bookTitle": "欧阳修诗文鉴赏辞典（珍藏本）", "articleId": "646c890f7da2f75ac708de8e", "shortContent": "此词为春日与友人在洛阳城东旧地同游有感而作。据词意，在写作此词的去年春，友人亦曾同作者在洛城东同游。仁宗天圣九年(1031)三月，欧阳修至洛阳西京留守钱惟演幕作推官，与同僚尹洙和河南县（治所即在洛阳）主簿梅尧臣等诗文唱和，相得甚欢，这年秋后，梅尧臣调河阳（治所在今河南孟州市南）主簿，次年（明道元年，1032）春，曾再至洛阳，写有《再至洛中寒食》和《依韵和欧阳永叔同游近郊》等诗。欧阳修在西京留守幕前...", "authors": ["王思宇"], "pressName": "崇文书局"}]', '俞陛云《唐五代两宋词选释》：因惜花而怀友，前欢寂寂，后会悠悠，至情语以一气挥写，可谓深情如水，行气如虹矣。', 'indent', 1418810958, '57af29b10a2b5800631c2b16', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10048, '卜算子 · 咏梅', NULL, 924, 9405, 3, 14, '陆游', NULL, 10019, '57b904a9d342d3005ac748fb', '宋', 'ci', '词', 'http://baike.baidu.com/subview/328650/4912436.htm', '', '驿外断桥边，寂寞开无主。已是黄昏独自愁，更著风和雨。
无意苦争春，一任群芳妒。零落成泥碾作尘，只有香如故。', '此词是南宋爱国诗人陆放翁所作。这首词以清新的笔调写傲然不屈的梅花，暗喻自己的坚贞不屈，笔致细腻，意味深隽，是咏梅词中的绝唱。此时放翁正处在人生的低谷，主战派士气低落，因而十分悲观，整首词十分悲凉，渲染了一种不畏强权的精神。', '卜算子：词牌名。相传是借用唐代诗人骆观光的绰号。骆观光写诗好用数字取名，人称「卜算子」。北宋时盛行此曲。明末清初·万红友《词律·卷三·卜算子》：「毛氏云：『骆义乌诗，用数名，人谓为「卜算子」，故牌名取之。』按山谷词『似扶著卖卜算』，盖取义以今卖卜算命之人也。又因秦湛词有『极目烟中百尺楼』之句，故《图谱》删『卜算子』而名『百尺楼』；然『卜算子』之名，得知较早也。」元高拭词注「仙吕调」。苏东坡词有「缺月挂疏桐」句，名《缺月挂疏桐》。秦处度词有「极目烟中百尺楼」句，名《百尺楼》。僧皎词有「目断楚天遥」句，名《楚天遥》。无名氏词有「蹙破眉峰碧」句，名《眉峰碧》。双调，四十四字，上下阕各两仄韵。两结亦可酌增衬字，化五言句为六言句，于第三字豆。宋教坊复演为慢曲，《乐章集》入「歇指调」，八十九字，前阕四仄韵，后阕五仄韵。
驿（yì）外：指荒僻、冷清之地。驿，驿站，供驿马或官吏中途休息的专用建筑。
断桥：一说「断」，通「簖」，簖桥乃是古时在为拦河捕鱼蟹而设簖之处所建之桥。
寂寞：孤单冷清。
无主：自生自灭，无人照管和玩赏。
更著（zhuó）：又遭到。著，同“着”，遭受，承受。
零落：凋谢、陨落。
碾（niǎn）：轧烂、压碎。
作尘：化作灰土。
香如故：香气依旧存在。', '驿站外断桥旁。梅花寂寞地开放、孤孤单单，无人来欣赏。黄昏里独处已够愁苦，又遭到风吹雨打而飘落四方。它花开在百花之首，却无心同百花争享春光，只任凭百花去嫉妒。即使花片飘落被碾作尘泥，也依然有永久的芬芳留在人间。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74de2cee9a0c24ec7d68", "shortContent": "这首《卜算子》，作者自注“咏梅”，可是，它意在言外，像“独爱莲之出淤泥而不染，濯清涟而不妖”的濂溪先生（周敦颐）以莲花自喻一样，作者正是以梅花自喻的。\n陆游曾经称赞梅花“雪虐风饕愈凛然，花中气节最高坚”（《落梅》）。梅花如此清幽绝俗，出于众花之上，可是如今竟开在郊野的驿站外面，紧临着破败不堪的“断桥”，自然是人迹绝少、寂寥荒寒、备受冷落了。从这一句可知它既不是官府中的梅，也不是名园中的梅，而是一株...", "authors": ["艾治平"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5e35914587d02f59079", "shortContent": "这首《卜算子》，作者自注“咏梅”，可是，它意在言外，像“独爱莲之出淤泥而不染，濯清涟而不妖”的濂溪先生（周敦颐）以莲花自喻一样，作者正是以梅花自喻的。\n陆游曾经称赞梅花“雪虐风饕愈凛然，花中气节最高坚”（《落梅》）。梅花如此清幽绝俗，出于众花之上，可是如今竟开在郊野的驿站外面，紧临着破败不堪的“断桥”，自然是人迹绝少、寂寥荒寒、倍受冷落了。从这一句可知它既不是官府中的梅，也不是名园中的梅，而是一株...", "authors": ["艾治平"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255e8f18b220af461fb", "shortContent": "这首《卜算子》，作者自注“咏梅”，可是，它意在言外，像“独爱莲之出淤泥而不染，濯清涟而不妖”的濂溪先生（周敦颐）以莲花自喻一样，作者正是以梅花自喻的。\n\n陆游曾经称赞梅花“雪虐风饕愈凛然，花中气节最高坚”（《落梅》）。梅花如此清幽绝俗，出于众花之上，可是如今竟开在郊野的驿站外面，紧临着破败不堪的“断桥”，自然是人迹绝少、寂寥荒寒、备受冷落了。从这一句可知它既不是官府中的梅，也不是名园中的梅，而是一...", "authors": ["艾治平"], "pressName": "上海辞书出版社"}, {"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88bac9ebcc6fbe96f7ce", "shortContent": "以上四句是说，那梅花本来无心与百花争夺春光，因此，任凭她们嫉妒而毫不在意。她的花瓣将随着风雨飘零，化为泥土并被过往的车轮碾作尘埃，唯有她那清幽的香气永不改变。前两句写照了词人不屑于媚俗邀宠、有别于一般官僚政客们的傲岸品格；后两句正凸显出他即便粉身碎骨也还是要坚持爱国理想、民族气节、君子操守的顽强意志。", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f4e73206168b2e020ee", "shortContent": "陆游一生爱梅，传世诗词作品中，与梅花相关者达一百六十余首。在他的笔下，梅花犹如大自然所孕育的花中精灵，既有“广寒宫中第一仙”（陆游《梅花》）的清雅，也有“得道自保冰雪颜”（陆游《梅》）的清高，更有“雪虐风饕愈凛然”（陆游《落梅》）的刚烈。曾许下“何方可化身千亿，一树梅花一放翁”（陆游《梅花绝句》）宏愿的陆游，真可算是对梅花情有独钟了。这阕《卜算子·咏梅》，便是其咏梅作品中最负盛名的一篇。\n\n这首词...", "authors": ["江俊伟"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127044c305cf0801816f14", "shortContent": "陆游一生爱梅，传世诗词作品中，与梅花相关者达一百六十余首。在他的笔下，梅花犹如大自然所孕育的花中精灵，既有“广寒宫中第一仙”（陆游《梅花》）的清雅，也有“得道自保冰雪颜”（陆游《梅》）的清高，更有“雪虐风饕愈凛然”（陆游《落梅》）的刚烈。曾许下“何方可化身千亿，一树梅花一放翁”（陆游《梅花绝句》）宏愿的陆游，真可算是对梅花情有独钟了。这阕《卜算子·咏梅》，便是其咏梅作品中最负盛名的一篇。\n\n这首词...", "authors": ["江俊伟"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271ffc305cf0801817112", "shortContent": "陆游一生爱梅，传世诗词作品中，与梅花相关者达一百六十余首。在他的笔下，梅花犹如大自然所孕育的花中精灵，既有“广寒宫中第一仙”（陆游《梅花》）的清雅，也有“得道自保冰雪颜”（陆游《梅》）的清高，更有“雪虐风饕愈凛然”（陆游《落梅》）的刚烈。曾许下“何方可化身千亿，一树梅花一放翁”（陆游《梅花绝句》）宏愿的陆游，真可算是对梅花情有独钟了。这阕《卜算子·咏梅》，便是其咏梅作品中最负盛名的一篇。\n这首词所...", "authors": ["江俊伟"], "pressName": "崇文书局"}]', '明·沈震峰《草堂诗馀·续集》：排涤陈言，大为梅誉。
明·潘游龙《古今诗馀醉·卷十三》：末二句大为梅誉。
明·钱允治《类编笺释续选草堂诗馀》：言梅虽零落，而香不替如初，岂群芳所能妒乎？皆称赞词中描写的梅花孤傲高洁的品格，又「知人论世」，由梅而称赏词人。
清·刘融斋《艺概·卷四》：陆放翁词，安雅清赡，其尤佳者，在苏（东坡）、秦（少游）间。', 'indent', 1360098336, '57b9210d5bbb50005b793876', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10049, '贾生', NULL, 341, 603, 1, 4, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383831/10382307.htm', '', '宣室求贤访逐臣，贾生才调更无伦。
可怜夜半虚前席，不问苍生问鬼神。', '《贾生》是唐代诗人李商隐的一首借古讽今的咏史诗，意在借贾谊的遭遇，抒写诗人怀才不遇的感慨。此诗是一首咏叹贾谊故事的七言绝句，但其着眼点，不在个人的穷通得失，而在于指出封建统治者不能真正重视人才，使其在政治上发挥作用。诗中选取汉文帝宣室召见贾谊，夜半倾谈的情节，写文帝不能识贤、任贤；“不问苍生问鬼神”则揭露了晚唐皇帝服药求仙，荒于政事，不顾民生的昏庸特性。该诗寓慨于讽，深刻而具有力度，在对贾谊怀才不遇的同情中，寄寓作者自己在政治上备受排挤、壮志难酬的感伤。', '贾生：指贾谊（前200~前168），西汉著名的政论家、文学家，力主改革弊政，提出了许多重要政治主张，但却遭谗被贬，一生抑郁不得志。
宣室：汉代长安城中未央宫前殿的正室。逐臣：被放逐之臣，指贾谊曾被贬谪。
才调：才华气质。
可怜：可惜，可叹。虚：徒然，空自。前席：在坐席上移膝靠近对方。
苍生：百姓。问鬼神：事见《史记·屈原贾生列传》。汉文帝接见贾谊，“问鬼神之本。贾生因具道所以然之状。至夜半，文帝前席。”', '汉文帝求贤，宣室召见被贬臣子。贾谊才能，确实高明无人能及。只是空谈半夜，令人扼腕叹息。文帝尽问鬼神之事，只字不提国事民生。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92e103572034f659e5c0", "shortContent": "贾谊贬长沙，久已成为诗人们抒写不遇之感的熟滥题材。作者独辟蹊径，特意选取贾谊自长沙召回，宣室夜对的情节作为诗材。《史记·屈贾列传》载：\n在一般封建文人心目中，这大概是值得大加渲染的君臣遇合盛事。但诗人却独具只眼，抓住不为人们所注意的“问鬼神”之事，翻出了一段新警透辟、发人深省的诗的议论。\n“宣室求贤访逐臣，贾生才调更无伦。”前幅纯从正面着笔，丝毫不露贬意。首句特标“求”、“访”（咨询），仿佛热烈颂...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9820695e6503ffff", "shortContent": "贾谊贬长沙，久已成为诗人们抒写不遇之感的熟滥题材。作者独辟蹊径，特意选取贾谊自长沙召回，宣室夜对的情节作为诗材。《史记·屈贾列传》载：\n\n贾生征见。孝文帝方受厘（刚举行过祭祀，接受神的福祐），坐宣室（未央宫前殿正室）。上因感鬼神事，而问鬼神之本。贾生因具道所以然之状。至夜半，文帝前席（在坐席上移膝靠近对方）。既罢，曰：“吾久不见贾生，自以为过之，今不及也。”\n\n在一般封建文人心目中，这大概是值得大...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d86c9ebcc6fbea1a106", "shortContent": "本篇借贾生的不幸遭遇抒写诗人怀才不遇的悲愤。汉文帝不采用贾生进步的政治主张，却向他问鬼神事，本末倒置，造成千古遗恨。义山怀经世之志，其抱负未有丝毫施展，官不挂朝籍，空将笔砚事人，这是他一生的憾事，因作《贾生》诗以寄慨。", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4dc26cbf3417f09399", "shortContent": "贾生，即贾谊，是西汉初年著名的文学家和政论家。他年轻时由河南郡守吴公推荐，被文帝召为博士，不到一年即被破格提为太中大夫。文帝试图升擢他为公卿，但遭到了群臣的反对。后来因为群臣的忌恨，被贬为长沙王太傅。几年后被召回长安，任梁怀王太傅。因梁怀王刘揖坠马而死，贾谊深怀歉疚，忧伤过度而死。\n\n在诗歌作品中，贾谊往往被看作失意的政治家形象，诗人以自身的遭遇寻求到契合点，通过对贾生的伤悼，抒发了自己才华湮没、...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270799761253910e90569", "shortContent": "贾生，即贾谊，是西汉初年著名的文学家和政论家。他年轻时由河南郡守吴公推荐，被文帝召为博士，不到一年即被破格提为太中大夫，文帝试图升擢他为公卿，但遭到了群臣的反对。后来因为群臣的忌恨，被贬为长沙王太傅。几年后被召回长安，任梁怀王太傅。因梁怀王刘揖坠马而死，贾谊深怀歉疚，忧伤过度而死。\n\n在诗歌作品中，贾谊往往被看作失意的政治家形象，诗人以自身的遭遇寻求到契合点，通过对贾生的伤悼，抒发了自己才华湮没、...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312714a77683d193301546c", "shortContent": "贾生，即贾谊，是西汉初年著名的文学家和政论家。他年轻时由河南郡守吴公推荐，被文帝召为博士，不到一年即被破格提为太中大夫。文帝试图升擢他为公卿，但遭到了群臣的反对。后来因为群臣的忌恨，被贬为长沙王太傅。几年后被召回长安，任梁怀王太傅。因梁怀王刘揖坠马而死，贾谊深怀歉疚，忧伤过度而死。\n在诗歌作品中，贾谊往往被看作失意的政治家形象。诗人以自身的遭遇寻求到契合点，通过对贾生的伤悼，抒发了自己才华湮没、遇...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64638a2cc0471b0062c88399", "shortContent": "贾谊贬长沙，久已成为诗人们抒写不遇之感的熟滥题材。作者独辟蹊径，特意选取贾谊自长沙召回，宣室夜对的情节作为诗材。《史记·屈原贾生列传》载：贾生征见。孝文帝方受厘（刚举行过祭祀，接受神的福祐），坐宣室（未央宫前殿正室）。上因感鬼神事，而问鬼神之本。贾生因具道所以然之状。至夜半，文帝前席（在坐席上移膝靠近对方）。既罢，曰：“吾久不见贾生，自以为过之，今不及也。”在一般封建文人心目中，这大概是值得大加渲...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '《艺苑雌黄》：严有翼曰：李义山诗：“可怜夜半虚前席，不问苍生问鬼神。”虽说贾谊，然反其意用之矣……直用其事，人皆能之，反其意而用之者，非识学素高，超越寻常拘挛之见，不规规然蹈袭前人陈迹者，何以臻此！
《诗薮》：晚唐绝……“可怜夜半虚前席，不问苍生问鬼神”，皆宋人议论之祖。间有极工者，亦气韵衰飒，天壤开、宝。然书情则凄怆而易动人，用事则巧切而工悦俗，世希大雅，或以为过盛唐，以眼观之，不待其辞毕矣。
《唐诗选脉会通评林》：以贾生而遇文帝，可谓获上矣，然所问不知其所策，信乎才难，而用才尤难！此后二句，诗时史断也。
《五朝诗善鸣集》：诗忌议论，憎其一发无馀耳。此诗议论之外，正多馀味。
《唐三体诗评》：贾生前席，犹为虚礼，况无宣室之访逮耶？自伤更在言外。
《唐诗别裁》：钱牧斋“绛灌但知谗贾泣，可思流汗愧陈平”，全学此种。
《玉溪生诗说》：纯用议论矣，却以唱叹出之，不见议论之迹。
《唐人万首绝句选评》：议论风格俱峻。
《诗境浅说续编》：玉溪绝句，属辞蕴籍，咏史诸作，则持正论，如咏《宫妓》及《涉洛川》、《龙池》、《北齐》与此诗皆是也。汉文、贾生，可谓明立遇合，乃召对青蒲，不求谠论，而涉想虚无，则孱主庸臣又何责耶？
《选玉溪生诗补说》：绝大议论、得未曾有。言外为求神仙者讽。
《唐人绝句精华》：程梦星《笼注》：“此谓李德裕谏武宗好仙也。”按诗责其不问苍生，则不止好仙为不当，且不恤国事，不重民生，尤非求贤之意，义更正大。', 'center', 1413385808, '57b966d37db2a200542a3a6a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10084, '短歌行', NULL, 1473, 29, 4, 8, '曹操', NULL, 10012, '57b902df5bbb50005b7835f1', '汉', 'shi', '诗', 'http://baike.baidu.com/subview/100592/5246408.htm', '', '对酒当歌，人生几何！譬如朝露，去日苦多。慨当以慷，忧思难忘。何以解忧？唯有杜康。青青子衿，悠悠我心。但为君故，沉吟至今。呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。
明明如月，何时可掇？忧从中来，不可断绝。越陌度阡，枉用相存。契阔谈讌，心念旧恩。月明星稀，乌鹊南飞。绕树三匝，何枝可依？山不厌高，海不厌深。周公吐哺，天下归心。', '《短歌行》是汉末政治家、文学家曹操以乐府古题创作的两首诗，是汉乐府旧题，属于《相和歌辞·平调曲》。这是第一首，通过宴会的歌唱，以沉稳顿挫的笔调抒写了诗人求贤如渴的思想和统一天下的雄心壮志。
全诗内容深厚，庄重典雅，感情充沛，充分发挥了诗歌创作的特长，准确而巧妙地运用了比兴手法，来达到寓理于情，以情感人的目的，历来被视为曹操的代表名作之一。', '对酒当歌：一边喝着酒，一边唱着歌。对，面对。当，应当。
几何：多少。
去日苦多：已经过去的日子太多了。用于感叹光阴易逝之语。
慨当以慷：指宴会上的歌声激昂慷慨。当以，这里「应当用」的意思。全句意思是，应当用激昂慷慨（的方式来唱歌）。
何以解忧：一作「以何解忧」。
杜康：相传是最早造酒的人，这里代指酒。
子，对对方的尊称；
青衿：周代读书人的服装，这里指代有学识的人。衿，古式的衣领。
悠悠：长久的样子，形容思虑连绵不断。
「青青子衿（jīn），悠悠我心」句：出自《诗经·郑风·子衿》。原写姑娘思念情人，这里用来比喻渴望得到有才学的人。
沉吟：原指小声叨念和思索，这里指对贤人的思念和倾慕。
「呦（yōu）呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙（shēng）」句：出自《诗经·小雅·鹿鸣》。呦呦，鹿叫的声音；苹，一作「萍」，艾蒿。
鼓：弹。
何时可掇（duō）：什么时候可以摘取呢？掇，拾取、摘取。掇，一作「辍（chuò）」，停止。何时可掇，意思就是什么时候可以停止呢？
越陌度阡：穿过纵横交错的小路。陌，东西向田间小路；阡，南北向的小路。
枉用相存：屈驾来访。枉，这里是「枉驾」的意思；用，以；存，问候、思念。
讌（yàn）：通「宴」。
三匝（zā）：三周。匝，周、圈。
何枝可依：一作「无枝可依」。
海不厌深：一本作「水不厌深」。这里是借用《管子·形解》中的话，原文是：「海不辞水，故能成其大；山不辞土，故能成其高；明主不厌人，故能成其众……」意思是表示希望尽可能多地接纳人才。', '面对着美酒高声放歌，人生的岁月能有几何？好比是清晨的露水日出就干，可悲可叹失去的日月已经很多。
慷慨激昂地唱着歌，内心忧虑却不能遗忘，用什么来消除忧愁？只有用美酒来狂欢。
穿青色衣领的学子，寄托着我悠长思慕之心。就是因为渴慕贤才，焦虑吟沉直到如今，
鹿儿嗷嗷鸣叫呼唤朋友，共享原野上找到的艾蒿。我有了尊贵的贵宾，更会设宴鼓乐盛情款待。
清明如月的博学贤才，什么时候被我招来？我的忧虑发自内心，日日夜夜都不会断绝，
有劳您走过阡陌小路远道跋涉，枉驾而来致意问候。久别重逢欢宴畅谈，感念您还结记着旧日的恩情。
月儿明亮的夜晚星辰稀疏，乌鹊寻找依托向南而飞。绕着大树飞翔三圈，不知可以依歇在哪根树枝？
大山永远不会嫌高，大海也永远不会嫌深。像周公那样虚心对待贤才，一定会得到天下人的拥戴。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecc99dbb8b379ee0a0def", "shortContent": "《三国演义》第四十八回有一段曹操横槊赋诗的描写。曹操平定北方后，率百万雄师，饮马长江，与孙权决战。是夜明月皎洁，他在大江之上置酒设乐，欢宴诸将。酒酣，操取槊立于船头，慷慨而歌。歌辞就是上面这首《短歌行》。\n这是一首很有名的诗，苏东坡在《前赤壁赋》中就提到它，后来经过小说家渲染，更是家喻户晓了。但此诗究竟写什么？唐代吴兢说它“言当及时为乐”（《乐府古题要解》）。罗贯中则又给此诗蒙上“诗谶”的迷信色彩...", "authors": ["张铁明"], "pressName": "上海辞书出版社"}, {"bookId": "64605c895b7b0d4f45fe6e6e", "bookTitle": "三曹诗文鉴赏辞典", "articleId": "646def26902ee364cc84ce9f", "shortContent": "《三国演义》第四十八回有一段曹操横槊赋诗的描写。曹操平定北方后，率百万雄师，饮马长江，与孙权决战。是夜明月皎洁，他在大江之上置酒设乐，欢宴诸将。酒酣，操取槊立于船头，慷慨而歌。歌辞就是上面这首《短歌行》。\n这是一首很有名的诗，苏东坡在《前赤壁赋》中就提到它，后来经过小说家渲染，更是家喻户晓了。但此诗究竟写什么？唐代吴競说它“言当及时为乐”（《乐府古题要解》）。罗贯中则又给此诗蒙上“诗谶”的迷信色彩...", "authors": ["张铁明"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f2afc5e6bb82b8cf0906c", "shortContent": "《三国演义》第四十八回有一段曹操横槊赋诗的描写。曹操平定北方后，率百万雄师，饮马长江，与孙权决战。是夜明月皎洁，他在大江之上置酒设乐，欢宴诸将。酒酣，操取槊立于船头，慷慨而歌。歌辞就是上面这首《短歌行》。\n这是一首很有名的诗，苏东坡在《前赤壁赋》中就提到它，后来经过小说家渲染，更是家喻户晓了。但此诗究竟写什么？唐代吴兢说它“言当及时为乐”（《乐府古题要解》）。罗贯中则又给此诗蒙上“诗谶”的迷信色彩...", "authors": ["张铁明"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f631a7da2f75ac71590f1", "shortContent": "《三国演义》第四十八回有一段曹操横槊赋诗的描写。曹操平定北方 后，率百万雄师，饮马长江，与孙权决战。是夜明月皎洁，他在大江之上置 酒设乐，欢宴诸将。酒酣，操取槊立于船头，慷慨而歌。歌辞就是上面这首《短歌行》。 \n\n这是一首很有名的诗，苏东坡在《前赤壁赋》中就提到它，后来经过小\n说家渲染，更是家喻户晓了。但此诗究竟写什么?唐代吴競说它“言当及 时为乐”(《乐府古题要解》)。罗贯中则又给此诗蒙上“诗谶...", "authors": ["张铁明"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6471f3bc30675327e1c0df82", "shortContent": "曹操平定北方后，率百万雄师，饮马长江，与孙权决战。是夜明月皎洁，他在大江之上置酒设乐，欢宴诸将。酒酣，操取槊立于船头，慷慨而歌，歌辞就是上面这首《短歌行》。\n\n这是一首很有名的诗，苏东坡在《前赤壁赋》中就提到它，后来经过小说家渲染，更是家喻户晓了。但此诗究竟写什么？唐代吴競说它“言当及时为乐”（《乐府古题要解》）。罗贯中则又给此诗蒙上“诗谶”的迷信色彩，说曹操“乌鹊南飞”诸句是不祥之兆，预示他赤壁...", "authors": ["张铁明"], "pressName": "上海辞书出版社"}]', '唐·吴兢《乐府古题要解》：魏武帝「对酒当歌，人生几何」……言当及时为乐。又旧说长歌短歌，大率言人寿命长短分定，不可妄求也。
宋·刘克庄《后村诗话·前集·卷一》：孔融、杨修俱毙其手，操之高深安在？身为汉相，而时人目以汉贼，乃以周公自拟，谬矣。
明·锺惺《古诗归》：「譬如朝露，去日苦多」：不用来日苦少，句觉尤妙。「但为君故，沈吟至今」：英雄何尝不笃于交情，然亦不泛。「明明如月」：如字幻极，乐府奇语。「契阔讌谈，心念旧恩」：惨刻处惨刻，厚道处厚道，各不妨，各不相讳所以为英雄。又云：四言至此，出脱《三百篇》殆尽，此其心手不粘滞处。「青青子衿」二句，「呦呦鹿鸣」四句，全写《三百篇》，而毕竟一毫不似，其妙难言。谭元春：少小时读之，不觉其细；数年前读之，不觉其厚。至细，至厚，至奇！英雄骚雅，可以验后人心眼。
明·许学夷《诗源辩体·卷三》、《诗源辩体·卷四》：徐昌谷云：「韦孟辈四言，窘缚不荡。曹公《短歌行》、子建《来日大难》，工堪为则矣。……。」愚按：……元瑞谓「曹公、子建二诗，虽精工华爽，而风雅典刑几尽」，斯并得之。……魏人乐府四言，如孟德《短歌行》、子桓《善哉行》、子建《飞龙篇》等，其源出于《采芝》、《鸿鹄》，轶荡自如，正是乐府之体，不当于风雅求之。
清·沈德潜《古诗源》：言当及时为乐也。「月明星稀」四句，喻客子无所依托。「山不厌高」四句，言王者不却众庶，故能成其大也。
清·陈沆《诗比兴笺·卷一》：此诗即汉高（祖）《大风歌》思猛士之旨也。「人生几何」发端，盖传所谓古之王者知寿命之不长，故并建圣哲，以贻后嗣。次两引《青衿》、《鹿鸣》二诗，一则求之不得，而沈吟忧思；一则求之既得，而笙簧酒醴。虽然，鸟则择木，木岂能择鸟？天下三分，士不北走则南驰耳。分奔吴蜀，栖皇未定，若非吐哺折节，何以来之。山不厌土，故能成其高；海不厌水，故能成其深；王者不厌士，故天下归心。说者不察，乃谓孟德禅夺已萌，而沈吟未决，畏人讥嫌。感岁月之如流，恐进退之失据。试问篇中《子衿》、《鹿鸣》之诗，「契阔燕谈」之语，当作何解？且孟德吐握求贤之日，犹王莽谦恭下士之初，岂肯直吐鄙怀，公言篡逆者乎？其谬甚矣。', 'indent', 1362183195, '57b8bde28ac2470062dea163', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10050, '记承天寺夜游', NULL, 457, 3406, 1, 14, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'wen', '文', 'http://baike.baidu.com/view/529722.htm', '', '元丰六年十月十二日夜，解衣欲睡，月色入户，欣然起行。念无与为乐者，遂至承天寺寻张怀民。怀民亦未寝，相与步于中庭。庭下如积水空明，水中藻、荇交横，盖竹柏影也。何夜无月？何处无竹柏？但少闲人如吾两人者耳。', '本文写于宋神宗元丰六年（西元一〇八三年），当时作者正因「乌台诗案」被贬谪到黄州任职。文中对月夜景色作了美妙描绘，真实的记录了作者当时生活的片段，表达东坡壮志难酬的苦闷，自解、自慰、自我排遣，同时表现出作者旷达乐观的人生态度。', '承天寺：故址在今湖北黄冈县城南。
元丰六年：西元一〇八三年。元丰，宋神宗赵顼年号。当时作者因乌台案被贬黄州已经四年。
户：一说指堂屋的门，又一说指窗户，这里指门。
欣然：高兴、愉快的样子。
念：考虑，想到。
张怀民：宋淸河（今河北淸河）人，名梦得，字怀民，东坡之友。元丰六年亦被贬到黄州，寓居承天寺。
空明：形容水的澄澈。在这里形容月色如水般澄净明亮的样子。
藻荇（xìng）：均为水生植物，这里是水草。藻，水草的总称。荇，一种多年生水草，叶子像心脏形，面绿背紫，夏季开黄花。
盖：句首语气词，这里可以译为「原来是」。
闲人：这里是指不汲汲于名利而能从容流连光景的人。东坡这时被贬为黄州团练副使，这里是一个有职无权的官，所以他十分清闲，自称「闲人」。', '元丰六年十月十二日夜晚，正脱下衣服准备睡觉，这时月光从门户射进来，（不由得生出夜游的兴致，于是）高兴地起身出门。想到没有可以共同游乐的人，就到承天寺寻找张怀民。张怀民也还没有睡觉，于是一起在庭院中散步。庭院中的月光宛如积水那样清澈透明。水藻、水草纵横交错，原来那是庭院里的竹子和松柏树枝的影子。哪一个夜晚没有月亮？哪个地方没有竹子和柏树呢？只是缺少像我们两个这样清闲的人罢了。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1fb34a8757d5a0edba2", "shortContent": "苏轼自己评论他的文学创作，有一段话很精辟：\n这段话，可与他的另一段话相补充：“夫昔之为文者，非能为之为工，乃不能不为之为工也。山川之有云雾，草木之有华实，充满勃郁而见于外，夫虽欲无有，其可得耶？”（《江行唱和集序》）\n这里最重要的一点是：文，是“充满勃郁”于内而不得不表现于外的东西。胸有“万斛泉源”，才能“不择地皆可出”；胸中空无所有，光凭技巧，就写不出好文章。苏轼的确是胸有“万斛泉源”的大作家。...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "64685a527f27182da3634ff1", "shortContent": "苏轼自己评论他的文学创作，有一段话很精辟：吾文如万斛泉源，不择地皆可出。在平地，滔滔汩汩，虽一日千里无难。及其与山石曲折，随物赋形，而不可知也。所可知者，常行于所当行，常止于不可不止，如是而已矣！其他，虽吾亦不能知也。（《文说》）\n\n这段话，可与他的另一段话相补充：“夫昔之为文者，非能为之为工，乃不能不为之为工也。山川之有云雾，草木之有华实，充满勃郁而见于外，夫虽欲无有，其可得耶？”（《江行唱和集...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "64720b4045e4710056fc7e66", "shortContent": "苏轼自己评论他的文学创作，有一段话很精辟：吾文如万斛泉源，不择地皆可出。在平地，滔滔汨汨，虽一日千里无难。及其与山石曲折，随物赋形，而不可知也。所可知者，常行于所当行，常止于不可不止，如是而已矣！其他，虽吾亦不能知也。（《文说》）这段话，可与他的另一段话相补充：“夫昔之为文者，非能为之为工，乃不能不为之为工也。山川之有云雾，草木之有华实，充满勃郁而见于外，夫虽欲无有，其可得耶？”（《江行唱和集序》...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '', 'indent', 1360702568, '57b97fd50a2b58005fc6b48a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10051, '宿骆氏亭寄怀崔雍崔衮', NULL, 272, 603, 1, 2, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/view/486518.htm', '', '竹坞无尘水槛清，相思迢递隔重城。
秋阴不散霜飞晚，留得枯荷听雨声。', '崔雍和崔衮，是崔戎的两个儿子，李商隐的从表兄弟。唐文宗大和七年（公元834年），李商隐应试不中，投奔做华州刺史的表叔崔​戎​。第二年，崔戎调任兖州观察使，没想刚到兖州就病故了。崔戎对李商隐不仅有亲戚之情，还有知遇之恩。崔戎的两个儿子崔雍、崔衮和李商隐也是情深义重。这首诗大概作于唐文宗大和八年，诗人离开崔家，旅宿在骆姓人家的园亭里，寂寥中怀念起两位朋友，写下了这首很有情韵的小诗。
全诗用笔极为简练，以竹坞、亭槛、流水、枯荷等极其普通的景物，勾勒出清幽绝妙的意境，并且把作者对崔雍、崔衮两兄弟丧父之悲的同情以及诗人自己的寂寥之感含蓄地传递出来。', '崔雍、崔衮：崔戎的儿子，李商隐的从表兄弟。
竹坞（wù）：丛竹掩映的池边高地。
水槛（jiàn）：指临水有栏杆的亭榭。此指骆氏亭。
迢递：遥远的样子。
重城：一道道城关。
秋阴不散霜飞晚：秋日阴云连日不散，霜期来得晚。
枯荷听雨声：雨滴枯荷，大约只有彻夜辗转难眠的人才能听到。', '竹丛里船坞深静无尘，临水的亭榭分外幽清。相思之情啊飞向远方，可却隔着重重的高城。
秋空上阴云连日不散，霜飞的时节也来迟了。留得满地枯残的荷叶，好听深夜萧瑟的雨声。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dc5e272d4b2254359e", "shortContent": "一个深秋的夜晚，诗人旅宿在骆姓人家的园亭里，寂寥中怀念起远隔重城的朋友，和枯荷听秋雨的意境，写下了这首很有情韵的小诗。题中的崔雍、崔衮，是诗人的重表叔兼知遇者崔戎的两个儿子。诗是和二崔告别后旅途中寄怀之作。\n首句写骆氏亭。“竹坞”，是竹林环抱荫蔽的船坞；“水槛”，指傍水的有栏杆的亭轩，也就是题中的“骆氏亭”。清澄的湖水，翠绿的修竹，把这座亭轩映衬得格外清幽雅洁。“无尘”和“清”，正突出了骆氏亭的这...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d7ff2af4e09d55b63b7", "shortContent": "首句谓胳氏亭临水而建，竹林掩映，景物清幽。次句谓怀友情深，久未通音问，仿佛思念崔氏兄弟之情谊被迢递高城阻隔住了。三四句谓秋天阴云不散，反觉霜期来迟；夜闻雨滴残荷之声，更觉孤独凄清，彻夜无眠。结句有无穷意味，交游零落，身世萧条，全在此中。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64631aefcd12b001c6df5128", "shortContent": "一个深秋的夜晚，诗人旅宿在骆姓人家的园亭里，寂寥中怀念起远隔重城的朋友，和枯荷听秋雨的意境，写下了这首很有情韵的小诗。题中的崔雍、崔衮，是诗人的重表叔兼知遇者崔戎的两个儿子。诗是和二崔告别后旅途中寄怀之作。\n\n首句写骆氏亭。“竹坞”，是竹林环抱荫蔽的船坞；“水槛”，指傍水的有栏杆的亭轩，也就是题中的“骆氏亭”。清澄的湖水，翠绿的修竹，把这座亭轩映衬得格外清幽雅洁。“无尘”和“清”，正突出了骆氏亭的...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '屈复《玉溪生诗意》：一骆氏亭，二寄怀，三见时，四情景，写“宿”字之神。
姚培谦《李义山诗集笺注》：秋霜未降，荷叶先枯，多少身世之感！
纪昀《玉溪生诗说》：分明自己无聊，却就枯荷雨声渲出，极有余味；若说破雨夜不眠，转尽于言下矣。“秋阴不散”起“雨声”，“霜飞晚”起“留得枯荷”，此是小处，然亦见得不苟。
何焯《李义山诗集辑评》：下二句暗藏永夜不寐，相思可以意得也。纪昀曰：不言雨夜无眠，只言枯荷聒耳，意味乃深。直说则尽于言下矣。又曰：“相思”二字，微露端倪，寄怀之意，全在言外。', 'center', 1361445779, '57b923d9128fe10054cab4dc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10052, '丑奴儿近 · 博山道中效李易安体', NULL, 249, 793, 4, 1, '辛弃疾', NULL, 10003, '57b8ed682e958a005fa4d096', '宋', 'ci', '词', 'http://baike.baidu.com/view/661798.htm', '', '千峰云起，骤雨一霎儿价。更远树斜阳，风景怎生图画？青旗卖酒，山那畔别有人家。只消山水光中，无事过这一夏。
午醉醒时，松窗竹户，万千潇洒。野鸟飞来，又是一般闲暇。却怪白鸥，觑着人欲下未下。旧盟都在，新来莫是，别有说话？', '博山位于上饶以东永丰县（今江西广丰）境内，淳熙十三年（公元1186年）前后，稼轩曾多次出游博山，这首词就是在往来途中所写。易安即李清照，擅长用清新、白描的手法来抒写自己的情感，这种特色被称为易安体词。本词即为作者效仿易安体所作。
此词写大雨后的山光水色的傍晚景色，上阕首写起云，次写骤雨，再次写放晴，体现了夏天山村的天气变化。下阕是作者设想在这里生活的情景。全词浅显明快，恬淡清新，反映了作者退居上饶后寄情山林的心情。文字秀丽、温婉，深似李清照词风。', '博山：地名，位于上饶以东永丰县境内，在今江西广丰县西南。南宋·王象之《舆地纪胜·卷二十一·〈江南东路·信州〉》：“博山在永丰西二十里，古名‘通元峰’，以形似庐山香炉峰，故改今名。”
效：学、仿。
李易安：李清照，自号易安居士，婉约派正宗词人。北宋末南宋初人，礼部郎济南李恪非之女，建康帅赵明诚之妻。南渡后不久，赵明诚病故。清照工诗文，尤以词擅名。其所作词，善于将寻常习用语言，随手拈来，度入音律，语言淡雅，格律严谨，练字琢句，意境新丽，卓然为宋代一大家。所著《李易安集》十二卷已佚，现仅后人所辑之《漱玉词》一卷行世。
体：写法、风格。
一霎儿价：四卷本作“一霎时价”，一会儿的功夫。宋·李易安《行香子·草际鸣蛩》词：“甚霎儿晴，霎儿雨，霎儿风。”价，语助词。
怎生：作怎么解。宋·李易安《声声慢·寻寻觅觅》词：“守着窗儿，独自怎生得黑。”
青旗：酒旗。
人家：四卷本作“人间”。
这一夏：王诏校刊本及《六十家词》本作“者一霎”，四印斋本作“者一夏”。
潇洒：从容大方，态度悠闲。
万千：作无限解。
旧盟：稼轩于退归带湖新居之初，有《水调歌头·盟鸥》一阕。
白鸥：水鸟名。', '乌云笼罩着群山，忽然下了一阵大雨，马上雨止了，天也晴了。在远处斜阳照在翠绿的树上，风景美丽动人，不知道画家们怎么描绘的！酒店的门上挂着卖酒的青旗，可想而知，在山的那边，另有人家居住。只要在这山光水色，美丽迷人的地方，没有什么事情扰乱我，平静地过一个夏天，就很幸福了。
午醉睡醒了，见窗外的苍松翠竹，郁郁葱葱，多么清静幽闲，心神舒畅自然。野鸟飞来飞去，和我一样的自由自在。却叫我奇怪的是：白鸥在天空往下斜看着，想要下来但又不下来；你这是为什么呢？咱们过去订的盟约还在，我是遵守归盟的，你是不是新来的？或者是另有什么话要说的呀？', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74e72cee9a0c24ec7d8f", "shortContent": "宋孝宗淳熙八年（1181），辛弃疾被劾去官，次年于江西上饶地区的带湖卜筑闲居，直至光宗绍熙三年（1192）再度起用，其间长达十年。这首词正是作于此时。\n词的上下片都是见景抒情，情景相生，写得明白如话而清新幽默。上片写的是博山道中的外景。博山在江西广丰县西南，“南临溪流，远望如庐山之香炉峰”，足见风景之秀美。开首三句，写得颇有季节特点，特别是“骤雨一霎儿价”，非常形象地写出了夏日阵雨的特点。阵雨过后...", "authors": ["陈允吉胡中行"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5e903572034f65a8bee", "shortContent": "宋孝宗淳熙八年（1181），辛弃疾被劾去官，次年于江西上饶地区的带湖卜筑闲居，直至光宗绍熙三年（1192）再度起用，其间长达十年。这首词正是作于此时。\n词的上下片都是见景抒情，情景相生，写得明白如话而清新幽默。上片写的是博山道中的外景。博山在江西广丰县西南，“南临溪流，远望如庐山之香炉峰”，足见风景之秀美。开首三句，写得颇有季节特点，特别是“骤雨一霎儿价”，非常形象地写出了夏日阵雨的特点。阵雨过后...", "authors": ["陈允吉胡中行"], "pressName": "上海辞书出版社"}, {"bookId": "64688f9830675327e19962ff", "bookTitle": "辛弃疾词鉴赏辞典（珍藏本）", "articleId": "6468d64a7f27182da365caa4", "shortContent": "宋孝宗淳熙八年(1181)，辛弃疾被劾去官，次年于江西上饶地区的带湖卜筑闲居，直至光宗绍熙三年(1192)再度起用，其间长达十年。这首词正是作于此时。\n词的上下片都是见景抒情，情景相生，写得明白如话而清新幽默。上片写的是博山道中的外景。博山在江西上饶广丰区西南，“南临溪流，远望如庐山之香炉峰”，足见风景之秀美。开首三句，写得颇有季节特点，特别是“骤雨一霎儿价”，非常形象地写出了夏日阵雨的特点。阵雨...", "authors": ["陈允吉　胡中行"], "pressName": "上海辞书出版社"}]', '夏承焘：这首词采用铺叙的手法，把景物一一展现在读者的面前。词的上阕以及下阕的前半，极力渲染风景的优美，环境的闲适。作者这样写的目的，是为了衬托最后五句所表达的失意的心情。通过白鸥的背盟，写出自己身世之感和生活道路的坎坷不平，不用一句直笔而收到很高的艺术效果。以淡景写浓愁，这也是辛稼轩词的一种常用的艺术手法。', 'indent', 1361445968, '57b8f5af7db2a20054265420', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10053, '喜外弟卢纶见宿', NULL, 151, 165, 1, 1, '司空曙', NULL, 10021, '57b967b98ac2470062e32d9a', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383419.htm', '', '静夜四无邻，荒居旧业贫。
雨中黄叶树，灯下白头人。
以我独沉久，愧君相见频。
平生自有分，况是蔡家亲。', '此诗是作者为表弟卢纶到家拜访有感而作。首句是写作者悲凉的境遇：年老独居荒野，近无四邻，孤苦无依，生活贫困。“雨中黄叶树，灯下白头人”一联写景抒情，把一位穷愁潦倒的白头老人的形象刻画得很丰满。后两句写对表弟到来的感激，这是写“喜”，但喜中仍有悲。喜的是因为自己被贬沉沦，亲人还来探望，自然喜出望外；但自己的处境不佳，又感到对不起亲人，所以仍感辛酸惭愧。全诗语言朴实，语调低沉悲切，真实感人。', '卢纶：作者表弟，与作者同属“大历十才子”。见宿：留下住宿。见：一作“访”。
旧业：指家中的产业。
以：因为。
自有分（fèn）：一作“有深分”。分：情谊。
蔡家亲：也作“霍家亲”。晋羊祜为蔡邕外孙，这里借指两家是表亲。', '静静的深夜四周没有相邻，居住在荒野因为家中清贫。
树上黄叶在雨中纷纷飘零，犹如灯下白发老人的命运。
自惭这样长久地孤独沉沦，辜负你频繁地来把我慰问。
我们是诗友生来就有缘分，更何况你我两家还是表亲。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b603048e64fbd91436", "shortContent": "司空曙和卢纶都在“大历十才子”之列，诗歌工力相匹，又是表兄弟。从这首诗，尤其是末联“平生自有分（情谊），况是蔡家亲（羊祜为蔡邕外孙，因称表亲为蔡家亲）”，可以看出他俩的亲密关系和真挚情谊，而且可以感受到作者生活境遇的悲凉。据元辛文房《唐才子传》卷四载，司空曙“磊落有奇才”，但因为“性耿介，不干权要”，所以落得宦途坎坷，家境清寒。这首诗正是作者这种境遇的写照。\n前四句描写静夜里的荒村，陋室内的贫士，...", "authors": ["林东海"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f09331", "shortContent": "外弟，即表弟。卢纶，大历十才子之一。这首诗写表弟卢纶来访，两人把酒话谈，诗人感慨良多，因成此篇。\n\n第一句交代时间地点。“静夜”，表明夜已深，与第四句“灯下”相呼应；“四无邻”，周遭没有邻居，一来更见静夜之静，二来呼应下句“荒居”之荒。连邻居都没有，可见地处之偏。“旧业贫”三字，见出诗人清贫苦寒的生活，与荒居、静夜形成因果，正因为贫困潦倒，故而只能住在这样简陋的荒居里。\n\n第三句点明季节天气。这是...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127069e6f69b71e93f62a8", "shortContent": "外弟，即表弟。卢纶，“大历十才子”之一。这首诗写表弟卢纶来访，两人把酒话谈，诗人感慨良多，因成此篇。\n\n第一句交代时间、地点。时值夜晚，与第四句“灯下”相呼应。“静夜”，表明夜已深；“四无邻”，周遭没有邻居，一来更见“静夜”之静，二来呼应下句“荒居”之荒。连邻居都没有，可见地处之偏。“旧业贫”三字，见出诗人清贫苦寒的生活，与荒居、静夜形成因果，正因为贫困潦倒，故而只能住在这样简陋的荒居里。\n\n第三...", "authors": ["张春晓"], "pressName": "崇文书局"}]', '范晞文《对床夜语》：诗人发兴遣语，往往不约而合。如“雨中山果落，灯下草虫鸣”，王维也。“树初黄叶日，人欲白头时”，乐天也。司空曙有云：“雨中黄叶树，灯下白头人”，句法王而意参白，然诗家不以为袭也。
谢榛《四溟诗话》：韦苏州曰“窗里人将老，门前树已秋”。白乐天曰：“树初黄叶日，人欲白头时”。司空曙曰：“雨中黄叶树，灯下白头人”。三诗同一机抒，司空为优，善状目前之景，无限凄感，见乎言表。又：晚唐人多用虚字，若司空曙“以我独沉久，愧君相见频”……此皆一句一意，虽瘦而健，虽粗而雅。
周珽《唐诗选脉会通评林》：深情剀切。
范大士《历代诗法》：得浩然之神髓。
蘅塘退士《唐诗三百首》：十字八层（“两中”一联下）。
高步瀛《唐宋诗举要》：三、四名句，“雨中”、“灯下”虽与王摩诘相犯，而意境各自不同，正不为病。
俞陛云《诗境浅说》：前半首写独处之悲，后言相逢之喜，反正相生，为律诗一格。', 'center', 1361446410, '57b8d80e2e958a005fa482ba', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10060, '六言诗  致彭德怀同志', NULL, 97, 106, 2, 0, '毛泽东', NULL, 10025, '57b8fb582e958a005fa52193', '当代', 'shi', '诗', 'http://baike.baidu.com/view/328684.htm', '', '山高路远坑深，大军纵横驰奔。
谁敢横刀立马？唯我彭大将军。', '1935年10月21日，到达陕北的红军迎击国民党35师骑兵团2000多人，毛泽东亲自在吴起镇西山督战迎敌，部署好战斗后，把指挥事宜交给彭德怀处理，战斗结束后，他当场赋此诗赠予彭德怀。这首诗中字里行间跳动着凯歌的欢快音符，更跳动着革命者那颗“爱将”之心。全诗仅浅明的六字白文，便充分表现了对将才的赞扬和称颂，在读者心目中树立起一位胸怀大略、指挥若定的彭大将军的高大形象。', '坑深：地势险峻。
唯我彭大将军：大战胜利毛泽东写诗赠于，首句即用电文句，但改“沟深”为“坑深”。彭德怀收到这首诗后，将诗的末句“唯我彭大将军”改为“唯我英勇红军”，然后将原诗送还了毛泽东。', '吴起镇山险路长沟深，中央红军骑马奔驰杀敌。有谁敢横刀立马，只有我彭德怀大将军。', '[{"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88ba7ccdb86c49e7aa12", "shortContent": "这首诗最早发表在一九四七年八月一日《战友报》（冀鲁豫军区政治部主办）。\n\n1935年10月，自中央红军主力进入西北高原后，敌“中央军”毛炳文部和宁夏马鸿逵、马鸿宾以及东北军的骑兵部队一直尾追不舍。10月19日，当红军进入陕北吴起镇时，毛泽东提出不能把敌人带进苏区，要把“尾巴”切掉。当日，毛泽东电召陕甘支队司令员彭德怀“来吴起镇商行动方针”。彭德怀20日赶到吴起镇后，毛泽东即与他筹划退敌之计，并决定...", "authors": ["胡为雄"], "pressName": "上海辞书出版社"}]', '', 'center', 1361898393, '57b8fb5e5bbb50005b77fc96', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (43382, '思明州', NULL, 0, 291, 0, 2, '陈孚', NULL, 11084, '5858e61e8e450a006c7f7e90', '元', 'shi', '诗', NULL, NULL, '刺竹丛丛苦笋生，山禽无数不知名。
元宵已似春深后，龙眼花开蛤蚧鸣。', NULL, NULL, NULL, NULL, NULL, 'center', 1525468301, '585ce9111b69e6006cc98583', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10061, '浪淘沙 · 北戴河', NULL, 243, 106, 3, 2, '毛泽东', NULL, 10025, '57b8fb582e958a005fa52193', '当代', 'ci', '词', 'http://baike.baidu.com/view/328704.htm', '', '大雨落幽燕，白浪滔天，秦皇岛外打鱼船。一片汪洋都不见，知向谁边？
往事越千年，魏武挥鞭，东临碣石有遗篇。萧瑟秋风今又是，换了人间。', '此词是作者于1954年于秦皇岛北戴河开会时创作。这首词生动描绘了北戴河海滨夏秋之交的壮丽景色，展示了无产阶级革命家前无古人的雄伟气魄和汪洋浩瀚的博大胸怀。', '浪淘沙：词牌名。
北戴河：在河北省东北部渤海边秦皇岛市西南海滨，是著名夏季休养地。
幽燕：古幽州及燕国，在今河北省北部及东北部。
滔天：形容水势很大，大到好像与天连接起来一样。
秦皇岛：三面环海，是渤海湾一个不冻良港，现已设为市，相传秦始皇求仙曾到此，它因此得名。
汪：指水势大，深且阔。
谁边：何处，哪里。
往事：过去的事，这里指公元二百零七年（建安十二年）曹操东征乌桓（古代部族名）经过碣石山时写下《观沧海》一诗之事；越：越过；千年：只是一个大概数，实际已一千七百多年。
魏武：即曹操（公元155~220年）。曹操死后，他儿子曹丕当上皇帝追封他为魏武帝。挥鞭：原指挥鞭策马，这里指骑马出征。
碣石：碣石是古代山名，位于现今何处，学术界尚有争议，河北乐亭说、河北昌黎说，山东无棣说等。本词应指的是位于河北昌黎。昌黎碣石山位于河北省昌黎城北1公里，与北戴河毗邻，面积28.8平方公里，形成历史久远，自然风光秀美，历史文化渊源，地理位置优越，是五岳之外的“神岳”，是古今中外有名的历史名山、仙山、观海胜地、佛教胜地和旅游胜地。遗篇：遗留下来的诗篇，指《观沧海》一诗。
萧瑟秋风：曹操《观沧海》：“秋风萧瑟，洪波涌起。”
人间：社会制度。', '大雨落在了幽燕，滔滔波浪连天，秦皇岛之外的打渔船，在起伏的波涛里都已经看不见，也不知漂去了哪里。
往事已经有千年，那时魏武帝曹操跃马挥鞭，东巡至碣石山吟咏过诗篇。秋风瑟瑟到了今日，人间却换了新颜。', '[{"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88ba7ccdb86c49e7aa1e", "shortContent": "这首词最早发表在《诗刊》一九五七年一月号。\n\n汉献帝建安十二年（207），时任大将军的曹操为清除边患，巩固后方，率大军北征乌桓。八月大破乌桓于柳城（今辽宁朝阳市南），九月凯旋，途经渤海口附近的碣石山，乘兴登临，以一首千古传颂的《观沧海》诗，描绘出一幅波澜壮阔的大海图景，抒发了诗人削平割据、统一中国的宏愿和自强不息、叱咤风云的豪情。\n\n1954年夏，毛泽东在北戴河，一日适逢海滨风雨大作，浪涛翻涌，他...", "authors": ["林一顺"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413196404, '57b9b7a92e958a0069329db6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10062, '卜算子 · 咏梅', NULL, 933, 106, 2, 7, '毛泽东', NULL, 10025, '57b8fb582e958a005fa52193', '当代', 'ci', '词', 'http://baike.baidu.com/subview/328650/4912437.htm', '读陆游咏梅词，反其意而用之', '风雨送春归，飞雪迎春到。已是悬崖百丈冰，犹有花枝俏。
俏也不争春，只把春来报。待到山花烂漫时，她在丛中笑。', '此词是毛泽东读陆游同题词，反其意而作。写梅花的美丽、积极、坚贞，不是愁而是笑，不是孤傲而是具有新时代革命者的操守与傲骨。', '卜算子：词牌名，骆宾王诗用数名，人称卜算子。山谷词“似扶著，卖卜算”，取卖卜算命的意思。
风雨送春归：出自辛弃疾《摸鱼儿》，“更能消几番风雨，匆匆春又归去”。
冰：冰雪。
犹：还，依然，仍然。
俏：俊俏，美好的样子；
烂漫：颜色鲜明而美丽。
丛中笑：百花盛开时，感到欣慰和高兴。', '风风雨雨把春天送走了，漫天飞雪又把春天迎来。悬崖已结百丈尖冰，但梅花依然傲雪俏丽竞放。
梅花她虽然美丽但不与桃李争艳比美，只是把春天消息来报。等到满山遍野开满鲜花之时，她却在花丛中笑。', '[{"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88bac9ebcc6fbe96f7cc", "shortContent": "这首词最早发表在人民文学出版社一九六三年十二月版《毛主席诗词》。\n\n梅花在中国传统文化中，和松、竹一起被称为“岁寒三友”，因为不畏严寒保持生机而成为逆境中坚守气节的象征。在中国传统文化中，梅花被不断吟咏，出现了许多脍炙人口的咏梅诗词。在这些咏梅诗词中，梅花的象征内涵被不断积淀、演化，具有了孤芳自赏、虽不为世俗理解却不改其志的意味，从而形成了一个较为固定的母题。\n\n毛泽东的这首《卜算子·咏梅》标题下...", "authors": ["闵慧"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413451018, '57b93fa4c4c97100559142ec', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10063, '洞仙歌', NULL, 352, 3406, 6, 3, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/865349.htm', '僕七岁时，见眉州老尼，姓朱，忘其名，年九十馀。自言尝随其师入蜀主孟昶宫中。一日，大热，蜀主与花蕊夫人夜起，避暑摩诃池上，作一词。朱具能记之。今四十年，朱已死久矣，人无知此词者，独记其首两句。暇日寻味，岂《洞仙歌令》乎？乃为足之云。', '冰肌玉骨，自清凉无汗。水殿风来暗香满。绣帘开，一点明月窥人，人未寝，欹枕钗横鬓乱。
起来携素手，庭户无声，时见疏星渡河汉。试问夜如何？夜已三更，金波淡，玉绳低转。但屈指西风几时来？又不道、流年暗中偷换。', '此词描述了五代时後蜀国君孟昶与其妃花蕊夫人夏夜在摩河池上纳凉的情景，着意刻绘了花蕊夫人姿质与心灵的美好、高洁，表达了词人对时光流逝的深深惋惜和感叹。全词清空灵隽，语意高妙，想象奇特，波澜起伏，读来令人神往。', '洞仙歌：词牌名。原唐教坊曲，後用为词牌。又名《洞仙歌令》、《洞仙歌慢》、《洞仙词》、《洞中仙》、《洞玄歌》、《羽仙歌》。据北宋李明远《太平广记·卷三十七·阳平谪仙》引《仙传拾遗》：「阳平谪仙，不言姓氏。初，九陇广元西人张守圭，仙君山有茶园。每岁召采茶人力百馀人，男女佣工者杂处园中。有一少年，自言无亲族，赁为摘茶，甚勤愿了慧。守圭怜之，以为义儿。又一女子，年二十，亦云无亲族，愿为义儿之妻。孝义端恪。守圭甚善之。一旦山水泛溢，市井路隔，盐酪既缺，守圭甚忧之。新妇曰：『此可买耳。』取钱出门十数步，置钱于树下，以杖叩树，得盐酪而归。後或有所需，但令叩树取之，无不得者。其术夫亦能之。因与邻妇十数人，于塴口市相遇，为买酒一碗，与妇饮之，皆大醉，而碗中酒不减。远近传说，人皆异之。守圭问其术受于何人。少年曰：『我阳平洞中仙人耳。因有小过，谪于人间。不久当去。』守圭曰：『洞府大小与人间城阙相类否？』对曰：『二十四化，各有一大洞，或方千里、五百里、三百里。其中皆有日月飞精，谓之伏晨之根，下照洞中，与世间无异。其中皆有仙王仙官、卿相辅佐，如世之职司。有得道之人，及积功迁神返生之士，皆居其中，以为民庶。每年三元大节，诸天各有上真，下游洞天，以观其所为善恶。人世生死兴废，水旱风雨，预关于洞中焉。龙神祠庙，血食之司，皆为洞府所统。二十四化之外，青城、峨嵋、益登、慈母、繁阳、嶓冢，皆亦有洞，不在十大洞天三十六小洞天之数。洞中仙曹，如人间郡县聚落耳，不可一一详记也。旬日之间，忽失其夫妇。』」调名本意即咏洞中仙人。敦煌曲中有此调，但与宋人所作词体式不同。此调有令词和有慢词两体。令词自八十三字至九十三字，常以《东坡乐府》之《洞仙歌令》为准，前後阕各三仄韵。音节舒徐，极骀宕摇曳之致。康伯可词名《洞仙歌令》，潘紫岩词名《羽仙歌》，袁通甫词名《洞仙词》。《宋史·乐志》名《洞中仙》，注「林钟商调」，又「歇指调」。金词注「大石调」。前阕第二句是上一、下四句法，後阕收尾八言句是以一去声字领下七言，紧接又以一去声字领下四言两句作结。前阕第二句亦有用上二、下三句法，并于全阕增一、二衬字，句豆平仄略异者。慢词自一百十八字至一百二十六字，柳耆卿《乐章集》「嘉景」词注「般涉调」，「乘兴閒泛兰舟」词注「仙吕调」，「佳景留心惯」词注「中吕调」，三词句读亦参差不一。按张南湖《诗馀图谱》，前阕六句三韵，後阕七句三韵，前後阕第三句俱七字，第四句俱九字，前阕结句六字，後阕结句九字，此令词正体也，间有摊破、添字句、添韵者，皆从此出。
题注：傅子立注：「公自序云：『仆七岁时，见眉州老尼，姓朱，忘其名，年九十馀。自言尝随其师入蜀主孟昶宫中。一日，大热，蜀主与花蕊夫人夜起，避暑摩诃池上，作一词。朱具能记之。今四十年，朱已死久矣，人无知此词者，独记其首两句。暇日寻味，岂《洞仙歌令》乎？乃为足之云。』」刘尚荣按：「此条题注原列调名下，今依全书体例移词後。『大热』，傅注本误作『大熟』，据元延祐本改。」元延祐本无「公自序云」四字，「仆」作「余」，「夜起避暑」作「夜纳凉」，「独记」作「但记」；明吴讷钞本「眉州」作「眉山」，「朱已死久矣」作「朱已死」，「独记」亦作「但记」，「乃为足之云」作「乃为足之」；《苏长公二妙集》本「朱已死久矣」作「朱已死矣」，「独记」亦作「但记」，「乃为足之云」作「乃为足之」。龙本「仆」作「余」，「眉州」作「眉山」，「年九十馀」作「年九十岁」，「夜起避暑」作「夜纳凉」，「独记」作「但记」；《苕溪渔隐丛话·前集卷二十五·〈洞仙歌〉》引此词「朱已死久矣」作「朱已死矣」，「独记其首两句」作「独记其首两句云『冰肌玉骨，自清凉无汗』」，馀同傅注。按，「公自序云」云云，见诸家诗话，《墨庄漫录·卷九》有详考，可参。
孟昶：龙榆生笺引清·吴任臣《十国春秋·卷四十九·〈後蜀·後主本纪〉》：「後主昶字保元，初名仁赞，高祖第三子也。……帝好学，为文皆本于理。居恒谓李昊、徐光溥曰：『王衍浮薄而好轻艳之辞，朕不为也。』然後主亦工声曲，有《相见欢》词。」
花蕊夫人：龙榆生笺宋·吴虎臣《能改斋漫录·卷十六·〈乐府·花蕊夫人词〉》：「伪蜀主孟昶，徐匡璋纳女于昶，拜贵妃，别号花蕊夫人，意花不足拟其色，似花蕊翾轻也。又升号慧妃，以号如其性也。王师下蜀，太祖闻其名，命别护送。途中作词自解曰：『初离蜀道心将碎，离恨绵绵。春日年，马上时时闻杜鹃。三千宫女皆花貌，妾最婵娟。此去朝天，只恐君王宠爱偏。』陈无已云夫人姓费、误也。」又引宋·蔡百衲《铁围山丛谈·卷六·花蕊夫人》：「花蕊夫人，蜀王建妾也，後号「小徐妃」者。大徐妃生王衍，而小徐妃其女弟。在王衍时，二徐坐游燕淫乱亡其国。庄宗平蜀後，二徐随王衍归中国，半途遭害焉。及孟氏再有蜀，传至其子昶，则又有一花蕊夫人，作宫词者是也。国朝降下西蜀，而花蕊夫人又随昶归中国。昶至且十日，则召花蕊夫人入宫中，而昶遂死。昌陵後亦惑之。尝进毒，屡为患，不能禁。太宗在晋邸时，数数谏昌陵，而未果去。一日兄弟相与猎苑中，花蕊夫人在侧，晋邸方调弓矢引满，政拟射走兽，忽回射花蕊夫人，一箭而死。始所传多伪，不知蜀有两花蕊夫人，皆亡国，且杀其身。」
冰肌玉骨：龙榆生笺：「宋玉《神女赋》：『温乎如莹。』《庄子·卷一·〈内篇·逍遥游〉》：『藐姑射之山，有神人居焉，肌肤若冰雪，绰约若处子。』杜子美《徐卿二子歌》：『秋水为神玉为骨。』」
一点明月：傅子立注：「杜子美《月诗》：『关山同一点。』」刘尚荣按：「句出《玩月呈汉中王》，见《九家集注杜诗·卷二十三》，『点』原作『照』。注引赵彦材云：『「照」字，旧一本作「点」，非也。「照」字乃出《月赋》「千里共明月」之意。』然而《补注杜诗·卷二十三》引黄希补注云：『「照」或作「点」，尝见善本如此，故东坡有「一点明月」之词。』」
钗横鬓乱：傅子立注：「公诗：『鬓乱钗横特地寒。』」刘尚荣按：「句见王荆公《临川集·卷二十七·题画扇诗》：『青冥风露非人世，鬓乱钗横特地寒。』别见《冷斋夜话·卷三·诸葛亮、刘伶、陶潜、李令伯文如肺腑中流出》、《能改斋漫录·卷八·沿袭》及宋李石林撰《王荆公诗注·卷四十一》。疑傅注误记作者或『公』上脱漏『荆』字。」龙榆生笺：「欧阳文忠《临江仙》词：『水精双枕，畔有堕钗横。』」
鬓乱：《苕溪渔隐丛话·前集卷二十五·〈洞仙歌〉》引此词作「云鬓乱」。
夜如何：傅子立注引《诗经·小雅·庭燎》：「夜如何其？夜未央。」
三更：毛本「三更」上衍「是」字。
玉绳：傅子立注：「谢玄晖：『金波丽鳷鹊，玉绳低建章。』」刘尚荣按：「谢句出《文选·卷二十六·谢玄晖〈暂使下都夜发新林至京邑赠西府同僚〉》。『金波』谓月光浮动，『玉绳』是星名，北斗七星之第五星。」龙榆生笺：「《文选·张平子〈西京赋〉》：『上飞闼而仰眺，正睹瑶光与玉绳。』李善注引《春秋元命苞》曰：『玉衡北两星为玉绳。』」《太平御览·卷五·天部五》：「《春秋元命苞》曰：『玉衡北两星为玉绳。玉之为言沟，刻也。瑕而不掩，折而不伤。』宋均注曰：『绳能直物，故名玉绳。沟，谓作器。』」玉衡，北斗第五星也。秋夜半，玉绳渐自西北转，冉冉而降，时为夜深或近晓也。
但屈指：明吴讷钞本、《苏长公二妙集》本、茅维《苏集》本、毛本皆作「但屈指」。元延祐本亦作「但屈指」，有校云：「一作『细屈指』」。《苕溪渔隐丛话·前集卷二十五·〈洞仙歌〉》引此词作「细屈指」。
西风几时来：傅子立注：「公《秋怀》诗：『苦热念西风，常恐来无时。』」刘尚荣按：「句见《东坡集·卷四·秋怀二首（其一）》。」', '肌肉骨头像冰玉般莹洁湿润，本来十分清凉没有一丝汗渍。晚风来水殿里丝丝暗香弥漫。绣帘撩开明月一点偷窥佳人，佳人斜倚在枕边还没有入眠，黄金钗横着堕着鬓发乱蓬蓬。
从床上坐起牵着白净玉手，起来漫步在寂静的庭院当中，时而可见细数流星渡过银河。试问夜色如何三更已经过去，月波淡玉绳星随着北斗低旋。屈指掐算什么时候送来寒冷，不知不觉流年似水悄然逝去。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b2dbb8b379ee08de8e", "shortContent": "坡公的词，手笔的高超，情思的深婉，使人陶然心醉，使人渊然以思，爽然而又怅然，一时莫明其故安在。继而再思，始觉他于不知不觉中将一个人生的哲理问题，已然提到了你的面前，使你如梦之冉冉惊觉，如茗之永永回甘，真词家之圣手，文事之神工，他人总无此境。\n即如此篇，其写作来由，老坡自家交代得清楚：“仆七岁时见眉山老尼姓朱，忘其名，年九十余，自言：尝随其师入蜀主孟昶宫中。一日大热，蜀主与花蕊夫人夜起避暑摩诃池上，...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b92cee9a0c24ed9e4f", "shortContent": "坡公的词，手笔的高超，情思的深婉，使人陶然心醉，使人渊然以思，爽然而又怅然，一时莫明其故安在。继而再思，始觉他于不知不觉中将一个人生的哲理问题，已然提到了你的面前，使你如梦之冉冉惊觉，如茗之永永回甘，真词家之圣手，文事之神工，他人总无此境。\n即如此篇，其写作来由，老坡自家交代得清楚：“仆七岁时见眉山老尼姓朱，忘其名，年九十余，自言：尝随其师入蜀主孟昶宫中。一日大热，蜀主与花蕊夫人夜起避暑摩诃池上，...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253f534825dee9fd6e6", "shortContent": "坡公的词，手笔的高超，情思的深婉，使人陶然心醉，使人渊然以思，爽然而又怅然，一时莫明其故安在。继而再思，始觉他于不知不觉中将一个人生的哲理问题，已然提到了你的面前，使你如梦之冉冉惊觉，如茗之永永回甘，真词家之圣手，文事之神工，他人总无此境。\n\n即如此篇，其写作来由，老坡自家交代得清楚：“仆七岁时见眉山老尼姓朱，忘其名，年九十余，自言：尝随其师入蜀主孟昶宫中。一日大热，蜀主与花蕊夫人夜起避暑摩诃池上...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7b7ccdb86c49f28f74", "shortContent": "朱本卷二：“案公生丙子，七岁为壬午，又四十年为壬戌也。”故编元丰五年壬戌（1082），作于黄州。薛本、邹王本从之。\n\n关于此词本事的记载歧义迭出，可参薛本考证及吴洪泽《〈洞仙歌〉（冰肌玉骨）公案考索》、闫小芬《苏轼〈洞仙歌〉杂考》。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3d73206168b2e020c6", "shortContent": "《洞仙歌》，又名《羽仙歌》、《洞仙词》等。这首词作于元丰五年（1082），时值苏轼因“乌台诗案”被贬居黄州，同期作品还有《赤壁赋》和《念奴娇》（赤壁怀古）。该词通过追忆五代后蜀国君孟昶及其宠妃花蕊夫人夜起纳凉之事，寄寓自己对时光流逝、人生蹉跎的感慨。\n关于这首词的创作，由词前小序可知，词人是根据小时候的记忆来创作该词，故更多是凭自己的想象以及结合自身的境遇和感悟来塑造人物形象，所以词中人物已基本脱...", "authors": ["吕青霞"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702e7ccdb86c49f291f4", "shortContent": "《洞仙歌》，又名《羽仙歌》、《洞仙词》等。这首词作于元丰五年（1082），时值苏轼因“乌台诗案”被贬居黄州，同期作品还有《赤壁赋》和《念奴娇》（赤壁怀古）。该词通过追忆五代后蜀国君孟昶及其宠妃花蕊夫人夜起纳凉之事，寄寓自己对时光流逝、人生蹉跎的感慨。\n\n关于这首词的创作，由词前小序可知，词人是根据小时候的记忆来创作该词，故更多是凭自己的想象以及结合自身的境遇和感悟来塑造人物形象，所以词中人物已基本...", "authors": ["吕青霞"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271aac9ebcc6fbea1a4e9", "shortContent": "《洞仙歌》，又名《羽仙歌》《洞仙词》等。这首词作于元丰五年（1082），时值苏轼因“乌台诗案”被贬居黄州，同期作品还有《赤壁赋》和《念奴娇·赤壁怀古》。该词通过追忆五代后蜀国君孟昶及其宠妃花蕊夫人夜起纳凉之事，寄寓自己对时光流逝、人生蹉跎的感慨。\n关于这首词的创作，由小序可知，词人是根据小时候的记忆来创作该词，故更多是凭自己的想象以及结合自身的境遇和感悟来塑造人物形象，所以词中人物已基本脱离原型，...", "authors": ["吕青霞"], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646836d5b6a81d0c5301f283", "shortContent": "坡公的词，手笔的高超，情思的深婉，使人陶然心醉，使人渊然以思，爽然而又怅然，一时莫明其故安在。继而再思，始觉他于不知不觉中将一个人生的哲理问题，已然提到了你的面前，使你如梦之冉冉惊觉，如茗之永永回甘，真词家之圣手，文事之神工，他人总无此境。\n\n即如此篇，其写作来由，老坡自家交代得清楚：“仆七岁时见眉山老尼姓朱，忘其名，年九十余，自言：尝随其师入蜀主孟昶宫中。一日大热，蜀主与花蕊夫人夜起避暑摩诃池上...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}]', '张子贤《墨庄漫录·卷九》：东坡作长短句《洞仙歌》所谓「冰肌玉骨，自清凉无汗」者，公自叙云：「予幼时见一老人，年九十馀，能言孟蜀主时事，云：『蜀主尝与花蕊夫人夜起，纳凉于摩诃池上，作《洞仙歌令》。老人能歌之。予今但记其首两句，乃为足之。』」近见李公彦季成《诗话》乃云：「杨元素作本事记《洞仙歌》：『冰肌玉骨，自清凉无汗。』钱唐有老尼能诵後主诗首章两句，後人为足其意，以填此词。」其说不同。予友陈兴祖德昭云：「顷见一诗话，亦题云『李季成』作，乃全载孟蜀主一诗：『冰肌玉骨清无汗，水殿风来暗香满。帘间明月独窥人，欹枕钗横云鬓乱。﻿﻿三更庭院悄无声，时见疏星度河汉。屈指西风几时来，只恐流年暗中换。』云东坡少年遇美人，喜《洞仙歌》，又邂逅处景色暗相似，故檃括稍协律以赠之也。予以谓此说近之。」据此乃诗耳，而东坡自叙乃云是《洞仙歌令》，盖公以此叙自晦耳。《洞仙歌》腔出近世，五代及国初，未之有也。
胡元任《苕溪渔隐丛话·前集卷二十五·〈洞仙歌〉》：「《漫叟诗话》云：『杨元素作《本事曲》，记《洞仙歌》：「冰肌玉骨，自清凉无汗，水殿风来暗香满。绣帘开，一点明月窥人，人未寝，欹枕钗横云鬓乱。起来携素手，庭户无声，时见疏星渡河汉。试问夜如何？夜已三更，金波淡，玉绳低转。细屈指，西风几时来，又不道流年暗中偷换。」钱塘有一老尼，能诵後主诗首章两句，後人为足其意，以填此词。余尝见一士人诵全篇云：「冰肌玉骨清无汗，水殿风来暗香暖，帘开明月独窥人，欹枕钗横云鬓乱。起来琼户启藻声，时见疏星渡河汉，屈指西风几时来，只恐流年暗中换。」』」
晚清·郑瘦碧曰：坡老改添此词数字，诚觉气象万千，其声亦如空山鸣泉，琴筑竞奏。', 'indent', 1361908109, '57b8d4ed2e958a005fa47a94', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10064, '抱朴子 · 外篇 · 博喻卷第三十八', NULL, 44, 3, 1, 1, '葛洪', NULL, 36987, '5c1c4a40fb4ffe005f19698b', '晋', 'wen', '文', 'https://baike.baidu.com/item/%E6%8A%B1%E6%9C%B4%E5%AD%90%E5%A4%96%E7%AF%87/12514817', '', '抱朴子曰：志合者，不以山海为远；道乖者，不以咫尺为近。故有跋涉而游集， 亦或密迩而不接。', '《抱朴子外篇》则主要谈论社会上的各种事情，属于道家政治范畴，也反映了葛洪道本儒末的思想轨迹。其内容可具体概括为：论人间得失，讥刺世俗，讲治民之法；评世事臧否，主张藏器待时，克己思君；论谏君主任贤能，爱民节欲，独掌权柄；论超俗出世，修身著书等。总之，《抱朴子》将玄学与道教神学，方术与金丹、丹鼎与符、儒学与仙学统统纳为一体之中，从而确立了道教神仙理论体系。', '', '', NULL, '', 'indent', 1413469578, '57b8f8487db2a2005426638f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10065, '前出师表', NULL, 725, 60, 0, 14, '诸葛亮', NULL, 10026, '57b8f8452e958a005fa50d86', '三国', 'wen', '文', 'http://baike.baidu.com/view/433685.htm', '', '先帝创业未半而中道崩殂，今天下三分，益州疲弊，此诚危急存亡之秋也。然侍卫之臣不懈于内，忠志之士忘身于外者，盖追先帝之殊遇，欲报之于陛下也。诚宜开张圣听，以光先帝遗德，恢弘志士之气，不宜妄自菲薄，引喻失义，以塞忠谏之路也。
宫中府中，俱为一体，陟罚臧否，不宜异同。若有作奸犯科及为忠善者，宜付有司论其刑赏，以昭陛下平明之理，不宜偏私，使内外异法也。
侍中、侍郎郭攸之、费祎、董允等，此皆良实，志虑忠纯，是以先帝简拔以遗陛下。愚以为宫中之事，事无大小，悉以咨之，然后施行，必能裨补阙漏，有所广益。
将军向宠，性行淑均，晓畅军事，试用于昔日，先帝称之曰能，是以众议举宠为督。愚以为营中之事，悉以咨之，必能使行阵和睦，优劣得所。
亲贤臣，远小人，此先汉所以兴隆也；亲小人，远贤臣，此后汉所以倾颓也。先帝在时，每与臣论此事，未尝不叹息痛恨于桓、灵也。侍中、尚书、长史、参军，此悉贞良死节之臣，愿陛下亲之信之，则汉室之隆，可计日而待也。
臣本布衣，躬耕于南阳，苟全性命于乱世，不求闻达于诸侯。先帝不以臣卑鄙，猥自枉屈，三顾臣于草庐之中，咨臣以当世之事，由是感激，遂许先帝以驱驰。后值倾覆，受任于败军之际，奉命于危难之间，尔来二十有一年矣。
先帝知臣谨慎，故临崩寄臣以大事也。受命以来，夙夜忧叹，恐托付不效，以伤先帝之明，故五月渡泸，深入不毛。今南方已定，兵甲已足，当奖率三军，北定中原，庶竭驽钝，攘除奸凶，兴复汉室，还于旧都。此臣所以报先帝而忠陛下之职分也。至于斟酌损益，进尽忠言，则攸之、祎、允之任也。
愿陛下托臣以讨贼兴复之效；不效，则治臣之罪，以告先帝之灵。若无兴德之言，则责攸之、祎、允等之慢，以彰其咎。陛下亦宜自谋，以咨诹善道，察纳雅言，深追先帝遗诏。臣不胜受恩感激。今当远离，临表涕零，不知所言。', '此文出自于《三国志·卷三十五·诸葛亮传》，是三国时期蜀汉丞相诸葛亮在北伐中原之前给后主刘禅上书的表文，阐述了北伐的必要性以及对后主刘禅治国寄予的期望，言辞恳切，写出了诸葛亮的一片忠诚之心。这篇表文以议论为主，兼用记叙和抒情。', '先帝创业未半而中道崩殂：一作“臣亮言：先帝创业未半而中道崩殂”。先帝，指蜀昭烈帝刘备，先，尊称死去的人。
创：开创、创立。
业：统一天下的大业。
中道：中途。
崩殂（cú）：死。崩，古时指皇帝死亡；殂，死亡。
今：现在。
三分：天下分为孙权，曹操，刘备三大势力。
益州：汉代行政区域十三刺史部之一，包括今四川省和陕西省一带。这里指蜀汉。
疲弊：人力缺乏，物力缺无，民生凋敝。
益州疲弊：指蜀汉的处境艰难；
「此诚危急存亡之秋也」句：指关键时期，一般多指不好的。此，这；诚，的确、实在；之，的；秋，时，时候。
然：然而。
侍：侍奉。
卫：护卫。
懈：松懈、懈怠。
于：在。
内：皇宫中。
忘身：舍身忘死、奋不顾身。
盖：原来。
追：追念。
殊遇：优待、厚遇。
诚：的确、确实。
宜：应该。
开张圣听：扩大圣明的听闻，意思是要后主广泛地听取别人的意见。开张，扩大。
光：发扬光大，用作动词。
遗德：留下的美德。
恢弘：发扬扩大，用作动词。恢，大；弘，大、宽。
气：志气。
妄自菲薄：过于看轻自己。妄，过分；菲薄，小看、轻视。
引喻失义：讲话不恰当。引喻，称引、譬喻；喻，比如；义，适宜、恰当。
以：以致（与以伤先帝之明的以用法相同：以致）；
塞：阻塞。
谏：劝谏。
宫：指皇宫。
府：指丞相府。
俱：通「具」，全、都。
陟（zhì）：提升、奖励。
罚：惩罚。
臧否（pǐ）：善恶，这里用作动词，意思是评论人物好坏。
作奸犯科：做奸邪事情，触犯科条法令。作奸，做了奸邪的事情；科，科条、法令。
及：以及。
为：做。
有司：职有专司，就是专门管理某种事情的官吏。
刑：罚。
昭：显示、表明。
平：公平。
明：严明。
理：治理。
偏私：偏袒、有私心。
内外异法：内宫和外府刑赏之法不同。内外，指内宫和外府；异法，刑赏之法不同。
志：志向。
虑：思想、心思。
忠纯：忠诚纯正。
简：选择；一说通「拣」，挑选。
拔：选拔。
遗（wèi）：给予。
悉以咨之：都拿来跟他们商量。悉，全部；咨，询问、商议、征求意见；之，指郭攸之等人。
必能裨（bì）补阙漏：一定能够弥补缺点和疏漏之处。裨，补；阙，通「缺」，缺点、疏漏。
有所广益：有所启发和帮助；广益，增益；益，好处。
性行（xíng）淑均：性情善良品德端正；淑，善；均，平。
晓畅：精通。
试用：任用。
督：武职，向宠曾为中部督（禁卫军统帅）。
营：军营、军队。
行（háng）阵：指部队。
优劣得所：好的差的各得其所。
小人：晚辈，下人，这里指宦官。
倾颓：倾覆衰败。
痛恨：痛惜、遗憾
死节：为国而死的气节，能够以死报国。
隆：兴盛。
计日：计算着天数，指时日不远。
布衣：平民、百姓。
躬：亲自。
耕：耕种。
南阳：当时南阳郡，今河南南阳和湖北襄阳城西一带。
苟：苟且。
全：保全。
闻达：显达扬名、扬名显贵。
卑鄙：地位、身份低微，见识短浅。卑，身份低微；鄙，地处偏远。与今义不同。
猥（wěi）：辱，这里有降低身份的意思。
枉屈：枉驾屈就。
顾：探望。
感激：有所感而情绪激动。
许：答应。
驱驰：奔走效劳。
有：通「又」，跟在数词后面表示约数。
临崩寄臣以大事：刘备在临死的时候，把国家大事托付给诸葛亮，并且对刘禅说：「汝与丞相从事，事之如父。」；临：将要、临近。
夙夜忧叹：早晚忧虑叹息。
泸：水名，即如今的金沙江。
不毛：不长草木，这里指人烟稀少的地方。毛，庄稼、苗。
兵：武器。
甲：装备。
奖率：奖赏率领。
庶：希望。竭：竭尽。
驽（nú）钝：比喻才能平庸，这是诸葛亮自谦的话。驽，劣马，走不快的马，指才能低劣。钝，刀刃不锋利。
攘（rǎng）除：排除、铲除。
奸凶：奸邪凶恶之人，此指曹魏政权。
还：回。
于：到。
旧都：指东汉都城洛阳。
此臣所以报先帝而忠陛下之职分也：这是我用来报答先帝，效忠陛下的职责本分。所以，用来……的是
斟酌损益：斟情酌理、有所兴办。比喻做事要掌握分寸。（处理事务）斟酌情理，有所兴革。损，除去；益，兴办、增加。
托臣以讨贼兴复之效：把讨伐曹魏复兴汉室的任务交付给我。托，托付、交付；效，效命的任务。
不效则治臣之罪：没有成效就治我的罪。
告：告慰、告祭。
兴德之言：发扬陛下恩德的忠言。
慢：怠慢、疏忽，指不尽职。
彰其咎：揭示他们的过失。彰，表明、显扬；咎，过失，罪。
咨诹（zōu）善道：询问（治国的）良策。诹，询问、咨询。
察纳：识别采纳。察，明察；雅言，正确的言论、合理的意见。
深追：深刻追念。
先帝遗诏：刘备给后主的遗诏，见《三国志·蜀志·先主传》注引《诸葛亮集》，诏中说：「勿以恶小而为之，勿以善小而不为。惟贤惟德，能服于人。」遗诏，皇帝在临终时所发的诏令。
当：在……时候。
临：面对。
涕零：一作「涕泣」，眼泪。
零：落下。
不知所言：不知道再该说些什么。', '先帝创业还没有完成一半，就中途去世了。如今天下分为三国，我们蜀汉国力困弊，这真是危急存亡的时刻啊。然而侍卫臣僚在内勤劳不懈，忠心的将士在外舍身忘死，这是因为他们追念先帝的特殊恩遇。想在您的身上进行报答。您应该广泛听取臣下的意见，以发扬光大先帝遗留下的美德。激发志士的勇气，不应当妄自菲薄。援引不恰当的譬喻，以堵塞忠言进谏的道路。
宫禁中的侍卫、各府署的臣僚都是一个整体，赏罚褒贬，不应有所不同。如有作恶违法的人，或行为忠善的人，都应该交给主管官吏评定对他们的惩奖，以显示陛下处理国事的公正严明。不应该有所偏爱，使宫内宫外执法不同。
侍中郭攸之、费祎、董允等人，都是善良诚实、心志忠贞纯洁的人，因此先帝选拔他们留给陛下。我认为宫中之事，无论大小，都去咨询他们，然后施行，必能弥补缺失，集思广益。
将军向宠，心性品德善良平和，又通晓军事。过去经过试用，先帝称赞他很有才能，因此众人商议推举他做中部督。我认为禁军营中的事都去咨问于他，必能使军队和睦，不同才能的人各得其所。
亲近贤臣，疏远小人，这是前汉所以兴盛的原因；亲近小人，疏远贤臣。这是后汉之所以衰败的原因。先帝在世时，每次与臣谈论这事，未尝不叹息而痛恨桓帝、灵帝时期的腐败。侍中、尚书、长史、参军，这些人都是忠贞善良、守节不逾的大臣。希望陛下亲近他们，信任他们，那么汉朝的复兴，就会指日可待了。
我原本一个平民，在南阳亲自耕田。只想在乱世里苟全性命，不求在诸侯间扬名显身。先帝不因为我卑微鄙陋，而委屈自己，三次到草庐中来拜访我。向我询问天下大事，由此使我感动奋发，而同意为先帝奔走效力。后来遭遇失败，我在军事失利之际接受任命。形势危急之时奉命出使，从这以来二十一年了。
先帝知道我做事谨慎，所以临终把国家大事托付给我。接受遗命以来，我日夜忧虑叹息。惟恐托付的事不能完成，有损于先帝的英明。因此五月渡泸南征，深入不毛之地。现在南方已经平定，兵甲已经充足，我应当勉励统率三军，北定中原，以便竭尽我拙劣的能力。扫除姦邪、兴复汉室、返还旧都。这是我用以报答先帝尽忠陛下的职责，至于处置日常之事，决定取舍损益，毫无保留地贡献忠言，那是郭攸之、费祎、董允的责任。
希望陛下把讨伐汉贼、兴复汉室的任务交给我去完成；若不能完成，就治我的罪，以告于先帝的英灵。如果不能进献增进圣德的忠言，那就责备郭攸之、费祎、董允的怠慢。以表明他们的过失。陛下也应当谋求自强，征询臣下的意见，考察并采纳正确的言论，深思先帝的遗诏。臣蒙受大恩，不甚感激。
现在即将远离，一边写表，一边流泪，真不知该说些什么。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1db911759740c9bdc9f", "shortContent": "诸葛亮并不是一个文学家，而所著《出师表》却成为千古传诵的文学名篇。诚如宋代大文豪苏轼所说：“诸葛孔明不以文章自名，而开物成务之姿，综练名实之意，自见于言语。至《出师表》，简而尽，直而不肆，大哉言乎，与《伊训》、《说命》相表里，非秦汉以来以事君为悦者所能至也。”（见《乐全先生文集叙》）一篇不到八百字的短文，看似平实无奇，竟受到后人如此高度的赞扬，其原因何在呢？\n无庸讳言，封建社会里的士大夫们看重《出...", "authors": ["蒋哲伦"], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f4f6542516c6dedf0a", "shortContent": "诸葛恪为东吴老臣诸葛瑾之子，少时以才思敏捷而出名。因其父诸葛瑾脸长，常被讥为驴，一次宴会中，孙权令人牵来一头驴，上书“诸葛子瑜”，诸葛恪却非常冷静，执笔在下填“之驴”二字，众人皆大笑，孙权即以驴赐诸葛恪。类似这样的故事颇为不少，每遇到棘手的问题，诸葛恪都能机智应对，他的回答既保全了诸葛家族的体面，也给予孙权皇族颇高的台阶，尽显其高情商、高智商。\n孙权有意识地栽培诸葛恪。最初，孙权命他在丹阳等地平定...", "authors": ["赵思渊"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "647206bca5f1e74f9587fafe", "shortContent": "此文写于后主建兴五年(227)诸葛亮率师北伐中原之际，而作者却把笔墨集中在修明内政这一点上。前半对后主进谏，直接谈朝政问题，后半自己述志，亦是落脚到劝刘禅“咨诹善道，察纳雅言”上来。为什么这样写呢？因为北伐曹魏、统一天下，是蜀汉建国以来的既定方针，而为了争取北伐的胜利，事前也作了一系列准备工作。这些都是本已明了的事，不必赘言。诸葛亮放心不下的，是他率领大军出征后的国内政治。他考虑到，只有把内部政局...", "authors": ["蒋哲伦"], "pressName": "上海辞书出版社"}]', '', 'indent', 1445192225, '57b8e26d5bbb50005b778035', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10072, '采桑子 · 重阳', NULL, 353, 106, 1, 3, '毛泽东', NULL, 10025, '57b8fb582e958a005fa52193', '当代', 'ci', '词', 'http://baike.baidu.com/view/328665.htm', '', '人生易老天难老，岁岁重阳。今又重阳，战地黄花分外香。
一年一度秋风劲，不似春光。胜似春光，寥廓江天万里霜。', '此词作于1929年重阳节，为当年阳历10月11日。毛泽东在闽西征途中，欣逢重阳佳节，触景生情，因成此词。诗情画意，最为浓郁。它写了泞秋的战地风光，写得那么鲜明爽朗；它表现了对自然和人生的看法，表现得那么豪迈乐观。天空海阔，气度恢宏。使人读过以后，毫无感到肃飒之气，而会受到无限鼓舞。', '重阳：重阳节农九月九日，为传统的重阳节，又称「老人节」。
岁岁：年年。
今又重阳：此重阳是指诗人在战地重逢的重阳，民國八年（公元1929年）的重阳。
战地：这里指闽西农村根据地，当时这里外有敌人包围，内有地主民团的扰乱。
黄花：指菊花。
分外：格外。
劲：强劲。
不似：不类似，不像。
胜似春光：是说秋风比春光更美，是主观感受。
寥廓：指宇宙的广阔，也指广阔高远。
江天：指汀江流域的天空。', '人的一生容易衰老而苍天却不老，重阳节年年都会来到。今天又逢重阳，战场上的菊花是那样的芬芳。
一年又一年秋风刚劲地吹送，这景色不如春天的光景那样明媚。却比春天的光景更为壮美，如宇宙般广阔的江面天空泛着白霜。', '[{"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88b9f2af4e09d5508bf1", "shortContent": "这首词最早发表在《人民文学》一九六二年五月号。\n\n“悲哉秋之为气也，萧瑟兮草木摇落而变衰。”自战国时期楚国宋玉的《九辩》问世以来，悲秋就成为中国古典诗赋的传统主题。而前人以九九重阳为题材的诗章词作，则更借凄清、肃杀、衰飒的秋景托怨情，兴别恨，少有不着一“悲”字的。诸如王维的“遥知兄弟登高处，遍插茱萸少一人”（《九月九日忆山东兄弟》），杜甫的“弟妹萧条各何在，干戈衰谢两相催”（《九日》），苏轼的“万...", "authors": ["林一顺"], "pressName": "上海辞书出版社"}]', '', 'indent', 1423166801, '57b93fae0a2b58005c946187', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10066, '后出师表', NULL, 60, 60, 1, 1, '诸葛亮', NULL, 10026, '57b8f8452e958a005fa50d86', '三国', 'wen', '文', 'http://baike.baidu.com/view/364431.htm', '', '先帝深虑汉、贼不两立，王业不偏安，故托臣以讨贼也。以先帝之明，量臣之才，故知臣伐贼才弱敌强也；然不伐贼，王业亦亡，惟坐而待亡，孰与伐之？是故托臣而弗疑也。
臣受命之日，寝不安席，食不甘味，思惟北征，宜先入南，故五月渡泸，深入不毛，并日而食。臣非不自惜也，顾王业不得偏全于蜀都，故冒危难以奉先帝之遗意也，而议者谓为非计。今贼适疲于西，又务于东，兵法乘劳，此进趋之时也。
谨陈其事如左：高帝明并日月，谋臣渊深，然涉险被创，危然后安。今陛下未及高帝，谋臣不如良、平，而欲以长计取胜，坐定天下，此臣之未解一也。刘繇、王朗各据州郡，论安言计，动引圣人，群疑满腹，众难塞胸，今岁不战，明年不征，使孙策坐大，遂并江东，此臣之未解二也。曹操智计殊绝于人，其用兵也，仿佛孙、吴，然困于南阳，险于乌巢，危于祁连，偪于黎阳，几败北山，殆死潼关，然后伪定一时耳，况臣才弱，而欲以不危而定之，此臣之未解三也。曹操五攻昌霸不下，四越巢湖不成，任用李服而李服图之，委任夏侯而夏侯败亡，先帝每称操为能，犹有此失，况臣驽下，何能必胜？此臣之未解四也。自臣到汉中，中间期年耳，然丧赵云、阳群、马玉、阎芝、丁立、白寿、刘合、邓铜等及曲长、屯将七十馀人，突将、无前。賨叟、青羌、散骑、武骑一千馀人，此皆数十年之内所纠合四方之精锐，非一州之所有，若复数年，则损三分之二也，当何以图敌？此臣之未解五也。今民穷兵疲，而事不可息，事不可息，则住与行劳费正等，而不及今图之，欲以一州之地与贼持久，此臣之未解六也。
夫难平者，事也。昔先帝败军于楚，当此时，曹操拊手，谓天下以定。然后先帝东连吴、越，西取巴、蜀，举兵北征，夏侯授首，此操之失计而汉事将成也。然后吴更违盟，关羽毁败，秭归蹉跌，曹丕称帝。凡事如是，难可逆见。臣鞠躬尽瘁，死而后已，至于成败利钝，非臣之明所能逆睹也。', '这份表章作于汉室三分之际，表现了作者兴邦建业，忠贞不二的品格。本文善于表达，通过举例来论证自己的观点，毫无呆板说教之嫌。通读本文，诸葛亮那份为国为君鞠躬尽瘁的精神令后人景仰，一句「死而后已」将那颗赤诚之心表现得淋漓尽致。由于本文是第一次北伐失败后所作，为提升士气，稳定朝局，作者在议论上气势宏伟，感情上慷慨豪迈。六个「臣之未解」将文章之气逐层提拔以至巅峰。与此同时，说理上义正词严，间接地将苟安之心驳斥地体无完肤。气生于理，理又借助气则更见立论之高远，虽无惊人之笔，但仍很具说服力和震撼效果。', '汉：指蜀汉。
贼：指曹魏。古时往往把敌方称为贼。
偏安：指王朝局处一地，自以为安。
孰与：何如，表示抉择，倾向肯定后一种（偏指一方）
惟：助词。
入南：指诸葛亮深入南中，平定四郡事。
并日：两天合作一天。
顾：这里有「但」的意思。
蜀都：此指蜀汉之境。
议者：指对诸葛亮决意北伐发表不同意见的官吏。
「故冒危难以奉先帝之遗意也，而议者谓为非计」句：建兴六年（公元228年）诸葛亮初出祁山（在今甘肃省礼县东）时，曹魏西部的南安、天水、安定三郡叛变，牵动关中局势：在魏、吴边境附近的夹石（今安徽省桐城县北），东吴大将陆逊击败魏大司马曹休两事。
进趋：快速前进。
高帝：刘邦死后的谥号为「高皇帝」。
并：平列。
渊深：指学识广博，计谋高深莫测。
「涉险被创」句：刘邦在楚汉战争中，屡败于楚军，公元前203年，在广武（今河南省荥阳县）被项羽射伤胸部：在汉朝初建时，因镇压各地的叛乱而多次出征，公元前195年又曾被淮南王英布的士兵射中；公元前200年在白登山还遭到匈奴的围困。被创，受创伤；被，通假字，同「披」
良：张良，汉高祖的著名谋士，与萧何、韩信被称为「汉初三杰」。
平：陈平，汉高祖的著名谋士。后位至丞相。
长计：长期相持的打算。
坐：安安稳稳。
未解：不能理解。胡三省认为「解」应读作「懈」，未解，即未敢懈怠之意。两说皆可通。
刘繇（yáo）：字正礼，东汉末年任扬州刺史，因受淮南大军阀袁术的逼迫，南渡长江，不久被孙策攻破，退保豫章（今江西省南昌市），后为豪强笮融攻杀。《三国志·吴书》有传。
王朗：字景兴，东汉末年为会稽（治所在今浙江省绍兴市）太守，孙策势力进入江浙时，兵败投降，后为曹操所征召，仕于曹魏。
孙策：字伯符，孙权的长兄。父孙坚死后，借用袁术的兵力，兼并江南地区，为孙吴政权的建立打下基础，不久遇刺身死。
江东：指长江中下游地区。
殊绝：极度超出的意思。
孙：指孙武，春秋时人，曾为吴国将领，善用兵，著有兵法十三篇。
吴：指吴起，战国时兵家、法家代表人物，先后仕于鲁、魏、楚，著有《吴子兵法》。
困于南阳：建安二年（公元197年）曹操在宛城（今河南省南阳市，汉时南阳郡的治所）为张绣所败，身中流矢。
险于乌巢：建安五年（公元200年），曹操与袁绍在官渡相持，因乏粮难支，在荀彧等人的劝说下，坚持不退，后焚烧掉袁绍在乌巢所屯的粮草，才得险胜。
危于祁连：这里的「祁连」，据胡三省说，可能是指邺（在今河北省磁县东南）附近的祁山，当时建安九年（公元204年）曹操围邺，袁绍少子袁尚败守祁山（在邺南面），操再败之，并还围邺城，险被袁将审配的伏兵所射中。
偪于黎阳：建安七年（公元202年）五月，袁绍死，袁谭、袁尚固守黎阳（今河南浚县东），曹操连战不克。
几败北山：事不详。可能指建安二十四年（公元219年），曹操率军出斜谷，至阳平北山（今陕西沔县西），与刘备争夺汉中，备据险相拒，曹军心涣，遂撤还长安。
殆死潼关：建安十六年（公元211年），曹操与马超、韩遂战于潼关，在黄河边与马超军遭遇，曹操避入舟中，马超骑兵沿河追射之。殆，几乎。
伪定：此言曹氏统一北中国，僭称国号。诸葛亮以蜀汉为正统，因斥曹魏为「伪」。
昌霸：又称昌豨。建安四年（公元199年），刘备袭取徐州，东海昌霸叛曹，郡县多归附刘备。
四越巢湖：曹魏以合肥为军事重镇，巢湖在其南面。而孙吴在巢湖以南长江边上的须濡口设防，双方屡次在此一带作战。
李服：建安四年，车骑将军董承根据汉献帝密诏，联络将军吴子兰、王子服和刘备等谋诛曹操，事泄，董承、吴子兰、王服等被杀。据胡三省云：「李服，盖王服也。」
夏侯：指夏侯渊。曹操遣夏侯渊镇守汉中。刘备取得益州之后，于建安二十四年出兵汉中，蜀将黄忠于阳平关定军山（今陕西省沔县东南）击杀夏侯渊。
汉中：郡名，以汉水上流（沔水）流经而得名，治所在南郑（今陕西省汉中县东）。
期（jī）年：一周年。
赵云：蜀中名将。
阳群等：事迹不详。
曲长、屯将：部曲中的将领。
突将、无前：蜀军中的冲锋将士。
賨叟（cóngsǒu）、青羌：蜀军中的少数民族部队。
散骑、武骑：都是骑兵的名号。
图：对付。
平：同「评」，评断。
败军于楚：指建安十三年（公元208年），曹操大军南下，刘备在当阳长坂被击溃事。当阳属古楚地，故云。
拊手：拍手。
以定：已定，以，同「已」。
「东连吴、越」句：刘备遣诸葛亮去江东连和，孙刘联军在赤壁大破曹军。
「西取巴、蜀」句：指建安十六年（公元211年）刘备势力进入刘璋占据的益州，后来攻下成都，取得巴蜀地区。
授首：交出脑袋。
关羽：字云长，蜀汉大将，刘备入川时，镇守荆州，建安二十四年（公元219年），他出击曹魏，攻克襄阳，擒于禁，斩庞德，威震中原。孙权趁机用吕蒙计谋偷袭荆州，擒杀关羽父子。
秭归蹉跌（cuōdiē）：指刘备因孙权背盟，袭取荆州，杀害关羽，就亲自领兵伐吴，在秭归（在今湖北省宜昌市北）被吴将陆逊所败。蹉跌，失坠，喻失败。
曹丕：字子桓，曹操子。在建安二十五年（公元220年）废汉献帝为山阳公，建立魏国，是为魏文帝。
逆见：预见、预测。
鞠躬尽瘁：一作「鞠躬尽力」。指为国事用尽全力。', '先帝考虑到蜀汉和曹贼不能并存，帝王之业不能苟且偷安于一地，所以委任臣下去讨伐曹魏。以先帝那样的明察，估量臣下的才能，本来就知道臣下要去征讨敌人，是能力微弱而敌人强大的。但是，不去讨伐敌人，王业也是要败亡的；是坐而待毙，还是主动去征伐敌人呢？因此委任臣下，一点也不犹疑。
臣下接受任命的时候，睡不安稳，食无滋味。想到要去北伐，应该先南征。所以五月里渡过泸水，深入不毛之地，两天才能吃上一餐；臣下不是不爱惜自己，而是看到帝王之业不可能局处在蜀地而得以保全，所以冒着危险，来执行先帝的遗愿，可是争议者说这不是上策。而敌人恰好在西面疲于对付边县的叛乱，东面又要竭力去应付孙吴的进攻，兵法要求趁敌方劳困时发动进攻，当前正是赶快进军的时机呵！现在谨将这些事陈述如下：
高祖皇帝的明智，可以和日月相比，他的谋臣见识广博，谋略深远，但还是要经历艰险，身受创伤，遭遇危难然后才得安定。现在，陛下比不上高祖皇帝，谋臣也不如张良、陈平，而想用长期相持的战略来取胜，安安稳稳地平定天下，这是臣所不能理解的第一点。
刘繇、王朗，各自占据州郡；在议论安守策略时，动辄引用古代圣贤的话，大家疑虑满腹，胸中充斥着惧难；今年不去打仗，明年不去征讨，让孙策安然强大起来，终于并吞了江东，这是臣下所不能理解的第二点。
曹操的智能谋略，远远超过别人，他用兵像孙武、吴起那样，但是在南阳受到窘困，在乌巢遇上危险，在祁山遭到厄难，在黎阳被敌困逼，几乎惨败在北山，差一点死在潼关，然后才得僭称国号于一时。何况臣下才能低下，而竟想不冒艰险来平定天下，这是臣下所不能理解的第三点。
曹操五次攻打昌霸而攻不下；四次想跨越巢湖而未成功，任用李服，而李服密谋对付他；委用夏侯渊，而夏侯渊却败死了。先帝常常称赞曹操有能耐，可还是有这些挫败，何况臣下才能低劣，怎能保证一定得胜呢？这是臣下所不能理解的第四点。
自从臣下进驻汉中，不过一周年而已，期间就丧失了赵云、阳群、马玉、阎芝、丁立、白寿、刘郃、邓铜等将领及部曲将官、屯兵将官七十余人；突将、无前、賨叟、青羌、散骑、武骑等士卒一千余人。这些都是几十年内从各处积集起来的精锐力量，不是一州一郡所能拥有的；如果再过几年，就会损失原有兵力的三分之二，那时拿什么去对付敌人呢？这是臣下所不能理解的第五点。
如今百姓贫穷兵士疲乏，但战争不可能停息；战争不能停息，那末耽在那里等待敌人来进攻和出去攻击敌人，其劳力费用正是相等的。不趁此时去出击敌人，却想拿益州一地来和敌人长久相持，这是臣下所不能理解的第六点。
最难于判断的，是战事。当初先帝兵败于楚地，这时候曹操拍手称快，以为天下已经平定了。但是，后来先帝东面与孙吴连和，西面取得了巴蜀之地，出兵北伐，夏侯渊掉了脑袋；这是曹操估计错误。看来复兴汉室的大业快要成功了。但是，后来孙吴又违背盟约，关羽战败被杀，先帝又在秭归遭到挫败，而曹丕就此称帝。所有的事都是这样，很难加以预料。臣下只有竭尽全力，到死方休罢了。至于伐魏兴汉究竟是成功是失败，是顺利还是困难，那是臣下的智力所不能预见的。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1db5914587d02f5a013", "shortContent": "《后出师表》是历代传诵的名篇，同时又是一篇著作者有争议的文章。这篇文章未见载于晋陈寿所进原编《诸葛亮集》，而出自三国时吴人张俨的《默记》（见《三国志·诸葛亮传》裴松之注引《汉晋春秋》），后世颇有人怀疑其真实可靠性，但历来仍将它视为《前出师表》的姐妹篇，宋司马光奉敕编集《资治通鉴》时亦将此表全文照录。而“鞠躬尽瘁（力），死而后已”二句，则成为诸葛亮为国事竭尽心力的千古名言。\n细细玩味，前、后两表所依...", "authors": ["蒋哲伦"], "pressName": "上海辞书出版社"}]', '', 'indent', 1462664205, '57b8f8ea128fe10054c952cd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10067, '论语 · 先进篇 · 第二十六章', NULL, 81, 327, 1, 2, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '子路、曾皙、冉有、公西华侍坐。子曰：「以吾一日长乎尔，毋吾以也。居则曰：『不吾知也。』如或知尔，则何以哉？」
子路率尔而对曰：「千乘之国，摄乎大国之间，加之以师旅，因之以饥馑；由也为之，比及三年，可使有勇，且知方也。」
夫子哂之。
「求，尔何如？」
对曰：「方六七十，如五六十，求也为之，比及三年，可使足民。如其礼乐，以俟君子。」
「赤，尔何如？」
对曰：「非曰能之，愿学焉。宗庙之事，如会同，端章甫，愿为小相焉。」
「点，尔何如？」
鼓瑟希，铿尔，舍瑟而作，对曰：「异乎三子者之撰。」
子曰：「何伤乎？亦各言其志也！」曰：「莫春者，春服既成，冠者五六人，童子六七人，浴乎沂，风乎舞雩，咏而归。」
夫子喟然叹曰：「吾与点也。」
三子者出，曾皙后。曾皙曰：「夫三子者之言何如？」
子曰：「亦各言其志也已矣！」
曰：「夫子何哂由也？」
曰：「为国以礼，其言不让，是故哂之。唯求则非邦也与？安见方六七十如五六十而非邦也者？唯赤则非邦也与？宗庙会同，非诸侯而何？赤也为之小，孰能为之大？」', '', '侍：侍奉。
侍坐：此处指执弟子之礼，侍奉老师而坐。
以吾一日长乎尔：以，因为；长，年长。
毋吾以也：吾，作「以」的宾语，在否定句中代词宾语前置。以，动词，用。
居：平时，平日在家的时候。
则：连词，就。
如或：如果有人。如：连词，如果。或：无定代词，有人。
则：连词，那么，就。
何以：用什么（去实现自己的抱负）。以，动词，用。
率尔：轻率急忙地样子；尔，助词，用作修饰语的词尾。
对：回答。
乘：车辆。春秋时，一辆兵车，配甲士3人，步卒72人，称一乘。
摄：夹，迫近。
乎：于，在。
师：军队。
因：动词，继，接续，接着。
之：代词，代之「千乘之国」。
比（bì）及：等到。
且：连词，并且。
方：道，指是非准则。
哂：微笑。
方：见方，纵横。
如：连词，表选择，或者。
足：使……富足。
如：连词，表提起另一话题，作「至于」讲。
其：那。
以：把。后边省宾语「之」。
俟：等待。
能：动词，能做到。
焉：之，指管理国家的事情。
如：连词，或者。
会：诸侯之间的盟会。
同：诸侯共同朝见天子。
端：古代的一种礼服。
章甫：古代的一种礼帽。这里都是名词用作动词，意思是「穿着礼服，戴着礼帽」。
愿：愿意。
相：在祭祀、会盟或朝见天子时主持赞礼和司仪的人。
焉：兼词，于是，在这些场合里。
鼓：弹。
瑟：古乐器。
希：同「稀」，稀疏，这里指鼓瑟的声音已接近尾声。
舍：放下。
作：站起身。
撰：才能。
伤：妨害。
乎：语气词，呢。
莫春：指农历三月。莫，音义同「暮」。
既：副词，已经。
成：稳定，指春服已经穿得住。
冠：古时男子二十岁为成年，束髮加冠。
喟然：叹息的样子。
与：动词，赞成，同意。
后：用作动词，走（落）在后面。
为：治理。
以：介词。靠，用。
让：谦让。
邦：国家，这是指国家大事。
与：同「欤」，疑问语气词。', '子路、曾皙、冉有、公西华陪孔子坐着。孔子说：「因为我比你们年纪大一点，你们不要因为我（年纪大一点就不说了）。你们平时总在说：『没有人知道我呀！』如果有人知道你们，那么你们打算怎么办呢？」
子路不加思索地回答说：「一个拥有一千辆兵车的国家，夹在大国之间，常受外国军队的侵犯，加上内部又有饥荒，如果让我去治理，等到三年的功夫，我就可以使人人勇敢善战，而且还懂得做人的道理。」
孔子听了，微微一笑。
孔子又问：「冉求，你怎么样？」
冉求回答说：「一个纵横六七十里、或者五六十里的国家，如果让我去治理，等到三年，就可以使老百姓富足起来。至于修明礼乐，那就只得另请高明了。」
孔子又问：「公西赤，你怎么样？」
公西赤回答说：「我不敢说能够做到，只是愿意学习。在宗庙祭祀的事务中，或者在诸侯会盟，朝见天子时，我愿意穿着礼服，戴着礼帽，做一个小小的赞礼人。」
孔子又问：「曾点，你怎么样？」
这时曾点弹瑟的声音逐渐稀疏了，接着铿的一声，放下瑟直起身子回答说：「我和他们三位的才能不一样呀！」
孔子说：「那有什么关系呢？不过是各自谈谈自己的志向罢了。」
曾点说：「暮春时节，春天的衣服已经穿上了。我和五六位成年人，六七个青少年，到沂河里洗洗澡，在舞雩台上吹吹风，一路唱着歌儿回来。」
孔子长叹一声说：「我是赞成曾点的想法呀！」
子路、冉有、公西华三个人都出去了，曾皙留在后面。曾皙问：「他们三位的话怎么样？」
孔子说：「也不过是各自谈谈自己的志向罢了。」
曾皙说：「您为什么笑仲由呢？」
孔子说：「治理国家要讲究礼让，可是他说话却一点也不谦让，所以我笑他。难道冉求所讲的就不是国家大事吗？哪里见得纵横六七十里或五六十里讲的就不是国家大事呢？公西赤所讲的不是国家大事吗？宗庙祭祀，诸侯会盟和朝见天子，讲的不是诸侯的大事又是什么呢？如果公西赤只能做个小小的赞礼人，那谁能去做大的赞礼人呢？」', NULL, '', 'indent', 1485423517, '57ea0e315bbb50005d6de057', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10068, '归园田居（其一）', NULL, 885, 99, 8, 16, '陶渊明', NULL, 10011, '57b8fa07c4c97100558ef104', '晋', 'shi', '诗', 'http://baike.baidu.com/subview/162513/4998396.htm', '', '少无适俗韵，性本爱丘山。
误落尘网中，一去三十年。
羁鸟恋旧林，池鱼思故渊。
开荒南野际，守拙归园田。
方宅十余亩，草屋八九间。
榆柳荫后檐，桃李罗堂前。
暧暧远人村，依依墟里烟。
狗吠深巷中，鸡鸣桑树颠。
户庭无尘杂，虚室有余闲。
久在樊笼里，复得返自然。', '此诗是东晋末期南朝宋初期大诗人陶渊明创作的组诗《归园田居五首》的第一首。全诗从对官场生活的强烈厌倦，写到田园风光的美好动人，农村生活的舒心愉快，流露了一种如释重负的心情，表达了对自然和自由的热爱。', '少无适俗韵：少年时就没有迎合世俗的本性。少，指少年时代。适俗，适应世俗，俗，世俗。韵，本性、气质，一作「愿」。
性本爱丘山：天性原本热爱山川田园（生活）。性，天性，本性。
尘网：指尘世，官府生活污浊而又拘束，犹如网罗。这里指仕途。
三十年：有人认为是「十三年」之误（陶渊明做官十三年）。一说，此处是三又十年之意（习惯说法是十又三年），诗人意感「一去十三年」音调嫌平，故将十三年改为倒文。
羁（ji）鸟：笼中之鸟。
恋：一作「眷」。
池鱼：池塘之鱼。鸟恋旧林、鱼思故渊，借喻自己怀恋旧居。
野：一作「亩」。
际：间。
守拙（zhuō）归园田：固守住愚拙，回乡过田园生活。持守愚拙的本性，即不学巧伪，不争名利。
方宅：宅地方圆。一说，「方」通「旁」。
荫（yìn）：荫蔽。
罗：罗列。
暧暧（ài）：昏暗、模糊。
依依：轻柔而缓慢的飘升。
墟里：村落。
户庭：门庭。
尘杂：尘俗杂事。
虚室：空室。
余闲：闲暇。
樊（fán）笼：蓄鸟工具，这里比喻官场生活。樊，藩篱，栅栏。
返自然：指归耕园田。', '少小时就没有随俗气韵，自己的天性是热爱自然。
偶失足落入了仕途罗网，转眼间离田园已十馀年。
笼中鸟常依恋往日山林，池里鱼向往着从前深渊。
我愿在南野际开垦荒地，保持着拙朴性归耕田园。
绕房宅方圆有十馀亩地，还有那茅屋草舍八九间。
榆柳树荫盖着房屋后檐，争春的桃与李列满院前。
远处的邻村舍依稀可见，村落里飘荡着袅袅炊烟。
深巷中传来了几声狗吠，桑树顶有雄鸡不停啼唤。
庭院内没有那尘杂干扰，静室里有的是安适悠闲。
久困于樊笼里毫无自由，我今日总算又归返林山。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccaa0f8fda5565060ed1", "shortContent": "公元405年（东晋安帝义熙元年），陶渊明在江西彭泽做县令，不过八十多天，便声称不愿“为五斗米向乡里小儿折腰”，挂印回家。从此结束了时隐时仕、身不由己的生活，终老田园。归来后，作《归园田居》诗一组，共五首，描绘田园风光的美好与农村生活的淳朴可爱，抒发归隐后愉悦的心情。这是第一首。\n陶诗通常呈现素淡平易的面貌，不见组织雕镂之工。然而苏东坡说：“其诗质而实绮，癯而实腴。”（《与苏辙书》）又说：“渊明诗初...", "authors": ["骆玉明"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4547f27182da33f706b", "bookTitle": "陶渊明诗文鉴赏辞典", "articleId": "6469ecf55b7b0d4f4526d8c3", "shortContent": "公元405年（东晋安帝义熙元年），陶渊明在江西彭泽做县令，不过八十多天，便声称不愿“为五斗米向乡里小儿折腰”，挂印回家。从此结束了时隐时仕、身不由己的生活，终老田园。归来后，作《归园田居》诗一组，共五首，描绘田园风光的美好与农村生活的淳朴可爱，抒发归隐后愉悦的心情。这是第一首。\n陶诗通常呈现素淡平易的面貌，不见组织雕镂之工。然而苏东坡说：“其诗质而实绮，癯而实腴。”（《与苏辙书》）又说：“渊明诗初...", "authors": ["骆玉明"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f2b4d7da2f75ac7145a84", "shortContent": "公元405年（东晋安帝义熙元年），陶渊明在江西彭泽做县令，不过八十多天，便声称不愿“为五斗米向乡里小儿折腰”，挂印回家。从此结束了时隐时仕、身不由己的生活，终老田园。归来后，作《归园田居》诗一组，共五首，描绘田园风光的美好与农村生活的淳朴可爱，抒发归隐后愉悦的心情。这是第一首。\n陶诗通常呈现素淡平易的面貌，不见组织雕镂之工。然而苏东坡说：“其诗质而实绮，癯而实腴。”（《与苏辙书》）又说：“渊明诗初...", "authors": ["骆玉明"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "6470a46fe49f46528ad87628", "shortContent": "公元405年(东晋安帝义熙元年)，陶渊明在江西彭泽做县令，不过八 十多天，便声称不愿“为五斗米向乡里小儿折腰”，挂印回家。从此结束了 时隐时仕、身不由己的生活，终老田园。归来后，作《归园田居》诗一组，共 五首，描绘田园风光的美好与农村生活的淳朴可爱，抒发归隐后愉悦的心 情。这是第一首。\n\n陶诗通常呈现素淡平易的面貌，不见组织雕镂之工。然而苏东坡说: “其诗质而实绮，癯而实腴。”(《与苏辙书》)又说...", "authors": ["骆玉明"], "pressName": "上海辞书出版社"}]', '宋代苏轼：外枯而中膏，似淡而实美。
现代朱光潜：如秋谭月影，彻底澄莹。
现代龚望《陶渊明集评议》：起首一句：名言；凡人百思千虑，不能得。', 'center', 1413388976, '57b90c312e958a005fa5a738', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10069, '白头吟', NULL, 1326, 112, 4, 2, '两汉乐府', NULL, 18119, '5831d697a22b9d006b8ec08c', '汉', 'shi', '诗', 'http://baike.baidu.com/subview/86640/6745489.htm', '', '皑如山上雪，皎若云间月。
闻君有两意，故来相决绝。
今日斗酒会，明旦沟水头。
躞蹀御沟上，沟水东西流。
凄凄复凄凄，嫁娶不须啼。
愿得一心人，白头不相离。
竹竿何袅袅，鱼尾何簁簁。
男儿重意气，何用钱刀为。', '《白头吟》的作者及创作背景仍有争议。《中国古代文学作品选·第一卷先秦两汉卷》记述，此诗作者为卓文君一事应为讹传，前人已在《诗纪匡谬》《诗比兴笺》中指出。据《西京杂记》卷三记载卓文君作《白头吟》。相传卓文君十七岁便守寡。司马相如一曲《凤求凰》多情而又大胆的表白，让她一听倾心，一见钟情。他们的爱情遭到了作者父亲的强烈阻挠。作者凭着自己对爱情的憧憬和对幸福的追求，毅然逃出了卓府，与深爱之人私奔。可是司马相如却让作者失望了。当他在事业上略显锋芒之后，久居京城，产生了纳妾之意。于是作者作《白头吟》，表达她对爱情的执著和向往，以及一个女子独特的坚定和坚韧。', '两意：就是二心（和下文「一心」相对），指情变。
决：别。
「今日斗酒会，明旦沟水头。」句：今天置酒作最后的聚会，明早沟边分手。斗，盛酒的器具；明旦，明日
躞蹀（xièdié）：走貌。
东西流：即东流。「东西」是偏义复词。这里偏用东字的意义。
「躞蹀御沟上，沟水东西流」句：设想别后在沟边独行，过去的爱情生活将如沟水东流，一去不返。御沟，流经御苑或环绕宫墙的沟。
凄凄：悲伤状。
竹竿：指钓竿。
袅袅：动摇貌。
簁簁（shāishāi）：形容鱼尾像濡湿的羽毛。在中国歌谣里钓鱼是男女求偶的象徵隐语。这里用隐语表示男女相爱的幸福。
意气：这里指感情、恩义。
钱刀：古时的钱有铸成马刀形的，叫做刀钱。所以钱又称为钱刀。', '爱情应该像山上的雪一般纯洁，像云间月亮一样光明。听说你怀有二心，所以来与你决裂。今日犹如最后的聚会，明日便将分手沟头。我缓缓的移动脚步沿沟走去，过去的生活宛如沟水东流，一去不返。当初我毅然离家随君远去，就不像一般女孩凄凄啼哭。满以为嫁了一个情意专心的称心郎，可以相爱到老永远幸福了。男女情投意合就像钓竿那样轻细柔长，鱼儿那样活泼可爱。男子应当以情意为重，失去了真诚的爱情是任何钱财珍宝都无法补偿的。', '[{"bookId": "60fc32b023353c0ba53dd945", "bookTitle": "历代女性诗词鉴赏辞典", "articleId": "610ec78303048e64fbd9c00c", "shortContent": "《史记·司马相如列传》：司马相如，蜀郡成都人，曾至长安，在景帝朝做微不足道的小官，也曾客游梁，因梁孝王去世，相如只好落寞还乡；卓文君，其人是临邛富人卓王孙的女儿，新寡后，遇到司马相如，司马相如“以琴心挑之”，于是两人私奔，逃到成都，然无以为生，卓文君提议重回临邛，开一小酒馆，文君当垆，相如身自着犊鼻裈，做酒保，卓王孙老脸挂不住了，最后“分予文君僮百人，钱百万……”司马相如顿然成为富人。\n故而，一旦...", "authors": ["汪春泓"], "pressName": "上海辞书出版社"}, {"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecc955e272d4b2254ea4a", "shortContent": "晋人葛洪《西京杂记》载：“司马相如将聘茂陵人女为妾，卓文君作《白头吟》以自绝，相如乃止。”但《宋书·乐志》言《白头吟》等“并汉世街陌谣讴”，即民歌。《玉台新咏》载此诗，题作《皑如山上雪》，则连题目亦与卓氏无关了。《西京杂记》乃小说家言，且相如、文君关系亦未尝至此，故云文君作，显系附会。此诗当属民歌，以女子口吻写其因见弃于用情不专的丈夫而表示出的决绝之辞。\n首二句是一篇起兴，言男女爱情应该是纯洁无瑕...", "authors": ["熊", "笃"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f60a845e4710056f1da62", "shortContent": "晋人葛洪《西京杂记》载:“司马相如将聘茂陵人女为妾，卓文君作《白 头吟》以自绝，相如乃止。”但《宋书·乐志》言《白头吟》等“并汉世街陌谣 讴”，即民歌。《玉台新咏》载此诗，题作《皑如山上雪》，则连题目亦与卓氏 无关了。《西京杂记》乃小说家言，且相如、文君关系亦未尝至此，故云文 君作，显系附会。此诗当属民歌，以女子口吻写其因见弃于用情不专的丈 夫而表示出的决绝之辞。\n\n首二句是一篇起兴，言男女爱情应...", "authors": ["熊笃"], "pressName": "上海辞书出版社"}]', '徐师曾：（《白头吟》）其格韵不凡，托意婉切，殊可讽咏。后世多有拟作，方其简古，未有能过之者。
王夫之《船山古诗评选》：亦雅亦宕，乐府绝唱。
张玉谷《古诗赏析》：凄凄四句，盖终冀其变两意为一心，而白头相守也。妙在从人家嫁娶时凄凄啼哭，凭空指点一妇人同有之愿，不着己身说而己身已在里许。', 'center', 1423167085, '57b8c601c4c97100558e3414', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10071, '沁园春 · 长沙', NULL, 1676, 106, 5, 10, '毛泽东', NULL, 10025, '57b8fb582e958a005fa52193', '当代', 'ci', '词', 'http://baike.baidu.com/view/328748.htm', '', '独立寒秋，湘江北去，橘子洲头。看万山红遍，层林尽染；漫江碧透，百舸争流。鹰击长空，鱼翔浅底，万类霜天竞自由。怅寥廓，问苍茫大地，谁主沉浮？
携来百侣曾游。忆往昔峥嵘岁月稠。恰同学少年，风华正茂；书生意气，挥斥方遒。指点江山，激扬文字，粪土当年万户侯。曾记否，到中流击水，浪遏飞舟？', '长沙是毛泽东求学和早年从事革命活动的地方，1925年二月他从上海回湖南开展农民运动，八月从韶山到长沙，九月前往广州主持全国农民运动讲习所。在长沙逗留期间重游橘子洲，面对湘江上美丽动人的自然秋景，联想起当时的革命形势，便以「长沙」为题写下此词。
在这峥嵘岁月里，作者和他的同学蔡和森、何叔衡等立志救国的知识青年，正值青春年少，神采飞扬，才华横溢，意气风发，热情奔放，面对万山红遍的美景，他们既赞叹锦绣河山的壮美，又悲愤大好河山的沉沦。于是，发表激浊扬清的文章，抨击黑暗，宣扬真理，鄙视当时的「万户侯」——军阀如粪土，这一段描写形象地概括了青年时期的毛泽东和其战友雄姿英发的战斗风貌和豪迈气概。', '沁园春：词牌名，「沁园」为东汉明帝为女儿沁水公主修建的皇家园林，据《后汉书窦宪传》记载，沁水公主的舅舅窦宪倚仗其妹贵为皇后之势，竟强夺公主园林，后人感叹其事，多在诗中咏之，渐成「沁园春」这一词牌。
寒秋：就是深秋、晚秋。秋深已有寒意，所以说是寒秋。
湘（xiāng）江：一名湘水，湖南省最大的河流，源出广西壮族自治区灵川县南的海洋山，长一千七百五十二里，向东北流贯湖南省东部，经过长沙，北入洞庭湖。所以说是湘江北去。
橘子洲：地名，又名水陆洲，是长沙城西湘江中一个狭长小岛，西面靠近岳麓山。南北长约十一里，东西最宽处约一里。毛泽东七律《答友人》中所谓长岛，指此。自唐代以来，就是游览胜地。
万山：指湘江西岸岳麓山和附近许多山峰。
层林尽染：山上一层层的树林经霜打变红，像染过一样。尽染：此处化用王实甫《西厢记》中「晓来谁染霜林醉」句意。
漫江：满江。漫：满，遍。
舸（gě）：大船。这里泛指船只。
争流：争着行驶。
鹰击长空，鱼翔浅底：鹰在广阔的天空里飞，鱼在清澈的水里游。击，搏击。这里形容飞得矫健有力。翔，本指鸟盘旋飞翔，这里形容鱼游得轻快自由。
万类：指一切生物。
霜天：指秋天，即上文「寒秋」。
万类霜天竞自由：万物都在秋光中竞相自由地生活。
怅：原意是失意，这里用来表达由深思而引发激昂慷慨的心绪。
寥廓（liáokuò）：广远空阔，这里用来描写宇宙之大。
怅寥廓（chàngliáokuò）：面对广阔的宇宙惆怅感慨。
苍茫：旷远迷茫。
主：主宰。
沉浮：同「昇沉」（上昇和没落）意思相近，比喻事物盛衰、消长，这里指兴衰。由上文的俯看游鱼，仰看飞鹰，纳闷地寻思（「怅」）究竟是谁主宰着世间万物的昇沉起伏。
携来：挽，牵。来，语气词，无实义。
百侣：很多的伴侣。侣，这里指同学（也指战友）。
峥嵘岁月稠：不平常的日子是很多的。峥嵘：本指山的高峻，此处意谓不平凡、不寻常。稠：多。
恰：适逢，正赶上。
同学少年：毛泽东于1913年至1918年就读于湖南第一师范学校。1918年毛泽东和萧瑜、蔡和森等组织新民学会，开始了他早期的政治活动。
风华正茂：风采才华正盛。风华：风采、才华；茂：丰满茂盛。
书生：读书人，这里指青年学生。
意气：意态气概。
挥斥：奔放。《庄子·田子方》：「挥斥八极」。郭象注：「挥斥，犹纵放也。」
挥斥方遒：热情奔放，劲头正足。遒，强劲有力；方，正。
指点江山，激扬文字：评论国家大事，用文字来抨击丑恶的现象，赞扬美好的事物。写出激浊扬清的文章。指点，评论；江山，指国家；激扬，激浊扬清，抨击恶浊的，褒扬清明的。
万户侯，汉代设置的最高一级侯爵，食邑万户，享有万户农民的赋税。此借指大军阀，大官僚。万户，指侯爵封地内的户口，要向受封者缴纳租税，服劳役。
粪土当年万户侯：视当时的军阀官僚同粪土一样。粪土，作动词用，视……如粪土。
中流：江心水深流急的地方。
击水：作者自注：「击水：游泳。那时初学，盛夏水涨，几死者数，一群人终于坚持，直到隆冬，犹在江中。当时有一篇诗，都忘记了，只记得两句：自信人生二百年，会当水击三千里。」这里引用祖逖（tì）的「中流击楫」典故。（祖逖因为国家政权倾覆，时刻怀着振兴光复的心志。元帝就让他担任奋威将军、豫州刺史，供给他一千人的军粮，三千匹布，但不给战衣和兵器，让他自行招募士众。祖逖仍就率领随自己流亡的部属一百多家，渡过长江，到江心时他扣击船桨发誓说：「我祖逖不能平定中原并再次渡江回来的话，就像长江的水一去不返！」言辞激昂神色悲壮，众人都为他的誓言感慨赞叹。）这里指游泳。
遏（è）：阻止。
飞舟：如飞之舟，言其迅速。', '在深秋一个秋高气爽的日子里，我独自伫立在橘子洲头，眺望着湘江碧水缓缓北流。看万千山峰全都变成了红色，一层层树林好像染过颜色一样，江水清澈澄碧，一艘艘大船乘风破浪，争先恐后。鹰在广阔的天空飞，鱼在清澈的水里游，万物都在秋光中争着过自由自在的生活。面对着无边无际的宇宙，（千万种思绪一齐涌上心头）我要问：这苍茫大地的盛衰兴废由谁来决定主宰呢？
回想过去，我和我的同学，经常携手结伴来到这里游玩。在一起商讨国家大事，那无数不平凡的岁月至今还萦绕在我的心头。同学们正值青春年少，风华正茂；大家踌躇满志，意气奔放，正强劲有力。评论国家大事，写出这些激浊扬清的文章，把当时那些军阀官僚看得如同粪土。还记得吗？那时我们在江水深急的地方游泳，那激起的浪花几乎挡住了疾驰而来的船。', '[{"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88b9f2af4e09d5508bec", "shortContent": "这首词最早发表在《诗刊》一九五七年一月号。\n\n毛泽东的词是独一无二的。这倒不是说他词的艺术性无与匹敌，而是说他词中所展现的崇高气魄、博大胸襟、乐观信念、伟大理想是超越前代、无与伦比的。我们试从历史的角度，比较分析一下1925年秋毛泽东在长沙写的这首《沁园春》词。\n\n秋天，在现代人看来，是一个收获的季节，是一个易使人产生成就感、满足感的快乐季节。而在中国古代诗人看来，秋天却是一个万物凋零、萧瑟冷清、...", "authors": ["王兆鹏"], "pressName": "上海辞书出版社"}, {"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88b9f2af4e09d5508bf5", "shortContent": "这首词最早发表在《人民文学》一九六二年五月号。\n\n《蝶恋花·从汀州向长沙》，毛泽东“在马背上哼成的”又一首史诗式词作。时间是1930年7月。从他高擎秋收起义的火炬，创建工农革命军，到把红旗插上井冈山，创建第一个工农革命根据地，到率领红四军主力三次进军赣南、闽西，为尔后的中央苏区奠定牢固的基础，他已经在枪林弹雨中纵马驰骋将近三年了。这时，他已经不仅仅是“指点江山，激扬文字”的一介书生，也不仅仅是一位...", "authors": ["陈敦源"], "pressName": "上海辞书出版社"}]', '', 'indent', 1362178323, '57b8be67df0eea006333ee9a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10074, '沁园春 · 雪', NULL, 2377, 106, 3, 15, '毛泽东', NULL, 10025, '57b8fb582e958a005fa52193', '当代', 'ci', '词', 'http://baike.baidu.com/view/78040.htm', '', '北国风光，千里冰封，万里雪飘。望长城内外，惟余莽莽；大河上下，顿失滔滔。山舞银蛇，原驰蜡象，欲与天公试比高。须晴日，看红装素裹，分外妖娆。
江山如此多娇，引无数英雄竞折腰。惜秦皇汉武，略输文采；唐宗宋祖，稍逊风骚。一代天骄，成吉思汗，只识弯弓射大雕。俱往矣，数风流人物，还看今朝。', '该词的创作有2种说法：
第一种：1936年2月，毛泽东等率领红军东征抗日先锋军东渡黄河、突破阎军防线后，踏雪沿官道山行进，顺利到达山西省石楼县留村，并在此写下了著名诗篇《沁园春·雪》；
第二种：1936年2月，毛泽东率红军抗日，来到西北高原。在陕西省清涧县高杰村附近的袁家沟，写下壮丽的《沁园春·雪》。
《沁园春·雪》最早发表于1945年11月14日重庆《新民报晚刊》，后正式发表于《诗刊》1957年1月号。
诗词分上下两阕，上阕描写乍暖还寒的北国雪景，展现伟大祖国的壮丽山河；下阕由毛泽东主席对祖国山河的壮丽而感叹，并引出秦皇汉武等英雄人物，纵论历代英雄人物。
此词不仅赞美了祖国山河的雄伟和多娇，更重要的是赞美了今朝的革命英雄，抒发毛泽东伟大的抱负及胸怀。', '北国：该词源于中国古代的分裂时期，如东晋称十六国等为北国，南北朝时代南方的各朝代称在北方与之对抗的各朝代为北国等。毛泽东诗中的“北国”使人在不觉中产生出一种中国疆土广大的民族自豪感。
雪：此词作于红一方面军1936年2月由陕北准备东渡黄河进入山西省西部的时候。作者在1945年10月7日给柳亚子信中说，此词作于“初到陕北看见大雪时”。
馀：剩下。此字一作“余”，但刊出的书法作品中写作“馀”，以此为准。
莽莽：无边无际。
大河上下：大河，指黄河。大河上下，犹言整条黄河。
山舞银蛇，原驰蜡象：群山好像（一条条）银蛇在舞动。高原（上的丘陵）好像（许多）白象在奔跑。“原”指高原，即秦晋高原。蜡象，白色的象。
天公：指天，即命运。
红装素裹：形容雪后天晴，红日和白雪交相辉映的壮丽景色。红装，原指妇女的艳装，这里指红日为大地披上了红装。素裹，原指妇女的淡装，这里指皑皑白雪覆盖着大地。
竞折腰：折腰，倾倒，躬着腰侍候。这里是说争着为江山奔走操劳。
风骚：本指《诗经》里的《国风》和《楚辞》里的《离骚》，后来泛指文章辞藻。
一代天骄：指可以称雄一世的英雄人物，泛指非常著名，有才能的人物。天骄，“天之骄子”的省略语。意思是上天所骄纵宠爱的人，成吉思汗即是。汉时匈奴自称。后来也泛称强盛的少数民族或其首领。
俱往矣：都已经过去了。俱，都。
数：数得着、称得上。', '北方的风光，千里冰封冻，万里雪花飘。望长城内外，只剩下无边无际白茫茫一片；宽广的黄河上下，顿时失去了滔滔水势。山岭好像银白色的蟒蛇在飞舞，高原上的丘陵好像许多白象在奔跑，它们都想与老天爷比比高。要等到晴天的时候，看红艳艳的阳光和白皑皑的冰雪交相辉映，分外美好。
江山如此媚娇，引得无数英雄竞相倾倒。只可惜秦始皇、汉武帝，略差文学才华；唐太宗、宋太祖，稍逊文治功劳。称雄一世的人物成吉思汗，只知道拉弓射大雕。这些人物全都过去了，称得上能建功立业的英雄人物，还要看今天的人们。', '[{"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88ba7ccdb86c49e7aa13", "shortContent": "这首词最早发表在《诗刊》一九五七年一月号。\n\n在这以前，一九四五年十月，毛泽东在重庆曾把这首词书赠柳亚子，因而被重庆《新民报晚刊》在十一月十四日传抄发表，以后别的报纸陆续转载，但多有讹误，不足为据。\n\n无论从何种角度着眼，《沁园春·雪》都说得上是毛泽东诗词的压卷之作。这决不是个人的意见，而是几乎所有评论家的共识。\n\n这首词的写作背景不同寻常。作者在给柳亚子的一封信中，称此词为“初到陕北看见大雪时”...", "authors": ["（周啸天）"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413470546, '57b907d279bc44005b9ed525', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10075, '水调歌头 · 游泳', NULL, 292, 106, 5, 1, '毛泽东', NULL, 10025, '57b8fb582e958a005fa52193', '当代', 'ci', '词', 'http://baike.baidu.com/view/328822.htm', '', '才饮长沙水，又食武昌鱼。万里长江横渡，极目楚天舒。不管风吹浪打，胜似闲庭信步。今日得宽馀，子在川上曰：“逝者如斯夫”。
风樯动，龟蛇静，起宏图。一桥飞架南北，天堑变通途。更立西江石壁，截断巫山云雨，高峡出平湖。神女应无恙，当惊世界殊。', '该首词最早发表在《诗刊》1957年1月。1954年中央人民政府决定修建武汉长江大桥。1955年毛泽东视察了全部工程。1956年毛泽东巡视南方，又视察了大桥的施工。6月1日、3日、4日毛泽东三次畅游长江，写下了此词。
词风依然壮志，他从上片对游泳的舒畅之感及时光流逝之感一直写到下片对社会主义建设蓝图在胸的自由联想。接着笔力一转，拨出雄音，“万里长江横渡，极目楚天舒。”点明此诗是“游泳”之主旨，同时又流露出诗人在江上所感到的舒展、空阔。', '游泳：1956年6月，作者曾由武昌游泳横渡长江，到达汉口。
长沙水：1958年12月21日作者自注：“民谣：常德德山山有德，长沙沙水水无沙。所谓无沙水，地在长沙城东，有一个有名的‘白沙井’。”
武昌鱼：据《三国志·吴书·陆凯传》记载，吴主孙皓要把都城从建业（故城在今南京市南）迁到武昌，老百姓不愿意，有童谣说：“宁饮建业水，不食武昌鱼。”这里化用。武昌鱼，指古武昌（今鄂城）樊口的鳊鱼，称团头鳊或团头鲂。
极目楚天舒：极目，放眼远望。武昌一带在春秋战国时属于楚国的范围，所以作者把这一带的天空叫“楚天”。舒，舒展，开阔。柳永词《雨霖铃》：“暮霭沉沉楚天阔。”作者在一九五七年二月十一日给黄炎培的信中说：“游长江二小时飘三十多里才达彼岸，可见水流之急。都是仰游侧游，故用‘极目楚天舒’为宜。”
宽馀（yú）：字从食从余，余本意为“剩下的”，“食”和“余”联合起来表示“用餐后剩下的食物”。指神态舒缓，心情畅快。
子在川上曰：逝者如斯夫：《论语·子罕》：“子在川上，曰：‘逝者如斯夫！不舍昼夜。’”意思是孔子在河边感叹道：“时光像流水一样消逝，日夜不停。”时光如流水，一去不复返；往者不可追，来者犹可惜。
风樯（qiáng）：樯，桅杆。风樯，指帆船。
龟蛇：见《菩萨蛮·黄鹤楼》“龟蛇锁大江”注。在词中实指龟山、蛇山。
一桥飞架南北：指当时正在修建的武汉长江大桥。1958年版《毛主席诗词十九首》和1963年版《毛主席诗词》，作者曾将此句改为“一桥飞架，南北天堑变通途”，后经作者同意恢复原句。
天堑（qiàn）：堑，沟壕。古人把长江视为“天堑”。据《南史·孔范传》记载，隋伐陈，孔范向陈后主说：“长江天堑，古来限隔，虏军岂能飞渡？”
巫山云雨：在四川省巫山县东南。“巫山云雨”，传楚宋玉《高唐赋·序》说，楚怀王在游云梦泽的高唐时曾梦与巫山神女遇，神女自称“旦为朝云，暮为行雨”，这里只是借用这个故事中的字面和人物。', '刚喝了长沙的水，又吃着武昌的鱼。我在万里长江上横渡，举目眺望舒展的长空。哪管得风吹浪涌，这一切犹如信步闲庭，今天我终于可以尽情流连。
江面风帆飘荡，龟蛇二山静静伫立，胸中宏图升起。大桥飞跨沟通南北，长江天堑将会畅行无阻。我还要在长江西边竖起大坝，斩断巫山多雨的洪水，让三峡出现平坦的水库。神女（神女峰）如果当时还在，必定会惊愕世界变了模样。', '[{"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88bac9ebcc6fbe96f7bf", "shortContent": "这首词最早发表在《诗刊》一九五七年一月号。\n\n1956年，社会主义改造运动已经接近尾声，毛泽东开始认真思考中国的社会主义建设道路问题。从2月开始，他用了两个半月时间，向34个部门的负责同志作调查，形成了《论十大关系》这篇讲话。后来，他在《十年总结》中回顾说：“前八年照抄外国经验。但从1956年提出‘十大关系’起，开始找到自己的一条适合中国的路线”，“开始反映中国客观经济规律”。\n\n4月25日和5月...", "authors": ["周振甫"], "pressName": "上海辞书出版社"}]', '', 'indent', 1362180193, '57b901f1165abd0054bfd744', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10076, '水调歌头 · 重上井冈山', NULL, 176, 106, 4, 1, '毛泽东', NULL, 10025, '57b8fb582e958a005fa52193', '当代', 'ci', '词', 'http://baike.baidu.com/view/328880.htm', '', '久有凌云志，重上井冈山。千里来寻故地，旧貌变新颜。到处莺歌燕舞，更有潺潺流水，高路入云端。过了黄洋界，险处不须看。
风雷动，旌旗奋，是人寰。三十八年过去，弹指一挥间。可上九天揽月，可下五洋捉鳖，谈笑凯歌还。世上无难事，只要肯登攀。', '此词以登井冈山为题材，在忆旧颂新中将崇高的理想和伟大的实践精神相结合，将叙事、写景、抒情、议论熔于一炉，既包含着丰富的思想内容，具有高度的概括力，又不乏明快活泼、生动细致的景物描写，慷慨激昂，与词人一贯的乐观主义和浪漫主义一脉相承。', '水调歌头：词牌名，又名“元会曲”、“凯歌”、“台城游”等。上下阕，九十五字，平韵。
重上井冈山：1965年五月下旬，作者重上井冈山游览视察。先后到黄洋界和茨坪。在茨坪居住期间，了解井冈山地区水利、公路建设和人民生活，会见了老红军、烈士家属、机关干部和群众。
黄洋界：井冈山五大哨口之一，另四个是八面山、双马石、朱沙冲、桐木岭。
人寰：人世间。
三十八年过去，弹指一挥间：从一1927年10月毛泽东率领秋收起义部队上井冈山，到这次重来，已经过去了三十八年，作者却觉得只是弹一下指、挥一下手的短时间。
九天揽月：九天，天的极高处。《孙子·形》：“善攻者，动于九天之上。”揽月，摘取月亮。唐李白《宣州谢朓楼饯别校书叔云》：“俱怀逸兴壮思飞，欲上青天览明月。”览同揽。
捉鳖（biē）：喻擒拿敌人。元康进之《李逵负荆》第四折：“管教他瓮中捉鳖，手到拿来。”', '我从小就心怀凌云壮志，今天我重新登上井冈山。走了千里来寻访这片旧地，哪里还有半分它昔日的容颜。到处都是莺啼燕飞的晚春新景，还有汩汩畅行的流水，宽大的盘山公路直入云端。过了黄洋界隘口，就没有任何的险处可看了。
风和雷在运动，旌旗在招展，这就是人间。三十八年都过去了，犹如弹指的一刹那。可以飞向长空摘月亮，也可以潜下海洋捉鱼或鳖，谈笑间高奏凯歌还师。世上没有什么困难的事，只要肯下定决心去登攀。', '[{"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88ba7f0b9738b35ec614", "shortContent": "这首词最早发表在《诗刊》一九七六年一月号。\n\n全词上片纪事、写景，下片抒怀明志。文字简单、明了，沿袭了诗人一贯的写作风格，豪迈、自信依然是毛泽东在这首词中的两大元素。\n\n“久有凌云志，重上井冈山。”首句即破空而来，气魄非凡。诗人在闲庭信步的从空间让阅读者看到的是一种大气派。“凌云志”借井冈山的巍峨写出了诗人的“凌云”抱负。三十八年前诗人在此立下的天下抱负，今天早已经实现，如今他一路征尘归来，重访故...", "authors": ["张克中"], "pressName": "上海辞书出版社"}]', '', 'indent', 1362180354, '57b95a33c4c9710055924045', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10077, '嫦娥', NULL, 1046, 603, 1, 7, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/2607205/13754402.htm', '', '云母屏风烛影深，长河渐落晓星沉。
嫦娥应悔偷灵药，碧海青天夜夜心。', '此诗咏叹嫦娥在月中的孤寂情景，抒发诗人自伤之情。前两句分别描写室内、室外的环境，渲染空寂清冷的气氛，表现主人公怀思的情绪；后两句是主人公在一宵痛苦的思忆之后产生的感想，表达了一种孤寂感。全诗情调感伤，意蕴丰富，奇思妙想，真实动人。', '嫦娥：神话中的月亮女神，传说是夏代东夷首领后羿的妻子。
云母屏风：以云母石制作的屏风。云母，一种矿物，板状，晶体透明有光泽，古代常用来装饰窗户、屏风等物。深：暗淡。
长河：银河。晓星：晨星。或谓指启明星，清晨时出现在东方。
灵药：指长生不死药。《淮南子·览冥训》载，后羿在西王母处求得不死的灵药，姮娥偷服后奔入月宫中。
碧海青天：指嫦娥的枯燥生活，只能见到碧色的海，深蓝色的天。碧海，形容蓝天苍碧如同大海。夜夜心：指嫦娥每晚都会感到孤单。', '烛影深深映上云母屏风，银河渐渐沉没，晨星渐渐消失。
嫦娥后悔寂寞，后悔偷吃灵药。面对碧海蓝天，日夜思念人间。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92e003572034f659e5be", "shortContent": "这首诗题为“嫦娥”，实际上抒写的是处境孤寂的主人公对于环境的感受和心灵独白。\n前两句描绘主人公的环境和永夜不寐的情景。室内，烛光越来越黯淡，云母屏风上笼罩着一层深深的暗影，越发显出居室的空寂清冷，透露出主人公在长夜独坐中黯然的心境。室外，银河逐渐西移垂地，牛郎、织女隔河遥望，本来也许可以给独处孤室的不寐者带来一些遐想，而现在这一派银河即将消失。那点缀着空旷天宇的寥落晨星，仿佛默默无言地陪伴着一轮孤...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9820695e6503fffe", "shortContent": "这首诗题为“嫦娥”，实际上抒写的是处境孤寂的主人公对于环境的感受和心灵独白。\n\n前两句描绘主人公的环境和永夜不寐的情景。室内，烛光越来越黯淡，云母屏风上笼罩着一层深深的暗影，越发显出居室的空寂清冷，透露出主人公在长夜独坐中黯然的心境。室外，银河逐渐西移垂地，牛郎、织女隔河遥望，本来也许可以给独处孤室的不寐者带来一些遐想，而现在这一派银河即将消失。那点缀着空旷天宇的寥落晨星，仿佛默默无言地陪伴着一轮...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d80e6f69b71e93f5f8c", "shortContent": "一二句说，月宫里的嫦娥在屏风后面烛光微弱的深处隐藏，她一直坐到银河隐没，列宿潜光，彻夜无眠。三四句说，她一定懊悔偷吃不死之药而奔上月宫，永远面对这碧海青天夜夜凄凉，相思之情绵绵不尽。本篇为修道女冠而作，同情其处境之孤独与内心的忧伤，含蓄蕴藉之至。是唐人七绝之名篇。", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4dc26cbf3417f09398", "shortContent": "凉秋的残夜，慢慢走到了黑暗的尽头，深夜蚰蛐的蝈蝈声渐渐稀落，偶尔有几声清脆的鸟叫，预示着黎明的降临。也许有什么事情纠结着诗人的心灵，他躺在床上辗转反侧，彻夜未眠。透过云母的屏风，他注意到燃烧了一夜的蜡烛快要耗竭了，火苗正渐渐地变弱变淡，光明所控制的范围开始被黑暗无情地吞噬，室内渐渐黯淡下来。诗人抬起头，蓦然发现窗外格外明亮，也许是快到黎明了吧。他一骨碌爬了起来，慢慢踱到窗前，将目光投向渺渺茫茫的天...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270799761253910e90568", "shortContent": "凉秋的残夜，慢慢走到了黑暗的尽头，蝈蝈声渐渐稀落，偶尔有几声清脆的鸟叫，预示着黎明的降临。也许有什么事情纠结着诗人的心灵，他躺在床上辗转反侧，已经彻夜未眠了。透过云母的屏风，他注意到燃烧了一夜的蜡烛，快要耗竭了，火苗正渐渐地变弱变淡，光明所控制的范围开始被黑暗无情地吞噬，室内渐渐黯淡下来。诗人抬起头，蓦然发现窗外格外的明亮起来，也许是快到黎明了吧。他一骨碌爬了起来，慢慢踱到窗前，将目光投向渺渺茫茫...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312714977683d193301546b", "shortContent": "凉秋的残夜，慢慢走到了黑暗的尽头，深夜蛐蛐的叫声渐渐稀落，偶尔有几声清脆的鸟叫，预示着黎明的降临。也许有什么事情纠结着诗人的心灵，他躺在床上辗转反侧，已经彻夜未眠了。透过云母的屏风，他注意到燃烧了一夜的蜡烛，快要耗竭了，火苗正渐渐地变弱变淡，光明所控制的范围开始被黑暗无情地吞噬，室内渐渐黯淡下来。诗人抬起头，蓦然发现窗外格外的明亮起来，也许是快到黎明了吧。他一骨碌爬了起来，慢慢踱到窗前，将目光投向...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "6463887730675327e18493a9", "shortContent": "这首诗题为“嫦娥”，实际上抒写的是处境孤寂的主人公对于环境的感受和心灵独白。\n\n前两句描绘主人公的环境和永夜不寐的情景。室内，烛光越来越黯淡，云母屏风上笼罩着一层深深的暗影，越发显出居室的空寂清冷，透露出主人公在长夜独坐中黯然的心境。室外，银河逐渐西移垂地，牛郎、织女隔河遥望，本来也许可以给独处孤室的不寐者带来一些遐想，而现在这一派银河即将消失。那点缀着空旷天宇的寥落晨星，仿佛默默无言地陪伴着一轮...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '吕本中《紫薇诗话》：杨道孚深爱义山“嫦娥应悔偷灵药，碧海青天夜夜心”，以为作诗当如此学。
洪迈《唐人万首绝句选评》：借嫦娥抒孤高不遇不感，笔舌之妙，自不可及。
高棅《唐诗品汇》：谢云：意谓嫦娥有长生之福，无夫妇之乐为悔，前人未道破。
敖英《唐诗绝句类选》：此诗翻空断意，从杜诗“斟酌姮娥寡，天寒奈九秋”变化出来。
钟惺《唐诗归》：语想俱刻，此三字（指“夜夜心”）却下得深浑（末句下）。
周珽《唐诗选脉会通评林》：陆时雍曰：多以意胜。胡次焱曰：此诗盖自道也。上二句纪发想之时，下二句志凝想之意。唐仲言曰：此疑有“桑中”之思，借嫦娥以指其人，与《锦瑟》同意。盖义山此类作甚多，如《月夕》、《西亭》、《有感》、《昨夜》等作，俱与《嫦娥》篇情思相左右，但不若此沉含更妙耳。
黄生《唐诗摘钞》：义山诗中多属意妇人。观《月夕》一首云：“草下阴虫叶上霜，朱栏迢递压湖光。兔寒蟾冷桂花白，此夜姮娥应通肠。”玩次句语景，“嫦娥”字似暗有所指，此作亦然。“朱栏迢递”“烛影屏风”，皆所思之地之景耳。
姚培谦《李义山诗集笺注》：此非咏嫦娥也。从来美人名士，最难持者末路，末二语警醒不少。
屈复《玉溪生诗意》：嫦娥指所思之人也，作真指嫦娥，痴人说梦。
朱鹤龄《重订李义山诗集笺注》：此亦刺女道士。首句言其洞房深曲之景，次句言其夜会晓离之情。下二句言其不为女冠，尽堪求偶，无端入道，何日上升也？则心、如悬旌，未免悔恨于天长海阔矣。
沈德潜《唐诗别裁》：孤寂之况，以“夜夜心”三字尽之。士有争先得路而自悔者，亦作如是观。
黄叔灿《唐诗笺注》：此诗似有所为，而借嫦娥以托意。上二句赋其长夜阒寂，借后羿之妃奔入月宫而言，亦翻案语。义山最喜作此等诗，如“金徽却是无情物，不许文君忆故夫”、“莫讶韩凭为蛱蝶，等闲飞上别枝花”、“八骏日行三万里，穆王何事不重来”，皆是有意出奇也。
冯浩《玉溪生诗集笺注》：或为入道而不耐孤孑者致诮也。
纪昀《玉溪生诗说》：意思藏在上二句，却从嫦娥对面写来，十分蕴藉。非咏嫦娥。
张采田《玉溪生年谱会笺》：义山依违党局，放利偷合，此自忏之词，作他解者非。
俞陛云《诗境浅说续编》：嫦娥偷药，本属寓言。更悬揣其有悔心，且万古悠悠，此心不变，更属幽玄之思，词人之戏笔耳。', 'center', 1413455889, '57b92db25bbb50005b79a11c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10078, '春晓', NULL, 5204, 266, 2, 12, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/25467/7920388.htm', '', '春眠不觉晓，处处闻啼鸟。
夜来风雨声，花落知多少。', '《春晓》是唐代诗人孟浩然隐居在鹿门山时所作，诗人抓住春天的早晨刚刚醒来时的一瞬间展开联想，描绘了一幅春天早晨绚丽的图景，抒发了诗人热爱春天、珍惜春光的美好心情。全诗语言平易浅近，自然天成，言浅意浓，景真情真，深得大自然的真趣。', '不觉晓：不知不觉天就亮了。晓：早晨，天明，天刚亮的时候。
闻：听见。啼鸟：鸟啼，鸟的啼叫声。
“夜来”句：一作“欲知昨夜风”。
“花落”句：一作“花落无多少”。知多少：不知有多少。知：不知，表示推想。', '春天睡醒不觉天已大亮，到处是鸟儿清脆的叫声。
回想昨夜的阵阵风雨声，吹落了多少芳香的春花。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92920f8fda55650553cc", "shortContent": "《春晓》这首小诗，初读似觉平淡无奇，反复读之，便觉诗中别有天地。它的艺术魅力不在于华丽的辞藻，不在于奇绝的艺术手法，而在于它的韵味。整首诗的风格就像行云流水一样平易自然，然而悠远深厚，独臻妙境。千百年来，人们传诵它，探讨它，仿佛在这短短的四行诗里，蕴涵着开掘不完的艺术宝藏。\n自然而无韵致，则流于浅薄；若无起伏，便失之平直。《春晓》既有优美的韵致，行文又起伏跌宕，所以诗味醇永。诗人要表现他喜爱春天的...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0fa", "shortContent": "《春晓》这首小诗，初读似觉平淡无奇，反复读之，便觉诗中别有天地。它的艺术魅力不在于华丽的辞藻，不在于奇绝的艺术手法，而在于它的韵味。整首诗的风格就像行云流水一样平易自然，然而悠远深厚，独臻妙境。千百年来，人们传诵它，探讨它，仿佛在这短短的四行诗里，蕴涵着开掘不完的艺术宝藏。\n\n自然而无韵致，则流于浅薄；若无起伏，便失之平直。《春晓》既有优美的韵致，行文又起伏跌宕，所以诗味醇永。诗人要表现他喜爱春天...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e90390", "shortContent": "此诗短短二十字，却韵味无穷，古今诗评家都推崇备至，乃至儿童学诗，开口就念“春眠不觉晓”。《王孟诗评》云：“风流闲美，正不在多。”诚哉！\n\n诗文贵曲，委曲才有味。“春眠不觉晓”，诗一开始就给人无限玄想。为什么会“不觉晓”呢？春天懒床？昨夜苦读？日来劳作？……作者没有说，又尽在不言中。诗的第三句，已有所披露，并由此引出下句“花落知多少”的悬念。正因诗没直言说尽，更能给人留下想象的余地。《唐诗解》云：“...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127036c9ebcc6fbea1a398", "shortContent": "此诗短短二十字，却韵味无穷，古今诗评家都推崇备至，乃至儿童学诗，开口就念“春眠不觉晓”。《王孟诗评》云：“风流闲美，正不在多。”诚哉！\n\n诗文贵曲，委曲才有味。“春眠不觉晓”，诗一开始就给人无限玄想，为什么会“不觉晓”呢？春天晚起？昨夜苦读？日来劳作？……作者没有说，又尽在不言中。诗的第三句，已有所披露，并由此引出下句“花落知多少”的悬念。正因诗没直言说尽，更能给人留下想象的余地。《唐诗解》云：“...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127069c305cf0801816fdf", "shortContent": "此诗短短二十字，却韵味无穷，古今诗评家都推崇备至，乃至儿童学诗，开口就念“春眠不觉晓”。《王孟诗评》云：“风流闲美，正不在多。”诚哉！\n诗文贵曲，委曲才有味。“春眠不觉晓”，诗一开始就给人无限悬想。为什么会“不觉晓”呢？春天懒床？昨夜苦读？日来劳作？……作者没有说，又尽在不言中。诗的第三句，已有所披露，并由此引出下句“花落知多少”的悬念。正因诗没直言说尽，更能给人留下想象的余地。\n《唐诗解》云：“...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f0a5e7da2f75ac713957e", "shortContent": "春天，有迷人的色彩，有醉人的芬芳，诗人都不去写。他只是从听觉角度着笔，写春之声：那处处啼鸟，那潇潇风雨。鸟声婉转，悦耳动听，是美的。加上“处处”二字，啁啾起落，远近应和，就更使人有置身山阴道上，应接不暇之感。春风春雨，纷纷洒洒，但在静谧的春夜，这沙沙声响却也让人想见那如烟似梦般的凄迷意境，和微雨后的众卉新姿。这些都只是诗人在室内的耳闻，然而这阵阵春声却逗露了无边春色，把读者引向了广阔的大自然，使读...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "645fc22c5e6bb82b8caff682", "bookTitle": "历代咏春诗鉴赏：春江花月夜", "articleId": "6472f5f145e4710056ff8443", "shortContent": "《春晓》这首小诗，初读似觉平淡无奇，反复读之，便觉诗中别有天地。它的艺术魅力不在于华丽的辞藻，不在于奇绝的艺术手法，而在于它的韵味。整首诗的风格就像行云流水一样平易自然，然而悠远深厚，独臻妙境。千百年来，人们传诵它、探讨它，仿佛在这短短的四行诗里，蕴涵着开掘不完的艺术宝藏。自然而无韵致，则流于浅薄；若无起伏，便失之平直。《春晓》既有悠美的韵致，行文又起伏跌宕，所以诗味醇永。诗人要表现他喜爱春天的感...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}]', '《王孟诗评》：刘风流闲美，正不在多。以诗近词，太以纤丽故。
《唐诗广选》：顾云：真景实情，人说不到。高兴奇语，唯吾孟公。
《唐诗归》：钟云：通是猜境，妙！妙！
《唐诗解》：昔人谓诗如参禅，如此等语，非妙悟者不能道。
《唐诗镜》：喁喁恹恹，绝得闺中体气，宛是六朝之余，第骨未峭耳。
《唐诗选》：玉遮曰：“知多少”，正是“不觉晓”妙处。
《唐诗选脉会通评林》：周珽曰：晓景喧媚，莫卜夜无寂寞。惜春心绪，有说不出之妙。周敬曰：二十字清声婉约。
《唐诗笺要》：朦胧臆想，构此幻境。“落多少”可以不说，又不容不说，诚非妙悟，不能有此。
《而庵说唐诗》：做上二句便煞住笔，复停想到昨夜去，又到花上来，看他用笔不定，瞻之在前，忽然在后矣。或问：何不写“夜来”在前？曰：看题中“晓”字。“处处闻啼鸟”下若再连一笔，则便不算晓矣，故特转到晓之前下“夜来”二字。“风雨声”紧跟上“闻”字，“晓”字便隔寻丈。其作“晓”精微有若此。
《唐诗笺注》：诗到自然，无迹可寻。“花落”句含几许惜春意。
《诗法易简录》：亦具一气流转之妙。
《历代诗评注读本》：描写春晓，而含有一种惋惜之意。惜落花乎？惜韶光耳。
《唐人绝句精华》：此古今传诵之作，佳处在人人所常有，唯浩然能道出之。闻风雨而惜落花，不但可见诗人清致，且有屈子“哀众芳之零落”之感也。', 'center', 1362181144, '57af3d972e958a005450d1ac', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (11057, '春暖郡圃散策三首（其三）', NULL, 78, 4331, 1, 1, '杨万里', NULL, 10248, '57b9ba230a2b58006cb02657', '宋', 'shi', '诗', 'http://baike.baidu.com/view/11520755.htm', '', '春禽处处讲新声，细草欣欣贺嫩晴。
曲折遍穿花底路，莫令一步作虚行。', '', NULL, NULL, NULL, NULL, 'center', 1445529820, '57b9571e0a2b58005c9540cd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (43516, '平山堂', NULL, 1, 291, 0, 1, '陈孚', NULL, 11084, '5858e61e8e450a006c7f7e90', '元', 'shi', '诗', NULL, NULL, '堂上醉翁仙去，芦花雪满汀洲。
二十四桥烟水，为谁流下扬州。', NULL, NULL, NULL, NULL, NULL, 'center', 1555325078, '585ce93261ff4b0063ef97eb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10079, '宿建德江', NULL, 1066, 266, 2, 12, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155061.htm', '', '移舟泊烟渚，日暮客愁新。
野旷天低树，江清月近人。', '这是一首刻画秋江暮色的诗，是唐人五绝中的写景名篇。作者把小船停靠在烟雾迷蒙的江边想起了以往的事情，因而以舟泊暮宿作为自己的抒发感情的归宿，写出了作者羁旅之思。第一句点题，也为下面写景抒情作了准备；第二句中“日暮”是“客愁新”的原因；最后两句，因为“野旷”所以天低于树，因为“江清”所以月能近人，天和树、人和月的关系，写得恰切逼真。此诗前两句为触景生情，后两句为借景抒情，描写了清新的秋夜，突出表现了细微的景物特点。全诗淡而有味，含而不露，自然流出，风韵天成，颇有特色。', '建德江：指新安江流经建德（今属浙江）西部的一段江水。
移舟：划动小船。泊：停船靠岸。烟渚（zhǔ）：指江中雾气笼罩的小沙洲。烟：一作“幽”。渚：水中小块陆地。《尔雅·释水》：“水中可居者曰洲，小洲曰渚。”
客：指作者自己。愁：为思乡而忧思不堪。
野：原野。旷：空阔远大。天低树：天幕低垂，好像和树木相连。
月近人：倒映在水中的月亮好像来靠近人。', '把小船停靠在烟雾迷蒙的小洲，日暮时分新愁又涌上客子心头。
旷野无边无际远天比树还低沉，江水清清明月来和人相亲相近。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929203572034f659e30e", "shortContent": "这是一首抒写羁旅之思的诗。建德江，指新安江流经建德（今属浙江）的一段江水。这首诗不以行人出发为背景，也不以船行途中为背景，而是以舟泊暮宿为背景。它虽然露出一个“愁”字，但立即又将笔触转到景物描写上去了。可见它在选材和表现上都是颇有特色的。\n诗的起句“移舟泊烟渚”，“移舟”，就是移舟近岸的意思；“泊”，这里有停船宿夜的含意。行船停靠在江中的一个烟雾朦胧的小洲边，这一面是点题，另一面也就为下文的写景抒...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0fb", "shortContent": "这是一首抒写羁旅之思的诗。建德江，指新安江流经建德（今属浙江）的一段江水。这首诗不以行人出发为背景，也不以船行途中为背景，而是以舟泊暮宿为背景。它虽然露出一个“愁”字，但立即又将笔触转到景物描写上去了。可见它在选材和表现上都是颇有特色的。\n\n诗的起句“移舟泊烟渚”，“移舟”，就是移舟近岸的意思；“泊”，这里有停船宿夜的含意。行船停靠在江中的一个烟雾朦胧的小洲边，这一面是点题，另一面也就为下文的写景...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e9038f", "shortContent": "客舟行驶在新安江上，现在是在建德地界了。天色将晚，江面烟水迷蒙，靠岸找个地方歇歇脚吧。可上岸后往哪走？去哪里歇脚呢？此处人生地不熟，吃住不会很贵吧？想想这些，真是发愁啊。\n\n光是愁也解决不了问题，在暂时没有想好去处之前，索性看看此处的风景吧。岸上旷野无垠，天地相接，透过树底能看到远处的天边。水面风平浪静，江天一色，水中月亮的倒影清晰可见，人仿佛伸手可触。“野旷天低树，江清月近人”为千古名句。在常识...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127036c9ebcc6fbea1a39c", "shortContent": "客舟行驶在新安江上，现在是在建德地界了。天色将晚，江面烟水迷蒙，靠岸找个地方歇歇脚吧。可上岸后往哪走？去哪里歇脚呢？此处人生地不熟，吃住不会很贵吧？想想这些，真是发愁啊。\n\n光是愁也解决不了问题，在暂时没有想好去处之前，索性看看此处的风景吧。岸上旷野无垠，天地相接，透过树底能看到远处的天边。水面风平浪静，江天一色，水中月亮的倒影清晰可见，人仿佛伸手可触。“野旷天低树，江清月近人”为千古名句。在常识...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127069c305cf0801816fe0", "shortContent": "客舟行驶在新安江上，现在是在建德地界了。天色将晚，江面烟水迷蒙，靠岸找个地方歇歇脚吧。可上岸后往哪走？去哪里歇脚呢？此处人生地不熟，吃住不会很贵吧？想想这些，真是发愁啊。\n光是愁也解决不了问题，在暂时没有想好去处之前，索性看看此处的风景吧。岸上旷野无垠，天地相接，透过树底能看到远处的天边。水面风平浪静，江天一色，水中月亮的倒影清晰可见，人仿佛伸手可触。“野旷天低树，江清月近人。”为千古名句。在常识...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '《鹤林玉露》：孟浩然诗云“江清月近人”，杜陵云“江月去人只数尺”，子美视浩然为前辈，岂祖述而敷衍之耶？浩然之句浑涵，子美之句精工。
《王孟诗评》：刘云：“新”字妙。“野旷”二语酷似老杜。
《批点唐诗正声》：语少意远，清思痛入骨髓。
《唐诗解》：客愁因景而生，故下联不复言情，而旅思自见。
《唐诗选脉会通评林》：周敬曰：神韵无伦。
《唐诗笺要》：襄阳最多率素语，如此绝又杂以庄重，似齐梁俪体。
《唐诗别裁》：下半写景，而客愁自见。
《茧斋诗谈》：“低”字、“近”字，宋人所谓诗眼，却无造作痕，此唐诗之妙也。
《唐诗笺注》：“野旷”一联，人但赏其写景之妙，不知其即景而言旅情，有诗外味。
《唐诗近体》：下半写景而客愁自见，十字咀味不尽。
《唐诗真趣编》：“低”字从“旷”宇生出，“近”字从“清”字生出。野惟旷，故见天低于树；江惟清，故觉月近于人。清旷极矣。烟际泊宿，恍置身海角天涯、寂寥无人之境，凄然四顾，弥觉家乡之远，故云“客愁新”也。下二句不是写景，有“愁”字在内。
《唐人绝句精华》：诗家有情在景中之说，此诗是也。', 'center', 1417547380, '57b910e3d342d3005ac7aafa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10080, '如梦令', NULL, 477, 395, 2, 1, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', 'http://baike.baidu.com/view/5455909.htm', '', '万帐穹庐人醉，星影摇摇欲坠。归梦隔狼河，又被河声搅碎。还睡，还睡，解道醒来无味。', '这首词是作者于康熙二十一年扈从东巡时所作，表现了深沉的思乡之情，以及作者对官场生活的厌烦。此词在写景上相当成功，开头两句「万帐穹庐人醉，星影摇摇欲坠」，尤其广为传诵。', '如梦令：相传为后唐庄宗自制曲，中有「如梦，如梦，残月落花烟重」句，因改今名。
穹庐：圆形的毡帐。
「归梦隔狼河，又被河声搅碎」句：言家乡远隔狼河，归梦不成。纵然做得归梦，河声彻夜，又把梦搅醒。狼河：白狼河，即今大凌河，在辽宁省西部。
解道：知道。', '千万顶行军毡帐之中，将士们酣歌豪饮，酩酊大醉，满天繁星摇曳，那星空仿佛摇摇欲坠。狼河阻隔，回家的梦，被那河水滔滔之声搅的粉碎。闭上眼睛，让梦境延续吧，我知道，梦醒之时，更加百无聊赖。', '[{"bookId": "60fc157134bfda01e0e91549", "bookTitle": "元明清词鉴赏辞典（新一版）", "articleId": "610e865d911759740c9ae795", "shortContent": "词抒羁旅之怀，见思归之意。词人在康熙二十一年（1682）曾扈驾东出山海关祭祀长白山，从词中所写景物来看，应该是这次扈驾东行时所作。\n首句之景，突出塞外特色。“穹庐”即毡帐，是游牧民族为适应长期迁徙生活用毛毡等材料建成的易于拆迁的居所，因为其外形似穹隆而得名。此句写景极为阔大，无尽的原野，无边的夜空，天上星光点点，地上穹庐千万。辽阔、空旷、悠远、静谧之中，透出神秘色彩，确实是祭山的气氛。在这样的写景...", "authors": ["罗立刚"], "pressName": "上海辞书出版社"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3ec26cbf3417f09190", "shortContent": "此篇亦作于康熙二十一年（1682）二月，大约与《长相思》“山一程”同时而作，其意旨也颇为相近，既表现出茫茫草原辽阔壮丽的景象，又透露出浓郁的思乡情绪，显露出疲惫而无奈的羁旅情怀。", "authors": [], "pressName": "崇文书局"}]', '', 'indent', 1362182250, '57b8eace79bc44005b9e1949', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10081, '浣溪沙', NULL, 1821, 395, 1, 5, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', 'http://baike.baidu.com/view/1142981.htm', '', '谁念西风独自凉，萧萧黄叶闭疏窗，沉思往事立残阳。
被酒莫惊春睡重，赌书消得泼茶香，当时只道是寻常。', '这是一首悼亡之作。上阕由问句起，接以黄叶、疏窗、残阳之秋景的勾画，由景物而勾起沉思，氛围已是孤寂凄清。下阕写沉思中所忆起的寻常往事，借用李易安夫妻和美的生活为喻，说明与亡妻往日的美满恩爱。结句的「寻常」二字更道出了今日的酸苦，即那些寻常的往事无法再现，亡妻不可复生，心灵之创痛也永无平复之日。', '浣溪沙：唐教坊曲名，因春秋时期人西施浣纱于若耶溪而得名，后用作词牌名，又名《浣纱溪》、《小庭花》等。此调有平仄两体。全词分上下两阕，上阕三句全用韵，下阕末二句用韵，过阕二句用对偶句的居多。音节明快，句式整齐，易于上口，为婉约派与豪放派多数词人所常用。
谁：此处指亡妻。
萧萧：风吹叶落发出的声音。
疏窗：刻有花纹的窗户。
被酒：中酒、酒醉。
春睡：醉困沉睡，脸上如春色。
赌书：此处为李清照和赵明诚的典故。李易安《金石录后序》云：「余性偶强记，每饭罢，坐归来堂，烹茶，指堆积书史，言某事在某书某卷第几页第几行，以中否角胜负，为饮茶先后。中即举杯大笑，至茶倾覆怀中，反不得饮而起，甘心老是乡矣！故虽处忧患困穷而志不屈。」此句以此典为喻说明往日与亡妻有着像李清照一样的美满的夫妻生活。
消得：消受，享受。', '秋风吹冷，孤独的情怀有谁惦念？看片片黄叶飞舞遮掩了疏窗，伫立夕阳下，往事追忆茫茫。
酒后小睡，春日好景正长，闺中赌书，衣襟满带茶香，昔日平常往事，已不能如愿以偿。', '[{"bookId": "60fc157134bfda01e0e91549", "bookTitle": "元明清词鉴赏辞典（新一版）", "articleId": "610e865e911759740c9ae798", "shortContent": "王国维在托名樊志厚作的《人间词乙稿序》中，称赏纳兰容若“其所为词，悲凉顽艳，独有得于意境之深，可谓豪杰之士，奋乎百世之下者矣”。王氏《人间词话》论词标举“境界说”，谓“内足以摅己而外足以感人者，意与境二者而已”，以王氏的词论观此词，不妨说，上片是境中生意，下片是意中见境，合而观之则达到了意与境合，浑化一体的程度。\n词虽没有加标题，其实是可以补上“悼亡”一类题目的。全词所用词语十分素淡，没有什么华丽...", "authors": ["胡邦彦"], "pressName": "上海辞书出版社"}, {"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126df6c305cf0801816c23", "shortContent": "《全五代诗》题作“浣溪沙曲”。又调名下吴讷《百家词》旧抄本、吕远本、萧江声抄本《南唐二主词》均注：“此词见《西清诗话》。”\n\n“浣溪沙”，唐教坊曲，为每句七字“浣溪纱”之别体。“沙”字应是“纱”误，但已沿用至今，不必深究。此调有数名，一名“山花子”（《词谱》），一名“填字浣溪沙”（《梅苑》），一名“摊破浣溪沙”（《乐府雅词》），结句破七字为十字，故曰“摊破”。一般“浣溪沙”押平声韵，此首押仄声韵，...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3ec26cbf3417f09185", "shortContent": "康熙十八年（1679）春，诸多才子名士齐聚京城，应举鸿儒。张见阳招集陈维崧诸人宴于其山庄，遂有此联句（张一民：《张纯修与纳兰性德交游考》，载《承德民族师专学报》1997年第4期）。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3fc26cbf3417f091b7", "shortContent": "嘶骑一去，征辔不还，玉楼歌吹已经随风飘散。佳人高楼望断，静掩屏帷，愁对绮窗，黯然神伤。停灯向晓，抱影斜倚，半睡半醒之间，一帘幽梦，若隐若现。草熏风暖，春色日浓。一片相思，转成凄楚。“人生自是有情痴，此恨不关风与月”，风月摧折，却使人憔悴。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3f7ccdb86c49f28f51", "shortContent": "康熙元年（1662），时任扬州府推官的王士祯，与袁于令、陈维崧等游红桥，作《红桥倡和》诗，赋《浣溪沙》三首。康熙二十三年（1684），容若扈驾至扬州，用王士祯《浣溪沙》第一首之韵而作此词，凭吊遗迹，感怀隋炀帝旧事。王士祯原词为：“北郭青溪一带流，红桥风物眼中秋。绿杨城郭是扬州。西望雷塘何处是？香魂零落使人愁。淡烟芳草旧迷楼。”", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e4077683d19330150be", "shortContent": "词当是悼亡之作。用李清照之典，赌书泼茶，暗指往日闺中琴瑟相和、情趣相投之甜蜜。但这温馨甜蜜，现如今已成云烟般的往事。词人独立残阳，秋风渐紧而黄叶漫天飞舞，寒意袭来而无人关怀，自然思悠悠，恨悠悠，忆起往日情事而哽咽无言。曾经以为，生活中不经意的那些点点滴滴，只是寻常之事，无须在意，失去之后，才恍然发现它们值得倍加珍惜。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e4077683d19330150c7", "shortContent": "词人奔波于旅途，偶见荒败不知名之野寺，因有所感。于斜阳残照中，容若不知见得几多长短亭，正为自己的劳碌奔波而感到心碎无奈，只觉得忙碌于红尘琐事中毫无所谓。残枝败叶之外，偶然瞥见古刹一座，不由记起当年斗鸡人贾昌，富贵之际，以至于时人感叹“生儿不用识文字，斗鸡走马胜读书”，却最终依然栖宿于古寺，蔬食粗饭。这使他对自己的忙碌更加怀疑起来。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6464506e7f27182da3524606", "bookTitle": "元明清词三百首鉴赏辞典", "articleId": "646b49cd30675327e1a4eeb3", "shortContent": "王国维在托名樊志厚作的《人间词乙稿序》中，称赏纳兰容若“其所为词，悲凉顽艳，独有得于意境之深，可谓豪杰之士，奋乎百世之下者矣”。王氏《人间词话》论词标举“境界说”，谓“内足以摅己而外足以感人者，意与境二者而已”，以王氏的词论观此词，不妨说，上片是境中生意，下片是意中见境，合而观之则达到了意与境合，浑化一体的程度。\n\n词虽没有加标题，其实是可以补上“悼亡”一类题目的。全词所用词语十分素淡，没有什么华...", "authors": ["胡邦彦"], "pressName": "上海辞书出版社"}]', '况夔笙《蕙风词话》：黄东甫……《眼儿媚》云：「当时不道春无价，幽梦费重寻。」此等语非深於词不能道，所谓词心也。……纳兰容若浣溪沙云：「被酒莫惊春睡重，赌书消得泼茶香。当时只道是寻常。」即东甫眼儿媚句意。酒中茶半，前事伶俜、皆梦痕耳。', 'indent', 1362182338, '57b8e243a633bd00665ca7ea', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10082, '朝中措 · 平山堂', NULL, 163, 1229, 4, 1, '欧阳修', NULL, 10018, '57b98d625bbb50005347ace1', '宋', 'ci', '词', 'http://baike.baidu.com/view/2481906.htm', '', '平山阑槛倚晴空，山色有无中。手种堂前垂柳，别来几度春风。
文章太守，挥毫万字，一饮千钟。行乐直须年少，尊前看取衰翁。', '这首词是作者在平山堂送别友人刘原甫时所作。平山堂是作者守扬州时所建，几年后重上平山堂，借酬赠友人之机，追忆起过去的豪迈生活：挥笔著书，赋文逾万字，饮宴堂上，千杯不醉。全词写出了作者意在山水之间的情感，塑造了一个风流儒雅、豪放达观的「文章太守」形象。词风豪放，在欧词中极为少见，对后来东坡的豪放词产生了一定的影响。', '朝中措：词牌名。宋以前旧曲，又名《照江梅》、《芙蓉曲》。双调四十八字，前片三平韵，後片两平韵。
刘仲原甫：当指刘敞。庆历进士，曾官知制诰、集贤院学士等，是欧阳文忠的年辈稍晚的朋友。
维扬：扬州的别称。
平山：即平山堂，为欧阳文忠任扬州知州时所修建，后成为扬州名胜。
「山色有无中」句：此处借用王摩诘《江汉临泛》「江流天地外，山色有无中」句意。
手种堂前垂柳：平山堂前，欧阳文忠曾亲手种下杨柳树。
别来：分别以来。当时作者离开扬州大约八年。
文章太守：作者当年知扬州府时，以文章名冠天下，故自称「文章太守」。一说「文章太守」是作者用以指刘原甫。太守，汉代官名，即宋代的知州。
挥毫万字：挥笔赋诗作文多达万字。
千钟：饮酒千杯。钟，古代酒器。
直须：就该、正应当。
尊：通「樽」，酒杯。
衰翁：词人自称。当时作者五十岁。', '平山堂的栏杆外是晴朗的天空，远山似有似无。我在堂前亲手栽种的那棵柳树啊，离别后又过了几个春光。
这位爱好写文章的太守，下笔就是万言，一饮千杯很豪爽。趁现在年轻赶快行乐吧，您看那坐在酒樽前的老头已白发苍苍。', '[{"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702d77683d1933015340", "shortContent": "清刘熙载在《艺概》中曾说：“冯延巳词，晏同叔得其俊，欧阳修得其深。”胡云翼解释这个“深”字说：“这所谓‘深’，大约是说欧比晏反映的情感真挚、深刻一点。”但他随即又解释道：“但他（指欧阳修）主要还是写士大夫的闲情逸致，题材的范围仍然很狭隘，我们看不出欧阳修和晏殊的词有什么基本的差异。”（《宋词选》）虽然词在宋初被认为“壮夫不为”，但没有初期阶段的这几个奠基人，绝不会有“宋词”这个固定称谓。而欧阳修词...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312718dc26cbf3417f09585", "shortContent": "清刘熙载在《艺概》中曾说：“冯延巳词，晏同叔得其俊，欧阳修得其深。”胡云翼解释这个“深”字说：“这所谓‘深’，大约是说欧比晏反映的情感真挚、深刻一点。”但他随即又解释道：“但他（指欧阳修）主要还是写士大夫的闲情逸致，题材的范围仍然很狭隘，我们看不出欧阳修和晏殊的词有什么基本的差异。”（《宋词选》）虽然词在宋初被认为“壮夫不为”，但没有初期阶段的这几个奠基人，绝不会有“宋词”这个固定称谓。而欧阳修词...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "646a05a345e4710056dab21f", "bookTitle": "欧阳修诗文鉴赏辞典（珍藏本）", "articleId": "646c7e447f27182da374f69d", "shortContent": "叶梦得《避暑录话》卷一说：“欧阳文忠公在扬州作平山堂，壮丽为淮南第一，堂据蜀冈，下临江南数百里，真、润、金陵三州，隐隐若可见。”仁宗嘉祐元年(1056)刘原甫（名敞）出守维扬，词人写这首词饯行，便联系自己守扬时有关景物，致其拳拳之意。古人送友赴任，通常是写诗，欧阳修以词送人赴任，无异是将历来被视为“艳科”的小词提高到与诗同等的地位，在词史上是一个创举。就此词风格而言，在欧阳修《六一词》中也是特殊的...", "authors": ["徐培均"], "pressName": "崇文书局"}]', '宋·严有翼《艺苑雌黄》：平山堂望江左诸山甚近。或以谓永叔短视，故云「山色有无中」。东坡笑之，因赋《快哉亭》道其事云：「长记平山堂上，欹枕江南烟雨，杳杳没孤鸿，认取醉翁语，山色有无中。」盖山色有无（中），非烟雨不能然也。
宋·魏菊庄《菊庄词话》：「平山阑槛倚晴空，山色有无中。」平山堂望江左诸山甚近，或以为永叔短视，故云。东坡笑之。因赋快哉亭道其事云：「长记平山堂上，欹枕江南烟雨，杳杳没孤鸿。认得醉翁语，山色有无中。」盖山色有无，非烟雨不能然也。
明末清初·曹顾菴《南溪词》：读欧公《朝中措》，如见公之「须眉生动，偕游于千载之上也」。
清·刘融斋《艺概》：词有尚风，有尚骨，欧公《朝中措》云：「手种堂前垂柳，别来几度春风。」东坡《雨中花慢》云：「髙会聊追短景，清商不假馀妍。」孰风孰骨可辨。
清·黄苏《蓼园词选》：（「行乐直须年少」句）按，君子进德修业欲及时也，无事不须在少年努力者。现身说法，神采奕奕动人。
清·沈约斋《论词随笔》：用成语，贵浑成脱化，如出诸已。贺方回「旧游梦挂碧云边，人归落雁后，思发在花前」，用薛玄卿句，欧阳永叔「平山栏槛倚晴空。山色有无中」，用王摩诘句，均妙。', 'indent', 1362182537, '57b92daa8ac2470062e10a8e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10083, '步出夏门行 · 其一 · 观沧海', NULL, 1871, 29, 3, 15, '曹操', NULL, 10012, '57b902df5bbb50005b7835f1', '汉', 'shi', '诗', 'http://baike.baidu.com/view/105684.htm', '', '东临碣石，以观沧海。
水何澹澹，山岛竦峙。
树木丛生，百草丰茂。
秋风萧瑟，洪波涌起。
日月之行，若出其中；
星汉灿烂，若出其里。
幸甚至哉！歌以咏志。', '这是一首古体诗。此诗把眼前的海上景色和自己的雄心壮志很巧妙地融合在一起。它的感情非常奔放，思想却很含蓄，所以更有启发性，更能激发我们的想象，更耐人寻味。过去人们称赞曹操的诗深沉饱满、雄健有力，「如幽燕老将，气韵沉雄」，从这里可以得到印证。全诗的基调苍凉慷慨，是建安风骨的代表作品。', '临：登上，有游览的意思。
碣（jié）石：山名。碣石山，河北昌黎碣石山。公元207年秋天，曹操征乌桓得胜回师时经过此地。
沧：通「苍」，青绿色。
海：渤海。
何：多么。
澹澹（dàndàn）：水波摇动的样子。
竦峙（sǒngzhì）：耸立。竦，通耸，高。
丛生：指草木聚集在一处生长。
丰茂：指茂盛，茂密。
萧瑟：树木被秋风吹的声音。
洪波：汹涌澎湃的波浪。
日月：太阳和月亮。
若：如同。好像是。
星汉：银河，天河。
幸：庆幸。
甚：很。
至：极。
咏志：即表达心志。
幸甚至哉：幸运得很，好极了.幸：幸运至：达到极点
咏：歌吟。
志：理想。
歌以咏志：以歌表达心志或理想。', '东行登上碣石山，来观赏那苍茫的海。
海水多么宽阔浩荡，山岛高高地挺立在海边。
树木和百草丛生，十分繁茂，
秋风吹动树木发出悲凉的声音，海中涌着巨大的海浪。
太阳和月亮的运行，好像是从这浩瀚的海洋中发出的。
银河星光灿烂，好像是从这浩瀚的海洋中产生出来的。
我很高兴，就用这首诗歌来表达自己内心的志向。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecc995e272d4b2254ea52", "shortContent": "《步出夏门行》，又名《陇西行》，属古乐府《相和歌·瑟调曲》。“夏门”原是洛阳北面西头的城门，汉代称夏门，魏晋称大夏门。古辞仅存“市朝人易，千岁墓平”二句（见《文选》李善注）。《乐府诗集》另录古辞“邪径过空庐”一篇，写升仙得道之事。曹操此篇，《宋书·乐志》归入《大曲》，题作《碣石步出夏门行》。从诗的内容看，与题意了无关系，可见，只是借古题写时事罢了。诗开头有“艳”辞（序曲），下分《观沧海》、《冬十月...", "authors": ["李文初"], "pressName": "上海辞书出版社"}, {"bookId": "64605c895b7b0d4f45fe6e6e", "bookTitle": "三曹诗文鉴赏辞典", "articleId": "646df3777f27182da37b978a", "shortContent": "《步出夏门行》，又名《陇西行》，属古乐府《相和歌·瑟调曲》。“夏门”原是洛阳北面西头的城门，汉代称夏门，魏晋称大夏门。古辞仅存“市朝人易，千岁墓平”二句（见《文选》李善注）。《乐府诗集》另录古辞“邪径过空庐”一篇，写升仙得道之事。曹操此篇，《宋书·乐志》归入《大曲》，题作《碣石步出夏门行》。从诗的内容看，与题意了无关系，可见，只是借古题写时事罢了。诗开头有“艳”辞（序曲），下分《观沧海》《冬十月》...", "authors": ["李文初"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f632a30675327e1b6eb6f", "shortContent": "《步出夏门行》，又名《陇西行》，属古乐府《相和歌·瑟调曲》。“夏门” 原是洛阳北面西头的城门，汉代称夏门，魏晋称大夏门。古辞仅存“市朝 人易，千岁墓平”二句(见《文选》李善注)。《乐府诗集》另录古辞“邪径过 空庐”一篇，写升仙得道之事。曹操此篇，《宋书·乐志》归入《大曲》，题作 《碣石步出夏门行》。从诗的内容看，与题意了无关系，可见，只是借古题 写时事罢了。诗开头有“艳”辞(序曲)，下分《观沧海》...", "authors": ["李文初"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471ea74a5f1e74f95876a22", "shortContent": "“日月之行，若出其中；星汉灿烂，若出其里。”前面的描写，是从海的平面去观察的，这四句则联系廓落无垠的宇宙，纵意宕开大笔，将大海的气势和威力托现在读者面前：茫茫大海与天相接，空蒙浑融；在这雄奇壮丽的大海面前，日、月、星、汉（银河）都显得渺小了，它们的运行，似乎都由大海自由吐纳。诗人在这里描写的大海，既是眼前实景，又融进了自己的想象和夸张，展现出一派吞吐宇宙的宏伟气象，大有“五岳起方寸”的势态。这种“...", "authors": ["李文初"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "6472f90ba5f1e74f958b2369", "shortContent": "《步出夏门行》，又名《陇西行》，属古乐府《相和歌·瑟调曲》。“夏门”原是洛阳北面西头的城门，汉代称夏门，魏晋称大夏门。古辞仅存“市朝人易，千岁墓平”二句（见《文选》李善注）。《乐府诗集》另录古辞“邪径过空庐”一篇，写升仙得道之事。曹操此篇，《宋书·乐志》归入《大曲》，题作《碣石步出夏门行》。从诗的内容看，与题意了无关系，可见只是借古题写时事罢了。诗开头有“艳”辞（序曲），下分《观沧海》、《冬十月》...", "authors": ["李文初"], "pressName": "上海辞书出版社"}]', '', 'center', 1413388856, '57b8ddabdf0eea0063342e21', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10113, '论语 · 雍也篇 · 第十一章 ', NULL, 167, 327, 1, 2, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', 'http://baike.baidu.com/view/1728986.htm', '', '子曰：“贤哉，回也！一箪食，一瓢饮，在陋巷，人不堪其忧，回也不改其乐。贤哉，回也！”', '选自《论语·雍也》第十一节。孔子称赞颜回“不改其乐”，即贫贱不能移的秉性。由此阐述了一个具有普遍意义的道理，即人总是要有一点精神的，为了自己的理想，就要不断追求，即使生活清苦困顿也自得其乐。', '箪：音dān，古代盛饭用的竹器。
巷：此处指颜回的住处。
乐：乐于学。', '孔子说：“颜回的品质是多么高尚啊！一碗饭，一瓢水，住在简陋的小屋里，别人都忍受不了这种穷困清苦，颜回却没有改变他好学的乐趣。颜回的品质是多么高尚啊！”', NULL, '', 'indent', 1362512143, '57b8ebd7df0eea0063346361', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10085, '游子吟', NULL, 3026, 501, 3, 11, '孟郊', NULL, 10030, '57b96453165abd0054c35040', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/47162/16514015.htm', '', '慈母手中线，游子身上衣。
临行密密缝，意恐迟迟归。
谁言寸草心，报得三春晖。', '本诗是唐代诗人孟郊的五言古诗，属于古体诗。全诗共六句三十字，采用白描的手法，通过回忆一个看似平常的临行前缝衣的场景，凸显并歌颂了母爱的伟大与无私，表达了诗人对母爱的感激以及对母亲深深的爱与尊敬。此诗情感真挚自然，千百年来广为传诵。', '游子：指诗人自己，以及各个离乡的游子。
临：将要。
意恐：担心。归：回来，回家。
谁言：一作“难将”。言：说。寸草：小草。这里比喻子女。心：语义双关，既指草木的茎干，也指子女的心意。
报得：报答。三春晖：春天灿烂的阳光，指慈母之恩。三春：旧称农历正月为孟春，二月为仲春，三月为季春，合称三春。晖（huī）：阳光。形容母爱如春天温暖、和煦的阳光照耀着子女。', '慈母用手中的针线，为远行的儿子赶制身上的衣衫。
临行前一针针密密地缝缀，怕的是儿子回来得晚衣服破损。
有谁敢说，子女像小草那样微弱的孝心，能够报答得了像春晖普泽的慈母恩情呢？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92bc0ce818559d0587d5", "shortContent": "孟郊一生窘困潦倒，直到五十岁时才得到了一个溧阳（今属江苏）县尉的卑微之职。诗人自然不把这样的小官放在心上，仍然放情于山水吟咏，公务则有所废弛，县令就只给他半俸。本篇题下作者自注：“迎母溧上作。”当是他居官溧阳时的作品。诗中亲切而真淳地吟颂了一种普通而伟大的人性美——母爱，因而引起了无数读者的共鸣，千百年来一直脍炙人口。\n深挚的母爱，无时无刻不在沐浴着儿女们。然而对于孟郊这位常年颠沛流离、居无定所的...", "authors": ["左成文"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a99", "shortContent": "孟郊一生窘困潦倒，直到五十岁时才得到了一个溧阳（今属江苏）县尉的卑微之职。诗人自然不把这样的小官放在心上，仍然放情于山水吟咏，公务则有所废弛，县令就只给他半俸。本篇题下作者自注：“迎母溧上作。”当是他居官溧阳时的作品。诗中亲切而真淳地吟颂了一种普通而伟大的人性美——母爱，因而引起了无数读者的共鸣，千百年来一直脍炙人口。\n\n深挚的母爱，无时无刻不在沐浴着儿女们。然而对于孟郊这位常年颠沛流离、居无定所...", "authors": ["左成文"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0c5", "shortContent": "《全唐诗》这首诗题下有一个小注：“自注：迎母溧上作。”孟郊一生窘困潦倒，直到五十岁时才得到了溧阳县尉这样一个卑微的职务。若依这个小注，那么该诗应作于其居官溧阳迎接母亲而作。但全诗分明是写儿子出门远游，临行前母亲为儿子缝制衣服，儿子有感而作。由此看来这个小注不是很可信。\n\n母爱普通而伟大，表现在很多方面。诗人独具匠心，选取母亲为游子缝制衣衫这一极平常而又最足以表达母子之情的场景加以刻画。开头两句“慈...", "authors": ["陈鹏"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706a73206168b2e0220d", "shortContent": "《全唐诗》这首诗题下有一个小注自注：“迎母溧上作。”孟郊一生窘困潦倒，直到五十岁时才得到了溧阳县尉这样一个卑微的职务。若依这个小注，那么该诗应作于其居官溧阳迎接母亲而作。但全诗分明是写儿子出门远游，临行前母亲为儿子缝制衣服，儿子有感而作。看来这个小注不是很可信。\n\n母爱普通而伟大，表现在很多方面。诗人独具匠心，选取母亲为游子缝制衣衫这一极平常而又最足以表达母子之情的场景加以刻画。开头两句“慈母手中...", "authors": ["陈鹏"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127104c9ebcc6fbea1a457", "shortContent": "《全唐诗》这首诗题下有一个小注：“自注，迎母溧上作。”孟郊一生窘困潦倒，直到五十岁时才得到了溧阳县尉这样一个卑微的职务。若依这个小注，那么该诗应作于其居官深阳迎接母亲而作。但全诗分明是写儿子出门远游，临行前母亲为儿子缝制衣服，儿子有感而作。看来这个小注不是很可信。\n\n母爱普通而伟大，表现在很多方面。诗人独具匠心，选取母亲为游子缝制衣衫这一极平常而又最足以表达母子之情的场景加以刻画。开头两句“慈母手...", "authors": ["陈鹏"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "64719ff0b6a81d0c5329842c", "shortContent": "深挚的母爱，无时无刻不在沐浴着儿女们。然而对于孟郊这位常年颠沛流离、居无定所的游子来说，最值得回忆的，莫过于母子分离的痛苦时刻了。此诗描写的就是这种时候慈母缝衣的普通场景，而表现的，却是诗人深沉的内心情感。\n开头两句“慈母手中线，游子身上衣”，实际上是两个词组，而不是两个句子。这样写就从人到物，突出了两件最普通的东西，写出了母子相依为命的骨肉之情。紧接两句写出人的动作和意态，把笔墨集中在慈母上。行...", "authors": ["左成文"], "pressName": "上海辞书出版社"}]', '《唐诗品汇》：刘云：全是托兴，终之悠然。不言之感，复非睍睆寒泉之比。千古之下，犹不忘淡，诗之尤不朽者。
《唐诗归》：钟云：仁孝之言，自然风雅。
《唐诗选脉会通评林》：周敬曰：亲在远游者难读。顾璘曰：所谓雅音，此等是也。
《唐风怀》：南村曰：二语婉至多风，使人子读之，爱慕油然自生，觉“昊天罔极”尚属理语（末二句下）。
《唐风定》：仁孝蔼蔼，万古如新。
《载酒园诗话又编》：贞元、元和间，诗道始杂，类各立门户。孟东野为最高深，如“慈母手中线……”，真是《六经》鼓吹，当与退之《拘幽操》同为全唐第一。
《寒瘦集》：此诗从苦吟中得来，故辞不烦而意尽，务外者观之，翻似不经意。
《柳亭诗话》：孟东野“慈母手中线”一首，言有尽而意无穷，足与李公垂“锄禾日当午”并传。
《唐诗别裁》：即“欲报之德，昊天罔极”意，与昌黎之“臣罪当诛，天王圣明”同有千古。', 'center', 1362183913, '57b8eabc79bc44005b9e1904', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10087, '楚辞 · 渔父', NULL, 308, 31, 5, 1, '屈原', NULL, 10031, '57b90424d342d3005ac744af', '周', 'wen', '文', 'http://baike.baidu.com/subview/139858/5112831.htm', '', '屈原既放，游于江潭，行吟泽畔，颜色憔悴，形容枯槁。渔父见而问之曰：「子非三闾大夫与？何故至于斯！」
屈原曰：「举世皆浊我独清，众人皆醉我独醒，是以见放！」
渔父曰：「圣人不凝滞于物，而能与世推移。世人皆浊，何不淈其泥而扬其波？众人皆醉，何不哺其糟而歠其醨？何故深思高举，自令放为？」
屈原曰：「吾闻之，新沐者必弹冠，新浴者必振衣；安能以身之察察，受物之汶汶者乎！宁赴湘流，葬于江鱼之腹中。安能以皓皓之白，而蒙世俗之尘埃乎！」
渔父莞尔而笑，鼓枻而去，乃歌曰：「沧浪之水清兮，可以濯吾缨。沧浪之水浊兮，可以濯吾足。」遂去不复与言。', '《渔父》中的人物有两个——屈原和渔父。全文采用对比的手法，主要通过问答体，表现了两种对立的人生态度和截然不同的思想性格。文章以屈原开头，以渔父结尾，中间两个自然段则是两人的对答，处处体现了道家的哲学思想。', '既：已经，引申为「（在）……之後」。
颜色：脸色。
形容：形体容貌。
三闾（lǘ）大夫：楚国官职名，掌管教育楚国王族屈、景、昭三姓宗族子弟。屈原曾任此职。
是：这。
以：因为。
见：被。
淈（gǔ）：《说文》：「淈，浊也。从水，屈声。一曰滒泥，一曰水出貌。」
哺：喫。
糟：酒糟。
歠（chuò）：通「啜」，《说文》：「歠，饮也。」
醨（lí）：《说文》：「醨，薄酒也。」
高举：高出世俗的行为。在文中与"深思"都是渔父对屈原的批评，有贬意，故译为（在行为上）自命清高。举，举动。为：句末语气词，表反问。《论语·季氏》：「是社稷之臣也，何以伐为？」
沐：《说文》：「沐，濯髮也。」
浴：《说文》：「浴，洒（xǐ）身也。」洒，古同「洗」。
察察：皎洁的样子。
汶（mén）汶：污浊的样子。
皓皓：洁白的或高洁的样子。
莞尔：微笑的样子。
鼓枻（yì）：摇摆着船桨。鼓，拍打。枻，船桨。
沧浪：水名，汉水的支流，在湖北境内。或谓沧浪为水清澈的样子。"沧浪之水清兮"四句：这首《沧浪歌》，亦名《孺子歌》，又见于《孟子·离娄上》，二"吾"字皆作"我"字，可能是流传于江浙一带的古歌谣。
濯：洗。
缨：繫冠的带子，以二组繫于冠，在颔下打结。', '屈原遭到了放逐，在沅江边上游荡。他沿着江边走边唱，面容憔悴，模样枯瘦。渔父见了向他问道：「您不是三闾大夫么，为什么落到这步田地？「屈原说："天下都是浑浊不堪只有我清澈透明（不同流合污），世人都迷醉了唯独我清醒，因此被放逐。」
渔父说：「圣人不死板地对待事物，而能随着世道一起变化。世上的人都肮脏，何不搅浑泥水扬起浊波，大家都迷醉了。何不既吃酒糟又大喝其酒？为什么想得过深又自命清高。以至让自己落了个放逐的下场？"
屈原说：「我听说：刚洗过头一定要弹弹帽子；刚洗过澡一定要抖抖衣服。怎能让清白的身体去接触世俗尘埃的污染呢？我宁愿跳到湘江里，葬身在江鱼腹中。怎么能让晶莹剔透的纯洁，蒙上世俗的尘埃呢？」
渔父听了，微微一笑，摇起船桨动身离去。唱道：「沧浪之水清又清啊，可以用来洗我的帽缨；沧浪之水浊又浊啊，可以用来洗我的脚。」便远去了，不再同屈原说话。', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf4f7d0ac1145495f5f5", "shortContent": "《楚辞章句》云：“《渔父》者，屈原之所作也。”明代以后始有人怀疑非屈原所作，主要原因是《史记·屈原列传》言“屈原者，名平”。而本篇与《卜居》开头皆曰“屈原”云云。然而六臣注《文选》引《史记》作“屈原字平”，则是名原。《文选》于作者标字，于《离骚》等屈作均标“屈平”，也可证。《离骚》曰：“名余曰正则兮，字余曰灵均。”“正则”即“原”之义，今人犹曰“原则”；“灵均”正是“平”之义，今人犹曰“平均”。《...", "authors": ["赵逵夫"], "pressName": "上海辞书出版社"}, {"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf6503572034f65a982b", "shortContent": "屈原有《渔父》对话，《史记》载入《屈贾列传》，以为实录。但假设问对本即辞赋文体常用的技法，借问答形式，以彰显作者之夙志。《渔父》借渔父说“圣人不凝滞于物而能与世推移”“何不淈其泥而扬其波”，作者坚持：“众人皆醉我独醒”“安能以皓皓之白，而蒙世俗之尘埃乎”，于是渔父笑而鼓栖枻而去，作者则歌《沧浪》之曲以坚守其志。本篇融化《渔父》篇，是继承模拟之作。唯最后是期待：“鹤性多暇，龟年自保。难知避世之由，但...", "authors": ["欧天发"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d35914587d02f5a003", "shortContent": "在《卜居》中经历了巨大内心冲突的诗人，不久又遭遇了一次外部思想的交锋———这就是《渔父》所记载的著名问答。\n文中的“渔父”，究竟是作者之所虚设，还是真有其人？这曾是楚辞研究中的难解之谜。但从司马迁、刘向对此均有记述看，在民间流传的屈原事迹中，大抵真的遇见过这位老渔父。从那“子非三闾大夫欤”的问语中还可推知，他应该还是屈原担任三闾大夫期间曾交往过的熟人。\n这次与渔父的不期而遇，发生在清波迭荡的湘水之...", "authors": ["潘啸龙"], "pressName": "上海辞书出版社"}, {"bookId": "60fccb5034bfda01e0ea02ff", "bookTitle": "先秦诗鉴赏辞典（新一版）", "articleId": "610f375f0f8fda556506c499", "shortContent": "以至让自己落了个放逐的下场？”\n关于《渔父》的作者，历来说法不一。最早认定为屈原作的，是东汉王逸的《楚辞章句》。《楚辞章句》是在西汉末年刘向编的《楚辞》的基础上作注。在《楚辞》中，《渔父》已作为屈原的二十五篇作品之一收入。据此，则认定屈原作《渔父》，又可上推至刘向时。后世认同屈原作《渔父》，影响较大的有南朝梁代萧统编的《昭明文选》和南宋朱熹的《楚辞集注》。但此说漏洞颇多。从外证来说，司马迁在《史记...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413195905, '57b904292e958a005fa5650d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10088, '醉翁亭记', NULL, 681, 1229, 2, 16, '欧阳修', NULL, 10018, '57b98d625bbb50005347ace1', '宋', 'wen', '文', 'http://baike.baidu.com/view/90770.htm', '', '环滁皆山也。其西南诸峰，林壑尤美，望之蔚然而深秀者，琅琊也。山行六七里，渐闻水声潺潺，而泻出于两峰之间者，酿泉也。峰回路转，有亭翼然临于泉上者，醉翁亭也。作亭者谁？山之僧智仙也。名之者谁？太守自谓也。太守与客来饮于此，饮少辄醉，而年又最高，故自号曰醉翁也。醉翁之意不在酒，在乎山水之间也。山水之乐，得之心而寓之酒也。
若夫日出而林霏开，云归而岩穴暝，晦明变化者，山间之朝暮也。野芳发而幽香，佳木秀而繁阴，风霜高洁，水落而石出者，山间之四时也。朝而往，暮而归，四时之景不同，而乐亦无穷也。
至于负者歌于途，行者休于树，前者呼，后者应，伛偻提携，往来而不绝者，滁人游也。临溪而渔，溪深而鱼肥，酿泉为酒，泉香而酒洌，山肴野蔌，杂然而前陈者，太守宴也。宴酣之乐，非丝非竹，射者中，弈者胜，觥筹交错，起坐而喧哗者，众宾欢也。苍颜白发，颓然乎其间者，太守醉也。
已而夕阳在山，人影散乱，太守归而宾客从也。树林阴翳，鸣声上下，游人去而禽鸟乐也。然而禽鸟知山林之乐，而不知人之乐；人知从太守游而乐，而不知太守之乐其乐也。醉能同其乐，醒能述以文者，太守也。太守谓谁？庐陵欧阳修也。', '《醉翁亭记》是北宋文学家欧阳修创作的一篇散文。宋仁宗庆历五年（西元一〇四五年），参知政事范文正等人遭谗离职，欧阳修上书替他们分辩，被贬到滁州做了两年知州。到任以後，他内心抑郁，但还能發挥「宽简而不扰」的作风，取得了某些政绩。《醉翁亭记》就写在这个时期。
文章描写了滁州一带朝暮四季自然景物不同的幽深秀美，滁州百姓和平宁静的生活，特别是作者在山林中与民一齐游赏宴饮的乐趣。全文贯穿一个「乐」字，其中则包含着比较複杂曲折的内容。一则暗示出一个封建地方长官能「与民同乐」的情怀，一则在寄情山水背後隐藏着难言的苦衷。正当四十岁的盛年却自号「醉翁」，而且经常出游，加上他那「饮少辄醉」、「颓然乎其间」的种种表现，都表明欧阳修是借山水之乐来排谴谪居生活的苦闷。', '环：环绕。
滁（chú）：滁州，今安徽省东部。
环滁：环绕着滁州城。
皆：副词，都。
其：代词，它，指滁州城。
壑（hè）：山谷。
尤：格外，特别。
蔚然：草木繁盛的样子。
蔚然而深秀者，琅琊也：树木茂盛，又幽深又秀丽的，是琅琊山。
山：名词作状语，沿着山路。
潺潺（chán）：流水声。
酿泉：泉的名字。因水清可以酿酒，故名。
回：回环，曲折环绕。
峰回路转：山势回环，路也跟着拐弯。比喻事情经历挫折失败後，出现新的转机。
翼然：四角翘起，像鸟张开翅膀的样子。
然：……的样子。
临：指居高临下，高踞，由上往下看。
于：在。
作：建造。
名：名词作动词，命名。
自谓：自称，用自己的别号来命名。
辄（zhé）：就，总是。
年又最高：年纪又是最大的。
号：名词作动词，取别号。
曰：叫做。
意：这里指情趣。「醉翁之意不在酒」，後来用以比喻本意不在此而另有目的。
乎：相当于「于」。
得：领会。
寓：寄托。
夫（fú）：语气助词，无实意，多用于句首。
林霏：树林中的雾气。霏，原指雨、雾纷飞，此处指雾气。
开：消散，散开。
归：聚拢。
暝（míng）：昏暗。
晦：昏暗。
晦明：指天气阴晴昏暗。
芳：花草發出的香味，这里引申为「花」，名词。
發：开放。
秀：植物开花结实。这里有繁荣滋长的意思。
繁阴：一片浓密的树荫。
佳木秀而繁阴：美好的树木繁荣滋长，（树叶）茂密成荫。
风霜高洁，水落而石出者：秋风高爽，霜色洁白，溪水滴落，山石显露。水落石出，原指一种自然景象，大多比喻事情终于真相大白。
至于：连词，于句首，表示两段的过渡，提起另事。
负者：背着东西的人。
休于树：倒装，「于树休」在树下休息。
伛偻（yǔlǚ）：腰背弯曲的样子，这里指老年人。
提携：小孩子被大人领着走，这里指小孩子。
临：来到。
渔：捕鱼。
酿泉：泉水名，原名玻璃泉，在琅邪山醉翁亭下，因泉水很清可以酿酒而得名。
洌（liè）：清澈。
山肴：用从山野捕获的鸟兽做成的菜。
野蔌（sù）：野菜。蔌，菜蔬的总称。
杂然：杂乱的样子。
陈：摆开，陈列。
酣：尽情地喝酒。
丝：絃乐器的代称。
竹：管乐器的代称。非丝非竹：不是音乐。
射：这里指投壶，古人宴饮时的一种游戏，把箭向壶里投，投中多的为胜，负者照规定的杯数喝酒。
弈：下棋。这里用做动词，下围棋。
觥（gōng）：酒杯。
筹：行酒令的筹码，用来记饮酒数。
觥筹交错：酒杯和酒筹交互错杂。
苍颜：容颜苍老。
颓然乎其间：醉醺醺地坐在宾客中间。颓然，原意是精神不振的样子，这里是醉醺醺的样子。
已而：随後，不久。
归：返回，回家。
翳（yì）：遮盖。
阴翳：形容枝叶茂密成阴。
鸣声上下：意思是鸟到处叫。上下，指高处和低处的树林。
乐其乐：乐他所乐的事情。乐，以…为乐。乐，乐事。
醉能同其乐，醒能述以文者：醉了能够同大家一起欢乐，醒来能够用文章记述这乐事的人。
谓：为，是。
庐陵：古郡名，庐陵郡，宋代称吉洲，今江西省吉安市。欧阳修先世为庐陵大族。', '环绕着滁州城的都是山。它西南方的山峰，树林和山谷格外秀美。远远望过去树木茂盛，又幽深又秀丽的，是琅琊山。沿着山上走六七里，渐渐听到潺潺的流水声，是一股水流从两峰之间飞泻而下，是酿泉。山势回环，路也跟着拐弯，有一个四角翘起，像鸟张开翅膀一样高踞于泉水之上的亭子，是醉翁亭。建造这个亭子的人是谁？是山里的和尚智仙。给它命名的人是谁？是太守用自己的号给它命名的。太守和宾客来这里饮酒，喝了一点就醉了，而且年龄又是最大，所以给自己起了个号叫「醉翁」。醉翁的情趣不在喝酒上，而在欣赏山水之间的美景。欣赏山水的乐趣，领会在心里，寄托在喝酒上。
又如太阳出来而树林的雾气消散了；烟云聚拢来，山谷就显得昏暗了。阴暗明亮交替变化的，是山间早晨和傍晚。野花开了，有一股清幽的香味；美好的树木繁茂滋长，形成一片浓郁的绿阴；天高气爽，霜色洁白，冬天溪水落下，露出石头，就是山里的四季景象。早晨进山，傍晚回城。四季的景色不同，乐趣也是无穷无尽的。
至于背负着东西的人在路上欢唱，走路的人在树下休息，前面的人呼喊，後面的人应答；老人弯着腰走，小孩子由大人领着走。来来往往络绎不绝的，是滁州人在出游。来到溪边捕鱼，溪水深，鱼儿肥；用酿泉的泉水来酿酒，泉水清，酒水甜；野味野菜，错杂地摆在面前的，那是太守在宴请宾客。宴会喝酒的乐趣，不在于弹琴奏乐；投壶的人中了，下棋的赢了，酒杯和酒筹交互错杂；人们时坐时起，大声喧哗，是宾客在尽情欢乐。容颜苍老，头髮花白，醉醺醺地坐在众人中间，是太守喝醉了。
不久，夕阳落到山顶，（于是）人的影子散乱一地，这是宾客们跟随着太守归去了。树林里的枝叶茂密成阴，鸟儿到处啼鸣，游人离开，鸟儿快乐。但是鸟儿只知道山林中的乐趣，却不知道人们的乐趣。而人们只知道跟随太守游玩的乐趣，却不知道太守以游人的快乐为快乐。醉了能够和大家一起欢乐，醒来能够用文章记叙这乐事的人，是太守。太守是谁？是庐陵的欧阳修。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1f534a8757d5a0edb8f", "shortContent": "这篇《醉翁亭记》是宋代散文名篇，历来被视为欧阳修的代表作之一。文章的语言平易明畅，写作背景却相当复杂，涵蕴也很丰厚，以致评析此文的主题时，众说纷纭，莫衷一是。\n首先要弄清的是：欧阳修为什么一贬滁州，就自号“醉翁”，并以此名亭，作文为记。就这篇文章内容看，那是由于琅邪山的风景使他陶醉，人与人之间亲密淳朴的关系使他陶醉，那香而且洌的酒使他陶醉。因此有人说，欧为此文，意在寓性情于游赏。或者说，纵情山水，...", "authors": ["赖汉屏"], "pressName": "上海辞书出版社"}, {"bookId": "646a05a345e4710056dab21f", "bookTitle": "欧阳修诗文鉴赏辞典（珍藏本）", "articleId": "646cbf8345e4710056e6b739", "shortContent": "这篇《醉翁亭记》是宋代散文名篇，历来被视为欧阳修的代表作之一。文章的语言平易明畅，写作背景却相当复杂，涵蕴也很丰厚，以致评析此文的主题时，众说纷纭，莫衷一是。\n首先要弄清的是：欧阳修为什么一贬滁州，就自号“醉翁”，并以此名亭，作文为记。就这篇文章内容看，那是由于琅邪山的风景使他陶醉，人与人之间亲密淳朴的关系使他陶醉，那香而且洌的酒使他陶醉。因此有人说，欧为此文，意在寓性情于游赏。或者说，纵情山水，...", "authors": ["赖汉屏"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "64720a855e6bb82b8cfc26c5", "shortContent": "欧文最长于抒情。在这篇散文里，他要抒发的是被贬滁州一年后的生活情怀。因此，题目虽是《醉翁亭记》，在“亭”字上反而着墨不多，用主要篇幅来写“醉翁”。林壑泉亭，无不是醉翁活动的衬景；“日出”“云归”，无不荡漾着醉翁的诗情雅意。这样安排重点，写“亭记”却突出人物，不以亭为核心，乍看似乎离了题面，其实扣紧题旨，是这篇优美的抒情散文在裁剪上独具的特色。但命题既为《醉翁亭记》，当然又不能完全不点到“亭”。这篇...", "authors": ["赖汉屏"], "pressName": "上海辞书出版社"}]', '黄震《黄氏日钞·卷六十一》：《醉翁亭记》，以文为戏者也。
王正德《余师录·卷一》：退之作记，记其事尔。今之记乃论也。少游谓《醉翁辛记》，亦用政体。
王若虚《滹南遗老集·卷三十六》：宋人多讥病《醉翁亭记》。此盖以文滑稽，曰：何害为佳，但不可为法耳。
茅坤《唐宋八大家文钞·卷四十九》：文中之画。昔人读此文谓如游幽泉邃石，入一层才见一层，路不穷兴亦不穷，读已令人神骨翛然长往矣。此是文章中洞天也。
金圣叹《天下才子必读书·卷十三》：一路逐笔缓写，略不使气之文。
林雲铭《古文析义·卷十四》：“亭在滁州西南两峰之间，酿泉之上，自当从滁州说起，层层入题。其作亭之故，亦因彼地有山水佳胜。记虽为亭，而作亦当细写山水。既写山水，自不得不记游宴之乐。此皆作文不易之定体也。但其中点染穿插，布置呼应，各极自然之妙，非人所及。至于亭作，自僧、太守、宾客、滁人皆有分，何故独以己号醉翁为亭之名？盖以太守治滁，滁民咸知有生之乐，故能同作山水之游，即太守亦以民生既遂，无吏事之烦，方能常为宾酣之乐。其所号醉翁，亦从山水之间而得，原非己之旧号，是醉翁大有关于是亭，亭之作始为不虚。夫然则全滁皆莫能争是亭，而醉翁得专名焉。通篇结穴处在“醉翁之意不在酒”一段。末以「乐其乐」三字见意，则乐民之乐，至情蔼然。可见旧解谓「是一篇风月文章，即施于有政，亦不妨碍」等语，何啻隔靴搔痒。计自首至尾，共用二十一个「也」字，句句是记山水，却句句是记亭，句句是记太守。读之帷见当年雍熙气象，故称绝构。
储欣《唐宋十大家全集录·六一居士全集录》：乃遂成一蹊径，然其中有画工所不能到处。
吴楚材、吴调侯《古文观止·卷十》：通篇共用二十一个「也」字，逐层脱卸，逐步顿映，句句是记山水，却句句是记亭，句句是记太守。似散非散，似排非排，丈家之创调也。
吕留良《古文精选·欧阳文》：前人每叹此记为欧阳绝作，闲尝熟玩其辞，要亦无关理道，而通篇以「也」字断句，更何足奇！乃前人推重如此者。
爱新觉罗·弘历《唐宋文醇·卷二十六》：盖于机畅则律吕自调，文中亦具有琴焉，故非他作之所可并也。况修之在滁，乃蒙被垢污而遭谪贬，常人之所不能堪，而君子亦不能无动心者，乃其文萧然自远如此，是其深造自得之功，發于心声而不可强者也。
余诚《重订古文释义新编·卷八》：风平浪静之中，自具波澜潇洄之妙。笔歌墨舞纯乎化境。洵是传记中绝品。至记亭所以名醉翁，以及醉翁所以醉处，俱隐然有乐民之乐意在，而却又未尝着迷。立言更极得体，彼谓似斌体者，固未足与言文；即目为一篇风月丈章，亦终未窥见永叔底里。
张伯行《重订唐未八大家文钞》卷六：文之妙，鹿门评监之。朱子言欧公文字亦多是修改到妙处，倾有人买得他《醉翁辛记》稿，初说滁州四面有山凡数十字，末後改定，只曰「环滁皆山也」五字而已。可见文字最要修改。故附录之。
何焯《义门读书记·卷三十八》：长史云：通篇命意在「醉翁之意」四句，下分两大段摹写。昭昭明太子《陶渊明集·序》云：「有疑渊明诗篇篇有酒，吾观其意不在酒，亦寄酒为迹者也。」公此篇中用其语。独孤至之琅琊溪述云：「公登山，乐山者争同，无小无大，乘兴从会。」又云：「时时醉止，与夕鸟俱。明月满山，朱幡除驱。」亦来用而变化出之。「环滁皆山也」，起句是法阳山天下之穷处也。「若夫山出而林霏开」以下，第二层又写琐屑事。「临溪而渔」至「太守醉也」，还题中醉字。「泉洌而酒香」，《泊宅编》云，东坡书此文改「泉洌而酒香」作“泉香而酒洌”。按。例转列句响，亦本《月令》「水泉必香」也。「树林阴翳」三句，无此一层即意味索然。「然而禽鸟知山林之乐」至末，逐层带转，兼取派上之意。
过珙《古文评注·卷十》：从山出泉，从泉出辛，从辛出人，从人出名，此明明是记，後人即谓之赋体，想读「山间之朝幕也」数段以为类斌耳。不知将此数句节节倒转，便是记体，此意从无人识。
过珙《古文评注·卷十》：有无限乐民之乐意，隐见言外，若止认作风月文章，便失千里。
浦起龙《古文眉诠·卷五十九》：一片天机，无意中得之，人言不可有二者，案臼之见也。族理剨然，特与点出。丰乐者，同民也，故处处触合滁人；醉翁者，写心也，故处处摄归太守。一地一官，两辛两记，各呈意象，分辟吐接。
李扶九《古文笔法百篇·卷六》：评解：随记随解，记体中千古创调也，亦千古绝调也。劈首用一「也」字，生出下二十「也」字。然首一「也」字，是拖起下文，尚应，与下众「也」字实然者不同。从来文中用「也」字之多，无过于此，故独出一奇。闻公初起稿时，从四方说来有数句，共二十餘字，後尽例，作此五字。省而括，高而洁，于此可悟作文不责冗长。又朝慕四时等，赋记中皆成套语，此只六句了之，亦见其人详我略，故不落俗。至末始点明一法，後来古文时文多祖之。盖欧公作《秋声斌》及此首，于作小题法最宜，学者熟读可也。
李扶九《古文笔法百篇·卷六》：书後：自来文人学士，请官栖迟，未有不放怀山水，以寄其幽思。而或抑郁过甚，而辱之以愚；抑或美恶横生，而盖之于物；又或以物悲喜，而古人忧乐绝不关心；甚或闻声感伤，而一己心思，托于音曲。凡此有山水之情，无山水之乐，而皆不得为谪官之极品也。六一公之守滁也，尝与民乐岁物之丰，而兴幸生无事之感。故其篇中写滁人之游，则以「前呼後应」，「伛偻提携」为言，以视忧乐之不关心者何如也？至其丝竹不入，而欢及众宾；禽鸟闻声，而神游物外。绝无沦落自伤之状。而有旷观自得之情。是以乘兴而来，尽兴而返，得山水之乐于一心，不同愚者之喜笑眷慕而不能去焉。然此记也，直谓有文正之规勉，无白傅之牢愁；有东坡之超然，无柳子之抑郁。岂不可哉？岂不可哉？
唐德宜《古文翼·卷七》：记体独僻，通篇写情写景，纯用衬笔，而直追出「太守之乐」，其乐句为结穴。当日政清人和，与民同乐景象，流溢于笔墨之外。', 'indent', 1413109536, '57b5a103128fe1005650a0eb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10089, '岳阳楼记', NULL, 1516, 328, 7, 16, '范仲淹', NULL, 10032, '57b9849979bc44006028bbf4', '宋', 'wen', '文', 'http://baike.baidu.com/view/15258.htm', '', '庆历四年春，滕子京谪守巴陵郡。越明年，政通人和，百废具兴，乃重修岳阳楼，增其旧制，刻唐贤今人诗赋于其上，属予作文以记之。
予观夫巴陵胜状，在洞庭一湖。衔远山，吞长江，浩浩汤汤，横无际涯，朝晖夕阴，气象万千，此则岳阳楼之大观也，前人之述备矣。然则北通巫峡，南极潇湘，迁客骚人，多会于此，览物之情，得无异乎？
若夫淫雨霏霏，连月不开，阴风怒号，浊浪排空，日星隐曜，山岳潜形，商旅不行，樯倾楫摧，薄暮冥冥，虎啸猿啼。登斯楼也，则有去国怀乡，忧谗畏讥，满目萧然，感极而悲者矣。
至若春和景明，波澜不惊，上下天光，一碧万顷，沙鸥翔集，锦鳞游泳，岸芷汀兰，郁郁青青。而或长烟一空，皓月千里，浮光跃金，静影沉璧，渔歌互答，此乐何极！登斯楼也，则有心旷神怡，宠辱偕忘，把酒临风，其喜洋洋者矣。
嗟夫！予尝求古仁人之心，或异二者之为，何哉？不以物喜，不以己悲，居庙堂之高则忧其民，处江湖之远则忧其君。是进亦忧，退亦忧。然则何时而乐耶？其必曰：“先天下之忧而忧，后天下之乐而乐”乎！噫！微斯人，吾谁与归？时六年九月十五日。', '《岳阳楼记》是北宋文学家范文正应好友巴陵郡太守滕子京之请，于北宋庆历六年（西元一〇四六年）九月十五日为重修岳阳楼写的。其中的诗句「先天下之忧而忧，后天下之乐而乐」、「不以物喜，不以己悲」是较为出名和引用较多的句子。文章通过对洞庭湖的侧面描写衬托岳阳楼。滕子京是被诬陷擅自动用官钱而被贬的，范仲淹正是借作记之机，含蓄规劝他要「不以物喜，不以己悲」，试图以自己「先天下之忧而忧，后天下之乐而乐」的济世情怀和乐观精神感染老友。这是本文命意之所在，也决定了文章叙议结合的风格。《岳阳楼记》超越了单纯写山水楼观的狭境，将自然界的晦明变化、风雨阴晴和「迁客骚人」的「览物之情」结合起来写，从而将全文的重心放到了纵议政治理想方面，扩大了文章的境界。', '记：一种文体。可以写景、叙事，多为议论。但目的是为了抒发作者的情怀和政治抱负（阐述作者的某些观念）。
庆历四年：西元一〇四四年。庆历，宋仁宗赵祯的年号。本文末句中的「时六年」，指庆历六年（西元一〇四六年），点明作文的时间。
滕子京：名宗谅，子京是他的字，范文正的朋友。
谪（zhé）守：把被革职的官吏或犯了罪的人充发到边远的地方。在这里作为动词被贬官，降职解释。谪，封建王朝官吏降职或远调；守，做郡的长官。汉朝「守某郡」，就是做某郡的太守；宋朝废郡称州，应说「知某州」。
巴陵郡：即岳州，治所在今湖南岳阳，这里沿用古称。「守巴陵郡」就是「守岳州」。
越明年：有三说，其一指庆历五年，为针对庆历四年而言；其二指庆历六年，此「越」为经过、经历；其三指庆历七年，针对作记时间庆历六年而言。
政通人和：政事顺利，百姓和乐。这是赞美滕子京的话。政，政事；通，通顺；和，和乐。
百废具兴：各种荒废的事业都兴办起来了。百，不是确指，形容其多；废，这里指荒废的事业；具，通「俱」，全、皆；兴，复兴。
乃：于是。
制：规模。
唐贤今人：唐代和当代名人。贤，形容词作名词用。
属（zhǔ）：通「嘱」，嘱托、嘱咐。
予：我。
作文：写文章。
以：连词，用来。
记：记述。
夫：那。
胜状：胜景，好景色。
衔：包含。
吞：吞吐。
浩浩汤汤（shāng）：水波浩荡的样子。汤汤，水流大而急。
横无际涯：宽阔无边。横，广远；际涯，边（际、涯的区别：际专指陆地边界，涯专指水的边界）。
朝晖夕阴，气象万千：或早或晚（一天里）阴晴多变化。朝，在早晨，名词做状语；晖，日光；气象，景象；万千，千变万化。
此则岳阳楼之大观也：这就是岳阳楼的雄伟景象。此，这；则，就；大观，雄伟景象。
前人之述备矣：前人的记述很详尽了。前人之述，指上面说的「唐贤今人诗赋」；备，详尽、完备。
然则：虽然如此，那么。
南极潇湘：南面直到潇水、湘水。潇水是湘水的支流。湘水流入洞庭湖。南，向南；极，尽，最远到达。
迁客：谪迁的人，指降职远调的人。
骚人：诗人。战国时屈原作《离骚》，因此后人也称诗人为骚人。
多：大多。
会：聚集。
览物之情，得无异乎：看到自然景物而引发的情感，怎能不有所不同呢？览，观看、欣赏；得无……乎，大概……吧。
若夫：用在一段话的开头以引起下文。下文的「至若」，同此。「若夫」近似「像那」。「至若」近似「至于」。
霪雨：一作「淫雨」，连绵不断的雨。
霏霏：雨或雪（繁密）的样子。
开：（天气）放晴。
阴：阴冷。
排空：冲向天空。
日星隐曜：太阳和星星隐藏起光辉。曜，一作耀，光辉。
山岳潜形：山岳隐没了形体。岳，高大的山；潜，隐没；形，形迹。
行：走，此指前行。
樯（qiáng）倾楫（jí）摧：桅杆倒下，船桨折断。樯，桅杆；楫，船桨；倾，倒下；摧，折断。
薄暮冥冥：傍晚天色昏暗。薄，迫近；冥冥，昏暗的样子。
则：就。
有：产生……的（情感）。
去国怀乡，忧谗畏讥：离开国都，怀念家乡，担心（人家）说坏话，惧怕（人家）批评指责。去，离开；国，国都，指京城；忧，担忧；谗，谗言；畏，害怕、惧怕；讥，嘲讽。
萧然：凄凉冷落的样子。
感极：感慨到了极点。
而：连词，表顺接。
至若春和景明：至于到了春天气候暖和，阳光普照。至若，至于；春和，春风和煦；景，日光；明，明媚。
波澜不惊：湖面平静，没有惊涛骇浪。惊，这里有「起」「动」的意思。
上下天光，一碧万顷：天色湖面光色交映，一片碧绿，广阔无边。一，一片；万顷，极言其广。
沙鸥翔集，锦鳞游泳：沙鸥时而飞翔，时而停歇，美丽的鱼在水中游来游去。沙鸥，沙洲上的鸥鸟；翔集，时而飞翔时而停歇；集，栖止，鸟停息在树上；锦鳞，指美丽的鱼；鳞，代指鱼；游泳，或浮或沉；游，贴着水面游；泳，潜入水里游。
岸芷（zhǐ）汀（tīng）兰：岸上的小草，小洲上的兰花。芷，香草的一种；汀，小洲，水边平地。
郁郁：形容草木茂盛。
而或长烟一空：有时大片烟雾完全消散。或，有时；长，大片；一，全；空，消散。
皓月千里：皎洁的月光照耀千里。
浮光跃金：湖水波动时，浮在水面上的月光闪耀起金光。这是描写月光照耀下的水波。有些版本作「浮光耀金」。
静影沉璧：湖水平静时，明月映入水中，好似沉下一块玉璧。这里是写无风时水中的月影。璧，圆形正中有孔的玉。沉璧，像沉入水中的璧玉。
互答：一唱一和。
何极：哪有穷尽。何，怎么；极，穷尽。
心旷神怡：心情开朗，精神愉快。旷，开阔；怡，愉快。
宠辱偕忘：荣耀和屈辱一并都忘了。宠，荣耀；辱，屈辱；偕，一起，一作「皆」。
把酒临风：端酒面对着风，就是在清风吹拂中端起酒来喝。把，持、执；临，面对。
洋洋：高兴的样子。
嗟（jiē）夫：唉。嗟夫为两个词，皆为语气词。
尝：曾经。
求：探求。
古仁人：古时品德高尚的人。
心：思想（感情心思）。
或异二者之为：或许不同于（以上）两种心情。或，近于「或许」「也许」的意思，表委婉口气；为，这里指心理活动，即两种心情；二者，这里指前两段的「悲」与「喜」。
不以物喜，不以己悲：不因为外物好坏和自己得失而或喜或悲（此句为互文）。以，因为。
居庙堂之高，处在高高的庙堂上，意为在朝中做官。下文的「进」，即指「居庙堂之高」；庙，宗庙；堂，殿堂；庙堂：指朝廷。
居庙堂之高则忧其民：在朝中做官就担忧百姓。
处江湖之远：处在偏远的江湖间，意思是不在朝廷上做官，下文的「退」，即指「处江湖之远」。
处江湖之远则忧其君：处在僻远的地方做官就为君主担忧。
先天下之忧而忧，后天下之乐而乐：在天下人担忧之前先担忧，在天下人享乐之后才享乐。先，在……之前；后，在……之后；其，指「古仁人」。
微斯人，吾谁与归：（如果）没有这种人，那我同谁一道呢？微，（如果）没有；斯人，这种人（指前文的「古仁人」）；谁与归，就是「与谁归」；归，归依。', '庆历四年的春天，滕子京被贬官做巴陵郡守。到了第二年，政治清明通达，人民安居和顺，过去一切废弃的事情，都重新兴起。于是重修岳阳楼，增加过去旧的规模，刻制唐代贤人和现代人的诗赋在楼上，嘱咐我写一篇文章来记述这件事。
在我看来，巴陵郡的盛景，全在洞庭湖上：衔接远山，吞没长江，流水浩浩荡荡，一望无际，早晨的光辉和晚上的美景，有万千的气象，这就是岳阳楼的大景观，前人的叙述已经很详尽了。然而这里北面通到巫峡，南面极尽潇湘一带，被降职的官吏、诗人墨客，多到这里来聚会，观览景物的心情，难道没有不相同的吗？
当那小雨霏霏落下，一连几个月不断。阴冷的风狂吹怒叫，污浊的水浪横在空中；日月星辰隐没了光辉，山岳潜藏起形迹；商人旅客不能外出，船上的桅杆倾倒、橹桨损坏；傍晚时天色一片昏暗，耳听到老虎啸叫，猿声悲啼。这时登上岳阳楼，则有远离都城，怀念故乡，忧虑别人诽谤，害怕众人嘲讽的种种思绪，满目凄凉，感慨到了极点，心中无限悲伤起来了。
至于那春风清和，春景明媚，湖中波平浪静，上下天光明亮，万顷湖面一片碧绿。沙鸥飞翔云集，锦色的鱼儿在水中游泳，岸上的芷草、汀洲的兰花，显得郁郁青青。有时烟雾全部消散，明月照耀千里，湖面波光闪耀，像金子一样发光，有时月亮在平静湖水中的影子像一轮沉入水中的玉璧，湖上渔人对歌，你问我答，这样快乐的情景，怎么会有穷尽呢？此时登上岳阳楼，则心旷神怡，心情舒畅，人生的荣华富贵，失意受辱都忘掉了。对着美景把酒痛饮，觉得其乐无穷，喜气洋洋了。
哎呀！我曾经探求过古代品德高尚的人的思想，或许不同于以上两种表现，为什么呢？他们不因为外物和个人的得失而欢喜或悲伤。在朝廷上做高官，则忧虑人民；处在江湖远方，就担心君王。他进也忧虑，退也忧愁，那么什么时候才快乐呢？古仁人必定说：「先于天下人的忧去忧，晚于天下人的乐去乐吧！」唉！不是这种人，我与谁一道归去呢？
写于庆历六年九月十五日。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1f403048e64fbd9cd14", "shortContent": "宋人王辟之曾说：“庆历中，滕子京谪守巴陵，治最为天下第一。政成，重修岳阳楼，属范文正公为记，词极清丽。苏子美书石，邵餗篆额，亦皆一时精笔。世谓之‘四绝’云。”（《渑水燕谈录》卷六）作为“四绝”之一的《岳阳楼记》，确是一篇脍炙人口的名文。\n全文共分五段。第一段，叙作记的原因。分三层。“庆历四年春，滕子京谪守巴陵郡。”这是第一层。“谪”字是全文的关键。“越明年，政通人和，百废具兴。”这是第二层。一个被...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "647209eb7f27182da38c6b88", "shortContent": "全文共分五段。第一段，叙作记的原因。分三层。“庆历四年春，滕子京谪守巴陵郡。”这是第一层。“谪”字是全文的关键。“越明年，政通人和，百废具兴。”这是第二层。一个被“谪”的人而能做出这样的成绩，自然值得赞美。作者写这几句，正是赞美滕子京；但也另有用意，后面再谈。“乃重修岳阳楼，增其旧制，刻唐贤今人诗赋于其上。属予作文以记之。”这是第三层。“乃”字承上启下，说明“重修岳阳楼”是在“政通人和，百废具兴”...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '宋·朱晦菴《江陵府曲江楼记》：予于此楼，既未得往寓目焉，无以写其山川风景、朝暮四时之变，如范公之书岳阳也。独次第敬夫本语，而附以予之所感者如此。后有君子，得以览观焉。
宋·陈后山《后山诗话》：范文正公为《岳阳楼记》，用对语说时景，世以为奇。尹师鲁读之曰：传奇体尔。传奇，唐裴铏所著小说也。
宋·欧阳文忠《可斋杂槁》尤焴原序：文正《岳阳楼记》，精切髙古，而欧公犹不以文章许之。然要皆磊磊落落，确实典重，凿凿乎如五穀之疗饥，与世之图章绘句、不根事实者，不可同年而语也。
孙绪：范文正公《岳阳楼记》，或谓其用赋体，殆未深考耳。此是学吕温《三堂记》，体制如出一轴」「然《岳阳楼记》闳远超越，青出于蓝矣。夫以文正千载人物，而乃肯学吕温，亦见君子不以人废言之盛心也。', 'indent', 1413199672, '57b90573165abd0054bff31c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10090, '渔家傲 · 秋思', NULL, 2007, 328, 5, 20, '范仲淹', NULL, 10032, '57b9849979bc44006028bbf4', '宋', 'ci', '词', 'http://baike.baidu.com/view/1341214.htm', '', '塞下秋来风景异，衡阳雁去无留意。四面边声连角起，千嶂里，长烟落日孤城闭。
浊酒一杯家万里，燕然未勒归无计。羌管悠悠霜满地，人不寐，将军白发征夫泪。', '《渔家傲·秋思》是由范仲淹创作，过去认为是其任陕西经略副使兼知延州（今陕西延安市）时写的一首抒怀词，而实际查找文献考订发现其实是在庆州写的。整首词表现将士们的英雄气概及艰苦生活，意境开阔苍凉，形象生动鲜明。上阕描绘边地的荒凉景象，下阕写戍边战士厌战思归的心情。范文正的《渔家傲》变低沉婉转之调而为慷慨雄放之声，把有关国家、社会的重大问题反映到词里，可谓大手笔。从词史上说，此词沉雄开阔的意境和苍凉悲壮的气概，对苏东坡、辛稼轩等也有影响。', '渔家傲：又名《吴门柳》、《忍辱仙人》、《荆溪咏》、《游仙关》。
塞：边界要塞之地，这里指西北边疆。
衡阳雁去：传说秋天北雁南飞，至湖南衡阳回雁峰而止，不再南飞。
边声：边塞特有的声音，如大风、号角、羌笛、马啸的声音。
千嶂：绵延而峻峭的山峰；崇山峻岭。
燕然：即燕然山，今名杭爱山，在今蒙古国境内。
燕然未勒：指战事未平，功名未立。据《后汉书·窦宪传》记载，东汉窦宪率兵追击匈奴单于，去塞三千馀里，登燕然山，刻石勒功而还。
羌管：即羌笛，出自古代西部羌族的一种乐器。
悠悠：形容声音飘忽不定。
寐：睡，不寐就是睡不着。', '秋天到了，西北边塞的风光和江南不同。大雁又飞回衡阳了，一点也没有停留之意。黄昏时，军中号角一吹，周围的边声也随之而起。层峦叠嶂里，暮霭沉沉，山衔落日，孤零零的城门紧闭。
饮一杯浊酒，不由得想起万里之外的家乡，未能像窦宪那样战胜敌人，刻石燕然，不能早作归计。悠扬的羌笛响起来了，天气寒冷，霜雪满地。夜深了，将士们都不能安睡：将军于战士为操持军事，须发都变白了，久戍边塞，也流下了伤时的眼泪。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749dc6e67846a9206abc", "shortContent": "北宋在仁宗即位之后，国家积弱积贫之势益加明显，表面上一片升平，实际上危机四伏，而文风、词风仍在沿袭着晚唐、五代的余习发展。有远见的政治家、文学家都已觉察到问题的严重性，“庆历新政”和古文运动先后发生在这个时期，不是偶然现象，而是当时政治现实、社会现实的客观要求。在词的方面，豪放词开始兴起，一变低沉婉转之调，而为慷慨雄放之声，把有关国家、社会的重大问题反映到词里。范仲淹的《渔家傲》可算是这方面的代表...", "authors": ["李廷先"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a5911759740c9bcb08", "shortContent": "北宋，仁宗即位之后，国家逐渐形成积弱积贫之势，表面上一片升平，实际上危机四伏，而文风、词风仍在沿袭着晚唐、五代的余习发展。有远见的政治家、文学家都已觉察到问题的严重性，“庆历新政”和古文运动先后发生在这个时期，不是偶然现象，而是当时政治现实、社会现实的客观要求。在词的方面，豪放词开始兴起，一变低沉婉转之调，而为慷慨雄放之声，把有关国家、社会的重大问题反映到词里。范仲淹的《渔家傲》可算是这方面的代表...", "authors": ["李廷先"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252ccce4d48ba496d79", "shortContent": "北宋，仁宗即位之后，国家逐渐形成积弱积贫之势，表面上一片升平，实际上危机四伏，而文风、词风仍在沿袭着晚唐、五代的余习发展。有远见的政治家、文学家都已觉察到问题的严重性，“庆历新政”和古文运动先后发生在这个时期，不是偶然现象，而是当时政治现实、社会现实的客观要求。在词的方面，豪放词开始兴起，一变低沉婉转之调，而为慷慨雄放之声，把有关国家、社会的重大问题反映到词里。范仲淹的《渔家傲》可算是这方面的代表...", "authors": ["李廷先"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3a7ccdb86c49f29095", "shortContent": "宋仁宗康定元年（1040）八月，西夏人扰边，范仲淹被调任为陕西经略安抚副使兼知延州（治所在今陕西延安），随军亲临前线。庆历元年（1041）四月，范仲淹调任耀州（治所在今陕西耀县）知州。这首《渔家傲》就写在词人多年戍边征战的营帐里。\n\n纵贯全词，意境开阔，语调铿锵，所写景色奇特瑰丽，形象生动鲜明，慷慨雄放，气郁沉潜，是词人边塞生活与心境的真实写照，无愧为宋代豪放词之先声。\n\n上阕着重写景，首句即开门...", "authors": ["鲁智勇　乐云"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe9f2af4e09d55b66de", "shortContent": "宋仁宗康定元年（1040）八月，西夏人扰边，范仲淹被调任为陕西经略安抚副使兼知延州（治所在今陕西延安），随军亲临前线。庆历元年（1041）四月，范仲淹调任耀州（治所在今陕西耀州）知州。这首《渔家傲》就写在词人多年戍边征战的营帐里。\n\n纵贯全词，意境开阔，语调铿锵，所写景色奇特瑰丽，形象生动鲜明，慷慨雄放，气郁沉潜，是词人边塞生活与心境的真实写照，无愧为宋代豪放词之先声。\n\n上阕着重写景，首句即开门...", "authors": ["鲁智勇　乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127175c305cf08018170b6", "shortContent": "宋仁宗康定元年（1040）八月，西夏人扰边，范仲淹被调任为陕西经略安抚副使兼知延州（治所在今陕西延安），随军亲临前线。庆历元年（1041）四月，范仲淹调任耀州（治所在今陕西铜川耀州区）知州。这首《渔家傲》就写在词人多年戍边征战的营帐里。\n纵贯全词，意境开阔，语调铿锵，所写景色奇特瑰丽，形象生动鲜明，慷慨雄放，气郁沉潜，是词人边塞生活与心境的真实写照，无愧为宋代豪放词之先声。\n上阕着重写景，首句即开...", "authors": ["鲁智勇　乐云"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471fae7902ee364cc9566ce", "shortContent": "“浊酒一杯家万里”，这是词人的自抒怀抱。他身负重任，防守危城，天长日久，难免起乡关之思。这“一杯”与“万里”之间形成了悬殊的对比，也就是说，一杯浊酒，销不了浓重的乡愁，造语雄浑有力。乡愁由何而来呢？“燕然未勒归无计”，这句是用典。燕然，山名，即杭爱山，在今蒙古国境内。汉和帝永元元年(89)，窦宪大破北匈奴，穷追北单于，曾登此山，“刻石勒功而还”（《后汉书·和帝纪》）。词意是说，战争没有取得胜利，还...", "authors": ["李廷先"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413386166, '57b8f448d342d3005ac6d8ea', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10666, '赠内人', NULL, 14, 500, 1, 0, '张祜', NULL, 10152, '57baf998efa631005a803402', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383804.htm', '', '禁门宫树月痕过，媚眼惟看宿鹭窠。
斜拔玉钗灯影畔，剔开红焰救飞蛾。', '此诗咏宫人寂寞无聊的生活，写了她们对真正爱情的渴望和自身的凄清境况。前两句写宫人生活的孤寂苦闷；后两句通过写宫人枯坐“拔玉钗”“救飞蛾”两个形象化动作，表现了她的无聊和对弱小者的同情之心。全诗词采艳丽，语意含蓄，句句描绘宫人孤寂的心情，耐人寻味。', '内人：指宫女。因皇宫又称大内，故宫女称内人。
禁门：宫门。
宿鹭：指双栖之鸳鸯。
红焰：指灯芯。', '月光由宫门移到宫树梢，媚眼只看那宿鹭的窝巢。
在灯影旁拔下头上玉钗，挑开灯焰救出扑火飞蛾。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92cf7d0ac114549539c3", "shortContent": "唐代选入宫中宜春院的歌舞妓称“内人”。她们一入深宫内院，就与外界隔绝，被剥夺了自由和人生幸福。这首诗题为《赠内人》，其实并不可能真向她们投赠诗篇，不过借此题目来驰骋诗人的遐想和遥念而已。这是一首宫怨诗，但诗人匠心独运，不落窠臼，既不正面描写她们的凄凉寂寞的生活，也不直接道出她们的愁肠万转的怨情，只从她们中间一个人在月下、灯畔的两个颇为微妙的动作，折射出她的遭遇、处境和心情。\n诗的首句“禁门宫树月痕...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290f2", "shortContent": "内人，指宫女，因皇宫又称大内，故称。唐代诗人中写宫词的很多，如“柳色参差掩画楼，晓莺啼送满宫愁。年年花落无人见，空逐春泉出御沟”（司马扎《宫怨》），“草生宫阙国无主，玉树后庭花为谁”（许浑《陈宫怨》），“吴王别殿绕江水，后宫不开美人死”（王建《古宫怨》）等等，大抵抒发对宫人容颜易逝、无人欣赏的悲愤与无奈。此诗亦写宫怨，但却匠心独运，构思精妙。在纤细如发的细节描写中，勾勒出宫人慵懒无聊的闲愁情态，含...", "authors": ["乐云"], "pressName": "崇文书局"}]', NULL, 'center', 1417684765, '57bec7d7a633bd005d557deb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10091, '苏幕遮 · 怀旧', NULL, 1815, 328, 4, 9, '范仲淹', NULL, 10032, '57b9849979bc44006028bbf4', '宋', 'ci', '词', 'http://baike.baidu.com/view/1728798.htm', '', '碧云天，黄叶地，秋色连波，波上寒烟翠。山映斜阳天接水，芳草无情，更在斜阳外。
黯乡魂，追旅思。夜夜除非，好梦留人睡。明月楼高休独倚，酒入愁肠，化作相思泪。', '这首词在别本中题作《别恨》或《怀旧》，抒写作者秋天思乡怀人的感情。上阕用多彩的画笔绘出绚丽、高远的秋景，意境开阔。「碧云天，黄叶地」为传诵名句。词的下阕表达客思乡愁带给作者的困扰，极其缠绵婉曲。以夜不能寐、楼不能倚、酒不能消解三层刻画，反言愈切。煞拍酒化为泪，消愁之物反酿成悲戚之情，最为警策。前人颇诧异镇边帅臣「亦作此消魂语」。《左菴词话》解释说：「希文宋一代名臣，词笔婉丽乃尔，比之宋广平赋梅花，才人何所不可，不似世之头巾气重，无与风雅也。」此说可谓得之。', '苏幕遮：词牌名。宋代词家用此调是另度新曲。又名《雲雾敛》、《鬓雲鬆令》。双调，六十二字，上下阕各五句。
波上寒烟翠：江波之上笼罩着一层翠色的寒烟。烟本呈白色，因其上连碧天，下接绿波，远望即与碧天同色。正所谓「秋水共长天一色」。
「芳草无情，更在斜阳外」句：草地绵延到天涯，似乎比斜阳更遥远。「芳草」常暗指故乡，因此，这两句有感叹故乡遥远之意。
黯乡魂：因思念家乡而黯然伤神。黯，形容心情忧郁。语出江文通《别赋》：「黯然销魂者，唯别而已矣。」
旅思（sì）：旅居在外的愁思。思，心绪，情怀。
追旅思：撇不开羁旅的愁思。追，追随，这里有缠住不放的意思。', '碧云飘悠的蓝天，黄叶纷飞的大地，秋景连绵江中水波，波上弥漫苍翠寒烟。群山映斜阳蓝天连江水。芳草不谙人情，一直延绵到夕阳照不到天边。
默默思念故乡黯然神伤，缠人的羁旅愁思难以排遣，除非夜夜都做好梦，在好梦中才能得到片刻安慰。不想在明月夜独倚高楼望远，只有频频地将苦酒灌入愁肠，一杯杯都化作相思的眼泪。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749d7d0ac1145494bb21", "shortContent": "这首词抒写羁旅相思之情，题材基本不脱传统的离愁别恨的范围，但意境的阔大却为这类词所少有。\n上片写秾丽阔远的秋景，暗透乡思。起手两句，即从大处落笔，浓墨重彩，展现出一派长空湛碧、大地澄黄的高远境界，而无写秋景经常出现的衰飒之气。王实甫《西厢记》“长亭送别”一折化用这两句，改为“碧云天，黄花地”，同样极富画画美与诗意美。\n“秋色连波，波上寒烟翠”两句，从碧天广野写到遥接天地的秋水。秋色，承上指碧云天、...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a52e6a6b501f96727c", "shortContent": "这首词抒写羁旅相思之情，题材基本不脱传统的离愁别恨的范围，但意境的阔大却为这类词所少有。\n上片写秾丽阔远的秋景，暗透乡思。起手两句，即从大处落笔，浓墨重彩，展现出一派长空湛碧、大地澄黄的高远境界，而无写秋景经常出现的衰飒之气。王实甫《西厢记》“长亭送别”一折化用这两句，改为“碧云天，黄花地”，同样极富画面美与诗意美。\n“秋色连波，波上寒烟翠”两句，从碧天广野写到遥接天地的秋水。秋色，承上指碧云天、...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252ccce4d48ba496d78", "shortContent": "这首词抒写羁旅相思之情，题材基本不脱传统的离愁别恨的范围，但意境的阔大却为这类词所少有。\n\n上片写秾丽阔远的秋景，暗透乡思。起手两句，即从大处落笔，浓墨重彩，展现出一派长空湛碧、大地澄黄的高远境界，而无写秋景经常出现的衰飒之气。王实甫《西厢记》“长亭送别”一折化用这两句，改为“碧云天，黄花地”，同样极富画面美与诗意美。\n\n“秋色连波，波上寒烟翠”两句，从碧天广野写到遥接天地的秋水。秋色，承上指碧云...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3a7ccdb86c49f29096", "shortContent": "《苏幕遮》创作于范仲淹出任陕西四路宣抚使，主持防御西夏的军事之时。庆历三年（1043），范仲淹任参知政事，提出“十事疏”，主张推行新政。庆历四年（1044），受到朝中保守派的反对，被排斥出朝廷，被贬至陕西。此词上阕借景抒情，下阕直抒胸臆，情景交融，层层渲染，表达了词人去国怀乡的羁旅愁思。\n\n正如王国维《人间词话》所述：“一切景语皆情语‘碧云”、“黄叶”、“秋波”、“寒烟”、“斜阳芳草”，所有的风景...", "authors": ["吕青霞"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe9f2af4e09d55b66df", "shortContent": "《苏幕遮》创作于范仲淹出任陕西四路宣抚使，主持防御西夏的军事之时。庆历三年（1043），范仲淹任参知政事，提出“十事疏”，主张推行新政。庆历四年（1044），受到朝中保守派的反对，被排斥出朝廷，被贬至陕西。此词上阕借景抒情，下阕直抒胸臆，情景交融，层层渲染，表达了词人去国怀乡的羁旅愁思。\n\n正如王国维《人间词话》所述：“一切景语皆情语。”“碧云”、“黄叶”、“秋波”、“寒烟”、“斜阳”、“芳草”，...", "authors": ["吕青霞"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312717c73206168b2e02325", "shortContent": "《苏幕遮》创作于范仲淹出任陕西四路宣抚使，主持防御西夏的军事之时。庆历三年（1043），范仲淹因提出“十事疏”，主张推行新政。庆历四年（1044）受到朝中保守派的反对，被排斥出朝廷，被贬至陕西。该词上阕写秋景，下阕抒发秋思，情景交融，层层渲染，表达了词人去国怀乡的羁旅愁思。\n上阕借景抒情，下阕直抒胸臆。正如王国维《人间词话》所述：“一切景语皆情语”。“碧云”“黄叶”“秋波”“寒烟”“斜阳”“芳草”...", "authors": ["吕青霞"], "pressName": "崇文书局"}]', '淸·谭復堂《谭评词辨》：大笔振迅之作。
淸·徐鞠庄《词苑》引《历代诗馀》：范文正公《苏幕遮》「碧云天」云云，公之正气塞天地，而情语入妙至此。
淸·邹程邨《远志斋词衷》：范希文《苏幕遮》一阕，前段多入丽语，后段纯写柔情，遂成绝唱。
淸·许蒿庐《词综偶评》：铁石心肠人亦作此消魂语。
淸·李佳《左菴词话》：希文宋一代名臣，词笔婉丽乃尔，比之宋广平赋梅花，才人何所不可，不似世之头巾气重，无与风雅也。
唐季特《唐宋词简释》：此首上阕写景，下阕抒情。上阕写天连水，水连山，山连芳草；天带碧云，水带寒烟，山带斜阳。自上及下，自近及远，纯是一片空灵境界，即画亦难到。下阕触景生情。「黯乡魂」四句，写在外淹滞之久与乡思之深。「明月」一句陡提，「酒入」两句拍合，「楼高」点明上阕之景为楼上所见。酒入肠化泪亦新。足见公之真情流露也。', 'indent', 1418771169, '57b8ee4a128fe10054c91757', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10092, '五柳先生传', NULL, 255, 99, 3, 7, '陶渊明', NULL, 10011, '57b8fa07c4c97100558ef104', '晋', 'wen', '文', 'http://baike.baidu.com/view/529739.htm', '', '先生不知何许人也，亦不详其姓字。宅边有五柳树，因以为号焉。
闲静少言，不慕荣利。好读书，不求甚解，每有会意，便欣然忘食。性嗜酒，家贫不能常得，亲旧知其如此，或置酒而招之。造饮辄尽，期在必醉，既醉而退，曾不吝情去留。环堵萧然，不蔽风日，短褐穿结，箪瓢屡空。——晏如也。常著文章自娱，颇示己志。忘怀得失，以此自终。
赞曰：黔娄之妻有言：「不戚戚于贫贱，不汲汲于富贵。」极其言，兹若人之俦乎？衔觞赋诗，以乐其志。无怀氏之民欤！葛天氏之民欤！', '《五柳先生传》是东晋田园派创始人陶渊明代表作之一，是陶渊明自传散文（存争议）。在文中表明其三大志趣，一是读书，二是饮酒，三是写文章，塑造了一个真实的自我，表现了卓然不群的髙尚品格，透露出强烈的人格个性之美。', '详：知道。
姓字：姓名。古代男子二十而冠，冠後另立别名称字。
因以为号焉：就以此为号。以为，以之为。焉，语气助词。
不求甚解：这里指读书只求领会要旨，不在一字一句的解释上过分探究。
会意：指对书中的有所体会。会，体会、领会。
欣然：髙兴的样子。
嗜：喜好。
亲旧：亲戚朋友。旧，这里指旧交，旧友。
如此：像这样，指上文所说的「性嗜酒，家贫不能常得。」
或：有时。
造饮辄（zhé）尽：去喝酒就喝个尽兴。造，往、到；辄，就。
期在必醉：希望一定喝醉。期，期望。
既：已经。
曾（zēng）不吝情去留：五柳先生态度率真，来了就喝酒，喝完就走。曾不，竟不；吝情，捨不得；去留，离开。
环堵（dǔ）：周围都是土墙，形容居室简陋。堵，墙壁。萧然：空寂的样子。
环堵萧然：简陋的居室里空空荡荡。
短褐：粗布短衣，穿结，指衣服破烂。
短褐穿结：粗布短衣上打了个补丁。穿，破；结，缝补。
箪瓢（dānpiáo）屡空：形容贫困，难以喫饱。箪，盛饭的圆形竹器；瓢，饮水用具；屡，经常。
晏如：安然自若的样子。
自终：过完自己的一生。
赞：传记结尾的评论性文字。
黔（qián）娄：战国时期齐稷下先生，齐国有名的隐士和著名的道家学，无意仕进，屡次辞去诸侯聘请。他死後，曾子前去吊丧，黔娄的妻子称赞黔娄「甘天下之淡味，安天下之卑位，不慼慼于贫贱，不汲汲于富贵。求仁而得仁，求义而得义。」
慼慼：忧愁的样子。
汲汲：极力营求的样子、心情急切的样子。
其言：推究她所说的话。
兹：这。
若人：此人，指五柳先生。
俦（chóu）：辈，同类。
觞（shāng）：酒杯。
以乐其志：为自己抱定的志向感到快乐。以，用来。
无怀氏：与下面的「葛天氏」都是传说中的上古帝王。据说在那个时代，人民生活安乐，恬淡自足，社会风气淳厚朴实。', '不知道五柳先生是什么地方的人，也不清楚他的姓字。因为住宅旁边有五棵柳树，就把这个作为号了。他安安静静，很少说话，也不羡慕荣华利禄。他喜欢读书，不在一字一句的解释上过分深究；每当对书中的内容有所领会的时候，就会髙兴得连饭也忘了喫。他生性喜爱喝酒，家里穷经常没有酒喝。亲戚朋友知道他这种境况，有时摆了酒席叫他去喝。他去喝酒就喝个尽兴，希望一定喝醉；喝醉了就回家，竟然说走就走。简陋的居室里空空荡荡，遮挡不住严寒和烈日，粗布短衣上打满了补丁，盛饭的篮子和饮水的水瓢里经常是空的，可是他还是安然自得。常常写文章来自娱自乐，也稍微透露出他的志趣。他从不把得失放在心上，从此过完自己的一生。
赞语说：黔娄的妻子曾经说过：「不为贫贱而忧愁，不热衷于发财做官。这话大概说的是五柳先生这一类的人吧？一边喝酒一边作诗，因为自己抱定的志向而感到无比的快乐。不知道他是无怀氏时代的人呢？还是葛天氏时代的人呢？', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1e0d635634aee3eab2c", "shortContent": "这是一篇用史传体写的自传性散文。五柳先生实即作者陶渊明自己。史传是由史官撰写的，实录行状，见美见刺，褒善贬恶，作出评论，留芳遗臭，千古永垂。而作者俨然以史官立场、春秋笔法来为自己立传。如果不是诡谲寓言，那就是坦然自信。所以本文明显的特点是思想明确，形象鲜明。\n传主五柳先生是个隐士，来路不明，姓氏不传。这并非姑隐其名，也不是隐士必须的特征，因为郡望、籍贯和姓字都可以杜撰，自古以来，隐士而为名士者也不...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4547f27182da33f706b", "bookTitle": "陶渊明诗文鉴赏辞典", "articleId": "646aabe15e6bb82b8cdc558e", "shortContent": "这篇所谓“传”，实际是作者抒述自己志趣的小品。林云铭《古文析义》，谓赞末“无怀”、“葛天”二句，“暗寓不仕宋意”，吴楚材《古文观止》谓“刘裕移晋祚，耻不复仕，号五柳先生，此传乃自述其生平”。刘裕之篡晋为宋，在永初元年（420），逯钦立《陶渊明事迹诗文系年》采林、吴之说，因而假定为渊明五十六岁前后之作。渊明的贫困，也至晚年而益甚。\n全文共用了九个“不”字，钱钟书《管锥编》第四册，以为“不”字为一篇眼...", "authors": ["金性尧"], "pressName": "上海辞书出版社"}]', '南朝齐梁·锺仲伟：文体省净，殆无长语。
宋·洪景庐《容斋随笔·巻八》：陶渊明髙简闲靖，为晋宋第一辈人。语其饥则箪瓢屡空，缾无储秉；其寒则短揭穿结，絺绤冬陈；其居刘环堵萧然，风日不蔽。穷困之状，可谓至矣。
宋·朱晦菴《朱子语类》：晋宋人物，虽曰尚清髙，然个个要官职，这边一面清谈，那边一面招权纳货。陶渊明真个能不要，所以髙于晋宋人物。
清·林损斋《古文析义·巻七》：昭明作陶公传，以此传叙入，别此传乃陶公实录也。看来此老胸中，浩浩落落，总无一点粘着。既好读书亦不知有章句，嗜饮酒亦不知有主客。毋论畜贵贫贱，非得孔、颜乐取，也易语此乎？赞末无怀葛天二句，即夷齐、神农、虞夏之思，暗窝不仕宋意。然以当身，即是上古人物，无采薇忽殁之叹，更觉髙浑也。後人倣作甚多，总无一似。
清·吴楚材、吴调侯《古文观止·巻七》：渊明以彭泽令辞归。後刘裕移晋祚，耻不复仕，号五柳先生。此传乃自述其生平之行也。潇洒澹逸，一片神行之文。
清·浦山伧《古文眉铨·巻四十二》：于客难诸体後，别开畦埒，超绝。昭明为渊明作传，录此一篇，又序其集，称其文章不群，独超众类。
清·李扶九《古文笔法百摘·巻十》：不矜张，不露圭角，淡淡写去，身份自见，亦与其诗相似，非养深者不能。此在文中，乃逸品也，乃逸品也。
民国·毛庆藩《古文学馀·巻二十六》：真气盘旋纸上，不可作文字观。
民国·鲁迅：是个非常平和的田园诗人。他的态度是不容易学的，他非常之穷，而心里很平静。家常无米，就去向人家门口求乞，他穷到衣服也破烂不堪，而还在东篱下采菊，偶然抬起头来，悠然的见了南山，这是何等自然。', 'indent', 1413204975, '57b8fa275bbb50005b77f48f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10093, '兰亭集序', NULL, 1829, 90, 2, 11, '王羲之', NULL, 10033, '57b8fc225bbb50005b7801ea', '晋', 'wen', '文', 'http://baike.baidu.com/subview/6850/17409556.htm', '', '永和九年，岁在癸丑，暮春之初，会于会稽山阴之兰亭，修禊事也。群贤毕至，少长咸集。此地有崇山峻岭，茂林修竹，又有清流激湍，映带左右，引以为流觞曲水，列坐其次。虽无丝竹管弦之盛，一觞一咏，亦足以畅叙幽情。
是日也，天朗气清，惠风和畅。仰观宇宙之大，俯察品类之盛，所以游目骋怀，足以极视听之娱，信可乐也。
夫人之相与，俯仰一世。或取诸怀抱，悟言一室之内；或因寄所托，放浪形骸之外。虽趣舍万殊，静躁不同，当其欣于所遇，暂得于己，怏然自足，不知老之将至。及其所之既倦，情随事迁，感慨系之矣。向之所欣，俯仰之间，以为陈迹，犹不能不以之兴怀，况修短随化，终期于尽！古人云：“死生亦大矣。”岂不痛哉！
每览昔人兴感之由，若合一契，未尝不临文嗟悼，不能喻之于怀。固知一死生为虚诞，齐彭殇为妄作。后之视今，亦犹今之视昔，悲夫！故列叙时人，录其所述。虽世殊事异，所以兴怀，其致一也。后之览者，亦将有感于斯文。', '《兰亭集序》又名《兰亭宴集序》、《兰亭序》。东晋穆帝永和九年（公元353年）三月三日，王羲之与谢安、孙绰等四十一位军政高官，在山阴（今浙江绍兴）兰亭「修禊」，会上各人做诗，《兰亭集序》即为王羲之为众人所作之诗写的序文手稿。文中记叙了兰亭山水之美和聚会的畅快之情，抒发作者对生死无常的感慨。
王羲之手书之真迹已随唐太宗葬于墓中，后人只得由临本中窥见此作。而其临本中又以「神龙本」《兰亭集序》最为称道，因该卷画心前上有唐中宗「神龙」年号小印左半印迹而得名，被认定为是由冯承素奉圣旨于兰亭真迹上双钩所摹，所以应是与真迹最为接近的摹本。本文内容即以《兰亭集序》「神龙摹本」为准。', '永和：东晋穆帝司马聃的年号，从公元345—356年共十二年。永和九年上巳节，王羲之与谢安，孙绰等四十一人。举行禊礼，饮酒赋诗，事后将作品结为一集，由王羲之写了这篇序总述其事。
暮春：阴历三月。暮，晚。
会：集会。
会稽（kuàijī）：郡名，今浙江绍兴。
山阴：今绍兴越城区。
修禊（xì）事也：（为了做）禊礼这件事。古代习俗，于阴历三月上旬的巳日（魏以后定为三月三日），人们群聚于水滨嬉戏洗濯，以祓除不祥和求福。实际上这是古人的一种游春活动。修禊，《兰亭集序》的神龙摹本作“脩稧”。
群贤：诸多贤士能人。指谢安等三十二位社会的名流。贤，形容词做名词。
毕至：全到。毕，全、都。
少长：如王羲之的儿子王凝之、王徽之是少；谢安、王羲之等是长。
咸：都。
崇山峻岭：高峻的山岭。岭，《兰亭集序》的神龙摹本作“领”。
修竹：高高的竹子。修，高高的样子。
激湍：流势很急的水。
映带左右：辉映点缀在亭子的周围。映带，映衬、围绕，《兰亭集序》的神龙摹本作“暎”。
流觞曲（shāngqū）水：用漆制的酒杯盛酒，放入弯曲的水道中任其飘流，杯停在某人面前，某人就引杯饮酒。这是古人一种劝酒取乐的方式。流，使动用法；曲水，引水环曲为渠，以流酒杯。
列坐其次：列坐在曲水之旁。列坐，排列而坐；次，旁边，水边。
丝竹管弦之盛：演奏音乐的盛况。盛，盛大。
一觞一咏：喝着酒作着诗。
幽情：幽深内藏的感情。
是日也：这一天。
惠风：和风。
和畅，缓和。
品类之盛：万物的繁多。品类，指自然界的万物。
所以：用来。
骋：使……奔驰。
极：穷尽。
信：实在。
夫人之相与，俯仰一世：人与人相交往，很快便度过一生。夫，句首发语词，不译。相与，相处、相交往。俯仰，表示时间的短暂。
取诸：取之于，从……中取得。
悟言：面对面的交谈。悟，通“晤”，面对面。
因寄所托，放浪形骸之外：就着自己所爱好的事物，寄托自己的情怀，不受约束，放纵无羁的生活。因，依、随着。寄，寄托。所托，所爱好的事物。放浪，放纵、无拘束。形骸，身体、形体。
趣（qū）舍万殊：各有各的爱好，取舍各不相同。趣舍，即取舍，爱好。趣，通“取”。万殊，千差万别。
静躁：安静与躁动。
暂：短暂，一时。
怏然自足：自大自满的样子。然，……的样子。中学教科书中“怏”字讹作“快”，不可取。
不知老之将至：（竟）不知道衰老将要到来。语出《论语·述而》：“其为人也，发愤忘食，乐以忘忧，不知老之将至云尔。”一本有“曾”在句前。
所之既倦：（对于）所喜爱或得到的事物已经厌倦。之，往、到达。
情随事迁：感情随着事物的变化而变化。迁，变化。
感慨系之：感慨随着产生。系，附着。
向：过去、以前。
以为陈迹：中学教科书中讹“以”字为“已”，今正之。
陈迹：旧迹。
以之兴怀：因它而引起心中的感触。以，因。之，指“向之所欣……以为陈迹”。兴，发生、引起。
修短随化：寿命长短听凭造化。化，自然。
期：至，及。
死生亦大矣：死生是一件大事啊。语出《庄子·德充符》。
契：符契，古代的一种信物。在符契上刻上字，剖而为二，各执一半，作为凭证。
临文嗟（jiē）悼：读古人文章时叹息哀伤。临，面对。
喻：明白。
固知一死生为虚诞，齐彭殇为妄作：本来知道把死和生等同起来的说法是不真实的，把长寿和短命等同起来的说法是妄造的。固，本来、当然。一，把……看作一样；齐，把……看作相等，都用作动词。虚诞，虚妄荒诞的话。殇，未成年死去的人。妄作，妄造、胡说。一生死，齐彭殇，都是庄子的看法。出自《齐物论》。
亦由今之视昔：中学教科书中将“由”字讹作“犹”，不可取。
列叙时人：一个一个记下当时与会的人。
录其所述：录下他们作的诗。
其致一也：人们的思想情趣是一样的。
后之览者：后世的读者。
斯文：这次集会的诗文。', '永和九年，时在癸丑之年，三月上旬，我们会集在会稽郡山阴城的兰亭，为了做禊事。众多贤才都汇聚到这里，年龄大的小的都聚集在这里。兰亭这个地方有高峻的山峰，茂盛的树林，高高的竹子。又有清澈湍急的溪流，辉映环绕在亭子的四周，我们引溪水作为流觞的曲水，排列坐在曲水旁边，虽然没有演奏音乐的盛况，但喝点酒，作点诗，也足够来畅快叙述幽深内藏的感情了。
这一天，天气晴朗，空气清新，和风温暖，仰首观览到宇宙的浩大，俯看观察大地上众多的万物，用来舒展眼力，开阔胸怀，足够来极尽视听的欢娱，实在很快乐。
人与人相互交往，很快便度过一生。有的人在室内畅谈自己的胸怀抱负；有的人就着自己所爱好的事物，寄托情怀，放纵无羁地生活。虽然各有各的爱好，安静与躁动各不相同，但当他们对所接触的事物感到高兴时，一时感到自得和满足，竟然不知道衰老将要到来。等到对得到或喜爱的东西已经厌倦，感情随着事物的变化而变化，感慨随之产生。过去所喜欢的东西，转瞬间，已经成为旧迹，尚且不能不因为它引发心中的感触，况且寿命长短，听凭造化，最后归结于消灭。古人说：“死生毕竟是件大事啊。”怎么能不让人悲痛呢？
每当看到前人所发感慨的原因，其缘由像一张符契那样相和，总难免要在读前人文章时叹息哀伤，不能明白于心。本来知道把生死等同的说法是不真实的，把长寿和短命等同起来的说法是妄造的。后人看待今人，也就像今人看待前人，可悲呀。所以一个一个记下当时与会的人，录下他们所作的诗篇。纵使时代变了，事情不同了，但触发人们情怀的原因，他们的思想情趣是一样的。后世的读者，也将对这次集会的诗文有所感慨。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1dfdbb8b379ee0a14a3", "shortContent": "王羲之精于书法，又富于文才，刘宋人评其文章“高爽有风气，不类常流”（《世说新语·赏誉》注引《文章志》）。这篇《〈兰亭集〉序》，是其传世作品之最佳者。\n兰亭，为东晋会稽郡治山阴（今浙江绍兴市）城西南郊名胜。其地有湖，“湖南有天柱山，湖口有亭，号曰兰亭”（《水经注·渐江水》）。东晋建立后，南渡之中原士族在山水清丽之会稽广置园田别墅。风景幽绝的兰亭，遂成为王羲之、谢安等名流宴集流连之地。穆帝永和九年（3...", "authors": ["方北辰"], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f544d24b2a4416e37c", "shortContent": "魏晋时代是一个书法艺术走向自觉的时代。由于造纸、制笔、研墨技术的发展，各种书体得到了长足的发展。被称为“书圣”的王羲之成为这个时期书法艺术的高峰。唐太宗李世民喜爱其书法亦为人熟知，他认为：“详察古今，研精篆素，尽善尽美，其惟王逸少乎！观其点曳之工，裁成之妙，烟霏露结，状若断而还连；风翥龙蟠，势如斜而反直。玩之不觉为倦，览之莫识其端，心摹手追，此人而已，其余区区之类，何足论哉！”俨然将其推为书家至圣...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f544d24b2a4416e37d", "shortContent": "若说王羲之是魏晋时代最伟大的书法家，那么顾恺之就是魏晋时代成就最高的画家。他不仅有摹本《女史箴图》、《洛神赋图》、《列女仁智图》等作品传世，而且留下了《论画》、《画云台山记》和《魏晋胜流画赞》等绘画理论著作，可以视为中国最早的绘画理论家。\n顾恺之，字长康，晋陵无锡人。他的父亲是担任过尚书左丞的顾悦之，亦出身于名门望族。顾恺之博学多才，不独绘画一绝，对于音乐、文学、玄学等都有非常高的造诣。《晋书》本...", "authors": ["周美玲李欢"], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f9e8f18b220af4c025", "shortContent": "刘穆之，字道和，小字道民，其先祖是西汉时期的齐王刘肥。刘氏世代居住于京口（今江苏镇江），到了东晋时期，这支刘氏家族已经趋于没落。关于刘穆之祖父和父亲的任职情况，史书中鲜有提及，他的叔父（或伯父）刘爽任职尚书都官郎，其从兄刘仲道投奔刘裕担任其参军。刘穆之早年“家本贫贱，赡生之具多缺”。刘穆之的出身虽不太理想，但喜欢读《书》、《传》，博览而精通群书。\n刘裕于京口起兵讨伐桓玄，向何无忌询问适合担任主簿之...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f9e8f18b220af4c026", "shortContent": "徐羡之，字宗文，东海郯（今山东郯城）人。他出身虽非寒门，然上代亦无显官。徐羡之曾祖父徐褚，晋太子洗马（七品），祖父徐宁，晋吏部郎（六品），父亲徐柞之，上虞令（六品）。徐羡之投奔刘裕前，官位低微，按其门第，如无刘裕提拔，很难到达司空、录尚书事等极品高位，所以当上宰相后仍被高门望族琅邪王氏视为“中才寒士”。看来东海徐氏在东晋末大概只是高级士族中位望最差的家族，和一流高门的关系并不深。\n徐羡之有才干，忠...", "authors": ["王骁"], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f9e8f18b220af4c02b", "shortContent": "沈庆之是刘宋王朝的元老重臣，生于晋末乱世，历仕武帝、文帝、孝武帝、前废帝。他以征讨南蛮的军功逐渐升至高级将领，深为群蛮所畏惧，称他为“苍头公”，一旦见到他率领大军，就会直呼“苍头公已复来矣”。\n沈庆之虽然出身寒微且文化程度较低，但刘宋历代帝王均视他为国之栋梁。文帝元嘉末年北伐，对沈庆之的劝谏不予采纳，致使前线萧斌、王玄谟大败于北魏太武帝。众将欲固守碻磝，文帝亦下诏军队不许撤退，沈庆之力排众议，陈说...", "authors": ["李睿毅"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "6471e47eb5420e27678f2132", "shortContent": "王羲之精于书法，又富于文才，刘宋人评其文章“高爽有风气，不类常流”（《世说新语·赏誉》注引《文章志》）。这篇《〈兰亭集〉序》，是其传世作品之最佳者。\n兰亭，为东晋会稽郡治山阴（今浙江绍兴市）城西南郊名胜。其地有湖，“湖南有天柱山，湖口有亭，号曰兰亭”（《水经注·渐江水》）。东晋建立后，南渡之中原士族在山水清丽之会稽广置园田别墅。风景幽绝的兰亭，遂成为王羲之、谢安等名流宴集流连之地。穆帝永和九年（3...", "authors": ["方北辰"], "pressName": "上海辞书出版社"}]', '金圣叹《天下才子必读书》卷九：此文一意反复生死之事甚疾，现前好景可念，更不许顺口说有妙理妙语，真古今第一情种也。
李兆洛《骈体文钞》卷二十一：雅人深致，玩其抑扬之趣。
吴楚材、吴调侯《古文观止》卷七：通篇着眼在死生二字。只为当时士大夫务清谈，鲜实效。一死生而齐彭疡，无经济大略，故触景兴怀，俯仰若有余病。但逸少旷达人，故虽苍凉感叹之中，自有无穷逸趣。
浦起龙《古文眉诠》卷四十二：非止序禊事也，序诗意也。修短死生，皆一时诗意所感，故其言如此。笔情绝俗，高出选体。
余诚《重汀古文释义新编》卷七：因游宴之乐，写人生死之可悲，则兰亭一会，固未可等诸寻常小集。而排斤当日竟尚清谈；倾惑朝廷者之意，亦寓言下。林西仲谓古人游览之文，亦不苟作如此。信非诬也。至其文情之高旷，文致之轻松，更难备述。', 'indent', 1362265196, '57b8fc507db2a20054267d22', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10094, '滕王阁序', NULL, 1900, 132, 5, 11, '王勃', NULL, 10034, '57b9109fa633bd00665dcd5d', '唐', 'wen', '文', 'http://baike.baidu.com/view/25328.htm', '', '豫章故郡，洪都新府。星分翼轸，地接衡庐。襟三江而带五湖，控蛮荆而引瓯越。物华天宝，龙光射牛斗之墟；人杰地灵，徐孺下陈蕃之榻。雄州雾列，俊采星驰。台隍枕夷夏之交，宾主尽东南之美。都督阎公之雅望，棨戟遥临；宇文新州之懿范，襜帷暂驻。十旬休暇，胜友如云；千里逢迎，高朋满座。腾蛟起凤，孟学士之词宗；紫电青霜，王将军之武库。家君作宰，路出名区；童子何知，躬逢胜饯。
时维九月，序属三秋。潦水尽而寒潭清，烟光凝而暮山紫。俨骖騑于上路，访风景于崇阿；临帝子之长洲，得天人之旧馆。层峦耸翠，上出重霄；飞阁流丹，下临无地。鹤汀凫渚，穷岛屿之萦回；桂殿兰宫，列冈峦之体势。
披绣闼，俯雕甍，山原旷其盈视，川泽纡其骇瞩。闾阎扑地，钟鸣鼎食之家；舸舰弥津，青雀黄龙之舳。云销雨霁，彩彻区明。落霞与孤鹜齐飞，秋水共长天一色。渔舟唱晚，响穷彭蠡之滨；雁阵惊寒，声断衡阳之浦。
遥襟甫畅，逸兴遄飞。爽籁发而清风生，纤歌凝而白云遏。睢园绿竹，气凌彭泽之樽；邺水朱华，光照临川之笔。四美具，二难并。穷睇眄于中天，极娱游于暇日。天高地迥，觉宇宙之无穷；兴尽悲来，识盈虚之有数。望长安于日下，目吴会于云间。地势极而南溟深，天柱高而北辰远。关山难越，谁悲失路之人？萍水相逢，尽是他乡之客。怀帝阍而不见，奉宣室以何年？
嗟乎！时运不齐，命途多舛。冯唐易老，李广难封。屈贾谊于长沙，非无圣主；窜梁鸿于海曲，岂乏明时？所赖君子见机，达人知命。老当益壮，宁移白首之心？穷且益坚，不坠青云之志。酌贪泉而觉爽，处涸辙以犹欢。北海虽赊，扶摇可接；东隅已逝，桑榆非晚。孟尝高洁，空余报国之情；阮籍猖狂，岂效穷途之哭！
勃，三尺微命，一介书生。无路请缨，等终军之弱冠；有怀投笔，慕宗悫之长风。舍簪笏于百龄，奉晨昏于万里。非谢家之宝树，接孟氏之芳邻。他日趋庭，叨陪鲤对；今辰捧袂，喜托龙门。杨意不逢，抚凌云而自惜；钟期既遇，奏流水以何惭？
呜乎！胜地不常，盛筵难再，兰亭已矣，梓泽丘墟。临别赠言，幸承恩于伟饯；登高作赋，是所望于群公。敢竭鄙怀，恭疏短引；一言均赋，四韵俱成。请洒潘江，各倾陆海云尔。
滕王高阁临江渚，珮玉鸣鸾罢歌舞。
画栋朝飞南浦云，珠帘暮卷西山雨。
闲云潭影日悠悠，物换星移几度秋。
阁中帝子今何在？槛外长江空自流。', '《滕王阁序》全称《秋日登洪府滕王阁饯别序》，亦名《滕王阁诗序》，骈文名篇。滕王阁位于江西省南昌市赣江滨。唐高祖之子滕王李元婴任洪州都督时（公元653年）始建，后阎伯屿为洪州牧，宴群僚于阁上，王勃省父过此，即席而作。《滕王阁序》笔力明快、风格清新、气势浩荡，堪称骈文典范之作。文中铺叙滕王阁一带形势景色和宴会盛况，抒发了作者“无路请缨”之感慨。', '豫章：滕王阁在今江西省南昌市。南昌，为汉豫章郡治。唐代宗当政之后，为了避讳唐代宗的名（李豫），「豫章故郡」被替换为「南昌故郡」。所以现存滕王阁内的石碑以及苏轼的手书都称作「南昌故郡」。
故：以前的。
洪都：汉豫章郡，唐改为洪州，设都督府。
星分翼轸：古人习惯以天上星宿与地上区域对应，称为「某地在某星之分野」。据《晋书·天文志》，豫章属吴地，吴越扬州当牛斗二星的分野，与翼轸二星相邻。翼、轸，星宿名，属二十八宿。
衡：衡山，此代指衡州（治所在今湖南省衡阳市）。
庐：庐山，此代指江州（治所在今江西省九江市）。
襟：以……为襟。因豫章在三江上游，如衣之襟，故称。
三江：太湖的支流松江、娄江、东江，泛指长江中下游的江河。
带：以…为带。五湖在豫章周围，如衣束身，故称。
五湖：一说指太湖、鄱阳湖、青草湖、丹阳湖、洞庭湖，又一说指菱湖、游湖、莫湖、贡湖、胥湖，皆在鄱阳湖周围，与鄱阳湖相连。以此借为南方大湖的总称。
蛮荆：古楚地，今湖北、湖南一带。
引：连接。
瓯越：古越地，即今浙江南部地区。古东越王建都于东瓯（今浙江省永嘉县），境内有瓯江。
物华天宝：物的精华就是天上的珍宝。
龙光射牛斗之墟：龙光，指宝剑的光辉。牛、斗，星宿名。墟、域，所在之处。据《晋书·张华传》，晋初，牛、斗二星之间常有紫气照射。张华请教精通天象的雷焕，雷焕称这是宝剑之精，上彻于天。张华命雷焕为丰城令寻剑，果然在丰城（今江西省丰城市，古属豫章郡）牢狱的地下，掘地四丈，得一石匣，内有龙泉、太阿二剑。后这对宝剑入水化为双龙。
俊采：指人才。
懿范：美好的风范。
宰：县令。
天人：一作「仙人」
维：在。又有一说此字为语气词，不译。
序：时序（春夏秋冬）
三秋：古人称七、八、九月为孟秋、仲秋、季秋，三秋即季秋，九月。此句被前人誉为“写尽九月之景”。
潦水：雨后的积水。
尽：没有俨：整齐的样子。
骖騑：驾车的马匹。上路：高高的道路。
访：看
崇阿：高大的山陵。
临、得：到。
帝子、天人：都指滕王李元婴。有版本为“得仙人之旧馆”。
长洲：滕王阁前赣江中的沙洲。
旧馆：指滕王阁
层：重叠。
上：上达。
飞阁流丹：飞檐涂饰红漆。有版本为“飞阁翔丹”。（新课改上对“流丹”给出的注解是：朱红的漆彩鲜艳欲滴）飞阁：架空建筑的阁道。流：形容彩画鲜艳欲滴。丹：丹漆，泛指彩绘
临：从高处往下探望。
鹤汀凫渚：鹤所栖息的水边平地，野鸭聚处的小洲。汀：水边平地。凫：野鸭。渚：水中小洲。
萦回：曲折。
列冈峦之体势：依着山岗的形式（而高低起伏）。列冈一作即冈。
桂，兰：两种名贵的树，形容宫殿的华丽，讲究。
遄：迅速。
朱华：荷花。
睇眄：看。
安贫：一作「见机」。
酌贪泉而觉爽：贪泉，在广州附近的石门，传说饮此水会贪得无厌，吴隐之喝下此水操守反而更加坚定。据《晋书·吴隐之传》，廉官吴隐之赴广州刺史任，饮贪泉之水，并作诗说：「古人云此水，一歃怀千金。试使（伯）夷（叔）齐饮，终当不易心。」
处涸辙：乾涸的车辙，比喻困厄的处境。《庄子·外物》有鲋鱼处涸辙的故事。
「北海虽赊，扶摇可接」句：语意本《庄子·逍遥游》。
东隅：日出处，表示早晨，引申为「早年」。
桑榆：日落处，表示傍晚，引申为「晚年」。
「东隅已逝，桑榆非晚」句：早年的时光消逝，如果珍惜时光，发愤图强，晚年并不晚。《后汉书·冯异传》：「失之东隅，收之桑榆。」
孟尝：据《后汉书·孟尝传》，孟尝字伯周，东汉会稽上虞人。曾任合浦太守，以廉洁奉公著称，后因病隐居。桓帝时，虽有人屡次荐举，终不见用。
阮籍：字嗣宗，晋代名士，不满世事，佯装狂放，常驾车出游，路不通时就痛哭而返。《晋书·阮籍传》：籍「时率意独驾，不由径路。车迹所穷，辄恸哭而反。」
三尺：衣带下垂的长度，指幼小。古时服饰制度规定束在腰间的绅的长度，因地位不同而有所区别，士规定为三尺。古人称成人为「七尺之躯」，称不大懂事的小孩儿为「三尺童儿」。
微命：即「一命」，周朝官阶制度是从一命到九命，一命是最低级的官职。
一介：一个。
终军：《汉书·终军传》：「终军字子雲，汉代济南人。武帝时出使南越，自请「愿受长缨，必羁南越王而致之阙下」，时仅二十馀岁。
等：相同，用作动词。
弱冠：古人二十岁行冠礼，表示成年，称「弱冠」。
投笔：事见《后汉书·班超传》，用汉班超投笔从戎的故事。
宗慤：据《宋书·宗慤传》：「宗慤字元干，南朝宋南阳人，年少时向叔父自述志向，云‘愿乘长风破万里浪。’」后因战功受封。
簪笏：冠簪、手版。官吏用物，这里代指官职地位。
百龄：百年，犹「一生」。
奉晨昏：侍奉父母。《礼记·曲礼上》：「凡为人子之礼……昏定而晨省。」
非谢家之宝树：指谢玄，比喻好子弟。《世说新语·言语》：「谢太傅（安）问诸子侄‘子弟亦何预人事，而正欲使其佳？’诸人莫有言者。车骑（谢玄）答曰：‘譬如芝兰玉树，欲使其生于庭阶耳。’」
接孟氏之芳邻：见刘向《列女传·母仪篇》。据说孟轲的母亲为教育儿子而三迁择邻，最后定居于学宫附近。接，通「结」，结交。
「他日趋庭，叨陪鲤对」句：《论语·季氏》：「（孔子）尝独立，（孔）鲤趋而过庭。（子）曰：‘学诗乎？’对曰：‘未也。’‘不学诗，无以言。’鲤退而学诗。他日，又独立，鲤趋而过庭。（子）曰：‘学礼乎？’对曰：‘未也。’‘不学礼，无以立。’鲤退而学礼。闻斯二者」鲤，孔子之子孔鲤；趋庭，受父亲教诲。
辰：一作「兹」
捧袂：举起双袖，表示恭敬的姿势。
喜托龙门：《后汉书·李膺传》：「膺以声名自高，士有被其容接者，名为登龙门。」
「杨意不逢，抚凌云而自惜」句：据《史记·司马相如列传》载，司马相如经蜀人杨得意引荐，方能入朝见汉武帝。又云：「相如既奏《大人》之颂，天子大悦，飘飘有凌云之气。」杨意，杨得意的省称；凌云，指司马相如作《大人赋》。
「锺期即遇，奏流水以何惭」句：《列子·汤问》：「伯牙善鼓琴，锺子期善听。伯牙鼓琴……志在流水，锺子期曰：‘善哉！洋洋兮若江河。’」锺期，锺子期的省称。
胜：名胜。
不：不能。
常：长存。
难：难以。
再：再次遇到。
兰亭：在浙江绍兴市。晋穆帝永和九年（公元353年）三月三日上巳节，王羲之与群贤宴集于此，行修禊礼，祓除不祥。
梓泽：即晋朝石崇的金谷园，故址在今河南省洛阳市西北。
临别赠言：临别时赠送正言以互相勉励，在此指本文。
恭疏短引：恭敬地写下一篇小序，在此指本文。
一言：一首诗。
赋：铺陈。
四韵：八句四韵诗，指王勃此时写下的《滕王阁诗》：「滕王高阁临江渚，佩玉鸣鸾罢歌舞。画栋朝飞南浦云，珠帘暮卷西山雨。闲云潭影日悠悠，物换星移几度秋。阁中帝子今何在？槛外长江空自流。」
四韵俱成：（我的）四韵一起写好了。
「请洒潘江，各倾陆海云尔」句：锺嵘《诗品》：「陆（机）才如海，潘（岳）才如江。」这里形容各宾客的文采。
珮玉鸣鸾：舞女身上的装饰，代指舞女。', '这里以往是汉代的豫章郡城，如今是洪州的都督府，天上的方位属于翼、轸两星宿的分野，地上的位置连结着衡山和庐山。以三江为衣襟，以五湖为衣带、控制着楚地，连接着瓯越。物的精华是上天的珍宝，宝剑的光芒直冲上牛、斗二星之间。因为大地有灵气，所以英杰辈出，陈蕃专为徐孺设下几榻。雄伟的大洲像雾一般涌起，博学的人才，像繁星一样地活跃。城池坐落在夷夏交界的地方，主人与宾客，集中了东南地区的英俊之才。都督阎公，享有崇高的名望，远道来到洪州坐镇，宇文州牧，是美德的楷模，赴任途中特地在此暂留。正逢十日休暇的日子，杰出的友人云集，高贵的宾客，也都不远千里来到这里聚会。文坛领袖孟学士所作文章的气势像腾起的蛟龙，飞舞的彩凤，王将军的兵器库里，藏有像紫电剑、青霜剑这样锋利的宝剑。由于父亲在交趾做县令，我在探亲途中经过这个著名的地方。我年幼无知，竟有幸亲身参加了这次盛大的宴会。
时当九月，季秋时节。积水消尽，潭水清澈，天空凝结着淡淡的云烟，暮霭中山峦呈现一片紫色。在高高的山路上驾着马车，在崇山峻岭中访求风景。来到滕王阁前的沙洲，发现了滕王所修的滕王阁。这里山峦重叠，青翠的山峰耸入云霄。凌空的楼阁，红色的阁道犹如飞翔在天空，从阁上看不到地面。白鹤，野鸭停息的小洲，极尽岛屿的纡曲回环之势，雅浩的宫殿，跟起伏的山峦配合有致。
推开雕花的阁门，俯视彩饰的屋脊，山峰平原尽收眼底，湖川曲折令人惊讶。遍地是里巷宅舍，许多钟鸣鼎食的富贵人家。舸舰塞满了渡口，尽是雕上了青雀黄龙花纹的大船。正值雨过天晴，虹消云散，阳光朗煦，落霞与野鸭一起飞翔，秋水和长天连成一片。傍晚渔舟中传出的歌声，响彻彭蠡湖滨，雁群感到寒意而发出的惊叫，鸣声到衡阳之浦为止。
放眼远望，胸襟刚感到舒畅，超逸的兴致立即兴起，排箫的音响引来的徐徐清风，柔缓的歌声吸引住飘动的白云。像睢园竹林的聚会，这里善饮的人，酒量超过彭泽县令陶渊明，像邺水赞咏莲花，这里诗人的文采，胜过临川内史谢灵运。（音乐与饮食，文章和言语）这四种美好的事物都已经齐备，（贤主、嘉宾）这两个难得的条件也凑合在一起了，向天空中极目远眺，在假日里尽情欢娱。苍天高远，大地辽阔，令人感到宇宙的无穷无尽。欢乐逝去，悲哀袭来，我知道了事物的兴衰成败是有定数的。西望长安，东指绍兴，南方的陆地已到尽头，大海深不可测，北方的北斗星多么遥远，天柱高不可攀。关山重重难以越过，有谁同情不得志的人？萍水偶尔相逢，大家都是异乡之客．怀念着君王的宫门，但却不被召见，什么时候才能够去侍奉君王呢？
呵，各人的时机不同，人生的命运多有不顺。冯唐容易衰老，李广难得封侯。使贾谊遭受委屈，贬于长沙，并不是没有圣明的君主，使梁鸿逃匿到齐鲁海滨，难道不是政治昌明的时代？只不过由于君子能了解时机，通达的人知道自己的命运罢了。年纪虽然老了，但志气应当更加旺盛，怎能在白头时改变心情？境遇虽然困苦，但节操应当更加坚定，决不能抛弃自己的凌云壮志。即使喝了贪泉的水，心境依然清爽廉洁；即使身处于干涸的车辙中，胸怀依然开朗愉快。北海虽然十分遥远，乘着旋风还是能够达到，早晨虽然已经过去，而珍惜黄昏却为时不晚。孟尝心地高洁，但白白地怀抱着报国的热情，阮籍为人放纵不羁，我们怎能学他那种穷途的哭泣！
我地位卑微，只是一个书生。虽然和终军一样年已二十一，却无处去请缨杀敌。我羡慕宗悫那种“乘长风破万里浪”的英雄气概，也有投笔从戎的志向。如今我抛弃了一生的功名，不远万里去朝夕侍奉父亲。虽然称不上谢家的“宝树”，但是能和贤德之士相交往。不久我将见到父亲，聆听他的教诲。今天我侥幸地奉陪各位长者，高兴地登上龙门。假如碰不上杨得意那样引荐的人，就只有抚拍着自己的文章而自我叹惜。既然已经遇到了钟子期，就弹奏一曲《流水》又有什么羞愧呢？
呵！名胜之地不能常存，盛大的宴会难以再逢。兰亭宴集已为陈迹，石崇的梓泽也变成了废墟。承蒙这个宴会的恩赐，让我临别时作了这一篇序文，至于登高作赋，这只有指望在座诸公了。我只是冒昧地尽我微薄的心意，作了短短的引言。在座诸位都按各自分到的韵字赋诗，我已写成了四韵八句。请在座诸位施展潘岳，陆机一样的才笔，各自谱写瑰丽的诗篇吧！
巍峨高耸的滕王阁俯临着江心的沙洲，想当初佩玉、鸾铃鸣响的豪华歌舞已经停止了。早晨，画栋飞上了南浦的云；黄昏，珠帘卷入了西山的雨。悠闲的彩云影子倒映在江水中，整天悠悠然地漂浮着；时光易逝，人事变迁，不知已经度过几个春秋。昔日游赏于高阁中的滕王如今已不知哪里去了，只有那栏杆外的滔滔江水空自向远方奔流。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1e803572034f65a9afc", "shortContent": "滕王阁为唐永徽四年（653）高祖子滕王李元婴为洪州都督时所建，以封号为名，故址在今江西南昌市赣江滨。上元二年（675）九月，王勃往南海省亲，途中路经洪州，逢都督阎公在滕王阁大宴宾客，遂在宴会上挥毫写成此《秋日登洪府滕王阁饯别序》（简称《滕王阁序》）。这篇临别赠言虽为即兴之作，但堪称古代骈文中的精品。在严格的骈体形式束缚下，作者充分发挥骈文特有的表现手段，熔对偶、声韵、事典、辞藻于一炉，又运散文之气...", "authors": ["顾伟列"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "6471e516b6a81d0c532af6ac", "shortContent": "滕王阁为唐永徽四年(653 )高祖子滕王李元婴为洪州都督时所建，以封号为名，故址在今江西南昌市赣江滨。上元二年（675）九月，王勃往南海省亲，途中路经洪州，逢都督阎公在滕王阁大宴宾客，遂在宴会上挥毫写成此《秋日登洪府滕王阁饯别序》（简称《滕王阁序》）。这篇临别赠言虽为即兴之作，但堪称古代骈文中的精品。在严格的骈体形式束缚下，作者充分发挥骈文特有的表现手段，熔对偶、声韵、事典、辞藻于一炉，又运散文之...", "authors": ["顾伟列"], "pressName": "上海辞书出版社"}]', '五代·王定保《唐摭言》：王勃著《滕王阁序》，时年十四。都督阎公不之信，勃虽在座，而阎公意属子婿孟学士者为之，已宿构矣。及以纸笔，延让宾客，勃不辞。公大怒，拂衣而起，专令人伺其下笔。第一报云：「南昌故郡，洪都新府。」公曰：「亦是老生常谈。」又报云：「星分翼轸，地接衡庐。」公闻之，沉吟不语。又云：「落霞与孤鹜齐飞，秋水共长天一色。」公矍然而起曰：「此真天才，当垂不朽矣！」遂亟请宴所，极欢而罢。
《旧唐书·文苑传》：勃六岁解属文，构思无滞，词情英迈。勃文章迈捷，下笔则成，尤好著书，撰《周易发挥》五卷及《次论》等书数部，勃亡后，并多遗失。有文集三十卷。勃聪警绝众，于推步历算尤精，尝作《大唐千岁历》。
《新唐书·文艺传》：六岁善文辞，九岁得颜师古注《汉书》读之，作《指瑕》以其失。勃属文，初不精思，先磨墨数升，则酣饮，引被覆面卧，及寤，援笔成篇，不易一字，时人谓勃为腹稿。尤喜著书。', 'indent', 1362265914, '57af1324c4c9710054770b01', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10095, '望岳', NULL, 3292, 1416, 3, 18, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155521.htm', '', '岱宗夫如何？齐鲁青未了。
造化钟神秀，阴阳割昏晓。
荡胸生曾云，决眦入归鸟。
会当凌绝顶，一览众山小。', '本诗是杜甫青年时代的作品，充满了诗人青年时代的浪漫与激情。全诗紧紧围绕诗题「望岳」的「望」字着笔，由远望到近望，再到凝望，最后是俯望。诗人描写了泰山雄伟磅礴的气象，抒发了自己勇于攀登，傲视一切的雄心壮志，洋溢着蓬勃向上的朝气。', '岱宗：泰山亦名岱山或岱岳，五岳之首，在今山东省泰安市城北。古代以泰山为五岳之首，诸山所宗，故又称「岱宗」。历代帝王凡举行封禅大典，皆在此山，这里指对泰山的尊称。
夫（fú）：句首发语词，无实在意义，语气词，强调疑问语气。
如何：怎么样。
齐、鲁：古代齐鲁两国以泰山为界，齐国在泰山北，鲁国在泰山南。原是春秋战国时代的两个国名，在今山东境内，后用齐鲁代指山东地区。
青未了：指郁郁苍苍的山色无边无际，浩茫浑涵，难以尽言。青，指苍翠、翠绿的美好山色；未了，不尽，不断。
造化：大自然。
钟：聚集。
神秀：天地之灵气，神奇秀美。
阴阳：阴指山的北面，阳指山的南面。这里指泰山的南北。
割：分。夸张的说法。
昏晓：黄昏和早晨。
「阴阳割昏晓」句：说极言泰山之高，山南山北因之判若清晓与黄昏，明暗迥然不同。
荡胸：心胸摇荡。
曾：同「层」，重叠。
决眦（zì）：眼角（几乎）要裂开。这是由于极力张大眼睛远望归鸟入山所致。决，裂开；眦，眼角。
入：收入眼底，即看到。
会当：终当，定要。
凌：登上。凌绝顶，即登上最高峰。
小：形容词的意动用法，意思为「以……为小，认为……小」。', '巍峨的泰山，到底如何雄伟？走出齐鲁，依然可见那青青的峰顶。
神奇自然汇聚了千种美景，山南山北分隔出清晨和黄昏。
层层白云，荡涤胸中沟壑；翩翩归鸟，飞入赏景眼圈。
定要登上泰山顶峰，俯瞰群山，豪情满怀。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a72e6a6b501f95c13a", "shortContent": "杜甫《望岳》诗，共有三首，分咏东岳（泰山）、南岳（衡山）、西岳（华山）。这一首是望东岳泰山。开元二十四年（736），二十四岁的诗人开始过一种“裘马清狂”的漫游生活。此诗即写于北游齐、赵（今河南、河北、山东等地）时，是现存杜诗中年代最早的一首，字里行间洋溢着青年杜甫那种蓬蓬勃勃的朝气。\n全诗没有一个“望”字，但句句写向岳而望。距离是自远而近，时间是从朝至暮，并由望岳悬想将来的登岳。\n首句“岱宗夫如何...", "authors": ["萧涤非"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d11b", "shortContent": "杜甫《望岳》诗，共有三首，分咏东岳（泰山）、南岳（衡山）、西岳（华山）。这一首是望东岳泰山。开元二十四年（736），二十四岁的诗人开始过一种“裘马清狂”的漫游生活。此诗即写于北游齐、赵（今河南、河北、山东等地）时，是现存杜诗中年代最早的一首，字里行间洋溢着青年杜甫那种蓬蓬勃勃的朝气。\n\n全诗没有一个“望”字，但句句写向岳而望。距离是自远而近，时间是从朝至暮，并由望岳悬想将来的登岳。\n\n首句“岱宗夫...", "authors": ["萧涤非"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d93", "shortContent": "如果有谁要用“沉郁顿挫”来概括杜甫所有诗作的特点，那么我就要说，你错了！其实，每个人都曾经年轻过，都有过青年人的朝气与活力，而不是一开始就老成似老杜。老杜呢，他也曾经和李白一样，二十几岁时曾度过一段“裘马轻狂”的漫游生活，在那样潇洒的日子里，我们的诗圣杜甫，也向我们展示了一种无边的青春活力与朝气。这不，谁人不知这首《望岳》，谁人不能脱口而出“会当凌绝顶，一览众山小”呢！\n\n如果您没有去过五岳之首“...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127066c305cf0801816fbc", "shortContent": "如果有谁要用“沉郁顿挫”来概括杜甫所有诗作的特点，那么我就要说，你错了！其实，每个人都曾经年轻过，都有过青年人的朝气与活力，而不是一开始就老成似老杜。老杜呢，他也曾经和李白一样，二十几岁时曾度过一段“裘马轻狂”的漫游生活，在那样潇洒的日子里，我们的诗圣杜甫，也向我们展示了一种无边的青春活力与朝气。这不，谁人不知这首《望岳》，谁人不能脱口而出“会当凌绝顶，一览众山小”呢！\n\n如果您没有去过五岳之首“...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270d4c26cbf3417f0950c", "shortContent": "如果有谁要用“沉郁顿挫”来概括杜甫所有诗作的特点，那么我就要说，你错了！其实，每个人都曾经年轻过，都有过青年人的朝气与活力，而不是一开始就老成似老杜。老杜呢，他也曾经和李白一样，二十几岁时曾度过一段“裘马轻狂”的漫游生活，在那样潇洒的日子里，我们的诗圣杜甫，也向我们展示了一种无边的青春活力与朝气。这不，谁人不知这首《望岳》，谁人不能脱口而出“会当凌绝顶，一览众山小”呢！\n\n如果您没有去过五岳之首“...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6463965130675327e184dcc1", "shortContent": "杜甫《望岳》诗，共有三首，分咏东岳（泰山）、南岳（衡山）、西岳（华山）。这一首是望东岳泰山。开元二十四年（736），二十四岁的诗人开始过一种“裘马清狂”的漫游生活。此诗即写于北游齐、赵（今河南、河北、山东等地）时，是现存杜诗中年代最早的一首，字里行间洋溢着青年杜甫那种蓬蓬勃勃的朝气。\n\n全诗没有一个“望”字，但句句写向岳而望。距离是自远而近，时间是从朝至暮，并由望岳悬想将来的登岳。\n\n首句“岱宗夫...", "authors": ["萧涤非"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f6285e6bb82b8cfbb7a3", "shortContent": "杜甫《望岳》诗，共有三首，分咏东岳（泰山）、南岳（衡山）、西岳（华山）。这一首是望东岳泰山。开元二十四年(736)，二十四岁的诗人开始过一种“裘马清狂”的漫游生活。此诗即写于北游齐、赵（今河南、河北、山东等地）时，是现存杜诗中年代最早的一首，字里行间洋溢着青年杜甫那种蓬蓬勃勃的朝气。“会当凌绝顶，一览众山小”，这最后两句，写由望岳而产生的登岳的意愿。“会当”是唐人口语，意即“一定要”。如王勃《春思...", "authors": ["萧涤非"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "64733e60a5f1e74f958c905c", "shortContent": "杜甫《望岳》诗，共有三首，分咏东岳（泰山）、南岳（衡山）、西岳（华山）。这一首是望东岳泰山。开元二十四年（736），二十四岁的诗人开始过一种“裘马清狂”的漫游生活。此诗即写于北游齐、赵（今河南、河北、山东等地）时，是现存杜诗中年代最早的一首，字里行间洋溢着青年杜甫那种蓬蓬勃勃的朝气。\n\n诗中没有一个“望”字，但句句写向岳而望。距离是自远而近，时间是从朝至暮，并由望岳悬想将来的登岳。\n\n“岱宗夫如何...", "authors": ["萧涤非"], "pressName": "上海辞书出版社"}]', '宋·范温《潜溪诗眼》：《望岳》诗云「齐鲁青未了」，《洞庭》诗云「吴楚东南坼，乾坤日夜浮」。语既高妙有力，而言东岳与洞庭之大，无过于此。后来文士极力道之，终有限量，益知其不可及。《望岳》第二句如此，故先云「岱宗夫如何」……无第二句，而云「岱宗夫如何」，虽曰乱道可也。
明·高棅《唐诗品汇》：起句之超然者也。
明·董其昌《画禅室随笔》：顷见岱宗诗赋六本，读之既尽，为区检讨用儒言曰：「总不如一句。」检讨请之。曰：「齐鲁青未了。」
明·莫如忠《登东郡望岳楼》：「齐鲁到今青未了，题诗谁继杜陵人？」
明·鍾惺《唐诗归》：三字得「望」之神（首句）。险奥（「荡胸」二句）。定用望岳语景作结，便弱便浅（末句）。此诗妙在起，后六句不称。如此结，自难乎其称，又今设身为作者想之。
明·周珽《唐诗选脉会通评林》：「齐鲁青未了」五字雄盖一世。「青未了」语好，「夫如何」跌荡，非凑句也。「荡胸」语，不必可解，登高意豁，自见其趣；对下句苦。郭浚曰：他人游泰山记，千言不了，被老杜数语说尽。只言片语，说得泰岳色气凛然，为万古开天名作。句字皆能泣鬼磷而裂鬼胆。
明·王嗣奭《杜臆》：「齐鲁青未了」、「荡胸生云」、「决眥入鸟」，皆望见岱岳之高大，揣摹想象而得之，故首用「夫如何」，正想象光景，三字直管到「入归鸟」，此诗中大开合也。……集中《望岳》诗三见，独此辞愈少，力愈大，直与泰岱争衡。诗垂近千年，未有赏识者。余初亦嫌「荡胸」一联为累句，今始知其奇。钟伯敬乃谓：「此诗妙在起，后六句不称。」犹然俗人之见也，又谓：「定用望岳语作结，便弱便浅。」请问将用何语作结耶？
清·金圣叹《杜诗解》：「岳」字已难着语，「望」字何处下笔？试想先生当日有题无诗时，何等惨淡经营！一字未落，却已使读者胸中、眼中隐隐隆隆具有「岳」字、「望」字。盖此题非此三字（「夫如何」）亦起不得；而此三字非此题，亦用不着也。……此起二语，皆神助之句（首句）。凡历二国，尚不尽其青，写「岳」奇绝，写「望」又奇绝。五字何曾一字是「岳」？何曾一字是「望」？而五字天造地设，恰是「望岳」二字（「齐鲁」句）。二句写「岳」。「岳」是造化间气所特钟，先生望「岳」，直算到未有岳以前，想见其胸中咄咄！「割昏晓」者，犹《史记》云：「日月所相隐辟为光明」也。一句写其从地发来，一句写其到天始尽，只十字写「岳」遂尽（「造化」二句）。翻「望」字为「凌」字已奇，乃至翻「岳」字为「众山」字，益奇也。如此作结，真有力如虎（末二句）。
清·黄周星《唐诗快》：只此五字，可以小天下矣，何小儒存乎见少也（首二句）。「割」字奇（「阴阳」句）。「入」字又奇，然「割」字人尚能用，「入」字人不能用（「决眦」句）。
清·张培仁《古欢堂集杂著》：余问聪山；老杜《望岳》诗「夫如何」、「青未了」六字，毕竟作何解？曰：子美一生，唯中年诸诗静练有神，晚则颓放。此乃少时有意造奇，非其至者。
清·仇兆鳌《杜诗详注》：诗用四层写意：首联远望之色，次联近望之势，三联细望之景，末联极望之情。上六实叙，下二虚摹。少陵以前，题咏泰山者，有谢灵运、李白之诗，谢诗八句，上半古秀，而下却平浅；李诗有六章，中有佳句，而意多重复。此诗遒劲峭刻，可以俯视二家矣。《龙门》及此章，格似五律，但句中平仄未谐，盖古诗之对偶者。而其气骨峥嵘，体势雄浑，能直驾齐、梁之上。卢世㴶曰：公初登东岳，似稍紧窄，然而旷甚。后望南岳，似稍错杂，然而肃甚。固不必登峰造极，而两岳真形已落其眼底。
《诗学纂闻》：起轻佻失体。
清·沈德潜《唐诗别裁》：「齐鲁青未了」五字，已尽太山。
清·汪师韩《读杜心解》：公望岳诗凡三首，此望东岳也。越境连绵，苍峰不断，写岳势只「青未了」三字，胜人千百矣。「钟神秀」，在岳势前推出；「割昏晓」，就岳势上显出。「荡胸」、「决眦」，明逗「望」字。未联则以将来之凌眺，剔现在之遥观，是透过一层收也。……杜子心胸气魄，于斯可观。取为压卷，屹然作镇。
清·杨伦《杜诗镜铨》：「荡胸」句不必可解，登高意豁，自见其趣。「割」字奇险（「阴阳」句）。
清爱新觉罗·弘历《唐宋诗醇》：四十字气势，欲与岱岳争雄。
清·延君寿《老生常谈》：予尝谓：读《北征》诗与荆公《上仁宗书》，唐、宋有大文章，后人敛衽低首，推让不遑，不敢复言文字矣。此言出，人必谓震其长篇大作耳。不知「齐鲁青未了」才五字，《读孟尝君传》才数行，后人越发不能。古人手段，纵则长河落天，收则灵珠在握，神龙九霄，不得以大小论。
清·施补华《岘佣说诗》：《望岳》一题，若入他人手，不知作多少语，少陵只以四韵了之，弥见简劲。「齐鲁青未了」五字，囊括数千里，可谓雄阔。
近代·高步瀛《唐宋诗举要》：此十字气象旁魄，与岱宗相称（「造化」二句）。奇情写望岳之神（「荡胸」二句）。抱负不凡。邵子湘曰：语语奇警（末二句）。', 'center', 1362266918, '57b8fda3d342d3005ac712d7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10123, '一斛珠 · 晓妆初过', NULL, 202, 87, 2, 2, '李煜', NULL, 10017, '57b8af7c5bbb50005b770fdd', '五代十国', 'ci', '词', 'http://baike.baidu.com/item/一斛珠·晓妆初过', '', '晓妆初过，沉檀轻注些儿个。向人微露丁香颗，一曲清歌，暂引樱桃破。
罗袖裛残殷色可，杯深旋被香醪涴。绣床斜凭娇无那，烂嚼红茸，笑向檀郎唾。', '此词是一曲描写男女欢情的艳歌，从整体风格看，应是李煜前期的作品。全词写女主人公从化妆出场到终场赴宴的全过程，中间充满了戏剧情趣的描写，塑造了一个富有个性特征的人物形象，具有强烈的艺术感染力。', '一斛珠：词牌名。又名《一斛夜明珠》、《怨春风》、《醉落魄》、《章台月》、《梅梢雪》等。清·毛稚黃《填词名解》：「唐玄宗在花萼楼，会夷使至，命封珍珠一斛，密赐梅妃。妃不受，赋诗云：『柳叶双眉久不描，残妆和泪污红绡。长门尽日无梳洗，何必珍珠慰寂寥？」付使者曰：『为我进御。』上览诗不乐，令乐府以新声度之，号「一斛珠」。曲名始此也。」据考，李煜所作此首《一斛珠》为此调首见。
晓：早晨。《词谱》《古今词统》《花草粹编》《历代诗馀》《全唐诗》《诗馀图谱》等文本均作「晚」。沈际飞选评《草堂诗馀》（古香岑四集本）中注：「一作晚，误。」
晓妆初过：指早晨起床刚刚梳洗打扮完毕。
沉檀：即「沉檀」。一种妇女妆饰用的颜料，唐、宋时妇女闺妆多用它，或用于眉端之间，或用于口唇之上。《花间集》阎选《虞美人》词中有「臂留檀印齿痕香」之句，毛熙震《后庭花》词中亦有「歌声慢发开檀点」之句，都是描绘以檀注唇的情形。沈，《醉翁琴趣》外篇作「浓」，带有润泽的深绛色；檀，浅绛色。
轻注：轻轻点画。注，这里是点的意思。
些儿个：当时方言，意谓少许，一点点。
向：《醉翁琴趣》外篇中作「见」。
人：吴本二主词、侯本二主词中缺字。
丁香颗：这里指女人口内之牙。丁，《花间集补》中误作「了」；丁香，常绿乔木，又名「鸡舌香」、「丁子香」，丁香子如钉，长三、四分，可以含于口中。古时用以代指女人的舌头；颗，指牙。
「向人微露丁香颗」句：描绘歌女开口歌唱，舌齿微露，形容得意的神情。
清歌：清脆响亮的歌声。也指不用乐器伴奏的独唱。南朝宋·谢康乐《拟魂太子「邺中集」诗·魏太子》：「急絃动飞听，清歌拂梁尘。」
暂：《醉翁琴趣》外篇中作「渐」。
引：使得。
樱桃，落叶乔木，果实多为红色，味道甜美或略带酸味。古人常用樱桃比喻女子口唇。白乐天诗有「樱桃樊素口，杨柳小蛮腰。」唐·李义山《赠歌妓》诗之一：「红绽樱桃含白雪，断肠声里唱《阳关》。」唐·韩致尧《袅娜》诗云：「着词但见樱桃破，飞盏遥闻豆蔻香。」
破：张开。
樱桃破：指女人张开娇小红润的口。
「暂引樱桃破」句：描写歌女们张开红润小口歌唱的情形。
罗袖，质地较薄的丝衣的袖。
裛（yì）残：指香气消失殆尽。裛，熏蒸，这里指香气。
殷（yān）：深红色。
可：意近「可可」，这里是模模糊糊、隐隐约约的意思。元微之《春》诗：「九霄浑可可，万姓尚忡忡。」
「罗袖裛残殷色可」句：谓说歌女的丝制的衣袖上的香气已经消失将尽，深红的颜色也只隐约可见了。
杯深：指酒杯斟酒斟得很满，引申意谓酒喝得过量。
旋：随即，很快地。
香醪（láo）：美酒，醇酒。本是一种汁滓混合的醇酒，味甜。
涴（wò）：沾污，污染。《醉翁琴趣》外篇中作「污」。
绣床：铺着织绣的床，这里指歌女的床。
凭：倚靠，靠着。
娇无那（nuò）：这里是形容娇娜无比，不能自主的样子。娇，《醉翁琴趣》外篇作「情」；无那，犹言无限，非常之意。
烂嚼：细嚼。嚼，用牙齿磨碎食物。
红茸：即红绒，刺绣用的红色丝线。吕本二主词、吴讷《唐宋名贤百家词》本《尊前集》中均作「红绒」。
檀郎：指西晋潘岳，小名檀奴，后世文人因以「檀郎」为妇女对夫婿或所爱的男子的美称。
唾（tuò）：将口中含物吐出来。萧本二主词中作「吐」，误，「吐」与「唾」韵不同。', '晓妆只粗粗理过，唇边可还得点一抹沉檀色的红膏。含笑未唱，先露一尖花蕾般的舌尖，于是樱桃小口微张，流出了婉转如莺的清歌。
到了场下的酒会，就又娇爽多了。小盅微啜似乎还不够过瘾，换过深口大杯拚醉，哪在意污湿罗衣？最传神的是，笑嚼着红嫩的草花，向心上人唾个不停。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74920f8fda556504d916", "shortContent": "这首词，写一个歌女从化妆出场到终场赴宴的全过程，中间充满了戏剧情趣的描写。\n词一开头，便把描写对象的一系列活动，像一幅一幅的连环画，一个一个的平视镜头展现在我们的面前，突出了对象的特点，强调了主人公的妩媚神态，使作品中所描写的生活情景，都成了主人公有意识的活动，以唤起人们生活经验中一些美好的回忆，给人以新鲜、真切、活泼、自然的审美情趣。“晓妆初过”两句，写那美丽活泼的歌女，刚刚梳洗完毕，在唇上轻轻...", "authors": ["羊春秋"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892d9820695e6503fd6f", "shortContent": "这首词，写一个歌女从化妆出场到终场赴宴的全过程，中间充满了戏剧情趣的描写。\n\n词一开头，便把描写对象的一系列活动，像一幅一幅的连环画，一个一个的平视镜头展现在我们的面前，突出了对象的特点，强调了主人公的妩媚神态，使作品中所描写的生活情景，都成了主人公有意识的活动，以唤起人们生活经验中一些美好的回忆，给人以新鲜、真切、活泼、自然的审美情趣。“晓妆初过”两句，写那美丽活泼的歌女，刚刚梳洗完毕，在唇上轻...", "authors": ["羊春秋"], "pressName": "上海辞书出版社"}, {"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126df6c305cf0801816c25", "shortContent": "《尊前集》注“商调”。《词的》、《古今诗余醉》、《古今词统》题作“咏佳人口”。《历代诗余》题作“咏美人口”。《清绮轩词选》卷六题作“美人口”。\n\n一斛珠，又名“醉落魄”、“怨春风”、“章台月”等。双调五十七字，仄韵。据旧题曹邺小说《梅妃传》载：谓唐玄宗既宠杨贵妃，遂疏梅妃。会夷使至，献珍珠。上封珍珠一斛密赐江妃。妃不受，以诗谢，曰：柳叶双眉久不描，残妆和泪污红绡。长门自是无梳洗，何必珍珠慰寂寥。玄...", "authors": [], "pressName": "崇文书局"}]', '李笠翁《窥词管见》：李后主《一斛珠》之结句云：「绣床斜倚娇无那，烂嚼红绒，笑向檀郎唾。」此词亦为人所竞赏。予曰：此倡楼妇倚门腔，梨园献丑态也。嚼红绒以唾郎，与倚市门而大嚼，唾枣核瓜子，以调路人者，其间不能以寸。优人演剧，每作此状，以发笑端，是深知其丑，而故意为之者也。不料填词之家，竟以此事谤美人，而后之读词者又止重情趣，不问妍媸，复相传为韵事，谬乎不谬乎？
沈震峰《草堂诗馀别集·卷二》：描画精细，似一篇小题绝好文字。……后主、炀帝辈，除却天子不为，使之作文士荡子，前无古，后无今。
贺黄公《皱水轩词筌》：词家多翻诗意入词，虽名家不免。吾常爱李后主《一斛珠》末句云：「绣床斜凭娇无那。烂嚼红茸，笑向檀郎唾。」杨孟载《春绣》绝句云：「闲情正在停针处，笑嚼红绒唾碧窗。」此却翻词入诗，弥子暇竟效颦于南子。
陈亦峰《闲情集·卷一》：风流秀曼，失人君之度矣。', 'indent', 1362515517, '57b8de2d0a2b58005c918a26', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10096, '饮中八仙歌', NULL, 514, 1416, 5, 2, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155541.htm', '', '知章骑马似乘船，眼花落井水底眠。
汝阳三斗始朝天，道逢曲车口流涎，
恨不移封向酒泉。
左相日兴费万钱，饮如长鲸吸百川，
衔杯乐圣称避贤。
宗之潇洒美少年，举觞白眼望青天，
皎如玉树临风前。
苏晋长斋绣佛前，醉中往往爱逃禅。
李白斗酒诗百篇，长安市上酒家眠，
天子呼来不上船，自称臣是酒中仙。
张旭三杯草圣传，脱帽露顶王公前，
挥毫落纸如云烟。
焦遂五斗方卓然，高谈雄辩惊四筵。', '此诗将当时号称「酒中八仙人」的李白、贺知章、李适之、李琎、崔宗之、苏晋、张旭、焦遂八人从「饮酒」这个角度联系在一起，用追叙的方式，洗炼的语言，人物速写的笔法，构成一幅栩栩如生的群像图。这首诗在体裁上是一个创格。以柏梁体的形式，句句押韵，一韵到底；前不用起，后不用收；并列地分写八人，句数多少不齐，但首、尾、中腰，各用两句，前后或三或四，变化中仍有条理。八人中，贺知章资格最老，所以放在第一位。其他按官爵，从王公宰相一直说到布衣。写八人醉态各有特点，纯用漫画素描的手法，写他们的平生醉趣，充分表现了他们嗜酒如命、放浪不羁的性格，生动地再现了盛唐时代文人士大夫乐观、放达的精神风貌。', '知章：即贺知章，越州永兴（今浙江萧山）人，官至秘书监。性旷放纵诞，自号“四明狂客”，又称“秘书外监”。他在长安一见李白，便称他为“谪仙人”，解所佩金龟换酒痛饮。这两句写贺知章醉后骑马，摇摇晃晃，像乘船一样。醉眼昏花坠入井中，竟在井底睡着了。
汝阳：汝阳王李琎，唐玄宗的侄子。
朝天：朝见天子。此谓李痛饮后才入朝。
曲车：“曲”是“麴”的简体字，“曲车”意即酒车。
移封：改换封地。
酒泉：郡名，在今甘肃酒泉县。传说郡城下有泉，味如酒。故名酒泉。
左相：指左丞相李适之，天宝元年（公元742年）八月为左丞相，天宝五年（公元746年）四月，为李林甫排挤罢相。
长鲸：鲸鱼。古人以为鲸鱼能吸百川之水，故用来形容李适之的酒量之大。
衔杯：贪酒。
圣：酒的代称。《三国志·魏志·徐邈传》：尚书郎徐邈酒醉，校事赵达来问事，邈言“中圣人”。达复告曹操，操怒，鲜于辅解释说：“平日醉客，谓酒清者为圣人，酒浊者为贤人。”李适之罢相后，尝作诗云：“避贤初罢相，乐圣且衔杯。为问门前客，今朝几个来？”此化用李之诗句，说他虽罢相，仍豪饮如常。
避：一作“世”。
宗之：崔宗之，吏部尚书崔日用之子，袭父封为齐国公，官至侍御史，也是李白的朋友。
觞：大酒杯。
白眼：晋阮籍能作青白眼，青眼看朋友，白眼视俗人。
玉树临风：崔宗之风姿秀美，故以玉树为喻。
苏晋：开元进士，曾为户部和吏部侍郎。
长斋：长期斋戒。
绣佛：画的佛像。
逃禅：这里指不守佛门戒律。佛教戒饮酒。苏晋长斋信佛，却嗜酒，故曰“逃禅”。
李白：以豪饮闻名，而且文思敏捷，常以酒助诗兴。《新唐书·李白传》载：李白应诏至长安，唐玄宗在金銮殿召见他，并赐食，亲为调羹，诏为供奉翰林。有一次，玄宗在沉香亭召他写配乐的诗，而他却在长安酒肆喝得大醉。范传正《李白新墓碑》载：玄宗泛舟白莲地，召李白来写文章，而这时李白已在翰林院喝醉了，玄宗就命高力士扶他上船来见。
张旭：吴人，唐代著名书法家，善草书，时人称为“草圣”。脱帽露顶：写张旭狂放不羁的醉态。据说张旭每当大醉，常呼叫奔走，索笔挥洒，甚至以头濡墨而书。醒后自视手迹，以为神异，不可复得。世称“张颠”。
焦遂：布衣之士，平民，以嗜酒闻名，事迹不详。
卓然：神采焕发的样子。袁郊在《甘泽谣》中称焦遂为布衣。', '贺知章酒后骑马，晃晃悠悠，如在乘船。他醉眼昏花坠入井中，竟在井底睡着了。
汝阳王李琎饮酒三斗以后才去觐见天子。路上碰到装载酒曲的车，酒味引得口水直流，为自己没能封在水味如酒的酒泉郡而遗憾。
左相李适为每日之兴起不惜花费万钱，饮酒如长鲸吞吸百川之水。自称举杯豪饮是为了脱略政事，以便让贤。
崔宗之是一个潇洒的美少年，举杯饮酒时，常常傲视青天，俊美之姿有如玉树临风。
苏晋虽在佛前斋戒吃素，饮起酒来常把佛门戒律忘得干干净净。
李白饮酒一斗，立可赋诗百篇，他去长安街酒肆饮酒，常常醉眠于酒家。天子在湖池游宴，召他为诗作序，他因酒醉不肯上船，自称是酒中之仙。
张旭饮酒三杯，即挥毫作书，时人称为草圣。他常不拘小节，在王公贵戚面前脱帽露顶，挥笔疾书，若得神助，其书如云烟之泻于纸张。
焦遂五杯酒下肚，才得精神振奋。在酒席上高谈阔论，常常语惊四座。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a8dbb8b379ee0959c7", "shortContent": "《饮中八仙歌》是一首别具一格，富有特色的“肖像诗”。八个酒仙是同时代的人，又都在长安生活过，在嗜酒、豪放、旷达这些方面彼此相似。诗人以洗练的语言，人物速写的笔法，将他们写进一首诗里，构成一幅栩栩如生的群像图。\n八仙中首先出现的是贺知章。他是其中资格最老、年事最高的一个。在长安，他曾“解金龟换酒为乐”（李白《对酒忆贺监序》）。诗中说他喝醉酒后，骑马的姿态就像乘船那样摇来晃去，醉眼矇眬，眼花缭乱，跌进...", "authors": ["何国治"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270617f0b9738b369b1f9", "shortContent": "杜甫此诗所呈现的意境，潇洒得令人有出尘之想。我们仿佛跟随着诗人的脚步，步入了瑶池仙境。在那里，我们和诗人一道，静看酒中八仙的潇洒所为，静听他们的卓然言论。时间仿佛在那一刻定格，摄下这永恒的画面；又仿佛在缓慢流走，似电影镜头般地记下饮中八仙的点滴所为。他们的神采在他们忘我的境界中展示着、张扬着，更感染了所有驻足观看、倾耳聆听的他者！\n\n首先出场的是年事最高的贺知章。带着八九分醉意，这位伟大的长者早已...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270d3c26cbf3417f09501", "shortContent": "杜甫此诗所呈现的意境，潇洒得令人有出尘之想。我们仿佛跟随着诗人的脚步，步入了瑶池仙境。在那里，我们和诗人一道，静看酒中八仙的潇洒所为，静听他们的卓然言论。时间仿佛在那一刻定格，摄下这永恒的画面；又仿佛在缓慢流走，似电影镜头般地记下饮中八仙的点滴所为。他们的神采在他们忘我的境界中展示着、张扬着，更感染了所有驻足观看、倾耳聆听的他者！\n\n首先出场的是年事最高的贺知章。带着八九分醉意，这位伟大的长者早已...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6464d6f945e4710056c5481b", "shortContent": "《饮中八仙歌》是一首别具一格，富有特色的“肖像诗”。八个酒仙是同时代的人，又都在长安生活过，在嗜酒、豪放、旷达这些方面彼此相似。诗人以洗练的语言，人物速写的笔法，将他们写进一首诗里，构成一幅栩栩如生的群像图。 \n\n八仙中首先出现的是贺知章。他是其中资格最老、年事最高的一个。在长安，他曾“解金龟换酒为乐”（李白《对酒忆贺监序》）。诗中说他喝醉酒后，骑马的姿态就像乘船那样摇来晃去，醉眼矇眬，眼花缭乱，...", "authors": ["何国治"], "pressName": "上海辞书出版社"}]', '《唐诗品汇》：蔡绦《西清诗话》云：此歌重叠用韵，古无其体。尝质之叔父元度云：此歌分八篇，人人各异，虽重押韵，无害。亦《三百篇》分章之意也。
《唐诗广选》：刘会孟曰：（诗分）八篇，近之。吾意复如题画，人自一二语，集之成歌。又曰：不伦不理，各极其醉题，古无此体，无此妙。
《四溟诗话》：少陵《哀江头》、《哀王孙》作法最古，然琢削靡砻，力尽此矣。《饮中八仙》，格力趄拔，庶足当之。
《唐诗解》：其他若崔之貌、苏之禅、李之诗、张旭之草圣、焦遂之问皆任其性直，逞其才俊，托于酒以自见者。藉令八人而当圣世，未必不为元恺之伦，今皆流落不偶。知章则以辅太子而见疏，适之则以忤权相而被斥，青莲则以触力士而放弃，其五人亦皆厌世之浊而托于酒，故子美咏之，有废中权之义云。
《唐宋诗醇》：李因笃曰：无首无尾，章法突兀妙是，叙述不涉议论，而八人身分自见，风雅中司马太史也。
《唐诗别裁》：前不用起，后不用收，中间参差历落，似八章，乃似一章，格法古未曾有。每人各赠几语，故有重韵而不妨碍。
《读杜心解》：此格亦从季札观乐、羊欣论书，及诗之《柏梁台》体化出。其写各人醉趣，语亦不浪下。
《石洲诗话·渔洋评杜摘记》：「无首无尾，章法突兀，然非杜之至者。」按：此亦西樵评也。……皆谬之甚者。
《杜诗镜铨》：四句独详。八人以此人为主也（「李白一斗」句下）。独以一不醉客作结（「焦遂五斗」句下）。入李子德云：似颂似赞，只一、二语可得其人生平。', 'center', 1423167308, '57b8e3a7c4c97100558e7dc6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10097, '茅屋为秋风所破歌', NULL, 542, 1416, 1, 13, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155844.htm', '', '八月秋高风怒号，卷我屋上三重茅。茅飞渡江洒江郊，高者挂罥长林梢，下者飘转沉塘坳。
南村群童欺我老无力，忍能对面为盗贼。公然抱茅入竹去，唇焦口燥呼不得，归来倚杖自叹息。
俄顷风定云墨色，秋天漠漠向昏黑。布衾多年冷似铁，娇儿恶卧踏里裂。床头屋漏无干处，雨脚如麻未断绝。自经丧乱少睡眠，长夜沾湿何由彻！
安得广厦千万间，大庇天下寒士俱欢颜！风雨不动安如山。呜呼！何时眼前突兀见此屋，吾庐独破受冻死亦足！', '此诗是唐代伟大诗人杜甫旅居四川成都草堂期间创作的一首歌行体古诗。此诗叙述作者的茅屋被秋风所破以致全家遭雨淋的痛苦经历，抒发了自己内心的感慨，体现了诗人忧国忧民的崇高思想境界，是杜诗中的典范之作。全篇可分为四段，第一段写面对狂风破屋的焦虑；第二段写面对群童抱茅的无奈；第三段写遭受夜雨的痛苦；第四段写期盼广厦，将苦难加以升华。前三段是写实式的叙事，诉述自家之苦，情绪含蓄压抑；后一段是理想的升华，直抒忧民之情，情绪激越轩昂。前三段的层层铺叙，为后一段的抒情奠定了坚实的基础，如此抑扬曲折的情绪变换，完美地体现了杜诗”沉郁顿挫“的风格。', '秋高：秋深。
怒号（háo）：大声吼叫。
三重（chóng）茅：几层茅草。三，泛指多。
挂罥（juàn）：挂着，挂住。罥，挂。
长（cháng）：高。
塘坳（ào）：低洼积水的地方（即池塘）。塘，一作“堂”。坳，水边低地。
忍能对面为盗贼：竟忍心这样当面做“贼”。忍能，忍心如此。对面，当面。为，做。
入竹去：进入竹林。
呼不得：喝止不住。
俄顷（qǐng）：不久，一会儿，顷刻之间。
秋天漠漠向昏黑（古音念hè）：指秋季的天空阴沉迷蒙，渐渐黑了下来。
布衾（qīn）：布质的被子。衾，被子。
娇儿恶卧踏里裂：孩子睡相不好，把被里都蹬坏了。恶卧，睡相不好。裂，使动用法，使……裂。
床头屋漏无干处：意思是，整个房子都没有干的地方了。屋漏，根据《辞源》释义，指房子西北角，古人在此开天窗，阳光便从此处照射进来。「床头屋漏」，泛指整个屋子。
雨脚如麻：形容雨点不间断，像下垂的麻线一样密集。雨脚，雨点。
丧（sāng）乱：战乱，指安史之乱。
沾湿：潮湿不干。何由彻：如何才能挨到天亮。彻，彻晓。
安得：如何能得到。
广厦（shà）：宽敞的大屋。
大庇（bì）：全部遮盖、掩护起来。庇，遮盖，掩护。
寒士：“士”原指士人，即文化人，但此处是泛指贫寒的士人们。
欢颜：喜笑颜开。
呜呼：书面感叹词，表示叹息，相当于“唉”。
突兀（wù）：高耸的样子，这里用来形容广厦。见（xiàn）：通“现”，出现。
庐：茅屋。
亦：一作“意”。
足：值得。', '八月里秋深，狂风怒号，狂风卷走了我屋顶上好几层茅草。茅草乱飞，渡过浣花溪，散落在对岸江边。飞得高的茅草缠绕在高高的树梢上，飞得低的飘飘洒洒沉落到池塘和洼地里。
南村的一群儿童欺负我年老没力气，竟忍心这样当面做「贼」抢东西，毫无顾忌地抱着茅草跑进竹林去了。我嘴唇干燥也喝止不住，回来后拄着拐杖，独自叹息。
一会儿风停了，天空中乌云像墨一样黑，深秋天空阴沉迷蒙渐渐黑下来了。布被盖了多年，又冷又硬，像铁板似的。孩子睡觉姿势不好，把被子蹬破了。一下雨屋顶漏水，屋内没有一点儿干燥的地方，房顶的雨水像麻线一样不停地往下漏。自从安史之乱之后，我睡眠的时间很少，长夜漫漫，屋漏床湿，怎能挨到天亮。
如何能得到千万间宽敞高大的房子，普遍地庇覆天下间贫寒的读书人，让他们开颜欢笑，房子在风雨中也不为所动，安稳得像是山一样？唉！什么时候眼前出现这样高耸的房屋，到那时即使我的茅屋被秋风所吹破，我自己受冻而死也心甘情愿！', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ad34a8757d5a0e1c90", "shortContent": "乾元三年（760）的春天，杜甫求亲告友，在成都浣花溪边盖起了一座茅屋，总算有了一个栖身之所。不料到了八月，大风破屋，大雨又接踵而至。诗人长夜难眠，感慨万千，写下了这篇脍炙人口的诗篇。诗写的是自己的数间茅屋，表现的却是忧国忧民的情感。\n这首诗可分为四节。第一节五句，句句押韵，“号”、“茅”、“郊”、“梢”、“坳”五个开口呼的平声韵脚传来阵阵风声。“八月秋高风怒号，卷我屋上三重茅。”起势迅猛。“风怒号...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a7c", "shortContent": "乾元三年（760）的春天，杜甫求亲告友，在成都浣花溪边盖起了一座茅屋，总算有了一个栖身之所。不料到了八月，大风破屋，大雨又接踵而至。诗人长夜难眠，感慨万千，写下了这篇脍炙人口的诗篇。诗写的是自己的数间茅屋，表现的却是忧国忧民的情感。\n\n这首诗可分为四节。第一节五句，句句押韵，“号”“茅”“郊”“梢”“坳”五个开口呼的平声韵脚传来阵阵风声。“八月秋高风怒号，卷我屋上三重茅。”起势迅猛。“风怒号”三字...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127066c305cf0801816fad", "shortContent": "读惯了老杜的诗作，则没有人会觉得这是一首矫情之作。\n\n这是一首用血泪写就的诗篇，字字催人泪下，读完痛彻肺腑。老杜一生，坎坷多难，居无定所，曾衣不得暖，食不能饱，遍尝人世艰辛。乱世磨砺了他，也造就了他，是为今日之诗圣“杜甫”。\n\n“八月秋高风怒号，卷我屋上三重茅。”诗人苦心盖造了一座茅屋，好不容易告别了天为被、地为床的日子，本想安享几日宁静。不料，八月秋至，狂风怒吼，这座茅屋却经受不了风雨的侵袭，在...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270d4c26cbf3417f09504", "shortContent": "读惯了老杜的诗作，则没有人会觉得这是一首矫情之作。\n\n这是一首用血泪写就的诗篇，字字催人泪下，读完痛彻肺腑。老杜一生，坎坷多难，居无定所，曾衣不得暖，食不能饱，遍尝人世艰辛。乱世磨砺了他，也造就了他，是为今日之诗圣“杜甫”。\n\n“八月秋高风怒号，卷我屋上三重茅。”诗人苦心盖造了一座茅屋，好不容易告别了天为被、地为床的日子，本想安享几日宁静。不料，八月秋至，狂风怒吼，这座茅屋却经受不了风雨的侵袭，在...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6465eaf45fc8182fe9a35c29", "shortContent": "乾元三年（760）的春天，杜甫求亲告友，在成都浣花溪边盖起了一座茅屋，总算有了一个栖身之所。不料到了八月，大风破屋，大雨又接踵而至。诗人长夜难眠，感慨万千，写下了这篇脍炙人口的诗篇。诗写的是自己的数间茅屋，表现的却是忧国忧民的情感。\n\n这首诗可分为四节。第一节五句，句句押韵，“号”、“茅”、“郊”、“梢”、“坳”五个开口呼的平声韵脚传来阵阵风声。“八月秋高风怒号，卷我屋上三重茅。”起势迅猛。“风怒...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f7255e6bb82b8cfbbc75", "shortContent": "乾元三年(760)的春天，杜甫求亲告友，在成都浣花溪边盖起了一座茅屋，总算有了一个栖身之所。不料到了八月，大风破屋，大雨又接踵而至。诗人长夜难眠，感慨万千，写下了这篇脍炙人口的诗篇。诗写的是自己的数间茅屋，表现的却是忧国忧民的情感。\n“安得广厦千万间，大庇天下寒士俱欢颜，风雨不动安如山”，前后用七字句，中间用九字句，句句蝉联而下，而表现阔大境界和愉快情感的词儿如“广厦”“千万间”“大庇”“天下”“...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '《唐诗援》：“‘安得广厦千万间’，发此大愿力，便是措大想头。”申凫盟此语最妙。他人定谓是老杜比稷、契处矣。
《唐诗镜》：子美七言古诗气大力厚，故多局面可观。力厚，澄之使清；气大，束之使峻：斯尽善矣。
《诗源辨体》：《茅屋为秋风所破》，亦为宋人滥觞，皆变体也。
《唐诗归》：钟云：好笑！好哭（“南村群童”二句下）。钟云：“入竹”妙！妙（“公然抱茅”句下）！谭云：“恶卧”，尽小儿睡性（“娇儿恶卧”句下）。
《杜臆》：“广厦万间”，“大庇寒士”，创见故奇，袭之便觉可厌。……“呜呼”一转，固是曲终馀意，亦是通篇大结。
《义门读书记》：元气淋漓，自抒胸臆，非出外袭也。“自叹息”三字，直贯注结处（“归来倚杖”句下）。“风”字带收前半（“风雨不动”句下）。
《唐宋诗醇》：极无聊事，以直写见笔力，入后大波轩然而起，叠笔作收，如龙掉尾，非仅见此老胸怀。若无此意，则诗亦可不作。朱鹤龄曰：白乐天云：“安得布裘长万丈，与君都盖洛阳城。”同此意。
《读杜心解》：起五句完题，笔亦如飘风之来，疾卷了当。“南村”五句，述初破不可耐之状，笔力恣横。单句缩住、黯然。“俄顷”八句，述破后拉杂事，停“风”接“雨”，忽变一境；满眼“黑”、“湿”，笔笔写生。“自经丧乱”，又带入平时苦趣，令此夜彻晓，加倍烦难。末五句，翻出奇情，作矫尾厉角之势。……结仍一笔兜转，又复飘忽如风。《楠树篇》峻整，《茅屋篇》奇奡。
《杜诗镜铨》：邵子湘云：此老襟抱自阔，与蝼蚁辈迥异。诗亦以朴胜，遂开宋派。蒋弱六云：此处若再加叹息，不成文矣。妙竞推开自家，向大处作结，于极潦倒中正有兴会（“安得广厦”句下）。还说穷话，妙（“风雨不动”句下）。
《网师园唐诗笺》：“安得”三句，固屋破而思广厦之庇，转说到独破不妨，想见“胞与”意量。末二句，有意必尽，惟老杜用笔喜如此。
《岘佣说诗》：后段胸襟极阔，然前半太觉村朴，如“南村群童欺我老无力，忍能对面为盗贼”四语，及“骄儿恶卧踏里裂”语，殊不可学。
《十八家诗钞》：张曰：沉雄壮阔，奇繁变化，此老独擅。', 'indent', 1423167365, '57b8ef4edf0eea00633474d2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10098, '戏为六绝句', NULL, 77, 1416, 3, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155888.htm', '', '【其一】
庾信文章老更成，凌云健笔意纵横。
今人嗤点流传赋，不觉前贤畏后生。
【其二】
王杨卢骆当时体，轻薄为文哂未休。
尔曹身与名俱灭，不废江河万古流。
【其三】
纵使卢王操翰墨，劣于汉魏近风骚。
龙文虎脊皆君驭，历块过都见尔曹。
【其四】
才力应难跨数公，凡今谁是出群雄？
或看翡翠兰苕上，未掣鲸鱼碧海中。
【其五】
不薄今人爱古人，清词丽句必为邻。
窃攀屈宋宜方驾，恐与齐梁作后尘。
【其六】
未及前贤更勿疑，递相祖述复先谁？
别裁伪体亲风雅，转益多师是汝师！', '《戏为六绝句》是唐代伟大诗人杜甫创作的组诗作品。这组诗包括六首七言绝句，前三首是对诗人的评价，后三首是论诗的宗旨。这六首诗每首单独成诗，表现了不同的主题。但同时这六首诗的精神前后贯通，互相联系，又是一个不可分割的整体。这组诗实质上是杜甫诗歌创作实践经验的总结，诗论的总纲；它所涉及的是关系到唐诗发展中一系列的重大理论问题。', '庾信：南北朝时期的著名诗人。
文章：泛言文学。
老更成：到了老年就更加成熟了。
凌云健笔：高超雄健的笔力。
意纵横：文思如潮，文笔挥洒自如。
嗤点：讥笑、指责。
前贤：指庾信。
畏后生：即孔子说的“后生可畏”。后生，指“嗤点”庾信的人。但这里是讽刺话，意思是如果庾信还活着，恐怕真会觉得“后生可畏”了。
王杨卢骆：王勃、杨炯、卢照邻、骆宾王。这四人都是初唐时期著名的作家，时人称之为“初唐四杰”。诗风清新、刚健，一扫齐、梁颓靡遗风。
当时体：指四杰诗文的体裁和风格在当时自成一体。
轻薄（bó）：言行轻佻，有玩弄意味。此处指当时守旧文人对“四杰”的攻击态度。
哂（shěn）：讥笑。
尔曹：你们这些人。
不废：不影响。这里用江河万古流比喻包括四杰在内的优秀作家的名字和作品将像长江黄河那样万古流传。
翰墨：笔墨。
风骚：“风”指《诗经》里的《国风》，“骚”指《楚辞》中的《离骚》，后代用来泛称文学。
龙文虎脊：喻瑰丽的文辞。
翡翠：鸟名。
兰苕（tiáo）：兰花和苕花。郭璞《游仙诗》：“翡翠戏兰苕，容色更相鲜”。
掣（chè）：拉，拽。
薄：小看，看不起，轻视。
必为邻：一定要引以为邻居，即不排斥的意思。
窃攀：内心里追攀。
屈宋：屈原和宋玉。
方驾：并车而行。这是诗人对轻薄文士说的：“你们想与屈原、宋玉齐名，应当具有和他们并驾齐驱的精神和才力。”齐、梁文风浮艳，重形式轻内容。这一句，诗人紧承上句说：“如若不然，恐怕你们连齐梁文人还不如呢！”
未及前贤更勿疑：这句是说那些轻薄之辈不及前贤是毋庸置疑的。
递相祖述：互相学习，继承前人的优秀传统。
复先谁：不用分先后。
别裁伪体：区别和裁减、淘汰那些形式内容都不好的诗。
亲风雅：学习《诗经》风、雅的传统。
转益多师：多方面寻找老师。
汝师：你的老师。', '【其一】
庾信的文章到了老年就更加成熟了，其笔力高超雄健，文思如潮，文笔挥洒自如。当今的人讥笑、指责他留下的文章，如果庾信还活着，恐怕真会觉得你们这些后生可畏了。
【其二】
王勃、杨炯、卢照邻和骆宾王四杰在当时的时代条件下，他们的作品已经达到最高的造诣。四杰的文章被认为是轻薄的，被守旧文人讥笑。你们这些守旧文人，在历史的长河中本微不足道，因此只能身名俱灭，而四杰却如江河不废，万古流芳。
【其三】
即便是王杨卢骆四杰操笔作诗，作品比不上汉魏的诗歌而接近《诗经》《楚辞》，但他们还是龙文虎脊的千里马，可以为君王驾车，纵横驰骋，不像你们一跑长途就会跌倒。
【其四】
你们的才力应难以超越上述几位，现在谁成就能超出他们？你们这些人所作的浓丽纤巧的诗文，不过是像翡翠飞翔在兰苕之上一般的货色，缺少大的气度，而没有如掣取鲸鱼于碧海之中那样的雄健才力和阔大气魄，只是一些小灵小巧的玩意。
【其五】
你们学诗要爱古人但也不能鄙薄像庾信、四杰这样的今人，要把他们的清词丽句引为同调。如果你们要在内心里追攀屈原、宋玉，应当具有和他们并驾齐驱的精神和才力，否则就会沿流失源，堕入齐、梁时期那种轻浮侧艳的后尘了。
【其六】
那些轻薄之辈不及前贤是毋庸置疑的，继承前人、互相学习的优秀传统应该是不用分先后的。区别和裁减、淘汰那些形式内容都不好的诗，学习《诗经》风、雅的传统。只有不拘一时一家地多方面学习各家的长处，才算真正找到了你的老师。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92adc6e67846a920eaf1", "shortContent": "清人李重华在《贞一斋诗话》里有段评论杜甫绝句诗的话：\n七绝乃唐人乐章，工者最多。……李白、王昌龄后，当以刘梦得为最。缘落笔朦胧缥缈，其来无端，其去无际故也。杜老七绝欲与诸家分道扬镳，故尔别开异径。独其情怀，最得诗人雅趣。\n他说杜甫“别开异径”，在盛唐七绝中走出一条新路子，这是熟读杜甫绝句的人都能感觉到的。除了极少数篇章如《赠花卿》、《江南逢李龟年》等外，他的七绝确是与众不同。\n首先，从内容方面扩展...", "authors": ["马茂元"], "pressName": "上海辞书出版社"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6465ec7645e4710056c97d07", "shortContent": "清人李重华在《贞一斋诗话》里有段评论杜甫绝句诗的话：七绝乃唐人乐章，工者最多。……李白、王昌龄后，当以刘梦得为最。缘落笔朦胧缥缈，其来无端，其去无际故也。杜老七绝欲与诸家分道扬镳，故尔别开异径。独其情怀，最得诗人雅趣。\n\n他说杜甫“别开异径”，在盛唐七绝中走出一条新路子，这是熟读杜甫绝句的人都能感觉到的。除了极少数篇章如《赠花卿》、《江南逢李龟年》等外，他的七绝确是与众不同。\n\n首先，从内容方面扩...", "authors": ["马茂元"], "pressName": "上海辞书出版社"}]', '仇兆鳌《杜诗详注》：此为后生讥诮前贤而作，语多跌宕讽刺，故云戏也。姑依梁氏编在上元二年。……少陵绝句，多纵横跌宕，能以议论摅其胸臆，气格才情，迥异常调，不徒以风韵姿致见长矣。
田雯《古欢堂集杂著》：古来论诗者，子美《戏为六绝句》……议论阐发，皆有妙理。
清高宗敕编《唐宋诗醇》：以诗论文，于绝句中，又属创体。此元好问《论诗绝句》之滥觞也。六朝，四子之文，自是天地英华，不可磨灭。其所成就，虽逊古人，要非浅薄疏陋之徒所可轻议，宜甫之直言诃之也。“翡翠兰苕”、“鲸鱼碧海”，所见何其高阔！上亲《风》、《雅》，转益多师，解人不当尔耶？此六诗固不当以字句工拙计之。
浦起龙《读杜心解》：金源元好问《论诗》三十首，托体于此。
翁方纲《石洲诗话》：《六绝句》皆戒后生之沿流而忘源也。其曰“今人嗤点”，曰“尔曹轻薄”、曰“今谁出群”，曰“未及前贤”，不惜痛诋今人者，盖欲俾之考求古人源流，知以古人为师耳。六首俱以师古力主。……“别哉为体”。正是薄之也：“亲风雅”，正是爱之也。杜陵薄今人嗤点之辈，至于如此！与“尔曹身与名俱灭”之言，未免太刺骨矣，故题之曰“戏”也。
杨伦《杜诗镜铨》：张上若曰：六诗使为诗学指南。趋今议古，世世相同，惟大家持论极平，著眼极正。昌黎诗：“李杜文章在，光焰万丈长。不知群儿愚，那用故谤伤。蚍蜉撼大树，可笑不自量。”当公之世，其诽诋者亦不少矣。故偶借庾信、四子以发其意。皆属自寓意多，作如遗山《论诗绝句》通论古今人之诗也。然“别裁伪体”、“转益多师”，学诗之道，实不出此。
萧涤非《杜甫诗选注》：这六首绝句可作文艺批评看，也可作杜甫个人的学习经验和创作经验看，是针对当时诗学界所存在的贵古贱今、好高骛远、夜郎自大等毛病而作的，值得借鉴。杜甫不欲“自以为是”，同时也为了冲淡教训人的气味，所以题作“戏为”。其实态度很严肃，议论很正大，教训也很不客气。', 'center', 1423167473, '57b9658c0a2b58005c95d2a7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10099, '绝句四首（其三）', NULL, 1321, 1416, 2, 11, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155912.htm', '', '两个黄鹂鸣翠柳，一行白鹭上青天。
窗含西岭千秋雪，门泊东吴万里船。', '这首诗是杜甫广德二年（764）春初回草堂时写的，是杜诗写景的佳作。这首绝句一句一景，两两对仗，写法精致考究，但读起来十分自然流畅，一点儿也不觉得有雕琢之感。因为一以贯之的是诗人的内在情感。一开始写草堂的春色，情绪是陶然的；而随着视线的游移、景物的转换、江船的出现，触动了他的乡情。四句景语完整表现了诗人这种复杂细致的内心思想活动。苏轼曾经说过：“少陵翰墨无形画”，此诗就像一幅绚丽生动的山水条幅：画的中心是几棵翠绿的垂柳，黄莺儿在枝头婉转歌唱；画的上半部是青湛湛的天，一行白鹭映于碧空；远处高山明灭可睹，遥望峰巅犹是经年不化的积雪；近处露出半边茅屋，门前一条大河，水面停泊着远方来的船只。从颜色和线条看，作者把两笔鹅黄点染在一片翠绿之中，在青淡的空间斜勾出一条白线。点线面有机结合，色彩鲜明而又和谐。', '黄鹂：黄莺。
白鹭：鹭鸶，羽毛纯白，能高飞。
窗含：是说由窗往外望西岭，好似嵌在窗框中，故曰窗含。
西岭：即成都西南的岷山，其雪常年不化，故云千秋雪。这是想象之词。
东吴：指长江下游的江苏一带。成都水路通长江，故云长江万里船。', '黄鹂在新绿的柳条间叫着春天，成双作对好喜庆；白鹭排成行迎着春风飞上青天，队列整齐真优美。那西岭的雪峰啊，像一幅美丽的画嵌在窗框里；这门前的航船啊，竟是从万里之外的东吴而来。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ae5e272d4b225432df", "shortContent": "公元762年，成都尹严武入朝，蜀中发生动乱，杜甫一度避往梓州（治今四川三台），翌年安史之乱平定，再过一年，严武还镇成都。杜甫得知这位故人的消息，也跟着回到成都草堂。这时他的心情特别好，面对这生气勃勃的景象，情不自禁，写下了这一组即景小诗。兴到笔随，事先既未拟题，诗成后也不打算拟题，干脆以“绝句”为题。\n诗的上联是一组对仗句。草堂周围多柳，新绿的柳枝上有成对黄鹂在欢唱，一派愉悦景象，有声有色，构成了...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a82", "shortContent": "公元762年，成都尹严武入朝，蜀中发生动乱，杜甫一度避往梓州（治今四川三台），翌年安史之乱平定，再过一年，严武还镇成都。杜甫得知这位故人的消息，也跟着回到成都草堂。这时他的心情特别好，面对这生气勃勃的景象，情不自禁，写下了这一组即景小诗。兴到笔随，事先既未拟题，诗成后也不打算拟题，干脆以“绝句”为题。\n\n诗的上联是一组对仗句。草堂周围多柳，新绿的柳枝上有成对黄鹂在欢唱，一派愉悦景象，有声有色，构成...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127066c305cf0801816fb7", "shortContent": "这首小诗，作于成都草堂。时安史之乱业已平定，友人严武还镇成都，难得这样的一份好心情，故而触目所及，是一片美好：阳光和煦，春色诱人，鸟儿和鸣。“以我观物，故物皆着我之色彩。”不错的，看老杜笔下景致的活泼你就知道了。\n\n小诗拆开来看，每一句都是一幅可以镶进镜框的风景画，色彩明丽，情调优雅。但它们彼此并不是独立的，而是共同构造了一幅和谐的诗意画。统一它们的，是诗人视线的流转与情感的波澜。那也许是一个春日...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270d4c26cbf3417f09508", "shortContent": "这首小诗，作于成都草堂。时安史之乱业已平定，友人严武还镇成都，难得这样的一份好心情，故而触目所及，是一片美好：阳光和煦，春色诱人，鸟儿和鸣。“以我观物，故物皆着我之色彩。”不错的，看老杜笔下景致的活泼你就知道了。\n\n小诗拆开来看，每一句都是一幅可以镶进镜框的风景画，色彩明丽，情调优雅。但它们彼此并不是独立的，而是共同构造了一幅和谐的诗意画。统一它们的，是诗人视线的流转与情感的波澜。那也许是一个春日...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "646607af5b7b0d4f4516edcb", "shortContent": "公元762年，成都尹严武入朝，蜀中发生动乱，杜甫一度避往梓州（治今四川三台），翌年安史之乱平定，再过一年，严武还镇成都。杜甫得知这位故人的消息，也跟着回到成都草堂。这时他的心情特别好，面对这生气勃勃的景象，情不自禁，写下了这一组即景小诗。兴到笔随，事先既未拟题，诗成后也不打算拟题，干脆以“绝句”为题。\n\n诗的上联是一组对仗句。草堂周围多柳，新绿的柳枝上有成对黄鹂在欢唱，一派愉悦景象，有声有色，构成...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f0e8f902ee364cc897918", "shortContent": "公元762年，成都尹严武入朝，蜀中发生动乱，杜甫一度避往梓州（治今四川三台），翌年安史之乱平定，再过一年，严武还镇成都。杜甫得知这位故人的消息，也跟着回到成都草堂。这时他的心情特别好，面对这生气勃勃的景象，情不自禁，写下了这一组即景小诗。兴到笔随，事先既未拟题，诗成后也不打算拟题，干脆以“绝句”为题。\n诗的上联是一组对仗句。草堂周围多柳，新绿的柳枝上有成对黄鹂在欢唱，一派愉悦景象，有声有色，构成了...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '程大昌《演繁露》（卷四）云：诗思丰狭，自其胸中来。若思同而句韵殊者，皆象其人，不可强求也。张祜送人游云南，固尝张大其境矣，曰“江连万里海，峡入一条天”。至老杜则日“窗含西岭千秋雪，门泊东吴万里船”，又曰“路经滟灏双蓬鬓，天入沧浪钓舟”，以较祜语，雄伟而又优裕矣。
《漫叟诗话》：诗中有拙句，不失为奇作。若……子美诗“两个黄鹂鸣翠柳，一行白鹭上青天”之类是也。
《高斋诗话》：子美诗云：“两个黄鹂鸣翠柳，……门泊东吴万里船。”东坡《题真州范氏溪堂诗》云：“白水满时双鹭下，绿槐高处一蝉吟。酒醒门外三竿日，卧看溪南十亩阴。”盖用杜老诗意也。
曾季狸《艇斋诗话》：韩子苍云，老杜“两个黄鹂鸣翠柳，一行白鹭上青天”，古人用颜色字，亦须配得相当方用，“翠”上方见得“黄”、“青”上方见得“白”、此说有理。
范季随《陵阳先生室中语》：杜少陵诗云：“两个黄鹂鸣翠柳，一行白鹭上青天。”王维诗云：“漠漠水田飞白鹭，阴阴夏木啭黄鹂。”极尽写物之工。
杨慎《升庵诗话》：绝句四句皆对，杜工部“两个黄鹂”一首是也，然不相连属，即是律中四句也。绝句者，一句一绝，起于《四时咏》："春水满四泽，夏云多奇峰。秋月扬明辉，冬岭秀孤松”是也。或以为陶渊明诗，非。杜诗“两个黄鹂鸣翠柳”实祖之。
胡应麟《诗薮》：杜之律，李之绝，皆天授神诣。然杜以律为绝，如“窗含西岭千秋雪，门泊东吴万里船”等句，本七言律壮语，而以为绝句，则断锦裂缯类也。李以绝为律，如“十月吴山晓，梅花落敬亭”等句，本五言绝妙境，而以为律诗，则骈拇枝指类也。
《夷白斋诗话》：长江万里，人言出于岷山，而不知元从雪山万壑中来。山亘三千余里，特起三峰。其上高寒多积雪，朝日曜之，远望日光若银海。杜子美草堂正当其胜处。其诗曰：“窗含西岭千秋雪”。
浦起龙《读杜心解》：“上兴下赋，意本一贯，注家以四景释之，浅矣”。
《杜臆》：此四诗盖作于入居草堂之后，拟客居此以终老，而自叙情事如此。其三，是自适语。草堂多竹树，境亦超旷，故鸟鸣鹭飞，与物俱适，窗对西山，古雪相映，对之不厌，此与拄笏看爽气者同趣。门泊吴船，即公诗“平生江海心，夙昔具扁舟”是也。公盖尝思吴，今安则可居，乱则可去，去亦不恶，何适如之！
《唐宋诗醇》：虽非正格，自是绝唱。
杨伦《杜诗镜铨》卷十二：此皆就所见掇拾成诗，亦漫兴之类。所谓漫兴，就是触景生情，随遇所感，似漫不经心也。', 'center', 1413388367, '57b908f1d342d3005ac768af', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10124, '玉楼春', NULL, 242, 87, 2, 0, '李煜', NULL, 10017, '57b8af7c5bbb50005b770fdd', '五代十国', 'ci', '词', 'http://baike.baidu.com/view/7249281.htm', '', '晚妆初了明肌雪，春殿嫔娥鱼贯列。凤箫吹断水云间，重按霓裳歌遍彻。
临春谁更飘香屑，醉拍阑干情味切。归时休放烛光红，待踏马蹄清夜月。', '中国传统的文学理论历来认为：「欢愉之辞难工，穷苦之言易好。」后主此词则打破了这一传统看法。词中形象丰美，情趣盎然，具有极强的艺术感染力。词中以真动人，以美感人，趣味高雅，纵情而不淫荡，风流而不艳薄，结尾二句宕开一层，从豪华热闹转向清静淡泊，更显得俊爽超逸，高雅不凡。', '晚妆：一作「晓妆」。
明肌雪：肌肤明洁，白滑似雪。韦端己《菩萨蛮》：」皓腕凝霜雪。」亦是用白雪形容肌肤清亮光洁。
嫔娥：宫中的姬妾与宫女。
鱼贯：游鱼先后接续．比喻一个挨一个地依序排列。
凤箫：凤凰箫。泛指管乐器。一作“笙箫”。
水云：水和云。此指水云相接之处。
重按：一再按奏。
霓裳（nícháng）：《霓裳羽衣舞》的简称，唐代著名法曲。
歌遍彻：唱完大曲中的最后一曲。唐宋大曲系按一定顺序连接若干小曲而成，又称大遍。其中各小曲亦有称「遍」的。一说遍、彻都是称曲调中的名目。据王静安《宋元戏曲史》云：「彻者，如破之末一遍也。」
香屑：香粉，香的粉末。一说指花瓣，花的碎片。如许昂胃《词综偶评》：「疑指落花言之。」
阑干：栏杆。用竹、木、砖石或金属等构制而成，设于亭台楼阁或路边、水边等处作遮拦用。
情味：犹情趣。
烛光红：一作「烛花红」。', '妃嫔宫女们画好了晚妆，一个肌肤似雪，明媚动人，她们鱼贯而入，准备在春殿之上一展自己的美丽和才华。凤箫声悠扬动听，不断演奏着《霓裳羽衣曲》，乐声一直传到水云之间。
临风当前，香料的气味随风飘散，醉拍阑干，其情味深切。归去时不要燃亮烛花焰火，且待骑马踏着清夜月归去。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74945914587d02f46589", "shortContent": "我以前写有《大晏词的欣赏》一文（见《迦陵论词丛稿》），曾经将诗人试分为理性之诗人与纯情之诗人二类。以为理性之诗人其感情乃如“一面平湖”，“虽然受风时亦复縠绉千叠，投石下亦复盘涡百转，然而却无论如何总也不能使之失去其含敛静止、盈盈脉脉的一份风度”。此一类型之诗人，应以晏殊为代表。至于南唐后主李煜，则恰好是另一类型，属于纯情之诗人的最好的代表。这一类型的诗人之感情，不像盈盈脉脉的平湖，而像滔滔滚滚的江...", "authors": ["叶嘉莹"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892e508c9c030fd725f1", "shortContent": "我以前写有《大晏词的欣赏》一文（见《迦陵论词丛稿》），曾经将诗人试分为理性之诗人与纯情之诗人二类。以为理性之诗人其感情乃如“一面平湖”，“虽然受风时亦复縠绉千叠，投石下亦复盘涡百转，然而却无论如何总也不能使之失去其含敛静止、盈盈脉脉的一份风度”。此一类型之诗人，应以晏殊为代表。至于南唐后主李煜，则恰好是另一类型，属于纯情之诗人的最好的代表。这一类型的诗人之感情，不像盈盈脉脉的平湖，而像滔滔滚滚的江...", "authors": ["叶嘉莹"], "pressName": "上海辞书出版社"}]', '', 'indent', 1362515655, '57b8ff160a2b58005c923102', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10100, '闻官军收河南河北', NULL, 795, 1416, 3, 10, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/129509.htm', '', '剑外忽传收蓟北，初闻涕泪满衣裳。
却看妻子愁何在，漫卷诗书喜欲狂。
白日放歌须纵酒，青春作伴好还乡。
即从巴峡穿巫峡，便下襄阳向洛阳。​', '此诗作于唐代宗广德元年（公元763年）春。当年正月史朝义自缢，他的部将李怀仙斩其首来献，安史之乱结束。杜少陵听到这消息，不禁惊喜欲狂，手舞足蹈，冲口唱出这首七律。全诗八句。开头写初闻喜讯的惊喜；后半部分写诗人手舞足蹈做返乡的准备，凸显了急于返回故乡的欢快之情。全诗情感奔放，处处渗透着「喜」字，痛快淋漓地抒发了作者无限喜悦兴奋的心情。因此被称为杜少陵「生平第一快诗」。诗的后六句都是对偶，但却明白自然像说话一般，有水到渠成之妙。', '闻：听说。
官军：指唐朝军队。
剑外：剑门关以南，这里指四川。
蓟北：泛指唐代幽州、蓟州一带，今河北北部地区，是安史叛军的根据地。
却看：回头看。
妻子：妻子和孩子。
愁何在：哪还有一点的忧伤？愁已无影无踪。
漫卷（juǎn）诗书喜欲狂：胡乱地卷起。是说杜少陵已经迫不及待地去整理行装准备回家乡去了。喜欲狂，高兴得简直要发狂。
放歌：放声高歌。
纵酒：开怀痛饮。
青春：指明丽的春天的景色。
作伴：与妻儿一同。
巫峡：长江三峡之一，因穿过巫山得名。
襄阳：今属湖北。
洛阳：今属河南，古代城池。', '剑门外忽传收复蓟北的消息，初闻此事分外欢喜泪洒衣衫。
回头看妻儿的愁云顿时消散，随便地收拾起诗书欣喜若狂。
日头照耀放声高歌痛饮美酒，明媚的春光伴着我返回故乡。
快快动身起程巴峡穿过巫峡，我穿过了襄阳后又直奔洛阳。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ad2cee9a0c24ecf8d6", "shortContent": "这首诗，作于唐代宗广德元年（763）春天，作者五十二岁。宝应元年（762）冬季，唐军在洛阳附近的横水打了一个大胜仗，收复了洛阳和郑（今河南郑州）、汴（今河南开封）等州，叛军头领薛嵩、张忠志等纷纷投降。第二年，即广德元年正月，史思明的儿子史朝义兵败自缢，其部将田承嗣、李怀仙等相继投降。正流寓梓州（治所在今四川三台），过着漂泊生活的杜甫听到这个消息，以饱含激情的笔墨，写下了这篇脍炙人口的名作。\n杜甫于...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a7f", "shortContent": "这首诗，作于唐代宗广德元年（763）春天，作者五十二岁。宝应元年（762）冬季，唐军在洛阳附近的横水打了一个大胜仗，收复了洛阳和郑（今河南郑州）、汴（今河南开封）等州，叛军头领薛嵩、张忠志等纷纷投降。第二年，即广德元年正月，史思明的儿子史朝义兵败自缢，其部将田承嗣、李怀仙等相继投降。正流寓梓州（治所在今四川三台），过着漂泊生活的杜甫听到这个消息，以饱含激情的笔墨，写下了这篇脍炙人口的名作。\n\n杜甫...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d1933015209", "shortContent": "安史之乱历时八年，且不说它给国家人民带来了多大的灾难，光是诗人杜甫自身的辗转流离，就让他每每想起，泪流满襟。他无时无刻不在盼望唐军早日恢复江山，让社稷重新走上和平的发展道路，这一期盼一望就是八年！终于，代宗广德元年（763），诗人欣闻唐军收复了洛阳和郑（河南郑州）、汴（今河南开封）等州，叛军纷纷溃退。历时长达八年之久的安史叛乱有望结束，爱国爱民的诗人杜甫喜急而狂，提笔挥洒，用热泪写就此作！\n\n“剑...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127066c305cf0801816fb3", "shortContent": "安史之乱历时八年，且不说它给国家人民带来了多大的灾难，光是诗人杜甫自身的辗转流离，就让他每每想起，泪流满襟。他无时无刻不在盼望唐军早日恢复江山，让社稷重新走上和平的发展道路，这一期盼一望就是八年！终于，代宗广德元年（763），诗人欣闻唐军收复了洛阳和郑（河南郑州）、汴（今河南开封）等州，叛军纷纷溃退。历时长达八年之久的安史叛乱有望结束，爱国爱民的诗人杜甫怎能不百感交集，提笔挥洒，用热泪写就此作！\n...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270d4c26cbf3417f09507", "shortContent": "安史之乱历时八年，且不说它给国家人民带来了多大的灾难，光是诗人杜甫自身的辗转流离，就让他每每想起，泪流满襟。他无时无刻不在盼望唐军早日恢复江山，让社稷重新走上和平的发展道路，这一期盼一望就是八年！终于，代宗广德元年（763），诗人欣闻唐军收复了洛阳和郑（河南郑州）、汴（今河南开封）等州，叛军纷纷溃退。历时长达八年之久的安史叛乱有望结束，爱国爱民的诗人杜甫怎能不百感交集，提笔挥洒，用热泪写就此作！\n...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6465ed675fc8182fe9a36c72", "shortContent": "这首诗，作于唐代宗广德元年（763）春天，作者五十二岁。宝应元年（762）冬季，唐军在洛阳附近的横水打了一个大胜仗，收复了洛阳和郑（今河南郑州）、汴（今河南开封）等州，叛军头领薛嵩、张忠志等纷纷投降。第二年，即广德元年正月，史思明的儿子史朝义兵败自缢，其部将田承嗣、李怀仙等相继投降。正流寓梓州（治所在今四川三台），过着飘泊生活的杜甫听到这个消息，以饱含激情的笔墨，写下了这篇脍炙人口的名作。\n\n杜甫...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '《潜溪诗眼》：古人律诗亦是一片文章，语或似无伦次，而意若贯珠……「剑外忽传收蓟北，初闻涕泪满衣裳。」夫人感极则悲，悲定而后喜。忽闻大盗之平，喜唐室复见太平，顾视妻子，知免流离，故曰「却看妻子愁何在」；其喜之至也，不知手之舞之，足之蹈之，故曰「漫展诗书喜欲狂」；从此有乐生之心，故曰「白日放歌须纵酒」；于是率中原流寓之人同归，以青春和暖之时即路，故曰「青春作伴好还乡」。言其道涂则曰「欲从巴峡穿巫峡」，言其所归则曰「便下襄阳到洛阳」此盖曲尽一时之意，惬当众人之情，通畅而有条理，如辩士之语言也。
《诗薮》：老杜好句中迭用字，惟「落花游丝」妙极。此外，如……「便下襄阳向洛阳」之类，颇令人厌。
《杜臆》：说喜者云喜跃，此诗无一字非喜，无一字不跃。其喜在「还乡」，而最妙在束语直写还乡之路，他人决不敢道。
《唐诗快》：写出意外惊喜之况，有如长比放流，骏马注坡，直是一往奔腾，不可收拾。
《杜诗说》：杜诗强半言愁，其言喜者，惟《寄弟》数首，及此作而已。言愁者使人对之欲哭，言喜者使人对之欲笑。盖能以其性情，达之纸墨，而后人之性情，类为之感动故也。使舍此而徒讨论其格调，剽拟其字句，抑末矣。
《义门读书记》：如龙。二泉云：后半喜之极，故言之泽。
《杜诗解》：「愁何在」妙。平日我虽不在妻子面前愁，妻子却偏要在我面前愁，一切攒眉泪眼之状，甚是难看。「漫捲诗书」妙，身在剑外，惟以诗书消遣过日，心却不在诗书上。
《初白庵诗评》：由浅入深，句法相生，自首至尾，一气贯注，似此章法，香山以外罕有其匹。
《杜诗详注》：顾宸曰：杜诗之妙，有以命意胜者，有以篇法胜者，有以俚质胜者，有以仓卒造状胜者。此诗之「忽传」、「初闻」、「却看」、「漫捲」、「即从」、「便下」，于仓卒间，写出欲歌欲哭之状，使人千载如见。朱瀚曰：「涕泪」，为收河北；狂喜，为收河南。此通章关键也。而河北则先点后发，河南则先发后点，详略顿挫，笔如游龙。又地名凡六见，主宾虚实，累累如贯珠，真善于将多者。
《茧斋诗谈》：一气如注，并异日归程一齐算出，神理如生，古今绝唱也。
《唐宋诗醇》：惊喜溢于字句之外，故其为诗，一气呵成，法极无迹。末联撒手空行，如懒残履衡岳之石，旋转而下，非有伯昏瞀人之气者不能也。
《唐诗别裁》：一气流注，不见句法字法之迹。对结自是落句、故收得住。若他人为之，仍是中间对偶，便无气力。
《读杜心解》：八句诗，其疾如飞。题事只一句，余俱写情。得力全在次句。于情理，妙在逼真，于文势，妙在反振。三、四，以转作承，第五，乃能缓受，第六，上下引脉，七、八，紧申「还乡」，生平第一首快诗也。
《杜诗镜铨》：结联，毛西河云，即实从归途一直快数作结，大奇。且两「峡」两「阳」作跌宕句，律法又变。
《闻鹤轩初盛唐近体读本》：
陈德公曰：所谓狂喜，其中生气莽溢行间，结二尤见踊跃如鹜。作诗有气，岂在字句争妍？
《读杜私言》：「剑外忽传收蓟北，初闻涕泪满衣裳」，纯用倒装，在起手犹难。
《杜诗集评》：李因笃云：转宕有神，纵横自得，深情老致，此为七律绝顶之篇。律诗中当带古意，乃致神境。然崔颢《黄鹤楼》以散为古，公此篇以整为古，较崔作更难。
《杜诗言志》：看他八句一气浑成中，细按之却有无限妙义，直是情至文生。
《唐诗绎》：通首一气挥洒，曲折如意。
《岘佣说诗》：「剑外忽传收蓟北」，今人动笔，便接「喜欲狂」矣。忽拗一笔云：「初闻涕泪满衣裳」，以曲取势。活动在「初闻」两字，从「初闻」转出「却看」，从「却看」转出「漫捲」，才到喜得「还乡」正面，又不遽接「还乡」，用「白首放歌」一句垫之，然后转到「还乡」。收笔「巴峡穿巫峡」、「襄阳下洛阳」，正说还乡矣，又恐通首太流利，作对句锁之。即走即守，再三读之，思之，可悟俯仰用笔之妙。
《近体秋阳》：白首不能放歌，要须纵酒而歌，还乡无人作伴，聊请青春相伴，对法整而乱，乱而整（「还乡」句下）。一气注下，格律清异。
《全唐风雅》：写喜意真切，愈朴而近（「漫捲诗书」句下）。自然是喜意流动得人，结复何等自然。喜愿之极，诚有如此，他语不足易也。', 'center', 1417443760, '57b8f7127db2a20054265cb7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10101, '卜算子 · 黄州定慧院寓居作', NULL, 995, 3406, 3, 6, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/660399.htm', '', '缺月挂疏桐，漏断人初静。谁见幽人独往来，缥缈孤鸿影。
惊起却回头，有恨无人省。拣尽寒枝不肯栖，寂寞沙洲冷。', '定慧院在今天的湖北黄冈市东南，又作定惠院，东坡另有《遊定慧院记》一文。由上可知这首词是东坡初贬黄州寓居定慧院时所作。东坡因所谓的「乌台诗案」，被贬为黄州团练副使。
此词上阕写鸿见人，下阕写人见鸿，藉月夜孤鸿这一形象托物寓怀，表达了词人孤髙自许、蔑视流俗的心境。全词藉物比兴，写景兴怀，托物咏人，物我交融，含蕴深广，风格清奇，为词中名篇。
黄山谷评：「语意髙妙，似非喫烟火食人语，非胸中有万卷书，笔下无一点尘俗气，孰能至此！」', '卜算子：词牌名。相传是借用唐代诗人骆观光的绰号。骆观光写诗好用数字取名，人称「卜算子」。北宋时盛行此曲。明末清初·万红友《词律》引毛氏云：「骆义乌诗，用数名，人谓为『卜算子』，故牌名取之。」又云：「按山谷词『似扶著卖卜算』，盖取义以今卖卜算命之人也。又因秦湛词有：『极目烟中百尺楼』之句，故《图谱》删『卜算子』而名『百尺楼』；然『卜算子』之名，得知较早也。」。元高拭词注「仙吕调」。苏东坡词有「缺月挂疏桐」句，名《缺月挂疏桐》。秦处度词有「极目烟中百尺楼」句，名《百尺楼》。僧皎词有「目断楚天遥」句，名《楚天遥》。无名氏词有「蹙破眉峰碧」句，名《眉峰碧》。双调，四十四字，上下阕各两仄韵。两结亦可酌增衬字，化五言句为六言句，于第三字豆。宋教坊复演为慢曲，《乐章集》入「歇指调」，八十九字，前阕四仄韵，后阕五仄韵。
「黄州定慧院寓居作」：明吴讷钞本、《苏长公二妙集》本、《东坡外集》均无词题，调名下径引黄鲁直跋，文字与傅注词末附录者稍异，作「黄鲁直跋云：『东坡道人在黄州时作。语意高妙，似非吃烟火食人语。非胸中有万卷书，笔下无一点尘俗气，孰能至此！』」又《苏长公二妙集》本、茅维《苏集》本于黄跋后接引《耆旧续闻》云：「赵右史家有顾禧景蕃《补注东坡长短句》真迹，……云：『余顷于郑公实处，见东坡亲迹书《卜算子》断句云「寂寞沙洲冷」，今本作「枫落吴江冷」，词意全不相属也。』又毛本调名下注云：「惠州有温都监女，颇有色，，年十六，不肯嫁人，闻坡至，甚喜，每夜闻坡讽咏，则徘徊窗下。坡觉而推窗，则其女逾墙而去。坡从而物色之，曰：『吾当呼王郎，与之子为姻。』未几而坡过海。女遂卒，葬于沙滩侧。坡回惠，为赋此词。」刘尚荣按：「毛本此注本宋王勉夫撰《野客丛书·卷二十四·东坡〈卜算子〉》。朱彊村曾在《彊村丛书》本《东坡乐府·凡例》中指出：『毛本标题，依托谬妄，并违词中本旨。』其说甚是。毛本妄拟本事，不可取。」
定慧院：龙榆生笺：「《东坡诗集》作『定惠院』。查注：『《名胜志》：「定惠院在黄冈县东南。」』」
谁见：傅子立注：「一作『时见』，一作『唯有』。」刘尚荣按：「明吴讷钞本、《苏长公二妙集》本、茅维《苏集》本作『时见』，今未见何本苏词作『唯有』。」
幽人：龙榆生笺引《周易·履卦》：「履道坦坦，幽人贞吉。」
孤鸿：龙榆生笺引唐·张曲江《感遇》诗：「孤鸿海上来，池潢不敢顾。」
「拣尽寒枝不肯栖」句：龙榆生笺：「《滹南遗老集·诗话》：『东坡雁词「拣尽寒枝不肯栖」，以其不栖木，故云尔。盖激诡之致，词人正贵其如此，而或者以为语病，是尚可与言哉？近日张吉甫复以「鸿渐于木」为辨，而怪昔人之寡闻，此益可笑。《易·象》之言，不可援引为證也。其实雁何尝栖木哉？』」
「寂寞沙洲冷」句：傅子立注：「一作『枫落吴江冷』。唐崔信明美文章，郑世翼亦自负，二人相遇江中，郑谓崔曰：『闻公有「枫落吴江冷」，愿见其馀。』崔出之，郑览未终，曰：『所见不逮所闻！』投诸水，引舟而去。」刘尚荣按引《唐才子传·卷一·崔信明传》：「信明，青州人。少英敏，及长，强记，美文章。高孝基语人曰：『崔生才冠一时，但恨位不到耳。』隋大业中，为尧城令。窦建德僭号，信明弟仕贼，劝信明降节，当得美官。不肯从，遂逾城去，隐太行山中。唐贞观六年，诏即家拜兴势丞，迁秦川令，卒。信明恃才蹇亢，尝自矜其文。时有扬州录事参军荥阳郑世翼，亦骜倨忤物，遇信明于江中，谓曰：『闻君有「枫落吴江冷」之句，仍愿见其馀。』信明欣然多出旧制。郑览未终，曰：『所见不逮所闻！』投卷于水中，引舟而去。今其诗传者数篇而已。」龙榆生笺引《新唐书·卷二百零一·〈文艺列传·崔信明传〉》：「崔信明，青州益都人。高祖光伯，仕后魏为七兵尚书。信明之生，五月五日日方中，有异雀鸣集庭树，太史令史良为占曰：『五月为火，火主《离》，《离》为文，日中，文之盛也，雀五色而鸣，此儿将以文显。然雀类微，位殆不高邪。』及长，强记，美文章。乡人高孝基尝语人曰：『崔生才富，为一时冠，但恨位不到耳。』隋大业中，为尧城令。窦建德僭号，而信明族弟敬素者，为贼鸿胪卿，自谓得意，语信明曰：『夏王英武，有举天下心，士女襁负而至不可数。兄不以此时立功立事，岂所谓见几不俟终日乎？』答曰：『昔申胥海隅钓师，能固其节。尔欲吾屈身贼中求斗筲邪？』遂逾城去，隐太行山。贞观六年，有诏即家拜兴势丞。迁秦川令，卒。信明蹇亢，以门望自负，尝矜其文，谓过李百药，议者不许。扬州录事参军郑世翼者，亦骜倨，数恌轻忤物，遇信明江中，谓曰：『闻公有「枫落吴江冷」，愿见其馀。』信明欣然多出众篇，世翼览未终，曰：『所见不逮所闻！』投诸水，引舟去。」又元延祐本、明吴讷钞本、《苏长公二妙集》本、茅维《苏集》本均作「枫落吴江冷」。刘尚荣按：「《耆旧续闻·卷二》：『赵右史家有顾禧景蕃《补注东坡长短句》真迹，……云：「余顷于郑公实处，见东坡亲迹书《卜算子》断句云『寂寞沙洲冷』，今本作『枫落吴江冷』，词意全不相属也。」』」
尾注：傅子立注：「黄鲁直跋云：『东坡道人在黄州时作。语意高妙，似非吃烟火食人语。非胸中有万卷书，笔下无一点俗气，孰能至此！黄庭坚题。』」', '残月高挂在稀疏的梧桐，滴漏声断人群开始安静了。谁能见幽居人独自往来，彷彿那缥缈的孤雁身影。
它突然惊起又回首匆匆，心里有恨却无人能懂。它拣遍了寒冷的树枝不肯栖息，却躲到寂寞的沙洲甘愿受苦。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b2c6e67846a9206b13", "shortContent": "这首词是元丰五年（1082）十二月苏轼在黄州所作（王文诰《苏诗总案》）。先是熙宁中，苏轼与王安石政见不合，出补外官，他看到当时地方官吏执行新法多扰民者，心中不满，发抒于诗中，因此激怒新党，说苏轼诽谤朝政，遂逮捕下狱，百端罗织，必欲置之死地，即所谓“乌台诗案”。幸而神宗还算明白，终于释放苏轼出狱，贬为黄州团练副使。苏轼自元丰三年（1080）二月至黄州，至元丰七年六月乃量移汝州，在黄州贬所居住四年多。...", "authors": ["缪", "钺"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b97d0ac1145495e88f", "shortContent": "这首词是元丰五年（1082）十二月苏轼在黄州所作（王文诰《苏诗总案》）。先是熙宁中，苏轼与王安石政见不合，出补外官，他看到当时地方官吏执行新法多扰民者，心中不满，发抒于诗中，因此激怒新党，说苏轼诽谤朝政，遂逮捕下狱，百端罗织，必欲置之死地，即所谓“乌台诗案”。幸而神宗还算明白，终于释放苏轼出狱，贬为黄州团练副使。苏轼自元丰三年（1080）二月至黄州，至元丰七年六月乃量移汝州，在黄州贬所居住四年多。...", "authors": ["缪", "钺"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253f534825dee9fd6e4", "shortContent": "这首词是元丰五年（1082）十二月苏轼在黄州所作（王文诰《苏诗总案》）。先是熙宁中，苏轼与王安石政见不合，出补外官，他看到当时地方官吏执行新法多扰民者，心中不满，发抒于诗中，因此激怒新党，说苏轼诽谤朝政，遂逮捕下狱，百端罗织，必欲置之死地，即所谓“乌台诗案”。幸而神宗还算明白，终于释放苏轼出狱，贬为黄州团练副使。苏轼自元丰三年（1080）二月至黄州，至元丰七年六月乃量移汝州，在黄州贬所居住四年多。...", "authors": ["缪　钺"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7ac305cf0801816c9b", "shortContent": "从黄庭坚跋及傅本题可知，此词乃苏轼贬谪黄州寓居定惠院时所作。定惠院：明弘治《黄州府志》卷四：“定惠院，在府治东南，苏子瞻尝寓居，作海棠诗以自述。”至于具体年份，王文诰《苏诗总案》卷二一云作于元丰四年与五年之内。朱本、龙本、曹本据之编元丰五年十二月。吴雪涛《苏词四首系年商兑》考证以上诸本编年之非，云：“苏轼于元丰三年庚申（1080）二月一日到黄州贬所，寓居定惠院僧舍未久，即迁于濒临大江的临皋亭，直至...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3d73206168b2e020c7", "shortContent": "这首《卜算子》是词人被贬黄州时所作，比起《江城子》（密州出猎）一词，这首词少了几分桀骜张扬，多了几许淡淡愁绪。\n上阕写景，桐枝稀疏，月挂枝头，夜已深，人声静，值此夜深人静之际，但见一幽人踽踽独行，兀自徘徊，有谁可见？惟一孤鸿而已。\n杜甫诗云：“感时花溅泪，恨别鸟惊心。”心之所感，目之所见。词人此时被贬黄州，自是心有戚戚，目之所及，无不是缺月、疏影、孤鸿，这既渲染一种孤寂清冷的氛围，又表达了作者的幽...", "authors": ["郑佳敏"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702e7ccdb86c49f291f6", "shortContent": "这首《卜算子》是词人被贬黄州时所作，比起《江城子》（密州出猎）一词，这首词少了几分桀骛张扬，多了几许淡淡愁绪。\n\n上阕写景，桐枝稀疏，月挂枝头，夜已深，人声静，值此夜深人静之际，但见一幽人踽踽独行，兀自徘徊，有谁可见？惟一孤鸿而已。杜甫诗云：“感时花溅泪，恨别鸟惊心。”心之所感，目之所见。词人此时被贬黄州，自是心有戚戚，目之所及，无不是缺月、疏影、孤鸿，这既渲染一种孤寂清冷的氛围，又表达了作者的幽...", "authors": ["郑佳敏"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271abc9ebcc6fbea1a4eb", "shortContent": "这首《卜算子》是词人被贬黄州时所作，比起《江城子》（密州出猎）一词，这首词少了几分桀骜张扬，多了几许淡淡愁绪。\n上阕写景，桐枝稀疏，月挂枝头，夜已深，人声静，值此夜深人静之际，但见一幽人踽踽独行，兀自徘徊，有谁可见？惟一孤鸿而已。杜甫诗云：“感时花溅泪，恨别鸟惊心。”心之所感，目之所见。词人此时被贬黄州，自是心有戚戚，目之所及，无不是缺月、疏影、孤鸿，这既渲染一种孤寂清冷的氛围，又表达了作者的幽思...", "authors": ["郑佳敏"], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "6468356b7f27182da36284b0", "shortContent": "这首词是元丰五年（1082）十二月苏轼在黄州所作（王文诰《苏诗总案》）。先是熙宁中，苏轼与王安石政见不合，出补外官，他看到当时地方官吏执行新法多扰民者，心中不满，发抒于诗中，因此激怒新党，说苏轼诽谤朝政，遂逮捕下狱，百端罗织，必欲置之死地，即所谓“乌台诗案”。幸而神宗还算明白，终于释放苏轼出狱，贬为黄州团练副使。苏轼自元丰三年（1080）二月至黄州，至元丰七年六月乃量移汝州，在黄州贬所居住四年多。...", "authors": ["缪钺"], "pressName": "上海辞书出版社"}]', '黄山谷：语意髙妙，似非喫烟火食人语，非胸中有万卷书，笔下无一点尘俗气，孰能至此！
黄蓼园《蓼园词选》：语语双关，格奇而语隽，斯为超诣神品。
陈亦峰《词则·大雅集》评此词说：寓意髙远，运笔空灵，措语忠厚，是坡仙独至处，美成、白石亦不能到也。
吴虑臣《能改斋漫录》：其属意盖为王氏女子也，读者不能解。张右史文潜继贬黄州，访潘邠老，闻得其祥，题诗以志之云：空江月明鱼龙眠，月中孤鸿影翩翩。有人清吟立江边，葛巾藜杖眼窥天。夜冷月堕幽虫泣，鸿影翘沙衣露湿。仙人采诗作步虚，玉皇饮之碧琳腴。
胡元任《苕溪渔隐丛话前集·卷三十九中》：此词本咏夜景，至换头但只说鸿。正如《贺新郎》词「乳燕飞华屋」，本咏夏景，至换头但只说榴花。盖其文章之妙，语意到处即为之，不可限以绳墨也。', 'indent', 1413129731, '57b8fe9d5bbb50005b7814a3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10102, '浣溪沙 · 游蕲水清泉寺', NULL, 463, 3406, 1, 12, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/3372888.htm', '游蕲水清泉寺，寺临兰溪，溪水西流。', '山下兰芽短浸溪，松间沙路净无泥。萧萧暮雨子规啼。
谁道人生无再少？门前流水尚能西！休将白发唱黄鸡。', '此词描写雨中的南方初春，表达作者虽处困境而老当益壮、自强不息的精神，洋溢着一种向上的人生态度。整首词如同一首意气风发的生命交响乐，一篇老骥伏枥，志千里的宣言书，流露出对青春活力的召唤，对未来的向往和追求，读之令人奋发自强。', '浣溪沙：词牌名。原为唐代教坊曲，《金奁集》入「黄钟宫」，《张子野词》入「中吕宫」。唐声诗唐代配乐之近体诗亦有「浣溪沙」调名，歌词为七言六句形式；又有「浣纱女」调名，歌词为五言四句形式。从字义上来看，「浣」，洗涤、漂洗也；「沙」，古通「纱」，故所「浣」者，「纱」也。敦煌出土之唐写本《云谣集·杂曲子》及五代後蜀赵崇祚《花间集》所录毛平圭、阎处士、毛熙震、李德润词，调名均题为「浣纱溪」。据南朝宋孔灵符《会稽记》载：「勾践索美女以献吴王，得诸暨罗山卖薪女西施、郑旦，先教习于土城山。山边有石，云是西施浣纱石」。今浙江诸暨市南近郊的苧萝山下浣纱溪畔有浣纱石，上有传为东晋王右军所书「浣纱」二字，即所传春秋时越国美女西子浣纱处。一说浣纱溪即浙江绍兴南二十里若耶溪。总之，调名「浣纱溪」的本意即咏西子浣纱之溪。又，近人梁启勋《词学·调名》云：「《浣纱溪》，杜少陵诗『移船先生庙，洗药浣纱溪』。」按：今查《杜工部集》，唐杜少陵《绝句三首》诗有「移船先主庙，洗药浣沙溪」之句。成都杜甫草堂附近有浣花溪而无浣纱溪，况且梁启勋所引诗句，其中的「生」「纱」二字尚有异文，故梁说仅备参考。最早采用此调的是唐人韩致尧，通常以其词《浣溪沙·宿醉离愁慢髻鬟》为正体，另有四种变体。正体双调，四十二字，上阕三句，三平韵；下阕三句，两平韵；过阕二句多用对偶。另有仄韵体，始于南唐後主。此调音节明快，句式整齐，易于上口，为婉约、豪放两派词人所常用。别有《摊破浣溪沙》，又名《山花子》，上下阕各增三字，韵全同。张子澄词有「露浓香泛小庭花」句，名《小庭花》；韩涧泉词有「芍药酴縻满院春」句，名《满院春》；有「东风拂栏露犹寒」句，名《东风寒》；有「一曲西风醉木犀」句，名《醉木犀》；有「霜後黄花菊自开」句，名《霜菊黄》；有「广寒曾折最高枝」句，名《广寒枝》；有「春风初试薄罗衫」句，名《试香罗》；有「清和风里绿荫初」句，名《清和风》；有「一番春事怨啼鹃」句，名《怨啼鹃》。
蕲（Qí）水：龙榆生笺引宋·乐子正《太平寰宇记·巻一百二十一·〈淮南道·蕲州蕲春郡·蕲水县〉》：「（淮南蕲春郡，领县四。其一）」蕲水县，西北七十二里。旧十乡，今四乡。本汉蕲春县地。宋武帝于此置浠水县。唐武德四年改为兰溪，至天宝元年改为蕲水县，以县界蕲水所出为名。茶山在县北。深州每年采造贡茶之所。兰溪水源出箬竹山，其侧多兰，唐武德初，县指此为名。」
清泉寺：《东坡志林·卷一·游沙湖》：「黄州东南三十里为沙湖，亦曰螺师店，予买田其间。因往相田得疾，闻麻桥人庞安常善医而聋，遂往求疗。安常虽聋而颖悟绝人，以指画字，不书数字，辄深了人意。予戏之曰：『予以手为口，君以眼为耳，皆一时异人也。』疾愈，与之同游清泉寺。寺在蕲水郭门外二里许，有王逸少洗笔泉，水极甘，下临兰溪，溪水西流。予作歌云：『山下兰芽短浸溪。松间沙路净无泥。萧萧暮雨子规啼。谁道人生无再少君，君看流水尚能西。休将白发唱黄鸡。』是日剧饮而归。」
「松间沙路净无泥」句：傅子立注：「杜工部诗：『碧涧虽多雨，秋沙先少泥。』」刘尚荣按：「句见《到村》诗，见《九家集注杜诗·卷二十六》。」龙榆生笺引宋·曾达臣《独醒杂志·巻二》：「徐公师川尝言东坡长短句有云：『山下兰芽短浸溪，松间沙路净无泥。』白乐天诗云：『柳桥晴有絮，沙路润无泥。』『净』、『润』两字，当有能辩之者。」
子规：傅子立注：「《成都记》：『杜宇亦曰杜主，自天而降，称望帝。好稼穑，教人务农。至今蜀之将农者，必先祀杜主。望帝时以国相开明有治水功，因禅位焉。後望帝死，其魂化为鸟，名曰杜鹃，亦曰子规云。』唐吴娘曲：『暮雨萧萧郎不归。』」刘尚荣按：「《新唐书·巻五十八·〈艺文志·乙部·地理〉》著录卢求《成都记》五巻，已失传。吴娘曲见明刻《吟窗杂志·巻五十》及白乐天《寄殷协律》诗自注引江南吴二娘曲词。『萧萧』又作『潇潇』，或作『朝朝』。又《唐宋诸贤绝妙词选·卷一》收全词，调名《长相思》，署白乐天作。」
人生无再少：傅子立注：「古诗：『花有重开日，人无再少年。』」刘尚荣按：「宋陈嵩溪撰《本堂集·巻一·续侄漙赏酴醾劝酒二首（其一）》」
门前：《东坡志林·卷一·游沙湖》作「君看」，兹从傅注本
流水尚能西：傅子立注：「公序云：『寺前兰溪水西流。』」刘尚荣按：「句见《东坡志林·巻一·游沙湖》，又见明刊《苏东坡全集·书清泉寺》文。」
白发唱黄鸡：傅子立注：「白乐天《醉歌示妓人商玲珑》：『罢胡琴，掩秦瑟，玲珑再拜歌初毕。谁道使君不解歌，听唱黄鸡与白日。黄鸡催晓丑时鸣，白日催年酉前没。腰间红绶系未稳，镜里朱颜看已失。玲珑玲珑奈老何，使君歌了汝更歌。』」刘尚荣按：「诗见《白氏长庆集·卷十二》。」', '山脚下溪边的兰草才抽出嫩芽，浸泡在溪水之中。松间的沙石小路经过春雨的冲刷，洁净无泥。时值日暮，松林间的杜鹃鸟在潇潇细雨中啼叫。
谁说人老不会再回年少时光呢？你看看，那门前的流水尚能向西奔流呢！所以，不要在老年感叹时光流逝。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b5c6e67846a9206b26", "shortContent": "这首小词是苏轼贬居黄州时期，于元丰五年（1082）三月游蕲水清泉寺时所作。蕲水，县名，即今湖北浠水县，距黄州不远。《东坡志林》卷一云：“黄州东南三十里为沙湖，亦曰螺师店，予买田其间，因往相田得疾。闻麻桥人庞安常善医而聋，遂往求疗。……疾愈，与之同游清泉寺。寺在蕲水郭门外二里许，有王逸少洗笔泉，水极甘，下临兰溪，溪水西流。余作歌云。”这里所指的歌，即这首《浣溪沙》，除第五句“门前”作“君看”外，其余...", "authors": ["刘乃昌"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5bc0f8fda556506048e", "shortContent": "这首小词是苏轼贬居黄州时期，于元丰五年（1082）三月游蕲水清泉寺时所作。蕲水，县名，即今湖北浠水县，距黄州不远。《东坡志林》卷一云：“黄州东南三十里为沙湖，亦曰螺师店，予买田其间，因往相田得疾。闻麻桥人庞安常善医而聋，遂往求疗。……疾愈，与之同游清泉寺。寺在蕲水郭门外二里许，有王逸少洗笔泉，水极甘，下临兰溪，溪水西流。余作歌云。”这里所指的歌，即这首《浣溪沙》，除第五句“门前”作“君看”外，其余...", "authors": ["刘乃昌"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253f534825dee9fd6ec", "shortContent": "这首小词是苏轼贬居黄州时期，于元丰五年（1082）三月游蕲水清泉寺时所作。蕲水，县名，即今湖北浠水县，距黄州不远。《东坡志林》卷一云：“黄州东南三十里为沙湖，亦曰螺师店，予买田其间，因往相田得疾。闻麻桥人庞安常善医而聋，遂往求疗。……疾愈，与之同游清泉寺。寺在蕲水郭门外二里许，有王逸少洗笔泉，水极甘，下临兰溪，溪水西流。余作歌云。”这里所指的歌，即这首《浣溪沙》，除第五句“门前”作“君看”外，其余...", "authors": ["刘乃昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7bf2af4e09d55b6555", "shortContent": "王文诰《苏诗总案》谓壬戌兰月，“蕲水多腴田，往求不遂。俄得臂疾，会潘尉、庞医来迎，相率至麻桥庞所居，留数日。”“疾愈，与庞医游清泉寺，饮王羲之洗笔泉，傥佯兰溪之上，作《浣溪沙》词。”孔《谱》、薛本、邹王本均编元丰五年壬戌（1082）三月。\n\n《苏轼文集》卷六十八《书清泉寺词》载此词本事云：“黄州东南三十里，为沙湖，亦曰螺师店。余将买田其间，因往相田。得疾，闻麻桥人庞安时善医而聋，遂往求疗。安时虽聋...", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646840b87da2f75ac7f684d7", "shortContent": "这首小词是苏轼贬居黄州时期，于元丰五年（1082）三月游蕲水清泉寺时所作。蕲水，县名，即今湖北浠水县，距黄州不远。《东坡志林》卷一云：“黄州东南三十里为沙湖，亦曰螺师店，予买田其间，因往相田得疾。闻麻桥人庞安常善医而聋，遂往求疗。……疾愈，与之同游清泉寺。寺在蕲水郭门外二里许，有王逸少洗笔泉，水极甘，下临兰溪，溪水西流。余作歌云。”这里所指的歌，即这首《浣溪沙》，除第五句“门前”作“君看”外，其余...", "authors": ["刘乃昌"], "pressName": "上海辞书出版社"}]', '曾独醒《独醒杂志·卷二》：徐公师川尝言：东坡长短句有云：「山下兰芽短浸溪，松间沙路净无泥。」白乐天诗云：「柳桥晴有絮，沙路润无泥。」「净」、「润」两字，当有能辨之者。
陈亦峰《白雨斋词话·巻六》：愈悲郁，愈豪放，愈忠厚，令我神往。', 'indent', 1415645038, '57b8fdc1df0eea006334ca15', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10103, '春江花月夜', NULL, 2554, 2, 7, 8, '张若虚', NULL, 10036, '57b9c218c4c971006148293b', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/29752/5072069.htm', '', '春江潮水连海平，海上明月共潮生。
滟滟随波千万里，何处春江无月明！
江流宛转绕芳甸，月照花林皆似霰。
空里流霜不觉飞，汀上白沙看不见。
江天一色无纤尘，皎皎空中孤月轮。
江畔何人初见月？江月何年初照人？
人生代代无穷已，江月年年望相似。
不知江月待何人，但见长江送流水。
白云一片去悠悠，青枫浦上不胜愁。
谁家今夜扁舟子？何处相思明月楼？
可怜楼上月徘徊，应照离人妆镜台。
玉户帘中卷不去，捣衣砧上拂还来。
此时相望不相闻，愿逐月华流照君。
鸿雁长飞光不度，鱼龙潜跃水成文。
昨夜闲潭梦落花，可怜春半不还家。
江水流春去欲尽，江潭落月复西斜。
斜月沉沉藏海雾，碣石潇湘无限路。
不知乘月几人归，落月摇情满江树。', '此诗共三十六句，每四句一换韵，以富有生活气息的清丽之笔，创造性地再现了江南春夜的景色，如同月光照耀下的万里长江画卷，同时寄寓着游子思归的离别相思之苦。诗篇意境空明，缠绵悱恻，洗净了六朝宫体的浓脂腻粉，词清语丽，韵调优美，脍炙人口，乃千古绝唱，素有「孤篇盖全唐」之誉。', '滟（yàn）滟：波光荡漾的样子。
芳甸（diàn）：芳草丰茂的原野。甸，郊外之地。
霰（xiàn）：天空中降落的白色不透明的小冰粒。形容月光下春花晶莹洁白。
流霜：飞霜，古人以为霜和雪一样，是从空中落下来的，所以叫流霜。在这里比喻月光皎洁，月色朦胧、流荡，所以不觉得有霜霰飞扬。
汀（tīng）：水边平地，小洲。
纤尘：微细的灰尘。
月轮：指月亮，因为月圆时象车轮，所以称为月轮。
穷已：穷尽。
望相似：又作「祇相似」、「秖相似」，「祇」、「秖」同「只（zhǐ）」。
但见：只见、仅见。
悠悠：渺茫、深远。
青枫浦上：青枫浦，地名。今湖南浏阳县境内有青枫浦。这里泛指游子所在的地方。暗用《楚辞·招魂》：「湛湛江水兮上有枫，目极千里兮伤春心。」浦上：水边。《九歌·河伯》：「送美人兮南浦。」因而此句隐含离别之意。
扁舟子：飘荡江湖的游子。扁舟，小舟。
明月楼：月夜下的闺楼。这里指闺中思妇。曹植《七哀诗》：「明月照高楼，流光正徘徊。上有愁思妇，悲叹有馀哀。」
月徘徊：指月光偏照闺楼，徘徊不去，令人不胜其相思之苦。徘徊，一作「裴回」。
离人：此处指思妇。
妆镜台：梳妆台。
玉户：形容楼阁华丽，以玉石镶嵌。
捣衣砧（zhēn）：捣衣石、捶布石。
相闻：互通音信。
逐：追随。
月华：月光。
文：同「纹」。
闲潭：幽静的水潭。
潇湘：湘江与潇水。
碣（jié）石、潇湘：一南一北，暗指路途遥远，相聚无望。
无限路：极言离人相距之远。
乘月：趁着月光。
摇情：激荡情思，犹言牵情。', '春天的江潮水势浩荡，与大海连成一片，一轮明月从海上升起，好像与潮水一起涌出来。
月光照耀着春江，随着波浪闪耀千万里，所有地方的春江都有明亮的月光。
江水曲曲折折地绕着花草丛生的原野流淌，月光照射着开遍鲜花的树林好像细密的雪珠在闪烁。
月色如霜，所以霜飞无从觉察。洲上的白沙和月色融合在一起，看不分明。
江水、天空成一色，没有一点微小灰尘，明亮的天空中只有一轮孤月高悬空中。
江边上什么人最初看见月亮，江上的月亮哪一年最初照耀着人？
人生一代代地无穷无尽，只有江上的月亮一年年地总是相像。
不知江上的月亮等待着什么人，只见长江不断地一直运输着流水。
游子像一片白雲缓缓地离去，只剩下思妇站在离别的青枫浦不胜忧愁。
哪家的游子今晚坐着小船在漂流？什么地方有人在明月照耀的楼上相思？
可怜楼上不停移动的月光，应该照耀着离人的梳妆台。
月光照进思妇的门帘，卷不走，照在她的捣衣砧上，拂不掉。
这时互相望着月亮可是互相听不到声音，我希望随着月光流去照耀着您。
鸿雁不停地飞翔，而不能飞出无边的月光；月照江面，鱼龙在水中跳跃，激起阵阵波纹。
昨天夜里梦见花落闲潭，可惜的是春天过了一半自己还不能回家。
江水带着春光将要流尽，水潭上的月亮又要西落。
斜月慢慢下沉，藏在海雾里，碣石与潇湘的离人距离无限遥远。
不知有几人能趁着月光回家，唯有那西落的月亮摇荡着离情，洒满了江边的树林。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e928fc6e67846a920e95e", "shortContent": "被闻一多先生誉为“诗中的诗，顶峰上的顶峰”（《宫体诗的自赎》）的《春江花月夜》，一千多年来使无数读者为之倾倒。一生仅留下两首诗的张若虚，也因这一首诗，“孤篇横绝，竟为大家”。\n诗篇题目就令人心驰神往。春、江、花、月、夜，这五种事物集中体现了人生最动人的良辰美景，构成了诱人探寻的奇妙的艺术境界。\n诗人入手擒题，一开篇便就题生发，勾勒出一幅春江月夜的壮丽画面：江潮连海，月共潮生。这里的“海”是虚指。江...", "authors": ["吴翠芬"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389abbb31680ae4c4b73b", "shortContent": "被闻一多先生誉为“诗中的诗，顶峰上的顶峰”（《宫体诗的自赎》）的《春江花月夜》，一千多年来使无数读者为之倾倒。一生仅留下两首诗的张若虚，也因这一首诗，“孤篇横绝，竟为大家”。\n\n诗篇题目就令人心驰神往。春、江、花、月、夜，这五种事物集中体现了人生最动人的良辰美景，构成了诱人探寻的奇妙的艺术境界。\n\n诗人入手擒题，一开篇便就题生发，勾勒出一幅春江月夜的壮丽画面：江潮连海，月共潮生。这里的“海”是虚指...", "authors": ["吴翠芬"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270317f0b9738b369b19d", "shortContent": "《春江花月夜》是唐代最美丽的诗歌之一。\n\n诗题原为隋炀帝所制，如炀帝《春江花月夜》：“暮江平不动，春花满正开。流波将月去，潮水带星来。”其诗要紧扣春、江、花、月、夜五字。在隋炀帝手中，此诗篇幅短小，还是乐府余风。到了张若虚手中，他却将这种宫体的体裁从内容到情感都大为拓展，终于以“孤篇横绝，竟为大家”。张若虚只留下了两首诗，但他在中国诗史上具有大家的地位，其原因就在这首《春江花月夜》。\n\n春江的潮水...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270547ccdb86c49f29244", "shortContent": "《春江花月夜》是唐代最美丽的诗歌之一。\n诗题原为隋炀帝所制，如炀帝《春江花月夜》：“暮江平不动。春花满正开。流波将月去。潮水带星来。”其诗要紧扣春、江、花、月、夜五字。在隋炀帝手中，此诗篇幅短小，还是乐府余风。到了张若虚手中，他却将这种宫体的体裁从内容到情感都大为拓展，终于以“孤篇横绝，竟为大家”。张若虚只留下了两首诗，但他在中国诗史上具有大家的地位，其原因就在这首《春江花月夜》。\n春江的潮水啊，...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6464506e7f27182da3524606", "bookTitle": "元明清词三百首鉴赏辞典", "articleId": "646b51585e6bb82b8cdff40f", "shortContent": "桃花夫人庙位于湖北黄陂县东。桃花夫人即春秋时息国国君的夫人息妫，据《左传·庄公十四年》记载，因蔡哀侯向楚文王称赞了息夫人的美貌，楚文王便灭息国并掳息夫人进了楚宫，后来息夫人虽在楚国生育二子，但始终未开口讲话。楚王追问其故，答曰：“吾一妇人而事二夫，纵弗能死，其又奚言？”这一凄苦哀婉的故事，历来有许多文人骚客以各种心态谈论评议过，到了史承谦的时代，早已不是什么新鲜的话题，然而词人以自身独特的生活经历...", "authors": ["戴元初", "承剑芬"], "pressName": "上海辞书出版社"}, {"bookId": "6464506e7f27182da3524606", "bookTitle": "元明清词三百首鉴赏辞典", "articleId": "646b6f325b7b0d4f452d89d9", "shortContent": "本词以刚健质朴的手法，表达了东走日本的秋瑾欲与同志拯救危难中的祖国的巨大爱国热情，并以此为契机，表达了她立志作一个女中豪杰的不凡的人生目标。\n\n上片主要表达她将生命献给拯救祖国事业的无比决心。首韵大笔振起，抒发她对于危机中的祖国的一片赤子深情。她不仅为它“感不禁”，即像一般有爱国情怀的同胞一样心念系之，扼腕叹息甚至于肝肠火热，而且直接起来行动，为拯救祖国危亡而远赴海外，寻找救国的真理和愿意救国的同...", "authors": ["邓红梅"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f2be9902ee364cc8a20d4", "shortContent": "被闻一多先生誉为“诗中的诗，顶峰上的顶峰”（《宫体诗的自赎》）的《春江花月夜》，一千多年来使无数读者为之倾倒。一生仅留下两首诗的张若虚，也因这一首诗，“孤篇横绝，竟为大家”。\n诗篇题目就令人心驰神往。春、江、花、月、夜，这五种事物集中体现了人生最动人的良辰美景，构成了诱人探寻的奇妙的艺术境界。\n诗人入手擒题，一开篇便就题生发，勾勒出一幅春江月夜的壮丽画面：江潮连海，月共潮生。这里的“海”是虚指。江...", "authors": ["吴翠芬"], "pressName": "上海辞书出版社"}, {"bookId": "645fc22c5e6bb82b8caff682", "bookTitle": "历代咏春诗鉴赏：春江花月夜", "articleId": "6472f5b87f27182da38f784c", "shortContent": "被闻一多先生誉为“诗中的诗，顶峰上的顶峰”（《宫体诗的自赎》）的《春江花月夜》，一千多年来使无数读者为之倾倒。一生仅留下两首诗的张若虚，也因这一首诗，“孤篇横绝，竟为大家”。\n\n诗篇题目就令人心驰神往。春、江、花、月、夜，这五种事物集中体现了人生最动人的良辰美景，构成了诱人探寻的奇妙的艺术境界。\n\n诗人入手擒题，一开篇便就题生发，勾勒出一幅春江月夜的壮丽画面：江潮连海，月共潮生。这里的“海”是虚指...", "authors": ["吴翠芬"], "pressName": "上海辞书出版社"}]', '', 'center', 1415645570, '57adcb9d1532bc0061717051', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10104, '七步诗', NULL, 604, 163, 1, 3, '曹植', NULL, 10037, '57b8eb6a79bc44005b9e1bf7', '三国', 'shi', '诗', 'http://baike.baidu.com/subview/72392/17798544.htm', '', '煮豆持作羹，漉菽以为汁。
萁在釜下燃，豆在釜中泣。
本自同根生，相煎何太急？', '《七步诗》据传是三国时期魏国著名文人曹植的名篇。最早见于《世说新语》的“煮豆持作羹，漉菽以为汁。萁在釜下燃，豆在釜中泣。本自同根生，相煎何太急？”，后由《三国演义》改编为“煮豆燃豆萁，豆在釜中泣。本是同根生，相煎何太急？”。
这首诗用同根而生的萁和豆来比喻同父共母的兄弟，用萁煎其豆来比喻同胞骨肉的哥哥残害弟弟，生动形象、深入浅出地反映了封建统治集团内部的残酷斗争和诗人自身处境艰难，沉郁愤激的感情。同时也反映了政治与人性之间的矛盾和冲击。', '豆萁：大豆的豆秸，豆秸。
釜中：锅中。釜，锅。
同根生：都是一家人。
太急：急迫，着急。', '锅里煮着豆子，豆秸在锅底下燃烧，豆子在锅里面哭泣。豆子和豆秸本来是同一条根上生长出来的，豆秸怎能这样急迫地煎熬豆子呢！', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecc9e5914587d02f599a4", "shortContent": "谢灵运曾说：“天下才有一石，曹子建独占八斗，我得一斗，天下共分一斗。”（《释常谈》）刘勰的《文心雕龙·才略》中也说：“子建思捷而才俊，诗丽而表逸。”明代王世贞的《艺苑卮言》也说：“子建天才流丽，虽誉冠千古，而实避父兄，何以故？才太高，辞太华。”可见前人都指出了曹植才华出众，禀赋异常的特点，而最能表现其才华的例子就是这首《七步诗》。\n据《世说新语·文学》中说，曹丕做了皇帝以后，对才华横溢的胞弟曹植一...", "authors": ["王镇远"], "pressName": "上海辞书出版社"}, {"bookId": "64605c895b7b0d4f45fe6e6e", "bookTitle": "三曹诗文鉴赏辞典", "articleId": "646e0c327f27182da37c249a", "shortContent": "谢灵运曾说：“天下才有一石，曹子建独占八斗，我得一斗，天下共分一斗。”（《释常谈》）刘勰的《文心雕龙·才略》中也说：“子建思捷而才俊，诗丽而表逸。”明代王世贞的《艺苑卮言》也说：“子建天才流丽，虽誉冠千古，而实逊父兄，何以故？材太高，辞太华。”可见前人都指出了曹植才华出众、禀赋异常的特点，而最能表现其才华的例子就是这首《七步诗》。\n据《世说新语·文学》中说，曹丕做了皇帝以后，对才华横溢的胞弟曹植一...", "authors": ["王镇远"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f672930675327e1b70a44", "shortContent": "谢灵运曾说:“天下才有一石，曹子建独占八斗，我得一斗，天下共分 一 斗 。”(《释 常 谈 》)刘勰的《文心雕龙 · 才略 》中也说 :“子建思捷而才俊 ，诗丽而 表逸 。”明代王世贞的《艺苑卮言》也说 :“子建天才流丽 ，虽誉冠千古，而实避父兄，何以故?才太高，辞太华。”可见前人都指出了曹植才华出众，禀赋异常的特点，而最能表现其才华的例子就是这首《七步诗》。\n\n据《世说新语·文学》中说，曹丕做了...", "authors": ["王镇远"], "pressName": "上海辞书出版社"}]', '王世贞《艺苑卮言》：子建天才流丽，虽誉冠千古，而实避父兄，何以故？才太高，辞太华。
郭沫若：站在豆的一方面说，固然可以感觉到萁的煎迫未免为火烧火；如果站在萁一方面说，不又是富于牺牲的精神的表现吗？', 'center', 1415645618, '57b8ea590a2b58005c91b7b7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (31459, '洞仙歌 · 谢杨成之寄梅', NULL, 1, 891, 0, 2, '李俊民', NULL, 10838, '5858e5e38e450a006c7f7cd2', '元', 'ci', '词', NULL, NULL, '陇头潇洒，辜负寻芳眼。浪蕊浮花问名懒。纵看看驿使、带得春来，只恐怕，绿叶成阴子满。
暗香无恙否，月落参横，惆怅罗浮梦魂短。赖故人情重、不减西湖，花上月、分我黄昏一半。更选甚、南枝与北枝，是一种春风、待争寒暖。', NULL, NULL, NULL, NULL, NULL, 'indent', 1512670226, '585cdaaa1b69e6006cc907e6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10118, '如梦令', NULL, 247, 395, 2, 1, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', 'http://baike.baidu.com/view/4196632.htm', '', '正是辘轳金井，满砌落花红冷。蓦地一相逢，心事眼波难定。谁省，谁省，从此簟纹灯影。', '此词描写作者与佳人偶遇，在古代男女授受不亲的陈规下，一见钟情所带来的冲击无法想象。然而惊鸿一瞥的美好情感转而制造了更多的内心纷扰，对方的心思无法琢磨，未来的不可测又添上了一份恐慌，于是，深宵的青灯旁、孤枕畔，又多了一个辗转反侧的不眠人。', '辘轳：井上汲水的工具。
砌：台阶。
蓦地：突然地。
省（xǐng）：明白。', '天亮了，井台上响起了辘轳声。一夜风雨，满阶落花，凋零中透出一丝冷意。在这样一个清晨，“我”和她蓦然相逢。“我”对她一见钟情，却难以明了她迷离的眼波背后暗藏的心事。谁能明白？谁能明白呢？从此以后，无论是在簟席上辗转反侧、孤枕难眠之时，还是独对孤灯、辗转徘徊之际，我都会想念她。', '[{"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3ec26cbf3417f09180", "shortContent": "词写一见钟情的场景。落花时节，辘轳声中，蓦然相逢，秋波一转，便情迷意乱，陷入相思苦恋之中.夜夜萦怀难眠。“新系青丝百尺绳，心在君家辘轳上。我心皎洁君不知，辘轳一转一惆怅”（顾况《短歌行》）。自己虽有意，却不知晓对方是否有情，这不免让人有些惆怅。", "authors": [], "pressName": "崇文书局"}]', '顾贞观：所为乐府小令，婉丽凄清，使读者哀乐不知所主。', 'indent', 1362513653, '57b2b79aa341310060fde0d2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10119, '金缕曲 · 赠梁汾', NULL, 370, 395, 6, 2, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', 'http://baike.baidu.com/view/3660689.htm', '', '德也狂生耳。偶然间、缁尘京国，乌衣门第。有酒惟浇赵州土，谁会成生此意。不信道、遂成知己。青眼高歌俱未老，向尊前、拭尽英雄泪。君不见，月如水。
共君此夜须沉醉。且由他、蛾眉谣诼，古今同忌。身世悠悠何足问，冷笑置之而已。寻思起、从头翻悔。一日心期千劫在，后身缘、恐结他生里。然诺重，君须记。', '此词作于康熙十五年（西元一六七六年），亦是纳兰容若的成名之作。其时容若初识郁郁不得志的顾梁汾，觉得相见恨晚。
「德也狂生耳」，起句奇兀，使人陡然一惊；因为纳兰容若的父亲明珠，是当时权倾朝野的宰辅。容若风华正茂，文武双全，在他面前正铺设着一条荣华富贵的坦途。然而，他竟劈头自称「狂生」，而且还带着颇为不屑的语气，这一下就抓住了读者的心，使人不得不注意品味。
「偶然间，缁尘京国，乌衣门第。容若化用谢玄晖「谁能久京洛，缁尘染素衣」的诗意，说自己生长在京师的富贵人家，蒙受尘世的污浊。「偶然间」三字。表明他并不希罕金粉世家繁华喧嚣的生活。在词的开头，他就坦率地把自己鄙薄富贵家庭的心境，告诉给顾贞观，是希望出身寒素的朋友们理解他，不要把他看成是一般的贵介公子。
「有酒惟浇赵州土」。原是唐代诗人李长吉的诗句：「买丝绣作平原君，有酒惟浇赵州土。」平原君即战国时代赵国的公子赵胜，此人平生喜欢结纳宾客。长吉写这两句诗，对那些能够赏识贤士的人表示怀念。他举起酒杯，浇向赵州，觉得茫茫宇内，惟独平原君值得景仰。容若径用李诗入词，同样是表示对爱惜人才者的敬佩。当然，他和长吉的心情不尽相同。长吉怀才不遇，攀附无门；容若生长名门，青云有路。但是，他从顾梁汾、吴汉槎诸人的遭遇里，深深感到社会的不平，感到人才总是无法逃脱遭受排挤的厄运，因而忧思重重，满怀悲愤。
「谁会成生此意」，透露出孤独落寞的悲哀。他的失望、彷徨、牢骚之情，统统包含在这里面。
「不信道，遂成知己」。骤然看来，在「不信道」之後，又加上「遂」字，显得有点累赘，但重复强调意外之感，是为了表达得友的狂喜。这几句，笔势驰骤，极尽腾挪变化之妙。
「青眼高歌俱未老，向尊前，拭尽英雄泪。」青眼是高兴的眼色，不过，在举杯痛饮之馀，又不禁涕泪滂沱。英雄失路，惺惺相惜，得友的喜悦、落拓的悲哀，一齐涌上心头。辛稼轩曾有句云：「倩何人唤取，红巾翠袖，揾英雄泪！」纳兰心情，与此相类。不过，辛词「揾」字比较含蓄，纳兰用「拭尽」一语，却是淋漓尽致地宣泄情感。这几句，诗人把歌哭笑啼交错在一起，比辛词显得更鲜明更奔放。
「君不见，月如水」以此景作结。月儿皎洁，凉浸浸的，似是映衬着他们悲凉的情怀，又似是他们纯洁友谊的见证。即景即情，尽在不言中。
「共君此夜须沉醉。」这里的「须」字很值得玩味。它表明，词人要有意识地使自己神经麻木。从写法上看，此句与杜甫的名句「白日放歌须纵酒」也颇相似，但意境大不相同。「纵酒」未必大醉，「沉醉」却是醉得不省人事。为什么必须烂醉如泥？下面跟着作答。「且由他，蛾眉谣诼，古今同忌。」屈原说过：「众女嫉余之蛾眉兮，谣诼谓余以善淫。」在纳兰容若看来，古往今来，有才识之士被排斥不用者多如牛毛，顾梁汾等受到不公的待遇也自不可避免。不合理的现实既已无法改变，他便劝慰好友，大家懒得去管，一醉了事。这种一醉解千愁的作法，固然是逃避现实的表现，但诗人冷峭的情绪，乃是愤怒与消极的混合物。
「身世悠悠何足问，冷笑置之而已」。从梁汾等今古才人的遭遇中，词人想到自己。在污浊的社会中，过去的生涯，毫无意趣，将来的命运，也不值一哂，因而他发出了「寻思起，从头翻悔」的感叹。在词的开头，词人已透露出他对门阀出身的不屑，这里再一次申明，是强调他和梁汾有着同样的烦恼，对现实有着同样的认识，他和梁汾一起承受着不合理社会给予的压力。在这里，通过词人对朋友安慰体贴相濡以沫的态度，我们也看到了他对现实生活的不满和激忿。
「一日心期千劫在，後生缘，恐结他生裏。」在激动之馀，纳兰把笔锋拉回，用沉着坚定的调子抒写他对友情的珍惜。在不期然得遇知己的时刻。他郑重表示，一旦倾心相许，友谊便地久天长，可以经历千年万载。同时，彼此相见恨晚，衹好期望来世补足今生错过的时间。用不着剖析，这番誓言，灼热如火。结句「然诺重，君须记」。再三叮咛，强烈地表达与梁汾世世为友的愿望。
纳兰着眼于传情，直抒胸臆，但也注意顺手拈来一二景语，约略点染。这首词因情写景，情景相生，收到了形象生动境界隽永的艺术效果。', '梁汾：指纳兰容若的朋友顾梁汾。清康熙十五年（西元一六七六年）与容若相识，从此交契，直至容若病殁。
德：作者自称。
淄尘：黑尘，喻污垢。此处作动词用，指混迹。淄，通「缁」，黑色。
浇：浇酒祭祀。
会：理解。
不信道、遂成知己：万万没有想到，今天竟然遇到了知己。
青眼：契重之眼光，此指青春年少。
尊：同「樽」。
蛾眉谣诼：又作娥眉。《楚辞·离骚》：「众女嫉余之蛾眉兮，謡諑谓余以善淫。」东汉·王叔师注：「謡，谓毁也。諑，犹譖也。」宋·洪练塘《〈楚辞〉补注》：「言众女竞为謡言，以譖愬我。」
悠悠：遥远而不定貌。
心期：以心相许，情投意合。
后身缘：来生情缘。
然诺重：指守信誉，不食言。', '我原本也是个狂妄的小子，我在京城混迹于官场，这不过是因为出身于高贵门第和命运的偶然安排罢了。我真心仰慕平原君的广结贤士，希望能有赵国平原君那样招贤纳士的人来善待天下贤德才士，可是却没有谁会理解我的这片心意。万万没有想到，今天竟然遇到了您这位知己。今天，趁我们还不算老，擦去感伤的眼泪，纵酒高歌，把精神振作起来。
今天我们一定要开怀畅饮，一醉方休。从古到今，才幹出众、品行端正的人遭受谣言中伤，这都是常有的事，姑且由他去吧。人生岁月悠悠，难免遭受点挫折苦恼，这些都没必要放在心上，思过之後冷笑一声放在一边就完事儿了。若总是耿耿于怀，那么从人生一开始就错了。今天我们一朝以心相许，成为知己，他日即使经历千万劫难，我们的友情也要依然长存。这后半生的缘分，恐怕要到来世也难以补足。这个诺言是很沉重的，您一定要牢牢记在心里。', '[{"bookId": "60fc157134bfda01e0e91549", "bookTitle": "元明清词鉴赏辞典（新一版）", "articleId": "610e865f0f8fda556505230b", "shortContent": "本篇题为“赠梁汾”，梁汾是词人顾贞观的号。据载，顾贞观读了纳兰性德这首词后，也写了一首《金缕曲》，题为“酬容若见赠”，并在纳兰性德的原作后题辞云：“岁丙辰，容若年二十有二，乃一见即恨识余之晚。阅数日，填此曲为余题照。极感其意，而私讶他生再结语殊不祥，何意竟为乙丑五月之谶也。伤哉！”（按：纳兰性德卒于康熙二十四年乙丑五月）\n由此可知，纳兰性德的这首《金缕曲》作于康熙十五年丙辰（1676）作者二十二岁...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3de6f69b71e93f604a", "shortContent": "词作于康熙十五年（1676）。顾贞观和词有附跋：“岁丙辰，容若年二十有二，乃一见即恨识余之晚，阅数日，填此曲为余题照。”（《弹指词》卷下）。是词为容若成名之作，慷慨淋漓，跌宕生姿，与他词之凄婉缠绵颇为不同，将重交谊、笃友情之执著展露无遗。故傅庚生以为“其率真无饰，至令人惊绝。率真则疏快而不滞，不滞则见赋于天者，可以显现而无遗，生香天色，此其是已”（《中国文学欣赏举隅》）。上片言风尘京洛，乍逢知己，...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3de6f69b71e93f604b", "shortContent": "康熙十五年（1676）末，顾贞观填写两首《金缕曲》，寄予吴汉槎，容若见之，颇为感激，遂挺身而出，允为奔走营救，使吴汉槎得以生人榆关。是词即作于此间，说他定把生还吴汉槎，作为眼下急切之事，也安慰顾贞观不要因吴季子一事心情过于沉重，不要因外界的纷扰影响两人的友情。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3f7ccdb86c49f28f4d", "shortContent": "词当作于康熙二十三年（1684）。容若此间曾致书顾贞观，多有感喟：“从前壮志，都已隳尽。昔人言，身后名不如生前一杯酒，此言大是。弟是以甚慕魏公子之饮醇酒、近妇人也。沦落之余，方欲葬身柔乡，不知安得如鄙人之愿否？”是词情绪之低回，及逃身于温柔之乡的愿望，都十分明显。词中说他曾经也豪情壮志，企盼多一番事业，然后功成身退，留名青史。只可惜这样的事情从古到今都没有几个例子。眼看一年年韶华虚度，青春即将耗尽...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6464506e7f27182da3524606", "bookTitle": "元明清词三百首鉴赏辞典", "articleId": "646b4ba25e6bb82b8cdfd65d", "shortContent": "本篇题为“赠梁汾”，梁汾是词人顾贞观的号。据载，顾贞观读了纳兰性德这首词后，也写了一首《金缕曲》，题为“酬容若见赠”，并在纳兰性德的原作后题辞云：“岁丙辰，容若年二十有二，乃一见即恨识余之晚。阅数日，填此曲为余题照。极感其意，而私讶他生再结语殊不祥，何意竟为乙丑五月之谶也。伤哉！”（按：纳兰性德卒于康熙二十四年乙丑五月）\n\n由此可知，纳兰性德的这首《金缕曲》作于康熙十五年丙辰（1676）作者二十二...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}]', '', 'indent', 1362514081, '57b8f48bdf0eea0063349188', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10120, '长相思·山一程水一程', NULL, 1490, 395, 2, 9, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', 'http://baike.baidu.com/view/4210536.htm', '', '山一程，水一程，身向榆关那畔行，夜深千帐灯。
风一更，雪一更，聒碎乡心梦不成，故园无此声。', '此词描写将士在外对故乡的思念，抒露着情思深苦的绵长心境。全词纯用自然真切、简朴清爽的白描语句，写得天然浑成，毫无雕琢之处，却格外真切感人。', '长相思：唐教坊曲，双翅小令。又名《双红豆》。
程：道路、路程，山一程、水一程，即山长水远。
榆关：即今山海关，在今河北秦皇岛东北；那畔：即山海关的另一边，指身处关外。
千帐灯：皇帝出巡临时住宿的行帐的灯火。千帐言军营之多。
更：旧时一夜分五更，每更大约两小时。风一更、雪一更，即言整夜风雪交加也。
聒（guō）：声音嘈杂，这里指风雪声。
故园：故乡，这里指北京；此声：指风雪交加的声音。', '将士们不辞辛苦地跋山涉水，马不停蹄地向着山海关进发。夜已经深了，千万个帐篷里都点起了灯。
外面正刮着风、下着雪，惊醒了睡梦中的将士们，勾起了他们对故乡的思念，故乡是多么的温暖宁静呀，哪有这般狂风呼啸、雪花乱舞的聒噪之声。', '[{"bookId": "60fc157134bfda01e0e91549", "bookTitle": "元明清词鉴赏辞典（新一版）", "articleId": "610e865e5914587d02f4afab", "shortContent": "历来论纳兰性德的词，多推许其小令，对其长调，则评价不高。较有代表性的评论如谭献说：“容若（纳兰性德的字）长调多不协律，小令则格高韵远，极缠绵婉约之致，能使残唐坠绪绝而复续。”（《箧中词》）这样说，并不意味着纳兰性德的长调中无一佳作，但总的说来，其小令中的佳作更多，艺术成就更高，却是不争的事实。而在他众多的短篇佳什中，这首《长相思》则又卓然独立、自具特色。\n这首小词作于康熙二十一年（1682）二月，...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3ec26cbf3417f0918f", "shortContent": "康熙二十一年（1682）二月，容若扈驾东巡，出山海关而有是作。上片写跋涉行军与途中驻扎，颇多无奈情绪，仿佛看见了词人疲惫的身影。下片写夜来风雪交加，搅碎了乡梦，倍觉惆怅。词作语言淳朴而意味深长，取景宏阔而对照鲜明。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3fc26cbf3417f091a2", "shortContent": "此词与前首同调之作当为同时而作，但其意绪却与《浣溪沙·姜女祠》更为接近，旨在抒写兴亡之叹、古今之悲。其取景亦自苍茫辽阔，所谓野火拂云、西风夜哭等，无不显得沉重且压抑。词人最后问道：秦始皇费尽心机，劳民伤财，修筑了这一道屏障。如今来看，这长城究竟是为谁而修筑的呢？这一问，问得惊心动魄。而明清易代，在他眼里，也不过是山海几经翻覆中的一次而已，似乎没有特别之处。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e41c305cf0801816c5b", "shortContent": "容若此作，虽无深刻意义，但其凄婉格调与主导风格依然保持了一致，结尾两句也颇耐咀嚼。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e41c305cf0801816c5c", "shortContent": "接到情人来信，灯下翻来覆去，一直读到了拂晓，将燕子折腾得一夜都无法安定。黎明时分，终于进入了梦乡，梦见情人笑嘻嘻地回来了。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e41e6f69b71e93f6068", "shortContent": "词写梦醒时分的惆怅。梦中正要与佳人相会，却被打落在窗棂上的几滴秋雨惊醒。西风卷地而来，大雁掠东檐去，捣衣声中，离人孤苦无告。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e419761253910e9025e", "shortContent": "词人来到废园，四处衰红败绿，枯井布满苔藓，惟有飞来飞去、叽叽喳喳的鸟雀，才给这片荒芜的园地带来一丝生机，这让他有韶华如梦、似水流年之感。柳絮飞舞，梅子青如豆，当日与友人的约定也已成空。他想把自己的感触写给对方，却又不知从何说起，断角残垣中，只好把一腔落寞寄与斜阳。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e419761253910e9025f", "shortContent": "词写情人分离时的复杂心情。人生短暂，而快乐的日子尤为紧促。倘若情动于中，有所牵挂，更感觉时光如梭。似乎是刚刚聚首，就又到了匆匆话别的时刻。炉烟散尽，残灯将灭，已经没有停留的借口。执手相看，无语凝噎，泪眼蒙昽。既然有缘无分，当初真不该投人款款深情，致使胶漆难分。更令人心悸的是，从此人去楼空，惟有窗间明月与扶疏的柳条添悲惹绪，满腹的惆怅又能向谁说？", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e42f2af4e09d55b64b2", "shortContent": "词写秋日离情。秋色已深，天气转凉，伫立池塘旁，见亭亭荷叶下鸳鸯成双，心中自是惆怅。霜冷风急，燕子也要还乡了，而自己惟有独立斜阳，默默无语，暗念故乡。仔细想来，竟然不知何故而羁留他方。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e42f2af4e09d55b64b4", "shortContent": "词为怀人之作。去年上已之日，曾与欢郎一起度过了一个美妙的节日。今年眼看芳草凄凄，春意阑珊，她一天天数着日子，一直数到上已节的前一天，去年的双燕都飞还了，而情郎还不知在何方。落花飘零之中，忆及前事，不禁粉泪盈盈。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6464506e7f27182da3524606", "bookTitle": "元明清词三百首鉴赏辞典", "articleId": "646b497445e4710056dfda51", "shortContent": "历来论纳兰性德的词，多推许其小令，对其长调，则评价不高。较有代表性的评论如谭献说：“容若（纳兰性德的字）长调多不协律，小令则格高韵远，极缠绵婉约之致，能使残唐坠绪绝而复续。”（《箧中词》）这样说，并不意味着纳兰性德的长调中无一佳作，但总的说来，其小令中的佳作更多，艺术成就更高，却是不争的事实。而在他众多的短篇佳什中，这首《长相思》则又卓然独立、自具特色。\n\n这首小词作于康熙二十一年（1682）二月...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}]', '', 'indent', 1415645693, '57b8ecc0d342d3005ac6b17d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10121, '木兰词 · 拟古决绝词柬友', NULL, 1765, 395, 2, 2, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', 'http://baike.baidu.com/view/9661253.htm', '', '人生若只如初见，何事秋风悲画扇。
等闲变却故人心，却道故心人易变。
骊山语罢清宵半，泪雨霖铃终不怨。
何如薄幸锦衣郎，比翼连枝当日愿。', '此词描写了一个为情所伤的女子和伤害她的男子坚决分手的情景，借用班婕妤被弃以及唐玄宗与杨贵妃的爱情悲剧的典故，通过「秋扇」「骊山语」「雨霖铃」「比翼连枝」这些意象，营造了一种幽怨、凄楚、悲凉的意境，抒写了女子被男子抛弃的幽怨之情。', '木兰词：实为《玉楼春》，错题为《木兰词》乃为前人误刻所误导。按《花间集》载《木兰花》、《玉楼春》两调，其七字八句者为《玉楼春》体，《木兰花》则韦词、毛词、魏词共三体，从无与《玉楼春》同者。自《尊前集》误刻以后，宋词相沿，率多混填。
柬：给……信札。
「何事秋风悲画扇」句：用汉朝班婕妤被弃的典故。班婕妤为汉成帝妃，被赵飞燕谗害，退居冷宫，后有诗《怨歌行》，以秋扇闲置为喻抒发被弃之怨情。南朝梁·刘孝绰《班婕妤怨》诗又点明「妾身似秋扇」，后遂以秋扇见捐喻女子被弃。这里是说本应当相亲相爱，但却成了相离相弃。唐代诗人王龙标作《长信秋词五首》来怜惜她。
故人：指情人。
却道故心人易变：娱园本作「却道故人心易变」。看似白话，其为用典，出处就在南朝齐国山水诗人谢玄晖《同王主簿怨情》后两句「故人心尚永，故心人不见」。汪元治本《纳兰词》误刻后句「故心人」为「故人心」，此误常为现代选本承袭。
「骊（lí）山语罢清宵半，泪雨霖铃终不怨」句：用唐明皇与杨玉环之典。《太真外传》载，唐明皇与杨玉环曾于七月七日夜，在骊山华清宫长生殿里盟誓，愿世世为夫妻。白乐天《长恨歌》：「在天愿作比翼鸟，在地愿作连理枝。」对此作了生动的描写。后安史乱起，明皇入蜀，于马嵬坡赐死杨玉环。杨死前云：「妾诚负国恩，死无恨矣！」又，明皇此后于途中闻雨声、铃声而悲伤，遂作《雨霖铃》曲以寄哀思。
薄幸：薄情，“幸”为“倖”的简化正字。
锦衣郎：指唐明皇。
「何如薄幸锦衣郎，比翼连枝当日愿。」句：化用唐李义山《马嵬》诗中「如何四纪为天子，不及卢家有莫愁」之句意。', '与意中人相处应当总像刚刚相识的时候，是那样地甜蜜，那样地温馨，那样地深情和快乐。但你我本应当相亲相爱，却为何成了今日的相离相弃？如今轻易地变了心，你却反而说情人间就是容易变心的。
我与你就像唐明皇与杨玉环那样，在长生殿起过生死不相离的誓言，却又最终作决绝之别，即使如此，也不生怨。但你又怎比得上当年的唐明皇呢，他总还是与杨玉环有过比翼鸟、连理枝的誓愿。', '[{"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3de6f69b71e93f604c", "shortContent": "词当是写实，记容若移植栽柳的过程与感受，与所谓相思无关。所用故实，如章台、娇眼等，只是绾合柳树而已，并无隐情。上片说春日迟迟之时，词人从他处移来一株柳树，植于庭院之中，想象其柳絮飞舞之日，必另是一番景色。下片说等到百尺垂垂，柳条依依，这柳树必将给回廊带来几分阴凉，再有黄莺驻留，更增添无数春色。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3de6f69b71e93f604d", "shortContent": "词当是写实，记容若移植栽柳的过程与感受，与所谓相思无关。所用故实，如章台、娇眼等，只是绾合柳树而已，并无隐情。上片说春日迟迟之时，词人从他处移来一株柳树，植于庭院之中，想象其柳絮飞舞之日，必另是一番景色。下片说等到百尺垂垂，柳条依依，这柳树必将给回廊带来几分阴凉，再有黄莺驻留，更增添无数春色。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3de6f69b71e93f604e", "shortContent": "词咏桃花。上片说夜来风雨，清晨莺啼燕啭，桃花依旧笑春风。下片写夕阳中，山郭下，桃花片片，飘向亭皋，更使春光无限。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3fc26cbf3417f091b3", "shortContent": "康熙二十一年（1682）秋，容若赴梭龙，归后友人绘有《楞伽山人出塞图》。吴雯与姜宸英等均有题画之作，前者如出关塞草白，立马独伤心。秋风吹雁影，天际正茫茫。岂念衣裳薄，还惊鬓发苍。金闺千里月，中夜拂流黄。”此词为容若自题之作，记录他对此次行役的感受。千里奔波，长亭短亭，带来的是劳顿与无奈；无穷山色，给人的感受是冷清凄凉；无边往事，唤醒的是英雄之梦，即对曾经发生的战争的意义表示质疑。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e409761253910e9024c", "shortContent": "此词虽传诵甚广，但历来似乎多有误读。对于它的主旨，向来有两种说法。一种是论交友之道当始终不渝，因为有一刻本的副题明确注明“柬友”两字。友情的始终如一与爱情的始终不渝，两者确实有相同之处，但“柬友”之“友”，并非一定要理解为友情，恐怕理解为友人更为恰当。那也就是说，这首词可能是用来劝慰友人的，如劝慰他在某些方面，诸如爱情等问题上不可过于执拗。另一种说法认为是在以女子的口吻驳斥薄情郎，从词中所用典故及...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e41c305cf0801816c65", "shortContent": "词写冬日佳人之相思。冬日里雪花飞舞飘扬，不断从稀疏的帘幕中窜人房中，轻盈地降落在红锦地毯之上。佳人一身大氅，将自己紧紧包裹，却似乎也难以抵御寒凉的侵袭。惟有寄希望以温馨的香梦，来挨过这漫长的严冬。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e41e6f69b71e93f606c", "shortContent": "此首与前篇意旨相近，当为同时同题之作。上片说夜来一阵风雪，寒柳饱受摧残，但枝干叶枯而丝未断，只要一气尚存，面对冰霜严寒，仅仅蹙柳叶眉而已。下片说明年春风吹来，依旧舞动纤腰，以葱葱绿荫与红泥亭子相映成趣，系住荡子斑骓，免除闺中寂寞。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e41e6f69b71e93f6075", "shortContent": "词写刺绣女儿的春情幽思，灵气勃发。傍晚时候，柳絮漫天飞舞。微风轻轻拂过池塘，使画楼的倒影也随之荡漾。楼上刺绣的女孩，心有所思，柔肠百转，情思一缕，幽幽难言。风定花犹落，片片人绣床。也许该梳妆打扮一下了，但梳妆后给谁欣赏呢？看看池塘并行的鸟儿，不由得痴了。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e419761253910e9026d", "shortContent": "这是词人回忆往日情事时的感喟，如脱口而出，洞彻心扉。时过境迁，多年以后再慢慢寻思，词人发现，所谓的温馨甜蜜，其实也无非是日常生活中的琐碎小事，一觞一饭，一颦一笑，诸如此类而已。只要是心意相通，就能感受到幸福。可惜这样的日子终不能长久，分别已经十年，往事还是不断涌上心头。残月、飞絮，当日的点点滴滴，“一处所，一物候”，总勾起伤心的回忆。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e42f2af4e09d55b64c0", "shortContent": "是词为人从《西余蒋氏宗谱》卷十六辑出，为容若与蒋景祁酬唱之作。据赵秀亭考证，“不向朱门和宋诗”涉及当时“有关清初文事变局，为全词关键。时渔洋‘«衍波》以后禁不作词’（景祁《刻瑶华集述》），以文场尊主身份鄙弃作词，甚至‘绝口不谈’（顾贞观《栩园词弃稿序》），转而专倡宋诗，高唱4神韵’，以应清廷‘盛世元音’之需，遂大得圣祖推赏，群僚响应。唯成德‘性喜诗馀，禁之难止’，不为所动；景祁亦‘再进再黜，然后赋...", "authors": [], "pressName": "崇文书局"}]', '', 'indent', 1413387057, '57b8eaf28ac2470062df147d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10122, '忆秦娥', NULL, 457, 1052, 4, 4, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'ci', '词', 'http://baike.baidu.com/view/2494031.htm', '', '箫声咽，秦娥梦断秦楼月。秦楼月，年年柳色，灞陵伤别。
乐游原上清秋节，咸阳古道音尘绝。音尘绝，西风残照，汉家陵阙。', '此词为唐五代词中的最为脍炙人口的作品之一，此词上阕伤别，下阕伤逝。两宋之交邵博《邵氏闻见后录》始称之为李白之作。南宋·黄叔旸《唐宋诸贤绝妙词选》亦录于李白名下。此处暂且将作者标记为李白，但此词作者是否为李白，暂且存疑。因其双调格式过于成熟，明代以来已屡有质疑者，作者至早为晚唐五代，我国著名的唐诗研究和中国古代文学理论研究专家詹锳认为是温庭筠所作，也可能是佚名作者。
此词双阕四十六字，伤今怀古，托兴深远。上阕以月下箫声凄咽引起，已见当年繁华梦断不堪回首。次三句，更自月色外，添出柳色，添出别情，将情景融为一片，想见惨淡迷离之概。下阕揭响云汉，摹写当年极盛之时与地。而「咸阳古道」一句，骤落千丈，凄动心目。再续「音尘绝」一句，悲感愈深。「西风」八字，只写境界，兴衰之感都寓其中。其气魄之雄伟，实冠今古。古人对此词评价很高，誉之为「百代词曲之祖」。', '箫：一种竹制的管乐器。
咽：呜咽，形容箫管吹出的曲调低沉而悲凉，呜呜咽咽如泣如诉。
梦断：梦被打断，即梦醒。
灞陵：在今陕西省西安市东，是汉文帝的陵墓所在地。当地有一座桥，为通往华北、东北和东南各地必经之处。《三辅黄图·卷六》：「文帝灞陵，在长安城东七十里。……跨水作桥。汉人送客至此桥，折柳送别。」
伤别：为别离而伤心。
乐游原：又叫「乐游园」，在长安东南郊，是汉宣帝乐游苑的故址，其地势较高，可俯视长安城，在唐代是游览之地。
清秋节：指农历九月九日的重阳节，是当时人们重阳登高的节日。
咸阳：秦都，在长安西北数百里，是汉唐时期由京城往西北从军、经商的要道。古咸阳在今陕西省咸阳市东二十里。唐人常以咸阳代指长安。
咸阳古道：长安道。
音尘：一般指消息，这里是指车行走时发出的声音和扬起的尘土。
残照：指落日的光辉。
汉家：汉朝。
陵阙：皇帝的坟墓和宫殿。', '玉箫的声音悲凉呜咽，秦娥从梦中惊醒时，秦家的楼上正挂着一弦明月。秦家楼上的下弦月，每一年桥边青青的柳色，都印染着灞陵桥上的凄怆离别。
遥望乐游原上冷落凄凉的秋日佳节，通往咸阳的古路上音信早已断绝。西风轻拂着夕阳的光照，眼前只是汉朝留下的坟墓和宫阙。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74855e272d4b2253b9b0", "shortContent": "这一篇千古绝唱，永远照映着中华民族的吟坛声苑。打开一部词史，我们的诗心首先为它所震荡，为之沉思翘首，为之惊魂动魄。\n然而，它只是一曲四十六字的小令。通篇亦无幽岩跨豹之奇情、碧海掣鲸之壮采，只见他寥寥数笔，微微唱叹，却不知是所因何故，竟会发生如此巨大的艺术力量！每一循吟，重深此感，以为这真是一个绝大的文学奇迹。含咀英华，揽结秀实，正宜潜心涵咏，用志覃研。\n第一韵，三字短句。万籁俱寂、玉漏沉沉，忽有一...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892bbb31680ae4c4b4aa", "shortContent": "这一篇千古绝唱，永远照映着中华民族的吟坛声苑。打开一部词史，我们的诗心首先为它所震荡，为之沉思翘首，为之惊魂动魄。\n\n然而，它只是一曲四十六字的小令。通篇亦无幽岩跨豹之奇情、碧海掣鲸之壮采，只见他寥寥数笔，微微唱叹，却不知是所因何故，竟会发生如此巨大的艺术力量！每一循吟，重深此感，以为这真是一个绝大的文学奇迹。含咀英华，揽结秀实，正宜潜心涵咏，用志覃研。\n\n第一韵，三字短句。万籁俱寂、玉漏沉沉，忽...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "64676e085e6bb82b8ccffe9c", "shortContent": "这一篇千古绝唱，永远照映着中华民族的吟坛声苑。打开一部词史，我们的诗心首先为它所震荡，为之沉思翘首，为之惊魂动魄。\n\n然而，它只是一曲四十六字的小令。通篇亦无幽岩跨豹之奇情、碧海掣鲸之壮采，只见他寥寥数笔，微微唱叹，却不知是所因何故，竟会发生如此巨大的艺术力量！每一循吟，重深此感，以为这真是一个绝大的文学奇迹。含咀英华，揽结秀实，正宜潜心涵咏，用志覃研。\n\n第一韵，三字短句。万籁俱寂、玉漏沉沉，忽...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413131320, '57b934500a2b58005c93f783', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10125, '菩萨蛮 · 花明月暗笼轻雾', NULL, 375, 87, 4, 2, '李煜', NULL, 10017, '57b8af7c5bbb50005b770fdd', '五代十国', 'ci', '词', 'http://baike.baidu.com/item/菩萨蛮·花明月暗笼轻雾', '', '花明月暗笼轻雾，今宵好向郎边去！刬袜步香阶，手提金缕鞋。
画堂南畔见，一晌偎人颤。奴为出来难，教君恣意怜。', '这首艳情词素以狎昵真切著称。“花明月黯笼轻雾”，繁花盛开，鲜明秾艳，香雾空蒙，渲染了柔和、美丽、朦胧的氛围；“今宵好向郎边去”，一个“好”字点明这是幽会的最佳时刻。“刬袜步香阶，手提金缕鞋”。“刬”音“产”，“刬袜”，以袜贴地。少女的轻盈步履，顾盼神情，跃然纸上。後阕将少女的炽烈恋情推向高潮：在一番担惊受怕之後，美好的愿望终于实现，像迂回曲折的流泉，遇到开阔处，如瀑布般倾泻出来，“见”、“颤”、“难”、“恣意怜”，几个字将所有的感触直截了当地显现出来，情真景真，毫无伪饰。
李煜的这首词，极俚，极真，也极动人，用浅显的语言呈现出深远的意境，虽无意于感人，而能动人情思，达到了王国维所说“专作情语而绝妙”的境地。', '笼轻雾：笼罩着薄薄的晨雾。笼，一作“飞”，一作“水”。
今宵：一作“今朝”，今夜。
郎边：一作“侬边”。
刬（chǎn）：《全唐诗》及《南唐书》中均作“衩”，只，仅，犹言“光着”。
刬袜：只穿着袜子着地。唐《醉公子》词中有：“刬袜下香阶，冤家今夜醉。”
步：这里作动词用，意为走过。
香阶：台阶的美称，即飘散香气的台阶。
手提：一作“手携”。
金缕鞋：指鞋面用金线绣成的鞋。缕，线。
画堂：古代宫中绘饰华丽的殿堂，这里也泛指华丽的堂屋。
南畔：南边。
一晌：一作“一向”，一时、刹时间。
偎：一作“畏”，紧紧地贴着、紧挨着。
颤：由于心情激动而身体發抖。
奴：一作“好”，古代妇女自称的谦词，也作奴家。
出来：一作“去来”。
教君：一作“教郎”、一作“从君”，让君、让你。
恣（zì）意：任意、放纵。恣，放纵、无拘束。
怜：爱怜、疼爱。', '朦胧的月色下花儿是那么娇艳，在这迷人的夜晚我要与你秘密相见。我光着袜子一步步迈上香阶，手里还轻轻地提着那双金缕鞋。在画堂的南畔我终于见到了你呀！依偎在你的怀里，我内心仍不停的發颤。你可知道我出来见你一次是多么的不容易，今天晚上我要让你尽情地把我爱怜。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e7493d635634aee3d70fa", "shortContent": "这是一首描写男女幽会的小词。那时李煜作为南唐小朝廷的君主，终日征歌逐舞，倚声填词，写了不少表现恋情的作品。与稍前的花间派词人相比，他洗尽铅华，不事雕绘，纯以白描的手法刻画感情，在词史上不能不说是一大进步。这首小词，便富有这样的特色。它的文字简练明白，自然真率，读完之后，词中女主人公热烈的爱情，大胆的追求，给我们留下深刻而又鲜明的印象。在唐五代词中，描写幽会题材的并非仅此一首，比李煜略早的牛峤也有一...", "authors": ["唐葆祥"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892e508c9c030fd725ed", "shortContent": "这是一首描写男女幽会的小词。那时李煜作为南唐小朝廷的君主，终日征歌逐舞，倚声填词，写了不少表现恋情的作品。与稍前的花间派词人相比，他洗尽铅华，不事雕绘，纯以白描的手法刻画感情，在词史上不能不说是一大进步。这首小词，便富有这样的特色。它的文字简练明白，自然真率，读完之后，词中女主人公热烈的爱情，大胆的追求，给我们留下深刻而又鲜明的印象。在唐五代词中，描写幽会题材的并非仅此一首，比李煜略早的牛峤也有一...", "authors": ["唐葆祥"], "pressName": "上海辞书出版社"}, {"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126df6c305cf0801816c29", "shortContent": "据马令《南唐书》记载，这首词是写小周后当日与李煜宫中幽会的情景。《菩萨蛮》，唐教坊曲，《宋史·乐志》、《尊前集》、《金奁集》并人“中吕宫”，《张子野词》作“中吕调”。唐苏鹗《杜阳杂编》：“大中（847—859）初，女蛮国贡双龙犀，明霞锦，其国人危髻金冠，缨络被体，故谓之菩萨蛮。当时倡优，遂歌菩萨蛮曲，文士亦往往效其词。”（见《词谱》卷五引）《唐音癸签》、《南部新书》略同。又《北梦琐言》：“宣宗爱唱...", "authors": [], "pressName": "崇文书局"}]', '卓人月《古今词统·卷五》引徐士俊：“花明月暗”一语，珠声玉价。
潘游龙《古今词馀醉·卷十》：结语极俚极真。
茅暎《词的·卷一》：竟不是作词，恍如对话矣。
沈雄《古今词话·词品》引孙琮：“感郎不羞赧，回身向郎抱”，六朝乐府便有此等艳情，莫诃词人轻薄。
陈廷焯《雲韶集·卷一》：“刬袜”二语，细丽。“一晌”妙，香奁词有此，真乃工绝。後人着力描写，细按之，总不逮古人。又《词则·闲情集·卷一》：荒淫语，十分沉至。
龙榆生《南唐二主词叙论》：其为小周后而作《菩萨蛮》，尤极风流狎呢之至，不愧“鸳鸯寺主”之名。', 'indent', 1423167854, '57b904890a2b58005c925b7c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10126, '渔父', NULL, 498, 87, 2, 2, '李煜', NULL, 10017, '57b8af7c5bbb50005b770fdd', '五代十国', 'ci', '词', 'http://baike.baidu.com/view/6929558.htm', '', '浪花有意千里雪，桃李无言一队春。一壶酒，一竿身，快活如侬有几人。', '词史上最早写《渔父》词的，是唐代的张志和。李煜这首词，继承的是张志和的「渔父家风」，写渔父的快乐逍遥。开篇选取两个场景来表现渔父的生活环境，一是江上，千里浪花翻滚如雪，一望无际，境界阔大。浪花翻滚，本是「无意」，而词人说「有意」，就写出了渔父与大自然的亲和感。江涛有意卷起雪浪来娱乐渔父的身心，衬托出渔父心情的快乐轻松。岸上，一排排的桃花李花，竞相怒放，把春天装点得十分灿烂。江上岸中所见，尽是美景。接着写渔父的装束和生活，身上挂着一壶酒，手里撑着一根竿，想到哪就把船撑到哪里，想喝酒随时都可以喝上几口，高兴了就唱首渔父歌，多自由，多快活！这世上像我这样的自由人，能有几个。结句以第一人称的口吻写出，实是作者对渔父的羡慕，就像王维《渭川田家》诗里所说的「即此羡闲逸」。', '渔父：词牌名，亦作《渔父词》，《历代诗馀》中作《渔歌子》。北宋·刘道醇《五代名画补遗·屋木门第五·神品一人（卫贤）》：「卫贤，京兆人，仕南唐，为内供奉。初师尹继昭，后刻苦不倦，执学吴生。长于楼观殿宇，盘车水磨，于时见称。予尝于富商高氏家观贤画《盘车水磨图》，及故大丞相文懿张公第有《春江钓叟图》，上有南唐李煜金索书《渔父词》二首，其一曰：『阆苑有情千里雪，桃花无言一队春。一壶酒，一竿身，快活如侬有几人。』其二曰：『一棹春风一叶舟，一轮茧缕一轻钩。花满渚，酒盈瓯。万顷波中得自由。』」。北宋·阮阅《诗话总龟·前集·巻二十·咏物门上》：「张文懿家有《春江钓叟图》，上有李煜《渔父词》二首。其一曰：『浪花有意千里雪，桃李无言一队春。一壶酒，一竿鳞，世上如侬有几人？』其二曰：『一棹春风一叶舟，一轮茧缕一轻钩。花满渚，酒满瓯，万顷波中得自由。』」明·陈耀文《花草粹编·巻一》中此词有题作「题供奉卫贤《春江钓叟图》（二首）」并注云：「金索书，不知书名抑书法也。」据夏承焘《唐宋词人年谱·南唐二主年谱》引陶谷《清异录》云：「后主善书，作颤笔樛曲之状，遒劲如寒松霜竹，谓之『金错刀』。」依王仲闻解，「金索书」即「金错刀书」，也就是李煜的书法。
浪花：《词谱》、《花草粹编》中均作「阆（láng）苑」。阆苑，传说中神仙居住的地方。
有意：有本作「有情」。
千里雪：一作「千重雪」，此据《全唐诗》。千重，千层，层层叠叠。
桃李：《全唐诗》作「桃花」。
一队春：指桃李盛开，由近及远，好像队列有序一样排列着，言春色正浓，春意盎然。
一竿身：一作「一竿鳞」，一作「一竿纶」，一根钓竿。
快活：一作「世上」。
侬（nóng）：江南口语，我。', '', '[{"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126df6c305cf0801816c21", "shortContent": "渔父，本名渔歌子。《词谱》云：唐教坊曲名。按《唐书·张志和传》曰：“志和居江湖，自称烟波钓徒。每垂钓，不设饵，志不在鱼也，宪宗图真求其人，不能致。尝撰渔歌，即此调也。”《花草粹编》调下有题“题供奉卫贤春江钓叟图”。\n\n据《诗话总龟》，渔父词是李煜的题画词作。写作年代当在早期，他还未即皇帝位。《南唐书·后主本纪》：“文献太子恶其有奇表，从嘉避祸，惟覃思经籍。”文献太子为了保住自己的继承权，曾用毒酒杀...", "authors": [], "pressName": "崇文书局"}]', '', 'indent', 1413204673, '57b8eb951532bc005b9a8b3d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10127, '渔父', NULL, 345, 87, 2, 1, '李煜', NULL, 10017, '57b8af7c5bbb50005b770fdd', '五代十国', 'ci', '词', 'http://baike.baidu.com/view/6929578.htm', '', '一棹春风一叶舟，一纶茧缕一轻钩。花满渚，酒满瓯，万顷波中得自由。', '这是《春江钓叟图》的题画词。此词写渔父的自由。可以想象渔父驾着一叶扁舟，划着一支长桨，迎着春风，出没在万顷波涛之中，何等潇洒自在。他时而举起一根丝线，放下一只轻钩；时而举起酒壶，看着沙洲上的春花，心满意足地品着美酒。全词借景寓意，突出了渔父的独立自由，表达了作者追求闲适、向往自由、隐逸遁世的思想情趣。', '此词调名亦作《渔父词》，《历代诗余》中作《渔歌子》。据宋阮阅《诗话总龟》载：“予尝于富商高氏家，观贤画《盘车水磨图》，及故大丞相文懿张公弟，有《春江钓叟图》，上有南唐李煜金索书《渔父词》二首。其一曰：‘浪花有意千里雪，……’其二曰：‘一棹春风一叶舟，……’”。另《古今诗话》中亦云：“张文懿家有《春江钓叟图》，上有李煜《渔父词》二首。”又，《花草粹编》中此词有题作“题供奉卫贤《春江钓叟图》，并注云：“金索书，不知书名抑书法也。”据夏承焘《唐宋词人年谱·南唐二主年谱》引陶谷《清异录》云：“后主善书，作颤笔樛曲之状，遒劲如寒松霜竹，谓之‘金错刀’。”依王仲闻解，“金索书”即“金错刀书”，也就是李煜的书法。
棹（zhào）：摇船的工具。短的叫楫，长的叫棹。
纶：《五代名画补遗》中作“轮”。纶，钓鱼用的粗丝线。茧缕（lǚ）：丝线，这里指渔弦。茧，茧丝。
渚（zhǔ）：水中间的小块陆地。
满：《五代名画补遗》作“盈”。此外各本作“满”。
瓯（ōu）：装酒的器具，即盅，一种平底深碗。
顷：土地面积单位。一百亩为一顷。', '', '[{"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126df6c305cf0801816c22", "shortContent": "王国维辑本《南唐二主词》校勘记：右二阕见《全唐诗》、《历代诗余》，笔意凡近，疑非李后主作也。彭文勤《五代史》注引《翰府名谈》张文懿家有《春江钓叟图》，卫贤画，上有李后主《渔父词》二首云云。此即《全唐诗》、《历代诗余》之所本，但字句小有不同，兹从《五代史》注所引改正。\n\n这首词的写作背景与上一首相同，也是表现了作者的避祸之心和遁世之思。据《十国春秋》卷十九《列传》：“弘茂，幼颖异，善歌诗，格调清古。...", "authors": [], "pressName": "崇文书局"}]', '', 'indent', 1413204335, '57b8e6115bbb50005b778d2e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10128, '虞美人·春花秋月何时了', NULL, 3160, 87, 4, 15, '李煜', NULL, 10017, '57b8af7c5bbb50005b770fdd', '五代十国', 'ci', '词', 'http://baike.baidu.com/view/652810.htm', '', '春花秋月何时了？往事知多少。小楼昨夜又东风，故国不堪回首月明中。
雕栏玉砌应犹在，只是朱颜改。问君能有几多愁？恰似一江春水向东流。', '相传七夕之夜中词人命歌伎唱此词，宋太宗赵光义知道这件事後，赐酒将他毒死，堪称绝命词。此词是一曲生命的哀歌，作者通过对自然永恒与人生无常的尖锐矛盾的对比，抒发了亡国後顿感生命落空的悲哀。全词语言明净、凝练、优美、清新，以问起，以答结，由问天、问人而到自问，通过凄楚中不无激越的音调和曲折回旋、流走自如的艺术结构，使作者沛然莫御的愁思贯穿始终，形成沁人心脾的美感效应。', '虞美人：原为唐教坊曲，後用为词牌名。此调初咏项羽宠姬虞美人死後地下开出一朵鲜花，因以为名。又名《一江春水》、《玉壶水》、《巫山十二峰》等。双调，五十六字，上下阕各四句，皆为两仄韵转两平韵。
了：了结，完结。
故国：指南唐故都金陵（今南京）。
雕栏玉砌：指远在金陵的南唐故宫。砌，台阶。
应犹：一作「依然」。
朱颜改：指所怀念的人已衰老。朱颜，红颜，少女的代称，这里指南唐旧日的宫女。
君：作者自称。
能：或作「都」「那」「还」「却」。', '这年的时光什么时候才能了结，往事知道有多少？昨夜小楼上又吹来了春风，在这皓月当空的夜晚，怎承受得了回忆故国的伤痛！
精雕细刻的栏杆、玉石砌成的台阶应该还在，只是所怀念的人已衰老。要问我心中有多少哀愁，就像这不尽的滔滔春水滚滚东流。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74925e272d4b2253b9e1", "shortContent": "前人吊李后主诗云：“作个才人真绝代，可怜薄命作君王。”的确，作为一个“好声色，不恤政事”的亡国之君，没有什么好说的，可是作为一代词人，他给后代留下许多惊天地泣鬼神的血泪文字，千古传诵不衰。这首《虞美人》就是其中最为人所熟知的一篇。相传后主于生日（七月七日）晚，在寓所命故妓作乐，唱《虞美人》词，声闻于外，宋太宗闻之大怒，命秦王赵廷美赐牵机药，将他毒死。所以，这首《虞美人》，可说是后主的绝命词了。\n这...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892d9820695e6503fd6a", "shortContent": "前人吊李后主诗云：“作个才人真绝代，可怜薄命作君王。”的确，作为一个“好声色，不恤政事”的亡国之君，没有什么好说的，可是作为一代词人，他给后代留下许多惊天地泣鬼神的血泪文字，千古传诵不衰。这首《虞美人》就是其中最为人所熟知的一篇。相传后主于生日（七月七日）晚，在寓所命故妓作乐，唱《虞美人》词，声闻于外，宋太宗闻之大怒，命秦王赵廷美赐牵机药，将他毒死。所以，这首《虞美人》，可说是后主的绝命词了。\n\n...", "authors": ["高原"], "pressName": "上海辞书出版社"}, {"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126e097ccdb86c49f28f08", "shortContent": "这首词向来被认为是李煜的绝命词，寄托了李煜对故国无法排遣的思念。\n吴讷《唐宋名贤百家词》本、汲古阁《词苑英华》本《尊前集》调作“虞美人影”。又《尊前集》注“中吕调”，王仲闻曰：唐宋词宫调无“中吕调”之称，认为系“中吕宫”之误也。各本调下注：“《尊前集》共八首，后主煜重光词也。”（侯文灿本无此注）吴讷本《南唐二主词》中“煜”误作“烟”。《草堂诗余》、《啸余谱》、《古今诗余醉》题作“感旧”。王仲闻《南...", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f3277e49f46528ad24f32", "shortContent": "前人吊李后主诗云：“作个才人真绝代，可怜薄命作君王。”的确，作为一个“好声色，不恤政事”的亡国之君，没有什么好说的，可是作为一代词人，他给后代留下许多惊天地泣鬼神的血泪文字，千古传诵不衰。这首《虞美人》就是其中最为人所熟知的一篇。相传后主于生日（七月七日）晚，在寓所命故妓作乐，唱《虞美人》词，声闻于外，宋太宗闻之大怒，命秦王赵廷美赐牵机药，将他毒死。所以，这首《虞美人》，可说是后主的绝命词了。\n这...", "authors": ["高原"], "pressName": "上海辞书出版社"}]', '宋·陈后山《後山诗话》：今语例袭陈言，但能转移耳。世称秦词「愁如海」为新奇，不知李国主已云「问君能有几多愁？恰似一江春水向东流」，但以「江」为「海」尔。
宋·王楙《野客丛书》：《後山诗话》载王平甫子游谓秦少游「愁如海」之句，出于江南李後主之意；又有所自。乐天诗曰：「欲识愁多少，高于艳濒堆。」刘禹锡诗曰：「蜀江春水拍山流，水流无限似侬愁」。得非祖此乎？则知好处前人皆已道过，後人但翻而用之耳。
宋·罗鹤林《鹤林玉露》：诗家有以山喻愁者，杜少陵云「忧端如山来，洪洞不可掇」，赵嘏云「夕阳楼上山重叠，未抵春愁一倍多」是也。有以水喻愁者，李颀云「请量东海水，看取浅深愁」，李後主云「问君能有几多愁，恰似一江春水向东流」，秦少游云「落红万点愁如海」是也。贺方回云：「试问闲愁知几许。一川烟草，满城风絮。梅子黄时雨。」盖以三者比愁之多也，尤为新奇，兼兴中有比，意味更长。
宋·陈藏一《藏一话腴》：太白云：「请君试问东流水，别意与之谁短长。」江南後主曰：「问君还有几多愁，恰似一江春水向东流。」略加融点，已觉精彩。至寇莱公则谓「愁情不断如春水」，少游云「落红万点愁如海」，青出于蓝而胜于蓝矣。
宋·俞文蔚《吹剑录》：诗有一联一字唤起一篇精神。李颀诗：「请量东海水，看取浅深愁。」李後主词：「问君能有几多愁？恰似一江春水向东流。」
明·卓蕊渊《古今词统》：只一「又」字，宋元以来抄者无数，终不厌烦。
明·董思翁《评注使读草堂诗馀》：山谷羡後主此词。荆公云：「未若『细雨梦回鸡塞远，小楼吹彻玉笙寒』尤为高妙。」
清·尤西堂《延露词序》：诗何以「馀」哉？「小楼昨夜」，《哀江头》之馀也。
清·王阮亭《花草蒙拾》：钟隐入汴後，「春花秋月」诸词，与「此中日夕只以眼泪洗面」一帖，同是千古情种，较长城公煞是可怜。
清·沈偶僧《古今词话》：李後主词：「春花秋月何时了……」当以此阕为最。
清·冯墨香《词苑萃编》：王介甫问黄鲁直，李後主词何句最佳。鲁直举「问君能有儿多愁，恰似一江春水向东流」。介甫以为未若「细雨梦回鸡塞远，小楼吹彻玉笙寒」。介甫之言是矣。顾以专论後主之词可耳，尚非词之至也。若总统诸家而求极致，于不食烟火；不落言诠，如女中之有国色，无事矜庄修饰，使当之者忽然自失，而未由彷彿其皎好，其惟太白「膜色人高楼，有人楼上愁」乎，惜乎今之才人、动而不静，往而不返，识此宗趣者盖寡。
清·陈亦峰《云韶集》：一声恸歌，如闻哀猿，呜咽缠绵，满纸血泪。
清·王壬父《湘绮楼词选》：常语耳，以初见故佳，再学便滥矣。朱颜本是山河，因归宋不敢言耳。若直说山河改，反又浅也。结亦恰到好处。
清·谭復堂《词辨·卷二十二》：词（谓此阕及「风回小院」阕）终当以神品目之。後主之词，足当太白诗篇，高奇无匹。
近·俞乐静《唐五代两宋词选释》：「亡国之音，何哀思之深耶！」传诵禁庭，不加悯而被祸，失国者不殉宗社而任人宰割，良足伤矣。《後山诗话》谓秦少游词「飞红万点愁如海」，出于後主「一江春水」句，《野客丛书》又谓李白之「愁高滟澦堆」，刘禹锡之「水流无限似依愁」，为後主词所祖。但以水喻愁，词家意所易到，屡见载籍，未必互相沿用。就词而论，李、刘、秦诸家之以水喻愁，不若後主之「春江」九字，真伤心人语也。
近·唐季特《唐宋词简释》：此首感怀故国，悲愤已极。起句，追维往事，痛不欲生！满腔恨血，喷薄而出：诚《天问》之遗也。「小楼」句承起句，缩笔吞咽；「故国」句承起句，放笔呼号。一「又」字惨甚。东风又入，可见春花秋月一时尚不得遽了。罪孽未满，苦痛未尽，仍须偷息人间，历尽磨折。下片承上，从故国月明想入，揭出物是人非之意。末以问答语，吐露心中万斛愁恨，令人不堪卒读。通首一气盘旋，曲折动荡，如怨如慕，如泣如诉。', 'indent', 1423167934, '57afef90c4c97100547caf03', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10144, '渔家傲', NULL, 594, 101, 3, 4, '李清照', NULL, 10043, '57b90879df0eea0063351b94', '宋', 'ci', '词', 'http://baike.baidu.com/view/2212659.htm', '', '天接云涛连晓雾，星河欲转千帆舞。仿佛梦魂归帝所，闻天语，殷勤问我归何处。
我报路长嗟日暮，学诗谩有惊人句。九万里风鹏正举。风休住，蓬舟吹取三山去。', '此词写梦中海天溟蒙的景象及与天帝的问答，隐寓对社会现实的不满与失望，对理想境界的追求和向往。作者把真实的生活感受融入梦境，以浪漫主义的艺术构思，梦游的方式，奇妙的设想，倾述隐衷，寄托情思。全词打破了上阕写景下阕抒情或情景交错的惯常格局，以故事性情节为主干，以人神对话为内容，实现了梦幻与生活、历史与现实的有机结合，用典巧妙，景象壮阔，气势磅礴，音调豪迈，充分显示了作者性情中豪放不羁的一面。', '渔家傲：词牌名，又名《渔歌子》、《渔父词》等。有用以作“十二月鼓子词”者。《清真集》入“般涉调”。明蒋氏《九宫谱目》入“中吕引子”。作为曲调，原是用于佛曲、道曲。宋·吴曾《能改斋漫录·卷二·〈事始·八相太常引〉》：“而南方释子作《渔父》、《拨棹子》、《渔家傲》、《千秋岁》唱道之辞。”《渔家傲》词牌创调者当为北宋范文正。《乐府纪闻》：“张志和自称‘烟波钓徒’，愿为浮家泛宅，往来苕霅（TiáoZhà）间，作《渔歌子》。”按张志和所作“西塞山前白鹭飞”一词，亦名《渔父词》，其调之曲拍，不传于后世。而唐宋词人，又多有《渔家乐》之作，其为描写渔人生活之词则同。至范希文乃有本调之创，题义盖与《渔家乐》无二致也。《东轩笔录》云：“范文正守边日，作《渔家傲》乐歌数曲，皆以‘塞下秋来’为首句，颇述边镇之劳苦。欧阳公尝呼为‘穷塞王’之词。及王尚书素出守平凉。文忠亦作《渔家傲》一首以送之。”是此调之创自希文，已可證明；惟所咏则渐涉于泛耳。按此调始自晏同叔，因词有“神仙一曲渔家傲”句，取以为名。如杜安世词三声叶韵，蔡申道词添字者，皆变体也。外有《十二个月鼓子词》，其十一月、十二月起句俱多一字。欧阳永叔词云：“十一月，新阳排寿宴。十二月，严凝天地闭。”欧阳原功词云：“十一月，都人居暖阁。十二月，都人供暖箑。”此皆因月令，故多一字，非添字体也。
星河：银河。
转：《历代诗馀》作“曙”。
帝所：天帝居住的地方。
天语：天帝的话语。
殷勤：关心地。
路长：屈原《离骚》：“路漫漫其修远兮，我将上下而求索”之意。
日暮：屈原《离骚》：“欲少留此灵琐兮，日忽忽其将暮”之意。
嗟（jiē）：慨叹。
“学诗谩有惊人”句：檃括杜甫句：“语不惊人死不休”。谩有，空有。
九万里：《庄子·逍遥游》中说大鹏乘风飞上九万里高空；鹏，古代神话传说中的大鸟。
蓬舟：像蓬蒿被风吹转的船。古人以蓬根被风吹飞，喻飞动。
吹取：吹得。
三山：《史记·封禅书》记载：渤海中有蓬莱、方丈、瀛洲三座仙山，相传为仙人所居住，可以望见，但乘船前往，临近时就被风吹开，终无人能到。蓬莱，又称蓬壶。', '天蒙蒙，晨雾蒙蒙笼云涛。银河欲转，千帆如梭逐浪飘。梦魂仿佛又回到了天庭，天帝传话善意地相邀。殷勤地问道：你可有归宿之处？
我回报天帝说：路途漫长又叹日暮时不早。学作诗，枉有妙句人称道，却是空无用。长空九万里，大鹏冲天飞正高。风啊！请千万别停息，将这一叶轻舟，载着我直送往蓬莱三仙岛。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74d134a8757d5a0d9e7e", "shortContent": "在词史上，李清照继柳永、秦观、周邦彦之后，被称为婉约之宗。她的词清丽婉转、幽怨凄恻，极富于抒情性。但是这首词却表现出不同的风格，它气势磅礴，音调豪迈，是李词中仅见的浪漫主义名篇。\n词写梦境。但是梦境也是现实生活在作家头脑中的折射，诚如夏承焘所说：“这决不是没有真实生活感情而故作豪语的人所能写得出的。”（《唐宋词欣赏》）南渡以前，李清照足迹不出闺门；南渡以后，“飘流遂与流人伍”，视野开始开阔起来。据...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5d50ce818559d063bca", "shortContent": "在词史上，李清照继柳永、秦观、周邦彦之后，被称为婉约之宗。她的词清丽婉转、幽怨凄恻，极富于抒情性。但是这首词却表现出不同的风格，它气势磅礴，音调豪迈，是李词中仅见的浪漫主义名篇。\n词写梦境。但是梦境也是现实生活在作家头脑中的折射，诚如夏承焘所说：“这决不是没有真实生活感情而故作豪语的人所能写得出的。”（《唐宋词欣赏》）南渡以前，李清照足迹不出闺门；南渡以后，“飘流遂与流人伍”，视野开始开阔起来。据...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "60fc32b023353c0ba53dd945", "bookTitle": "历代女性诗词鉴赏辞典", "articleId": "610ec78b7d0ac1145495ebcf", "shortContent": "这首《渔家傲》是易安词中表现了特殊风格的一首名作。一般说来，唐宋词中所写的景物情事大多是现实中之所实有者，而这首词从整体来看，却表现有一种非现实的理想之意味。以前王国维在《人间词话》中曾经提出过“造境”与“写境”之说，谓“有造境，有写境，此理想与写实二派之所由分”。又说，“然二者颇难分别，因大诗人所造之境，必合乎自然，所写之境，亦必邻于理想故也”。李氏此词佳处之所在，还不仅只是在于其所象喻的理想意...", "authors": ["叶嘉莹"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592544b56e213e684804a", "shortContent": "在词史上，李清照继柳永、秦观、周邦彦之后，被称为婉约之宗。她的词清丽婉转、幽怨凄恻，极富于抒情性。但是这首词却表现出不同的风格，它气势磅礴，音调豪迈，是李词中仅见的浪漫主义名篇。\n\n词写梦境。但是梦境也是现实生活在作家头脑中的折射，诚如夏承焘所说：“这决不是没有真实生活感情而故作豪语的人所能写得出的。”（《唐宋词欣赏》）南渡以前，李清照足迹不出闺门；南渡以后，“飘流遂与流人伍”，视野开始开阔起来。...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "6277f84f8efdff05d7d6839b", "bookTitle": "李清照全集", "articleId": "6312258b77683d193300d3c0", "shortContent": "这首词《花庵词选》题作《记梦》。作者借助于梦想象，寻求精神寄托。以鹏鸟自喻，表现了她对自由的渴望，显示了她的豪迈气概，词风雄健，用语新奇，出自新寡贵妇，特奇。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645d1153a2a0d66afdbadb39", "bookTitle": "李清照诗词鉴赏辞典", "articleId": "6464a8de45e4710056c450ea", "shortContent": "在词史上，李清照继柳永、秦观、周邦彦之后，被称为婉约之宗。她的词清丽婉转、幽怨凄恻，极富于抒情性。但是这首词却表现出不同的风格，它气势磅礴，音调豪迈，是李词中仅见的浪漫主义名篇。\n\n词写梦境。但是梦境也是现实生活在作家头脑中的折射，诚如夏承焘所说：“这决不是没有真实生活感情而故作豪语的人所能写得出的。”（《唐宋词欣赏》）南渡以前，李清照足迹不出闺门；南渡以后，“飘流遂与流人伍”，视野开始开阔起来。...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "64720074e49f46528addc40e", "shortContent": "在词史上，李清照继柳永、秦观、周邦彦之后，被称为婉约之宗。她的词清丽婉转、幽怨凄恻，极富于抒情性。但是这首词却表现出不同的风格，它气势磅礴，音调豪迈，是李词中仅见的浪漫主义名篇。\n词一开头，便展现一幅辽阔、壮美的海天相接的图画。这样的境界，在唐五代以及两宋词中，很少见到。首二句写了天、云涛、晓雾、星河、千帆，景象已极壮丽，其中又准确地嵌入了几个动词，则绘景如活，动态俨然。“接”“连”二字把四垂的天...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}]', '黄苏《蓼园词选》：浑成大雅，无一毫钗粉气。
梁任公《艺蘅馆词选》：此绝似苏辛派，不类《漱玉词》中语。', 'indent', 1413128694, '57b975600a2b58005c967c32', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10130, '浪淘沙令', NULL, 1088, 87, 4, 4, '李煜', NULL, 10017, '57b8af7c5bbb50005b770fdd', '五代十国', 'ci', '词', 'http://baike.baidu.com/view/1287183.htm', '', '帘外雨潺潺，春意阑珊。罗衾不耐五更寒。梦里不知身是客，一晌贪欢。
独自莫凭栏，无限江山。别时容易见时难。流水落花春去也，天上人间。', '这首词作于李煜被囚汴京期间，抒发了由天子降为臣虏后难以排遣的失落感，以及对南唐故国故都的深切眷念。全词情真意切、哀婉动人，深刻地表现了词人的亡国之痛和囚徒之悲，生动地刻画了一个亡国之君的艺术形象。', '浪淘沙令：原为唐教坊曲，又名《浪淘沙》、《卖花声》等。唐人多用七言绝句入曲，南唐李煜始演为长短句。双调，五十四字（宋人有稍作增减者），平韵，此调又由柳永、周邦彦演为长调《浪淘沙漫》，是别格。
潺潺：形容雨声。
阑珊：衰残。一作“将阑”。
罗衾（qīn）：绸被子。不耐：受不了。一作“不暖”。
身是客：指被拘汴京，形同囚徒。
一晌（shǎng）：一会儿，片刻。一作“饷（xiǎng）”。贪欢：指贪恋梦境中的欢乐。
凭栏：靠着栏杆。
江山：指南唐河山。', '门帘外传来雨声潺潺，浓郁的春意又要凋残。罗织的锦被受不住五更时的冷寒。只有迷梦中忘掉自身是羁旅之客，才能享受片时的欢娱。独自一人在高楼上倚靠栏杆遥望远方，因为想到旧时拥有的无限江山，心中便会泛起无限伤感。离别它是容易的，再要见到它就很艰难。像流失的江水凋落的红花跟春天一起回去也，今昔对比，一是天上一是人间。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74942e6a6b501f954108", "shortContent": "宋蔡絛《西清诗话》谓本词是作者去世前不久所写：“南唐李后主归朝后，每怀江国，且念嫔妾散落，郁郁不自聊，尝作长短句云：‘帘外雨潺潺……’含思凄惋，未几下世。”从本词低沉悲怆的基调中，透露出这个亡国之君绵绵不尽的故土之思，可以说这是一支宛转凄苦的哀歌。\n上片用倒叙，先写梦醒再写梦中。起首说五更梦回，薄薄的罗衾挡不住晨寒的侵袭。帘外，是潺潺不断的春雨，是寂寞零落的残春；这种境地使他倍增凄苦之感。“梦里”...", "authors": ["潘君昭"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892e508c9c030fd725f0", "shortContent": "宋蔡絛《西清诗话》谓本词是作者去世前不久所写：“南唐李后主归朝后，每怀江国，且念嫔妾散落，郁郁不自聊，尝作长短句云：‘帘外雨潺潺……’含思凄惋，未几下世。”从本词低沉悲怆的基调中，透露出这个亡国之君绵绵不尽的故土之思，可以说这是一支宛转凄苦的哀歌。\n\n上片用倒叙，先写梦醒再写梦中。起首说五更梦回，薄薄的罗衾挡不住晨寒的侵袭。帘外，是潺潺不断的春雨，是寂寞零落的残春；这种境地使他倍增凄苦之感。“梦里...", "authors": ["潘君昭"], "pressName": "上海辞书出版社"}, {"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126e097ccdb86c49f28f07", "shortContent": "这首词《草堂诗余》、《词的》、《古今诗余醉》本调下有题“怀旧”。《啸余谱》调下有题“春暮怀旧”。吕远本《南唐二主词》作“浪淘沙令”。其他各本《南唐二主词》作“浪淘沙”。这首词的意境很悲苦，是李煜被俘后所作。《苕溪渔隐丛话》前集卷三十一引蔡绦《西清诗话》云：“南唐李后主归朝后，每怀江国，且念嫔妾散落，郁郁不自聊。尝作长短句帘外雨潺潺云云，含思凄婉，未几下世。”所以这首词向来被视为李煜的绝笔之作。这首...", "authors": [], "pressName": "崇文书局"}]', '陈锐《褒碧斋词话》：古诗“行行重行行”，寻常白话耳。赵宋人诗亦说白话，能有此气骨否？李后主词“帘外雨潺潺”，寻常白话耳。金元人词亦说白话，能有此缠绵否？
沈际飞《草堂诗余正集》：“梦觉”语妙，那知半生富贵，醒亦是梦耶？末句，可言不可言，伤哉。
贺裳《皱水轩词筌》：南唐主《浪淘沙》曰：“梦里不知身是客，一晌贪欢。”至宣和帝《燕山亭》则曰：“无据。和梦也有时不做。”其情更惨矣。呜呼，此犹《麦秀》之后有《黍离》也。
王国维《人间词话》：李重光之词，神秀也。词至李后主而眼界始大，感慨遂深。……“自是人生长恨水长东”、“流水落花春去也，天上人间”，金荃、浣花，能有此气象耶？', 'indent', 1413130852, '57b14b09c4c971005486bf67', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10131, '相见欢', NULL, 1339, 87, 2, 12, '李煜', NULL, 10017, '57b8af7c5bbb50005b770fdd', '五代十国', 'ci', '词', 'http://baike.baidu.com/view/652807.htm', '', '无言独上西楼，月如钩。寂寞梧桐深院锁清秋。
剪不断，理还乱，是离愁。别是一般滋味在心头。', '这是作者被囚于宋国时所作。词牌名为《相见欢》，咏的却是离别愁。词中的缭乱离愁不过是他宫廷生活结束後的一个插曲，由于当时已经归降宋朝，这里所表现的是他离乡去国的锥心怆痛。这首词感情真实，深沉自然，突破了花间词以绮丽腻滑笔调专写「妇人语」的风格，是宋初婉约派词的开山之作。', '相见欢：词牌名，原为唐教坊曲，又名《乌夜啼》、《上西楼》、《西楼子》、《秋夜月》、《月上瓜洲》、《忆真妃》等。三十六字，上阕平韵，下阕两仄韵两平韵。
锁清秋：深深被秋色所笼罩。清秋，一作深秋。
剪：一作“翦”。
离愁：指去国之愁。
别是一般：另有一种意味。别是一作“别有”，一般一作“一番”。', '默默无言，孤孤单单，独自一人缓缓登上空空的西楼。抬头望天，只有一弯如钩的冷月相伴。低头望去，只见梧桐树寂寞地孤立院中，幽深的庭院被笼罩在清冷凄凉的秋色之中。
那剪也剪不断，理也理不清，让人心乱如麻的，正是亡国之苦。那悠悠愁思缠绕在心头，却又是另一种无可名状的痛苦。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e7492d635634aee3d70f0", "shortContent": "亡国前耽于享乐，亡国后溺于悲哀，这就是李后主的一生。宋太祖开宝八年（975），宋军围攻金陵，李煜肉袒出降，被封为“违命侯”。从此，幽居在汴京的一座深院小楼，过着日夕以眼泪洗面的凄凉寂寞的日子。这首《相见欢》就是写这种幽囚生活的愁苦滋味。\n一个被幽禁的人有着一般人难以体会的孤独与寂寞，后主真切地写出了这种感受。“无言独上西楼”，既是“独上”，自然无人共语。这里的“无言”更表现了后主内心的情绪，他的痛...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892d9820695e6503fd6e", "shortContent": "亡国前耽于享乐，亡国后溺于悲哀，这就是李后主的一生。宋太祖开宝八年（975），宋军围攻金陵，李煜肉袒出降，被封为“违命侯”。从此，幽居在汴京的一座深院小楼，过着日夕以眼泪洗面的凄凉寂寞的日子。这首《相见欢》就是写这种幽囚生活的愁苦滋味。\n\n一个被幽禁的人有着一般人难以体会的孤独与寂寞，后主真切地写出了这种感受。“无言独上西楼”，既是“独上”，自然无人共语。这里的“无言”更表现了后主内心的情绪，他的...", "authors": ["高原"], "pressName": "上海辞书出版社"}, {"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126e097ccdb86c49f28efe", "shortContent": "这首词的作者，《花草粹编》引杨提《古今词话》及《十国春秋》均认为为孟昶作，《花庵词选》、《续集》均列为后主作。《词谱》作者也认为是李后主作。赵万里校辑杨堤《古今词话》在此词后案：“《花庵唐宋诸贤绝妙词选》引作李后主词，南词本《南唐二主词》无之，杨堤谓为孟昶作，殆必有据。”王仲闻《南唐二主词校订》曰：“《乌夜啼》词究为孟作抑李作，未能断定。”但据词的风格来看，更接近李煜，故今人多归之于李煜，如唐圭璋...", "authors": [], "pressName": "崇文书局"}]', '沈震峰《草堂诗馀续集》：七情所至，浅尝者说破，深尝者说不破。破之浅，不破之深。「别是一般滋味在心头」句妙。
茅远士《词的·卷一》：绝无皇帝气。可人，可人。
谭复堂：前半阙濡染大笔。
陈亦峰《词则·大稚集·卷一》：哀感顽艳，只说不出。」
陈亦峰《云韶集·卷一》：「凄凉况味，欲言难言，滴滴是泪。
王湘绮《湘绮楼词选》前编：词之妙处，亦别是一般滋味。
俞乐静《唐五代两宋词选释》：後阕仅十八字，而肠回心倒，一片凄异之音，伤心人固别有怀抱。
刘知秋《词论》：纯作情语，比托情景中为难工也。此类佳者，如：李後主「剪不断，理还乱，是离愁，别是一般滋味在心头。
刘知秋《唐五代两宋词简析》：上半阕言所处之寂寞。下半例满腹离怨，无语可以形容，故朴直说出。「别是」句，尤为沉痛。盖亡国君之滋味，实尽人世悲苦之滋味无可与比者。故曰：「别是一般」。此二首表面似春秋闺怨之词，因不敢明抒已情，而托之闺人离思也。
俞平伯《读词偶得》：其实首句「无言独上西楼」六字之中，已摄尽凄婉之神矣。」《唐宋词选释》「虽上阕写景，下阕抒情，凄凉的气象，却融会全篇，如起笔「无言独上西楼」一句，已摄尽凄婉的神情，「别是一番滋味」，也是离愁。剪不断，理还乱，还可形状，这却说不出，是更深一层的写法。
唐季特《唐宋词简释》：此词写别愁，凄惋已极。「无言独上西楼」一句，叙事直起，画出後主愁容。其下两句，画出後主所处之愁境。举头见新月如钩，低头见桐阴深锁俯仰之间，万感萦怀矣。此阕写景亦妙，惟其桐阴深黑，新月乃愈显明媚也。下阕，因景抒情。换头三句，深刻无匹，使有千丝万缕之离愁，亦未必不可剪，不可理，此言「剪不断，理还乱」，则离愁之纷繁可知。所谓「别是一般滋味」，是无人尝过之滋味，唯有自家领略也。後主以南朝天子，而为北地幽囚；其所受之痛苦，所尝之滋味，自与常人不同，心头所交集者，不知是悔是恨，欲说则无从说起，且亦无人可说，故但云「别是一般滋味」。', 'indent', 1423167994, '57b5a4ed79bc44005e126349', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10132, '浪淘沙令', NULL, 324, 87, 4, 2, '李煜', NULL, 10017, '57b8af7c5bbb50005b770fdd', '五代十国', 'ci', '词', 'http://baike.baidu.com/view/652789.htm', '', '往事只堪哀，对景难排。秋风庭院藓侵阶。一任珠帘闲不卷，终日谁来？
金锁已沉埋，壮气蒿莱。晚凉天净月华开。想得玉楼瑶殿影，空照秦淮！', '这首词是李煜囚于汴京期间（976·978）所作。宋人王轾《默记》记载，李煜的居处有“老卒守门”，“不得与外人接”，所以李煜降宋后，实际上被监禁起来了。他曾传信给旧时官人说，“此中日夕以泪洗面！”
这首词是词人从一个亡国之君的立场和思想感情来写他追怀昔日帝王生活的悲哀和寂寞，词中以直抒悲怀领起，继之以一系列鲜明的图景。词中有眼前景，有象征景，有想象景，把他的凄凉之感，亡国之痛，故国之思，寄寓其中，突出地表现了词人善于捕捉形象的艺术才能。', '浪淘沙令：又名《卖花声》、《曲入冥》、《过龙门》、《炼丹砂》。正体双调五十四字，前后片各五句、四平韵，多作激越凄壮之音。
藓侵阶：苔藓上阶，表明很少有人来。
一任：任凭。吴本、吕本、侯本《南唐二主词》、《花草粹编》作“一行”；《续选草堂诗余》、《古今词统》作“一片”；粟本《二主词》、《历代诗余》、《全唐诗》作“桁（héng）”。一桁：一列，一挂，如杜牧《十九兄郡楼有宴病不赴》：“燕子嗔重一桁帘。”
终日谁来：整天没有人来。
金锁：即铁锁，用三国时吴国用铁锁封江对抗晋军事。或以为“金锁”即“金琐”，指南唐旧日宫殿。也有人把“金锁”解为金线串制的铠甲，代表南唐对宋兵的抵抗。众说皆可通。锁：萧本、晨本《二主词》作“琐”。侯本《南唐二主词》、《花草粹编》、《词综》、《历代诗余》、《全唐诗》作“金剑”。《续选草堂诗余》、《古今词统》作“金敛”。《古今词统》并注：“敛，一作剑。”按：作敛不可解，盖承“金剑”而误。
已：《草堂诗余续集》、《古今词统》作“玉”。《古今词统》并注：“玉，一作已。”
蒿莱：蒿莱，借指野草、杂草，这里用作动词，意为淹没野草之中，以此象征消沉，衰落。
净：吴讷《百家词》旧抄本、吕本、侯本、萧本《南唐二主词》、《花草粹编》、《词综》、《续集》、《词综》、《全唐诗》俱作“静”。
秦淮：即秦淮河。是长江下游流经今南京市区的一条支流。据说是秦始皇为疏通淮水而开凿的，故名秦淮。秦淮一直是南京的胜地，南唐时期两岸有舞馆歌楼，河中有画舫游船。', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749434a8757d5a0d9d4e", "shortContent": "这首词始见于南宋无名氏辑本《南唐二主词》。近人因这首词的风格比较“豪放”，而认为非李煜所作。其实，从创作风格看，它同李煜后期写的《虞美人》和另一首《浪淘沙》等词并无很大差异，都是直抒胸臆、一气呵成之作。\n词的主旨一上来就开门见山地道破，即“往事堪哀”、“对景难排”这八个字。“景”指眼前景物，正对“往事”而言，而“往事”又与今日之处境两相映照，昔日贵为天子，今日贱为俘虏，这简直有九天九地之差。而今生...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892e508c9c030fd725ef", "shortContent": "这首词始见于南宋无名氏辑本《南唐二主词》。近人因这首词的风格比较“豪放”，而认为非李煜所作。其实，从创作风格看，它同李煜后期写的《虞美人》和另一首《浪淘沙》等词并无很大差异，都是直抒胸臆、一气呵成之作。\n\n词的主旨一上来就开门见山地道破，即“往事堪哀”、“对景难排”这八个字。“景”指眼前景物，正对“往事”而言，而“往事”又与今日之处境两相映照，昔日贵为天子，今日贱为俘虏，这简直有九天九地之差。而今...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126e097ccdb86c49f28f06", "shortContent": "这首词，《草堂诗余续集》调下有题“感念”，《古今词统》调下有题“在汴京念秣陵作”。词是李煜后期的作品，与《虞美人》、《菩萨蛮》一样都是感念往事之作。同时也表达了他入宋后的孤苦，一句“终日谁来”确实道尽辛酸。", "authors": [], "pressName": "崇文书局"}]', '沈际飞《草堂诗余续集》卷上：此在汴京念秣陵事作，读不忍霓。
陈廷焯《大雅集》卷一：起五字极凄婉，而来势妙，极突兀。陈廷焯《云韶集》卷一：起五字凄婉，却来得突兀，故妙。凄恻之词而笔力精健，古今词人谁不低首。
俞陛云《唐五代两宋词选释》：藓阶帘静，凄寂等于长门，“金锁”二句有铁锁沉江，王气黯然之慨。回首秦淮，宜其凄咽。唐人《浪淘沙》，本七言断句，至后主始制二段，每段尚存七言诗二句，盖因旧曲名而别创新声也。原注谓此词昔已散佚，乃白池州夏氏家藏传播者。
唐圭璋《李后主评传》：他自迁宋都后，自然是事事不得自由。他看不见江南的人物风景，他也挽不回过去的青春。仅仅有自由的梦魂，时时去萦绕他的故国。他的词说：“往事只堪哀（略）”，“无言独上西楼（略）”。可想见他孤独的悲哀。李易安所谓“寻寻觅觅，冷冷清清，凄凄惨惨戚戚”的生活，也正是他的写照。
唐圭璋《唐宋词简释》：此首念秣陵。上片，白昼凄清状况，哀思弥切。起两句，总括全篇。“秋风”一句，补实上句难排之景。秋风袅袅，苔藓满阶，想见荒凉无人之情，与当年“春殿嫔娥鱼贯列”之盛较之，真有天渊之别。“一桁”两句，极致孤独之哀。后主人汴以后之生活，于此可见。换头，自叹当年之意气都已销尽。“晚凉”一句，点月出。“想得”两句，因月生感，怅望无极。月影空照秦淮，画出失国后惨淡景象。
詹安泰《李璟李煜词》：这是李煜抒写入宋后怀念南唐的一种哀痛的心情。前后段都先以无比怨愤的声调冲激而出，然后通过具体的生活现象和内心活动来表达当时十分难堪的情况。前段写风景撩人，而珠帘不卷，无谁告语，是日间生活的难堪。后段写天清月白，想起秦淮河畔的楼殿，只有影儿投入河里，一切繁华旧事，都成空花，是夜间生活的难堪。日夜并举，用突出的形象，作高度的概括。', 'indent', 1413204563, '57b8ee8b5bbb50005b77b22d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10133, '咏鹅', NULL, 5134, 132, 1, 8, '骆宾王', NULL, 10042, '57b9c1c5a34131005b0d7f6e', '唐', 'shi', '诗', 'http://baike.baidu.com/view/47325.htm', '', '鹅，鹅，鹅，曲项向天歌。
白毛浮绿水，红掌拨清波。​', '《咏鹅》是初唐诗人骆宾王于七岁时写的一首五言古诗。这首诗开篇先声夺人，「鹅！鹅！鹅！」写出鹅的声响美，又通过「曲项」与「向天」、「白毛」与「绿水」、「红掌」与「清波」的对比写出鹅的线条美与色彩美，同时，「歌」、「浮」、「拨」等字又写出鹅的动态美，听觉与视觉、静态与动态、音声与色彩完美结合，将鹅的形神活现而出。', '曲项：弯着脖子。歌：长鸣。
拨：划动。', '鹅鹅鹅，面向蓝天，一群鹅儿伸着弯曲的脖子在歌唱。
洁白的羽毛，漂浮在碧绿水面。红红的脚掌，拨动着清清水波。', '[{"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646e0de35e6bb82b8cec11fe", "shortContent": "这首诗是骆宾王年仅7岁时所写，他以孩子的眼光细致地观察，把鹅描写得生动鲜活，又颇有童趣。开篇连用三个“鹅”字。有人认为是模仿鹅的叫声，也有人认为是表现一个孩子见到鹅的兴奋与喜爱之情，无论是哪种解释，都不失为一个简单却响亮的开头。“曲项向天歌”，巧妙抓住了鹅长长的脖子这一特征，描绘鹅引吭高歌之态。\n后两句转而描写鹅在水中游的样子。“浮”“拨”准确刻画鹅游泳的姿态，“白毛”与“红掌”，既写出了鹅在颜色...", "authors": ["陈炜琦"], "pressName": "上海辞书出版社"}]', '', 'center', 1362517185, '57b9147d79bc44005b9f4138', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10134, '为徐敬业讨武曌檄', NULL, 62, 132, 1, 1, '骆宾王', NULL, 10042, '57b9c1c5a34131005b0d7f6e', '唐', 'wen', '文', 'http://baike.baidu.com/view/857020.htm', '', '伪临朝武氏者，性非和顺，地实寒微。昔充太宗下陈，曾以更衣入侍。洎乎晚节，秽乱春宫。潜隐先帝之私，阴图后房之嬖。入门见嫉，蛾眉不肯让人；掩袖工谗，狐媚偏能惑主。践元后于翚翟，陷吾君于聚麀。加以虺蜴为心，豺狼成性。近狎邪僻，残害忠良。杀姊屠兄，弑君鸩母。人神之所同嫉，天地之所不容。犹复包藏祸心，窥窃神器。君之爱子，幽之于别宫；贼之宗盟，委之以重任。呜呼！霍子孟之不作，朱虚侯之已亡。燕啄皇孙，知汉祚之将尽。龙漦帝后，识夏庭之遽衰。
敬业皇唐旧臣，公侯冢子。奉先君之成业，荷本朝之厚恩。宋微子之兴悲，良有以也；袁君山之流涕，岂徒然哉！是用气愤风云，志安社稷。因天下之失望，顺宇内之推心。爰举义旗，以清妖孽。
南连百越，北尽三河；铁骑成群，玉轴相接。海陵红粟，仓储之积靡穷；江浦黄旗，匡复之功何远！班声动而北风起，剑气冲而南斗平。喑呜则山岳崩颓，叱咤则风云变色。以此制敌，何敌不摧？以此图功，何功不克？
公等或居汉地，或协周亲；或膺重寄于爪牙，或受顾命于宣室。言犹在耳，忠岂忘心。一抔之土未干，六尺之孤何托？倘能转祸为福，送往事居，共立勤王之勋，无废旧君之命，凡诸爵赏，同指山河。若其眷恋穷城，徘徊歧路，坐昧先几之兆，必贻后至之诛。请看今日之域中，竟是谁家之天下！
移檄州郡，咸使知闻。', '嗣圣元年（公元684年），武则天废中宗自立，这年9月，徐敬业（即李敬业）在扬州起兵反对。骆宾王为徐府属，被任为艺文令，掌管文书机要。他起草著名的《讨武氏檄》，慷慨激昂，气吞山河。武则天读至“一抔之土未干，六尺之孤何托”，皇然问：“谁为之？”或以宾王对，武则天感叹曰：“宰相安得失此人？”十一月徐敬业兵败被杀，骆宾王下落不明。', '', '那个非法把持朝政的武氏，不是一个温和善良之辈，而且出身卑下。当初是太宗皇帝的姬妾，曾因更衣的机会而得以奉侍左右。到后来，不顾伦常与太子（唐高宗李治）关系暧昧。隐瞒先帝曾对她的宠幸，谋求取得在宫中专宠的地位。选入宫里的妃嫔美女都遭到她的嫉妒，一个都不放过；她偏偏善于卖弄风情，象狐狸精那样迷住了皇上。终于穿着华丽的礼服，登上皇后的宝座，把君王推到乱伦的丑恶境地。加上一幅毒蛇般的心肠，凶残成性，亲近奸佞，残害忠良，杀戮兄姊，谋杀君王，毒死母亲。这种人为天神凡人所痛恨，为天地所不容。她还包藏祸心，图谋夺取帝位。皇上的爱子，被幽禁在冷宫里；而她的亲属党羽，却委派以重要的职位。呜呼！霍光这样忠贞的重臣，再也不见出现；刘章那样强悍的宗室也已消亡了。“燕啄皇孙”歌谣的出现，人们知道汉朝的皇统将要穷尽；孽龙的口水流淌在帝王的宫庭里，标志着夏后氏王朝快要衰亡。
我徐敬业是大唐的老臣下，是王公贵族的长子，奉行的是先帝留下的训示，承受着本朝的优厚恩典。宋微子为故国的覆灭而悲哀，确实是有他的原因的；桓谭为失去爵禄而流泪，难道是毫无道理的吗！因此我愤然而起来干一番事业，目的是为了安定大唐的江山。依随着天下的失望情绪，顺应着举国推仰的心愿，于是高举正义之旗，发誓要消除害人的妖物。南至偏远的百越，北到中原的三河，铁骑成群，战车相连。海陵的粟米多得发酵变红，仓库里的储存真是无穷无尽；大江之滨旌旗飘扬，光复大唐的伟大功业还会是遥远的吗！战马在北风中嘶鸣，宝剑之气直冲向天上的星斗。战士的怒吼使得山岳崩塌，云天变色。拿这来对付敌人，有什么敌人不能打垮；拿这来攻击城市，有什么城市不能占领！
诸位或者是世代蒙受国家的封爵，或者是皇室的姻亲，或者是负有重任的将军，或者是接受先帝遗命的大臣。先帝的话音好像还在耳边，你们的忠诚怎能忘却？先帝的坟土尚未干透，我们的幼主却不知被贬到哪里去了！如果能转变当前的祸难成为福祉，好好地送走死去的旧主和服事当今的皇上，共同建立匡救王室的功勋，不至于废弃先皇的遗命，那么各种封爵赏赐，一定如同泰山黄河那般牢固长久。如果留恋目前的既得利益，在关键时刻犹疑不决，看不清事先的征兆，就一定会招致严厉的惩罚。
请看明白今天的世界，到底是哪家的天下。这道檄文颁布到各州郡，让大家都知晓。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1e85914587d02f5a033", "shortContent": "弘道元年（683），唐高宗死去，太子李显即位（中宗），武则天临朝称制；翌年即废中宗为庐陵王，改立第四子李旦为帝（睿宗），实囚之于宫。武后大权在握，改东都洛阳为神都，悉改百官名称，积极筹建武周王朝。李唐宗室旧臣与武后集团长期以来的权利斗争更趋尖锐。李敬业是唐朝开国功臣英国公李勣（本姓徐，因有功赐姓李）的长孙，曾任太仆少卿、眉州刺史，这年因事谪柳州司马，便与其弟敬猷联络薛璋、唐之奇、杜求仁及客居扬州的...", "authors": ["熊", "笃"], "pressName": "上海辞书出版社"}]', '', 'indent', 1423168411, '57b90bb75bbb50005b787cae', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10135, '在狱咏蝉', NULL, 250, 132, 2, 1, '骆宾王', NULL, 10042, '57b9c1c5a34131005b0d7f6e', '唐', 'shi', '诗', 'http://baike.baidu.com/view/522450.htm', '余禁所禁垣西，是法厅事也，有古槐数株焉。虽生意可知，同殷仲文之古树；而听讼斯在，即周召伯之甘棠，每至夕照低阴，秋蝉疏引，发声幽息，有切尝闻，岂人心异于曩时，将虫响悲于前听？嗟乎，声以动容，德以象贤。故洁其身也，禀君子达人之高行；蜕其皮也，有仙都羽化之灵姿。候时而来，顺阴阳之数；应节为变，审藏用之机。有目斯开，不以道昏而昧其视；有翼自薄，不以俗厚而易其真。吟乔树之微风，韵姿天纵；饮高秋之坠露，清畏人知。仆失路艰虞，遭时徽纆。不哀伤而自怨，未摇落而先衰。闻蟪蛄之流声，悟平反之已奏；见螳螂之抱影，怯危机之未安。感而缀诗，贻诸知己。庶情沿物应，哀弱羽之飘零；道寄人知，悯余声之寂寞。非谓文墨，取代幽忧云尔。', '西陆蝉声唱，南冠客思深。
那堪玄鬓影，来对白头吟。
露重飞难进，风多响易沉。
无人信高洁，谁为表予心。', '这首诗作于唐高宗仪凤三年（公元678年）。当年，屈居下僚十多年而刚升为侍御史的骆宾王因上疏论事触忤武后，遭诬，以贪赃罪名下狱。闻一多先生说，骆宾王「天生一副侠骨，专喜欢管闲事，打抱不平、杀人报仇、革命，帮痴心女子打负心汉」（《宫体诗的自赎》）。这些话道出了骆宾王下狱的根本原因。他敢抗上司、敢动刀笔，于是被当权者以「贪赃」与「触忤武后」的罪名收系下狱。此诗是骆宾王身陷囹圄之作。
作者歌咏蝉的高洁品行，以蝉比兴，以蝉寓己，寓情于物，寄托遥深，蝉人浑然一体，抒发了诗人品行高洁却「遭时徽纆」的哀怨悲伤之情，表达了辨明无辜、昭雪沉冤的愿望。全诗情感充沛，取譬明切，用典自然，语意双关，达到了物我一体的境界，是咏物诗中的名作。', '「虽生意可知，同殷仲文之古树」句：东晋殷仲文，见大司马桓温府中老槐树，叹曰：「此树婆娑，无复生意。」借此自叹其不得志。这里即用其事。
「而听讼斯在，即周召伯之甘棠」句：传说周代召伯巡行，听民间之讼而不烦劳百姓，就在甘棠（即棠梨）下断案，后人因相戒不要损伤这树。召伯，即召公。周代燕国始祖名，因封邑在召（今陕西岐山西南）而得名。
曩时：前时。
将：抑或。
徽：捆绑罪犯的绳索，这里是被囚禁的意思。
缀诗：成诗。
西陆：指秋天。《隋书·天文志》：「日循黄道东行一日一夜行一度，三百六十五日有奇而周天。行东陆谓之春，行南陆谓之夏，行西陆谓之秋，行北陆谓之冬。」
南冠：楚冠，这里是囚徒的意思。用《左传·成公九年》，楚钟仪戴着南冠被囚于晋国军府事。
深：一作「侵」。
玄鬓：指蝉的黑色翅膀，这里比喻自己正当盛年。
那堪：一作「不堪」。
白头吟：乐府曲名。《乐府诗集》解题说是鲍照、张正见、虞世南诸作，皆自伤清直却遭诬谤。两句意谓，自己正当玄鬓之年，却来默诵《白头吟》那样哀怨的诗句。
露重：秋露浓重。
飞难进：是说蝉难以高飞。
响：指蝉声。
沉：沉没，掩盖。
高洁：清高洁白。古人认为蝉栖高饮露，是高洁之物。作者因以自喻。
予心：我的心。', '囚禁我的牢房的西墙外，是受案听讼的公堂，那里有数株古槐树。虽然能看出它们的勃勃生机，与东晋殷仲文所见到的槐树一样；但听讼公堂在此，像周代召伯巡行在棠树下断案一般。每到傍晚太阳光倾斜，秋蝉鸣唱，发出轻幽的声息，凄切悲凉超过先前所闻。难道是心情不同往昔，抑或是虫响比以前听到的更悲？唉呀，蝉声足以感动人，蝉的德行足以象征贤能。所以，它的清廉俭信，可说是禀承君子达人的崇高品德；它蜕皮之后，有羽化登上仙境的美妙身姿。等待时令而来，遵循自然规律；适应季节变化，洞察隐居和活动的时机。有眼就瞪得大大的，不因道路昏暗而不明其视；有翼能高飞却自甘澹泊，不因世俗浑浊而改变自己本质。在高树上临风吟唱，那姿态声韵真是天赐之美，饮用深秋天宇下的露水，洁身自好深怕为人所知。我的处境困忧，遭难被囚，即使不哀伤，也时时自怨，像树叶未曾凋零已经衰败。听到蝉鸣的声音，想到昭雪平反的奏章已经上报；但看到螳螂欲捕鸣蝉的影子，我又担心自身危险尚未解除。触景生情，感受很深，写成一诗，赠送给各位知己。希望我的情景能应鸣蝉征兆，同情我像微小秋蝉般的飘零境遇，说出来让大家知道，怜悯我最后悲鸣的寂寞心情。这不算为正式文章，只不过聊以解忧而已。
深秋季节西墙外寒蝉不停地鸣唱，蝉声把我这囚徒的愁绪带到远方。
怎堪忍受正当玄鬓盛年的好时光，独自吟诵白头吟这么哀怨的诗行。
露重翅薄欲飞不能世态多么炎凉，风多风大声响易沉难保自身芬芳。
无人知道我像秋蝉般的清廉高洁，有谁能为我表白冰晶玉洁的心肠？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e928b2e6a6b501f95be57", "shortContent": "这首诗作于高宗仪凤三年（678）。当时骆宾王任侍御史，因上疏论事触忤武后，遭诬，以贪赃罪名下狱。\n起二句在句法上用对偶句，在作法上则用起兴的手法，以蝉声来逗起客思。诗一开始即点出秋蝉高唱，触耳惊心。接下来就点出诗人在狱中深深怀想家园。\n三、四两句，一句说蝉，一句说自己，用“不堪”和“来对”构成流水对，把物我联系在一起。诗人几次讽谏武则天，以至下狱。大好的青春，经历了政治上的种种折磨已经消逝，头上增...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389abbb31680ae4c4b72c", "shortContent": "这首诗作于高宗仪凤三年（678）。当时骆宾王任侍御史，因上疏论事触忤武后，遭诬，以贪赃罪名下狱。\n\n起二句在句法上用对偶句，在作法上则用起兴的手法，以蝉声来逗起客思。诗一开始即点出秋蝉高唱，触耳惊心。接下来就点出诗人在狱中深深怀想家园。\n三、四两句，一句说蝉，一句说自己，用“不堪”和“来对”构成流水对，把物我联系在一起。诗人几次讽谏武则天，以至下狱。大好的青春，经历了政治上的种种折磨已经消逝，头上...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151bf", "shortContent": "此诗诗前有序云：“余禁所禁垣西，是法厅事也。有古槐数株焉。虽生意可知，同殷仲文之古树；而听讼斯在，即周召伯之甘棠。每至夕照低阴，秋蝉疏引，发声幽息，有切尝闻。岂人心异于曩时，将虫响悲乎前听？嗟乎！声以动容，德以象贤，故洁其身也，禀达人君子之高行；蜕其皮也，有仙都羽化之灵姿。候时而来，顺阴阳之数；应节为变，审藏用之机。有目斯开，不以道昏而昧其视；有翼自薄，不以俗厚而易其贞。吟乔树之微风，韵资天纵；饮...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63126fe2f2af4e09d55b66d8", "shortContent": "此诗诗前有序云：“余禁所禁垣西，是法厅事也。有古槐数株焉。虽生意可知，同殷仲文之古树；而听讼斯在，即周召伯之甘棠。每至夕照低阴，秋蝉疏引，发声幽息，有切尝闻。岂人心异于曩时，将虫响悲乎前听。嗟乎！声以动容，德以象贤，故洁其身也，禀君子达人之高行；蜕其皮也，有仙都羽化之灵姿。候时而来，顺阴阳之数；应节为变，审藏用之机。有目斯开，不以道昏而昧其视；有翼自薄，不以俗厚而易其真。吟乔树之微风，韵资天纵；饮...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270309761253910e904c8", "shortContent": "此诗诗前有序云：“余禁所禁垣西，是法曹厅事也。有古槐数株焉。虽生意可知，同殷仲文之枯树；而听讼斯在，即周召伯之甘棠。每至夕照低阴，秋蝉疏引，发声幽息，有切尝闻。岂人心异于曩时，将虫响悲乎前听。嗟乎！声以动容，德以象贤，故洁其身也，禀达人君子之高行；蜕其皮也，有仙都羽化之灵姿。候时而来，顺阴阳之数；应节为变，审藏用之机。有目斯开，不以道昏而昧其视；有翼自薄，不以俗厚而易其贞。吟乔树之微风，韵资天纵；...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '周珽《唐诗选脉会通评林》：次句映带「在狱」。三四流水对，清利。五六寓所思，深婉。尾「表」字应上「侵」字，「心」字应「思」字，有情。咏物诗，此与《秋雁》篇可称绝唱。
施补华《岘佣说诗》：《三百篇》比兴为多，唐人犹得此意。同一《咏蝉》，虞世南「居高声自远，非是藉秋风」，是清华人语；骆宾王「露重飞难进，风多响易沉」，是患难人语；李商隐「本以高难饱，徒劳恨费声」，是牢骚人语。比兴不同如此。
高步瀛《唐宋诗举要》：以蝉自喻，语意沉至。', 'center', 1416909390, '57b8ee1cd342d3005ac6b7f3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10136, '渔父四首', NULL, 211, 3406, 2, 1, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'https://baike.baidu.com/item/渔父四首/12664003', '', '渔父饮，谁家去。鱼蟹一时分付。酒无多少醉为期，彼此不论钱数。
渔父醉，蓑衣舞。醉时却寻归路。轻舟短棹任斜横，醒后不知何处。
渔父醒，春江午。梦断落花飞絮。酒醒还醉醉还醒，一笑人间今古。
渔父笑，轻鸥举。漠漠一江风雨。江边骑马是官人，借我孤舟南渡。', '元豐七年（公元一〇八四年），苏东坡从黄州调任汝州团练副使，第二年到河南商丘，收到诰命，宋神宗准许其在常州宜兴居住。想东坡半生凋零，屡遭贬谪，心内悽苦。而作於此间的四首《渔夫》组词（一说为组诗），颇得人生感慨。
第一首写渔父以鱼蟹与酒家换酒喝，彼此不计较价钱；第二首写渔父饮归，醉卧渔舟，任其东西，醒来不知身在何处；第三首写渔父在落花飞絮中醒来已是中午时分，醒复饮，饮复醉，醉复醒；第四首写渔父在风雨中与江鸥相伴，逍遥自在，奔波的官人借孤舟渡河。四篇作品既独立成篇，合起来又是一个整体，运用了描写、记叙和议论结合以及景、事、理融合的方法，生动地展示了渔父超然物外、悠闲自得的情景，充满了生活情趣。
东坡以最具特徵的饮、醉、醒、笑之行为来描写渔父的形象，并且借鉴了船子和尚的渔父，把渔父描写为已悟道的佛家渔父。全首渔父词在表面上描绘了渔父饮酒之乐，实际上赞美了以不同方法来施行教化和启导人生的渔父之慈悲心，并以此自比。词中具有一幅水墨画般的风景描写，无禅语而有禅味，寓禅理而不落形迹，颇得禅趣。', '渔父：词牌名。《钦定词谱》：「渔歌子，原唐教坊曲名。按《唐书·张志和传》，志和居江湖，自称江波钓徒，每垂钓不设铒，志不在鱼也。宪宗图真，求其人不能致。尝撰《渔歌》，即此词也。单调体实始于此。至双调体，昉自《花间集》顾夐、孙孟文。有魏承班、李德润诸词可校。若苏轼单调词，则又从双调词脱化耳。和凝词更名《渔父》，徐积词名《渔父乐》。按张志和所撰《渔歌子》词五首，体调如一，可以参校。」
题注：傅注本、元延祐本、明吴讷钞本、《苏长公二妙集》本、茅维《苏集》本、《东坡外集》、毛本均不收此四首，唯见《东坡集·卷十四》、宋刊《集注分类东坡先生诗》、清查初白撰《苏诗补注·卷二十五》及朱彊村《彊村丛书》本《东坡乐府·卷二》。
醉为期：龙榆生笺引《南史·卷七十五·〈隐逸列传·陶潜传〉》：「陶潜，字渊明，或云字深明，名元亮。寻阳柴桑人，晋大司马侃之曾孙也。少有高趣，宅边有五柳树，故常著《五柳先生》传云：『先生不知何许人，不详姓字。闲静少言，不慕荣利。好读书，不求甚解，每有会意，欣然忘食。性嗜酒，而家贫不能恒得。亲旧知其如此，或置酒招之，造饮辄尽，期在必醉。既醉而退，曾不吝情去留。环堵萧然，不蔽风日，裋褐「裋褐」各本作「短褐」，据《宋书》改。按《汉书·贡禹传》注：「裋，僮竖所著布长襦；褐，毛布之衣。」指粗服穿结，箪瓢屡空，晏如也。常著文章自娱，颇示己志，忘怀得失，以此自终。』」
蓑衣舞：龙榆生笺引唐·孟东野《送澹公》诗：「短蓑不怕雨，白鹭相争飞。短楫画菰蒲，斗作豪横归。笑伊水健儿，浪战求光辉。不如竹枝弓，射鸭无是非。」
酒醒：龙榆生笺唐·白乐天《自问行何迟》诗：「酒醒夜深后，睡足日高时。」
漠漠：龙榆生笺唐·杜少陵《滟滪》诗：「江天漠漠鸟双去，风雨时时龙一吟。」
官人：龙榆生笺「韩昌黎《王君墓誌》：『高处士曰：「吾以龃龉穷，一女，怜之，必嫁官人，不以与凡子。」』刘梦得《插田歌》：『君看二三年，我作官人去。』」
', '【其一】
渔父想饮酒，到哪一家去好呢？鱼和螃蟹同时交给了酒家换酒喝。饮酒不计多少量，一醉方休。渔父的鱼蟹与酒家的酒彼此之间何必谈论钱数。
【其二】
渔父酒醉了，披着蓑衣走路跌跌跄跄像跳舞。醉酒的渔父想寻找回去的归途。短桨小船无人执掌，任它随意漂流。酒醒后，渔父不知身在何处。
【其三】
渔父酒醒后，春江上时光已是正午。醒来只见阵阵落花飞絮。醒后还会再喝醉，醉后又会再醒。将古往今来人间的功名利禄付之一笑。
【其四】
渔父仰天大笑、吟唱，轻飘飘的江鸥在飞翔，宽阔的长江上吹洒满江风雨。江边骑马奔波的当差的小官，现在竟然借我的小船往南渡过长江。', '[{"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7bf2af4e09d55b6557", "shortContent": "四首《渔父》，《东坡纪年录》、孔《谱》未收。王文诰《苏诗总案》云：“《渔父词》起于三闾，诰向能以七弦道之。公又尝改张志和词为《鹧鸪天》。此四章亦其遗意，皆可谱入琴声也。”朱本据《苏轼诗集》编元丰八年乙丑（1085）。薛本从之，并云两首《调笑令》（渔父）（归雁）似为一时之作。曹本认为四首词必作于在黄州数年之间，“乙丑年自正月起，东坡仆仆风尘于泗州、南都、楚州、扬州。五月至常州贬所。六月起知登州，过润...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7bf2af4e09d55b6558", "shortContent": "同上首。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7bf2af4e09d55b6559", "shortContent": "同上首。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7bf2af4e09d55b655a", "shortContent": "同上首。", "authors": [], "pressName": "崇文书局"}]', '中国古典文学评论家陈迩冬《苏东坡诗词选》：「酒无多少醉无期」，一个出鱼、一个出酒、「彼此不论钱数」的渔人和酒家，或者是一个一个，或者是逐对逐对的出现。词读起来心旷神怡，有活力。」
苏轼研究专家孔凡礼《三苏年谱》：当轻鸥飞举、漠漠一江风雨之际，骑马江边之官人，藉渔父之孤舟南渡，其时渔父笑。其所以笑，当以此时可为此官人效力，此种效力，不为金钱，而为自觉之帮助，并以此为乐。', 'indent', 1423168576, '57b8ffe90a2b58005c9236fa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10137, '夏日绝句', NULL, 1166, 101, 2, 9, '李清照', NULL, 10043, '57b90879df0eea0063351b94', '宋', 'shi', '诗', 'http://baike.baidu.com/subview/305485/5819205.htm', '', '生当作人杰，死亦为鬼雄。
至今思项羽，不肯过江东。', '这首诗起调高亢，鲜明地提出了人生的价值取向，爱国激情，溢于言表，在当时确有振聋发聩的作用。南宋统治者不管百姓死活，只顾自己逃命；抛弃中原河山，苟且偷生。诗人鞭挞南宋当权派的无耻行径，借古讽今，正气凛然。全诗仅二十个字，连用了三个典故，慷慨雄健、掷地有声，但无堆砌之弊。', '人杰：人中豪杰。汉高祖曾称赞开国功臣张良、萧何、韩信是「人杰」。
鬼雄：鬼中英雄。屈原《国殇》：「身既死兮神以灵，子魂魄兮为鬼雄。」
项羽：秦末时自立为西楚霸王，与刘邦争夺天下，在垓下之战中，兵败自杀。
江东：项羽当初随叔父项梁起兵的地方。', '', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea72303572034f65a37fc", "shortContent": "李清照是我国历史上最著名的一位女词人，她的诗作传世很少，也不甚为世所称，这首五言绝句却是一首名作，传诵很广。\n诗意明白爽朗，所用的项羽故事，也是人人所知的熟典。她的词或轻柔婉丽，或缠绵悱恻，而诗则都是洗净儿女气的慷慨之音，和词风大不相同。\n这其实是一首借古讽今、发抒悲愤的怀古诗。北宋靖康二年（1127），腐败的宋王朝在金兵的沉重打击下瓦解，徽、钦二帝及赵氏亲属和大批臣民被掳北去。以当时的形势言，金...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "60fc32b023353c0ba53dd945", "bookTitle": "历代女性诗词鉴赏辞典", "articleId": "610ec78b2e6a6b501f9675c5", "shortContent": "这首诗又题作《乌江》，虽只四句二十字，但其中昂扬的爱国热情和犀利的批判矛头却使之成为李清照影响最大的诗歌，至今仍流传于妇孺之口。\n诗歌前两句发调惊挺，掷地有声。“人杰”出自《史记·高祖本纪》，指张良、萧何和韩信等贤臣良将；“鬼雄”出自屈原《九歌·国殇》：“身既死兮神以灵，魂魄毅兮为鬼雄。”高度凝练的诗句鲜明而响亮地唱出了李清照的人生价值观：为国捐躯，生死何惧！自先秦以来，这种爱国主义精神一直是中华...", "authors": ["王晓骊"], "pressName": "上海辞书出版社"}, {"bookId": "6277f84f8efdff05d7d6839b", "bookTitle": "李清照全集", "articleId": "6312258c73206168b2df9de2", "shortContent": "此诗另有题作《夏日绝句》，李清照南渡之后，建炎三年（1129年）赵明诚罢守江宁，李清照与丈夫具舟去芜湖。沿江而上时经过和县乌江（楚霸王项羽兵败自刎处）。此诗作于此时。此时，正“北兵仓皇南遁之时”也。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645d1153a2a0d66afdbadb39", "bookTitle": "李清照诗词鉴赏辞典", "articleId": "6464ac005e6bb82b8cc4598b", "shortContent": "李清照是我国历史上最著名的一位女词人，她的诗作传世很少，也不甚为世所称，这首五言绝句却是一首名作，传诵很广。\n\n诗意明白爽朗，所用的项羽故事，也是人人所知的熟典。她的词或轻柔婉丽，或缠绵悱恻，而诗则都是洗净儿女气的慷慨之音，和词风大不相同。\n\n这其实是一首借古讽今、发抒悲愤的怀古诗。北宋靖康二年（1127），腐败的宋王朝在金兵的沉重打击下瓦解，徽、钦二帝及赵氏亲属和大批臣民被掳北去。以当时的形势言...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646b2d46902ee364cc7860d0", "shortContent": "李清照是我国历史上最著名的一位女词人，她的诗作传世很少，也不甚为世所称，这首五言绝句却是一首名作，传诵很广。\n\n诗意明白爽朗，所用的项羽故事，也是人人所知的熟典。她的词或轻柔婉丽，或缠绵悱恻，而诗则都是洗净儿女气的慷慨之音，和词风大不相同。\n\n这其实是一首借古讽今、发抒悲愤的怀古诗。北宋靖康二年（1127），腐败的宋王朝在金兵的沉重打击下瓦解，徽、钦二帝及赵氏亲属和大批臣民被掳北去。以当时的形势言...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471e2d8e49f46528add33dd", "shortContent": "项羽在垓下一战，为刘邦所败，逃至乌江，乌江亭长劝他暂避江东，重振旗鼓，但他以“无颜见江东父老”而自杀。此事的得失可置之不论，但他的生为人杰、死为鬼雄的豪壮气概是令人感动的。举出项羽的不肯南渡，正是对怯懦畏葸、只顾逃命苟安的南宋君臣的辛辣讽刺。诗在字面上只是对千年以前英雄发感慨，但对时事的沉痛悲愤的谴责之情却溢于言表。\n李清照之所以有如此沉痛悲愤的感情，是因为她本人正是在朝廷败逃的情势下被弄得家破人...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472c16ea5f1e74f958a053d", "shortContent": "李清照是我国历史上最著名的一位女词人，她的诗作传世很少，也不甚为世所称，这首五言绝句却是一首名作，传诵很广。\n\n诗意明白爽朗，所用的项羽故事，也是人人所知的熟典。她的词或轻柔婉丽，或缠绵悱恻，而诗则都是洗净儿女气的慷慨之音，和词风大不相同。\n\n这其实是一首借古讽今、发抒悲愤的怀古诗。北宋靖康二年（1127），腐败的宋王朝在金兵的沉重打击下瓦解，徽、钦二帝及赵氏亲属和大批臣民被掳北去。以当时的形势言...", "authors": ["何满子"], "pressName": "上海辞书出版社"}]', '', 'center', 1362518160, '57b911dac4c97100558fb30e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10138, '如梦令', NULL, 2490, 101, 3, 15, '李清照', NULL, 10043, '57b90879df0eea0063351b94', '宋', 'ci', '词', 'http://baike.baidu.com/view/1945307.htm', '', '常记溪亭日暮，沉醉不知归路。兴尽晚回舟，误入藕花深处。争渡，争渡，惊起一滩鸥鹭。', '这是一首忆昔词，寥寥数语，似乎是随意而出，却又惜墨如金，句句含有深意。开头两句，写沉醉兴奋之情。接着写「兴尽」归家，又「误入」荷塘深处，别有天地，更令人流连。最后一句，纯洁天真，言尽而意不尽。这首《如梦令》以李易安特有的方式表达了她早期生活的情趣和心境，境界优美怡人，以尺幅之短给人以足够的美的享受。', '常记：常常记起。
沉醉：深入，程度深，醉到一定的程度但又有酣乐。
兴尽：尽，达到一定的程度，使自己的兴致得到极大的满足。兴：兴致。
藕花：荷花。《薛昭蕴·浣溪沙》：「越王宫殿半平芜，藕花菱蔓满重湖。」
争渡：这里指抢着争着奋力划船渡过。有注「怎渡」者，不宜从。
鸥鹭：鸥，鸟类的一科，羽毛多为白色，嘴扁平，前趾有蹼，翼长而尖。生活在湖海上，捕食鱼、螺等。鹭，鸟类的一科，翼大尾短，嘴直而尖，颈和腿很长，常见的有「白鹭」（亦称「鹭鸶」）、「苍鹭」、「绿鹭」等。鸥鹭，泛指水鸟。', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74d15914587d02f4670f", "shortContent": "现存李清照《如梦令》词有两阕，一是广为传诵的“昨夜雨疏风骤”，一即此篇。两相对照，颇多相似之处：都是记游赏之作，都写了酒醉、花美，都是那样的清新别致。后者虽然没有出现“绿肥红瘦”那样清奇的名句，但它同样以李清照特有的方式表达了她早期生活的情趣和心境，把读者带进了一个同样美好的文学天地。\n“常记”两句起得仿佛平了些，然而却又自然、和谐，似乎面对着一位知己娓娓地叙述，让人觉得作者完全忘记了是在填词，而...", "authors": ["魏同贤"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5d65914587d02f5904d", "shortContent": "现存李清照《如梦令》词有两阕，一是广为传诵的“昨夜雨疏风骤”，一即此篇。两相对照，颇多相似之处：都是记游赏之作，都写了酒醉、花美，都是那样的清新别致。后者虽然没有出现“绿肥红瘦”那样清奇的名句，但它同样以李清照特有的方式表达了她早期生活的情趣和心境，把读者带进了一个同样美好的文学天地。\n“常记”两句起得仿佛平了些，然而却又自然、和谐，似乎面对着一位知己娓娓地叙述，让人觉得作者完全忘记了是在填词，而...", "authors": ["魏同贤"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592544b56e213e684804b", "shortContent": "现存李清照《如梦令》词有两阕，一是广为传诵的“昨夜雨疏风骤”，一即此篇。两相对照，颇多相似之处：都是记游赏之作，都写了酒醉、花美，都是那样的清新别致。后者虽然没有出现“绿肥红瘦”那样清奇的名句，但它同样以李清照特有的方式表达了她早期生活的情趣和心境，把读者带进了一个同样美好的文学天地。\n\n“常记”两句起得仿佛平了些，然而却又自然、和谐，似乎面对着一位知己娓娓地叙述，让人觉得作者完全忘记了是在填词，...", "authors": ["魏同贤"], "pressName": "上海辞书出版社"}, {"bookId": "6277f84f8efdff05d7d6839b", "bookTitle": "李清照全集", "articleId": "6312258ac9ebcc6fbea1204a", "shortContent": "南宋·黄升《花庵词选》题作《酒兴》。《乐府雅词》等多种词书收为易安词。它追忆少女时代一次郊游活动。从内容和情调的欢快活泼来看，当是少女时代的作品。这首小令完整地叙述了整个游程、游兴、游感。既有感情的跌宕起伏，又有场景的动静结合，表现其卓尔不群的情趣，豪放潇洒的风姿，活泼开朗的性格。用白描的艺术手法，创造了一个具有平淡之美的艺术境界，给读者美的享受。", "authors": ["唐圭璋", "王璠", "薛祥生"], "pressName": "崇文书局"}, {"bookId": "645d1153a2a0d66afdbadb39", "bookTitle": "李清照诗词鉴赏辞典", "articleId": "6464a8edb6a81d0c53f3aee7", "shortContent": "现存李清照《如梦令》词有两阕，一是广为传诵的“昨夜雨疏风骤”，一即此篇。两相对照，颇多相似之处：都是记游赏之作，都写了酒醉、花美，都是那样的清新别致。后者虽然没有出现“绿肥红瘦”那样清奇的名句，但它同样以李清照特有的方式表达了她早期生活的情趣和心境，把读者带进了一个同样美好的文学天地。\n\n“常记”两句起得仿佛平了些，然而却又自然、和谐，似乎面对着一位知己娓娓地叙述，让人觉得作者完全忘记了是在填词，...", "authors": ["魏同贤"], "pressName": "上海辞书出版社"}]', '', 'indent', 1415646047, '57b9099da633bd00665d909c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10150, '水调歌头', NULL, 4395, 3406, 6, 24, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/538467.htm', '丙辰中秋，欢饮达旦，大醉，作此篇，兼怀子由。', '明月几时有？把酒问青天。不知天上宫阙，今夕是何年。我欲乘风归去，又恐琼楼玉宇，高处不胜寒。起舞弄清影，何似在人间。
转朱阁，低绮户，照无眠。不应有恨，何事长向别时圆？人有悲欢离合，月有阴晴圆缺，此事古难全。但愿人长久，千里共婵娟。', '此词作于神宗熙宁九年（西元一〇七六年）。当时，东坡为避开汴京的政治风波而在密州做官，其唯一的亲人弟弟子由则远在齐州任掌书记。中秋之夜，处在政治上失意及与亲人离别之中的东坡，不免有感于怀，故作此词。
这首词以月起兴，与弟子由七年未见之情为基础，围绕中秋明月展开想象和思考，把人世间的悲欢离合之情纳入对宇宙人生的哲理性追寻之中，反映了作者复杂而又矛盾的思想感情，又表现出作者热爱生活与积极向上的乐观精神。词作上阕反映执著人生，下阕表现善处人生。落笔潇洒，舒卷自如，情与景融，境与思偕，思想深刻而境界高逸，充满哲理，是东坡词的典范之作。此处所收版本取自影元本《东坡乐府》卷上。', '水调歌头：词牌名。调名来源自《水调》曲。《水调》曲，隋炀帝所制也。唐·刘鼎卿《隋唐嘉话》：「炀帝凿汴河，自制《水调歌》。」宋·王颐堂《碧鸡漫志·卷四·〈水调歌〉》引《脞说》：「《水调》《河传》，炀帝将幸江都时自制，声韵悲切，帝喜之。乐工王令言谓其弟子曰：『不返矣，《水调》《河传》但有去声。』」《〈樊川诗集〉注·卷三·〈扬州〉诗》「谁家唱《水调》」句自注亦云：「炀帝凿汴河成，自造《水调》。」然《水调》究制于开汴河前或汴河开成後，三家说法不一，但为炀帝自制，则无异辞。逮唐，《水调》已为传唱不衰之名曲。盛唐王龙标有《听流人〈水调子〉》诗：「岭色千重万重雨，断弦收与泪痕深。」唐·段安节《乐府杂录·歌》：「开元中，内人有许和子者，本吉州永新县乐家女也，开元末选入宫，即以永新名之，籍于宜春院。既美且慧，善歌，能变新声。……洎渔阳之乱，六宫星散，永新为一士人所得。（金吾将军）韦青避地广陵，因月夜凭阑于小河之上，忽闻舟中奏《水调》者，曰：『此永新歌也。』乃登舟与永新对泣久之。青始亦晦其事。」可见《水调》为时人所熟。玄宗本人亦喜听此曲，奔蜀之前，登楼置酒，令善唱《水调》者登楼而歌，「闻之，潸然出涕」（唐·李朱崖《次柳氏旧闻》，唐·郑延美《明皇杂录》）。中唐白乐天有《听〈水调〉》诗：「不会当时翻曲意，此声肠断为何人？」晚唐罗昭谏亦有《席上歌〈水调〉》：「若使炀皇魂魄在，为君应合过江来。」至五代北宋，《水调》仍在传唱。宋·郑仲贤《南唐旧事》载「（元宗）尝乘醉，命乐工杨花飞奏《水调辞》进酒。」南唐冯正中《抛球乐》亦有「《水调》声长醉里听」之句。北宋·张子野《天仙子》之「《水调》数声持酒听」更为人所熟。与子野同时而略晚的刘原甫《公是集》有《扬州闻歌》诗：「淮南旧有《于遮》舞，隋俗今传《水调》声。」一曲传唱四五百年，其魅力可见矣。唐时《水调》有大曲、小曲之分。大曲《水调》歌，「凡十一叠，前五叠为歌，後六叠为入破。其歌，第五叠五言调，声韵怨切。故白乐天诗云：『五言一遍最殷勤，调少情多似有因。不会当时翻曲意，此声肠断为何人？』」（《乐府诗集·卷七十九·〈水调〉歌》）按，《乐府诗集》所载十一叠《水调》，第一至第四叠（遍）歌为七言，第五叠为五言；入破第一至第五为七言，第六辙又为五言。《水调》小曲，为单曲歌唱（参任半塘《唐声诗·下编卷十三》）。王龙标所听《水调子》即是小曲。时《水调》主以笛奏，唐大曲《水调》第二叠歌辞即说「笛倚新翻《水调歌》」，冯正中《采桑子》：「《水调》何人吹笛声？」「唐又有新《水调》，亦商调曲也。」（《乐府诗集·卷七十九·〈水调〉歌》）《碧鸡漫志·卷四·〈水调歌〉》引白乐天《看采菱》诗所言「时唱一声新《水调》，谩人道是《采菱歌》」，即指「《水调》中新腔」。唐代《水调》，又指音调名，即一部乐之总名（非一曲之专名）。《唐会要·卷三十三》所载「南昌商，时号『水调』」，即指音调而言。《碧鸡漫志·卷四·〈水调歌〉》：「《理道要诀》所载唐乐曲，南吕商时号『水调』。予数见唐人说『水调』，各有不同。予因疑『水调』非曲名，乃俗呼音调之异名，今决矣。……《外史梼杌》云：『王衍泛舟巡阆中，舟子皆衣锦绣，自制水调《银汉曲》。』此『水调』中制《银汉曲》也。」王衍所制《银汉曲》，属「水调」乐部中之曲，故《银汉曲》前冠以「水调」。毛稚黄《填词名解·卷三》据此亦说：「水调者，一部乐之名也；《水调歌》者，一曲之名也。」《水调歌头》则是截取大曲《水调》之首章另倚新声而成。《填词名解》：「歌头，又曲之始音，如《六州歌头》、《氐州第一》之类。《海录碎事》云：『炀帝开汴河，自造《水调》，其歌颇多，谓之『歌头』，首章之一解也。顾从敬《诗馀笺释》云：『明皇欲幸蜀时，犹听唱《水调》，至「唯有年年秋雁飞」，因潸然，叹峤真才子！不待曲终。』水调曲颇广，因歌止首解，故谓之『歌头』。或云南唐元宗留心内宠，击鞫无虚日。乐工杨花飞奏《水调》词，但唱『南朝天子爱风流』一句，如是数四，以为讽谏。後人广其意为词，以其第一句，故称『水调歌头』云。」《水调歌头》与唐人《水调》所属宫调不同：唐《水调》，属商调曲；宋《水调歌头》，则为中吕调（《碧鸡漫志·卷四·〈水调歌〉》）。故《词谱·卷二十三》：「凡大曲歌头，另倚新声也。」毛东堂词名《元会曲》，张芸窗词名《凯歌》，吴梦窗词《江南好》，贺方回词名《台城游》，汪相如词名《水调歌》，姜白石词名《花犯念奴》，明杨升菴词名《花犯》。双调，九十五字，前後阕各四平韵。亦有前後阕两六言句夹叶仄韵者，有平仄互叶几于句句用韵者。
「明月几时有，把酒问青天」句：傅子立注引「青天有月来几时，我今停杯一问之。」
「今夕是何年」句：傅子立注引唐·杜少陵《今夕行》诗：「今夕何夕岁云徂。」
乘风：傅子立注：「《列子》：『随风东西，犹木叶干壳。竟不知我乘风邪，风乘我耶？』」刘尚荣按：「语见《列子·卷二·黄帝》，原文作『风乘我邪，我乘风乎』，傅注引文有误倒。」
又恐：另据明吴讷钞本、《苏长公二妙集》、毛本作「惟恐」。
琼楼：傅子立注：「唐段成式云：『翟天师尝于江上望月，或曰：「此中竟何有？」翟笑曰：「可随吾指观。」忽见月规半天，琼楼金阙满焉。顷刻不复见。』」刘尚荣按：「通行本《酉阳杂俎·前集卷二·壶史》所载与此微异，原文如下：『翟天师名乾祐，峡中人。长六尺。手大尺馀，每揖人，手过胸前。卧常虚枕。晚年往往言将来事。常入夔州市，大言曰：『今夕当有八人过此，可善待之。』人不之悟。其夜火焚数百家，八人乃『火』字也。每入山，虎群随之。曾于江岸与弟子数十玩月，或曰：『此中竟何有？』翟笑曰：『可随吾指观。』弟子中两人见月规半天，琼楼金阙满焉。数息间，不复见。』」
不胜寒：傅子立注：「《明皇杂录》：『八月十五日夜，叶能静邀上游月宫。将行，请上衣裘而往。及至月宫，寒凛特异，上不能禁。能静出丹二粒进上，服之，乃止。』」刘尚荣按：「今通行本《明皇杂录》无此条。」
起舞：傅子立注唐·李太白《月下独酌》诗：：「我歌月徘徊，我舞影零乱。」
照无眠：傅注本原误作「照不眠」，据诸本改。
有恨：傅子立注：「唐诗：『月如无恨月长圆。』」刘尚荣按：「《全唐诗》中无此句。司马温公《温公续诗话》：『李长吉歌「天若有情天亦老」，人以为奇绝无对。曼卿对「月如无恨月长圆」，人以为勍敌。』事别见《苕溪渔隐丛话·前集·卷五十三·的对》引《迂叟诗话》：『李长吉歌「天若有晴天亦老」，人以为奇艳无对。石曼卿对「月如无恨月长圆」，人以为勍敌。』石延年，字曼卿，北宋诗人。傅注似别有所据。」
阴晴圆缺：傅子立注：「公《中秋寄子由》诗云：『尝闻此宵月，万里阴晴圆。』」刘尚荣按：「《东坡集·卷九·中秋月三首》原句作：『万里同阴晴。』按此诗押『庚』韵，傅注引作『阴晴圆』者误也。又有东坡自注可證：『故人史生为余言：「尝见海贾云『中秋有月，则是岁珠多而圆。』贾人常以此候之，虽相去万里，他日会合，相问阴晴，无不同者。」』」
此事：傅注本原误作「此时」，据诸本改。
千里：傅子立注引南朝宋·谢希逸《月赋》：「美人邈兮音尘绝，隔千里兮共明月。」刘尚荣按：「《文选·卷三十二》『邈』作『迈』，『绝』作『阙』。又唐·许丁卯《送客》诗：『唯应洞庭月，万里共婵娟。』见《文苑英华·卷二百八十》。」', '丙辰年的中秋节，高兴地喝酒直到第二天早晨，喝到大醉，写了这首词，同时思念弟弟子由。
明月从什么时候才开始出现的？我端起酒杯遥问苍天。不知道在天上的宫殿，今天晚上是何年何月。我想要乘御清风回到天上，又恐怕在美玉砌成的楼宇，受不住高耸九天的寒冷。翩翩起舞玩赏着月下清影，（月宫）哪里比得上在人间？
月儿转过朱红色的楼阁，低低地挂在雕花的窗户上，照着没有睡意的自己。明月不该对人们有什么怨恨吧，为什么偏在人们离别时才圆呢？人有悲欢离合的变迁，月有阴晴圆缺的转换，这种事自古来难以周全。只希望这世上所有人的亲人能平安健康，即便相隔千里，也能共享这美好的月光。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74afd635634aee3d7171", "shortContent": "本篇长调词，作于宋神宗熙宁九年（1076），即丙辰年的中秋节日。时作者正任密州（今山东诸城）知州。从题序来看，这首词盖为醉后抒情，怀念兄弟（子由）之作。古人评论说：“此词前半自是天仙化人之笔”（清程洪、先著《词洁》）。今天看来，本词通篇风调，又何尝不是这样。至于明卓人月把本词比为“画家大斧皴，书家擘窠体”，则是囿于“苏词粗豪”的传统之见。揆诸实际，本篇除具苏词一般共有的豪迈清雄特色之外，它还有其飘...", "authors": ["徐翰逢", "陈长明"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b62e6a6b501f9672af", "shortContent": "本篇长调词，作于宋神宗熙宁九年（1076），即丙辰年的中秋节日。时作者正任密州（今山东诸城）知州。从题序来看，这首词盖为醉后抒情，怀念兄弟（子由）之作。古人评论说：“此词前半自是天仙化人之笔”（清程洪、先著《词洁》）。今天看来，本词通篇风调，又何尝不是这样。至于明卓人月把本词比为“画家大斧皴，书家擘窠体”，则是囿于“苏词粗豪”的传统之见。揆诸实际，本篇除具苏词一般共有的豪迈清雄特色之外，它还有其飘...", "authors": ["徐翰逢", "陈长明"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253f534825dee9fd6dc", "shortContent": "本篇长调词，作于宋神宗熙宁九年（1076），即丙辰年的中秋节日。时作者正任密州（今山东诸城）知州。从题序来看，这首词盖为醉后抒情，怀念兄弟（子由）之作。古人评论说：“此词前半自是天仙化人之笔”（清程洪、先著《词洁》）。今天看来，本词通篇风调，又何尝不是这样。至于明卓人月把本词比为“画家大斧皴，书家擘窠体”，则是囿于“苏词粗豪”的传统之见。揆诸实际，本篇除具苏词一般共有的豪迈清雄特色之外，它还有其飘...", "authors": ["徐翰逢", "陈长明"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e79f2af4e09d55b652f", "shortContent": "据词题可知，此词为熙宁九年丙辰（1076）中秋作于密州，时苏轼于超然台宴饮达旦。马里扬《苏轼词解读辨正六则》认为“琼楼玉宇”乃隐居之代称，“何似”当解为“何如”、“不如”，而“人间”则代指出仕。此词写作一年后，苏轼在另一首《水调歌头》（安石在东海）的《序》中说：“余去岁在东武，作《水调歌头》以寄子由。今年，子由相从彭城百余日。过中秋而去，作曲以别余，以其语过悲，乃为和之。其意以不早退为戒，以退而相...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3d73206168b2e020c2", "shortContent": "该词是咏中秋之名篇，宋代胡仔说：“中秋词自东坡《水调歌头》一出，余词尽废。”（《苕溪渔隐丛话》）其受推崇可见一斑。词前小序指出该词作于丙辰中秋，即神宗熙宁九年（1076），为怀念弟弟子由之作。时词人正在密州（今山东诸城）太守任上。\n上阕望月。中秋佳节，皓月当空，词人举起酒杯对天发问，追溯明月的起源、宇宙之伊始，此非东坡独创，屈原《天问》、太白《把酒问月》、张若虚《春江花月夜》诸篇已启其端。接着词人...", "authors": ["江宏泽"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702d77683d193301534a", "shortContent": "\n该词是咏中秋之名篇，宋代胡仔说：“中秋词自东坡《水调歌头》一出，余词尽废。”（《苕溪渔隐丛话》）其受推崇可见一斑。词前小序指出该词作于丙辰中秋，即神宗熙宁九年（1076），为怀念弟弟子由之作。时词人正在密州（今山东诸城）太守任上。\n\n上阕望月。中秋佳节，皓月当空，词人举起酒杯对天发问，追溯明月的起源、宇宙之伊始，此非东坡独创，屈原《天问》、太白《把酒问月》、张若虚《春江花月夜》诸篇已启其端。接着...", "authors": ["江宏泽"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312719c73206168b2e02355", "shortContent": "该词是咏中秋之名篇，宋代胡仔说：“中秋词自东坡《水调歌头》一出，余词尽废。”（《苕溪渔隐丛话》）其受推崇可见一斑。词前小序指出该词作于丙辰中秋，即神宗熙宁九年（1076），为怀念弟弟子由之作。时词人正在密州（今山东诸城）太守任上。\n上阕望月。中秋佳节，皓月当空，词人举起酒杯对天发问，追溯明月的起源、宇宙之伊始，此非东坡独创，屈原《天问》、太白《把酒问月》、张若虚《春江花月夜》诸篇已启其端。接着词人...", "authors": ["江宏泽"], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "64682b1d5e6bb82b8cd24787", "shortContent": "本篇长调词，作于宋神宗熙宁九年（1076），即丙辰年的中秋节日。时作者正任密州（今山东诸城）知州。从题序来看，这首词盖为醉后抒情，怀念兄弟（子由）之作。古人评论说：“此词前半自是天仙化人之笔”（清程洪、先著《词洁》）。今天看来，本词通篇风调，又何尝不是这样。至于明卓人月把本词比为“画家大斧皴，书家擘窠体”，则是囿于“苏词粗豪”的传统之见。揆诸实际，本篇除具苏词一般共有的豪迈清雄特色之外，它还有其飘...", "authors": ["徐翰逢", "陈长明"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "64720029b6a81d0c532b75aa", "shortContent": "《水调歌头》中秋词，是苏词代表性篇章之一。它落想奇拔，蹊径独辟，极富浪漫色彩。格调上，它“一洗绮罗香泽之态，摆脱绸缪宛转之度；使人登高望远，举首高歌”（胡寅《酒边词序》），是历来公认的中秋词中的绝唱。在表现上，本词前半纵写，后半横叙。前半高屋建瓴，后半峰回路转。前半是对古老神话传说、故事笔记的推陈出新，也是对魏晋六朝游仙诗的递嬗发展。后半白描素写，人月双济。它名为演绎物理，实则阐释人生。笔势错综回...", "authors": ["徐翰逢", "陈长明"], "pressName": "上海辞书出版社"}]', '宋·蔡百衲《铁围山丛谈·卷三》：歌者袁绹，乃天宝之李龟年也。宣和间，供奉九重。尝为吾言：「东坡公昔与客游金山，适中秋夕，天宇四垂，一碧无际，加江流澒涌，俄月色如画，遂共登金山山顶之妙高台，命绹歌其水调歌头曰：『明月何时有？把酒问青天。』歌罢，坡为起舞而顾问曰：『此便是神仙矣！』吾谓：『文章人物，诚千载一时，后世安所得乎？』」
宋·胡致堂《酒边集序》：一洗绮罗香泽之态，摆脱绸缪宛转之度，使人登高望远，举首而歌，而逸怀浩气，超然乎尘垢之外。
宋·胡苕溪《渔隐丛话前集·卷五十九》：先君尝云：坡词「低绮户」，尝云「窥绮户」。二字既改，其词益佳。
宋·胡仔《渔隐丛话后集·卷三十九》：中秋词，自东坡《水调歌头》一出，馀词俱废。
元·李冶《敬斋古今黈·卷八》：东坡水调歌头：「我欲乘风归去，唯恐琼楼玉宇，髙处不胜寒。起舞弄清影，何似在人间？」一时词手，多用此格。如鲁直云：「我欲穿花寻路，直入白云深处，浩气展虹蜺。只恐花深里，红露湿人衣。」盖效东坡语也。近世闲闲老赵秉文亦云：「我欲骑鲸归去，只恐神仙官府，嫌我醉时真。笑拍群仙手，几度梦中身？」
清·程洪、先著《词洁》：此词前半自是天仙化人之笔。
清·刘融斋《艺概·卷四》：词以不犯本位为髙。东坡满庭芳：「老去君恩未报，空回首弹铗悲歌。」语诚慷慨，究不若水调歌头：「我欲乘风归去，又恐琼楼玉宇，髙处不胜寒。」尤觉空灵蕴藉。
清·郑瘦碧评《东坡乐府》：发端从太白仙心脱化，顿成奇逸之笔。湘绮王闿运诵此词，以为此「全」字韵，可当「三语掾」，自来未经人道。', 'indent', 1413470122, '57b08d170a2b58006326dcd1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10139, '如梦令 · 昨夜雨疏风骤', NULL, 2937, 101, 3, 8, '李清照', NULL, 10043, '57b90879df0eea0063351b94', '宋', 'ci', '词', 'http://baike.baidu.com/item/如梦令·昨夜雨疏风骤', '', '昨夜雨疏风骤，浓睡不消残酒。试问卷帘人，却道海棠依旧。知否？知否？应是绿肥红瘦。', '春夜里大自然经历了一场风吹雨打，词人预感到庭园中的花木必然是绿叶繁茂，花事凋零了。因此，翌日清晨她急切地向「卷帘人」询问室外的变化，粗心的「卷帘人」却答之以「海棠依旧」。对此，词人禁不住连用两个「知否」与一个「应是」来纠正其观察的粗疏与回答的错误。「绿肥红瘦」一句，形象地反映出作者对春天将逝的惋惜之情。全词充分体现出作者对大自然、对春天的热爱，篇幅虽短，但含蓄蕴藉，意味深长，对人物的心理刻画栩栩如生，以对话推动词意发展，跌宕起伏，显示出作者深厚的艺术功力。', '如梦令：又名「忆仙姿」「宴桃源」。五代时后唐庄宗（李存勖）创作。《清真集》入「中吕调」。三十三字，五仄韵，一叠韵。
雨疏风骤：雨点稀疏，晚风急猛。疏，稀疏。
浓睡：酣睡。
残酒：尚未消散的醉意。
浓睡不消残酒：虽然睡了一夜，仍有馀醉未消。
卷帘人：有学者认为此指侍女。
绿肥红瘦：绿叶繁茂，红花凋零。', '昨夜雨虽然下得稀疏，风却刮得急猛，沉沉的酣睡却不能把残存的酒力全部消尽。问那正在卷帘的侍女：庭园里海棠花现在怎么样了？她说海棠花依然和昨天一样。你可知道，你可知道，这个时节应该是绿叶繁茂，红花凋零了。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74d1911759740c9aa3d6", "shortContent": "一篇小令，才共六句，好似一幅图画，并且还有对话，并且还交代了事情的来龙去脉，———这可能是现代的电影艺术才能胜任的一种“镜头”表现法，然而它却实实在在是九百年前的一位女词人自“编”自“演”的作品，不谓之奇迹，又将谓之何哉？\n她上来先交代原委，或者叫“背景”，说是昨宵雨狂风猛。疏，正写疏放疏狂，而非通常的稀疏义。当此芳春，名花正好，偏那风雨就来逼迫了，心绪如潮，不得入睡，只有借酒消忧一法，赖以排遣。...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5d6911759740c9bcb93", "shortContent": "一篇小令，才共六句，好似一幅图画，并且还有对话，并且还交待了事情的来龙去脉，———这可能是现代的电影艺术才能胜任的一种“镜头”表现法，然而它却实实在在是九百年前的一位女词人自“编”自“演”的作品，不谓之奇迹，又将谓之何哉？\n她上来先交待原委，或者叫“背景”，说是昨宵雨狂风猛。疏，正写疏放疏狂，而非通常的稀疏义。当此芳春，名花正好，偏那风雨就来逼迫了，心绪如潮，不得入睡，只有借酒消忧一法，赖以排遣。...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "60fc32b023353c0ba53dd945", "bookTitle": "历代女性诗词鉴赏辞典", "articleId": "610ec78b7d0ac1145495ebd0", "shortContent": "这首词当作于南渡之前，描写闺中惜花伤春之意。这是词中最常见的题材，在李清照之前早已佳作林立。但从审美效果而言，词作却给人以极大的新奇感，也因此赢得了一致好评，“当时文士莫不击节称赏，未有能道之者”（蒋一葵《尧山堂外纪》卷五十四）。\n这种新奇感首先来自于构思。《如梦令》的词意与晚唐韩偓的《懒起》“昨夜三更雨，临明一阵寒。海棠花在否？侧卧卷帘看”有一定的相似性，但词人又作了大胆的创新。这首词更像一出独...", "authors": ["王晓骊"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592544b56e213e684804c", "shortContent": "一篇小令，才共六句，好似一幅图画，并且还有对话，并且还交待了事情的来龙去脉，——这可能是现代的电影艺术才能胜任的一种“镜头”表现法，然而它却实实在在是九百年前的一位女词人自“编”自“演”的作品，不谓之奇迹，又将谓之何哉？\n\n她上来先交待原委，或者叫“背景”，说是昨宵雨狂风猛。疏，正写疏放疏狂，而非通常的稀疏义。当此芳春，名花正好，偏那风雨就来逼迫了，心绪如潮，不得入睡，只有借酒消忧一法，赖以排遣。...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277f84f8efdff05d7d6839b", "bookTitle": "李清照全集", "articleId": "6312258ac9ebcc6fbea1204b", "shortContent": "《词学筌蹄》题为《春晓》；《诗余画谱》题为《春景》；《花镜隽声》题为《春容》；《彤管遗编》等题为《暮春》，均可。当以末题为佳。\n\n这首惜春之作，抒发了少女时代李清照对大自然的热爱。全词语新意隽，通过对话曲折地表现出女主人对百花的怜惜，对春光的珍视，对美好事物的热爱。以构思新颖，造语精巧名垂千古。它化用了韩惺《懒起》诗句：“昨夜三更雨，今朝一阵寒。海棠花在否？侧卧卷帘看”，点铁成金。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f49c26cbf3417f09387", "shortContent": "此词别本题作“春晚”。有人说此词整个词意化用唐人韩惺《懒起》诗：“昨夜三更雨，临明一阵寒。海棠花在否？侧卧卷帘看。”但写法更为别致。小词借宿酒醒后询问花事的描写，反映出词人对大自然变化的敏感和对美好事物的真切关怀，曲折委婉地表达了少女怜花惜春的情愫和相思伤春的愁怀，语言清新自然而又含而不露。这首小令是李清照的奠定“才女”地位之作，轰动朝野。传闻就是这首词，使得赵明诚日夜作相思之梦，充分说明了这首小...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312703be6f69b71e93f623d", "shortContent": "此词别本题作“春晚”。有人说此词整个词意化用唐人韩偓《懒起》诗：“昨夜三更雨，临明一阵寒。海棠花在否？侧卧卷帘看。”但写法更为别致。小词借宿酒醒后询问花事的描写，反映出词人对大自然变化的敏感和对美好事物的真切关怀，曲折委婉地表达了少女怜花惜春的情愫和相思伤春的愁怀，语言清新自然而又含而不露。这首小令是李清照的奠定“才女”地位之作，轰动朝野。传闻就是这首词，使得赵明诚日夜作相思之梦，充分说明了这首小...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271e473206168b2e023af", "shortContent": "此词别本题作“春晚”。有人说此词整个词意化用唐人韩偓《懒起》诗：“昨夜三更雨，临明一阵寒。海棠花在否？侧卧卷帘看。”但写法更为别致。小词借宿酒醒后询问花事的描写，反映出词人对大自然变化的敏感和对美好事物的真切关怀，曲折委婉地表达了少女怜花惜春的情愫和相思伤春的愁怀，语言清新自然而又含而不露。这首小令是李清照的奠定“才女”地位之作，轰动朝野。传闻就是这首词，使得赵明诚日夜作相思之梦，充分说明了这首小...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d1153a2a0d66afdbadb39", "bookTitle": "李清照诗词鉴赏辞典", "articleId": "6464a8fe45e4710056c45195", "shortContent": "一篇小令，才共六句，好似一幅图画，并且还有对话，并且还交待了事情的来龙去脉，——这可能是现代的电影艺术才能胜任的一种“镜头”表现法，然而它却实实在在是九百年前的一位女词人自“编”自“演”的作品，不谓之奇迹，又将谓之何哉？\n\n她上来先交待原委，或者叫“背景”，说是昨宵雨狂风猛。疏，正写疏放疏狂，而非通常的稀疏义。当此芳春，名花正好，偏那风雨就来逼迫了，心绪如潮，不得入睡，只有借酒消忧一法，赖以排遣。...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}]', '宋·胡仔《苕溪渔隐丛话·前集·卷六十》：近时妇人能文词，如李易安，颇多佳句，小词云「昨夜雨疏风骤，浓睡不消残酒：试问卷帘人，却道海棠依旧。知否，知否？应是绿肥红瘦。」「绿肥红瘦」，此语甚新。
宋·陈郁《藏一话腴·内篇·卷下》：李易安工造语，《如梦令》「绿肥红瘦」之句，天下称之。余爱赵彦若《剪彩花》诗云「花随红意发，叶就绿情新。」「绿情」「红意」，似尤胜于李云。
明·蒋一葵《尧山堂外记·卷五十四》：李易安又有《如梦令》，云「昨夜雨疏风骤，浓睡不消残酒。试问卷帘人，却道海棠依旧。知否，知否？应是绿肥红瘦。」当时文士莫不击节称赏，未有能道之者。
明·沈际飞《草堂诗馀正集·卷一》：「知否」二字，叠得可味。「绿肥红瘦」创获自妇人，大奇。
明·徐士俊《古今词统·卷四》：《花间集》云：此词安顿二叠语最难。「知否，知否」，口气宛然。若他「人静，人静」、「无寐，无寐」，便不浑成。
明·徐伯龄《蟫精隽》：当时赵明诚妻李氏，号易安居士，诗词尤独步，缙绅咸推重之。其「绿肥红瘦」之句暨「人与黄花俱瘦」之语传播古今。
清·王士禛《花草蒙拾》：前辈谓史梅溪之句法，吴梦窗之字面，固是确论，尤须雕组而不失天然。如「绿肥红瘦」、「宠柳娇花」，人工天巧，可称绝唱。若「柳腴花瘦」，「蝶凄蜂惨」，即工，亦「巧匠斫山骨」矣。
清·黄苏《蓼园词选》：按：一问极有情，答以「依旧」，答得极澹，跌出「知否」二句来。而「绿肥红瘦」，无限凄婉，却又妙在含蓄。短幅中藏无数曲折，自是圣于词者。
清·陈廷焯《云韶集·卷十》：只数语中，层次曲折有味。世徒称其「绿肥红瘦」一语，犹是皮相。
清·陳廷焯《白雨斋词话·卷六》：词人好作精艳语，如左与言之「滴粉搓酥」，姜白石之「柳怯云松」，李易安之「绿肥红瘦」、「宠柳娇花」等类，造句虽工，然非大雅。', 'indent', 1362518337, '57b922e95bbb50005b794753', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10140, '点绛唇 · 蹴罢秋千', NULL, 654, 101, 1, 2, '李清照', NULL, 10043, '57b90879df0eea0063351b94', '宋', 'ci', '词', '', '', '蹴罢秋千，起来慵整纤纤手。露浓花瘦，薄汗轻衣透。
见客入来，袜刬金钗溜。和羞走，倚门回首，却把青梅嗅。', '此词描述少女的天真情态，上片写主人公下了鞦韆以後的情景，下片写主人公在来客忽至的羞赧情状，形象生动地刻画了一个天真纯洁、感情丰富却又矜持的少女形象。全词语言通俗，风格明快，节奏轻鬆，是李清照早年的代表作。', '点绛唇：词牌名。
蹴：踏。此处指打鞦韆。
慵：懒，倦怠的样子。
袜刬：这里指跑掉鞋子以袜着地。
金钗溜：意谓快跑时首饰从头上掉下来。
见客入来：一作「见有人来」。', '荡罢鞦韆起身，懒得揉搓细嫩的手。在她身旁，瘦瘦的花枝上挂着晶莹的露珠，她身上的涔涔香汗渗透着薄薄的罗衣。
突然进来一位客人，她慌得顾不上穿鞋，只穿着袜子抽身就走，连头上的金钗也滑落下来。她含羞跑开，倚靠门回头看，嗅在青梅，假装闻青梅的香味。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74d1dbb8b379ee08df14", "shortContent": "此词写少女初次萌动的爱情，真实而生动，当为清照早年作品。\n词的上片写荡完秋千的精神状态，妙在静中见动。词人没有写她荡秋千时的矫健身影和欢乐心情，而是剪取了“蹴罢秋千”以后一刹那间的镜头。此刻全部动作虽已停止，但仍可以想象得出她在荡秋千时的情景，罗衣轻飏，像燕子一样地在空中飞来飞去。“起来慵整纤纤手”，“慵整”二字用得非常恰切，令人想到她下秋千后已经极度疲劳，两手有些麻木，也懒得稍微活动一下。“纤纤...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5d52cee9a0c24ed9ea8", "shortContent": "此词写少女初次萌动的爱情，真实而生动，当为清照早年作品。\n词的上片写荡完秋千的精神状态，妙在静中见动。词人没有写她荡秋千时的矫健身影和欢乐心情，而是剪取了“蹴罢秋千”以后一刹那间的镜头。此刻全部动作虽已停止，但仍可以想象得出她在荡秋千时的情景，罗衣轻飏，像燕子一样地在空中飞来飞去。“起来慵整纤纤手”，“慵整”二字用得非常恰切，令人想到她下秋千后已经极度疲劳，两手有些麻木，也懒得稍微活动一下。“纤纤...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "60fc32b023353c0ba53dd945", "bookTitle": "历代女性诗词鉴赏辞典", "articleId": "610ec78b5e272d4b2254e2b1", "shortContent": "这首词是否为李清照所作，学者颇有争议。南宋王灼曾说李清照“作长短句能曲折尽人意，轻巧尖新，姿态百出”（《碧鸡漫志》卷二），这首词轻俏活泼的风格虽然与词人的其他作品有所不同，但却颇符合王灼“轻巧尖新，姿态百出”的评论，所以在确凿的文献证据发现之前，恐怕是不能轻易将之排除在李清照作品之外的。\n词作描写少女生活片断，上片写蹴秋千。秋千是宋代盛行的妇女之戏，宋人诗词多有描写，如欧阳修《浣溪沙》“绿杨楼外出...", "authors": ["王晓骊"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592544b56e213e6848049", "shortContent": "此词写少女初次萌动的爱情，真实而生动，当为清照早年作品。\n\n词的上片写荡完秋千的精神状态，妙在静中见动。词人没有写她荡秋千时的矫健身影和欢乐心情，而是剪取了“蹴罢秋千”以后一刹那间的镜头。此刻全部动作虽已停止，但仍可以想象得出她在荡秋千时的情景，罗衣轻飏，像燕子一样地在空中飞来飞去。“起来慵整纤纤手”，“慵整”二字用得非常恰切，令人想到她下秋千后已经极度疲劳，两手有些麻木，也懒得稍微活动一下。“纤...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "6277f84f8efdff05d7d6839b", "bookTitle": "李清照全集", "articleId": "6312258ac9ebcc6fbea1204c", "shortContent": "《续草堂诗余》题为《秋千》；扬金本《草堂诗余》题为《佳人》。可从前题。这首词当是婚前相亲时之作。通过富有个性化的一系列动作，使一个天真活泼有些顽皮的少女形象跃然纸上。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645d1153a2a0d66afdbadb39", "bookTitle": "李清照诗词鉴赏辞典", "articleId": "6464a84730675327e1893e00", "shortContent": "此词写少女初次萌动的爱情，真实而生动，当为清照早年作品。\n\n词的上片写荡完秋千的精神状态，妙在静中见动。词人没有写她荡秋千时的矫健身影和欢乐心情，而是剪取了“蹴罢秋千”以后一刹那间的镜头。此刻全部动作虽已停止，但仍可以想象得出她在荡秋千时的情景，罗衣轻飏，像燕子一样地在空中飞来飞去。“起来慵整纤纤手”, “慵整”二字用得非常恰切，令人想到她下秋千后已经极度疲劳，两手有些麻木，也懒得稍微活动一下。“...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}]', '明·钱功甫《续选草堂诗馀·巻上》：曲尽情悰。
明·沈震峰《草堂诗馀续集·巻上》：片时意态，淫夷万变。美人则然，纸上何遽能尔。
明·潘遊龙等《古今诗馀醉·巻十二》：「和羞走」下，如画。
清·贺黃公《皱水轩词筌》：至无名氏「见客人来袜刬金钗溜。和羞走，倚门回首，却把青梅嗅」直用「见客人来和笑走，手搓梅子映中门」二语演之耳。语虽工，终智在人後。
赵万里辑《漱玉词》：案词意浅薄，不似他作。末知升菴何据？
詹安泰《读词偶记》：女儿情态，曲曲绘出，非易安不能为此。求之宋人，未见其匹，耆卿、美成尚隔一尘。
王学初《李清照集校注》卷一：按1959年出版之北京大学学生编写之《中国文学史》第五编第四章，断定此首为易安作，评价颇高，恐未详考。《词林万选》中不可靠之词甚多，误题作者姓名之词，约有二三十首，非审慎不可也。
马兴荣：有人大约就是以封建社会的深闺少女总是遵守「礼」的、温顺的、循规蹈矩的、羞答答的这个尺度来衡量易安《点绛唇》这首词，所以怀疑它不像大家闺秀易安的作品。追求自由的易安假如地下有知的话，她是会笑这些人未免太封建了。（《中国古典文学鉴赏丛刊·唐宋词鉴赏集》，人民文学出版社1983年5月出版）
唐季特《读李清照词札记》：明杨慎《词林万选》卷四，误收易安一首《点绛唇》词云（略）。据《花草粹编》卷一收此词乃无名氏作，非易安词……且易安名门闺秀，少有诗名，亦不致不穿鞋而着袜行走。含羞迎笑，倚门回首，颇似市井妇女之行径，不类易安之为人，无名氏演韩偓诗，当有可能。（《南京师大学报》，1984年第二期）
裴斐：易安《词论》所谓「铺叙」，论者无解。窃谓此乃针对直抒胸臆而言，即主张有情节。这个主张，她自己是实行了的，从前期作品到南渡以後之作，无不如此。此首……当是易安早期作品。由前片「慵整纤纤手」到後片「袜刬金钗溜」再到「倚门回首，却把青梅嗅」，整首均为铺叙，极有层次，从而活脱出一个妩媚、敏感而矜持的少女，既见其外表情态，亦见其内心世界。历代词人当中，再没谁能如易安那样善于表达自己了！而这种表达，无论欢快或悲苦。均很少直接倾诉，而总是截取日常生活中一段情节加以铺叙，使你如闻其声，如见其人，深受其情绪感染。', 'indent', 1362518432, '57b8e297a34131005f900147', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10141, '醉花阴', NULL, 1145, 101, 2, 15, '李清照', NULL, 10043, '57b90879df0eea0063351b94', '宋', 'ci', '词', 'http://baike.baidu.com/view/1339687.htm', '', '薄雾浓云愁永昼，瑞脑销金兽。佳节又重阳，玉枕纱厨，半夜凉初透。
东篱把酒黄昏后，有暗香盈袖。莫道不销魂，帘卷西风，人比黄花瘦。', '这首词是作者婚后所作，通过描述作者重阳节把酒赏菊的情景，烘托了一种凄凉寂寥的氛围，表达了作者思念丈夫的孤独与寂寞的心情。上阕咏节令，写别愁；下阕写赏菊情景。作者在自然景物的描写中，加入自己浓重的感情色彩，使客观环境和人物内心的情绪融和交织。尤其是结尾三句，用黄花比喻人的憔悴，以瘦暗示相思之深，含蓄深沉，言有尽而意无穷，历来广为传诵。', '醉花阴：词牌名，又名「九日」，双调小令，仄韵格，五十二字，上下阕各五句三仄韵。
云：一作「雰」，一作「阴」。
愁永昼：愁难排遣觉得白天太长。永昼，漫长的白天。
瑞脑：一种薰香名。又称龙脑，即冰片。
销金兽：香炉里香料逐渐燃尽。金兽，兽形的铜香炉，一作「香兽」。
重阳：农历九月九日为重阳节。《周易》以「九」为阳数，日月皆值阳数，并且相重，故名。这是个古老的节日。南朝梁·庾肩吾《九日侍宴乐游苑应令诗》：「朔气绕相风，献寿重阳节。」
纱厨：即防蚊蝇的纱帐。宋·周美成《浣溪沙》：「薄薄纱厨望似空，簟纹如水浸芙蓉。」厨，一作「窗」，通：橱。
凉：一作「秋」。
东篱：泛指采菊之地。东晋·陶渊明《饮酒》：「采菊东篱下，悠然见南山。」为古今艳称之名句，故「东篱」亦成为诗人惯用之咏菊典故。
暗香：这里指菊花的幽香。
盈袖：满袖。《古诗十九首·庭中有奇树》：「攀条折其荣，将以遗所思。馨香盈怀袖，路远莫致之。」这里用其意。
销魂：形容极度忧愁、悲伤。南朝·江文通《别赋》：「黯然销魂者，惟别而已矣。」
帘卷西风：秋风吹动帘子。西风，秋风。
比：一作「似」。
黄花：指菊花。《礼记·月令》：「鞠有黄华」。鞠，本用菊。唐·王无功《九月九日》：「忽见黄花吐，方知素节回。」', '薄雾弥漫，云层浓密，日子过得愁烦，龙脑香在金兽香炉中缭袅。又到了重阳佳节，卧在玉枕纱帐中，半夜的凉气刚将全身浸透。
在东篱边饮酒直到黄昏以后，淡淡的黄菊清香溢满双袖。莫要说清秋不让人伤神，西风卷起珠帘，帘内的人儿比那黄花更加消瘦。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74d25914587d02f46716", "shortContent": "旧题元代伊世珍撰的《瑯嬛记》记载：“易安以重阳《醉花阴》词函致赵明诚。明诚叹赏，自愧弗逮，务欲胜之。一切谢客，忘食忘寝者三日夜，得五十阕，杂易安作以示友人陆德夫。德夫玩之再三，曰：‘只三句绝佳。’明诚诘之，答曰：‘莫道不消魂，帘卷西风，人比黄花瘦。’正易安作也。”这个故事未必可靠，但说明《醉花阴》颇有艺术特色，特别“莫道”三句妙绝，非他人所能及。\n这首词表面上写词人深秋时节的孤独寂寞之感，实际上，...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5d62cee9a0c24ed9eac", "shortContent": "旧题元代伊世珍撰的《瑯嬛记》记载：“易安以重阳《醉花阴》词函致赵明诚。明诚叹赏，自愧弗逮，务欲胜之。一切谢客，忘食忘寝者三日夜，得五十阕，杂易安作以示友人陆德夫。德夫玩之再三，曰：‘只三句绝佳。’明诚诘之，答曰：‘莫道不消魂，帘卷西风，人比黄花瘦。’正易安作也。”这个故事未必可靠，但说明《醉花阴》颇有艺术特色，特别“莫道”三句妙绝，非他人所能及。\n这首词表面上写词人深秋时节的孤独寂寞之感，实际上，...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "60fc32b023353c0ba53dd945", "bookTitle": "历代女性诗词鉴赏辞典", "articleId": "610ec78c2cee9a0c24eda204", "shortContent": "大观二年（1108年）重阳，赵明诚与朋友结伴出游，李清照留在青州归来堂独过佳节，这首词即描写词人对丈夫深切的思念之情。\n起句从天气入手，却很自然地切入到词人的心境。天气是阴沉沉的，词人内心也像这天气一样云遮雾绕，愁意难消。第二句描写闺中景象，“瑞脑”是名贵的香料，“金兽”是黄铜所铸的兽形香炉，瑞脑在精致的香炉中慢慢烧尽，闺中的生活看似宁静而闲适，却无处不渗透着寂寞。上阕的前两句描写永昼无聊之情，后...", "authors": ["王晓骊"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592544b56e213e6848050", "shortContent": "旧题元代伊世珍撰的《瑯嬛记》记载：“易安以重阳《醉花阴》词函致赵明诚。明诚叹赏，自愧弗逮，务欲胜之。一切谢客，忘食忘寝者三日夜，得五十阕，杂易安作以示友人陆德夫。德夫玩之再三，曰：‘只三句绝佳。’明诚诘之，答曰：‘莫道不消魂，帘卷西风，人比黄花瘦。’正易安作也。”这个故事未必可靠，但说明《醉花阴》颇有艺术特色，特别“莫道”三句妙绝，非他人所能及。\n\n这首词表面上写词人深秋时节的孤独寂寞之感，实际上...", "authors": ["高　原"], "pressName": "上海辞书出版社"}, {"bookId": "6277f84f8efdff05d7d6839b", "bookTitle": "李清照全集", "articleId": "6312258ae6f69b71e93ee1a1", "shortContent": "《乐府雅词》等多种词书题作《九日》，《草堂诗余》等题作《重阳》，《汇选历代名贤词府全集》题作《重九》，均可。《乐府雅词》等诸多词书收录为李清照词，是。这首小令抒写了在重阳佳节时寂寞无聊的心情。丈夫暂离，妻子承受着独居之苦，重阳佳节倍增寂寞。作者用“人比黄花瘦”，婉转传神，语创绝妙，雅唱空前，历代争诵。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f49c26cbf3417f09389", "shortContent": "这首词也是北宋末年时作。大观二年（1108）重阳节，赵明诚离乡在外任知州，李清照独守青州空闺，百无聊赖，难解寂寞，作此词，后来成为《漱玉词》中的佳作。\n上片写离愁。李清照很多词都是书写愁情，但是不同的情景，所用手法也不同，所以总会给读者一种新鲜的感觉。这首同是写愁的词章法却很别致，它特意按照时间顺序来写的。“薄雾浓云愁永昼”，从清晨写到白天，这轻薄的雾气加上浓浓的阴云，叫我如何消磨这漫长的白昼呢？...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312703be6f69b71e93f623f", "shortContent": "这首词也是北宋末年时作。大观二年（1108）重阳节，赵明诚离乡在外任知州，李清照独守青州空闺，百无聊赖，难解寂寞，作此词，后来成为《漱玉词》中的佳作。\n\n上片写离愁。李清照很多词都是书写愁情，但是不同的情景，所用手法也不同，所以总会给读者一种新鲜的感觉。这首同是写愁的词章法却很别致，它特意按照时间顺序来写的。“薄雾浓云愁永昼”，从清晨写到白天，这轻薄的雾气加上浓浓的阴云，叫我如何消磨这漫长的白昼呢...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271e473206168b2e023b0", "shortContent": "这首词也是北宋末年时作。大观二年（1108）重阳节，赵明诚离乡在外任知州，李清照独守青州空闺，百无聊赖，难解寂寞，作此词，后来成为《漱玉词》中的佳作。\n上片写离愁。李清照很多词都是书写愁情，但是不同的情景，所用手法也不同，所以总会给读者一种新鲜的感觉。这首同是写愁的词章法却很别致，它特意按照时间顺序来写的。“薄雾浓云愁永昼”，从清晨写到白天，这轻薄的雾气加上浓浓的阴云，叫我如何消磨这漫长的白昼呢？...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d1153a2a0d66afdbadb39", "bookTitle": "李清照诗词鉴赏辞典", "articleId": "6464aa2d30675327e1894697", "shortContent": "旧题元代伊世珍撰的《瑯嬛记》记载：“易安以重阳《醉花阴》词函致赵明诚。明诚叹赏，自愧弗逮，务欲胜之。一切谢客，忘食忘寝者三日夜，得五十阕，杂易安作以示友人陆德夫。德夫玩之再三，曰：‘只三句绝佳。’明诚诘之，答曰：‘莫道不消魂，帘卷西风，人比黄花瘦。’正易安作也。”这个故事未必可靠，但说明《醉花阴》颇有艺术特色，特别“莫道”三句妙绝，非他人所能及。\n\n这首词表面上写词人深秋时节的孤独寂寞之感，实际上...", "authors": ["高原"], "pressName": "上海辞书出版社"}]', '宋·胡元任《苕溪渔隐丛话·前集·卷六十》：又《九日》词云「帘捲西风，人似黄花瘦。」此语亦妇人所难到也。
元·伊世珍《琅嬛记·卷中》引《外传》：易安以《重阳·醉花阴》词函致明诚。明诚叹赏，自愧弗逮，务欲胜之。一切谢客，忘食忘寝者三日夜，得五十阕，杂易安作，以示友人陆德夫。德夫玩之再三，曰：「只三句绝佳。」明诚诘之。曰：「莫道不销魂，帘捲西风，人似黄花瘦。」正易安作也。
明·杨升菴批点本《草堂诗馀·卷一》：（批点末两句）凄语，怨而不怒。
明·茅远士《词的·卷二》：但知传诵结语，不知妙处全在「莫道不销魂」。
清·万紅友《词律·卷七》：《醉花阴》，沈氏极赏之，密圈到底，且加双层圈。呜呼！此岂有目者耶！按：《词谱》以毛泽民一首注云：换头第四字疑韵，如杨无咎词之「扑人飞絮浑无数」。李清照词之「东篱把酒黄昏后」，「絮」字「酒」字俱韵，此即《乐府指迷》所谓「藏短韵于句内」者。然宋词如此者亦少遵此。「酒」字应注叶。
清·周稚圭《晚香室词录·卷七》：愚按，《醉花阴》「帘捲西风」，为易安传作，其实寻常语耳。
清·许穆堂《自怡轩词谱·卷二》：幽细凄清，声情双绝。
清·许蒿庐《词综偶评》：结句亦从「人与绿杨俱瘦」脱出，但语意较工妙耳。
清·谭玉生《古今词辩》：绿肥红瘦语嫣然，人比黄花更可怜。若并诗中论位置，易安居士李青莲。
清·王湘绮《湘绮楼词选·前编》：此语若非出女子自写照，则无意致。「比」字各本皆作「似」，类书引，反不误。
清·陈亦峰《云韶集·卷十》：无一字不秀雅，深情苦调，元人词曲往往宗之。
近現代·王学初《李清照集校注·卷一》：按赵明诚喜金石刻，平生专力于此，不以词章名。《琅嬛记》所引《外传》，不知何书，殆出自捏造。所云「明诚欲胜之。」必非事实。
近現代·夏瞿禅《唐宋词欣赏》：在诗词中，作为警句，一般是不轻易拿出来的。这句「人比黄花瘦」之所以能给人深刻的印象，除了它本身运用比喻，描写出鲜明的人物形象之外，句子安排得妥当，也是其原因之一。她在这个结句的前面，先用一句「莫道不消魂」带动宕语气的句子作引，再加一句写动态的「帘捲西风」，这以后，才拿出「人比黄花瘦」警句来。人物到最后才出现。这警句不是孤立的，三句联成一气，前面两句环绕后面一句，起到绿叶红花的作用。经过作者的精心安排，好像电影中的一个特写镜头，形象性很强。这首词末了一个「瘦」字，归结全首词的情意，上面种种景物描写，都是为了表达这点精神，因而它确实称得上是「词眼」。以炼字来说，李清照另有《如梦令》「绿肥红瘦」之句，为人所传诵。这里她说的「人比黄花瘦」一句，也是前人未曾说过的，有它突出的创造性。
近現代·吴熊和《唐宋诗词探胜》：李清照论词鄙薄柳永「词语尘下」，这（指「莫道」句以下）三句就是柳词「衣带渐宽终不悔，为伊消得人憔悴」之意，表示思念之深。但表达时屏绝浮花浪蕊，选择了不求秾丽、自甘素淡的菊花，既是重九即景，又象征着一种高雅的情操。以它自比，温柔蕴藉，又绝无浮薄之嫌，更能反衬出作者不同凡俗的高标逸韵。
近現代·刘乃昌：全词是用洗练、本色的语言，写出经过艺术加工的真实日常生活图景，以显示自己的内心感情。
近現代·唐季特《唐宋词简释》：此首情深词苦，古今共赏。起言永昼无聊之情景，次言重阳佳节之感人。换头，言向晚把酒。着末，因花瘦而触及己瘦，伤感之至。尤妙在「莫道」二字唤起，与方回之「试问闲愁知几许」句，正同妙也。
近現代·余恕诚《百家唐宋词新话》：结尾「莫道不销魂，帘捲西风，人比黄花瘦。」「帘捲西风」，乍看可有可无，少此一笔似亦无损于诗意。实则不然。四字有「帘捲」、「西风」两个意象、「西风」以凄冷、萧瑟的一面加强了词的情调气氛，「帘捲」构成室内和室外的联系。没有「帘捲」，「人比黄花瘦」就变成单纯比喻。有此一笔，则交待出当帘捲西风之际，词人看到帘外黄花，因物生感迸发出了「人比黄花瘦」这样的心声。显得真切自然，而非作词时强拉来的比喻。又，词中前后两句写人，中间插以「帘捲西风」一句写景物，亦显得跌宕回肠，符合词人千回百转的感情节奏。', 'indent', 1413387094, '57b5afdc2e958a00563044ab', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10142, '鹧鸪天 · 桂花', NULL, 610, 101, 3, 3, '李清照', NULL, 10043, '57b90879df0eea0063351b94', '宋', 'ci', '词', 'http://baike.baidu.com/view/2766104.htm', '', '暗淡轻黄体性柔，情疏迹远只香留。何须浅碧深红色，自是花中第一流。
梅定妒，菊应羞，画阑开处冠中秋。骚人可煞无情思，何事当年不见收。', '李清照喜欢桂花酒，也喜欢桂花的风神气质。桂花貌不出众，色不诱人，但却「暗淡轻黄」、「情疏迹远」而又馥香自芳，这正是词人品格的写照，显示了词人卓而不群的审美品味。', '鹧鸪天：词牌名。小令词调，双阕五十五字，上阕四句三平韵，下阕五句三平韵。唐人郑嵎诗「春游鸡鹿塞，家在鹧鸪天」，调名取于此。又名《思佳客》、《思越人》、《剪朝霞》、《骊歌一叠》。
暗淡轻黄：形容桂花的颜色是暗黄、淡黄、轻黄。
体性柔：体质柔弱，性格和顺。体性，本指人的体貌与性情，这里指桂花。
疏：疏放。
迹远：桂树多生长于深山中，故云。
何须：犹何必，何用。
深红色：一作轻红色。
自是：自然是。
画阑：指饰有彩绘的栏杆。
冠：居于首位。
「画阑」句：化用唐·李贺《金铜仙人辞汉歌》的「画阑桂树悬秋香」之句意，谓桂花为中秋时节首屈一指的花木。
骚人：指屈原，因其作《离骚》，故称其为「骚人」。唐李白《古风五十九首》：「正声何微茫，哀怨起骚人。
可煞：表示疑问，犹可是，是否。
情思：情义。
何事：为何、何故。', '此花浅黄而清幽，形貌温顺又娇羞。性情萧疏远离尘世，它的浓香却久久存留。无须用浅绿或大红的色相去招摇炫弄，它本来就是花中的第一流。
梅花肯定妒忌它，而它又足以令迟开的菊花感到害羞。在装有华丽护栏的花园里，它在中秋的应时花木中无双无俦。大诗人屈原啊，可真叫无情无义，在写到诸多花木的《离骚》里，为何桂花不被收？', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74d27d0ac1145494bc30", "shortContent": "咏物诗词一般以咏物抒情为主，绝少议论。李清照的这首咏桂词一反传统，以议论入词，又托物抒怀。咏物既不乏形象，议论也能充满诗意，堪称别开生面。\n“暗淡轻黄体性柔，情疏迹远只香留。”短短十四字却形神兼备，写出了桂花的独特风韵。上句重在赋“色”，兼及体性；下句重在咏怀，突出“香”字。据有关记载，桂树花白者名银桂，黄者名金桂，红者为丹桂。它常生于高山之上，冬夏常青，以同类为林，间无杂树。又秋天开花者为多，其...", "authors": ["朱德才"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5d75e272d4b2254dfea", "shortContent": "咏物诗词一般以咏物抒情为主，绝少议论。李清照的这首咏桂词一反传统，以议论入词，又托物抒怀。咏物既不乏形象，议论也能充满诗意，堪称别开生面。\n“暗淡轻黄体性柔，情疏迹远只香留。”短短十四字却形神兼备，写出了桂花的独特风韵。上句重在赋“色”，兼及体性；下句重在咏怀，突出“香”字。据有关记载，桂树花白者名银桂，黄者名金桂，红者为丹桂。它常生于高山之上，冬夏常青，以同类为林，间无杂树。又秋天开花者为多，其...", "authors": ["朱德才"], "pressName": "上海辞书出版社"}, {"bookId": "60fc32b023353c0ba53dd945", "bookTitle": "历代女性诗词鉴赏辞典", "articleId": "610ec78c5914587d02f59303", "shortContent": "这是一首咏物词，描写桂花，当作于词人少年时期。宋代咏物词的表现形态无外乎两类：一是追求形似，对审美对象作穷纤极隐的描绘；二是借物寓志，这是古人咏物的真正用意。清代沈祥龙《论词随笔》云：“咏物之作，在借物以寓性情，凡身世之感、君国之忧，隐然蕴于其内，斯寄托遥深，非沾沾焉咏一物矣。”李清照这首词即带有明显的寄托性情的用意。\n词作起句直写桂花的形态，桂花花色浅淡，或黄或白；花体轻小，形如米粒，从外形来看...", "authors": ["王晓骊"], "pressName": "上海辞书出版社"}, {"bookId": "6277f84f8efdff05d7d6839b", "bookTitle": "李清照全集", "articleId": "6312258ac9ebcc6fbea12051", "shortContent": "这首词所咏为桂花。《全芳备祖》前集“桂花门”，清·汪灏《广群芳谱》卷四十“岩桂”均收录为易安词。本词在对桂花赞叹时，为其遭忌，深鸣不平，寄寓了自己的身世之感，家国之忧，“非沾沾焉咏一物矣”（沈祥龙评语）。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645d1153a2a0d66afdbadb39", "bookTitle": "李清照诗词鉴赏辞典", "articleId": "6464aa495fc8182fe99e524c", "shortContent": "咏物诗词一般以咏物抒情为主，绝少议论。李清照的这首咏桂词一反传统，以议论入词，又托物抒怀。咏物既不乏形象，议论也能充满诗意，堪称别开生面。\n\n“暗淡轻黄体性柔，情疏迹远只香留。”短短十四字却形神兼备，写出了桂花的独特风韵。上句重在赋“色”，兼及体性；下句重在咏怀，突出“香”字。据有关记载，桂树花白者名银桂，黄者名金桂，红者为丹桂。它常生于高山之上，冬夏常青，以同类为林，间无杂树。又秋天开花者为多，...", "authors": ["朱德才"], "pressName": "上海辞书出版社"}]', '王国维《人间词话》：「何须浅碧轻红色，自是花中第一流」，易安语也，其词品亦似之。', 'indent', 1413385761, '57b90bf97db2a2005426f7f4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10143, '一剪梅', NULL, 1457, 101, 5, 2, '李清照', NULL, 10043, '57b90879df0eea0063351b94', '宋', 'ci', '词', 'http://baike.baidu.com/item/一剪梅·红藕香残玉簟秋', '', '红藕香残玉簟秋。轻解罗裳，独上兰舟。云中谁寄锦书来？雁字回时，月满西楼。
花自飘零水自流。一种相思，两处闲愁。此情无计可消除，才下眉头，却上心头。', '此词作于词人与丈夫赵明诚离别之后，寄寓着作者不忍离别的一腔深情，反映出少妇沉溺于情海之中的纯洁心灵。作品以其清新的格调，女性特有的沉挚情感，丝毫「不落俗套」的表现方式，给人以美的享受，是一首工致精巧的别情词作。', '玉簟（diàn）秋：意谓时至深秋，精美的竹席已嫌清冷。
兰舟：《述异记》卷下谓：木质坚硬而有香味的木兰树是制作舟船的好材料，诗家遂以木兰舟或兰舟为舟之美称。一说「兰舟」特指睡眠的床榻。
锦书：对书信的一种美称。《晋书·窦滔妻苏氏传》云：苏蕙织锦为回文旋图诗，以赠其被徙流沙的丈夫窦滔。这种用锦织成的字称锦字，又称锦书。
雁字：群雁飞时常排成「一」字或「人」字，诗文中因以雁字称群飞的大雁。', '荷已残，香已消，冷滑如玉的竹席，透出深深的凉秋，轻轻脱换下薄纱罗裙，独自泛一叶兰舟。仰头凝望远天，那白云舒卷处，谁会将锦书寄来？正是雁群排成“人”字，一行行南归时候，月光皎洁浸人，洒满这西边独倚的亭楼。
花，自在地飘零，水，自在地漂流，一种离别的相思，你与我，牵动起两处的闲愁。啊，无法排除的是——这相思，这离愁，刚从微蹙的眉间消失，又隐隐缠绕上了心头。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74d234a8757d5a0d9e83", "shortContent": "这首词，据题名为元人伊世珍作的《瑯嬛记》引《外传》云：“易安结缡未久，明诚即负笈远游。易安殊不忍别，觅锦帕书《一剪梅》词以送之。”但如王学初在《李清照集校注》中所指出：“清照适赵明诚时，两家俱在东京，明诚正为太学生，无负笈远游事。此则所云，显非事实。”何况《瑯嬛记》本是伪书，所引《外传》更不知为何书，是不足为据的。玩味词意，这首词决不是作者与赵明诚分别时所写，而是作于远离后。\n词的起句“红藕香残玉...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5d603572034f65a8bb5", "shortContent": "这首词，据题名为元人伊世珍作的《瑯嬛记》引《外传》云：“易安结缡未久，明诚即负笈远游。易安殊不忍别，觅锦帕书《一剪梅》词以送之。”但如王学初在《李清照集校注》中所指出：“清照适赵明诚时，两家俱在东京，明诚正为太学生，无负笈远游事。此则所云，显非事实。”何况《瑯嬛记》本是伪书，所引《外传》更不知为何书，是不足为据的。玩味词意，这首词决不是作者与赵明诚分别时所写，而是作于远离后。\n词的起句“红藕香残玉...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "60fc32b023353c0ba53dd945", "bookTitle": "历代女性诗词鉴赏辞典", "articleId": "610ec78cc6e67846a92193c2", "shortContent": "这首词描写别愁，据元代伊世珍《瑯嬛记》载，李清照婚后不久，赵明诚即外出游学，清照不忍别离，以锦帕书此词以送之。不过，从词意来看，此词当写于离别之后。\n宋词特擅抒情，别愁更是常见的情感内容，不过大多数作品都以缠绵柔靡见长，这首词却在低回婉转之外，别具超逸清绝之气。首句“红藕香残玉簟秋”七字便营造了伤感而又空灵的抒情氛围，清代梁绍壬认为“有吞梅嚼雪不食人间烟火气象”（《两般秋雨庵随笔》）。“红藕”指荷...", "authors": ["王晓骊"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592544b56e213e684804e", "shortContent": "这首词，据题名为元人伊世珍作的《瑯嬛记》引《外传》云：“易安结缡未久，明诚即负笈远游。易安殊不忍别，觅锦帕书《一剪梅》词以送之。”但如王学初在《李清照集校注》中所指出：“清照适赵明诚时，两家俱在东京，明诚正为太学生，无负笈远游事。此则所云，显非事实。”何况《瑯嬛记》本是伪书，所引《外传》更不知为何书，是不足为据的。玩味词意，这首词决不是作者与赵明诚分别时所写，而是作于远离后。\n\n词的起句“红藕香残...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "6277f84f8efdff05d7d6839b", "bookTitle": "李清照全集", "articleId": "6312258ac9ebcc6fbea12057", "shortContent": "明·郦虎辑《彤管遗编》题作《一枝花》。宋·黄升《花庵词选》题为《别愁》，明·周瑛辑《词学筌谛》题为《离别》，清·夏秉衡辑《清琦轩词选》题为《闺思》。此词抒发作者对丈夫深厚的情意，吐露不忍离别之苦。它是李词代表作之一。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645d1153a2a0d66afdbadb39", "bookTitle": "李清照诗词鉴赏辞典", "articleId": "6464a99ec0471b0062cd17ee", "shortContent": "这首词，据题名为元人伊世珍作的《瑯嬛记》引《外传》云：“易安结缡未久，明诚即负笈远游。易安殊不忍别，觅锦帕书《一剪梅》词以送之。”但如王学初在《李清照集校注》中所指出：“清照适赵明诚时，两家俱在东京，明诚正为太学生，无负笈远游事。此则所云，显非事实。”何况《瑯嬛记》本是伪书，所引《外传》更不知为何书，是不足为据的。玩味词意，这首词决不是作者与赵明诚分别时所写，而是作于远离后。\n\n词的起句“红藕香残...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}]', '元·伊世珍《琅嬛记·卷中》引《外传》：易安结缡未久，明诚即负岌远遊。易安殊不忍别，觅锦帕书《一剪梅》词以送之。
明·杨升庵批点杨金本《草堂诗馀·卷三》：离情欲泪。读此始知高则诚、关汉卿诸人，又是效颦。
明·茅映《词的·卷三》：香弱脆溜，自是正宗。
明·李沧溟《草堂诗馀隽·卷五》眉批：「多情不随雁字去，空教一种上眉头。」评语：「惟锦书、雁字，不得将情传去，所以一种相思，眉头心头，在在难消。」
明·王凤洲《弇州山人词评》：李易安「此情无计可消除，方下眉头，又上心头。」可谓憔悴支离矣。
明·沈震峰《草堂诗馀正集·卷二》：时本落「西」字，作七字句，非调。是元人乐府妙句。关、郑、白、马诸君，固效颦耳。
明·李廷机《草堂诗馀评林·卷二》：此词颇尽离别之情，语意超逸，令人醒目。
明·张米庵《清河书画舫·申集》引《才妇录》：易安词稿一纸，乃清秘阁故物也。笔势清真可爱。此词《漱玉集》中亦载，所谓离别曲者耶？卷尾略无题识，仅有点定两字耳。录具于左：「（词略，唯「月满西楼」，作「月满楼」）」。右调（一剪梅）。
明·徐士俊《古今词统·卷十》：「楼」字上不必增「西」字。刘诚意「雁短人遥可奈何」亦七字句，仿此。
清·王阮亭《花草蒙拾》：俞仲茅小词云：「轮到相思没处辞，眉间露一丝。」视易安「纔下眉头，却上心头」，可谓此儿善盗。然易安亦从范希文「都来此事，眉间心上，无计相回避」语脱胎，李特工耳。
清·沈偶僧《古今词话·词辨·卷上》：周永年曰：《一剪梅》唯易安作为善。刘后村换头亦用平字，于调未叶。若「云中谁寄锦书来」，与「此情无计可消除」，「来」字、「除」字，不必用韵，似俱出韵。但「雁字回时月满楼」，「楼」字上失一「西」字。刘青田「雁短人遥可奈何」，「楼」上似不必增「西」字。今南曲只以前段作引子，词家复就单调，别名「剪半」。将法曲之被管弦者，渐不可究诘矣。
清·万红友《词律·卷九》：「月满楼」，或作「月满西楼」。不知此调与他词异。如「裳」、「思」、「来」、「除」等字，皆不用韵，原与四段排比者不同。「雁字」句七字，自是古调。何必强其入俗，而添一「西」字以凑八字乎？人若欲填排偶之句，自有别体在也。
清·张藕村《词林纪事·卷十九》：此《一剪梅》，变体也。前段第五句原本无「西」字，后人所增。旧谱谓脱去一字者，非。又按：《汲古阁宋词》，此阕载入《惜香乐府》，恐误。
清·梁晋竹《两般秋雨庵随笔·卷三》：易安《一剪梅》词起句「红藕香残玉簟秋」七字，便有吞梅嚼雪，不识人间烟火气象，其实寻常不经意语也。
清·陈亦峰《云韶集·卷十》：起七字秀绝，真不食人间烟火者。梁绍壬谓：只起七字已是他人不能到。结更凄绝。
清·陈亦峰《白雨斋词话·卷二》：易安佳句，如《一剪梅》起七字云：「红藕香残玉簟秋」，精秀特绝，真不食人间烟火者。
清·况夔笙《〈漱玉词〉笺》：玉梅词隐云，易安精研宫律，所以何至出韵。周美成倚声传家，为南北宋关键，其《一剪梅》第四句均不用韵，讵皆出韵耶？窃谓《一剪梅》调当以第四句不用韵一体为最早，晚近作者，好为靡靡之音，徒事和畅，乃添入此叶耳。
王学初《〈李清照集〉校注·卷一》：又按，易安适赵德甫时，两家俱在东京，德甫正为太学生，无负岌远遊事。此则（指本辑评「一」）所云，显非事实。而易安父（李文叔）称为李翁，一似不知其名者，尤见芜陋。《琅嬛记》乃伪书，不足据。', 'indent', 1423168769, '57b2bb0f7db2a2005436fede', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (43796, '题曾省元藏温日观葡萄后用温师韵', NULL, 0, 12, 0, 1, '陆居仁', NULL, 11088, '5858e61f61ff4b0063d6f4dc', '元', 'shi', '诗', NULL, NULL, '黄金台壮帝王州，我亦曾为汗漫游。
不入凤池鹓鹭序，依然天地一沙鸥。', NULL, NULL, NULL, NULL, NULL, 'center', 1525432791, '585ce9811b69e600560ea64b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10145, '声声慢', NULL, 2498, 101, 7, 13, '李清照', NULL, 10043, '57b90879df0eea0063351b94', '宋', 'ci', '词', 'http://baike.baidu.com/view/649291.htm', '', '寻寻觅觅，冷冷清清，凄凄惨惨戚戚。乍暖还寒时候，最难将息。三杯两盏淡酒，怎敌他、晚来风急！雁过也，正伤心，却是旧时相识。
满地黄花堆积，憔悴损，如今有谁堪摘？守着窗儿，独自怎生得黑！梧桐更兼细雨，到黄昏、点点滴滴。这次第，怎一个愁字了得！', '此词为悲秋抒怀之作。靖康之难后，李易安随其夫赵德甫逃亡江南，宋高宗建炎三年（西元一一二九年）秋八月十八日赵明诚亡故。此词在其夫亡后所作，是抒发家国身世愁之作。首用七对叠字发端，「寻寻觅觅」写国破家亡夫死己寡之后的精神失落，独身彷徨之情状，「冷冷清清」则写时世、境况之凄清冷寂，「凄凄」句更细腻深微地描摹词人心情的悲苦凄戚。薄酒难御风寒，过雁触动乡思，菊花萎谢无人怜惜，独守寒窗时间难熬，黄昏冷雨敲击梧桐，种种场景，无不益发加重愁情分量，折磨一己孤独、柔弱、痛苦的灵魂。全篇字字写愁，层层写愁，却不露一「愁」字，末尾句画龙点睛，以「愁」归结，而又谓「愁」不足以概括个人处境，推进一层，愁情之重，实无法估量。全词用白描铺叙，讲究声情，巧用叠字，更以舌齿音交加更替，传达幽咽凄楚情悰，肠断心碎，满纸呜咽，撼人心弦。', '寻寻觅觅：意谓想把失去的一切都找回来，表现非常空虚怅惘、迷茫失落的心态。
凄凄惨惨戚戚：忧愁苦闷的样子。
乍暖还（huán）寒：指秋天的天气，忽然变暖，又转寒冷。
将息：旧时方言，休养调理之意。
怎敌他：对付，抵挡。
晚：一本作「晓」。
损：表示程度极高。
堪：可。
着：亦写作「著」。
怎生：怎样的。生：语助词。
梧桐更兼细雨：暗用白居易《长恨歌》「秋雨梧桐叶落时」诗意。
这次第：这光景、这情形。
怎一个愁字了得：一个「愁」字怎么能概括得尽呢？', '整天都在寻觅一切清冷惨淡，我不由感到极度的哀伤凄凉。乍暖还寒的秋季最难以调养。饮三杯两盏淡酒怎能抵御它、傍晚之时来的冷风吹的紧急。向南避寒的大雁已飞过去了，伤心的是却是原来的旧日相识。
家中的后园中已开满了菊花，我因忧伤憔悴无心赏花惜花、如今花儿将败还有谁能采摘？静坐窗前独自熬到天色昏黑？梧桐凄凄细雨淅沥黄昏时分、那雨声还点点滴滴。此情此景，用一个愁字又怎么能说的够？', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74d35e272d4b2253bbe8", "shortContent": "唐宋古文家以散文为赋，而倚声家实以慢词为赋。慢词具有赋的铺叙特点，且蕴藉流利，匀整而富变化，堪称“赋之余”。李清照这首《声声慢》，脍炙人口数百年，就其内容而言，简直是一篇悲秋赋。亦惟有以赋体读之，乃得其旨。李清照的这首词在作法上是有创造性的。原来的《声声慢》的曲调，韵脚押平声字，调子相应地也比较徐缓。而这首词却改押入声韵，并屡用叠字和双声字，这就变舒缓为急促，变哀惋为凄厉。此词以豪放纵恣之笔写激动...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5d703572034f65a8bbd", "shortContent": "唐宋古文家以散文为赋，而倚声家实以慢词为赋。慢词具有赋的铺叙特点，且蕴藉流利，匀整而富变化，堪称“赋之余”。李清照这首《声声慢》，脍炙人口数百年，就其内容而言，简直是一篇悲秋赋。亦惟有以赋体读之，乃得其旨。李清照的这首词在作法上是有创造性的。原来的《声声慢》的曲调，韵脚押平声字，调子相应地也比较徐缓。而这首词却改押入声韵，并屡用叠字和双声字，这就变舒缓为急促，变哀惋为凄厉。此词以豪放纵恣之笔写激动...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "60fc32b023353c0ba53dd945", "bookTitle": "历代女性诗词鉴赏辞典", "articleId": "610ec78c5914587d02f59304", "shortContent": "这首《声声慢》，是在易安词中被称述和评说得最多的一篇作品，也是其美感特质表现得最为女性化的一阕词作。\n该词之所以被很多人称述评说，其重点往往落在开端所用的十四个叠字之上。最早的一个称述其叠字之人，乃是宋朝的张端义。张氏在其《贵耳集》中，曾谓其开端所用的十四个叠字：“乃公孙大娘舞剑手。本朝非无能词之士，未曾有一下十四叠字者。”又曾称美此词之后半阕云：“‘梧桐更兼细雨，到黄昏、点点滴滴’又使叠字，俱无...", "authors": ["叶嘉莹"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592544b56e213e6848054", "shortContent": "唐宋古文家以散文为赋，而倚声家实以慢词为赋。慢词具有赋的铺叙特点，且蕴藉流利，匀整而富变化，堪称“赋之余”。李清照这首《声声慢》，脍炙人口数百年，就其内容而言，简直是一篇悲秋赋。亦惟有以赋体读之，乃得其旨。李清照的这首词在作法上是有创造性的。原来的《声声慢》的曲调，韵脚押平声字，调子相应地也比较徐缓。而这首词却改押入声韵，并屡用叠字和双声字，这就变舒缓为急促，变哀惋为凄厉。此词以豪放纵恣之笔写激动...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "6277f84f8efdff05d7d6839b", "bookTitle": "李清照全集", "articleId": "6312258a77683d193300d3be", "shortContent": "此词《三百词谱》调名作《梧桐雨》。《词的》等题作《秋情》，明·赵世杰《古今女史〉〉题作《秋晴》，明·卓人月《古今词统》等题作《秋闺》，清·谢元淮《碎金词谱》题作《秋词》，明·杨慎《词品》等诸多词书收为易安词。当写于赵明诚逝世后。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f49c26cbf3417f0938a", "shortContent": "这首词堪称李清照词集中的压卷之作，其所表现的凄苦愁绪，已不是前面所选词作可以比拟的了。这种变化，也是因现实生活的改变所造成的。靖康之变后，李清照个人的闲适恬静的生活也被打破。南宋建立后李清照随夫南下江宁，建炎三年（1129）丈夫赵明诚去世，时清照46岁。接着金兵深入南下，她又到处流亡。再后来，她与赵明诚生前收集的金石古玩大多丢失，清照的境况也变得越来越艰难。一连串的变故，李清照的性格也由开朗变得忧...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312703be6f69b71e93f6240", "shortContent": "这首词堪称李清照词集中的压卷之作，其所表现的凄苦愁绪，已不是前面所选词作可以比拟的了。这种变化，也是因现实生活的改变所造成的。靖康之变后，李清照个人的闲适恬静的生活也被打破。南宋建立后李清照随夫南下江宁，建炎三年（1129）丈夫赵明诚去世，时清照46岁。接着金兵深入南下，她又到处流亡。再后来，她与赵明诚生前收集的金石古玩大多丢失，清照的境况也变得越来越艰难。一连串的变故，李清照的性格也由开朗变得忧...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271e473206168b2e023b1", "shortContent": "这首词堪称李清照词集中的压卷之作，其所表现的凄苦愁绪，已不是前面所选词作可以比拟的了。这种变化，也是因现实生活的改变所造成的。靖康之变后，李清照个人的闲适恬静的生活也被打破。南宋建立后李清照随夫南下江宁，1129年丈夫赵明诚去世，时清照46岁，接着金兵深入南下，她又到处流亡，再后来，赵明诚生前收集的金石古玩大多丢失，清照的境况也变得越来越艰难。一连串的变故中，李清照的性格也由开朗变得忧郁。\n李清照...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d1153a2a0d66afdbadb39", "bookTitle": "李清照诗词鉴赏辞典", "articleId": "6464aac85e6bb82b8cc4540c", "shortContent": "唐宋古文家以散文为赋，而倚声家实以慢词为赋。慢词具有赋的铺叙特点，且蕴藉流利，匀整而富变化，堪称“赋之余”。李清照这首《声声慢》，脍炙人口数百年，就其内容而言，简直是一篇悲秋赋。亦惟有以赋体读之，乃得其旨。李清照的这首词在作法上是有创造性的。原来的《声声慢》的曲调，韵脚押平声字，调子相应地也比较徐缓。而这首词却改押入声韵，并屡用叠字和双声字，这就变舒缓为急促，变哀婉为凄厉。此词以豪放纵恣之笔写激动...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f351b7da2f75ac7149155", "shortContent": "唐宋古文家以散文为赋，而倚声家实以慢词为赋。慢词具有赋的铺叙特点，且蕴藉流利，匀整而富变化，堪称“赋之余”。李清照这首《声声慢》，脍炙人口数百年，就其内容而言，简直是一篇悲秋赋。亦惟有以赋体读之，乃得其旨。李清照的这首词在作法上是有创造性的。原来的《声声慢》的曲调，韵脚押平声字，调子相应地也比较徐缓。而这首词却改押入声韵，并屡用叠字和双声字，这就变舒缓为急促，变哀惋为凄厉。此词以豪放纵恣之笔写激动...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}]', '宋张端义《贵耳集》卷上：炼句精巧则易，平淡入调者难。且《秋词·声声慢》：「寻寻觅觅，冷冷清清，凄凄惨惨戚戚。」此乃公孙大娘舞剑手。本朝非无能词之士，未曾有一下十四叠字者，用《文选》诸赋格。后叠又云：「梧桐更兼细雨，到黄昏、点点滴滴。」又使叠字，俱无斧凿痕。更有一奇字云：「守定窗儿，独自怎生得黑。」「黑」字不许第二人押。妇人中有此文笔，殆间气也。
宋罗大经《鹤林玉露》卷十二：近时李易安词云：「寻寻觅觅，冷冷清清，凄凄惨惨戚戚。」起头连叠七字。以一妇人，乃能创意出奇如此。
明杨慎《词品》卷二：宋人中填词，李易安亦称冠绝。使在衣冠，当与秦七、黄九争雄，不独雄于闺阁也。其词名《漱玉集》，寻之未得。《声声慢》一词，最为婉妙。其词云（略）……山谷所谓以故为新，以俗为雅者，易安先得之矣。
明茅映《词的》卷四：这用十四叠字，后又四叠字，情景婉绝，真是绝唱。后人效颦，便觉不妥。
明陆云龙《词菁》卷二：连下叠字无迹，能手。「黑」字妙绝。
明徐士俊《古今词统》卷十二：（眉批）才一斛，愁千斛，虽六斛明珠何以易之！
清刘体仁《七颂堂词绎》：惟易安居士「最难将息」、「怎一个愁字了得」、深妙稳雅，不落蒜酪、亦不落绝句，真此道本色当行第一人也。', 'indent', 1419285994, '57b5e0aa165abd0065d4442a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10146, '阮郎归 · 初夏', NULL, 565, 3406, 3, 4, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/865013.htm', '', '绿槐高柳咽新蝉，薰风初入弦。碧纱窗下水沉烟，棋声惊昼眠。
微雨过，小荷翻，榴花开欲然。玉盆纤手弄清泉，琼珠碎却圆。', '此词表现了初夏时节的闺阁生活，采用从反面落笔的手法，上阕写静美，而从听觉入手，以声响状环境之寂，下阕写动美，却从视觉落笔，用一幅幅无声画来展示大自然的生机，营造出一种清丽欢快的情调，显得淡雅清新而又富于生活情趣。全词以描写手法为主，注意景物描写、环境描写和人物描写的交叉运用，从而获得了极好的艺术效果。', '阮郎归：词牌名。唐教坊曲有《阮郎迷》，疑为其初名。词名用刘晨、阮肇故事。相传东汉永平年间，浙江剡县人刘晨、阮肇入天台山采药迷路，遇二仙女，被邀至家。留住半年，思归甚苦。既归则乡邑零落，已十世。二人重返天台访仙女，踪迹已杳。详见《太平广记·卷六十一·天台二女》引《神仙记》。曲名本此，韵密而平和，故作凄音。宋人用此调者甚众。双调，四十七字，前後阕各四平韵。曲牌名，有二，均属南曲南吕宫。其一字句格律与词牌同，但多仅用其前半阕或後半阕，用作引子；其二与词牌不同，用作过曲。宋丁持正词有「碧桃春昼长」句，名《碧桃春》。李萧远词名《醉桃源》。曹双溪词名《宴桃源》。韩涧泉词有「濯缨一曲可流行」句，名《濯缨曲》。
题注：傅注本、元延祐本无题，明吴讷钞本、《苏长公二妙集》本、毛本调名下有词题曰「初夏」。
高柳咽新蝉：傅子立注：「陆士衡诗：『寒蝉鸣高柳。』」刘尚荣按：「句出《文选·卷三十·陆士衡〈拟明月何皎皎〉诗》。」
「薰风初入弦」句：傅子立注：「舜帝作五弦之琴，以歌《南风》曰：『南风之薰兮，可以解吾民之愠兮。』」刘尚荣按：「详见《礼记·乐记》并孔仲远疏，又见《史记·卷一·〈五帝纪·帝舜纪〉》，又见《孔子家语·卷八·辨乐篇》。」
水沉：傅子立注：「香以沉水者为绝品。」刘尚荣按：「详见《梁书·卷五十四·〈诸夷列传·海南诸国·林邑国〉》：『林邑国者，本汉日南郡象林县，古越裳之界也。伏波将军马援开汉南境，置此县。……其南界，水步道二百馀里，有西国夷亦称王，马援植两铜柱表汉界处也。其国有金山，石皆赤色，其中生金。……又出玳瑁、贝齿、吉贝、沈木香。……沈木者，土人斫断之，积以岁年，朽烂而心节独在，置水中则沈，故名曰「沈香」。次不沈不浮者，曰「？香」也。』。」
「榴花开欲然」句：傅子立注：「梁孝元《榴花》诗：『然灯疑夜火。』杜子美：『山青花欲然。』李太白诗：『月色醉远客，山花开欲然。』」刘尚荣按：「梁孝元诗见《艺文类聚·卷八十六·〈果部·石榴〉》，又见《文苑英华·卷三百二十六》，『疑』作『宜』。杜句出《绝句二首（其二）》，《九家集注杜诗·卷二十五》。李句出《寄韦南陵冰，余江上乘兴访之，遇寻颜尚书笑，有此赠》，见《李太白诗集·卷十三》，『然』一作『燃』。」
「琼珠碎却圆」句：傅子立注：「杜子美：『棹拂荷珠碎却圆。』」刘尚荣按：「句出《宇文晁尚书之甥崔彧司业之孙中有脱字尚书之子重泛郑监审前湖》，《九家集注杜诗·卷三十三》。」却，茅维《苏集》本原校：「一作『又』。」毛本据之改「又」。
', '窗外绿槐阴阴，高高的柳树随风轻动，蝉鸣声戛然而止，和风将初夏的清凉吹入屋内。绿色的纱窗下，沉水香的淡淡芬芳随风飘散；惬意的昼眠，忽而被落棋之声惊醒。
雨後的小荷，随清风翻转。石榴花衬着湿润的绿葉，愈见得红丽如燃。美丽女子正在清池边用荷葉舀水嬉耍，清澈的泉水溅起就像晶莹的珍珠，一会儿破碎一会儿又圆。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b203048e64fbd89335", "shortContent": "这首词写的是初夏时节的闺阁生活，闲雅而有生气。上片写初夏已悄悄来到一个少女的身边。“绿槐高柳咽新蝉”，都是具有初夏特征的景物：枝叶繁茂的槐树，高大的柳树，还有浓绿深处的新蝉鸣声乍歇，一片阴凉幽静的庭园环境。“薰风初入弦”，又是初夏的气候特征。薰风，即暖和的南风。古人对这种助长万物的风曾写有《南风》歌大加赞颂：“南风之薰兮，可以解吾民之愠兮。南风之时兮，可以阜吾民之财兮。”据《礼记·乐记》载：“昔者...", "authors": ["谢楚发"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b97d0ac1145495e890", "shortContent": "这首词写的是初夏时节的闺阁生活，闲雅而有生气。上片写初夏已悄悄来到一个少女的身边。“绿槐高柳咽新蝉”，都是具有初夏特征的景物：枝叶繁茂的槐树，高大的柳树，还有浓绿深处的新蝉鸣声乍歇，一片阴凉幽静的庭园环境。“薰风初入弦”，又是初夏的气候特征。薰风，即暖和的南风。古人对这种助长万物的风曾写有《南风》歌大加赞颂：“南风之薰兮，可以解吾民之愠兮。南风之时兮，可以阜吾民之财兮。”据《礼记·乐记》载：“昔者...", "authors": ["谢楚发"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253f534825dee9fd6e7", "shortContent": "这首词写的是初夏时节的闺阁生活，闲雅而有生气。上片写初夏已悄悄来到一个少女的身边。“绿槐高柳咽新蝉”，都是具有初夏特征的景物：枝叶繁茂的槐树，高大的柳树，还有浓绿深处的新蝉鸣声乍歇，一片阴凉幽静的庭园环境。“薰风初入弦”，又是初夏的气候特征。薰风，即暖和的南风。古人对这种助长万物的风曾写有《南风》歌大加赞颂：“南风之薰兮，可以解吾民之愠兮。南风之时兮，可以阜吾民之财兮。”据《礼记·乐记》载：“昔者...", "authors": ["谢楚发"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7c7ccdb86c49f28f85", "shortContent": null, "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7c7ccdb86c49f28f86", "shortContent": "朱本、龙本、曹本未编年。王质《雪山集》卷七《东坡先生祠堂记》云：“先生以元丰七年别黄，杨元素起为富川（即兴国军永兴，今湖北阳新县，时杨知兴国军），闻先生自黄移汝，欲顺大江逆西江，适筠见子由，令富川弟子员李翔，要先生道富川，《满庭芳》序所谓会李仲览自江南来者是。先生自临皋渡武昌，至富川，见诗‘吾曹总为长江老’者是，今传富川。见词‘绿槐高柳咽新蝉’者是，今载集，且藏下雉李氏。先生自富川趣高安，与元素浓...", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646837a57f27182da3628f3d", "shortContent": "这首词写的是初夏时节的闺阁生活，闲雅而有生气。上片写初夏已悄悄来到一个少女的身边。“绿槐高柳咽新蝉”，都是具有初夏特征的景物：枝叶繁茂的槐树，高大的柳树，还有浓绿深处的新蝉鸣声乍歇，一片阴凉幽静的庭园环境。“薰风初入弦”，又是初夏的气候特征。薰风，即暖和的南风。古人对这种助长万物的风曾写有《南风》歌大加赞颂：“南风之薰兮，可以解吾民之愠兮。南风之时兮，可以阜吾民之财兮。”据《礼记·乐记》载：“昔者...", "authors": ["谢楚发"], "pressName": "上海辞书出版社"}]', '李沧溟《草堂诗馀隽·卷三》：景是写情，情在笔先，景描楮上，色色如画。
沈偶僧《古今词话》：观者叹服其八句状八景。音律一同，殊不散乱，入争宝之。刻之琬琰，挂于堂室间也。
俞乐静《唐五代两宋词选释》：写闺情而不着言辞，不作情语，自有一种闲雅之趣。', 'indent', 1423168835, '57b9016dc4c97100558f2932', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10147, '少年游 · 润州作，代人寄远', NULL, 224, 3406, 2, 1, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/864980.htm', '', '去年相送，余杭门外，飞雪似杨花。今年春尽，杨花似雪，犹不见还家。
对酒卷帘邀明月，风露透窗纱。恰似姮娥怜双燕，分明照、画梁斜。', '此词上阕写夫妻别离时间之久，诉说亲人不当别而别、当归而未归；下阕转写夜晚，着意刻画妻子对月思人的孤寂与惆怅。词用飞雪似杨花和杨花似雪这两个比喻贯穿上阕，结构精致，文思巧妙。全词情景交融，如一幅幽美的画卷，运用对比与类比手法，营造出一种幽深、缠绵的意境，新奇别致，感人肺腑。', '少年游：词牌名。六朝乐府「杂曲歌辞」有《少年行》，与此稍异。近人梁仲策《词学·调名》称：「调名源自鲍明远《行乐诗》：『春风太多情，村村花柳好。少年宜游春，莫使颜色槁。』」检今人逯钦立《先秦汉魏晋南北朝诗》所辑鲍明远诗，并无此几句。调见北宋晏同叔《珠玉集》。因词有「长似少年时」句，为创调之作，并取以为调名。调名本意即咏怀少年之恣意游乐。一说北宋柳屯田词为创调之作。因词中有「贪迷恋、少年游，似恁疏狂」句，取「少年游」三字为词调名。《乐章集》《张子野词》入「林钟商」，《清真集》分入「黄钟」、「商调」。此调最为参差，各家句读亦多出入，今分七体，其源俱出于晏词。或添一字摊破前后阕起句作四字两句者；或减一字摊破前后阕第三、四句作七字一句者；或于前后阕第二句添一字者；或于两结句添字、减字者。《词律》以柳词为定格，而《词谱》则以晏词为正体。韩涧泉词有「明窗玉蜡梅枝好」句，更名《玉蜡梅枝》。萨天锡词名《小阑干》。
「润州作，代人寄远」：吴讷钞本、《二妙集》本、毛本皆作「润州作」。
润州：龙榆生笺引《元和郡县志》：「润州东有润浦口，因以名。」又引《清一统志·镇江府》：「隋开皇十五年置润州，唐天宝元年改丹阳郡。宋仍曰润州丹阳郡，开宝八年改镇江军。」
余杭：龙榆生笺引《清一统志·杭州府》：「隋置杭州，大业三年改曰馀杭郡。宋仍曰杭州馀杭郡。」
邀明月：唐·李太白《月下独酌》诗：「举杯邀明月，对影成三人。」
姮娥：《淮南子·览冥训》：「羿请不死之药于西王母，姮娥窃以奔月。」东汉·高诱注：「姮娥，羿妻。羿请不死之药于西王母，未及服之；姮娥盗食之，得仙，奔入月中，为月精也。」汉避文帝讳改嫦娥。
照画梁：傅子立注引战国楚·宋玉《神女赋》：「月初出，照屋梁。」刘尚荣按：「《文选·卷十九·宋玉〈神女赋〉序》原句作『其始来也，耀乎若白日初出照屋梁。』傅《注》截取句中数字，又误『日』为『月』。」', '去年相送于馀杭门外，大雪纷飞如同杨花。如今春天已尽，杨花飘絮似飞雪，却不见离人归来，怎能不叫人牵肠挂肚呢？
卷起帘子举起杯，引明月作伴，可是风露又乘隙而入，透过窗纱，扑入襟怀。月光无限怜爱那双宿双栖的燕子，把它的光辉与柔情斜斜地洒向画梁上的燕巢。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b10ce818559d05079f", "shortContent": "宋神宗熙宁四年（1071）苏轼因与王安石议论不合，乞补外郡，被朝廷派往杭州作通判。这对被党争的政治漩涡搅得晕头转向的苏轼来说，无异于是一种精神上的解脱。杭州的湖光山色，市民与同僚对他的尊敬，僧人与歌妓对他的崇拜，都使他感到从未有过的愉快。续娶的年轻的妻子和牙牙学语的儿女也使他感到惬意和温暖。杭州真的成了他的人间天堂，每一次因公而暂时离开杭州都使他依依不舍。熙宁六年冬天，他又被两浙转运使派往常、润、...", "authors": ["谢楚发"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b8911759740c9bcb36", "shortContent": "宋神宗熙宁四年（1071）苏轼因与王安石议论不合，乞补外郡，被朝廷派往杭州作通判。这对被党争的政治漩涡搅得晕头转向的苏轼来说，无异于是一种精神上的解脱。杭州的湖光山色，市民与同僚对他的尊敬，僧人与歌妓对他的崇拜，都使他感到从未有过的愉快。续娶的年轻的妻子和牙牙学语的儿女也使他感到惬意和温暖。杭州真的成了他的人间天堂，每一次因公而暂时离开杭州都使他依依不舍。熙宁六年冬天，他又被两浙转运使派往常、润、...", "authors": ["谢楚发"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e78f2af4e09d55b64f8", "shortContent": "王文诰《苏诗总案》卷十一：“公以去年十一月发临平（今杭州东北），及是春尽，犹行役未归，故托为此词耳。”孔《谱》编熙宁七年（1074）四月。薛本认为与《蝶恋花》（雨后春容清更丽）作于同时。苏轼熙宁七年二月在京口，旋游宜兴，三月赴常州，故词作于二月底。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646830aeb6a81d0c5301cc8a", "shortContent": "宋神宗熙宁四年（1071）苏轼因与王安石议论不合，乞补外郡，被朝廷派往杭州作通判。这对被党争的政治漩涡搅得晕头转向的苏轼来说，无异于是一种精神上的解脱。杭州的湖光山色，市民与同僚对他的尊敬，僧人与歌妓对他的崇拜，都使他感到从未有过的愉快。续娶的年轻的妻子和牙牙学语的儿女也使他感到惬意和温暖。杭州真的成了他的人间天堂，每一次因公而暂时离开杭州都使他依依不舍。熙宁六年冬天，他又被两浙转运使派往常、润、...", "authors": ["谢楚发"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413206114, '57b8ee105bbb50005b77aff6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10148, '定风波 · 南海归，赠王定国侍人寓娘', NULL, 951, 3406, 3, 1, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/13361290.htm', '', '常羡人间琢玉郎，天应乞与点酥娘。尽道清歌传皓齿，风起，雪飞炎海变清凉。
万里归来年愈少，微笑，笑时犹带岭梅香。试问岭南应不好？却道：此心安处是吾乡。', '此词不仅刻画了歌女柔奴的姿容和才艺，而且着重歌颂了她的美好情操和高洁人品。柔中带刚，情理交融，空灵清旷，细腻柔婉，是这首词的独特风格。', '定风波：词牌名。原为唐教坊曲。《张子野词》入「双调」。李德润词名《定风流》，张子野词名《定风波令》。又名《捲春空》、《醉琼枝》。敦煌曲子词联章两首，其一：「攻书学剑能几何，争如沙塞骋偻侈。手执绿沉枪似铁，明月，龙泉三尺斩新磨。堪羡昔时军伍，谩夸儒士德能康。四塞忽闻狼烟起，问儒士，谁人敢去定风波。」其二：「征战偻罗未是功，儒士偻侈转更加。三策张良非恶弱，谋略，汉兴楚灭本由他。项羽翘据无路，酒后难消一曲歌。霸王虞姬皆自刎，当本，便知儒士定风波。」两词为武将与儒士回答，「定风波」以喻平定社会动乱，词风豪健，为此调之始词。另有敦煌曲子词三首为讲述伤寒病症口诀。此体始自五代欧阳炯，为通用之正体。双调六十二字，前阕五句三平韵叶二仄韵，后阕五句二平韵叶四仄韵。另有双调六十三字，前阕五句三平韵叶两仄韵，后阕六句四仄韵叶两平韵；双调六十字，前阕五句三平韵叶两仄韵，后阕五句两平韵叶两仄韵；双调六十字，前后阕各五句两平韵叶两仄韵诸变体。《乐章集》演为慢词，一入「双调」，一入「林钟商」，并全用仄韵。此调以七言句式为主，每句用韵，于平声韵中三叶仄韵，插入三个两字句，调势于流畅时忽然顿挫转折，因而韵律复杂，其中之两字句很难处理，用此调时应注意格律与词意之转折变化。此调适应之题材较广。从始词来看，此调宜于表现社会重大题材，亦宜言志与酬赠。欧阳炯、孙孟光、蔡申道、陈西麓等亦用以抒闺情。魏夫人用以写暮春感怀，词情极为婉约。欧阳文忠词六首，多写人生感慨。
「南海归，赠王定国侍人寓娘」：元延祐本作「海南归，赠王定国侍儿寓娘」。毛本有词叙曰：「王定国歌儿曰柔奴，姓宇文氏，眉目娟丽，善应对，家世住京师。定国南迁归，余问柔：『广南风土，应是不好？』柔对曰：『此心安处，便是吾乡。』因为缀词云。」刘尚荣按：「此节文字见于《苕溪渔隐丛话·后集卷四十》所引《东皋杂录》，应系毛本妄加词叙。」龙本词叙从毛本。
王定国：傅子立注：「王定国名巩，丞相旦之孙。」刘尚荣按：「见《宋史·卷三百二十·〈王素传·（子）王巩传〉》：『巩有隽才，长于诗，从苏轼游。轼守徐州，巩往访之，与客游泗水，登魋山，吹笛饮酒，乘月而归。轼待之于黄楼上，谓巩曰：「李太白死，世无此乐三百年矣。」轼得罪，巩亦窜宾州。数岁得还，豪气不少挫。后历宗正丞，以跌荡傲世，每除官，辄为言者所议，故终不显。』」
定国南迁：龙榆生笺引《东坡诗集》冯注：「《续通鉴长编》元祐六年六月注载刘挚云：『巩奇俊有文词，然不就规检，喜立事功，往往犯分，躁于进取。苏辙兄弟奖引之甚力。然好作议论誇诞，轻易臧否人物，其口可畏，以是颇不容于人。昔坐事窜南荒三年，安患难，一不戚于怀，归来颜色和豫，气益刚实。此其过人远甚，不得谓无入于道也。』」
柔奴：龙榆生笺：「《东皋杂录》：『王定国自岭表归，出歌奴柔奴，劝东坡饮。坡问：「广南风土应不好？」柔奴曰：「此心安处，便是吾乡。」坡喜其语，作《定风波》词以记之。』『应乞与』作『教分付』。」
琢玉郎、点酥娘：傅子立注：「『琢玉郎』，言其美姿如玉也；『点酥娘』，言其如凝酥之滑腻也。」刘尚荣按：「事详《苕溪渔隐丛话·后集卷四十》引《东皋杂录》。」
常羡：傅注本作「谁羡」，元延祐本作「长羡」，兹从明吴讷钞本、毛本、。
「天应乞与点酥娘」句：元延祐本作「天应乞与点苏娘」，句下原校：「一作『故教天与点苏娘』。」又毛本作「天教分付点酥娘」。
尽道：元延祐本、《苕溪渔隐丛话·后集卷四十》作「自作」。
皓齿：傅子立注：「杜子美：『佳人绝代歌，独立发皓齿。』」刘尚荣按：「句出《听杨氏歌》，见《九家集注杜诗·卷十三》。」
颜愈少：元延祐本、《苕溪渔隐丛话·后集卷四十》作「年愈少」。
笑时：毛本作「时时」。
岭梅：明吴讷钞本、《苏长公二妙集》本、毛本作「岭南」。龙榆生笺：「《六帖》：『庾（Yǔ）岭上梅花，南枝已落，北枝方开，寒暖之候异也。』杜少陵《秋日荆南述怀三十韵》诗：『秋水漫湘竹，阴风过岭梅。』」
「此心安处是吾乡」句：傅子立注：「白乐天：『安处即吾乡。』」刘尚荣按：「《白氏长庆集·卷十六·四十五诗》有此句，『吾』原作『为』。又《吾士》诗：『身心安处为吾土。』」', '常常羡慕这世间如玉雕琢般丰神俊朗的男子，就连上天也怜惜他，赠予他柔美聪慧的佳人与之相伴。人人称道那女子歌声轻妙，笑容柔美，风起时，那歌声如雪片飞过炎热的夏日使世界变得清凉。
你从遥远的地方归来却看起来更加年轻了，笑容依旧，笑颜里好像还带着岭南梅花的清香；我问你：「岭南的风土应该不是很好吧？」你却坦然答道：「心安定的地方，便是我的故乡。」
', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b1dbb8b379ee08de8a", "shortContent": "这首词的原序说：“王定国歌儿曰柔奴，姓宇文氏，眉目娟丽，善应对，家世住京师。定国南迁归，余问柔：‘广南风土，应是不好？’柔对曰：‘此心安处，便是吾乡。’因为缀词云。”宋神宗元丰二年（1079）六月，苏轼因“乌台诗案”被捕入狱，后贬为黄州团练副使。王巩字定国，从苏轼学为文，因收受苏诗而遭牵连，被贬宾州（治所在今广西宾阳县南）监盐酒税。宾州当时属广南西路，为岭南地区，僻远荒凉，生活艰苦。王巩赴岭南时，...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b82e6a6b501f9672b4", "shortContent": "这首词的原序说：“王定国歌儿曰柔奴，姓宇文氏，眉目娟丽，善应对，家世住京师。定国南迁归，余问柔：‘广南风土，应是不好？’柔对曰：‘此心安处，便是吾乡。’因为缀词云。”宋神宗元丰二年（1079）六月，苏轼因“乌台诗案”被捕入狱，后贬为黄州团练副使。王巩字定国，从苏轼学为文，因收受苏诗而遭牵连，被贬宾州（治所在今广西宾阳县南）监盐酒税。宾州当时属广南西路，为岭南地区，僻远荒凉，生活艰苦。王巩赴岭南时，...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7cc26cbf3417f0921b", "shortContent": "朱本编元丰六年癸亥（1083）：“案本集《王定国诗集序》云：‘定国以余故，贬海上三年。’又《次韵王鞏南迁初归》诗，施注编癸亥。词亦是年之作。”龙本、曹本从其说。薛本考证说，《次韵王鞏南迁初归》乃寄达而非面和，而此词显系作者与王定国晤面之后所作，故二作绝非作于同时，朱本编年有误。《重编东坡先生外集》此词原注云：“元祐元年王定国席上，赠侍儿寓娘。”《苕溪渔隐丛话》后集卷四十引《东皋杂录》云：“王定国岭...", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646831c0c0471b0062db7122", "shortContent": "这首词的原序说：“王定国歌儿曰柔奴，姓宇文氏，眉目娟丽，善应对，家世住京师。定国南迁归，余问柔：‘广南风土，应是不好？’柔对曰：‘此心安处，便是吾乡。’因为缀词云。”宋神宗元丰二年（1079）六月，苏轼因“乌台诗案”被捕入狱，后贬为黄州团练副使。王巩字定国，从苏轼学为文，因收受苏诗而遭牵连，被贬宾州（治所在今广西宾阳县南）监盐酒税。宾州当时属广南西路，为岭南地区，僻远荒凉，生活艰苦。王巩赴岭南时，...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}]', '南宋·杨湜《古今词话》：其句全引点酥之语，云云。点酥因是词誉藉甚。
清·沈雄《古今词话》：然最难凑泊者此调也，亦不过记事云尔。', 'indent', 1362519763, '57b168e65bbb500062dadef1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10149, '江神子 · 别徐州', NULL, 331, 3406, 2, 0, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/865837.htm', '', '天涯流落思无穷。既相逢，却匆匆。携手佳人，和泪折残红。为问东风余几许，春纵在，与谁同？
隋堤三月水溶溶，背归鸿，去吴中。回首彭城，清泗与淮通。欲寄相思千点泪，流不到，楚江东。', '此词作于元丰二年（西元一〇七九年）三月东坡由徐调知湖州途中。因弟子由通判南都（今河南商丘），便于赴任途中先去南都小住半月，随後再南下。此词系南下途中所作，叙写与徐州友人的别情。词中化用唐代李义山《无题》诗中「相见时难别亦难，东风无力百花残。春蚕到死丝方尽，蜡炬成灰泪始干」句意，将积郁的愁思注入即事即地的景物之中，抒发了作者对徐州风物人情无限留恋之情，并在离愁别绪中融入了深沉的身世之感。别恨是全词主旨，上阕写别时情景，下阕想象别后境况。
上阕以感慨起调，言天涯流落，愁思茫茫，无穷无尽。「天涯流落」，深寓词人的身世之感。东坡外任多年，类同飘萍，自视亦天涯流落之人。他在徐州仅两年，又调往湖州，南北辗转，这就更增加了他的天涯流落之感。这一句同时也饱含着词人对猝然调离徐州的感慨。「既相逢，却匆匆」两句，转写自己与徐州人士的交往，对邂逅相逢的喜悦，对骤然分别的痛惜，得而复失的哀怨，溢于言表。「携手」两句，写他永远不能忘记自己最後离开此地时依依惜别的动人一幕。「携手佳人」，借与佳人乍逢又别的感触言离愁。「和泪折残红」，写作者面对落花，睹物伤怀，情思绵绵，辗转不忍离去，同时也是写离徐的时间，启过拍「为问」三句。末三句由残红而想到残春，因问东风尚余几许，感叹纵使春光仍在，而身离徐州，与谁同春！此三句通过写离徐后的孤单，写对徐州的依恋，且笔触一波三折，婉转抑郁。
词的下阕即景抒情，继续抒发上阕未了之情。过阕「隋隄三月水溶溶」，是写词人离徐途中的真景，将浩荡的悲思注入东去的三月隋隄那溶溶春水中。
「背归鸿，去吴中」，亦写途中之景，而意极沉痛。春光明媚，鸿雁北归故居，而词人自己却与雁行相反，离开徐州热土，南去吴中湖州。东坡显然是把徐州当成了他的故乡，而自叹不如归鸿。「彭城」即徐州城。「清泗与淮通」暗寓作者不忍离徐，而现实偏偏无情，不得不背鸿而去，故于途中频频回顾，直至去程已远，回顾之中，唯见清澈的泗水由西北而东南，向着淮水脉脉流去。看到泗水，触景生情，自然会想到徐州（泗水流经徐州）。歇拍三句，即景抒情，于沉痛之中交织着怅惘的情绪。徐州既相逢难再，因而词人欲托清泗流水把千滴相思之泪寄往徐州，怎奈楚江（指泗水）东流，相思难寄，怎不令词人怅然若失！托淮泗以寄泪，情真意厚，且想象丰富，造语精警；而楚江东流，又大有「自是人生长恨水长东」之意，感情沉痛、怅惘，读之令人肠断。
此词写别恨，采用了化虚为实的艺术手法。作者由分别之地彭城，想到去途中沿泗入淮，向吴中新任所的曲折水路；又由别时之「和泪」，想到别後的「寄泪」。这样，离愁别绪更显深沉、哀婉。结句「流不到，楚江东」，别泪千点因春水溶溶而愈见浩荡，犹如一声绵长的浩叹，久远地回响在读者的心头。', '江神子：词牌名。据唐·崔令钦《教坊记》、敦煌曲子词与现存晚唐前文人词，均无载录《江城子》，故是调当兴于晚唐。王昆吾《唐代酒令艺术》谓是调源自唐著词曲调，即唐时酒令，知是调始流行于晚唐酒筵上，经文人加工，遂成小令词调。唐五代时为单调，始见《花间集》韦端己词，单调三十五字，七句五平韵，间有三十六字、三十七字诸格。可见唐五代《江城子》调兴之初，格式尚未定型。全唐五代以《江城子》词约十六首，由七位词人所作，以端己最长，当为最早依调填词者。五代时，欧阳炯单调词添一衬字变尾二句为七言句，开宋词「衬字法」。牛松卿单调词添二字于第二句，开宋词「添字法」。尹鹗单调词摊破首句为两三言句，开宋词「减字法」、「摊破法」。北宋初，是调作者甚少，晏同叔、柳耆卿、欧阳文忠诸大家均无《江城子》传世，唯张子野有两首《江城子》。至东坡始变双调，由是词格渐定。薛瑞生《东坡词编年笺证》中考东坡首用是调约于熙宁年间，《江神子·湖上与张先同赋，时闻弹筝》与《江神子·孤山竹阁送述古》卽东坡初创之作，仍承唐五代词柔婉细腻之风。元丰间，《江神子·乙卯正月二十日夜记梦》和《江神子·密州出猎》开一代词风，引时人乃至後代追和。是调衰于金元，近三分之一为道士所作，内容多涉道教。《钦定词谱》：「晁无咎改名《江神子》，韩涧泉词有『腊后春前邨意远』句，更名《邨意远》。」严建文《词牌释例》：「《江城子》，又名《江神子》、《邨意远》、《水晶帘》，……清李符曾《词家辨證》云：『南唐人张泌有《江城子》二阕，五代欧阳炯用此调填词有『如西子镜，照江城』句，含本意……」《唐圭璋推荐唐宋词》注：「《江城子》调应由咏江城事而得名。『子』为曲名后缀。本篇用原始题意咏扬子江畔古城金陵。」可知调因欧词「如西子镜，照江城」句得名。欧词虽非现存《江城子》首作，然咏江城金陵事而归本意。有单调四体，分三十五字、三十六字、三十七字三种；双调一体，七十字，上下阕各七句，五平韵。格律多为平韵格，双调体偶有填仄韵者。
「别徐州」：明吴讷钞本、《苏长公二妙集》本、茅维《苏集》本、毛本作「恨别」。傅注本存目阙文，今据元延祐本补足正文，仍以明吴讷钞本等加以校订。傅注文则无从辑补，暂付阙如。
隋堤：龙榆生笺：「《开河记》：『隋大业年，开汴河，筑堤，自大梁至灌口，龙舟所过，香闻百里。既过雍丘，渐达宁陵，水势紧急，龙舟阻碍。虞世基请为铁脚木鹅，验水深浅。自雍州至灌口，得一百二十九浅处。今亦名隋堤。』吴子华《彭门用兵后经汴路三首》诗：『隋堤风物已凄凉。』」
回首：《苏长公二妙集》本、茅维《苏集》本、毛本作「回望」。
欲寄：明吴讷钞本、《苏长公二妙集》本、毛本作「寄我」。', '流落在滚滚红尘中，人在天涯，思绪无穷！已经相逢了，可在一起时候的欢乐却是那么短暂。在我临行之时，握着佳人纤细的玉手，欲语还休，只得流泪对着漫天飘零的落花。想要问温暖的东风还留下多少？春天纵使还在，与谁共赏呢？
隋堤在阳春三月里的时候，水面上波光粼粼。我却要在此时和向北归家的鸿鹄背道而驰，远去南方的吴中，回头远望这第二故乡般的徐州，我心潮澎湃。清澈的泗水和徐州的淮河相通，我想要把相思离别的眼泪寄给徐州，却是流不到楚江的东面啊！', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b3911759740c9aa33c", "shortContent": "苏轼于熙宁十年（1077）四月调知徐州，五月到任，历时近两年，元丰二年（1079）三月由徐州调往湖州。这首词就是他在离徐后赴湖州途中写的，故曰“别徐州”，又题作“恨别”。\n况蕙风曾说：“‘真’字是词骨。情真，景真，所作必佳。”（《蕙风词话》卷一）苏轼这首词的突出特点便是“真”，情真，景真，语语真切，抒发了他对徐州风物人情无限留恋之情。\n词以感慨起调，言天涯流落，愁思茫茫，无穷无尽。“天涯流落”，深...", "authors": ["邱鸣皋"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ba2cee9a0c24ed9e50", "shortContent": "苏轼于熙宁十年（1077）四月调知徐州，五月到任，历时近两年，元丰二年（1079）三月由徐州调往湖州。这首词就是他在离徐后赴湖州途中写的，故曰“别徐州”，又题作“恨别”。\n况蕙风曾说：“‘真’字是词骨。情真，景真，所作必佳。”（《蕙风词话》卷一）苏轼这首词的突出特点便是“真”，情真，景真，语语真切，抒发了他对徐州风物人情无限留恋之情。\n词以感慨起调，言天涯流落，愁思茫茫，无穷无尽。“天涯流落”，深...", "authors": ["邱鸣皋"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7af2af4e09d55b653d", "shortContent": "王文诰《苏诗总案》卷一八：己未（元丰二年，1079）三月，“告下，以祠部员外郎直史馆知湖州军州事，留别田叔通、寇元弼、石坦夫，作《江神子》词”。薛本、邹王本从之。时苏轼自徐州移知湖州，为留别之作。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "6468393bb6a81d0c5302013c", "shortContent": "苏轼于熙宁十年（1077）四月调知徐州，五月到任，历时近两年，元丰二年（1079）三月由徐州调往湖州。这首词就是他在离徐后赴湖州途中写的，故曰“别徐州”，又题作“恨别”。\n\n况蕙风曾说：“‘真’字是词骨。情真，景真，所作必佳。”（《蕙风词话》卷一）苏轼这首词的突出特点便是“真”，情真，景真，语语真切，抒发了他对徐州风物人情无限留恋之情。\n\n词以感慨起调，言天涯流落，愁思茫茫，无穷无尽。“天涯流落”...", "authors": ["邱鸣皋"], "pressName": "上海辞书出版社"}]', '', 'indent', 1362519892, '57b476ad2e958a0056285fe6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (31461, '洞仙歌 · 中秋', NULL, 0, 891, 0, 1, '李俊民', NULL, 10838, '5858e5e38e450a006c7f7cd2', '元', 'ci', '词', NULL, NULL, '秋光海底，涌出银盘烂。只怕微云淡河汉。料姮娥应笑、醉舞仙人，今夜里，空恁樽前撩乱。
寻常三五夜，也有团圆，争柰人心未能满。记当初破镜、飞上天时，双照影、留得人闲一半。待仗他玉斧、再修成，问明月明年、共谁同看。', NULL, NULL, NULL, NULL, NULL, 'indent', 1512670231, '585cdaab570c3500692fd2b2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (76919, '左掖梨花', NULL, 90, 14, 0, 2, '丘为', NULL, 10120, '57b9a054a633bd005d2dca9b', '唐', 'shi', '诗', NULL, NULL, '冷艳全欺雪，馀香乍入衣。
春风且莫定，吹向玉阶飞。', NULL, NULL, NULL, NULL, NULL, 'center', 1512739238, '585d078e8d6d810065dc9ceb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10151, '题西林壁', NULL, 1079, 3406, 2, 11, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'shi', '诗', 'http://baike.baidu.com/view/273000.htm', '', '横看成岭侧成峰，远近高低各不同。
不识庐山真面目，只缘身在此山中。', '这是一首诗中有画的写景诗，又是一首哲理诗，哲理蕴含在对庐山景色的描绘之中。前两句描述了庐山不同的形态变化。庐山横看绵延逶迤，崇山峻岭郁郁葱葱连环不绝；侧看则峰峦起伏，奇峰突起，耸入云端。从远处和近处不同的方位看庐山，所看到的山色和气势又不相同。后两句写出了作者深思后的感悟：之所以从不同的方位看庐山，会有不同的印象，原来是因为「身在此山中」。也就是说，衹有远离庐山，跳出庐山的遮蔽，纔能全面把握庐山的真正仪态。全诗紧紧扣住游山谈出自己独特的感受，藉助庐山的形象，用通俗的语言深入浅出地表达哲理，故而亲切自然，耐人寻味。', '题西林壁：写在西林寺的墙壁上。西林寺在庐山西麓。题，书写，题写；西林，西林寺，在江西庐山。
横看：从正面看。庐山总是南北走向，横看就是从东面西面看。
侧：侧面。
各不同：各不相同。
不识：不能认识，辨别。
真面目：指庐山真实的景色、形状。
缘：因为；由于。
此山：这座山，指庐山。', '从正面、侧面看庐山山岭连绵起伏、山峰耸立，从远处、近处、高处、低处看庐山，庐山呈现各种不同的样子。我之所以认不清庐山真正的面目，是因为我自身处在庐山之中。', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea70a0ce818559d05e3fd", "shortContent": "苏轼于神宗元丰七年（1084）由黄州贬所改迁汝州（今属河南）团练副使。据南宋施宿《东坡先生年谱》：“四月发黄州，自九江抵兴国，取高安，访子由，因游庐山……”可知此诗约作于是年五月间。同时所作的游庐山诗，有《初入庐山五言绝句》（三首）、《瀑布亭》、《庐山二胜》（两首）、《赠总长老》等七首。《庐山二胜》前有短序云：“余游庐山，南北得十五六（意谓游程所至达全山十分之五六），奇胜殆不可胜纪，而懒不作诗，独...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646820075e6bb82b8cd2098e", "shortContent": "苏轼于神宗元丰七年（1084）由黄州贬所改迁汝州（治所在今河南临汝）团练副使。据南宋施宿《东坡先生年谱》:“四月发黄州，自九江抵兴国，取高安，访子由，因游庐山……”可知此诗约作于是年五月间。同时所作的游庐山诗，有《初入庐山五言绝句》（三首）、《瀑布亭》、《庐山二胜》（两首）、《赠总长老》等七首。《庐山二胜》前有短序云：“余游庐山，南北得十五六（意谓游程所至达全山十分之五六），奇胜殆不可胜纪，而懒不...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646b0cb07da2f75ac701fdea", "shortContent": "苏轼于神宗元丰七年（1084）由黄州贬所改迁汝州（治所在今河南临汝）团练副使。据南宋施宿《东坡先生年谱》:“四月发黄州，自九江抵兴国，取高安，访子由，因游庐山……”可知此诗约作于是年五月间。同时所作的游庐山诗，有《初入庐山五言绝句》（三首）、《瀑布亭》、《庐山二胜》（两首）、《赠总长老》等七首。《庐山二胜》前有短序云：“余游庐山，南北得十五六（意谓游程所至达全山十分之五六），奇胜殆不可胜纪，而懒不...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471a40b902ee364cc93993d", "shortContent": "西林寺又称乾明寺，位于庐山七岭之西。姚宽《西溪丛语》评此诗首句谓：“南山宣律师《感通录》云：‘庐山七岭，共会于东，合而成峰。’因知东坡‘横看成岭侧成峰’之句，有自来矣。”如果不是泛游了全山，收摄远近高低的全部峰岭在胸中构成整体的形象，就正如《初入庐山》第一首中所说：“青山若无素，偃蹇不相亲。要识庐山面，他年是故人”那样，只能看到峰峦坡陀的偃蹇（高耸貌）之状了。\n次句“远近高低各不同”，一本作“远近...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "6473425c7f27182da39104d8", "shortContent": "苏轼于神宗元丰七年（1084）由黄州贬所改迁汝州（治所在今河南临汝）团练副使。据南宋施宿《东坡先生年谱》：“四月发黄州，自九江抵兴国，取高安，访子由，因游庐山……”可知此诗约作于是年五月间。同时所作的游庐山诗，有《初入庐山五言绝句》（三首）、《瀑布亭》、《庐山二胜》（两首）、《赠总长老》等七首。《庐山二胜》前有短序云：“余游庐山，南北得十五六（意谓游程所至达全山十分之五六），奇胜殆不可胜纪，而懒不...", "authors": ["何满子"], "pressName": "上海辞书出版社"}]', '', 'center', 1415646500, '57b9553ca633bd00666036b1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10152, '和子由渑池怀旧', NULL, 511, 3406, 2, 1, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'shi', '诗', 'http://baike.baidu.com/view/822243.htm', '', '人生到处知何似，应似飞鸿踏雪泥。
泥上偶然留指爪，鸿飞那复计东西。
老僧已死成新塔，坏壁无由见旧题。
往日崎岖还记否，路长人困蹇驴嘶。', '北宋嘉祐六年，苏轼赴任陕西路过渑池（今属河南）。其弟苏辙难遣手足之情，写了首《怀渑池寄子瞻兄》寄赠。此诗为作者的和诗。
前四句一气贯串，自由舒卷，超逸绝伦，散中有整，行文自然。首联两句，以雪泥鸿爪比喻人生。一开始就发出感喟，有发人深思、引人入胜的作用，并挑起下联的议论。次联两句又以「泥」「鸿」领起，用顶针格就「飞鸿踏雪泥」发挥。鸿爪留印属偶然，鸿飞东西乃自然。偶然故无常，人生如此，世事亦如此。他用巧妙的比喻，把人生看作漫长的征途，所到之处，诸如曾在渑池住宿、题壁之类，就像万里飞鸿偶然在雪泥上留下爪痕，接着就又飞走了；前程远大，这里并非终点。人生的遭遇既为偶然，则当以顺适自然的态度去对待人生。果能如此，怀旧便可少些感伤，处世亦可少些烦恼。苏轼的人生观如此，其劝勉爱弟的深意亦如此。此种亦庄亦禅的人生哲学，符合古代士大夫的普遍命运，亦能宽解古代士大夫的共同烦恼，所以流布广泛而久远。
后四句照应「怀旧」诗题，以叙事之笔，深化雪泥鸿爪的感触。五、六句言僧死壁坏，故人不可见，旧题无处觅，见出人事无常，是「雪泥」、「指爪」感慨的具体化。尾联是针对苏辙原诗「遥想独游佳味少，无言骓马但鸣嘶」而引发的往事追溯。回忆当年旅途艰辛，有珍惜现在勉励未来之意，因为人生的无常，更显人生的可贵。艰难的往昔，化为温情的回忆，而如今兄弟俩都中了进士，前途光明，更要珍重如今的每一时每一事了。在这首早期作品中，诗人内心强大、达观的人生底蕴已经得到了展示。全诗悲凉中有达观，低沉中有昂扬，读完并不觉得人生空幻，反有一种眷恋之情荡漾心中，犹如冬夜微火。于「怀旧」中展望未来，意境阔远。诗中既有对人生来去无定的怅惘，又有对前尘往事的深情眷念。
此诗的重心在前四句，而前四句的感受则具体地表现在后四句之中，从中可以看出诗人先前的积极人生态度，以及后来处在颠沛之中的乐观精神的底蕴。全篇圆转流走，一气呵成，涌动着散文的气脉，是苏轼的名作之一。', '子由：苏轼弟苏辙字子由。
渑（miǎn）池：今河南渑池县。这首诗是和苏辙《怀渑池寄子瞻兄》而作。
「人生」句：此是和作，苏轼依苏辙原作中提到的雪泥引发出人生之感。查慎行、冯应榴以为用禅语，王文诰已驳其非，实为精警的譬喻，故钱鍾书《宋诗选注》指出：「雪泥鸿爪」，「后来变为成语」。
老僧：即指奉闲。苏辙原唱「旧宿僧房壁共题」自注：「昔与子瞻应举，过宿县中寺舍，题其老僧奉闲之壁。」古代僧人死后，以塔葬其骨灰。
坏壁：指奉闲僧舍。嘉祐三年（公元1056年），苏轼与苏辙赴京应举途中曾寄宿奉贤僧舍并题诗僧壁。
蹇（jiǎn）驴：腿脚不灵便的驴子。蹇，跛脚。苏轼自注：「往岁，马死于二陵（按即崤山，在渑池西），骑驴至渑池。」', '人生在世，到这里、又到那里，偶然留下一些痕迹，你觉得像是什么？我看真像随处乱飞的鸿鹄，偶然在某处的雪地上落一落脚一样。
它在这块雪地上留下一些爪印，正是偶然的事，因为鸿鹄的飞东飞西根本就没有一定。
老和尚奉闲已经去世，他留下的只有一座藏骨灰的新塔，我们也没有机会再到那儿去看看当年题过字的破壁了。
老和尚的骨灰塔和我们的题壁，是不是同飞鸿在雪地上偶然留下的爪印差不多呢！你还记得当时往渑池的崎岖旅程吗？——路又远，人又疲劳，驴子也累得直叫。', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea7052cee9a0c24ed4770", "shortContent": "仁宗嘉祐六年（1061），苏轼出任凤翔府（今属陕西）签判，其弟苏辙送他到郑州，然后返回京城开封，寄给他一首诗，题为《怀渑池寄子瞻兄》。苏轼和了这首诗，完全依照苏辙的原韵。\n苏辙十九岁时，曾被委为渑池县主簿，但未到任便中了进士[1]，因此他对渑池有一种特殊的感情。他寄给哥哥的诗里就说：“曾为县吏民知否？旧宿僧房壁共题。”很有怀旧之情。所以苏轼此诗开头四句就发表了一段议论。\n就一个人来说，或是为了谋生...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "6467784ae49f46528ab19872", "shortContent": "仁宗嘉祐六年（1061），苏轼出任凤翔府（今属陕西）签判，其弟苏辙送他到郑州，然后返回京城开封，寄给他一首诗，题为《怀渑池寄子瞻兄》。苏轼和了这首诗，完全依照苏辙的原韵。\n\n苏辙十九岁时，曾被委为渑池县主簿，但未到任便中了进士[1]，因此他对渑池有一种特殊的感情。他寄给哥哥的诗里就说：“曾为县吏民知否？旧宿僧房壁共题。”很有怀旧之情。所以苏轼此诗开头四句就发表了一段议论。\n\n就一个人来说，或是为了...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646b092045e4710056de5969", "shortContent": "仁宗嘉祐六年（1061），苏轼出任凤翔府（今属陕西）签判，其弟苏辙送他到郑州，然后返回京城开封，寄给他一首诗，题为《怀渑池寄子瞻兄》。苏轼和了这首诗，完全依照苏辙的原韵。\n\n苏辙十九岁时，曾被委为渑池县主簿，但未到任便中了进士  ，因此他对渑池有一种特殊的感情。他寄给哥哥的诗里就说：“曾为县吏民知否？旧宿僧房壁共题。”很有怀旧之情。所以苏轼此诗开头四句就发表了一段议论。\n\n就一个人来说，或是为了谋...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}]', '纪昀《始己评苏诗·卷三》：前四句单行入律，唐人旧格；而意境恣逸，则东坡本色。', 'center', 1423168968, '57b908c7128fe10054c9c901', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10153, '儋耳', NULL, 62, 3406, 1, 1, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'shi', '诗', 'http://baike.baidu.com/subview/683401/12092390.htm', '', '霹雳收威暮雨开，独凭栏槛倚崔嵬。
垂天雌霓云端下，快意雄风海上来。
野老已歌丰岁语，除书欲放逐臣回。
残年饱饭东坡老，一壑能专万事灰。', '儋耳即今海南儋县。元祐八年（公元1093年）宋哲宗亲政，重新起用新党。绍圣元年（公元1094年），苏轼以讥刺先朝的罪名贬官惠州（州治在今广东惠阳），绍圣四年（公元1097年）再贬儋耳。元符三年（公元1100年）正月宋哲宗去世，宋徽宗继位，政局在短时间内发生了有利于元祐党人的变化，已死的追复原官，未死的逐渐内迁。六十五岁高龄的苏轼于五月内迁廉州（州治在今广西合浦），《儋耳》诗即作于此时。这首诗表现了他初得诏书时的欣喜之情，抒发了风烛残年、万念俱冷的深沉感慨。', '儋（dān）耳：古代南方国名。又名离耳。西汉元鼎六年内属，称儋耳郡。在今海南岛。《说文·耳部》「聸，垂耳也。从耳詹声。南方有聸耳国。」清·段玉裁注：「古祇作『耽』，一变为聸耳，再变则为儋耳矣。」《史记·货殖列传》：「九疑苍梧以南至儋耳者，与江南大同俗，而杨越多焉。」《文选·左思〈吴都赋〉》：「儋耳黑齿之酋，金邻象郡之渠。」刘逵注：「儋耳人鏤其耳匡。」
「霹雳收威暮雨开」句：比喻朝政更新。霹雳，疾猛之雷；暮雨，傍晚的雨。
栏槛（jiàn）：栏杆。
倚崔嵬（wéi）：依傍嵯峨的高山。崔嵬，山高貌。
雌霓（ní）：霓即虹。《埤雅》：「虹常双见，鲜盛者雄，其暗者雌。」双虹并出，色彩浅淡者为雌霓。这里似暗喻小人。
雄风：凉爽的风。宋玉《风赋》：「此大王之雄风也。」此句隐以雄风喻王命。柳永《竹马子》词：「对雌霓挂雨，雄风拂槛，微收残暑。」为此联所化用。
野老：村野老人。
丰岁：丰收年。
除书：拜官之诏书。除去旧官，改授新官曰除。这里指令苏轼移廉州安置的诰命。
残年饱饭：化用杜甫《痛后过王倚饮赠歌》：「但得残年饱吃饭」句。残年，一生将尽的年月，指人的晚年。
一壑（hè）能专：占有一丘一壑。陆云《逸民赋序》：「古之选民，或轻天下，细万物，而欲专一丘之欢，擅一壑之美。」这里指有一块地能退居隐身即可。', '临近傍晚，云开雨散，雷电收起淫威，凭倚栏杆，我独自观赏大自然的瑰丽。
一双彩虹自云端垂天而下；雄风从海上吹来顿感快意。
田间的老人发出丰年的赞歌颂语，圣上的赦书将把流放的大臣放回。
苏东坡已经老去，只求馀生吃饱饭；只要一个山沟能安心养神，其他万事俱成灰。', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea70c2cee9a0c24ed4793", "shortContent": "儋耳今属海南省儋州市。元祐八年（1093）哲宗亲政，重新起用新党。绍圣元年（1094）苏轼以讥斥先朝的罪名贬官惠州（今属广东），绍圣四年再贬儋耳。元符三年（1100）正月哲宗去世，徽宗继位，政局在短时间内发生了有利于元祐党人的变化，已死的追复原官，未死的逐渐内迁。六十五岁高龄的苏轼于五月内迁廉州（州治在今广西合浦），《儋耳》诗即作于此时。这首诗表现了他初得诏书时的欣喜之情，抒发了风烛残年，万念俱冷...", "authors": ["曾枣庄"], "pressName": "上海辞书出版社"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646827ff7f27182da3623472", "shortContent": "儋耳即今广东海南岛儋县。元祐八年（1093）哲宗亲政，重新起用新党。绍圣元年（1094）苏轼以讥斥先朝的罪名贬官惠州（州治在今广东惠阳），绍圣四年再贬儋耳。元符三年（1100）正月哲宗去世，徽宗继位，政局在短时间内发生了有利于元祐党人的变化，已死的追复原官，未死的逐渐内迁。六十五岁高龄的苏轼于五月内迁廉州（州治在今广西合浦）,《儋耳》诗即作于此时。这首诗表现了他初得诏书时的欣喜之情，抒发了风烛残年...", "authors": ["曾枣庄"], "pressName": "上海辞书出版社"}]', '方东树《昭昧詹言·卷二十》：奇警（第二联）。
汪师韩《苏诗选评》：崷崪雄姿，经挫折而不稍损抑。浩然之气，于此见其心声。', 'center', 1362520551, '57b941ae7db2a2005428d135', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10154, '定风波', NULL, 3164, 3406, 2, 10, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/864969.htm', '三月七日，沙湖道中遇雨。雨具先去，同行皆狼狈，余独不觉。已而遂晴，故作此词。', '莫听穿林打叶声，何妨吟啸且徐行。竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。
料峭春风吹酒醒，微冷，山头斜照却相迎。回首向来萧瑟处，归去，也无风雨也无晴。', '此词通过野外途中偶遇风雨这一生活中的小事，於简朴中见深意，於寻常处生奇景，表现出旷达超脱的胸襟，寄寓着超凡脱俗的人生理想。上阕着眼於雨中，下阕着眼於雨後，全词体现出一个正直文人在坎坷人生中力求解脱之道，篇幅虽短，但意境深邃，内蕴丰富，诠释着作者的人生信念，展现着作者的精神追求。', '定风波：词牌名。原为唐教坊曲。《张子野词》入「双调」。李德润词名《定风流》，张子野词名《定风波令》。又名《捲春空》、《醉琼枝》。敦煌曲子词联章两首，其一：「攻书学剑能几何，争如沙塞骋偻侈。手执绿沉枪似铁，明月，龙泉三尺斩新磨。堪羡昔时军伍，谩夸儒士德能康。四塞忽闻狼烟起，问儒士，谁人敢去定风波。」其二：「征战偻罗干练，伶俐，机灵未是功，儒士偻侈转更加。三策张良非恶弱，谋略，汉兴楚灭本由他。项羽翘据无路，酒後难消一曲歌。霸王虞姬皆自刎，当本，便知儒士定风波。」两词为武将与儒士回答，「定风波」以喻平定社会动乱，词风豪健，为此调之始词。另有敦煌曲子词三首为讲述伤寒病症口诀。此体始自五代欧阳炯，为通用之正体。双调六十二字，前阕五句三平韵叶二仄韵，後阕五句二平韵叶四仄韵。另有双调六十三字，前阕五句三平韵叶两仄韵，後阕六句四仄韵叶两平韵；双调六十字，前阕五句三平韵叶两仄韵，後阕五句两平韵叶两仄韵；双调六十字，前後阕各五句两平韵叶两仄韵诸变体。《乐章集》演为慢词，一入「双调」，一入「林钟商」，并全用仄韵。此调以七言句式为主，每句用韵，于平声韵中三叶仄韵，插入三个两字句，调势于流畅时忽然顿挫转折，因而韵律复杂，其中之两字句很难处理，用此调时应注意格律与词意之转折变化。此调适应之题材较广。从始词来看，此调宜于表现社会重大题材，亦宜言志与酬赠。欧阳炯、孙孟光、蔡申道、陈西麓等亦用以抒闺情。魏夫人用以写暮春感怀，词情极为婉约。欧阳文忠词六首，多写人生感慨。这首词于元丰五年（1082）三月七日作于黄州。
题注：沙湖，地名，在黄州城东南30里，苏轼被贬黄州后，准备在沙湖买田终老，这首词是去看田归途遇雨后所作。已而，不久，过一会。傅子立注：「公旧序云：『三月七日，沙湖道中遇雨。雨具先去，同行皆狼狈，余独不觉。已乃遂晴，故作此词。』」刘尚荣按：「此条题注原钞于调名下，今移词後。元延祐本删『公旧序云』四字，径以此注为词题。又脱『独』、『词』等字，『已乃』作『已而』。《苏长公二妙集》本无『雨具先去』四字，无『故』字。明吴讷钞本『同行』作『同去』。龙本『故作此词』作『故作此』。」
吟啸：吟咏长啸。傅子立注：「《晋书·阮籍传》：『阮籍登山临水，啸咏自若。』」刘尚荣按：「事详《晋书·卷四十九·阮籍传》。」
竹杖芒鞋：竹杖和草鞋。傅子立注：「无则诗：『腾腾兀兀恣闲行，竹杖芒鞋称野情。』」刘尚荣按：「《全唐诗·卷八百二十五》收无则诗三首，无此句，则为其佚诗也。宋·陈芸居编《江湖小集·卷二十二·李雪林〈剪绡集〉》有《重寄》集句诗，首句云『竹杖芒鞋称野情』，署无则句。又『腾腾兀兀恣闲行』二句诗别见于宋刊施顾《注苏诗·卷十二·答任师中、家汉公》『芒鞋老菑畬』句下小字夹注，署名元微之名。然《元氏长庆集》中无此二句。待考。」芒，傅注诸本皆误作「芸」，据元延祐本改；鞋，龙本作「芒鞵」。
一蓑烟雨：傅子立注：「郑都官诗：『往来烟波非定居，生涯蓑笠外无馀。』魏草堂诗：『何日扁舟去，江上负烟蓑。』」刘尚荣按：「郑诗乃罗邺《钓翁》诗句，见《全唐诗·卷六百五十四》，『往来』原作『来往』，题下原注云：『一作郑谷诗。』然而《全唐诗》卷内郑都官未收此诗。又，《古今事文类聚·前集卷三十七》收此诗，署名郑都官作。魏句见魏草堂《东观集·卷七·暮春闲望》，上句原作『扁舟何日去』。」蓑，元延祐本、《东坡外集》作「莎」。
料峭：傅子立注：「公有诗云：『渐觉春风料峭寒。』」刘尚荣按：「句出《送范德孺》，见《东坡续集·卷三》，『春风』原作『东风』。」
萧瑟：风吹雨落的声音。傅注本、毛本作「潇洒」。按，东坡又有《独觉》诗曰：「回首向来萧瑟处，也无风雨也无晴。」于此词句同，因疑「萧瑟」更近苏词原貌。兹从元延祐本。
也无风雨也无晴：意思是风雨天气和晴朗的天气是一样的，没有差别。', '三月七日，在沙湖道上赶上了下雨，拿着雨具的仆人先前离开了，同行的人都觉得很狼狈，只有我不这么觉得。过了一会儿天晴了，就做了这首词。
不要害怕树林中风雨的声音，何妨放开喉咙吟唱从容而行。拄竹杖曳草鞋轻便胜过骑马，这都是小事情又有什么可怕？披一蓑衣任凭湖海中度平生。
料峭的春风把我的酒意吹醒，身上略略微微感到一些寒冷，看山头上斜阳已露出了笑脸，回首来程风雨潇潇的情景，归去不管它是风雨还是放晴。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b1911759740c9aa329", "shortContent": "此词作于宋神宗元丰五年（1082），贬谪黄州后的第三年。写眼前景，寓心中事；因自然现象，谈人生哲理。属于即景生情，而非因情造景。作者自有这种情怀，遇事便触发了。《东坡志林》说：“黄州东南三十里为沙湖，亦曰螺师店，予买田其间，因往相田。”途中遇雨，便写出这样一首于简朴中见深意、寻常处生波澜的词来。\n首句“莫听穿林打叶声”，只“莫听”二字便见性情。雨点穿林打叶，发出声响，是客观存在，说“莫听”，就有外...", "authors": ["陈长明"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b82cee9a0c24ed9e4c", "shortContent": "此词作于宋神宗元丰五年（1082），贬谪黄州后的第三年。写眼前景，寓心中事；因自然现象，谈人生哲理。属于即景生情，而非因情造景。作者自有这种情怀，遇事便触发了。《东坡志林》说：“黄州东南三十里为沙湖，亦曰螺师店，予买田其间，因往相田。”途中遇雨，便写出这样一首于简朴中见深意、寻常处生波澜的词来。\n首句“莫听穿林打叶声”，只“莫听”二字便见性情。雨点穿林打叶，发出声响，是客观存在，说“莫听”，就有外...", "authors": ["陈长明"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253f534825dee9fd6e2", "shortContent": "此词作于宋神宗元丰五年（1082），贬谪黄州后的第三年。写眼前景，寓心中事；因自然现象，谈人生哲理。属于即景生情，而非因情造景。作者自有这种情怀，遇事便触发了。《东坡志林》说：“黄州东南三十里为沙湖，亦曰螺师店，予买田其间，因往相田。”途中遇雨，便写出这样一首于简朴中见深意、寻常处生波澜的词来。\n\n首句“莫听穿林打叶声”，只“莫听”二字便见性情。雨点穿林打叶，发出声响，是客观存在，说“莫听”，就有...", "authors": ["陈长明"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e79f2af4e09d55b6503", "shortContent": "傅藻《东坡纪年录》：“熙宁七年甲寅（1074），送述古赴南都作《菩萨蛮》。”王文诰《苏诗总案》卷十二：“甲寅七月，与陈襄放舟湖上燕于孤山竹阁作《江神子》词，再作《菩萨蛮》词。”孔《谱》、薛本、邹王本从之。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7bf2af4e09d55b6554", "shortContent": "《苏轼文集》卷六十八《书清泉寺词》：“黄州东南三十里，为沙湖，亦曰螺师店。将买田其间，因往相田。”王文诰《苏诗总案》卷二一：“元丰五年壬戌（l082），三月七日，公以相田至沙湖，道中遇雨作。”孔《谱》、薛本、邹王本从之。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7ef2af4e09d55b655f", "shortContent": "此词诸本均未编年。曹本云：“按此词系女流口吻，意境与东坡词不类，断非东坡作。今移列误入词。”此词诸本均收，仅以意境不类即断为伪作，证据不足。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3d73206168b2e020ca", "shortContent": "据《东坡志林》记载，东坡尝往沙湖相田，此词盖作于是时，为贬谪黄州的第三个年头。途中偶然遇雨，便写出这首富有人生哲理的词来。\n雨点穿林打叶，又词序云“同行皆狼狈”，想来雨下得不小，东坡却只道“莫听”，即外物不足动我心之意。常人遇雨，躲之唯恐不及，东坡则非但徐行还要放声高歌，从容中多少带点倔强。竹杖芒鞋多为村野之人或山林隐者的装束，“马”则是官家象征。谪居黄州期间，词人自辟东坡而耕，自筑雪堂而居，已近...", "authors": ["江宏泽"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702f7ccdb86c49f291fa", "shortContent": "据《东坡志林》记载，东坡尝往沙湖相田，此词盖作于是时，为贬谪黄州的第三个年头。途中偶然遇雨，便写出这首富有人生哲理的词来。\n\n雨点穿林打叶，又词序云“同行皆狼狈”，想来雨下得不小，东坡却只道“莫听”，即外物不足动我心之意。常人遇雨，躲之唯恐不及，东坡则非但徐行还要放声高歌，从容中多少带点倔强。竹杖芒鞋多为村野之人或山林隐者的装束，“马”则是官家象征。谪居黄州期间，词人自辟东坡而耕，自筑雪堂而居，已...", "authors": ["江宏泽"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271abc9ebcc6fbea1a4ee", "shortContent": "据《东坡志林》记载，东坡尝往沙湖相田，此词盖作于是时，为贬谪黄州的第三个年头。途中偶然遇雨，便写出这首富有人生哲理的词来。\n雨点穿林打叶，又词序云“同行皆狼狈”，想来雨下得不小，东坡却只道“莫听”，即外物不足动我心之意。常人遇雨，躲之唯恐不及，东坡则非但徐行还要放声高歌，从容中多少带点倔强。竹杖芒鞋多为村野之人或山林隐者的装束，“马”则是官家象征。谪居黄州期间，词人自辟东坡而耕，自筑雪堂而居，已近...", "authors": ["江宏泽"], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646830f77f27182da3626c36", "shortContent": "此词作于宋神宗元丰五年（1082），贬谪黄州后的第三年。写眼前景，寓心中事；因自然现象，谈人生哲理。属于即景生情，而非因情造景。作者自有这种情怀，遇事便触发了。《东坡志林》说：“黄州东南三十里为沙湖，亦曰螺师店，予买田其间，因往相田。”途中遇雨，便写出这样一首于简朴中见深意、寻常处生波澜的词来。\n\n首句“莫听穿林打叶声”，只“莫听”二字便见性情。雨点穿林打叶，发出声响，是客观存在，说“莫听”，就有...", "authors": ["陈长明"], "pressName": "上海辞书出版社"}]', '晩淸·郑瘦碧《手批〈东坡乐府〉》：此足徵是翁坦荡之怀，任天而动。琢句亦瘦逸，能道眼前景，以曲笔写胸臆，倚声能事尽之矣。', 'indent', 1415646931, '57b908b02e958a005fa5891a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10155, '侠客行', NULL, 909, 1052, 3, 1, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/4383/6037291.htm', '', '赵客缦胡缨，吴钩霜雪明。
银鞍照白马，飒沓如流星。
十步杀一人，千里不留行。
事了拂衣去，深藏身与名。
闲过信陵饮，脱剑膝前横。
将炙啖朱亥，持觞劝侯嬴。
三杯吐然诺，五岳倒为轻。
眼花耳热后，意气素霓生。
救赵挥金槌，邯郸先震惊。
千秋二壮士，烜赫大梁城。
纵死侠骨香，不惭世上英。
谁能书阁下，白首太玄经。', '《侠客行》是唐代伟大诗人李白创作的一首描写和歌颂侠客的古体五言诗。此诗前四句从侠客的装束、兵刃、坐骑描写侠客的外貌；第二个四句写侠客高超的武术和淡泊名利的行藏；第三个四句引入信陵君和侯嬴、朱亥的故事来进一步歌颂侠客，同时也委婉地表达了自己的抱负，侠客得以结识明主，明主借助侠客的勇武谋略去成就一番事业，侠客也就功成名就了；最后四句表示，即使侠客的行动没有达到目的，但侠客的骨气依然流芳后世，并不逊色于那些功成名就的英雄。全诗抒发了他对侠客的倾慕，对拯危济难、用世立功生活的向往。', '侠客行：侠客之歌。行，歌行体。
赵客：燕赵之地的侠客。自古燕赵多慷慨悲歌之士。《庄子·说剑》：「昔赵文王好剑，剑士夹门而客三千馀人。」
缦胡缨：少数民族做工粗糙的没有花纹的带子。这句写侠客的冠带。缦，没有花纹；胡，古时对北方少数民族通称；缨，繫冠帽的带子。
吴钩：宝刀名。
霜雪明：谓宝刀的锋刃像霜雪一样明亮。
飒沓：群飞的样子，形容马跑得快。
「十步杀一人，千里不留行」句：原自《庄子·说剑》：「臣之剑十步一人，千里不留行。」这里是说侠客剑术高强，而且勇敢。
信陵：信陵君，战国四公子之一，为人礼贤下士，门下食客三千餘人。
朱亥、侯嬴：都是信陵君的门客。朱亥本是一屠夫，侯嬴原是魏国都城大梁东门的门官，两人都受到信陵君的礼遇，都为信陵君所用。
炙：烤肉。
啖朱亥，让朱亥来喫。啖，喫。
「三杯吐然诺，五岳倒为轻」句：说几杯酒下肚（古诗文中，三、九常是虚指）就作出了承诺，并且把承诺看得比五岳还重。
素霓：白虹，古人认为，凡要出现不寻常的大事，就会有不寻常的天象出现，如「白虹贯日」。
「意气素霓生」句：侠客重然诺、轻死生的精神感动了上天。也可以理解为，侠客这一承诺，天下就要發生大事了。这样与下文扣得更紧。
「救赵挥金槌，邯郸先震惊」句：朱亥锤击晋鄙的故事。信陵君是魏国大臣，魏、赵结成联盟共同对付秦国，这就是合纵以抗秦。信陵君是积极主张合纵的。邯郸，赵国国都。秦军围邯郸，赵向魏求救。魏王派晋鄙率军救赵，后因秦王恐吓，又令晋鄙按兵不动。这样，魏赵联盟势必瓦解。信陵君准备亲率家丁与秦军一拚，去向侯嬴辞行（实际是试探侯嬴），侯不语。信陵君行至半路又回来见侯嬴。侯笑着说：「我知道你会回来的。」于是为信陵君设计，串通魏王宠姬，盗击秦军，解了邯郸的围。
太玄经：扬雄曾在皇帝藏书的天禄阁任校刊工作。《太玄经》是扬雄写的一部哲学著作。', '燕赵的侠士，头上繫着侠士的武缨，腰佩吴越闪亮的弯刀，骑着银玻白马，像流星一样在大街上弛骋。他们的武艺盖世，十步可斩杀一人，千里之行，无人可挡。他们为人仗义行侠，事成之后，连个姓名也不肯留下。想当年，侯嬴、朱亥与信陵君结交，与之脱剑横膝，交相欢饮。三杯热酒下肚，便慷慨许诺，愿为知己两肋插刀。一诺重于泰山；眼花耳热之后，胸中之意气，可贯长虹。朱亥为信陵君救赵，挥起了金椎。此一壮举，使赵都邯郸上下，都先为之震惊。二壮士的豪举，千秋之后仍然在大梁城传为美谈。他们纵死而侠骨犹香，不愧是盖世之英豪。要做人就要像他们这样的侠士一样，传名百代，为人称颂。谁能学扬雄那个儒生，终身在书阁上，头发白了，还在书写《太玄经》。', NULL, '', 'center', 1362521259, '57ae01fc0a2b580063134970', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (406457, '开元乐', NULL, 0, 32, 0, 1, '杨继端', NULL, 24893, '5858f2c0570c3500691805c6', '清', 'ci', '词', NULL, NULL, '惆怅阶前梅树，今年几度春花。犹带别时泪影，郎行何日还家。', NULL, NULL, NULL, NULL, NULL, 'indent', 1542798077, '585ee28bda2f6000658edd02', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10156, '静夜思', NULL, 4324, 1052, 2, 13, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/47169/4947494.htm', '', '床前明月光，疑是地上霜。
举头望明月，低头思故乡。', '《静夜思》是唐代诗人李白所作的一首五绝小诗。此诗描写了秋日夜晚，诗人于屋内抬头望月的所感，表达客居思乡之情，语言清新朴素而韵味含蓄无穷，历来广为传诵。
明代版本是目前流传比较广泛的版本。该版本虽然可能不完全是李白的原作，有个别字词后世或有所修改，但是流传度很高，并被收录于各版本的语文教科书中。
宋代版本与人们常说的“床前明月光”明显不一致，其实并非是错误，而是流传版本不同。一般认为，这一版本比明版本更接近李白的原作，但仍有学者认为可能存在更早的版本。宋刊本的《李太白文集》、宋人郭茂倩所编的《乐府诗集》、洪迈所编《万首唐人绝句》中，《静夜思》的第一句均为“床前看月光”，第三句也均作“举头望山月”。元萧士赟《分类补注李太白集》、明高棅《唐诗品汇》，也是如此。宋人一直推崇唐诗，其收录编辑甚有规模，加之距唐年代相近，误传差错相对较少，故宋代乃至元代所搜集的《静夜思》应该是可靠准确的；在清朝玄烨皇帝亲自钦定的权威刊本《全唐诗》中，也并没有受到前面同时代不同刊本的影响而对此诗作任何修改。　　在此之前《静夜思》已传入日本（日本静嘉堂文库藏有宋刊本《李太白文集》12册），因日本人对唐诗崇尚，在后世流传过程中并未对其作出任何修改。但在中国情况就不一样了，到了明代赵宦光、黄习远对宋人洪迈的《唐人万首绝句》进行了整理与删补，《静夜思》的第三句被改成“举头望明月”，但是第一句“床前看月光”没有变化。清朝康熙年间沈德潜编选的《唐诗别裁》，《静夜思》诗的第一句是“床前明月光”，但第三句却是“举头望山月”。直到1763年（清乾隆二十八年）蘅塘退士所编的《唐诗三百首》里，吸纳了明刊《唐人万首绝句》与清康熙年《唐诗别裁》对《静夜思》的两处改动，从此《静夜思》才成为在中国通行至今的版本：“床前明月光，疑是地上霜；举头望明月，低头思故乡”。但是这也不是清朝流行的唯一版本，就在《唐诗三百首》问世前58年的1705年（康熙四十四年），康熙钦定的《全唐诗》中的《静夜思》就是与宋刊本《李太白文集》完全相同的“床前看月光，疑是地上霜。举头望山月，低头思故乡”，后来中华书局出版的《全唐诗》也沿用着这一表述。　　这一表述是明朝以后为普及诗词而改写的。经过“改动”了的《静夜思》比“原版”要更加朗朗上口却是不争的事实，这也解释了为什么“床前明月光”版比“床前看月光”版在中国民间更受欢迎的原因。中国李白研究会会长、新疆师范大学教授薛天纬先生在《漫说》（《文史知识》1984年第4期）一文中专门对两个版本的差异发表了如下看法：仔细体味，第一句如作“床前看月光”，中间嵌进一个动词，语气稍显滞重；再说，“月光”是无形的东西，不好特意去“看”，如果特意“看”，也就不会错当成“霜”了。而说“明月光”，则似不经意间月光映入眼帘，下句逗出“疑”字，便觉得很自然；何况，“明”字还增加了月夜的亮色。第三句，“望明月”较之“望山月”不但摆脱了地理环境的限制，而且，“山月”的说法不免带点文人气——文人诗中，往往将月亮区分为“山月”“海月”等，“明月”则全然是老百姓眼中的月亮了。所谓“篡改说”、“山寨说”实在是言过其实。有学者认为，“《静夜思》四句诗，至少有50种不同版本，并且你很难知道哪一种抄本更接近‘原本’。我们现在熟知的‘举头望明月’版本是在明代确定下来的”。莫砺锋在《百家讲坛》进行唐诗普及时，选取的也是大家熟知的版本，“所谓的‘篡改’不是一个人任意妄为的，而是长久以来的集体选择。古诗流传的历史，也是读者参与创造的过程，大家觉得这样更美，更朗朗上口，是千万百读者共同选择了这个版本。”今人读到的《静夜思》已经不仅仅是一首“唐”诗，它其实凝结了1300多年来一代又一代人的审美创造，后人应该抱以尊重的态度。近年来有关版本争议源于对李白诗歌版本众多这一常识普及不够。因此，有学者表示，国人对文史知识的缺失应引起深思，要意识到普及文史知识的必要，对博大精深的五千年中华文明存有敬畏之心。', '静夜思：安静的夜晚产生的思绪。
床：此诗中的“床”字，是争论和异议的焦点。今传五种说法。指井台。指井栏。从考古发现来看，中国最早的水井是木结构水井。古代井栏有数米高，成方框形围住井口，防止人跌入井内，这方框形既像四堵墙，又像古代的床。因此古代井栏又叫银床，说明井和床有关系，其关系的发生则是由于两者在形状上的相似和功能上的类同。“窗”的通假字。从意义上讲，“床”可能与‘窗’通假，而且在窗户前面是可能看到月亮的。但是，参照宋代版本，‘举头望山月’，便可证实作者所言乃是室外的月亮。从时间上讲，宋代版本比明代版本在对作者原意的忠诚度上，更加可靠。取本义，即坐卧的器具，《诗经·小雅·斯干》有“载寐之牀”，《易·剥牀·王犊注》亦有“在下而安者也”之说，讲得即是卧具。马未都等认为，床应解释为胡床。胡床，亦称“交床”、“交椅”、“绳床”。古时一种可以折叠的轻便坐具，马扎功能类似小板凳，但人所坐的面非木板，而是可卷折的布或类似物，两边腿可合起来。现代人常为古代文献中或诗词中的“胡床”或“床”所误。至迟在唐时，“床”仍然是“胡床”（即马扎，一种坐具）。
疑：好像。
举头：抬头。', '明亮的月光洒在窗户纸上，好像地上泛起了一层霜。我禁不住抬起头来，看那天窗外空中的一轮明月，不由得低头沉思，想起远方的家乡。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929bd635634aee3deb48", "shortContent": "明胡应麟说：“太白诸绝句，信口而成，所谓无意于工而无不工者。”（《诗薮·内编》卷六）明王世懋认为：“（绝句）盛唐惟青莲（李白）、龙标（王昌龄）二家诣极。李更自然，故居王上。”（《艺圃撷馀》）怎样才算“自然”，才是“无意于工而无不工”呢？这首《静夜思》就是个样榜。所以胡氏特地把它提出来，说是“妙绝古今”。\n这首小诗，既没有奇特新颖的想象，更没有精工华美的辞藻；它只是用叙述的语气，写远客思乡之情，然而...", "authors": ["马茂元"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac821a74606fc4093a", "shortContent": "明胡应麟说：“太白诸绝句，信口而成，所谓无意于工而无不工者。”（《诗薮·内编》卷六）明王世懋认为：“（绝句）盛唐惟青莲（李白）、龙标（王昌龄）二家诣极。李更自然，故居王上。”（《艺圃撷余》）怎样才算“自然”，才是“无意于工而无不工”呢？这首《静夜思》就是个样榜。所以胡氏特地把它提出来，说是“妙绝古今”。\n\n这首小诗，既没有奇特新颖的想象，更没有精工华美的辞藻；它只是用叙述的语气，写远客思乡之情，然...", "authors": ["马茂元"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e90391", "shortContent": "潇洒的诗人也有落寞的时候。他年纪轻轻就仗剑去国，辞亲远游，到过通衢大都，到过名山大川，也到过一些幽僻荒凉的村庄。走的地方多了，家乡的影子越来越淡，渐渐竟模糊不清。人生如旅途。行走在旅途中，劳累了，自然就会记起家中的千般好处、万种温馨。心灵惫顿了，茫然了，就会寻找慰藉。再长久的漂泊，也许都不会让飘逸的诗人沉寂下来；再辛苦的寻觅，也许都不会让执著热情的诗人感到厌倦。但他总有小憩的时候，正如喧闹过后会倍...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312704d73206168b2e021e0", "shortContent": "潇洒的诗人也有落寞的时候。他年纪轻轻就仗剑去国，辞亲远游，到过通衢大都，到过名山大川，也到过一些幽僻荒凉的村庄。走的地方多了，家乡的影子越来越淡，渐渐竟模糊不清。人生如旅途。行走在旅途中，劳累了，自然就会记起家中的千般好处、万种温馨。心灵惫顿了，茫然了，就会寻找慰藉。再长久的漂泊，也许都不会让飘逸的诗人沉寂下来；辛苦的寻觅，也许都不会让执着热情的诗人感到厌倦。但他总有小憩的时候，正如喧闹过后会倍感...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127078f2af4e09d55b67a2", "shortContent": "潇洒的诗人也有落寞的时候。他年纪轻轻就仗剑去国，辞亲远游，到过通衢大都，到过名山大川，也到过一些幽僻荒凉的村庄。走的地方多了，家乡的影子越来越淡，渐渐竟模糊不清。人生如旅途。行走在旅途中，劳累了，自然就会记起家中的千般好处、万种温馨。心灵惫顿了，茫然了，就会寻找慰藉。再长久的漂泊，也许都不否会让飘逸的诗人沉寂下来；辛苦的寻觅，也许都不会让执着热情的诗人感到厌倦。但他总有小憩的时候，正如喧闹过后会倍...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6466e61ce49f46528aae8761", "shortContent": "明胡应麟说：“太白诸绝句，信口而成，所谓无意于工而无不工者。”（《诗薮·内编》卷六）明王世懋认为：“（绝句）盛唐惟青莲（李白）、龙标（王昌龄）二家诣极。李更自然，故居王上。”（《艺圃撷馀》）怎样才算“自然”，才是“无意于工而无不工”呢？这首《静夜思》就是个样榜。所以胡氏特地把它提出来，说是“妙绝古今”。\n\n这首小诗，既没有奇特新颖的想象，更没有精工华美的辞藻；它只是用叙述的语气，写远客思乡之情，然...", "authors": ["马茂元"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f0ca07f27182da3800fd8", "shortContent": "这首小诗，既没有奇特新颖的想象，更没有精工华美的辞藻；它只是用叙述的语气，写远客思乡之情，然而它却意味深长，耐人寻绎，千百年来，如此广泛地吸引着读者。\n一个作客他乡的人，大概都会有这样的感觉吧：白天倒还罢了，到了夜深人静的时候，思乡的情绪，就难免一阵阵地在心头泛起波澜；何况是月明之夜，更何况是明月如霜的秋夜！\n月白霜清，是清秋夜景；以霜色形容月光，也是古典诗歌中所经常看到的。例如梁简文帝萧纲《玄圃...", "authors": ["马茂元"], "pressName": "上海辞书出版社"}]', '《唐诗品汇》：自是古意，不须言笑。
《唐诗正声》：百千旅情，妙复使人言说不得。天成偶语，讵由精炼得之？
《批点唐诗正声》：乐府体。老炼着意作，反不及此。
《增订评注唐诗正声》：悄悄冥冥，千古旅情，尽此十字（末二句下）。
范德机《李杜诗选》：五言短古，不可明白说尽，含糊则有余味，如此篇也。
《唐诗广选》：有第三句，自不意其末句忽转至此。便奇（“疑是”句下）。蒋仲舒曰：“举头”、“低头”，写出踌蹰踯躅之态。
《诗薮》：太白五言，如《静夜思》、《玉阶怨》等，妙绝古今，然亦齐、梁体格。他作视七言绝句，觉神韵小减，缘句短，逸气未舒耳。
《唐诗归》：忽然妙境，目中口中，凑泊不得，所谓不用意得之者。
《李诗钞》：偶然得之，读不可了。
《李诗通》：思归之辞，白自制名。
《唐诗解》：摹写静夜之景，字字真率，正济南所谓“不用意得之”者。
《增订唐诗摘钞》：思乡诗最多，终不如此四语真率而有味。此信口语，后人复不能摹拟，摹拟便丑，语似极率，回坏尽致。
《古唐诗合解》：此诗如不经意，而得之自然。故群服其神妙。
《唐诗别裁》：旅中情思，虽说叫却不说尽。
《唐诗选胜直解》：此旅怀之思。，月色侵床，凄清之景电，易动乡思。月光照地，恍疑霜白。举头低头、同此月也，一俯一仰间多少情怀。题云《静夜思》，淡而有味。
《唐宋诗醇》：《诗薮》谓古今专门大家得三人焉，陈思之古、拾遗之律、翰林之绝，皆天授而非人力也，要是确论。至所云唐五言绝多法齐梁，体制白别：此则气骨甚高，神韵甚穆，过齐梁远矣。
《唐诗笺注》：即景即情，忽离忽合，极质直却自情至。
《网师园唐诗笺》：得天趣（末二句下）。
《湖楼随笔》：李太白诗“床前明月光”云云，王昌龄诗“闺中少妇不知愁”云云，此两诗体格不伦而意实相准。夫闺中少妇本不知愁，方且凝妆而上翠楼，乃“忽见陌头杨柳色”，则“悔教夫婿觅封侯”矣。此以见春色之感人者深也。“床前明月光”，初以为地上之霜耳，乃举头而见明月，则低头而思故乡矣。此以见月色之感人者深也。盖欲言其感人之深而但言如何相感，则虽深仍浅矣。以无情言情则情出，从无意写意则意真。知此者可以打诗乎！
《诗境浅说续编》：前二句，取喻殊新。后二句，往举头、低头俄顷之间，顿生乡思。良以故乡之念，久蕴怀中，偶见床前明月，一触即发，正见其乡心之切。且“举头”、“低头”，联属用之，更见俯仰有致。
《李太白诗醇》：谢云：直书衷曲，不着色相。徐增曰：因“疑”则“望”，因“望”则“思”，并无他念，真“静夜思”也。
《唐人绝句精华》：李白此诗绝去雕采，纯出天真，犹是《子夜》民歌本色，故虽非用乐府古题，而古意盎然。', 'center', 1362523653, '57b926748ac2470062e0d025', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10170, '南乡子 · 细雨湿流光', NULL, 229, 105, 2, 2, '冯延巳', NULL, 10045, '57b90551128fe10054c9ae3e', '五代十国', 'ci', '词', 'http://baike.baidu.com/view/649421.htm', '', '细雨湿流光，芳草年年与恨长。烟锁凤楼无限事，茫茫，鸾镜鸳衾两断肠。
魂梦任悠扬，睡起杨花满绣床。薄悻不来门半掩，斜阳，负你残春泪几行。', '此词写怨妇思归。作品通过细腻的笔触描写了雨中的春草、凤楼、鸾镜、鸳衾、杨花等表达怨妇对于情郎不至，心中哀怨的情感。', '流光：流动，闪烁的光采。
凤楼：即凤台、秦楼，语本《列仙传》秦穆公之女弄玉所居之楼，尝引来凤凰。此处指妆楼。
鸾镜：妆镜的美称。
薄悻：薄情郎。', '细雨霏霏，浸湿了光阴，芳草萋萋，年复一年，与离恨一起生长。凤楼深深，多少情事如烟，封存在记忆之中。恍如隔世呦，望着饰有鸾鸟图案的铜镜，绣着鸳鸯的锦被，思念往事，寸断肝肠。
梦魂，信马由缰，千里飘荡，魂回梦觉，蓦然见杨花点点，飘满绣床。薄情负心的人呀，我半掩闺门，你却迟迟不来，夕阳西下，眼看辜负了三春的良辰美景，洒下清淡的泪珠几行。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74915e272d4b2253b9da", "shortContent": "此词写少女怀春之情。宋陈世修《阳春集序》评冯延巳词云：“观其思深辞丽，均律调新，真清奇飘逸之才也。”本篇摆脱花间词人对妇女容貌与服饰的描绘，而转向人物内心感情的刻画，思深辞丽，在词史上有一定影响。\n首句以咏草起兴。宋人周文璞云：“《花间集》只有五字绝佳：‘细雨湿流光’。景意俱微妙。”（见张端义《贵耳集》。按称《花间集》系误记，词乃见于《阳春集》。）近人王国维则以为此五字“能摄春草之魂”（《人间词话...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892dbb31680ae4c4b4ec", "shortContent": "此词写少女怀春之情。宋陈世修《阳春集序》评冯延巳词云：“观其思深辞丽，均律调新，真清奇飘逸之才也。”本篇摆脱花间词人对妇女容貌与服饰的描绘，而转向人物内心感情的刻画，思深辞丽，在词史上有一定影响。\n\n首句以咏草起兴。宋人周文璞云：“《花间集》只有五字绝佳：‘细雨湿流光’。景意俱微妙。”（见张端义《贵耳集》。按称《花间集》系误记，词乃见于《阳春集》。）近人王国维则以为此五字“能摄春草之魂”（《人间词...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}]', '刘知秋《唐五代两宋词简析》：此亦托闺情以自抒己怨望之情。观「烟锁」句，所谓「无限事」，所谓「茫茫」，言外必有具体事在，特未明言耳。⋯⋯后半阕即就闺思描写怨望之情事，「杨花满绣床」，是一片迷离景象，与「悠扬」之「魂梦」正相合，亦即前半「茫茫」二字之意，总之皆写心情之纷纭复杂也。
刘知秋《唐五代两宋词简析》：末句则无可奈何之词，写得幽怨动人，与和凝、欧阳炯辈之纯作艳情词不同，不可并论。
王靜安《人间词话》：人知和靖《点蜂唇》、圣俞《苏幕遮》、永叔《少年游》三阅为詠春草绝调，不知先有正中「细雨湿流光」五字，皆能摄春草之魂者也。
陈秋帆《阳春集笺》：按「细雨湿流光」，昔人多激赏之，周方泉、王荆公均极赞其妙。余谓冯此语，实本温庭筠《荷叶杯》「细雨湿愁红」、皇甫松《怨回纥》「江路湿红蕉」而来。又陈鹆《者旧续闻》称「赵彦端《渴金门》「波底夕阳红湿」，盖用「细雨湿流光」与「一帘疏雨湿春愁」之湿」云云。「一帘疏雨」，孙光宪《浣澳沙》词。词人善用「湿」字，《阳春》则承先启后耳。', 'indent', 1423169037, '57b027c10a2b580063231adf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10171, '谒金门 · 风乍起', NULL, 143, 105, 2, 2, '冯延巳', NULL, 10045, '57b90551128fe10054c9ae3e', '五代十国', 'ci', '词', 'http://baike.baidu.com/item/谒金门·风乍起', '', '风乍起，吹皱一池春水。闲引鸳鸯香径里，手挼红杏蕊。
斗鸭阑干独倚，碧玉搔头斜坠。终日望君君不至，举头闻鹊喜。', '此词上片以写景为主，点明时令、环境及人物活动；下片以抒情为主，并点明所以烦愁的原因。全词写贵族少妇在春日思念丈夫的百无聊赖的景况，反映了她的苦闷心情。', '谒金门：词牌名。
乍：忽然。
闲引：无聊地逗引着玩。
挼：揉搓。
斗鸭：以鸭相斗为欢乐。斗鸭阑和斗鸡台，都是官僚显贵取乐的场所。独：一作“遍”
碧玉搔头：一种碧玉做的簪子。《西京杂记》载：“（汉）武帝过李夫人，就取玉簪搔头；自此后，宫人搔头皆用玉。”', '春风乍起，吹皱了一池碧水。（我）闲来无事，在花间小径里逗引池中的鸳鸯，随手折下杏花蕊把它轻轻揉碎。独自倚靠在池边的栏杆上观看斗鸭，头上的碧玉簪斜垂下来。（我）整日思念心上人，但心上人始终不见回来，（正在愁闷时），忽然听到喜鹊的叫声。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74907d0ac1145494baf1", "shortContent": "在浩如烟海的古典诗词中，以闺怨为题材的作品，其数量之多难以胜数，然而能经受时间的考验又为人们所普遍喜爱、传诵而历久不衰的篇章，恐怕并不很多。而冯延巳的这首词，却是属于为数不多的优秀作品之一。它一问世，就博得了人们的高度赞赏。马令《南唐书·党与传下》有一段涉及此词的记载：“延巳有‘风乍起，吹皱一池春水’之句，皆为警策。元宗尝戏延巳曰：‘吹皱一池春水，干卿何事？’延巳曰：‘未如陛下“小楼吹彻玉笙寒”。...", "authors": ["高章采"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892dbb31680ae4c4b4e6", "shortContent": "在浩如烟海的古典诗词中，以闺怨为题材的作品，其数量之多难以胜数，然而能经受时间的考验又为人们所普遍喜爱、传诵而历久不衰的篇章，恐怕并不很多。而冯延巳的这首词，却是属于为数不多的优秀作品之一。它一问世，就博得了人们的高度赞赏。马令《南唐书·党与传下》有一段涉及此词的记载：“延巳有‘风乍起，吹皱一池春水’之句，皆为警策。元宗尝戏延巳曰：‘吹皱一池春水，干卿何事？’延巳曰：‘未如陛下“小楼吹彻玉笙寒”。...", "authors": ["高章采"], "pressName": "上海辞书出版社"}]', '俞陛云《唐五代两宋词选释》：“风乍起”二句破空而来，在有意无意间，如柴浮水，似沾非著，宜后主盛加称赏。此在南唐全盛时作。“喜闻鹊报”句，殆有束带弹冠之庆及效忠尽瘁之思也。
四印斋刻《阳春集序》：冯词类多劳人、思妇之作，“忧生念乱，意内而言外。”
《蓼园词选》引沈际飞云：闻鹊报喜，须知喜中还有疑在，无非望幸希宠之心，而语自清隽。
贺裳《皱水轩词筌》：南唐主（李璟）语冯延巳曰：“‘风乍起，吹皱一池春水’，何与卿事？”冯曰：“未若‘细雨梦回鸡塞远，小楼吹彻玉笙寒’。”不可使闻于邻国。然细看词意，含蓄尚多。又云：“无凭谐鹊语，犹觉暂心宽”，韩偓语也。冯延巳去偓不多时，用其语曰：“终日望君君不至，举头闻鹊喜。”虽窃其意，而语加蕴藉。', 'indent', 1423169173, '57b92a3779bc44005b9ffc34', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10172, '陋室铭', NULL, 1662, 815, 2, 15, '刘禹锡', NULL, 10047, '57b922b57db2a2005427bf3a', '唐', 'wen', '文', 'http://baike.baidu.com/view/218529.htm', '', '山不在高，有仙则名。水不在深，有龙则灵。斯是陋室，惟吾德馨。苔痕上阶绿，草色入帘青。谈笑有鸿儒，往来无白丁。可以调素琴，阅金经。无丝竹之乱耳，无案牍之劳形。南阳诸葛庐，西蜀子云亭。孔子云：「何陋之有？」', '《陋室铭》选自《全唐文》卷六百零八集，为唐代诗人刘禹锡所作。此文聚描写、抒情、议论于一体。通过具体描写「陋室」恬静、雅致的环境和主人高雅的风度来表述自己两袖清风的情怀。文章运用了对比，白描，隐寓，用典等手法，而且压韵，韵律感极强，读来金石掷地又自然流畅，一曲既终，犹余音绕梁，让人回味无穷。文章表现了作者不与世俗同流合污，洁身自好、不慕名利的生活态度。表达了作者高洁傲岸的情操，流露出作者安贫乐道的隐逸情趣。', '陋室：简陋的屋子。
铭：古代刻在器物上用来警戒自己或称述功德的文字，叫「铭」，后来就成为一种文体。这种文体一般都是用骈句，句式较为整齐，朗朗上口。
在（zài）：在于，动词。
名（míng）：出名，著名，名词用作动词。
灵（líng）：神奇、灵异。
斯是陋室（lòushì）：这是简陋的屋子。斯：此、这；是，表肯定的判断动词；陋室，简陋的屋子，这里指作者自己的屋子。
惟吾德馨（xīn）：只因为我的品德高尚（就不感到简陋了）。惟，只；吾，我，这里是指作者。馨，散布很远的香气，这里指（品德）高尚。《尚书·君陈》：「黍稷非馨，明德惟馨。」。
「苔痕上阶绿，草色入帘青。」句：苔痕碧绿，长到阶上；草色青葱，映入帘里。上，长到；入，映入。
鸿儒（hóngrú）：大儒，这里指博学的人。鸿，同「洪」，大。儒，旧指读书人。
白丁：平民。这里指没有什么学问的人。
调（tiáo）素琴：弹奏不加装饰的琴。调，调弄，这里指弹（琴）；素琴，不加装饰的琴。
金经：现今学术界仍存在争议，有学者认为是指佛经（《金刚经》），也有人认为是装饰精美的经典（《四书五经》），金，珍贵的，金者贵义，是珍贵的意思，儒释道的经典都可以说是金经。
丝竹：琴瑟、箫管等乐器的总称，「丝」指絃乐器，「竹」指管乐器。这里指奏乐的声音。
之：语气助词。
乱耳：扰乱双耳。乱，使……乱，扰乱。
案牍（dú）：（官府的）公文，文书。
劳形：使身体劳累（「使」动用法）。劳，使……劳累；形，形体、身体。
南阳：地名，今河南省南阳市。诸葛亮在出山之前，曾在南阳卧龙岗中隐居躬耕。
诸葛亮：字孔明，三国时蜀汉丞相，著名的政治家和军事家，出仕前曾隐居南阳卧龙岗中。
扬雄：字子雲，西汉时文学家，蜀郡成都人。
「南阳诸葛庐，西蜀子雲亭」句：南阳有诸葛亮的草庐，西蜀有扬子雲的亭子。诸葛庐和子云亭都很简陋，因为居住的人很有名，所以受到人们的景仰。庐，简陋的小屋子。
孔子云：孔子说。云，在文言文中一般都指说。《论语·子罕》：「君子居之，何陋之有？」作者在此去掉君子居之，体现他谦虚的品格。
何陋之有：即「有何之陋」，属于宾语前置。之，助词，表示强烈的反问，宾语前置的标志，不译。全句译为：有什么简陋的呢？《论语·子罕》：「君子居之，何陋之有？」这里以孔子之言，亦喻自己为「君子」，点明全文，这句话也是点睛之笔，全文的文眼。', '山不在于高，只要有仙人居住就会出名；水不在于深，只要有蛟龙栖留住就显神灵。这是一间简陋的居室，因我的美德使它芳名远扬。苔藓爬上台阶染出一片碧绿，草色映入竹帘映得漫屋青色。这里谈笑的都是博学多识的人，来往的没有不学无术之徒。平时可以弹奏清雅的古琴，阅读装饰精美的经典。没有繁杂的音乐搅扰听觉，没有文牍公务劳累身心。似南阳诸葛亮的草庐，如西蜀扬子云的草屋。孔子说：“这有什么简陋呢？”', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1eec6e67846a921a125", "shortContent": "《陋室铭》是一篇托物言志的铭文。它单纯、简练、清新像一首精粹的诗，充满了哲理和情韵。\n开篇几句从《世说新语·排调》“山不高则不灵，渊不深则不清”翻出新意，运用诗歌中常见的比兴手法引出陋室。“山不在高”、“水不在深”比兴陋室，“有仙则名”、“有龙则灵”则比兴陋室之德。这四句是脍炙人口的名言佳句，颇有哲理诗的精警和含蕴。\n作者自远而近，次第写来，以并列句式造成顺流直下的气势，随后托出“斯是陋室，惟吾德...", "authors": ["王少华"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "647208f645e4710056fc72a0", "shortContent": "《陋室铭》是一篇托物言志的铭文。它单纯、简练、清新像一首精粹的诗，充满了哲理和情韵。开\n篇几句从《世说新语·排调》“山不高则不灵，渊不深则不清”翻出新意，运用诗歌中常见的比兴手法引出陋室。“山不在高”“水不在深”比兴陋室，“有仙则名”“有龙则灵”则比兴陋室之德。这四句是脍炙人口的名言佳句，颇有哲理诗的精警和含蕴。\n作者自远而近，次第写来，以并列句式造成顺流直下的气势，随后托出“斯是陋室，惟吾德馨”...", "authors": ["王少华"], "pressName": "上海辞书出版社"}]', '', 'indent', 1415636628, '57ae026579bc440058cc0998', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10173, '乌衣巷', NULL, 1069, 815, 2, 7, '刘禹锡', NULL, 10047, '57b922b57db2a2005427bf3a', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/131760/7854736.htm', '', '朱雀桥边野草花，乌衣巷口夕阳斜。
旧时王谢堂前燕，飞入寻常百姓家。', '这是一首抚今吊古的诗篇，是怀古组诗《金陵五题》中的第二首。此诗凭吊昔日东晋南京秦淮河上朱雀桥和南岸的乌衣巷的繁华鼎盛，而今野草丛生，荒凉残照，感慨沧海桑田，人生多变。作者选取燕子寄居的主人家已经不是旧时的主人这一平常现象，使人们认识到富贵荣华难以常保，那些曾经煊赫一时的达官贵族，如过眼烟云，成为历史的陈迹。诗中没有一句议论，而是通过野草、夕阳的描写，以燕子作为盛衰兴亡的见证，巧妙地把历史和现实联系起来，引导人们去思考时代的发展和社会的变化，含着深刻的寓意。全诗语虽极浅，味却无限。', '乌衣巷：金陵城内街名，位于秦淮河之南，与朱雀桥相近。三国时期吴国曾设军营于此，为禁军驻地。由于当时禁军身着黑色军服，所以此地俗语称乌衣巷。在东晋时以王导、谢安两大家族，都居住在乌衣巷，人称其子弟为“乌衣郎”。入唐后，乌衣巷沦为废墟。
朱雀桥：六朝时金陵正南朱雀门外横跨秦淮河的大桥，在今江苏省南京市江宁区。
王谢：王导、谢安，晋相，世家大族，贤才众多，皆居巷中，冠盖簪缨，为六朝巨室。旧时王谢之家庭多燕子。至唐时，则皆衰落不知其处。
寻常：平常。', '朱雀桥边长满丛丛野草，点点野花。乌衣巷口断壁残垣，正是夕阳西斜。从前在王谢大堂前筑巢的燕子，如今再来飞进平常百姓人家。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c6d635634aee3dedb2", "shortContent": "《乌衣巷》曾博得白居易的“掉头苦吟，叹赏良久”（宋何汶《竹庄诗话》卷二十），是刘禹锡最得意的怀古名篇之一。\n首句“朱雀桥边野草花”，朱雀桥横跨南京秦淮河上，是由市中心通往乌衣巷的必经之路。桥同河南岸的乌衣巷，不仅地点相邻，历史上也有瓜葛。东晋时，乌衣巷是高门士族的聚居区，开国元勋王导和指挥淝水之战的谢安都住在这里。旧日桥上装饰着两只铜雀的重楼，就是谢安所建。在字面上，“朱雀桥”又同“乌衣巷”偶对天...", "authors": ["范之麟"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad9820695e6503ffe1", "shortContent": "《乌衣巷》曾博得白居易的“掉头苦吟，叹赏良久”（宋何汶《竹庄诗话》卷二十），是刘禹锡最得意的怀古名篇之一。\n\n首句“朱雀桥边野草花”，朱雀桥横跨南京秦淮河上，是由市中心通往乌衣巷的必经之路。桥同河南岸的乌衣巷，不仅地点相邻，历史上也有瓜葛。东晋时，乌衣巷是高门士族的聚居区，开国元勋王导和指挥淝水之战的谢安都住在这里。旧日桥上装饰着两只铜雀的重楼，就是谢安所建。在字面上，“朱雀桥”又同“乌衣巷”偶对...", "authors": ["范之麟"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290ef", "shortContent": "秦淮河，朱雀桥，乌衣巷，好一个繁华的所在。\n \n南京，秦淮河上，一桥飞架南北，这就是朱雀桥。桥的这一头，是奔走的车水马龙，寻着这些车马的影踪，我们的目光会转向桥的另一端。放眼望去，乌衣巷口，那里有巍峨的亭台楼阁。亭台楼阁之上，开国元勋王导和指挥了淝水之战的谢安等高门士族正舒适地坐定，静享玉液琼浆，海陆八珍。下人不时地奔走相告，说有客来访，静候大人的回话。兴致高时，“见！”于是客人带着十分谨慎，小心...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706fc9ebcc6fbea1a407", "shortContent": "秦淮河，朱雀桥，乌衣巷，好一个繁华的所在。\n\n南京，秦淮河上，一桥飞架南北，这就是朱雀桥。桥的这一头，车水马龙，寻着这些车马的影踪，我们的目光会转向桥的另一端。放眼望去，乌衣巷口，那里有巍峨的亭台楼阁。亭台楼阁之上，开国元勋王导和指挥了淝水之战的谢安等高门士族正舒适地坐定，静享玉液琼浆，海陆八珍。下人不时地奔走相告，说有客来访，静候大人的回话。兴致高时，“见”！于是客人带着十分谨慎，小心地同尊者说...", "authors": ["刘琴）"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127115e6f69b71e93f638b", "shortContent": "秦淮河，朱雀桥，乌衣巷，好一个繁华的所在。南京，秦淮河上，一桥飞架南北，这就是朱雀桥。桥的这一头，是奔走的车水马龙，寻着这些车马的影踪，我们的目光会转向桥的另一端。放眼望去，乌衣巷口，那里有巍峨的亭台楼阁。亭台楼阁之上，开国元勋王导和指挥了淝水之战的谢安等高门士族正舒适地坐定，静享玉液琼浆，海陆八珍。下人不时地奔走相告，说有客来访，静候大人的回话。兴致高时，“见”！于是客人带着十分谨慎，小心地同尊...", "authors": ["刘琴"], "pressName": "崇文书局"}]', '施补华《岘佣说诗》：若作燕子他去，便呆。盖燕子仍入此堂，王谢零落，已化作寻常百姓矣。如此则感慨无穷，用笔极曲。', 'center', 1417684507, '57b9292f8ac2470062e0e6cf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (634595, '唐才子传 · 道人灵一', NULL, 33, 128, 2, 0, '辛文房', NULL, 36761, '5830322c570c35006c044168', '元', 'wen', '文', '', '', '一公，剡中人。童子出家，瓶钵之外，余无有。天性超颖，追踪谢客，隐麻源第三谷中，结茆读书。后白业精进，居若耶溪云门寺，从学者四方而至矣。尤工诗，气质淳和，格律清畅。两浙名山，暨衡、庐诸甲刹，悉所经行。与皇甫昆季、严少府、朱山人、彻上人等为诗友，酬赠甚多。刻意声调，苦心不倦，骋誉丛林。后顺寂于岑山。集今传世。
论曰：自齐、梁以来，方外工文者，如支遁、道遒、惠休、宝月之俦，驰骤文苑，沉淫藻思，奇章伟什，绮错星陈，不为寡矣。厥后丧乱，兵革相寻，缁素亦已狼藉，罕有复入其流者。至唐累朝，雅道大振，古风再作，率皆崇衷像教，驻念津梁，龙象相望，金碧交映。虽寂寥之山河，实威仪之渊薮。宠光优渥，无逾此时。故有颠顿文场之人，憔悴江海之客，往往裂冠裳，拨矰缴，杳然高迈，云集萧斋，一食自甘，方袍便足，灵台澄皎，无事相干，三余有简牍之期，六时分吟讽之隙。青峰瞰门，绿水周舍，长廊步屟，幽径寻真，景变序迁，荡入冥思。凡此数者，皆达人雅士，夙所钦怀，虽则心侔迹殊，所趣无间。会稽传孙、许之玄谈，庐阜接谢、陶于白社，宜其日锻月炼，志弥厉而道弥精。佳句纵模，不废禅定，岩穴相迩，更唱迭酬，苦于三峡猿，清同九皋鹤，不其伟欤。与夫迷津畏途，埋玉世虑，蓄愤于心，发在篇咏者，未可同年而论矣。然道或浅深，价有轻重，未能悉采。其乔松于灌莽，野鹤于鸡群者，有灵一、灵彻、皎然、清塞、无可、虚中、齐己、贯休八人，皆东南产秀，共出一时，已为录实。其或虽以多而寡称，或着少而增价者，如惟审、护国、文益、可止、清江、法照、广宣、无本、修睦、无闷、太易、景云、法振、栖白、隐峦、处默、卿云、栖一、淡交、良乂、若虚、云表、昙域、子兰、僧鸾、怀楚、惠标、可朋、怀浦、慕幽、善生、亚齐、尚颜、栖蟾、理莹、归仁、玄宝、惠侃、法宣、文秀、僧泚、清尚、智暹、沧浩、不特第四十五人，名既隐僻，事且微冥，今不复喋喋云尔
', '', '', '', NULL, '', 'indent', 1489486777, '58c7531cac502e00621b064e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10174, '西塞山怀古', NULL, 226, 815, 2, 3, '刘禹锡', NULL, 10047, '57b922b57db2a2005427bf3a', '唐', 'shi', '诗', 'http://baike.baidu.com/view/159323.htm', '', '王濬楼船下益州，金陵王气黯然收。
千寻铁锁沉江底，一片降幡出石头。
人世几回伤往事，山形依旧枕寒流。
今逢四海为家日，故垒萧萧芦荻秋。', '此诗怀古伤今。前四句写西晋灭吴的历史故事，表现国家统一是历史之必然，阐发了事物兴废决定于人的思想；后四句写西塞山，点出它之所以闻名，是因为曾经是军事要塞，而今山形依旧，可是人事全非，拓开了诗的主题。全诗叙说的内容是历史上的事实，状摹的景色是眼前的实景，抒发的感叹是诗人胸中的真情。诗人巧妙地把史、景、情完美地揉合在一起，使得三者相映相衬，相长相生，营造出一种含蕴半瞻的苍凉意境，给人以沉郁顿挫之感。', '西塞山：位于今湖北省黄石市，又名道士洑，山体突出到长江中，因而形成长江弯道，站在山顶犹如身临江中。
王濬：晋益州刺史。一作“西晋”。益州：晋时郡治在今成都。晋武帝谋伐吴，派王濬造大船，出巴蜀，船上以木为城，起楼，每船可容二千余人。
金陵：今南京，当时是吴国的都城。王气：帝王之气。黯然：一作“漠然”。
千寻铁锁沉江底：东吴末帝孙皓命人在江中轧铁锥，又用大铁索横于江面，拦截晋船，终失败。寻：长度单位。
一片降幡（fān）出石头：王濬率船队从武昌顺流而下，直到金陵，攻破石头城，吴主孙皓到营门投降。
人世几回伤往事：一作“荒苑至今生茂草”。
枕寒流：一作“枕江流”。
四海为家：即四海归于一家，指全国统一。今逢：一作“从今”。
故垒：旧时的壁垒。萧萧：秋风的声音。', '王濬的战舰沿江东下离开益州，显赫无比的金陵王气骤然失色。
大火溶毁了百丈铁锁沉入江底，石头城上举起了降旗东吴灭亡。
人世间有多少叫人感伤的往事，西塞山依然背靠着滚滚的长江。
如今全国统一四海已成为一家，故垒已成废墟只有芦荻在飘摇。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c434a8757d5a0e1d5a", "shortContent": "西塞山，在今湖北大冶东面的长江边。岚横秋塞，山锁洪流，形势险峻，是六朝有名的军事要塞。长庆四年（824）刘禹锡由夔州刺史，调任和州刺史，沿江东下，途经西塞山，即景抒怀，写下了这首诗。太康元年（280）晋武帝命王濬率领以高大的战船组成的水军，顺江而下，讨伐东吴。诗人便以这件史事为题。\n开头写“楼船下益州”，“金陵王气”便黯然消失。益州（治今四川成都）、金陵（今江苏南京市），相距遥遥，一“下”即“收”...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad9820695e6503ffdb", "shortContent": "西塞山，在今湖北大冶东面的长江边。岚横秋塞，山锁洪流，形势险峻，是六朝有名的军事要塞。长庆四年（824）刘禹锡由夔州刺史，调任和州刺史，沿江东下，途经西塞山，即景抒怀，写下了这首诗。太康元年（280）晋武帝命王濬率领以高大的战船组成的水军，顺江而下，讨伐东吴。诗人便以这件史事为题。\n\n开头写“楼船下益州”，“金陵王气”便黯然消失。益州（治今四川成都）、金陵（今江苏南京市），相距遥遥，一“下”即“收...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290b7", "shortContent": "此诗作于唐穆宗长庆四年（824），刘禹锡由夔州调任和州刺史，途经西塞山，作者触景生情，抚今追昔，写下这篇咏史怀古的名篇。西塞山在今湖北大冶，因山体突出到长江中，地势险要，扼长江天堑，故为著名军事要塞，三国时东吴曾在此设防。此诗题为“西塞山怀古”，实则是写金陵六朝兴亡之事。\n\n首联以简洁洗练之语，概括了历史上著名的西晋灭东吴之事。西晋王濬的战船从益州出发，东吴的王气便黯然消逝。西晋灭东吴，本是历史上...", "authors": ["乐云"], "pressName": "崇文书局"}]', '汪师韩《诗学纂闻》：假使感古者取三国六代事，衍为长律，便使一句一事，包举无遗，岂成体制？梦得之专咏晋事，尊题也。下接云“人事几回伤往事”，若有上下千年，纵横万里在其笔底者。山形枕水之情，不涉其境，不悉其妙。至于芦荻萧萧，履清时而依故垒，含蕴正靡穷矣。所谓骊珠之得，或在于斯者欤？
薛雪《一瓢诗话》：似议非议，有论无论，笔着纸上，神来天际，气魄法律，无不精到，洵是此老一生杰作，自然压倒元、白。
屈复《唐诗成法》：前四句止就一事言，五以“几回”二字括过六代，繁简得宜，此法甚妙。
钱朝鼎《唐诗鼓吹笺注》：劈将王濬下益州起，加“楼船”二字，何等雄壮！随手接云：“金陵王气黯然收”，下一“收”字，何等惨溃！……看他前四句单写吴主孙皓，五忽转云“人世几回伤往事”，直将六朝人物变迁，世代废兴俱收在七字中。六又接云：“山形依旧枕寒流”，何等高雅，何等自然！末将无限衰飒字样写当今四海为家，于极感慨中却极壮丽，何等气度，何等佳构！此真唐人怀古之绝唱也。
《絸斋诗谈》：太平既久，向之霸业雄心消磨已净。此方是怀古胜场。
纪昀：第六句一笔折到西塞山是为圆熟。
俞陛云《诗境浅说》：余谓刘诗与崔颢《黄鹤楼》诗，异曲同工。崔诗从黄鹤仙人着想，前四句皆言仙人乘鹤事，一气贯注；刘诗从西塞山铁锁横江着想，前四句皆言王濬平吴事，亦一气贯注，非但切定本题，且七律诗能前四句专咏一事，而劲气直达者，在盛唐时，沈佺期《龙池篇》、李太白《鹦鹉篇》外，罕有能手。', 'center', 1413128671, '57b91c285bbb50005b790ca7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10175, '酬乐天扬州初逢席上见赠', NULL, 500, 815, 2, 13, '刘禹锡', NULL, 10047, '57b922b57db2a2005427bf3a', '唐', 'shi', '诗', 'http://baike.baidu.com/view/643972.htm', '', '巴山楚水凄凉地，二十三年弃置身。
怀旧空吟闻笛赋，到乡翻似烂柯人。
沉舟侧畔千帆过，病树前头万木春。
今日听君歌一曲，暂凭杯酒长精神。', '此诗作于唐敬宗宝历二年（826年），刘禹锡罢和州刺史返回洛阳，同时白居易从苏州返洛阳，二人在扬州初逢时，白居易在宴席上作诗赠与刘禹锡，刘禹锡也写诗作答。首联概写谪守巴楚、度尽劫难的经历。“凄凉地”、“弃置身”，虽语含哀怨，却在感伤中不失沉雄，凄婉中尤见苍劲。二联感叹旧友凋零、今昔异貌。“闻笛赋”、“烂柯人”，借典寄慨，耐人寻味。三联展示的却是生机勃勃的景象，寄寓在其中的是新陈代谢的进化思想和辩证地看待自己的困厄的豁达襟怀；在手法上，它则将诗情、画意、哲理熔于一炉，以形象的画面表现抽象的哲理，旨趣隽永。尾联顺势而下，请白氏举杯痛饮，藉以振奋精神。全诗感情真挚，起伏跌宕，沉郁中见豪放，不仅反映了深刻的人生哲理，也具有很强的艺术感染力。', '酬：答谢，酬答，这里是指以诗相答的意思。用诗歌赠答。
乐天：指白居易，字乐天。
见赠：送给（我）。
巴山楚水：指四川、湖南、湖北一带。古时四川东部属于巴国，湖南北部和湖北等地属于楚国。刘禹锡被贬后，迁徙于朗州、连州、夔州、和州等边远地区，这里用“巴山楚水”泛指这些地方。
二十三年：从唐顺宗永贞元年（805年）刘禹锡被贬为连州刺史，至宝历二年（826）冬应召，约22年。因贬地离京遥远，实际上到第二年才能回到京城，所以说23年。
弃置身：指遭受贬谪的诗人自己。置：放置。弃置：贬谪（zhé）。
怀旧：怀念故友。
吟：吟唱。
闻笛赋：指西晋向秀的《思旧赋》。三国曹魏末年，向秀的朋友嵇康、吕安因不满司马氏篡权而被杀害。后来，向秀经过嵇康、吕安的旧居，听到邻人吹笛，不禁悲从中来，于是作《思旧赋》。序文中说：自己经过嵇康旧居，因写此赋追念他。刘禹锡借用这个典故怀念已死去的王叔文、柳宗元等人。
到：到达。
翻似：倒好像。翻：副词，反而。
烂柯人：指晋人王质。相传晋人王质上山砍柴，看见两个童子下棋，就停下观看。等棋局终了，手中的斧柄（柯）已经朽烂。回到村里，才知道已过了一百年。同代人都已经亡故。作者以此典故表达自己遭贬23年的感慨。刘禹锡也借这个故事表达世事沧桑，人事全非，暮年返乡恍如隔世的心情。
沉舟：这是诗人以沉舟、病树自比。
侧畔：旁边。
歌一曲：指白居易的《醉赠刘二十八使君》。
长（zhǎng）精神：振作精神。长：增长，振作。', '在巴山楚水这些凄凉的地方，度过了二十三年沦落的光阴。
怀念故友徒然吟诵闻笛小赋，久谪归来感到已非旧时光景。
沉船的旁边正有千艘船驶过，病树的前头却也是万木争春。
今天听了你为我吟诵的诗篇，暂且借这一杯美酒振奋精神。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c42cee9a0c24ecf999", "shortContent": "唐敬宗宝历二年（826），刘禹锡罢和州（治今安徽和县）刺史任返洛阳，同时白居易从苏州归洛，两位诗人在扬州相逢。白居易在筵席上写了一首《醉赠刘二十八使君》诗相赠：“为我引杯添酒饮，与君把箸击盘歌。诗称国手徒为尔，命压人头不奈何。举眼风光长寂寞，满朝官职独蹉跎。亦知合被才名折，二十三年折太多。”刘禹锡便写了《酬乐天扬州初逢席上见赠》来酬答他。\n刘禹锡这首酬答诗，接过白诗的话头，着重抒写这特定环境中自己...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad9820695e6503ffdc", "shortContent": "唐敬宗宝历二年（826），刘禹锡罢和州（治今安徽和县）刺史任返洛阳，同时白居易从苏州归洛，两位诗人在扬州相逢。白居易在筵席上写了一首《醉赠刘二十八使君》诗相赠：“为我引杯添酒饮，与君把箸击盘歌。诗称国手徒为尔，命压人头不奈何。举眼风光长寂寞，满朝官职独蹉跎。亦知合被才名折，二十三年折太多。”刘禹锡便写了《酬乐天扬州初逢席上见赠》来酬答他。\n\n刘禹锡这首酬答诗，接过白诗的话头，着重抒写这特定环境中自...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706fc9ebcc6fbea1a408", "shortContent": "刘禹锡是中唐著名诗人和政治家，他曾参加永贞革新，失败后被贬出京，长达二十余年。宝历二年（826），他罢和州刺史任返洛阳，这时白居易也从苏州归洛阳，两位诗人在扬州相逢。白居易在筵席上写了一首诗相赠，刘禹锡便写了这首诗作答。\n\n“巴山楚水凄凉地，二十三年弃置身。”“巴山楚水”泛指贬官所历朗州、夔州等地。这些地方当时属荒凉僻远之地，穷山恶水，条件很差，加之自己又在贬谪之中，所以用“凄凉”来形容。“二十三...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127115e6f69b71e93f638c", "shortContent": "刘禹锡是中唐著名诗人和政治家，他曾参加永贞革新，失败后被贬出京，长达二十余年。宝历二年（826），他罢和州刺史任返洛阳，这时白居易也从苏州归洛阳，两位诗人在扬州相逢。白居易在筵席上写了一首诗相赠，刘禹锡便写了这首诗作答。\n\n“巴山楚水凄凉地，二十三年弃置身。”“巴山楚水”泛指贬官所历朗州、夔州等地。这些地方当时属荒凉僻远之地，穷山恶水，条件很差，加之自己又在贬谪之中，所以用“凄凉”来形容。“二十三...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f7e3b6a81d0c532b4a8a", "shortContent": "唐敬宗宝历二年(826)，刘禹锡罢和州（治今安徽和县）刺史任返洛阳，同时白居易从苏州归洛，两位诗人在扬州相逢。白居易在筵席上写了一首《醉赠刘二十八使君》诗相赠：“为我引杯添酒饮，与君把箸击盘歌。诗称国手徒为尔，命压人头不奈何。举眼风光长寂寞，满朝官职独蹉跎。亦知合被才名折，二十三年折太多。”刘禹锡便写了《酬乐天扬州初逢席上见赠》来酬答他。\n白居易的赠诗中有“举眼风光长寂寞，满朝官职独蹉跎”这样两句...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}]', NULL, 'center', 1423169218, '57ba7f66165abd0066233011', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10176, '秋词（其一）', NULL, 1080, 815, 2, 10, '刘禹锡', NULL, 10047, '57b922b57db2a2005427bf3a', '唐', 'shi', '诗', 'http://baike.baidu.com/view/159350.htm', '', '自古逢秋悲寂寥，我言秋日胜春朝。
晴空一鹤排云上，便引诗情到碧霄。', '这首诗是作者第一次被贬郎州（今湖南常德）时写的，他虽被贬谪，但却不悲观消沉，在这首诗中，诗人通过歌颂秋天的壮美，表达了他的乐观情绪和昂扬奋发的进取精神。这首诗的可贵，在于诗人对秋的感受与众不同，一反历来他人悲秋的情调，以奔放的热情、生动的画面，热情赞美秋日风光的美好，唱出了一首昂扬奋发的励志之歌。前两句是议论，直接表达了秋日胜春朝的看法。后两句晴空中排云而上的白鹤形象，把诗人的豪迈乐观之情抒发的淋漓尽致。', '悲寂寥：悲叹萧条空寂。宋玉《九辩》有“悲哉，秋之为气也”、“寂寥兮，收潦而水清”等句。
春朝：春初朝，朝，有早晨的意思，这里指的是刚开始。
晴：一作“横”。排云：推开白云。排：推开，有冲破的意思。
诗情：作诗的情绪、兴致。碧霄：青天。', '自古以来，骚人墨客都悲叹秋天萧条、凄凉、空旷。我却说秋天远远胜过春天。
秋日天高气爽，晴空万里。一只仙鹤直冲云霄推开层云，也激发我的诗情飞向万里晴空。', NULL, '', 'center', 1413128460, '57b8f6575bbb50005b77dd87', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10177, '西江月 · 平山堂', NULL, 506, 3406, 3, 2, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/867074.htm', '', '三过平山堂下，半生弹指声中。十年不见老仙翁，壁上龙蛇飞动。
欲吊文章太守，仍歌杨柳春风。休言万事转头空，未转头时皆梦。', '平山堂位于扬州西北大明寺侧，乃欧阳文忠于庆历八年（1048年）知扬州时所建。宋神宗元丰二年（1079年）四月，苏东坡自徐州调知湖州，生平第三次经过平山堂。这时距东坡和其恩师欧阳文忠最后一次见面已达九年，而欧阳文忠也已逝世八年。适逢自己政治处境艰难，东坡为重遊故地、缅怀恩师而作的这首词，自然会有抚今追昔的万千感慨。
东坡受佛家思想影响颇深，习惯用佛家的色空观念看待事物。白乐天诗云「百年随手过，万事转头空」，东坡则更进一步认识到「休言万事转头空，未转头时皆梦。」这种对整体人生的空幻、悔悟、淡漠感，这种携带某种禅意玄思的人生偶然的感喟，其中深深地埋藏着某种要求彻底解脱的出世意念。苏词中传达的这种独特的人生态度，是解读其作品的关键所在。', '西江月：词牌名。唐教坊曲名，源自南朝清商乐，属法部道曲，后用为词牌，最早见于唐玄宗时《教坊记》。调名或取自李太白《苏台览古》诗句「只今惟有西江月，曾照吴王官里人」。西江是长江的别称，调咏吴王、西施故事。是调大致形成于唐五代时期，初为流行于民间，后因清越哀伤，转入法部道曲。唐五代时存词数目较少，唐吕纯阳所作《西江月·著意黄庭岁久》、《西江月·任是聪明志士》两首为最早可见《西江月》，后人多谓系托名之作。《敦煌曲子词》存有三首无名氏的《西江月》，《尊前集》收录五代欧阳炯《西江月·月映长江秋水》、《西江月·水上鸳鸯比翼》两词，或为是调最早之文人作品。及至两宋，《西江月》词调之格律、音韵、句式等渐得统一，依调填词之词人辈出，凡一百五十六人，四百七十三首（不计异名词作），占两宋词坛词人总数之11.8%，词作总数之2.6%。欧阳炯词有「两岸蘋香暗起」句，又名《白蘋香》；因宋程洺水词而得名《步虚词》；因宋韩涧泉词而得名《晚香时候》、《晚春时候》；因元王行词而得名《江月令》；因元丘长春词宣传教义而得名《玉炉三涧雪》；因明马守贞词而得名《壶天晓》。唐五代词本为平仄韵异部间协，宋后词则上下阕各用两平韵，末转仄韵，例须同部。以柳屯田《西江月·凤额绣帘高捲》词为正体，双调五十字，前后阕各四句两平韵一叶韵。另有五十字前后阕各四句两平韵两叶韵，五十一字前后阕各四句两平韵两仄韵，五十六字前后阕各四句三平韵诸变体。
「平山堂」：傅注本、元延祐本无题。《东坡外集》题作「元丰七年过扬州」。兹从明吴讷钞本、《苏长公二妙集》本、茅维《苏集》本调名下题。
平山堂：傅子立注：「欧阳文忠公守扬州，于僧舍建平山堂，颇得观览之胜。」刘尚荣按：「参见南宋·王仪父《舆地纪胜·卷三十七·扬州景物》，别见北宋·叶石林《避暑录话·卷上》：『欧阳文忠公在扬州作平山堂，壮丽为淮南第一。堂据蜀冈，下临江南，下临江南数百里，真润金陵三州，隐隐可见。』」龙榆生笺引《舆地纪胜·卷三十七·扬州景物》：「在大明寺侧。负堂而望，江南诸山拱列檐下，故名，为士女游观之所。」
弹指：傅子立注：「释氏有一弹指之顷。」刘尚荣按：「《翻译名义集·卷五·时分篇第二十三》：『时极短者，谓刹那也。……壮士一弹指顷。六十五刹（chà）那。……一念中有九十刹那。……二十念为一瞬。二十瞬名一弹指。』或即傅注所本。」龙榆生笺：「《吕氏春秋》：『二十瞬为一弹指。』」按：此所引不见今本《吕氏春秋》。
十年：清·王文诰《苏文忠公诗编注集成总案》：「己未四月，同张大亨游平山堂。公倅杭、赴密、守湖，三过扬。熙宁辛亥，见欧阳公于汝阴，至是元丰己未，凡九年。词云『十年』，举成数也。时鲜于侁（shēn）自京东转运使移知扬州，此燕集平山堂主人也。」
老仙翁：傅子立注：「老仙翁，谓文忠公也。文忠公墨妙多著于平山堂。」
龙蛇飞动：傅子立注：「龙蛇飞动，言其笔势之腾扬如此。」
文章太守：傅子立注：「欧阳文忠公知滁州日，作亭琅琊山，自号醉翁，因以名亭。后守扬州，于僧寺建平山堂，甚得观览之胜。堂下手植柳数株。后数年，公在翰林，金华刘原父出守维扬，公出家乐饮饯，亲作《朝中措》词。议者谓非刘之才，不能当公之词。可谓双美矣。词曰：『平山栏槛倚晴空，山色有无中。手种堂前垂柳，别来几度春风。文章太守，挥毫万字，一饮千钟。行乐直须年少，尊前看取衰翁。』」
休言：《东坡外集》作「莫言」。
万事转头空：傅子立注引唐·白乐天《自咏》诗：「百年随手过，万事转头空。」
皆梦：元延祐本作「是梦」。毛本作「莫梦」。', '我第三次经过平山堂，前半生在弹指声中过去了。整十年没见老仙翁了，只有墙上他的墨迹，仍是那样气势雄浑，犹如龙飞蛇舞。我在平山堂前「欧公柳」的下面，写下这首词悼念文坛英杰，故扬州太守欧阳修。别说人死后万事皆空，即使活在世上，也不过是一场大梦呀！', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b003048e64fbd8932e", "shortContent": "宋神宗元丰二年（1079）四月，作者自徐州移知湖州，途经扬州时，知州鲜于侁设宴于平山堂。作者酒酣思贤，即席赋此词。释德洪《跋东坡平山堂词》云：“东坡登平山堂，怀醉翁，作此词。张嘉父谓予曰：时红妆成轮，名士堵立，看其落笔置笔，目送万里，殆欲仙去尔。”（《石门题跋》卷二）张嘉父与德洪均是作者的友人，张所云又是亲见，当为可信。\n词的上片写瞻仰欧词手迹而生感慨。作者对他的恩师欧阳修怀有深挚的情谊，此刻置身...", "authors": ["汤易水", "周义敢"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b72cee9a0c24ed9e4b", "shortContent": "宋神宗元丰二年（1079）四月，作者自徐州移知湖州，途经扬州时，知州鲜于侁设宴于平山堂。作者酒酣思贤，即席赋此词。释德洪《跋东坡平山堂词》云：“东坡登平山堂，怀醉翁，作此词。张嘉父谓予曰：时红妆成轮，名士堵立，看其落笔置笔，目送万里，殆欲仙去尔。”（《石门题跋》卷二）张嘉父与德洪均是作者的友人，张所云又是亲见，当为可信。\n词的上片写瞻仰欧词手迹而生感慨。作者对他的恩师欧阳修怀有深挚的情谊，此刻置身...", "authors": ["汤易水", "周义敢"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7c7ccdb86c49f28f90", "shortContent": "关于苏轼三过平山堂的考证如下：一过平山堂，《总案》、孔《谱》均编在熙宁四年（1071）十月由汴京赴杭倅时；二过平山堂，《总案》、孔《谱》均编在熙宁七年（1074）十月由杭倅移密守时；三过平山堂，王文诰《苏诗总案》卷一八云：“元丰二年己未（1079），四月，过扬州访鲜于侁，同张大亨游平山堂，作《西江月》词。”朱本、龙本、曹本、薛本、石塘本均据此而编此词于元丰二年四月。而孔《谱》则编元丰七年（1084...", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "64682ef85b7b0d4f451f2b49", "shortContent": "宋神宗元丰二年（1079）四月，作者自徐州移知湖州，途经扬州时，知州鲜于侁设宴于平山堂。作者酒酣思贤，即席赋此词。释德洪《跋东坡平山堂词》云：“东坡登平山堂，怀醉翁，作此词。张嘉父谓予曰：时红妆成轮，名士堵立，看其落笔置笔，目送万里，殆欲仙去尔。”（《石门题跋》卷二）张嘉父与德洪均是作者的友人，张所云又是亲见，当为可信。\n\n词的上片写瞻仰欧词手迹而生感慨。作者对他的恩师欧阳修怀有深挚的情谊，此刻置...", "authors": ["汤易水", "周义敢"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413196054, '57b8ae47d342d3005ac610ec', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10178, '水调歌头 · 黄州快哉亭赠张偓佺', NULL, 636, 3406, 7, 4, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/872456.htm', '', '落日绣帘卷，亭下水连空。知君为我新作，窗户湿青红。长记平山堂上，欹枕江南烟雨，杳杳没孤鸿。认得醉翁语，山色有无中。
一千顷，都镜净，倒碧峰。忽然浪起，掀舞一叶白头翁。堪笑兰台公子，未解庄生天籁，刚道有雌雄。一点浩然气，千里快哉风。', '苏东坡被贬黄州期间，结识同被谪放黄州的张偓佺。元丰六年（西元一〇八三年）十一月，张偓佺在其新居西南筑亭，以观览长江胜景，苏东坡为其取名为「快哉亭」，并赠其这首《水调歌头》。
全词把写景、抒情和议论熔为一炉，表现作者身处逆境却泰然处之、大气凛然的精神世界，在艺术构思和结构上，具有波澜起伏、跌宕多姿、大开大合、大起大落的特点，充分体现了苏词雄奇奔放的风格。', '水调歌头：词牌名。调名来源自《水调》曲。《水调》曲，隋炀帝所制也。唐·刘鼎卿《隋唐嘉话》：「炀帝凿汴河，自制《水调歌》。」宋·王颐堂《碧鸡漫志·卷四·〈水调歌〉》引《脞说》：「《水调》《河传》，炀帝将幸江都时自制，声韵悲切，帝喜之。乐工王令言谓其弟子曰：『不返矣，《水调》《河传》但有去声。』」《〈樊川诗集〉注·卷三·〈扬州〉诗》「谁家唱《水调》」句自注亦云：「炀帝凿汴河成，自造《水调》。」然《水调》究制于开汴河前或汴河开成后，三家说法不一，但为炀帝自制，则无异辞。逮唐，《水调》已为传唱不衰之名曲。盛唐王龙标有《听流人〈水调子〉》诗：「岭色千重万重雨，断弦收与泪痕深。」唐·段安节《乐府杂录·歌》：「开元中，内人有许和子者，本吉州永新县乐家女也，开元末选入宫，即以永新名之，籍于宜春院。既美且慧，善歌，能变新声。……洎渔阳之乱，六宫星散，永新为一士人所得。（金吾将军）韦青避地广陵，因月夜凭阑于小河之上，忽闻舟中奏《水调》者，曰：『此永新歌也。』乃登舟与永新对泣久之。青始亦晦其事。」可见《水调》为时人所熟。玄宗本人亦喜听此曲，奔蜀之前，登楼置酒，令善唱《水调》者登楼而歌，「闻之，潸然出涕」（唐·李朱崖《次柳氏旧闻》，唐·郑延美《明皇杂录》）。中唐白乐天有《听〈水调〉》诗：「不会当时翻曲意，此声肠断为何人？」晚唐罗昭谏亦有《席上歌〈水调〉》：「若使炀皇魂魄在，为君应合过江来。」至五代北宋，《水调》仍在传唱。宋·郑仲贤《南唐近事》载「（元宗）尝乘醉，命乐工杨花飞奏《水调辞》进酒。」南唐冯正中《抛球乐》亦有「《水调》声长醉里听」之句。北宋·张子野《天仙子》之「《水调》数声持酒听」更为人所熟。与子野同时而略晚的刘原甫《公是集》有《扬州闻歌》诗：「淮南旧有《于遮》舞，隋俗今传《水调》声。」一曲传唱四五百年，其魅力可见矣。唐时《水调》有大曲、小曲之分。大曲《水调》歌，「凡十一叠，前五叠为歌，后六叠为入破。其歌，第五叠五言调，声韵怨切。故白乐天诗云：『五言一遍最殷勤，调少情多似有因。不会当时翻曲意，此声肠断为何人？』」（《乐府诗集·卷七十九·〈水调〉歌》）按，《乐府诗集》所载十一叠《水调》，第一至第四叠（遍）歌为七言，第五叠为五言；入破第一至第五为七言，第六辙又为五言。《水调》小曲，为单曲歌唱（参任半塘《唐声诗·下编卷十三》）。王龙标所听《水调子》即是小曲。时《水调》主以笛奏，唐大曲《水调》第二叠歌辞即说「笛倚新翻《水调歌》」，冯正中《采桑子》：「《水调》何人吹笛声？」「唐又有新《水调》，亦商调曲也。」（《乐府诗集·卷七十九·〈水调〉歌》）《碧鸡漫志·卷四·〈水调歌〉》引白乐天《看采菱》诗所言「时唱一声新《水调》，谩人道是《采菱歌》」，即指「《水调》中新腔」。唐代《水调》，又指音调名，即一部乐之总名（非一曲之专名）。《唐会要·卷三十三》所载「南昌商，时号『水调』」，即指音调而言。《碧鸡漫志·卷四·〈水调歌〉》：「《理道要诀》所载唐乐曲，南吕商时号『水调』。予数见唐人说『水调』，各有不同。予因疑『水调』非曲名，乃俗呼音调之异名，今决矣。……《外史梼杌》云：『王衍泛舟巡阆中，舟子皆衣锦绣，自制水调《银汉曲》。』此『水调』中制《银汉曲》也。」王衍所制《银汉曲》，属「水调」乐部中之曲，故《银汉曲》前冠以「水调」。毛稚黄《填词名解·卷三》据此亦云：「水调者，一部乐之名也；《水调歌》者，一曲之名也。」《水调歌头》则是截取大曲《水调》之首章另倚新声而成。《填词名解》：「歌头，又曲之始音，如《六州歌头》、《氐州第一》之类。《海录碎事》云：『炀帝开汴河，自造《水调》，其歌颇多，谓之『歌头』，首章之一解也。顾从敬《诗馀笺释》云：『明皇欲幸蜀时，犹听唱《水调》，至「唯有年年秋雁飞」，因潸然，叹峤真才子！不待曲终。』水调曲颇广，因歌止首解，故谓之『歌头』。或云南唐元宗留心内宠，击鞫无虚日。乐工杨花飞奏《水调》词，但唱『南朝天子爱风流』一句，如是数四，以为讽谏。后人广其意为词，以其第一句，故称『水调歌头』云。」《水调歌头》与唐人《水调》所属宫调不同：唐《水调》，属商调曲；宋《水调歌头》，则为（中吕调《碧鸡漫志·卷四·〈水调歌〉》）。故《词谱·卷二十三》：「凡大曲歌头，另倚新声也。」毛东堂词名《元会曲》，张芸窗词名《凯歌》，吴梦窗词《江南好》，贺方回词名《台城游》，汪相如词名《水调歌》，姜白石词名《花犯念奴》，明杨升庵词名《花犯》。双调，九十五字，前后阕各四平韵。亦有前后阕两六言句夹叶仄韵者，有平仄互叶几于句句用韵者。
「快哉亭作」：元延祐本作「黄州快哉亭赠张偓佺」。《东坡外集》调名下注云：「黄州快哉亭，张君梦得谪居时作，子瞻为之命名，且赋词。」
水连空：傅子立注：「朱巨川：『水将空合色。』李正己：『白水连天暮。』」刘尚荣按：「朱句出《九日登青山》，见《全唐诗·卷三百〇六》。李句出《宿洞庭》，见《全唐诗·卷二百八十五》。」
窗户湿青红：傅子立注：「杜子美诗：『孤城西北起高楼，碧瓦朱甍照城郭。』」刘尚荣按：「句出《越王楼歌》，见《九家集注杜诗·卷十》。」
平山堂：傅子立注：「欧阳文忠公守扬州，于僧舍建平山堂，颇得观览之胜。」刘尚荣按：「参见南宋·王仪父《舆地纪胜·卷三十七·扬州景物》，别见北宋·叶石林《避暑录话·卷上》：『欧阳文忠公在扬州作平山堂，壮丽为淮南第一。堂据蜀冈，下临江南，下临江南数百里，真润金陵三州，隐隐可见。』」龙榆生笺引《舆地纪胜·卷三十七·扬州景物》：「在大明寺侧。负堂而望，江南诸山拱列檐下，故名，为士女游观之所。」
欹枕江南烟雨：龙榆生笺：「韦端己《东湖》诗：『何处最添诗客兴，黄昏烟雨乱蛙声。』」
杳杳没孤鸿：傅子立注：「罗虬《雁》诗：『影沉江雨暝。』」刘尚荣按：「《全唐诗》罗虬卷不收此诗，当是佚诗。」杳杳，元延祐本作「渺渺」；没，清钞本讹作「设」，今据珍重阁本改。
「认得醉翁语，山色有无中」：傅子立注：「欧阳文忠公知滁州日，作亭琅琊山，自号醉翁，因以名亭。后守扬州，于僧寺建平山堂，甚得观览之胜。堂下手植柳数株。后数年，公在翰林，金华刘原父出守维扬，公出家乐饮饯，亲作《朝中措》词。议者谓非刘之才，不能当公之词。可谓双美矣。词曰：『平山栏槛倚晴空，山色有无中。手种堂前垂柳，别来几度春风。文章太守，挥毫万字，一饮千钟。行乐直须年少，尊前看取衰翁。』」龙榆生笺：「宋本《醉翁琴趣外篇·醉偎香词》：『平山栏槛倚晴空，山色有无中。』《醉偎香》毛本作《朝中措》。」认取，元延祐本、明吴讷钞本、《苏长公二妙集》本作「认得」。
「一千顷，都镜净，倒碧峰」句：傅子立注：「韩退之：『曲江千顷秋波（原作「波秋」，据《昌黎文集》乙正）净，平铺红蕖盖明镜。』李太白：『湖阔数千里，湖光摇碧山。』徐骑省（清钞本误作「省骑」，今据珍重阁本乙正）《孺子亭记》云：『平湖千亩，凝碧乎其下；西山万叠，倒影乎其中。』」刘尚荣按：「韩句出《奉酬卢给事云夫四兄曲江荷花行见寄并呈上钱七兄（徽）阁老张十八助教》，见《五百家注昌黎文集·卷七》，别见《全唐诗·卷三百四十二》。李句出《陪从祖济南太守泛鹊山湖三首（其二）》，见《李太白诗集·卷二十》。徐记事详《苕溪渔隐丛话·后集卷十四》引《谈苑》，『知制诰日，与余恕同考试，恕曰：『夙昔师范徐骑省为文，骑省有《徐孺子亭记》，其警句云：「平湖千亩，凝碧乎其下；西山万叠，倒影乎其中。」他皆常语。』」
一叶白头翁：傅子立注：「郑都官：『白头波上白头翁，一叶舟移蒲蒲风（沈钞本「蒲」字不重文，珍重阁本误作「满蒲风」。今据《才调集》补正）。』」刘尚荣按：「郑都官《淮上渔者》诗『一叶舟』作『家逐船』，见《才调集·卷五》，别见《全唐诗·卷六百七十五》。」龙榆生笺引《江表传》：「会有白头鸟集殿前，孙权问：『此何鸟？』诸葛恪曰：『白头翁也。』张昭自以坐中最老，疑恪戏之，因曰：『欺陛下，未闻鸟名白头翁者。试使恪复寻白头母。』恪曰：『鸟名鹦母，未必有对。试使辅吴复求鹦父。』坐中皆笑。」
兰台公子：傅子立注：「楚襄王游于兰台之宫，宋玉侍，有风飒然而至者，王乃披襟而当之，曰：『快哉此风！寡人所与庶人共者耶？』宋玉对曰：『此独大王之风耳，庶人安得而共之！夫风与气殊焉。』因陈大王之雄风、庶人之雌风而赋之。」刘尚荣按：「详见《文选·卷十三·宋玉〈风赋并序〉》。」龙榆生笺引战国楚·宋玉《风赋》：「楚襄王游于兰台之宫，宋玉、景差侍。有风飒然而至，王乃披襟而当之，曰：『快哉此风！寡人所与庶人共者邪？』宋玉对曰：『此独大王之风耳，庶人安得而共之！』……王曰：『夫风，安生始哉？』宋玉对曰：『夫风生于地，起于青蘋之末，……故其清凉雄风，则飘举升降，乘淩高城，入于深宫。抵花叶而振气，徘徊于桂椒之间，翱翔于激水之上。将击芙蓉之精，猎蕙草，离秦蘅，概新夷，被荑杨，回穴冲陵，萧条众芳。然后徜徉中庭，北上玉堂，跻于罗幢，经于洞房，乃得为大王之风也。故其风中人，状直憯憯惏慄，清凉增欷。清清冷冷，愈病析酲，发明耳目，宁体便人。此所谓大王之雄风也。』王曰：『善哉论事！夫庶人之风，岂可闻乎？』宋玉对曰：『夫庶人之风，塕然起于穷巷之间，堀堁扬尘，勃郁烦冤，冲孔袭门。动沙堁，吹死灰，骇浑浊，扬腐馀，邪薄入瓮牖，至于室庐。故其风中人，状直憞混郁邑，驱温致湿，中心惨怛，生病造热。中唇为胗，得目为篾，啖齰嗽获，死生不卒。此所谓庶人之雌风也。』」
庄生天籁：傅子立注：「『天籁』则《庄子》载子綦之言曰：『夫吹万不同，而使其自已也。』」刘尚荣按：「《庄子·卷一·〈内篇·齐物论〉》：『（颜成）子游曰：「地籁则众窍是已，人籁则比竹是已，敢问天籁。」子綦曰：「夫吹万不同，而使其自已也，咸其自取，怒者其谁邪！」』傅注系节引而致文义不明矣。」
浩然气：傅子立注：「『浩然气』，孟子所谓『我善养吾浩然之气』。」刘尚荣按：「语见《孟子·公孙丑上》。」龙榆生笺引《孟子·公孙丑上》：「我知言，我善养吾浩然之气。……其为气也至大至刚，以直养而无害，则塞于天地之间。」', '落日中卷起绣帘眺望，亭下江水与碧空相接，远处的夕阳与亭台相映，空阔无际。为了我的来到，你特意在窗户上涂上了清油的朱漆，色彩犹新。这让我想起当年在平山堂的时候，靠着枕席，欣赏江南的烟雨，遥望远方天际孤鸿出没的情景。今天看到眼前的景象，我方体会到欧阳醉翁词句中所描绘的，山色若隐若现的景致。
广阔的水面十分明净，山峰翠绿的影子倒映其中。忽然江面波涛汹涌，一个渔翁驾着小舟在风浪中掀舞。见此不由得想起了宋玉的《风赋》，像宋玉这样可笑的人，是不可能理解庄子的风是天籁之说的，硬说什么风有雄雌。其实，一个人只要具备至大至刚的浩然之气，就能在任何境遇中都处之泰然，享受到无穷快意的千里雄风。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74af0ce818559d05079b", "shortContent": "张怀民字偓佺，又字梦得，谪居黄州，坦然自适，在其宅西南长江边筑亭，作为陶冶性情之所。苏轼贬黄州后，与张心境相同。他不仅欣赏江边的优美景致，而更钦佩张的气度。所以，苏轼为张的亭台取名为“快哉亭”，并赋此词相赠。时为宋神宗元丰六年（1083）。其后，苏辙又写《黄州快哉亭记》，极其生动地描绘了“快哉亭”周围的山光水影，并把张怀民的处世精神，予以表述。因而，苏辙这篇散文，便成为苏轼这首词的姊妹篇。\n这首词...", "authors": ["陆永品"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b6d635634aee3e9a79", "shortContent": "张怀民字偓佺，又字梦得，谪居黄州，坦然自适，在其宅西南长江边筑亭，作为陶冶性情之所。苏轼贬黄州后，与张心境相同。他不仅欣赏江边的优美景致，而更钦佩张的气度。所以，苏轼为张的亭台取名为“快哉亭”，并赋此词相赠。时为宋神宗元丰六年（1083）。其后，苏辙又写《黄州快哉亭记》，极其生动地描绘了“快哉亭”周围的山光水影，并把张怀民的处世精神，予以表述。因而，苏辙这篇散文，便成为苏轼这首词的姊妹篇。\n这首词...", "authors": ["陆永品〔注〕①", "天籁：《庄子·齐物论》说：“女汝闻人籁，而未闻地籁；女闻地籁，而未闻天籁夫！”“人籁”，谓箫管之音。“地籁”，谓穴窍之声。“天籁”，谓自然界的声响。"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253f534825dee9fd6db", "shortContent": "张怀民字偓佺，又字梦得，谪居黄州，坦然自适，在其宅西南长江边筑亭，作为陶冶性情之所。苏轼贬黄州后，与张心境相同。他不仅欣赏江边的优美景致，而更钦佩张的气度。所以，苏轼为张的亭台取名为“快哉亭”，并赋此词相赠。时为宋神宗元丰六年（1083）。其后，苏辙又写《黄州快哉亭记》，极其生动地描绘了“快哉亭”周围的山光水影，并把张怀民的处世精神，予以表述。因而，苏辙这篇散文，便成为苏轼这首词的姊妹篇。\n\n这首...", "authors": ["陆永品"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7c7ccdb86c49f28f81", "shortContent": "傅藻《东坡纪年录》云：“元丰六年癸亥，于快哉亭作《水调歌头》赠张偓佺。”王文诰《苏诗总案》卷二十二：癸亥闰六月，“张梦得营新居于江上，筑亭，公榜曰‘快哉亭’，作《水调歌头》。”薛本从之。而苏辙《栾城集》卷二十四《黄州快哉亭记》后署日期则为元丰六年十一月。邹王本即据此编元丰六年癸亥（1083）十一月，作于黄州。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "64682aa27da2f75ac7f60238", "shortContent": "张怀民字偓佺，又字梦得，谪居黄州，坦然自适，在其宅西南长江边筑亭，作为陶冶性情之所。苏轼贬黄州后，与张心境相同。他不仅欣赏江边的优美景致，而更钦佩张的气度。所以，苏轼为张的亭台取名为“快哉亭”，并赋此词相赠。时为宋神宗元丰六年（1083）。其后，苏辙又写《黄州快哉亭记》，极其生动地描绘了“快哉亭”周围的山光水影，并把张怀民的处世精神，予以表述。因而，苏辙这篇散文，便成为苏轼这首词的姊妹篇。\n\n这首...", "authors": ["陆永品"], "pressName": "上海辞书出版社"}]', '刘融斋《艺概·诗概》：其精微超旷，真足以开拓心胸，推倒豪杰。
郑瘦碧评《东坡乐府》：此等句法，使作者稍稍矜才使气，便流入粗豪一派。妙能写景中人，用生出无情思。', 'indent', 1362600114, '57b8df620a2b58005c918dff', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (78132, '阴雨', NULL, 3, 2952, 0, 1, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', NULL, NULL, '岚雾今朝重，江山此地深。
滩声秋更急，峡气晓多阴。
望阙云遮眼，思乡雨滴心。
将何慰幽独，赖此北窗琴。', NULL, NULL, NULL, NULL, NULL, 'center', 1581205521, '585d08b9128fe10069cbd9ea', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10180, '扬州慢', NULL, 799, 288, 7, 7, '姜夔', NULL, 10049, '57b97702a633bd006661948c', '宋', 'ci', '词', 'http://baike.baidu.com/view/2753818.htm', '淳熙丙申至日，予过维扬。夜雪初霁，荠麦弥望。入其城，则四顾萧条，寒水自碧，暮色渐起，戍角悲吟。予怀怆然，感慨今昔，因自度此曲。千岩老人以为有《黍离》之悲也。', '淮左名都，竹西佳处，解鞍少驻初程。过春风十里，尽荠麦青青。自胡马窥江去后，废池乔木，犹厌言兵。渐黄昏，清角吹寒，都在空城。
杜郎俊赏，算而今，重到须惊。纵豆蔻词工，青楼梦好，难赋深情。二十四桥仍在，波心荡，冷月无声。念桥边红药，年年知为谁生？', '此词开头三句点明扬州昔日名满国中的繁华景象，以及自己对传闻中扬州的深情向往；接着二句写映入眼帘的只是无边的荠麦，与昔日盛况截然不同；「自胡马」三句，言明眼前的残败荒凉完全是金兵南侵造成的，在人们心灵上留下不可磨灭的创伤；「渐黄昏」二句，以回荡于整座空城之上的凄凉呜咽的号角声，进一步烘托今日扬州的荒凉落寞。下片化用杜牧系列诗意，抒写自己哀时伤乱、怀昔感今的情怀。「杜郎」成为词人的化身，词的表面是咏史、写古人，更深一层是写己与叹今。
全词洗尽铅华，用雅洁洗练的语言，描绘出凄淡空蒙的画面，笔法空灵，寄寓深长，声调低婉，具有清刚峭拔之气势，冷僻幽独之情怀。它既控诉了金朝统治者发动掠夺战争所造成的灾难，又对南宋王朝的偏安政策有所谴责，有一定的积极意义。', '扬州慢：词牌名，又名《郎州慢》，上下阕，九十八字，平韵。此调为姜白石自度曲，后人多用以抒发怀古之思。
淳熙丙申：淳熙三年（西元一一七六年）。
至日：冬至。
维扬：即扬州（今属江苏）。
荠麦：荠菜和野生的麦。
弥望：满眼。
戍角：军营中发出的号角声。
千岩老人：南宋诗人萧德藻，字东夫，自号千岩老人。姜白石曾跟他学诗，又是他的姪婿。
黍离：《诗经·王风》篇名。据说周平王东迁后，周大夫经过西周故都，看见宗庙毁坏，尽为禾黍，彷徨不忍离去，就做了此诗。后以「黍离」表示故国之思。
淮左名都：指扬州。宋朝的行政区设有淮南东路和淮南西路，扬州是淮南东路的首府，故称淮左名都。左，古人方位名，面朝南时，东为左，西为右；名都，著名的都会。
解鞍：解下马鞍。
少驻：稍作停留。
初程：初段行程。
春风十里：唐杜牧《赠别》诗：「春风十里扬州路，捲上珠帘总不如。」这里用以借指扬州。
胡马窥江：指金兵侵略长江流域地区，洗劫扬州。这里应指第二次洗劫扬州。
废池乔木：废毁的池台和残存的古树。二者都是乱后馀物，表明城中荒芜，人烟萧条。
渐：向，到。
清角：悽清的号角声。
杜郎：即杜牧。唐文宗大和七年到九年，杜牧在扬州任淮南节度使掌书记。
俊赏：俊逸清赏。锺仲伟《诗品序》：「近彭城刘士章，俊赏才士。」
豆蔻词工：唐·杜牧《赠别》：「娉娉袅袅十三馀，豆蔻梢头二月初。」豆蔻，形容少女美艳。
青楼梦好：唐杜牧《遣怀》诗：「十年一觉扬州梦，赢得青楼薄倖名。」青楼，妓院。
二十四桥：扬州城内古桥，即吴家砖桥，也叫红药桥。此处非实指。
红药：红芍药花，是扬州繁华时期的名花。', '淳熙年丙申月冬至这天，我经过扬州。夜雪初晴，放眼望去，全是荠草和麦子。进入扬州，一片萧条，河水碧绿凄冷，天色渐晚，城中响起凄凉的号角。我内心悲凉，感慨于扬州城今昔的变化，于是自创了这支曲子。千岩老人认为这首词有《黍离》的悲凉意蕴。
扬州是淮河东边著名的大都，在竹西亭美好的住处，解下马鞍少为停留，这是最初的路程。过去是十里春风一派繁荣景色，而我如今看到却长满荠麦叶草一片青青。金兵侵略长江流域地区，二次洗劫扬州后，到处都是废毁的池台和残存的古树。至今还讨厌说起旧日用兵。天气渐渐进入黄昏，凄凉的号角吹起了冷寒，这都是在劫后的扬州城。
杜牧有卓越的鉴赏，料想今天，重来此地一定吃惊。即使「豆蔻」词语精工，青楼美梦的诗意很好，也很难表达出深厚的感情。二十四桥仍然还在，却桥下江中的波浪浩荡，凄冷的月色，处处寂静无声。怀念桥边的红芍药，可每一年知道它替什么人开花繁生！', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74f334a8757d5a0d9f0f", "shortContent": "这首词写于宋孝宗淳熙三年（1176）冬至日，词前的小序对写作时间、地点及写作动因均作了交代。姜夔因路过扬州，目睹了战争洗劫后扬州的萧条景象，抚今追昔，悲叹今日的荒凉，追忆昔日的繁华，发为吟咏，以寄托对扬州昔日繁华的怀念和对今日山河残破的哀思。\n这首词在艺术表现上的一个显著特点是写景物带有浓厚的感情色彩，景中含情，化景物为情思。它的写景，不俗不滥，紧紧围绕着一个统一的主题，即为抒发“黍离之悲”服务。...", "authors": ["刘文忠"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5f55914587d02f590ab", "shortContent": "这首词写于宋孝宗淳熙三年（1176）冬至日，词前的小序对写作时间、地点及写作动因均作了交待。姜夔因路过扬州，目睹了战争洗劫后扬州的萧条景象，抚今追昔，悲叹今日的荒凉，追忆昔日的繁华，发为吟咏，以寄托对扬州昔日繁华的怀念和对今日山河残破的哀思。\n这首词在艺术表现上的一个显著特点是写景物带有浓厚的感情色彩，景中含情，化景物为情思。它的写景，不俗不滥，紧紧围绕着一个统一的主题，即为抒发“黍离之悲”服务。...", "authors": ["刘文忠"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255f6542516c6de7fb6", "shortContent": "这首词写于宋孝宗淳熙三年（1176）冬至日，词前的小序对写作时间、地点及写作动因均作了交待。姜夔因路过扬州，目睹了战争洗劫后扬州的萧条景象，抚今追昔，悲叹今日的荒凉，追忆昔日的繁华，发为吟咏，以寄托对扬州昔日繁华的怀念和对今日山河残破的哀思。\n\n这首词在艺术表现上的一个显著特点是写景物带有浓厚的感情色彩，景中含情，化景物为情思。它的写景，不俗不滥，紧紧围绕着一个统一的主题，即为抒发“黍离之悲”服务...", "authors": ["刘文忠"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f52f2af4e09d55b665c", "shortContent": "《扬州慢》词牌为姜夔首创。词人路过扬州，目睹曾经的名都扬州，此时经过战争之乱，已是荒芜残破，词人百感交集，自度此曲，以抒发其感怀河山破败之伤。姜夔有十七首自度曲，这是写得最早的一首，时年姜夔二十二岁。\n词的上片，姜夔先从自己的行踪写起。这是他第一次来到扬州城，他在著名的竹西亭解鞍下马，驻足观看，走在漫长的扬州道上，词人满眼所见到的是长势旺盛而齐整的荠麦，而曾经繁华无比的那个大城市扬州已经不见踪影。...", "authors": ["陈庆之"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312704a77683d193301537a", "shortContent": "扬州慢》词牌为姜夔首创。词人路过扬州，目睹曾经的名都扬州，此时经过战乱，已是荒芜残破。词人百感交集，自度此曲，以抒发其感怀河山破败之伤。姜夔有十七首自度曲，这是写得最早的一首，时年二十二岁。\n\n词的上片，姜夔先从自己的行踪写起。这是他第一次来到扬州城，他在著名的竹西亭解鞍下马，驻足观看，走在漫长的扬州道上，词人满眼所见到的是长势旺盛而齐整的荠麦，而曾经繁华无比的那个大城市扬州已经不见踪影。胡马窥江...", "authors": ["陈庆之"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631272139761253910e90691", "shortContent": "《扬州慢》词牌为姜夔首创。词人路过扬州，目睹曾经的名都扬州，此时经过战乱，已是荒芜残破。词人百感交集，自度此曲，以抒发其感怀河山破败之伤。姜夔有十七首自度曲，这是写得最早的一首，时年姜夔二十二岁。\n词的上片，姜夔先从自己的行踪写起，这是他第一次来到扬州城，他在著名的竹西亭解鞍下马，驻足观看，走在漫长的扬州道上，词人满眼所见到的是长势旺盛而齐整的荠麦，而曾经繁华无比的那个大城市扬州已经不见踪影。胡马...", "authors": ["陈庆之"], "pressName": "崇文书局"}, {"bookId": "645d10a9e745e33de31310c7", "bookTitle": "姜夔诗词鉴赏辞典", "articleId": "64689f8a7da2f75ac7f871b5", "shortContent": "这首词写于宋孝宗淳熙三年（1176）冬至日，词前的小序对写作时间、地点及写作动因均作了交代。姜夔因路过扬州，目睹了战争洗劫后扬州的萧条景象，抚今追昔，悲叹今日的荒凉，追忆昔日的繁华，发为吟咏，以寄托对扬州昔日繁华的怀念和对今日山河残破的哀思。\n\n这首词在艺术表现上的一个显著特点是写景物带有浓厚的感情色彩，景中含情，化景物为情思。它的写景，不俗不滥，紧紧围绕着一个统一的主题，即为抒发“黍离之悲”服务...", "authors": ["刘文忠"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "6471760782772d459425753a", "shortContent": "这首词写于宋孝宗淳熙三年(1176 )冬至日，词前的小序对写作时间、地点及写作动因均作了交代。姜夔因路过扬州，目睹了战争洗劫后扬州的萧条景象，抚今追昔，悲叹今日的荒凉，追忆昔日的繁华，发为吟咏，以寄托对扬州昔日繁华的怀念和对今日山河残破的哀思。\n这首词在艺术表现上的一个显著特点是写景物带有浓厚的感情色彩，景中含情，化景物为情思。它的写景，不俗不滥，紧紧围绕着一个统一的主题，即为抒发“黍离之悲”服务...", "authors": ["刘文忠"], "pressName": "上海辞书出版社"}]', '宋·张玉田《词源》：白石词疏影、暗香、扬州慢、一萼红、琵琶仙、探春、八归、淡黄柳等曲，不惟清空，又且骚雅，读之使入神观飞越。
清·先著《词洁辑评》：「二十四桥仍在，波心荡、冷月无声」，是「荡」字着力。所谓一字得力，通首光彩，非炼字不能，然炼变亦未易到。「水」、「桥」、「月」点明今昔情景的不同。
清·陈亦峰《白雨斋词话》：「犹厌言兵」的「厌」字，写得极其传神。意谓扬州遭兵火后，荒废的池沼、尚存的大树，至今仍厌恶谈论战事。「无数伤乱语，他人累千百言，亦此韵味。」
清·郑鹤翁批《白石道人歌曲》：绍兴三十年，完颜亮南寇，江淮军败，中外震骇。亮寻为其臣下弑于瓜州。此词作于淳熙三年，寇平已十有六年，而景物萧条，依然有废池乔木之感。
唐季特《唐宋词简释》：此首写维扬乱后景色，悽怆已极。千岩老人，以为有《黍离》之悲，信不虚也。至文笔之清刚，情韵之绵邈，亦令人讽诵不厌。起首八字，以拙重之笔，点明维扬昔时之繁盛。「解鞍」句，记过维扬。「过春风」两句，忽地折入现时荒凉景象，警动异常。且十字包括一切，十里荠麦，则乱后之人与屋宇，荡然无存可知矣。正与杜甫「城春草木深」同意。「自胡马」三句，更言乱事之惨，即废池乔木，犹厌言之，则人之伤心自不待言。「渐黄昏」两句，再点出空城寒角，尤觉悽寂万分。换头，用杜牧之诗意，伤今怀昔，不尽歔欷。「重到须惊」一层，「难赋深情」又进一层，「二十四」两句，以现景寓情，字练句烹，振动全篇。末句收束，亦含哀无限。正亦杜甫「细柳新蒲为谁绿」之意。玉田谓白石《琵琶仙》，与少游《八六子》同工。若此首，亦与少游《满庭芳》同为情韵兼胜之作。惟少游笔柔，白石笔健。少游所写为身世之感，白石则感怀家国，哀时伤乱，境极悽焉可伤，语更沈痛无比。参军芜城之赋，似不得专美于前矣。周止庵既屈白石于稼轩下，又谓白石情浅，皆非公论。
沈紫曼《宋词赏析》：首两句，赒济指为「俗滥处」，不知于天下名胜、昔日繁华，特郑重言之，益见「荠麦青青」、「废池乔木」、「黄昏清角」种种荒凉之不堪回首，乃有力之反衬，非漫然之滥调也。「过春风」两句，序所谓「《黍离》之悲」。十里长街，惟馀荠麦，则屋宇荡然可知。「废池乔木，犹厌言兵」，则居人心情可知。「渐黄昏」两句，点明时刻，补足荒寒景况。下阕用杜牧诗意，而以「重到须惊」四字翻进一层。「俊赏」与起两句绾合，「须惊」、「难赋」与「过春风」以下绾合，昔之繁盛，今之残破，俱在其中；而上阕著重景色，下阕著重情怀，意虽接连，词无重复。「二十四桥」两句，与「黄昏」相应，又以「仍在」二字点出今昔之感。结句言昔之「名都」，今则「空城」，纵「桥边红药」，年年自开，岂复有春游之盛？「知为谁生」，叹花固不知，人亦不知也。清初蒋超《金陵旧院》云：「锦绣歌残翠黛尘，楼台已尽曲池烟。荒园一种瓢儿菜，独佔秦淮旧日春。」词中荠麦，即诗中瓢儿菜也。', 'indent', 1413462251, '57aea5662e958a00544a6f7a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10181, '蝶恋花 · 春景', NULL, 1029, 3406, 4, 4, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/2892201.htm', '', '花褪残红青杏小。燕子飞时，绿水人家绕。枝上柳绵吹又少，天涯何处无芳草！
墙里秋千墙外道。墙外行人，墙里佳人笑。笑渐不闻声渐悄，多情却被无情恼。', '此词是由北宋时期著名文学家苏东坡任密州（今山东诸城）太守时所作。上阕写春，触目红花纷谢，柳绵日少，青杏初结，普天芳草，充满了繁华易逝，「落花流水春去也」之意。下阕写伤情，借「多情却被无情恼」的意象，寓有对朝廷一片痴心却被贬官远谪的惆怅，表达出作者仕途坎坷、飘泊天涯的失落心情。', '蝶恋花：词牌名。原为唐教坊曲，後用作词牌，本名《鹊踏枝》，明杨升庵《词品·卷一·词名多取诗句》谓「《蝶恋花》则取梁元帝『翻阶蛱蝶恋花情。』」清毛稚黄《填词名解·卷二》袭升庵论，谓：「梁简文帝乐府有『翻阶蛱蝶恋花情』故名。」按，升庵误记作者，句出梁简文帝《东飞伯劳歌二首（其一）》：「翻阶蛱蝶恋花情，容华飞燕相逢迎。」今人李琏生《中国历代词分调评注〈蝶恋花〉》从词调史驳前人论，谓「《蝶恋花》虽与梁简文帝诗有关，或出于明人附会，绝非六朝时所制曲。此调本唐教坊曲，源于盛唐，属新燕乐曲。」《蝶恋花》之名采于前人诗句，原以《鹊踏枝》之名列于唐教坊曲，张梦机《词律探源》谓「自北宋晏同叔词，始改调名为《蝶恋花》，词家遂不复知有《鹊踏枝》之本意矣。」按，易《鹊踏枝》为「蝶恋花」之作实始于南唐李後主《蝶恋花·遥夜亭皋闲信步》。王易《词曲史》：「此首乃由七言八句变为仄韵，双叠。第二、六句各增二字，破为四五句。」《钦定词谱》列《蝶恋花》三体；清万红友《词律》列《蝶恋花》为平仄互叶体；龙榆生《唐宋词格律》列《蝶恋花》为仄韵格，注：「双调，六十字，上下阕各四仄韵。」以南唐冯正中《蝶恋花·六曲阑干偎碧树》（一作晏同叔词）为正体。《乐章集》、《张子野词》并入「小石调」，《清真集》入「商调」，《太平乐府》注「双调」，赵德鳞词有《商调蝶恋花》，联章作《鼓子词》，咏《会真记》事。冯正中词有「杨柳风轻，展尽黄金缕」句，名《黄金缕》。赵德鳞词有「不捲珠簾，人在深深院」句，名《捲珠簾》。司马才仲词有「夜凉明月生南浦」句，名《明月生南浦》。韩涧泉词有「细雨吹池沼」句，名《细雨吹池沼》。贺方回词名《凤栖梧》，李方舟词名《一箩金》，衷元吉词名《鱼水同欢》，沈文伯词名《转调蝶恋花》。
题注：傅注本存目阕词，据元延祐本补足正文，并以明吴讷钞本等加以校订。注文则仍付阙如。元延祐本无题，明吴讷钞本、《苏长公二妙集》本、茅维《苏集》本、毛本题作「春景」。
青杏小：毛本作「青杏了」。
飞：《苏长公二妙集》本、毛本原注：「一作『来』」。
人家绕：《全芳备祖集·後集卷五·〈杏·乐府〉》引此词作「门前绕」。绕，元延祐本原校：「一作『晓』。」', '花儿残红褪尽，树梢上长出了小小的青杏，燕子在天空飞舞。清澈的河流围绕着村落人家。柳枝上的柳絮已被风吹得越来越少，天涯路远，哪里没有芳草呢！
围墙里有位少女正荡着秋千，围墙外行人经过，听到了墙里佳人的笑声。笑声渐渐就听不到了。声音渐渐消散了。行人怅然，仿佛自己的多情被少女的无情所伤。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b3c6e67846a9206b18", "shortContent": "在词史上，苏轼是豪放派的代表作家。他的词横放杰出，清旷雄奇，“歌之曲终，觉天风海雨逼人”（陆游《跋东坡七夕词后》）。然而这样的作品不多，就数量而言，大都比较婉约。所以南宋王灼在《碧鸡漫志》中说：“东坡先生以文章余事作诗，溢而作词曲，高处出神入天，平处尚临镜笑春。”这两种风格似乎都融合在这首词中，它清婉雅丽，深笃超迈，具有一种扣人心弦的艺术魅力。\n此词上阕写暮春景色与伤春情绪，然却作旷达之语。这在一...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ba0ce818559d063b79", "shortContent": "在词史上，苏轼是豪放派的代表作家。他的词横放杰出，清旷雄奇，“歌之曲终，觉天风海雨逼人”（陆游《跋东坡七夕词后》）。然而这样的作品不多，就数量而言，大都比较婉约。所以南宋王灼在《碧鸡漫志》中说：“东坡先生以文章余事作诗，溢而作词曲，高处出神入天，平处尚临镜笑春。”这两种风格似乎都融合在这首词中，它清婉雅丽，深笃超迈，具有一种扣人心弦的艺术魅力。\n此词上阕写暮春景色与伤春情绪，然却作旷达之语。这在一...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253f534825dee9fd6ea", "shortContent": "在词史上，苏轼是豪放派的代表作家。他的词横放杰出，清旷雄奇，“歌之曲终，觉天风海雨逼人”（陆游《跋东坡七夕词后》）。然而这样的作品不多，就数量而言，大都比较婉约。所以南宋王灼在《碧鸡漫志》中说：“东坡先生以文章余事作诗，溢而作词曲，高处出神入天，平处尚临镜笑春。”这两种风格似乎都融合在这首词中，它清婉雅丽，深笃超迈，具有一种扣人心弦的艺术魅力。\n\n此词上阕写暮春景色与伤春情绪，然却作旷达之语。这在...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7ac305cf0801816ca8", "shortContent": "此词朱本、龙本未编年。其后诸家编年有异。曹本云：“细玩此词上片之意境，与本集《满江红》（东武城南）之上片相似。而本词下片之意境，复与本集《蝶恋花》（帘外东风交雨霰）之上片相似。以上二词，俱作于熙宁九年丙辰密州任内。铭颇疑此词亦系在密州所作，志以待考。”薛本、邹王本均据《冷斋夜话》所载王朝云在惠州贬所曾唱此词及苏轼惠州时期的诗文里惯用此词中出现的“天涯”一词而系于绍圣二年（1095）春，作于惠州。陈...", "authors": [], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702e7ccdb86c49f291ef", "shortContent": "这是一首伤春词，所作年份暂无可考，有作于密州、黄州、定州、惠州等多种说法。上阕抒发了伤春之怀，下阕则直透惆怅苦恼之情。全词充满了情与情、情与理相冲突的矛盾心境。\n\n上阕主要描写了暮春的景色。残花凋落使人伤情，但此时杏树上却新长出了小小的充满生气的果实。偶尔有燕子飞过天空，周围的人家都在绿水的环绕之中。枝头上的柳絮被风越吹越少了，但天涯海角都长满了芳草。上阕的感情变化非常鲜明。“花褪残红青杏小”写残...", "authors": ["李诗敏　乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312719c73206168b2e02358", "shortContent": "这是一首伤春词，所作年份暂无可考，有作于密州、黄州、定州、惠州等多种说法。上阕抒发了伤春之怀，下阕则直透惆怅苦恼之情。全词充满了情与情、情与理相冲突的矛盾心境。\n上阕主要描写了暮春的景色。残花凋落使人伤情，但此时杏树上却新长出了小小的充满生气的果实。偶尔有燕子飞过天空，周围的人家都在绿水的环绕之中。枝头上的柳絮被风越吹越少了，但天涯海角都长满了芳草。上阕的感情变化非常鲜明。“花褪残红青杏小”写残花...", "authors": ["李诗敏　乐云"], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646839fc5b7b0d4f451f7144", "shortContent": "在词史上，苏轼是豪放派的代表作家。他的词横放杰出，清旷雄奇，“歌之曲终，觉天风海雨逼人”（陆游《跋东坡七夕词后》）。然而这样的作品不多，就数量而言，大都比较婉约。所以南宋王灼在《碧鸡漫志》中说：“东坡先生以文章余事作诗，溢而作词曲，高处出神入天，平处尚临镜笑春。”这两种风格似乎都融合在这首词中，它清婉雅丽，深笃超迈，具有一种扣人心弦的艺术魅力。\n\n此词上阕写暮春景色与伤春情绪，然却作旷达之语。这在...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}]', '宋·魏菊庄《诗人玉屑》：予得真本于友人处，「绿水人家绕」作「绿水人家晓」。「多情却被无情恼」，盖行人多情，佳人无情耳。此两字极有理趣，而「绕」与「晓」自霄壤也。
明·兪仲茅《爰园词话》：古人好词，即一字未易弹，亦未易改。子瞻「绿水人家绕」，别本「绕」作「晓」，为《古今词话》所赏。愚谓「绕」字虽平，然是实境；「晓」字无皈着，试通咏全章便见。
清·王阮亭《花草蒙拾》：「枝上柳绵」，恐屯田缘情绮靡，未必能过。孰谓坡但解作「大江东去」耶？髯直是轶伦绝群。
清·先著、程洪《词洁》：坡公于有韵之言，多笔走不守之憾。後半手滑，遂不能自由，少一停思，必无此矣。
清·黄苏《蓼园词选》：「绿水人家绕」，非「绕」字，乃曰「人家晓」。「晓」字与「绕」字盖霄壤也。「枝上」一句，断送朝云。一声何满子，竟能使肠断。李龟年正若是耳。「佳人」是「无情」，「行人」是「多情」者。「柳绵」自是佳句，而次阕尤为奇情四溢也。
清·李佳《左菴词话》：此亦寓言，元端致谤之喻。
清·王湘绮《湘绮楼词选》：此则逸思，非文人所宜。
近·兪乐静《唐五代两宋词选释》：絮飞花落，每易伤春，此独作旷达语。下阕墙内外之人，干卿底事，殆偶闻秋千笑语，发此妙想，多情而实无情，色是空，公其有悟耶？', 'indent', 1362601756, '57b316bf165abd00543a405c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10182, '生查子 · 元夕', NULL, 1045, 1229, 3, 5, '欧阳修', NULL, 10018, '57b98d625bbb50005347ace1', '宋', 'ci', '词', 'http://baike.baidu.com/view/167223.htm', '', '去年元夜时，花市灯如昼。月上柳梢头，人约黄昏后。
今年元夜时，月与灯依旧。不见去年人，泪满春衫袖。​', '这是首相思词，写去年与情人相会的甜蜜与今日不见情人的痛苦，明白如话，饶有韵味。词的上阕写「去年元夜」的事情，花市的灯像白天一样亮，不但是观灯赏月的好时节，也给恋爱的青年男女以良好的时机，在灯火阑珊处秘密相会。「月到柳梢头，人约黄昏后」二句言有尽而意无穷，柔情密意溢于言表。下阕写「今年元夜」的情景。「月与灯依旧」，虽然只举月与灯，实际应包括二三句的花和柳，是说闹市佳节良宵与去年一样，景物依旧。下一句「不见去年人」、「泪满春衫袖」，表情极明显，一个「满」字，将物是人非，旧情难续的感伤表现得淋漓尽致。', '此词作者一说为朱淑真。
元夜：元宵之夜。农历正月十五为元宵节。自唐朝起有观灯闹夜的民间风俗。北宋时从十四到十六三天，开宵禁，游灯街花市，通宵歌舞，盛况空前，也是年轻人蜜约幽会，谈情说爱的好机会。
花市：民俗每年春时举行的卖花、赏花的集市。
灯如昼：灯火像白天一样。据宋代孟元老《东京梦华录·卷六·元宵》载：「正月十五日元宵，……灯山上彩，金碧相射，锦绣交辉。」由此可见当时元宵节的繁华景象。
月上：一作「月到」。“月到”从《欧阳文忠集·巻一百三十一·〈近体乐府·生查子〉》。
见：看见。
泪满：朱竹垞《词综》作「泪湿」。兹从《欧阳文忠集·卷一百三十一·〈近体乐府·生查子〉》。
春衫：年少时穿的衣服，也指代年轻时的自己。', '去年正月十五元宵节，花市灯光像白天一样雪亮。月儿升起在柳树梢头，他约我黄昏以後同叙衷肠。
今年正月十五元宵节，月光与灯光同去年一样。再也看不到去年的情人，泪珠儿不觉湿透衣裳。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74a62cee9a0c24ec7c5a", "shortContent": "此词作者，或作朱淑真，或作秦观。但南宋初曾慥所编《乐府雅词》作欧阳修，当较为可信。词作通过主人公对去年今日的往事回忆，写物是人非之感，其语言通俗可谓到口即消，其内容情事几乎一目了然，但构思巧妙，饶有新意，这集中表现在词的分片上。\n词的上片写“去年元夜”情事。“元夜”今称元宵节，自唐时起即有观灯闹夜的风俗：“谁家见月能闲坐？何处闻灯不看来？”（崔液《上元夜》）“火树银花合，星桥铁锁开”，“金吾不禁夜...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ad5e272d4b2254df6d", "shortContent": "此词作者，或作朱淑真，或作秦观。但南宋初曾慥所编《乐府雅词》作欧阳修，当较为可信。词作通过主人公对去年今日的往事回忆，写物是人非之感，其语言通俗可谓到口即消，其内容情事几乎一目了然，但构思巧妙，饶有新意，这集中表现在词的分片上。\n词的上片写“去年元夜”情事。“元夜”今称元宵节，自唐时起即有观灯闹夜的风俗：“谁家见月能闲坐？何处闻灯不看来？”（崔液《上元夜》），“火树银花合，星桥铁锁开”，“金吾不禁...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592534b56e213e6848027", "shortContent": "此词作者，或作朱淑真，或作秦观。但南宋初曾慥所编《乐府雅词》作欧阳修，当较为可信。词作通过主人公对去年今日的往事回忆，写物是人非之感，其语言通俗可谓到口即消，其内容情事几乎一目了然，但构思巧妙，饶有新意，这集中表现在词的分片上。\n\n词的上片写“去年元夜”情事。“元夜”今称元宵节，自唐时起即有观灯闹夜的风俗：“谁家见月能闲坐？何处闻灯不看来？”（崔液《上元夜》）“火树银花合，星桥铁锁开”，“金吾不禁...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "6277f84f8efdff05d7d6839b", "bookTitle": "李清照全集", "articleId": "6312258bc26cbf3417f014ae", "shortContent": "此首为欧阳修词，见《欧阳文忠公近体乐府》卷一。《词的》卷一误作李清照词。", "authors": [], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fefc305cf0801816e62", "shortContent": "有人认为这首词是女词人朱淑真的作品，故其词集《断肠集》中有收录，而她也因这首词招致了怨怼，王士禛《池北偶谈》载：“世遂因此词，疑淑真失妇德。”但清况周颐已经明确这首词为欧阳修之作。他说：“‘生查子’词，今载《庐陵集》第一百三十一卷。宋曾慥《乐府雅词》、明陈耀文《花草粹编》并作永叔。慥录欧词特慎，《雅词》序云：‘当时或作艳曲，谬为公词，今悉删除。’此阕适在选中，其为欧词甚明。”（《蕙风词话》）北宋初...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312718cc26cbf3417f0957c", "shortContent": "有人认为这首词是女词人朱淑真的作品，故其词集《断肠集》中有收录，而她也因这首词招致了怨怼，王士祯《池北偶谈》载：“世遂因此词，疑淑真失妇德。”但清况周颐已经明确辩为这首词为欧阳修之作。他说：“‘生查子’词，今载《庐陵集》第一百三十一卷。宋曾慥《乐府雅词》、明陈耀文《花草粹编》并作永叔。慥录欧词特慎，《雅词》序云‘当时或作艳曲，谬为公词，今悉删除。’此阕适在选中，其为欧词甚明。”（《蕙风词话》）北宋...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "646a05a345e4710056dab21f", "bookTitle": "欧阳修诗文鉴赏辞典（珍藏本）", "articleId": "646c7f3e7da2f75ac708a0ba", "shortContent": "此词作者，或作朱淑真，或作秦观。但南宋初曾慥所编《乐府雅词》作欧阳修，当较为可信。词作通过主人公对去年今日的往事回忆，写物是人非之感，其语言通俗可谓到口即消，其内容情事几乎一目了然，但构思巧妙，饶有新意，这集中表现在词的分片上。\n词的上片写“去年元夜”情事。“元夜”今称元宵节，自唐时起即有观灯闹夜的风俗：“谁家见月能闲坐？何处闻灯不看来？”（崔液《上元夜》）“火树银花合，星桥铁锁开”，“金吾不禁夜...", "authors": ["周啸天"], "pressName": "崇文书局"}]', '徐野君《古今词统》：元曲之称绝者，不过得此法。
王阮亭《池北偶谈》：今世所传女郎朱淑真「去年元夜时，灯市花如昼」（《生查子》词），见《欧阳文忠公集》一百三十一卷，不知何以讹为朱氏之作。世遂因此词，疑淑真失妇德，纪载不可不慎也。
陆敬安《冷庐杂识》：「去年元夜」一词，本欧阳公作。后人误编入《断肠集》（渔洋山人亦辨之），遂疑朱淑真为泆女，皆不可不辨。按『去年元夜』词，非朱淑真作，信矣。', 'indent', 1362601863, '57b8e8f3128fe10054c8ff14', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10183, '题菊花', NULL, 255, 3, 1, 3, '黄巢', NULL, 10050, '57b9040d0a2b58005c9257b2', '唐', 'shi', '诗', 'http://baike.baidu.com/view/635548.htm', '', '飒飒西风满院栽，蕊寒香冷蝶难来。
他年我若为青帝，报与桃花一处开。', '《题菊花》是唐末农民起义领袖黄巢创作的一首诗，载于《全唐诗》卷七百三十三。此诗采用比兴手法，托物言志，抒发了作者力图主宰社会的豪迈思想。其不同凡响之处在于它展开了充满浪漫主义激情的大胆想象：一旦自己成为青帝（春神）就要让菊花与桃花在大好春光中开放，让菊花也同样享受到蕊暖香浓蜂蝶绕丛的欢乐。这种对不公正“天道”的大胆否定和对理想中的美好世界的热烈憧憬，集中地反映出诗人超越封建文人价值观念的远见卓识和勇于掌握、改变自身命运的雄伟胆略。', '飒飒：形容风声。
蕊：花心儿。
青帝：司春之神。古代传说中的五天帝之一，住在东方，主行春天时令。
报：告诉，告知，这里有命令的意思。', '飒飒秋风卷地而来，满园菊花瑟瑟飘摇。花蕊花香充满寒意，蝴蝶蜜蜂难以到来。有朝一日，我要当了春神，我将安排菊花和桃花同在春天盛开。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92e703572034f659e643", "shortContent": "唐末诗人林宽有这样两句诗：“莫言马上得天下，自古英雄皆解诗。”（《歌风台》）古往今来，确有不少能“解诗”的英雄，唐末农民起义领袖黄巢就是其中突出的一个。自从东晋陶渊明“采菊东篱下，悠然见南山”（《饮酒二十首》其五）的名句一出，菊花就和孤标傲世的高士、隐者结下了不解之缘，几乎成了封建文人孤高绝俗精神的一种象征。黄巢的菊花诗，却完全脱出了同类作品的窠臼，表现出全新的思想境界和艺术风格。\n第一句写满院菊...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707ce6f69b71e93f62f2", "shortContent": "黄巢有两首题咏菊花的诗，都写得非常好，这是其中的一首。全诗通过描写迎寒怒放的菊花，表达了诗人对它们的赞美之情与不平之意，并由此抒发了诗人自己的怀抱。\n\n“飒飒西风满院栽，蕊寒香冷蝶难来”两句，首先描写菊花不畏风霜、独自开放的情景。在瑟瑟秋风的吹拂下，万木凋零、百花凋谢，唯独这满院的菊花仍傲然挺立、含苞怒放。它们虽然只散发幽微的芳香，比不上春天百花的浓艳，但是却始终迎风屹立、临寒盛开，表现出顽强的生...", "authors": ["余春丽"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127156c9ebcc6fbea1a4af", "shortContent": "黄巢有两首题咏菊花的诗，都写得非常好，这是其中的一首。全诗通过描写迎寒怒放的菊花，表达了诗人对它们的赞美之情与不平之意，并由此抒发了诗人自己的怀抱。\n“飒飒西风满院栽，蕊寒香冷蝶难来”两句，首先描写菊花不畏风霜、独自开放的情景。在瑟瑟秋风的吹拂下，万木凋零、百花凋谢，唯独这满院的菊花仍傲然挺立、含苞怒放。它们虽然只散发幽微的芳香，比不上春天百花的浓艳，但是却始终迎风屹立、临寒盛开，表现出顽强的生命...", "authors": ["余春丽"], "pressName": "崇文书局"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472b7c530675327e1c31176", "shortContent": "唐末诗人林宽有这样两句诗：“莫言马上得天下，自古英雄皆解诗。”古往今来，确有不少能“解诗”的英雄，唐末农民起义领袖黄巢就是其中突出的一个。自从陶渊明“采菊东篱下，悠然见南山”的名句一出，菊花就和孤标傲世的高士、隐者结下了不解之缘，几乎成了一些文人孤高绝俗精神的一种象征。黄巢的菊花诗，却完全脱出了同类作品的窠臼，表现出全新的思想境界和艺术风格。\n\n第一句写满院菊花在飒飒秋风中开放。“西风”点明节令，...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472b825a5f1e74f9589d058", "shortContent": "这首诗的题目，《全唐诗》作“不第后赋菊”，大概是根据明代郎瑛《七修类稿》引《清暇录》关于此诗的记载。但《清暇录》只说此诗是黄巢落第后所作，题为“菊花”。\n\n重阳节有赏菊的风俗，相沿既久，这一天也无形中成了菊花节。这首菊花诗，其实并非泛咏菊花，而是遥庆菊花节。因此一开头就是“待到秋来九月八”，意即等到菊花节那一天。不说“九月九”而说“九月八”，是为了与“杀”、“甲”叶韵。这首诗押入声韵，作者要借此造...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '张端义《贵耳集》：跋扈之意，已见婴孩之时。加以数年，岂不为神器之大盗耶！', 'center', 1362602405, '57b904102e958a005fa5643e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10190, '闺怨', NULL, 191, 202, 1, 2, '王昌龄', NULL, 10051, '57b91963128fe10054ca5788', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/155120/8050209.htm', '', '闺中少妇不知愁，春日凝妆上翠楼。
忽见陌头杨柳色，悔教夫婿觅封侯。', '这是唐代诗人王昌龄描写上流贵妇赏春时心理变化的一首闺怨诗。唐代前期，国力强盛。从军远征，立功边塞，成为人们“觅封侯”的重要途径。诗中的“闺中少妇”和她的丈夫对这一道路也同样充满了幻想。
诗的首句，与题意相反，写她“不知愁”：天真浪漫，富有幻想；二句写她登楼赏春：带有幼稚无知，成熟稍晚的憨态；三句急转，写忽见柳色而勾起情思：柳树又绿，夫君未归，时光流逝，春情易失；四句写她的省悟：悔恨当初怂恿“夫婿觅封侯”的过错。诗无刻意写怨愁，但怨之深，愁之重，已裸露无余。
从诗作主旨看，此诗深刻地描画了少妇微妙的心理变化轨迹。诗也抓住天真烂漫的少妇于登楼眺览春光时，顷刻间的感情波澜，表现了世俗荣华不如朝夕相爱的思想。全诗先抑后扬，耐人寻味。', '闺怨：少妇的幽怨。闺，女子卧室，借指女子。一般指少女或少妇。古人“闺怨”之作，一般是写少女的青春寂寞，或少妇的离别相思之情。以此题材写的诗称“闺怨诗”。
不知愁：刘永济《唐人绝句精华》注：“不曾”一本作“不知”。作“不曾”与凝妆上楼，忽见春光，顿觉孤寂，因而引起懊悔之意，相贯而有力。
凝妆：盛妆，严妆。
翠楼：翠楼即青楼，古代显贵之家楼房多饰青色，这里因平仄要求用“翠”，且与女主人公的身份、与时令季节相应。
陌头：路边。
柳：谐留音，古俗折柳送别。
悔教：后悔让
觅封侯：觅，寻求。从军建功封爵。', '闺中少妇未曾有过相思离别之愁，在明媚的春日，她精心妆饰，登上高楼。忽然看到路边的杨柳春色，惆怅之情涌上心头。她后悔当初不该让丈夫从军边塞，建功封侯。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9294d635634aee3deb1b", "shortContent": "王昌龄善于用七绝细腻而含蓄地描写宫闺女子的心理状态及其微妙变化。这首《闺怨》和《长信秋词》等宫怨诗，都是素负盛誉之作。\n题称“闺怨”，一开头却说“闺中少妇不曾愁”，似乎故意违反题面。其实，作者这样写，正是为了表现这位闺中少妇从“不曾愁”到“悔”的心理变化过程。丈夫从军远征，离别经年，照说应该有愁。之所以“不曾愁”，除了这位女主人公正当青春年少，还没有经历多少生活波折，和家境比较优裕（从下句“凝妆上...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d103", "shortContent": "王昌龄善于用七绝细腻而含蓄地描写宫闺女子的心理状态及其微妙变化。这首《闺怨》和《长信秋词》等宫怨诗，都是素负盛誉之作。\n\n题称“闺怨”，一开头却说“闺中少妇不曾愁”，似乎故意违反题面。其实，作者这样写，正是为了表现这位闺中少妇从“不曾愁”到“悔”的心理变化过程。丈夫从军远征，离别经年，照说应该有愁。之所以“不曾愁”，除了这位女主人公正当青春年少，还没有经历多少生活波折，和家境比较优裕（从下句“凝妆...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f459761253910e903b1", "shortContent": "一个贵家少妇，因为丈夫出了远门，在家中无所事事。于是在一个风和日丽的日子里，打扮得漂漂亮亮的，走上高楼，向远处眺望，欣赏初春的美景。这是一个充满闲情逸致的日子，贵家少妇本不知愁，生活无忧，闲庭信步，心情轻松而愉悦，所以很有心情打扮。“忽见”二句转得极为突然，却在情理之中，将少妇急转突变的微妙心理描述得真切而自然。\n\n站在高楼之上，看到陌头已经一片杨柳青青。欣欣向荣、万物复苏的景象在唤醒生命的热情与...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312703bf2af4e09d55b672d", "shortContent": "一个贵家少妇，因为丈夫出了远门，在家中无所事事，于是在一个风和日丽的日子里，打扮得漂漂亮亮的，走上高楼，向远处眺望，欣赏初春的美景。这是一个充满闲情逸致的日子，贵家少妇本不知愁，生活无忧，闲庭信步，心情轻松而愉悦，所以很有心情打扮。“忽见”二句转得极为突然，却在情理之中，将少妇急转突变的微妙心理描述得真切而自然。\n\n站在高楼之上，看到陌头已经一片杨柳青青。欣欣向荣、万物复苏的景象在唤醒生命的热情与...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312706ac305cf0801816fe9", "shortContent": "一个贵家少妇，因为丈夫出了远门，在家中无所事事，于是在一个风和日丽的日子里，打扮得漂漂亮亮的，走上高楼，向远处眺望，欣赏初春的美景。这是一个充满闲情逸致的日子，贵家少妇本不知愁，生活无忧，闲庭信步，心情轻松而愉悦，所以很有心情打扮。“忽见”二句转得极为突然，却在情理之中，将少妇急转突变的微妙心理描述得真切而自然。\n站在高楼之上，看到陌头已经一片杨柳青青。欣欣向荣、万物复苏的景象在唤醒生命的热情与憧...", "authors": ["张春晓"], "pressName": "崇文书局"}]', '', 'center', 1417651524, '57b9b4480a2b58006cafe88c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10184, '不第后赋菊', NULL, 421, 3, 2, 2, '黄巢', NULL, 10050, '57b9040d0a2b58005c9257b2', '唐', 'shi', '诗', 'http://baike.baidu.com/view/342512.htm', '', '待到秋来九月八，我花开后百花杀。
冲天香阵透长安，满城尽带黄金甲。', '《不第后赋菊》是唐末农民起义领袖黄巢所作的咏物诗。此诗运用比喻的手法，赋予菊花以英雄风貌与高洁品格，把菊花作为广大被压迫人民的象征，以百花喻指反动腐朽的封建统治集团，形象地显示了农民革命领袖果决坚定的精神风貌。全诗辞采壮伟，设喻新颖，想象奇特，意境瑰丽，气魄雄伟。', '不第：科举落第。
九月八：九月九日为重阳节，有登高赏菊的风俗，说“九月八”是为了押韵。
杀：草木枯萎。《吕氏春秋·应同》：“及禹之时，天先见草木秋冬不杀。”
黄金甲：指金黄色铠甲般的菊花。', '等到秋天九月重阳节来临的时候，菊花盛开以后别的花就凋零了。盛开的菊花璀璨夺目，阵阵香气弥漫长安，满城均沐浴在芳香的菊意中，遍地都是金黄如铠甲般的菊花。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92e803572034f659e645", "shortContent": "这首诗的题目，《全唐诗》作“不第后赋菊”，大概是根据明代郎瑛《七修类稿》引《清暇录》关于此诗的记载。但《清暇录》只说此诗是黄巢落第后所作，题为“菊花”。\n重阳节有赏菊的风俗，相沿既久，这一天也无形中成了菊花节。这首菊花诗，其实并非泛咏菊花，而是遥庆菊花节。因此一开头就是“待到秋来九月八”，意即等到菊花节那一天。不说“九月九”而说“九月八”，是为了与“杀”、“甲”叶韵。这首诗押入声韵，作者要借此造成...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '郎瑛：《清暇录》载：黄巢下第，有《菊花》诗曰：“待到秋来九月八，我花开后百花杀。冲天香阵透长安，满城尽带黄金甲。”尝闻我（朱）太祖亦有咏《菊花》诗：“百花发，我不发；我若发，都骇杀。要与西风战一场，遍身穿就黄金甲。”人看二诗，彼此一意：成则为明，而败则为黄也。', 'center', 1362602463, '57b9041379bc44005b9eb808', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10185, '出塞', NULL, 2599, 202, 2, 12, '王昌龄', NULL, 10051, '57b91963128fe10054ca5788', '唐', 'shi', '诗', 'http://baike.baidu.com/view/722526.htm', '', '秦时明月汉时关，万里长征人未还。
但使龙城飞将在，不教胡马度阴山。', '此诗是王龙标早年赴西域时所做，《出塞》是乐府旧题。王龙标所处的时代，正值盛唐，这一时期，唐在对外战争中屡屡取胜，全民族的自信心极强，边塞诗人的作品中，多能体现一种慷慨激昂的向上精神，和克敌制胜的强烈自信。同时，频繁的边塞战争，也使人民不堪重负，渴望和平，《出塞》正是反映了人民的这种和平愿望。
此诗以平凡的语言，唱出雄浑豁达的主旨，气势流畅，一气呵成。诗人以雄劲的笔触，对当时的边塞战争生活作了高度的艺术概括，把写景、叙事、抒情与议论紧密结合，在诗里熔铸了丰富复杂的思想感情，使诗的意境雄浑深远，既激动人心，又耐人寻味。对《出塞》的评价历来很高。明代诗人李攀龙甚至推奖它是唐人七绝的压卷之作，杨慎编选唐人绝句，也列它为第一。', '龙城飞将：《汉书·卫青霍去病传》载，元光六年（公元前129年），卫青为车骑将军，出上谷，至笼城，斩首虏数百。笼城，颜师古注曰：“笼”与“龙”同。龙城飞将谓卫青奇袭龙城之事，或谓龙城飞将为汉飞将军李广。龙城即唐卢龙城，为汉李广练兵之地，属汉右北平郡，在今河北省喜峰口附近）。纵观李广平生抗击匈奴，防止匈奴掠边，其中每次匈奴重点进攻的汉天子几乎都是派遣李广为太守，所以这种说法也不无道理。
胡马：指侵扰内地的外族骑兵。
阴山：昆仑山的北支，起自河套西北，横贯绥远、察哈尔及热河北部，是中国北方的屏障。', '依旧是秦汉时期的明月和边关，守边禦敌鏖战万里征人未回还。
倘若龙城的飞将李广如今还在，绝不许匈奴南下牧马度过阴山。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92935914587d02f4e444", "shortContent": "这是一首名作，明代诗人李攀龙曾经推奖它是唐人七绝的压卷之作。清沈德潜《说诗晬语》说：“‘秦时明月’一章，前人推奖之而未言其妙，盖言师劳力竭，而功不成，由将非其人之故；得飞将军备边，边烽自熄，即高常侍《燕歌行》归重‘至今人说李将军’也。防边筑城，起于秦汉，明月属秦，关属汉，诗中互文。”他这段话批评李攀龙只知推奖此诗而未言其妙，可是他自己也只是说明了全诗的主旨，并没有点出作者的匠心。\n沈氏归纳的全诗的...", "authors": ["廖仲安"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d101", "shortContent": "这是一首名作，明代诗人李攀龙曾经推奖它是唐人七绝的压卷之作。清沈德潜《说诗晬语》说：“‘秦时明月’一章，前人推奖之而未言其妙，盖言师劳力竭，而功不成，由将非其人之故；得飞将军备边，边烽自熄，即高常侍《燕歌行》归重‘至今人说李将军’也。防边筑城，起于秦汉，明月属秦，关属汉，诗中互文。”他这段话批评李攀龙只知推奖此诗而未言其妙，可是他自己也只是说明了全诗的主旨，并没有点出作者的匠心。\n\n沈氏归纳的全诗...", "authors": ["廖仲安"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4e7ccdb86c49f29105", "shortContent": "这首诗以其卓越的时空感和普遍认同的情感成为古诗中脍炙人口的名篇。\n\n前两句极写自古以来征战的士兵总是卫戍边疆不得归家的现实。秦汉时为防御匈奴，在北方修筑长城，大量戍卒被征发来戍守长城。“秦时明月汉时关”，是互文见义之法，并非单指秦时的明月、汉时的关塞，而是合指秦汉的明月、秦汉的关塞。秦汉时代开始，已经是征人难还，时至唐代，仍然面临同样的问题。“万里”，点出地域的广阔、边塞的苍茫，既是写征人离家之远...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312703bf2af4e09d55b672a", "shortContent": "这首诗以其卓越的时空感和情感的普遍认同成为古诗中脍炙人口的作品。\n\n前二句以互文见义之法，极写自古以来征战的士兵总是卫戍边疆不得归家的现实。建筑边塞防备胡人，始于秦汉时代。“秦时明月汉时关”，是互文见义之法，并非单指秦时的明月，汉时的关塞，而是合指秦汉的明月、秦汉的关塞。秦汉时代开始，已经是征人难还，时至唐代，仍然面临同样的问题。“万里”，点出地域的广阔、边塞的苍茫，既是写征人离家之远，其所代表的...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312706ac305cf0801816fe8", "shortContent": "这首诗以其卓越的时空感和情感的普遍认同成为古诗中脍炙人口的作品。\n前二句以互文见义之法，极写自古以来征战的士兵总是卫戍边疆不得归家的现实。建筑边塞防备胡人，始于秦汉时代。“秦时明月汉时关”，是互文见义之法，并非单指秦时的明月，汉时的关塞，而是合指秦汉的明月、秦汉的关塞。秦汉时代开始，已经是征人难还，时至唐代，仍然面临同样的问题。“万里”，点出地域的广阔、边塞的苍茫，既是写征人离家之远，其所代表的空...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f0af47da2f75ac713988c", "shortContent": "这首诗里，有一句最美最耐人寻味的诗句，即开头第一句：“秦时明月汉时关。”这句诗有什么妙处呢？得从诗题说起。此诗题名《出塞》，一望而知是一首乐府诗。乐府诗是要谱成乐章广泛传唱的，为入谱传唱的需要，诗中就往往有一些常见习用的词语。王昌龄这首诗也不例外。你看这开头一句中的“明月”和“关”两个词，正是有关边塞的乐府诗里很常见的词语。《乐府诗集·横吹曲辞》里不是就有《关山月》吗？《乐府解题》说：“关山月，伤...", "authors": ["廖仲安"], "pressName": "上海辞书出版社"}]', '《升菴诗话》：此诗可入神品。「秦时明月」四字，横空盘硬语也。人所难解。李中溪侍御尝问余，余曰：扬子云赋，欃枪为闉，明月为堠。此诗借用其字，而用意深矣。盖言秦时虽远征而未设关，但在明月之地，犹有行役不逾时之意；汉则设关而戍守之，征人无有还期矣，所赖飞将御边而已。虽然，亦异乎守在四夷之世矣。
《批点唐音》：惨淡可伤。音律虽柔。终是盛唐骨格。
《唐诗绝句类选》：「秦时明月」一首，用修、于鳞谓为唐绝第一，愚谓王之涣《凉州词》神骨声调当为伯仲，青莲「洞庭西望」气概相敌。第李诗作于沦落，其气沉郁；少伯代边帅自负语，其神气飘爽耳。
《唐诗直解》：惨淡可伤。结句出人意表，盛唐气骨。
王世贞《艺苑卮言》：于鳞言唐人绝句当以此压卷，余始不信，以少伯集中有极工妙才。既而思之：若落意解、当别有所取；若以有意无意、可解不可解间求之，不免此诗第一耳。
《艺圃撷馀》：于鳞选唐七言绝句，取王龙标「秦时明月汉时关」为第一，以语人，多不服。于鳞意止击节「秦时明月」四字耳。必欲压卷，还当于王翰「葡萄美酒」、王之涣「黄河远上」二诗求之。
《诗薮》：「秦时明月」在少伯自为常调，用修以诸家不选，故《唐绝增奇》首录之。所谓前人遗珠，兹则掇拾。于鳞不察而和之，非定论也。
《唐音癸签》：王少伯七绝宫同闺怨，尽多诣极之作，若边同「秦时明月」一绝，发端句虽奇，而后劲尚属中驷，于鳞遽取压卷，尚须商榷。
《唐诗摘钞》：中晚唐绝句涉议论便不佳、此诗亦涉议论，而未尝不佳。此何以故？风度胜故，气味胜故。
《此木轩论诗汇编》：好在第二句，「秦时明月汉时关」不可通。「但使龙城飞将在，不教胡马渡阴山」，令人起长城之叹。诗人之词凡百，皆不忍尽、不敢尽、只有此一节尤不尽者，此《春秋》继诗之旨也。如不信者、试遍觅唐人诗读之。
《说诗晬语》：「秦时明月」一章，前人推奖之而未言其妙，盖言师劳力竭而功不成，由将非其人之故，得飞将军备边，边烽自熄，即高常侍《燕歌行》归重「至今人说李将军」也，边防築城，起于秦汉；明月属秦，关属汉，诗中互文。
《网师园唐诗笺》：悲壮浑成，应推绝唱。
《岘佣说诗》：「秦时明月」一首，「黄河远上」一首，「天山雪后」一首，皆边塞名作，意态雄健，音节高亮，情思悱恻，令人百读不厌也。', 'center', 1413197842, '57b8b1f7c4c97100558e0d45', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10186, '从军行', NULL, 1121, 202, 5, 15, '王昌龄', NULL, 10051, '57b91963128fe10054ca5788', '唐', 'shi', '诗', 'http://baike.baidu.com/view/1259570.htm', '', '【其一】
烽火城西百尺楼，黄昏独上海风秋。
更吹羌笛关山月，无那金闺万里愁。
【其二】
琵琶起舞换新声，总是关山旧别情。
撩乱边愁听不尽，高高秋月照长城。
【其三】
关城榆叶早疏黄，日暮云沙古战场。
表请回军掩尘骨，莫教兵士哭龙荒。
【其四】
青海长云暗雪山，孤城遥望玉门关。
黄沙百战穿金甲，不破楼兰终不还。
【其五】
大漠风尘日色昏，红旗半卷出辕门。
前军夜战洮河北，已报生擒吐谷浑。
【其六】
胡瓶落膊紫薄汗，碎叶城西秋月团。
明敕星驰封宝剑，辞君一夜取楼兰。
【其七】
玉门山嶂几千重，山北山南总是烽。
人依远戍须看火，马踏深山不见踪。', '《从军行七首》是王昌龄采用乐府旧题写的一组边塞诗，载于《全唐诗》卷一百四十三。
盛唐优秀边塞诗的一个重要的思想特色，就是在抒写戍边将士的豪情壮志的同时，并不回避战争的艰苦。典型环境与人物感情高度统一，是王昌龄绝句的一个突出优点，这在此篇中也有明显的体现。', '从军行：乐府旧题，属相和歌辞平调曲，多是反映军旅辛苦生活的。
羌笛：羌族竹制乐器。
关山月：乐府曲名，属横吹曲。多为伤离别之辞。
独上：一作“独坐”。
无那：无奈，指无法消除思亲之愁。一作“谁解”。
新声：新的歌曲。
关山：边塞。
旧别：一作“离别”。
撩乱：心里烦乱。
边愁：久住边疆的愁苦。
听不尽：一作“弹不尽”。
关城：指边关的守城。
云沙：像云一样的风沙。
表：上表，上书。
掩尘骨：指尸骨安葬。掩，埋。
龙荒：荒原。
青海：指青海湖，在今青海省。唐朝大将哥舒翰筑城于此，置神威军戍守。
长云：层层浓云。
雪山：即祁连山，山巅终年积雪，故云。
孤城：即玉门关。
玉门关：汉置边关名，在今甘肃敦煌西。一作“雁门关”。
破：一作“斩”。
楼兰：汉时西域国名，即鄯善国，在今新疆维吾尔自治区鄯善县东南一带。西汉时楼兰国王与匈奴勾通，屡次杀害汉朝通西域的使臣。此处泛指唐西北地区常常侵扰边境的少数民族政权。
终不还：一作“竟不还”。
前军：指唐军的先头部队。
洮河：河名，源出甘肃临洮西北的西倾山，最后流入黄河。
吐谷浑：中国古代少数民族名称，晋时鲜卑慕容氏的后裔。据《新唐书·西域传》记载：“吐谷浑居甘松山之阳，洮水之西，南抵白兰，地数千里。”唐高宗时吐谷浑曾经被唐朝与吐蕃的联军所击败。
胡瓶：唐代西域地区制作的一种工艺品，可用来储水。
敕：专指皇帝的诏书。
星驰：像流星一样迅疾奔驰，也可解释为星夜奔驰。
嶂：指直立像屏障一样的山峰。
烽：指烽火台。', '【其一】
在烽火台的西边高高地耸着一座戍楼，黄昏时分，独坐在戍楼上任凭从湖面吹来的秋风撩起自己的战袍。
此时又传来一阵幽怨的羌笛声，吹奏的是《关山月》的调子，无奈着笛声更增添了对万里之外的妻子的相思之情。
【其二】
军中起舞，伴奏的琵琶翻出新声，不管怎样翻新，每每听到《关山月》的曲调时，总会激起边关将士久别怀乡的忧伤之情。
纷杂的乐舞与思乡的愁绪交织在一起，欲理还乱，无尽无休。此时秋天的月亮高高地照着长城。
【其三】
边城榆树的叶子早已稀疏飘落，颜色发黄了，傍晚时分，一场战斗刚刚结束，环视战场，只见暮云低合，荒丘起伏。
将军向皇帝上表，奏请班师，以便能把战死沙场的将士们的尸骨运回故土安葬，不能让士兵们为他乡埋葬自己的战友而伤感痛哭。
【其四】
青海湖上乌云密布，连绵雪山一片黯淡。边塞古城，玉门雄关，远隔千里，遥遥相望。
守边将士，身经百战，铠甲磨穿，壮志不灭，不打败进犯之敌，誓不返回家乡。
【其五】
塞北沙漠中大风狂起，尘土飞扬，天色为之昏暗，前线军情十分紧急，接到战报后迅速出击。
先头部队已经于昨天夜间在洮河的北岸和敌人展开了激战，刚刚听说与敌人交火，现在就传来了已获得大捷的消息。
【其六】
将军臂膊上绑缚着胡瓶，骑着紫薄汗马，英姿飒爽；碎叶城西的天空中一轮秋月高高悬挂。
边境传来紧急军情，皇上派使者星夜传诏将军，并赐予尚方宝剑令其即刻领兵奔赴前线杀敌；将军拜诏辞京，奔赴战场，将士用命，一鼓作气，很快就攻破了敌人的老巢。
【其七】
玉门关周围山峦层层叠叠，像重重屏障护卫着王朝的西北边防；烽火台遍布各个山头。
人们戍边要依靠烽火来传递消息；那里山深林密，马儿跑过一会儿就看不见踪影了。', '[{"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0ff", "shortContent": "读唐代边塞诗，往往因为诗中所涉及的地名古今杂举、空间悬隔而感到困惑。怀疑作者不谙地理，因而不求甚解者有之，曲为之解者亦有之。这首诗就有这种情形。\n\n前两句提到三个地名。雪山即河西走廊南面横亘延伸的祁连山脉。青海与玉关东西相距数千里，却同在一幅画面上出现，于是对这两句就有种种不同的解说。有的说，上句是向前极目，下句是回望故乡。这很奇怪。青海、雪山在前，玉关在后，则抒情主人公回望的故乡该是玉门关西的西...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d100", "shortContent": "读过《三国演义》的人，可能对第五回“关云长温酒斩华雄”有深刻印象。这对塑造关羽英雄形象是很精彩的一节。但书中并没有正面描写单刀匹马的关羽与领兵五万的华雄如何正面交手，而是用了这样一段文字：\n\n（关羽）出帐提刀，飞身上马。众诸侯听得关外鼓声大振，喊声大举，如天摧地塌，岳撼山崩，众皆失惊。正欲探听，鸾铃响处，马到中军，云长提华雄之头，掷于地上，其酒尚温。\n\n这段文字，笔墨非常简练，从当时的气氛和诸侯的...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312703bf2af4e09d55b6729", "shortContent": "【其一】\n烽火城西，点明这段情境发生的背景和地点。烽火，表示战事正在进行，诗中所有的情感都源于战争中人们的离别和彼此的牵念。烽火，是现实的背景，更是人心复杂情绪的来由。古来向有登楼思乡的传统，诗中人不仅在楼上，更在百尺高楼上。楼越高，人越显得渺小，人之渺小，越衬出在命运面前的无能为力，面对离别的无所作为；楼越高，风越大，人之凄楚无助之感愈重；楼越高，视野越开阔，人心越渴望远眺到家乡，而无论楼有多高...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312706ac305cf0801816fe7", "shortContent": "其一\n烽火城西，点明这段情境发生的背景和地点。烽火，表示战事正在进行，诗中所有的情感都源于战争中人们的离别和彼此的牵念。烽火，是现实的背景，更是人心复杂情绪的来由。古来向有登楼思乡的传统，诗中人不仅在楼上，更在百尺高楼上。楼越高，人越显得渺小，越衬出在命运面前的无能为力，面对离别的无所作为；楼越高，风越大，人之凄楚无助之感愈重；楼越高，视野越开阔，人心越渴望远眺到家乡，而无论楼有多高，家乡总是在云...", "authors": ["张春晓"], "pressName": "崇文书局"}]', '沈德潜《唐诗别裁》：“不破楼兰终不还”句，“作豪语看亦可，然作归期无日看，倍有意味。
刘永济《唐人绝句精华》：用一“终”字，而使人读之凄然。盖‘终不还’者，终不得还也，连上句金甲着穿观之，久戍之苦益明，如以为思破敌立功而归，则非诗人本意矣。', 'center', 1413197605, '57b8f482128fe10054c9395d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10187, '有美堂暴雨', NULL, 13, 3406, 2, 0, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'shi', '诗', 'http://baike.baidu.com/view/863540.htm', '', '游人脚底一声雷，满座顽云拨不开。
天外黑风吹海立，浙东飞雨过江来。
十分潋滟金樽凸，千杖敲铿羯鼓催。
唤起谪仙泉洒面，倒倾鲛室泻琼瑰。', '此诗生动地展现暴雨由远而近、横跨大江、呼啸奔来的壮观景象。首联非常特征地写出了雨前一刹那的气氛，在拨不开的浓云堆积低空的时候，一声炸雷从云中钻出来了，预示暴雨即将来临。颔联三句是想象，四句是亲见。颈联二句具体写暴雨，西湖比作小小的金樽，把急雨比作羯鼓声。尾联写观感，突发奇想，联想到李白故事。诗如写生画家即兴挥毫，临摹自然实景，展现大自然的壮丽雄伟之景。', '有美堂：嘉祐二年（1057年），梅挚出知杭州，仁宗皇帝亲自赋诗送行，中有“地有吴山美，东南第一州”之句。梅到杭州后，就在吴山顶上建有美堂以见荣宠。
顽云：犹浓云。
潋滟（liàn yàn）：水波相连貌。凸：高出。
敲铿（kēng）：啄木鸟啄木声，这里借指打鼓声。羯（音竭）鼓：羯族传入的一种鼓。
谪仙：被贬谪下凡的仙人，指李白。贺知章曾赞美他为谪仙人。唐玄宗曾谱新曲，召李白作词。白已醉，以水洒面，使之清醒后，即时写了多篇。
鲛室：神话中海中鲛人所居之处，这里指海。琼瑰：玉石。', '一声响亮的雷声宛如从游人的脚底下震起，有美堂上，浓厚的云雾缭绕，挥散不开。远远的天边，疾风挟带着乌云，把海水吹得如山般直立；一阵暴雨，从浙东渡过钱塘江，向杭州城袭来。西湖犹如金樽，盛满了雨水，几乎要满溢而出；雨点敲打湖面山林，如羯鼓般激切，令人开怀。我真想唤起沉醉的李白，用这满山的飞泉洗脸，让他看看，这眼前的奇景，如倾倒了鲛人的宫室，把珠玉洒遍人寰。', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea70703572034f65a35fb", "shortContent": "熙宁六年（1073），苏轼任杭州通判时作此诗。有美堂在西湖东南面的吴山上，为杭州知州梅挚于嘉祐二年（1057）所建。堂名“有美”，乃取自宋仁宗赐梅挚诗“地有吴山美，东南第一州”中的二字。\n乍读此诗，常使人错以为是截取古风诗中的一段，其气势、节奏和结构与一般的七律颇不相同。例如，开篇便不取律诗寻常开合之法，而是直接将大暴风雨的声势突兀展现出来。俗话说高雷无雨，一旦雷起脚底，其雨势便可想而知了。“一声...", "authors": ["胡晓晖"], "pressName": "上海辞书出版社"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646785d730675327e195762b", "shortContent": "熙宁六年（1073），苏轼任杭州通判时作此诗。有美堂在西湖东南面的吴山上，为杭州知州梅挚于嘉祐二年（1057）所建。堂名“有美”，乃取自宋仁宗赐梅挚诗“地有吴山美，东南第一州”中的二字。\n\n乍读此诗，常使人错以为是截取古风诗中的一段，其气势、节奏和结构与一般的七律颇不相同。例如，开篇便不取律诗寻常开合之法，而是直接将大暴风雨的声势突兀展现出来。俗话说高雷无雨，一旦雷起脚底，其雨势便可想而知了。“一...", "authors": ["胡晓晖"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646b0ad55fc8182fe9b844a4", "shortContent": "熙宁六年（1073），苏轼任杭州通判时作此诗。有美堂在西湖东南面的吴山上，为杭州知州梅挚于嘉祐二年（1057）所建。堂名“有美”，乃取自宋仁宗赐梅挚诗“地有吴山美，东南第一州”中的二字。\n\n乍读此诗，常使人错以为是截取古风诗中的一段，其气势、节奏和结构与一般的七律颇不相同。例如，开篇便不取律诗寻常开合之法，而是直接将大暴风雨的声势突兀展现出来。俗话说高雷无雨，一旦雷起脚底，其雨势便可想而知了。“一...", "authors": ["胡晓晖"], "pressName": "上海辞书出版社"}]', '', 'center', 1470665932, '57ba67fd128fe1005f8a82c6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10189, '芙蓉楼送辛渐二首', NULL, 1224, 202, 2, 8, '王昌龄', NULL, 10051, '57b91963128fe10054ca5788', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155111.htm', '', '【其一】
寒雨连江夜入吴，平明送客楚山孤。
洛阳亲友如相问，一片冰心在玉壶。
【其二】
丹阳城南秋海阴，丹阳城北楚云深。
高楼送客不能醉，寂寂寒江明月心。', '《芙蓉楼送辛渐》是唐朝诗人王昌龄的一首送别诗，是作者被贬为江宁县丞时所写。诗的构思新颖，淡写朋友的离情别绪，重写自己的高风亮节。首两句写景，用苍茫的江雨和孤峙的楚山，烘托送别时的凄寒孤寂之情，也展现了诗人开朗的胸怀和坚强的性格；后两句诗人以晶莹透明的冰心玉壶自喻，与前面屹立在江天之中的孤山之间形成一种有意无意的照应，令人自然联想到诗人孤介傲岸的形象和光明磊落、表里澄澈的品格。全诗即景生情，寓情于景，含蓄蕴藉，韵味无穷。', '芙蓉楼：湖南洪江（黔城）芙蓉楼。
辛渐：诗人的一位朋友。
寒雨：秋冬时节的冷雨。
连江：雨水与江面连成一片，形容雨很大。
吴：古代国名，这里泛指江苏南部、浙江北部一带。江苏镇江一带为三国时吴国所属。
平明：天亮的时候。
客：指作者的好友辛渐。
楚山：楚山：楚地的山。这里的楚也指镇江市一带，因为古代吴、楚先后统治过这里，所以吴、楚可以通称。
孤：独自，孤单一人。
洛阳：现位于河南省西部、黄河南岸。
冰心：比喻纯洁的心。
玉壶：道教概念妙真道教义，专指自然无为虚无之心。陆机《汉高祖功臣颂》有“心若怀冰”句，比喻心地纯洁。鲍照《白头吟》：“直如朱丝绳，清如玉壶冰。”也是以“玉壶冰”比喻清白的操守。唐人有时也以此比喻为官廉洁，如姚崇《冰壶诫》序云“夫洞澈无瑕，澄空见底，当官明白者，有类是乎？故内怀冰清，外涵玉润，此君子冰壶之德也”。', '冷雨洒满江天的夜晚我来到吴地，天明送走好友只留下楚山的孤影。到了洛阳，如果有亲友向您打听我的情况，就请转告他们，我的心依然像玉壶里的冰一样纯洁，未受功名利禄等世情的玷污。
往丹阳城南望去，只见秋海阴雨茫茫；向丹阳城北望去，只见楚天层云深深。高楼送客，与友人依依惜别，心情悲愁，喝酒也不能尽兴。四周一片寂静，对着寒冷江天，只有高悬的明月照我心。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929403572034f659e316", "shortContent": "题中芙蓉楼原名西北楼，遗址在润州（今江苏镇江）西北，登临可以俯瞰长江，遥望江北。这首诗大约作于开元二十九年（741）以后。王昌龄当时为江宁（今江苏南京市）丞，辛渐是他的朋友，这次拟由润州渡江，取道扬州，北上洛阳。王昌龄可能陪他从江宁到润州，然后在此分手。这诗原题共两首，第二首说到头天晚上诗人在芙蓉楼为辛渐饯别，这一首写的是第二天早晨在江边离别的情景。\n“寒雨连江夜入吴”，迷濛的烟雨笼罩着吴地江天，...", "authors": ["葛晓音"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d104", "shortContent": "题中芙蓉楼原名西北楼，遗址在润州（今江苏镇江）西北，登临可以俯瞰长江，遥望江北。这首诗大约作于开元二十九年（741）以后。王昌龄当时为江宁（今江苏南京市）丞，辛渐是他的朋友，这次拟由润州渡江，取道扬州，北上洛阳。王昌龄可能陪他从江宁到润州，然后在此分手。这诗原题共两首，第二首说到头天晚上诗人在芙蓉楼为辛渐饯别，这一首写的是第二天早晨在江边离别的情景。\n\n“寒雨连江夜入吴”，迷蒙的烟雨笼罩着吴地江天...", "authors": ["葛晓音"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f459761253910e903b0", "shortContent": "这首诗是王昌龄的名篇，最后一句尤为脍炙人口。此诗通篇浑然一体，无论是内心情感的表白，还是送别意境的营造，都与“一片冰心在玉壶”相一致。\n\n芙蓉楼，原名西北楼，在今镇江西北。王昌龄当时在南京做官，友人辛渐即将由镇江过江，取道扬州前往洛阳。王昌龄从南京赶到镇江，在芙蓉楼给辛渐饯行。雨一直下个不停，一夜寒雨汇入江水，东流吴地。“寒”字，点明季节特征，亦衬托心情之黯然神伤。“连”字说明雨下得很大很久，雨水...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312703bf2af4e09d55b6730", "shortContent": "这首诗是王昌龄的名篇，最后一句尤为脍炙人口。此诗通篇浑然一体，无论是内心情感的表白，还是送别意境的营造，都与“一片冰心在玉壶”相一致。\n\n芙蓉楼，原名西北楼，在今镇江西北。王昌龄当时在南京做官，友人辛渐即将由镇江过江，取道扬州前往洛阳。王昌龄从南京赶到镇江，在芙蓉搂给辛渐饯行。雨一直下个不停，一夜寒雨汇入江水，东流吴地。“寒”字，点明季节特征，亦衬托心情之黯然神伤。“连”字说明雨下得很大很久，雨水...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312706ac305cf0801816fea", "shortContent": "这首诗是王昌龄的名篇，最后一句尤为脍炙人口。此诗通篇浑然一体，无论是内心情感的表白，还是送别意境的营造，都与“一片冰心在玉壶”相一致。\n\n芙蓉楼，原名西北楼，在今镇江西北。王昌龄当时在南京做官，友人辛渐即将由镇江过江，取道扬州前往洛阳。王昌龄从南京赶到镇江，在芙蓉楼给辛渐饯行。雨一直下个不停，一夜寒雨汇入江水，东流吴地。“寒”字，点明季节特征，亦衬托心情之黯然神伤。“连”字说明雨下得很大很久，雨水...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f0b545fc8182fe9ca25b4", "shortContent": "早在六朝刘宋时期，诗人鲍照就用“清如玉壶冰”（《代白头吟》）来比喻高洁清白的品格。自从开元宰相姚崇作《冰壶诫》以来，盛唐诗人如王维、崔颢、李白等都曾以冰壶自励，推崇光明磊落、表里澄澈的品格。王昌龄托辛渐给洛阳亲友带去的口信不是通常的平安竹报，而是传达自己依然冰清玉洁、坚持操守的信念，是大有深意的。据《唐才子传》和《河岳英灵集》载，王昌龄曾因不拘小节，“谤议沸腾，两窜遐荒”，开元二十七年被贬岭南即是...", "authors": ["葛晓音"], "pressName": "上海辞书出版社"}]', '陆时雍《唐诗镜》：炼格最高。“孤”字时作一语。后二句别有深情。
周珽《唐诗选脉会通评林》：神骨莹然如玉。薛应旂曰：多写己意。送客有此一法者。
黄生《唐诗摘钞》：古诗“清如玉壶冰”，此自喻其志行之洁，却将古句运用得妙。
邹弢《精选评注五朝诗学津梁》：自夜至晓饯别，风景尽情描出。下二句写临别之语。意在言外。
《唐人万首绝句选评》：唐人多送别妙。少伯请送别诗，俱情极深，味极永，调极高，悠然不尽，使人无限留连。
黄叔灿《唐诗笺注》：上二句送时情景，下二句托寄之言，自述心地莹洁，无尘可滓。本传言少伯“不护细行”、或有所为而云。
俞陛云《诗境浅说续编》：借送友以自写胸臆，其词自萧洒可爱。', 'center', 1413470845, '57b90afbc4c97100558f7403', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10191, '渔歌子 · 西塞山前白鹭飞', NULL, 918, 8, 2, 11, '张志和', NULL, 10053, '57ba7b6ac4c97100614d0e91', '唐', 'ci', '词', 'http://baike.baidu.com/view/3212939.htm', '', '西塞山前白鹭飞，桃花流水鳜鱼肥。青箬笠，绿蓑衣，斜风细雨不须归。', '此词开头两句写垂钓的地方和季节。这两句里，出现了山、水、鸟、花、鱼，勾勒了一个垂钓的优美环境，为人物出场作好了铺垫。词的后两句写烟波上垂钓。尾句里的“斜风细雨”既是实写景物，又另含深意。这首词通过对自然风光和渔人垂钓的赞美，表现了作者向往自由生活的心情。', '渔歌子：原是曲调名，后来人们根据它填词，又成为词牌名。
西塞山：在今浙江省湖州市西面。
前：一作“边”。
白鹭：一种白色的水鸟。
桃花流水：桃花盛开的季节正是春水盛涨的时候，俗称桃花汛或桃花水。
鳜鱼：俗称“花鱼”、“桂鱼”。扁平、口大、鳞细、黄绿色，味道鲜美。
箬笠：用竹篾、箬叶编的斗笠。
蓑衣：用草或棕麻编织的雨衣。', '西塞山前白鹭在自由地飞翔，江岸桃花盛开，春水初涨，水中鳜鱼肥美。渔翁头戴青色的箬笠，身披绿色的蓑衣，冒着斜风细雨，乐然垂钓，用不着回家。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74857d0ac1145494bac1", "shortContent": "在唐代，小令词风格多样，清空乃其风格之一；王维一派水墨画又有冲淡之特质。词人而兼画家的张志和，则完美地融合了这两种艺术风格。他把高远的情思外化为清空的意境，又把质朴玲珑的语感，提炼为翛然脱俗的冲淡意趣，从而使他的词作形成了独树一帜的高蹈风格。他传世之作有《渔父》词五首，但另外四首却都为这一首的光辉所掩。也正因为有这么一首短短的词，张志和得以传名千古。\n张志和肃宗时待诏翰林，做过左金吾卫录事参军，因...", "authors": ["吴调公"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892bbb31680ae4c4b4b0", "shortContent": "在唐代，小令词风格多样，清空乃其风格之一；王维一派水墨画又有冲淡之特质。词人而兼画家的张志和，则完美地融合了这两种艺术风格。他把高远的情思外化为清空的意境，又把质朴玲珑的语感，提炼为翛然脱俗的冲淡意趣，从而使他的词作形成了独树一帜的高蹈风格。他传世之作有《渔父》词五首，但另外四首却都为这一首的光辉所掩。也正因为有这么一首短短的词，张志和得以传名千古。\n\n张志和肃宗时待诏翰林，做过左金吾卫录事参军，...", "authors": ["吴调公"], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f3e8f18b220af4c007", "shortContent": "张飞，字益德，涿郡人，年轻时与关羽一道侍奉刘备，三人并肩作战，情同手足。刘备与曹操反目，投奔刘表。后曹操南下，进占荆州，刘备一路向南撤退，曹军紧追不舍，即将在当阳县长阪追上刘备。此时，张飞率领二十名骑兵断后。他守住河岸、拆毁河桥，怒目圆睁，大喝曹军，竟无人敢近，故刘备等得以逃脱。刘备西进益州，张飞作为先锋到达江州，击败并活捉刘璋大将严颜。张飞怒斥其为何不早点投降，严颜临危不惧，回答其宁做断头将军，...", "authors": ["许孝乐"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471a061a5f1e74f9585f3b0", "shortContent": "由于取自民间，这首词的基调以清新、质朴见长。但另一方面，由于作者张志和并不是一个真正的渔父，而是以“烟波”为寄托的文人式的“钓徒”，所以词中除了具有民间文学的质朴、清新之气外，还融和着一种出淤泥而不染的古代高蹈文人的淡泊、澄洁的高情远意。\n词人的淡怀逸致不是诉诸直接咏怀，而是寄情于景，以画入词。通篇二十七字，写了山，写了水，写了白鹭和肥鱼，写了斜风细雨，更写了优游自在的渔父。词人借渔父寄托自己的情...", "authors": ["吴调公"], "pressName": "上海辞书出版社"}]', '清·刘熙载《艺概》：张志和《渔歌子》“西塞山前白鹭飞”一阕，风流千古。东坡尝以其成句用入《鹧鸪天》，又用于《浣溪沙》，然其所足成之句，犹未若原词之妙通造化也。黄山谷亦尝以其词增为《浣溪沙》，且诵之有矜色焉。
清·黄苏《蓼园词评》：数句只写渔家之自乐其乐，无风波之患。对面已有不能自由者已。隐跃言外，蕴含不露，笔墨入化，超然尘埃之外。
清·俞陛云《唐五代两宋词选释》：自来高洁之士，每托志渔翁，访尚父于硒溪，讽灵钧于湘浦，沿及后贤，见于载籍者夥矣。而轩冕之士，能身在江湖者，实无几人。志和固手把钓竿者，而词言“西塞”、“巴陵”、“松江”、“雷溪”、“钓台”，地兼楚越，非一舟能达，则此词亦托想之语，初非躬历。然观其每首结句，君子固穷，达人知命，襟怀之超逸可知。“桃花流水”句，犹世所传诵。', 'indent', 1423169583, '57b9595b7db2a2005429b10d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10192, '念奴娇 · 过洞庭', NULL, 389, 643, 6, 6, '张孝祥', NULL, 10054, '57bbbd045bbb500063036208', '宋', 'ci', '词', 'http://baike.baidu.com/view/384002.htm', '', '洞庭青草，近中秋，更无一点风色。玉鉴琼田三万顷，着我扁舟一叶。素月分辉，明河共影，表里俱澄澈。悠然心会，妙处难与君说。
应念岭海经年，孤光自照，肝肺皆冰雪。短发萧骚襟袖冷，稳泛沧浪空阔。尽挹西江，细斟北斗，万象为宾客。扣舷独啸，不知今夕何夕。', '此词是南宋文学家张于湖泛舟洞庭湖时即景抒怀之作，藉洞庭夜月之景，抒发了作者的髙洁忠贞和豪迈气概，同时隐隐透露出作者被贬谪之悲凉。
人们比较熟悉稼轩与东坡之间的继承和发展关系，但却较少有人注意于湖在苏、辛之间所起到的过渡性作用。于湖实际是南宋豪放词派重要奠基人之一。这首《念奴娇》就是广泛传诵的于湖代表作。宋孝宗乾道二年（西元一一六六年），于湖因受政敌谗害而被免职。他从桂林北归，途经洞庭湖，卽景生情而作。这是一首寓情於景之作。它以生动的笔墨，描绘了中秋节前夕洞庭湖雄伟壮阔、晴明澄澈的绚丽画面，抒写了作者光明磊落、冰肝雪胆般纯洁髙尚的情操，反映了作者对投降派之蔑视。
词的上阕写湖上美景。开篇三句点地域与节候的特点，点明了一个接近中秋、风平浪静的洞庭湖之夜。「玉鉴琼田三万顷，着我扁舟一葉」是词中壮丽的佳句，它形象地槪括出洞庭湖广阔无涯、优美而又平静的特点，抒发了作者泛舟湖上所得的乐趣。字里行间透露出作者以世间万物的主人翁而自居的思想境界。「素月分辉，明河共影，表里俱澄澈」三句旣是对洞庭湖的夜景加以补充，同时又是作者爱国抗金这一髙尚人格的具体写照，暗地里还反映了作者对南宋小朝廷腐朽黑暗政治的憎恶和不满。「悠然心会，妙处难与君说」两句，以虚带实，含而不露，似合而实起，引出下阕。
下阕以「应」字领起，似承而转。作者回忆起「岭表经年」的为宦生涯，并以「孤光自照，肝胆皆冰雪」来象徵自己纯正无私和洁身自好，这对谗害自己的政敌，无疑是一有力回击。在结构上，它又与上阕「表里俱澄澈」的意境上呼下应。「短髮萧疏襟袖冷，稳泛沧溟空阔」承上，进一步抒发积郁于胸的堂堂正气，暗示出尽管屡遭谗害，环境险恶，但自己依然两袖清风，稳操航向，安如泰山。不仅如此，词人还由此而产生出一段浪漫主义的幻想。「尽挹西江，细斟北斗，万象为宾客」三句是词中传神之笔，它进一步突现出作者襟怀坦荡、识见超迈与乐观豪爽的性格，颇有居髙临下，对投降派不屑一顾的气势。煞尾，以「扣舷独啸，不知今夕何夕」结束全篇，更觉神馀言外。
这首词画面开阔，意境优美，大气磅礴，具有鲜明的浪漫主义特色，艺术感染力很强。其特点集中表现在以下三个方面：一是恰当的比喻。词中用「玉鉴琼田」来形容波平浪静与水晶般透明的洞庭湖，反衬出「扁舟一葉」之中的作者人格的纯洁髙尚。「孤光自照，肝胆皆冰雪」喩词人心地纯净，俯仰无愧。二是奇特的想象。词中幕天席地、友月交风的意境固然来自现实生活，但是，如果没有充分的、大胆的想象，决不会写得如此生动感人。至于同中写到的吸江酌斗、宾客万象的境界，则纯係想象之词了。正是由于作者把现实生活中不可能出现的事物写得惟妙惟肖，生动传神，才反映出作者强烈的爱憎与美的理想。作者正是通过想象这一心灵的眼睛去探察客观事物内部的奥秘，凭藉想象这一心灵的翅膀向着理想的境界起飞。三是豪放的风格。古代描写洞庭湖的佳作层出不穷。如孟襄陽《望洞庭湖赠张丞相》、杜少陵《登岳阳楼》是著名的律诗，范文正《岳阳楼记》是著名的散文。它们都以自己的特点和豐富的内容而千古不朽。但就平静的洞庭湖之夜并把自己置身湖上舟中来抒发豪情逸兴的佳篇，却并不多见。这一点充分显示出作者艺术上的独创性。这首词句句有人，笔笔含情，「情以物动，辞以情发」，在艺术上达到了内情与外景水乳交融的妙境。词中那种豪放的风格，也由此产生。', '洞庭：湖名，在湖南岳阳西南。
素月：洁白的月亮。
明河：一作「银河」，天河。
表里：里里外外。此处指天上月亮和银河的光辉映入湖中，上下一片澄明。
岭海：一作「岭表」，岭外，即五岭以南的两广地区，作者此前为官广西。
经年：经过一年。
孤光：指月光。
肝肺：一作「肝胆」。
冰雪：比喻心地光明磊落像冰雪般纯洁。
萧骚：一作「萧疏」，稀疏。
襟袖冷：形容衣衫单薄。
沧浪：一作「沧溟」，青苍色的水。
挹（yì）：一作「吸」，舀。
西江：长江连通洞庭湖，中上游在洞庭以西，故称西江。
北斗：星座名。由七颗星排成像舀酒的斗的形状。
万象：万物。
扣：一作「叩」，敲击。
啸：一作「笑」，撮口作声。
「不知今夕何夕」句：赞叹夜色美好，使人沉醉，竟忘掉一切（包括时间）。', '洞庭湖与青草湖相连，浩瀚无垠，在这个中秋将至的时候，没有一丝风过的痕迹。是玉的世界，还是琼的原野？三万顷明镜般的湖水，载着我一叶细小的扁舟。皎洁的明月和灿烂的银河，在这浩瀚的玉镜中映出她们的芳姿，水面上下一片明亮澄澈。体会着万物的空明，却不知如何道出，与君分享。
感怀这一轮孤光自照的明月啊，多少年徘徊于岭海之间，胸襟仍像冰雪一样透明。而此刻的我，正披着萧瑟幽冷的鬚髮和衣袂，平静的泛舟在这广阔浩淼的苍溟之中。让我捧尽西江清澈的江水，细细的斟在北斗星做成的酒勺中，请天地万象统统来做我的宾客，我尽情的拍打着我的船舷，独自的放声高歌啊，怎能记得此时是何年！', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74e2c6e67846a9206bfd", "shortContent": "宋孝宗乾道元年（1165），张孝祥出知静江府（治所在今广西桂林），兼广南西路经略安抚使，七月到任。次年六月，被谗落职北归，途经湖南洞庭湖（词中的“洞庭”、“青草”二湖相通，总称洞庭湖）。时近中秋的平湖秋月之夜，诱发了词人深邃的“宇宙意识”和勃然诗兴，使他援笔写下了这首词。\n说到诗歌表现“宇宙意识”，我们便会想到唐人诗中的《春江花月夜》和《登幽州台歌》。不过，宋词所表现的“宇宙意识”和唐诗比较起来，...", "authors": ["杨海明"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5e67d0ac1145495e923", "shortContent": "宋孝宗乾道元年（1165），张孝祥出知静江府（治所在今广西桂林），兼广南西路经略安抚使，七月到任。次年六月，被谗落职北归，途经湖南洞庭湖（词中的“洞庭”、“青草”二湖相通，总称洞庭湖）。时近中秋的平湖秋月之夜，诱发了词人深邃的“宇宙意识”和勃然诗兴，使他援笔写下了这首词。\n说到诗歌表现“宇宙意识”，我们便会想到唐人诗中的《春江花月夜》和《登幽州台歌》。不过，宋词所表现的“宇宙意识”和唐诗比较起来，...", "authors": ["杨海明"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255ccce4d48ba496db0", "shortContent": "宋孝宗乾道元年（1165），张孝祥出知静江府（治所在今广西桂林），兼广南西路经略安抚使，七月到任。次年六月，被谗落职北归，途经湖南洞庭湖（词中的“洞庭”“青草”二湖相通，总称洞庭湖）。时近中秋的平湖秋月之夜，诱发了词人深邃的“宇宙意识”和勃然诗兴，使他援笔写下了这首词。\n\n说到诗歌表现“宇宙意识”，我们便会想到唐人诗中的《春江花月夜》和《登幽州台歌》。不过，宋词所表现的“宇宙意识”和唐诗比较起来，...", "authors": ["杨海明"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f35fde49f46528ad26477", "shortContent": "宋孝宗乾道元年(1165)，张孝祥出知静江府（治所在今广西桂林），兼广南西路经略安抚使，七月到任。次年六月，被谗落职北归，途经湖南洞庭湖（词中的“洞庭”“青草”二湖相通，总称洞庭湖）。时近中秋的平湖秋月之夜，诱发了词人深邃的“宇宙意识”和勃然诗兴，使他援笔写下了这首词。\n词的开头三句即在我们面前展现了一个静谧、开阔的画面。“气蒸云梦泽，波撼岳阳城”，现实中的八月洞庭湖，可以说是极少会风平浪静的。因...", "authors": ["杨海明"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "647343de902ee364cc9a467b", "shortContent": "这首词是张孝祥在孝宗乾道四年（1168），由知潭州（今湖南长沙）调知荆南（荆州，今湖北江陵）兼荆湖北路安抚使时，沿湘江入洞庭湖所作。他前年为言官所劾，罢桂林任北归，也曾泛湘江至洞庭，作《念奴娇·过洞庭》词，有“孤光自照，肝胆皆冰雪。短发萧骚襟袖冷”等语，流露出一种不谐于世的情绪。这一首写得心气平和多了。他从长沙出发，舟行至洞庭湖，前一段路程以“行尽潇湘”一笔带过，“到洞庭”三字领出下文。“楚天阔处...", "authors": ["曹济平"], "pressName": "上海辞书出版社"}]', '王湘绮《湘绮楼词选》：飘飘有凌云之气，觉东坡《水调》犹有尘心。', 'indent', 1362605429, '57b8eafb2e958a005fa4c54b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10194, '永州八记 · 其四 · （至小丘西）小石潭记', NULL, 365, 243, 1, 14, '柳宗元', NULL, 10055, '57b9042f7db2a2005426b940', '唐', 'wen', '文', 'http://baike.baidu.com/view/47562.htm', '', '从小丘西行百二十步，隔篁竹，闻水声，如鸣珮环，心乐之。伐竹取道，下见小潭，水尤清冽。全石以为底，近岸，卷石底以出，为坻，为屿，为嵁，为岩。青树翠蔓，蒙络摇缀，参差披拂。
潭中鱼可百许头，皆若空游无所依，日光下澈，影布石上。佁然不动，俶尔远逝，往来翕忽，似与游者相乐。
潭西南而望，斗折蛇行，明灭可见。其岸势犬牙差互，不可知其源。
坐潭上，四面竹树环合，寂寥无人，凄神寒骨，悄怆幽邃。以其境过清，不可久居，乃记之而去。
同游者：吴武陵，龚古，余弟宗玄。隶而从者，崔氏二小生，曰恕己，曰奉壹。', '柳宗元于唐顺宗永贞元年（公元805年）因拥护王叔文的改革，被贬为永州司马，王叔文被害。政治上的失意，使他寄情于山水，柳宗元贬官之后，为排解内心的愤懑之情，常常不避幽远，伐竹取道，探山访水，并通过对景物的具体描写，抒发自己的不幸遭遇，此间共写了八篇山水游记，后称《永州八记》。
《小石潭记》保持了《永州八记》一贯的行文风格，察其微，状其貌，传其神。是一篇充满了诗情画意、情景交融的山水游记散文。', '从：自，由。
小丘：小山丘（在小石潭东边）。
西：向西，名词作状语。
行：走。
篁（huáng）竹：成林的竹子。
如鸣珮环：好像人身上佩戴的佩环相碰击发出的声音。鸣，使……发出声音；珮、环，玉质装饰物。
乐：以……为乐，对……感到快乐（意动用法）。
伐：砍伐。
取：这里指开辟。
下见小潭：向下看就看见一个小潭。见，看见；下，向下。
水尤清冽：水格外（特别）清澈。尤，格外、特别；冽，凉。清冽，清凉。
全石以为底：即以全石为底（潭）把整块石头当作底部。以，把；为，当作。
「近岸，卷石底以出」句：靠近岸的地方，石底有些部分翻卷过来露出水面。近，靠近；岸，岸边；卷，弯曲；以，相当于「而」，表修饰，不译。
「为坻（chí），为屿，为嵁（kān），为岩」句：成为坻、屿、嵁、岩各种不同的形状。坻，水中高地；屿，小岛；嵁，不平的岩石；岩，悬崖。
翠蔓：翠绿的藤蔓。
「蒙络摇缀，参差披拂」句：覆盖缠绕，摇动下垂，参差不齐，随风飘动。
可百许头：大约有一百来条。文中指小潭里的鱼大约有一百来条。可，大约；许，用在数词后表示约数，相当于同样用法的「来」。
皆若空游无所依：都好像在空中游动，什么依托也没有。空：在空中，名词作状语；皆：全、都。
「日光下澈，影布石上」句：阳光向下直照到水底，鱼的影子好像映在水底的石头上。下，向下照射；布，照映、分布；澈，一作「彻」，穿透。
佁（yǐ）然不动：（鱼影）呆呆地一动不动。佁然，呆呆的样子。
俶（chù）尔远逝：忽然间向远处游去了。俶尔，忽然。
往来翕（xī）忽：来来往往，轻快敏捷。翕忽，轻快敏捷的样子；翕，迅疾。
斗折：像北斗七星那样曲折。
蛇行：像蛇爬行那样弯曲。
明灭可见：若隐若现。灭，暗、看不见。
「斗折蛇行，明灭可见」句：（溪水）曲曲折折，（望过去）一段看得见，一段又看不见。
犬牙差（cī）互：像狗的牙齿那样互相交错。犬牙，像狗的牙齿一样；差互，互相交错。
「凄神寒骨，悄（qiǎo）怆（chuàng）幽邃（suì）」句：使人感到心神凄凉，寒气透骨，幽静深远，弥漫着忧伤的气息。凄、寒，使动用法，使……感到凄凉，使……感到寒冷；悄怆，凄凉的样子；邃，深。
以其境过清：因为那种环境太过凄清。以，因为；其，那；清，凄清。
「不可久居，乃记之而去」句：不能长时间停留，于是记下小石潭的情况就离开了。居，待、停留；乃，于是……就；之，代游小石潭这件事；去，离开。
吴武陵：作者的朋友，也被贬在永州。
龚古：作者的朋友。
宗玄：作者的堂弟。
「隶而从者，崔氏二小生」句：跟着我一同去的，有姓崔的两个年轻人。隶而从，跟着同去的；隶，作为随从，动词；崔氏，指柳宗元姐夫崔简；小生，年轻人。', '从小丘向西走一百二十多步，隔着竹林，可以听到流水的声音，好像人身上佩带的玉佩、玉环相互碰击发出的声音，心里十分高兴。砍伐竹子，开辟道路，向下看见一个小潭，水格外清澈。小潭以整块石头为底，靠近岸边的地方，石底有些部分翻卷出来，露出水面，成为水中的高地，像是水中的小岛，也有高低不平的石头和小岩石（露了出来）。青葱的树木，翠绿的藤蔓，覆盖缠绕，摇动连结，参差不齐，随风飘拂。
潭中的鱼大约有百多条，都好像在空中游动，什么依靠也没有。阳光直照到水底，鱼的影子映在水底的石上。鱼儿呆呆地一动不动，忽然向远处游去，来来往往，轻快敏捷，好像在和游玩的人逗玩。
向小石潭的西南方望去，溪岸像北斗七星一样曲折，像蛇爬行一样弯曲，望过去一段看得见，一段看不见。溪岸的形状像狗的牙齿那样参差不齐，不能知道溪水的源头在哪里。
我坐在潭边，四下里竹林和树木包围着，寂静没有旁人。使人感到心神凄凉，寒气透骨，幽静深远，弥漫着忧伤的气息。因为那种环境太过凄清，不能长时间停留，于是记录下了此地就离开。
一同去游览的人有吴武陵、龚古、我的弟弟宗玄。我带着一同去的，有姓崔的两个年轻人。一个名叫恕己，一个名叫奉壹。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1f0d635634aee3eab4e", "shortContent": "这是《永州八记》的第四篇。题中有个“至”字，第一段即紧承上篇《钴鉧潭西小丘记》，写从小丘西行“至”小石潭的经过。“隔篁竹，闻水声，如鸣珮环”，于是“心乐之”，欲寻声而往，一窥究竟；但为丛篁所隔，无路可通，便下决心“伐竹取道”。“伐竹取道”四字，用行动写心情，坐实了前边的“乐”字。到了“下见小潭，水尤清冽”，见得力气没有白费，其“乐”更不待言。这几句，既与前篇联系，点出小石潭的环境，又表现了发现小石...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645d12f76de2f61f4bb3feb6", "bookTitle": "柳宗元诗文鉴赏辞典", "articleId": "646b38fd5e6bb82b8cdf6f8d", "shortContent": "这是《永州八记》的第三篇。开头几句，照应前两篇，点出西山、钴[插图]潭和小丘的发现经过及其位置，并为后面“不匝旬而得异地者二”预留伏线。接下去，即抓住小丘的“异”处，描绘满布丘上的嶙嶙奇石。在一般人看来，那些毫无生命的石头本来就暴露在那里；但在作者眼中，却是“突怒偃蹇、负土而出、争为奇状”。这是说：那埋于泥土之中，不见天日的石头，不甘埋没，愤然突破地面，顶土而出，争作奇状，以显示自己的存在。构思何...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645d12f76de2f61f4bb3feb6", "bookTitle": "柳宗元诗文鉴赏辞典", "articleId": "646b39875b7b0d4f452c5c6c", "shortContent": "这是《永州八记》的第四篇。题中有个“至”字，第一段即紧承上篇《钴[插图]潭西小丘记》，写从小丘西行“至”小石潭的经过。“隔篁竹，闻水声，如鸣珮环”，于是“心乐之”，欲寻声而往，一窥究竟；但为丛篁所隔，无路可通，便下决心“伐竹取道”。“伐竹取道”四字，用行动写心情，坐实了前边的“乐”字。到了“下见小潭，水尤清冽”，见得力气没有白费，其“乐”更不待言。这几句，既与前篇联系，点出小石潭的环境，又表现了发...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "64720974902ee364cc95ad9e", "shortContent": "这是《永州八记》的第四篇。第一段即紧承上篇《钴鉧潭西小丘记》，写从小丘西行至小石潭的经过。“隔篁竹，闻水声，如鸣珮环”，于是“心乐之”，欲寻声而往，一窥究竟；但为丛篁所隔，无路可通，便下决心“伐竹取道”。“伐竹取道”四字，用行动写心情，坐实了前边的“乐”字。到了“下见小潭，水尤清冽”，见得力气没有白费，其“乐”更不待言。这几句，既与前篇联系，点出小石潭的环境，又表现了发现小石潭的喜悦心情。未见小潭...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '沈德潜《唐宋八大家文读本》：记潭中鱼数语，动定俱妙。后全在不尽，故意境弥深。
陈衍《石遗室论文》：《小石潭记》极短篇，不过百许字，亦无特别风景可以出色，始终写水竹凄清之景而已。而前言「心乐」，中言潭中鱼与游者相乐，后「凄神寒骨」，理似相反，然乐而生悲，游者常情。大而汾水，小而兰亭，此物此志也。其写鱼云：「潭中鱼可百许头，皆空游无所依。日光下澈，影布石上，怡然不动，傲尔远逝，往来翕忽。」工于写鱼，工于写水之情也。
孙琮《山晓阁选唐大家柳柳州全集》：古人游记，写尽妙景，不如不写尽为更佳；游尽妙境，不如不游尽为更高。盖写尽游尽，早已境味索然；不写尽，不游尽，便见余兴无穷。篇中遥望潭西南一段，便是不写尽妙景；潭中不久坐一段，便是不游尽妙境。笔墨悠长，情兴无极。', 'indent', 1413385566, '57ba483279bc4400639f8719', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10195, '渔翁', NULL, 350, 243, 2, 5, '柳宗元', NULL, 10055, '57b9042f7db2a2005426b940', '唐', 'shi', '诗', 'http://baike.baidu.com/view/159464.htm', '', '渔翁夜傍西岩宿，晓汲清湘燃楚竹。
烟销日出不见人，欸乃一声山水绿。
回看天际下中流，岩上无心云相逐。', '此诗通过渔翁在山水间获得内心宁静的描写，表达了作者在政治革新失败、自身遭受打击后寻求超脱的心境。全诗就像一幅飘逸的风情画，充满了色彩和动感，境界奇妙动人。其中“烟销日出不见人，欸乃一声山水绿”两句尤为人所称道。', '傍：靠近。西岩：当指永州境内的西山，可参作者《始得西山宴游记》。
汲（jí）：取水。
湘：湘江之水。
楚：西山古属楚地。
销：消散。亦可作“消”。
欸（ǎi）乃：象声词，一说指桨声，一说是人长呼之声。唐时湘中棹歌有《欸乃曲》（见元结《欸乃曲序》）。
下中流：由中流而下。
无心：陶渊明《归去来兮辞》：“云无心而出岫。”一般是表示庄子所说的那种物我两忘的心灵境界。苏轼《书柳子厚〈渔翁〉诗》云：“诗以奇趣为宗，反常合道为趣。熟味此诗有奇趣。然其尾两句，虽不必亦可。”严羽《沧浪诗话》从此说，曰：“东坡删去后二句，使子厚复生，亦必心服。”然刘辰翁认为：“此诗气泽不类晚唐，下正在后两句。”此后，关于此诗后两句当去当存，一直有两种意见。', '夜晚时分，渔翁船靠西山停宿。清晨起来，取水燃竹烧火做饭。
旭日初升，晓雾渐散，四周悄然既无人声。渔翁摇橹，欸乃一声，青山绿水映入眼帘。
回望天边，江水滚滚东流。山上白云，悠然自在舒卷。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92cc0f8fda55650555bc", "shortContent": "此篇作于永州（治今湖南永州）。作者所写的著名散文《永州八记》，于寄情山水的同时，略寓政治失意的孤愤。同样的意味，在他的山水小诗中也是存在的。此诗首句的“西岩”即指《始得西山宴游记》的西山，而诗中那在山青水绿之处自遣自歌、独往独来的“渔翁”，则含有几分自况的意味。主人公独来独往，突现出一种孤芳自赏的情绪，“不见人”、“回看天际”等语，又都流露出几分孤寂情怀。而在艺术上，此诗尤为后人注目。宋苏东坡赞叹...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad4797a92d5e4fd90c", "shortContent": "此篇作于永州（治今湖南永州）。作者所写的著名散文《永州八记》，于寄情山水的同时，略寓政治失意的孤愤。同样的意味，在他的山水小诗中也是存在的。此诗首句的“西岩”即指《始得西山宴游记》的西山，而诗中那在山青水绿之处自遣自歌、独往独来的“渔翁”，则含有几分自况的意味。主人公独来独往，突现出一种孤芳自赏的情绪，“不见人”“回看天际”等语，又都流露出几分孤寂情怀。而在艺术上，此诗尤为后人注目。宋苏东坡赞叹说...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f092fe", "shortContent": "柳宗元被贬到永州之后，精神上受到很大的刺激和压抑，于是他就借描写山水景物来寄托自己清高而孤傲的情感。《永州八记》中，处处有作者的身影，而《江雪》中的“独钓寒江雪”的“蓑笠翁”和本诗中的山青水绿之处自遣自歌、独往独来的“渔翁”，也含有几分自况的意味。作者在《始得西山宴游记》中写他登临西山时的感受：“悠悠乎与颢气俱，而莫得其涯；洋洋乎与造物者游，而不知其所穷。”达到了物我融合为一的忘我境界。此诗首句的...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127074e6f69b71e93f62cb", "shortContent": "柳宗元被贬到永州之后，精神上受到很大的刺激，备感压抑，于是他就借描写山水景物来寄托自己清高而孤傲的情感。《永州八记》中，处处有作者的身影，而《江雪》中的独钓寒江雪的“蓑笠翁”和本诗中的山青水绿之处自遣自歌、独往独来的“渔翁”，也含有几分自况的意味。作者在《始得西山宴游记》中写他登临西山时的感受说：“悠悠乎与颢气俱，而莫得其涯；洋洋乎与造物者游，而不知其所穷。”达到了物我融合为一的忘我境界。此诗首句...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "645d12f76de2f61f4bb3feb6", "bookTitle": "柳宗元诗文鉴赏辞典", "articleId": "646c51c0b6a81d0c53133d6e", "shortContent": "此篇作于永州（治今湖南永州）。作者所写的著名散文《永州八记》，于寄情山水的同时，略寓政治失意的孤愤。同样的意味，在他的山水小诗中也是存在的。此诗首句的“西岩”即指《始得西山宴游记》的西山，而诗中那在山青水绿之处自遣自歌、独往独来的“渔翁”，则含有几分自况的意味。主人公独来独往，突现出一种孤芳自赏的情绪，“不见人”、“回看天际”等语，又都流露出几分孤寂情怀。而在艺术上，此诗尤为后人注目。宋苏东坡赞叹...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '', 'center', 1416840213, '57b903c9df0eea006334f86e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10196, '江雪', NULL, 2450, 243, 2, 13, '柳宗元', NULL, 10055, '57b9042f7db2a2005426b940', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/47188/5028606.htm', '', '千山鸟飞绝，万径人踪灭。
孤舟蓑笠翁，独钓寒江雪。', '《江雪》是唐代诗人柳宗元的一首山水诗，描述了一幅江乡雪景图。山山是雪，路路皆白。飞鸟绝迹，人踪湮没。遐景苍茫，迩景孤冷。意境幽僻，情调凄寂。渔翁形象，精雕细琢，清晰明朗，完整突出。诗采用入声韵，韵促味永，刚劲有力。历代诗人无不交口称绝。千古丹青妙手，也争相以此为题，绘出不少动人的江天雪景图。', '绝：无，没有。
万径：虚指，指千万条路。
蓑笠（suō lì）：蓑衣和斗笠。', '所有的山，飞鸟全都断绝；所有的路，不见人影踪迹。
江上孤舟，渔翁披蓑戴笠；独自垂钓，不怕冰雪侵袭。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92cc34a8757d5a0e1d89", "shortContent": "这是一首押仄韵的五言绝句，是柳宗元的代表作之一。大约作于他谪居永州（治今湖南永州）期间。\n柳宗元被贬到永州之后，精神上受到很大刺激和压抑，于是，他就借描写山水景物，借歌咏隐居在山水之间的渔翁，来寄托自己清高而孤傲的情感，抒发自己在政治上失意的郁闷苦恼。因此，柳宗元笔下的山水诗有个显著的特点，那就是把客观境界写得比较幽僻，而诗人的主观的心情则显得比较寂寞，甚至有时不免过于孤独，过于冷清，不带一点人间...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad4797a92d5e4fd90b", "shortContent": "这是一首押仄韵的五言绝句，是柳宗元的代表作之一。大约作于他谪居永州（治今湖南永州）期间。\n\n柳宗元被贬到永州之后，精神上受到很大刺激和压抑，于是，他就借描写山水景物，借歌咏隐居在山水之间的渔翁，来寄托自己清高而孤傲的情感，抒发自己在政治上失意的郁闷苦恼。因此，柳宗元笔下的山水诗有个显著的特点，那就是把客观境界写得比较幽僻，而诗人的主观的心情则显得比较寂寞，甚至有时不免过于孤独，过于冷清，不带一点人...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e9039d", "shortContent": "柳宗元的《江雪》可谓将中国诗歌“含不尽之意在言外”的意境发挥到了极致。\n\n刺骨的寒风卷着玉蝶般的雪花，铺天盖地、纷纷扬扬地飘洒，山谷银装素裹，寂静得近乎忧伤。远远望去，只有连绵起伏的一层层山峦，干净、刺眼的白。没有人迹，白须的老翁、黄发的孩子，都已还家，躲在温暖的炉火旁，让跳跃的红温暖僵硬的四肢和脸庞。路人踏出的小径早已不见踪迹，让人忘却了曾经明媚和煦的春天郊游踏青的闲适与欢愉。没有林荫掩映的通幽...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127074e6f69b71e93f62c9", "shortContent": "柳宗元的《江雪》可谓将中国诗歌“含不尽之意在言外”的意境发挥到了极致。\n\n刺骨的寒风卷着玉蝶般的雪花，铺天盖地、纷纷扬扬地飘洒，山谷银装素裹，寂静得近乎忧伤。远远望去，只有连绵起伏的一层层山峦，干净、灼目，刺眼的白。没有人迹，白须的老翁、黄发的孩子，都已还家，躲在温暖的炉火旁，让跳跃的红温暖僵硬的四肢和脸庞，路人踏出的小径早已不见踪迹，让人忘却了曾经明媚和煦的春天，郊游踏青的闲适与欢愉。没有林荫掩...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127123e6f69b71e93f63a8", "shortContent": "柳宗元的《江雪》可谓将中国诗歌“含不尽之意在言外”的意境发挥到了极致。\n\n刺骨的寒风卷着玉蝶般的雪花，铺天盖地、纷纷扬扬地飘洒。山谷银装素裹，寂静得近乎忧伤。远远望去，只有连绵起伏的一层层山峦，干净、灼目，刺眼的白。没有人迹，白须的老翁、黄发的孩子，都已还家，躲在温暖的炉火旁，让跳跃的红温暖僵硬的四肢和脸庞，路人踏出的小径早已不见踪迹，让人忘却了曾经明媚和煦的春天，郊游踏青的闲适与欢愉。没有林荫掩...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645d12f76de2f61f4bb3feb6", "bookTitle": "柳宗元诗文鉴赏辞典", "articleId": "646c4ef87da2f75ac7079b3e", "shortContent": "这是一首押仄韵的五言绝句，是柳宗元的代表作之一。大约作于他谪居永州（治今湖南永州）期间。\n柳宗元被贬到永州之后，精神上受到很大刺激和压抑，于是，他就借描写山水景物，借歌咏隐居在山水之间的渔翁，来寄托自己清高而孤傲的情感，抒发自己在政治上失意的郁闷苦恼。因此，柳宗元笔下的山水诗有个显著的特点，那就是把客观境界写得比较幽僻，而诗人的主观的心情则显得比较寂寞，甚至有时不免过于孤独，过于冷清，不带一点人间...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471a1f5b6a81d0c532990c3", "shortContent": "在这首诗里，笼罩一切、包罗一切的东西是雪，山上是雪，路上也是雪，而且“千山”“万径”都是雪，才使得“鸟飞绝”“人踪灭”。就连船篷上，渔翁的蓑笠上，当然也都是雪。可是作者并没有把这些景物同“雪”明显地联系在一起。相反，在这个画面里，只有江，只有江心。江，当然不会存雪，不会被雪盖住，而且即使雪下到江里，也立刻会变成水。然而作者却偏偏用了“寒江雪”三个字，把“江”和“雪”这两个关系最远的形象联系到一起，...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}]', '《东坡题跋》：柳子厚云：“千山鸟飞绝……”人性有隔也哉！殆天所赋，不可及也已。
《对床夜语》：唐人五言四句，除柳子厚《钓雪》一诗之外，极少佳者。
《归叟诗话》：郑谷雪诗云：“江上晚来堪画处，渔人披得一蓑归。”此村学堂中语也，如柳子厚“千山鸟飞绝，万径人踪灭，孤舟蓑笠翁，独钧寒江雪”此信有格也哉，作诗者当以此为标准。
《唐诗品汇》：刘须溪云：得天趣，独由落句五字道尽矣。
《批点唐诗正声》：绝唱，雪景如在目前。
《增订评注唐诗正声》：好雪景，句句妙（末句下）。
《诗薮》：“千山鸟飞绝”二十字，骨力豪上，句格天成，然律以《辋川》诸作，便觉太闹。青莲“明月出天山，苍茫云海间。长风几万里，吹度玉门关”，浑雄之中，多少闲雅。
《而庵说唐诗》：余谓此诗乃子厚在贬时所作以自寓也。当此途穷日短，可以归矣，而犹依泊于此，岂为一官所系耶？一官无味如钓寒江之鱼，终亦无所得而已，余岂效此翁者哉！
《唐诗笺要》：柳州气骨迟重，故摹陶、韦不落浮佻。
《诗法易简录》：前二句不沾着“雪”字，而确是雪景，可称空灵，末句一点便足。阮亭论前人雪诗，于此诗尚有遗憾，甚矣诗之难也。
《古唐诗合解》：江寒而鱼伏，岂钓之可得？彼老翁独何为稳坐孤舟风雪中乎？世态寒冷，宦情孤冷，如钓寒江之鱼，终无所得。子厚以自寓也。
《唐诗三百首》：二十字可作二十层，却自一片，故奇。
《筱园诗话》：祖咏“终南阴岭秀”一绝，阮亭最所心赏，然不免气味凡近。柳子厚“千山鸟飞绝”一绝，笔意生峭，远胜祖咏之平，而阮翁反有微词，谓未免近俗。殆以人口熟诵而生厌心，非公论也。
《唐人绝句精华》：此诗读之便有寒意，故古今传诵不绝。', 'center', 1413387397, '57b90d7dc4c97100558f8bb5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (33753, '南柯子 · 次韵卫立礼春街踏月', NULL, 2, 169, 0, 1, '邵亨贞', NULL, 10917, '5858e5f461ff4b006875be34', '元', 'ci', '词', NULL, NULL, '门掩黄昏后，风销绛蜡时。行春小队夜参差。一曲仙音飞上广寒枝。
不访金钗客，空歌白苎衣。画桥梅影散玻瓈。月底婆娑带得暗香归。', NULL, NULL, NULL, NULL, NULL, 'indent', 1532021914, '585cdd9d128fe1006de454ef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10197, '永州八记 · 其一 · 始得西山宴游记', NULL, 65, 243, 2, 3, '柳宗元', NULL, 10055, '57b9042f7db2a2005426b940', '唐', 'wen', '文', 'http://baike.baidu.com/view/156371.htm', '', '自余为僇人，居是州，恒惴慄。其隙也，则施施而行，漫漫而游。日与其徒上高山，入深林，穷回溪，幽泉怪石，无远不到。到则披草而坐，倾壶而醉。醉则更相枕以卧，卧而梦。意有所极，梦亦同趣。觉而起，起而归。以为凡是州之山有异态者，皆我有也，而未始知西山之怪特。
今年九月二十八日，因坐法华西亭，望西山，始指异之。遂命仆人，过湘江，缘染溪，斫榛莽，焚茅茷，穷山之高而止。攀援而登，箕踞而遨，则凡数州之土壤，皆在衽席之下。
其高下之势，岈然洼然，若垤若穴，尺寸千里，攒蹙累积，莫得遯隐。萦青缭白，外与天际，四望如一。然后知是山之特出，不与培塿为类，悠悠乎与颢气俱，而莫得其涯；洋洋乎与造物者游，而不知其所穷。
引觞满酌，颓然就醉，不知日之入。苍然暮色，自远而至，至无所见，而犹不欲归。心凝形释，与万化冥合。然后知吾向之未始游，游于是乎始，故为之文以志。是岁元和四年也。', '柳宗元因参加王叔文革新运动，于唐宪宗元和元年（公元806年）被贬到永州担任司马。到永州后，其母病故，王叔文被处死，他自己也不断受到统治者的诽谤和攻击，心情压抑。永州山水幽奇雄险，许多地方还鲜为人知。柳宗元在这漫长的戴罪期间，便到处游览，搜奇探胜，借以开拓胸襟，得到精神上的慰藉。《永州八记》就是这种心态之下的游历结晶。此文为《永州八记》的第一篇，记叙了作者发现和宴游西山的经过，描写了西山的怪特，抒发了对怀才不遇愤懑和现实丑恶的无奈之情。', '僇人：同「戮人」，受过刑辱的人，罪人。作者因永贞革新失败，被贬为永州司马，故自称僇人。僇，通「戮」，耻辱。
是州：这个州，指永州。
恒：常常。
惴慄：恐惧不安。此意为害怕政敌落井下石。惴，恐惧；栗，发抖。
其：如果，连词。
隟：指空闲时间。
施施而行：慢慢地行走。施施，慢步缓行的样子。
漫漫而游：无拘无束地游。漫漫，不受拘束的样子。
日：每日，时间名词作状语。
其徒：那些同伴。徒，同一类的人，指爱好游览的人。
穷：走到尽头。
回溪：曲折溪流。
幽泉：深僻的泉水。
无远不到：没有一处僻远的地方不曾到过。
披草：分开草。披，用手分开。
倾壶：倒尽壶里的酒。倾，倒出来。
更相：互相。
意有所极，梦亦同趣：心里有向往的好境界，梦里也就有相同的乐趣。所极，所向往的境界；极，向往。
觉：睡醒。
以为：认为。
异态：奇特的形状。
未始：未曾。
怪特：奇异特别。
今年：指元和四年（公元809年）。
法华：指法华寺，在原零陵县城东山之上。
西亭：在法华寺内，为柳宗元所建，他经常在这里游赏山景，饮酒赋诗。
始：才。
指异之：指着它觉得它奇特。指，指点。异，觉得……奇特。
湘江：应为潇水。潇水流经永州城西，至萍州才与湘江汇合。
缘：沿着。
染溪：又作「冉溪」，柳宗元又称为「愚溪」，是潇水的一条小支流。
斫：砍伐。
榛莽：指杂乱丛生的荆棘灌木。
茅茷：指长得繁密杂乱的野草。茷，草叶茂盛。
穷山之高而止：一直砍除、焚烧到山的最高处才停止。穷，尽，指把榛莽、茅茷砍除、焚烧尽。
箕踞：像簸箕一样地蹲坐着。指坐时随意伸开两腿，像个簸箕，是一种不拘礼节的坐法。正规坐法，屁股要压在脚后跟上，两腿不能伸直。箕，簸箕。踞，蹲坐。
遨：游赏。
土壤：土地，指地域。
衽席：坐垫、席子。
其：代词，指上句「数州之土壤」。
岈然：高山深邃的样子。岈，《广韵》：「岈，蛤岈，山深之状。」
洼然：深谷低洼的样子。「岈然」承「高」，「洼然"承「下」。
垤：蚁封，即蚂蚁洞边的小土堆。「若垤」承「岈然」，「若穴」承「洼然」。
尺寸千里：（从西山顶上望去）只有尺寸之远，实际上有千里之遥。
攒：聚集在一起。
蹙：紧缩在一起。
累积：堆积。
莫得：没有什么能够。莫，没有什么，代词。得，能。
遁隐：隐藏。
萦青缭白：青山萦回，白水缭绕。作者为了突出「萦」「缭」景象，有意把主谓式变成动宾式。白，指山顶所见潇、湘二水。
际：接近。
四望如一：向四面望去都像一样的。
是山：这座山，指西山。
特出：一作「特立」，特别突出。
培塿：小土堆。
悠悠乎：辽阔浩渺啊。
灏气：同「浩气」，指天地间的大气。
俱：在一起。
涯：边际。
洋洋乎：悠然自得啊。
造物者：创造万物的天地，指大自然。
引觞：拿起酒杯。
满酌：斟满酒。
颓然：东倒西歪地。颓，跌倒。
就：接近，进入。
苍然：灰暗的样子，这里是形容傍晚的天色。
犹：还，仍然。
心凝：思想停止了（不再想任何事情）。
形释：形体消散了（忘掉了自己的存在）。
万化：万物变化，指自然界万物。
冥合：不知不觉地融合为一体。
向：以前。
未始游：不曾（真正）游赏过。
于是：从这里。
为之文：把这次西山之游写成文章。之，代指西山之游，是动词「为」的间接宾语。
志：记载下来。
是岁：这一年。
元和：唐宪宗李纯年号。', '我自从成为有罪的人，住在这个州里，就常常恐惧不安。如有空闲时间，就慢慢地行走，无拘束地游玩。每日和那些同伴，上高山，入深林，走到曲折溪流的尽头。幽僻的泉水，奇异的山石，没有一处僻远的地方不曾到过。到了目的地就分开草而坐下，倒尽壶中酒，一醉方休。醉了就互相枕着睡觉，睡觉了就做梦。心里有向往的好境界，梦里也就有（在这种境界中获得的）相同的乐趣。睡醒了就起来，起来了就回家。我以为凡是这个州的山有奇特形状的，我都游过了；可是我还未曾知道西山的奇异特别。
今年九月二十八日，我因坐在法华寺西亭，眺望西山，才指点着觉得它奇特。于是命令仆人渡过湘江，沿着染溪，砍伐荆棘，焚烧乱草，一直到山顶才停下。（我们随后）攀援登上山顶，随意坐下观赏，附近几个州的土地，就全在我们的坐席之下了。这几州的地势高低不平，高处是深山，低处是洼地，像蚁封，像洞穴，（看上去）只有尺寸之远，实际上有千里之遥。（这为千里之内的景物）聚集、紧缩、累积在眼下，没有什么能够隐藏。青山萦回，白水缭绕，外与天边相接。向四面望去都是一样的景象。（登上山顶）然后才知这座山的特别突出，与小土丘不一样。辽阔浩渺啊与天地间的大气合一而不能得到它的边际，悠然自得啊和大自然交游而不知它的尽期。（于是我们）拿起酒杯斟满酒，喝得东倒西歪地进入醉态，不知太阳下了山。灰暗的暮色，由远而至，直到看不见什么了还不想返回。（我只觉得）思想停止了，形体消散了，与自然界万物不知不觉地融为一体了。（游过西山）然后才知我以前不曾真正游赏过，真正的游赏是从这里开始的。所以我把这次西山之游写成文章以记载下来。
这一年是元和四年。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1f0c6e67846a921a129", "shortContent": "柳宗元因参与王叔文“永贞革新”失败，被贬为永州（今属湖南）司马。时艰不可济，唐祚难振兴，谤毁兼至，贫病交迫，老母病故，居处遭火，他满怀忧惧之情，多藉山水以排遣。被明人吴讷称为“体之正”的《永州八记》就写于此时。这“八记”是情景交融的真正游记，它们如同通景画，自成章法又互有联系。《始得西山宴游记》是其首篇。\n文章题目的“始得”二字是全文关键。诚如清人浦起龙《古文眉诠》卷五十三所说：“‘始得’有惊喜意...", "authors": ["邓乔彬"], "pressName": "上海辞书出版社"}, {"bookId": "645d12f76de2f61f4bb3feb6", "bookTitle": "柳宗元诗文鉴赏辞典", "articleId": "646b37d130675327e1a48ba0", "shortContent": "柳宗元因参与王叔文“永贞革新”失败，被贬为永州（今属湖南）司马。时艰不可济，唐祚难振兴，谤毁兼至，贫病交迫，老母病故，居处遭火，他满怀忧惧之情，多藉山水以排遣。被明人吴讷称为“体之正”的《永州八记》就写于此时。这“八记”是情景交融的真正游记，它们如同通景画，自成章法又互有联系。《始得西山宴游记》是其首篇。\n文章题目的“始得”二字是全文关键。诚如清人浦起龙《古文眉诠》卷五十三所说：“‘始得’有惊喜意...", "authors": ["邓乔彬"], "pressName": "上海辞书出版社"}]', '储欣《唐宋八大家类选·卷十》：前后将「始得」二字，极力翻剔。盖不尔，则为「西山宴游记」五字题也。可见作文，凡题中虚处，必不可轻易放过。其笔力矫拔，故是河东本来能事。
沈德潜《唐宋八家文读本·卷九》：从「始得」字着意，人皆知之。苍劲秀削，一归元化，人巧既尽，浑然天工矣。此篇领起后诸小记。
林云铭《古文析义·卷十三》：全在「始得」二字着笔。语语指划如画。千载以下，读之如置身于其际。非得游中三昧，不能道只字。」
浦起龙《古文眉诠·卷五十三》：「「始得」有惊喜意，得而宴游，且有快足意，此扼题眼法也。
林纾《古文辞类纂选本·卷九》：此篇极写山之状态，细按似属悔过之言。子厚负其才，急欲自见，故失身而党叔文。既为谬人，以山水放，何必「惴慄」？知「惴慄」，则知过矣……未始知山，即未始知「道」也，斫莽焚茅，除旧染之污也。穷山之高，造「道」深也。然后知山之特出，即知「道」之不凡也。不与培楼为类，是知「道」后远去群小也。悠悠者，知「道」之无涯也。洋洋者，抱「道」之真体也。无所见犹不欲归，知「道」之可乐，恨已往之未见也。于是乎始，自明其投足之正……全是描写山水，点眼处在「惴慄」、「其隙」四字，此虽鄙人臆断，然亦不能无似。', 'indent', 1362606982, '57b972dd165abd0054c3ef2b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10202, '道德经（第四十一章）', NULL, 217, 81, 1, 1, '老子', NULL, 10006, '57b9028d5bbb50005b783385', '周', 'wen', '文', 'http://baike.baidu.com/view/9647230.htm', '', '上士闻道，勤而行之；中士闻道，若存若亡；下士闻道，大笑之。不笑不足以为道。故建言有之：明道若昧；进道若退；夷道若颣；上德若谷；广德若不足；建德若偷；质真若渝；大白若辱；大方无隅；大器晚成；大音希声；大象无形；道隐无名。夫唯道，善贷且成。', '本章前面先讲了「上士」、「中士」、「下士」对道的反映。「上士」即高明的小奴隶主贵族，「中士」即平庸的贵族，「下士」即浅薄的贵族。上、中、下不是就政治上的等级制度而言，而是就其思想认识水平的高低而言。「道」的本质隐藏在现象后面，浅薄之士是无法看到的，所以不被嘲笑那就不足以成其为「道」了。在后面所引的十二句成语中，前六句是指「道」、「德」而言的。后六句的「质真」、「大白」、「大方」、「大器」、「大音」、「大象」指「道」或道的形象，或道的性质。所以引完这十二句格言以后，用一句话加以归纳：「道」是幽隐无名的，它的本质是前者，而表象是后者。这十二句，从有形与无形、存在与意识、自然与社会各个领域多种事物的本质和现象中，论证了矛盾的普遍性，揭示出辩证法的真谛。这是极富智慧的。', '建言：立言。
夷道若纇（lèi）：平坦的道好似崎岖。夷，平坦；纇，崎岖不平、坎坷曲折。
建德若偷：刚健的德好像怠惰的样子。偷，意为惰。
质真若渝：质朴而纯真好像浑浊。渝，变污。
大白若辱：最洁白的东西反而含有污垢。辱，黑垢。
大方无隅：最方整的东西却没有角。隅，角落、墙角。
「夫唯道，善贷且成」：道使万物善始善终，而万物自始至终也离不开道。贷，施与、给予。引伸为帮助、辅助之意。', '上等资质的人听到「道」，能彻底领悟「道」的深意，并且勤而不懈地身体力行。中等资质的人听到「道」，不能彻底领悟而表现出似懂非懂、将信将疑，进而也不会身体力行。下等资质的人听到「道」，完全无法领悟「道」，而觉得「道」是难以置信的，甚至是荒诞，以至于放声讥笑。（因为真正的「道」是无法言说的，且不易被普通人所理解的，）那种不被尚未悟道的人所嘲笑的「道」，其实就根本不是真正的「道」。因此古代建言立论的人就说过这样的话：真正领悟「道」的人，不再为名利所羁绊，在世俗看来，状若愚痴；在「道」上获得精进的人，消除私欲，事事後于人，在世俗看来，反而是退化了；这种看似平坦的「道」，要在世俗中领悟和修习，却是艰难万分。德心高于天下者，虚怀若谷；德泽披于天下者，功成不居；德行立于天下者，戒慎恐惧；德风施于天下者，虚空无欲。真正的「道」是无所不包的，就如同最纯洁的东西可以包容一切污浊而不被其染；真正的「道」是没有边际的，就如同无限的方形没有四角的；真正的「道」是能够经受得住时间的长期考验，就如同大的器皿是经历费时且繁杂的工艺才能制成；真正的「道」也是听觉和视觉所感知不到，就如同世间那些超过人类感知极限的声音和具象。真正的「道」就客观存在于这样无法被感知的无形世界中。只有「道」，才能使万物善始善终，而万物自始至终也离不开「道」。', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a700a677602a202fe2ba", "shortContent": "大器晚成”之涵义，在现代汉语中是指贵重的器物需长期的雕琢才能制成，引申为真正的大才往往成就较晚。\n\n然此成语原出于《老子·四十一章》：“大方无隅，大器晚成，大音希声，大象无形。”陈柱云：“晚者，免之借。免成犹无成，与上文之无隅，下文之希声，无形一例。无隅与大方相反，希声与大音相反，无形与大象相反，故知免成与大器相反。晚借为免，义通于无”（陈柱《老子集训》）。由此，“大器晚成”乃“至大之器无形体”之...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fbe43cd12b001c6d1f33c", "bookTitle": "老子鉴赏辞典", "articleId": "646d84517da2f75ac70ccd18", "shortContent": "本章老子承上章“反者，‘道’之动”而讲到道和德与物相反十二事，如“明道若昧”“建德若偷”；再由道之微妙玄奥讲到各种人对“道”的理解与态度：“上士闻道勤而行之，中士闻道若存若亡，下士闻道大笑之”。最后老子讲到只有隐于无的“道”才能善辅万物。\n对于本章之旨，吴澄说道：“此详言上章反者道之动也……建言有之以下十二事，皆道之与物相反者也。”这十二事就是本章中自“明道若昧”至“大象无形”的十二句古代成语，按...", "authors": ["刘康德"], "pressName": "上海辞书出版社"}, {"bookId": "645fbe43cd12b001c6d1f33c", "bookTitle": "老子鉴赏辞典", "articleId": "646dffa245e4710056ebe75d", "shortContent": "“大器晚成”之涵义，在现代汉语中是指贵重的器物需长期的雕琢才能制成，引申为真正的大才往往成功较晚。\n然此成语原出于《四十一章》:“大方无隅，大器晚成，大音希声，大象无形。”陈柱云：“晚者，免之借。免成犹无成，与上文之无隅，下文之希声、无形一例。无隅与大方相反，希声与大音相反，无形与大象相反，故知免成与大器相反。晚借为免，义通于无”（陈柱《老子集训》）。由此，“大器晚成”乃“至大之器无形体”之义。\n...", "authors": ["张榕坤"], "pressName": "上海辞书出版社"}]', '', 'indent', 1423169692, '57b90a8d128fe10054c9d747', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10208, '梦游天姥吟留别', NULL, 1743, 1052, 6, 6, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155413.htm', '', '海客谈瀛洲，烟涛微茫信难求；越人语天姥，云霞明灭或可睹。天姥连天向天横，势拔五岳掩赤城。天台四万八千丈，对此欲倒东南倾。
我欲因之梦吴越，一夜飞度镜湖月。湖月照我影，送我至剡溪。谢公宿处今尚在，渌水荡漾清猿啼。脚著谢公屐，身登青云梯。半壁见海日，空中闻天鸡。千岩万转路不定，迷花倚石忽已暝。熊咆龙吟殷岩泉，栗深林兮惊层巅。云青青兮欲雨，水澹澹兮生烟。列缺霹雳，丘峦崩摧。洞天石扉，訇然中开。青冥浩荡不见底，日月照耀金银台。霓为衣兮风为马，云之君兮纷纷而来下。虎鼓瑟兮鸾回车，仙之人兮列如麻。忽魂悸以魄动，恍惊起而长嗟。惟觉时之枕席，失向来之烟霞。
世间行乐亦如此，古来万事东流水。别君去兮何时还？且放白鹿青崖间，须行即骑访名山。安能摧眉折腰事权贵，使我不得开心颜！', '《梦游天姥吟留别》又名《别东鲁诸公》，是唐代著名诗人李白创作的一首古体诗。这是一首记梦诗，也是游仙诗。诗写梦游仙府名山，着意奇特，构思精密，意境雄伟。感慨深沉激烈，变化惝恍莫测于虚无飘渺的描述中，寄寓着生活现实。虽离奇，但不做作。内容丰富曲折，形象辉煌流丽，富有浪漫主义色彩。形式上杂言相间，兼用骚体，不受律束，体制解放。信手写来，笔随兴至，诗才横溢，堪称绝世名作。', '天姥山：在浙江新昌东面。传说登山的人能听到仙人天姥唱歌的声音，山因此得名。
瀛洲：古代传说中的东海三座仙山之一（另两座叫蓬莱和方丈）。
烟涛：波涛渺茫，远看像烟雾笼罩的样子。
微茫：景象模糊不清。
信：确实，实在。
越人：指浙江一带的人。
云霞：彩云，彩霞。一作“云霓”。明灭：忽明忽暗。指天姥山在云彩中时隐时现。
明灭：忽明忽暗。
天横：古星名。即天潢。《汉书·天文志》：「王梁策马，车骑满野。旁有八星，絶汉，曰天横。」《史记·天官书》：「王良策马，车骑满野。旁有八星，絶汉，曰天潢。」《晋书·天文志上》：「三柱一曰三泉……其中五星曰天潢。」
拔：超出。
五岳：指东岳泰山、西岳华（huà）山、中岳嵩山、北岳恒山、南岳衡山。
赤城：和下文的「天台（tāi）」都是山名，在今浙江天台北部。
「势拔五岳掩赤城」句：山势高过五岳，遮掩了赤城。
四万八千丈：一作「一万八千丈」。
对此欲倒东南倾「句」：对着天姥这座山，天台山就好像要倒向它的东南一样。意思是天台山和天姥山相比，显得低多了。
因：依据。
之：指代前边越人的话。
镜湖：又名鉴湖，在浙江绍兴南面。
剡（shàn）溪：水名，在浙江嵊（shèng）州南面。
谢公：指南朝诗人谢灵运。谢灵运喜欢游山。游天姥山时，他曾在剡溪这个地方住宿。
渌（lù）：清。
清：这里是凄清的意思。
谢公屐（jī）：谢灵运穿的那种木屐。《南史·谢灵运传》记载：谢灵运游山，必到幽深高峻的地方；他备有一种特制的木屐，屐底装有活动的齿，上山时去掉前齿，下山时去掉后齿。木屐，以木板作底，上面有带子，形状像拖鞋。
著：一说“着”
青云梯：指直上云霄的山路。
半壁见海日：上到半山腰就看到从海上升起的太阳。
天鸡：古代传说，东南有桃都山，山上有棵大树叫桃都，树枝绵延三千里，树上栖有天鸡，每当太阳初升，照到这棵树上，天鸡就叫起来，天下的鸡也都跟着它叫。
「迷花倚石忽已暝（míng）」句：迷恋着花，依靠着石，不觉天色已经很晚了。暝，日落、天黑。
「熊咆龙吟殷岩泉」句：熊在怒吼，龙在长鸣，岩中的泉水在震响。「殷岩泉」即「岩泉殷」。殷，这里用作动词，震响。
「栗深林兮惊层巅」句：使深林战栗，使层巅震惊。栗、惊，使动用法。
青青：黑沉沉的。
澹澹：波浪起伏的样子。
列缺：指闪电。
「洞天石扉，訇（hōng）然中开」句：仙府的石门，訇的一声从中间打开。洞天，仙人居住的洞府。扉，门扇；訇然，形容声音很大。
青冥：指天空。
浩荡：广阔远大的样子。
金银台：金银铸成的宫阙，指神仙居住的地方。
云之君：云里的神仙。
鸾回车：鸾鸟驾着车。鸾，传说中的如凤凰一类的神鸟；回，旋转，运转。
恍：恍然，猛然。
觉时：醒时。
「失向来之烟霞」句：刚才梦中所见的烟雾云霞消失了。向来，觉醒以前；烟霞，指前面所写的仙境。
东流水：像东流的水一样一去不复返。
「且放白鹿青崖间，须行即骑访名山」句：暂且把白鹿放在青青的山崖间，等到要行走的时候就骑上它去访问名山。白鹿，传说神仙或隐士多骑白鹿；须，等待。
摧眉折腰：低头弯腰。摧眉，即低眉。', '海外来客们谈起瀛洲，烟波渺茫实在难以寻求。越中来人说起天姥山，在云雾忽明忽暗间有人可以看见。天姥山仿佛连接着天遮断了天空。山势高峻超过五岳，遮掩过赤城山。天台山虽高四万八千丈，面对着它好像要向东南倾斜拜倒一样。
我根据越人说的话梦游到吴越，一天夜晚飞渡过明月映照下的镜湖。镜湖上的月光照着我的影子，一直伴随我到了剡溪。谢灵运住的地方如今还在，清澈的湖水荡漾，猿猴清啼。我脚上穿着谢公当年特制的木鞋，攀登直上云霄的山路。上到半山腰就看见了从海上升起的太阳，在半空中传来天鸡报晓的叫声。无数山岩重叠，道路盘旋弯曲，方向不定，迷恋着花，依倚着石头，不觉天色已经晚了。熊在怒吼，龙在长鸣，岩中的泉水在震响，使森林战栗，使山峰惊颤。云层黑沉沉的，像是要下雨，水波动荡生起了烟雾。电光闪闪，雷声轰鸣，山峰好像要被崩塌似的。仙府的石门，訇的一声从中间打开。洞中蔚蓝的天空广阔无际，看不到尽头，日月照耀着金银做的宫阙。用彩虹做衣裳，将风作为马来乘，云中的神仙们纷纷下来。老虎弹奏着琴瑟，鸾鸟驾着车。仙人们成群结队密密如麻。忽然魂魄惊动，我猛然惊醒，不禁长声叹息。醒来时只有身边的枕席，刚才梦中所见的烟雾云霞全都消失了。
人世间的欢乐也是像梦中的幻境这样，自古以来万事都像东流的水一样一去不复返。告别诸位朋友远去（东鲁）啊，什么时候才能回来？暂且把白鹿放牧在青崖间，等到要远行时就骑上它访名山。岂能卑躬屈膝去侍奉权贵，使我不能有舒心畅意的笑颜！', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929e911759740c9b1a3a", "shortContent": "这是一首记梦诗，也是一首游仙诗。意境雄伟，变化惝恍莫测，缤纷多彩的艺术形象，新奇的表现手法，向来为人传诵，被视为李白的代表作之一。\n这首诗的题目一作《别东鲁诸公》，作于出翰林之后。天宝三载（744），李白被唐玄宗赐金放还，这是李白政治上的一次大失败。离长安后，曾与杜甫、高適游梁、宋、齐、鲁，又在东鲁家中居住过一个时期。这时东鲁的家已颇具规模，尽可在家中怡情养性，以度时光。可是李白没有这么做，他有一...", "authors": ["乔象钟"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac821a74606fc40940", "shortContent": "这是一首记梦诗，也是一首游仙诗。意境雄伟，变化惝恍莫测，缤纷多彩的艺术形象，新奇的表现手法，向来为人传诵，被视为李白的代表作之一。\n\n这首诗的题目一作《别东鲁诸公》，作于出翰林之后。天宝三载（744），李白被唐玄宗赐金放还，这是李白政治上的一次大失败。离长安后，曾与杜甫、高适游梁、宋、齐、鲁，又在东鲁家中居住过一个时期。这时东鲁的家已颇具规模，尽可在家中怡情养性，以度时光。可是李白没有这么做，他有...", "authors": ["乔象钟"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0cf", "shortContent": "李白说，他“五岳寻仙不辞远，一生好入名山游”（《庐山谣寄卢侍御虚舟》）。经常听海外归来的人谈起海上仙境，令他无限神往；从越州来的人，谈到家乡的美景也如数家珍，称赞他们的天姥山掩映在浮云霓霞之中，不输仙境，也让他兴致盎然。但瀛洲那样的仙山缥缈神秘，隐藏在万顷碧波之中，可遇而不可寻求，不如到天姥山寻幽探胜。天姥山有多高呢？越人这样崇拜它，想必应该是耸立云霄，横跨天宇。在它面前，雄伟的五岳相形见绌，奇丽...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127052c305cf0801816f5c", "shortContent": "李白说，他“五岳寻仙不辞远，一生好入名山游”（《庐山谣寄卢侍御虚舟》），经常听海外归来的人谈起海上仙境，令他无限神往；从越州来的人，谈到家乡的美景也如数家珍，称赞他们的天姥山掩映在浮云丽霓之中，不输仙境，也让他兴致盎然。但瀛洲那样的仙山缥渺神秘，隐藏在万顷碧波之中，可遇而不可寻求，不如到天姥山寻幽探胜。天姥山有多高呢？越人这样崇拜它，想必应该是耸立云霄，横跨天宇，在它面前，雄伟的五岳相形见绌，奇丽...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270a5e6f69b71e93f6329", "shortContent": "李白说，他“五岳寻仙不辞远，一生好入名山游”（《庐山谣寄卢侍御虚舟》），经常听海外归来的人谈起海上仙境，令他无限神往；从越州来的人，谈到家乡的美景也如数家珍，称赞他们的天姥山掩映在浮云丽霓之中，不输仙境，也让他兴致盎然。但瀛洲那样的仙山缥缈神秘，隐藏在万顷碧波之中，可遇而不可寻求，不如到天姥山寻幽探胜。天姥山有多高呢？越人这样崇拜它，想必应该是耸立云霄，横跨天宇，在它面前，雄伟的五岳相形见绌，奇丽...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "646701b35b7b0d4f451a99b1", "shortContent": "这是一首记梦诗，也是一首游仙诗。意境雄伟，变化惝恍莫测，缤纷多彩的艺术形象，新奇的表现手法，向来为人传诵，被视为李白的代表作之一。\n\n这首诗的题目一作《别东鲁诸公》，作于出翰林之后。天宝三载（744），李白被唐玄宗赐金放还，这是李白政治上的一次大失败。离长安后，曾与杜甫、高適游梁、宋、齐、鲁，又在东鲁家中居住过一个时期。这时东鲁的家已颇具规模，尽可在家中怡情养性，以度时光。可是李白没有这么做，他有...", "authors": ["乔象钟"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f2d48b6a81d0c531ffc81", "shortContent": "这是一首记梦诗，也是一首游仙诗。意境雄伟，变化惝恍莫测，缤纷多彩的艺术形象，新奇的表现手法，向来为人传诵，被视为李白的代表作之一。\n这首诗的题目一作《别东鲁诸公》，作于出翰林之后。天宝三载(744)，李白被唐玄宗赐金放还，这是李白政治上的一次大失败。离长安后，曾与杜甫、高適游梁、宋、齐、鲁，又在东鲁家中居住过一个时期。这时东鲁的家已颇具规模，尽可在家中怡情养性，以度时光。可是李白没有这么做，他有一...", "authors": ["乔象钟"], "pressName": "上海辞书出版社"}]', '《唐诗品汇》：范云：瀛洲难求而不必求，天姥可睹而实未睹，故欲因梦而睹之耳（「海客」四句下）。甚显（「半壁」二句下）。甚晦（「千岩万转」二句下）。又甚显（「洞天」四句下）。又甚晦（「霓为衣兮」四句下）。范云：「梦吴越」以下，梦之源也；次诸节，梦之波澜。其间显而晦，晦而显，至「失向来之烟霞」极而与人接矣，非太白之胸次、笔力，亦不能发此。「枕席」、「烟霞」二句最有力。结语平衍，亦文势之当如此也。
《批点唐诗正声》：《梦游无姥吟》胸次皆烟霞云石，无分毫尘浊，别是一副言语，故特为难到。
《增订评注唐诗正声》：郭云：恍恍惚惚，奇奇幻幻，非满肚皮烟霞，决挥洒木出。
《李杜诗选》：桂曰：骚语奇奇怪怪。
《唐诗选脉会通评林》：周珽曰：出于千丝铁网之思，运以百色流苏之局，忽而飞步凌顶，忽而烟云自舒。想其拈笔时，神魂毛发尽脱于毫楮而不自知，其神耶！吴山民曰：「天台四万八千丈」，形容语，「白发三千丈」同意，有形容天姥高意。「千岩万转」句，语有概括。下三句，梦中危景。又八句，梦中奇景。又四句，梦中所遇。「唯觉时之枕席」二语，篇中神句，结上启下。「世间行乐」二句，因梦生意。结超。
《增订唐诗摘钞》：「忽魂」四句，束上生下，笔意最紧。万斛之舟，收于一柁（末二句下）。
《唐诗别裁》：「飞渡镜湖月」以下，皆言梦中所历。一路离奇灭没，恍恍惚惚，是梦境，是仙境（「列缺霹雳」十二句下）。托言梦游，穷形尽相以极「洞天」之奇幻；至酲后，顿失烟霞矣。知世间行乐，亦同一梦，安能于梦中屈身权贵乎？吾当别去，遍游名山，以终天年也。诗境虽奇，脉理极细。
《唐宋诗醇》：七古歌行，本出楚骚、乐府。至于太白，然后穷极笔力，优入圣域。昔人谓其「以气为主，以自然为宗，以俊逸高畅为贵，咏之使人飘飘欲仙」，而尤推其《天姥吟》、《远别离》等篇，以为虽子美不能道。盖其才横绝一世，故兴会标举，非学可及，正不必执此谓子美不能及也。此篇夭矫离奇，不可方物，然因语而梦，因梦而悟，因悟而别，节次柑生，丝毫不乱；若中间梦境迷离，不过词意伟怪耳。胡应麟以为「无首无尾，窈冥昏默」，是真不可以说梦也特谓非其才力，学之立见踬踣，则诚然耳。
《赵秋谷所传声调谱》：方纲按：《扶风豪士歌》、《梦游天姥吟》二篇，虽句法、音节极其变化，然实皆自然入拍，非任意参错也。秋谷于《豪士》篇但评其神变，于《天姥》篇则第云「观此知转韵元无定格」，正恐难以示后学耳。
《网师园唐诗笺》：纵横变化，离奇光怪，以奇笔写梦境，吐句皆仙，着纸谷飞（「列缺霹雳」十句下）。砉然收勒，通体宗主攸在，线索都灵（「世间行乐」二句下）。
《昭昧詹言》：陪起，令人迷。「我欲」以下正叙梦，愈唱愈高，愈出愈奇「失向」句，收住。「世间」二句，入作意，因梦游推开，见世事皆成虚幻也；不如此，则作诗之旨无归宿。留别意，只末后一点。韩《记梦》之本。
《老生常谈》：《梦游天姥吟留别》诗，奇离惝恍，似无门径可寻。细玩之，起首入梦不突，后幅出梦不竭，极恣肆幻化之中，又极经营惨淡之苦，若只貌其右句字面，则失之远矣。一起淡淡引入，至「我欲因之梦吴越」句，乘势即入，使笔如风，所谓缓则按辔徐行，急则短兵相接也。「湖月照我影」八句，他人捉笔可云已尽能事矣，岂料后边尚有许多奇奇怪怪。「千岩万转」二句，用仄韵一束以下至「仙之人兮」句，转韵不转气，全以笔力驱驾，遂成鞭山倒海之能，读云似未曾转韵者，有真气行乎其间也。此妙可心悟，不可言喻。出梦时，用「忽动悸以魄动」四句，似亦可以收煞得住，试想若不再足「世间行乐」二句，非但叫题不酲，抑亦尚欠圆满。「且放白鹿」二句，一纵一收，用笔灵妙不测。后来慢东坡解此法，他人多昧昧耳。
《李太白诗醇》：严云：「半壁」一句，不独境界超绝，语音亦复高朗。严云：有意味在「青青」、「澹澹」字作叠（「云青青兮」二句下）。严云：太白写仙人境界皆渺茫寂历，独此一段极真，极雄，反不似梦中语（「霓为衣兮」四句下）。又云：「世间」云云，甚达，甚警策，然自是唐人语，无宋气。', 'indent', 1413451372, '57b3178f165abd00543a480d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10209, '月下独酌四首', NULL, 2846, 1052, 4, 11, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/1367368.htm', '', '【其一】
花间一壶酒，独酌无相亲。
举杯邀明月，对影成三人。
月既不解饮，影徒随我身。
暂伴月将影，行乐须及春。
我歌月徘徊，我舞影零乱。
醒时同交欢，醉后各分散。
永结无情游，相期邈云汉。
【其二】
天若不爱酒，酒星不在天。
地若不爱酒，地应无酒泉。
天地既爱酒，爱酒不愧天。
已闻清比圣，复道浊如贤。
贤圣既已饮，何必求神仙。
三杯通大道，一斗合自然。
但得酒中趣，勿为醒者传。
【其三】
三月咸阳城，千花昼如锦。
谁能春独愁，对此径须饮。
穷通与修短，造化夙所禀。
一樽齐死生，万事固难审。
醉后失天地，兀然就孤枕。
不知有吾身，此乐最为甚。
【其四】
穷愁千万端，美酒三百杯。
愁多酒虽少，酒倾愁不来。
所以知酒圣，酒酣心自开。
辞粟卧首阳，屡空饥颜回。
当代不乐饮，虚名安用哉。
蟹螯即金液，糟丘是蓬莱。
且须饮美酒，乘月醉高台。', '《月下独酌四首》是唐代诗人李白的组诗作品。这四首诗写诗人在月夜花下独酌，无人亲近的冷落情景。诗意表明，诗人心中愁闷，遂以月为友，对酒当歌，及时行乐。诗人运用丰富的想象，表达出由孤独到不孤独，再由不孤独到孤独的一种复杂感情。表面看来，诗人真能自得其乐，可是深处却有无限的凄凉。全诗笔触细腻，构思奇特，体现了诗人怀才不遇的寂寞和孤傲，在失意中依然旷达乐观、放浪形骸、狂荡不羁的豪放个性。', '独酌：一个人饮酒。酌，饮酒。
间：一作「下」，一作「前」。
无相亲：没有亲近的人。
「举杯邀明月，对影成三人」句：我举起酒杯招引明月共饮，明月和我以及我的影子恰恰合成三人。一说月下人影、酒中人影和我为三人。
既：已经。
不解：不懂，不理解。三国魏·嵇康《琴赋》：「推其所由，似元不解音声。」
徒：徒然，白白的。徒，空。
将：和、共。
及春：趁着春光明媚之时。
月徘徊：明月随我来回移动。
影零乱：因起舞而身影纷乱。
同交欢：一作「相交欢」，一起欢乐。。
无情游：月、影没有知觉，不懂感情，李白与之结交，故称「无情游」。
相期邈（miǎo）云汉：约定在天上相见。期，约会；邈，遥远；云汉，银河，这里指遥天仙境。邈云汉，一作「碧岩畔」。
酒星：古星名。也称酒旗星。《晋书·天文志》：「轩辕右角南三星曰酒旗，酒官之旗也，主享宴酒食。」汉·孔融《与曹操论酒禁书》：「天垂酒星之耀，地列酒泉之郡，人著旨酒之德。」
酒泉：酒泉郡，汉置。传说郡中有泉，其味如酒，故名酒泉。在今甘肃省酒泉市。
大道：指自然法则。《庄子·天下》：「天能覆之而不能载之，地能载之而不能覆之，大道能包之而不能辩之，知万物皆有所可，有所不可。」
酒中趣：饮酒的乐趣。晋·陶潜《晋故征西大将军长史孟府君传》：「温（桓温）尝问君：‘酒有何好，而卿嗜之？’君笑而答曰：‘明公但不得酒中趣尔。’」
「三月咸阳城，千花昼如锦」句：一作「好鸟吟清风，落花散如锦」；一作「园鸟语成歌，庭花笑如锦」。咸阳城，此指长安城；城，一作「时」。
径须：直须。李白《将进酒》诗：「主人何为言少钱，径须沽取对君酌。」
穷通：困厄与显达。《庄子·让王》：「古之得道者，穷亦乐，通亦乐，所乐非穷通也；道德于此，则穷通为寒暑风雨之序矣。」
修短：长短，指人的寿命。《汉书·谷永传》：「加以功德有厚薄，期质有修短，时世有中季，天道有盛衰。」
造化：自然界的创造者。亦指自然。《庄子·大宗师》：「今一以天地为大炉，以造化为大冶，恶乎往而不可哉？」
齐死生：生与死没有差别。
兀然：昏然无知的样子。
孤枕：独枕，借指独宿、独眠。唐李商隐《戏赠张书记》诗：「别馆君孤枕，空庭我闭关。」
穷愁：穷困愁苦。《史记·平原君虞卿列传论》：「然虞卿非穷愁，亦不能著书以自见于后世云。」
千万端：一作「有千端」。
三百杯：一作「唯数杯」。
酒圣：谓豪饮的人。宋曾巩《招泽甫竹亭闲话》诗：「诗豪已分材难强，酒圣还谙量未宽。」
卧首阳：一作「饿伯夷」。首阳，山名，一称雷首山，相传为伯夷、叔齐采薇隐居处。
屡空：经常贫困，谓贫穷无财。《论语·先进》：「回也其庶乎！屡空。」何晏集解：「言回庶几圣道，虽数空匮而乐在其中。」颜回，春秋末期鲁国人，孔子的得意门生。
乐饮：畅饮。《史记·高祖本纪》：「沛父兄诸母故人日乐饮极驩，道旧故为笑乐。」
安用：有什么作用。安，什么。
蟹螯（áo）：螃蟹变形的第一对脚。状似钳，用以取食或自卫。《晋书·毕卓传》：「右手持酒杯，左手持蟹螯，拍浮酒船中，便足了一生矣。」
金液：喻美酒。唐·白居易《游宝称寺》诗：「酒懒倾金液，茶新碾玉尘。」
糟丘：积糟成丘。极言酿酒之多，沉湎之甚。《尸子·卷下》：「六马登糟丘，方舟泛酒池。」
蓬莱：古代传说中的神山名。此处泛指仙境。
乘月：趁着月光。《乐府诗集·清商曲辞一·子夜四时歌夏歌一》：「乘月采芙蓉，夜夜得莲子。」', '【其一】
花丛中摆下一壶好酒，无相知作陪独自酌饮。举杯邀请明月来共饮，加自己身影正好三人。月亮本来就不懂饮酒，影子徒然在身前身后。暂且以明月影子相伴，趁着春光美景及时行乐。我唱歌月亮徘徊不定，我起舞影子飘前飘后。清醒时我们共同欢乐，酒醉以后各奔东西。我愿与他们永远结下忘掉伤情的友谊，相约在缥缈的银河边。
【其二】
天如果不爱酒，酒星就不能罗列在天。地如果不爱酒，就不应该地名有酒泉。天地既然都喜爱酒，那我爱酒就无愧于天。我先是听说酒清比作圣，又听说酒浊比作贤。既然圣贤都饮酒，又何必再去求神仙？三杯酒可通儒家的大道，一斗酒正合道家的自然。我只管得到醉中的趣味，这趣味不能向醒者相传！
【其三】
三月里的长安城，春光明媚，春花似锦。谁能如我春来独愁，到此美景只知一味狂饮？富贫与长寿，本来就造化不同，各有天分。酒杯之中自然死生没有差别，何况世上的万事根本没有是非定论。醉后失去了天和地，一头扎向了孤枕。沉醉之中不知还有自己，这种快乐何处能寻？
【其四】
无穷的忧愁有千头万绪，我有美酒三百杯多，美酒一倾愁不再回。因此我才了解酒中圣贤，即使酒少愁多，酒酣心自开朗。伯夷和叔齐二人不食周粟饿死于首阳山，没有酒食颜回也受饥。当代不乐于饮酒，虚名有什么用呢？蟹螯就是仙药金液，糟丘就是仙山蓬莱。姑且先饮一番美酒，乘着月色在高台上大醉一回。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a103048e64fbd91365", "shortContent": "佛教中有所谓“立一义”，随即“破一义”，“破”后又“立”，“立”后又“破”，最后得到究竟辨析方法。用现代话来说，就是先讲一番道理，经驳斥后又建立新的理论，再驳再建，最后得到正确的结论。关于这样的论证，一般总有双方，相互“破”、“立”。可是李白这首诗，就只一个人，以独白的形式，自立自破，自破自立，诗情波澜起伏而又纯乎天籁，所以一直为后人传诵。\n诗人上场时，背景是花间，道具是一壶酒，登场角色只是他自己...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d10b", "shortContent": "佛教中有所谓“立一义”，随即“破一义”，“破”后又“立”，“立”后又“破”，最后得到究竟辨析方法。用现代话来说，就是先讲一番道理，经驳斥后又建立新的理论，再驳再建，最后得到正确的结论。关于这样的论证，一般总有双方，相互“破”“立”。可是李白这首诗，就只一个人，以独白的形式，自立自破，自破自立，诗情波澜起伏而又纯乎天籁，所以一直为后人传诵。\n\n诗人上场时，背景是花间，道具是一壶酒，登场角色只是他自己...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d91", "shortContent": "“花间一壶酒，独酌无相亲。举杯邀明月，对影成三人。”一壶酒，一个人，一明月，一孤影。好似台上一出戏，眉目之间便道尽了悲欢离合。手持一壶梨花白，独自徘徊这繁花碎影之间，举杯邀请那明月共饮，低头才发现携着影子成了三人同欢。李白总是能从那简单的景色之中，提炼出令人心神向往的梦境。真真假假、虚虚实实间，让你分不清现实与梦幻，但亦心甘情愿沉沦。李白在抬头低头之间，将孤独化为了不孤。\n\n从逻辑上讲，物与人的内...", "authors": ["孟佳"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312704d73206168b2e021e1", "shortContent": "“花间一壶酒，独酌无相亲。举杯邀明月，对影成三人。”一壶酒，一个人，一明月，一孤影。好似台上一出戏，眉目之间便道尽了悲欢离合。手持一壶梨花白，独自徘徊这繁花碎影之间，举杯邀请那明月共饮，低头才发现携着影子成了三人同欢。李白总是能从那简单的景色之中，提炼出令人心神向往的梦境。真真假假、虚虚实实间，让你分不清现实与梦幻，但亦心甘情愿沉沦。李白在抬头低头之间，将孤独化为了不孤。\n\n从逻辑上讲，物与人的内...", "authors": ["孟佳"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127078f2af4e09d55b67a3", "shortContent": "“花间一壶酒，独酌无相亲。举杯邀明月，对影成三人。”一壶酒，一个人，一明月，一孤影。好似台上一出戏，眉目之间便道尽了悲欢离合。手持一壶梨花白，独自徘徊这繁花碎影之间，举杯邀请那明月共饮，低头才发现携着影子成了三人同欢。李白总是能从那简单的景色之中，提炼出令人心神向往的梦境。真真假假、虚虚实实间，让你分不清现实与梦幻，但亦心甘情愿沉沦。李白在抬头低头之间，将孤独化为了不孤。\n\n从逻辑上讲，物与人的内...", "authors": ["孟佳"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6467687630675327e194dde0", "shortContent": "佛教中有所谓“立一义”，随即“破一义”，“破”后又“立”，“立”后又“破”，最后得到究竟的辩析方法。用现代话来说，就是先讲一番道理，经驳斥后又建立新的理论，再驳再建，最后得到正确的结论。关于这样的论证，一般总有双方，相互“破”、“立”。可是李白这首诗，就只一个人，以独白的形式，自立自破，自破自立，诗情波澜起伏而又纯乎天籁，所以一直为后人传诵。\n\n诗人上场时，背景是花间，道具是一壶酒，登场脚色只是他...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}]', '【其一】
明·高棅《唐诗品汇》：刘云：古无此奇（「对影」句下）。刘云：凡情俗态终以此，安得不为改观（末句下）？
明·锺惺、谭元春《唐诗归》：谭云：奇想，旷想。锺云：放言只中无人。
清·沈德潜《唐诗别裁》：脱口而出，纯乎天籁，此种诗人不易学。
清·李家瑞《停云阁诗话》：李诗「举杯邀明月，对影成三人」，东坡喜其造句之工，屡用之。予读《南史·沈庆之传》，庆之谓人曰：「我每履田园，有人时与马成三，无人则与马成二。」李诗殆本此。然庆之语不及李诗之妙耳。
清高宗敕编《唐宋诗醇》：千古奇趣、从眼前得之。尔时情景，虽复潦倒，终不胜其旷达。陶潜云：「挥杯劝孤影」，白意本此。
清·蘅塘退士《唐诗三百首》：题本独酌，诗偏幻出三人，月影伴说，反复推勘，愈形其独（「举杯」四句下）。
现代傅庚生《中国文学欣赏举隅》：花间有酒，独酌无亲；虽则无亲，邀月与影，乃如三人；虽如三人，月不解饮，影徒随身；虽不解饮，聊可为伴，虽徒随身，亦得相将。及时行乐，春光几何？月徘徊，如听歌；影零乱，如伴舞。醒时虽同欢，醉后各分散；聚时似无情，情深得永结；云汉邈相期，相亲慰独酌。此诗一步一转，愈转愈奇，虽奇而不离其宗。青莲奇才，故能尔尔，恐未必苦修能接耳。
日本近藤元粹《李太白诗醇》：严沧浪曰：饮情之奇。于孤寂时，觅此伴侣，更不须下酒物。且一叹一解，若远若近，开开阖阖，极无情，极有情。如此相期，世间岂复有可「相亲」者耶？
【其二】
清·查慎行《初白庵诗评》：此种语太庸近，疑非太白作。', 'center', 1413388212, '57b8e71d1532bc005b9a77d6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10210, '早发白帝城', NULL, 2049, 1052, 2, 12, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155504.htm', '', '朝辞白帝彩云间，千里江陵一日还。
两岸猿声啼不住，轻舟已过万重山。​', '此诗是唐代伟大诗人李白在流放途中遇赦返回时所创作的一首七言绝句，是李白诗作中流传最广的名篇之一。诗人是把遇赦后愉快的心情和江山的壮丽多姿、顺水行舟的流畅轻快融为一体来表达的。全诗无不夸张和奇想，写得流丽飘逸，惊世骇俗，但又不假雕琢，随心所欲，自然天成。', '发：启程。白帝城：故址在今重庆市奉节县白帝山上。杨齐贤注：“白帝城，公孙述所筑。初，公孙述至鱼复，有白龙出井中，自以承汉土运，故称白帝，改鱼复为白帝城。”王琦注：“白帝城，在夔州奉节县，与巫山相近。所谓彩云，正指巫山之云也。”
朝：早晨。辞：告别。彩云间：因白帝城在白帝山上，地势高耸，从山下江中仰望，仿佛耸入云间。白帝：今四川省奉节县东白帝山，山上有白帝城，位于长江上游。
江陵：今湖北荆州市。从白帝城到江陵约一千二百里，其间包括七百里三峡。郦道元《三峡》：“自三峡七百里中，两岸连山，略无阙处。重岩叠障，隐天蔽日，自非亭午时分，不见曦月。至于夏水襄陵，沿溯（或泝）阻绝。或王命急宣，有时朝发白帝，暮到江陵，其间千二百时里，虽乘奔御风，不以疾也。春冬之时，则素湍绿潭，回清倒影。绝巘（或巚）多生怪柏，悬泉瀑布，飞漱其间。清荣峻茂，良多趣味。每至晴初霜旦，林寒涧肃，常有高猿长啸，属引凄异。空谷传响，哀啭久绝。故渔者歌曰：‘巴东三峡巫峡长，猿鸣三声泪沾裳。’”一日还：一天就可以到达；还：归；返回。
猿：猿猴。啼：鸣、叫。住：停息。
万重山：层层叠叠的山，形容有许多。', '清晨我告别高入云霄的白帝城；江陵远在千里船行只一日时间。
两岸猿声还在耳边不停地啼叫；不知不觉轻舟已穿过万重青山。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a12cee9a0c24ecf895", "shortContent": "唐肃宗乾元二年（759）春天，李白因永王璘案，流放夜郎（治今贵州正安西北），取道四川赴贬地。行至白帝城，忽闻赦书，惊喜交加，旋即放舟东下江陵（治今湖北荆州市），故诗题一作“下江陵”。此诗抒写了当时喜悦畅快的心情。\n首句“彩云间”三字，描写白帝城地势之高，为全篇写下水船走得快这一动态蓄势。不写白帝城之极高，则无法体现出长江上下游之间斜度差距之大。白帝城地势高入云霄，于是下面几句中写舟行之速、行期之短...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d10a", "shortContent": "唐肃宗乾元二年（759）春天，李白因永王璘案，流放夜郎（治今贵州正安西北），取道四川赴贬地。行至白帝城，忽闻赦书，惊喜交加，旋即放舟东下江陵（治今湖北荆州市），故诗题一作“下江陵”。此诗抒写了当时喜悦畅快的心情。\n\n首句“彩云间”三字，描写白帝城地势之高，为全篇写下水船走得快这一动态蓄势。不写白帝城之极高，则无法体现出长江上下游之间斜度差距之大。白帝城地势高入云霄，于是下面几句中写舟行之速、行期之...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f459761253910e903b5", "shortContent": "乾元二年（759），李白因永王李璘事而流放夜郎，行至白帝城而遇赦。故乘船返江陵，行程中他写下这首七绝小诗，记录自己因遇赦而欣喜若狂的心情。此诗又题作《下江陵》。诗中所展示的“洒脱流利”（《唐诗选脉会通评林》引周敬）与畅快心情，在李白诗歌中较为常见。\n \n首句交代诗返回江陵的时间地点，烘托白帝城地势之高峻雄奇。清晨的时候，我告别高入云霄的白帝城，马上要回到江陵去了。“彩云间”三字用得精妙，既是实与，...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6467655830675327e194c9d3", "shortContent": "唐肃宗乾元二年（759）春天，李白因永王璘案，流放夜郎（治今贵州正安西北），取道四川赴贬地。行至白帝城，忽闻赦书，惊喜交加，旋即放舟东下江陵（治今湖北荆州市），故诗题一作“下江陵”。此诗抒写了当时喜悦畅快的心情。\n\n首句“彩云间”三字，描写白帝城地势之高，为全篇写下水船走得快这一动态蓄势。不写白帝城之极高，则无法体现出长江上下游之间斜度差距之大。白帝城地势高入云霄，于是下面几句中写舟行之速、行期之...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f0dfcb6a81d0c531f3b52", "shortContent": "唐肃宗乾元二年(759)春天，李白因永王璘案，流放夜郎（治今贵州正安西北），取道四川赴贬地。行至白帝城，忽闻赦书，惊喜交加，旋即放舟东下江陵（治今湖北荆州市），故诗题一作“下江陵”。此诗抒写了当时喜悦畅快的心情。\n首句“彩云间”三字，描写白帝城地势之高，为全篇写下水船走得快这一动态蓄势。不写白帝城之极高，则无法体现出长江上下游之间斜度差距之大。白帝城地势高入云霄，于是下面几句中写舟行之速、行期之短...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "64732ddd82772d45942c790b", "shortContent": "唐肃宗乾元二年（759）春天，李白因永王璘案，流放夜郎，取道四川赴贬地。行至白帝城，忽闻赦书，惊喜交加，旋即放舟东下江陵，故诗题一作“下江陵”。此诗抒写了当时喜悦畅快的心情。\n\n首句“彩云间”三字，描写白帝城地势之高，为全篇写下水船走得快这一动态蓄势。不写白帝城之极高，则无法体现出长江上下游之间斜度差距之大。白帝城地势高入云霄，于是下面几句中写舟行之速、行期之短、耳（猿声）目（万重山）之不暇迎送，...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "64733de1902ee364cc9a27b6", "shortContent": "唐肃宗乾元二年（759）春天，李白因永王璘案，流放夜郎，取道四川赴贬地。行至白帝城，忽闻赦书，惊喜交加，旋即放舟东下江陵，故诗题一作“下江陵”。此诗抒写了当时喜悦畅快的心情。\n\n首句“彩云间”三字，描写白帝城地势之高，为全篇写下水船走得快这一动态蓄势。不写白帝城之极高，则无法体现出长江上下游之间斜度差距之大。白帝城地势高入云霄，于是下面几句中写舟行之速、行期之短、耳（猿声）目（万重山）之不暇迎送，...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}]', '《批点唐诗正声》：亦有作者，无此声调。此飘逸。
《增订评注唐诗正声》：郭云：“已过”二字，便见瞬息千里，点入猿声，妙，妙。
《升庵诗话》：盛弘之《荆州记》“巫峡江水之迅”云：“朝发白帝，暮到江陵，其间千二百里，虽乘奔御风，不以疾也。”杜子美诗：“朝发白帝暮江陵，顷来目击信有征。”李太白“朝辞白帝彩云间……”虽同用盛弘之语，而优劣自别。今人谓李、杜不可以优劣论，此语亦太愦愦。白帝至江陵，春水盛时，行舟朝发夕至，云飞鸟逝，不是过也。太白述之为韵语，惊风雨而泣鬼神矣。
《唐诗训解》：笔势迅如下峡。
《唐诗选脉会通评林》：周敬曰：脱洒流利，非实历此境说不出。焦竑曰：盛弘之谓白帝至江陵其远，春水盛时行舟，朝发暮至。太白述之为韵语，惊风雨而泣鬼神矣。
《唐风怀》：汉仪曰：境之所到，笔即追之，有声有情，腕疑神助，此真天才也。
《唐诗归》：谭云：忽然，写得出。
《唐诗归折衷》：吴敬大云：只为第二句下注脚耳，然有意境可想（末一句下）。
《唐诗摘钞》：一、二即“朝发白帝，暮宿江陵”语，运用得妙。以后二句证前二句，趣。
《增订唐诗摘钞》：插“猿声”一句，布景着色之法。第三句妙在能缓，第四句妙在能疾。
《唐诗别裁》：写出瞬息千里，若有神助。入“猿声”一句，文势不伤于直。画家布景设色，每于此处用意。
《唐宋诗醇》：顺风扬帆，瞬息千里，但道得眼前景色，便疑笔墨间亦有神助。三、四设色托起，殊觉自在中流。
《网师园唐诗笺》：一片化机（首二句下）。烘托得妙（末二句下）。
《诗法易简录》：通首只写舟行之速，而峡江之险，已历历如绘，可想见其落笔之超。
《唐人万首绝句选评》：读者为之骇极，作者殊不经意，出之似不着一点气力。阮亭推为三唐压卷，信哉！
《札朴》：友人请说太白“朝辞白帝”诗，馥曰：但言舟行快绝耳，初无深意，而妙在第三句，能使通首精神飞越，若无此句，将不得为才人之作矣。晋王廙尝从南下，旦自寻阳，迅风飞帆，暮至都，廙倚舫楼长啸，神气俊逸，李诗即此种风概。
《岘佣说诗》：太白七绝，天才超逸，而神韵随之。如“朝辞白帝彩云间，千里江陵一日还”，如此迅捷，则轻舟之过万山不待言矣。中间却用“两岸猿声啼不住”一句垫之，无此句，则直而无味；有此句，走处仍留、急语仍缓。可悟用笔之妙。
《诗式》：绝句要婉曲回环，删芜就简，句绝而意不绝。大抵以第三句为主，而第四句接之。有实接，有虚接，承接之间，开与合相关，反与正相依，顺与逆相应，一呼一吸。如此诗三句“啼不住”二字，与四句“已过”二字呼应，盖言晓猿啼犹未歇，而轻舟已过万山，状其迅速也。[品]俊迈。
《诗境浅说续编》：四渎之水，惟蜀江最为迅急，以万山紧束，地势复高，江水若建瓴而下，舟行者帆橹不施，疾于飞鸟。自来诗家，无专咏之者、惟太白此作，足以状之。诵其诗，若身在三峡舟中，峰峦城郭，皆掠舰飞驰，诗笔亦一气奔放，如轻舟直下；惟蜀道诗多咏猿啼，李诗亦言两岸猿声。今之蜀江，猿声绝少，闻猱玃皆在深山，不在江畔，盖今昔之不同也。
《唐人绝句精华》：此诗写江行迅速之状，如在目前。而“两岸猿声”句，虽小小景物，插写其中，大足为末句生色。正如太史公于叙事紧迫中，忽入一二闲笔，更令全篇生动有味。而施均父谓此诗“走处仍留，急语仍缓”，乃用笔之妙。', 'center', 1417652106, '57b9272a8ac2470062e0d5be', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (78171, '闲坐', NULL, 76, 2952, 1, 0, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', NULL, NULL, '暖拥红炉火，闲搔白发头。
百年慵里过，万事醉中休。
有室同摩诘，无儿比邓攸。
莫论身在日，身后亦无忧。', NULL, NULL, NULL, NULL, NULL, 'center', 1478997890, '5827470267f356005878f3cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10211, '长干行', NULL, 718, 1052, 2, 4, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3722948.htm', '', '妾发初覆额，折花门前剧。
郎骑竹马来，绕床弄青梅。
同居长干里，两小无嫌猜。
十四为君妇，羞颜未尝开。
低头向暗壁，千唤不一回。
十五始展眉，愿同尘与灰。
常存抱柱信，岂上望夫台。
十六君远行，瞿塘滟滪堆。
五月不可触，猿声天上哀。
门前迟行迹，一一生绿苔。
苔深不能扫，落叶秋风早。
八月蝴蝶黄，双飞西园草。
感此伤妾心，坐愁红颜老。
早晚下三巴，预将书报家。
相迎不道远，直至长风沙。', '这是一首写商妇的爱情和离别的诗。诗以商妇的自白，用缠绵婉转的笔调，抒写了她对远出经商丈夫的真挚的爱和深深的思念。
诗的开头六句是回忆与丈夫孩提时“青梅竹马，两小无猜”的情景，为读者塑了一对少年儿童天真无邪，活泼可爱的形象。“十四为君妇”四句，是细腻地刻画初婚的羞涩，重现了新婚的甜蜜醉人。“十五始展眉”四句，写婚后的热恋和恩爱，山盟海誓，如胶似漆。“十六君远行”四句，写遥思丈夫远行经商，并为之担心受怕，缠绵悱恻，深沉无限。“门前迟行迹”八句，写触景生情，忧思不断，颜容憔悴。最后四句，写寄语亲人，望其早归。把思念之情更推进一步。
全诗形象完整明丽，活泼动人。感情细腻，缠绵婉转；语言坦白，音节和谐；格调清新隽永，是诗歌艺术上品。“青梅竹马”、“两小无猜”，已成描摹幼男幼女天真无邪情谊的佳语。', '长干行：属乐府《杂曲歌辞》调名。下篇一作张潮。黄庭坚作李益诗。《苕溪渔隐丛话》：山谷云：太白集中《长干行》二篇：“妾发初覆额”，真太白作也。“忆妾深闺里”，李益尚书作也。……词意亦清丽可喜，乱之太白诗中，亦不甚远。
床：井栏，后院水井的围栏。
长干里：在今南京市，当年系船民集居之地，故《长干曲》多抒发船家女子的感情。
抱柱信：典出《庄子·盗跖篇》，写尾生与一女子相约于桥下，女子未到而突然涨水，尾生守信而不肯离去，抱着柱子被水淹死。
滟滪（yànyù）堆：三峡之一瞿塘峡峡口的一块大礁石，农历五月涨水没礁，船只易触礁翻沉。
天上哀：哀一作“鸣”。
迟行迹：迟一作“旧”。
生绿苔：绿一作“苍”。
胡蝶黄：一作“胡蝶来”。胡蝶，即蝴蝶。清王琦《李太白文集注》云：“杨升庵谓蝴蝶或白或黑，或五彩皆具，唯黄色一种至秋乃多，盖感金气也，引太白‘八月蝴蝶黄’一句，以为深中物理，而评今本‘来’字为浅。琦谓以文义论字，终以‘来’字为长。”作‘黄’字亦有道理。
早晚：多早晚，犹何时。三巴：地名。即巴郡、巴东、巴西。在今四川东部地区。
长风沙：地名，在今安徽省安庆市的长江边上，距南京约七百里。', '我的头发刚刚盖过额头，便同你一起在门前做折花的游戏。你骑着竹马过来，我们一起绕着井栏，互掷青梅为戏。我们同在长干里居住，两个人从小都没什么猜忌。十四岁时嫁给你作妻子，害羞得没有露出过笑脸。低着头对着墙壁的暗处，一再呼唤也不敢回头。十五岁才舒展眉头，愿意永远和你在一起。常抱着至死不渝的信念，怎么能想到会走上望夫台？十六岁时你离家远行，要去瞿塘峡滟滪堆。五月水涨时，滟滪堆不可相触，两岸猿猴的啼叫声传到天上。门前是你离家时徘徊的足迹，渐渐地长满了绿苔。绿苔太厚，不好清扫，树叶飘落，秋天早早来到。八月里，黄色的蝴蝶飞舞，双双飞到西园草地上。看到这种情景我很伤心，因而忧愁容颜衰老。无论什么时候你想下三巴回家，请预先把家书捎给我。迎接你不怕道路遥远，一直走到长风沙。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929b911759740c9b1a26", "shortContent": "这是一首以商妇的爱情和离别为题材的诗。它以女子自述的口吻，抒写对远出经商的丈夫的怀念。诗用年龄序数法和四季相思的格调，巧妙地把一些生活片断（或女主人公拟想中的生活情景）连缀成完整的艺术整体。\n诗一开始四句，女子回忆童年时与丈夫一起长大，彼此“青梅竹马”、“两小无猜”的情景。“十四为君妇”四句，以极细腻的笔触写初婚时的情景。尽管对方是童年的伙伴，但出嫁时仍然羞涩不堪。“十五始展眉”四句，抒写夫妇间婚...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc40935", "shortContent": "这是一首以商妇的爱情和离别为题材的诗。它以女子自述的口吻，抒写对远出经商的丈夫的怀念。诗用年龄序数法和四季相思的格调，巧妙地把一些生活片断（或女主人公拟想中的生活情景）联缀成完整的艺术整体。\n\n诗一开始四句，女子回忆童年时与丈夫一起长大，彼此“青梅竹马”“两小无猜”的情景。“十四为君妇”四句，以极细腻的笔触写初婚时的情景。尽管对方是童年的伙伴，但出嫁时仍然羞涩不堪。“十五始展眉”四句，抒写夫妇间婚...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1bc305cf0801816db2", "shortContent": "《长干行》本为乐府旧题，属杂曲歌辞，原是长江下游一带的民歌。李白所作有两首，此选第一首，写一商人之妇对入蜀丈夫的思念。\n\n诗篇从女主人公的回忆开始，她与丈夫一起长大，彼此“青梅竹马”、“两小无猜”。小姑娘的头发刚刚能够覆盖住前额的时候，她在自家门前折花嬉戏，未来的丈夫——当初拿着一根细长的竹竿当作高头大马，一路吆喝着跑来的小男孩，就开始进入了她的生活。小女孩把玩着青梅，小男孩跨骑着竹马围绕井栏跑来...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312704d73206168b2e021dd", "shortContent": "《长干行》本为乐府旧题，属杂曲歌辞，原是长江下游一带的民歌。李白所作有两首，此选第一首，写一商人之妇对入蜀丈夫的思念。\n\n诗篇从女主人公的回忆开始，她与丈夫一起长大，彼此“青梅竹马”、“两小无猜”。小姑娘的头发刚刚能够覆盖住前额的时候，她在自家门前折花嬉戏，未来的丈夫——当初拿着一根细长的竹竿当作高头大马，一路吆喝着跑来的小男孩，就开始进入了她的生活。小女孩把玩着青梅，小男孩跨骑着竹马围绕井栏跑来...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6466e3e3c0471b0062d5f5e3", "shortContent": "这是一首以商妇的爱情和离别为题材的诗。它以女子自述的口吻，抒写对远出经商的丈夫的怀念。诗用年龄序数法和四季相思的格调，巧妙地把一些生活片断（或女主人公拟想中的生活情景）联缀成完整的艺术整体。\n\n诗一开始四句，女子回忆童年时与丈夫一起长大，彼此“青梅竹马”、“两小无猜”的情景。“十四为君妇”四句，以极细腻的笔触写初婚时的情景。尽管对方是童年的伙伴，但出嫁时仍然羞涩不堪。“十五始展眉”四句，抒写夫妇间...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}]', '《苕溪渔隐丛话》：山谷云：太白集中《长干行》二篇：“妾发初覆额”，真太白作也。“忆妾深闺里”，李益尚书作也。……词意亦清丽可喜，乱之太白诗中，亦不甚远。
《唐诗归》：钟云：古秀，真汉人乐府。谭云：人负轻捷妍媚之才者，每于换韵疾佻，结句疏宕，太白尤甚。
《唐诗快》：虽是儿女子喁喁，却原带英雄之气，自与他人闺怨不同。
《此木轩论诗汇编》：写他贞信处极其妖邪。句句小家气，方是此题神理。似《西洲曲》（末二句下）。
《唐诗别裁》：“蝴蝶”二句，即所见以感兴（“双飞”句下）。“长风沙”在舒州。金陵至舒州七百余里，言相迎之远也（末二句下）。
《诗法易简录》：此诗音节，深得汉人乐府之遗，当熟玩之。
《历代诗法》：青莲才气，一瞬千里；此篇层析，独有节制。
《唐宋诗醇》：儿女子情事，直从胸臆间流出，萦迁回折，一往情深。尝爰司空图所云“道不自器，与之圆方”、为探得委曲之妙，此篇庶几近之。
《王闿运手批唐诗选》：明艳娇憨，盖有所指。
《唐诗三百首注疏》：二章词意，前后层次，一线贯通，不可折断，直作一首读可也。
《李太白诗醇》：严云：“两小无嫌猜”，极寻常情事，说得出。又云：“低头”云云。盖常情羞生，此却羞又云：“不叮触”、“天上哀”、或迈或远，难为情。', 'center', 1416740030, '57b90833a633bd00665d8580', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10212, '独坐敬亭山', NULL, 2315, 1052, 2, 11, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155467.htm', '', '众鸟高飞尽，孤云独去闲。
相看两不厌，只有敬亭山。', '此诗表面是写独游敬亭山的情趣，而其深含之意则是诗人生命历程中旷世的孤独感。诗人以奇特的想象力和巧妙的构思，赋予山水景物以生命，将敬亭山拟人化，写得十分生动。作者写的是自己的孤独，写的是自己的怀才不遇，但更是自己的坚定，在大自然中寻求安慰和寄托。此诗是诗人表现自己精神世界的佳作。', '敬亭山：在今安徽宣城市北。《元和郡县志》记载：「在宣城县北十里。山有万松亭、虎窥泉。」《江南通志·巻十六·宁国府》：「敬亭山在府城北十里。府志云：古名昭亭，东临宛、句二水，南俯城闉，烟市风帆，极目如画。」
尽：没有了。
孤云：陶渊明《咏贫士诗》中有「孤云独无依」的句子。朱谏注：「言我独坐之时，鸟飞云散，有若无情而不相亲者。独有敬亭之山，长相看而不相厌也。」独去闲：独去，独自去。闲，形容云彩飘来飘去，悠闲自在的样子。孤单的云彩飘来飘去。
两不厌：指诗人和敬亭山而言。厌，满足。
只有：一作“唯有”。', '群鸟高飞无影无踪，孤云独去自在悠闲。
你看我，我看你，彼此之间两不相厌，衹有我和眼前的敬亭山了。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a12cee9a0c24ecf899", "shortContent": "敬亭山在宣州（治所在今安徽宣州市），宣州是六朝以来江南名郡，大诗人如谢灵运、谢朓等曾在这里做过太守。李白一生凡七游宣城（今安徽宣州市），这首五绝作于天宝十二载（753）秋游宣州时，距他被迫于天宝三载离开长安已有整整十年时间了。长期漂泊生活，使李白饱尝了人间辛酸滋味，看透了世态炎凉，从而加深了对现实的不满，增添了孤寂之感。此诗写独坐敬亭山时的情趣，正是诗人带着怀才不遇而产生的孤独与寂寞的感情，到大自...", "authors": ["宛敏灏宛新彬"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d10c", "shortContent": "敬亭山在宣州（治所在今安徽宣州市），宣州是六朝以来江南名郡，大诗人如谢灵运、谢朓等曾在这里做过太守。李白一生凡七游宣城（今安徽宣州市），这首五绝作于天宝十二载（753）秋游宣州时，距他被迫于天宝三载离开长安已有整整十年时间了。长期漂泊生活，使李白饱尝了人间辛酸滋味，看透了世态炎凉，从而加深了对现实的不满，增添了孤寂之感。此诗写独坐敬亭山时的情趣，正是诗人带着怀才不遇而产生的孤独与寂寞的感情，到大自...", "authors": ["宛敏灏", "宛新彬"], "pressName": "上海辞书出版社"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6467698330675327e194e4ed", "shortContent": "敬亭山在宣州（治所在今安徽宣州市），宣州是六朝以来江南名郡，大诗人如谢灵运、谢朓等曾在这里做过太守。李白一生凡七游宣城（今安徽宣州市），这首五绝作于天宝十二载（753）秋游宣州时，距他被迫于天宝三载离开长安已有整整十年时间了。长期飘泊生活，使李白饱尝了人间辛酸滋味，看透了世态炎凉，从而加深了对现实的不满，增添了孤寂之感。此诗写独坐敬亭山时的情趣，正是诗人带着怀才不遇而产生的孤独与寂寞的感情，到大自...", "authors": ["宛敏灏", "宛新彬"], "pressName": "上海辞书出版社"}]', '《唐诗广选》：便是独坐境界。
《诗薮》：绝句最贵含蓄，青莲「相看两不厌，惟有敬亭山」，亦太分晓。
《唐诗训解》：描写独坐之景，非深知山水趣者不能道。
《批选唐诗》：大雅玄冲。
《唐诗归》：胸中无事，眼中无人。钟云：说出矣，说不出。谭云：「只有」二字，人皆用作萧条零落，沿袭可厌，惟「相看两不厌」之下，接以「只有敬亭山」，则此二字，竟是意象所结，岂许俗人浪识！
《唐诗选脉会通评林》：周敬曰：孤行千古。
《唐诗归折衷》：「不厌」妙矣，「两不厌」尤妙。
《唐诗摘钞》：贤者自表其节，不肯为世推移也。
《增订唐诗摘钞》：鸟飞云远，言其独坐也；末句「独」字更醒。
《而庵说唐诗》：衹此五个字（按指「众鸟高飞尽」），使我目开心朗，身在虚空，一丝不挂，不必更读其诗也。白七言绝，佳；而五言绝，尤佳。此作于五言绝中，尤其佳者也。
《唐诗别裁》：传「独坐」之神，
《唐宋诗醇》：宛然「独坐」神理。胡应麟谓「绝句贵含蓄，此诗太分晓」，非善说诗者。
《李太白全集》：王琦注：《江南通志》：敬亭山在宁国府城北十里……东临宛溪，南俯城闉，烟市风帆，极目如画。
《唐诗笺注》：「尽」字、「闲」字是「不厌」之魂，「相看」下着「两」字，与敬亭山对若宾主，共为领略，妙！
《诗法易简录》：首二句已绘出「独坐」神理，三、四句偏不从独处写，偏曰「相看两不厌」，从不独处写出「独」字，倍觉警妙异常。
《唐诗选胜直解》：山间之所有者，鸟与云耳，今则飞尽矣，去闲矣。独坐之际对之郁然而深秀者，则有此山，陶靖节诗「悠然见南山」，即此意也，加「不厌」二字，方醒得独坐神理。言浅意深，人所不能道。
《唐人万首绝句选评》：命意之高不待言，气格亦内外具足、五绝中有数之作。
《唐诗真趣编》：鸟尽天空，孤云独去，青峰历历，兀坐怡然。写得敬亭山竟如好友当前，把臂谈心，安有厌倦？且敬亭而外，又安有投契若此者？然此情写之不尽，妙以「两不厌」三字了之。为「独坐」二字传神，性灵结撰，无复笔墨痕迹。
《诗式》：首句「众鸟」喻世间名利之辈，「高飞尽」言皆得意去，尽为「独」字写照。「孤云」喻世间高隐一流，「独去闲」言虽与世相忘。而尚有往来之迹。「独」字非题中「独」字，应上句「尽」字。三句看曰「相看」，见人固看著山，山亦似看著人；「两不厌」，见人固恋看山，山亦似恋看人。四句「只有」二字，见恋看山者惟人，而恋看人者似亦惟山。除却敬亭山以外，无足语者，「独坐」二字之神，跃然纸上。（品）高旷。
《诗境浅说续编》：后二句以山为喻，言世既与我相遗，惟敬亭山色，我不厌看，山亦爱我。夫青山漠漠无情，焉知憎爱，而言不厌我者，乃太白愤世之深，愿遗世独立，索知音于无情之物也。
《李太白诗醇》：严沧浪曰：与寒山一片石语，惟山有耳；与敬亭山相看，惟山有目：不怕聋聩杀世上人。古人胸怀眼界，直如此孤旷。潘云：不同鸟与云之易舍，是人不厌山；不同鸟与云之暂对，是山不厌人：故谓之「两」。然山无情，人有情，止成「独坐」而已。
《唐人绝句精华》：首二句独坐所见，三四句独坐所感，曰「两不厌」，便觉山亦有情，而太白之风神，有非尘俗所得知者，知者其山灵乎？
《李诗直解》：此独坐而有目中无人之景也。', 'center', 1413109428, '57b9109aa633bd00665dcd2a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10213, '宣州谢朓楼饯别校书叔云', NULL, 1321, 1052, 6, 11, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155460.htm', '', '弃我去者，昨日之日不可留。
乱我心者，今日之日多烦忧。
长风万里送秋雁，对此可以酣高楼。
蓬莱文章建安骨，中间小谢又清发。
俱怀逸兴壮思飞，欲上青天揽明月。
抽刀断水水更流，举杯销愁愁更愁。
人生在世不称意，明朝散发弄扁舟。', '此诗是唐代诗人李太白在宣城与其叔李云相遇并同登谢朓楼时创作的一首送别诗。此诗共九十二字，并不直言离别，而是重笔抒发自己怀才不遇的牢骚。全诗灌注了慷慨豪迈的情怀，抒发了诗人怀才不遇的激烈愤懑，表达了对黑暗社会的强烈不满和对光明世界的执著追求。虽极写烦忧苦闷，却并不阴郁低沉。诗中蕴含了强烈的思想感情，如奔腾的江河瞬息万变，波澜迭起，和艺术结构的腾挪跌宕、跳跃发展完美结合，达到了豪放与自然和谐统一的境界。', '宣州：今安徽宣城一带。
谢朓（tiǎo）楼：又名北楼、谢公楼，在陵阳山上，是南齐诗人谢玄晖任宣城太守时所建，并改名为叠嶂楼。李白曾多次登临，并且写过一首《秋登宣城谢朓北楼》。
饯别：以酒食送行。
校（jiào）书：官名，即祕书省校书郎，掌管朝廷的图书整理工作。
叔云：李白的叔叔李云。
长风：远风、大风。
此：指上句的长风秋雁的景色。
酣（hān）髙楼：畅饮于髙楼。
蓬莱：此指东汉时藏书之东观。《后汉书·卷二十三·〈窦融列传·（玄孙）窦章传〉》：「是时学者称东观为老氏藏室，道家蓬莱山」。章怀太子注：「言东观经籍多也。蓬莱，海中神山，为仙府，幽经秘籍并皆在也。」
蓬莱文章：借指李云的文章。
建安骨：汉献帝建安年间，「三曹」和「七子」等作家所作之诗风骨遒上，后人称之为「建安风骨」。
小谢：指谢朓，字玄晖，南朝齐诗人。后人将他和谢康乐并称为大谢、小谢。这里用以自喻。
清发：指清新秀发的诗风。发：诗文俊逸。
俱怀：两人都怀有。逸兴（xìng）：飘逸豪放的兴致，多指山水游兴，超远的意兴。王勃《滕王阁序》：「遥襟甫畅，逸兴遄飞」。李白《送贺宾客归越》：「镜湖流水漾清波，狂客归舟逸兴多。」壮思飞：卢思道《卢记室诔》：「丽词泉涌，壮思云飞。」壮思：雄心壮志，豪壮的意思。
揽：摘取。一本作「览」。
销：一本作「消」。
称（chèn）意：称心如意。
明朝（zhāo）：明天。
散发：不束冠，意谓不做官。这里是形容狂放不羁。古人束发戴冠，散发表示闲适自在。
弄扁（piān）舟：乘小舟归隐江湖。扁舟，小舟、小船。春秋末年，范蠡辞别越王勾践，「乘扁舟浮于江湖」（《史记·货殖列传》）。', '舍弃我而逝去的昨天，已经不可挽留，
扰乱我的心绪的今天，令人多有烦忧。
长风吹过了几万里送来秋雁，对此可以开怀畅饮酣醉高楼。
校书您的文章颇具建安风骨，又有我的诗如谢朓秀朗清发。
我们都是心怀逸兴壮思飞动，想登上九天去摘取一轮明月。
拔刀断水水却更加汹涌奔流，举杯消愁愁情上却更加忧愁。
人生在世上不能够称心如意，不如明天披头散发驾舟漂流。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929fd635634aee3deb78", "shortContent": "这是天宝末年李白在宣城期间饯别秘书省校书郎李云之作。谢朓楼，系南齐著名诗人谢朓任宣城太守时所创建，又称北楼、谢公楼。诗题一作《陪侍御叔华登楼歌》。\n发端既不写楼，更不叙别，而是陡起壁立，直抒郁结。“昨日之日”与“今日之日”，是指许许多多个弃我而去的“昨日”和接踵而至的“今日”。也就是说，每一天都深感日月不居，时光难驻，心烦意乱，忧愤郁悒。这里既蕴含了“功业莫从就，岁光屡奔迫”（《淮南卧病书怀寄蜀中...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac821a74606fc40945", "shortContent": "这是天宝末年李白在宣城期间饯别秘书省校书郎李云之作。谢朓楼，系南齐著名诗人谢朓任宣城太守时所创建，又称北楼、谢公楼。诗题一作《陪侍御叔华登楼歌》。\n\n发端既不写楼，更不叙别，而是陡起壁立，直抒郁结。“昨日之日”与“今日之日”，是指许许多多个弃我而去的“昨日”和接踵而至的“今日”。也就是说，每一天都深感日月不居，时光难驻，心烦意乱，忧愤郁悒。这里既蕴含了“功业莫从就，岁光屡奔迫”（《淮南卧病书怀寄蜀...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0d1", "shortContent": "\n宣州，江南名城，在今安徽南部。谢朓楼，南齐谢朓任宣州太守时所建，又称谢公楼，位于宣州城陵阳山巅。登此楼而望，满城风光尽收眼底。叔云，指李白族叔、校书郎李云。诗题一作《陪侍御叔华登楼歌》，叔华，即李白族叔李华，天宝、开元年间著名的古文家，曾任监察御史。据詹瑛先生考证，当以后者为是。\n\n天宝十二载（753），已经五十出头的李白来到宣州。此前，他曾游览了北方的幽州。初、盛唐的文人，往往抱有从军的志愿，...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127052c305cf0801816f61", "shortContent": "宣州，江南名城，在今安徽南部。谢朓楼，南齐谢朓任宣州太守时所建，又称谢公楼，位于宣州城陵阳山巅。登此楼而望，满城风光尽收眼底。叔云，指李白族叔、校书郎李云。诗题一作《陪侍御叔华登楼歌》，叔华，即李白族叔李华，开元、天宝年间著名的古文家，曾任监察御史。据詹瑛先生考证，当以后者为是。\n\n天宝十二载（753），已经五十出头的李白来到宣州。此前，他曾游览了北方的幽州。初、盛唐的文人，往往抱有从军的志愿，向...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270a5e6f69b71e93f632e", "shortContent": "宣州，江南名城，在今安徽南部。谢朓楼，南齐谢朓任宣州太守时所建，又称谢公楼，位于宣州城陵阳山巅。登此楼而望，满城风光尽收眼底。叔云，指李白族叔、校书郎李云。诗题一作《陪侍御叔华登楼歌》。叔华，即李白族叔李华，天宝、开元年间著名的古文家，曾任监察御史。据詹瑛先生考证，当以后者为是。\n\n天宝十二载（753），已经五十出头的李白来到宣州。此前，他曾游览了北方的幽州。初、盛唐的文人，往往抱有从军的志愿，向...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "64675ef045e4710056cfb35d", "shortContent": "这是天宝末年李白在宣城期间饯别秘书省校书郎李云之作。谢朓楼，系南齐著名诗人谢朓任宣城太守时所创建，又称北楼、谢公楼。诗题一作《陪侍御叔华登楼歌》。\n\n发端既不写楼，更不叙别，而是陡起壁立，直抒郁结。“昨日之日”与“今日之日”，是指许许多多个弃我而去的“昨日”和接踵而至的“今日”。也就是说，每一天都深感日月不居，时光难驻，心烦意乱，忧愤郁悒。这里既蕴含了“功业莫从就，岁光屡奔迫”（《淮南卧病书怀寄蜀...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '宋·严沧浪、刘须溪评点《李太白集》载明人评语：如天马行空，神龙出海。
明·高漫士《唐诗品汇》：刘云：崔嵬迭宕，正在起一句。「不称意」，诺欲绝。
明·陆仲昭《唐诗镜·卷十九》：雄情逸调。
明·唐仲言《唐诗解·卷十三》：此厌世多艰，思栖逸也。言往日不返，来日多忧，盍乘此秋色登楼以相酣畅乎？……然不得近君，是以愁不能忘。而以抽刀断水起兴，因言人生既不称意，便当适志扁舟，何栖栖仕宦为也？
明末清初·王船山《唐诗评选·卷一》：兴起超忽。
清髙宗敕编《唐宋诗醇·卷七》：遥情飙竖，逸兴云飞，杜少陵所谓「飘然思不群」此矣。二载而下，犹见酒间岸异之状，真仙才也。吴樊桐曰：亦从明远变化出来。
清·王翼云《唐诗合解·卷三》：前四句起势豪迈，如风雨之骤至。言日月如流，光阴如驶已去之。昨日难留，方来之忧思烦乱，况人生之聚散不定，而秋风又复可悲乎！当此秋风送雁，临眺髙楼，可不尽醉沉酣，以写我忧乎？《古唐诗合解》：此篇三韵两转，而起结别是一法。起势豪迈如风雨之骤至。
清·沈归愚《唐诗别裁》：此种格调，太白从心中化出（首二句下）。
清·宋宗元《网师园唐诗笺》：耸突爽逸（首二句下）。奥思奇句（「抽刀断水」二句下）。
清·方仪卫《昭昧詹言》：起二句，发兴无端。「长风」二句，落入；如此落法，非寻常所知。「抽刀」二句，仍应起意为章法。「人生」二句，言所以愁。
清·刘融斋《艺概》：昔人谓激昂之言出于兴，此「兴」字与他处言兴不同。激昂大抵*是情过于事，如太白诗「欲上青天揽日月」是也。
清·王缃绮《王闿运手批唐诗选》：起句破格，赖此救之（「长风万里」二句下）。中四句不贯，以其无愁也（「蓬莱文章」四句下）。
近·高阆仙《唐宋诗举要》：吴曰：破空时来，不可端倪（首二句下）。吴曰：再用破空之句作接，非太白雄才，那得有此奇横（「长空万里」句下）？吴曰：第四句始倒煞到题。翁覃溪曰：「蓬莱」句从中突起，横亘而出。吴曰：「抽刀」句再断。吴曰：收倒煞到题（末二句下）。', 'center', 1413387698, '57b2b3585bbb500062e4bef6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10214, '将进酒', NULL, 5641, 1052, 8, 9, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/31478/5173751.htm', '', '君不见黄河之水天上来，奔流到海不复回。
君不见高堂明镜悲白发，朝如青丝暮成雪。
人生得意须尽欢，莫使金樽空对月。
天生我材必有用，千金散尽还复来。
烹羊宰牛且为乐，会须一饮三百杯。
岑夫子，丹丘生，将进酒，杯莫停。
与君歌一曲，请君为我倾耳听。
钟鼓馔玉不足贵，但愿长醉不复醒。
古来圣贤皆寂寞，惟有饮者留其名。
陈王昔时宴平乐，斗酒十千恣欢谑。
主人何为言少钱，径须沽取对君酌。
五花马，千金裘，
呼儿将出换美酒，与尔同销万古愁。', '《将进酒》，唐代以前乐府歌曲的一个题目，内容大多咏唱饮酒放歌之事。在这首诗里，李白「借题发挥」借酒浇愁，抒发自己的愤激情绪。这首诗非常形象的表现了李白桀骜不驯的性格：一方面对自己充满自信，孤高自傲；一方面在政治前途出现波折后，又流露出纵情享乐之情。全诗气势豪迈，感情奔放，语言流畅，具有很强的感染力。', '将（qiāng）进酒：属乐府旧题。将，请。
君不见：乐府中常用的一种夸语。
天上来：黄河发源于青海，因那里地势极高，故称。
“君不见高堂明镜悲白发，朝如青丝暮成雪。”句：在高堂上的明镜中看到了自己的白发而悲伤。高堂，高大的厅堂；青丝，黑发。
得意：适意高兴的时候。
会须：正应当。
岑夫子：岑勋，李白的好友。
丹丘生：元丹丘，李白的好友。
杯莫停：一作“君莫停”。
与君：给你们、为你们。君，指岑、元二人。
倾耳听：一作“侧耳听”。
钟鼓：富贵人家宴会中奏乐使用的乐器。
馔（zhuàn）玉：形容食物如玉一样精美。
不复醒：也有版本为“不用醒”或“不愿醒”。
陈王：指陈思王曹植。
平乐：观名。在洛阳西门外，为汉代富豪显贵的娱乐场所。
恣：纵情任意。
谑（xuè）：戏。
言少钱：一作“言钱少”。
径须：干脆、只管。
沽：买。
五花马：指名贵的马。一说毛色作五花纹，一说颈上长毛修剪成五瓣。
尔：你。
销：同“消”。', '你难道看不见那黄河之水从天上奔腾而来，波涛翻滚直奔东海，从不再往回流。
你难道看不见高堂上的明镜中的满头白发，早晨还是满头的黑发，怎么才到傍晚就变成了雪白一片。
（所以）人生得意之时就应当纵情欢乐，不要让这金杯无酒空对明月。
每个人的出生都一定有自己的价值和意义，黄金千两（就算）一挥而尽，它也还是能够再得来。
我们烹羊宰牛姑且作乐，（今天）一次性痛快地饮三百杯也不为多！
岑夫子，丹丘生啊！快喝酒吧！不要停下来。
让我来为你们高歌一曲，请你们为我倾耳细听：
整天吃山珍海味的豪华生活有何珍贵，只希望醉生梦死而不愿清醒。
自古以来圣贤无不是冷落寂寞的，只有那会喝酒的人才能够留传美名。
陈王曹植当年宴设平乐观的事迹你可知道，斗酒万千也豪饮，让宾主尽情欢乐。
主人呀，你为何说钱不多？只管买酒来让我们一起痛饮。
那些什么名贵的五花良马，昂贵的千金狐裘，把你的侍儿喊出来，都让他拿去换美酒来吧，让我们一起来消除这无穷无尽的万古长愁！', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929a0ce818559d058675", "shortContent": "李白咏酒的诗篇极能表现他的个性，这类诗固然数长安放还以后所作思想内容更为深沉，艺术表现更为成熟。《将进酒》即其代表作。\n《将进酒》原是汉乐府短箫铙歌的曲调，“将（狇犻ā狀ɡ）”意为“愿”、“请”，题目意译即“劝酒歌”，故古词有“将进酒，乘大白”云。作者这首“填之以申己意”（萧士赟《分类补注李太白诗》）的名篇，旧说均以为作于天宝间去朝之后（约752）。据今人考证，李白曾两入长安，此诗当为开元间一入长...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc40931", "shortContent": "李白咏酒的诗篇极能表现他的个性，这类诗固然数长安放还以后所作思想内容更为深沉，艺术表现更为成熟。《将进酒》即其代表作。\n\n《将进酒》原是汉乐府短箫铙歌的曲调，“将（狇犻ā狀ɡ）”意为“愿”“请”，题目意译即“劝酒歌”，故古词有“将进酒，乘大白”云。作者这首“填之以申己意”（萧士赟《分类补注李太白诗》）的名篇，旧说均以为作于天宝间去朝之后（约752）。据今人考证，李白曾两入长安，此诗当为开元间一入长...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f0930b", "shortContent": "《将进酒》原是汉乐府短箫铙歌的曲调，古人多用来颂扬武功以美君德。李白借用古词“将进酒，乘大白”之意以写眼前宴饮之乐，所以这首诗实际上就是劝酒之歌，所劝的对象就是“岑夫子，丹丘生”。大约在天宝十一载（752），李白与友人岑勋、元丹丘登高饮宴，诗兴大发而赋此篇。\n\n诗人开端即言人有生则必有死，正如黄河之水从天而来，一泻千里，势不可回。由此联想到人既生之后，未死之前，美好光阴能有几时？昨日黄发少年，转瞬...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312704d73206168b2e021da", "shortContent": "《将进酒》原是汉乐府短箫铙歌的曲调，古人多用来颂扬武功以美君德，李白借用古词“将进酒，乘大白”之意以写眼前宴饮之乐，所以这首诗实际上就是劝酒之歌，所劝的对象就是“岑夫子，丹丘生”。大约在天宝十一载（752），李白与友人岑勋、元丹丘登高饮宴，诗兴大发而赋此篇。\n\n诗人开端即言人有生则必有死，正如黄河之水从天而来，一泻千里，势不可回。由此联想到人既生之后，未死之前，美好光阴能有几时？昨日黄发少年，转瞬...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127078f2af4e09d55b67a0", "shortContent": "《将进酒》原是汉乐府短箫铙歌的曲调，古人多用来颂扬武功以美君德。李白借用古词“将进酒，乘大白”之意以写眼前燕饮之乐，所以这首诗实际上就是劝酒之歌，所劝的对象就是“岑夫子，丹丘生”。大约在天宝十一载（752），李白与友人岑勋、元丹丘登高饮宴，诗兴大发而赋此篇。\n\n诗人开端即言人有生则必有死，正如黄河之水从天而来，一泻千里，势不可回。由此联想到人既生之后，未死之前，美好光阴能有几时？昨日黄发少年，转瞬...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6466c90ce49f46528aadd313", "shortContent": "李白咏酒的诗篇极能表现他的个性，这类诗固然数长安放还以后所作思想内容更为深沉，艺术表现更为成熟。《将进酒》即其代表作。\n\n《将进酒》原是汉乐府短箫铙歌的曲调，“将（qiānɡ）”意为“愿”、“请”，题目意译即“劝酒歌”，故古词有“将进酒，乘大白”云。作者这首“填之以申己意”（萧士赟《分类补注李太白诗》）的名篇，旧说均以为作于天宝间去朝之后（约752）。据今人考证，李白曾两入长安，此诗当为开元间一入...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f2df930675327e1b5c24a", "shortContent": "李白咏酒的诗篇极能表现他的个性，这类诗固然数长安放还以后所作思想内容更为深沉，艺术表现更为成熟。《将进酒》即其代表作。\n诗篇发端就是两组排比长句，如挟天风海雨迎面扑来。“君不见黄河之水天上来，奔流到海不复回”，颍阳去黄河不远，登高纵目，故借以起兴。黄河源远流长，落差极大，如从天而降，一泻千里，东奔大海。如此壮浪景象，定非肉眼可以穷极，作者是想落天外，“自道所得”，语带夸张。上句写大河之来，势不可挡...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '《李太白诗集》：严羽评：一结豪情，使人不能句字赏摘。盖他人作诗用笔想，太白但用胸口一喷即是，此其所长。
《唐诗广选》：转折动荡自然（“岑夫子”二句下）。杨升庵曰：太白狂歌。实中玄理，非故为狂语者。
《唐诗解》卷上：此怀才不遇，托于酒以自放也。
《唐诗选脉会通评林》：周珽曰：首以“黄河”起兴，见人之年貌倏改，有如河流莫返。一篇主意全在“人生得意须尽欢，莫使金樽空对月”两句。
《此木轩论诗汇编》：“惟有饮者留其名”，乱道故妙，一学便俗。
《古唐诗合解》：太白此歌豪放极矣。
《而庵说唐诗》：太白此歌，最为豪放，才气千古无双。
《唐诗选胜直解》：此诗妙在自解又以劝人。“主人”是谁？“对君”是谁？骂尽窃高位、守钱虏辈，妙，妙！
《唐诗合选详解》：王翼云曰：此篇用长短句为章法，篇首两个“君不见”领起，亦一局也。
《唐宋诗举要》：吴曰：驱迈淋漓之气（“人生得意”一句下）。吴曰：豪健（末句下）。
《李太白诗醇》：一起奇想，亦自天外来。', 'indent', 1415640870, '57b087cc5bbb500062d4cce4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10225, '八声甘州', NULL, 530, 225, 6, 6, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/view/2790103.htm', '', '对潇潇暮雨洒江天，一番洗清秋。渐霜风凄紧，关河冷落，残照当楼。是处红衰翠减，苒苒物华休。唯有长江水，无语东流。
不忍登高临远，望故乡渺邈，归思难收。叹年来踪迹，何事苦淹留。想佳人、妆楼颙望，误几回、天际识归舟。争知我、倚阑干处，正恁凝愁。', '柳永出身士族家庭，从小接受儒家思想文化熏陶，有求仕用世之志。因其天性浪漫，极具音乐天赋，适逢北宋安定统一，城市繁华，开封歌楼妓馆林林总总，被流行歌曲吸引，乐与伶工、歌妓为伍。初入仕，竟因谱写俗曲歌词，遭致当权者挫辱，而不得伸其志。他于是浪迹天涯，用词抒写羁旅之志和怀才不遇的痛苦愤懑。《八声甘州》即此类词的代表作。被苏轼称赞其佳句为「不减唐人高处」。
此词抒写了作者漂泊江湖的愁思和仕途失意的悲慨。上阕描绘了雨后清秋的傍晚，关河冷落夕阳斜照的凄凉之景；下阕抒写词人久客他乡急切思念归家之情。全词语浅而情深，融写景、抒情为一体，通过描写羁旅行役之苦，表达了强烈的思归情绪，写出了封建社会知识分子怀才不遇的典型感受，从而成为传诵千古的名篇。', '对潇潇暮雨洒江天，一番洗清秋：写眼前的景象。潇潇暮雨在辽阔江天飘洒，经过一番雨洗的秋景分外清朗寒凉。潇潇，下雨声。一说雨势急骤的样子。一作「萧萧」，义同。清秋，清冷的秋景。
霜风：指秋风。
凄紧：一作「凄惨」。凄凉紧迫。
关河：关塞与河流，此指山河。
残照：落日馀光。当，对。
是处：到处。
红衰翠减：指花叶凋零。
红，代指花。
翠，代指绿叶。此句为借代用法。
苒苒（rǎn）：同「荏苒」，形容时光消逝，渐渐（过去）的意思。
物华：美好的景物。
休：这里是衰残的意思。
渺邈（miǎo）：远貌，渺茫遥远。一作「渺渺」，义同。
归思（sì）：渴望回家团聚的心思。思，做心绪愁思讲
淹留：长期停留。
佳人：美女。古诗文中常用代指自己所怀念的对象。
颙（yóng）望：抬头凝望。颙，一作「长」。
误几回：多少次错把远处驶来的船只当作心上人的归舟。语意出温庭筠《望江南》词：「过尽千帆皆不是，斜晖脉脉水悠悠，肠断白苹洲。」
天际，指目力所能达到的极远之处。
争：怎。
处：这里表示时间。
倚阑干处：即「倚栏杆时」。
恁（nèn）：如此。
凝愁：愁苦不已，愁恨深重。凝，表示一往情深，专注不已。', '伫立江边面对着潇潇暮雨，暮雨仿佛在洗涤清冷的残秋。渐渐地雨散云收秋风逐渐紧，山河冷落落日余晖映照江楼。满目的凄凉到处是花残叶凋，那些美好的景色都已经歇休。只有长江水默默地向东流淌。
其实我实在不忍心登高眺望，想到故乡遥远不可及之处，一颗归乡的心迫切难以自抑。叹息这几年来四处奔波流浪，究竟是什么苦苦到处滞留？佳人一定天天登上江边画楼，眺望我的归舟误认一舟一舟？你可知道我正在倚高楼眺望，心中充满了思念家乡的忧愁苦闷？', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749f7d0ac1145494bb2c", "shortContent": "柳耆卿在世时，不为人重，但因擅长填词而深受歌妓们的欢迎和赏识，一生潦倒，死后也是只有歌儿笛工们怀念不忘，逢时设祭。这种文士，旧时讥为“无行”，但是他并不像那些正统士大夫们所估计得那般微不足道。他写下的几篇名阕，境界高绝，成为词史上的丰碑，是第一流作品，千古传颂。这篇《八声甘州》，早被苏东坡巨眼所识，说其间佳句“不减唐人高处”。须知这样的赞语，是极高的评价，东坡不曾轻易以此许人的。\n吟赏此词，全要着...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a70ce818559d063ad7", "shortContent": "柳耆卿在世时，不为人重，但因擅长填词，却深受歌妓们的欢迎和赏识，一生潦倒，死后也是只有歌儿笛工们怀念不忘，逢时设祭。这种文士，旧时讥为“无行”，但是他并不像那些正统士大夫们所估计的那般微不足道，他写下的几篇名阕，境界高绝，成为词史上的丰碑，是第一流作品，千古传颂。这篇《八声甘州》，早被苏东坡巨眼识，说其间佳句“不减唐人高处”。须知这样的赞语，是极高的评价，东坡不曾轻易以此许人的。\n吟赏此词，全要着...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252ccce4d48ba496d83", "shortContent": "柳耆卿在世时，不为人重，但因擅长填词，却深受歌妓们的欢迎和赏识，一生潦倒，死后也是只有歌儿笛工们怀念不忘，逢时设祭。这种文士，旧时讥为“无行”，但是他并不像那些正统士大夫们所估计的那般微不足道，他写下的几篇名阕，境界高绝，成为词史上的丰碑，是第一流作品，千古传颂。这篇《八声甘州》，早被苏东坡巨眼识，说其间佳句“不减唐人高处”。须知这样的赞语，是极高的评价，东坡不曾轻易以此许人的。\n\n吟赏此词，全要...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f39e6f69b71e93f6193", "shortContent": "近代著名学者夏敬观先生认为读柳永词应先分出雅、俚两类，“雅词用六朝小品文赋作法，层层铺叙，情景兼融，一笔到底，始终不懈”（手评《乐章集》），此词可称典范。柳永初入世时因谱写俗曲歌词，遭致当权者挫辱而不得伸其志。他于是浪迹天涯，用词抒写羁旅之志和怀才不遇的痛苦愤懑，《八声甘州》即此类写秋士易感之佳作。这首词，整体思路上与《玉蝴蝶》颇为相似，所不同者，《玉蝴蝶》是怀念故交旧友的，这一首则是想家思归的，...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe47ccdb86c49f29181", "shortContent": "近代著名学者夏敬观先生认为读柳永词应先分出雅、俚两类，“雅词用六朝小品文赋作法，层层铺叙，情景兼融，一笔到底，始终不懈”（手评《乐章集》），此词可称典范。柳永初入世时因谱写俗曲歌词，遭致当权者挫辱而不得伸其志。他于是浪迹天涯，用词抒写羁旅之志和怀才不遇的痛苦愤懑，《八声甘州》即此类写秋士易感之佳作。这首词，整体思路上与《玉蝴蝶》颇为相似，所不同者，《玉蝴蝶》是怀念故交旧友的，这一首则是想家思归的，...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127174c305cf08018170b3", "shortContent": "近代著名学者夏敬观先生认为读柳永词应先分出雅、俚两类，“雅词用六朝小品文赋作法，层层铺叙，情景兼融，一笔到底，始终不懈”（手评《乐章集》），此词可称典范。柳永初入世时因谱写俗曲歌词，遭致当权者挫辱而不得伸其志。他于是浪迹天涯，用词抒写羁旅之志和怀才不遇的痛苦愤懑，《八声甘州》即此类写秋士易感之佳作。这首词，整体思路上与《玉蝴蝶》颇为相似，所不同者，《玉蝴蝶》是怀念故交旧友的，这一首则是想家思归的，...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d125c7af6de1647100d8a", "bookTitle": "柳永词鉴赏辞典", "articleId": "646d8fab82772d4594158311", "shortContent": "柳耆卿在世时，不为人重，但因擅长填词，却深受歌妓们的欢迎和赏识，一生潦倒，死后也是只有歌儿笛工们怀念不忘，逢时设祭。这种文士，旧时讥为“无行”，但是他并不像那些正统士大夫们所估计的那般微不足道，他写下的几篇名阕，境界高绝，成为词史上的丰碑，是第一流作品，千古传颂。这篇《八声甘州》，早被苏东坡巨眼识，说其间佳句“不减唐人高处”。须知这样的赞语，是极高的评价，东坡不曾轻易以此许人的。\n\n吟赏此词，全要...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413196716, '57b8ed095bbb50005b77ab1e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (187186, '四景', NULL, 14, 43, 0, 1, '朱瞻基', NULL, 15666, '5858ea3d8d6d810065c3364d', '明', 'shi', '诗', '', '', '暑雨初过爽气清，玉波荡漾画桥平。
穿帘小燕双双好，泛水闲鸥个个轻。', '', '', '', NULL, '', 'center', 1553081329, '585d892aac502e006724f348', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10215, '永遇乐 · 京口北固亭怀古', NULL, 1038, 793, 4, 15, '辛弃疾', NULL, 10003, '57b8ed682e958a005fa4d096', '宋', 'ci', '词', 'http://baike.baidu.com/view/206844.htm', '', '千古江山，英雄无觅，孙仲谋处。舞榭歌台，风流总被，雨打风吹去。斜阳草树，寻常巷陌，人道寄奴曾住。想当年，金戈铁马，气吞万里如虎。
元嘉草草，封狼居胥，赢得仓皇北顾。四十三年，望中犹记，烽火扬州路。可堪回首，佛狸祠下，一片神鸦社鼓。凭谁问：廉颇老矣，尚能饭否？', '此词写于宋宁宗开禧元年（西元一二〇五年），辛稼轩六十六岁。当时韩侂胄执政，正积极筹划北伐，闲置已久的辛稼轩于前一年被起用为浙东安抚使，这年春初，又受命担任镇江知府，戍守江防要地京口。从表面看来，朝廷对他似乎很重视，然而实际上衹不过是利用他那主战派元老的招牌作为号召而已。辛稼轩到任後，一方面积极布置军事进攻的准备工作；但另一方面，他又清楚地意识到政治鬬争的险恶，自身处境的孤危，深感很难有所作为。辛稼轩支持北伐抗金的决策，但是对独揽朝政的韩侂胄轻敌冒进的作法，又感到忧心忡忡，他认为应当做好充分准备，绝不能草率从事，否则难免重蹈覆辙，使北伐再次遭到失败。辛稼轩的意见没有引起南宋当权者的重视。一次他来到京口北固亭，登高眺望，怀古忆昔，心潮澎湃，感慨万千，于是写下了这首词中佳作。
上阕赞扬在京口建立霸业的孙权和率军北伐，气吞胡虏的刘裕，表示要像他们一样金戈铁马为国立功。下阕藉讽刺刘义隆表明自己坚决主张抗金但反对冒进误国的立场和态度。该词的抒发感慨连连用典，中间稍加几句抒情性议论以见，不仅体现了稼轩词好用典的特点，也可窥见「词论」的风格。', '永遇乐（lè）：词牌名。南宋·周草窗《天基节乐次》：「乐奏夹钟宫，第五盏，觱（bì）篥（lì）起《永遇乐慢》。」此调有平韵、仄韵两体。仄韵者始自北宋，《乐章集》注「林钟商」。晁无咎词名《消息》，自注「越调」。清·毛稚黄《填词名解》云：「《永遇乐》，歇拍调也。唐杜秘书工小词，邻家有小女名酥香，凡才人歌曲悉能吟讽，尤喜杜词，遂成逾墙之好。后为仆所诉，杜竟流河朔。临行，述《永遇乐》词决别，女持纸三唱而死。第未知此调，创自杜与否。」所引故事不可考；大抵创自唐之中叶。明末清初·万红友《词律》引晁无咎《消息》注云：「自过腔，即越调《永遇乐》。」是此词又为越调也。兹以苏、辛词为准。一百四字，前后阕各四仄韵。平韵者始自南宋，陈允平创为之。
京口：即今江苏镇江。唐·李弘宪《元和郡县志·卷二十六·〈江南道·润州〉》：「今为浙西观察使理所。……本春秋吴之朱方邑，始皇改为丹徒。汉初为荆国，刘贾所封。后汉献帝建安十四年，孙权自吴理丹徒，号曰『京城』，今州是也。十六年迁都建业，以此为京口镇。」
北固亭：清·顾宛溪《读史方舆纪要·卷二十五·〈南直·镇江府·北固山〉》：「北固山在城北一里府治后，下临长江。自晋以来，郡治皆据其上。三面临水，回岭斗绝，势最险固，因名，盖郡之主山也。蔡谟起楼于其上，以贮君实，谢安复营葺之。……大同十年，武帝登望，久之曰：『此岭下足须固守，然于京口，实乃壮观。』于是改楼曰北顾楼。」南宋·陈季麟《北固山志·卷二·建置》：「北固山在山上，晋蔡谟建。《梁纪》云：『大同十年春三月乙酉幸京口城北固楼，改名北顾。』乾道己丑守臣待制陈天麟补建，有碑记（嘉定甲戌，待制史弥坚命吏访得，裂为三而失其一）。楼或亭名。旧亭在郡圃后，绍熙壬子殿撰赵彦逾徙于山，西向。嘉泰壬戌阁学黄由增广之。」
孙仲谋：三国时吴国开国皇帝孙权，字仲谋，吴郡富春县（今浙江富阳）人，曾建都京口。长沙太守孙文台次子，幼跟兄孙伯符平江东，汉献帝建安五年（西元二〇〇年）孙伯符早逝。孙仲谋继位江东之主。
舞榭歌台：演出歌舞之台榭，此代指孙仲谋故宫。
「斜阳草树，寻常巷陌」句：宋·周美成《西河·金陵怀古》词：「燕子不知何世，入寻常、巷陌人家，相对如说兴亡，斜阳里。」寻常，古代长度单位，八尺为寻，倍寻为常，遂状窄狭，亦引伸为普通、平常。
寄奴：南朝宋武帝刘裕，字德舆，小字寄奴。自其高祖随晋渡江，即居于晋陵郡丹徒县之京口里。
金戈铁马，五代后唐李袭吉《论梁书》：「毒手尊泉，交相于暮夜；金戈铁马，蹂践于明月。」二者皆为当时精良军事装备，此代指精锐部队。金戈，用金属所制之长枪；铁马，披著铁甲之战马。
「想当年、金戈铁马，气吞万里如虎。」句：宋武帝曾两次领兵北伐，收复洛阳、长安等地。
元嘉草草：宋武帝第三子宋文帝年号。宋文帝好大喜功，仓促北伐，反为北魏太武帝趁机以骑兵集团南下，直抵长江北岸，重创刘宋而返。草草，轻率。
封狼居胥：古时积土为坛于山上，祭天曰「封」，祭地曰「禅」，以庆胜。《史记·卷一百十一·〈卫将军骠骑列传·骠骑传〉》：「元狩四年春，上令大将军青、骠骑将军去病将各五万骑，步兵转者踵军数十万，而敢力战深入之士皆属骠骑。骠骑始为出定襄，当单于。捕虏言单于东，乃更令骠骑出代郡，令大将军出定襄。郎中令为前将军，太仆为左将军，主爵赵食其为右将军，平阳侯襄为后将军，皆属大将军。兵即度幕，人马凡五万骑，与骠骑等咸击匈奴单于。……骠骑将军亦将五万骑，车重与大将军军等，而无裨将。悉以李敢等为大校，当裨将，出代、右北平千馀里，直左方兵，所斩捕功已多大将军。军既还，天子曰：『骠骑将军去病率师，躬将所获荤粥之士，约轻赍，绝大幕，涉获章渠，以诛比车耆，转击左大将，斩获旗鼓，历涉离侯。济弓闾，获屯头王、韩王等三人，将军、相国、当户、都尉八十三人，封狼居胥山，禅于姑衍，登临翰海。执卤获丑七万有四百四十三级，师率减什三，取食于敌，閒行殊远而粮不绝，以五千八百户益封骠骑将军。』」《宋书·卷七十六·王玄谟传》：「玄谟每陈北侵之策，上谓殷景仁曰：『闻王玄谟陈说，使人有封狼居意。』」词中用「元嘉北伐」失利事，以影射南宋「隆兴北伐」。狼居胥山，在内蒙古自治区西北部。
赢得：落得。
仓皇北顾：宋文帝刘义隆命王玄谟率师北伐，为北魏太武帝拓跋焘击败，魏趁机大举南侵，直抵扬州，嚇得宋文帝亲自登上建康幕府山向北观望形势。《宋书·卷九十五·索虏传》：「（元嘉八年）上以滑台战守弥时，遂至陷没，乃作诗曰：『逆虏乱疆埸，边将婴寇仇。坚城效贞节，攻战无暂休。覆沈不可拾，离机难复收。势谢归涂单，于焉见幽囚。烈烈制邑守，舍命蹈前修。忠臣表年暮，贞柯见严秋。楚庄投袂起，终然报强雠。去病辞高馆，卒获舒国忧。戎事谅未殄，民患焉得瘳。抚剑怀感激，志气若云浮。愿想淩扶摇，弭旆拂中州。爪牙申威灵，帷幄骋良筹。华裔混殊风，率土浃王猷。惆怅惧迁逝，北顾涕交流。』」
四十三年：稼轩于宋高宗绍兴三十二年（西元一一六二年）正月，奉表南归，至宋宁宗开禧元年（西元一二〇五年）春于京口作此词，恰为四十三年。
烽火扬州路：隆兴二年（西元一一六四年）金兵渡淮陷濠州、滁州而至扬州。
可堪：表面意为可以忍受得了，实犹「岂堪」、「那堪」，即怎能忍受得了。堪，忍受。
佛（bì）狸祠：北魏太武帝小字佛狸。南朝宋元嘉二十七年（西元四五〇年），北魏太武帝曾反击刘宋，两月内兵锋南下，五路远征军分道并进，从黄河北岸直驱长江北岸，并于瓜步山建立行宫，即后之佛狸祠。《宋书·卷九十五·索虏传》：「索头虏姓托跋氏，其先汉将李陵后也。陵降匈奴，有数百千种，各立名号，索头亦其一也。……（托跋）嗣死，谥曰明元皇帝，子焘字佛狸代立。」宋·陆放翁《入蜀记·卷二》：「（乾道六年七月）四日，风便，解缆挂帆，发真州。岸下舟相先后发者甚众，烟帆映山，缥缈如画。有顷，风愈厉，舟行甚疾。过瓜步山，山蜿蜓蟠伏，临江起小峰，颇巉峻。绝顶有元魏太武庙，庙前大木可三百年。一井已眢，传以为太武所凿，不可知也。太武以宋文帝元嘉二十七年南侵至瓜步，建康戒严。太武凿瓜步出为蟠道，于其上设毡庐，大会群臣，疑即此地。王文公诗所谓『丛祠瓜步认前朝』是也。梅圣俞题庙云：『魏武数忘归，孤军驻山顶。』按太武初未尝败，圣俞误以佛狸为曹瞒耳。山出玛瑙石，多虎豹害人，往时大将刘宝，每募人捕虎于此。周世宗伐南唐，齐王景达自瓜步渡江，距六合二十里设栅，亦此地也。入夹行数里，沿岸园畴衍沃，庐舍竹树极盛，大抵多长芦寺庄。出夹望长芦，楼塔重复。自江淮兵火，官寺民庐，莫不残坏，独此寺之盛，不减承平，至今日常数百众。江面渺瀰无际，殊可畏。李太白诗云『维舟至长芦，目送烟云高』是也。晚泊竹筱港，有居民二十馀家，距金陵三十里。」
「佛狸祠下，一片神鸦社鼓。」句：南宋时的当地老百姓只把佛狸祠作为供奉神祇之所，而不知其曾为北魏太武帝之行宫。神鸦，指在庙里吃祭品之乌鸦。社鼓，祭祀时之鼓声。
「凭谁问，廉颇老矣，尚能饭否？」句：廉颇：战国时赵国名将。《史记·卷八十一·〈廉颇蔺相如列传·廉颇传〉》：「廉颇居梁，久之，魏不能信用。赵以数困于秦兵，赵王思复得廉颇，廉颇亦思复用于赵。赵王使使者视廉颇尚可用否。廉颇之仇郭开多与使者金，令毁之。赵使者既见廉颇，廉颇为之一饭斗米，肉十斤，被甲上马，以示尚可用。赵使还报王曰：『廉将军虽老，尚善饭，然与臣坐，顷之三遗矢矣。』赵王以为老，遂不召。」', '历经千古的江山，再也难找到像孙权那样的英雄。当年的舞榭歌台还在，英雄人物却随着岁月的流逝早已不复存在。斜阳照着长满草树的普通小巷，人们说那是当年刘裕曾经住过的地方。回想当年，他领军北伐、收复失地的时候是何等威猛！
然而刘裕的儿子刘义隆好大喜功，仓促北伐，却反而让北魏太武帝拓跋焘乘机挥师南下，兵抵长江北岸而返，遭到对手的重创。我回到南方已经有四十三年了，看着中原仍然记得扬州路上烽火连天的战乱场景。怎么能回首啊，当年拓跋焘的行宫外竟有百姓在那里祭祀，乌鸦啄食祭品，人们过着社日，衹把他当作一位神祗来供奉，而不知道这里曾是一个皇帝的行宫。还有谁会问，廉颇老了，饭量还好吗？', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74ec2cee9a0c24ec7daa", "shortContent": "此词作于开禧元年（1205）。当时，韩侂胄正准备北伐。闲废已久的辛弃疾于前一年被起用为浙东安抚使，这年春初，又受命知镇江府，出镇江防要地京口（今江苏镇江）。从表面看来，朝廷对他似乎很重视，然而实际上只不过是利用他那主战派元老的招牌作为号召而已。辛弃疾到任后，一方面积极布置军事进攻的准备工作；但另一方面，他又清楚地意识到政治斗争的险恶，自身处境的孤危，深感很难有所作为。一片紧锣密鼓的北伐声，当然能唤...", "authors": ["马", "群"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ee2e6a6b501f967364", "shortContent": "此词作于开禧元年（1205）。当时，韩侂胄正准备北伐。闲废已久的辛弃疾于前一年被起用为浙东安抚使，这年春初，又受命知镇江府，出镇江防要地京口（今江苏镇江）。从表面看来，朝廷对他似乎很重视，然而实际上只不过是利用他那主战派元老的招牌作为号召而已。辛弃疾到任后，一方面积极布置军事进攻的准备工作；但另一方面，他又清楚地意识到政治斗争的险恶，自身处境的孤危，深感很难有所作为。在一片紧锣密鼓的北伐声中，当然...", "authors": ["马", "群"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255eebf5e0fdea508f0", "shortContent": "此词作于开禧元年（1205）。当时，韩侂胄正准备北伐。闲废已久的辛弃疾于前一年被起用为浙东安抚使，这年春初，又受命知镇江府，出镇江防要地京口（今江苏镇江）。从表面看来，朝廷对他似乎很重视，然而实际上只不过是利用他那主战派元老的招牌作为号召而已。辛弃疾到任后，一方面积极布置军事进攻的准备工作；但另一方面，他又清楚地意识到政治斗争的险恶，自身处境的孤危，深感很难有所作为。在一片紧锣密鼓的北伐声中，当然...", "authors": ["马　群"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f4f73206168b2e020fd", "shortContent": "英雄，是辛词中频繁出现的字眼。以英雄自许的辛弃疾，从不掩饰对英雄功业的崇拜与渴望。在辛弃疾笔下的历史英雄中，三国时代的孙权显得格外突出。公允说来，辛弃疾对孙权的推崇，固然出于男人对男人的欣赏，英雄对英雄的仰慕；然而更为深层的原因，还是因为东吴政权与南宋朝廷在处境上的某种相似之处。换言之，辛弃疾对孙权的颂扬与推崇，实则寄寓着他对南宋国运的忧思与期望。这首以孙权史事开篇的《永遇乐》词，便是其中之一。\n...", "authors": ["江俊伟"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127044c305cf0801816f1f", "shortContent": "这是一首游览古迹之后的怀古之作，也可以说是一首咏史词。词人游览之处是建康城外的赏心亭，它位于建康下水门之上。这首词是送给建康留守史致道的，留守是官职，即行宫留守，南宋高宗赵构南渡时，曾停留在建康，所以此处设有行宫留守一职。\n\n词的上片，写词人登上高楼，触景伤情，感慨万千。建康曾做过六个王朝的都城，词人游历古迹，不禁发问，钟山龙盘，石头虎踞，这虎踞龙盘的地理位置今尤在，那些王朝却已经覆灭了，只剩下了...", "authors": ["陈庆之"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312704773206168b2e021ca", "shortContent": "英雄，是辛词中频繁出现的字眼。以英雄自许的辛弃疾，从不掩饰对英雄功业的崇拜与渴望。在辛弃疾笔下的历史英雄中，三国时代的孙权显得格外突出。公允说来，辛弃疾对孙权的推崇，固然出于男人对男人的欣赏，英雄对英雄的仰慕；然而更为深层的原因，还是因为东吴政权与南宋朝廷在处境上的某种相似之处。换言之，辛弃疾对孙权的颂扬与推崇，实则寄寓着他对南宋国运的忧思与期望。这首以孙权史事开篇的《永遇乐》词，便是其中之一。\n...", "authors": ["江俊伟"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127200c305cf080181711e", "shortContent": "英雄，是辛词中频繁出现的字眼。以英雄自许的辛弃疾，从不掩饰对英雄功业的崇拜与渴望。在辛弃疾笔下的历史英雄中，三国时代的孙权显得格外突出。公允说来，辛弃疾对孙权的推崇，固然出于男人对男人的欣赏，英雄对英雄的仰慕；然而更为深层的原因，还是因为东吴政权与南宋朝廷在处境上的某种相似之处。换言之，辛弃疾对孙权的颂扬与推崇，实则寄寓着他对南宋国运的忧思与期望。这首以孙权史事开篇的《永遇乐》词，便是其中之一。\n...", "authors": ["江俊伟"], "pressName": "崇文书局"}, {"bookId": "64688f9830675327e19962ff", "bookTitle": "辛弃疾词鉴赏辞典（珍藏本）", "articleId": "64698372b6a81d0c5307099d", "shortContent": "此词作于开禧元年(1205)。当时，韩侂胄正准备北伐。闲废已久的辛弃疾于前一年被起用为浙东安抚使，这年春初，又受命知镇江府，出镇江防要地京口（今江苏镇江）。从表面看来，朝廷对他似乎很重视，然而实际上只不过是利用他那主战派元老的招牌作为号召而已。辛弃疾到任后，一方面积极布置军事进攻的准备工作；但另一方面，他又清楚地意识到政治斗争的险恶，自身处境的孤危，深感很难有所作为。一片紧锣密鼓的北伐声，当然能唤...", "authors": ["马群"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f365a82772d45941d0f80", "shortContent": "此词作于开禧元年(1205)。当时，韩侂胄正准备北伐。闲废已久的辛弃疾于前一年被起用为浙东安抚使，这年春初，又受命知镇江府，出镇江防要地京口（今江苏镇江）。从表面看来，朝廷对他似乎很重视，然而实际上只不过是利用他那主战派元老的招牌作为号召而已。辛弃疾到任后，一方面积极布置军事进攻的准备工作；但另一方面，他又清楚地意识到政治斗争的险恶，自身处境的孤危，深感很难有所作为。一片紧锣密鼓的北伐声，当然能唤...", "authors": ["马群"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472dfefa5f1e74f958aad4f", "shortContent": "此词作于开禧元年（1205）。当时，韩侂胄正准备北伐。闲废已久的辛弃疾于前一年被起用为浙东安抚使，这年春初，又受命知镇江府，出镇江防要地京口（今江苏镇江）。从表面看来，朝廷对他似乎很重视，然而实际上只不过是利用他那主战派元老的招牌作为号召而已。辛弃疾到任后，一方面积极布置军事进攻的准备工作；但另一方面，他又清楚地意识到政治斗争的险恶，自身处境的孤危，深感很难有所作为。在一片紧锣密鼓的北伐声中，当然...", "authors": ["马群"], "pressName": "上海辞书出版社"}]', '杨升菴《词品》：辛词当以京口北固亭怀古《永遇乐》为第一。', 'indent', 1413385187, '57b908e4165abd0054c00dcb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10216, '蜀道难', NULL, 1940, 1052, 3, 11, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/155370/6183241.htm', '', '噫吁嚱，危乎高哉！蜀道之难，难于上青天！蚕丛及鱼凫，开国何茫然！尔来四万八千岁，不与秦塞通人烟。西当太白有鸟道，可以横绝峨眉巅。地崩山摧壮士死，然后天梯石栈相钩连。上有六龙回日之高标，下有冲波逆折之回川。黄鹤之飞尚不得过，猿猱欲度愁攀援。青泥何盘盘，百步九折萦岩峦。扪参历井仰胁息，以手抚膺坐长叹。
问君西游何时还，畏途巉岩不可攀。但见悲鸟号古木，雄飞雌从绕林间。又闻子规啼夜月，愁空山。蜀道之难，难于上青天，使人听此凋朱颜！连峰去天不盈尺，枯松倒挂倚绝壁。飞湍瀑流争喧豗，砯崖转石万壑雷。其险也如此，嗟尔远道之人胡为乎来哉！
剑阁峥嵘而崔嵬，一夫当关，万夫莫开。所守或匪亲，化为狼与豺。朝避猛虎，夕避长蛇，磨牙吮血，杀人如麻。锦城虽云乐，不如早还家。蜀道之难，难于上青天，侧身西望长咨嗟。', '全诗二百九十四字，以山川之险言蜀道之难，给人以回肠荡气之感，充分显示了诗人的浪漫气质和热爱祖国河山的感情。诗中诸多的画面此隐彼现，无论是山之高，水之急，河山之改观，林木之荒寂，连峰绝壁之险，皆有逼人之势，其气象之宏伟，其境界之阔大，确非他人可及。正如清代诗评家沈德潜所盛称：「笔势纵横，如虬飞蠖动，起雷霆于指顾之间。」', '《蜀道难》：古乐府题，属《相和歌·瑟调曲》。
噫（yī）吁（xū）嚱（xī）：三个都是惊叹词。惊叹声，蜀方言，表示惊讶的声音。宋庠《宋景文公笔记·卷上》：「蜀人见物惊异，辄曰『噫吁嚱』。」
蚕丛及鱼凫（fú）：蚕丛、鱼凫，是传说中古蜀国两位国王的名字；难以考证。
何茫然：指古史传说悠远难详，不知道。据西汉·扬雄《蜀本王纪》记载：「蜀王之先，名蚕丛、柏灌、鱼凫，蒲泽、开明。……从开明上至蚕丛，积三万四千岁。」何，多么。茫然，完全不知道的样子。
尔来：从那时以来。尔，那，指开国之初。
四万八千岁：极言时间之漫长，夸张而大约言之。
秦塞：秦的关塞，指秦地。秦地四周有山川险阻，故称「四塞之地」。塞，山川险要的地方。
通人烟：人员往来。
西当太白有鸟道：意思是，（长安）西面有太白山（阻隔了入蜀之路），只有鸟儿飞行的路径。西当，在西边的，当，在。太白，太白山，又名太乙山，在长安西（今陕西眉县、太白县一带）。鸟道，指连绵高山间的低缺处，只有鸟能飞过，人迹所不能至。
横绝：横越，飞越。
峨眉巅：峨眉顶峰。
地崩山摧壮士死：《华阳国志·蜀志》：相传秦惠王想征服蜀国，知道蜀王好色，答应送给他五个美女。蜀王派五位壮士去接人。回到梓潼（今四川剑阁之南）的时候，看见一条大蛇进入穴中，一位壮士抓住了它的尾巴，其余四人也来相助，用力往外拽。不多时，山崩地裂，壮士和美女都被压死。山分为五岭，入蜀之路遂通。这便是有名的「五丁开山」的故事。摧，倒塌。
天梯：非常陡峭的山路。
石栈：俗称“栈道”，在山崖上凿石架木建成的通道。
上有六龙回日之高标：上面有迫使太阳神的车子掉头的高俊山峰。六龙回日，《淮南子》注云：「日乘车，驾以六龙。羲和御之。日至此面而薄于虞渊，羲和至此而回六螭。」，意思就是传说中的羲和驾驶着六龙之车（即太阳）到此处便迫近虞渊（传说中的日落处）；六龙，传说太阳神的车子由羲和驾驭六条龙拉着，每天在空中行驶。高标，指蜀山中可作一方之标识的最高峰。
下有冲波逆折之回川：下面有波涛滚滚的回旋的急流。冲波，水流冲击腾起的波浪，这里指激流。逆折，倒流，水流回旋。回川，有漩涡的河流。
黄鹤：黄鹄（hú），善飞的大鸟。
尚：尚且。
得：能。
猿猱（náo）：猿的一种，蜀山中最善攀援的猴类。
青泥：青泥岭，在今甘肃徽县南，陕西略阳县北。《元和郡县志·卷二十二》：「青泥岭，在县西北五十三里，接溪山东，即今通路也。悬崖万仞，山多云雨，行者屡逢泥淖，故号青泥岭。」
盘盘：（形容山路）曲折回旋的样子。
百步九折：百步之内拐九道弯。
萦：盘绕。
岩峦：山峰。
扪参（ménshēn）历井：意思是，山高入天，人在山上，可以用手触摸星星，甚至可以从它们中间穿过。参、井是二星宿名。古人把天上的星宿分别指配于地上的州国，叫做「分野」，以便通过观察天象来占卜地上所配州国的吉凶。参星为蜀之分野，井星为秦之分野。扪，用手摸；历，经过。
仰胁息：仰着头，屏住呼吸。胁息，屏气不敢呼吸。
膺：胸。
坐：徒，空。
君：入蜀的友人。
西游：指入蜀。
畏途：可怕的路途。
巉（chán）岩：险恶陡峭的山壁。
但见：只听见。
号（háo）古木：在古树木中大声啼鸣。
从：跟随。
子规：即杜鹃鸟，蜀地最多，鸣声悲哀，若云「不如归去」。《蜀记》曰：「昔有人姓杜名宇，王蜀，号曰『望帝』。宇死，俗说杜宇化为子规。子规，鸟名也。蜀人闻子规鸣，皆曰『望帝』也。」这两句也有断为「又闻子规啼，夜月愁空山」的，但不如此文这种断法顺。
凋朱颜：红颜带忧色，如花凋谢，这里是吓得脸变色的意思。凋，使动用法，使……凋谢，这里指脸色由红润变成铁青。
连峰去天不盈尺：绵延不断的山峰距天不足一尺。去，距离。盈，满、足。
飞湍（tuān）：飞奔而下的急流。湍，急流。
喧豗（huī）：喧闹声，这里指急流和瀑布发出的巨大响声。
砯（pīng）崖转石万壑雷：急流和瀑布冲击山崖，石块滚滚而下，千山万壑间响起雷鸣般的声音。砯崖，水撞石之声，砯，水冲击石壁发出的响声，这里作动词用，冲击的意思。转，使滚动。壑，山谷。
其险也如此：一作「其险也若此」。
嗟尔远道之人胡为乎来哉：唉，你这远方的人为什么到这里来呢？这是用蜀人的口气劝说“西游”的人不要来蜀地。嗟，叹惋之辞，感叹声。尔，你。胡为，为什么。乎，语助词，无义。来，指入蜀。
剑阁：又名剑门关，在四川剑阁县北，是大、小剑山之间的一条栈道，长约三十馀里。
峥嵘、崔嵬：形容山势高大雄峻的样子。
一夫当关，万夫莫开：形容剑阁易守难攻。《文选·卷四·左思·〈蜀都赋〉》：「一人守隘，万夫莫向」。《文选·卷五十六·张载·〈剑阁铭〉》：「一人荷戟，万夫趦趄。形胜之地，匪亲勿居。」一夫，一人；当关，守关；莫开，不能打开。
所守或匪亲，化为狼与豺：守关的将领倘若不是（自己的）亲信，就会变成叛乱者。所守，指把守关口的人。或匪亲：倘若不是可信赖的人；或，倘若；匪，同「非」。狼与豺，比喻叛乱的人。
朝：早上。
吮：吸。
锦城：成都古代以产棉闻名，朝廷曾经设官于此，专收棉织品，故称锦城或锦官城。《元和郡县志·卷三十一·〈剑南道·成都府·成都县〉》：「锦城在县南十里，故锦官城也。」今四川成都市。
咨嗟：叹息。', '啊！何其高峻，何其峭险！蜀道难走比登上青天还要难，古蜀国先王的事迹久远渺茫。岁月漫漫过去四万八千年，蜀道还未能与秦地相通人烟。西边太白山上只有一条鸟道，才能从秦地横越过峨眉山巅。山崩地裂压死迎亲的五壮士，才能修成栈道与陡峭山路相接。上有高峰神仙也要绕路而行，下有河川冲波倒流漩涡转动。翱翔高飞的黄鹤尚不能越渡，攀援敏捷的猿猱更一筹莫展。青泥河的小路曲折又蜿蜒，走一百步就要绕路而行，伸手可触星辰快快屏住呼吸，用手抚胸惊恐不已徒长吁短叹。
请问你这次西方游历何时归？山路险道峭岩实在难以攀登。只听见古树枝头飞鸟在哀号，雄雌相随林间飞绕徘徊不前。又听见月夜里杜鹃声声哀鸣，悲声回荡在空山中愁情更添。蜀道难走比登上青天还要难。此情景即使听说也要变容颜！绵延的山峰离天不到一尺远，倒挂的枯松斜倚绝壁悬崖边。瀑布飞泻激流涌争相喧嚣，撞击山岩的巨石响声似惊雷。蜀道这般艰险你为何来此呢？
更有崎岖高峻险恶的剑门关，一人把关万余人也休想进入。守关的将领倘若不可信则酿成大祸，那里早晚要避开猛虎和蛇。虎蛇磨牙吸人血好比斩乱麻，锦城虽说能享乐不如早回家。蜀道难走比登上青天还要难，回身向西望禁不住怅惘长叹。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929a0ce818559d058671", "shortContent": "这首诗，大约是唐玄宗天宝初年，李白第一次到长安时写的。《蜀道难》是他袭用乐府古题，展开丰富的想象，着力描绘了秦蜀道路上奇丽惊险的山川，并从中透露了对社会的某些忧虑与关切。\n诗人大体按照由古及今，自秦入蜀的线索，抓住各处山水特点来描写，以展示蜀道之难。\n从“噫吁嚱”到“然后天梯石栈相钩连”为一个段落。一开篇就极言蜀道之难，以感情强烈的咏叹点出主题，为全诗奠定了雄放的基调。以下随着感情的起伏和自然场景...", "authors": ["阎昭典"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc40930", "shortContent": "这首诗，大约是唐玄宗天宝初年，李白第一次到长安时写的。《蜀道难》是他袭用乐府古题，展开丰富的想象，着力描绘了秦蜀道路上奇丽惊险的山川，并从中透露了对社会的某些忧虑与关切。\n\n诗人大体按照由古及今、自秦入蜀的线索，抓住各处山水特点来描写，以展示蜀道之难。\n\n从“噫吁嚱”到“然后天梯石栈相钩连”为一个段落。一开篇就极言蜀道之难，以感情强烈的咏叹点出主题，为全诗奠定了雄放的基调。以下随着感情的起伏和自然...", "authors": ["阎昭典"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f09308", "shortContent": "《蜀道难》本为南朝乐府旧题，属“相和歌辞”中的“瑟调曲”。郭茂倩《乐府诗集》卷四十引《乐府解题》说：“《蜀道难》备言铜梁、玉垒之阻。”而自梁简文帝至初唐张文琮，已有一些写入蜀之难的诗篇。李白此诗，唐代以来就有种种猜测，或认为是为房琯、杜甫而作，担忧他们遭受剑南节度使严武的迫害；或认为是讽刺唐玄宗幸蜀之非；或认为是讽刺章仇兼琼之飞扬跋扈；或认为是自为蜀咏，别无寓意。今人詹瑛则认为是送友人入蜀而作。但...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312704d73206168b2e021d8", "shortContent": "《蜀道难》本为南朝乐府旧题，属“相和歌辞”中的“瑟调曲”。郭茂倩《乐府诗集》卷四十引《乐府解题》说：“《蜀道难》备言铜梁、玉垒之阻。”而自梁简文帝至初唐张文琮，已有一些写入蜀之难的诗篇。李白此诗，唐代以来就有种种猜测，或认为是为房琯、杜甫而作，担忧他们遭受剑南节度使严武的迫害，或认为是讽刺唐玄宗幸蜀之非，或认为是讽刺章仇兼琼之飞扬跋扈，或认为是自为蜀咏，别无寓意。今人詹瑛则认为是送友人入蜀而作。但...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127078f2af4e09d55b679f", "shortContent": "《蜀道难》本为南朝乐府旧题，属“相和歌辞”中的“瑟调曲”。郭茂倩《乐府诗集》卷四十引《乐府解题》说：“《蜀道难》备言铜梁、玉垒之阻。”而自梁简文帝至初唐张文琮，已有一些写入蜀之难的诗篇。李白此诗，唐代以来就有种种猜测，或认为是为房琯、杜甫而作，担忧他们遭受剑南节度使严武的迫害，或认为是讽刺唐玄宗幸蜀之非，或认为是讽刺章仇兼琼之飞扬跋扈，或认为是自为蜀咏，别无寓意。今人詹瑛则认为是送友人入蜀而作。但...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6466c6a0e49f46528aadc4d4", "shortContent": "这首诗，大约是唐玄宗天宝初年，李白第一次到长安时写的。《蜀道难》是他袭用乐府古题，展开丰富的想象，着力描绘了秦蜀道路上奇丽惊险的山川，并从中透露了对社会的某些忧虑与关切。\n\n诗人大体按照由古及今，自秦入蜀的线索，抓住各处山水特点来描写，以展示蜀道之难。\n\n从“噫吁嚱”到“然后天梯石栈相钩连”为一个段落。一开篇就极言蜀道之难，以感情强烈的咏叹点出主题，为全诗奠定了雄放的基调。以下随着感情的起伏和自然...", "authors": ["阎昭典"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f2c9cb6a81d0c531ff987", "shortContent": "这首诗，大约是唐玄宗天宝初年，李白第一次到长安时写的。《蜀道难》是他袭用乐府古题，展开丰富的想象，着力描绘了秦蜀道路上奇丽惊险的山川，并从中透露了对社会的某些忧虑与关切。\n诗人大体按照由古及今，自秦入蜀的线索，抓住各处山水特点来描写，以展示蜀道之难。\n从“噫吁嚱”到“然后天梯石栈相钩连”为一个段落。一开篇就极言蜀道之难，以感情强烈的咏叹点出主题，为全诗奠定了雄放的基调。以下随着感情的起伏和自然场景...", "authors": ["闫昭典"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "64732d1030675327e1c56e9c", "shortContent": "这首诗，大约是唐玄宗天宝初年，李白第一次到长安时写的。全诗袭用乐府古题，展开丰富的想像，着力描绘了秦蜀道路上奇丽惊险的山川，并从中透露了作者对社会的某些忧虑与关切。\n\n诗人大体按照由古及今，自秦入蜀的线索，抓住各处山水特点来描写，以展示蜀道之难。\n\n从“噫吁嚱”到“然后天梯石栈相钩连”为一个段落。一开篇就极言蜀道之难，以感情强烈的咏叹点出主题，为全诗奠定了雄放的基调。以下随着感情的起伏和自然场景的...", "authors": ["阎昭典"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "64733d5182772d45942cc56f", "shortContent": "这首诗，大约是唐玄宗天宝初年，李白第一次到长安时写的。全诗袭用乐府古题，展开丰富的想像，着力描绘了秦蜀道路上奇丽惊险的山川，并从中透露了作者对社会的某些忧虑与关切。\n\n诗人大体按照由古及今，自秦入蜀的线索，抓住各处山水特点来描写，以展示蜀道之难。\n\n从“噫吁嚱”到“然后天梯石栈相钩连”为一个段落。一开篇就极言蜀道之难，以感情强烈的咏叹点出主题，为全诗奠定了雄放的基调。以下随着感情的起伏和自然场景的...", "authors": ["阎昭典"], "pressName": "上海辞书出版社"}]', '', 'indent', 1416860024, '57b908b07db2a2005426db2c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10217, '下终南山过斛斯山人宿置酒', NULL, 1564, 1052, 3, 3, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383016.htm', '', '暮从碧山下，山月随人归。
却顾所来径，苍苍横翠微。
相携及田家，童稚开荆扉。
绿竹入幽径，青萝拂行衣。
欢言得所憩，美酒聊共挥。
长歌吟松风，曲尽河星稀。
我醉君复乐，陶然共忘机。', '此诗以田家、饮酒为题材，前四句写诗人下山归途所见，中间四句写诗人到斛斯山人家所见，末六句写两人饮酒交欢及诗人的感慨，全用赋体写成，流露了诗人相携欢言，置酒共挥，长歌风松，赏心乐事，自然陶醉忘机的感情。全诗情景交融，色彩鲜明，神情飞扬，语言淳厚质朴，风格真率自然。', '终南山：即秦岭，在今陕西省西安市南，唐时士子多隐居于此山。
过：拜访。
斛（hú）斯山人：复姓斛斯的一位隐士。
碧山：指终南山。
下：下山。
却顾：回头望。
所来径：下山的小路。
苍苍：一说是指灰白色，但这里不宜作此解，而应解释苍为苍翠、苍茫，苍苍叠用是强调群山在暮色中的那种苍茫貌。
翠微：青翠的山坡，此处指终南山。
相携：下山时路遇斛斯山人，携手同去其家。
及：到。
田家：田野山村人家，此指斛斯山人家。
荆扉：柴门，以荆棘编制。
青萝：攀缠在树枝上下垂的藤蔓。
行衣：行人的衣服。
挥：举杯。
松风：古乐府琴曲名，即《风入松曲》，此处也有歌声随风而入松林的意思。
河星稀：银河中的星光稀微，意谓夜已深了。
河星：一作“星河”。
陶然：欢乐的样子。
忘机：忘记世俗的机心，不谋虚名蝇利。
机：机巧之心。', '傍晚从终南山上走下来，山月好像随着行人而归。
回望来时走的山间小路，山林苍苍茫茫一片青翠。
遇斛斯山人相携到他家，孩童出来急忙打开柴门。
走进竹林穿过幽静小路，青萝枝叶拂着行人衣裳。
欢言笑谈得到放松休息，畅饮美酒宾主频频举杯。
放声高歌风入松的曲调，歌罢银河星星已经很稀。
我喝醉酒主人非常高兴，欢乐忘了世俗奸诈心机。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929f5e272d4b225431c6", "shortContent": "我国的田园诗以东晋陶潜为开山祖，他的诗，对后代影响很大。李白这首田园诗，似也有陶诗那种描写琐事人情，平淡爽直的风格。\n李白作此诗时，正在长安供奉翰林。从诗的内容看，诗人是在月夜到长安南面的终南山去造访一位姓斛斯的隐士。首句“暮从碧山下”，“暮”字挑起了第二句的“山月”和第四句的“苍苍”，“下”字挑起了第二句的“随人归”和第三句的“却顾”，“碧”字又逗出第四句的“翠微”。平平常常五个字，却无一字虚设...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac821a74606fc40946", "shortContent": "我国的田园诗以东晋陶潜为开山祖，他的诗对后代影响很大。李白这首田园诗，似也有陶诗那种描写琐事人情，平淡爽直的风格。\n\n李白作此诗时，正在长安供奉翰林。从诗的内容看，诗人是在月夜到长安南面的终南山去造访一位姓斛斯的隐士。首句“暮从碧山下”，“暮”字挑起了第二句的“山月”和第四句的“苍苍”，“下”字挑起了第二句的“随人归”和第三句的“却顾”，“碧”字又逗出第四句的“翠微”。平平常常五个字，却无一字虚设...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d90", "shortContent": "这首诗写于李白在长安供奉翰林时，描述自己在钟南山游玩并造访山中隐士，与其相携欢言，置酒共挥，长歌风松，赏心乐事。\n\n“暮从碧山下，山月随人归。却顾所来径，苍苍横翠微。”全诗以“暮”首领。暮色四合，山上月色如影随形。诗人从山上归来，荷着温婉月色，步履轻快。但心中却含着对那山景的不舍，蓦然回首，只见那苍茫野绿充盈眼前，那一脉温润翠绿轻轻地在自己行过的小径间蔓延开来。那恢宏的暮色沾染着那深绿的碧山，又渐...", "authors": ["孟佳"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6467611030675327e194ac08", "shortContent": "我国的田园诗以东晋陶潜为开山祖，他的诗，对后代影响很大。李白这首田园诗，似也有陶诗那种描写琐事人情，平淡爽直的风格。\n\n李白作此诗时，正在长安供奉翰林。从诗的内容看，诗人是在月夜到长安南面的终南山去造访一位姓斛斯的隐士。首句“暮从碧山下”，“暮”字挑起了第二句的“山月”和第四句的“苍苍”，“下”字挑起了第二句的“随人归”和第三句的“却顾”，“碧”字又逗出第四句的“翠微”。平平常常五个字，却无一字虚...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}]', '', 'center', 1413387871, '57b900307db2a20054269a2a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10218, '听蜀僧濬弹琴', NULL, 349, 1052, 3, 2, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383266.htm', '', '蜀僧抱绿绮，西下峨眉峰。
为我一挥手，如听万壑松。
客心洗流水，余响入霜钟。
不觉碧山暮，秋云暗几重。', '此诗写听蜀地一位和尚弹琴技艺之高妙，极写琴声之入神。首联写和尚来自故乡四川，表达对他的倾慕；颔联写弹琴，以大自然的万壑松涛声作比，令人感到琴声之不凡；颈联写琴声荡涤胸怀，使人心旷神怡，回味无穷；尾联写聚精会神听琴，而不知时日将尽，反衬琴声之高妙诱人。全诗一气呵成，势如行云流水，明快畅达，风韵健爽，在赞美琴声美妙的同时，也寓有知音的感慨和对故乡的眷恋。', '蜀僧濬：即蜀地的僧人名濬的。有人认为“蜀僧濬”即李白集中《赠宣州灵源寺仲濬公》中的仲濬公。
绿绮（qǐ）：琴名。晋傅玄《琴赋序》：“楚王有琴曰绕梁，司马相如有绿绮，蔡邕有焦尾，皆名器也。”诗中以绿绮形容蜀僧濬的琴很名贵。
峨眉：山名，在四川省峨眉县。
一：助词，用以加强语气。挥手：这里指弹琴。
万壑（hè）松：指万壑松声。这是以万壑松声比喻琴声。琴曲有《风入松》。壑：山谷。这句是说，听了蜀僧濬的琴声好像听到万壑松涛雄风。
“客心”句：意思是说，听了蜀僧濬弹的美妙琴声，客中郁结的情怀，像经过流水洗了一样感到轻快。客：诗人自称。流水：《列子·汤问》：“伯牙鼓瑟，志在高山，钟子期曰：‘峨峨然若泰山；’志在流水，曰：‘洋洋乎若江河。’子期死，伯牙绝弦，以无知音者。”这句诗中的“流水”，语意双关，既是对僧濬琴声的实指，又暗用了伯牙善弹的典故。
余响：指琴的余音。霜钟：指钟声。
“碧山”句：意思是说，因为听得入神，不知不觉天就黑下来了。
秋云：秋天的云彩。暗几重：意即更加昏暗了，把上句“暮”字意伸足。', '蜀僧怀抱着绿绮琴，来自遥远的峨眉山。
为我随意挥手一弹，如同听到万壑松声。
余音袅袅，汇入霜天钟声，我心清静，如经流水洗过。
不知不觉，暮色笼罩青山，秋云黯淡，布满黄昏天空。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a27d0ac11454953752", "shortContent": "这首五律写的是听琴，听蜀地一位法名叫濬的和尚弹琴。\n开头两句：“蜀僧抱绿绮，西下峨眉峰。”说明这位琴师是从四川峨眉山下来的。李白是在四川长大的，四川奇丽的山水培育了他的壮阔胸怀，激发了他的艺术想象。峨眉山月不止一次地出现在他的诗里。他对故乡一直很怀恋，对于来自故乡的琴师当然也格外感到亲切。所以诗一开头就说明弹琴的人是自己的同乡。“绿绮”本是琴名，汉代司马相如有一张琴，名叫绿绮，这里用来泛指名贵的琴...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d10d", "shortContent": "这首五律写的是听琴，听蜀地一位法名叫濬的和尚弹琴。\n\n开头两句：“蜀僧抱绿绮，西下峨眉峰。”说明这位琴师是从四川峨眉山下来的。李白是在四川长大的，四川奇丽的山水培育了他的壮阔胸怀，激发了他的艺术想象。峨眉山月不止一次地出现在他的诗里。他对故乡一直很怀恋，对于来自故乡的琴师当然也格外感到亲切。所以诗一开头就说明弹琴的人是自己的同乡。“绿绮”本是琴名，汉代司马相如有一张琴，名叫绿绮，这里用来泛指名贵的...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151ca", "shortContent": "“蜀僧浚”，即四川一位名为浚的和尚。有人认为他就是李白《赠宣州灵源寺仲浚公》中的仲浚和尚。如果是这样，那么此公不但擅长琴术，而且“风韵逸江左，文章动海隅。观心同水月，解领得明珠”。这首诗主要写浚公琴术之高超。\n\n诗歌从演奏之人写起，蜀僧浚抱着绿绮古琴，从“秀甲天下”的峨眉山而来。李白在诗中多次提到峨眉山，它是诗人心目中故乡的象征，所以从千里之外的故乡而来的蜀僧，首先就给他一种亲切之感。诗人省掉了浚...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127052c305cf0801816f53", "shortContent": "“蜀僧濬”，即四川一位名为濬的和尚。有人认为他就是李白《赠宣州灵源寺仲濬公》中的仲濬和尚。如果是这样，那么此公不但擅长琴术，而且“风韵逸江左，文章动海隅。观心同水月，解领得明珠”。这首诗主要写濬公琴术之高超。\n\n诗歌从演奏之人写起，蜀僧濬抱着绿绮古琴，从“秀甲天下”的峨眉山而来。李白在诗中多次提到峨眉山，它是诗人心目中故乡的象征，所以从千里之外的故乡而来的蜀僧，首先就给他一种亲切之感。诗人省掉了濬...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "64676b145e6bb82b8ccfee82", "shortContent": "这首五律写的是听琴，听蜀地一位法名叫濬的和尚弹琴。\n\n开头两句：“蜀僧抱绿绮，西下峨眉峰。”说明这位琴师是从四川峨眉山下来的。李白是在四川长大的，四川奇丽的山水培育了他的壮阔胸怀，激发了他的艺术想象。峨眉山月不止一次地出现在他的诗里。他对故乡一直很怀恋，对于来自故乡的琴师当然也格外感到亲切。所以诗一开头就说明弹琴的人是自己的同乡。“绿绮”本是琴名，汉代司马相如有一张琴，名叫绿绮，这里用来泛指名贵的...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}]', '清高宗敕《唐宋诗醇》：累累如贯珠，冷冷如口玉，斯为雅奏清音。', 'center', 1362670109, '57b92891a633bd00665e9f26', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10219, '登金陵凤凰台', NULL, 1060, 1052, 3, 4, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155438.htm', '', '凤凰台上凤凰游，凤去台空江自流。
吴宫花草埋幽径，晋代衣冠成古丘。
三山半落青天外，二水中分白鹭洲。
总为浮云能蔽日，长安不见使人愁。', '此诗是唐代伟大诗人李白登金陵凤凰台而创作的怀古抒情之作。全诗八句五十六字，以登临凤凰台时的所见所感而起兴唱叹，把天荒地老的历史变迁与悠远飘忽的传说故事结合起来摅志言情，用以表达深沉的历史感喟与清醒的现实思索。此诗气韵高古，格调悠远，体现了李白诗歌以气夺人的艺术特色。', '凤凰台：在金陵凤凰山上。据《江南通志》载：「凤凰台在江宁府城内之西南隅，犹有陂陀，尚可登览。宋元嘉十六年，有三鸟翔集山间，文彩五色，状如孔雀，音声谐和，众鸟群附，时人谓之凤凰。起台于山，谓之凤凰山，里曰凤凰里。」
江：长江。
吴宫：三国时孙吴曾于金陵建都筑宫。
晋代：指东晋，南渡后也建都于金陵。
衣冠：指的是东晋文学家郭璞的衣冠冢。现今仍在南京玄武湖公园内。一说指当时豪门世族。衣冠，士大夫的穿戴，借指士大夫、官绅。
成古丘：晋明帝当年为郭璞修建的衣冠冢豪华一时，然而到了唐朝诗人来看的时候，已经成为一个丘壑了。现今这里被称为郭璞墩，位于南京玄武湖公园内。
三山：山名。据《景定建康志》载：「其山积石森郁，滨于大江，三峰并列，南北相连，故号三山」。今三山街为其旧址，明初朱元璋筑城时，将城南的三座无名小山也围在了城中。这三座山正好挡住了从城北通向南门──聚宝门的去路。恰逢当时正在城东燕雀湖修筑宫城，于是将这三座山填进了燕雀湖。三山挖平后，在山基修了一条街道，取名为三山街。半落青天外：形容极远，看不大清楚。
二水：一作「一水」。指秦淮河流经南京后，西入长江，被横截其间的白鹭洲分为二支。
白鹭洲：白鹭洲：古代长江中的沙洲，洲上多集白鹭，故名。今已与陆地相连，位于今南京市江东门外。
浮云蔽日：比喻谗臣当道障蔽贤良。浮云，比喻奸邪小人。陆贾《新语·慎微篇》：「邪臣之蔽贤，犹浮云之障日月也。」日，一语双关，因为古代把太阳看作是帝王的象征。', '凤凰台上曾经有凤凰来悠游，凤去台空只有江水依旧东流。
吴宫鲜花芳草埋着荒凉小径，晋代多少王族已成荒冢古丘。
三山云雾中隐现如落青天外，江水被白鹭洲分成两条河流。
总有奸臣当道犹如浮云遮日，长安望不见心中郁闷长怀愁。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a034a8757d5a0e1c41", "shortContent": "李白很少写律诗，而《登金陵凤凰台》却是唐代的律诗中脍炙人口的杰作。此诗是作者流放夜郎遇赦返回后所作，一说是作者天宝年间，被排挤离开长安（今陕西西安），南游金陵（今江苏南京）时所作。\n开头两句写凤凰台的传说，十四字中连用了三个“凤”字，却不嫌重复，音节流转明快，极其优美。“凤凰台”在金陵凤凰山上，相传南朝刘宋永嘉年间有凤凰集于此山，乃筑台，山和台也由此得名。在封建时代，凤凰是一种祥瑞。当年凤凰来游象...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d107", "shortContent": "李白很少写律诗，而《登金陵凤凰台》却是唐代的律诗中脍炙人口的杰作。此诗是作者流放夜郎遇赦返回后所作，一说是作者天宝年间，被排挤离开长安（今陕西西安），南游金陵（今江苏南京）时所作。\n\n开头两句写凤凰台的传说，十四字中连用了三个“凤”字，却不嫌重复，音节流转明快，极其优美。“凤凰台”在金陵凤凰山上，相传南朝刘宋永嘉年间有凤凰集于此山，乃筑台，山和台也由此得名。在封建时代，凤凰是一种祥瑞。当年凤凰来游...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d19330151fe", "shortContent": "据说在天宝三年（744）左右，李白登上黄鹤楼，看到崔颢的《黄鹤楼》诗赞叹不已。江山如画，他诗兴大发，也欲挥笔题诗，但想来想去，总是跳不出崔颢诗的意境，只好搁笔叹道：“眼前有景道不得，崔颢题诗在上头。”这让自负的诗人非常沮丧，为此耿耿于怀。三年后，他来到金陵，登上凤凰台，郁积已久的情感终于找到了突破口，一气呵成，写出了这首志在与崔颢《黄鹤楼》一较高下的《登金陵凤凰台》。\n\n凤凰台，故址在今南京市凤凰...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127052c305cf0801816f64", "shortContent": "据说在天宝三载（744）左右，李白登上黄鹤楼，看到崔颢的《黄鹤楼》诗赞叹不已。江山如画，他诗兴大发，也欲挥笔题诗，但想来想去，总是跳不出崔颢诗的意境，只好搁笔叹道：“眼前有景道不得，崔颢题诗在上头。”这让自负的诗人非常沮丧，为此耿耿于怀。三年后，他来到金陵，登上凤凰台，郁积已久的情感终于找到了突破口，一气呵成，写出了这首志在与崔颢《黄鹤楼》一较高下的《登金陵凤凰台》。\n\n凤凰台，故址在今南京市凤凰...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270a5e6f69b71e93f632f", "shortContent": "据说在天宝三年（744）左右，李白登上黄鹤楼，看到崔颢的《黄鹤楼》诗赞叹不已。江山如画，他诗兴大发，也欲挥笔题诗，但想来想上，总是跳不出崔颢诗的意境，只好搁笔叹道：“眼前有景道不得，崔颢题诗在上头。”这让自负的诗人非常沮丧，为此耿耿于怀。三年后，他来到金陵，登上凤凰台，郁积已久的情感终于找到了突破口，一气呵成，写出了这首志在与崔颢《黄鹤楼》一较高下的《登金陵凤凰台》。\n\n凤凰台，故址在今南京市凤凰...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "646763095e6bb82b8ccfc0a8", "shortContent": "李白很少写律诗，而《登金陵凤凰台》却是唐代的律诗中脍炙人口的杰作。此诗是作者流放夜郎遇赦返回后所作，一说是作者天宝年间，被排挤离开长安（今陕西西安），南游金陵（今江苏南京）时所作。\n\n开头两句写凤凰台的传说，十四字中连用了三个“凤”字，却不嫌重复，音节流转明快，极其优美。“凤凰台”在金陵凤凰山上，相传南朝刘宋永嘉年间有凤凰集于此山，乃筑台，山和台也由此得名。在封建时代，凤凰是一种祥瑞。当年凤凰来游...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}]', '《珊瑚钩诗话》：金陵凤凰台，在城之东南，四顾江山，下窥井邑，古题咏惟谪仙为绝唱。
《瀛奎律髓》：太白此诗与崔颢《黄鹤楼》相似，格律气势未易甲乙。此诗以凤凰台为名，而咏凤凰台不过起二语已尽之矣。下六句乃登台而观望之景也。三、四怀古人之不见也。五、六、七、八咏今日之景，而慨帝都之不可见也。登台而望，所感深矣。金陵建都自吴始，三山、二水，白鹭洲，皆金陵山水名。金陵巧以北望中原唐都长安，故太白以浮云遮蔽，不见长安为愁焉。
《唐诗品汇》：范德机云：登临诗首尾好，结更悲壮，七言律之可法者也。刘须溪云：其开口雄伟、脱落雕饰俱不论，若无后两句，亦不必作。出下崔颢而待胜之，以此云（「总为浮云」二句下）。
《归田诗话》：崔颢题黄鹤楼，太白过之不更作。时人有「眼前有景道不得，崔颢题诗在上头」之讥。及登凤凰台作诗，可谓十倍曹丕矣。盖颢结句云：「日暮乡关何处是，烟波江上使人愁。」而太白结句云：「总为浮云能蔽日，长安不见使人愁。」爱君忧国之意，远过乡关之念。善占地步矣！
《唐诗广选》：王元美曰：《凤凰台》效颦崔颢，可厌。次联亦非作手。律无全盛者，惟得此篇及「借问欲栖珠树鹤，何年却向帝城飞」两结耳。
《唐诗直解》：一气嘘成，但二联仍不及崔。
《艺圃撷馀》：崔郎中作《黄鹤楼》诗，青莲短气。后题凤凰台，古今目为勍敌。识者谓前六句不能当，结语深悲慷慨，差足胜耳。然馀意更有不然。无论中二联不能及，即结语亦大有辨。言诗须道兴、比、赋，如「日暮乡关」，兴而赋也。「浮云蔽日」，比而赋也。以此思之，「使人愁」三字虽同，孰为当乎？「日暮乡关」、「烟波江上」，本无指著，登临者自生愁耳，故曰：「使人愁」，烟波使之愁也。「浮云蔽日」、「长安不见」，逐客自应愁，宁须使之？青莲才情标映万载，宁以予言重轻？尺有所短，寸有所长，窃以为此诗不逮，非一端也。如有罪我者，则不敢辞。
《诗薮》：崔颢《黄鹤楼》、李白《凤凰台》，但略点题面，未尝题黄鹤、凤凰也。……故古人之作，往往神韵超然，绝去斧凿。
《唐诗选脉会通评林》：周敬曰：读此诗，知太白眼空法界，以感生愁，勍敌《黄鹤楼》。一结实胜之。周珽曰：胸中笼盖，口里吐吞。眼前光景，又岂虑说不尽耶？
《唐诗评选》：「浮云蔽日」、「长安不见」，借晋明帝语影出。「浮云」以悲江左无人中原沦陷；「使人愁」三字总结「幽径」、「古丘」之感，与崔颢《黄鹤楼》落句语同意别。宋人不解此，乃以疵其不及颢作，觌面不识，而强加长短，何有哉！太白诗是通首混收，颢诗是扣尾掉收；太白诗自《十九首》来，颢诗则纯为唐音矣。
《贯华堂选批唐才子诗》：此二句，只是承上「凤去台空」，极写人世沧桑。然而先生妙眼妙手，于写吴后偏又写晋，此是其胸中实实看破得失成败，是非赞骂，一总只如电拂。我恶乎知甲子兴必贤于甲子亡，我恶乎知收瓜豆人之必便宜于种瓜豆人哉！此便是《仁王经》中最尊胜偈（「吴宫花草」二句下）。看先生前后二解文，直各自顿挫，并不牵合顾盼，此为大家风轨。', 'center', 1417427633, '57b8bea01532bc005b9a16aa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (33761, '一落索 · 新柳', NULL, 0, 169, 0, 1, '邵亨贞', NULL, 10917, '5858e5f461ff4b006875be34', '元', 'ci', '词', 'https://baike.baidu.com/item/%E4%B8%80%E8%90%BD%E7%B4%A2%E6%96%B0%E6%9F%B3/17555428', '', '陌上东风初转。暗黄犹浅。金鞭拂雪记章台，是几度、朱门掩。
千缕柔丝迎面。吹笙人远。妆楼妒冷绣帘垂，恐误了、双双燕。', '', '', '', NULL, '', 'indent', 1532626236, '585cdd9f8d6d810065db4ba0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (33762, '一落索 · 新柳', NULL, 0, 169, 0, 1, '邵亨贞', NULL, 10917, '5858e5f461ff4b006875be34', '元', 'ci', '词', NULL, NULL, '缕缕鹅黄拂晓。弄烟轻袅。宜春花外万丝金，记朝罢、惊啼早。
学舞楚腰犹小。不禁寒悄。近来张绪减风流，又恐被、蛾眉恼。', NULL, NULL, NULL, NULL, NULL, 'indent', 1532626246, '585cdd9f1b69e600560e3f16', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10220, '临江仙', NULL, 1454, 1556, 5, 5, '杨慎', NULL, 10059, '57b9b9d5a633bd005d2ee74f', '明', 'ci', '词', 'http://baike.baidu.com/view/417587.htm', '', '滚滚长江东逝水，浪花淘尽英雄。是非成败转头空。青山依旧在，几度夕阳红。
白发渔樵江渚上，惯看秋月春风。一壶浊酒喜相逢。古今多少事，都付笑谈中。', '此词是明代文学家杨慎所作《廿一史弹词》第三段《说秦汉》的开场词，后毛宗岗父子评刻《三国演义》时将其放在卷首。央视版电视剧《三国演义》将其作为主题歌歌词。
从全词看，基调慷慨悲壮，意味无穷，令人读来荡气回肠，不由得在心头平添万千感慨。在让读者感受苍凉悲壮的同时，这首词又营造出一种淡泊宁静的气氛，并且折射出高远的意境和深邃的人生哲理。作者试图在历史长河的奔腾与沉淀中探索永恒的价值，在成败得失之间寻找深刻的人生哲理，有历史兴衰之感，更有人生沉浮之慨，体现出一种高洁的情操、旷达的胸怀。', '淘尽：荡涤一空。
渚（zhǔ）：水中的小块陆地。', '滚滚长江向东流，不再回头，多少英雄像翻飞的浪花般消逝，争什么是与非、成功与失败，都是短暂不长久，只有青山依然存在，依然的日升日落。江上白髮渔翁，早已习惯于四时的变化，和朋友难得见了面，痛快地畅饮一杯酒，古往今来的纷纷扰扰，都成为下酒闲谈的材料。', NULL, '', 'indent', 1362670416, '57b8fa61df0eea006334b2d4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10222, '破阵子 · 为陈同甫赋壮词以寄之', NULL, 1448, 793, 4, 17, '辛弃疾', NULL, 10003, '57b8ed682e958a005fa4d096', '宋', 'ci', '词', 'http://baike.baidu.com/view/2305079.htm', '', '醉里挑灯看剑，梦回吹角连营。八百里分麾下炙，五十弦翻塞外声，沙场秋点兵。
马作的卢飞快，弓如霹雳弦惊。了却君王天下事，赢得生前身后名。可怜白发生！', '此词通过对作者早年抗金部队豪壮的阵容和气概以及自己沙场生涯的追忆，表达了作者杀敌报国、收复失地的理想，抒发了壮志难酬、英雄迟暮的悲愤心情；通过创造雄奇的意境，生动地描绘出一位披肝沥胆、忠一不二、勇往直前的将军形象。全词在结构上打破成规，前九句为一意，末一句另为一意，以末一句否定前九句，前九句写得酣恣淋漓，正为加重末五字失望之情，这种艺术手法体现了辛词的豪放风格和独创精神。', '“为陈同甫赋壮词以寄之”：四卷本丁集作“为陈同父赋壮词以寄”。
陈同甫：陈亮（公元1143年—公元1194年），字同父（甫），号龙川，婺州永康（今属浙江）人，才气超迈，曾三上书孝宗，反对议和。光宗策进士，擢第一，授签书建康府判官，未赴任卒。有《龙川集》行世。《宋史·卷四百三十六·儒林》有传。
挑灯看剑：北宋·刘斧《青琐高议·卷三》载高言诗：“男儿慷慨平生事，时复挑灯把剑看。”挑灯，把灯芯挑亮；看剑，抽出宝剑来细看。
梦回：梦里遇见，说明下面描写的战场场景，不过是作者旧梦重温。
角：军中乐器，长五尺，形如竹筒，用竹、木、皮、铜制成，外加彩绘．名曰画角。始仅直吹，后用以横吹。其声哀厉高亢，闻之使人振奋。
吹角连营：各个军营里接连不断地响起号角声。
八百里：牛名。南朝宋·刘义庆《世说新语·汰侈》：“王君夫（恺）有牛，名‘八百里駮（bó）’，常瑩其蹄角。王武子（济）语君夫：‘我射不如卿，今指赌卿牛，以千万对之。’君夫既恃手快，且谓骏物无有杀理，便相然可。令武子先射。武子一起便破的，却据胡床，叱左右：‘速探牛心来！’须臾，炙至，一脔便去。”唐·韩愈《元和圣德诗》：“万牛脔炙，万瓮行酒。”宋·苏轼《约公择饮是日大风》诗：“要当啖公八百里，豪气一洗儒生酸。”唐·范摅《云溪友谈·卷下·杂嘲戏》：“李日新《题仙娥驿》诗曰：‘商山食店太悠悠，陈□䭔饠古䭃头。更有台中牛肉炙，尚盘数脔紫光毬。’”
麾下：部下。麾，军中大旗。
炙（zhì）：切碎的熟肉炙
分麾下炙：把烤牛肉分赏给部下。
五十弦：原指瑟，此处泛指各种乐器。《史记·卷二十八·封禅书》：“太帝使素女鼓五十弦瑟，悲，帝禁不止，故破其瑟为二十五弦。”唐·李商隐《锦瑟》：“锦瑟无端五十弦，一弦一柱思华年。”
翻：演奏。
塞外声：指悲壮粗犷的战歌
沙场：战场。
秋：古代点兵用武，多在秋天。
点兵：检阅军队。
的卢：良马名，一种烈性快马。《相马经》：“马白额入口齿者，名曰‘榆雁’，一名‘的卢’。”《三国志·卷三十二·〈蜀书·先主传〉》注引《世语》：“（刘）备屯樊城，刘表礼焉，惮其为人，不甚信用。曾请备宴会，蒯越、蔡瑁欲因会取备，备觉之，伪如厕，潜遁出。所乘马名的卢，骑的卢走，渡襄阳城西檀溪水中，溺不得出。备急曰：“的卢：今日厄矣，可努力！”的卢乃一踊三丈，遂得过，乘桴渡河。”
马作的卢飞快：战马像的卢马那样跑得飞快。作：像……一样。
霹雳：本是疾雷声，此处比喻弓弦响声之大。
弓如霹雳弦惊：《南史·卷五十五·曹景宗传》：“曹景宗，字子震，新野人也。……景宗幼善骑射，好畋猎，……景宗谓所亲曰：‘我昔在乡里，骑快马如龙，与年少辈数十骑，拓弓弦作霹雳声，箭如饿鸱叫，平泽中逐獐，数肋射之，渴饮其血，饥食其脯，甜如甘露浆。觉耳后生风，鼻头出火，此乐使人忘死，不知老之将至。……’”
了却：了结，把事情做完。
君王天下事：统一国家的大业，此特指恢复中原事。
赢得：博得。
身后：死后。
可怜：可惜。', '醉里挑亮油灯观看宝剑，梦中听到军营的号角声响成一片。把牛肉分给部下享用，让乐器奏起雄壮的军乐鼓舞士气。这是秋天在战场上阅兵。
战马像的卢马那样跑得飞快，弓箭像惊雷一样震耳离弦。一心想完成替君收复国家失地的大业，取得世代相传的美名。可惜壮志难酬，白发已生！', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74ec0ce818559d0508cd", "shortContent": "词以两个二、二、二的对句开头，通过具体描述，表现了七八层情意。第一句，只六个字，却用三个连续的、富有特征性的动作，塑造了一个壮士的形象，让读者从那些动作中去体会人物的“潜台词”，去想象人物所处的环境。为什么要吃酒，而且吃“醉”？既“醉”之后，为什么不去睡觉，而要“挑灯”？“挑”亮了“灯”，为什么不干别的，偏偏抽出宝剑，映着灯光看了又看？……这一连串问题，只要细读全词，就可能作出应有的回答，因而不必...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ee34a8757d5a0ecb2f", "shortContent": "词以两个二、二、二的对句开头，通过具体描述，表现了七八层情意。第一句，只六个字，却用三个连续的、富有特征性的动作，塑造了一个壮士的形象，让读者从那些动作中去体会人物的“潜台词”，去想象人物所处的环境。为什么要吃酒，而且吃“醉”？既“醉”之后，为什么不去睡觉，而要“挑灯”？“挑”亮了“灯”，为什么不干别的，偏偏抽出宝剑，映着灯光看了又看？……这一连串问题，只要细读全词，就可能作出应有的回答，因而不必...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255eebf5e0fdea508ed", "shortContent": "词以两个二、二、二的对句开头，通过具体描述，表现了七八层情意。第一句，只六个字，却用三个连续的、富有特征性的动作，塑造了一个壮士的形象，让读者从那些动作中去体会人物的“潜台词”，去想象人物所处的环境。为什么要吃酒，而且吃“醉”？既“醉”之后，为什么不去睡觉，而要“挑灯”？“挑”亮了“灯”，为什么不干别的，偏偏抽出宝剑，映着灯光看了又看？……这一连串问题，只要细读全词，就可能作出应有的回答，因而不必...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127044c305cf0801816f1e", "shortContent": "这首词是辛弃疾的经典之作，陈同甫即陈亮，是辛弃疾的志同道合之友。这首词通过描写词人早年在抗金战场上的军旅生涯，表达了词人对收复失地的渴望，对壮志未酬身已先老的悲愤之情。\n\n词的上片，“醉里挑灯看剑”一句是全词的引子。这一天的夜里，词人酒醉不成眠，他把灯芯挑亮，拿出那把曾随他征战四方的宝剑，抽出来反复摩挲。词人的记忆，仿佛回到了抗金的战场上，在那里，他听到了军营外号角声连成一片。在那峥嵘的岁月里，词...", "authors": ["陈庆之"], "pressName": "崇文书局"}, {"bookId": "64688f9830675327e19962ff", "bookTitle": "辛弃疾词鉴赏辞典（珍藏本）", "articleId": "64697fc6b6a81d0c5306f67d", "shortContent": "词以两个二、二、二的对句开头，通过具体描述，表现了七八层情意。第一句，只六个字，却用三个连续的、富有特征性的动作，塑造了一个壮士的形象，让读者从那些动作中去体会人物的“潜台词”，去想象人物所处的环境。为什么要吃酒，而且吃“醉”？既“醉”之后，为什么不去睡觉，而要“挑灯”？“挑”亮了“灯”，为什么不干别的，偏偏抽出宝剑，映着灯光看了又看？……这一连串问题，只要细读全词，就可能作出应有的回答，因而不必...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6472019345e4710056fc4a31", "shortContent": "同甫是陈亮的字。学者称为龙川先生。为人才气超迈，议论纵横。自称能够“推倒一世之智勇，开拓万古之心胸”。他先后写了《中兴五论》和《上孝宗皇帝书》，积极主张抗战，因而遭到投降派的打击。宋孝宗淳熙十五年(1188)冬天，他到上饶访辛弃疾，留十日。别后辛弃疾写《贺新郎》词寄他，他和了一首；以后又用同一词牌往复唱和。这首《破阵子》大约也是这一时期写的。\n全词从意义上看，前九句是一段，十分生动地描绘出一位忠勇...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472c93c30675327e1c37808", "shortContent": "词以两个二、二、二的对句开头，通过具体描述，表现了七八层情意。第一句，只六个字，却用三个连续的、富有特征性的动作，塑造了一个壮士的形象，让读者从那些动作中去体会人物的“潜台词”，去想象人物所处的环境。为什么要吃酒，而且吃“醉”？既“醉”之后，为什么不去睡觉，而要“挑灯”？“挑”亮了“灯”，为什么不干别的，偏偏抽出宝剑，映着灯光看了又看？……这一连串问题，只要细读全词，就可能作出应有的回答，因而不必...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '陈廷焯《云韶集》：字字跳掷而出，“沙场”五字，起一片秋声，沉雄悲壮，凌轹千古。
梁启超《艺蘅馆词选》：无限感慨，哀同甫亦自哀也。', 'indent', 1413206261, '57ae72402e958a005448a404', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10223, '雨霖铃·寒蝉凄切', NULL, 3867, 225, 7, 9, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/view/2789798.htm', '', '寒蝉凄切，对长亭晚，骤雨初歇。都门帐饮无绪，留恋处，兰舟催发。执手相看泪眼，竟无语凝噎。念去去，千里烟波，暮霭沉沉楚天阔。
多情自古伤离别，更那堪、冷落清秋节！今宵酒醒何处？杨柳岸，晓风残月。此去经年，应是良辰好景虚设。便纵有千种风情，更与何人说？', '此词上阕细腻刻画了情人离别的场景，抒发离情别绪；下阕着重摹写想象中别后的凄楚情状。全词遣词造句不着痕迹，绘景直白自然，场面栩栩如生，起承转合优雅从容，情景交融，蕴藉深沉，将情人惜别时的真情实感表达得缠绵悱恻，凄婉动人，堪称抒写别情的千古名篇，也是柳词和婉约词的代表作。', '雨霖铃：词牌名，也写作《雨淋铃》，调见《乐章集》。相传唐玄宗入蜀时在雨中听到铃声而想起杨贵妃，故作此曲。曲调自身就具有哀伤的成分。
秋别：兹从《钦定四库全书·乐章集》。
寒蝉：蝉的一种，又名寒蜩（tiáo）。
凄切：凄凉急促。
长亭：古代在交通要道边每隔十里修建一座长亭供行人休息，又称「十里长亭」。靠近城市的长亭往往是古人送别的地方。
都门：国都之门。这里代指北宋的首都汴京（今河南开封）。
帐饮：在郊外设帐饯行。
无绪：没有心思，心情不好。
留恋处：兹从《钦定四库全书·乐章集》。《强村丛书》本《乐章集》卷中作「留恋处」。按「方」为领起字，不宜简省。
兰舟：古代传说鲁班曾刻木兰树为舟（南朝梁·任昉《述异记》。这里用做对船的美称。
凝噎（yē）：喉咙哽塞，欲语不出的样子。一作「凝咽」，义同。
去去：重复「去」字，表示行程遥远。
暮霭（ǎi）：傍晚的云雾。
沉沉：深厚的样子。
楚天：指南方楚地的天空。
暮霭沉沉楚天阔：傍晚的云雾笼罩着南天，深厚广阔，不知尽头。
清秋节：凄清的秋节。
今宵：今夜。
经年：年复一年。
纵：即使。
千种风情：形容说不尽的相爱、相思之情。风情，情意，男女相爱之情，深情蜜意。情，一作「流」。
更：一作「待」。', '秋后的蝉叫得是那样地凄凉而急促，面对着长亭，正是傍晚时分，一阵急雨刚停住。在京都城外设帐饯别，却没有畅饮的心绪，正在依依不舍的时候，船上的人已催着出发。握着手互相瞧着，满眼泪花，直到最后也无言相对，千言万语都噎在喉间说不出来。想到这回去南方，这一程又一程，千里迢迢，一片烟波，那夜雾沉沉的楚地天空竟是一望无边。
自古以来多情的人最伤心的是离别，更何况又逢这萧瑟冷落的秋季，这离愁哪能经受得了！谁知我今夜酒醒时身在何处？怕是只有杨柳岸边，面对凄厉的晨风和黎明的残月了。这一去长年相别，相爱的人不在一起，我料想即使遇到好天气、好风景，也如同虚设。即使有满腹的情意，又能和谁一同欣赏呢？', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749d911759740c9aa2a8", "shortContent": "此词当为词人从汴京南下时与一位恋人的惜别之作。据传柳永因作词忤仁宗，遂“失意无俚，流连坊曲”，为歌伶乐伎撰写曲子词。由于得到艺人们的密切合作，他能变旧声为新声，在唐五代小令的基础上，创制了大量的慢词，使宋词开始了一个新的发展阶段。这首词调名《雨霖铃》，盖取唐时旧曲翻制。据《明皇杂录》云，安史之乱时，唐玄宗避地蜀中，于栈道雨中闻铃音，起悼念杨贵妃之思，“采其声为《雨霖铃》曲，以寄恨焉”。王灼《碧鸡漫...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a534a8757d5a0eca5e", "shortContent": "此词当为词人从汴京南下时与一位恋人的惜别之作。柳永因作词忤仁宗，遂“失意无俚，流连坊曲”，为歌伶乐伎撰写曲子词。由于得到艺人们的密切合作，他能变旧声为新声，在唐五代小令的基础上，创制了大量的慢词，使宋词开始了一个新的发展阶段。这首词调名《雨霖铃》，盖取唐时旧曲翻制。据《明皇杂录》云，安史之乱时，唐玄宗避地蜀中，于栈道雨中闻铃音，起悼念杨贵妃之思，“采其声为《雨霖铃》曲，以寄恨焉”。王灼《碧鸡漫志》...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252ccce4d48ba496d7b", "shortContent": "此词当为词人从汴京南下时与一位恋人的惜别之作。柳永因作词忤仁宗，遂“失意无俚，流连坊曲”，为歌伶乐伎撰写曲子词。由于得到艺人们的密切合作，他能变旧声为新声，在唐五代小令的基础上，创制了大量的慢词，使宋词开始了一个新的发展阶段。这首词调名《雨霖铃》，盖取唐时旧曲翻制。据《明皇杂录》云，安史之乱时，唐玄宗避地蜀中，于栈道雨中闻铃音，起悼念杨贵妃之思，“采其声为《雨霖铃》曲，以寄恨焉”。王灼《碧鸡漫志》...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f39e6f69b71e93f618a", "shortContent": "这是柳永词最负盛名的代表作，几乎所有的宋词选本都无所缺遗。词的背景是词人离开京城南下赴任，与恋人依依惜别。作者当时在仕途上失意，不得已离京远行，这种抑郁的心情和失去爱情慰藉的痛苦交织在一起，谱成了这首词的主旋律。词人把这个人人都会遇到的场景写得凄凄切切，十分感人，元人将它列为“宋金十大曲”之一。全词从“别”字生发，临别前—惜别时——别离后，由景及情，由情及景，层层铺叙开来。\n上片写一个深秋的傍晚，...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe47ccdb86c49f29178", "shortContent": "这是柳永词最负盛名的代表作，几乎所有的宋词选本都无所缺遗。词的背景是词人离开京城南下赴任，与恋人依依惜别。作者当时在仕途上失意，不得已离京远行，这种抑郁的心情和失去爱情慰藉的痛苦交织在一起，谱成了这首词的主旋律。词人把这个人人都会遇到的场景写得凄凄切切，十分感人，元人将它列为“宋金十大曲”之一。全词从“别”字生发，临别前——惜别时——别离后，由景及情，由情及景层层铺叙开来。\n\n上片写一个深秋的傍晚...", "authors": ["（周密）"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127174c305cf08018170ad", "shortContent": "这是柳永词最负盛名的代表作，几乎所有的宋词选本都无所缺遗。词的背景是词人离开京城南下赴任，与恋人依依惜别。作者当时在仕途上失意，不得已离京远行，这种抑郁的心情和失去爱情慰藉的痛苦交织在一起，谱成了这首词的主旋律。词人把这个人人都会遇到的场景写得凄凄切切，十分感人，元人将它列为“宋金十大曲”之一。全词从“别”字生发，临别前—惜别时—别离后，由景及情，由情及景，层层铺叙开来。\n上片写一个深秋的傍晚，寒...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d125c7af6de1647100d8a", "bookTitle": "柳永词鉴赏辞典", "articleId": "646d8e27902ee364cc82b2cd", "shortContent": "此词当为词人从汴京南下时与一位恋人的惜别之作。柳永因作词忤仁宗，遂“失意无俚，流连坊曲”，为歌伶乐伎撰写曲子词。由于得到艺人们的密切合作，他能变旧声为新声，在唐五代小令的基础上，创制了大量的慢词，使宋词开始了一个新的发展阶段。这首词调名《雨霖铃》，盖取唐时旧曲翻制。据《明皇杂录》云，安史之乱时，唐玄宗避地蜀中，于栈道雨中闻铃音，起悼念杨贵妃之思，“采其声为《雨霖铃》曲，以寄恨焉”。王灼《碧鸡漫志》...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}]', '明·李沧溟《草堂诗馀隽》：「千里烟波」，惜别之情已骋；「千种风情」，相期之愿又赊。真所谓善传神者。
清·贺黄公《皱水轩词筌》：柳屯田「今宵酒醒何处？杨柳岸，晓风残月」，自是古今俊句。
清·周止菴《宋四家词选》：清真词多从耆卿夺胎，思力沉挚处，往往出蓝。然耆卿秀淡幽艳，是不可及。
清·沈偶僧《古今词话·词话上卷》引俞文蔚《吹剑录》：东坡在玉堂日，有幕士善歌，因问：「我词何如柳七？」对曰：「柳郎中词，衹合十七八女郎，执红牙板，歌『杨柳岸、晓风残月』。学士词，须关西大汉、铜琵琶、铁绰板，唱『大江东去』。」东坡为之绝倒。
清·刘融斋《艺概·词概》：词有点，有染。柳耆卿《雨霖铃》云：「多情自古伤离别，更那堪冷落清秋节。今宵酒醒何处？杨柳岸、晓风残月。」
现·唐季特《唐宋词简释》：此首写别情，尽情展衍，备足无馀，浑厚绵密，兼而有之。宋於庭谓柳词多「精金粹玉」，殆谓此类。词末馀恨无穷，馀味不尽。', 'indent', 1413129905, '57ad742f5bbb500062bc7c9c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10224, '蝶恋花 · 伫倚危楼风细细', NULL, 1130, 225, 4, 5, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/view/2790080.htm', '', '伫倚危楼风细细，望极春愁，黯黯生天际。草色烟光残照里，无言谁会凭阑意。
拟把疏狂图一醉，对酒当歌，强乐还无味。衣带渐宽终不悔，为伊消得人憔悴。', '此词上阕写登高望远所引起的无尽离愁，以迷离的景物描写渲染出凄楚悲凉的气氛；下阕写主人公为消释离愁决意痛饮狂歌，但强颜为欢终觉无味，最后以健笔写柔情，自誓甘愿为思念伊人而日渐消瘦憔悴。全词巧妙地把飘泊异乡的落魄感受，同怀恋意中人的缠绵情思融为一体，表现了主人公坚毅的性格与执着的态度，成功地刻画了一个思念远方亲人的男性的形象。', '伫（zhù）倚危楼：长时间倚靠在高楼的栏杆上。伫，久立；危楼，高楼。
望极：极目远望。
黯黯（ànàn）：心情沮丧忧愁。
生天际：从遥远无边的天际升起。
烟光：飘忽缭绕的云霭雾气。
会：理解。
阑：同「栏」。
拟把：打算。
疏狂：狂放不羁。
对酒当歌：语出曹操《短歌行》「对酒当歌，人生几何」。当，与"对"意同。
强（qiǎng）乐：勉强欢笑。强，勉强。
衣带渐宽：指人逐渐消瘦。语本《古诗十九首》：「相去日已远，衣带日已缓」。
消得：值得。', '伫立高楼倚着栏杆和风细细，极目远望春愁无际内心惆怅。夕阳斜照青草映着烟霞光彩，谁懂得我依靠栏杆时的思绪？
我想纵情狂饮直到一醉方休，频举酒杯强颜欢笑了无趣味。纵然衣带渐渐宽松终生不悔，为了她值得我相思而憔悴。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749e911759740c9aa2ab", "shortContent": "这是一首怀人之作。词人把飘泊异乡的落魄感受，同怀恋意中人的缠绵情思结合到一起来写，采用“曲径通幽”的表现方式，抒情写景，感情真挚。\n“伫倚危楼风细细”，全词只此一句叙事，其余全是抒情，但只此一句，便把主人公的外在形象像一幅剪纸那样凸现出来了。他一个人久久地伫立在高楼之上，向远处眺望。“风细细”，带写一笔景物，为这幅剪影添加了一点背景，使画面立刻活跃起来了。他“伫倚”楼头做什么？\n“望极春愁，黯黯生...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a603572034f65a8b09", "shortContent": "这是一首怀人之作。词人把漂泊异乡的落魄感受，同怀恋意中人的缠绵情思结合到一起来写，采用“曲径通幽”的表现方式，抒情写景，感情真挚。\n他首先说登楼引起了“春愁”：“伫倚危楼风细细”，全词只此一句叙事，其余全是抒情，但只此一句，便把主人公的外在形象像一幅剪纸那样凸显出来了。他一个人久久地伫立在高楼之上，向远处眺望。“风细细”，带写一笔景物，为这幅剪影添加了一点背景，使画面立刻活跃起来了。他“伫倚”楼头...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252ccce4d48ba496d7c", "shortContent": "这是一首怀人之作。词人把漂泊异乡的落魄感受，同怀恋意中人的缠绵情思结合到一起来写，采用“曲径通幽”的表现方式，抒情写景，感情真挚。\n\n他首先说登楼引起了“春愁”：“伫倚危楼风细细”，全词只此一句叙事，其余全是抒情，但只此一句，便把主人公的外在形象像一幅剪纸那样突现出来了。他一个人久久地伫立在高楼之上，向远处眺望。“风细细”，带写一笔景物，为这幅剪影添加了一点背景，使画面立刻活跃起来了。他“伫倚”楼...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f39e6f69b71e93f618b", "shortContent": "这是一首客中怀人之作，词人将漂泊异乡的落魄与思念伊人的缠绵融合在一起写来，情真而意切。\n上片写景，又带写情。登高望远，春风微吹，春草无边使人黯然愁生，一抹残照更触动凄凉孤寂之感。王夫之《姜斋诗话》曰“一切景语皆情语”，这首词正是通过景，加以特定的环境，表现伤愁、惆怅与无法排遣的别情。“伫倚危楼风细细”，词人从眼前幽微细小的风景入手，“风细细”，表面看来不沉重，但纤细平淡之中，有一种凄凉意味的感发的...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe47ccdb86c49f29179", "shortContent": "这是一首客中怀人之作，词人将漂泊异乡的落魄与思念伊人的缠绵融合在一起写来，情真而意切。\n\n上片写景，又带写情。登高望远，春风微吹，春草无边使人黯然愁生，一抹残照更触动凄凉孤寂之感。王夫之《姜斋诗话》曰“一切景语皆情语”，这首词正是通过景，加以特定的环境，表现伤愁、惆怅与无法排遣的别情。“伫倚危楼风细细”，词人从眼前幽微细小的风景入手，“风细细”，表面看来不沉重，但纤细平淡之中，有一种凄凉意味的感发...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127174c305cf08018170ae", "shortContent": "这是一首客中怀人之作，词人将漂泊异乡的落魄与思念伊人的缠绵融合在一起写来，情真而意切。\n上片写景，又带写情。登高望远，春风微吹，春草无边使人黯然愁生，一抹残照更触动凄凉孤寂之感。王夫之《姜斋诗话》曰：“一切景语皆情语”。这首词正是通过景，加以特定的环境，表现伤愁、惆怅与无法排遣的别情。“伫倚危楼风细细”，词人从眼前幽微细小的风景入手，“风细细”，表面看来不沉重，但纤细平淡之中，有一种带着凄凉意味的...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d125c7af6de1647100d8a", "bookTitle": "柳永词鉴赏辞典", "articleId": "646d8e657f27182da379611d", "shortContent": "这是一首怀人之作。词人把漂泊异乡的落魄感受，同怀恋意中人的缠绵情思结合到一起来写，采用“曲径通幽”的表现方式，抒情写景，感情真挚。\n\n他首先说登楼引起了“春愁”：“伫倚危楼风细细”，全词只此一句叙事，其余全是抒情，但只此一句，便把主人公的外在形象像一幅剪纸那样凸显出来了。他一个人久久地伫立在高楼之上，向远处眺望。“风细细”，带写一笔景物，为这幅剪影添加了一点背景，使画面立刻活跃起来了。他“伫倚”楼...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}]', '唐圭璋《唐宋词简释》：此首上片写境，下片抒情。「伫倚」三句，写远望愁生。「草色」两句，实写所见冷落景象与伤高念远之意。换头深婉。「拟把」句，与「衣带」两句，更柔厚。与「不辞镜里朱颜瘦」语，同合风人之旨。
王国维《人间词话》：古今之成大事业、大学问者，必经过三种之境界，以「衣带渐宽终不悔，为伊消得人憔悴」为第二境。
俞陛云《唐五代两宋词选释》：长守尾生抱柱之信，拼减沈郎腰带之围，真情至语。', 'indent', 1413386979, '57b315ce165abd00543a3783', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10288, '送别', NULL, 1537, 394, 1, 2, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/21443/7001360.htm', '', '下马饮君酒，问君何所之。
君言不得意，归卧南山陲。
但去莫复问，白云无尽时。', '这是首送友人归隐的诗，采用问答的方式从友人口中说出归隐的原因。全诗语言看似平淡无奇，但最后两句却顿增诗意，可谓词浅情深，蕴含着不尽的意味。', '饮君酒：劝君饮酒。饮，使······喝。
何所之：去哪里。之，往。
归卧：隐居。
南山：终南山，即秦岭，在今陕西省西安市西南。
陲：边缘。
但：只。', '请你下马来喝一杯酒，敢问朋友你要去何方？
你说因为生活不得意，回乡隐居在终南山旁。
只管去吧我何须再问，看那白云正无边飘荡。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92950f8fda55650553d9", "shortContent": "这首诗写送友人归隐，看似语句平淡无奇，细细读来，却是词浅情深，含着悠然不尽的意味。\n“下马饮君酒，问君何所之？”第一句叙事。一开始就写饮酒饯别，是点题。第二句设问，问君到哪里去。由此引出下面的答话，过渡到写归隐。这一质朴无华的问语，表露了作者对友人关切、爱护的深厚情意。送别者的感情起始就渗透在字里行间。\n“君言不得意，归卧南山陲。”“不得意”三字，显然是有深意的。不仅交代友人归隐的原因，表现他失意...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d98", "shortContent": "这是一首送别诗。但是，我们却读不出送别的时间，也找不到送别的地点。这样模糊的送别背景图，似乎正宜读者去飞腾自己的想象：或许是在喧嚣的闹市间，衬托出的是对宁静归隐生活的向往；或许是阳春三月，折柳赠别，更多的是一份惜别的依恋；又或许是秋高气爽的时节，在波光粼粼的水边，流水亦绾结着离人的不尽情思；甚或是在萧瑟的寒风中，送别的主题更渗进了一份莫名的凄怨、哀伤与苍凉。\n\n虽然送别的背景是如此朦胧，送别的主体...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312703bf2af4e09d55b673a", "shortContent": "这是一首送别诗，但是我们却读不出送别的时间，也找不到送别的地点，这样模糊的送别背景图，似乎正宜读者去飞腾自己的想象。或许是在喧嚣的闹市间，衬托出的是对宁静归隐生活的向往；或许是阳春三月，折柳赠别，更多的是一份惜别的依恋；又或许是秋高气爽的时节，在波光粼粼的水边，流水亦寄托着离人的不尽情思；甚或是在萧瑟的寒风中，送别的主题更渗进了一份莫名的凄怨、哀伤与苍凉。\n\n虽然送别的背景是如此朦胧，逢别的主体却...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "6463993ae49f46528aa16966", "shortContent": "这首诗写送友人归隐，看似语句平淡无奇，细细读来，却是词浅情深，含着悠然不尽的意味。\n“下马饮君酒，问君何所之？”第一句叙事。一开始就写饮酒饯别，是点题。第二句设问，问君到哪里去。由此引出下面的答话，过渡到写归隐。这一质朴无华的问语，表露了作者对友人关切、爱护的深厚情意。送别者的感情起始就渗透在字里行间。\n“君言不得意，归卧南山陲。”“不得意”三字，显然是有深意的。不仅交代友人归隐的原因，表现他失意...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "64639db25fc8182fe99a0b44", "shortContent": "这首诗写送友人归隐，看似语句平淡无奇，细细读来，却是词浅情深，含着悠然不尽的意味。\n\n “下马饮君酒，问君何所之？”第一句叙事。一开始就写饮酒饯别，是点题。第二句设问，问君到哪里去。由此引出下面的答话，过渡到写归隐。这一质朴无华的问语，表露了作者对友人关切、爱护的深厚情意。送别者的感情起始就渗透在字里行间。\n\n “君言不得意，归卧南山陲。”“不得意”三字，显然是有深意的。不仅交代友人归隐的原因，表...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}]', '', 'center', 1363204331, '57b930588ac2470062e11fc7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10226, '八声甘州', NULL, 166, 793, 3, 2, '辛弃疾', NULL, 10003, '57b8ed682e958a005fa4d096', '宋', 'ci', '词', 'http://baike.baidu.com/view/2769784.htm', '夜读《李广传》，不能寐。因念晁楚老、杨民瞻约同居山间，戏用李广事，赋以寄之。', '故将军饮罢夜归来，长亭解雕鞍。恨灞陵醉尉，匆匆未识，桃李无言。射虎山横一骑，裂石响惊弦。落魄封侯事，岁晚田园。
谁向桑麻杜曲，要短衣匹马，移住南山？看风流慷慨，谈笑过残年。汉开边、功名万里，甚当时健者也曾闲？纱窗外、斜风细雨，一阵轻寒。', '汉「飞将军」李广的故事广为人知，在古代诗文中也多所咏及。辛稼轩的这首《八声甘州》，便是其中的名篇。辛稼轩在题语说「夜读《李广传》，不能寐」，可见他当时的情绪是非常激动的。后边说「戏用李广事」，则不过是寓庄于谐的说法罢了。
此词上阕聊聊数语，约略叙述了李广的事迹。据《史记·李将军列传》载李广罢官闲居时，「尝夜从一骑出，从人田间饮。还至霸陵亭。霸陵尉醉，呵止广。广骑曰：『故李将军』。尉曰：『今将军尚不得夜行，何乃故也！』止广宿亭下。」开篇至「无言」数句即写此事。这里特别突出「故将军」一语，以之居篇首，表现了作者对霸陵尉势利人的愤慨。同时，词中直接把司马迁对李广的赞辞「桃李无言，下自成蹊」当作李广的代称，表示对李广朴实性格的赞赏。一褒一贬，爱憎分明。传文又载：「广出猎，见草中石，以为虎而射之。中石，没镞。视之，石也。」「射虎」二句即写此事。单人独骑横山射虎，可见胆气之豪；弓弦惊响而矢发裂石，可见筋力之健。李广如此健者而被废弃，又可见当时朝政之昏暗。传文又载李广语云：「自汉击匈奴而广未尝不在其中，而诸部校尉以下，才能不及中人，然以击胡军功取侯者数十人，而广不为后人，然无尺寸之功以得封邑者何也？」辛词中「落魄」二句即指此事。劳苦而不得功勋，英勇而反遭罢黜，进一步说明朝政之黑暗。一篇《史记·李将军列传》长达数千字，但作者只用数十字便勾画出了人物的性格特征和生平主要事迹，且写得有声有色，生动传神，可见作者不愧为一代文豪。
与上阕不同，词的下阕专写作者自己的感慨。唐代诗人杜甫《曲江三章》第三首「自断此生休问天，杜曲幸有桑麻田，故将移住南山边，短衣匹马随李广，看射猛虎终残年」诗句。作者在题语云「晁楚老、杨民瞻约同居山间」，此处即以杜甫思慕李广之心，隐喻晁、杨亲爱自己之意，盛赞晁、杨不以穷达异交的高风，与开头所写霸陵呵夜事形成鲜明的对照。其中「看风流慷慨，谈笑过残年」一语，上应「落魄封侯事，岁晚田园」句，表现了作者宠辱不惊、无所悔恨的坚强自信。「汉开边、功名万里，甚当时、健者也曾闲」一句，借汉言宋，感慨极深沉，讽刺极强烈。具体说来，它大致有以下几层含义：一是汉时开边拓境，号召立功绝域，健如李广者本不当投闲，然竟亦投闲，可见邪曲之害公、方正之不容，乃古今之通病，正不必为之怅恨；二是汉时征战不休，健如李广者尚且弃而不用，宋朝求和讳战，固当斥退一切勇夫，更不必为之嗟叹。以上皆反面意，实则是痛恨朝政腐败，进奸佞而逐贤良，深恐国势更趋衰弱。作者遭到罢黜，乃因群小谗毁所致，故用「纱窗外、斜风细雨，一阵轻寒」之景作结，隐喻此辈之阴险和卑劣，并以点明题语所云「夜读」情事。此语盖用柳宗元《登柳州城楼寄漳汀封连四州刺史》「惊风乱颭芙蓉水，密雨斜侵薜荔墙」诗意，但换「惊风」为「斜风」，以示其谗毁之邪恶；改「密雨」为「细雨」，以示其谗毁之琐屑；又益以「轻寒」一事，以示其谗毁之虚弱。这样一来，使其更具有表达力。
辛稼轩的这首词，其句子隐括了不少前人的诗文。但是，这首词决不是简单地照搬古人语句，而是在隐括前人辞句时加进了生动的想象，融入了深厚的情感。如上阕写霸陵呵夜事，加进「长亭解雕鞍」的想象，便觉情景逼真；写出猎射虎事，加进「裂石响惊弦」的想象，更觉形神飞动。下阕「汉开边、功名万里，甚当时、健者也曾闲」一问，气劲辞婉，几经顿挫才把意思说完，情真意切，充满了无限悲愤。这首词不仅抒情真切感人，而且语言上也多所创新，是不可多得的佳作。', '《李广传》：《史记·卷一百零九·李将军列传》略云：「李将军广者，陇西成纪人也。……广家与故颍阴侯孙屏野居蓝田南山中射猎。尝夜从一骑出，从人田间饮。还至霸陵亭，霸陵尉醉，呵止广。广骑曰：『故李将军。』尉曰：『今将军尚不得夜行，何乃故也！』止广宿亭下。……广居右北平，匈奴闻之，号曰『汉之飞将军』，避之数岁，不敢入右北平。广出猎，见草中石，以为虎而射之，中石没镞，视之石也。因复更射之，终不能复入石矣。广所居郡闻有虎，尝自射之。及居右北平射虎，虎腾伤广，广亦竟射杀之。……诸广之军吏及士卒或取封侯。广尝与望气王朔燕语，曰：『自汉击匈奴而广未尝不在其中，而诸部校尉以下，才能不及中人，然以击胡军功取侯者数十人，而广不为后人，然无尺寸之功以得封邑者，何也？岂吾相不当侯邪？且固命也？』……太史公曰：『传曰：「其身正，不令而行；其身不正，虽令不从。」其李将军之谓也？余睹李将军悛悛如鄙人，口不能道辞。及死之日，天下知与不知，皆为尽哀。彼其忠实心诚信于士大夫也？谚曰「桃李不言，下自成蹊。」此言虽小，可以谕大也。』」
晁楚老：《上饶县志·卷二十三·寓贤》：「晁谦之字恭祖，澶州人，渡江亲族离散，极力收恤，因居信州。仕宋，官敷文阁直学士，卒葬铅山鹅湖，子孙因家焉。」按：晁楚老始末未详，疑即谦之后人。
杨民瞻：其名莫考，当亦居上饶者。宋·韩淲《闻民瞻久归一诗寄之》：「我居溪南望城北，最高园台竹树碧，眼前带湖歌舞空，耳畔茶山陆子宅。知君才自天竺归，那得缁尘染客衣？日携研席过阿连，怡神散发思采薇。」又《和民瞻所寄》诗：「南北一峰高可仰，东西二馆隐谁招？园居好在带湖水，冰雪春须积渐消。」宋·赵蕃《以归来后与斯远倡酬诗卷寄辛卿》：「人家馈岁何所为？纷纷酒肉相携持。我曹馈岁复何有，酬倡之诗十馀首。……公乎比复何所作？想亦高吟动清酌。宾朋杂遝孰为佳？咸推杨、范工词华。」按：所谓「杨、范工词华」，范必指范廓之，杨则当为杨民瞻也。果尔，则民瞻当为范廓之一同从游于稼轩者。惜其生平别无可考耳。
解雕鞍：卸下精美的马鞍，指下马。
桃李无言：谚语「桃李不言，下自成蹊。」司马迁在《史记·卷一百零九·李将军列传》中曾用此谚语来赞美李广虽然不善辞令，却深得天下人敬爱。这里代指李广。
裂石响惊弦：引用李广射石虎的典故。
「落魄」：四卷本丙集作「落托」。', '汉飞将军李广，曾夜出与友人在田间饮酒，回到灞陵亭，下马住宿营，灞陵尉喝醉了出言侮辱他，虽然来时匆匆，灞陵尉可能还不认识李广将军。但李广将军闻名天下，桃李树虽然不会说话，树下自然成蹊。李将军在南山半腰里，一人一匹马去射猎，误把草丛里的石头当作老虎，弓弦发出了惊人的响声，箭镞射进了石头，把石头都射裂了。这样的英雄没有受到封侯，到了晚年，退居山村，过着耕田地、种菜园的生活。
谁去杜曲去种桑麻？我是不去的。我要穿上轻便的短衣，骑上一匹马，到南山去学李广射虎的生活。我要风流潇洒，慷慨激昂、谈笑愉快地过一个幸福的晚年。汉代开拓边疆，打击侵略者，保卫边疆的事业是伟大的，不少的人在这个长约万里的国境线上，建功立业。可是，为什么正在非常需要人才的当时，像李广将军这样有胆略、有才干而且是曾经在边疆建立过奇功伟迹的人，也落职闲居呢？我正在沉思的时候，纱窗外，斜风细雨，送来一阵轻寒。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74ea5e272d4b2253bc64", "shortContent": "辛弃疾是一个“慷慨有大略”的英雄，二十二岁即起兵抗金，南归以后亦所至多有建树。但因为人刚正不阿，敢于抨击邪恶势力，遭到朝中群小的忌恨，一直未能实现恢复中原的理想，且被诬以种种罪名，在壮盛之年削除了官职。此种肝胆和遭遇，极似汉时名将李广。因此，他特别同情和思慕这位不幸的“飞将军”，多次在词中写到李广的事迹。此词即借李广功高反黜的不平遭遇，抒发自己遭谗被废的悲愤心情。题语说“夜读《李广传》，不能寐”，...", "authors": ["罗忠族"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ec2e6a6b501f96735e", "shortContent": "辛弃疾是一个“慷慨有大略”的英雄，二十三岁即起兵抗金，南归以后亦所至多有建树。但因为人刚正不阿，敢于抨击邪恶势力，遭到朝中群小的忌恨，一直未能实现恢复中原的理想，且被诬以种种罪名，在壮盛之年削除了官职。此种肝胆和遭遇，极似汉时名将李广。因此，他特别同情和思慕这位不幸的“飞将军”，多次在词中写到李广的事迹。此词即借李广功高反黜的不平遭遇，抒发自己遭谗被废的悲愤心情。题语说“夜读《李广传》，不能寐”，...", "authors": ["罗忠族"], "pressName": "上海辞书出版社"}, {"bookId": "64688f9830675327e19962ff", "bookTitle": "辛弃疾词鉴赏辞典（珍藏本）", "articleId": "6469796b7da2f75ac7fb20cf", "shortContent": "辛弃疾是一个“慷慨有大略”的英雄，二十二岁即起兵抗金，南归以后亦所至多有建树。但因为人刚正不阿，敢于抨击邪恶势力，遭到朝中群小的忌恨，一直未能实现恢复中原的理想，且被诬以种种罪名，在壮盛之年削除了官职。此种肝胆和遭遇，极似汉时名将李广。因此，他特别同情和思慕这位不幸的“飞将军”，多次在词中写到李广的事迹。此词即借李广功高反黜的不平遭遇，抒发自己遭谗被废的悲愤心情。题语说“夜读《李广传》，不能寐”，...", "authors": ["罗忠族"], "pressName": "上海辞书出版社"}]', '', 'indent', 1362672234, '57b905945bbb50005b784b07', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10227, '丑奴儿 · 书博山道中壁', NULL, 1166, 793, 2, 6, '辛弃疾', NULL, 10003, '57b8ed682e958a005fa4d096', '宋', 'ci', '词', 'http://baike.baidu.com/view/383876.htm', '', '少年不识愁滋味，爱上层楼。爱上层楼，为赋新词强说愁。
而今识尽愁滋味，欲说还休。欲说还休，却道“天凉好个秋”！', '此词是南宋词人辛稼轩被弹劾去职、闲居带湖时所作的一首词。此词通篇言愁，前阕描绘出少年涉世未深却故作深沉的情态，後阕写出满腹愁苦却无处倾诉的抑郁，通过「少年」时与「而今」的对比，表达了作者受压抑、遭排挤、报国无门的痛苦之情。全词突出地渲染了一个「愁」字，以此作为贯串全篇的线索，构思精巧，感情真率而又委婉，言浅意深，令人回味无穷。', '丑奴儿：四卷本甲集作「采桑子」。词牌名。唐教坊曲有《杨下采桑》，调名本此。汉代乐府诗《陌上桑》：「秦氏有好女，自名为罗敷。罗敷喜蚕桑，采桑城南隅。」此曲应是乐府旧曲《采桑》而入燕乐者。晚唐和凝词为创调之作。南唐李煜词名《丑奴儿令》，冯延巳词名《罗敷媚歌》，贺铸词名《丑奴儿》，陈师道词名《罗敷媚》。南卓《羯鼓录》作《凉下采桑》，属「太簇角」。此双调小令，殆就大曲中截取一遍为之。《尊前集》注「羽调」。《乐府雅词》注「中吕宫」，《张子野词》入「双调」。此调四十四字，前后阕相同，各三平韵。由四个七字句和四个四字句组成，每阕四字句处于七字句之间，使词气和缓；用韵甚密，而又使音节浏亮。此调宜于抒情与写景，既可表现婉约风格，又可表现旷达与刚健的风格。别有添字格，两结句各添二字，两平韵，一叠韵。
博山：地名，位于上饶以东永丰县境内，在今江西广丰县西南。南宋·王象之《舆地纪胜·卷二十一·〈江南东路·信州〉》：「博山在永丰西二十里，古名『通元峰』，以形似庐山香炉峰，故改今名。」淳熙八年（公元1181年）辛稼轩罢职退居上饶，常过博山。
少年：指年轻的时候。
不识：不懂、不知道什么是。
「为赋新词强（qiǎng）说愁」句：为了写出新词，没有愁而硬要说有愁。强，勉强地，硬要。
识尽：尝够、深深懂得。
欲说还（huán）休：内心有所顾虑而不敢表达。宋·李清照《凤凰台上忆吹箫》词：「生怕闲愁暗恨，多少事欲说还休。」休，停止。', '人年少时不知道忧愁的滋味，喜欢登高远望。喜欢登高远望，为写一首新词无愁而勉强说愁。
现在尝尽了忧愁的滋味，想说却说不出。想说却说不出，却说好一个凉爽的秋天啊！', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74eb0f8fda556504dab1", "shortContent": "这一首词，是辛弃疾被劾去职，闲居带湖时所作（1181—1192），他常闲游于博山道中，风景如画，却无心赏玩。眼看国事日非，自己无能为力，一腔愁绪无法排遣，遂在博山道中一壁上题了这首词。在这首词中作者运用对比手法，突出地渲染了一个“愁”字，以此作为贯串全篇的线索，感情真率而又委婉，把一首短短的词，写得曲折多变，娓娓动人，高度概括了词人大半生的经历感受。\n词的上片，着重描写自己的少年时代：那时风华正茂...", "authors": ["陈允吉", "胡中行"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ed2cee9a0c24ed9eec", "shortContent": "这一首词，是辛弃疾被劾去职，闲居带湖时所作（1181—1192），他常闲游于博山道中，风景如画，却无心赏玩。眼看国事日非，自己无能为力，一腔愁绪无法排遣，遂在博山道中一壁上题了这首词。在这首词中作者运用对比手法，突出地渲染了一个“愁”字，以此作为贯串全篇的线索，感情真率而又委婉，把一首短短的词，写得曲折多变，娓娓动人，高度概括了词人大半生的经历感受。\n词的上片，着重描写自己的少年时代：那时风华正茂...", "authors": ["陈允吉", "胡中行"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255eebf5e0fdea508eb", "shortContent": "这一首词，是辛弃疾被劾去职，闲居带湖时所作（1181—1192），他常闲游于博山道中，风景如画，却无心赏玩。眼看国事日非，自己无能为力，一腔愁绪无法排遣，遂在博山道中一壁上题了这首词。在这首词中作者运用对比手法，突出地渲染了一个“愁”字，以此作为贯串全篇的线索，感情真率而又委婉，把一首短短的词，写得曲折多变，娓娓动人，高度概括了词人大半生的经历感受。\n\n词的上片，着重描写自己的少年时代：那时风华正...", "authors": ["陈允吉", "胡中行"], "pressName": "上海辞书出版社"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127044c305cf0801816f21", "shortContent": "这首词是辛弃疾被弹劾免官，闲居江西带湖时所作。带湖有一处叫博山的地方，风景秀美，词人常常游历于此，然而，他却无心山水，国破家亡、山河破碎之下的他，满腔愁绪无法排解，便在博山山道旁题下了这首词。\n\n词的上片第一句，便是千古名句——少年不识愁滋味，年少时的词人不知道忧愁是什么滋味，喜欢遍上层楼，登高望远，甚至为了作一首新词，搜肠刮肚，明明毫无忧愁，却硬说忧愁。可见，年轻时的辛弃疾是何等的意气风发，然而...", "authors": ["陈庆之"], "pressName": "崇文书局"}, {"bookId": "64688f9830675327e19962ff", "bookTitle": "辛弃疾词鉴赏辞典（珍藏本）", "articleId": "64697c255b7b0d4f45245568", "shortContent": "这一首词，是辛弃疾被劾去职，闲居带湖时所作(1181—1192)，他常闲游于博山道中，风景如画，却无心赏玩。眼看国事日非，自己无能为力，一腔愁绪无法排遣，遂在博山道中一壁上题了这首词。在这首词中作者运用对比手法，突出地渲染了一个“愁”字，以此作为贯串全篇的线索，感情真率而又委婉，把一首短短的词，写得曲折多变，娓娓动人，高度概括了词人大半生的经历感受。\n词的上片，着重描写自己的少年时代：那时风华正茂...", "authors": ["陈允吉　胡中行"], "pressName": "上海辞书出版社"}]', '', 'indent', 1415647122, '57b8fbc90a2b58005c92187e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10228, '摸鱼儿', NULL, 469, 793, 7, 3, '辛弃疾', NULL, 10003, '57b8ed682e958a005fa4d096', '宋', 'ci', '词', 'http://baike.baidu.com/view/2540571.htm', '淳熙己亥，自湖北漕移湖南，同官王正之置酒小山亭，为赋。', '更能消、几番风雨，匆匆春又归去。惜春长怕花开早，何况落红无数。春且住。见说道、天涯芳草无归路。怨春不语。算只有殷勤、画檐蛛网，尽日惹飞絮。
长门事，准拟佳期又误。蛾眉曾有人妒，千金纵买相如赋，脉脉此情谁诉？君莫舞，君不见、玉环飞燕皆尘土！闲愁最苦，休去倚危栏，斜阳正在，烟柳断肠处。', '此词是一首忧时感世之作。上阕描写抒情主人公对春光的无限留恋和珍惜之情；下阕以比喻手法反映全词情调婉转凄恻，柔中寓刚。词中表层写的是美女伤春、蛾眉遭妒，实际上是作者借此抒发自己壮志难酬的愤慨和对国家命运的关切之情。全词托物起兴，借古伤今，融身世之悲和家国之痛于一炉，沉郁顿挫，寄托遥深。', '摸鱼儿：词牌名。一名《摸鱼子》，又名《买陂塘》、《迈陂塘》、《双蕖怨》等。唐教坊曲，後用为词牌。宋词以晁补之《琴趣外篇》所收为最早。双调，一百一十六字，前阕六仄韵，後阕七仄韵。双结倒数第三句第一字皆领格，宜用去声。
“淳熙己亥，自湖北漕移湖南，同官王正之置酒小山亭，为赋。”：《花庵词选》作“暮春”，《草堂诗馀》作“春晚”，《绝妙好词》作无题，《鹤林玉露》作“晚春”。
淳熙己亥：即淳熙六年（公元1179年）。淳熙，宋孝宗的年号；己亥，干支之一。
漕：漕司的简称，指转运使。
王正之，名正已，是作者旧交，淳熙六年任湖北转运判官。即稼轩调离湖北转运判官后，由王正之接任原来职务，故称“同官”。南宋·楼钥《攻愧集·卷九十九·朝议大夫秘阁修撰致仕王公墓志铭》：“（绍兴）三十二年有旨：王正已不畏彊禦，节槩可称，三省详加访问，其人如在，可与甄录。寻召赴行在。……公字伯仁父，旧字正之，至今以旧字行。……以叶丞相之荐，除尚书吏部员外郎，权右司郎官，遂为真。叶公去国，公亦遭论，再奉祠。除严州，改婺州，内引奏事，尤加褒纳。……庆元二年三月二日属疾，却药不进，翌日终于正寝。享年七十有八。”《宝庆四明志·卷八·叙人》：“（王）正已，字正之，勋长子也。……以叔祖珩任为丰城主簿，连帅张澄俾对，易理曹。时相姻党王鈇家豫章，家舍亡瑞香花，与一富民有他憾，因诬之，帅讽理曹文致其罪，正已直之，忤帅意，称疾寻医以归。孝宗闻之，既践阼，诏以不畏彊禦，节槩可称，自泰州海陵县召对，改令入官。淳熙初，访求廉吏，参政叶衡举正已辞赙事以闻，召对，上语辅臣曰：‘王正已望之俨然，即之甚温。’史忠定王浩再相，论朋党事，上曰：‘叶衡既去，人以王正已为其党，朕固留之。虽衡所引，其人自贤，则知朕不以朋党待臣下也。’正已凡四典郡，六为部使者，终太府卿、秘阁修撰致仕。”
小山亭：《舆地纪胜·荆湖北路·鄂州》：“绍兴二年，复置荆湖北路转运副使，治鄂州。有副使、判官东西二衙。……小山亭在东漕衙之乖崖堂。”
消：消受、经受。
长怕：四卷本甲集及《阳春白雪·卷三》作“长恨”。
落红：落花。
“见说道、天涯芳草无归路。”句：宋·苏轼《点绛唇》：“归不去，凤楼何处？芳草迷归路。”无归路，四卷本作“迷归路”。
“算只有殷勤、画檐蛛网，尽日惹飞絮。”句：想来只有檐下蛛网还殷勤地沾惹飞絮，留住春色。画檐蛛网，苏轼《虚飘飘》诗：“画檐蛛结网。”画檐，有画饰的屋檐；飞絮，飘飞的柳絮。
长门：汉代宫殿名，武帝皇后失宠後被幽闭於此。西汉·司马相如《长门赋序》：“孝武皇帝陈皇后，时得幸，颇妬。别在长门宫，愁闷悲思，闻蜀郡成都司马相如天下工为文，奉黄金百斤，为相如、文君取酒，因於解悲愁之辞。而相如为文以悟主上，陈皇后复得幸。”
蛾眉：借指女子容貌的美丽。战国楚·屈原《離騷》：“众女嫉予之蛾眉兮，谣诼谓予以善淫。”
纵买：《阳春白雪》作“莫买”。
相如赋：即司马相如的《长门赋》。
脉脉：绵长深厚。
谁诉：《阳春白雪》作“难诉”。
君：指那些忌妒别人来邀宠的人。
玉环：《杨太真外传》：“杨贵妃，小字玉环，弘农华阴人也。”《新唐书·卷七十六·后妃传》：“玄宗贵妃杨氏，隋梁郡通守汪四世孙。……幼孤，养叔父家。始为寿王妃。开元二十四年，武惠妃薨，后廷无当帝意者。或言妃姿质天挺，宜充掖廷，遂召内禁中，异之，即为自出妃意者，丐籍女官，号‘太真’，更为寿王聘韦昭训女，而太真得幸。善歌舞，邃晓音律，且智算警颖，迎意辄悟。帝大悦，遂专房宴，宫中号‘娘子’，仪体与皇后等。天宝初，进册贵妃。……禄山反，以诛国忠为名，且指言妃及诸姨罪。……及西幸至马嵬，陈玄礼等以天下计诛国忠，已死，军不解。帝遣力士问故，曰：‘祸本尚在！’帝不得已，与妃诀，引而去，缢路祠下，裹尸以紫茵，瘗道侧，年三十八。”
飞燕：《汉书·卷九十七下·〈外戚传·孝成赵皇后〉》：“孝成赵皇后，本长安宫人。……及壮，属阳阿主家，学歌舞，号曰‘飞燕’。成帝尝微行出。过阳阿主，作乐，上见飞燕而说之，召入宫，大幸。有女弟复召入，俱为婕妤，贵倾后宫。……姊弟颛宠十馀年，卒皆无子。”
皆尘土：汉·伶玄《赵飞燕外传·伶玄自叙》：“伶玄，字子于，潞水人，学无不通。……哀帝时，子于老休，买妾樊通德，……有才色，知书，慕司马迁《史记》。颇能言赵飞燕姊弟故事。子于闲居命言，厌厌不倦。子于语通德曰：‘斯人（指赵氏姊妹）俱灰灭矣，当时疲精力，驰骛嗜欲蛊惑之事，宁知终归荒田野草乎！’通德占袖，顾视灯影，以手拥髻，凄然泣下，不胜其悲。子于亦然。”
闲愁：指自己精神上的郁闷。
危栏、斜阳：宋·苏舜钦《春日晚晴》诗：“谁见危栏外，斜阳尽眼平。”危栏，四卷本作“危楼”，高处的栏杆。
断肠：形容极度思念或悲痛。', '还经得起几回风雨，春天又将匆匆归去。爱惜春天我常怕花开得过早，何况此时已落红无数。春天啊，请暂且留步，难道没听说，连天的芳草已阻断你的归路？真让人恨啊春天就这样默默无语，看来殷勤多情的，只有雕梁画栋间的蛛网，为留住春天整天沾染飞絮。
长门宫阿娇盼望重被召幸，约定了佳期却一再延误。都只因太美丽有人嫉妒。纵然用千金买了司马相如的名赋，这一份脉脉深情向谁倾诉？奉劝你们不要得意忘形，难道没看见玉环、飞燕都化作了尘土。闲愁折磨人最苦。不要去登楼凭栏眺望，一轮就要沉落的夕阳正在那，令人断肠的烟柳迷蒙之处。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74e503048e64fbd8943d", "shortContent": "这是辛弃疾四十岁时，也就是宋孝宗淳熙六年（1179）暮春写的词。辛弃疾自绍兴三十二年（1162）渡淮水来归南宋，十七年中，他的抗击金军、恢复中原的主张，始终没有被南宋朝廷所采纳。朝廷不把他放在抗战前线的重要位置上，只是任命他作闲职官员和地方官吏。这一次，又把他从荆湖北路转运副使任上调到荆湖南路继续当转运副使。转运使亦称“漕”，主要掌管一路财赋，对辛弃疾来说，当然不能尽情施展他的才能和抱负。何况如今...", "authors": ["夏承焘", "吴无闻"], "pressName": "上海辞书出版社"}, {"bookId": "60fc157134bfda01e0e91549", "bookTitle": "元明清词鉴赏辞典（新一版）", "articleId": "610e86690f8fda5565052341", "shortContent": "张惠言、张琦兄弟论词专主比兴，开常州词派，选编五代两宋词，仅百余首，矜严已甚。作为词家一大流派的创始人，二家词作数量并不丰富，亦可见其矜严的创作态度。这首《摸鱼儿》是一曲伤春加闺思、乡情的作品，但词中所述殊非泛泛笔墨，颇能启人遐思。\n古人伤春，往往是落花流水春归后，对春的追忆，以好春之去象征人生的韶华易逝、好景不再，抒发自己的悲哀。但也有一些伤春词，却是在暮春时节，春还没有逝去之时，便作悲怆之语。...", "authors": ["郭", "锋"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5e803048e64fbd9bdaa", "shortContent": "这是辛弃疾四十岁时，也就是宋孝宗淳熙六年（1179）暮春写的词。辛弃疾自绍兴三十二年（1162）渡淮水来归南宋，十七年中，他的抗击金军、恢复中原的主张，始终没有被南宋朝廷所采纳。朝廷不把他放在抗战前线的重要位置上，只是任命他作闲职官员和地方官吏。这一次，又把他从荆湖北路转运副使任上调到荆湖南路继续当转运副使。转运使亦称漕司，是主要掌管一路财赋的官职，对辛弃疾来说，当然不能尽情施展他的才能和抱负。何...", "authors": ["夏承焘", "吴无闻"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255ccce4d48ba496db2", "shortContent": "这是辛弃疾四十岁时，也就是宋孝宗淳熙六年（1179）暮春写的词。辛弃疾自绍兴三十二年（1162）渡淮水来归南宋，十七年中，他的抗击金军、恢复中原的主张，始终没有被南宋朝廷所采纳。朝廷不把他放在抗战前线的重要位置上，只是任命他作闲职官员和地方官吏。这一次，又把他从荆湖北路转运副使任上调到荆湖南路继续当转运副使。转运使亦称漕司，是主要掌管一路财赋的官职，对辛弃疾来说，当然不能尽情施展他的才能和抱负。何...", "authors": ["夏承焘", "吴无闻"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f4e73206168b2e020fb", "shortContent": "所谓“女悲春、士悲秋”，对于节序的变化，人们从心理上都会有所感染。时光流逝，会让本愿有所作为之人因无所成而感叹时不我待，因年华老去而感到蹉跎。对春之匆匆来、匆匆去，不仅仅是女性感伤的专属，辛弃疾这首词即是感春而赋，而且名传千古。\n开篇以感叹春去匆匆开始。“更能消”，是一种反问语气，同时也透露出无奈，意谓“还能消”。“几番风雨”，指词人面对着“匆匆春又归去”不知多少次了，而以后还要面对多少次亦是未知...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312704773206168b2e021c8", "shortContent": "所谓“女悲春、士悲秋”，对于节序的变化，人们从心理上都会有所感染。时光流逝，会让本愿有所作为之人因无所成而感叹时不我待，因年华老去而感到蹉跎。对春之匆匆来、匆匆去，不仅仅是女性感伤的专属，辛弃疾这首词即是感春而赋，而且名传千古。\n\n开篇以感叹春去匆匆开始。“更能消”，是一种反问语气，同时也透露出无奈，意谓“还能消”。“几番风雨”，指词人面对着“匆匆春又归去”不知多少次了，而以后还要面对多少次亦是未...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271ffc305cf080181711d", "shortContent": "所谓“女悲春、士悲秋”，对于节序的变化，人们从心理上都会有所感染。时光流逝，会让本愿有所作为之人因无所成而感叹时不我待，因年华老去而感到蹉跎。对春之匆匆来、匆匆去，不仅仅是女性感伤的专属，辛弃疾这首词即是感春而赋，而且名传千古。\n开篇以感叹春去匆匆开始。“更能消”，是一种反问语气，同时也透露出无奈，意谓“还能消”。“几番风雨”，指词人面对着“匆匆春又归去”不知多少次了，而以后还要面对多少次亦是未知...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "64688f9830675327e19962ff", "bookTitle": "辛弃疾词鉴赏辞典（珍藏本）", "articleId": "6468a9e47da2f75ac7f8ad11", "shortContent": "这是辛弃疾四十岁时，也就是宋孝宗淳熙六年(1179)暮春写的词。辛弃疾自绍兴三十二年(1162)渡淮水来归南宋，十七年中，他的抗击金军、恢复中原的主张，始终没有被南宋朝廷所采纳。朝廷不把他放在抗战前线的重要位置上，只是任命他作闲职官员和地方官吏。这一次，又把他从荆湖北路转运副使任上调到荆湖南路继续当转运副使。转运使亦称“漕”，主要掌管一路财赋，对辛弃疾来说，当然不能尽情施展他的才能和抱负。何况如今...", "authors": ["夏承焘　吴无闻"], "pressName": "上海辞书出版社"}]', '罗大经《鹤林玉露》：词意殊怨。斜阳烟柳之句，其“未须愁日暮，天际乍轻阴”者异矣。便在汉唐时，宁不贾种豆种桃之祸哉。愚闻寿皇（宋孝宗）见此词颇不悦。
夏承焘《唐宋词欣赏》：他的豪放激昂的作品固然振奋人心，而婉约含蓄的也同样出色动人。如《摸鱼儿》和《青玉案·元夕》就是。又云本词“肝肠似火，色貌如花”。
陈廷焯《白雨斋词话》：稼轩“更能消几番风雨”一章，词意殊怨，然姿态飞动，极沉郁顿挫之致。又云：稼轩词，于雄莽中别饶隽味。……“休去倚危栏，斜阳正在，烟柳断肠处”，多少曲折，惊雷怒涛中时见和风暖日，所以独绝古今，不容人学步。
梁启超《艺蘅馆词选》：回肠荡气，至于此极，前无古人，後无来者。
唐圭璋《唐宋词简释》：此首以太白诗法，写忠爱之忱，宛转怨慕，尽态极妍。起处大踏步出来，激切不平。“惜春”两句，惜花惜春。“春且住”两句，留春。“怨春”三句，因留春不住，故怨春。正壬秋谓“画檐蛛网，指张俊、秦桧一流人”，是也。下阕，径言本意。“长门”两句，言再幸无望，而所以无望者，则因有人妒也。“千金”两句，更深一层，言纵有相如之赋，仍属无望。脉脉谁诉，“怨春不语”相应。“君莫舞”两句顿挫，言得宠之人化为尘土，不必伤感。“闲愁”三句，纵笔言今情，但于景中寓情，含思极凄婉。', 'indent', 1415647031, '57b8edff5bbb50005b77afa7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10229, '行路难三首', NULL, 1266, 1052, 5, 15, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/item/行路难三首/2864251', '', '【其一】
金樽清酒斗十千，玉盘珍羞直万钱。
停杯投箸不能食，拔剑四顾心茫然。
欲渡黄河冰塞川，将登太行雪满山。
闲来垂钓碧溪上，忽复乘舟梦日边。
行路难，行路难，多歧路，今安在？
长风破浪会有时，直挂云帆济沧海！
【其二】
大道如青天，我独不得出。
羞逐长安社中儿，赤鸡白雉赌梨栗。
弹剑作歌奏苦声，曳裾王门不称情。
淮阴市井笑韩信，汉朝公卿忌贾生。
君不见昔时燕家重郭隗，拥篲折节无嫌猜。
剧辛乐毅感恩分，输肝剖胆效英才。
昭王白骨萦蔓草，谁人更扫黄金台？
行路难，归去来！
【其三】
有耳莫洗颍川水，有口莫食首阳蕨。
含光混世贵无名，何用孤高比云月？
吾观自古贤达人，功成不退皆殒身。
子胥既弃吴江上，屈原终投湘水滨。
陆机雄才岂自保？李斯税驾苦不早。
华亭鹤唳讵可闻？上蔡苍鹰何足道？
君不见吴中张翰称达生，秋风忽忆江东行。
且乐生前一杯酒，何须身后千载名？', '《行路难三首》是唐代伟大诗人李白的组诗作品。这三首诗抒写了诗人在政治道路上遭遇艰难后的感慨。诗中跌宕起伏的感情，跳跃式的思维，以及高昂的气势，使作品具有独特的艺术魅力，成为后人广为称颂的千古名篇。全诗蕴意波澜起伏，跌宕多姿。', '行路难：乐府《杂曲歌辞》调名，古乐府道路六曲之一，亦有变行路难，内容多写社会道途艰难及离别悲伤之意，多以「君不见」为首，后鲍照拟作为多。
樽（zūn）：古代盛酒的器具，以金为饰。
清酒：清醇的美酒。
斗十千：一斗值十千钱（即万钱），形容酒美价高。
玉盘：精美的食具。
珍羞：珍贵的菜肴。羞，同「馐」，美味的食物。
直：通「值」，价值。
投箸（zhù）：丢下筷子。箸，筷子。
茫然：无所适从。
塞：堵塞。
太行：太行山，现山西、河南、河北三省交界处。
雪满山：一作「雪暗天」。详细说明：根据《平水韵》来看，这里一句的「川」和下一句的「边」都是属于下平一先，而「山」属于上平十五删。而「天」才是同在下平一先中的字。《平水韵》是后人总结唐人的用韵，总结的时候不可能把「山」这样的常见字放错位置，更不可能忽略这篇李白的名篇。
「闲来垂钓碧溪上，忽复乘舟梦日边。」句：暗用典故：姜太公吕尚曾在渭水的磻溪上钓鱼，得遇周文王，助周灭商；伊尹曾梦见自己乘船从日月旁边经过，后被商汤聘请，助商灭夏。这两句表示诗人自己对从政仍有所期待。碧，一作「坐」。
「多岐路，今安在。」句：岔道这么多，如今身在何处？岐，一作「歧」；安，哪里。
长风破浪：比喻实现政治理想。据《宋书·宗悫传》载：宗悫少年时，叔父宗炳问他的志向，他说：「愿乘长风破万里浪。」
会：当。
云帆：高高的船帆。船在海里航行，因天水相连，船帆好像出没在云雾之中。
济：渡过。
沧海：大海。
社：古二十五家为一社。
白狗：一作「白雉」。
弹剑：战国时齐公子孟尝君门下食客冯谖曾屡次弹剑作歌怨己不如意。
贾生：洛阳贾谊，曾上书汉文帝，劝其改制兴礼，受时大臣反对。
拥篲：燕昭王亲自扫路，恐灰尘飞扬，用衣袖挡帚以礼迎贤士邹衍。
折节：一作「折腰」。
归去来：指隐居。语出东晋陶渊明《归去来辞》。
首阳蕨：《史记·伯夷列传》：「武王已平殷乱，天下宗周，而伯夷、叔齐耻之，义不食周粟，隐于首阳山，采薇而食之……遂饿死于首阳山。」《索引》：「薇，蕨也。」按薇、蕨本二草，前人误以为一。
含光混世贵无名：此句言不露锋芒，随世俯仰之意。《高士传》：巢父谓许由曰：「何不隐汝形，藏汝光？」
自古贤达人：鲍照《拟行路难》：「自古圣贤尽贫贱」。《史记·蔡泽列传》：「四时之序，成功者去。……商君为秦孝公明法令，……功已成矣，而遂以车裂。……白起……功已成矣，而遂赐剑死于杜邮。吴起……功已成矣，而卒枝解。大夫种为越王深谋远计……令越成霸，功已彰而信矣，勾践终负而杀之。此四子者，功成不去，祸至于身？」
子胥：伍子胥，春秋末期吴国大夫。《吴越春秋》卷五《夫差内传》：「吴王闻子胥之怨恨也，乃使人赐属镂之剑，子胥……遂伏剑而死。吴王乃取子胥尸，盛以鸱夷之器，投之于江中。」又见《国语·吴语》。
陆机雄才岂自保：《晋书·陆机传》载：陆机因宦人诬陷而被杀害于军中，临终叹曰：「华亭鹤唳，岂可复闻乎？」
李斯税驾苦不早：李斯，秦国统一六国的大功臣，任秦朝丞相，后被杀。《史记·李斯列传》载：李斯喟然叹曰：「……斯乃上蔡布衣……今人臣之位，无居臣上者，可谓富贵极矣。物极则衰，吾未知所税驾？」《索引》：「税驾，犹解驾，言休息也。」
华亭鹤唳讵可闻？上蔡苍鹰何足道：这两句还是写李斯。《史记·李斯列传》：「二世二年七月，具斯五刑，论腰斩咸阳市。斯出狱，与其中子俱执，顾谓其中子曰：『吾欲与若复牵黄犬俱出上蔡东门逐狡兔，岂可得乎！』」《太平御览·卷九二六》：「《史记》曰：『李斯临刑，思牵黄犬、臂苍鹰，出上蔡门，不可得矣。』」
秋风忽忆江东行：这句写张翰。《晋书·张翰传》：「张翰，字季鹰，吴郡吴人也。……为大司马东曹掾。……因见秋风起，乃思吴中菰菜、莼羹、鲈鱼脍，曰：『人生贵得适志，何能羁官数千里，以要名爵乎？』遂命驾而归。……或谓之曰：『卿乃纵适一时，独不为身后名邪？』答曰：『使我有身后名，不如即时一杯酒。』时人贵其旷达。」', '【其一】
金杯中的美酒一斗价十千，玉盘里的菜肴珍贵值万钱。
但心情愁烦使得我放下杯筷，不愿进餐。拔出宝剑环顾四周，心里一片茫然。
想渡过黄河，坚冰堵塞大川；想登太行山，大雪遍布高山。
遥想当年，姜太公溪垂钓，得遇重才的文王，伊尹乘舟梦日，受聘在商汤身边。
人生的道路何等艰难，何等艰难，歧路纷杂，真正的大道究竟在哪边？
坚信乘风破浪的时机定会到来，到那时，将扬起征帆远渡碧海青天。
【其二】
大道虽宽广如青天，唯独没有我的出路。
我不愿意追随长安城中的富家子弟，去搞斗鸡走狗一类的赌博游戏。
像冯谖那样弹剑作歌发牢骚，在权贵之门卑躬屈节，那不合我心意。
韩信发迹之前被淮阴市井之徒讥笑，贾谊才能超群遭汉朝公卿妒忌。
君不见古时燕昭王重用郭隗，拥彗折节、谦恭下士，毫不嫌疑猜忌。
剧辛和乐毅感激知遇的恩情，竭忠尽智，以自己的才能为君主效力。
而今燕昭王之白骨已隐于荒草之中，还有谁能像他那样重用贤士呢？
世路艰难，我只得归去啦！
【其三】
不要学许由用颍水洗耳，不要学伯夷和叔齐隐居首阳采薇而食。
在世上活着贵在韬光养晦，为什么要隐居清高自比云月？
我看自古以来的贤达之人，功绩告成之后不自行隐退都死于非命。
伍子胥被吴王弃于吴江之上，屈原最终抱石自沉汨罗江中。
陆机如此雄才大略也无法自保，李斯以自己悲惨的结局为苦。
陆机是否还能听见华亭别墅间的鹤唳？李斯是否还能在上蔡东门牵鹰打猎？
你不知道吴中的张翰是个旷达之人，因见秋风起而想起江东故都。
生时有一杯酒就应尽情欢乐，何须在意身后千年的虚名？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929ad635634aee3deb43", "shortContent": "“大道如青天，我独不得出。”这个开头与《行路难》第一首不同。第一首用赋的手法，从筵席上的美酒佳肴写起，起得比较平。这一首，一开头就陡起壁立，让久久郁积在内心里的感受，一下子喷发出来。亦赋亦比，使读者感到它的思想感情内容十分深广。后来孟郊写了“出门如有碍，谁谓天地宽”（《赠崔纯亮》）的诗句，可能受了此诗的启发，但气局比李白差多了。能够和它相比的，还是李白自己的诗“蜀道之难难于上青天”（《蜀道难》）这...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929a34a8757d5a0e1c23", "shortContent": "这是李白所写的三首《行路难》的第一首。这组诗从内容看，应该是写在天宝三载（744）李白离开长安的时候。\n诗的前四句写朋友出于对李白的深厚友情，出于对这样一位天才被弃置的惋惜，不惜金钱，设下盛宴为之饯行。“嗜酒见天真”的李白，要是在平时，因为这美酒佳肴，再加上朋友的一片盛情，肯定是会“一饮三百杯”的。然而，这一次他端起酒杯，却又把酒杯推开了；拿起筷子，却又把筷子撂下了。他离开坐席，拔下宝剑，举目四顾...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc40933", "shortContent": "这是李白所写的三首《行路难》的第一首。这组诗从内容看，应该是写在天宝三载（744）李白离开长安的时候。\n\n诗的前四句写朋友出于对李白的深厚友情，出于对这样一位天才被弃置的惋惜，不惜金钱，设下盛宴为之饯行。“嗜酒见天真”的李白，要是在平时，因为这美酒佳肴，再加上朋友的一片盛情，肯定是会“一饮三百杯”的。然而，这一次他端起酒杯，却又把酒杯推开了；拿起筷子，却又把筷子撂下了。他离开座席，拔下宝剑，举目四...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f0930a", "shortContent": "《行路难》是古乐府旧题，内容多写世路的艰难和离别的悲哀。《乐府诗集》列入杂曲歌辞。今存最早的作品是鲍照的十八首《拟行路难》。李白有三首《行路难》，作于不同时期，都受到了鲍照的影响。这里所选的是第一首，当是李白天宝三载（744）遭谗离京后作。\n\n诗人首先描写了一个“金樽清酒”、“玉盘珍馐”的宴会场面，他面对满桌美酒佳肴，拿起筷子，端起酒杯，却食不甘味。于是诗人推开杯盏，扔下碗筷，抽身而起，拔剑四顾，...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312704d73206168b2e021dc", "shortContent": "《行路难》是古乐府旧题，内容多写世路的艰难和离别的悲哀。《乐府诗集》卷七十收此诗，列入杂曲歌辞。今存最早的作品是鲍照的十八首《拟行路难》。李白有三首《行路难》，作于不同时期，都受到了鲍照的影响，这里所选的是第一首。\n\n诗人首先描写了一个“金樽清酒”、“玉盘珍馐”的宴会场面，他面对满桌美酒佳肴，拿起筷子，端起酒杯，却食不甘味，于是推开杯盏，扔下碗筷，抽身而起，拔剑四顾，想将它刺向一个地方，可又觉得茫...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127078f2af4e09d55b67a1", "shortContent": "《行路难》是古乐府旧题，内容多写世路的艰难和离别的悲哀。《乐府诗集》卷七十收此诗，列入杂曲歌辞。今存最早的作品是鲍照的十八首《拟行路难》。李白有三首《行路难》，作于不同时期，都受到了鲍照的影响，这里所选的是第一首。\n\n诗人首先描写了一个“金樽美酒”“玉盘珍馐”的宴会场面，他面对满桌美酒佳肴，拿起筷子，端起酒杯，却食不甘味，于是推开杯盏，扔下碗筷，抽身而起，拔剑四顾，想将它刺向一个地方，可又觉得茫然...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6466c9895b7b0d4f45194ccf", "shortContent": "这是李白所写的三首《行路难》的第一首。这组诗从内容看，应该是写在天宝三载（744）李白离开长安的时候。\n\n诗的前四句写朋友出于对李白的深厚友情，出于对这样一位天才被弃置的惋惜，不惜金钱，设下盛宴为之饯行。“嗜酒见天真”的李白，要是在平时，因为这美酒佳肴，再加上朋友的一片盛情，肯定是会“一饮三百杯”的。然而，这一次他端起酒杯，却又把酒杯推开了；拿起筷子，却又把筷子撂下了。他离开座席，拔下宝剑，举目四...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6466c9cb30675327e1915a40", "shortContent": "“大道如青天，我独不得出。”这个开头与《行路难》第一首不同。第一首用赋的手法，从筵席上的美酒佳肴写起，起得比较平。这一首，一开头就陡起壁立，让久久郁积在内心里的感受，一下子喷发出来。亦赋亦比，使读者感到它的思想感情内容十分深广。后来孟郊写了“出门如有碍，谁谓天地宽”（《赠崔纯亮》）的诗句，可能受了此诗的启发，但气局比李白差多了。能够和它相比的，还是李白自己的诗“蜀道之难难于上青天”（《蜀道难》）这...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f5965e6bb82b8cfbb55a", "shortContent": "这首诗一共十四句，八十二个字，在七言歌行中只能算是短篇，但它跳荡纵横，具有长篇的气势格局。其重要的原因之一，就在于它百步九折地揭示了诗人感情的激荡起伏、复杂变化。诗的一开头，“金樽清酒”，“玉盘珍羞”，让人感觉似乎是一个欢乐的宴会，但紧接着“停杯投箸”“拔剑四顾”两个细节，就显示了感情波涛的强烈冲击。中间四句，刚刚慨叹“冰塞川”“雪满山”，又恍然神游千载之上，仿佛看到了吕尚、伊尹由微贱而忽然得到君...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472a41e82772d459429b525", "shortContent": "这是李白所写的三首《行路难》的第一首。这组诗从内容看，应该是写在天宝三载（744）李白离开长安的时候。\n\n诗的前四句写朋友出于对李白的深厚友情，出于对这样一位天才被弃置的惋惜，不惜金钱，设下盛宴为之饯行。“嗜酒见天真”的李白，要是在平时，因为这美酒佳肴，再加上朋友的一片盛情，肯定是会“一饮三百杯”的。然而，这一次他端起酒杯，却又把酒杯推开了；拿起筷子，却又把筷子撂下了。他离开坐席，拔下宝剑，举目四...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472a47fe49f46528adf65b8", "shortContent": "“大道如青天，我独不得出”，首句与此题第一首不同。第一首用赋的手法，从筵席上的美酒佳肴写起，起得比较平。这一首，一开头就陡起壁立，让久久郁积在内心里的感受，一下子喷发出来。亦赋亦比，使读者感到它的思想感情内容十分深广。后来孟郊写了“出门如有碍，谁谓天地宽”的诗句，可能受了此诗的启发，但气局比李白差多了。能够和它相比的，还是李白自己的诗：“蜀道之难，难于上青天”这类诗句，大概只有李白那种胸襟才能写得...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}]', '《唐诗品汇》：刘云：结得不至鼠尾，甚善，甚善。
《李杜诗通》：《行路难》，叹世路艰难及贫贱离索之感。古辞亡，后鲍照拟作为多。白诗似全效照。
《唐宋诗醇》：冰寒雪满，道路之难甚矣。而日边有梦，破浪济海，尚未决志于去也。后有二篇，则畏其难而决去矣。此盖被放之初述怀如此，真写得「难」字意出。
《李太白诗醇》：句格长短错综，如缚龙蛇。
刘鉴《合刻李杜分体全集序》：青莲《梁父》、《行路》诸吟，《巧言》、《巷伯》之伦也。
《李太白诗醇》：严云：「天衢」亦是常语、作喻却奇。又云：第四句极粗，极雅。短句作结，结法警拔，寄托兀傲。', 'center', 1413387822, '57b5b11d1532bc0063ef39eb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10233, '浮生六记 · 卷三 · 坎坷记愁', NULL, 25, 5, 0, 1, '沈复', NULL, 10008, '57b9c0a079bc4400639c8182', '清', 'wen', '文', 'http://baike.baidu.com/view/1124871.htm', '', '人生坎坷何为乎来哉？往往皆自作孽耳，余则非也，多情重诺，爽直不羁，转因之为累。况吾父稼夫公慷慨豪侠，急人之难、成人之事、嫁人之女、抚人之儿，指不胜屈，挥金如土，多为他人。余夫妇居家，偶有需用，不免典质。始则移东补西，继则左支右决绌。谚云：“处家人情，非钱不行。”先起小人之议，渐招同室之讥。“女子无才便是德”，真千古至言也！余虽居长而行三，故上下呼芸为“三娘”。后忽呼为“三太太”，始而戏呼，继成习惯，甚至尊卑长幼，皆以“三太太”呼之，此家庭之变机欤？
乾隆乙巳，随侍吾父于海宁官舍。芸于吾家书中附寄小函，吾父曰：“媳妇既能笔墨，汝母家信付彼司之。”后家庭偶有闲言，吾母疑其述事不当，仍不令代笔。吾父见信非芸手笔，询余曰：“汝妇病耶？”余即作札问之，亦不答。久之，吾父怒曰：“想汝妇不屑代笔耳！”迨余归，探知委曲，欲为婉剖，芸急止之曰：“宁受责于翁，勿失欢于姑也。”竟不自白。
庚成之春，予又随侍吾父于邗江幕中，有同事俞孚亭者挈眷居焉。吾父谓孚亭曰：“一生辛苦，常在客中，欲觅一起居服役之人而不可得。儿辈果能仰体亲意，当于家乡觅一人来，庶语音相合。”罕亭转述于余，密札致芸，倩媒物色，得姚氏女．芸以成否未定，未即禀知吾母。其来也，托言邻女为嬉游者，及吾父命余接取至署，芸又听旁人意见，托言吾父素所合意者。吾母见之曰：“此邻女之嬉游者也，何娶之乎？”芸遂并失爱于姑矣。
壬子容，余馆真州。吾父病于邗江，余往省，亦病焉。余弟启堂时亦随待。芸来书曰：“启堂弟曾向邻妇借贷，倩芸作保，现追索甚急。”余询启堂，启堂转以嫂氏为多事，余遂批纸尾曰：“父子皆病，无钱可偿，俟启弟归时，自行打算可也。”未几病皆愈，余仍往真州。芸覆书来，吾父拆视之，中述启弟邻项事，且云：“令堂以老人之病留由姚姬而起，翁病稍痊，宜密瞩姚托言思家，妾当令其家父母到扬接取。实彼此卸责之计也。”吾父见书怒甚，询启堂以邻项事，答言不知，遂札饬余曰：“汝妇背夫借债，谗谤小叔，且称姑曰令堂，翁曰老人，悖谬之甚！我已专人持札回苏斥逐，汝若稍有人心，亦当知过！”余接此札，如闻青天霹雳，即肃书认罪，觅骑遄归，恐芸之短见也。到家述其本末，而家人乃持逐书至，历斥多过，言甚决绝。芸泣曰：“妾固不合妄言，但阿翁当恕妇女无知耳。”越数日，吾父又有手谕至，曰：“我不为已甚，汝携妇别居，勿使我见，免我生气足矣。”乃寄芸于外家，而芸以母亡弟出，不愿往依族中，幸友人鲁半舫闻而怜之，招余夫妇往居其家萧爽楼。
越两载，吾父渐知始未，适余自岭南归，吾父自至萧爽楼谓芸曰：“前事我已尽知，汝盍归乎？”余夫妇欣然，仍归故宅，骨肉重圆。岂料又有憨园之孽障耶！
芸素有血疾，以其弟克昌出亡不返。母金氏复念子病没，悲伤过甚所致，自识憨园，年余未发，余方幸其得良药。而憨为有力者夺去，以千金作聘，且许养其母。佳人已属沙叱利矣！余知之而未敢言也，及芸往探始知之，归而呜咽，谓余口：“初不料憨之薄情乃尔也！”余曰：“卿自情痴耳，此中人何情之有哉？况锦衣玉食者，未必能安于荆钗布裙也，雨其后悔，莫若无成。”因抚慰之再三。而芸终以受愚为恨，血疾大发，床席支离，刀圭无效，时发时止，骨瘦形销。不数年而逋负曰增，物议日起，老亲又以盟妓一端，憎恶日甚，余则调停中立。已非生人之境矣。
芸生一女名青君，时年十四，颇知书，且极贤能，质钗典服，幸赖辛劳。子名逢森，时年十二，从师读书。余连年无馆，设一书画铺于家门之内，三日所进，不敷一日所出，焦劳困苦，竭蹶时形。隆冬无裘，挺身而过，青君亦衣中股栗，犹强曰“不寒”。因是芸誓不医药。偶能起床，适余有友人周春煦自福郡王幕中归，倩人绣《心经》一部，芸念绣经可以消灾降福，且利其绣价之丰，竟绣焉。而春煦行色匆匆，不能久待，十日告成，弱者骤劳，致增腰酸头晕之疾。岂知命薄者，佛亦不能发慈悲也！
绣经之后，芸病转增，唤水索汤，上下厌之。有西人赁屋于余画铺之左，放利债为业，时倩余作画，因识之。友人某间渠借五十金，乞余作保，余以情有难却，允焉，而某竟挟资远遁。西人惟保是问，时来饶舌，初以笔墨为抵，渐至无物可偿。岁底吾父家居，西人索债，咆哮于门。吾父闻之，召余诃责曰：“我辈衣冠之家，何得负此小人之债！”正剖诉间，适芸有自幼同盟姊锡山华氏，知其病，遣人问讯。堂上误以为憨园之使，因愈怒曰：“汝妇不守闺训，结盟娼妓；汝亦不思习上，滥伍小人。若置汝死地，情有不忍．姑宽三日限，速自为计，退必首汝逆矣！”
芸闻而泣曰：“亲怒如此，皆我罪孽。妾死君行，君必不忍；妾留君去，君必不舍。姑密唤华家人来，我强起问之。”因令青君扶至房外，呼华使问曰：“汝主母特遗来耶？抑便道来耶？”曰：“主母久闻夫人卧病，本欲亲来探望，因从未登门，不敢造次，临行嘱咐：“倘夫人不嫌乡居简亵，不妨到乡调养，践幼时灯下之言。”盖芸与同绣日，曾有疾病相扶之誓也。因嘱之曰：“烦汝速归，禀知主母，于两日后放舟密来。”
其人既退，谓余曰：“华家盟姊情逾骨肉，君若肯至其家，不妨同行，但儿女携之同往既不便，留之累亲又不可，必于两日内安顿之。”时余有表兄王荩臣一子名韫石，愿得青君为媳妇。芸曰：“闻王郎懦弱无能，不过守成之子，而王又无成可守。幸诗礼之家，且又独子，许之可也。”余谓荩臣曰：“吾父与君有渭阳之谊，欲媳青君，谅无不允。但待长而嫁，势所不能。余夫妇往锡山后，君即禀知堂上，先为童熄；何如？”荩臣喜曰：“谨如命”。逢森亦托友人夏揖山转荐学贸易。
安顿已定，华舟适至，时庚申之腊二十五日也。芸曰：“孑然出门，不惟招邻里笑，且西人之项无着，恐亦不放，必于明日五鼓悄然而去。”余曰：“卿病中能冒晓寒耶？”芸曰；“死生有命，无多虑也。”密禀吾父，办以为然。是夜先将半肩行李挑下船，令逢森先卧。青君泣于母侧，芸嘱曰：“汝母命苦，兼亦情痴，故遭此颠沛，幸汝父待我厚，此去可无他虑。两三年内，必当布置重圆。汝至汝家须尽妇道，勿似汝母。汝之翁姑以得汝为幸，必善视汝。所留箱笼什物，尽付汝带去。汝弟年幼，故未令知，临行时托言就医，数日即归，俟我去远告知其故，禀闻祖父可也。”旁有旧妪，即前卷中曾赁其家消暑者，愿送至乡，故是时陪傍在侧，拭泪不已。将交五鼓，暖粥共啜之。芸强颜笑曰：“昔一粥而聚，今一粥而散，若作传奇，可名《吃粥记》矣。”逢森闻声亦起，呻曰：“母何为？”芸曰：“将出门就医耳。”逢森曰：“起何早？”曰：“路远耳。汝与姊相安在家，毋讨祖母嫌。我与汝父同往，数日即归。”鸡声三唱，芸含泪扶妪，启后门将出，逢森忽大哭曰：“噫，我母不归矣！”青君恐惊人，急掩其口而慰之．当是时，余两人寸肠已断，不能复作一语，但止以“匆哭”而已。青君闭们后，芸出巷十数步，已疲不能行，使妪提灯，余背负之而行。将至舟次，几为逻者所执，幸老妪认芸为病女，余为婿，且得舟子皆华氏工人，闻声接应，相扶下船。解维后，芸始放声痛哭。是行也，其母子已成永诀矣！
华名大成，居无锡之东高山，面山而居，躬耕为业，人极朴诚，其妻夏氏，即芸之盟姊也。是日午未之交，始抵其家。华夫人已倚门而侍，率两笑女至舟，相见甚欢，扶芸登岸，款待殷勤。四邻妇人孺子哄然入室，将芸环视，有相问讯者，有相怜惜者，交头接耳，满室啾啾。芸谓华夫人曰：“今日真如渔父入桃源矣。”华曰：“妹莫笑，乡人少所见多所怪耳。”自此相安度岁。
至元宵，仅隔两旬而芸渐能起步，是夜观龙灯于打麦场中，神情态度渐可复元。余乃心安，与之私议曰：“我居此非计，欲他适而短于资，奈何？”芸曰：“妾亦筹之矣。君姊丈范惠来现于靖江盐公堂司会计，十年前曾借君十金，适数不敷，妾典钗凑之，君忆之耶？”余曰：“忘之矣。”芸曰：“闻靖江去此不远，君盍一往？”余如其言。
时天颇暖，织绒袍哗叽短褂犹觉其热，此辛酉正月十六日也。是夜宿锡山客旅，赁被而卧。晨起趁江阴航船，一路逆风，继以微雨。夜至江阴江口，春寒彻骨，沽酒御寒，囊为之罄。踌躇终夜，拟卸衬衣质钱而渡。十九日北风更烈，雪势犹浓，不禁惨然泪落，暗计房资渡费，不敢再饮。正心寒股栗间，忽见一老翁草鞋毡笠负黄包，入店，以目视余，似相识者。余曰：“翁非泰州曹姓耶？”答曰：“然。我非公，死填沟壑矣！今小女无恙，时诵公德。不意今日相逢，何逗留于此？”盖余幕泰州时有曹姓，本微贱，一女有姿色，已许婿家，有势力者放债谋其女，致涉讼，余从中调护，仍归所许，曹即投入公们为隶，叩首作谢，故识之。余告以投亲遇雪之由，曹曰：“明日天晴，我当顺途相送。”出钱沽酒，备极款洽。二十日晓钟初动，即闻江口唤渡声，余惊起，呼曹同济。曹曰：“勿急，宜饱食登舟。”乃代偿房饭钱，拉余出沽。余以连日逗留，急欲赶渡，食不下咽，强啖麻饼两枚。及登舟，江风如箭，四肢发战。曹曰：“闻江阴有人缢于靖，其妻雇是舟而往，必俟雇者来始渡耳。”枵腹忍寒，午始解缆。至靖，暮烟四合矣。曹曰：“靖有公堂两处，所访者城内耶？城外耶？”余踉跄随其后，且行且对曰：“实不知其内外也。”曹曰：“然则且止宿，明日往访耳。”进旅店，鞋袜已为泥淤湿透，索火烘之，草草饮食，疲极酣睡。晨起，袜烧其半，曹又代偿房饭钱。访至城中，惠来尚未起，闻余至，披衣出，见余状惊曰：“舅何狼狈至此？”余曰：“姑勿问，有银乞借二金，先遣送我者。”惠来以香饼二圆授余，即以赠曹。曹力却，受一圆而去。余乃历述所遭，并言来意。惠来曰：“郎舅至戚，即无宿逋，亦应竭尽绵力，无如航海盐船新被盗，正当盘帐之时，不能挪移丰赠，当勉描番银二十圆以偿旧欠，何如？”余本无奢望，遂诺之．
留住两日，天已晴暖，即作归计。二十五日仍回华宅。芸曰：“君遇雪乎？”余告以所苦。因惨然曰：“雪时，妾以君为抵靖，乃尚逗留江口。幸遇曹老，绝处逢生，亦可谓吉人天相矣。”越数日，得青君信，知逢森已为揖山荐引入店，荩臣请命于吾父，择正月二十四日将伊接去。儿女之事粗能了了，但分离至此，令人终觉惨伤耳。
二月初，日暖风和，以靖江之项薄备行装，访故人胡肯堂于邗江盐署，有贡局众司事公延入局，代司笔墨，身心稍定。至明年壬戌八月，接芸书曰：“病体全廖，惟寄食于非亲非友之家，终觉非久长之策了，愿亦来邗，一睹平山之胜。”余乃赁屋于邗江先春门外，临河两椽，自至华氏接芸同行。华夫人赠一小奚奴曰阿双，帮司炊爨，并订他年结邻之约。
时已十月，平山凄冷，期以春游。满望散心调摄，徐图骨肉重圆。不满月，而贡局司事忽裁十有五人，余系友中之友，遂亦散闲。芸始犹百计代余筹画，强颜慰藉，未尝稍涉怨尤。至癸亥仲春，血疾大发。余欲再至靖江作将伯之呼，芸曰：“求亲不如求友。”余曰：“此言虽是，亲友虽关切，现皆闲处，自顾不遑。”芸曰：“幸天时已暖，前途可无阻雪之虑，愿君速去速回，勿以病人为念。君或体有不安，妾罪更重矣。”时已薪水不继，余佯为雇骡以安其心，实则囊饼徒步，且食且行。向东南，两渡叉河，约八九十里，四望无村落。至更许，但见黄沙漠漠，明星闪闪，得一土地祠，高约五尺许，环以短墙，植以双柏，因向神叩首，祝曰：“苏州沈某投亲失路至此，欲假神祠一宿，幸神怜佑。”于是移小石香炉于旁，以身探之，仅容半体。以风帽反戴掩面，坐半身于中，出膝于外，闭目静听，微风萧萧而已。足疲神倦，昏然睡去。及醒，东方已白，短墙外忽有步语声，急出探视，盖土人赶集经此也。问以途，曰；“南行十里即泰兴县城，穿城向东南十里一土墩，过八墩即靖江，皆康庄也。”余乃反身，移炉于原位，叩首作谢而行。过泰兴，即有小车可附。申刻抵靖。投刺焉。良久，司阍者曰：“范爷因公往常州去矣。”察其辞色，似有推托，余诘之曰：“何日可归？”曰：“不知也。”余曰：“虽一年亦将待之。”阍者会余意，私问曰：“公与范爷嫡郎舅耶？”余曰：“苟非嫡者，不待其归矣。”阍者曰：“公姑待之。”越三日，乃以回靖告，共挪二十五金。
雇骡急返，芸正形容惨变，咻咻涕泣。见余归，卒然曰：“君知昨午阿双卷逃乎？倩人大索，今犹不得。失物小事，人系伊母临行再三交托，今若逃归，中有大江之阻，已觉堪虞，倘其父母匿子图诈，将奈之何？且有何颜见我盟姊？”余曰：“请勿急，卿虑过深矣。匿子图诈，诈其富有也，我夫妇两肩担一口耳，况携来半载，授衣分食，从未稍加扑责，邻里咸知。此实小奴丧良，乘危窃逃。华家盟姊赠以匪人，彼无颜见卿，卿何反谓无颜见彼耶？今当一面呈县立案，以杜后患可也。”芸闻余言，意似稍释。然自此梦中呓语，时呼“阿双逃矣”，或呼“憨何负我”，病势日以增矣。
余欲延医诊治，芸阻曰；“妾病始因弟亡母丧，悲痛过甚，继为情感，后由忿激，而平素又多过虑，满望努力做一好媳妇，而不能得，以至头眩、怔忡诸症毕备，所谓病人膏盲，良医束手，请勿为无益之费。忆妾唱随二十三中，蒙君错爱，百凡体恤，不以顽劣见弃，知己如君，得婿如此，妾已此生无憾！若布衣暖，菜饭饱，一室雍雍，优游泉石，如沧浪亭、萧爽楼之处境，真成烟火神仙矣。神仙几世才能修到，我辈何人，敢望神仙耶？强而求之，致干造物之忌，即有情魔之扰。总因君太多情，妾生薄命耳！”因又呜咽而言曰：“人生百年，终归一死。今中道相离，忽焉长别，不能终奉箕帚、目睹逢森娶妇，此心实觉耿耿。”言已，泪落如豆。余勉强慰之曰：“卿病八年，恹恹欲绝者屡矣，今何忽作断肠语耶？”芸曰：“连日梦我父母放舟来接，闭目即飘然上下，如行云雾中，殆魂离而躯壳存乎？”余曰：“此神不收舍，服以补剂，静心调养，自能安痊。”芸又唏嘘曰：“妾若稍有生机—线，断不敢惊君听闻。今冥路已近，苟再不言，言无日矣．君之不得亲心，流离颠沛，皆由妾故，妾死则亲心自可挽回，君亦可免牵挂。堂上春秋高矣，妾死，君宜早归。如无力携妾骸骨归，不妨暂居于此，待君将来可耳。愿君另续德容兼备者，以奉双亲，抚我遗子，妾亦瞑目矣。”言至此，痛肠欲裂，不觉惨然大恸。余曰：“卿果中道相舍，断无再续之理，况‘曾经沧海难为水，除却巫山不是云’耳。”芸乃执余手而更欲有言，仅断续叠言“来世”二宇，忽发喘口噤，两目瞪视，千呼万唤已不能言。痛泪两行，涔涔流溢．既而喘沥微，泪渐干，一灵缥缈，竟尔长逝！时嘉庆癸亥三月三十日也。当是时，孤灯一盏，举目无亲，两手空拳，寸心欲碎。绵绵此恨，曷其有极！
承吾友胡省堂以十金为助，余尽室中所有，变卖一空，亲为成殓。呜呼！芸一女流，具男子之襟怀才识。归吾门后，余日奔走衣食，中馈缺乏，芸能纤悉不介意。及余家居，惟以文字相辩析而已。卒之疾病颠连，赍恨以没，谁致之耶？余有负闺中良友，又何可胜道哉？！奉劝世间夫妇，固不可彼此相仇，亦不可过于情笃。话云“恩爱夫妻不到头”，如余者，可作前车之鉴也。
回煞之期，俗传是日魂必随煞而归，故居中铺设一如生前，且须铺生前旧衣于床上，置旧鞋于床下，以待魂归瞻顾，吴下相传谓之“收眼光”。延羽士作法，先召于床而后遣之，谓之“接眚”。邗江俗例，设酒肴于死者之室。一家尽出，调之“避眚”。以故有因避被窃者。芸娘眚期，房东因同居而出避，邻家嘱余亦设肴远避。众冀魄归一见，姑漫应之。同乡张禹门谏余曰：“因邪入邪，宜信其有，勿尝试也。”余曰：“所以不避而待之者，正信其有也。”张曰：“回煞犯煞不利生人，夫人即或魂归，业已阴阳有间，窃恐欲见者无形可接，应避者反犯其锋耳。”时余痴心不昧，强对曰：“死生有命。君果关切，伴我何如？”张口：“我当于门外守之，君有异见，一呼即入可也。”余乃张灯入室，见铺设宛然而音容已杳，不禁心伤泪涌。又恐泪眼模糊失所欲见，忍泪睁目，坐床而待。抚其所遗旧服，香泽犹存，不觉柔肠寸断，冥然昏去。转念待魂而来，何去遽睡耶？开目四现，见席上双烛青焰荧荧，缩光如豆，毛骨悚然，通体寒栗。因摩两手擦额，细瞩之，双焰渐起，高至尺许，纸裱顶格几被所焚。余正得借光四顾间，光忽又缩如前。此时心舂股栗，欲呼守者进观，而转念柔魂弱魄，恐为盛阳所逼，悄呼芸名而祝之，满室寂然，一无所见，既而烛焰复明，不复腾起矣。出告禹门，服余胆壮，不知余实一时情痴耳。
芸没后，忆和靖“妻梅子鹤”语，自号梅逸。权葬芸于扬州西门外之金桂山，俗呼郝家宝塔。买一棺之地，从遗言寄于此。携木主还乡，吾母亦为悲悼，青君、逢森归来，痛哭成服。启堂进言曰：“严君怒犹未息，兄宜仍往扬州，俟严君归里，婉言劝解，再当专札相招。”余遂拜母别子女，痛哭一场，复至扬州，卖画度日。因得常哭于芸娘之墓，影单形只，备极凄凉，且偶经故居，伤心惨目。重阳日，邻冢皆黄，芸墓独青，守坟者曰：“此好穴场，故地气旺也。”余暗祝曰：“秋风已紧，身尚衣单，卿若有灵，佑我图得一馆，度此残年，以持家乡信息。”未几，江都幕客章驭庵先生欲回浙江葬亲，倩余代庖三月，得备御寒之具。封篆出署，张禹门招寓其家。张亦失馆，度岁艰难，商于余，即以余资二十金倾囊借之，且告曰：“此本留为亡荆扶柩之费，一俟得有乡音，偿我可也。”是年即寓张度岁，晨占夕卜，乡音殊杳。
至甲子三月，接青君信，知吾父有病。即欲归苏，又恐触旧忿。正趑趄观望间，复接青君信，始痛悉吾父业已辞世。刺骨痛心，呼天莫及。无暇他计，即星夜驰归，触首灵前，哀号流血。呜呼！吾父一生辛苦，奔走于外。生余不肖，既少承欢膝下，又未侍药床前，不孝之罪何可逭哉！吾母见余哭，曰：“汝何此日始归耶？”余曰：“儿之归，幸得青君孙女信也。”吾母目余弟妇，遂默然。余入幕守灵至七，终无一人以家事告，以丧事商者。余自问人子之道已缺，故亦无颜询问。
一日，忽有向余索逋者登门饶舌，余出应曰，“欠债不还，固应催索，然吾父骨肉未寒，乘凶追呼，未免太甚。”中有一人私谓余曰：“我等皆有人招之使来，公且避出，当向招我者索偿也。”余曰：“我欠我偿，公等速退！”皆唯唯而去。余因呼启堂谕之曰：“兄虽不肖，并未作恶不端，若言出嗣降服，从未得过纤毫嗣产，此次奔丧归来，本人子之道，岂为产争故耶？大丈夫贵乎自立，我既一身归，仍以一身去耳！”言已，返身入幕，不觉大恸。叩辞吾母，走告青君，行将出走深山，求赤松子于世外矣。
青君正劝阻间，友人夏南熏字淡安、夏逢泰字揖山两昆季寻踪而至，抗声谏余曰：“家庭若此，固堪动忿，但足下父死而母尚存，妻丧而子未立，乃竟飘然出世，于心安乎。”余曰：“然则如之何？”淡安曰：“奉屈暂居寒舍，闻石琢堂殿撰有告假回籍之信，盍俟其归而往谒之？其必有以位置君也。”余曰：“凶丧未满百日，兄等有老亲在堂，恐多未便。”揖山曰：“愚兄弟之相邀，亦家君意也。足下如执以为不便，四邻有禅寺，方丈僧与余交最善，足下设榻于寺中，何如？”余诺之。青君曰：“祖父所遗房产，不下三四千金，既已分毫不取。岂自己行囊亦舍去耶？我往取之，径送禅寺父亲处可也。”因是于行囊之外，转得吾父所遗图书、砚台、笔筒数件。
寺僧安置予于大悲阁。阁南向，向东设神像，隔西首一间，设月窗，紧对佛龛，中为作佛事者斋食之地。余即设榻其中，临门有关圣提刀立像，极威武。院中有银杏一株，大三抱，荫覆满阁，夜静风声如吼。揖山常携酒果来对酌，曰：“足下一人独处，夜深不寐，得无畏怖耶？”余口：“仆一生坦直，胸无秽念，何怖之有？”居未几，大雨倾盆，连宵达旦三十条天，时虑银杏折枝，压梁倾屋。赖神默佑，竟得无恙。而外之墙坍屋倒者不可胜计，近处田禾俱被漂没。余则日与僧人作画，不见不闻。七月初，天始霁，揖山尊人号几莼芗有交易赴崇明，偕余往，代笔书券得二十金。归，值吾父将安葬，启堂命逢森向余曰：“叔因葬事乏用，欲助一二十金。”余拟倾囊与之，揖山不允，分帮其半。余即携青君先至墓所，葬既毕，仍返大悲阁。九月杪，揖山有田在东海永寨沙，又偕余往收其息。盘桓两月，归已残冬，移寓其家雪鸿草堂度岁。真异姓骨肉也。
乙丑七月，琢堂始自都门回籍。琢堂名韫玉，字执如，琢堂其号也，与余为总角交。乾隆庚戌殿元，出为四川重庆守。白莲教之乱，三年戎马，极著劳绩。及归，相见甚欢，旋于重九日挈眷重赴四川重庆之任，邀余同往。余即四别吾母于九妹倩陆尚吾家，盖先君故居已属他人矣。吾母嘱曰“汝弟不足恃，汝行须努力。重振家声，全望汝也！”逢森送余至半途，忽泪落不已，因嘱勿送而返。舟出京口，琢堂有旧交王惕夫孝廉在淮扬盐署，绕道往晤，余与偕往，又得一顾芸娘之墓。返舟由长江溯流而上，一路游览名胜。至湖北之荆州，得升潼关观察之信，遂留余雨其嗣君敦夫眷属等，暂寓荆州，琢堂轻骑减从至重庆度岁，遂由成都历栈道之任。丙寅二月，川眷始由水路往，至樊城登陆。途长费短，车重人多，毙马折轮，备尝辛苦。抵潼关甫三月，琢堂又升山左廉访，清风两袖。眷属不能偕行，暂借潼川书院作寓。十月杪，始支山左廉俸，专人接眷。附有青君之书，骇悉逢森于四月间夭亡。始忆前之送余堕泪者，盖父子永诀也。呜呼！芸仅一子，不得延其嗣续耶！琢堂闻之，亦为之浩叹，赠余一妾，重入春梦。从此扰扰攘攘，又不知梦醒何时耳。', '本文节选自《浮生六记·卷三·坎坷记愁》。', '', '', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9c0ce818559d071264", "shortContent": "《聊斋志异》写狐女、鬼女的篇什很多，本篇所写却是鼠女，令人有耳目一新之感。\n阿纤的性格特征可以说是秀外慧中。奚山借宿古家，阿纤出来行酒，她在奚山眼中的形象是“年十六七，窈窕秀弱，风致嫣然”。古叟死后，奚山路遇古媪及阿纤，也是阿纤先“频转顾”，继而“把媪袂，附耳不知何辞”，古媪才停步相认，成就了阿纤和奚山之弟三郎的一段姻缘。阿纤过门以后，“寡言少怒，或与言，但有微笑；昼夜绩织无停晷：以是上下俱怜悦之...", "authors": ["赵山林"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa87d0ac1145496bcec", "shortContent": "本篇故事叙述一对恩爱夫妻之间真挚的感情：孙某与妻子“伉俪甚笃”，孙某妻子病逝，孙某十分悲伤郁闷，便外出饮酒。谁知醉归途中遇鬼且受到鬼的无理纠缠讹诈，以致中邪。孙某亡妻为了保护自己的丈夫，奋起与鬼作了针锋相对的说理斗争，最后终于挫败了鬼的讹诈，使丈夫转危为安。通过这个故事，一个忠贞地挚爱丈夫而又机智勇敢的妇女形象跃然纸上。一位已死的妇女得知活着的丈夫有难，竟毫无畏惧地赶来相助，充分地表现了爱情的伟大...", "authors": ["胡邦炜"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42c603572034f65b6af1", "shortContent": "本篇选自纪昀晚年所撰《阅微草堂笔记》，题目系笔者所加。\n小说记叙的是一对夫妻咫尺千里、睽离难合的悲剧故事。故事本身具有很强的传奇色彩，但与《聊斋志异》不同，作者并未铺采摛文，展开细微曲折、摹绘如生的场面和情景描写，而只是平实自然地叙述其原委。这固然在生动形象的感染力上逊于《聊斋》之文，但却增强了故事的可信性和切实感，自有其长处。\n在人伦关系上，夫妻是最为亲密的，同卧同起，相携相伴。然而李生与其妻子...", "authors": ["李永祥"], "pressName": "上海辞书出版社"}]', '', 'indent', 1478216795, '57ea0e6da22b9d006163db4c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10234, '浮生六记 · 卷四 · 浪游记快', NULL, 32, 5, 0, 3, '沈复', NULL, 10008, '57b9c0a079bc4400639c8182', '清', 'wen', '文', '', '', '余游幕三十年来，天下所未到者，蜀中、黔中与滇南耳。惜乎轮蹄徵逐，处处随人，山水怡情，云烟过眼，不道领略其大概，不能探僻寻幽也。余凡事喜独出己见，不屑随人是非，即论诗品画，莫不存人珍我弃、人弃我取之意，故名胜所在，贵乎心得，有名胜而不觉其佳者，有非名胜而自以为妙者，聊以平生历历者记之。
余年十五时，吾父稼夫公馆于山阴赵明府幕中。有赵省斋先生名传者，杭之宿儒也，赵明府延教其子，吾父命余亦拜投门下。暇日出游，得至吼山，离城约十馀里。不通陆路。近山见一石洞，上有片石横裂欲堕，即从其下荡舟入。豁然空其中，四面皆峭壁，俗名之曰「水园」。临流建石阁五椽，对面石壁有「观鱼跃」三字，水深不测，相传有巨鳞潜伏，余投饵试之，仅见不盈尺者出而唼食焉。阁后有道通旱园，拳石乱矗，有横阔如掌者，有柱石平其顶而上加大石者，凿痕犹在，一无可取。游览既毕，宴于水阁，命从者放爆竹，轰然一响，万山齐应，如闻霹雳生。此幼时快游之始。惜乎兰亭、禹陵未能一到，至今以为憾。
至山阴之明年，先生以亲老不远游，设帐于家，余遂从至杭，西湖之胜因得畅游。结构之妙，予以龙井为最，小有天园次之。石取天竺之飞来峰，城隍山之瑞石古洞。水取玉泉，以水清多鱼，有活泼趣也。大约至不堪者，葛岭之玛瑙寺。其馀湖心亭、六一泉诸景，各有妙处，不能尽述，然皆不脱脂粉气，反不如胁室之幽僻，雅近天然。
苏小墓在西泠桥侧。土人指示，初仅半丘黄土而已，乾隆庚子圣驾南巡，曾一询及，甲辰春复举南巡盛典，则苏小墓已石筑其坟，作八角形，上立一碑，大书曰：「钱塘苏小小之墓」。从此吊古骚人不须徘徊探访矣。馀思古来烈魄忠魂堙没不传者，固不可胜数，即传而不久者亦不为少，小小一名妓耳，自南齐至今。尽人而知之，此殆灵气所钟，为湖山点缀耶？
桥北数武有祟文书院，余曾与同学赵缉之投考其中。时值长夏，起极早，出钱塘门，过昭庆寺，上断桥，坐石阑上。旭日将升，朝霞映于柳外，尽态极妍；白莲香里，清风徐来，令人心骨皆清。步至书院，题犹未出也。午后交卷。
偕缉之纳凉于紫云洞，大可容数十人，石窍上透日光。有入设短几矮凳，卖酒于此。解衣小酌，尝鹿脯甚妙，佐以鲜菱雪藕，微酣出洞。缉之曰：「上有朝阳台，颇高旷，盍往一游？」余亦兴发，奋勇登其巅，觉西湖如镜，杭城如丸，钱塘江如带，极目可数百里。此生平第一大观也。坐良久，阳乌将落，相携下山，南屏晚钟动矣。韬光、云栖路远未到，其红门局之梅花，姑姑庙之铁树，不过尔尔。紫阳洞予以为必可观，而访寻得之，洞口仅容—指，涓涓流水而已，相传中有洞天，恨不能抉门而入。
清明日，先生春祭扫墓，挈余同游。墓在东岳，是乡多竹，坟厄未出土之毛笋，形如梨而尖，作羹供客。余甘之，尽其两碗。先生曰：「噫！是虽味美而克心血，宜多食肉以解之。」余素不贪屠门之嚼，至是饭量且因笋而减，归途觉烦躁，唇舌几裂。过石屋洞，不甚可观。水乐洞峭壁多藤萝，入洞如斗室，有泉流甚急，其声琅琅。池广仅三尺，深五寸许，不溢亦不竭。余俯流就饮，烦躁顿解。洞外二小亭，坐其中可听泉声。衲子请观万年缸。缸在香积厨，形甚巨，以竹引泉灌其内，听其满溢，年久结苔厚尺许，冬日不冰，故不损也。
辛丑秋八月，吾父病疟返里，寒索火，热索冰，余谏不听，竟转伤寒，病势日重。余侍奉汤药，昼夜不交睫者几一月。吾妇芸娘亦大病，恹恹在床。心境恶劣，莫可名状。吾父呼余嘱之曰：「我仓不起，汝守数本书，终非糊口计，我托汝于盟弟蒋思斋，仍继吾业可耳。」越日思斋来，即于榻前命拜为师。未几，得名医徐观莲先生诊治，父病渐痊。芸亦得徐力起床。而余则从此习幕矣。此非快事，何记于此？曰：此抛书浪游之始，故记之。
思斋先生名襄，是年冬，即相随习幕于奉贤官舍。有同习幕者，顾姓名金鉴，字鸿干，号紫霞，亦苏州人也。为人慷慨刚毅，直谅不阿，长馀一岁，呼之为兄。鸿干即毅然呼余为弟，倾心相交。此余第一知己交也，惜以二十二岁卒，余即落落寡交，今年且四十有六矣，茫茫沧海，不知此生再遇知己如鸿干者否？
忆与鸿干订交，襟怀高旷，时兴山居之想。重九日，余与鸿干俱在苏，有前辈王小侠与吾父稼夫公唤女伶演剧，宴客吾家，余患其扰，先一日约鸿干赴寒山登高，借访他日结庐之地。芸为整理衅榼。
越日天将晓，鸿干已登门相邀。遂携榼出胥门，入面肆，各饱食。渡胥江，步至横塘枣市桥，雇一叶扁舟，到山日犹未午。舟子颇循良，令其籴米煮饭。余两人上岸，先至中峰寺。寺在支硎古刹之南，循道而上，寺藏深树，山门寂静，地僻僧闲，见余两人不衫不履，不甚接待，余等志不在此，未深入。归舟，饭已熟。饭毕，舟子携榼相随，嘱其子守船，由寒山至高义园之自云精舍。轩临峭壁，飞凿小池，围以石栏，一泓秋水，崖悬薜荔，墙积霉苔。坐轩下，惟闻落叶萧萧，悄无人迹。出门有一亭，嘱舟子坐此相候。余两人从石罅中入，名「一线天」，循级盘旋，直造其巅，曰「上白云」，有庵已坍颓，存一危栈，仅可远眺。小憩片刻，即相扶而下，舟子曰：「登高忘携酒榼矣。」鸿干曰：「我等之游，欲觅偕隐地耳，非专为登高也。」舟子曰：「离此南行二三里，有上沙村，多人家，有隙地，我有表戚范姓居是村，盍往一游？」余喜曰：「此明末徐俟斋先生隐居处也，有园闻极幽雅，从未一游。」于是舟子导往。村在两山夹道中。园依山而无石，老树多极纡回盘郁之势，亭榭窗栏尽从朴素，竹篱茆舍，不愧隐者之居。中有皂荚亭，树大可两抱。余所历园亭，此为第一。园左有山，俗呼鸡笼山，山峰直竖，上加大石，如杭城之瑞石古洞，而不及其玲珑。旁一青石加榻，鸿干卧其上曰：「此处仰观峰岭，俯视园亭，既旷且幽，可以开樽矣。」因拉舟子同饮，或歌或啸，大畅胸怀。土人知余等觅地而来，误以为堪舆，以某处有好风水相告。鸿干曰：「但期合意，不论风水。」（岂意竟成谶语！）酒瓶既罄，各采野菊插满两鬓。
归舟，日已将没。更许抵家，客犹未散。芸私告余曰：「女伶中有兰官者，端庄可取。」余假传母命呼之入内，握其腕而睨之，果丰颐白腻。余顾芸曰：「美则美矣，终嫌名不称实。」芸曰：「肥者有福相。」余曰：「马嵬之祸，玉环之福安在？」芸以他辞遣之出。谓余曰：「今日君又大醉耶？」余乃历述所游，芸亦神往者久之。
癸卯春，余从思斋先生就维扬之聘，始见金、焦面目。金山宜远观，焦山宜近视，惜余往来其间未尝登眺。渡江而北，渔洋所谓「绿杨城郭是扬州」一语已活现矣！平山堂离城约三四里，行其途有八九里，虽全是人工，而奇思幻想，点缀天然，即阆苑瑶池、琼楼玉宇，谅不过此。其妙处在十馀家之园亭合而为一，联络至山，气势俱贯。其最难位置处，出城入景，有一里许紧沿城郭。夫城缀于旷远重山间，方可入画，园林有此，蠢笨绝伦。而观其或亭或台、或墙或石、或竹或树，半隐半露间，使游人不觉其触目，此非胸有丘壑者断难下手。城尽，以虹园为首折面向北，有石梁曰「虹桥」，不知园以桥名乎？桥以园名乎？荡舟过，曰「长堤春柳」，此景不缀城脚而缀于此，更见布置之妙。再折而西，垒土立庙，曰「小金山」，有此一挡便觉气势紧凑，亦非俗笔。闻此地本沙土，屡筑不成，用木排若干，层叠加土，费数万金乃成，若非商家，乌能如是。过此有胜概楼，年年观竞渡于此。河面较宽，南北跨一莲花桥，桥门通八面，桥面设五亭，扬人呼为「四盘一暖锅」，此思穷力竭之为，不甚可取。桥南有莲心寺，寺中突起喇嘛白塔，金顶缨络，商矗云霄，殿角红墙松柏掩映，钟磬时闻，此天下园亭所未有者。过桥见三层高阁，画栋飞檐，五采绚烂，叠以太湖石，围以白石栏，名目「五云多处」，如作文中间之大结构也。过此名「蜀冈朝阳」，平坦无奇，且属附会。将及山，河面渐束，堆土植竹树，作四五曲。似已山穷水尽，而忽豁然开朗，平山之万松林已列于前矣。「平山堂」为欧阳文忠公所书。所谓淮东第五泉，真者在假山石洞中，不过一井耳，味与天泉同；其荷亭中之六孔铁井栏者，乃系假设，水不堪饮。九峰园另在南门幽静处，别饶天趣，余以为诸园之冠。康山未到，不识如何。此皆言其大概，其工巧处、精美处，不能尽述，大约宜以艳妆美人目之，不可作浣纱溪上观也。余适恭逢南巡盛典，各工告竣，敬演接驾点缀，因得畅其大观，亦人生难遇者也。
甲辰之春，余随待吾父于吴江明府幕中，与山阴章苹江、武林章映牧、苕溪颐蔼泉诸公同事，恭办南斗圩行宫，得第二次瞻仰天颜。一日，天将晚矣，忽动归兴。有办差徐船，双舻两浆，于太湖飞棹疾驰，吴俗呼为「出水辔头」，转瞬已至吴门桥。即跨鹤腾空，无此神爽。抵家，晚餐未熟也。吾乡素尚繁华，至此日之争奇夺胜，较昔尤奢。灯彩眩眸，笙歌聒耳，古人所谓「画栋雕甍」、「珠帘绣幕」、「玉栏杆」、「锦步障」，不啻过之。余为友人东拉西扯，助其插花结彩，闲则呼朋引类，剧饮狂歌，畅怀游览，少年豪兴，不倦不疲。苟生于盛世而仍居僻壤，安得此游观哉？
是年，何明府因事被议，吾父即就海宁王明府之聘。嘉兴有刘蕙阶者，长斋佞佛，来拜吾父。其家在烟雨楼侧，一阁临河，曰「水月居」，其诵经处也，洁静如僧舍。烟雨楼在镜湖之中，四岸皆绿杨，惜无多竹。有平台可远眺，渔舟星列，漠漠平波，似宜月夜。衲子备素斋甚佳。至海宁，与白门史心月、山阴俞午桥同事。心月一子名烛衡，澄静缄默，彬彬儒雅，与余莫逆，此生平第二知心交也。惜萍水相逢，聚首无多日耳。游陈氏安澜园，地占百亩，重楼复阁，夹道回廊；池甚广，桥作六曲形；石满藤萝，凿痕全掩；古木千章，皆有参天之势；鸟啼花落，如入深山。此人工而归于天然者。余所历平地之假石园亭，此为第一。曾于桂花楼中张宴，诸味尽为花气所夺，惟酱姜味不变。姜接之性老而愈辣，以喻忠节之臣，洵不虚也。出南门即大海，一日两潮，如万丈银堤破海而过。船有迎潮者，潮至，反棹相向，于船头设一木招，状如长柄大刀，招一捺，潮即分破，船即随招而入，俄顷始浮起，拨转船头随潮而去，顷刻百里。塘上有塔院，中秋夜曾随吾父观潮于此。循塘东约三十里，名尖山，一峰突起，扑入海中，山顶有阁，匾曰「海阔天空」，一望无际，但见怒涛接天而已。
余年二十有五，应徽州绩溪克明府之召，由武林下「江山船」，过富春山，登子陵钓台。台在山腰，一峰突起，离水十馀丈。岂汉时之水竞与峰齐耶？月夜泊界口，有巡检署，「山高月小，水落石出」，此景宛然。黄山仅见其脚，惜未一瞻面目。绩溪城处于万山之中，弹丸小邑，民情淳朴。近城有石镜山，由山弯中曲折中里许，悬崖急湍，湿翠欲滴；渐高至山腰，有一方石亭，四面皆陡壁；亭左石削如屏，青色光润，可鉴人形，俗传能照前生。黄巢至此，照为猿猴形，纵火焚之，故不复现。离域十里有火云洞天，石纹盘结，凹凸廛岩，如黄鹤山樵笔意，而杂乱无章，洞石皆深绛色。旁有一庵甚幽静，盐商程虚谷曾招游设宴于此。席中有肉馒头，小沙弥眈眈旁视，授以四枚，临行以番银二圆为酬，山僧不识，推不受。告以一枚可易青钱七百馀文，僧以近无易处，仍不受。乃攒凑青蚨六百文付之，始欣然作谢。他日余邀同人携榼再往，老僧嘱曰：「曩者小徒不知食何物而腹泻，今勿再与。」可知藜藿之腹不受肉味，良可叹也。余谓同人曰：「作和尚者，必用此等僻地，终身不见不闻，或可修真养静。若吾乡之虎丘山，终日目所见者妖童艳妓，耳所听者弦索笙歌，鼻所闻者佳肴美酒，安得身如枯木、心如死灰哉？」
又去城三十里，名曰仁里，有花果会，十二年一举，每举各出盆花为赛。余在绩溪适逢其会，欣然欲往，苦无轿马，乃教以断竹为杠，缚椅为轿，雇人肩之而去，同游者惟同事许策廷，见者无不讶笑。至其地，有庙，不知供何神。庙前旷处高搭戏台，画梁方柱极其巍焕，近视则纸札彩画，抹以油漆者。锣声忽至，四人抬对烛大如断柱，八人抬一猪大若牯牛，盖公养十二年始宰以献神。策廷笑曰：「猪固寿长，神亦齿利。我若为神，乌能享此。」余曰：「亦足见其愚诚也。」入庙，殿廊轩院所设花果盆玩，并不剪枝拗节，尽以苍老古怪为佳，大半皆黄山松。既而开场演剧，人如潮涌而至，余与策廷遂避去。未两载，余与同事不合，拂衣归里。
余自绩溪之游，见热闹场中卑鄙之状不堪入目，因易儒为贾。余有姑丈袁万九，在盘溪之仙人塘作酿酒生涯，余与施心耕附资合夥。袁酒本海贩，不一载，值台湾林爽文之乱，海道阻隔，货积本折，不得已仍为冯妇。馆江北四年，一无快游可记。迨居萧爽楼，正作烟火神仙，有表妹倩徐秀峰自粤东归，见余阅居，慨然曰：「足下待露而爨，笔耕而炊，终非久计，盍偕我作岭南游？当不仅获蝇头利也。」芸亦劝余曰：「乘此老亲尚健，子尚壮年，与其商柴计米而寻欢，不如一劳永逸。」余乃商诸交游者，集资作本。芸会亦自办绣货及岭南所无之苏酒醉蟹等物。禀知堂上，于小春十日，偕秀峰由东坝出芜湖口。
长江初历，大畅襟怀。每晚舟泊后，必小酌船头。见捕鱼者罾幂不满三尺，孔大约有四寸，铁箍四角，似取易沉。余笑曰：「圣人之教虽曰『罟不用数』，而如此之大孔小罾，焉能有获？」秀峰曰：「此专为网鳊鱼设也。」见其系以长绠，忽起忽落，似探鱼之有无。末几，急挽出水，已有鳊鱼枷罾孔而起矣。余始喟然曰：「可知一己之见，未可测其奥妙。」一日，见江心中一峰突起，四无依倚。秀峰曰：「此小孤山也。」霜林中，殿阁参差。乘风径过，惜未一游。至滕王阁，犹吾苏府学之尊经阁移于胥门之大码头，王子安序中所云不足信也。即于阁下换高尾昂首船，名「三板子」，由赣关至南安登陆。值馀三十诞辰，秀峰备面为寿。越日过大庾岭，出巅一亭，匾曰「举头日近」，言其高也。山头分为二，两边峭壁，中留一道如石巷。口列两碑，一曰「急流勇退」，一曰「得意不可再往」。山顶有梅将军祠，未考为何朝人。所谓岭上梅花，并无一树，意者以梅将军得名梅岭耶？余所带送礼盆梅，至此将交腊月，已花落而叶黄矣。过岭出口，山川风物便觉顿殊。岭西一山，石窍玲珑，已忘其名，舆夫曰：「中有仙人床榻。」匆匆竟过，以未得游为怅。至南雄，雇老龙船，过佛山镇，见人家墙顶多列盆花，叶如冬青，花如牡丹，有大红、粉白、粉红三种，盖山茶花也。
腊月望，始抵省城，寓靖海门内，赁王姓临街楼屋三椽。秀峰货物皆销与当道，余亦随其开单拜客，即有配礼者络绎取货，不旬日而余物已尽。除夕蚊声如雷。岁朝贺节，有棉袍纱套者。不惟气候迥别，即土著人物，同一五官而神情迥异。
正月既望，有署中园乡三友拉余游河观妓，名曰「打水围」，妓名「老举」。于是同出靖海门，下小艇（如剖分之半蛋而加篷焉），先至沙面。妓船名「花艇」，皆对头分排，中留水巷以通小艇往来。每帮约一二十号，横木绑定，以防海风。两船之间钉以木桩，套以藤圈，以便随潮长落。鸨儿呼为「梳头婆」，头用银丝为架，高约四寸许，空其中而蟠发于外，以长耳挖插一朵花于鬓，身披元青短袄，著元青长裤，管拖脚背，腰束汗巾，或红或绿，赤足撒鞋，式如梨园旦脚。登其艇，即躬身笑迎，搴帏入舱。旁列椅杌，中设大炕，一门通艄后。妇呼有客，即闻履声杂沓而出，有挽髻者，有盘辫者，傅粉如粉墙，搽脂如榴火，或红袄绿裤，或绿袄红裤，有著短袜而撮绣花蝴蝶履者，有赤足而套银脚镯者，或蹲于炕，或倚于门，双瞳闪闪，一言不发。余顾秀峰曰：「此何为者也？」秀峰曰：「目成之后，招之始相就耳。」余试招之，果即欢容至前，袖出槟榔为敬。入口大嚼，涩不可耐，急吐之，以纸擦唇，其吐如血。合艇皆大笑。又至军工厂，妆束亦相等，惟长幼皆能琵琶而已。与之言，对曰「?」，「?」者，「何」也。余曰：「『少不入广』者，以其销魂耳，若此野妆蛮语，谁为动心哉？」一友曰：「潮帮妆束如仙，可往一游。」至其帮，排舟亦如沙面。有著名鸨儿素娘者，妆束如花鼓妇。其粉头衣皆长领，颈套项锁，前发齐眉，后发垂肩，中挽一鬏似丫髻，裹足者著裙，不裹足者短袜，亦著蝴蝶履，长拖裤管，语音可辩。而余终嫌为异服，兴趣索然。秀峰曰：「靖海门对渡有扬帮，留吴妆，君往，必有合意者。」一友曰：「所谓扬帮者，仅一鸨儿，呼曰邵寡妇，携一媳曰大姑，系来自扬州，余皆湖广江西人也。」因至扬帮。对面两排仅十馀艇，其中人物皆云鬟雾鬓，脂粉薄施，阔袖长裙，语音了了，所谓邵寡妇者殷勤相接。遂有一友另唤酒船，大者曰「恒艛」，小者曰「沙姑艇」，作东道相邀，请余择妓。余择一雏年者，身材状貌有类余妇芸娘，而足极尖细，名喜儿。秀峰唤一妓，名翠姑。余皆各有旧交。放艇中流，开怀畅饮。至更许，余恐不能自持，坚欲回寓，而城已下钥久矣。盖海疆之城，日落即闭，余不知也。及终席，有卧吃鸦片烟者，有拥妓而调笑者，使头各送衾枕至，行将连床开铺。余暗询喜儿：「汝本艇可卧否？」对曰：「有寮可居，未知有客否也。」（寮者，船顶之楼。）余曰：「姑往探之。」招小艇渡至邵船，但见合帮灯火相对如长廊，寮适无客。鸨儿笑迎曰：「我知今日贵客来，故留寮以相待也。」余笑曰：「姥真荷叶下仙人哉！」遂有使头移烛相引，由舱后梯而登。宛如斗室，旁一长榻，几案俱备。揭帘再进，即在头舱之顶，床亦旁设，中间方窗嵌以玻璃，不火而光满一室，盖对船之灯光也。衾帐镜奁，颇极华美。喜儿曰：「从台可以望月。」即在梯门之上叠开一窗，蛇行而出，即后梢之顶也。三面皆设短栏，一轮明月，水阔天空。纵横如乱叶浮水者，酒船也；闪烁如繁星列天者，酒船之灯也；更有小艇梳织往来，笙歌弦索之声杂以长潮之沸，令人情为之移。余曰：「『少不入广』，当在斯矣！」惜余妇芸娘不能偕游至此，回顾喜儿，月下依稀相似，因挽之下台，息烛而卧。天将晓，秀峰等已哄然至，余披衣起迎，皆责以昨晚之逃。余曰：「无他，恐公等掀衾揭帐耳！」遂同归寓。
越数日，偕秀峰游海珠寺。寺在水中，围墙若城四周。离水五尺许有洞，设大炮以防海寇，潮长潮落，随水浮沉，不觉炮门之或高或下，亦物理之不可测者。十三洋行在幽兰门之西，结构与洋画同。对渡名花地，花木甚繁，广州卖花处也。余自以为无花不识，至此仅识十之六七，询其名有群芳谱所未载者，或土音之不同钦？海珠寺规模极大，山门内植榕树，大可十馀抱，阴浓如盖，秋冬不凋。柱槛窗栏皆以铁梨木为之。有菩提树，其叶似柿，浸水去皮，肉筋细如蝉翼纱，可裱小册写经。
归途访喜儿于花艇，适翠、喜二妓俱无客。茶罢欲行，挽留再三。余所属意在寮，而其媳大姑已有酒客在上，因谓邵鸨儿曰：「若可同往寓中，则不妨一叙。」邵曰：「可。」秀峰先归，嘱从者整理酒肴。余携翠、喜至寓。正谈笑间，适郡署王懋老不期来，挽之同饮。酒将沾唇，忽闻楼下人声嘈杂，似有上楼之势，盖房东一侄素无赖，知余招妓，故引人图诈耳。秀峰怨曰：「此皆三白一时高兴，不合我亦从之。」余曰：「事已至此，应速思退兵之计，非斗口时也。」懋老曰：「我当先下说之。」余即唤仆速雇两轿，先脱两妓，再图出城之策。闻懋老说之不退，亦不上楼。两轿已备，余仆手足颇捷，令其向前开路，秀峰挽翠姑继之，余挽喜儿于后，一哄而下。秀峰、翠姑得仆力已出门去，喜儿为横手所拿，余急起腿，中其臂，手一松而喜儿脱去，余亦乘势脱身出。余仆犹守于门，以防追抢。急问之曰：「见喜儿否？」仆曰：「翠姑已乘轿去，喜娘但见其出，未见其乘轿也。」余急燃炬，见空轿犹在路旁。急追至靖海门，见秀峰侍翠轿而立，又问之，对曰：「或应投东，而反奔西矣。」急反身，过寓十馀家，闻暗处有唤余者，烛之，喜儿也，遂纳之轿，肩而行。秀峰亦奔至，曰：「幽兰门有水窦可出，已托人贿之启钥，翠姑去矣，喜儿速往！」余曰：「君速回寓退兵，翠、喜交我！」至水窦边，果已启钥，翠先在。余遂左掖喜，右挽翠，折腰鹤步，踉跄出窦。天适微雨，路滑如油，至河干沙面，笙歌正盛。小艇有识翠姑者，招呼登舟。始见喜儿首如飞蓬，钗环俱无有。余曰：「被抢去耶？」喜儿笑曰：「闻此皆赤金，阿母物也，妾于下楼时已除去，藏于囊中。若被抢去，累君赔偿耶。」余闻言，心甚德之，令其重整钗环，勿舍阿母，托言寓所人杂，故仍归舟耳。翠姑如言告母，并曰：「酒菜已饱，备粥可也。」时寮上酒客已去，邵鸨儿命翠亦陪余登寮。见两对绣鞋泥污已透。三人共粥，聊以充饥。剪烛絮谈，始悉翠籍湖南，喜亦豫产，本姓欧阳，父亡母醮，为恶叔所卖。翠姑告以迎新送旧之苦，心不欢必强笑，酒不胜必强饮，身不快必强陪，喉不爽必强歌。更有乖张其性者，稍不合意，即掷酒翻案，大声辱骂，假母不察，反言接待不周，又有恶客彻夜蹂躏，不堪其扰。喜儿年轻初到，母犹惜之。不觉泪随言落。喜儿亦嘿然涕泣。余乃挽喜入怀，抚慰之。瞩翠姑卧于外榻，盖因秀峰交也。
自此或十日或五日，必遣人来招，喜或自放小艇，亲至河干迎接。余每去必邀秀峰，不邀他客，不另放艇。一夕之欢，番银四圆而已。秀峰今翠明红，俗谓之跳槽，甚至一招两妓；余则惟喜儿一人，偶独往，或小酌于平台，或清谈于寮内，不令唱歌，不强多钦，温存体恤，一艇怡然，邻妓皆羡之。有空闲无客者，知余在寮，必来相访。合帮之妓无一不识，每上其艇，呼余声不绝，余亦左顾右盼，应接不暇，此虽挥霍万金所不能致者。余四月在彼处，共费百馀金，得尝荔枝鲜果，亦生平快事。后鸨儿欲索五百金强余纳喜，余患其扰，遂图归计。秀峰迷恋于此，因劝其购一妾，仍由原路返吴。明年，秀峰再往，吾父不准偕游，遂就青浦杨明府之聘。及秀峰归，述及喜儿因余不往，几寻短见。噫！「半年一觉扬帮梦，赢得花船薄幸名」矣！
余自粤东归来，馆青浦两载，无快游可述。未几，芸、憨相遇，物议沸腾，芸以激愤致病。余与程墨安设一书画铺于家门之侧，聊佐汤药之需。
中秋后二日，有吴云客偕毛忆香、王屋灿邀余游西山胁室，余适腕底无闲，嘱其先往。吴曰：「子能出城，明午当在山前水踏桥之来鹤庵相候。」余诺之。
越日，留程守铺，余独步出阊门，至山前过水踏桥，循田塍而西。见一庵南向，门带清流，剥琢问之，应曰：「客何来？」余告之。笑曰：「此『得云』也，客不见匾额乎？『来鹤』已过矣！」余曰：「自桥至此，未见有庵。」其人回指曰：「客不见土墙中森森多竹者，即是也。」余乃返至墙下。小门深闭，门隙窥之，短篱曲径，绿竹猗猗，寂不闻人语声，叩之亦无应者。一人过，曰：「墙穴有石，敲门具也。」余试连击，果有小沙弥出应。余即循径入，过小石桥，向西一折，始见山门，悬黑漆额，粉书「来鹤」二字，后有长跋，不暇细观。入门经韦陀殿，上下光洁，纤尘不染，知为好静室。忽见左廊又一小沙弥奉壶出，余大声呼问，即闻室内星灿笑曰：「何如？我谓三白决不失信也！」旋见云客出迎，曰：「候君早膳，何来之迟？」一僧继其后，向余稽首，问知为竹逸和尚。入其室，仅小屋三椽，额曰「桂轩」，庭中双桂盛开。星灿、忆香群起嚷曰：「来迟罚三杯！」席上荤素精洁，酒则黄白俱备。余问曰：「公等游几处矣？」云客曰：「昨来已晚，今晨仅到得云、河亭耳。」欢饮良久。饭毕，仍自得云、河亭共游八九处，至华山而止。各有佳处，不能尽述。华山之顶有莲花峰，以时欲暮，期以后游。桂花之盛至此为最，就花下饮清茗—瓯，即乘山舆，径回来鹤。
桂轩之东另有临洁小阁，已杯盘罗列。竹逸寡言静坐而好客善饮。始则折桂催花，继则每人一令，二鼓始罢。余曰：「今夜月色甚佳，即此酣卧，未免有负清光，何处得高旷地，一玩月色，庶不虚此良夜也？」竹逸曰：「放鹤亭可登也。」云客曰：「星灿抱得琴来，未闻绝调，到彼一弹何如？」乃偕往．但见木犀香里，一路霜林，月下长空，万籁俱寂。星灿弹梅花三弄，飘飘欲仙。忆香亦兴发，袖出铁笛，呜呜而吹之。云客曰：「今夜石湖看月者，谁能如吾辈之乐裁？」盖吾苏八月十八日石湖行春桥下有看串月胜会，游船排挤，彻夜笙歌，名虽看月，实则挟妓哄饮而已。未几，月落霜寒，兴逋归卧。
明晨，云客谓众曰：「此地有无隐庵，极幽僻，君等有到过者否？」咸对曰：「无论未到，并未尝闻也。」竹逸曰：「无隐四面皆山，其地甚僻，僧不能久居。向年曾一至，已坍废，自尺木彭居士重修后，未尝往焉，今犹依稀识之。如欲往游，请为前导。」忆香曰：「枵腹去耶？」竹逸笑曰：「已备素面矣，再令道人携酒盒相从也。」面毕，步行而往。过高义园，云客欲往白云精舍，入门就坐。一僧徐步出，向云客拱手曰：「违教两月，城中有何新闻？抚军在辕否？」忆香忽起曰：「秃！」拂袖径出。余与星灿忍笑随之，云客、竹逸酬答数语，亦辞出。高义园即范文正公墓，白云精舍在其旁。一轩面壁，上悬藤萝，下凿一潭，广丈许，一泓清碧，有金鳞游泳其中，名曰「钵盂泉」。竹炉茶灶，位置极幽。轩后于万绿丛中，可瞰范园之概。惜衲子俗，不堪久坐耳。是时由上沙村过鸡笼山，即余与鸿干登高处也。风物依然，鸿干已死，不胜今昔之感。正惆怅间，忽流泉阻路不得进，有三、五村童掘菌子于乱草中，探头而笑，似讶多人之至此者。询以无隐路，对曰：「前途水大不可行，请返数步，南有小径，度岭可达。」从其言。度岭南行里许，渐觉竹树丛杂，四山环绕，径满绿茵，已无人迹。竹逸徘徊四顾曰：「似在斯，而径不可辨，奈何？」余乃蹲身细瞩，于千竿竹中隐隐见乱石墙舍，径拨丛竹间，横穿入觅之，始得一门，曰「无隐禅院，某年月日南园老人彭某重修」，众喜曰：「非君则失武陵源矣！」山门紧闭，敲良久，无应者。忽旁开一门，呀然有声，一鹑衣少年出，面有菜色，足无完履，问曰：「客何为者？」竹逸稽首曰：「慕此幽静，特来瞻仰。」少年曰：「如此穷山，僧散无人接待，请觅他游。」言已，闭门欲进。云客急止之，许以启门放游，必当酬谢。少年笑曰：「茶叶俱无，恐慢客耳，岂望酬耶？」山门一启，即见佛面，金光与绿阴相映，庭阶石础苔积如绣，殿后台级如墙，石栏绕之。循台而西，有石形如馒头，高二丈许，细竹环其趾。再西折北，由斜廊蹑级而登，客堂三卷楹紧对大石。石下凿一小月池，清泉一派，荇藻交横。堂东即正殿，殿左西向为僧房厨灶，殿后临峭壁，树杂阴浓，仰不见天。星灿力疲，就池边小憩，余从之。将启盒小酌，忽闻忆香音在树杪，呼曰：「三白速来，此间有妙境！」仰而视之，不见其人，因与星灿循声觅之。由东厢出一小门，折北，有石蹬如梯，约数十级，于竹坞中瞥见一楼。又梯而上，八窗洞然，额曰「飞云阁」。四山抱列如城，缺西南一角，遥见一水浸天，风帆隐隐，即太湖也。倚窗俯视，风动竹梢，如翻麦浪。忆香曰：「何如？」余曰：「此妙境也。」忽又闻云客于楼西呼曰：「忆香速来，此地更有妙境！」因又下楼，折而西，十馀级，忽豁然开朗，平坦如台。度其地，已在殿后峭壁之上，残砖缺础尚存，盖亦昔日之殿基也。周望环山，较阁更畅。忆香对太湖长啸一声，则群山齐应。乃席地开樽，忽愁枵腹，少年欲烹焦饭代茶，随令改茶为粥，邀与同啖。询其何以冷落至此，曰：「四无居邻，夜多暴客，积粮时来强窃，即植蔬果，亦半为樵子所有。此为崇宁寺下院，长厨中月送饭乾一石、盐菜一坛而已。某为彭姓裔，暂居看守，行将归去，不久当无人迹矣。」云客谢以番银一圆。返至来鹤，买舟而归。余绘无隐图一幅，以赠竹逸，志快游也。
是年冬，余为友人作中保所累，家庭失欢，寄居锡山华氏。明年春，将之维扬而短于资，有故人韩春泉在上洋幕府，因往访焉。衣敝履穿，不堪入署，投札约晤于郡庙园亭中。及出见，知余愁苦，慨助十金。园为洋商捐施而成，极为阔大，惜点缀各景，杂乱无章，后叠山石，亦无起伏照应。归途忽思虞山之胜，适有便舟附之。时当春仲，桃李争研，逆旅行踪，苦无伴侣，乃怀青铜三百，信步至虞山书院。墙外仰瞩，见丛树交花，娇红稚绿，傍水依山，极饶幽趣。惜不得其门而入，问途以往，遇设篷瀹茗者，就之，烹碧罗春，饮之极佳。询虞山何处最胜，一游者曰：「从此出西关，近剑门，亦虞山最佳处也，君欲往，请为前导。」余欣然从之。出西门，循山脚，高低约数里，渐见山峰屹立，石作横纹，至则一山中分，两壁凹凸，高数十仞，近而仰视，势将倾堕。其人曰：「相传上有洞府，多仙景，惜无径可登。」余兴发，挽袖卷衣，猿攀而上，直造其巅。所谓洞府者，深仅丈许，上有石罅，洞然见天。俯首下视，腿软欲堕。乃以腹面壁，依藤附蔓而下。其人叹曰：「壮裁！游兴之豪，未见有如君者。」余口渴思饮，邀其人就野店沽饮三杯。阳乌将落，未得遍游，拾赭石十馀块，怀之归寓，负笈搭夜航至苏，仍返锡山。此余愁苦中之快游也。
嘉庆甲子春，痛遭先君之变，行将弃家远遁，友人夏揖山挽留其家。秋八月，邀余同往东海永泰沙勘收花息。沙隶崇明。出刘河口，航海百馀里。新涨初辟，尚无街市。茫茫芦荻，绝少人烟，仅有同业丁氏仓库数十椽，四面掘沟河，筑堤栽柳绕于外。丁字实初，家于崇，为一沙之首户；司会计者姓王。俱家爽好客，不拘礼节，与余乍见即同故交。宰猪为饷，倾瓮为饮。令则拇战，不知诗文；歌则号呶，不讲音律。酒酣，挥工人舞拳相扑为戏。蓄牯牛百馀头，皆露宿堤上。养鹅为号，以防海盗。日则驱鹰犬猎于芦丛沙渚间，所获多飞禽。余亦从之驰逐，倦则卧。引至园田成熟处，每一字号圈筑高堤，以防潮汛。堤中通有水窦，用闸启闭，旱则长潮时启闸灌之，潦则落潮时开闸泄之。佃人皆散处如列星，一呼俱集，称业户曰「产主」，唯唯听命，朴诚可爱。而激之非义，则野横过于狼虎；幸一言公平，率然拜服。风雨晦明，恍同太古。卧床外瞩即睹洪涛，枕畔潮声如鸣金鼓。一夜，忽见数十里外有红灯大如栲栳，浮于海中，又见红光烛天，势同失火，实初日：「此处起现神灯神火，不久又将涨出沙田矣。」揖山兴致素豪，至此益放。余更肆无忌惮，牛背狂歌，沙头醉舞，随其兴之所至，真生平无拘之快游也。事竣，十月始归。
吾苏虎丘之胜，余取后山之千顷云一处，次则剑池而已，馀皆半借人工，且为脂粉所污，已失山林本相。即新起之白公祠、塔影桥，不过留雅名耳。其冶坊滨，余戏改为「野芳滨」，更不过脂乡粉队，徒形其妖冶而已。其在城中最著名之狮子林，虽曰云林手笔，且石质玲珑，中多古木，然以大势观之，竟同乱堆煤渣，积以苔藓，穿以蚁灾，全无山林气势。以余管窥所及，不知其妙。灵岩山，为吴王馆娃宫故址，上有西施洞、响屉廊、采香径诸胜，而其势散漫，旷无收束，不及天平支硎之别饶幽趣。
邓尉山一名元墓，西背太湖，东对锦峰，丹崖翠阁，望如图画，居人种梅为业，花开数十里，一望如积雪，故名「香雪海」。山之左有古柏四树，名之曰「清、奇、古、怪」：清者，一株挺直，茂如翠盖；奇者，卧地三曲，形「之」字；古者，秃顶扁阔，半朽如掌；怪者，体似旋螺，枝干皆然。相传汉以前物也。
乙丑孟春，揖山尊人莼芗先生偕其弟介石，率子侄四人，往襆山家祠春祭，兼扫祖墓，招余同往。顺道先至灵岩山，出虎山桥，由费家河进香雪海观梅。襆山祠宇即藏于香雪海中，时花正盛，咳吐俱香，余曾为介石画襆山风木国十二册。是年九月，余从石琢堂殿撰赴四川重庆府之任，溯长江而上，舟抵皖城。皖山之麓，有元季忠臣余公之墓，墓侧有堂三楹，名曰「大观亭」，面临南湖，背倚潜山。亭在山脊，眺远颇畅。旁有深廊，北窗洞开，时值霜时初红，烂如桃李。同游者为蒋寿朋、蔡子琴。南城外又有王氏园，其地长于东西，短于南北，盖北紧背城、南则临湖故也。既限于地，颇难位置，而观其结构，作重台叠馆之法。重台者，屋上作月台为庭院，叠石栽花于上，使游人不知脚下有屋。盖上叠石者则下实，上庭院者则下虚，故花木仍得地气而生也。叠馆者，楼上作轩，轩上再作平台。上下盘折，重叠四层，且有小池，水不漏泄，竟莫测其何虚何实。其立脚全用砖石为之，承重处仿照西洋立柱法。幸面对南湖，目无所阻，骋怀游览，胜于平园。真人工之奇绝者也。
武昌黄鹤楼在黄鹄矶上，后拖黄鹄山，俗呼为蛇山。楼有三层，画栋飞檐，倚城屹峙，面临汉江，与汉阳晴川阁相对。余与琢堂冒雪登焉，俯视长空，琼花飞舞，遥指银山玉树，恍如身在瑶台。江中往来小艇，纵横掀播，如浪卷残叶，名利之心至此一冷。壁间题咏甚多，不能记忆，但记楹对有云：「何时黄鹤重来，且共倒金樽，浇洲渚千年芳草；但见白云飞去，更谁吹玉笛，落江城五月梅花。」
黄州赤壁在府城汉川门外，屹立江滨，截然如壁。石皆绛色，故名焉。水经谓之赤鼻山，东坡游此作二赋，指为吴魏交兵处，则非也。壁下已成陆地，上有二赋亭。
是年仲冬抵荆州。琢堂得升潼关观察之信，留余祝州，余以未得见蜀中山水为怅。时琢堂入川，而哲嗣敦夫眷属及蔡子琴、席芝堂俱留于荆州，居刘氏废园。余记其厅额曰「紫藤红树山房」。庭阶围以石栏，凿方池一亩；池中建一亭，有石桥通焉；亭后筑土垒石，杂树丛生；馀多旷地，楼阁俱倾颓矣。客中无事，或吟或啸，或出游，或聚谈。岁暮虽资斧不继，而上下雍雍，典衣沽酒，且置锣鼓敲之。每夜必酌，每酌必令。窘则四两烧刀，亦必大施觞政。遇同乡蔡姓者，蔡子琴与叙宗系，乃其族子也，倩其导游名胜。至府学前之曲江楼，昔张九龄为长史时，赋诗其上，朱子亦有诗曰：「相思欲回首，但上曲江楼。」城上又有雄楚搂，五代时高氏所建。规模雄峻，极目可数百里。绕城傍水，尽植垂杨，小舟荡浆往来，颇有画意。荆州府署即关壮缪帅府，仪门内有青石断马槽，相传即赤兔马食槽也。访罗含宅于城西小湖上，不遇。又访宋玉故宅于城北。昔庾信遇侯景之乱，遁归江陵，居宋玉故宅，继改为酒家，今则不可复识矣。
是年大除，雪后极寒，献岁发春，无贺年之扰，日惟燃纸炮、放纸鸢、扎纸灯以为乐。既而风传花信，雨濯春尘，琢堂诸姬携其少女幼子顺川流而下，敦夫乃重整行装，合帮而走。由樊城登陆，直赴潼关。
由山南阌乡县西出函谷关，有「紫气东来」四字，即老子乘青牛所过之地。两山夹道，仅容二马并行。约十里即潼关，左背峭壁，右临黄河，关在山河之间扼喉而起，重楼垒垛，极其雄峻。而车马寂然，人烟亦稀。昌黎诗曰：「日照潼关四扇开」，殆亦言其冷落耶？
城中观察之下，仅一别驾。道署紧靠北城，后有园圃，横长约三亩。东西凿两池，水从西南墙外而入，东流至两池间，支分三道：一向南至大厨房，以供日用；一向东入东池；一向北折西、由石螭口中喷入西池，绕至西北，设闸泄泻，由城脚转北，穿窦而出，直下黄河。日夜环流，殊清人耳。竹树阴浓，仰不见天。西池中有亭，藕花绕左右。东有面南书室三间，庭有葡萄架，下设方石，可弈可饮，以外皆菊畦。西有面东轩屋三间，坐其中可听流水声。轩南有小门可通内室。轩北窗下另凿小池，池之北有小庙，祀花神。园正中筑三层楼一座，紧靠北城，高与城齐，俯视城外即黄河也。河之北，山如屏列，已属山西界。真洋洋大观也！余居园南，屋如舟式，庭有土山，上有小亭，登之可览园中之概，绿阴四合，夏无暑气。琢堂为余颜其斋曰」不系之舟」。此余幕游以来第一好居室也。土山之间，艺菊数十种，惜未及含葩，而琢堂调山左廉访矣。眷属移寓潼川书院，余亦随往院中居焉。
琢堂先赴任，余与子琴、芝堂等无事，辄出游。乘骑至华阴庙。过华封里，即尧时三祝处。庙内多秦槐汉柏，大皆三四抱，有槐中抱柏而生者，柏中抱槐而生者。殿廷古碑甚多，内有陈希夷书「福」、「寿」字。华山之脚有玉泉院，即希夷先生化形骨蜕处。有石洞如斗室，塑先生卧像于石床。其地水净沙明，草多绛色，泉流甚急，修竹绕之。洞外一方亭，额曰「无忧亭」。旁有古树三栋，纹如裂炭，叶似槐而色深，不知其名，土人即呼曰「无忧树」。太华之高不知几千仞，惜未能裹粮往登焉。归途见林柿正黄，就马上摘食之，土人呼止弗听，嚼之涩甚，急吐去，下骑觅泉漱口，始能言，土人大笑。盖柿须摘下煮一沸，始去其涩，余不知也。
十月初，琢堂自山东专人来接眷属，遂出潼关，由河南入鲁。山东济南府城内，西有大明湖，其中有历下亭、水香亭诸胜。夏月柳阴浓处，菡萏香来，载酒泛舟，极有幽趣。余冬日往视，但见衰柳寒烟，一水茫茫而已。趵突泉为济南七十二泉之冠，泉分三眼，从地底怒涌突起，势如腾沸。凡泉皆从上而下，此独从下而上，亦一奇也。池上有楼，供吕祖像，游者多于此品茶焉。明年二月，余就馆莱阳。至丁卯秋，琢堂降官翰林，余亦入都。所谓登州海市，竟无从一见。 ', '本文节选自《浮生六记·卷四·浪游记快》。', '', '', NULL, '', 'indent', 1478217461, '57ea0e6ea3413100624e8395', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10235, '盘铭', NULL, 243, 1, 1, 1, '商汤', NULL, 10062, '57b902865bbb50005b783351', '商', 'wen', '文', 'http://baike.baidu.com/view/4754129.htm', '', '苟日新，日日新，又日新。', '此文选自中国儒家经典《大学》，相传为商汤王刻在澡盆上的箴言，展示了一种革新的姿态，鞭策自己弃旧图新。', '汤：即成汤，商朝的开国君主。盘铭是刻在器皿上警醒自己的箴言。
盘：这里指商汤的洗澡用具。', '', NULL, '', 'center', 1478213045, '57b901b58ac2470062df9cdc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (33783, '越调 · 凭阑人 · 题曹云西翁赠妓小画', NULL, 10, 169, 1, 1, '邵亨贞', NULL, 10917, '5858e5f461ff4b006875be34', '元', 'qu', '曲', '', '', '谁写江南一段秋，妆点钱塘苏小楼？楼中多少愁，楚山无断头。', '', '', '', NULL, '', 'indent', 1536335894, '585cdda4b123db0065a5a814', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (57154, '天仙子 · 寿杜左丞', NULL, 0, 58, 0, 1, '程文海', NULL, 11336, '5858e657b123db00658d7ce3', '元', 'ci', '词', NULL, NULL, '一自寿仙临杜曲。岁岁小春春意熟。泰阶相向更分明，调玉烛。扶钧轴。突兀眼前惟此屋。
折得岁寒枝上玉。拟祝翠尊还觉俗。何如绣彩在庭前，看未足。杯方续。周鲁后先光汗竹。', NULL, NULL, NULL, NULL, NULL, 'indent', 1533229501, '585cf566ac502e00672155a9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10236, '归程小记', NULL, 155, 137, 2, 0, '归有光', NULL, 10004, '57b940198ac2470062e1af28', '明', 'wen', '文', '', '', '予每北上，常翛然独往来，一与人同，未免屈意以循之，殊非其性，杜子美诗：眼前无俗物，多病也身轻。子美真可语也。昨自瓜洲渡江，四顾无人，独览江山之胜，殊为快意。过浒墅，风雨萧飒如高秋，西山屏列，远近掩映，凭栏眺望，亦是奇游，山不必陟乃佳也。', '', '翛（xiāo）：无拘无束、自由自在的样子。
陟（zhì）：登高。', '我每次北上，常常无拘无束，自由自在，独自往来，一旦与人同行，未免就要屈意顺随他人，这样做很违背我的本性，唐朝杜子美有诗云：眼前无俗物，多病也身轻。子美先生真正是可以交谈的人啊。昨天，我从瓜洲渡长江，四处无人，独自欣赏江山胜景，心情非常舒畅。过浒墅关，风雨萧飒，仿佛到了深秋季节，西山像一座花屏摆放，远近风景，互相交映，原来凭栏远望，也是一种奇异绝佳的旅游，而不一定要亲身去攀登它。', NULL, '', 'indent', 1362773274, '57b940942e958a005fa77518', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10237, '寒花葬志', NULL, 30, 137, 1, 1, '归有光', NULL, 10004, '57b940198ac2470062e1af28', '明', 'wen', '文', 'http://baike.baidu.com/view/914386.htm', '', '婢，魏孺人媵也。嘉靖丁酉五月四日死，葬虚丘。事我而不卒，命也夫！
婢初媵时，年十岁，垂双鬟，曳深绿布裳。一日，天寒，爇火煮荸荠熟，婢削之盈瓯；余入自外，取食之；婢持去，不与。魏孺人笑之。孺人每令婢倚几旁饭，即饭，目眶冉冉动。孺人又指予以为笑。
回思是时，奄忽便已十年。吁！可悲也已！', '《寒花葬志》是明代文学家归有光的一篇散文。当时，作者的妻子魏孺人已经离开人世，而魏氏的陪侍丫环寒花也过早去世。文中通过追忆寒花的生前经历，表达了作者对妻子深切的思念之情。
归有光少年丧母，两次丧妻，儿女或早夭，或长成之际猝然离世，使他在人生中体味到了太多的无奈与悲凉，所以他有时候会对千百年来为人们深信不疑的“天命”产生怀疑，对天发出痛切悲怆的呼号。但更多时候，作为深受儒家传统思想影响的正统文人，他把这种种对人世的不公的愤恨与无奈化为了一种哀而不伤的淡淡笔触，向人们娓娓道来。如《寒花葬志》，便是明写寒花，暗写魏孺人。这种看似一带而过的闲笔与淡笔，正是归有光散文突出的特点。这种写法，表面上容易被人忽略，但在这种刻意的淡化与压抑之中，包含了作者深挚沉痛的情感和细腻丰富的心灵。', '寒花：婢女的名字。
魏孺人：作者的妻子魏氏。孺人，明清七品官的母亲或妻子的封号。
媵（yìng）：古代随嫁的男女都称为媵。这里指古代贵族随嫁的女子。
嘉靖丁酉：嘉庆十六年（公元1537年）。嘉靖，明世宗朱厚熜年号（公元1522年—公元1566年）。
虚丘：古虚丘邑在今山东省境内。这里的“虚丘”可能应为“丘虚”，指荒地。
媵：陪嫁的人。
鬟：妇女梳的环形的发髻。
曳：拖着，这里是拉的意思。
爇（ruò）：点火、点燃。
荸荠：多年生草本植物，可以吃。
盈瓯：装满一盤，。
饭：吃饭。
冉冉：形容缓慢移动或飘忽迷离。
奄忽（yǎnhū）：忽然，很快的。', '寒花是魏孺人的陪嫁的丫鬟。在嘉靖的丁酉年的五月四日死的，葬在虚丘。侍奉我而不能到最后，这是命运啊！
寒花刚陪嫁过来的时候，才十岁，低垂着两个环形发髻，拖着深绿色的裙子。有一天，天很寒冷，她点火煮熟了荸荠，削了皮盈满瓦盆。我从外面回来，要取荸荠来吃，她端着荸荠离开，不给我吃。妻子魏孺人见了便笑这件事。妻子常常让她靠在桌子旁边吃饭，她吃饭时，眼睛慢慢地转动。妻子又指着她那样子对着我笑。
回想当时的情景，转眼已经十年了。唉，真可悲呀！', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed204911759740c9bdcf3", "shortContent": "《寒花葬志》是归有光叙事抒情散文的名篇之一。寒花，为作者婢女的名字；葬志，是为死者写的记事文章。题旨所示，在于悼念亡故之人。全文仅一百多字，简洁凝练，一往情深。\n首节，开头三句就点明了寒花身分、死去时日和安葬处所。言身分：“魏孺人媵也”。寒花不是一般婢女，而是作者所挚爱的前妻的随嫁婢女。言死日：“嘉靖丁酉五月四日死”。寒花时年仅十九岁，距魏孺人之死已四年。言葬地：“葬虚丘”。寒花虽为婢女，仍择地郑...", "authors": ["刘立人"], "pressName": "上海辞书出版社"}]', '明·黄宗羲：予读震川之为女妇者，一往情深，每以一二细事见之，使人欲涕。盖古往今来事无巨细，唯此可歌可泣精神，长留天垠。
明·王锡爵：其文无意于感人，而欢愉惨恻之思，溢于语言之外。
清·胡怀琛：能将婢女神态曲折描写出来，着墨不多，而神采生动，此是震川擅长文字，所谓于太史公所深会处也。
清·王文濡：涉笔成趣。', 'indent', 1415640592, '57b98875a633bd00619f453b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10240, '秋灯琐忆', NULL, 64, 6, 1, 2, '蒋坦', NULL, 10046, '57bb21ff0a2b58006cbb47e7', '清', 'wen', '文', 'http://baike.baidu.com/view/2093924.htm', '', '道光癸卯闰秋，秋芙来归。漏三下，臧获皆寝。秋芙绾堕马髻，衣红绡之衣，灯花影中，欢笑弥畅，历言小年嬉戏之事。渐及诗词，余苦水舌挢不能下，因忆昔年有传闻其《初冬诗》云「雪压层檐重，风欺半臂单」，余初疑为阿翘假托，至是始信。于时桂帐虫飞，倦不成寐。盆中素馨，香气滃然，流袭枕簟。秋芙请联句，以观余才，余亦欲试秋芙之诗，遂欣然诺之。余首赋云：「翠被鸳鸯夜，」秋芙续云：「红云织蟔楼。花迎纱幔月，」余次续云：「入觉枕函秋。」犹欲再续，而檐月暧斜，邻钟徐动，户外小鬟已啁啁来促晓妆矣。余乃阁笔而起。
数曰不入巢园，阴廊之间，渐有苔色，因感赋二绝云：「一觉红蕤梦，朝记记不真。昨宵风露重，忆否忍寒人？」「镜槛无人拂，房栊久不开。欲言相忆处，户下有青苔。」时秋芙归宁三十五曰矣。群季青绫，兴应不浅，亦忆夜深有人，尚徘徊风露下否？
秋芙之琴，半出余授。入秋以来，因病废辍。既起，指法渐疏，强为理习，乃与弹于夕阳红半楼上。调弦既久，高不成音，再调则当五徽而绝。秋芙索上新弦，忽烟雾迷空，窗纸欲黑。下楼视之，知雏鬟不戒，火延幔帷。童仆扑之始灭。乃知猝断之弦，其谶不远，况五，火数也，应徽而绝，琴其语我乎？
秋芙以金盆捣戎葵叶汁，杂于云母之粉，用纸拖染，其色蔚绿，虽澄心之制，无以过之。曾为余录《西湖百咏》，惜为郭季虎携去。季虎为余题《秋林著书图》云：「诗成不用苔笺写，笑索兰闺手细钞」，即指此也。秋芙曏不工书，自游魏滋伯，吴黟山两丈之门，始学为晋唐格。惜病后目力较差，不能常事笔墨。然间作数字，犹是秀媚可人。
夏夜苦热，秋芙约游理安。甫出门，雷声殷殷，狂飙疾作。仆夫请回车，余以游兴方炽，强趣之行。永及南屏，而黑云四垂，山川瞑合。俄见白光如练，出独秀峰顶，经天丈馀，雨下如注，乃止大松树下。雨霁更行，觉竹风骚骚，万翠浓滴，两山如残妆美人，蹙黛垂眉，秀色可餐。余与秋芙且观且行，不知衣袂之既湿也。时月查开士主讲理安寺席，留饭伊蒲，并以所绘白莲画帧见贻。秋芙题诗其上，有「空到色香何有相，若离文字岂能禅」之句。茶话既洽，复由杨梅坞至石屋洞，洞中乱石排拱，几察俨然。秋芙安琴磐磴，鼓《平沙落雁》之操，归云滃然，涧水互答，此时相对，几忘我两人犹生尘世间也。俄而残暑渐收，暝烟四起，回车里许，已月上苏堤杨柳梢矣。是日，屋漏床前，窗户皆湿，童仆以重门锁扃，未获入视。俟归，已蝶帐蚊橱，半为泽国，呼小婢以筠笼熨之，五鼓始睡。
秋芙喜绘牡丹，而下笔颇自矜重。嗣从老友杨渚白游，活色生香，遂入南田之室。时同人中寓余草堂及晨夕过从者，有钱文涛、费子苕，严文樵、焦仲梅诸人，品叶评花，弥日不倦。既而钱去杨死，焦严诸人各归故乡。秋芙亦以盐米事烦，弃置笔墨。惟余纨扇一枚，犹为诸人合画之笔，精神意态，不减当年，暇日观之，不胜宾朋零落之感。
桃花为风雨所摧，零落池上，秋芙拾花瓣砌字，作《谒金门》词云：「春过半，花命也如春短。一夜落红吹渐漫，风狂春不管。」「春」字未成，而东风骤来，飘散满地，秋芙怅然。余日，「此真个‘风狂春不管’矣！」相与一笑而罢。
余旧蓄一绿鹦鹉，字日「翠娘」，呼之辄应。所诵诗句，曏为侍儿秀绢所教。秀绢既嫁，翠娘饮啄常失时，日渐憔悴。一日，余起盥沐，闻帘外作细语声，恍如秀娟声吻，惊起视之，则翠娘也。杨枝去数月矣，翠娘有知，亦忆教诗人否？
秋芙每谓余云：「人生百年，梦寐居半，愁病居半，襁褓垂老之日又居半，所仅存者，十之一二耳，况我辈蒲柳之质，犹未必百年者乎！庾兰成云：一月欢娱，得四五六日。想亦自解语耳。」斯言信然。
平生未作百里游。甲辰娥江之役，秋芙方病寒疾，欲更行期。而行装既发，黄头促我矣。晚渡钱江，飓风大作，隔岸越山，皆低鬟敛眉，郁郁作相对状，因忆子安《滕王阁序》云：「天高地迥，觉宇宙之无穷，兴尽悲来，识盈虚之有数。」殊觉此身茫茫，不知当置何所。明河在天，残灯荧荧，酒醒已五更时矣。欲呼添衣，而罗帐垂垂，四无人应，开眼视之，始知此身犹卧舟中也。
秋月正佳，秋芙命雏鬟负琴，放舟两湖荷芰之间。时余自西溪归，及门，秋芙先出，因买瓜皮迹之，相遇于苏堤第二桥下。秋芙方鼓琴作《汉宫秋怨》曲，余为披襟而听。斯时四山沉烟，星月在水，琤瑽杂鸣，不知天风声环佩声也。琴声末终，船唇已移近漪园甫岸矣。固叩白云庵门。庵尼故相识也，坐次，采池中新莲，制羹以进。香色清冽，足沁肠睹，其视世味腥膻，何止薰莸之别。回船至段家桥登岸，施竹簟于地，坐话良久。闻城中尘嚣声，如蝇营营，殊聒人耳。桥上石柱，为去年题诗处，近为嫔衣剥蚀，无复字迹。欲重书之，苦无中书。其时星斗渐稀，湖气横白，听城头更鼓，已沉沉第四通矣，遂携琴刺船而去。
余莲村来游武林，以惠山泉一瓮见饷。适墨颠开士主讲天日山席，亦寄头纲茶来。竹炉烹饮，不啻如来滴水，遍润八万四千毛孔，初不待卢同七碗也。莲村止余草堂十有馀日，剪烛论文，有逾胶漆。惜言欢未终，饥为驱去。树云相望，三年于兹矣。常忆其论吴门诸子诗，极称觉阿开士为闻见第一。觉阿以名秀才剃落佛前，磨砖十年，得正法眼藏。所居种梅三百馀本，香雪满时，跌坐其下，禅定既起，间事吟咏。有《咏怀诗》云：「自从一见楞严后，不读人间糠粕书。」昔简斋老人论《华严经》云：「文义如一桶水，倒来倒去。」不特不解《华严》，直是未见《华严》语。以视觉阿，伺止上下床之别耶！惜未见全诗，不胜半偈之憾。闻莲村近客毗陵，暇日当修书问之。
夜来闻风雨声，枕簟渐有凉意。秋芙方卸晚妆，余坐案傍。制《百花图记》未半，闻黄叶数声，吹堕窗下。秋芙顾镜吟曰：「昨日胜今日，今年老去年。」余怃然云：「生年不满百，安能为他人拭涕！」辄为掷笔。夜深，秋芙思饮，瓦铞温暾，已无馀火，欲呼小鬟，皆蒙头户间，为趾离召去久矣。余分案上灯置茶灶间，温莲子汤一瓯饮之。秋芙病肺十年，深秋咳嗽，必高枕始得熟睡。今年体力较强，拥髻相对，常至夜分，殆眠餐调摄之功欤？然入秋犹未数日，未知八九月间更复何如耳。
余为秋芙制梅花画衣，香雪满身，望之如绿萼仙人，翩然尘世。每当春暮，翠袖凭栏，鬓边蝴蝶，犹栩栩然不知东风之既去也。扫地焚香，喻佛法耳，谓如此即可成佛，则值寺阍黎，已充满极乐国矣。秋芙性爱洁，地有纤尘，必亲事箕帚。余为举王栖云偈云：「日日扫地上，越扫越不净。若要地上净，撇却苕帚柄。」秋芙卒不能悟。秋芙辨才十倍于我，执于斯者，良亦积习使然。
余居湖上十年，大人月给数十金，资余盐米。余以挥霍，每至匮乏，夏葛冬裘，递质递赎，敝箧中终岁常空空也。曾赋诗示秋芙云：「一寒至此怜张禄，再拥无由惜谢耽。箧为频搜卿有意，裈犹可挂我何惭。」纪实也。
丁未冬，伊少沂大令课最北行，余饯之草堂，来会者二十馀人。酒次，李山樵鼓琴，吴康甫作擘窠书，吴乙杉、杨渚白、钱文涛分画四壁，余或拈韵赋诗，清谈瀹茗。惟施庭午、田望南、家宾梅十馀人，踞地赌霸王拳，狂饮疾呼，酒尽数十觥不止。是夕，风月正佳，余留诸人为长夜饮。羊灯既上，洗盏更酌，未及数巡，而呼酒不至。讶询秋芙，答云：「瓶罍罄矣。床头惟馀数十钱，余脱玉钏换酒，酒家不辨真赝，今付质库，去市远，故未至耳。」余为诵元九「泥他沽酒拔金钗」诗，相对怅然。是集得诗数十篇，酒尽八九瓮，数年来文酒之乐，于斯为盛。自此而后，踪迹天涯，云萍聚散，馀与秋芙亦以尘事相羁，不能屡为山泽游矣。
秋芙素不工词，忆初作《菩萨蛮》云：「莫道铁为肠，铁肠今也伤。」造意尖新，无板滞之病。其后馀游山阴，秋芙制《洞仙歌》见寄，气息深稳，绝无疵颠，余始讶其进境之速。归后索览近作，居然可观，乃知三日之别，固非昔日阿蒙矣。昔瑶花仙史降乩巢团，目秋芙为昙阳后身，观其辨才，似亦可信。加以长斋二十年，《楞严》《法华》熟诵数千卷，定而生蕙，一指半偈，犹能言下了悟，况区区文字间乎！昔人谓「书到今生读已迟」，余于秋芙信之矣。
秦亭山西去二十里，地名西溪，余家槐眉庄在焉。缘溪而西，地多芦苇，秋风起时，晴雪满滩，水波弥漫，上下一色。芦花深处，置精蓝数椽，以奉瞿昙，曰「云章阁」。阁去庄里馀，复涧回溪，非苇杭不能到也。时有佛缘僧者，居华坞∴斋，相传戒律精严，知未来之事。乙巳秋，余因携秋芙访之，叩以面壁宗旨，如聩如聋，鼻孔撩天，曷胜失笑。时残雪方晴，堂下绿梅，如尘梦初醒，玉齿粲然。秋芙约为永兴寺游，遂与登二雪堂，观汪夫人方佩书刻。还坐溪上，寻炙背鱼、剪尾螺，皆颠师胜迹。明日更游交芦，秋雪诸刹，寺僧以松萝茶进，并索题《交芦雅集图卷》。回船已夕阳在山，晚钟催饭矣。霜风乍寒，溪上澄波粼粼，作皱縠纹。秋芙时著薄棉，有寒色，余脱半臂拥之。夜半至庄，吠尨迎门，回里隔溪渔火，不减鹿门晚归时也。秋芙强余作游记诗，遂与挑灯命笔，不觉至曙。
秋芙有停琴伫月小彰，悬之寝室，日以沉水供之。将归，戏谓余曰：「夜窗孤寂，留以伴君，君当酬以瓣香。无扃置空房，令娥眉有秋风团扇悲也。」
晓过妇家。窗栊犹闭，微闻仓琅一声，似鸾篦堕地，重帘之中，有人晓妆初就也。时初日在梁，影照窗户，盘盘腻云，光足鉴物，因忆微之诗云：「水晶帘底看梳头」，古人当日，已先我消受眼福。
关、蒋故中表亲。余未聘时，秋芙来余家，绕床弄梅，两无嫌猜。丁亥元夕，秋芙来贺岁，见于堂前。秋芙衣葵绿衣，余着银红绣袍，肩随额齐，钗帽相傍。张情齐丈方居巢园，谓大人曰：「俨然佳儿佳妇。」大人遂有丝罗之意。后数月，巢园鼠姑作花，大人招亲朋，置酒花下。秋芙随严君来。酒次，秋芙收筵上果脯，藏帕中。余夺之，秋芙曰：「余将携归，不汝食也。」余戏解所系巾，曰：「以此缚汝，看汝得归去否？」秋芙惊泣，乳妪携去始解。大人顾之而笑。固倩俞霞轩师为之蹇修，筵上聘定。自后数年，绝不相见。大人以关氏世有姻娅，岁时仍率余往趋谒，故关氏之庭，迹虽疏，未尝绝也。忆壬辰新岁，余往，入门见青衣小鬟，拥一粲姝上车而去。俄闻屏间笑声，乃知出者即为秋芙。又一年，圃桥试近，妻父集同人会文，意在察婿。置酒后堂，余列末座。闻湘帘之中，环玉相触，未知有秋关在否。又一年，余行市间，忽车雷声中，帘□疾卷，中有丽人，相注作熟视状。最后一车，似是妻母，意卷帘人即膝前娇女也。又一年，余举弟子员，大人命余晋谒。庭遇秋芙，戴貂茸，立蜜梅花下。俄闻银钩一声，无复鸿影。余自聘及迎，相去凡十五年，五经邂逅，及却扇筵前，剪灯相见，始知颊上双涡，非复旧时丰满矣。今去结缡又复十载，余与秋芙皆鬓有霜色，未知数年而后，更作何状？忽忽前尘，如梦如醉，质之秋芙，亦忆一二否？
秋芙谓「元九《长庆集》诗，如土饭尘羹，食者不知有味。惟《悼亡》三诗，字字泪痕，不堕浮艳之习。」余日：「未必不似宋考功于刘希夷事耳。不然，微之轻薄小人，安能为此刻骨语？」
余读《述异记》云「龙眠于渊，颔下之珠，为虞人所得，龙觉而死」，不胜叹息。秋芙从旁语曰：「此龙之罪也。颔下有珠，则宜知宝。既不能宝而为人得，则唏嘘云雨，与虞人相持江湖之间，珠可还也。而以身殉之，龙则逝矣，而使珠落人手，永无还日，龙岂爱珠者哉？」余默然良久，曰：「不意秋芙亦能作议论，大奇。」
葛林园为招贤寺遗址，有水榭数楹，俯瞰竹石。榭下有池，矩□横架其上。池偏凌霄花一本，藤蔓蜿蜒，相传为唐宋时物，诗僧半颠及其师破林，驻锡于此数十年矣。己酉初夏，积潦成灾，余所居草堂，巳为泽国。半颠以书相招，遂与秋芙往借居焉。是时，城市可以行舟，所交宾朋，无歹中隔。日与半颠谈禅，间以觞咏，悠悠忽忽，不知人间有岁月矣。闻岳坟卖馂馅馒首，日使赤脚婢数钱买之。瞰食既饱，分饲池鱼。秋芙起拊栏楯，误堕翠簪，水花数圈，杳不能迹，惟簪上所插素馨，漂浮波上而已。池偏为梁氏墓庐，庐西有门，久鞠茂草。庐居梁氏族子数人，出入每由寺中。梁有劣弟，贫乏不材。余居月惊，阅墙之声，未歇于耳。一日，余行池上，闻剥啄声。寺僧方散午斋，余为启扉。有毡笠布衣者，问梁某在否，余为指示。其人入粱氏庐，余亦闭门。半颠知之，因见梁，问来者云何，梁曰：「无之。」相与遍索室中，不得。惟东偏小楼，扃闭甚固，破窗而入，其弟已缢死床上矣，乃知叩门者缢死鬼耳！自后鬼语啾啾，夜必达旦，梁以心恇迁去。余与秋芙虽恃《楞严》卫护之力，而阴霾逼人，究难长处。时水潦已退，旋亦移归草堂，嗣闻半颠飞锡南屏。余不过此寺又数年矣，未知近日楼中，尚复有人居住否？
枕上不寐，与秋芙论古今人材，至韩擒虎。余曰：「擒虎生为上柱国，死不失为阎罗王，亦侥幸甚矣。」秋英笑曰：「特张嫦娥诸人之冤，无可控告，奈何？」
大人晚年多疴，余与秋芙结坛修玉皇忏仪四十九日。秋芙作骈俪疏文，辞义奥艳，惜稿无遗存，不可记忆。维时霜风正秋，瓶中黄菊，渐有佳色。夜深钟磐一鸣，万籁皆伏。沈烟笼罩中，恍觉上清官阙，即现眼前，不知身在人世间也。
秋芙所种芭蕉，已叶大成阴，荫蔽帘□。秋来雨风滴沥，枕上闻之，心与俱碎。一日，余戏题断句叶上云：「是谁多事种芭蕉，早也潇潇，晚也潇潇。」明日见叶上续书数行云：「是君心绪太无聊，种了芭蕉，又怨芭蕉。」字画柔媚，此秋芙戏笔也，然余于此，悟入正复不浅。
春夜扶鸾，瑶花仙史降坛，赋《双红豆》词云：「风丝丝，雨丝丝，谁使花粘蛛网丝？春光留一丝。烟丝丝，柳丝丝，依与红蚕同有丝。蚕丝依鬓丝。」又《贺新凉》赠秋芙云：「久未城西过。料如今、夕阳楼畔，芭蕉新大。日日东风吹暮雨，闻道病愁无那。况几日妆台梳裹。纸薄衫儿寒易中，算相宜还是摊衾卧。切莫向，夜深坐。西池已谢桃花朵。恁青鸾、天天来去，书儿无个。一卷楞严应读遍，能否情惮参破？问归计甚时才可？双凤归来星月下，好细斟元碧相称贺。须预报，玉楼我。」甲辰岁，仙史曾降笔草堂，指示金丹还返之道，故有「久未西城过」之语。
忆戊申秋日，寄秋芙七古—首，诗云：「乾萤冷贴屏风死，秋逼兰釭落花紫。满床风雨不成眠，有人剪烛中霄起。风雨秋凉玉簟知，镜台钗股最相思。伤心独忆闺中妇，应是残灯拥髻时。髻影飘萧同卧病，中间两接红鲂信。病热曾云甘蔗良，心忪或藉浮瓜镇。夜半传闻还织素，锦诗渐满回文数。可怜玉臂岂禁寒，连波只悔从前错。从前听雨芙蓉室，同衾忆汝初来日。才见何郎卺合双，便疑司马心非一。鸿庑牛衣感最深，春衣典后况无金。六年费汝金钗力，买得萧郎薄幸心。薄幸明知难自避，脱舆未免参人议。或有珠期浦口还，何曾剑忍微时弃。端赖鸳鸯壶内语，疏狂尚为鲰生恕。无端乞我卖薪钱，明朝便决归宁去。去日青荷初卷叶，罗衣曾记箱中叠。一年容易到秋风，渡江又阻归来楫。我似齐纨易弃捐，怀中冷暖仗人怜。名争蜗角难言胜，命比蚕□岂久坚。莫为机丝曾有故，蛾眉何人能持护？门前但看合欢花，也须各有归根树。树犹如此我何堪，近信无由绮阁探。拥到兰衾应忆我，半窗残梦雨声参。雨声入夜生惆怅，两家红烛昏罗帐。一例悲欢各自听，楚魂来去芭蕉上。芭蕉叶大近窗楹，枕上秋天不肯明。明日谢家堂下过，入门预想绣鞋声。」此稿遗佚十年，枕上忽忆及之，命笔重书，恍惚如梦。
晚来闻络纬声，觉胸中大有秋气。忽忆宋玉悲秋《九辩》，击枕而读。秋芙更衣阁中，良久不出。闻唤始来，眉间有秋色。余问其故，秋芙曰：「悲莫悲兮生别离，何可使我闻之？」余慰之曰：「因缘离合，不可定论。余与子久皈觉王，誓无他趣。他日九莲台上，当不更结离恨缘，何作此无益之悲也？昔锻金师以一念之誓，结婚姻九十馀劫，况余与子乎？」秋芙唯唯，然颊上粉痕，已为泪花污湿矣。余亦不复卒读。
秋芙藏有书尺，为吴黟山所贻。尺长尺馀，阔二寸许。相传乾隆壬子，泰山汉柏出火自焚，钱塘高迈庵拾其烬馀，以为书尺，刻铭于上。铭云：「汉已往，柏有神。坚多节，含古春。劫灰未烬兮，芸编是亲。然藜痹徽兮，焦桐共珍。」
开户见月，霜天悄然，固忆去年今夕，与秋芙探梅巢居阁下，斜月暧空，远水渺口，上下千里，一碧无际，相与登补梅亭，瀹茗夜谈，意兴弥逸。秋芙方戴梅花鬓翘，虬枝在檐，遽为攫去，余为摘枝上花朴之。今亭且倾圮，花木荒落，惟口娥有情，尚往来孤山林麓间耳。
秋芙好棋，而不甚精，每夕必强余手谈，或至达旦。余戏举竹坨同云：「簸钱斗草已都输，问持底今宵偿我？」秋芙故饰词云：「君以我不能胜耶？请以所佩玉虎为赌。」下数十子，棋局惭输，秋芙纵膝上口儿搅乱棋势。余笑云：「子以玉奴自况欤？」秋芙嘿然。而银烛荧荧，已照见桃花上颊矣。自此更不复棋。
去年燕来较迟，帘外桃花，已零落殆半。夜深巢泥忽倾，堕雏于地。秋芙惧为口儿所攫，急收取之，且为钉竹片于梁，以承其巢。今年燕子复来，故巢犹在，绕屋呢喃，殆犹忆去年护雏人耶？
同里沉湘涛夫人与秋芙友善，赠以所著诗词属为删校。中有句云：「却喜近来归佛后，清才渐觉不如前。」因忆前见朱莲卿诗，有「却喜今年身稍健，相逢常得笑颜生」之句，两「喜」字用法不同，各极沉痛。莲卿近得消渴疾，两月未起，霜风在林，未知寒衣曾检点否？
斜月到窗，忽作无数个「人」字，知堂下修篁解箨矣。忆居槐眉庄，庄前种竹数弓。笋泥初出，秋芙命秀娟携鸦嘴锄，口数筐，煮以盐菜，香味甘美，初不让廷秀煮笋经也。秀娟嫁数年，如林中绿衣人得锦绷儿矣。惟余老守谷中，鬓颜非故，此君有知，得无笑人？
虎跑泉上有术樨数株，偃伏石上，花时黄雪满阶，如游天香国中，足怡鼻观。余负花癖，与秋芙常煮茗其下。秋芙攒花簪鬓，额上发为树枝捎乱，余为蘸泉水掠之。临去折花数枝，插车背上，携入城口，欲人知新秋消息也。近闻寺憎添植数本，金粟世界，定更为如来增色矣。秋风匪遥，早晚应有花信，花神有灵，亦忆去年看花人否？
宾梅宿予草堂，漏三下，闻邻人失火，急率仆从救之。及门，已扑灭矣。惟闻空中语云：「今日非有力人居此，此境几为焦土。」言顷，有二道入与一比丘自天而下。道人戴藕华冠，衣蟠龙口口之袍。其一玉貌长髯，所衣所冠皆黄金色。比丘踵道人之后，若木若讷。藕冠者曰：「吾名证若，居青城赤水之间，访蒋居士至此。」与长须道人拂尘而歌，歌长数千言，未暇悉记。惟记其末句云：「只回来巧递了云英密信，那裴航痴了心，何时得醒？若不早回头，累我飞升。醒，醒，醒，明日阴晴难信。」歌竟而逝。趋视之，则星月在户，残灯不明，惟闻落叶数声，蘧然一梦觉也。既旦，告予，予曰：「余家断杀数十年，而修鸿宝之道六七载，至今黄口飞腾，犹少返还之诀。岂仙师垂悯凡愚，现身说法欤？歌中曰「云英」，云英者，岂以余闺房之缘，未解缠缚，而讽咏示警欤？时予与秋芙修陀罗尼忏数月矣，所谓比丘者，岂观音化身，寻声自西竺来欤？
秋芙病，居母家六十馀日。臧获陪侍，多至疲惫。其昼夜不辍者，仅余与妻妹侣琼耳。余或告归，侣琼以身代予，事必手亲，故药炉病榻之间，予得赖以息肩。侣琼固情笃友于，然当此患难之时，而荼苦能甘，亦不自觉伺以至是也。秋芙生负情癖，病中尤为缠缚。余归，必趣人召余，比至，仍无一语。侣琼问之，秋芙曰：「余命如悬丝，自分难续，仓猝恐无以与诀，彼来，余可撒手行耳。」余闻是言，始觉腹痛，继思秋芙念佛二十年，誓赴金台之迎，观此一念，恐异日轮堕人天，秋芙犹未能免。手中梧桐花，放下正自不易耳。
秋夜正长，与妻妹佩琪围棋，三战三北，自念平生此技未肯让人，佩琪年未及笄，所造如此，殆天授耶？佩琪性静默，有林下风，字与诗篇，靡不精晓，自言前身自上清官来。观其神寒骨清，洵非世间烟火人也。今不与对局数年矣，布算之神，应更倍昔。他日谢家堂上，当效楚子反整师复战，期雪曩年城下之耻。
踏月夜归，秋芙方灯下呼卢。座中有人一掷得六么色，余戏为《卜算子》词云：「妆阁夜呼卢，钗影阑干背。六个骰儿六个窝，到底都成对。借问阿谁赢，莫是青溪妹？赚得回头一顾无，试报说金钮坠。」秋芙见面笑曰：「如此绮语，不虑方子鞭背耶？」
近作小词，有句云：「不是绣衾孤，新来梦也无。」又《买陂塘》后半云：「中门掩，更念荀郎忧困，王瓯莲子亲进。无端别了秦楼去，食性伺人猜准。闲抚鬓。看半载相思，又及三春尽。前期未稳。怕再到兰房，剪灯私语，做梦也无分。」时宾梅以纨扇属书，团戏录之。宾梅见而笑曰：「做梦何以无分？」秋芙笑云：「想新来梦也无耳。」相与绝倒。
甲辰秋，同入招游月湖。夜深为风露所欺。明日复集吴山笙鹤楼，中酒禁寒。归而病热几殆，赖乩示方药，始获再生。越一年，为丙午岁，疽发背间，旋复病疟。方届秋试，扶病登车，未及试院，而魂三逝矣。仆从舁归，匝月始安。已酉之夏，复病疮痢，俯枕三月，痛甚剥肤。六年之间，三堕病劫，秋芙每侍余疾，衣不解带。柔脆之质，岂禁劳瘁，故余三病，而秋芙亦三病也。余生有懒疾，自己酉奉讳以来，火死灰寒，无复出山之想。惟念亲亡未葬，弟长未婚，为生平未了事。然先人生圹久营，所需卜吉。增弟年二十矣，兔郭数顷田，足可耕食。数年而后，当与秋芙结庐华坞河渚间，夕梵晨钟，忏除慧业。花开之日，当并见弥陀，听无生之法。即或再堕人天，亦愿世世永为夫妇。明日为如来潘涅槃日，当持此誓，证明佛前。', '《秋灯琐忆》是清代文人蒋坦所作散文集，内容记述了他与爱妻秋芙的日常生活琐事。这是一对情深意笃、才情清绝、心性淡远的夫妻，他们意趣高雅，性情相契，尽管生活贫寒，却整日涵泳于琴棋书画中，陶然忘忧。文辞极美，叙事传情栩然哀切，辄催人泪下。', '', '', NULL, '', 'indent', 1362779108, '57b908022e958a005fa583ea', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10241, '庄子 · 内篇 · 逍遥游', NULL, 1630, 16, 4, 9, '庄子', NULL, 10064, '57b90297165abd0054bfdce7', '周', 'wen', '文', 'http://baike.baidu.com/subview/27478/5069199.htm', '', '北冥有鱼，其名为鲲。鲲之大，不知其几千里也。化而为鸟，其名为鹏。鹏之背，不知其几千里也；決起而飞，其翼若垂天之云。是鸟也，海运则将徙于南冥。南冥者，天池也。
《齐谐》者，志怪者也。《谐》之言曰：「鹏之徙于南冥也，水击三千里，抟扶摇而上者九万里，去以六月息者也。」野马也，尘埃也，生物之以息相吹也。天之苍苍，其正色邪？其远而无所至极邪？其视下也，亦若是则已矣。
且夫水之积也不厚，则其负大舟也无力。覆杯水于坳堂之上，则芥为之舟；置杯焉则胶，水浅而舟大也。风之积也不厚，则其负大翼也无力。故九万里，则风斯在下矣，而后乃今培风；背负青天，而莫之夭阏者，而后乃今将图南。
蜩与学鸠笑之曰：「我決起而飞，枪榆枋而止，时则不至，而控于地而已矣，奚以之九万里而南为？」适莽苍者，三餐而反，腹犹果然；适百里者，宿舂粮；适千里者，三月聚粮。之二虫又何知！
小知不及大知，小年不及大年。奚以知其然也？朝菌不知晦朔，蟪蛄不知春秋，此小年也。楚之南有冥灵者，以五百岁为春，五百岁为秋；上古有大椿者，以八千岁为春，八千岁为秋，此大年也。而彭祖乃今以久特闻，众人匹之，不亦悲乎！
汤之问棘也是已。汤之问棘曰：「上下四方有极乎？」棘曰：「无极之外，复无极也。穷发之北有冥海者，天池也。有鱼焉，其广数千里，未有知其修者，其名为鲲。有鸟焉，其名为鹏，背若太山，翼若垂天之云，抟扶摇羊角而上者九万里，绝云气，负青天，然后图南，且适南冥也。斥鷃笑之曰：『彼且奚适也？我腾跃而上，不过数仞而下，翱翔蓬蒿之间，此亦飞之至也，而彼且奚适也？』」此小大之辩也。
故夫知效一官，行比一乡，德合一君，而征一国者，其自视也，亦若此矣。而宋荣子犹然笑之。且举世誉之而不加劝，举世非之而不加沮，定乎内外之分，辩乎荣辱之境，斯已矣。彼其于世未数数然也。虽然，犹有未树也。夫列子御风而行，泠然善也，旬有五日而后反。彼于致福者，未数数然也。此虽免乎行，犹有所待者也。若夫乘天地之正，而御六气之辩，以游无穷者，彼且恶乎待哉！故曰，至人无己，神人无功，圣人无名。
尧让天下于许由，曰：「日月出矣而爝火不息，其于光也，不亦难乎！时雨降矣而犹浸灌，其于泽也，不亦劳乎！夫子立而天下治，而我犹尸之，吾自视缺然。请致天下。」
许由曰：「子治天下，天下既已治也。而我犹代子，吾将为名乎？名者，实之宾也，吾将为宾乎？鹪鹩巢于深林，不过一枝；偃鼠饮河，不过满腹。归休乎君，予无所用天下为！庖人虽不治庖，尸祝不越樽俎而代之矣。」
肩吾问于连叔曰：「吾闻言于接舆，大而无当，往而不返。吾惊怖其言，犹河汉而无极也；大有径庭，不近人情焉。」
连叔曰：「其言谓何哉？」
曰：「藐姑射之山，有神人居焉，肌肤若冰雪，绰约若处子。不食五谷，吸风饮露。乘云气，御飞龙，而游乎四海之外。其神凝，使物不疵疠而年谷熟。吾以是狂而不信也。」
连叔曰：「然，瞽者无以与乎文章之观，聋者无以与乎钟鼓之声。岂唯形骸有聋盲哉？夫知亦有之。是其言也，犹时女也。之人也，之德也，将旁礡万物以为一世蕲乎乱，孰弊弊焉以天下为事！之人也，物莫之伤，大浸稽天而不溺，大旱金石流土山焦而不热。是其尘垢秕糠，将犹陶铸尧舜者也，孰肯以物为事！宋人资章甫而适诸越，越人断发文身，无所用之。尧治天下之民，平海内之政，往见四子藐姑射之山，汾水之阳，窅然丧其天下焉。」
惠子谓庄子曰：「魏王贻我大瓠之种，我树之成而实五石，以盛水浆，其坚不能自举也。剖之以为瓢，则瓠落无所容。非不呺然大也，吾为其无用而掊之。」
庄子曰：「夫子固拙于用大矣。宋人有善为不龟手之药者，世世以洴澼为事。客闻之，请买其方百金。聚族而谋曰：『我世世为洴澼絖，不过数金；今一朝而鬻技百金，请与之。』客得之，以说吴王。越有难，吴王使之将。冬与越人水战，大败越人，裂地而封之。能不龟手，一也；或以封，或不免于洴澼絖，则所用之异也。今子有五石之瓠，何不虑以为大樽而浮乎江湖，而忧其瓠落无所容？则夫子犹有蓬之心也夫！」
惠子谓庄子曰：「吾有大树，人谓之樗。其大本拥肿而不中绳墨，其小枝卷曲而不中规矩，立之涂，匠者不顾。今子之言，大而无用，众所同去也。」
庄子曰：「子独不见狸狌乎？卑身而伏，以候敖者；东西跳梁，不避高下；中于机辟，死于罔罟。今夫斄牛，其大若垂天之云。此能为大矣，而不能执鼠。今子有大树，患其无用，何不树之于无何有之乡，广莫之野，彷徨乎无为其侧，逍遥乎寝卧其下。不夭斤斧，物无害者，无所可用，安所困苦哉！」', '此文为《庄子》三十三篇之第一篇。其开篇语：“北冥有鱼，其名为鲲……”流传久远，妇孺皆知。《逍遥游》的想象奇特怪诞，洋溢着浪漫色彩，追求顺其自然无所依，最终获得无穷的自在自由。', '逍遥游：闲适自得、无拘无束的样子。
北冥：北海，因海水深黑而得名。冥，通「溟」，指广阔幽深的大海。下文的「南冥」和「冥海」都用此意。
鲲（kūn）：传说中的大鱼。本义鱼子，小鱼。在此被庄子借用为大鱼之义，这符合庄子的《齐物论》本旨和庄子的独特的奇诡文风。
几：本义为极微小，引申为「极为接近」。《庄子》中此种用法不少，如《人间世》中「无传其溢言，则几乎全」；又引申为「尽」，《庄子》中此种用法更多，如「适得而几矣」（《齐物论》），「无时无几」（《则阳》）。此处当解释为「尽」。旧说「不知其几千里也」都解释为「不知道它有几千里大」，恐误。因《庄子》一书中表数量的词都用「数」，如「数仞」、「数金」释为「几仞」、「很多金子」；若要表达「几千里大」之义，应为「不知其数千里也」（《逍遥游》后文有「其广数千里」）。
千里也：应有千里之大。
鹏：传说中的大鸟。
怒而飞：振翅奋发。怒，奋发，这里指鼓起翅膀，通「努」，奋力飞举。
垂天之云：悬挂在天空的云。垂天，天边，垂，通「陲」，边际。
海运：海动，古有“六月海动”之说，海动必有大风，有大风鹏鸟始可借风力而南徙。指海啸，形容海动风起之时。
徙：迁徙。
天池：天然形成的大水池。
《齐谐》：人名，一说古书名，晋末宋初之书借用此典以命名。
志怪：记述怪异的故事。志，记述。
水击：「击水」一词的倒装，形容大鹏起飞时翅膀拍击水面的壮观景象。击，拍打。
抟（tuán）扶摇而上者九万里：乘着旋风环旋飞上几万里的高空。抟，盘旋上升，一说“抟”当作“搏”（bó），拍击的意思。扶摇，旋风。九，表虚数，不是实指。
去以六月息：凭借着六月的大风才能离开。去，离开。以，用。息，气息，这里指风。
野马：云雾之气变化腾涌成野马的样子。
尘埃：空中游尘。
生物：概指各种有生命的东西。
息：这里指有生命的东西呼吸所产生的气息。
相：互相。
吹：吹拂。
苍苍：深蓝色。
其：或许。
正色：真正的颜色。
邪（yé）：通「耶」，疑问词。
其视下也：它（指大鹏）向下俯视。
亦若是则已矣：也不过像人在地面上看天一样罢了。是，这样。
且夫：助词，无实义，起提示下文的作用。
负：承载。
覆：倒。
坳（ào）堂：屋前地上的洼坑。
芥：小草。
置：放。
焉：兼词，于此，在这里。
胶：动词，粘住地面动不了。
则其负大翼也无力：就没有力量托起鹏巨大的翅膀。
则风斯在下矣：风就在大鹏的下面（说明风有九万里深厚）。斯，则、就。
而后乃今：「今而后乃」的倒装，这时……然后才……。
培风：乘风。培，凭。
夭（yāo）阏（è）：受阻中断。
图南：图谋飞往南方。
蜩（tiáo）：蝉。
学鸠：即鸴鸠，斑鸠一类的小鸟。
決起：迅速跃起。
榆枋（yúfāng）：泛指树木。榆，榆树；枋，檀木。
时则：时或。
控：《康熙字典》：「投也。」
奚（xī）以：何必，哪里用得着。
之：往。
为：疑问助词，相当于「呢」。
适：去往。
莽（mǎng）苍：草色苍莽的郊野。
三餐：指一天。
反：通「返」，返回，下同。
犹：还是。
果然：饱足的样子。
宿：隔夜，头一夜。
舂（chōng）粮：把谷物的壳捣掉，指准备粮食。
三月聚粮：准备三个月的粮食。
之：指示代词，这。
二虫：指蜩和鸴鸠。虫，古代对动物的统称，如大虫指老虎，老虫指老鼠，长虫指蛇。
又何知：又怎么会知晓呢。
小知：小聪明。知，通「智」，下同。
大知：大智慧。
小年：短命。
大年：长寿。
朝菌：一种朝生暮死的菌类植物。
晦朔（huìshuò）：月亮的盈缺。晦，每月的最后一天。朔，每月的第一天。也指从黑夜到天明。
蟪蛄（huìgū）：寒蝉，春生夏死或夏生秋死。
春秋：一整年。
冥灵：大树名，一说大龟名。
大椿（chūn）：树名。
彭祖：传说中寿达八百岁的人物。
乃今：而今，现在。
久：长寿。
匹之：和他相比。匹，比。
悲：可悲。
汤：商朝的建立者。
棘：人名，相传是商汤时的大夫。
是已：就是这样，表示肯定。
穷发：草木不生的地方。发，草木。
修：长。
羊角：像羚羊角的旋风。
绝云气：穿越云气。绝，超越。
斥鷃（yàn）：小池泽中的一种小雀。
仞：古代丈量单位。周代以八尺为一仞，汉代以七尺为一仞。
翱翔蓬蒿（pénghāo）之间：翱翔在蓬木蒿草之间。
至：极致。
辩：通「辨」，区别。
效：功效，此处引申为胜任。
行：品行。
比：团结。
而：通「能」，能力。
其：指上述四种人。
自视：看待自己。
此：指斥鷃。
宋荣子：战国中期的思想家。
犹然：讥笑的样子。
举：全。
誉：赞美。
劝：勉励、奋发。
非：非难、指责。
沮：沮丧。
内：主观。
外：客观。
分：分际。
辩：通「辨」，辨明。
境：界限。
斯：这样，如此。
已：而已。指宋荣子的智德仅此而已。
数数（shuòshuò）然：急切追求的样子。
虽然：即便如此。虽，即使。
树：树立、建树。
列子：郑国人，名御寇，传说能御风而行，战国时代思想家。著有《列子》八篇。今人多异口同声称《列子》一书为后人（尤指晋代张湛）伪托而作。但列子其人其事多次互见于《庄子》，如《应帝王》篇。文段借列子乘风飞行，表明有待的道理。至少可证明：（一）列子有其人，先于庄子或与庄子同时代；（二）《列子》一书中内容多为后人所记述，但应存在有原文原句。这一论断还有待于地下考古证实。
御：驾驭。
泠然：轻妙的样子。
善：美妙。
旬有（xúnyòu）五日：十五天。旬，十天；有，通「又」。
致福：得福。
有所待：有所凭借。待，依靠。庄子的「有待」与「无待」是哲学范畴，指的是事物有否条件性。全句是指列子即使可乘风飞行，也仍然不得不凭借他物。
若夫：至于。
乘：顺。
天地之正：天地万物的本性。正，自然本性。
六气：指阴、阳、风、雨、晦、明。
辩：通「变」，变化。与「正」相对。「正」为本根，「辩」为派生。
以游无穷：行游于绝对自由的境界。无穷，绝对自由的境界。
恶乎待哉：还用什么凭借呢？恶，什么。反问句式加强了「无所待」的意义。
至人：极致的人，庄子心目中境界最高的人。至人、神人、圣人，三者名异实同。
无己：指至人破除自我偏执，扬弃小我，摒绝功名束缚的本我，追求绝对自由、通达，物我相忘的境界。
无功：顺应大道不示功名。
无名：不求名望。「至人无己」是庄子体悟的最高人格境界；「神人无功」是庄子无治主义政治观的表达；「圣人无名」是庄子扬弃功名、去除外物束缚的人生追求。
尧：传说中的帝王。
古代尧时的隐士。此人还见于《徐无鬼》《外物》等篇，皆记述许由拒位之事。
爝（jué）火：火把、火炬。
浸灌：侵润灌溉。
夫子：先生，指许由。
治：太平。
尸：掌管，主持。
缺然：缺乏能力的样子。
致：送与，送给。
宾：派生物。
鹪鹩（jiāoliáo）：一种小鸟。
偃鼠：即鼹鼠，善于钻洞。
归休乎君：「君归休乎」的倒装，君主您还是回去吧。
予无所用天下为：天下对我一点用也没有。为，语气助词。
庖人：厨师。庖，烹饪一类的事。
尸祝：古代祠庙中掌管祭祀的司仪。
樽（zūn）：酒器。
俎（zǔ）：盛肉的器具。全句为成语「越俎代庖」的出处。本意为厨师即使不下厨了，也不能由掌管祭祀的人将酒器肉器拿来烹饪。这是说「尽管有人不管事了，也不能超越自己的职责范围代行其事」。
肩吾、连叔：都为庄子笔下的虚构的体道之士。《庄子》一书，此类人物很多，即使是史上确有其人的，也是一副「道家」腔调、「道家」风格，甚至孔子有时也不例外。
接舆（yú）：楚国隐士，姓陆，名通，字接舆，与孔子同时。此处庄子有自喻接舆的意思。
大而无当：宏达而不适当。无当，不切实际。
往而不反：一往无前而没有反复可循。
惊怖：惊恐。
河汉：天上的银河。
极：边。
大有迳庭：成语「大相径庭」的出处。比喻差别极大。径，门外路径。庭，庭院。
藐（miǎo）：通「邈」，遥远。
姑射：传说中的仙山名。
淖（chuò）约：柔美的姿态。
处子：处女。
凝：凝聚专一。
疵疠（cīlì）：指疾病、灾害。
年谷：指庄稼。
狂：借用为「诳」，谎言。
瞽（gǔ）：盲人。
文章：纹理色彩。文，通「纹」。全句是指为纹理色彩对盲人毫无意义。
观：景象。
岂唯：难道只有。
形骸：形体。
时：通「是」，这。
女：通「汝」，你。
之：这样。
旁礴万物以为一：混同天地万物为纯一。旁礴，通「磅礴」，混同，无所不包容。
世蕲（qí）乎乱：世人祈求纷纷扰扰。蕲，祈求；乱，纷扰，倾轧。
孰：谁，指神人。
弊弊：劳神苦思的样子。
大浸：大水、洪水。
稽：至、到达。
溺：淹。
尘垢秕糠（chéngòubǐkāng）：尘土、污垢、秕谷、糠皮，比喻琐屑无用的东西。
陶铸：原指烧制陶器、熔铸金属，这里指造就培育。
物：事，指世俗事务。
资章甫：贩卖衣帽。资，买卖。章，冠、帽。甫，衣服。
适诸越：到百越去。适，往；诸，于。
断髮：剪髮。
文身：纹身，往身上刺花纹。
四子：旧注指王倪、啮缺、被衣、许由四人，实为虚构的人物。
汾（fén）水之阳：汾河北面。古人以山南水北为阳，山北水南为阴。
窅（yǎo）然丧其天下焉：怅怅然忘却了天下。窅然，怅然自失的样子。
惠子：即惠施，庄子的朋友，先秦时期的杰出代表人物。
魏王：即魏惠王。由于魏国曾定都大梁，所以魏国也称为梁国，因此魏惠王即《孟子》中的梁惠王。
贻：赠给。
大瓠（hù）之种：大葫芦的种子。瓠，葫芦。
树：培植。
实：容纳。
石（dàn）：即「禾石」，古代重量单位，相当于一百二十斤（担）。
落：平浅的样子。
无所容：无可容之物。
呺（xiāo）然：空空的样子。
掊（pǒu）：打破，砸烂。
为：配制。
不龟手之药：防止冻伤的药。龟，通「皲」，皮肤冻裂，下同。
洴澼（píngpì）：漂洗。
絖（kuàng）：通「纩」，絮衣服的丝绵。
聚族：召集同族的人。
鬻（yù）技：出卖、转让技术。
说（shuì）：游说
越有难：越国入侵吴国。难，发动军事行动。
将：率领军队。
裂地：划拨出一块土地。
封：封赏。
龟手：指手足皮肤受冻而开裂。
何不虑：为什么不系缚。
樽：腰舟。可以捆在腰间漂浮在水上。
蓬（péng）之心：即蓬心，心有茅塞，比喻不能通达，见识肤浅。蓬，一种茎叶不直的草。
樗（chū）：一种木质低劣的乔木。
大本：主干。
拥肿：肥粗不端正。拥，通「臃」。
中：符合。
绳墨：木匠画直线的工具。
规矩：木匠用以画圆、方的工具。
涂：通「途」，道路上。
狸：野猫。
狌（shēng）：黄鼠狼。
敖：通「遨」，遨游。
跳梁：跳跃腾挪。成语「跳梁小丑」的出处。梁，通「踉」，跳跃。
中：踩中、触到。
机辟：弩机陷阱，捕猎走兽的工具。
罔（wǎng）：通「网」，罗网。
罟（gǔ）：网的总称。
斄（lí）牛：即牦牛。
执：捉拿。
无何有之乡：宽旷无人的地方。无何有，什么都没有。
广莫：广漠。莫，通「漠」。
野：旷野。
彷徨（pánghuáng）：游逸自得。
无为：随意、悠然。
夭：折断、砍伐。
斤：大斧头。', '北海里有一条鱼，它的名字叫鲲。鲲非常巨大，不知道有几千里。鲲变化成为鸟，它的名字就叫做鹏。鹏的脊背，也不知道有几千里长；当它振动翅膀奋起直飞的时候，翅膀就好像挂在天边的云彩。这只鸟，大风吹动海水的时候就要迁徙到南方的大海去了。南方的大海是一个天然的大池子。
《齐谐》这本书，是记载一些怪异事情的书。书上记载：「鹏往南方的大海迁徙的时候，翅膀拍打水面，能激起三千里的浪涛，环绕着旋风飞上了九万里的高空，乘着六月的风离开了北海。」像野马奔腾一样的游气，飘飘扬扬的尘埃，活动着的生物都因为风吹而运动。天空苍苍茫茫的，难道就是它本来的颜色吗？还是因为天高远而看不到尽头呢？鹏往下看的时候，看见的应该也是这个样子。
如果聚集的水不深，那么它就没有负载一艘大船的力量了。在堂前低洼的地方倒上一杯水，一棵小草就能被当作是一艘船，放一个杯子在上面就会被粘住，这是水浅而船却大的原因。如果聚集的风不够强大的话，那么负载一个巨大的翅膀也就没有力量了。因此，鹏在九万里的高空飞行，风就在它的身下了，凭借着风力，背负着青天毫无阻挡，然后才开始朝南飞。
蝉和小斑鸠讥笑鹏说：「我们奋力而飞，碰到榆树和檀树就停止，有时飞不上去，落在地上就是了。何必要飞九万里到南海去呢？」到近郊去的人，只带当天吃的三餐粮食，回来肚子还是饱饱的；到百里外的人，要用一整夜时间舂米准备干粮；到千里外的人，要聚积三个月的粮食。蝉和小斑鸠这两只小虫、鸟又知道什么呢。
小智比不上大智，短命比不上长寿。怎么知道是这样的呢？朝生暮死的菌草不知道黑夜与黎明。春生夏死、夏生秋死的寒蝉，不知道一年的时光，这就是短命。楚国的南方有一种大树叫做灵龟，它把五百年当作一个春季，五百年当作一个秋季。上古时代有一种树叫做大椿，它把八千年当作一个春季，八千年当作一个秋季，这就是长寿。可是活了七百来岁的彭祖如今还因长寿而特别闻名，普通人都想与他相比，岂不可悲！
商汤问棘，谈的也是这件事。汤问棘说：「上下四方有极限吗？」棘说：「无极之外，又是无极！在草木不生的极远的北方，有个大海，就是天池。里面有条鱼，它的身子有几千里宽，没有人知道它有多长，它的名字叫做鲲。有一只鸟，它的名字叫做鹏。鹏的背像泰山，翅膀像天边的云；借着旋风盘旋而上九万里，超越云层，背负青天，然后向南飞翔，将要飞到南海去。小泽里的麻雀讥笑鹏说：‘它要飞到哪里去呢？我一跳就飞起来，不过数丈高就落下来，在蓬蒿丛中盘旋，这也是极好的飞行了。而它还要飞到哪里去呢？’」这是大和小的分别。
所以，那些才智能胜任一官的职守，行为能够庇护一乡百姓的，德行能投合一个君王的心意的，能力能够取得全国信任的，他们看待自己，也像上面说的那只小鸟一样。而宋荣子对这种人加以嘲笑。宋荣子这个人，世上所有的人都称赞他，他并不因此就特别奋勉，世上所有的人都诽谤他，他也并不因此就感到沮丧。他认定了对自己和对外物的分寸，分辨清楚荣辱的界限，就觉得不过如此罢了。他对待人世间的一切，都没有拼命去追求。即使如此，他还是有未达到的境界。
列子乘风而行，飘然自得，驾轻就熟。十五天以后返回；他对于求福的事，没有拼命去追求。这样虽然免了步行，还是有所凭借的。倘若顺应天地万物的本性，驾驭着六气的变化，邀游于无穷的境地，他还要凭借什么呢？所以说：修养最高的人能任顺自然、忘掉自己，修养达到神化不测境界的人无意于求功，有道德学问的圣人无意于求名。
尧要把天下让给许由，说：「太阳月亮出来了，而小火把还不熄灭，它的亮度，要和日月相比不是太难了吗！及时雨降下了，还要灌溉田地，对于滋润禾苗，不是徒劳吗！你如果成了君王，天下一定大治，而我还忝居其位，我自己感到惭愧极了，请允许我把天下交给你。」许由说：「你治理天下，天下已经治理好了，而我再接替你，我岂不是为名而来吗？名，是依附于实的客体，我难道要做有名无实的客体吗？鹪鹩在深林中筑巢，只要一根树枝；鼹鼠饮河水，只要肚子喝饱。请你回去吧，天下对于我没有什么用！厨子虽然不下厨，主祭的人却不应该超越权限而代行厨子的职事。」
肩吾向连叔求教：「我从接舆那里听到谈话，大话连篇没有边际，一说下去就回不到原来的话题上。我十分惊恐他的言谈，就好像天上的银河没有边际，跟一般人的言谈差异甚远，确实是太不近情理了。」连叔问：「他说的是些什么呢？」肩吾转述道：「‘在遥远的姑射山上，住着一位神人，皮肤润白像冰雪，体态柔美如处女，不食五谷，吸清风饮甘露，乘云气驾飞龙，遨游于四海之外。他的神情那么专注，使得世间万物不受病害，年年五谷丰登。’我认为这全是虚妄之言，一点也不可信。」连叔听后说：「是呀！对于瞎子没法同他们欣赏花纹和色彩，对于聋子没法同他们聆听钟鼓的乐声。难道只是形骸上有聋与瞎吗？思想上也有聋和瞎啊！这话似乎就是说你肩吾的呀。那位神人，他的德行，与万事万物混同一起，以此求得整个天下的治理，谁还会忙忙碌碌把管理天下当成回事！那样的人哪，外物没有什么能伤害他，滔天的大水不能淹没他，天下大旱使金石熔化、土山焦裂，他也不感到灼热。他所留下的尘埃以及瘪谷糠麸之类的废物，也可造就出尧舜那样的圣贤仁君来，他怎么会把忙着管理万物当作己任呢！北方的宋国有人贩卖帽子到南方的越国，越国人不蓄头发满身刺着花纹，没什么地方用得着帽子。尧治理好天下的百姓，安定了海内的政局，到姑射山上、汾水北面，去拜见四位得道的高士，不禁怅然若失，忘记了自己居于治理天下的地位。」
惠子对庄子说：「魏王送给我大葫芦的种子，我种下后结出的葫芦大得可以容纳五石。用它来盛水，它却因质地太脆无法提举。切开它当瓠，又大而平浅无法容纳东西。我不是嫌它不大，只是因为它无用，我把它砸了。」庄子说：「你真不善于使用大的物件。宋国有个人善于制作防止手冻裂的药，他家世世代代都以漂洗丝絮为职业。有个客人听说了，请求用一百金来买他的药方。这个宋国人召集全家商量说：‘我家世世代代靠这种药从事漂洗丝絮，一年所得不过数金；现在一旦卖掉这个药方马上可得百金，请大家答应我卖掉它。’这个客人买到药方，就去游说吴王。那时正逢越国有难，吴王就命他为将，在冬天跟越国人展开水战，大败越人，吴王就割地封侯来奖赏他。同样是一帖防止手冻裂的药方，有人靠它得到封赏，有人却只会用于漂洗丝絮，这是因为使用方法不同啊。现在你有可容五石东西的大葫芦，为什么不把它系在身上作为腰舟而浮游于江湖呢？却担忧它大而无处可容纳，可见你的心地过于浅陋狭隘了！」
惠子对庄子说：「我有一棵大树，人家把它叫做臭椿；它那树干上有许多赘瘤，不合绳墨，它那枝权弯弯曲曲，不合规矩。它长在路边，木匠都不看它一眼。现在你说的那段话，大而没有用，大家都不相信。」庄子说：「你难道没见过野猫和黄鼠狼吗？屈身伏在那里，等待捕捉来来往往的小动物；它捉小动物时东跳西跃，不避高下；但是一踏中捕兽的机关陷阱，就死在网中。再看那牦牛，它大如天边的云；这可以说够大的了，但是却不能捕鼠。现在你有一棵大树，担忧它没有用处，为什么不把它种在虚无之乡，广阔无边的原野，随意地徘徊在它的旁边，逍遥自在地躺在它的下面；这样大树就不会遭到斧头的砍伐，也没有什么东西会伤害它。它没有什么用处，又哪里会有什么困苦呢？」', '[{"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f9e8f18b220af4c040", "shortContent": "齐武帝育有二十三个皇子，其中最有威望的莫过于文惠太子和竟陵文宣王萧子良。可惜受重点栽培的文惠太子英年早逝，齐武帝不得不重新考虑接班人选，是选疼爱有加的皇太孙萧昭业还是才华横溢的二皇子萧子良，历史在这里开了个不大不小的玩笑，萧子良在众望所归之下竟甘居人臣，很是有些可惜。\n在齐朝诸位王子中，萧子良有治事之才，在会稽、丹阳政绩颇佳。他有仁德之心，每每在天下苍生需要的时候，勇敢地向自己的父皇请求施行仁政，...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf3035", "shortContent": "这是庄学的入手处。庄子认为，欲明大道，先欲扩大心量、开阔眼界，摆脱由于地域、时代、角色的限制而产生的一曲之见，然后才谈得上逍遥。“若无天肚量，争得培圣胎。”此为道家的“入道”法。\n\n儒家对此则不太强调。儒家更看重个人生活中的实践理性，故一下手就是《大学》的“正心诚意”、“格物致知”，认为一定要到治国平天下的社会实践体认此道，才算到位。这一层政治实践的意思，《庄子》“内七篇”里也有，但到了最后一篇《...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf303b", "shortContent": "这是古人解决“名”“实”矛盾的基本方法。\n\n在中国古人看来，人心的运动与天地的运转是一个活生生的整体，根本不可分开。但是，人心要反映天地宇宙的运行，又不得不产生“名相”，不如此，生命的自我认知便不算完成。这样，“名”与“实”之间便形成了一个二律悖反。古人解决这个二律悖反的办法是：自说自扫、随立随破。用《庄子》里的话说，便是“得鱼忘荃”、“得兔忘蹄”、“得意忘言”。古人希望用这种方式，来避免天地宇宙...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "6471e1f982772d4594278edf", "shortContent": "《逍遥游》是《庄子》中的代表作品，列于《内篇》之首。逍遥游的意思，是指无所依赖、绝对自由地遨游永恒的精神世界。\n庄子天才卓绝，聪明勤奋，“其学无所不窥”（《史记·老子韩非列传》），并非生来就无用世之心。但是，“而今也以天下惑，予虽有祈向，不可得也”（《庄子·天地》）。一方面“窃钩者诛，窃国者为诸侯”（《胠箧》）的腐败社会使他不屑与之为伍，另一方面，“王公大人不能器之”（《史记·老子韩非列传》）的现...", "authors": ["周先民"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "64720568a5f1e74f9587f2e5", "shortContent": "庄子为战国道家学派的代表，其文章以奔放浪漫、汪洋恣肆为特色，善于用神奇的寓言启发人。选段为《庄子》首篇《逍遥游》的开头，堪称古今中外一切书籍中最为雄奇浪漫的开篇。字里行间，洋溢着庄子特有的奔放不拘的想象力：北海之鱼“鲲”，其大数千里，时辰一到，便化身为大鹏鸟，在海水动荡之际，迁徙向南海天池。庄子虚构了一本名叫《齐谐》的记载神怪故事的书，描述了鲲化为鹏之时，乘着“六月息”，即六月动荡的海风，离海升空...", "authors": ["孙逊"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "647205f445e4710056fc643c", "shortContent": "“高山流水”作为成语用来形容乐曲的高妙以及知音的可贵，出处便是伯牙子期的故事。开篇先交代二人一个“善鼓琴”，一个“善听”，总领全文，后面再进一步展开具体描写。善鼓琴的伯牙，可以用琴声表达出高山、流水、霖雨、崩山这样鲜明而又截然不同的形象。可是这样精妙的技艺，如果没有遇到善听的人，无人欣赏，那也是徒然。需得一个善鼓琴，一个善听，两相契合，相得益彰，才成就了这流传千古的知音佳话。子期对琴音的“善听”，...", "authors": ["陈炜琦"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413205832, '57b9029bc4c97100558f32ce', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10242, '庄子 · 内篇 · 齐物论', NULL, 71, 16, 0, 1, '庄子', NULL, 10064, '57b90297165abd0054bfdce7', '周', 'wen', '文', 'https://baike.baidu.com/item/%E9%BD%90%E7%89%A9%E8%AE%BA/7213047?fr=aladdin', '', '南郭子綦隐机而坐，仰天而嘘，荅焉似丧其耦。颜成子游立侍乎前，曰：「何居乎？形固可使如槁木，而心固可使如死灰乎？今之隐机者，非昔之隐机者也？」
子綦曰：「偃，不亦善乎，而问之也！今者吾丧我，汝知之乎？汝闻人籁而未闻地籁，汝闻地籁而未闻天籁夫！」
子游曰：「敢问其方。」
子綦曰：「夫大块噫气，其名为风。是唯无作，作则万窍怒呺。而独不闻之翏翏乎？山林之畏隹，大木百围之窍穴，似鼻，似口，似耳，似枅，似圈，似臼，似洼者，似污者；激者、謞者、叱者、吸者、叫者、号者、宎者、咬者，前者唱于而随者唱喁。泠风则小和，飘风则大和，厉风济则众窍为虚。而独不见之调调，之刁刁乎？」
子游曰：「地籁则众窍是已，人籁则比竹是已，敢问天籁。」
子綦曰：「夫吹万不同，而使其自己也，咸其自取，怒者其谁邪！」
大知闲闲，小知间间；大言炎炎，小言詹詹。其寐也魂交，其觉也形开，与接为搆，日以心斗。缦者，窖者，密者。小恐惴惴，大恐缦缦。其发若机栝，其司是非之谓也；其留如诅盟，其守胜之谓也；其杀若秋冬，以言其日消也；其溺之所为之，不可使复之也；其厌也如缄，以言其老洫也；近死之心，莫使复阳也。喜怒哀乐，虑叹变慹，姚佚启态；乐出虚，蒸成菌。日夜相代乎前，而莫知其所萌。已乎，已乎！旦暮得此，其所由以生乎！
非彼无我，非我无所取。是亦近矣，而不知其所为使。若有真宰，而特不得其朕。可行己信，而不见其形，有情而无形。百骸，九窍，六藏，赅而存焉，吾谁与为亲？汝皆说之乎？其有私焉？如是皆有为臣妾乎？其臣妾不足以相治乎？其递相为君臣乎？其有真君存焉？如求得其情与不得，无益损乎其真。一受其成形，不忘以待尽。与物相刃相靡，其行尽如驰，而莫之能止，不亦悲乎！终身役役而不见其成功，苶然疲役而不知其所归，可不哀邪！人谓之不死，奚益！其形化，其心与之然，可不谓大哀乎？人之生也，固若是芒乎？其我独芒，而人亦有不芒者乎？夫随其成心而师之，谁独且无师乎？奚必知代而心自取者有之？愚者与有焉。未成乎心而有是非，是今日适越而昔至也。是以无有为有。无有为有，虽有神禹，且不能知，吾独且柰何哉！
夫言非吹也，言者有言。其所言者特未定也。果有言邪？其未尝有言邪？其以为异于鷇音，亦有辩乎？其无辩乎？道恶乎隐而有真伪？言恶乎隐而有是非？道恶乎往而不存？言恶乎存而不可？道隐于小成，言隐于荣华。故有儒墨之是非，以是其所非而非其所是。欲是其所非而非其所是，则莫若以明。
物无非彼，物无非是。自彼则不见，自知则知之。故曰彼出于是，是亦因彼。彼是方生之说也，虽然，方生方死，方死方生；方可方不可，方不可方可；因是因非，因非因是。是以圣人不由，而照之于天，亦因是也。是亦彼也，彼亦是也。彼亦一是非，此亦一是非。果且有彼是乎哉？果且无彼是乎哉？彼是莫得其偶，谓之道枢。枢始得其环中，以应无穷。是亦一无穷，非亦一无穷也。故曰莫若以明。以指喻指之非指，不若以非指喻指之非指也；以马喻马之非马，不若以非马喻马之非马也。天地一指也，万物一马也。
可乎可，不可乎不可。道行之而成，物谓之而然。恶乎然？然于然。恶乎不然？不然于不然。物固有所然，物固有所可。无物不然，无物不可。故为是举莛与楹，厉与西施，恢恑谲怪，道通为一。其分也，成也；其成也，毁也。凡物无成与毁，复通为一。唯达者知通为一，为是不用而寓诸庸。庸也者，用也；用也者，通也；通也者，得也；适得而几矣。因是已，已而不知其然，谓之道。劳神明为一而不知其同也，谓之朝三。何谓朝三？狙公赋芧，曰：「朝三而暮四，」众狙皆怒。曰：「然则朝四而暮三，」众狙皆悦。名实未亏而喜怒为用，亦因是也。是以圣人和之以是非而休乎天钧，是之谓两行。
古之人，其知有所至矣。恶乎至？有以为未始有物者，至矣，尽矣，不可以加矣。其次以为有物矣，而未始有封也。其次以为有封焉，而未始有是非也。是非之彰也，道之所以亏也。道之所以亏，爱之所以成。果且有成与亏乎哉？果且无成与亏乎哉？有成与亏，故昭氏之鼓琴也；无成与亏，故昭氏之不鼓琴也。昭文之鼓琴也，师旷之枝策也，惠子之据梧也，三子之知几乎，皆其盛者也，故载之末年。惟其好之也，以异于彼，其好之也，欲以明之。彼非所明而明之，故以坚白之昧终。而其子又以文之论论绪，终身无成。若是而可谓成乎？虽我亦成也。若是而不可谓成乎？物与我无成也。是故滑疑之耀，圣人之所图也。为是不用而寓诸庸，此之谓以明。
今且有言于此，不知其与是类乎？其与是不类乎？类与不类，相与为类，则与彼无以异矣。虽然，请尝言之。有始也者，有未始有始也者，有未始有夫未始有始也者。有有也者，有无也者，有未始有无也者，有未始有夫未始有无也者。俄而有无矣，而未知有无之果孰有孰无也。今我则已有谓矣，而未知吾所谓之其果有谓乎，其果无谓乎？天下莫大于秋豪之末，而太山为小；莫寿于殇子，而彭祖为夭。天地与我并生，而万物与我为一。既已为一矣，且得有言乎？既已谓之一矣，且得无言乎？一与言为二，二与一为三。自此以往，巧历不能得，而况其凡乎！故自无适有以至于三，而况自有适有乎！无适焉，因是已！
夫道未始有封，言未始有常，为是而有畛也，请言其畛：有左有右，相对而相反，各异便也，有伦有义，有分有辩，有竞有争，此之谓八德。六合之外，圣人存而不论；六合之内，圣人论而不议。春秋经世先王之志，圣人议而不辩。故分也者，有不分也；辩也者，有不辩也。曰：何也？圣人怀之，众人辩之以相示也。故曰辩也者有不见也。夫大道不称，大辩不言，大仁不仁，大廉不嗛，大勇不忮。道昭而不道，言辩而不及，仁常而不成，廉清而不信，勇忮而不成。五者园而几向方矣，故知止其所不知，至矣。孰知不言之辩，不道之道？若有能知，此之谓天府。注焉而不满，酌焉而不竭，而不知其所由来，此之谓葆光。
故昔者尧问于舜曰：「我欲伐宗、脍、胥敖，南面而不释然。其故何也？」舜曰：「夫三子者，犹存乎蓬艾之间。若不释然，何哉？昔者十日并出，万物皆照，而况德之进乎日者乎！」
啮缺问乎王倪曰：「子知物之所同是乎？」
曰：「吾恶乎知之！」
「子知子之所不知邪？」
曰：「吾恶乎知之！」
「然则物无知邪？」
曰：「吾恶乎知之！」
虽然，尝试言之。庸讵知吾所谓知之非不知邪？庸讵知吾所谓不知之非知邪？
且吾尝试问乎女：民湿寝则腰疾偏死，鳅然乎哉？木处则惴慄恂惧，猿猴然乎哉？三者孰知正处？民食刍豢，麋鹿食荐，蝍蛆甘带，鸱鸦耆鼠，四者孰知正味？猿猵狙以为雌，麋与鹿交，鳅与鱼游。毛嫱丽姬，人之所美也；鱼见之深入，鸟见之高飞，麋鹿见之决骤，四者孰知天下之正色哉？自我观之，仁义之端，是非之涂，樊然殽乱，吾恶能知其辩！
啮缺曰：「子不知利害，则至人固不知利害乎？」
王倪曰：「至人神矣！大泽焚而不能热，河汉冱而不能寒，疾雷破山，飘风振海而不能惊。若然者，乘云气，骑日月，而游乎四海之外，死生无变于己，而况利害之端乎！」
瞿鹊子问乎长梧子曰：「吾闻诸夫子，圣人不从事于务，不就利，不违害，不喜求，不缘道；无谓有谓，有谓无谓，而游乎尘垢之外。夫子以为孟浪之言，而我以为妙道之行也。吾子以为奚若？」
长梧子曰：「是黄帝之所听荧也，而丘也何足以知之！且女亦大早计，见卵而求时夜，见弹而求鸮炙。
予尝为女妄言之，女以妄听之。奚旁日月，挟宇宙？为其吻合，置其滑涽，以隶相尊。众人役役，圣人愚芚，参万岁而一成纯。万物尽然，而以是相蕴。
予恶乎知说生之非惑邪！予恶乎知恶死之非弱丧而不知归者邪！丽之姬，艾封人之子也。晋国之始得之也，涕泣沾襟；及其至于王所，与王同筐床，食刍豢，而后悔其泣也。予恶乎知夫死者不悔其始之蕲生乎？
梦饮酒者，旦而哭泣；梦哭泣者，旦而田猎。方其梦也，不知其梦也。梦之中又占其梦焉，觉而后知其梦也。且有大觉而后知此其大梦也，而愚者自以为觉，窃窃然知之。君乎，牧乎，固哉！丘也与女，皆梦也；予谓女梦，亦梦也。是其言也，其名为吊诡。万世之后而一遇大圣，知其解者，是旦暮遇之也。
既使我与若辩矣，若胜我，我不若胜，若果是也，我果非也邪？我胜若，若不吾胜，我果是也，而果非也邪？其或是也，其或非也邪？其俱是也，其俱非也邪？我与若不能相知也。则人固受其黮闇，吾谁使正之？使同乎若者正之？既与若同矣，恶能正之！使同乎我者正之？既同乎我矣，恶能正之！使异乎我与若者正之？既异乎我与若矣，恶能正之！使同乎我与若者正之？既同乎我与若矣，恶能正之！然则我与若与人俱不能相知也，而待彼也邪？
何谓和之以天倪？曰：是不是，然不然。是若果是也，则是之异乎不是也亦无辩﹔然若果然也，则然之异乎不然也亦无辩。化声之相待、若其不相待。和之以天倪，因之以曼衍，所以穷年也。忘年忘义，振于无竟，故寓诸无竟。」
罔两问景曰：「曩子行，今子止﹔曩子坐，今子起。何其无特操与？」
景曰：「吾有待而然者邪？吾所待又有待而然者邪？吾待蛇蚹蜩翼邪？恶识所以然！恶识所以不然！」
昔者庄周梦为蝴蝶，栩栩然蝴蝶也。自喻适志与！不知周也。俄然觉，则蘧蘧然周也。不知周之梦为蝴蝶与，蝴蝶之梦为周与？周与蝴蝶，则必有分矣。此之谓物化。', '《齐物论》是《庄子·内篇》的第二篇。全篇由五个相对独立的故事连珠并列组成，故事与故事之间虽然没有表示关联的语句和段落，但内容上却有统一的主题思想贯穿着，而且在概括性和思想深度上逐步加深提高，呈现出一种似连非连、若断若续、前后贯通、首尾呼应的精巧结构。', '齐物论：分为物论、齐论、齐同物论。即人物论、万物论、齐同论、齐同万物论。齐，一、合众为一。物，人物、万物。庄子的笔法将这几层论述融合在「齐物论」三个字中，《齐物论》也是混融交合得物我皆忘。
南郭：住在城南而以为名称。「滥竽充数」的南郭先生就是住在城南，救狼的东郭先生就住在城东。
子綦（qí）：人名。
隐机：依凭着案几。机，通「几」，地上的或床榻上的矮桌。
嘘：呼气，吐气。
荅焉：形体破坏的样子，这里指生气索然。
耦（ǒu）：躯体。
颜成子游：南郭子綦的门人。颜成，复姓。
而心固可使如死灰乎：成语「心如死灰」的出处。上文「形固可使如槁木」，成语「形如槁木」的出处。死灰，指内心不起念。
偃（yǎn）：子游的名。
不亦善乎，而问之也：补语前置，正序为「而问之不亦善乎」，你问得很好。善，很好。而，你。
吾丧我：吾丧我：摒弃小我的私见。吾，真我。丧，忘却。我，偏执小我。
女：通「汝」，你。
人籁：人吹竹管之声。
地籁：大地的箫声，指风吹孔窍之声。
天籁：自然的箫声，指万物因其各自的自然而然状态而自鸣。
方：道理。
大块噫（yī）气：大地吐气。块，土地。
万窍怒呺（háo）：万千个孔穴都鼓怒号叫，指风吹遍了满世界。
翏翏（liáo）：《康熙字典》：「音『聊』，长风声。」
山陵之畏隹（wēicuī）：指山林的高大，这里意为山林被风吹得摇来动去。陵，通「林」。畏隹，通「巍崔」。
枅（jī）：柱上横木。
圈：圈栏。
臼（jiù）：地坑。
洼：凹洼深地。
污：有水的小坑。
激：激流声。
謞（hè）：箭射出的声音。
叱（chì）：叱骂声。
吸：呼吸声。
叫：叫喊声。
譹（háo）：哭声。
宎（yǎo）：深谷之声。
咬：细语声。
前者唱于而随者唱喁（yú）：于，喁，表示相应和之声。前者指风，随者指孔穴。
泠（líng）风：小风。
飘风：暴风。
厉风济：猛烈的风停止。济，停止。
调调：风摇树之声。
刁刁：也作「刀刀」，也是树摇之声。
比竹：排列竹管，泛指乐器。
自己：有这样的孔窍就有这样的声音，都是孔窍之自取。
夫吹万不同：大道之吹，万物声音各不相同。吹，在这里是个重要概念，指大道的物化表现。
咸：全是。
怒：通「努」，奋发。
邪（yé）：语气助词。
大知（zhì）闲闲，小知间间：旧注的价值标准一般将大知、大言解为褒义词，似不妥。这一段是对各执己见的描述，其间的各种情形都未达到丧我，所以都属贬义。大知，绝顶聪明的人。知，通「智」。闲闲，拒绝他人意见的样子。小知，才智浅陋的人。间间，计较小事。
大言：富于雄辩的言论。
炎炎：气势烈猛逼人。
小言：徒费口舌的言论。
詹詹：喋喋不休，哆里哆唆。
魂交：精神交错。
形开：形体不宁。
与接为构，日以心斗：互文句法。与上句「其寐也魂交，其觉也形开」用法相同。接，与外界接触。耩，纠缠不清。日，日日夜夜。心斗，钩心斗角。
缦（màn）：通「慢」，迟缓。
窖（jiào）：设下圈套。
密：心思缜密。
惴惴（zhuìzhuì）：忧惧。
缦缦：沮丧。
栝（guā）：箭头。
司：通「伺」，等待时机。
盟：誓言。
守：沉默不语。
杀：威严。
日消：一天天消毁。
溺：沉溺。
复：恢复原状。
厌：压抑。
缄（jiān）：密封，
洫（xù）：衰老颓败。
复阳：恢复生气。
变：无常。
蜇（zhé）：恐惧害怕。
姚（yáo）：轻浮。
佚（yì）：奢华。
启：放纵。
态：造作。
乐出虚：乐音出虚空的箫管。
蒸成菌：湿热的天气能滋长茵类。
相代：相互更替。
萌：起始。
旦暮：早晚。
所由：从何处，因谁。
非彼无我：此段中的辩证关系错综复杂又奇特诡异，体现着庄子独特的认识论。彼，即上文「旦暮得此」的「此」，指自然造化。「我」即上文「日夜相代乎前」的现象，与「彼」相对。
取：禀受、体现。
宰：主宰。
眹（zhèn）：迹象，征兆。
信：真实。
情：情景。
形：形迹。
百骸（hái）：百余骨节。
九窍：孔穴，指双眼、双耳、双鼻孔、口、生殖器、肛门。
六藏：心、肺、肝、脾、双肾。藏，通「脏」。
赅（gāi）：完备。
吾谁与为亲：正序为「吾与谁为亲」，我同哪一部分最亲近呢。
私：偏私。
臣妾：西周、春秋时对奴隶的称谓。男奴叫臣，女奴叫妾。
相治：相互支配。
递：轮流。
真君：即上文的「真宰」，意为自然造化。
相刃：交锋，互相竞斗。
相靡（mó）：互相摩擦。靡，通「磨」。
驰：奔跑。
役役：劳劳碌碌。
苶（niè）：疲惫不堪的样子。
形化：形体变化。指少年变为青年、中年、老年直至死亡。
芒：茫然。
成心：由禀受真宰形成的自我意识，即成见。
师：师法、效法。
自取：自以为是。
心：成熟的思想。
今日适越而昔至也：今日去越国而昨天已经到了。指是非是由于成心先已形成。
无有为有：有生于无，以无为有。
神禹：神明的大禹。
言非吹：风吹出自天然，言论出自成心成见。言，言论、言说。非，否定词，不是。吹，风吹。
言者有言：发表言论的人各有说法。
特未定：还不足以成为定则。
鷇（kòu）音：初生小鸟的叫声。比喻不带成见的话语。鷇，雏鸟。
辩：通「辨」，辨别。
隐：被隐蔽。
小成：小的、片面的认识成果。
荣华：华美的辞藻。
莫若以明：不如用明澈的心境去观照事物的本然。
彼：指两个对立的方面。
物无非是：天下万物没有不是「此」的。
自彼则不见：从「彼」的角度看就看不到这方面。
自知则知之：「自知」文意难通，似应为「自是」，为「自是则知之」，意为从自身这方面的角度来看就知道了。
彼出于是：「彼」出自于「是」。意为「彼」是出自于「是」相对而立的。
是亦因彼：「是」也是依存于「彼」而存在。
方生方死，方死方生：一方出生的同时另一方也在死灭，一方在死灭的同时另一方也在出生。即万物随起随灭，随灭随起。方，表示动作状态的进行格动词。
方可方不可，方不可方可：正确的同时出现错误．错误的同时出现正确。可，肯定、正确。不可，否定、错误。
因是因非，因非因是：正确就任由它正确，错误就任由它错误。即不去计较是与非。因，任由。
照之于天：观照自然大道。照，观照、反映。天，自然大道。
亦因是也：也是任由如此。是，这个自然之道。
是亦彼也：「此」也就是「彼」。
彼亦一是非，此亦一是非：彼有它的是非，此也有它的是非。
果且有彼是乎哉：果真有彼与此的分别吗？
莫得其偶：不能互相对立。偶，相对立。
道枢（shū）：道的枢纽关键。
枢始得其环中：合乎道的枢纽关键才能如进入环之中心般空空如也。环中。环之中心，环之中心是空的。空空如也才能应变无穷。
以应无穷：以应变无穷的是非流变。
是亦一无穷，非亦一无穷也：「是」是变化无穷的，「非」也是变化无穷的。
以指喻指之非指，不若以非指喻指之非指也：以拇指来譬喻拇指不是手指，不如以不是拇指来譬喻拇指不是手指。喻，譬喻、说明。
以马喻马之非马，不若以非马喻马之非马也：以白马来譬喻白马不是马，不如以不是白马来譬喻白马不是马。马，每句的前两个「马」字意为白马，后一个「马」字为马的概念。与「指」情况相同。以上两注的两句明显是对公孙龙「指非指」、「白马非马」命题的批评。「指非指」，前一个「指」为拇指，是具体事物；后一个「指」为手指，是抽象概念，所以「拇指不是手指」。「白马非马」，「白马」是具体事物，后一个「马」为马的概念，所以「白马不是马」。而庄子是针对这些命题有感而发，认为与其从概念出发来说明具体事物不是概念本身，还不如从具体事物来说明概念不是具体事物。庄子的意思是，不必将抽象概念和具体事物当做「彼」与「此」的对立，不如不分彼此是非，一切随任自然。
天地一指也，万物一马也：以其同万物的观点来看，天地就是「一指」，万物就是「一马」。
道：道路。
行之而成：人走过而形成。
物谓之而然：事物的名称是人叫出来的。物，某一事物。谓之而然，人叫了而这样。
有自也而可，有自也而不可；有自也而然，有自也而不然：「可」有「可的」来由，「不可」有「不可」的来由。「是」有「是的」来由，「不是」有「不是」的来由。自，来自、原因。
物固有所然：万物都固有「是」的地方。
无物不然，无物不可：没有一物「不是」，没有一物「不可」。
莛（tíng）与楹（yíng）：草茎。楹，房柱。莛在此喻「小」，楹在此喻「大」。小大之别，与下文丑关之别相对。
厉：丑陋女子。
恢诡谲（jué）怪：泛指诡异奇怪的事物。
道通为一：从「道」的角度看都相通为一。
其分也，成也：有所分散，必有所聚成。分，分开、分解。成，生成、形成。「成」和「分」也是相对立的，一个事物被分解了，这就意味着生成一种新的事物。
其成也，毁也：有所聚成，必有所毁灭。毁，毁灭，指失去了原有的状态。「毁」与「成」也是相对立的，一个新事物通过分解而生成了，这就意味原事物的本有状态必定走向毁灭。
复通：融合，通融。
不用：不用偏执于成心己见。
诸：兼词，相当于「之于」。
庸：循环变化。
通：缘于同一。
适得：达到德。
因是已：达到了万物的本根。
神明：心思智巧。
狙公：养猴的人。
赋芧：分发橡栗。
狙：猕猴。
天钧：天然均衡的状态。
两行：任由对立双方自然演化。
至：极致。
未始：未曾，不曾。
封：界限，界域。
彰：分明。
有成与亏，故昭氏之鼓琴也；无成与亏，故昭氏之不鼓琴也：即使最完备的乐队也不能同时将所有乐音全演奏出来，总有乐音被遗漏。所以一奏乐，就有所成也有所亏，不奏乐也就无成无亏。昭氏，昭文，著名琴师。
师旷：著名乐师。
枝策：指师旷敲打节奏。
惠子：惠施，古名家学派代表人。
据梧：指惠子依靠在梧桐树下与人辩论。
盛：最高境界。
载之末年：从事这项技术直到晚年。末年，晚年。
以异于彼：宾语前置句，即以其好之也异于彼。异，炫耀于他人。彼，他人。
彼非所明而明之：他人并不一定要了悟却非要他人了悟。明，了悟、了解。
故以坚白之昧终：所以玩弄「离坚白」的眩惑之论而自愚终身。「坚白」，战国时代的著名论题，与「白马非马」同是诡辩命题，意为石头的坚硬为触觉，白为视觉，任何一种视觉或触觉衹能辨析其中之一「坚」或「白」，而不能同时获得。昧，自愚。
其子又以文之纶（lún）终：指昭文的儿子后来继承了父亲的余绪。
滑疑：混乱诡异。
图：摒弃，革除。
今且：假设词。且，姑且。
类：指「莫若以明」的言论。
类与不类：无论是类同或是不类同。
虽然：即使如此，表示转折论述。
有始也者：天地万物总有个开始。
有未始有始也者：还有没有开始的开始。
有未始有夫未始有始也者：更有未曾开始的未有开始的开始。上三句意为宇宙本体的「开始」问题追溯起来是无穷无尽的，在「……之前」总有个「……之前的之前」，由此确定宇宙的无穷无尽。
有无也者：宇宙万物也有「无」的状态。道家认为「天下万物生于有，有生于无」。在老子那里，「无」是终极的、绝对的；而在庄子这里，「无」是相对的，「无」之前还有「无无」、「无无无」「无无无无」……
有未始有无也者：还有不曾「无」的「无」的状态。
有未始有夫未始有无也者：更有不曾「无」的不曾「无」的「无」的状态。
俄而有无矣：突然一下子产生了「有」和「无」。俄而，突然，表示时间之快速与偶然。
秋豪之末：秋天野兽的毫毛尖。成语「明察秋毫」与之意同。豪，通「毫」，毫毛。末，尖端、末端。
太山：即泰山。
殇（shāng）子：夭折的孩子。
彭祖：传说中长寿的人。
夭：短命。
天地与我并生，而万物与我为一：互文句。天地万物与我共生并存，都合为一体。
巧历：工于计算的人。
自无适有，以至于三：从「无」到「有」还推断出个「三」来。
而况自有适有乎：更何况是从「有」到「有」呢。
无（wú）适焉：不必再往下推算了。无，通「毋」。
常：恒常，定数。
畛（zhěn）：界限。
八德：上述左、右、伦、义、分、辩、竞、争，指百家争鸣各派所偏执争论的八种情况。
六合：天地四方。天、地、东、西、南、北，为六合。
存：姑且搁置。
论：论证。
议：评议。
春秋：指记载历史之书。
经：治理。
先王之志：先王政绩的记载。
辩：辩解是非。
相示：互相显示。
有不见：有看不见的地方。
大道不称：大道不可称谓。
大辩不言，大仁不仁：大辩不需言辞，大仁无所偏爱。与《老子》「天地不仁」同义。
大廉不谦：大廉无须逊让。嗛，通「谦」，谦让。
大勇不忮（zhì）：大勇从不伤害他人。忮，忌恨、伤害。
昭：光显。
清：为贪求美名而清廉。
信：真实。
勇忮而不成：「勇」滞于悖逆就不能成功。
五者圆而几向方矣：这五种情况，离道太远犹如画圆却更接近方了。园，通「圆」。
天府：天然的府藏，指圣人的心胸宽广，可以涵收万物。
酌（zhuó）：汲取。
葆（bǎo）光：含藏光明。
故：句首语气助词，相当于「夫」、「盖」等。
宗、脍、胥敖：三个小国的名字。
南面：临朝，古时帝王坐向为面南背北。
释然：愉悦的样子。
三子：三个小国的国君。
蓬艾之间：意为三个国家很小，好像存在于蓬草之间。蓬，蓬蒿。艾，艾草。
若：你，第二人称代词，指尧。
十日并出：十个太阳一齐出升，古代神话里处于后羿之前的时代。
进乎：超过、胜过。
啮（niè）缺、王倪（ní）：均为庄子笔下杜撰之名。
庸讵（jù）知：怎么知道
偏死：半身不遂。
鳅：泥鳅。
惴栗（lì）恂（xún）惧：恐惧害怕不安。
猨（yuán）猴：猿猴。猨，通「猿」。
刍（chú）：用草喂的牛羊的肉。
豢（huàn）：用谷子喂的家禽类的肉。
荐：好草。
蝍蛆（jíqū）：蜈蚣。
鸱鸦（chīyā）：猫头鹰。
耆（shì）：通「嗜」，喜欢。
正味：口味的标准。
猵（biān）狙：猕猴，与猿形似。
毛嫱（qiáng）丽姬：古代两位美人。
美：形容词的意动用法，认为很美。
决（kuài）：通「快」。
骤：疾走。
正色：美色的标准。
涂：通「途」，途径。
樊（fán）然肴（xiào）乱：纷乱错杂。
大泽：大湖泽。
热：形容词的使动用法，使……觉得热。与下句「寒」的用法相同。
冱（hù）：冰冻。
死生无变于己：生死对自身毫无作用。
瞿（qú）鹊子、长梧子：庄子杜撰的人名。
夫子：指孔子。
务：俗务。
就利：追逐利益。
违害：躲避灾害。
喜求：热衷于妄求。
缘道：拘泥于俗道。
孟浪：荒诞而不着实际。
听荧：疑惑不明。
时夜：守夜，意喻司职守夜的公鸡。
鸮（xiāo）：斑鸠鸟。
奚（hé）：通「曷」，何不，表示强调语气。
旁（bàng）：通「傍」，依傍。
脗（wěn）合：吻合。脗，通「吻」。
滑涽（hūn）：纷繁杂乱。
以隶相尊：以贱奴卑隶为尊贵。指混同尊卑贵贱之分。
芚（dùn）：通「沌」，混沌。
纯：纯清。
相蕴：积淀沉蕴。
说（yuè）：通「悦」。
弱：少年，古人将刚成年称为「弱冠」。
丧：亡失，离开家乡。
丽之姬：即前文所述的「丽姬」。
王所：王宫。
筐（kuāng）床：方床。
蕲（qí）：追求。
旦：早上，这里指酒醒后。
窃窃然：自以为明察的样子。
牧：牧人，指卑贱之人。
吊诡：怪异，诡奇。
既使：假使，表假设关系，而非现代汉语中的条件关系。
不若胜：宾语前置句。正序为「不胜若」。
果是：果然正确。果，果然、果真。
或：一方。后一个「或」为另一方。
黮（dàn）暗：暗昧不明，所见偏颇。
正：评判，裁别。
天倪（ní）：自然的分别。
是不是：对就是不对。
然不然：「这」就是「非这」。
化声：是非之辩。
待：对立。
因之以曼衍：因顺万物的自然演化。因，因顺、随任。曼衍，自然的变化。
穷年：享尽天年。
忘年忘义：忘却时间和仁义。年，年月，这里指时间。
振于无竟：畅游无穷之境。竟，通「境」。
寓诸无竟：寄托于无穷之境。
罔两：影子外围的淡影。
景：通「影」，影子。
曩（nǎng）：先前
特操：独特的操守。
有待而然：有所依凭才这样。
蛇蚹（fù）蜩（tiáo）翼：蛇依凭鳞片，蝉依凭薄翼。
栩栩然：活泼自在的样子。
喻：晓，觉得。
适志：得意顺畅。
不知周：忘却了自己是庄周。
俄然：忽然。
蘧蘧（qú）：惶恐的样子。
物化：物我两化而融为纯一。', '南郭子綦靠几静坐，仰面朝天缓缓地吐气，茫然若失，就像魂魄离开了躯体。南郭子綦的学生颜成子游见状马上前来侍候，问南郭子綦说：「您刚才是处于一种什么样的境界呢？一个人的肢体形貌在打坐时固然可以使它像枯槁之木一样毫无生气，难道一个人的心神在打坐时也可以使它像死灰一样毫无生气吗？您在今天所表现出来的安稳境界，跟以前的安稳境界绝对不一样。」南郭子綦回答说：「偃，你问此事，不是问得很好吗？今天我遗忘了形体之我，你知道这一点吗？你衹听到人吹箫管发出的声音，而没听听风吹众窍所发出的声音，你衹听到风吹众窍所发出的声音，而没有听到天地间万物的自鸣之声！」
子游说：「能不能问一问大地的声音与天的声音是怎么回事呢？」南郭子綦回答说：「那个地籁就是无边无际的造物之作用所发出的能量之气息啊，发出来之后就被叫作风。这种能量要么就是内在蕴含着不发出来，一旦发出来就会万窍怒号，难道你耳边就没有听到过这种‘呼呼’的风声吗！山林的险峻、大树周身的窍穴，有的形状像鼻子，有的形状像张开的嘴，有的形状像耳朵，有的形状」像扁长的发簪，有的形状像凸出来的圈筒，有的形状像凹下去的浅坑，有的浅一些，有的深一些；于是所发的声响就有的快促，有的像响箭，有的刺耳，有的发自往里吸，有的发自往外出，有的像嚎哭声，有的像狗叫，有的像悲哀声。能量流的运动原本就很舒缓动听，怪就怪哉随着各种物体所发出的众口乱叫而嘈杂了；当徐徐之风时万物就会轻微地唱和，当风大时万物就会大点儿地唱和，当劲风厉厉时反而所有能发响者皆欲发而无声了，难道你没有从风响的音调中听出来各种声响的发声原因、从风的响声上听出其后面的那个不发声的东西吗？」
子游又问：「大地的本意可以借助万物之窍所发出的唱和声中表达出来，人所的本意也可以从清悠、消沉、谐美的各种丝竹的或条畅或激昂的声中表达出来，那么天的本意是怎么表达出来的呢？」南郭子綦说：「所谓天籁的音响万变，而又能使其自行息止，这完全都是出于自然，有什么东西主使着它呢？」
大智者看上去显得非常广博，小智者却十分琐细；高论者盛气凌人，争论者小辩不休。辩士睡时，精神与梦境交错在一起，醒后疲于与外物接触纠缠。每天与外物相接，其心有如经历了一场又一场的战斗一样疲惫。有的心机柔奸，有的善设陷阱，有的潜机不露。小的惧怕表现为忧惧不安，大的惧怕表现为惊恐失神。三灾八难的降临就像箭在弦上一样地随时而发，这全是由于行为人的心机所伺机行是非之行径所造成的；三灾八难的不降临也可以像发愿一样的通过履践其愿誓而消失，那就要看行为人是否践履自己的愿誓而坚持无思无为的行径来决定了。神情衰沮就像秋风冬雪肃杀万木一样无情，这就说明道心逍遥之本性的消亡是渐进的过程；如果行为人沉迷于自己之心机的经营里而不醒悟的话，也就很难再回到那个逍遥的本性去了。然而行为人对恢复道心的修行却厌恶得像自行封闭起来的蚕子一样的听不进去，这就说明行为人的执着意识的积习太严重了；像这样的几乎等于死亡的心，实在是没法使它再恢复生气。所谓的喜怒哀乐，都是认取了事物对自己所引发的感受而逐步形成多忧惧的意识，正在这个意识之执着的支配下才形成了轻狂而放任的或喜或怒或哀或了的情绪了。喜怒哀乐发出来之后就过去了，接着而来的就是又孕育出了无明之烦恼，如此的一天到晚的不是喜乐就是烦恼的交替着出现在眼前，而从来不知道它们是怎么产生的。不可救药啊，不可救药！一天到晚地如此活着，三灾八难也就由此产生了啊！
如果没有了我之内外的任何对立面的观念也就没有我的观念了，如果没有了我的观念也就没有了博取之心了，如此也就基本上接近于那个道心的行径了，然而却不知道是什么东西在支配着这个道心的行径。好像其中有一个迫使万物循势而动的主宰在，然而偏偏找不到那个主宰的迹象在什么地方，当你恢复了道心之后就会彻底明了那个迫使万物循势而动的主宰了，但它却又没有一个具体的形状可见，它仅仅是道心的广大无缘之悲性而没有具体形状而已。一个人身上有百骸、九窍、六脏，当这些脏器都完备了之后才能决定一个人的生存，那么你认为哪一个脏器最重要而倍加爱护呢？还不是都喜欢而都倍加爱护吗？这个问题的背后岂不牵扯到一个「私我」的观念了吗？如果有一个「私我」之观念的话，那么各脏器岂不就成了分别为「私我」提供专职服务的臣下与妻妾了吗？这种势必缺乏协调性的臣下与妻妾岂不就不足以担当全面治理整个机体的重任了吗？难道它们是逐个轮流着担当君的职责而协调各位臣妾的工作吗？这就证明里面有一个真正的主宰在后面起着决定作用吗？如果实证到了那个广大无缘之慈悲性的道心原来是没有具体形状可得的时候，那时候就会明白这个真宰的作用无论怎么做都既不会益于也不会损于那个真宰者的不生不灭、不增不减、不垢不净性了。然而自从那个人人都有的真主秉承了执着之意识以投胎成人之后，还没有到该死的寿数时就在哪里等着寿尽的一天了，这是因为内外界事物所诱发的爱、恶、欲、的心行在相争斗以至于相消耗的缘故；明明知道生命的寿终就像飞驰一样，但却不知道如何止住这种迈向寿终的步伐，对于自许聪明的人们来说难道不是一种悲哀吗！衹知道一辈子地役使自己的心身去赴爱、恶、欲的劳役但对于恢复道心却毫无一点儿进展，整天精神不振地疲于劳役但却不知道究竟是为了什么，对于自许聪明的人们来说难道不是一种痛心吗！即使能够达到人们所说的千万岁的长生不老，对于道心的恢复又有什么益处呢？即使其形体逐渐衰败枯萎，也衹是其执着心使其具有了这种变化而已，对于那个真宰的不生不死、不增不减、不垢不净性而言怎能不是最大的痛心呢！人生在世，本来就如此糊涂吗？
还是衹有我糊涂，而别人也有不糊涂的呢？世人如果都以自己的偏见作为判别是非的标准，那么谁没有一个标准呢？何必是懂得事物更替的聪明人才有是非标准呢？即使愚蠢的人也是有的。在未有成见存于心中之前已经就因自己的好恶之感受而得出对与错的心得了，这个心得之现象的得出就像今天刚到了越国而实际上原本就在越国一样地早就待在那个地方了。所以才从道心里凭空产生出心得乃至执着了。对于通过作意而产生出神奇的事物来的行为而言，即使有着禹王那样的神通，也不能有一点儿故意去知道的心在，客观世界的任何事物又怎能奈何于超然物外的那个道心之吾的神奇作用呢！
言论出于机心，与无心而吹的「天籁」是不同的。发言者知持一端，他们的话并不能作为衡量是非的标准。为了表述某事物果真就需要言辞吗？人们最初始时的思想交流并没有使用言辞啊！人们的言辞之所以能听得懂而雏鸟的叫声却听不懂，这个能听懂的背后是有一个思辨的审明作用在呢？还是没有思辨的审明作用在呢？那个大道为什么未被真正地认识到而产生了见解上的真与假呢？言辞所表述的意义为什么未被真正地认识到而产生了判断上的是与非呢？那个大道为什么必须去参悟才能实证到它而不能通过想象去找到它呢？言辞所表述的意义为什么必须通过思辨才能听懂而不能一听就能确定其真意呢？原因就在于那个大道被不深刻、不全面的小见解给遮蔽住了，就在于言辞所表述的意义被言辞本身的巧妙之比喻或夸张给遮蔽住了。所以才产生了儒墨两家之学术思想的我对你错的争鸣，世人都是用自己所认定的正确去评判人家的不正确，都是用自己所认定的人家的不正确来宣扬自己的正确。与其想用自己所认为的正确去推定人家的不正确，与其想用人家的不正确来证明自己所认为的正确，那就不如静下心来认认真真地修身以达到内明为好。
天地万物在道体上不存在你我它的分别，天地万物在道体上也不存在你对及它错的差别。如果从万物存在的现象去看就不会认识到万物是道体之妙用的那个本质，衹有从内明的大智慧上去看才能认识到万物同是道体之妙用的那个本质。所以说人们之所以会有万物的个体皆有差异以及你对而它错的分别心乃是从没有分别心的物我同胞的实相中产生的，于是那个没有分别心的物我同胞之实相的提法也就对应于人们的分别心而提出来了。人们之所以会产生分别心，乃是由于当下一念的喜爱心所造成的虽然都是因为当下一念的喜爱心所造成，但当下一念的喜爱心刚刚生起便又马上消失了，前念刚刚消失便又马上生起了后念的喜爱心；于是人们的分别心刚刚形成执着又紧接着遇到新的事物而须要去分别了，于是对新事物的分别心又形成另一个新的执著心了；因为先前的执着心而产生了对新遇到之事物的不认同，对新遇到之事物的不认同经过喜爱心的分别又形成了新的另一个执着。所以每一位恢复了道心的圣人无不鉴于当下之一念的迁流不断而不由得时刻注意着当下一念的似起未起之时，也就是因为这个道理啊！在先前的那个执着的作用下产生了新的另一个执着，新的另一个执着又变成了产生新执着的旧执着。先前的执着是喜爱心所认为的对与错而形成的，新执着也是喜爱心所认为的对与错而形成的。果真存在着执着心所认为的那个正确吗，果真存在着执着心所认为的那个不正确吗？无论是执着心所认为的正确还是所认为的不正确皆是失去了道心中庸之用的结果，这就是所说的形成执着的关键之所在。正是由于形成执着的整个关键作用发生在旧执着与新执着的环环相产生的现象中，于是无始劫以来所形成的无穷的执着也就变成了遮蔽道心的「五蕴」了。道心的中庸之大用是无穷无尽的，意识心的执着之妄用也是无穷无尽的。所以说要想了知道心的全体之大用还是静下心来认认真真地修身以达到内明为好。
用自己的手指来说明人家的手指不是手指，不如不用自己的手指来说明人家的手指不是手指为好；用马来说明白马不是马，不如不用马来说明白马不是马为好。从道通为一的观点看，天地与一指，万物与一马，都是没有区别的。
人家认为可，我也跟着认为可；人家认为不可，我也跟着认为不可。于是那个道的生发万物的妙用也就在因缘聚合而生的条件下形成了，于是万物也就在遇到了所对应的因缘聚合的条件下而形成了各具特色的形物了。有的万物之个体能适应因缘聚合而生的各种不同的环境条件而生，有的万物之个体不能适应因缘聚合而生的各种不同的环境条件而衹能待其适应的环境条件时而生；所以有的万物之个体也就顺势而形成了具有新特色的形体了，有的万物之个体则未能顺势形成新特色的形体而是保持了始祖的面目乃至被淘汰。为什么有的万物之个体能顺势而形成具有新特色的形体呢？那是因为它具有能顺势而生的适应性所以才形成了具有新特色的形体。为什么有的万物之个体不能顺势而形成具有新特色的形体呢？那是因为它不具有能顺势而生的适应性所以才不能形成具有新特色的形体。为什么有的万物之个体能具有顺势而生的适应性呢？那是因为它具有适应因缘聚合而生的各种不同环境条件的天性。为什么有的万物之个体不具有顺势而生的适应性呢？那是因为它不具有适应因缘聚合而生的各种不同环境条件的天性。万物原本就具有顺势而形成的具有新特色的适应性，万物原本就具有适应因缘聚合而生的各种不同环境的天性。没有哪一个万物之个体不是因为这种适应性而生，也没有哪一个万物之个体不是因为这种天性而生。所以才产生了诸如轻空的莚秆或坚实的楹柱之类的各种不同物类，才产生了诸如丑陋或美丽之类的各种不同形色，才产生了诸如中正、阴险、诡秘、古怪之类的各种不同性格，当你通达了那个道心的大用后就会明白它们都是无二无别的实相了。
万物之生命的死亡与分解的过程，就是又形成新的生命的过程；形成新的生命的过程，就是其生命的下一次死亡与分解的过程。万物根本就没有什么生与死的截然不同，或生活死的现象也衹是同时发生着的道心之大用而已；正是由于实证到了道境界的人彻底明白了或生活死的现象都是同时发生着的，所以也就没有了意识分别心地将一切行为都隐含在恰到好处的无之用中了。当一切行为都隐含在恰到好处的无之用中了的时候，才能遵循道心的全体之大用；当能遵循道心的全体之大用的时候，才能通达一切现象皆是无二无别的实相；当通达了一切现象皆是无二无别之实相的时候，才能驾驭道心的全体之大用；当驾驭了道心的全体之大用的时候，也就差不多恢复了那个道心了。遵循这个过程也就恢复那个道心了。恢复了那个道心也就凡事衹是无为地去做而不去问为什么了，这才叫作真正的道境界。被喜怒爱恶欲所驱使的心意之妄动与其内在的思辨觉知之作用是一个本原，然而却不知道此二者都是一个本原，这就叫作衹知朝四而不知暮三的猴子意识。为什么叫作衹知朝四而不知暮三的猴子意识呢？管理猴子的人给猴子餧食橡实时说：「早晨喂三个晚上喂四个。」众猴子闻之则大怒；管理猴子的人又说：「既然大家都不同意，那就还按早晨喂四个晚上喂三个的老法子。」众猴子们则闻之则大喜。名字之类的名相与名相所代表的那个实物的本性原本就没有什么不同，然而在人们的喜怒哀乐恶慾的心理作用下却变成了各种不同的理解，这就是因为那个衹知朝四而不知暮三的意识在作怪啊。所以恢复了道心的圣人们既能在外行上将各种矛盾对立的意识调节控制在中和的状态，又能在内行上安闲自在于道心大用之遍行的无二无别的精神境界中，这就叫作一个道心境界而同时有着内外两种行径的圣行。
古时候的人，他们所具足的大智慧任何地方都能无所不至啊！都是打倒了什么样的无所不至呢？凡所做出的任何行为从根本上就没有做事之动机的存在，就是具足了无所不至的大智慧的境界了，当具足了这种无所不至的大智慧后，就再也不会被喜怒爱恶欲的习气所污染了。差一点的境界则仅仅才有了做事的动机，但却没有达到「这是我的，那是你的」的私我意识；再差一点的境界也衹是有了「这是我的，那是你的」的私我意识，但却没有形成以我见而划分对错是非的唯我意识。后来我人便有了对错是非之心而且越来越严重了，于是道心也就亏失了；道心之所以亏失了，完全是心里的那个喜欢之所用所导致的。难道那个道心果真会圆满也会亏失吗，还是果真不会圆满也不会亏失呢？那个道心确实会圆满也会亏失，所以当大琴师昭氏鼓琴时便能激荡起人们心神的喜悦而造成道心之静的亏失了啊；那个道心确实不会圆满也不会亏失，所以当大琴师昭氏不鼓琴时人们的心神便恢复了道心之静的常态了。大琴师昭文的鼓琴之技艺，大乐师师旷持策以击乐器，大逻辑家惠子的诡辩之造诣，就这三个人对于各自爱好之事所达到的极其微妙的程度而言，都是各自领域里的顶尖高手，所以才能千古流传下来。由此三人在琴、诊、论上有着超乎寻常的爱好心，所以才使得在琴、诊、论的成就上大大超出了其他方面的技能；他们之所以爱好其所好的东西，其目的就是为了彻底研究明白所爱好之东西的内在机制。所爱好之东西的内在机制本来就不是靠研究所能研究明白的事反而执意地要去研究明白它，所以才犯了坚石非坚、白马非马之逻辑式的错误以至于愚昧终生。像他们那样地达到了极其微妙的程度就算是真正的最高成就了吗？那么我们每一个意识心用事的人也就可以说是成道的圣人了。像他们那样地达到了极其微妙的程度不算是真正的最高成就吗？那么万物与我人也就不会成为个别的个体了。所以，衹有这样地将那个大道的玄机深究到大生疑惑的境地才能不知不觉地过渡到恍然大悟的境界，这正是圣人所希望的啊！衹有达到了恍然大悟的境界才能没有是非对错之意识而一切行为都隐含在道心的无为之大用中，所以也就没有了意识分别心地将一切行为都隐含在恰到好处的无之用中了。
刚才已将「是非之彰也，道之所以亏也」的道理说过了，那么它与「为是不用而寓诸庸」的道理是一回事呢，还是与「为是不用而寓诸庸」的道理不是一回事呢？就以人们所认为的是一回事与不是一回事的那个认识而言，认识本身的那个思维所产生的心行就是同一回事，如此也就理解「是非之彰也，道之所以亏也」的道理与「为是不用而寓诸庸」的道理没有什么不同了。尽管如此，也需要试着将其道理说明如下。有的心行是从意识中突然产生的，有的心行是从末那识中迁流过来的，有的心行是从藏识中迁流过来的。来源于意识中的心行有的正存在着，有的已经过去了，来源于末那识的心行有的出于旧有的执着、有的出于最近才有的心得，来源于藏识中的心行乃是既没有形成执着，又没有形成心得的无为之举。心行就是这样地一会儿是从意识中产生出来，一会儿是从藏识中迁流出来，却不知道这两张心行的现象，它是不是真实的存在呢？现在用哪个会思会想的意识心反思一下自己就会发现所谓的「我」是不真实的假象了，而那个不会思不会想的道心之吾则是真实存在的了。道心之吾果真是真实的存在啊！意识心之假我果真是不真实的存在啊！
整个的天下在实相上不会比秋毫的尖头大，相形之下那有形的大山却是渺小得很；我们的寿命在实相上不会比夭折的小儿寿长，相形之下那八百寿的彭祖却是夭亡的小儿；这就证明天地与我们都是道心之大用的妙用所生，万物与我们都是一个本体而没有人我万物之别。既然天地人我万物都是一个本体的「一」而没有差别，为什么会有天地人我万物之不同的认识存在呢？既然认为它们都是一个一个的个体而有差别，又怎会没有天地人我万物之不同的认识存在呢？道之实相用言辞说出来就变成第二重的言辞之比喻象了，将道的比喻象再用言辞说出来就变成第三重的意识之妄见象了。自从道之实相变成言辞之比喻象再变成意识之妄见象以来所代代递增的妄见象，即使技术最高超的人来推算也不能计算清楚它，更何况还有以后所必然会形成的意识之妄见象呢！从道的不可言说的实相上就能变成言辞之比喻象以至于再变成意识之妄见象，更何况将意识之妄见象再变成妄见的言辞之比喻象呢！由此而知，意识之妄见再变成意识之妄见的沿流永远没有一个尽头，原因就在于妄见的沿流层出不穷。
对于那个道心的大用而言在最初并没有「这是我的，那是你的」的私我之意识，对于言辞而言却从一开始便不存在永久不变，正是因为意识之妄见的沿流永远没有一个尽头而从道心之大用中形成了人我万物的各个个体及各种思想意识了。请让我说说这些界限：有上下、尊卑之序，有亲疏之理、贵贱之仪，有剖析万物、分别彼此，有角逐胜负、对辩是非，这就是儒、墨等派所争辩的八种界限。对于宇宙之外的不可知，圣人衹是保留其说而不加以讲解；对于宇宙之内的事物，圣人衹是讲解而不加以评说；对于以天道中正为喻的《春秋》所记载的经纶天下的先王的济世之道，圣人衹是评说而不加以争辩。
由圣人的做法可知，既然有了是非对错的认识之分别，这本身就说明道心原本就是一而没有认识之分别；既然有了是非对错的争辩，这本身就说明道心原本就是一而没有争辩之实质。这证明了什么呢？证明了圣人是思虑于心，而众人是妄议于言为了将这个道理开示出来。所以告诉大家，「之所以存在着争辩的现象，乃是还没有达到内明的缘故。」真正的大道没有任何名相之称谓，真正的大辩没有任何说道之言辞，真正的大仁没有任何仁慈之目的，真正的大廉是不自需锋芒的，大勇是不自逞血气之勇的。如果还有有道的样子显现出来则恰恰证明没有道，言语过于辩察，就不能达到真理，仁者滞于一偏之爱就不能周遍，过分表示廉洁就不够真实，自逞血气之勇就不成器大勇。不称、不言、不仁、不嗛、不忮这五个方面，本来是圆通混成的；如果涉及昭、辩、常、清、忮等形迹，就变成四方之物了。所以道心之知的明了作用若能停留在衹管去做而不去动其心的境界上，那么修心的境界也就到家了。怎能又去管它什么没有言辞才是真正的论辩，不认为有道才是真正的有道呢？如果保持住了那个能知而又不去动心的境界，也就叫作修心阶段的最高成就了。衹有达到了像大海一样地诸如多少也不会满溢，舀取多少也不会枯竭，而且也不去思考为什么会这样的境界时，这才叫作包藏光亮而不露。
在过去的时候尧帝曾考问于大位的接班人舜帝说：「我真想消灭宗、脍、胥这三个屡犯边庭的小国，但是朕想到天子的责任又放不下对他们的牵挂，这个原因是什么呢？」舜帝回答说：「这三个小国的国君，竟然还能够在偏小卑微之地生存下来也真是不容易，你感到心情不怡悦。这说明了什么呢？过去曾有十个太阳同时普照大地，万物皆能普受恩惠，更何况您的道德境界胜过十个太阳的普照呢？」
啮缺问于王倪说：「先生知道万物所共同的那个根本吗？」王倪回答说：「道心之吾为什么要去知道呢！」啮缺又问道：「先生知道您那个为什么不去知道吗？」王倪回答说：「道心之吾为什么要去知道呢！」啮缺进一步问道：「那么万物是否也都是一样的什么也不去知道吗？」王倪回答道：道心之吾为什么要去知道呢！尽管如此，也需要试着将其道理说明。怎么能知道我所说的道心的大用止于「知」，也就是道心之吾的那个「知」并不是不能知道啊？道心的大用止于「知」，则正是道心之吾的那个「知」明明就在却不去知啊！现在吾且试着问于你：我们如果在潮湿的地方安歇就会腰痛乃至偏瘫，泥鳅会这样吗？我们如果在树木上安歇就会担心掉下来而心惊恐惧，猿猴会这样吗？对于人、泥鳅、猿猴这三种动物的安歇方式而言哪一种是正确的呢？我人喜欢食食草的及喂养的动物，麋鹿喜欢食草类植物，蜈蚣喜欢食蛇之类的爬行动物，鹞鹰喜欢食鼠类动物，对于人、麋鹿、蜈蚣、鹞鹰这四种动物的口味而言哪一种是正确的呢？濑猴与猴子互相吸引，狍子与鹿互相倾情，泥鳅与鱼互相交欢。毛嫱与丽姬，在我们眼里都是最具吸引力的大美女；然而鱼见了她们却恶心地躲入深水中，飞鸟见到她们却鄙视地高飞而去，麋鹿见到她们却厌恶地急速地跑走。对于猿狙、麋鹿、鳅鱼、人这四种动物的审美观点而言哪一种是正确的呢？从我们的意识心上分析，讲究仁义的开始，便是是非涂抹道心的开始，像这样互相缠绕得杂乱的意识行为，道心之吾又怎能分清仁义与是非的观念是谁对谁错呢！啮缺又问道：「看来现实您是不知道凡事对自己的利与害了，难道心身行为最完美的人也是原本就不知道凡事对自己的利与害吗？」王倪回答道：「心身行为最完美的人可就神通广大了，即使四大海都变得干涸而燃烧起来他也不会感到热，即使宇宙都冻得成冰了他也不会感到冷，即使霹雳能击破山岳、狂风能掀起海啸也不会吓着他。如果达到了这种境界的话，就能够乘云气、骑日月而逍遥地游乎环宇之内了；即使人们所认为的死生也不会改变自己的道心之大用了，更何况是人们所认为的利与害的小事呢！」
瞿鹊子问于长梧子说：我听孔子说：「圣人在对待立身处世之心身行为的培养上没有必须要如何如何的想法，既没有获取利益之心，也没有躲避害处之心，既没有必得的执着之心，也没有等待外缘具备时再去做的懒散之心，衹有心里真正达到了无所谓时才算是有了道心的成就了，若是心里有一点儿所谓的影子那就还没有真正达到道心的境界，如此才能使自己的心行既在世俗中生活又不受各种世俗之心对道心的污染。」先生您却认为这是好高骛远之言，而我却认为是最好的修道宗旨，作为得道的先生您认为咱俩的看法谁对呢？
长梧子回答说：孔子所说的境界，恰恰是轩辕皇帝毫无意识心地任由那个道心的作用慢慢地明亮后的境界，单凭听了孔丘所说的几句道理又何足以真正地知道那个境界呢！而且你也太过于听风即是雨了，似乎见到鸡蛋就得到了会即时报更的公鸡了，见到弹弓就得到了香喷喷的烤鸮了。我试着为你妄言之，你也妄听之。如何才能与日月为邻，驾驭宇宙呢，唯一的办法就是必须完全做到与孔子所说的道理相吻合，对当下的心念不管是明白地知道还是糊里糊涂都不去管它，这才能符合孔子所说的道理。不要像众人役使自己的身心为自己的欲望服劳役那样地往外求，要像圣人傻傻地待在葆光的境界里那样，如此才能参究透一万年也衹不过纯属当下的一念所变现而已；万物也都是如此，也都是以这个当下一念的作用在积蓄着生命的能量。我怎么知道喜欢活着的心理并不是内心不明之迷惑呢？我怎么知道厌恶死亡的心理并不是不害怕死亡呢？我怎么知道人们害怕死亡就像弱孩迷失在他乡而不知回归故乡呢！
丽这个地方的美女丽姬，原是丽地一个名叫「艾」的城邑之长官的女儿；晋国的国君刚选她入宫时，她不知道这是好运气来了反而吓得哭成了泪人儿，等到她到了王宫之后，没想到竟然是与国君同吃同住，而且餐餐都是食草的及喂养的动物肉，于是就后悔当初的无知而暗自落泪。从这类事上难道我们还不明白「那些怕死的人岂不应该后悔当初怕死」的无知之心理吗！夜里梦到席间饮宴娱乐的梦，第二天往往会遇到伤心而哭泣的事；夜里梦到伤心而哭泣的梦，第二天往往会遇到驰骋田猎而心旷神怡的事。当时再梦中的时候，并不知道自己是在做梦。而且还在梦中将所梦达成了真实的事，衹到醒了之后才知道那是虚幻的梦境而非真实。还有一种情况是，彻底恢复了道心之内明而后明白了夜里的梦境与白天的所作所为，它们都是非常虚幻的。然而我们未恢复道心的所有凡夫却自以为所捞到的财官名利皆是自己最聪明的结果，且暗自为自己的聪明而高兴，真不知道自己是人生的主人，还是被人生所放牧的犟牛，这可是多累劫以来所形成的根深蒂固的虚妄习气所致使的啊！孔子给你所讲的那些道理，皆都是梦话；就连我所说的「孔子给你所讲的那些道理都是梦话」的话，也同样是梦话啊！我刚才的说法，名字就叫作为了归于道用之实相而截断各种妄见的接引后学的吊诡之法。假若万世之后能够遇到一位恢复了道心的大圣人，那也是在这种接引之法的接引下，起到了早晨听了道而晚上也就明白了的作用而已。
假使我与你再论辩，如果你胜了我，那么我就胜不了你，难道你就果真对了，我就果真错了吗？如果我胜了你，那么你就胜不了我，难道我就果真对了，你就果真错了吗？无论你认为是你果真对了还是我果真对了，岂不皆证明你的认为是出于意识心的了吗？如果你认为你与我的论辩都是对的，岂不证明你与我的论辩皆是出于意识的了吗？既然你与我之间不能论辩得明白，那么我人就会一直处于自己所证得的绝非道心内明的黑暗之中，那么我人的道心又怎能通过纠正自己的虚妄性而得到恢复呢？如果用与你的见地相同的人来纠正你的虚妄性，既然与你的见地相同，又怎能纠正得了呢？如果用与我的见地相同的人来纠正你的虚妄性，既然与我的见地相同，又怎能纠正得了你呢？如果用与你我的见地皆不相同的人来纠正你的虚妄性，既然与你我的见地皆不相同，又怎能纠正你的虚妄性呢？如果用与你我的见地皆相同的人来纠正你的虚妄性，既然与你我的意见皆相同，又怎能纠正你的虚妄性呢？然而反过来看我与你，也像世人一样的都是不明白自己的人，还必须有赖于吊诡之辩才能最终明白自己啊！
怎能将极细微的起心动念控制在中和的程度呢？长梧子回答道：主观上所认定的对了，与道用上的客观事实一定是不相符的；主观上所认定的模样，与道用上的客观模样一定是相矛盾的。主观上所认定的对了，如果与道用上的客观事实是相符的，这个主观上所认定的也就达到非思维、言语所能辩的道用之实相的境界了。主观上所认定的模样，如果与道用上的客观模样是一致的，这个主观上所认定的模样也就达到非思维、言语所能辩的道用之实相的境界了。是与非纠缠在一起，如果那个审明辨知不起作用了，那就必须将起审明辨知之作用的那个极微细的起心动念时控制在中和的程度了，如果让那个极微的起心动念游衍自得，那就永远也不会恢复道心的明性而丧失审明辨知的作用了。当自己的心理上没有了时间及情义的概念时，才能像大鹏怒而飞一样地振作于不可预料的尘世生活环境中，于是也就能在各种各样的尘世生活中燕处超然了。
影子的影子问影子说：「正当我刚刚跟着你走的时候，你却突然又停了下来；正当我刚刚跟着你坐下来的时候，你却突然又站了起来；你怎么就如此地没有独立的志操呢？」影子回答说：「我后面还有一个对应地管束我的东西在如此地做吗？我后面的那个对应地管束我的东西的后面还有一个对应地管束它的东西在如此地做吗？对应的我衹是像蛇腹下的横鳞或蝉的翼一样地被动地随之而动而已吗？我怎么能知道我为什么会一会儿被这样？又怎么能知道为什么一会儿会不被这样呢？」
过去庄周我曾经梦到自己变成了蝴蝶，活灵活现的一隻真蝴蝶的燕子，当时自己心里很明白自己就是这隻蝴蝶而且非常惬意啊，已经完全不知道自己原本是庄周了；一会儿梦醒了，也就又恢复成了现实中的庄周我了。真不知道是庄周我在梦里化为了蝴蝶呢，还是蝴蝶在梦里化为了庄周我呢！对于庄周我与蝴蝶在梦中互化的现象而言，必然是在不同的心力下所产生的不同的物类及个体而已，这就是形身在心力的作用下从一个物类个体又转化为另一个物类个体的物化现象。', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf6703572034f65a9831", "shortContent": "梅尧臣于景祐元年至五年（1034—1038）任建德（今安徽东至）县令，本赋是其深入当地官港茶区考察后所作。宋初“百年无一事”的局面，造就了执政者和士大夫追求怡情雅趣的承平风气，作为闲逸生活标志的品茗之习也十分兴盛。黄儒《品茶要录·序》曰：“自国初已来，士大夫沐浴膏泽，咏歌升平之日久矣。夫体势洒落，神观冲淡，惟兹茗饮为可喜。园林亦相与摘英夸异，制卷鬻新而趋时之好，故殊绝之品始得自出于蓁莽之间，而其名...", "authors": ["赵红岩"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1fcdbb8b379ee0a14e3", "shortContent": "本文作于文与可去世一年后，苏轼发现了文氏的飞白，惊叹其艺术造诣，故而写下这篇赞文。\n飞白，是书法艺术的一种。飞白体的特点是笔画露白，似枯笔所写，具有独特的艺术魅力。本文紧紧围绕飞白的这种特点，用博喻手法，准确、生动、形象地描绘出文与可飞白的艺术造境。\n“美哉多乎，其尽万物之态也。”是总的赞美，振起文气，统领全部赞词。自“霏霏乎”至“袅袅乎”四句，以自然风物为喻，赞其走笔用墨的工力造境；“离离乎”、...", "authors": ["任国绪"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f957d0ac1145496bc81", "shortContent": "人常说：“日之所思，夜之所梦。”然而也有例外者。当今所说的“梦游症”，就是一种例外。这篇志怪小说中所写的既非梦境，又非梦游症，倒像是摄魂法一类的巫术了。小说中尚有一二疑点。诚如女伶陈嘉庆所说，陈氏并不是讨厌元某，元某也不是那种囊中羞涩的嫖客，可是元某为什么不登门造访，反而要用这种偷偷摸摸的手段呢？或许是怕有碍自己的仕途前程，或者是有意卖弄他的巫术。只是小说中的描写颇为生动，情节、细节、人物、对话一...", "authors": ["陈建生"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa6911759740c9ca3c5", "shortContent": "本篇似可分为两部分，上半篇侧重于描写一个关于古瓶的怪异故事；下半篇则是非非子的议论。其特点是描写与议论紧密结合。但通篇紧紧扣住上半篇所描述的故事，乃是从描写中生发出议论，故而并不显得空泛而离题。\n本篇语言生动简练，如写甲乙深夜发掘古冢，见没有金银财宝，只有两只古瓶、一方古砚时，作者叙述道：“甲恚甚，举畚碎其一瓶，乙曰：‘止，取此聊为养花器，不庸愈于空返乎？’因提一瓶及砚以归。”这一段寥寥数语，描写...", "authors": ["纪乃咸"], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf3036", "shortContent": "这是庄子对宇宙起源的基本认知。\n\n关于宇宙怎么起源的问题，从古至今，争论不休。基督教认为神造宇宙，神说要有光，就有了光，要有人，就造了人，如此世界形成了。这样明显是寓言性质的宇宙起源论能在西方社会中流传千年，我们实在不知道该说什么。而现代西方文化抛开创世论，试图以自然科学的方式从时间上倒溯宇宙的起源，以为一切都来自不知多少亿年前的那场宇宙大爆炸，在那场爆炸里，诞生了物质，产生了时空。若问，那之前如...", "authors": [], "pressName": "上海辞书出版社"}]', '晋·郭子玄《庄子注·齐物论》：夫自是而非彼，美己而恶人，物莫不皆然，故是非虽异而彼我均也。
南北朝·刘彦和《文心雕龙·论说》：庄周《齐物》，以「论」为名。然也。《公孙龙子》及《荀子》之中，以「论」为篇名者亦伙。
宋·王厚斋《困学纪闻》：庄子《齐物论》，非欲齐物也，盖谓物论之难齐也。
宋·林竹溪《南华真经口义·齐物论》：物论者，人物之论也，犹言「众论」也……此其立名之意也。
明·释德清《庄子内篇注·齐物论》：物论者，乃古今人物众口之辩论也。……如此，则物论不必要齐而是非自泯，了无人我是非之相，此齐物之大旨也。
清·王葵园《庄子集解》：天下之物、之言，皆可齐一视之，不必致辩守道而己。
清·刘宥斋《庄子释滞》：此篇初明万物之然，因明彼我之皆是，故曰「齐物」。
清·胡穰园《南华经合注吹影·齐物论》：物论，谓众论也；……庄子以为不若两忘而化其道也。
清·林损斋《庄子因·齐物论》：文之意中出意，言外立言，层层相生，段段回顾，倏而羊肠鸟道，倏而迭嶂重峦。……呜呼，庄叟当日下笔落想时，原不许此辈轻易读得也，又何怪焉！
清·宣茂公《南华经解·齐物论》：写地籁忽而杂奏，忽而寂收，乃衹是风作风济之故。……写天籁，更不须另说，止就地籁上提醒一笔，便陡地豁然。
清·屈见心《南华通·齐物论》：通篇大势，前半顺提，中间总锁，后半倒应，千变万化，一线穿来，如常山之蛇，击首尾应，击尾首应，击中则首尾皆应也。
今·周山《庄子解》：物论者，形开而接物以相构也，弗能齐也，以道齐也，则又入其中与相刀，惟任其不齐，而听其自己，知其所自兴，知所其自息，皆假人生之气相吹而巧为变，则见其不足与辨，而包含于始有之中……', 'indent', 1474069189, '57dc269ec4c97100611cf6a0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10243, '庄子 · 内篇 · 养生主', NULL, 199, 16, 3, 3, '庄子', NULL, 10064, '57b90297165abd0054bfdce7', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%85%BB%E7%94%9F%E4%B8%BB/7067648?fr=aladdin', '', '吾生也有涯，而知也无涯。以有涯随无涯，殆已；已而为知者，殆而已矣。为善无近名，为恶无近刑。缘督以为经，可以保身，可以全生，可以养亲，可以尽年。
庖丁为文惠君解牛，手之所触，肩之所倚，足之所履，膝之所踦，砉然向然，奏刀騞然，莫不中音。合于桑林之舞，乃中经首之会。
文惠君曰：「嘻，善哉！技盖至此乎？」
庖丁释刀对曰：「臣之所好者，道也，进乎技矣。始臣之解牛之时，所见无非全牛者。三年之后，未尝见全牛也。方今之时，臣以神遇而不以目视，官知止而神欲行。依乎天理，批大郤，导大窾，因其固然。技经肯綮之未尝，而况大軱乎！良庖岁更刀，割也；族庖月更刀，折也。今臣之刀十九年矣，所解数千牛矣，而刀刃若新发于硎。彼节者有间，而刀刃者无厚；以无厚入有间，恢恢乎其于游刃必有馀地矣，是以十九年而刀刃若新发于硎。虽然，每至于族，吾见其难为，怵然为戒，视为止，行为迟。动刀甚微，謋然以解，如土委地。提刀而立，为之四顾，为之踌躇满志，善刀而藏之。」文惠君曰：「善哉！吾闻庖丁之言，得养生焉。」
公文轩见右师而惊曰：「是何人也？恶乎介也？天与，其人与？」曰：「天也，非人也。天之生是使独也，人之貌有与也。以是知其天也，非人也。」泽雉十步一啄，百步一饮，不蕲畜乎樊中。神虽王，不善也。
老聃死，秦失吊之，三号而出。弟子曰：「非夫子之友邪？」曰：「然。」「然则吊焉若此，可乎？」曰：「然。始也吾以为其人也，而今非也。向吾入而吊焉，有老者哭之，如哭其子；少者哭之，如哭其母。彼其所以会之，必有不蕲言而言，不蕲哭而哭者，是遁天倍情，忘其所受，古者谓之遁天之刑。适来，夫子时也；适去，夫子顺也。安时而处顺，哀乐不能入也，古者谓是帝之县解。」
指穷于为薪，火传也，不知其尽也。', '《养生主》一文寓说理于故事之中，意趣横生，富于启发意义。文章在提出论点后，接着就引用「庖丁解牛」的故事加以说明，通过故事来说明道理。这既能把抽象的道理阐述得明白易懂，又避免了说理的枯燥，增强了文章的生动性和形象性。文章描写生动形象，细节刻画精细入微。耐人寻味。选自《庄子》中的《养生主》是《庄子》中的名篇，为世代人民所传颂，它为人类树起一面维护生命的大旗。', '涯：边际，极限。
知（zhì）：知识，才智。
随：追随，索求。
殆：危险，这里指疲困不堪，神伤体乏。
已：此，如此；这里指上句所说的用有限的生命索求无尽的知识的情况。
近：接近，这里含有追求、贪图的意思。
缘：顺着，遵循。
督：中，正道。中医有奇经八脉之说，所谓督脉即身背之中脉，具有总督诸阳经之作用；「缘督」就是顺从自然之中道的含意。经：常。
生：通作「性」，「全生」意思是保全天性。
养亲：养亲：从字面上讲，上下文意不能衔接，旧说称不为父母留下忧患。一说亲指精神。
尽年：终享天年，不使夭折。
庖（páo）：厨房。「庖丁」即厨师。一说「庖」指厨师，「丁」是他的名字。
为（wèi）：替，给。
文惠君：旧说指梁惠王。
解：剖开、分解。
触：接触。
倚：靠。
履：踏、踩。
踦（yǐ）：通「倚」用膝抵住。
砉（huā）然：皮肉分离的声音。
向然：多种声音相互响应的样子。向，通「响」，声响。
奏：进刀。
騞（huō）然：以刀快速割牛的声音。
中（zhòng）：合乎；「中音」，意思是合乎音乐的节奏。
桑林：传说中的殷商时代的乐曲名。「桑林之舞」意思是用桑林乐曲伴奏的舞蹈。
经首：传说中帝尧时代的乐曲名。
会：乐律，节奏。
盖：通作「盍」，讲作何，怎么的意思。一说为句中语气词，读如「盖」。
释：放下。
好（hào）：喜好。
道：事物的规律。
进：进了一层，含有超过、胜过的意思。
乎：于，比。
神：精神，心思。
官：器官，这里指眼。
知：知觉，这里指视觉。
天理：自然的纹理，这里指牛体的自然结构。
批：击。
郤（xì）：通作「隙」，这里指牛体筋腱骨骼间的空隙。
道：同「导」，循着。
窾（kuǎn）：空，这里指牛体骨节间较大的空处。
因：依，顺着。
固然：牛身体本来的结构。
技（zhī）：通作「枝」，指枝脉。
经：经脉。「技经」指经络结聚的地方。
肯：附在骨上的肉。
綮（qìng）：骨肉连接很紧的地方。
未：不曾。
尝：尝试。
軱（gū）：大骨。
岁：每年。
更（gēng）：更换。
族庖：指一般的厨师。族，众。
折：断；这里指用刀砍断骨头。
发：出，这里指刚从磨刀石上磨出来。
硎（xíng）：磨刀石。
闲（jiàn）：缝，间隙；这个意义后代写作「间」。
恢恢：宽广。游刃：运转的刀刃。
族：指骨节、筋腱聚结交错的部位。
怵（chù）然：小心谨慎的样子。
謋（huò）：牛体分解的声音。
委：散布。
踌躇：悠然自得的样子。
满志：满足了心意。
善：擦拭。
养生：其后省中心语，意思是「养生之道」。', '我的生命是有限的，而知识是无限的。以有限的生命去追求无限的知识，真是危险啊！已经有了危险，还要执着地去追求知识，那么除了危险以外就什么都已经没有了。做了世人所谓的善事却不去贪图名声，做了世人所谓的恶事却不至于面对刑戮的屈辱。以遵循虚无的自然之道为宗旨，便可以保护生命，可以保全天性，可以养护新生之机，可以享尽天年。
庖丁为文惠君宰牛，手触肩顶、足踩膝抵等各种动作，牛的骨肉分离所发出的砉砉响声，还有进刀解牛时哗啦啦的声音，都无不符合音乐的节奏，与《桑林》舞的节拍，《经首》曲的韵律相和谐。
文惠君说：「啊，妙极了！你的技术怎么会高超到这个地步？」
庖丁放下屠刀回答说：「我所爱好的是道，已经超出了技术的范围。开始我宰牛时，见到的都是整体的牛，三年之后，就再也看不见整头的牛了。现在，我宰牛时全凭心领神会，而不需要用眼睛看。视觉的作用停止了，而心神还在运行。按照牛的生理结构，把刀劈进筋骨相连的大缝隙，再在骨节的空隙处引刀而入。因为完全依照牛体的本来结构用刀，即便是经络相连、筋骨交错的地方都不会碰到，何况那大骨头呢！好的厨师一年换一把刀，因为他们用刀割；一般的厨师一个月换一把刀，因为他们是用刀砍。我的刀用到如今已经十九年了，宰过的牛也有几千头，可是刀刃还像刚开口的时候一样完好无缺。牛的骨节间有缝隙，刀刃却薄得没有厚度，用没有厚度的刀刃切入有缝隙的骨节，宽宽绰绰，刀刃的活动肯定有足够的馀地。所以这把刀用了十九年还像刚开口时一样。虽然如此，每碰到筋骨盘结的地方，我看到它很难下手，依然惶惧警惕，目光盯住此处，动作放慢。动刀虽然很轻，整条牛却哗啦一声立刻解体了，就像泥土被堆积在地上一般。我提刀站起，环顾四周，悠然自得，心满意足，然后把刀擦干净收藏起来。」
文惠君说：「好啊，我听了庖丁的这番话，懂得养生的道理了。」
公文轩看见右师而吃惊地说，「这是什么人？为什么只有一只脚？这是自然生成的，还是人为的呢？」接着又说：「这是自然生成的，不是人为的，自然造就他时就是使他只有一只脚。人的形貌都是自然所赋予的，由此可见是自然生成的，不是人为的。」
草泽中的野鸡走十步才能吃到一口食，走百步才能喝到一口水，但它并不希求被豢养在笼子里。在笼子里纵然很神气，但并不快乐。
老聃死了，秦失前去吊唁，号哭了三声就走。
弟子问：「他不是老师的朋友吗？」
回答说：「是的。」
「那么，吊丧像这样子行吗？」
秦失说：「可以。原先我以为老聃是我所认为的那个人，现在知道不是。方才我进去吊唁，有老人在哭他，像哭自己的儿子一样；有年轻人在哭他，像哭自己母亲一样。他之所以招来这样的吊唁者，必然是他自己也有不必吊唁而去吊唁，不必哭泣而哭泣的情况。这种情况是背弃自然，给世俗感情推波助澜，而忘了人的生命都受于自然。古时候称这种做法是违反自然所招致的刑罚。一个人偶然来到世间，这是他顺时而生，偶然离去了，这是他顺时而死。安于时运而顺应自然，一切哀乐之情就不能进入心怀，古时候称此为自然的解脱。」
脂膏在作为烛薪燃烧后就烧尽了。火种却传续下去，没有穷尽的时候。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d103572034f65a9ac4", "shortContent": "此文为庄子阐明“养生”的一则寓言。\n文章开始是一段惟妙惟肖的“解牛”描写。作者以浓重的笔墨，文采斐然地表现出庖丁解牛时神情之悠闲，动作之和谐。全身手、肩、足、膝并用，触、倚、踩、抵相互配合，一切都显得那么协调潇洒。“砉然响然，奏刀騞然”，声形逼真。牛的骨肉分离的声音，砍牛骨的声音，轻重有致，起伏相间，声声入耳。紧接着又用文惠君之叹：“善哉！技盖至此乎！”进一步点出庖丁解牛之“神”，这就为下文由叙转...", "authors": ["高若海"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9503572034f65b5dd7", "shortContent": "志怪小说多言神仙道术、精灵鬼怪，且多取材于民间的传说，一个故事在口口相传的过程中往往渗透了广大人民的思想意识和道德观念。生活在社会底层的劳动人民，常常把他们强烈的反抗意识和对理想的追求，借助于神鬼故事曲折地表现出来。《叶诚》就是一篇使用“曲笔”控诉统治阶级巧取豪夺的志怪小说。小说的开头说叶诚之妻耿氏常言“天下之居者、行者、耕者、桑者、交货者、歌舞者之中，人鬼各半，鬼则自知非人，而人则不识也”，这就...", "authors": ["陈建生"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa8dbb8b379ee0aecf7", "shortContent": "中国人的传统美德之一，便是品行端正、规矩守法，不图他人钱财、身外之物。刘小黑的所作所为，显然是大大地违背了通行的道德准则，所以自然不会有好下场。可如果按照常理写来，写刘小黑如何有一天东窗事发，被官兵捉拿，又如何全盘招供，被打入大狱的话，需要花费不少的笔墨；而本文则省却不必要的交代，仅仅通过因果报应等环节，简洁明了地直接揭示出偷盗行为的后果，同样对世人起到警醒劝诫的作用。殊途同归，抓住要害，而结构、...", "authors": ["欧阳云飞"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fad0f8fda556506e508", "shortContent": "这是一篇借神碗劝惩的小故事。李保全弟兄于偶然之中掘到一个古磁碗。磁碗非常神奇，盛水则现出两条红色的游鱼，还可以准确地报时辰。后来分家，弟兄几个都来争这个磁碗，原本和睦的家庭一时搞得乱糟糟的。保全母乘人不备，摔碎了这只神碗，保全了这个家庭。作者最后引《左传》二句话感叹道：“保全之母是能保全子孙哉！”\n这样的阋墙之争在财产私有的社会中，是很普遍的。上引《左传》两句话就是出于春秋虞国国君弟兄的玉璧之争，...", "authors": ["汤华泉"], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf3037", "shortContent": "如果说，《逍遥游》讲的是人生态度，大其心以入天。《齐物论》讲的是思想方法，本无一物，何须齐同。那么，《养生主》讲的则是如何来长养这本来无一物的灵妙之心了。心虽虚灵不昧，但这个物质世界却是芜杂混乱，盘根错节，于是，“以无厚入有间”，在其中游刃有余，便成了每个有志于大道者的必修之功。\n\n为此，庄子为我们讲了一个“庖丁解牛”的故事。在庖丁看来，牛的骨节虽有空隙，但他的刀刃却薄得几乎没有厚度，把没有厚度的...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1413451840, '57b90b76df0eea00633532de', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10244, '庄子 · 内篇 · 人间世', NULL, 57, 16, 2, 3, '庄子', NULL, 10064, '57b90297165abd0054bfdce7', '周', 'wen', '文', 'https://baike.baidu.com/item/%E4%BA%BA%E9%97%B4%E4%B8%96/2110596', '', '颜回见仲尼，请行。曰：“奚之？”曰：“将之卫。”曰：“奚为焉？”曰：“回闻卫君，其年壮，其行独。轻用其国而不见其过。轻用民死，死者以国量，乎泽若蕉，民其无如矣！回尝闻之夫子曰：‘治国去之，乱国就之。医门多疾。’愿以所闻思其则，庶几其国有瘳乎！”
仲尼曰：“嘻，若殆往而刑耳！夫道不欲杂，杂则多，多则扰，扰则忧，忧而不救。古之至人，先存诸己而后存诸人。所存于己者未定，何暇至于暴人之所行！且若亦知夫德之所荡而知之所为出乎哉？德荡乎名，知出乎争。名也者，相轧也；知也者争之器也。二者凶器，非所以尽行也。
且德厚信矼，未达人气；名闻不争，未达人心。而强以仁义绳墨之言术暴人之前者，是以人恶有其美也，命之曰灾人。灾人者，人必反灾之。若殆为人灾夫。
且苟为人悦贤而恶不肖，恶用而求有以异？若唯无诏，王公必将乘人而斗其捷。而目将荧之，而色将平之，口将营之，容将形之，心且成之。是以火救火，以水救水，名之曰益多。顺始无穷，若殆以不信厚言，必死于暴人之前矣！
且昔者桀杀关龙逢，纣杀王子比干，是皆修其身以下伛拊人之民，以下拂其上者也，故其君因其修以挤之。是好名者也。
昔者尧攻丛枝、胥、敖，禹攻有扈。国为虚厉，身为刑戮。其用兵不止，其求实无已，是皆求名实者也，而独不闻之乎？名实者，圣人之所不能胜也，而况若乎！虽然，若必有以也，尝以语我来。”
颜回曰：“端而虚，勉而一，则可乎？”曰：“恶！恶可！夫以阳为充孔扬，采色不定，常人之所不违，因案人之所感，以求容与其心，名之曰日渐之德不成，而况大德乎！将执而不化，外合而内不訾，其庸讵可乎！”
“然则我内直而外曲，成而上比。内直者，与天为徒。与天为徒者，知天子之与己，皆天之所子，而独以己言蕲乎而人善之，蕲乎而人不善之邪？若然者，人谓之童子，是之谓与天为徒。外曲者，与人之为徒也。擎跽曲拳，人臣之礼也。人皆为之，吾敢不为邪？为人之所为者，人亦无疵焉，是之谓与人为徒。成而上比者，与古为徒。其言虽教，谪之实也，古之有也，非吾有也。若然者，虽直而不病，是之谓与古为徒。若是则可乎？”仲尼曰：“恶！恶可！大多政法而不谍。虽固，亦无罪。虽然，止是耳矣，夫胡可以及化！犹师心者也。”
颜回曰：“吾无以进矣，敢问其方。”仲尼曰：“斋，吾将语若。有心而为之，其易邪？易之者，皞天不宜。”颜回曰：“回之家贫，唯不饮酒不茹荤者数月矣。如此则可以为心斋？”曰：“是祭祀之斋，非心斋也。”
回曰：“敢问心斋。”仲尼曰：“若一志，无听之以耳而听之以心；无听之以心而听之以气。听止于耳，心止于符。气也者，虚而待物者也。唯道集虚。虚者，心斋也。”
颜回曰：“回之未始得使，实自回也；得使之也，未始有回也，可谓虚乎？”夫子曰：“尽矣！吾语若：若能入游其樊而无感其名，入则鸣，不入则止。无门无毒，一宅而寓于不得已则几矣。绝迹易，无行地难。为人使易以伪，为天使难以伪。闻以有翼飞者矣，未闻以无翼飞者也；闻以有知知者矣，未闻以无知知者也。瞻彼阕者，虚室生白，吉祥止止。夫且不止，是之谓坐驰。夫徇耳目内通而外于心知，鬼神将来舍，而况人乎！是万物之化也，禹、舜之所纽也，伏戏、几蘧之所行终，而况散焉者乎！”
叶公子高将使于齐，问于仲尼曰：“王使诸梁也甚重。齐之待使者，盖将甚敬而不急。匹夫犹未可动也，而况诸侯乎！吾甚栗之。子常语诸梁也曰：‘凡事若小若大，寡不道以欢成。事若不成，则必有人道之患；事若成，则必有阴阳之患。若成若不成而后无患者，唯有德者能之。’吾食也执粗而不臧，爨无欲清之人。今吾朝受命而夕饮冰，我其内热与！吾未至乎事之情而既有阴阳之患矣！事若不成，必有人道之患，是两也。为人臣者不足以任之，子其有以语我来！”
仲尼曰：“天下有大戒二：其一命也，其一义也。子之爱亲，命也，不可解于心；臣之事君，义也，无适而非君也，无所逃于天地之间。是之谓大戒。是以夫事其亲者，不择地而安之，孝之至也；夫事其君者，不择事而安之，忠之盛也；自事其心者，哀乐不易施乎前，知其不可奈何而安之若命，德之至也。为人臣子者，固有所不得已。行事之情而忘其身，何暇至于悦生而恶死！夫子其行可矣！
丘请复以所闻：凡交近则必相靡以信，远则必忠之以言。言必或传之。夫传两喜两怒之言，天下之难者也。夫两喜必多溢美之言，两怒必多溢恶之言。凡溢之类妄，妄则其信之也莫，莫则传言者殃。故法言曰：‘传其常情，无传其溢言，则几乎全。’
且以巧斗力者，始乎阳，常卒乎阴，泰至则多奇巧；以礼饮酒者，始乎治，常卒乎乱，泰至则多奇乐。凡事亦然，始乎谅，常卒乎鄙；其作始也简，其将毕也必巨。言者，风波也；行者，实丧也。夫风波易以动，实丧易以危。故忿设无由，巧言偏辞。兽死不择音，气息勃然于是并生心厉。克核太至，则必有不肖之心应之而不知其然也。苟为不知其然也，孰知其所终！故法言曰：‘无迁令，无劝成。过度益也。’迁令劝成殆事。美成在久，恶成不及改，可不慎与！且夫乘物以游心，托不得已以养中，至矣。何作为报也！莫若为致命，此其难者？”
颜阖将傅卫灵公大子，而问于蘧伯玉曰；“有人于此，其德天杀。与之为无方则危吾国，与之为有方则危吾身。其知适足以知人之过，而不知其所以过。若然者，吾奈之何？”蘧伯玉曰：“善哉问乎！戒之，慎之，正女身哉！形莫若就，心莫若和。虽然，之二者有患。就不欲入，和不欲出。形就而入，且为颠为灭，为崩为蹶；心和而出，且为声为名，为妖为孽。彼且为婴儿，亦与之为婴儿；彼且为无町畦，亦与之为无町畦；彼且为无崖，亦与之为无崖；达之，入于无疵。
汝不知夫螳螂乎？怒其臂以当车辙，不知其不胜任也，是其才之美者也。戒之，慎之，积伐而美者以犯之，几矣！
汝不知夫养虎者乎？不敢以生物与之，为其杀之之怒也；不敢以全物与之，为其决之之怒也。时其饥饱，达其怒心。虎之与人异类，而媚养己者，顺也；故其杀者，逆也。
夫爱马者，以筐盛矢，以蜃盛溺。适有蚊虻仆缘，而拊之不时，则缺衔毁首碎胸。意有所至而爱有所亡。可不慎邪？”
匠石之齐，至于曲辕，见栎社树。其大蔽牛，絜之百围，其高临山十仞而后有枝，其可以舟者旁十数。观者如市，匠伯不顾，遂行不辍。弟子厌观之，走及匠石，曰：‘自吾执斧斤以随夫子，未尝见材如此其美也。先生不肯视，行不辍，何邪？”曰：“已矣，勿言之矣！散木也。以为舟则沉，以为棺椁则速腐，以为器则速毁，以为门户则液樠，以为柱则蠹，是不材之木也。无所可用，故能若是之寿。”
匠石归，栎社见梦曰：“女将恶乎比予哉？若将比予于文木邪？夫楂梨橘柚果蓏之属，实熟则剥，剥则辱。大枝折，小枝泄。此以其能苦其生者也。故不终其天年而中道夭，自掊击于世俗者也。物莫不若是。且予求无所可用久矣！几死，乃今得之，为予大用。使予也而有用，且得有此大也邪？且也若与予也皆物也，奈何哉其相物也？而几死之散人，又恶知散木！”匠石觉而诊其梦。弟子曰：“趣取无用，则为社何邪？”曰：“密！若无言！彼亦直寄焉！以为不知己者诟厉也。不为社者，且几有剪乎！且也彼其所保与众异，而以义喻之，不亦远乎！”
南伯子綦游乎商之丘，见大木焉，有异：结驷千乘，隐将芘其所藾。子綦曰：“此何木也哉！此必有异材夫！”仰而视其细枝，则拳曲而不可以为栋梁；俯而视其大根，则轴解而不可以为棺椁；舐其叶，则口烂而为伤；嗅之，则使人狂醒三日而不已。子綦曰：“此果不材之木也，以至于此其大也。嗟乎，神人以此不材。”
宋有荆氏者，宜楸柏桑。其拱把而上者，求狙猴之杙斩之；三围四围，求高名之丽者斩之；七围八围，贵人富商之家求禅傍者斩之。故未终其天年而中道之夭于斧斤，此材之患也。故解之以牛之白颡者，与豚之亢鼻者，与人有痔病者，不可以适河。此皆巫祝以知之矣，所以为不祥也。此乃神人之所以为大祥也。
支离疏者，颐隐于齐，肩高于顶，会撮指天，五管在上，两髀为胁。挫针治繲，足以糊口；鼓荚播精，足以食十人。上征武士，则支离攘臂于其间；上有大役，则支离以有常疾不受功；上与病者粟，则受三锺与十束薪。夫支离者其形者，犹足以养其身，终其天年，又况支离其德者乎！
孔子适楚，楚狂接舆游其门曰：“凤兮凤兮，何如德之衰也。来世不可待，往世不可追也。天下有道，圣人成焉；天下无道，圣人生焉。方今之时，仅免刑焉！福轻乎羽，莫之知载；祸重乎地，莫之知避。已乎，已乎！临人以德。殆乎，殆乎！画地而趋。迷阳迷阳，无伤吾行。吾行郤曲，无伤吾足。”
山木，自寇也；膏火，自煎也。桂可食，故伐之；漆可用，故割之。人皆知有用之用，而莫知无用之用也。', '《人间世》是一本记录庄子思想的一部书籍。本书的中心是讨论处世之道，既表述了庄子所主张的处人与自处的人生态度，也揭示出庄子处世的哲学观点。', '颜回：孔子的弟子，姓颜名回字子渊，鲁国人。仲尼：孔子，仲尼为字。孔子与颜回的这段谈话完全出自假托。
之：往。
独：专断。
蕉：草芥。
如：往。“无如”意思是没有归往的地方。
去：离。
就：趋赴，前往。
以：用，根据。则：准则，办法。
庶几：也许可以；含有希望的意思。瘳（chōu）：病愈，这里指国家恢复了元气。
殆：恐怕，大概。刑：遭受刑戳。
存：存立，这里指道德修养的建立。
暴人：施政暴虐的人，这里指卫国国君。
荡：丧失，毁坏。所为：讲作“……的原因”。
轧：倾轧。
矼（qiāng）：坚实、笃厚。
人气：犹言民情、民心，与下句的“人心”意思相近。“未达人气”、“未达人心”，意思是未能得到人们广泛的理解。
绳墨：喻指规矩、规范。术（术）：通作“述”。一说“术”字是“炫”字之误，卖弄的意思。
此句就上下文意看很难串通。一说“有”字乃是“育”字之误，讲作“卖”，即“鬻”的意思。其：己；三人称代词变用为己称。
命之：名之，称谓它。菑（zāi）：“灾”字的异体，“灾”字今简化为“灾”。
悦：喜好。不肖：不像，这里指不学好。
而：汝，你。
唯：只。诏：告，这里指向卫君进言。
王公：指卫君。乘：趁；“乘人”就是抓住说话人说漏了嘴的机会。一说讲作借助国君的威势。捷：形容言语快捷善辩，不让说话对方有喘息思考的机会。
荧（yíng）：眩，迷惑。
色：脸色。平：平和。
营：营救，这里指用言语自我解脱。
容：容颜、态度。形：显露，表现。
成之：以之为成，把对方的作为加以认可。
桀：夏代最后一个国君，素以暴虐称著于史。关龙逄：夏桀时代的贤臣，因直言劝谏而被夏桀杀害。
纣：商代最后一个国君，史传又一个暴君。比干：商纣王的庶出叔叔，也因力谏而被纣王杀害。
下：下位，居于臣下之位。伛（yǔ）拊（fǔ）：怜爱抚育。人：人君的省称。
拂：违反。上：居于上位的人，这里指国君。
修：美好，这里专指很有道德修养。挤：排斥。
丛枝、胥敖：帝尧时代的两个部落小国的国名。《齐物论》中有宗、脍、胥敖之称，“丛枝”疑即“宗”、“脍”，姑备参考。
有扈：古国名。
虚：墟所，这个意义后代写作“墟”。厉：人死而无后代。
实：实利。已：止。
有以：有所依凭。
以语我：把它告诉给我。来：句末语气词，表示感叹。
端：端庄、正派。虚：虚豁、谦逊。“端”指外表，“虚”指内心。
勉：勤恳努力。一：这里是始终如一，忠贞不二的意思。
恶（wū）：叹词，驳斥之声；与下句疑问代词用法的“恶”不同。
阳：指刚猛之盛气。充：满，充斥于心。孔：甚，很。扬：露于外表。
采色：这里指面部表情。“采色不定”犹言“喜怒无常”。
案：压抑，压制。
容与：放纵。
渐：浸渍，润泽。
执：固守己见。
外合：外表赞同。訾（zǐ）：非议。“不訾”意思是不愿对自己的言行作出反省。
其：那，那样。庸讵：怎么。
直：正直，光明正大。曲：弯曲，含有俯首曲就的意思。
成：成就，指心中有数，已有成熟的主张和看法。一说引用现成的话。上：上世，指古代。“上比”意思是跟古代的作法相比较。
天：自然。
所子：所养育的子女。
蕲：祈求，希望得到。善之：以之为善，把这样的言论看作是正确的。
童子：未成年的人。
擎：举，这里指手里拿着朝笏（hù）。跽：长跪。曲拳：躬身屈体。
疵（cī）：诽谤。
讁（zhé）：“谪”字的异体；谴责、责备。
病：怨恨、祸害。
大：太。政：通作“正”，端正、纠正的意思。谍：当。
固：固陋，执着而不通达。
止是：只此。耳矣：罢了。
胡：何，怎么。
师：讲作以……为师。心：这里指内心的定见。
敢：表示谦敬之词，相当于今天“斗胆地”、“冒昧地”之意。方：办法。
斋：斋戒，指祭祀前的清心洁身，这里专指清心。
有心：指怀有积极用世之心。
暤（hào）：通作“昊”，广大的意思。“暤天”就是“大天”。宜：当，合适。
茹：吃。荤：旧注指荤辛，即葱蒜之类的菜。
心斋：内心的斋戒。
一：专一。“一志”意思是凝寂虚忘，摒除杂念，心思高度专一。
气：“气”在中国古代哲学中是一极为重要的概念，指构成宇宙万物的本原。但这里是指虚以待物的心境。
“听止于耳”一句，联系下句当是“耳止于听”之误倒。
符：合。
虚：这里指纯净、空明的境界。
得使：意思是禀受了心斋的教诲。
自：疑是“有”字之误。
尽：详尽，指颜回的上述言论对于“心斋”的理解，说得十分深透。
樊：篱笆，喻指卫君统治的范围，并暗含追名逐利之场所的意思。感其名：为名利地位所动。
入：采纳进谏。
毒：通作“壔”（dǎo），累积土石用作保卫门栏的土台，喻指索求门径的标的。
一：心思高度集中。宅：这里用指心灵的位置。“一宅”意思就是心灵安于凝聚专一，全无杂念。
几：近，意思是做到了这一步就接近于大道，符合“心斋”的要求了。
无行地：行走却不践地，喻指做了什么事都不留下痕迹。
使：驱使。伪：假。
有知知者：前者读zhì，智慧、才能之意。后者读zhī，意即认识、了解。
瞻（zhān）：望。阕（què）：空虚。
虚室：空灵的精神世界。白：洁净，指什么也不存在的虚无的心理状态。
止止：意思是止于凝静的心境。
坐驰：形体坐在那里而心理却驰骋于他处。
徇：使。内通，向内通达。外：这里是排除的意思。心知：心智。
纽：枢纽，关键。
伏戏、几蘧（qú）：传说时代的远古帝王。“伏戏”多写为“伏羲”。终：到底，遵循始终。
“散焉者”指疏散的人，即普通、平常的人。
叶公子高：楚庄王玄孙尹成子，名诸梁，字子高。为楚大夫，封于叶（旧注读为shè），自僭（jiàn）为“公”，故有“叶公子高”之称。使：出使。
使诸梁：以诸梁为使。
栗：恐惧。
若：或者。
寡：少。道：由，通过。懽：“欢”字的异体，今简作“欢”。“欢成”，指圆满的结果。
人道之患：人为的祸害，指国君的惩罚。
阴：事未办成时的忧惧。阳：事已办成时的喜悦。这里是说忽忧忽喜而交集于心，势必失调以致病患。
执粗：食用粗茶淡饭。臧：好。“不臧”指不精美的食品。
爨（cuàn）：炊，烹饪食物。这句话颇费解，联系上下文大意是，烹饪食物也就无须解凉散热的人。
内热：内心烦躁和焦虑。
情：真实。
任：承担。
戒：法。“大戒”指人生足以为戒的大法。
无适而非君也：适，往、到。全句是说，天下虽大，但所到之处，没有不受国君统治的地方。
盛：极点、顶点。
自事其心：侍奉自己的心思，意思是注意培养自己的道德修养。
施（yí）：移动，影响。
靡（mō）：通作“摩”，爱抚顺从的意思。一说通作“縻”，维系的意思。“相靡以信”，用诚信相互和顺与亲近。
忠之以言：用忠实的语言相交。一说“忠”字为“怘”字之误，“怘”为固字之古体。
两喜两怒之言：两国国君或喜或怒的言辞。
溢：满，超出。“溢美之言”指过分夸赞的言辞。下句“溢恶之言”对文，指过分憎恶的话。
妄：虚假。
莫：薄。“信之以莫”意思是真实程度值得怀疑。
法言：古代的格言。
全：保全。
斗力：相互较力，犹言相互争斗。
阳：指公开地争斗。
卒：终。阴：指暗地里使计谋。
泰至：大至，达到极点。奇巧：指玩弄阴谋。
治：指合乎常理和规矩。
奇乐：放纵无度。
谅：取信，相互信任。
鄙：恶，欺诈。
实丧：得失。这句话是说，传递语言总会有得有失。
设：置，含有发作、产生的意思。
巧：虚浮不实。偏：片面的。
茀（bó）：通作“勃”；“茀然”，气息急促的样子。
厉：狠虐；“心厉”，指伤害人的恶念。
克：“克”字的异体。“克核”，即苛责。
不肖：不善，不正。
迁：改变。
劝：勉力；这里含有力不能及却勉强去做的意思。成：指办成功什么事。“劝成”，意思是勉强让人去做成某一件事。
益：添加。一说“益”就是“溢”的意思，即前面所说的“溢之类妄”的含意。
殆：危险。“殆事”犹言“坏事”。
美成：意思是美好的事情要做成功。下句“恶成”对文，意思是坏事做成了。
乘物：顺应客观事物。
中：中气，这里指神智。
作：作意。大意是何必为齐国作意其间。
为致命：原原本本地传达国君的意见。一说“命”当讲作天命，即自然的意思，则全句大意是不如顺应自然。
颜阖：鲁国的贤人。傅卫灵公大子：给卫灵公太子作师傅。大（tài）子：太子。
蘧（qú）伯玉：卫国的贤大夫，名瑗，字伯玉。
天杀：生就的凶残嗜杀。
与之：朝夕与共的意思。方：法度、规范。
其知（zhì）：他们的智慧。⑥其：“其”字的指代含意旧注指前句之有过者，认为公子自身无道，致使百姓有过，全句意思是，却不知道人们为什么出现过错。“其”字一说作反身自代讲，全句意思则是，却不知道自己为什么会出现过错。姑备参考。译文从前一说。
形：外表；与下句“心”相对文。就：靠拢，亲近。
和：顺，含有顺其本性的意思，近似于疏导的含意。
之：这。
入：关系太深。
出：超出，过于显露，与上句“入”字对文。
颠：仆倒，坠落。
崩：毁坏。蹶：失败，挫折。联系前一句，“颠”、“灭”、“崩”、“蹶”均用指“形就而入”可能造成的恶果。
为（wèi）：为了。本句两个“为”字跟上下三句的另六个“为”字含意不同，其他六个“为”字均是造成、招致的意思。
孽（niè）：灾害。
町（tīng）畦（qí）：田间的界路，喻指分界、界线。
崖：山边或岸边，“无崖”喻指无边，没有约束。
达：通达，指通过疏导与卫太子思想相通，逐步地使他走上正途。
疵：病，这里指行动上的过失。
怒：奋起。当：阻挡；这个意义后代写作“挡”，简化为“挡”。辙：车轮行过的印记。“车辙”犹言“车轮”。
是其才之美：即“以其才之美为是”，即自恃才能太高。
积：长期不断地。伐：夸耀。而：你。
几：危险。
生物：活物。
为其杀之之怒也：唯恐它扑杀活物时而诱发残杀生物的怒气。
决：裂，撕开。
达：通晓、了解。
异类：不同类。媚：喜爱。
逆：反，触犯。
矢：屎，粪便。
蜄（shèn）：大蛤，这里指蛤壳。溺：尿。
蚉：“蚊”、“虻”两字之异体，即牛虻。仆缘：附着，指叮在马身上。
拊（fǔ）：拍击。
衔：马勒口，“缺衔”指咬断了勒口。首：辔头，“毁首”指挣断了辔头。胸：胸饰，“碎胸”指弄坏了络饰。
亡：失。“意有所至”是说本意在于爱马；“爱有所亡”是说失其所爱，适得其反。
匠石：名叫“石”的匠人。之：往。
栎（lì）：树名。社：土神。“栎社树”意思是把栎树当作社神。
絜（xié）：用绳子计量周围。围：周长一尺。
临山：接近山巅。
仞：八尺。
旁：通作“方”，且：将的意思。
匠伯：即匠石。“伯”这里用指工匠之长。
辍（chuò）：中止，停。
厌：（厌）：满足，这个意义后代写作“餍”，今简化为“餍”。“厌观”意思是看了个够。
走：跑。及：赶上。
斤：斧之一种，后称“锛”，即横口斧。
已：止。“已矣”犹言“算了”。
散木：指不成材的树木。
以为：即“以之为”，把它做成。沈（chén）：同“沉”。
椁（guǒ）：“椁”字的异体，指棺外的套棺。
户：单扇的门。液：浸渍。樠（mán）：松木心；“液樠”意思是像松木心那样液出树脂。一说为一树名，其心似松。
蠹（dù）：蛀蚀。
若是之寿：像这样的长寿。
见（xiàn）：拜见。“见梦”即梦中会见。
比：比并，相提并论。“比予”即跟我相提并论。
文：纹理，这个意义后代写作“纹”。“文木”即可用之木。
柤（zhā）：楂。
蓏（luǒ）：瓜类植物的果实。属：类。
实：果实。剥：通作“攴（pō）”，用器物轻轻打落在地。
辱：屈；意思是果树摘落果实后枝干就随意受人摧残。
泄（yè）：通作“抴”；“抴”亦写作“拽”，用力拉的意思。
以：因。苦其一生：使其一生受苦。
掊（pǒu）：打。
为予大用：这里隐含有“积无用而为大用”的哲理。正因为被人们视为无用之材，所以才保全了自身，这才成就我最大的用处。
相：看待。
散人：不成材的人，相对“散木”说的。
诊：通作“畛”，告诉的意思。
趣：意趣。“趣取”就是意在求取。
为社何：意思是为什么做社树而让世人供奉。
密：默，犹言“闭嘴”。
直：通作“特”，仅只的意思。
诟厉：辱骂、伤害。
剪（jiǎn）：斩伐。
义：常理。喻：了解。
南伯子綦：人名，庄子寓言中人物。商之丘：即商丘，在今河南省，地名。
驷（sì）：一辆车套上四匹马。
芘（pí）：通作“庇”，荫庇的意思。藾（lài）：荫蔽。
拳曲：弯弯曲曲的样子。
轴：指木心。解：裂开。“轴解”意思是从木心向外裂开。一说“解”讲作“散”，指纹理松散不可用。椁：“椁”字的异体，外棺。
咶（shì）：通作“舐”，用舌舔。
酲（chéng）：酒醉。
已：止。
嗟乎：感叹声。
以：如，这个意义后代写作“似”。
荆氏：地名。
拱：两手相合。把：一手所握。
杙（yì）：小木桩，用来系牲畜的。斩：指砍伐。
围：一说指两臂合抱的长度。一说两手拇指和食指合拢起来的长度。
高名：指地位高贵名声显赫的人家。丽：通作“？”，栋，即屋之中梁。
椫（shàn）傍：指由独幅做成的棺木左右扇。
解之：指祈祷神灵以消灾。颡（shǎng）：额。亢：高；“亢鼻”指鼻孔上仰。古人以高鼻折额、毛色不纯的牲畜和痔漏的人为不洁净，因而不用于祭祀。
适：沉入河中以祭神。
巫祝：巫师。
以为：认为。
支离疏：假托的人名。“支离”隐含形体不全的意思，“疏”隐含泯灭其智的意思。
颐：下巴。脐：肚脐。
会撮：发髻。因为脊背弯曲，所以发髻朝天。
五管：五官。旧说指五脏的腧穴。
髀（bì）：股骨，这里指大腿。胁（xié）：腋下肋骨所在的部位。
针（zhēn）：“针”字的异体。“挫针”即缝衣。繲（xiè）：洗衣。
鼓：簸动。：小簸箕。播：扬去灰土与糠屑。
上：指国君、统治者。
攘（rǎng）：捋。“攘臂”指捋起衣袖伸长手臂。
以：因。常疾：残疾。功：通作“工”，指劳役之事。
钟：古代粮食计量单位，合六斛四斗。
适：往。
楚狂接舆：楚国的隐士，相传姓陆名通，接舆为字。
凤：凤鸟，这里用来比喻孔子。
何如：如何，怎么。之：往。全句大意是，怎么怀有圣德却来到这衰乱之国。一说“如”通作“尔”，全句讲作怎么你的德行衰败了。姑备参考。
有道：指顺应规律使社会得到治理。下句的“无道”则与此相反。
成：指成就了事业。
乎：于，比。
莫：不。载：取。
已矣：即“算了”。
画地：在地面上画出道路来。喻指人为的规范让人们去遵循。
迷阳：指荆棘。
郤（xì）曲：屈曲，指道路曲折难行。根据上句结构特点，“吾行郤曲”当与“迷阳迷阳”结构相同，而“吾行”很可能是传抄时误迭，则全句当是“郤曲郤曲”。
寇：侵犯，掠夺。“自寇”意思是自取砍伐。
膏：油脂。“自煎”意思是自取熔煎。
桂：树名，其皮可作香料。', '颜回拜见老师仲尼，请求同意他出远门。孔子说：“到哪里去呢？”颜回回答：“打算去卫国。”孔子说：“去卫国干什么呢？”颜回说：“我听说卫国的国君，他正年轻，办事专断；轻率地处理政事，却看不到自己的过失；轻率地役使百姓使人民大量死亡，死人遍及全国不可称数，就像大泽中的草芥一样，百姓都失去了可以归往的地方。我曾听老师说：‘治理得好的国家可以离开它。治理得不好的国家却要去到那里，就好像医生门前病人多一样’。我希望根据先生的这些教诲思考治理卫国的办法，卫国也许还可以逐步恢复元气吧！”
孔子说：“唉！你恐怕去到卫国就会遭到杀害啊！推行大道是不宜掺杂的，杂乱了就会事绪繁多，事绪繁多就会心生扰乱，心生扰乱就会产生忧患，忧患多了也就自身难保，更何况拯救国家。古时候道德修养高尚的至人，总是先使自己日臻成熟方才去扶助他人。如今在自己的道德修养方面还没有什么建树，哪里还有什么工夫到暴君那里去推行大道！
“你懂得道德毁败和智慧表露的原因吗？道德的毁败在于追求名声，智慧的表露在于争辩是非。名声是互相倾轧的原因，智慧是互相争斗的工具。二者都像是凶器，不可以将它推行于世。
“一个人虽然德行纯厚诚实笃守，可未必能和对方声气相通，一个人虽然不争名声，可未必能得到广泛的理解。而勉强把仁义和规范之类的言辞述说于暴君面前，这就好比用别人的丑行来显示自己的美德，这样的做法可以说是害人。害人的人一定会被别人所害，你这样做恐怕会遭到别人的伤害的呀！况且，假如说卫君喜好贤能而讨厌恶人，那么，哪里还用得着等待你去才有所改变？你果真去到卫国也只能是不向卫君进言，否则卫君一定会紧紧抓住你偶然说漏嘴的机会快捷地向你展开争辩。你必将眼花缭乱，而面色将佯作平和，你说话自顾不暇，容颜将被迫俯就，内心也就姑且认同卫君的所作所为了。这样做就像是用火救火，用水救水，可以称之为错上加错。有了依顺他的开始，以后顺从他的旨意便会没完没了，假如你未能取信便深深进言，那么一定会死在这位暴君面前。
“从前，夏桀杀害了敢于直谏的关龙逢，商纣王杀害了力谏的叔叔比干，这些贤臣他们都十分注重自身的道德修养而以臣下的地位抚爱人君的百姓，同时也以臣下的地位违逆了他们的国君，所以他们的国君就因为他们道德修养高尚而排斥他们、杀害了他们。这就是喜好名声的结果。当年帝尧征伐丛枝和胥敖，夏禹攻打有扈，三国的土地变成废墟，人民全都死尽，而国君自身也遭受杀戮，原因就是三国不停地使用武力，贪求别国的土地和人口。这些都是求名求利的结果，你偏偏就没有听说过吗？名声和实利，就是圣人也不可能超越，何况是你呢？虽然这样，你必定有所依凭，你就试着把它告诉我吧！”
颜回说：“我外表端庄内心虚豁，勤奋努力终始如一，这样就可以了吗？”孔子说：“唉，这怎么可以呢！卫君刚猛暴烈盛气露于言表，而且喜怒无常，人们都不敢有丝毫违背他的地方，他也借此压抑人们的真实感受和不同观点，以此来放纵他的欲望。这真可以说是每日用道德来感化都不会有成效，更何况用大德来劝导呢？他必将固守己见而不会改变，表面赞同而内心里也不会对自己的言行作出反省，你那样的想法怎么能行得通呢？”
颜回说：“如此，那我就内心秉正诚直而外表俯首曲就，内心自有主见并处处跟古代贤人作比较。内心秉正诚直，这就是与自然为同类。跟自然为同类，可知国君与自己都是上天养育的子女。又何必把自己的言论宣之于外而希望得到人们的赞同，还是希望人们不予赞同呢？象这样做，人们就会称之为未失童心，这就叫跟自然为同类。外表俯首曲就的人，是跟世人为同类。手拿朝笏躬身下拜，这是做臣子的礼节，别人都这样去做，我敢不这样做吗？做一般人臣都做的事，人们也就不会责难了吧，这就叫跟世人为同类。心有成见而上比古代贤人，是跟古人为同类。他们的言论虽然很有教益，指责世事才是真情实意。这样做自古就有，并不是从我才开始的。像这样做，虽然正直不阿却也不会受到伤害，这就叫跟古人为同类。这样做便可以了吗？”孔子说：“唉，怎么可以呢？太多的事情需要纠正，就是有所效法也会出现不当，虽然固陋而不通达也没有什么罪责。即使这样，也不过如此而已，又怎么能感化他呢！你好像是太执着于自己内心成见的人哩。”
颜回说：“我没有更好的办法了，冒昧地向老师求教方策。”孔子说：“斋戒清心，我将告诉你！如果怀着积极用世之心去做，难道是容易的吗？如果这样做也很容易的话，苍天也会认为是不适宜的。”颜回说：“我颜回家境贫穷，不饮酒浆、不吃荤食已经好几个月了，像这样，可以说是斋戒了吧？”孔子说：“这是祭祀前的所谓斋戒，并不是‘心斋。’颜回说：“我请教什么是‘心斋’。”孔子说：“你必须摒除杂念，专一心思，不用耳去听而用心去领悟，不用心去领悟而用凝寂虚无的意境去感应！耳的功用仅只在于聆听，心的功用仅只在于跟外界事物交合。凝寂虚无的心境才是虚弱柔顺而能应待宇宙万物的，只有大道才能汇集于凝寂虚无的心境。虚无空明的心境就叫做‘心斋’。”
颜回说：“我不曾禀受过‘心斋’的教诲，所以确实存在一个真实的颜回；我禀受了‘心斋’的教诲，我便顿时感到不曾有过真实的颜回。这可以叫做虚无空明的境界吗？”孔子说：“你对‘心斋’的理解实在十分透彻。我再告诉你，假如能够进入到追名逐利的环境中遨游而又不为名利地位所动，卫君能采纳你阐明你的观点，不能采纳你就停止不说，不去寻找仕途的门径，也不向世人提示索求的标的，心思凝聚全无杂念，把自己寄托于无可奈何的境域，那么就差不多合于‘心斋’的要求了。一个人不走路容易，走了路不在地上留下痕迹就很难。受世人的驱遣容易伪装，受自然的驱遣便很难作假。听说过凭借翅膀才能飞翔，不曾听说过没有翅膀也能飞翔；听说过有智慧才能了解事物，不曾听说过没有智慧也可以了解事物。看一看那空旷的环宇，空明的心境顿时独存精白，而什么也都不复存在，一切吉祥之事都消逝于凝静的境界。至此还不能凝止，这就叫形坐神驰。倘若让耳目的感观向内通达而又排除心智于外，那么鬼神将会前来归附，何况是人呢！这就是万物的变化，是禹和舜所把握的要领，也是伏羲、几蘧所遵循始终的道理，何况普通的人呢！”
叶公子高将要出使齐国，他向孔子请教：“楚王派我诸梁出使齐国，责任重大。齐国接待外来使节，总是表面恭敬而内心怠慢。平常老百姓尚且不易说服，何况是诸侯呢！我心里十分害怕。您常对我说：‘事情无论大小，很少有不通过言语的交往可以获得圆满结果的。事情如果办不成功，那么必定会受到国君惩罚；事情如果办成功了，那又一定会忧喜交集酿出病害。事情办成功或者办不成功都不会留下祸患，只有道德高尚的人才能做到。’我每天吃的都是粗糙不精美的食物，烹饪食物的人也就无须解凉散热。我今天早上接受国君诏命到了晚上就得饮用冰水，恐怕是因为我内心焦躁担忧吧！我还不曾接触到事的真情，就已经有了忧喜交加所导致的病患；事情假如真办不成，那一定还会受到国君惩罚。成与不成这两种结果，做臣子的我都不足以承担，先生你大概有什么可以教导我吧！”
孔子说：“天下有两个足以为戒的大法：一是天命，一是道义。做儿女的敬爱双亲，这是自然的天性，是无法从内心解释的；臣子侍奉国君，这是人为的道义，天地之间无论到什么地方都不会没有国君的统治，这是无法逃避的现实。这就叫做足以为戒的大法。所以侍奉双亲的人，无论什么样的境遇都要使父母安适，这是孝心的最高表现；侍奉国君的人，无论办什么样的事都要让国君放心，这是尽忠的极点。注重自我修养的人，悲哀和欢乐都不容易使他受到影响，知道世事艰难，无可奈何却又能安于处境、顺应自然，这就是道德修养的最高境界。做臣子的原本就会有不得已的事情，遇事要能把握真情并忘掉自身，哪里还顾得上眷恋人生、厌恶死亡呢！你这样去做就可以了！
“不过我还是把我所听到的道理再告诉你：不凡与邻近国家交往一定要用诚信使相互之间和顺亲近，而与远方国家交往则必定要用语言来表示相互间的忠诚。国家间交往的语言总得有人相互传递。传递两国国君喜怒的言辞，乃是天下最困难的事。两国国君喜悦的言辞必定添加了许多过分的夸赞，两国国君愤怒的言辞必定添加了许多过分的憎恶。大凡过度的话语都类似于虚构，虚构的言辞其真实程度也就值得怀疑，国君产生怀疑传达信息的使者就要遭殃。所以古代格言说：‘传达平实的言辞，不要传达过分的话语，那么也就差不多可以保全自己了’。况且以智巧相互较量的人，开始时平和开朗，后来就常常暗使计谋，达到极点时则大耍阴谋、倍生诡计。按照礼节饮酒的人，开始时规规矩矩合乎人情，到后来常常就一片混乱大失礼仪，达到极点时则荒诞淫乐、放纵无度。无论什么事情恐怕都是这样：开始时相互信任，到头来互相欺诈；开始时单纯细微，临近结束时便变得纷繁巨大。
“言语犹如风吹的水波，传达言语定会有得有失。风吹波浪容易动荡，有了得失容易出现危难。所以愤怒发作没有别的什么缘由，就是因为言辞虚浮而又片面失当。猛兽临死时什么声音都叫得出来，气息急促喘息不定，于是迸发伤人害命的恶念。大凡过分苛责，必会产生不好的念头来应付，而他自己也不知道这是怎么回事。假如做了些什么而他自己却又不知道那是怎么回事，谁还能知道他会有怎样的结果！所以古代格言说：‘不要随意改变已经下达的命令，不要勉强他人去做力不从心的事，说话过头一定是多余、添加的’。改变成命或者强人所难都是危险，成就一桩好事要经历很长的时间，坏事一旦做出悔改是来不及的。行为处世能不审慎吗！至于顺应自然而使心志自在遨游，一切都寄托于无可奈何以养蓄神智，这就是最好的办法。有什么必要作意回报！不如原原本本地传达国君所给的使命，这样做有什么困难呢！”
颜阖[3]将被请去做卫国太子的师傅，他向卫国贤大夫蘧伯玉求教：“如今有这样一个人，他的德行生就凶残嗜杀。跟他朝夕与共如果不符合法度与规范，势必危害自己的国家；如果合乎法度和规范，那又会危害自身。他的智慧足以了解别人的过失，却不了解别人为什么会出现过错。像这样的情况，我将怎么办呢？”
蘧伯玉说：“问得好啊！要警惕，要谨慎，首先要端正你自己！表面上不如顺从依就以示亲近，内心里不如顺其秉性暗暗疏导。即使这样，这两种态度仍有隐患。亲附他不要关系过密，疏导他不要心意太露。外表亲附到关系过密，会招致颠仆毁灭，招致崩溃失败。内心顺性疏导显得太露，将被认为是为了名声，也会招致祸害。他如果像个天真的孩子一样，你也姑且跟他一样像个无知无识的孩子；他如果同你不分界线，那你也就跟他不分界线。他如果跟你无拘无束，那么你也姑且跟他一样无拘无束。慢慢地将他思想疏通引入正轨，便可进一步达到没有过错的地步。
你不了解那螳螂吗？奋起它的臂膀去阻挡滚动的车轮，不明白自己的力量全然不能胜任，还自以为才高智盛很有力量。警惕呀，谨慎呀！经常夸耀自己的才智而触犯了他，就危险了！你不了解那养虎的人吗？他从不敢用活物去喂养老虎，因为他担心扑杀活物会激起老虎凶残的怒气；他也从不敢用整个的动物去喂养老虎，因为他担心撕裂动物也会诱发老虎凶残的怒气。知道老虎饥饱的时刻，通晓老虎暴戾凶残的秉性。老虎与人不同类却向饲养人摇尾乞怜，原因就是养老虎的人能顺应老虎的性子，而那些遭到虐杀的人，是因为触犯了老虎的性情。
爱马的人，以精细的竹筐装马粪，用珍贵的蛤壳接马尿。刚巧一只牛虻叮在马身上，爱马之人出于爱惜随手拍击，没想到马儿受惊便咬断勒口、挣断辔头、弄坏胸络。意在爱马却失其所爱，能够不谨慎吗！”
匠人石去齐国，来到曲辕这个地方，看见一棵被世人当作神社的栎树。这棵栎树树冠大到可以遮蔽数千头牛，用绳子绕着量一量树干，足有头十丈粗，树梢高临山巅，离地面八十尺处方才分枝，用它来造船可造十余艘。观赏的人群像赶集似地涌来涌去，而这位匠人连瞧也不瞧一眼，不停步地往前走。他的徒弟站在树旁看了个够，跑着赶上了匠人石，说：“自我拿起刀斧跟随先生，从不曾见过这样壮美的树木。可是先生却不肯看一眼，不住脚地往前走，为什么呢？”匠人石回答说：“算了，不要再说它了！这是一棵什么用处也没有的树，用它做成船定会沉没，用它做成棺椁定会很快朽烂，用它做成器皿定会很快毁坏，用它做成屋门定会流脂而不合缝，用它做成屋柱定会被虫蛀蚀。这是不能取材的树。没有什么用处，所以它才能有如此寿延。”
匠人石回到家里，梦见社树对他说：“你将用什么东西跟我相提并论呢？你打算拿可用之木来跟我相比吗？那楂、梨、橘、柚都属于果树，果实成熟就会被打落在地，打落果子以后枝干也就会遭受摧残，大的枝干被折断，小的枝丫被拽下来。这就是因为它们能结出鲜美果实才苦了自己的一生，所以常常不能终享天年而半途夭折，自身招来了世俗人们的打击。各种事物莫不如此。而且我寻求没有什么用处的办法已经很久很久了，几乎被砍死，这才保全住性命，无用也就成就了我最大的用处。假如我果真是有用，还能够获得延年益寿这一最大的用处吗？况且你和我都是‘物’，你这样看待事物怎么可以呢？你不过是几近死亡的没有用处的人，又怎么会真正懂得没有用处的树木呢！”
匠人石醒来后把梦中的情况告诉给他的弟子。弟子说：“旨意在于求取无用，那么又做什么社树让世人瞻仰呢？”匠人石说：“闭嘴，别说了！它只不过是在寄托罢了，反而招致不了解自己的人的辱骂和伤害。如果它不做社树的话，它还不遭到砍伐吗？况且它用来保全自己的办法与众不同，而用常理来了解它，可不就相去太远了吗！”
南伯子綦[4]在商丘一带游乐，看见长着一棵出奇的大树，上千辆驾着四马的大车，荫蔽在大树树荫下歇息。子綦说：“这是什么树呢？这树一定有特异的材质啊！”仰头观看大树的树枝，弯弯扭扭的树枝并不可以用来做栋梁；低头观看大树的主干，树心直到表皮旋着裂口并不可以用来做棺椁；用舌舔一舔树叶，口舌溃烂受伤；用鼻闻一闻气味，使人像喝多了酒，三天三夜还醒不过来。
子綦说：“这果真是什么用处也没有的树木，以至长到这么高大。唉，精神世界完全超脱物外的‘神人’，就像这不成材的树木呢！”宋国有个叫荆氏的地方，很适合楸树、柏树、桑树的生长。树干长到一两把粗，做系猴子的木桩的人便把树木砍去；树干长到三、四围粗，地位高贵名声显赫的人家寻求建屋的大梁便把树木砍去；树干长到七、八围粗，达官贵人富家商贾寻找整幅的棺木又把树木砍去。所以它们始终不能终享天年，而是半道上被刀斧砍伐而短命。这就是材质有用带来的祸患。因此古人祈祷神灵消除灾害，总不把白色额头的牛、高鼻折额的猪以及患有痔漏疾病的人沉入河中去用作祭奠。这些情况巫师全都了解，认为他们都是很不吉祥的。不过这正是“神人”所认为的世上最大的吉祥。
有个名叫支离疏的人，下巴隐藏在肚脐下，双肩高于头顶，后脑下的发髻指向天空，五官的出口也都向上，两条大腿和两边的胸肋并生在一起。他给人缝衣浆洗，足够？口度日；又替人筛糠簸米，足可养活十口人。国君征兵时，支离疏捋袖扬臂在征兵人面前走来走去；国君有大的差役，支离疏因身有残疾而免除劳役；国君向残疾人赈济米粟，支离疏还领得三钟粮食十捆柴草。像支离疏那样形体残缺不全的人，还足以养活自己，终享天年，又何况像形体残缺不全那样的德行呢！
孔子去到楚国，楚国隐士接舆有意来到孔子门前，说“凤鸟啊，凤鸟啊！你怎么怀有大德却来到这衰败的国家！未来的世界不可期待，过去的时日无法追回。天下得到了治理，圣人便成就了事业；国君昏暗天下混乱，圣人也只得顺应潮流苟全生存。当今这个时代，怕就只能免遭刑辱。幸福比羽毛还轻，而不知道怎么取得；祸患比大地还重，而不知道怎么回避。算了吧，算了吧！不要在人前宣扬你的德行！危险啊，危险啊！人为地划出一条道路让人们去遵循！遍地的荆棘啊，不要妨碍我的行走！曲曲弯弯的道路啊，不要伤害我的双脚！”
山上的树木皆因材质可用而自身招致砍伐，油脂燃起烛火皆因可以燃烧照明而自取熔煎。桂树皮芳香可以食用，因而遭到砍伐，树漆因为可以派上用场，所以遭受刀斧割裂。人们都知道有用的用处，却不懂得无用的更大用处。', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf67c6e67846a9219e0c", "shortContent": "古赋咏物，自魏晋以降，好明“物理”，如张华《鹪鹩赋》以小喻大，知微见著，于是微虫、细禽、小兽，纷呈笔端；宋人好理，诗文辞赋无不崇尚义理之学，以至借物以骋发议论，也成为赋家的常用方法，王氏兹赋，即具当时赋家咏物的典范意义。\n赋咏尺蠖，乃飞蛾之幼虫，却为赋者钟爱，其间内涵，又当追溯古代咏物之两大传统：一则屈子，倡导如“千里马”“凤雏”般神奇而伟大的传统；一则庄子，关注于如“鹪鹩”等平庸却知性的传统。王...", "authors": ["许", "结", "赵元皓"], "pressName": "上海辞书出版社"}, {"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf69c6e67846a9219e14", "shortContent": "刘子翚是南宋著名的理学家，一代尊师朱熹的启蒙老师。刘子翚的诗文赋具有鲜明的理学色彩，但又不堕于理窟而流于枯涩，尤其散文、辞赋，无论叙事，抑或论理，常常采用比喻、寓言等艺术手法，化抽象为具体，化深奥于明晓，借此充实其文章之艺术美感。钱锺书曾在《宋诗选注》中赞扬刘子翚是宋代“诗人里的一位道学家，并非只在道学家里充个诗人”的人，“他沾染‘讲义语录’的习气最少，就是讲心理学、伦理学的时候，也能够用鲜明的比...", "authors": ["漆子扬"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1dd2cee9a0c24edae49", "shortContent": "作者傅玄少孤贫，性刚劲亮直，不能容人之短，在仕途上累受压抑，两次因小故与人争，被免官。因而他对像马钧这样具有发明创造的人才受到压抑，能表示痛惜之情，并为他撰写了《马钧传》。\n马钧是个大发明家，在科技发明上是与张衡并称的，连道家葛洪的《抱朴子》也记载了他是“木圣”这一事实：“故张衡、马钧于今有木圣之名焉。”（《辨问》）可见马钧在当时极受尊重。\n傅玄生长在老庄盛行，士大夫放纵形骸的时代，独能注意科学生...", "authors": ["龙", "晦"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1ee0f8fda55650615b6", "shortContent": "古文中有说、论二体，二者性质相近，而又有所区别。论，着重在论理；说，着重在说明、申释。明人吴讷在《文章辨体序说》中称：“说者，释也，述也，解释义理而以己意述之也。”一般说来，称之为“说”的文章，往往带有某些杂文、杂感性质，或论述一得之见，或抒发内心感触，如韩愈的《杂说》、苏轼的《日喻说》等。本文题为《说骥》，也属于这类。\n文章分前后两部分。前一部分重在叙事，叙述了得马、售马、相马，善养马和果得良马...", "authors": ["程郁缀"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1f37d0ac1145495f916", "shortContent": "本文选自罗隐的《谗书》。《谗书》是罗隐抒写杂感的小品文集，编成于唐懿宗咸通八年（867）正月。其自序云：“有可以谗者则谗之，亦多言之一派也。而今而后，有诮予以谗自矜者，则对曰：‘不能学扬子云寂寞以诳人。’”鲁迅曾说：“罗隐的《谗书》，几乎全部是抗争和愤激之谈。”（《南腔北调集·小品文的危机》）\n这篇《英雄之言》，推衍《庄子·胠箧》“窃钩者诛，窃国者为诸侯”的论点，进一步指出以救民为号召的英雄们，其...", "authors": ["徐应佩"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed2035914587d02f5a093", "shortContent": "刘基在元末归隐期间，曾数次游览会稽山水，这篇游记是他第二次游览会稽山时写的第一篇作品。\n文章开头，先从雨风露雷写起，用简练而又准确的语言辨析风和雨露雷的异同。四者“皆出乎天”，生成于自然，但风“无形而有声”，不同于雨露而同于雷。可是，它“不能自为声”，需“附于物而有声”，又不同于“訇磕于虚无之中”的“雷之怒号”。在对比辨析中，风的特征已了然在目。然后紧扣题目中的“风”字，写其种种情状。首先，风之为...", "authors": ["臧维熙", "张", "璟"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed2082e6a6b501f9685db", "shortContent": "园林，作为“人化的自然”，是人与自然共同创造的审美的家园，诗意的栖居地。祁彪佳此文，就是对这种充满痛苦与狂喜、痴情与逸趣、意匠与灵感的独特的创造过程的描写。他带领读者进入创造过程，进入他的性灵世界，一起享受审美创造的愉悦。\n是经过风尘人寰、沧桑世事的洗礼，才对“委置于丛篁灌莽中”的小山“若有感触焉”的。“感触”什么？“二十年前情事”确是美好的，“捧土作婴儿戏”的天真在“引疾南归”后忆起，显然是别有...", "authors": ["骆冬青"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f855e272d4b2255c1e4", "shortContent": "《补江总白猿传》是《新唐书·艺文志》所著录的三篇单篇传奇文之一，其实它的内容更接近于志怪。它叙述梁将欧阳纥随军南征，其美貌的妻子被白猿精所窃，藏于深山，后经过艰难寻找，终于刺杀白猿，夺回妻子。早在汉代，焦氏《易林》中就已有“南山大玃，盗我媚妾。怯不敢逐，退然独宿”的传说。西晋张华《博物志》中更有猕猴盗美妇，产子如人一类记载。《补江总白猿传》在上述传说基础上推衍想象，构成一个情节完整的故事。小说中的...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f890f8fda556506e460", "shortContent": "说理记事之文，应力求通畅明白，但奇僻荒诞的志怪之作，则往往需要制造扑朔迷离的境界，使读者初起如堕五里雾中，最后方或明或暗地点醒之，令人重见天日，心开神释，骨飞眉舞。《胡志忠》可以说是深得其三昧的一篇。\n开篇，作者极简单地介绍了胡志忠的服役处所、职务和新接使命，后迅疾地引入“夜梦一物，犬首人质”，提出“某不食岁余”的陈述和止其馆时“能减所食见沾乎”的请求，以及“忠梦中不诺”的态度。不是梦亲朋故旧，不...", "authors": ["何均地"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9403048e64fbda97d5", "shortContent": "“五通神”，在志怪小说中是专门摧残女性的坏家伙，本文中却被作者“借”来嘲弄贪婪狡黠的沈一。沈一，本为城里的酒店老板，又在城外承包丰乐楼酒库。宋代税酒，在京都及州府城内实行官卖，城外及县镇乡闾则由民间承办自酿，实行包税。南宋以来，为了加紧搜刮民脂，任人加价竞争，承办包税，这种做法就叫“扑买”。沈某显然是一好利之徒，于城中开酒肆尚不满足，又在城外承包，每日监沽，至日暮方回。这种贪婪的个性注定了他不肯放...", "authors": ["陈建生"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9b7d0ac1145496bca1", "shortContent": "这则故事讲的是一个养鸽爱好者的一次奇遇，情节很生动，寓意也很深刻。\n故事中那位张公子可算得上是一个“高级鸽迷”，他不但养鸽成癖，而且精于此道。“按经而求，务尽其种。”竟然想把鸽的所有名贵品种搜罗齐全。其爱好的程度，于此可见一斑。“其养之也，如保婴儿。”他养鸽的方法十分细致，冷了该怎么样，热了该怎么样，“睡太甚”又该怎么样，他都有一套办法，真正做到精心调理。因此，张公子好鸽之名传遍遐迩，成了齐鲁一带...", "authors": ["范民声"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9d0ce818559d071265", "shortContent": "关于《黄英》，因其为《聊斋》名篇，人们对它的思想性和艺术性，已经说得很多很多了。我们这里只拈出一个问题作些新的探讨，这就是我国古代的商品经济意识问题。\n一般的看法，认为中国古代一向重农轻商，尚本抑末，因而人们的商品经济意识淡薄。所谓：“士农工商”，士居其首，农亦在工商之上。这个说法，有符合实际情况的一面，但也未免笼统、含混。我们只要去翻翻《史记》中的《货殖列传》，就不难感受到汉代人商品经济意识并不...", "authors": ["王星琦", "王雪盼"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9e5e272d4b2255c263", "shortContent": "高二不过是个逻卒，根本说不上什么官，却可以凭此身份胡作非为，乃至奸淫妇女。\n高二的好色，给了母猪精以可乘之机。一个是有意栽花，想借此达到“转轮为人”的目的；一个是无心插柳，只是因“内诈”而将母猪精“片言解脱”。其实，“得人好处，与人消灾”，也是有传统的。许多并非“人类”的变成“人”，都是因为主事者得到了这样那样的好处。高二行为的后果看似偶然，实际上却有必然的因素在内。\n搞不懂的，似乎只有外史氏，他...", "authors": ["全岳春"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9e2cee9a0c24ee7981", "shortContent": "这是一篇“色诫”。不过它的正文与“外史氏曰”部分的主题有所不同。\n空上人指点迷津的杰作——画廊，一言以贯之，就是“女人是祸水”。廊上所画的女性，也确是让人望而生畏。你看，把少年男子绑在铜柱上用刀挖其心肝，摔在火床上用烙铁烫其手脚……真是可怖之极，惨不忍睹。那样的女人，谁敢领教？然而那只是空上人大彻大悟后的“明白画”，作为“祸水”的女人在人世间并非如此真相毕露。空上人的三世经历就说明了这一点。上人三...", "authors": ["全岳春"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa1c6e67846a9226e19", "shortContent": "《道士剖丽女心》记叙道士受额都统干扰、斩妖不成的故事，并借道士之口，阐述了放纵恶物贻患无穷的道理，从而凸显出对贪官污吏不能宽容的主旨。\n故事开头真是骇人听闻。一个道士竟要剖一个美女的心！这实在不可思议。读者的确也要像额都统那样扬起马鞭急急驰去扼住道士的手，喝令他：“刀下留人！”可是，作者笔锋陡转，那美女竟“噭然一声，化火光飞去”。读者不禁愕然。惊愕之余，也似乎要问个究竟。但作者没有顺应读者的探奇心...", "authors": ["钟林斌"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa403048e64fbda9830", "shortContent": "本文旨在赞美鲁卞夫微雕技艺精湛，已达到出神入化、感天地泣鬼神的地步。作为艺术组成部分的微雕，在我国源远流长，至明清则登向高峰。明代擅长以橄榄、胡桃、樱桃之核雕刻，夏白眼、邱山、王毅、邢献之等辈，都曾名闻艺坛。清代竹刻名家封锡禄、封锡章兄弟亦尝擅刻胡桃核舟，其高超技艺，尤为文人墨客赞赏不绝。故而赞其技艺之文，诸如宋起凤《核工记》、魏学洢《核舟记》、高士奇《记核桃念珠》以及陈贞慧《秋园杂佩》、李日华《...", "authors": ["徐振贵", "王宪昭"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa50ce818559d071284", "shortContent": "夫妻口角，丈夫怒而离家，鬼物冒充其夫上床就寝，幸被妻子识破，鬼物惧而遁去。众人说：“夫妇不和，故鬼物乘其隙也。”这句话很好地概括了这一故事所包含的教益。夫妻口角，本是极平常之事。只要互相宽容谅解，心平气和地交换意见，消除误会，矛盾并不难解决。可是那位丈夫却“怒而出”，“寄宿他所”，结果给鬼物造成了可乘之机，险些造成难以设想的后果。家和万事兴，夫妻和睦，才能有家庭的幸福和兴旺。\n故事情节极为简单，但...", "authors": ["许金榜"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa9c6e67846a9226f1a", "shortContent": "“祝由”是古代一种迷信治病方法。其法为巫医向鬼神祷告，祝说病由，而后将鬼神的旨意传达给病人，病人只要遵旨去做，痛苦便可解除。《素问·移情变气论》唐王冰注谓“祝说病由，不劳针石而已”。宋淳熙《秘藏医书》记载有“祝由科”。元明太医院也有祝由科。这篇小说所写的祝由科，专治金枪及跌打而死者，实际上是祝由科的一个分支。\n小说突出地刻画了陈客法术之神。事故的发生，纯属偶然。刀尖直刺受害者之脑，使其立即倒地而卧...", "authors": ["赵山林"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fabdbb8b379ee0aed09", "shortContent": "在封建社会中，仕途经济是读书人唯一的出路。十年寒窗，囊萤映雪，刻苦用功，一旦在科举考试中占得鳌头，则立即身登龙门，夫荣妻贵。本篇通过一只狐精与一个士人之间喋喋不休的争论，辛辣地讽刺了科举制度下的读书人，在功名利禄面前患得患失、歌哭无常的种种丑态。\n本篇中的狐精，实质上就是科举制度下读书人的真实写照。\n故事中的狐精与浙生都各执一词，“剌剌强辩”，所谓“当局者迷，旁观者清”，作者为我们安排了一位旁观者...", "authors": ["储有明"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3faa5e272d4b2255c2a4", "shortContent": "本篇叙述了一个幻化成美女媚人，使受害者生命垂危的蛇魅，最后终于被狐仙降服的故事，从而告诫青年人，不要和萍水相逢的异性发生不正当的关系，以免招来杀身之祸。全文可分为三个层次，第一层次写蛇为祟，第二层次写人降狐，第三个层次写狐伏妖。\n先看第一个层次：蛇为祟。\n刘生供职的地方，其周围都是农家。一个偶然的机缘，他在村外见到一个“其貌袅娜”，穿着打扮不像农家女的年轻女子。惊讶之余他用调笑的言辞去挑逗这位时髦...", "authors": ["储有明"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fab03048e64fbda9859", "shortContent": "这是一篇讽刺性的志怪小说，它通过“素以操行自许”的书生马宏谟以说大话开始，以丑行败露而结尾，辛辣地鞭挞了当时社会中某些儒士的伪君子嘴脸。\n这篇志怪小说的真正思想意义在于它对假道学的批判，对人类本性的肯定。饮食男女，本来是很正常的事情，是人类本能的反映，但是，自从儒家兴起，尤其是宋明理学形成之后，道学家便视男女之事为禁区。道学先生们一方面允许皇帝有三宫六院七十二妃三千宫女，大规模地占有妇女，允许达官...", "authors": ["陈云发", "周美旭"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fab7d0ac1145496bcf9", "shortContent": "本篇通过一匹能“作人语”的马，控诉了一些具有“虐畜狂”的人“毒挞”、“痛鞭”牲畜的恶劣行径。\n马会开口说话，这在英国小说家斯威夫特的《格列佛游记》中倒是有之的，但在现实生活中则恐怕是不可思议的。所以，作者在评语中也说这件事“终近于虚诞”。\n但是，若把这则故事看作是一篇寓言的话，那么，它所蕴蓄的深层意义倒是颇为发人深省的。\n俗话说“阎王好见，小鬼难当”。有时候，一些当官的还能关心民瘼，体察下情，而那...", "authors": ["储有明"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fad2cee9a0c24ee7b00", "shortContent": "《聊斋志异》中，有名篇曰《聂小倩》，谓女鬼聂小倩，专媚人，人为其所惑者，入夜则被吸尽体血而死。后小倩逢书生宁采臣，此乃一铮铮铁汉子，小倩百计诱之不得，终于折服，其后亦得还魂，与宁生成眷属云云。这一篇《萧补烟》，与《聂小倩》有异曲同工之妙，殆作者有感于《聊斋》，反其意而作之哉？\n始观萧补烟之为人，与宁生似甚相似，且又有大见识，为宁生所无者：其一则弃科举，不求仕进，其淡泊可敬也；其二则于“后嗣”无挂于...", "authors": ["沈维藩"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42afc6e67846a9227bfe", "shortContent": "《心坚金石传》选自陶辅《花影集》卷三。嘉靖二年（1523）作者自撰《花影集·引》称，此书系继《剪灯新话》《剪灯余话》《效颦集》后，“较三家得失之端，约繁补略”而作。《心坚金石传》就是其中最杰出的一篇。\n《心坚金石传》是一篇爱情传奇小说。叙元代前至元年间（1264—1294），松江府书生李彦直与名妓张丽容一对心坚如金石的恋人，被强权势力拆散身死的悲剧故事。小说热情讴歌了李、张二人不畏强暴、生死不渝的...", "authors": ["侯忠义"], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf3038", "shortContent": "北京奥运会上，中国提出了一个令全世界振奋的口号———“同一个世界，同一个梦想”，充分表达了中国欲融入世界大家庭的愿望。不过，如果当时有一个中国古人穿越回来，坐在看台，细审这个口号，恐怕会觉得有点问题：我们真的跟他人同在一个世界，共做同一个梦么？\n\n在中国古人看来，绝对不是这么回事，他们认为，每个人都有自己独立的“心斋”。\n\n跟世界上其他的文明古国一样，中国古代也有着极为丰厚的祭祀文化，这种文化直到...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1524824442, '57ea0e74bf22ec0058825dc1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10245, '庄子 · 内篇 · 德充符', NULL, 8, 16, 0, 1, '庄子', NULL, 10064, '57b90297165abd0054bfdce7', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BE%B7%E5%85%85%E7%AC%A6/1662741', '', '鲁有兀者王骀，从之游者与仲尼相若。
常季问于仲尼曰：“王骀，兀者也，从之游者与夫子中分鲁。立不教，坐不议。虚而往，实而归。固有不言之教，无形而心成者邪？是何人也？”
仲尼曰：“夫子，圣人也，丘也直后而未往耳！丘将以为师，而况不若丘者乎！奚假鲁国，丘将引天下而与从之。”
常季曰：“彼兀者也，而王先生，其与庸亦远矣。若然者，其用心也，独若之何？”
仲尼曰：“死生亦大矣，而不得与之变；虽天地覆坠，亦将不与之遗；审乎无假而不与物迁，命物之化而守其宗也。”
常季曰：“何谓也？”
仲尼曰：“自其异者视之，肝胆楚越也；自其同者视之，万物皆一也。夫若然者，且不知耳目之所宜，而游心乎德之和。物视其所一而不见其所丧，视丧其足犹遗土也。”
常季曰：“彼为己，以其知得其心，以其心得其常心。物何为最之哉？”
仲尼曰：“人莫鉴于流水而鉴于止水。唯止能止众止。受命于地，唯松柏独也正，在冬夏青青；受命于天，唯尧、舜独也正，在万物之首。幸能正生，以正众生。夫保始之徵，不惧之实，勇士一人，雄入于九军。将求名而能自要者而犹若是，而况官天地、府万物、直寓六骸、象耳目、一知之所知而心未尝死者乎！彼且择日而登假，人则从是也。彼且何肯以物为事乎！”
申徒嘉，兀者也，而与郑子产同师于伯昏无人。子产谓申徒嘉曰：“我先出则子止，子先出则我止。”其明日，又与合堂同席而坐。子产谓申徒嘉曰：“我先出则子止，子先出则我止。今我将出，子可以止乎？其未邪？且子见执政而不违，子齐执政乎？”
申徒嘉曰：“先生之门固有执政焉如此哉？子而说子之执政而后人者也。闻之曰：‘鉴明则尘垢不止，止则不明也。久与贤人处则无过。’今子之所取大者，先生也，而犹出言若是，不亦过乎！”
子产曰：“子既若是矣，犹与尧争善。计子之德，不足以自反邪？”
申徒嘉曰：“自状其过以不当亡者众；不状其过以不当存者寡。知不可奈何而安之若命，唯有德者能之。游于羿之彀中。中央者，中地也；然而不中者，命也。人以其全足笑吾不全足者众矣，我怫然而怒，而适先生之所，则废然而反。不知先生之洗我以善邪？吾之自寐邪？吾与夫子游十九年，而未尝知吾兀者也。今子与我游于形骸之内，而子索我于形骸之外，不亦过乎！”
子产蹴然改容更貌曰：“子无乃称！”
鲁有兀者叔山无趾，踵见仲尼。
仲尼曰：“子不谨，前既犯患若是矣。虽今来，何及矣！”
无趾曰：“吾唯不知务而轻用吾身，吾是以亡足。今吾来也，犹有尊足者存，吾是以务全之也。夫天无不覆，地无不载，吾以夫子为天地，安知夫子之犹若是也！”
孔子曰：“丘则陋矣！夫子胡不入乎？请讲以所闻。”无趾出。孔子曰：“弟子勉之！夫无趾，兀者也，犹务学以复补前行之恶，而况全德之人乎！”
无趾语老聃曰：“孔丘之于至人，其未邪？彼何宾宾以学子为？彼且以蕲以諔诡幻怪之名闻，不知至人之以是为己桎梏邪？”
老聃曰：“胡不直使彼以死生为一条，以可不可为一贯者，解其桎梏，其可乎？”
无趾曰：“天刑之，安可解！”
鲁哀公问于仲尼曰：“卫有恶人焉，曰哀骀它。丈夫与之处者，思而不能去也；妇人见之，请于父母曰：‘与为人妻，宁为夫子妾’者，数十而未止也。未尝有闻其唱者也，常和人而已矣。无君人之位以济乎人之死，无聚禄以望人之腹，又以恶骇天下，和而不唱，知不出乎四域，且而雌雄合乎前，是必有异乎人者也。寡人召而观之，果以恶骇天下。与寡人处，不至以月数，而寡人有意乎其为人也；不至乎期年，而寡人信之。国无宰，而寡人传国焉。闷然而后应，氾而若辞。寡人丑乎，卒授之国。无几何也，去寡人而行。寡人恤焉若有亡也，若无与乐是国也。是何人者也！”
仲尼曰：“丘也尝使于楚矣，适见豚子食于其死母者。少焉眴若，皆弃之而走。不见己焉尔，不得其类焉尔。所爱其母者，非爱其形也，爱使其形者也。战而死者，其人之葬也不以翣资；刖者之屡，无为爱之。皆无其本矣。为天子之诸御：不爪剪，不穿耳；取妻者止于外，不得复使。形全犹足以为尔，而况全德之人乎！今哀骀它未言而信，无功而亲，使人授己国，唯恐其不受也，是必才全而德不形者也。”
哀公曰：“何谓才全？”
仲尼曰：“死生、存亡、穷达、贫富、贤与不肖、毁誉、饥渴、寒暑，是事之变、命之行也。日夜相代乎前，而知不能规乎其始者也。故不足以滑和，不可入于灵府。使之和豫，通而不失于兑。使日夜无隙，而与物为春，是接而生时于心者也。是之谓才全。”
“何谓德不形？”
曰：“平者，水停之盛也。其可以为法也，内保之而外不荡也。德者，成和之修也。德不形者，物不能离也。”
哀公异日以告闵子曰：“始也吾以南面而君天下，执民之纪而忧其死，吾自以为至通矣。今吾闻至人之言，恐吾无其实，轻用吾身而亡吾国。吾与孔丘非君臣也，德友而已矣！”
闉跂支离无唇说卫灵公，灵公说之，而视全人：脰其肩肩。甕盎大瘿说齐桓公，桓公说之，而视全人：其脰肩肩。故德有所长而形有所忘。人不忘其所忘而忘其所不忘，此谓诚忘。
故圣人有所游，而知为孽，约为胶，德为接，工为商。圣人不谋，恶用知？不斫，恶用胶？无丧，恶用德？不货，恶用商？四者，天鬻也。天鬻者，天食也。既受食于天，又恶用人！有人之形，无人之情。有人之形，故群于人；无人之情，故是非不得于身。眇乎小哉，所以属于人也；謷乎大哉，独成其天。
惠子谓庄子曰：“人故无情乎？”
庄子曰：“然。”
惠子曰：“人而无情，何以谓之人？”
庄子曰：“道与之貌，天与之形，恶得不谓之人？”
惠子曰：“既谓之人，恶得无情？”
庄子曰：“是非吾所谓情也。吾所谓无情者，言人之不以好恶内伤其身，常因自然而不益生也。”
惠子曰：“不益生，何以有其身？”
庄子曰：“道与之貌，天与之形，无以好恶内伤其身。今子外乎子之神，劳乎子之精，倚树而吟，据槁梧而瞑。天选子之形，子以坚白鸣。”', '本篇的中心在于讨论人的精神世界，应该怎样反映宇宙万物的本原观念和一体性观念。庄子在本篇里所说的“德”，并非通常理解的道德或者德行，而是指一种心态。庄子认为宇宙万物均源于“道”，而万事万物尽管千差万别，归根到底又都浑然为一，从这两点出发，体现在人的观念形态上便应是“忘形”与“忘情”。所谓“忘形”就是物我俱化，死生同一；所谓“忘情”就是不存在宠辱、贵贱、好恶、是非。这种“忘形”与“忘情”的精神状态就是庄子笔下的“德”。“充”指充实，“符”则是证验的意思。', '兀：通作“跀”（yuè），断足的刑法。“兀者”指受过跀刑只有一只脚的人。王骀（tái）：假托的人名。
常季：鲁国贤人，传说为孔子弟子。
中分鲁：在鲁国平分，意思是在鲁国彼此间差不多，不分上下。
无形：不具有完整的形体。心成：内心世界达到成熟的境界。一说“无形”指不须用形表，“心成”指潜移默化。
直：通作“特”，仅只的意思。后：意思是落在对方的后面。
奚：何。假：已，只。
王：突出、超过的意思；“王先生”即远远超过了先生。
庸：平庸，这里指平常的人。“其与庸亦远矣”，是说他跟平常人相比也就相差很远很远了。
若之何：如何，怎么样。
遗：失。“不与之遗”是说不会随着天翻地覆的情况而丧失。
审：明悉，通晓。假：凭依；“无假”即是“无待”。旧注“假”通作“瑕”，指审度自己没有一点儿毛病；姑备参考。
命：任。“命物之化”就是听任事物的变化。宗：本，主旨。
肝胆楚越：肝胆两种器官紧紧相连，楚越两国相去甚远，喻指邻近的肝胆同于一体之中也像是楚越那样相去甚远。
一：同一，一样的。
耳目之所宜：指适宜于听觉、视觉的东西。
游心：使心灵自由驰骋遨游。和：混同。
所一：同一的方面。所丧：失去而引起差异的一面。
遗土：失落土块。
以下四句很不好理解，各家断句也不一致，这里取传统的断句方法。为己：即修己。知（zhì）：智慧。“为己以其知”即“以其知为己”，意思是运用自己的才智来修养自己。
得其心以其心：即以其心得其心，大意是，用自己的心智去求取自己的理念。
常心：真常之心，即忘知忘觉，无思无虑的心境。
物：外物，这里指众多的门徒。何为：为何，为什么。最：聚集。
鉴：“鉴”字的异体，照看，审察的意思。远古无镜子，人们对着盛有水的器皿照看就像今天照镜子一样，故有“鉴于止水”而“莫鉴于流水”的说法。
唯止能止众止：唯有静止之物方能照人，方能使别的什么东西也静止下来。
以下四句有的版本为六句：“受命于地，唯松柏独也正，在冬夏青青；受命于天，唯尧舜独也正，在万物之首”，句式要工整得多，姑备参考。
正生：即正己，指端正自己的品行。下句“正众生”即端正他人的品行。
始：本初之态。征：迹象。
九：非实数，“九军”犹言千军万马。一说天子六军，诸侯三军，故名九军。
要：通作“徼”，求取的意思。
官：主宰。
府：包藏。
寓六骸：把自身的躯体当作寓所。
象：表象。
一知：自然赋予的智慧。
假：通作“格”，陟升的意思。
肎：“肯字之古本字。
郑子产：郑国的大政治家。伯昏无人：假托的人名。
止：停止，留下。
其：还是、抑或。
执政：子产曾是郑国执政大臣，故有此说。违：回避。申徒嘉为一兀者，地位低下而子产位尊，不愿与之同步，故有先出、留止的一段话。
齐：跟……齐一、一样，向……看齐；“齐执政”意思是跟执政大臣齐一，即把自己看得跟执政大臣一样。
固：岂。全句大意是，哪有执掌政务的大臣如此拜师从学的呢？言外之意是，伯昏无人门下没有贵贱之分，要分贵贱就不会到这里来拜师从学。
说（yuè）通作“悦，”喜悦。后人：以别人为后，含有瞧不起别人的意思。
大者：这里指广博精深的见识。
计：计算，估量。反：反省。这句语意有所隐含，好像是说受过刑断还不足以使自己有所反省吗？
状：陈述，含有为自己的过失辩解的意思。其过：自己的过失。以：认为。亡：丢失、失去，这里指使身体残缺，与下句“存”字表示保全的含义相对应。
羿：古代神话传说中的善射者。彀（gòu）：张满弓弩。“彀中”指弓箭射程范围之内，喻指人们生活的社会范围。
中（zhòng）：地：最易射中的地方。
怫（bó）然：勃然，发怒时盛气的样子。
先生：指伯昏无人。所：寓所。
废然：怒气消失的样子。反：返，指回复到原有的正常神态。
洗我以善：即以善洗我，用善道来教诲我。
夫子：指伯昏无人。
形骸之内：指人的精神世界。“游于形骸之内”即以德相交，精神世界相通。
形骸之外：指人的外在形体。索：要求。
蹴（cù）然：恭敬不安的样子。更：更改。
乃：仍。称：说。
踵：脚后跟，这里指用脚后跟走路。叔山无趾被刑断脚趾，所以只能用脚后跟来走路。
何及：怎么赶得上。言外之意怎么能够补救。
不知务：犹言不通晓事理。
尊足：即尊于足，“尊足者”意思是比脚更尊贵的东西，这里指道德修养。
务：务求，努力做到。
无：莫名，没有什么。
陋：浅薄固陋。
全德：保全了道德修养。一说“全德”即全体，指形体没有残缺。从上下文意看，后说更合理些。
老聃（dān）：即老子，姓李，名聃。
宾宾：频频。学子：即学于子，向老聃请教。
蕲（qí）：求。 （chù）诡：奇异。“ 诡幻怪”四字词义相近，都含有奇特、怪异、虚妄的意思。
桎梏：古代的一种刑具，犹如今言脚镣手铐，喻指束缚自己的工具。
一条：一致，一样的。
贯：通。“一贯”即齐一相通。
天：自然。刑：这里讲作“惩罚”的意思。
恶人：丑陋的人。
哀骀（tái）它（tuō）：虚构的人名。
丈夫：古代成年男子的通称。
去：离开。
唱：唱导，前导；跟下句的“和”相对应。
君人之位：即统治别人的地位。济：救助。
禄：俸禄，这里泛指财物。望：月儿满圆；这里引申用其饱满之义，“望人之腹”即使人人都能吃饱。
骇：惊扰。
四域：四周的邻界。
雌雄：这里泛指妇女和男人。合：亲近。
寡人：古代国君的谦称。
意：猜想，意料。“有意乎其为人”意思是，对于他的为人有了了解。
期（jī）年：一周年。
—宰：主持政务的官员。
闷然：神情淡漠的样子。
氾：这里形容心不在焉，有口无心的样子。辞：推却。
恤（xù）：“恤”字的异体，忧虑。亡：失。
使：出使。一说“出使”即出游。
少焉：一会儿。眴（shùn）若：惊惶的样子。走：跑。
使：主使，支配。
翣（shà）：古代出殡时棺木上的饰物，形同羽扇。资：送。
刖（yuè）：断足的刑罚。屦（jù）：用麻、葛等制成的单底鞋，这里泛指鞋子。连续两句都是比喻：战死之人埋葬沙场无须棺木，当然也就用不着棺饰，砍断了脚的人无须穿鞋，当然也就用不着鞋子，意在说明失去了根本外在的东西也就同时失去了可爱的价值。
诸御：宫中御女，即宫女。
剪（jiǎn）：“剪”字的异体。联系下一句，不修指甲，不穿耳眼，意在说明不加修饰以显本质。
取：通作“娶”。旧注男女婚娶之后便不再前往宫中服役。
尔：如此。
形：表露在外的意思。
穷：困窘，走头无路。达：通畅、顺利。
命之行：自然的运行，指非人为造成的情况变化。
相代：相互更替。
规：窥。
滑（gǔ）：通作“汩”，乱的意思。和：谐和，均衡。
灵府：心灵。
豫：安适。
兑（yuè）：悦，欢乐。
郤（xì）：通作“隙”，间隙的意思。
接：接触外物。时：顺时，顺应四时而作的意思。
法：仿效，借鉴。
荡：动。
成和之脩：事得以成功、物得以顺和的极高修养。“脩”同“修”。
闵子：人名，孔子的弟子。
纪：纲纪。
说（yuè）：通“悦”；喜欢。
脰（dòu）：颈项。肩肩：细小的样子。
瓮（wèng）（àng）：腹大口小的陶制盛器。“”字亦作“盎”。瘿（yǐng）：瘤。颈下的瘤子大如瓮盎，这里也是用畸形特征作为人名。
诚：真实。
孽（niè）：祸根。
约：盟誓。胶：粘固，胶着。“约为胶”意思是把盟约当成胶着似的束缚。
德为接：意思是把施德看作交接外物的手段。⑨工：工巧。
斲（zhuó）：“斫”字的异体，砍削的意思。
丧（shàng）：丢失、缺损。
货：意思是买卖东西以谋利。
天：自然。鬻（yù）：通作“育”，养育的意思。
天食：禀受自然的饲养和供给。
眇（miǎo）：通作“秒”，微小的意思。
謷（áo）：高大的样子。
惠子：即惠施，名家的代表人物。
道：中国古代哲学中的“道”，含义十分复杂，这里与“天”对应，“天”指事物的自然，“道”可能是指事物的本原，即宇宙万物的本体。
益：增添。
劳：耗费。
据：靠，凭依。槁梧：指用梧桐木做成的几案。瞑（mián）：通作“眠”，假寐的意思。
天选：自然的授予。
坚白：“坚白”论是古代名家的著名言论，它以石为喻，指石之白色与石之坚质都独立于“石”。庄子对于这一类辩论极不赞赏，斥之为无稽之谈。', '鲁国有个被砍掉一只脚的人，名叫王骀，可是跟从他学习的人却跟孔子的门徒一样多。孔子的学生常季向孔子问道；“王骀是个被砍去了一只脚的人，跟从他学习的人在鲁国却和先生的弟子相当。他站着不能给人教诲，坐着不能议论大事；弟子们却空怀而来，学满而归。难道确有不用言表的教导，身残体秽内心世界也能达到成熟的境界吗？这又是什么样的人呢？”孔子回答说：“王骀先生是一位圣人，我的学识和品行都落后于他，只是还没有前去请教他罢了。我将把他当作老师，何况学识和品行都不如我孔丘的人呢！何止鲁国，我将引领天下的人跟从他学习。”
常季说：“他是一个被砍去了一只脚的人，而学识和品行竟超过了先生，跟平常人相比相差就更远了。像这样的人，他运用心智是怎样与众不同的呢？”仲尼回答说：“死或生都是人生变化中的大事了，可是死或生都不能使他随之变化；即使天翻过来地坠下去，他也不会因此而丧失、毁灭。他通晓无所依凭的道理而不随物变迁，听任事物变化而信守自己的要旨。”常季说：“这是什么意思呢？”孔子说：“从事物千差万别的一面去看，邻近的肝胆虽同处于一体之中也像是楚国和越国那样相距很远；从事物都有相同的一面去看，万事万物又都是同一的。像这样的人，将不知道耳朵眼睛最适宜何种声音和色彩，而让自己的心思自由自在地遨游在忘形、忘情的浑同境域之中。外物看到了它同一的方面却看不到它因失去而引起差异的一面，因而看到丧失了一只脚就像是失落了土块一样。”
常季说：“他运用自己的智慧来提高自己的道德修养，他运用自己的心智去追求自己的理念。如果达到了忘情、忘形的境界，众多的弟子为什么还聚集在他的身边呢？”孔子回答说：“一个人不能在流动的水面照见自己的身影而是要面向静止的水面，只有静止的事物才能使别的事物也静止下来。各种树木都受命于地，但只有松树、柏树独自傲然挺立，无论冬夏都郁郁青青；每个人都受命于天，但只有虞舜道德品行最为端正。幸而他们都善于端正自己的品行，因而能端正他人的品行。保全本初时的迹象，心怀无所畏惧的胆识；勇士只身一人，也敢称雄于千军万马。一心追逐名利而自我索求的人，尚且能够这样，何况那主宰天地，包藏万物，只不过把躯体当作寓所，把耳目当作外表，掌握了自然赋予的智慧所通解的道理，而精神世界又从不曾有过衰竭的人呢！他定将选择好日子升登最高的境界，人们将紧紧地跟随着他。他还怎么会把聚合众多弟子当成一回事呢！”
申徒嘉是个被砍掉了一只脚的人，跟郑国的子产同拜伯昏无人为师。子产对申徒嘉说：“我先出去那么你就留下，你先出去那么我就留下。”到了第二天，子产和申徒嘉同在一个屋子里、同在一条席子上坐着。子产又对申徒嘉说：“我先出去那么你就留下，你先出去那么我就留下。现在我将出去，你可以留下吗，抑或是不留下呢？你见了我这执掌政务的大官却不知道回避，你把自己看得跟我执政的大臣一样吗？”
申徒嘉说：“伯昏无人先生的门下，哪有执政大臣拜师从学的呢？你津津乐道执政大臣的地位把别人都不放在眼里吗？我听说这样的话：‘镜子明亮尘垢就没有停留在上面，尘垢落在上面镜子也就不会明亮。长久地跟贤人相处便会没有过错’。你拜师从学追求广博精深的见识，正是先生所倡导的大道。而你竟说出这样的话，不是完全错了吗！”
子产说：“你已经如此形残体缺，还要跟唐尧争比善心，你估量你的德行，受过断足之刑还不足以使你有所反省吗？”申徒嘉说：“自个儿陈述或辩解自己的过错，认为自己不应当形残体缺的人很多；不陈述或辩解自己的过错，认为自己不应当形整体全的人很少。懂得事物之无可奈何，安于自己的境遇并视如命运安排的那样，只有有德的人才能做到这一点。一个人来到世上就象来到善射的后羿张弓搭箭的射程之内，中央的地方也就是最容易中靶的地方，然而却没有射中，这就是命。用完整的双脚笑话我残缺不全的人很多，我常常脸色陡变怒气填胸；可是只要来到伯昏无人先生的寓所，我便怒气消失回到正常的神态。真不知道先生用什么善道来洗刷我的呢？我跟随先生十九年了，可是先生从不曾感到我是个断了脚的人。如今你跟我心灵相通、以德相交，而你却用外在的形体来要求我，这不又完全错了吗？”子产听了申徒嘉一席话深感惭愧，脸色顿改而恭敬地说：“你不要再说下去了！”
鲁国有个被砍去脚趾的人，名叫叔山无趾，靠脚后跟走路去拜见孔子。孔子对他说：“你极不谨慎，早先犯了过错才留下如此的后果。虽然今天你来到了我这里，可是怎么能够追回以往呢！”叔山无趾说：“我只因不识事理而轻率作践自身，所以才失掉了两只脚趾。如今我来到你这里，还保有比双脚更为可贵的道德修养，所以我想竭力保全它。苍天没有什么不覆盖，大地没有什么不托载，我把先生看作天地，哪知先生竟是这样的人！”孔子说：“我孔丘实在浅薄。先生怎么不进来呢，请把你所知晓的道理讲一讲。”叔山无趾走了。孔子对他的弟子说：“你们要努力啊。叔山无趾是一个被砍掉脚趾的人，他还努力进学来补救先前做过的错事，何况道德品行乃至身形体态都没有什么缺欠的人呢！”
叔山无趾对老子说：“孔子作为一个道德修养至尚的人，恐怕还未能达到吧？他为什么不停地来向你求教呢？他还在祈求奇异虚妄的名声能传扬于外，难道不懂得道德修养至尚的人总是把这一切看作是束缚自己的枷锁吗？”老子说：“怎么不径直让他把生和死看成一样，把可以与不可以看作是齐一的，从而解脱他的枷锁，这样恐怕也就可以了吧？”叔山无趾说：“这是上天加给他的处罚，哪里可以解脱！”
鲁哀公向孔子问道：“卫国有个面貌十分丑陋的人，名叫哀骀它。男人跟他相处，常常想念他而舍不得离去。女人见到他便向父母提出请求，说‘与其做别人的妻子，不如做哀骀它先生的妾，’这样的人已经十多个了而且还在增多。从不曾听说哀骀它唱导什么，只是常常附和别人罢了。他没有居于统治者的地位而拯救他人于临近败亡的境地，他没有聚敛大量的财物而使他人吃饱肚子。他面貌丑陋使天下人吃惊，又总是附和他人而从没首倡什么，他的才智也超不出他所生活的四境，不过接触过他的人无论是男是女都乐于亲近他。这样的人一定有什么不同于常人的地方。我把他召来看了看，果真相貌丑陋足以惊骇天下人。跟我相处不到一个月，我便对他的为人有了了解；不到一年时间，我就十分信任他。国家没有主持政务的官员，我便把国事委托给他。他神情淡漠地回答，漫不经心又好像在加以推辞。我深感羞愧，终于把国事交给了他。没过多久，他就离开我走掉了，我内心忧虑像丢失了什么，好像整个国家没有谁可以跟我一道共欢乐似的。这究竟是什么样的人呢？”
孔子说：“我孔丘也曾出使到楚国，正巧看见一群小猪在吮吸刚死去的母猪的乳汁，不一会又惊惶地丢弃母猪逃跑了。因为不知道自己的同类已经死去，母猪不能像先前活着时那样哺育它们。小猪爱它们的母亲，不是爱它的形体，而是爱支配那个形体的精神。战死沙场的人，他们埋葬时无须用棺木上的饰物来送葬，砍掉了脚的人对于原来穿过的鞋子，没有理由再去爱惜它，这都是因为失去了根本。做天子的御女，不剪指甲不穿耳眼；婚娶之人只在宫外办事，不会再到宫中服役。为保全形体尚且能够做到这一点，何况德性完美而高尚的人呢？如今哀骀它他不说话也能取信于人，没有功绩也能赢得亲近，让人乐意授给他国事，还唯恐他不接受，这一定是才智完备而德不外露的人。”
鲁哀公问：“什么叫做才智完备呢？”孔子说：“死、生、存、亡，穷、达、贫、富，贤能与不肖、诋毁与称誉，饥、渴、寒、暑，这些都是事物的变化，都是自然规律的运行；日夜更替于我们的面前，而人的智慧却不能窥见它们的起始。因此它们都不足以搅乱本性的谐和，也不足以侵扰人们的心灵。要使心灵平和安适，通畅而不失怡悦，要使心境日夜不间断地跟随万物融会在春天般的生气里，这样便会接触外物而萌生顺应四时的感情。这就叫做才智完备。”鲁哀公又问：“什么叫做德不外露呢？”孔子说：“均平是水留止时的最佳状态。它可以作为取而效法的准绳，内心里充满蕴含而外表毫无所动。所谓德，就是事得以成功、物得以顺和的最高修养。德不外露，外物自然就不能离开他了。”
有一天鲁哀公把孔子这番话告诉闵子，说：“起初我认为坐朝当政统治天下，掌握国家的纲纪而忧心人民的死活，便自以为是最通达的了，如今我听到至人的名言，真忧虑没有实在的政绩，轻率作践自身而使国家危亡。我跟孔子不是君臣关系，而是以德相交的朋友呢。”
一个跛脚、伛背、缺嘴的人游说卫灵公，卫灵公十分喜欢他；再看看那些体形完整的人，他们的脖颈实在是太细太细了。一个颈瘤大如瓮盎的人游说齐桓公，齐桓公十分喜欢他；再看看那些体形完整的人，他们的脖颈实在是太细太细的了。所以，在德行方面有超出常人的地方而在形体方面的缺陷别人就会有所遗忘，人们不会忘记所应当忘记的东西，而忘记了所不应当忘记的东西，这就叫做真正的遗忘。因而圣人总能自得地出游，把智慧看作是祸根，把盟约看作是禁锢，把推展德行看作是交接外物的手段，把工巧看作是商贾的行为。圣人从不谋虑，哪里用得着智慧？圣人从不砍削，哪里用得着胶着？圣人从不感到缺损，哪里用得着推展德行？圣人从不买卖以谋利，哪里用得着经商？这四种作法叫做天养。所谓天养，就是禀受自然的饲养。既然受养于自然，又哪里用得着人为！有了人的形貌，不一定有人内在的真情。有了人的形体，所以与人结成群体；没有人的真情，所以是与非都不会汇聚在他的身上。渺小呀，跟人同类的东西！伟大呀，只有浑同于自然。
惠子对庄子说：“人原本就是没有情的吗？”庄子说：“是的”。惠子说：“一个人假若没有情，为什么还能称作人呢？”庄子说：“道赋予人容貌，天赋予人形体，怎么能不称作人呢？”惠子说：“既然已经称作了人，又怎么能够没有情？”庄子回答说：“这并不是我所说的情呀。我所说的无情，是说人不因好恶，而致伤害自身的本性，常常顺任自然而不随意增添些什么。”惠子说：“不添加什么，靠什么来保有自己的身体呢？”庄子回答说：“道赋予人容貌，天赋予人形体，可不要因外在的好恶而致伤害了自己的本性。如今你外露你的心神，耗费你的精力，靠着树干吟咏，凭依几案闭目假寐。自然授予了你的形体，你却以‘坚’、‘白’的诡辩而自鸣得意！”', NULL, '', 'indent', 1524824848, '57ea0e758ac247005be1583b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10246, '庄子 · 内篇 · 大宗师', NULL, 54, 16, 1, 1, '庄子', NULL, 10064, '57b90297165abd0054bfdce7', '周', 'wen', '文', 'http://baike.baidu.com/item/%E5%A4%A7%E5%AE%97%E5%B8%88/18477047', '', '知天之所为，知人之所为者，至矣！知天之所为者，天而生也；知人之所为者，以其知之所知以养其知之所不知，终其天年而不中道夭者，是知之盛也。虽然，有患：夫知有所待而后当，其所待者特未定也。庸讵知吾所谓天之非人乎？所谓人之非天乎？且有真人而后有真知。
何谓真人？古之真人，不逆寡，不雄成，不谟士。若然者，过而弗悔，当而不自得也。若然者，登高不栗，入水不濡，入火不热，是知之能登假于道者也若此。
古之真人，其寝不梦，其觉无忧，其食不甘，其息深深。真人之息以踵，众人之息以喉。屈服者，其嗌言若哇。其耆欲深者，其天机浅。
古之真人，不知说生，不知恶死。其出不欣，其入不距。翛然而往，翛然而来而已矣。不忘其所始，不求其所终。受而喜之，忘而复之。是之谓不以心捐道，不以人助天，是之谓真人。若然者，其心志，其容寂，其颡頯（音qiu）。凄然似秋，暖然似春，喜怒通四时，与物有宜而莫知其极。故圣人之用兵也，亡国而不失人心。利泽施乎万世，不为爱人。故乐通物，非圣人也；有亲，非仁也；天时，非贤也；利害不通，非君子也；行名失己，非士也；亡身不真，非役人也。若狐不偕、务光、伯夷、叔齐、箕子、胥余、纪他、申徒狄，是役人之役，适人之适，而不自适其适者也。
古之真人，其状义而不朋，若不足而不承；与乎其觚而不坚也，张乎其虚而不华也；邴邴乎其似喜也，崔崔乎其不得已也，滀乎进我色也，与乎止我德也，广乎其似世也，謷乎其未可制也，连乎其似好闭也，悗乎忘其言也。以刑为体，以礼为翼，以知为时，以德为循。以刑为体者，绰乎其杀也；以礼为翼者，所以行于世也；以知为时者，不得已于事也；以德为循者，言其与有足者至于丘也，而人真以为勤行者也。故其好之也一，其弗好之也一。其一也一，其不一也一。其一与天为徒，其不一与人为徒，天与人不相胜也，是之谓真人。
死生，命也；其有夜旦之常，天也。人之有所不得与，皆物之情也。彼特以天为父，而身犹爱之，而况其卓乎！人特以有君为愈乎己，而身犹死之，而况其真乎！
泉涸，鱼相与处于陆，相呴以湿，相濡以沫，不如相忘于江湖。与其誉尧而非桀也，不如两忘而化其道。
夫大块载我以形，劳我以生，佚我以老，息我以死。故善吾生者，乃所以善吾死也。夫藏舟于壑，藏山于泽，谓之固矣！然而夜半有力者负之而走，昧者不知也。藏小大有宜，犹有所循。若夫藏天下于天下而不得所循，是恒物之大情也。特犯人之形而犹喜之。若人之形者，万化而未始有极也，其为乐可胜计邪？故圣人将游于物之所不得循而皆存。善妖善老，善始善终，人犹效之，而况万物之所系而一化之所待乎！
夫道有情有信，无为无形；可传而不可受，可得而不可见；自本自根，未有天地，自古以固存；神鬼神帝，生天生地；在太极之先而不为高，在六极之下而不为深，先天地生而不为久，长于上古而不为老。豨韦氏得之，以挈天地；伏戏氏得之，以袭气母；维斗得之，终古不忒；日月得之，终古不息；勘坏得之，以袭昆仑；冯夷得之，以游大川；肩吾得之，以处大山；黄帝得之，以登云天；颛顼得之，以处玄宫；禺强得之，立乎北极；西王母得之，坐乎少广，莫知其始，莫知其终；彭祖得之，上及有虞，下及五伯；傅说得之，以相武丁，奄有天下，乘东维、骑箕尾而比于列星。
南伯子葵问乎女偊曰：“子之年长矣，而色若孺子，何也？”曰：“吾闻道矣。”南伯子葵曰：“道可得学邪？”曰：“恶！恶可！子非其人也。夫卜梁倚有圣人之才而无圣人之道，我有圣人之道而无圣人之才。吾欲以教之，庶几其果为圣人乎？不然，以圣人之道告圣人之才，亦易矣。吾犹守而告之，参日而后能外天下；已外天下矣，吾又守之，七日而后能外物；已外物矣，吾又守之，九日而后能外生；已外生矣，而后能朝彻；朝彻而后能见独；见独而后能无古今；无古今而后能入于不死不生。杀生者不死，生生者不生。其为物无不将也，无不迎也，无不毁也，无不成也。其名为撄宁。撄宁也者，撄而后成者也。”
南伯子葵曰：“子独恶乎闻之？”曰：“闻诸副墨之子，副墨之子闻诸洛诵之孙，洛诵之孙闻之瞻明，瞻明闻之聂许，聂许闻之需役，需役闻之于讴，于讴闻之玄冥，玄冥闻之参寥，参寥闻之疑始。”子祀、子舆、子犁、子来四人相与语曰：“孰能以无为首，以生为脊，以死为尻；孰知死生存亡之一体者，吾与之友矣！”四人相视而笑，莫逆于心，遂相与为友。俄而子舆有病，子祀往问之。曰：“伟哉，夫造物者将以予为此拘拘也。”曲偻发背，上有五管，颐隐于齐，肩高于顶，句赘指天，阴阳之气有沴，其心闲而无事，胼囗（左“足”右“鲜”音xian）而鉴于井，曰：“嗟乎！夫造物者又将以予为此拘拘也。”
子祀曰：“女恶之乎？”曰：“亡，予何恶！浸假而化予之左臂以为鸡，予因以求时夜；浸假而化予之右臂以为弹，予因以求鸮炙；浸假而化予之尻以为轮，以神为马，予因以乘之，岂更驾哉！且夫得者，时也；失者，顺也。安时而处顺，哀乐不能入也，此古之所谓县解也，而不能自解者，物有结之。且夫物不胜天久矣，吾又何恶焉！”
俄而子来有病，喘喘然将死。其妻子环而泣之。子犁往问之，曰：“叱！避！无怛化！”倚其户与之语曰：“伟哉造化！又将奚以汝为？将奚以汝适？以汝为鼠肝乎？以汝为虫臂乎？”子来曰：“父母于子，东西南北，唯命之从。阴阳于人，不翅于父母。彼近吾死而我不听，我则悍矣，彼何罪焉？夫大块以载我以形，劳我以生，佚我以老，息我以死。故善吾生者，乃所以善吾死也。今大冶铸金，金踊跃曰：‘我且必为镆铘！’大冶必以为不祥之金。今一犯人之形而曰：‘人耳！人耳！’夫造化者必以为不祥之人。今一以天地为大炉，以造化为大冶，恶乎往而不可哉！”成然寐，蘧然觉。
子桑户、孟子反、子琴张三人相与友曰：“孰能相与于无相与，相为于无相为；孰能登天游雾，挠挑无极，相忘以生，无所穷终！”三人相视而笑，莫逆于心，遂相与友。
莫然有间，而子桑户死，未葬。孔子闻之，使子贡往侍事焉。或编曲，或鼓琴，相和而歌曰：“嗟来桑户乎！嗟来桑户乎！而已反其真，而我犹为人猗！”子贡趋而进曰：“敢问临尸而歌，礼乎？”二人相视而笑曰：“是恶知礼意！”子贡反，以告孔子曰：“彼何人者邪？修行无有而外其形骸，临尸而歌，颜色不变，无以命之。彼何人者邪？”孔子曰：“彼游方之外者也，而丘游方之内者也。外内不相及，而丘使女往吊之，丘则陋矣！彼方且与造物者为人，而游乎天地之一气。彼以生为附赘县疣，以死为决囗（“病”字以“丸”代“丙”音huan4）溃痈。夫若然者，又恶知死生先后之所在！假于异物，托于同体；忘其肝胆，遗其耳目；反复终始，不知端倪；芒然仿徨乎尘垢之外，逍遥乎无为之业。彼又恶能愦愦然为世俗之礼，以观众人之耳目哉！”
子贡曰：“然则夫子何方之依？”孔子曰：“丘，天之戮民也。虽然，吾与汝共之。”子贡曰：“敢问其方？”孔子曰：“鱼相造乎水，人相造乎道。相造乎水者，穿池而养给；相造乎道者，无事而生定。故曰：鱼相忘乎江湖，人相忘乎道术。”子贡曰：“敢问畸人？”
曰：“畸人者，畸于人而侔于天。故曰：天之小人，人之君子；人之君子，天之小人也。”
颜回问仲尼曰：“孟孙才，其母死，哭泣无涕，中心不戚，居丧不哀。无是三者，以善处丧盖鲁国，固有无其实而得其名者乎？回壹怪之。”仲尼曰：“夫孟孙氏尽之矣，进于知矣，唯简之而不得，夫已有所简矣。孟孙氏不知所以生，不知所以死。不知就先，不知就后。
若化为物，以待其所不知之化已乎。且方将化，恶知不化哉？方将不化，恶知已化哉？吾特与汝，其梦未始觉者邪！且彼有骇形而无损心，有旦宅而无情死。孟孙氏特觉，人哭亦哭，是自其所以乃。且也相与‘吾之’耳矣，庸讵知吾所谓‘吾之’乎？且汝梦为鸟而厉乎天，梦为鱼而没于渊。不识今之言者，其觉者乎？其梦者乎？造适不及笑，献笑不及排，安排而去化，乃入于寥天一。”
意而子见许由，许由曰：“尧何以资汝？”意而子曰：“尧谓我：汝必躬服仁义而明言是非。”许由曰：“而奚来为轵？夫尧既已黥汝以仁义，而劓汝以是非矣。汝将何以游夫遥荡恣睢转徙之涂乎？”
意而子曰：“虽然，吾愿游于其藩。”许由曰：“不然。夫盲者无以与乎眉目颜色之好，瞽者无以与乎青黄黼黻之观。”意而子曰：“夫无庄之失其美，据梁之失其力，黄帝之亡其知，皆在炉捶之间耳。庸讵知夫造物者之不息我黥而补我劓，使我乘成以随先生邪？”许由曰：“噫！未可知也。我为汝言其大略：吾师乎！吾师乎！赍万物而不为义，泽及万世而不为仁，长于上古而不为老，覆载天地、刻雕众形而不为巧。此所游已！
颜回曰：“回益矣。”仲尼曰：“何谓也？”曰：“回忘仁义矣。”曰：“可矣，犹未也。”他日复见，曰：“回益矣。”曰：“何谓也？”曰：“回忘礼乐矣！”曰：“可矣，犹未也。”他日复见，曰：“回益矣！”曰：“何谓也？”曰：“回坐忘矣。”仲尼蹴然曰：“何谓坐忘？”颜回曰：“堕肢体，黜聪明，离形去知，同于大通，此谓坐忘。”仲尼曰：“同则无好也，化则无常也。而果其贤乎！丘也请从而后也。”
子舆与子桑友。而霖雨十日，子舆曰：“子桑殆病矣！”裹饭而往食之。至子桑之门，则若歌若哭，鼓琴曰：“父邪！母邪！天乎！人乎！”有不任其声而趋举其诗焉。子舆入，曰：“子之歌诗，何故若是？”曰：“吾思夫使我至此极者而弗得也。父母岂欲吾贫哉？天无私覆，地无私载，天地岂私贫我哉？求其为之者而不得也！然而至此极者，命也夫！”', '本文是《庄子》一书中的一篇，《庄子》的思想包含着朴素辩证法因素，主要思想是“天道无为”“宗”指敬仰、尊崇，“大宗师”意思是最值得敬仰、尊崇的老师。谁够得上称作这样的老师呢？那就是“达于道之人”。', '', '知道自然的作为，并且了解人的作为，这就达到了认识的极点。知道自然的作为，是懂得事物出于自然；了解人的作为，是用他智慧所通晓的知识哺育、薰陶他智慧所未能通晓的知识，直至自然死亡而不中途夭折，这恐怕就是认识的最高境界了。虽然这样，还是存在忧患。人们的知识一定要有所依凭方才能认定是否恰当，而认识的对象却是不稳定的。怎么知道我所说的本于自然的东西不是出于人为呢，怎么知道我所说的人为的东西又不是出于自然呢？
况且有了“真人”方才有真知。什么叫做“真人”呢？古时候的“真人”，不倚众凌寡，不自恃成功雄踞他人，也不图谋琐事。像这样的人，错过了时机不后悔，赶上了机遇不得意。象这样的人，登上高处不颤栗，下到水里不会沾湿，进入火中不觉灼热。这只有智慧能通达大道境界的人方才能像这样。古时候的“真人”，他睡觉时不做梦，他醒来时不忧愁，他吃东西时不求甘美，他呼吸时气息深沉。“真人”呼吸凭借的是着地的脚根，而一般人呼吸则靠的只是喉咙。被人屈服时，言语在喉前吞吐就像哇哇地曼语。那些嗜好和欲望太深的人，他们天生的智慧也就很浅。古时候的“真人”，不懂得喜悦生存，也不懂得厌恶死亡；出生不欣喜，入死不推辞；无拘无束地就走了，自由自在地又来了罢了。不忘记自己从哪儿来，也不寻求自己往哪儿去，承受什么际遇都欢欢喜喜，忘掉死生像是回到了自己的本然，这就叫做不用心智去损害大道，也不用人为的因素去帮助自然。这就叫“真人”。像这样的人，他的内心忘掉了周围的一切，他的容颜淡漠安闲，他的面额质朴端严；冷肃得像秋天，温暖得像春天，高兴或愤怒跟四时更替一样自然无饰，和外界事物合宜相称而没有谁能探测到他精神世界的真谛。
所以古代圣人使用武力，灭掉敌国却不失掉敌国的民心；利益和恩泽广施于万世，却不是为了偏爱什么人。乐于交往取悦外物的人，不是圣人；有偏爱就算不上是“仁”；伺机行事，不是贤人；不能看到利害的相通和相辅，算不上是君子；办事求名而失掉自身的本性，不是有识之士；丧失身躯却与自己的真性不符，不是能役使世人的人。像狐不偕、务光、伯夷、叔齐、箕子、胥余、纪他、申徒狄，这样的人都是被役使世人的人所役使，都是被安适世人的人所安适，而不是能使自己得到安适的人。
古时候的“真人”，神情嵬峨而不矜持，好像不足却又无所承受；态度安闲自然、特立超群而不执着顽固，襟怀宽阔虚空而不浮华；怡然欣喜像是格外地高兴，一举一动又像是出自不得已！容颜和悦令人喜欢接近，与人交往德性宽和让人乐于归依；气度博大像是宽广的世界！高放自得从不受什么限制，绵邈深远好像喜欢封闭自己，心不在焉的样子又好像忘记了要说的话。把刑律当作主体，把礼仪当作羽翼，用已掌握的知识去等待时机，用道德来遵循规律。把刑律当作主体的人，那么杀了人也是宽厚仁慈的；把礼仪当作羽翼的人，用礼仪的教诲在世上施行；用已掌握的知识去等待时机的人，是因为对各种事情出于不得已；用道德来遵循规律，就像是说大凡有脚的人就能够登上山丘，而人们却真以为是勤于行走的人。所以说人们所喜好的是浑然为一的，人们不喜好的也是浑然为一的。那些同一的东西是浑一的，那些不同一的东西也是浑一的。那些同一的东西跟自然同类，那些不同一的东西跟人同类。自然与人不可能相互对立而相互超越，具有这种认识的人就叫做“真人”。
死和生均非人为之力所能安排，犹如黑夜和白天交替那样永恒地变化，完全出于自然。有些事情人是不可能参与和干预的，这都是事物自身变化的实情。人们总是把天看作生命之父，而且终身爱戴它，何况那特立高超的“道”呢！人们还总认为国君是一定超越自己的，而且终身愿为国君效死，又何况应该宗为大师的“道”呢？
泉水干涸了，鱼儿困在陆地上相互依偎，互相大口出气来取得一点湿气，以唾沫相互润湿，不如将过去江湖里的生活彻底忘记。与其赞誉唐尧的圣明而非议夏桀的暴虐，不如把他们都忘掉而融化混同于“道”。大地把我的形体托载，并且用生存来劳苦我，用衰老来闲适我，用死亡来安息我。所以，把我的存在看作好事的，也就因此而可以把我的死亡看作是好事。
将船儿藏在大山沟里，将渔具藏在深水里，可以说是十分牢靠了。然而半夜里有个大力士把它们连同山谷和河泽一块儿背着跑了，睡梦中的人们还一点儿也不知道。将小东西藏在大东西里是适宜的，不过还是会有丢失。假如把天下藏在天下里而不会丢失，这就是事物固有的真实之情。人们只要承受了人的形体便十分欣喜，至于像人的形体的情况，在万千变化中从不曾有过穷尽，那快乐之情难道还能够加以计算吗？所以圣人将生活在各种事物都不会丢失的环境里而与万物共存亡。以少为善以老为善，以始为善以终为善，人们尚且加以效法，又何况那万物所联缀、各种变化所依托的“道”呢！
“道”是真实而又确凿可信的，然而它又是无为和无形的；“道”可以感知却不可以口授，可以领悟却不可以面见；“道”自身就是本、就是根，还未出现天地的远古时代“道”就已经存在；它引出鬼帝，产生天地；它在太极之上却并不算高，它在六极之下不算深，它先于天地存在还不算久，它长于上古还不算老。狶韦氏得到它，用来统驭天地；伏羲氏得到它，用来调合元气；北斗星得到它，永远不会改变方位；太阳和月亮得到它，永远不停息地运行；堪坏得到它，用来入主昆仑山；冯夷得到它，用来巡游大江大河；肩吾得到它，用来驻守泰山；黄帝得到它，用来登上云天；颛顼得到它，用来居处玄宫；禹强得到它，用来立足北极；西王母得到它，用来坐阵少广山。没有人能知道它的开始，也没有人能知道它的终结。彭祖得到它，从远古的有虞时代一直活到五伯时代；傅说得到它，用来辅佐武丁，统辖整个天下，乘驾东维星，骑坐箕宿和尾宿，而永远排列在星神的行列里。
南伯子葵向女偊问道：“你的岁数已经很大了，可是你的容颜却像孩童，这是什么缘故呢？”女偊回答：“我得‘道’了。”南伯子葵说：“‘道’可以学习吗？”女偊回答说：“不！怎么可以呢！你不是可以学习‘道’的人。卜梁倚有圣人明敏的才气却没有圣人虚淡的心境，我有圣人虚淡的心境却没有圣人明敏的才气，我想用虚淡的心境来教导他，恐怕他果真能成为圣人哩！然而却不是这样，把圣人虚淡的心境传告具有圣人才气的人，应是很容易的。我还是持守着并告诉他，三天之后便能遗忘天下，既已遗忘天下，我又凝寂持守，七天之后能遗忘万物；既已遗忘外物，我又凝寂持守，九天之后便能遗忘自身的存在；既已遗忘存在的生命，而后心境便能如朝阳一般清新明彻；能够心境如朝阳般清新明彻，而后就能够感受那绝无所待的‘道’了；既已感受了‘道’，而后就能超越古今的时限；既已能够超越古今的时限，而后便进入无所谓生、无所谓死的境界。摒除了生也就没有死，留恋于生也就不存在生。作为事物，‘道’无不有所送，也无不有所迎；无不有所毁，也无不有所成，这就叫做‘撄宁’。撄宁，意思就是不受外界事物的纷扰，而后保持心境的宁静。”
南伯子葵又问：“你偏偏是怎么得‘道’的呢？”女偊又回答说：“我从副墨（文字）的儿子那里听到的，副墨的儿子从洛诵（背诵）的孙子那里听到的，洛诵的孙子从瞻明（目视明晰）那里听到的，瞻明从聂许（附耳私语）那里听到的，聂许从需役（勤行不怠）那里听到的，需役从於讴（吟咏领会）那里听到的，於讴从玄冥（深远虚寂）那里听到的，玄冥从参寥（高旷寥远）那里听到的，参寥从疑始（迷茫而无所本）那里听到的。”
子祀、子舆、子犁、子来四个人在一块摆谈说：“谁能够把无当作头，把生当作脊柱，把死当作尻尾，谁能够通晓生死存亡浑为一体的启发，我们就可以跟他交朋友。”四个人都会心地相视而笑，心心相契却不说话，于是相互交往成为朋友。
不久子舆生了病，子祀前去探望他。子舆说：“伟大啊，造物者！把我变成如此曲屈不伸的样子！腰弯背驼，五脏穴口朝上，下巴隐藏在肚脐之下，肩部高过头顶，弯曲的颈椎形如赘瘤朝天隆起”。阴阳二气不和酿成如此灾害，可是子舆的心里却十分闲逸好像没有生病似的，蹒跚地来到井边对着井水照看自己，说：“哎呀，造物者竟把我变成如此曲屈不伸！”
子祀说：“你讨厌这曲屈不伸的样子吗？”子舆回答：“没有，我怎么会讨厌这副样子！假令造物者逐渐把我的左臂变成公鸡，我便用它来报晓；假令造物者逐渐把我的右臂变成弹弓，我便用它来打斑鸠烤熟了吃。假令造物者把我的臀部变化成为车轮，把我的精神变化成骏马，我就用来乘坐，难道还要更换别的车马吗？至于生命的获得，是因为适时，生命的丧失，是因为顺应；安于适时而处之顺应，悲哀和欢乐都不会侵入心房。这就是古人所说的解脱了倒悬之苦，然而不能自我解脱的原因，则是受到了外物的束缚。况且事物的变化不能超越自然的力量已经很久很久，我又怎么能厌恶自己现在的变化呢？”
不久子来也生了病，气息急促将要死去，他的妻子儿女围在床前哭泣。子犁前往探望，说：“嘿，走开！不要惊扰他由生而死的变化！”子犁靠着门跟子来说话：“伟大啊，造物者！又将把你变成什么，把你送到何方？把你变化成老鼠的肝脏吗？把你变化成虫蚁的臂膀吗？”
子来说：“父母对于子女，无论东西南北，他们都只能听从吩咐调遣。自然的变化对于人，则不啻于父母；它使我靠拢死亡而我却不听从，那么我就太蛮横了，而它有什么过错呢！大地把我的形体托载，用生存来劳苦我，用衰老来闲适我，用死亡来安息我。所以把我的存在看作是好事，也因此可以把我的死亡看作是好事。现在如果有一个高超的冶炼工匠铸造金属器皿，金属熔解后跃起说‘我将必须成为良剑莫邪’，冶炼工匠必定认为这是不吉祥的金属。如今人一旦承受了人的外形，便说‘成人了成人了’，造物者一定会认为这是不吉祥的人。如今把整个浑一的天地当作大熔炉，把造物者当作高超的冶炼工匠，用什么方法来驱遣我而不可以呢？”于是安闲熟睡似的离开人世，又好像惊喜地醒过来而回到人间。
子桑户、孟子反、子琴张三人在一起谈话：“谁能够相互交往于无心交往之中，相互有所帮助却像没有帮助一样？谁能登上高天巡游雾里，循环升登于无穷的太空，忘掉自己的存在，而永远没有终结和穷尽？”三人会心地相视而笑，心心相印于是相互结成好友。过不多久子桑户死了，还没有下葬。孔子知道了，派弟子子贡前去帮助料理丧事。孟子反和子琴张却一个在编曲，一个在弹琴，相互应和着唱歌：“哎呀，子桑户啊！哎呀，子桑户啊！你已经返归本真，可是我们还成为活着的人而托载形骸呀！”子贡听了快步走到他们近前，说：“我冒昧地请教，对着死人的尸体唱歌，这合乎礼仪吗？”二人相视笑了笑，不屑地说：“这种人怎么会懂得‘礼’的真实含意！”
子贡回来后把见到的情况告诉给孔子，说：“他们都是些什么样的人呢？不看重德行的培养而无有礼仪，把自身的形骸置于度外，面对着死尸还要唱歌，容颜和脸色一点也不改变，没有什么办法可以用来称述他们。他们究竟是些什么样的人呢？”
孔子说：“他们都是些摆脱礼仪约束而逍遥于人世之外的人，我却是生活在具体的世俗环境中的人。人世之外和人世之内彼此不相干涉，可是我却让你前去吊唁，我实在是浅薄呀！他们正跟造物者结为伴侣，而逍遥于天地浑一的元气之中。他们把人的生命看作像赘瘤一样多余，他们把人的死亡看作是毒痈化脓后的溃破，像这样的人，又怎么会顾及死生优劣的存在！凭借于各各不同的物类，但最终寄托于同一的整体；忘掉了体内的肝胆，也忘掉了体外的耳目；无尽地反复着终结和开始，但从不知道它们的头绪；茫茫然彷徨于人世之外，逍遥自在地生活在无所作为的环境中。他们又怎么会烦乱地去炮制世俗的礼仪，而故意炫耀于众人的耳目之前呢！”
子贡说：“如此，那么先生将遵循什么准则呢？”孔子说：“我孔丘，乃是苍天所惩罚的罪人。即使这样，我仍将跟你们一道去竭力追求至高无尚的‘道’。子贡问：“请问追求‘道’的方法。”孔子回答：“鱼争相投水，人争相求道。争相投水的鱼，掘地成池便给养充裕；争相求道的人，漠然无所作为便心性平适。所以说，鱼相忘于江湖里，人相忘于道术中”。子贡说：“再冒昧地请教‘畸人’的问题”。孔子回答：“所谓‘畸人’，就是不同于世俗而又等同于自然的人。所以说，自然的小人就是人世间的君子；人世间的君子就是自然的小人。”
颜回请教孔子说：“孟孙才这个人，他的母亲死了，哭泣时没有一滴眼泪，心中不觉悲伤，居丧时也不哀痛。这三个方面没有任何悲哀的表现，可是却因善于处理丧事而名扬鲁国。难道真会有无其实而有其名的情况吗？颜回实在觉得奇怪。”
孔子说：“孟孙才处理丧事的作法确实是尽善尽美了，大大超过了懂得丧葬礼仪的人。人们总希望从简治丧却不能办到，而孟孙才已经做到从简办理丧事了。孟孙才不过问人因为什么而生，也不去探寻人因为什么而死；不知道趋赴生，也不知道靠拢死；他顺应自然的变化而成为他应该变成的物类，以期待那些自己所不知晓的变化！况且即将出现变化，怎么知道不变化呢？即将不再发生变化，又怎么知道已经有了变化呢！只有我和你呀，才是做梦似的没有一点儿觉醒的人呢！那些死去了的人惊扰了自身形骸却无损于他们的精神，犹如精神的寓所朝夕改变却并不是精神的真正死亡。唯独孟孙才觉醒，人们哭他也跟着哭，这就是他如此居丧的原因。况且人们交往总借助形骸而称述自我，又怎么知道我所称述的躯体一定就是我呢？而且你梦中变成鸟便振翅直飞蓝天，你梦中变成鱼便摇尾潜入深渊。不知道今天我们说话的人，算是醒悟的人呢，还是做梦的人呢？心境快适却来不及笑出声音，表露快意发出笑声却来不及排解和消泄，安于自然的推移而且忘却死亡的变化，于是就进入到寂寥虚空的自然而浑然成为一体。”
意而子拜访许由。许由说：“尧把什么东西给予了你？”意而子说：“尧对我说：‘你一定得亲身实践仁义并明白无误地阐明是非’”。许由说：“你怎么还要来我这里呢？尧已经用‘仁义’在你的额上刻下了印记，又用‘是非’割下了你的鼻子，你将凭借什么游处于逍遥放荡、纵任不拘、辗转变化的道途呢？”意而子说：“虽然这样，我还是希望能游处于如此的境域。”
许由说：“不对。有眼无珠的盲人没法跟他观赏佼好的眉目和容颜，瞎子没法跟他赏鉴礼服上各种不同颜色的花纹。”意而子说：“无庄不再打扮忘掉自己的美丽，据梁不再逞强忘掉自己的勇力，黄帝闻‘道’之后忘掉自己的智慧，他们都因为经过了‘道’的冶炼和锻打。怎么知道那造物者不会养息我受黥刑的伤痕和补全我受劓刑所残缺的鼻子，使我得以保全托载精神的身躯而跟随先生呢？”
许由说：“唉！这可是不可能知道的。我还是给你说个大概吧。‘道’是我伟大的宗师啊！我伟大的宗师啊！把万物碎成粉末不是为了某种道义，把恩泽施于万世不是出于仁义，长于上古不算老，回天载地、雕创众物之形也不算技巧。这就进入‘道’的境界了。”
颜回说：“我进步了。”孔子问道：“你的进步指的是什么？”颜回说：“我已经忘却仁义了。”孔子说：“好哇，不过还不够。”过了几天颜回再次拜见孔子，说：“我又进步了。”孔子问：“你的进步指的是什么？”颜回说：“我忘却礼乐了。”孔子说：“好哇，不过还不够。”过了几天颜回又再次拜见孔子，说：“我又进步了。”孔子问：“你的进步指的是什么？”颜回说：“我‘坐忘’了”。孔子惊奇不安地问：“什么叫‘坐忘’？”颜回答道：“毁废了强健的肢体，退除了灵敏的听觉和清晰的视力，脱离了身躯并抛弃了智慧，从而与大道浑同相通为一体，这就叫静坐心空物我两忘的‘坐忘’。”孔子说：“与万物同一就没有偏好，顺应变化就不执滞常理。你果真成了贤人啊！我作为老师也希望能跟随学习而步你的后尘。”
子舆和子桑是好朋友，连绵的阴雨下了十日，子舆说：“子桑恐怕已经困乏而饿倒。”便包着饭食前去给他吃。来到子桑门前，就听见子桑好像在唱歌，又好像在哭泣，而且还弹着琴：“是父亲呢？还是母亲呢？是天呢？还是人呢？”声音微弱好像禁不住感情的表达，急促地吐露着歌词。
子舆走进屋子说：“你歌唱的诗词，为什么象这样？”子桑回答说：“我在探寻使我达到如此极度困乏和窘迫的人，然而没有找到。父母难道会希望我贫困吗？苍天没有偏私地覆盖着整个大地，大地没有偏私地托载着所有生灵，天地难道会单单让我贫困吗？寻找使我贫困的东西可是我没能找到。然而已经达到如此极度的困乏，还是‘命’啊！”', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf6c5e272d4b2254edc6", "shortContent": "这是一篇抒怀赋，为耶律铸晚年创作的“独醉”系列赋（《独醉园赋》《独醉园三台赋》《独醉亭赋》《独醉道者赋》）之一。全赋由三部分构成。第一部分写作者自称独醉痴仙，虽“驰声荣路”，但内心深处却“栖心化元”，向往释道的清静沉寂。既然迷醉于大道，就“殊泂酌以微言”，不计较世俗的细枝末叶了。接着发起议论，照应题目，“粤飨道者，本乎忘情；而沉世者，利乎适意。适其意而冲其气者，无捷于春酒；忘其情而凝其神者，莫优于...", "authors": ["李占鹏", "金艳霞"], "pressName": "上海辞书出版社"}, {"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf700ce818559d0649aa", "shortContent": "客曰：“嗟哉！下邑之民若是病乎？”\n关于此赋的写作时间，马积高在《赋史》中谓“作于明嘉靖初”，而毕万忱则在《中国历代赋选（明清卷）》中认为此赋“是明宪宗成化以来江南织农生产生活状况的写照”，从赋文具体描写来看，后说似更符合情理。作者弃官后徙居吴兴（今属浙江湖州），但赋中所言，当指整个江南一带。钱谦益《列朝诗集小传》丁集上言徐献忠“生平著述外，无他嗜好，《白莲》《羽扇》《芦汀》《灵泉》诸赋，皆为时人...", "authors": ["孙京荣"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed207dbb8b379ee0a1503", "shortContent": "故都金陵（今江苏南京）城内，可游览的名胜景观不少，而谭元春却独钟爱乌龙潭。究其原因，一是乌龙潭位于城内，不像游燕子矶、莫愁湖那样须费跋涉攀援之苦；二是乌龙潭幽僻而人迹罕至，又不像秦淮河附近那样烦嚣杂乱（见谭元春《初游乌龙潭记》）。因此，近而幽静的乌龙潭，对一心追求“荒寒独处，稀闻渺见”（《渚宫草序》）的谭元春来说，是很有吸引力的。万历四十七年（1619）秋，谭氏居南京期间，曾与友人三游乌龙潭，并写...", "authors": ["刘传新"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f940ce818559d07123f", "shortContent": "满少卿本来也是淮南世家子弟，后来浪游四方，落魄凤翔，在饥寒交迫中栖身客舍。邻叟焦大郎见他可怜，给予饭食，他因而每天到焦家去，认识了焦女。由于两个年轻男女的朝夕相见，不久便发生恋情，焦女为他而失贞。焦大郎知道后，虽然责备了几句，还是将女儿嫁给他。这一段情节发展得很自然很正常，也表现出焦大郎的厚道开明，气氛是和谐的、轻快的。但开头“生独跅弛不羁，浪游四方”两句，已暗示他是一个轻浮的青年。\n成婚之后，满...", "authors": ["金性尧"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9ed635634aee3f74ed", "shortContent": "江南刘医留饮于病家，酩酊而归。归舟经过隔江楼侧，得大姑召唤，醉中“一时恍惚，不复忆其既死”，欣然登楼饮茶。甚至当大姑请他治病，说到“又成鬼病，一死不堪再死”时，刘医仍然懵懂不知。直到把脉之时，才想起大姑早已亡故。但是“身在醉乡，竟不知惧”，反而引出了人死之后怎么还会有病的一段有趣的对话。看病之后，刘医又能坐下来跟大姑闲聊，并且谈锋甚健，“遍及九幽风景”。联想到刘医面对江面月色喜而长啸的情景，使人觉...", "authors": ["全岳春"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3faa34a8757d5a0fa522", "shortContent": "《水浒传》中高太尉的假子高衙内，依仗父辈“炙手可热势绝伦”的权势，为非作歹，无恶不作，强占民女，致使受害者家破人亡，连八十万禁军教头林冲这样有地位的武官都难于幸免。对这些为所欲为、作恶多端的衙内，百姓深恶痛绝，却又无可奈何，因为他们身后有居高官显爵之位的父辈作靠山。这在封建社会里，带有一定的普遍性，却又一时得不到妥善的解决。于是，善良的人们便寄希望于“家法森严”的显贵，祈望他们以森严的家法来约束和...", "authors": ["储有明"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fad0ce818559d0712ac", "shortContent": "人们常把恭维、奉承说成是戴高帽子。看，戴上一顶嵯峨切云、危乎高哉的帽子，是多么神气、威风。爱戴高帽，世人不免，而尤以官场人物为甚。这些人或大或小，都有些权，权则须威，不戴高帽子，哪得许大威风？更有甚者，一些人不满足于口头的恭维，进而贪求实际的财货，于是高帽子就由纸的变成金的、银的了，戴上那样的高帽子就更叫人敬畏了。高帽子是产生于腐朽的官僚体制，而在“三年清知府，十万雪花银”的封建社会，当官的很少不...", "authors": ["汤华泉"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42b15914587d02f67d5c", "shortContent": "《花神三妙传》，又名《白潢源三妙传》《白锦琼奇会遇》等，明代中篇传奇小说。此小说有多种版本，而以《国色天香》本最为完善。\n《国色天香》本《花神三妙传》，全篇长约二万五千言，分为十三节，每节有一小标目，依序为：“白锦琼奇会遇”“白生锦娘佳会”“饮宴赏月流连”“白生琼姐佳会”“三妙寄情倡和”“白生奇姐佳会”“四美连床夜雨”“庆节上寿会饮”“凉亭水阁风流”“玉碗卜缔姻联”“锦娘割股救亲”“奇姐临难死节”...", "authors": ["侯忠义"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42c703572034f65b6af5", "shortContent": "本篇选自清代文言笑话集《夜航船》，破额山人撰。作者自序称，吴越间夜有客船，船客为消磨长夜，往往聚坐讲述奇闻异事，作者裒辑而成此书。书中所记多滑稽谐谑之事，而在俳谐之中寓意了对世风的讽刺与箴规。《臭铜员外》一篇成功地刻画了一位吝啬鬼。\n臭铜员外钱为命首先是以病丐的形象出现在我们面前的，他遍体疮泡，惨不忍睹，蹒跚着上前向刘轩云乞药。众人叱责病丐，被刘氏制止并对众人进行了一番博爱的教育。故事本可以在刘氏...", "authors": ["宋莉华"], "pressName": "上海辞书出版社"}]', '', 'indent', 1524824917, '57ea0e75a22b9d006163de67', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10247, '庄子 · 内篇 · 应帝王', NULL, 10, 16, 0, 1, '庄子', NULL, 10064, '57b90297165abd0054bfdce7', '周', 'wen', '文', 'http://baike.baidu.com/view/2787738.htm', '', '啮缺问于王倪，四问而四不知。啮缺因跃而大喜，行以告蒲衣子。
蒲衣子曰：“而乃今知之乎？有虞氏不及泰氏。有虞氏其犹藏仁以要人，亦得人矣，而未始出于非人。泰氏其卧徐徐，其觉于于。一以己为马，一以己为牛。其知情信，其德甚真，而未始入于非人。”
肩吾见狂接舆。狂接舆曰：“日中始何以语女？”肩吾曰：“告我：君人者以己出经式义度，人孰敢不听而化诸！”狂接舆曰：“是欺德也。其于治天下也，犹涉海凿河而使蚊负山也。夫圣人之治也，治外夫？正而后行，确乎能其事者而已矣。且鸟高飞以避弋之害，鼷鼠深穴乎神丘之下以避凿之患，而曾二虫之无知？”天根游于殷阳，至蓼水之上，适遭无名人而问焉，曰：“请问为天下。”无名人曰：“去！汝鄙人也，何问之不豫也！予方将与造物者为人，厌则又乘夫莽眇之鸟，以出六极之外，而游无何有之乡，以处圹之野。汝又何为以治天下感予之心为？”又复问，无名人曰：“汝游心于淡，合气于漠，顺物自然而无容私焉，而天下治矣。”阳子居见老聃，曰：“有人于此，向疾强梁，物彻疏明，学道不倦，如是者，可比明王乎？”老聃曰：“是于圣人也，胥易技系，劳形怵心者也。且也虎豹之文来田，猿狙之便执嫠之狗来藉。如是者，可比明王乎？”阳子居蹴然曰：“敢问明王之治。”老聃曰：“明王之治：功盖天下而似不自己，化贷万物而民弗恃。有莫举名，使物自喜。立乎不测，而游于无有者也。”
郑有神巫曰季咸，知人之死生、存亡、祸福、寿夭，期以岁月旬日，若神。郑人见之，皆弃而走。列子见之而心醉，归，以告壶子，曰：“始吾以夫子之道为至矣，则又有至焉者矣。”壶子曰：“吾与汝既其文，未既其实。而固得道与？众雌而无雄，而又奚卵焉！而以道与世亢，必信，夫故使人得而相汝。尝试与来，以予示之。”明日，列子与之见壶子。出而谓列子曰：“嘻！子之先生死矣！弗活矣！不以旬数矣！吾见怪焉，见湿灰焉。”列子入，泣涕沾襟以告壶子。壶子曰：“乡吾示之以地文，萌乎不震不正，是殆见吾杜德机也。尝又与来。”明日，又与之见壶子。出而谓列子曰：“幸矣！子之先生遇我也，有瘳矣！全然有生矣！吾见其杜权矣！”列子入，以告壶子。壶子曰：“乡吾示之以天壤，名实不入，而机发于踵。是殆见吾善者机也。尝又与来。”明日，又与之见壶子。出而谓列子曰：“子之先生不齐，吾无得而相焉。试齐，且复相之。”列子入，以告壶子。壶子曰：“吾乡示之以以太冲莫胜，是殆见吾衡气机也。鲵桓之审为渊，止水之审为渊，流水之审为渊。渊有九名，此处三焉。尝又与来。”明日，又与之见壶子。立未定，自失而走。壶子曰：“追之！”列子追之不及。反，以报壶子曰：“已灭矣，已失矣，吾弗及已。”壶子曰：“乡吾示之以未始出吾宗。吾与之虚而委蛇，不知其谁何，因以为弟靡，因以为波流，故逃也。”然后列子自以为未始学而归。三年不出，为其妻爨，食豕如食人，于事无与亲。雕琢复朴，块然独以其形立。纷而封哉，一以是终。
无为名尸，无为谋府，无为事任，无为知主。体尽无穷，而游无朕。尽其所受乎天而无见得，亦虚而已！至人之用心若镜，不将不逆，应而不藏，故能胜物而不伤。
南海之帝为儵，北海之帝为忽，中央之帝为浑沌。儵与忽时相与遇于浑沌之地，浑沌待之甚善。儵与忽谋报浑沌之德，曰：“人皆有七窍以视听食息，此独无有，尝试凿之。”日凿一窍，七日而浑沌死。', '', '啮缺（nièquē）：传说中的上古贤人。隐居不仕。《庄子·天地》：“尧之师曰许由，许由之师曰啮缺，啮缺之师曰王倪。”
蒲衣子：成玄英疏：“蒲衣子，尧时贤人，年八岁，舜师之，让位不受，即被衣子也。”
乃今：如今，方今。
有虞氏：指舜。古部落名。传说其首领舜受尧禅，都蒲阪。故址在今山西省永济县东南。有：词头。
泰氏：指伏羲。
徐徐：陆德明释文引司马彪云：“徐徐，安稳貌。”；成玄英疏：“徐徐，宽缓之貌。”
于于：成玄英疏：”于于，自得之貌。”
肩吾：传说中的神名。《山海经·西山经》“西南四百里曰昆仑之丘，是实惟帝之下都，神陆吾司之”晋郭璞注：“即肩吾也。”
接舆：春秋时楚国隐士，佯狂不仕。亦以代指隐士。《论语·微子》：“楚狂接舆，歌而过孔子。”邢昺疏：“接舆，楚人，姓陆名通，字接舆也。昭王时，政令无常，乃被发佯狂不仕，时人谓之‘楚狂’也。”见”楚狂接舆歌“。
日中始：李云：“日中始，人姓名，贤者也。”崔本无“日”字，云：“中始，贤人也。”俞云：“日，犹言日者也。义见左文七年、襄二十六年、昭七年、十九年传。”
经式义度：皆谓法也。“义”通“仪”。
弋（yì）：用带绳子的箭射鸟。
鼷（xī）鼠：鼠类最小的一种。古人以为有毒，啮人畜至死不觉痛，故又称甘口鼠。
神丘：祭社神之坛。
曾（zēng）：竟，简直，还。
天根：崔曰“人姓名也”。
殷阳：殷山之阳。一说殷阳乃地名。
蓼（liǎo）水：川名，未可实考也。
豫：欢喜，快乐，安闲，舒适。
莽眇（miǎo）：成玄英疏：“莽眇，深远之谓。”
阳子居：居，名也；子，对男子的通称。姓名未可考，庄子自造者也。
向疾强梁：强梁：强劲有力；勇武。《老子》：“强梁者不得其死。”。言“办事迅疾敏捷、强干果决”
物彻疏明：陆德明释文引司马彪曰：“物，事也；彻，通也；事能通而开明也。”成玄英疏：“鉴物洞彻，疏通明敏。”
胥（xǖ）易技系：成玄英疏：“技术工巧，神虑劬劳，故形容变改；系累，故心灵怵惕也。”郭庆藩集释：“技系，若《王制》‘凡执技以事上者，不贰事，不移官’，谓为技所系也。”
怵（chù）心：犹“惊心”。
猿狙（jū）：泛指猿猴。
嫠（lí）：髦牛
藉：绳索；田：畋猎。
蹴（cù）然：亦作“蹵然”。惊惭不安貌。一说为恭敬貌。
化贷：犹言感化也。
季咸：古代神巫名。《隋书·艺术传序》：“语医，则文挚、扁鹊、季咸、华佗。”
列子：即战国时郑人列御寇。古有列子能御风之说。又为中国道教典籍之一。列子，本名列御寇，信奉道家的与世无争思想，主张循名责实，无为而治。他一生安于贫寒，不求名利，不进官场，“列子居郑圃，四十年人无识者”，农耕之馀，醉心读书著述，潜心撰文二十篇，约十万多字。流传有《列子》一书，其作品在汉代以后已部分散失，现存八篇《天瑞》、《黄帝》、《周穆王》、《仲尼》、《汤问》、《力命》、《杨朱》、《说符》。其中《愚公移山》、《杞人忧天》、《夸父追日》、《两小儿辩日》、《纪昌学射》、《黄帝神游》、《汤问》等脍炙人口的寓言故事百馀篇，篇篇珠玉，妙趣横生，且影响极大，可谓家喻户晓，广为流传。其中《两小儿辩日》被纳入小学语文六年级下册第一篇课文。
壶子：成玄英疏：“壶子，郑之得道人也。号壶子，名林，即列子之师也。”
既：一言“尽”也，一言“教授”。
亢：匹敌。
吾见怪焉，见湿灰焉：我观察到他临死前的怪异形色，神情像遇水的灰烬一样。
乡：刚才。
地文：地面山岳河海丘陵平原之形；地貌。北齐刘昼《新论·慎言》：“日月者天之文也，山川者地之文也，言语者人之文也。天文失则有谪蚀之变，地文失必有崩竭之灾，人文失必有伤身之患。”
萌乎不震不正：萌：本意指“植物发芽”；震：动；正：或指“止”。
殆：大概，几乎。
杜德机：杜：杜绝，堵塞；德机：亦作“德几”。犹生机。
杜权：谓闭塞中有所变动。王先谦集解引宣颖曰：“杜闭中觉有权变。”
天壤：天和地。~~之别。
踵：脚后跟。
善者机：未甚明白，待高人修改补充。
不齐：谓生机变化莫测，前后不一致，忽有忽无，忽静忽动。
太冲：谓极其虚静和谐的境界。《淮南子·诠言训》：“聪明虽用，必反诸神，谓之太冲。”高诱注：“冲，调也。”
衡：平衡。
鲵：或谓泛指“大鱼”。
鲵桓（huán）之审（shěn审）：或谓“大鱼盘桓逗留的地方”。
九渊：九渊之说，出于《列子》，指鲵桓、止水、流水、滥水、沃水、氿水、雍水、汧水、肥水。
自失：谓自知道行尚浅。
走：逃跑。
未始出吾宗：未甚明也，待高人补充。
委蛇（wēiyí）：同"逶迤"；成玄英疏：“委蛇，随顺之貌也。”
弟靡（mí）：谓柔顺而随波逐流。郭象注：“变化颓靡，世事波流，无往而不因也。”成玄英疏：“颓者，放任；靡者，顺从。”
爨（cuàn）：烧火做饭。
食（sì）豕（shǐ）：拿东西给猪吃，喂猪。
于事无与亲：或解为“对于各种世事不分亲疏没有偏私”。未甚明也。
块然：木然无知貌。成玄英疏：“块然，无情之貌也。”
纷而封：或谓“涉入世间的纷扰却能固守本真”。
名尸：名誉之主，谓囿于名誉。成玄英疏：“尸，主也。身尚忘遗，名将安寄？故无复为名誉之主也。”
谋府：指谋虑所从出之处。成玄英疏：“虚淡无心，忘怀任物，故无复运为谋虑於灵府耳。”
事任：犹言承担职务。郭象注：“付物使各自任。”然物可任事乎？吾于此甚惑，待高人指点。无为事任，则何以立世乎？何以养亲？人可无情乎？
知主：智慧的主宰，出主意的人。
体尽无穷：潜心地体验真源而且永不休止。
朕：我。中国秦始皇时起专用作皇帝自称，秦始皇之前普通人也可称朕。
不将不逆：未甚明也。
应而不藏：应者，指照镜子，原本地反映事物本来的面目。
儵（shū）：同“倏”。倏忽：迅疾貌。
视听食息：看，听，吃，呼吸。', '齧缺向王倪求教，四次提问王倪四次都不能作答。齧缺于是跳了起来高兴极了，去到蒲衣子处把上述情况告诉给他。
蒲衣子说：“你如今知道了这种情况吗？虞舜比不上伏羲氏。虞舜他心怀仁义以笼络人心，获得了百姓的拥戴，不过他还是不曾超脱出人为的物我两分的困境。伏羲氏他睡卧时宽缓安适，他觉醒时悠游自得；他听任有的人把自己看作马，听任有的人把自己看作牛；他的才思实在真实无伪，他的德行确实纯真可信，而且从不曾涉入物我两分的困境。”
肩吾拜会隐士接舆。接舆说：“往日你的老师日中始用什么来教导你？”肩吾说：“他告诉我，做国君的一定要凭借自己的意志来推行法度，人们谁敢不听从而随之变化呢？”
接舆说：“这是欺诳的做法，那样治理天下，就好像徒步下海开凿河道，让蚊虫背负大山一样。圣人治理天下，难道去治理社会外在的表象吗？他们顺应本性而后感化他人，听任人们之所能罢了。鸟儿尚且懂得高飞躲避弓箭的伤害，老鼠尚且知道深藏于神坛之下的洞穴逃避熏烟凿地的祸患，而你竟然连这两种小动物本能地顺应环境也不了解！”
天根闲游殷山的南面，来到蓼水河边，正巧遇上无名人而向他求教，说：“请问治理天下之事。”无名人说：“走开，你这个见识浅薄的人，怎么一张口就让人不愉快！我正打算跟造物者结成伴侣，厌烦时便又乘坐那状如飞鸟的清虚之气，超脱于‘六极’之外，而生活在什么也不存在的地方，居处于旷达无垠的环境。你又怎么能用梦呓般的所谓治理天下的话语来撼动我的心思呢？”天根又再次提问。无名人说：“你应处于保持本性、无所修饰的心境，交合形气于清静无为的方域，顺应事物的自然而没有半点儿个人的偏私，天下也就得到治理。”
阳子居拜见老聃，说：“倘若现在有这样一个人，他办事迅疾敏捷、强干果决，对待事物洞察准确、了解透彻，学‘道’专心勤奋从不厌怠。象这样的人，可以跟圣哲之王相比而并列吗？”老聃说：“这样的人在圣人看来，只不过就像聪明的小吏供职办事时为技能所拘系、劳苦身躯担惊受怕的情况。况且虎豹因为毛色美丽而招来众多猎人的围捕，猕猴因为跳跃敏捷、狗因为捕物迅猛而招致绳索的拘缚。象这样的动物，也可以拿来跟圣哲之王相比而并列吗？”阳子居听了这番话脸色顿改，不安地说：“冒昧地请教圣哲之王怎么治理天下。”老聃说：“圣哲之王治理天下，功绩普盖天下却又像什么也不曾出自自己的努力，教化施及万物而百姓却不觉得有所依赖；功德无量没有什么办法称述赞美，使万事万物各居其所而欣然自得；立足于高深莫测的神妙之境，而生活在什么也不存在的世界里。”
郑国有个占卜识相十分灵验的巫师，名叫季咸，他知道人的生死存亡和祸福寿夭，所预卜的年、月、旬、日都准确应验，仿佛是神人。郑国人见到他，都担心预卜死亡和凶祸而急忙跑开。列子见到他却内心折服如醉如痴，回来后把见到的情况告诉老师壶子，并且说：“起先我总以为先生的道行最为高深，如今又有更为高深的巫术了。”壶子说：“我教给你的还全是道的外在的东西，还未能教给你道的实质，你难道就已经得道了吗？只有众多的雌性可是却无雄性，又怎么能生出受精的卵呢！你用所学到的道的皮毛就跟世人相匹敌，而且一心求取别人的信任，因而让人洞察底细而替你看相。你试着跟他一块儿来，把我介绍给他看看相吧。”
第二天，列子跟神巫季咸一道拜见壶子。季咸走出门来就对列子说：“呀！你的先生快要死了！活不了了，用不了十来天了！我观察到他临死前的怪异形色，神情像遇水的灰烬一样。”列子进到屋里，泪水弄湿了衣襟，伤心地把季咸的话告诉给壶子。壶子说：“刚才我将如同地表那样寂然不动的心境显露给他看，茫茫然既没有震动也没有止息。这样恐怕只能看到我闭塞的生机。试试再跟他来看看。”
第二天（后一天），列子又跟神巫季咸一道拜见壶子。季咸走出门来就对列子说：“幸运啊，你的先生遇上了我！症兆减轻了，完全有救了，我已经观察到闭塞的生机中神气微动的情况。”列子进到屋里，把季咸的话告诉给壶子。壶子说：“刚才我将天与地那样相对而又相应的心态显露给他看，名声和实利等一切杂念都排除在外，而生机从脚跟发至全身。这样恐怕已看到了我的一线生机。试着再跟他一块儿来看看。”
第二天，列子又跟神巫季咸一道拜见壶子。季咸走出门来就对列子说：“你的先生心迹不定，神情恍惚，我不可能给他看相。等到心迹稳定，再来给他看相。”列子进到屋里，把季咸的话告诉给壶子。壶子说：“刚才我把阴阳二气均衡而又和谐的心态显露给他看。这样恐怕看到了我内气持平、相应相称的生机。大鱼盘桓逗留的地方叫做深渊，静止的河水聚积的地方叫做深渊，流动的河水滞留的地方叫做深渊。渊有九种称呼，这里只提到了上面三种。试着再跟他一块儿来看看。”
第二天，列子又跟神巫咸季一道拜见壶子。季咸还未站定，就不能自持地跑了。壶子说：“追上他！”列子没能追上，回来告诉壶子，说：“已经没有踪影了，让他跑掉了，我没能赶上他。”壶子说：“起先我显露给他看的始终未脱离我的本源。我跟他随意应付，他弄不清我的究竟，于是我使自己变的那么颓废顺从，变的像水波逐流一样，所以他逃跑了。”
这之后，列子深深感到像从不曾拜师学道似的回到了自己的家里，三年不出门。他帮助妻子烧火做饭，喂猪就像侍侯人一样。对于各种世事不分亲疏没有偏私，过去的雕琢和华饰已恢复到原本的质朴和纯真，像大地一样木然忘情地将形骸留在世上。虽然涉入世间的纷扰却能固守本真，并像这样终生不渝。
不要成为名誉的寄托，不要成为谋略的场所；不要成为世事的负担，不要成为智慧的主宰。潜心地体验真源而且永不休止，自由自在地游乐而不留下踪迹；任其所能禀承自然，从不表露也从不自得，也就心境清虚淡泊而无所求罢了。修养高尚的“至人”心思就象一面镜子，对于外物是来者即照去者不留，应合事物本身从不有所隐藏，所以能够反映外物而又不因此损心劳神。
南海的大帝名叫儵，北海的大帝名叫忽，中央的大帝叫浑沌。儵与忽常常相会于浑沌之处，浑沌款待他们十分丰盛，儵和忽在一起商量报答浑沌的深厚情谊，说：“人人都有眼耳口鼻七个窍孔用来视、听、吃的呼吸，唯独浑沌没有，我们试着为他凿开七窍。”他们每天凿出一个孔窍，凿了七天浑沌也就死去了。', NULL, '', 'indent', 1524824965, '57ea0e76c4c971005f80acdd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10249, '报任安书', NULL, 116, 139, 1, 4, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', 'http://baike.baidu.com/view/231273.htm', '', '太史公牛马走司马迁再拜言。少卿足下：曩者辱赐书，教以慎于接物，推贤进士为务。意气勤勤恳恳，若望仆不相师，而用流俗人之言。仆非敢如是也。仆虽罢驽，亦尝侧闻长者之遗风矣。顾自以为身残处秽，动而见尤，欲益反损，是以独郁悒而无谁语。谚曰：「谁为为之？孰令听之？」盖钟子期死，伯牙终身不复鼓琴。何则？士为知己者用，女为悦己者容。若仆大质已亏缺矣，虽才怀随和，行若由夷，终不可以为荣，适足以发笑而自点耳。书辞宜答，会东从上来，又迫贱事，相见日浅，卒卒无须臾之间，得竭指意。今少卿抱不测之罪，涉旬月，迫季冬；仆又薄从上雍，恐卒然不可讳。是仆终已不得舒愤懑以晓左右，则长逝者魂魄私恨无穷。请略陈固陋，阙然久不报，幸勿为过。
仆闻之：修身者，智之符也；爱施者，仁之端也；取与者，义之表也；耻辱者，勇之决也；立名者，行之极也。士有此五者，然后可以托于世，列于君子之林矣。故祸莫憯于欲利，悲莫痛于伤心，行莫丑于辱先，而诟莫大于宫刑。刑馀之人，无所比数，非一世也，所从来远矣。昔卫灵公与雍渠同载，孔子适陈；商鞅因景监见，赵良寒心；同子参乘，爰丝变色。自古而耻之。夫以中才之人，事有关于宦竖，莫不伤气，而况于忼慨之士乎！如今朝虽乏人，奈何令刀锯之馀荐天下豪隽哉！
仆赖先人绪业，得待罪辇毂下，二十馀年矣。所以自惟，上之，不能纳忠效信，有奇策才力之誉，自结明主；次之，又不能拾遗补阙，招贤进能，显岩穴之士；外之，不能备行伍，攻城野战，有斩将搴旗之功；下之，不能累日积劳，取尊官厚禄，以为宗族交游光宠。四者无一遂，苟合取容，无所短长之效，可见于此矣。乡者，仆亦尝厕下大夫之列，陪外廷末议。不以此时引维纲，尽思虑。今以亏形为扫除之隶，在阘茸之中，乃欲卬首信眉，论列是非，不亦轻朝廷，羞当世之士邪！嗟乎！嗟乎！如仆，尚何言哉！尚何言哉！
且事本末未易明也。仆少负不羁之才，长无乡曲之誉，主上幸以先人之故，使得奉薄技，出入周卫之中。仆以为戴盆何以望天，故绝宾客之知，忘室家之业，日夜思竭其不肖之材力，务壹心营职，以求亲媚于主上。而事乃有大谬不然者。
夫仆与李陵俱居门下，素非相善也。趣舍异路，未尝衔杯酒接殷勤之欢。然仆观其为人，自奇士，事亲孝，与士信，临财廉，取予义，分别有让，恭俭下人，常思奋不顾身以徇国家之急。其素所畜积也，仆以为有国士之风。夫人臣出万死不顾一生之计，赴公家之难，斯已奇矣。今举事壹不当，而全躯保妻子之臣随而媒孽其短，仆诚私心痛之。且李陵提步卒不满五千，深践戎马之地，足历王庭，垂饵虎口，横挑彊胡，卯亿万之师，与单于连战十馀日，所杀过当。虏救死扶伤不给，旃裘之君长咸震怖，乃悉徵其左右贤王，举引弓之民，一国共攻而围之。转斗千里，矢尽道穷，救兵不至，士卒死伤如积。然陵一呼劳军，士无不起，躬自流涕，沬血饮泣，张空弮，冒白刃，北向争死敌者。陵未没时，使有来报，汉公卿王侯皆奉觞上寿。后数日，陵败书闻，主上为之食不甘味，听朝不怡。大臣忧惧，不知所出。仆窃不自料其卑贱，见主上惨悽怛悼，诚欲效其款款之愚，以为李陵素与士大夫绝甘分少，能得人之死力，虽古之名将，不能过也。身虽陷败，彼观其意，且欲得其当而报汉。事已无可柰何，其所摧败，功亦足以暴于天下矣。仆怀欲陈之，而未有路，适会召问，即以此指推言陵之功，欲以广主上之意，塞睚眦之辞。未能尽明，明主不深晓，以为仆沮贰师，而为李陵游说，遂下于理。拳拳之忠，终不能自列。因为诬上，卒从吏议。家贫，财赂不足以自赎，交游莫救；左右亲近不为壹言。身非木石，独与法吏为伍，深幽囹圄之中，谁可告愬者！此正少卿所亲见，仆行事岂不然邪？李陵既生降，隤其家声；而仆又茸以蚕室，重为天下观笑。悲夫！悲夫！事未易一二为俗人言也。
仆之先人，非有剖符丹书之功，文史星历近乎卜祝之间，固主上所戏弄，倡优畜之，流俗之所轻也。假令仆伏法受诛，若九牛亡一毛，与蝼蚁何异？而世又不与能死节者比，特以为智穷罪极，不能自免，卒就死耳。何也？素所自树立使然也。人固有一死，死有重于泰山，或轻于鸿毛，用之所趋异也。太上不辱先，其次不辱身，其次不辱理色，其次不辱辞令，其次诎体受辱，其次易服受辱，其次关木索被棰楚受辱，其次剔剃毛发婴金铁受辱，其次毁肌肤断支体受辱，最下腐刑，极矣。传曰：「刑不上大夫。」此言士节不可不厉也。猛虎处深山，百兽震恐，及其在阱槛之中，摇尾而求食，积威约之渐也。故士有画地为牢势不入，削木为吏议不对，定计于鲜也。今交手足，受木索，暴肌肤，受榜棰，幽于圜墙之中。当此之时，见狱吏则头枪地，视徒隶则正惕息。何者？积威约之势也。及已至此，言不辱者，所谓彊颜耳，曷足贵乎！且西伯，伯也，拘于牖里；李斯，相也，具于五刑；淮阴，王也，受械于陈；彭越、张敖，南乡称孤，系狱具罪；绛侯诛诸吕，权倾五伯，囚于请室；魏其，大将也，衣赭衣，关三木；季布为朱家钳奴；灌夫受辱居室。此人皆身至王侯将相，声闻邻国，及罪至罔加，不能引决自裁，在尘埃之中，古今一体，安在其不辱也！由此言之，勇怯，势也；强弱，形也。审矣！曷足怪乎？且夫人不能蚤自财绳墨之外，以稍陵夷至于鞭棰之间，乃欲引节，斯不亦远乎！古人所以重施刑于大夫者，殆为此也。
夫人情莫不贪生恶死，念亲戚，顾妻子，至激于义理者不然，乃有所不得已也。今仆不幸，蚤失二亲，无兄弟之亲，独身孤立，少卿视仆于妻子何如哉？且勇者不必死节，怯夫慕义，何处不勉焉！仆虽怯懦耎欲苟活，亦颇识去就之分矣，何至自湛溺累绁之辱哉！且夫臧获婢妾犹能引决，况若仆之不得已乎！所以隐忍苟活，函粪土之中而不辞者，恨私心有所不尽，鄙没世而文采不表于后也。
古者富贵而名摩灭，不可胜记，唯倜傥非常之人称焉。盖文王拘而演周易；仲尼厄而作春秋；屈原放逐，乃赋离骚；左丘失明，厥有国语；孙子膑脚，兵法修列；不韦迁蜀，世传吕览；韩非囚秦，说难、孤愤。诗三百篇，大抵圣贤发愤之所为作也。此人皆意有所郁结，不得通其道，故述往事，思来者。及如左丘明无目，孙子断足，终不可用，退而论书策以舒其愤，思垂空文以自见。
仆窃不逊，近自托于无能之辞，网罗天下放失旧闻，考之行事，综其终始，稽其成败兴坏之理，上计轩辕，下至于兹，为十表，本纪十二，书八章，世家三十，列传七十，凡百三十篇，亦欲以究天人之际，通古今之变，成一家之言。草创未就，适会此祸，惜其不成，是以就极刑而无愠色。仆诚已著此书，藏诸名山，传之其人通邑大都，则仆偿前辱之责，虽万被戮，岂有悔哉！然此可为智者道，难为俗人言也。
且负下未易居，下流多谤议，仆以口语遇遭此祸，重为乡党戮笑，污辱先人，亦何面目复上父母丘墓乎？虽累百世，垢弥甚耳！是以肠一日而九回，居则忽忽若有所亡，出则不知所如往。每念斯耻，汗未尝不发背沾衣也。身直为闺閤之臣，宁得自引深臧于岩穴邪？故且从俗浮沉，与时俯仰，以通其狂惑。今少卿乃教以推贤进士，无乃与仆之私心剌谬乎。今虽欲自雕瑑，曼辞以自解，无益，于俗不信，祗取辱耳。要之，死日然后是非乃定。书不能悉意，故略陈固陋，谨再拜。', '', '太史公：太史公不是自称，也不是公职，汉代只有太史令一职，且古人写信不可能自称公。钱穆认为，《史记》原名是《太史公》。
牛马走：谦词，意为如牛马一样以供奔走。走，意同「仆」。此十二字《汉书·司马迁传》无，据《文选》补。意思是太史公为了《史记》一书像当牛做马一样活着。
曩（nǎng）者：从前。
望：埋怨。
流俗人：世俗之人
罢：同「疲」。
驽：劣马，疲弩：比喻才能低下。
侧闻：从旁听说。犹言「伏闻」，自谦之词。
身残处秽：指因受宫刑而身体残缺，兼与宦官贱役杂处。
锺子期、伯牙：春秋时楚人。伯牙善鼓琴，锺子期知音。锺子期死后，伯牙破琴绝弦，终身不复鼓琴。事见《吕氏春秋·本味篇》。
随、和：随侯之珠和和氏之璧，是战国时的珍贵宝物。
由、夷：许由和伯夷，两人都是西周早期被推为品德高尚的人。
点：玷污。
会东从上来：太始四年（公元前九十三年）三月，汉武帝东巡泰山，四月，又到海边的不其山，五月间返回长安。太史公从驾而行。
卒卒：同「猝猝」，匆匆忙忙的样子。
季冬：冬季的第三个月，即十二月。
汉律：每年十二月处决囚犯。
薄：同「迫」。
上雍：地名，在今陕西凤翔县南，设有祭祀五帝的神坛五畤。《汉书·郊祀志》句“其秋上雍，且郊”，有注“雍地形高，故云上也”。
不可讳：死的委婉说法。任安这次下狱，后被汉武帝赦免。但两年之后，任安又因戾太子事件被处腰斩。
宫刑：一种破坏男性生殖器的刑罚，也称「腐刑」。
「卫灵公」二句：春秋时，卫灵公和夫人乘车出游，让宦官雍渠同车，而让孔子坐后面一辆车。孔子深以为耻辱，就离开了卫国。事见《孔子家语》。这里说「适陈」，未详。
「商鞅」二句：商鞅得到秦孝公的支持变法革新。景监是秦孝公宠信的宦官，曾向秦孝公推荐商鞅。赵良是秦孝公的臣子，与商鞅政见不同。事见《史记·商君列传》：「赵良谓商君曰：……今君之相秦也，因嬖人景监以为主，非所以为名也。」
「同子」二句：同子指汉文帝的宦官赵谈，因为与太史公的父亲司马谈同名，避讳而称「同子」。爰同「袁」。爰丝即袁丝，亦即袁盎，汉文帝时任郎中。据载，文帝坐车去看他母亲时，宦官陪乘，袁盎伏在车前说：「臣闻天子所与共六尺舆者，皆天下豪英，今汉虽乏人，奈何与刀锯之馀共载？」于是文帝只得依言令赵谈下车。事见《汉书·袁盎列传》。
竖：供役使的小臣。后泛指卑贱者。
忼慨：慷慨。
待罪：做官的谦词。
辇毂下：皇帝的车驾之下。代指京城长安。
惟：思考。
搴（qiān）：拔取。
乡：通「向」。
厕：参与。
下大夫：太史令官位较低，属下大夫。
外廷：汉制，凡遇疑难不决之事，则令群臣在外廷讨论。
末议：微不足道的意见。「陪外廷末议」是谦词。
维纲：国家的法令。
闒茸（tǎróng）：下贱，低劣。
卬：同「昂」。信：同「伸」：
乡曲：乡里。汉文帝为了询访自己治理天下的得失，诏令各地「举贤良方正能直言切谏者」，亦即有乡曲之誉者，选以授官，二句言太史公未能由此途径入仕。
周卫：周密的护卫，即宫禁。
戴盆何以望天：当时谚语，形容忙于职守，识见浅陋，无暇他顾。
李陵：字少卿，生活在汉武帝在位年间，西汉名将李广之孙，善骑射，官至骑都尉，率兵出击匈奴贵族，战败投降，封右校王。后病死匈奴。
俱居门下：太史公曾与李陵同在「侍中曹」（官署名）内任侍中。
趣舍：向往和废弃。趣，同「趋」。
衔杯酒：在一起喝酒。指私人交往。
媒孽：也作「孽」，酵母。这里是夸大的意思。
王庭：匈奴单于的居处。
彊：同「强」。
胡：指匈奴。
卬：即「仰」，仰攻。当时李陵军被围困谷地。
旃：毛织品。《史记·匈奴列传》：「自君王以下，咸食肉，衣其皮革。披旃裘。」
左右贤王：左贤王和右贤王，匈奴封号最高的贵族。
沬：以手掬水洗脸。
弮：强硬的弓弩。
上寿：这里指祝捷。
怛：悲痛。
款款：忠诚的样子。
士大夫：此指李陵的部下将士。
绝甘：舍弃甘美的食品。
分少：即使所得甚少也平分给众人。
睚眦：怒目相视。
沮：毁坏。
贰师：贰师将军李广利，汉武帝宠妃李夫人之兄。李陵被围时，李广利并未率主力救授，致使李陵兵败。其后太史公为李陵辨解，武帝以为他有意诋毁李广利。
理：掌司法之官。
囹圄：监狱。
聩：坠毁。李陵是名将之后，据《史记·李将军列传》记载：「单于既得陵，素闻其家声，以女妻陵而贵之。自是之后，李氏名败。」
茸：推置其中。
蚕室：温暖密封的房子。言其象养蚕的房子。初受腐刑的人怕风，故须住此。
剖符：把竹做的契约一剖为二，皇帝与大臣各执一块，上面写着同样的誓词，说永远不改变立功大臣的爵位。
丹书：把誓词用丹砂写在铁制的契券上。凡持有剖符、丹书的大臣，其子孙犯罪可获赦免。
文史星历：史籍和天文历法，都属太史令掌管。
蝼螘：蝼蚁。螘，同「蚁」。
易服：换上罪犯的服装。古代罪犯穿赭（深红）色的衣服。
木索：木枷和绳索。
鬀：同「剃」，把头髮剃光，即髡刑。
婴：环绕。颈上带着铁链服苦役，即钳刑。
腐刑：即宫刑。
刑不上大夫：《礼记·曲礼》中语。
穽：捕兽的陷坑。
槛：关兽的笼子。
鲜：态度鲜明。即自杀，以示不受辱。
榜：鞭打。
棰：竹棒。此处用作动词。
枪：同「抢」。
惕息：胆战心惊。
西伯：即周文王，为西方诸侯之长。伯也：伯通「霸」。
牖里：又作「羑里」，在今河南汤阴县。周文王曾被殷纣王囚禁于此。
李斯：秦始皇时任为丞相，后因秦二世听信赵高谗言，被受五刑，腰斩于咸阳。
五刑：秦汉时五种刑罚，见《汉书·刑法志》：「当三族者，皆先黥劓，斩左右趾，笞杀之，枭其首，葅其骨肉于市。」
淮阴：指淮阴侯韩信。
受械于陈：汉立，淮阴侯韩信被刘邦封为楚王，都下邳（今江苏邳县）。后高祖疑其谋反，用陈平之计，在陈（楚地）逮捕了他。械，拘禁手足的木制刑具。
彭越：汉高祖的功臣。
张敖：汉高祖功臣张耳的儿子，袭父爵为赵王。彭越和张敖都因被人诬告称孤谋反，下狱定罪。
绛侯：汉初功臣周勃，封绛侯。惠帝和吕后死后，吕后家族中吕产、吕禄等人谋夺汉室，周勃和陈平一起定计诛诸吕，迎立刘邦中子刘恒为文帝。
五伯：即「五霸」。
请室：大臣犯罪等待判决的地方。周勃后被人诬告谋反，囚于狱中。
魏其：大将军窦婴，汉景帝时被封为魏其侯。武帝时，营救灌夫，被人诬告，下狱判处死罪。
三木：头枷、手铐、脚镣。
季布：楚霸王项羽的大将，曾多次打击刘邦。项羽败死，刘邦出重金缉捕季布。季布改名换姓，受髡刑和钳刑，卖身给鲁人朱家为奴。
灌夫：汉景帝时为中郎将，武帝时官太仆。因得罪了丞相田蚡，被囚于居室，后受诛。
居室：少府所属的官署。
耎：「软」的古字。
湛：同「沉」。累绁捆绑犯人的绳子，引伸为捆绑、牢狱。
臧获：奴曰臧，婢曰获。
俶傥：豪迈不受拘束。
西伯拘而演《周易》：传说周文王被殷纣王拘禁在牖里时，把古代的八卦推演为六十四卦，成为《周易》的骨干。
仲尼厄而作春秋：孔丘字仲尼，周遊列国宣传儒道，在陈地和蔡地受到围攻和绝粮之苦，返回鲁国作《春秋》一书。
屈原：曾两次被楚王放逐，幽愤而作《离骚》。
左丘：春秋时鲁国史官左丘明。
《国语》：史书，相传为左丘明撰著。
孙子：春秋战国时著名军事家孙膑。膑脚：孙膑曾与庞涓一起从鬼谷子习兵法。后庞涓为魏惠王将军，骗膑入魏，割去了他的膑骨（膝盖骨）。孙膑有《孙膑兵法》传世。
不韦：吕不韦，战国末年大商人，秦初为相国。曾命门客著《吕氏春秋》（一名《吕览》）。始皇十年，令吕不韦举家迁蜀，吕不韦自杀。
韩非：战国后期韩国公子，曾从荀卿学，入秦被李斯所谗，下狱死。著有《韩非子》，《说难》、《孤愤》是其中的两篇。
《诗》三百篇：今本《诗经》共有三百零五篇，此举其成数。
失：读为「佚」。
愠：怒。
戮笑：辱笑。
九回：九转。形容痛苦之极。
闺閤之臣：指宦官。闺、閤都是宫中小门，代指禁宫。
雕琢：修饰，美化。这里指自我妆饰。', '像牛马一样替人奔走的仆役太史公司马迁再拜。
少卿足下：从前承蒙您给我写信，教导我用谨慎的态度在待人接物上，以推举贤能、引荐人才为己任，情意十分恳切诚挚，好像抱怨我没有遵从您的教诲，而是追随了世俗之人的意见。我是不敢这样做的。我虽然平庸无能，但也曾听到过德高才俊的前辈遗留下来的风尚。只是我自认为身体已遭受摧残，又处于污浊的环境之中，每有行动便受到指责，想对事情有所增益，结果反而自己遭到损害，因此我独自忧闷而不能向人诉说。俗话说：「为谁去做，教谁来听？」鍾子期死了，伯牙便一辈子不再弹琴。这是为什么呢？贤士乐于被了解自己的人所用，女子为喜爱自己的人而打扮。像我这样的人，身躯已经亏残，即使才能像随侯珠、和氏璧那样稀有，品行像许由、伯夷那样高尚，终究不能把这些当做光荣，只不过足以被人耻笑而自取污辱。
来信本应及时答复，刚巧我侍从皇上东巡回来，后又为烦琐之事所逼迫，能见面的日子很少，我又匆匆忙忙地没有片刻的闲工夫来详尽地表达心意。您蒙受意想不到的罪祸，再过一月，临近十二月，我侍从皇上到雍县去的日期也迫近了，恐怕突然之间您就会有不幸之事发生，因而使我终生不能向您抒发胸中的愤懑，那么与世长辞的灵魂会永远留下无穷的遗憾。请让我向您略约陈述浅陋的意见。隔了很长的日子没有复信给您，希望您不要责怪。
我听到过这样的说法：一个人如何修身，是判断他智慧的凭证；能够自修其身，这是有智慧的凭证。能够怜爱别人，乐于施舍，这是行仁德的开始。取和予是否得当，这是衡量义与不义的标志。看一个人对耻辱采取什么态度，就可以决断他是否勇敢。建立好的名声，这是德行的最高准则。志士有这五种品德，然后就可以立足于社会，排在君子的行列中了。所以，没有什么灾祸比贪图私利更惨的了。没有什么悲哀比伤创心灵更为可悲了。没有什么行为比使先人受辱这件事更丑恶了，没有什么耻辱比遭受宫刑更严重了。受过宫刑后获得馀生的人，社会地位是没法比类的，这并非当今之世如此，这种情况从开始以来已经很久了。从前卫灵公与宦官雍渠同坐一辆车子，孔子感到这对他是一种侮辱，便离开卫国到陈国去，商鞅通过姓景的太监而得以谒见秦孝公，贤士赵良为此担忧；太监赵谈陪坐在汉文帝的车上，袁盎为之脸色大变。自古以来，人们把与刑馀之人相并列当做一种耻辱。就一般才智的人来说，一旦事情关系到宦官，没有不感到伤心丧气的，更何况气节高尚的人呢？如今朝廷虽然缺乏人才，但怎么会让一个受过刀锯摧残之刑的人，来推荐天下的豪杰俊才呢？我凭着先父遗留下来的事业，纔能够在京城任职，到已二十多年了。我常常这样想：上不能对君王进纳忠言，献出诚实的心意，而有出谋划策的称誉，从而得到皇上的信任；其次，又不能给皇上拾取遗漏，补正阙失，招纳贤才，推举能人，使隐居在岩穴中的贤士不至被埋没；对外，又不能备数于军队之中，参加攻城野战，以建立斩将夺旗的功劳；从最次要的方面来看，又不能积累老资格，在言论方面立功，谋得尊贵的官职，优厚的俸禄，来为宗族和朋友争光。这四个方面没有哪一方面做出成绩，我只能有意地迎合皇上的心意，以保全自己的地位。我没有些微的建树，从这四方面就可以看出来了。以前，我也曾夹杂在下大夫的行列，跟在外朝官员的后面发表一些微不足道的议论。我没有利用这个机会申张国家的法度，竭尽自己的思虑，到如今已经身体残废成为打扫污秽的奴隶，处在地位卑贱的人的行列当中，还想昂首扬眉，评论是非，不也是轻视朝廷、使当世的君子们感到羞耻吗？唉！唉！像我这样的人，尚且说什么呢？尚且说什么呢？
而且，事情的前因后果一般人是不容易弄明白的。我在少年的时候就没有卓越不羁的才华，成年以后也没有得到乡里的称誉，幸亏皇上因为我父亲是太史令，使我能够获得奉献微薄才能的机会，出入宫禁之中。我认为头上顶着盆子就不能望天，所以断绝了宾客的往来，忘掉了家室的事务，日夜都在考虑全部献出自己的微不足道的才幹和能力，专心供职，以求得皇上的信任和宠幸。但是，事情与愿望违背太大，不是原先所料想的那样。我和李陵都在朝中为官，向来并没有多少交往，追求和反对的目标也不相同，从不曾在一起举杯饮酒，互相表示友好的感情。但是我观察李陵的为人，确是个守节操的不平常之人：奉事父母讲孝道，同朋友交往守信用，遇到钱财很廉洁，或取或予都合乎礼义，能分别长幼尊卑，谦让有礼，恭敬谦卑自甘人下，总是考虑着奋不顾身来赴国家的急难。他历来积铸的品德，我认为有国士的风度。做人臣的，从出于万死而不顾一生的考虑，奔赴国家的危难，这已经是很少见的了。现今他行事一有不当，而那些只顾保全自己性命和妻室儿女利益的臣子们，便跟着挑拨是非，夸大过错，陷人于祸，我确实从内心感到沉痛。况且李陵带领的兵卒不满五千，深入敌人军事要地，到达单于的王庭，好像在老虎口上垂挂诱饵，向强大的胡兵四面挑战，面对着亿万敌兵，同单于连续作战十多天，杀伤的敌人超过了自己军队的人数，使得敌人连救死扶伤都顾不上。匈奴君长都十分震惊恐怖，于是就征调左、右贤王，出动了所有会开弓放箭的人，举国上下，共同攻打李陵并包围他。李陵转战千里，箭都射完了，进退之路已经断绝，救兵不来，士兵死伤成堆。但是，当李陵振臂一呼，鼓舞士气的时候，兵士没有不奋起的，他们流着眼泪，一个个满脸是血，强忍悲泣，拉开空的弓弦，冒着白光闪闪的刀锋，向北拼死杀敌。当李陵的军队尚未覆没的时候，使者曾给朝廷送来捷报，朝廷的公卿王侯都举杯为皇上庆贺。几天以后，李陵兵败的奏书传来，皇上为此而饮食不甜，处理朝政也不高兴。大臣们都很忧虑，害怕，不知如何是好。我私下里并未考虑自己的卑贱，见皇上悲伤痛心，实在想尽一点我那款款愚忠。我认为李陵向来与将士们同甘共苦，能够换得士兵们拼死效命的行动，即使是古代名将恐怕也没能超过的。他虽然身陷重围，兵败投降，但看他的意思，是想寻找机会报效汉朝。事情已经到了无可奈何的地步，但他摧垮、打败敌军的功劳，也足以向天下人显示他的本心了。我内心打算向皇上陈述上面的看法，而没有得到适当的机会，恰逢皇上召见，询问我的看法，我就根据这些意见来论述李陵的功劳，想以此来宽慰皇上的胸怀，堵塞那些攻击、诬陷的言论。我没有完全说清我的意思，圣明的君主不深入了解，认为我是攻击贰师将军，而为李陵辩解，于是将我交付狱官处罚。我的虔敬和忠诚的心意，始终没有机会陈述和辩白，被判了诬上的罪名，皇上终于同意了法吏的判决。我家境贫寒，微薄的钱财不足以拿来赎罪，朋友们谁也不出面营救，皇帝左右的亲近大臣又不肯替我说一句话。我血肉之躯本非木头和石块，却与执法的官吏在一起，深深地关闭在牢狱之中，我向谁去诉说内心的痛苦呢？这些，正是少卿所亲眼看见的，我的所作所为难道不正是这样吗？李陵投降以后，败坏了他的家族的名声，而我接着被置于蚕室，更被天下人所耻笑，可悲啊！可悲！
这些事情是不容易逐一地向俗人解释的。我的祖先没有剖符丹书的功劳，职掌文献史料、天文历法工作的官员，地位接近于算卦、赞礼的人，本是皇上所戏弄并当作倡优来畜养的人，是世俗所轻视的。假如我伏法被杀，那好像是九牛的身上失掉一根毛，同蝼蚁又有什么区别？世人又不会拿我之死与能殉节的人相比，只会认为我是智尽无能、罪大恶极，不能免于死刑，而终于走向死路罢了！为什么会这样呢？这是我向来所从事的职业以及地位，使人们会这样地看待自己。人本来就有一死，但有的人死得比泰山还重，有的人死的却比鸿毛还轻，这是因为他们用死追求的目的不同啊！一个人最重要的是不使祖先受辱，其次是不能使身体受辱，其次是不能因自己的脸色不合礼仪而受辱，其次是不能因为自己的言语不当而受辱，其次是使肢体受扭曲（长跪、被可捆绑）而受辱，其次是穿上囚服受辱，其次是带上木枷，遭受杖刑而受辱，其次是被剃光头发、颈戴枷锁而受辱，其次是毁坏肌肤、断肢截体而受辱，最下等的是宫刑了，侮辱到了极点。古书说"刑不上大夫"，这句话的意思是说，对于士大夫的气节，不可不劝勉鼓励啊（鼓励士大夫在犯罪以后勇于自杀，自杀就坚守了士大夫的气节）。猛虎生活在深山之中，百兽就都震恐，等到它落入陷阱和栅栏之中时，就只得摇着尾巴乞求食物，这是人不断地使用威力和约束而逐渐使它驯服的。所以，士子看见画地为牢而决不进入，面对削木而成的假狱吏也决不能接受他的审讯，把思虑计谋定在自我了断上面。如今我的手脚捆在一起，被木枷锁住、绳索捆绑，皮肉暴露在外，受着棍打和鞭笞，关在牢狱之中。在这种时候，看见狱吏就叩头触地，看见牢卒就恐惧喘息。这是为什么呢？这是经过长时间的威逼约束所造成的形势。事情已经到了这种地步，再谈什么不受污辱，那就是人们常说的厚脸皮了，有什么值得尊贵的呢？况且，像西伯姬昌，是诸侯的领袖，曾被拘禁在羑里；李斯，是丞相，也受尽了五刑；淮阴侯韩信，被封为王，却在陈地被戴上刑具；彭越、张敖被诬告有称帝野心，被捕入狱并定下罪名；绛侯周勃，曾诛杀诸吕，一时间权力大于春秋五霸，也被囚禁在请罪室中；魏其侯窦婴，是一员大将，也穿上了红色的囚衣，手、脚、颈项都套上了刑具；季布以铁圈束颈卖身给朱家当了奴隶；灌夫被拘于居室而受屈辱。这些人的身份都到了王侯将相的地位，声名传扬到邻国，等到犯了罪而法网加身的时候，不能够下决心自杀，处在污秽屈辱的地位。古今都是一样的，哪里能不受辱呢？照这样说来，勇敢或怯懦，乃是形势所造成；坚强或懦弱，也是根据自己外在的表现所决定。这是很清楚明白的事了，有什么奇怪的呢？况且人不能早一点在被法律制裁之前就自杀，因此渐渐地衰败，到了挨打受刑的时候，纔想到伸张士大夫的名节，这种愿望和现实不是相距太远了吗？古人之所以慎重地对大夫用刑，大概就是因为这个缘故。
人之常情，没有谁不贪生怕死的，都挂念父母，顾虑妻室儿女。至于那些激愤于正义公理的人当然不是这样，这里有迫不得已的情况。如今我很不幸，早早地失去双亲，又没有兄弟互相爱护，独身一人，孤立于世，少卿你看我对妻室儿女又怎样呢？况且一个勇敢的人不一定要为名节去死，怯懦的人如果仰慕大义，什么地方不可以勉励自己去死节呢？我虽然怯懦软弱，想苟活在人世，但也稍微懂得区分弃生就死的界限，哪会自甘沉溺于牢狱生活而忍受屈辱呢？再说奴隶婢妾尚且能够下决心自杀，何况像我到了这样不得已的地步！我之所以忍受着屈辱苟且活下来，陷在污浊的监狱之中却不肯死，是遗憾我内心的志愿有未达到的，如果平平庸庸地死了，文章就不能在后世显露。
古时候富贵但名字磨灭不传的人，无法完整地记录，只有那些卓越洒脱不平常的人才被称颂。（那就是：）周文王被拘禁而推演了《周易》；孔子受困窘而作《春秋》；屈原被放逐，纔写了《离骚》；左丘明失去视力，纔有《国语》；孙膑被截去膝盖骨，《兵法》纔被撰写出来；吕不韦被贬谪到蜀地，后世纔流传着《吕氏春秋》；韩非被囚禁在秦国，写出《说难》《孤愤》；《诗经》三百篇，大致是一些圣贤们抒发愤慨而写作的。这些人都是（因为）感情有压抑郁结不解的地方，不能实现其理想，所以记述过去的事迹，使将来的人深思。就像左丘明没有了视力，孙膑断了双脚，终生不能被人重用，便退隐著书立说来抒发他们的怨愤，想到活下来从事著作来表现自己的思想。
我私下里也自不量力，用我那不高明的文辞，收集天下散失的历史传闻，粗略地考订其真实性，综述其事实的本末，推究其成败盛衰的道理，上自黄帝，下至于当今，写成十篇表，十二篇本纪，八篇书，三十篇世家，七十篇列传，一共一百三十篇，也是想研究自然现象和人类社会之间的关系，贯通古往今来变化的脉络，成为一家的言论。刚开始草创还没有成书，恰恰遭遇到这场灾祸，我痛惜这部书不能完成，因此受到最残酷的刑罚也没有怨怒之色。我确实想完成这本书，把它（暂时）藏在名山之中，（以后）再传给跟自己志同道合的人，再让它广传于天下。那么，我便抵偿了以前所受的侮辱，即使受再多的侮辱，难道会后悔吗？然而，这些只能向有见识的人诉说，却很难向世俗之人讲清楚啊！
再说，戴罪被侮辱的处境是很不容易安生的，地位卑贱的人，往往被人诽谤和议论。我因为多嘴说了几句话而遭遇这场大祸，更被乡里之人、朋友羞辱和嘲笑，污辱了祖宗，又有什么颜面再到父母的坟墓上去祭扫呢？即使是到百代之后，这污垢和耻辱会更加深重啊！因此在肺腑中肠子里每日多次回转，在家中心神不定，好像失去了什么东西一样；出门则不知道往哪儿走。每当想到这件耻辱的事，冷汗没有不从脊背上冒出来而沾湿衣襟的。我已经成了宦官，怎么能够自己引退，深深地在山林岩穴隐居呢？所以只得随俗浮沉，跟着形势上下，以表现我狂放和迷惑不明。如今少卿竟教导我要推贤进士，岂不是与我自己的内心愿望相违背的吗？现今我虽然想自我雕饰一番，用美好的言辞来为自己开脱，这也没有好处，因为世俗之人是不会相信的，只会使我自讨侮辱啊。简单地说，人要到死后的日子，然后是非纔能够论定。书信是不能完全表达心意的，因而只是略微陈述我愚执、浅陋的意见罢了。恭敬地拜两次。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d82cee9a0c24edae36", "shortContent": "这是我国古典文学史上第一篇富于抒情性的长篇书信。据书中“会东从上来”及“薄从上雍”二事，司马迁写这封信，在汉武帝太始四年（前93）冬。致书的对象任少卿，名安，这时下狱。旧说，安这次下狱被处死。然据王国维《太史公行年考》，任安诛死，是坐戾太子案，当在征和二年（前91），褚少孙在《史记·田叔列传》后面补叙任安事，载武帝语：“任安有当死之罪甚众，吾尝活之。”则太始四年之狱，安或再遇赦，后死于北军护军使者...", "authors": ["陈祥耀"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "6471a55eb6a81d0c5329a1c5", "shortContent": "这是我国古典文学史上第一篇富于抒情性的长篇书信。据书中“会东从上来”及“薄从上雍”二事，司马迁写这封信，在汉武帝太始四年（前93 ）冬。致书的对象任少卿，名安，这时下狱。任安下狱前，司马迁任中书谒者令，掌“领赞尚书，出入奏事”，职属宫廷机要，安要他“推贤进士”，为朝廷荐举人才。司马迁自以为前数年因李陵事下狱，受过“腐刑”，是莫大的耻辱，不配做这种事。在信中，引证古今，抒发愤懑，对当时的现实及其自身...", "authors": ["陈祥耀"], "pressName": "上海辞书出版社"}]', '明末清初文学家金圣叹《天下才子必读书》：学其疏畅，再学其郁勃；学其迂回，再学其直注；学其阔略，再学其细琐；学其径遂，再学其重复。一篇文字，凡作十来番学之，恐未能尽也。
清代学者李晚芳《读史管见》：此篇与《自序》，俱原作史之由。《自序》重承先继圣，此重惜死立名。《自序》悲惋，此则沉郁雄健。其操纵起落，俱挟浩气流行，如怒马奔驰，不可羁勒，与《史记》之雅洁稍异，是史公另一种豪放激宕之文。盖因救友陷刑，满肚皮拂郁不平之气，借此发泄。书中「舒愤懑」是此本旨，故篇中处处皆愤懑之辞。纵横跌宕，慷慨淋漓，转折提接虽多，却如一气呵成。挣眉裂眦而写之，骤读无不为之惋惜。
明代学者孙月峰《评注昭明文选》：直抒胸臆，发挥又发挥，唯恐倾吐不尽，读之使人慷慨激烈，唏嘘欲绝，真是有大力量大文字。
林损斋《古文析义·二编》：是书反覆数千百言，其叙受刑处，只点出「仆沮贰师」四字，是非自见。所谓「舒愤懑以晓左右」者，此也。结穴在受辱不死、著书自见上。通篇淋漓悲壮，如泣如诉，自始至终，似一气呵成。盖缘胸中积愤不能自遏，故借少卿「推贤进土」之语，做个题目耳。读者逐段细绎，如见其慷慨激烈，须眉欲动。班掾讥其不能以智自全，犹是流俗之见也夫。
近代著名学者钱鍾书《管锥编》：「太上不辱」云云，每下愈况，循次九而至底，「不辱」四，「受辱」五，事归一致而词判正反，变化以避呆板，得不谓为有意为文耶？……此书情文相生，兼纡徐卓荦之妙，后人口沫手胝，遂多仿构。李陵《重报苏武书》、刘知几《史通·杂说》下以来论定为赝托者，实效法迁此篇而作。杨恽《报孙会宗书》亦师其意。恽于迁为外孙，如何无忌之似舅矣。泻瓶有受，传灯不绝。', 'indent', 1468663746, '57b8f615df0eea00633499f2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10251, '贺新郎 · 读史', NULL, 78, 106, 2, 1, '毛泽东', NULL, 10025, '57b8fb582e958a005fa52193', '当代', 'ci', '词', 'http://baike.baidu.com/view/328869.htm', '', '人猿相揖别。只几个石头磨过，小儿时节。铜铁炉中翻火焰，为问何时猜得？不过几千寒热。人世难逢开口笑，上疆场彼此弯弓月。流遍了，郊原血。
一篇读罢头飞雪，但记得斑斑点点，几行陈迹。五帝三皇神圣事，骗了无涯过客。有多少风流人物。盗跖庄蹻流誉后，更陈王奋起挥黄钺。歌未竟，东方白。', '诗人写的这首《贺新郎·读史》就是自己一生读书，尤其是读中国历史书的艺术性的总结，充满诗情画意及历史唯物主义的特点。这首诗从人类诞生一直写到社会主义，纵贯几百万年的历史，而着墨仅仅一百一十五个字，的确是气象恢宏，古今罕见。', '石头磨过：把石头磨成石器。石器时代是人类的“小儿时节”。
铜铁炉中翻火焰：指青铜器时代和铁器时代。青铜器和铁器都要用炉火来冶炼和翻铸。
不过几千寒热：这里作六字句，是此调的一体。赵朴初提出，照词律，这里一般是七字句，当作“不过是几千寒热”，可能写漏一个字。青铜器时代和铁器时代只经过几千年，和石器时代经过几十万年不同，说明人类的进化越来越快。
“人世难逢开口笑，上疆场彼此弯弓月”句：前句用唐杜牧《九日齐山登高》句：“尘世难逢开口笑”。全句指人类过去的历史充满了各种苦难和战争。北宋苏轼《江城子·密州出猎》：“会挽雕弓如满月”。
五帝三皇神圣事：传说中国上古有三皇五帝，具体说法不一，总之都被认为是最高尚最有才能的神圣人物。
盗跖（zhí）：跖被古代统治阶级污蔑为“盗”，后来袭称盗跖，春秋时人。
庄蹻（jué）：战国时人。当时被压迫阶级的起义领袖。《荀子·不苟》称盗跖“名声若日月”。同书《议兵》称楚国在垂沙一战（公元前301年）被齐、韩、魏三国打败，将领唐蔑被杀，“庄蹻起，楚分而为三四”。
流誉：流传名誉。
陈王：秦末农民起义领袖陈胜，他进占陈县（今河南淮阳县），称王。
挥黄钺（yuè）：挥动饰以黄金的大斧。《史记·周本纪》曾说周武王用黄钺斩商纣。
“盗跖庄屩流誉后，更陈王奋起挥黄钺”句：概括中国几千年历史上被压迫人民的武装斗争。', '与猿拱手作别进化到了原始社会人类犹如呱呱坠地，再经过磨石为工具的石器时代人类进入了少儿时期。炉中火焰翻滚，那是青铜时代，也经过了几千个春夏秋冬。纵观历史，也如人这一生多半忧愁少开怀。尽是征战杀伐弓箭疆场。这大好河山哪一处没有战争没有流血。
一部历史读罢，我已满头白发，我自己的人生也走到了暮年。回顾起来不过是那些同样的事情一再发生，什么王侯将相功名利禄，有多少人为其白首执迷。那些所谓的英雄人物难道是真风流？我看不尽然。盗跖、庄蹻、陈胜、吴广这些敢于揭竿而起挑战统治者的权威的人，那才是真豪杰。', '[{"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88ba7f0b9738b35ec613", "shortContent": "这首词最早发表在《红旗》一九七八年第九期。\n\n《贺新郎·读史》这首词，正如题目所标明的，是以历史为题材的。当然，毛主席不是为读史而读史，而是为了“古为今用”，为了教育今人。这首词的中心思想，它的一以贯之的主线就是阶级斗争观点。毛主席说：“阶级斗争，一些阶级胜利了，一些阶级消灭了。这就是历史，这就是几千年的文明史。拿这个观点解释历史的就叫做历史的唯物主义，站在这个观点反面的是历史的唯心主义。”（《丢...", "authors": ["萧涤非"], "pressName": "上海辞书出版社"}]', '', 'indent', 1447932574, '57ba43461532bc00656fca20', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10252, '人民解放军占领南京', NULL, 431, 106, 4, 1, '毛泽东', NULL, 10025, '57b8fb582e958a005fa52193', '当代', 'shi', '诗', 'http://baike.baidu.com/view/145977.htm', '', '钟山风雨起苍黄，百万雄师过大江。
虎踞龙盘今胜昔，天翻地覆慨而慷。
宜将剩勇追穷寇，不可沽名学霸王。
天若有情天亦老，人间正道是沧桑。', '', '钟山：《江南通志》：「钟山在江宁府东北，一曰金陵山，一曰蒋山，一名北山，一名元武山，俗名紫金山。周围六十里，高一百五十丈。诸葛亮对吴大帝云：钟山龙蟠，指此。」此处用作南京的代语。
苍黄：两解：一、同仓皇，慌张，匆忙，急遽失措貌。二、变化翻覆的意思。《墨子·所染篇》：「墨子见染丝者而叹曰：染于苍则苍，染于黄则黄，所入者变，其色亦变。」后因此比喻变化不定，反复无常。并引申为天翻地覆。此苍黄就是仓皇，即突然的意思。
虎踞（jù）龙盘：形容地势优异。三国时诸葛亮看到吴国都城建业（今南京市南）的地势曾说：「钟山龙蟠，石头虎踞，此帝王之宅。」（《太平御览》引《吴录》）石头即石头山，在今南京市西。
慨（kǎi）而慷：感慨而激昂。曹操《短歌行》：「慨当以慷」。
宜将剩勇追穷寇：剩勇，形容人民解放军（三大战役大量歼灭国民党反动派部队后）过剩的勇气。穷寇，走投无路的敌人。《后汉书·皇甫嵩传》：「兵法（指《司马兵法》），穷寇勿追。」这里反其意而为之，号召将革命进行到底，把敌人坚决、彻底、干净、全部地歼灭掉，不要留下后患。
沽（gū）名：故意做作或用某种手段猎取名誉。
霸王：霸王指楚霸王项羽。
天若有情天亦老：借用唐李长吉《金铜仙人辞汉歌》中诗句，原诗说的是汉武帝时制作的极贵重的宝物金铜仙人像，在三国时被魏明帝由长安迁往洛阳的传说。原句的意思是，对于这样的人间恨事，天若有情，也要因悲伤而衰老。这里是说，天若有情，见到国民党统治的黑暗残酷，也要因痛苦而变衰老；
人间正道是沧桑：人间正道，社会发展的正常规律。沧桑，沧海（大海）变为桑田，此喻革命性的发展变化。古代神话：女仙麻姑对另一仙人王方平说，他们相见以来，东海已经三次变为桑田（葛洪《神仙传》）。', '革命的暴风雨震荡着蒋家王朝都城南京，解放军以百万雄师突破长江天险，直攻蒋军苦心经营三个半月的根据地—南京城。
以雄奇险峻而著称的古都南京城回到了人民手中，她比任何时候都美丽。这天翻地覆的巨大变化，是足以令人慷慨高歌和欢欣鼓舞的。
应该趁现在这敌衰我盛的大好时机，痛追残敌，解放全中国。不可学那割据长江南岸，建立割据势力的霸王项羽。
自然界如果有知，它会体察到兴盛与衰败这条不可改变的法则。不断地变异、不断地发展、不断地前进，这是人类社会发展的必然规律。', '[{"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88ba7ccdb86c49e7aa18", "shortContent": "这首诗最早发表在人民文学出版社一九六三年十二月版《毛主席诗词》。\n\n1949年4月21日，毛泽东主席和朱德总司令发出《向全国进军的命令》，号令全军坚决、彻底、干净、全部地歼灭中国境内一切敢于抵抗的国民党反动派，解放全中国。中国人民解放军百万大军随即在东起江苏江阴、西至江西湖口的1 000余里战线上强渡长江，并于4月23日占领国民党反动政府的“首都”南京。毛泽东同志在北平香山双清别墅得到占领南京的捷...", "authors": ["周振甫"], "pressName": "上海辞书出版社"}]', '', 'center', 1463331162, '57b8fb907db2a2005426781a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10256, '清平乐 · 六盘山', NULL, 264, 106, 2, 2, '毛泽东', NULL, 10025, '57b8fb582e958a005fa52193', '当代', 'ci', '词', 'http://baike.baidu.com/view/146035.htm', '', '天高云淡，望断南飞雁。不到长城非好汉，屈指行程二万。
六盘山上高峰，红旗漫卷西风。今日长缨在手，何时缚住苍龙？', '此词为毛泽东翻越六盘山时的咏怀之作。1935年10月，毛泽东率领的红一方面军在向陕北根据地挺进中，于六盘山前击败了前来堵截的敌骑兵团。在战斗胜利的鼓舞下，当天下午部队便一鼓作气翻过了六盘山。
这首词写景、抒情工整分明，流转自然。上、下半阕均是一、二句写景，三、四句言志。情景交织，浑然一体。整诗洋溢着革命胜利的豪情，运用高亢雄壮的语气，抒发了“长缨在手”定当“缚住苍龙”的革命豪情。', '清平乐：词牌名，原为唐教坊曲名，取用汉乐府“清乐”、“平乐”这两个乐调而命名。双调，四十六字。上阕押仄声韵，下阕换平声韵。也有全押仄声韵的。
望断：望着，直到看不见。
长城：借指长征的目的地。
屈指：弯着手指头计算。
六盘山：宁夏南部固原西南，是六盘山山脉的主峰，险窄的山路要盘旋多重才能到达峰顶。毛泽东在1935年九月中旬率领中央红军进入甘肃省南部，10月上旬，突破敌人的封锁线，打垮了敌人的骑兵部队，胜利地越过六盘山。
红旗：1957年在《诗刊》创刊号上发表时作“旄头”。1961年九月为宁夏干部书写此词时改为“红旗”，手迹发表在1961年10月7日的《光明日报》。
漫卷，任意吹卷。
长缨：指捕缚敌人的长绳，出自“终军请缨”的典故，《汉书·终军传》：“愿受长缨，必羁南越王而致之阙下”，这里指革命武装。
在手，在共产党领导下。
缚住：擒住。
苍龙：《后汉书·张纯传》注：“苍龙，太岁也。”古代方士以太岁所在为凶方，因称太岁为凶神恶煞。苍龙，毛泽东注：此处指蒋介石的国民党反动派，因为当前主要对付的是国民党反动派。', '长空高阔白云清朗，南飞的大雁已望到了天边。不登临长城关口绝不是英雄，算下来已征战了二万。
六盘山上雄峰再拔，烈烈西风漫卷着红旗。今天我长绳之武装紧握手中，哪一天才会将那蒋家狂龙捆缚？', '[{"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88b97ccdb86c49e7aa11", "shortContent": "这首词最早发表在《诗刊》一九五七年一月号。\n\n这首《清平乐》是毛泽东于1935年10月、红军长征翻越最后一座天险时写就的作品。词作上下阕均是先景而情、再抒其志，纵横开阖，气象万千，将六盘山壮阔伟丽的景象与作者心中的豪迈情怀成功地联系起来，相得益彰。\n\n开首一句“天高云淡，望断南飞雁”意义丰富。它首先传达了作者经历千难万险、突出重围之后的休憩状态。此时的毛泽东已经率部登上了六盘山顶，摆脱了围追堵截的...", "authors": ["王毅"], "pressName": "上海辞书出版社"}]', '', 'indent', 1363132344, '57ba43430a2b58006cb3578e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10257, '满江红 · 和郭沫若同志', NULL, 103, 106, 1, 1, '毛泽东', NULL, 10025, '57b8fb582e958a005fa52193', '当代', 'ci', '词', 'http://baike.baidu.com/view/328693.htm', '', '小小寰球，有几个苍蝇碰壁。嗡嗡叫，几声凄厉，几声抽泣。蚂蚁缘槐夸大国，蚍蜉撼树谈何易。正西风落叶下长安，飞鸣镝。
多少事，从来急；天地转，光阴迫。一万年太久，只争朝夕。四海翻腾云水怒，五洲震荡风雷激。要扫除一切害人虫，全无敌。', '', '满江红：词牌名，又名《上江虹》、《念良游》、《伤春曲》。唐人小说《冥音录》载曲名《上江虹》，后更名《满江红》。宋以来始填此词调。
郭沫若：光绪十八年 （西元一八九二年）11月16日生于四川省乐山县铜河沙湾，毕业于日本九州帝国大学，现代文学家、历史学家、新诗奠基人之一。
寰（huán）球：这里指地球。
蚂蚁缘槐：唐·李公佐《南柯太守传》，有个叫淳于棼的人，一天喝醉，梦见自己在「大槐安国」当了驸马，做了南柯郡太守，醒来才知是梦。后来他在屋后发现一个白蚂蚁穴，还建有王城，原来这就是「大槐安国」。
蚍蜉（pí fú）撼树：唐·韩昌黎《调张籍》，「蚍蜉撼大树，可笑不自量」。蚍蜉指苍蝇，在这里指霸权主义国家。
鸣镝（dí）：响箭，汉时匈奴冒顿单于用来发号施令。
朝（zhāo）夕：一早一晚，这里指一天。
四海：指全国范围内。', '小小的地球上，有那么几个国家，像几只碰壁的苍蝇一样嗡嗡叫唤，貌似声色俱厉，又像哭泣声一样。这些国家好比那大槐树下的蚂蚁一样吹嘘自己的国家有多强大，却不知道他们的所做所为，就像蚍蜉撼大树一样可笑！我们吹响冲锋的号角（飞鸣镝），要像秋风扫落叶一样席卷他们。
天下的事情，从来都是那样急切；日月轮回，光阴紧迫。要等一万年后才等来胜利，实在是太久，我们要抓紧时间，力求主动，只争朝夕。当今的世界上，四海翻腾，风云变幻，五洲震荡，形势诡谲，我们要消灭所有危害人类的败类，还世界一个太平。', '[{"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88bac9ebcc6fbe96f7cb", "shortContent": "这首诗最早发表在人民文学出版社一九六三年十二月版《毛主席诗词》。\n\n这首诗是和诗，因此必须先知道原诗的意思。另外，郭沫若原诗题为《看〈孙悟空三打白骨精〉》，故要了解郭诗，也得大体知道郭沫若所看的这个剧的大体内容。\n\n《孙悟空三打白骨精》是浙江省绍剧团演出的，内容是根据《西游记》第二十七、二十八回改编。剧情说，白骨精先后变为女子、老妇人、老汉来欺骗唐僧，孙悟空因打这化作假象的妖精而屡被唐僧念紧箍咒惩...", "authors": ["赵逵夫"], "pressName": "上海辞书出版社"}, {"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88bac9ebcc6fbe96f7d0", "shortContent": "这首词最早发表在人民文学出版社一九六三年十二月版《毛主席诗词》。\n\n20世纪50年代后期到60年代前期，世界局势动荡，国际共产主义运动中的思想分歧不断加剧、激化。以赫鲁晓夫为首的前苏共领导集团在对外关系上奉行霸权主义，热衷于同美帝国主义做政治买卖，而对坚持原则的中国共产党采取阴谋手段，发动突然袭击，并将苏中两党的分歧扩大到国家关系方面。他们撕毁合同，撤走专家，断绝援助，挑起边界纠纷，妄图通过政治和...", "authors": ["林一顺"], "pressName": "上海辞书出版社"}]', '', 'indent', 1468664041, '57b9d7dfc4c971006149068b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10258, '忆秦娥 · 娄山关', NULL, 349, 106, 3, 3, '毛泽东', NULL, 10025, '57b8fb582e958a005fa52193', '当代', 'ci', '词', 'http://baike.baidu.com/view/328894.htm', '', '西风烈，长空雁叫霜晨月。霜晨月，马蹄声碎，喇叭声咽。
雄关漫道真如铁，而今迈步从头越。从头越，苍山如海，残阳如血。', '此词写于1935年，描写了红军铁血长征中征战娄山关的紧张激烈场景。通过在战争中积累多年的景物观察，以景入情，情中有景，从内到外表现了作者面对失利和困难从容不迫的气度和博大胸怀。', '忆秦娥：是词牌名，源于李白的词句“秦娥梦断秦楼月”。双调，仄韵格，四十六字。该词牌名的最早出李白《忆秦娥·箫声咽》词。此调别名甚多，计有《秦楼月》、《玉交枝》、《碧云深》、《双荷叶》，而《秦楼月》则与《忆秦娥》同取词中首句为之名。
西风烈：列，凛烈、猛风；西风劲厉。
长空雁叫霜晨月：在霜晨残月映照下，在烟雾茫茫的长空中，有飞雁在叫唤。这两句是记拂晓情景，时娄山关战斗已经胜利结束。
霜晨月：叠句，类似音律上的和声，有连锁作用，详见词牌忆秦娥。
马蹄声碎：碎，碎杂，碎乱。
喇叭声咽：喇叭，一种管乐器，即军号。咽，呜咽、幽咽，声音因阻塞而低沉。
雄关漫道真如铁：雄关，雄壮的关隘，即指娄山关。漫道，徒然说，枉然说。人们徒然传说娄山关坚硬如铁。
而今迈步从头越：迈步，跨步、大踏步。从头越，即为头越。张相《诗词曲语词汇释》：“为头，犹云从头，或开始也。”有重头再开始的意思。说的是从头大踏步越过雄关，却隐约透露着当时战略任务受挫，要对长征计划从头再作部署，且有取得胜利的坚定不移的信心。
苍山如海：青山起伏，像海的波涛。
残阳如血：夕阳鲜红，像血的颜色。', '', '[{"bookId": "62de396a1e31260377829cb1", "bookTitle": "毛泽东诗词鉴赏辞典", "articleId": "630f88b97ccdb86c49e7aa0e", "shortContent": "这首词最早发表在《诗刊》一九五七年一月号。\n\n使用《忆秦娥》这个词牌的词始见于宋代黄编的《唐宋诸贤绝妙词选》，题李白作，其中有“秦娥梦断秦楼月”一句，故名《忆秦娥》。这首《忆秦娥·娄山关》是毛泽东在娄山关战役胜利之后所写，最早发表于《诗刊》1957年1月号，发表时没有标明写作时间。1963年12月人民文学出版社出版《毛泽东诗词》时，将写作时间标明为“一九三五年二月”。这首词上阕写的是红军向娄山关进...", "authors": ["刘怀辉"], "pressName": "上海辞书出版社"}]', '', 'indent', 1363132561, '57b9525d2e958a005fa82325', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10260, '过零丁洋', NULL, 732, 987, 3, 17, '文天祥', NULL, 10066, '57b9bb6ed342d3006bdff813', '宋', 'shi', '诗', 'http://baike.baidu.com/view/203555.htm', '', '辛苦遭逢起一经，干戈寥落四周星。
山河破碎风飘絮，身世浮沉雨打萍。
惶恐滩头说惶恐，零丁洋里叹零丁。
人生自古谁无死？留取丹心照汗青！', '此诗是宋代大臣文天祥在1279年经过零丁洋时所作。前二句诗人回顾平生；中间四句紧承“干戈寥落”，明确表达了作者对当前局势的认识；末二句是作者对自身命运的一种毫不犹豫的选择。全诗表现了慷慨激昂的爱国热情和视死如归的高风亮节，以及舍生取义的人生观，是中华民族传统美德的崇高表现。', '零丁洋：零丁洋即”伶丁洋“。现在广东省珠江口外。宋端宗景炎三年(公元1278年）底，文天祥率军在广东五坡岭与元军激战，兵败被俘，囚禁船上曾经过零丁洋。
遭逢：遭遇。起一经，因为精通一种经书，通过科举考试而被朝廷起用作官。文天祥二十岁考中状元。
干戈：指抗元战争。
寥（liáo）落：一作“落落”,荒凉冷落。
四周星：四周年。文天祥从宋恭帝德佑元年（公元1275年）起兵抗元，到宋端宗景炎三年(公元1278年）被俘，一共四年。
絮：柳絮。
萍：浮萍。
惶恐滩：在今江西省万安县，是赣江中的险滩。宋端宗景炎二年(公元1277年），文天祥在江西被元军打败，所率军队死伤惨重，妻子儿女也被元军俘虏。他经惶恐滩撤到福建。
零丁：孤苦无依的样子。
丹心：红心，比喻忠心。
汗青：同汗竹，史册。古代用简写字，先用火烤干其中的水分，干后易写而且不受虫蛀，也称汗青。', '回想我早年由科举入仕历尽辛苦，如今战火消歇已熬过了四个年头。
国家危在旦夕恰如狂风中的柳絮，个人又哪堪言说似骤雨里的浮萍。
惶恐滩的惨败让我至今依然惶恐，零丁洋身陷元虏可叹我孤苦零丁。
人生自古以来有谁能够长生不死？我要留一片爱国的丹心映照史册。', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea74c03572034f65a389d", "shortContent": "此诗是文天祥《指南录》中的一篇，为其代表作之一，约作于祥兴二年（1279）———被元军俘获的第二年正月过零丁洋之时。后来元军元帅张弘范一再逼他写信招降南宋在海上坚持抵抗的张世杰，他出示此诗以明志节。\n“辛苦遭逢起一经，干戈寥落四周星。”作者面临生死关头，回忆一生，感慨万千，从何写起呢？他只抓住两件大事，一是以明经入仕，这是关系他个人政治前途的大事；二是“勤王”，这是关系宋王朝存亡的大事。他深感知遇...", "authors": ["苏者聪"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646c2c5bb6a81d0c53127076", "shortContent": "此诗是文天祥《指南录》中的一篇，为其代表作之一，约作于祥兴二年（1279）——被元军俘获的第二年正月过零丁洋之时。后来元军元帅张弘范一再逼他写信招降南宋在海上坚持抵抗的张世杰，他出示此诗以明志节。\n\n“辛苦遭逢起一经，干戈寥落四周星。”作者面临生死关头，回忆一生，感慨万千，从何写起呢？他只抓住两件大事，一是以明经入仕，这是关系他个人政治前途的大事；二是“勤王”，这是关系宋王朝存亡的大事。他深感知遇...", "authors": ["苏者聪"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "647201ec902ee364cc958a2b", "shortContent": "此诗是文天祥《指南录》中的一篇，为其代表作之一，约作于祥兴二年(1279)———被元军俘获的第二年正月过零丁洋之时。后来元军元帅张弘范一再逼他写信招降南宋在海上坚持抵抗的张世杰，他出示此诗以明志节。\n“辛苦遭逢起一经，干戈寥落四周星。”作者面临生死关头，回忆一生，感慨万千，从何写起呢？他只抓住两件大事，一是以明经入仕，这是关系他个人政治前途的大事；二是“勤王”，这是关系宋王朝存亡的大事。他深感知遇...", "authors": ["苏者聪"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472e2dba5f1e74f958ab914", "shortContent": "此诗是文天祥《指南录》中的一篇，为其代表作之一，约作于祥兴二年（1279）——被元军俘获的第二年正月过零丁洋之时。后来元军元帅张弘范一再逼他写信招降南宋在海上坚持抵抗的张世杰，他出示此诗以明志节。\n\n“辛苦遭逢起一经，干戈寥落四周星”，作者面临生死关头，回忆一生，感慨万千，从何写起呢？他只抓住两件大事，一是以明经入仕，这是关系他个人政治前途的大事；二是“勤王”，这是关系宋王朝存亡的大事。他深感知遇...", "authors": ["苏者聪"], "pressName": "上海辞书出版社"}]', '谢榛《四溟诗话》：结句当如撞钟，清音有余。', 'center', 1415647738, '57b902ea5bbb50005b783639', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10261, '正气歌', NULL, 208, 987, 2, 3, '文天祥', NULL, 10066, '57b9bb6ed342d3006bdff813', '宋', 'shi', '诗', 'http://baike.baidu.com/subview/98170/8412514.htm', '予囚北庭，坐一土室。室广八尺，深可四寻。单扉低小，白间短窄，污下而幽暗。当此夏日，诸气萃然：雨潦四集，浮动床几，时则为水气；涂泥半朝，蒸沤历澜，时则为土气；乍晴暴热，风道四塞，时则为日气；檐阴薪爨，助长炎虐，时则为火气；仓腐寄顿，陈陈逼人，时则为米气；骈肩杂遝，腥臊汗垢，时则为人气；或圊溷、或毁尸、或腐鼠，恶气杂出，时则为秽气。叠是数气，当侵沴，鲜不为厉。而予以孱弱，俯仰其间，於兹二年矣，幸而无恙，是殆有养致然尔。然亦安知所养何哉？孟子曰：“吾善养吾浩然之气。”彼气有七，吾气有一，以一敌七，吾何患焉！况浩然者，乃天地之正气也，作正气歌一首。', '天地有正气，杂然赋流形。
下则为河岳，上则为日星。
于人曰浩然，沛乎塞苍冥。
皇路当清夷，含和吐明庭。
时穷节乃见，一一垂丹青。
在齐太史简，在晋董狐笔。
在秦张良椎，在汉苏武节。
为严将军头，为嵇侍中血。
为张睢阳齿，为颜常山舌。
或为辽东帽，清操厉冰雪。
或为出师表，鬼神泣壮烈。
或为渡江楫，慷慨吞胡羯。
或为击贼笏，逆竖头破裂。
是气所磅礴，凛烈万古存。
当其贯日月，生死安足论。
地维赖以立，天柱赖以尊。
三纲实系命，道义为之根。
嗟予遘阳九，隶也实不力。
楚囚缨其冠，传车送穷北。
鼎镬甘如饴，求之不可得。
阴房阗鬼火，春院閟天黑。
牛骥同一皁，鸡栖凤凰食。
一朝蒙雾露，分作沟中瘠。
如此再寒暑，百疠自辟易。
哀哉沮洳场，为我安乐国。
岂有他缪巧，阴阳不能贼。
顾此耿耿存，仰视浮云白。
悠悠我心悲，苍天曷有极。
哲人日已远，典刑在夙昔。
风檐展书读，古道照颜色。', '此诗是南宋诗人文天祥在狱中写的一首五言古诗。诗的开头即点出浩然正气存乎天地之间，至时穷之际，必然会显示出来。随後连用十二个典故，都是历史上有名的人物，他们的所作所为凛然显示出浩然正气的力量。接下来八句说明浩然正气贯日月，立天地，为三纲之命，道义之根。最後联系到自己的命运，自己虽然兵败被俘，处在极其恶劣的牢狱之中，但是由于自己一身正气，各种邪气和疾病都不能侵犯自己，因此自己能够坦然面对自己的命运。全诗感情深沉、气壮山河、直抒胸臆、毫无雕饰，充分体现了作者崇高的民族气节和强烈的爱国主义精神。', '予：我，一作「余」。
北庭：指元朝首都大都（今北京）。
寻：古时八尺为一寻。
单扉：单扇门。
白间：窗户。
污下：低下。
萃然：聚集的样子。
雨潦：下雨形成的地上积水。
涂泥半朝：「朝」当作「潮」，意思是狱房墙上涂的泥有一半是潮湿的。
蒸沤历澜：热气蒸，积水沤，到处都杂乱不堪。澜，澜漫、杂乱。
乍晴：刚晴、初晴。
风道四塞：四面的风道都堵塞了。
薪爨（cuàn）：烧柴做饭。
炎虐：炎热的暴虐。
仓腐寄顿：仓库里储存的米谷腐烂了。
陈陈逼人：陈旧的粮食年年相加，霉烂的气味使人难以忍受。陈陈：陈陈相因，《史记·平准书》：「太仓之粟，陈陈相因。」
骈肩杂遝（tà）：肩挨肩，拥挤杂乱的样子。
腥臊：鱼肉发臭的气味，此指囚徒身上发出的酸臭气味。
圊溷（qīnghùn）：厕所。
毁尸：毁坏的尸体。
秽：肮脏。
叠是数气：这些气加在一起。
侵沴（lì）：恶气侵人。沴，恶气。
鲜不为厉：很少有不生病的。厉，病。
孱弱：虚弱。
俯仰其间：生活在那里。
于兹：至今。
无恙：没有生病。
是殆有养致然：这大概是因为会保养正气才达到这样的吧。殆，大概；有养，保有正气。语本《孟子·公孙丑》：「我善养吾浩然之气。」致然，使然、造成这样子。
然尔亦安知所养何哉：然而又怎么知道所保养的内容是什么呢？
孟子：名轲，战国时代的思想家，其弟子将孟子言行变成《孟子》一书，为儒家经典。
浩然之气：纯正博大而又刚强之气。见《孟子·公孙丑》。
吾何患焉：我还怕什么呢。中国古代的许多思想家都认为浩然正气对于人身有无所不能的巨大力量。
「天地有正气，杂然赋流形。」句：天地之间充满正气，它赋予各种事物以不同形态。这类观点明显有唯心色彩，但作者主要用以强调人的节操。杂然，纷繁、多样。
「下则为河岳，上则为日星。」句：是说地上的山岳河流，天上的日月星辰，都是由正气形成的。
「于人曰浩然，沛乎塞苍冥。」句：赋予人的正气叫浩然之气，它充满天地之间。沛乎，旺盛的样子；苍冥，天地之间。
皇路：国运、国家的局势。
清夷：清平、太平。
吐：表露。
见：同「现」，表现、显露。
丹青：图画，古代帝王常把有功之臣的肖像和事迹叫画工画出来。
垂丹青：见于画册，传之後世。垂，留存、流传。
太史：史官。
简：古代用以写字的竹片。《左传·襄公二十五年》载：春秋时，齐国大夫崔杼把国君杀了，齐国的太史在史册中写道「崔杼弑其君」。崔杼怒，把太史杀了。太史的两个弟弟继续写，都被杀，第三个弟弟仍这样写，崔杼没有办法，只好让他写在史册中。
在晋董狐笔：出自《左传·宣公二年》载，春秋时，晋灵公被赵穿杀死，晋大夫赵盾没有处置赵穿，太史董狐在史册上写道：「赵盾弑其君。」孔子称赞这样写是「良史」笔法。
张良椎：《史记·留侯传》载，张良祖上五代人都做韩国的丞相，韩国被秦始皇灭掉後，他一心要替韩国报仇，找到一个大力士，持一百二十斤的大椎，在博浪沙（今河南省新乡县南）伏击出巡的秦始皇，未击中。後来张良辅佐刘邦建立汉朝，封留侯。
苏武节：《汉书·李广苏建传》载，汉武帝时，苏武出使匈奴，匈奴人要他投降，他坚决拒绝，被流放到北海（今西伯利亚贝加尔湖）边牧羊。为了表示对祖国的忠诚，他一天到晚拿着从汉朝带去的符节，牧羊十九年，始终贤贞不屈，後来终于回到汉朝。
严将军：《三国志·蜀志·张飞传》载，严颜在刘璋手下做将军，镇守巴郡，被张飞捉住，要他投降，他回答说：「我州但有断头将军，无降将军！」张飞见其威武不屈，把他释放了。
嵇侍中：嵇绍，嵇中散之子，晋惠帝时做侍中（官名）。《晋书·嵇绍传》载，晋惠帝永兴元年（西元三〇四年），皇室内乱，惠帝的侍卫都被打垮了，嵇绍用自己的身体遮住惠帝，被杀死，血溅到惠帝之衣。战争结束後，有人要洗去惠帝衣服上的血，惠帝说：「此嵇侍中血，勿去！」
张睢阳：即唐朝的张巡。《旧唐书·张巡传》载，安禄山叛乱，张巡固守睢阳（今河南省商丘市），每次上阵督战，大声呼喊，牙齿都咬碎了。城破被俘，拒不投降，敌将问他：「闻君每战，皆目裂，嚼齿皆碎，何至此耶？」张巡回答说：「吾欲气吞逆贼，但力不遂耳。」敌将视其齿，存者不过三数。
颜常山：即唐朝的颜杲卿，任常山太守。《新唐书·颜杲卿传》载，安禄山叛乱时，他起兵讨伐，後城破被俘，当面大骂安禄山，被钩断舌头，仍不屈，被杀死。
辽东帽：东汉末年的管宁有高节，是在野的名士，避乱居辽东（今辽宁省辽阳市），一再拒绝朝廷的徵召，他常戴一顶黑色帽子，安贫讲学，名闻于世。
清操厉冰雪：是说管宁严格奉守清廉的节操，凛如冰雪。厉，严肃、严厉。
出师表：诸葛亮出师伐魏之前，上表给蜀汉後主刘禅，表明白己为统一事业奋鬭到底的决心。表文中有「鞠躬尽力，死而後已」的名言。
鬼神泣壮烈：鬼神也被诸葛亮的壮烈精神感动得流泪。
渡江楫：东晋爱国志士祖逖率兵北伐，渡长江时，敲着船桨发誓北定中原，後来终于收复黄河以南失地。楫，船桨。
胡羯：古代对北方少数民族的称呼。过去史书上曾称匈奴、鲜卑、羯、氐、羌为五胡。这句是形容祖逖的豪壮气概。
击贼笏：唐德宗时，朱泚谋反，召段秀实议事，段秀实不肯同流合污，以笏猛击朱泚的头，大骂：「狂贼，吾恨不斩汝万段，岂从汝反耶？」笏：古代大臣朝见皇帝时所持的手板。
逆竖：叛乱的贼子，指朱眦。
是气：这种「浩然之气」。磅礴，充塞。
凛烈：庄严、令人敬畏的样子。
「当其贯日月，生死安足论。」句：当正气激昂起来直冲日月的时候，个人的生死还有什么值得计较的。
地维：古代人认为地是方的，四角有四根支柱撑着。
天柱：古代传说，崑崙山有铜柱，高人云天，称为天柱，又说天有人山为柱。
「地维赖以立，天柱赖以尊。」句：是说地和天都依靠正气支撑着。
三纲实系命：是说三纲实际系命于正气，即靠正气支撑着。
道义为之根：道义以正气为根本。
嗟：感叹词。
遘：遭逢、遇到。
阳九：即百六阳九，古人用以指灾难年头，此指国势的危亡。
隶也实无力：是说我实在无力改变这种危亡的国势。隶，地位低的官吏，此为作者谦称。
楚囚缨其冠：《左传·成公九年》载，春秋时被俘往晋国的楚国俘虏钟仪戴着一种楚国帽子，表示不忘祖国，被拘囚着，晋侯问是什么人，旁边人回答说是「楚囚」。这里作者是说，自己被拘囚着，把从江南戴来的帽子的带系紧，表示虽为囚徒仍不忘宋朝。
传车：官办交通站的车辆。
穷北：极远的北方。
鼎镬：大锅，古代一种酷刑，把人放在鼎镬里活活煮死。
鼎镬甘如饴：身受鼎镬那样的酷刑，也感到像吃糖一样甜，表示不怕牺牲。
阴房：见不到阳光的居处，此指囚房。
阒：幽暗、寂静。
阴房阒鬼火：囚室阴暗寂静，只有鬼火出没。杜甫《玉华宫》诗：「阴房鬼火青。」
春院閟（bì）天黑：虽在春天里，院门关得紧紧的，照样是一片漆黑。杜甫《大云寺赞公房》诗：「天黑閟春院。」閟，关闭。
「牛骥同一皂，鸡栖凤凰食。」句：牛和骏马同槽，鸡和凤凰共处，比喻贤愚不分，杰出的人和平庸的人都关在一起。骥，良马；皂，马槽；鸡栖，鸡窝。
一朝蒙雾露：一旦受雾露风寒所侵。蒙，受。
分作沟中瘠：料到自己一定成为沟中的枯骨。分，料、估量。沟中瘠，弃于沟中的枯骨。《说苑》：「死则不免为沟中之瘠。」
如此再寒暑：在这种环境里过了两年了。
百沴自辟易：各种致病的恶气都自行退避了。这是说没有生病。
沮洳场：低下阴湿的地方。
「岂有他缪（miù）巧，阴阳不能贼。」两句：哪有什么妙法奇术，使得寒暑都不能伤害自己？缪巧，智谋、机巧；贼，害。
顾此耿耿存：只因心中充满正气。顾，但，表示意思有转折的连接词；此，指正气；耿耿，光明貌。
仰视浮云白：对富贵不屑一顾，视若浮云。《论语·述而》：「不义而富且贵，于我如浮云。」
「悠悠我心悲，苍天曷有极。」句：我心中亡国之痛的忧思，像苍天一样，哪有尽头。曷，何、哪；极，尽头。
哲人：贤明杰出的人物，指上面列举的古人。
哲人日以远：古代的圣贤一天比一天远了。
典刑：榜样、模范。
夙昔：从前、讨去。
风檐展书读：在临风的廊檐下展开史册阅读。
古道照颜色：古代传统的美德，闪耀在面前。', '', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea74dc6e67846a9213bd4", "shortContent": "《正气歌》是一首光华灿烂的诗篇。诗中充满了浩然正气，表现出作者坚贞的民族气节，威武不能屈、富贵不能淫的战斗精神以及死生不渝的崇高信念。\n作者于宋帝昺祥兴元年（1278）十二月，在潮阳五坡岭兵败被俘，次年十月解达元都燕京。囚系土室，环境污浊，艰苦备尝，而毅然拒绝了元统治者多番的利诱威胁。作者认为支持他坚持不屈的精神力量就是正气。也就是孟子所说的充塞于天地之间的至大至刚的浩然之气。因而以“正气”为题，...", "authors": ["马祖熙"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646c2cb45e6bb82b8ce320b0", "shortContent": "《正气歌》是一首光华灿烂的诗篇。诗中充满了浩然正气，表现出作者坚贞的民族气节，威武不能屈、富贵不能淫的战斗精神以及死生不渝的崇高信念。\n\n作者于宋帝昺祥兴元年（1278）十二月，在潮阳五坡岭兵败被俘，次年十月解达元都燕京。囚系土室，环境污浊，艰苦备尝，而毅然拒绝了元统治者多番的利诱威胁。作者认为支持他坚持不屈的精神力量就是正气。也就是孟子所说的充塞于天地之间的至大至刚的浩然之气。因而以“正气”为题...", "authors": ["马祖熙"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472e341b6a81d0c532e5bd4", "shortContent": "《正气歌》是一首光华灿烂的诗篇。诗中充满了浩然正气，表现出作者坚贞的民族气节，威武不能屈、富贵不能淫的战斗精神以及死生不渝的崇高信念。作者于宋帝昺祥兴元年（1278）十二月，在潮阳五坡岭兵败被俘，次年十月解达元都燕京。囚系土室，环境污浊，艰苦备尝，而毅然拒绝了元统治者多番的利诱威胁。作者认为支持他坚持不屈的精神力量就是正气，也就是孟子所说的充塞于天地之间的至大至刚的浩然之气。因而以“正气”为题，以...", "authors": ["马祖熙"], "pressName": "上海辞书出版社"}]', '清·康熙《古文评论·卷四十三》：斯篇出于至性，慷慨凄恻。朕每于披读之际，不觉泪下数行，其忠君忧国之诚，洵足以弥宇宙而贯金石。
清·过珙《重订古文详注全集·卷六》：宋祚将尽，先生以致仕起兵，後元灭宋，执先生，历万苦而不屈，屹然如山，卒遇害而死，真能全其正气矣。试读此歌，言言若神鬼之泪，诚足沮金石而薄云天。
清·蔡世远《古文雅正·卷十四》：文山以年少对策第状元，以法不息为主，一气呵成数千言。……以此知养气者不可不读书也，特不为章句之儒耳。歌中又曰，「皇路当清夷，含和吐明庭」。公岂乐以死节见哉。', 'center', 1448041299, '57b916c7128fe10054ca4142', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10262, '书愤', NULL, 371, 9405, 2, 8, '陆游', NULL, 10019, '57b904a9d342d3005ac748fb', '宋', 'shi', '诗', 'http://baike.baidu.com/subview/58421/16612421.htm', '', '早岁那知世事艰，中原北望气如山。
楼船夜雪瓜洲渡，铁马秋风大散关。
塞上长城空自许，镜中衰鬓已先斑。
出师一表真名世，千载谁堪伯仲间！', '此诗是南宋诗人陆放翁创作的五首七言律诗《书愤》的第一首。该诗系宋孝宗淳熙十三年（西元一一八六年）春陆游居家家乡山阴时所作。放翁时年已六十二，想那山河破碎，中原未收而「报国欲死无战场」，感于世事多艰，小人误国而「书生无地效孤忠」，于是，诗人郁愤之情便喷薄而出，遂成此组诗。
「书愤」者，抒发胸中郁愤之情。回看整首诗歌，可见句句是愤，字字是愤。以愤而为诗，诗便尽是愤。全诗感情沉郁，气韵浑厚，显然得力于杜少陵。中两联属对工稳，尤以颔联「楼船」、「铁马」两句，雄放豪迈，为人们广泛传诵。', '书愤：书写自己的愤恨之情。书，写。
早岁：早年，年轻时。
那：即「哪」。
世事艰：指抗金大业屡遭破坏。
「中原北望气如山」句：北望中原，收复故土的豪迈气概坚定如山。中原北望，「北望中原」的倒文。气，气概。
楼船：指采石之战中宋军使用的车船，又名明轮船、车轮柯。车船内部安装有以踩踏驱动的机械连接船外的明轮，依靠一组人的脚力踩踏前行。车船在宋代盛极一时。因这种战船髙大有楼，故把它称之为楼船。
瓜洲：在今江苏邢江南长江边，与镇江隔江相对，是当时的江防要地。
「楼船夜雪瓜洲渡」句：此时作者三十七岁，在镇江府任通判。宋孝宗隆兴元年（西元一一六三年），张魏公以右丞相都督江淮诸路军马，亲率水兵乘楼船往来于建康、镇江之间。但不久兵败符离，收复故土的愿望化为泡影。
铁马：披着铁甲的战马。
大散关：在今陕西宝鸡西南，是当时宋金的西部边界。
「铁马秋风大散关」句：宋孝宗乾道八年（西元一一七二年），王公明以枢密使出任四川宣抚使，谋划恢复中原之事。放翁人其军幕，并任幹办公事兼检法官赴南郑（今陕西汉中）。其间，他曾亲临大散关前线，研究抗敌策略。但不久王公明调回京城。收复故土的愿望又一次落空。
「塞上长城空自许」句：意为作者徒然地自许为是「塞上长城」。塞上长城，喩能守边的将领。《南史·檀道济传》载，宋文帝要杀大将檀道济，檀临刑前怒叱道：「乃坏汝万里长城！」
衰鬓：年老而疏白的头髮。
斑：指黑髮中夹杂了白髮。
出师一表：蜀汉後主建兴五年（西元二二七年）三月，诸葛亮出兵伐魏前曾写了一篇《出师表》，表达了自己「奖率三军，北定中原」，「兴复汉室，还于旧都」的坚强决心。
名世：名传後世。
堪：能够。
伯仲：原指兄弟间的次第。这里比喻人物不相上下，难分优劣髙低。唐·杜少陵《咏怀古迹》诗之五称赞诸葛武侯：「伯仲之间见伊吕，指挥若定失萧曹。」', '年轻时就立志北伐中原，哪想到竟然是如此艰难。我常常北望那中原大地，收复故土的气概如山啊。
记得在瓜州渡痛击金兵，雪夜里飞奔着楼船战舰。秋风中跨战马纵横驰骋，收复了大散关捷报频传。
想当初我自比万里长城，立壮志为祖国扫除边患。到如今垂垂老鬓发如霜，盼北伐盼恢复都成空谈。
不由人缅怀那诸葛孔明，出师表真可谓名不虚传，有谁像诸葛亮鞠躬尽瘁，率三军复汉室北定中原！', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea72fc6e67846a9213b5c", "shortContent": "此诗作于孝宗淳熙十三年（1186）春，这时陆游退居于山阴家中，已是六十二岁的老人。从淳熙七年起，他罢官已六年，挂着一个空衔在故乡蛰居。直到作此诗时，才以朝奉大夫、权知严州军州事起用。因此，诗的内容兼有追怀往事和重新立誓报国的两重感情。\n诗的前四句是回顾往事。“早岁”句指隆兴元年（1163）他三十九岁在镇江府任通判和乾道八年（1172）他四十八岁在南郑任王炎幕僚事。当时他亲临抗金战争的第一线，北望中...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646b70e17f27182da370acdd", "shortContent": "此诗作于孝宗淳熙十三年（1186）春，这时陆游退居于山阴家中，已是六十二岁的老人。从淳熙七年起，他罢官已六年，挂着一个空衔在故乡蛰居。直到作此诗时，才以朝奉大夫、权知严州军州事起用。因此，诗的内容兼有追怀往事和重新立誓报国的两重感情。\n\n诗的前四句是回顾往事。“早岁”句指隆兴元年（1163）他三十九岁在镇江府任通判和乾道八年（1172）他四十八岁在南郑任王炎幕僚事。当时他亲临抗金战争的第一线，北望...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f358082772d45941d0aa9", "shortContent": "此诗作于孝宗淳熙十三年(1186 )春，这时陆游退居于山阴家中，已是六十二岁的老人。从淳熙七年起，他罢官已六年，挂着一个空衔在故乡蛰居。直到作此诗时，才以朝奉大夫、权知严州军州事起用。因此，诗的内容兼有追怀往事和重新立誓报国的两重感情。\n诗的前四句是回顾往事。“早岁”句指隆兴元年(1163 )他三十九岁在镇江府任通判和乾道八年（1172 ）他四十八岁在南郑任王炎幕僚事。当时他亲临抗金战争的第一线，...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472c5a5b6a81d0c532db5ba", "shortContent": "此诗作于孝宗淳熙十三年（1186）春，这时陆游退居于山阴家中，已是六十二岁的老人。从淳熙七年起，他罢官已六年，挂着一个空衔在故乡蛰居。直到作此诗时，才以朝奉大夫、权知严州军州事起用。因此，诗的内容兼有追怀往事和重新立誓报国的两重感情。\n\n诗的前四句是回顾往事。“早岁”句指隆兴元年（1163）他三十九岁在镇江府任通判和乾道八年（1172）他四十八岁在南郑任王炎幕僚事。当时他亲临抗金战争的第一线，北望...", "authors": ["何满子"], "pressName": "上海辞书出版社"}]', '清·李越縵《越缦堂诗话》：全首浑成，风格髙健，置之老杜集中，直无愧色。', 'center', 1415640181, '57b91876d342d3005ac7eee6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10263, '望江南 · 超然台作', NULL, 1627, 3406, 2, 7, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/864635.htm', '', '春未老，风细柳斜斜。试上超然台上望，半壕春水一城花，烟雨暗千家。
寒食后，酒醒却咨嗟。休对故人思故国，且将新火试新茶，诗酒趁年华。', '超然台，位于密州（今山东诸城）北城上。东坡任密州太守的第二年，见北城墙上原来的旧台年久破败，便修葺一新，时时与友人登临。在济南的弟弟苏颍滨闻知後，将其命名为超然台。此词係登超然台作，时间是熙宁九年（公元一〇七六年）春天。此词描绘了春日景象和作者感情、神态的复杂变化，寄寓了作者对有家难回、有志难酬的无奈与怅惘，同时表达了作者豁达超脱的襟怀和“用之则行，舍之则藏”的人生态度。全词含蓄深沉，短小玲珑，以诗为词，独树一帜，连珠妙语似随意而出，清新自然，显示出词人深厚的艺术功力。', '望江南：词牌名。原唐教坊曲名，后用为词牌。又名《忆江南》、《梦江南》、《江南好》。《金奁集》入“南吕宫”。唐段安节《乐府杂录》：“《望江南》始自朱崖李太尉镇浙日，为亡妓谢秋娘所撰。本名《谢秋娘》。”后因白乐天尝依格作《忆江南》三首，但嫌其名不雅，遂改名为《忆江南》。此调廿七字，三平韵。首句三字；次句仄起平韵五字，句法上二下三，亦有添一衬字者；第三句仄起仄收七字，第一、第三字平仄不拘；第四句平起平韵七字；第五句句法与次句同，故首字平仄不拘。此调三、四句，全与平起七言律诗之颔联无异，故多用对偶为工，历来词家，亦多其例也。宋人多用双调。
“超然台作”：毛本无题。明吴讷钞本、茅维《苏集》本题作“暮春”。
超然台：傅子立注：“超然台在高密。”刘尚荣按引东坡《超然台记》：“予自钱塘移守胶西，……于是治其园囿，洁其庭宇，伐安邱、高密之木，以修补破败，为苟完之计。而园之北，因城以为台者旧矣；稍葺而新之。……方是时，予弟子由适在济南，闻而赋之，且名其台曰‘超然’。”又引颍滨《超然台赋》序：“子瞻既通守余杭，三年不得代。以辙之在济南也，求为东州守。既得请高密，其地介于淮海之间，风俗朴陋，四方宾客不至。受命之岁，承大旱之余孽，驱除螟蝗，逐捕盗贼，廪恤饥馑，日不遑给。几年而后少安，顾居处隐陋，无以自放，乃因其城上之废台而增葺之。日与其僚览其山川而乐之，以告辙曰：‘此将何以名之？’辙曰：‘今夫山居者知山，林居者知林，耕者知原，渔者知泽，安于其所而已。其乐不相及也，而台则尽之。天下之士，奔走于是非之场，噶于荣辱之海，嚣然尽力而忘反，亦莫自知也。而达者哀之，二者非以其超然不累于物故邪。《老子》曰：“虽有荣观，燕处超然。”尝试以“超然”命之，可乎？’”
试上超然台上望：“望”一作“看”。
半壕：傅子立注：“‘壕’，城下也。”刘尚荣按：“宋司马温公《类篇·卷三十九》：‘壕，乎刀切，城下池。’傅注‘也’应是‘池’之讹。”龙榆生笺：“《广韵》：‘壕，城下池也。’柳河东诗：‘雁鸣寒雨下空壕。’”按，此非柳河东诗，乃许丁卯《登故洛阳城》诗，见《全唐诗·卷五百三十三》。
思故国：傅子立注：“杜子美诗：‘思国延归望。’”刘尚荣按：“句出《题衡山县文宣王庙新学堂呈陆宰》，《九家集注杜诗·卷十六》‘思’作‘故’，是。”
新火：傅子立注：“《周官》以‘季春出火’，则寒食后乃其时尔，故曰‘新火’。”刘尚荣按：“语见《周礼·夏官司爟》。宋·祝和甫《古今事文类聚·前集卷八·〈天时部·三月赐新火〉》引《辇下岁时记》：‘唐朝清明取榆柳之火，以赐近臣，顺阳气也。’又引《会要》‘禁火乃周之旧制，唐及宋朝清明日赐新火，亦周人出火之事。’”
新茶：指清明前所采之“明前茶”。', '春天还没有过去，微风细细，柳枝斜斜随之起舞。登上超然台远远眺望，护城河只半满的春水微微闪动，城内则是缤纷竞放的春花。更远处，家家瓦房均在雨影之中。
寒食节过后，酒醒反而因思乡而叹息不已，只得自我安慰：不要在老朋友面前思念故乡了，姑且点上新火来烹煮一杯刚采的新茶，作诗醉酒都要趁年华尚在啊。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b20f8fda556504d990", "shortContent": "这首词作于熙宁九年（1076）暮春，在密州（今山东诸城县）任上。作者于熙宁七年十一月至密州，“处之期年”，即八年底，动工修葺园北旧台，并由其弟苏辙命其名曰“超然”，这就是超然台（据苏轼《超然台记》）。作者登超然台，眺望满城烟雨，触动乡思，写下了这首词。\n这首词为双调，比原来的单调《望江南》增加了一叠。上片写登台时所见城中景象，包括三个层次。首先以春柳在春风中的姿态———“风细柳斜斜”，点明当时的季...", "authors": ["施议对"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b95914587d02f58ff3", "shortContent": "这首词作于熙宁九年（1076）暮春，在密州（今山东诸城县）任上。作者于熙宁七年十一月至密州，“处之期年”，即八年底，动工修葺园北旧台，并由其弟苏辙命其名曰“超然”，这就是超然台（据苏轼《超然台记》）。作者登超然台，眺望满城烟雨，触动乡思，写下了这首词。\n这首词为双调，比原来的单调《望江南》增加了一叠。上片写登台时所见城中景象，包括三个层次。首先以春柳在春风中的姿态———“风细柳斜斜”，点明当时的季...", "authors": ["施议对"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253f534825dee9fd6e3", "shortContent": "这首词作于熙宁九年（1076）暮春，在密州（今山东诸城县）任上。作者于熙宁七年十一月至密州，“处之期年”，即八年底，动工修葺园北旧台，并由其弟苏辙命其名曰“超然”，这就是超然台（据苏轼《超然台记》）。作者登超然台，眺望满城烟雨，触动乡思，写下了这首词。\n\n这首词为双调，比原来的单调《望江南》增加了一叠。上片写登台时所见城中景象，包括三个层次。首先以春柳在春风中的姿态——“风细柳斜斜”，点明当时的季...", "authors": ["施议对"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e79f2af4e09d55b652b", "shortContent": "傅藻《东坡纪年录》编于熙宁八年乙卯（1075），薛本、邹王本均辨其非，认为熙宁九年丙辰（1076）春作于密州。孔《谱》亦编是年。此词与后首一言“春未老”，一言“春已老”，盖为同时作。超然台，在密州郡圃之北，因城以为台。苏轼《超然台记》末署“熙宁九年三月三日东武两斋书”。后一首“春已老”中“寒食后”、“且将新火试新茶”很明显是言寒食、清明节。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646835307f27182da362835e", "shortContent": "这首词作于熙宁九年（1076）暮春，在密州（今山东诸城县）任上。作者于熙宁七年十一月至密州，“处之期年”，即八年底，动工修葺园北旧台，并由其弟苏辙命其名曰“超然”，这就是超然台（据苏轼《超然台记》）。作者登超然台，眺望满城烟雨，触动乡思，写下了这首词。\n\n这首词为双调，比原来的单调《望江南》增加了一叠。上片写登台时所见城中景象，包括三个层次。首先以春柳在春风中的姿态——“风细柳斜斜”，点明当时的季...", "authors": ["施议对"], "pressName": "上海辞书出版社"}]', '', 'indent', 1363133582, '57b1968e8ac247005f167e61', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10264, '桂枝香 · 金陵怀古', NULL, 508, 1836, 5, 7, '王安石', NULL, 10067, '57b93713c4c971005590f52a', '宋', 'ci', '词', 'http://baike.baidu.com/view/167225.htm', '', '登临送目，正故国晚秋，天气初肃。千里澄江似练，翠峰如簇。归帆去棹残阳里，背西风，酒旗斜矗。彩舟云淡，星河鹭起，画图难足。
念往昔，繁华竞逐，叹门外楼头，悲恨相续。千古凭高对此，谩嗟荣辱。六朝旧事随流水，但寒烟、衰草凝绿。至今商女，时时犹唱，后庭遗曲。', '全词上阕写景。「澄江」、「翠峰」、「征帆」、「酒旗」、「彩舟」、「鹭起」，构成一幅雄伟壮丽的金陵晚秋图。下阕通过怀古，揭露了六朝统治阶级「繁华竞逐」的奢侈生活。结句「至今商女，时时犹唱，后庭遗曲」则是对当道者的警醒。这首词语言苍劲，意境开阔，摆脱了当时绮靡词风的影响。在艺术风格上摆脱纤细、绮靡的词风，「一扫五代旧习」，有着极大的独创性；在意趣和识度上，一反千古谩嗟荣辱的悲叹，站得高，看得远，隐喻现实，寄兴遥深，所以被推为金陵怀古词的绝唱。', '桂枝香：词牌名，又名「疏帘淡月」，首见于王安石此作。金陵：今江苏南京。
登临送目：登山临水，举目望远。送目，远目、望远。
故国：即故都，旧时的都城。金陵为六朝故都，故称故国。
初肃：天气刚开始萧肃。肃，萎缩、肃杀，形容草木枯落，天气寒而高爽。
千里澄江似练：形容长江像一匹长长的白绢。语出谢朓《晚登三山还望京邑》：「馀霞散成绮，澄江静如练。」澄江，清澈的长江。练，白色的绢。
如簇：这里指群峰好像丛聚在一起。簇，丛聚。
棹（zhào）：划船的一种工具，形似桨，也可引申为船。
归帆去棹：远去的船只。归帆一作：征帆
斜矗：斜插。矗，直立。
星河：天河，这里指秦淮河。
鹭：白鹭，一种水鸟。一说指白鹭洲（长江与秦淮河相汇之处的小洲）。
「彩舟云淡，星河鹭起」句：意谓结彩的画船行于薄雾迷离之中，犹在云内；华灯映水，繁星交辉，白鹭翩飞。这两句转写秦淮河，「彩舟」系代人玩乐的河上之船，与江上「征帆去棹」的大船不同。又与下阕「繁华」相接，释为秦淮河较长江为妥。
画图难足：用图画也难以完美地表现它。难足，难以完美地表现出来。
繁华竞逐：（六朝的达官贵人）争着过豪华的生活。竞逐，竞相仿效追逐。
门外楼头：指南朝陈亡国惨剧。语出杜牧《台城曲》：「门外韩擒虎，楼头张丽华。」韩擒虎是隋朝开国大将，统兵伐陈，他已带兵来到金陵朱雀门（南门）外，陈后主尚与他的宠妃张丽华于结绮阁上寻欢作乐。陈后主、张丽华被韩俘获，陈亡于隋。门，指朱雀门；楼，指结绮阁。
悲恨相续：指六朝亡国的悲恨，接连不断。
凭高：登高。这是说作者登上高处远望。
谩嗟荣辱：空叹历朝兴衰。这是作者的感叹。谩：一说“漫”。荣，兴盛；辱，灭亡。
六朝：指三国吴、东晋、南朝宋、齐、梁、陈六个朝代。它们都建都金陵。
「六朝旧事随流水，但寒烟衰草凝绿。」句：六朝的往事像流水般消逝了，如今只有寒烟笼罩衰草，凝成一片暗绿色，而繁华无存了。衰草一作：芳草
商女：酒楼茶坊的歌女。
后庭遗曲：指歌曲《玉树后庭花》，传为陈后主所作，其辞哀怨绮靡，后人将它看成亡国之音。最后三句化用杜牧《泊秦淮》「商女不知亡国恨，隔江犹唱《后庭花》」诗意。', '我登上城楼放眼远望，故都金陵正是深秋，天气已变得飒爽清凉。千里澄江宛如一条白练，青翠山峰像箭簇耸立前方。帆船在夕阳中远去，西风起处，斜插的酒旗在小街飘扬。画船如同在淡云中浮游，白鹭好像在银河里飞舞，丹青妙笔也难描画这壮美风光。
遥想当年，故都金陵何等繁盛堂皇。可叹在朱雀门外结绮阁楼，六朝君主一个个地相继败亡。自古多少人在此登高怀古，无不对历代荣辱喟叹感伤。六朝旧事已随流水消逝，剩下的只有寒烟惨淡、绿草衰黄。时至今日，商女们时时地还把《后庭花》遗曲吟唱。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74aadbb8b379ee08de65", "shortContent": "古来有学识、有抱负的文士，一旦登高望远，便兴起了满怀愁绪，那愁又不是区区个人私情，而常常是日月之迁流，世途之坎壈，家国之忧患，人生之苦辛……一齐涌上心头，奔赴笔下，遂而写成了名篇佳作，历久长新，此等例真是举之不尽，而王半山的这一阕《桂枝香》，实为个中翘楚。\n作者这次是在南朝古都，金陵胜地，而时值深秋，天色傍晚，他在此意境之间，临江揽胜，凭高吊古。他开门见山，表明时地。试看他虽以登高望远为主题，却是...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b0d635634aee3e9a71", "shortContent": "古来有学识、有抱负的文士，一旦登高望远，便兴起了满怀愁绪，那愁又不是区区个人私情，而常常是日月之迁流，世途之坎壈，家国之忧患，人生之苦辛，……一齐涌上心头，奔赴笔下，遂而写成了名篇佳作，历久长新，此等例真是举之不尽，而王半山的这一阕《桂枝香》，实为个中翘楚。\n作者这次是在南朝古都，金陵胜地，而时值深秋，天色傍晚，他在此意境之间，临江揽胜，凭高吊古。他开门见山，表明时地。试看他虽以登高望远为主题，却...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592534b56e213e684802c", "shortContent": "古来有学识、有抱负的文士，一旦登高望远，便兴起了满怀愁绪，那愁又不是区区个人私情，而常常是日月之迁流，世途之坎壈，家国之忧患，人生之苦辛……一齐涌上心头，奔赴笔下，遂而写成了名篇佳作，历久长新，此等例真是举之不尽，而王半山的这一阕《桂枝香》，实为个中翘楚。\n\n作者这次是在南朝古都，金陵胜地，而时值深秋，天色傍晚，他在此意境之间，临江揽胜，凭高吊古。他开门见山，表明时地。试看他虽以登高望远为主题，却...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62de4ae858b41e188206f9ca", "bookTitle": "王安石诗文鉴赏辞典", "articleId": "6305a39130a1d3054c75614e", "shortContent": "古来有学识、有抱负的文士，一旦登高望远，便兴起了满怀愁绪，那愁又不是区区个人私情，而常常是日月之迁流，世途之坎，家国之忧患，人生之苦辛，……一齐涌上心头，奔赴笔下，遂而写成了名篇佳作，历久长新，此等例真是举之不尽，而王半山的这一阕《桂枝香》，实为个中翘楚。\n\n作者这次是在南朝古都，金陵胜地，而时值深秋，天色傍晚，他在此意境之间，临江览胜，凭高吊古。他开门见山，表明时地。试看他虽以登高望远为主题，却...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3d73206168b2e020bd", "shortContent": "这首词在黄昇《唐宋诸贤绝妙词选》中词牌下注“金陵怀古”四字，是一首登临怀古之作。\n\n一般认为是王安石罢相后退居金陵的作品。金陵，即今天的南京，是东吴、东晋、宋、齐、梁、陈、南唐等朝代的都城所在，历来为骚人墨客吟咏，而以词咏金陵的，当首推王安石这首《桂枝香》。\n\n词上片写登临远望之景。时值深秋，草木凋零，天气清寒。长江如同一匹长长的白绢，两岸峰峦如聚。江上小船在斜阳中往来不息，岸边酒旗迎风招展。彩色...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702d77683d1933015345", "shortContent": "这首词在黄昇《唐宋诸贤绝妙词选》中词牌下注“金陵怀古”四字，是一首登临怀古之作。一般认为是王安石罢相后退居金陵的作品。金陵，即今天的南京，是东吴、东晋、宋、齐、梁、陈、南唐等朝代的都城所在，历来为骚人墨客吟咏，而以词咏金陵的，当首推王安石这首《桂枝香》。\n\n词上片写登临远望之景。时值深秋，草木凋零，天气清寒。长江如同一匹长长的白绢，两岸峰峦如聚。江上小船在斜阳中往来不息，岸边酒旗迎风招展。彩色的画...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312718dc26cbf3417f09587", "shortContent": "这首词在黄昇《唐宋诸贤绝妙词选》中词牌下注“金陵怀古”四字，是一首登临怀古之作。一般认为是王安石罢相后退居金陵的作品。金陵，即今天的南京，是东吴、东晋、宋、齐、梁、陈、南唐等朝代的都城所在，历来为骚人墨客吟咏，而以词咏金陵的，当首推王安石这首《桂枝香》。\n词上片写登临远望之景。时值深秋，草木凋零，天气清寒。长江如同一匹长长的白绢，两岸峰峦如聚。江上小船在斜阳中往来不息，岸边酒旗迎风招展。彩色的画船...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f334382772d45941d00db", "shortContent": "古来有学识、有抱负的文士，一旦登高望远，便兴起了满怀愁绪，那愁又不是区区个人私情，而常常是日月之迁流，世途之坎[插图]，家国之忧患，人生之苦辛……一齐涌上心头，奔赴笔下，遂而写成了名篇佳作，历久长新，此等例真是举之不尽，而王半山的这一阕《桂枝香》，实为个中翘楚。\n作者这次是在南朝古都，金陵胜地，而时值深秋，天色傍晚，他在此意境之间，临江揽胜，凭高吊古。他开门见山，表明时地。试看他虽以登高望远为主题...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}]', '张思岩《词林纪事·卷四》引宋·杨曼倩《古今词话》：金陵怀古，诸公寄词于《桂枝香》凡十三馀首，独介甫最为绝唱。东坡见之，不觉叹息曰：「此老乃野狐精也。」
宋·张炎《词源》：词以意趣为主，要不蹈袭前人语意。如东坡《中秋·水调歌头》（词略）、王荆公《金陵怀古·桂枝香》（词略），……此数词皆清空中有意趣，无笔力者未易到。
明·张皋文《论词》：《桂枝香》登临送目：情韵有美成、耆卿所不能到。
清·梁任公《饮冰室评词》：《桂枝香》登临送目：李易安谓介甫文章似西汉，然以作歌词，则人必绝到。但此却颉颃清真、稼轩，未可谩诋也。
现·周敏菴《唐宋词鉴赏辞典》：此词抒发金陵怀古人之情，为作者别创一格、非同凡响的杰作。词中流露出王安石失意无聊之时颐情自然风光的情怀。全词开门见山，写作者南朝古都金陵胜地，于一个深秋的傍晚，临江揽胜，凭高吊古。他虽以登高望远为主题，却是以故国晚秋为眼目。「正」「初」「肃」三个字逐步将其主旨点醒。以下两句，借六朝谢家名句「解道‘澄江净如练’，令人长忆谢玄晖」之意，点化如同已出。即一个「似练」，一个「如簇」，形胜已赫然而出。然后专写江色，纵目一望，只见斜阳映照之下，数不清的帆风樯影，交错于闪闪江波之上。细看凝眸处，却又见西风紧处，那酒肆青旗高高挑起，因风飘拂。帆樯为广景，酒旗为细景，而词人之意以风物为导引，而以人事为着落。一个「背」字，一个「矗」字，用得极妙，把个江边景致写得栩栩如生，似有生命其中。写景至此，全是白描，下面有所变化。「彩舟」「星河」两句一联，顿增明丽之色。然而词拍已到上阕歇处，故而笔亦就此敛住，以「画图难足」一句，抒赞美嗟赏之怀，颇有大家风范。「彩舟云淡」，写日落之江天：「星河鹭起」，状夕夜之洲渚。下阕另换一幅笔墨，感叹六朝皆以荒淫而相继亡覆的史实。写的是悲恨荣辱，空贻后人凭吊之资；往事无痕，唯见秋草凄碧，触目惊心而已。「门外楼头」，用杜牧《台城曲》句加以点染，亦简净有力。词至结语，更为奇妙，词人写道：时至今日，六朝已远，但其遗曲，往往犹似可闻。此处用典。「商女不知亡国恨，隔江犹唱《后庭花》！」此唐贤小杜于「烟笼寒水月笼沙，夜泊秦淮近酒家」时所吟之名句，词人复加运用，便觉尺幅千里，饶有有馀不尽之情致，而嗟叹之意，千古弥永。', 'indent', 1415640316, '57b8f359c4c97100558ec827', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10265, '梅花', NULL, 1423, 1836, 2, 8, '王安石', NULL, 10067, '57b93713c4c971005590f52a', '宋', 'shi', '诗', 'http://baike.baidu.com/subview/4085/6477433.htm', '', '墙角数枝梅，凌寒独自开。
遥知不是雪，为有暗香来。', '此诗首二句写墙角梅花不惧严寒，傲然独放，末二句写梅花洁白鲜艳，香气远布，赞颂了梅花的风度和品格，这正是诗人幽冷倔强性格的写照。诗人通过对梅花不畏严寒的高洁品性的赞赏，用雪喻梅的冰清玉洁，又用“暗香”点出梅胜于雪，说明坚强高洁的人格所具有的伟大的魅力。作者在北宋极端复杂和艰难的局势下，积极改革，而得不到支持，其孤独心态和艰难处境，与梅花自然有共通的地方。这首小诗意味深远，而语句又十分朴素自然，没有丝毫雕琢的痕迹。', '凌寒：冒着严寒。
遥：远远地。知：知道。
为（wèi）：因为。暗香：指梅花的幽香。', '白玉堂前有一棵梅花树，梅树花谢花开，却不知为谁而开为谁而谢。
年复一年，不见旁人相惜，唯独那吹拂的春风，每年归来相探。', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea70034a8757d5a0e73f0", "shortContent": "据惠洪《冷斋夜话》记王安石此诗的写作缘由说：“荆公尝访一高士不遇，题其壁。”这话的可靠性如何，难以遽断；王安石的诗文向无编年，除了作品中有事实可考、足以断定年代的以外，大多数无法确断其具体年限，从而也无法从写作年代来考索其行事、交往和作诗的情况，所以只能就诗论诗。\n诗的第二句“凌寒独自开”，对梅花极表赞赏。严冬群芳纷谢，独有梅花凌寒开放，报道将至的春讯，诗人所欣羡的就是这种倔强的风骨。这不仅从字面...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "62de4ae858b41e188206f9ca", "bookTitle": "王安石诗文鉴赏辞典", "articleId": "6305a391251899613caf1fac", "shortContent": "据惠洪《冷斋夜话》记王安石此诗的写作原由说：“荆公尝访一高士不遇，题其壁。”这话的可靠性如何，难以遽断；王安石的诗文向无编年，除了作品中有事实可考、足以断定年代的以外，大多数无法确断其具体年限，从而也无法从写作年代来考索其行事、交往和作诗的情况，所以只能就诗论诗。\n\n诗的第二句“凌寒独自开”，对梅花极表赞赏。严冬群芳纷谢，独有梅花凌寒开放，报道将至的春讯，诗人所欣羡的就是这种倔强的风骨。这不仅从字...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646af0dd7f27182da36dd987", "shortContent": "据惠洪《冷斋夜话》记王安石此诗的写作原由说：“荆公尝访一高士不遇，题其壁。”这话的可靠性如何，难以遽断；王安石的诗文向无编年，除了作品中有事实可考、足以断定年代的以外，大多数无法确断其具体年限，从而也无法从写作年代来考索其行事、交往和作诗的情况，所以只能就诗论诗。\n\n诗的第二句“凌寒独自开”，对梅花极表赞赏。严冬群芳纷谢，独有梅花凌寒开放，报道将至的春讯，诗人所欣慕的就是这种崛犟的风骨。这不仅从字...", "authors": ["何满子"], "pressName": "上海辞书出版社"}]', '', 'center', 1415647817, '57b912d9128fe10054ca2054', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10266, '元日', NULL, 1776, 1836, 2, 7, '王安石', NULL, 10067, '57b93713c4c971005590f52a', '宋', 'shi', '诗', 'http://baike.baidu.com/subview/10323/9020019.htm', '', '爆竹声中一岁除，春风送暖入屠苏。
千门万户曈曈日，总把新桃换旧符。', '此诗描写春节除旧迎新的景象，取材于民间习俗，摄取了老百姓过春节时的典型素材，抓住有代表性的生活细节：点燃爆竹，饮屠苏酒，换新桃符，充分表现出年节的欢乐气氛，富有浓厚的生活气息。', '元日：农历正月初一，即春节。
爆竹：古人烧竹子时使竹子爆裂发出的响声。用来驱鬼避邪，后来演变成放鞭炮。
一岁除：一年已尽。除，逝去。
屠苏：指屠苏酒，饮屠苏酒也是古代过年时的一种习俗，大年初一全家合饮屠苏酒，以驱邪避瘟疫，求得长寿。
千门万户：形容门户众多，人口稠密。
曈曈：日出时光亮而温暖的样子。
桃：桃符，古代一种风俗，农历正月初一时人们用桃木板写上神荼、郁垒两位神灵的名字，悬挂在门旁，用来压邪。也作春联。', '阵阵轰鸣的爆竹声中，旧的一年已经过去；和暖的春风吹来了新年，人们欢乐地畅饮着新酿的屠苏酒。初升的太阳照耀着千家万户，他们都忙着把旧的桃符取下，换上新的桃符。', '[{"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471a311902ee364cc9394d1", "shortContent": "这首诗所写的是正月初一新年的情景。爆竹声声，辞去旧岁，人们喝着屠苏酒，感受着春风带来的温暖的气息。千家万户迎接着明亮的初升朝日，将大门悬挂的旧桃符摘掸，换上新的桃符。古时候，人们在大门外挂着画有郁垒、神荼二神的桃木板，也就是“桃符”，用以辟邪镇宅。后来演变为写在桃木板的文字，直至成为今日写在纸上的春联。王安石生活的宋代距今已有千年，不过从这首诗中却可见，很多过年时的习俗依然留存，今天读来也能够被这...", "authors": ["陈炜琦"], "pressName": "上海辞书出版社"}]', '王相《增补重订千家诗》：此诗自况其初拜相时的行君政，陈旧布新，顺始行己之政今也。
熊柏畦《宋八大家绝句选》：这首诗既是句句写新年，也是句句写新法。两者结合得紧密桔切，天衣无缝，把元日的温暖光明景象，写得如火如荼，歌颂和肯定了实行新法的胜利和美好前途。
姚奠中《唐宋绝句选注析》：用一「换」字，即写出当时的风俗习惯，更为读者开辟了新的诗意。揭示出新的代替旧的，进步的代替落后的，历史发展的这个不可抗拒的规律。', 'center', 1363134965, '57b902400a2b58005c924951', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10267, '书湖阴先生壁二首', NULL, 385, 1836, 2, 6, '王安石', NULL, 10067, '57b93713c4c971005590f52a', '宋', 'shi', '诗', 'http://baike.baidu.com/view/246847.htm', '', '【其一】
茅檐长扫净无苔，花木成畦手自栽。
一水护田将绿绕，两山排闼送青来。
【其二】
桑条索漠楝花繁，风敛余香暗度垣。
黄鸟数声残午梦，尚疑身属半山园。', '此诗前两句写他家的环境，洁净清幽，暗示主人生活情趣的高雅；后两句转到院外，写山水对湖阴先生的深情，暗用“护田”与“排闼”两个典故，把山水化成了具有生命感情的形象，山水主动与人相亲，正是表现人的高洁。全诗既赞美了主人朴实勤劳，又表达了诗人退休闲居的恬淡心境，从田园山水和与平民交往中领略到无穷的乐趣。诗中虽然没有正面写人，但写山水就是写人，景与人处处照应，句句关合，融化无痕。', '书：书写、题诗。
湖阴先生：本名杨德逢，隐居之士，是王安石晚年居住金陵紫金山（今江苏南京）时的邻居。
茅檐：茅屋檐下，这里指庭院。
无苔：没有青苔。
成畦（qí）：成垄成行。畦。经过修整的一块块田地。
护田：这里指护卫环绕着园田。语出《汉书·西域传序》：“自敦煌西至盐泽，往往起亭，而轮台、渠犁，皆有田卒数百人，置使者校尉领护。”
排闼（tà）：开门。语出《汉书·樊哙传》：“高帝尝病，恶见人，卧禁中，诏户者无得入群臣。哙乃排闼直入。”闼，小门；送青来，送来绿色。
楝（liàn）花：“二十四番花信”里的楝花，指的就是北方常见的苦楝花。', '【其一】
茅草房庭院经常打扫，洁净得没有一丝青苔。花草树木成行成垄，都是主人亲手栽种。
庭院外一条小河保护着农田，并且环绕着农田；两座大山打开门来为人们送去绿色。
【其二】
桑树枝叶萧疏，楝花十分繁盛。清风吹送楝花馀香，悄悄地送过墙头。
黄莺几声清脆的啼叫，惊醒了我的午觉。一梦醒来，我恍恍惚惚还觉得自己好像仍然在旧日所住的半山园中。', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea7005e272d4b225489a0", "shortContent": "这是王安石题在杨骥屋壁上的一首诗。杨骥字德逢，别号湖阴先生，是作者退居金陵（今江苏南京）时的邻居和经常往来的朋友。\n首二句赞美杨家庭院的清幽。“茅檐”代指庭院。“静”即净。怎样写净呢？诗人摒绝一切平泛的描绘，而仅用“无苔”二字，举重若轻，真可谓别具手眼。何以见得？江南地湿，又时值初夏多雨季节，这对青苔的生长比之其他时令都更为有利。况且，青苔性喜阴暗，总是生长在僻静之处，较之其他杂草更难于扫除。而今...", "authors": ["陈文新"], "pressName": "上海辞书出版社"}, {"bookId": "62de4ae858b41e188206f9ca", "bookTitle": "王安石诗文鉴赏辞典", "articleId": "6305a391251899613caf1fb2", "shortContent": "这是王安石题在杨骥屋壁上的一首诗。杨骥字德逢，别号湖阴先生，是作者退居金陵（今江苏南京）时的邻居和经常往来的朋友。\n\n首二句赞美杨家庭院的清幽。“茅檐”代指庭院。“静”即净。怎样写净呢？诗人摒绝一切平泛的描绘，而仅用“无苔”二字，举重若轻，真可谓别具手眼。何以见得？江南地湿，又时值初夏多雨季节，这对青苔的生长比之其他时令都更为有利。况且，青苔性喜阴暗，总是生长在僻静之处，较之其他杂草更难于扫除。而...", "authors": ["陈文新"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646af102902ee364cc770980", "shortContent": "这是王安石题在杨德逢屋壁上的一首诗。杨德逢，别号湖阴先生，是作者退居金陵（今江苏南京）时的邻居和经常往来的朋友。\n\n首二句赞美杨家庭院的清幽。“茅檐”代指庭院。“静”即净。怎样写净呢？诗人摒绝一切平泛的描绘，而仅用“无苔”二字，举重若轻，真可谓别具手眼。何以见得？江南地湿，又时值初夏多雨季节，这对青苔的生长比之其他时令都更为有利。况且，青苔性喜阴暗，总是生长在僻静之处，较之其他杂草更难于扫除。而今...", "authors": ["陈文新"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471a35ce49f46528adbea00", "shortContent": "这是王安石题在杨骥屋壁上的一首诗。杨骥字德逢，别号湖阴先生，是作者退居金陵（今江苏南京）时的邻居和经常往来的朋友。\n“一水护田”加以“绕”字，正见得那小溪曲折生姿，环绕着绿油油的农田，这不恰像一位母亲双手护着小孩的情景吗？著一“护”字，“绕”的神情明确显示。至于“送青”之前冠以“排闼”二字，更是神来之笔。它既写出了山色不只是深翠欲滴，也不只是可掬，而竟似扑向庭院而来！这种描写给予读者的美感极为新鲜...", "authors": ["陈文新"], "pressName": "上海辞书出版社"}]', '', 'center', 1423170083, '57b8d1faa633bd00665c79c7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10268, '登飞来峰', NULL, 556, 1836, 1, 15, '王安石', NULL, 10067, '57b93713c4c971005590f52a', '宋', 'shi', '诗', 'http://baike.baidu.com/view/143033.htm', '', '飞来山上千寻塔，闻说鸡鸣见日升。
不畏浮云遮望眼，自缘身在最高层。
', '此诗为王安石三十岁时所作。皇祐二年（公元1050年）夏，他在浙江鄞县知县任满回江西临川故里时，途经杭州，写下此诗。是他初涉宦海之作。此时诗人正值壮年，抱负不凡，正好借登飞来峰一抒胸臆，表达宽阔的情怀和远大的政治抱负。', '飞来山：一作飞来峰。有两说：一说在浙江绍兴城外的林山。唐宋时其中有座应天塔。传说此峰是从琅即郡东武县飞来的，故名飞来峰。一说在今浙江杭州西湖灵隐寺前。
千寻塔：很高很高的塔。寻，古时长度单位，八尺为寻。
闻说：听说。
浮云：在山间浮动的云雾。
望眼：视线。
自缘：一作“只缘”。缘，因为。', '飞来峰顶有座高耸入云的塔，听说鸡鸣时分可以看见旭日升起。
不怕层层浮云遮住我那远眺的视野，只因为我站在飞来峰顶，登高望远心胸宽广。', '[{"bookId": "62de4ae858b41e188206f9ca", "bookTitle": "王安石诗文鉴赏辞典", "articleId": "6305a390251899613caf1f8d", "shortContent": "这首诗是王安石年轻时候的作品，但具体的写作时间难以确定。关于此诗所写之飞来峰到底在何处，亦有多种说法。明田汝成将本诗收入《西湖游览志余》，固已认本诗所写是杭州之飞来峰。但宋代的李壁在这之前就已经对这种“杭州说”提出了疑问，他在《王荆公诗注》的注中说：“兴化军仙游县有大飞山，临安钱塘县灵隐寺有飞来山。介甫未尝入闽。若又以灵隐飞来峰，则初无塔，兼所见亦不至甚远。恐别指一处也。”相较之下，认为诗中所写为...", "authors": ["刘竞飞"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471ff13b6a81d0c532b7155", "shortContent": "“飞来山上千寻塔。”飞来山，即飞来之山之意。《会稽志》卷九引《吴越春秋》：“城既成，琅琊东武海中山一夕自来，故名怪山。”峰以飞来为奇，则其上之塔更奇。“千寻塔”，古以八尺（或云七尺、六尺）为一寻，千寻之塔，可想该有多高了。“闻说鸡鸣见日升。”正因塔高，故可闻鸡鸣而见日升了。《太平御览》卷一百七十九引汉《封禅仪》：“泰山东南有山名日观，鸡一鸣时见日始出，长三丈。秦观者望见长安，吴观者望见会稽，周观者...", "authors": ["刘竞飞"], "pressName": "上海辞书出版社"}]', '', 'center', 1423170176, '57b91f152e958a005fa64e10', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (57317, '维扬十咏', NULL, 0, 116, 0, 1, '舒頔', NULL, 11346, '5858e65a8d6d810065c31635', '元', 'shi', '诗', NULL, NULL, '平山山上构高堂，堂下青芜接大荒。
堂废山空人不见，冷云秋草卧横冈。', NULL, NULL, NULL, NULL, NULL, 'center', 1555325086, '585cf58961ff4b006cd1acbc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (221920, '月节折杨柳歌十三首正月歌', NULL, 0, 1905, 0, 2, '陈恭尹', NULL, 16195, '5835d867a22b9d006bc45a9a', '明', 'shi', '诗', NULL, NULL, '寒消时未暑，梅子欲成黄，摽落当谁取。折杨柳，青春不可追，长条已堪扫。', NULL, NULL, NULL, NULL, NULL, 'indent', 1525432458, '585db4fa8d6d810065e01998', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10269, '泊船瓜洲', NULL, 1076, 1836, 1, 8, '王安石', NULL, 10067, '57b93713c4c971005590f52a', '宋', 'shi', '诗', 'http://baike.baidu.com/view/246749.htm', '', '京口瓜洲一水间，钟山只隔数重山。
春风又绿江南岸，明月何时照我还？', '此诗是北宋诗人王安石创作的一首七言绝句，其中名句「春风又绿江南岸，明月何时照我还」千百年来一直为人所传颂。诗中「绿」字将无形的春风化为鲜明的形象，极其传神。', '泊船：停船。泊，停泊。指停泊靠岸。
京口：古城名。故址在江苏镇江市。
瓜洲：镇名，在长江北岸，扬州南郊，即今扬州市南部长江边，京杭运河分支入江处。
一水：一条河。古人除将黄河特称为「河」，长江特称为「江」之外，大多数情况下称河流为「水」，如汝水、汉水、浙水、湘水、澧水等。这里的「一水」指长江。一水间指一水相隔之间。
钟山：今南京市紫金山。
绿：吹绿，拂绿。
还：回。', '京口和瓜洲之间只隔着一条长江，我所居住的钟山隐没在几座山峦的后面。暖和的春风啊，吹绿了江南的田野，明月什么时候才能照着我回到钟山下的家里？', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea6fe5914587d02f538a7", "shortContent": "王安石喜欢改诗。他不仅为同时代人刘贡父、王仲至改诗（见《王直方诗话》），而且还为古人改诗。谢贞的《春日闲居诗》“风定花犹舞”，王安石“改‘舞’字作‘落’字，其语顿工”（《彦周诗话》）。对于自己的诗作，他更是不惮多改。《泊船瓜洲》是他修改己作使之更为完美的著名例证。\n这首诗作于熙宁八年（1075）二月。当时王安石第二次拜相，奉诏进京，舟次瓜洲。首句“京口瓜洲一水间”，以愉快的笔调写他从京口渡江，抵达...", "authors": ["吴汝煜"], "pressName": "上海辞书出版社"}, {"bookId": "62de4ae858b41e188206f9ca", "bookTitle": "王安石诗文鉴赏辞典", "articleId": "6305a390251899613caf1f95", "shortContent": "王安石喜欢改诗。他不仅为同时代人刘贡父、王仲至改诗（见《王直方诗话》），而且还为古人改诗。谢贞的《春日闲居诗》“风定花犹舞”，王安石“改‘舞’字作‘落’字，其语顿工”（《彦周诗话》）。对于自己的诗作，他更是不惮多改。《泊船瓜洲》是他修改己作使之更为完美的著名例证。\n\n这首诗作于熙宁八年（1075）二月。当时王安石第二次拜相，奉诏进京，舟次瓜洲。首句“京口瓜洲一水间”，以愉快的笔调写他从京口渡江，抵...", "authors": ["吴汝煜"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646aef5d7f27182da36dd094", "shortContent": "王安石喜欢改诗。他不仅为同时代人刘贡父、王仲至改诗（见《王直方诗话》），而且还为古人改诗。谢贞的《春日闲居诗》:“风定花犹舞”，王安石“改‘舞’字作‘落’字，其语顿工。”（《彦周诗话》）对于自己的诗作，他更是不惮多改。《泊船瓜洲》是他修改己作使之更为完美的著名例证。\n\n这首诗作于熙宁八年（1075）二月。当时王安石第二次拜相，奉诏进京，舟次瓜洲。首句“京口瓜洲一水间”，以愉快的笔调写他从京口渡江，...", "authors": ["吴汝煜"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471a334e49f46528adbe94c", "shortContent": "“春风又绿江南岸”，描绘了江岸美丽的春色，寄托了诗人浩荡的情思。其中“绿”字是经过精心筛选的，极其富于表现力。洪迈《容斋续笔》卷八云：“吴中士人家藏其草。初云‘又到江南岸’。圈去‘到’字，注日‘不好’。改为‘过’，复圈去而改为‘入’。旋改为‘满’。凡如是十许字，始定为‘绿’。”作者认为“到”“过”“入”“满”等字都不理想，只有“绿”字最为精警。这是因为，一、前四字都只从风本身的流动着想，粘皮带骨，...", "authors": ["吴汝煜"], "pressName": "上海辞书出版社"}]', '《童蒙诗训》：文字频改，工夫自出。
《彦周诗话》：超然迈伦，能追逐李杜陶谢。', 'center', 1415640108, '57b8ec0679bc44005b9e1ec8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10270, '枫桥夜泊', NULL, 1988, 36, 2, 15, '张继', NULL, 10068, '57b9c129a633bd005d2f2f0d', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/156045/4899471.htm', '', '月落乌啼霜满天，江枫渔火对愁眠。
姑苏城外寒山寺，夜半钟声到客船。', '《枫桥夜泊》是唐朝安史之乱后，诗人张继途经寒山寺时，写下的一首羁旅诗。在这首诗中，诗人精确而细腻地讲述了一个客船夜泊者对江南深秋夜景的观察和感受，勾画了月落乌啼、霜天寒夜、江枫渔火、孤舟客子等景象，有景有情有声有色。此外，这首诗也将作者羁旅之思，家国之忧，以及身处乱世尚无归宿的顾虑充分地表现出来，是写愁的代表作。
这首诗句句形象鲜明，可感可画，句与句之间逻辑关系又非常清晰合理，内容晓畅易解。不仅是中国历代各种唐诗选本和别集选入此诗，连亚洲一些国家的小学课本也曾收录此诗。该诗作品不仅在中国家喻户晓，甚至在日本也是很有影响。本诗问世后，寒山寺也因此名扬天下，成为游览胜地。', '枫桥：在今苏州市阊门外。
夜泊：夜间把船停靠在岸边。
乌啼：一说为乌鸦啼鸣，一说为乌啼镇。
霜满天：霜，不可能满天，这个“霜”字应当体会作严寒；霜满天，是空气极冷的形象语。
江枫：一般解释作“江边枫树”，江指吴淞江，源自太湖，流经上海，汇入长江，俗称苏州河。另外有人认为指“江村桥”和“枫桥”。“枫桥”在吴县南门（阊阖门）外西郊，本名“封桥”，因张继此诗而改为“枫桥”。
渔火：通常解释，“鱼火”就是渔船上的灯火；也有说法指“渔火”实际上就是一同打渔的伙伴。
对愁眠：伴愁眠之意，此句把江枫和渔火二词拟人化。就是后世有不解诗的人，怀疑江枫渔火怎么能对愁眠，于是附会出一种讲法，说愁眠是寒山寺对面的山名。
姑苏：苏州的别称，因城西南有姑苏山而得名。
寒山寺：在枫桥附近，始建于南朝梁代。相传因唐代僧人寒山、拾得曾住此而得名。在今苏州市西枫桥镇。本名“妙利普明塔院”，又名枫桥寺；另一种说法，“寒山”乃泛指肃寒之山，非寺名。寺曾经数次重建，现在的寺宇，为太平天国以后新建。寺钟在第二次世界大战时，被日本人运走，下落不明。
夜半钟声：当今的佛寺（春节）半夜敲钟，但当时有半夜敲钟的习惯，也叫「无常钟」或「分夜钟」。宋朝大文豪欧阳修曾提出疑问表示：“诗人为了贪求好句，以至于道理说不通，这是作文章的毛病，如张继诗句“夜半钟声到客船”，句子虽好，但那有三更半夜打钟的道理？”可是经过许多人的实地查访，才知苏州和邻近地区的佛寺，有打半夜钟的风俗。', '月亮已落下乌鸦啼叫寒气满天，对着江边枫树和渔火忧愁而眠。
姑苏城外那寂寞清静寒山古寺，半夜里敲钟的声音传到了客船。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b3c6e67846a920eb89", "shortContent": "一个秋天的夜晚，诗人泊舟苏州城外的枫桥。江南水乡秋夜幽美的景色，吸引着这位怀着旅愁的客子，使他领略到一种情味隽永的诗意美，写下了这首意境清远的小诗。\n题为“夜泊”，实际上只写“夜半”时分的景象与感受。诗的首句，写了午夜时分三种有密切关连的景象：月落、乌啼、霜满天。上弦月升起得早，半夜时便已沉落下去，整个天宇只剩下一片灰蒙蒙的光影。树上的栖乌大约是因为月落前后光线明暗的变化，被惊醒后发出几声啼鸣。月...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac26845f3e157ce322", "shortContent": "一个秋天的夜晚，诗人泊舟苏州城外的枫桥。江南水乡秋夜幽美的景色，吸引着这位怀着旅愁的客子，使他领略到一种情味隽永的诗意美，写下了这首意境清远的小诗。\n\n题为“夜泊”，实际上只写“夜半”时分的景象与感受。诗的首句，写了午夜时分三种有密切关联的景象：月落、乌啼、霜满天。上弦月升起得早，半夜时便已沉落下去，整个天宇只剩下一片灰蒙蒙的光影。树上的栖乌大约是因为月落前后光线明暗的变化，被惊醒后发出几声啼鸣。...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290e8", "shortContent": "这是一首千古传唱的名作，大约作于诗人张继在安史之乱后辟地吴中时。寒山寺在今苏州市西的枫桥镇，始建于南朝梁，自张继此诗后，便闻名遐迩了。\n\n此诗成为经久流传的佳作，有多方面原因。首先此诗意境极美，意象选取十分用心。首句“月落乌啼霜满天”，用乌啼突出月夜之静谧。而在色彩上，月色洁白，天穹漆黑，繁星点点缀于夜空，仿佛霜满大地，黑白分明且光色的布局也充满美感。二句“江枫渔火对愁眠”，江畔的枫树、渔船的灯火...", "authors": ["唐磊"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127069c305cf0801816fce", "shortContent": "这是一首千古传唱的名作，大约作于诗人张继在安史之乱后避地吴中时。寒山寺在今苏州市西的枫桥镇，始建于南朝梁，自张继此诗后，便闻名遐迩了。\n\n此诗成为经久流传的佳作，有多方面原因。首先此诗意境极美，意象选取十分用心，首句“月落乌啼霜满天”，用乌啼突出月夜之静谧，而在色彩上月色洁白，天穹漆黑，繁星点点缀于夜空，仿佛霜满大地，黑白分明且光色的布局也充满美感。二句“江枫渔火对愁眠”，江畔的枫树、渔船的灯火色...", "authors": ["唐磊"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270e1f2af4e09d55b680b", "shortContent": "这是一首千古传唱的名作，大约作于诗人张继在安史之乱后避地吴中时。寒山寺在今苏州市西的枫桥镇，始建于南朝梁，自张继此诗后，便闻名遐迩了。\n\n此诗成为经久流传的佳作，有多方面原因。首先此诗意境极美，意象选取十分用心，首句“月落乌啼霜满天”，用乌啼突出月夜之静谧，而在色彩上月色洁白，天穹漆黑，繁星点点缀于夜空，仿佛霜满大地，黑白分明且光色的布局也充满美感。二句“江枫渔火对愁眠”，江畔的枫树、渔船的灯火色...", "authors": ["唐磊"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "64719e937f27182da38a33bf", "shortContent": "一个秋天的夜晚，诗人泊舟苏州城外的枫桥。江南水乡秋夜幽美的景色，吸引着这位怀着旅愁的客子，使他领略到一种情味隽永的诗意美，写下了这首意境清远的小诗。\n诗的前幅布景密度很大，十四个字写了六种景象，后幅却特别疏朗，两句诗只写了一件事：卧闻山寺夜钟。这是因为，诗人在枫桥夜泊中所得到的最鲜明深刻、最具诗意美的感觉印象，就是这寒山寺的夜半钟声。月落乌啼、霜天寒夜、江枫渔火、孤舟客子等景象，固然已从各方面显示...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "64733ee682772d45942ccc80", "shortContent": "一个秋天的夜晚，诗人泊舟苏州城外的枫桥。江南水乡秋夜幽美的景色，吸引着这位怀着旅愁的客子，使他领略到一种情味隽永的诗意美，写下了这首意境清远的小诗。\n\n题为“夜泊”，实际上只写“夜半”时分的景象与感受。诗的首句，写了午夜时分三种有密切关联的景象：月落、乌啼、霜满天。上弦月升起得早，半夜时便已沉落下去，整个天宇只剩下一片灰蒙蒙的光影。树上的栖乌大约是因为月落前后光线明暗的变化，被惊醒后发出几声啼鸣。...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '《庚溪诗话》：六一居士《诗话》谓：“句则佳矣，奈半夜非鸣钟时。”然余昔官姑苏，每三鼓尽，四鼓初，即诸寺钟皆鸣，想自唐时已然也。后观于鹄诗云：“定知别后家中伴，遥听缑山半夜钟。”白乐天云：“新秋松影下，半夜钟声后。”温庭筠云：“悠然旅榜频回首，无复松窗半夜钟。”则前人言之，不独张继也。
《批点唐诗正声》：诗佳，效之恐伤气。
《诗薮》：张继“夜半钟声到客船”，谈者纷纷，皆为昔人愚弄。诗流借景立言，惟在声律之调，兴象之合，区区事实，彼岂暇计？无论夜半是非，即钟声闻否，未可知也。
《唐诗选脉会通评林》：周敬曰：目未交睫而斋钟声遽至，则客夜恨怀，何假名言？周珽曰：看似口头机锋，却作口头机锋看不得。
《唐风怀》：南村曰：此诗苍凉欲绝，或多辨夜半钟声有无，亦太拘矣。且释家名幽宾钟者，尝彻夜鸣之。如于鹄“遥听缑山半夜钟”，温庭筠“无复松窗半夜钟”之类，不止此也。
《唐诗三集合编》：全篇诗意自“愁眠”上起，妙在不说出。
《唐诗摘钞》：三句承上起下，深而有力，从夜半无眠至晓，故怨钟声太早，搅人魂梦耳。语脉深深，只“对愁眠”三字略露意。夜半钟声或谓其误，或谓此地故有半夜钟，俱非解人。要之，诗人兴象所至，不可执着。必曰执着者，则“晨钟云外湿”、“钟声和白云”、“落叶满疏钟”皆不可通矣。
《笺注唐贤三体诗法》：何焯评：愁人自不能寐，却咎晓钟，诗人语妙，往往乃尔。
《碛砂唐诗》：“对愁眠”三字为全章关目。明逗一“愁”字，虚写竟夕光景，转辗反侧之意自见。
《唐诗别裁》：尘市喧阗之处，只闻钟声，荒凉寥寂可知。
《古唐诗合解》：此诗装句法最妙，似连而断，似断而连。
《大历诗略》：高亮殊特，青莲遗响。
《网师园唐诗笺》：写野景夜景，即不必作离乱荒凉解，亦妙。
《诗境浅说续编》：作者不过夜行记事之诗，随手写来，得自然趣味。诗非不佳，然唐人七绝佳作如林，独此诗流传日本，几妇稚皆习诵之。诗之传与不传，亦有幸有不幸耶！
《唐人绝句精华》：此诗所写枫桥泊舟一夜之景，诗中除所见所闻外，只一“愁”字透露心情。半夜钟声，非有旅愁者未必便能听到。后人纷纷辨夜半有无钟声，殊觉可笑。', 'center', 1413127904, '57b8d9ae5bbb50005b776383', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10271, '新添声杨柳枝词', NULL, 1155, 394, 2, 2, '温庭筠', NULL, 10069, '57b93da179bc44005ba0a318', '唐', 'ci', '词', 'http://baike.baidu.com/view/2625393.htm', '', '【其一】
一尺深红胜曲尘，天生旧物不如新。
合欢桃核终堪恨，里许元来别有人。
【其二】
井底点灯深烛伊，共郎长行莫围棋。
玲珑骰子安红豆，入骨相思知不知？', '温飞卿的诗词多丽词艳曲，生香活色，绣绘字句，镂金错彩，炫人眼目。此两句却是深情远韵，允称清丽。
红豆一名相思子，而骰子多为骨制。以骰子安红豆来喻入骨相思，纯用寻常事物作比喻，设想机巧，别开生面。但读来不觉晦涩，反而觉得「眉目清秀」，饶有风趣。这种双关修辞手法，用得巧妙，别有情致，但寓意深刻。
此外，前句「玲珑」两字，貌似形容骰子，却暗示了恋人的一颗「七巧玲珑心」，而后句「知不知」三字，爽脆委婉，回环复问，带有听觉上的特殊冲击，也极富感染力。', '胜曲尘：一作“蒙曲尘”。
深烛：音谐深嘱，此处用的是谐音双关的修辞手法，写女子「深嘱」情郎。
伊：人称代词，「你」。
长行：长行局，古代的一种博戏，盛行于唐。李肇《唐国史补·卷下》：「今之博戏，有长行最盛。其具有局有子，子有黄黑各十五，掷采之骰有二。」这里用此博戏的名称双关长途旅行。围棋：中国传统棋种。变化极复杂，棋理极深奥；高手对弈，一局棋常需数个时辰，甚至数日方可分出胜负。此处用「围棋」与「违期」的谐音，劝「郎」莫要误了归期。
玲珑：精巧貌。
骰（tóu）子：博具，相传为三国曹植创制，初为玉制，后演变为骨制，因其点着色，又称色子；为小立方体块状，六个面上分别刻有从一到六不同数目的圆点，其中一、四点数着红色，其馀点数皆着黑色。这骰子上的红点，即被喻为相思的红豆。
「入骨相思知不知」句：用骨制的骰子上的红点深入骨内，来隐喻入骨的相思。「入骨」是双关隐语。', '', '[{"bookId": "6277f1855b7e9043f114440e", "bookTitle": "温庭筠词全集", "articleId": "63126e907f0b9738b369afe4", "shortContent": "按：此首见稗海本《云溪友议》卷一。\n温庭筠《新添声杨柳枝》二首，始见《云溪友议》。清代顾嗣立刻《温飞卿诗集》时收作集外诗。又题作《新声杨柳枝》（见明毛晋辑《词苑英华》）。此调形式仍与《杨柳枝》一样，也是七言四句。加上“新添声”、“新声”，可能是由于乐曲增添了和声；所咏内容则超出了咏柳之范围，而歌咏其他事物。\n\n词作首二句感物起兴，写原来那块极鲜亮的红丝绸，却蒙上了灰尘，颜色变得像酒曲那样暗黄暗黄了...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f1855b7e9043f114440e", "bookTitle": "温庭筠词全集", "articleId": "63126e907f0b9738b369afe5", "shortContent": "按：此首见稗海本《云溪友议》卷一。\n这首词抒写女子对情郎的眷恋。前两句是叮嘱之辞。首句中“井底点灯”意指深处之烛，即“深烛”，隐喻“深嘱”。嘱咐什么呢？即“共郎长行莫围棋”，“共郎”表示女子正与郎相聚，“长行”既指当前进行的博戏的名称，也双关长途旅行，暗示着这是离别的时刻。因此，女子叮嘱郎不要“围棋”，这也是谐音双关，既指中国传统的棋艺，也意指“违误归期”，借此托出女子的内心隐曲。接着，由“长行”...", "authors": [], "pressName": "崇文书局"}]', '唐·范云溪《云溪友议·卷下》：裴郎中诚，晋国公次子也。足情调，善谈谐。举子温岐为友，好作歌曲，迄今饮席，多是其词焉。……二人又为《新添声杨柳枝》词，饮筵竟唱其词而打令也。……湖州崔郎中刍言，初为越副戎，宴席小有周德华。德华者，乃刘采春女也。虽《罗顷》之歌不及其母，而《杨柳枝》词，采春难及。崔副车宠爱之异，将至京洛。后豪门女弟子从其学者众矣。温、裴所称歌曲，请德华一陈音韵，以为浮艳之美，德华终不取焉。二君深有愧色。
宋·王頤堂《碧鸡漫志·卷二》：温飞卿号多作侧辞艳曲，其甚者「合欢桃叶（核）终堪恨，里许元来别有人。」「玲珑骰子安红豆，入骨相思知不知？」亦止此耳。
明·胡赤城《唐音癸籤·卷十三》：《新添声杨柳枝》，温庭筠作。时饮筵竞歌，独女优周德华以声太浮艳不取。', 'center', 1423170318, '57b5a54e8ac2470064456ee8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10272, '蝶恋花 · 阅尽天涯离别苦', NULL, 640, 210, 1, 2, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'ci', '词', 'http://baike.baidu.com/view/10622008.htm', '', '阅尽天涯离别苦。不道归来，零落花如许。花底相看无一语，绿窗春与天俱莫。
待把相思灯下诉。一缕新欢，旧恨千千缕。最是人间留不住，朱颜辞镜花辞树。', '光绪三十一年（西元一九〇五年）春天，长期奔走在外的词人回到家乡海宁。夫人莫氏原本就体弱多病，久别重逢，只见她面色更显憔悴，不禁万分感伤。这首词，或许就是此时而作。
“阅尽天涯离别苦”，开篇即直陈久别给人带来的苦楚。离别诚然是痛苦的，在词人眼里，连相逢也是苦楚的，时间无情，荡去了容颜，一分重逢之欢难抵十分久别之苦。莎士比亚《十四行诗》说“一切少男少女皆将如扫烟筒者同归于灰烬”，这正是王国维“最是人间留不住，朱颜辞镜花辞树”之深意。
上阕“阅尽”三句写天涯离别之苦，不抵时光流逝之悲。加倍写来，意尤深厚。“花底”二句中“无一语”，益觉悲凉。春暮，日暮，象征着情人们年华迟暮。作者以花喻人。“零落花如许”的“花”字，当即暗喻妻子。“零落”的是她的青春，她的美丽。这些年来，词人忍受了多少离别的煎熬，如今兴冲冲归来，不意却是如此境况，愧、悔、爱、怜齐集心头，真是离别苦，相见更苦。最妙的是“花底相看无一语”之句。这里的“花”无疑指庭院中的花树，花底看“花”，花面交映，真是浑然一体。大自然的“花”与人间的“花”一样，在这暮春时节，都开始走向“零落”。这其实是在暗喻零落的是他们的青春。
下阕“待把”三句更着力写迟暮的悲感。当日的别离，辜负了大好芳春，这千丝万缕的怨恨是无法消除的。“最是”二句中“辞镜”二字新，有点铁成金之妙。两“辞”字重用亦佳。在词的下阕作者把时间推向了夜晚，把地点推向了闺房，“花底”变成“灯下”。夫妻款款细语，互相诉说着多年来的别情。这短暂的良宵，短暂的欢会，能抵消那么多的相思之苦吗？纵使无穷的“旧恨”从此都烟消云散，都能够化作“新欢”，但令人十分无可奈何的是，青春已经逝去，朱颜已经暗淡，正如窗外的一树花影，也正在悄悄地凋零。“最是人间留不住”一句，写得十分惨痛。莫氏于两年后病逝，果真没有“留住”，这一句竟成为不幸而言中的恶谶。
这首词一改前人写重逢之喜，而抒重逢之苦，富有浓厚的悲剧色彩。通篇写花即写人，上下阕都有透过一层的转笔。但上阕明用“不道”字面，下阕却是暗转，匠心独运，甚是高妙。', '蝶恋花：词牌名，又名《凤栖梧》、《鹊踏枝》等。双调，六十字，上下阕各四仄韵。
阅：经历。
不道：不料。
如许：像这样。
绿窗：绿色的纱窗，指女子居所。韦端己《菩萨蛮》：「劝我早归家，绿窗人似花。」
莫：通「暮」，傍晚。
新欢：久别重逢的喜悦。
旧恨：长期以来的相思之苦。
朱颜辞镜花辞树：南唐·冯正中的《鹊踏枝》：「日日花前常病酒，不辞镜里朱颜瘦。」', '我早已历尽天涯离别的痛苦，想不到归来时，却看到百花如此零落的情景。我跟她，在花底黯然相看，都无一语。绿窗下的芳春，也与天时同样地迟暮了。
本来准备在夜阑灯下，细诉别后的相思。可是，一点点新的欢娱，又勾起了无穷的旧恨。在人世间最留不住的是，那在镜中一去不复返的青春和离树飘零的落花。', '[{"bookId": "60fc157134bfda01e0e91549", "bookTitle": "元明清词鉴赏辞典（新一版）", "articleId": "610e868203572034f659afbf", "shortContent": "莫道学人心枯寂，也能风流旖旎词。旧时的文人，大抵学富且兼情长，王国维尤其如此。他在近代学术史上泰斗般的地位，越来越得到人们的认可；他那些温雅绮丽、怊怅切情的小词，可以与历来的婉约名篇相媲美，这首《蝶恋花》便是一例。时在光绪三十一年（1905）春天，长期奔走在外的词人回到家乡海宁。他的夫人莫氏原就体弱多病，久别重逢，只见她面色益显憔悴，不禁万分感伤。这首诗，或许就是为此而作的吧。\n通篇不离一个“花”...", "authors": ["萧华荣"], "pressName": "上海辞书出版社"}, {"bookId": "6464506e7f27182da3524606", "bookTitle": "元明清词三百首鉴赏辞典", "articleId": "646b6fc5b6a81d0c531001f3", "shortContent": "莫道学人心枯寂，也能风流旖旎词。旧时的文人，大抵学富且兼情长，王国维尤其如此。他在近代学术史上泰斗般的地位，越来越得到人们的认可；他那些温雅绮丽、怊怅切情的小词，可以与历来的婉约名篇相媲美，这首《蝶恋花》便是一例。时在光绪三十一年（1905）春天，长期奔走在外的词人回到家乡海宁。他的夫人莫氏原就体弱多病，久别重逢，只见她面色益显憔悴，不禁万分感伤。这首诗，或许就是为此而作的吧。\n\n通篇不离一个“花...", "authors": ["萧华荣"], "pressName": "上海辞书出版社"}]', '近代诗评家陈邦炎《论静安词》：离别是一个悲剧，归来还是一个悲剧。静安词的悲剧色彩之特别浓厚，正表现在这些地方。他笔下的人间悲剧，不是一时、一地的，不是单一、孤立的，而是延绵相续、重重叠叠的。在静安眼中，人生的苦海，从时、空两方面看都是无边无际、没有尽头的。
香港中文大学哲学博士朱歧祥《选评七》：此言人生最不可掌握的生命。人间的分离，无论是生命的自然终结，抑或是客观环境的阻碍，都构成永恒的苦恼。', 'indent', 1413385877, '57b8ef70128fe10054c91d17', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10273, '一剪梅 · 舟过吴江', NULL, 786, 96, 5, 3, '蒋捷', NULL, 10071, '57ac9514c4c9710054655e3c', '宋', 'ci', '词', 'http://baike.baidu.com/view/859029.htm', '', '一片春愁待酒浇。江上舟摇，楼上帘招。秋娘渡与泰娘桥，风又飘飘，雨又萧萧。
何日归家洗客袍？银字笙调，心字香烧。流光容易把人抛，红了樱桃，绿了芭蕉。', '宋亡，作者深怀亡国之痛，隐居姑苏一带太湖之滨，漂泊不仕。此词为作者乘船经过吴江县时，见春光明艳的风景借以反衬自己羁旅不定的生活所作的一首词。
全词以首句的「春愁」为核心，用「点」「染」结合的手法，选取典型景物和情景层层渲染，写出了词人伤春的情绪及久客异乡思归的情绪。', '吴江：今江苏县名。在苏州南。
浇：浸灌，消除。
帘招：指酒旗。
秋娘渡：指吴江渡。秋娘：唐代歌伎常用名，或有用以通称善歌貌美之歌伎者。又称杜仲阳，为唐德宗时镇海军节度使李侍女。渡：一本作「度」。
桥：一本作「娇」。
萧萧：象声，雨声。
银字笙：管乐器的一种。调笙，调弄有银字的笙。
心字香：点熏炉里心字形的香。', '船在吴江上飘摇，我满怀羁旅的春愁，看到岸上酒帘子在飘摇，招揽客人，便产生了借酒消愁的愿望。船只经过令文人骚客遐想不尽的胜景秋娘渡与泰娘桥，也没有好心情欣赏，眼前是「风又飘飘，雨又萧萧」，实在令人烦恼。哪一天能回家洗客袍，结束客游劳顿的生活呢？哪一天能和家人团聚在一起，调弄镶有银字的笙，点燃熏炉里心字形的盘香？春光容易流逝，使人追赶不上，樱桃才红熟，芭蕉又绿了，春去夏又到。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e7511d635634aee3d73df", "shortContent": "这首词写作者乘船漂泊途中倦游思归的心情。词题“舟过吴江”表明，他当时正乘船经过濒临太湖东岸的吴江县。首句“一片春愁待酒浇”，揭出了“春愁”这个主题，并点出了时序。“一片”，形容他愁闷连绵不断。“待酒浇”，又从急需宽解表现了他愁绪之浓。唐韦庄《置酒不得》诗“满面春愁消不得”，不就是由于无酒浇愁以至春愁难消么！那么，词人的愁绪究竟在什么样的景况下产生的？产生了哪些愁绪？往下的描写就回答了这两个问题。\n...", "authors": ["范之麟"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec61234a8757d5a0ecbb3", "shortContent": "这首词写作者乘船漂泊途中倦游思归的心情。词题“舟过吴江”表明，他当时正乘船经过濒临太湖东岸的吴江县。首句“一片春愁待酒浇”，揭出了“春愁”这个主题，并点出了时序。“一片”，形容他愁闷连绵不断。“待酒浇”，又从急需宽解表现了他愁绪之浓。唐韦庄《置酒不得》诗：“满面春愁消不得”，不就是由于无酒浇愁以至春愁难消嚒！那么，词人的愁绪究竟在什么样的景况下产生的？产生了哪些愁绪？往下的描写就回答了这两个问题。...", "authors": ["范之麟"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059257e8f18b220af46207", "shortContent": "这首词写作者乘船漂泊途中倦游思归的心情。词题“舟过吴江”表明，他当时正乘船经过濒临太湖东岸的吴江县。首句“一片春愁待酒浇”，揭出了“春愁”这个主题，并点出了时序。“一片”，形容他愁闷连绵不断。“待酒浇”，又从急需宽解表现了他愁绪之浓。唐韦庄《置酒不得》诗：“满面春愁消不得”，不就是由于无酒浇愁以至春愁难消么！那么，词人的愁绪究竟在什么样的景况下产生的？产生了哪些愁绪？往下的描写就回答了这两个问题。...", "authors": ["范之麟"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413200909, '57b339122e958a0054727e91', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10274, '虞美人 · 听雨', NULL, 1323, 96, 4, 2, '蒋捷', NULL, 10071, '57ac9514c4c9710054655e3c', '宋', 'ci', '词', 'http://baike.baidu.com/view/384117.htm', '', '少年听雨歌楼上，红烛昏罗帐。壮年听雨客舟中，江阔云低、断雁叫西风。
而今听雨僧庐下，鬓已星星也。悲欢离合总无情，一任阶前、点滴到天明。', '南宋德祐二年（公元1276年），元灭南宋。宋元之际的词人，经历了这一沧桑变故，其国破之痛、家亡之恨，都在他们的作品中表现出来。其中，蒋捷是颇有代表性的作家。蒋捷用词作来抒发黍离之悲、铜驼荆棘之感，表现悲欢离合的个人遭遇，其中《虞美人·听雨》便是这一时期创作中的代表作，被选入《宋词三百首》。
这是一首小令，却概括出少年、壮年和晚年的特殊感受，可谓言简意赅。它以「听雨」为媒介，将几十年大跨度的时间和空间相融合。少年只知追欢逐笑享受陶醉；壮年飘泊孤苦触景伤怀；老年的寂寞孤独，一生悲欢离合，尽在雨声中体现。因受国亡之痛的影响，感情变得麻木，一任雨声淋漓，消解了喜怒哀乐，而其深层则潜隐着亡国愁情。', '虞美人：著名词牌之一。唐教坊曲。兹取两格，一为五十六字，上下阕各两仄韵，两平韵。一为五十八字，上下阕各两仄韵，三平韵。
昏：昏暗，罗帐：古代床上的纱幔。
断雁：失群孤雁
僧庐：僧寺，僧舍。
星星：白髮点点如星，形容白髮很多。左思《白髮赋》：「星星白髮，生于鬓垂。」
无情：无动于衷。
一任：听凭。', '年少的时候，歌楼上听雨，红烛盏盏，昏暗的灯光下罗帐轻盈。人到中年，在异国他乡的小船上，看蒙蒙细雨，茫茫江面，水天一线，西风中，一只失群的孤雁阵阵哀鸣。
而今，人已暮年，两鬓已是白髮苍苍，独自一人在僧庐下，听细雨点点。人生的悲欢离合的经历是无可奈何的，还是让台阶前一滴滴的小雨下到天亮吧。', '[{"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059257e8f18b220af46208", "shortContent": "这首词，层次清楚，脉络分明。分上、下片看，上片是感怀已逝的岁月，下片是慨叹目前的境况。从通篇看，它按时间顺序，由少年写到壮年，再写到老年，写了三个不同时期的不同环境、不同生活和不同心情，而以“听雨”作为一条贯串始终的线索。\n\n蒋捷生当宋、元易代之际，大约在宋度宗咸淳十年（1274）成进士，而几年以后宋朝就亡了。他的一生是在战乱年代中颠沛流离、饱经忧患的一生。这首词正是他的忧患余生的自述。他还写了一...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}]', '许昂霄《词综偶评》：此种襟怀固不易到，亦不愿到。
刘熙载：未极流动自然，然洗炼缜密，语多创获，其志视梅溪较贞，其思视梦窗较清。
《四库总目提要》：练字精深，调音谐畅，为倚声家之榘矱。', 'indent', 1413200955, '57b427ada3413100646ae918', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10275, '绮怀（其十五）', NULL, 392, 1197, 1, 3, '黄景仁', NULL, 10072, '57b9a221a633bd005d2ddbdd', '清', 'shi', '诗', 'http://baike.baidu.com/view/4434763.htm', '', '几回花下坐吹箫，银汉红墙入望遥。
似此星辰非昨夜，为谁风露立中宵。
缠绵思尽抽残茧，宛转心伤剥后蕉。
三五年时三五月，可怜杯酒不曾消。', '「绮」本意为「有花纹的丝织品」，后来引申为「美丽」，「绮怀」自是一种美丽的情怀，对清代诗人黄鹿菲来说，这种美丽来自一种爱情失落无处寻觅的绝望，因而更加凄婉动人。
黄鹿菲年轻时曾同自己的表妹两情相悦，但故事却仅有一个温馨的开始和无言的结局。正因如此，在《绮怀》之中，笼罩着隐隐约约的感伤。这种感伤，被那种无法排解的甜蜜回忆和苦涩的现实纠缠着，使得诗人一步步地陷入绝望中。
首联「几回花下坐吹箫，银汉红墙入望遥」。明月相伴，花下吹箫，美好的相遇。但是这衹是一个开始。那伊人所在的红墙虽然近在咫尺，却如天上的银汉一般遥遥而不可及。
第二联「似此星辰非昨夜，为谁风露立中宵」。这是最让人称道的一联，是的，今夜已非昨夜，昨夜的星辰，是记录着花下吹箫的浪漫故事，而今夜的星辰，却只有陪伴自己这个伤心之人。诗人是清醒的，他知道往事不可能重现，而正是因为这种清醒，纔使他陷入了更深的绝望。
在黄鹿菲的诗中，所有虚幻的安慰全消失了，衹有一个孤独的人依旧保持着一种望月的姿势，思念的姿势。试想，诗人独立中庭，久久望月，一任夜晚的冷露打湿了自己的衣裳，打湿了自己的心灵。而这种等待的尽头却衹能是一片虚无，这种思念的幻灭以及明明知道思念幻灭却仍然不能不思念的心态，正是最为绝望的一种心态。第三联「缠绵思尽抽残茧，宛转心伤剥后蕉」。这句可以和李义山的《无题》诗「春蚕到死丝方尽，蜡炬成灰泪始干」相媲美。春蚕吐丝，将自己重重包裹，正如诗人自己，用重重思念将自己重重包围。春蚕吐丝尽头是茧，是死，红烛流泪的尽头是灰，是死。而死，自然是人世间最为绝望的结局了。「芭蕉」也是幽怨的意象，李义山《代赠》诗有「芭蕉不展丁香结，同向春风各自愁」句。
尾联「三五年时三五月，可怜杯酒不曾消」。尾联同首联呼应，三五年时三五之月，自然是「几回花下坐吹箫」的往昔，而那时的美酒在今夜早已被酿成苦涩的酒。而这种苦涩是永远也无法消除的。因为，诗人无法不想念，也就无法同往昔和现实的夹缝之中突围出来。法国著名诗人缪塞说：「最美丽的诗歌也是最绝望的诗歌，有些不朽的篇章是纯粹的眼泪。」黄鹿菲的七言律诗《绮怀十六首之十五》，也正是因为这种绝望而更有了魅力。', '银汉红墙：唐·李义山《代应》：「本来银汉是红墙，隔得卢家白玉堂。」
星辰：唐·李义山《无题》：「昨夜星辰昨夜风，画楼西畔桂堂东。」
思：丝。
心：芯。皆双关语。', '', '[{"bookId": "60d939cea06dc908f045ad24", "bookTitle": "元明清诗鉴赏辞典（新一版）", "articleId": "610e8d17911759740c9b02de", "shortContent": "黄仲则少年时和他的表妹有一段恋情，不知何种原因有情人未成眷属。她远嫁多年之后，有一次，在她生子的“汤饼”宴会上，偶然相见，她还流露出未忘的旧情，引起作者的追忆和感慨，作“绮怀”十六首。\n此时诗人二十六岁（乾隆四十年），客居安徽寿州，以教书为业。那堪孤馆寂聊，感慨人生，追忆那已经失去的青春的绮丽的梦。诗的开篇说：想当年，我多少次坐在花下吹箫，以箫声向她倾诉自己的爱情。汉代风流才子司马相如不就曾“琴挑...", "authors": ["铁", "明"], "pressName": "上海辞书出版社"}]', '', 'center', 1363199255, '57b8f5320a2b58005c91f108', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10276, '大圣乐 · 陶成之生日', NULL, 61, 96, 1, 0, '蒋捷', NULL, 10071, '57ac9514c4c9710054655e3c', '宋', 'ci', '词', '', '', '笙月凉边，翠翘双舞，寿仙曲破。更听得艳拍流星，慢唱寿词初了，群唱莲歌。主翁楼上披鹤氅，展一笑、微微红透涡。襟怀好，纵炎官驻伞，长是春和。
千年鼻祖事业，记曾趁雷声飞快梭。但也曾三径，抚松采菊，随分吟哦。富贵云浮，荣华风过，淡处还他滋味多。休辞饮，有碧荷贮酒，深似金荷。', '', NULL, NULL, NULL, NULL, 'indent', 1468664674, '57b9b8e58ac2470063fee562', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10277, '归去来兮辞', NULL, 1351, 99, 7, 9, '陶渊明', NULL, 10011, '57b8fa07c4c97100558ef104', '晋', 'fu', '赋', 'http://baike.baidu.com/view/16966.htm', '余家贫，耕植不足以自给。幼稚盈室，瓶无储粟，生生所资，未见其术。亲故多劝余为长吏，脱然有怀，求之靡途。会有四方之事，诸侯以惠爱为德，家叔以余贫苦，遂见用于小邑。于时风波未静，心惮远役，彭泽去家百里，公田之利，足以为酒。故便求之。及少日，眷然有归欤之情。何则？质性自然，非矫厉所得。饥冻虽切，违己交病。尝从人事，皆口腹自役。於是怅然慷慨，深愧平生之志。犹望一稔，当敛裳宵逝。寻程氏妹丧于武昌，情在骏奔，自免去职。仲秋至冬，在官八十余日。因事顺心，命篇曰《归去来兮》。乙巳岁十一月也。', '归去来兮，田园将芜胡不归？既自以心为形役，奚惆怅而独悲？悟已往之不谏，知来者之可追。实迷途其未远，觉今是而昨非。舟遥遥以轻飏，风飘飘而吹衣。问征夫以前路，恨晨光之熹微。
乃瞻衡宇，载欣载奔。僮仆欢迎，稚子候门。三径就荒，松菊犹存。携幼入室，有酒盈樽。引壶觞以自酌，眄庭柯以怡颜。倚南窗以寄傲，审容膝之易安。园日涉以成趣，门虽设而常关。策扶老以流憩，时矫首而遐观。云无心以出岫，鸟倦飞而知还。景翳翳以将入，抚孤松而盘桓。
归去来兮，请息交以绝游。世与我而相违，复驾言兮焉求？悦亲戚之情话，乐琴书以消忧。农人告余以春及，将有事于西畴。或命巾车，或棹孤舟。既窈窕以寻壑，亦崎岖而经丘。木欣欣以向荣，泉涓涓而始流。善万物之得时，感吾生之行休。
已矣乎！寓形宇内复几时？曷不委心任去留？胡为乎遑遑欲何之？富贵非吾愿，帝乡不可期。怀良辰以孤往，或植杖而耘籽。登东皋以舒啸，临清流而赋诗。聊乘化以归尽，乐夫天命复奚疑！', '“归去来兮”就是“归去”，“来”和“兮”都是语助词，无义。辞，在汉代往往与赋并称为“辞赋”，源于“楚辞”，是一种抒情赋，同样讲究文字与韵节。全文描述了作者在回乡路上和到家后的情形，并设想日后的隐居生活，从而表达了作者对当时官场的厌恶和对农村生活的向往。另一方面，也流露出诗人的一种“乐天知命”的消极思想。', '“耕植不足以自给”句：耕田植桑不足以供自己生活。耕，耕田；植，植桑；以，来；给，供给。
幼稚盈室：孩子很多。幼稚，指孩童；盈，满。
瓶无储粟：米缸里没有剩馀的粮食。瓶，同“缾”，指盛米用的陶制容器、如甏（bèng）、瓮之类。
“生生所资，未见其术”句：赖以维持生计的本领我还没有找到。生生，犹言维持生计，前一“生”字为动词，后一“生”字为名词；资，凭藉；术，这里指经营生计的本领。
长吏：较高职位的县吏。指小官。
脱然：轻快貌。
有怀：有所思念（指有了做官的念头）。
靡途：没有门路。
会有四方之事：刚巧碰上有出使到外地去的事情。会，适逢；四方，意为到各处去。
诸侯：指州郡长官。
家叔：指陶夔（kuí），当时任太常卿。
惮：害怕。
役：服役。
彭泽：县名。在今江西省湖口县东。
眷然：依恋貌。
归欤（yú）之情：回去的心情。
质性：本性。
矫厉：造作勉强。
违己：违反自己本心。
交病：指思想上遭受痛苦。
从人事：从事于仕途中的人事交往。指做官。
口腹自役：为了满足口腹的需要而驱使自己。
怅然：失意。
一稔（rěn）：公田收获一次。稔，谷物成熟。
敛裳：收拾行装。
程氏妹：嫁给程家的妹妹。
武昌：今湖北省鄂城县。
骏奔：急着前去奔丧。
仲秋：农历八月。
乙巳岁：晋安帝义熙元年（西元四〇五年）。
归去来兮：意思是“回去吧”。来，助词，无义；兮，语气词。
田园将芜胡不归：田园将要荒芜了，为什么不回去？胡，同“何”。
“以心为形役”句：让心神为形体所役使。意思是本心不愿出仕，但为了免于饥寒，违背本意做了官。心，意愿；形，形体，指身体；役，奴役。
“奚惆怅而独悲”句：为什么悲愁失意。惆怅，失意貌。
悟已往之不谏：觉悟到过去做错了的事（指出仕）已经不能改正。谏，谏止，劝止。
“知来者之可追”句：知道未来的事（指归隐）还可以挽救。追，挽救，补救。
迷途：做官。
“舟遥遥以轻飏（yáng）”句：船在水面上轻轻地飘荡着前进。遥遥，摇摆不定貌；以，而；扬，飞扬，形容船行驶轻快貌。
“恨晨光之熹微”句：遗憾的是天刚刚放亮。恨，遗憾；熹微，微明，天未大亮。
乃瞻衡宇，载欣载奔：看见自己家的房子，心中欣喜，奔跑过去。瞻，远望；衡宇，横木为门之屋，谓简陋之屋。
稚子：幼儿。
三径：院中小路。汉朝蒋诩（xǔ）隐居之后，在院里竹下开辟三径，只于少数友人来往。后人以“三径”代指隐士所居。
“三径就荒，松菊犹存”句：院子里的小路快要荒芜了，松菊还长在那里。
盈樽：满杯。
眄（miàn）庭柯以怡颜：看看院子里的树木，觉得很愉快。眄，斜看，这里是“随便看看”的意思；柯，树枝；以，为了；怡颜，使面容现出愉快神色。
寄傲：寄托傲然自得的心情。傲，指傲世。
“审容膝之易安”句：觉得住在简陋的小屋里也非常舒服。审，觉察；容膝，只能容下双膝的小屋，极言其狭小。
“园日涉以成趣”句：天天到园里行走，自成一种乐趣。涉，涉足，走到。
“策扶老以流憩（qì）”句：拄着拐杖出去走走，随时随地休息。策，拄着。扶老，手杖。憩，休息。流憩，游息，就是没有固定的地方，到处走走歇歇。
“时矫首而遐观”句：时时抬起头向远处望望。矫，举。遐，远。
“云无心以出岫（xiù）”句：云气自然而然地从山里冒出。无心，无意地；岫，有洞穴的山，这里泛指山峰。
“景翳（yì）翳以将入”句：阳光黯淡，太阳快落下去了。景，日光；翳翳，阴暗貌。
盘桓：盘旋，徘徊，留恋不去。
扶孤松而盘桓：手扶孤松徘徊。
“请息交以绝游”句：意思是不再同官场有任何瓜葛。息交，停止与人交往断绝交游。
“世与我而相违，复驾言兮焉求”句：世事与我所想的相违背，还能努力探求什么呢？驾，驾车，这里指驾车出游去追求想要的东西；言，助词。
情话：知心话。
春及：春天到了。
“将有事于西畴”句：西边田野里要开始耕种了。有事，指耕种之事；事，这里指农事；畴，田地。
或命巾车：有时叫上一辆有帷的小车。巾车，有车帷的小车；或，有时。
或棹（zhào）孤舟：有时划一艘小船。棹，本义船桨。这里名词做动词，意为划桨。
“既窈窕以寻壑”句：经过幽深曲折的山谷。窈窕，幽深曲折貌；壑，山沟。
“亦崎岖而经丘”句：走过高低不平的山路。
木欣欣以向荣：草木茂盛。欣欣，向荣，都是草木滋长茂盛的意思。
涓涓：水流细微貌。
“善万物之得时，感吾生之行休”句：羡慕自然界万物一到春天便及时生长茂盛，感叹自己的一生行将结束。善，欢喜，羡慕；行休，行将结束。
已矣乎：算了吧！助词“矣”与“乎”连用，加强感叹语气。
“寓形宇内复几时，曷（hé）不委心任去留”句：活在世上能有多久，何不顺从自己的心愿，管它什么生与死呢？寓形，寄生；宇内，天地之间；曷，何；委心，随心所欲；去留，指生死。
“胡为乎遑遑欲何之：为什么心神不定，想到哪里去呢？遑遑，不安貌；之，往。
“帝乡不可期”句：仙境到不了。帝乡，仙乡，神仙居住的地方。期，希望，企及。
“怀良辰以孤往”句：爱惜美好的时光，独自外出。怀，留恋、爱惜；良辰，指上文所说万物得时的春天；孤往，独自外出。
“或植杖而耘耔”句：有时扶着拐杖除草培苗。植，立，扶着。耘，除草。耘，除草。籽，培苗。
“登东皋（gāo）以舒啸”句：登上东面的高地放声长啸，皋，高地；啸，撮口发出的长而清越的一种声音；舒，放。
“聊乘化以归尽”句：姑且顺其自然走完生命的路程。聊：姑且。乘化，随顺大自然的运转变化；归尽：到死；尽，指死亡。
“乐夫天命复奚疑”句：乐安天命，还有什么可疑虑的呢？复，还有；疑，疑虑。', '【序文】
我家贫穷，耕田植桑不足以供自己生活。孩子很多，米缸里没有剩馀的粮食，赖以维持生计的本领我还没有找到。亲友大都劝我去做官，我心里也有这个念头，可是求官缺少门路。正赶上出使到外地的事情，地方大吏以爱惜人才为美德，叔父也因为我家境贫苦（替我设法），我就被委任到小县做官。那时社会上动荡不安，心里惧怕到远处当官。彭泽县离家一百里，公田收获的粮食，足够造酒饮用，所以就请求去那里。等到过了一些日子，便产生了留恋故园的怀乡感情。那是为什么？本性任其自然，这是勉强不得的；饥寒虽是急需解决的问题，但是违背本意去做官，身心都感痛苦。过去为官做事，都是为了吃饭而役使自己。于是惆怅感慨，心情激动不平，深深有愧於平生的志愿。仍然希望看到这一茬庄稼成熟，便收拾行装连夜离去。不久，嫁到程家的妹妹在武昌去世，去吊丧的心情像骏马奔驰一樣急迫，自己请求免去官职。自立秋第二个月到冬天，在职共八十多天。因辞官而顺遂了心愿，写了一篇文章，题目叫《归去来兮》。乙巳年（晋安帝义熙元年）十一月。
【正文】
回去吧！田园都将要荒芜了，为什么不回去呢？既然自己的心灵被躯壳所役使，那为什么悲愁失意？我明悟过去的错误已不可挽回，但明白未發生的事尚可补救。我确实入了迷途，但不算太远，已觉悟如今的选择是正确的，而曾经的行为才是迷途。船在水面轻轻地飘荡着前进，轻快前行，风轻飘飞舞，吹起了衣袂翩翩。我向行人询问前面的路，遗憾的是天刚刚放亮。
终於看到了自己的家，心中欣喜，奔跑过去。家僮欢快地迎接我，幼儿们守候在门庭等待。院子里的小路快要荒芜了，松菊还长在那里。我带着幼儿们进入屋室，早有清酿溢满了酒樽。我端起酒壶酒杯自斟自饮，看看院子裏的树木，觉得很愉快；倚着南窗寄托傲然自得的心情，觉得住在简陋的小屋里也非常舒服。天天到院子里走走，自成一种乐趣，小园的门经常地关闭，拄着拐杖出去走走，随时随地休息，时时抬头望着远方。云气自然而然的从山里冒出，倦飞的小鸟也知道飞回巢中；阳光黯淡，太阳快落下去了，手抚孤松徘徊。
回来呀！我要跟世俗之人断绝交游。世事与我所想的相违背，还能努力探求什么呢？以亲人间的知心话为愉悦，以弹琴读书为乐来消除忧愁。农夫告诉我春天到了，西边田野里要开始耕种了。有时叫上一辆有帷的小车，有时划过一艘小船。有时经过幽深曲折的山谷，有时走过高低不平的山路。草木茂盛，水流细微。羡慕自然界的万物一到春天便及时生长茂盛，感叹自己的一生行将结束。
算了吧！活在世上还能有多久，为什么不放下心来任其自然地生死？为什么心神不定，想要到哪裏去？富贵不是我所求，修成神仙是没有希望的。趁着春天美好的时光，独自外出。有时放下手杖，拿起农具除草培土；登上东边的高岗放声呼啸，傍着清清的溪流吟诵诗篇。姑且顺其自然走完生命的路程，抱定乐安天命的主意，还有什么可犹疑的呢！', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1e05e272d4b2254f079", "shortContent": "逆江而行的一叶扁舟上，站立着从彭泽弃官归家的诗人陶渊明。猎猎的江风，吹得他衣袂飘拂。此刻，他的心境正如那轻轻摇漾的小舟，既惆怅，又快意：想起以往的几度出仕，“皆口腹自役”，有违平生向往自由的情性，便不免爽然若失；仰对江天，想到终于从“迷途”返回，从此冲破官场的羁绊，就又欣然开怀。遥远的山村，似正有一个热切的声音在呼唤：“归来！归来！”而浪花飞溅的舟上，他那颗激动的心，也分明作出了殷殷的回应：“归去...", "authors": ["张", "巍"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4547f27182da33f706b", "bookTitle": "陶渊明诗文鉴赏辞典", "articleId": "646aad36902ee364cc759108", "shortContent": "逆江而行的一叶扁舟上，站立着从彭泽弃官归家的诗人陶渊明。猎猎的江风，吹得他衣袂飘拂。此刻，他的心境正如那轻轻摇漾的小舟，既惆怅，又快意：想起以往的几度出仕，“皆口腹自役”，有违平生向往自由的情性，便不免爽然若失；仰对江天，想到终于从“迷途”返回，从此冲破官场的羁绊，就又欣然开怀。遥远的山村，似正有一个热切的声音在呼唤：“归来！归来！”而浪花飞溅的舟上，他那颗激动的心，也分明作出了殷殷的回应：“归去...", "authors": ["张巍"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "6471dd6c5e6bb82b8cfb3eed", "shortContent": "逆江而行的一叶扁舟上，站立着从彭泽弃官归家的诗人陶渊明。猎猎的江风，吹得他衣袂飘拂。此刻，他的心境正如那轻轻摇漾的小舟，既惆怅，又快意：想起以往的几度出仕，“皆口腹自役”，有违平生向往自由的情性，便不免爽然若失；仰对江天，想到终于从“迷途”返回，从此冲破官场的羁绊，就又欣然开怀。遥远的山村，似正有一个热切的声音在呼唤：“归来！归来！”而浪花飞溅的舟上，他那颗激动的心，也分明作出了殷殷的回应：“归去...", "authors": ["张巍"], "pressName": "上海辞书出版社"}]', '', 'indent', 1363199517, '57b8fb0fc4c97100558ef7c5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10278, '唐多令', NULL, 674, 451, 4, 3, '刘过', NULL, 10073, '57b9aa917db2a20068bdc258', '宋', 'ci', '词', 'http://baike.baidu.com/view/3256057.htm', '安远楼小集，侑觞歌板之姬黄其姓者，乞词于龙洲道人，为赋此《唐多令》。同柳阜之、刘去非、石民瞻、周嘉仲、陈孟参、孟容。时八月五日也。', '芦叶满汀洲，寒沙带浅流。二十年重过南楼。柳下系船犹未稳，能几日，又中秋。
黄鹤断矶头，故人今在否？旧江山浑是新愁。欲买桂花同载酒，终不似、少年游。', '此词写秋日重登二十年前旧游地武昌南楼，所见所思，缠绵凄怆。在表层山水风光乐酒留连的安适下面，可以感到作者心情沉重的失落。
刘过的爱国词篇，多为豪爽奔放，痛快淋漓之作。但这首《唐多令》却写得蕴藉含蓄，耐人咀嚼。与其他爱国词比较，的确别具一格，故而流传甚广。《唐多令》原为僻调，罕有填者。自刘词出而和者如林，其调乃显。刘辰翁即追和七阕，周密而因其有“重过南楼”之语，为更名曰《南楼令》，可见此词影响之大。', '唐多令：词牌名，也写作《糖多令》，又名《南楼令》，双调，六十字，上下片各四平韵，亦有前片第三句加一衬字者。
安远楼：在今武昌黄鹄山上，又称南楼。宋·姜夔《翠楼吟》词序云：“淳熙十三年（公元1186年）冬，武昌安远楼成。”当时武昌是南宋和金人交战的前方。
小集：此指小宴。
侑（yòu）觞歌板：指酒宴上劝饮执板的歌女。侑觞，劝酒。歌板，执板奏歌。
龙洲道人：刘过自号。
汀洲：水中小洲。
“二十年重过南楼”句：南楼初建时期，刘过曾漫游武昌，过了一段“黄鹤楼前识楚卿，彩云重叠拥娉婷”（《浣溪沙》）的豪纵生活。南楼，指安远楼。
系船：一作“系舟”。
黄鹤断矶：黄鹤矶，在武昌城西，上有黄鹤楼。断矶，形容矶头荒凉。
故人今在否：一作“故人曾到否”，又作“故人今在不”。
浑是：全是。', '同一帮友人在安远楼聚会，酒席上一位姓黄的歌女请我作一首词，我便当场创作此篇。时为八月五日。
芦苇的枯叶落满沙洲，浅浅的寒水在沙滩上无声无息地流过。二十年光阴似箭，如今我又重新登上这旧地南楼。柳树下的小舟尚未系稳，我就匆匆忙忙重回故地。因为过不了几日就是中秋。
早已破烂不堪的黄鹤矶头，我的老朋友有没有来过？我眼前满目是苍凉的旧江山，又平添了无尽的绵绵新愁。想要买上桂花，带着美酒一同去水上泛舟逍遥一番。但却没有了少年时那种豪迈的意气。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74f02cee9a0c24ec7dbc", "shortContent": "这是一首忧国伤时、沉哀入骨的名作。安远楼，在武昌黄鹄山上，一名南楼。建于淳熙十三年（1186）。姜夔曾自度《翠楼吟》词纪之。其小序云“淳熙丙午冬，武昌安远楼成，与刘去非诸友落之，度曲见志”，具载其事。序里提到的刘去非，这次又陪刘过游览，列名于两位词家的篇籍，可谓词坛佳话。\n刘过重访南楼，距上次登览几二十年。时值韩侂胄当国，夸诞轻躁，欲启伐金之衅。这是一个国变日亟、危机四伏的时刻，当时有识之士，皆以...", "authors": ["周笃文"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5f22e6a6b501f967371", "shortContent": "这是一首忧国伤时、沉哀入骨的名作。安远楼，在武昌黄鹄山上，一名南楼。建于淳熙十三年（1186）。姜夔曾自度《翠楼吟》词纪之。其小序云“淳熙丙午冬，武昌安远楼成，与刘去非诸友落之，度曲见志”，具载其事。序里提到的刘去非，这次又陪刘过游览，列名于两位词家的篇籍，可谓词坛佳话。\n刘过重访南楼，距上次登览几二十年。时值韩侂胄当国，夸诞轻躁，欲启伐金之衅。这是一个国变日亟、危机四伏的时刻，当时有识之士，皆以...", "authors": ["周笃文"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255f6542516c6de7fb0", "shortContent": "这是一首忧国伤时、沉哀入骨的名作。安远楼，在武昌黄鹄山上，一名南楼。建于淳熙十三年（1186）。姜夔曾自度《翠楼吟》词纪之。其小序云“淳熙丙午冬，武昌安远楼成，与刘去非诸友落之，度曲见志”，具载其事。序里提到的刘去非，这次又陪刘过游览，列名于两位词家的篇籍，可谓词坛佳话。\n\n刘过重访南楼，距上次登览几二十年。时值韩侂胄当国，夸诞轻躁，欲启伐金之衅。这是一个国变日亟、危机四伏的时刻，当时有识之士，皆...", "authors": ["周笃文"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f4f73206168b2e0210d", "shortContent": "刘过曾伏阙上书，力陈恢复方略，未被采纳而落拓江湖。宁宗时，曾为辛弃疾幕僚，常以词唱和。撰有《龙洲集》、《龙洲词》。其词多写政治抱负和抒发怀才不遇的感慨，其中的爱国词篇，深得辛弃疾的神髓，多为豪爽奔放、淋漓痛快之作。本词为重访南楼（安远楼，在武昌，是南宋与金交战的前线），伤时忧国之作，写得温婉含蓄，别具一格，是刘过词集中不多见的清逸蕴藉之作。\n\n词的上片写景叙事，满目凄怆。下片借景抒情，一腔悲愤。首...", "authors": ["吕淑娟"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127049e6f69b71e93f626a", "shortContent": "刘过曾伏阙上书，力陈恢复方略，未被采纳而落拓江湖。宁宗时，曾为辛弃疾幕僚，常以词唱和。撰有《龙洲集》、《龙洲词》。其词多写政治抱负和抒发怀才不遇的感慨，其中的爱国词篇，深得辛弃疾的神髓，多为豪爽奔放、淋漓痛快之作。本词为重访南楼（安远楼，在武昌，是南宋与金交战的前线），伤时忧国之作，写得温婉含蓄，别具一格，是刘过词集中不多见的清逸蕴藉之作。\n\n词的上片写景叙事，满目凄怆。下片借景抒情，一腔悲愤。首...", "authors": ["吕淑娟"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631272139761253910e90688", "shortContent": "刘过曾伏阙上书，力陈恢复方略，未被采纳而落拓江湖。宁宗时，曾为辛弃疾幕僚，常以词唱和。撰有《龙洲集》《龙洲词》。其词多写政治抱负和抒发怀才不遇的感慨，其中的爱国词篇，深得辛弃疾的神髓，多为豪爽奔放、淋漓痛快之作。本词为重访南楼（安远楼，旧时与敌纷争之地），伤时忧国之作，写得温婉含蓄，别具一格，是刘过词集中不多见的清逸蕴藉之作。\n词的上片写景叙事，满目凄怆。下片借景抒情，一腔悲愤。首句借描写清冷的秋...", "authors": ["吕淑娟"], "pressName": "崇文书局"}]', '清·黄蓼园《蓼园词选》：宋当南渡，武昌系与敌纷争之地，重过能无今昔之感？词旨清越，亦见含蓄不尽这致。
清·李佳《左庵词话》：小令中工品。', 'indent', 1363201046, '57b922e7c4c9710055904842', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10294, '辛夷坞', NULL, 326, 394, 1, 4, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/704850/5029274.htm', '', '木末芙蓉花，山中发红萼。
涧户寂无人，纷纷开且落。', '此诗短短四句，在描绘了辛夷花的美好形象的同时，又写出了一种落寞的景况和环境。此诗由花开写到花落，而以一句环境描写插入其中，一前后境况迥异，由秀发转为零落。尽管画面上似乎不着痕迹，却能让人体会到一种对时代环境的寂寞感。', '辛夷坞（wù）：辋川地名，因盛产辛夷花而得名，今陕西省蓝田县内。坞：周围高而中央低的谷地。
木末芙蓉花：即指辛夷。辛夷，落叶乔木。其花初出时尖如笔椎，故又称木笔，因其初春开花，又名应春花。花有紫白二色，大如莲花。白色者名玉兰。紫者六瓣，瓣短阔，其色与形似莲花，莲花亦称芙蓉。辛夷花开在枝头，故以“木末芙蓉花”借指。
木末：树梢，枝头。
芙蓉花：此指辛夷花，因芙蓉花与辛夷花形相似，花色相近。
萼（è）：花萼，花的组成部分之，由若干片状物组成，包在花瓣外面，花开时托着花瓣。
涧（jiàn）户：一说指涧边人家；一说山涧两崖相向，状如门户。
且：又。', '枝条最顶端的木芙蓉花，在山中绽放鲜红的花萼。
涧口一片寂静杳无人迹，纷纷扬扬独自开了又落。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9297dbb8b379ee09597b", "shortContent": "这是王维田园组诗《辋川集》二十首中的第十八首。这组诗全是五绝，犹如一幅幅精美的绘画小品，从多方面描绘了辋川一带的风物。作者很善于从平凡的事物中发现美，不仅以细致的笔墨写出景物的鲜明形象，而且往往从景物中写出一种环境气氛和精神气质。\n“木末芙蓉花，山中发红萼。”“木末”，指树杪。辛夷花不同于梅花、桃花之类，它的花苞打在每一根枝条的最末端上，形如毛笔，所以用“木末”二字是很准确的。“芙蓉花”，即指辛夷...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270447ccdb86c49f29222", "shortContent": "这是一种美丽的花，它的花苞在每一根枝条的末端傲然绽放，有如一枝枝带露的荷花，亭亭地、静静地在自己的世界言说自己的美丽。“山中发红萼”，在青青的山色中，红色是一种多么醒目的颜色！它可以在人眼的第一刻吸引你、打动你，让你的目光久久为它停留。红色亦是一种生命的色彩，代表温暖与活力，神秘的辛夷坞中，一片春意萌动。就是这种美丽的花儿，寂寞地开在寂寞的涧户，随着春天的脚步慢慢零落。但这也是一种美丽的零落，是“...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127077f2af4e09d55b6796", "shortContent": "这是一种美丽的花，它的花苞在每一根枝条的末端傲然绽放，有如一枝枝带露的荷花，亭亭地、静静地在自己的世界言说自己的美丽。“山中发红萼”，在青青的山色中，红色是一种多么醒目的颜色！它可以在人眼的第一刻吸引你、打动你，让你的目光久久为它停留。红色亦是一种生命的色彩，代表温暖与活力，神秘的辛夷坞中，一片春意萌动。就是这种美丽的花儿，寂寞地开在寂寞的涧户，随着春天的脚步慢慢零落。但这也是一种美丽的零落，是“...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646477d845e4710056c2ef0b", "shortContent": "这是王维田园组诗《辋川集》二十首中的第十八首。这组诗全是五绝，犹如一幅幅精美的绘画小品，从多方面描绘了辋川一带的风物。作者很善于从平凡的事物中发现美，不仅以细致的笔墨写出景物的鲜明形象，而且往往从景物中写出一种环境气氛和精神气质。\n\n“木末芙蓉花，山中发红萼。”“木末”，指树杪。辛夷花不同于梅花、桃花之类，它的花苞打在每一根枝条的最末端上，形如毛笔，所以用“木末”二字是很准确的。“芙蓉花”，即指辛...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}]', '《王孟诗评》：顾云：其意不欲着一字，渐可语禅。
《唐风定》：此诗每为禅宗所引，反令减价，衹就本色观，自是绝顶。
《唐贤三昧集笺注》：思致平淡闲雅，亦自可爱。
《唐诗别裁》：幽极。借用楚词，因颜色相似也。
《诗法易简录》：幽淡已极，却饶远韵。
《唐人万首绝句选评》：刻意取远味。
《唐诗真趣编》：摩诘深于禅，此是心无挂碍境界。虽在世中，脱然世外，令人动海上三山之想。
《诗境浅说续编》：东坡《罗汉赞》：「空山无人，水流花开。」世称妙悟，亦即此诗之意境。', 'center', 1415639714, '57ac9bbac4c971005465949a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10279, '摸鱼儿 · 雁丘词', NULL, 910, 819, 5, 2, '元好问', NULL, 10074, '57b9127ca633bd00665de11d', '金', 'ci', '词', 'http://baike.baidu.com/view/1221627.htm', '乙丑岁赴试并州，道逢捕雁者云：“今日获一雁，杀之矣。其脱网者悲鸣不能去，竟自投于地而死。”予因买得之，葬之汾水之上，垒石为识，号曰“雁丘”。同行者多为赋诗，予亦有《雁丘词》。旧所作无宫商，今改定之。', '问世间，情是何物，直教生死相许？天南地北双飞客，老翅几回寒暑！欢乐趣，离别苦，就中更有痴儿女。君应有语：渺万里层云，千山暮雪，只影向谁去？
横汾路，寂寞当年箫鼓，荒烟依旧平楚。招魂楚些何嗟及，山鬼暗啼风雨。天也妒，未信与，莺儿燕子俱黄土。千秋万古，为留待骚人，狂歌痛饮，来访雁丘处。', '这是一首咏物词，词人为雁殉情而死的事所感动，才挥笔写下了《摸鱼儿·雁丘词》，寄托自己对殉情者的哀思。这首词紧紧围绕“情”字，以雁拟人，谱写了一曲凄恻动人的恋情悲歌。在词中，作者驰骋丰富的想象，运用比喻、拟人等艺术手法，对大雁殉情而死的故事，展开了深入细致的描绘，再加以充满悲剧气氛的环境描写的烘托，塑造了忠于爱情、生死相许的大雁的艺术形象，谱写了一曲凄婉缠绵，感人至深的爱情悲歌，是为中国古代歌颂忠贞爱情的佳词。', '摸鱼儿：一名《摸鱼子》，又名《买陂塘》、《迈陂塘》、《双蕖怨》等。唐教坊曲，后用为词牌。宋词以晁补之《琴趣外篇》所收为最早。双调，一百一十六字，前阕六仄韵，后阕七仄韵。双结倒数第三句第一字皆领格，宜用去声。
乙丑岁：金章宗泰和五年（公元1205年），以天干地支纪年为乙丑年，当时元好问年仅十六岁。
赴试并州：《金史·选举志》载：金代选举之制，由乡至府，由府至省及殿试，凡四试。明昌元年罢免乡试。府试试期在秋八月。府试处所承安四年赠太原，共为十处。
识（zhì）：标志。
雁丘：嘉庆《大清一统志》：雁丘在阳曲县西汾水旁。金元好问赴府试……累土为丘，作《雁丘词》。
无宫商：不协音律。
直教：竟使。
许：随从。
双飞客：大雁双宿双飞，秋去春来，故云。
“就中更有痴儿女”句：这雁群中更有痴迷于爱情的。
“君应有语：渺万里层云，千山暮雪，只影向谁去”句：万里长途，层云迷漫，千山暮景，处境凄凉，形影孤单为谁奔波呢？
平楚：远望树梢齐平，故称平楚。楚，指丛木。
“横汾路，寂寞当年箫鼓，荒烟依旧平楚”句：这葬雁的汾水，当年汉武帝横渡时何等热闹，如今寂寞凄凉。汉武帝《秋风辞》：“泛楼船兮济汾河，横中流兮扬素波，箫鼓鸣兮发棹歌。”
招魂楚些（suò）：《楚辞·招魂》句尾皆有“些”字。
何嗟及：悲叹无济于事。
山鬼：《楚辞·九歌·山鬼》篇指山神，此指雁魂。
“招魂楚些何嗟及，山鬼暗啼风雨”句：我欲为死雁招魂又有何用，雁魂也在风雨中啼哭。
暗啼：一作“自啼”。
“天也妒，未信与，莺儿燕子具黄土”句：不信殉情的雁子与普通莺燕一样都寂灭无闻变为黄土，它将声名远播，使天地忌妒。
骚人：诗人。', '天啊！请问世间的各位，爱情究竟是什么，竟会令这两只飞雁以生死来相对待？南飞北归遥远的路程都比翼双飞，任它多少的冬寒夏暑，依旧恩爱相依为命。比翼双飞虽然快乐，但离别才真的是楚痛难受。到此刻，方知这痴情的双雁竟比人间痴情儿女更加痴情！相依相伴，形影不离的情侣已逝，真情的雁儿心里应该知道，此去万里，形孤影单，前程渺渺路漫漫，每年寒暑，飞万里越千山，晨风暮雪，失去一生的至爱，形单影隻，即使苟且活下去又有什么意义呢？
这葬雁的汾水，当年汉武帝横渡时何等热闹，如今寂寞凄凉。我欲为死雁招魂又有何用，雁魂也在风雨中啼哭。双雁生死相许的深情连上天也嫉妒，殉情的大雁决不会和莺儿燕子一般，死后化为一抔尘土。将会留得生前身后名，与世长存。狂歌纵酒，寻访雁丘坟故地，来祭奠这一对爱侣的亡灵。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e751ad635634aee3d740b", "shortContent": "这是一首咏物词。作者驰骋着丰富的想象，运用拟人等艺术手法，紧紧围绕“情”字，对大雁殉情的故事展开了深入细致的描绘，塑造了一个忠于爱情的大雁的艺术形象，谱写了一曲凄恻动人的恋情悲歌，寄托了作者对殉情者的哀思。\n情因景而生，词为情而作。作者在词前小序中说：“太和五年乙丑岁，赴试并州，道逢捕雁者云：‘今旦获一雁，杀之矣。其脱网者悲鸣不能去，竟自投于地而死。’予因买得之，葬之汾水之上，累石为识，号曰雁丘。...", "authors": ["薛祥生"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec61b34a8757d5a0ecbce", "shortContent": "这是一首咏物词。作者驰骋着丰富的想象，运用拟人等艺术手法，紧紧围绕“情”字，对大雁殉情的故事展开了深入细致的描绘，塑造了一个忠于爱情的大雁的艺术形象，谱写了一曲凄恻动人的恋情悲歌，寄托了作者对殉情者的哀思。\n情因景而生，词为情而作。作者在词前小序中说：“太和五年乙丑岁，赴试并州，道逢捕雁者云：‘今旦获一雁，杀之矣。其脱网者悲鸣不能去，竟自投于地而死。’予因买得之，葬之汾水之上，累石为识，号曰雁邱。...", "authors": ["薛祥生"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059257e8f18b220af46215", "shortContent": "这是一首咏物词。作者驰骋着丰富的想象，运用拟人等艺术手法，紧紧围绕“情”字，对大雁殉情的故事展开了深入细致的描绘，塑造了一个忠于爱情的大雁的艺术形象，谱写了一曲凄恻动人的恋情悲歌，寄托了作者对殉情者的哀思。\n\n情因景而生，词为情而作。作者在词前小序中说：“太和五年乙丑岁，赴试并州，道逢捕雁者云：‘今旦获一雁，杀之矣。其脱网者悲鸣不能去，竟自投于地而死。’予因买得之，葬之汾水之上，累石为识，号曰雁邱...", "authors": ["薛祥生"], "pressName": "上海辞书出版社"}, {"bookId": "6464506e7f27182da3524606", "bookTitle": "元明清词三百首鉴赏辞典", "articleId": "646733d745e4710056cec9c0", "shortContent": "这是一首咏物词。作者驰骋着丰富的想像，运用拟人等艺术手法，紧紧围绕“情”字，对大雁殉情的故事展开了深入细致的描绘，塑造了一个忠于爱情的大雁的艺术形象，谱写了一曲凄恻动人的恋情悲歌，寄托了作者对殉情者的哀思。\n\n情因景而生，词为情而作，雁殉情而死的事，强烈地拨动了作者心灵的琴弦，使其挥笔写下了这首充满激情的词。\n\n这首词的主旨是赞美雁情坚贞专一。词的开头三句，陡然发问，奇思妙想，破空而来。作者本要咏...", "authors": ["薛祥生"], "pressName": "上海辞书出版社"}]', '', 'indent', 1423170367, '57b900cddf0eea006334e18f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10280, '终南别业', NULL, 733, 394, 1, 8, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383317.htm', '', '中岁颇好道，晚家南山陲。
兴来每独往，胜事空自知。
行到水穷处，坐看云起时。
偶然值林叟，谈笑无还期。', '这首诗属于近体诗中的五律，是唐代山水田园诗人王维的代表作之一。诗中把退隐後自得其乐的闲适情趣，写得有声有色，惟妙惟肖。诗人兴致来了就独自信步漫遊，走到水的尽头就坐看行雲变幻，这生动地刻画了一位隐居者的形象，如见其人。同山间老人谈谈笑笑，把回家的时间也忘了，十分自由惬意，这是诗人捕捉到了典型环境中的典型事例，诗把退隐後自得其乐的闲适情趣，写得有声有色，突出地表现了退隐者豁达的性格。平白如话，却极具功力，诗味、理趣二者兼备。', '中岁：中年。
好（hào）：喜好。
道：这里指佛教。
家：安家。
南山：即终南山。
陲（chuí）：边缘，旁边，边境；南山陲，指辋川别墅所在地，意思是终南山脚下。
胜事：美好的事。
值：遇到。
叟（sǒu）：老翁。
无还期：没有回还的准确时间。', '（自己）中年以后厌尘俗喧嚣，信奉道教，晚年定居安家在南山边陲，常游山水。
兴致来了，就独自一人前往欣赏这美丽的景色，这种美好的事只能自得其乐。
随意而行，不知不觉，竟走到流水的尽头，看是无路可走了，于是索性就地坐下来，看那悠闲无心的云兴起漂游。
遇见山林中的一位老者，就与他谈论山间水边之事，相与留连，忘了回去的时间。', '[{"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc40921", "shortContent": "王维晚年官至尚书右丞，职务可谓不小。其实，由于政局变化反复，他早已看到仕途的艰险，便想超脱这个烦扰的尘世。他吃斋奉佛，悠闲自在，大约四十岁后，就开始过着亦官亦隐的生活。这首诗描写的，就是那种自得其乐的闲适情趣。\n\n开头两句“中岁颇好道，晚家南山陲”，叙述自己中年以后即厌尘俗，而信奉佛教。“晚”是晚年；“南山陲”指辋川别墅所在地。此处原为宋之问别墅，王维得到这个地方后，完全被那里秀丽、寂静的田园山水...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e020a9", "shortContent": "这是一篇潇洒的诗作，用字潇洒，诗境也潇洒。\n\n“中岁颇好道，晚家南山陲”，这是超脱了烦扰尘世的表述：精神上获得了皈依，事实上也找到了一方乐土。王维约在四十岁以后，就开始过亦官亦隐的生活，这让他拥有了享受不尽的自在与悠闲。\n\n只要诗人愿意，他可以随时出发，去到自己想要去的地方。在独自游历的过程中享受一份怡然自得的乐趣。这份乐趣，似乎无须与人分享，诗人自能独得其中真味。或许因某种原因的触发，或许竟是无...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646458245e6bb82b8cc2539c", "shortContent": "王维晚年官至尚书右丞，职务可谓不小。其实，由于政局变化反复，他早已看到仕途的艰险，便想超脱这个烦扰的尘世。他吃斋奉佛，悠闲自在，大约四十岁后，就开始过着亦官亦隐的生活。这首诗描写的，就是那种自得其乐的闲适情趣。\n\n开头两句“中岁颇好道，晚家南山陲”，叙述自己中年以后即厌尘俗，而信奉佛教。“晚”是晚年；“南山陲”指辋川别墅所在地。此处原为宋之问别墅，王维得到这个地方后，完全被那里秀丽、寂静的田园山水...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646463de5b7b0d4f450f8ad7", "shortContent": "王维晚年官至尚书右丞，职务可谓不小。其实，由于政局变化反复，他早已看到仕途的艰险，便想超脱这个烦扰的尘世。他吃斋奉佛，悠闲自在，大约四十岁后，就开始过着亦官亦隐的生活。这首诗描写的，就是那种自得其乐的闲适情趣。\n\n开头两句“中岁颇好道，晚家南山陲”，叙述自己中年以后即厌尘俗，而信奉佛教。“晚”是晚年；“南山陲”指辋川别墅所在地。此处原为宋之问别墅，王维得到这个地方后，完全被那里秀丽、寂静的田园山水...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}]', '《诗人玉屑》：此诗造意之妙，至与造物相表裏，岂直诗中有画哉！观其诗，知其蝉蜕尘埃之中，浮遊万物之表者也。山谷老人云：余顷年登山临水，未尝不读王摩诘诗，顾知此老胸次，定有泉石膏肓之疾。
《瀛奎律髓》：右丞此诗有一唱三叹不可穷之妙。
《王孟诗评》：无言之境，不可说之味，不知者以为淡易，其质如此，故自难及。
《批选唐诗》：迫近性情，悄然忘言。
《唐诗镜》：五六神境。
《唐诗归》：锺云：此等作衹似未有声诗之先，便有此一首诗，然读之如新出诸口及初入目者，不觉见成，其故难言。谭云：衹是作人，行径幽妙。
《唐诗解》：此堪号「结庐在人境」竞爽。
《唐诗选脉会通评林》：周弼为一意体，以纵横放肆，外如不整，中实应节也。何新之为高古体。僧慧洪曰：不直言其闲逸，而意中见其闲逸，谓之遗意句法。玩「偶然」二字，得趣幽深。陆钿曰：律合古，意趣非言尽。盖有一種悠然会心处，所见无非道也。
《唐诗评选》：清靡为时调之冠，亦令人欲割爱而不能。
《唐律消夏录》：「行」、「坐」、「谈」、「笑」，句句不说在别业，却句句是别业。「好道」两字，先生既云「空自知」矣，予又安能强下注脚？予友继庄先生曰：「此诗若衹作文字读，辜负先生慈悲不少。然文字三昧，必须于此等诗领会得，方有悟门。」「还期」一字，与「别业」略一照应。
《此木轩论诗汇编》：观其意若不欲为诗者，其诗之绝境乎？「胜事空自知」，正不容他人知。诗有两字诀，曰「无心」。
《古唐诗合解》：此诗不必粘题，亦不必分解，清微之至。
《唐诗成法》：一家别业之由。二别业。三四承一二。五六承三四。七八承五六结。无一语说别业，却语语是别业，神妙乃尔。以「中岁」生「晩家」，以「独往」生「自知」，以「行到」应「独往」，以「坐看」应「自知」，以「水穷」、「雲起」应「兴来」、「胜事」，以「林叟」、「谈笑」而用「偶然」字总应上，此律中带古法。
《唐诗意》：此诗言已造道之致，三联亦比体也。
《近体秋阳》：不脱落一切尘凡，便际此境界，未必有此领略。能此领略，道邪非邪？流对天然，占断终古。八句衹如一句，近体中纤纤出尘，夷犹入道，未有过于此作者。孟浩然雅以泉石自骄，却无此等一作，以虽立品高清，而天怀不如右丞之夷旷也。然而气格严举，孟又当过之矣。
《唐诗从绳》：此全篇直叙格。五六句法径直。此種句法不假造作，以浑成雅健为贵。通首言中岁虽参究此事，不免茫无着落，至晩年方知有安身立命之处。得此把柄，则行止洒落，冷暖自知，水穷雲起，尽是禅機，林叟闲淡，无非妙谛矣。以人我相忘作结，有悠悠自得之意。
《茧斋诗谈》：一气贯注中不动声色，所向惬然，最是难事。古秀天然，杜不能尔。
《唐诗别裁》：行所无事，一片化機。末语「无还期」，谓不定还期也。
《网师园唐诗笺》：一往清气（「兴来」四句下）。
《历代诗评注读本》：第三句至第八句，一气相生，不分转合，而转合自分，自是化工之笔。
《瀛奎律髓汇评》：冯钝吟：第二联奇句惊人。查初白：五六自然，有无穷景味。纪晓岚：此诗之妙，由绚烂之极归于平淡，然不可以躐等求也。学盛唐者，当以此種为归墟，不得以此種为初步。又云：此種皆熔炼之至，渣滓俱融，涵养之熟，矜躁尽化，而後天機所到，自在流出，非可以摹拟而得者。无其熔炼涵养之功，而以貌袭之，即为窠臼之陈言，敷衍之空调。矫语盛唐者，多犯是病。此亦如禅家者流，有真空、顽空之别，论诗者不可不辨。', 'center', 1363203492, '57b8e4738ac2470062defa4a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10281, '相思', NULL, 1947, 394, 2, 3, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/56154/5244401.htm', '', '红豆生南国，春来发几枝？
愿君多采撷，此物最相思。', '《相思》是唐代诗人王维的作品，是一首借咏物而寄相思的诗作。此诗写相思之情，却全篇不离红豆，正用其相思子之名以关合相思之情。全诗极为明快，却又委婉含蓄，语浅而情深，相传当时即为人谱曲传唱，流行江南。', '相思：题一作“相思子”，又作“江上赠李龟年”。
红豆：又名相思子，一种生在江南地区的植物，结出的籽像豌豆而稍扁，呈鲜红色。
“春来”句：一作“秋来发故枝”。
“愿君”句：一作“劝君休采撷”。采撷（xié）：采摘。
相思：想念。', '红豆树生长在南方，春天到了它将生出多少新枝呢？希望你多采摘一些红豆，它最能够引起人们的思念之情。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9298911759740c9b1a14", "shortContent": "唐代绝句名篇经乐工谱曲而广为流传者为数甚多。王维《相思》就是梨园弟子爱唱的歌词之一。据说天宝之乱后，著名歌者李龟年流落江南，经常为人演唱它，听者无不动容。\n红豆产于南方，结实鲜红浑圆，晶莹如珊瑚，南方人常用以镶嵌饰物。传说古代有一位女子，因丈夫死在边地，哭于树下而死，化为红豆，于是人们又称呼它为“相思子”。唐诗中常用它来关合相思之情。而“相思”不限于男女情爱范围，朋友之间也有相思的，如旧题《李少卿...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc4092b", "shortContent": "唐代绝句名篇经乐工谱曲而广为流传者为数甚多。王维《相思》就是梨园弟子爱唱的歌词之一。据说天宝之乱后，著名歌者李龟年流落江南，经常为人演唱它，听者无不动容。\n\n红豆产于南方，结实鲜红浑圆，晶莹如珊瑚，南方人常用以镶嵌饰物。传说古代有一位女子，因丈夫死在边地，哭于树下而死，化为红豆，于是人们又称呼它为“相思子”。唐诗中常用它来关合相思之情。而“相思”不限于男女情爱范围，朋友之间也有相思的，如旧题《李少...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f09366", "shortContent": "这是王维青年时期的咏物寄相思的诗作，又名为《江上赠李龟年》，可见为怀念友人之作。\n\n本诗中的第一、二句因物起兴，诗人在外散步，偶然看见结在枝上的红豆，心中日夜思念的人儿倏然出现，情思油然而生。“红豆”的鲜艳与“南国”大地的葱绿结合，脑海里展现出春回大地的画面，在色彩的对照中、鲜明的画面感里，突出了“红豆”这个意象，从而暗示着对身处南国朋友的思念之情。“南国”即是红豆产地，又是好友所在之地。而“春来...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270437ccdb86c49f29220", "shortContent": "本诗又名为《江上赠李龟年》，可见为怀念友人之作。据《云溪友议》载：安史乱时，唐宫乐师李龟年流落江南。一次于湘中采访使筵上唱这首诗，满座遥望玄宗所在的蜀中，潸然泪下。可见此诗在当时传诵的情况。这首诗，一直传诵到今天。真挚的相思之情由外在具体的景物生动展现，听者怎能不为之动容。随着《唐诗三百首》流布的广远，影响之深刻，这首诗一直传诵至今，几近家喻户晓。\n\n这是王维青年时期的咏物寄相思的诗作，亦是眷怀友...", "authors": ["林錦萍"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127077f2af4e09d55b6795", "shortContent": "本诗又名为《江上赠李龟年》，可见为怀念友人之作。据《云溪友议》载：安史乱时，唐宫乐师李龟年流落江南。一次于湘中采访使筵上唱这首诗，满座遥望玄宗所在的蜀中，潸然泪下。可见此诗在唐代当时传诵的情况。这首诗，一直传诵到今天。真挚的相思之情由外在具体的景物生动展现，听者怎能不为之动容。随着《唐诗三百首》流布的广远，影响之深刻，这首诗一直传诵至今，几近家喻户晓。\n\n这是王维青年时期的咏物寄相思的诗作，亦是眷...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "64647835b6a81d0c53f2505d", "shortContent": "唐代绝句名篇经乐工谱曲而广为流传者为数甚多。王维《相思》就是梨园弟子爱唱的歌词之一。据说天宝之乱后，著名歌者李龟年流落江南，经常为人演唱它，听者无不动容。\n\n红豆产于南方，结实鲜红浑圆，晶莹如珊瑚，南方人常用以镶嵌饰物。传说古代有一位女子，因丈夫死在边地，哭于树下而死，化为红豆，于是人们又称呼它为“相思子”。唐诗中常用它来关合相思之情。而“相思”不限于男女情爱范围，朋友之间也有相思的，如旧题《李少...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '《读雪山房唐诗序例》：王维“红豆生南国”、王之涣“杨柳东门树”、李白“天下伤心处”，皆直举胸臆，不假雕锼，袓帐离筵，听之惘惘，二十字移情固至此哉！
《唐诗评注读本》：睹物思人，恒情所有，况红豆本名相思，“愿君多采撷”者，即谆嘱无忘故人之意。
《诗境浅说续编》：红豆号相思子，故愿君采撷，以增其别后感情，犹郭元振诗，以同心花见殷勤之意。
《唐人绝句精华》：此以珍惜相思之情，托之名相思子之红豆也。', 'center', 1363203531, '57b8dcfe128fe10054c8d401', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10282, '鸟鸣涧', NULL, 1981, 394, 2, 12, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/154749.htm', '', '人闲桂花落，夜静春山空。
月出惊山鸟，时鸣春涧中。', '该诗是王维题友人皇甫岳所居的云溪别墅所写的组诗《皇甫岳云溪杂题五首》之首。五首诗每一首写一处风景，接近于风景写生，而不同于一般的写意画，或许是一处景点。《鸟鸣涧》侧重于表现夜间春山的宁静幽美。
首句“人闲桂花落，夜静春山空”，便以声写景，巧妙地采用了通感的手法，将“花落”这一动态情景与“人闲”结合起来。花开花落，都属于天籁之音，唯有心真正闲下来，放下对世俗杂念的挚着迷恋，才能将个人的精神提升到一个“空”的境界。当时的背景是“深夜”，诗人显然无法看到桂花飘落的景致，但因为“夜静”，更因为观风景的人“心静”，所以他还是感受到了盛开的桂花从枝头脱落、飘下、着地的过程。而我们也似乎进入了“香林花雨”的胜景。此处的“春山”还给我们留下了想象的空白，因是“春山”，可以想见白天的喧闹的画面：春和日丽、鸟语花香、欢声笑语。而此时，夜深人静，游人离去，白天的喧闹消失殆尽，山林也空闲了下来，其实“空”的还有诗人作为禅者的心境。唯其心境洒脱，才能捕捉到别人无法感受的情景。', '鸟鸣涧：鸟儿在山涧中鸣叫。
人闲：指没有人事活动相扰。闲：安静、悠闲，含有人声寂静的意思。桂花：此指木樨，有春花、秋花等不同品种，这里写的是春天开花的一种。
春山：春日的山。亦指春日山中。空：空寂、空空荡荡。空虚。这时形容山中寂静，无声，好像空无所有。
月出：月亮升起。惊：惊动，扰乱。山鸟：山中的鸟。
时鸣：偶尔（时而）啼叫。时：时而，偶尔。', '很少有人活动只有桂花无声地飘落，夜里一片静谧春日的山谷寂寂空空。
明月升起光辉照耀惊动了山中栖鸟，不时地高飞鸣叫在这春天的溪涧中。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9298c6e67846a920e9bc", "shortContent": "关于这首诗中的桂花，颇有些分歧意见。一种解释是桂花有春花、秋花、四季花等不同种类，此处所写的当是春日开花的一种。另一种意见认为文艺创作不一定要照搬生活，传说王维画的《袁安卧雪图》，在雪中还有碧绿的芭蕉，现实生活中不可能同时出现的事物，在文艺创作中是允许的。不过，这首诗是王维题友人所居的《皇甫岳云溪杂题五首》之一。五首诗每一首写一处风景，接近于风景写生，而不同于一般的写意画，因此，以解释为山中此时实...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc40929", "shortContent": "关于这首诗中的桂花，颇有些分歧意见。一种解释是桂花有春花、秋花、四季花等不同种类，此处所写的当是春日开花的一种。另一种意见认为文艺创作不一定要照搬生活，传说王维画的《袁安卧雪图》，在雪中还有碧绿的芭蕉，现实生活中不可能同时出现的事物，在文艺创作中是允许的。不过，这首诗是王维题友人所居的《皇甫岳云溪杂题五首》之一。五首诗每一首写一处风景，接近于风景写生，而不同于一般的写意画，因此，以解释为山中此时实...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646477f97da2f75ac7e6d9a4", "shortContent": "关于这首诗中的桂花，颇有些分歧意见。一种解释是桂花有春花、秋花、四季花等不同种类，此处所写的当是春日开花的一种。另一种意见认为文艺创作不一定要照搬生活，传说王维画的《袁安卧雪图》，在雪中还有碧绿的芭蕉，现实生活中不可能同时出现的事物，在文艺创作中是允许的。不过，这首诗是王维题友人所居的《皇甫岳云溪杂题五首》之一。五首诗每一首写一处风景，接近于风景写生，而不同于一般的写意画，因此，以解释为山中此时实...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}]', '刘辰翁《王孟诗评》：皆非着意。顾云：所谓情真者。又云：何限清逸。
高棅《批点唐诗正声》：闭关时有此佳趣，亦不寂寂。
朱之荆《增订唐诗摘抄》：鸟惊月出，甚言山中之空。
徐增《而庵说唐诗》：“夜静春山空”，右丞精于禅理，其诗皆合圣教，有此五个字，可不必更读十二部经矣。“时鸣春涧中”，夫鸟与涧同在春山之中，月既惊鸟，鸟亦惊涧，鸟鸣在树，声却在涧，纯是化工，非人为可及也。
吴煊、胡棠《唐贤三昧集笺注》：神清。顾云：如此好景，安得不歆动好情。
黄叔灿《唐诗笺注》：闲事闲情，妙以闲人领此闲趣。
沈德潜《唐诗别裁》：诸咏声息臭味，迥出常格之外，任后人摹仿不到，其故难知。
李锳《诗法易简录》：鸟鸣，动机也；涧，狭境也。而先着“夜静春山空”五字于其前，然后点出鸟鸣涧来，便觉有一种空旷寂静景象，因鸟鸣而愈显者，流露于笔墨之外。一片化机，非复人力可到。
宋顾乐《唐人万首绝句选评》：下二句只是写足“空”字意。
胡应麟《诗薮》：太白五言自是天仙口语，右丞却入禅宗，如“人闲桂花落……”读之身世两忘，万念皆寂。
俞陛云《诗境浅说续编》：昔人谓“鸟鸣山更幽”句，静中之动，弥见其静，此诗亦然。', 'center', 1363203594, '57b90137a633bd00665d510f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (11726, '沁园春 · 赴密州，早行，马上寄子由', NULL, 51, 3406, 2, 1, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/14463402.htm', '', '孤馆灯青，野店鸡号，旅枕梦残。渐月华收练，晨霜耿耿；云山摛锦，朝露漙漙。世路无穷，劳生有限，似此区区长鲜欢。微吟罢，凭征鞍无语，往事千端。
当时共客长安，似二陆初来俱少年。有笔头千字，胸中万卷；致君尧舜，此事何难。用舍由时，行藏在我，袖手何妨闲处看。身长健，但优游卒岁，且斗尊前。', '此词作于宋神宗熙宁七年（西元一〇七四年）七月，苏东坡由杭州移守密州（州治今山东诸城）的早行途中寄给其弟苏颍滨的作品。词中由景入情，由今入昔，直抒胸臆，表达了作者人生遭遇的不幸和壮志难酬的苦闷。', '沁园春：词牌名。北宋新声，东坡词为始词，题为《赴密州早行马上怀子由》。宋人吴虑臣《能改斋漫录·卷十六·〈乐府·沁水公主园〉》：「今世乐府传《沁园春》词。案《後汉书》：『窦宪女弟立为皇后，宪恃宫掖声势，遂以贱直请夺沁水公主园。』然则沁水园者，公主之园也。故唐人类用之。崔湜《长宁公主东庄侍宴》诗云：『沁园东郭外，襄驾一游盘。』李适《长宁公主东庄侍宴》诗云：『歌舞平阳地，园亭沁水林。』李义府《长宁公主东庄》诗云：『平阳馆外有仙家，沁水园中好物华。』汉代沁水园早已无存，但北宋真宗时驸马都尉李遵勖于大中祥符间尚万寿长公主。据宋僧释文莹《湘山野录·卷下》，记李遵勖府第「沁园东北滨于池」，则此北宋初年之沁园。《宋史·卷四百六十四·〈外戚列传·李遵勖传〉》，记李氏「所居地园池冠京城。嗜奇石，募人载送，有自千里至者。构堂引水，环以佳木，延一时名士大夫与宴乐。」故调名源于东汉窦宪仗势夺取沁水公主园林之典故，後人作诗以咏其事而得名。张东泽词结句有「号我东仙」句，名《东仙》。李梅亭词名《寿星明》。秦少游减字词，名《洞庭春色》。又名《寿星明》、《洞庭春色》等。明末清初·万红友《词律》云：「《沁园春》是古调，作者极盛，其名最显。」此调格局开张，宜抒壮阔豪迈情感。苏辛一派最喜用之。平韵，一百一十四字，前阕四平韵，後阕五平韵，亦有于过阕处增一暗韵者。《词律·卷十九》还录另一体，即一百一十五字者。另有《花发沁园春》与此调无涉。曲牌亦有《沁园春》，大致与词牌相同或有变化。曲牌是由词牌演化而来，其来历亦相同。
「赴密州，早行，马上寄子由」：傅注本残阙词调、词序及正文「孤馆」至「俱少年」十五句凡七十字，今据元延祐本补录。吴讷钞本、《二妙集》本、茅维《苏集》本、毛本无题。
子由：龙榆生笺引《宋史·卷三百三十九·苏辙传》：「苏辙，字子由，年十九，与兄轼同登进士科，又同策制举。……（熙宁五年），授齐州掌书记。又三年，改著作佐郎。复从方平签书南京判官。居二年，坐兄轼以诗得罪，谪监筠州盐酒税，五年不得调。移知绩溪县。……崇宁中，蔡京当国，又降朝请大夫，罢祠，居许州，再复太中大夫致仕。筑室于许，号「颍滨遗老」，自作传万馀言，不复与人相见。终日默坐，如是者几十年。政和二年，卒，年七十四。追复端明殿学士。淳熙中，谥文定。辙性沉静简洁，为文汪洋澹泊，似其为人，不愿人知之，而秀杰之气终不可掩，其高处殆与兄轼相迫。所著《〈诗〉传》、《〈春秋〉传》、《古史》、《〈老子〉解》、《栾城文集》并行于世。」
野店鸡号：龙榆生笺引唐·温飞卿《商山早行》诗：「鸡声茅店月，人迹板桥霜。」
耿耿：龙榆生笺：「小明也。谢玄晖《暂使下都夜发新林至京邑赠西府同僚》诗：『秋河曙耿耿。』」
漙漙（tuántuán）：龙榆生笺：「露多貌。《诗经·郑风·野有蔓草》：『野有蔓草，零露漙兮。』」元延祐本作「团团」，兹从吴讷钞本、茅维《苏集》本、毛本。
「世路无穷，劳生有限」句：龙榆生笺引唐·杜少陵《绝句漫兴九首·其四》诗：「莫思身外无穷事，且尽生前有限杯。」
二陆：傅子立注：「……六，与兄齐名，号『二陆』」刘尚荣按：「此条傅注只残存如上九字，文义不明。疑傅氏当引《晋书·卷五十四·陆机陆云传》以释『二陆』。《晋书》云：陆机字士衡，吴郡人也。少有异才，文章冠世。云字士龙，六岁能属文。少与兄机齐名，虽文章不及机，而持论过之，号曰『二陆』。」龙榆生笺引《晋书·卷五十四·陆机陆云传》：「陆机，字士衡，吴郡人也。祖逊，吴丞相。父抗，吴大司马。机身长七尺，其声如钟。少有异才，文章冠世，伏膺儒术，非礼不动。抗卒，领父兵为牙门将。年二十而吴灭，退居旧里，闭门勤学，积有十年。以孙氏在吴，而祖父世为将相，有大勋于江表，深慨孙皓举而弃之，乃论权所以得，皓所以亡，又欲述其祖父功业，遂作《辩亡论》二篇。……至太康末，与弟云俱入洛，造太常张华。华素重其名，如旧相识，曰：『伐吴之役，利获二俊。』……云字士龙，六岁能属文，性清正，有才理。少与兄机齐名，虽文章不及机，而持论过之，号曰『二陆』。幼时吴尚书广陵闵鸿见而奇之，曰：『此儿若非龙驹，当是凤雏。』後举云贤良，时年十六。吴平，入洛。机初诣张华，华问云何在。机曰：『云有笑疾，未敢自见。』俄而云至。华为人多姿制，又好帛绳缠须。云见而大笑，不能自已。」
「笔头千字，胸中万卷」句：傅子立注：「晋傅毅下笔不能休。杜少陵诗：『读书破万卷，下笔如有神。』」刘尚荣按：「傅毅字武仲，见《後汉书·卷八十上·〈文苑列传·傅毅传〉》。傅注误标朝代。三国·魏文帝《典论·论文》：『夫文人相轻，自古而然。傅毅之于班固，伯仲之间耳，而固小之，与弟超书曰︰「武仲以能属文，为兰台令史，下笔不能自休。」』杜句出《奉赠韦左丞丈二十二韵》诗。」
致君尧舜：傅子立注：「孟子曰：『使是君为尧舜之君。』杜诗：『致君尧舜上。』」刘尚荣按：「《孟子·万章上》：『伊尹曰：「吾岂若使是君为尧舜之君哉？」』傅注摘引原文失当，遂有断章取义之嫌。杜句出《奉赠韦左丞丈二十二韵》诗。」
「用舍由时，行藏在我」句：傅子立注引《论语·述而》：「用之则行，舍之则藏，惟我与尔有是夫。」用舍，吴讷钞本、茅维《苏集》本、毛本作「用舍」，舍，古字也。
「优游卒岁，且斗尊前」句：傅子立注：「《家语》：『优哉游哉，聊以卒岁。』杜牧之诗：『且斗尊前见在身。』」刘尚荣笺：「见《孔子家语·卷五》，此係逸《诗》，最早见于《左传·襄公二十一年》所引。杜诗出唐·牛思黯《席上赠刘梦得》诗。」', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b05914587d02f46624", "shortContent": "这首词一本有副题《赴密州早行马上寄子由》，作于神宗熙宁七年（1074）十月由海州出发赴密州（今山东诸城）途中，时苏轼三十九岁，由杭州通判调知密州，其弟苏辙时在齐州（今山东济南）。\n这首词的突出特点是以议论入词，直抒胸臆，表现政治怀抱。词作一开头，作者便以“孤馆灯青，野店鸡号，旅枕梦残”以及“月华收练，晨霜耿耿；云山摛锦，朝露漙漙”数句，绘声绘色地画出了一幅旅途早行图。早行中，眼前月光、山色、晨霜、...", "authors": ["夏承焘", "施议对"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b634a8757d5a0eca8e", "shortContent": "这首词一本有副题《赴密州早行马上寄子由》，作于神宗熙宁七年（1074）十月由海州出发赴密州（今山东诸城）途中，时苏轼三十九岁，由杭州通判调知密州，其弟苏辙时在齐州（今山东济南）。\n这首词的突出特点是以议论入词，直抒胸臆，表现政治怀抱。词作一开头，作者便以“孤馆灯青，野店鸡号，旅枕梦残”以及“月华收练，晨霜耿耿；云山摛锦，朝露漙漙”数句，绘声绘色地画出了一幅旅途早行图。早行中，眼前月光、山色、晨霜、...", "authors": ["夏承焘", "施议对"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e79f2af4e09d55b651c", "shortContent": "傅藻《东坡纪年录》：“熙宁七年甲寅（1074）十月赴密州，早行马上作《沁园春》。”王文诰《苏诗总案》卷一二：“公时由海州赴密，不复绕道至齐一视子由，故其词如此耳。”薛本、邹王本因之。孔《谱》编熙宁七年十一月，作于自杭州北上赴密州途中，时苏辙授齐州（今山东济南）书记。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "64682d0130675327e197461d", "shortContent": "这首词一本有副题《赴密州早行马上寄子由》，作于神宗熙宁七年（1074）十月由海州出发赴密州（今山东诸城）途中，时苏轼三十九岁，由杭州通判调知密州，其弟苏辙时在齐州（今山东济南）。\n\n这首词的突出特点是以议论入词，直抒胸臆，表现政治怀抱。词作一开头，作者便以“孤馆灯青，野店鸡号，旅枕梦残”以及“月华收练，晨霜耿耿；云山摛锦，朝露[插图][插图]”数句，绘声绘色地画出了一幅旅途早行图。早行中，眼前月光...", "authors": ["夏承焘", "施议对"], "pressName": "上海辞书出版社"}]', '', 'indent', 1472523692, '57c48cc20a2b58006c021257', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10283, '山居秋暝', NULL, 1975, 394, 4, 10, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/154755.htm', '', '空山新雨后，天气晚来秋。
明月松间照，清泉石上流。
竹喧归浣女，莲动下渔舟。
随意春芳歇，王孙自可留。', '此诗描绘了秋雨初晴后傍晚时分山村的旖旎风光和山居村民的淳朴风尚，表现了诗人寄情山水田园并对隐居生活怡然自得的满足心情，以自然美来表现人格美和社会美。全诗将空山雨后的秋凉，松间明月的光照，石上清泉的声音以及浣女归来竹林中的喧笑声，渔船穿过荷花的动态，和谐完美地融合在一起，给人一种丰富新鲜的感受。它像一幅清新秀丽的山水画，又像一支恬静优美的抒情乐曲，体现了王维诗中有画的创作特点。', '暝（míng）：日落，天色将晚。
空山：空旷，空寂的山野。
新：刚刚。
清泉石上流：写的正是雨后的景色。
竹喧：竹林中笑语喧哗。喧：喧哗，这里指竹叶发出沙沙声响。
浣（huàn）女：洗衣服的姑娘。浣：洗涤衣物。
随意：任凭。
春芳：春天的花草。歇：消散，消失。
王孙：原指贵族子弟，后来也泛指隐居的人。
留：居。
「王孙自可留」句：反用淮南小山《招隐士》：「王孙兮归来，山中兮不可久留」的意思，王孙实亦自指。反映出无可无不可的襟怀。', '空旷的群山沐浴了一场新雨，夜晚降临使人感到已是初秋。
皎皎明月从松隙间洒下清光，清清泉水在山石上淙淙淌流。
竹林喧响知是洗衣姑娘归来，莲叶轻摇想是上游荡下轻舟。
春日的芳菲不妨任随它消歇，秋天的山中王孙自可以久留。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9296c6e67846a920e9ae", "shortContent": "这首山水名篇，于诗情画意之中寄托着诗人高洁的情怀和对理想境界的追求。\n“空山新雨后，天气晚来秋。”诗中明明写有浣女渔舟，诗人怎下笔说是“空山”呢？原来山中树木繁茂，掩盖了人们活动的痕迹，正所谓“空山不见人，但闻人语响”（《鹿柴》）啊！又由于这里人迹罕到，“峡里谁知有人事，世中遥望空云山”（《桃源行》），一般人自然不知山中有人了。“空山”二字点出此处有如世外桃源。山雨初霁，万物为之一新，又是初秋的傍...", "authors": ["傅如一"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc40920", "shortContent": "这首山水名篇，于诗情画意之中寄托着诗人高洁的情怀和对理想境界的追求。\n\n“空山新雨后，天气晚来秋。”诗中明明写有浣女渔舟，诗人怎下笔说是“空山”呢？原来山中树木繁茂，掩盖了人们活动的痕迹，正所谓“空山不见人，但闻人语响”（《鹿柴》）啊！又由于这里人迹罕到，“峡里谁知有人事，世中遥望空云山”（《桃源行》），一般人自然不知山中有人了。“空山”二字点出此处有如世外桃源。山雨初霁，万物为之一新，又是初秋的...", "authors": ["傅如一"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e020a2", "shortContent": "明月将清辉洒满松林，清泉在石头上潺潺流过。不惟如此，山雨初霁，洗去了如盖在青松身上的尘埃，让青松的身影更加伟岸挺拔，在月色下焕发出勃勃生机。微雨也让清泉更加清冽，它欢快地在山林间奔走，仿佛一条洁白无瑕的白练在山间萦绕。这就是诗人笔下的“山居秋暝图”，“诗中有画”的评语用在这里再恰当不过了。\n\n诗人似乎是独自迈步在雨后的山林中，这一刻，一切都是静谧的、美好的。欣赏着青松间透下的月色，聆听着泉水自在的...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270437ccdb86c49f2921d", "shortContent": "明月将清辉洒满松林，清泉在石头上潺潺流过，不唯如此，山雨初霁，洗去了如盖青松身上的尘埃，让青松的身影更加伟岸挺拔，在月色下焕发出勃勃生机。微雨也让清泉更加清冽，它欢快地在山林间奔走，仿佛一条洁白无瑕的白练在山间萦绕。这就是诗人笔下的“山居秋暝图”，“诗中有画”的评语用在这里再恰当不过了。\n\n诗人似乎是独自迈步在雨后的山林中，这一刻，一切都是静谧的、美好的。欣赏着青松间透下的月色，聆听着泉水自在的叮...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127077f2af4e09d55b6792", "shortContent": "明月将清辉洒满松林，清泉在石头上潺潺流过，不唯如此，山雨初霁，洗去了青松身上的尘埃，让青松的身影更加伟岸挺拔，在月色下焕发出勃勃生机。微雨也让清泉更加清冽，它欢快地在山林间奔走，仿佛一条洁白无瑕的白练在山间萦绕。这就是诗人笔下的“山居秋暝图”，“诗中有画”的评语用在这里再恰当不过了。\n\n诗人似乎是独自迈步在雨后的山林中，这一刻，一切都是静谧的、美好的。欣赏着青松间透下的月色，聆听着泉水自在的叮咚声...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646455ee45e4710056c24530", "shortContent": "这首山水名篇，于诗情画意之中寄托着诗人高洁的情怀和对理想境界的追求。\n\n“空山新雨后，天气晚来秋。”诗中明明写有浣女渔舟，诗人怎下笔说是“空山”呢？原来山中树木繁茂，掩盖了人们活动的痕迹，正所谓“空山不见人，但闻人语响”（《鹿柴》）啊！又由于这里人迹罕至，“峡里谁知有人事，世中遥望空云山”（《桃源行》），一般人自然不知山中有人了。“空山”二字点出此处有如世外桃源。山雨初霁，万物为之一新，又是初秋的...", "authors": ["傅如一"], "pressName": "上海辞书出版社"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646461f730675327e1878143", "shortContent": "这首山水名篇，于诗情画意之中寄托着诗人高洁的情怀和对理想境界的追求。\n\n“空山新雨后，天气晚来秋。”诗中明明写有浣女渔舟，诗人怎下笔说是“空山”呢？原来山中树木繁茂，掩盖了人们活动的痕迹，正所谓“空山不见人，但闻人语响”（《鹿柴》）啊！又由于这里人迹罕至，“峡里谁知有人事，世中遥望空云山”（《桃源行》），一般人自然不知山中有人了。“空山”二字点出此处有如世外桃源。山雨初霁，万物为之一新，又是初秋的...", "authors": ["傅如一"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f2c5e30675327e1b5bb1a", "shortContent": "这首山水名篇，于诗情画意之中寄托着诗人高洁的情怀和对理想境界的追求。\n“空山新雨后，天气晚来秋。”诗中明明写有浣女渔舟，诗人怎下笔说是“空山”呢？原来山中树木繁茂，掩盖了人们活动的痕迹，正所谓“空山不见人，但闻人语响”（《鹿柴》）啊！又由于这里人迹罕到，“峡里谁知有人事，世中遥望空云山”（《桃源行》），一般人自然不知山中有人了。“空山”二字点出此处有如世外桃源。山雨初霁，万物为之一新，又是初秋的傍...", "authors": ["傅如一"], "pressName": "上海辞书出版社"}]', '《王孟诗评》：总无可点，自是好。
《增订评注唐诗正声》：郭云：色韵清绝。
《唐诗归》：谭云：说偈（「明月」二句下）。钟云：「竹暄」、「莲动」细极！静极！
《唐诗解》：雅淡中有致趣。结用楚辞化。
《唐诗选脉会通评林》：周珽曰：月从松间照来，泉由石上流出，极清极淡，所谓洞口胡麻，非复俗指可染者。「浣女」、「渔舟」，秋晚情景；「归」字、「下」字，句眼大妙；而「喧」、「动」二字属之「竹」、「莲」，更奇入神。
《唐诗评选》：凡使皆新，此右丞之似储者。颔联同用，力求切押。
《唐诗矩》：尾联见意格。右丞本从工丽入，晚岁加以平淡，遂到天成，如「明月松间照，清泉石上流」，此非复食烟火人能道者。今人不察其渐老渐熟乃造平淡之故，一落笔便想作此等语，以为吾以王、孟为宗，其流弊可胜道哉！
《历代诗法》：天光工影，无复人工。
《唐贤三昧集笺注》：写景太多，非其至者。顾云：翻案「春草年年绿，王孙归不归」句，谓岂必春草思归。「随意」字着「秋」，「留」字着「山居」，澹适。
《说诗晬语》：中二联不宜纯乎写景。如「明月松间照，清泉石上流。竹喧归浣女，莲动下渔舟」，景象虽工，讵为模楷？
《茧斋诗谈》：「空山」两句，起法高洁，带得通篇俱好。
《闻鹤轩初盛唐近体读本》：陈德公曰：三四极直置，而清寒欲溢，遂使起二句顿增生致，不见为率。五六加婉琢矣。评：三四佳在景耳，景佳则语虽率直，不伤于浅。然人人有此景。人人不能言之，以是知修辞之不可废也。梅坤承曰：语语作致，三四是其自然本色。
《唐贤清雅集》：语气若不经意，看其结体下字何等老洁，切勿顺口读过。
《唐诗合选详解》：王翼云曰：前是写山居秋瞑之景，后入事言情，而不欲仕宦之意可见。
《唐宋诗举要》：随意挥写，得大自在。', 'center', 1413471363, '57b9089bc4c97100558f611f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10284, '使至塞上', NULL, 883, 394, 1, 18, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/154736.htm', '', '单车欲问边，属国过居延。
征蓬出汉塞，归雁入胡天。
大漠孤烟直，长河落日圆。
萧关逢候骑，都护在燕然。', '此诗为唐代诗人王维奉命赴边疆慰问将士途中所作的一首纪行诗，记述出使塞上的旅程以及旅程中所见的塞外风光。首联两句交待此行目的和到达地点，诗缘何而作；颔联两句包含多重意蕴，借蓬草自况，写飘零之感；颈联两句描绘了边陲大漠中壮阔雄奇的景象，境界阔大，气象雄浑；尾联两句虚写战争已取得胜利，流露出对都护的赞叹。此诗既反映了边塞生活，同时也表达了诗人由于被排挤而产生的孤独、寂寞、悲伤之情以及在大漠的雄浑景色中情感得到熏陶、净化、升华后产生的慷慨悲壮之情，显露出一种豁达情怀。', '使至塞上：奉命出使边塞。
使：出使。
单车：一辆车，车辆少，这里形容轻车简从。
问边：到边塞去看望，指慰问守卫边疆的官兵。
属国：有几种解释：一指少数民族附属于汉族朝廷而存其国号者。汉、唐两朝均有一些属国。二指官名，秦汉时有一种官职名为典属国，苏武归汉后即授典属国官职。属国，即典属国的简称，汉代称负责外交事物的官员为典属国，唐人有时以「属国」代称出使边陲的使臣，这里诗人用来指自己使者的身份。
居延：地名，汉代称居延泽，唐代称居延海，在今内蒙古额济纳旗北境。又西汉张掖郡有居延县（参见《汉书·地理志》），故城在今额济纳旗东南。又东汉凉州刺史部有张掖居延属国，辖境在居延泽一带。此句一般注本均言王维路过居延。然而王维此次出使，实际上无需经过居延。因而林庚、冯沅君主编的《中国历代诗歌选》认为此句是写唐王朝「边塞的辽阔，附属国直到居延以外」。
征蓬：随风远飞的枯蓬，此处为诗人自喻。
归雁：雁是候鸟，春天北飞，秋天南行，这里是指大雁北飞。
胡天：胡人的领地。这里是指唐军占领的北方。
大漠：大沙漠，此处大约是指凉州之北的沙漠。
孤烟：赵殿成注有二解：一云古代边防报警时燃狼粪，「其烟直而聚，虽风吹之不散」。二云塞外多旋风，「袅烟沙而直上」。据后人有到甘肃、新疆实地考察者证实，确有旋风如「孤烟直上」。又：孤烟也可能是唐代边防使用的平安火。《通典·卷二一八》云：「及暮，平安火不至。」胡三省注：「《六典》：唐镇戍烽候所至，大率相去三十里，每日初夜，放烟一炬，谓之平安火。」
长河：一说指流经凉州（今甘肃武威）以北沙漠的一条内陆河，这条河在唐代叫马成河，疑即今石羊河；一说指古弱水（今额济纳河），中国第二大内陆河，干流全长八百二十一公里，流经青海省、甘肃省和内蒙古自治区，最后注入苏古淖尔（东居延海）和嘎顺淖尔（西居延海），其上游流淌在甘肃张掖地区，称羌谷水、鄂博河（古作弱水），流到酒泉地区就改称弱水，进入阿拉善盟则称额济纳河。
萧关：古关名，又名陇山关，故址在今宁夏固原东南。
候骑：一作「候吏」，负责侦察、通讯的骑兵。王维出使河西并不经过萧关，此处大概是用何逊诗「候骑出萧关，追兵赴马邑」之意，非实写。
都护：唐朝在西北边疆置安西、安北等六大都护府，其长官称都护，每府派大都护一人，副都护二人，负责辖区一切事务。这里指前敌统帅。
燕然：古山名，即今蒙古国杭爱山。这里代指前线。《后汉书·窦宪传》：宪率军大破单于军，「遂登燕然山，去塞三千馀里，刻石勒功，纪汉威德，令班固作铭。」此两句意谓在途中遇到候骑，得知主帅破敌后尚在前线未归。', '乘单车想去慰问边关，路经的属国已过居延。
千里飞蓬也飘出汉塞，北归大雁正翱翔云天。
浩瀚沙漠中孤烟直上，无尽长河上落日浑圆。
到萧关遇到侦候骑士，告诉我都护已在燕然。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92960ce818559d058659", "shortContent": "开元二十五年（737）河西节度副大使崔希逸战胜吐蕃，唐玄宗命王维以监察御史的身份出塞宣慰，察访军情。这实际是将王维排挤出朝廷。这首诗作于赴边途中。\n“单车欲问边”，轻车前往，向哪里去呢？“属国过居延”，居延在今甘肃张掖县西北，远在西北边塞，在这里并非实指，只是用来泛指边疆之地。\n“征蓬出汉塞，归雁入胡天”，诗人以“蓬”、“雁”自比，说自己像随风而去的蓬草一样出临“汉塞”，像振翮北飞的“归雁”一样进...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc40925", "shortContent": "开元二十五年（737）河西节度副大使崔希逸战胜吐蕃，唐玄宗命王维以监察御史的身份出塞宣慰，察访军情。这实际是将王维排挤出朝廷。这首诗作于赴边途中。\n\n“单车欲问边”，轻车前往，向哪里去呢？“属国过居延”，居延在今甘肃张掖西北，远在西北边塞，在这里并非实指，只是用来泛指边疆之地。\n\n“征蓬出汉塞，归雁入胡天”，诗人以“蓬”“雁”自比，说自己像随风而去的蓬草一样出临“汉塞”，像振翮北飞的“归雁”一样进...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270447ccdb86c49f2922b", "shortContent": "现在是开元二十五年（737）的春天，我近来隐约感受到了自己处境的尴尬，似乎朝廷有人排挤我。河西节度副使崔希逸战胜吐蕃，这使我分外激动，但是另一方面我的担忧还是最终发生了，皇上命我以监察御史的身份出塞宣慰，察访军情。名义上是出使边塞，实际上却是我远离朝廷的开始，于是我踏上了漫漫黄沙之途。\n \n在前方等待我的将是怎样的一个情景呢？漫天飞舞的狂沙如同金子般洒落在人烟稀少的土地上。前方的路很遥远，一辆轻车...", "authors": ["黄蓓"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127077f2af4e09d55b679b", "shortContent": "现在是开元二十五年（737）的春天，我近来隐约感受到了自己处境的尴尬，似乎朝廷有人排挤我。河西节度副使崔希逸战胜吐蕃，这使我分外激动，但是另一方面我的担忧最终还是发生了，皇上命我以监察御史的身份出塞宣慰，察访军情。名义上是出使边塞，实际上却是我远离朝廷的开始，于是我踏上了漫漫黄沙之途。\n\n在前方等待我的将是怎样的一个情景呢？漫天飞舞的狂沙如同金子般洒落在人烟稀少的土地上。前方的路很遥远，一辆轻车载...", "authors": ["黄蓓"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "64646beb45e4710056c2b4ec", "shortContent": "开元二十五年(737)河西节度副大使崔希逸战胜吐蕃，唐玄宗命王维以监察御史的身份出塞宣慰，察访军情。这实际是将王维排挤出朝廷。这首诗作于赴边途中。\n\n“单车欲问边”，轻车前往，向哪里去呢？“属国过居延”，居延在今甘肃张掖市西北，远在西北边塞，在这里并非实指，只是用来泛指边疆之地。\n\n“征蓬出汉塞，归雁入胡天”，诗人以“蓬”“雁”自比，说自己像随风而去的蓬草一样出临“汉塞”，像振翮北飞的“归雁”一样...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f4b645e4710056fc08e4", "shortContent": "诗人把笔墨重点用在了他最擅胜场的方面———写景。作者出使，恰在春天。途中见数行归雁北翔，诗人即景设喻，用归雁自比，既叙事，又写景，一笔两到，贴切自然。尤其是“大漠孤烟直，长河落日圆”一联，写进入边塞后所看到的塞外奇特壮丽的风光，画面开阔，意境雄浑，近代王国维称之为“千古壮观”的名句。边疆沙漠，浩瀚无边，所以用了“大漠”的“大”字。边塞荒凉，没有什么奇观异景，烽火台燃起的那一股浓烟就显得格外醒目，因...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "6473286030675327e1c5596a", "shortContent": "开元二十五年（７３７），河西节度副大使崔希逸战胜吐蕃，唐玄宗命王维以监察御史的身份出塞宣慰，察访军情。这实际上是将王维排挤出朝廷。这首诗作于赴边途中。\n“单车欲问边”，轻车前往，向哪里去呢？“属国过居延”，居延在今甘肃张掖县西北，远在西北边塞。\n“征蓬出汉塞，归雁入胡天。”此二句与首句的“单车”相呼应。诗人以“蓬”、“雁”自比，说自己像随风而去的蓬草一样出临“汉塞”，像振翮北飞的“归雁”一样进入“...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}]', '屈复《唐诗成法》：前四写其芜远，故有「过」、「出」、「入」字。五六写其无人，故用「孤烟」、「落日」、「直」、「圆」，又加一倍惊恐，方转出七八，乃为有力。
徐而菴《说唐诗》：「大漠」、「长河」一联，独绝千古。
王阮亭《唐贤三昧集笺江》：「直」、「圆」二字极锤炼，亦极自然。后人全讲炼字之法，非也；不讲炼字之法，亦非也。」
曹雪芹《红楼梦》：「大漠孤烟直，长河落日圆。」想来烟如何直？日自然是圆的。这「直」字似无理，「圆」字似太俗。要说再找两个字换这两个，竟再找不出两个字来。诗的好处，有口里说不出来的意思，想去却是逼真的；又似乎无理的，想去竟是有理有情的。
王观堂《人间词话》：「明月照积雪」、「大江流日夜」、「中天悬明月」、「长河落日圆」，此种境界，可谓千古壮观。求之于词，唯纳兰容若塞上之作，如《长相思》之「夜深千帐灯」，《如梦令》之「万帐穹庐人醉，星影摇摇欲坠」差近之。
赵殿成《〈王右丞集〉笺注》：亲见其景者，始知「直」字之佳。', 'center', 1415639983, '57b9018b128fe10054c99053', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10285, '九月九日忆山东兄弟', NULL, 2226, 394, 2, 10, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/104822.htm', '', '独在异乡为异客，每逢佳节倍思亲。
遥知兄弟登高处，遍插茱萸少一人。', '此诗写出了游子的思乡怀亲之情，诗一开头便紧切题目，写异乡异土生活的孤独凄然，因而时时怀乡思人，遇到佳节良辰，思念倍加。接着诗一跃而写远在家乡的兄弟，按照重阳节的风俗而登高时，也在怀念自己。诗意反复跳跃，含蓄深沉，既朴素自然，又曲折有致。其中“每逢佳节倍思亲”更是千古名句。', '九月九日：即重阳节。古以九为阳数，故曰重阳。忆：想念。山东：王摩詰迁居于蒲县（今山西永济县），在函谷关与华山以东，所以称山东。
异乡：他乡、外乡。为异客：作他乡的客人。
佳节：美好的节日。此处指重阳节。
登高：古有重阳节登高的风俗。
茱萸（zhūyú）：植物名。香气辛烈，可入药。古俗农历九月九日重阳节，佩茱萸能祛邪辟恶。', '独自离家在外地为他乡客人，每逢佳节来临格外思念亲人。
遥想兄弟们今日登高望远时，头上插茱萸可惜只少我一人。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92980ce818559d058667", "shortContent": "王维是一位早熟的作家，少年时期就创作了不少优秀的诗篇。这首诗就是他十七岁时的作品。和他后来那些富于画意、构图设色非常讲究的山水诗不同，这首抒情小诗写得非常朴素。但千百年来，人们在作客他乡的情况下读这首诗，却都强烈地感受到了它的艺术力量。这种艺术力量，首先来自它的朴质、深厚和高度的艺术概括。\n诗因重阳节思念家乡的亲人而作。王维家居蒲州（今山西永济），在华山之东，所以题称“忆山东兄弟”。写这首诗时，他...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc4092e", "shortContent": "王维是一位早熟的作家，少年时期就创作了不少优秀的诗篇。这首诗就是他十七岁时的作品。和他后来那些富于画意、构图设色非常讲究的山水诗不同，这首抒情小诗写得非常朴素。但千百年来，人们在作客他乡的情况下读这首诗，却都强烈地感受到了它的艺术力量。这种艺术力量，首先来自它的朴质、深厚和高度的艺术概括。\n\n诗因重阳节思念家乡的亲人而作。王维家居蒲州（今山西永济），在华山之东，所以题称“忆山东兄弟”。写这首诗时，...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f459761253910e903af", "shortContent": "说到王维的诗作，我们印象是诗中有画、诗中有乐、诗中有禅。但这首作于诗人十七岁时的作品，却不是以色彩、构图、声响或禅意取胜，而是以朴质与深厚见长。一如诗人的年龄所传达的讯息：纯真而质朴；一如诗人的学识所折射的光芒：深刻而浑厚。\n\n《易经》中，“六”为阴数，“九”为阳数，九月九日，日月并阳，两九相重，故名重阳，亦称重九。重阳佳节，倍感思亲，因有此作。\n王维时在长安、洛阳之间奔波以谋取功名，故乡蒲州（今...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312703bf2af4e09d55b6738", "shortContent": "说到王维的诗作，我们印象是诗中有画、诗中有乐、诗中有禅。但这首作于诗人十七岁时的作品，却不是以色彩、构图、声响或禅意取胜，而是以朴质与深厚见长。一如诗人的年龄所传达的讯息：纯真而质朴；一如诗人的学识所折射的光芒：深刻而浑厚。\n\n《易经》中，“六”为阴数，“九”为阳数，九月九日，日月并阳，两九相重，故名重阳，亦称重九。重阳佳节，倍感思亲，因有此作。\n\n年轻的士子独自游历在外，漂泊无依，孤独凄然。正如...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127076f2af4e09d55b6790", "shortContent": "说到王维的诗作，我们的印象是诗中有画、诗中有乐、诗中有禅。但这首作于诗人十七岁时的作品，却不是以色彩、构图、声响或禅意取胜，而是以朴质与深厚见长。一如诗人的年龄所传达的讯息：纯真而质朴；一如诗人的学识所折射的光芒：深刻而浑厚。\n\n《易经》中，“六”为阴数，“九”为阳数，九月九日，日月并阳，两九相重，故名重阳，亦称重九。重阳佳节，倍感思亲，因有此作。\n\n年轻的士子独自游历在外，漂泊无依，孤独凄然。正...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "6464788e5fc8182fe99d06ac", "shortContent": "王维是一位早熟的作家，少年时期就创作了不少优秀的诗篇。这首诗就是他十七岁时的作品。和他后来那些富于画意、构图设色非常讲究的山水诗不同，这首抒情小诗写得非常朴素。但千百年来，人们在作客他乡的情况下读这首诗，却都强烈地感受到了它的艺术力量。这种艺术力量，首先来自它的朴质、深厚和高度的艺术概括。\n\n诗因重阳节思念家乡的亲人而作。王维家居蒲州（今山西永济），在华山之东，所以题称“忆山东兄弟”。写这首诗时，...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f0c6a5fc8182fe9ca2ba0", "shortContent": "诗因重阳节思念家乡的亲人而作。王维家居蒲州（今山西永济），在华山之东，所以题称“忆山东兄弟”。写这首诗时，他大概正在长安谋取功名。繁华的帝都对当时热衷仕进的年轻士子虽有很大吸引力，但对一个少年游子来说，毕竟是举目无亲的“异乡”；而且越是繁华热闹，在茫茫人海中的游子就越显得孤孑无亲。第一句用了一个“独”字，两个“异”字，分量下得很足。对亲人的思念，对自己孤孑处境的感受，都凝聚在这个“独”字里面。“异...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '《批点唐音》：真意所发，切实故难。
顾云《王孟诗评》：真意所发，忠厚蔼然。
吴逸一《唐诗正声》：口角边说话，故能真得妙绝，若落冥搜，便不能如此自然。
蒋仲舒《唐诗广选》：在兄弟处想来，便远。
《唐诗直解》：诗不深苦，情自蔼然，叙得真率，不用雕琢。
《唐诗解》：摩诘作此，时年十七，词义之美，虽《涉岵》不能加。史以孝友称维，不虚哉！
《唐诗选脉会通评林》：周敬曰：自有一种至情，言外可想。徐充曰：「倍」字佳。「少一人」正应「独」字。
《唐贤三昧集笺注》：情至意新。《陟岵》之思。此非故学《三百篇》，人人胸中自有《三百篇》也。
《唐诗笺要》：右丞七绝，飘逸处如释仙仗履，古藻处如轩昊衣冠，其所养者深矣。
《唐诗别裁》：即《陟岵》诗意，谁谓唐人不近《三百篇》耶？
《茧斋诗谈》：不说我想他，却说他想我，加一倍凄凉。
《网师园唐诗笺》：至情流露，岂是寻常流连光景者？
《唐诗真趣编》：从对面说来，己之情自已，此避实击虚法。起二语拙，直是童年之作。
《诗式》：三四句与白居易「共看明月应垂泪，一夜乡心五处同」，意境相似。
《碛砂唐诗》：圣叹曾言，唐人作诗每用「遥」字，如「遥知远林际」、「遥知兄弟登高处」，皆用倩女离魂法也，极有远致。
《诗境浅说续编》：杜少陵诗「忆弟看云白日眠」、白乐天诗「一夜乡心五处同」、皆寄怀群季之作，此诗尤万口流传。诗到真切动人处，一字不可移易也。', 'center', 1414922287, '57b95cedc4c9710055925b16', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10286, '汉江临泛', NULL, 387, 394, 4, 3, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/916167.htm', '', '楚塞三湘接，荆门九派通。
江流天地外，山色有无中。
郡邑浮前浦，波澜动远空。
襄阳好风日，留醉与山翁。', '此诗以淡雅的笔墨描绘了汉江周围壮丽的景色，表达了诗人追求美好境界、希望寄情山水的思想感情，也隐含了歌颂了地方行政长官的功绩之意。首联写众水交流，密不间发；颔联开阔空白，疏可走马；颈联由远而近，远近相映，笔墨酣畅；尾联直抒胸臆，可比作画上题字。诗人采取的几乎全是白描的写意手法，从大处着墨，于平凡中见新奇，将登高远眺、极目所见的山川景物写得极为壮阔飞动，奔放雄伟，全诗犹如一巨幅水墨山水，意境开阔，气魄宏大。', '汉江临泛：诗题在元代方回的《瀛奎律髓》中题名为“汉江临眺”，临眺，登高远望。汉江从襄阳城中流过，把襄阳与樊城一分为二（合称“襄樊”），以及襄樊周围大大小小的无数城郭（包括襄阳城门外的许多“瓮城”），一个个都像在眼前的水道两旁漂浮。临汎江上，随着小舟在波澜中摇晃，感觉远处的天空都在摇动，非常恰当地扣题，写出“临泛”的独特观感。假如是“汉江临眺”，就不会有这样的感觉。所以此诗还是应题为《汉江临泛》为是。
汉江：即汉水，流经陕西汉中、安康，湖北十堰、襄阳、荆门、天门、潜江、仙桃、孝感，到汉口流入长江。
楚塞：楚国边境地带，这里指汉水流域，此地古为楚国辖区。三湘：湘水合漓水为漓湘，合蒸水为蒸湘，合潇水为潇湘，总称三湘；一说是湖南的湘潭、湘阴、湘乡合称三湘。古诗文中，三湘一般泛称今洞庭湖南北、湘江一带。
荆门：山名，荆门山，在今湖北宜都县西北的长江南岸，战国时为楚之西塞。
九派：指长江的九条支流，长江至浔阳分为九支。相传大禹治水，开凿江流，使九派相通。这里指江西九江。
郡邑：指汉水两岸的城镇。
浦：水边。
动：震动。
好风日：一作“风日好”，风景天气好。
山翁：一作“山公”，指山简，晋代竹林七贤之一山涛的幼子，西晋将领，镇守襄阳，有政绩，好酒，每饮必醉。《晋书·山简传》说他曾任征南将军，镇守襄阳。当地习氏的园林，风景很好，山简常到习家池上大醉而归。这里借指襄阳地方官。一说是作者以山简自喻。', '楚国边塞连接着三湘之水，荆门山下茫茫九派相汇合。
江水滚滚似奔流天地之外，青山延绵水雾中时时隐现。
波涛汹涌城郭仿佛飘江上，大浪翻滚远空好似在摇晃。
襄阳的风光真是无限美好，愿与山翁留此地长醉不归。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929634a8757d5a0e1c11", "shortContent": "这首《汉江临泛》可谓王维融画法入诗的力作。\n“楚塞三湘接，荆门九派通”，语工形肖，一笔勾勒出汉江雄浑壮阔的景色，作为画幅的背景。泛舟江上，纵目远望，只见莽莽古楚之地和从湖南方面奔涌而来的“三湘”之水相连接，汹涌汉江入荆江而与长江九派汇聚合流。诗虽未点明汉江，但足已使人想象到汉江横卧楚塞而接“三湘”、通“九派”的浩渺水势。诗人将不可目击之景，予以概写总述，收漠漠平野于纸端，纳浩浩江流于画边，为整个画...", "authors": ["徐应佩", "周溶泉"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc40924", "shortContent": "这首《汉江临泛》可谓王维融画法入诗的力作。\n\n“楚塞三湘接，荆门九派通”，语工形肖，一笔勾勒出汉江雄浑壮阔的景色，作为画幅的背景。泛舟江上，纵目远望，只见莽莽古楚之地和从湖南方面奔涌而来的“三湘”之水相连接，汹涌汉江入荆江而与长江九派汇聚合流。诗虽未点明汉江，但足已使人想象到汉江横卧楚塞而接“三湘”、通“九派”的浩渺水势。诗人将不可目击之景，予以概写总述，收漠漠平野于纸端，纳浩浩江流于画边，为整个...", "authors": ["徐应佩", "周溶泉"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e020a8", "shortContent": "这首诗是王维山水诗中的名作。唐玄宗开元二十八年（740），时任殿中侍御史的王维，因公务去南方，途经襄阳。这首诗就是诗人在襄阳城欣赏汉江景色时所作。诗歌又名《汉江临泛》，所谓临泛，意即泛舟汉江。临眺，即临水远望。诗歌围绕这一题目，写了临水远望的自然美景。\n\n“楚塞三湘接，荆门九派通”，“楚塞”，指楚国地界，襄阳古为楚国辖区。“三湘”，具体包括哪三者，说法不一，但在古代诗文中一般泛指湘江流域及洞庭湖地...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646469e97f27182da352d05d", "shortContent": "这首《汉江临泛》可谓王维融画法入诗的力作。\n\n“楚塞三湘接，荆门九派通”，语工形肖，一笔勾勒出汉江雄浑壮阔的景色，作为画幅的背景。泛舟江上，纵目远望，只见莽莽古楚之地和从湖南方面奔涌而来的“三湘”之水相连接，汹涌汉江入荆江而与长江九派汇聚合流。诗虽未点明汉江，但足以使人想象到汉江横卧楚塞而接“三湘”、通“九派”的浩渺水势。诗人将不可目击之景，予以概写总述，收漠漠平野于纸端，纳浩浩江流于画边，为整个...", "authors": ["徐应佩　周溶泉"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "6473282530675327e1c5587e", "shortContent": "这首《汉江临泛》可谓王维融画法入诗的力作。\n“楚塞三湘接，荆门九派通。”语工形肖，一笔勾勒出汉江雄浑壮阔的景色，作为画幅的背景。泛舟江上，纵目远望，只见莽莽古楚之地和从湖南方面奔涌而来的“三湘”之水相连接，汹涌汉江入荆江而与长江九派汇聚合流。诗虽未点明汉江，但足已使人想像到汉江横卧楚塞而接“三湘”、通“九派”的浩渺水势。诗人将不可目击之景，予以概写总述，收漠漠平野于纸端，纳浩浩江流于画边，为整个画...", "authors": ["徐应佩", "周溶泉"], "pressName": "上海辞书出版社"}]', '《王孟诗评》：顾云：此等处本浑成，但难拟作，恐近浅率。
《瀛奎律髓》：右丞此诗，中两联皆言景，而前联尤壮，足敌孟、杜《岳阳》之作。
《增订评注唐诗正声》：郭云：气象涵蓄，浑浑无际，浅率者拟学不得。
《唐诗归》：钟云：真境说不得（“江流”句下）。
《唐诗解》：第四句对巧，五六上句较胜。
《唐诗选脉会通评林》：刘辰翁曰：无意之意。魏庆之曰：三四轻重对法，意高则不觉。吴山民曰：起有注《水经》笔意。
《唐诗意》：胸中有一段浩然广大之致，适于泛江写出，可风亦可雅。
《唐诗成法》：前六雄俊阔大，甚难收拾，却以“好风日”三字结之，笔力千钧。题中“临泛”，不过末句顺带而已，此法亦整嗾鲙《唐贤三昧集笺注》：三四气格雄浑，盛唐本色。五六即第三句之半。
《茧斋诗谈》：“江流天地外，山色有无中”。学其气象之大。
《瀛奎律髓汇评》：冯舒：澄之使清矣，“壮”字不足以尽之。陆贻典：顺题做法，落句推开，查慎行，第一、第三句中两用“江”字。不但此也，“三江”、“九派”、“前浦”、“波澜”，篇中说水处太多，终是诗病。纪昀：三四好，五六撑不起，六句尤少味，复衍三句故也。无名氏：壮句仍冲雅，见右丞本色。
《唐诗近体》：三句雄阔，四句缥渺，此换笔之妙。
《唐宋诗举要》：吴曰：雄伟有气力，学者宜从此等入手。', 'center', 1416995728, '57b8f2c1d342d3005ac6cf67', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10287, '送元二使安西', NULL, 1710, 394, 2, 15, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/257099/5120849.htm', '', '渭城朝雨浥轻尘，客舍青青柳色新。
劝君更尽一杯酒，西出阳关无故人。', '此诗是唐代诗人王维送朋友去西北边疆时所作。此诗前两句写送别的时间、地点、环境气氛。三四句是一个整体，主人的这句似乎脱口而出的劝酒辞就是此刻强烈，深挚的惜别之情的集中表现。这首诗所描写的是一种最有普遍性的离别。它没有特殊的背景，而自有深挚的惜别之情，这就使它适合于绝大多数离筵别席演唱，后来编入乐府，成为最流行，传唱最久的歌曲。', '元二：姓元，排行第二，作者的朋友。使：出使。安西：指唐代安西都护府，在今新疆库车附近。
渭城：秦时咸阳城，汉改渭城，在长安西北，渭水北岸。朝雨：早晨下的雨。浥（yì）：湿。
客舍：旅店。
阳关：在今甘肃省敦煌县西南，是古代通西域的要道。', '清晨刚下阵雨，渭城达到尘土湿润，空气清新，旅舍更加青翠。
朋友啊，再干一杯送别的酒吧，要知道西出阳关之后，就再也难见老朋友了。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9298dbb8b379ee095980", "shortContent": "这是一首送朋友去西北边疆的诗。安西，是唐中央政府为统辖西域地区而设的安西都护府的简称，治所在龟兹城（今新疆库车）。这位姓元的友人是奉朝廷的使命前往安西的。唐代从长安往西去的，多在渭城送别。渭城即秦都咸阳故城，在长安西北，渭水北岸。\n前两句写送别的时间、地点、环境气氛。清晨，渭城客舍，自东向西一直延伸、不见尽头的驿道，客舍周围、驿道两旁的柳树。这一切，都仿佛是极平常的眼前景，读来却风光如画，抒情气氛...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc4092f", "shortContent": "这是一首送朋友去西北边疆的诗。安西，是唐中央政府为统辖西域地区而设的安西都护府的简称，治所在龟兹城（今新疆库车）。这位姓元的友人是奉朝廷的使命前往安西的。唐代从长安往西去的，多在渭城送别。渭城即秦都咸阳故城，在长安西北，渭水北岸。\n\n前两句写送别的时间、地点、环境气氛。清晨，渭城客舍，自东向西一直延伸、不见尽头的驿道，客舍周围、驿道两旁的柳树。这一切，都仿佛是极平常的眼前景，读来却风光如画，抒情气...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4ec26cbf3417f093a2", "shortContent": "《送元二使安西》是王维在京城长安附近的渭城为好朋友元二饯行的诗，由于元二要去的地方在数千里之外的安西，因而这又是一首送客远别的诗。\n\n诗的前两句写景，写了送别的地点、时间和环境气氛。清晨，渭城客舍，自东向西一直延伸、不见尽头的驿道，客舍周围、驿道两旁的柳树。这是一些极平常的眼前景，读来却风光如画，抒情气氛浓郁。因为纯真的友情本身就是自然的、朴素的。早晨下了一阵小雨，刚刚润湿尘土就停了，仿佛特意为远...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646478a2c0471b0062cbd26c", "shortContent": "这是一首送朋友去西北边疆的诗。安西，是唐中央政府为统辖西域地区而设的安西都护府的简称，治所在龟兹城（今新疆库车）。这位姓元的友人是奉朝廷的使命前往安西的。唐代从长安往西去的，多在渭城送别。渭城即秦都咸阳故城，在长安西北，渭水北岸。\n\n前两句写送别的时间、地点、环境气氛。清晨，渭城客舍，自东向西一直延伸、不见尽头的驿道，客舍周围、驿道两旁的柳树。这一切，都仿佛是极平常的眼前景，读来却风光如画，抒情气...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f0c267da2f75ac7139f1e", "shortContent": "绝句在篇幅上受到严格限制。这首诗，对如何设宴饯别，宴席上如何频频举杯、殷勤话别，以及启程时如何依依不舍，登程后如何瞩目遥望，等等，一概舍去，只剪取饯行宴席即将结束时主人的劝酒辞：再干了这一杯吧，出了阳关，可就再也见不到老朋友了。诗人像高明的摄影师，摄下了最富表现力的镜头。宴席已经进行了很长一段时间，酿满别情的酒已经喝过多巡，殷勤告别的话已经重复过多次，朋友上路的时刻终于不能不到来，主客双方的惜别之...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '《王孟诗评》：更万首绝句，亦无复近，古今第一矣。顾云：后人所谓《阳关三叠》，名下不虚。
《笺注唐贤绝句三体诗法》：首句藏行尘，次句藏折柳。两面皆画出，妙不露骨。从休文“莫言一杯酒，明日难重持”变来。
《麓堂诗话》：作诗不可以意徇辞，而须以辞达意。辞能达意，可歌可咏，则可以传。王摩诘“阳关无故人”之句，盛唐以前所未道。此辞一出，一时传诵不足，至为三叠歌之。后之咏别者，千言万语。殆不能出其意之外。必如是，方可谓之达耳。
《批点唐诗正声》：《阳关三叠》，唐人以为送行之曲，虽歌调已亡，而音节自尔悲畅。
《唐诗绝句类选》：唐人别诗，此为绝唱。
《诗薮》：“数声风笛离亭晚，君向潇湘我向秦”、“日暮酒醒人已远，满天风雨下西楼”，岂不一唱三叹，而气韵衰飒殊甚。“渭城朝雨”自是口语，而千载如新。此论盛唐、晚唐三昧。
《唐诗正声》：吴逸一曰：语由信笔，千古擅长，既谢光芒，兼空追琢，太白、少伯，何遽胜之！
《唐诗镜》：语老情深，遂为千古绝调。
《唐诗解》：唐人饯别之诗以亿计，独《阳关》擅名，非为其真切有情乎？凿混沌者皆下风也。
《唐诗选脉会通评林》：谢枋得曰：意味悠长。唐汝洵曰：信手拈出，乃为送别绝唱。作意者正不能佳。蒋一梅曰：片言之悲，令人魂断。
《唐风定》：风韵超凡，声情刺骨，自尔百代如新，更无继者。
《唐诗摘钞》：先点别景，次写别情，唐人绝句多如此，毕竟以此首为第一，惟其气度从容，风味隽永，诸作无出其右故也。失粘须将一二倒过，然毕竟移动不得，由作者一时天机凑泊，宁可失粘而语势不可倒转。此古人神境，未易到也。
《唐音审体》：刘梦得诗云“更与殷勤唱渭城”，白居易诗云“听唱阳关第四声”，皆谓此曲也，相传其调最高，倚歌者笛为之裂。
《此木轩论诗汇编》：古今绝调。“渭城朝雨浥轻尘”下面决不是遇着个高僧，遇着个处士，此钩魂摄魄之说。第三、第四句不可连读。落句冷水一涕，却只是冲口道出，不费寻思。
《唐诗笺要》：不作深语，声情沁骨。
《而庵说唐诗》：人皆知此诗后二句妙，而不知亏煞前二句提顿得好。此诗之妙只是一个真，真则能动人。后维偶于路旁，闻人唱诗，为之落泪。
《唐贤三昧集笺注》：惜别意悠长不露。《阳关三叠》艳称今古，音节最高者。按“三叠”为度曲者叠第三句也。相传倚笛亦为之裂。
《唐诗别裁》：阳关在中国外，安西更在阳关外。言阳关已无故人矣，况安西乎？此意须微参。
《唐人万首绝句选评》：送别诗要情味俱深，意境两尽，如此篇真绝作也。
《瓯北诗话》：人人意中所有，却未有人道过，一经说出，便人人如其意之所欲出，而易于流播，遂足传当时而名后世。如李太白“今人不见古时月，今月曾经照古人”，王摩诘“劝君更尽一杯酒，西出阳关无故人”，至今犹脍炙人口，皆是先得人心之所同然也。
《唐诗真趣编》：只体贴友心，而伤别之情不言自喻。用笔曲折。刘仲肩曰：是故人亲厚话。', 'center', 1413129535, '57b910fac4c97100558faa8c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (45832, '望海潮 · 寄保下胡仲明', NULL, 0, 12, 0, 1, '马需庵', NULL, 11117, '5858e62761ff4b006875bfde', '元', 'ci', '词', 'https://baike.baidu.com/item/%E6%9C%9B%E6%B5%B7%E6%BD%AE%E5%AF%84%E4%BF%9D%E4%B8%8B%E8%83%A1%E4%BB%B2%E6%98%8E/15176046', '', '流年如电，归心似水，求田问舍悠悠。蚁穴蜂衙，燕巢鸠计，元龙久厌拘囚。回首羡沙鸥。待清风北渚，明月南楼。奈世事多艰，此身天地一虚舟。
青衫白发堪羞。岂儒冠误我，命压人头。太学三年，京华十口，算来依旧淹留。别后几经秋。想音容渐老，文采风流。安得浮香亭上，羯鼓醉梁州。', '', '', '', NULL, '', 'indent', 1533833993, '585ceb71570c350069306482', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10289, '过香积寺', NULL, 290, 394, 3, 3, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383294.htm', '', '不知香积寺，数里入云峰。
古木无人径，深山何处钟？
泉声咽危石，日色冷青松。
薄暮空潭曲，安禅制毒龙。', '《过香积寺》是唐代诗人王维的代表作之一。这是一首写游览的诗，主要在于描写山中古寺之幽深静寂。此诗意在写山寺，但并不正面描摹，而侧写周围景物，来烘托映衬山寺之幽胜。最后看到深潭已空，想到佛经中所说的其性暴烈的毒龙已经制服，喻指只有克服邪念妄想，才能悟到禅理的高深，领略宁静之幽趣。全诗不写寺院，而寺院已在其中。诗歌构思奇妙、炼字精巧，其中“泉声咽危石，日色冷青松”，历来被誉为炼字典范。', '过：过访，探望。香积寺：唐代著名寺院，有争议，一说香积寺在长安县（今陕西省西安市）南神禾原上。”故址已废。一说在河南汝州，今风穴寺，唐时称香积寺。
入云峰：登上入云的高峰。
钟：寺庙的钟鸣声。
咽：呜咽。危：高的，陡的。“危石”意为高耸的崖石。
冷青松：为青松所冷。
薄暮：黄昏。曲：水边。“安禅”即安静地打坐，在这里指佛家思想。
安禅：为佛家术语，指身心安然进入清寂宁静的境界，在这里指佛家思想。毒龙：佛家比喻俗人的邪念妄想。见《涅槃经》：“但我住处有一毒龙，想性暴急，恐相危害。”', '不知道香积寺在什么地方，攀登好几里误入云拥群峰。
古木参天却没有人行路径，深山里何处传来古寺鸣钟。
山中泉水撞危石响声幽咽，松林里日光照射也显寒冷。
黄昏时来到空潭隐蔽之地，安然地修禅抑制心中毒龙。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92965e272d4b2254318e", "shortContent": "诗题《过香积寺》的“过”，与孟浩然《过故人庄》的“过”相同，意谓“访问”、“探望”。\n既是去访香积寺，却又从“不知”说起；“不知”而又要去访，见出诗人的洒脱不羁。因为“不知”，诗人便步入茫茫山林中去寻找，行不数里就进入白云缭绕的山峰之下。此句正面写人入云峰，实际映衬香积寺之深藏幽邃。还未到寺，已是如此云封雾罩，香积寺之幽远可想而知矣。\n接着四句，是写诗人在深山密林中的目见和耳闻。先看三、四两句。古...", "authors": ["唐永德"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e020a6", "shortContent": "修身养性的生活是我现在的理想追求。我对长安城的香积寺慕名已久，那是心灵深处的一座家园，那是超脱尘世的一片乐土，我决定去寻找我的家园，我的乐土。\n\n行不数里，便来到云雾缭绕的山峰之下。那不就是我一直在寻找的乐园吗？我被眼前的景象惊呆了：丛林中处处可见参天的古木，阳光偶尔从树叶的缝隙中洒下，这茫茫的绿色之中，杳无人迹。我正陶醉在这静谧的海洋里，这空灵的氛围里，耳边却传来隐隐淡淡的钟声。令我惊奇的是这钟...", "authors": ["黄蓓"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "64645573cd12b001c6e480f9", "shortContent": "诗题《过香积寺》的“过”，与孟浩然《过故人庄》的“过”相同，意谓“访问”“探望”。\n\n既是去访香积寺，却又从“不知”说起；“不知”而又要去访，见出诗人的洒脱不羁。因为“不知”，诗人便步入茫茫山林中去寻找，行不数里就进入白云缭绕的山峰之下。此句正面写人入云峰，实际映衬香积寺之深藏幽邃。还未到寺，已是如此云封雾罩，香积寺之幽远可想而知矣。\n\n接着四句，是写诗人在深山密林中的目见和耳闻。先看三、四两句。...", "authors": ["唐永德"], "pressName": "上海辞书出版社"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "64645fb5c0471b0062cb5cb8", "shortContent": "诗题《过香积寺》的“过”，与孟浩然《过故人庄》的“过”相同，意谓“访问”“探望”。\n\n既是去访香积寺，却又从“不知”说起；“不知”而又要去访，见出诗人的洒脱不羁。因为“不知”，诗人便步入茫茫山林中去寻找，行不数里就进入白云缭绕的山峰之下。此句正面写人入云峰，实际映衬香积寺之深藏幽邃。还未到寺，已是如此云封雾罩，香积寺之幽远可想而知矣。\n\n接着四句，是写诗人在深山密林中的目见和耳闻。先看三、四两句。...", "authors": ["唐永德"], "pressName": "上海辞书出版社"}]', '《唐诗广选》：顾与新曰：幽深本色语，不杂一句，洁净玄微，无声无色。
《唐诗直解》：“古木”二句幽而浑，中晚人有此法，多失于卑。
《唐诗镜》：韵气冷甚。三四偷律，病在不严。
《唐诗解》：起联与“独有宦游人”一法。
《唐诗选脉会通评林》：极状山寺深僻幽静，篇法句法字法入微入妙。“毒龙”。佛喻砍心也，用以收局，不失释氏面目。此与《登辨觉寺》诗，何如狮子捉物，象兔俱用全力耶？汪道昆曰：五六即景衬贴荒凉意，“咽”字、“冷”字工。
《唐诗评选》：三四似流水，一似双立，安句自然，结亦不累。
《唐诗摘钞》：幽处见奇，老中见秀，章法、句法、字法皆极浑浑，五律无上神品。
《唐贤三昧集笺注》：顾云：“不知”字玄妙，模写幽深处。又云：三四甚是浅易，甚是深处，字法。五六即景，衬贴荒深意。
《唐诗别裁》：“咽”与“冷”，见用字之妙。
《唐诗从绳》：此尾联寓意格也。起用“不知”二字，便是往时未到，今日方过，幽赏胜情，得未曾有，俱寓此二字内。中二联写景，分途中，本寺。五六是“危石”边“泉声咽”。“青松”上“日色冷”，成倒装句。通篇从“过”字着画。
《茧斋诗谈》：“不知”两字领起全章脉。“泉声咽危石，日色冷青松”，泉遇石而咽，松向日而冷，意自互用。
《网师园唐诗笺》：炼字幽峭（“深山”句下）。
《闻鹤轩初盛唐近体读本》：评：三四亦是隽逸句法。五六特作生峭，“咽”、“冷”二字，法极欲尖出。骂声写色，已难到地，着“咽”、“冷”字，妙更入神，是《子虚》《上林》赋手。
《唐贤清雅集》：“古木”一联远写，“泉声”一联近写，总从“不知”生出，渐次行来，已至寺矣，故以“安禅”收住。构局炼句与《山居秋暝》略同，超旷稍异，乃相题写景法。
《唐宋诗举要》：吴曰：幽微夐邈，最是王、孟得意神境。
《诗境浅说》：常建《过破山寺》咏寺中静趣，此咏寺外幽景，皆不从本寺落笔，游山寺者，可知所着想矣。', 'center', 1363204366, '57b997707db2a20054f79238', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10290, '辋川闲居赠裴秀才迪', NULL, 323, 394, 3, 2, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383291.htm', '', '寒山转苍翠，秋水日潺湲。
倚杖柴门外，临风听暮蝉。
渡头馀落日，墟里上孤烟。
复值接舆醉，狂歌五柳前。', '此诗是唐代著名诗人王维的一首五言律诗。描绘了幽居山林，超然物外之志趣，因而以接舆比裴迪，以陶潜比自己。风光人物，交替行文，相映成趣，形成物我一体情景交融的艺术意境，抒发了闲居之乐和对友人的真切情谊。
开头二句写景，着意刻画水色山光之可爱，虽深秋，山依然苍翠，水依旧潺流。三、四两句，转而写情。倚杖柴门，临风听蝉，神驰邈远，自由自在。五、六句又间写景致。渡头落日，墟里孤烟，地道山村风物。最后两句再写人情。接舆、五柳、洁身自好，高风脱俗。风光无限，加之人物疏狂，令人情趣陶然。', '辋川：水名，在今陕西省蓝田县南终南山下。山麓有宋之问的别墅，后归王维。王维在那里住了三十多年，直至晚年。裴迪：诗人，王维的好友，与王维唱和较多。
转苍翠：一作“积苍翠”。转：转为，变为。苍翠：青绿色，苍为灰白色，翠为墨绿色。
潺湲（chányuán）：水流声。这里指水流缓慢的样子，当作为“缓慢地流淌”解。
听暮蝉：聆听秋后的蝉儿的鸣叫。暮蝉：秋后的蝉，这里是指蝉的叫声。
渡头：渡口。余：又作“馀”。
墟里：村落。孤烟：直升的炊烟，可以是倚门看到的第一缕村烟。
值：遇到。接舆：陆通先生的字。接舆是春秋时楚国人，好养性，假装疯狂，不出去做官。在这里以接舆比裴迪。
五柳：陶渊明。这里诗人以“五柳先生”自比。这两句诗的意思是说，又碰到狂放的裴迪喝醉了酒，在我面前唱歌。', '寒山转变得格外郁郁苍苍，秋水日日舒缓地流向远方。
我柱杖伫立在茅舍的门外，迎风细听着那暮蝉的吟唱。
渡头那边太阳快要落山了，村子里的炊烟一缕缕飘散。
又碰到裴迪这个接舆酒醉，在恰如陶潜的我面前讴狂。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92955e272d4b2254318b", "shortContent": "《新唐书·王维传》：“别墅在辋川，地奇胜。……与裴迪游其中，赋诗相酬为乐。”这首诗即与裴迪相酬为乐之作。\n这是一首诗、画、音乐完美结合的五律。首联和颈联写景，描绘辋川附近山水田园的深秋暮色；颔联和尾联写人，刻画诗人和裴迪两个隐士的形象。风光人物，交替行文，相映成趣，形成物我一体、情景交融的艺术境界，抒写诗人的闲居之乐和对友人的真切情谊。\n“寒山转苍翠，秋水日潺湲。”首联写山中秋景。时在水落石出的寒...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc4091e", "shortContent": "《新唐书·王维传》：“别墅在辋川，地奇胜。……与裴迪游其中，赋诗相酬为乐。”这首诗即与裴迪相酬为乐之作。\n\n这是一首诗、画、音乐完美结合的五律。首联和颈联写景，描绘辋川附近山水田园的深秋暮色；颔联和尾联写人，刻画诗人和裴迪两个隐士的形象。风光人物，交替行文，相映成趣，形成物我一体、情景交融的艺术境界，抒写诗人的闲居之乐和对友人的真切情谊。\n\n“寒山转苍翠，秋水日潺湲。”首联写山中秋景。时在水落石出...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e020a1", "shortContent": "这是一首表现作者辋川闲居生活情景的诗，为我们展示了一幅秋日暮色图。\n\n“寒山转苍翠，秋水日潺湲。”首联分别从山色、水声两方面描摹辋川秋景。同一座山，在不同季节呈现不同色调，相应的给人的感觉也不同。\n“山寒水瘦”常用来形容秋冬山水。这里在山前着一“寒”字，就显出深秋的季节特点。“转苍翠”表示山色愈来愈深，寒意愈来愈重，这又是就一日之内从朝到暮的变化说的，意思是随着天色向晚，山色也显得更加苍翠了。北方...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270447ccdb86c49f29228", "shortContent": "这是一首表现作者辋川闲居生活情景的诗，为我们展示了一幅秋日暮色图。\n\n“寒山转苍翠，秋水日潺湲。”首联分别从山色、水声两方面描摹辋川秋景。同一座山，在不同季节呈现不同色调，相应的给人的感觉也不同。\n\n“山寒水瘦”常用来形容秋冬山水。这里在山前着一“寒”字，就显出深秋的季节特点。“转苍翠”表示山色愈来愈深，寒意愈来愈重，这又是就一日之内从朝到暮的变化说的，意思是随着天色向晚，山色也显得更加苍翠了。北...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "6464524f30675327e18729bb", "shortContent": "《新唐书·王维传》：“别墅在辋川，地奇胜。……与裴迪游其中，赋诗相酬为乐。”这首诗即与裴迪相酬为乐之作。\n\n这是一首诗、画、音乐完美结合的五律。首联和颈联写景，描绘辋川附近山水田园的深秋暮色；颔联和尾联写人，刻画诗人和裴迪两个隐士的形象。风光人物，交替行文，相映成趣，形成物我一体、情景交融的艺术境界，抒写诗人的闲居之乐和对友人的真切情谊。\n\n“寒山转苍翠，秋水日潺湲。”首联写山中秋景。时在水落石出...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646454005fc8182fe99c3f7a", "shortContent": "新唐书·王维传》：“别墅在辋川，地奇胜。……与裴迪游其中，赋诗相酬为乐。”这首诗即与裴迪相酬为乐之作。\n\n这是一首诗、画、音乐完美结合的五律。首联和颈联写景，描绘辋川附近山水田园的深秋暮色；颔联和尾联写人，刻画诗人和裴迪两个隐士的形象。风光人物，交替行文，相映成趣，形成物我一体、情景交融的艺术境界，抒写诗人的闲居之乐和对友人的真切情谊。\n\n“寒山转苍翠，秋水日潺湲。”首联写山中秋景。时在水落石出的...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}]', '《唐诗品汇》：刘云：类以无情之景述无情之意，复非作者所有。
《唐诗归》：钟云：“转”字妙，于“寒山”有情（首句下钟云：“上”字好（“墟里”句下）。
《唐诗镜》：三四意态犹夷。五六佳在布景，不在属词。彼“时倚檐前树，远看原上村”，语似逊此。
《唐风定》：起语高远空旷，然与嘉州不同。
《唐诗选脉会通评林》：周珽曰：淡宕闲适，绝类渊明。
《唐诗评选》：通首都有“赠”意在言句文身之外，不可徒以结用两古人为赠也。楚狂、陶令俱凑手偶然，非著意处，以高洁写清幽，故胜。
《唐诗矩》：虚实相间格。一二五六用实，三四七八用虚，相间成篇。
《唐贤三昧集笺注》：对起，上句尤妙，此从陶出。“渡头余落日，墟里上孤烟”。景色可想。顾云：一时情景，真率古淡。
《闻鹤轩初盛唐近体读本》：陈德公曰：此篇声格与上诸作迥别，淡逸清高，自然绝俗。右丞有此二致，朝殿则绅黻雍容，山林则瓢衲自得，惟其称也。评：三四绝不作意，品高气逸，与“采菊东篱下，悠然见南山”正同一格。五六亦是直置语，淡然高老，无假胭脂。绮隽之外，又须知有此种，盖关乎性情，本之元亮，不从沈、宋袭得，独为千古。
《唐贤清雅集》：神韵止可意会，才拟议便非。
《唐诗三百首》：又从上“暮”字生出（“墟里”句下）。
《唐宋诗举要》：自然流转，时气象又极阔大。', 'center', 1415639518, '57b8f71bdf0eea0063349fb7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10291, '竹里馆', NULL, 1788, 394, 2, 14, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/154771.htm', '', '独坐幽篁里，弹琴复长啸。
深林人不知，明月来相照。', '此诗是王维晚年隐居蓝田辋川时创作的一首五绝。此诗写山林幽居情趣，属闲情偶寄，遣词造句简朴清丽，传达出诗人宁静、淡泊的心境，表现了清幽宁静、高雅绝俗的境界。全诗虽只有短短的二十个字，但有景有情、有声有色、有静有动、有实有虚，对立统一，相映成趣，是诗人生活态度以及作品特点的绝佳表述。', '竹里馆：辋川别墅胜景之一，房屋周围有竹林，故名。
幽篁（huáng）：幽深的竹林。
啸（xiào）：嘬口发出长而清脆的声音，类似于打口哨。
深林：指“幽篁”。
相照：与“独坐”相应，意思是说，左右无人相伴，唯有明月似解人意，偏来相照。
长啸：撮口而呼，这里指吟咏、歌唱。古代一些超逸之士常用来抒发感情。魏晋名士称吹口哨为啸。', '我独自坐在幽深的竹林，一边弹琴一边高歌长啸。
没人知道我在竹林深处，只有明月相伴静静照耀。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9297dbb8b379ee09597a", "shortContent": "这首小诗总共四句。拆开来看，既无动人的景语，也无动人的情语；既找不到哪个字是诗眼，也很难说哪一句是警策。\n诗中写到景物，只用六个字组成三个词，就是：“幽篁”、“深林”、“明月”。对普照大地的月亮，用一个“明”字来形容其皎洁，并无新意巧思可言，是人人惯用的陈词。至于第一句的“篁”与第三句的“林”，其实是一回事，是重复写诗人置身其间的竹林，而在竹林前加“幽”、“深”两字，不过说明其既非北周庾信《小园赋...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc40928", "shortContent": "这首小诗总共四句。拆开来看，既无动人的景语，也无动人的情语；既找不到哪个字是诗眼，也很难说哪一句是警策。\n\n诗中写到景物，只用六个字组成三个词，就是：“幽篁”“深林”“明月”。对普照大地的月亮，用一个“明”字来形容其皎洁，并无新意巧思可言，是人人惯用的陈词。至于第一句的“篁”与第三句的“林”，其实是一回事，是重复写诗人置身其间的竹林，而在竹林前加“幽”“深”两字，不过说明其既非北周庾信《小园赋》所...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f09364", "shortContent": "《竹里馆》是唐代诗人王维晚年隐居蓝田辋川时创作的一首五言绝句。王维信奉佛教，思想超脱，加之仕途坎坷，四十岁以后就过着半官半隐的生活。正如他自己所说：“晚年惟好静，万事不关心。”因而诗人常常独自坐在幽深的竹林之中，弹着古琴以抒寂寞的情怀。作者对大自然真挚的喜爱从诗中流露，正如清代宋征璧在《抱真堂诗话》中说：“王摩诘胸中真有辋川，非强为之词者。”\n\n本诗写山林幽居情趣，属闲情偶寄，通过描绘了诗人月下独...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270437ccdb86c49f2921e", "shortContent": "《竹里馆》是唐代诗人王维晚年隐居蓝田辋川时创作的一首五言绝句。王维早年信奉佛教，思想超脱，加之仕途坎坷，四十岁以后就过着半官半隐的生活。正如他自己所说：“晚年惟好静，万事不关心。”因而诗人常常独自坐在幽深的竹林之中，弹着古琴以抒寂寞的情怀。作者对大自然真挚的喜爱从诗中流露，正如清代宋征璧在《抱真堂诗话》中说：“王摩诘胸中真有辋川，非强为之词者。”\n\n本诗写山林幽居情趣，属闲情偶寄，通过描绘诗人月下...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127077f2af4e09d55b6793", "shortContent": "《竹里馆》是唐代诗人王维晚年隐居蓝田辋川时创作的一首五绝。王维早年信奉佛教，思想超脱，加之仕途坎坷，四十岁以后就过着半官半隐的生活。正如他自己所说：“晚年惟好静，万事不关心。”因而常常独自坐在幽深的竹林之中，弹着古琴以抒寂寞的情怀。作者对大自然真挚的喜爱从诗中流露，正如清代宋徽璧在《抱真堂诗话》中说：“王摩诘胸中真有辋川，非强为之词者。”\n\n本诗写山林幽居情趣，属闲情偶寄，通过描绘诗人月下独坐、弹...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646477c2e49f46528aa45e39", "shortContent": "这是《辋川集》中的一首，这首小诗总共四句。拆开来看，既无动人的景语，也无动人的情语；既找不到哪个字是诗眼，也很难说哪一句是警策。\n\n诗中写到景物，只用六个字组成三个词，就是：“幽篁”“深林”“明月”。对普照大地的月亮，用一个“明”字来形容其皎洁，并无新意巧思可言，是人人惯用的陈词。至于第一句的“篁”与第三句的“林”，其实是一回事，是重复写诗人置身其间的竹林，而在竹林前加“幽”“深”两字，不过说明其...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}]', '顾云《王孟诗评》：一时清兴，适与景会。
《唐诗广选》：人不知而月相照，正应首句“独坐”二字。
《唐贤三昧集笺注》：幽迥之思，使人神气爽然。
《唐诗笺注》：《辋川》诸诗，皆妙绝天成，不涉色相。止录二首（指《鹿柴》及此诗），尤为色籁俱清，读之肺腑若洗。
《唐人万首绝句选评》：毋乃有傲意。
《诗境浅说续编》：《辋川集》中，如《孟城坳》、《栾家濑》诸作，皆闲静而有深湛之思。此诗言月下鸣琴，风篁成韵，虽一片静景，而以浑成出之。坊本《唐诗三百首》特录此首者，殆以其质直易晓，便于初学也。
《唐人绝句精华》：以上四诗（指《鹿柴》、《栾家漱》、《竹里馆》及《鸟鸣涧》），皆一时清景与诗人兴致相会合，故虽写景色、而诗人幽静恬淡之胸怀，亦缘而见。此文家所谓融景入情之作。', 'center', 1415639573, '57b910f879bc44005b9f21cf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10292, '如梦令', NULL, 255, 1624, 2, 1, '刘基', NULL, 10076, '57ba8247c4c97100614d49ee', '明', 'ci', '词', '', '', '一抹斜阳沙觜，几点闲鸥草际，乌榜小渔舟，摇过半江秋水。风起，风起，棹入白苹花里。', '残阳一抹，闲鸥几点，景极悠远淡雅；秋水荡舟，风起白蘋，更是风韵别具，令人神怡。此词短小精致，意境美，文辞亦美。堪称明词中之佳作。', NULL, NULL, NULL, NULL, 'indent', 1415639642, '57b2bb0b0a2b58006336fa8a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10293, '五月十九日大雨', NULL, 138, 1624, 1, 2, '刘基', NULL, 10076, '57ba8247c4c97100614d49ee', '明', 'shi', '诗', 'http://baike.baidu.com/view/3200315.htm', '', '风驱急雨洒高城，云压轻雷殷地声。
雨过不知龙去处，一池草色万蛙鸣。', '这首诗非常形象地描述了夏天所特有的雷阵雨前后的自然景象。前两句极力描述大雨的气势：黑云压城，风急雨骤，电闪雷鸣，大雨倾盆。后两句描述雨过天晴的景象：雷雨过后，草色更青，池塘水涨，蛙声一片。此诗写的是雨来到雨止。诗的前半句写出雷雨交作，气势雄峻；后半句写雨过天晴，平淡恬淡。前雷声，后蛙鸣，两两对照，逸趣横生。', '驱：驱使。
急雨：骤雨。
云：这里指乌云。
殷（yǐn）：震动。
池：池塘。', '疾风驱使着骤雨倾倒在高城，乌云密布，雷声殷殷隆隆。一会儿，那兴云作雨的龙挟着雷电乌云离去，眼前出现的是池塘水溢，青草滴翠，万蛙齐鸣。', '[{"bookId": "60d939cea06dc908f045ad24", "bookTitle": "元明清诗鉴赏辞典（新一版）", "articleId": "610e8cca03048e64fbd8f6ce", "shortContent": "绝句由于篇幅短小，所蕴含量又要求很大，所以往往采用开门见山的写法。这首诗是写大雨，一开始就展现大雨奇观。诗人站在高高的城楼上，眼见疾风驱使着大雨，倾倒下来，乌云密布，雷声隆隆，震撼大地。诗注重炼字，雨是“急雨”，且被大风驱赶，洒向城楼，“急”、“驱”、“洒”三字，形象地表现出夏雨的骤猛。陪伴风雨的云是“压”向城；雷是“殷”地，又说明了黑云、雷电的迅疾、气势。杜甫《白帝》诗写雨景：“白帝城头云若屯，...", "authors": ["李梦生"], "pressName": "上海辞书出版社"}, {"bookId": "645bb7088258810260d4d543", "bookTitle": "元明清诗三百首鉴赏辞典", "articleId": "645f6a3a45e4710056ae423f", "shortContent": "绝句由于篇幅短小，所蕴含量又要求很大，所以往往采用开门见山的写法。这首诗是写大雨，一开始就展现大雨奇观。诗人站在高高的城楼上，眼见疾风驱使着大雨，倾倒下来，乌云密布，雷声隆隆，震撼大地。诗注重炼字，雨是“急雨”，且被大风驱赶，洒向城楼，“急”、“驱”、“洒”三字，形象地表现出夏雨的骤猛。陪伴风雨的云是“压”向城；雷是“殷”地，又说明了黑云、雷电的迅疾、气势。杜甫《白帝》诗写雨景：“白帝城头云若屯，...", "authors": ["李梦生"], "pressName": "上海辞书出版社"}]', '李梦生《元明清诗三百首鉴赏辞典》：刘基这首诗虽然写的是雨，无疑又给人这样的启示：大风大雨虽然猛烈，但维持的时间决不会长久；一个人在生活中遇到挫折时，应当勇敢顽强，难关终将过去。
黄绍筠《中华古典诗歌吟味》：暗示了暴雨不终朝”的哲理，启发人们思考，遇到大困难时，再坚持一下。往往就可以闯过难关。
钱仲联《元明清诗鉴赏辞典辽·金·元·明》：杜甫《白帝》诗写雨景：耵自帝城头云若电，白帝城下雨硒盆。高江急峡雷霆斗，翠木苍藤日月昏．”李贺《雁门太守行》写云：“黑云压城城欲摧，甲光向日金鳞开。”刘基这两句诗摹写风云雷电，明显脱胎于杜甫、李贺，但更为集中。', 'center', 1415639691, '57b901640a2b58005c9242a8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (11749, '八月十五日夜湓亭望月', NULL, 37, 2952, 0, 1, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', 'http://baike.baidu.com/view/901655.htm', '', '昔年八月十五夜，曲江池畔杏园边。
今年八月十五夜，湓浦沙头水馆前。
西北望乡何处是，东南见月几回圆。
昨风一吹无人会，今夜清光似往年。', '《八月十五日夜湓亭望月》唐代诗人白居易的作品，出自《全唐诗》。', '昔年：去年、以往。', '以往八月十五的夜晚，我站在曲江的池畔杏园旁边。
今年八月十五的夜晚，我又在湓浦沙头水馆前。
向着西北怎么才能看到故乡在哪里，向着东南方向看见月亮又圆了好几次。
昨天的风吹过没有人理会，今晚清美的风彩就好像以往的那些年。', NULL, '', 'center', 1473087944, '57cd1cce5bbb500074f8ca21', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10295, '沈园（其一）', NULL, 435, 9405, 1, 1, '陆游', NULL, 10019, '57b904a9d342d3005ac748fb', '宋', 'shi', '诗', 'http://baike.baidu.com/view/1778994.htm', '', '城上斜阳画角哀，沈园非复旧池台。
伤心桥下春波绿，曾是惊鸿照影来。', '《沈园二首》是宋代诗人陆游的组诗作品，是作者在七十五岁时创作的两首悼亡诗，此为第一首，回忆沈园相逢之事，悲伤之情充溢楮墨之间。', '沈园：故址在今浙江绍兴禹迹寺南。
斜阳：偏西的太阳。
画角：涂有色彩的军乐器，发声凄厉哀怨。
惊鸿：语出三国魏·曹植《洛神赋》句「翩若惊鸿」，以喻美人体态之轻盈。这里指唐琬。', '斜阳下城墙上的角声彷彿也在哀痛，沈园已经不是原来的亭台池阁。
那座令人伤心的桥下，春水依然碧绿，当年这里我见到她美丽的侧影惊鸿一现。', '[{"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646b7512e49f46528ac2446e", "shortContent": "陆游被誉为“亘古男儿一放翁”（梁启超《读陆放翁集》），尝自称“老夫壮气横九州”（《冬暖》），渴望“上马击狂胡，下马草军书”（《观大散关图有感》），是一个豪气冲天的大丈夫，写有大量天风海雨般的作品。但这只是其人其诗之一面（当然是主导方面）。他还有另一面，即个人家庭的悲欢离合，儿女之情的缠绵悱恻。他抒发此类感情的作品，写得哀婉动人。他一生最大的个人不幸就是与结发妻唐琬的爱情悲剧。据《齐东野语》等书记载...", "authors": ["王英志"], "pressName": "上海辞书出版社"}]', '徐中玉：陆游作此诗时已七十五岁。四十多年前发生的悲剧，一直啮嚼着老诗人的心。故地重游，触景生情，仍禁不住伤心泪下。
余春柯：陆游诗里、心头的「沈园情结」，不仅让自己至死含恨，也引得无数文人学者前赴后继为之纠结、求索、考证。《沈园二首》情动辞发，以枯木之心，幻出葩华，诗情要约写真，志惟深远，启迪来者。', 'center', 1423174483, '57b8b5572e958a005fa43daf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10296, '木兰花慢 · 滁州送范倅', NULL, 288, 793, 7, 4, '辛弃疾', NULL, 10003, '57b8ed682e958a005fa4d096', '宋', 'ci', '词', 'http://baike.baidu.com/view/384028.htm', '', '老来情味减，对别酒，怯流年。况屈指中秋，十分好月，不照人圆。无情水，都不管，共西风、只管送归船。秋晚莼鲈江上，夜深儿女灯前。
征衫，便好去朝天。玉殿正思贤。想夜半承明，留教视草，却遣筹边。长安故人问我，道愁肠殢酒只依然。目断秋霄落雁，醉来时响空弦。', '这首词作于乾道八年（公元1172年）滁州（今属安徽）任上，是为送他的同事范昂赴京城临安而作。上阕写惜别之情和流光虚度之叹。下阕寄托自己感慨之情。词意层层相催，逼人欷献叹惋，抒发离情中透露着豪放。', '滁州：古州名。东魏置南谯州，隋改置滁州，唐、宋因之。宋属淮南东路，地处滁河流域，境内琅琊山风景幽美，为游览胜地。
范倅：即范昂，滁州（今安徽滁州市）通判。《滁州府志·职官·通判》：“范昂，乾道六年任。”《宋会要辑稿·职官·一〇之九》：“乾道八年正月十四日诏滁州州县官到任任满，依次边舒州州县官推赏。先是，权通判滁州范昂陈请，故有是诏。”据知此范倅即范昂。唯范氏事历别无所考。并其字里亦莫得而知。倅，副职。
老来：稼轩三十三岁而自称“老来”。一则因为古人常常感叹时光流逝人生易老，二则针对年少立业而言，现在已过而立之年，而复国大业仍未实现，所以称“老”。
“对别酒，怯流年”句：宋·苏轼《江城子·东武雪中送客》：“对尊前，惜流年。”
秋晚莼鲈江上：《世说新语·识鉴》：“张季鹰辟齐王东曹掾，在洛，见秋风起，因思吴中菰菜、莼羹、鲈鱼脍，曰：‘人生贵得适意尔，何能羁宦数千里以要名爵？’遂命驾便归。俄而齐王败，时人皆谓见机。”作者借其指代范昂返乡。
夜深儿女灯前：宋·黄庭坚《寄叔父夷仲》诗:“弓刀陌上看行色，儿女灯前语夜深。”
朝天：指朝见天子。
玉殿：皇帝处理政事的金銮宝殿，用以代指皇帝。
夜半承明：《汉书·卷六十四上·严助传》：“君厌承明之庐，劳侍从之事。”注：“汉有承明庐。承明庐在石渠阁外。直宿所止曰庐。”东汉·班固《西都赋》：“又有承明金马，著作之庭。大雅宏达，于兹为群。”唐·李商隐《贾生》诗：“宣室求贤访逐臣，贾生才调更无伦。可怜夜半虚前席，不问苍生问鬼神。”
视草：为皇帝起草制诏。《旧唐书·卷四十三·职官志·翰林院》：“玄宗即位，张说等人入禁中，谓之翰林待诏。……或诏从中出，虽宸翰所挥，亦资其检讨，谓之视草，故尝简当代士人，以备顾问。”
筹边：筹划边防军务。
殢酒：沉溺于酒。唐·韩偓《有忆》：“愁肠殢酒人千里，泪眼倚楼天四垂。”宋·秦观《梦扬州》词：“殢酒困花，十载因谁淹留。”
“目断秋霄落雁，醉来时响空弦。”句：《战国策·卷十七·楚策四》：“天下合从。赵使魏加见楚春申君曰：‘君有将乎？’曰：‘有矣，仆欲将临武君。’魏加曰：‘臣少之时好射，臣愿以射譬之，可乎？’春申君曰：‘可。’加曰：‘异日者，更羸与魏王处京台之下，仰见飞鸟。更羸谓魏王曰：“臣为王引弓虚发而下鸟。”魏王曰：“然则射可至此乎？”更羸曰：“可。”有间，雁从东方来，更羸以虚发而下之。魏王曰：“然则射可至此乎？”更羸曰：“此孽也。”王曰：“先生何以知之？”对曰：“其飞徐而鸣悲。飞徐者，故疮痛也；鸣悲者，久失群也，故疮未息，而惊心未去也。闻弦音，引而高飞，故疮陨也。”今临武君，尝为秦孽，不可为拒秦之将也。’”宋·苏轼《次韵王雄州送侍其泾州》诗：“闻道名城得真将，故应惊羽落空弦。”', '我感到人生衰老，早年的情怀、趣味全减，面对着送别酒，怯惧年华流变。何况屈指计算中秋佳节将至，那一轮美好的圆月，偏不照人的团圆。无情的流水全不管离人的眷恋，与西风推波助澜，只管将归舟送归。祝愿你在这晚秋的江面，能将莼菜羹、鲈鱼脍品尝，回家后和儿女团聚在夜深的灯前。
趁旅途的征衫未换，正好去朝见天子，而今朝廷正思贤访贤。料想在深夜的承明庐，正留下来教你检视翰林院草拟的文件，还派遣筹划边防军备。说都故友倘若问到我，只说我依然是愁肠满腹借酒浇愁愁难遣。遥望秋天的云霄里一只落雁消逝不见，我沉醉中听到有谁奏响了空弦！', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74e734a8757d5a0d9ede", "shortContent": "这首词作于宋孝宗乾道八年（1172）。辛稼轩词率多感时抚事之作，词情豪放。即或是送别词，亦多尚慷慨悲吟，不效昵昵儿女语。本词即其一。作者以送别为发端，倾吐自己满腹忧国深情。在激励友人奋进之中，又抒泄了自己壮志难酬的苦闷。慷慨悲凉之情，磊落不平之气，层见叠出。\n“老来情味减，对别酒，怯流年。”发端数语陡然而起，直抒胸臆，以建瓴之势笼罩全篇。苏轼有“对尊前，惜流年”（《江城子·冬景》），此处化用其句，...", "authors": ["许理绚"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ea34a8757d5a0ecb24", "shortContent": "这首词作于宋孝宗乾道八年（1172）。辛稼轩词率多感时抚事之作，词情豪放。即或是送别词，亦多尚慷慨悲吟，不效昵昵儿女语。本词即其一。作者以送别为发端，倾吐自己满腹忧国深情。在激励友人奋进之中，又抒泄了自己壮志难酬的苦闷。慷慨悲凉之情，磊落不平之气，层见叠出。\n“老来情味减，对别酒，怯流年。”发端数语陡然而起，直抒胸臆，以建瓴之势笼罩全篇。苏轼有“对尊前，惜流年”（《江神子·冬景》），此处化用其句，...", "authors": ["许理绚"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f4f73206168b2e020fe", "shortContent": "世人每谓稼轩词“大声镗鞳，小声铿，横绝六合，扫空万古”（刘克庄评语）、“别开天地，横绝古今”（吴衡照评语），其实风云气多，并不妨碍其深情绵密，所以周济评道：“后人以粗豪学稼轩，非徒无其才，并无其情。稼轩固是才大，然情至处后人万不能及。”以“情至”来作为理解这阕《木兰花慢》，是最好的一把钥匙。\n这首词的题目是“滁州送范侔”，是时辛弃疾任滌州知州，而范昂是滁州通判，期满将归乡。分别之际，辛弃疾写了这首...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312704773206168b2e021cc", "shortContent": "世人每谓稼轩词“大声镗鞳，小声铿鍧，横绝六合，扫空万古”（刘克庄评语）、“别开天地，横绝古今”（吴衡照评语），其实风云气多，并不妨碍其深情绵密，所以周济评道：“后人以粗豪学稼轩，非徒无其才，并无其情。稼轩固是才大，然情至处后人万不能及。”以“情至”来作为理解这阕《木兰花慢》，是最好的一把钥匙。\n\n这首词的题目是“滁州送范倅”，是时辛弃疾任滁州知州，而范昂是滁州通判，期满将归乡。分别之际，辛弃疾写了...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631272067ccdb86c49f29398", "shortContent": "世人每谓稼轩词“大声镗鞳，小声铿鍧，横绝六合，扫空万古”（刘克庄评语）、“别开天地，横绝古今”（吴衡照评语）。其实风云气多，并不妨碍其深情绵密，所以周济评道：“后人以粗豪学稼轩，非徒无其才，并无其情。稼轩固是才大，然情至处后人万不能及。”以“情至”来作为理解这阕《木兰花慢》，是最好的一把钥匙。\n这首词的题目是“滁州送范倅”，是时辛弃疾任滁州知州，而范倅是滁州通判，期满将归乡。分别之际，辛弃疾写了这...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "64688f9830675327e19962ff", "bookTitle": "辛弃疾词鉴赏辞典（珍藏本）", "articleId": "6468d806c0471b0062dedbf0", "shortContent": "这首词作于宋孝宗乾道八年(1172)。辛稼轩词率多感时抚事之作，词情豪放。即或是送别词，亦多尚慷慨悲吟，不效昵昵儿女语。本词即其一。作者以送别为发端，倾吐自己满腹忧国深情。在激励友人奋进之中，又抒泄了自己壮志难酬的苦闷。慷慨悲凉之情，磊落不平之气，层见叠出。\n“老来情味减，对别酒，怯流年。”发端数语陡然而起，直抒胸臆，以建瓴之势笼罩全篇。苏轼有“对尊前，惜流年”（《江城子·冬景》），此处化用其句，...", "authors": ["许理绚"], "pressName": "上海辞书出版社"}]', '', 'indent', 1363206360, '57b8e1aa79bc44005b9df5ec', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10297, '国风 · 郑风 · 女曰鸡鸣', NULL, 368, 573, 1, 2, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'shi', '诗', 'http://baike.baidu.com/view/3622161.htm', '', '女曰鸡鸣，士曰昧旦。子兴视夜，明星有烂。将翱将翔，弋凫与雁。
弋言加之，与子宜之。宜言饮酒，与子偕老。琴瑟在御，莫不静好。
知子之来之，杂佩以赠之。知子之顺之，杂佩以问之。知子之好之，杂佩以报之。', '全诗三章，每章六句。这首赋体诗恰似一幕生活小剧。诗人通过士女对话，展示了三个情意融融的特写镜头。这对青年夫妇和谐的家庭生活和诚笃而热烈的感情，令人羡慕，令人赞叹。《诗经》是汉族文学史上第一部诗歌总集。对后代诗歌发展有深远的影响。', '昧旦：天色将明未明之际。
兴：起。
视夜：察看夜色。
明星：启明星，即金星。
将翱将翔：指已到了破晓时分，宿鸟将出巢飞翔。
弋（yì）射：用生丝做绳，繫在箭上射鸟。
凫：野鸭。
言：语助词，下同。
加：射中。一说「加豆」，食器。
与：犹为。
宜：用适当地方法烹饪。译为烹饪。
御：用，弹奏。
静好：和睦安好。
来：借为「赉（lài）」，慰劳。
杂佩：古人佩饰，上繫珠、玉等，质料和形状不一，故称杂佩。
顺：柔顺。
问：慰问，问候。
好（hào）：爱恋。', '女说：「公鸡已鸣唱。」男说：「天还没有亮。不信推窗看天上，启明星已在闪光。」「宿巢鸟雀将翱翔，射鸭射雁去芦荡。」
「野鸭大雁射下来，为你烹调做好菜。佳肴做成共饮酒，白头偕老永相爱。」女弹琴来男鼓瑟，和谐美满在一块。
「知你对我真关怀呀，送你杂佩答你爱呀。知你对我体贴细呀，送你杂佩表谢意呀。知你爱我是真情呀，送你杂佩表同心呀。」', '[{"bookId": "60fccb5034bfda01e0ea02ff", "bookTitle": "先秦诗鉴赏辞典（新一版）", "articleId": "610f37477d0ac11454969999", "shortContent": "这首赋体诗恰似一幕生活小剧。诗人通过士女对话，展示了三个情意融融的特写镜头。这对青年夫妇和谐的家庭生活与诚笃而热烈的感情，令人羡慕，令人赞叹。\n第一个镜头：鸡鸣晨催。起先，妻子的晨催，并不令丈夫十分惬意。公鸡初鸣，勤勉的妻子便起床准备开始一天的劳作，并告诉丈夫“鸡已打鸣”。“女曰鸡鸣”，妻子催得委婉，委婉的言辞含蕴不少爱怜之意；“士曰昧旦”，丈夫回得直白，直决的回答显露出明显的不快之意。他似乎确实...", "authors": ["陈文忠"], "pressName": "上海辞书出版社"}, {"bookId": "627298aa34359466e82f44e0", "bookTitle": "诗经鉴赏辞典", "articleId": "63126fe477683d1933015290", "shortContent": "这是反映夫妻和美生活之诗。\n全诗三章。诗中写的是凌晨时猎人夫妻间的一场精彩对话。妻子说：“鸡已叫了。”丈夫则说：“天刚破晓。”妻子又催促说：“你起来去看看夜空，启明星已经很亮了。”丈夫接着说：“我就起来，到四处去游猎，射那野鸭和大雁。”妻子听罢，便温情脉脉地说：“你射中野禽，我来做成美味菜肴。咱俩一边品尝野味，一边尽兴饮酒，与你白头偕老。愿你我之情如同琴瑟之音那样和谐，永远生活得宁静而又美好。”丈...", "authors": [], "pressName": "崇文书局"}, {"bookId": "627298aa34359466e82f44e0", "bookTitle": "诗经鉴赏辞典", "articleId": "63126fe477683d193301529e", "shortContent": "这是男女幽会之诗。\n全诗三章。写的是一对恋人幽会将终时的窃窃私语，表达了燕尔亲昵难舍难分的热恋之情。一章重在写听觉。女子说：“鸡已叫了，天快亮了。”男子说：“不是鸡的叫声，而是苍蝇的声音。”二章重在写视觉。女子说：“东方发白，天已大亮。”男子说：“不是东方发白，而是月亮的光华。”这些对白，道出了这对恋人害怕天明的复杂心理。三章写幽会将终难舍难分。男子说：“虫子群飞薨薨响，愿与你一同入梦乡。”女子说...", "authors": [], "pressName": "崇文书局"}, {"bookId": "642074e9995d79753170c75a", "bookTitle": "诗经三百篇鉴赏辞典", "articleId": "6470647c82772d4594219d25", "shortContent": "这首赋体诗恰似一幕生活小剧。诗人通过士女对话，展示了三个情意融融的特写镜头。这对青年夫妇和谐的家庭生活和诚笃而热烈的感情，令人羡慕，令人赞叹。\n\n第一个镜头：鸡鸣晨催。起先，妻子的晨催，并不令丈夫十分惬意。公鸡初鸣，勤勉的妻子便起床准备开始一天的劳作，并告诉丈夫“鸡已打鸣”。“女曰鸡鸣”，妻子催得委婉，委婉的言辞含蕴不少爱怜之意；“士曰昧旦”，丈夫回得直白，直决的回答显露出明显的不快之意。他似乎确...", "authors": ["陈文忠"], "pressName": "上海辞书出版社"}]', '', 'indent', 1445533471, '57b8f2bf8ac2470062df3b89', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10298, '诗经 · 郑风 · 子衿', NULL, 1313, 573, 2, 3, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'shi', '诗', 'http://baike.baidu.com/view/3655275.htm', '', '青青子衿，悠悠我心。纵我不往，子宁不嗣音？
青青子佩，悠悠我思。纵我不往，子宁不来？
挑兮达兮，在城阙兮。一日不见，如三月兮！', '此诗是《诗经》中的一首诗，描写一个女子思念她的心上人。每当看到颜色青青的东西，女子就会想起心上人青青的衣领和青青的佩玉。于是她登上城门楼，就是想看见心上人的踪影。如果有一天看不见，她便觉得如隔三月。全诗充分描写了女子单相思的心理活动，惟妙惟肖，而且意境很美，是一首难得的优美的情歌，成为中国文学史上描写相思之情的经典之作，其中「一日不见，如三月兮」更是千古名句。', '子衿：周代读书人的服装。子，男子的美称，这里即指「你」。衿：即襟，衣领。
嗣（sì）音：接续，继续。
佩：这里指系珮之绶带。
挑（tāo）兮达（tà）兮：独自走来走去的样子。挑，《康熙字典》：「《康熙字典》：「《唐韵》：『土刀切』《集韵》《韵会》《正韵》：『他刀切』，？音叨。《诗·郑风》：『挑兮达兮。』《毛传》：『往来相见貌。』《朱传》：『挑，独自徘徊的样子。』」
城阙：城门两边的观楼。', '青青的是你的衣领，悠悠的是我的心境。纵然我不曾去会你，难道你就此断音信？
青青的是你的佩带，悠悠的是我的情怀。纵然我不曾去会你，难道你不能主动来？
来来往往张眼望啊，在这高高城楼上啊。一天不见你的面啊，好像已有三月长啊！', '[{"bookId": "60fccb5034bfda01e0ea02ff", "bookTitle": "先秦诗鉴赏辞典（新一版）", "articleId": "610f374803572034f65b3d98", "shortContent": "由于孔子曾说过“《诗》三百，一言以蔽之，曰思无邪”（《论语》），经学家便将《诗经》的每首诗都套上“思无邪”的灵光圈，致使一部《诗经》竟成了儒家的道德教科书。如本篇《子衿》，《毛诗序》认为“刺学校废也，乱世则学校不修焉”。孔颖达疏进一步解释说：“郑国衰乱不修学校，学者分散，或去或留，故陈其留者恨责去者之辞，以刺学校之废也。经三章皆陈留者责去者之辞也。”可是我们在诗中实在看不出什么“学校废”的迹象。朱...", "authors": ["陈如江"], "pressName": "上海辞书出版社"}, {"bookId": "627298aa34359466e82f44e0", "bookTitle": "诗经鉴赏辞典", "articleId": "63126fe477683d1933015296", "shortContent": "这是男子亲迎而女子未随之诗。\n全诗四章。一对青年，本已缔结了婚约。然而待到男方驾车前往亲迎时，情况却起了变化。首二章写女子因这场风波而起的内心悔恨。从诗中看，这一对青年本来是有情的。小伙子长得挺不错，他不仅体魄健壮，而且相貌堂堂。这“丰”“昌”二字从女子口中唱出，说明她是很爱这个小伙子的。然而临到关键时刻，女方却反悔了这门亲事。引起婚姻变故的原因，当是由于女子父母变心。就这样，一场圆满的婚姻被破坏...", "authors": [], "pressName": "崇文书局"}, {"bookId": "627298aa34359466e82f44e0", "bookTitle": "诗经鉴赏辞典", "articleId": "63126fe477683d1933015299", "shortContent": "这是女子焦灼地等候情人之诗。\n全诗三章。热恋中的青年男女时常为一些细小的缘故而引出层层的心理波澜。此诗中的女子也正处在这种心态之中。从诗中看，在此之前，她与男友的交往是亲密的，感情是融洽的。他俩经常相会，互倾情愫。然而不知何故，这对恋人之间似乎有了一点小的曲折和误会，闹了一点小别扭。她终于有些沉不住气了，于是来到以前他俩时常幽会的地方，希望能重见他的身影。\n一、二章写女子思望之情。她在城阙上等了一...", "authors": [], "pressName": "崇文书局"}, {"bookId": "627298aa34359466e82f44e0", "bookTitle": "诗经鉴赏辞典", "articleId": "63126fedc305cf0801816e38", "shortContent": "这是歌咏猎人之诗。\n全诗三章。诗中写了两个猎人。甲猎人称赞乙猎人为“还”，为“茂”，为“昌”。仅此三字便将乙猎人敏捷、健美、强壮的英姿再现了出来。他俩在峱山相遇，并马追逐野兽，猎取野物。打猎结束时，乙猎人拱手作揖，并称赞甲猎人为“儇”，为“好”，为“臧”。也仅此三字，便将甲猎人利落、壮美、善射的雄姿勾勒了出来。方玉润《诗经原始》说：“章潢曰：子之还兮，己誉人也。谓我儇兮，人誉己也。并驱，则人己皆与...", "authors": [], "pressName": "崇文书局"}, {"bookId": "642074e9995d79753170c75a", "bookTitle": "诗经三百篇鉴赏辞典", "articleId": "647064c682772d4594219e74", "shortContent": "由于孔子曾说过“《诗》三百，一言以蔽之，曰思无邪”（《论语》），经学家便将《诗经》的每首诗都套上“思无邪”的灵光圈，致使一部《诗经》竟成了儒家的道德教科书。如本篇《子衿》，《毛诗序》认为“刺学校废也，乱世则学校不修焉”。孔颖达疏进一步解释说：“郑国衰乱不修学校，学者分散，或去或留，故陈其留者恨责去者之辞，以刺学校之废也。经三章皆陈留者责去者之辞也。”可是我们在诗中实在看不出什么“学校废”的迹象。朱...", "authors": ["陈如江"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b5a5582772d459481c73e", "shortContent": "古往今来，一个“情”字，多少人拿得起，却放不下，从而为后人留下了几多风流佳话；多少青春女子，为一个“情”字，在史书上谱写了几多刚烈多情的篇章。《子衿》出自《郑风》，诗中表达的正是多情少女对恋人的深深思念。所以朱熹这位老学究看不惯，斥之为“淫奔之诗”。在他看来，似乎女人要自由表达自己的爱情，就是神经不正常，不过这从反面承认了诗中女子所具有的大胆、泼辣，远远超出了一般男子的想象。对这首诗，《毛诗序》还...", "authors": ["张传友"], "pressName": "上海辞书出版社"}]', '《毛诗序》：刺学校废也，乱世则学校不修焉。
孔颖达《诗疏》：郑国衰乱不修学校，学者分散，或去或留，故陈其留者恨责去者之辞，以刺学校之废也。经三章皆陈留者责去者之辞也。
朱熹《诗集传》：此亦淫奔之诗。
吴闿生《诗义会通》：旧评：前二章回环入妙，缠绵婉曲。末章变调。
钱锺书《管锥编》：《子衿》云：「纵我不往，子宁不嗣音？」「子宁不来？」薄责己而厚望于人也。已开后世小说言情心理描绘矣。', 'indent', 1415639808, '57b92575c4c9710055905e13', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10299, '国风 · 卫风 · 木瓜', NULL, 375, 573, 2, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'shi', '诗', 'http://baike.baidu.com/view/3618793.htm', '', '投我以木瓜，报之以琼琚，匪报也，永以为好也。
投我以木桃，报之以琼瑶，匪报也，永以为好也。
投我以木李，报之以琼玖，匪报也，永以为好也。', '全诗三章，每章四句。被后世认为是描述男女情谊的佳篇，其作者不详。关于此诗主旨有很多争论，经过汉人、宋人、清人乃至当今学者的考释，对此诗，文学史上大致出现了“美齐桓公说”“男女相互赠答说”“朋友相互赠答说”“臣下报上说”“讽卫人以报齐说”“讽刺送礼行贿说”“表达礼尚往来思想说”等七种说法。在艺术上，全诗语句具有极高的重叠复沓程度，具有很强的音乐性，而句式的参差又造成跌宕有致的韵味，取得声情并茂的效果。《诗经》是中国文学史上第一部诗歌总集。对后代诗歌发展有深远的影响，成为古典文学现实主义传统的源头。', '木瓜：一种落叶灌木（或小乔木），蔷薇科，果实长椭圆形，色黄而香，蒸煮或蜜渍后供食用。按：今粤桂闽台等地出产的木瓜，全称为番木瓜，供生食，与此处的木瓜非一物。
琼琚（jū）：美玉，下“琼玖”“琼瑶”同。
匪：非。
木桃：果名，即楂子，比木瓜小。
木李：果名，即榠楂，又名木梨。', '你将木瓜投赠我，我拿琼琚作回报。不是为了答谢你，珍重情意永相好。
你将木桃投赠我，我拿琼瑶作回报。不是为了答谢你，珍重情意永相好。
你将木李投赠我，我拿琼玖作回报。不是为了答谢你，珍重情意永相好。', '[{"bookId": "60fccb5034bfda01e0ea02ff", "bookTitle": "先秦诗鉴赏辞典（新一版）", "articleId": "610f374534a8757d5a0f80a5", "shortContent": "《诗经·大雅·抑》有“投我以桃，报之以李”之句，后世“投桃报李”便成了成语，比喻相互赠答，礼尚往来。比较起来，《卫风·木瓜》这一篇虽然也有从“投之以木瓜（桃、李），报之以琼琚（瑶、玖）”生发出的成语“投木报琼”（如托名宋尤袤《全唐诗话》就有“投木报琼，义将安在”的记载），但“投木报琼”的使用频率却根本没法与“投桃报李”相提并论。可是倘若据此便认为《抑》的传诵程度也比《木瓜》要高，那就大错而特错了，...", "authors": ["庞", "坚"], "pressName": "上海辞书出版社"}, {"bookId": "627298aa34359466e82f44e0", "bookTitle": "诗经鉴赏辞典", "articleId": "63126fe07ccdb86c49f2915e", "shortContent": "这是青年男女互赠礼物之诗。\n全诗三章。青年男女互赠礼物，作为定情的信物，以表永结同心之好。此诗为男子所唱。每章首二句写互赠礼物。一章说：她送给我香甜的木瓜，我用美丽的佩玉回赠她。二章说：她送给我新鲜的木桃，我用美丽的佩玉来回报。三章说：她送给我鲜美的李子，我用美丽的佩玉来回礼。每章后二句写回赠的目的。男子说：这不是什么回报，而是为了永结同心之好。须得说明的是，风诗的主题常在首章。二、三章写女子送给...", "authors": [], "pressName": "崇文书局"}, {"bookId": "642074e9995d79753170c75a", "bookTitle": "诗经三百篇鉴赏辞典", "articleId": "645e2206cd12b001c6cb47ce", "shortContent": "《诗经·大雅·抑》有“投我以桃，报之以李”之句，后世“投桃报李”便成了成语，比喻相互赠答，礼尚往来。比较起来，《卫风·木瓜》这一篇虽然也有从“投之以木瓜（桃、李），报之以琼琚（瑶、玖）”生发出的成语“投木报琼”（如托名宋尤袤《全唐诗话》就有“投木报琼，义将安在”的记载），但“投木报琼”的使用频率却根本没法与“投桃报李”相提并论。可是倘若据此便认为《抑》的传诵程度也比《木瓜》要高，那就大错而特错了，...", "authors": ["庞坚"], "pressName": "上海辞书出版社"}]', '《毛诗序》：《木瓜》美齐桓公也。卫国有狄人之败出处于漕。齐桓公救而封之遗之车马器服焉。卫人思之欲厚报之而作是诗也。
郑玄《笺》：匪非也。我非敢以琼琚为报木瓜之惠欲令齐长以为玩好结己国之恩也。
贾谊《新书·礼篇》：故礼者所以恤下也。……诗曰“投我以木瓜报之以琼琚。匪报也永以为好也。上少投之则下以躯偿矣。弗敢谓报愿长以为好。古之蓄其下者其报施如此。', 'indent', 1445533574, '57b8fff2c4c97100558f1dc2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639334, '水浒传 · 第六十六回 · 时迁火烧翠云楼 吴用智取大名府', NULL, 0, 124, 0, 1, '施耐庵', NULL, 10333, '57b9ebb3a633bd005d30998b', '明', 'wen', '文', '', '', '诗曰：
野战攻城事不通，神谋鬼计运奇功。
星桥铁锁悠悠展，火树银花处处同。
大府忽为金璧碎，高楼翻作祝融红。
龙群虎队真难制，可愧中书智力穷。
话说吴用对宋江道：“今日幸喜得兄长无事，又得安太医在寨中看视贵疾，此是梁山泊万千之幸。比及兄长卧病之时，小生累累使人去北京探听消息，梁中书昼夜忧惊，只恐俺军马临城。又使人直往北京城里城外市井去处，遍贴无头告示，晓谕居民，勿得疑虑。冤各有头，债各有主；大军到郡，自有对头。因此梁中书越怀鬼胎。东京蔡太师见说降了关胜，天子之前，更不敢题；只是主张招安，大家无事。因此累累寄书与梁中书，教道且留卢俊义、石秀二人性命，好做脚手。”宋江见说，便要催趱军马下山，去打北京。吴用道：“即今冬尽春初，早晚元宵节近，北京年例大张灯火。我欲乘此机会，先令城中埋伏，外面驱兵大进，里应外合，可以救难破城。”宋江道：“若要如此调兵，便请军师发落。”吴用道：“为头最要紧的是城中放火为号。你众弟兄中谁敢与我先去城中放火？”只见阶下走过一人道：“小弟愿往！”众人看时，却是鼓上蚤时迁。时迁道：“小弟幼年间曾到北京。城内有座楼，唤做翠云楼，楼上楼下大小有百十个阁子。眼见得元宵之夜，必然喧哄。乘空潜地入城。正月十五日夜，盘去翠云楼上，放起火来为号，军师可自调人马劫牢，此为上计。”吴用道：“我心正待如此。你明日天晓，先下山去。只在元宵夜一更时候，楼上放起火来，便是你的功劳。”时迁应允，听令去了。吴用次日却调解珍、解宝扮做猎户，去北京城内官员府里献纳野味。正月十五日夜间，只看火起为号，便去留守司前截住报事官兵。两个听令去了。再调杜迁、宋万扮做粜米客人，推辆车子去城中宿歇。元宵夜只看号火起时，却来先夺东门。“此是你两个功劳。”两个听令去了。再调孔明、孔亮扮做仆者，去北京城内闹市里房檐下宿歇。只看楼前火起，便去往来接应。两个听令去了。再调李应、史进扮做客人，去北京东门外安歇。只看城中号火起时，先斩把门军士，夺下东门，好做出路。两个听令去了。再调鲁智深、武松扮做行脚僧行，去北京城外庵院挂搭。只看城中号火起时，便去南门外截住大军，冲击去路。两个听令去了。再调邹渊、邹润扮做卖灯客人，直往北京城中寻客店安歇。只看楼中火起，便去司狱司前策应。两个听令去了。再调刘唐、杨雄扮作公人，直去北京州衙前宿歇。只看号火起时，便去截住一应报事人员，令他首尾不能救应。两个听令去了。再调公孙胜先生扮做云游道士，却教凌振扮做道童跟着，将带风火轰天等炮数百个，直去北京城内净处守待。只看号火起时施放。两个听令去了。再调张顺跟随燕青从水门里入城，径奔卢员外家，单捉淫妇奸夫。再调王矮虎、孙新、张青、扈三娘、顾大嫂、孙二娘扮作三对村里夫妻入城看灯，寻至卢俊义家中放火。再调柴进带同乐和扮做军官，直去蔡节级家中，要保救二人性命。调拨已定，众头领俱各听令去了。各各遵依军令，不可有误。此是正月初头。不说梁山泊好汉依次各各下山进发。有诗为证：
卢生石秀久幽囚，豪杰分头去复仇。
只待上元灯火夜，一时焚却翠云楼。
且说北京梁中书唤过李成、闻达、王太守等一干官员商议放灯一事。梁中书道：“年例北京大张灯火，庆赏元宵，与民同乐，全似东京体例。如今被梁山泊贼人两次侵境，只恐放灯因而惹祸。下官意欲住歇放灯，你众官心下如何计议？”闻达便道：“想此贼人潜地退去，没头告示乱贴，此计是穷，必无主意。相公何必多虑。若还今年不放灯时，这厮们细作探知，必然被他耻笑。可以传下钧旨，晓示居民：比上年多设花灯，添扮社火，市心中添搭两座鳌山，照依东京体例，通宵不禁，十三至十七放灯五夜。教府尹点视居民，勿令缺少。相公亲自行春，务要与民同乐。闻某亲领一彪军马出城去飞虎峪驻扎，以防贼人奸计。再着李都监亲引铁骑马军，绕城巡逻，勿令居民惊忧。”梁中书见说大喜。众官商议已定，随即出榜晓谕居民。
这北京大名府是河北头一个大郡，冲要去处。却有诸路买卖，云屯雾集，只听放灯，都来赶趁。在城坊隅巷陌，该管厢官每日点视，只得装扮社火。豪富之家，各自去赛花灯，远者三二百里去买，近者也过百十里之外。便有客商，年年将灯到城货卖。家家门前扎起灯棚，都要赛挂好灯，巧样烟火。户内缚起山棚，摆放五色屏风炮灯，四边都挂名人画片并奇异古董玩器之物。在城大街小巷，家家都要点灯。大名府留守司州桥边搭起一座鳌山，上面盘红黄纸龙两条，每片鳞甲上点灯一盏，口喷净水。去州桥河内周围上下，点灯不计其数。铜佛寺前扎起一座鳌山，上面盘青龙一条，周回也有千百盏花灯。翠云楼前也扎起一座鳌山，上面盘着一条白龙，四面灯火不计其数。原来这座酒楼，名贯河北，号为第一。上有三檐滴水，雕梁绣柱，极是造得好。楼上楼下，有百十处阁子。终朝鼓乐喧天，每日笙歌聒耳。城中各处宫观寺院佛殿法堂中，各设灯火，庆赏丰年。三瓦两舍，更不必说。
那梁山泊探细人得了这个消息，报上山来。吴用得知大喜，去对宋江说知备细。宋江便要亲自领兵去打北京。安道全谏道：“将军疮口未完，切不可轻动。稍若怒气相侵，实难痊可。”吴用道：“小生替哥哥走一遭。”随即与铁面孔目裴宣点拨八路军马：第一队，双鞭呼延灼引领韩滔、彭玘为前部，镇三山黄信在后策应，都是马军。前者呼延灼阵上打了的是假的，故意要赚关胜，故设此计。第二队，豹子头林冲引领马麟、邓飞为前部，小李广花荣在后策应，都是马军。第三队，大刀关胜引领宣赞、郝思文为前部，病尉迟孙立在后策应，都是马军。第四队，霹雳火秦明引领欧鹏、燕顺为前部，青面兽杨志在后策应，都是马军。第五队，却调步军头领没遮拦穆弘，将引杜兴、郑天寿。第六队，步军头领黑旋风李逵将引李立、曹正。第七队，步军头领插翅虎雷横将引施恩、穆春。第八队，步军头领混世魔王樊瑞将引项充、李衮。这八路马步军兵，各自取路，即今便要起行，毋得时刻有误。正月十五日二更为期，都要到北京城下。马军、步军一齐进发。那八路人马依令下山。其余头领尽跟宋江保守山寨。有诗为证：
八路军兵似虎狼，横天杀气更鹰扬。
安排盖地遮天技，要使鳌山变杀场。
且说时迁是个飞檐走壁的人，不从正路入城，夜间越墙而过。城中客店内却不着单身客人，他自白日在街上闲走，到晚来东岳庙内神座底下安身。正月十三日，却在城中往来观看居民百姓搭缚灯棚，悬挂灯火。正看之间，只见解珍、解宝挑着野味在城中往来观看。又撞见杜迁、宋万两个从瓦子里走将出来。时迁当日先去翠云楼上打一个踅。只见孔明披着头发，身穿羊裘破衣，右手拄一条杖子，左手拿个碗，腌腌臜臜在那里求乞。见了时迁，打抹他去背后说话。时迁道：“哥哥，你这般一个汉子，红红白白面皮，不象叫化的。北京做公的多，倘或被他看破，须误了大事。哥哥可以躲闪回避。”说不了，又见个丐者从墙边来。看时，却是孔亮。时迁道：“哥哥，你又露出雪也似白面来，亦不象忍饥受饿的人。这般模样，必然决撒。”却才道罢，背后两个劈角儿揪住喝道：“你三个做得好事！”回头看时，却是杨雄、刘唐。时迁道：“你惊杀我也！”杨雄道：“都跟我来。”带去僻静处埋冤道：“你三个好没分晓！却怎地在那里说话？倒是我两个看见。倘或被他眼明手快的公人看破，却不误了哥哥大事！我两个都已见了弟兄们，不必再上街去。”孔明道：“邹渊、邹润自在街上卖灯。鲁智深、武松已在城外庵里。再不必多说，只顾临期各自行事。”五个说了，都出到一个寺前，正撞见一个先生从寺里出来，喝道：“你五个在此做甚事？”众人抬头看时，却是入云龙公孙胜，背后凌振扮做道童跟着。七个人都颐指气使，点头会意，各自去了。
看看相近上元，梁中书先令闻大刀闻达将引军马出城，去飞虎峪驻扎，以防贼寇。十四日，却令李天王李成亲引铁骑马军五百，全副披挂，绕城巡视。次日，正是正月十五日上元佳节，好生晴明。黄昏月上，六街三市，各处坊隅巷陌，点放花灯。大街小巷，都有社火。值此元宵，有诗为证：
北京三五风光好，膏雨初晴春意早。
银花火树不夜城，陆地拥出蓬莱岛。
烛龙衔照夜光寒，人民歌舞欣时安。
五凤羽扶双贝阙，六鳌背驾三神山。
红妆女立朱帘下，白面郎骑紫骝马。
笙箫嘹亮入青云，月光清射鸳鸯瓦。
翠云楼高侵碧天，嬉游来往多婵娟。
灯球灿烂若锦绣，王孙公子真神仙。
游人轇輵尚未绝，高楼顷刻生云烟。
是夜，节级蔡福分付教兄弟蔡庆看守着大牢：“我自回家看看便来。”方才进得家门，只见两个人闪将入来，前面那个军官打扮，后面仆者模样。灯光之下看时，蔡福认得是小旋风柴进，后面的已自是铁叫子乐和。蔡节级只认得柴进，便请入里面去，见成杯盘，随即管待。柴进道：“不必赐酒，在下到此有件紧事相央。卢员外、石秀全得足下相觑，称谢难尽。今晚小子欲就大牢里，趁此元宵热闹，看望一遭。望你相烦引进，休得推却。”蔡福是个公人，早猜了八分。欲待不依，诚恐打破城池，都不见了好处，又陷了老小一家人口性命。只得担着血海的干系，便取些旧衣裳教他两个换了，也扮做公人，换了巾帻，带柴进、乐和径奔牢中去了。
初更左右，王矮虎、一丈青、孙新、顾大嫂、张青、孙二娘三对儿村里夫妻，乔乔画画，装扮做乡村人，挨入在人丛里，便入东门去了。公孙胜带同凌振，挑着荆篓去城隍庙里廊下坐地。这城隍庙只在州衙侧边。邹渊、邹润挑着灯，在城中闲走。杜迁、宋万各推一辆车子，径到梁中书衙前，闪在人闹处。原来梁中书衙，只在东门里大街住。刘唐、杨雄各提着水火棍，身边都自有暗器，来州桥上两边坐定。燕青领了张顺，自从水门里入城，静处埋伏。都不在话下。
不移时，楼上鼓打二更。却说时迁挟着一个篮儿，里面都是硫黄、焰硝，放火的药头，篮儿上插几朵闹鹅儿，踅入翠云楼后，走上楼去。只见阁子内吹笙箫，动鼓板，掀云闹社，子弟们闹闹穰穰，都在楼上打哄赏灯。时迁上到楼上，只做卖闹鹅儿的，各处阁子里去看。撞见解珍、解宝拖着钢叉，叉上挂着兔儿，在阁子前踅。时迁便道：“更次到了，怎生不见外面动掸？”解珍道：“我两个方才在楼前，见探马过去，多管兵马到了。你只顾去行事。”
言犹未了，只见楼前都发起喊来，说道：“梁山泊军马到了西门外。”解珍分付时迁：“你自快去，我自去留守司前接应。”奔到留守司前，只见败残军马，一齐奔入城来，说道：“闻大刀吃劫了寨也。梁山泊贼寇引军都赶到城下。”李成正在城上巡逻，听见说了，飞马来到留守司前，教点军兵，分付闭上城门，守护本州。
却说王太守亲引随从百余人，长枷铁锁，在街镇压。听得报说这话，慌忙回留守司前。却说梁中书正在衙前闲坐，初听报说，尚自不甚慌。次后没半个更次，流星探马接连报来，吓得魂不附体，慌忙快叫备马。
说言未了，时迁就在翠云楼上点着硫黄焰硝，放一把火来。那火烈焰冲天，火光夺月，十分浩大。梁中书见了，急上得马。却待要去看时，只见两条大汉，推两辆车子，放在当路，便去取碗挂的灯来，望车子上点着，随即火起。梁中书要出东门时，两条大汉口称：“李应、史进在此！”手拈扑刀，大踏步杀来。把门官军吓得走了，手边的伤了十数个。杜迁、宋万却好接着出来，四个合做一处，把住东门。梁中书见不是头势，带领随行伴当，飞奔南门。南门传说道：“一个胖大和尚轮动铁禅杖，一个虎面行者掣出双戒刀，发喊杀入城来。”梁中书回马，再到留守司前，只见解珍、解宝手拈钢叉，在那里东撞西撞。急待回州衙，不敢近前。王太守却好过来，刘唐、杨雄两条水火棍齐下，打得脑浆迸流，眼珠突出，死于街前。虞候、押番各逃残生去了。梁中书急急回马奔西门，只听得城隍庙里火炮齐响，轰天震地。邹渊、邹润手拿竹竿，只顾就房檐下放起火来。南瓦子前，王矮虎、一丈青杀将来。孙新、顾大嫂身边掣出暗器，就那里协助。铜佛寺前，张青、孙二娘入去，扒上鳌山，放起火来。此时北京城内，百姓黎民，一个个鼠窜狼奔，一家家神号鬼哭。四下里十数处火光亘天，四方不辨。有诗为证：
回禄施威特降灾，熏天烈焰涨红埃。
黄童白叟皆惊惧，又被雄兵混杀来。
却说梁中书奔到西门，接着李成军马，急到南门城上，勒住马在鼓楼上看时，只见城下兵马摆满，旗号上写着“大将呼延灼”，火焰光中，抖擞精神，施逞骁勇，左有韩滔，右有彭玘，黄信在后，催动人马，雁翅一般横杀将来，随到门下。梁中书出不得城去，和李成躲在北门城下，望见火光明亮，军马不知其数，却是豹子头林冲，跃马横枪，左有马麟，右有邓飞，花荣在后催动人马，飞奔将来。再转东门，一连火把丛中，只见没遮拦穆弘，左有杜兴，右有郑天寿，三筹步军好汉当先，手拈扑刀，引领一千余人，杀入城来。梁中书径奔南门，舍命夺路而走。吊桥边火把齐明，只见黑旋风李逵，左有李立，右有曹正，李逵浑身脱剥，睁圆怪眼，咬定牙根，手搦双斧，从城濠里飞杀过来。李立、曹正，一齐俱到。李成当先，杀开条血路，奔出城来，护着梁中书便走。只见左手下杀声震响，火把丛中军马无数，却是大刀关胜，拍动赤兔马，手舞青龙刀，径抢梁中书。李成手举双刀，前来迎敌。那时李成无心恋战，拨马便走。左有宣赞，右有郝思文，两肋里撞来，孙立在后催动人马，并力杀来。正斗间，背后赶上小李广花荣，拈弓搭箭，射中李成副将，翻身落马。李成见了，飞马奔走。未及半箭之地，只见右手下锣鼓乱鸣，火光夺目，却是霹雳火秦明，跃马舞棍，引着燕顺、欧鹏，背后杨志，又杀将来。李成且战且走，折军大半，护着梁中书，冲路走脱。
话分两头，却说城中之事。杜迁、宋万去杀梁中书老小一门良贱。刘唐、杨雄去杀王太守一家老小。孔明、孔亮已从司狱司后墙爬将入去。邹渊、邹润却在司狱司前接住往来之人。大牢里柴进、乐和看见号火起了，便对蔡福、蔡庆道：“你弟兄两个见也不见？更待几时？”蔡庆在门边守时，邹渊、邹润早撞开牢门，大叫道：“梁山泊好汉全伙在此！好好送出卢员外、石秀哥哥来！”蔡庆慌忙报蔡福时，孔明、孔亮早从牢屋上跳将下来，不由他弟兄两个肯与不肯，柴进身边取出器械，便去开枷，放了卢俊义、石秀。柴进说与蔡福：“你快跟我去家中保护老小。”一齐都出牢门来。邹渊、邹润接着，合做一处。蔡福、蔡庆跟随柴进，来家中保全老小。卢俊义将引石秀、孔明、孔亮、邹渊、邹润五个弟兄，径奔家中来捉李固、贾氏。
却说李固听得梁山泊好汉引军马入城，又见四下里火起，正在家中有些眼跳，便和贾氏商量，收拾了一包金珠细软背了，便出门奔走。只听得排门一带都倒，正不知多少人抢将入来。李固和贾氏慌忙回身，便望里面开了后门，踅过墙边，径投河下来寻自家躲避处。只见岸上张顺大叫：“那婆娘走那里去！”李固心慌，便跳下船中去躲。却待攒入舱里，只见一个人伸出手来，劈角儿揪住，喝道：“李固，你认得我么？”李固听得是燕青的声音，慌忙叫道：“小乙哥！我不曾和你有甚冤仇，你休得揪我上岸！”岸上张顺早把那婆娘挟在肋下，拖到船边。燕青拿了李固，都望东门来了。
再说卢俊义奔到家中，不见了李固和那婆娘，且叫众人把应有家私金银财宝，都搬来装在车子上，往梁山泊给散。
却说柴进和蔡福到家中收拾家资老小，同上山寨。蔡福道：“大官人可救一城百姓，休教残害。”柴进见说，便去寻军师吴用。比及柴进寻着吴用，急传下号令去，休教杀害良民时，城中将及伤损一半。但见：
烟迷城市，火燎楼台。千门万户受灾危，三市六街遭患难。鳌山倒塌，红光影里碎琉璃；屋宇崩摧，烈焰火中烧翡翠。前街傀儡，顾不得面是背非；后巷清音，尽丢坏龙笙凤管。班毛老子，猖狂燎尽白髭须；绿发儿郎，奔走不收华盖伞。耍和尚烧得头焦额烂，麻婆子赶得屁滚尿流。踏竹马的暗中刀枪，舞鲍老的难免刃槊。如花仕女，人丛中金坠玉崩；玩景佳人，片时间星飞云散。瓦砾藏埋金万斛，楼台变作祝融墟。可惜千年歌舞地，翻成一片战争场。
当时天色大明，吴用、柴进在城内鸣金收军。众头领却接着卢员外并在秀，都到留守司相见。备说牢中多亏了蔡福、蔡庆弟兄两个看管，已逃得残生。燕青、张顺早把这李固、贾氏解来。卢俊义见了，且教燕青监下，自行看管，听候发落。不在话下。
再说李成保护梁中书出城逃难，又撞着闻达领着败残军马回来，合兵一处，投南便走。正走之间，前军发起喊来。却是混世魔王樊瑞，左有项充，右有李衮，三筹步军好汉，舞动飞刀飞枪，直杀将来。背后又是插翅虎雷横，将引施恩、穆春，各引一千步军，前来截住退路。却似虾儿逢巨浪，兔子遇豺狼。正是：狱囚遇赦重回禁，病客逢医又上床。毕竟梁中书一行人马怎地计结，且听下回分解。', '', '', '', NULL, '', 'indent', 1537289373, '5ba0b6cb9f54540039eecfb5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10300, '青玉案', NULL, 157, 33, 1, 2, '黄公绍', NULL, 10078, '57b9eb3bc4c9710061498d6e', '宋', 'ci', '词', 'http://baike.baidu.com/view/2841971.htm', '', '年年社日停针线，怎忍见、双飞燕？今日江城春已半，一身犹在，乱山深处，寂寞溪桥畔。
春衫著破谁针线？点点行行泪痕满。落日解鞍芳草岸，花无人戴，酒无人劝，醉也无人管。', '此词是一首抒写游子思乡情怀之词作。上片写游子在深山溪桥边，遥念家乡社日，看到双双飞燕而自伤孤单；下片写游子长期飘流在外，春衫已破，满是泪痕，却还不知归期。末尾连用三个“无人”，点出不仅赏花、饮酒都无心情，甚至醉了也受不到照顾。全词写尽孤身羁旅的凄凉况味。通篇缠绵凄恻，委婉含蓄。', '青玉案：词牌名之一，取于东汉张衡《四愁诗》：“美人赠我锦绣段，何以报之青玉案”一诗。又名《横塘路》、《西湖路》，双调六十七字，前后阕各五仄韵，上去通押。
社日：指立春以后的春社。
停针线：《墨庄漫录》说：“唐、宋社日妇人不用针线，谓之忌作。”唐张籍《吴楚词》：“今朝社日停针线。”
“春衫”两句：春衫已经穿破，这是谁做的针线活呢？这里的“谁针线”与“停针线”相呼应，由著破春衫想起那制作春衫的人，不觉凄然泪下，泪痕沾满了破旧的春衫。', '年年春社的日子妇女们停下针线，孤单的她怎忍看见，双飞双栖的春燕？今日江城春色已过去大半，我独自还羁身于乱山深处，寂寞地伫立在小溪畔。
春衫穿破了谁给我补缀针线？点点行行的泪痕洒满春衫。落日时分我解鞍驻马在芳草萋萋的河岸，虽有花枝却无人佩戴，虽有美酒却无人劝酒把盏，纵然醉了也无人照管。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e7515c6e67846a9206d0a", "shortContent": "这首无名氏的作品，写的是游子春日感怀。全篇即景抒情，纯用白描，却能达到“语淡而情浓，事浅而言深”的境地。\n春社，正当每年春分前后，燕子也在此时从南方飞回，再过半个月就是清明节。晏殊《破阵子》上片：“燕子来时新社，梨花落后清明。池上碧苔三四点，叶底黄鹂一两声，日长飞絮轻。”描绘的就是此际风光。春社又本来是古代祭社神（土地神）的节日，到处迎神赛会，十分热闹，妇女于此日都不做针线活计，结伴出外闲游，称之...", "authors": ["潘君昭"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec6167d0ac1145495e9b7", "shortContent": "这首无名氏的作品，写的是游子春日感怀。全篇即景抒情，纯用白描，却能达到“语淡而情浓，事浅而言深”的境地。\n春社，正当每年春分前后，燕子也在此时从南方飞回，再过半个月就是清明节。晏殊《破阵子》上片：“燕子来时新社，梨花落后清明。池上碧苔三四点，叶底黄鹂一两声，日长飞絮轻。”描绘的就是此际风光。春社又本来是古代祭社神（土地神）的节日，到处迎神赛会，十分热闹，妇女于此日都不做针线活计，结伴出外闲游，称之...", "authors": ["潘君昭"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059257e8f18b220af46212", "shortContent": "这首无名氏的作品，写的是游子春日感怀。全篇即景抒情，纯用白描，却能达到“语淡而情浓，事浅而言深”的境地。\n\n春社，正当每年春分前后，燕子也在此时从南方飞回，再过半个月就是清明节。晏殊《破阵子》上片：“燕子来时新社，梨花落后清明。池上碧苔三四点，叶底黄鹂一两声，日长飞絮轻。”描绘的就是此际风光。春社又本来是古代祭社神（土地神）的节日，到处迎神赛会，十分热闹，妇女于此日都不做针线活计，结伴出外闲游，称...", "authors": ["潘君昭"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f62c9ebcc6fbea1a2e6", "shortContent": "这是一首游子怀人词，选用《青玉案》这一词牌名，源出东汉张衡《四愁诗》“美人赠我锦绣缎，何以报之青玉案”之句，已经点明题旨，即回赠美人之意，以词寄托无限的思念。\n\n上阕主要写景。“年年社日停针线”句，说明了时间是社日期间，并透露出古代妇女在社日期间不事女红、不动针线的社会风俗信息。北宋张邦基所作《墨庄漫录》记载：“唐、宋社日妇人不用针线，谓之忌作。”又唐代张籍《吴楚歌词》云：“今朝社日停针线。”首句...", "authors": ["陈　瑶"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127051c305cf0801816f45", "shortContent": "这是一首游子怀人词，选用《青玉案》这一词牌名，源出东汉张衡《四愁诗》“美人赠我锦绣缎，何以报之青玉案”之句，已经点明题旨，即回赠美人之意，以词寄托无限的思念。\n\n上阕主要写景。“年年社日停针线”句，说明了时间是社日期间，并透露出古代妇女在社日期间不事女红、不动针线的社会风俗信息。北宋张邦基所作《墨庄漫录》记载：“唐、宋社日妇人不用针线，谓之忌作。”又唐代张籍《吴楚歌词》云：“今朝社日停针线。”首句...", "authors": ["陈瑶"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312723b9761253910e906f0", "shortContent": "这是一首游子怀人词，选用《青玉案》这一词牌名，源出东汉张衡《四愁诗》“美人赠我锦绣缎，何以报之青玉案”之句，已经点明题旨，即回赠美人之意，以词寄托无限的思念。\n上阕主要写景。“年年社日停针线”句，说明了时间是社日期间，并透露出古代妇女在社日期间不事女红、不动针线的社会风俗信息。北宋张邦基所作《墨庄漫录》记载：“唐、宋社日妇人不用针线，谓之忌作。”又唐代张籍《吴楚歌词》云：“今朝社日停针线”。首句起...", "authors": ["陈瑶"], "pressName": "崇文书局"}]', '贺裳：语淡而情浓，事浅而言深。
陈廷焯：不是风流放荡，只是一腔血泪耳。', 'indent', 1413386880, '57b93fa7a633bd00665f67e6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10301, '国风 · 邶风 · 击鼓', NULL, 440, 573, 1, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'shi', '诗', 'http://baike.baidu.com/view/3639270.htm', '', '击鼓其镗，踊跃用兵。
土国城漕，我独南行。
从孙子仲，平陈与宋。
不我以归，忧心有忡。
爰居爰处？爰丧其马？
于以求之？于林之下。
死生契阔，与子成说。
执子之手，与子偕老。
于嗟阔兮，不我活兮。
于嗟洵兮，不我信兮。', '全诗共五章，每章四句。前三章征人自叙出征情景，承接绵密，已经如怨如慕，如泣如诉；后两章描写战士间的互相勉励、同生共死，令人感动。此诗描写士卒长期征战之悲，无以复加。其中，描写战士感情的「死生契阔，与子成说。执子之手，与子偕老」，在后世也被用来形容夫妻情深。《诗经》是中国文学史上第一部诗歌总集。对后代诗歌发展有深远的影响，成为古典文学现实主义传统的源头。', '镗（tāng）：鼓声。其镗，即「镗镗」。
踊跃：双声连绵词，犹言鼓舞。
兵：武器，刀枪之类。
土国城漕：土，挖土；城，修城；国，指都城；漕：卫国的城市。
孙子仲：即公孙文仲，字子仲，卫国将领。
平：平定两国纠纷。谓救陈以调和陈宋关系。
陈、宋：诸侯国名。
不我以归：是不以我归的倒装，有家不让回。
有忡：忡忡，忧虑不安的样子。
「爰（yuán）居爰处？爰丧其马」句：哪里可以住，我的马丢在哪里。爰：哪里；丧，丧失，此处言跑失。
于以：在哪里。
契阔：聚散、离合的意思。契，合；阔，离。
成说（shuō）：约定、成议、盟约。
于嗟：叹词。
活：借为「佸（huó）」，相会。
洵：久远。
信：守信，守约。', '击起战鼓咚咚响，士兵踊跃练武忙。有的修路筑城墙，我独从军到南方。
跟随统领孙子仲，联合盟国陈与宋。不愿让我回卫国，致使我心忧忡忡。
何处可歇何处停？跑了战马何处寻？一路追踪何处找？不料它已入森林。
一同生死不分离，我们早已立誓言。让我握住你的手，同生共死上战场。
只怕你我此分离，没有缘分相会和。只怕你我此分离，无法坚定守信约。', '[{"bookId": "60fccb5034bfda01e0ea02ff", "bookTitle": "先秦诗鉴赏辞典（新一版）", "articleId": "610f37432cee9a0c24ee54ba", "shortContent": "《毛诗序》云：“《击鼓》，怨州吁也。卫州吁用兵暴乱，使公孙文仲将而平陈与宋。国人怨其勇而无礼也。”郑笺以《左传·隐公四年》州吁伐郑之事实之。姚际恒《诗经通论》以为“与经不合者六”，此实乃《春秋·宣公十二年》“宋师伐陈，卫人救陈”之事，在卫穆公时。今以为姚说较《毛序》为合理，姑从姚氏。\n第一章总言卫人救陈，平陈宋之难，叙卫人之怨。结云“我独南行”者，诗本以抒写个人愤懑为主，这是全诗的线索。诗的第三句...", "authors": ["郭晋稀"], "pressName": "上海辞书出版社"}, {"bookId": "627298aa34359466e82f44e0", "bookTitle": "诗经鉴赏辞典", "articleId": "63126fd7c26cbf3417f09408", "shortContent": "这是士兵厌战思归之诗。\n春秋时期，诸侯之间战争频仍。据《左传》记载，鲁宣公十二年，宋国攻打陈国，卫国出兵救援陈国。十三年，晋国不满意卫国救援陈国而出兵讨伐卫国。这可能就是此诗产生的历史背景。\n全诗五章。一章写应征入伍。诗一开头就笼罩紧张的备战气氛。战鼓咚咚响，士兵们正在跳跃着操练刀枪。有的人在国都兴建土木，有的人在漕邑修筑城墙，而主人公却出征南方。二章写随帅出征。士兵们随从统帅孙子仲，去平定陈国与...", "authors": [], "pressName": "崇文书局"}, {"bookId": "642074e9995d79753170c75a", "bookTitle": "诗经三百篇鉴赏辞典", "articleId": "645e203f5e6bb82b8ca947cc", "shortContent": "《毛诗序》云：“《击鼓》，怨州吁也。卫州吁用兵暴乱，使公孙文仲将而平陈与宋。国人怨其勇而无礼也。”郑笺以《左传·隐公四年》州吁伐郑之事实之。姚际恒《诗经通论》以为“与经不合者六”，此实乃《春秋·宣公十二年》“宋师伐陈，卫人救陈”之事，在卫穆公时。今以为姚说较《毛序》为合理，姑从姚氏。\n\n第一章总言卫人救陈，平陈宋之难，叙卫人之怨。结云“我独南行”者，诗本以抒写个人愤懑为主，这是全诗的线索。诗的第三...", "authors": ["郭晋稀"], "pressName": "上海辞书出版社"}]', '《毛诗序》：《击鼓》，怨州吁也。卫州吁用兵暴乱，使公孙文仲将而平陈与宋。国人怨其勇而无礼也。
孔颖达《诗疏》：怨者，情所恚恨。……经五章皆陈兵役之怨辞。……当往之时，不于我以告归期，不知早晚得还，故我忧心忡忡然，忧不得归也。
钱锺书《管锥编》：《笺》：「从军之士，与其伍约：‘死也、生也，相与处勤苦之中，我与子成相说爱之恩’。志在相存救也；‘俱老’者，庶几俱免于难」；《正义》：王肃云：「言国人室家之志，欲相与从；‘生死契阔’，勤苦而不相离，相与成男女之数，相扶持俱老。’」按《笺》甚迂谬，王说是也，而于「契阔」解亦未确。盖征人别室妇之词，恐战死而不能归，故次章曰：「不我以归，忧心有忡」。', 'center', 1445533628, '57b8f2e90a2b58005c91e327', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10302, '摊破浣溪沙', NULL, 396, 101, 2, 2, '李清照', NULL, 10043, '57b90879df0eea0063351b94', '宋', 'ci', '词', 'http://baike.baidu.com/view/2766438.htm', '', '病起萧萧两鬓华，卧看残月上窗纱。豆蔻连梢煎熟水，莫分茶。
枕上诗书闲处好，门前风景雨来佳。终日向人多酝藉，木犀花。', '这首词创作于李清照的晚年，是一首抒情词，最早收录在《乐府雅词》中。从此词的词情来看是李清照大病渐愈时所作。上阕描写黎明前病中室内生活，下阕描写白天里室外景物，作者抓住大病渐愈这一生活片段，从身心感受运笔，无论写病中生活细事，还是写病中所见景物，不受物所束，不为病所苦，无不流露出女词人病中清静闲适的心情；而身卧病床，鬓发斑白，卧看残月，煎药忌茶，又无不蕴含着病中孤苦哀愁的心境。此词笔致淡雅，情调直切，意境清朗，含蕴耐味。', '摊破浣溪沙：又名《山花子》。原为唐教坊曲名，后用为词牌。在唐五代时即将《浣溪沙》的上下片，各增添三个字的结句，成为“七、七、七、三”字格式，名曰《摊破浣溪沙》或《添字浣溪沙》。又因南唐李璟词“菡萏香销”之下片“细雨梦回”两句颇有名，故又有《南唐浣溪沙》之称。双调四十八字，平韵。
萧萧：这里形容鬓发华白稀疏的样子。
豆蔻：药物名，其性能行气、化湿、温中、和胃……豆蔻连梢：语见于张良臣《西江月》：“蛮江豆蔻影连梢。”熟：《天籁轩词选》、《历代诗余》作“热”。熟水：当时的一种药用饮料。陈元靓《事林广记》别集卷七之《豆蔻熟水》：“夏月凡造熟水，先倾百盏滚汤在瓶器内，然后将所用之物投入。密封瓶口，则香倍矣……白豆蔻壳拣净，投入沸汤瓶中，密封片时用之，极妙。每次用七个足矣。不可多用，多则香浊。”《百草正义》则说：“白豆蔻气味皆极浓厚，咀嚼久之，又有一种清澈冷洌之气，隐隐然沁入心脾。则先升后降，所以又能下气。”
分茶：杨万里《澹庵坐上观显上人分茶》诗有云：“分茶何似煎茶好，煎茶不似分茶巧”，由此可见，“分茶”是一种巧妙高雅的茶戏。其方法是用茶匙取茶汤分别注入盏中饮食。
书：《历代诗余》作“篇”字。
酝藉：宽和有涵容。《汉书·薛广德传》：“广德为人，温雅有酝藉。”
木犀花：即桂花。', '两鬓已经稀疏病后又添白发了，卧在床榻上看着残月照在窗纱上。将豆蔻煎成沸腾的汤水，不用强打精神分茶而食。靠在枕上读书是多么闲适，门前的景色在雨中更佳。整日陪伴着我，只有那深沉含蓄的木犀花。	', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74d3c6e67846a9206bb2", "shortContent": "此词写病后的生活和心境，是作者晚年流寓越中所作。\n久病初起的人，总想照照镜子，看看自己有了什么变化。此词亦即由此起笔。“病起”，说明曾经长期卧床不起，此刻已能下床活动了。“萧萧”是头发花白稀疏的样子。词中系相对病前而言，因为大病，头发白了许多，而且掉了不少。对镜端详，情况是不妙的，按说接下去应是再写病容或感慨，然而词中即刻打住，下句另起一意。这个处理极妙，意思似乎是说，头发已经那样，何必再去管它，...", "authors": ["王思宇"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5d7d635634aee3e9b15", "shortContent": "此词写病后的生活和心境，是作者晚年流寓越中所作。\n久病初起的人，总想照照镜子，看看自己有了什么变化。此词亦即由此起笔。“病起”，说明曾经长期卧床不起，此刻已能下床活动了。“萧萧”是头发花白稀疏的样子。词中系相对病前而言，因为大病，头发白了许多，而且掉了不少。对镜端详，情况是不妙的，按说接下去应是再写病容或感慨，然而词中即刻打住，下句另起一意。这个处理极妙，意思似乎是说，头发已经那样，何必再去管它，...", "authors": ["王思宇"], "pressName": "上海辞书出版社"}, {"bookId": "6277f84f8efdff05d7d6839b", "bookTitle": "李清照全集", "articleId": "6312258b77683d193300d3c3", "shortContent": "此词《天籁轩词选》调作《山花子》，《历代诗余》调作《南唐浣溪沙》。《花草粹编》等收为李清照词。当作于宋高宗绍兴二年（1132年）。词人才49岁，却经历了太多的人生坎坷。词表面上看显得从容淡泊，实则隐含了落寞无奈。此虽病中自慰之作，实为苦上加苦也。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645d1153a2a0d66afdbadb39", "bookTitle": "李清照诗词鉴赏辞典", "articleId": "6464ab0e5e6bb82b8cc45554", "shortContent": "此词写病后的生活和心境，是作者晚年流寓越中所作。\n\n久病初起的人，总想照照镜子，看看自己有了什么变化。此词亦即由此起笔。“病起”，说明曾经长期卧床不起，此刻已能下床活动了。“萧萧”是头发花白稀疏的样子。词中系相对病前而言，因为大病，头发白了许多，而且掉了不少。对镜端详，情况是不妙的，按说接下去应是再写病容或感慨，然而词中即刻打住，下句另起一意。这个处理极妙，意思似乎是说，头发已经那样，何必再去管它...", "authors": ["王思宇"], "pressName": "上海辞书出版社"}]', '', 'indent', 1363209253, '57b90318128fe10054c99d5b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10303, '阮郎归', NULL, 268, 267, 2, 3, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'http://baike.baidu.com/view/2259317.htm', '', '天边金掌露成霜，云随雁字长。绿杯红袖趁重阳，人情似故乡。
兰佩紫，菊簪黄，殷勤理旧狂。欲将沉醉换悲凉，清歌莫断肠。', '此词写於汴京，是重阳佳节宴饮之作。词中感喟身世，自抒怀抱，虽写抑郁之情，但并无绝望之意。全词写情波澜起伏，步步深化，由空灵而入厚重，音节从和婉到悠扬，适应感情的变化，整首词的意境是悲凉凄冷的。', '阮郎归：词牌名，又名《碧桃春》《醉桃源》等。《神仙记》载刘晨、阮肇入天台山采药，遇二仙女。留住半年，思归甚苦。既归则乡邑零落，经已十世。曲名本此，故作凄音。四十七字，前后片各四平韵。
金掌：汉武帝时在长安建章宫筑柏梁台，上有铜制仙人以手掌托盘，承接露水。此处以「金掌」借指国都，即汴京。即谓汴京已入深秋。
雁字：雁群飞行时排列成人字，有时排列成一字，故称雁字。
绿杯红袖：代指美酒佳人。
人情：风土人情。
「兰佩紫」两句：佩戴紫色兰花，头上插黄菊。屈原《离骚》中有「纫秋兰以为佩」。
理旧狂：重又显出从前狂放不羁的情态。', '天边的云彩有如仙人金掌承玉露。玉露凝成了白霜，浮云随着大雁南翔，排成一字长。举绿杯，舞红袖，趁着九九重阳，人情温厚似故乡。
身佩紫兰，头簪菊黄，急切切重温旧日的颠狂。想借一番沉醉换掉失意悲凉，清歌莫唱悲曲，一唱断人肠。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74ad5e272d4b2253bb2f", "shortContent": "晏幾道为晏殊幼子，是个赋性天真而又风流的贵公子，年青时候，酒筵歌席，良辰佳节，有过不少欢娱的朝暮。父亲死后，家道衰落，生活陷于贫困，对于人情世故、悲欢离合，有更多的体验，天真的心肠不免时时蒙受悲哀，因此，他的词作也由写得真率而逐渐走向深沉。\n这首《阮郎归》是晏幾道词情思深沉的代表作之一，题材还是属于酒筵歌席、佳节良辰的，但感情和早年的单纯看待欢乐不同了。词是写重阳节的。“天边金掌露成霜，云随雁字长...", "authors": ["陈祥耀"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b32cee9a0c24ed9e42", "shortContent": "晏几道为晏殊幼子，是个赋性天真而又风流的贵公子，年轻时候，酒筵歌席，良辰佳节，有过不少欢娱的朝暮。父亲死后，家道衰落，生活陷于贫困，对于人情世故、悲欢离合，有更多的体验，天真的心肠不免时时蒙受悲哀，因此，他的词作也由写得真率而逐渐走向深沉。\n这首《阮郎归》是晏几道词情思深沉的代表作之一，题材还是属于酒筵歌席、佳节良辰的，但感情和早年的单纯看待欢乐不同了。词是写重阳节的。“天边金掌露成霜，云随雁字长...", "authors": ["陈祥耀"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592534b56e213e6848037", "shortContent": "晏几道为晏殊幼子，是个赋性天真而又风流的贵公子，年青时候，酒筵歌席，良辰佳节，有过不少欢娱的朝暮。父亲死后，家道中落，生活陷于贫困，对于人情世故、悲欢离合，有更多的体验，天真的心肠不免时时蒙受悲哀，因此，他的词作也由写得真率而逐渐走向深沉。\n\n这首《阮郎归》是晏几道词情思深沉的代表作之一，题材还是属于酒筵歌席、佳节良辰的，但感情和早年的单纯看待欢乐不同了。词是写重阳节的。“天边金掌露成霜，云随雁字...", "authors": ["陈祥耀"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290c0", "shortContent": "此词写于词人客居汴京之时，是时当值重阳佳节，上片开篇便是一派气高清朗之深秋景象。“天边金掌”借汉代时长安帝京所建造的手托铜盘、承接露水的仙人像，词人想象着那仙人像上所承托的露水在这深秋之际恐怕也早已化霜了。此四字既含蓄地点出了深秋，又使词的开篇具有了时代变易的沧桑之感，甚有诗味。接句继言北雁南飞，天边的疏云仿佛被横空的雁群拉长，“随”字仿佛用得轻描淡写，然却直观地呈现出一种秋云易散之感，足见词人用...", "authors": ["梁晓琳"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127030c26cbf3417f09456", "shortContent": "这首词大概作于小山晚年居住在汴京时候，某一年参加了重阳节的宴会，有感而作了此篇。\n\n开篇交代时序。“露成霜”，时至重阳，因天冷，故露水已变成了霜，而北雁也正南飞。“天边金掌”，据《三辅黄图》记载，汉武帝曾在长安城建章宫造了一个神明台，台上又立了一个铜柱仙人，伸开手掌托着露盘，用来承接天上落下的露水，调和玉屑引之，目的是为了成仙。这里用这个典故，是用汉长安来借指宋汴京，就如“汉皇重色思倾国”，用汉皇...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312719b73206168b2e0234d", "shortContent": "这首词大概作于小山晚年居住在汴京时候，某一年参加了重阳节的宴会，有感而作了此篇。\n开篇交代时序。“露成霜”，时至重阳，因天冷，故露水已变成了霜。而北雁也正南飞。“天边金掌”，据《三辅黄图》记载，汉武帝曾在长安城建章宫造了一个神明台，台上又立了一个铜柱仙人，伸开手掌，用来承接天上落下的露水，调和玉屑引之，目的是为了成仙。这里用这个典故，是用汉长安来借指宋汴京，就如“汉皇重色思倾国”，用汉皇来借指唐玄...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "646791d5e49f46528ab22feb", "shortContent": "晏幾道为晏殊幼子，是个赋性天真而又风流的贵公子，年轻时候，酒筵歌席，良辰佳节，有过不少欢娱的朝暮。父亲死后，家道衰落，生活陷于贫困，对于人情世故、悲欢离合，有更多的体验，天真的心肠不免时时蒙受悲哀，因此，他的词作也由写得真率而逐渐走向深沉。\n\n这首《阮郎归》是晏幾道词情思深沉的代表作之一，题材还是属于酒筵歌席、佳节良辰的，但感情和早年的单纯看待欢乐不同了。词是写重阳节的。“天边金掌露成霜，云随雁字...", "authors": ["陈祥耀"], "pressName": "上海辞书出版社"}]', '夏敬观：叔原以贵人暮子，落拓一生，华屋山丘，身亲经历，哀丝豪竹，寓其微痛纤悲，宜其造诣又过于父。
况夔笙《蕙风词话·卷二》：「绿杯」二句，意已厚矣。「殷勤理旧狂」，五字三层意思：狂已旧矣，而理之，而殷勤理之，其狂若有甚不得已者。
陈匪石：此在《小山词》中，为最凝重深厚之作，与其他艳词不同。
唐季特《唐宋词简释》：此首起两句，言霜寒云薄，是深秋冷落景象，令人生悲。「绿杯」两句，言所以欲暂图沉醉，藉解悲凉者，一则因重阳佳节，一则因人情隆重。换头三句，言重阳行乐之实。「欲将」二字与「莫」字呼应，既将全词收束，更觉馀韵悠然。', 'indent', 1363209420, '57b8c827df0eea006333fdfc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10304, '临江仙', NULL, 830, 267, 5, 2, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'http://baike.baidu.com/view/2758867.htm', '', '梦后楼台高锁，酒醒帘幕低垂。去年春恨却来时，落花人独立，微雨燕双飞。
记得小蘋初见，两重心字罗衣。琵琶弦上说相思，当时明月在，曾照彩云归。', '这是怀旧忆人之作，所忆的是作者倾心爱慕、至老不能忘情的一位少女。此词代表了晏几道深婉精美的艺术风格。因怀人而梦，为解愁而酒。梦后酒醒，愈感孤寂，「高锁」、「低垂」显见孤寂之境，自然兜出一「恨」字，「春恨」又来，说明伤春怀人年复一年。如今更为深沉。末嵌入古人诗句，画出一幅暮春独立怀人图。「微雨」、「落花」，春意阑珊；「人独」、「燕双」，倍增怀思。浑化无迹，意象妙绝。「记得」转入所怀内容，即对小苹第一印象。美妙之打扮，含情之弹奏，月光下之飘然归去，尤以此三种细节，深印脑际，终身难忘。全篇由怀人之境之形，进而写所怀之人之事，情真、意婉、人美、语工，诸美荟萃，实罕其匹。这首词对偶工整，出语俊逸，写得曲折深婉。', '临江仙：双调小令，唐教坊曲名，后用为词牌。《乐章集》入「仙吕调」，《张子野词》入「高平调」。五十八字，上下片各三平韵。约有三格，第三格增二字。柳永演为慢曲，九十三字，前阕五平韵，后阕六平韵。
「梦后楼台高锁，酒醒帘幕低垂」句：眼前实景，「梦后」「酒醒」互文，犹晏殊《踏莎行·小径红稀》所云「一场愁梦酒醒时」；「楼台高锁」，从外面看，「帘幕低垂」，就里面说，也只是一个地方的互文，表示春来意与非常阑珊。许浑《客有卜居不遂薄游汧陇因题》：「楼台深锁无人到，落尽春风第一花。」
却来：又来，再来。
「去年春恨却来时，落花人独立，微雨燕双飞。」句：「去年春恨」是较近的一层回忆，独立花前，閒看燕子，比今年的醉眠愁卧，静掩房栊意兴还稍好一些。郑谷《杏花》：「小桃初谢后，双燕却来时。」「独立」与「双燕」对照，已暗逗怀人意。《五代诗话·卷七》引翁宏《宫词》「落花人独立，微雨燕双飞。」（翁诗全篇见《诗话总龟·前集卷十一》）以下直到篇末，是更远的回忆，即此篇的本事。
小蘋：当时歌女名。汲古阁本《小山词》作者自跋：「始时沈十二廉叔，陈十君宠家，有莲、鸿、蘋、云，品清讴娱客。每得一解，即以草授诸儿。」小莲、小蘋等名，又见他的《玉楼春》词中。
心字罗衣：未详。明·杨慎《词品·卷二》：「心字罗衣则谓心字香薰之尔，或谓女人衣曲领如心字。」说亦未必确。疑指衣上的花纹。「心」当是篆体，故可作为图案。「两重心字」，殆含「心心」义。李白《宫中行乐词八首》之一：「山花插鬓髻，石竹绣罗衣」，仅就两句字面，虽似与此句差远，但太白彼诗篇末云：「只愁歌舞散，化作彩云飞」，显然为此词结句所本，则「罗衣」云云盖亦相绾合。前人记诵广博，于创作时，每以联想的关系，错杂融会，成为新篇。此等例子正多，殆有不胜枚举者。
彩云：比喻美人。江淹《丽色赋》：「其少进也，如彩云出崖。」其比喻美人之取义仍从《高唐赋》「行云」来，屡见李白集中，如《感遇四首》之四「巫山赋彩云」、《凤凰曲》「影灭彩云断」及前引《宫中行乐词》。白居易《简简吟》：「彩云易散琉璃脆。」此篇「当时明月」「曾照彩云」，与诸例均合，寓追怀追昔之意，即作者自跋所云。', '梦醒只见高高楼台阁门紧锁，酒意消退但见帷帘重重低垂。去年春天惹起的恨恚来恼我，恰是落花纷坠斯人孤独伫立，细雨霏霏之中燕儿翩翩双飞。
依然清晰记得初次见到小蘋，穿着绣有两重心字的小衣衫。拨弹琵琶舞弦诉说相思滋味，当时月光是那样的皎洁如玉，她像一朵美丽的彩云翩然归去。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74ab7d0ac1145494bb5a", "shortContent": "这是晏幾道词的代表作。在内容上，它写的是小山词中最习见的题材，对过去欢乐生活的追忆，并寓有“微痛纤悲”的身世之感；在艺术上，它表现了小山词特有的深婉沉着的风格。可以说，这首词代表了作者在词的艺术上的最高成就，堪称婉约词中的绝唱。\n本词当是别后怀思歌女小蘋之作。上片用两个六言句对起。午夜梦回，只见四周的楼台已闭门深锁；宿酒方醒，那重重的帘幕正低垂到地。“梦后”、“酒醒”二句互文，写眼前的实景。对偶极...", "authors": ["陈永正"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b10f8fda5565060479", "shortContent": "这是晏几道词的代表作。在内容上，它写的是《小山词》中最习见的题材，对过去欢乐生活的追忆，并寓有“微痛纤悲”的身世之感；在艺术上，它表现了《小山词》特有的深婉沉着的风格。可以说，这首词代表了作者在词的艺术上的最高成就，堪称婉约词中的绝唱。\n本词当是别后怀思歌女小蘋之作。上片用两个六言句对起。午夜梦回，只见四周的楼台已闭门深锁；宿酒方醒，那重重的帘幕正低垂到地。“梦后”、“酒醒”二句互文，写眼前的实景...", "authors": ["陈永正"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592534b56e213e684802f", "shortContent": "这是晏几道词的代表作。在内容上，它写的是《小山词》中最习见的题材，对过去欢乐生活的追忆，并寓有“微痛纤悲”的身世之感；在艺术上，它表现了《小山词》特有的深婉沉着的风格。可以说，这首词代表了作者在词的艺术上的最高成就，堪称婉约词中的绝唱。\n\n本词当是别后怀思歌女小\"之作。上片用两个六言句对起。午夜梦回，只见四周的楼台已闭门深锁；宿酒方醒，那重重的帘幕正低垂到地。“梦后”“酒醒”二句互文，写眼前的实景...", "authors": ["陈永正"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3d73206168b2e020cf", "shortContent": "在词史上，小山词开创了宋词的新局面。在创作风格上，晏几道继承了其父清新脱俗、清丽婉转的词风，但个性更为狂放和无所顾忌，正如黄庭坚在《小山集序》中所说：“磊隗权其，疏于顾忌。”\n该词由景入情，春日的风景触发词人回忆起与小苹初见的情景，抒发了词人孤寂痛苦的心情。上阕词人从梦中醒来，发现楼台依旧紧锁；醉意逐渐清醒，看见帘幕仍然低垂着，原来没有佳人造访。然后他独自一人伫立门前，看着庭院中的花开花落、微雨中...", "authors": ["吕青霞"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702f7ccdb86c49f29200", "shortContent": "在词史上，小山词开创了宋词的新局面。在创作风格上，晏几道继承了其父清新脱俗、清丽婉转的词风，但个性更为狂放和无所顾忌，正如黄庭坚在《小山集序》中所说：“磊隗权其，疏于顾忌。”\n\n该词由景入情，春日的风景触发词人回忆起与小苹初见的情景，抒发了词人孤寂痛苦的心情。上阕词人从梦中醒来，发现楼台依旧紧锁；醉意逐渐清醒，看见帘幕仍然低垂着，原来没有佳人造访。然后他独自一人伫立门前，看着庭院中的花开花落、微雨...", "authors": ["吕青霞"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312719b73206168b2e02345", "shortContent": "在词史上，小山词开创了宋词的新局面。在创作风格上，晏几道继承了其父清新脱俗、清丽婉转的词风，但个性更为狂放和无所顾忌，正如黄庭坚在《小山集序》中所说：“磊隗权其，疏于顾忌。”\n该词由景入情，春日的风景触发词人回忆起与小蘋初见的情景，抒发了词人孤寂痛苦的心情。上阕词人从梦中醒来，发现楼台依旧紧锁；醉意逐渐清醒，看见帘幕仍然低垂着，原来没有佳人造访。然后他独自一人伫立门前，看着庭院中的花开花落、微雨中...", "authors": ["吕青霞"], "pressName": "崇文书局"}, {"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "646790a25b7b0d4f451d9348", "shortContent": "这是晏幾道词的代表作。在内容上，它写的是《小山词》中最习见的题材，对过去欢乐生活的追忆，并寓有“微痛纤悲”的身世之感；在艺术上，它表现了《小山词》特有的深婉沉着的风格。可以说，这首词代表了作者在词的艺术上的最高成就，堪称婉约词中的绝唱。\n\n本词当是别后怀思歌女小[插图]之作。上片用两个六言句对起。午夜梦回，只见四周的楼台已闭门深锁；宿酒方醒，那重重的帘幕正低垂到地。“梦后”、“酒醒”二句互文，写眼...", "authors": ["陈永正"], "pressName": "上海辞书出版社"}]', '宋·杨万里《诚斋诗话》：晏叔原云：「落花人独立，微雨燕双飞。」可谓好色而不淫矣。
淸·谭献评《词辨·卷一》：名句（「落花」二句）千古不能有二。结笔，所谓柔厚在此。
梁启超《艺蘅馆词选·乙卷》：康南海（有为）云：起二句，纯是华严境界。', 'indent', 1418828733, '57aca1e52e958a00543d91b0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (45932, '赠叶洞春画葡萄', NULL, 0, 766, 0, 1, '陈普', NULL, 11120, '5858e628128fe1006dcc2033', '元', 'shi', '诗', NULL, NULL, '引蔓牵藤寸管头，扶骊剔蚌出风流。
三千龙女抛珠佩，一个儒生拥碧油。
莫是前生封即墨，便堪作酒博青州。
齐奴倘会清妍意，免得红裙逐翠楼。', NULL, NULL, NULL, NULL, NULL, 'center', 1525432808, '585ceb858d6d810065dbc5ad', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (47658, '题荔枝', NULL, 1, 472, 0, 1, '陶宗仪', NULL, 11135, '5858e62c128fe1006b87c8b5', '元', 'shi', '诗', NULL, NULL, '大唐置驿贡遐方，火齐虬珠裹蔗浆。
博得玉环才一笑，教坊曲奏荔枝香。', NULL, NULL, NULL, NULL, NULL, 'center', 1525432009, '585cecfe8d6d810065dbd184', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10305, '鹧鸪天', NULL, 870, 267, 4, 3, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'http://baike.baidu.com/view/4890678.htm', '', '彩袖殷勤捧玉钟，当年拚却醉颜红。舞低杨柳楼心月，歌尽桃花扇底风。
从别后，忆相逢，几回魂梦与君同。今宵剩把银釭照，犹恐相逢是梦中。', '这首词描写了与久别佳人重逢时犹疑是梦的惊喜和追忆别后对佳人苦苦的相思之情。上阕写往日的欢聚。「彩袖」代指佳人，「当年」点明是往事。「殷勤」、「拚却」，见情意之笃。「舞低」二句，晁补之称其词「风度闲雅，自是一家」。月被舞低、风被歌尽，情绪之高、兴致之浓，可想而知。下阕写当今的重逢。久忆成梦，几回以梦为真，而今重逢，又不免疑真为梦，往昔只盼梦中相逢，今宵唯恐相逢是梦。曲折深婉，乍喜乍惊。往日欢情之浓，衬叠出相忆之深，愈见重逢难得。全词言情婉丽，文心曲妙，空灵雅致，足见小山本色。', '鹧鸪天：词牌名，又名《思佳客》，五十五字。此词黄升《花庵词选》题作《佳会》。
彩袖：代指穿彩衣的歌女。
玉钟：古时指珍贵的酒杯，是对酒杯的美称。
拚（pàn）却：甘愿，不顾惜。却，语气助词。
「舞低杨柳楼心月，歌尽桃花扇底风。」句：歌女舞姿曼妙，直舞到挂在杨柳树梢照到楼心的一轮明月低沉下去；歌女清歌婉转，直唱到扇底儿风消歇（累了停下来），极言歌舞时间之久。桃花扇，歌舞时用作道具的扇子，绘有桃花。歌扇风尽，形容不停地挥舞歌扇。这两句是《小山词》中的名句。「低」字为使动用法，使……低。
同：聚在一起。。
剩：通「尽（jǐn）」，只管。
把：持、握。
银釭（gāng）：银质的灯台，代指灯。', '当年首次相逢你酥手捧杯殷勤劝酒频举玉盅，是那么地温柔美丽和多情，我开怀畅饮喝得酒醉脸通红。翩翩起舞从月上柳梢的傍晚时分开始，直到楼顶月坠楼外树梢的深夜，我们尽情地跳舞歌唱，筋疲力尽累到无力再把桃花扇摇动。
自从那次离别后，我总是怀念那美好的相逢，多少回梦里与你相拥。今夜里我举起银灯把你细看，还怕这次相逢又是在梦中。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74ab03048e64fbd8931b", "shortContent": "这首词是晏幾道与一个相熟的女子久别重逢之作。这个女子可能是晏幾道自撰《小山词序》中所提到的他的朋友沈廉叔、陈君龙家歌女莲、鸿、蘋、云诸人中的一个。晏幾道经常在这两位朋友家中饮酒听歌，与这个女子是很熟的而且有相当爱惜之情的，离别之后，时常思念，哪知道现在忽然不期而重遇，又惊又喜，所以作了这首词。上半阕写当年相聚时欢乐之况，下半阕写今日重逢时惊喜之情。\n上半阕叙写当年欢聚之时，歌女殷勤劝酒，自己拚命痛...", "authors": ["缪", "钺"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b203572034f65a8b2e", "shortContent": "这首词是晏几道与一个相熟的女子久别重逢之作。这个女子可能是晏几道自撰《小山词序》中所提到的他的朋友沈廉叔、陈君龙家歌女莲、鸿、蘋、云诸人中的一个。晏几道经常在这两位朋友家中饮酒听歌，与这个女子是很熟的而且有相当爱惜之情的，离别之后，时常思念，哪知道现在忽然不期而重遇，又惊又喜，所以作了这首词。上半阕写当年相聚时欢乐之况，下半阕写今日重逢时惊喜之情。\n上半阕叙写当年欢聚之时，歌女殷勤劝酒，自己拼命痛...", "authors": ["缪", "钺"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592534b56e213e6848032", "shortContent": "这首词是晏几道与一个相熟的女子久别重逢之作。这个女子可能是晏几道自撰《小山词序》中所提到的他的朋友沈廉叔、陈君龙家歌女莲、鸿、\"、云诸人中的一个。晏几道经常在这两位朋友家中饮酒听歌，与这个女子是很熟的而且有相当爱惜之情的，离别之后，时常思念，哪知道现在忽然不期而重遇，又惊又喜，所以作了这首词。上半阕写当年相聚时欢乐之况，下半阕写今日重逢时惊喜之情。\n\n上半阕叙写当年欢聚之时，歌女殷勤劝酒，自己拼命...", "authors": ["缪　钺"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290b8", "shortContent": "本词为小晏词中的名作，陈廷焯称赞此词“婉转缠绵，情深一往，丽而有则，耐人寻味”（《白雨斋词话》）。\n上片是对往事的追忆，当时相逢之境况犹历历在目。“彩袖殷勤捧玉钟”，“彩袖”借言佳人，说得含蓄深婉。佳人捧盅，殷勤劝酒，推杯接盏间，难免使人心神荡漾。“当年拼却醉颜红”的“拼却”二字可知词人为知己者饮的心意，为伊无所怜惜地痛饮一场，以此回报佳人的钟情。“殷勤”与“拼却”相照应，词人与知己之间情意相投跃...", "authors": ["梁晓琳"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127030c26cbf3417f09453", "shortContent": "本词为小晏词中的名作，陈廷焯称赞此词“婉转缠绵，情深一往，丽而有则，耐人寻味”（《白雨斋词话》）。\n\n上片是对往事的追忆，当时相逢之境况犹历历在目。“彩袖殷勤捧玉钟”，“彩袖”借言佳人，说得含蓄深婉。佳人捧盅，殷勤劝酒，推杯接盏间，难免使人心神荡漾。“当年拼却醉颜红”的“拼却”二字可知词人为知己者饮的心意，为伊无所怜惜地痛饮一场，以此回报佳人的钟情。“殷勤”与“拼却”相照应，词人与知己之间情意相投...", "authors": ["梁晓琳"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312719b73206168b2e02347", "shortContent": "本词为小晏词中的名作，陈廷焯称赞此词“婉转缠绵，情深一往，丽而有则，耐人寻味”（《白雨斋词话》）。\n上片是对往事的追忆，当时相逢之境况犹历历在目。“彩袖殷勤捧玉钟”，“彩袖”借言佳人，说得含蓄深婉。佳人捧盅，殷勤劝酒，推杯接盏间，难免使人心神荡漾。“当年拼却醉颜红”的“拼却”二字可知词人为知己者饮的心意，为伊无所怜惜地痛饮一场，以此回报佳人的钟情。“殷勤”与“拼却”相照应，词人与知己之间情意相投跃...", "authors": ["梁晓琳"], "pressName": "崇文书局"}, {"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "646790e97f27182da360bbdb", "shortContent": "这首词是晏幾道与一个相熟的女子久别重逢之作。这个女子可能是晏幾道自撰《小山词序》中所提到的他的朋友沈廉叔、陈君龙家歌女莲、鸿、[插图]、云诸人中的一个。晏幾道经常在这两位朋友家中饮酒听歌，与这个女子是很熟的而且有相当爱惜之情的，离别之后，时常思念，哪知道现在忽然不期而重遇，又惊又喜，所以作了这首词。上半阕写当年相聚时欢乐之况，下半阕写今日重逢时惊喜之情。\n\n上半阕叙写当年欢聚之时，歌女殷勤劝酒，自...", "authors": ["缪钺"], "pressName": "上海辞书出版社"}]', '北宋·赵令畤《侯鲭录·卷七》：晁无咎（即晁补之）言：「叔原不蹈袭人语，而风调闲雅，自是一家。如「舞低杨柳楼心月，歌尽桃花扇底风」，自可知此人不生在三家村中也。
北宋·胡仔《渔隐丛话前集·卷五十九》引雪浪斋日记：晏叔原工小词。「舞低杨柳楼心月，歌尽桃花扇底风」，不愧六朝宫掖体。
明·刘体仁《七颂堂词绎》：「夜阑更秉烛，相对如梦寐」，叔原（即晏几道）云：「今宵剩把银釭照，犹恐相逢是梦中。」此诗与词之分疆也。
明·沈际飞《草堂诗馀正集》：末二句惊喜俨然。
清·陈廷焯《白雨斋词话》：下半阕曲折深婉，自有艳词，更不得不让伊独步。
民国·陈匪石《宋词举》：「从别后，忆相逢」六字，颇见回环之妙笔。「几回魂梦与君同」，承上启下，措语已妙绝无伦。
当代·唐圭璋《唐宋词简释》：「剩把」与「犹恐」四字呼应，则惊喜俨然，变质直为婉转空灵矣。上言梦似真，今言真如梦，文心曲折微妙。', 'indent', 1418828997, '57b926c7a633bd00665e8e80', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10306, '国风 · 周南 · 关雎', NULL, 5929, 573, 2, 14, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'shi', '诗', 'http://baike.baidu.com/view/3614183.htm', '', '关关雎鸠，在河之洲。
窈窕淑女，君子好逑。
参差荇菜，左右流之。
窈窕淑女，寤寐求之。
求之不得，寤寐思服。
悠哉悠哉，辗转反侧。
参差荇菜，左右采之。
窈窕淑女，琴瑟友之。
参差荇菜，左右芼之。
窈窕淑女，钟鼓乐之。', '此诗是《诗经》中的第一篇诗歌，通常认为是一首描写男女恋爱的情歌。此诗在艺术上巧妙地采用了「兴」的表现手法。首章以雎鸟相向合鸣，相依相恋，兴起淑女陪君子的联想。以下各章，又以采荇菜这一行为兴起主人公对女子疯狂的相思与追求。全诗语言优美，善于运用双声、叠韵和重叠词，增强了诗歌的音韵美和写人状物、拟声传情的生动性。', '关关：象声词，雌雄二鸟相互应和的叫声。
雎鸠（jūjiū）：一种水鸟名，即王鴡。
洲：水中的陆地。
窈窕（yǎotiǎo）淑女：贤良美好的女子。窈窕，身材体态美好的样子。窈，深邃，喻女子心灵美；窕，幽美，喻女子仪表美。淑，好，善良。
好逑（hǎoqiú）：好的配偶。逑，「仇」的假借字，匹配。
参差：长短不齐的样子。
荇（xìng）菜：水草类植物。圆叶细茎，根生水底，叶浮在水面，可供食用。
寤寐（wùmèi）：醒和睡。指日夜。寤，醒觉。寐，入睡。又，马瑞辰《毛诗传笺注通释》说：「寤寐，犹梦寐。」也可通。
思服：思念。服，想。《毛传》：「服，思之也。」
悠哉（yōuzāi）悠哉：意为「悠悠」，就是长。这句是说思念绵绵不断。悠，感思。见《尔雅·释诂》郭璞注。哉，语气助词。悠哉悠哉，犹言「想念呀，想念呀」。
辗转反侧：翻覆不能入眠。辗，古字作展。展转，即反侧。反侧，犹翻覆。
琴瑟友之：弹琴鼓瑟来亲近她。琴、瑟，皆弦乐器。琴五或七弦，瑟二十五或五十弦。友：用作动词，此处有亲近之意。这句说，用琴瑟来亲近「淑女」。
左右芼（mào）之：时而向左、时而向右地择取荇菜。这里是以勉力求取荇菜，隐喻「君子」努力追求「淑女」。芼，用手指或指尖采摘；之，指荇菜。
钟鼓乐之：用钟奏乐来使她快乐。乐，使动用法，使……快乐。', '在那河中的小沙洲上，一对雎鸠鸟相互啼鸣唱和。美丽娴静的女子，是男子渴望的好配偶。
参差不齐的荇菜，从左到右去捞它。美丽娴静的女子，小伙子日夜都想追求你。
追求不到，他在睡梦中都在思念。绵绵不尽的思念，翻来覆去难以入眠。
参差不齐的荇菜，少女左右来回采摘。美丽娴静的女子，小伙子要弹着琴瑟来亲近你。
参差不齐的荇菜，少女翩翩来回采摘，美丽娴静的女子，小伙子要敲着鼓来取悦你。', '[{"bookId": "60fccb5034bfda01e0ea02ff", "bookTitle": "先秦诗鉴赏辞典（新一版）", "articleId": "610f37402cee9a0c24ee54b0", "shortContent": "《关雎》这首短小的诗篇，在中国文学史上占据着特殊的位置。它是《诗经》的第一篇，而《诗经》是中国文学最古老的典籍。虽然从性质上判断，一些神话故事产生的年代应该还要早些，但作为书面记载，却是较迟的事情。所以差不多可以说，当读者翻开中国文学的历史，首先遇到的就是《关雎》。\n当初编纂《诗经》的人，在诗篇的排列上是否有某种用意呢？这已不得而知。但至少后人的理解，并不认为《关雎》是随便排列在首位的。孔子《论语...", "authors": ["骆玉明"], "pressName": "上海辞书出版社"}, {"bookId": "627298aa34359466e82f44e0", "bookTitle": "诗经鉴赏辞典", "articleId": "63126fc8c9ebcc6fbea1a333", "shortContent": "这是贵族青年男女的恋歌。\n\n《关雎》列为《诗经》之首，足见其地位的重要。古人认为，夫妇为人伦之始，天下一切道德的完善，都必须以夫妇之德为基础。这恐怕就是如此编排的用意吧。\n\n全诗四章。一章以河洲上对对和鸣的鱼鹰，兴比淑女是君子的好配偶。此章统摄全诗，为下面的描写做了铺垫。二章以采摘长短不齐的荇菜，兴比君子对淑女的追求。“求”是全诗的关键字眼。君子因求之不得，故日夜思念，倍觉长夜难熬，卧躺床上，翻来...", "authors": [], "pressName": "崇文书局"}, {"bookId": "642074e9995d79753170c75a", "bookTitle": "诗经三百篇鉴赏辞典", "articleId": "645ceae0ec56251f2eea9afe", "shortContent": "《关雎》这首短小的诗篇，在中国文学史上占据着特殊的位置。它是《诗 经》的第一篇，而《诗经》是中国文学最古老的典籍。虽然从性质上判断，一些 神话故事产生的年代应该还要早些，但作为书面记载，却是较迟的事情。所以 差不多可以说，你翻开中国文学的历史，首先遇到的就是《关雎》。\n\n当初编纂《诗经》的人，在诗篇的排列上是否有某种用意呢?这已不得而 知。但至少后人的理解，并不认为《关雎》是随便排列在首位的。孔子...", "authors": ["骆玉明"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文(小学、初中)", "articleId": "6471e82d30675327e1c0aaaa", "shortContent": "《关雎》这首短小的诗篇，在中国文学史上占据着特殊的位置。它是《诗经》的第一篇，而《诗经》是中国文学最古老的典籍。虽然从性质上判断，一些神话故事产生的年代应该还要早些，但作为书面记载，却是较迟的事情。所以差不多可以说，当读者翻开中国文学的历史，首先遇到的就是《关雎》。\n《关雎》的内容其实很单纯，是写一个“君子”对“淑女”的追求，写他得不到“淑女”时心里苦恼，翻来覆去睡不着觉；得到了“淑女”就很开心，...", "authors": ["骆玉明"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b5927b1076d586378e23b", "shortContent": "《关雎》是《诗经》，也是《国风》的第一首诗歌，诗中表达的是对于自己心仪的女子强烈的爱情追求。孔子的八字评语“乐而不淫，哀而不伤（《论语·八佾》）”很是恰当。可为什么汉代以来的学者要赋予这首情歌那么多的教化内涵呢？\n\n在我们看来，男女相悦首先是“人道之大伦”，夫妇之道是“人伦之始”。当然，这也是孔子把它列为《诗经》之首的原因之一；其次，“关雎”出自“周南”，周国本在雍州境内岐山之阳，后稷十三世孙古公...", "authors": ["张传友"], "pressName": "上海辞书出版社"}]', '《毛诗序》：《关雎》，后妃之德也，《风》之始也，所以风天下而正夫妇也。
郑玄《毛诗传笺》：后妃觉寐则常求此贤女，欲与之共己职也。
孔颖达《毛诗正义》：此诗之作，主美后妃进贤。思贤才，谓思贤才之善女。
司马迁《史记·十二诸侯年表》：周道缺，诗人本之衽席，《关雎》作。仁义陵迟，《鹿鸣》刺焉。
孔子《论语》：《关雎》乐而不淫，哀而不伤。
朱熹《诗集传》：孔子曰「《关雎》乐而不淫，哀而不伤」，愚谓此言为此诗者，得其性情之正，声气之和也。
余冠英《诗经选》：这诗写男恋女之情。
陈子展《诗三百解题》：《关雎》，乐得淑女以配君子之诗。
赵浩如《诗经选译》：这是一首民间的情歌，用兴起的艺术手法，写青年男子思恋少女。', 'center', 1415639281, '57b1e1205bbb500062df7633', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10308, '己亥杂诗 · 其五', NULL, 481, 723, 2, 15, '龚自珍', NULL, 10080, '57b9b97d79bc4400639c3e56', '清', 'shi', '诗', 'http://baike.baidu.com/view/3677257.htm', '', '浩荡离愁白日斜，吟鞭东指即天涯。
落红不是无情物，化作春泥更护花。', '这首诗是清代诗人龚自珍写的组诗《己亥杂诗》中的第五首，写诗人离京的感受。全诗分前后两部分，前两句为第一部分，后两句为第二部分。在第一部分里，诗人以天涯、日暮、落花写出一片浩荡的离愁，以落花自况，赋予自己的身世之感；第二部分以落花为过渡，从落花、春泥展开联想，把自己变革现实的热情和不甘寂寞消沉的意志移情落花，然后代落花立言，向春天宣誓，倾吐了深曲的旨意。全诗意象单纯，而情景浑成，比兴无端，而心迹昭然，短短二十八字，展示了诗人博大的胸怀，揭示了一种难能可贵的生命价值观，具有涵包天地的思想和感情容量，堪称定庵诗的压卷之作。', '浩荡离愁：离别京都的愁思浩如水波，也指作者心潮不平。浩荡：无限。
吟鞭：诗人的马鞭。东指：东方故里。天涯：指离别京都的距离。
落红：落花。花朵以红色者为尊贵，因此落花又称为落红。
花：比喻国家。即：到。', '浩浩荡荡的离别愁绪向着日落西斜的远处延伸，离开北京，马鞭向东一挥，感觉就是人在天涯一般。我辞官归乡，有如从枝头上掉下来的落花，但它却不是无情之物，化成了春天的泥土，还能起着培育下一代的作用。', '[{"bookId": "60d939cea06dc908f045ad24", "bookTitle": "元明清诗鉴赏辞典（新一版）", "articleId": "610e8d1f2e6a6b501f95a6a8", "shortContent": "《红楼梦》中黛玉葬花词云：“依今葬花人笑痴，他年葬侬知是谁？”林黛玉面对满地落花，不禁联想到自己的红颜薄命。无独有偶，一代才人龚自珍也是以落花自喻身世，在《己亥杂诗》（其五）中吟出了挚切深情的诗句。\n龚自珍于道光十九年己亥（1839）离开京都辞官南归。正值暮春时节，万花纷谢，残红满地。这景象惹起诗人一股浓浓的离情，他情不自禁地在马上唱出了上面这首歌。“浩荡离愁白日斜”，诗人心中的离愁啊，多么深广，...", "authors": ["铁", "明"], "pressName": "上海辞书出版社"}, {"bookId": "645bb7088258810260d4d543", "bookTitle": "元明清诗三百首鉴赏辞典", "articleId": "6460b53de49f46528a94c607", "shortContent": "《红楼梦》中黛玉葬花词云：“侬今葬花人笑痴，他年葬侬知是谁？”林黛玉面对满地落花，不禁联想到自己的红颜薄命。无独有偶，一代才人龚自珍也是以落花自喻身世，在《己亥杂诗》（其五）中吟出了挚切深情的诗句。\n\n龚自珍于道光十九年己亥（1839）离开京都辞官南归。正值暮春时节，万花纷谢，残红满地。这景象惹起诗人一股浓浓的离情，他情不自禁地在马上唱出了上面这首歌。“浩荡离愁白日斜”，诗人心中的离愁啊，多么深广...", "authors": ["铁明"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "647202a282772d4594282f98", "shortContent": "龚自珍于道光十九年己亥(1839)离开京都辞官南归。正值暮春时节，万花纷谢，残红满地。这景象惹起诗人一股浓浓的离情，他情不自禁地在马上唱出了上面这首歌。\n从这首诗的头两句，我们不难想象当时诗人悄然出京的情景。作者曾自述此次离京时“不携眷属兼从，雇两车，以一车自载，一车载文集百卷出都。”再联系到这两句诗的描写可知诗人是只身骑着马走出北京城的，这时已“白日斜”了，他满怀着“浩荡离愁”，在那北方郊野的大...", "authors": ["铁明"], "pressName": "上海辞书出版社"}]', '', 'center', 1423174774, '57b9107079bc44005b9f1c68', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10309, '己亥杂诗', NULL, 330, 723, 1, 4, '龚自珍', NULL, 10080, '57b9b97d79bc4400639c3e56', '清', 'shi', '诗', 'http://baike.baidu.com/view/3445717.htm', '', '九州生气恃风雷，万马齐喑究可哀。
我劝天公重抖擞，不拘一格降人才。', '此诗是《己亥杂诗》中的第一百二十五首。这首诗以祈祷天神的口吻，呼唤着风雷般的变革，以打破清王朝束缚思想、扼杀人才造成的死气沉沉的局面，表达了作者解放人才，变革社会，振兴国家的愿望。', '九州：中国的别称之一。分别是：冀州、兖州、青州、徐州、扬州、荆州、梁州、雍州和豫州。王昌龄《放歌行》：「清乐动千门，皇风被九州」。
生气：生气勃勃的局面。
恃（shì）：依靠。
万马齐喑（yīn）：比喻社会政局毫无生气。喑，沉默、不说话。
天公：造物主。
抖擞：振作，奋发。
降：降生、降临。
人才：一作“人材”。', '只有狂雷炸响般的巨大力量才能使中国大地发出勃勃生机，然而社会政局毫无生气终究是一种悲哀。
我奉劝上天要重新振作精神，不要拘泥一定规格以降下更多的人才。', '[{"bookId": "60d939cea06dc908f045ad24", "bookTitle": "元明清诗鉴赏辞典（新一版）", "articleId": "610e8d1f0f8fda5565053bba", "shortContent": "龚自珍的时代是一个山雨欲来风满楼的时代，他逝世前一年就发生鸦片战争了。正是这样的时代，产生了这位近代史上启蒙思想家。他意识到封建的闭关锁国政策行不通了，帝国主义的侵略更加暴露出封建主义衰朽没落的本质。龚自珍敏感到了这腐败的气息，他以惊世骇俗的才华，起而议政“医国”，宣传变革。他的思想，他的词锋，他的离经叛道的精神，像光照天地的出鞘长剑，震惊了醉生梦死中的清朝廷权贵。终因“动触时忌”，他于道光十九年...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "645bb7088258810260d4d543", "bookTitle": "元明清诗三百首鉴赏辞典", "articleId": "6460b5a55fc8182fe98d625f", "shortContent": "龚自珍的时代是一个山雨欲来风满楼的时代，他逝世前一年就发生鸦片战争了。正是这样的时代，产生了这位近代史上启蒙思想家。他意识到封建的闭关锁国政策行不通了，帝国主义的侵略更加暴露出封建主义衰朽没落的本质。龚自珍敏感到了这腐败的气息，他以惊世骇俗的才华，起而议政“医国”，宣传变革。他的思想，他的词锋，他的离经叛道的精神，像光照天地的出鞘长剑，震惊了醉生梦死中的清朝廷权贵。终因“动触时忌”，他于道光十九年...", "authors": ["高原"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471e7bdb6a81d0c532b011e", "shortContent": "龚自珍的时代是一个山雨欲来风满楼的时代，他逝世前一年就发生鸦片战争了。正是这样的时代，产生了这位近代史上启蒙思想家。他意识到封建的闭关锁国政策行不通了，帝国主义的侵略更加暴露出封建主义衰朽没落的本质。龚自珍敏感地嗅到了这腐败的气息，他以惊世骇俗的才华，起而议政“医国”，宣传变革。他的思想，他的词锋，他的离经叛道的精神，像光照天地的出鞘长剑，震惊了醉生梦死中的清朝廷权贵。终因“动触时忌”，他于道光十...", "authors": ["高原"], "pressName": "上海辞书出版社"}]', '', 'center', 1423175853, '57b99732a633bd00619fdbb8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10310, '病梅馆记', NULL, 17, 723, 0, 2, '龚自珍', NULL, 10080, '57b9b97d79bc4400639c3e56', '清', 'wen', '文', 'http://baike.baidu.com/view/36064.htm', '', '江宁之龙蟠，苏州之邓尉，杭州之西溪，皆产梅。或曰：梅以曲为美，直则无姿；以欹为美，正则无景；梅以疏为美，密则无态。固也。此文人画士，心知其意，未可明诏大号，以绳天下之梅也；又不可以使天下之民，斫直，删密，锄正，以夭梅、病梅为业以求钱也。梅之欹、之疏、之曲，又非蠢蠢求钱之民，能以其智力为也。有以文人画士孤癖之隐，明告鬻梅者，斫其正，养其旁条，删其密，夭其稚枝，锄其直，遏其生气，以求重价；而江、浙之梅皆病。文人画士之祸之烈至此哉！
予购三百盆，皆病者，无完者，既泣之三日，乃誓疗之、纵之、顺之，毁其盆，悉埋于地，解其棕缚；以五年为期，必复之全之。予本非文人画士，甘受诟厉，辟病梅之馆以贮之。呜呼！安得使予多暇日，又多闲田，以广贮江宁、杭州、苏州之病梅，穷予生之光阴以疗梅也哉？ ', '此文是清代文学家龚自珍创作的一篇散文。作者托梅议政，形象地揭露和抨击了清朝封建统治者束缚人们思想，压抑，摧残人才的罪行，表达了作者要求改革政治，打破严酷的思想统治，追求个性解放的强烈愿望。全文共三段。第一段，剖析产生病梅的根由。第二段，表明自己疗梅的行动和决心。第三段，抒写自己辟馆疗梅的苦心。', '江宁：旧江宁府所在地，在今江苏南京。
龙蟠：龙蟠里，在今南京清凉山下。
邓尉：山名。在今江苏苏州西南。
西溪：地名。
欹（qī）：倾斜。
固也：本来如此。固，本来。
明诏大号：公开宣告，大声疾呼。明，公开。诏，告诉，一般指上告下。号，疾呼，喊叫。
绳：名作动，约束。
斫：砍削。
直：笔直的枝干。
夭梅病梅：摧折梅，把它弄成病态。夭：使……摧折（使……弯曲）。病，使……成为病态。
蠢蠢：无知的样子。
智力：智慧和力量。
孤癖：特殊的嗜好。
隐：隐衷，隐藏心中特别的嗜好。
鬻（yù）：卖。
旁条：旁逸斜出的枝条。
稚枝：嫩枝。
重价：高价。
遏（è）：遏制。
泣：为……哭泣。
纵：放纵。
顺：使……顺其自然。
悉：全。
棕缚：棕绳的束缚。
以……为：把……当做。
复：使……恢复。
全：使……得以保全。
诟厉：讥评，辱骂。厉，病。
安得：怎么能够。
暇：空闲。
穷：穷尽。', '江宁的龙蟠里，苏州的邓尉山，杭州的西溪，都出产梅。有人说："梅凭着弯曲的姿态被认为是美丽的，笔直了就没有风姿；凭着枝干倾斜被认为是美丽的，端正了就没有景致；凭着枝叶稀疏被认为是美丽的，茂密了就没有姿态。”本来就如此。（对于）这，文人画家在心里明白它的意思，却不便公开宣告，大声疾呼，用（这种标准）来约束天下的梅。又不能够来让天下种梅人砍掉笔直的枝干、除去繁密的枝条、锄掉端正的枝条，把枝干摧折、使梅花呈病态作为职业来谋求钱财。梅的枝干的倾斜、枝叶的疏朗、枝干的弯曲，又不是那些忙于赚钱的人能够凭借他们的智慧、力量做得到的。有的人把文人画士这隐藏在心中的特别嗜好明白地告诉卖梅的人，（使他们）砍掉端正的（枝干），培养倾斜的侧枝，除去繁密的（枝干），摧折它的嫩枝，锄掉笔直的（枝干），阻碍它的生机，用这样的方法来谋求大价钱，于是江苏、浙江的梅都成病态了。文人画家造成的祸害严重到这个地步啊！　　我买了三百盆梅，都是病梅，没有一盆完好的。我已经为它们流了好几天泪之后，于是发誓要治疗它们：我放开它们，使它们顺其自然生长，毁掉那些盆子，把梅全部种在地里，解开捆绑它们棕绳的束缚；把五年作为期限，一定使它们恢复和使它们完好。我本来不是文人画士，心甘情愿受到辱骂，开设一个病梅馆来贮存它们。
唉！怎么能让我有多一些空闲时间，又有多一些空闲的田地，来广泛贮存南京、杭州、苏州的病态的梅树，竭尽我毕生的时间来治疗病梅呢！', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed211dbb8b379ee0a1522", "shortContent": "③西溪：地名，在今杭州市灵隐山西北。④欹（qī）：歪斜。⑤固：必，毫无疑义。“固也”，紧承上文，并且直贯下面三个带“也”字的判断长句。⑥“此文”句：意谓这是文人画士心照不宣，不便公开告谕，大肆号令，用以束缚天下自然多姿之梅的良苦用心。绳，木匠用来取直的墨绳，这里用作动词衡量之义，引申为约束。⑦“又不”句：意谓文人画士又不可能让天下所有之人尽从其意，以摧残自然之梅为业来谋利。斫（zhuó浊），砍。夭...", "authors": ["孙钦善"], "pressName": "上海辞书出版社"}]', '', 'indent', 1423175938, '57b912e5a633bd00665de4c5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (47691, '十一月朔大雪节早见雪', NULL, 4, 472, 0, 1, '陶宗仪', NULL, 11135, '5858e62c128fe1006b87c8b5', '元', 'shi', '诗', NULL, NULL, '狂风昨夜吼棱棱，寒压重衾若覆冰。
节气今朝逢大雪，清晨瓦上雪微凝。', NULL, NULL, NULL, NULL, NULL, 'center', 1582024380, '585ced06da2f60006582edc9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (47795, '立冬', NULL, 9, 656, 0, 1, '陆文圭', NULL, 11145, '5858e62eb123db00658d7b64', '元', 'shi', '诗', NULL, NULL, '早久何当雨，秋深渐入冬。
黄花犹带露，红叶已随风。
边思吹寒角，村歌相晚舂。
篱门日高卧，衰懒愧无功。', NULL, NULL, NULL, NULL, NULL, 'center', 1575622562, '585ced1b61ff4b00688e6f50', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10311, '贺新郎', NULL, 748, 793, 4, 1, '辛弃疾', NULL, 10003, '57b8ed682e958a005fa4d096', '宋', 'ci', '词', 'http://baike.baidu.com/view/2775649.htm', '邑中园亭，仆皆为赋此词。一日，独坐停云，水声山色，竞来相娱。意溪山欲援例者，遂作数语，庶几仿佛渊明思亲友之意云。', '甚矣吾衰矣。怅平生、交游零落，只今馀几！白发空垂三千丈，一笑人间万事。问何物、能令公喜？我见青山多妩媚，料青山见我应如是。情与貌，略相似。
一尊搔首东窗里。想渊明《停云》诗就，此时风味。江左沉酣求名者，岂识浊醪妙理。回首叫、云飞风起。不恨古人吾不见，恨古人不见吾狂耳。知我者，二三子。', '此词作于宋宁宗嘉泰元年（1201年）。全词层叠典故之中抒发了词人昂扬激越的豪放情怀，表达了罢职闲居时的寂寞与苦闷的心情。', '贺新郎：词牌名，又名《金缕曲》、《乳燕飞》、《貂裘换酒》、《金缕歌》、《风敲竹》、《贺新凉》。传作以《东坡乐府》所收为最早，惟句豆平仄，与诸家颇多不合。因以《稼轩长短句》为准。双调，一百十六字，上阕五十七字，下阕五十九字，各十句六仄韵。大抵用入声部韵者较激壮，用上、去声部韵者较凄郁，贵能各适物宜耳。
邑：指铅山县。辛稼轩在江西铅山期思渡建有别墅，带湖居所遭燬后举家迁之。
僕：自称。
停云：停云堂，在瓢泉别墅。
「甚矣吾衰矣」句：《论语·述而》：「子曰：『甚矣，吾衰也！久矣，吾不复梦见周公！』」孔子慨叹己「道不行」之语（梦周公，欲行其道）。作者藉此感叹自己壮志难酬。
「白发空垂三千丈」句：唐·李太白《秋浦歌十七首·其十五》：「白发三千丈，缘愁似个长。」
「问何物、能令公喜」句：南朝宋·刘义庆《世说新语·宠礼》：「王恂、郗超并有奇才，为大司马所眷拔，恂为主薄，超为记室参军。超为人多髯，恂状短小，于时荆州为之语曰：『髯参军，短主薄，能令公喜，能令公怒。』」
「我见青山多妩媚」句：《旧唐书·卷七十一·魏徵传》：「帝大笑曰：『人言魏徵举动疏慢，我但觉妩媚，适为此耳。』」《新唐书·卷九十七·魏徵传》：「帝大笑曰：『人言徵举动疏慢，我但见其妩媚耳！』」
「一尊搔首东窗里。想渊明《停云》诗就」句：《停云》诗序云：「停云，思亲友也。樽湛新醪，园列初荣，愿言不从，叹息弥襟。」全诗云：「霭霭停云，濛濛时雨。八表同昏，平路伊阻。静寄东轩，春醪独抚。良朋悠邈，搔首延伫。		停云霭霭，时雨濛濛。八表同昏，平陆成江。有酒有酒，闲饮东窗。愿言怀人，舟车靡从。		东园之树，枝条再荣。竞用新好，以招余情。人亦有言，日月于征。安得促席，说彼平生。			翩翩飞鸟，息我庭柯。敛翮闲止，好声相和。岂无他人，念子寔多。愿言不获，抱恨如何！」
「江左沉酣求名者」句：宋·苏东坡《和陶渊明饮酒诗二十首·其三》：「道丧士失己，出语辄不情。江左风流人，醉中亦求名。渊明独清真，谈笑得此生。」江左，原指长江南部一带，此指东晋。
浊醪（láo）妙理：唐·杜少陵《晦日寻崔戢（jí）李封》诗：「浊醪有妙理，庶用慰沈浮。」浊醪，浊酒。
云飞风起：汉高帝《大风歌》：「大风起兮云飞扬，威加海内兮归故乡，安得猛士兮守四方。」
「不恨古人吾不见」句：《南史·卷三十二·〈张邵传·（从孙）张融传〉》：「融字思光，弱冠有名。……融善草书，常自美其能。帝曰：『卿书殊有骨力，但恨无二王法。』答曰：『非恨臣无二王法，亦恨二王无臣法。』。常叹云：『不恨我不见古人，所恨古人又不见我。』」', '我已经很衰老了。平生曾经一同出游的朋友零落四方，如今还剩下多少？真令人惆怅。这么多年只是白白老去而已，功名未竟，对世间万事也慢慢淡泊了。还有什么能真正让我感到快乐？我看那青山潇洒多姿，想必青山看我也是一样。不论情怀还是外貌，都非常相似。
把酒一尊，在窗前吟诗，怡然自得。想来当年陶渊明写成《停云》之时也是这样的感觉吧。江南那些醉中都渴求功名的人，又怎能体会到饮酒的真谛？在酒酣之际，回头朗吟长啸，云气会翻飞，狂风会骤起。不恨我不能见到疏狂的前人，只恨前人不能见到我的疏狂而已。了解我的，还是那几个朋友。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74eadbb8b379ee08df81", "shortContent": "此词作年，依邓广铭《稼轩词编年笺注》考证，约略定为宋宁宗庆元四年（1198）左右。此时辛弃疾被投闲置散又已四年。他在信州铅山（今属江西）东期思渡瓢泉旁筑了新居，建了园、亭等。其中有“停云堂”，取陶渊明《停云》诗意命名。辛弃疾《临江仙·停云偶作》云：“偶向停云堂上坐，晓猿夜鹤惊猜。”即咏此间风物。\n此词仿陶渊明《停云》“思亲友”之意，抒写了作者落职后的寂寞心情和对时局的深刻怨愤。\n“甚矣吾衰矣。怅平...", "authors": ["蔡厚示"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ecdbb8b379ee0a0319", "shortContent": "此词作年，依邓广铭《稼轩词编年笺注》考证，约略定为宋宁宗庆元四年（1198）左右。此时辛弃疾被投闲置散又已四年。他在信州铅山（今属江西）东期思渡瓢泉旁筑了新居，建了园、亭等。其中有“停云堂”，取陶渊明《停云》诗意命名。辛弃疾《临江仙·停云偶作》云：“偶向停云堂上坐，晓猿夜鹤惊猜”，即咏此间风物。\n此词仿陶渊明《停云》“思亲友”之意，抒写了作者落职后的寂寞心情和对时局的深刻怨愤。\n“甚矣吾衰矣。怅平...", "authors": ["蔡厚示"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255eebf5e0fdea508e9", "shortContent": "此词作年，依邓广铭《稼轩词编年笺注》考证，约略定为宋宁宗庆元四年（1198）左右。此时辛弃疾被投闲置散又已四年。他在信州铅山（今属江西）东期思渡瓢泉旁筑了新居，建了园、亭等。其中有“停云堂”，取陶渊明《停云》诗意命名。辛弃疾《临江仙·停云偶作》云：“偶向停云堂上坐，晓猿夜鹤惊猜”，即咏此间风物。\n\n此词仿陶渊明《停云》“思亲友”之意，抒写了作者落职后的寂寞心情和对时局的深刻怨愤。\n\n“甚矣吾衰矣。...", "authors": ["蔡厚示"], "pressName": "上海辞书出版社"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127044c305cf0801816f23", "shortContent": "这首是辛弃疾追忆与陈亮的会面，抒发别情的词作。辛弃疾与陈亮的友情，是南宋诗词史上的一段佳话，他们两人志同道合，都是铁杆主战派，多次以诗词“唱和”抗金大业。这首词写于淳熙十五年（1188）冬，陈亮从东阳来，与辛弃疾同游鹅湖，陈亮离去之后，辛弃疾写下了这首词。\n\n词的上片，词人追忆与陈亮话别时的情景。他们手持酒杯，在长亭话别，辛弃疾非常欣赏陈亮的为人，推崇陈亮的才干。他把陈亮安贫乐道的君子品格比作隐居...", "authors": ["陈庆之"], "pressName": "崇文书局"}, {"bookId": "64688f9830675327e19962ff", "bookTitle": "辛弃疾词鉴赏辞典（珍藏本）", "articleId": "64697aed30675327e19c8fed", "shortContent": "此词作年，依邓广铭《稼轩词编年笺注》考证，约略定为宋宁宗庆元四年(1198)左右。此时辛弃疾被投闲置散又已四年。他在信州铅山（今属江西）东期思渡瓢泉旁筑了新居，建了园、亭等。其中有“停云堂”，取陶渊明《停云》诗意命名。辛弃疾《临江仙·停云偶作》云：“偶向停云堂上坐，晓猿夜鹤惊猜”，即咏此间风物。\n此词仿陶渊明《停云》“思亲友”之意，抒写了作者落职后的寂寞心情和对时局的深刻怨愤。\n“甚矣吾衰矣。怅平...", "authors": ["蔡厚示"], "pressName": "上海辞书出版社"}]', '缪彥威《稼轩词序》：余读稼轩词，恒感觉双重之印象，除表面所发抒之情思以外，其里面尚蕴含一种境界，与其表面之情思相异或相反，而生调剂映衬之作用，得相反相成之妙，使其作品更跻于浑融深美之境。
范廓之：公一世之豪，以气节自负，以功业自许。
岳倦翁《桯史·卷三》：辛稼轩守南徐，已多病谢客，子来筮仕委吏，实隶总所，例于州家殊参辰，旦望贽谒刺而已。余时以乙丑南宫试，岁前莅事仅两旬，即谒告去。稼轩偶读余《通名启》而喜，又颇阶父兄旧，特与其洁。余试既不利，归官下，时一招去。稼轩以词名，每燕必命侍妓歌其所作。特好歌《贺新郎》一词，自诵其警句曰：「我见青山多妩媚，料青山见我应如是。」又曰：「不恨古人吾不见，恨古人不见吾狂耳。」每至此，辄拊髀自笑，顾问坐客何如，皆叹誉如出一口。既而又作一永遇乐，序北府事，首章曰：「千古江山，英雄无觅孙仲谋处。」又曰：「寻常巷陌，人道寄奴曾住。」其寓感概者，则曰：「不堪回首，佛狸祠下，一片神鸦社鼓。凭谁问：廉颇老矣，尚能饭否？」特置酒召数客，使妓叠歌，益自击节，遍问客，必使摘其疵，孙谢不可。客或措一二辞，不契其意，又弗答，然挥羽四视不止。余时年少，勇于言，偶坐于席侧，稼轩因诵启语，顾问再四。余率然对曰：「待制词句，脱去今古轸辙，每见集中有『解道此句，真宰上诉，天应嗔耳』之序，尝以为其言不诬。童子何知，而敢有议？然必欲如范文正以千金求《严陵祠记》一字之易，则晚进尚窃有疑也。」稼轩喜，促膝亟使毕其说。余曰：「前篇豪视一世，独首尾两腔，警语差相似；新作微觉用事多耳。」于是大喜，酌酒而谓坐中曰：「夫君实中予痼。」乃咏改其语，日数十易，累月犹未竟，其刻意如此。余既以一语之合，益加厚，颇取视其骫骳，欲以家世荐之朝，会其去，未果。', 'indent', 1415639136, '57b8c5e32e958a005fa45dae', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10312, '溪亭', NULL, 197, 310, 2, 0, '林景熙', NULL, 10081, '57bb0a1679bc440063a6860f', '宋', 'shi', '诗', 'http://baike.baidu.com/view/1035405.htm', '', '清秋有馀思，日暮尚溪亭。
高树月初白，微风酒半醒。
独行穿落叶，闲坐数流萤。
何处渔歌起？孤灯隔远汀。', '全诗写作者于清秋日暮在溪亭散心，独自在落叶飘零的树林中穿行。通过对富有象征意义的意象的选择和描绘，在字里行间表达出内心深处的真情实感，语意委婉，情韵深长。', '馀：同“余”。
尚：还，依然。
溪亭：临溪水的亭子。张祜《题上饶亭》：“溪亭拂一琴，促轸坐披衿。”
汀：水边平地，小洲。屈原《九歌·湘夫人》：“搴汀洲兮杜若。”', '', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea7525e272d4b22548b31", "shortContent": "在诗歌中，如果能在真实描摹客观景物的同时，又把诗人的某种独特感受倾注在景物描写之中，使读者从思想上受到感染，艺术上得到享受，这就需要诗人在思想深度和艺术造诣两个方面下功夫。林景熙的《溪亭》诗正是借景抒情，达到情景交融的艺术境界的佳作。\n首联破题。“清秋有余思，日暮尚溪亭”。表明全诗以溪亭为中心，逐一描绘周围的清秋初月的景色。乍读起来，似有恬静闲适的印象，细细品味，又觉不然。诗人徙倚溪亭，观览景色，...", "authors": ["张锡厚"], "pressName": "上海辞书出版社"}]', '', 'center', 1413470191, '57b8efbdc4c97100558eb3df', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10313, '春夜宴从弟桃花园序', NULL, 650, 1052, 1, 4, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'wen', '文', 'http://baike.baidu.com/view/415796.htm', '', '夫天地者，万物之逆旅也；光阴者，百代之过客也。而浮生若梦，为欢几何？古人秉烛夜游，良有以也。况阳春召我以烟景，大块假我以文章。会桃花之芳园，序天伦之乐事。群季俊秀，皆为惠连；吾人咏歌，独惭康乐。幽赏未已，高谈转清。开琼筵以坐花，飞羽觞而醉月。不有佳咏，何伸雅怀？如诗不成，罚依金谷酒数。', '此序约于开元二十一年（公元733年）前后作于安陆。李白与堂弟们在春夜宴饮赋诗，并为之作此序文。唐玄宗开元十五年（公元727年），二十七岁的李白「仗剑去国，辞亲远游」来到安陆。在这里，他娶故宰相许圉师的孙女为妻，养育了一双儿女。十年期间，他西入长安，东游吴越，南泛洞庭，北抵太原，留下了百余首脍炙人口的千古名篇。
文章以清新俊逸的风格，转折自如的笔调，记叙了作者与诸位堂弟在桃花园聚会赋诗畅叙天伦一事，慷慨激昂地表达了李白热爱生活、热爱生命的人生追求和积极乐观的人生态度。', '桃花园：疑在安陆兆山桃花岩。
从（zòng）弟：堂弟。从，堂房亲属。
逆旅：迎客止歇，所以客舍称逆旅。逆，迎接；旅，客。
过客：过往的客人。唐·李白《拟古十二首·其九》：「生者为过客。」
浮生若梦：死生之差异，就好像梦与醒之不同，纷纭变化，不可究诘。
秉烛夜游：谓及时行乐。这里是说人生有限，应夜以继日的游乐。《古诗十九首·其十五》：「昼短苦夜长，何不秉烛游。」三国魏·曹丕《与吴质书》：「少壮真当努力，年一过往，何可攀援！古人思秉烛夜游，良有以也。」秉，执；以，因由、道理；有以，有原因。
阳春：和煦的春光。
召：召唤，引申为吸引。
烟景：春天气候温润，景色似含烟雾。
大块：大地。大自然。
假：借，这里是提供、赐予的意思。
文章：这里指绚丽的文采。古代以青与赤相配合为文，赤与白相配合为章。
桃花：一作“桃李”。
序：通「叙」，叙说。
天伦：指父子、兄弟等亲属关系。这里专指兄弟。
季：年少者的称呼。古以伯（孟）、仲、叔、季排行，季指同辈排行中最小的，故以季代称弟
群季：这里泛指诸弟。
惠连：谢惠连，南朝诗人，早慧。这里以惠连来称赞诸弟的文才。
咏歌：吟诗。
康乐：南朝刘宋时山水诗人谢灵运，袭封康乐公，世称谢康乐。
「幽赏未已，高谈转清」句：谓一边欣赏着幽静的美景，一边谈论着清雅的话题。
琼筵（yán）：华美的宴席。
坐花：坐在花丛中。
羽觞（shāng）：古代一种酒器，作鸟雀状，有头尾羽翼。
醉月：醉倒在月光下。
金谷酒数：金谷，园名，晋·石崇于金谷涧（在今河南洛阳西北）中所筑，他常在这里宴请宾客。其《金谷诗序》："遂各赋诗，以叙中怀，或不能者，罚酒三斗。"后泛指宴会上罚酒三杯的常例。', '天地是万物的客舍，百代是古往今来时间的过客，死生的差异，就好像梦与醒的不同，纷纭变换，不可究诘，得到的欢乐，又能有多少呢！古人夜间执着蜡烛游玩实在是有道理啊，况且春天用艳丽景色召唤我，大自然把各种美好的形象赐予我，相聚在桃花飘香的花园中，畅叙兄弟间快乐的往事。弟弟们英俊优秀，个个都有谢惠连那样的才情，而我作诗吟咏，却惭愧不如谢灵运。清雅的赏玩兴致正雅，高谈阔论又转向清言雅语。摆开筵席来坐赏名花，快速地传递着酒杯醉倒在月光中，没有好诗，怎能抒发高雅的情怀？倘若有人作诗不成，就要按照当年石崇在金谷园宴客赋诗的先例，谁咏不出诗来，罚酒三杯。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1ea03048e64fbd9ccfa", "shortContent": "这篇散文小品，洋溢着诗情画意，像一首优美的诗，长期以来，家弦户诵，脍炙人口。明代大画家仇英还把它转化为视觉形象，绘成图画，流传至今。\n从题目看，这是一篇记事文。记事文，一般要包含六个要素：Who（何人）、When（何时）、Where（何地）、What（何事）、How（如何）、Why（为何）。题目即回答了四个要素：什么人？作者与诸从弟。什么时候？春夜。什么地方？桃李园。干什么？宴饮。这已经在很大程度...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6467701145e4710056d00ca0", "shortContent": "这篇散文小品，洋溢着诗情画意，像一首优美的诗，长期以来，家弦户诵，脍炙人口。明代大画家仇英还把它转化为视觉形象，绘成图画，流传至今。\n\n从题目看，这是一篇记事文。记事文，一般要包含六个要素：Who（何人）、When（何时）、Where（何地）、What（何事）、How（如何）、Why（为何）。题目即回答了四个要素：什么人？作者与诸从弟。什么时候？春夜。什么地方？桃李园。干什么？宴饮。这已经在很大程...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413455195, '57b14e99a633bd0057092707', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10314, '离思 · 其四', NULL, 1232, 890, 2, 2, '元稹', NULL, 10082, '57b9bf37d342d3006be01c7b', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3856278.htm', '', '曾经沧海难为水，除却巫山不是云。
取次花丛懒回顾，半缘修道半缘君。', '此诗为悼念亡妻韦丛之作。诗人运用「索物以托情」的比兴手法，以精警的词句，赞美了夫妻之间的恩爱，表达了对韦丛的忠贞与怀念之情。', '曾经：曾经到临。经，经临、经过。
难为：这里指「不足为顾」「不值得一观」的意思。
「除却巫山不是云」句：相形之下，除了巫山，别处的云便不称其为云。此句与前句均暗喻自己曾经接触过的一段恋情。除却，除了、离开。
取次：草草，仓促，随意。这里是「匆匆经过」「仓促经过」或「漫不经心地路过」的样子。宋·陆游《秋暑夜兴》诗：「呼童持烛开藤纸，一首清诗取次成。」元·朱庭玉《青杏子·送别》曲：「肠断处，取次作别离。」
花丛：这里并非指自然界的花丛，乃借喻美貌女子众多的地方，也暗指青楼妓馆。
半缘：此处指「一半是因为……」。
修道：此处指修炼道家之术。此处阐明的是修道之人讲究清心寡欲。
君：此指曾经心仪的恋人。', '曾经到临过沧海，别处的水就不足为顾；若除了巫山，别处的云便不称其为云。草草地在青楼妓馆走过，懒得回头顾盼；这缘由，一半是因为修道人的清心寡欲，一半是因为曾经拥有过的你。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ce2e6a6b501f95c381", "shortContent": "此为悼念亡妻韦丛之作。诗人运用“索物以托情”的比兴手法，以精警的词句，赞美了夫妻之间的恩爱，表达了对韦丛的忠贞与怀念之情。\n首二句“曾经沧海难为水，除却巫山不是云”，是从《孟子·尽心》篇“观于海者难为水，游于圣人之门者难为言”变化而来的。两处用比相近，但《孟子》是明喻，以“观于海”比喻“游于圣人之门”，喻意显明；而这两句则是暗喻，喻意并不明显。沧海无比深广，因而使别处的水相形见绌。巫山有朝云峰，下...", "authors": ["阎昭典"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad4797a92d5e4fd911", "shortContent": "此为悼念亡妻韦丛之作。诗人运用“索物以托情”的比兴手法，以精警的词句，赞美了夫妻之间的恩爱，表达了对韦丛的忠贞与怀念之情。\n\n首二句“曾经沧海难为水，除却巫山不是云”，是从《孟子·尽心》篇“观于海者难为水，游于圣人之门者难为言”变化而来的。两处用比相近，但《孟子》是明喻，以“观于海”比喻“游于圣人之门”，喻意显明；而这两句则是暗喻，喻意并不明显。沧海无比深广，因而使别处的水相形见绌。巫山有朝云峰，...", "authors": ["阎昭典"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127075e6f69b71e93f62db", "shortContent": "关于此诗所指之“君”，向来有两种说法：一说指元稹的原配夫人韦丛，如《云溪友议》云：“初，韦蕙丛逝，不胜其悲，为诗悼之。”另一说指元稹年少时恋人崔双文，如《唐诗快》卷一五云：“上皆为双文而作也。胡天胡地，美至乎此，无怪乎痴人之想莺莺也。”笔者倾向于前者。\n\n元和四年（809），元稹爱妻韦丛病逝，死时年仅二十七岁。韦丛死后，元稹悲痛欲绝，曾陆续创作多首悼亡诗，如《六年春遣怀八首》、《遣悲怀三首》等，情...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271307ccdb86c49f292ec", "shortContent": "关于此诗所指之“君”，向来有两种说法：一说指元稹的原配夫人韦丛，如《云溪友议》云：“初，韦蕙丛逝，不胜其悲，为诗悼之。”另一说指元稹年少时恋人崔双文，如《唐诗快》卷一五云：“上皆为双文而作也。胡天胡地，美至乎此，无怪乎痴人之想莺鸾也。”笔者倾向于前者。\n\n元和四年（809），元稹爱妻韦丛病逝，死时年仅二十七岁。韦丛死后，元稹悲痛欲绝，曾陆续创作多首悼亡诗，如《六年春遣怀八首》、《遣悲怀三首》等，情...", "authors": ["乐云"], "pressName": "崇文书局"}]', '', 'center', 1423176085, '57b90102165abd0054bfd056', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10316, '题都城南庄', NULL, 1129, 5, 2, 3, '崔护', NULL, 10083, '57b917642e958a005fa609bb', '唐', 'shi', '诗', 'http://baike.baidu.com/view/432112.htm', '', '去年今日此门中，人面桃花相映红。
人面不知何处去，桃花依旧笑春风。', '《题都城南庄》是唐代诗人崔护的作品，载于《全唐诗》卷三百六十八。这首诗设置了两个场景，“寻春遇艳”与“重寻不遇”，虽然场景相同，却是物是人非。开头两句追忆“去年今日”的情景，先点出时间和地点，接着描写佳人，以“桃花”的红艳烘托“人面”之美；结尾两句写“今年今日”此时，与“去年今日”有同有异，有续有断，桃花依旧，人面不见。两个场景的映照，曲折地表达出诗人的无限怅惘之情。此诗脍炙人口，尤其以“人面不知何处去，桃花依旧笑春风”二句流传甚广。', '都：国都，指唐朝京城长安。
人面：指姑娘的脸。第三句中“人面”指代姑娘。
笑：形容桃花盛开的样子。', '去年春天，就在这扇门里，姑娘脸庞，相映鲜艳桃花。
今日再来此地，姑娘不知去向何处，只有桃花依旧，含笑怒放春风之中。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92bf2cee9a0c24ecf972", "shortContent": "这首诗有一段颇具传奇色彩的本事：“（崔护）举进士下第，清明日，独游都城南，得居人庄。一亩之宫，而花木丛萃，寂若无人。扣门久之，有女子自门隙窥之，问曰：‘谁耶？’以姓字对，曰：‘寻春独行，酒渴求饮。’女子以杯水至，开门，设床命坐，独倚小桃斜柯伫立，而意属殊厚，妖姿媚态，绰有余妍。崔以言挑之，不对，目注者久之。崔辞去，送至门，如不胜情而入，崔亦睠盼而归。嗣后绝不复至。及来岁清明日，忽思之，情不可抑，径...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a9e", "shortContent": "这首诗有一段颇具传奇色彩的本事：“（崔护）举进士下第，清明日，独游都城南，得居人庄。一亩之宫，而花木丛萃，寂若无人。扣门久之，有女子自门隙窥之，问曰：‘谁耶？’以姓字对，曰：‘寻春独行，酒渴求饮。’女子以杯水至，开门，设床命坐，独倚小桃斜柯伫立，而意属殊厚，妖姿媚态，绰有余妍。崔以言挑之，不对，目注者久之。崔辞去，送至门，如不胜情而入，崔亦睠盼而归。嗣后绝不复至。及来岁清明日，忽思之，情不可抑，径...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706c9761253910e90538", "shortContent": "据唐代孟柴《本事诗·情感》记载，崔护这首《题都城南庄》有一段“本事”：“博陵崔护……举进士下第，清明日，独游都城南，得居人庄，一亩之宫，而花木丛萃，寂若无人。扣门久之，有女子自门隙窥之，问曰：‘谁耶？’以姓字对，曰：‘寻春独行，酒渴求饮。’女子以杯水至，开门，设床命坐，独倚小桃斜柯伫立，而意属殊厚，妖姿媚态，绰有余妍。崔以言挑之，不对，目注者久之。崔辞去，送至门，如不胜情而入，崔亦睠盼而归。嗣后绝...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127105c9ebcc6fbea1a462", "shortContent": "据唐代孟棨《本事诗·情感》记载，崔护这首《题都城南庄》有一段“本事崔护……进士下第，清明日，独游都城南，得居人庄，一亩之宫，而花木丛萃，寂若无人。扣门久之，有女子自门隙窥之，问曰：‘谁耶？’以姓字对，曰：‘寻春独行，酒渴求饮。’女子以杯水至，开门，设床命坐，独倚小桃斜柯伫立，而意属殊厚，妖姿媚态，绰有余妍。崔以言挑之，不对，目注者久之。崔辞去，送至门，如不胜情而入，崔亦睠盼而归。嗣后绝不复至。及来...", "authors": ["易文翔"], "pressName": "崇文书局"}]', '沈括《梦溪笔谈》：诗人以诗主人物，故虽小诗，莫不埏蹂极工而后已。所谓“旬锻月炼”者，信非虚言。小说崔护《题城南》诗，其始曰：“去年今日此门中，人面桃花相映红。人面不知何处去，桃花依旧笑春风。”后以其意未全，语未工，改第三句曰“人面秖今何处在”。至今所传此两本，惟《本事诗》作“秖今何处在”。唐人工诗，大率多如此。虽有两“今”字，不恤也，取语意为主耳。后人以其有两“今”字，只多行前篇。
吴乔《围炉诗话》：唐人作诗，意细法密，如崔护“人面不知何处去”，后改为“人面秖今何处在”，以有“今”字，则前后交付明白，重字不惜也。', 'center', 1413205503, '57b46ea07db2a200546d9cad', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (48156, '梨花', NULL, 2, 656, 0, 1, '陆文圭', NULL, 11145, '5858e62eb123db00658d7b64', '元', 'shi', '诗', NULL, NULL, '粉香初试晓妆匀，花貌参差是玉真。
茅屋诗人嗟老去，东风勿送一枝春。', NULL, NULL, NULL, NULL, NULL, 'center', 1586347616, '585ced6761ff4b00580c6264', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10317, '国风 · 卫风 · 硕人', NULL, 261, 573, 2, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'shi', '诗', 'http://baike.baidu.com/view/2943360.htm', '', '硕人其颀，衣锦褧衣。齐侯之子，卫侯之妻。东宫之妹，邢侯之姨，谭公维私。
手如柔荑，肤如凝脂，领如蝤蛴，齿如瓠犀，螓首蛾眉，巧笑倩兮，美目盼兮。
硕人敖敖，说于农郊。四牡有骄，朱幩镳镳。翟茀以朝。大夫夙退，无使君劳。
河水洋洋，北流活活。施罛濊濊，鳣鲔发发。葭菼揭揭，庶姜孽孽，庶士有朅。', '全诗四章，每章七句。描写齐女庄姜出嫁卫庄公的壮盛和美貌，着力刻划了庄姜高贵，美丽的形象。描写细致，比喻新鲜，以致清人姚际恒由衷感叹：「千古颂美人者无出其右，是为绝唱。」诗从庄姜身份家世写起，再写其外貌，有如一个特定镜头。最后一节在「河水洋洋」，「葭菼揭揭」优美环境中，铺写「庶姜」「庶士」的盛况，又像是一幅画面，镜头慢慢推向远方，一行人走向远方，给人留下无尽的回味，新鲜生动，而且意味深长。阅罢《硕人》，这幅妙绝千古的「美人图」，留给人们最鲜活的印象，是那倩丽的巧笑，流盼的美目——即「巧笑倩兮，美目盼兮」。《诗经》是中国文学史上第一部诗歌总集。对后代诗歌发展有深远的影响。', '硕人：高大白胖的人，美人。当时以身材高大为美。此指卫庄公夫人庄姜。
颀（qí）：修长貌。
衣锦：穿着锦衣，翟衣。「衣」为动词。
褧（jiǒng）：妇女出嫁时御风尘用的麻布罩衣，即披风。
齐侯：指齐庄公。
子：这里指女儿。
卫侯：指卫庄公。
东宫：太子居处，这里指齐太子得臣。
邢：春秋国名，在今河北邢台。
姨：这里指妻子的姐妹。
谭：春秋国名，在今山东历城。
谭公维私：意谓谭公是庄姜的姐夫。维，其；私，女子称其姊妹之夫。
荑（tí）：白茅之芽。
领：颈。
蝤蛴（qiúqí）：天牛的幼虫，色白身长。
瓠犀（hùxī）：瓠瓜子儿，色白，排列整齐。
螓（qín）首，形容前额丰满开阔。螓，似蝉而小，头宽广方正。
蛾眉：蚕蛾触角，细长而曲。
螓首蛾眉：形容眉毛细长弯曲。
倩：嘴角间好看的样子。
盼：眼珠转动，一说眼儿黑白分明。
敖敖：修长高大貌。
说（shuì）：通「税」，停车。
农郊：近郊。一说东郊。
四牡：驾车的四匹雄马。
有骄：骄骄，强壮的样子。「有」是虚字，无义。
朱幩（fén）：用红绸布缠饰的马嚼子。
镳镳（biāo）：盛美的样子。
翟茀（dífú）：以雉羽为饰的车围子。翟，山鸡。茀，车篷。
夙退：早早退朝。
河水：特指黄河。洋洋：水流浩荡的样子。
北流：指黄河在齐、卫间北流入海。
活活（guō）：水流声。
施：张，设。
罛（gū）：大的鱼网。
濊濊（huò）：撒网入水声。
鱣（zhān）：鳇鱼。一说赤鲤。
鲔（wěi）：鲟鱼。一说鲤属。
发发（bō）：鱼尾击水之声。一说盛貌。
葭（jiā）：初生的芦苇。
菼（tǎn）：初生的荻。
揭揭：长貌。
庶姜：指随嫁的姜姓众女。
孽孽：高大的样子，或曰盛饰貌。
士：从嫁的媵臣。
有朅（qiè）：朅朅，勇武貌。', '好个修美的女郎，麻纱罩衫锦绣裳。她是齐侯的女儿，她是卫侯的新娘，她是太子的阿妹，她是邢侯的小姨，谭公又是她姊丈。
手像春荑好柔嫩，肤如凝脂多白润，颈似蝤蛴真优美，齿若瓠子最齐整。额角丰满眉细长，嫣然一笑动人心，秋波一转摄人魂。
好个高挑的女郎，车歇郊野农田旁。看那四马多雄健，红绸系在马嚼上，华车徐驶往朝堂。诸位大夫早退朝，今朝莫太劳君王。
黄河之水白茫茫，北流入海浩荡荡。下水鱼网哗哗动，戏水鱼儿刷刷响，两岸芦苇长又长。陪嫁姑娘身材高，随从男士貌堂堂！', '[{"bookId": "60fccb5034bfda01e0ea02ff", "bookTitle": "先秦诗鉴赏辞典（新一版）", "articleId": "610f37455e272d4b22559fce", "shortContent": "阅罢《硕人》，这幅妙绝千古的“美人图”，留给人们最鲜活的印象，无疑是那倩丽的巧笑、流盼的美目———即“巧笑倩兮，美目盼兮”。\n不错，《硕人》通篇用了铺张手法，不厌其烦地吟唱了有关“硕人”的方方面面，如第一章主要说她的出身———她的三亲六戚，父兄夫婿，皆是当时各诸侯国有权有势的头面人物，她无疑是一位门第高华的贵夫人。第三、四章主要写婚礼的隆重和盛大，特别是第四章，七句之中，竟连续六句用了叠字。那洋洋...", "authors": ["萧华荣"], "pressName": "上海辞书出版社"}, {"bookId": "627298aa34359466e82f44e0", "bookTitle": "诗经鉴赏辞典", "articleId": "63126fe07ccdb86c49f29159", "shortContent": "这是庄姜初嫁之诗。\n全诗四章。一章写庄姜出身高贵。她身材高大，仪态端庄。身着锦衣罩衫，更衬出她的美丽。她是齐侯的公主，卫侯的夫人，齐太子得臣的妹妹，邢侯夫人的姊妹，谭国君主则是她的妹夫。二章写庄姜容貌美丽。她的手像初生的茅芽一样细软，皮肤像凝固的脂膏一样洁白，脖子像蜗牛颈子一样柔嫩，牙齿像瓠瓜子儿一样整齐。她前额宽广而方正，眉毛弯长而秀美。她轻巧一笑现酒窝，美丽的眼睛黑白分明，波光流动，美好无比。...", "authors": [], "pressName": "崇文书局"}, {"bookId": "642074e9995d79753170c75a", "bookTitle": "诗经三百篇鉴赏辞典", "articleId": "645e21aa7da2f75ac7cd3781", "shortContent": "阅罢《硕人》，这幅妙绝千古的“美人图”，留给人们最鲜活的印象，无疑是那倩丽的巧笑，流盼的美目——即“巧笑倩兮，美目盼兮”。\n\n不错，《硕人》通篇用了铺张手法，不厌其烦地吟唱了有关“硕人”的方方面面，如第一章主要说她的出身——她的三亲六戚，父兄夫婿，皆是当时各诸侯国有权有势的头面人物，她无疑是一位门第高华的贵夫人。第三、四章主要写婚礼的隆重和盛大，特别是第四章，七句之中，竟连续六句用了叠字。那洋洋洒...", "authors": ["萧华荣"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b599bc98d685fd9d8a5a7", "shortContent": "《硕人》是《卫风》的第三篇，全诗四章，主旨在于“闵庄姜”。庄姜是卫庄公的妃子，从卫庄公在位的时间（前759—前735）来看，这首诗大致作于公元前8世纪中叶。因为“庄公惑于嬖妾，使骄上僭。庄姜贤而不答，终以无子，国人闵而忧之（《毛诗序》）”。这段史实《左传·鲁隐公三年》中也有相同的记载，“卫庄公娶于齐东宫得臣之妹，曰庄姜。美而无子，卫人所为赋《硕人》也”。人们往往对美好的事物得不到珍惜和爱护寄予深深...", "authors": ["张传友"], "pressName": "上海辞书出版社"}]', '', 'indent', 1445533687, '57b90002df0eea006334dc12', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10318, '菩萨蛮', NULL, 478, 394, 4, 4, '温庭筠', NULL, 10069, '57b93da179bc44005ba0a318', '唐', 'ci', '词', 'http://baike.baidu.com/item/菩萨蛮·小山重叠金明灭', '', '小山重叠金明灭，鬓云欲度香腮雪。懒起画蛾眉，弄妆梳洗迟。
照花前后镜，花面交相映。新帖绣罗襦，双双金鹧鸪。', '这首《菩萨蛮》，为了适应宫廷歌伎的声口，也为了点缀皇宫里的生活情趣，把妇女的容貌写得很美丽，服饰写得很华贵，体态也写得十分娇柔，彷彿描绘了一幅唐代仕女图。
词学专家周汝昌先生认为：此篇通体一气。精整无隻字杂言，所写只是一件事，若为之拟一题目增入，便是「梳妆」二字。领会此二字，一切迎刃而解。而妆者，以眉为始；梳者，以鬓为主；故首句即写眉，次句即写鬓。
小山，眉妆之名目，晚唐五代，此样盛行，见于《海录碎事》，为「十眉」之一式。大约「眉山」一词，亦因此起。眉曰小山，也时时见于当时词中，如五代蜀秘书监毛熙震《女冠子》云：「修蛾慢脸（脸，古义，专指眼部），不语檀心一点（檀心，眉间额妆，双关语），小山妆。」正指小山眉而言。又如同时孙孟文《酒泉子》云：「玉纤（手也）淡拂眉山小，镜中嗔共照。翠连娟，红缥缈，早妆时。」亦正写晨妆对镜画眉之情景。可知小山本谓淡扫蛾眉，实与韦庄《荷叶杯》所谓「一双愁黛远山眉」同义。
旧解多以小山为「屛」，其实未允。此由（1）不知全词脉络，误以首句与下无内在联系；（2）不知「小山」为眉样专词，误以为此乃「小山屛」之简化。又不知「叠」乃眉蹙之义，遂将「重叠」解为重重叠叠。然「小山屛」者，译为今言，谓「小小的山样屛风」也，故「山屛」即为「屛山」，为连词，而「小」为状词；「小」可省减而「山屛」不可割裂而止用「山」字。既以「小山」为屛，又以「金明灭」为日光照映不定之状，不但「屛」「日」全无着落，章法脉络亦不可寻矣。
重，在诗词韵语中，往往读平声而义为去声，或者反是，全以音律上的得宜为定。此处声平而义去，方为识音。叠，相当于蹙眉之蹙字义，唐诗有「双蛾叠柳」之语，正此之谓。金，指唐时妇女眉际妆饰之「额黄」，故诗又有「八字宫眉捧额黄」之句，其良证也。
已将眉喻为山，再将鬓喻为云，再将腮喻为雪，是谓文心脉络。盖晨间闺中待起，其眉蹙锁，而鬓已散乱，其披拂之发缕，掩于面际，故上则微掩眉端额黄，在隐现明灭之间；下则欲度腮香，——度实亦微掩之意。如此，山也，金也，云也，雪也，构为一幅春晓图，十分别致。
上来两句所写，待起未起之情景也。故第三句紧接懒起，起字一逗——虽曰懒起，并非不起，是娇懒迟迟而起也。闺中晓起，必先梳妆，故「画蛾眉」三字一点题——正承「小山」而来。「弄妆」再点题，而「梳洗」二字又正承鬓之腮雪而来。其双管并下，脉络最清。然而中间又着一「迟」字，远与「懒」相为呼应，近与「弄」字互为注解。「弄」字最奇，因而是一篇眼目。一「迟」字，多少层次，多少时光，多少心绪，多少神情，俱被此一字包尽矣。
梳妆虽迟，终究须有完毕之日，故过片重开，即写梳妆已罢，最后以两镜前后对映而审看梳妆是否合乎标准。其前镜，妆台奁内之座镜也；其后镜，手中所持之柄镜也——俗呼「把儿镜」。所以照者，为看两鬓簪花是否妥恰，而两镜之交，「套景」重叠，花光之与人面，亦交互重叠，至于无数层次！以十个字写此难状之妙景，尽得神理，实为奇绝之笔。
词笔至此，写梳妆题目已尽其能事了，后面又忽有两句，又不知为何而设？新贴，新鲜之「花样子」也，剪纸为之，贴于绸帛之上，以为刺绣之「蓝本」者也。盖言梳妆既妥，遂开始一日之女红：刺绣罗襦，而此新样花贴，偏偏是一双一双的的鹧鸪图纹。闺中之人，见此图纹，不禁有所感触。此处之所感所触，乃与开头之山眉深蹙，梦起迟妆者相应。由此一例足见飞卿词极工于组织联络，回互呼应之妙。', '小山：眉妆的名目，指小山眉，弯弯的眉毛。另外一种理解为：小山是指屛风上的图案，由于屛风是折叠的，所以说小山重叠。金：指唐时妇女眉际妆饰之「额黄」。
金明灭：形容阳光照在屏风上金光闪闪的样子。一说描写女子头上插戴的饰金小梳子重叠闪烁的情形，或指女子额上涂成梅花图案的额黄有所脱落而或明或暗。明灭，隐现明灭的样子。
鬓云：像云朵似的鬓发。形容发髻蓬松如云。
度：覆盖，过掩，形容鬓角延伸向脸颊，逐渐轻淡，像云影轻度。
欲度：将掩未掩的样子。
香腮雪：香雪腮，雪白的面颊。
蛾眉：女子的眉毛细长弯曲像蚕蛾的触须，故称蛾眉。一说指元和以后叫浓阔的时新眉式「蛾翅眉」。
弄妆：梳妆打扮，修饰仪容。
罗襦：丝绸短袄。
鹧鸪：贴绣上去的鹧鸪图，这说的是当时的衣饰，就是用金线绣好花样，再绣贴在衣服上，谓之「贴金」。', '眉妆漫染，叠盖了部分额黄，鬓边发丝飘过。洁白的香腮似雪，懒得起来，画一画蛾眉，整一整衣裳，梳洗打扮，慢吞吞，意迟迟。
照一照新插的花朵，对了前镜，又对后镜，红花与容颜，交相辉映，刚穿上的绫罗裙襦，绣着一双双的金鹧鸪。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e7488dbb8b379ee08dd88", "shortContent": "飞卿为晚唐诗人，而《菩萨蛮》十四首乃是词史上的一段丰碑，雍容绮绣，罕见同俦，影响后来，至为深远，盖曲子词本是民间俗唱与乐工俚曲，士大夫偶一拈弄，不过花间酒畔，信手消闲，不以正宗文学视之。至飞卿此等精撰，始有意与刻意为之，词之为体方得升格，文人精意，遂兼入填词，词与诗篇分庭抗礼，争华并秀。\n本篇通体一气，精整无只字杂言，所写只是一件事，若为之拟一题目增入，便是“梳妆”二字。领会此二字，一切迎刃而解。...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892c508c9c030fd725d3", "shortContent": "飞卿为晚唐诗人，而《菩萨蛮》十四首乃是词史上的一段丰碑，雍容绮绣，罕见同俦，影响后来，至为深远，盖曲子词本是民间俗唱与乐工俚曲，士大夫偶一拈弄，不过花间酒畔，信手消闲，不以正宗文学视之。至飞卿此等精撰，始有意与刻意为之，词之为体方得升格，文人精意，遂兼入填词，词与诗篇分庭抗礼，争华并秀。\n\n本篇通体一气，精整无只字杂言，所写只是一件事，若为之拟一题目增入，便是“梳妆”二字。领会此二字，一切迎刃而解...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277f1855b7e9043f114440e", "bookTitle": "温庭筠词全集", "articleId": "63126e8f7ccdb86c49f28f9e", "shortContent": "《菩萨蛮》，又名《菩萨鬘》《子夜歌《重叠金》《巫山一段云》《城里钟》《花间意》《花溪碧》《梅花句》《晚云烘日》。本为唐教坊曲，后用为词牌，属于小令。此调前人以为创于唐宣宗时，因女蛮国派遣使者进贡，教坊而制此曲。唐人苏颚《杜阳杂编》卷下载，唐宣宗大中初（约847年），女蛮国入贡，来人梳高髻，戴金冠，号“菩萨蛮队”，当时艺人于是创制《菩萨蛮曲》。后来，成为宣宗最爱唱的词调，文人也多有仿作。全词双调八句...", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f313e7da2f75ac7147a44", "shortContent": "飞卿为晚唐诗人，而《菩萨蛮》十四首乃是词史上的一段丰碑，雍容绮绣，罕见同俦，影响后来，至为深远，盖曲子词本是民间俗唱与乐工俚曲，士大夫偶一拈弄，不过花间酒畔，信手消闲，不以正宗文学视之。至飞卿此等精撰，始有意与刻意为之，词之为体方得升格，文人精意，遂兼入填词，词与诗篇分庭抗礼，争华并秀。\n本篇通体一气，精整无只字杂言，所写只是一件事，若为之拟一题目增入，便是“梳妆”二字。领会此二字，一切迎刃而解。...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413128250, '57b6ed92a34131005f86d7de', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10319, '琵琶行', NULL, 2896, 2952, 6, 12, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/33438/10346184.htm', '元和十年，予左迁九江郡司马。明年秋，送客湓浦口，闻舟中夜弹琵琶者，听其音，铮铮然有京都声。问其人，本长安倡女，尝学琵琶于穆、曹二善才，年长色衰，委身为贾人妇。遂命酒，使快弹数曲。曲罢悯然，自叙少小时欢乐事，今漂沦憔悴，转徙于江湖间。予出官二年，恬然自安，感斯人言，是夕始觉有迁谪意。因为长句，歌以赠之，凡六百一十六言。命曰《琵琶行》。', '浔阳江头夜送客，枫叶荻花秋瑟瑟。
主人下马客在船，举酒欲饮无管弦。
醉不成欢惨将别，别时茫茫江浸月。
忽闻水上琵琶声，主人忘归客不发。
寻声暗问弹者谁，琵琶声停欲语迟。
移船相近邀相见，添酒回灯重开宴。
千呼万唤始出来，犹抱琵琶半遮面。
转轴拨弦三两声，未成曲调先有情。
弦弦掩抑声声思，似诉平生不得志。
低眉信手续续弹，说尽心中无限事。
轻拢慢捻抹复挑，初为《霓裳》后《六幺》。
大弦嘈嘈如急雨，小弦切切如私语。
嘈嘈切切错杂弹，大珠小珠落玉盘。
间关莺语花底滑，幽咽泉流冰下难。
冰泉冷涩弦凝绝，凝绝不通声暂歇。
别有幽愁暗恨生，此时无声胜有声。
银瓶乍破水浆迸，铁骑突出刀枪鸣。
曲终收拨当心画，四弦一声如裂帛。
东船西舫悄无言，唯见江心秋月白。
沉吟放拨插弦中，整顿衣裳起敛容。
自言本是京城女，家在虾蟆陵下住。
十三学得琵琶成，名属教坊第一部。
曲罢曾教善才服，妆成每被秋娘妒。
五陵年少争缠头，一曲红绡不知数。
钿头银篦击节碎，血色罗裙翻酒污。
今年欢笑复明年，秋月春风等闲度。
弟走从军阿姨死，暮去朝来颜色故。
门前冷落鞍马稀，老大嫁作商人妇。
商人重利轻别离，前月浮梁买茶去。
去来江口守空船，绕船月明江水寒。
夜深忽梦少年事，梦啼妆泪红阑干。
我闻琵琶已叹息，又闻此语重唧唧。
同是天涯沦落人，相逢何必曾相识！
我从去年辞帝京，谪居卧病浔阳城。
浔阳地僻无音乐，终岁不闻丝竹声。
住近湓江地低湿，黄芦苦竹绕宅生。
其间旦暮闻何物？杜鹃啼血猿哀鸣。
春江花朝秋月夜，往往取酒还独倾。
岂无山歌与村笛，呕哑嘲哳难为听。
今夜闻君琵琶语，如听仙乐耳暂明。
莫辞更坐弹一曲，为君翻作琵琶行。
感我此言良久立，却坐促弦弦转急。
凄凄不似向前声，满座重闻皆掩泣。
座中泣下谁最多？江州司马青衫湿。', '此诗通过对琵琶女高超弹奏技艺和她不幸经历的描述，揭露了封建社会官僚腐败、民生凋敝、人才埋没等不合理现象，表达了诗人对她的深切同情，也抒发了诗人对自己无辜被贬的愤懑之情。', '左迁：贬官，降职。与下文所言「迁谪」同义。古人尊右卑左，故称降职为左迁。
铮铮：形容金属、玉器等相击声。
京都声：指唐代京城流行的乐曲声调。
倡女：歌女。倡，古时歌舞艺人。
善才：当时对琵琶师或曲师的通称。是「能手」的意思。
委身：托身，这里指嫁的意思。
为：做。
贾（gǔ）人：商人。
命酒：叫（手下人）摆酒。
快：畅快。
漂沦：漂泊沦落。
出官：（京官）外调。
恬然：淡泊宁静的样子。
迁谪（zhé）：贬官降职或流放。
为：创作。
长句：指七言诗。
歌：作歌，动词。
凡：总共。
言：字。
命：命名，题名。
浔阳江：据考究，为流经浔阳城中的湓水，卽今江西省九江市中的龙开河（97年被人工填埋），经湓浦口注入长江。
荻（dí）花：多年生草本植物，生在水边，叶子长形，似芦苇，秋天开紫花。
瑟瑟：形容枫树、芦荻被秋风吹动的声音。
主人：诗人自指。
回灯：重新拨亮灯光。回：再。一说移灯。
掩抑：掩蔽，遏抑。
思：悲伤的情思。
信手：随手。
续续弹：连续弹奏。
拢：左手手指按弦向里（琵琶的中部）推。
捻：揉弦的动作。
抹：顺手下拨的动作
挑：反手回拨的动作。
《霓裳》：卽《霓裳羽衣曲》，本为西域乐舞，唐开元年间西凉节度使杨敬述依曲创声后流入中原。
《六幺》：大曲名，又叫《乐世》《绿腰》《录要》，为歌舞曲。
大弦：琵琶上最粗的弦。
嘈嘈：声音沉重抑扬。
小弦：琵琶上最细的弦。
切切：形容声音急切细碎。
间关：象声词，这里形容「莺语」声（鸟鸣婉转）
幽咽泉流冰下难：一作“幽咽流泉水下滩”。
幽咽：遏塞不畅状。
冰下难：泉流冰下阻塞难通，形容乐声由流畅变为冷涩。难，与滑相对，有涩之意。
凝绝：凝滞。
暂：一作「渐」。
暗恨：内心的怨恨。
迸：溅射。
曲终：乐曲结束。
当心画：用拔子在琵琶的中部划过四弦，是一曲结束时经常用到的右手手法。
帛：古时对丝织品的总称。
舫：船。
敛容：收敛（深思时悲愤深怨的）面部表情。
虾（há）蟆陵：「虾」通「蛤」。在长安城东南，曲江附近，是当时有名的游乐地区。
教坊：唐代管理宫廷乐队的官署。第一部：如同说第一团、第一队。
	曲罢曾教善才服：曾教，一作“常教”；服，一作“伏”。
秋娘：唐时歌舞妓常用的名字。泛指当时貌美艺高的歌伎。
五陵：在长安城外，指长陵、安陵、阳陵、茂陵、平陵五个汉代皇帝的陵墓，是当时富豪居住的地方。
缠头：用锦帛之类的财物送给歌舞妓女。指古代赏给歌舞女子的财礼，唐代用帛，后代用其他财物。
绡：精细轻美的丝织品。红绡：一种生丝织物。
钿（diàn）头：两头装着花钿的发篦.
银篦（bì）：一说「云篦」，用金翠珠宝装点的首饰。
击节：打拍子。歌舞时打拍子原本用木制或竹制的板
等闲：随随便便，不重视。
颜色故：容貌衰老。
浮梁：古县名，隶属饶州。在今江西省景德镇市，盛产茶叶。
去来：离别后。来，语气词。
梦啼妆泪：梦中啼哭，匀过脂粉的脸上带着泪痕。
红阑干：泪水融和脂粉流淌满面的样子。
重：重新，重又之意。
唧唧：叹声。
呕哑：拟声词，形容单调的乐声；嘲，通形容声音繁杂，也作啁哳。
嘲哳（zhāozhā）：卽「啁哳」，形容声音烦杂而细碎。《楚辞·九辩》：「雁廱廱而南游兮，鹍鸡啁哳而悲鸣。」洪练塘补注：「啁哳，声繁细貌。」
琵琶语：琵琶声，琵琶所弹奏的乐曲。
暂：突然，一下子。
却坐：退回到原处。
促弦：把弦拧得更紧。
向前声：刚才奏过的单调。
掩泣：掩面哭泣。
青衫：唐朝八品、九品文官的服色。白居易当时的官阶是将侍郎，从九品，所以服青衫。', '序：
唐宪宗元和十年，我被贬为九江郡司马。第二年秋季的一天，送客到湓浦口，夜里听到船上有人弹琵琶。听那声音，铮铮铿铿有京都流行的声韵。探问这个人，原来是长安的歌女，曾经向穆、曹两位琵琶大师学艺。后来年纪大了，红颜退尽，嫁给商人为妻。于是命人摆酒叫她畅快地弹几曲。她弹完后，有些闷闷不乐的样子，自己说起了少年时欢乐之事，而今漂泊沉沦，形容憔悴，在江湖之间辗转流浪。我离京调外任职两年来，随遇而安，自得其乐，而今被这个人的话所感触，这天夜里才有被降职的感觉。于是撰写一首长诗赠送给她，共六百一十六字，题为《琵琶行》。
正文：
秋夜我到浔阳江头送一位归客，冷风吹着枫叶和芦花秋声瑟瑟。
我和客人下马在船上饯别设宴，举起酒杯要饮却无助兴的音乐。
酒喝得不痛快更伤心将要分别，临别时夜茫茫江水倒映着明月。
忽听得江面上传来琵琶清脆声；我忘却了回归客人也不想动身。
寻着声源探问弹琵琶的是何人？琵琶停了许久却迟迟没有动静。
我们移船靠近邀请她出来相见；叫下人添酒回灯重新摆起酒宴。
千呼万唤她才缓缓地走出来，怀里还抱着琵琶半遮着脸面。
转紧琴轴拨动琴弦试弹了几声；尚未成曲调那形态就非常有情。
弦弦凄楚悲切声音隐含着沉思；似乎在诉说着她平生的不得志；
她低着头随手连续地弹个不停；用琴声把心中无限的往事说尽。
轻轻地拢，慢慢地捻，一会儿抹，一会儿挑。初弹《霓裳羽衣曲》接着再弹《六幺》。
大弦浑宏悠长嘈嘈如暴风骤雨；小弦和缓幽细切切如有人私语。
嘈嘈声切切声互为交错地弹奏；就像大珠小珠一串串掉落玉盘。
琵琶声一会儿像花底下宛转流畅的鸟鸣声，一会儿又像水在冰下流动受阻艰涩低沉、呜咽断续的声音。
好像水泉冷涩琵琶声开始凝结，凝结而不通畅声音渐渐地中断。
像另有一种愁思幽恨暗暗滋生；此时闷闷无声却比有声更动人。
突然间好像银瓶撞破水浆四溅；又好像铁甲骑兵厮杀刀枪齐鸣。
一曲终了她对准琴弦中心划拨；四弦一声轰鸣好像撕裂了布帛。
东船西舫人们都静悄悄地聆听；只见江心之中映着白白秋月影。
她沉吟着收起拨片插在琴弦中；整顿衣裳依然显出庄重的颜容。
她说我原是京城负有盛名的歌女；老家住在长安城东南的虾蟆陵。
弹奏琵琶技艺十三岁就已学成；教坊乐团第一队中列有我姓名。
每曲弹罢都令艺术大师们叹服；每次妆成都被同行歌妓们嫉妒。
京都豪富子弟争先恐后来献彩；弹完一曲收来的红绡不知其数。
钿头银篦打节拍常常断裂粉碎；红色罗裙被酒渍染污也不后悔。
年复一年都在欢笑打闹中度过；秋去春来美好的时光白白消磨。
兄弟从军姊妹死家道已经破败；暮去朝来我也渐渐地年老色衰。
门前车马减少光顾者落落稀稀；青春已逝我只得嫁给商人为妻。
商人重利不重情常常轻易别离；上个月他去浮梁做茶叶的生意。
他去了留下我在江口孤守空船；秋月与我作伴绕舱的秋水凄寒。
更深夜阑常梦少年时作乐狂欢；梦中哭醒涕泪纵横污损了粉颜。
我听琵琶的悲泣早已摇头叹息；又听到她这番诉说更叫我悲凄。
我们俩同是天涯沦落的可悲人；今日相逢何必问是否曾经相识！
自从去年我离开繁华长安京城；被贬居住在浔阳江畔常常卧病。
浔阳这地方荒凉偏僻没有音乐；一年到头听不到管弦的乐器声。
住在湓江这个低洼潮湿的地方；第宅周围黄芦和苦竹缭绕丛生。
在这里早晚能听到的是什么呢？尽是杜鹃猿猴那些悲凄的哀鸣。
春江花朝秋江月夜那样好光景；也无可奈何常常取酒独酌独饮。
难道这里就没有山歌和村笛吗？只是那音调嘶哑粗涩实在难听。
今晚我听你弹奏琵琶诉说衷情，就像听到仙乐眼也亮来耳也明。
请你不要推辞坐下来再弹一曲；我要为你创作一首新诗《琵琶行》。
被我的话所感动她站立了好久；回身坐下再转紧琴弦拨出急声。
凄凄切切不再像刚才那种声音；在座的人重听都掩面哭泣不停。
要问在座之中谁流的眼泪最多？我江州司马泪水湿透青衫衣襟！', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c72e6a6b501f95c360", "shortContent": "本题为《琵琶引并序》，“序”里却写作“行”。“行”和“引”，都是乐府歌辞的一体。“序”文如下：“元和十年（815），予左迁九江郡司马。明年秋，送客湓浦口。闻舟中夜弹琵琶者，听其音，铮铮然有京都声。问其人，本长安倡女。尝学琵琶于穆、曹二善才，年长色衰，委身为贾人妇。遂命酒使快弹数曲，曲罢，悯默。自叙少小时欢乐事，今漂沦憔悴，转徙于江湖间。予出官二年，恬然自安，感斯人言，是夕始觉有迁谪意。因为长句，歌...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad4797a92d5e4fd8ff", "shortContent": "本题为《琵琶引并序》，“序”里却写作“行”。“行”和“引”，都是乐府歌辞的一体。“序”文如下：“元和十年（815），予左迁九江郡司马。明年秋，送客湓浦口。闻舟中夜弹琵琶者，听其音，铮铮然有京都声。问其人，本长安倡女。尝学琵琶于穆、曹二善才，年长色衰，委身为贾人妇。遂命酒使快弹数曲，曲罢悯然。自叙少小时欢乐事，今漂沦憔悴，转徙于江湖间。予出官二年，恬然自安，感斯人言，是夕始觉有迁谪意。因为长句，歌以...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f09300", "shortContent": "唐元和十年（815），白居易被贬江州。第二年秋天，他在湓浦口（今江西九江市北）送客，遇到了一位来自长安城的嫁为商人妇的歌女。她为白居易一行弹奏了琵琶，引起了白居易深深的感慨。其感慨便化作了一首流传千古的杰作——《琵琶行》。\n\n诗歌可分为四段。第一段从开头到“犹抱琵琶半遮面”，写歌女的出场。开头的景物和情绪的渲染，是一派萧索的意境：浔阳江头，夜晚送客，枫叶荻花，带着浓浓的秋意。而主人与客人，醉不成欢...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270727f0b9738b369b232", "shortContent": "唐元和十年（815），白居易被贬江州（今江西九江）。第二年秋天，他在湓浦口送客，遇到了一位来自长安城的嫁为商人妇的歌女。她为白居易一行弹奏了琵琶，引起了白居易深深的感慨。其感慨便化作了一首流传千古的杰作——《琵琶行》。\n\n诗歌可分为四段。第一段从开头到“犹抱琵琶半遮面”，写歌女的出场。开头的景物和情绪的渲染，是一派萧索的意境：浔阳江头，夜晚送客，枫叶荻花，带着浓浓的秋意，而主人与客人，醉不成欢，别...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127122e6f69b71e93f63a3", "shortContent": "白居易因其政治主张与保守派和掌有军政大权的宦官集团有违，于元和十年（815）被贬到江州任司马一职，第二年秋天的一个傍晚，他送一个朋友到湓浦口。\n\n是夜，枫叶如霜染般殷红，像燃烧的烈火，似夏日里的火烧云。芦荻花是黄色的，瑟瑟的秋风吹来，它们发出索索的响声。白居易陪着朋友下马，来到船中，两个人举着酒杯依依惜别，愁苦的情绪始终萦绕心头，只恨没有音乐为这样的夜晚伴奏一曲，有的只是江面上一轮明晃晃的月亮，随...", "authors": ["王萍"], "pressName": "崇文书局"}, {"bookId": "645d09bbec56251f2eeb5b78", "bookTitle": "白居易诗文鉴赏辞典", "articleId": "646245525e6bb82b8cba4744", "shortContent": "本题为《琵琶引并序》,“序”里却写作“行”。“行”和“引”，都是乐府歌辞的一体。“序”文如下：“元和十年（815），予左迁九江郡司马。明年秋，送客湓浦口。闻舟中夜弹琵琶者，听其音，铮铮然有京都声。问其人，本长安倡女。尝学琵琶于穆、曹二善才，年长色衰，委身为贾人妇。遂命酒使快弹数曲，曲罢，悯默。自叙少小时欢乐事，今漂沦憔悴，转徙于江湖间。予出官二年，恬然自安，感斯人言，是夕始觉有迁谪意。因为长句，歌...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f2fed5fc8182fe9cb00af", "shortContent": "《琵琶行》和《长恨歌》是各有独创性的名作。早在作者生前，已经是“童子解吟《长恨》曲，胡儿能唱《琵琶》篇”。此后，一直传诵国内外，显示了强大的艺术生命力。\n如“序”中所说，诗里所写的是作者由长安贬到九江期间在船上听一位长安故倡弹奏琵琶、诉说身世的情景。\n宋人洪迈认为夜遇琵琶女事未必可信，作者是通过虚构的情节，抒发他自己的“天涯沦落之恨”（《容斋随笔》卷七），这是抓住了要害的。但那虚构的情节既然真实地...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '杨升菴：「枫叶荻花秋瑟瑟」，此句绝妙。枫叶红，荻花白，映秋色碧也。
苏子美：「夜深忽梦少年事，觉来粉泪红阑干」，此联真佳句。
陈章侯：十分情十分说出，能令有情者皆为之死。
《容斋五笔》：白乐天《琵琶行》一篇，读者但羡其风致，敬其词章，至形于乐府，咏歌之不足，遂以谓真为长安故倡所作。予窃疑之。唐世法纲虽于此为宽，然乐天曾居禁密，且谪居未久，必不肯乘夜入独处妇人船中，相从饮酒；至于极弹丝之乐，中夕方去。岂不虞商人者它日议其后乎？乐天之意，直欲抒写天涯沦落之恨尔。
《朱子语类》：白乐天《琵琶行》云：「嘈嘈切切错杂弹，大珠小珠落玉盘」云云，这是和而淫。至「凄凄不似向前声，满座重闻皆掩泣」，这是淡而伤。
《唐诗援》：初唐人喜为长篇，大率以词采相高而乏神韵。至元、白，去其排比，而仍踵其拖沓。惟《连昌宫词》直陈时事，可为龟鉴；《琵琶行》情文兼美，故特取之。
《批选唐诗》：以诗代叙记情兴，曲折婉转，《连昌宫词》正是伯仲。
《唐诗镜》：乐天无简炼法，故觉顿挫激昂为难。
《唐诗归》：锺云：以此说曲罢，情理便深（「水泉冷涩」二句下）。锺云：唤醒人语，不怕说得败兴（「门前冷落」二句下）。锺云：止此妙，亦似多后一段（「同是天涯」二句下）。
《唐诗解》：《连昌》纪事，《琵琶》叙情，《长恨》讽刺，并长篇之胜，而高、李弗录。余采而笺释之，俾学者有所观法焉。
《唐诗选脉会通评林》：唐汝询日：此乐天宦游不遂，因琵琶以托兴也。「饮无管弦」，埋琵琶话头。一篇之中，「月」字五见，「秋月」三用，各自有情，何尝厌重！「声沉欲语迟」，「沉」字细，若作「停」字便浅；「欲语迟」，形容妙绝。「未成曲调先有情」，「先有情」三字，一篇大机括。「弦弦掩抑」下四语总说，情见乎辞。「大弦」以下六语，写琵琶声响，曲穷其妙。「水泉冷涩」四语，传琵琶之神。「银瓶」二语，已歇而复振，是将罢时光景。「唯见江心秋月白」，收用冷语，何等有韵！「自言本是京城女」下二十二句，商妇自诉之词，甚夸、甚戚，曲尽青楼情态。「同是天涯」三旬，锺伯（敬）谓：「止此，妙；亦似多后一段。」若止，乐天本意，何处发舒？惟以沦落人「转入迁谪，何等相关」！香山善铺叙，繁而不冗，若百衲衣手段，如何学得？陆时雍日：形容仿佛。又日：作长歌须得崩浪奔雷、蓦涧腾空之势，乃佳；乐天只一平铺次第。
《野鸿诗的》：香山《琵琶行》婉折周详，有意到笔随之妙，篇中旬亦警拔。音节靡靡，是其一生短处，非独是诗而已。
《中晚唐诗叩弹集》：庭珠按：以上琵琶妇自叙；下，乐天自言迁谪之感也（「梦啼妆泪」句下）。
《古欢堂集杂著》：余尝谓白香山《琵琶行》一篇，从杜子美《观公孙大娘弟子舞剑器行》诗得来。「临颍美人在白帝，妙舞此曲神扬扬。与余问答既有以，感时抚事增惋伤。」杜以四语，白成数行，所谓演法也。凫胫何短，鹤胫何长，续之不能，截之不可，各有天然之致；不惟诗也，文亦然。
《蕙榜杂记》：予曏读吴梅村《琵琶行》，喜其浏离顿挫，谓胜白文公《琵琶行》，久而知其谬也。白诗开手便从江头送客说到闻琵琶，此直叙法也。吴诗先将琵琶铺陈一段，便成空套。
《而菴说唐诗》：此篇铺叙甚佳，语多情至，顿挫之法颇有。若较子美之陡健，相去远矣。滥觞从此始。「琵琶声停欲语迟」，「欲语迟」宛然妇人行径矣。「枫叶荻花秋瑟瑟」，人知是写景，而不知是写秋。古人作长篇，法有详略。此篇纯用详法，此乐天短处也（「转轴拨弦」句下）。「未成曲调先有情」，司马迁谪，复当别离，此乐天之情也；嫁与商人，不得遂意，此妇人之情也。大家暗暗相关。此诗是乐天听过琵琶曲从亮处做的。「其问旦暮闻何物」作问辞，句法变，方无直下之病。「春江花朝秋月夜，往往取酒还独饮。」要知乐天不是单对妇人自叙，还有所送之客在此。正是眼光向客处。此二句妙甚。
《唐诗别裁》：写同病相怜之意，侧侧动人。
《唐贤小三昧集》：感商妇之飘流，叹谪居之沦落，凄婉激昂，声能引泣。
《精选评注五朝诗学津梁》：结以两相叹感收之，此行似江潮涌雪，馀波荡漾，有悠然不尽之妙。凡作长题，步步映衬，处处点缀，组织处，悠扬处，层出不穷，笔意鲜艳无过白香山者。
《唐宋诗醇》：满腔迁谪之感，借商妇以发之，有同病相怜之意焉。比兴相纬，寄托遥深，其意微以显，其意哀以思，其辞丽以则。《十九首》云：「清商随风发，中曲正徘徊。一弹再三叹，慷慨有馀哀。」及杜甫《观公孙大娘弟子舞剑器行》与此篇同为千秋绝调，不必以古近前后分也。
《网师园唐诗笺》：为下二段伏线（「醉不成欢」二句下）。即声暂歇时言（「此时无声」旬下）。应首段作一束（「惟见江心」句下）。映上重作一束，为文章留顿法（「绕船月明」旬下）。双收上二段，转到自己（「同是天涯」二句下）。自叙踪迹与起处相应（「其间旦暮」句下）。此诗及《长恨歌》，诸家选本率与元微之《连昌宫词》并存。然细玩之，虽同是洋洋大篇，而情辞斐叠无伦，元词之远不逮白歌。即此与李毫州之悲善才，并为闻琵琶作，而亦有仙凡之判，醐不但以人品高下为去取也。
《岘俯说涛》：《琵琶行》较有情味，然「我从去年」一段又嫌繁冗，如老妪向人谈旧事，叨叨絮絮，厌读而不肯休也。', 'indent', 1416840335, '57adcb22a341310060ea34ef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10320, '虞美人 · 寄公度', NULL, 206, 196, 1, 2, '舒亶', NULL, 10084, '57b9c0468ac2470063ff2aae', '宋', 'ci', '词', 'http://baike.baidu.com/view/1094547.htm', '', '芙蓉落尽天涵水，日暮沧波起。背飞双燕贴云寒，独向小楼东畔、倚阑看。
浮生只合尊前老，雪满长安道。故人早晚上高台，赠我江南春色、一枝梅。', '宋神宗元丰六年（公元1083年），舒亶因与尚书省意见相左逐出京城，在家赋闲十年后，再次被任用。但入京后却已是物是人非，不由得对自己的身世感到孤独和凄凉并且渴望友人的信息，于是创作了这首词并寄予一为字为公度的友人。或以为此词题中的公度为黄公度，非是。黄公度生于宋徽宗大观三年（公元1109年），其时舒亶已去世六年。《全宋词》收舒亶词中有《蝶恋花》调，题为「置酒别公度座间探题得梅」。其词云：「折向樽前君细看，便是江南，寄我人还远。手把此枝多少怨。小楼横笛吹肠断。」又有《醉花阴》调，题为「越州席上官妓献梅花」。其词云：「月幌风帘香一阵，正千山雪尽。冷对酒樽旁，无语含情，别是江南信。」因此，这位叫公度的作者友人，可能是越州一带的官员。作者在越州及北上之前，都曾有席上献梅得梅之事，并与当时的饮酒狎妓生活有关。', '芙蓉：指荷花。
涵：包含，包容。
沧：暗绿色（指水）。
背飞双燕：双燕相背而飞。此处有劳燕分飞、朋友离别的意思。
阑：栏杆。
合：应该。
尊：同「樽」，酒杯。
「故人早晚上高台，赠我江南春色一枝梅」句：用陆凯赠梅与范晔事。《荆州记》：「陆凯与范晔交善，自江南寄梅花一枝，诣长安与晔，曾赠诗……」诗云：「折梅逢驿使，寄与陇头人。江南无所有，聊赠一枝春。」此处化用其意。', '芙蓉都已凋落，远天涵着近水，苍茫一片，黄昏时秋风阵阵，涌起波澜。我独自在小楼东畔，久久地倚着栏杆，看分飞的双燕各自东西，远远向寒云飞去，引起我一怀愁绪。
浮生有多少难以消释的烦恼，真应该在醉乡中老去。光阴荏苒，京城又盖满纷纷大雪。我的朋友，你时时都会登上高台把我怀想，你将寄给我一枝梅花，饱含着美丽的江南春光。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b603048e64fbd89345", "shortContent": "这是一首寄赠友人的词。一本无“寄公度”的词题。公度，或谓即黄公度，字师宪，莆田（今属福建）人，非是。黄公度生于徽宗大观三年（1109），时舒亶卒已六年。此“公度”似友人之字，其人俟考。\n上片写日暮登楼所见。“芙蓉落尽天涵水，日暮沧波起。”芙蓉，即荷花。荷花落尽，时当夏末秋初。秋风江上，日暮远望，水天相接，烟波无际；客愁离思，亦随烟波荡漾而起。这两句视野开阔，而所见秋风残荷、落日沧波等外景，则透示出...", "authors": ["吴战垒"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5be03572034f65a8b4c", "shortContent": "这是一首寄赠友人的词。一本无“寄公度”的词题。公度，或谓即黄公度，字师宪，莆田（今属福建）人，非是。黄公度生于徽宗大观三年（1109），时舒亶卒已六年。此“公度”似友人之字，其人俟考。\n上片写日暮登楼所见。“芙蓉落尽天涵水，日暮沧波起。”芙蓉，即荷花。荷花落尽，时当夏末秋初。秋风江上，日暮远望，水天相接，烟波无际；客愁离思，亦随烟波荡漾而起。这两句视野开阔，而所见秋风残荷、落日沧波等外景，则透示出...", "authors": ["吴战垒"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3f7ccdb86c49f290cb", "shortContent": "《虞美人》是一首寄赠友人的词，写于新法失败后舒亶遭贬谪期间。此时的舒亶经历了“乌台诗案”和“车盖亭诗案”，其诗词在政治上的表达已经很少，更多的是与世隔绝、清逸自然的风格。\n\n上片写日暮登楼所见。“芙蓉落尽”二句写景。木芙蓉开于晚秋，童谣有“十月芙蓉正上妆”，“落尽”二字点明时值秋末冬初。需要注意的是，此处极易为世人所误解，吴战垒言此词中芙蓉为“荷花”（《唐宋词鉴赏辞典》，上海辞书出版社1988年版...", "authors": ["杨乐娟"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127030c26cbf3417f09467", "shortContent": "《虞美人》是一首寄赠友人的词，写于新法失败后舒亶遭贬谪期间。此时的舒亶经历了“乌台诗案”和“车盖亭诗案”，其诗词在政治上的表达已经很少，更多的是与世隔绝、清逸自然的风格。\n\n上片写日暮登楼所见。“芙蓉落尽”二句写景。木芙蓉开于晚秋，童谣有“十月芙蓉正上妆”，“落尽”二字点明时值秋末冬初。需要注意的是，此处极易为世人所误解，吴战垒言此词中芙蓉为“荷花”（《唐宋词鉴赏辞典》，上海辞书出版社1988年版...", "authors": ["杨乐娟"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271abc9ebcc6fbea1a4f9", "shortContent": "《虞美人》是一首寄赠友人的词，写于新法失败后舒亶遭贬谪期间。此时的舒亶经历了“乌台诗案”和“车盖亭诗案”，其诗词在政治上的表达已经很少，更多的是与世隔绝、清逸自然的风格。\n上片写日暮登楼所见。“芙蓉落尽”二句写景。木芙蓉开于晚秋，童谣有“十月芙蓉正上妆”，“落尽”二字点明时值秋末冬初。需要注意的是，此处极易为世人所误解，吴战垒言此词中芙蓉为“荷花”（《唐宋词鉴赏辞典》，上海辞书出版社1988年版）...", "authors": ["杨乐娟"], "pressName": "崇文书局"}]', '丁绍仪《听秋声馆词话》：纵不识字，亦知是天生好语。
谭莹《论词绝句一百首》：名推菩萨蛮词好，实使东坡到海南。各各赏者同此调，我朝贻上宋花庵。
朱祖谋：如此等雅词，倘出太虚（秦观）、无咎（晁补之）之手，便觉神骨俱仙，乃辱以舒信道乎。', 'indent', 1363291934, '57b945857db2a2005428f5f0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10321, '鹊桥仙', NULL, 2388, 590, 4, 10, '秦观', NULL, 10085, '57b927b7d342d3005ac872a6', '宋', 'ci', '词', 'http://baike.baidu.com/view/1098541.htm', '', '纤云弄巧，飞星传恨，银汉迢迢暗度。金风玉露一相逢，便胜却人间无数。
柔情似水，佳期如梦，忍顾鹊桥归路。两情若是久长时，又岂在朝朝暮暮？', '此词是一首爱情颂歌，上片写牛郎织女聚会，下片写他们的离别。全词哀乐交织，融抒情与议论于一炉，融天上人间为一体，优美的形象与深沉的感情结合起来，起伏跌宕地讴歌了美好的爱情。此词议论自由流畅，通俗易懂，却又显得婉约蕴藉，馀味无穷，尤其是末二句，使词的思想境界升华到一个崭新的高度。', '纤云：轻盈的云彩。
弄巧：指云彩在空中幻化成各种巧妙的花样。
飞星：流星。一说指牵牛、织女二星。
银汉：银河。
迢迢：遥远的样子。
暗度：悄悄渡过。
金风玉露：指秋风白露。李义山《辛未七夕》：“恐是仙家好别离，故教迢递作佳期。由来碧落银河畔，可要金风玉露时。”
忍顾：怎忍回视。
朝朝暮暮：指朝夕相聚。语出宋玉《高唐赋》。', '纤薄的云彩在天空中变幻多端，天上的流星传递着相思的愁怨，遥远无垠的银河今夜我悄悄渡过。在秋风白露的七夕相会，就胜过尘世间那些长相厮守却貌合神离的夫妻。
共诉相思，柔情似水，短暂的相会如梦如幻，分别之时不忍去看那鹊桥路。只要两情至死不渝，又何必贪求卿卿我我的朝欢暮乐呢。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74bc03048e64fbd89369", "shortContent": "“七夕”是一个美好而又充满神话色彩的节日。杜牧《七夕》诗云：“天阶夜色凉如水，卧看牵牛织女星。”相传这天夜晚（阴历七月初七）是分居银河两侧的牛郎织女，一年一度相会的日子。织女是织造云锦的巧手，所以，这天夜晚，天空的云彩特别好看。旧时风俗，少女们要于此夜陈设瓜果，朝天礼拜，向织女“乞巧”。这个汉魏以来就流传着的美丽神话，引起了古往今来多少诗人的咏叹。其中能长久地脍炙人口，传诵不衰的绝唱，则要推秦少游...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5c234a8757d5a0ecaae", "shortContent": "“七夕”是一个美好而又充满神话色彩的节日。杜牧《七夕》诗云：“天阶夜色凉如水，卧看牵牛织女星。”相传这天夜晚（阴历七月初七）是分居银河两侧的牛郎织女，一年一度相会的日子。织女是织造云锦的巧手，所以，这天夜晚，天空的云彩特别好看。旧时风俗，少女们要于此夜陈设瓜果，朝天礼拜，向织女“乞巧”。这个汉魏以来就流传着的美丽神话，引起了古往今来多少诗人的咏叹。其中能长久地脍炙人口，传诵不衰的绝唱，则要推秦少游...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253ccce4d48ba496d9b", "shortContent": "“七夕”是一个美好而又充满神话色彩的节日。杜牧《七夕》诗云：“天阶夜色凉如水，卧看牵牛织女星。”相传这天夜晚（阴历七月初七）是分居银河两侧的牛郎织女一年一度相会的日子。织女是织造云锦的巧手，所以，这天夜晚，天空的云彩特别好看。旧时风俗，少女们要于此夜陈设瓜果，朝天礼拜，向织女“乞巧”。这个汉魏以来就流传着的美丽神话，引起了古往今来多少诗人的咏叹。其中能长久地脍炙人口、传诵不衰的绝唱，则要推秦少游这...", "authors": ["高　原"], "pressName": "上海辞书出版社"}, {"bookId": "6277f3fb5b7e9043f1144c57", "bookTitle": "秦观词全集", "articleId": "63126e5ae6f69b71e93f6094", "shortContent": "本篇为宋词名篇，也是少游诸作中最负盛名者之一。由古及今，借牛郎织女故事表现人世悲欢离合的诗词作品难以胜计，虽遣词造句各异，却大略不出“欢娱苦短”的格套，情深恨长，凄楚哀婉。比较之下，少游此作不落常套，独出机抒，熔抒情、写景、议论于一炉，既自然流畅又婉约蕴藉，堪称不世出之佳构。观其眼界之阔，胸次之旷，气度之达，在少游集中实属仅见，依此推想，或为元丰八年进士及第，正“春风得意马蹄疾”时所为作。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645d137a7af6de164710138d", "bookTitle": "秦观诗词鉴赏辞典", "articleId": "6469d7a130675327e19eaa15", "shortContent": "“七夕”是一个美好而又充满神话色彩的节日。杜牧《七夕》诗云：“天阶夜色凉如水，卧看牵牛织女星。”相传这天夜晚（阴历七月初七）是分居银河两侧的牛郎织女，一年一度相会的日子。织女是织造云锦的巧手，所以，这天夜晚，天空的云彩特别好看。旧时风俗，少女们要于此夜陈设瓜果，朝天礼拜，向织女“乞巧”。这个汉魏以来就流传着的美丽神话，引起了古往今来多少诗人的咏叹。其中能长久地脍炙人口，传诵不衰的绝唱，则要推秦少游...", "authors": ["高原"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f345a82772d45941d05c0", "shortContent": "“七夕”是一个美好而又充满神话色彩的节日。杜牧《七夕》诗云：“天阶夜色凉如水，卧看牵牛织女星。”相传这天夜晚（阴历七月初七）是分居银河两侧的牛郎织女，一年一度相会的日子。织女是织造云锦的巧手，所以，这天夜晚，天空的云彩特别好看。旧时风俗，少女们要于此夜陈设瓜果，朝天礼拜，向织女“乞巧”。这个汉魏以来就流传着的美丽神话，引起了古往今来多少诗人的咏叹。其中能长久地脍炙人口，传诵不衰的绝唱，则要推秦少游...", "authors": ["高原"], "pressName": "上海辞书出版社"}]', '沈震峰：（世人咏）七夕，往往以双星会少离多为恨，而此词独谓情长不在朝暮，化腐臭为神奇！
李沧溟：相逢胜人间，会心之语。两情不在朝暮，破格之谈。七夕歌以双星会少别多为恨，独少游此词谓“两情若是久长”二句，最能醒人心目。
黄苏《蓼园词选》：七夕歌以双星会少别多为恨，少游此词谓两情若是久长，不在朝朝暮暮，所谓化臭腐为神奇。凡咏古题，须独出心裁，此固一定之论。少游以坐党被谪，思君臣际会之难，因托双星以写意，而慕君之念，婉侧缠绵，令人意远矣。', 'indent', 1363292349, '57b2b3c1165abd0054369cf8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (360829, '潇湘神', NULL, 0, 644, 0, 1, '易顺鼎', NULL, 21499, '5858ef778e450a006cba8491', '清', 'ci', '词', NULL, NULL, '潇水波。湘水波。
月明唱起竹枝歌。万艳万愁呼欲出，湘花颜色似湘娥。', NULL, NULL, NULL, NULL, NULL, 'indent', 1543406328, '585e93f1570c3500693b401e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10322, '踏莎行 · 郴州旅舍', NULL, 405, 590, 4, 3, '秦观', NULL, 10085, '57b927b7d342d3005ac872a6', '宋', 'ci', '词', 'http://baike.baidu.com/view/1259223.htm', '', '雾失楼台，月迷津渡。桃源望断无寻处。可堪孤馆闭春寒，杜鹃声里斜阳暮。
驿寄梅花，鱼传尺素。砌成此恨无重数。郴江幸自绕郴山，为谁流下潇湘去。', '此词大约作于绍圣四年（公元1097年）春三月作者初抵郴州之时。词人因党争遭贬，远徙郴州（今属湖南），精神上倍感痛苦。词写客次旅舍的感慨：上阕写谪居中寂寞凄冷的环境；下阕由叙实开始，写远方友人殷勤致意、安慰。全词以委婉曲折的笔法，抒写了失意人的凄苦和哀怨的心情，流露了对现实政治的不满。', '郴（chēn）州：今属湖南。
雾失楼台：暮霭沉沉，楼台消失在浓雾中。
月迷津渡：月色朦胧，渡口迷失不见。
桃源：语出晋·陶渊明《桃花源记》，指生活安乐、合乎理想的地方。
无寻处：找不到。
「桃源望断无寻处」句：拼命寻找也看不见理想的桃花源。
可堪：怎堪，哪堪，受不住。
杜鹃：鸟名，相传其鸣叫声像人言「不如归去」，容易勾起人的思乡之情。
驿寄梅花：陆凯《赠范晔诗》：「折梅逢驿使，寄与陇头人。江南无所有，聊寄一枝春。」这里作者是将自己比作范晔，表示收到了来自远方的问候。
鱼传尺素：东汉·蔡邕《饮马长城窟行》：「客从远方来，遗我双鲤鱼。呼儿烹鲤鱼，中有尺素书。」另外，古时舟车劳顿，信件很容易损坏，古人便将信件放入匣子中，再将信匣刻成鱼形，美观而又方便携带。「鱼传尺素」成了传递书信的又一个代名词。这里也表示接到朋友问候的意思。
砌：堆积。无重数：数不尽。
郴（chēn）江：清·顾祖禹《读史方舆纪要·湖广》载：郴水在「州东一里，一名郴江，源发黄岑山，北流经此……下流会来水及自豹水入湘江。」
幸自：本自，本来是。
为谁：为什么。
潇湘：潇水和湘水，是湖南境内的两条河流，合流后称湘江，又称潇湘。
「为谁流下潇湘去」句：为什么要流到潇湘去呢？意思是连郴江都耐不住寂寞何况人呢？', '雾迷蒙，楼台依稀难辨，月色朦胧，渡口也隐匿不见。望尽天涯，理想中的桃花源，无处觅寻。怎能忍受得了独居在孤寂的客馆，春寒料峭，斜阳西下，杜鹃声声哀鸣！
远方的友人的音信，寄来了温暖的关心和嘱咐，却平添了我深深的别恨离愁。郴江啊，你就绕着你的郴山流得了，为什么偏偏要流到潇湘去呢？', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74bc0ce818559d0507cb", "shortContent": "此词毛晋汲古阁本《淮海词》调下附注谓作于郴州旅舍，时间略晚于《阮郎归》（湘天风雨破寒初），大约作于绍圣四年（1097）春三月，其时，由于新旧党争，秦观先贬杭州通判，再贬监处州酒税，最后又被人罗织罪名，贬徙郴州，并削去了所有的官爵和俸禄。接二连三的贬官，少游内心的悲苦绝望可想而知。他来到郴州后，写下了这首词，以委婉曲折的笔法，抒写了谪居之恨，成为蜚声词坛的千古绝唱。\n开篇三句“雾失楼台，月迷津渡，桃...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5c27d0ac1145495e8af", "shortContent": "此词毛晋汲古阁本《淮海词》调下附注谓作于郴州旅舍，时间略晚于《阮郎归》（湘天风雨破寒初），大约作于绍圣四年（1097）春三月，其时，由于新旧党争，秦观先贬杭州通判，再贬监处州酒税，最后又被人罗织罪名，贬徙郴州，并削去了所有的官爵和俸禄。接二连三的贬官，少游内心的悲苦绝望可想而知。他来到郴州后，写下了这首词，以委婉曲折的笔法，抒写了谪居之恨，成为蜚声词坛的千古绝唱。\n开篇三句“雾失楼台，月迷津渡，桃...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253ccce4d48ba496d9e", "shortContent": "此词毛晋汲古阁本《淮海词》调下附注谓作于郴州旅舍，时间略晚于《阮郎归》（湘天风雨破寒初），大约作于绍圣四年（1097）春三月，其时，由于新旧党争，秦观先贬杭州通判，再贬监处州酒税，最后又被人罗织罪名，贬徙郴州，并削去了所有的官爵和俸禄。接二连三的贬官，少游内心的悲苦绝望可想而知。他来到郴州后，写下了这首词，以委婉曲折的笔法，抒写了谪居之恨，成为蜚声词坛的千古绝唱。\n\n开篇三句“雾失楼台，月迷津渡，...", "authors": ["高　原"], "pressName": "上海辞书出版社"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3fc26cbf3417f0919b", "shortContent": "词作于康熙二十一年（1682），与前篇均作于塞外，所用故实相同，意绪相近，惟所见景致不同。前者写广漠原野万里雪飘之势，或是安营扎寨时所见；此则描绘高山丛林雪花迷蒙之景，当时行军途中所感。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f3fb5b7e9043f1144c57", "bookTitle": "秦观词全集", "articleId": "63126e5bf2af4e09d55b64d2", "shortContent": "据《皇宋通鉴长编纪事本末》：“绍圣四年二月庚辰诏谓：郴州编管秦观，移送横州编管。”本篇作于是年（1097）春，当为已奉诏而未即行之时。明毛晋刻本调下题作《郴州旅舍》。《唐宋诸贤绝妙词选》调下注云： “东坡绝爱尾两句。”故宫影印本词末附注：“坡翁绝爱此词尾两句，自书于扇云：‘少游已矣，虽万人何赎！’释天隐注《三体唐诗》，谓此两句实自‘沅湘日夜东流去，不为愁人住少时，变化。然《邶》之‘毖彼泉水，亦流于...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f407f0b9738b369b10e", "shortContent": "少游一生仕途坎坷，流窜无终日，三十七岁才中进士。绍圣元年（1094）因新旧党之争，出杭州通判，道贬处州，任监酒税一职，后徙郴州，编管横州，又徙雷州，愈贬愈远。孤身处南荒之地倍思故里，却又归乡无期，心中益发苦闷只得藉词发哀感。\n长年贬谪在外的经历对其创作产生了重大影响，前期词多承温韦花间词，以抒写绮思艳情儿女情长为主，清丽婉约；后期词多为游仙怀古羁旅寓慨身世，凝重凄厉。少游将“身世之感融入艳情”，开...", "authors": ["谇雪颜"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127031c305cf0801816f07", "shortContent": "少游一生仕途坎坷，流窜无终日，三十七岁才中进士。绍圣元年（1094）因新旧党之争，出杭州通判，道贬处州，任监酒税一职，后徙郴州，编管横州，又徙雷州，愈贬愈远。孤身处南荒之地倍思故里，却又归乡无期，心中益发苦闷只得藉词发哀感。\n\n长年贬谪在外的经历对其创作产生了重大影响，前期词多承温韦花间词，以抒写绮思艳情儿女情长为主，清丽婉约；后期词多为游仙怀古羁旅寓慨身世，凝重凄厉。少游将“身世之感融入艳情”，...", "authors": ["谭雪颜"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271ba73206168b2e0237d", "shortContent": "少游一生仕途坎坷，流窜无终日，三十七岁才中进士。绍圣元年（1094）因新旧党之争，出杭州通判，道贬处州，任监酒税一职，后徙郴州，编管横州，又徙雷州，愈贬愈远，孤身处南荒之地倍思故里，却又归乡无期，心中益发苦闷只得藉词发哀感。\n长年贬谪在外的经历对其创作产生了重大影响，前期词多承温韦花间词，以抒写绮思艳情儿女情长为主，清丽婉约；后期词多为游仙怀古羁旅寓慨身世，凝重凄厉。少游将“身世之感融入艳情”，开...", "authors": ["谭雪颜"], "pressName": "崇文书局"}, {"bookId": "645d137a7af6de164710138d", "bookTitle": "秦观诗词鉴赏辞典", "articleId": "6469d92c5e6bb82b8cd99fd8", "shortContent": "此词毛晋汲古阁本《淮海词》调下附注谓作于郴州旅舍，时间略晚于《阮郎归》（湘天风雨破寒初），大约作于绍圣四年（1097）春三月，其时，由于新旧党争，秦观先贬杭州通判，再贬监处州酒税，最后又被人罗织罪名，贬徙郴州，并削去了所有的官爵和俸禄。接二连三的贬官，少游内心的悲苦绝望可想而知。他来到郴州后，写下了这首词，以委婉曲折的笔法，抒写了谪居之恨，成为蜚声词坛的千古绝唱。\n开篇三句“雾失楼台，月迷津渡，桃...", "authors": ["高原"], "pressName": "上海辞书出版社"}]', '王国维《人间词话》：少游词境，最为凄婉。至「可堪孤馆闭春寒，杜鹃声里斜阳暮」，则变而凄厉矣。
王士祯《花草蒙拾》：「郴江幸自绕郴山，为谁流下潇湘去？」千古绝唱。秦殁后坡公常书此于扇云：「少游已矣，虽万人何赎！」高山流水之悲，千载而下，令人腹痛。
黄苏《蓼园词选》：少游坐党籍，安置郴州。首一阙是写在郴，望想玉堂天上，如桃源不可寻，而自己意绪无聊也。次阕言书难达意，自己同郴水之自绕郴山，不能下潇湘以向北流也。语意凄切，亦自蕴藉，玩味不尽。「雾失」、「月迷」，总是被谗写照。
唐圭璋《唐宋词简释》：此首写羁旅，哀怨欲绝。起写旅途景色，已有归路茫茫之感。末引「郴江」、「郴山」，以喻人之分别，无理已极，沉痛已极，宜东坡爱之不忍释也。
王方俊《唐宋词赏析》：这首词层次极为分明。开头两句都以对句起，都是平叙；中间第三句一顿；末两句是中心所在。虽是小词，用的是慢词作法。
叶嘉莹《唐宋词十七讲》：头三句的象征与结尾的发问有类似《天问》的深悲沉恨的问语，写得这样沉痛，是他过人的成就，是词里的一个进展。', 'indent', 1413386601, '57b91f182e958a005fa64e24', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10323, '浣溪沙 · 漠漠轻寒上小楼', NULL, 376, 590, 2, 3, '秦观', NULL, 10085, '57b927b7d342d3005ac872a6', '宋', 'ci', '词', 'http://baike.baidu.com/view/1687507.htm', '', '漠漠轻寒上小楼，晓阴无赖似穷秋，淡烟流水画屏幽。
自在飞花轻似梦，无边丝雨细如愁，宝帘闲挂小银钩。', '此词描写了一幅晚春拂晓清寒景象。上阕以总摄方式写“晓阴穷秋”的景象。“漠漠”形容清晨时烟雾丝雨、柳絮飞花交织成的淡淡迷濛的画面。“晓阴无赖”乃楼中人发出的怨恼：真是无奈呀！清晨阴冷竟像深秋，暗示出时节正当寒食清明之际。“淡烟”写楼中人在晓阴轻寒中突然发现眼前景物之美：白濛濛的淡淡烟雾，清潺潺流淌的碧水像一幅清幽、淡逸的画境。
下阕承“画屏幽”而选取“飞花”“丝雨”富有动态性的细节意象精描细绘画境之清幽与楼中人似梦如怨的情怀。“自在”乃形容柳絮与落红顺其自然地飘然而落，倏忽而去，有如缥缈的春梦一样轻柔、空盈。最后以“闲挂”二字透出楼中人的空虚、闲寂的神情与心绪，与前面的景物描写融成一片。这首词以清丽优美的语言描绘了一位相思女子的精小的楼阁和她闲淡的精神世界，这两者全容纳在寥寥三十几字的小令之中，却作得仿佛一件精美玲珑的艺术盆景，令人久久欣赏把玩。', '浣溪沙：原唐教坊曲名，本为舞曲。“沙”又写作“纱”。又称《小庭花》、《满院春》。另有一体五十六字。
漠漠：像清寒一样的冷漠。
轻寒：薄寒，有别于严寒和料峭春寒。
晓阴：早晨天阴着。
无赖：词人厌恶之语。
穷秋：秋天走到了尽头。
淡烟流水：画屏上轻烟淡淡，流水潺潺。
幽：意境悠远。
丝雨：细雨。
宝帘：缀着珠宝的帘子，指华丽的帘幕。
闲挂：很随意地挂着。', '带着一丝寒意，独自登上小楼，清晨的阴凉，令人厌烦，仿佛已是深秋。回望画屏，淡淡烟雾，潺潺流水，意境幽幽。
窗外，花儿自由自在地轻轻飞舞，恰似梦境，雨淅淅沥沥的下着，漫无边际地飘洒着，就像愁绪飞扬。再看那缀着珠宝的帘子正随意悬挂在小小银钩之上。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74bc7d0ac1145494bbab", "shortContent": "在秦观《淮海词》中，长调应推《满庭芳》（山抹微云）为冠，小令则似应以这首《浣溪沙》为压卷了。论诗要讲境界，论词也应当讲境界。王国维在《人间词话》中说：“境界有大小，然不以是而分高下。‘细雨鱼儿出，微风燕子斜’，何遽不若‘落日照大旗，马鸣风萧萧’；‘宝帘闲挂小银钩’，何遽不若‘雾失楼台，月迷津渡’也。”他认为此词结句境界虽小，然艺术性却高。其实就通篇来说，何尝不能作如此评价？\n这首词的特点就在于描绘...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5c3911759740c9bcb4d", "shortContent": "在秦观《淮海词》中，长调应推《满庭芳》（山抹微云）为冠，小令则似应以这首《浣溪沙》为压卷了。论诗要讲境界，论词也应当讲境界。王国维在《人间词话》中说：“境界有大小，然不以是而分高下。‘细雨鱼儿出，微风燕子斜’，何遽不若‘落日照大旗，马鸣风萧萧’；‘宝帘闲挂小银钩’，何遽不若‘雾失楼台，月迷津渡’也。”他认为此词结句境界虽小，然艺术性却高。其实就通篇来说，何尝不能作如此评价？\n这首词的特点就在于描绘...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253ccce4d48ba496da0", "shortContent": "在秦观《淮海词》中，长调应推《满庭芳》（山抹微云）为冠，小令则似应以这首《浣溪沙》为压卷了。论诗要讲境界，论词也应当讲境界。王国维在《人间词话》中说：“境界有大小，然不以是而分高下。‘细雨鱼儿出，微风燕子斜’，何遽不若‘落日照大旗，马鸣风萧萧’；‘宝帘闲挂小银钩’，何遽不若‘雾失楼台，月迷津渡’也。”他认为此词结句境界虽小，然艺术性却高。其实就通篇来说，何尝不能作如此评价？\n\n这首词的特点就在于描...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "6277f3fb5b7e9043f1144c57", "bookTitle": "秦观词全集", "articleId": "63126e5ae6f69b71e93f6099", "shortContent": "此作为公认之宋词名篇。少游以轻描淡写的笔法，融情人景，将细致幽微的内心哀愁外化为可居可感的艺术境界，怅静悠闲，空灵含蓄，令人流连不尽。约作于元祐年间。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f407f0b9738b369b10f", "shortContent": "这是淮海小令的压卷之作，也是宋词中的名篇。淮海词以其凄婉蕴藉、清丽婉约的特点被赞誉为“词家正音”、“词中上品”。此词可谓将词体的特色诠释得淋漓尽致。\n全词借景抒情，营造了一个幽深寂寥的艺术境界，更是展现了少游纤柔善感的词人本质。此词约作于元佑时期，当时少游正供职于朝中，深陷党争之苦，忧惧于党祸，每日如履薄冰，心情彷徨，满腔苦闷和郁郁不得志终化作其词的凄婉和感伤意境。\n首句起调很轻，“漠漠”运用叠字...", "authors": ["谭雪颜"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127031c305cf0801816f08", "shortContent": "这是淮海小令的压卷之作，也是宋词中的名篇。淮海词以其凄婉蕴藉、清丽婉约的特点被赞誉为“词家正音”、“词中上品”。此词可谓将词体的特色诠释得淋漓尽致。\n\n全词借景抒情，营造了一个幽深寂寥的艺术境界，更是展现了少游纤柔善感的词人本质。此词约作于元祐时期，当时少游正供职于朝中，深陷党争之苦，忧惧于党祸，每日如履薄冰，心情彷徨，满腔苦闷和郁郁不得志终化作其词的凄婉和感伤意境。\n\n首句起调很轻，“漠漠”运用...", "authors": ["谭雪颜"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271bb73206168b2e0237e", "shortContent": "这是淮海小令的压卷之作，也是宋词中的名篇。淮海词以其凄婉蕴藉、清丽婉约的特点被赞誉为“词家正音”“词中上品”。此词可谓将词体的特色诠释得淋漓尽致。\n全词借景抒情，营造了一个幽深寂寥的艺术境界，更是展现了少游纤柔善感的词人本质。此词约作于元祐时期，当时少游正供职于朝中，深陷党争之苦，忧惧于党祸，每日如履薄冰，心情彷徨，满腔苦闷和郁郁不得志终化作其词的凄婉和感伤意境。\n首句起调很轻，“漠漠”运用叠字，...", "authors": ["谭雪颜"], "pressName": "崇文书局"}, {"bookId": "645d137a7af6de164710138d", "bookTitle": "秦观诗词鉴赏辞典", "articleId": "6469d9c75e6bb82b8cd9a2b7", "shortContent": "在秦观《淮海词》中，长调应推《满庭芳》（山抹微云）为冠，小令则似应以这首《浣溪沙》为压卷了。论诗要讲境界，论词也应当讲境界。王国维在《人间词话》中说：“境界有大小，然不以是而分高下。‘细雨鱼儿出，微风燕子斜’，何遽不若‘落日照大旗，马鸣风萧萧’; ‘宝帘闲挂小银钩’，何遽不若‘雾失楼台，月迷津渡’也。”他认为此词结句境界虽小，然艺术性却高。其实就通篇来说，何尝不能作如此评价？\n这首词的特点就在于描...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}]', '', 'indent', 1418935308, '57b9a8f779bc4400639b92fd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10324, '望海潮', NULL, 58, 590, 1, 1, '秦观', NULL, 10085, '57b927b7d342d3005ac872a6', '宋', 'ci', '词', '', '', '星分牛斗，疆连淮海，扬州万井提封。花发路香，莺啼人起，珠帘十里东风。豪俊气如虹。曳照春金紫，飞盖相从。巷入垂杨，画桥南北翠烟中。
追思故国繁雄，有迷楼挂斗，月观横空。纹锦制帆，明珠溅雨，宁论爵马鱼龙。往事逐孤鸿。但乱云流水，萦带离宫。最好挥毫万字，一饮拚千钟。', '此词是他的早年之作，词作于元丰三年（公元1080年），时秦观自会稽（今浙江绍兴）还里，“时复扁舟循邗沟而南，以适广陵，泛九曲池，访隋氏陈迹，入大明寺，饮蜀井，上平山堂”，“遂登摘星寺。寺，迷楼故址也。”（见《淮海集·与李乐天简》）
这首词吊古伤怀，借题发挥，不失为中国文人抒怀写意的独特方式。词人在词中抚今追昔，“豪俊气如虹，曳照春金紫，飞盖相从”的风光已成昨日黄花，而今剩下的只有“乱云”、“流水”和“离宫”。此时此境，词人唯有饮酒、作词可打发时光：“最好挥毫万字，一饮拚千钟。”词的气势也由此而冲天直起，词人饱满的人格力量因此而张扬，那种困兽犹斗、慷慨悲壮的形象与顽强拚搏的豪情与雄心清晰可见，给人以强大的精神力量与意志鼓舞。', '', '', '[{"bookId": "6277f3fb5b7e9043f1144c57", "bookTitle": "秦观词全集", "articleId": "63126e59e6f69b71e93f608a", "shortContent": "本篇作于元丰三年（1080），明及以后刻本于调下多题作《广陵怀古》。是年少游《与李乐天简》云：“自还家来……时复扁舟循邗沟而南，以适广陵……上平山堂，折欧阳文忠所种柳，而诵其所赋诗，为之喟然以叹。”又同年作《扬州集序》称该地该集可“推表废兴迁徙之迹”，皆与词中内容相合。词作极力渲染扬州之物华天宝，人杰地灵，并结合隋炀帝巡幸史实将历史兴亡之感蕴蓄其中，视界宽广，风格豪阔，作者之胸襟抱负于中隐然可见。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645d137a7af6de164710138d", "bookTitle": "秦观诗词鉴赏辞典", "articleId": "6469d30745e4710056d9a3d1", "shortContent": "《望海潮》词调创自柳永，据罗大经《鹤林玉露》所载，这是柳永献给杭州地方官孙何（一说孙沔）的干谒之作，描写杭州的富庶壮丽，“东南形胜，三吴都会，钱塘自古繁华”，陈振孙在《直斋书录解题》中称赞它“承平气象，形容曲尽”。据说金主完颜亮也被“三秋桂子，十里荷花”之句所倾倒，兴兵南下。自柳词之后，此调多用来描写都市风光，抒发豪情。秦观的这首词就是如此，有明显的模仿柳词的特征。\n秦观年轻的时候多次游览扬州，叶...", "authors": ["孔燕妮"], "pressName": "上海辞书出版社"}]', '', 'indent', 1423176300, '57b9b08d165abd00661d8090', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10325, '望海潮', NULL, 113, 590, 2, 1, '秦观', NULL, 10085, '57b927b7d342d3005ac872a6', '宋', 'ci', '词', '', '', '秦峰苍翠，耶溪潇洒，千岩万壑争流。鸳瓦雉城，谯门画戟，蓬莱燕阁三休。天际识归舟，泛五湖烟月，西子同游。茂草台荒，苎萝村冷起闲愁。
何人览古凝眸，怅朱颜易失，翠被难留。梅市旧书，兰亭古墨，依稀风韵生秋。狂客鉴湖头，有百年台沼，终日夷犹。最好金龟换酒，相与醉沧州。', '此词作於元豐二年（西元一〇七九年），时秦少游省大父承议公及叔父定於会稽（今浙江绍兴），郡守程师孟（字公闢）馆之于蓬莱阁，相与酬唱。（见秦瀛《淮海先生年谱》）少游偶尔也有咏史之作，此词是其一，所咏不尽是古人的「艳情」，自己的「身世之感」也依然隐约可见。
词咏范蠡（lǐ）、西施旧事，并连带古会稽郡的其他古人往事。古人的那一段轰轰烈烈恋情曾经让吴国覆灭、越国中兴，如今也只落得「台荒」与「村冷」了。惟有潇洒自在的范蠡，「泛五湖烟月」，载「西子同游」。真正让今日「览古凝眸」的词人羡煞。词人感慨「朱颜易失，翠被难留」，物是人非，好景不常。想起此地的墨客骚人王右军、贺季真等等，决心也向他们学习，「金龟换酒，相与醉沧州」，去过舒适自由的隐逸生活。这显然是词人仕途屡遭挫折後的一种牢骚感慨，字裏行间透露出来的还是「身世之感」。', '', '', '[{"bookId": "6277f3fb5b7e9043f1144c57", "bookTitle": "秦观词全集", "articleId": "63126e59e6f69b71e93f6085", "shortContent": "本篇作于元丰二年（1079）。据清秦瀛《淮海先生年谱》，是年少游“省大父承议公及叔父定于会稽。……乃东游鉴湖，谒禹庙，憩蓬莱阁。是时，给事广平程公辟领越州，先生相得欢甚，多登临唱酬之什……作《会稽怀古》诸词。”或因畅游酒酣而致胸襟阔朗，此作绝少向来之婉约风味，虽在怀古中亦隐然可见功名未就的牢骚感慨，但整体风格上的豪旷潇散溢于言表。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645d137a7af6de164710138d", "bookTitle": "秦观诗词鉴赏辞典", "articleId": "6469d38f5b7b0d4f45265242", "shortContent": "这首词，宋本《淮海居士长短句》无题，汲古阁本《淮海词》题为《洛阳怀古》。细玩词意，乃是感旧而非怀古；且作词之地也为汴京而非洛阳。至其作期，则在绍圣元年（1094）春，即朝局大变，旧党下台，新党再起，他因此贬官即将离京之时。\n秦观曾于元丰五年（1082）及八年（1085）两度入京应试，但只是在元祐五年（1090）制举及第之后，才留京供职达五年之久，得以参与当时名公的文酒之会，而元祐七年（1092）的...", "authors": ["程千帆", "沈祖棻"], "pressName": "上海辞书出版社"}]', '', 'indent', 1423176458, '57b926c1df0eea0063362019', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10326, '减字木兰花', NULL, 150, 590, 2, 3, '秦观', NULL, 10085, '57b927b7d342d3005ac872a6', '宋', 'ci', '词', 'http://baike.baidu.com/view/2738437.htm', '', '天涯旧恨，独自凄凉人不问。欲见回肠，断尽金炉小篆香。
黛蛾长敛，任是春风吹不展。困倚危楼，过尽飞鸿字字愁。', '此词上片写女子独自凄凉，愁肠欲绝；下片写百无聊赖的女主人公困倚危楼。全词通体悲凉，可谓断肠之吟，先着力写内心，再着重写外形，触物兴感，借物喻情，词采清丽，笔法多变，细致入微地表现了女主人公深重的离愁，抒写出一种深沉的怨愤激楚之情。词中出语凝重，显出沉郁顿挫的风致，抑扬分明，有强烈的起伏跌宕之感。', '减字木兰花：词牌名。此调将《偷声木兰花》上下阕起句各减三字，故名。
篆（zhuàn）香：比喻盘香和缭绕的香烟。
黛蛾：指眉毛。', '远隔天涯旧恨绵绵，凄凄凉凉孤独度日无人问讯。要想知道我是如何愁肠百结，就像金炉中燃尽的篆香。
长眉总是紧锁，任凭春风劲吹也不舒展。困倦地倚靠高楼栏杆，看那高飞的雁行，字字都是愁。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74bc5e272d4b2253bb73", "shortContent": "这首词写一位独处高楼的女子深长的离愁。\n起句陡峭，由情直入。“天涯”点明所思远隔，“旧恨”说明分离已久，四字写出空间、时间的悬隔，为“独自凄凉”张本。独居高楼，已是凄凉，而这种孤凄的处境与心情，竟连存问同情的人都没有，就更觉得难堪了。“人”可以理解为泛指，但也不妨包括所思念的远人在内，这与下片结句“过尽飞鸿字字愁”联系起来体味，就可以看得比较清楚。两句于伤离嗟独中含有怨意。\n“欲见回肠，断尽金炉小...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5c20ce818559d063b8d", "shortContent": "这首词写一位独处高楼的女子深长的离愁。\n起句陡峭，由情直入。“天涯”点明所思远隔，“旧恨”说明分离已久，四字写出空间、时间的悬隔，为“独自凄凉”张本。独居高楼，已是凄凉，而这种孤凄的处境与心情，竟连存问同情的人都没有，就更觉得难堪了。“人”可以理解为泛指，但也不妨包括所思念的远人在内，这与下片结句“过尽飞鸿字字愁”联系起来体味，就可以看得比较清楚。两句于伤离嗟独中含有怨意。\n“欲见回肠，断尽金炉小...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277f3fb5b7e9043f1144c57", "bookTitle": "秦观词全集", "articleId": "63126e5bf2af4e09d55b64d7", "shortContent": "本篇写思妇念远，将无形之愁绪尽化为有形之具象，清丽俊爽，含蕴悠远。虽系传统题材，但恐非一般意义上的“男子作闺音”，而是将自己强烈的身世之感融蓄其中，故肝肠寸断，格外凄婉动人。艺术表现方面则用语自然省洁，笔法纯熟老练。应系绍圣年间贬谪生涯中所作。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f407f0b9738b369b10d", "shortContent": "这是一首闺怨词，约作于绍圣三年（1096）少游被贬郴州之时。作者以男性的视觉吟咏女子倚楼怀人的离愁别怨，借女子际遇感怀自己仕途坎坷、爱情失意的人生之悲。\n开篇直写恨之深恨之久。“天涯”写所处之地蛮荒，“旧恨”写恨之久远，“人不问”可知音信不通相思难寄，道尽凄凉的原因。接下来，诗人以三个特写画面来刻画女子独处的凄凉和惆怅之情。画面一：“断尽金炉小篆香”，以篆香作比写女子燃香数刻的愁闷无聊情绪。篆香就...", "authors": ["谭雪颜"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127031c305cf0801816f06", "shortContent": "这是一首闺怨词，约作于绍圣三年（1096）少游被贬郴州之时。作者以男性的视觉吟咏女子倚楼怀人的离愁别怨，借女子际遇感怀自己仕途坎坷、爱情失意的人生之悲。\n\n开篇直写恨之深恨之久。“天涯”写所处之地蛮荒，“旧恨”写恨之久远，“人不问”可知音信不通相思难寄，道尽凄凉的原因。接下来，诗人以三个特写画面来刻画女子独处的凄凉和惆怅之情。画面一：“断尽金炉小篆香”，以篆香作比写女子燃香数刻的愁闷无聊情绪。篆香...", "authors": ["谭雪颜"], "pressName": "崇文书局"}, {"bookId": "645d137a7af6de164710138d", "bookTitle": "秦观诗词鉴赏辞典", "articleId": "6469d7ee5b7b0d4f45266af9", "shortContent": "这首词写一位独处高楼的女子深长的离愁。起句陡峭，由情直入。“天涯”点明所思远隔，“旧恨”说明分离已久，四字写出空间、时间的悬隔，为“独自凄凉”张本。独居高楼，已是凄凉，而这种孤凄的处境与心情，竟连存问同情的人都没有，就更觉得难堪了。“人”可以理解为泛指，但也不妨包括所思念的远人在内，这与下片结句“过尽飞鸿字字愁”联系起来体味，就可以看得比较清楚。两句于伤离嗟独中含有怨意。\n“欲见回肠，断尽金炉小篆...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '张炎《词源》：体制淡雅，气骨不衰，清丽中不断意脉。', 'indent', 1418929636, '57b8f740165abd0054bf8d92', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (12032, '孤雁', NULL, 56, 1416, 1, 2, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383462/5087463.htm', '', '孤雁不饮啄，飞鸣声念群。
谁怜一片影，相失万重云？
望尽似犹见，哀多如更闻。
野鸦无意绪，鸣噪自纷纷。', '这是一首咏物诗，体物曲尽其妙，同时又表达的就是乱离漂泊中失群人的痛苦心情。全诗通过对雁孤苦伶仃的描写来象征诗人自己。
首联「孤雁不饮啄，飞鸣声念群」唤出「孤雁」，「不饮啄」。写得孤雁有品骨。孤雁非常想念它的同伴。不单是想念，而且还拼命追寻，是一只情感热烈而执着的「孤雁」。「不饮啄」体现出孤雁的执着，不达目的绝不放弃的决心。寄寓诗人当时渴望与亲人朋友团聚的心情。
颔联「谁怜一片影，相失万重云？」境界忽然开阔。高远浩茫的天空中，这小小的孤雁仅是「一片影」，它与雁群相失在「万重云」间，此时此际显得惶急、焦虑和迷茫。「一片」、「万重」对比，构成极大的反差，极言其「孤」。「谁怜」二字直抒胸臆，凝聚了诗人对孤雁的怜悯之情。形象地写出了路远雁孤、同伴难寻的凄苦之情。这一联以「谁怜」二字设问诗人与雁，「物我交融」，浑然一体了。诗人所思念的不单是兄弟，还包括他的亲密的朋友。经历了安史之乱，在那动荡不安的年月里，诗人流落他乡，亲朋离散，天各一方，可他无时不渴望骨肉团聚，无日不梦想知友重逢，这孤零零的雁儿，寄寓了诗人自己的影子。
颈联「望尽似犹见，哀多如更闻。」联紧承上联，从心理方面刻画孤雁的鲜明个性。「似」、「如」二字表现了未见而似见，未闻而犹闻的幻觉。颈联通过对孤雁飞着叫着寻找同伴的描写，将孤雁的渴望、煎熬表现得淋漓尽致。它被思念缠绕着，被痛苦煎熬着，迫使它不停地飞鸣。它望尽天际，不停地望，仿佛那失去的雁群老在它眼前晃。它哀唤声声，不停地唤，似乎那侣伴的鸣声老在它耳畔响。所以，它更要不停地追飞，不停地呼唤了。这两句血泪文字，情深意切，哀痛欲绝。从中体现出诗人流离失所，生活困苦，又没有亲人和朋友可以依靠的状态。「犹」和「更」道出了诗人心中的沉重的悲哀与伤痛。
尾联「野鸦无意绪，鸣噪自纷纷。」用了陪衬的笔法，表达了诗人的爱憎感情。用野鸦的无忧无虑、热闹非常来反衬孤雁的寂寞、愁苦，尾联进一步表现了孤雁渴望团聚的哀愁与奋力寻找的坚持不懈。孤雁念群之情那么迫切，它那么痛苦、劳累；而野鸦们是全然不懂的，它们纷纷然鸣噪不停，自得其乐。「无意绪」是孤雁对着野鸦时的心情，也是杜甫既不能与知己亲朋相见，却面对着一些俗客庸夫时厌恶无聊的心绪。
这是一篇念群之雁的赞歌，它表现的情感是浓挚的，悲中有壮的。孤雁那样孤单、困苦，同时却还要不断地呼号、追求，它那念友之情在胸中炽烈地燃烧，它甚至连吃喝都可抛弃，更不顾处境的安危；虽然命薄但是心高，宁愿飞翔在万重云里，未曾留意暮雨寒塘，诗情激切高昂，思想境界很高。就艺术技巧而论，全篇咏物传神，是大匠运斤，自然浑成，全无斧凿之痕。中间两联有情有景，一气呵成，而且景中有声有色，甚至还有光和影，能给读者以「立体感」。
全诗以孤雁象征自己。诗写的是孤雁，无一字涉及诗人自己。但通过这只不饮不啄、穿飞哀鸣、思寻伙伴的失群的孤雁间接暗示了诗人在战乱中只身颠沛流离、怀念亲朋的情怀。', '饮啄：鸟类饮水啄食。
万重云：指天高路远，云海弥漫。
望尽：望尽天际。
意绪：心绪，念头。
鸣噪：野鸦啼叫。
自：自己。一作“亦”。', '一只离群孤雁，不想饮水，不肯进食，只是低飞哀叫，思念追寻它的同伴。
雁群消失在云海之间，谁来怜惜着天际孤雁？
放眼望尽天涯，好像看到同伴身影；哀鸣响震山谷，好像听到同伴叫唤。
野鸡不解孤雁心情，只顾自己鸣噪不停。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b0d635634aee3ded43", "shortContent": "这首咏物诗写于大历初杜甫居夔州（治今重庆奉节）时。它是一首孤雁念群之歌，体物曲尽其妙，同时又融注了作者的思想感情，堪称佳绝。\n依常法，咏物诗以曲为佳，以隐为妙，所咏之物是不宜道破的。杜甫则不然，他开篇即唤出“孤雁”。而此孤雁不同一般，它不饮，不啄，只是一个劲地飞着，叫着，声音里透出：它是多么想念它的同伴！不独想念，而且还拼命追寻，这真是一只情感热烈而执著的“孤雁”。清人浦起龙评曰：“‘飞鸣声念群’...", "authors": ["徐永端"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270597f0b9738b369b1df", "shortContent": "不知在什么时候，也不知在什么地点，一位孤单前行的老人孤独地默数自己孤寂的脚步。这时，耳畔突然传来了一声凄恻的哀鸣，老人不禁为之驻足了，回首了，他在茫茫天空仔细搜寻，搜寻这凄恻哀鸣声的来源。他看到了，一片孤单的身影正在自己头顶的天空费力地向前“游移”。老人在默想，这一定是一只失群的小雁，看它那可怜样儿、费力劲儿，就知道它已有一段时间不进饮食了，甚至连水也顾不得喝上一口，只是在茫茫长天之下奋力地追赶，...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "64662b067da2f75ac7ee7d0b", "shortContent": "这首咏物诗写于大历初杜甫居夔州（治今重庆奉节）时。它是一首孤雁念群之歌，体物曲尽其妙，同时又融注了作者的思想感情，堪称佳绝。\n\n依常法，咏物诗以曲为佳，以隐为妙，所咏之物是不宜道破的。杜甫则不然，他开篇即唤出“孤雁”。而此孤雁不同一般，它不饮，不啄，只是一个劲地飞着，叫着，声音里透出：它是多么想念它的同伴！不独想念，而且还拼命追寻，这真是一只情感热烈而执著的“孤雁”。清人浦起龙评曰：“‘飞鸣声念群...", "authors": ["徐永端"], "pressName": "上海辞书出版社"}]', '', 'center', 1477481086, '581021ff570c35006802ba53', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10327, '无题', NULL, 1824, 603, 4, 16, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3251151.htm', '', '相见时难别亦难，东风无力百花残。
春蚕到死丝方尽，蜡炬成灰泪始干。
晓镜但愁云鬓改，夜吟应觉月光寒。
蓬山此去无多路，青鸟殷勤为探看。', '此诗是一首唐代诗人李商隐以男女离别为题材的爱情诗。以句中的“别”字为通篇文眼，描写了一对情人离别的痛苦和别后的思念，抒发了无比真挚的相思离别之情，但其中也流露出诗人政治上失意和精神上的闷苦，具有浓郁的伤感色彩，极写凄怨之深、哀婉之痛，并借神话传说表达了对心中恋人的无比挚爱、深切思念。诗中融入了诗人切身的人生感受。
整首诗的内容围绕着第一句，尤其是“别亦难”三字展开。三、四句是相互忠贞不渝、海誓山盟的写照。五、六句则分别描述两人因不能相见而惆怅、怨虑，倍感清冷以至衰颜的情状。唯一可以盼望的是七、八两句中的设想：但愿青鸟频频传递相思情。', '无题：唐代以来，有的诗人不愿意标出能够表示主题的题目时，常用“无题”作诗的标题。
东风无力百花残：这里指百花凋谢的暮春时节。东风，春风。残，凋零。
丝方尽：丝，与“思”谐音，以“丝”喻“思”，含相思之意。
蜡炬：蜡烛。
泪始干：泪，指燃烧时的蜡烛油，这里取双关义，指相思的眼泪。
晓镜：早晨梳妆照镜子。镜，用作动词，照镜子的意思。
云鬓：女子多而美的头髮，这里比喻青春年华。
应觉：设想之词。
月光寒：指夜渐深。
蓬山：蓬莱山，传说中海上仙山，指仙境。
青鸟：神话中为西王母传递音讯的信使。
殷勤：情谊恳切深厚。
探看（kān）：探望。', '见面的机会真是难得，分别时更是难舍难分，况且又兼东风将收的暮春天气，百花残谢，更加使人伤感。
春蚕结茧到死时丝才吐完，蜡烛要燃尽成灰时像泪一样的蜡油才能滴干。
女子早晨妆扮照镜，只担忧丰盛如云的鬓发改变颜色，青春的容颜消失。男子晚上长吟不寐，必然感到冷月侵人。
对方的住处就在不远的蓬莱山，却无路可通，可望而不可及。希望有青鸟一样的使者殷勤地为我去探看情人。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dd5e272d4b225435ae", "shortContent": "玉谿生的这首《无题》，全以首句“别”字为通篇主眼。南朝梁江淹《别赋》说：“黯然销魂者，唯别而已矣！”他以此句领起一篇惊心动魄而又美丽的赋；而“黯然”二字，也正是玉谿此诗所表达的整个情怀与气氛。\n乐聚恨别，人之常情；离亭分首，河桥洒泪。——这是古代所常见描述的情景。离别之怀，非可易当；但如相逢未远，重会不难，那么分别自然也就无所用其魂销凄黯了。玉谿一句点破说：惟其相见之不易，故而离别之尤难。——惟其...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9820695e6503fff8", "shortContent": "玉谿生的这首《无题》，全以首句“别”字为通篇主眼。南朝梁江淹《别赋》说：“黯然销魂者，唯别而已矣！”他以此句领起一篇惊心动魄而又美丽的赋；而“黯然”二字，也正是玉谿此诗所表达的整个情怀与气氛。\n\n乐聚恨别，人之常情；离亭分首，河桥洒泪。——这是古代所常见描叙的情景。离别之怀，非可易当；但如相逢未远，重会不难，那么分别自然也就无所用其魂销凄黯了。玉谿一句点破说：惟其相见之不易，故而离别之尤难。——惟...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d7e73206168b2e01e79", "shortContent": "李商隐的诗歌以“无题”命篇的共有十七首，“万里风波一叶舟”一首之外，十六首都是写男女爱情的，或是有与爱情相关的内容。本篇是商隐最早的爱情诗，诗人对一位少女产生爱慕之情，因爱而生怜悯，不能不忧心她的前途，故采取民歌形式描写这位少女聪明美丽，才艺俱佳，然而她的命运并不掌握在自己手中，至待嫁之年，悄然生悲，黯然泣下。这首小诗有仿效古诗《焦仲卿妻》之痕迹，概括了中国封建社会绝大多数妇女的共同命运，因此具有...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d80f2af4e09d55b63c1", "shortContent": "本篇所写女性既非诗人之妻王氏，亦非刘、余《集解》所谓“作者之化身”。学者多以为一二句是义山试博学宏词失败之后抒写心中不平之语，此说无据。参加宏博试在开成三年春天，当时尚未与王氏结婚，何来“锦书”？，以宏词试为“弹棋”，义山恐怕不如此打比方。只有《柳枝五首》之二所云“玉作弹棋局，中心亦不平”与本篇的尾联相近。本篇亦为柳枝而作，前半写其花容月貌，打扮轻巧；后半为她的前途而忧虑。柳枝被东诸侯娶去之后，心...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d80f2af4e09d55b63c7", "shortContent": "诗中所谓仙人宝灯，本是诗人想望爱慕之女冠，欲与之饮宴，久候未至，故曰云液成冰。后二句说，值此雪月交辉之夜，她竟有约不来，却独居高阁，令人失望。诗人直把道观描写成冰清玉洁的琼瑶仙境，将女冠视为神仙丽人。格调奇高，词采华茂。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d80e6f69b71e93f5f86", "shortContent": "本篇是义山爱情诗中最为传诵的名篇。它表达了最真诚、最执著的典型的爱情心理，具有不朽的艺术魅力和深刻的哲理意义。首联谓离别时的难堪情景。昔人只说“别易会难”，而义山独曰“别亦难”，一语道尽难分难舍的深切感受。次联谓一息尚存，志不稍懈，地老天荒，爱心不死。此联胜过一切言语如表达，真可以惊天地，泣鬼神。英国19世纪诗人彭斯的《红红的玫瑰》有云：“哪怕大海干枯水流尽，哪怕太阳把岩石烧作灰尘。”古代也有“海...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d86c9ebcc6fbea1a112", "shortContent": "本篇原编集外诗，原题失去，编录者署以《无题》，实与其他《无题》诗迥不相侔。义山于大中二年三月自桂州罢幕北归，五月至潭州，在李回幕作短期逗留，然后出洞庭至夏口稍稍停驻，即溯江西上至江陵，并且到达三峡、巴东一带地方。本篇当作于淹滞荆巴之时。首联谓万里风波，孤舟一叶，桂幕初罢，思归心切。心知令狐绹对自己深怀不满，回长安求职的机会不多，故于归途中徘徊淹滞，希望在江湘或巴蜀谋一幕职。颔联紧承上联而来，即谓巴...", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f09359", "shortContent": "此诗以一多情柔美女子的口吻回忆与情郎见面的情景，淋漓尽致地展示女子相思之苦及无法言表的复杂心理，是古代闺怨诗的典范，也是商隐情诗的代表作，尽显李商隐诗歌情深缠绵、伤感朦胧的风格。\n\n首联回忆见面场景，渲染暮春悲伤哀婉气氛，也写这对情人分别时的不舍。春风渐减，百花凋零，两人终于见面了。可是这一次见面之后，又要等多长时间才能再会呢？也或许此次相见之后再无相见之时了，如落红归去碾作尘。珍惜吧珍惜吧，珍惜...", "authors": ["林妙芝"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "646362b87da2f75ac7e29eb4", "shortContent": "玉谿生的这首《无题》，全以首句“别”字为通篇主眼。南朝梁江淹《别赋》说：“黯然销魂者，唯别而已矣！”他以此句领起一篇惊心动魄而又美丽的赋；而“黯然”二字，也正是玉谿此诗所表达的整个情怀与气氛。\n\n乐聚恨别，人之常情；离亭分首，河桥洒泪。——这是古代所常见描述的情景。离别之怀，非可易当；但如相逢未远，重会不难，那么分别自然也就无所用其魂销凄黯了。玉谿一句点破说：惟其相见之不易，故而离别之尤难。——惟...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471fa44e49f46528adda710", "shortContent": "玉谿生的这首《无题》，全以首句“别”字为通篇主眼。南朝梁江淹《别赋》说：“黯然销魂者，唯别而已矣！”他以此句领起一篇惊心动魄而又美丽的赋；而“黯然”二字，也正是玉谿此诗所表达的整个情怀与气氛。\n乐聚恨别，人之常情；离亭分首，河桥洒泪。———这是古代所常见描述的情景。离别之怀，非可易当；但如相逢未远，重会不难，那么分别自然也就无所用其魂销凄黯了。玉谿一句点破说：唯其相见之不易，故而离别之尤难。———...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}]', '《韵语阳秋》：李义山《无题诗》云：春蚕到死丝方尽，蜡炬成灰泪始干。”此又是一格。今效此体为俚语小词传于世者甚多，不足道也。
《四溟诗话》：“春蚕到死丝方尽，蜡炬成灰泪始干。”……措词流丽，酷似六朝。
《五朝诗善鸣集》：诗中比意从汉魏乐府中得来，遂为《无题》诸篇之冠。
《初白庵诗评》：三四摹写“别亦难”，是何等风韵！
《瀛奎律髓汇评》：冯舒：第二句毕世接不出，次联犹之“彩凤”、“灵犀”之句，入妙未入神。冯班：妙在首联。三四亦杨、刘语耳。何义门：“东风无力”，上无明主也。“百花残”，己且老至也。落句具屈子《远游》之思乎？
《唐诗贯珠》：此首玩通章，亦圭角太露，则词藻反为皮肤，而神髓另在内意矣。若竟作艳情解，近于怒张，非法之善也。细测其旨，盖有求于当路而不得耶？
《李义山诗解》：八句中真是千回万转。
《玉溪生诗意》：三四进一步法。结用转笔有力。
《重订李义山诗集笺注》：程梦星曰：此诗似邂逅有力者，望其援引入朝，故不便明言，而属之无题也。起句言缱绻多情，次句言流光易去，三四言心情难已于仕进，五六言颜状亦觉其可怜，七八望其为王母青禽，庶得入蓬山之路也。
《山满楼笺注唐诗七言律》：泛读首句，疑是未别时语，及玩通首，皆是作别后追思语，乃知此句是倒文……呜呼！言情至此，真可以惊天地而泣鬼神，《玉台》、《香奁》，其犹粪土哉！镂心刻骨之言（“春蚕到死”二句下）。
《茧斋诗谈》：情太浓，便不能自摄，入于淫纵，只看李义山“春蚕到死丝方尽，蜡炬成灰泪始干”之句便知。
《龙性堂诗话初集》：李义山慧业高人，敖陶孙谓其诗“绮密瑰妍，要非适用”，此皮相耳。义山《无题》云：“春蚕到死丝方尽，蜡炬成灰泪始干。”又“神女生涯原是梦，小姑居处本无郎。”其指点情痴处，拈花棒喝，殆兼有之。
《唐诗笺注》：首句七字屈曲，唯其相见难，故别更难。
《唐贤小三昧集续集》：玉溪《无题》诸作，深情丽藻，千古无双，读之但觉魂摇心死，亦不能名言其所以佳也。
《玉溪生诗说》：感遇之作，易为激语。此云“蓬山此去无多路，青鸟殷勤为探看”，不为绝望之词，固诗人忠厚之旨也。但三四太纤近鄙，不足存耳。
《唐诗三百首》：一息尚存，志不少懈，可以言情，可以喻道。
《精选七律耐吟集》：镂心刻骨之词。千秋情语，无出其右。
《澹山诗话》：义山“春蚕到死丝方尽，蜡炬成灰泪始干”，道出一生工夫学问，后人再四摹仿，绝无此奇句。', 'center', 1413470616, '57b8ea5a128fe10054c9053f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10328, '无题', NULL, 993, 603, 2, 2, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3445733.htm', '', '昨夜星辰昨夜风，画楼西畔桂堂东。
身无彩凤双飞翼，心有灵犀一点通。
隔座送钩春酒暖，分曹射覆蜡灯红。
嗟余听鼓应官去，走马兰台类转蓬。', '此诗写的是追忆所遇见的艳情场景。从内容上看，首句以“昨夜”明点追忆旧事。三四句以他物作比，“身无彩凤”写昨夜之情。五六句从两人的默契转到对整个宴会的描绘，七八句从恋情的欢悦转入“听鼓应官”，欢情一落千丈。全诗以心理活动为出发点，诗人的感受细腻而真切，将一段可意会不可言传的情感描绘得扑朔迷离而又入木三分。单看这首无题诗，全诗在哀婉凄凉的乐调下给人一种似解非解的感觉，让人觉的既像是写给不能长久相伴的恋人的，又像哀叹君臣遇合，却似乎没有这么世俗，如此，就是李义山无题诗的妙处所在了。', '「昨夜星辰昨夜风」句：《尚书·洪范》「星有好风。」此含有好会的意思。星辰：众星，星之通称。
画楼：指彩绘华丽的高楼。一作「画堂」。
桂堂：形容厅堂的华美。
灵犀：犀角中心的髓质像一条白线贯通上下，借喻相爱双方心灵的感应和暗通。
「隔座送钩春酒暖，分曹射覆蜡灯红」句：邯郸淳《艺经》：「义阳腊日饮祭之后，叟妪儿童为藏钩之戏，分为二曹，以校胜负。」隔座送钩，一队用一钩藏在手内，隔座传送，使另一队猜钩所在，以猜中为胜。分曹：分组。射覆：《汉书·东方朔传》：「上尝使诸数家射覆，置守宫盂下射之，皆不能中。」把东西放在菠盖物下使人猜。
嗟（jiē）：叹词。
听鼓应官：到官府上班，古代官府卯刻击鼓，召集僚属，午刻击鼓下班。
走马：跑马。
兰台：《旧唐书·职官志》：「祕书省，龙朔（高宗年号）初改为兰台。」当时李义山在做祕书省校书郎。
转蓬：《坤雅》：「蓬，末大于本，遇风辄拔而旋。」指身如蓬草飞转。转，一作「断」。', '昨夜的星空与昨夜的春风，在那画楼之西侧桂堂之东。
身虽无彩凤双翅飞到一处，心却有灵犀一点息息相通。
隔着座位送钩春酒多温暖，分开小组射覆蜡灯分外红。
叹我听更鼓要去官署应卯，骑马去兰台心中像转飞蓬。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dddbb8b379ee095d2a", "shortContent": "这是一首有作者自己直接出场的无题诗，抒写对昨夜偶然相值，旋成间隔的意中人深切的怀想。原题二首，另一首是七绝，其中有“岂知一夜秦楼客，偷看吴王苑内花”的诗句，看来诗人所怀想的对象可能是一位贵家女子。\n开头两句由今宵情景引发对昨夜的追忆。这是一个美好的春夜：星光闪烁，和风习习，空气中充溢着令人沉醉的温馨气息，一切都似乎和昨夜相仿佛。但昨夜在“画楼西畔桂堂东”和所爱者相见的那一幕却已经成为亲切而难以追寻...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9820695e6503fff6", "shortContent": "这是一首有作者自己直接出场的无题诗，抒写对昨夜偶然相值，旋成间隔的意中人深切的怀想。原题二首，另一首是七绝，其中有“岂知一夜秦楼客，偷看吴王苑内花”的诗句，看来诗人所怀想的对象可能是一位贵家女子。\n\n开头两句由今宵情景引发对昨夜的追忆。这是一个美好的春夜：星光闪烁，和风习习，空气中充溢着令人沉醉的温馨气息，一切都似乎和昨夜相仿佛。但昨夜在“画楼西畔桂堂东”和所爱者相见的那一幕却已经成为亲切而难以追...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d80f2af4e09d55b63cc", "shortContent": "一二句谓美人乘七香车循萦回之白道远去。三四句谓彼姝嫣然含笑，却寂寞无依，空有倾城之色也。本篇为女冠而作。\n", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f09355", "shortContent": "清晨，在鼓声的催促下，诗人叹惋着，极不情愿地要去官衙应差；他沮丧地骑着马，走在通往所供职的秘书省的路上，忽然觉得自己像漫天飞舞的蓬草一样，漂泊无依，没有归所，且要日复一日地从事这枯燥乏味的校书工作。面对这种无聊的薄宦生涯，诗人早已产生一种厌倦感，宦途凄凉、长久不遇始终是诗人解不开的郁郁愁结。\n\n他开始追忆起昨宵的愉快生活。那真是美妙的夜晚：微风袭来，满堂洋溢着清凉舒爽的气息，漆黑的夜空洒满着忽闪忽...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270799761253910e90567", "shortContent": "清晨，在鼓声的催促下，诗人叹惋着，极不情愿地去官衙应差；他沮丧地骑着马，走在通往所供职的秘书省的路上，忽然觉得自己像漫天飞舞的蓬草一样，漂泊无依，没有归所，且要日复一日地从事这枯燥乏味的校书工作。面对这种无聊的薄宦生涯，诗人早已产生一种厌倦感，宦途凄凉、长久不遇始终是诗人解不开的郁郁愁结。\n\n他开始追忆起昨宵的愉快生活。那真是美妙的夜晚：微风袭来，满堂洋溢着清凉舒爽的气息，漆黑的夜空洒满着忽闪忽闪...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312714977683d193301546a", "shortContent": "清晨，在鼓声的催促下，诗人叹惋着，极不情愿地要去官衙应差；他沮丧地骑着马，走在通往所供职的秘书省的路上，忽然觉得自己像漫天飞舞的蓬草一样，漂泊无依，没有归所，且要日复一日地从事这枯燥乏味的校书工作。面对这种无聊的薄宦生涯，诗人早已产生一种厌倦感，宦途凄凉、长久不遇始终是诗人解不开的郁郁愁结。\n他开始追忆起昨宵的愉快生活。那真是美妙的夜晚：微风袭来，满堂洋溢着清凉舒爽的气息，漆黑的夜空洒满着忽闪忽闪...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64631e045e6bb82b8cbd2ec6", "shortContent": "这是一首有作者自己直接出场的无题诗，抒写对昨夜偶然相值，旋成间隔的意中人深切的怀想。原题二首，另一首是七绝，其中有“岂知一夜秦楼客，偷看吴王苑内花”的诗句，看来诗人所怀想的对象可能是一位贵家女子。\n\n开头两句由今宵情景引发对昨夜的追忆。这是一个美好的春夜：星光闪烁，和风习习，空气中充溢着令人沉醉的温馨气息，一切都似乎和昨夜相仿佛。但昨夜在“画楼西畔桂堂东”和所爱者相见的那一幕却已经成为亲切而难以追...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '《唐诗鼓吹评注》：此追忆昨夜之景而思其地，谓身不能至，而心则可通也。「送钩」、「射覆」，乃昨夜之事。嗟余听鼓而去，迹似转蓬，不唯不能相亲，并与画楼、桂堂相远矣。
《围炉诗话》：「昨夜星辰昨夜风，画楼西畔桂堂东」，乃是具文见意之法。起联以引起下文而虚做者，常道也；起联若实，次联反虚，是为定法。
《唐诗贯珠》：此诗是席上有遇追忆之作。妙在欲言良宵佳会，独从星辰说起……凌空步虚，有绘风之妙……得三四铺云衬月，顿觉七宝放光，透出上文，身远心通，俨然相对一堂之中。五之胜情，六之胜境，皆为佳人着色。且隔座分曹，申明三之意；送钩春暖，方见四之实。蜡灯红后，恨无主人烛灭留髡之会。闻鼓而起，今朝寂寞，能不重念昨夜之为良时乎？
《唐音审体》：义山无题诗，直是艳语耳。杨眉庵谓托于臣不忘君，亦是故为高论，未敢信其必然。
《玉溪生诗意》：一二昨夜所会时地。三四身虽似远，心已相通。五六承三四，言藏钩送酒，其如隔座；分曹射覆，唯碍烛红。及天明而去，应官走马，无异转蓬。感目成于此夜，恐后会之难期。
《重订李义山诗集笺注》：程梦星曰：盖叹不得立朝，将为下吏也。
《瀛奎律髓汇评》：冯舒：妙在首二句。次联衬贴，流丽圆美，「西昆」诸公一世所效。冯班：起二句妙。纪昀：观此首末二句，实是妓席之作，不得以寓意曲解。义山「风怀」诗，注家皆以寓言君臣为说，殊多穿凿。
《唐诗笺注》：诗意平常，而炼句设色，字字不同。
《精选评注五朝诗学津梁》：此诗自炫其才，述眼前境遇，笔情飘忽。', 'center', 1363293126, '57b8ed5d0a2b58005c91c5dd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10329, '无题', NULL, 292, 603, 2, 2, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/view/1738765.htm', '', '来是空言去绝踪，月斜楼上五更钟。
梦为远别啼难唤，书被催成墨未浓。
蜡照半笼金翡翠，麝熏微度绣芙蓉。
刘郎已恨蓬山远，更隔蓬山一万重。', '此诗是一首艳情诗。诗中写女主人思念远别的情郎，有好景不常在之恨。「梦为远别」为一篇眼目。全诗就是围绕「梦」来写离别之恨。但它并没有按远别、思念、入梦、梦醒的顺序来写。而是先从梦醒时情景写起，然后将梦中与梦后、实境与幻觉来柔合在一起，创造出疑梦疑真、亦梦亦真的艺术境界，最后才点明蓬山万重的阻隔之恨，与首句遥相呼应。这样的艺术构思，曲折宕荡，有力地突出爱情阻隔的主题和梦幻式的心理氛围，使全诗充满迷离恍惚的情怀。', '空言：空话。
蜡照：烛光。
半笼：半映。指烛光隐约，不能全照床上被褥。
金翡翠：指饰以金翠的被子。《长恨歌》：「翡翠衾寒谁与共。」
麝熏：麝香的气味。麝本动物名，即香獐，其体内的分泌物可作香料。这里即指香气。
度：透过。
绣芙蓉：指绣花的帐子。
刘郎：相传东汉时刘晨、阮肇一同入山采药，遇二女子，邀至家，留半年乃还乡。后也以此典喻「艳遇」。
蓬山：蓬莱山，指仙境。', '她说过要来的，其实是句空话，一去便杳无影踪。我在楼上等着，直到残月西斜，传来五更的晓鐘。
因为远别而积思成梦，梦里悲啼，久唤难醒；醒后便匆忙提笔写信，心情急切，墨未磨浓。
蜡烛的馀光，半罩着饰有金翡翠的帷幕；兰麝的香气，熏染了被褥上刺绣的芙蓉。
我像古代的刘郎，本已怨恨蓬山仙境的遥远；我所思念的人啊，哪堪更隔着蓬山千重万重！', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dd34a8757d5a0e1e3d", "shortContent": "《无题四首》，包括七律两首，五律、七古各一首。体裁既杂，各篇之间在内容上也看不出有明显的联系，似乎不一定是同时所作的有统一主题的组诗。\n这首无题写一位男子对远隔天涯的所爱女子的思念。“梦为远别”四字是一篇眼目。全诗就是围绕着“梦”来抒写“远别”之情的。不过它没有按照远别——思念——入梦——梦醒的顺序来写，而是先从梦醒时的情景写起，然后再将梦中和梦后、实境与幻觉糅合在一起抒写，最后才点明蓬山重隔，归...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9820695e6503fff7", "shortContent": "《无题四首》，包括七律两首，五律、七古各一首。体裁既杂，各篇之间在内容上也看不出有明显的联系，似乎不一定是同时所作的有统一主题的组诗。\n\n这首无题写一位男子对远隔天涯的所爱女子的思念。“梦为远别”四字是一篇眼目。全诗就是围绕着“梦”来抒写“远别”之情的。不过它没有按照远别——思念——入梦——梦醒的顺序来写，而是先从梦醒时的情景写起，然后再将梦中和梦后、实境与幻觉糅合在一起抒写，最后才点明蓬山重隔，...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f09357", "shortContent": "【其一】\n\n远处又响起了浑厚的钟声，现在已经是五更时分了。诗人孤独地躺在床上，一夜辗转反侧，疲惫感越发浓郁了，但睡意依然没有来临。也许这样的失眠已不是第一次，诗人凄然地看着朦胧的夜月迷离地照耀在楼阁上，透过窗棂，他隐约看到斜挂在西天的月儿，渐渐地变白变淡，快要被渐渐来临的黎明吞噬了。\n\n到底是什么如此苦痛地煎熬着诗人呢？原来是思念魂牵梦萦的恋人。想当初十里长亭送别时，信誓旦旦地相约了重聚的日期，如...", "authors": ["徐昌盛", "乐云"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64631e60c0471b0062c6190d", "shortContent": "《无题四首》，包括七律两首，五律、七古各一首。体裁既杂，各篇之间在内容上也看不出有明显的联系，似乎不一定是同时所作的有统一主题的组诗。\n\n这首无题写一位男子对远隔天涯的所爱女子的思念。“梦为远别”四字是一篇眼目。全诗就是围绕着“梦”来抒写“远别”之情的。不过它没有按照远别——思念——入梦——梦醒的顺序来写，而是先从梦醒时的情景写起，然后再将梦中和梦后、实境与幻觉糅合在一起抒写，最后才点明蓬山重隔，...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '《唐诗鼓吹注解》：此有幽期不至，故言「来是空言」而去已绝迹。
《李义山诗集辑评》：何焯曰：梦别、书成，为远、被催，啼难、墨未，皆用双声叠韵对。
《载酒园诗话》：（艳诗）至元稹、杜牧、李商隐、韩倔，而上宫之迎，垝垣之望，不唯极意形容，兼亦直认无讳，真桑濮耳孙也……元微之「频频闻动中门锁，犹带春酲懒相送」，李义山「书被催成墨未浓」、「车走雷声语未通」，始真是浪子宰相、清狂从事。
《唐诗贯珠》：此诗内容，起言君臣无际会之时，或指当路止有空言之约，二三四是日夕想念之情，五六言其寂寞，七八言隔绝无路可寻。若以外象言之，乃是所欢一去，芳踪便绝，再来却付之空言矣。
《山满楼笺注唐诗七言律》：只首句七字，便写尽幽期虽在，良会难成，种种情事，真有不觉其望之切而怨之深者。次句一落，不是见月而惊，乃是闻钟而叹，盖钟动则天明，而此宵竟已虚度矣。三四放开一步，略举平日事，三写神魂恍惚，四写报问之仓皇，情真理至，不可以其媟而忽之。五六乃缩笔重写。
《玉溪生诗意》：一相期久别。二此时难堪。三梦犹难别。四幸通音信，五六孤灯微香，咫尺千里。七八远而又远，无可如何矣。
《唐诗笺注》：语极摇曳，思却沉挚。
《选玉溪生诗补说》：梦中之景。点出梦，统贯上下，以清意旨，针线极细（「梦为远别」二句下）。
人。', 'center', 1415638788, '57b916b3128fe10054ca40ae', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10330, '晚晴', NULL, 345, 603, 2, 2, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/1132847/5805126.htm', '', '深居俯夹城，春去夏犹清。
天意怜幽草，人间重晚晴。
并添高阁迥，微注小窗明。
越鸟巢干后，归飞体更轻。', '这首诗描绘雨后晚晴明净清新的境界和生意盎然的景象，表达出诗人欣慰喜悦的感受和明朗乐观的襟怀。作为一首有寓托的诗，《晚晴》的写法更接近于「在有意无意之间」的「兴」。诗人也许本无托物喻志的明确意图，只是在登高览眺之际，适与物接而触发联想，情与境谐，从而将一刹那间别有会心的感受融化在对晚晴景物的描写之中，故显得自然浑成，不着痕迹。', '夹城：城门外的曲城。
幽草：幽暗地方的小草。
并：更。
高阁：指诗人居处的楼阁。
迥：高远。
微注：因是晚景斜晖，光线显得微弱和柔和，故说“微注”。
越鸟：南方的鸟。', '一个人深居简出过着清幽的日子，俯瞰夹城，春天已去，夏季清朗。
小草饱受雨水的浸淹，终于得到上天的怜爱，雨过天晴了。
登上高阁，凭栏远眺，天高地迥，夕阳冉冉的馀晖透过窗棂。
越鸟的窝巢已被晒干，它们的体态也恢复轻盈了。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92df7d0ac11454953a7c", "shortContent": "细腻地描画晚晴景物，或许不算太难。但如果要在景物描写中融入诗人独特的感受与心境，特别是要不露痕迹地寓托某种积极的人生态度，使读者在思想上受到启示，这就需要诗人在思想境界和艺术工力上都“更上一层楼”。\n首联说自己居处幽僻，俯临夹城（城门外的曲城），时令正值清和的初夏。乍读似不涉题，上下两句也不相属，其实“俯夹城”的“深居”即是览眺晚晴的立足点，而清和的初夏又进而点明了晚晴的特定时令，不妨说是从时、地...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9820695e6503fffc", "shortContent": "细腻地描画晚晴景物，或许不算太难。但如果要在景物描写中融入诗人独特的感受与心境，特别是要不露痕迹地寓托某种积极的人生态度，使读者在思想上受到启示，这就需要诗人在思想境界和艺术工力上都“更上一层楼”。\n\n首联说自己居处幽僻，俯临夹城（城门外的曲城），时令正值清和的初夏。乍读似不涉题，上下两句也不相属，其实“俯夹城”的“深居”即是览眺晚晴的立足点，而清和的初夏又进而点明了晚晴的特定时令，不妨说是从时、...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d84f2af4e09d55b63f0", "shortContent": "首联谓深居桂林寓所，俯瞰夹城，眺望晚晴景物，感觉初夏气候清和宜人。颔联谓雨后放晴，幽僻处的小草沐浴晚晴的余晖，呈现一派生机，似乎是天意怜爱小草，同情弱小的生命。人间也因云消雨霁，十分看重晚晴，心情为之舒展爽快。此一联寄寓身世之感，而又极其自然，不露形迹。颈联谓晴后凭高，所见愈远。夕阳斜照，室内一片光明。尾联谓天晴之后，越鸟巢干，傍晚飞回，体态轻盈，十分得意。本篇写久雨之后，傍晚放晴的喜悦，郁闷气为...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707a73206168b2e02221", "shortContent": "正是初夏时节，寄居桂林的诗人，在离瓮城不远的地方，有一处幽静的居所。看样子房屋的地势还不错，低头可以观看瓮城里的人来人往，平视则可眺望远处的山野平原。秀丽的春色刚刚退去，草木依然一如既往的生机勃勃，初夏时节的天气，并不比春日逊色，“清”字，既点明景色的清丽，也透露出作者轻松爽快的心情。\n\n“天意怜幽草，人间重晚晴”，是描写景色的名句。诗人以拟人化的手法，将天赋予了人的意志，“怜”字最妙，写出天的善...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312714a77683d193301546d", "shortContent": "正是初夏时节，寄居桂林的诗人，在离瓮城不远的地方，有一处幽静的居所。看样子房屋的地势还不错，低头可以观看瓮城里的人来人往，平视则可眺望远处的山野平原。秀丽的春色刚刚退去，草木依然一如既往的生机勃勃，初夏时节的天气，并不比春日逊色，“清”字，既点明景色的清丽，也透露出作者轻松爽快的心情。\n“天意怜幽草，人间重晚晴”，是描写景色的名句。诗人以拟人化的手法，将天赋予了人的意志，“怜”字最妙，写出天的善良...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "6463853045e4710056bf708b", "shortContent": "腻地描画晚晴景物，或许不算太难。但如果要在景物描写中融入诗人独特的感受与心境，特别是要不露痕迹地寓托某种积极的人生态度，使读者在思想上受到启示，这就需要诗人在思想境界和艺术工力上都“更上一层楼”。\n\n首联说自己居处幽僻，俯临夹城（城门外的曲城），时令正值清和的初夏。乍读似不涉题，上下两句也不相属，其实“俯夹城”的“深居”即是览眺晚晴的立足点，而清和的初夏又进而点明了晚晴的特定时令，不妨说是从时、地...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '《逸老堂诗话》：唐李义山诗，有「天意怜幽草，人间重晚晴」之句。世俗久雨，见晚晴辄喜，自古皆然。
《唐诗归》：锺云：妙在大样（「人间」句下）。谭云：此句说晚晴，其妙难知（「并添」句下）。
《围炉诗话》：次联澹妙。
《唐诗快》：不必然，不必不然，说来却便似确然不易，故妙（「天意」二句下）。
《唐律消夏录》：二四妙在将「天意」突说一句，然后对出晚晴。「并添」、「微注」，「晴」字说得深细。结句有意无意，亦是少陵遗法。
《载酒园诗话》：义山之诗，妙于纤细，如《全溪作》：「战蒲知雁唼，皱月觉龟来。」《晚晴》：「并添高阁迥，微注小窗明。」
《李义山诗集辑评》：朱彝尊云：「越鸟巢干后」，写其得意。何焯云：但露微明，已觉心开目舒，五六是倒装语，酷写望晴之极也。
《重订李义山诗集笺注》：程梦星云：此为历所从事者多见憎忌于时，而己亦为所累，久而自明，适有天幸，故于「天意怜幽草，人间重晚晴」一联微露其旨。结言越鸟归巢。疑在桂管将入京师时作也。
《李义山诗集笺注》：姚培谦曰：晚晴，比常时晴色更佳。天上人间，若另换一番光景者，在清和时节尤妙。小窗高阁、异样焕发，而归燕亦觉体轻。言外有身世之感。
《网师园唐诗笺》：玉溪咏物，妙能体贴，时有佳句，在可解不可解之间。风人比兴之意，纯自意匠经营中得来（「天意」二句下）。
《玉溪生诗说》：轻秀，是钱、郎一格。五六再振起，则大历以上矣。末句结「晚晴」，可谓细意熨贴，即无寓意亦自佳也。
《唐诗笺要》：「并添高阁迥」，妙空迹象，下句便落筌蹄。第三句亦胜对句。
《龙性堂诗话初集》：（义山）咏物入微，写照妙语，则如咏云云「潭暮随龙起，河秋压雁声」，咏雨云「气凉先动竹，点细未开萍」，咏晴云「并添高阁迥，微注小窗明」……是皆得象外之趣，尤不可及。
《唐贤小三昧集续集》：大家数语，结近滞（「人间」句下）。
《律髓辑要》：前半深厚，后半细致，老杜有此格律。', 'center', 1363293462, '57b8e5018ac2470062defc38', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10331, '寄黄几复', NULL, 616, 2398, 2, 4, '黄庭坚', NULL, 10086, '57b9594b8ac2470062e29b7d', '宋', 'shi', '诗', 'http://baike.baidu.com/view/822249.htm', '', '我居北海君南海，寄雁传书谢不能。
桃李春风一杯酒，江湖夜雨十年灯。
持家但有四立壁，治病不蕲三折肱。
想得读书头已白，隔溪猿哭瘴溪藤。', '这首诗作于宋神宗元丰八年（西元一〇八五年），此时黄庭坚监德州（今属山东）德平镇。黄几复，名介，南昌（今江西南昌市）人，与黄庭坚少年交游，交情很深，黄山谷为几复写过不少诗，如《留几复饮》、《再留几复饮》、《赠别几复》等。时几复知四会县（今广东四会县）。当时两人分处天南海北，山谷遥想友人，写下了这首诗。
此诗称赞黄几复廉正、幹练、好学，而对其垂老沉沦的处境，深表惋惜，抒发了思念友人的殷殷之情，寄寓了对友人怀才不遇的不平与愤慨。全诗情真意厚，感人至深。而在好用书卷，以故为新，运古于律，拗折波峭等方面，又都表现出黄诗的特色，可视为黄庭坚的代表作。', '黄几复：即黄介，字几复，南昌人，是黄山谷少年时的好友。其事迹见黄山谷所作《豫章黄先生文集·巻二十三·黄几复墓誌铭》。
「我居北海君南海」句：《左传·僖公四年》：「君处北海，寡人处南海，惟是风马牛不相及也。」作者在「跋」中说：「几复在广州四会，予在德州德平镇，皆海滨也。」
「寄雁传书谢不能」句：传说雁南飞时不过衡阳回雁峰，更不用说岭南了。
四立壁：《史记·司马相如传》：「文君夜奔相如，相如驰归成都，家徒四壁立。」
蕲（qí）：祈求。
肱：上臂，手臂由肘到肩的部分，古代有三折肱而为良医的说法。
想得：一作“想见”。
瘴（zhàng）溪：旧传岭南边远之地多瘴气。
溪：文集、明大全本作「烟」。', '我住在北方海滨，而你住在南方海滨，欲托鸿雁传书，它却飞不过衡阳。
当年春风下观赏桃李共饮美酒，江湖落魄，一别已是十年，常对着孤灯听着秋雨思念着你。
你支撑生计也只有四堵空墙，艰难至此。古人三折肱后便成良医，我却但愿你不要如此。
想你清贫自守发奋读书，如今头髮已白了罢，隔着充满瘴气的山溪，猿猴哀鸣攀援深林里的青藤。', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea70f5e272d4b225489ef", "shortContent": "此诗作于神宗元丰八年（1085），其时诗人监德州（今属山东）德平镇。黄幾复，名介，南昌（今属江西）人，与诗人少年交游，此时知四会县（今属广东）；其事迹见《黄幾复墓志铭》（《豫章黄先生文集》卷二三）。\n首句“我居北海君南海”化用《左传·僖公四年》楚子问齐桓公“君处北海，寡人处南海”的话，起势突兀。写彼此所居之地一“北”一“南”，已露怀念友人、望而不见之意；各缀一“海”字，更显得相隔辽远，海天茫茫。作...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fb67ec0471b0062b8b5b0", "bookTitle": "黄庭坚诗文鉴赏辞典", "articleId": "6464aee55e6bb82b8cc46851", "shortContent": "此诗作于神宗元丰八年（1085），其时诗人监德州（今属山东）德平镇。黄幾复，名介，南昌（今属江西）人，与诗人少年交游，此时知四会县（今属广东）；其事迹见《黄幾复墓志铭》（《豫章黄先生文集》卷二三）。\n\n首句“我居北海君南海”化用《左传·僖公四年》楚子问齐桓公“君处北海，寡人处南海”的话，起势突兀。写彼此所居之地一“北”一“南”，已露怀念友人、望而不见之意；各缀一“海”字，更显得相隔辽远，海天茫茫。...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646b188945e4710056deb586", "shortContent": "此诗作于神宗元丰八年（1085），其时诗人监德州（今属山东）德平镇。黄幾复，名介，南昌（今属江西）人，与诗人少年交游，此时知四会县（今属广东）；其事迹见《黄幾复墓志铭》（《豫章黄先生文集》卷二三）。\n\n首句“我居北海君南海”化用《左传·僖公四年》楚子问齐桓公“君处北海，寡人处南海”的话，起势突兀。写彼此所居之地一“北”一“南”，已露怀念友人、望而不见之意；各缀一“海”字，更显得相隔辽远，海天茫茫。...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '宋·王直方《王直方诗话》：张文潜尝谓余曰：「黄九诗『桃李春风一杯酒，江湖夜雨十年灯』，真是奇语。」
宋·普闻《诗论》：初二句为破题，第三第四句为颔联。大凡颔联皆宜意对。春风桃李但一杯，而想象无聊，窭空为甚，飘蓬寒雨十年灯之下，未见青云得路之便，其羁孤未遇之叹，具见矣。其句意亦就境中宣出。「桃李春风」、「江湖夜雨」，皆境也。昧者不知，直谓境句，谬矣。
宋·陈模《怀古录·卷上》：山谷「桃李春风一杯酒，江湖夜雨十年灯」，尽言杯酒别又十年灯矣。同一机轴，此最高处。
清·方仪卫《昭昧詹言·卷二十》：亦是一起浩然，一气涌出。五六一顿。结句与前一样笔法。山谷兀傲纵横，一气涌现。然专学之，恐流入空滑，须慎之。
近·陈衍《宋诗精华录·卷二》：次句语妙，化臭腐为神奇也。三四为此老最合时宜语；五六则狂奴故态矣。', 'center', 1363294056, '57b90ff17db2a200542719ca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10332, '爱莲说', NULL, 1379, 38, 2, 14, '周敦颐', NULL, 10087, '57bbbd1b2e958a0069403f71', '宋', 'wen', '文', 'http://baike.baidu.com/subview/121681/15847788.htm', '', '水陆草木之花，可爱者甚蕃。晋陶渊明独爱菊。自李唐来，世人甚爱牡丹。予独爱莲之出淤泥而不染，濯清涟而不妖，中通外直，不蔓不枝，香远益清，亭亭净植，可远观而不可亵玩焉。
予谓菊，花之隐逸者也；牡丹，花之富贵者也；莲，花之君子者也。噫！菊之爱，陶后鲜有闻。莲之爱，同予者何人？牡丹之爱，宜乎众矣。', '宋熙宁四年（公元一〇七一年），周敦颐来星子任南康知军。周敦颐为人清廉正直，襟怀淡泊，平生酷爱莲花。周敦颐来星子后，在军衙东侧开挖了一口池塘，全部种植荷花。周敦颐来星子时已值暮年（五十五岁），又抱病在身，所以每当茶余饭后，他或独身一人，或邀三五幕僚好友，于池畔赏花品茗，并写下了散文《爱莲说》。
这篇文章通过对莲的形象和品质的描写，歌颂了莲花坚贞的品格，也表现了作者洁身自爱的高洁人格和洒落的胸襟。', '可：值得。
蕃：通「繁」，多。
晋陶渊明独爱菊：晋朝陶渊明只喜爱菊花。陶渊明（365—427），一名潜，字元亮，自称五柳先生，世称靖节先生，东晋浔阳柴桑（现江西省九江县）人，东晋著名诗人。是著名的隐士。他独爱菊花，常在诗里咏菊，如《饮酒》诗里的「采菊东篱下，悠然见南山」，曏来称为名句。独，只，唯独。
自李唐来，世人甚爱牡丹：从唐朝以来，人们很爱牡丹。唐人爱牡丹，古书里有不少记载，如唐朝李肇的《唐国史补》里说：「京城贵游，尚牡丹……每春暮，车马若狂……种以求利，一本有直数万者。」李唐，指唐朝。唐朝的皇帝姓李，所以称为「李唐」。世人，社会上的一般人。自，（自）从。盛，很，十分，一作「甚」。
予（yú）：我。
之：助词，用于主谓之间，取消句子独立性，无实际意义。
淤泥：河沟或池塘里积存的污泥。
染：沾染（污秽）。
濯（zhuó）：洗涤。
清涟（lián）：水清而有微波，这里指清水。
妖：妖艳。美丽而不端庄。
中通外直：（它的茎）内空外直。通，空。直，挺立。
不蔓（màn）不枝：不生枝蔓，不长枝节。蔓，名词用作动词，生枝蔓。枝，名词用作动词，长枝节。
香远益清：香气远播，更加显得清芬。远，形容词作动词，遥远，空间距离大。益，更，更加。
亭亭净植：笔直地洁净地立在那里。亭亭，耸立的样子。植，「植」通「直」，立。
可：可以。
亵（xiè）：亲近而不庄重。
玩：玩弄。
焉：助词。
谓：认为。
隐逸者：指隐居的人。在封建社会里，有些人不愿意跟统治者同流合污，就隐居避世。
君子：指品德高尚的人。
噫：感叹词，相当于「啊」。
菊之爱：对于菊花的喜爱。之，的。一说为「宾语提前的标志」。下文「莲之爱」、「牡丹之爱」同。
鲜（xiǎn）：少。
闻：听说。
同予者何人：像我一样（喜爱莲花的）还有什么人呢？
宜乎众矣：（喜爱牡丹的）人应该是很多了。宜，当，这里与乎连用有当然的意思。众，多。', '水上，陆地上的各种花草树木，值得喜爱的非常多。晋朝陶渊明唯独喜爱菊花。从唐朝以来世间的人们非常喜爱牡丹。我唯独喜爱莲花，它从淤泥中长出来，却不沾染污秽，在清水里洗涤过但是不显得妖媚，它的茎中间贯通，外形挺直，不生枝蔓，不长枝节，香气远播，更加清香，笔直地洁净地立在那里，可以远远地观赏但是不能玩弄它。
我认为，菊花是花中的隐士；牡丹，是花中的富贵者；莲花，是花中的君子。唉！对于菊花的喜爱，在陶渊明以后很少听到了。对于莲花的喜爱，和我一样的还有谁？对于牡丹的喜爱，当然有很多人了。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1f734a8757d5a0edb93", "shortContent": "周敦颐是北宋理学濂洛学派创始人、二程（程颢、程颐）的老师。他博学力行，品德高尚，为官清廉，不媚权贵，明断狱案，得到人民的赞赏。北宋中叶，士大夫在封建统治者诱掖下，追求富贵利达，耽于享乐之风盛行。作者目击时弊，慨然命笔，写成此篇借物咏志的小品，通过对莲花的爱慕与礼赞，表明自己对美好理想的憧憬，对高尚情操的崇奉，对庸劣世态的憎恶。其懿德高行与美学情趣，在当时具有现实意义，在今天也不失其思想价值。\n作者...", "authors": ["邓韶玉"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "64720aefb6a81d0c532bb160", "shortContent": "周敦颐是北宋理学濂洛学派创始人、二程（程颢、程颐）的老师。他博学力行，品德高尚，为官清廉，不媚权贵，明断狱案，得到人民的赞赏。北宋中叶，士大夫在封建统治者诱掖下，追求富贵利达，耽于享乐之风盛行。作者目击时弊，慨然命笔，写成此篇借物咏志的小品，通过对莲花的爱慕与礼赞，表明自己对美好理想的憧憬，对高尚情操的崇奉，对庸劣世态的憎恶。其懿德高行与美学情趣，在当时具有现实意义，在今天也不失其思想价值。\n作者...", "authors": ["邓韶玉"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413196630, '57b8fe240a2b58005c922a12', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10333, '石钟山记', NULL, 63, 3406, 1, 5, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'wen', '文', 'http://baike.baidu.com/view/118646.htm', '', '《水经》云：「彭蠡之口有石钟山焉。」郦元以为下临深潭，微风鼓浪，水石相搏，声如洪钟。是说也，人常疑之。今以钟磬置水中，虽大风浪不能鸣也，而况石乎！至唐李渤始访其遗踪，得双石于潭上，扣而聆之，南声函胡，北音清越，桴止响腾，余韵徐歇。自以为得之矣。然是说也，余尤疑之。石之铿然有声者，所在皆是也，而此独以钟名，何哉？
元丰七年六月丁丑，余自齐安舟行适临汝，而长子迈将赴铙之德兴尉，送之至湖口，因得观所谓石钟者。寺僧使小童持斧，于乱石间，择其一二扣之，硿硿焉。余固笑而不信也。至暮夜月明，独与迈乘小舟，至绝壁下。大石侧立千尺，如猛兽奇鬼，森然欲搏人，而山上栖鹘，闻人声亦惊起，磔磔云霄间；又有若老人咳且笑于山谷中者，或曰：「此鹳鹤也。」余方心动欲还，而大声发于水上，噌洪如钟鼓不绝，舟人大恐。徐而察之，则山下皆石穴罅，不知其浅深，微波入焉，涵澹澎湃而为此也。舟回至两山间，将入港口，有大石当中流，可坐百人，空中而多窍，与风水相吞吐，窾坎镗鞳之声，与向之噌吰者相应，如乐作焉。因笑谓迈曰：「汝识之乎？噌吰者，周景王之无射也；款坎镗嗒者，魏庄子之歌钟也。古之人不余欺也。」
事不目见耳闻，而臆断其有无，可乎？郦元之所见闻殆与余同，而言之不详；士大夫终不肯以小舟夜泊绝壁之下，故莫能知；而渔工水师虽知而不能言，此世所以不传也。而陋者乃以斧斤考击而求之，自以为得其实，余是以记之，盖叹郦元之简，而笑李渤之陋也。', '《石钟山记》是北宋文学家苏东坡于宋神宗元丰七年（公元1084年）游石钟山后所写的一篇考察性的游记。文章通过记叙对石钟山得名由来的探究，强调要正确判断一件事物，必须要深入实际，认真调查。', '石钟山，在江西湖口鄱阳湖东岸，有南、北二山，在县城南边的叫上钟山，在县城北边的叫下钟山。明清时有人认为苏轼关于石钟山得名由来的说法也是错误的，正确的说法是：「盖全山皆空，如钟覆地，故得钟名。」今人经过考察，认为石钟山之所以得名，是因为它具有钟之「声」，又具有钟之「形」。
彭蠡：鄱阳湖的又一名称。
郦元：即郦道元，《水经注》的作者。
鼓：振动。
搏：击，拍。
洪钟：大钟。
是说：这个说法。
磬（qìng）：古代打击乐器，形状像曲尺，用玉或石制成。
李渤：唐朝洛阳人，写过一篇《辨石钟山记》。
遗踪：旧址，陈迹。这里指所在地。
南声函胡：南边（那座山石）的声音重浊而模糊。函胡，通「含糊」。
北音清越：北边（那座山石）的声音清脆而响亮。越，高扬。
桴（fú）止响腾：鼓槌停止了（敲击），声音还在传播。腾，传播。
余韵徐歇：馀音慢慢消失。韵，这里指声音。徐，慢。
得之：找到了这个（原因）。之，指石钟山命名的原因。
尤：更加。
铿（kēng）然：敲击金石所发出的响亮的声音。
所在皆是：到处都（是）这样。是，这样。
元丰：宋神宗的年号。
六月丁丑：农历六月初九。
齐安：在今湖北黄州。
临汝：即汝州（今河南临汝）。
赴：这里是赴任、就职的意思。
湖口：今江西湖口。
硿（kōng）硿焉：硿硿地（发出响声）。焉，相当于「然」。
莫（mù）夜：晚上。莫，通「暮」。
森然：形容繁密直立。
搏人：捉人，打人。
栖鹘（hú）：宿巢的老鹰。鹘，鹰的一种。
磔（zhé）磔：鸟鸣声。
鹳鹤：水鸟名，似鹤而顶不红，颈和嘴都比鹤长。
心动：这里是心惊的意思。
噌吰（chēnghóng）：这里形容钟声洪亮。
舟人：船夫。
罅（xià）：裂缝。
涵澹澎湃：波浪激荡。涵澹，水波动荡。澎湃，波浪相激。
为此：形成这种声音。
中流：水流的中心。
空中：中间是空的。
窍：窟窿。
窾（kuǎn）坎镗（táng）鞳（tà）：窾坎，击物声。镗鞳，钟鼓声。
汝识（zhì）之乎：你知道那些（典故）吗？识，知道。
周景王之无射（yì）：《国语》记载，周景王二十三年（前522）铸成「无射」钟。
魏庄子之歌钟：《左传》记载，鲁襄公十一年（前561）郑人以歌钟和其他乐器献给晋侯，晋侯分一半赐给晋大夫魏绛。庄子，魏绛的谥号。歌钟，古乐器。
古之人不余欺也：古人（称这山为「石钟山」）没有欺骗我啊！不余欺，就是「不欺余」。
臆断：根据主观猜测来判断。臆，胸。
殆：大概。
终：终究。
渔工水师：渔人（和）船工。
言：指用文字表述、记载。
此世所以不传也：这（就是）世上没有流传下来（石钟山得名由来）的缘故。
陋者：浅陋的人。
以斧斤考击而求之：用斧头敲打石头的办法来寻求（石钟山得名的）原因。考，敲击。
实：指事情的真相。', '', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1fa34a8757d5a0edba1", "shortContent": "元丰七年（1084）正月，神宗出手札命苏轼由黄州（今湖北黄冈）移任汝州（今河南汝州）团练副使本州安置。三月文书到，四月离黄州，计划走水路经长江、淮河入洛赴任所，先至江西，游庐山，五月至筠州（今江西高安）别其弟子由（时监筠州盐酒税），六月送长子迈赴饶州德兴（今属江西）县尉任，途经湖口，游石钟山，写了这篇游记。文中将议论和叙述相结合，通过夜游石钟山的实地考查，对郦道元和李渤关于石钟山得名的说法进行了分...", "authors": ["王思宇"], "pressName": "上海辞书出版社"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646858e95fc8182fe9ad3cc2", "shortContent": "元丰七年（1084）正月，神宗出手札命苏轼由黄州（今湖北黄冈）移任汝州（今河南临汝）团练副使本州安置。三月文书到，四月离黄州，计划走水路经长江、淮河入洛赴任所，先至江西，游庐山，五月至筠州（今江西高安）别其弟子由（时监筠州盐酒税），六月送长子迈赴饶州德兴（今属江西）县尉任，途经湖口，游石钟山，写了这篇游记。文中将议论和叙述相结合，通过夜游石钟山的实地考查，对郦道元和李渤关于石钟山得名的说法进行了分...", "authors": ["王思宇"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "6471df425e6bb82b8cfb47ce", "shortContent": "元丰七年(1084)正月，神宗出手札命苏轼由黄州（今湖北黄冈）移任汝州（今河南汝州）团练副使本州安置。三月文书到，四月离黄州，计划走水路经长江、淮河入洛赴任所，先至江西，游庐山，五月至筠州（今江西高安）别其弟子由（时监筠州盐酒税），六月送长子迈赴饶州德兴（今属江西）县尉任，途经湖口，游石钟山，写了这篇游记。文中将议论和叙述相结合，通过夜游石钟山的实地考察，对郦道元和李渤关于石钟山得名的说法进行了分...", "authors": ["王思宇"], "pressName": "上海辞书出版社"}]', '刘後村《後村先生大全集·卷一百一十》：坡公此记：议沦，天下之名言也；笔力，天下之至文也；楷法，天下之妙画也。
郑之惠《苏长公合作·卷二》：平摘直叙，却自波折可喜，此是性灵上带来丈字，今古所希……苏长公字字挟飞鸣之势。
杨升菴《三苏文范·卷十四》：通篇讨山水之幽胜，而中较李渤、寺僧、郦元之简陋，又辨出周景王、魏庄子之钟音。其转折处，以人之疑起己之疑，至见中流大石，始释己之疑，故此记遂为绝调。
杨升菴《三苏文范·卷十四》引锺退谷：真穷理之言，所谓身到处不肯放过也。又：可见穷山水之情者，不是好事，真是虚心细心。
杨升菴《三苏文范·卷十四》引袁中郎：予涉历方内名山，与同志探幽选胜，退必记之。阅坡公集中记述，恍通千古一知己。
茅鹿门《唐宋八大家文钞·东坡文钞·卷一百四十一》：风旨亦有《水经》来，然多奇峭之兴。
姚惜抱《古文辞类纂·卷五十六》引方望溪：潇洒自得，子瞻诸记中特出者。
姚惜抱《古文辞类纂·卷五十六》引刘耕南：以心动欲还跌出大声发于水上，才有波折，而兴会更觉淋漓。钟声二处，必取古钟二事以实之，具此诙谐，文章妙趣洋溢行间。坡公第一首记文。
沈歸愚《唐宋八家文读本·卷二十三》：记山水并悟读书观理之法。盖臆断有无，而或简或陋，均可以求古人也。通体神行，末幅尤极得心应手之乐。
吴楚材、吴调侯《古文观止·卷十一》：世人不晓石钟命名之故，始失于旧注之不详，继失于浅人之俗见。千古奇胜，埋没多少。坡公身历其境，闻之真，察之详，从前无数疑案，一一破尽。爽心快目。
吕晚村《晚村精选八大家古文》：此翻案也。李翻郦，苏又翻李，而以己之所独得，详前之所未备，则道元亦遭简点矣。文最奇致，古今绝调。', 'indent', 1423176539, '57b978aa5bbb50005b7c7507', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10334, '正月十五夜', NULL, 260, 16, 2, 1, '苏味道', NULL, 10088, '57b917680a2b58005c92fc68', '唐', 'shi', '诗', 'http://baike.baidu.com/view/1414384.htm', '', '火树银花合，星桥铁锁开。
暗尘随马去，明月逐人来。
游伎皆秾李，行歌尽落梅。
金吾不禁夜，玉漏莫相催。', '初唐时期，每年元宵节晚上，洛阳城里都要大放花灯。该诗第一句写灯，把灯比作“火树”和“银花”，表现出灯的辉煌。第二句写观灯的环境，既有美丽壮观的自然景象，又有政治环境，即元宵佳节特许放宽禁区后市民可以信步漫游所带来的喜悦氛围。第三四句总写观灯盛况，抒发骑马逐月的欢乐情怀。第五六句细写游人盛景，歌舞妓们艳丽华美，杂于各色人之间，踏着“梅花落”曲子，唱着愉快的歌，把观灯之乐推向高潮。最后两句用“金吾不禁”和“玉漏莫催”来表达人们让欢乐继续下去的心愿，有力地烘托出太平盛世歌舞升平的初唐繁荣，让人感到兴犹未尽，产生出强烈的艺术效果。', '火树银花：比喻灿烂绚丽的灯光和焰火。特指上元节的灯景。此句对后世影响甚大，如宋辛弃疾《青玉案·元夕》词有：“东风夜放花千树……蓦然回首，那人却在灯火阑珊处。”《红楼梦》十八回：“只见庭燎绕空，香雪布地，火树琪花，金窗玉槛”
星桥：星津桥，天津三桥之一，“洛水贯都，以像星汉”此处或以星津桥指代天津三桥。”东都洛阳，洛水从西面流经上阳宫南，流到皇城端门外，分为三道，上各架桥，南为星津桥，中为天津桥，北为黄道桥。开元年间，改修天津桥，星津桥毁，二桥合而为一。
铁锁开：比喻京城开禁。唐朝都城都有宵禁，但在正月十五这天取消宵禁，连接洛水南岸的里坊区与洛北禁苑的天津桥、星津桥、黄道桥上的铁锁打开，任平民百姓通行。
暗尘：暗中飞扬的尘土。
逐人来：追随人流而来。
游伎：歌女、舞女。一作“游骑（jì）”
秾李：此处指观灯歌伎打扮得艳若桃李。《诗经·召南·何彼秾矣》：“何彼秾矣，华如桃李。”
落梅：曲调名。
金吾：原指仪仗队或武器，此处指金吾卫，掌管京城戒备，禁人夜行的官名，汉代置。《唐两京新记》云：”正月十五日夜，敕金吾弛禁，前后各一日以看灯，光若昼日。”
不禁夜：指取消宵禁。唐时，京城每天晚上都要戒严，对私自夜行者处以重罚。一年只有三天例外，即正月十四、十五、十六。
玉漏：古代用玉做的计时器皿，即滴漏。', '', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e928c7d0ac114549536e5", "shortContent": "这首诗是描写长安城里元宵之夜的景象。据《大唐新语》和《唐两京新记》记载：每年这天晚上，长安城里都要大放花灯；前后三天，夜间照例不戒严，看灯的真是人山人海。豪门贵族的车马喧阗，市民们的歌声笑语，汇成一片，通宵都在热闹的气氛中度过。\n春天刚刚才透露一点消息，还不是万紫千红的世界，可是明灯错落，在大路两旁、园林深处映射出灿烂的辉光，简直像明艳的花朵一样。从“火树银花”的形容，我们不难想象，这是多么奇丽的...", "authors": ["马茂元"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389abbb31680ae4c4b72e", "shortContent": "这首诗是描写长安城里元宵之夜的景象。据《大唐新语》和《唐两京新记》记载：每年这天晚上，长安城里都要大放花灯；前后三天，夜间照例不戒严，看灯的真是人山人海。豪门贵族的车马喧阗，市民们的歌声笑语，汇成一片，通宵都在热闹的气氛中度过。\n\n春天刚刚才透露一点消息，还不是万紫千红的世界，可是明灯错落，在大路两旁、园林深处映射出灿烂的辉光，简直像明艳的花朵一样。从“火树银花”的形容，我们不难想象，这是多么奇丽...", "authors": ["马茂元"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270309761253910e904d5", "shortContent": "正月十五元宵节是我国的传统节日，这一天大街小巷男女老幼倾城出游，甚至平日难有机会出门的大家闺秀、小家碧玉也三五成群出来嬉闹游玩。平日就多闲又多情的文人们更是不会错过这大好机会。这是一个举国欢腾的民间佳节。男女老幼积蓄一年的情感在这一天终于有机会尽情宣泄。其盛况有点类似今日西方的狂欢节。此情此景，《大唐新语》和《唐两京新记》等杂著中都有许多记载。热闹之后，自然也少不了题诗作文。翻翻中国古代的诗词文章...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270537ccdb86c49f29239", "shortContent": "正月十五元宵节是我国的传统节日，这一天大街小巷男女老幼倾城出游，甚至平日难有机会出门的大家闺秀、小家碧玉也三五成群出来嬉闹游玩。平日就多闲又多情的文人们更是不会错过这大好机会。这是一个举国欢腾的民间佳节。男女老幼积蓄一年的情感在这一天终于有机会尽情宣泄。此情此景，《大唐新语》和《唐两京新记》等杂著中都有许多记载。热闹之后，自然也少不了题诗作文。翻翻中国古代的诗词文章，其中有多少是与元宵佳节有关！其...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '《本事诗》：宰相苏味道与张昌龄俱有名，暇日相遇，互相夸诮。昌龄曰：“某诗所以不及相公者，为无‘银花合’，故也。”苏有《观灯》诗曰：“火树银花合……”味道云：“子诗虽无‘银花合’，还有‘金铜钉’。”昌龄赠张昌宗诗曰：“昔日浮丘伯，今同丁令威。”遂相与拊掌大笑。
《瀛奎律髓》方回：味道武后时人，诗律已如此健快。古今元宵诗少，五言好者殆无出此篇矣。
《唐诗镜》：纤浓恰中。
《姜斋诗话》：“火树银花合”，浑然一气。
《唐诗成法》：此诗人传诵已久，他作莫及者。元夜情景，包括已尽，笔致流动。天下游人，今古同情，结句遂成绝调。
《闻鹤轩初盛唐近体读本》：陈德公先生曰：三、四故是爽笔。“秾李”“落梅”工切，便极见妍姿。结语得“金”、“玉”字小对，弥足增致；他处金玉纁黄、藻丽堆垛者，又复无致。此所须辨矣。
《瀛奎律髓汇评》：冯舒：真正盛唐。《品汇》所分，谬也。纪昀：三、四自然有味，确是元夜真景，不可移之他处。夜游得神处尤在出句，出句得神处尤在“暗”字。许印芳：八句皆对，唐律多如此。
此诗对仗工稳，前后照应，结构紧密，可称得上初唐五律的典范。作品以其常读常新的艺术魅力昭示着后世诗人，促进了五言律诗的成熟。“火树银花”一词亦成为描写节日之夜的特用成语。历代诗评家对此诗多有赞赏。清代学者纪昀认为该诗“三四句自然有味，确是元夜真景，不可移之他处。夜游得神处尤在出句，出句得神处尤在‘暗’字”（《瀛奎律髓汇评》卷十六）。', 'center', 1363294926, '57b8f839c4c97100558ee59e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10346, '山坡羊 · 潼关怀古', NULL, 393, 131, 3, 15, '张养浩', NULL, 10090, '57b921e95bbb50005b793fa9', '元', 'qu', '曲', 'http://baike.baidu.com/view/392406.htm', '', '峰峦如聚，波涛如怒，山河表里潼关路。望西都，意踌躇。伤心秦汉经行处，宫阙万间都做了土。兴，百姓苦；亡，百姓苦。', '此为作者赴陕西救灾途经潼关所作。此曲抚今追昔，从历代王朝的兴衰更替，想到人民的苦难，一针见血地点出了封建统治与人民的对立，表现了作者对历史的思索和对人民的同情。这种同情与关怀的出发点是儒家经世济民的思想，在传统的五七言诗歌中本为常见，但在元代散曲中却是少有。全曲采用的是层层深入的方式，由写景而怀古，再引发议论，将苍茫的景色、深沉的情感和精辞的议论三者完美结合，具有强烈的感染力，字里行间中充满着历史的沧桑感和时代感，既有怀古诗的特色，又有与众不同的沉郁风格。', '山坡羊：曲牌名，是这首散曲的格式；「潼关怀古」是标题。
峰峦如聚：形容群峰攒集，层峦叠嶂。聚，聚拢、包围。
波涛如怒：形容黄河波涛的汹涌澎湃。怒，指波涛汹涌。
表里：即内外。《左传·僖公二十八年》：「表里山河，必无害也。」注：「晋国外河而内山。」
潼关：古关口名，在今陕西省临潼县，关城建在华山山腰，下临黄河，扼秦、晋、豫三省要冲，非常险要，为古代入陕门戸，是历代的军事重地。
「山河表里潼关路」句：外面是山，里面是河，形容潼关一带地势险要。具体指潼关外有黄河，内有华山。
西都：指长安（今陕西西安）。这是泛指秦汉以来在长安附近所建的都城。秦、西汉建都长安，东汉建都洛阳，因此称洛阳为东都，长安为西都。
踌躇：一作「踟蹰（chí chú）」，犹豫、徘徊不定，心事重重，此处形容思潮起伏，，感慨万端陷入沉思，表示心里不平静。。
伤心：令人伤心的事，形容词作动词。
秦汉经行处：秦朝（前221年~前206年）都城咸阳和西汉（前208~8）的都城长安都在陕西省境内潼关的西面。经行处，经过的地方。指秦汉故都遗址。
宫阙：宫，宫殿；阙，皇宫门前面两边的楼观。
「伤心秦汉经行处，宫阙万间都做了土」句：谓目睹秦汉遗迹，旧日宫殿尽成废墟，内心伤感。
兴、亡：指朝代的盛衰更替。兴，指政权的统治稳固。', '（华山的）山峰从四面八方会聚，（黄河的）波涛像发怒似的汹涌。潼关外有黄河，内有华山，山河雄伟，地势险要。遥望古都长安，陷于思索之中。从秦汉宫遗址经过，引发无限伤感，万间宫殿早已化作了尘土。一朝兴盛，百姓受苦；一朝灭亡，百姓依旧受苦。', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec28cd635634aee3e9559", "shortContent": "这首小令是作者路过潼关时写的。《元史·张养浩传》说：“天历二年，关中大旱，饥民相食，特拜（张养浩）为陕西行台中丞。……登车就道，遇饥者则赈之，死者则葬之。”并说他“到官四月，忧劳以死”。就他的作品和有关史料看，他对元朝的黑暗统治深感不满，对人民的疾苦相当关心。他在“关中大旱，饥民相食”之时写的这首〔山坡羊〕，尽管题为“怀古”，实际上重在“伤今”，其揭露、批判的锋芒，既指向历史上历朝累代的统治者，更...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62de2d8a3bba5677642ac2d1", "bookTitle": "元曲三百首", "articleId": "630593d2a677602a202f8193", "shortContent": "这首小令是作者路过潼关时写的。《元史·张养浩传》说：“天历二年，关中大旱，饥民相食，特拜（张养浩）为陕西行台中丞。……登车就道，遇饥者则赈之，死者则葬之。”并说他“到官四月，忧劳以死”。就他的作品和有关史料看，他对元朝的黑暗统治深感不满，对人民的疾苦相当关心。他在“关中大旱，饥民相食”之时写的这首【山坡羊】，尽管题为“怀古”，实际上重在“伤今”，其揭露、批判的锋芒，既指向历史上历朝累代的统治者，更...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "6277bbb9f716b7243c7bdff3", "bookTitle": "元曲鉴赏辞典", "articleId": "63126ed273206168b2e02001", "shortContent": "天历二年，关中大旱。朝廷派张养浩前去赈灾。这一天，张养浩一行来到关中的门户——潼关。\n潼关是关中的大门，更是关中的险要之地。张养浩举目四顾，被这险峻而壮阔的山形水势给吸引住了。这里东有崤山，北有中条，西有华岳，四面的山峦层层叠叠，都聚集在潼关周围。一个“聚”字，写出了群山环绕之态。这里的水势也有一番胜景。从潼关之顶往下望去，黄河从龙门倾泻而来，汹涌澎湃，直奔关下。一个“怒”字，写出了黄河奔腾咆哮之...", "authors": ["李若晖"], "pressName": "崇文书局"}, {"bookId": "62777f94f716b7243c7b102b", "bookTitle": "元曲三百首鉴赏辞典 ", "articleId": "63126f08f2af4e09d55b65cc", "shortContent": "元文宗天历二年（1329），关中大旱，张养浩被任命为陕西行台中丞，前往赈灾，途经未央、潼关、骊山等地，用【山坡羊】调名写下了一组怀古曲。这首小令即是经潼关写下的。\n潼关位于今陕西省潼关县东南，地处陕、豫、晋三省交界，加之南有华山，北有太行，黄河从山间滚滚流过，形势险要，历来为兵家必争之地。“峰峦如聚，波涛如怒，山河表里潼关路。”小令开头三句就点明了潼关险要的地形。“峰峦如聚”，先写山，写出了山峰的...", "authors": ["李新科"], "pressName": "崇文书局"}]', '朱权《太和正音谱》：张云庄之词如玉树临风。
孛术鲁翀《云庄类稿序》：其文渊奥昭朗，豪宕妥帖，辞必己出，凛有生气。', 'indent', 1423176644, '57b90f47165abd0054c0431a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10347, '越调 · 天净沙 · 秋思', NULL, 2039, 68, 2, 17, '马致远', NULL, 10091, '57b9b9eb79bc4400639c4264', '元', 'qu', '曲', 'http://baike.baidu.com/subview/188620/18849697.htm', '', '枯藤老树昏鸦，小桥流水人家，古道西风瘦马。夕阳西下，断肠人在天涯。', '此曲以多种景物并置，组合成一幅秋郊夕照图，让天涯游子骑一匹瘦马出现在一派凄凉的背景上，从中透出令人哀愁的情调，它抒发了一个飘零天涯的游子在秋天思念故乡、倦于漂泊的凄苦愁楚之情。这支小令句法别致，前三句全由名词性词组构成，一共列出九种景物，言简而意丰。全曲仅五句二十八字，语言极为凝练却容量巨大，意蕴深远，结构精巧，顿挫有致，被后人誉为“秋思之祖”。', '天净沙：曲牌名。
枯藤：枯萎的枝蔓。昏鸦：黄昏时的乌鸦。昏：傍晚。
人家：农家。此句写出了诗人对温馨的家庭的渴望。
古道：古老荒凉的道路。西风：寒冷、萧瑟的秋风。瘦马：瘦骨如柴的马。
断肠人：形容伤心悲痛到极点的人，此处指漂泊天涯、极度忧伤的旅人。天涯：远离家乡的地方。', '枯藤缠绕着老树，树枝上栖息着黄昏时归巢的乌鸦。
小桥下，流水潺潺，旁边有几户人家。
在古老荒凉的道路上，秋风萧瑟，一匹疲惫的瘦马驮着我前行。
夕阳向西缓缓落下，极度忧伤的旅人还漂泊在天涯。', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec27e2cee9a0c24ed997b", "shortContent": "这是写“秋思”的名曲，被誉为“秋思之祖”（周德清《中原音韵》）。写秋思而如此出名，究竟有什么奥秘呢？\n第一，有景有人，人和景都是精心选择的，最能表现“秋思”。\n秋思指一种萧条、寂寞、悲凉的情思。这种情思之所以冠以“秋”字，就因为“秋”是触媒剂。宋玉的《九辩》一开头就阐明了这个道理：\n悲哉，秋之为气也！萧瑟兮，草木摇落而变衰。憭慄兮，若在远行；登山临水兮，送将归。\n秋思既然是秋景触发的，那么要写好秋...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62de2d8a3bba5677642ac2d1", "bookTitle": "元曲三百首", "articleId": "630593d2eebf5e0fdea511d6", "shortContent": "这是写“秋思”的名曲，被誉为“秋思之祖”（周德清《中原音韵》）。写秋思而如此出名，究竟有什么奥秘呢？\n\n第一，有景有人，人和景都是精心选择的，最能表现“秋思”。秋思指一种萧条、寂寞、悲凉的情思，这种情思之所以冠以“秋”字，就因为“秋”是触媒剂。宋玉的《九辩》一开头就阐明了这个道理：“悲哉秋之为气也！萧瑟兮草木摇落而变衰。憭慄兮若在远行，登山临水兮送将归。”秋思既然是秋景触发的，那么要写好秋思，就得...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "6277bbb9f716b7243c7bdff3", "bookTitle": "元曲鉴赏辞典", "articleId": "63126ed0c305cf0801816d06", "shortContent": "这首小令手法高妙，意境深远，感情真切，素有“秋思之祖”的美誉。它的篇幅虽短，但将游子的愁思抒写无遗。王国维《人间词话》评曰：“寥寥数语，深得唐人绝句妙境。”\n此曲描绘了一幅绝妙的秋思图。时至深秋，一位游子还在天涯漂泊。他骑着一匹瘦马，冒着萧瑟的秋风，正在蜿蜒曲折的古道上缓慢地行进着。沿途悲凉的秋意向他眼前扑来：那枯黄藤蔓缠绕在老树之上，那数点昏鸦已落在树上栖息。面对此景，他不禁黯然神伤。他边走边想...", "authors": ["陈咸堡"], "pressName": "崇文书局"}, {"bookId": "62777f94f716b7243c7b102b", "bookTitle": "元曲三百首鉴赏辞典 ", "articleId": "63126efd7f0b9738b369b0a6", "shortContent": "关于这首散曲的作者学术界有争议。有学者认为它不是马致远的作品，是无名氏之作。\n“自古逢秋悲寂寥”，悲秋是我国古典文学的主题之一。自宋玉在《九辩》中以“悲哉秋之为气也”句开篇，后来的文人墨客都是一片悲秋之声，但这种感情的表现，却因人因事的不同而千差万别，这种感情本身，也不是“悲”、“愁”二字所能了得。马致远年轻时热衷功名，但由于元统治者实行民族等级政策，因而一直未能得志。他几乎一生都过着漂泊无定的生...", "authors": ["陈鹏"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6472022d7f27182da38c3e71", "shortContent": "通常说这只曲子之所以写得好，在于“描绘了一幅绝妙的秋景图”。这当然不算错。但更确切地说，则是一幅绝妙的秋思图。这幅图，是随着抒情主人公的脚步、视线和思绪展开的。“断肠人在天涯”一句，尽管在结尾，但实际上是贯串全局的主线。读这首曲，一开头就应该想到它，并且跟着“断肠人”在“天涯”漂泊的足迹进入画卷。大致说来，这画卷是这样的：\n的：时已深秋，一位远离故乡的“断肠人”还在天涯漂泊。他骑着瘦马，冒着西风，...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '周德清《中原音韵·小令定格》：秋思之祖。
王国维《人间词话》：深得唐人绝句妙境。', 'indent', 1423176685, '57afece2a633bd0057fe5fe3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10348, '易水歌', NULL, 236, 1, 1, 1, '荆轲', NULL, 10092, '57b902ac79bc44005b9ead5f', '周', 'shi', '诗', 'http://baike.baidu.com/view/296753.htm', '', '风萧萧兮易水寒，壮士一去兮不复还。', '《易水歌》一作《渡易水歌》，是战国时期荆轲将为燕太子丹去秦国刺杀秦王在易水饯别之际所作的一首楚辞。这首辞前句通过描写秋风萧瑟、易水寒冽，一上一下极天地愁惨之状，渲染了苍凉悲壮的肃杀气氛，渗透出歌者激越澎湃的感情。後句表现主人公大义凛然、义无反顾、抱定必死决心深入虎穴的献身精神。全辞语言简洁、直白，情景交融。', '易水：河流名，在今河北省易县，当时为燕国的南界。
萧萧：秋天的风声。
兮：语气助词。
壮士：在这里指荆轲。', '北风萧萧易水森寒，壮士一去再不回返。　', '[{"bookId": "60fccb5034bfda01e0ea02ff", "bookTitle": "先秦诗鉴赏辞典（新一版）", "articleId": "610f3762c6e67846a92247a5", "shortContent": "这是一位决心舍身抗暴的英勇壮士，在飞车赴秦前夕，发唱于易水河畔的烈烈壮歌。所以对这首歌的鉴赏，与其着眼于它的“艺术”，不如领略它那悲亢的精神。\n秦王政二十年（前227），荆轲受燕太子丹之命出使秦庭，欲以数寸匕首，劫持嬴政（即后来的秦始皇），迫其“悉归诸侯侵地”。终因秦王身负长剑。“断其左股”，而壮心不酬。荆轲虽“身被八创”，犹“倚柱而笑，箕踞以骂”，直至被杀气绝，表现了一位助弱抗暴志士视死如归的气...", "authors": ["潘啸龙"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f38a5902ee364cc8a5e25", "shortContent": "这是一位决心舍身抗暴的英勇壮士，在飞车赴秦前夕，发唱于易水河 畔的烈烈壮歌。所以对这首歌的鉴赏，与其着眼于它的“艺术”，不如领略 它那悲亢的精神。\n\n秦王政二十年(前227)，荆轲受燕太子丹之命出使秦庭，欲以数寸匕 首，劫持嬴政(即后来的秦始皇)，迫其“悉归诸侯侵地”。终因秦王身负长 剑，“断其左股”，而壮心不酬。荆轲虽“身被八创”，犹“倚柱而笑，箕踞以 骂”，直至被杀气绝，表现了一位助弱抗暴志士...", "authors": ["潘啸龙"], "pressName": "上海辞书出版社"}]', '唐士雅：惜哉剑术之疏而奇功遂不成，令千载而下英雄为之短气。朱子谓轲匹夫之勇，其事无足言，特其词悲壮有足关者。
沈归愚：至今读之，犹存变徵之声。
张玉谷：竟说一去不还，壮在此，悲亦在此。全妙在上句写景，助得声势起，故读之愈觉悲壮。
锺退谷：「风萧萧」一语凄苦难读。
胡元瑞：《易水歌》仅十数言，而凄婉激烈，风骨情景，种种具备。亘千载下，复欲二语，不可得。', 'center', 1423176579, '57b902afc4c97100558f3372', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10349, '终南山', NULL, 269, 394, 3, 6, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/40278/5070319.htm', '', '太乙近天都，连山接海隅。
白云回望合，青霭入看无。
分野中峰变，阴晴众壑殊。
欲投人处宿，隔水问樵夫。', '终南山，又名太乙山，西起陕西宝鸡眉县，东至陕西西安蓝田县，千峰叠翠，景色幽美。开元二十九年（西元七四一年）至天宝三年（西元七四四年）之间，王摩诘曾隐居于长安附近的终南山，这首诗大概是诗人隐居终南期间的作品。诗旨在咏叹终南山的宏伟壮大，全诗写景、写人、写物，动如脱兔，静若淑女，有声有色，意境清新、宛若一幅山水画。', '终南山，在长安南五十里，秦岭主峰之一。古人又称秦岭山脉为终南山。秦岭绵延八百馀里，是渭水和汉水的分水岭。
太乙：终南山别名。又名太一，秦岭之一峰。唐人每称终南山一名太一，《元和郡县志》："终南山在县（京兆万年县）南五十里。按经传所说，终南山一名太一，亦名中南"。天都：传说天帝居所。这里指帝都长安。
海隅（yú）：海边。终南山并不到海，此为夸张之词。
青霭（ǎi）：山中的岚气。霭：云气。
分野：以天上星宿配地上州国称分野。古人以天上的二十八个星宿的位置来区分中国境内的地域，被称为分野。地上的每一个区域都对应星空的某一处分野。
壑（hè）：山谷。「分野中峰变，阴晴众壑殊」这两句诗是说终南山连绵延伸，占地极广，中峰两侧的分野都变了，众山谷的天气也阴晴变化，各自不同。
人处：有人烟处。', '髙耸的终南山似乎接近长安，山峦延绵不绝遥遥伸向海滨。
回望山下白云滚滚连成一片，进入山中青青烟雾若有若无。
巍峨终南山能分隔星宿州国，山川里的阴晴也就各不相同。
我想投宿人家在这度过一夜，隔着河川向打柴的樵夫询问。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9296d635634aee3deb2b", "shortContent": "艺术创作，贵在以个别显示一般，以不全求全，刘勰所谓“以少总多”，古代画论家所谓“意馀于象”，都是这个意思。作为诗人兼画家的王维，很懂得此中奥秘，因而能用只有四十个字的一首五言律诗，为偌大一座终南山传神写照。\n首联“太乙近天都，连山接海隅”，先用夸张手法勾画了终南山的总轮廓。这个总轮廓，只能得之于遥眺，而不能得之于逼视。所以，这一联显然是写远景。\n“太乙”是终南山的别称。终南虽高，去天甚遥，说它“近...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc40922", "shortContent": "艺术创作，贵在以个别显示一般，以不全求全，刘勰所谓“以少总多”，古代画论家所谓“意余于象”，都是这个意思。作为诗人兼画家的王维，很懂得此中奥秘，因而能用只有四十个字的一首五言律诗，为偌大一座终南山传神写照。\n\n首联“太乙近天都，连山接海隅”，先用夸张手法勾画了终南山的总轮廓。这个总轮廓，只能得之于遥眺，而不能得之于逼视。所以，这一联显然是写远景。\n\n“太乙”是终南山的别称。终南虽高，去天甚遥，说它...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e020a4", "shortContent": "绵延八百里、高峻广袤的终南山屹立在长安城的南边，巍峨的山峰似乎就在眼前。山与山相连，峰与峰相接，绵绵起伏的山脉一直延伸到了海天相连、旭日高升的东海之涯。我漫步进入山中，那云雾缭绕、变幻莫测的奇妙景象让我犹如置身仙境。朝前看，弥漫的白云让我迷失在云海之中，茫茫的雾气、淡淡的白云缠绕着我，仿佛只要再走几步，就可以浮游于白云的海洋。继续前进，峰回路转，烟云变灭，换步移形，白云继续分向两边，可望而不可即；...", "authors": ["黄蓓"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270447ccdb86c49f2922d", "shortContent": "绵延八百里、高峻广袤的终南山屹立在长安城的南边，巍峨的山峰似乎就在眼前。山与山相连，峰与峰相接，绵绵起伏的山脉一直延伸到了海天相连、旭日高升的东海之涯。我漫步进入山中，那云雾缭绕、变幻莫测的奇妙景象让我犹如置身仙境。朝前看，弥漫的白云让我迷失在云海之中，茫茫的雾气、淡淡的白云缠绕着我，仿佛只要再走几步，就可以浮游于白云的海洋。这茫茫云海、蒙蒙青霭，如此迷幻；然而继续前进，峰回路转，烟云变灭，换步移...", "authors": ["黄蓓"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127078f2af4e09d55b679c", "shortContent": "绵延八百里、高峻广袤的终南山屹立在长安城的南边，巍峨的山峰似乎就在眼前。山与山相连，峰与峰相接，绵绵起伏的山脉一直延伸到了海天相连、旭日高升的东海之涯。我漫步进入山中，那云雾缭绕、变幻莫测的奇妙景象让我犹如置身仙境。朝前看，弥漫的白云让我迷失在云海之中，茫茫的雾气、淡淡的白云缠绕着我，仿佛只要再走几步，就可以浮游于白云的海洋。这茫茫云海、蒙蒙青霭，如此迷幻；然而继续前进，峰回路转，烟云变幻，换步移...", "authors": ["黄蓓"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "64645a427da2f75ac7e649bf", "shortContent": "艺术创作，贵在以个别显示一般，以不全求全，刘勰所谓“以少总多”，古代画论家所谓“意余于象”，都是这个意思。作为诗人兼画家的王维，很懂得此中奥秘，因而能用只有四十个字的一首五言律诗，为偌大一座终南山传神写照。\n\n首联“太乙近天都，连山接海隅”，先用夸张手法勾画了终南山的总轮廓。这个总轮廓，只能得之于遥眺，而不能得之于逼视。所以，这一联显然是写远景。\n\n“太乙”是终南山的别称。终南虽高，去天甚遥，说它...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "6464660fc0471b0062cb7b00", "shortContent": "艺术创作，贵在以个别显示一般，以不全求全，刘勰所谓“以少总多”，古代画论家所谓“意余于象”，都是这个意思。作为诗人兼画家的王维，很懂得此中奥秘，因而能用只有四十个字的一首五言律诗，为偌大一座终南山传神写照。\n\n首联“太乙近天都，连山接海隅”，先用夸张手法勾画了终南山的总轮廓。这个总轮廓，只能得之于遥眺，而不能得之于逼视。所以，这一联显然是写远景。\n\n“太乙”是终南山的别称。终南虽高，去天甚遥，说它...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "647327f5b6a81d0c532fc439", "shortContent": "艺术创作，贵在以个别显示一般，以不全求全。刘勰所谓“以少总多”，古代画论家所谓“意余于象”，都是这个意思。作为诗人兼画家的王维，很懂得此中奥秘，因而能用只有四十个字的一首五言律诗，为偌大一座终南山传神写照。\n首联“太乙近天都，连山接海隅”，先用夸张手法勾画了终南山的总轮廓。这个总轮廓，只能得之于遥眺，而不能得之于逼视。所以，这一联显然是写远景。\n“太乙”是终南山的别称。终南虽高，去天甚遥，说它“近...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '《王孟诗评》：语不必深辟，清夺众妙。
《唐诗直解》：王摩诘「欲投人处宿，隔水问樵夫」，孟浩然「再来迷处所，花下问渔舟」。并可作画。末语流丽。
《唐诗镜》：「阴晴众壑殊」一语苍然入雅。
《唐诗选》：玉遮曰：「入看无」三字妙入神。
《唐诗选脉会通评林》：蒋一梅曰：三四真画出妙境。周敬曰：五六直在鲛宫蜃市之间。周启琦曰：摩诘终南二诗，机熟脉清，手眼俱妙。
《唐风定》：右丞不独幽闲，乃饶奇丽，但一出其口，自然清冷，非世中味耳。
《唐诗评选》：工苦，安排备尽矣。人力参天，与天为一矣。「连山到海隅」非徒为穷大语，读《禹贡》自知之。结语亦以形其阔大，妙在脱卸，勿但作诗中画观也，此正是画中有诗。
《唐律消夏录》：通首俱写终南山之大。全是白云、青霭，一中峰而分野已变，历众壑而阴晴复殊，游将竟日尚无宿处，其大何如？
《增订唐诗摘钞》：结见山远人稀。
《唐诗观澜集》：屈注天潢，倒连沧海。而俯视一气，尽化烟云。一结杳渺寥泬，更有凭虚御风之气。
《而庵说唐诗》：是诗如在开辟之初，笔有鸿蒙之气，奇观大观也。
《唐贤三昧集笺注》：神境。四十字中无一字可易，昔人所谓四十位贤人。
《唐诗别裁》：「近天都」言其髙，「到海隅」言其远，「分野」二句言其大，四十字中无所不包，手笔不在杜陵下。或谓末二句似与通体不配。今玩其语意，见山远而人寡也，非寻常写景可比。
《茧斋诗谈》：于此看「积健为雄」之妙。「白云」两句，看山得三昧，尽此十字中。
《唐诗从绳》：此尾联补题格。中四句分承说，此立柱应法。回望处白云已合，入看时青霭却无，错综成句，此法与倒装异者，以神韵不动也。
《网师园唐诗笺》：得此形容，乃不同寻常登眺（「青霭」句下）。
《唐宋诗举要》：吴曰：壮阔之中而写景复极细腻（「青霭」句下）。吴曰：接笔雄俊（「分野」句下）。', 'center', 1363619035, '57b91377df0eea0063357a5b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10350, '黄鹤楼', NULL, 1563, 46, 4, 16, '崔颢', NULL, 10093, '57b9a826a633bd005d2e2d61', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/1981/11206842.htm', '', '昔人已乘黄鹤去，此地空余黄鹤楼。
黄鹤一去不复返，白云千载空悠悠。
晴川历历汉阳树，芳草萋萋鹦鹉洲。
日暮乡关何处是？烟波江上使人愁。', '《黄鹤楼》是唐代诗人崔颢创作的一首七言律诗，被选入《唐诗三百首》。此诗描写了在黄鹤楼上远眺的美好景色，是一首吊古怀乡之佳作。前四句写登临怀古，後四句写站在黄鹤楼上的所见所思。诗虽不协律，但音节浏亮而不拗口。信手而就，一气呵成，成为历代所推崇的珍品。
这首诗在当时就很有名，传说李白登黄鹤楼，有人请李白题诗，他说：「眼前有景道不得，崔颢题诗在上头。」严羽《沧浪诗话》评：「唐人七言律诗，当以崔颢《黄鹤楼》为第一。」', '黄鹤楼：三国吴黄武二年修建。为古代名楼，旧址在湖北武昌黄鹤矶上，俯见大江，面对大江彼岸的龟山。
昔人已乘黄鹤去：一作“乘白云”。
悠悠：飘荡的样子。
晴川：阳光照耀下的原野。川，平原。
历历：清楚可数。
萋萋：形容草木茂盛。
鹦鹉洲：在湖北省武昌县西南，据《后汉书》载，汉黄祖任江夏太守时，在此大宴宾客，有人献上鹦鹉，故称鹦鹉洲。
乡关：故乡家园。
烟波：暮霭沉沉的江面，一作“烟花”。', '昔日的仙人已乘着黄鹤飞去，这地方只留下空荡的黄鹤楼。
黄鹤一去再也没有返回这里，千万年来只有白云飘飘悠悠。
汉阳晴川的碧树历历可辨，更能看清芳草繁茂的鹦鹉洲。
时至黄昏不知何处是我家乡？看江面烟波渺渺更使人烦愁！', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a3d635634aee3dec32", "shortContent": "元人辛文房《唐才子传》记李白登黄鹤楼本欲赋诗，因见崔颢此作，为之敛手，说：“眼前有景道不得，崔颢题诗在上头。”传说或出于后人附会，未必真有其事。然李白确曾两次作诗拟此诗格调。其《鹦鹉洲》诗前四句说：“鹦鹉东过吴江水，江上洲传鹦鹉名。鹦鹉西飞陇山去，芳洲之树何青青。”与崔诗如出一辙。又有《登金陵凤凰台》诗亦是明显地摹学此诗。为此，说诗者众口交誉，如宋代严羽《沧浪诗话》谓：“唐人七言律诗，当以崔颢《黄...", "authors": ["蔡义江"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d10f", "shortContent": "元人辛文房《唐才子传》记李白登黄鹤楼本欲赋诗，因见崔颢此作，为之敛手，说：“眼前有景道不得，崔颢题诗在上头。”传说或出于后人附会，未必真有其事。然李白确曾两次作诗拟此诗格调。其《鹦鹉洲》诗前四句说：“鹦鹉东过吴江水，江上洲传鹦鹉名。鹦鹉西飞陇山去，芳洲之树何青青。”与崔诗如出一辙。又有《登金陵凤凰台》诗亦是明显地摹学此诗。为此，说诗者众口交誉，如宋代严羽《沧浪诗话》谓：“唐人七言律诗，当以崔颢《黄...", "authors": ["蔡义江"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d19330151f9", "shortContent": "这首诗是崔颢的代表作。据元代辛文房《唐才子传》记载，李白登黄鹤楼本欲题诗，因为见到崔颢的这首题诗，停笔不作，叹曰：“眼前有景道不得，崔颢题诗在上头。”传说或许是后人附会，未必真有其事。然而李白的确曾两次作诗拟此诗格调。其《鹦鹉洲》诗前四句说：“鹦鹉东过吴江水，江上洲传鹦鹉名。鹦鹉西飞陇山去，芳洲之树何青青。”与崔诗如出一辙。又有《登金陵凤凰台》诗也明显摹学此诗。论诗之人对崔颢此诗也是赞誉有加，如严...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127053e6f69b71e93f627b", "shortContent": "这首诗是崔颢的代表作。据元代辛文房《唐才子传》记载，李白登黄鹤楼本欲题诗，因为见到崔颢的这首题诗，停笔不作，叹曰：“眼前有景道不得，崔颢题诗在上头。”传说或许是后人附会，未必真有其事。然而李白的确曾两次作诗拟此诗格调。其《鹦鹉洲》诗前四句说：“鹦鹉东过吴江水，江上洲传鹦鹉名。鹦鹉西飞陇山去，芳洲之树何青青。”与崔诗如出一辙。又有《登金陵凤凰台》诗也明显摹学此诗。论诗之人对崔颢此诗也是赞誉有加，如严...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270a5e6f69b71e93f6333", "shortContent": "这首诗是崔颢的代表作。据元代辛文房《唐才子传》记载，李白登黄鹤楼本欲题诗，因为见到崔颢的这首题诗，停笔不作，叹曰：“眼前有景道不得，崔颢题诗在上头。”传说或许是后人附会，未必真有其事。然而李白的确曾两次作诗拟此诗格调。其《鹦鹉洲》诗前四句说：“鹦鹉东过吴江水，江上洲传鹦鹉名。鹦鹉西飞陇山去，芳洲之树何青青。”与崔诗如出一辙。又有《登金陵凤凰台》诗也明显摹学此诗。论诗之人对崔颢此诗也是赞誉有加，如严...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f5dde49f46528add8ee5", "shortContent": "前人有“文以气为主”之说，此诗前四句看似随口说出，一气旋转，顺势而下，绝无半点滞碍。“黄鹤”二字再三出现，却因其气势奔腾直下，使读者“手挥五弦，目送飞鸿”，急忙读下去，无暇觉察到它的重复出现，而这是律诗格律上之大忌，诗人好像忘记了是在写“前有浮声，后须切响”、字字皆有定声的七律。试看：首联的五、六字同出“黄鹤”；第三句几乎全用仄声；第四句又用“空悠悠”这样的三平调煞尾；亦不顾什么对仗，用的全是古体...", "authors": ["蔡义江"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "64732e0e30675327e1c572b4", "shortContent": "元人辛文房《唐才子传》记李白登黄鹤楼本欲赋诗，因见崔颢此作，为之敛手，说：“眼前有景道不得，崔颢题诗在上头。”传说或出于后人附会，未必真有其事。然李白确曾两次作诗拟此诗格调。其《鹦鹉洲》诗前四句说：“鹦鹉东过吴江水，江上洲传鹦鹉名。鹦鹉西飞陇山去，芳洲之树何青青。”与崔诗如出一辙。又有《登金陵凤凰台》诗亦是明显地摹学此诗。为此，说诗者众口交誉，如严羽《沧浪诗话》谓：“唐人七言律诗，当以崔颢《黄鹤楼...", "authors": ["蔡义江"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "64733e0d902ee364cc9a2867", "shortContent": "元人辛文房《唐才子传》记李白登黄鹤楼本欲赋诗，因见崔颢此作，为之敛手，说：“眼前有景道不得，崔颢题诗在上头。”传说或出于后人附会，未必真有其事。然李白确曾两次作诗拟此诗格调。其《鹦鹉洲》诗前四句说：“鹦鹉东过吴江水，江上洲传鹦鹉名。鹦鹉西飞陇山去，芳洲之树何青青。”与崔诗如出一辙。又有《登金陵凤凰台》诗亦是明显地摹学此诗。为此，说诗者众口交誉，如严羽《沧浪诗话》谓：“唐人七言律诗，当以崔颢《黄鹤楼...", "authors": ["蔡义江"], "pressName": "上海辞书出版社"}]', '《沧浪诗话》：唐人七言律诗，当以崔颢《黄鹤楼》为第一。
《瀛奎律髓》：此诗前四句不拘对偶，气势雄大。李白读之，不敢再题此楼，乃去而赋《登金陵凤凰臺》也。
《唐诗品汇》：刘後村云：古人服善。李白登黄鹤楼有「眼前有景道不得，崔颢题诗在上头」之句，至金陵乃作《凤凰台》以拟之。今观二诗，真敌手棋也。刘须溪云：恨以滔滔莽莽，有疏宕之气，故胜巧思。
《七修类稿》：古人不以饾饤为工，如「鹦鹉洲」对「汉阳树」，「白鹭洲」对「青天外」，超然不为律缚，此气昌而有馀意也。
《艺圃撷馀》：崔郎中作《黄鹤楼》诗，青莲短气，后题《凤凰臺》，古今目为敕敌。识者谓前六句不能当，结语深悲慷慨，差足胜耳。然馀意更有不然，无论中二联不能及，即结语亦大有辨。言诗须道兴比赋，如「日暮乡关」，兴而陚也，「浮云」「蔽日」，比而赋也，以此思之，「使人愁」三字虽同，孰为当乎？「日暮乡关」、「烟波江上」，本无指著，登临者自生愁耳，故曰「使人愁」，烟波使之愁也；「浮云」「蔽日」，「长安不见」，逐客自应愁，宁须使之？青莲才情，标映万载，宁以予言重轻？尺有所短，寸有所长，窃以为此诗不逮，非一端也，如有罪我者则不敢辞。
《诗薮》：崔颢《黄鹤楼》、李白《凤凰臺》，但略点题面，未尝题黄鹤、凤凰也。……故古人之怍，往往神韵超然，绝去斧凿。
《批点唐诗正声》：气格音调，千载独步。
《唐诗广选》：李宾之曰：崔颢此诗乃律间出古，要自不厌。
《唐诗镜》：此诗气格高迥，浑若天成。
《唐诗归》：谭云：此诗妙在宽然有馀，无所不写。使他人以歌行为之，尤觉不舒，宜尔太白起敬也。
《唐诗选脉会通评林》：前四句叙楼名之由，何等流利鲜活？後四句寓感慨之思，何等清迥凄怆？盖黄鹤无返期，白云空在望，睹江树洲草，自不能不触目生愁。赋景摅情，不假斧凿痕，所以成千古脍炙。李梦阳云：一气浑成，净亮奇瑰，太白所以见屈。周敬曰：通篇琉越，煞处悲壮，奇妙天成。
《诗源辨体》：崔《黄鹤》、《雁门》，读之有金石宫商之声，盖晚年作也。
《唐风定》：本歌行体也，作律更入神境。云卿《古意》犹涉锻炼，此最高矣。
《贯华堂选批唐才子诗》：此诗正以浩浩大笔，连写三「黄鹤」字为奇耳。……四之忽陪「白云」，正妙于有意无意，有谓无谓。通解细寻，他何曾是作诗，直是直上直下放眼恣看，看见道理却是如此，于是立起身，提笔濡墨，前向楼头白粉壁上，恣意大书一行。既已书毕，亦便自看，并不解其好之与否。单衹觉得修已不须修，补已不须补，添已不可添，减已不可减，于是满心满意，即便留却去休回，实不料後来有人看见，已更不能跳出其笼罩也。且後人之不能跳出，亦衹是修补添减俱用不着，于是便复袖手而去，非谓其有字法、句法、章法，都被占尽，遂更不能争夺也。此解（按：指後四句）又妙于更不牵连上文，只一意凭高望远，别吐自家怀抱，任凭後来读者自作如何会通，真为大家规摹也。五六只是翻跌「乡关何处是」五字，言此处历历是树，此处凄凄是洲，独有目断乡关，却是不知何处。他只于句上横安得「日暮」二字，便令前解四句二十八字，字字一齐摇动入来，此为绝奇之笔也。
《唐诗评选》：鹏飞象行，惊人以远大。竟从怀古起，是题楼诗，非登楼。一结自不如《凤凰台》，以意多碍气也。
《春酒堂诗话》：评赞者无过随太白为虚声耳。独喜谭友夏「宽然有余」四字，不特尽崔诗之境，且可推之以悟诗道。非学问博大，性情深厚，则蓄缩羞赧，如牧竖咶席见诸将矣。
《删订唐诗解》：不古不律，亦古亦律，千秋绝唱，何独李唐？
《唐诗归折衷》：吴敬夫云：吊古伤今，意到笔到之作。
《唐七律选》：此律法之最变者，然系意兴所至、信笔抒写而得之，如神驹出水，任其跋踔，无行步工拙，裁摩拟便恶劣矣。前人品此为唐律第一，或未必然，然安可有二也。
《增订唐诗摘钞》：前半一气直走，竟不作对，律之变体。五六「州」一类，「草」「树」一类，上下互换成对（犄角对）。前半即吊古之意，凭空而下。「晴川历历」、「芳草萋萋」，即从「白云」「悠悠」生出。结从「汉阳树」、「鹦鹉洲」生出「乡关」，见作者身分；点破「江上」，指明其地；又以「烟波」唤起「愁」字，以「愁」字绾上前半。前半四句笔矫，中二句气和，结又健举，横插「烟波」二字点睛。雄浑傲岸，全以气胜，直如《国策》文字，而其法又极细密。
《碛砂唐诗》：今细求之，一气浑成，律中带古，自不必言。即「晴川」二句，清迥绝伦，他再有作，皆不过眼前景矣。而且痕迹俱消，所以独步千古乎？
《初白庵诗评》：此诗为後来七律之袓，取其气局开展。
《唐三体诗评》：此篇体势可与老杜《登岳阳楼》匹敌。
《唐诗成法》：格律脱洒，律调叶和，以青莲仙才即时阁笔，已高绝千古。《凤凰台》诸作屡拟此篇，邯郸学步，并故步失之矣。《鹦鹉洲》前半神似，後半又谬以千里者，律调不叶也。在崔实本之《龙池篇》，而沈之字句虽本范云，调则自制，崔一拍便合，当是才性所近。盖此为平商流利之调，而谪仙乃宫音也。
《近体秋阳》：灏高排空，怆浑绝世，此与太白《凤凰台》篇当同冠七言。顾太白不拘粘，唯心师之，不敢辄以程后学，不得不独推此作尔。
《而庵说唐诗》：字字针锋相凑，如此作转。方是名手。
《历代诗法》：此如十九首《古诗》，乃太空元气，忽然逗入笔下，作者初不自知，观者叹为绝作，亦相赏于意言上拙之外耳。
《唐贤三昧集笺注》：此诗得一叠字诀，全从《三百篇》化出。
《唐诗别裁》：意得象先，神行语外，纵笔写去，遂擅千古之奇。
《山满楼笺注唐诗七言律》：妙在一曰黄鹤，再曰黄鹤，三曰黄鹤，令读者不嫌其复，不觉其烦，不讶其何谓。尤妙在一曰黄鹤，再曰黄鹤，三曰黄鹤，而忽然接以白云，令读者不嫌其突，不觉其生，不讶其无端。此何故耶？由其气足以充之，神足以运之而已矣。若论作法，则崔之妙在凌驾，李之妙在安顿，岂相碍乎？
《昭昧詹言》：崔颢《黄鹤楼》，此千古擅名之作，只是以文笔行之，一气转折。五六虽断写景，而气亦直下喷溢。收亦然。所以可贵。此体不可再学，学则无味，亦不奇矣。细细校之，不如「卢家少妇」有法度，可以为法千古也。
《瀛奎律髓汇评》：冯舒：何有声病，即是律诗，且不拘平仄，何况对偶？冯班：真奇。上半有千里之势。起四句宕开，有万钧之势，纪昀：偶尔得之，自成绝调。然不可无一，不可有二。再一临摹，便成窠臼。许印芳：此篇乃变体律诗，前半是古诗体、以古笔为律诗。无名氏（乙）：前六句神兴溢涌，结二语蕴含无穷，千秋第一绝唱。赵熙：此诗万难嗣响，其妙则殷璠所谓「神来，气来，情来」者也。
《唐七律隽》：毛秋晴云：张南士谓人不识他诗不碍，惟崔司勋《黄鹤楼》、沈詹事《古意》，若心不能记、口不能诵，便为不识字白丁矣。
《唐诗选胜直解》：此体全是赋体，前四句因登楼而生感。
《湘绮楼说诗》：起有飘然之致，观太白《凤凰台》、《鹦鹉洲》诗学此，方知工拙。
《唐宋诗举要》：吴曰：渺茫无际，高唱入云，太白尚心折，何况余子？', 'center', 1415638429, '57b8f0915bbb50005b77bd38', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10351, '登鹳雀楼', NULL, 3733, 6, 2, 15, '王之涣', NULL, 10094, '57ba7d9379bc440063a17bda', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/122176/5247405.htm', '', '白日依山尽，黄河入海流。
欲穷千里目，更上一层楼。', '《登鹳雀楼》是盛唐诗人王之涣的一首五言绝句，前两句写的是自然景色，但开笔就有缩万里于咫尺，使咫尺有万里之势；后两句写意，写的出人意料，把哲理与景物、情势溶化得天衣无缝，成为鹳雀楼上一首不朽的绝唱。此诗虽然只有二十字，却以千钧巨椽，绘下北国河山的磅礴气势和壮丽景象，令人襟怀豪放。诗人受大自然震撼的心灵，悟出的是朴素而深刻的哲理，能够催人抛弃固步自封的浅见陋识，登高放眼，不断拓出愈益美好的崭新境界。清代诗评家也认为：「王诗短短二十字，前十字大意已尽，后十字有尺幅千里之势。」这首诗是唐代五言诗的压卷之作，王之涣因这首五言绝句而名垂千古，鹳雀楼也因此诗而名扬中华。', '鹳雀楼：古名鹳鹊楼，因时有鹳鹊栖其上而得名，其故址在永济市境内古蒲州城外西南的黄河岸边。《蒲州府志》记载：「（鹳雀楼）旧在郡城西南黄河中高阜处，时有鹳雀栖其上，遂名。」
白日：太阳。
依：依傍。
尽：消失。 这句话是说太阳依傍山峦沉落。
欲：想要得到某种东西或达到某种目的的愿望，但也有希望、想要的意思。
穷：尽，使达到极点。
千里目：眼界宽阔。
更：再。', '夕阳依傍着西山慢慢地沉没，滔滔黄河朝着东海汹涌奔流。
若想把千里的风光景物看够， 那就要登上更高的一层城楼。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929003572034f659e284", "shortContent": "鹳雀楼，又名鹳鹊楼，据《清一统志》记载，楼的旧址在山西蒲州（今永济县，唐时为河中府）西南，黄河中高阜处，时有鹳雀栖其上，遂名。宋沈括在《梦溪笔谈》中记述：“河中府鹳雀楼三层，前瞻中条，下瞰大河。唐人留诗者甚多。”王之涣的这首五绝是“唐人留诗”中的不朽之作。\n诗的前两句“白日依山尽，黄河入海流”，写的是登楼望见的景色，写得景象壮阔，气势雄浑。这里，诗人运用极其朴素、极其浅显的语言，既高度形象又高度概...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0f1", "shortContent": "鹳雀楼，又名鹳鹊楼，据《清一统志》记载，楼的旧址在山西蒲州（今永济市，唐时为河中府）西南，黄河中高阜处，时有鹳雀栖其上，遂名。宋沈括在《梦溪笔谈》中记述：“河中府鹳雀楼三层，前瞻中条，下瞰大河。唐人留诗者甚多。”王之涣的这首五绝是“唐人留诗”中的不朽之作。\n\n诗的前两句“白日依山尽，黄河入海流”，写的是登楼望见的景色，写得景象壮阔，气势雄浑。这里，诗人运用极其朴素、极其浅显的语言，既高度形象又高度...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e90394", "shortContent": "鹳雀楼，据沈括《梦溪笔谈》：“河中府鹳雀楼，三层，前瞻中条，下瞰大河，唐人留诗者甚多。”其楼在今山西永济西南黄河岸边，因时有鹳雀栖于其上，故名。在这“留诗者甚多”的人中，只有李益、王之涣和畅当三人的诗最为有名，而尤以王之涣的诗歌为佳。\n \n前两句气势雄阔。一轮落日在眼前连绵不断的群山间渐渐西沉，黄河在远处猛然转折，向东朝着大海奔腾而去。此处写白日与黄河的壮阔，同时也正是写鹳雀楼地势之险峻。十个字气...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127036c9ebcc6fbea1a388", "shortContent": "鹳雀楼，据沈括《梦溪笔谈》：“河中府鹳雀楼，三层，前瞻中条，下瞰大河，唐人留诗者甚多。”其楼在今山西永济西南黄河岸边，因时有鹳雀栖于其上，故名。在这“留诗者甚多”的人中，只有李益、王之涣和畅当三人的诗最为有名，而尤以王之涣的诗歌为佳。\n\n前两句气势雄阔。一轮落日在眼前连绵不断的群山间渐渐西沉，黄河在远处猛然转折，向东朝着大海奔腾而去。此处写白日与黄河的壮阔，同时也正是写鹳雀楼地势之险峻。十个字气势...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127069c305cf0801816fc3", "shortContent": "鹳雀楼，据沈括《梦溪笔谈》：“河中府鹳雀楼，三层，前瞻中条，下瞰大河，唐人留诗者甚多。”其楼在今山西永济西南黄河岸边，因时有鹳雀栖于其上，故名。在这“留诗者甚多”的人中，只有李益、王之涣和畅诸三人的诗最为有名，而尤以王之涣的诗歌为佳。\n前两句气势雄阔。一轮落日在眼前连绵不断的群山间渐渐西沉，黄河在远处猛然转折，向东朝着大海奔腾而去。此处写白日与黄河的壮阔，同时也正是写鹳雀楼地势之险峻。十个字气势浑...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f09ff5fc8182fe9ca1dac", "shortContent": "首句写遥望一轮落日向着楼前一望无际、连绵起伏的群山西沉，在视野的尽头冉冉而没。这是天空景、远方景、西望景。次句写目送流经楼前下方的黄河奔腾咆哮、滚滚南来，又在远处折而东向，流归大海。这是由地面望到天边，由近望到远，由西望到东。这两句诗合起来，就把上下、远近、东西的景物，全都容纳进诗笔之下，使画面显得特别宽广，特别辽远。就次句诗而言，诗人身在鹳雀楼上，不可能望见黄河入海，句中写的是诗人目送黄河远去天...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "6473275b30675327e1c55560", "shortContent": "鹳雀楼，又名鹳鹊楼。据《清一统志》记载，楼的旧址在山西蒲州（今永济县，唐时为河中府）西南，黄河中高阜处，时有鹳雀栖其上，遂名。沈括在《梦溪笔谈》中记述：“河中府鹳雀楼三层，前瞻中条，下瞰大河。唐人留诗者甚多。”王之涣的这首五绝是“唐人留诗”中的不朽之作。\n诗的前两句“白日依山尽，黄河入海流”，写的是登楼望见的景色，写得景象壮阔，气势雄浑。这里，诗人运用极其朴素、极其浅显的语言，既高度形象又高度概括...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}]', '《古今诗话》：河中府鹳雀楼，唐人留诗者极多，唯王之涣、李益、畅当诗最佳。
《唐诗解》：日没河流之景，未足称奇，穷目之观，更在高处。
《唐诗选》：玉遮曰：不明说「高」字，已自极高。
《唐诗训解》：结语天成，非可意撰。
《唐诗选脉会通评林》：周敬曰：大豁眼界。
《唐诗摘钞》：空阔中无所不有，故雄浑而不疏寂。
《诗境浅说续编》：前一句写山河胜概，雄伟阔远，兼而有之，已如题之量；后二句复馀劲穿札。二十字中，有尺幅千里之势。
沈括《梦溪笔谈》：「河中府鹳雀楼三层，前瞻中条，下瞰大河。唐人留诗者甚多，惟李益、王之涣、畅当三首能壮其观」。这三首中，李益的诗是一首七律；王之涣、畅当的诗则是五绝，均题作《登鹳雀楼》。其中以王之涣的《登鹳雀楼》最为脍炙人口，畅当的诗境也很壮阔，不失为一首名作，但有王之涣的这首诗在前，比较之下，畅当之诗终输一筹，没有王诗有韵律、有激情，不得不让王诗独步千古。', 'center', 1363619469, '57adf967a341310060ebf751', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10352, '凉州词二首 · 其一', NULL, 1798, 6, 2, 10, '王之涣', NULL, 10094, '57ba7d9379bc440063a17bda', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/155229/8984684.htm', '', '黄河远上白云间，一片孤城万仞山。
羌笛何须怨杨柳，春风不度玉门关。', '此诗是唐代诗人王之涣《凉州词二首》中的第一首，以一种特殊的视角描绘了黄河远眺的特殊感受，同时也展示了边塞地区壮阔、荒凉的景色，悲壮苍凉，流露出一股慷慨之气，边塞的酷寒正体现了戍守边防的征人回不了故乡的哀怨，这种哀怨不消沉，而是壮烈广阔。', '凉州词：又名《出塞》。为当时流行的一首曲子《凉州》配的唱词。郭茂倩《乐府诗集·卷七十九·近代曲词》载有《凉州歌》，并引《乐苑》云：「《凉州》，宫调曲，开元中西凉府都督郭知运进。」凉州，属唐陇右道，治所在姑臧县（今甘肃省武威市凉州区）。
黄河远上：远望黄河的源头。河：一作「沙」；远上：远远向西望去；远：一作「直」。
孤城：指孤零零的戍边的城堡。
仞：古代的长度单位，一仞相当于七尺或八尺（约等于213厘米或264厘米）。
羌笛：古羌族主要分布在甘、青、川一带。羌笛是羌族乐器，属横吹式管乐。
何须：何必。
杨柳：《折杨柳》曲。古诗文中常以杨柳喻送别情事。《诗经·小雅·采薇》：「昔我往矣，杨柳依依。」北朝乐府《鼓角横吹曲》有《折杨柳枝》，歌词曰：「上马不捉鞭，反拗杨柳枝。下马吹横笛，愁杀行客儿。」
度：吹到过。
玉门关：汉武帝置，因西域输入玉石取道于此而得名。故址在今甘肃敦煌西北小方盘城，是古代通往西域的要道。六朝时关址东移至今安西双塔堡附近。', '纵目望去，黄河渐行渐远，好像奔流在缭绕的白云中间，就在黄河上游的万仞高山之中，一座孤城玉门关耸峙在那里，显得孤峭冷寂。何必用羌笛吹起那哀怨的杨柳曲去埋怨春光迟迟不来呢，原来玉门关一带春风是吹不到的啊！', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92900f8fda55650553c5", "shortContent": "据唐人薛用弱《集异记》记载：开元间，王之涣与高適、王昌龄到酒店饮酒，遇梨园伶人唱曲宴乐，三人便私下约定以伶人演唱各人所作诗篇的情形定诗名高下。结果三人的诗都被唱到了，而诸伶中最美的一位女子所唱则为“黄河远上白云间”。王之涣甚为得意，这就是著名的“旗亭画壁”故事。此事未必实有。但表明王之涣这首《凉州词》在当时已成为广为传唱的名篇。\n诗的首句抓住自下（游）向上（游）、由近及远眺望黄河的特殊感受，描绘出...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0f2", "shortContent": "据唐人薛用弱《集异记》记载：开元间，王之涣与高适、王昌龄到酒店饮酒，遇梨园伶人唱曲宴乐，三人便私下约定以伶人演唱各人所作诗篇的情形定诗名高下。结果三人的诗都被唱到了，而诸伶中最美的一位女子所唱则为“黄河远上白云间”。王之涣甚为得意，这就是著名的“旗亭画壁”故事。此事未必实有。但表明王之涣这首《凉州词》在当时已成为广为传唱的名篇。\n\n诗的首句抓住自下（游）向上（游）、由近及远眺望黄河的特殊感受，描绘...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4e7ccdb86c49f29107", "shortContent": "《凉州词》亦名《出塞》，是王之涣的名作。\n\n“黄河远上白云间”，这是大漠中特有的景象。唐时凉州在今甘肃武威境内，并无黄河流过。然而唐人诗歌中的凉州多泛指西北，故可将黄河入凉州词中。远远望去，黄河北流，流向天边，与远处地平线上的白云似乎相接，这是在辽阔空旷的大漠中远眺时的视觉错觉，给人一种身临其地的感觉。\n\n“一片孤城万仞山”，那黄河绕经的一片孤城，坐落在万仞高的群山中，显得分外险峻而孤零。此处的孤...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127036c9ebcc6fbea1a389", "shortContent": "《凉州词》是王之涣的名作。\n\n“黄河远上白云间”，这是大漠中特有的景象。唐时凉州在今甘肃武威境内，并无黄河流过。然而唐人诗歌中的凉州多泛指西北，黄河流经兰州，亦可入凉州词中。远远望去，黄河北流，流向天边，与远处地平线上的白云似乎相接，这是在辽阔空旷的大漠中远眺时的视觉错觉，给人一种身临其地的感觉。\n\n“一片孤城万仞山”，那黄河绕经的一片孤城，坐落在万仞高的群山中，显得分外险峻而孤零。此处的孤城和山...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127069c305cf0801816fc9", "shortContent": "《凉州词》是王之涣的名作。\n“黄河远上白云间”，这是大漠中特有的景象。唐时凉州在今甘肃武威境内，并无黄河流过。然而唐人诗歌中的凉州多泛指西北，黄河流经兰州，亦可入凉州词中。远远望去，黄河北流，流向天边，与远处地平线上的白云似乎相接，这是在辽阔空旷的大漠中远眺时的视觉错觉，给人一种身临其地的感觉。\n“一片孤城万仞山”，那黄河绕经的一片孤城，坐落在万仞高的群山中，显得分外险峻而孤零。此处的孤城和山到底...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文208篇（小学、初中）", "articleId": "646f09ff5fc8182fe9ca1dac", "shortContent": "首句写遥望一轮落日向着楼前一望无际、连绵起伏的群山西沉，在视野的尽头冉冉而没。这是天空景、远方景、西望景。次句写目送流经楼前下方的黄河奔腾咆哮、滚滚南来，又在远处折而东向，流归大海。这是由地面望到天边，由近望到远，由西望到东。这两句诗合起来，就把上下、远近、东西的景物，全都容纳进诗笔之下，使画面显得特别宽广，特别辽远。就次句诗而言，诗人身在鹳雀楼上，不可能望见黄河入海，句中写的是诗人目送黄河远去天...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f0a355fc8182fe9ca1fa6", "shortContent": "诗起于写山川的雄阔苍凉，承以戍守者处境的孤危。第三句忽而一转，引入羌笛之声。羌笛所奏乃《折杨柳》曲调，这就不能不勾起征夫的离愁了。折柳赠别的风习在唐时最盛。“杨柳”与离别有更直接的关系。所以，人们不但见了杨柳会引起别愁，连听到《折杨柳》的笛曲也会触动离恨。而“羌笛”句不说“闻折柳”却说“怨杨柳”，造语尤妙。这就避免直接用曲调名，化板为活，且能引发更多的联想，深化诗意。玉门关外，春风不度，杨柳不青，...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '', 'center', 1413389055, '57b911ed8ac2470062e01ff3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (48420, '念奴娇', NULL, 1, 656, 0, 1, '陆文圭', NULL, 11145, '5858e62eb123db00658d7b64', '元', 'ci', '词', NULL, NULL, '延年有术，飧古松根下，茯苓千岁。纵是延年如何益，命也道之将废。思古之人，词章节行，杲杲行当世。遗风流韵，渊然尚有余味。
无奈先哲凋零，后生坦率，多以儒为戏。每笑唐人书不读，直把黄金买贵。山泽奇才，云林真隐，没齿何曾遇。人生如梦，江流日夜东去。', NULL, NULL, NULL, NULL, NULL, 'indent', 1512670648, '585ceda3b123db0065a62fc4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10353, '望月怀远', NULL, 1814, 216, 3, 8, '张九龄', NULL, 10095, '57b90ef17db2a200542711c0', '唐', 'shi', '诗', 'http://baike.baidu.com/view/154993.htm', '', '海上生明月，天涯共此时。
情人怨遥夜，竟夕起相思。
灭烛怜光满，披衣觉露滋。
不堪盈手赠，还寝梦佳期。', '此诗是望月怀思的名篇。开头紧扣题目，首句写「望月」，次句写「怀远」；接着直抒对远方亲人的思念之情；五、六句承接三、四句，具体描绘了彻夜难眠的情境；结尾两句进一步抒写了对远方亲人的一片深情。全诗语言自然浑成而不露痕迹，情意缠绵而不见感伤，意境幽静秀丽，构思巧妙，情景交融，细腻入微，感人至深。', '怀远：怀念远方的亲人。
「海上生明月，天涯共此时」句：辽阔无边的大海上升起一轮明月，使人想起了远在天涯海角的亲友，此时此刻也该是望着同一轮明月。谢庄《月赋》：「隔千里兮共明月」。
情人：多情的人，指作者自己；一说指亲人。
怨遥夜：因离别而幽怨失眠，以至抱怨夜长。遥夜，长夜。
竟夕：终夜，通宵，即一整夜。《后汉书·第五伦传》：「吾子有疾，虽不省视而竟夕不眠。若是者，岂可谓无私乎？」
怜光满：爱惜满屋的月光。滋，湿润。
怜：爱。
盈手：双手捧满之意。盈：满（指那种满荡荡的充盈的状态）。
「不堪盈手赠，还寝梦佳期」二句：月华虽好但是不能相赠，不如回入梦乡觅取佳期。陆机《拟明月何皎皎》：「照之有馀辉，揽之不盈手。」', '海上面升起了一轮明月，你我天各一方共赏月亮。
有情人怨恨漫漫的长夜，彻夜不眠将你苦苦思念。
灭烛灯月光满屋令人爱，披衣起露水沾挂湿衣衫。
不能手捧美丽银光赠你，不如快入梦与你共欢聚。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92905e272d4b22543168", "shortContent": "这是一首月夜怀念远人的诗。起句“海上生明月”意境雄浑阔大，是千古佳句。它和南朝宋谢灵运的“池塘生春草”（《登池上楼》）、“明月照积雪”（《岁暮》），南朝齐谢朓的“大江流日夜”（《暂使下都夜发新林》）以及作者自己的“孤鸿海上来”等名句一样，看起来平淡无奇，没有一个奇特的字眼，没有一分点染的色彩，脱口而出，却自然具有一种高华浑融的气象。这一句完全是景，点明题中的“望月”。第二句“天涯共此时”，即由景入...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0f0", "shortContent": "这是一首月夜怀念远人的诗。起句“海上生明月”意境雄浑阔大，是千古佳句。它和南朝宋谢灵运的“池塘生春草”（《登池上楼》）、“明月照积雪”（《岁暮》），南朝齐谢朓的“大江流日夜”（《暂使下都夜发新林》）以及作者自己的“孤鸿海上来”等名句一样，看起来平淡无奇，没有一个奇特的字眼，没有一分点染的色彩，脱口而出，却自然具有一种高华浑融的气象。这一句完全是景，点明题中的“望月”。第二句“天涯共此时”，即由景入...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151bd", "shortContent": "“举头望明月，低头思故乡”（李白《静夜思》），望月而思乡、念远，正是古往今来文人墨客的共同情思。张九龄这首《望月怀远》也是个中名篇。\n\n首联“海上生明月，天涯共此时”为千古佳句，“海上生明月”写明月升起，回应“望月”诗题。起句看似平淡，毫无点染，如脱口而出，却展现了一幅深邃、宏阔景象。用“生”而非“升”，仿佛明月自海中缓缓吐露，写出大海包孕之态。下句的“共”字把天各一方的思绪联系在一起，于是自然而...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270317f0b9738b369b1a6", "shortContent": "“举头望明月，低头思故乡”（李白《静夜思》），望月而思乡、念远，正是古往今来文人墨客的共同情思。张九龄这首《望月怀远》也是个中名篇。\n\n首联“海上生明月，天涯共此时”为千古佳句，“海上生明月”写明月升起，回应“望月”诗题。起句看似平淡，毫无点染，如脱口而出，却展现了一幅深邃、宏阔景象。用“生”而非“升”，仿佛明月自海中缓缓吐露，写出大海包孕之态。下句的“共”字把天各一方的思绪联系在一起，于是自然引...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270547ccdb86c49f29248", "shortContent": "“举头望明月，低头思故乡”（唐·李白《静夜思》），望月而思乡、念远，正是古往今来文人墨客的共同情思。张九龄这首《望月怀远》也是个中名篇。\n首联“海上生明月，天涯共此时”为千古佳句。“海上生明月”写明月升起，回应“望月”诗题。起句看似平淡，毫无点染，如脱口而出，却展现了一幅深邃、宏阔景象。用“生”而非“升”，仿佛明月自海中缓缓吐露，写出大海包孕之态。下句的“共”字把天各一方的思绪联系在一起，于是自然...", "authors": ["冯丽霞"], "pressName": "崇文书局"}]', '郭云《增订评注唐诗正声》：清浑不著，又不佻薄，较杜审言《望月》更有馀味。
《唐诗镜》：起结圆满，五、六语有姿态，八为踯躅彷徨。
钟云《唐诗归》：虚者难于厚，此及上作（按指《初发曲江溪中》）得之，浑是一片元气，莫作清松看。
《唐诗选脉会通评林》：通篇全以骨力胜，即「灭烛」、「光满」四字，正尽月之神。用一「怜」字，便含下结意，可思不可言。
《唐诗成法》：「共」字逗起情人，「怨」字逗起相思。五、六亦是人月合写，而「怜」、「觉」「滋」、「满」大有痕迹。七、八仍是说月，说相思，不能超脱，不过挨次说出而已，较射洪、必简去天渊矣。
《唐诗笺注》：首二句领得妙。「情人」一联，先就远人怀念言之，少陵「今夜鄜州月」诗同此笔墨。
陈德公《闻鹤轩唐诗读本》：五、六生悽，极是作意。结意尤为婉曲。三、四一意递下，又复紧承起二情绪。落句更与三、四相映。
《五七言今体诗钞》：是五律中《离骚》。', 'center', 1363619716, '57aca120a341310060e2a09f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10354, '赋得自君之出矣', NULL, 180, 216, 1, 0, '张九龄', NULL, 10095, '57b90ef17db2a200542711c0', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383857.htm', '', '自君之出矣，不复理残机。
思君如满月，夜夜减清辉。', '这首诗描写了丈夫远行的妻子在家中的孤单和对丈夫的思念之情。首句“自君之出矣”，即拈用成句。良人离家远行而未归，表明了一个时间概念。良人离家有多久，诗中没有说，只写了“不复理残机”一句，发人深思：首先，织机残破，久不修理，表明良人离家已很久，女主人长时间没有上机织布了；其次，如果说，人去楼空给人以空虚寂寥的感受。那么，君出机残也同样使人感到景象残旧衰飒，气氛落寞冷清；再次，机上布织来织去，始终未完成，它仿佛在诉说，女主人心神不定，无心织布，内心极其不平静。
以上，是对事情起因的概括介绍，接着，诗人便用比兴手法描绘她心灵深处的活动：“思君如满月，夜夜减清辉。”古诗十九首中，以“相去日已远，衣带日已缓”（《行行重行行》）直接描摹思妇的消瘦形象，写得相当具体突出，而在这里，诗人用皎皎明月象征思妇情操的纯洁无邪，忠贞专一。“夜夜减清辉”，写得既含蓄婉转，又真挚动人。比喻美妙贴切，想象新颖独特，使整首诗显得清新可爱，充满浓郁的生活气息。', '赋得：凡摘取古人成句为题之诗，题首多冠以“赋得”二字。“自君之出矣”是乐府诗杂曲歌辞名。
君之出矣：夫君离家。之，助词，无实际意义。矣，了。
不复：不再。理残机：理会残破的织布机。
思：思念。满月：农历每月十五夜的月亮。
减：减弱，消减。清辉：指皎洁的月光。', '自从你离开家乡远行，我再不去动破旧织机。
想念你犹如天边圆月，一夜一夜减弱了光辉。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9290911759740c9b19ee", "shortContent": "《自君之出矣》是乐府诗杂曲歌辞名。赋得是一种诗体。张九龄摘取古人成句作为诗题，故题首冠以“赋得”二字。\n首句“自君之出矣”，即拈用成句。良人离家远行而未归，表明了一个时间概念。良人离家有多久呢？诗中没有说，只写了“不复理残机”一句，发人深思：首先，织机残破，久不修理，表明良人离家已很久，女主人长时间没有上机织布了；其次，如果说，人去楼空给人以空虚寂寥的感受，那么，君出机残也同样使人感到景象残旧衰飒...", "authors": ["何国治"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270317f0b9738b369b1a8", "shortContent": "《自君之出矣》是乐府旧题，诗题来自建安诗人徐干著名的《室思》诗，该诗以女子的口吻，诉说对远方丈夫的深情思念。其第三章云：“自君之出矣，明镜暗不治。思君如流水，何有穷已时。”设喻妥帖，生动展现缠绵相思之情，深受后人赞赏。\n\n南朝以来，不断有人模拟这四句的形式，抒写思妇的哀怨，《自君之出矣》遂成为独立的乐府诗题。\n\n与其他拟乐府诗不同，后世的《自君之出矣》基本上都保持着徐干原诗的内容与形式，即写思妇闺...", "authors": ["冯丽霞"], "pressName": "崇文书局"}]', '《唐诗归》：钟云：此题古今作者，毕竟此首第一。
《诗筏》：“满”字、“减”字纤而无痕，殊近乐府。
《诗法易简录》：题本六朝，而特出巧思，亦得《子夜》诸曲之妙，若直言稍减容光，便平直少味，借满月以写之，新颖绝伦，其思路之巧，全在一“满”字。', 'center', 1423176746, '57b97bdf79bc440060286a99', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10355, '春夜喜雨', NULL, 2322, 1416, 2, 13, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/95044.htm', '', '好雨知时节，当春乃发生。
随风潜入夜，润物细无声。
野径云俱黑，江船火独明。
晓看红湿处，花重锦官城。', '《春夜喜雨》是唐诗名篇之一，是杜甫上元二年（公元761年）在成都草堂居住时所作。此诗运用拟人手法，以极大的喜悦之情细致地描绘了春雨的特点和成都夜雨的景象，热情地讴歌了来得及时、滋润万物的春雨。诗中对春雨的描写，体物精微，细腻生动，绘声绘形。全诗意境淡雅，意蕴清幽，诗境与画境浑然一体，是一首传神入化、别具风韵的咏雨诗。', '知：明白，知道。说雨知时节，是一种拟人化的写法。
乃：就。
发生：萌发生长。
潜（qián）：暗暗地，悄悄地。这里指春雨在夜里悄悄地随风而至。
润物：使植物受到雨水的滋养。
野径：田野间的小路。
“野径云俱黑，江船火独明。”句：意谓满天黑云，连小路、江面、江上的船只都看不见，只能看见江船上的点点灯火，暗示雨意正浓。
晓：天刚亮的时候。
红湿处：雨水湿润的花丛。
花重（zhòng）：花因为饱含雨水而显得沉重。
锦官城：故址在今成都市南，亦称锦城。三国蜀汉时管理织锦之官驻此，故名。后人有用作成都的别称。此句是说露水盈花的美景。', '好雨似乎会挑选时辰，降临在万物萌生之春。
伴随和风，悄悄进入夜幕。细细密密，滋润大地万物。
浓浓乌云，笼罩田野小路；点点灯火，闪烁江上渔船。
明早再看带露的鲜花，成都满城必将繁花盛开。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ac7d0ac114549537e6", "shortContent": "这是描绘春夜雨景，表现喜悦心情的名作。\n一开头就用一个“好”字赞美“雨”。在生活里，“好”常常被用来赞美那些做好事的人。如今用“好”赞美雨，已经会唤起关于做好事的人的联想。接下去，就把雨拟人化，说它“知时节”，懂得满足客观需要。不是吗？春天是万物萌芽生长的季节，正需要下雨，雨就下起来了。你看它多么“好”！\n第二联，进一步表现雨的“好”。雨之所以“好”，就好在适时，好在“润物”。春天的雨，一般是伴随...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a7b", "shortContent": "这是描绘春夜雨景，表现喜悦心情的名作。\n\n一开头就用一个“好”字赞美“雨”。在生活里，“好”常常被用来赞美那些做好事的人。如今用“好”赞美雨，已经会唤起关于做好事的人的联想。接下去，就把雨拟人化，说它“知时节”，懂得满足客观需要。不是吗？春天是万物萌芽生长的季节，正需要下雨，雨就下起来了。你看它多么“好”！\n\n第二联，进一步表现雨的“好”。雨之所以“好”，就好在适时，好在“润物”。春天的雨，一般是...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270617f0b9738b369b1fc", "shortContent": "这首小诗，玲珑剔透，写雨切春、切夜、切喜，读之神清气爽，若要借助诗中一字来表达感受，则曰“好”！\n\n“好雨知时节”，雨乃“好”雨。或许有人会说，用这么平常的一个字眼，也太平淡了，太缺乏诗味了！实则不然！“好”字淡得有如婴儿的啼哭，是一种返朴归真的原始味道。每个人牙牙学语之时，会说的第一个形容词也许就是“好”呢！当我们第一次看到烟波浩渺的大海时，脱口而出的也许就是“好多水啊”；当一座耸入云霄的大山横...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270d4c26cbf3417f09503", "shortContent": "这首小诗，玲珑剔透，写雨切春、切夜、切喜，读之神凊气爽，若要借寺中一字来表达感受，则曰“好”！\n\n“好雨知时节”，雨乃“好”雨。或许有人会说，用这么平常的一个字眼，也太平淡了，太缺乏诗味了！实则不然！“好”字淡得有如婴儿的啼哭，是一种返朴归真的原始味道。每个人牙牙学语之时，会说的第一个形容词也许就是“好”呢！当我们第一次面临烟波浩渺的大海时，脱口而出的也许就是“好多水啊”，当一座耸入云霄的大山横亘...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6465e96a7da2f75ac7ed17bd", "shortContent": "这是描绘春夜雨景，表现喜悦心情的名作。一开头就用一个“好”字赞美“雨”。在生活里，“好”常常被用来赞美那些做好事的人。如今用“好”赞美雨，已经会唤起关于做好事的人的联想。接下去，就把雨拟人化，说它“知时节”，懂得满足客观需要。不是吗？春天是万物萌芽生长的季节，正需要下雨，雨就下起来了。你看它多么“好”！\n\n第二联，进一步表现雨的“好”。雨之所以“好”，就好在适时，好在“润物”。春天的雨，一般是伴随...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f0eca5e6bb82b8cefe8e3", "shortContent": "这是描绘春夜雨景，表现喜悦心情的名作。\n一开头就用一个“好”字赞美“雨”。在生活里，“好”常常被用来赞美那些做好事的人。如今用“好”赞美雨，已经会唤起关于做好事的人的联想。接下去，就把雨拟人化，说它“知时节”，懂得满足客观需要。不是吗？春天是万物萌芽生长的季节，正需要下雨，雨就下起来了。你看它多么“好”！\n诗人盼望这样的“好雨”，喜爱这样的“好雨”。所以题目中的那个“喜”字在诗里虽然没有露面，但“...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fc22c5e6bb82b8caff682", "bookTitle": "历代咏春诗鉴赏：春江花月夜", "articleId": "6472f6a6e49f46528ae10d6d", "shortContent": "这是描绘春夜雨景，表现喜悦心情的名作。\n\n一开头就用一个“好”字赞美“雨”。在生活里，“好”常常被用来赞美那些做好事的人。如今用“好”赞美雨，已经会唤起关于做好事的人的联想。接下去，就把雨拟人化，说它“知时节”，懂得满足客观需要。不是吗？春天是万物萌芽生长的季节，正需要下雨，雨就下起来了。你看它多么“好”！\n\n第二联，进一步表现雨的“好”。雨之所以“好”，就好在适时，好在“润物”。春天的雨，一般是...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '周珽《唐诗选脉会通评林》：此诗妙在春时雨，首联便得所喜之故，后摹雨景入细，而一结见春，尤有可爱处。
仇兆鳌《杜诗详注》：雨骤风狂，亦足损物。曰“潜”曰“细”，写得脉脉绵绵，于造化发生之机，最为密切。
黄生《唐诗摘钞》：雨细而不骤，才能润物，又不遽行，才见好雨。三、四紧着雨说，五六略开一步，七八再绾合。杜咏物诗多如此，后学之圆规方矩也。五六写雨境妙矣，尤妙能见“喜”意。盖云黑则雨浓可知。六衬五，五衬三，三衬四，加倍写“润物细无声”五字，即是加倍写“喜”字，细语更有风味。
浦起龙《读杜心解》：起有悟境，于“发生”悟出“知时”也。五六拓开，自是定法。结语亦从悟得，乃是意其然也。通首下字，从咀含而出。“喜”意都从罅缝里迸透。', 'center', 1413388439, '57b1aaeea341310060f66719', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10356, '客至', NULL, 372, 1416, 2, 2, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155838.htm', '', '舍南舍北皆春水，但见群鸥日日来。
花径不曾缘客扫，蓬门今始为君开。
盘飧市远无兼味，樽酒家贫只旧醅。
肯与邻翁相对饮，隔篱呼取尽余杯。', '据黄鹤《黄氏集千家注杜工部诗史补遗》，此诗是上元二年（761）春天，杜甫五十岁时，在成都草堂所作。杜甫在历尽颠沛流离之后，终于结束了长期漂泊的生涯，在成都西郊浣花溪头盖了一座草堂，暂时定居下来。诗人在久经离乱，安居草堂后不久，客人来访时作了这首诗。
此诗前两句描写居处的景色，清丽疏淡，与山水鸥鸟为伍，显出与世相隔的心境；后六句写有客来访的欣喜以及诚恳待客，呼唤邻翁对饮的场景。全诗流露诗人诚朴恬淡的情怀和好客的心境，自然浑成，一线相接，把居处景、家常话、故人情等富有情趣的生活场景刻画得细腻逼真，表现出了浓郁的生活气息和人情味。', '客至：客指崔明府，杜甫在题后自注：“喜崔明府相过”。明府，唐人对县令的称呼。相过，即探望、相访。
舍：指家。
但见：只见。此句意为平时交游很少，只有鸥鸟不嫌弃能与之相亲。
花径：长满花草的小路。
蓬门：用蓬草编成的门户，以示房子的简陋。
市远：离市集远。
兼味：多种美味佳肴。无兼味，谦言菜少。
“樽酒家贫只旧醅”句：古人好饮新酒，杜甫以家贫无新酒感到歉意。樽，酒器；旧醅，隔年的陈酒。
肯：能否允许，这是向客人徵询。
余杯：馀下来的酒。', '房前屋后都是一波春水，只见群鸥日日飞去归来。
长满花草的庭院小路没有因为迎客而打扫，只是为了你的到来，我家草门首次打开。
集市太远，盘中的饭菜实在简单；家境贫寒，只有陈年浊酒招待。
如肯与邻家老翁举杯一起对饮，那我就隔着篱笆将他唤来。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ac2e6a6b501f95c155", "shortContent": "这是一首洋溢着浓郁生活气息的纪事诗，表现诗人诚朴的性格和喜客的心情。作者自注：“喜崔明府（“明府”为唐人对县令的称呼）相过”，简要说明了题意。\n一、二两句先从户外的景色着笔，点明客人来访的时间、地点和来访前夕作者的心境。“舍南舍北皆春水”，把绿水缭绕、春意荡漾的环境表现得十分秀丽可爱。这就是临江近水的成都草堂。“皆”字暗示出春江水势涨溢的情景，给人以江波浩渺、茫茫一片之感。群鸥，在古人笔下常常作水...", "authors": ["范之麟"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a7a", "shortContent": "这是一首洋溢着浓郁生活气息的纪事诗，表现诗人诚朴的性格和喜客的心情。作者自注：“喜崔明府（“明府”为唐人对县令的称呼）相过”，简要说明了题意。\n\n一、二两句先从户外的景色着笔，点明客人来访的时间、地点和来访前夕作者的心境。“舍南舍北皆春水”，把绿水缭绕、春意荡漾的环境表现得十分秀丽可爱。这就是临江近水的成都草堂。“皆”字暗示出春江水势涨溢的情景，给人以江波浩渺、茫茫一片之感。群鸥，在古人笔下常常作...", "authors": ["范之麟"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d1933015207", "shortContent": "今日浣花溪畔的草堂的氛围似乎与往日格外有些不同。向来的宁谧与清幽好似被打破了，主人正翘首而望，似有所期盼。他究竟在等待什么呢？结合诗题“客至”，刹那间，我们明白了，原来是有客前来，来到这世外桃源般的所在。\n\n诗人似乎在向客人展示，这边风景独好！看啊，“舍南舍北皆春水，但见群鸥日日来。”绿水环绕，在我的居所左右，每一个泛起的涟漪都荡漾着几分春色，浩渺的江波，则给人带来了不尽的春意享受。每日枕着绿波入...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6465e8b27f27182da3596cfd", "shortContent": "这是一首洋溢着浓郁生活气息的纪事诗，表现诗人诚朴的性格和喜客的心情。作者自注：“喜崔明府（“明府”为唐人对县令的称呼）相过”，简要说明了题意。\n\n一、二两句先从户外的景色着笔，点明客人来访的时间、地点和来访前夕作者的心境。“舍南舍北皆春水”，把绿水缭绕、春意荡漾的环境表现得十分秀丽可爱。这就是临江近水的成都草堂。“皆”字暗示出春江水势涨溢的情景，给人以江波浩渺、茫茫一片之感。群鸥，在古人笔下常常作...", "authors": ["范之麟"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f2f3230675327e1b5c7f2", "shortContent": "这是一首洋溢着浓郁生活气息的纪事诗，表现诗人诚朴的性格和喜客的心情。作者自注：“喜崔明府（“明府”为唐人对县令的称呼）相过”，简要说明了题意。\n一、二两句先从户外的景色着笔，点明客人来访的时间、地点和来访前夕作者的心境。“舍南舍北皆春水”，把绿水缭绕、春意荡漾的环境表现得十分秀丽可爱。这就是临江近水的成都草堂。“皆”字暗示出春江水势涨溢的情景，给人以江波浩渺、茫茫一片之感。群鸥，在古人笔下常常作水...", "authors": ["范之麟"], "pressName": "上海辞书出版社"}]', '《后村诗话》：此篇（按指《客至》）若戏效元白体者。
《唐诗归》：钟云：二语严，门无杂宾，意在言外矣（“花径不曾”二句下）。谭云：“肯与”二字形容贵客豪宾，入妙（“肯与邻翁”二句下）。
《唐诗援》：天然风韵，不烦涂抹。
《唐诗镜》：村朴趣，村朴语。
《唐诗摘钞》：经时无客过，日日有鸥来。语中虽见寂寞，意内愈形高旷。前半见空谷足音之喜，后半见贫家真率之趣。
《初白庵诗评》：自始至末，蝉联不断，七律得此，有掉臂游行之乐。
《义门读书记》：反打开去，惟公能之，《宾至》起相似。风雨则思友，况经春积水绕舍，日惟鸥鹭群乎？极写不至，则“喜”字溢发纸上矣（“舍南舍北”二句下）。
《茧斋诗谈》：一、二言无人来也。三、四是敬客意。五、六是待客具。每句含三层意，人却不觉，炼力到也。七、八又商量得妙。如书法之有中锋，最当临摹。
《唐宋诗醇》：朱瀚云：首句用“在水一方”诗意。次句用“渔翁狎鸥”故事。
《读杜心解》：首联兴起，次联流水入题，三联使“至”字足意，至则须款也。末联就“客”字生情，客则须陪也。
《杜诗镜铨》：邵云：超脱有真趣。陈秋田云：宾是贵介之宾，客是相知之客，与前《宾至》首各见用意所在。
《唐诗归折衷》：唐云：前篇《宾至》以气骨胜，此以风韵胜。吴敬夫云：临文命意，如匠石呈材，《早朝》必取高华，《客至》不妨朴野。昔人评杜诗，谓如周公制作，巨细咸备，以此也。
《唐七律隽》：只家常话耳。不见深艰作意之语，而有天然真致。与《宾至》诗同一格，而《宾至》犹有作意语；虽开元、白一派，而元、白一生，何曾得此妙境！
《唐诗偶评》：极写不至，则喜意溢发纸上矣。市远家贫，惟恐我喜之无以将也。
《近体秋阳》：无意为诗，率然而成。却增损一意不得，颠倒一句不得，变易一字不得。此等构结，浅人既不辨，深人又不肯，非子美，吾谁与归！
《闻鹤轩初盛唐近体读本》：评：首二句是《三百篇》即所见以起兴，反兴法也。三、四开合了然，五、六直率。近人学杜，但袭此种，便失少陵真面目矣！落句作致，在着“隔篱呼取”字。
《读杜私言》：《宾至》、《客至》二首，别有机抒，自成经纬。
《杜诗集评》：朱彝尊云：起二句妙极天趣。
《历代诗法》：诗人荡然谦厚之意，见于言外。
《唐宋诗举要》：层层反跌，一句到题，自然得势（“蓬门今始”句下）。', 'center', 1417443541, '57b8bbf01532bc005b9a118f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10397, '青玉案', NULL, 619, 877, 4, 6, '贺铸', NULL, 10098, '57b9bbb28ac2470063feff0a', '宋', 'ci', '词', 'http://baike.baidu.com/view/1775870.htm', '', '凌波不过横塘路，但目送、芳尘去。锦瑟华年谁与度？月桥花院，琐窗朱户，只有春知处。
飞云冉冉蘅皋暮，彩笔新题断肠句。试问闲愁都几许？一川烟草，满城风絮，梅子黄时雨。', '此词通过对暮春景色的描写，抒发作者所感到的「闲愁」。上阕写路遇佳人而不知所往的怅惘情景，也含蓄地流露其沉沦下僚、怀才不遇的感慨；下阕写因思慕而引起的无限愁思，表现了幽居寂寞积郁难抒之情绪。全词虚写相思之情，实抒悒悒不得志的「闲愁」。立意新奇，想象丰富，历来广为传诵。', '青玉案：词牌名。汉·张平子《四愁诗》：「美人赠我锦绣段，何以报之青玉案」。因取以为调名。六十七字，前后阕各五仄韵。亦有第五句不用韵者。
凌波：形容女子步态轻盈。三国魏·曹子建《洛神赋》：「凌波微步，罗袜生尘。」
芳尘去：指美人已去。
锦瑟：饰有彩纹的瑟。
锦瑟华年：指美好的青春时期。唐·李义山《锦瑟》诗：「锦瑟无端五十絃，一絃一柱思华年。」
月桥：像月亮似的小拱桥。
花院：花木环绕的庭院。
月桥花院：一作「月台花榭」。
琐窗：雕绘连琐花纹的窗子。
朱户：朱红的大门。
飞：一作「碧」。
冉冉：指云彩缓缓流动。
蘅皋（hénggāo）：长着香草的沼泽中的高地。
彩笔：比喻有写作的才华。《南史·江淹传》：「……（淹）尝宿于冶亭，梦一丈夫自称郭璞，谓淹曰：『吾有笔在卿处多年，可以见还。』淹乃探怀中得五色笔一以授之。」断肠句：伤感的诗句。
试问：一说「若问」。
闲愁：一说「闲情」。
都几许：总计为多少。
一川：遍地、一片。
梅子黄时雨：江南一带初夏梅熟时多连绵之雨，俗称「梅雨」。《岁时广记·卷一》引《东皋杂录》：「后唐人诗云：『楝花开后风光好，梅子黄时雨意浓。』」', '你步履轻盈却不肯来到横塘，依旧凝望目送你带走了芬芳。你与谁相伴共度这美好时光？月桥花屋朱门映着美丽花窗，只有春风才知你生活的地方。
碧云飘飘的杜恒洲暮色茫茫，我用彩笔写下这伤心的诗行。如果要问我的伤心多深多长？就像那一川烟雨笼罩的青草，又如满城飞絮，又如同江南的梅雨。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74c00ce818559d0507e3", "shortContent": "这首词说来好笑，原是贺方回退居苏州时，因看见了一位女郎，便生了倾慕之情，写出了这篇名作。这事本身并不新奇，好像也没有“重大意义”，值不得表彰。无奈它确实写来美妙动人，当世就已膺盛名，历代传为名篇———这就不容以“侧艳之词”而轻加蔑视了。\n方回在苏州筑“企鸿居”，大约也是因此而作。何以言之？试看此词开头就以子建忽睹洛神为比，而《洛神赋》中“翩若惊鸿”之句，脍炙千古，企鸿者，岂不是企望此一惊鸿般的宓妃...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5c60ce818559d063b9b", "shortContent": "这首词说来好笑，原是贺方回退居苏州时，因看见了一位女郎，便生了倾慕之情，写出了这篇名作。这事本身并不新奇，好像也没有“重大意义”，值不得表彰。无奈它确实写来美妙动人，当世就已膺盛名，历代传为佳句，———这就不容以“侧艳之词”而轻加蔑视了。\n方回在苏州筑“企鸿居”，大约就也是因此而作。何以言之？试看此词开头就以子建忽睹洛神为比，而《洛神赋》中“翩若惊鸿”之句，脍炙千古，企鸿者，岂不是企望此一惊鸿般的...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059254f534825dee9fd6f8", "shortContent": "这首词说来好笑，原是贺方回退居苏州时，因看见了一位女郎，便生了倾慕之情，写出了这篇名作。这事本身并不新奇，好像也没有“重大意义”，值不得表彰。无奈它确实写来美妙动人，当世就已膺盛名，历代传为佳句，——这就不容以“侧艳之词”而轻加蔑视了。\n\n方回在苏州筑“企鸿居”，大约就也是因此而作。何以言之？试看此词开头就以子建忽睹洛神为比，而《洛神赋》中“翩若惊鸿”之句，脍炙千古，企鸿者，岂不是企望此一惊鸿般的...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277f84f8efdff05d7d6839b", "bookTitle": "李清照全集", "articleId": "6312258bc26cbf3417f014ab", "shortContent": "此首为贺铸作，见《东山词》卷上，《乐府雅词》卷上、《中吴记闻》卷三，《诗人玉屑》卷二十一等书。（《词学筌蹄》卷五误作李清照词）。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f427ccdb86c49f290d5", "shortContent": "《宋史·贺铸传》有言：“（贺铸）长七尺，面铁色，眉目耸拔。喜谈当世事，可否不少假借。虽贵要权倾一时，少不中意，极口诋之无遗辞，人以为近侠。”贺铸外貌奇丑，性格耿介孤傲，棱角分明，其词作亦有“剑吼西风。恨登山临水，手寄七弦桐，目送归鸿”等傲然自重之语。但更多承花间词派婉约绮丽之风，用笔铱丽精致，抒写男女之情或感慨人生变幻。\n不同于花间词派的艳丽露骨，贺铸词风格清丽婉媚，情感含而不发，寓意幽远。这首《...", "authors": ["马　瑶"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127032c26cbf3417f09475", "shortContent": "《宋史·贺铸传》有言：“（贺铸）长七尺，面铁色，眉目耸拔。喜谈当世事，可否不少假借。虽贵要权倾一时，少不中意，极口诋之无遗辞，人以为近侠。”贺铸外貌奇丑，性格耿介孤傲，棱角分明，其词作亦有“剑吼西风。恨登山临水，手寄七弦桐，目送归鸿”等傲然自重之语。但更多承间词派婉约绮丽之风，用笔秾丽精致，抒写男女之情或感慨人生变幻。\n\n不同于花间词派的艳丽露骨，贺铸词风格清丽婉媚，情感含而不发，寓意幽远。这首《...", "authors": ["马瑶"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271c87ccdb86c49f29366", "shortContent": "《宋史·贺铸传》有言：“（贺铸）长七尺，面铁色，眉目耸拔。喜谈当世事，可否不少假借。虽贵要权倾一时，小不中意，极口诋之无遗辞，人以为近侠。”贺铸外貌奇丑，性格耿介孤傲，棱角分明，其词作亦有“剑吼西风。恨登山临水，手寄七弦桐，目送归鸿”等傲然自重之语。但更多承花间词派婉约绮丽之风，用笔秾丽精致，抒写男女之情或感慨人生变幻。\n不同于花间词派的艳丽露骨，贺铸词风格清丽婉媚，情感含而不发，寓意幽远。这首《...", "authors": ["马瑶"], "pressName": "崇文书局"}]', '周竹坡《竹坡诗话》：贺方回尝作《青玉案》，有「梅子黄时雨」之句，人皆服其工，士大夫谓之「贺梅子」。
罗鹤林《鹤林玉露》：贺方回有「试问闲愁都几许？一川烟草，满城风絮，梅子黄时雨」。盖以三者比愁之多也，尤为新奇，兼兴中有比，意味更长。
沈去矜《填词杂说》：「一川烟草，满城风絮，梅子黄时雨。」不特善于喻愁，正以琐碎为妙。
先著、程洪《词洁》：方回《青玉案》词工妙之至，无迹可寻，语句思路亦在目前，而千人万人不能凑拍。
沈震峰《草堂诗馀正集》：叠写三句闲愁，真绝唱！
刘融斋《艺概》：贺方回《青玉案》词收四句云：「试问闲愁都几许？一川烟草，满城风絮，梅子黄时雨。」其末句好处全在「试问」呼起，及与上「一川」二句并用耳。', 'indent', 1413455275, '57b8b53a2e958a005fa43d74', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10357, '旅夜书怀', NULL, 912, 1416, 3, 10, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/4384.htm', '', '细草微风岸，危樯独夜舟。
星垂平野阔，月涌大江流。
名岂文章著，官应老病休。
飘飘何所似，天地一沙鸥。', '此诗是唐代著名诗人杜甫于765年离开四川成都草堂以后，在旅途中所作。诗人用阔大无垠的夜景衬托深沉滞重的孤独感，使人感受到诗人生命的激情正如他笔下奔涌的江流一样澎湃难平，深刻地表现了作者内心飘泊无依的感伤，是杜甫诗歌中的经典作品，也是杜诗五律的名篇，历来为人称道。', '岸：指江岸边。
危樯（qiáng）：高高的船桅杆。独夜舟：是说自己孤零零的一个人夜泊江边。
星垂平野阔：星空低垂，原野显得格外广阔。
月涌：月亮倒映，随水流涌。大江：指长江。
名岂：这句连下句，是用“反言以见意”的手法写的。杜甫确实是以文章而著名的，却偏说不是，可见另有抱负，所以这句是自豪语。休官明明是因论事见弃，却说不是，是什么老而且病，所以这句是自解语了。
官应老病休：官倒是因为年老多病而被罢退。应：认为是、是。
飘飘：飞翔的样子，这里含有“飘零”、“飘泊”的意思，因为这里是借沙鸥以写人的飘泊。', '微风吹拂着江岸的细草，那立着高高桅杆的小船在夜里孤独地停泊着。
星星垂在天边，平野显得宽阔；月光随波涌动，大江滚滚东流。
我难道是因为文章而著名，年老病多也应该休官了。
自己到处漂泊像什么呢？就像天地间的一只孤零零的沙鸥。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92af2cee9a0c24ecf8dc", "shortContent": "公元765年，杜甫带着家人离开成都草堂，乘舟东下，在岷江、长江漂泊。这首五言律诗大概是他舟经渝州（治所在今重庆）、忠州（治所在今重庆忠县）一带时写的。\n诗的前半描写“旅夜”的情景。第一、二两句写近景：微风吹拂着江岸上的细草，竖着高高桅杆的小船在月夜孤独地停泊着。当时杜甫离成都是迫于无奈。这一年的正月，他辞去节度使参谋职务，四月，在成都赖以存身的好友严武死去。处此凄孤无依之境，便决意离蜀东下。因此，...", "authors": ["傅思均"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a85", "shortContent": "公元765年，杜甫带着家人离开成都草堂，乘舟东下，在岷江、长江漂泊。这首五言律诗大概是他舟经渝州（治所在今重庆）、忠州（治所在今重庆忠县）一带时写的。\n\n诗的前半描写“旅夜”的情景。第一、二两句写近景：微风吹拂着江岸上的细草，竖着高高桅杆的小船在月夜孤独地停泊着。当时杜甫离成都是迫于无奈。这一年的正月，他辞去节度使参谋职务，四月，在成都赖以存身的好友严武死去。处此凄孤无依之境，便决意离蜀东下。因此...", "authors": ["傅思均"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e0209f", "shortContent": "经历了几年的辗转漂泊，在朋友的资助下，诗人好不容易在成都郊外建造了一处简单的草堂，有了一个安身之所，也度过了几年相对平和安定的生活。但客居在外，自己的遭遇总是和他人、和朋友紧紧相连。唐代宗永泰元年（765）正月，诗人辞去了节度使参谋职务，同年四月，他的好友严武去世。这样，他在成都赖以生存的所有条件都失去了。失去了一份糊口的职务，更失去了他长久依存的好友，他只能如一只飘零的大雁，携雏另觅新的居所。于...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270597f0b9738b369b1e3", "shortContent": "经历了几年的辗转漂泊，在朋友的资助下，诗人好不容易在成都郊外建造了一处简单的草堂，有了一个安身之所，也度过了几年相对平和安定的生活。但客居在外，自己的遭遇总是和他人、和朋友紧紧相连。永泰元年（765）正月，诗人辞去了节度使参谋职务，同年四月，他的好友严武去世。这样，他在成都赖以生存的所有条件都失去了。失去了一份糊口的职务，更失去了他长久依存的好友，他只能如一只飘零的大雁，携雏另觅新的居所。于是，他...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270d3c26cbf3417f094fb", "shortContent": "经历了几年的辗转漂泊，在朋友的资助下，诗人好不容易在成都郊外建造了一处简单的草堂，有了一个安身之所，也度过了几年相对平和安定的生活。但客居在外，自己的遭遇总是和他人、和朋友紧紧相连。永泰元年（765）正月，诗人辞去了节度使参谋职务。同年四月，他的好友严武去世。这样，他在成都赖以生存的所有条件都失去了。失去了一份糊口的职务，更失去了他长久依存的好友，他只能如一只飘零的大雁，携雏另觅新的居所。于是，他...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6465e79330675327e18e3f02", "shortContent": "此诗写于上元元年（760），这时杜甫刚在成都西郊的草堂定居下来。经过长年颠沛流离之后，总算得到了一个憩息之处，这使他聊感欣慰。然而国家残破、生民涂炭的现实，却时时在撞击他的心灵，使他无法宁静。这首诗就揭示了他内心这种微妙深刻的感情波动。\n\n诗的前四句写草堂之景，笔触悠闲疏淡，诗句好像信手拈来似的。开头“野老”二字，是杜甫自称。江岸回曲，竹篱茅舍，此时诗人正在草堂前的江边漫步观赏。“柴门”一句妙在写...", "authors": ["黄宝华"], "pressName": "上海辞书出版社"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "646609d15fc8182fe9a4152a", "shortContent": "公元765年，杜甫带着家人离开成都草堂，乘舟东下，在岷江、长江飘泊。这首五言律诗大概是他舟经渝州（治所在今重庆）、忠州（治所在今重庆忠县）一带时写的。\n\n诗的前半描写“旅夜”的情景。第一、二两句写近景：微风吹拂着江岸上的细草，竖着高高桅杆的小船在月夜孤独地停泊着。当时杜甫离成都是迫于无奈。这一年的正月，他辞去节度使参谋职务，四月，在成都赖以存身的好友严武死去。处此凄孤无依之境，便决意离蜀东下。因此...", "authors": ["傅思均"], "pressName": "上海辞书出版社"}]', '《鹤林玉露》：诗要健宇撑柱，活字斡旋。如“红入桃花嫩，青归柳叶新”、“弟子贫原宪，诸生老服虔”、“入”与“归”字，“贫”与“老”字，乃撑柱也；……“名岂文章著，官应老病休”，……“岂”与“应”字，乃斡旋也。撑柱，如屋之有柱；斡旋，如车之有轴，文亦然。诗以字，文以句。
《瀛奎律髓》：老杜夕、暝、晚、夜五言律近二十首，选此八首洁净精致者。多是中二句言景物，二句言情。若四句皆言景物，则必有情思贯其间，痛愤哀怨之意多，舒徐和易之调少。以老杜之为人，纯乎忠襟义气，而所遇之时，丧乱不已，宜其然也。
《唐诗品汇》：刘曰：等闲星月，着一“涌”字，夐觉不同（“月涌”句下）。
《四溟诗话》：子美“星随平野阔，月涌大江流”，句法森严，“涌”字尤奇。可严则严，不可严则放过些子，若“鸿雁几时到？江湖秋水多”意在一贯，又觉闲雅不凡矣。
《诗薮》：“山随平野阔，江入大荒流”，太白壮语也；杜“星垂平野阔，月涌大江流”，骨力过之。
《增订评注唐诗正声》：“星垂”二语壮远，意实凄冷。
《唐诗训解》：眉批：夜景之近而小者（“细草”二句下）。夜景之远而大者（“星垂”二句下）。范德机曰：作诗要有惊人语，险诗便惊人。如子美……“船舷暝戛云际寺，水面月出兰田关”，“星垂平野阔，月浦大江流”……李贺“黑云压城城欲摧，甲光照日金鳞开”。此等语，任是人道不到。
《唐诗直解》：写景妙，传情亦妙（“星垂”二句下）。
《唐诗选脉会通评林》：周敬曰：写景妙，传情更妙。
《唐诗评选》：颔联一空万古。虽以后四语之脱气，不得不留之，看杜诗常有此憾。“名岂文章著”自是好句。“天地…沙鸥”则大言无实也。
《杜诗解》：看他眼中但见星垂、月涌，不见平野、大江；心头但为平野、大江，不为星垂、月涌。千锤万炼，成此奇句，使人读之，咄咄乎怪事矣！
《瀛奎律髓汇评》：纪昀：通首神完气足，气象万千，可当雄浑之品。
《茧斋诗谈》：“星垂平野阔，月浦大江流”，气象极佳。极失意事，看他气不痿薾，此是骨力定。
《唐宋诗醇》：“小市常争米，孤城早闭门”。写荒凉之景，如在目前。若此孤舟夜泊，著语乃极雄杰，当由真力弥满耳。李白“山随平野”一联，语意暗合，不分上下，亦见大家才力天然相似。
《唐诗别裁》：胸怀经济，故云：名岂以文章而著；官以论事罢，而云：老病应休。立言之妙如此。
《杜诗镜铨》：邵子湘云：警联不易得（“星垂”句下）。
《唐诗选》：此二句与后二句俱用单字起，是句法（“月涌”句下）。
《网师园唐诗笺》：十字写得广大，几莫能测（“星垂”二句下）。
《唐诗矩》：前后两截格。“一沙鸥”何其渺；“天地”字，何其大。合而言之曰：“天地一沙鸥”，语愈悲，气愈傲。
《闻鹤轩初盛唐近体读本》：评：三、四雄大而有骨，不入虚枵，此居可辨。五、六亦大峭健，必无时弱。且二联一景一情，肉骨称适，章法最整。首联必多对起，又每用“独”字，此老杜所独。', 'center', 1415638482, '57b8a41d8ac2470062de646e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10358, '登岳阳楼', NULL, 543, 1416, 3, 10, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/156032/4966977.htm', '', '昔闻洞庭水，今上岳阳楼。
吴楚东南坼，乾坤日夜浮。
亲朋无一字，老病有孤舟。
戎马关山北，凭轩涕泗流。', '唐代宗大历三年（西元七六八年）之后，杜少陵出峡漂泊两湖，此诗是登岳阳楼而望故乡，触景感怀之作。开头写早闻洞庭盛名，然而到暮年纔实现目睹名湖的愿望，表面看有初登岳阳楼之喜悦，其实意在抒发早年抱负至今未能实现之情。二联是洞庭的浩瀚无边。三联写政治生活坎坷，漂泊天涯，怀才不遇的心情。末联写眼望国家动荡不安，自己报国无门的哀伤。写景虽衹二句，却显技巧精湛，抒情虽暗淡落寞，却吞吐自然，毫不费力。', '洞庭水：即洞庭湖，在今湖南北部，长江南岸，是中国第二淡水湖。
岳阳楼：即岳阳城西门楼，在湖南省岳阳市，下临洞庭湖，为游览胜地。
坼（chè）：分裂。
乾坤：指日、月。
浮：日月星辰和大地昼夜都飘浮在洞庭湖上。
「吴楚东南坼，乾坤日夜浮。」句：吴楚两地在我国东南。
无一字：音讯全无。字，这里指书信。
老病：杜少陵时年五十七岁，身患肺病，风痹，右耳已聋。
有孤舟：唯有孤舟一叶飘零无定。
戎马：指战争。
关山北：北方边境。
凭轩：靠着窗户。
涕泗（sì）流：眼泪禁不住地流淌。', '早早就闻知洞庭湖的盛名，今天终于登上了岳阳楼观看。
吴楚被大至分为东南两地，日月星辰都漂浮在洞庭湖上。
亲朋好友个个都音信全无，我年老多病仿佛一叶孤舟。
北边的关山战火不曾停息，我扶窗远眺不禁涕泪交流。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b0d635634aee3ded47", "shortContent": "这首诗的意境是十分宽阔宏伟的。\n诗的颔联“吴楚东南坼，乾坤日夜浮”，是说广阔无边的洞庭湖水，划分开吴国和楚国的疆界，日月星辰都像是整个地飘浮在湖水之中一般。只用了十个字，就把洞庭湖水势浩瀚、无边无际的巨大形象特别逼真地描画出来了。\n杜甫到了晚年，已经是“漂泊西南天地间”，没有一个安居之所，只好“以舟为家”了。所以下边接着写：“亲朋无一字，老病有孤舟。”亲戚朋友们这时连音信都没有了，只有年老多病的诗...", "authors": ["傅庚生"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac26845f3e157ce319", "shortContent": "这首诗的意境是十分宽阔宏伟的。\n\n诗的颔联“吴楚东南坼，乾坤日夜浮”，是说广阔无边的洞庭湖水，划分开吴国和楚国的疆界，日月星辰都像是整个地飘浮在湖水之中一般。只用了十个字，就把洞庭湖水势浩瀚、无边无际的巨大形象特别逼真地描画出来了。\n\n杜甫到了晚年，已经是“漂泊西南天地间”，没有一个安居之所，只好“以舟为家”了。所以下边接着写：“亲朋无一字，老病有孤舟。”亲戚朋友们这时连音信都没有了，只有年老多病...", "authors": ["傅庚生"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e020a0", "shortContent": "本诗作于大历三年（768），杜甫漂泊于江湘流域时所作。\n\n此诗笔力雄浑，力压群伦，此前此后，唯一可与之相比的题岳阳楼诗，唯有孟浩然《望洞庭湖赠张丞相》的“气蒸云梦泽，波撼岳阳城”一联，然孟诗比之于杜诗，亦稍有所缺，不能像杜诗如此浑成。\n\n“昔闻洞庭水，今上岳阳楼”，起句平易。“昔闻”与“今上”，是常见的闻其名而终至的格局。杜甫唯有晚年，才漂泊在江、湘之上，与江水和洞庭相亲，是为与实。\n\n颔联气象陡...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "64662db0c0471b0062d3b021", "shortContent": "这首诗的意境是十分宽阔宏伟的。\n\n诗的颔联“吴楚东南坼，乾坤日夜浮”，是说广阔无边的洞庭湖水，划分开吴国和楚国的疆界，日月星辰都像是整个地飘浮在湖水之中一般。只用了十个字，就把洞庭湖水势浩瀚、无边无际的巨大形象特别逼真地描画出来了。\n\n杜甫到了晚年，已经是“漂泊西南天地间”，没有一个安居之所，只好“以舟为家”了。所以下边接着写：“亲朋无一字，老病有孤舟。”亲戚朋友们这时连音信都没有了，只有年老多病...", "authors": ["傅庚生"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f2fafe49f46528ad23564", "shortContent": "这首诗的意境是十分宽阔宏伟的。\n诗的颔联“吴楚东南坼，乾坤日夜浮”，是说广阔无边的洞庭湖水，划分开吴国和楚国的疆界，日月星辰都像是整个地飘浮在湖水之中一般。只用了十个字，就把洞庭湖水势浩瀚、无边无际的巨大形象特别逼真地描画出来了。\n杜甫到了晚年，已经是“漂泊西南天地间”，没有一个安居之所，只好“以舟为家”了。所以下边接着写：“亲朋无一字，老病有孤舟。”亲戚朋友们这时连音信都没有了，只有年老多病的诗...", "authors": ["傅庚生"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "64733ec430675327e1c5c017", "shortContent": "这首诗的意境是十分广阔宏伟的。\n\n诗的颔联“吴楚东南坼，乾坤日夜浮”，是说广阔无边的洞庭湖水，划分开吴国和楚国的疆界，日月星辰都像是整个地飘浮在湖水之中一般。只用了十个字，就把洞庭湖水势浩瀚、无边无际的巨大形象特别逼真地描画出来了。\n\n杜甫到了晚年，已经是“漂泊西南天地间”，没有一个定居之所，只好“以舟为家”了。所以下边接着写：“亲朋无一字，老病有孤舟。”亲戚朋友们这时连音信都没有了，只有年老多病...", "authors": ["傅庚生"], "pressName": "上海辞书出版社"}]', '唐鲁国《唐子西文录》：过岳阳楼，观杜子美诗，不过四十字尔，气象宏放，涵蓄深远，殆与洞庭争雄，所谓富哉言乎者。太白、退之辈率为大篇，极其笔力，终不逮也。杜诗虽小而大，余诗虽大而小。
胡元任《苕溪渔隐丛话》：《西清诗话》云：洞庭天下壮观，自昔骚人墨客，题之者众矣……皆见称于世。然未若孟浩然「气蒸云梦泽，波动岳阳城」，则洞庭空旷无际，气象雄张，如在目前。至读子美诗，则又不然。「吴楚东南坼，乾坤日夜浮。」不知少陵胸中吞几云梦也。
刘後村《後村诗话》：岳阳城赋咏多矣，须推此篇独步，非孟浩然辈所及。
方虛谷《瀛奎律髓》：岳阳楼天下壮观，孟杜二诗尽之矣。中二联，前言景，后言情，乃诗质一体也。
高漫士《唐诗品汇》：刘曰：气压百代，为五言雄浑之绝（「吴楚」二句下）。
周青羊《唐诗选脉会通评林》：刘辰翁曰：五、六略不用意，而情景适等。赵云龙曰：句律浑朴。盛唐起语，大率如此，三、四高绝。
何义门《义门读书记》：定远云：破题笔力千钧。岳阳楼因洞庭湖而有，先点洞庭，后破「登」字，迎刃之势，……上下各四句，直似不相照顾；仍复浑成一气。非公笔力天纵，鲜不顾此失彼。
胡元瑞《诗薮》：「气蒸云梦泽，波撼岳阳城」，浩然壮语也，杜「吴楚东南坼，乾坤日夜浮」气象过之。
王船山《唐诗评选》：出峡时摄汗漫于整暇，不复作「花鸟无私」、「水流不竞」等语。起二句得未曾有，虽近情而不俗。「亲朋」一联，情中有景。「戎马关山北」五字卓炼。此诗之佳亦止此。必推高之以为大家，为元气，为雄浑壮健，皆不知诗者以耳食不以舌食之论。
查他山《初白菴诗评》：杜作前半首由近说到远，阔大沉雄，千古绝唱，孟作亦在下风。
黄扶孟《唐诗摘钞》：亲朋无一字相遗，老病有孤舟相伴，各藏后二字，名「歇后句」。题是登岳阳楼，诗中便要见出登楼之人是何身分；对此景作此诗，是何胸次，如此诗方与洞庭岳阳气势相敌。
黄扶孟《杜诗说》：前半写景，如此阔大；五、六自叙，如此落寞，诗境阔狭顿异。结语凑泊极难，转出「戎马关山北」五字。胸襟气象，一等相称，宜使后人搁笔也。
张谦宜《茧斋诗谈》：「吴楚东南坼，乾坤日夜浮。」十字写尽湖势，气象甚大。一转入自己心事，力与之敌。
清高宗敕编《唐宋诗醇》：元气浑沦，不可凑泊，千古绝唱。
沈归愚《唐诗别裁》：三、四雄跨今古，五、六写情黯淡。著此一联，方不板滞。孟襄阳三、四语实写洞庭，此衹用空写，却移他处不得，本领更大。
浦山伧《读杜心解》：黄生云：写景如此阔大，自叙如此落寞，诗境阔狭顿异……愚按：不阔则狭处不苦，能狭则阔境愈空。然玩三、四，亦已暗逗辽远漂流之象。
杨西木《杜诗镜铨》：王阮亭云：元气浑沦，不可凑泊，高立云霄，纵怀身世。写洞庭衹两句，雄跨今古。下衹写情，方不似后人泛咏洞庭诗也。
谭宗《近体秋阳》：元气浑灏，目无今古。
宋宗元《网师园唐诗笺》：「吴楚」二句雄伟，雅与题称。此作与襄阳《临洞庭》诗同为绝唱，宜方虚谷大书毬门，后人更不敢题也。
梁退菴《浪迹丛谈》：徐筠亭时作曰：「孟襄阳诗『气蒸云梦泽，波撼岳阳城』，杜少陵诗『吴楚东南坼，乾坤日夜浮』，力量气魄已无可加，而孟则继之曰『欲济无舟揖，端居耻圣明』，杜则继之曰『亲朋无一字，老病有孤舟』，皆以索寞幽渺之情，摄归至小。两公所作，不谋而合，可见文章有定法。若更求博大高深之语以称之，必无可称而力蹶无完诗矣。」', 'center', 1416941030, '57b8f7760a2b58005c91fdd9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10359, '登高', NULL, 1047, 1416, 4, 13, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/76345/5364115.htm', '', '风急天高猿啸哀，渚清沙白鸟飞回。
无边落木萧萧下，不尽长江滚滚来。
万里悲秋常作客，百年多病独登台。
艰难苦恨繁霜鬓，潦倒新停浊酒杯。', '此诗是唐代伟大诗人杜甫于大历二年（767）秋天在夔州所作的一首七律。前四句写景，述登高见闻，紧扣秋天的季节特色，描绘了江边空旷寂寥的景致。首联为局部近景，颔联为整体远景。后四句抒情，写登高所感，围绕作者自己的身世遭遇，抒发了穷困潦倒、年老多病、流寓他乡的悲哀之情。颈联自伤身世，将前四句写景所蕴含的比兴、象征、暗示之意揭出；尾联再作申述，以衰愁病苦的自我形象收束。此诗语言精练，通篇对偶，一二句尚有句中对，充分显示了杜甫晚年对诗歌语言声律的把握运用已达圆通之境。', '登高：农历九月九日为重阳节，历来有登高的习俗。
猿啸哀：指长江三峡中猿猴凄厉的叫声。《水经注·江水》引民谣云：“巴东三峡巫峡长，猿鸣三声泪沾裳。”
渚（zhǔ）：水中的小洲；水中的小块陆地。鸟飞回：鸟在急风中飞舞盘旋。回：回旋。
落木：指秋天飘落的树叶。萧萧：风吹落叶的声音。
万里：指远离故乡。常作客：长期漂泊他乡。
百年：犹言一生，这里借指晚年。
艰难：兼指国运和自身命运。苦恨：极恨，极其遗憾。苦，极。繁霜鬓：增多了白发，如鬓边着霜雪。繁，这里作动词，增多。
潦倒：衰颓，失意。这里指衰老多病，志不得伸。新停：新近停止。重阳登高，例应喝酒。杜甫晚年因肺病戒酒，所以说“新停”。', '天高风急猿声凄切悲凉，清澈水中群鸥嬉戏盘旋。
无穷无尽的树叶纷纷落，长江滚滚涌来奔腾不息。
悲对秋色感叹漂泊在外，暮年多病我独自登高台。
深为憾恨鬓发日益斑白，困顿潦倒病后停酒伤怀。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b034a8757d5a0e1c9e", "shortContent": "此诗是杜甫大历二年（767）秋在夔州（治今重庆奉节）时所写。夔州在长江之滨。全诗通过登高所见秋江景色，倾诉了诗人长年漂泊、老病孤愁的复杂感情，慷慨激越，动人心弦。清杨伦称赞此诗为“杜集七言律诗第一”（《杜诗镜铨》），明胡应麟《诗薮》更推重此诗“精光万丈”，是“古今七言律第一”。\n前四句写登高见闻。首联对起。诗人围绕夔州的特定环境，用“风急”二字带动全联，一开头就写成了千古流传的佳句。夔州向以猿多著...", "authors": ["陶道恕"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac26845f3e157ce318", "shortContent": "此诗是杜甫大历二年（767）秋在夔州（治今重庆奉节）时所写。夔州在长江之滨。全诗通过登高所见秋江景色，倾诉了诗人长年漂泊、老病孤愁的复杂感情，慷慨激越，动人心弦。清杨伦称赞此诗为“杜集七言律诗第一”（《杜诗镜铨》），明胡应麟《诗薮》更推重此诗“精光万丈”，是“古今七言律第一”。\n\n前四句写登高见闻。首联对起。诗人围绕夔州的特定环境，用“风急”二字带动全联，一开头就写成了千古流传的佳句。夔州向以猿多...", "authors": ["陶道恕"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d193301520a", "shortContent": "《登高》是杜甫七言律诗的代表作之一。七律这种诗体产生于初唐，到盛唐时期已发展到成熟阶段，其最高成就的代表作家正是杜甫。按常规写法，七律每句七字，每首八句，每两句称为一联。四联之中，中间两联要求对仗，分别写景（或叙事）、抒情，从而形成一种很严整的结构。由于杜甫的诗艺已达到妒火纯青的境界，因而往往对常格有所突破。我们细读这首《登高》，不难发现它四联都是对偶句，既特别严整，又给人耳目一新之感。它的前两联...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270617f0b9738b369b1fb", "shortContent": "《登高》是杜甫七言律诗的代表作之一。七律这种诗体产生于初唐，到盛唐时期已发展到成熟阶段，其最高成就的代表作家正是杜甫。按常规写法，七律每句七字，每首八句，每两句称为一联。四联之中，中间两联要求对仗，分别写景（或叙事）、抒情，从而形成一种很严整的结构。由于杜甫的诗艺已达到炉火纯青的境界，因而往往对常格有所突破。我们细读这首《登高》，不难发现它四联都是对偶句，既特别严整，又给人耳目一新之感。它的前两联...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270d4c26cbf3417f09502", "shortContent": "《登高》是杜甫七言律诗的代表作之一。七律这种诗体产生于初唐，到盛唐时期已发展到成熟阶段，其最高成就的代表作家正是杜甫。按常规写法，七律每句七字，每首八句，每两句称为一联。四联之中，中间两联要求对仗，分别写景（或叙事）、抒情，从而形成一种很严整的结构。由于杜甫的诗艺已达到炉火纯青的境界，因而往往对常格有所突破。我们细读这首《登高》，不难发现它四联都是对偶句，既特别严整，又给人耳目一新之感。它的前两联...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "64662c07b6a81d0c53fa2e2b", "shortContent": "此诗是杜甫大历二年（767）秋在夔州（治今重庆奉节）时所写。夔州在长江之滨。全诗通过登高所见秋江景色，倾诉了诗人长年飘泊、老病孤愁的复杂感情，慷慨激越，动人心弦。清杨伦称赞此诗为“杜集七言律诗第一”（《杜诗镜铨》），明胡应麟《诗薮》更推重此诗“精光万丈”，是“古今七言律第一”。\n\n前四句写登高见闻。首联对起。诗人围绕夔州的特定环境，用“风急”二字带动全联，一开头就写成了千古流传的佳句。夔州向以猿多...", "authors": ["陶道恕"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f2f6f902ee364cc8a30fa", "shortContent": "此诗是杜甫大历二年(767)秋在夔州（治今重庆奉节）时所写。夔州在长江之滨。全诗通过登高所见秋江景色，倾诉了诗人长年漂泊、老病孤愁的复杂感情，慷慨激越，动人心弦。清杨伦称赞此诗为“杜集七言律诗第一”（《杜诗镜铨》），明胡应麟《诗薮》更推重此诗“精光万丈”，是“古今七言律第一”。\n前四句写登高见闻。首联对起。诗人围绕夔州的特定环境，用“风急”二字带动全联，一开头就写成了千古流传的佳句。夔州向以猿多著...", "authors": ["陶道恕"], "pressName": "上海辞书出版社"}]', '宋·罗大经《鹤林玉露》：杜陵诗云：“万里悲秋常作客，百年多病独登台。”万里，地之远也；悲秋，时之惨凄也；作客，羁旅也；常作客，久旅也；百年，暮齿也；多病，衰疾也；台，高迥处也；独登台，无亲朋也。十四字之间含有八意，而对偶又极精确。
宋·杨万里《诚斋诗话》：“词源倒流三峡水，笔阵独扫千人军。”“无边落木萧萧下，不尽长江滚滚来。”前一联蜂腰，后一联鹤膝。
宋·刘克庄《后村诗话》：此两联（按指“无边落木”四句）不用故事，自然高妙，在樊川《齐山九日》七言之上。
元·方回《瀛奎律髓》：此诗已去成都分晓。旧以为在梓州作，恐亦未然。当考公病而止酒在何年也。长江滚滚，必临大江耳。
明·凌宏宪《唐诗广选》：杨诚斋曰：全以“萧萧“滚滚”唤起精神，见得连绵，不是装凑赘语。刘会孟曰：三、四句自雄畅，结复郑重。
明·王世贞《艺苑卮言》卷四：老杜集中，吾甚爱“风急天高”一章，结亦微弱。
明·李东阳《麓堂诗话》：“无边落木萧萧下，不尽长江滚滚来。万里悲秋常作客，百年多病独登台。“景是何等景，事是何等事？宋人乃以《九日崔氏蓝天庄》为律师绝唱，何耶？
明·张綖《杜工部诗通》：少陵派有二诗，一派立论宏阔，如此篇”万里悲秋常作客，百年多病独登台“及”二仪清浊还高下，三伏炎蒸定有无“其流为宋诗，本朝庄定山诸公祖之。一派造语富丽，如”珠帘绣柱围黄鹄，锦缆牙墙起白鸥“及，“鱼吹细浪摇歌扇，燕蹴飞花落舞筵”等作，其流为元诗，本朝杨孟诸公祖之。
明·胡应麟《诗薮》内编卷五：作诗大法，唯在格律精严，词调稳契，使句意高远，纵孜孜可剪，何害其工？骨体卑陋，虽一字莫移，何补其拙？如老杜”风急天高“乃唐七言律诗第一首。……“风急天高”一章五十六，如海底珊瑚，瘦劲难明，深沉莫测，而力量万钧。通首章法，句法，字法，前无昔人，后无来学。微说说者，是杜诗，非唐诗耳。然此诗自当为古今七律第一，不必为唐人七言律第一也。元人凭此诗云：”一篇之内，句句皆奇，一句之内，字字皆奇；亦有识者。
明·胡震亨《唐音癸签》：无论结语膇重，即起处“鸟飞回”三字，亦勉强属对，无意味。
明·陆时雍《唐诗镜》：三、四是愁绪语。
明·周珽《唐诗选脉会通评林》：陆深曰：杜格高，不尽合唐律。此篇声韵，字字可歌，与诸作又别。蒋一葵曰：虽起联而句中各自对，老杜中联亦多用此法。吴山民曰：次联势若大海奔涛，四叠字振起之。三联“常”、“独”二字，何等骨力！周珽云：章法句法，直是蛇神牛鬼佐其笔战。
明·王夫之《唐诗评选》：尽古来今，必不可废。结句生僵，不恶，要亦破体特断，不作死板语。
清·查慎行《初白庵诗评》：七律八句皆属对，创自老杜。前四句写景，何等魄力。
清·何焯《义门读书记》：远客悲秋，又以老病止酒，其无聊可知。千绪万端，无首无尾，使人无处捉摸，此等诗如何可学？“风急天高猿啸哀”，发端已藏“独”字。……“潦倒新停浊酒杯”，顶“百年多病”。结凄壮，止益登高之悲，不见九日之乐也。前半先写“登高”所见，第五插出“万里作客”，呼起“艰难”，然后点出“登台”，在第六句中，见排奡纵横。
清高宗敕编《唐宋诗醇》：气象高浑，有如巫峡千寻，走云连风，诚为七律中稀有之作。后人无其骨力，徒肖之于声貌之间，外强而中干，是为不善学杜者。
清·吴昌祺《删订唐诗解》：太白过散，少陵过整，故此诗起太实，结亦滞。
清·张世炜《唐七律隽》：四句如千军万马，冲坚破锐，又如飘风骤雨，折旆翻盆。合州极爱之，真有力拔泰山之势。
清·黄叔灿《唐诗笺注》：通首下字皆不寻常。
清·沈德潜《唐诗别裁》：八句皆对，起二句，对举之中仍复用韵，格奇变。昔人谓两联俱可裁去二字，试思“落木萧萧下”，“长江滚滚来”，成何语耶？好在“无边”、“不尽”、“万里”、“百年”。
清·王士禛《带经堂诗话》卷三：七言律有以叠字益见悲壮者，如杜子美“无边落木萧萧下，不尽长江滚滚来。”“江天漠漠鸟双去，风雨时时龙一吟”是也。
清·施补华《岘佣说诗》一六二：《登高》起二“风急天高猿啸哀，渚清沙白鸟飞回”，收二艰难苦恨繁霜鬓，潦倒新停浊酒杯“，通首作对而不嫌其笨者，三四”无边落木“之句，有万钧之气；五六”万里悲秋“二句，有顿挫之神耳。又首句妙在押韵，押韵则声长，不押韵则局板。
清·杨伦《杜诗镜铨》：高浑一气，古今独步，当为杜集七言律诗第一。
清·方东树《昭昧詹言》：前四句景，后四句情。一、二碎，三、四整，变化笔法。五、六接递开合，兼叙点，一气喷薄而出。此放翁所常拟之境也。收不觉为对句，换笔换意，一定章法也。而笔势雄骏奔放，若天马之不可羁，则他人不及。
清·曾国藩《十八家诗钞》：张云：此孙仅所谓“夐邈高耸，若凿太虚而号万窍”者。', 'center', 1417443811, '57b8ea8dd342d3005ac6a739', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10360, '白雪歌送武判官归京', NULL, 861, 405, 5, 16, '岑参', NULL, 10096, '57b97daec4c971005593ac34', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155283.htm', '', '北风卷地白草折，胡天八月即飞雪。
忽如一夜春风来，千树万树梨花开。
散入珠帘湿罗幕，狐裘不暖锦衾薄。
将军角弓不得控，都护铁衣冷难着。
瀚海阑干百丈冰，愁云惨淡万里凝。
中军置酒饮归客，胡琴琵琶与羌笛。
纷纷暮雪下辕门，风掣红旗冻不翻。
轮台东门送君去，去时雪满天山路。
山回路转不见君，雪上空留马行处。', '此诗描写西域八月飞雪的壮丽景色，抒写塞外送别、雪中送客之情，表现离愁和乡思，却充满奇思异想，并不令人感到伤感。诗中所表现出来的浪漫理想和壮逸情怀使人觉得塞外风雪变成了可玩味欣赏的对象。全诗内涵丰富宽广，色彩瑰丽浪漫，气势浑然磅礴，意境鲜明独特，具有极强的艺术感染力，堪称盛世大唐边塞诗的压卷之作。其中“忽如一夜春风来，千树万树梨花开”等诗句已成为千古传诵的名句。', '武判官：名不详，当是封常清幕府中的判官。判官，官职名。唐代节度使等朝廷派出的持节大使，可委任幕僚协助判处公事，称判官，是节度使、观察使一类的僚属。
白草折（zhé）：白草：西北的一种牧草，晒干后变白。
胡天：指塞北的天空。胡，古代汉民族对北方各民族的通称。
梨花：春天开放，花作白色。这里比喻雪花积在树枝上，像梨花开了一样。
珠帘：用珍珠串成或饰有珍珠的帘子。形容帘子的华美。罗幕：用丝织品做成的帐幕。形容帐幕的华美。这句说雪花飞进珠帘，沾湿罗幕。“珠帘”“罗幕”都属于美化的说法。
狐裘：狐皮袍子。
锦衾：锦缎做的被子。
锦衾薄：丝绸的被子（因为寒冷）都显得单薄了。形容天气很冷。
角弓：两端用兽角装饰的硬弓，一作“雕弓”。
不得控：（天太冷而冻得）拉不开（弓）。控，拉开。
都护：镇守边镇的长官此为泛指，与上文的“将军”是互文。铁衣：铠甲。
难着：一作“犹着”。着，亦写作“著”。
瀚海：沙漠。这句说大沙漠里到处都结着很厚的冰。
阑干：纵横交错的样子。
百丈：一作“百尺”，一作“千尺”。
惨淡：昏暗无光。
中军：称主将或指挥部。古时分兵为中、左、右三军，中军为主帅的营帐。
饮归客：宴饮归京的人，指武判官。饮，动词，宴饮。
胡琴琵琶与羌笛：胡琴等都是当时西域地区兄弟民族的乐器。这句说在饮酒时奏起了乐曲。羌笛，羌族的管乐器。
辕门：军营的门。古代军队扎营，用车环围，出入处以两车车辕相向竖立，状如门。这里指帅衙署的外门。
风掣：红旗因雪而冻结，风都吹不动了。一言旗被风往一个方向吹，给人以冻住之感。掣，拉、扯。
轮台：唐轮台在今新疆维吾尔自治区米泉县境内，与汉轮台不是同一地方。天山：一名祁连山，横亘新疆东西，长六千余里。
满：铺满。形容词活用为动词。
山回路转：山势回环，道路盘旋曲折。', '北风席卷大地吹折白草，仲秋八月胡地飘降大雪。
仿佛一夜之间春风吹来，树上有如梨花竞相开放。
雪花飘入帘笼沾湿帐幕，就是穿狐皮袍也不暖和。
将军兽角弓冻得拉不开，都护的铠甲冷得难穿上。
无边沙漠结成百丈坚冰，忧愁的阴云凝结在长空。
帐中摆酒为回京人送行，助兴的是琵琶羌笛胡琴。
黄昏时辕门外大雪纷飞，冻硬的红旗风吹不飘动。
在轮台东门外送你回京，临行时茫茫白雪布满山。
山路曲折不见你的身影，雪地上空留马蹄的印迹。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b103048e64fbd9141e", "shortContent": "此诗是一首咏雪送人之作。天宝十三载（754），岑参再度出塞，充任安西北庭节度使封常清的判官。武某或即其前任。为送他归京，写下此诗。“岑参兄弟皆好奇”（杜甫《渼陂行》），读此诗处处不要忽略一个“奇”字。\n此诗开篇就奇突。未及白雪而先传风声，所谓“笔所未到气已吞”——全是飞雪之精神。大雪必随刮风而来，“北风卷地”四字，妙在由风而见雪。“白草”，据《汉书·西域传》颜师古注，乃西北一种草名，王先谦补注谓其...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac26845f3e157ce31b", "shortContent": "此诗是一首咏雪送人之作。天宝十三载（754），岑参再度出塞，充任安西北庭节度使封常清的判官。武某或即其前任。为送他归京，写下此诗。“岑参兄弟皆好奇”（杜甫《渼陂行》），读此诗处处不要忽略一个“奇”字。\n\n此诗开篇就奇突。未及白雪而先传风声，所谓“笔所未到气已吞”——全是飞雪之精神。大雪必随刮风而来，“北风卷地”四字，妙在由风而见雪。“白草”，据《汉书·西域传》颜师古注，乃西北一种草名，王先谦补注谓...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0d4", "shortContent": "天宝十三载（754），岑参再度出塞，在安西北庭节度使封长清幕任判官。武判官是他的同僚，要回京述职，故在中军帐里摆开酒宴，为武判官饯行，于是产生了这首咏雪送人之作。诗以咏雪起，在咏雪中暗寓别情。以送人结，展现了雪中送人的奇景和深情，再现了边地瑰丽的自然风光和戍边将士的精神风貌。\n\n诗从西北边塞的气候特点落墨：这里风大，一刮起来铺天盖地，连坚韧的白草也要折断；这里雪早，一到八月便下雪了。这不仅和内地形...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127068f2af4e09d55b6772", "shortContent": "天宝十三载（754），岑参再度出塞，在安西北庭节度使封常清幕任判官，武判官是他的同僚，要回京述职，在中军帐里摆开酒宴，为武判官饯行，于是产生了这首咏雪送人之作。诗以咏雪起，在咏雪中暗寓别情。以送人结，展现了雪中送人的奇景和深情，再现了边地瑰丽的自然风光和戍边将士的精神风貌。\n\n诗从西北边塞的气候特点落墨：这里风大，一刮起来铺天盖地，连坚韧的白草也要折断；这里雪早，一交八月便下雪了。这不仅和内地形成...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270e0f2af4e09d55b67fd", "shortContent": "天宝十三年（754），岑参再度出塞，在安西北庭节度使封常清幕任判官。武判官是他的同僚，要回京述职，在中军帐里摆开酒宴，为武判官饯行，于是产生了这首咏雪送人之作。诗以咏雪起，在咏雪中暗寓别情。以送人结，展现了雪中送人的奇景和深情，再现了边地瑰丽的自然风光和戍边将士的精神风貌。\n\n诗从西北边塞的气候特点落墨：这里风大，一刮起来铺天盖地，连坚韧的白草也要折断；这里雪早，一交八月便下雪了。这不仅和内地形成...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f79da5f1e74f9587a6a4", "shortContent": "塞外苦寒，北风一吹，大雪纷飞。诗人以“春风”使梨花盛开，比拟“北风”使雪花飞舞，极为新颖贴切。“忽如”二字下得甚妙，不仅写出了“胡天”变幻无常，大雪来得急骤，而且，再次传出了诗人惊喜好奇的神情。“千树万树梨花开”的壮美意境，颇富有浪漫色彩。南方人见过梨花盛开的景象，那雪白的花不仅是一朵一朵，而且是一团一团，花团锦簇，压枝欲低，与雪压冬林的景象极为神似。春风吹来梨花开，竟至“千树万树”，重叠的修辞表...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '方东树《昭昧詹言》：岑嘉州《白雪歌送武判官归京》奇峭。起飒爽，“忽如”六句，奇气奇情逸发，令人心神一快。须日诵一过，心摹而力追之。“瀚海”句换气，起下“归客”。
范大士《历代诗发》：酒笔酣歌，才锋驰突。“雪”字四见，一一精神。
张文荪《唐贤清雅集》：嘉州七古，纵横跌荡，大气盘旋，读之使人自生感慨。有志者，诚宜留心此种。看他如此杂健，其中起伏转折一丝不乱，可谓刚健中含郏后人竞学盛唐，能有此否？', 'center', 1416821572, '57b903e3d342d3005ac74290', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10404, '保俶塔顶观海日', NULL, 2, 253, 0, 1, '高濂', NULL, 10013, '57ba82a88ac2470063045693', '明', 'wen', '文', NULL, '', '保俶塔游人罕登其颠，能穷七级，四望神爽。初秋时，夜宿僧房，至五鼓起登绝顶，东望海日将起，紫雾氤氲，金霞漂荡，漫天光彩，状若长横匹练，圆走车轮，或肖虎豹超骧，鸾鹤飞舞，五色鲜艳，过目改观，瞬息幻化，变迁万状。顷焉阳谷吐火，千山影赤，金轮浴海，闪烁荧煌，火镜浮空，朣胧辉映，丹焰炯炯弥天，流光赫赫动地。斯时惟启明在东，晶丸灿烂，众星隐隐，不敢为颜矣。长望移时，令我目乱神骇，陡然狂呼，声振天表。忽听筹报鸣鸡，树喧宿乌，大地云开，露华影白。回顾城市嚣尘，万籁滚滚生动，空中新凉逼人，凛乎不可留也。下塔闭息敛神，迷目尚为云霞眩彩。', '', NULL, NULL, NULL, NULL, 'indent', 1468668981, '57bba52879bc440063a8feb7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10361, '菩萨蛮', NULL, 241, 1052, 4, 3, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'ci', '词', 'http://baike.baidu.com/view/394196.htm', '', '平林漠漠烟如织，寒山一带伤心碧。暝色入高楼，有人楼上愁。
玉阶空伫立，宿鸟归飞急。何处是归程，长亭更短亭。', '此词是唐宋五代词中的最为脍炙人口的作品之一，一说为唐代诗人李太白所作，然双调词形式在晚唐时才由温庭筠等文人摸索而出，盛唐的李白却早已如此娴熟运用，于理不通，因此此词实际作者一直备受质疑。加之此词未见于唐代载籍，直到宋《尊前集》方出，因此较为主要的一种说法认为此词至早为晚唐五代的蜀人作品，假托李白而已。这首词在艺术层次上颇有水平，写的是深秋暮色之景，全词都浸染在一种愁情离绪之中。其结构呈网状，情景交织，句与句之间紧密相扣，各句间含义也相互交织，创造了一个浑然天成的意境。此词受到古人很高的评价，与《忆秦娥·箫声咽》一起被誉为「百代词曲之祖」。', '菩萨蛮：唐教坊曲名。又名《菩萨篁》、《重叠金》、《花间意》、《梅花句》等。《杜阳杂编》说：「大中初，女蛮国入贡，危髻金冠，璎珞被体，号为菩萨蛮，当时倡优遂制《菩萨蛮曲》，文士亦往往声其词。」后来，《菩萨蛮》便成了词人用以填词的词牌。但据《教坊记》载开元年间已有此曲名。到底孰是，今不可考。
平林：平原上的林木。《诗·小雅·车舝》：「依彼平林，有集维鷮。」毛传：「平林，林木之在平地者也。」
漠漠：迷蒙貌。
烟如织：暮烟浓密。
伤心：极甚之辞。愁苦、欢快均可言伤心。此处极言暮山之青。
暝色：夜色。
玉阶：玉砌的台阶。这里泛指华美洁净的台阶。
伫（zhù）立：长时间地站着等候。谢玄晖《秋夜》诗：「夜夜空伫立。」
归：一作「回」。
长亭更短亭：一作「长亭连短亭」，古代设在路边供行人休歇的亭舍。庾开府《哀江南赋》云：「十里五里，长亭短亭。」说明当时每隔十里设一长亭，五里设一短亭。亭，《释名·卷五》：「亭，停也，人所停集也。」', '远处舒展的树林烟雾漾潆，好像纺织物一般，秋寒的山色宛如衣带，触目伤心的碧绿。暮色进了高高的闺楼，有人正在楼上独自忧愁。
玉石的台阶上，徒然侍立盼望。那回巢的鸟儿，在归心催促下急急飞翔。哪里是我返回的路程？过了长亭接着短亭。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e748434a8757d5a0d9d07", "shortContent": "季节和时序对敏感的人常是触发感兴的媒介。黄昏，是动感情的时刻。风烛残年的老人惆怅地倚闾盼望浪子归家；怀春少女，望着湖中的鸳鸯，陷入了缠绵悱恻的相思之中；而那远离乡井的旅人，也不禁在异地的暮色中勾起浓重的乡思，如果他凑巧是诗人，便会像孟浩然那样地吟出“移舟泊烟渚，日暮客愁新”（《宿建德江》），那愁思，正像薄暮的烟霭那样侵入人的心头，愈来愈浓郁，愈来愈沉重，终于像昏暝的夜幕似的压得人难以喘息。难怪诗人...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892bbb31680ae4c4b4a9", "shortContent": "季节和时序对敏感的人常是触发感兴的媒介。黄昏，是动感情的时刻。风烛残年的老人惆怅地倚闾盼望浪子归家；怀春少女，望着湖中的鸳鸯，陷入了缠绵悱恻的相思之中；而那远离乡井的旅人，也不禁在异地的暮色中勾起浓重的乡思，如果他凑巧是诗人，便会像孟浩然那样地吟出“移舟泊烟渚，日暮客愁新”（《宿建德江》），那愁思，正像薄暮的烟霭那样侵入人的心头，愈来愈浓郁，愈来愈沉重，终于像昏暝的夜幕似的压得人难以喘息。难怪诗人...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "64676d545b7b0d4f451cd356", "shortContent": "季节和时序对敏感的人常是触发感兴的媒介。黄昏，是动感情的时刻。风烛残年的老人惆怅地倚闾盼望浪子归家；怀春少女，望着湖中的鸳鸯，陷入了缠绵悱恻的相思之中；而那远离乡井的旅人，也不禁在异地的暮色中勾起浓重的乡思，如果他凑巧是诗人，便会像孟浩然那样地吟出“移舟泊烟渚，日暮客愁新”（《宿建德江》），那愁思，正像薄暮的烟霭那样侵入人的心头，愈来愈浓郁，愈来愈沉重，终于像昏暝的夜幕似的压得人难以喘息。难怪诗人...", "authors": ["何满子"], "pressName": "上海辞书出版社"}]', '', 'indent', 1415638197, '57b97d2a79bc440060287988', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10362, '点绛唇 · 绍兴乙卯登绝顶小亭', NULL, 131, 241, 2, 1, '叶梦得', NULL, 10097, '57baf1012e958a00693c2ce3', '宋', 'ci', '词', 'http://baike.baidu.com/view/658606.htm', '', '缥缈危亭，笑谈独在千峰上。与谁同赏，万里横烟浪。
老去情怀，犹作天涯想。空惆怅，少年豪放，莫学衰翁样。', '此词作于1135年（宋高宗绍兴五年）作者去任隐居吴兴卞山时，为作者登临卞山绝顶亭有感而发之作。绝顶亭，在吴兴西北弁山峰顶。宋室南渡八年，未能收复中原大片失地，而朝廷却一味向敌求和，与敌妥协，使爱国志士不能为国效力，英雄豪杰也无用武之地。作者作为南宋主战派人物之一，对此深以为恨。词中抒发了作者归居后既旷达超迈又不免孤寂惆怅的矛盾情怀。', '点绛唇：词牌名。此调因梁江淹《咏美人春游》诗中有“白雪凝琼貌，明珠点绛唇”句而取名。四十一字。上阕四句，从第二句起用三仄韵；下阕五句，亦从第二句起用四仄韵。《词律》认为，上阕第二句第一字宜用去声，“作平则不起调”。但亦有作平起调者。又有《点樱桃》《十八香》《南浦月》《沙头雨》《寻瑶草》《万年春》等异名。
绝顶亭：在吴兴西北弁山峰顶。
缥缈：隐隐约约，亦因其高而之似可见似不可见，应题目中的“小亭”。
危亭：《说文》：“危，高而惧也。”此言亭之高，应题目的“绝顶”，绝顶亭就是因所位置之高而命名。
烟浪：烟云如浪，即云海。
天涯想：指恢复中原万里河山的梦想。
衰翁：衰老之人。', '小亭在高耸入云的山峰，隐隐约约浮现着。在千峰上独自叙述胸意，看那万里云烟如浪花般滚来，我与谁共同欣赏呢？
人已经老了，但情怀仍在。虽然思虑着万里山河，但也只能无奈的惆怅。少年啊，要胸怀豪情万丈，莫要学我这个老头子。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74cb34a8757d5a0d9e4c", "shortContent": "宋高宗绍兴五年乙卯（1135），叶梦得登上他所居住的吴兴西北卞山（一称弁山）绝顶亭。绝顶亭位于卞山南山之巅，为叶梦得所筑。亭基将建成，他即离吴兴出任江东安抚大使兼知建康府，兼寿春等六州宣抚使，时在绍兴元年。此时则已去任归居卞山，登此亭，心有所感，写了这首词。\n“缥缈危亭”，一起径直点题。危亭，《说文》：“危，在高而惧也。”此言亭之高，应题目的“绝顶”，绝顶亭就是因所在位置之高而命名。缥缈，隐隐约约...", "authors": ["陈长明", "艾治平"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5d003048e64fbd9bd78", "shortContent": "宋高宗绍兴五年乙卯（1135），叶梦得登上他所居住的吴兴西北卞山（一称弁山）绝顶亭。绝顶亭位于卞山南山之巅，为叶梦得所筑。亭基将建成，他即离吴兴出任江东安抚大使兼知建康府，兼寿春等六州宣抚使，时在绍兴元年。此时则已去任归居卞山，登此亭，心有所感，写了这首词。\n“缥缈危亭”，一起径直点题。危亭，《说文》：“危，在高而惧也。”此言亭之高，应题目的“绝顶”，绝顶亭就是因所在位置之高而命名。缥缈，隐隐约约...", "authors": ["陈长明", "艾治平"], "pressName": "上海辞书出版社"}]', NULL, 'indent', 1413131019, '57b5b1236be3ff006a154d53', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10364, '鹤冲天', NULL, 641, 225, 6, 1, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/view/2790173.htm', '', '黄金榜上，偶失龙头望。明代暂遗贤，如何向？未遂风云便，争不恣狂荡。何须论得丧？才子词人，自是白衣卿相。
烟花巷陌，依约丹青屏障。幸有意中人，堪寻访。且恁偎红倚翠，风流事，平生畅。青春都一饷。忍把浮名，换了浅斟低唱！', '《鹤冲天·黄金榜上》是宋代词人柳耆卿早期的作品。是柳耆卿进士科考落第之后的一纸「牢骚言」，表现出作者身世漂零之感，又反映出对妓女们的同情以及蔑视功名、鄙薄卿相的倾向。全词直抒胸臆，语言自然流畅，平白如话，读来朗朗上口。', '鹤冲天：词牌名。调见柳耆卿《乐章集》。双调八十四字，仄韵格。另有词牌《喜迁莺》、《风光好》的别名也叫鹤冲天，「黄金榜上」词注「正宫」。
黄金榜：指录取进士的金字题名榜。
龙头：旧时称状元为龙头。
明代：圣明的时代。一作「千古」。
遗贤：抛弃了贤能之士，指自己为仕途所弃。
如何向：向何处。
风云：际会风云，指得到好的遭遇。
争不：怎不。
恣：放纵，随心所欲。
得丧：得失。
白衣卿相：指自己才华出众，虽不入仕途，也有卿相一般尊贵。白衣，古代未仕之士著白衣。
烟花：指妓女。
巷陌：指街巷。
丹青屏障：彩绘的屏风。丹青，绘画的颜料，这里借指画。
堪：能，可以。
恁：如此。偎红倚翠：指狎妓。宋·陶穀《清异录·释族》载，南唐后主李煜微行娼家，自题为「浅斟低唱，偎红倚翠大师，鸳鸯寺主」。
平生：一生。
饷：片刻，极言靑年时期的短暂。
忍：忍心，狠心。
浮名：指功名。', '在金字题名的榜上，我只不过是偶然失去取得状元的机会。即使在政治清明的时代，君王也会一时错失贤能之才，我今后该怎么办呢？既然没有得到好的机遇，为什么不随心所欲地游乐呢！何必为功名患得患失？做一个风流才子为歌姬谱写词章，即使身着白衣，也不亚于公卿将相。
在歌姬居住的街巷里，有摆放着丹青画屏的绣房。幸运的是那里住着我的意中人，值得我细细地追求寻访。与她们依偎，享受这风流的生活，才是我平生最大的欢乐。青春不过是片刻时间，我宁愿把功名，换成手中浅浅的一杯酒和耳畔低徊婉转的歌唱。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74a003572034f659624d", "shortContent": "这首词是柳永参与进士科考落第之后，抒发牢骚感慨之作，它表现了作者的思想性格，关系到作者的生活道路，是一篇重要的作品。南宋人吴曾的《能改斋漫录》卷十六里有一则记载，与这首词的关系最为直接，略云：仁宗留意儒雅，而柳永好为淫冶讴歌之曲，传播四方，尝有《鹤冲天》词云云，及临轩放榜，特落之，曰：“且去浅斟低唱，何要浮名！”其写作背景大致是：初考进士落第，填《鹤冲天》词以抒不平，为仁宗闻知；后再次应试，本已中...", "authors": ["王双启"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a80ce818559d063ad9", "shortContent": "这首词是柳永参与进士科考落第之后，抒发牢骚感慨之作，它表现了作者的思想性格，关系到作者的生活道路，是一篇重要的作品。南宋人吴曾的《能改斋漫录》卷十六里有一则记载，与这首词的关系最为直接，略云：仁宗留意儒雅，而柳永好为淫冶讴歌之曲，传播四方，尝有《鹤冲天》词云云，及临轩放榜，特落之，曰：“且去浅斟低唱，何要浮名！”其写作背景大致是：初考进士落第，填《鹤冲天》词以抒不平，为仁宗闻知；后再次应试，本已中...", "authors": ["王双启"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252ccce4d48ba496d87", "shortContent": "这首词是柳永参与进士科考落第之后，抒发牢骚感慨之作，它表现了作者的思想性格，关系到作者的生活道路，是一篇重要的作品。南宋人吴曾的《能改斋漫录》卷十六里有一则记载，与这首词的关系最为直接，略云：仁宗留意儒雅，而柳永好为淫冶讴歌之曲，传播四方，尝有《鹤冲天》词云云，及临轩放榜，特落之，曰：“且去浅斟低唱，何要浮名！”其写作背景大致是：初考进士落第，填《鹤冲天》词以抒不平，为仁宗闻知；后再次应试，本已中...", "authors": ["王双启"], "pressName": "上海辞书出版社"}, {"bookId": "645d125c7af6de1647100d8a", "bookTitle": "柳永词鉴赏辞典", "articleId": "646d9009902ee364cc82bb10", "shortContent": "这首词是柳永参与进士科考落第之后，抒发牢骚感慨之作，它表现了作者的思想性格，关系到作者的生活道路，是一篇重要的作品。南宋人吴曾的《能改斋漫录》卷十六里有一则记载，与这首词的关系最为直接，略云：仁宗留意儒雅，而柳永好为淫冶讴歌之曲，传播四方，尝有《鹤冲天》词云云，及临轩放榜，特落之，曰：“且去浅斟低唱，何要浮名！”其写作背景大致是：初考进士落第，填《鹤冲天》词以抒不平，为仁宗闻知；后再次应试，本已中...", "authors": ["王双启"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413197103, '57aeff68a633bd0057f7d406', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10365, '望海潮', NULL, 708, 225, 5, 5, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/view/281211.htm', '', '东南形胜，三吴都会，钱塘自古繁华。烟柳画桥，风帘翠幕，参差十万人家。云树绕堤沙，怒涛卷霜雪，天堑无涯。市列珠玑，户盈罗绮，竞豪奢。
重湖叠巘清嘉，有三秋桂子，十里荷花。羌管弄晴，菱歌泛夜，嬉嬉钓叟莲娃。千骑拥高牙，乘醉听箫鼓，吟赏烟霞。异日图将好景，归去凤池夸。', '此词主要描写杭州的富庶与美丽。上阕描写杭州的自然风光和都市的繁华，下阕写西湖，展现杭州人民和平宁静的生活景象。全词以点带面，明暗交叉，铺叙晓畅，形容得体，一反柳永惯常的风格，以大开大阖、波澜起伏的笔法，浓墨重彩地铺叙展现了杭州的繁荣、壮丽景象。此词慢声长调和所抒之情起伏相应，音律协调，情致婉转，是柳永的一首传世佳作。', '三吴：（说法不一）即吴兴（今浙江省湖州市）、吴郡（今江苏省苏州市）、会稽（今浙江省绍兴市）三郡，在这里泛指今江苏南部和浙江的部分地区。
钱塘：即今浙江杭州，古时候的吴国的一个郡。
烟柳：雾气笼罩着的柳树。
画桥：装饰华美的桥。
风帘：挡风用的帘子。
翠幕：青绿色的帷幕。
参差：参音此跟反，差音此衣反。
近似；高下不齐貌。
云树：树木如云，极言其多。
怒涛卷霜雪：又高又急的潮头冲过来，浪花像霜雪在滚动。
天堑：天然沟壑，人间险阻。一般指长江，这里借指钱塘江。
珠玑（jī）：珠是珍珠，玑是一种不圆的珠子。这里泛指珍贵的商品。
重（chóng）湖：以白堤为界，西湖分为里湖和外湖，所以也叫重湖。
叠巘（yǎn）：层层叠叠的山峦。此指西湖周围的山。巘，小山峰。
清嘉：清秀佳丽。
三秋：秋季，亦指秋季第三月，即农历九月。王勃《滕王阁序》有「时维九月，序属三秋」。柳永《望海潮》有「三秋桂子，十里荷花」。
羌管（qiāng）：即羌笛，羌族之簧管乐器。这里泛指乐器。
弄：吹奏。
菱歌泛夜：采菱夜归的船上一片歌声。菱，菱角；泛，漂流。
嬉嬉钓叟莲娃：钓鱼的老叟和采莲的少女都很愉快。
千骑（jì）拥高牙：这里指孙何外出时仪仗很威风，随从人员很多。高牙，高矗之牙旗；牙旗，将军之旌，竿上以象牙饰之，故云牙旗；这里指高官孙何。
吟赏烟霞：歌咏和观赏湖光山色。烟霞，此指山水林泉等自然景色。
异日图将好景：有朝一日把这番景致描绘出来。异日，他日。图，描绘。将，用在动词后的语气助词。
凤池：全称凤凰池，原指皇宫禁苑中的池沼。此处是对中书省的美称，代指朝廷。', '杭州地理位置重要，风景优美，是三吴的都会。这里自古以来就十分繁华。如烟的柳树、彩绘的桥梁，挡风的帘子、翠绿的帐幕，楼阁高高低低，大约有十万户人家。高耸入云的大树环绕着钱塘江沙堤，澎湃的潮水卷起霜雪一样白的浪花，宽广的江面一望无涯。市场上陈列着琳琅满目的珠玉珍宝，家家户户都存满了绫罗绸缎，争相比奢华。
里湖、外湖与重重叠叠的山岭非常清秀美丽。秋天桂花飘香，夏季十里荷花。晴天欢快地吹奏羌笛，夜晚划船采菱唱歌，钓鱼的老翁、采莲的姑娘都嬉笑颜开。千名骑兵簇拥着巡察归来的长官。在微醺中听着箫鼓管弦，吟诗作词，赞赏着美丽的水色山光。他日把这美好的景致描绘出来，回京升官时向朝中的人们夸耀。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749f03048e64fbd892e2", "shortContent": "在词史上，一般把柳永推为婉约派的正宗，有时与秦观合称“秦柳”，有时与周邦彦合称“周柳”，因为他“长于纤艳之词，然近俚俗”（《花庵词选》），“所作旖旎近情，使人易入”（《四库提要》）。就其大部分作品而言，固属如此，然亦有不同风格。在这首《望海潮》中，词人以大开大阖、直起直落的笔法，描写杭州的繁荣景象，仿佛在读者面前展开一幅宏伟壮丽的历史画卷。因此李之仪在论及词体发展时说他“铺叙展衍，备足无余，形容盛...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a75914587d02f58fbf", "shortContent": "在词史上，一般把柳永推为婉约派的正宗，有时与秦观合称“秦柳”，有时与周邦彦合称“周柳”，因为他“长于纤艳之词，然近俚俗”（《花庵词选》），“所作旖旎近情，使人易入”（《四库提要》）。就其大部分作品而言，固属如此，然亦有不同风格。在这首《望海潮》中，词人以大开大阖、直起直落的笔法，描写杭州的繁荣景象，仿佛在读者面前展开一幅宏伟壮丽的历史画卷。因此李之仪在论及词体发展时说他“铺叙展衍，备足无余，形容盛...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252ccce4d48ba496d80", "shortContent": "在词史上，一般把柳永推为婉约派的正宗，有时与秦观合称“秦柳”，有时与周邦彦合称“周柳”，因为他“长于纤艳之词，然近俚俗”（《花庵词选》），“所作旖旎近情，使人易入”（《四库提要》）。就其大部分作品而言，固属如此，然亦有不同风格。在这首《望海潮》中，词人以大开大阖、直起直落的笔法，描写杭州的繁荣景象，仿佛在读者面前展开一幅宏伟壮丽的历史画卷。因此李之仪在论及词体发展时说他“铺叙展衍，备足无余，形容盛...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "645d125c7af6de1647100d8a", "bookTitle": "柳永词鉴赏辞典", "articleId": "646d8f76e49f46528acae4fd", "shortContent": "在词史上，一般把柳永推为婉约派的正宗，有时与秦观合称“秦柳”，有时与周邦彦合称“周柳”，因为他“长于纤艳之词，然近俚俗”（《花庵词选》），“所作旖旎近情，使人易入”（《四库提要》）。就其大部分作品而言，固属如此，然亦有不同风格。在这首《望海潮》中，词人以大开大阖、直起直落的笔法，描写杭州的繁荣景象，仿佛在读者面前展开一幅宏伟壮丽的历史画卷。因此李之仪在论及词体发展时说他“铺叙展衍，备足无余，形容盛...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f32c3e49f46528ad251eb", "shortContent": "在词史上，一般把柳永推为婉约派的正宗，有时与秦观合称“秦柳”，有时与周邦彦合称“周柳”，因为他“长于纤艳之词，然近俚俗”（《花庵词选》），“所作旖旎近情，使人易入”（《四库提要》）。就其大部分作品而言，固属如此，然亦有不同风格。在这首《望海潮》中，词人以大开大阖、直起直落的笔法，描写杭州的繁荣景象，仿佛在读者面前展开一幅宏伟壮丽的历史画卷。因此李之仪在论及词体发展时说他“铺叙展衍，备足无余，形容盛...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}]', '宋·罗鹤林《鹤林玉露·卷十三》：孙何帅钱塘，柳耆卿作《望海潮》词赠之云「东南形胜」云云。此词流播，金主亮闻歌，欣然有慕于「三秋桂子，十里荷花」，遂起投鞭渡江之志。近时谢处厚诗云：「谁把杭州曲子讴？荷花十里桂三秋。那知卉木无情物，牵动长江万里愁！」余谓此词虽牵动长江之愁，然卒为金主送死之媒，未足恨也。至于荷艳桂香，妆点湖山之清丽，使士夫流连于歌舞嬉游之乐，遂忘中原，是则深可恨耳！
宋·陈直斋《直斋书录解题》：承平气象，形容曲尽。
宋·吴自牧《梦粱录卷·十九》：柳永咏钱塘词曰「参差十万人家」，此元丰前语也。自高庙车驾自建康幸杭驻跸，几近二百馀年，户口蕃息，近百万馀家。杭城之外城，南西东北，各数十里，人烟生聚，民物阜蕃，市井坊陌，铺席骈盛，数日经行不尽，各可比外路一州郡，足见杭城繁盛耳。', 'indent', 1413197231, '57b318228ac247005f2223db', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10394, '长歌行', NULL, 1397, 112, 5, 12, '两汉乐府', NULL, 18119, '5831d697a22b9d006b8ec08c', '汉', 'shi', '诗', 'http://baike.baidu.com/subview/74268/4965849.htm', '', '青青园中葵，朝露待日晞。
阳春布德泽，万物生光辉。
常恐秋节至，焜黄华叶衰。
百川东到海，何时复西归？
少壮不努力，老大徒伤悲！', '这是一首汉族古典诗歌，属于汉乐府诗，是劝诫世人惜时奋进的名篇。此诗从整体构思看，主要意思是说时节变换得很快，光阴一去不返，因而劝人要珍惜青年时代，发奋努力，使自己有所作为。全诗以景寄情，由情入理，将“少壮不努力，老大徒伤悲”的人生哲理，寄寓于朝露易干、秋来叶落、百川东去等鲜明形象中，借助朝露易晞、花叶秋落、流水东去不归来，发生了时光易逝、生命短暂的浩叹，鼓励人们紧紧抓住随时间飞逝的生命，奋发努力趁少壮年华有所作为。其情感基调是积极向上的。其主旨体现在结尾两句，但诗人的思想又不是简单的表述出来，而是从现实世界中撷取出富有美感的具体形象，寓教于审美之中。', '长歌行：汉乐府曲题。这首诗选自《乐府诗集·卷三十》，属相和歌辞中的平调曲。
葵：蔬菜名，中国古代重要蔬菜之一。《诗经·豳风·七月》：“七月亨葵及菽。”李时珍《本草纲目》说“葵菜古人种为常食，今之种者颇鲜。有紫茎、白茎二种，以白茎为胜。大叶小花，花紫黄色，其最小者名鸭脚葵。其实大如指顶，皮薄而扁，实内子轻虚如榆荚仁。”此诗“青青园中葵”即指此。
朝露：清晨的露水。
晞：天亮，引申为阳光照耀。
“阳春”句：阳是温和。阳春是露水和阳光都充足的时候，露水和阳光都是植物所需要的，都是大自然的恩惠，即所谓的“德泽”。布，布施、给予；德泽，恩惠。
秋节：秋季。
焜黄：形容草木凋落枯黄的样子。
华（huā）：同“花”。
衰：一说读“cuī”，因为古时候没有“shuāi”这个音；一说读shuāi，根据语文出版社出版的《古代汉语》，除了普通话的规范发音之外，任何其他的朗读法都是不可取的。
百川：大河流。
少壮：年轻力壮，指青少年时代。
老大：指年老了，老年。
徒：白白地。', '园中的葵菜都郁郁葱葱，晶莹的朝露阳光下飞升。
春天把希望洒满了大地，万物都呈现出一派繁荣。
常恐那肃杀的秋天来到，树叶儿黄落百草也凋零。
百川奔腾着东流到大海，何时才能重新返回西境？
少年人如果不及时努力，到老来只能是悔恨一生。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecc942cee9a0c24eda875", "shortContent": "汉代《长歌行》古辞共三首，在宋人郭茂倩的《乐府诗集》中列入“相和歌辞”平调曲，并把后二首合成一篇（其实它们是完全不相干的两首诗，严羽《沧浪诗话》已指出后者应是两首）。这里要讲的是三首中的第一首，它最早见于萧统的《文选》。这首诗的主题思想很明确，就是篇末两句：“少壮不努力，老大徒伤悲。”由于唐吴兢《乐府古题要解》释此诗说：“言荣华不久，当努力为乐，无至老大乃伤悲也。”后世便把这样一首劝人珍惜青春，应...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646e0d7eb6a81d0c531b6608", "shortContent": "这首诗有一个严肃而健康的主题，它的思想内容是对不知珍惜青春韶光的人进行一次严厉的当头棒喝，其发人深省的程度是惊心动魄的。但就全诗而论，读起来却给人以循循善诱、浑朴天成的感受，丝毫不觉得生硬牵强。这正由于原诗作者是以形象思维为比喻来打动人，而不是用抽象概念当教条来教训人的缘故。\n秋天一到，植物的华叶生长得再茂盛秀美，也终于逃不脱衰谢凋残的命运。然而正如早于此诗的一首民间挽歌所说：“薤上露，何易晞！露...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f6067b6a81d0c53210a3e", "shortContent": "汉代《长歌行》古辞共三首，在宋人郭茂倩的《乐府诗集》中列入“相和 歌辞”平调曲，并把后两首合成一篇(其实它们是完全不相干的两首诗，严 羽《沧浪诗话》已指出后者应是两首)。这里要讲的是三首中的第一首，它 最早见于萧统的《文选》。这首诗的主题思想很明确，就是篇末两句:“少 壮不努力，老大徒伤悲。”由于唐吴兢《乐府古题要解》释此诗说:“言荣华 不久，当努力为乐，无至老大乃伤悲也。”后世便把这样一首劝人珍...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}]', '', 'center', 1423178618, '57b95897d342d3005aca2f4f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10366, '八声甘州 · 寄参寥子，时在巽亭', NULL, 288, 3406, 3, 4, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/74039.htm', '', '有情风万里卷潮来，无情送潮归。问钱塘江上，西兴浦口，几度斜晖？不用思量今古，俯仰昔人非。谁似东坡老，白首忘机。
记取西湖西畔，正暮山好处，空翠烟霏。算诗人相得，如我与君稀。约他年，东还海道，愿谢公、雅志莫相违。西州路，不应回首，为我沾衣。', '此词作于元祐六年（西元一〇九一年）苏东坡由杭州太守被召为翰林学士承旨时，是作者离杭时送给参寥的。参寥是僧道潜的字，以精深的道义和清新的文笔为东坡所推崇，与东坡过从甚密，结为莫逆之交。东坡贬谪黄州时，参寥不远千里赶去，追随他数年。这首赠给参寥的词，表现了二人深厚的友情，同时也抒写出世的玄想，表现出巨大的人生空漠之感。整首词达观中充满豪气，向往出世却又执着于友情，读来毫无颓唐、消极之感，但觉气势恢宏，荡气回肠。
上阕「有情风万里卷潮来，无情送潮归」，二句以钱塘潮水比喻人的欢聚与离别，气势非凡。虽然是写「卷潮来」和「送潮归」两个方面，但却是以「有情」始，以「无情」终，其归根到底仍是「无情」，接着以「问」字领起下文，「钱塘江上，西兴浦口，几度斜辉？」仍是表达了愁苦的心情。最後几句则宕开一笔，纵阅古今之变，通过对历史上机心倾轧的否定而自明心迹：「谁似东坡老，白首忘机。」使精神得以超脱和自由。
下阕则开始追忆往事：「记取西湖西畔，正暮山好处，空翠烟霏。算诗人相得，如我与君稀」将旧日漫游的地点、季节、景色以及二人相知相得的友谊一一写出。後几句则是借用谢安、羊昙的故事，来表明自己的志向，「愿谢公、雅志莫相违」，并殷殷嘱托友人不要为自己担忧：「西州路，不应回首，为我沾衣。」
此词以平实的语言，抒写深厚的情意，气势雄放，意境浑然。郑瘦碧《手披〈东坡乐府〉》说，此词「雲锦成章，天衣无缝」，「从至情中流出，不假熨贴之工」，这一评语正道出了此词的特色。词人那超旷的心态，那交织着人生矛盾的悲慨和发扬蹈厉的豪情，给读者以强烈的震撼和深刻的启迪。', '八声甘州：词牌名、曲牌名，简称《甘州》。唐玄宗时教坊大曲有《甘州》，杂曲有《甘州子》，属唐边塞曲，因以边塞地甘州为名。《西域记》云：「龟茲（QiūCí）国土制曲，《伊州》、《甘州》、《梁州》等曲翻入中国。」《伊州》、《甘州》、《梁州》诸曲，音节慷慨悲壮。据宋·王颐堂《碧鸡漫志·卷三·〈甘州〉》「《甘州》，世不见，今『仙吕调』有曲破，有八声慢，有令，而『中吕调』有《象八声甘州》，他宫调不见也。凡大曲就本宫调制引、序、慢、近、令，盖度曲者常态。若《象八声甘州》，即是用其法于『中吕调』，此例甚广。伪蜀毛平圭有《甘州遍》，顾夐（Xiòng）、李德润有《倒排甘州》，顾夐又有《甘州子》，皆不著宫调。」按此调前後阕八韵，故名「八声」，乃慢词也，与《甘州遍》之曲破，《甘州子》之令词不同。今所传《八声甘州》，《乐章集》亦注「仙吕调」。周草窗词名《甘州》。张玉田词因柳词有「对萧萧暮雨洒江天」句，更名《萧萧雨》。白仁甫词名《宴瑶池》。以柳耆卿词为正体，双调，九十七字，前阕四十六字，後阕五十一字，前後阕各九句四平韵。亦有在起句增一韵的。前阕起句、第三句，後阕第二句、第四句，多用领句字。另有变格，九十五字、九十六字、九十八字体。
「寄参寥子，时在巽亭」：元延祐本、明吴讷钞本、《苏长公二妙集》本、毛本作「寄参寥子」。又《苕溪渔隐丛话·後集卷三十九》谓本篇石刻後，东坡自题云：「元祐六年三月六日。」
参寥子：龙榆生笺引《东坡诗集》施注：「僧道潜字参寥，于潜人。能文章，尤喜为诗，尝有句云：『风蒲猎猎弄轻柔，欲立蜻蜓不自由。五月临平山下路，藕花无数满汀洲。』过东坡于彭城，甚爱之，以书告文与可，谓其诗句清绝，与林逋上下，而通了道义，见之令人萧然。苏黄门每称其体制绝类储光羲，非近时诗僧所能及。坡守吴兴，会于松江。坡既谪居，不远二千里，相从于齐安。留期年，遇移汝海，同游庐山，有《次韵留别》诗。坡守钱塘，卜智果精舍居之，入院分韵赋诗，又作《参寥泉铭》。坡南迁，遂欲转海访之，以书力戒勿萌此意，自揣馀生必须相见。当路亦捃（jùn）其诗语，谓有刺讥，得罪，反初服。建中靖国初，曾子开在翰苑，言其非罪，诏复矱（yuē）发。」又引《咸淳临安志》：「参寥本姓何。幼不茹荤，以童子诵《法华经》为比邱，于内外典无所不窥。崇宁末示寂，赐号妙聪大师。」
钱塘、西兴：傅子立注：「钱塘、西兴，并吴中之绝景。」龙榆生笺：「《唐书·地理志》：『杭州馀杭郡，县钱塘。』《钱塘记》：『大海在县东一里（符）[许]，郡议曹华信家议立此塘，以防海水。始开募，有能致一斛土者，即与钱一千。旬月之间，来者云集。塘未成而不复取，于是载土石者皆弃而去，塘以之成。故改名钱塘焉。』《〈水经〉注》：『浙江又东北流至钱塘县，谷水入焉。』《一统志》：『秦置钱唐县，後汉省入馀杭郡。唐改「唐」为「塘」，为杭州治。五代及宋初因之。』《会稽志》：『西陵在萧山县，吴越改为西兴。郎士元《送李遂之越》诗：「西兴待潮信，落日满孤舟。」』《清一统志》：『西陵城在浙江萧山县西十二里。本名西陵，为吴越通津。』」
俯仰昔人非：傅子立注：「晋王逸少《兰亭记》：『向之所欣，俯仰之间，已为陈迹。』」刘尚荣按：「文见《晋书·卷八十·王羲之传》。」
暮山：元延祐刻本原阙「暮」字，四印斋翻刻本补为「春」字，皆不足为据。
谢公雅志：傅子立注：「晋谢安石虽受朝寄，然而东山之志，始末不渝。及镇新城，尽室而行，造泛海之装，欲须经略粗定，自江道还东。雅志不就，遂疾。有诏还都。」刘尚荣按：「详见《晋书·卷七十九·谢安传》。」龙榆生笺引《晋书·卷七十九·谢安传》：「安虽受朝寄，然东山之志始末不渝，每形于言色。及镇新城，尽室而行，造泛海之装，欲须经略粗定，自江道还东。雅志未就，遂遇疾笃。上疏请量宜旋旆，……诏遣侍中慰劳，遂还都。闻当舆入西州门，自以本志不遂，深自慨失，因怅然谓所亲曰：『昔桓温在时，吾常惧不全。忽梦乘温舆行十六里，见一白鸡而止。乘温舆者，代其位也。十六里，止今十六年矣。白鸡主酉，今太岁在酉，吾病殆不起乎！』乃上疏逊位，诏遣侍中、尚书喻旨。先是，安发石头，金鼓忽破，又语未尝谬，而忽一误，众亦怪异之。寻薨，时年六十六。」
西州路：傅子立注：「晋羊昙为谢安所爱重。安薨，昙辍乐弥年，行不由西州路『由』，原误作『游』；『西州』，原误作『州西』。据《晋书·谢安传》乙正。尝因石头大醉，扶路唱乐，不觉至州门。左右曰：『此西州门也。』昙悲感不已，因恸哭而去。『西州』者，《晋志》：『扬州廨，王敦所创，开东南西三门，俗称之西州。今润州也。』」刘尚荣按：「昙事详《晋书·卷七十九·谢安传》。《晋志》无此条。又《元和郡县志·卷二十五·〈江南道·润州·上元县〉》：『上元县，东北至州一百八十里。本金陵地，……（武德）九年，为白下县，属润州。贞观九年，又改白下为江宁。至德二年，于县置江宁郡，乾元元年改为升州，并置浙西节度使。上元二年，废升州，仍改江宁为上元县。……扬州故理，在县东百步。……刘繇为扬州刺史，始移理曲阿。吴长沙桓王孙策定江东，置扬州于建业，其州廨王敦及王道所创也，後会稽王道子于东府城领丹阳郡故城，在县东南五里。东府城，在县东七里。其地西则简文帝为会稽王里邸第，东则丞相会稽王道子府。谢安薨，道子代领扬州，仍前府，故称为东府，而谓扬州廨为西州。』」龙榆生笺引《晋书·卷七十九·谢安传》：「（安）还都，闻当舆入西州门，自以本志不遂，深自慨失。……羊昙者，太山人，知名士也，为安所爱重。安薨後，辍乐弥年，行不由西州路。尝游石头大醉，扶路唱乐，不觉至州门，左右白曰：『此西州门。』昙悲感不已，以马策扣扉，诵曹子建诗曰：「生存华屋处，零落归山丘。」恸哭而去。」
沾衣：傅注本原作「泪沾衣」，据元延祐本、明吴讷钞本、《苏长公二妙集》、毛本删「泪」字。', '有情风从万里之外卷潮扑来，无情时又送潮返回。请问在钱塘江上或西兴渡口，我俩共赏过几次夕阳斜晖？用不着仔细思量古今的变迁，一俯一仰的工夫，早已物是人非。谁像我东坡老。白首之年，淡忘了仕进的机会。
记住西湖的西岸，春日最美的山隈，就是那空明的翠微，如烟的雲霏。算起来诗人中相处得宜。如我与您这样的友情，确实稀微，弥足珍贵。约定日後，像东晋宰相谢安那样，沿着直通大海的长江航道，向东引退、回归。别让这一夙愿与未来事实彼此违背。不应在西州路上回首恸哭，为了我而沾湿衣襟，洒落泪水。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b234a8757d5a0d9dd8", "shortContent": "这首词写作的时间、地点，多有异说：一、作于宋哲宗绍圣四年（1097），时苏轼谪居儋州（今属海南省），见清人王文诰《苏诗编注集成总案》卷四十一；二、作于哲宗元祐六年（1091），时苏轼由杭州知州召为翰林学士承旨，将离杭州赴汴京，见朱祖谋《东坡乐府编年本》，后龙榆生《东坡乐府笺》、曹树铭《苏东坡词》从之；三、清人黄蓼园《蓼园词选》谓作于杭州任内：“此词不过叹其久于杭州，未蒙内召耳”；四、建国后又有两说...", "authors": ["王水照"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b95914587d02f58ff4", "shortContent": "这首词写作的时间、地点，多有异说：一、作于宋哲宗绍圣四年（1097），时苏轼谪居儋州（今海南岛儋县），见清人王文诰《苏诗编注集成总案》卷四十一；二、作于哲宗元祐六年（1091），时苏轼由杭州知州召为翰林学士承旨，将离杭州赴汴京，见朱祖谋《东坡乐府编年本》，后龙榆生《东坡乐府笺》、曹树铭《苏东坡词》从之；三、清人黄蓼园《蓼园词选》谓作于杭州任内：“此词不过叹其久于杭州，未蒙内召耳”；四、新中国成立后...", "authors": ["王水照"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7de6f69b71e93f60b7", "shortContent": "《苕溪渔隐丛话》后集卷三十九云：“东坡别参寥长短句云（词略）。其词石刻后东坡自题云：‘元祐六年三月六日。’余以东坡先生年谱考之，元祐四年知杭州，六年召为翰林学士承旨，则长短句盖此时作也。”词为苏轼离杭赴京时别参寥之作，朱本、孔《谱》、薛本、邹王本从之。此词另有三种编年：一、王文诰《苏诗总案》编绍圣四年（1097），时苏轼谪居儋州；二、陈迩冬《苏轼词选》认为作于元祐六年去杭入京之后；三、王仲镛《读苏...", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "6468373430675327e19787fa", "shortContent": "这首词写作的时间、地点，多有异说：一、作于宋哲宗绍圣四年（1097），时苏轼谪居儋州（今属海南岛儋县），见清人王文诰《苏诗编注集成总案》卷四十一；二、作于哲宗元祐六年（1091），时苏轼由杭州知州召为翰林学士承旨，将离杭州赴汴京，见朱祖谋《东坡乐府编年本》，后龙榆生《东坡乐府笺》、曹树铭《苏东坡词》从之；三、清人黄蓼园《蓼园词选》谓作于杭州任内：“此词不过叹其久于杭州，未蒙内召耳”；四、建国后又有...", "authors": ["王水照"], "pressName": "上海辞书出版社"}]', '清·郑瘦碧《手批〈东坡乐府〉》：突兀雪山，卷地而来，真似钱塘江上看潮时，添得此老胸中数万甲兵，是何气象雄且杰！妙在无一字豪宕，无一语险怪，又出以闲逸感喟之情，所谓骨重神寒，不食人间烟火气者。词境至此，观止矣！清·鄭瘦碧《手批〈東坡樂府〉》：雲锦成章，天衣无缝，是作从至情流出，不假熨帖之工。', 'indent', 1423177299, '57b8b7571532bc005b9a070a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10367, '定风波 · 次高左藏使君韵', NULL, 94, 2398, 2, 2, '黄庭坚', NULL, 10086, '57b9594b8ac2470062e29b7d', '宋', 'ci', '词', 'http://baike.baidu.com/view/666652.htm', '', '万里黔中一漏天，屋居终日似乘船。及至重阳天也霁，催醉，鬼门关外蜀江前。
莫笑老翁犹气岸，君看，几人黄菊上华颠？戏马台南追两谢，驰射，风流犹拍古人肩。', '此词是宋代文学家黄庭坚贬谪黔州期间创作的一首词。通过对重阳节的描述，抒发了一种老当益壮、穷且益坚的乐观奋发精神，显示了作者身处逆境而宠辱不惊的旷达胸襟。全词铸词造句新警生动，用典自然贴切，其豪迈之气动人心魄。', '左藏（cánɡ）：古代国库之一，以其在左方，故称左藏。
黔（qián）中：即黔州（今四川彭水）。
漏天：指阴雨连绵。
及至：表示等到某种情况出现；直至。
霁（jì）：雨雪之止也。
鬼门关：即石门关，今重庆市奉节县东，两山相夹如蜀门户。
老翁（wēng）：老年男子，含尊重意。
气岸：气度傲岸。
华颠：白头。
戏马台：一名掠马台，项羽所筑，今江苏徐州城南。晋安帝义熙十二年，刘裕北征，九月九日会僚属于此，赋诗为乐，谢瞻和谢灵运各赋《九日从宋公戏马台集送孔令》一首。两谢：即谢瞻和谢灵运。', '黔中阴雨连绵，仿佛天漏，遍地都是水，终日被困家中，犹如待在一艘破船上。久雨放晴，又逢重阳佳节，在蜀江之畔，畅饮狂欢。
不要取笑我，虽然年迈但气概仍在。请看，老翁头上插菊花者有几人呢？吟诗填词，堪比戏马台南赋诗的两谢。骑马射箭，纵横驰骋，英雄直追古时风流人物。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b77d0ac1145494bb9b", "shortContent": "此词为作者在黔州贬所的作品。唐置黔中郡，后改黔州，治所在今四川彭水，在宋时是边远险阻的处所。绍圣二年（1095）黄庭坚以修《神宗实录》不实的罪名，贬为涪州（今重庆市涪陵区）别驾，黔州安置，开始他生平最艰难困苦的一段生活。当时他的弟弟知命有诗云：“人鲊瓮中危万死，鬼门关外更千岑。问君底事向前去，要试平生铁石心。”（《戏答刘文学》）写出他在穷困险恶的处境中，不向命运屈服的博大胸怀。这种心境见于词体创作...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5bf03572034f65a8b54", "shortContent": "此词为作者在黔州贬所的作品。唐置黔中郡，后改黔州，治所在今四川彭水，在宋时是边远险阻的处所。绍圣二年（1095）黄庭坚以修《神宗实录》不实的罪名，贬为涪州（今四川涪陵）别驾，黔州安置，开始他生平最艰难困苦的一段生活。当时他的弟弟知命有诗云：“人鲊瓮中危万死，鬼门关外更千岑。问君底事向前去，要试平生铁石心”（《戏答刘文学》），写出他在穷困险恶的处境中，不向命运屈服的博大胸怀。这种心境见于词体创作，则...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f407f0b9738b369b0ff", "shortContent": "黄庭坚于宋哲宗绍圣元年（1094）冬贬涪州（今四川涪陵）别驾、黔州（今重庆彭水县）安置，这首词即黔州安置期间所作。\n\n上片写黔州的生活实景。黔州整日阴雨连绵，好像天漏了，到处是水，在家里也仿佛整天都困在破船上。到重阳节，又逢雨过天晴，喜上加喜，于是在蜀江畔放怀畅饮。词人强调是“鬼门关外蜀江前”，既说明了自己被贬险恶之地的处境，更是用自然环境来反衬自己不惧艰险、不畏打击的傲兀之气，由此自然引出下片的...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127031c305cf0801816ef6", "shortContent": "黄庭坚于宋哲宗绍圣元年（1094）冬贬涪州（今四川涪陵）别驾、黔州（今重庆彭水县）安置，这首词即黔州安置期间所作。\n\n上片写黔州的生活实景。黔州整日阴雨连绵，好像天漏了，到处是水，在家里也仿佛整天都困在破船上。到重阳节，又逢雨过天晴，喜上加喜，于是在蜀江畔放怀畅饮。词人强调是“鬼门关外蜀江前”，既说明了自己被贬险恶之地的处境，更是用自然环境来反衬自己不惧艰险、不畏打击的傲兀之气，由此自然引出下片的...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271ba73206168b2e02370", "shortContent": "黄庭坚于宋哲宗绍圣元年（1094）冬贬涪州（今四川涪陵）别驾、黔州（今重庆彭水县）安置，到元符二年（1099）又移戎州（今四川宜宾）安置，这首词即黔州安置期间所作。\n上片写黔州的生活实景。黔州整日阴雨连绵，好像天漏了，到处是水，在家里也仿佛整天都困在破船上。到重阳节，又逢雨过天晴，喜上加喜，于是在蜀江畔放怀畅饮。词人强调是“鬼门关外蜀江前”，既说明了自己被贬险恶之地的处境，更是用自然环境来反衬自己...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "645fb67ec0471b0062b8b5b0", "bookTitle": "黄庭坚诗文鉴赏辞典", "articleId": "6464b393c0471b0062cd4925", "shortContent": "此词为作者在黔州贬所的作品。唐置黔中郡，后改黔州，治所在今四川彭水，在宋时是边远险阻的处所。绍圣二年（1095）黄庭坚以修《神宗实录》不实的罪名，贬为涪州（今重庆市涪陵区）别驾，黔州安置，开始他生平最艰难困苦的一段生活。当时他的弟弟知命有诗云：“人鲊瓮中危万死，鬼门关外更千岑。问君底事向前去，要试平生铁石心。”（《戏答刘文学》）写出他在穷困险恶的处境中，不向命运屈服的博大胸怀。这种心境见于词体创作...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '王十朋《东坡诗集注》：戏马台在徐州彭城县，项羽所筑。宋武建第舍，重九日，引宾客登台赋诗。', 'indent', 1423177349, '57b2702d165abd005433ebd4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10368, '捣练子', NULL, 444, 87, 2, 2, '李煜', NULL, 10017, '57b8af7c5bbb50005b770fdd', '五代十国', 'ci', '词', 'http://baike.baidu.com/view/652771.htm', '', '深院静，小庭空，断续寒砧断续风。无奈夜长人不寐，数声和月到帘栊。', '这首小令通过描绘深院小庭夜深人静对断续传来的风声、捣衣声，以及映照着帘栊的月色，刻意营造出一种幽怨欲绝的意境，让人不觉沉浸其中，去感受长夜不寐者的悠悠情怀。', '这是一首写别后相思的本义词。此词调名于《尊前集》、《花草粹编》、《花间集补》、《全唐诗》等本中均作《捣练子》，为单调。《花草粹编》中有题作“闻砧”，《续选草堂诗余》、《古今诗余醉》、《古今词统》等本中题作“秋闺”，《词的》中题作“本意”。又《历代诗余》中于调名下有注曰：“一名《深院月》，又名《深夜月》。李煜秋闺词有‘断续寒砧断续风’之句，遂以‘捣练’名其调。”明杨慎《词品》亦云：“李后主词，词名《捣练子》，即咏捣练，乃唐词本体也。”自李煜此调始见于此词。
寒砧（zhēn）：砧，捣衣石，这里指捣衣声。古时将生丝织成的绢用木杵在石上捣软制成熟绢，以便裁制衣服。寒砧，因夜深天寒，故称。这里指寒夜之中的捣衣声。唐代杜甫《秋兴》中有诗句云：“寒衣处处催刀尺，白帝城高急暮砧。”
无奈：《啸余谱》、《尊前集》、《南词新谱》中作“早是”。
不寐：《啸余谱》、《尊前集》、《南词新谱》中均作“不寝”。不寐，不能入睡。
数声：几声，这里指捣衣的声音。
和月：伴随着月光。
到：传到。
帘栊（lóng）：挂着竹帘的格子窗。栊：有横直格的窗子。', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74930ce818559d05070d", "shortContent": "这是一首本义词。白练是古代一种丝织品，其制作要经过在砧石上用木棒捶捣这道工序，而这工序一般都是由妇女操作的。这首词的词牌即因其内容以捣练为题材而得名。作者通过对一个失眠者夜听砧上捣练之声的描绘，写出了抒情主人公内心的焦躁烦恼。但作者却为这种忐忑不宁的心情安排了一个十分幽静寂寥、空虚冷漠的环境。头两句乍一看仿佛是重复的，后来汤显祖在《牡丹亭》里就写出“人立小庭深院”的句子，把“深院”和“小庭”基本上...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892e508c9c030fd725eb", "shortContent": "这是一首本义词。白练是古代一种丝织品，其制作要经过在砧石上用木棒捶捣这道工序，而这工序一般都是由妇女操作的。这首词的词牌即因其内容以捣练为题材而得名。作者通过对一个失眠者夜听砧上捣练之声的描绘，写出了抒情主人公内心的焦躁烦恼。但作者却为这种忐忑不宁的心情安排了一个十分幽静寂寥、空虚冷漠的环境。头两句乍一看仿佛是重复的，后来汤显祖在《牡丹亭》里就写出“人立小庭深院”的句子，把“深院”和“小庭”基本上...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126e097ccdb86c49f28ef7", "shortContent": "这是一首月夜怀人的词，月光的冷寂极好地衬托了思妇内心的凄苦和幽怨。捣练子令：即“捣练子”。《尊前集》、《花草粹编》、《全唐诗》均无“令”字。杨慎《词品》：“词名《捣练子》，即咏捣练。乃唐词本体也此词在《花草粹编》调下有题“闻砧”。盖咏捣练者。二十七字，单调。《草堂诗余续集》、《古今诗余醉》、《古今词统》调下有题“秋闺”。《词的》调下有题“本意”。\n此词或作冯延已作，见《尊前集》、《啸余谱》卷九（《...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126e147f0b9738b369af6c", "shortContent": "这首及下首《鹧鸪天》，清贺裳《皱水轩词诠》及清徐《词苑丛谈》认为是李煜所作，王仲闻《南唐二主词校订》从文辞角度考证，认为这两首词系伪作。今从王说。", "authors": [], "pressName": "崇文书局"}]', '明杨慎《词品》：李后主《捣练子》云：（略）。词名《捣练子》，即咏捣练，乃唐词本体也。
清陈廷焯《云韶集》卷一：古人以词名为题，他本增“秋阑”二字，殊属恶劣。
俞陛云《唐五代两宋词选释》：曲名《捣练子》，即以咏之。乃唐词本体。首二句言闻捣练之时，院静庭空，已写出幽悄之境。三句赋捣练。四五句由闻砧者说到砧声之远递。通首赋捣练，而独夜怀人情味，摇漾于寒砧断续之中，可谓极此题之能事。杨升庵谓田本以此曲为《鹧鸪天》之后半首，尚有上半首云：“塘水初澄似玉容，所思远在别离中，谁知九月初三夜，露似珍珠月似弓。”案《鹧鸪天》调，唐人罕填之。况塘水四旬，全与捣练无涉，升庵之说未确。但露珠月弓，传诵词苑，自是佳句。
王国维《南唐二主词》校勘记：“可怜九月初三夜，露似珍珠月似弓。”此乐天《暮江吟》后二句，见《白氏长庆集》卷十九。后主不应全袭之。且《鹧鸪天》下半阕，平仄亦与《捣练子》不合，显系明人赝作。
唐圭璋《屈原与李后主》：后主始无奋斗之志，后亦不思奋斗，平居贪欢作乐，国危则日夜戚伤。其《捣练子》云：“无奈夜长人不寐”，《相见欢》云：“无奈朝来寒雨晚来风”，朝朝暮暮，只觉无奈。
又唐圭璋《唐宋词简释》：此首闻砧而作，起两句，叙夜间庭院之寂静。“断续”句叙风送砧声，庭愈空，砧愈响。长夜迢迢，人自难眠，其中心之悲哀，亦可揣知。“无奈”二字，曲笔径转，贯下十二字，四层含意。夜既长，人又不寐，而砧声、月影，得并赴目前，此境凄迷，此情难堪矣。杨升庵谓此乃《鹧鸪天》下半阕，然平仄不合，杨说殊不可信。', 'indent', 1423177402, '57b8f62ac4c97100558ed93c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10369, '念奴娇', NULL, 237, 2398, 4, 2, '黄庭坚', NULL, 10086, '57b9594b8ac2470062e29b7d', '宋', 'ci', '词', 'http://baike.baidu.com/view/2786402.htm', '八月十七日，同诸生步自永安城楼，过张宽夫园待月。偶有名酒，因以金荷酌众客。客有孙彦立，善吹笛。援笔作乐府长短句，文不加点。', '断虹霁雨，净秋空，山染修眉新绿。桂影扶疏，谁便道，今夕清辉不足？万里青天，姮娥何处，驾此一轮玉。寒光零乱，为谁偏照醽醁？
年少从我追游，晚凉幽径，绕张园森木。共倒金荷，家万里，难得尊前相属。老子平生，江南江北，最爱临风笛。孙郎微笑，坐来声喷霜竹。', '宋哲宗绍圣年间，黄山谷被贬涪州别驾黔州安置，后改移地处西南的戎州（今四川宜宾）安置。据任渊《山谷诗集注》附《年谱》，宋哲宗元符二年（西元一〇九九年）八月十七日，黄山谷与一群青年人一起赏月、饮酒，有个朋友名叫孙彦立的，善吹笛，月光如水，笛声悠扬。于此情此境中，黄山谷援笔写下这首词。', '永安：即白帝城，在今四川奉节县西长江边上。
诸生：一作「诸甥」。此据《渔隐丛话后集·卷三十一》改。
张宽夫：作者友人，生平不详。
金荷：金质莲花杯。
文不加点：谓不须修改。
断虹：一部分被云所遮蔽的虹，称断虹。
山染句：谓山峰染成青黛色，如同美人的长眉毛。
桂影：相传月中有桂树，因称月中阴影为桂影。
扶疏：繁茂纷披貌，意为枝叶繁茂。
姮娥：月中女神娥。汉时避汉文帝刘恒讳，改称嫦娥。
一轮玉：指圆月。
醽醁（líng lù）：酒名。湖南衡阳县东二十里有酃湖，其水湛然绿色，取以酿酒，甘美，名酃渌，又名醽醁。
老子：老夫，作者自指。
临风笛：一作「临风曲」，具体见第一条辑评。
坐来：马上。
霜竹：指笛子。《乐书》「剪云梦之霜筠，法龙吟之异韵。', '雨后新晴，天边出现一道彩虹，万里秋空一片澄明。如秀眉的山峦经过雨水的冲刷，彷彿披上了新绿的衣服。月中的桂树还很茂密，怎么能说今夜的月色不明亮呢？万里的晴天，嫦娥在何处？她驾驶着这一轮圆月，在夜空驰骋。月光寒冷，为谁照射在这坛美酒上？
一群年轻人伴我左右，在微凉的晚风中踏着幽寂的小径，走进长满林木的张家小园，畅饮欢谈。让我们斟满手中的金荷叶杯，虽然离家万里，可是把酒畅饮的欢聚时刻实在难得。老夫我一生漂泊，走遍大江南北，最喜欢听临风的霜笛。孙郎听后，微微一笑，吹出了更加悠扬的笛声。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b77d0ac1145494bb99", "shortContent": "黄山谷的个性、学养一似东坡，豪放不羁，豁达大度，即使处在最恶劣的环境中，依然谈笑风生，不改其乐。山谷一生和东坡一样，一直被卷在党争的旋涡里。哲宗绍圣年间，他被贬涪州别驾黔州安置，后改移戎州（今四川宜宾）安置。有一年（据任渊《山谷诗集注》附《年谱》，当是哲宗元符二年［1099］）八月十七日，与一群青年人一起赏月、饮酒，有个朋友名叫孙彦立的，善吹笛，月光如水，笛声悠扬。此情此境，山谷意兴方浓，援笔写下...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5be2cee9a0c24ed9e58", "shortContent": "黄山谷的个性、学养一似东坡，豪放不羁，豁达大度，即使处在最恶劣的环境中，依然谈笑风生，不改其乐。山谷一生最崇拜东坡，处处模仿东坡。他和东坡一样，一直被卷在党争的漩涡里。哲宗绍圣年间，他被贬涪州别驾黔州安置，后改移戎州（今四川宜宾）安置。有一年（据任渊《山谷诗集注》附《年谱》，当是哲宗元符二年［1099］）八月十七日，与一群青年人一起赏月、饮酒，有个朋友名叫孙彦立的，善吹笛，月光如水，笛声悠扬。此情...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "645fb67ec0471b0062b8b5b0", "bookTitle": "黄庭坚诗文鉴赏辞典", "articleId": "6464b3517f27182da354a021", "shortContent": "黄山谷的个性、学养一似东坡，豪放不羁，豁达大度，即使处在最恶劣的环境中，依然谈笑风生，不改其乐。山谷一生和东坡一样，一直被卷在党争的旋涡里。哲宗绍圣年间，他被贬涪州别驾黔州安置，后改移戎州（今四川宜宾）安置。有一年（据任渊《山谷诗集注》附《年谱》，当是哲宗元符二年[1099]）八月十七日，与一群青年人一起赏月、饮酒，有个朋友名叫孙彦立的，善吹笛，月光如水，笛声悠扬。此情此境，山谷意兴方浓，援笔写下...", "authors": ["高原"], "pressName": "上海辞书出版社"}]', '宋·陆放翁《老学庵笔记·卷二》：鲁直在戎州，作乐府曰：「老子平生，江南江北，最爱临风笛。孙郎微笑，坐来声喷霜竹。」予在蜀，见其稿。今俗本改「笛」为「曲」以协韵，非也。然亦疑笛字太不入韵。及居蜀久，习其语音，乃知泸、戎间谓「笛」为「独」，故鲁直得借用，亦因以戏之耳。
宋·胡苕溪《渔隐丛话后集·卷三十一》：山谷云：八月十七日，与诸生步自永安城，入张宽夫园，待月。以金荷叶酌客。客有孙叔敏，善长笛，连作数曲。诸生曰：「今日之会乐矣，不可以无述。」因作此曲记之，文不加点，或以为可继东坡赤壁之歌云。', 'indent', 1413205201, '57b908b10a2b58005c927be4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10405, '乘舟风雨听芦', NULL, 64, 253, 1, 2, '高濂', NULL, 10013, '57ba82a88ac2470063045693', '明', 'wen', '文', '', '', '秋来风雨怜人，独芦中声最凄黯。余自河桥望芦，过处一碧无际，归枕故丘，每怀拍拍。武林唯独山王江泾百脚村多芦。时乎风雨连朝，能独乘舟卧听，秋声远近，瑟瑟离离，芦苇萧森，苍苍蔌蔌，或雁落哑哑，或鹭飞濯濯，风逢逢而雨沥沥，耳洒洒而心于于，寄兴幽深，放怀闲逸。舟中之中谓非第一出尘阿罗汉耶？避嚣炎而甘寥寂者，当如是降伏其心。', '', '', '', NULL, '', 'indent', 1468668986, '57b90c882e958a005fa5aa52', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10370, '六州歌头·少年侠气', NULL, 339, 877, 5, 2, '贺铸', NULL, 10098, '57b9bbb28ac2470063feff0a', '宋', 'ci', '词', 'http://baike.baidu.com/view/2755030.htm', '', '少年侠气，交结五都雄。肝胆洞，毛发耸。立谈中，死生同，一诺千金重。推翘勇，矜豪纵，轻盖拥，联飞鞚，斗城东。轰饮酒垆，春色浮寒瓮，吸海垂虹。闲呼鹰嗾犬，白羽摘雕弓，狡穴俄空。乐匆匆。
似黄粱梦，辞丹凤；明月共，漾孤篷。官冗从，怀倥偬，落尘笼，簿书丛。鹖弁如云众，供粗用，忽奇功。笳鼓动，渔阳弄，思悲翁。不请长缨，系取天骄种，剑吼西风。恨登山临水，手寄七弦桐，目送归鸿。', '此词上阕落笔先从追忆作者在东京度过的六、七年倜傥逸群的侠少生活写起，「侠」、「雄」二字总摄下文，接写豪侠们的「侠」、「雄」品格，勇敢正义，慷慨豪爽，再写豪侠们「侠」、「雄」的具体行藏，驰逐、射猎、豪饮，过着快乐的生活。上阕有点有染，虚实相间地向读者展示了一幅弓刀武侠的生动画卷。换头紧承「乐匆匆」三字，用「似黄梁梦」四字转折文意、变换情绪，锋芒直指埋没扼杀人才的封建统治阶级。「笳鼓动」以下六句，是全词的高潮，极写报国无门的悲愤，爱国之情，感人至深。最后三句，变激烈为凄凉，写理想破灭的悲哀。全词风格苍凉悲壮，感情充沛，叙事、议论、抒情结合紧密，抒发了作者报国无门、忧国忧民的情怀。', '五都：泛指北宋的各大城市。
「少年侠气，交结五都雄」句：化用李白「结发未识事，所交尽豪雄」及李益「侠气五都少」诗句。
一诺千金：喻一言既出，驷马难追，诺言极为可靠。语出《史记·季布列传》引楚人谚曰：「得黄金百斤，不如得季布一诺。」
盖：车盖，代指车。
飞：飞驰的马。鞚（kòng）：有嚼口的马络头。
斗（dǒu）城：汉长安故城，这里借指汴京。
嗾（sǒu）：指使犬的声音。
冗（rǒng）从：散职侍从官。
倥偬（kǒngzǒng）：事多、繁忙。
鹖弁（hébiàn）：本义指武将的官帽，指武官。
笳鼓：都是军乐器。
渔阳：安禄山起兵叛乱之地。此指侵扰北宋的少数民族发动了战争。
七弦桐：即七弦琴。桐木是制琴的最佳材料，故以「桐」代「琴」。', '少年时一股侠气，结交各大都市的豪雄之士。待人真诚，肝胆照人，遇到不平之事，便会怒髮冲冠，具有强烈的正义感。站立而谈，生死与共，一诺千金。我们推崇的是出众的勇敢，狂放不羁傲视他人。轻车簇拥联镳驰逐，出游京郊。在酒店里豪饮，酒坛浮现出诱人的春色，我们像长鲸和垂虹那样饮酒，顷刻即干。间或带着鹰犬去打猎，霎那间便荡平了狡兔的巢穴。虽然欢快，可惜时间太过短促。
就像卢生的黄梁一梦，很快就离开京城。驾孤舟飘流于水中，唯有明月相伴。散职侍从官品位卑微，事多繁忙，情怀愁苦。陷入了污浊的官场仕途，担任了繁重的文书事务工作。像我这样成千上万的武官，都被支派到地方上去打杂，劳碌于文书案牍，不能杀敌疆场、建功立业。笳鼓敲响了，渔阳之兵乱起来了，战争爆发了，想我这悲愤的老兵啊，却无路请缨，不能为国御敌，生擒西夏酋帅，就连随身的宝剑也在秋风中发出愤怒的吼声。怅恨自己极不得志，只能满怀惆怅游山临水，抚琴寄情，目送归鸿。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74c22e6a6b501f954300", "shortContent": "《东山词》中的压卷之作，恐怕非这首闪耀着爱国主义光辉的《六州歌头》莫属了。关于它的创作背景，向有二说。二说都把它系在徽宗宣和七年（1125），亦即词人七十四岁，临死的那一年。不过一说为抗金而作，一说为抗辽而作，又略有分歧。据笔者考证，此词实作于哲宗元祐三年（1088）秋，时词人年三十七岁，在和州（今安徽和县一带）管界巡检（负责地方上训治甲兵、巡逻州邑、擒捕盗贼等事宜的武官）任；而词的要旨，则与抗夏...", "authors": ["钟振振"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5c70ce818559d063ba4", "shortContent": "《东山词》中的压卷之作，恐怕非这首闪耀着爱国主义光辉的《六州歌头》莫属了。关于它的创作背景，向有二说。二说都把它系在徽宗宣和七年（1125），亦即词人七十四岁，临死的那一年。不过一说为抗金而作，一说为抗辽而作，又略有分歧。据笔者考证，此词实作于哲宗元三年（1088）秋，时词人年三十七岁，在和州（今安徽和县一带）管界巡检（负责地方上训治甲兵、巡逻州邑、擒捕盗贼等事宜的武官）任；而词的要旨，则与抗夏...", "authors": ["钟振振"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059254f534825dee9fd6fb", "shortContent": "《东山词》中的压卷之作，恐怕非这首闪耀着爱国主义光辉的《六州歌头》莫属了。关于它的创作背景，向有二说。二说都把它系在徽宗宣和七年（1125），亦即词人七十四岁，临死的那一年。不过一说为抗金而作，一说为抗辽而作，又略有分歧。据笔者考证，此词实作于哲宗元祐三年（1088）秋，时词人年三十七岁，在和州（今安徽和县一带）管界巡检（负责地方上训治甲兵、巡逻州邑、擒捕盗贼等事宜的武官）任；而词的要旨，则与抗夏...", "authors": ["钟振振"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472c00982772d45942a44c4", "shortContent": "《东山词》中的压卷之作，恐怕非这首闪耀着爱国主义光辉的《六州歌头》莫属了。关于它的创作背景，向有二说。二说都把它系在徽宗宣和七年（1125），亦即词人七十四岁，临死的那一年。不过一说为抗金而作，一说为抗辽而作，又略有分歧。据笔者考证，此词实作于哲宗元祐三年（1088）秋，时词人年三十七岁，在和州（今安徽和县一带）管界巡检（负责地方上训治甲兵、巡逻州邑、擒捕盗贼等事宜的武官）任；而词的要旨，则与抗夏...", "authors": ["钟振振"], "pressName": "上海辞书出版社"}]', '', 'indent', 1363623205, '57b91076165abd0054c04cd6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10385, '庐山草堂记', NULL, 24, 2952, 1, 1, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'wen', '文', 'http://baike.baidu.com/view/1216913.htm', '', '匡庐奇秀，甲天下山，山北峰曰香炉峰，峰北寺曰遗爱寺。介峰寺间，其境胜绝，又甲庐山。
元和十一年秋，太原人白乐天见而爱之，若远行客过故乡，恋恋不能去，因面峰腋寺，作为草堂。
明年春，草堂成。三间两柱，二室四牖，广袤丰杀，一称心力。洞开北户，来阴风，防徂暑也。敞南甍，纳阳日，虞祁寒也。木，斫而已，不加丹。墙，圬而已，不加白。墄阶用石，幂窗用纸，竹帘纻帏，率称是焉。堂中设木榻四，素屏二，漆琴一张，儒道佛书，各两三卷。
乐天既来为主，仰观山，俯听泉，傍睨竹树云石，自辰至酉，应接不暇。俄而物诱气随，外适内和。一宿体宁，再宿心恬，三宿后颓然嗒然，不知其然而然。
自问其故。答曰：是居也，前有平地，轮广十丈；中有平台，半平地；台南有方池，倍平台。环池多山竹，野卉。池中生白莲，白鱼。又南抵石涧。夹涧有古松，老杉，大仅十人围，高不知几百尺，修柯嘎云，低枝拂潭；如幢竖，如盖张，如龙蛇走。松下多灌丛，萝茑叶蔓，骈织承翳，日月光不到地。盛夏风气，如八九月时。下铺白石，为出入道。堂北五步，据层崖，积石，嵌空垤块，杂木异草，盖覆其上。绿阴蒙蒙，朱实离离，不识其名，四时一色。又有飞泉，植茗就以烹燀，好事者见，可以永日。堂东有瀑布，水悬三尺，泻阶隅，落石渠，昏晓如练色，夜中如环佩琴筑声。堂西倚北崖右趾，以剖竹架空，引崖上泉，脉分线悬，自檐注砌，累累如贯珠，霏微如雨露，滴沥飘洒，随风远去。其四旁耳目杖屦可及者，春有锦绣谷花，夏有石门涧云，秋有虎溪月，冬有庐峰雪。阴晴显晦，昏旦含吐，千变万状，不可殚纪，覶缕而言，故云甲庐山者。噫！凡人丰一屋，华一箦，而起居其间，尚不免有骄矜之态，今我为是物主，物至致知，各以类至，又安得不外适内和，体宁心恬哉昔永，远，宗，雷辈十八人，同入此山，老死不返，去我千载，我知其心以是哉！
矧予自思，从幼迨老，若白屋，若朱门，凡所止虽一日二日，辄覆篑土为台，聚拳石为山，环斗水为池，其喜山水病癖如此。一旦蹇剥，来佐江郡，郡守以优容抚我，庐山以灵胜待我，是天与我时，地与我所，卒获所好，又何求焉！尚以冗员所羁，余累未尽，或往或来，未遑宁处。待予异时弟妹婚嫁毕，司马岁秩满，出处行止，得以自遂，则必左手引妻子，右手抱琴书，终老于斯，以成就我平生之志。清泉白石，实闻此言！
时三月二十七日始居新堂；四月九日与河南元集虚，范阳张允中，南阳张深之，东西二林长老凑，朗，满，晦，坚等凡二十又二人，具斋，施茶果以乐之。因为草堂记。', '此文为白居易创作的山水游记。先交代草堂的由来和位置，次写草堂的设置，再写住进草堂后的情景，然后正面记叙对山水的爱好和希望终老草堂的心情，最后附记移居、庆贺及作记等事。全文以娴熟的文笔和技巧，充分表达了自己酷爱山水癖好，并注入了自己的身世感、沧桑感，使山水别具内涵与风韵。', '匡庐：指江西的庐山。相传殷周之际有匡俗兄弟七人结庐于此，故称。
介：处于两者之中。
面峰腋寺：对山傍寺。腋，两腋在人身旁，古引申为“傍”。
明年：第二年。
广袤：土地的长和宽。这里指面积大小。丰杀：增减。
一称心力：全与自己的愿望和财力相称。
洞：洞开。
阴风：北风。
徂暑：盛暑。
祁寒：严寒。
幂：覆盖。
嗒（tà）然：物我两忘貌。
轮广：纵横。南北为轮，东西为广。
环：环绕。卉（huì）：花草。
戛（jiá）：摩，摩挲。
幢：古代作仪仗用的一种旗帜，以羽毛为饰。
可以：可以借此。
筑：古代打击的弦乐器。
杖屦：扶杖步行。
晦：暗。
殚：尽。
覶缕（luólǚ）：原委本末，此指细说。
甲：名作动，居第一。
物至致知：谓各种景物纷至眼前，使人有所感受而增长智慧。
永、远、宗、雷辈十八人：指东晋高僧慧永、慧远兄弟和著名隐士宗炳、雷次宗等人。
白屋：指贫苦人家的屋子。
蹇剥：均为《易经》卦名。此指遭受挫折。
冗员：闲散多余的官员。
岁秩：规定的任职年限。
落：落成。这里指庆贺落成。', '庐山的风景，秀丽至极，简直是天下诸山的冠军。山的北峰，叫做香炉峰；香炉峰的北面的寺庙叫做遗爱寺；介于香炉峰与遗爱寺之间，那地方最美，又是庐山之最。元和十一年的秋天，太原人白乐天一见就爱上它了，就像远行的游子路过故乡一样，恋恋不舍而不忍离去，于是面对香炉峰，下近遗爱寺，盖了一间草堂。
第二年春天，草堂落成了。三间屋子，两根楹柱；两个卧房，四扇窗子；（屋子的）面积大小，完全与心意相合，与财力相称。打开北边的小门，使凉爽的风吹进来，避盛暑；把屋脊南面盖得高些，让阳光照射进来，防备严寒。建造房屋的木材只用斧子砍削，不用油漆彩绘；墙涂泥就可，不必用石灰白粉之类粉刷。砌台阶用石头；糊窗户用纸，竹子做的帘子，麻布做的帐幕，一切全都和草堂的简朴格局相称。屋子里设有木制椅榻四张，素色屏风两座，还有漆琴一张，和儒、释、道书籍各三两卷。
乐天我已来到这里做了草堂的主人，仰观山色，俯听泉声，随意浏览旁边的竹树云石。从早到晚，美景很多，来不及一一观赏。看了一会儿，由于清幽景物的诱发，性情也随之变得恬淡；环境适宜，心情平和。只要住一宿，身体就十分安宁，住两夜更感到心情平静安适，住三个晚上以后，心旷神怡，物我两忘，也不知是如何进入这种状态的。
自问其缘故，回答说：这草堂，前面有平地，面积约十丈，中间有平台，是平地面积的一半，平台的南边有方形的池子，池子的面积比平台大一倍。环绕着水池多是山竹、野草，池里长满了白莲、白鱼。再往南走，就到了一个山石间的水沟，石涧两旁有古松、老杉，树身粗大的将近十人之围（十人围大约是两人合抱），树的高度不知几百尺，长枝条上摩云霄，低垂的枝柯轻拂着潭水。像旌旗一样竖立，像车盖一样张开，盘曲伸展如龙蛇游走。古松下多灌木丛，茑罗枝叶蔓生，互相纠结交织，互相承接遮盖，使得日光月华都无法照射到地面。到了盛夏时的气候，仍像八九月的秋凉时节。地下铺着白石做为出入的信道。草堂北边五步远的地方，凭借高崖积石作为假山，在空凹处卡进小土堆和土块，各种树木、奇花异草覆盖其上。绿荫浓密，红色的果实繁多，也说不出它们的名字，四季都是这个样子。又有天上飞落的泉水，就地种植的茶树，就这飞泉和植茗来烹茶，若被爱好风雅之事的人看到，可以终日不去。草堂东边有一座瀑布，清水悬挂三尺高，泻落在台阶角落，然后注入石渠中。从早到晚，就像洁白的绸子，要是在夜间听起来，就像珠玉琴筝的声音。草堂的西边，靠近北面山崖的右侧山脚，用剖开的竹子，架在空中，接引北崖山上的泉水，这些竹管如脉管一样分出水流，细水从上流下，像细线一样悬挂空中，从屋檐灌注到水池里，连接不断像成串的珍珠，细微水点飘散的样子像雨露一般，水一点一点地往下落，随风远去。那附近望得见、走得到的地方，春，有锦绣山谷中的繁花；夏，有石门涧里的皓云；秋，有虎溪的明月；冬，有炉峰的白雪。阴晴明暗，黄昏早晨的烟云隐现，千变万化，不可详尽记述，细细说来，所以我才说这里的景色是庐山第一！
唉！一般人只要建造一间高大的房屋，精制一张竹席，而生活在当中，尚且免不了有骄傲自负之态。何况是我，已成了这些东西的主人，草堂周围的美景纷至沓来，激发人的思想感情，接触什么样的景物就产生什么样的思想感情，我又怎能不外在安适、内在和乐，身体安宁，心情恬适呢？想当年东晋高僧慧永、慧远、名儒宗炳、雷次宗等十八人一起住入此山，就直到老死也都不肯离开，虽然与我现在相距久远，但我知道他们心里也是因为这庐山的美景啊！
更何况我从小到老，不管住的是白色的茅屋或者朱色的大厦，只要在居所住上一天两天，我总是要搬少许土做个台子，聚集一些卵石来筑座假山，再环绕个小小的水池，可见我对山水的癖好已经到了如此无可救药的地步。
一旦命运不顺当，被贬来辅佐九江郡守，郡守以宽厚来安抚我，庐山以他神奇的美景对待我，这简直是上天赐给了我最好的时机、大地送给我最好的空间，我终于能得到自己的最爱，还有什么好苛求呢？只不过我为闲散的官职所束缚，未能完全摆脱牵累，时去时回，没有闲暇安宁地住下来。等到哪天弟妹各自成家了，官职任期满了，外出做官还是在家不仕，都能顺遂自己的心意，那么一定会左手牵着老伴和孩子，右手抱着古琴与书本，终老在此，以完成我一辈子的心愿。我发誓，清泉白石可以做我盟誓的证人。
在三月二十七日，我刚搬到这新居草堂；四月九日，和河南元集虚、范阳张允中、南阳张深之以及东林寺、西林寺的长老大德凑、朗、满、慧、坚等二十二人，准备了斋食摆设了茶果点心来为新居行落成典礼，于是写下了这篇《草堂记》。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1ef2cee9a0c24edae71", "shortContent": "此文作于唐宪宗元和十二年（817），前此二年，宰相武元衡被平卢节度使李师道派人暗杀。白居易上疏“急请捕贼，以雪国耻”（《旧唐书》本传），为权贵所憎恶，以“越职言事”贬为江州司马。元和十一年（816）秋，白居易游庐山，独爱香炉峰下、遗爱寺旁的一处胜景，便在那里修筑一草堂。次年草堂落成，他写了这篇《庐山草堂记》。\n文章起始，交代草堂的由来及位置。庐山三面临水，层峦叠嶂，云影瀑流，相互映发，景色奇丽秀美...", "authors": ["潘裕民"], "pressName": "上海辞书出版社"}, {"bookId": "645d09bbec56251f2eeb5b78", "bookTitle": "白居易诗文鉴赏辞典", "articleId": "6462e6207f27182da34be155", "shortContent": "此文作于唐宪宗元和十二年（817），前此二年，宰相武元衡被平卢节度使李师道派人暗杀。白居易上疏“急请捕贼，以雪国耻”（《旧唐书》本传），为权贵所憎恶，以“越职言事”贬为江州司马。元和十一年（816）秋，白居易游庐山，独爱香炉峰下、遗爱寺旁的一处胜景，便在那里修筑一草堂。次年草堂落成，他写了这篇《庐山草堂记》。\n\n文章起始，交代草堂的由来及位置。庐山三面临水，层峦叠嶂，云影瀑流，相互映发，景色奇丽秀...", "authors": ["潘裕民"], "pressName": "上海辞书出版社"}]', '', 'indent', 1423177695, '57adb431c4c97100546c797a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10386, '古诗十九首 · 行行重行行', NULL, 974, 496, 5, 6, '无名氏', NULL, 10100, '57b959c18ac2470062e2a00f', '汉', 'shi', '诗', 'http://baike.baidu.com/subview/432100/13355351.htm', '', '行行重行行，与君生别离。
相去万余里，各在天一涯；
道路阻且长，会面安可知？
胡马依北风，越鸟巢南枝。
相去日已远，衣带日已缓；
浮云蔽白日，游子不顾反。
思君令人老，岁月忽已晚。
弃捐勿复道，努力加餐饭。', '《行行重行行》是《古诗十九首》的第一首，写的是思妇的离愁别恨。东汉末年，游宦之风极盛，读书人为了寻求出路，求取功名富贵，不得不背井离乡，四处奔走。当时政治异常黑暗，社会极为混乱，出身低下的知识分子，即使满腹经纶，也难于施展。在这种情况下，亲人远离的痛苦，就显得更为突出。所以，《古诗十九首》中以夫妻别离、互相思念为题材的作品占了很大比例，从一个侧面反映了当时社会状况，特别是下层知识分子的思想苦闷。', '「行行重行行」句：行而不止。重，又。
生别离：活生生地分离
相去：相距，相离。
涯：边际。
阻：艰险。
「胡马依北风，越鸟巢南枝」句：这是当时习用的比喻，借喻眷恋故乡的意思。胡马，北方所产的马；越鸟，南方所产的鸟。
已：同「以」。
远：久。
缓：宽松。这句意思是说，人因相思而躯体一天天消瘦。
顾：顾恋、思念。
反：同「返」，返回、回家。
老：并非实指年龄，而指消瘦的体貌和忧伤的心情，是说心身憔悴，有似衰老而已。
晚：指行人未归，岁月已晚，表明春秋忽代谢，相思又一年，暗喻青春易逝
弃捐：抛弃。
「弃捐勿复道，努力加餐饭。」句：把我们彼此的睹物思人的物件收起，不要再诉说相思了。化用的班婕妤的“弃捐箧笥中，恩情中道绝”努力加餐饭为化用卓文君“努力加餐勿念妾，锦水汤汤，与君长诀”。', '你走啊走啊老是不停的走，就这样活生生分开了你我。
从此你我之间相距千万里，我在天这头你就在天那头。
路途那样艰险又那样遥远，要见面可知道是什么时候？
北马南来仍然依恋着北风，南鸟北飞筑巢还在南枝头。
彼此分离的时间越长越久，衣服越发宽大人越发消瘦。
飘荡游云遮住了太阳，他乡的游子不想回还。
只因为想你使我都变老了，又是一年很快地到了年关。
还有许多心里话都不说了，只愿你多保重切莫受饥寒。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecc967d0ac1145495f2df", "shortContent": "这是一首在东汉末年动荡岁月中的相思乱离之歌。尽管在流传过程中失去了作者的名字，但“情真、景真、事真、意真”（陈绎《诗谱》），读之使人悲感无端，反复低徊，为女主人公真挚痛苦的爱情呼唤所感动。\n首句五字，连叠四个“行”字，仅以一“重”字绾结。“行行”言其远，“重行行”极言其远，兼有久远之意，翻进一层，不仅指空间，也指时间。于是，复沓的声调，迟缓的节奏，疲惫的步伐，给人沉重的压抑感，痛苦伤感的氛围，立即...", "authors": ["曹", "旭"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f614f902ee364cc8b30fb", "shortContent": "这是一首在东汉末年动荡岁月中的相思乱离之歌。尽管在流传过程 中失去了作者的名字，但“情真、景真、事真、意真”(陈绎《诗谱》)，读之使 人悲感无端，反复低徊，为女主人公真挚痛苦的爱情呼唤所感动。\n\n首句五字，连叠四个“行”字，仅以一“重”字绾结。“行行”言其远，“重 行行”极言其远，兼有久远之意，翻进一层，不仅指空间，也指时间。于是， 复沓的声调，迟缓的节奏，疲惫的步伐，给人沉重的压抑感，痛苦伤感的...", "authors": ["曹旭"], "pressName": "上海辞书出版社"}]', '陈绎《诗谱》：情真、景真、事真、意真。', 'center', 1423177748, '57b19776128fe10055c7c6a5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10387, '古诗十九首 · 青青河畔草', NULL, 369, 496, 3, 1, '无名氏', NULL, 10100, '57b959c18ac2470062e2a00f', '汉', 'shi', '诗', 'http://baike.baidu.com/view/333389.htm', '', '青青河畔草，郁郁园中柳。
盈盈楼上女，皎皎当窗牖。
娥娥红粉妆，纤纤出素手。
昔为倡家女，今为荡子妇。
荡子行不归，空床难独守。', '此诗叙述的是一个生活片断，大致描述如下：诗中的女主人公独立楼头，体态盈盈，如临风凭虚；她倚窗当轩，容光照人，皎皎有如轻云中的明月；她红妆艳服，打扮得十分用心；她牙雕般的纤纤双手，扶着窗棂，在久久地引颈远望：她望见了园久河畔，草色青青，绵绵延延，伸向远方，“青青河畔草，绵绵思远道；远道不可思，宿昔梦见之”（《古诗》），原来她的目光，正随着草色，追踪着远行人往日的足迹；她望见了园中那株郁郁葱葱的垂柳，她曾经从这株树上折枝相赠，希望柳丝儿，能“留”住远行人的心儿。原来一年一度的春色，又一次燃起了她重逢的希望，也撩拔着她那青春的情思。希望，在盼望中又一次归于失望，情思，在等待中化成了悲怨。她不禁回想起生活的波弄，她，一个倡家女，好不容易挣脱了欢场泪歌的羁绊，找到了惬心的郎君，希望过上正常的人的生活；然而何以造化如此弄人，她不禁在心中呐喊：“远行的荡子，为何还不归来，这冰凉的空床，叫我如何独守！”
此诗定的就是这样一个重演过无数次的平凡的生活片断，用的也只是即景抒情的平凡的章法、“秀才说家常话”（谢榛语）式的平凡语言；然而韵味却不平凡。能于平凡中见出不平凡的境界来，就是此诗，也是《古诗十九首》那后人刻意雕镌所不能到的精妙。', '', '', '[{"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f615e5e6bb82b8cf1a619", "shortContent": "她，独立楼头，体态盈盈，如临风凭虚;她，倚窗当轩，容光照人，皎皎 有如轻云中的明月;为什么，她红妆艳服，打扮得如此用心;为什么，她牙 雕般的纤纤双手，扶着窗櫺，在久久地引颈远望:她望见了什么呢?望见 了园外河畔，草色青青，绵绵延延，伸向远方，“青青河畔草，绵绵思远道; 远道欲何之，宿昔梦见之”(《古诗》)，原来她的目光，正随着草色，追踪着 远行人往日的足迹;她望见了园中那株郁郁葱葱的垂柳，她曾经从...", "authors": ["马茂元", "赵昌平"], "pressName": "上海辞书出版社"}]', '', 'center', 1423177924, '57b2c79e5bbb500062e57247', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10395, '赠卫八处士', NULL, 988, 1416, 2, 2, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155666.htm', '', '人生不相见，动如参与商。
今夕复何夕，共此灯烛光。
少壮能几时，鬓发各已苍。
访旧半为鬼，惊呼热中肠。
焉知二十载，重上君子堂。
昔别君未婚，儿女忽成行。
怡然敬父执，问我来何方。
问答未及已，驱儿罗酒浆。
夜雨剪春韭，新炊间黄粱。
主称会面难，一举累十觞。
十觞亦不醉，感子故意长。
明日隔山岳，世事两茫茫。', '此诗作于诗人被贬华州司功参军之后。诗写偶遇少年知交的情景，抒写了人生聚散不定，故友相见格外亲。然而暂聚忽别，却又觉得世事渺茫，无限感慨。开头四句，写久别重逢，从离别说到聚首，亦悲亦喜，悲喜交集；第五至八句，从生离说到死别，透露了干戈乱离、人命危浅的现实；从「焉知」到「意长」十四句，写与卫八处士的重逢聚首以及主人及其家人的热情款待，表达诗人对生活美和人情美的珍视；最后两句写重会又别之伤悲，低徊婉转，耐人寻味。全诗平易真切，层次井然。', '卫八：名字和生平事迹已不可考。八，行八。
处士：指隐居不仕的人；
动如：是说动不动就像。
参（shēn）商：二星名。典故出自《左传·昭公元年》：「昔高辛氏有二子，伯曰阏伯，季曰实沉。居于旷林，不相能也。日寻干戈，以相征讨。后帝不臧，迁阏伯于商丘，主辰，商人是因，故辰为商星。迁实沉于大夏，主参，唐人是因，以服事夏商。」商星居于东方卯位（上午五点到七点），参星居于西方酉位（下午五点到七点），一出一没，永不相见，故以为比。
今夕：一作「今此」。
共此灯烛光：一作「共宿此灯光」。
苍：灰白色。
「访旧半为鬼」句：意谓彼此打听故旧亲友，竟已死亡一半。访旧，一作「访问」。
「惊呼热中肠」句：有两种理解，一为：见到故友的惊呼，使人内心感到热乎乎的；二为：意外的死亡，使人惊呼怪叫以至心中感到火辣辣的难受。惊呼，一作「呜呼」。
成行（háng）：儿女众多。
「怡然敬父执」：词出《礼记·曲礼》：「见父之执。」意即父亲的执友。执是接的借字，接友，即常相接近之友。
乃未已：一作「未及已」，还未等说完。
驱儿：一作「儿女」。
罗：罗列酒菜。
「夜雨剪春韭」句：用郭泰冒雨剪韭招待好友范逵的故事。「（郭）林宗自种畦圃，友人范逵夜至，自冒雨剪韭，作汤饼以供之。」明·程登吉《幼学琼林·卷四·花木》：「冒雨剪韭，郭林宗款友情殷；踏雪寻梅，孟浩然自娱兴雅。」
新炊：一作「晨炊」。
间（jiàn）：一作「闻」。间，搀和。
黄粱：即黄米。新炊是刚煮的新鲜饭。
主：主人，即卫八。
称：说。曹植《箜篌引》诗：「主称千金寿，宾奉万年酬。」
累十觞：一作「蒙十觞」。累。接连。
十觞：一作「百觞」。
不醉：一作「不辞」。
故意长：老朋友的情谊深长。
「明日隔山岳」句：意谓明天便要分手。山岳，指西岳华山。
世事：包括社会和个人。
两茫茫：是说明天分手后，命运如何，便彼此都不相知了。极言会面之难，正见今夕相会之乐。这时大乱还未定，故杜甫有此感觉。根据末两句，这首诗乃是饮酒的当晚写成的。', '人生旅途常有别离不易相见，就像参星商星实在难得相遇。
今夜又是一个什么吉日良辰，让我们共同在这烛光下叙谈。
青春壮健年少岁月能有多少，转瞬间你我都已经两鬓如霜。
昔日往来的朋友一半已去世，我内心激荡不得不连声哀叹。
没想到我们已分别廿个春秋，今天还能亲临你家里的厅堂。
相分别时你还没有结婚成家，倏忽间你的子女已成帮成行。
他们彬彬有礼笑迎父亲老友，亲切地询问我来自什么地方？
还来不及讲述完所有的往事，你就催促儿女快把酒菜摆上。
冒着夜雨剪来了青鲜的韭菜，呈上新煮的黄米饭让我品尝。
主人感慨见面的机会太难得，开怀畅饮一连喝干了十几杯。
一连喝干十几杯还没有醉意，令我感动你对老友情深意长。
明日分别后又相隔千山万水，茫茫的世事真令人愁绪难断。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92aa2cee9a0c24ecf8b6", "shortContent": "这首诗是肃宗乾元二年（759）春天，杜甫自洛阳（今属河南）返回华州（治今陕西华县）途中所作。卫八处士，名字和生平事迹已不可考。处士，指隐居不仕的人。\n开头四句说，人生动辄如参、商二星，此出彼没，不得相见；今夕又是何夕，咱们一同在这灯烛光下叙谈。这几句从离别说到聚首，亦悲亦喜，悲喜交集，把强烈的人生感慨带入了诗篇。诗人与卫八重逢时，安史之乱已延续了三年多，虽然两京已经收复，但叛军仍很猖獗，局势动荡不...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a76", "shortContent": "这首诗是肃宗乾元二年（759）春天，杜甫自洛阳（今属河南）返回华州（治今陕西渭南市华州区）途中所作。卫八处士，名字和生平事迹已不可考。处士，指隐居不仕的人。\n\n开头四句说，人生动辄如参、商二星，此出彼没，不得相见；今夕又是何夕，咱们一同在这灯烛光下叙谈。这几句从离别说到聚首，亦悲亦喜，悲喜交集，把强烈的人生感慨带入了诗篇。诗人与卫八重逢时，安史之乱已延续了三年多，虽然两京已经收复，但叛军仍很猖獗，...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d94", "shortContent": "身逢战乱，面对仍然动荡不安的局势，友人相见，恍如梦寐。\n\n“人生不相见，动如参与商。”一开始，诗人就陷入了一种深沉的悲哀情绪中了。参与商是中国古代的星宿名，按照当今天文学的星座划分，参星是现在的猎户座，商星是天蝎座。参星在西而商星在东，当一个上升时，另一个则下沉，永不相见。经历了几年辗转流离的生活，今日能以一身之完与卫八处士相见，诗人抑制不住内心的感慨，悲喜交集的情绪溢于笔端。“今夕复何夕，共此灯...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270597f0b9738b369b1de", "shortContent": "身逢战乱，面对仍然动荡不安的局势，友人相见，恍如梦寐。\n\n“人生不相见，动如参与商。”一开始，诗人就陷入了一种深沉的悲哀情绪中了。参与商是中国古代的星宿名，按照当今天文学的星座划分，参星是现在的猎户座，商星是天蝎座。参星在西而商星在东，当一个上升，另一个即下沉，永不相见。经历了几年辗转流离的生活，今日能以一身之完与卫八处士相见，诗人抑制不住内心的感慨，悲喜交集的情绪溢于笔端。“今夕复何夕，共此灯烛...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270c79761253910e905b3", "shortContent": "身逢战乱，面对仍然动荡不安的局势，友人相见，恍如梦寐。“人生不相见，动如参与商。”一开始，诗人就陷入了一种深沉的悲哀情绪中了。参与商是中国古代的星宿名，按照当今天文学的星座划分，参星是现在的猎户座，商星是天蝎座。参星在西而商星在东，当一个上升，另一个下沉，永不相见。经历了几年辗转流离的生活，今日能以一身之完与卫八处士相见，诗人抑制不住内心的感慨，悲喜交集的情绪溢于笔端。“今夕复何夕，共此灯烛光。”...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6465d8a17da2f75ac7ecb2f8", "shortContent": "这首诗是肃宗乾元二年（759）春天，杜甫自洛阳（今属河南）返回华州（治今陕西华县）途中所作。卫八处士，名字和生平事迹已不可考。处士，指隐居不仕的人。\n\n开头四句说，人生动辄如参、商二星，此出彼没，不得相见；今夕又是何夕，咱们一同在这灯烛光下叙谈。这几句从离别说到聚首，亦悲亦喜，悲喜交集，把强烈的人生感慨带入了诗篇。诗人与卫八重逢时，安史之乱已延续了三年多，虽然两京已经收复，但叛军仍很猖獗，局势动荡...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}]', '《唐诗品汇》：刘云：《阳关》之后，此语为畅（末二句下）。
《唐诗快》：此首无甚奇妙处，既逸而复收之，不过一真。
《唐诗归》：钟云：写情寂寂（首四句下）。谭云：「父执」二字凄然，读之使人自老（「怡然」句下）。钟云：只叙真境，如道家常，欲歌，欲哭（「问我」句下）。钟云：幽事著色（「夜雨」二句下）。
《汇编唐诗十集》：唐云：凡诗，情真者不厌浅。钟、谭虽喜深，不能删此作。
《唐诗选脉会通评林》：周敬曰：情真，浅不堕肤；淡雅，的然陶派。甸曰：主宾情义，蔼然于久别之馀。陆时雍曰：此诗情胜乎词。
《杜臆》：信手写去，意尽而止，空灵宛畅，曲尽其妙。
《唐诗评选》：每当近情处，即抗引作浑然语，不使泛滥，熟吟「青青河日草」，当知此作之雅。杜赠送五言，能有节者，唯此一律。
《增订唐诗摘钞》：只是「真」，便不可及，真则熟而常新。人也未尝无此真景，但为笔墨所隔，写不出耳。
《义门读书记》：句句转。……「夜雨剪春韭」，虽然仓卒薄设，犹必冒雨剪韭，所以见其恭也。「新炊间黄梁」，宋子京书作「闻黄粱」，非常生动。
《读杜心解》：古趣盎然，少陵别调。一路皆属叙事，情真、景真，莫乙其处只起四句是总提，结两句是去路。
《杜诗镜铨》：蒋云：处士家风宛然（「夜雨」二句下）。张上若云：诗无句不关人情之至，情景逼真，兼极顿挫之妙。', 'center', 1363990782, '57b2c7b479bc440058efc6bd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (63567, '摊破浣溪沙', NULL, 0, 33, 0, 1, '赵雍', NULL, 11477, '5858e67d1b69e6006cb0f37e', '元', 'ci', '词', NULL, NULL, '春草萋萋绿渐浓。梨花落尽晚来风。试问相逢何处好，小楼东。
朱箔影移无限恨，玉箫声转曲将终。独倚阑干谁是伴，月明中。', NULL, NULL, NULL, NULL, NULL, 'indent', 1541435167, '585cfb0cac502e0067218351', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10388, '古诗十九首 · 庭中有奇树', NULL, 367, 496, 4, 4, '无名氏', NULL, 10100, '57b959c18ac2470062e2a00f', '汉', 'shi', '诗', 'http://baike.baidu.com/view/784434.htm', '', '庭中有奇树，绿叶发华滋。
攀条折其荣，将以遗所思。
馨香盈怀袖，路远莫致之。
此物何足贵，但感别经时。', '此诗选自《古诗十九首》，写一个妇女对远行的丈夫的深切的怀念之情。由树及叶，由叶及花，由花及采，由采及送，由送及思。全诗八句，可分作两个层次。前四句诗描绘了这样一幅图景：
在春天的庭院里，有一株嘉美的树，在满树绿叶的衬托下，开出了茂密的花朵，显得格外生气勃勃。春意盎然。女主人攀着枝条，折下了最好看的一束花，要把它赠送给日夜思念的亲人。
古诗中写女子的相思之情，常常从季节的转换来发端。因为古代女子受到封建礼教的严重束缚，生活的圈子很狭小，不像许多男子那样，环境的变迁，旅途的艰辛，都可能引起感情的波澜；这些妇女被锁在闺门之内，周围的一切永远是那样沉闷而缺少变化，使人感到麻木。唯有气候的变化，季节的转换，是她们最敏感的，因为这标志着她们宝贵的青春正在不断地逝去，而怀念远方亲人的绵绵思绪，却仍然没有头。
“庭中有奇树，绿叶发华滋。攀条折其荣，将以遗所思。”这两句诗写得很朴素，其中展现的正是人们在日常生活中常常可以见到的一种场面。但是把这种场面和思妇怀远的特定主题相结合，却形成了一种深沉含蕴的意境，引起读者许多联想：这位妇女在孤独中思念丈夫，已经有了很久的日子吧？也许，在整个寒冬，她每天都在等待春天的来临，因为那充满生机的春光，总会给人们带来欢乐和希望。那时候，日夜思念的人儿或许就会回来，春日融融，他们将重新团聚在花树之下，执手相望，倾诉衷肠。可是，如今眼前已经枝叶扶疏，繁花满树了，而站在树下的她仍然只是孤零零的一个，怎不教人感到无限惆怅呢？再说，如果她只是偶尔地见了这棵树，或许会顿然引起一番惊讶和感慨：时光过得真快，转眼又是一年了！然而这树就生在她的庭院里，她是眼看着叶儿一片片地长，从鹅黄到翠绿，渐渐地铺满了树冠；她是眼见着花儿一朵朵地开，星星点点渐渐地就变成了绚烂的一片。她心里的烦恼也跟着一分一分地堆积起来，这种与日聚增的痛苦，不是更令人难以忍受吗？此时此刻，她自然会情不自禁地折下一枝花来，想把它赠送给远方的亲人。因为这花凝聚着她的哀怨和希望，寄托着她深深的爱情。也许，她指待这花儿能够带走一部分相思的苦楚，使那思潮起伏的心能够得到暂时的平静；也许，她希望这故园亲人手中的花枝，能够打动远方游子的心，催促他早日归来。总之，我们在这简短的四句诗中，不是可以体会到许多诗人没有写明的内容吗？
自第五句发生转折，进入第二个层次。“馨香盈怀袖”，是说花的香气染满了妇人的衣襟和衣袖。这句紧承上面“攀条折其荣，将以遗所思”两句，同时描绘出花的珍贵和人物的神情。这花是“奇树”的花，它的香气特别浓郁芬芳，不同于般的杂花野卉，可见用它来表达纯洁的爱情，寄托深切的思念，是再合适不过了。至于人物的神情，诗人虽没有明写，但一个“盈”字，却暗示我们：主人公手执花枝，站立了很久。本来，她“攀条折其荣”，是因为思绪久积，情不自禁；可待到折下花来，才猛然想到：天遥地远，这花无论如何也不可能送到亲人的手中。古时交通不便，通信都很困难，何况这是一枝容易凋零的鲜花呢？此时的她，只是痴痴地手执着花儿，久久地站在树下，听任香气充满怀袖而无可奈何。她似乎忘记了时间也忘记了周围的一切，对着花深深地沉入冥想之中。
“馨香盈怀袖，路远莫致之”，这简简单单的十个字，给我们描绘了一幅多么清晰生动的画面啊。我们还可以进一步想象：这位妇女正在想些什么呢？她是否在回忆往日的幸福？因为这奇树生在他们的庭院之中，往日夫妻双双或许曾在花树下，消磨过许许多多欢乐的时光。在那叶茂花盛的时候，她所爱的人儿，是不是曾经把那美丽的花朵插在她鬓发之间呢？而如今，她时时思念的丈夫正在哪儿？可曾遭遇到什么？她自己所感受的痛苦，远方的人儿也同样感受到了吗？……不管她想到了什么，有一点她总是不能摆脱的，那就是对青春年华在寂寞孤苦之中流逝的无比惋惜。古代妇女的生活，本来就那么狭窄单调，唯有真诚的爱情，能够给她们带来一点人生的乐趣。当这点乐趣也不能保有的时候，生活是多么暗淡无光啊！花开花落，宝贵的青春又能经得住几番风雨呢？
现在，我们再回顾这首诗对于庭中奇树的描写，就可以明明白白地看到，诗人始终暗用比兴的手法，以花来衬托人物，写出人物的内心世界。一方面，花事的兴盛，显示了人物的孤独和痛苦；另一方面，还隐藏着更深的一层意思，那就是：花事虽盛，可是风吹雨打，很快就会落，那不正是主人公一生遭遇的象征吗？在《古诗十九首》的另一篇《冉冉孤竹生》里面，有这样一段话：“伤彼蕙兰花，含英扬光辉；过时而不采，将随秋草萎。”用蕙兰花一到秋天便凋谢了，比喻女主人公的青春不长，红颜易老。这是我国古诗中常用的一种比喻。但是在《庭中有奇树》这一篇中，这一层意思却并不明白说出，而留给读者去细细地体会了。
诗的最后两句：“此物何足贵，但感别经时。”，大意是说：“这花有什么稀罕呢？只是因为别离太久，想借着花儿表达怀念之情罢了。”这是主人公无可奈何、自我宽慰的话，同时也点明了全诗的主题。从前面六句来看，诗人对于花的珍奇美丽，本来是极力赞扬的。可是写到这里，突然又说“此物何足贵”，未免使人有点惊疑。其实，对花落下先抑的一笔，正是为了后扬“但感别经时”这一相思怀念的主题。无论说花的可贵还是不足稀奇，都是为了表达同样的思想感情。但这一抑一扬，诗的感情增强了，最后结句也显得格外突出。诗写到这里，算结束了。然而题外之意，仍然耐人寻味：主人公折花，原是为了解脱相思的痛苦，从中得到一点慰藉；而偏偏所思在天涯，花儿无法寄达，平白又添了一层苦恼；相思怀念更加无法解脱。', '奇树：犹“嘉木”，美好的树木。
滋：当“繁”解。“发华滋”，花开得正繁盛。
荣：犹“花”。
馨香：香气。
致：送达。
贵：一作“贡”，献。
最后二句是说，这枝花本不值得远寄给你，不过离别久了，借以表达怀念之情罢了。', '庭院里一株佳美的树，满树绿叶衬托着繁盛的花朵。
我攀着树枝，摘下了其中一朵，想把它赠送给心中日夜思念的人。
花香充满了我的衣服襟袖之间，可是天遥地远，没能送到心上人的手中。
并不是此花有什么珍贵，只是有感于离别多时，想借着花儿表达思念之情罢了。', '[{"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f61da5fc8182fe9cc02cc", "shortContent": "这诗写一个妇女对远行的丈夫的深切怀念之情。全诗八句，可分作 两个层次。前四句诗描绘了这样一幅图景:在春天的庭院里，有一株嘉 美的树，在满树绿叶的衬托下，开出了茂密的花朵，显得格外生气勃勃，春 意盎然。女主人攀着枝条，折下了最好看的一枝花，要把它赠送给日夜思 念的亲人。\n\n古诗中写女子的相思之情，常常从季节的转换来发端。因为古代妇 女受到封建礼教的严重束缚，生活的圈子很狭小，不像许多男子那样，环 境...", "authors": ["孙明"], "pressName": "上海辞书出版社"}]', '', 'center', 1423179578, '57b9342dc4c971005590da07', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10389, '古诗十九首 · 迢迢牵牛星', NULL, 1523, 496, 3, 13, '无名氏', NULL, 10100, '57b959c18ac2470062e2a00f', '汉', 'shi', '诗', 'http://baike.baidu.com/view/327972.htm', '', '迢迢牵牛星，皎皎河汉女。
纤纤擢素手，札札弄机杼。
终日不成章，泣涕零如雨。
河汉清且浅，相去复几许。
盈盈一水间，脉脉不得语。', '此诗为《古诗十九首》中的第十首。看似写神话传说，而实则是人间爱情生活的真实写照。此诗产生的年代，正是社会动乱时期，男子从征服役，人为地造成家庭破裂、夫妻分别，尤其给劳动妇女造成的是身心上的双重痛苦。夫妇久别是她们的生活，离愁别恨是她们的伴侣，夫妇团聚就成了她们的向往。全诗语言质朴清丽，情趣盎然。', '迢迢（tiáo）：遥远。
牵牛星：隔银河和织女星相对，俗称「牛郎星」，是天鹰星座的主星，在银河东。
皎皎：明亮的样子。河汉女，指织女星，是天琴星座的主星，在银河北。织女星与牵牛星隔河相对。
河汉，即银河。
擢（zhuó）：伸出。
素：白皙。
「纤纤（xiānxiān）擢素手」句：伸出细长而白皙的手。
札（zhá）札：这是一个象声词。正摆弄着织机（织着布），发出札札的织布声。
弄：摆弄。
杼（zhù）：织布机上的梭子。
章：指布帛上的经纬纹理，这里指整幅的布帛。终日不成章：是用《诗经·大东》语意，说织女终日也织不成布。《诗经》原意是织女徒有虚名，不会织布。而这里则是说织女因相思，而无心织布。
涕：眼泪。
零：落下。
去：间隔。
几许：多少。
「河汉清且浅，相去复几许」句：织女和牵牛二星彼此只隔着一条银河，相距能有多远啊？
间（jiàn）：隔，之间。
盈盈：清澈、晶莹的样子。
脉脉（mòmò）：默默地用眼神或行动表达情意。', '（看那天边）遥远明亮的牵牛星和织女星。
（织女）伸出细长而白皙的手，正摆弄着织机（织布），发出札札的织布声。
（她思念牛郎，无心织布），因此一整天也没织成一段布，眼泪像下雨一样落下来。
银河又清又浅，相隔又有多远呢？
相隔在清清浅浅的银河两边，含情脉脉相视无言地痴痴凝望。', '[{"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f61e9902ee364cc8b3552", "shortContent": "牵牛和织女本是两个星宿的名称。牵牛星即“河鼓二”，在银河东。 织女星又称“天孙”，在银河西，与牵牛相对。在中国关于牵牛和织女的民 间故事起源很早。《诗·小雅·大东》已经写到了牵牛和织女，但还只是 作为两颗星来写的。《春秋元命苞》和《淮南子·俶真》开始说织女是神 女。而在曹丕的《燕歌行》，曹植的《洛神赋》和《九咏》里，牵牛和织女已成 为夫妇了。曹植《九咏》曰:“牵牛为夫，织女为妇。织女牵牛之星各处河...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}]', '', 'center', 1423178994, '57af3d8b0a2b5800631d0849', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10390, '古诗十九首 · 生年不满百', NULL, 312, 496, 3, 1, '无名氏', NULL, 10100, '57b959c18ac2470062e2a00f', '汉', 'shi', '诗', 'http://baike.baidu.com/view/1163096.htm', '', '生年不满百，常怀千岁忧。
昼短苦夜长，何不秉烛游！
为乐当及时，何能待来兹。
愚者爱惜费，但为后世嗤。
仙人王子乔，难可与等期。', '此诗选自《古诗十九首》，是一首东汉的五言诗，作者未知。本诗劝人通达世事，及时行乐，不必为那些毫无益处的事而日夜烦忧，并讽刺了那些贪图富贵者不懂得领悟人生的愚昧无知。', '秉烛游：犹言作长夜之游。秉，执也。
来兹：因为草生一年一次，所以训「兹」为「年」，这是引申义。「来兹」，就是「来年」。
费：费用，指钱财。
嗤：轻蔑的笑。
王子乔：古代传说中著名的仙人之一。
期：待也，谓成仙之事不是一般人所能期待。', '一个人活在世上通常不满百岁，心中却老是记挂着千万年后的忧愁，这是何苦呢？
既然老是埋怨白天是如此短暂，黑夜是如此漫长，那么何不拿着烛火，日夜不停地欢乐游玩呢？
人生应当及时行乐才对啊！何必总要等到来年呢？
整天不快乐的人，只想为子孙积攒财富的人，就显得格外愚蠢，不肖子孙也只会嗤笑祖先的不会享福！
像王子乔那样成仙的人，恐怕难以再等到吧！', '[{"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f623945e4710056f1e4f2", "shortContent": "人生价值的怀疑，似乎常是因了生活的苦闷。在苦闷中看人生，许多 传统的观念，都会在怀疑的目光中轰然倒塌。这首诗即以松快的旷达之 语，给世间的两类追求者，兜头浇了一桶冷水。\n\n首先是对吝啬聚财的“惜费”者的嘲讽，它几乎占了全诗的主要篇幅。 这类人正如《诗经·唐风》“山有枢”一诗所讥刺的:“子有衣裳，弗曳弗娄(穿裹着);子有车马，弗驰弗驱。宛其死矣，他人是愉”———只管苦苦地聚 敛财货，就不知道及时享受...", "authors": ["潘啸龙"], "pressName": "上海辞书出版社"}]', '', 'center', 1363637595, '57b8f70cdf0eea0063349f79', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10391, '木兰诗', NULL, 1323, 48, 18, 4, '无名氏', NULL, 10101, '57b9024a0a2b58005c9249cc', '南北朝', 'shi', '诗', 'http://baike.baidu.com/view/72261.htm', '', '唧唧复唧唧，木兰当户织。不闻机杼声，唯闻女叹息。
问女何所思，问女何所忆。女亦无所思，女亦无所忆。昨夜见军帖，可汗大点兵，军书十二卷，卷卷有爷名。阿爷无大儿，木兰无长兄，愿为市鞍马，从此替爷征。
东市买骏马，西市买鞍鞯，南市买辔头，北市买长鞭。旦辞爷娘去，暮宿黄河边，不闻爷娘唤女声，但闻黄河流水鸣溅溅。旦辞黄河去，暮至黑山头，不闻爷娘唤女声，但闻燕山胡骑鸣啾啾。
万里赴戎机，关山度若飞。朔气传金柝，寒光照铁衣。将军百战死，壮士十年归。
归来见天子，天子坐明堂。策勋十二转，赏赐百千强。可汗问所欲，木兰不用尚书郎，愿驰千里足，送儿还故乡。
爷娘闻女来，出郭相扶将；阿姊闻妹来，当户理红妆；小弟闻姊来，磨刀霍霍向猪羊。开我东阁门，坐我西阁床。脱我战时袍，著我旧时裳。当窗理云鬓，对镜帖花黄。出门看火伴，火伴皆惊忙：同行十二年，不知木兰是女郎。
雄兔脚扑朔，雌兔眼迷离；双兔傍地走，安能辨我是雄雌？', '《木兰诗》，又名《木兰辞》，约作于北魏，最初录于南朝陈朝释智匠《古今乐录》，长三百馀字，后经隋唐文人润色。一说《木兰诗》是唐人韦元甫所作，《文苑英华·卷三三三》载《木兰歌》，并题作者为唐人韦元甫。宋朝郭茂倩《乐府诗集》载：「唐人韦元甫拟作木兰诗一篇。」并归入《横吹曲辞·梁鼓角横吹曲》中。严羽《沧浪诗话》认为「朔气传金柝，寒光照铁衣」之类，「已似太白，必非汉魏人诗」。
这是一首长篇叙事诗，讲述讲述了一个叫木兰的女孩，女扮男装，替父从军，在战场上建立功勋，回朝后不愿作官，只求回家团聚的故事，热情赞扬了这位女子勇敢善良的品质、保家卫国的热情和英勇无畏的精神。全诗以「木兰是女郎」来构思木兰的传奇故事，富有浪漫色彩；详略安排极具匠心，富有生活气息；以铺陈、排比、对偶、互文等手法描述人物情态，刻画人物心理，生动细致，使作品具有强烈的艺术感染力。', '唧（jī）唧：纺织机的声音。一说为叹息声，意思是木兰无心织布，停机叹息。首句一作「唧唧何力力」。
当（dāng）户：对着门或在门旁，泛指在家中。
机杼（zhù）声：织布机发出的声音。机，指织布机；杼，织布的梭子。
唯：只。
何：什么。
忆：思念，惦记
军帖（tiě）：徵兵的文书。
可汗（kèhán）：古代西北地区少数民族对君主的称呼。大点兵：大规模征兵。
军书十二卷：征兵的名册很多卷。十二，表示很多，不是确指。下文的「十年」、「十二转」、「十二年」，用法与此相同。
爷：和下文的「阿爷」一样，都指父亲。当时北方呼父为「阿爷」。
鞍马：马匹和乘马用具。《新唐书·兵志》载：起自西魏的府兵制规定从军的人要自备武器、粮食和衣服。
愿为市鞍（ān）马：为，为此（指代父从军）。市，买。
鞯（jiān）：马鞍下的垫子。
辔（pèi）头：驾驭牲口用的嚼子、笼头和缰绳。
辞：离开、辞行。
溅（jiān）溅：水流激射的声音。
旦：早晨。
但闻：只听见。
胡骑（jì）：胡人的战马。胡，古代对北方少数民族的称呼。
啾（jiū）啾：马叫的声音。
戎机：军机，指战争。
万里赴戎机：不远万里，奔赴战场。
关山度若飞：像飞一样地跨过一道道的关，越过一座座的山。度，越过。
金柝（tuò），即刁斗。古代军中用的一种铁锅，白天用来做饭，晚上用来报更。一说金为刁斗，柝为木柝。李善注：「金，谓刁斗也。衞宏《汉旧仪》曰：昼漏尽，夜漏起，城门击刁斗，周庐击木柝。」
朔（shuò）气传金柝：北方的寒气传送着打更的声音。朔，北方。
寒光照铁衣：冰冷的月光照在将士们的铠甲上。寒光，指清冷的月光，铁衣，古代战士穿的带有铁片的战衣。
天子：即前面所说的「可汗」。
明堂：皇帝用来祭祀、接见诸侯、选拔等所用的殿堂。
转（zhuǎn）：勋级每升一级叫一转，十二转为最高的勋级。
十二转：不是确数，形容功劳极高。
策勋十二转：记很大的功。策勋，记功。
赏赐百千强（qiáng）：赏赐很多的财物。百千，形容数量多；强，有余。
问所欲：问（木兰）想要什么。
不用：不为、不做。
尚书郎：官名，魏晋以后在尚书台（省）下分设若干曹（部），主持各曹事务的官通称尚书郎。
千里足：可驰千里的脚力，指好马。一作「愿借明驼千里足」，均指愿得良骑速回故乡。
「爷娘闻女来，出郭相扶将。」句：谓父母互相搀扶着到城外来迎接木兰。郭，外城；扶，扶持；将，助词。
姊（zǐ）：姐姐。
理：梳理。
红妆（zhuāng）：指女子的艳丽装束。
霍（huò）霍：磨刀迅速时发出的声音。一说，刀光闪动疾速貌。
著（zhuó）：通假字通「着」，穿。
云鬓（bìn）：像云那样的鬓发，形容好看的头发。
帖（tiē）花黄：当时流行的一种化妆款饰，把金黄色的纸剪成星、月、花、鸟等形状贴在额上，或在额上涂一点黄的颜色。帖，同「贴」；花黄，古代妇女的一种面部装饰物。
火伴：古时兵制，十人为一火，火伴即同火的人。
「雄兔脚扑朔，雌兔眼迷离。」句：据说，提着兔子的耳朵悬在半空时，雄兔两只前脚时时动弹，雌兔两只眼睛时常眯着，所以容易辨认。扑朔，形容雄兔脚上的毛蓬松的样子；迷离，形容雌兔的眼睛被蓬松的毛遮蔽的样子。
「双兔傍（bàng）地走，安能辨我是雄雌？」句：当两只兔子一起在地上跑时便区别不出它们的雌雄。傍地走，指在地上跑。以上四句通过雄兔雌兔在跑动时不能区别的比喻，对木兰的才能和智慧加以赞扬和肯定，传达了一种「谁说女子不如男」的观念。', '叹息声一声接着一声传出，木兰对着房门织布。听不见织布机织布的声音，只听见木兰在叹息。问木兰在想什么？问木兰在惦记什么？（木兰答道）我也没有在想什么，也没有在惦记什么。昨天晚上看见徵兵文书，知道君主在大规模征兵，那么多卷徵兵文册，每一卷上都有父亲的名字。父亲没有大儿子，木兰（我）没有兄长，木兰愿意为此到集市上去买马鞍和马匹，就开始替代父亲去征战。
在集市各处购买马具。第二天早晨离开父母，晚上宿营在黄河边，听不见父母呼唤女儿的声音，只能听到黄河水流水声。第三天早晨离开黄河上路，晚上到达黑山头，听不见父母呼唤女儿的声音，只能听到燕山胡兵战马的啾啾的鸣叫声。
不远万里奔赴战场，翻越重重山峰就像飞起来那样迅速。北方的寒气中传来打更声，月光映照着战士们的铠甲。将士们身经百战，有的为国捐躯，有的转战多年胜利归来。
胜利归来朝见天子，天子坐在殿堂（论功行赏）。给木兰记很大的功勋，得到的赏赐有千百金还有余。天子问木兰有什么要求，木兰说不愿做尚书郎，希望骑上千里马，回到故乡。
父母听说女儿回来了，互相搀扶着到城外迎接她；姐姐听说妹妹回来了，对着门户梳妆打扮起来；弟弟听说姐姐回来了，忙着霍霍地磨刀杀猪宰羊。每间房都打开了门进去看看，脱去打仗时穿的战袍，穿上以前女孩子的衣裳，当着窗子、对着镜子整理漂亮的头发，对着镜子在面部贴上装饰物。走出去看一起打仗的火伴，火伴们很吃惊，（都说我们）同行数年之久，竟然不知木兰是女孩。
（提着兔子耳朵悬在半空中时）雄兔两只前脚时时动弹、雌兔两只眼睛时常眯着，所以容易分辨。雄雌两兔一起并排跑，怎能分辨哪个是雄兔哪个是雌兔呢？', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccea5914587d02f59a83", "shortContent": "《木兰诗》，北朝民歌之绝唱也。这首长篇叙事诗，歌唱的是木兰女扮男装替父从军的传奇故事。\n《木兰诗》最早著录于陈释智匠《古今乐录》，可证其产生之时代不晚于陈。诗中称天子为“可汗”，征战地点皆在北方，则其产生之地域在北朝。诗中有“旦辞黄河去，暮至黑山头”，“但闻燕山胡骑鸣啾踿”语。黑山即杀虎山，在今内蒙古呼和浩特市东南，去黄河不远。燕山指燕然山，即今蒙古国杭爱山。据此，《木兰诗》中之战事，当发生于北魏...", "authors": ["邓小军"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471eaf9e49f46528add5be2", "shortContent": "《木兰诗》是祖国诗史上罕有的杰作，诗中首次塑造了一位替父从军的女英雄形象。木兰完满具备了英雄品格与女性特点。天性善良勇敢，沉着机智，坚韧不拔，是木兰英雄品格之必要内涵，对父母对祖国之无限爱心和献身精神，则是其英雄品格之最大精神力量源泉。同时，全诗紧扣“木兰是女郎”，从“不闻爷娘唤女声”到“木兰不用尚书郎”，从“木兰当户织”到“著我旧时裳”，始终不失其为女性之特点。故木兰形象极为真实感人。《木兰诗》...", "authors": ["邓小军"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "6470b4987f27182da3873a71", "shortContent": "《木兰诗》，北朝民歌之绝唱也。这首长篇叙事诗，歌唱的是木兰女扮 男装替父从军的传奇故事。\n\n《木兰诗》最早著录于陈释智匠《古今乐录》，可证其产生之时代不晚 于陈。诗中称天子为“可汗”，征战地点皆在北方，则其产生之地域在北 朝。诗中有“旦辞黄河去，暮至黑山头”，“但闻燕山胡骑鸣啾啾”语。黑山 即杀虎山，在今内蒙古呼和浩特市东南，去黄河不远。燕山指燕然山，即 今蒙古人民共和国杭爱山。据此，《木兰诗》中...", "authors": ["邓小军"], "pressName": "上海辞书出版社"}]', '', 'indent', 1363638015, '57b9024d128fe10054c99652', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10392, '古诗为焦仲卿妻作 · 孔雀东南飞', NULL, 262, 112, 6, 9, '两汉乐府', NULL, 18119, '5831d697a22b9d006b8ec08c', '汉', 'shi', '诗', 'http://baike.baidu.com/subview/26343/7538852.htm', '汉末建安中，庐江府小吏焦仲卿妻刘氏，为仲卿母所遣，自誓不嫁。其家逼之，乃投水而死。仲卿闻之，亦自缢于庭树。时人伤之，为诗云尔。', '孔雀东南飞，五里一徘徊。
「十三能织素，十四学裁衣，十五弹箜篌，十六诵诗书。十七为君妇，心中常苦悲。君既为府吏，守节情不移，贱妾留空房，相见常日稀。鸡鸣入机织，夜夜不得息。三日断五匹，大人故嫌迟。非为织作迟，君家妇难为！妾不堪驱使，徒留无所施，便可白公姥，及时相遣归。」
府吏得闻之，堂上启阿母：「儿已薄禄相，幸复得此妇，结发同枕席，黄泉共为友。共事二三年，始尔未为久，女行无偏斜，何意致不厚？」
阿母谓府吏：「何乃太区区！此妇无礼节，举动自专由，吾意久怀忿，汝岂得自由！东家有贤女，自名秦罗敷，可怜体无比，阿母为汝求。便可速遣之，遣去慎莫留！」
府吏长跪告：「伏惟启阿母，今若遣此妇，终老不复取！」
阿母得闻之，槌床便大怒：「小子无所畏，何敢助妇语！吾已失恩义，会不相从许！」
府吏默无声，再拜还入户，举言谓新妇，哽咽不能语：「我自不驱卿，逼迫有阿母。卿但暂还家，吾今且报府。不久当归还，还必相迎取。以此下心意，慎勿违吾语。」
新妇谓府吏：「勿复重纷纭。往昔初阳岁，谢家来贵门。奉事循公姥，进止敢自专？昼夜勤作息。伶俜萦苦辛。谓言无罪过，供养卒大恩；仍更被驱遣，何言复来还！妾有绣腰襦，葳蕤自生光；红罗复斗帐，四角垂香囊；箱帘六七十，绿碧青丝绳，物物各自异，种种在其中。人贱物亦鄙，不足迎后人，留待作遗施，于今无会因。时时为安慰，久久莫相忘！」
鸡鸣外欲曙，新妇起严妆。著我绣夹裙，事事四五通。足下蹑丝履，头上玳瑁光。腰若流纨素，耳著明月珰。指如削葱根，口如含朱丹。纤纤作细步，精妙世无双。
上堂拜阿母，阿母怒不止。「昔作女儿时，生小出野里，本自无教训，兼愧贵家子。受母钱帛多，不堪母驱使。今日还家去，念母劳家里。」却与小姑别，泪落连珠子。「新妇初来时，小姑始扶床；今日被驱遣，小姑如我长。勤心养公姥，好自相扶将。初七及下九，嬉戏莫相忘。」出门登车去，涕落百馀行。
府吏马在前，新妇车在后，隐隐何甸甸，俱会大道口。下马入车中，低头共耳语：「誓不相隔卿，且暂还家去；吾今且赴府，不久当还归，誓天不相负！」
新妇谓府吏：「感君区区怀！君既若见录，不久望君来。君当做磐石，妾当做蒲苇，蒲苇纫如丝，磐石无转移。我有亲父兄，性行暴如雷，恐不任我意，逆以煎我怀。」举手长劳劳，二情同依依。
入门上家堂，进退无颜仪。阿母大拊掌，不图子自归：「十三教汝织，十四能裁衣，十五弹箜篌，十六知礼仪，十七遣汝嫁，谓言无誓违。汝今何罪过，不迎而自归？」兰芝惭阿母：「儿实无罪过。」阿母大悲摧。
还家十余日，县令遣媒来。云有第三郎，窈窕世无双，年始十八九，便言多令才。
阿母谓阿女：「汝可去应之。」
阿女含泪答：「兰芝初还时，府吏见丁宁，结誓不别离。今日违情义，恐此事非奇。自可断来信，徐徐更谓之。」
阿母白媒人：「贫贱有此女，始适还家门。不堪吏人妇，岂合令郎君？幸可广问讯，不得便相许。」媒人去数日，寻遣丞请还，说有兰家女，承籍有宦官。云有第五郎，娇逸未有婚。遣丞为媒人，主薄通语言。直说太守家，有此令郎君，既欲结大义，故遣来贵门。
阿母谢媒人：「女子先有誓，老姥岂敢言！」
阿兄得闻之，怅然心中烦，举言谓阿妹：「作计何不量！先嫁得府吏，后嫁得郎君，否泰如天地，足以荣汝身。不嫁义郎体，其往欲何云？」
兰芝仰头答：「理实如兄言。谢家事夫婿，中道还兄门。处分适兄意，那得自任专！虽与府吏要，渠会永无缘。登即相许和，便可作婚姻。」
媒人下床去，诺诺复尔尔。还部白府君：「下官奉使命，言谈大有缘。」府君得闻之，心中大欢喜。视历复开书，便利此月内，六合正相应。良吉三十日，今已二十七，卿可去成婚。交语速装束，络绎如浮云。青雀白鹄舫，四角龙子幡，婀娜随风转。金车玉作轮，踯躅青骢马，流苏金镂鞍。赍钱三百万，皆用青丝穿。杂彩三百匹，交广市鲑珍。从人四五百，郁郁登郡门。
阿母谓阿女：「适得府君书，明日来迎汝。何不作衣裳？莫令事不举！」
阿女默无声，手巾掩口啼，泪落便如泻。移我琉璃榻，出置前窗下。左手持刀尺，右手执绫罗。朝成绣夹裙，晚成单罗衫。晻晻日欲暝，愁思出门啼。
府吏闻此变，因求假暂归。未至二三里，摧藏马悲哀。新妇识马声，蹑履向逢迎。怅然遥相望，知是故人来。举手拍马鞍，嗟叹使心伤：「自君别我后，人事不可量。果不如先愿，又非君所详。我有亲父母，逼迫兼弟兄，以我应他人，君还何所望！」
府吏谓新妇：「贺卿得高迁！磐石方且厚，可以卒千年。蒲苇一时韧，便作旦夕间。卿当日胜贵，吾独向黄泉！」
新妇谓府吏：「何意出此言！同是被逼迫，君尔妾亦然。黄泉下相见，勿违今日言！」执手分道去，各各还家门。生人作死别，恨恨那可论？念与世间辞，千万不复全！
府吏还家去，上堂拜阿母：「今日大风寒，寒风摧树木，严霜结庭兰。儿今日冥冥，令母在后单。故作不良计，勿复怨鬼神！命如南山石，四体康且直！」
阿母得闻之，零泪应声落：「汝是大家子，仕宦于台阁，慎勿为妇死，贵贱情何薄！东家有贤女，窈窕艳城郭，阿母为汝求，便复在旦夕。」
府吏再拜还，长叹空房中，作计乃尔立。转头向户里，渐见愁煎迫。
其日牛马嘶，新妇入青庐。奄奄黄昏后，寂寂人定初。「我命绝今日，魂去尸长留！」揽裙脱丝履，举身赴清池。
府吏闻此事，心知长别离，徘徊庭树下，自挂东南枝。
两家求合葬，合葬华山傍。东西植松柏，左右种梧桐。枝枝相覆盖，叶叶相交通。中有双飞鸟，自名为鸳鸯，仰头相向鸣，夜夜达五更。行人驻足听，寡妇起彷徨。多谢后世人，戒之慎勿忘！', '《孔雀东南飞》是中国古代汉族文学史上最早的一首长篇叙事诗，中国古代最优秀的民间叙事诗，也是古代汉民族最长的叙事诗。作为汉乐府叙事诗发展的高峰，也是中国文学史上现实主义诗歌发展中的重要标志。它原名为《古诗为焦仲卿妻作》，最早见于《玉台新咏》，作者不详，是以真人真事为基础创作的。全诗三百五十七句，共一千七百八十五个字，沈归愚称为「古今第一首长诗」，与《木兰辞》并称「乐府双璧」，乐府双壁加上唐代韦庄的《秦妇吟》又被并称为「乐府三绝」。', '建安中：建安年间（西元一九六年至二一九年）。建安，东汉献帝年号。
庐江：汉代郡名，郡城在今安徽潜山一带。
遣：女子出嫁后被夫家休弃回娘家。
云尔：句末语气词。如此而已。
徘徊（páihuái）：来回走动。汉代乐府诗常以飞鸟徘徊起兴，以写夫妇离别。
素：白绢。这句话开始到「及时相遣归」是焦仲卿妻对仲卿说的。
箜篌（kōnghóu）：古代的一种絃乐器，形如筝、瑟。
诗书：原指《诗经》和《尚书》，这里泛指儒家的经书。
守节：遵守府里的规则。
断：（织成一匹）截下来。
大人故嫌迟：婆婆故意嫌我织得慢。大人，对长辈的尊称，这里指婆婆。
不堪：不能胜任。
徒：徒然，白白地。
施：用。
白公姥（mǔ）：禀告婆婆。白，告诉、禀告；公姥，公公婆婆，这里是偏义复词，专指婆婆。
薄禄相：官禄微薄的相貌。
结髮：束髮。古时候的人到了一定的年龄（男子二十岁，女子十五岁）才把头发结起来，算是到了成年，可以结婚了。
始尔：刚开始。尔，助词，无义。一说是代词，这样。
致不厚：招致不喜欢。致，招致；厚，厚待，这里是「喜欢」的意思。
区区：小，这里指见识短浅。
自专由：与下句「汝岂得自由」中的「自由」都是自作主张的意思。专，独断专行；由，随意、任意。
贤：这里指聪明贤惠。
可怜：可爱。
伏惟：趴在地上想。古代下级对上级或小辈对长辈说话表示恭敬的习惯用语。
取：通「娶」，娶妻。
床：古代的一种坐具。
会不相从许：当然不能答应你的要求。会，当然、必定。
举言：发言、开口。
新妇：媳妇（不是新嫁娘）。「新妇」是汉代末年对已嫁妇女的通称。
报府：赴府，指回到庐江太守府。
下心意：低心下意，受些委屈。
勿复重（chóng）纷纭：不必再添麻烦吧。也就是说，不必再提接她回来的话了。
初阳岁：农历冬末春初。
谢：辞别。
作息：原意是工作和休息，这里是偏义复词，专指工作。
伶俜萦（pīngyíng）苦辛：孤孤单单，受尽辛苦折磨。伶俜，孤单的样子；萦，缠绕。
谓言：总以为。
卒：完成，引申为报答。
绣腰襦（rú）：绣花的齐腰短袄。
葳蕤（wēiruí）：草木繁盛的样子，这里形容短袄上刺绣的花叶繁多而美丽。
箱：衣箱。
帘：通「奁」，古代妇女梳妆用的镜匣。
后人：指府吏将来再娶的妻子。
遗（wèi）施：赠送、施与。
会因：会面的机会。
严妆：整妆，郑重地梳妆打扮。
通：次、遍。
蹑（niè）：踩、踏，这里指穿鞋。
玳瑁（dàimào）：一种同龟相似的爬行动物，甲壳可制装饰品。
珰（dāng）：耳坠。
昔作女儿时：以下八句是仲卿妻对焦母告别时说的话。
野里：乡间。
兼愧：更有愧于……。
却：从堂上退下来。
扶将：扶持、搀扶。这里是服侍的意思。
初七：指农历七月七日，旧时妇女在这天晚上在院子里陈设瓜果，向织女星祈祷，祈求提高刺绣缝纫技巧，称为「乞巧」。
下九：古人以每月的二十九为上九，初九为中九，十九为下九。在汉朝时候，每月十九日是妇女欢聚的日子。
隐隐：和下面的「甸甸」都是象声词，指车声。
誓不相隔卿……誓天不相负：这是府吏对兰芝说的话。
区区：这里是诚挚的意思，与上面「何乃太区区」中的「区区」意思不同。
若见录：如此记住我。见录，记着我；见，被；录，记。
纫：通「韧」，柔韧牢固。
亲父兄：即同胞兄。
逆：逆料，想到将来。
劳劳：怅惘若失的样子。
颜仪：脸面、面子。
拊（fǔ）掌：拍手，这里表示惊异。
子自归：你自己回来。意思是，没料到女儿竟被驱遣回家。古代女子出嫁以后，一定要娘家得到婆家的同意，派人迎接，才能回娘家。下文「不迎而自归」，也是按这种规矩说的责备的话。
无誓违：不会有什么过失。誓，似应作「諐」（古「愆（qiān）」字），愆违、过失。
悲摧：悲痛、伤心。
窈窕（yǎotiǎo）：容貌体态美好的样子。
便（pián）言多令才：口才很好，又多才能。便言，很会说话；令，美好。
丁宁：嘱咐我。丁宁，嘱咐，后写作「叮咛」。
非奇：不宜、不妥。
断来信：回绝来做媒的人。断，回绝；信，使者，指媒人。
更谓之：再谈它。之，指再嫁之事。
适：出嫁。
不堪：这里是「不能做」的意思。
媒人去数日……丞籍有宦官：这几句可能有文字脱漏或错误，因此无法解释清楚。这里列出部分字的意义解释：寻，随即、不久；丞，县丞；承籍，承继先人的仕籍；宦官，即「官宦」，指做官的人。
娇逸：娇美文雅。
主簿：太守的属官。
作计：拿主意、打算。
量（liáng）：考虑。
否（pǐ）泰：都是《易经》中的卦名。这里指运气的好坏。否，坏运气；泰，好运气。
义郎：男子的美称，这里指太守的儿子。
其往欲何云：往后打算怎么办。其往，其后、将来；何云，这里指怎么办。
处分：处置。
适：依照。
要（yāo）：相约。
渠（qú）会：同他相会。渠，他。一说是那种相会。渠，那。
登即：立即。
尔尔：如此如此。等于说「就这样，就这样」。
府君：对太守的尊称。
下官：县丞自称。
缘：缘分。
视历：翻看历书。
六合：古时候迷信的人，结婚要选好日子，要年、月、日的干支（干，天干，甲、乙、丙、丁……支，地支，子、丑、寅、卯……）合起来都相适合，这叫「六合」。
卿：你，指县丞。
交语：交相传话。
舫（fǎng）：船。
龙子幡（fān）：绣龙的旗帜。
婀娜（ēnuó）：轻轻飘动的样子。
踯躅（zhízhú）：缓慢不进的样子。
青骢（cōng）马：青白杂毛的马。
流苏：用五彩羽毛做的下垂的缨子。
赍（jī）：赠送。
杂彩：各种颜色的绸缎。
交广：交州、广州，古代郡名，这里泛指今广东、广西一带。
鲑（xié）：这里是鱼类菜肴的总称。
郁郁：繁盛的样子。
适：刚才。
不举：办不成。
榻（tà）：坐具。
晻晻（yǎnyǎn）：日色昏暗无光的样子。
摧藏（zàng）：摧折心肝。藏，脏腑。
人事不可量：人间的事不能预料。
父母：这里偏指母。
弟兄：这里偏指兄。
日胜贵：一天比一天高贵。
恨恨：抱恨不已，这里指极度无奈。
日冥冥：原意是日暮，这里用太阳下山来比喻生命的终结。
单：孤单。
故：有意，故意。
不良计：不好的打算（指自杀）。
四体：四肢，这里指身体。
直：意思是腰板硬朗。
台阁：原指尚书台，这里泛指大的重府。
乃尔立：就这样决定。
青庐：用青布搭成的篷帐，举行婚礼的地方。
奄奄：通「晻晻」，日色昏暗无光的样子。
黄昏：古时计算时间按十二地支将一日分为十二个「时辰」。「黄昏」是「戌时」（相当于现代的晚上七时至九时）。下句的「人定」是「亥时」（相当于现代的晚上九时至十一时）。
华山：庐江郡内的一座小山。
交通：交错，这里指挨在一起。
驻足：停步。
谢：告诉。', '东汉末年建安年间，庐江府小吏焦仲卿的妻子刘氏，被仲卿的母亲驱赶回娘家，她发誓不再改嫁。但她娘家的人一直逼着她再嫁，她只好投水自尽。焦仲卿听到妻子的死讯后，也吊死在自己家里庭院的树上。当时的人哀悼他们，便写了这样一首诗。
孔雀朝着东南方向飞去，每飞五里便是一阵徘徊。
「我十三岁就能织出白色的丝绢，十四岁就学会了裁衣。十五岁学会弹箜篌，十六岁就能诵读诗书。十七岁做了你的妻子，但心中常常感到痛苦伤悲。你既然已经做了府吏，当然会坚守臣节专心不移。只留下我孤身一人待在空房，我们见面的日子常常是日渐疏稀。每天当鸡叫的时候我就进入机房纺织，天天晚上都不能休息。三天就能在机上截下五匹布，但婆婆还故意嫌我缓慢松弛。不是我纺织缓慢行动松弛，而是你家的媳妇难做公婆难服侍。我已经受不了你家这样的驱使，徒然留下来也没有什么用处无法再驱驰。你这就禀告公公婆婆，及时遣返我送我回娘家去。」
府吏听到这些话，便走到堂上禀告阿母：「儿已经没有做高官享厚禄的福相，幸而娶得这样一个好媳妇。刚成年时我们便结成同床共枕的恩爱夫妻，并希望同生共死直到黄泉也相伴为伍。我们共同生活才过了两三年，这种甜美的日子只是开头还不算长久。她的行为没有什么不正当，哪里知道竟会招致你的不满得不到慈爱亲厚。」
阿母对府吏说：「你怎么这样狭隘固执！这个媳妇不懂得礼节，行动又是那样自专自由。我心中早已怀着愤怒，你哪能自作主张对她迁就。东邻有个贤惠的女子，她本来的名字叫秦罗敷。她可爱的体态没有谁能比得上，我当为你的婚事去恳求。你就应该把兰芝快赶走，把她赶走千万不要让她再停留！」
府吏直身长跪作回答，他恭恭敬敬地再向母亲哀求：「现在如果赶走这个媳妇，儿到老也不会再娶别的女子！」
阿母听了府吏这些话，便敲着坐床大发脾气：「你这小子胆子太大毫无畏惧，你怎么敢帮着媳妇胡言乱语。我对她已经断绝了情谊，对你的要求决不会依从允许！」
府吏默默不说话，再拜之后辞别阿母回到自己的房里。开口向媳妇说话，悲痛气结已是哽咽难语：「我本来不愿赶你走，但阿母逼迫着要我这样做。但你只不过是暂时回到娘家去，现在我也暂且回到县官府。不久我就要从府中回家来，回来之后一定会去迎接你。你就为这事委屈一下吧，千万不要违背我这番话语。」
兰芝对府吏坦陈：「不要再（说）提前接我回来这样的话了！记得那年初阳的时节，我辞别娘家走进你家门。侍奉公婆都顺着他们的心意，一举一动哪里敢自作主张不守本分？日日夜夜勤劳地操作，孤身一人周身缠绕着苦辛。自以为可以说是没有什么罪过，能够终身侍奉公婆报答他们的大恩。但仍然还是要被驱赶，哪里还谈得上再转回你家门。我有一件绣花的短袄，绣着光彩美丽的花纹。还有一床红罗做的双层斗形的小帐，四角都垂挂着香囊。大大小小的箱子有六七十个，都是用碧绿的丝线捆扎紧。里面的东西都各不相同，各种各样的东西都收藏其中。人既然低贱东西自然也卑陋，不值得用它们来迎娶后来的新人。你留着等待以后有机会施舍给别人吧，走到今天这一步今后不可能再相会相亲。希望你时时安慰自己，长久记住我不要忘记我这苦命的人。」
当公鸡鸣叫窗外天快要放亮，兰芝起身精心地打扮梳妆。她穿上昔日绣花的裌裙，梳妆打扮时每件事都做了四五遍才算妥当。脚下她穿着丝鞋，头上的玳瑁簪闪闪发光。腰间束着流光的白绸带，耳边挂着明月珠装饰的耳珰。十个手指像尖尖的葱根又细又白嫩，嘴唇涂红像含着朱丹一样。她轻轻地小步行走，艳丽美妙真是举世无双。
她走上堂去拜别阿母，阿母听任她离去而不挽留阻止。「从前我做女儿的时候，从小就生长在村野乡里。本来就没有受到教管训导，更加惭愧的是又嫁到你家愧对你家的公子。受了阿母许多金钱和财礼，却不能胜任阿母的驱使。今天我就要回到娘家去，还记挂着阿母孤身操劳在家里。」她退下堂来又去向小姑告别，眼泪滚滚落下像一连串的珠子。「我这个新媳妇初嫁过来时，小姑刚学走路始会扶床。今天我被驱赶回娘家，小姑的个子已和我相当。希望你尽心地侍奉我的公婆，好好地扶助他们精心奉养。每当七夕之夜和每月的十九日，玩耍时千万不要把我忘。」她走出家门上车离去，眼泪落下百多行。
府吏骑着马走在前头，兰芝坐在车上跟在后面走。车声时而小声隐隐时而大声甸甸，但车和马都一同到达了大道口。府吏下马走进车中，低下头来在兰芝身边低声细语：「我发誓不同你断绝，你暂且回到娘家去，我今日也暂且赶赴官府。不久我一定会回来，我向天发誓永远不会辜负你。」
兰芝对府吏说：「感谢你对我的诚心和关怀。既然承蒙你这样的记着我，不久之后我会殷切地盼望着你来。你应当像一块大石，我必定会像一株蒲苇。蒲苇像丝一样柔软但坚韧结实，大石也不会转移。只是我有一个亲哥哥，性情脾气不好常常暴跳如雷。恐怕不能任凭我的心意由我自主，他一定会违背我的心意使我内心饱受熬煎。」两人忧伤不止地举手告别，双方都依依不舍情意绵绵。
兰芝回到娘家进了大门走上厅堂，进退为难觉得脸面已失去。母亲十分惊异地拍着手说道：「想不到没有去接你你竟自己回到家里。十三岁我就教你纺织，十四岁你就会裁衣，十五岁会弹箜篌，十六岁懂得礼仪，十七岁时把你嫁出去，总以为你在夫家不会有什么过失。你现在有什么过失？为什么没有去接你你自己回到家里？」「兰芝十分惭愧面对亲娘，女儿实在没有什么过失。」亲娘听了十分伤悲。
回家才过了十多日，县令便派遣了一个媒人来提亲。说县太爷有个排行第三的公子，身材美好举世无双。年龄只有十八九岁，口才很好文才也比别人强。
亲娘便对女儿说：「你可以出去答应这门婚事。」
兰芝含着眼泪回答说：「兰芝当初返家时，府吏一再嘱咐我，发誓永远不分离。今天如果违背了他的情义，这门婚事就大不吉利。你就可以去回绝媒人，以后再慢慢商议。」
亲娘出去告诉媒人：「我们贫贱人家养育了这个女儿，刚出嫁不久便被赶回家里，不配做小吏的妻子，哪里适合再嫁你们公子为妻？希望你多方面打听打听，我不能就这样答应你。」
媒人去了几天后，那派去郡里请示太守的县丞刚好回来。他说：「在郡里曾向太守说起一位名叫兰芝的女子，出生于官宦人家。」又说：「太守有个排行第五的儿子，貌美才高还没有娶妻。太守要我做媒人，这番话是由主簿来转达。」县丞来到刘家直接说：「在太守家里，有这样一个美好的郎君，既然想要同你家结亲，所以才派遣我来到贵府做媒人。」
兰芝的母亲回绝了媒人：「女儿早先已有誓言不再嫁，我这个做母亲的怎敢再多说？」
兰芝的哥哥听到后，心中不痛快十分烦恼，向其妹兰芝开口说道：「作出决定为什么不多想一想！先嫁是嫁给一个小府吏，后嫁却能嫁给太守的贵公子。命运好坏差别就像天和地，改嫁之后足够让你享尽荣华富贵。你不嫁这样好的公子郎君，往后你打算怎么办？」
兰芝抬起头来回答说：「道理确实像哥哥所说的一样，离开了家出嫁侍奉丈夫，中途又回到哥哥家里，怎么安排都要顺着哥哥的心意，我哪里能够自作主张？虽然同府吏有过誓约，但同他相会永远没有机缘。立即就答应了吧，就可以结为婚姻。」媒人从坐床走下去，连声说好！好！就这样！就这样！他回到太守府禀告太守：「下官承奉着大人的使命，商议这桩婚事谈得很投机。」太守听了这话以后，心中非常欢喜。他翻开历书反复查看，吉日就在这个月之内，月建和日辰的地支都相合。「成婚吉日就定在三十日，今天已是二十七日，你可立即去办理迎娶的事。」彼此相互传语快快去筹办，来往的人连续不断像天上的浮云。迎亲的船只上画着青雀和白鹄，船的四角还挂着绣着龙的旗子。旗子随风轻轻地飘动，金色的车配着玉饰的轮。驾上那毛色青白相杂的马缓步前进，马鞍两旁结着金线织成的缨子。送了聘金三百万，全部用青丝串联起。各种花色的绸缎三百匹，还派人到交州广州购来海味和山珍。随从人员共有四五百，热热闹闹地齐集太守府前准备去迎亲。
亲娘对兰芝说：「刚才得到太守的信，明天就要来迎娶你。你为什么还不做好衣裳？不要让事情办不成！」
兰芝默默不说话，用手巾掩口悲声啼，眼泪坠落就像流水往下泻。移动她那镶着琉璃的坐榻，搬出来放到前窗下。左手拿着剪刀和界尺，右手拿着绫罗和绸缎。早上做成绣裌裙，傍晚又做成单罗衫。一片昏暗天时已将晚，她满怀忧愁想到明天要出嫁便伤心哭泣。
府吏听到这个意外的变故，便告假请求暂且回家去看看。还未走到刘家大约还有二三里，人很伤心马儿也悲鸣。兰芝熟悉那匹马的鸣声，踏着鞋急忙走出家门去相迎。心中惆怅远远地望过去，知道是从前的夫婿已来临。她举起手来拍拍马鞍，不断叹气让彼此更伤心。「自从你离开我之后，人事变迁真是无法预测和估量。果然不能满足我们从前的心愿，内中的情由又不是你能了解端详。我有亲生的父母，逼迫我的还有我的亲兄长。把我许配了别的人，你还能有什么希望！」
府吏对兰芝说：「祝贺你能够高升！大石方正又坚厚，可以千年都不变。蒲苇虽然一时坚韧，但只能坚持很短的时间。你将一天比一天生活安逸地位显贵，只有我独自一人下到黄泉。」
兰芝对府吏说：「想不到你会说出这样的话！两人同样是被逼迫，你是这样我也是这样受熬煎。我们在黄泉之下再相见，不要违背今天的誓言！」他们握手告别分道离去，各自都回到自己家里面。活着的人却要做死的离别，心中抱恨哪里能够说得完。他们都想很快地离开人世，无论如何也不愿苟且偷生得保全。
府吏回到自己家，上堂拜见阿母说：「今天风大天又寒，寒风摧折了树木，浓霜冻坏了庭院中的兰花。我今天已是日落西山生命将终结，让母亲独留世间以后的日子孤单。我是有意作出这种不好的打算，请不要再怨恨鬼神施责罚！但愿你的生命像南山石一样的久长，身体强健又安康。」
阿母听到了这番话，泪水随着语声往下落：「你是大户人家的子弟，一直做官在官府台阁。千万不要为了一个妇人去寻死，贵贱不同你将她遗弃怎能算情薄？东邻有个好女子，苗条美丽全城称第一。做母亲的为你去求婚，答复就在这早晚之间。」
府吏再拜之后转身走回去，在空房中长叹不已。他的决心就这样定下了，把头转向屋子里，心中忧愁煎迫一阵更比一阵紧。
迎亲的那一天牛马嘶叫，新媳妇兰芝被迎娶进入青色帐篷里。天色昏暗已是黄昏后，静悄悄的四周无声息。「我的生命终结就在今天，只有尸体长久留下我的魂魄将要离去。」她挽起裙子脱下丝鞋，纵身一跳投进了清水池。
府吏听到了这件事，心里知道这就是永远的别离，于是来到庭院大树下徘徊了一阵，自己吊死在东南边的树枝。
两家要求将他们夫妻二人合葬，结果合葬在华山旁。坟墓东西两边种植着松柏，左右两侧栽种梧桐。各种树枝枝枝相覆盖，各种树叶叶叶相连通。中间又有一对双飞鸟，鸟名本是叫鸳鸯，它们抬起头来相对鸣叫，每晚都要鸣叫一直叫到五更。过路的人都停下脚步仔细听，寡妇惊起更是不安和彷徨。我要郑重地告诉后来的人，以此为鉴戒千万不要把它忘。', '[{"bookId": "60d939cea06dc908f045ad24", "bookTitle": "元明清诗鉴赏辞典（新一版）", "articleId": "610e8d1b2e6a6b501f95a694", "shortContent": "清代杭州关吏恶劣贪财出名。蒋士铨《杭州》绝句云：“一肩书剑残冬路，犹检寒衣索税钱。”沈钟《杭榷》古诗亦云：“杭州关吏猛于虎……倒笼倾箱细搜估”。舒位这诗，更是淋漓尽致地把嘉庆年间杭州水路关卡的吏卒如何胡作非为、任意敲诈勒索旅客的强盗行径，如实作了记载，从而有力地揭露了当时捐税杂乱繁多，官吏贪婪凶恶的社会现实。\n诗人曾从威勒侯勒保谋划军事，后勒保改任四川经略，诗人借故辞归，当路过杭州时，记下了这幕丑...", "authors": ["吕美生", "朱永平"], "pressName": "上海辞书出版社"}, {"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecc96911759740c9bd61c", "shortContent": "《孔雀东南飞》最早见于《玉台新咏》，题为《古诗为焦仲卿妻作》。诗前有序文：“汉末建安中，庐江府小吏焦仲卿妻刘氏，为仲卿母所遣，自誓不嫁。其家逼之，乃没水而死。仲卿闻之，亦自缢于庭树。时人伤之，为诗云尔。”这是一曲基于事实而形于吟咏的悲歌。其中，主人公刘兰芝、焦仲卿之死，表面上看来，是由于凶悍的焦母和势利的刘兄逼迫的结果。事实上，焦母、刘兄同样是封建礼教的受害者。因为焦母、刘兄的本意，并不想害死自己...", "authors": ["朱大刚"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f7ddbb8b379ee0aec0d", "shortContent": "“阎王要你三更死，谁敢留人到五更。”这大约是阴司地府的传统规矩。本篇中李除的经历却是例外。他三更时为鬼吏将去，至晓时竟“渐渐得苏”。代价是一只金钏，赤裸裸是贿赂的结果。\n鬼吏是多大的角色我们不太清楚，从篇中的叙述来看，也可能是后代传说的“牛头马面”之类吧。他本身并不掌握生死予夺的大权，却在押行途中不惮为谋取私利而玩忽职守，这就说明了阴曹中贪赃枉法的普遍。李除在“见有行货得免”的众多先例下，“乃许吏...", "authors": ["穆", "俦"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f80911759740c9ca301", "shortContent": "这是一则宣扬佛教的故事。作者通过佛教弟子康阿得死而复生，在阴间所见所闻来宣扬信佛的好处。康阿得被误抓往阴间，按照一般的处理，阴间府君派吏送回人间就是，但康阿得却不然，他受到了特殊的礼遇：首先，府君大怒，斥责错抓康阿得的白马吏，进而将其绑在柱上，鞭打一百。对失职的小吏，如此重罚，殊为少有。同时，府君还给马一匹，随从一个，伴同康阿得游遍地狱，再送他回阳。康阿得为何受到如此礼遇呢？因为他是一个虔诚的佛教...", "authors": ["唐葆祥"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f612d7da2f75ac715832f", "shortContent": "《孔雀东南飞》最早见于《玉台新咏》，题为《古诗为焦仲卿妻作》。诗 前有序文:“汉末建安中，庐江府小吏焦仲卿妻刘氏，为仲卿母所遣，自誓 不嫁。其家逼之，乃没水而死。仲卿闻之，亦自缢于庭树。时人伤之，为 诗云尔。”这是一曲基于事实而形于吟咏的悲歌。其中，主人公刘兰芝、焦 仲卿之死，表面上看来，是由于凶悍的焦母和势利的刘兄逼迫的结果。事 实上，焦母、刘兄同样是封建礼教的受害者。因为焦母、刘兄的本意，并不...", "authors": ["朱大刚"], "pressName": "上海辞书出版社"}]', '', 'indent', 1423178399, '57b916a17db2a200542755bf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10393, '长恨歌', NULL, 2570, 2952, 16, 4, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/28603/6817109.htm', '', '汉皇重色思倾国，御宇多年求不得。
杨家有女初长成，养在深闺人未识。
天生丽质难自弃，一朝选在君王侧。
回眸一笑百媚生，六宫粉黛无颜色。
春寒赐浴华清池，温泉水滑洗凝脂。
侍儿扶起娇无力，始是新承恩泽时。
云鬓花颜金步摇，芙蓉帐暖度春宵。
春宵苦短日高起，从此君王不早朝。
承欢侍宴无闲暇，春从春游夜专夜。
后宫佳丽三千人，三千宠爱在一身。
金屋妆成娇侍夜，玉楼宴罢醉和春。
姊妹弟兄皆列土，可怜光彩生门户。
遂令天下父母心，不重生男重生女。
骊宫高处入青云，仙乐风飘处处闻。
缓歌慢舞凝丝竹，尽日君王看不足。
渔阳鼙鼓动地来，惊破霓裳羽衣曲。
九重城阙烟尘生，千乘万骑西南行。
翠华摇摇行复止，西出都门百余里。
六军不发无奈何，宛转蛾眉马前死。
花钿委地无人收，翠翘金雀玉搔头。
君王掩面救不得，回看血泪相和流。
黄埃散漫风萧索，云栈萦纡登剑阁。
峨嵋山下少人行，旌旗无光日色薄。
蜀江水碧蜀山青，圣主朝朝暮暮情。
行宫见月伤心色，夜雨闻铃肠断声。
天旋日转回龙驭，到此踌躇不能去。
马嵬坡下泥土中，不见玉颜空死处。
君臣相顾尽沾衣，东望都门信马归。
归来池苑皆依旧，太液芙蓉未央柳。
芙蓉如面柳如眉，对此如何不泪垂。
春风桃李花开夜，秋雨梧桐叶落时。
西宫南苑多秋草，落叶满阶红不扫。
梨园弟子白发新，椒房阿监青娥老。
夕殿萤飞思悄然，孤灯挑尽未成眠。
迟迟钟鼓初长夜，耿耿星河欲曙天。
鸳鸯瓦冷霜华重，翡翠衾寒谁与共。
悠悠生死别经年，魂魄不曾来入梦。
临邛道士鸿都客，能以精诚致魂魄。
为感君王辗转思，遂教方士殷勤觅。
排空驭气奔如电，升天入地求之遍。
上穷碧落下黄泉，两处茫茫皆不见。
忽闻海上有仙山，山在虚无缥缈间。
楼阁玲珑五云起，其中绰约多仙子。
中有一人字太真，雪肤花貌参差是。
金阙西厢叩玉扃，转教小玉报双成。
闻道汉家天子使，九华帐里梦魂惊。
揽衣推枕起徘徊，珠箔银屏迤逦开。
云鬓半偏新睡觉，花冠不整下堂来。
风吹仙袂飘飖举，犹似霓裳羽衣舞。
玉容寂寞泪阑干，梨花一枝春带雨。
含情凝睇谢君王，一别音容两渺茫。
昭阳殿里恩爱绝，蓬莱宫中日月长。
回头下望人寰处，不见长安见尘雾。
惟将旧物表深情，钿合金钗寄将去。
钗留一股合一扇，钗擘黄金合分钿。
但令心似金钿坚，天上人间会相见。
临别殷勤重寄词，词中有誓两心知。
七月七日长生殿，夜半无人私语时。
在天愿作比翼鸟，在地愿为连理枝。
天长地久有时尽，此恨绵绵无绝期。', '《长恨歌》是唐代诗人白居易的一首长篇叙事诗。全诗形象地叙述了唐玄宗与杨贵妃的爱情悲剧。诗人借历史人物和传说，创造了一个回旋宛转的动人故事，并通过塑造的艺术形象，再现了现实生活的真实，感染了千百年来的读者。该诗对后世诸多文学作品产生了深远的影响。', '汉皇：原指汉武帝。此处借指唐玄宗。唐人文学创作常以汉称唐。
重色：爱好女色。
倾国：绝色女子。汉代李延年对汉武帝唱了一首歌：「北方有佳人，绝世而独立。一顾倾人城，再顾倾人国。宁不知倾城与倾国，佳人难再得。」後来，「倾国倾城」就成为美女的代称。
御宇：驾御宇内，即统治天下。汉·贾长沙《过秦论》：「振长策而御宇内」
杨家有女：蜀州司户杨玄琰，有女杨玉环，自幼由叔父杨玄珪抚养，十七岁（开元二十三年）被册封为玄宗之子寿王李瑁之妃。二十七岁被玄宗册封为贵妃。白居易此谓「养在深闺人未识」，是作者有意为帝王避讳的说法。
丽质：美丽的姿质。
六宫粉黛：指宫中所有嫔妃。古代皇帝设六宫，正寝（日常处理政务之地）一，燕寝（休息之地）五，合称六宫。粉黛，粉黛本为女性化妆用品，粉以抹脸，黛以描眉。此代指六宫中的女性。
无颜色：意谓相形之下，都失去了美好的姿容。
华清池：即华清池温泉，在今西安市临潼区南的骊山下。唐贞观十八年建汤泉宫，咸亨二年改名温泉宫，天宝六载扩建后改名华清宫。唐玄宗每年冬、春季都到此居住。
凝脂：形容皮肤白嫩滋润，犹如凝固的脂肪。《诗经·卫风·硕人》语「肤如凝脂」。
侍儿：宫女。
新承恩泽：刚得到皇帝的宠幸。
金步摇：一种金首饰，用金银丝盘成花之形状，上面缀着垂珠之类，插于发鬓，走路时摇曳生姿。
芙蓉帐：绣着莲花的帐子。形容帐之精美。萧纲《戏作谢惠连体十三韵》：珠绳翡翠帷，绮幕芙蓉帐。
春宵：新婚之夜。
佳丽三千：《后汉书·皇后纪》：自武元之后，世增淫费，乃至掖庭三千。言后宫女子之多。据《旧唐书·宦官传》等记载，开元、天宝年间，长安大内、大明、兴庆三宫，皇子十宅院，皇孙百孙院，东都大内、上阳两宫，大率宫女四万人。
金屋：《汉武故事》记载，武帝幼时，他姑妈将他抱在膝上，问他要不要她的女儿阿娇作妻子。他笑着回答说：「若得阿娇，当以金屋藏之。」
列土：分封土地。据《旧唐书·后妃传》等记载，杨贵妃有姊三人，玄宗并封国夫人之号。长日大姨，封韩国夫人。三姨，封虢国夫人。八姨，封秦国夫人。妃父玄琰，累赠太尉、齐国公。母封凉国夫人。叔玄珪，为光禄卿。再从兄铦，为鸿胪卿。锜，为侍御史，尚武惠妃女太华公主。从祖兄国忠，为右丞相。姊妹，姐妹。
可怜：可爱，值得羡慕。
不重生男重生女：陈鸿《长恨歌传》云，当时民谣有「生女勿悲酸，生男勿喜欢」，「男不封侯女作妃，看女却为门上楣」等。
骊宫：骊山华清宫。骊山在今陕西临潼。
凝丝竹：指弦乐器和管乐器伴奏出舒缓的旋律。
渔阳：郡名，辖今北京市平谷县和天津市的蓟县等地，当时属于平卢、范阳、河东三镇节度史安禄山的辖区。天宝十四载冬，安禄山在范阳起兵叛乱。
鼙鼓：古代骑兵用的小鼓，此借指战争。
霓（ní）裳羽衣曲：舞曲名，据说为唐开元年间西凉节度使杨敬述所献，经唐玄宗润色并制作歌词，改用此名。乐曲着意表现虚无缥缈的仙境和仙女形象。
九重城阙：九重门的京城，此指长安。
烟尘生：指发生战事。阙，意为古代宫殿门前两边的楼，泛指宫殿或帝王的住所。《楚辞·九辩》：君之门以九重。
千乘（shèng）万骑西南行：天宝十五载六月，安禄山破潼关，逼近长安。玄宗带领杨贵妃等出延秋门向西南方向逃走。当时随行护卫并不多，「千乘万骑」是夸大之词。乘，四马一车为一乘；骑，一人一马为一骑。
翠华：用翠鸟羽毛装饰的旗帜，皇帝仪仗队用。司马相如《上林赋》：建翠华之旗，树灵鼍之鼓。
百余里：指到了距长安一百多里的马嵬坡。
「翠华摇摇行复止，西出都门百余里。」句：李隆基西奔至距长安百馀里的马嵬驿（今陕西兴平），扈从禁卫军发难，不再前行，请诛杨国忠、杨玉环兄妹以平民怨。玄宗为保自身，只得照办。
六军：指天子军队。《周礼·夏官·司马》：王六军。据新旧《唐书·玄宗纪》、《资治通鉴》等记载：天宝十五载六月，哥舒翰至潼关，为其帐下火拔归仁执之降安禄山，潼关不守，京师大骇。玄宗谋幸蜀，乃下诏亲征，仗下后，士庶恐骇。乙未日凌晨，玄宗自延秋门出逃，扈从唯宰相杨国忠、韦见素，内侍高力士及太子、亲王、妃主，皇孙已下多从之不及。丙辰日，次马嵬驿（在兴平县北，今属陕西），诸军不进。龙武大将军陈玄礼奏：逆胡指阙，以诛国忠为名，然中外群情，不无嫌怨。今国步艰阻，乘舆震荡，陛下宜徇群情，为社稷大计，国忠之徒，可置之于法。会吐蕃使遮国忠告诉于驿门，众呼曰：杨国忠连蕃人谋逆！兵士围驿四合，及诛杨国忠、魏方进一族，兵犹未解。玄宗令高力士诘之，回奏曰：诸将既诛国忠，以贵妃在宫，人情恐惧。玄宗即命力士赐贵妃自尽。
宛转：形容美人临死前哀怨缠绵的样子。蛾眉：古代美女的代称，此指杨贵妃。《诗经·卫风·硕人》：螓首蛾眉。
花钿：用金翠珠宝等制成的花朵形首饰。
委地：丢弃在地上。
翠翘：首饰，形如翡翠鸟尾。
金雀：金雀钗，钗形似凤（古称朱雀）。
玉搔头：玉簪。《西京杂记·卷二》：武帝过李夫人，就取玉簪搔头。自此後宫人搔头皆用玉。
云栈：高入云霄的栈道。
萦纡（yíngyū）：萦回盘绕。
剑阁：又称剑门关，在今四川剑阁县北，是由秦入蜀的要
道。此地群山如剑，峭壁中断处，两山对峙如门。诸葛亮相蜀时，凿石驾凌空栈道以通行。
峨嵋山：在今四川峨眉山市。玄宗奔蜀途中，并未经过峨嵋山，这里泛指蜀中高山。
行宫：皇帝离京出行在外的临时住所。
夜雨闻铃：《明皇杂录·补遗》：「明皇既幸蜀，西南行。初入斜谷，霖雨涉旬，于栈道雨中闻
铃音与山相应。上既悼念贵妃，采其声为《雨霖铃曲》以寄恨焉。」这里暗指此事。后《雨霖铃》成为宋词词牌名。
天旋日转：指时局好转。肃宗至德二年，郭子仪军收复长安。
回龙驭：皇帝的车驾归来。
不见玉颜空死处：据《旧唐书·后妃传》载：玄宗自蜀还，令中使祭奠杨贵妃，密令改葬于他所。初瘗时，以紫褥裹之，肌肤已坏，而香囊仍在，内官以献，上皇视之凄惋，乃令图其形于别殿，朝夕视焉。
信马：意思是无心鞭马，任马前进。
太液：汉宫中有太液池。
未央：汉有未央宫。此皆借指唐长安皇宫。
春风桃李花开夜：一作「春风桃李花开日」。
西宫南苑：一作「西宫南内」，皇宫之内称为大内。西宫即西内太极宫，南内为兴庆宫。玄宗返京后，初居南内。上元元年，权宦李辅国假借肃宗名义，胁迫玄宗迁往西内，并流贬玄宗亲信高力士、陈玄礼等人。
梨园弟子：指玄宗当年训练的乐工舞女。梨园：据《新唐书·礼乐志》：唐玄宗时宫中教习音乐的机构，曾选「坐部伎」三百人教练歌舞，随时应诏表演，号称「皇帝梨园弟子」。
椒房：后妃居住之所，因以花椒和泥抹墙，故称。阿监：宫中的侍从女官。青娥：年轻的宫女。据《新唐书·百官志》，内官宫正有阿监、副监，视七品。
孤灯挑尽：古时用油灯照明，为使灯火明亮，过了一会儿就要把浸在油中的灯草往前挑一点。挑尽，说明夜已深。按，唐时宫延夜间燃烛而不点油灯，此处旨在形容玄宗晚年生活环境的凄苦。
迟迟：迟缓。报更钟鼓声起止原有定时，这里用以形容玄宗长夜难眠时的心情。
耿耿：微明的样子。
欲曙天：长夜将晓之时。
鸳鸯瓦：屋顶上俯仰相对合在一起的瓦。《三国志·魏书·方技传》载：文帝梦殿屋两瓦堕地，化为双鸳鸯。房瓦一俯一仰相合，称阴阳瓦，亦称鸳鸯瓦。
霜华：霜花。
翡翠衾：布面绣有翡翠鸟的被子。《楚辞·招魂》：翡翠珠被，烂齐光些。言其珍贵。
谁与共：与谁共。
临邛道士鸿都客：意谓有个从临邛来长安的道士。临邛，今四川邛崃县；鸿都，指仙府。
致魂魄：招来杨贵妃的亡魂。
方士：有法术的人。这里指道士。
殷勤：尽力。
排空驭气：即腾云驾雾。
穷：穷尽，找遍。
碧落：即天空。
黄泉：指地下。
海上仙山：《史记·封禅书》：自威、宣、燕昭使人人海求蓬莱、方丈、瀛洲，此三神山者，其传在渤海中。
玲珑：华美精巧。
五云：五彩云霞。
绰约：体态轻盈柔美。《庄子·逍遥游》：藐姑射之山，有神人居焉，肌肤若冰雪，绰约如处子。
参差：仿佛，差不多。
金阙：《太平御览》卷六六。引《大洞玉经》：上清宫门中有两阙，左金阙，右玉阙。西厢：《尔雅·释宫》：室有东西厢日庙。西厢在右。
玉扃（jiōng）：玉门。即玉阙之变文。
转教小玉报双成：意谓仙府庭院重重，须经辗转通报。小玉：吴王夫差女。双成：传说中西王母的侍女。这里皆借指杨贵妃在仙山的侍女。
九华帐：绣饰华美的帐子。九华，重重花饰的图案，言帐之精美。《宋书·后妃传》：自汉氏昭阳之轮奂，魏室九华之照耀。
珠箔：珠帘。
银屏：饰银的屏风。
迤逦：接连不断地。
云鬓：一作「云髻」，形容女子鬓发盛美如云。
新睡觉：刚睡醒。觉，醒。
袂（mèi）：衣袖。
飘飖：一作「飘飘」。
玉容寂寞：此指神色黯淡凄楚。
阑干：纵横交错的样子。这里形容泪痕满面。
凝睇（dì）：凝视。
昭阳殿：汉成帝宠妃赵飞燕的寝宫。此借指杨贵妃住过的宫殿。
蓬莱宫：传说中的海上仙山。这里指贵妃在仙山的居所。
人寰（huán）：人间。
旧物：指生前与玄宗定情的信物。
寄将去：托道士带回。
擘：分开。
合分钿：将钿盒上的图案分成两部分。
「钗留一股合一扇，钗擘黄金合分钿。」句：把金钗、钿盒分成两半，自留一半。
但令：一作「但教」。
重寄词：贵妃在告别是重又托他捎话。
两心知：只有玄宗、贵妃二人心里明白。
长生殿：在骊山华清宫内，天宝元年造。按「七月」以下六句为作者虚拟之词。陈寅恪在《元白诗笺证稿·长恨歌》中云：「长生殿七夕私誓之为後来增饰之物语，并非当时真确之事实」。「玄宗临幸温汤必在冬季、春初寒冷之时节。今详检两唐书玄宗记无一次于夏日炎暑时幸骊山。」而所谓长生殿者，亦非华清宫之长生殿，而是长安皇宫寝殿之习称。
比翼鸟：传说中的鸟名，据说只有一目一翼，雌雄并在一起才能飞。
连理枝：两株树木树干相抱。古人常用此二物比喻情侣相爱、永不分离。
恨：遗憾。
绵绵：连绵不断。
无绝期：没有了结的时候。一作“无尽期”。', '唐明皇偏好美色，当上皇帝后多年来一直在寻找美女，却都是一无所获。
杨家有个女儿刚刚长大，十分娇艳，养在深闺中，外人不知她美丽绝伦。
天生丽质、倾国倾城让她很难埋没世间，果然没多久便成为了唐明皇身边的一个妃嫔。
她回眸一笑时，千姿百态、娇媚横生；六宫妃嫔，一个个都黯然失色。
春寒料峭时，皇上赐她到华清池沐浴，温润的泉水洗涤着凝脂一般的肌肤。
侍女搀扶她，如出水芙蓉软弱娉婷，由此开始得到皇帝恩宠。
鬓发如云颜脸似花，头戴着金步摇。温暖的芙蓉帐里，与皇上共度春宵。
情深只恨春宵短，一觉睡到太阳高高升起。君王深恋儿女情温柔乡，从此再也不早朝。
承受君欢侍君饮，忙得没有闲暇。春日陪皇上一起出游，晚上夜夜侍寝。
後宫中妃嫔不下三千人，却只有她独享皇帝的恩宠。
金屋中梳妆打扮，夜夜撒娇不离君王；玉楼上酒酣宴罢，醉意更添几许风韵。
兄弟姐妹都因她列土封侯，杨家门楣光耀令人羡慕。
于是使得天下的父母都改变了心意，变成重女轻男。
骊山上华清宫内玉宇琼楼高耸入云，清风过处仙乐飘向四面八方。
轻歌曼舞多合拍，管弦旋律尽传神，君王终日观看，却百看不厌。
渔阳叛乱的战鼓震耳欲聋，宫中停奏霓裳羽衣曲。
九重宫殿霎时尘土飞扬，君王带着大批臣工美眷向西南逃亡。
车队走走停停，西出长安才百馀里。
六军停滞不前，要求赐死杨玉环。君王无可奈何，只得在马嵬坡下缢杀杨玉环。
贵妃头上的饰品，抛撒满地无人收拾。翠翘金雀玉搔头，珍贵头饰一根根。
君王欲救不能，掩面而泣，回头看贵妃惨死的场景，血泪止不住地流。
秋风萧索扫落叶，黄土尘埃已消遁，回环曲折穿栈道，车队踏上了剑阁古道。
峨眉山下行人稀少，旌旗无色，日月无光。
蜀地山清水秀，引得君王相思情。行宫里望月满目凄然，雨夜听曲声声带悲。
叛乱平息後，君王重返长安，路过马嵬坡，睹物思人，徘徊不前。
萋萋马嵬坡下，荒凉黄冢中，佳人容颜再不见，唯有坟茔躺山间。
君臣相顾，泪湿衣衫，东望京都心伤悲，信马由缰归朝堂。
回来一看，池苑依旧，太液池边芙蓉仍在，未央宫中垂柳未改。
芙蓉开得像玉环的脸，柳叶儿好似她的眉，此情此景如何不心生悲戚？
春风吹开桃李花，物是人非不胜悲；秋雨滴落梧桐叶，场面寂寞更惨凄。
兴庆宫和甘露殿，处处萧条，秋草丛生。宫内落叶满台阶，长久不见有人扫。
戏子头已雪白，宫女红颜尽褪。晚上宫殿中流萤飞舞，孤灯油尽君王仍难以入睡。
细数迟迟钟鼓声，愈数愈觉夜漫长。遥望耿耿星河天，直到东方吐曙光。
鸳鸯瓦上霜花重生，冰冷的翡翠被里谁与君王同眠？
阴阳相隔已一年，为何你从未在我梦里来过？
临邛道士正客居长安，据说他能以法术招来贵妃魂魄。
君王思念贵妃的情意令他感动。他接受皇命，不敢怠慢，殷勤地寻找，八面御风。
驾驭云气入空中，横来直去如闪电，升天入地遍寻天堂地府，都毫无结果。
忽然听说海上有一座被白云围绕的仙山。
玲珑剔透楼台阁，五彩祥云承托起。天仙神女数之不尽，个个风姿绰约。
当中有一人字太真，肌肤如雪貌似花，好像就是君王要找的杨贵妃。
道士来到金阙西边，叩响玉石雕做的院门轻声呼唤，让小玉叫侍女双成去通报。
太真听说君王的使者到了，从帐中惊醒。穿上衣服推开枕头出了睡帐。逐次地打开屏风放下珠帘。
半梳着云鬓刚刚睡醒，来不及梳妆就走下坛来，还歪带着花冠。
轻柔的仙风吹拂着衣袖微微飘动，就像霓裳羽衣的舞姿，袅袅婷婷。寂
寞忧愁颜，面上泪水长流，犹如春天带雨的梨花。
含情凝视天子使，托他深深谢君王。马嵬坡上长别後，音讯颜容两渺茫。
昭阳殿里的姻缘早已隔断，蓬莱宫中的孤寂，时间还很漫长。
回头俯视人间，长安已隐，只剩尘雾。
只有用当年的信物表达我的深情，钿盒金钗你带去给君王做纪念。
金钗留下一股，钿盒留下一半，金钗劈开黄金，钿盒分了宝钿。
但愿我们相爱的心，就像黄金宝钿一样忠贞坚硬，天上人间总有机会再见。
临别殷勤托方士，寄语君王表情思，语中誓言只有君王与我知。
当年七月七日长生殿中，夜半无人，我们共起山盟海誓。
在天愿为比翼双飞鸟，在地愿为并生连理枝。
即使是天长地久，也总会有尽头，但这生死遗恨，却永远没有尽期。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c72e6a6b501f95c35f", "shortContent": "《长恨歌》是白居易诗作中脍炙人口的名篇，作于元和元年（806），当时诗人正在盩厔县（今陕西周至）任县尉。这首诗是他和友人陈鸿、王质夫同游仙游寺，有感于唐玄宗、杨贵妃的故事而创作的。在这首长篇叙事诗里，作者以精练的语言，优美的形象，叙事和抒情结合的手法，叙述了唐玄宗、杨贵妃在安史之乱中的爱情悲剧：他们的爱情被自己酿成的叛乱断送了，正在没完没了地吃着这一精神的苦果。唐玄宗、杨贵妃都是历史上的人物，诗人...", "authors": ["饶芃子"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f4180d635634aee3f7cb1", "shortContent": "南面[1]，山河一统皇唐。层霄雨露回春，深宫草木齐芳。升平早奏，韶华好行乐何妨。愿此生终老温柔，白云不羡仙乡。\n韶华入禁闱，宫树发春晖。天喜时相合，人和事不违。《九歌》扬政要[2]，《六舞》散朝衣[3]。别赏阳台乐，前旬暮雨飞[4]。朕乃大唐天宝皇帝是也。起自潜邸[5]，入缵皇图。任人不二，委姚、宋于朝堂[6]；从谏如流，列张、韩于省闼[7]。且喜塞外风清万里，民间粟贱三钱。真个太平致治，庶几贞观...", "authors": ["唐葆祥"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad4797a92d5e4fd8fe", "shortContent": "《长恨歌》是白居易诗作中脍炙人口的名篇，作于元和元年（806），当时诗人正在盩厔县（今陕西周至）任县尉。这首诗是他和友人陈鸿、王质夫同游仙游寺，有感于唐玄宗、杨贵妃的故事而创作的。在这首长篇叙事诗里，作者以精练的语言，优美的形象，叙事和抒情结合的手法，叙述了唐玄宗、杨贵妃在安史之乱中的爱情悲剧：他们的爱情被自己酿成的叛乱断送了，正在没完没了地吃着这一精神的苦果。唐玄宗、杨贵妃都是历史上的人物，诗人...", "authors": ["饶芃子"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f092ff", "shortContent": "元和元年（806）冬十二月，白居易为盩厔（今陕西周至）尉，此时写《长恨歌传》的陈鸿和琅琊王质夫都家于盩厔，三人相携出游，言及唐明皇与杨贵妃事，均相与感叹。应王质夫的要求，白居易为《长恨歌传》作歌一首，意图“感其事，亦欲惩尤物，窒乱阶，垂于将来也。”果然，此歌一出，立刻传遍天下。但与白居易的意图不同的是，人们从这首诗中看到的是唐明皇与杨玉环之间真挚的爱情，其中的名句如“回眸一笑百媚生，六宫粉黛无颜色...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127074e6f69b71e93f62c1", "shortContent": "元和元年（806）冬十二月，白居易为盩厓（今陕西周至）尉，此时写《长恨歌传》的陈鸿和琅琊王质夫都家于盩厔，三人相携出游，言及唐明皇与杨贵妃事，均相与感叹。应王质夫的要求，白居易为《长恨歌传》作歌一首，意图“感其事，亦欲惩尤物，窒乱阶，垂于将来也”。果然，此歌一出，立刻传遍天下。但与白居易的意图不同的是，人们从这首诗中看到的是唐明皇与杨玉环之间真挚的爱情，其中的名句如“回眸一笑百媚生，六宫粉黛无颜色...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645d09bbec56251f2eeb5b78", "bookTitle": "白居易诗文鉴赏辞典", "articleId": "6462447030675327e17f337c", "shortContent": "《长恨歌》是白居易诗作中脍炙人口的名篇，作于元和元年（806），当时诗人正在盩厔县（今陕西周至）任县尉。这首诗是他和友人陈鸿、王质夫同游仙游寺，有感于唐玄宗、杨贵妃的故事而创作的。在这首长篇叙事诗里，作者以精练的语言，优美的形象，叙事和抒情结合的手法，叙述了唐玄宗、杨贵妃在安史之乱中的爱情悲剧：他们的爱情被自己酿成的叛乱断送了，正在没完没了地吃着这一精神的苦果。唐玄宗、杨贵妃都是历史上的人物，诗人...", "authors": ["饶芃子"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f617145e4710056f1def5", "shortContent": "这首诗与《古诗》中的另一首《驱车上东门》(见后)在感慨生命短促这 一点上有共同性，但艺术构思和形象蕴含却很不相同。《驱车上东门》的 主人公望北邙而生哀，想到的只是死和未死之前的生活享受;这首诗的主 人公游京城而兴叹，想到的不止是死和未死之时的吃好穿好。\n\n开头四句，接连运用有形、有色、有声、有动作的事物作反衬、作比喻， 把生命短促这样一个相当抽象的意思讲得很有实感，很带激情。主人公 独立苍茫，俯仰...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '', 'center', 1413455514, '57b9005cc4c97100558f20a6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10398, '南乡子 · 和杨元素时移守密州', NULL, 293, 3406, 2, 3, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/10771170.htm', '', '东武望余杭，云海天涯两杳茫。何日功成名遂了，还乡，醉笑陪公三万场。
不用诉离觞，痛饮从来别有肠。今夜送归灯火冷，河塘，堕泪羊公却姓杨。', '此词上阕想象两地相望的情景以及功成还乡的愿望，以表达别后思念之情；下阕表示不以世俗的方式来表达离情别绪，并写出了对友人的赞赏之情。', '南乡子：唐教坊曲名，后用作词牌。又名《好离乡》、《蕉叶怨》。《金奁集》入「黄钟宫」。原为单调，有二十七字、二十八字、三十字各体，两平韵，三仄韵，平仄换韵。单调始自后蜀欧阳炯，此词牌即以欧阳炯《南乡子》为正体。冯正中、李德润俱本此添字。双调者始自南唐冯正中词。冯词平韵五十六字，十句，上下阕各四句用韵。另有五十八字体者。其定格为双调五十六字，上下阕各四平韵，一韵到底。此调唱时音节需流丽谐婉，声情掩抑。
「和杨元素，时移守密州」：吴讷钞本、《二妙集》本、毛本作「和杨元素」。
杨元素：杨绘，宋汉州绵竹（今属四川）人，字元素，号无为子。宋仁宗皇祐五年（西元一〇五三年）进士。通判荆南府，迁开封府推官，知眉州，徙兴元府，皆有治声。宋神宗立，召修起居注、知制诰、知谏院。与宰相曾鲁公忤，改兼侍读，元素以「谏官不得其言则去」，不拜。熙宁四年（西元一〇七一年），擢翰林学士、御史中丞《续〈资治通鉴〉长编·卷二百二十》。免役法行，元素陈十害，忤王介甫，罢知亳州。熙宁七年（西元一〇七四年）六月，自应天府（今河南商丘）移知杭州，八月到任。再为翰林学士。贬荆南节度副使，分司南京，改提举太平观，起知兴国军。宋哲宗即位，复天章阁待制，再知杭州。元祐三年（西元一〇八八年）卒于任，年六十二。有《群经索蕴》、《无为编》、《西垣集》等。事见《范太史集·卷三十九·天章阁待制杨公墓志铭》，《宋史·卷三百二十二·杨绘传》。
密州：龙榆生笺引宋·苏颍滨《超然台赋》序：「子瞻既通守馀杭，三年不得代。以辙之在济南也，求为东州守。既得请高密，五月乃有移知密州之命。」又引《钦定大清一统志·卷一百三十四·〈青州府·诸城县〉》：「诸城县，在府东南二百八十里，东西距九十里，南北距一百八十里。……东北至莱州府高密县界五十里，……本春秋时，鲁诸邑及齐琅邪邑地。秦置琅邪郡。汉初置东武县，为郡治并领琅邪诸县，后汉改置琅邪国，于开阳以东武等三县为属。三国魏因之。晋初省琅邪县，以东武诸县属城阳郡，太康十年属东莞郡。宋以东武县分属平昌郡。后魏永安二年，置东武郡兼置胶州。北齐改置高密郡，仍置胶州省诸县入之。隋开皇初，郡废，五年改州曰密州，十八年改东武县曰诸城，大业初州废为高密郡。唐武德五年，复曰密州。天宝元年，复曰高密郡。乾元元年，复曰密州，属河南道。宋曰密州高密郡，开宝五年升安化军节度，属京东东路。」
杳茫：元延祐本作「渺茫」。
功成名遂：傅子立注引《老子·卷上·第九章》：「功成、名遂、身退，天之道。」
三万场：傅子立注引唐·李太白《襄阳歌》：「百年三万六千日，一日须倾三百杯。」
痛饮：傅子立注引：「《世说》：『王孝伯云：「名士不必须奇才，但常得无事，痛饮，读《离骚》，可称名士。」』」刘尚荣按：「事见南朝宋·刘义庆《世说新语·任诞》。原文『但』下有『使』，『饮』下有『酒』，『读』上有『熟』，『可』上有『便』。」
河塘：指沙河塘。傅子立注：「钱塘繁会之地。」刘尚荣按：「《新唐书·卷四十一·〈地理志·江南道·东道采访使〉》：『钱塘县南五里，有沙河塘。』」龙榆生笺：「《东坡诗集》王注：『《新唐书·卷四十一·〈地理志·江南道·东道采访使〉》：「钱塘县南五里，有沙河塘。咸通二年，刺史崔彦曾开。」昔潮水冲击钱塘江岸，至于奔逸入城，势莫能禦，故开沙河以决之。河有三，曰：外沙、中沙、里沙。』」
堕泪：傅子立注：「晋羊祜为荆州都督，卒。襄阳人于岘山建碑立庙，岁时飨祭焉。望其碑者，莫不流涕，杜预因名为『堕泪碑』。」刘尚荣按：「详见《晋书·卷三十四·羊祜（Hù）传》、晋·习彦威《襄阳耆旧记·卷五·牧守》。」龙榆生笺引《晋书·卷三十四·羊祜传》：「羊祜，字叔子，泰山南城人也。帝将有灭吴之志，以祜为都督荆州诸军事、假节，散骑常侍、卫将军如故。……疾渐笃，乃举杜预自代。寻卒，时年五十八。……襄阳百姓于岘山祜平生游憩之所建碑立庙，岁时飨祭焉。望其碑者莫不流涕，杜预因名为『堕泪碑』。」此以羊叔子况杨元素，「羊」、「杨」音近。', '东武和余杭两地相望，但见远隔天涯云海茫茫。不知什么时候才能功成名就，衣锦还乡，到那时我与你同笑长醉三万场。
不用像世俗的样子用酒来诉说离情别绪，痛快的饮宴从来都另有缘由。今夜拿着残灯送你归去，走过河塘，恍惚间见落泪如羊祜的却是你杨元素啊。', '[{"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e79f2af4e09d55b650b", "shortContent": "傅藻《东坡纪年录》：“熙宁七年甲寅（1074），移守密，和元素《南乡子》。”王文诰《苏诗总案》：“甲寅九月，再饯别于湖上作《南乡子》词。”孔《谱》、薛本、邹王本从之。保苅佳昭《苏轼与杨绘有关之词》说这首词表达了苏轼将要离开杭州到密州去的事情和杨绘留在杭州送苏轼的悲哀。从词题“和杨元素，时移守密州”看，苏轼已得知奉调到密州去。词的开头两句设想苏轼到密州以后回头看杭州的情形，结尾三句描写了杨绘送苏轼后...", "authors": [], "pressName": "崇文书局"}]', '', 'indent', 1413470413, '57b8d111165abd0054bef93d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10399, '江城梅花引 · 荆溪阻雪', NULL, 555, 96, 4, 2, '蒋捷', NULL, 10071, '57ac9514c4c9710054655e3c', '宋', 'ci', '词', 'http://baike.baidu.com/view/1010288.htm', '', '白鸥问我泊孤舟，是身留，是心留？心若留时，何事锁眉头？风拍小帘灯晕舞，对闲影，冷清清，忆旧游。
旧游旧游今在否？花外楼，柳下舟。梦也梦也，梦不到，寒水空流。漠漠黄云，湿透木棉裘。都道无人愁似我，今夜雪，有梅花，似我愁。', '词人蒋竹山这首《江城梅花引》，表现了他乘船阻雪于荆溪（在今江苏南部）时的惆怅情怀。词中以悠扬的节奏、活泼的笔调，在冷清的画面上，织进了热烈的回忆和洒脱的情趣；在淡淡的哀愁中，展示了一个清妍潇洒的艺术境界。吟诵起来，给人的感受，如同欣赏一支优美的随想曲，它即兴抒情，旋律自由又富于幻想。', '江城梅花引：词牌名。《中原音韵》注「越调」。《钦定词譜》：「按万俟雅言《梅花引》句读與《江城子》相近，故可合为一調。程正伯词换头句藏短韵者名《摊破江城子》。江皓詞三聲叶者四首，每首有一『笑』字，名《四笑江梅引》。周草窗詞三声叶韵者名《梅花引》，全押平韵者名《明月引》。陈西麓詞名《西湖明月引》。」
白鸥（ōu）：白鹭。
身留：被雪所阻，被迫不能动身而羁留下来。
心留：自己心里情愿留下。
灯晕（yūn）舞：昏暗的灯光摇晃不定。
旧游：指昔日漫遊的伴友与遊时的情景。
漠漠（mò）：密布的样子。
黄云：指昏黄的天色。高達夫曾有诗「千里黄雲白日曛，北风吹雁雪纷纷。」
木棉裘（qiú）：木棉为絮的冬衣。裘，毛皮衣服。', '那自由自在的白鸥问我：“怎么在这儿停舟？是被迫身留？若是愉悦心留，又为何愁云锁眉头？”江风拍打着船窗的小帘，灯影儿摇曳不休。独对孤灯闲影，冷清清、无聊赖，忆念旧时游。
呵！旧游呵，旧游！今日可否仍在心头？只记得花外有楼柳下系舟。梦魂呵，梦魂！梦魂儿飞不到，让寒水空自流。漠漠的黄云，将铁木棉衣湿透。都说没有人似我一般愁，今夜飞雪，有梅花似我一般愁。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e75115e272d4b2253bd09", "shortContent": "荆溪在今江苏宜兴，流入太湖。而蒋捷就是宜兴人，他这次乘舟沿荆溪而行，或者是离家外出，或者是从外地返回家乡，途中为雪所阻，泊舟荒野，空寂无聊，怀旧之情，油然而生，于是写了这首词，描述当时的心境。\n词人设想奇，落笔也奇。开头不写风雪，不写溪流，也不写泊舟的经过，而是创造幻象，以虚写实。“白鸥问我泊孤舟，是身留，是心留？”“心留”指的是乐意羁留，“身留”则是出于被迫，无可奈何！词人途中遇雪，不能继续航行...", "authors": ["朱世英"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec61203048e64fbd9be16", "shortContent": "荆溪在今江苏宜兴，流入太湖。而蒋捷就是宜兴人，他这次乘舟沿荆溪而行，或者是离家外出，或者是从外地返回家乡，途中为雪所阻，泊舟荒野，空寂无聊，怀旧之情，油然而生，于是写了这首词，描述当时的心境。\n词人设想奇，落笔也奇。开头不写风雪，不写溪流，也不写泊舟的经过，而是出示幻象，以虚写实。“白鸥问我泊孤舟，是身留，是心留？”“心留”指的是乐意羁留，“身留”则是出于被迫，无可奈何！词人途中遇雪，不能继续航行...", "authors": ["朱世英"], "pressName": "上海辞书出版社"}]', '清代文学家毛汲古《竹山词跋》：竹山词语语纤巧，字字妍倩。
现代作家木斋《唐宋词评译》：蒋竹山之词，尤以造语奇巧活泼，在宋季词坛上独标一格。此词即以奇巧为胜。上下片问句起兴，上片以白鸥发问，引发「心若留时、何事锁眉头」矛盾心境，并道出「对闲影，冷清清、忆旧游」的景况。上下片之间，以顶针手法承上而下，接以三个「梦」字重复渲染词人的那种江山改颜、时过境迁、恍然如隔世的梦幻感、悲凉感。结以梅花比拟自己，与起首之白鸥呼应，衬托自我高洁之情怀。', 'indent', 1363999590, '57ac9baf165abd0054097f12', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10400, '临江仙 · 夜登小阁，忆洛中旧游', NULL, 365, 662, 4, 4, '陈与义', NULL, 10102, '57baf563165abd0066277faf', '宋', 'ci', '词', 'http://baike.baidu.com/view/2557590.htm', '', '忆昔午桥桥上饮，坐中多是豪英。长沟流月去无声。杏花疏影里，吹笛到天明。
二十余年如一梦，此身虽在堪惊。闲登小阁看新晴。古今多少事，渔唱起三更。', '此词是北宋文人陈去非晚年追忆洛中朋友和旧游而作的。上阕写对已经沦落敌国之手的家乡以及早年自在快乐生活的回顾。下阕宕开笔墨回到现实，概括词人从踏上仕途所经历的颠沛流离和国破家亡的痛苦生活，结句将古今悲慨、国恨家愁，都融入“渔唱”之中，将沉挚的悲感化为旷达的襟怀。', '临江仙：词牌名，又称《鸳鸯梦》、《雁后归》、《庭院深深》。双调，上阕五句，押三平韵，三十字；下阕同，共六十字。
午桥：在洛阳南面。
“忆昔午桥桥上饮，坐中多是豪英。”句：想从前在午桥桥头饮宴，在一起喝酒的都是英雄好汉。
长沟流月：月光随着流水悄悄地消逝。此句即杜甫《旅夜书怀》“月涌大江流”之意，谓时间如流水般逝去。
去无声：表示月亮西沉，夜深了。
“杏花疏影里，吹笛到天明。”句：在杏花稀疏的影子里吹起短笛，一直欢乐到天明。疏影，稀疏的影子。
二十余年：二十多年来的经历（包括北宋亡国的大变乱）。
“二十余年如一梦，此身虽在堪惊。”句：二十多年好像一场春梦，我亲身经历了亡国的变乱，自己虽然还活着，回想起来总是胆战心惊。
渔唱：打鱼人编的歌儿。
三更：古代漏记时，自黄昏至指晓分为五刻，即五更，三更正是午夜。
“闲登小阁看新晴。古今多少事，渔唱起三更。”句：百无聊赖地登上小楼，看看雨后初晴的月夜景色。古往今来多少大事，也不过让打鱼的人编作歌儿在三更半夜里唱唱罢了。', '忆昔日洛阳桥聚会宴饮，到会在坐多是豪杰英雄。月影好像河水静静流去。在杏花稀疏的影子里面，不停吹奏笛子直到天明。二十多年岁月犹如一梦，身躯虽健在但令人心惊。闲登上阁楼看雨后初晴。想那古今多少兴亡事迹，不如听三更犹唱的渔歌。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74d62e6a6b501f95436b", "shortContent": "陈与义（1090—1138）字去非，是北宋末南宋初的著名诗人，也善于填词。他生平致力于诗，所作甚多，约六百余首，而其词作则仅有《无住词》十八首，不及其诗的二十分之一，可见他是以余事填词的。他的《无住词》十八首，其中绝大部分都是在他晚年奉祠退居湖州青墩镇寿圣院僧舍时所作，青墩僧舍有“无住庵”，陈与义曾在这里住过，故遂以“无住”名词。\n这首《临江仙》词大概是在高宗绍兴五年（1135）或六年陈与义退居青...", "authors": ["缪", "钺"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5db5e272d4b2254dff4", "shortContent": "陈与义字去非（1090—1138），是北宋末南宋初的著名诗人，也善于填词。他生平致力于诗，所作甚多，约六百余首，而其词作则仅有《无住词》十八首，不及其诗的二十分之一，可见他是以馀事填词的。他的《无住词》十八首，其中绝大部分都是在他晚年奉祠退居湖州青墩镇寿圣院僧舍时所作，青墩僧舍有“无住庵”，陈与义曾在这里住过，故遂以“无住”名词。\n这首《临江仙》词大概是在高宗绍兴五年（1135）或六年陈与义退居青...", "authors": ["缪", "钺"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255e8f18b220af461ea", "shortContent": "陈与义，字去非（1090—1138），是北宋末南宋初的著名诗人，也善于填词。他生平致力于诗，所作甚多，约六百余首，而其词作则仅有《无住词》十八首，不及其诗的二十分之一，可见他是以余事填词的。他的《无住词》十八首，其中绝大部分都是在他晚年奉祠退居湖州青墩镇寿圣院僧舍时所作，青墩僧舍有“无住庵”，陈与义曾在这里住过，故遂以“无住”名词。\n\n这首《临江仙》词大概是在高宗绍兴五年（1135）或六年陈与义退...", "authors": ["缪　钺"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f4df2af4e09d55b6643", "shortContent": "陈与义的诗流传下来的有600多首，但其词却只存有《无住词》18首，与宋代大多数词家相比，数量相对较少；与大多数南渡文人的词表现波澜壮阔的场景相比，他的词反映的社会现实生活面也比较狭窄。按题材分类的话，忆旧、怀古六首，闲情致逸四首，孤独无奈、有志难伸的四首，此外，还有三首仙词，一首别词。整体上来说，大多局限于自己的小天地里吟咏着自己的哀怜，但却并不妨碍他词艺术上的高超和精美。\n\n虽然建炎四年（113...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312703ee6f69b71e93f6250", "shortContent": "对于南宋人来说，靖康之耻常常萦绕在他们的梦中，搅得他们无法安睡。但也有一些畏缩胆小的人，过着“直把杭州作汴州”的生活，而不再回望黄河冀北。于是，在战与和、攻与守的对垒中，即使有人高唱悲歌，但有时不免黯然落泪。\n\n因宰相王黼获罪而受牵连被贬陈留监酒税的陈与义，第二年又赶上了靖康之难，于是他避难南奔，五年多的时间，流离漂泊于豫、鄂、湘、桂、粤、闽、浙，最后在绍兴元年才到达了会稽。这首《临江仙》按其《年...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312703ee6f69b71e93f6251", "shortContent": "陈与义的诗流传下来的有600多首，但其词却只存有《无住词》18首，与宋代大多数词家相比，数量相对较少；与大多数南渡文人的词表现波澜壮阔的场景相比，他的词反映的社会现实生活面也比较狭窄。按题材分类的话，忆旧、怀古六首，闲情致逸四首，孤独无奈、有志难伸的四首，此外，还有三首仙词，一首别词。整体上来说，大多局限于自己的小天地里吟咏着自己的哀怜，但却并不妨碍他词艺术上的高超和精美。\n\n虽然建炎四年（113...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271f2c26cbf3417f095ca", "shortContent": "陈与义的诗流传下来的有六百多首，但其词却只存有《无住词》18首，与宋代大多数词家相比，数量相对较少；与大多数南渡文人的词表现波澜壮阔的场景相比，他的词反映的社会现实生活面也比较狭窄。按题材分类的话，忆旧、怀古六首，闲情致逸四首，孤独无奈、有志难伸的四首，此外，还有三首仙词，一首别词。整体上来说，大多局限于自己的小天地里吟咏着自己的哀怜，但却并不妨碍他词艺术上的高超和精美。\n虽然建炎四年（1130）...", "authors": ["刘晓亮"], "pressName": "崇文书局"}]', '', 'indent', 1413388258, '57b8c73fdf0eea006333fc9b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10401, '桃花庵歌', NULL, 978, 395, 2, 2, '唐寅', NULL, 10103, '57b8f867c4c97100558ee6b0', '明', 'shi', '诗', 'http://baike.baidu.com/view/109511.htm', '', '桃花坞里桃花庵，桃花庵里桃花仙。
桃花仙人种桃树，又折花枝当酒钱。
酒醒只在花前坐，酒醉还须花下眠。
酒醉酒醒日复日，花前花后年复年。
但愿老死花酒间，不愿鞠躬车马前。
车尘马足贵者趣，酒盏花枝贫者缘。
若将富贵比贫贱，一在平地一在天。
若将贫贱比车马，他得驱驰我得闲。
别人笑我忒风颠，我笑他人看不穿。
不见五陵豪杰墓，无酒无花锄作田。', '《桃花庵歌》为明代著名画家、文学家唐寅（伯虎）的经典诗作，是唐寅诗词中最著名的一首，乃是自况、自谴兼以警世之作。全诗画面艳丽清雅，风格秀逸清俊，音律回风舞雪，意蕴醇厚深远。虽然满眼都是花、桃、酒、醉等香艳字眼，却毫无低俗之气，反而笔力直透纸背，让人猛然一醒。本文内容以苏州唐寅园的碑搨原版为准。', '桃花庵：唐寅在桃花坞建屋，名为桃花庵。拓本诗幅有“弘治乙丑三月”。
桃花坞（wù）：位于苏州金阊门外。北宋时章粢父子在此建成别墅，后渐废为蔬圃。唐寅于此筑室，故名桃花庵。
又摘桃花换酒钱：拓本诗幅作“又折花枝当酒钱”。
车马：此处代指高官权贵。
花酒：《六如居士全集·卷一》作“贫贱”。
五陵：原指汉朝的长陵、安陵、阳陵、茂陵平陵五座皇陵，皇陵周围还环绕着富家豪族和外戚陵墓，后用来指豪门贵族。', '', '[{"bookId": "60d939cea06dc908f045ad24", "bookTitle": "元明清诗鉴赏辞典（新一版）", "articleId": "610e8cd67d0ac11454951dfd", "shortContent": "唐寅在科举失败以后，与家人失和，迁居于桃花坞。他的《姑苏八咏》中《桃花坞》一篇，是这样写的：“花开烂漫满村坞，风烟酷似桃源古；千林映日莺乱啼，万树围春双燕舞……”桃花本自鲜丽，一枝二枝，掩映于山石林莽，已有一种媚趣；千树万树地开作一片，更是灿若云霞，令人如痴如狂，欲歌欲舞了。\n但是，正因为桃花是如此鲜丽娇艳，容易逗引情绪跃动，所以它并不是高人雅士喜欢的花。他们讲究清高素洁，不同凡俗，而桃花却是太热...", "authors": ["骆玉明"], "pressName": "上海辞书出版社"}, {"bookId": "645bb7088258810260d4d543", "bookTitle": "元明清诗三百首鉴赏辞典", "articleId": "645f776f45e4710056ae82da", "shortContent": "唐寅在科举失败以后，与家人失和，迁居于桃花坞。他的《姑苏八咏》中《桃花坞》一篇，是这样写的：“花开烂漫满村坞，风烟酷似桃源古；千林映日莺乱啼，万树围春双燕舞……”桃花本自鲜丽，一枝二枝，掩映于山石林莽，已有一种媚趣；千树万树地开作一片，更是灿若云霞，令人如痴如狂，欲歌欲舞了。\n\n但是，正因为桃花是如此鲜丽娇艳，容易逗引情绪跃动，所以它并不是高人雅士喜欢的花。他们讲究清高素洁，不同凡俗，而桃花却是太...", "authors": ["骆玉明"], "pressName": "上海辞书出版社"}]', '', 'center', 1364000412, '57b8f8685bbb50005b77e9ce', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10402, '湖冻初晴远泛', NULL, 3, 253, 0, 1, '高濂', NULL, 10013, '57ba82a88ac2470063045693', '明', 'wen', '文', '', '', '西湖之水，非严寒不冰，冰亦不坚。冰合初晴，朝阳闪烁，湖面冰澌琼珠，点点浮泛。时操小舟，敲冰浪游，观冰开水路，俨若舟引长蛇，晶莹片片堆叠。家童善击冰丬，举手铿然，声溜百步，恍若星流，或冲激破碎，状飞玉屑，大快寒眼，幽然此兴，恐人所未同。扣舷长歌，把酒豪举，觉我阳春满抱，白雪知音，忘却冰湖雪岸之为寒也。旧闻戒涉春冰，胸中不抱惧心，又何必以涉冰为戒？', '', '', '', NULL, '', 'indent', 1468668974, '57b9d2287db2a20068bf5fc0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10403, '六和塔夜玩风潮', NULL, 2, 253, 0, 1, '高濂', NULL, 10013, '57ba82a88ac2470063045693', '明', 'wen', '文', 'http://baike.baidu.com/subview/25739/16964172.htm', '', '浙江潮汛，人多从八月昼观，鲜有知夜观者，余昔焚修寺中，燃点塔灯，夜午月色横空，江波静寂，悠悠逝水，吞吐蟾光，自是一段奇景。顷焉风色陡寒，海门潮起，月影银涛，光摇喷雪，云移玉岸，浪卷轰雷，白练风扬，奔飞屈折，势若山岳声腾，使人毛骨欲竖。古云：“十万军声半夜潮。”信哉！过眼惊心。因忆当年浪游，身共水天飘泊，随潮逐浪，不知几作泛泛中人。此际沉吟，始觉利名误我不浅。遥见浪中数点浮沤，是皆南北去来舟楫。悲夫二字，搬弄人间，千古曾无英雄打破，尽为名利之梦沉酣，风波自不容人唤醒。', '', '', '', NULL, '', 'indent', 1468668978, '57bec01e8ac24700632520ed', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10407, '苏堤看桃花', NULL, 30, 253, 0, 1, '高濂', NULL, 10013, '57ba82a88ac2470063045693', '明', 'wen', '文', 'http://baike.baidu.com/subview/22278/5082373.htm', '', '六桥桃花，人争艳赏，其幽趣数种，赏或未尽得也。若桃花妙观，其趣有六：其一，在晓烟初破，霞彩影红，微露轻匀，风姿潇洒，若美人初起，娇怯新妆。其二，明月浮花，影笼香雾，色态嫣然，夜容芳润，若美人步月，风致幽闲。其三，夕阳在山，红影花艳，酣春力倦，妩媚不胜，若美人微醉，风度羞涩。其四，细雨湿花，粉容红腻，鲜洁华滋，色更烟润，若美人浴罢，暖艳融酥。其五，高烧庭燎，把酒看花，瓣影红绡，争妍弄色，若美人晚妆，容冶波俏。其六，花事将阑，残红零落，辞条未脱，半落半留。兼之封家姨无情，高下陡作，使万点残红，纷纷飘泊，或扑面撩人，或浮樽沾席，意恍萧骚，若美人病怯，铅华销减。六者惟真赏者得之。又若芳草留春，翠裀堆锦，我当醉眠席地，放歌咏怀，使花片历乱满衣，残香隐隐扑鼻，梦与花神携手巫阳，思逐彩云飞动，幽欢流畅，此乐何极。', '', '六桥：今浙江省杭州西湖外湖宋苏轼所建苏堤上之六桥：映波 、锁澜 、望山 、压堤 、东浦 、跨虹。
芳润：芳香润泽。宋陆游《蝶恋花‧离小益作》词：“雨过园林，花气浮芳润。” 
幽闲：柔顺闲静。多用以形容女子。《诗‧周南‧关雎》“窈窕淑女” 毛传：“窈窕，幽闲也。” 
鲜洁：洁净无瑕疵。 
庭燎：古代庭中照明的火炬。
弄色：显现美色。
容冶：指对面容的修饰。
波俏：俊俏，漂亮。
花事：关于花的事情。春季百花盛开，故多指游春看花等事。
辞条：离开树枝。
封家姨：犹封姨。亦作“封夷”、“十八姨”、“封十八姨”。古时神话传说中的风神。 与负责初春催开花朵的“飞廉”相对，负责春后将花瓣卷落。
真赏者：真能赏识的人。
花片历乱：飘落的花瓣纷乱。
花神：掌管花的神。《云笈七籤》卷一一三： “窥见女子红裳艷丽，游于树下。有辄採花折枝者，必为所祟，俗传女子花神也。”
巫阳：即巫山。 
', '', NULL, '', 'indent', 1468668992, '57b9d22b0a2b58006cb1208a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10409, '鹧鸪天·半死桐', NULL, 154, 877, 5, 1, '贺铸', NULL, 10098, '57b9bbb28ac2470063feff0a', '宋', 'ci', '词', 'http://baike.baidu.com/view/660118.htm', '', '重过阊门万事非，同来何事不同归？梧桐半死清霜后，头白鸳鸯失伴飞。
原上草，露初晞，旧栖新垅两依依。空床卧听南窗雨，谁复挑灯夜补衣！', '此词是北宋词人贺铸为亡妻作的一首悼亡词。词中通过旧地重游抒发感情，追念了作者与亡妻在长期同甘共苦的生活中，培育出来的深厚爱情。全词触景生情，出语沉痛，情真意切，哀怨凄婉，动人肺腑。', '阊（chāng）门：本为苏州西门，这里代指苏州。
梧桐半死：比喻丧偶。
原上草，露初晞：比喻死亡。晞：干掉。
旧栖：旧居。
新垅：新坟。', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74bf911759740c9aa374", "shortContent": "有宋一代，诗坛是个“被爱情遗忘的角落”，爱情的花朵，几乎都开放在词的园林里。而宋词中所吟咏的爱情，又几乎是清一色的婚外之恋———文士和妓女们的卿卿我我，言及夫妻伉俪之情的作品微乎其微。究其原因，殆为封建社会讲究门当户对，并不以两性爱情为婚姻的第一要义之故。但是，先结婚后谈恋爱，在长期同甘共苦的生活中培养出浓郁情感的例子总还是有的。谓予不信，请看贺铸为其妻赵氏夫人所作的这首悼亡词。\n词人一生屈居下僚...", "authors": ["钟振振"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5c5d635634aee3e9aa2", "shortContent": "有宋一代，诗坛是个“被爱情遗忘的角落”，爱情的花朵，几乎都开放在词的园林里。而宋词中所吟咏的爱情，又几乎是清一色的婚外之恋———文士和妓女们的卿卿我我，言及夫妻伉俪之情的作品微乎其微。究其原因，殆为封建社会讲究门当户对，并不以性爱为婚姻的第一要义之故。但是，先结婚后谈恋爱，在长期同甘共苦的生活中培养出浓郁情感的例子总还是有的。谓予不信，请看贺铸为其妻赵氏夫人所作的这首悼亡词。\n词人一生屈居下僚，经...", "authors": ["钟振振"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059254f534825dee9fd6f2", "shortContent": "有宋一代，诗坛是个“被爱情遗忘的角落”，爱情的花朵，几乎都开放在词的园林里。而宋词中所吟咏的爱情，又几乎是清一色的婚外之恋——文士和妓女们的卿卿我我，言及夫妻伉俪之情的作品微乎其微。究其原因，殆为封建社会讲究门当户对，并不以性爱为婚姻的第一要义之故。但是，先结婚后谈恋爱，在长期同甘共苦的生活中培养出浓郁情感的例子总还是有的。谓予不信，请看贺铸为其妻赵氏夫人所作的这首悼亡词。\n\n词人一生屈居下僚，经...", "authors": ["钟振振"], "pressName": "上海辞书出版社"}]', '', 'indent', 1364204503, '57b8fb845bbb50005b77fd9c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10411, '凉州词二首 · 其一', NULL, 2126, 17, 2, 15, '王翰（子羽）', NULL, 10104, '57ba236d79bc4400639ec7d4', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/155229/8984685.htm', '', '葡萄美酒夜光杯，欲饮琵琶马上催。
醉卧沙场君莫笑，古来征战几人回？', '《凉州词》创作于开元年间，是描绘边塞生活的名曲之一，诗人性情的豪爽在其中表现得淋漓尽致。全诗写出了广袤边塞来之不易的一次盛宴，勾画出了戍边将士尽情畅饮、欢快愉悦的场面，抒发的是反战的哀怨，所揭露的是自有战争以来生还者极少的悲惨事实，却出以豪迈旷达之笔，表现了一种视死如归的悲壮情绪。使人透过这种貌似豪放旷达的胸怀，更加看清了军人们心灵深处的忧伤与幻灭。', '凉州词：唐乐府名，属《近代曲辞》，是《凉州曲》的唱词，盛唐时流行的一种曲调名。凉州词：王翰写有《凉州词》两首，慷慨悲壮，广为流传。而这首《凉州词》被明代王世贞推为唐代七绝的压卷之作。
夜光杯：用白玉制成的酒杯，光可照明，这里指华贵而精美的酒杯。据《海内十洲记》所载，为周穆王时西胡所献之宝。
琵琶：这里指作战时用来发出号角的声音时用的。
催：催人出征；也有人解作鸣奏助兴。
沙场：平坦空旷的沙地，古时多指战场。', '酒筵上甘醇的葡萄美酒盛满在精美的夜光杯之中，歌伎们弹奏起急促欢快的琵琶声助兴催饮，想到即将跨马奔赴沙场杀敌报国，战士们个个豪情满怀。今日一定要一醉方休，即使醉倒在战场上又何妨？此次出征为国效力，本来就打算马革裹尸，没有准备活着回来。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a30f8fda556505541b", "shortContent": "边地荒寒艰苦的环境，紧张动荡的征戍生活，使得边塞将士很难得到一次欢聚的酒宴。有幸遇到那么一次，那激昂兴奋的情绪，那开怀痛饮、一醉方休的场面，是不难想象的。这首诗正是这种生活和感情的写照。诗中的酒，是西域盛产的葡萄美酒；杯，相传是周穆王时代，西胡以白玉精制成的酒杯，有如“光明夜照”，故称“夜光杯”；乐器则是胡人用的琵琶；还有“沙场”、“征战”等等词语。这一切都表现出一种浓郁的边地色彩和军营生活的风味...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d111", "shortContent": "边地荒寒艰苦的环境，紧张动荡的征戍生活，使得边塞将士很难得到一次欢聚的酒宴。有幸遇到那么一次，那激昂兴奋的情绪，那开怀痛饮、一醉方休的场面，是不难想象的。这首诗正是这种生活和感情的写照。诗中的酒，是西域盛产的葡萄美酒；杯，相传是周穆王时代，西胡以白玉精制成的酒杯，有如“光明夜照”，故称“夜光杯”；乐器则是胡人用的琵琶；还有“沙场”“征战”等等词语。这一切都表现出一种浓郁的边地色彩和军营生活的风味。...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f459761253910e903b3", "shortContent": "唐人七绝多是乐府歌词，《凉州词》是其中之一。它是根据凉州地方乐调歌唱的。《新唐书•乐志》说：“天宝间乐调，皆以边地为名，若凉州、伊州、甘州之类。”这首诗地方色彩极浓。从标题看，凉州属西北边地。从内容看，葡萄酒是当时西域特产；夜光杯是西域所进，相传是周穆王时代，西胡以白玉精制成的酒杯，有如“光明夜照”，故称“夜光杯”；琵琶更是经西域传入大唐而风行天下。这些无一不与西北边塞风情相关。\n首句用语绚丽优美...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127053e6f69b71e93f6283", "shortContent": "唐人七绝多是乐府歌词，凉州词是其中之一。它是根据凉州（今甘肃省河西、陇右一带）地方乐调歌唱的。《新唐书·乐志》说：“天宝间乐调，皆以边地为名，若凉州、伊州、甘州之类。”这首诗地方色彩极浓。从标题看，凉州属西北边地；从内容看，葡萄酒是当时西域特产；夜光杯是西域所进，相传是周穆王时代，西胡以白玉精制成的酒杯，有如“光明夜照”，故称“夜光杯”；琵琶更是西域所产。这些无一不与西北边塞风情相关。王翰的这首七...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270a6e6f69b71e93f6339", "shortContent": "唐人七绝多是乐府歌词，《凉州词》是其中之一。它是根据凉州地方乐调歌唱的。《新唐书·乐志》说：“天宝间乐调，皆以边地为名，若凉州、伊州、甘州之类。”这首诗地方色彩极浓。从标题看，凉州属西北边地；从内容看，葡萄酒是当时西域特产。夜光杯是西域所进，相传是周穆王时代，西胡以白玉精制成的酒杯，有如“光明夜照”，故称“夜光杯”；琵琶更是西域所产——这些无一不与西北边塞风情相关。王翰的这首七绝正是一首优美的边塞...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f0a91e49f46528ad169b0", "shortContent": "边地荒寒艰苦的环境，紧张动荡的征戍生活，使得边塞将士很难得到一次欢聚的酒宴。有幸遇到那么一次，那激昂兴奋的情绪，那开怀痛饮、一醉方休的场面，是不难想象的。这首诗正是这种生活和感情的写照。诗中的酒，是西域盛产的葡萄美酒；杯，相传是周穆王时代，西胡以白玉精制成的酒杯，有如“光明夜照”，故称“夜光杯”；乐器则是胡人用的琵琶；还有“沙场”“征战”等等词语。这一切都表现出一种浓郁的边地色彩和军营生活的风味。...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}]', '《唐诗绝句类选》：语意远，乃得隽永。
《唐诗直解》：悲慨在“醉卧”二字。
《艺苑卮言》：“可怜无定河边骨，犹是深闺梦里人”，用意工妙至此，可谓绝唱矣。惜为前二句所累，筋骨毕露，令人厌憎。“葡萄美酒”一绝，便是无瑕之璧。盛唐地位不凡乃尔。
《增订唐诗摘钞》：诗意在末句，而以饮酒引之，沉痛语也。若以豪饮解之，则人人所知，非古人之意。
《而庵说唐诗》：此诗妙绝，无人不知，若非细细寻其金针，其妙亦不可得而见。……若论顿挫，“葡萄美酒”一顿，“夜光杯”一顿，“欲饮”一顿，“琵琶马上催”一顿，“醉卧沙场”一顿，“君莫笑”一顿，凡六顿，“古来征战几人回”则方挫去。夫顿处皆截，挫处皆连，顿多挫少，唐人得意乃在此。
《唐诗别裁》：故作豪饮旷达之词，而悲感已极。杨仲弘论绝句，以第三句为主，而第四句发之，盛唐多与此合。
《诗法易简录》：“君莫笑”三字喝末句有力。
《唐人万首绝句选评》：气格俱胜，盛唐绝作。', 'center', 1364210775, '57b910e7d342d3005ac7ab2a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10412, '祭妹文', NULL, 44, 173, 1, 1, '袁枚', NULL, 10099, '57b921bed342d3005ac840e9', '清', 'wen', '文', 'http://baike.baidu.com/view/881529.htm', '', '呜呼！汝生于浙，而葬于斯，离吾乡七百里矣；当时虽觭梦幻想，宁知此为归骨所耶？
汝以一念之贞，遇人仳离，致孤危托落，虽命之所存，天实为之；然而累汝至此者，未尝非予之过也。予幼从先生授经，汝差肩而坐，爱听古人节义事；一旦长成，遽躬蹈之。呜呼！使汝不识《诗》、《书》，或未必艰贞若是。
予捉蟋蟀，汝奋臂出其间；岁寒虫僵，同临其穴。今予殓汝葬汝，而当日之情形，憬然赴目。予九岁，憩书斋，汝梳双髻，披单缣来，温《缁衣》一章；适先生奓户入，闻两童子音琅琅然，不觉莞尔，连呼「则则」，此七月望日事也。汝在九原，当分明记之。予弱冠粤行，汝掎裳悲恸。逾三年，予披宫锦还家，汝从东厢扶案出，一家瞠视而笑，不记语从何起，大概说长安登科、函使报信迟早云尔。凡此琐琐，虽为陈迹，然我一日未死，则一日不能忘。旧事填膺，思之凄梗，如影历历，逼取便逝。悔当时不将嫛婗情状，罗缕记存；然而汝已不在人间，则虽年光倒流，儿时可再，而亦无与为证印者矣。
汝之义绝高氏而归也，堂上阿奶，仗汝扶持；家中文墨，䀢汝办治。尝谓女流中最少明经义、谙雅故者。汝嫂非不婉嫕，而于此微缺然。故自汝归后，虽为汝悲，实为予喜。予又长汝四岁，或人间长者先亡，可将身后托汝；而不谓汝之先予以去也。前年予病，汝终宵刺探，减一分则喜，增一分则忧。后虽小差，犹尚殗殜，无所娱遣；汝来床前，为说稗官野史可喜可愕之事，聊资一欢。呜呼！今而后，吾将再病，教从何处呼汝耶？
汝之疾也，予信医言无害，远吊扬州；汝又虑戚吾心，阻人走报；及至绵惙已极，阿奶问：「望兄归否？」强应曰：「诺。」已予先一日梦汝来诀，心知不祥，飞舟渡江，果予以未时还家，而汝以辰时气绝；四支犹温，一目未瞑，盖犹忍死待予也。呜呼痛哉！早知诀汝，则予岂肯远游？即游，亦尚有几许心中言要汝知闻、共汝筹画也。而今已矣！除吾死外，当无见期。吾又不知何日死，可以见汝；而死后之有知无知，与得见不得见，又卒难明也。然则抱此无涯之憾，天乎人乎！而竟已乎！
汝之诗，吾已付梓；汝之女，吾已代嫁；汝之生平，吾已作传；惟汝之窀穸，尚未谋耳。先茔在杭，江广河深，势难归葬，故请母命而宁汝于斯，便祭扫也。其傍，葬汝女阿印；其下两冢：一为阿爷侍者朱氏，一为阿兄侍者陶氏。羊山旷渺，南望原隰，西望栖霞，风雨晨昏，羁魂有伴，当不孤寂。所怜者，吾自戊寅年读汝哭侄诗后，至今无男；两女牙牙，生汝死后，才周睟耳。予虽亲在未敢言老，而齿危发秃，暗里自知；知在人间，尚复几日？阿品远官河南，亦无子女，九族无可继者。汝死我葬，我死谁埋？汝倘有灵，可能告我？
呜呼！生前既不可想，身后又不可知；哭汝既不闻汝言，奠汝又不见汝食。纸灰飞扬，朔风野大，阿兄归矣，犹屡屡回头望汝也。呜呼哀哉！呜呼哀哉！', '《祭妹文》是清代文学家袁枚的一篇散文，是中国古代文学史上哀祭散文的珍品。这篇祭文从兄妹之间的亲密关系着眼，选取自己所见、所闻、所梦之事，对妹妹袁机的一生做了绘声绘色的描述，渗透着浓厚的哀悼、思念以及悔恨的真挚情感。文章记述袁机在家庭生活中扶持奶奶，办治文墨，写她明经义，谙雅故，表现出妹妹的德能与才华。写的虽然都是家庭琐事，却描述得「如影历历」，真切可信。
', '乾隆丁亥：卽公元1767年。丁亥，纪年干支；
素文：名机，字素文，别号青琳居士。康熙五十八年（公元1719年）生，乾隆二十四年（公元1759年）卒，得四十岁。
上元：旧县名。唐肃宗李亨上元二年（公元761年）置。在今南京市。羊山：在南京市东。
奠：祭献。
汝（rǔ）：你。
浙：浙江省。
斯：此，这里。指羊山。
吾乡：袁枚的枚乡，在浙江钱塘（今杭州市）。
觭（jī）梦：这里是做梦的意思。觭，得。语出《周礼·春官太卜》：「太卜滨三梦之法，二曰觭梦。」
宁知：怎么知道。归骨所：指葬地。
耶（yē）：语气词，表疑问。
以：因为。
一念之贞：一时信念中的贞节观。贞，封建礼教对女子的一种要求。忠诚地附属于丈夫（包括仅在名义上确定关系而实际上未结婚的丈夫），不管其情况如何，都要从一而终，这种信念和行为称之为「贞」。
遇人仳（pǐ）离：《诗经·王风·中谷有蓷》：「有女仳离，条其歗矣；条其歗矣。遇人之不淑矣。」这里化用其语，意指遇到了不好的男人而终被离弃。遇人，是「遇人不淑」的略文。淑，善。仳离，分离。特指妇女被丈夫遗弃。
孤危：孤单困苦。
托落：即落拓（tuò），失意无聊。
存：注定。
累：连累；使之受罪。
未尝：义同「未始」，这里不作「未曾」解。过：过失。
授经：这里同「受经」，指读儒家的「四书五经」。封建社会里，儿童时就开始受这种教育。授，古亦同「受」。韩愈《师说》：「师者，所以传道受（授）业解惑也。」
差（cī）肩而坐：谓兄妹并肩坐在一起。二人年龄有大小，所以肩膀高低不一。语出《管子·轻重甲》：「管子差肩而问。」
节义事：指封建社会里妇女单方面、无条件地忠于丈夫的事例。
遽（jù）：骤然，立即。
躬（gōng）：身体。引早为「亲自」。
蹈（dǎo）：踏，踩。「实行」。
使：如果。《诗》、《书》：《诗经》、《尚书》。指前文中先生所授的「经」。
艰贞：困苦而又坚决。若是：如此。
出其间：出现在捉蟋蟀的地方。
虫：指前文中的蟋蟀。
僵：指死亡。
同临其穴（xué）：一同来到掩埋死蟋蟀的土坑边。
殓（liàn）：收殓。葬前给尸体穿衣、下棺。
憬然赴目：清醒地来到眼前。憬然，醒悟的样子。
憩（qì）：休息。
书斋：书房。
双髻（jì）挽束在头顶上的两个辫丫。古代女孩子的发式。
单缣（jiān）：这里指用缣制成的单层衣衫。缣，双丝织成的细绢。
温：温习。《缁衣》：《诗经·郑风》篇名。缁，黑色。一章：《诗经》中诗凡一段称之为一章。
适：刚好。
奓（zhà）户：开门。
琅（láng）琅然：清脆流畅的样子。形容读书声。
莞（wǎn）尔：微笑貌。语出《论语·阳货》：「夫子莞尔而笑。」
则则：犹「啧啧」，赞叹声。
望日：阴历每月十五，日月相对，月亮圆满，所以称为「望日」。
九原：春秋时晋国卿大夫的墓地。语出《礼记·檀弓下》：「赵文子与叔誉观乎九原。」后泛指墓地。
弱冠（guàn）：出《礼记·曲礼上》：「二十曰弱，冠。」意思是男子到了他举行冠礼（正式承认他是个成年人）。弱，名词。冠，动词。后因以「弱冠」表示男子进入成年期的年龄。
粤（月yuè）行：到广东去。粤，广东省的简称。袁枚二十一岁时经广东到了广西他叔父袁鸿（字健槃）那里。袁鸿是文档巡抚金鉷（红hóng）的幕客。金鉷器重袁枚的才华，举荐他到北京考博学鸿词科。
掎（jǐ）：拉住。恸：痛哭。
逾：越，经过。
披宫锦：指袁枚于乾隆三年（公元1738年）考中进士，选授翰林院庶吉士，请假南归省亲的事。宫锦，宫廷作坊特制的丝织品。这里指用这种锦制成的宫袍。因唐代李白曾待诏翰林，着宫锦袍，后世遂用以称翰林的朝服。
厢：边屋。案：狭长的桌子。
瞠（chēng）视而笑：瞪眼看着笑，形容惊喜激动的情状。
长安：汉、唐旧都，即今西安市。
函使：递送信件的人。唐时新进士及第，以泥金书帖，报登科之喜。此指传报录取消息的人，俗称「报子」。
云尔：如此如此罢了。
凡此琐琐：所有这些细小琐碎的事。袁枚有诗：「远望蓬门树彩竿，举家相见问平安。同欣阆苑荣归早，尚说长安得信难。壁上泥金经雨淡，窗前梅柳带春寒。娇痴小妹怜兄贵，教把宫袍著与看。」（见《小仓山房诗集》卷二）可与「凡此琐琐」去者相印证。
填膺（yīng）：充满胸怀。
凄梗：悲伤凄切，心头像堵塞了一样。
历历：清晰得一一可数的样子。
逼取便逝：真要接近它|把握它，它就消失了。
嫛婗（yī ní）：婴儿。这里引申为儿时。
罗缕（lǚ）纪存：排成一条一条，记录下来保存着。罗缕，也作「（尔见）褛」。
可再：可以再有第二次。
印证：指袁枚的母亲章氏。
义绝：断绝情宜。这里指离婚。
阿奶：指袁枚的母亲章氏。
文墨：有关文字方面的事务。
眣（shùn）：卽用眼色示意。这里作「期望」解。
尝：曾经。
明经义：明白儒家经典的含义。
谙（ān）雅故：了解古书古事，知道前言往行的意思。语出《汉书·叙传》：「函雅故，通古今。」谙，熟闻熟知。
这句意思说：你嫂嫂（指袁枚的妻子王氏）不是不好，但是在这方面稍有欠缺。
婉嫕（yì）：温柔和顺。出《晋书·武悼杨皇后传》：「婉嫕有妇德。」
长（zhǎng）：年纪大。
身后：死后的一应事务。
先予以去：比我先离开人世。
绞宵：整夜。
剌探：打听、探望。
小差：病情稍有好转。
差（chài），同「瘥」。
殗殜（yè dié）病得不太厉害，但还没有痊愈。
娱遣：消遣。
稗（bài）官野史：指私人编定的笔记、小说之类的历史记载，与官方编号的「正史」相对而言。《汉书·艺文志》：「小说家者流，盖出于稗官。」据说，西周高有掌管收录街谈巷议的官职，称为稗官，稗是碎米。稗官，取琐碎之义，即小官。
愕（è）：惊骇。
聊资：绝代：姑且作为一时的快乐。
吊：凭吊，游览。
虑戚吾心：顾虑着怕我心里难过。戚，忧愁。
阴人走报：阻止别人报急讯。走，跑。
绵惙（chuò）：病势危险。
强（qiǎng）：勉强。
诺（nuò）：表示同意的答语，犹言「好」。
诀：诀别。袁枚有哭妹诗：「魂孤通梦速，江阔送终迟。」自注：「得信前一夕，梦与妹如平生欢。」
果：果真。未时：相当下午一至三时。
辰时：相当于上午七时至九时。
支：同「肢」。
一目示瞑（míng）：一只眼睛没有闭紧。
几许：多少。
知闻：听取，知道。
共汝筹画：和你一起商量，安排。
已矣：完了。
又卒难明：最终又难以明白。卒，终于。
天乎人乎：有史以来强烈时的呼唤，表示极端悲痛。这句说：然而就这样带着无穷的憾恨而终于完了啊！
付梓（zǐ）付印。梓，树名。这里指印刷书籍用的雕板。素文的遗稿，附印在袁枚的《小仓山房全集》中，题为《素文女子遗稿》。袁枚为了它写了跋文。
代嫁：指代妹妹作主把外甥女嫁出去。
传（zhuàn）：即《女弟素文传》。
窀穸（zhūn xī）：墓穴。
先茔（yíng）：祖先的墓地。
江广河深：言地理阻隔，交通不便。
阿印：《女弟素文传》载：「女阿印，病瘖，一切人事器物不能音，而能书。」其哭妹诗说：「有女空生口，无言但点颐。「
冢（zhǒng）：坟墓。
阿爷：袁枚的父亲袁滨，曾在各地为幕僚，于袁枚三十三岁时去世。侍者：这里指妾。
阿兄：袁枚自称。
陶氏：作者的妾。亳州人，工棋善绣。
旷渺（miǎo）：空旷辽阔。
望：对着。
原隰（xí）：平广的代地。高而平的地叫原，低下而潮湿的地为隰。
栖霞：山名。一名摄山。在南京市东。
风雨：泛指各种气候。晨昏：指一天到晚。
羁（jī）魂：飘荡在他乡的魂魄。
男：儿子。袁枚于乾隆二十三年（公元1758年）丧子。他的兄弟曾为此写过两首五言律诗，题为《民兄得了不举》。这就是文所说的「哭侄诗」。袁枚写这篇祭文的时候还没有儿子。再后两年，至六十三岁，其妾锺氏才生了一个儿子，名阿迟。
两女：袁枚的双生女儿。也是钟氏所生。
牙牙：小孩学话的声音。这里说两个女儿还很幼小。
周晬（zuì）：周岁。
亲在未敢言老：封建孝道规定，凡父母长辈在世，子女即使老了也不得说老。否则既不尊敬，又容易使年迈的长辈惊怵于已近死亡。出《礼记·坊记》：「父母在，不称老。」袁枚这句话，是婉转地表示自己已经老了。按，袁枚这时六十一岁，母亲还健在。
齿危：牙齿摇摇欲坠。
阿品远官河南，亦无子女：袁枚的堂弟袁树，字东芗，号芗亭，小名阿品，由进士任河南正阳县县令。当时也没有子女。据袁枚《先妣行状》所说，阿品有个儿子叫阿通；但那是袁枚写这篇《祭妹文》以后的事。
九族：指高祖、曾祖、祖父、父亲、本身、儿子、孙子、曾孙和玄孙。这里指血缘关系较近的许多宗属。
无可继者：没有可以传宗接代的人。按，专指男性。
可能：犹言「能否」。
纸灰：锡箔、纸钱等焚烧后的灰烬。
朔风野大：旷野上，北风显得更大。《诗经·郑风》中的名篇。', '乾隆三十二年冬，葬三妹素文在上元的羊山上，并作这篇文章来致祭：
唉！你生在浙江，却葬在此地，远离我们的故乡七百里了；当时你即使做梦、幻想，也怎会知道这里竟是你的埋骨所在呢？
你因为坚守从一而终的贞节观念，嫁了一个品德败坏的丈夫而被遗弃，以致陷在孤苦落拓的境地，虽然这是命中注定，是上天的安排，然而连累你到这种地步，也未尝不是我的过错。我幼年时跟从老师诵读四书五经，你同我并肩坐在一起，爱听那些古人的节义故事；一旦长大成人，你立即亲身来实践。唉！要是你不懂得经书，也许未必会像这样苦守贞节。
我捉蟋蟀，你紧跟我捋袖伸臂，抢着捕捉；寒冬蟋蟀死了，你又同我一起挖穴埋葬它们。今天我收殓你的尸体，给你安葬，而当年的种种情景，却一一清晰地呈现在眼前。我九岁时，在书房里休息，你梳着两个发髻，披了一件细绢单衣进来，共同温习《诗经》中的《缁衣》一章；刚好老师开门进来，听到两个孩子琅琅的读书声，不禁微笑起来，连声「啧啧」称赞。这是七月十五日的事情。你在九泉之下，一定还清楚地记得。我二十岁去广西，你牵住我的衣裳，悲伤痛哭。过了三年，我考中进士，衣锦还乡，你从东厢房扶着长桌出来，一家人瞪着眼相视而笑，记不得当时话是从哪里说起，大概是说了些在京城考进士的经过情况以及报信人来得早、晚等等吧。所有这些琐碎的事情，虽然已经成为过去，但只要我一天不死，就一天也不能忘却。往事堆积在我的胸中，想起来，心头悲切得像被堵塞似的。它们像影子一样似乎非常清晰，但真要靠近它抓住它，却又不见了。我后悔当时没有把这些儿时的情状，一条一条详细地记录下来；然而你已不在人间了，那么即使年光可以倒流回去，儿童时代可以重新来过，也没有人来为它们对照证实的了。
你与高家断绝关系后回到娘家，堂上老母，依仗你照料扶持；家中的文书事务，期待你去办理。我曾经以为妇女中很少明白经书的意义、熟识古代文物典故的人。你嫂嫂并非不够温柔和顺，但在这方面稍有不足。所以自从你回家后，虽然我为你而悲伤，对我自己来说却很高兴。我又比你年长四岁，或许像世间通常那样年长的先死，那就可以将身后之事托付给你；却没有想到你比我先离开人世！
前些年我生了病，你整夜都在打听、探望病情，减轻一分就高兴，加重一分就担忧。后来虽然我的病情稍有好转，但仍半卧半起，感到没有什么好取乐消遣；你来到我的床前，讲一些稗官野史中使人好笑和使人惊奇的故事，给我带来一些欢乐。唉！自今以后，我如果再有病痛，教我从哪里去呼唤你呢？
你的病，我相信医师的话以为不要紧，所以才远游去扬州。你又怕我心中忧虑，不让别人来给我报信。直到病已垂危时，母亲问你：「盼望哥哥回来吗？」，你才勉强答应说：「好。」就在你死前一日，我已梦见你来诀别，心知这是不吉祥的，急忙飞舟渡江赶回家。果然，我于未时到家，而你已在辰时停止了呼吸，四肢尚有馀温，一只眼睛还未闭紧，大概你还在忍受着临死的痛苦等待我回来吧。唉！痛心啊！早知要和你诀别，那我怎么肯离家远游呢？即使出外，也还有多少心里话要让你知道、同你一起商量安排啊！如今完了，除非我死，否则就没有相见的日期。可我又不知道哪一天死，才可以见到你；而死后究竟有知觉还是没有知觉，以及能相见还是不能相见，终究是难以明白的啊！如果如此，那么我将终身抱着这无穷的遗恨，天啊！人啊！竟然这样完了吗！
你的诗，我已经付印了；你的女儿，我已替你嫁了出去；你的生平，我已写了传记；只有你的墓穴，还没有安排好。我家祖先的坟墓在杭州，但是江广河深，势难将你归葬到祖坟，所以请示母亲的意见而把你安葬在这里，以便于祭奠扫墓。在你的墓傍，葬着你的女儿阿印，在下面还有两个坟墓，一个是父亲的侍妾朱氏，一个是我的侍妾陶氏。羊山空旷辽阔，朝南是一片宽广的平地，西望面向着栖霞山；风风雨雨，清晨黄昏，你这个羁留在异乡的精魂有了伴侣，当不致于感到孤独寂寞。可怜的是，我自从戊寅年读了你写的哭侄诗后，至今没有儿子；两个牙牙学语的女儿，在你死后出生，才只有一周岁。我虽因母亲健全而不敢说自己老，但齿牙摇动，头发已秃，自己心里知道，在这人世间尚能活几天？阿品弟远在河南为官，也没有子女，我家九族之内没有可以传宗接代的人。你死有我安葬，我死后由谁来埋葬呢？你如果死后有灵的话，能不能告诉我？
唉！生前的事既不堪想，死后的事又不可知；哭你既听不到你回话，祭你又看不到你来享食。纸钱的灰烬飞扬着，北风在旷野里显得更猛，我回去了，但又连连回过头来看你。唉，真悲痛啊！唉，真悲痛啊！', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed20e5e272d4b2254f0e0", "shortContent": "〔注〕①乾隆丁亥：清高宗乾隆三十二年（1767）。②素文：名机，字素文，别号青琳居士。据袁枚《女弟素文传》，袁机于“乾隆二十四年（1759）十一月死，年四十”。③上元：县名，在今南京市。羊山：在今南京市东。④觭（犼ī基）梦：做梦，得梦。《周礼·春官·大卜》：“二曰觭梦”。郑玄注：“言梦之所得。”⑤一念之贞：据《女弟素文传》：袁机不满周岁即许给如皋高氏子。十余年后高氏因其子不肖，曾提出解除婚约，但袁...", "authors": ["王英志"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413450202, '57b8fdf1d342d3005ac71585', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10413, '陇西行四首（其二）', NULL, 290, 147, 1, 5, '陈陶', NULL, 10105, '57bb1449128fe1005f90affb', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/229776/5109335.htm', '', '誓扫匈奴不顾身，五千貂锦丧胡尘。
可怜无定河边骨，犹是春闺梦里人。', '此为《陇西行》组诗中的第二首。首二句写将士忠勇，丧亡甚众；末二句写牺牲者是春闺少妇日夜盼望归来团聚的情人。全诗反映了唐代长期征战带给人民的痛苦和灾难，表达了非战情绪。三、四两句，以“无定河边骨”与“春闺梦里人”比照，虚实相对，宛若电影中的蒙太奇，用意工妙。诗情凄楚，吟来潸然泪下。', '匈奴：指西北边境部族。
貂锦：这里指战士，指装备精良的精锐之师。
无定河：在陕西北部。
春闺：这里指战死者的妻子。', '唐军将士誓死横扫匈奴奋不顾身，
五千身穿锦袍的精兵战死在胡尘。
真可怜啊那无定河边成堆的白骨，
还是少妇们梦中相依相伴的丈夫。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92db2e6a6b501f95c501", "shortContent": "《陇西行》是乐府《相和歌·瑟调曲》旧题，内容写边塞战争。陇西，即今甘肃宁夏陇山以西的地方。陈陶的《陇西行》共四首，此其二。诗反映了唐代长期的边塞战争给人民带来的痛苦和灾难。\n首二句以精练概括的语言，叙述了一个慷慨悲壮的激战场面。唐军誓死杀敌，奋不顾身，但结果五千将士全部丧身“胡尘”。“誓扫”、“不顾”，表现了唐军将士忠勇敢战的气概和献身精神。汉代羽林军穿“貂锦”（锦衣貂裘），这里借“貂锦”指精锐部...", "authors": ["阎昭典"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9820695e6503fff0", "shortContent": "《陇西行》是乐府《相和歌·瑟调曲》旧题，内容写边塞战争。陇西，即今甘肃宁夏陇山以西的地方。陈陶的《陇西行》共四首，此其二。诗反映了唐代长期的边塞战争给人民带来的痛苦和灾难。\n\n首二句以精练概括的语言，叙述了一个慷慨悲壮的激战场面。唐军誓死杀敌，奋不顾身，但结果五千将士全部丧身“胡尘”。“誓扫”“不顾”，表现了唐军将士忠勇敢战的气概和献身精神。汉代羽林军穿“貂锦”（锦衣貂裘），这里借“貂锦”指精锐部...", "authors": ["阎昭典"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4ec26cbf3417f0939e", "shortContent": "《陇西行》本乐府《相和歌辞•瑟调曲》旧题，内容多写边塞战争。陈陶有《陇西行》四首，此为其二。\n\n诗歌并不正面描写战斗场面，首句借士兵态度暗示战事之激烈：“誓扫匈奴”表现士兵们态度坚决、胆气豪壮，“不顾身”凸显其作战的英勇顽强。\n\n第二句笔锋跳转，描述将士阵亡场面。汉代曾设羽林军，他们身穿锦衣貂裘，以作战英勇、顽强著称，这里的“貂锦”即借代唐军精锐部队。五千之众的精锐士兵牺牲，也可想见之前经历了一场...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270799761253910e90565", "shortContent": "《陇西行》本乐府《相和歌辞·瑟调曲》旧题，内容多写边塞战争。陈陶有《陇西行》四首，此为其二。\n\n诗歌并不正面描写战斗场面，首句借士兵态度暗示战事之激烈：“誓扫匈奴”表现士兵们态度坚决、胆气豪壮，“不顾身”凸显其作战的英勇顽强。\n\n第二句笔锋跳转，描述将士阵亡场面。汉代曾设羽林军，他们身穿锦衣貂裘，以作战英勇、顽强著称，这里的“貂锦”即借代唐军精锐部队。五千之众的精锐士兵牺牲，也可想见之前经历了一场...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312714977683d1933015468", "shortContent": "《陇西行》本乐府乐府《相和歌辞·瑟调曲》旧题，内容多写边塞战争。陈陶有《陇西行》四首，此为其二。\n诗歌并不正面描写战斗场面，首句借士兵态度暗示战事之激烈：“誓扫匈奴”表现士兵们态度坚决、胆气豪壮，“不顾身”凸显其作战的英勇顽强。\n第二句笔锋跳转，描述将士阵亡场面。汉代曾设羽林军，他们身穿锦衣貂裘，以作战英勇、顽强著称，这里的“貂锦”即借代唐军精锐部队。五千之众的精锐士兵牺牲，也可想见之前经历了一场...", "authors": ["冯丽霞"], "pressName": "崇文书局"}]', '', 'center', 1415636800, '57b91121c4c97100558faccf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (68029, '题秋茄图', NULL, 0, 40, 0, 3, '钱选', NULL, 11595, '5858e69c61ff4b0063d6f8ce', '元', 'shi', '诗', NULL, NULL, '忆昔毗山爱写生，瓜茄任我笔纵横。
自怜老去翻成拙，学圃今犹学不成。', NULL, NULL, NULL, NULL, NULL, 'center', 1525432517, '585cff2c1b69e600560f5198', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10417, '诉衷情令', NULL, 508, 9405, 3, 7, '陆游', NULL, 10019, '57b904a9d342d3005ac748fb', '宋', 'ci', '词', 'http://baike.baidu.com/view/398955.htm', '', '当年万里觅封侯，匹马戍梁州。关河梦断何处，尘暗旧貂裘。
胡未灭，鬓先秋，泪空流。此生谁料，心在天山，身老沧洲。', '此词描写了作者一生中最值得怀念的一段岁月，通过今昔对比，反映了一位爱国志士的坎坷经历和不幸遭遇，表达了作者壮志未酬、报国无门的悲愤不平之情。上片开头追忆作者昔日戎马疆场的意气风发，接写当年宏愿只能在梦中实现的失望；下片抒写敌人尚未消灭而英雄却已迟暮的感叹。全词格调苍凉悲壮，语言明白晓畅，用典自然，不着痕迹，不加雕饰，如叹如诉，有较强的艺术感染力。', '诉衷情令：词牌名。
万里觅封侯：奔赴万里外的疆场，寻找建功立业的机会。《后汉书·班超传》载：班超少有大志，尝曰，大丈夫应当“立功异域，以取封侯，安能久事笔砚间乎？”
戍（shù）：守边。梁州：《宋史·地理志》：“兴元府，梁州汉中郡，山南西道节度。”治所在南郑。陆游著作中，称其参加四川宣抚使幕府所在地，常杂用以上地名。
关河：关塞、河流。一说指潼关黄河之所在。此处泛指汉中前线险要的地方。梦断：梦醒。
尘暗旧貂裘：貂皮裘上落满灰尘，颜色为之暗淡。这里借用苏秦典故，说自己不受重用，未能施展抱负。据《战国策·秦策》载，苏秦游说秦王“书十上而不行，黑貂之裘敝，黄金百斤尽，资用乏绝，去秦而归”。
胡：古泛称西北各族为胡，亦指来自彼方之物。南宋词中多指金人。此处指金入侵者。
鬓：鬓发。秋：秋霜，比喻年老鬓白。
天山：在中国西北部，是汉唐时的边疆。这里代指南宋与金国相持的西北前线。
沧洲：靠近水的地方，古时常用来泛指隐士居住之地。谢朓《之宣城郡出新林浦向板桥》诗有“既欢怀禄情，复协沧州趣”句。这里是指作者位于镜湖之滨的家乡。', '回忆当年鹏程万里为了寻找建功立业的机会，单枪匹马奔赴边境保卫梁州。如今防守边疆要塞的从军生活只能在梦中出现，梦一醒不知身在何处？灰尘已经盖满了旧时出征的貂裘。
胡人还未消灭，鬓边已呈秋霜，感伤的眼泪白白地淌流。这一生谁能预料，原想一心一意抗敌在天山，如今却一辈子老死于沧洲！', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74de911759740c9aa413", "shortContent": "积贫积弱、日见窘迫的南宋是一个需要英雄的时代，但这又是一个英雄“过剩”的时代。陆游的一生以抗金复国为己任，但请缨无路，屡遭贬黜，晚年退居山阴，有志难申。“壮士凄凉闲处老，名花零落雨中看。”历史的秋意，时代的风雨，英雄的本色，艰难的现实，共同酿成了这一首悲壮、沉郁的《诉衷情》。作这首词时，词人已年近七十，身处江湖，未忘国忧，烈士暮年，雄心不已。这种高亢的政治热情，永不衰竭的爱国精神形成了词作风骨凛然...", "authors": ["史双元"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5e32cee9a0c24ed9ed5", "shortContent": "积贫积弱、日见窘迫的南宋是一个需要英雄的时代，但这又是一个英雄“过剩”的时代。陆游的一生以抗金复国为己任，但请缨无路，屡遭贬黜，晚年退居山阴，有志难申。“壮士凄凉闲处老，名花零落雨中看。”历史的秋意，时代的风雨，英雄的本色，艰难的现实，共同酿成了这一首悲壮沉郁的《诉衷情》。作这首词时，词人已年近七十，身处江湖，未忘国忧，烈士暮年，雄心不已，这种高亢的政治热情，永不衰竭的爱国精神形成了词作风骨凛然的...", "authors": ["史双元"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059255e8f18b220af461fd", "shortContent": "积贫积弱、日见窘迫的南宋是一个需要英雄的时代，但这又是一个英雄“过剩”的时代。陆游的一生以抗金复国为己任，但请缨无路，屡遭贬黜，晚年退居山阴，有志难申。“壮士凄凉闲处老，名花零落雨中看。”历史的秋意、时代的风雨、英雄的本色、艰难的现实，共同酿成了这一首悲壮沉郁的《诉衷情》。作这首词时，词人已年近七十，身处江湖，未忘国忧，烈士暮年，雄心不已，这种高亢的政治热情，永不衰竭的爱国精神形成了词作风骨凛然的...", "authors": ["史双元"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472c63b30675327e1c365f8", "shortContent": "积贫积弱、日见窘迫的南宋是一个需要英雄的时代，但这又是一个英雄“过剩”的时代。陆游的一生以抗金复国为己任，但请缨无路，屡遭贬黜，晚年退居山阴，有志难申。“壮士凄凉闲处老，名花零落雨中看”，历史的秋意，时代的风雨，英雄的本色，艰难的现实，共同酿成了这一首悲壮沉郁的《诉衷情》。作这首词时，词人已年近七十，身处江湖，未忘国忧，烈士暮年，雄心不已，这种高亢的政治热情，永不衰竭的爱国精神形成了词作风骨凛然的...", "authors": ["史双元"], "pressName": "上海辞书出版社"}]', '陆永品：陆游于六十五岁被罢官，以后曾担任过闲官，绝大部分时间都是闲居在家乡山阴的镜湖边。对于陆游这样以身许国、胸怀壮志的人，这种生活使他难以忍受。他不能理解，也万没有想到，为什么国难当头，他竟然报国无门，而落得心系前线、闲老家乡的境地。因此，在词的结尾，他以天山代指南宋抗金的西北前线，以沧洲代指自己闲居的湖边，痛苦地发出了“此生谁料，心在天山，身老沧洲”的呼喊。这是爱国诗人内心矛盾的自白，也抒写了他对南宋统治集团的强烈不满。
王方俊、张曾峒：情感真挚，丝毫不见半点虚假造作；语言通俗，明白如话；悲壮处见沉郁，愤懑却不消沉。所有这些，使陆游这首词感人至深，独具风格。', 'indent', 1413469954, '57b928a87db2a2005427f1cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10419, '雁门太守行', NULL, 538, 247, 4, 15, '李贺', NULL, 10108, '57b927a2128fe10054cad4c3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/159579.htm', '', '黑云压城城欲摧，甲光向日金鳞开。
角声满天秋色里，塞上燕脂凝夜紫。
半卷红旗临易水，霜重鼓寒声不起。
报君黄金台上意，提携玉龙为君死。', '此诗是唐代诗人李贺运用乐府古题创作的一首描写战争场面的诗歌。用浓艳斑驳的色彩描绘悲壮惨烈的战斗场面，奇异的画面准确地表现了特定时间、特定地点的边塞风光和瞬息万变的战争风云。首联写景又写事，渲染兵临城下的紧张气氛和危急形势，并借日光显示守军威武雄壮；颔联从听觉和视觉两方面渲染战场的悲壮气氛和战斗的残酷；颈联写部队夜袭和浴血奋战的场面；尾联引用典故写出将士誓死报效国家的决心。全诗意境苍凉，格调悲壮，具有强烈的震撼力和艺术魅力。', '雁门太守行：古乐府曲调名。
雁门，郡名。古雁门郡大约在今山西省西北部，是唐王朝与北方突厥部族的边境地带。
黑云：此形容战争烟尘铺天盖地，弥漫在边城附近，气氛十分紧张。
摧：毁。
甲光：指铠甲迎着太阳发出的闪光。。甲，指铠甲，战衣。
向日：迎着太阳。亦有版本写作「向月」。向，向着，对着。
金鳞开：（铠甲）像金色的鱼鳞一样闪闪发光。
「甲光向日金鳞开」句：形容敌军兵临城下的紧张气氛和危急形势。
角：古代军中一种吹奏乐器，多用兽角制成，亦古代军中的号角。
燕脂：即胭脂，这里指暮色中塞上泥土有如胭脂凝成。
凝夜紫：在暮色中呈现出暗紫色。凝，凝聚。「燕脂」、「夜紫」暗指战场血迹。
易水：河名，大清河上源支流，源出今河北省易县，向东南流入大清河。易水距塞上尚远，此借荆轲故事以言悲壮之意。战国时荆轲前往刺秦王，燕太子丹及众人送至易水边，荆轲慷慨而歌：「风萧萧兮易水寒，壮士一去兮不复还！」不起：是说鼓声低沉不扬。
霜重鼓寒：天寒霜降，战鼓声沉闷而不响亮。
声不起：形容鼓声低沉；不响亮。
「霜重鼓寒声不起」句：一作「霜重鼓声寒不起」。
黄金台：故址在今河北省易县东南，相传战国燕昭王所筑。《战国策·燕策》载燕昭王求士，筑高台，置黄金于其上，广招天下人才。
意：信任，重用。
玉龙：宝剑的代称。
君：君王。', '敌兵滚滚而来，犹如黑云翻卷，想要摧倒城墙；我军严待以来，阳光照耀铠甲，一片金光闪烁。
秋色里，响亮军号震天动地；黑夜间战士鲜血凝成暗紫。
红旗半卷，援军赶赴易水；夜寒霜重，鼓声郁闷低沉。
只为报答君王恩遇，手携宝剑，视死如归。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d1dbb8b379ee095cfb", "shortContent": "“雁门太守行”系乐府旧题。李贺生活的时代藩镇叛乱此伏彼起，发生过重大的战争。如史载，元和四年（809），王承宗的叛军攻打易州和定州，爱国将领李光颜曾率兵驰救。元和九年，他身先士卒，突出、冲击吴元济叛军的包围，杀得敌人人仰马翻，狼狈逃窜。\n从有关《雁门太守行》这首诗的一些传说和材料记载推测，可能是写平定藩镇叛乱的战争。\n诗共八句，前四句写日落前的情景。首句既是写景，也是写事，成功地渲染了敌军兵临城下...", "authors": ["朱世英"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389aecdc25963feee1aa5", "shortContent": "“雁门太守行”系乐府旧题。李贺生活的时代藩镇叛乱此伏彼起，发生过重大的战争。如史载，元和四年（809），王承宗的叛军攻打易州和定州，爱国将领李光颜曾率兵驰救。元和九年，他身先士卒，突出、冲击吴元济叛军的包围，杀得敌人人仰马翻，狼狈逃窜。\n\n从有关《雁门太守行》这首诗的一些传说和材料记载推测，可能是写平定藩镇叛乱的战争。\n\n诗共八句，前四句写日落前的情景。首句既是写景，也是写事，成功地渲染了敌军兵临...", "authors": ["朱世英"], "pressName": "上海辞书出版社"}, {"bookId": "6277f9fed4cef5295f72c610", "bookTitle": "李贺全集", "articleId": "63126dc077683d193301504a", "shortContent": "《雁门太守行》系乐府旧题，六朝以来多歌咏边塞战争。长吉拟作，也是一幅震撼人心的战争画卷。首两句写战争乍起，敌军兵临城下，来势汹汹，战士披坚执锐，严阵以待；三、四句写鏖战场面，萧瑟的秋风中，惨烈的战争从白天持续到夜晚，鲜血把塞土都染成了紫色。五、六句写冒寒挺进，夜袭敌营，将生死置之度外。最后两句为誓死之词，表达报国之志。唐人张固《幽闲鼓吹》云：“李贺以歌诗谒韩吏部，吏部时为国子博士分司，送客归，极困...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707677683d19330153d3", "shortContent": "“雁门太守行”系乐府旧题。中唐时期，藩镇飞扬跋扈，叛变无常，河北地区战事频繁，国家的统一遭到严重威胁。作者热情歌颂那些浴血奋战、慷慨赴难的将士，表现了他对当时叛乱不安、国无宁日的社会现实的不满。\n\n开头两句写激战前的敌我形势。敌人像黑云一样压过来，说明当时敌人之多，而且来势汹汹得想把城池给摧毁了，这更是让人措手不及。但是，夕阳下将士的铠甲闪着金光，他们正披坚执锐，严阵以待。这里借日光来显示守军的阵...", "authors": ["宋丹萍"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271327ccdb86c49f292fd", "shortContent": "“雁门太守行”系乐府旧题。中唐时期，藩镇飞扬跋扈，叛变无常，河北地区战事频繁，国家的统一遭到严重威胁。作者热情歌颂那些浴血奋战、慷慨赴难的将士，表现了他对当时叛乱不安、国无宁日的社会现实的不满。\n开头两句写激战前的敌我形势。敌人像黑云一样压过来，说明当时敌人之多，而且来势汹汹地想把城池给摧毁了，这更是让人措手不及。但是，夕阳下将士的铠甲闪着粼光，他们正披坚执锐，严阵以待。这里借日光来显示守军的阵营...", "authors": ["宋丹萍"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f901b5420e27678f83cd", "shortContent": "雁门太守行”系乐府旧题。李贺生活的时代藩镇叛乱此伏彼起，发生过重大的战争。如史载，元和四年(809)，王承宗的叛军攻打易州和定州，爱国将领李光颜曾率兵驰救。元和九年，他身先士卒，突出、冲击吴元济叛军的包围，杀得敌人人仰马翻，狼狈逃窜。\n从有关《雁门太守行》这首诗的一些传说和材料记载推测，可能是写平定藩镇叛乱的战争。\n一般说来，写悲壮惨烈的战斗场面不宜使用表现秾艳色彩的词语，而李贺这首诗几乎句句都有...", "authors": ["朱世英"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472a62245e4710056fde29d", "shortContent": "“雁门太守行”系乐府旧题。李贺生活的时代藩镇叛乱此伏彼起，发生过重大的战争。如史载，元和四年（809），王承宗的叛军攻打易州和定州，爱国将领李光颜曾率兵驰救。元和九年，他身先士卒，突出、冲击吴元济叛军的包围，杀得敌人人仰马翻，狼狈逃窜。\n\n从有关《雁门太守行》这首诗的一些传说和材料记载推测，可能是写平定藩镇叛乱的战争。\n\n诗共八句，前四句写日落前的情景。首句既是写景，也是写事，成功地渲染了敌军兵临...", "authors": ["朱世英"], "pressName": "上海辞书出版社"}]', '王谠《唐语林》：李贺以歌诗谒韩愈，愈时为国子博士分司，送客归，极困。门人呈卷，解带旋读之，有篇《雁门太守》云：「黑云压城城欲摧，甲光向日金鳞开。」却缓带，命迎之。
王得臣《麈史》：长吉才力奔放，不惊众绝俗不下笔，有《雁门太守》诗曰：「黑云压城城欲摧，甲光射日金鳞开。」王安石曰：「是儿言不相副也。方黑云如此，安待向日之甲光乎？」
曾季狸《艇斋诗话》：李贺《雁门太守行》语奇。
高棅《唐诗品汇》：刘云：有此一语方畅（「角声满天」句下）。此等景不可无（「塞上燕脂」二句下）。起语起。赋雁门著紫土本嫩。后三语无甚生气，设为死敌之意偏欲如此，颇似败后之作。
杨慎《升庵诗话》：或问：「此诗韩、王二公去取不同，谁为是？」予曰：「宋老头巾不知诗，凡兵围城，必有怪云变气，昔人赋鸿门有‘东龙白日西龙雨’之句，解此意矣。予在滇，值安凤之变，居围城中，见日晕两重，黑云如蚊在其侧，始信贺之诗善状物也。」
周珽《唐诗选脉会通评林》：刘辰翁曰：语少而劲，转出死敌意，愤咽。范梈曰：作诗要有惊人句。语险，诗便惊人。如李贺「黑云压城城欲摧，甲光照日金鳞开」，此等语，任是人道不出。周敬曰：萃精求异，刻画点缀，真好气骨，好才思。顾璘曰：词奇而俊，前辈所称。陆时雍曰：「塞上燕脂凝夜紫」，「燕脂」二字难下；「霜重鼓寒声不起」，语甚有色。周珽曰：今观其全首，似为中唐另树旗鼓者。至末二句，雄浑尤不减初、盛风格。……长吉诗大抵创意奥而生想深，萃精求异，有不自知为古古怪怪者。他如《剑子》、《铜仙》等歌什，辄多呕心语，宜为昌黎公所知重也。
黄淳耀、黎简《李长吉集》：黎简：「声满天地」似昌黎「天狗堕地」之作篇中活句，贺其不愧作者。「霜重」句即李陵「兵气不扬」意。写败军如见（「半卷红旗」二句下）。以死作结势，结得决绝险劲（末二句下）。
杜诏、杜庭珠《中晚唐诗叩弹集》：杜诏：此诗言城危势亟，擐甲不休，至于哀角横秋，夕阳塞紫，满目悲凉，犹卷旆前征，有进无退。虽士气已竭，鼓声不扬，而一剑尚存，死不负国。皆极写忠诚慷慨。
薛雪《一瓢诗话》：李奉礼「黑云压城城欲摧，甲光向日金鳞开」，是阵前实事，千古妙语。王荆公訾之，岂疑其黑云、甲光不相属耶？儒者不知兵，乃一大患。
沈德潜《唐诗别裁》：阴云蔽天，忽露赤日，实有此景（「黑云压城」二句下）。字字锤炼而成，昌谷集中定推老成之作。
宋宗元《网师园唐诗笺》：沉雄乃尔（「黑云压城」二句下）。警绝（「霜重鼓寒」三句下）。
史承豫《唐贤小三昧集》：闪烁纸上（「黑云压城」句下）。结更陡健。
王闿运《王闿运手批唐诗选》：长吉诗皆仅成章（「半卷红旗」二句下）。
王琦《李长吉歌诗汇解》：此篇盖咏中夜出兵，乘间捣敌之事。「黑云压城城欲摧」，甚言寒云浓密，至云开处逗露月光与甲光相射，有似金鳞。此言初出兵时，语气甚雄壮。「角声满天」，写军中之所闻；「塞上胭脂」，写军中之所见。「半卷红旗」，见轻兵夜进之捷；「霜重鼓咽」，冒寒将战之景。末复设为誓死之词，以答君上恩礼之隆，所以明封疆臣子之志也。」', 'center', 1423215263, '57b8f0ad1532bc005b9aa494', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10420, '南园十三首（其五）', NULL, 435, 247, 2, 3, '李贺', NULL, 10108, '57b927a2128fe10054cad4c3', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/565691/14258631.htm', '', '男儿何不带吴钩，收取关山五十州？
请君暂上凌烟阁，若个书生万户侯？', '此诗是唐代诗人李贺的组诗作品《南园十三首》的第五首。这首诗由两个设问句组成，顿挫激越，而又直抒胸臆，把家国之痛和身世之悲都淋漓酣畅地表达出来了。', '吴钩：吴地出产的弯形的刀，此处指宝刀。一作“横刀”。
凌烟阁：唐太宗为表彰功臣而建的殿阁，上有秦琼等二十四人的像。', '男子汉大丈夫为什么不带上锋利的吴钩，去收复那黄河南北割据的关山五十州？请你且登上那画有开国功臣的凌烟阁去看，又有哪一个书生能被册封为食邑万户的列侯？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d22e6a6b501f95c3f6", "shortContent": "这首诗由两个设问句组成，顿挫激越，而又直抒胸臆，把家国之痛和身世之悲都淋漓酣畅地表达出来了。\n第一个设问是泛问，也是自问，含有“国家兴亡，匹夫有责”的豪情。“男儿何不带吴钩”，起句峻急，紧连次句“收取关山五十州”，犹如悬流飞瀑，从高处跌落而下，显得气势磅礴。“带吴钩”指从军的行动，身佩军刀，奔赴疆场，那气概多么豪迈！“收复关山”是从军的目的，山河破碎，民不聊生，诗人怎甘蛰居乡间，无所作为呢？因而他...", "authors": ["朱世英"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472b63182772d45942a09e7", "shortContent": "这首诗由两个设问句组成，顿挫激越，而又直抒胸臆，把家国之痛和身世之悲都淋漓酣畅地表达出来了。\n\n第一个设问是泛问，也是自问，含有“国家兴亡，匹夫有责”的豪情。“男儿何不带吴钩”，起句峻急，紧连次句“收取关山五十州”，犹如悬流飞瀑，从高处跌落而下，显得气势磅礴。“带吴钩”指从军的行动，身佩军刀，奔赴疆场，那气概多么豪迈！“收复关山”是从军的目的，山河破碎，民不聊生，诗人怎甘蛰居乡间，无所作为呢？因而...", "authors": ["朱世英"], "pressName": "上海辞书出版社"}]', '《李长吉集》：黎简：欲弃毛锥，亦自愤也。
《昌谷集注》：裴度伐吴元济，蔡、郓、淮西数十州至是尽归朝廷。贺盖美诸将之功，而复羡其荣宠，故不觉壮志勃生。
《李长吉歌诗汇解》：观凌烟阁上之像，未有以书生而封侯者，不得不弃笔墨而带吴钩矣。', 'center', 1364814648, '57b8b7f35bbb50005b772434', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10421, '李凭箜篌引', NULL, 300, 247, 4, 4, '李贺', NULL, 10108, '57b927a2128fe10054cad4c3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/159547.htm', '', '吴丝蜀桐张高秋，空山凝云颓不流。
江娥啼竹素女愁，李凭中国弹箜篌。
昆山玉碎凤凰叫，芙蓉泣露香兰笑。
十二门前融冷光，二十三丝动紫皇。
女娲炼石补天处，石破天惊逗秋雨。
梦入神山教神妪，老鱼跳波瘦蛟舞。
吴质不眠倚桂树，露脚斜飞湿寒兔。', '此诗载于《全唐诗·卷三百九十》。全诗语言峭丽，构思新奇，独辟蹊径，对乐曲本身，仅用两句略加描摹，而将大量笔墨用来渲染乐曲惊天地、泣鬼神的动人效果，大量的联想、想象和神话传说，使作品充满浪漫主义气息。', '李凭：当时的梨园艺人，善弹奏箜篌。唐·杨景山《听李凭弹箜篌》诗曰：「听奏繁弦玉殿清，风传曲度禁林明。君王听乐梨园暖，翻到《云门》第几声？」「花咽娇莺玉嗽泉，名髙半在玉筵前。汉王欲助人间乐，从遣新声坠九天。」
箜篌引：乐府旧题，属《相和歌·瑟调曲》。
箜篌：古代弦乐器。又名空侯、坎侯。形状有多种。据诗中「二十三丝」，可知李凭弹的是竖箜篌。一作“二十三弦”。
引：一种古代诗歌体裁，篇幅较长，音节、格律一般比较自由，形式有五言、七言、杂言。
吴丝蜀桐：吴地之丝，蜀地之桐。此指制作箜篌的材料。张：调好弦，准备调奏。
高秋：指弹奏时间。
「吴丝蜀桐张高秋」句：在深秋天气弹奏起箜篌。
空白：一作「空山」。《列子·汤问》：「秦青抚节悲歌，响遏行云」。
「空山凝云颓不流」句：言山中的行云因听到李凭弹奏的箜篌声而凝定不动了。
江娥：一作「湘娥」。元·李息斋《竹谱详录·巻六》：「泪竹生全湘九疑山中……《述异记》云：『舜南巡，葬于苍梧，尧二女娥皇、女英泪下沾竹，文悉为之斑。』一名湘妃竹。」
素女：传说中的神女。《汉书·郊祀志上》：「秦帝使素女鼓五十弦瑟，帝禁不止，故破其瑟为二十五弦。」这句说乐声使江娥、素女都感动了。
中国：即国之中央，意谓在京城。
昆山玉碎凤凰叫：昆仑玉碎，形容乐音清脆。昆山，即昆仑山。凤凰叫，形容乐音和缓。
芙蓉泣露、香兰笑：形容乐声时而低回，时而轻快。
十二门：长安城东西南北每一面各三门，共十二门，故言。「十二门前融冷光」句：清冷的乐声使人觉得长安城沉浸在寒光之中。
二十三丝：《通典·卷一百四十四》：「竖箜篌，胡乐也，汉灵帝好之，体曲而长，二十三弦。竖抱于怀中，用两手齐奏，俗谓之擘箜篌。」
紫皇：道教称天上最尊的神为「紫皇」。这里用来指皇帝。
女娲：中华上古之神，人首蛇身，为伏羲之妹，风姓。《淮南子·览冥训》和《列子·汤问》载有女娲炼五色石补天故事。
石破天惊逗秋雨：补天的五色石（被乐音）震破，引来了一场秋雨。逗，引。
坤山：一作「神山」。
神妪（yù）：《搜神记·巻四》：「永嘉中，有神现兖州，自称樊道基。有妪号成夫人。夫人好音乐，能弹箜篌，闻人弦歌，辄便起舞。」所谓「神妪」，疑用此典。从这句以下写李凭在梦中将他的绝艺教给神仙，惊动了仙界。
老鱼跳波：鱼随着乐声跳跃。源自《列子·汤问》：「瓠巴鼓琴而鸟舞鱼跃。」
吴质：卽吴刚。《酉阳杂俎·巻一》：「旧言月中有桂，有蟾蜍。故异书言月桂髙五百丈，下有一人常斫之，树创随合。人姓吴名刚，西河人，学仙有过，谪令伐树。」
露脚：露珠下滴的形象说法。
寒兔：传说月中有玉兔，故称。', '在深秋的夜晚，弹奏起吴丝蜀桐制成精美的箜篌。听到美妙的乐声，天空的白云凝聚起来不再飘游。
湘娥把泪珠洒满斑竹，九天素女也牵动满腔忧愁。出现这种情况，是由于乐工李凭在京城弹奏箜篌。
乐声清脆动听得就像昆仑山美玉击碎，凤凰鸣叫；时而使芙蓉在露水中饮泣，时而使香兰开怀欢笑。
清脆的乐声，融和了长安城十二门前的清冷光气。二十三根弦丝高弹轻拨，打动了高高在上的天帝。
高亢的乐声直冲云霄，冲上女娲炼石补过的天际。好似补天的五彩石被击破，逗落了漫天绵绵秋雨。
幻觉中仿佛乐工进入了神山，把技艺向女仙传授；老鱼兴奋得在波中跳跃，瘦蛟也翩翩起舞乐悠悠。
月宫中吴刚被乐声吸引，彻夜不眠在桂树下逗留。桂树下的兔子也佇立聆听，不顾露珠斜飞寒飕飕！', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d10ce818559d0588ba", "shortContent": "此诗大约作于元和六年（811）至元和八年，当时，李贺在京城长安，任奉礼郎。李凭是梨园弟子，因善弹箜篌，名噪一时。“天子一日一回见，王侯将相立马迎”（顾况《李供奉弹箜篌歌》），身价之高，似乎远远超过盛唐时期的著名歌手李龟年。他的精湛技艺，受到诗人们的热情赞赏。李贺此篇想象丰富，设色瑰丽，艺术感染力很强。清人方扶南把它与白居易的《琵琶行》、韩愈的《听颖师弹琴》相提并论，推许为“摹写声音至文”（见清方扶...", "authors": ["朱世英"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae4797a92d5e4fd91d", "shortContent": "此诗大约作于元和六年（811）至元和八年，当时，李贺在京城长安，任奉礼郎。李凭是梨园弟子，因善弹箜篌，名噪一时。“天子一日一回见，王侯将相立马迎”（顾况《李供奉弹箜篌歌》），身价之高，似乎远远超过盛唐时期的著名歌手李龟年。他的精湛技艺，受到诗人们的热情赞赏。李贺此篇想象丰富，设色瑰丽，艺术感染力很强。清人方扶南把它与白居易的《琵琶行》、韩愈的《听颖师弹琴》相提并论，推许为“摹写声音至文”（见清方扶...", "authors": ["朱世英"], "pressName": "上海辞书出版社"}, {"bookId": "6277f9fed4cef5295f72c610", "bookTitle": "李贺全集", "articleId": "63126dc2f2af4e09d55b6441", "shortContent": "深秋的一天，李凭在长安演奏箜篌。音乐刚一响起，就爆发出最强音，直上云霄，给人强烈的震撼，连天上的云彩都停止流动，聚集在一起静静聆听。随之曲调变得伤感起来，人们仿佛看到，悲痛欲绝的湘妃在岸边失声痛哭，她的眼泪滴答滴答落在湘竹之上；又仿佛听到，凄楚忧伤的素女也在拨弄琴弦，诉说幽幽心曲。悠扬低徊中，音乐突然明朗起来，如昆仑山的美玉相撞击，又如凤凰嘹亮优雅的鸣叫。音乐开始欢快起来，人们似乎可以看见，晶莹透...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707677683d19330153ce", "shortContent": "李凭是大名鼎鼎的梨园艺人，诗人杨巨源曾经写有《听李凭弹箜篌》，诗曰：“听奏繁弦玉殿清，风传曲度禁林明。君王听乐梨园暖，翻到《云门》第几声？”赞叹李凭弹箜篌之技艺高超、动人心魄。\n\n唐代另一位大诗人李贺则用天马行空的想象、神出鬼没的笔触，更形象地描绘了李凭的弹奏带给人们的力的震撼和美的体验。深秋的一天，在长安，李凭将要演奏箜篌。李凭拿出用吴地之丝、蜀地之桐所制造的箜篌，调好琴弦，开始演奏。音乐刚刚响...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f30c0e49f46528ad23d74", "shortContent": "此诗大约作于元和六年(811 )至元和八年，当时，李贺在京城长安，任奉礼郎。李凭是梨园弟子，因善弹箜篌，名噪一时。“天子一日一回见，王侯将相立马迎”（顾况《李供奉弹箜篌歌》），身价之高，似乎远远超过盛唐时期的著名歌手李龟年。他的精湛技艺，受到诗人们的热情赞赏。李贺此篇想象丰富，设色瑰丽，艺术感染力很强。清人方扶南把它与白居易的《琵琶行》、韩愈的《听颖师弹琴》相提并论，推许为“摹写声音至文”（见清方...", "authors": ["朱世英"], "pressName": "上海辞书出版社"}]', '《诚斋诗话》：诗有惊人句。杜《山水障》：「堂上不合生枫树，怪底江山起烟雾。」……李贺云：「女娲炼石补天处，石破天惊逗秋雨。」
《唐诗品汇》：刘云：其形容偏得于此，而于箜篌为近（「老鱼跳波」句下）。刘云：状景如画，自其所长。箜篌声碎有之，「昆山玉」颇无谓。下七字妙语，非玉箫不足以当，「石破天惊」过于绕梁遏云之上。至「教神妪」忽入鬼语。吴质懒态，月露无情。
《增订评注唐诗正声》：幽玄神怪，至此而极，妙在写出声音情态。
《唐诗快》：本咏箜篌耳，忽然说到女娲、神妪，惊天入月，变眩百怪，不可方物，真是鬼神于文。
《龙性堂诗话初集》：长吉耽奇凿空，真有「石破天惊」之妙，阿母所谓是儿不呕出心不已也。然其极作意费解处，人不能学，亦不必学。义山古体时效此调，却不能工，要非其至也。
《李长吉诗集批注·巻一》：白香山「江上琵琶」，韩退之《颖师琴》，李长吉《李凭箜篌》，皆摹写声音至文。韩足以惊天，李足以泣鬼，白足以移人。
《唐贤小三昧集》：七字可作昌谷诗评《「石破天惊」句下）。
《王闿运手批唐诗选》：接突兀（「昆山玉碎」二句下）。
《唐宋诗举要》：吴云：通体皆从神理中曲曲摹绘，出神入幽，无一字落恒人蹊径。', 'center', 1423215483, '57b92a940a2b58005c93a708', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10422, '行香子 · 述怀', NULL, 1761, 3406, 5, 2, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/6234932.htm', '', '清夜无尘，月色如银。酒斟时、须满十分。浮名浮利，虚苦劳神。叹隙中驹，石中火，梦中身。
虽抱文章，开口谁亲。且陶陶、乐尽天真。几时归去，作个闲人。对一张琴，一壶酒，一溪云。', '此词所作时间不详。从内容上看，表达的是归隐志向，这种志向自作者被贬黄州后逐渐强烈，时不时会从心底冒出。在一个把酒对月的夜晚，已厌倦了官场生活的苏轼，再次表述了这一情怀。', '行香子：词牌名，又名《爇心香》、《读书引》。自南北朝，朝廷即设「行香」法会。南宋·程文简《演繁露·卷七·行香》云：「沈存中叙行香，谓『当以香末散撒』，乃为行香。毕仲荀元丰三年作《幕府燕閒录》曰：『国忌行香起于后魏江左。齐梁间每然香熏手，或以香末散行，谓之行香。』予案《南史》：『王僧达性好鹰犬。……何尚之设八关斋，大集朝士，自行香，次至僧达曰：「愿郎且放鹰犬，勿复游猎。」』其谓行香次及僧达者，即释教之谓行道烧香也。行道者，主斋之人亲自周行道场之中；烧香者，熟之於炉也。」唐·张水部《送令狐尚书赴东都留守》诗：「行香暂出天桥上，巡礼常过禁殿中。」故此调当为佛曲，调名本意即咏佛教行道烧香事。《中原音韵》、《太平乐府》俱注「双调」，蒋氏《九宫谱目》入「中吕引子」（《钦定词谱》）。此调当为重头曲，六十六字，有三体，前后阕俱八句，唯首句用韵或不用韵异。此调以四言句和三言句为主，间以两个上三下四之七言句，结尾以一字领三个三言句，前人多于此三句中构词相同而又意义连贯，尤别致。音节颇流美悦耳，亦可略加衬字（龙榆生《唐宋词格律》）。东坡七首用于咏物、写景、酬赠、感叹人生；稼轩五首具嘲讽之意，风格更为恣肆；亦用以言情，如洪空同《楚楚精神》阕，蒋竹山《舟宿兰湾》阕。
「述怀」：傅注本、元延祐本无题。明吴讷钞本、《苏长公二妙集》本、毛本调名下有词题曰「述怀」。
虚苦：《苏长公二妙集》本、毛本作「休苦」。
「月色如银」句：傅子立注：「梁戴皓《月诗》：『浮川疑让璧，入户类烧银。』」刘尚荣按：「句出《月重轮行》诗，见《乐府诗集·卷四十》，别见《文苑英华·卷一百九十三》。『璧』原作『壁』，据《乐府诗集》改。」
「酒斟时、须满十分」句：傅子立注：「白乐天：『十分蘸甲酌。』」刘尚荣按：「句出《早饮湖州酒寄崔使君》，见《白氏长庆集·卷二十三》。」
隙中驹：傅子立注：「《庄子》曰：『人生天地间，如白驹之过隙，忽然而已。』」刘尚荣按：「见《庄子·卷二十二·〈外篇·知北游〉》。《庄子》『如』原作『若』，『隙』原作『郤』，『郤』通『隙』。」
石中火：傅子立注：「李太白诗：『石火无留光，还如世中人。』」刘尚荣按：「句出《拟古十二首·其三》，见《李太白诗集·卷二十四》。『留』原作『烟』，据《李太白诗集》改。」
梦中身：傅子立注：「韩退之：『须著人间比梦间。』」刘尚荣按：「句出《游城南十六首·遣兴》，见《全唐诗·卷三百四十三》。《五百家集注昌黎文集·卷九》诗题作『远兴』。『比』原作『此』，据《全唐诗》改。」
陶陶：傅子立注：「刘伶《酒德颂》：『无思无虑，其乐陶陶。』」刘尚荣按：「语见《文选·卷四十七·刘伯伦〈酒德颂〉》。」', '夜气清新，尘滓皆无，月光皎洁如银。值此良辰美景，把酒对月，须尽情享受。名利都如浮云变幻无常，徒然劳神费力。人的一生只不过像快马驰过缝隙，像击石迸出一闪即灭的火花，像在梦境中短暂的经历一样短暂。
虽有满腹才学，却不被重用，无所施展。姑且借现实中的欢乐，忘掉人生的种种烦恼。何时能归隐田园，不为国事操劳。有琴可弹，有酒可饮，赏玩山水，就足够了。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b4d635634aee3d718f", "shortContent": "这首词的写作时间不可确考，从其所表现的强烈退隐愿望来看，应是苏轼在元祐时期（1086—1093）的作品。当时宋哲宗年幼，高太后主持朝政，罢行新法，起用旧派，苏轼受到特殊恩遇。但是政敌朱光庭、黄庆基等人曾多次以类似“乌台诗案”之事欲再度诬陷苏轼，因高太后的保护，他虽未受害，但却使他对官场生活无比厌倦，感到“心形俱悴”，产生退隐思想。苏轼曾在诗中表示：“老病思归真暂寓，功名如幻终何得。从来自笑画蛇足，...", "authors": ["谢桃坊"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ba0f8fda5565060489", "shortContent": "这首词的写作时间不可确考，从其所表现的强烈退隐愿望来看，应是苏轼在元祐时期（1086—1093）的作品。当时宋哲宗年幼，高太后主持朝政，罢行新法，起用旧派，苏轼受到特殊恩遇。但是政敌朱光庭、黄庆基等人曾多次以类似“乌台诗案”之事欲再度诬陷苏轼，因高太后的保护，他虽未受害，但却使他对官场生活无比厌倦，感到“心形俱悴”，产生退隐思想。苏轼曾在诗中表示：“老病思归真暂寓，功名如幻终何得。从来自笑画蛇足，...", "authors": ["谢桃坊"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7d9761253910e902af", "shortContent": "朱本、龙本、石唐本未编年。孔《谱》未载。薛本谓此词与作于元祐八年（1093）出知定州所作《行香子》（三入承明）一阕意相连属，疑为一时之作。邹王本从之。沈松勤《苏轼词编年补证》编此词于元祐二年（1087）或三年间翰林任上。他认为词中贪酒求闲及感叹“浮名浮利”及求“归去”的心情,与作者在元祐二年至三年间的诗篇中多有表现，故编于此时。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "64683c227f27182da362ac1a", "shortContent": "这首词的写作时间不可确考，从其所表现的强烈退隐愿望来看，应是苏轼在元祐时期（1086—1093）的作品。当时宋哲宗年幼，高太后主持朝政，罢行新法，起用旧派，苏轼受到特殊恩遇。但是政敌朱光庭、黄庆基等人曾多次以类似“乌台诗案”之事欲再度诬陷苏轼，因高太后的保护，他虽未受害，但却使他对官场生活无比厌倦，感到“心形俱悴”，产生退隐思想。苏轼曾在诗中表示：“老病思归真暂寓，功名如幻终何得。从来自笑画蛇足，...", "authors": ["谢桃坊"], "pressName": "上海辞书出版社"}]', '', 'indent', 1373985304, '57b2c8fa7db2a20054377ecd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (12058, '辨奸论', NULL, 66, 65, 3, 1, '苏洵', NULL, 10289, '57ba68a7c4c97100614c5723', '宋', 'wen', '文', 'http://baike.baidu.com/view/863129.htm', '', '事有必至，理有固然。惟天下之静者，乃能见微而知著。月晕而风，础润而雨，人人知之。人事之推移，理势之相因，其疏阔而难知，变化而不可测者，孰与天地阴阳之事。而贤者有不知，其故何也？好恶乱其中，而利害夺其外也!
昔者，山巨源见王衍曰：“误天下苍生者，必此人也!”郭汾阳见卢杞曰：“此人得志。吾子孙无遗类矣!”自今而言之，其理固有可见者。以吾观之，王衍之为人，容貌言语，固有以欺世而盗名者。然不忮不求，与物浮沉。使晋无惠帝，仅得中主，虽衍百千，何从而乱天下乎？卢杞之奸，固足以败国。然而不学无文，容貌不足以动人，言语不足以眩世，非德宗之鄙暗，亦何从而用之？由是言之，二公之料二子，亦容有未必然也!
今有人，口诵孔、老之言，身履夷、齐之行，收召好名之士、不得志之人，相与造作言语，私立名字，以为颜渊、孟轲复出，而阴贼险狠，与人异趣。是王衍、卢杞合而为一人也。其祸岂可胜言哉？夫面垢不忘洗，衣垢不忘浣。此人之至情也。今也不然，衣臣虏之衣。食犬彘之食，囚首丧面，而谈诗书，此岂其情也哉？凡事之不近人情者，鲜不为大奸慝，竖刁、易牙、开方是也。以盖世之名，而济其未形之患。虽有愿治之主，好贤之相，犹将举而用之。则其为天下患，必然而无疑者，非特二子之比也。
孙子曰：“善用兵者，无赫赫之功。”使斯人而不用也，则吾言为过，而斯人有不遇之叹。孰知祸之至于此哉？不然。天下将被其祸，而吾获知言之名，悲夫!', '《辨奸论》是北宋古文名篇。此文宋本《嘉祐集》不载，见于南宋吕祖谦编选的《宋文鉴》，《古文观止》列于苏洵名下，但一说为邵伯温托苏洵名作，该问题的研究自清初李绂作《书<辨奸论>後》开始，至20世纪末王水照先生作《再论<辨奸论>真伪之争——读邓广铭先生再论<辨奸论>非苏洵所作》，尚无定论。', '静者：指能够冷静地观察周围事物而做出合理结论的贤人。
天地阴阳之事：指自然现象。古人认为自然界有阴阳二气，二气交互發生作用，便产生了形形色色的自然变化。
贤者：旧说以为是影射欧阳修。据史书记载，曾巩曾向欧阳修推荐王安石的文章，欧阳修大加赞赏，并帮助王安石考取了进士。
山巨源：山涛（公元205年—283年），字巨源，晋初人，任吏部尚书，为当时的“竹林七贤”之一。他喜好评论人物，对王衍的评价不高。
王衍（公元256年—311年）：字夷甫，晋初人，任尚书令、太尉。衍有盛才，常自比子贡。当时晋室诸王擅权，他周旋于诸王间，唯求自全之计，後死于战乱之中。
郭汾阳：即郭子仪（公元697年—781年），唐华州（今属陕西）人，累官至太尉、中书令，曾平定安史之乱，破吐蕃，以一身系国家安危者二十年，後封为汾阳郡王，世称郭汾阳。
卢杞：字子良，唐滑州（今河南滑县一带）人，唐德宗时任宰相，搜刮民财，排斥异己。杞相貌丑陋，好口辩。後被贬职死于外地。
忮(zhì)：嫉恨。
惠帝：晋惠帝(公元290年—306年在位)，晋开国君主司马炎之子，以痴呆闻名。他在位时不理朝政，大权旁落，终导致“八王之乱”，晋室随之衰败。
眩(xuàn)：通“炫”，惑乱。
德宗：唐德宗(公元780—805在位)，唐代晚期的庸君，他削去郭子仪的兵权，重用卢杞，导致朝政紊乱。', '事情的發展必定会有一定的结局，道理有它原本就该如此的规律。天下只有表现冷静的人，才能从细微之处预见到日後将会發生的显著变化。月亮周围出现了晕圈预示着将要刮风，房屋的石柱返潮湿润预示着将要下雨，这是人人皆知的事。人事的發展变化，情理和形势之间的因果关系，也是空疏渺茫难以尽知，千变万化而无法预先料到的，怎么能和天地阴阳的变化相比？即便是贤能的人对此也有所不解。这是什么原因呢？这是由于喜爱和憎恨扰乱了他们的内心，利害关系又影响了他们的行动啊!
从前山巨源见到王衍，说：“将来给天下百姓带来灾难的，一定是这个人!”郭汾阳见到卢杞，说：“这个人一旦得志，我的子孙就会被他杀得一个不留!”现在分析一下他们所说的话。其中的道理是可以料想到的。依我看来，王衍之为人，从容貌和谈吐上，确实具备了欺世盗名的条件。但是他不妒忌别人，不贪图钱财，只是随大流。如果晋朝当时没有惠帝这个昏君，当政者即使只是一个中等的君主，就算是有成百上千个王衍这样的人，又怎能扰乱天下呢？卢杞那样的奸诈，确实足以败坏国家。但是他不学无术，容貌不足以动人，言谈不足以蒙蔽社会，如果不是遇到德宗这样的鄙陋昏庸的君主，又怎能受到重用呢？由此说来，山、郭二公对王、卢二人所作的预言，也未必完全如此啊!
现在有人嘴里背诵着孔子、老子的话，亲身实践着伯夷、叔齐的行为，收罗了一批追求名声和不得志的士人，相互制造舆论，私下里互相标榜，以为自己是颜渊、孟轲再世，然而他们为人阴险狠毒，和一般人的志趣不同。这是把王衍和卢杞合成一个人了。他在社会上酿造的祸害还能说得完吗？脸面脏了不忘洗脸，衣服脏了不忘洗衣，这本是人之常情。现在他却不是这样，身穿奴仆的衣服，吃猪狗的食物，头髮蓬乱得像囚犯，表情哭丧着像家里有人去世，却在那里大谈《诗》《书》，这难道说是人的真实的心情吗？凡是办事不近人情的，很少不成为大奸大恶之辈，竖刁、易牙、开方就是这样的人。此人借助当世享有盛名之力，来促成他尚未形成气候的祸患。虽然有励精图治的君主，敬重贤才的宰相，也还是会选拔并重用他的。这样，他将成为天下的祸患，是必定无疑的了，这就不只是王、卢二人所能比拟的。
孙子说：“善于用兵的人，并没有显赫的功勋。”如果这个人没有被重用，那么我的话就有些过头了，而此人就会有怀才不遇的感慨。谁又能知道祸患会达到上述这种地步呢？不然的话，天下将要蒙受他的祸害，而我也会获取卓有远见的名声，那就太可悲了!', NULL, '', 'indent', 1477659147, '5812d98c2e958a00548ac51c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10423, '江南逢李龟年', NULL, 1119, 1416, 1, 9, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/156039.htm', '', '岐王宅里寻常见，崔九堂前几度闻。
正是江南好风景，落花时节又逢君。', '此诗大概作于大历五年（公元770年）杜甫在长沙的时候。李龟年，唐朝开元、天宝年间的著名乐师，擅长唱歌。因为受到皇帝唐玄宗的宠幸而红极一时。“安史之乱”后，李龟年流落江南，卖艺为生。杜甫漂泊到江南一带，和李龟年重逢，回忆起在岐王和崔九的府第频繁相见和听歌的情景而感慨万千，写下这首诗。
语言极平易，而含意极深远，包含着非常丰富的社会生活内容，表达出了时世凋零丧乱与人生凄凉飘零之感。那种昔盛今衰，构成了尖锐的对比，使读者感到诗情的深沉与凝重。诗的开首二句是追忆昔日与李龟年的接触，寄寓诗人对开元初年鼎盛的眷怀；后两句是对国事凋零，艺人颠沛流离的感慨。仅仅四句却概括了整个开元时期的时代沧桑、人生巨变。', '李龟年：唐朝开元、天宝年间的著名乐师，擅长唱歌。因为受到皇帝唐玄宗的宠幸而红极一时。“安史之乱”后，李龟年流落江南，卖艺为生。
岐王：唐玄宗李隆基的弟弟， 名叫李范，以好学爱才著称，雅善音律。寻常：经常。
崔九：崔涤，在兄弟中排行第九，中书令崔湜的弟弟。玄宗时，曾任殿中监，出入禁中，得玄宗宠幸。崔姓，是当时一家大姓，以此表明李龟年原来受赏识。
江南：这里指今湖南省一带。
落花时节：暮春，通常指阴历三月。落花的寓意很多，人衰老飘零，社会的凋弊丧乱都在其中。
君：指李龟年。', '当年在岐王宅里，常常见到你的演出；在崔九堂前，也曾多次欣赏你的艺术。
没有想到，在这风景一派大好的江南；正是落花时节，能巧遇你这位老相熟。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b134a8757d5a0e1ca3", "shortContent": "这是杜甫绝句中最有情韵、最富含蕴的一篇，只二十八字，却包含着丰富的时代生活内容。如果诗人当年围绕安史之乱的前前后后写一部回忆录，是不妨用它来题卷的。\n李龟年是开元时期“特承顾遇”的著名歌唱家。杜甫初逢李龟年，是在“开口咏凤凰”的少年时期，正值所谓“开元全盛日”。当时王公贵族普遍爱好文艺，杜甫即因才华早著而受到岐王李范和秘书监崔涤的延接，得以在他们的府邸欣赏李龟年的歌唱。而一位杰出的艺术家，既是特定...", "authors": ["刘学锴", "余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f459761253910e903b7", "shortContent": "他乡遇故知，是唐诗中常见的题材，多表达对朋友之思念与重逢之喜悦。但杜甫这首七绝，虽短短二十八字，却语浅而情真，涵蕴隽永，称得当上“言情在笔墨之外，悄然数语，可抵白氏一篇《琵琶行》矣”（《唐宋诗醇》）。\n\n从字面意思上来看，本诗通俗易懂，节奏明快，朗朗上口，表达的是诗人在江南与旧友重逢时的喜悦。然而，对此诗的解读必须跟创作背景紧密联系起来。此诗作于大历五年（770）杜甫寄居长沙之时。此时，安史之乱已...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "64662eef5e6bb82b8ccae339", "shortContent": "这是杜甫绝句中最有情韵、最富含蕴的一篇，只二十八字，却包含着丰富的时代生活内容。如果诗人当年围绕安史之乱的前前后后写一部回忆录，是不妨用它来题卷的。\n\n李龟年是开元时期“特承顾遇”的著名歌唱家。杜甫初逢李龟年，是在“开口咏凤凰”的少年时期，正值所谓“开元全盛日”。当时王公贵族普遍爱好文艺，杜甫即因才华早著而受到岐王李范和秘书监崔涤的延接，得以在他们的府邸欣赏李龟年的歌唱。而一位杰出的艺术家，既是特...", "authors": ["刘学锴", "余恕诚"], "pressName": "上海辞书出版社"}]', '《云溪友议》：明皇帝幸岷山，百官皆窜辱，积尸满中原，士族随车驾也。伶官：张野狐觱栗、雷海青琵琶、李龟年唱歌、公孙大娘舞剑……唯李龟年奔泊江潭，杜甫以诗赠之曰：“岐王宅里寻常见……落花时节又逢君。”
《木天禁语》：绝句篇法：藏咏。
《杜诗说》：此诗与《剑器行》同意。今昔盛衰之感，言外*然欲绝。见风韵于行间，寓感慨于字里，即使龙标、供奉操笔，亦无以过。乃知公于此体，非不能为正声，直不屑耳。有目公七言绝句为别调者，亦可持此解嘲矣。
《李杜诗选》：刘曰：兴来感旧，不觉真率自然。
《义门读书记》：四句浑浑说去，而世运之盛衰，年华之迟暮，两人之流落，俱在言表。
《唐诗摘钞》：一、二总藏一“歌”字。“江南”字见地，“落花时节”见时，四字将“好风景”三字衬润一层。“正是”字、“又”字紧醒前二句，明“岐宅”、“崔堂”听歌之时，无非“好风景”之时也。今风景不殊，而回思天宝之盛，已如隔世，流离异地，旧人相见，亦复何堪？无限深情，俱藏于数虚字之内。杜有此七言绝而选者多忽之，信识真者之少也。
《唐宋诗醇》：言情在笔墨之外，悄然数语，可抵白氏一篇《琵琶行》矣。“休唱贞元供奉曲，当时朝士已无多”，刘禹锡之婉情；“钿蝉金雁皆零落，一曲伊州泪万行”，温庭筠之哀调。以彼方此，何其超妙！此千秋绝调也。
《唐诗别裁》：含意未伸，有案无断。
《杜诗镜铨》：邵云：子美七绝，此为压卷。
《唐诗笺注》：“落花时节又逢君”，多少盛衰今昔之思！上二句是追旧，下二句是感今，却不说尽，偏着“好风景”三字，而意含在“正是”字、“又”字内。
《唐诗从绳》：无限深情，俱藏裹于数虚字之内，真妙作也。
《诗法易简录》：少陵七绝多类《竹枝》体，殊失正宗。此诗纯用止锋、藏锋，深得绝句之味。
《唐诗近体》：含意未伸，有案无断；而世运之治乱、年华之盛衰、彼此之凄凉流落，俱在其中。
《唐诗评注读本》：王文濡曰：上二句极言其宠遇之隆，下二句陡然一转，以见盛衰不同，伤龟年亦所以自伤也。
《诗境浅说续编》：少陵为诗家泰斗，人无间言，而皆谓其不长于七绝。今观此诗，馀味深长，神韵独绝，虽王之涣之“黄河远上”，刘禹锡之“潮打空城”，群推绝唱者，不能过是。此诗以多少盛衰之感，千万语无从*起，皆于“又逢君”三字之中，蕴无穷酸泪。', 'center', 1374055589, '57b90968c4c97100558f6734', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10424, '相见欢', NULL, 1157, 87, 2, 3, '李煜', NULL, 10017, '57b8af7c5bbb50005b770fdd', '五代十国', 'ci', '词', 'http://baike.baidu.com/view/652805.htm', '', '林花谢了春红，太匆匆。无奈朝来寒雨晚来风。
胭脂泪，相留醉，几时重？自是人生长恨水长东。', '相见欢，词牌名，又名“乌夜啼”“忆真妃”“月上瓜州”等。以薛昭蕴《相见欢·罗襦绣袂香红》为正体，双调三十六字，前段三句三平韵，后段四句两仄韵两平韵。另有双调三十六字，前段三句三平韵，后段四句一叶韵一叠韵两平韵；双调三十六字，前段三句三平韵，后段三句两平韵等变体。代表作有李煜《相见欢·无言独上西楼》等。
这首词当作于北宋太祖开宝八年（公元975年）李煜被俘之后。南唐灭亡，李煜被俘北上，留居汴京（今河南开封）二年多。此词即写于作者身为阶下囚时期。
此词是即景抒情的典范之作，它将人生失意的无限怅恨寄寓在对暮春残景的描绘中，表面上是伤春咏别，实质上是抒写「人生长恨水长东」的深切悲慨。这种悲慨不仅是抒写一己的失意情怀，而且是涵盖了整个人类所共有的生命的缺憾，是一种融汇和浓缩了无数痛苦的人生体验的浩叹。', '谢：凋谢。
春红：春天的花朵。
匆匆：一作「忽忽」。
无奈：一作「常恨」。
寒雨：一作「寒重」。
晚：一作「晓」。
胭脂泪：原指女子的眼泪，女子脸上搽有胭脂，泪水流经脸颊时沾上胭脂的红色，故云。在这里，胭脂是指林花着雨的鲜艳颜色，指代美好的花。胭脂，一作「臙脂」，又作「燕支」。
相留醉：一本作「留人醉」，意为令人陶醉。留，遗留、给以；醉，心醉。
几时重（chóng）：何时再度相会。
自是：自然是、必然是。', '树林间的红花已经凋谢，花开花落，才有几时，实在是去得太匆忙了。也是无可奈何啊，花儿怎么能经得起那凄风寒雨昼夜摧残呢？
飘落遍地的红花，被雨水淋过，像是美人双颊上的胭脂在和着泪水流淌。花儿和怜花人相互留恋，如醉如痴，什么时候才能再重逢呢？人生从来就是令人遗憾的事情太多，就像那东逝的江水，不休不止，永无尽头。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74920f8fda556504d915", "shortContent": "南唐后主的这种词，都是短幅的小令，况且明白如话，不待讲析，自然易晓。他所“依靠”的，不是粉饰装做，扭捏以为态，雕琢以为工，这些在他都无意为之；所凭的只是一片强烈直爽的情性。其笔亦天然流丽，如不用力，只是随手抒写。这些自属有目共见。但如以为他这“随手”就是任意“胡来”，文学创作都是以此为“擅场”，那自然也是一个笑话。即如首句，先出“林花”，全不晓毕竟何林何花；继而说是“谢了春红”，乃知是春林之红花，...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892d9820695e6503fd6d", "shortContent": "南唐后主的这种词，都是短幅的小令，况且明白如话，不待讲析，自然易晓。他所“依靠”的，不是粉饰装做，扭捏以为态，雕琢以为工，这些在他都无意为之；所凭的只是一片强烈直爽的情性。其笔亦天然流丽，如不用力，只是随手抒写。这些自属有目共见。但如以为他这“随手”就是任意“胡来”，文学创作都是以此为“擅场”，那自然也是一个笑话。即如首句，先出“林花”，全不晓毕竟何林何花；继而说是“谢了春红”，乃知是春林之红花，...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126e097ccdb86c49f28efd", "shortContent": "调名，《乐府雅词》作“忆真妃”。《花草粹编》将此首归人《相见欢》，在李后主下注“乌夜啼”。乌夜啼，原为唐教坊曲，又名“相见欢”、“秋夜月”、“上西楼”。这首词是李煜后期词作的代表作之一。为李煜人宋后所作，抒写人生失意的无限怅恨，是一篇即景抒情的名作。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471faa245e4710056fc2837", "shortContent": "亡国前耽于享乐，亡国后溺于悲哀，这就是李后主的一生。宋太祖开宝八年(975)，宋军围攻金陵，李煜肉袒出降，被封为“违命侯”。从此，幽居在汴京的一座深院小楼，过着日夕以眼泪洗面的凄凉寂寞的日子。这首《相见欢》就是写这种幽囚生活的愁苦滋味。\n这首词特别为后世词家极口称道的，是它对“离愁”的描写。“离愁”，是人们内心一种抽象的感情，后主把它写得很形象，写出其滋味，写出一种非常深切的人生感受，确是千古妙笔...", "authors": ["高原"], "pressName": "上海辞书出版社"}]', '谭献《词辨》：濡染大笔。
俞陛云《唐五代两宋词选释》：后主为樊若水所卖，举国与人。词借伤春为喻，恨风雨之摧花，犹逆臣之误国，迫魁柄一失，如水之东流，安能挽沧海尾间，复鼓回澜之力耶！
俞平伯《读词偶得》：此词全用杜诗「林花着雨胭脂湿」，却分作两阕，可悟点化成句之法。上阕只三韵耳，而一韵一折，犹书家所谓「无垂不缩」，特后主气度雄肆，虽骨子里笔笔在转换，而行之以浑然元气。谭献曰：「濡染大笔。」殆谓此也。首叙，次断，三句溯其经过因由，花开花谢，朝朝暮暮，风风雨雨，片片丝丝，包孕甚广。试以散文译之，非恰好三小段而何？下阕三短句一气读。忽人人事，似与上阕断了脉络。细按之，不然。盖「春红护」二字己远为「胭脂」作根，而匆匆风雨，又处处关合「泪」字。春红着雨，非胭脂泪钦，心理学者所谓联想也。结句转为重大之笔，与「一江春水」意同，因此特沉着，后主之词，兼有阳刚阴柔之美。
唐圭璋《唐宋词简释》：此首伤别，从惜花写起。「太匆匆」三字，极传惊叹之神，「无奈」句，又转怨恨之情，说出林花所以速谢之故，朝是雨打，晚是风吹，花何以堪，人何以堪。说花即以说人，语固双关也。「无奈」二字，且见无力护花，无计回天之意。一片珍惜怜爱之情，跃然纸上。下阕，明点人事，以花落之易，触及人别离之易。花不得重上故枝，人亦不易重逢也。「几时重」三字轻顿；「自是」句重落。以水之必然长东，喻人之必然长恨，语最深刻。「自是」二字，尤能揭出人生苦闷之义蕴，与「此外不堪行」，「肠断更无疑」诸语，皆重笔收来，沉哀人骨。
唐圭璋《屈原与李后主》：以水必然长东，以喻人之必然长恨，沉痛已极。', 'indent', 1415637844, '57b8af85128fe10054c87518', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10425, '归园田居（其三）', NULL, 635, 99, 2, 4, '陶渊明', NULL, 10011, '57b8fa07c4c97100558ef104', '晋', 'shi', '诗', 'http://baike.baidu.com/subview/162513/4998396.htm', '', '种豆南山下，草盛豆苗稀。
晨兴理荒秽，带月荷锄归。
道狭草木长，夕露沾我衣。
衣沾不足惜，但使愿无违。', '此诗是晋末宋初大诗人陶渊明创作的组诗《归园田居》五首的第三首。这首诗十分细腻、生动地描写了诗人对农田劳动生活的体验。作品既因运用典故而使诗句的含蕴更为深远，又不因运用典故而使诗句失去真淳的情意，风格清淡而又不失典雅，洋溢着诗人心情的愉快和对归隐的自豪。', '南山：指庐山。
稀：稀少。
兴：起身，起床。
荒秽：指野草之类。形容词作名词。秽：肮脏。这里指田中杂草。
带：一作「戴」，披。荷（hè）锄：扛着锄头。荷，扛着。
狭：狭窄。
草木长：草木丛生。
夕露：傍晚的露水。
沾：打湿。
足：值得。
「但使愿无违」句：只要不违背自己的意愿就行了。但，只；违，违背。', '南山下田野里种植豆子，结果是草茂盛豆苗疏稀。
清晨起下田地铲除杂草，暮色降披月光扛锄回去。
狭窄的小路上草木丛生，傍晚时有露水沾湿我衣。
身上衣沾湿了并不可惜，只愿我不违背归隐心意。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccaad635634aee3ea580", "shortContent": "《归园田居》第一首的结尾二句，是“久在樊笼里，复得返自然”。所谓“自然”，不仅指乡村的自然环境，亦是指自然的生活方式。在陶渊明看来，为口腹所役，以社会的价值标准作为自己的行动准则，追逐富贵，追逐虚名，都是扭曲人性、失去自我的行为。而自耕自食，满足于俭朴的生活，舍弃人与人之间的竞逐与斗争，这才是自然的生活方式。不管这种认识在社会学中应作如何评价，终究是古今中外反复被提出的一种思想。当然，陶渊明作为一...", "authors": ["孙", "明"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4547f27182da33f706b", "bookTitle": "陶渊明诗文鉴赏辞典", "articleId": "6469edaa30675327e19f2142", "shortContent": "《归园田居》第一首的结尾二句，是“久在樊笼里，复得返自然”。所谓“自然”，不仅指乡村的自然环境，亦是指自然的生活方式。在陶渊明看来，为口腹所役，以社会的价值标准作为自己的行动准则，追逐富贵，追逐虚名，都是扭曲人性、失去自我的行为。而自耕自食，满足于俭朴的生活，舍弃人与人之间的竞逐与斗争，这才是自然的生活方式。不管这种认识在社会学中应作如何评价，终究是古今中外反复被提出的一种思想。当然，陶渊明作为一...", "authors": ["孙明"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "6470a484b6a81d0c53261b21", "shortContent": "《归园田居》第一首的结尾二句，是“久在樊笼里，复得返自然”。所谓 “自然”，不仅指乡村的自然环境，亦是指自然的生活方式。在陶渊明看 来，为口腹所役，以社会的价值标准作为自己的行动准则，追逐富贵，追逐 虚名，都是扭曲人性、失去自我的行为。而自耕自食，满足于俭朴的生活， 舍弃人与人之间的竞逐与斗争，这才是自然的生活方式。不管这种认识 在社会学中应作如何评价，终究是古今中外反复被提出的一种思想。当 然，...", "authors": ["孙明"], "pressName": "上海辞书出版社"}]', '苏轼：以「夕露沾衣」之故而违其所愿者，多矣！
查慎行：前言桑麻，此言种豆，皆田园中实事，亦有次第。
龚望《陶渊明集评议》：五古中之精金秀玉。陶公本色，于这样诗可见。', 'center', 1413386522, '57b8fbbdc4c97100558efd3a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10426, '塞下曲 其三', NULL, 680, 341, 1, 9, '卢纶', NULL, 10014, '57b9c2f6c4c97100614832f4', '唐', 'shi', '诗', 'http://baike.baidu.com/view/655309.htm', '', '月黑雁飞高，单于夜遁逃。
欲将轻骑逐，大雪满弓刀。', '此诗为卢纶组诗《塞下曲》中的第三首。卢纶曾任幕府中的元帅判官，对行伍生活有体验，描写此类生活的诗比较充实，风格雄劲。这首诗写将军雪夜准备率兵追敌的壮举，气概豪迈。诗句虽然没有直接写激烈的战斗场面，但留给了读者广阔的想象空间，营造了诗歌意蕴悠长的氛围。', '塞下曲：古时边塞的一种军歌。
月黑：没有月光。
单于（chányú）：匈奴的首领。这里指入侵者的最高统帅。
遁：逃走。
将：率领。
轻骑：轻装快速的骑兵。
逐：追赶。
满：沾满。', '暗淡的月夜里，一群大雁惊叫着高飞而起，暴露了单于的军队想要趁夜色潜逃的阴谋。将军率领轻骑兵一路追杀，顾不得漫天的大雪已落满弓和刀。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ba03048e64fbd9144c", "shortContent": "《塞下曲》组诗共六首，这是第三首。卢纶虽为中唐诗人，其边塞诗却依旧是盛唐的气象，雄壮豪放，字里行间充溢着英雄气概，读后令人振奋。\n一、二句“月黑雁飞高，单于夜遁逃”，写敌军的溃退。“月黑”，无光也。“雁飞高”，无声也。趁着这样一个漆黑的阒寂的夜晚，敌人悄悄地逃跑了。单于，是古时匈奴最高统治者，这里代指入侵者的最高统帅。“夜遁逃”，可见他们已经全线崩溃。\n尽管有夜色掩护，敌人的行动还是被我军察觉了。...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a93", "shortContent": "《塞下曲》组诗共六首，这是第三首。卢纶虽为中唐诗人，其边塞诗却依旧是盛唐的气象，雄壮豪放，字里行间充溢着英雄气概，读后令人振奋。\n\n一、二句“月黑雁飞高，单于夜遁逃”，写敌军的溃退。“月黑”，无光也。“雁飞高”，无声也。趁着这样一个漆黑的阒寂的夜晚，敌人悄悄地逃跑了。单于，是古时匈奴最高统治者，这里代指入侵者的最高统帅。“夜遁逃”，可见他们已经全线崩溃。\n\n尽管有夜色掩护，敌人的行动还是被我军察觉...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706a73206168b2e02200", "shortContent": "“塞下曲”是唐代诗人写得很多的乐府旧题。卢纶《塞下曲》组诗共六首，有说是题目应为《和张仆射塞下曲》，这是第二首。首句交代了具体的时间、地点。在夜暗星稀的晚上，树林里的光线更加黯淡，忽然一阵疾风吹来，草木为之惊颤。密林中有可能是隐藏着猛虎，也有可能是埋伏着敌军，总之是周围有危险存在，随时都有可能发生。明写“草惊”，其实是人惊，渲染了一种异常紧张的气氛。面对这种危急情况，将军没有表现出丝毫的惊慌失措，...", "authors": ["陈鹏"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706a73206168b2e02201", "shortContent": "《塞下曲》本是乐府旧题，用来写边塞风光和军旅生活。卢纶的《塞下曲》共六首，分别描绘了发号施令、射猎破敌、奏凯庆功等等不同场景，表现了边塞将士的英雄气概和艰苦的战斗生活。这里选的是其中的第三首，写将士们雪夜追击溃敌的情景。\n\n“月黑雁飞高，单于夜遁逃。”一、二两句写敌军的溃退。“单于”是匈奴君主的称号。匈始是我国古代民族，战国时游牧在燕、赵、秦以北。秦汉以来，不时南侵中原，成为北部边防的对象。唐人写...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270f7f2af4e09d55b6827", "shortContent": "《塞下曲》本是乐府旧题，用来写边塞风光和军旅生活。卢纶的《塞下曲》共六首，分别描绘了发号施令、射猎破敌、奏凯庆功等等不同场景，表现了边塞将士的英雄气概和艰苦的战斗生活。这里选的是其中的第三首，写将士们雪夜追击溃敌的情景。\n\n“月黑雁飞高，单于夜遁逃。”一、二两句写敌军的溃退。“单于”是匈奴君主的称号。匈始是我国古代民族，战国时游牧在燕、赵、秦以北。秦汉以来，不时南侵中原，成为北部边防的对象。唐人写...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471a089902ee364cc9387b5", "shortContent": "《塞下曲》组诗共六首，这是第三首。字里行间充溢着英雄气概，读后令人振奋。\n一、二句“月黑雁飞高，单于夜遁逃”，写敌军的溃退。“月黑”，无光也。“雁飞高”，无声也。趁着这样一个漆黑的阒寂的夜晚，敌人悄悄地逃跑了。单于，是古时匈奴最高统治者，这里代指入侵者的最高统帅。“夜遁逃”，可见他们已经全线崩溃。\n尽管有夜色掩护，敌人的行动还是被我军察觉了。三、四句“欲将轻骑逐，大雪满弓刀”，写我军准备追击的情形...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}]', '《唐诗训解》：中唐音律柔弱，此独高健，得意之作。此见边威之壮，守备之整，而惜士卒寒苦也。允言语素卑弱，独此绝雄健，堪入盛唐乐府。（李攀龙）
《唐诗选脉会通评林》：中唐高调，句句挺拔。顾璘曰：健。所谓古乐府者，此篇可参。（周敬）
《诗源辨体》：纶五言绝“月黑雁飞高”一首，气魄皆调，中唐所无。
《唐风定》：音节最古，与《哥舒歌》相似。
《诗法易简录》：上二句言匈奴畏威远遁。下二句不肯邀开边之功，而托言大雪，便觉委婉，而边地之苦亦自见。
清·黄生《唐诗摘抄》卷二：“夜”字一本作“远”，不惟句法不健，且惟乘月黑而夜遁，方见单于久在围中，若远而后遁，则无及矣。止争一字，语意悬远若此。甚类，书贵善本也。', 'center', 1417644147, '57b909e20a2b58005c928589', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10427, '贺新郎 · 同父见和，再用韵答之', NULL, 108, 793, 5, 2, '辛弃疾', NULL, 10003, '57b8ed682e958a005fa4d096', '宋', 'ci', '词', 'http://baike.baidu.com/view/2898323.htm', '', '老大那堪说。似而今、元龙臭味，孟公瓜葛。我病君来高歌饮，惊散楼头飞雪。笑富贵千钧如发。硬语盘空谁来听？记当时、只有西窗月。重进酒，换鸣瑟。
事无两样人心别。问渠侬：神州毕竟，几番离合？汗血盐车无人顾，千里空收骏骨。正目断关河路绝。我最怜君中宵舞，道“男儿到死心如铁”。看试手，补天裂。', '宋孝宗淳熙十五年冬，陈亮自浙江东阳来江西上饶北郊带湖访问作者。作者和陈亮纵谈天下大事，议论抗金復国，极为投契。陈亮在带湖住了十天，又同游鹅湖。後来，陈亮因朱熹失约未来紫溪，匆匆别去。辛稼轩思念陈亮，曾先写《贺新郎》一首寄给陈亮。陈亮很快就和了一首《贺新郎·寄辛幼安和见怀韵》。辛稼轩见到陈亮的和词以後，再次回忆他们相会时的情景而写下了这首词。
此词的突出特点在于，把即事叙景与直抒胸臆巧妙结合起来，用凌雲健笔抒写慷慨激昂，奔放郁勃的感情，悲壮沉雄發扬奋厉的格调。', '贺新郎：词牌名，又名《金缕曲》《贺新凉》。
“同父见和，再用韵答之”：四卷本乙集作“同父见和，再用前韵”。
同父：陈亮（公元1143年—公元1194年），字同父（甫），号龙川，婺州 永康（今属浙江）人，才气超迈，曾三上书孝宗，反对议和。光宗策进士，擢第一，授签书建康府判官，未赴任卒。有《龙川集》行世。《宋史·卷四百三十六·儒林》有传。
老大：年纪大。《乐府诗集·相和歌辞五·长歌行》：“少壮不努力，老大徒伤悲。”唐·白居易《琵琶行》：“门前冷落鞍马稀，老大嫁作商人妇。”
那堪：四卷本作“犹堪”。
元龙臭味：《三国志·卷七·〈魏书·陈登传〉》：“陈登者，字元龙，在广陵有威名。又掎角吕布有功，加伏波将军，年三十九卒。后许汜与刘备并在荆州牧刘表坐，表与备共论天下人，汜曰：‘陈元龙湖海之士，豪气不除。’备谓表曰：‘许君论是非？’表曰：‘欲言非，此君为善士，不宜虚言；欲言是，元龙名重天下。’备问汜：‘君言豪，宁有事邪？’汜曰：‘昔遭乱，过下邳，见元龙。元龙无客主之意，久不相与语，自上大床卧，使客卧下床。’备曰：‘君有国士之名，今天下大乱，帝主失所，望君忧国忘家，有救世之意，而君求田问舍，言无可采，是元龙所讳也，何缘当与君语？如小人：欲卧百尺楼上，卧君于地，何但上下床之间邪？’表大笑。备因言曰：‘若元龙文武胆志，当求之于古耳，造次难得比也。’”按：元龙切陈同父姓。
臭味：《左传·襄公八年》：“今譬于草木，寡君在君，君之臭味也。”注：“言同类。”
孟公瓜葛：《汉书·卷九十二·〈游侠传·陈遵传〉》：“陈遵字孟公，杜陵人也。……居长安中，列侯、近臣、贵戚皆贵重之。牧守当之官，及郡国豪杰至京师者，莫不相因到遵门。遵嗜酒，每大饮，宾客满堂，辄关门，取客车辖投井中。虽有急，终不得去。”按：孟公切陈同父姓。
瓜葛：指交遊。
楼头：楼上。唐·王昌龄《青楼曲·其一》诗：“楼头小妇鸣筝坐，遥见飞尘入建章。”
笑富贵千钧如发：《晋书·卷八十五·诸葛长民传》：“长民犹豫未发，既而叹曰：‘贫贱常思富贵，富贵必履机危。今日欲为丹徒布衣，岂可得也！’”宋·苏轼《宿州次韵刘泾》：“晚觉文章真小技，早知富贵有危机。”唐·韩愈《与孟尚书书》：“其危如一发引千钧。”钧，古代重量单位，合三十斤。
硬语盘空：形容文章的气势雄伟，矫健有力。唐·韩愈《荐士》诗：“横空盘硬语，妥贴力排奡。”
进酒：斟酒劝饮；敬酒。
换鸣瑟：四卷本作“唤鸣瑟”。
鸣瑟：即瑟。《史记·货殖列传》：“女子则鼓鸣瑟，跕屣，游媚贵富，入後宫，徧诸侯。”南朝梁·江淹《丽色赋》：“女乃耀邯郸之躧步，媚北里之鸣瑟。”南朝梁·简文帝《金錞赋》：“应南斗之鸣瑟，杂西汉之金丸。”
渠侬：吴语方言。对他人的称呼，指南宋当权者。渠，他；侬，你。
神州：中原。
离合：分裂和统一。此为偏义複词，谓分裂。
汗血：古代西域骏马名。流汗如血，故称。后多以指骏马。《史记·卷一百二十三·大宛列传》：“得乌孙马好，名曰‘天马’。及得大宛 汗血马，益壮，更名乌孙马曰‘西极’，名大宛马曰‘天马’云。”《汉书·卷六·武帝纪》：“四年春，贰师将军广利斩大宛王首，获汗血马来。作西极天马之歌。”唐·颜师古注引东汉·应劭曰：“大宛旧有天马种，蹋（tà）石汗血，汗从前肩膊（bó）出，如血，号一日千里。”
盐车：典出《战国策·卷十七·〈楚策四·汗明见春申君〉》：“夫骥之齿至矣，服盐车而上太行，蹄申膝折，尾湛胕（fū）溃，漉汁洒地，白汗交流，中阪迁延，负辕不能上。”
汗血盐车：骏马拉运盐的车子。後以之比喻人才埋没受屈。
骏骨：典出《战国策·卷二十九·〈燕策一·燕昭王收破燕後即位〉》：“燕昭王收破燕后即位，卑身厚币，以招贤者，欲将以报雠。故往见郭隗先生曰：‘齐因孤国之乱，而袭破燕。孤极知燕小力少，不足以报。然得贤士与共国，以雪先王之耻，孤之愿也。敢问以国报雠者柰何？’……郭隗先生曰：‘臣闻古之君人，有以千金求千里马者，三年不能得。涓人言于君曰：“请求之。”君遣之。三月得千里马，马已死，买其首五百金，反以报君。君大怒曰：“所求者生马，安事死马而捐五百金？”涓人对曰：“死马且买之五百金，况生马乎？天下必以王为能市马，马今至矣。”于是不能期年，千里之马至者三。今王诚欲致士，先从隗始；隗且见事，况贤于隗者乎？岂远千里哉？’”。後因以“买骏骨”指燕昭王用千金购千里马骨以求贤的故事，喻招揽人才。
目断：纵目远眺。
关河：即边塞、边防，指边疆。
怜：爱重之意。
中宵：半夜。
试手：大显身手。
补天裂：女娲氏补天。《史记补·三皇本纪》：“女娲氏末年，诸侯有共工氏，与祝融战，不胜而怒，乃头触不周山崩，天柱折，地维绝，女娲乃炼五色石以补天，断鳌足以立四极，聚芦灰以止淘水，以济冀州。于是地平天成，不改归物。”', '我本来已老大无成，不该再说什么了，可是，如今碰到了你这个如同陈登、陈遵般有着湖海侠气的臭味相投者，便忍不住“老夫聊發少年狂”了。我正生着病，你来了，我高兴得陪你高歌痛饮，欢喜和友谊驱散了楼头上飞雪的寒意。可笑那些功名富贵，别人将其看得如同千钧般重，我们却把它看得如同毫毛一般轻。可是我们当时所谈论和阐發的那些事关国家兴亡的真知灼见又有谁听见了呢？只有那个照人间沧桑、不关时局安危的西窗明月。我们谈得如此投机，一次又一次地斟着酒，更换着琴瑟音乐。
国家大事依然如故，可是人心却大为消沉，不同于过去了。请问你们，神州大地，究竟还要被金人割裂主宰多久呢？汗血良马拖着笨重的盐车无人顾惜，当政者却要到千里之外用重金收买骏马的骸骨。极目远眺，关塞河防道路阻塞，不能通行。我最尊敬你那闻鸡起舞的壮烈情怀，你曾说过：男子汉大丈夫，抗金北伐的决心至死也会像铁一般坚定。我等待着你大显身手，为恢復中原作出重大的贡献。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74e903572034f65963b6", "shortContent": "把即事叙景与直抒胸臆巧妙结合起来，用凌云健笔抒写慷慨激越、奔放郁勃的感情，格调悲壮沉雄，发扬奋厉，是这首词在艺术上的主要特点。\n文学作品的艺术力量在于以情感人。古今中外的优秀诗作，无不充溢着激情。辛弃疾的这首词也是如此。辛弃疾与陈亮，都是南宋时期著名的爱国词人，怀有恢复中原的大志。但南宋统治者不思北图，因而他们的宏愿久久不得实现。当时，辛弃疾正罢官闲居上饶，陈亮特地赶来与他共商抗战恢复大计。二人同...", "authors": ["薛祥生", "王少华"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ebdbb8b379ee0a0311", "shortContent": "把即事叙景与直抒胸臆巧妙结合起来，用凌云健笔抒写慷慨激越、奔放郁勃的感情，格调悲壮沉雄，发扬奋厉，是这首词在艺术上的主要特点。\n文学作品的艺术力量在于以情感人。古今中外的优秀诗作，无不充溢着激情。辛弃疾的这首词也是如此。辛弃疾与陈亮，都是南宋时期著名的爱国词人，怀有恢复中原的大志。但南宋统治者不思北图，因而他们的宏愿久久不得实现。当时，辛弃疾正落职闲居上饶，陈亮特地赶来与他共商抗战恢复大计。二人同...", "authors": ["薛祥生", "王少华"], "pressName": "上海辞书出版社"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312704773206168b2e021bf", "shortContent": "宋孝宗淳熙十五年（1188）冬，陈亮自浙江东阳来江西上饶北郊带湖访问辛弃疾。词人和陈亮纵谈天下大事，议论抗金复国，极为投契。陈亮在带湖住了十天，又同游鹅湖。后来，陈亮因朱熹失约未来紫溪，故匆匆别去。辛弃疾思念陈亮，曾写《贺新郎·把酒长亭说》一首寄给陈亮。陈亮很快就和了一首《贺新郎·寄辛幼安和见怀韵》。辛弃疾见到陈亮的和词以后，再次回忆他们相会时的情景而写下了这首词。\n\n词的上片写友情。第一句，词人...", "authors": ["陈庆之"], "pressName": "崇文书局"}, {"bookId": "64688f9830675327e19962ff", "bookTitle": "辛弃疾词鉴赏辞典（珍藏本）", "articleId": "64697465902ee364cc708b36", "shortContent": "把即事叙景与直抒胸臆巧妙结合起来，用凌云健笔抒写慷慨激越、奔放郁勃的感情，格调悲壮沉雄，发扬奋厉，是这首词在艺术上的主要特点。\n文学作品的艺术力量在于以情感人。古今中外的优秀诗作，无不充溢着激情。辛弃疾的这首词也是如此。辛弃疾与陈亮，都是南宋时期著名的爱国词人，怀有恢复中原的大志。但南宋统治者不思北图，因而他们的宏愿久久不得实现。当时，辛弃疾正罢官闲居上饶，陈亮特地赶来与他共商抗战恢复大计。二人同...", "authors": ["薛祥生　王少华"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472c8de45e4710056fe9c1a", "shortContent": "把即事叙景与直抒胸臆巧妙结合起来，用凌云健笔抒写慷慨激越、奔放郁勃的感情，格调悲壮沉雄，发扬奋厉，是这首词在艺术上的主要特点。\n\n文学作品的艺术力量在于以情感人。古今中外的优秀诗作，无不充溢着激情。辛弃疾的这首词也是如此。辛弃疾与陈亮（字同父。父，或作甫），都是南宋时期著名的爱国词人，怀有恢复中原的大志。但南宋统治者不思北图，因而他们的宏愿久久不得实现。当时，辛弃疾正落职闲居上饶，陈亮特地赶来与他...", "authors": ["薛祥生", "王少华"], "pressName": "上海辞书出版社"}]', '', 'indent', 1408461955, '57b9688a8ac2470062e33651', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10428, '清明', NULL, 2236, 501, 2, 10, '杜牧', NULL, 10109, '57b9836cc4c971005593dfec', '唐', 'shi', '诗', 'https://baike.baidu.com/item/%E6%B8%85%E6%98%8E/8645623#viewPageContent', '', '清明时节雨纷纷，路上行人欲断魂。
借问酒家何处有？牧童遥指杏花村。', '《清明》传为唐代文学家杜牧的诗作。此诗写清明春雨中所见，色彩清淡，心境凄冷，历来广为传诵。第一句交代情景、环境、气氛；第二句写出了人物，显示了人物的凄迷纷乱的心境；第三句提出了如何摆脱这种心境的办法；第四句写答话带行动，是整篇的精彩所在。全诗运用由低而高、逐步上升、高潮顶点放在最后的手法，余韵邈然，耐人寻味。
此诗首见于南宋初年《锦绣万花谷》注明出唐诗，后依次见于《分门纂类唐宋时贤千家诗选》、明托名南宋谢枋得《千家诗》、清康熙《御选唐诗》。《江南通志》载：杜牧任池州刺史时，曾经过金陵杏花村饮酒，诗中杏花村指此。而在这之前由杜牧嘱外甥亲自整理的《樊川文集》、甚至收录了不少其他唐人诗作的《樊川外集》和《樊川别集》中都没有收入《清明》一诗，因此陈寅恪等研究者认为此诗的真实作者颇为可疑，宋人洪迈《万首唐人绝句序》：“金华所刊杜牧之《续别集》，皆许浑诗也。”刘克庄《后村诗话》：“樊川有《续别集》三卷，十之八九皆（许）浑诗。”因而我国唐诗研究专家韩成武教授结合风格等因素考证认为这首诗作者可能是素有“许浑千首湿”之称的唐代许浑，此说获得了一定支持。但这首诗在许浑的诗集中同样没有收录，因而又有学者缪钺在刊于《文史知识》一九八三年第十二期的《关于杜牧〈清明诗〉的两个问题》中指出：“此诗乃首见于《千家诗》，此前文献并无提及杜牧此诗者。此诗文韵、魂韵通押，通押用韵与唐人用韵不合。此诗非杜牧作，乃宋人词。”从音韵的角度将诗断代为宋人作品，证据比风格更有力，但这桩疑案最终也仍旧没有具体定论，待敲定后更改作者栏。', '清明：二十四节气之一，在阳历四月五日前后。旧俗当天有扫墓、踏青、插柳等活动。宫中以当天为秋千节，坤宁宫及各后宫都安置秋千，嫔妃做秋千之戏。
纷纷：形容多。
欲断魂：形容伤感极深，好像灵魂要与身体分开一样。断魂：神情凄迷，烦闷不乐。这两句是说，清明时候，阴雨连绵，飘飘洒洒下个不停；如此天气，如此节日，路上行人情绪低落，神魂散乱。
借问：请问。
杏花村：杏花深处的村庄，位于安徽池州贵池区秀山门外。受此诗影响，后人多用“杏花村”作酒店名。', '江南清明时节细雨纷纷飘洒，路上羁旅行人个个落魄断魂。
借问当地之人何处买酒浇愁？牧童笑而不答遥指杏花山村。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d95e272d4b22543534", "shortContent": "这一天正是清明佳节。诗人小杜，在行路中间，可巧遇上了雨。清明，虽然是柳绿花红、春光明媚的时节，可也是气候容易发生变化的时期，甚至时有“疾风甚雨”。但这日的细雨纷纷，是那种“天街小雨润如酥”（韩愈《早春呈水部张十八员外》）样的雨。——这也正是春雨的特色。这“雨纷纷”，传达了那种“做冷欺花，将烟困柳”（宋史达祖《绮罗香》）的凄迷而又美丽的境界。\n这“纷纷”在此自然毫无疑问是形容那春雨的意境的；可是它又...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9820695e6503ffe9", "shortContent": "这一天正是清明佳节。诗人小杜，在行路中间，可巧遇上了雨。清明，虽然是柳绿花红、春光明媚的时节，可也是气候容易发生变化的时期，甚至时有“疾风甚雨”。但这日的细雨纷纷，是那种“天街小雨润如酥”（韩愈《早春呈水部张十八员外》）样的雨。——这也正是春雨的特色。这“雨纷纷”，传达了那种“做冷欺花，将烟困柳”（宋史达祖《绮罗香》）的凄迷而又美丽的境界。\n\n这“纷纷”在此自然毫无疑问是形容那春雨的意境的；可是它...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "645d0ac98258810260dbe044", "bookTitle": "杜牧诗文鉴赏辞典", "articleId": "6461f1447da2f75ac7dc6fe9", "shortContent": "这一天正是清明佳节。诗人小杜，在行路中间，可巧遇上了雨。清明，虽然是柳绿花红、春光明媚的时节，可也是气候容易发生变化的时期，甚至时有“疾风甚雨”。但这日的细雨纷纷，是那种“天街小雨润如酥”（韩愈《早春呈水部张十八员外》）样的雨。——这也正是春雨的特色。这“雨纷纷”，传达了那种“做冷欺花，将烟困柳”（宋史达祖《绮罗香》）的凄迷而又美丽的境界。\n\n这“纷纷”在此自然毫无疑问是形容那春雨的意境的；可是它...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471a2887f27182da38a454a", "shortContent": "这首小诗，一个难字也没有，一个典故也不用，整篇是十分通俗的语言，写得自如之极，毫无经营造作之痕。音节十分和谐圆满，景象非常清新、生动，而又境界优美，兴味隐跃。诗由篇法讲也很自然，是顺序的写法。第一句交代情景、环境、气氛，是“起”；第二句是“承”，写出了人物，显示了人物的凄迷纷乱的心境；第三句是一“转”，然而也就提出了如何摆脱这种心境的办法；而这就直接逼出了第四句，成为整篇的精彩所在———“合”。在...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}]', '《千家诗》：此清明遇雨而作也。游人遇雨，巾履沾湿，行倦而兴败矣。神魂散乱，思入酒家暂息而未能也。故见牧童而同酒家，遥望杏花深处而指示之也。', 'center', 1464730397, '57b8c63fa633bd00665c6649', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10429, '山行', NULL, 1765, 501, 2, 13, '杜牧', NULL, 10109, '57b9836cc4c971005593dfec', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/95048/7385968.htm', '', '远上寒山石径斜，白云生处有人家。
停车坐爱枫林晚，霜叶红于二月花。', '《山行》是诗人杜牧的一首描写和赞美深秋山林景色的七言绝句。这首诗描绘的是秋之色，展现出一幅动人的山林秋色图，山路、人家、白云、红叶，构成一幅和谐统一的画面。在这首诗中，杜牧以情驭景，敏捷、准确地捕捉足以体现自然美的形象，并把自己的情感融汇其中，使情感美与自然美水乳交融，情景互为一体。全诗构思新颖，布局精巧，于萧瑟秋风中摄取绚丽秋色，与春光争胜，令人赏心悦目。这首小诗不只是即兴咏景，而且进而咏物言志，是诗人内在精神世界的表露。', '山行：在山中行走。
远上：登上远处的。
寒山：深秋季节的山。
石径：石子的小路。
斜（xié，旧读xiá）：倾斜。
生：另有版本作“深”（“深”可理解为在云雾缭绕的的深处；“生”可理解为在形成白云的地方）。此处学术界一直存在争议，清康熙陈梦雷编辑《古今图书集成》作“白云深处有人家”。明万历赵宦光刊本，宋洪迈编《万首唐人绝句》作"白云深处有人家"。清乾隆《四库全书》收入的两种版本都有，例如明高棅编《唐诗品汇》和《御定全唐诗》作"白云深处有人家"，而宋洪迈编《万首唐人绝句》作“白云生处有人家”。当代有些课本中本诗也从原来的"白云深处有人家“修改为"白云生处有人家”，并于注释处说明“‘生处’一作‘深处’”（考试时应以使用的课本为准）。94年版教育部重编国语辞典作“白云深处有人家”。
坐：因为。
霜叶：枫树的叶子经深秋寒霜之后变成了红色。
枫林晚：傍晚时的枫树林。', '沿着弯弯曲曲的小路上山，在那白云深处，居然还有人家。
停下车来，是因为喜爱这深秋枫林晚景。枫叶秋霜染过，艳比二月春花。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d97d0ac11454953a32", "shortContent": "这首诗描绘的是秋之色，展现出一幅动人的山林秋色图。诗里写了山路、人家、白云、红叶，构成一幅和谐统一的画面。这些景物不是并列地处于同等地位，而是有机地联系在一起，有主有从，有的处于画面的中心，有的则处于陪衬地位。简单来说，前三句是宾，第四句是主，前三句是为第四句描绘背景、创造气氛，起铺垫和烘托作用的。\n“远上寒山石径斜”，写山，写山路。一条弯弯曲曲的小路蜿蜒伸向山头。“远”字写出了山路的绵长，“斜”...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389aecdc25963feee1aba", "shortContent": "这首诗描绘的是秋之色，展现出一幅动人的山林秋色图。诗里写了山路、人家、白云、红叶，构成一幅和谐统一的画面。这些景物不是并列地处于同等地位，而是有机地联系在一起，有主有从，有的处于画面的中心，有的则处于陪衬地位。简单来说，前三句是宾，第四句是主，前三句是为第四句描绘背景、创造气氛，起铺垫和烘托作用的。\n\n“远上寒山石径斜”，写山，写山路。一条弯弯曲曲的小路蜿蜒伸向山头。“远”字写出了山路的绵长，“斜...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270787ccdb86c49f29282", "shortContent": "清人李慈铭《唐诗三百首续选》曾评价杜牧诗曰：“七绝尤有远韵远神，晚唐诸家让渠独步。”对于杜牧某些七绝来说，此论可能有夸誉之嫌，但《山行》这首诗却当之无愧，其质朴的口语、简洁的白描，传达出悠远不尽的诗情画意，历来脍炙人口。\n\n“远上寒山石径斜”，写山，写山路，点明“山行”题旨。“远”字用得极为巧妙，既突出了此行目的地之遥远，也照应脚下的山路之崎岖绵长。“寒山”，暗示诗人山行的季节时令，当在深秋万物萧...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312713e73206168b2e022da", "shortContent": "清人李慈铭《唐诗三百首续选》曾评价杜牧诗曰：“七绝尤有远韵远神，晚唐诸家让渠独步。”对于杜牧某些七绝来说，此论可能有夸誉之嫌，但《山行》这首诗却当之无愧，其质朴的口语、简洁的白描，传达出悠远不尽的诗情画意，历来脍炙人口。\n“远上寒山石径斜”，写山，写山路，点明“山行”题旨。“远”字用得极为巧妙，既突出了此行目的地之遥远，也照应脚下的山路之崎岖绵长。“寒山”，暗示诗人山行的季节时令，当在深秋万物萧条...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645d0ac98258810260dbe044", "bookTitle": "杜牧诗文鉴赏辞典", "articleId": "6461e3fcc0471b0062c10c4c", "shortContent": "这首诗描绘的是秋之色，展现出一幅动人的山林秋色图。诗里写了山路、人家、白云、红叶，构成一幅和谐统一的画面。这些景物不是并列地处于同等地位，而是有机地联系在一起，有主有从，有的处于画面的中心，有的则处于陪衬地位。简单来说，前三句是宾，第四句是主，前三句是为第四句描绘背景、创造气氛，起铺垫和烘托作用的。\n\n“远上寒山石径斜”，写山，写山路。一条弯弯曲曲的小路蜿蜒伸向山头。“远”字写出了山路的绵长，“斜...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471a24a902ee364cc939171", "shortContent": "“远上寒山石径斜”，写山，写山路。一条弯弯曲曲的小路蜿蜒伸向山头。“远”字写出了山路的绵长，“斜”字与“上”字呼应，写出了高而缓的山势。\n“白云生处有人家”，写云，写人家。诗人的目光顺着这条山路一直向上望去，在白云飘浮的地方，有几处山石砌成的石屋石墙。这里的“人家”照应了上句的“石径”。———这一条山间小路，就是那几户人家上上下下的通道吧？这就把两种景物有机地联系在一起了。有白云缭绕，说明山很高。...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}]', '《归田诗话》：予为童子时，十月朝从诸长上拜南山先垄，行石磴间，红叶交坠。先伯元范诵杜牧之“停车坐爱枫林晚，霜叶红于二月花”之句……至今每见红叶与飞落，辄思之。
《唐诗归折衷》：唐云：妙在冷落中寻出佳景。
《唐三体诗评》：“白云”即是炊烟，已起“晚”字；“白”、“红”二字，又相映发。“有人家”三字下反接“停车”，“爱”字方有力。
《碛砂唐诗》：敏曰：味此诗，似与“老马反为驹，不顾其后”之语同义。
《唐诗摘抄》：次句承上“远”字说，此未上时所见。三四则既上之景。诗中有画，此秋山行旅图也。
《唐诗笺注》：“霜叶红于二月花”，真名句。诗写山行，景色幽邃，而致也豪荡。
《历代诗法》：结句写得秋光绚烂。
《诗境浅说续编》：诗人之咏及红叶者多矣，如“林间暖酒烧红叶”、“红树青山好放船”等句，尤脍炙词坛，播诸图画。唯杜牧诗专赏其色之艳。谓胜于春花。当风劲霜严之际，独绚秋光，红黄绀紫，诸色咸备，笼山络野，春花无此大观，宜司勋特赏于艳李秾桃外也。
《唐人绝句精华》：读此可见诗人高怀逸致。霜叶胜花，常人所不易道出者。一经诗人道出，便留诵千口矣。', 'center', 1464730340, '57b940b17db2a2005428c7a3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10430, '夜雪', NULL, 522, 2952, 1, 3, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/718584/13862380.htm', '', '已讶衾枕冷，复见窗户明。
夜深知雪重，时闻折竹声。', '《夜雪》是唐代诗人白居易创作的一首五言绝句。这是一首咏雪诗，诗人描写的是“夜雪”，全用侧面烘托手法。诗人怀着真情实感抒写自己独特的感受，在众多的咏雪诗中，此诗新颖别致，清新淡雅，别具韵味。首句从感觉写起，通过冷不仅点明有雪，而且暗示雪大。次句从视觉的角度进一步写夜雪，夜深却见窗明，正说明雪下得大、积雪深，是积雪的反光给暗夜带来了亮光。三四句是从听觉的角度着笔，深夜传来了积雪压折竹枝的声音，可知雪势的有增无减。“折竹声”于深夜时闻，衬托了冬夜的寂静，也暗示出诗人一夜无眠。这不只是因为“衾枕冷”，也透露出诗人谪居江州的孤寂心情。', '讶：惊讶。衾（qīn）枕：被子和枕头。
重：大的意思，指雪下的很大。
折竹声：指大雪压折竹子的声响。', '实在惊讶今夜的寒冷，被子枕头竟然冰凉，又见窗外一片通明。夜深了，知道这是外边下了大雪，雪越下越大，不时听到厚厚积雪压断树枝的声音。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c70ce818559d05880a", "shortContent": "在大自然众多的产儿中，雪可谓得天独厚。她以洁白晶莹的天赋丽质，装点关山的神奇本领，赢得古往今来无数诗人的赞美。在令人目不暇接的咏雪篇章中，白居易这首《夜雪》，显得那么平凡，既没有色彩的刻画，也不作姿态的描摹，初看简直毫不起眼；但细细品味，便会发现它凝重古朴，清新淡雅，是一朵别具风采的小花。\n这首诗新颖别致，首要在立意不俗。咏雪诗写夜雪的不多，这与雪本身的特点有关。雪无声无嗅，只能从颜色、形状、姿态...", "authors": ["张明非"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270717f0b9738b369b221", "shortContent": "雪，是大自然美丽的精灵，它以天赋丽质装扮山川，飘洒寰宇，也是诗人们情有独钟的诗思寄托物。古人咏雪，有“残雪压枝犹有橘，冻雷惊笋欲抽芽”，有“五月天山雪，无花只有寒”，有“野云万里无城郭，雨雪纷纷连大漠”等等。在如此众多的咏雪诗词中，白居易的这首《夜雪》，并非光彩夺目，也没有波澜起伏，更没有能让人刻骨铭心，但是这一朵小花，却也开出了别有一番的韵味，耐人寻味，让人一感其清新淡雅、无尽韵味。\n\n“已讶衾...", "authors": ["肖莉莉"], "pressName": "崇文书局"}, {"bookId": "645d09bbec56251f2eeb5b78", "bookTitle": "白居易诗文鉴赏辞典", "articleId": "646242ab30675327e17f2b1f", "shortContent": "在大自然众多的产儿中，雪可谓得天独厚。她以洁白晶莹的天赋丽质，装点关山的神奇本领，赢得古往今来无数诗人的赞美。在令人目不暇接的咏雪篇章中，白居易这首《夜雪》，显得那么平凡，既没有色彩的刻画，也不作姿态的描摹，初看简直毫不起眼；但细细品味，便会发现它凝重古朴，清新淡雅，是一朵别具风采的小花。\n\n这首诗新颖别致，首要在立意不俗。咏雪诗写夜雪的不多，这与雪本身的特点有关。雪无声无嗅，只能从颜色、形状、姿...", "authors": ["张明非"], "pressName": "上海辞书出版社"}]', NULL, 'center', 1445197441, '57b927f0128fe10054cad744', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10431, '众星罗列', NULL, 480, 312, 2, 1, '寒山', NULL, 10110, '57ba460ba633bd005d32204f', '唐', 'shi', '诗', 'http://baike.baidu.com/view/11712793.htm', '', '众星罗列夜明深，岩点孤灯月未沉。
圆满光华不磨镜，挂在青天是我心。', '寒山之诗为点化愚蒙，导引初机，往往写得直白如话，妇妪可解。此七言绝句，又别是一格。这首诗意趣十分含蓄，境界亦幽远深沉，以景寄情，情景交融。短短四句二十八字，犹如一幅写意山水，令人深思，回味无穷。特别是次句“岩点孤灯”形容得很妙，此灯即为心灯，心灯孤明，点明了与尘世的隔绝。正因此，一代高僧那孤独而崇高的形象就矗立在读者面前了。', '罗列：排列。古辞《鸡鸣高树巅》：“鸳鸯七十二，罗列自成行。”
孤灯：指月亮。
光华：光彩明丽。《卿云歌》：“日月光华，旦复旦兮。”莹：光亮透明状。', '众多星星像棋子排列，使夜空显得非常幽深。尚未西沉的月亮像一盏孤灯在山崖上点亮。光彩明丽、圆满如镜的月亮不用打磨也晶莹剔透。那挂在青天上的，就是我的一颗心哪。', NULL, NULL, 'center', 1413110057, '57ae050a7db2a200541375c4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10432, '杳杳寒山道', NULL, 487, 312, 2, 1, '寒山', NULL, 10110, '57ba460ba633bd005d32204f', '唐', 'shi', '诗', 'http://baike.baidu.com/view/647739.htm', '', '杳杳寒山道，落落冷涧滨。
啾啾常有鸟，寂寂更无人。
淅淅风吹面，纷纷雪积身。
朝朝不见日，岁岁不知春。', '《杳杳寒山道》是唐代诗僧寒山的作品。此诗主要写作者居住天台山寒岩时亲眼所见山路及其周围的景致。首二句描述这条山道的形势和位置；三、四两句从声音上描摹寒山道的静寂宁远；五、六两句从静态描写转向动态描画，着意表现诗人顶风冒雪的自我形象；最后两句以抒写诗人的情怀作结，情中见景。全诗运用景物渲染气氛、以气氛烘托心情的表现手法，同时大量使用叠字，使诗篇富于一种特殊的音乐美。', '杳杳：幽暗状。
寒山：始丰县（今浙江天台县西）天台山有寒暗二岩，寒山即寒岩，乃诗人所居。
落落：寂静冷落的样子。
淅淅：象声词，形容风声。一作「碛碛」。', '寒山道上一片寂静幽暗，冷寂的涧边一片幽僻寥落。
这里常常有鸟儿啾啾地啼鸣，却空虚冷清罕见人烟。
风淅淅沥沥颳向我面门，雪纷纷扬扬洒落在我身上。
我身处其中天天见不到阳光，年年也不知道有春天。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e928b0f8fda5565055397", "shortContent": "寒山是贞观时代的诗僧。长期住在天台山寒岩，诗就写刻在山石竹木之上，盈六百首，现存三百余首。其诗语言明浅如话，有鲜明的乐府民歌风。内容除用形象演说佛理之外，多描述世态人情，山水景物。诗风幽冷，别具境界。这首《杳杳寒山道》，很能代表他的风格。\n诗的内容，写寒岩左近高山深壑中的景色，最后见出心情，通篇浸透了寒意。首联写山水。“杳杳”言山路深暗幽远，“落落”言涧边寂寥冷落。诗一开始就把读者带进一个冷森森的...", "authors": ["赖汉屏"], "pressName": "上海辞书出版社"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63126fe1f2af4e09d55b66d0", "shortContent": "诗僧是唐代诗人中的特殊群体，其存在有非常重要的文化意义。主要有二，一是说明唐代诗人群体分布之广泛，二是从世外人的视角看人生，别有情趣。寒山就是这个诗人群体的重要成员。\n\n乍一看此诗，我们也许并不知道作者究竟想表达什么。但从鸟、风、雪、春这些字眼，可以断定为写景诗。“落落”“寂寂”“冷”等字眼无不透着一股冷风，使通篇浸透了寒意。诗中主要写作者居住天台山寒岩时所见山路及其周围的景致。首联“杳杳寒山道，...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312702e9761253910e904bd", "shortContent": "诗僧是唐代诗人中的特殊群体，其存在有非常重要的文化意义。主要有二，一是说明唐代诗人群体分布之广泛，二是从世外人的视角看人生，别有情趣。寒山就是这个诗人群体的重要成员。\n\n乍一看此诗，我们也许并不知道作者究竟想表达什么。但从鸟、风、雪、春这些字眼，可以断定为写景诗。“落落”、“寂寂”、“冷”等字眼无不透着一股冷风，使通篇浸透了寒意。诗中主要写作者居住天台山寒岩时所见山路及其周围的景致。首联“杳杳寒山...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '', 'center', 1413110278, '57b8e62c8ac2470062df006c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10445, '次北固山下', NULL, 1306, 12, 2, 17, '王湾', NULL, 10116, '57bba5d00a2b58006cbd1660', '唐', 'shi', '诗', 'http://baike.baidu.com/view/287037.htm', '', '客路青山外，行舟绿水前。
潮平两岸阔，风正一帆悬。
海日生残夜，江春入旧年。
乡书何处达？归雁洛阳边。', '此诗以准确精练的语言描写了冬末春初时作者在北固山下停泊时所见到青山绿水、潮平岸阔等壮丽之景，抒发了作者深深的思乡之情。全诗用笔自然，写景鲜明，情感真切，情景交融，风格壮美，极富韵致，历来广为传诵。
这首写冬末春初，旅行江中，即景生情，而起乡愁。开头以对偶句发端，写神驰故里的飘泊羁旅之情怀。次联写「潮平」、「风正」的江上行船，情景恢弘阔大。三联写拂晓行船的情景，对仗隐含哲理，「形容景物，妙绝千古」，给人积极向上的艺术魅力。尾联见雁思亲，与首联呼应。全诗笼罩着一层淡淡的乡思愁绪。「海日生残夜，江春入旧年」，不失诗苑奇葩，艳丽千秋。', '次：旅途中暂时停宿，这里是停泊的意思。
北固山：在今江苏镇江北，三面临水，倚长江而立。
客路：行客前进的路。
青山：指北固山。
潮平两岸阔：潮水涨满时，两岸之间水面宽阔。
风正一帆悬：顺风行船，风帆垂直悬挂。风正，风顺；悬，挂。
海日：海上的旭日。
生：升起。
残夜：夜将尽之时。
入：到。
乡书：家信。
归雁：北归的大雁。大雁每年秋天飞往南方，春天飞往北方。古代有用大雁传递书信的传说。', '客行在碧色苍翠的青山前，泛舟于微波荡漾绿水间。
潮水涨满，两岸之间水面宽阔，顺风行船恰好把帆儿高悬
夜幕还没有褪尽，旭日已在江上冉冉升起，还在旧年时分，江南已有了春天的气息。
身在旅途，家信何传？还是托付北归的大雁，让它捎到远方的洛阳。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a35e272d4b225431d7", "shortContent": "这首题为《次北固山下》的五律，最早见于唐人芮挺章编选的《国秀集》。唐人殷璠选入《河岳英灵集》时题为《江南意》，但有不少异文：“南国多新意，东行伺早天。潮平两岸失，风正数帆悬。海日生残夜，江春入旧年。从来观气象，惟向此中偏。”本文系据长期传诵的《次北固山下》。\n王湾是洛阳人，一生中，“尝往来吴楚间”。“北固山”，在今江苏镇江市以北，三面临江。上引《江南意》中首二句为“南国多新意，东行伺早天”。其“东...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d10e", "shortContent": "这首题为《次北固山下》的五律，最早见于唐人芮挺章编选的《国秀集》。唐人殷璠选入《河岳英灵集》时题为《江南意》，但有不少异文：“南国多新意，东行伺早天。潮平两岸失，风正数帆悬。海日生残夜，江春入旧年。从来观气象，惟向此中偏。”本文系据长期传诵的《次北固山下》。\n\n王湾是洛阳人，一生中，“尝往来吴楚间”。“北固山”，在今江苏镇江市以北，三面临江。上引《江南意》中首二句为“南国多新意，东行伺早天”。其“...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151c4", "shortContent": "这首五律《次北固山下》在当时及后世受到普遍重视，明代胡应麟甚至认为诗中的“海日生残夜，江春入旧年”二句，是区别盛唐与初唐、中唐诗界限的标志（《诗薮》）。据资料记载，此诗最早见于唐代芮挺章编选的《国秀集》。唐人殷璠选入《河岳英灵集》时题为《江南意》，但有不少异文：“南国多新意，东行伺早天。潮平两岸失，风正数帆悬。海日生残夜，江春入旧年。从来观气象，惟向此中偏。”\n\n王湾，洛阳人，玄宗先天元年（712...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127053e6f69b71e93f6279", "shortContent": "这首五律《次北固山下》在当时及后世受到普遍重视，明代胡应麟甚至认为诗中的“海日生残夜，江春入旧年”二句，是区别盛唐与初唐、中唐诗界限的标志（《诗薮》）。据资料记载，此诗最早见于唐代芮挺章编选的《国秀集》。唐人殷璠选入《河岳英灵集》时题为《江南意》，但有不少异文：“南国多新意，东行伺早天。潮平两岸失，风正数帆悬。海日生残夜，江春入旧年。从来观气象，惟向此中偏。”\n\n王湾，洛阳人，景云三年（712）进...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270a5e6f69b71e93f6331", "shortContent": "这首五律《次北固山下》在当时及后世受到普遍重视，明代胡应麟甚至认为诗中的“海日生残夜，江春入旧年”二句，是区别盛唐与初唐、中唐诗界限的标志（《诗薮》）。据资料记载，此诗最早见于唐代芮挺章编选的《国秀集》。唐人殷墦选入《河岳英灵集》时题为《江南意》，但有不少异文：“南国多新意，东行伺早天。潮平两岸失，风正数帆悬。海日生残夜，江春入旧年。从来观气象，惟向此中偏。”\n\n王湾，洛阳人，景云三年进士及第，次...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f47482772d459427e4ec", "shortContent": "读到第三联，就知道作者是于岁暮腊残，连夜行舟的。潮平而无浪，风顺而不猛，近看可见江水碧绿，远望可见两岸空阔。这显然是一个晴明的、处处透露着春天气息的夜晚，孤舟扬帆，缓行江上，不觉已到残夜。这第三联，就是表现江上行舟，即将天亮时的情景。\n这一联历来脍炙人口，唐人殷璠说：“‘海日生残夜，江春入旧年’，诗人已来少有此句。张燕公（张说）手题政事堂，每示能文，令为楷式。”（《河岳英灵集》）明代胡应麟在《诗薮...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645fc22c5e6bb82b8caff682", "bookTitle": "历代咏春诗鉴赏：春江花月夜", "articleId": "6472f67ee49f46528ae10c96", "shortContent": "王湾是洛阳人，一生中，“尝往来吴楚间”。“北固山”，在今江苏镇江市以北，三面临江。此诗别题《江南意》，且有异文，其首二句为“南国多新意，东行伺早天”。其“东行”，当是经镇江到江南一带去。诗人一路行来，当舟次北固山下的时候，潮平岸阔，残夜归雁，触发了心中的情思，吟成了这一千古名篇。\n\n诗以对偶句发端，既工丽，又跳脱。“客路”，指作者要去的路。“青山”点题中“北固山”。作者乘舟，正朝着展现在眼前的“绿...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '《河岳英灵集》：海日生残夜，江春入旧年，诗人已来少有此句。张燕公（张说）手题政事堂，每示能文，令为楷式。
《唐诗直解》：皇甫子循曰：王湾《北固》之作，燕公揭以表署，才闻两语，已叹服于群众；不见只今汾水上，惟有年年秋雁飞，曾不终篇，遽增悲于时主，美岂在多哉！中联真奇秀而不朽。
《诗薮·内编》：清晖能娱人，游子澹忘归，凡登览皆可用。微云淡河汉，疏雨滴梧桐，凡燕集皆可书。海日生残夜，江春入旧年，北固之名奚与？天阙象纬逼，云卧衣裳冷，奉先之殳奚存？而皆妙绝干古，则诗之所尚可知。今题金山而必曰金玉之金，咏赤城而必云赤白之赤，皆逐末忘本之过也。
《唐诗训解》：三四工而易拟，五六太淡而难求。
《唐诗选脉会通评林》：徐充曰：此篇写景寓怀，风韵洒落，佳作也。生字、入字淡而化，非浅浅可到。
《唐诗镜》：潮平二语，俚气殊甚。海日生残夜，略有景色，江春入旧年，此溷语耳。
《唐风定》：高奇与日月常新，非摹仿可得。
《初白庵诗评》：大历以后无此等气格矣。
《唐贤三昧集笺注》：力量酣足。
《唐诗别裁》：江中日早，客冬立春，本寻常意，一经锤炼，便成奇绝。与少陵无风云出塞，不夜月临关一种笔墨。
《唐诗从绳》：五六以残夜反拖早字，以旧年反拖新字，名正言反挑法，亦奇秀不可言。何处达，首无处达也。洛阳正在邛雁边，乡书即从何处达？保见思乡之情，顺看即不然。此唐人句调，粗心人未易识也。
《唐诗笺注》：潮平一联写得宏阔，非复寻常笔墨。
《网师园唐诗笺》：潮平两岸失，失字炼。
《闻鹤轩初盛唐近体读本》：陈德公先生曰：……盖是侵晓行舟，复值岁前春旦，字字工刻，作语故极婉琢，足以脍灸一时。评：五六残夜、旧年，字法作意不必言，著海、江二字更为增致。', 'center', 1413457667, '57b95de92e958a005fa8919e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10434, '苏幕遮', NULL, 797, 239, 4, 9, '周邦彦', NULL, 10111, '57ba6fafa34131005b0e18bd', '宋', 'ci', '词', 'http://baike.baidu.com/view/2525944.htm', '', '燎沉香，消溽暑。鸟雀呼晴，侵晓窥檐语。叶上初阳干宿雨，水面清圆，一一风荷举。
故乡遥，何日去？家住吴门，久作长安旅。五月渔郎相忆否？小楫轻舟，梦入芙蓉浦。', '此词是宋代词人周邦彦创作的，主要表达作者的思乡之情。此词由眼前的荷花想到故乡的荷花，游子浓浓的思乡情，向荷花娓娓道来，构思尤为巧妙别致。上阕主要描绘荷花姿态，下阕由荷花梦回故乡。全词写景写人写情写梦皆语出天然，不加雕饰而风情万种，通过对清圆的荷叶、五月的江南、渔郎的轻舟这些情景进行虚实变幻的描写，思乡之苦表达得淋漓尽致。', '燎（liáo）：细焚。
沉香：现写作「沉香」，一种名贵香料，置水中则下沉，故又名沉水香，其香味可辟恶气。
溽（rù）暑：夏天闷热潮湿的暑气。沈约《休沐寄怀》诗：「临池清溽暑，开幌望高秋。」溽，湿润潮湿。
呼晴：唤晴。旧有鸟鸣可占晴雨之说。
侵晓：拂晓。侵，渐近。
宿雨：隔夜的雨。
清圆：清润圆正。
一一风荷举：意味荷叶迎着晨风，每一片荷叶都挺出水面。举，擎起。司空图《王官二首》诗：「风荷似醉和花舞，沙鸟无情伴客闲。」
吴门：古吴县城亦称吴门，即今之江苏苏州，此处以吴门泛指吴越一带。作者是钱塘人，钱塘古属吴郡，故称之。
久作长安旅：长年旅居在京城。长安，借指北宋的都城汴京（今河南开封）；旅，客居。
楫（jí）：划船用具，短桨。', '细焚沉香，来消除夏天闷热潮湿的暑气。鸟雀鸣叫呼唤着晴天，拂晓时分鸟儿东张西望的在屋檐下的「言语」。荷叶上初出的阳光晒干了昨夜的雨，水面上的荷花清润圆正，荷叶迎着晨风，每一片荷叶都挺出水面。
看到这风景，我想到遥远的故乡，何日才能回去啊？我家本在吴越一带，长久地客居长安。五月，我故乡的小时候的伙伴是否在想我，划着一叶扁舟，在我的梦中来到了过去的杭州西湖荷花塘。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74c503572034f65962fc", "shortContent": "宋代文人写词，就语言艺术方面说，有雕刻与自然两种不同的路径。曾经被词论家捧为“词中老杜”、“两宋之间，一人而已”的周邦彦，就是以雕刻取胜的。他的词集一名《片玉集》，可是集中大部分作品，并不能做到“咳唾落九天，随风生珠玉”那样地天然美好，而是用镂金刻玉的手段以掩盖它真美的不足。但像这首《苏幕遮》，倒是“清水出芙蓉，天然去雕饰”的，在周词中，可算是少数的例外。\n这词以写雨后风荷为中心，由此而引入故乡归...", "authors": ["钱仲联"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5cb5e272d4b2254dfd0", "shortContent": "宋代文人写词，就语言艺术方面说，有雕刻与自然两种不同的路径。曾经被词论家捧为“词中老杜”、“两宋之间，一人而已”的周邦彦，就是以雕刻取胜的。他的词集一名《片玉集》，可是集中大部分作品，并不能做到“咳唾落九天，随风生珠玉”那样地天然美好，而是用镂金刻玉的手段以掩盖它真美的不足。但像这首《苏幕遮》，倒是“清水出芙蓉，天然去雕饰”的，在周词中，可算是少数的例外。\n这词以写雨后风荷为中心，由此而引入故乡归...", "authors": ["钱仲联"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059254f534825dee9fd706", "shortContent": "宋代文人写词，就语言艺术方面说，有雕刻与自然两种不同的路径。曾经被词论家捧为“词中老杜”“两宋之间，一人而已”的周邦彦，就是以雕刻取胜的。他的词集一名《片玉集》，可是集中大部分作品，并不能做到“咳唾落九天，随风生珠玉”那样地天然美好，而是用镂金刻玉的手段以掩盖它真美的不足。但像这首《苏幕遮》，倒是“清水出芙蓉，天然去雕饰”的，在周词中，可算是少数的例外。\n\n这词以写雨后风荷为中心，由此而引入故乡归...", "authors": ["钱仲联"], "pressName": "上海辞书出版社"}, {"bookId": "645d152a7af6de1647101bdf", "bookTitle": "周邦彦词鉴赏辞典", "articleId": "6469bf8d5fc8182fe9b2e792", "shortContent": "宋代文人写词，就语言艺术方面说，有雕刻与自然两种不同的路径。曾经被词论家捧为“词中老杜”、“两宋之间，一人而已”的周邦彦，就是以雕刻取胜的。他的词集一名《片玉集》，可是集中大部分作品，并不能做到“咳唾落九天，随风生珠玉”那样地天然美好，而是用镂金刻玉的手段以掩盖它真美的不足。但像这首《苏幕遮》，倒是“清水出芙蓉，天然去雕饰”的，在周词中，可算是少数的例外。\n这词以写雨后风荷为中心，由此而引入故乡归...", "authors": ["钱仲联"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f34ee5e6bb82b8cf0c45a", "shortContent": "宋代文人写词，就语言艺术方面说，有雕刻与自然两种不同的路径。曾经被词论家捧为“词中老杜”“两宋之间，一人而已”的周邦彦，就是以雕刻取胜的。他的词集一名《片玉集》，可是集中大部分作品，并不能做到“咳唾落九天，随风生珠玉”那样地天然美好，而是用镂金刻玉的手段以掩盖它真美的不足。但像这首《苏幕遮》，倒是“清水出芙蓉，天然去雕饰”的，在周词中，可算是少数的例外。\n这词以写雨后风荷为中心，由此而引入故乡归梦...", "authors": ["钱仲联"], "pressName": "上海辞书出版社"}]', '周济《宋四家词选》：上阕，若有意，若无意，使人神眩。
陈廷焯《云韶集》：不必以词胜，而词自胜。风致绝佳，亦见先生胸襟恬淡。
王国维《人间词话》：「叶上初阳乾宿雨，水面清圆，一一风荷举」，此真能得荷之神理者，觉白石《念奴娇》。《惜红衣》二词，犹有隔雾看花之恨。', 'indent', 1413111192, '57b25cd87db2a20054335a9d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10435, '夜上受降城闻笛', NULL, 460, 166, 2, 9, '李益', NULL, 10112, '57b9bd658ac2470063ff0efa', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383801.htm', '', '回乐峰前沙似雪，受降城外月如霜。
不知何处吹芦管，一夜征人尽望乡。', '此诗是唐代诗人李益创作的一首七言绝句。这首诗最大的特点是蕴藉含蓄，将所要抒发的感情蕴涵在对景物和情态的描写之中。诗的开头两句，写登城时所见的月下景色。如霜的月光和月下雪一般的沙漠，正是触发征人乡思的典型环境。环境的描写之中现出人物的感受。在这万籁俱寂的静夜里，夜风送来了凄凉幽怨的芦笛声，更加唤起了征人望乡之情。「一夜征人尽望乡」，不说思乡，不说盼归，而是以人物的情态行为展现其心理，写出了人物不尽的乡愁。', '受降城：唐初名将张仁愿为了防御突厥，在黄河以北筑受降城，分东、中、西三城，都在今内蒙古自治区境内。另有一种说法是：贞观二十年（公元646年），唐太宗亲临灵州接受突厥一部的投降，「受降城」之名即由此而来。
回乐峰：一作「回乐烽」。唐代有回乐县，灵州治所，在今宁夏回族自治区灵武县西南。回乐峰即当地山峰。回乐烽指回乐县附近的烽火台。
城外：一作「城上」，一作「城下」。
芦管：笛子。一作「芦笛」。
征人：戍边的将士。
尽：全。', '回乐峰前的沙地白得像雪，受降城外的月色犹如秋霜。
不知何处吹起凄凉的芦管，一夜间征人个个眺望故乡。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92bc03048e64fbd91454", "shortContent": "这是一首抒写戍边将士乡情的诗作。诗题中的受降城，是灵州治所回乐县（古县名，西夏时废，治今宁夏灵武市西南）的别称。在唐代，这里是防御突厥、吐蕃的前线。\n诗的开头两句，写登城时所见的月下景色。远望回乐城东面数十里的丘陵上，耸立着一排烽火台。丘陵下是一片沙地，在月光的映照下，沙子像积雪一样洁白而带有寒意。近看，但见高城之外，天上地下满是皎洁、凄冷的月色，有如秋霜那样令人望而生寒。这如霜的月光和月下雪一般...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a96", "shortContent": "这是一首抒写戍边将士乡情的诗作。诗题中的受降城，是灵州治所回乐县（古县名，西夏时废，治今宁夏灵武市西南）的别称。在唐代，这里是防御突厥、吐蕃的前线。\n\n诗的开头两句，写登城时所见的月下景色。远望回乐城东面数十里的丘陵上，耸立着一排烽火台。丘陵下是一片沙地，在月光的映照下，沙子像积雪一样洁白而带有寒意。近看，但见高城之外，天上地下满是皎洁、凄冷的月色，有如秋霜那样令人望而生寒。这如霜的月光和月下雪一...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290ee", "shortContent": "唐武后时，朔方总管张仁愿为抵御突厥的入侵修建了东、西、中三座受降城，此指西受降城。诗中的前两句是对句，描写边塞荒寒夜景。“烽”即烽火台。有的版本作“峰”，实误。“回乐烽前”就在“受降城外”，两句是平起，都是点明题目中的“受降城”和“夜”。在一个深秋的夜晚，诗人乘着月色，登绝塞之孤城，举目四望，只见辽阔的沙漠和耸立的烽火台，笼罩在寒冷的月光中。沙漠如雪一般银白，城外地上也好像铺满了白霜，景色荒寒，令...", "authors": ["陈鹏"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706a73206168b2e0220a", "shortContent": "唐武后时，朔方总管张仁愿为抵御突厥的入侵修建了东、西、中二座受降城，此指西受降城。诗中的前两句是对句，描与边塞荒寒夜景。“烽”即烽火台。有的版本作“峰”，实误。“回乐烽前”就在“受降城外”，两句是平起，都是点明题目中的“受降城”和“夜”。在一个深秋的夜晚，诗人乘着月色，登绝塞之孤城，举目四望，只见辽阔的沙漠和耸立的烽火台，笼罩在寒冷的月光中。沙漠如雪一般银白，城外地上也好像铺满了白霜，景色荒寒，令...", "authors": ["陈鹏"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270f7f2af4e09d55b682b", "shortContent": "唐武后时，朔方总管张仁愿为抵御突厥的入侵修建了东、西、中三座受降城，此指西受降城。诗中的前两句是对句，描写边塞荒寒夜景。“烽”即烽火台。有的版本作“峰”。“回乐烽前”就在“受降城外”，两句是平起，都是点明题目中的“受降城”和“夜”。在一个深秋的夜晚，诗人乘着月色，登绝塞之孤城，举目四望，只见辽阔的沙漠和耸立的烽火台，笼罩在寒冷的月光中。沙漠如雪一般银白，城外地上也好像铺满了白霜，景色荒寒，令人感到...", "authors": ["陈鹏"], "pressName": "崇文书局"}]', '', 'center', 1413111534, '57b91effa633bd00665e4f15', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10436, '寻南溪常山道人隐居', NULL, 352, 492, 3, 3, '刘长卿', NULL, 10113, '57b9a043165abd00661cbf89', '唐', 'shi', '诗', 'http://baike.baidu.com/view/929836.htm', '', '一路经行处，莓苔见履痕。
白云依静渚，春草闭闲门。
过雨看松色，随山到水源。
溪花与禅意，相对亦忘言。', '唐代宗大历前后，是个感伤时代，很多诗歌都着意表现感伤色彩，但更多的是摆脱时代失意、政治苦闷、人世困惑，而追求宁静、冲远、淡泊的心理。刘长卿此诗也反映了当时的“时代心声”。
诗人兴冲冲步行山中拜访一位道士，不想却吃了个闭门羹，在居所远近寻找，仍未如愿，诗人非但没有产生失望惆怅，反而获得精神惬意和心理的满足。此诗就是在这样的情境下所作的。
尾联的“禅意”，用得精妙。诗人看见了“溪花”，却浮起“禅意”，从幽溪深涧的陶冶中得到超悟，从摇曳的野花静静的观照中，领略到恬静的清趣，溶化于心灵深处是一种体察宁静，荡涤心胸的内省喜悦，自在恬然的心境与清幽静谧的物象交融为一。况且禅宗本来就有拈花微笑的故事，这都溶入默契不言的妙悟中，而领会出“禅意”，因用“与”，把物象和情感联结起来。禅宗的妙悟和道家的得意忘言，有内在相通之处。佛道都喜占山林，幽径寻真，荡入冥思，于此佛道互融，而进入“相对亦忘言”的精神境界。', '莓苔：一作“苍苔”，即青苔。
履痕：一作“屐痕”，木屐的印迹，此处指足迹。
渚：水中的小洲。一作“者”。
春草：一作“芳草”。
“溪花与禅意，相对亦忘言。”句：因悟禅意，故也相对忘言。禅，佛教指清寂凝定的心境。', '一路上经过的地方，青苔小道留下鞋痕。
白云依偎安静沙洲，春草环绕道院闲门。
新雨过后松色青翠，循着山路来到水源。
看到溪花心神澄静，凝神相对默默无言。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f09324", "shortContent": "这首诗题为“寻南溪常山道人隐居”，诗人紧扣一个“寻”字来写。寻的结果，自然是不遇。这类诗的写法大体如此，因为只有如此才能突出道士的超迈出尘，譬如云中之龙，神乎其神。既然无法一睹仙容，只好描写途中所见。诗人以生花妙笔，写幽静之景，而归之于禅意，藉此既可见出诗人慧根不浅，又足暗示道士造诣精深。\n\n首联描写缘山而行，路上铺满青苔，其间屐齿隐约可见。“莓苔”暗示山中幽静，绝少行人，诗词中多用以渲染幽寂氛围...", "authors": ["李曙光"], "pressName": "崇文书局"}]', '《批点唐诗正声》：“芳草闭闲门”，绝好绝好。结句空色俱了。
《唐诗镜》：幽色满抱。
《唐诗选脉会通评林》：周敬曰：起二句便幽，中联自然，结闲静，有渊明丰骨。
《碛砂唐诗选》：敏曰：全首稳称，无一懈笔，清新俊逸，兼有其长，诗家正法眼也。
《唐诗成法》：题是“寻常道士”诗、只“见履痕”三字完题。余但写南溪自己一路得意忘言之妙，其见道士否不论，与王子猷何必见安道问意。
《唐诗三百首》：语语是“寻”。', 'center', 1413127634, '57b8ff90128fe10054c980bd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10437, '十一月四日风雨大作（其二）', NULL, 679, 9405, 1, 13, '陆游', NULL, 10019, '57b904a9d342d3005ac748fb', '宋', 'shi', '诗', 'http://baike.baidu.com/view/408321.htm', '', '僵卧孤村不自哀，尚思为国戍轮台。
夜阑卧听风吹雨，铁马冰河入梦来。', '此诗是绍熙三年（公元1192年）十一月陆游退居家乡山阴时所作，表明陆游投身抗战、为国雪耻的壮志至老不衰。但是，诗人满怀壮志，却不为朝廷所重，只能「僵卧孤村」，把为国家恢复中原的理想寄托到梦境之中。
此诗以「痴情化梦」的手法，深沉地表达了作者收复国土、报效祖国的壮志和那种「年既老而不衰」的矢志不渝精神，向读者展示了诗人的一片赤胆忠心。
诗的开头两句，意思紧密相联：「僵卧孤村不自哀」叙述了作者的现实处境和精神状态，「尚思为国戍轮台」是对「不自哀」这种精神状态的解释，前后照应，形成对比。「僵、卧、孤、村」四字写出了作者此时凄凉的境遇。「僵」字写年迈，写肌骨衰老，「卧」字写多病，写常在床蓐；「孤」字写生活孤苦，不仅居处偏僻，而且思想苦闷，没有知音；「村」写诗人贫困村居，过着荒村野老的凄苦生活。四字写出了作者罢官回乡后处境寂寞、窘迫、冷落的生活现状，笼罩着一种悲哀的气氛。但接下去「不自哀」三字情绪急转，又现出一种乐观豪放之气。诗人对自己的处境并不感到悲哀，贫病凄凉对他来说没有什么值得悲哀之处；诗人自己尚且「不自哀」，当然也不需要别人的同情。但他需要理解，理解他终生不渝的统一之志，理解他为这个壮志奋斗的一生，理解他的满腔热血、一颗忠心，就是「尚思为国戍轮台」的精神状态。这两句诗是诗人灵魂和人格的最好说明，山河破碎，国难当头，自有「肉食者谋之」，诗人不必多此一举。另外，诗人正是因为「喜论恢复」、热心抗敌才屡屡受打击，最后才罢官闲居的。作为一个年近七旬的老人，他一生问心无愧，对国家的前途和命运尽到了自己的责任，而今后国运如何他可以毫不负责。其次，虽说「天下兴亡，匹夫有责」，诗人作为年迈多病的老人也已不能承担报国杀敌的义务了。作为一个既无责任也无义务的七旬老人仍有「为国戍轮台」的壮志，这就让人肃然起敬慷慨扼腕。相比之下，那些屈辱投降的达官贵人和苟且偷生的人，他们承担着责任和义务却无心复国，显得渺小和可鄙。
「夜阑卧听风吹雨」紧承上两句。因「思」而夜阑不能成眠，不能眠就更真切地感知自然界的风吹雨打声，由自然界的风雨又想到国家的风雨飘摇，由国家的风雨飘摇自然又会联想到战争的风云、壮年的军旅生活。这样听着、想着，辗转反侧，幻化出特殊的梦境——「铁马冰河」，而且「入梦来」反映了政治现实的可悲：诗人有心报国却遭排斥而无法杀敌，一腔御敌之情只能形诸梦境。「铁马冰河入梦来」正是诗人日夜所思的结果，淋漓尽致地表达了诗人的英雄气概。这也是一代志士仁人的心声，是南宋时代的民族正气。', '僵卧：直挺挺地躺着。这里形容自己穷居孤村，无所作为。《汝南先贤传》：「时大雪，积地丈馀。洛阳令身出案行，见人家皆除雪出，有乞食者。至袁安门，无有行路，谓安已死，令人除雪，入户见安僵卧。」僵，僵硬。
孤村：孤寂荒凉的村庄。
不自哀：不为自己哀伤。
思：想着，想到。
戍（shù）轮台：在新疆一带防守，这里指戍守边疆。戍，守卫。
轮台：在今新疆境内，是古代边防重地。此代指边关。《唐书·地理志》：「北庭大都护府，有轮台县，大历十年置。」曹唐诗：「灞水桥边酒一杯，送君千里赴轮台。」
夜阑（lán）：夜深。
风吹雨：风雨交加，和题目中「风雨大作」相呼应；当时南宋王朝处于风雨飘摇之中，「风吹雨」也是时局写照，故诗人直到深夜尚难成眠。
铁马：披着铁甲的战马。《宋书》：「铁马二千，风驱电击。」
冰河：冰封的河流，指北方地区的河流。', '我直挺挺躺在孤寂荒凉的乡村里，没有为自己的处境而感到悲哀，心中还想着替国家防卫边疆。
夜将尽了，我躺在床上听到那风雨的声音，迷迷糊糊地梦见，自己骑着披着铁甲的战马跨过冰封的河流出征北方疆场。', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea73003572034f65a3834", "shortContent": "南宋光宗绍熙三年（1192）农历十一月四日深夜山阴（今浙江绍兴）骤起一场风雨，震响了僵卧孤村的六十八岁老诗人的心弦。在此前二年他以“嘲弄风月”的罪名被弹劾罢官，归隐于山阴三山故居，但老骥伏枥而志在千里，此刻诗的灵感又随风雨同至。诗中强烈的报国感情、豪迈的诗风，使人读之足可“发扬矜奋，起痿兴痹”（姚范《援鹑堂笔记》）！\n当时诗人境遇不佳，罢官时两袖清风，归居后祠禄亦时有中断，故曾有《薪米偶不继戏书》...", "authors": ["王英志"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646b72985e6bb82b8ce0b17c", "shortContent": "南宋光宗绍熙三年（1192）农历十一月四日深夜山阴（今浙江绍兴）骤起一场风雨，震响了僵卧孤村的六十八岁老诗人的心弦。在此前二年他以“嘲弄风月”的罪名被弹劾罢官，归隐于山阴三山故居，但老骥伏枥而志在千里，此刻诗的灵感又随风雨同至。诗中强烈的报国感情、豪迈的诗风，使人读之足可“发扬矜奋，起痿兴痹”（姚范《援鹑堂笔记》）！\n\n当时诗人境遇不佳，罢官时两袖清风，归居后祠禄亦时有中断，故曾有《薪米偶不继戏书...", "authors": ["王英志"], "pressName": "上海辞书出版社"}]', '', 'center', 1413128116, '57b949325bbb50005b7a9d27', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10465, '春思', NULL, 1720, 1052, 3, 2, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/151545/10830342.htm', '', '燕草如碧丝，秦桑低绿枝。
当君怀归日，是妾断肠时。
春风不相识，何事入罗帏？', '此诗写一位出征军人的妻子在明媚的春日里对丈夫梦绕魂牵的思念，以及对战争早日胜利的盼望，表现思妇的思边之苦及其对爱情的坚贞。全诗言辞朴实无华，情景交融，神骨气味高雅浑然，富有民歌特色。', '燕草：指燕地的草。燕，河北省北部一带，此泛指北部边地，征夫所在之处。
秦桑：秦地的桑树。秦，指陕西省一带，此指思妇所在之地。燕地寒冷，草木迟生于较暖的秦地。
君：指征夫。怀归：想家。
妾：古代妇女自称。此处为思妇自指。
罗帏：丝织的帘帐。', '燕地小草像碧丝般青绿，秦地的桑树已叶翠枝绿。当你怀念家园盼归之日，早就思念你而愁肠百结。春风啊你与我素不相识，为何吹进罗帐激我愁思？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929c0ce818559d05867a", "shortContent": "李白有相当数量的诗作描摹思妇的心理，《春思》是其中著名的一首。在我国古典诗歌中，“春”字往往语带双关。它既指自然界的春天，又可以比喻青年男女之间的爱情。诗题“春思”之“春”，就包含着这样两层意思。\n开头两句“燕草如碧丝，秦桑低绿枝”，可以视作“兴”。诗中的兴句一般是就眼前所见，信手拈起，这两句却以相隔遥远的燕、秦两地的春天景物起兴，颇为别致。“燕草如碧丝”，当是出于思妇的悬想；“秦桑低绿枝”，才是...", "authors": ["吴汝煜"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d92", "shortContent": "在中国古典诗歌之中，“春”通常是语意双关的：一是实指春天之时，另一则是男女情爱之代表。而本诗《春思》中的“春”，便就蕴含了这两重含义。这首诗描绘了思妇对远在燕塞的丈夫的思念之情，并巧妙地描写思妇斥责春风之态，生动勾勒出一位深闺中万分思念丈夫归来的妇人形象。\n\n首句“燕草如碧丝，秦桑低绿枝”，描绘了一番春景。燕地的春草才娇嫩如同碧玉般的细丝，而秦地的桑叶却已浓绿茂盛得压弯了枝干。燕地离妇人远在千里，...", "authors": ["孟佳"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6466e6b730675327e1920a27", "shortContent": "李白有相当数量的诗作描摹思妇的心理，《春思》是其中著名的一首。在我国古典诗歌中，“春”字往往语带双关。它既指自然界的春天，又可以比喻青年男女之间的爱情。诗题“春思”之“春”，就包含着这样两层意思。\n\n开头两句“燕草如碧丝，秦桑低绿枝”，可以视作“兴”。诗中的兴句一般是就眼前所见，信手拈起，这两句却以相隔遥远的燕、秦两地的春天景物起兴，颇为别致。“燕草如碧丝”，当是出于思妇的悬想；“秦桑低绿枝”，才...", "authors": ["吴汝煜"], "pressName": "上海辞书出版社"}]', '《分类补注李太白诗》：萧士赟注：「燕北地寒，生草迟。当秦地柔桑低绿之时，燕草方生，兴其夫方萌怀归之志，犹燕草之方生。妾则思君之久，犹秦桑之已低绿也。」又注：「燕草如丝，兴征夫怀归；秦桑低枝，兴思妇断肠。末句比喻此心贞洁，非外物所能动。此诗可谓得《国风》不淫不诽之体矣。」
《唐诗品汇》：刘云：平易近情，自有天趣。
《唐诗归》：锺云：若嗔若喜，俱着「春风」上，妙，妙（末二句下）！比「小开骂春风」沉老成些，然各有至处。谭云：后人用引意跌入填词者多矣，毕竟此处无一毫填词气，所以为践。
《唐诗镜》：尝谓大雅之道有三：淡、简、温。每读太白诗，觉深得此致。
《汇编唐诗十集》：唐云：太白虽长才，尤妙于短。如《乌夜啼》、《金陵酒肆留别》、七古之胜也：「长安一片月」、「燕草如碧丝」，五古之胜也，然《吴歌》三十字中，字字豪放；《春思》三十字中，字字和缓，谓非诗圣不可。
《唐诗评选》：字辽欲飞，不以情，不以景。《华严》有「两镜相入」义，唯供奉不离不堕。
《唐诗快》：同一「入罗帏」也，「明月」则无心可猜，而「春风」则不识何事。一信一疑，各有其妙。
《唐诗归折衷》：吴敬夫云：当两地怀思之日，而春风又至，能不悲乎！若以不为他物所摇，毁诋春风，真欲见矣。
《古唐诗合解》：此五言占中最短，难在后二句结。
《唐宋诗醇》：古意却带秀色，体近齐梁。「不相识」言不识人意也，自有贞静之意。吴昌祺曰：以风之来反衬夫之不来，与「只恐多情月，旋来照妾床」同意。', 'center', 1416661535, '57b8ee8fdf0eea0063347101', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10438, '送僧归日本', NULL, 116, 435, 1, 1, '钱起', NULL, 10114, '57bbbb372e958a00694032d7', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383375.htm', '', '上国随缘住，来途若梦行。
浮天沧海远，去世法舟轻。
水月通禅寂，鱼龙听梵声。
惟怜一灯影，万里眼中明。', '唐代国势强盛，日本派了不少遣唐使来到中国，还有不少僧人同来学习文化、技艺，求取佛法，从而极大地促进了中日文化的交流。这首诗是作者赠送给即将回国的僧人的，当时诗人在长安。
这是赠给日本僧人的送别诗。诗之起笔突兀，本是送别，前两句却不写送归，偏从来路写起。「若梦行」表现长时间乘舟航海的疲惫、恍惚的状态，以衬归国途中的艰辛，并启中间两联。颔联写海上航行时的迷茫景象，暗示归途邈远。「浮天」状海路之远，海面之阔，寓含着对僧人长途颠簸的关怀和体贴。「法舟」扣紧僧人身份，又含有人海泛舟、随缘而往之意蕴，储蓄空灵，意蕴丰富。颈联写僧人在海路中依然不忘法事修行，在月下坐禅，在舟上诵经。「水月」喻禅理，「鱼龙听」切海行，又委婉表现僧人独自诵经而谨守佛律的品性，想象丰富。尾联用「一灯」描状僧人归途中之寂寞，只有孤灯相伴，这是实处。但实中有虚，「一灯」又喻禅理、佛理。虚实相映成趣。此诗后半首不明写送归，而写海上景物，这就拓宽诗境，不受内容拘泥，使较窄的题目，能有丰富的内容，成为好的诗篇。', '上国：春秋时称中原为上国，这里指中国（唐朝）。
随缘：佛家语，随其机缘。
住：一作“至”，一作“去”。
来途：一作“东途”，指从日本来中国。
浮天：一作“浮云”，舟船浮于天际。形容海面宽广，天好像浮在海上。
沧海：即大海，因水深而呈青绿色，故名。
去世：离开尘世，这里指离开中国。
法舟：一作“法船”，指受佛法庇佑的船。
法舟轻：意为因佛法高明，乘船归国，将会一路顺利。
水月：佛教用语，比喻僧品格清美，一切像水中月那样虚幻。
禅寂：佛教悟道时清寂凝定的心境。
梵声：念佛经的声音。
惟怜：一作“惟慧”，最爱，最怜。
一灯：一作“一塔”，佛家用语，比喻智慧。灯，双关，以舟灯喻禅灯。', '只要有机缘，随时都可以到中国来；
一路雾霭茫茫，船只象在梦中航行。
天海浮沉，小船驶去那遥远的边际；
超脱世俗，自然会感受到法舟轻盈。
心境凝定清寂，一切都如水月虚幻；
海内鱼龙，也会出来听你诵经之声。
最可爱的是，有盏照亮心田的佛灯；
航行万里，眼中永远都是灿烂光明。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f09327", "shortContent": "钱起此诗，为送某位日本僧人回归日本而作。\n\n唐朝时，日本多有求法僧随遣唐使及商船前来唐朝，见于文献的达九十余人。他们在中国巡礼名士，求取佛法，带回大量佛经、佛像、佛具等，同时也有文化上的传播。最著名的最澄、空海分别创立了日本的天台宗和真言宗，空海还著有《文镜秘府论》、《篆隶万象名义》等。圆仁留唐十年的日记《入唐求法巡礼行记》，是研究唐代后期历史的重要文献。\n\n钱起是中唐时人，其时遣唐使尚未中止派遣...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '', 'center', 1413129165, '57b9a5d58ac2470063fe14b3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10439, '省试湘灵鼓瑟', NULL, 137, 435, 3, 1, '钱起', NULL, 10114, '57bbbb372e958a00694032d7', '唐', 'shi', '诗', 'http://baike.baidu.com/view/1532035.htm', '', '善鼓云和瑟，常闻帝子灵。
冯夷空自舞，楚客不堪听。
苦调凄金石，清音入杳冥。
苍梧来怨慕，白芷动芳馨。
流水传潇浦，悲风过洞庭。
曲终人不见，江上数峰青。', '这首诗为钱起唐玄宗天宝十载（751年）参加省试时所作。省试诗限定了题目和内容，又对声韵要求十分苛严，此类诗鲜有传诵人口的佳作。不过，有的作者善于“戴着镣铐跳舞”，往往能够即席发挥，写出传诵不衰的好诗来。钱起这首《省试湘灵鼓瑟》，就是一首千古称赏的名篇。
此诗既紧扣题旨，又能驰骋想象，天上人间，幻想现实，无形的乐声得到有形的表现。全诗通过曾听、客听、远近听、苍梧怨、水风悲等多层次多角度的描写，形象地再现了娥皇和女英寻夫不遇鼓瑟所弹奏的苦调清音，生动地表现了二妃对爱情生死不渝的忠贞和对驾崩于苍梧的舜帝的哀怨和思慕之情，成为公认的试帖诗范本。
结尾两句如横空出世，堪称“绝唱”，但同时又是构成全篇整体的关键一环。诗的前面大部分篇幅都是运用想象的画面着力抒写湘水女神的哀怨之情，结尾一笔跳开，描写曲终人散之后，画面上只有一川江水，几峰青山。这极其省净明丽的画面，给读者留下了思索回味的广阔空间：或许湘灵的哀怨之情已融入了湘江绵绵不断的流水，或许湘灵美丽的倩影已化成了江上偶露峥嵘的数峰青山，或许湘灵和大自然熔为一体，年年岁岁给后人讲述她那凄艳动人的故事，或许湘灵的瑟声伴着湘江流水歌吟，永远给人们留下神奇美妙的遐想。这一切的一切，都尽在不言之中了。', '省试：唐时各州县贡士到京师由尚书省的礼部主试，通称省试。
鼓：一作“拊”。云和瑟：云和，古山名。《周礼·春官大司乐》：“云和之琴瑟。”
帝子：屈原《九歌》：“帝子降兮北渚。”注者多认为帝子是尧女，即舜妻。
冯（píng）夷：传说中的河神名。见《后汉书·张衡传》注。空：一作“徒”。
楚客：指屈原，一说指远游的旅人。
金：指钟类乐器。石：指磬类乐器。
杳冥：遥远的地方。
苍梧：山名，今湖南宁远县境，又称九嶷，传说舜帝南巡，崩于苍梧，此代指舜帝之灵。来：一作“成”。
白芷：伞形科草本植物，高四尺余，夏日开小白花。
潇浦：一作“湘浦”，一作“潇湘”。
人不见：点灵字。
江上数峰青：点湘字。', '常常听说湘水的神灵，善于弹奏云和之瑟。美妙的乐曲使得河神冯夷闻之起舞，而远游的旅人却不忍卒听。那深沉哀怨的曲调，连坚硬的金石都为之感动、悲伤；那清亮高亢的乐音，穿透力是那样强劲，一直飞向那高远无垠的地方。当如此美妙的乐曲传到苍梧之野时，连安息在九嶷山上的舜帝之灵也为之感动，生出抱怨思慕之情；而生长在苍梧一带的白芷，在乐曲的感召之下，也吐出了更多的芬芳。乐声顺着流水传到湘江，化作悲风飞过了浩渺的洞庭湖。曲终声寂，却没有看见鼓瑟的湘水女神，江上烟气消散，露出几座山峰，山色苍翠迷人。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b32e6a6b501f95c236", "shortContent": "从诗题“省试”可以看出，这是一首试帖诗。《湘灵鼓瑟》这个题目，是从《楚辞·远游》“使湘灵鼓瑟兮，令海若舞冯夷”句中摘出来的。\n诗的开头两句点题，赞扬湘灵善于鼓瑟，那优美动听的乐声常常萦绕耳边。在试帖诗里，这叫做概括题旨。\n湘水女神鼓瑟，曲声袅袅，于是诗人展开想象的羽翼，伴随着仙乐，往返盘旋。那瑟曲，是多么动人心弦呵！它首先吸引了名叫冯夷的水神，使他忍不住在水上跳起舞来。其实，冯夷并没有真正听懂在美...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac26845f3e157ce323", "shortContent": "从诗题“省试”可以看出，这是一首试帖诗。《湘灵鼓瑟》这个题目，是从《楚辞·远游》“使湘灵鼓瑟兮，令海若舞冯夷”句中摘出来的。\n\n诗的开头两句点题，赞扬湘灵善于鼓瑟，那优美动听的乐声常常萦绕耳边。在试帖诗里，这叫做概括题旨。\n\n湘水女神鼓瑟，曲声袅袅，于是诗人展开想象的羽翼，伴随着仙乐，往返盘旋。那瑟曲，是多么动人心弦呵！它首先吸引了名叫冯夷的水神，使他忍不住在水上跳起舞来。其实，冯夷并没有真正听懂...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127069c305cf0801816fd0", "shortContent": "中国诗歌史上有不少考试诗，但大多水平不高，这是因为考试诗是命题而作，诸多条件限制了作者们的诗才发挥。钱起的这首诗，就是一首考试诗。“省试”是唐时各州县贡士到京师参加由尚书省主持的礼部主试。此诗格调却与众不同，它受到了楚骚文学的影响，想象丰富，渲染在神话般意境中的音乐之美。《韵语阳秋》说：“唐朝人士以诗名者甚众，往往因一篇之善，一句之工，名公先达为之游谈延誉，遂至声闻四驰。‘曲终人不见，江上数峰青。...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270e1f2af4e09d55b680d", "shortContent": "中国诗歌史上有不少考试诗，但大多水平不高，这是因为考试诗是命题而作，诸多条件限制了作者们的诗才发挥。钱起的这首诗，就是一首考试诗。“省试”是唐时各州县贡士到京师参加由尚书省主持的礼部主试。此诗格调却与众不同，它受到了楚骚文学的影响，想象丰富，渲染在神话般意境中的音乐之美。《韵语阳秋》说：“唐朝人士以诗名者甚众，往往因一篇之善，一句之工，名公先达为之游谈延誉，遂至声闻四驰。‘曲终人不见，江上数峰青。...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '《旧唐书·钱徽传》：（钱）起能五言诗。初从乡荐，寄家江湖，尝于客舍月夜独吟，遽闻人吟于庭曰：“曲终人不见，江上数峰青”。起愕然，摄衣视之，无所见矣，以为鬼怪，而志其一十字。起就试之年，李所试《湘灵鼓瑟》诗题中有“青”字，起即以鬼谣十字为落句，炜深嘉之，称为绝唱。
《韵语阳秋》：唐朝人士以诗名者甚众，往往因一篇之善，一句之工，名公先达为之游谈延誉，遂至声闻四驰。“曲终人不见，江上数峰青”。钱起以是得名。
《增订评注唐诗正声》：郭云：余亦常调，只末二语杳渺，咀味不尽。
《唐诗分类绳尺》：通篇大雅，一结信乎神助！
《唐风怀》：孙月绛曰：风致超脱，然体格却最稳密。
《五朝诗善鸣集》：真神助语，湘灵有灵。
《增订唐诗摘钞》：结自有神助，亦先有“湘浦”、“洞庭”二句，故接“曲终”、“江上”，觉缥缈超旷，云烟万状，吾谓此四句皆神助也。至“流水”、“悲风”，原系曲名，紧接“曲终”，真是神来之笔。
《唐人试帖》：承点屈平一句，亦补题法（“楚客”句下）。
《围炉诗话》：钱起亦天宝人，而《湘灵鼓瑟》诗，虽甚佳而气象萧瑟。
《而庵说唐诗》：落句真是绝调，主司读至此，叹有神助。
《大历诗略》：题境惝恍，非此杳渺之音不称。
《网师园唐诗笺》：曲与人与地胶粘入妙。末二句远韵悠然。
《唐诗近体》：结得缥缈不尽。
《唐诗五言排律》：先虚描二句，即点明题之来历，最工稳（首四句下）。结得渺然，题境方尽。“曲终”非专指既终后说，盖谓自始至终，究竟但闻其声未见其形，正不知于何来于何往，一片苍茫，杳然极目而已。题外映衬，乃得题妙，此为入神之技。', 'center', 1413129517, '57b8f461a633bd00665cfc2e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10440, '登科后', NULL, 724, 501, 1, 2, '孟郊', NULL, 10030, '57b96453165abd0054c35040', '唐', 'shi', '诗', 'http://baike.baidu.com/view/644890.htm', '', '昔日龌龊不足夸，今朝放荡思无涯。
春风得意马蹄疾，一日看尽长安花。', '唐贞元十二年（公元796年），年届四十六岁的孟郊又奉母命第三次赴京科考，终于登上了进士第。放榜之日，孟郊喜不自胜，当即写下了生平第一首快诗《登科后》。
诗的前两句将作者过去失魂落魄的处境和现今考取功名的得意情境进行今昔对比，突现今朝跃入新天地时的思绪沸腾。后两句说他在春风里洋洋得意地跨马疾驰，一天就看完了长安的似锦繁花，表现出极度欢快的心情。', '登科：唐朝实行科举考试制度，考中进士称及第，经吏部复试取中後授予官职称登科。
龌龊（wò chuò）：原意是肮脏，这里指不如意的处境。不足夸：不值得提起。
放荡（dàng）：自由自在，不受约束。
思无涯：兴致高涨。
得意：指考取功名，称心如意。
疾：飞快。', '往昔的困顿日子再也不足一提，今日金榜题名令人神采飞扬。
迎着浩荡春风得意地纵马奔驰，好像一日之内赏遍京城名花。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92bc03572034f659e502", "shortContent": "这首诗因为给后人留下了“春风得意”与“走马看花”两个成语而更为人们熟知。\n孟郊四十六岁那年进士及第，他自以为从此可以别开生面，风云际会，龙腾虎跃一番了。满心按捺不住得意欣喜之情，便化成了这首别具一格的小诗。\n诗一开头就直抒自己的心情，说以往在生活上的困顿与思想上的局促不安再不值得一提了，今朝金榜题名，郁结的闷气已如风吹云散，心上真有说不尽的畅快。孟郊两次落第，这次竟然高中鹄的，颇出意料。这就仿佛像...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a9a", "shortContent": "这首诗因为给后人留下了“春风得意”与“走马看花”两个成语而更为人们熟知。\n\n孟郊四十六岁那年进士及第，他自以为从此可以别开新生面，风云际会，龙腾虎跃一番了。满心按捺不住得意欣喜之情，便化成了这首别具一格的小诗。\n\n诗一开头就直抒自己的心情，说以往在生活上的困顿与思想上的局促不安再不值得一提了，今朝金榜题名，郁结的闷气已如风吹云散，心上真有说不尽的畅快。孟郊两次落第，这次竟然高中鹄的，颇出意料。这就...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706a73206168b2e02211", "shortContent": "唐德宗贞元十三年（797），孟郊终于进士及第，而这时，他已经46岁了。诗人高兴地作了这首绝句，来表达他当时难以按捺的喜悦之情。\n\n唐代实科举制，登科可以为官，光耀门庭，为士人显达最重要的途径。故登科的成败是决定士人政治生命的关键，甚为时人看重。在中举之前，诗人曾经几次落第，其中包含着多少难以言说的悲哀和无奈。回首往日的辛酸苦辣，不禁感慨万千。“昔日龌龊不足夸”是指过去那种穷困窘迫的生活已像流水一样...", "authors": ["陈鹏"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127104c9ebcc6fbea1a458", "shortContent": "唐德宗贞元十三年（797），孟郊终于进士及第，而这时，他已经四十六岁了。诗人高兴地作了这首绝句，来表达他当时难以按捺的喜悦之情。\n\n唐代盛行科举制，登科可以为官，光耀门庭，为士人显达最重要的途径。故登科的成败是决定士人政治生命的关键，甚为时人看重。在中举之前，诗人曾经几次落第，其中包含着多少难以言说的悲哀和无奈。回首往日的辛酸苦辣，不禁感慨万千。“昔日龌龊不足夸”是指过去那种穷困窘迫的生活已像流水...", "authors": ["陈鹏"], "pressName": "崇文书局"}]', '国材：失意处牢骚幽愤过甚，得意后便尔骄穉放荡，何语未免寒态。
周紫芝《竹坡诗话》：余尝读孟东野下第诗云：「弃置复弃置，情如刀剑伤。」及登弟，则自谓「春风得意马蹄疾，一日看尽长安花。」一第之得失，喜忧至于如此，宜其虽得之而不能享也。
黄彻《巩溪诗话》：乐天及第后，阳觐留别同年云：「擢第未为贵，拜亲方始荣。」此毛义得檄而与之意也。论者以「春风得意马蹄疾」决非孟郊语，其气格亦不类。而白公亦有「得意减别恨，半酣轻远程。翩翩马蹄疾，春日阳乡情」。此又不可晓也。
葛立方《韵语阳秋》：孟郊《落第》诗曰：「弃置复弃置，情如刀刃伤。」《再下第》诗曰：「一夕九起嗟，梦短不到家。」《下第东南行》曰：「江蓠伴我泣，海月投人惊。」愁有余矣。……《诗意投刘侍御》云：「离娄岂不明，子野岂不聪，至宝非眼别，至音非耳通。」《叹命》云：「题诗怨还怨，问易蒙复蒙。本望文字达，今因文字穷」，怨有余矣。至《登科后》诗，则云：「昔日龌龊不足夸，今朝放荡思无涯，春风得意马蹄疾，一日看尽长安花。」议者以此诗验郊非远器。余谓郊偶不遂志，至于屡泣，非能委顺者，年五十始得一第，而放荡无涯，哦诗夸咏，非能自持者，其不至远大，宜哉。
瞿佑《归田诗话》：东野诗如「食荠肠亦苦，强歌声无欢。出门即有碍，谁谓大地宽？」……气象如此，宜其一生局蹐也。惟《登第》云：「春风得意马蹄疾，一日看尽长安花。」颇放绳墨。然长安花，一日岂能看尽？此亦谶其不至远大之兆。
陆时雍《唐诗镜》：末二句似古诗语，不类绝句常调。', 'center', 1413200019, '57add198a633bd0057eefa8a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10441, '浣溪沙 · 元丰七年十二月二十四日，从泗州刘倩叔游南山', NULL, 710, 3406, 2, 1, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/item/浣溪沙·细雨斜风作晓寒', '', '细雨斜风作晓寒，淡烟疏柳媚晴滩。入淮清洛渐漫漫。
雪沫乳花浮午盏，蓼茸蒿笋试春盘。人间有味是清欢。', '这首纪游词，是宋神宗元丰七年（西元一〇八四年），苏东坡在赴汝州（今河南汝县）任团练使途中，路经泗州（今安徽泗县）时，与泗州刘倩叔同遊南山时所作。词的上阕写早春景象，下阕写作者与同遊者遊山时以清茶野餐的风味。作品充满春天的气息，洋溢着生命的活力，反映了作者对现实生活的热爱和健胜进取的精神。
上阕写沿途景观。第一句写清晨，风斜雨细，瑟瑟寒侵，这残冬腊月是很难耐的，可是东坡却衹以「作小寒」三字出之，表现了一种不大在乎的态度。
第二句写向午的景物：雨脚渐收，烟云淡荡，河滩疏柳，尽沐晴晖。一个「媚」字，极富动感地传出作者喜悦的心声。作者从曳于淡云晴日中的疏柳，觉察到萌发中的春潮。于残冬岁暮之中把握住物象的新机，这正是东坡逸怀浩气的表现，是他精神境界上度越恒流之处。「入淮」句寄兴遥深，一结甚远。句中的「清洛」，即「洛涧」，发源于合肥，北流至怀远合于淮水，地距泗州（宋治临淮）不近，非目力能及。词中提到清洛，是以虚摹的笔法，眼前的淮水联想到上游的清碧的洛涧，当它汇入浊淮以後，就变得浑浑沌沌一片浩茫了。
下阕转写作者遊览时的清茶野餐及欢快心情。一起两句，作者抓住了两件有特征性的事物来描写：乳白色的香茶一盏和翡翠般的春蔬一盘。两相映托，便有浓郁的节日气氛和诱人的力量。「雪沫」乳花，状煎茶时上浮的白泡。以雪、乳形容茶色之白，既是比喻，又是夸张，形象鲜明。午盏，指午茶。此句可说是对宋人茶道的形象描绘。「蓼茸蒿笋」，即蓼芽与蒿茎，这是立春的应时节物。旧俗立春时馈送亲友以鲜嫩春菜和水果、饼饵等，称「春盘」。
此二句绘声绘色、活灵活现地写出了茶叶和鲜菜的鲜美色泽，使读者从中体味到词人品茗尝鲜时的喜悦和畅适。这种将生活形象铸成艺术形象的手法，显示出词人高雅的审美意趣和旷达的人生态度。「人间有味是清欢」，这是一个具有哲理性的命题，用词的结尾，却自然浑成，有照彻全篇之妙趣，为全篇增添了欢乐情调和诗味、理趣。
这首词，色彩清丽而境界开阔的生动画面中，寄寓着作者清旷、闲雅的审美趣味和生活态度，给人以美的享受和无尽的遐思。', '浣溪沙：词牌名。原为唐代教坊曲，《金奁集》入「黄钟宫」，《张子野词》入「中吕宫」。唐声诗（唐代配乐之近体诗）亦有「浣溪沙」调名，歌词为七言六句形式；又有「浣纱女」调名，歌词为五言四句形式。从字义上来看，「浣」，洗涤、漂洗也；「沙」，古通「纱」，故所「浣」者，「纱」也。敦煌出土之唐写本《云谣集·杂曲子》及五代後蜀赵崇祚《花间集》所录毛平圭、阎处士、毛熙震、李德润词，调名均题为「浣纱溪」。据南朝宋孔灵符《会稽记》载：「勾践索美女以献吴王，得诸暨罗山卖薪女西施、郑旦，先教习于土城山。山边有石，云是西施浣纱石」。今浙江诸暨市南近郊的苧萝山下浣纱溪畔有浣纱石，上有传为东晋王右军所书「浣纱」二字，即所传春秋时越国美女西子浣纱处。一说浣纱溪即浙江绍兴南二十里若耶溪。总之，调名「浣纱溪」的本意即咏西子浣纱之溪。又，近人梁启勋《词学·调名》云：「《浣纱溪》，杜少陵诗『移船先生庙，洗药浣纱溪』。」按：今查《杜工部集》，唐杜少陵《绝句三首》诗有「移船先主庙，洗药浣沙溪」之句。成都杜甫草堂附近有浣花溪而无浣纱溪，况且梁启勋所引诗句，其中的「生」「纱」二字尚有异文，故梁说仅备参考。最早采用此调的是唐人韩致尧，通常以其词《浣溪沙·宿醉离愁慢髻鬟》为正体，另有四种变体。正体双调，四十二字，上阕三句，三平韵；下阕三句，两平韵；过阕二句多用对偶。另有仄韵体，始于南唐后主。此调音节明快，句式整齐，易于上口，为婉约、豪放两派词人所常用。别有《摊破浣溪沙》，又名《山花子》，上下阕各增三字，韵全同。张子澄词有「露浓香泛小庭花」句，名《小庭花》；韩涧泉词有「芍药酴縻满院春」句，名《满院春》；有「东风拂栏露犹寒」句，名《东风寒》；有「一曲西风醉木犀」句，名《醉木犀》；有「霜后黄花菊自开」句，名《霜菊黄》；有「广寒曾折最高枝」句，名《广寒枝》；有「春风初试薄罗衫」句，名《试香罗》；有「清和风里绿荫初」句，名《清和风》；有「一番春事怨啼鹃」句，名《怨啼鹃》。
雪沫：明吴讷钞本、茅维《苏集》本作「雪味」。
乳花：龙榆生笺：「《茶寮记》：『云脚渐垂，乳花浮面。』」傅子立注：「『云腴』、『花乳』，茶之佳品如此。曹邺之《茶》诗：『碧波霞脚碎，香汎乳花轻。』又丁谓诗：『花随僧箸破，云逐客瓯圆。』」刘尚荣按：「曹邺之《故人寄茶》诗见《全唐诗·卷五百九十二》，题下原注：『一作李朱崖诗。』原句『波』作『沉』。又丁谓《煎茶》诗见《瀛奎律髓·卷八十》转引，其文集已佚。」
「雪沫乳花浮午盏」句：谓午间喝茶。雪沫乳花，状煎茶时上浮之白泡。宋人以讲茶泡制成白色为贵，所谓「茶与墨正相反，茶欲白，墨欲黑」（宋·赵德麟《侯鲭录·卷四》记司马温公语）。
蓼茸蒿笋：龙榆生笺：「《说文》：『蓼，辛菜。』《礼记·月令》注：『蒿亦蓬萧之属。』」蓼茸，《苏长公二妙集》本、毛本作「蓼芽」。', '细雨斜风天气微寒。淡淡的烟雾，滩边稀疏的柳树使刚放晴后的沙滩愈加美丽。眼前入淮清洛，亦仿佛渐流渐见广远无际。
乳色鲜白的好茶伴着新鲜的野菜。人间真正有味道的还是清淡的欢愉。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b603572034f65962b8", "shortContent": "这首南山纪游之作，掇拾眼前景物，却涉笔成趣，寓意深刻，有自然浑成之妙。\n元丰七年（1085）三月，苏轼在黄州贬所过了四年多谪居生活之后，被命迁汝州（今属河南汝州市）团练副使。这种量移虽然不是升迁，但却标志着政治气候的转机。据《宋史》本传，神宗手札移轼汝州，有“人材实难，不忍终弃”之语。这年四月东坡离黄赴汝，心境比较轻松，一路上颇事游访。畅游庐山，在江西筠州探视了胞弟子由，到金陵又与致仕家居的王安石...", "authors": ["周笃文"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5bcc6e67846a92190c0", "shortContent": "这首南山纪游之作，掇拾眼前景物，却涉笔成趣，寓意深刻，有自然浑成之妙。\n元丰七年（1085）三月，苏轼在黄州贬所过了四年多谪居生活之后，被命迁汝州（治所在今河南临汝）团练副使。这种量移虽然不是升迁，但却标志着政治气候的转机。据《宋史》本传，神宗手札移轼汝州，有“人材实难，不忍终弃”之语。这年四月东坡离黄赴汝，心境比较轻松，一路上颇事游访。畅游庐山，在江西筠州探视了胞弟子由，到金陵又与致仕家居的王安...", "authors": ["周笃文"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7cc26cbf3417f09208", "shortContent": "傅藻《东坡纪年录》：“元丰七年甲子（1084）十二月二十四日，从刘倩叔游南山作《浣溪沙》。”薛本、邹王本从之。南山，又名都梁山。《太平寰宇记》：“盱眙县在泗州南五里，都梁山在县南六十里。”苏轼《泗州南山监仓萧渊东轩二首》其一自注：“南山名都梁山，山出都梁香故也。”", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646843835fc8182fe9acd52d", "shortContent": "这首南山纪游之作，掇拾眼前景物，却涉笔成趣，寓意深刻，有自然浑成之妙。\n\n元丰七年（1085）三月，苏轼在黄州贬所过了四年多谪居生活之后，被命迁汝州（今属河南临汝）团练副使。这种量移虽然不是升迁，但却标志着政治气候的转机。据《宋史》本传，神宗手札移轼汝州，有“人材实难，不忍终弃”之语。这年四月东坡离黄赴汝，心境比较轻松，一路上颇事游访。畅游庐山，在江西筠州探视了胞弟子由，到金陵又与致仕家居的王安石...", "authors": ["周笃文"], "pressName": "上海辞书出版社"}]', '', 'indent', 1413388603, '57b8eea4128fe10054c918ea', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10442, '履园丛话·水学·三江', NULL, 51, 7, 1, 3, '钱泳', NULL, 25945, '5858f3b31b69e6006cb16016', '清', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%A5%E5%9B%AD%E4%B8%9B%E8%AF%9D/4598282?fr=aladdin', '', ' 大凡治事，必需通观全局，不可执一而论。昔人有专浚吴淞而舍刘河、白茅者，亦有专治刘河而舍吴淞、白茅者，是未察三吴水势也。', '《履园丛话》是清代作家、书法家钱泳创作的一部笔记小说著作。该书讲述了作者以亲身经历为依照，对清代的政治、经济、文化、社会生活等各个方面的进行记载。', '', '', NULL, '', 'indent', 1413450752, '57b8f1f45bbb50005b77c405', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10443, '滁州西涧', NULL, 971, 570, 1, 14, '韦应物', NULL, 10115, '57b9b835128fe1005f860400', '唐', 'shi', '诗', 'http://baike.baidu.com/view/35950.htm', '', '独怜幽草涧边生，上有黄鹂深树鸣。
春潮带雨晚来急，野渡无人舟自横。', '作者任滁州剌史时，游览至滁州西涧，写下了这首诗情浓郁的小诗。诗里写的虽然是平常的景物，但经诗人的点染，却成了一幅意境幽深的有韵之画，还蕴含了诗人一种不在其位，不得其用的无奈与忧伤情怀，也就是作者对自己怀才不遇的不平。', '滁州：在今安徽滁州以西。西涧：在滁州城西，俗名称上马河。　
独怜：唯独喜欢。幽草：幽谷里的小草。幽，一作“芳”。生：一作“行”。
深树：枝叶茂密的树。深，《才调集》作“远”。树，《全唐诗》注“有本作‘处’”。
春潮：春天的潮汐。
野渡：郊野的渡口。横：指随意飘浮。', '我喜爱生长在涧边的幽草，黄莺在幽深的树丛中啼鸣。
春潮夹带着暮雨流的湍急，惟有无人的小船横向江心。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b934a8757d5a0e1d2d", "shortContent": "这是一首山水诗的名篇，也是韦应物的代表作之一。诗写于唐德宗建中二年（781）诗人出任滁州刺史期间。唐滁州治所即今安徽滁州市，西涧在滁州城西郊野。这诗写春游西涧赏景和晚雨野渡所见。诗人以情写景，借景述意，写自己喜爱与不喜爱的景物，说自己合意与不合意的情事，而其胸襟恬淡，情怀忧伤，便自然流露出来。但是诗中有无寄托，寄托何意，历来争论不休。有人认为它通首比兴，是刺“君子在下，小人在上”；有人认为“此偶赋...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a91", "shortContent": "这是一首山水诗的名篇，也是韦应物的代表作之一。诗写于唐德宗建中二年（781）诗人出任滁州刺史期间。唐滁州治所即今安徽滁州市，西涧在滁州城西郊野。这诗写春游西涧赏景和晚雨野渡所见。诗人以情写景，借景述意，写自己喜爱与不喜爱的景物，说自己合意与不合意的情事，而其胸襟恬淡，情怀忧伤，便自然流露出来。但是诗中有无寄托，寄托何意，历来争论不休。有人认为它通首比兴，是刺“君子在下，小人在上”；有人认为“此偶赋...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290e7", "shortContent": "在中国山水诗诗史上，这是一首久负盛名的写景佳作。唐德宗建中二年（781）诗人出任滁州刺史，这首诗就是这一时期所写。通篇富有“野美”情趣。\n \n作者游览至人迹罕至的滁州西涧，野外的风物打动了久在世俗夹缝中求生存的诗人。涧边无声无息生长的幽草，深林中自由自在欢叫的黄鸾，都引起诗人的无限诗心。这是自然的色彩与动听的百籁交织成的幽雅景致。“独怜”是偏爱的意思，偏爱幽草，流露出诗人恬淡的胸怀。凡俗之人也许不...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706a7f0b9738b369b214", "shortContent": "在中国山水诗诗史上，这是一首久负盛名的写景佳作。唐德宗建中二年（781）诗人出任滁州刺史，这首诗就是这一时期所写。通篇富有“野美”情趣。\n\n作者游览至人迹罕至的滁州西涧，野外的风物打动了久在世俗夹缝中求生存的诗人。涧边无声无息地生长的幽草，深林中自由自在的黄莺的欢叫，都引起诗人的无限诗心。这是自然的色彩与动听的百籁交织成的幽雅景致。“独怜”是偏爱的意思，偏爱幽草，流露出诗人恬淡的胸怀。凡俗之人也许...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270f6f2af4e09d55b6822", "shortContent": "在中国山水诗诗史上，这是一首久负盛名的写景佳作。唐德宗建中二年（781）诗人出任滁州刺史，这首诗就是这一时期所写。通篇富有“野美”情趣。\n\n作者游览至人迹罕至的滁州西涧，野外的风物打动了久在世俗夹缝中求生存的诗人。涧边无声无息地生长的幽草，深林中自由自在的黄莺的欢叫，都引起诗人的无限诗心。这是自然的色彩与动听的百籁交织成的幽雅景致。“独怜”是偏爱的意思，偏爱幽草，流露出诗人恬淡的胸怀。凡俗之人也许...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "64719ecfb5420e27678db9c0", "shortContent": "这是一首山水诗的名篇，也是韦应物的代表作之一。诗写于唐德宗建中二年(781)诗人出任滁州刺史期间。唐滁州治所即今安徽滁州市，西涧在滁州城西郊野。这诗写春游西涧赏景和晚雨野渡所见。诗人以情写景，借景述意，写自己喜爱与不喜爱的景物，说自己合意与不合意的情事，而其胸襟恬淡，情怀忧伤，便自然流露出来。\n诗的前二句，在春天繁荣景物中，诗人独爱自甘寂寞的涧边幽草，而无意于深树上鸣声诱人的黄莺儿，置之陪衬，以相...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}]', '高棅《唐诗品汇》：欧阳子云：滁州城西乃是丰山，无西涧，独城北有一涧水极浅不胜舟，又江潮不到。岂诗人务在佳句而实无此景耶？谢叠山云：“幽草”、“黄鹂”，此君子在野，小人在位。“春潮带雨晚来急”，乃季世危难多，如日之已晚，不复光明也。末句谓宽闲寂莫之滨，必有贤人如孤舟之横渡者，特君不能用耳。此诗人感时多故而作，又何必滁之果如是也。刘（辰翁）云：此语自好，但韦公体出，数字神情又别，故贵知言，不然不免为野人语矣。好诗必是拾得，此绝先得后半，起更难似，故知作者用心。
《批点唐诗正声》：沉密中寓意闲雅，如独坐看山，澹然忘归，诗之绝佳者。谢公曲意取譬、何必乃尔！
《增订评注唐诗正声》：郭云：冷处着眼，妙。
周珽《唐诗选脉会通评林》：周敬曰：一段天趣，分明写出画意。
王士禛《带经堂诗话》：西涧在滁州城西……昔人或谓西涧潮所不至，指为今六合县之芳草涧，谓此涧亦以韦公诗而名，滁人争之。余谓诗人但论兴象，岂必以潮之至与不至为据？真痴人前不得说梦耳！
沈德潜《唐诗别裁》：起二句与下半无关。下半即景好句，元人谓刺君子在下，小人在上，此辈难与言诗。
赵彦传《唐绝诗钞注略》：《诗人玉屑》以“春潮”二句为入画句法。
黄叔灿《唐诗笺注》：闲淡心胸，方能领略此野趣。所难尤在此种笔墨，分明是一幅画图。
宋顾乐《唐人万首绝句选评》：写景清切，悠然意远，绝唱也。
王文濡《唐诗评注读本》：先以“涧边幽草”、“深树黄鹂”引起，写西涧之景，历历如绘。', 'center', 1413455724, '57b8ebc17db2a20054261f6a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10444, '八阵图', NULL, 386, 1416, 1, 2, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/2352/5814391.htm', '', '功盖三分国，名成八阵图。
江流石不转，遗恨失吞吴。', '这是作者初到夔州时作的一首咏怀诸葛亮的诗，写于唐代宗大历元年（766年）。前二句赞颂诸葛亮的丰功伟绩，尤其称颂他在军事上的才能和建树。后二句对刘备吞吴失师，葬送了诸葛亮联吴抗曹统一中国的宏图大业，表示惋惜。末句照应开头，三句照应二句。在内容上，既是怀古，又是抒怀，情中有情，言外有意；在绝句中别树一格。', '八阵图：由八种阵势组成的图形，用来操练军队或作战。
盖：超过。三分国：指三国时魏、蜀、吴三国。
石不转：指涨水时，八阵图的石块仍然不动。
失吞吴：是吞吴失策的意思。', '三国鼎立，孔明的功勋最为卓著，他创制的八卦阵，更是名扬千古。
任凭江流冲击，石头却依然如故，千年遗恨，在于刘备失策想吞吴。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92afc6e67846a920eafa", "shortContent": "这是作者初到夔州（治今重庆奉节）时作的一首咏怀诸葛亮的诗，写于大历元年（766）。“八阵图”，指由天、地、风、云、龙、虎、鸟、蛇八种阵势所组成的军事操练和作战的阵图，是诸葛亮的一项创造，反映了他卓越的军事才能。\n“功盖三分国，名成八阵图。”这两句赞颂诸葛亮的丰功伟绩。第一句是从总的方面写，说诸葛亮在确立魏蜀吴三分天下、鼎足而立局势的过程中，功绩最为卓绝。三国并存局面的形成，固然有许多因素，而诸葛亮...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e90393", "shortContent": "杜甫入蜀之后，对诸葛亮的济世之才情有独钟，写下了多首关于诸葛亮的诗歌。本诗写于杜甫初入夔州时的大历元年（766），他在凭吊相传由蜀相诸葛亮所首创的八阵图遗迹时即兴创作了本作。\n\n这是一首咏怀诗。诗人赞颂了诸葛亮的丰功伟绩，尤其称颂他在军事上的才能和建树。这首怀古绝句，具有融议论入诗的特点。既是怀古，又是抒怀，情中有情，言外有意，在绝句中别树一格。但诗中的议论并不空洞抽象，反而生动形象，抒情色彩浓郁...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270607f0b9738b369b1f2", "shortContent": "杜甫入蜀之后，对诸葛亮的济世之才情有独钟，写下了多首关于诸葛亮的诗歌，本诗写于杜甫初入夔州时的大历元年（766），他在凭吊相传由蜀相诸葛亮所首创的八阵图遗迹时即兴创作了本诗。这首诗的内容，既有对诸葛亮功绩的全面概括和总结，也有对诸葛亮军事成就的高度赞美，还有对诸葛亮失误之处的客观评析。在杜甫所有诗作中，吟咏诸葛亮丰功伟绩的诗篇相当引人注目。\n\n这是一首咏怀诗。诗人赞颂了诸葛亮的丰功伟绩，尤其称颂他...", "authors": ["林錦萍"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270d3c26cbf3417f094fe", "shortContent": "杜甫入蜀之后，对诸葛亮的济世之才情有独钟，写下了多首关于诸葛亮的诗歌。本诗写于杜甫初入夔州时的大历元年（766），他在凭吊相传由蜀相诸葛亮所首创的八阵图遗迹时即兴创作了本诗。这首诗的内容，既有对诸葛亮功绩的全面概括和总结，也有对诸葛亮军事成就的高度赞美，还有对诸葛亮失误之处的客观评析。在杜甫所有诗作中，这首吟咏诸葛亮丰功伟绩的诗篇相当引人注目。\n\n这是一首咏怀诗。诗人赞颂了诸葛亮的丰功伟绩，尤其称...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "64660a1345e4710056ca1cc1", "shortContent": "这是作者初到夔州（治今重庆奉节）时作的一首咏怀诸葛亮的诗，写于大历元年（766）。“八阵图”，指由天、地、风、云、龙、虎、鸟、蛇八种阵势所组成的军事操练和作战的阵图，是诸葛亮的一项创造，反映了他卓越的军事才能。\n\n“功盖三分国，名成八阵图。”这两句赞颂诸葛亮的丰功伟绩。第一句是从总的方面写，说诸葛亮在确立魏蜀吴三分天下、鼎足而立局势的过程中，功绩最为卓绝。三国并存局面的形成，固然有许多因素，而诸葛...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}]', '《东坡志林》：仆尝梦见人，云是杜子美，谓仆曰：“世人多误解吾诗。《八阵图》诗云：‘江流石不转，遣恨失吞吴’，人皆以为‘先主、武侯，皆欲与关羽复仇，故恨其不能灭吴’，非也。我本意谓吴、蜀唇齿之国，不当相图；晋之所以能取蜀者，以蜀有吞吴之意；此为恨耳。”此理甚长。
《唐诗选脉会通评林》：周珽曰：洒英雄之泪，唾壶无不碎者矣。
《杜工部集》：钱谦益笺：按先主征吴败绩，还至鱼腹，孔明叹曰：“法孝直若在，必能制主上东行，不至危倾矣。”公诗意亦如此。
《杜诗详注》：下句（按指“遗恨失吞吴”）有四说：以不能灭吴为恨，此旧说也；以先主之征吴为恨，此东坡说也；不能制主东行，而自以为恨，此《杜臆》、朱注说也；以不能用阵法而致吞吴失师，此刘逹之说也。
《唐宋诗醇》：遂使诸葛精神，炳然千古，读之殷殷有金石声。
《读杜心解》：
说是诗者，言人人殊……抛却“石不转”二字，致全诗走作。岂知“遗恨”从“石不转”生出耶？盖阵图正当控扼东吴之口，故假石以寄其婉惜。云此石不为江水所转，天若欲为千载留遗此恨迹耳。如此才是咏阵图之诗。
《诗法易简录》：前题《武侯庙》，故写出武侯全部精神，此题《八阵图》，故只就阵图一节写其遗恨，作诗切题之法有如是。
《诗境浅说续编》：武侯之志，征吴非所急也：乃北伐未成，而先主猇亭挫败，强邻未灭，剩有阵图遗石，动悲壮之江声。故少陵低徊江浦，感遗恨于吞吴，千载下如闻叹息声也。
《唐人绝句精华》：“江流”句，从句面看似写聚石不为水所冲激，实已含末句“恨”字之意。……“石不转”有恨不消之意，知此五字亦非空设。杜甫运思之细，命意之高，于此可见。', 'center', 1413456072, '57b95d098ac2470062e2bf1f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10446, '春雨', NULL, 187, 603, 1, 4, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/176593/5129883.htm', '', '怅卧新春白袷衣，白门寥落意多违。
红楼隔雨相望冷，珠箔飘灯独自归。
远路应悲春晼晚，残宵犹得梦依稀。
玉珰缄札何由达，万里云罗一雁飞。', '春雨潇潇，情丝缭绕。这首诗是借助飘洒迷朦的春雨，抒发怅念远方恋人的情绪。开头先点明时令，再写旧地重寻之凄怆，继而写隔雨望楼，寻访落空之迷茫，终而只有相思相梦，缄札寄情。一步紧逼一步，怅念之情恰似雨丝不绝如缕。诗的意境、感情、色调、气氛都是十分清晰明丽，优美动人。诗借助于飘洒迷濛的春雨，融入主人公迷茫的心境，依稀的梦境，烘托别离的寥落，思念的真挚，构成浑然一体的艺术境界。
李商隐的诗歌擅用一些具有代表性的意象来展示诗人心灵中最美丽的东西。这首《春雨》也隐喻着诗人难言的感情，抒发着诗人哀伤的情愫，并且具有相当的美感。', '白袷衣：即白夹衣，唐人以白衫为闲居便服。
白门：金陵的别称，即现南京。南朝乐府民歌《杨叛儿》说：“暂出白门前，杨柳可藏乌。欢作沉水香，侬作博山炉”，讲的是男女欢会。后人常用“白门”指代男女幽会之地。
红楼：华美的楼房，多指女子的住处。
珠箔：珠帘，此处比喻春雨细密。
晼晚：夕阳西下的光景，此处还蕴涵年复一年、人老珠黄之意。
依稀：形容梦境的忧伤迷离。
玉珰：是用玉做的耳坠，古代常用环珮、玉珰一类的饰物作为男女定情的信物。
缄札：指书信。
云罗：像螺纹般的云片，阴云密布如罗网，比喻路途艰难。', '初春我身披白色便服躺在床上，眼前寥落的景象令我万分感伤。
你住过的红楼在雨中更加凄凉，我默然归去任珠帘在风中摆动。
在远路奔波却已暮春令人感伤，只有在残宵梦中才能与你相见。
我的一片痴情却无法传递给你，春阴云弥漫大雁正在为我传书。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dfdbb8b379ee095d3d", "shortContent": "一个春雨绵绵的早晨，诗中的男主人公穿着白布夹衫，和衣怅卧。他的心中究竟隐藏着什么？究竟何以至此呢？诗在点明“怅卧”之后，用一句话作了概括的交代：“白门寥落意多违”。据南朝民歌《杨叛儿》：“暂出白门前，杨柳可藏乌。欢作沉水香，侬作博山炉。”“白门”当指男女欢会之所。过去的欢会处，今日寂寥冷落已不见对方的踪影。与所爱者分离的失意，便是他愁思百结地怅卧的原因。\n怅卧中，他的思绪浮动，回味着最后一次寻访对...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d7ff2af4e09d55b63bc", "shortContent": "本篇借春雨为题怀念所思女子。首联谓己在春雨绵绵的天气里和衣而卧，心中怅然；有约不来，门庭冷落。次联谓雨中探望女子所居之楼阁，人去楼空，只得提灯冒着寒风细雨独自归来。三联谓伊人在夕照途中，定当感别而伤春；己则因相思入梦，仿佛见其犹在身边。末联谓玉珰和书信凭谁带给伊人留赏呢？只有把渺茫的希望寄托于碧落飞鸿了。", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f0935a", "shortContent": "这是作者重游故地，怀念旧日情人所作。开头写诗人重新来到当日欢聚的地方，却已人去楼空。独自穿着白色的夹衣，寂寞地徘徊，又兼春雨如丝，更添愁绪。怀着惆怅的心情躺在卧榻之上，相思的情怀更加不能自已。隔着濛濛的细雨，看见思念的人当初住的红楼，只觉楼空院冷，兴味萧索。独自归来的途中，细雨洒在手提的灯笼之上，在灯光的照耀之下，晶莹飘逸，有如珠帘荡漾。\n\n远去的伊人难道不会像自己这样多情吗？难道她不会在日暮黄昏...", "authors": ["张力"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "6463849dcd12b001c6e1a92c", "shortContent": "一个春雨绵绵的早晨，诗中的男主人公穿着白布夹衫，和衣怅卧。他的心中究竟隐藏着什么？究竟何以至此呢？诗在点明“怅卧”之后，用一句话作了概括的交代：“白门寥落意多违。”据南朝民歌《杨叛儿》:“暂出白门前，杨柳可藏乌。欢作沉水香，侬作博山炉。”“白门”当指男女欢会之所。过去的欢会处，今日寂寥冷落已不见对方的踪影。与所爱者分离的失意，便是他愁思百结地怅卧的原因。\n\n怅卧中，他的思绪浮动，回味着最后一次寻访...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}]', '《李义山诗集笺注》：姚培谦曰：此借春雨怀人，而寓君门万里之感也……此等诗，字字有意，概以闺帏之语读之，负义山极矣。
《玉溪生诗意》：中四是白门怅卧时忆往多违事，末二句是怅卧时所思后事。
《重订李义山诗集笺注》：程梦星曰：此亦应辟无聊、望人汲引之作，盖入藩幕未出长安之时也。
《玉溪生诗说》：宛转有味。平山笺以为此有寓意，亦属有见。然如此诗即无寓意，亦自佳。
《唐贤清雅集》：以丽语写惨怀，一字一泪。用比作结，不知是泪是墨，义山真有心人。
《李义山诗辨正》：此与《燕台》二章相合。首二句想其流转金陵寥落之态。三四句经过旧居，室迩人遐，唯笼灯独归耳。五句道远难亲。六句梦中相见。结即“欲织相思花寄远”之意。', 'center', 1413461998, '57b967732e958a005fa8f602', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10447, '题破山寺后禅院', NULL, 920, 55, 3, 19, '常建', NULL, 10117, '57b9bf5ac4c9710061480f1c', '唐', 'shi', '诗', 'http://baike.baidu.com/view/162686.htm', '', '清晨入古寺，初日照高林。
曲径通幽处，禅房花木深。
山光悦鸟性，潭影空人心。
万籁此都寂，但余钟磬音。', '此诗是唐代诗人常建的一首题壁诗，载于《全唐诗·卷一四四》，并入选《唐诗三百首》。此诗抒写清晨游寺后禅院的观感，以凝炼简洁的笔触描写了一个景物独特、幽深寂静的境界，表达了诗人游览名胜的喜悦和对高远境界的强烈追求。全诗笔调古朴，层次分明，兴象深微，意境浑融，简洁明净，感染力强，艺术上相当完整，是唐代山水诗中独具一格的名篇。', '破山寺：即兴福寺，在今江苏常熟市西北虞山上。南朝齐邑人郴州刺史倪德光舍宅所建。
清晨：早晨。
入：进入。
古寺：指破山寺。
初日：早上的太阳。
照：照耀。
高林：高树之林。
曲径：一作「竹径」、又作「一径」。
通：一作「遇」。
幽：幽静。
禅房：僧人居住修行的地方。
悦：此处为使动用法，使……高兴。
潭影：清澈潭水中的倒影。
空：此处为使动用法，使……空。此句意思是，潭水空明清澈，临潭照影，令人俗念全消。
万籁（lài）：各种声音。籁，从孔穴里发出的声音，泛指声音。
此：在此，即在后禅院。
都：一作「俱」。
但余：只留下。一作「惟余」、又作「唯闻」。
钟磬（qìng）：佛寺中召集众僧的打击乐器。磬，古代用玉或金属制成的曲尺形的打击乐器。', '大清早我走进这古老寺院，旭日初升映照着山上树林。
竹林掩映小路通向幽深处，禅房前后花木繁茂又缤纷。
山光明媚使飞鸟更加欢悦，潭水清澈也令人爽神净心。
此时此刻万物都沉默静寂，只留下了敲鐘击磬的声音。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92bfc6e67846a920ec29", "shortContent": "破山在今江苏常熟，寺指兴福寺，是南齐时郴州刺史倪德光施舍宅园改建的，到唐代已属古寺。诗中抒写清晨游寺后禅院的观感，笔调古朴，描写省净，兴象深微，意境浑融，艺术上相当完整，是盛唐山水诗中独具一格的名篇。\n这首诗题咏的是佛寺禅院，抒发的是寄情山水的隐逸胸怀。诗人在清晨登破山，入兴福寺，旭日初升，光照山上树林。佛家称僧徒聚集的处所为“丛林”，所以“高林”兼有称颂禅院之意，在光照山林的景象中显露着礼赞佛宇...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a9f", "shortContent": "破山在今江苏常熟，寺指兴福寺，是南齐时郴州刺史倪德光施舍宅园改建的，到唐代已属古寺。诗中抒写清晨游寺后禅院的观感，笔调古朴，描写省净，兴象深微，意境浑融，艺术上相当完整，是盛唐山水诗中独具一格的名篇。\n\n这首诗题咏的是佛寺禅院，抒发的是寄情山水的隐逸胸怀。诗人在清晨登破山，入兴福寺，旭日初升，光照山上树林。佛家称僧徒聚集的处所为“丛林”，所以“高林”兼有称颂禅院之意，在光照山林的景象中显露着礼赞佛...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151c5", "shortContent": "常建的这首《题破山寺后禅院》曾被，宋代洪驹父誉为“全篇皆工”（《宋诗话辑佚》）。常建一生仕途失意，所以寄情山水，写了一些山水田园诗，《题破山寺后禅院》就是诗人游览名山古刹、寻幽探胜之作，也是他的代表作。\n\n破山寺又叫兴福寺，是由六朝齐代郴州刺史倪德光舍宅改建的，宋代学者朱长文《吴郡图经续记》称之“为海虞之胜处”。诗中抒写清晨游寺后禅院的观感，笔调古朴，描写省净，兴象深微，意境浑融，艺术上相当完整，...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706c9761253910e9053c", "shortContent": "常建的这首《题破山寺后禅院》曾被宋代洪驹父誉为“全篇皆工”（见《宋诗话辑佚》），这首五言律诗也是他的代表作。常建一生仕途失意，所以寄情山水，写了一些山水田园诗，《题破山寺后禅院》就是诗人游览名山古刹，寻幽探胜之作。\n\n破山寺又叫兴福寺，是由六朝齐代郴州刺史倪德光舍宅改建的，宋代学者朱长文《吴郡图经续记》称之“为海虞之胜处”。诗中抒写清晨游寺后禅院的观感，笔调古朴，描写省净，兴象深微，意境浑融，艺术...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127105c9ebcc6fbea1a464", "shortContent": "常建的这首《题破山寺后禅院》曾被宋代洪驹父誉为“全篇皆工”（见《宋诗话辑佚》），这首五言律诗也是他的代表作。常建一生仕途失意，所以寄情山水，写了一些山水田园诗。《题破山寺后禅院》就是诗人游览名山古刹，寻幽探胜之作。\n\n破山寺又叫兴福寺，是由六朝齐代郴州刺史倪德光舍宅改建的，宋代学者朱长文《吴郡图经续记》称之“为海虞之胜处”。诗中抒写清晨游寺后禅院的观感，笔调古朴，描写省净，兴象深微，意境浑融，艺术...", "authors": ["易文翔"], "pressName": "崇文书局"}]', '《洪驹父诗话》：丹阳殷璠撰《河岳英灵集》首列常建诗，爱其「山光悦鸟性，潭影空人心」之句，以为警策。欧公又爱建「竹径通幽处，禅房花木深」，欲效作数语，竟不能得，以为恨。予谓建此诗，全篇皆工，不独此两联而已。
《瀛奎律髓》：三四不必偶，乃自是一体、盖亦古诗、律诗之间。全篇自然。
《唐诗广选》：胡元瑞曰：中二联，五言律之入禅者。
《诗薮》：孟诗淡而不幽；常建「清晨入古寺」、「松际露微月」，幽矣。
《唐诗镜》：三四清韵自然。
《唐诗归》：锺云：无象有影，无影有光，是何物参之？潭云：妙极矣，注脚转语，一切难着，所谓见诗人身而为说法也。又云：清境幻思，千古不磨。
《唐诗选脉会通评林》：陆钿曰：读此诗，何必发禅家大藏，可当了心片偈，更妙在镜花水月。
《唐风定》：诗家幽境，常尉臻极，此犹是其古体也。
《唐律消夏录》：（增）「曲径」、「禅房」二句深为欧阳公所慕，免屡拟不慊。吾意未若刘君之「时有落花至，远随流水香」为尤妙也。
《唐诗归折衷》：吴敬夫云：自济北集粗豪之语以为初盛，而竟陵以空幻矫之，引人入魔。如「山光悦鸟性，潭影空人心」，吟咏之家奉为金科玉律矣，不知诗贵深细，不贵粗豪，贵真实，不贵空幻。若悟二家无有是处，即已得是处矣。
《唐诗摘钞》：全篇直叙。对一二，不对三四，名换柱对。有右丞《香积寺》之摹写，而神情高古过之；有拾遗《奉先寺》之超悟，而意象浑融过之。「薄暮空潭曲、安禅制毒龙」、「欲觉闻晨鐘，令人发深省」，方之此结，工力存馀，天然则远矣。
《历代诗发》：解人为诗，不横作诗之见于胸，随所感触写来，自然超妙，读此益信。
《唐诗绪笺》：五六写一时佳景，澄潭莹净，万象森罗。「影」字下得妙，形容心体妙明，无如此语。
《唐诗成法》：但写幽情，不着一赞羡语，而赞羡已到十分。次写景真，句法又活。
《而庵说唐诗》：「山光」二句，其气力全注射到合处也。此诗人皆称其中二联，而忽起合，何异拾却仙人，而反为扇所障也？
《唐贤三昧集笺注》：欧阳公极赏此作，自以生平未能为。此即「唐无文章，惟《盘谷序》」之意。
《闻鹤轩初盛唐近体读本》：评：幽人逸笔，自是一种。三四逸，第六峭，前四一气转旋，不为律缚，结更悠然，
《瀛奎律髓汇评》：冯班：字字人神。纪昀：通体谐律，何得云古诗、律诗之间？然前八句不对之律诗，皆谓之古诗矣。兴象深微，笔笔超妙，此为神来之候。「自然」二字不足以尽之。
《唐诗别裁》：鸟性之悦，悦以山光；人心之空，空因潭水：此倒装句法。通体幽绝。
《历代诗话》：劈头劈脑喝出「清晨」两字，次句云「初日照高林」，接得有力。竹与花木，皆从「高林」带出，而映之以「初日」，虽欲不幽且深，不可得也。此际声闻、色象、种种销灭，惟有一寺，与入寺者同摄入光影中。佛性、人性、鸟性，无动不静，无静不一，故结言「万籁此俱寂」。昔人所以美旦气、快朝气来也。自始至尾，总是「清晨」两字，安得不为一篇尽善！', 'center', 1414922766, '57b8feb6a633bd00665d3eb0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10448, '念奴娇', NULL, 120, 124, 2, 1, '施耐庵', NULL, 10333, '57b9ebb3a633bd005d30998b', '明', 'ci', '词', 'http://baike.baidu.com/view/8033040.htm', '', '天南地北，问乾坤，何处可容狂客？借得山东烟水寨，来买凤城春色。翠袖围香，绛绡笼雪，一笑千金值。神仙体态，薄幸如何消得？
想芦叶滩头，蓼花汀畔，皓月空凝碧。六六雁行连八九，只待金鸡消息。义胆包天，忠肝盖地，四海无人识。离愁万种，醉乡一夜头白。', '小说《水浒传》第七十二回《柴进簪花入禁院，李逵元夜闹东京》中，浪子燕青引宋江再次见到名妓李师师，李师师以酒食款待他们。席间，李师师低唱苏东坡《念奴娇·赤壁怀古》词，宋江乘着酒兴，填写了这首词，呈给李师师。
该词上片前面四句描述了宋江自己曾为世道所不容纳，竟然到了无处安身的地步，后来投奔了梁山，做了梁山泊的寨主，现在来到东京，观赏灯景。接着后面的五句，笔锋转向李师师，表述了宋江对这位名妓的倾慕之情。先是描述了李师师的衣着服饰，“翠袖围香，绛绡笼雪”，衣袖散发着淡淡的香气，红色绢纱里笼罩着的是如雪的洁白肌肤。面对这样一位佳丽，是值得掷干金来买她的一笑的。像这样美如仙女的人，是薄幸的男人无缘消受的。
这首词下片前面的五句，回述了宋江身在梁山水泊的寂寞情怀，色沉雁杳，日夜盼望朝廷降旨招安的消息。结尾五句描述了他满怀忠义之心，却不能够被理解，为此常只能是借酒浇愁，把头发都愁白了。宋江这一次冒险来到东京观赏花灯的真实目的便是设法打通关系，想要通过名妓李师师能让宋徽宗体察到他宋江的”忠肝义胆”，殷切希望朝廷能够对梁山水泊的起义军进行招安。这首词集中披露了宋江投奔梁山只是暂时栖身，最终将投降朝廷的用心。', '天南地北：指代普天之下。
狂客：狂放不羁之人。此处为宋江自谦之词。
山东烟水寨：指梁山泊。
凤城：旧时京都的别称，谓帝王所居之城。
翠袖：青绿色衣袖，泛指女人的装束。
绛绡：红色绡绢。雪：比喻李师师洁白的肌肤。
一笑千金值：值得千金买一笑。
神仙体态：意谓美如仙女。
薄幸如何消得：薄幸，薄情；负心。消得：消受得了。
芦叶滩头，蓼（liǎo）花汀畔：指梁山水泊。
六六：六六三十六，暗指天罡星数，八九七十二，暗指地煞星数。
金鸡消息：黄鸡报晓的声音。指朝廷招安。
四海：泛指天下。
醉乡：喝醉酒时神志迷离的状态。', '普天之下，请问这个世界，什么地方可以使我容身？暂栖身在水泊梁山，今日来观赏京城之春。翠绿的衣袖散发着香气，红色的绡绢笼罩着洁白的肌肤，真是一笑值千金，美如仙女的体态，与薄情人没有缘份。
想那芦叶萧萧的滩头，开满蓼花的岸边，纵然有月色如水如银。鱼在水中雁飞天上，只盼金鸡报晓的佳音。虽有包天的义胆，盖地的忠肝，有谁能理解我的心。满怀的离愁千万种，醉乡里一夜霜染双鬓。', NULL, '', 'indent', 1415637377, '57b8e9b51532bc005b9a82d1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10449, '无题', NULL, 300, 603, 2, 3, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/view/1738765.htm', '', '飒飒东风细雨来，芙蓉塘外有轻雷。
金蟾啮锁烧香入，玉虎牵丝汲井回。
贾氏窥帘韩掾少，宓妃留枕魏王才。
春心莫共花争发，一寸相思一寸灰。', '这首《无题》抒写了一位幽闺中的女子对爱情热切的追求和失意的痛苦。首联以凄惘弥蒙的春景衬托女子的痛苦与惆怅，颔联通过具体的环境和动作，表现了这位女子怅然若失之情，颈联通过历史典故寄予了她对英俊潇洒、才华横溢的男子的倾慕相思。末联终于迸发出女子内心的郁积与悲愤不平，「一寸相思一寸灰」一句，化抽象为具象，化平淡为神奇，用强烈对照显示了美好事物的毁灭，使全诗具有一种动人心魄的悲剧美。这一句也是千古名句，这是深锁幽闺、渴望爱情的女主人公相思无望地呐喊，诗中的痛苦，也正是诗人无法实现理想的绝望心情的流露。', '芙蓉塘：荷塘。轻雷：司马相如《长门赋》：「雷殷殷而响起兮，声像君之车音。」起二句以风、雨、雷等景物起兴，烘托女子怀人之情。
金蟾：金蛤蟆。古时在锁头上的装饰。
啮：齩。
玉虎：用玉石作装饰的井上辘轳，形如虎状。
丝：指井索。
贾氏：西晋贾充之次女。她在门帘后窥见韩寿，爱悦他年少俊美，两人私通。贾氏以皇帝赐贾充的异香赠寿，被贾充发觉，遂以女嫁给韩寿。
韩掾：指韩寿。韩曾为贾充的掾属。
宓（fú）妃留枕：唐·李善注曹子建《洛神赋》引《汉书音义》：「如淳曰：宓妃，伏羲女，溺死洛水，遂为洛水之神。」《记》曰：「魏东阿王，汉末求甄逸女，既不遂。太祖回与五官中郎将。植殊不平，昼思夜想，废寝与食。黄初中入朝，帝示植甄后玉镂金带枕，植见之，不觉泣。时已为郭后谗死。帝意亦寻悟，因令太子留宴饮，仍以枕赉植。植还，度轘辕，少许时，将息洛水上，思甄后。忽见女来，自云：『我本托心君王，其心不遂。此枕是我在家时从嫁前与五官中郎将，今与君王。遂用荐枕席，欢情交集，岂常辞能具。为郭后以糠塞口，今被发，羞将此形貌重睹君王尔！』言讫，遂不复见所在。遣人献珠于王，王答以玉珮，悲喜不能自胜，遂作《感甄赋》。后明帝见之，改为《洛神赋》。」
魏王：指魏东阿王曹植。
春心：指相思之情。', '飒飒的东风吹来阵阵的细雨，阵阵轻雷响彻荷花池塘内外。
从金蟾的炉内飘出缕缕清香，转动玉虎辘轳可以汲上饮水。
贾氏隔帘偷窥韩寿英俊年少，宓妃遗赠玉枕钦慕曹植文采。
爱情的种子不要和春花开放，寸寸相思只会化成寸寸尘灰。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dd03048e64fbd9167e", "shortContent": "这首无题写一位深锁幽闺的女子追求爱情而失望的痛苦，是一篇“刻意伤春”之作。\n首联描绘环境气氛：飒飒东风，飘来细雨；芙蓉塘外，传来阵阵轻雷。这里，既隐隐传出生命萌动的春天气息，又带有一些凄迷黯淡的色调，烘托出女主人公正在萌发跃动的春心和难以名状的迷惘苦闷。这种“象外之致”，和诗歌语言的富于暗示性有密切关系。“东风细雨”，会使人自然联想起“梦雨”的典故和“东风飘兮神灵雨，留灵脩兮憺忘归”（《楚辞·...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d80e6f69b71e93f5f87", "shortContent": "其一\n第一首是一别无会的失恋的诗。首联谓所思之人有约不来，去无消息，使我梦绕魂牵；醒后惟见残月，惟闻晨钟，天已明矣。次联上句追忆梦中情景，因远别而痛哭，泣不成声，唤她不应；下句谓醒后因强烈思念而匆忙写成情书，以至于墨犹未浓。三联谓室中“蜡照半笼”、“麝熏微度”，皆是为伊人到来所作的准备，可这一切徒劳无用，反成为对自己的嘲讽。末联谓本恨咫尺天涯，如今伊人远去，永无会期，令人抱恨无穷。\n\n其二\n第二首...", "authors": [], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64631ef9e49f46528a9eaa38", "shortContent": "这首无题写一位深锁幽闺的女子追求爱情而失望的痛苦，是一篇“刻意伤春”之作。\n\n首联描绘环境气氛：飒飒东风，飘来濛濛细雨；芙蓉塘外，传来阵阵轻雷。这里，既隐隐传出生命萌动的春天气息，又带有一些凄迷黯淡的色调，烘托出女主人公正在萌发跃动的春心和难以名状的迷惘苦闷。这种“象外之致”，和诗歌语言的富于暗示性有密切关系。“东风细雨”，会使人自然联想起“梦雨”的典故和“东风飘兮神灵雨，留灵脩兮憺忘归”（《楚辞...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '《唐诗鼓吹注解》：末则如怨诉，相思之至，反言之而情愈深矣。
《李义山诗集笺注》：朱鹤龄云：窥帘留枕，春心之摇荡极矣。迨乎香消梦断，丝尽泪乾，情焰炽然，终归灰灭。不至此，不知有情之皆幻也。乐天《和微之梦游诗序》谓：「曲尽其妄，周知其非，然后返乎真，归乎实。」义山诗即此义，不得但以艳语目之。
《玉溪生诗意》：一二时景，三四当此时而汲井方问、烧香始入。五六即从三四托下，于是帘窥韩掾，枕留宓妃，须臾之间，不可复得。故七八以春心莫发自解自叹，而情更深矣。
《重订李义山诗集笺注》：程梦星曰：第二首言幕中，盖作此寂寂之叹。起二句言雷雨飘潇，秋花冷落，以兴起无聊之景。三四言晨入暮归情况，晓则伺门扃焚香而入，晚则见辘轳汲井而归，盖终日如是也。五六似指当时官奴而言，谓窥帘贾女，留枕宓妃，邂迩之间，亦尝相遇。七八「春心」字、「相思」字紧接上联，然发乎情、止乎礼义，不得不自戒饬如香山所谓「少日为名多检束」者，故曰「莫发」，曰「心灰」也。
《唐诗笺注》：东风细雨，讫其时也；塘上轻雷，言其来也。
《玉溪生诗说》：起二句妙有远神，不可理解而可以意喻……「贾氏窥帘」以韩掾之少，「宓纪留枕」以魏王之才，自顾生平，岂复有分及此，故曰「春心莫共花争发，一寸相思一寸灰」，此四句是一提一落也。四首皆寓言也。此作较有蕴味，气体亦不堕卑琐。
《唐诗三百首》：锁虽固，香犹可入；井虽深，汲犹可出（「金蟾啮锁」一联下）。
《养一斋诗话》：自来咏雷电诗，皆壮伟有馀，轻婉不足，未免狰狞可畏。……李义山「飒飒东风细雨来，芙蓉塘外有轻雷」，最耐讽玩。', 'center', 1415638947, '57b8fd8679bc44005b9e85a4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10450, '怨情', NULL, 594, 1052, 1, 2, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/143094/14677306.htm', '', '美人卷珠帘，深坐颦蛾眉。
但见泪痕湿，不知心恨谁。', '这首小诗抒写一位美人的幽怨，不直截了当地写怨，而只作美人神态的描绘：含颦独坐、泪痕满面，却表现出了她心中深深的愁恨。', '卷珠帘：意指其卷帘相望。
珠帘：珠串的帷帘。
深坐：长久的坐。
颦（pín）：皱眉。一作“蹙”。
蛾眉：蚕蛾触须弯而细长，故以称女子之眉。《诗·硕人》：“螓首蛾眉。”', '美人卷起珠帘，
深闺独坐还皱着蛾眉。
只见玉颜上泪痕斑斑，
不知她心里究竟抱怨的是谁。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e90392", "shortContent": "这是一首五言闺怨诗，全诗着重在“怨”字。由“怨”而深坐，“怨”而蹙眉，到“怨”而流泪，层层递进，层层深化。通过描写闺中妇人独自一人在房里的动作、神态，诗人以简洁的语言，刻画出了弃妇幽怨的情态。语言平浅简易，情态缠绵凄凉，含蓄蕴藉，言短意长。明代许学夷更是在《诗源辨体》中评价道：“五言绝，太白、摩诘多入于圣矣。”可见这首诗精妙入圣。\n\n诗的第一、二句写美人独坐闺房，卷着珠帘，蹙着眉头，望向离人去的方...", "authors": ["林锦萍"], "pressName": "崇文书局"}]', '', 'center', 1415648113, '57b9109adf0eea0063355e70', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (489385, '忆古城柿', NULL, 1, 942, 0, 1, '洪适', NULL, 29307, '5858f6ce570c350069182833', '宋', 'shi', '诗', NULL, NULL, '果园幽僻少能知，丹柿乌椑手自移。
欲学郑虔书坠叶，何人解有寄来时。', NULL, NULL, NULL, NULL, NULL, 'center', 1525432618, '585fa02c128fe10069db5519', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10451, '山中问答', NULL, 704, 1052, 2, 2, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/486122/6810029.htm', '', '问余何意栖碧山，笑而不答心自闲。
桃花流水窅然去，别有天地非人间。', '这是一首古绝，以问答形式抒发作者隐居生活的自在天然的情趣。全诗虽然只有四句，但是有问、有答，有叙述、有描绘、有议论。诗境似近而实远，诗情似淡而实浓。用笔有虚有实，实处形象可感，虚处一触即止，虚实对比，蕴意幽邃。语言质朴自然，格调悠然舒缓。', '
何意：一作「何事」。
栖：居住。
碧山：山名，在湖北省安陆市内，山下桃花洞是李白读书处。一说碧山指山色的青翠苍绿。
自闲：悠闲自得。闲，安然、泰然。三国魏·曹子建《杂诗》之五：「烈士多悲心，小人媮自闲。」
窅（yǎo）然：指幽深遥远的样子。《庄子·知北游》：「夫道，窅然难言哉！将为汝言其崖略。」
「桃花流水窅然去」句：晋陶渊明《桃花源记》载，东晋时，武陵有一渔人在溪中捕鱼。忽进桃花林，林尽处有山。山有小口。从山口进去，遇一与外界隔绝的桃花源，里边的人过着安居乐业的生活。此句暗用其事。
别有天地：另有一种境界。别，另外。唐·段柯古《酉阳杂俎·诺皋记下》：「抑知厚地之下，别有天地也。」
非人间：不是人间，这里指诗人的隐居生活。', '有人疑惑不解地问我，为何幽居碧山？我只笑而不答，心里却一片轻松坦然。
桃花飘落溪水，随之远远流去。此处别有天地，真如仙境一般。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929fc6e67846a920ea48", "shortContent": "这是一首诗意淡远的七言绝句。\n诗的前两句“问余何意栖碧山，笑而不答心自闲”，前句起得突兀，后句接得迷离。这首诗的诗题一作《山中答俗人》，那么“问”的主语即所谓“俗人”；“余”，诗人自指；“何意”，一作“何事”。“碧山”即指山色的青翠苍绿。诗以提问的形式领起，突出题旨，唤起读者的注意，当人们正要倾听答案时，诗人笔锋却故意一晃，“笑而不答”。“笑”字值得玩味，它不仅表现出诗人喜悦而矜持的神态，造成了轻...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "64675f5de49f46528ab10bb7", "shortContent": "是一首诗意淡远的七言绝句。\n\n诗的前两句“问余何意栖碧山，笑而不答心自闲”，前句起得突兀，后句接得迷离。这首诗的诗题一作《山中答俗人》，那么“问”的主语即所谓“俗人”;“余”，诗人自指；“何意”，一作“何事”。“碧山”即指山色的青翠苍绿。诗以提问的形式领起，突出题旨，唤起读者的注意，当人们正要倾听答案时，诗人笔锋却故意一晃，“笑而不答”。“笑”字值得玩味，它不仅表现出诗人喜悦而矜持的神态，造成了轻...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}]', '《诚斋诗话》：「问余何意栖碧山……」，又「相随遥遥访赤城，三十六曲水回萦。一溪初入千花明，万壑度尽松风声」，此李太白诗体也。
《麓堂诗话》：诗贵意，意贵远不贵近，贵淡不贵浓；浓而近者易识，淡时远者难知。如杜子美「钩帘宿鹭起，丸药流莺啭」、「不通姓字祖豪甚，指点银瓶索酒尝」、「衔泥点涴琴书内，更接飞虫打著人」，李太白「桃花流水杳然去，别有天地非人间」，王摩诘「返景入深林，复照青苔上」，皆淡而愈浓，近而愈远，可与知者道，难与俗人言。
《唐诗选脉会通评林》：周珽曰：随心趁口，不经思维，苍词古意，自成天籁。非谪仙人何得此不食烟火语！
《唐诗摘钞》：此绝句中拗体，三、四只当「心自闲」三字注脚，究竟不曾答其所以。栖山原非本怀，然难为俗人道，故立言如此。
《古唐诗合解》：此诗信手拈来，字字入化，无段落可寻，特可会其意，而不可拘其辞也。
《而庵说唐诗》：此诗纯是化机。白作此诗，如世尊拈花；人读此诗，当如迦叶微笑。不可说，亦不必说。
《唐宋诗醇》：自是君身有仙骨，世人那得知其故。许顗曰：贺知章呼太白为「谪仙人」，余观此诗信之矣。
《雨村诗话》：李诗本陶渊明，杜诗本庾子山，余尝持此论，而人多疑之。杜本庾，信矣；李与陶，似绝不相近。不知善读古人书，在观其神与气之间，不在区区形迹也，如「问余何事栖碧山……」，岂非《桃源记》搨本乎？
《湘绮楼说诗》：「为政心闲物自闲，朝看飞鸟暮飞还。寄书河上神明宰，羡尔城头姑射山」，此篇超妙，为绝句上乘。所谓「羚羊挂角，不著一字」者也。欲知其超，但看太白诗「问余何事栖碧山」一首，世所谓仙才者，与此相比，觉李诗有意作态，不免村气。李选字皆妍丽，此则拉杂，如「神明宰」等字，比之「桃花流水」等字雅俗相远，而俗者反雅，雅者反俗，何耶？', 'center', 1415648251, '57b8dd1379bc44005b9de671', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10452, '滞雨', NULL, 193, 603, 1, 2, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/view/2296852.htm', '', '滞雨长安夜，残灯独客愁。
故乡云水地，归梦不宜秋。', '这是一首羁旅诗，“独在异乡为异客”，孤单寂寞的处境本就容易滋生乡愁，更何况还是在秋雨绵绵的深夜？归思难收，归期无定，归梦不宜，难道，这一切都是因为“滞雨”的缘故吗？首句“滞雨长安夜”交代时间地点和缘由。将“滞”字提前，不仅更能体现雨下得久，还能突出夜的漫长，好像是厚实、缠绵的雨连时间的脚步也阻碍了，迟迟不能到黎明。归心似箭，但偏偏又碰上似乎永无休止的连夜雨，给人一种无法排遣的无奈、凝重之感。也为后面的“客愁”、“归梦”蓄势。
“残灯独客愁”描写场景：一盏灯油将尽的孤灯之下，坐着一个满脸愁容的独客。“残灯”，不仅不能给人以光明、温暖的感觉，与外面无尽的雨夜相比，它反而更让人觉得凄凉、忧伤。灯已残，说明独坐已久；独坐久，说明客难眠；客难眠，说明乡愁深。“残灯独客”与前面的“滞雨夜”共同营造出一种朦胧迷离、孤寂凄清的氛围，在这样的意境下，游子很自然会想到自己的故乡。
“故乡云水地”是虚写，是故乡在云水相接的苍茫辽阔之地吗？是故乡有云重水复遥远的阻隔吗？还是故乡根本就不存在于现实，而只在自己如行云流水般飘渺的乡思中吗？这一句体现了诗人特有的朦胧性，怎么理解似乎都可以，怎么理解都给人一种真实而亲切的感受。
“归梦不宜秋”是直抒感慨，语似直切，实则含蓄。雨夜客居，残灯独坐，正是思乡梦回的“好”时候，为什么“不宜秋”呢？因为在诗人眼中，秋就是愁，秋风秋雨秋云秋水……无一不令诗人愁肠百结，在满目愁景的季节，在满怀愁绪的梦中，即使回到故乡，还不是一样愁苦？算了吧，不做归乡梦也罢！其实，这样的梦，在任何季节做都是“不宜”的。诗人在此说“不宜”，其实是“最宜”，有正话反说、不言神伤之妙。', '', '', '[{"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d7ff2af4e09d55b63b8", "shortContent": "一二句谓诗人客居长安，因天雨而行动受阻，独对残灯忧愁不寐，思念故乡。三四句推进一层，谓故乡本是烟树晴岚、碧水萦回之地，可是现在正值秋雨绵绵之时，即使梦魂回归故里，所见也是霪雨霏霏，令人抑郁烦忧，故归梦亦不宜当此风雨潇潇之秋时也。义山乃失意之人，好梦无多。小诗曲折有致，自成高格。yu", "authors": [], "pressName": "崇文书局"}]', '', 'center', 1415648788, '57b90ff5128fe10054ca068d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10453, '喜见外弟又言别', NULL, 290, 166, 3, 3, '李益', NULL, 10112, '57b9bd658ac2470063ff0efa', '唐', 'shi', '诗', 'http://baike.baidu.com/view/160881.htm', '', '十年离乱后，长大一相逢。
问姓惊初见，称名忆旧容。
别来沧海事，语罢暮天钟。
明日巴陵道，秋山又几重。', '此诗描写了诗人同表弟在乱离中不期而遇而又匆匆话别的伤感场面，抒发了真挚的至亲情谊和人生聚散离合无定的感慨，从侧面反映了动乱给人们带来的痛苦。全诗用凝炼的语言、白描的手法、生动的细节、典型的场景，层次分明地再现了社会动乱中人生聚散的独特一幕，具有强烈的生活真实感。', '外弟：表弟。言别：话别。
十年离乱：在社会大动乱中离别了十年。离乱，一作“乱离”。
一：副词。可作“竟然”或“忽而”解。
“问姓惊初见，称名忆旧容”句：“问姓”与“称名”互文见义。
别来：指分别十年以来。来，后也。
沧海事：比喻世事的巨大变化，有如沧海变桑田，桑田变沧海那样。
语罢：谈话停止。
暮天钟：黄昏寺院的鸣钟。
巴陵：即岳州（治今湖南省岳阳市），即诗中外弟将去的地方。', '战乱之中离别，屈指算来十年。如今一朝相逢，表弟已经成人。
问姓顿感惊喜亲切，道名忆及儿时面容。
别后有多少世事变迁要说？直说到黄昏传来阵阵晚钟。
明天又要踏上西去巴陵的征途，你我之间又要相隔多少重秋山？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ba03048e64fbd9144e", "shortContent": "这首诗艺术地再现了诗人同表弟（外弟）久别重逢又匆匆话别的情景。在以人生聚散为题材的小诗中，它历来引人注目。\n“十年离乱后，长大一相逢”，开门见山，介绍二人相逢的背景。这里有三层意思：一是指出离别已有十年之久。二是说明这是社会动乱中的离别。它使人想起，发生于李益八岁到十六岁时的安史之乱及其后的藩镇混战、外族入侵等战乱。三是说二人分手于幼年，“长大”才会面，这意味着双方的容貌已有极大变化。他们长期音信...", "authors": ["范之麟"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a94", "shortContent": "这首诗艺术地再现了诗人同表弟（外弟）久别重逢又匆匆话别的情景。在以人生聚散为题材的小诗中，它历来引人注目。\n\n“十年离乱后，长大一相逢”，开门见山，介绍二人相逢的背景。这里有三层意思：一是指出离别已有十年之久。二是说明这是社会动乱中的离别。它使人想起，发生于李益八岁到十六岁时的安史之乱及其后的藩镇混战、外族入侵等战乱。三是说二人分手于幼年，“长大”才会面，这意味着双方的容貌已有极大变化。他们长期音...", "authors": ["范之麟"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f0932f", "shortContent": "该诗首联介绍相逢的背景。由于安史之乱及其后的藩镇混战、外族入侵等战乱，诗人在年幼时就与表弟分散，音信全无，生死未卜。“一”字反映出诗人与表弟是突然邂逅、意外相逢。颔联正面描写重逢场面。相遇时，这对表兄弟竟然变成了对面不相识的陌生人。待报过姓名之后，诗人才惊讶地发现面前的这位陌生人，原来就是幼时一起嬉戏玩耍的表弟。诗人一边激动地称呼表弟的名字，一边努力回忆有关表弟的印象。“问”、“称”、“惊”、“忆...", "authors": ["陈鹏"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706a73206168b2e02205", "shortContent": "该诗首联介绍相逢的背景。由于安史之乱及其后的藩镇混战、外族入侵等战乱，诗人在年幼时就与表弟分散，音信全无，生死未卜。“一”字反映出诗人与表弟是突然邂逅、意外相逢。颔联正面描写重逢场面。相遇时，这对表兄弟竟然变成了对面不相识的陌生人。待报过姓名之后，诗人才惊讶地发现面前的这位陌生人，原来就是幼时一起嬉戏玩耍的表弟。诗人一边激动地称呼表弟的名字，一边努力回忆有关表弟的印象。“问”、“称”、“惊”、“忆...", "authors": ["陈鹏"], "pressName": "崇文书局"}]', '《对床夜语》：“马上相逢久，人中欲认难”，“问姓惊初见，称名忆旧容”，“乍见翻疑梦，相悲各问年”，皆诗人会故人诗也。久别倏逢之意，宛然在目，想而味之，情融神会，殆如直述。前辈谓唐人行旅聚散之作，最能感动人意，信非虚语。
《诗镜总论》：盛唐人工于缀景，惟杜子美长于言情。人情向外，见物易时自见难也。司空曙“乍见翻疑梦，想悲各问年”，李益“问姓惊初见，称名识旧容”，抚衷述怀，罄快极矣。因之思《三百篇》，情绪如丝，绎之不尽，汉人曾道只字不得。
《载酒园诗话又编》：司空文明每作得一联好语，辄力人压占。如“乍见翻疑梦，相悲各问年”，可谓情至之语；李益曰：“问姓惊初见，称名忆旧容”，则情尤深，语尤怆，读之几于泪不能收。
《唐诗别裁》：一气旋折，中唐诗中仅见者。
《网师园唐诗笺》：形容刻至（“问姓”二句下）。', 'center', 1415649070, '57b901a3165abd0054bfd530', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10454, '江南春', NULL, 1241, 501, 1, 12, '杜牧', NULL, 10109, '57b9836cc4c971005593dfec', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/56301/7821530.htm', '', '千里莺啼绿映红，水村山郭酒旗风。
南朝四百八十寺，多少楼台烟雨中。', '此诗是唐代诗人杜牧的一首七言绝句，诗中不仅描绘了明媚的江南春光，而且还再现了江南烟雨蒙蒙的楼台景色，使江南风光更加神奇迷离，别有一番情趣。迷人的江南，经过诗人生花妙笔的点染，显得更加令人心旌摇荡了。
这首诗四句均为景语，有众多意象和景物，有植物有动物，有声有色，景物也有远近之分，动静结合，各具特色。以轻快的文字，极具概括性的语言描绘了一幅生动形象、丰富多彩而又有气魄的江南春画卷，呈现出一种深邃幽美的意境，表达出一缕缕含蓄深蕴的情思，千百年来素负盛誉。', '莺啼：即莺啼燕语。
郭：外城。此处指城镇。
酒旗：一种挂在门前以作为酒店标记的小旗。
南朝：指先后与北朝对峙的宋、齐、梁、陈政权。
四百八十寺：南朝皇帝和大官僚好佛，在京城（今南京市）大建佛寺。据《南史·循吏·郭祖深传》说：“都下佛寺五百余所”。这里说四百八十寺，是虚数。
楼台：楼阁亭台。此处指寺院建筑。
烟雨：细雨蒙蒙，如烟如雾。', '千里江南，到处莺歌燕舞，有相互映衬的绿树红花，有临水的村庄，有依山的城郭，到处都有迎风招展的酒旗。昔日到处是香烟缭绕的深邃的寺庙，如今亭台楼阁都沧桑矗立在朦胧的烟雨之中。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d734a8757d5a0e1e17", "shortContent": "这首《江南春》，千百年来素负盛誉。四句诗，既写出了江南春景的丰富多彩，也写出了它的广阔、深邃和迷离。\n“千里莺啼绿映红，水村山郭酒旗风。”诗一开头，就像迅速移动的电影镜头，掠过南国大地：辽阔的千里江南，黄莺在欢乐地歌唱，丛丛绿树映着簇簇红花；傍水的村庄，依山的城郭，迎风招展的酒旗，一一在望。迷人的江南，经过诗人生花妙笔的点染，显得更加令人心旌摇荡了。摇荡的原因，除了景物的繁丽外，恐怕还由于这种繁丽...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389aecdc25963feee1ab3", "shortContent": "这首《江南春》，千百年来素负盛誉。四句诗，既写出了江南春景的丰富多彩，也写出了它的广阔、深邃和迷离。\n\n“千里莺啼绿映红，水村山郭酒旗风。”诗一开头，就像迅速移动的电影镜头，掠过南国大地：辽阔的千里江南，黄莺在欢乐地歌唱，丛丛绿树映着簇簇红花；傍水的村庄，依山的城郭，迎风招展的酒旗，一一在望。迷人的江南，经过诗人生花妙笔的点染，显得更加令人心旌摇荡了。摇荡的原因，除了景物的繁丽外，恐怕还由于这种繁...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270789761253910e9055a", "shortContent": "《江南春绝句》是一首借景抒情的诗，只有结合作者的生平思想和当时的背景来读，才能真正理解。\n\n杜牧入仕前期，曾在洪、宣、扬州幕府供职多年。后期出任黄、池、睦、湖等州刺史，又历时十余年。这些州多数地处江南，这就使得这位才情横溢的北方诗人对江南的风物有深切的体验。诗人积极用世，关心时事和民生，除对政治、军事、经济有不少卓越见解外，在思想上排佛最为坚决。而在他入仕后的三十年间，正是文宗、武宗、宣宗三位皇帝...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312713f73206168b2e022e0", "shortContent": "《江南春绝句》是一首借景抒情的诗，只有结合作者的生平思想和当时的背景来读，才能真正理解。\n杜牧入仕前期，曾在洪、宣、扬州幕府供职多年。后期出任黄、池、睦、湖等州刺史，又历时十余年。这些州多数地处江南，这就使得这位才情横溢的北方诗人对江南的风物有深切的体验。诗人积极用世，关心时事和民生，除对政治、军事、经济有不少卓越见解外，在思想上排佛最为坚决。而在他入仕后的三十年间，正是文宗、武宗、宣宗三位皇帝围...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "645d0ac98258810260dbe044", "bookTitle": "杜牧诗文鉴赏辞典", "articleId": "646199f87da2f75ac7da8ba5", "shortContent": "这首《江南春》，千百年来素负盛誉。四句诗，既写出了江南春景的丰富多彩，也写出了它的广阔、深邃和迷离。\n\n“千里莺啼绿映红，水村山郭酒旗风。”诗一开头，就像迅速移动的电影镜头，掠过南国大地：辽阔的千里江南，黄莺在欢乐地歌唱，丛丛绿树映着簇簇红花；傍水的村庄，依山的城郭，迎风招展的酒旗，一一在望。迷人的江南，经过诗人生花妙笔的点染，显得更加令人心旌摇荡了。摇荡的原因，除了景物的繁丽外，恐怕还由于这种繁...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471a2a7a5f1e74f9585fd61", "shortContent": "这首《江南春》，千百年来素负盛誉。四句诗，既写出了江南春景的丰富多彩，也写出了它的广阔、深邃和迷离。\n“千里莺啼绿映红，水村山郭酒旗风。”诗一开头，就像迅速移动的电影镜头，掠过南国大地：辽阔的千里江南，黄莺在欢乐地歌唱，丛丛绿树映着簇簇红花；傍水的村庄，依山的城郭，迎风招展的酒旗，一一在望。迷人的江南，经过诗人生花妙笔的点染，显得更加令人心旌摇荡了。摇荡的原因，除了景物的繁丽外，恐怕还由于这种繁丽...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "645fc22c5e6bb82b8caff682", "bookTitle": "历代咏春诗鉴赏：春江花月夜", "articleId": "6472f88c82772d45942b6048", "shortContent": "这首《江南春》，千百年来素负盛誉。四句诗，既写出了江南春景的丰富多彩，也写出了它的广阔、深邃和迷离。\n\n“千里莺啼绿映红，水村山郭酒旗风。”诗一开头，就像迅速移动的电影镜头，掠过南国大地：辽阔的千里江南，黄莺在欢乐地歌唱，丛丛绿树映着簇簇红花；傍水的村庄、依山的城郭、迎风招展的酒旗，一一在望。迷人的江南，经过诗人生花妙笔的点染，显得更加令人心旌摇荡了。摇荡的原因，除了景物的繁丽外，恐怕还由于这种繁...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}]', '宋·张表臣《珊瑚钩诗话》：杜牧诗云：“南朝四百八十寺，多少楼台烟雨中。”帝王所都而四百八十寺，当时已为多，而诗人侈其楼阁台殿焉。
明·杨慎《升庵诗话》：“千里莺啼”，谁人听得？千里“绿映红”，谁人见得？若作“十里”，则莺啼绿红之景，村郭、楼台、僧寺、酒旗皆在其中矣。
明·周珽《唐诗选脉会通评林》：为实接体。小李将军画山水人物，色色争岍，真好一幅江南春景图。大抵牧之好用数目字。如“南朝四百八十寺”、“二十四桥明月夜”、“故乡七十五长亭”是也。
明·胡震亨《唐音戊签》：杨用修欲改“千里”为“十里”。诗在意象耳，“千里”毕竟胜“十里”也。
清·黄生《唐诗摘钞》：曰“烟雨中”，则非真有楼台矣，感南朝遗迹之湮灭而语，特不直说。许浑亦云：“鸟下绿芜秦苑夕，蝉鸣黄叶汉宫秋。”窦牟云：“满目山阳笛里人”，言人已不存也……不曰楼台已毁，而曰“多少楼台烟雨中”，皆见立言之妙。
清·何焯《唐三体诗评》：缀以“烟雨”二字，便见春景，古人工夫细密。
清·黄周星《唐诗快》：若将此诗画作锦屏，恐十二扇铺排不尽。
清·周咏堂《唐贤小三昧集续集》：字字着色画。此种风调，樊川所独擅。
清·宋宗元《网师园唐诗笺》：江南春景，描写莫尽，能以简括，胜人多许。
清·严长明《唐人万首绝句选评》：二十八字中写出江南春景，真有吴道子于大同殿画嘉陵山水手段，更恐画不能到此耳。
清·范大士《历代诗发》：“四百八十寺”，无景不收入结句，包罗万象，真天地间惊人语也。
清·何文焕《历代诗话考索》：“千里莺啼绿映红”云云，此杜牧《江南春》诗也。升庵谓“千”应作“十”。盖“千里”已听不着、看不见矣，何所云“莺啼绿映红”耶？余谓即作“十里”，亦未必听得着、看得见。题云《江南春》，江南方广千里。千里之中，莺啼而绿映焉，水村山郭，无处无酒旗，四百八十寺，楼台多在烟雨中也。此诗之意既广，不得专指一处，故总而名曰《江南春》，诗家善立题者也。
近代·俞陛云《诗境浅说续编》：前二句言江南之景。渡江梅柳、芳信早传，袁随园诗所谓“十里烟笼村店晓，一枝风压酒旗偏”，绝妙惠崇图画也。后言南朝寺院多在山水胜处，有四百八十寺之多，况空濛烟雨之时，罨画楼台，益增佳景。小杜曾有“倚遍江南寺寺楼”句，刘梦得有“偏上南朝寺”句，可见琳宫梵宇随处皆是。
近代·刘永济《唐人绝句精华》：按杨慎之说，拘泥可笑，何文焕驳之楚也。但谓为诗家善立题，则亦浅之夫视诗人矣。盖古诗人非如后世作者先立一题，然后就题成诗，多是诗成而后立题。此诗乃杜牧游江南时，感于景物之繁丽，追想南朝盛日，遂有此作。“千里”之词，亦概括言之耳，必欲以听得着、看得见求之，岂不可笑！', 'center', 1415649356, '57b8f69b5bbb50005b77df6d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10455, '钱塘湖春行', NULL, 1437, 2952, 2, 16, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', 'http://baike.baidu.com/view/33440.htm', '', '孤山寺北贾亭西，水面初平云脚低。
几处早莺争暖树，谁家新燕啄春泥。
乱花渐欲迷人眼，浅草才能没马蹄。
最爱湖东行不足，绿杨阴里白沙堤。', '此诗是唐代诗人白居易的一首描写西湖颇具盛名的七律。此诗通过写西湖早春明媚风光的描绘，抒发了作者早春游湖的喜悦和对钱塘湖风景的喜爱，更表达了作者对于自然之美的热爱之情。尤其是中间四句，细致地描绘了西湖春行所见景物，形象活现，即景寓情，准确生动地表现了自然之物的活泼情趣和雅致闲情。全诗对仗精工，语言浅近，用词准确，气质清新，成为历代吟咏西湖的名篇。', '钱塘湖：杭州西湖的别称。因古时杭州名为钱唐，故名。後来写成「钱塘湖」。
孤山寺：在西湖白堤孤山上。
贾亭：唐代杭州刺史贾全所建的贾公亭，今已不存。
初平：远远望去，西湖水面彷彿刚和湖岸齐平。
云脚：古汉语称下垂的物象为「脚」，如下落雨丝的下部叫「雨脚」。这里指下垂的云彩。（接近地面的云气，多见于将雨或雨初停时）
暖树：向阳的树。
新燕：春时初来的燕子。
乱花：指纷繁开放的春花。
没（mò）：隐没。
湖东：以孤山为参照物，白沙堤（卽白堤）在孤山的东北面。
足：满足。
白沙堤：指西湖东面的白堤，上有断桥等名胜。', '行至孤山寺北，贾公亭西，举目远眺，但见水面涨平，白云低垂。
几只黄莺，争先飞往向阳树木；谁家燕子，为筑新巢衔来春泥？
鲜花缤纷，几乎迷人眼神；野草青青，刚好遮没马蹄。
湖东景色，令人流连忘返，最为可爱的，还是那绿杨掩映的白沙堤。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92cad635634aee3dedc6", "shortContent": "这诗是长庆三或四年（823或824）春白居易任杭州刺史时所作。\n钱塘湖是西湖的别名。提起西湖，人们就会联想到宋代苏轼诗中的名句：“欲把西湖比西子，淡妆浓抹总相宜。”（《饮湖上初晴后雨》）读了白居易这诗，仿佛真的看到了那含睇宜笑的西施的面影，更加感到东坡这比喻的确切。\n乐天在杭州时，有关湖光山色的题咏很多。这诗处处扣紧环境和季节的特征，把刚刚披上春天外衣的西湖，描绘得生意盎然，恰到好处。\n“孤山寺北...", "authors": ["马茂元"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad4797a92d5e4fd906", "shortContent": "这诗是长庆三或四年（823或824）春白居易任杭州刺史时所作。\n\n钱塘湖是西湖的别名。提起西湖，人们就会联想到宋代苏轼诗中的名句：“欲把西湖比西子，淡妆浓抹总相宜。”（《饮湖上初晴后雨》）读了白居易这诗，仿佛真的看到了那含睇宜笑的西施的面影，更加感到东坡这比喻的确切。\n\n乐天在杭州时，有关湖光山色的题咏很多。这诗处处扣紧环境和季节的特征，把刚刚披上春天外衣的西湖，描绘得生意盎然，恰到好处。\n\n“孤...", "authors": ["马茂元"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270717f0b9738b369b220", "shortContent": "《钱塘湖春行》生动地描绘了诗人早春漫步西湖所见的明媚风光，是一首唱给春日良辰和西湖美景的赞歌。\n\n诗的首联紧扣题目总写湖水。前一句点出钱塘湖的方位和四周“楼观参差”景象，两个地名连用，又给读者以动感，说明诗人是在一边走、一边观赏。后一句正面写湖光水色：春水初涨，水面与堤岸齐平，空中舒卷的白云和湖面荡漾的波澜连成一片，正是典型的江南春湖的水态天容。\n\n颔联写仰视所见禽鸟。莺在歌，燕在舞，显示出春天的...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127115e6f69b71e93f638e", "shortContent": "《钱塘湖春行》生动地描绘了诗人早春漫步西湖所见的明媚风光，是一首唱给春日良辰和西湖美景的赞歌。\n\n诗的首联紧扣题目总写湖水。前一句点出钱塘湖的方位和四周“楼观参差”景象，两个地名连用，又给读者以动感，说明诗人是在一边走、一边观赏。后一句正面写湖光水色：春水初涨，水面与堤岸齐平，空中舒卷的白云和湖面荡漾的波澜连成一片，正是典型的江南春湖的水态天容。\n\n颔联写仰视所见禽鸟。莺在歌，燕在舞，显示出春天的...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "645d09bbec56251f2eeb5b78", "bookTitle": "白居易诗文鉴赏辞典", "articleId": "6462de7830675327e180bbbd", "shortContent": "这诗是长庆三年或四年（823或824）春白居易任杭州刺史时所作。\n\n钱塘湖是西湖的别名。提起西湖，人们就会联想到宋代苏轼诗中的名句：“欲把西湖比西子，淡妆浓抹总相宜。”（《饮湖上初晴后雨》）读了白居易这诗，仿佛真的看到了那含睇宜笑的西施的面影，更加感到东坡这比喻的确切。\n\n乐天在杭州时，有关湖光山色的题咏很多。这诗处处扣紧环境和季节的特征，把刚刚披上春天外衣的西湖，描绘得生意盎然，恰到好处。\n\n“...", "authors": ["马茂元"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f88bb5420e27678f8035", "shortContent": "这诗是长庆三或四年（823或824）春白居易任杭州刺史时所作。\n钱塘湖是西湖的别名。提起西湖，人们就会联想到宋代苏轼诗中的名句：“欲把西湖比西子，淡妆浓抹总相宜。”（《饮湖上初晴后雨》）读了白居易这诗，仿佛真的看到了那含睇宜笑的西施的面影，更加感到东坡这比喻的确切。\n诗的前四句写湖上春光，范围是宽广的，它从“孤山”一句生发出来；后四句专写“湖东”景色，归结到“白沙堤”。前面先点明环境，然后写景；后...", "authors": ["马茂元"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "64733fa8a5f1e74f958c96ad", "shortContent": "这首诗是长庆三年（823）或四年（824）春白居易任杭州刺史时所作。\n\n钱塘湖是西湖的别名。提起西湖，人们就会联想到苏轼诗中的名句：“欲把西湖比西子，淡妆浓抹总相宜。”（《饮湖上初晴后雨》）读了白居易这首诗，仿佛真的看到了那含睇宜笑的西施的面影，更加感到东坡比喻的确切。\n\n乐天在杭州时，有关湖光山色的题咏很多。此诗处处扣紧环境和季节的特征，把刚披上春天外衣的西湖，描绘得生意盎然，恰到好处。\n\n“孤...", "authors": ["马茂元"], "pressName": "上海辞书出版社"}]', '金圣叹《贯华堂选批唐才子诗》：前解先写湖上。横开则为寺北亭西，竖展则为低云平水，浓点则为早莺新燕，轻烘则为暖树春泥。写湖上，真如天开图画也。後解方写春行。花迷，草没，如以戥子称量此日春光之浅深也。「绿杨阴里白沙堤」者，言于如是浅深春光中，幅巾单裕款段闲行，即此杭州太守白居士也。
王船山《唐诗评选》：大历之诗变为长庆，自如出黔中溪箐，入滇南佳地。元、白同以一往风味，流荡天下心脾，雅可以韵相赏；檃括微至，自非所长，不当以彼责此。
何义门《唐律偶评》：平平八句，自然清丽，小才不知费多少妆点。
杨逢春《唐诗绎》：首领笔，言自孤山北贾亭西行起，下五句历写绕湖行处春景，七、八以行不到之湖东结，遥望犹有馀情。
胡以梅《唐诗贯珠》：三、四灵活之极，「争」字既佳，而「谁家」更有情。
赵臣瑗《山满楼笺注唐诗七言律》：何言乎上半首专写湖上？察他口气所重，只在「寺北」、「亭西」、「几处」、「谁家」，见其间佳丽不可胜纪，而初不在「水平」、「云低」、「早莺」、「新燕」、「暖树」、「春泥」之种种布景设色也。何言乎下半首专写春行？察他口气所重，只在「渐欲迷」、「才能没」绿杨阴之一路行来，细细较量春光之浅深，春色之浓淡，而初不在「湖东」、「白沙堤」几个印板上之衬贴字也。要之，轻重既已得宜，风情又复宕漾，最是中唐佳调。谁谓先生之诗近于俗哉！
宋宗元《网师园唐诗笺》：娟秀无比。
方仪卫《昭昧詹言》：章法意匠，与前诗（按指《西湖留别》）相似，而此加变化。佳处在象中有兴，有人在，不比死句。
髙阆仙《唐宋诗举要》：方植之曰：佳处在象中有兴，有人在，不比死句。又曰：句句回旋，曲折顿挫，皆从意匠经营而出。', 'center', 1415649723, '57b992e08ac2470062e4c39a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (48422, '念奴娇 · 送幕职', NULL, 1, 656, 0, 1, '陆文圭', NULL, 11145, '5858e62eb123db00658d7b64', '元', 'ci', '词', NULL, NULL, '残花剩柳，正啼鹃声里，邮亭别馆。三叠阳关听未彻，手执离杯引满。政坐诸君，久烦老子，今日才萧散。翩然归去，故园绿树春晚。
人世苍白浮云，自舒自卷，不入高人眼。官事如麻何日了，输与闲中不管。翠柏台高，紫薇省近，别有清华选。功名岁晏，江城回首天远。', NULL, NULL, NULL, NULL, NULL, 'indent', 1512670643, '585ceda4da2f60006582f28e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10456, '浪淘沙 · 山寺夜半闻钟', NULL, 298, 793, 2, 1, '辛弃疾', NULL, 10003, '57b8ed682e958a005fa4d096', '宋', 'ci', '词', 'http://baike.baidu.com/view/3213399.htm', '', '身世酒杯中，万事皆空。古来三五个英雄。雨打风吹何处是，汉殿秦宫。
梦入少年丛，歌舞匆匆。老僧夜半误鸣钟。惊起西窗眠不得，卷地西风。', '此词当是作者后期的作品，词虽以“万事皆空”总摄全篇，实充盈家国身世之感，风格沉郁悲凉。上阕怀古，实叹喟今无英雄，秦汉盛世难再。下阕歌舞匆匆者，亦少年盛事惟梦境再现。闻钟梦觉，只西风满窗而已。', '夜半闻钟：北宋·王直方《王直方诗话·半夜钟》：“欧公言：唐人有‘姑苏城外寒山寺，夜半钟声到客船’之句，说者云：‘句则佳也，其如三更不是撞钟时！’余观于鹄《送宫人入道诗》云：‘定知别后宫中伴，遥听缑（gōu）山半夜钟。’而白乐天亦云：‘新秋松影下，半夜钟声后。’岂唐人多用此语也？傥非递相沿袭，恐必有说耳。温庭筠诗亦云：‘悠然逆旅频回首，无复松窗半夜钟。’庭筠诗多缵（zuǎn）在白乐天诗后。”
身世：平生。酒杯：借酒浇愁。
汉殿：汉代宫阙，代指刘邦。
秦宫：秦朝宫阙，代指秦始皇。
梦入：梦境。
少年丛：当谓英雄年少种种。
西窗：思念，代指抱负。
卷地：谓贴着地面迅猛向前推进。多指风。代指身世悲凉。', '整日在借酒浇愁的状态中渡过，一生的努力因没能改变国家的败局而全部成空。古今往来的英雄们本就不多，却因时间的流逝而淹没，再也难找到像刘邦、秦始皇那样的英雄。
少年繁华如梦，如今一一破灭，让人直欲遁入空门，做隐逸之士，可真正要去寻觅夜半禅钟的时候，却只有卷地的西风。', NULL, '', 'indent', 1415651611, '57b8ed750a2b58005c91c637', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10457, '自题小像', NULL, 130, 23, 1, 0, '鲁迅', NULL, 10118, '57b93fd70a2b58005c946328', '当代', 'shi', '诗', 'http://baike.baidu.com/view/652713.htm', '', '灵台无计逃神矢，风雨如磐暗故园。
寄意寒星荃不察，我以我血荐轩辕。', '此诗是现代文学家鲁迅创作的一首七言绝句。这首诗的第一句作者倾吐自己内心蓄积的爱国感情，第二句叙述自己爱憎的原因，第三句总括前两句内容，并作了转折，流露出感到「同胞未醒」的苦闷忧虑，尾句是为国献身的誓言，表达了作者同帝国主义列强斗争的决心和为国捐躯的精神。全诗诚挚恳切，雄健激昂。', '自题小像：这首诗原无题目，诗题为作者好友许寿裳在其发表的《怀旧》一文中所加。
灵台：指心，古人认为心有灵台，能容纳各种智慧，语出《庄子·庚桑楚》：「不可内（纳）于灵台」。郭象注：「灵台，心也。」在本诗应代指为国殉道的烈士。
神矢：爱神之箭。据《希腊罗马神话故事》记载：「丘比特是小爱神，也有人叫他做弓神，……他的箭有些是金子造的，箭头非常尖锐，凡是被射中的人，无不立刻就深深地发生了爱情。可是另外有一些箭，是用没有光彩的铅造成的，箭头很钝，那些被它射中的人，就只有彼此互相憎恨。」作者鲁迅在这里，是把中了爱神丘比特的神箭比喻为自己对祖国对人民的热爱和对当时帝国主义的憎恨感情。
风雨如磐：风雨，在这里指帝国主义的侵略和封建主义的统治。磐，扁而厚的大石。风雨如磐，比喻国家和民族灾难的深重。
故园：故国、祖国。
寄意寒星：语出宋玉《九辩》：「愿寄言夫流星兮」。宋玉以流星比贤人。这里的寒星从「流星」转化而来。寄意寒星，是说作者当时远在国外，想把自己一片爱国赤诚寄托天上的寒星，让它代为转达于祖国人民。
荃（quán）不察：语出屈原《离骚》：「荃不察余之衷情兮」。荃，香草名，古时比喻国君，这里借喻祖国人民。不察，不理解。
荐：奉献。
轩辕：即黄帝，是古代传说中的氏族帮落酋长。《史记》记载：中国历史，是从黄帝开始的。黄帝复姓轩辕，所以轩辕黄帝被称为汉族始祖，由此引申为「中华民族」或「中国」。', '烈士们浴血拼搏也没能挽救濒危的中国，此时信奉的神灵也没有半点作用。故国家园在战争中风雨飘摇，暗无天日。
这份情感寄托给天上的星星却没有人明了，我誓将我的一腔热血报效我的祖国。', NULL, '锺敬文：鲁迅这首七绝，是他满腔火热的忧愤和奋斗激情的表现。而这一句（我以我血荐轩辕）又是这种表现的喷火口。
茅盾：他的《自题小像》就表示了把生命献给祖国的决心。', 'center', 1415651975, '57b9017f5bbb50005b782b27', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10458, '自嘲', NULL, 310, 23, 2, 0, '鲁迅', NULL, 10118, '57b93fd70a2b58005c946328', '当代', 'shi', '诗', 'http://baike.baidu.com/view/433176.htm', '', '运交华盖欲何求，未敢翻身已碰头。
破帽遮颜过闹市，漏船载酒泛中流。
横眉冷对千夫指，俯首甘为孺子牛。
躲进小楼成一统，管他冬夏与春秋。', '此诗是现代文学家鲁迅于1932年所作的一首七言律诗。这首诗的首联写当时作者所处的险恶处境；颔联写他坚持斗争的行动；颈联写他坚持斗争的内在动力，即强烈的爱和憎；尾联写他战斗到底的决心。全诗内在逻辑性强，文字风趣，内容庄肃。', '华盖：星座名，共十六星，在五帝座上，今属仙后座。旧时迷信，以为人的命运中犯了华盖星，运气就不好。
破帽：原作“旧帽”。
漏船载酒：用《晋书·毕卓传》中的典故：“得酒满数百斛（hú）……浮酒船中，便足了一生矣。”漏船：原作“破船”。“中流：河中。
横眉：怒目而视的样子，表示愤恨和轻蔑。
孺子牛：春秋时齐景公跟儿子嬉戏，装牛趴在地上，让儿子骑在背上。这里比喻为人民大众服务，更指小孩子，意思是说鲁迅把希望寄托在小孩子身上，就是未来的希望。
成一统：意思是说，我躲进小楼，有个一统的小天下。
管他冬夏与春秋：即不管外在的气候、环境有怎样的变化。', '交了不好的运气我又能怎么办呢？想摆脱却被碰得头破血流。
破帽遮脸穿过热闹的集市，像用漏船载酒驶于水中一样危险。
横眉怒对那些丧尽天良、千夫所指的人，俯下身子甘愿为老百姓做孺子牛。
坚守自己的志向和立场永不改变，不管外面的环境发生怎样的变化。', NULL, '', 'center', 1415652087, '57b8dd49c4c97100558e67a5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10459, '狱中题壁', NULL, 135, 75, 1, 2, '谭嗣同', NULL, 10119, '57b9b93ca633bd005d2ee195', '清', 'shi', '诗', 'http://baike.baidu.com/subview/535847/11368890.htm', '', '望门投止思张俭，忍死须臾待杜根。
我自横刀向天笑，去留肝胆两昆仑。', '此诗是近代维新派政治家、思想家谭嗣同的作品，于光绪二十四年（1898年）戊戌变法失败后后作者在狱中所作，诗中表达愿为理想而英勇献身的大无畏精神。', '望门投止：望门投宿。张俭：东汉末年高平人，因弹劾宦官侯览，被反诬“结党”，被迫逃亡，在逃亡中凡接纳其投宿的人家，均不畏牵连，乐于接待。事见《后汉书·张俭传》。
忍死：装死。须臾：不长的时间。杜根：东汉末年定陵人，汉安帝时邓太后摄政、宦官专权，其上书要求太后还政，太后大怒，命人以袋装之而摔死，行刑者慕杜根为人，不用力，欲待其出宫而释之。太后疑，派人查之，见杜根眼中生蛆，乃信其死。杜根终得以脱。事见《后汉书·杜根传》。
横刀：屠刀，意谓就义。
两昆仑：有两种说法，其一是指康有为和浏阳侠客大刀王五；其二为“去”指康有为（按：康有为在戊戌政变前潜逃出京，后逃往日本），“留”指自己。', '逃亡生活是如此紧张，看到有人家就上门投宿，我希望出亡的康有为、梁启超能像张俭一样受到人们的保护。也希望战友们能如杜根一样忍死待机完成变法维新的大业。
我横刀而出，仰天大笑，因为去者和留者肝胆相照、光明磊落，有如昆仑山一样的雄伟气魄。', '[{"bookId": "60d939cea06dc908f045ad24", "bookTitle": "元明清诗鉴赏辞典（新一版）", "articleId": "610e8d2edbb8b379ee094428", "shortContent": "谭嗣同是近代史上维新变法的著名人物。1898年6月，光绪皇帝发布变法命令，谭氏奉诏进京，“参预新政”。同年九月，慈禧太后发动政变，废光绪，捕杀维新派。谭嗣同临危不惧，决心留下来纠合“侠士”数十人，营救光绪，事未成而被捕，投入死牢。在狱中，他意气自若，拾起地上煤屑，在壁上写下上面这首绝笔诗。\n诗的前两句，以张俭、杜根这两个历史人物受迫害的故事，说明维新变法运动的正义性和深得人民的支持与同情。张俭是东...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472e9ece49f46528ae0cded", "shortContent": "谭嗣同是近代史上维新变法的著名人物。1898年6月，光绪皇帝发布变法命令，谭氏奉诏进京，“参预新政”。同年9月，慈禧太后发动政变，废光绪，捕杀维新派。谭嗣同临危不惧，决心留下来纠合“侠士”数十人，营救光绪，事未成而被捕，投入死牢。在狱中，他意气自若，拾起地上煤屑，在壁上写下上面这首绝笔诗。\n\n诗的前两句，以张俭、杜根这两个历史人物受迫害的故事，说明维新变法运动的正义性和深得人民的支持与同情。张俭是...", "authors": ["高原"], "pressName": "上海辞书出版社"}]', '清朝诗人黄遵宪：颈血模糊似未干，中藏耿耿寸心丹。
武灜海：这是一首“拔起千仞，高唱入云”（谭嗣同语）的诗作。', 'center', 1423215510, '57b905cfa633bd00665d73ba', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (11841, '金刚经 · 第二十五品 · 化无所化分', NULL, 62, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', '', '', '“须菩提！于意云何？汝等勿谓如来作是念：‘我当度众生。’须菩提！莫作是念。何以故？实无有众生如来度者。若有众生如来度者，如来则有我、人、众生、寿者。须菩提！如来说：‘有我者，则非有我，而凡夫之人以为有我。’须菩提！凡夫者，如来说则非凡夫，是名凡夫。”', '', '', '须菩提，你的意思怎么样？你们不要说，如来有这样的念头：我应当救度众生。须菩提，不要这样想，为什么呢？实在没有众生是如来度的。如果有众生是如来所救度的，那么，如来就有我人众生寿者相。须菩提，如来说有我，就是虚幻的有我，而凡夫却以为有真实的我。须菩提，凡夫者，如来说是虚幻的凡夫。', NULL, '', 'indent', 1475756406, '57f5d0f78ac24700589bb493', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10460, '逢雪宿芙蓉山主人', NULL, 750, 492, 2, 9, '刘长卿', NULL, 10113, '57b9a043165abd00661cbf89', '唐', 'shi', '诗', 'http://baike.baidu.com/view/327374.htm', '', '日暮苍山远，天寒白屋贫。
柴门闻犬吠，风雪夜归人。', '这首诗描绘的是一幅风雪夜归图。前两句，写诗人投宿山村时的所见所感。后两句写诗人投宿主人家以后的情景。全诗语言朴实浅显，写景如画，叙事虽然简朴，含意十分深刻。', '逢：遇上。
宿：投宿；借宿。
芙蓉山主人：芙蓉山，各地以芙蓉命山名者甚多，这里大约是指湖南桂阳或宁乡的芙蓉山。主人，即指留诗人借宿者。这首诗通过雪夜借宿山村的情形，巧妙地写出山村景象与农家生活。
日暮：傍晚的时候。
苍山远：青山在暮色中影影绰绰显得很远。苍：青色。
白屋：未加修饰的简陋茅草房。一般指贫苦人家。
犬吠：狗叫。
夜归人：夜间回来的人。', '暮色苍茫，更觉前行山路遥远。天寒地冻，倍觉投宿人家清贫。忽然听得柴门狗叫，应是主人风雪夜归。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a6d635634aee3dec40", "shortContent": "这首诗用极其凝练的诗笔，描画出一幅以旅客暮夜投宿、山家风雪人归为素材的寒山夜宿图。诗是按时间顺序写下来的。首句写旅客薄暮在山路上行进时所感，次句写到达投宿人家时所见，后两句写入夜后在投宿人家所闻。每句诗都构成一个独立的画面，而又彼此连属。诗中有画，画外见情。\n诗的开端，以“日暮苍山远”五个字勾画出一个暮色苍茫、山路漫长的画面。诗句中并没有明写人物，直抒情思，但使读者感到其人呼之欲出，其情浮现纸上。...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d116", "shortContent": "这首诗用极其凝练的诗笔，描画出一幅以旅客暮夜投宿、山家风雪人归为素材的寒山夜宿图。诗是按时间顺序写下来的。首句写旅客薄暮在山路上行进时所感，次句写到达投宿人家时所见，后两句写入夜后在投宿人家所闻。每句诗都构成一个独立的画面，而又彼此连属。诗中有画，画外见情。\n\n诗的开端，以“日暮苍山远”五个字勾画出一个暮色苍茫、山路漫长的画面。诗句中并没有明写人物，直抒情思，但使读者感到其人呼之欲出，其情浮现纸上...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270597f0b9738b369b1d9", "shortContent": "夕阳西下，山野一片暮色苍茫，远处千峰百嶂开始笼上一层淡淡的薄雾，四围山色逐渐暗淡凝重。刘长卿翻山越岭，经过一天劳碌奔波，早已劳顿疲惫不堪，此时，他背靠一棵青古的松柏，环顾荒山壁下，落日西斜，满眼荒芜，心中不禁涌起一股落寞之感，喟然愁叹道：这荒山枯岭，未见人踪，唯吾一人踽踽独行于此，山路漫长，行途遥远，而今又是这般天寒地冷，积雪重重，不知今夜栖身何处……\n\n凄厉的北风呼晡着，一阵阵袭来，穿过稀疏的枯...", "authors": ["董镇菲"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270c79761253910e905b1", "shortContent": "夕阳西下，山野一片暮色苍茫，远处千峰百嶂开始笼上一层淡淡的薄雾，四围山色逐渐暗淡凝重。刘长卿翻山越岭，经过一天劳碌奔波，早已劳顿疲惫不堪，此时，他背靠一棵青古的松柏，环顾荒山壁下，落日西斜，满眼荒芜，心中不禁涌起一股落寞之感，喟然愁叹道：这荒山枯岭，未见人踪，唯吾一人踽踽独行于此，山路漫长，行途遥远，而今又是这般天寒地冷，积雪重重，不知今夜栖身何处……\n\n凄厉的北风呼啸着，一阵阵袭来，穿过稀疏的枯...", "authors": ["董镇菲"], "pressName": "崇文书局"}]', '《批点唐音》：此所谓真语真情者，清语古调。
《唐诗正声》：吴逸一曰：极肖山庄清景，却不寂寞。
《唐诗解》：此诗直赋实事，然令落魄者读之，真足凄绝千古。
《唐诗选脉会通评林》：周敬曰：语清调古，含无限凄楚。
《大历诗略》：宜入宋人团扇小景。
《唐诗笺注》：上二句孤寂况味，犬吠人归，若惊若喜，景色入妙。
《岘佣说诗》：较王、韦稍浅，其清妙自不可废。
《唐人绝句精华》：此诗二十字，将雪夜宿山人家一段情事，描绘如见。', 'center', 1415652741, '57b954da79bc44005ba17ed0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10461, '读山海经（其十）', NULL, 179, 99, 2, 2, '陶渊明', NULL, 10011, '57b8fa07c4c97100558ef104', '晋', 'shi', '诗', 'http://baike.baidu.com/view/3583888.htm', '', '精卫衔微木，将以填沧海。
刑天舞干戚，猛志固常在。
同物既无虑，化去不复悔。
徒设在昔心，良辰讵可待！', '本诗为《读山海经》诗的第十首。陶渊明对东晋的灭亡十分惋惜，对恭帝被弑痛心疾首。诗中歌颂了精卫和刑天的坚强斗争精神，寄托着诗人慷慨不平的心情和意愿。', '精卫：古代神话中鸟名。据《山海经·北山经》及《述异记》卷上记载，古代炎帝之女精卫，因游东海淹死，灵魂化为鸟，经常衔木石去填东海。衔：用嘴含。微木：细木。
刑天：神话人物，因和天帝争权，失败后被砍去了头，埋在常羊山，但他不甘屈服，以两乳为目，以肚脐当嘴，仍然挥舞着盾牌和板斧。（《山海经·海外西经》）干戚:盾斧。
同物：精卫既然淹死而化为鸟，就和其它的都相同，即使再死也不过从鸟化为另一种物，所以没有什么忧虑。
化去：刑天已被杀死，化为异物，但他对以往和天帝争神之事并不悔恨。
徒：徒然、白白地。在昔心：过去的壮志雄心。
良辰：实现壮志的好日子。讵：岂。这两句是说精卫和刑天徒然存在昔日的猛志，但实现他们理想的好日子岂是能等待得到！
猛志：勇猛的斗志。
在昔心：过去的壮志雄心。
讵：表示反问，岂。', '', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccae5914587d02f599d2", "shortContent": "陶渊明一生酷爱自由，反抗精神是陶诗重要的主题，这首诗赞叹神话形象精卫、刑天，即是此精神的体现。\n“精卫衔微木，将以填沧海。”起笔二句，概括了精卫的神话故事，极为简练、传神。《山海经·北山经》云：“发鸠之山……有鸟焉，其状如乌，文首、白喙、赤足，名曰精卫，其鸣自詨。是炎帝之少女，名曰女娃。女娃游于东海，溺而不返，故为精卫。常衔西山之木石，以堙于东海。”精卫为复溺死之仇，竟口衔微木，要填平东海。精卫之...", "authors": ["邓小军"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4547f27182da33f706b", "bookTitle": "陶渊明诗文鉴赏辞典", "articleId": "646aaa2330675327e1a164d8", "shortContent": "陶渊明一生酷爱自由，反抗精神是陶诗重要的主题，这首诗赞叹神话形象精卫、刑天，即是此精神的体现。\n“精卫衔微木，将以填沧海。”起笔二句，概括了精卫的神话故事，极为简练、传神。《山海经·北山经》云：“发鸠之山……有鸟焉，其状如乌，文首、白喙、赤足，名曰精卫，其鸣自[插图]。是炎帝之少女，名曰女娃。女娃游于东海，溺而不返，故为精卫。常衔西山之木石，以堙于东海。”精卫为复溺死之仇，竟口衔微木，要填平东海。...", "authors": ["邓小军"], "pressName": "上海辞书出版社"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472052e7f27182da38c521a", "shortContent": "陶渊明一生酷爱自由，反抗精神是陶诗重要的主题，这首诗赞叹神话形象精卫、刑天，即是此精神的体现。\n\n“精卫衔微木，将以填沧海”，起笔二句，概括了精卫的神话故事，极为简练、传神。《山海经·北山经》云：“发鸠之山……有鸟焉，其状如乌，文首、白喙、赤足，名曰精卫，其鸣自詨。是炎帝之少女，名曰女娃。女娃游于东海，溺而不返，故为精卫。常衔西山之木石，以堙于东海。”精卫为复溺死之仇，竟口衔微木，要填平东海。精卫...", "authors": ["邓小军"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "6470a4ceb5420e27678a688e", "shortContent": "陶渊明一生酷爱自由，反抗精神是陶诗重要的主题，这首诗赞叹神话 形象精卫、刑天，即是此精神的体现。\n\n“精卫衔微木，将以填沧海。”起笔二句，概括了精卫的神话故事，极为 简练、传神。《山海经·北山经》云:“发鸠之山......有鸟焉，其状如乌，文 首、白喙、赤足，名曰精卫，其鸣自?。是炎帝之少女，名曰女娃。女娃游 于东海，溺而不返，故为精卫。常衔西山之木石，以堙于东海。”精卫为复 溺死之仇，竟口衔微...", "authors": ["邓小军"], "pressName": "上海辞书出版社"}]', '', 'center', 1415653126, '57b8fba47db2a20054267899', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10462, '南歌子 · 钱塘端午', NULL, 221, 3406, 1, 3, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/view/1069514.htm', '', '山与歌眉敛，波同醉眼流。游人都上十三楼，不羡竹西歌吹、古扬州。
菰黍连昌歜，琼彝倒玉舟。谁家《水调》唱歌头，声绕碧山飞去、晚云留。', '此词描绘了在端午节时的各种赏心乐事。上阕开始就用移情手法描绘了湖光山色的美丽可人，继而用对比手法自身所处的十三楼加以赞美；下阕提笔便极写宴饮对酌的游赏乐事，其後则用一曲声满湖山的轻歌曼曲作结。有情、有景、有声、有色，给人一种飘然欲仙的愉悦之感。', '南歌子：唐教坊曲名。隋唐以来曲多以「子」名，「子」有小的含义，大体属小曲。调名本自汉张平子《南都赋》：「坐南歌兮起郑舞」句，取淳于棼事。《金奁集》入「仙吕宫」。此词有单调、双调二体。单调者始自温飞卿词，因词有「恨春宵」句，名《春宵曲》。张子澄词本此添字，因词有「高捲水晶帘额」句，名《水晶帘》，又有「惊破碧窗残梦」句，名《碧窗梦》。郑子聃有《我爱沂阳好》词十首，更名《十爱词》。以温飞卿《南歌子·手里金鹦鹉》为正体，单调二十三字，五句三平韵。另有单调二十六字，五句三平韵。双调者有平韵、仄韵两体。平韵者始自毛熙震词，周美成、杨无咎、仲殊五十四字体，无名氏五十三字体，俱本此添字。仄韵者始自《乐府雅词》，惟石次仲词最为谐婉。周美成词名《南柯子》，程正伯词名《望秦川》，田不伐词有「帘风不动蝶交飞」句，名《风蝶令》。双调五十二字，前後阕各四句三平韵；双调五十四字，前後阕各四句三平韵等变体。
调注：《苏长公二妙集》本、茅维《苏集》本「歌」下注：「一作『柯』。」
「钱塘端午」：元延祐本题作「杭州端午」，明吴讷钞本、《苏长公二妙集》本、毛本题作「游赏」。
「山与歌眉敛，波同醉眼流」句：傅子立注：「梁谢偃《听歌赋》：『低翠蛾而敛色，睇横波而流光。』」刘尚荣按：「见《文苑英华·卷七十八·〈乐·听歌赋〉》，别见《全唐诗·卷一百五十六》。又按东坡《次韵曹子方运判雪中同游西湖》诗：『云山已作歌眉浅，山下碧流清似眼。』与此词句同旨。」
十三楼：傅子立注：「钱塘西湖上，旧有十三间楼。」刘尚荣按：「详见宋周彦广《乾道临安志·卷三》、别见陈鹄《耆旧续闻·卷二》：『赵右史家有顾禧景蕃《补注东坡长短句》真迹，……又云：「余顷於郑公实处，见东坡亲迹……又《南歌子》云『游人都上十三楼，不羡竹西歌吹古扬州』，十三间楼在钱塘西湖北山，此词在钱塘作。旧注云汴京旧有十三楼，非也。」』」
竹西歌吹、古扬州：傅子立注：「扬州有蜀冈，有竹西亭。杜牧之诗：『斜阳竹西路，歌吹是扬州。』」刘尚荣按：「参见宋阮松菊撰《诗话总龟·卷三十·故事门》：『淮南蜀冈者，维扬之地也。或曰势连蜀土，或以产茶味如蜀茶云。自蜀冈之南有竹西亭，修竹疏翠，後即禅智寺也。竹西取杜牧之诗「斜阳竹西路，歌吹是扬州」。自蜀冈以南，景气顿异，北风至此遂绝。』杜诗据《全唐诗·卷五百二十二》杜牧之《题扬州禅智寺》，句中『斜阳』原作『谁知』。又，东坡《别公择》：『若问西来祖师意，竹西歌吹是扬州。』」
菰黍连昌歜（chù）：傅子立注：「《风土记》：『五月五日以菰叶裹黏米。』『楚祭屈原之馀风。』又：『俗饮菖蒲酒。』《左传》：『飨有昌歜。』注云：『菖蒲也。』」刘尚荣按：「包糉子祭屈原事，详见《艺文类聚·卷四·〈岁时部中·五月五日〉》引《风土记》：『仲夏端五，烹鹜角黍。端，始也，谓五月初五日也。又以菰叶裹黏米煮熟，谓之角黍。』又引《续齐谐记》：『屈原以五月五日投汨罗而死，楚人哀之，每至此日，以竹筒贮米投水祭之。』饮菖蒲酒事，见《古今事文聚类·前集·卷九·〈天时部·菖蒲酒〉》引《岁时杂记》：『端午以菖蒲或缕或屑汎酒。章简公《端午帖子》：「菖华汎酒尧樽绿，菰叶萦丝楚糉香。」』傅注将三事并举同归入《风土记》，不确也。《左传》文见《左传·僖公三十年》，杜元凯注：『昌歜，菖蒲俎。』盖菖蒲根，切之四寸，腌以为菜。傅注脱『俎』字，恐非是。」
琼彝倒玉舟：傅子立注：「《周礼·司彝尊》有鸡、虎等六彝之名，所以纳五齐三酒也。而彝皆有舟，则舟者彝下之台，所以承载彝，若今承露盘然。世俗或用琼玉为之。」刘尚荣按：「详见《周礼·春官·司彝尊》。『舟』为尊彝等器之托盘。」
《水调》唱歌头：傅子立注：「《明皇杂录》：『明皇好《水调》歌，及胡羯犯京，上欲迁幸，犹登花萼楼，置酒，回顾凄怆。使其中人歌《水调》毕，因使视楼下，有工歌而善《水调》者乎？有一少年自言工歌亦善《水调》，遂歌曰：「山川满月泪沾衣，富贵荣华能几时？不见只今汾水上，惟有年年秋雁飞。」上闻之，潸然曰：「谁为此词？」左右对曰：「宰相李峤。」上曰：「真才子也。」不待曲终。』《水调》曲颇广，谓之『歌头』，岂非首章之一解乎？白乐天：『《六幺》《水调》家家唱。』」刘尚荣按：「事见宋阮松菊《诗话总龟·前集卷二十四·感事门上》引《明皇传信记》，又见宋·王颐堂《碧鸡漫志·卷四·〈水调歌〉》引《明皇杂录》及唐·孟初中《本事诗·事感第二·李峤〈汾阴行〉》，诸家所记情节有异。又今通行本之《明皇杂录》：『兴庆宫帝潜邸，於西南隅起花萼、相辉二楼，与诸王游处。禄山犯顺，乘遽以闻，议欲迁幸，置酒楼上，命作乐，有进《水调》歌者曰：「山川满月泪沾衣，富贵荣华能几时！不见只今汾水上，惟有年年秋雁飞。」上问谁为此词，曰：「李峤。」上曰：「真才子也。」遂不终而去。』」龙榆生笺引宋·王颐堂《碧鸡漫志·卷四·〈水调歌〉》：「《理道要诀》所载唐乐曲，南吕商时号『水调』。予数见唐人说『水调』，各有不同。予因疑『水调』非曲名，乃俗呼音调之异名，今决矣。按《隋唐嘉话》：『炀帝凿汴河，自製《水调歌》』，即是『水调』中製歌也。世以今曲《水调歌》为炀帝自製，今曲乃中吕调，而唐所谓南吕商，则今俗呼中管林钟商也。《脞说》云：『水调《河传》，炀帝将幸江都时所製，声韵悲切，帝喜之。乐工王令言谓其弟子曰：「不返矣。水调《河传》，但有去声。」』此说与《安公子》事相类，盖水调中《河传》也。《明皇杂录》云：『禄山犯顺，议欲迁幸。帝置酒楼上，命作乐。有进《水调歌》者，曰：「山川满目泪沾衣，富贵荣华能几时。不见只今汾水上，惟有年年秋雁飞。」上问谁为此曲，曰：「李峤。」上曰：「真才子。」不终饮而罢。』此水调中一句七字曲也。白乐天《听水调诗》云：『五言一遍最殷勤，调少情多似有因。不会常时翻曲意，此声肠断为何人。』《脞说》亦云：『《水调》第五遍，五言调，声最愁苦。』此水调中一句五字曲。又有多遍，似是大曲也。乐天诗又云：『时唱一声新水调，谩人道是采菱歌。』此水调中新腔也。《南唐近事》云：『元宗留心内宠，宴私击鞠无虚日。尝命乐工杨花飞奏水调词进酒，花飞惟唱「南朝天子好风流」一句，如是数四。上悟，覆杯赐金帛。』此又一句七字。然既曰『命奏水调词』，则是令杨花飞水调中撰词也。《外史梼杌》云：『王衍泛舟巡阆中，舟子皆衣锦绣，自製水调《银汉曲》。』此水调中製《银汉曲》也。今世所唱中吕调《水调歌》，乃是以俗呼音调异名者名曲，虽首尾亦各有五言两句，决非乐天所闻之曲。《河传》，唐词存者二，其一属南吕宫，凡前段平韵，後仄韵。其一乃今《怨王孙》曲，属无射宫。以此知炀帝所製《河传》，不传已久。然欧阳永叔所集词内，《河传》附越调，亦《怨王孙》曲。今世《河传》乃仙吕调，皆令也。」
「声绕碧山飞去、晚云留」句：傅子立注：「张华《博物志》：『秦青善讴，每抚节而歌，声震林木，响遏行云。』」刘尚荣按：「《博物志·卷八》：『薛谭学讴於秦青，未穷青之旨，於一日遂辞归。秦青乃饯於郊衢，抚节悲歌，声震林木，响遏行云。』傅注引述之情节与原书有出入。」', '山色与歌女黛眉浓聚一样绿，碧波就像人的朦胧醉眼一样流。
人们都爱登上十三楼，不再羡慕竹西歌吹的古扬州。
菰米软糕菖蒲菜，玉壶向玉杯倾倒着美酒。
不知谁家唱起水调歌头，歌声绕着青山飞去晚云又将它挽留。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b22e6a6b501f9542bb", "shortContent": "苏轼一到杭州就对杭州的山水发出惊叹，“余杭自是山水窟”，“故乡无此好湖山”，并表示死后愿能葬在这里。他先为通判，后作知州，在杭期间无日不在山水之间，甚至连辨讼决案等公务也在西湖办理。随着政治上的日益不得志，他对杭州的这种深情也与日俱增。他不仅把杭州当作游赏地、栖身所，更把它当作摆脱烦恼的精神逋逃薮。他写于杭州的诗词有不少就是这一段心灵历程的忠实纪录。此词就是其中之一。\n这首词写的是杭州的游赏之乐，...", "authors": ["谢楚发"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b80f8fda5565060485", "shortContent": "苏轼一到杭州就对杭州的山水发出惊叹：“余杭自是山水窟”、“故乡无此好湖山”，并表示死后愿能葬在这里。他先为通判，后做知州，在杭期间无日不在山水之间，甚至连辨讼决案等公务也在西湖办理。随着政治上的日益不得志，他对杭州的这种深情也与日俱增。他不仅把杭州当作游赏地、栖身所，更把它当作摆脱烦恼的精神逋逃薮。他写于杭州的诗词有不少就是这一段心灵历程的忠实记录。此词就是其中之一。\n这首词写的是杭州的游赏之乐，...", "authors": ["谢楚发"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e7d9761253910e9029e", "shortContent": "朱本、龙本编庚午（1090），孔《谱》、薛本从之。周淙《乾道临安志》卷二云：“十三间楼，去钱塘门二里许，苏轼治杭日，多治事于此。”陈鹄《耆旧续闻》卷二：“《南歌子》云：‘游人都上十三楼。不羡竹西歌吹、古扬州。’十三间楼在钱塘西湖北山，此词在钱塘作。旧注云：‘汴京旧有十三楼’非也。”邹王本云：东坡守杭，元祐四年七月三日到任，元祐六年三月离杭还朝，只元祐五年在杭度端午节，故编此词于元祐五年庚午（109...", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646834555e6bb82b8cd27f77", "shortContent": "苏轼一到杭州就对杭州的山水发出惊叹，“余杭自是山水窟”,“故乡无此好湖山”，并表示死后愿能葬在这里。他先为通判，后作知州，在杭期间无日不在山水之间，甚至连辨讼决案等公务也在西湖办理。随着政治上的日益不得志，他对杭州的这种深情也与日俱增。他不仅把杭州当作游赏地、栖身所，更把它当作摆脱烦恼的精神逋逃薮。他写于杭州的诗词有不少就是这一段心灵历程的忠实纪录。此词就是其中之一。\n\n这首词写的是杭州的游赏之乐...", "authors": ["谢楚发"], "pressName": "上海辞书出版社"}]', '明·潘游龙《精选古今诗馀醉》：此词妙在援引古事，不为古用，非直写景物而已。
清·黄苏《蓼园词选》：此词不过叙汴京端午繁盛光景耳。在苏集中，此为平调，然亦自壮丽。', 'indent', 1415653595, '57b90ff95bbb50005b78a193', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10463, '感遇（其一）', NULL, 4613, 216, 2, 2, '张九龄', NULL, 10095, '57b90ef17db2a200542711c0', '唐', 'shi', '诗', 'http://baike.baidu.com/view/1617779.htm', '', '兰叶春葳蕤，桂华秋皎洁。
欣欣此生意，自尔为佳节。
谁知林栖者，闻风坐相悦。
草木有本心，何求美人折？', '诗人在开篇用整齐的对偶句突出了两种高雅的植物：茂盛纷披的春兰，皎明洁净的秋桂，然后生动地写出它们的勃勃生机，转而写到人们对它们的态度，最后引出全诗主旨：春兰、秋桂的美好，完全出于自然本性，而并非为了求得人们的赏识。诗人以此比喻洁身自好的君子。
本诗虽短小，但用尽全力，结构严谨，诗境意境没有落空。诗意温和，不知不觉中，在咏物的背后，讲出了高雅的生活哲理。', '感遇：古诗题，用于写心有所感，借物寓意之诗。
葳蕤（wēiruí）：枝叶茂盛而纷披。
林栖者：指隐士。
坐：因而。
本心：天性。
美人：喻指理想中的同道者。', '泽兰逢春茂盛芳馨，桂花遇秋皎洁清新。兰桂欣欣生机勃发，春秋自成佳节良辰。谁能领悟山中隐士，闻香深生仰慕之情？花卉流香原为天性，何求美人采撷扬名。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e928fdbb8b379ee09594b", "shortContent": "张九龄遭谗贬谪后所作的《感遇》诗十二首，朴素遒劲，寄慨遥深。此为第一首，诗以比兴手法，抒发了诗人孤芳自赏，不求人知的情感。\n诗一开始，用整齐的偶句，突出了两种高雅的植物——春兰与秋桂。战国楚屈原《九歌·礼魂》中，有“春兰与秋菊，长无绝兮终古”句。张九龄是广东曲江人，其地多桂，即景生情，就地取材，把秋菊换成了秋桂，师古而不泥古。兰桂对举，兰举其叶，桂举其花，这是由于对偶句的关系，互文以见义，其实是各...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389abbb31680ae4c4b73c", "shortContent": "张九龄遭谗贬谪后所作的《感遇》诗十二首，朴素遒劲，寄慨遥深。此为第一首，诗以比兴手法，抒发了诗人孤芳自赏，不求人知的情感。\n\n诗一开始，用整齐的偶句，突出了两种高雅的植物——春兰与秋桂。战国楚屈原《九歌·礼魂》中，有“春兰与秋菊，长无绝兮终古”句。张九龄是广东曲江人，其地多桂，即景生情，就地取材，把秋菊换成了秋桂，师古而不泥古。兰桂对举，兰举其叶，桂举其花，这是由于对偶句的关系，互文以见义，其实是...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d8f", "shortContent": "【其一】\n\n张九龄《感遇》诗共十二首，多感事寄兴，寄托人生慨望，作于唐开元二十五年（737）被贬为荆州长史时。本诗为其中第一首，借歌咏兰草桂花，表达了诗人不慕权贵、坚守节操的高尚人格。\n\n一、二句以春兰秋桂对举，赞美兰花桂树的生机盎然与清雅高洁。以“兰桂”喻志趣高洁之君子，源自屈原《离骚》，其诗中有“扈江离与辟芷兮，纫秋兰以为佩”、“矫菌桂以纫蕙兮，索胡绳之”等句，是中国传统文学中“香草美人”之譬...", "authors": ["乐云", "冯丽霞"], "pressName": "崇文书局"}]', '', 'center', 1416661228, '57b2c7a3c4c9710054926358', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10464, '感遇（其二）', NULL, 1842, 216, 1, 1, '张九龄', NULL, 10095, '57b90ef17db2a200542711c0', '唐', 'shi', '诗', 'http://baike.baidu.com/view/1617779.htm', '', '江南有丹橘，经冬犹绿林。
岂伊地气暖？自有岁寒心。
可以荐嘉客，奈何阻重深。
运命唯所遇，循环不可寻。
徒言树桃李，此木岂无阴？', '诗人谪居江陵，正是橘之产区。于是借彼丹橘，喻己贞操。诗开头二句，托物喻志之意，尤其明显。以一个「犹」字，充满了赞颂之意。三、四句用反诘，说明橘之高贵是其本质使然，并非地利之故。五、六句写如此嘉树佳果，本应荐之嘉宾，然而却重山阻隔，无法为之。七、八句叹惜丹橘之命运和遭遇。最后为桃李之被宠誉，丹橘之被冷遇打抱不平。全诗表达诗人对朝政昏暗和身世坎坷的愤懑。诗平淡自然，愤怒哀伤不露痕迹，语言温雅醇厚。桃李媚时，丹橘傲冬，邪正自有分别。', '伊：语助词。
岁寒心：意即耐寒的特性。
荐：进奉意。
树：种植意。', '江南丹橘叶茂枝繁，经冬不凋四季常青。岂是南国地气和暖，而是具有松柏品性。荐之嘉宾必受称赞，山重水阻如何进献？命运遭遇往往不一，因果循环奥秘难寻。只说桃李有果有林，难道丹橘就不成阴？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9290d635634aee3deaa1", "shortContent": "读着张九龄这首歌颂丹橘的诗，很容易想到屈原的《橘颂》。屈原生于南国，橘树也生于南国，他的那篇《橘颂》一开头就说：“后皇嘉树，橘徕服兮。受命不迁，生南国兮。”其托物喻志之意，灼然可见。张九龄也是南方人，而他的谪居地荆州的治所江陵（即楚国的郢都），本来是著名的产橘区。他的这首诗一开头就说：“江南有丹橘，经冬犹绿林”。其托物喻志之意，尤其明显。屈原《九歌·湘夫人》的名句告诉我们：“袅袅兮秋风，洞庭波兮木...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389abbb31680ae4c4b73e", "shortContent": "读着张九龄这首歌颂丹橘的诗，很容易想到屈原的《橘颂》。屈原生于南国，橘树也生于南国，他的那篇《橘颂》一开头就说：“后皇嘉树，橘徕服兮。受命不迁，生南国兮。”其托物喻志之意，灼然可见。张九龄也是南方人，而他的谪居地荆州的治所江陵（即楚国的郢都），本来是著名的产橘区。他的这首诗一开头就说：“江南有丹橘，经冬犹绿林。”其托物喻志之意，尤其明显。屈原《九歌·湘夫人》的名句告诉我们：“袅袅兮秋风，洞庭波兮木...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '', 'center', 1416661351, '57b93ccf165abd0054c1cc44', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (49172, '送郑汝玉归莆关', NULL, 1, 125, 0, 1, '陈高', NULL, 11172, '5858e6341b69e60056f60fdf', '元', 'shi', '诗', NULL, NULL, '莆关深入海东南，日出先看曙色酣。
李愿归耕盘谷土，杜陵思乐百花潭。
到家三月山矾白，入馔千林竹笋甘。
愧我天涯尚羁旅，乡愁因尔不能堪。', NULL, NULL, NULL, NULL, NULL, 'center', 1525464497, '585cee2a128fe1006de4e1aa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10466, '佳人', NULL, 914, 1416, 4, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/71593/5128543.htm', '', '绝代有佳人，幽居在空谷。
自云良家子，零落依草木。
关中昔丧乱，兄弟遭杀戮。
官高何足论，不得收骨肉。
世情恶衰歇，万事随转烛。
夫婿轻薄儿，新人美如玉。
合昏尚知时，鸳鸯不独宿。
但见新人笑，那闻旧人哭。
在山泉水清，出山泉水浊。
侍婢卖珠回，牵萝补茅屋。
摘花不插发，采柏动盈掬。
天寒翠袖薄，日暮倚修竹。', '此诗写一个乱世佳人被丈夫遗弃，幽居空谷，艰难度日的不幸遭遇。她出身良家，然而生不逢时，在安史战乱中，原来官居高位的兄弟惨遭杀戮，丈夫见她娘家败落，就遗弃了她，于是她在社会上流落无依。然而，她没有被不幸压倒没有向命运屈服；她咽下生活的苦水，幽居空谷，与草木为邻，立志守节，宛若山泉。此诗讴歌的就是这种贫贱不移，贞节自守的精神。全诗文笔委婉，缠绵悱恻，绘声如泣如诉，绘影楚楚动人。「在山泉水清，出山泉水浊」二句深寓生活哲理。', '绝代：冠绝当代，举世无双。
佳人：貌美的女子。
幽居：静处闺室，恬淡自守。
空谷：一作「山谷」。
零落：飘零沦落。
依草木：住在山林中。
关中：指函谷关以西的地区，这里指长安。
丧乱：一作「丧败」，死亡和祸乱，指遭逢安史之乱。
官高：指娘家官阶高。
骨肉：指遭难的兄弟。
转烛：烛火随风转动，比喻世事变化无常。
夫壻：丈夫。
新人：指丈夫新娶的妻子。
美如玉：一作「已如玉」。
合昏：夜合花，叶子朝开夜合。
鸳鸯：水鸟，雌雄成对，日夜形影不离。
旧人：佳人自称。
卖珠：因生活穷困而卖珠宝。
牵萝：拾取树藤类枝条。也是写佳人的清贫。
插发：一作「插髻」，一作「插鬢」。
采柏：采摘柏树叶。
动：往往
盈掬：一作「盈握」。
修竹：高高的竹子。喩佳人高尚的节操。', '一位容貌绝伦美丽女人，孤独地住在幽深的山谷。
自称出身名门清白女子，飘零沦落在荒山野林中。
当年关中一带战火连天，自己的兄弟也惨遭杀戮。
官高禄厚又有什么用处，连骸骨都没能收进坟墓。
世俗人情厌恶衰败的人，万事就像那摇曳的烛光。
薄情寡义的丈夫厌弃我，爱上貌美如玉美丽新妇。
合欢花到了晚上就闭合，鸳鸯鸟双栖不隻身独宿。
丈夫眼裏衹有新人笑容，哪听得到我的悲伤啼哭。
大山裏的泉水清澈明亮，出山後泉水就染上污浊。
等待侍女变卖珍珠回来，牵起藤萝修补破漏茅屋。
采摘鲜花不去装饰鬓发，喜爱翠柏坚贞尽情摘采。
寒风吹动我薄薄的衣衫，日落黄昏我斜倚着青竹。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92aad635634aee3ded2f", "shortContent": "诗的主人公是一个战乱时被遗弃的女子。在中国古典文学的人物画廊中，这是一个独特而鲜明的女性形象。\n诗一开头，便引出这位幽居空谷的绝代佳人，接着以“自云”领起，由佳人诉说自己的身世遭遇。她说自己出身于高门府第，但生不逢时，赶上了社会动乱；兄弟虽官居高位，但惨死于乱军之中，连尸骨也无法收葬。在这人情世态随着权势转移而冷暖炎凉的社会里，命运对于不幸者格外冷酷。由于娘家人亡势去，轻薄的夫婿无情地抛弃了她，在...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a77", "shortContent": "诗的主人公是一个战乱时被遗弃的女子。在中国古典文学的人物画廊中，这是一个独特而鲜明的女性形象。\n\n诗一开头，便引出这位幽居空谷的绝代佳人，接着以“自云”领起，由佳人诉说自己的身世遭遇。她说自己出身于高门府第，但生不逢时，赶上了社会动乱；兄弟虽官居高位，但惨死于乱军之中，连尸骨也无法收葬。在这人情世态随着权势转移而冷暖炎凉的社会里，命运对于不幸者格外冷酷。由于娘家人亡势去，轻薄的夫婿无情地抛弃了她，...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d95", "shortContent": "诗人杜甫以满含深情的笔墨，创造了一位绝代佳人的美好形象。\n\n“绝代有佳人，幽居在深谷。”诗人没有具体描绘佳人美貌，但仅“绝代”二字，就足以让人产生无尽的想象。是秀发如瀑、明眸善睐吧！是一顾倾城、再盼倾国吧！是凌波微步、罗袜生尘吧！是“手如柔荑，肤如凝脂”吧！抑或是“巧笑倩兮，美目盼兮”吧！……不，这些诗人都没有指实，就是“绝代”，是无与伦比的一种美貌与气质。而这样的一位佳人，却“幽居在山谷”，独自...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127067c305cf0801816fc0", "shortContent": "诗人杜甫以满含深情的笔墨，创造了一位绝代佳人的美好形象。\n\n“绝代有佳人，幽居在空谷。”诗人没有具体描绘佳人美貌，但仅“绝代”二字，就足以让人产生无尽的想象。是秀发如瀑、明眸善睐吧！是一顾倾城、再盼倾国吧！是凌波微步、罗袜生尘吧！是“手如柔荑，肤如凝脂”吧！抑或是“巧笑倩兮，美目盼兮”吧！……不，这些诗人都没有指实，就是“绝代”，是无与伦比的一种美貌与气质。而这样的一位佳人，却“幽居在空谷”，独自...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6465dc215fc8182fe9a2ff1f", "shortContent": "诗的主人公是一个战乱时被遗弃的女子。在中国古典文学的人物画廊中，这是一个独特而鲜明的女性形象。\n\n诗一开头，便引出这位幽居空谷的绝代佳人，接着以“自云”领起，由佳人诉说自己的身世遭遇。她说自己出身于高门府第，但生不逢时，赶上了社会动乱；兄弟虽官居高位，但惨死于乱军之中，连尸骨也无法收葬。在这人情世态随着权势转移而冷暖炎凉的社会里，命运对于不幸者格外冷酷。由于娘家人亡势去，轻薄的夫婿无情地抛弃了她，...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}]', '《唐诗品汇》：刘云：闲言馀语，无不可感（「世情」四句下）。刘云：似悲似诉。自言自誓，矜持慷慨，修洁端丽，画所不能如，论所不能及（「合昏」八句下）。刘云：字字矜到而不艰棘。尽不容尽（「摘花」四句下）。
《唐诗解》：此诗叙事真切，疑当时实有是人。然其自况之意，盖亦不浅。夫少陵冒险以奔行在，千里从君，可谓忠矣，然肃宗慢不加礼，一论房琯而遂废斥于华州，流离艰苦，采橡栗以食，此与「倚修竹」者何异耶？吁！读此而知唐室待臣之薄也，
《唐诗归》：锺云：卖珠补屋，故家暴贫真境，未经过者以为迂（「侍婢」二句下）。锺云：清境难堪，然自不恶（末二句下）。
《唐诗选脉会通评林》：吴山民曰：语虽浅，当是《谷风》後第一首。「世情」二语，人情万端，可叹，「夫婿」以下六语，写情至此，直可痛哭。周珽曰：以《骚》为经，以《选》为纬，高踞汉魏之顶。郭浚曰：转折流美，又极凄怨。陆时雍曰：「在山」二句，语何自持；「天寒」二句，益更矜重，端人不作佻语。
《唐诗快》：题衹「佳人」二字耳，初未尝云「叹佳人」、「惜佳人」也，然篇中可胜叹惜乎？此诗盖为佳人而发，但不知作者果为佳人否？则观者果当作佳人观否？请试参之。衹此二语，令人凄然欲泪（首二句下）。「自云」二字亦伤心（「自云」句下）。伤心（「零落」四句下）。可哭（「那闻」句下）。悄然（末二句下）。
《杜诗说》：末二语嫣然有韵，本美其幽闲贞静之意，却尤半点道学气。
《茧斋诗谈》：「在山泉水清，出山泉水浊」，古腰锁法，云横山腰，似断不断，此所以妙。
《唐诗别裁》：结处衹用写景，不更着议论，而清洁贞正意，自隐然言外，诗格最超。
《杜诗镜铨》：接转，又插一喻，语浅义深，逼真汉魏乐府神理（「在山」四句下）。入李云；落落穆穆，写出幽真本色（「摘花」二句下）。
《读杜心解》：「在山清」、「出山浊」，可谓贞士之心，化人之舌矣。建安而下，齐、梁而上，无此见道语。衹以写景作结，脱尽色相。
《网师园唐诗笺》：「在山泉水清」至末，落落写来，不着议论，而神韵弥隽。
《诗法简易录》：忽入比喻对偶句，气则停蓄，调则高起，最妙（「在山」一联下）。
《超纯斋诗词》：「佳人」并非写实，衹是一种寄託，可能是诗人自己的身影。虽时世艰难，多遭不幸，仍不愿入染浊流。', 'center', 1416661741, '57b8f0ff165abd0054bf6a0d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10467, '送綦毋潜落第还乡', NULL, 343, 394, 1, 3, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383030.htm', '', '圣代无隐者，英灵尽来归。
遂令东山客，不得顾采薇。
既至金门远，孰云吾道非。
江淮度寒食，京洛缝春衣。
置酒临长道，同心与我违。
行当浮桂棹，未几拂荆扉。
远树带行客，孤城当落晖。
吾谋适不用，勿谓知音稀。', '《送綦毋潜落第还乡》是唐代诗人王维创作的一首劝慰友人落第的诗。此诗围绕送友还乡，对友人科考落第一事多方给予慰藉和劝勉，鼓励友人不要灰心懊丧，使其觉得知音是极为重要的。全诗着意在这个主旨上加以烘染，有叙事、有写景、有抒情，有感慨，有勉励，写景清新，抒情柔蜜，感慨由衷，勉励挚敬，令人振奋。诗意明晰动人，语言质朴真实，充溢着诗人对友人的信任和希望。', '綦毋（qíwú）潜：字孝通（一作季通），江西赣州人，王维好友。綦毋，複姓。
圣代：政治开明、社会安定的时代。
英灵：英华灵秀的贤才。
东山客：东晋谢安曾隐居会稽东山，此处泛指隐居的贤才。
采薇：商末周初，伯夷、叔齐兄弟隐于首阳山，采薇而食，后世遂以采薇指隐居生活。
金门：一作「君门」。金马门，汉代宫门名。汉代贤士等待皇帝召见的地方。
吾道非：《孔子家语·在厄》记载：「楚昭王聘孔子，孔子往，陈蔡发兵围孔子，孔子曰：『匪兕匪虎，率彼旷野，吾道非乎，吾何为至此乎？』」是指孔子叹自己政策的不能实行，半途受到阻碍。
寒食：古人以冬至后一百零五天为寒食节，断火三日。
京洛：一作「京兆」。指东京洛阳。
江淮：指长江，淮水，是綦毋潜所必经的水道。
临长道：一作「长安道」。
同心：志同道合的朋友、知己。
违：分离。
行当：将要。
棹：划船的用具，此处用以指代船。
未几：不久。
孤城：一作「孤村」。
「吾谋适不用」句：说綦毋潜此次落第是偶然失败。左传记载：「士曾行，绕朝赠之以策（马鞭）曰：‘子无谓秦无人，吾谋适不用也。’」适，偶然的意思。
知音稀：语出《古诗十九首》：「不惜歌者苦，但伤知音稀。」', '政治清明时代绝无隐者存在，为朝政服务有才者纷纷出来。
就连你这个隐居东山的隐者，也不再效法伯夷叔齐去采薇。
你应试到京城君门遥远难叩，那是命运不济谁说吾道不对？
你将经过江淮去度过寒食节，到东京洛阳时滞留缝制春衣。
我们又在长安城外设酒饯别，知心朋友如今又要与我分离。
你行将驾驶着小船南下归去，不几天就可把自家柴门扣开。
远山的树木把你的身影遮盖，夕阳余辉映得孤城艳丽多彩。
你暂不被录用纯属偶然的事，别以为知音稀少而徒自感慨！', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d97", "shortContent": "此诗是诗人王维赠与友人綦毋潜的，由诗名我们便可以得知綦毋潜当时应是落榜后准备返回家乡，此诗便是王维为了劝慰落第友人而写。本诗既有叙事，又有写景，更有抒情之句，语言十分质朴真实，令人充分感受到诗人对友人的希望与劝慰。\n\n“圣代无隐者，英灵尽来归。遂令东山客，不得顾采薇。”“东山客”由东晋谢安曾隐居会稽东山得来，而在此诗中，则泛指那些隐居的贤士。“采薇”的典故是指商末周初，伯夷、叔齐兄弟隐于首阳山，采...", "authors": ["孟佳"], "pressName": "崇文书局"}]', '', 'center', 1416661846, '57b8bf7f79bc44005b9da9ac', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10468, '青溪', NULL, 461, 394, 1, 3, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/344240/8232706.htm', '', '言入黄花川，每逐青溪水。
随山将万转，趣途无百里。
声喧乱石中，色静深松里。
漾漾泛菱荇，澄澄映葭苇。
我心素已闲，清川澹如此。
请留磐石上，垂钓将已矣。', '此诗描写了一条青溪的幽秀景色，诗人用多彩的画笔，绘出青溪流经不同地方时呈现的不同画面。其中“声喧乱石中，色静深松里”两句，以喧响的声音和幽冷的色调形成闹与静的强烈对比，如同一幅“有声画”。诗的末四句写出诗人心境的闲澹正如清川的闲澹，把自己的精神和自然的精神融和起来，意味隽永。', '青溪：在今陕西勉县之东。
言：发语词，无义。
黄花川：在今陕西凤县东北黄花镇附近。
趣途：趣，同“趋”，指走过的路途。
声：溪水声。
色：水色。
漾漾：水波动荡。
菱荇（língxìng）：泛指水草。
“漾漾泛菱荇，澄澄映葭苇。”句：描写菱荇在青溪水中浮动，芦苇的倒影映照于清澈的流水。
葭（jiā）苇：泛指芦苇。
素：一向。
闲：悠闲澹泊。
澹（dàn）：恬静安然。溪水澄澈平静。
磐石：一作：盘石，大石。
将已矣：将以此度过终生。已，结束。', '每次我进入黄花川漫游，常常沿着青溪辗转飘流。
流水依随山势千回万转，路途无百里却曲曲幽幽。
乱石丛中水声喧哗不断，松林深处山色静谧清秀。
溪中菱藕荇菜随波荡漾，澄澄碧水倒映芦苇蒲莠。
我的心平素已习惯闲静，澹泊的青溪更使我忘忧。
让我留在这盘石上好了，终日垂钓一直终老到头！
', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929503048e64fbd912cc", "shortContent": "诗题一作《过青溪水作》，大约是王维初隐蓝田（今属陕西）南山时所作。此诗写了一条不甚知名的溪水，却很能体现王维山水诗的特色。\n看来王维曾不止一次地循青溪入黄花川游历。这一段路程虽长不及百里，但溪水随着山势盘曲蛇行，千回万转，颇为蜿蜒多姿。王维另有一首《自大散以往深林密竹蹬道盘曲四五十里至黄牛岭见黄花川》，也说那里的山路“危径几万转”，可与此诗的“随山将万转”对看。\n诗开头四句对青溪作总的介绍后，接着...", "authors": ["刘德重"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d99", "shortContent": "素有“诗佛”之称的王维，其大多数作品都是山水田园诗歌。王维常运用五律和五绝的诗歌形式，诗歌篇幅短小，且均用词优美、语言精致。不仅描绘出幽静淡远的自然景色，也吐露出自己闲逸恬适的生活情趣与隐于山水间的真挚追求。此首五言古诗《青溪》亦是这种风格。此诗又名《过青溪水作》，大约是王维初隐蓝田南山时所作。\n\n开头四句“言入黄花川，每逐青溪水。随山将万转，趣途无百里”，是对青溪的一个总的介绍。“言”字在此为发...", "authors": ["孟佳"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646399ce45e4710056bfea55", "shortContent": "诗题一作《过青溪水作》，大约是王维初隐蓝田（今属陕西）南山时所作。此诗写了一条不甚知名的溪水，却很能体现王维山水诗的特色。\n看来王维曾不止一次地循青溪入黄花川游历。这一段路程虽长不及百里，但溪水随着山势盘曲蛇行，千回万转，颇为蜿蜒多姿。王维另有一首《自大散以往深林密竹蹬道盘曲四五十里至黄牛岭见黄花川》，也说那里的山路“危径几万转”，可与此诗的“随山将万转”对看。\n诗开头四句对青溪作总的介绍后，接着...", "authors": ["刘德重"], "pressName": "上海辞书出版社"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "64639e1c7f27182da34ff368", "shortContent": "诗题一作《过青溪水作》，大约是王维初隐蓝田（今属陕西）南山时所作。此诗写了一条不甚知名的溪水，却很能体现王维山水诗的特色。\n\n 看来王维曾不止一次地循青溪入黄花川游历。这一段路程虽长不及百里，但溪水随着山势盘曲蛇行，千回万转，颇为蜿蜒多姿。王维另有一首《自大散以往深林密竹蹬道盘曲四五十里至黄牛岭见黄花川》，也说那里的山路“危径几万转”，可与此诗的“随山将万转”对看。\n\n 诗开头四句对青溪作总的介绍...", "authors": ["刘德重"], "pressName": "上海辞书出版社"}]', '明·鍾惺《唐诗归·卷八》：随山二句亦是真境。
明·谭元春：“声喧”二句下“喧”、“静”俱极深妙。
清·黄周星《唐诗快·卷四》：右丞诗大抵无烟火所，故当于笔墨外求之。', 'center', 1416670557, '57b92be0c4c9710055909354', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10469, '渭川田家', NULL, 400, 394, 2, 2, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383031.htm', '', '斜阳照墟落，穷巷牛羊归。
野老念牧童，倚杖候荆扉。
雉雊麦苗秀，蚕眠桑叶稀。
田夫荷锄至，相见语依依。
即此羡闲逸，怅然吟式微。', '此诗是唐代诗人王右丞晚年的作品，描写的是初夏傍晚农村夕阳西下、牛羊回归、老人倚杖、麦苗吐秀、桑叶稀疏、田夫荷锄一系列宁静和谐的景色，表现了农村平静闲适、悠闲可爱的生活。这种充满诗情画意的田家生活图景也是作者当时心境的反映，反映了他对官场生活的厌恶。全诗语言朴素，纯用白描，自然清新，诗意盎然，体现出王右丞诗歌「诗中有画」的艺术特色。', '渭川：一作「渭水」。渭水源于甘肃鸟鼠山，经陕西，流入黄河。田家：农家。
墟落：村庄。
斜阳：一作「斜光」。
穷巷：深巷。
野老：村野老人。
牧童：一作「僮仆」。
倚杖：靠着拐杖。
荆扉：柴门。
雉雊（zhìgòu）：野鸡鸣叫。《诗经·小雅·小弁》：「雉之朝雊，尚求其雌。」
蚕眠：蚕蜕皮时，不食不动，像睡眠一样。
荷（hè）：肩负的意思。
至：一作「立」。
即此：指上面所说的情景。
式微：《诗经》篇名，其中有「式微，式微，胡不归」之句，表归隐之意。', '夕阳的馀晖照着村庄，牛羊回到深深的小巷。
老人惦记远出的牧童，拄着拐杖在门口眺望。
开花的麦田野鸡鸣叫，稀疏的桑叶蚕儿休眠。
归来的农夫扛着锄头，相见时招呼絮语依依。
我多么向往隐居生活，不禁吟咏着《式微》诗章。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9295911759740c9b1a05", "shortContent": "夕阳西下、夜幕将临之际，诗人面对一幅恬然自乐的田家晚归图，油然而生羡慕之情。诗的核心是一个“归”字。\n诗人一开头，首先描写夕阳斜照村落的景象，渲染暮色苍茫的浓烈气氛，作为总背景，统摄全篇。接着，诗人一笔就落到“归”字上，描绘了牛羊徐徐归村的情景，使人很自然地联想起《诗经·王风·君子于役》里的几句诗：“鸡栖于埘，日之夕矣，羊牛下来。君子于役，如之何勿思？”诗人痴情地目送牛羊归村，直至没入深巷。就在这...", "authors": ["傅如一"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc4091d", "shortContent": "夕阳西下、夜幕将临之际，诗人面对一幅恬然自乐的田家晚归图，油然而生羡慕之情。诗的核心是一个“归”字。\n\n诗人一开头，首先描写夕阳斜照村落的景象，渲染暮色苍茫的浓烈气氛，作为总背景，统摄全篇。接着，诗人一笔就落到“归”字上，描绘了牛羊徐徐归村的情景，使人很自然地联想起《诗经·王风·君子于役》里的几句诗：“鸡栖于埘，日之夕矣，羊牛下来。君子于役，如之何勿思？”诗人痴情地目送牛羊归村，直至没入深巷。就在...", "authors": ["傅如一"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d9a", "shortContent": "这是一幅恬静、美妙的田家晚归图。金色的落日余晖洒满村落，茫茫的暮色即将临近，这是一个祥和、忙碌的时刻。看：牛羊开始成群地走向村子，慢慢没入长长的小巷。一位慈祥的老人正倚着拐杖，于柴门外翘首期盼，他在静静地等待放牧归来的孩子的可爱身影。可以想象，经过一天的放牧生活，孩子也正兴奋地向家的方向奔走。在那里，有慈爱的爷爷为他准备了无尽的关爱！田野里，青青的麦丛中野鸡正卖力地鸣叫，深情地呼唤着自己的配偶；桑...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270447ccdb86c49f29221", "shortContent": "这是一幅恬静、美妙的田家晚归图。金色的落日余晖洒满村落，茫茫的暮色即将临近，这是一个祥和、忙碌的时刻。看：牛羊开始成群地走向村子，慢慢没入长长的小巷。一位慈祥的老人正倚着拐杖，于柴门外翘首期盼，他在静静地等待放牧归来的孩子的可爱身影。可以想象，经过一天的放牧生活，孩子也正兴奋地向家的方向奔走。在那里，有慈爱的爷爷为他准备了无尽的关爱！田野里，青青的麦丛中野鸡正卖力地鸣叫，深情地呼唤着自己的配偶；桑...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "64639e72c0471b0062c8ed43", "shortContent": "夕阳西下、夜幕将临之际，诗人面对一幅恬然自乐的田家晚归图，油然而生羡慕之情。诗的核心是一个“归”字。\n\n 诗人一开头，首先描写夕阳斜照村落的景象，渲染暮色苍茫的浓烈气氛，作为总背景，统摄全篇。接着，诗人一笔就落到“归”字上，描绘了牛羊徐徐归村的情景，使人很自然地联想起《诗经·王风·君子于役》里的几句诗：“鸡栖于埘，日之夕矣，羊牛下来。君子于役，如之何勿思？”诗人痴情地目送牛羊归村，直至没入深巷。就...", "authors": ["傅如", "一"], "pressName": "上海辞书出版社"}]', '《批点唐音》：晚色妙。
《唐诗镜》：景色依然。
《汇编唐诗十集》：唐云：右丞妙于田家，此是其得意作。
《唐诗选脉会通评林》：王世贞曰：田家本色，无一字淆杂，陶诗后少见。
《唐诗归》：钟云：厚风（「野老」句下）。
《唐诗评选》：通篇用「即此」二字括收。前八句皆情语，非景语，属词命篇，总与建安以上合辙。
《古唐诗合解》：《田家》诸作，储、王并推，写境真率中有静气。
《唐贤三昧集笺注》：此瓣香陶柴桑。顾云：「田夫」二句恬澹。又云：「即此」二句冲古。
《网师园唐诗笺》：田家情事如绘（「野老」句下）。
《唐贤清雅集》：真实似靖节，风骨各别，以终带文士气。', 'center', 1416670839, '57b90d44df0eea0063354354', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10489, '塞下曲 · 其二', NULL, 317, 202, 2, 3, '王昌龄', NULL, 10051, '57b91963128fe10054ca5788', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/1771140/14260115.htm', '', '饮马渡秋水，水寒风似刀。
平沙日未没，黯黯见临洮。
昔日长城战，咸言意气高。
黄尘足今古，白骨乱蓬蒿。', '此诗为王昌龄《塞下曲四首》组诗的第二首。以长城为背景，描绘战争的悲惨残酷。诗的前四句写塞外晚秋时节，平沙日落的荒凉景象；后四句写长城一带，历来是战场，白骨成丘，景象荒凉。全诗写得触目惊心，表达了非战思想。', '饮（yìn）马：给马喝水。
平沙：广漠的沙原。
黯（àn）黯：昏暗模糊的样子。
临洮：古县名，秦置，治所在今甘肃岷县，以临近洮水得名。秦筑长城，西起于此，故有“昔日长城战”之语。
昔：一作“当”。
长：一作“龙”。
足：一作“漏”，一作“是”。
蓬蒿：蓬草蒿草之类杂草。', '牵马饮水渡过了那大河，水寒刺骨秋风如剑如刀。
沙场广袤夕阳尚未下落，昏暗中看见遥远的临洮。
当年长城曾经一次鏖战，都说戍边战士的意气高。
自古以来这里黄尘迷漫，遍地白骨零乱夹着野草。', NULL, '', 'center', 1416739670, '57b95210d342d3005ac9f181', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10470, '西施咏', NULL, 356, 394, 1, 1, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/344209.htm', '', '艳色天下重，西施宁久微？
朝为越溪女，暮作吴宫妃。
贱日岂殊众，贵来方悟稀。
邀人傅脂粉，不自著罗衣。
君宠益娇态，君怜无是非。
当时浣纱伴，莫得同车归。
持谢邻家子，效颦安可希！', '诗人借西施从平民到宫廷宠妃的历史典故，来揭示人生浮沉，全凭际遇的炎凉世态，并表达对小人的嘲讽，揭露当时社会上潜藏的危机，抒发诗人怀才不遇的不平与感慨；借世人只见显贵时的西施之美，表达对势利小人的嘲讽；借「朝为越溪女」的西施「暮作吴宫妃」后的骄纵，讥讽那些由于偶然机遇受到恩宠就趾高气扬、不可一世的人；借效颦的东施，劝告世人不要为了博取别人赏识而故作姿态，弄巧成拙。', '西施：《吴越春秋》：「苧萝山鬻薪之女，曰西施。郑旦，饰以罗谷，教以容步，三年学成而献于吴。」
傅脂粉：《史记》：「孝惠时，郎侍中皆傅脂粉。」
浣纱：《寰宇记》：「会稽县东有西施浣纱石。」《水经注》：「浣纱溪在荆州，为夷陵州西北，秋冬之月，水色净丽。」
持谢：奉告。
效颦：《庄子》西施病心而颦，其里之丑人见而美之，归亦捧心而效其颦，富人见之，闭门而不出，贫人见之，挈妻子而去之，彼知美颦而不知颦之所以美。按：颦古作膑。
安可希：怎能希望别人的赏识。', '艳丽的姿色向来为天下器重，美丽的西施怎么能久处低微？
原先她是越溪的一个浣纱女，后来却成了吴王宫里的爱妃。
贫贱时难道有什么与众不同？显贵了才惊悟她丽质天下稀。
曾有多少宫女为她搽脂敷粉，她从来也不用自己穿著罗衣。
君王宠幸她的姿态更加娇媚，君王怜爱从不计较她的是非。
昔日一起在越溪浣纱的女伴，再不能与她同车去来同车归。
奉告那盲目效颦的邻人东施，光学皱眉而想取宠并非容易！', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d9b", "shortContent": "此诗作于天宝年间。在这盛唐时期，繁华的盛世下却掩饰着各式各样严峻的政治危机。朝廷大权沦丧于奸诈小人之手，纨绔子弟凭借裙带关系飞黄腾达，而真正的才俊却无人赏识，只得空叹满腹经纶无以报国。在这一世事风气下，诗人借着美人西施的故事，对其见闻表达出自己的感慨与思考。\n\n具有“沉鱼”之貌的美人西施，被越王勾践献与吴王夫差，成功离间了吴王与其大将伍子胥的关系，帮助越国更加顺利地灭了吴国。\n\n首句“艳色天下重，...", "authors": ["孟佳"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "6464798830675327e187ecdf", "shortContent": "西施是历代咏史诗最常出现的女性形象之一。据《越绝书》《吴越春秋》等杂史记载，春秋吴越战争期间，越国败于吴国，乃征国中绝色献于吴王，以丧其志，祸其国。西施原为越国苎萝山鬻薪、浣纱女，以美色入选，深受吴王宠爱，后越国果然反败为胜。此事作为“美色误国”“女祸论”的例证，是历代文人墨客咏叹的绝佳题材，代不乏作。至于西施的个人的命运、结局，亦是命运无常、红颜薄命论的最好注脚，这也是西施题材咏史诗的另一常见意...", "authors": ["石晓玲"], "pressName": "上海辞书出版社"}]', '唐·殷璠：维诗词秀雅，意新理惬，一字一句，皆出常境。
宋·苏東坡：味摩诘之诗，诗中有画；观摩诘之画，画中有诗。
明·鍾退谷《唐诗归》：情艳诗到极深细、极委曲处，非幽静人原不能理会，此右丞所以妙于情诗也。彼专以禅寂闲居求右丞幽静者，真浅且浮矣。
清·王船山《唐诗评选》：讽刺亦褊，其转折浑成，犹有元韵。
清·沈歸愚《唐诗别裁集》：写尽炎凉人眼界，不为题缚，乃臻斯诣；入后人手，徵引导故实而已。
', 'center', 1416670979, '57b961132e958a005fa8b434', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10471, '秋登兰山寄张五', NULL, 336, 266, 2, 2, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383032.htm', '', '北山白云里，隐者自怡悦。
相望试登高，心随雁飞灭。
愁因薄暮起，兴是清秋发。
时见归村人，沙行渡头歇。
天边树若荠，江畔洲如月。
何当载酒来，共醉重阳节。', '此诗围绕清秋季节登高来写，表达了对友人的思念之情。先写为望友人而登高，故“心随雁飞灭”。因薄暮时思念之“愁”和清秋之“兴”无法排遣，更因登高而望，只见“归村人”，而不见友人踪影，所以要相邀重阳节携酒登高而醉。全诗用极洗练严谨的语言，描绘了登高所见的清秋薄暮景色，其中“天边树若荠，江畔洲如月”二句历来脍炙人口。', '兰山：一作“万山”。万山，一名汉皋山，又称方山、蔓山，在湖北襄阳西北十里。张五：一作“张子容”，兄弟排行不对，张子容排行第八。有人怀疑张五为张八之误。
“北山”二句：晋陶弘景《诏问山中何所有赋诗以答》：“山中何所有？岭上多白云。只可自怡悦，不堪持赠君。”这两句由此变化而来。北山：指张五隐居的山。北：一作“此”。隐者：指张五。
相望：互相遥望。试：一作“始”。
“心随”句：又作“心飞逐鸟灭”、“心随飞雁灭”、“心随鸟飞灭”等。
薄暮：傍晚，太阳快落山的时候。《楚辞·天问》：“薄暮雷电，归何忧？厥严不奉，帝何求？”
清秋：明净爽朗的秋天。晋殷仲文《南州桓公九井作》诗：“独有清秋日，能使高兴尽。”一作“清境”。
归村人：一作“村人归”。
沙行：一作“沙平”，又作“平沙”。渡头：犹渡口。过河的地方。
“天边”二句：隋薛道衡《敬酬杨仆射山斋独坐》中有：“遥原树若荠，远水舟如叶。”这两句似是据此变化而成。荠：荠菜。洲：又作“舟”。
何当：商量之辞，相当于”何妨“或”何如“。
重阳节：古以九为阳数之极。九月九日故称“重九”或“重阳”。魏晋后，习俗于此日登高游宴。', '面对北山岭上白云起伏霏霏，山中隐者自己能把欢欣品味。
我试着登上高山是为了遥望，心情早就随着鸿雁远去高飞。
忧愁每每是薄暮引发的情绪，兴致往往是清秋招致的氛围。
在山上时时望见回村的人们，走过沙滩坐在渡口憩息歇累。
远看天边的树林活像是荠菜，俯视江畔的沙洲好比是弯月。
什么时候你能载酒到这里来，重阳佳节咱们开怀畅饮共醉。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9290d635634aee3deaa6", "shortContent": "这是一首怀人之作。张五名子容，隐居于襄阳岘山南约两里的白鹤山。孟浩然园庐在岘山附近，因登岘山对面的万山以望张五，并写诗寄意。全诗情随景生，而景又烘托情，两者紧密联系，真做到了情景交融，浑然一体。情飘逸而真挚，景清淡而优美，为孟诗代表作之一。\n晋代陶弘景《答诏问山中何所有》云：“山中何所有，岭上多白云。只可自怡悦，不堪持赠君。”孟浩然这首诗开头两句就从陶诗脱化而来。\n三、四两句起，进入题意。“相望”...", "authors": ["李景白"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d9c", "shortContent": "这是一首赠友人诗。张五，名子容，是孟浩然的好友，二人同隐鹿门山。“秋登”表明诗人秋日登高，遥想好友。\n\n一、二句是由晋时陶弘景《诏问山中何所有赋诗以答》诗中的“山中何所有？岭上多白云。只可自怡悦，不堪持赠君”变化而来。“自怡悦”表现了诗人怡然自得的心境，亦表明诗人登高眺望的原因之一，即自娱自乐，享受美景。而三、四句则表明了另一层原因，“登高”缘起于“相望”，为了眺望好友隐归的远山。登上那藏匿于片片...", "authors": ["孟佳"], "pressName": "崇文书局"}]', '《苕溪渔隐丛话》引《复斋漫录》语：颜之推《家训》云：“《罗浮山记》：‘望平地树如荠’。故戴皓诗‘长安树如荠’。有人《咏树》诗：‘遥望长安荠’，此耳学之过也。”余因读浩然《秋登万（兰）山》诗：“天边树若荠，江畔洲如月。”乃知孟真得皓意。
《王孟诗评》：刘云：朴而不厌。
《升庵诗话》：《罗浮山记》云：“望平地树如荠。”自是俊语。梁戴皓诗“长安树如荠”，用其语也。后人翻之益工，薛道衡诗：“遥原树若荠，远水舟如叶。”孟浩然诗：“天边树若荠，江畔洲如月。”
《唐贤三昧集笺注》：刘云：“时见”二句，其俚如此。
《唐贤清雅集》：超旷中独饶劲健，神味与右丞稍异，高妙则一也。结出主意，通首方着实。
《历代诗评注读本》：“天边”、“江畔”两句，摹写物象，超然入神。', 'center', 1416671148, '57b8e6d62e958a005fa4b403', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10472, '夏日南亭怀辛大', NULL, 539, 266, 2, 5, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383048.htm', '', '山光忽西落，池月渐东上。
散发乘夕凉，开轩卧闲敞。
荷风送香气，竹露滴清响。
欲取鸣琴弹，恨无知音赏。
感此怀故人，终宵劳梦想。', '此诗描绘了夏夜乘凉的悠闲自得，抒发了诗人对老友的怀念。开头写夕阳西下与素月东昇，为纳凉设景；三、四句写沐后纳凉，表现闲情适意；五、六句由嗅觉继续写纳凉的真实感受；七、八句写由境界清幽想到弹琴，想到「知音」，从纳凉过渡到怀人；最后写希望友人能在身边共度良宵而生梦。全诗写景状物细腻入微，语言流畅自然，情境浑然一体，诗味醇厚，意韵盎然，给人一种清闲之感。', '辛大：孟襄阳的朋友，排行老大，名不详，疑即辛谔。
山光：傍山的日光。
落：一作「发」。
池月：池边的月色。
东上：从东面昇起。
散发：古人男子平时束发戴帽，这里表现的是作者放浪不羁的惬意。
开轩：开窗。
卧闲敞：躺在幽静宽敞的地方。
清响：极微细的声响。
鸣琴：琴。用阮籍《咏怀》「夜中不能寐，起坐弹鸣琴」诗意。
恨：遗憾。
感此：有感于此。
终宵：一作「中宵」，中夜、半夜。
劳：苦于。
梦想：想念。', '山上夕阳慢慢向西落，池塘上的月亮渐渐东昇。
我披散着头发尽享清凉，推开窗户我悠闲地躺着。
微风吹拂荷花清香怡人，竹叶滴落露水声音清脆。
想要取出鸣琴弹奏一曲，可惜没有知音前来欣赏。
如此美景更加思念老友，日夜都在梦中想念着他。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9290dbb8b379ee095952", "shortContent": "浩然诗的特色是“遇景入咏，不拘奇抉异”（皮日休《郢州孟亭记》），虽只就闲情逸致作轻描淡写，往往能引人渐入佳境。《夏日南亭怀辛大》是有代表性的名篇。\n诗的内容可分两部分，既写夏夜水亭纳凉的清爽闲适，同时又表达对友人的怀念。“山光忽西落，池月渐东上”，开篇就是遇景入咏，细味却不止是简单写景，同时写出诗人的主观感受。“忽”、“渐”二字运用之妙，在于它们不但传达出夕阳西下与素月东升给人实际的感觉（一快一慢...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0f3", "shortContent": "浩然诗的特色是“遇景入咏，不拘奇抉异”（皮日休《郢州孟亭记》），虽只就闲情逸致作轻描淡写，往往能引人渐入佳境。《夏日南亭怀辛大》是有代表性的名篇。\n\n诗的内容可分两部分，即写夏夜水亭纳凉的清爽闲适，同时又表达对友人的怀念。“山光忽西落，池月渐东上”，开篇就是遇景入咏，细味却不止是简单写景，同时写出诗人的主观感受。“忽”“渐”二字运用之妙，在于它们不但传达出夕阳西下与素月东升给人实际的感觉（一快一慢...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d9d", "shortContent": "这首诗写夏夜池边水亭乘凉兼怀友人，写出了闲适自得的情趣，表达了知音难觅的感慨。夏日纳凉，本是人间细琐之事，但作者于细微处见深情，诚如《唐诗镜》评孟诗云：“孟浩然诗材虽浅窘，然语气清亮，诵之有泉流石上、风来松下之音。”\n\n“山光忽西落，池月渐东上”，开篇自然入笔，《王孟诗评》说：“起处似陶，清景幽情，洒洒楮墨间。”日落西山，一轮明月渐渐升起，月影在池水中荡漾。“忽”、“渐”二字极妙，日落月起，一快一...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127036c9ebcc6fbea1a38c", "shortContent": "这首诗写夏夜池边水亭乘凉时的清爽闲适和对友人的怀念，写出闲适自得的情趣，表达出知音难觅的感慨。夏日纳凉，本是人间细琐之事，但作者于细微处见深情，诚如《唐诗镜》评孟诗云：“孟浩然材虽浅窘，然语气清亮，诵之有泉流石上、风来松下之音。”这首诗堪称代表。\n\n“山光忽西落，池月渐东上”，开篇自然入笔，《王孟诗评》说此处“起处似陶，清景幽情，洒洒楮墨间”。日落西山，一轮明月渐渐升起，月影在池水中荡漾。“忽”、...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '《王孟诗评》：刘云：起处似陶，清景幽情，洒洒楮墨间。
《批选唐诗》：写景自然，不损天真。
《唐诗选脉会通评林》：周珽曰：此倒薤垂露书也。大小篆皆出其下，何况俗书！陈继儒曰：风入松而发响，月穿水而露痕，《兰山》、《南亭》二诗深静，真可水月齐辉，松风比籁。
《此木轩论诗汇编》：“荷风送香气，竹露滴清响”，韦诗多似此。
《唐贤三昧集笺注》：“卧闲敞”字甚新奇。“荷风”二句一读，使人神思清旷。
《唐诗别裁》：“荷风”、“竹露”，佳景亦佳句也。外又有“微云淡河汉，疏雨滴梧桐”句，一时叹为清绝。
《网师园唐诗笺》：“荷风”、“竹露”亦凡写夏景者所当有，妙在“送”字、“滴”字耳。
《唐贤清雅集》：清旷，与右丞《送宇文太守》同调，气色较华美。
《王闿运手批唐诗选》：爽朗（“散发”二句下）。', 'center', 1416671240, '57b9152d7db2a20054274764', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10473, '宿业师山房待丁大不至', NULL, 346, 266, 2, 2, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/1432938.htm', '', '夕阳度西岭，群壑倏已暝。
松月生夜凉，风泉满清听。
樵人归欲尽，烟鸟栖初定。
之子期宿来，孤琴候萝径。', '此诗写诗人夜宿山寺中，于山径之上等待友人的到来，而友人不至的情景。前六句尽写夜色：夕阳西下，万壑蒙烟，凉生松月，清听风泉，樵人归尽，暮鸟栖定；后两句写期待故人来宿而未至，于是抱琴等待。全诗不仅表现出山中从薄暮到深夜的时令特征，而且融合着诗人期盼知音的心情，境界清新幽静，语言委婉含蓄。', '业师：业禅师的简称，法名业的僧人。一作“来公”。
山房：山中房舍，指佛寺。
待：一作“期”。
丁大：作者友人。名凤，排行老大，故称丁大，有才华而不得志。
度：过、落。
壑：山谷。
倏（shū）：忽然。
满清听：满耳都是清脆的响声。
樵人：砍柴的人。
烟鸟：雾霭中的归鸟。
之子：这个人。之，此。子，古代对男子的美称。
宿来：一作“未来”。
孤琴：一作“孤宿”，或作“携琴”。', '夕阳越过了西边的山岭，千山万壑忽然昏暗静寂。
月照松林更觉夜晚清凉，风声泉声共鸣分外清晰。
山中砍柴人差不多走尽，烟霭中鸟儿刚归巢安息。
丁大约定今晚来寺住宿，独自抚琴站在山路等你。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f19c305cf0801816d9e", "shortContent": "诗人孟浩然与友人丁大相约同宿于僧人业师的僧房，但好友丁大却久候不至。孟浩然则将等待友人之时所见的景色变化、心境如何作成此诗。\n全诗前六句为写景，从天色渐瞑、夕阳西下直写至夜色渐浓、皓月直升。“夕阳度西岭，群壑倏已暝。”首句描写的是暮色之景。夕阳在西边的山岭缓缓落下，千山万壑刹那间忽已昏暗静谧。“松月生夜凉，风泉满清听。”此句描绘的是夜色降至的美妙景色。皓然月色照拂在浩浩松林之上，越发为这夜色添了几...", "authors": ["孟佳"], "pressName": "崇文书局"}]', '《王孟诗评》：此诗愈淡愈浓、景物满眼，而清淡之趣更浮动，非寂寞者。
《唐诗选脉会通评林》：周珽曰：“生”、“满”二字静中含动，“尽”、“定”二字动中得静，禅语妙思。伯敬谓“尽”字不如用“稀”字，那知“尽”字得暮宿真境。
《唐诗摘钞》：与王右丞《过香积寺》作几不相上下，但王作调平时较浑，此作调高而语过峭，此处微输一筹。
《唐贤三昧集笺注》：三、四使人生尘外之想。幽绝。
《唐诗别裁》：山水清音，悠然自远，末二句见“不至”意。
《茧斋诗谈》：不做作清态，正是天真烂漫。
《唐贤清雅集》：清秀彻骨，是襄阳独得处。
《王闿运手批唐诗选》：常语清妙。', 'center', 1416671357, '57b8ff745bbb50005b781aff', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10474, '同从弟南斋玩月忆山阴崔少府', NULL, 234, 202, 2, 1, '王昌龄', NULL, 10051, '57b91963128fe10054ca5788', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383050.htm', '', '高卧南斋时，开帷月初吐。
清辉澹水木，演漾在窗户。
冉冉几盈虚，澄澄变今古。
美人清江畔，是夜越吟苦。
千里共如何，微风吹兰杜。', '这首观月怀友的古体诗，写得恬淡悠远。诗的前六句着重写开窗所见的月色，清幽的月色引起诗人深刻的思考，深深的慨叹反映了诗人对人生的珍视。最后四句是怀友。诗人驰骋想象，想象在这月光普照的夜晚，崔少府也一定在曹娥江畔苦吟，思念自己，真是人隔千里，明月相共。最后采用传统的「引类譬喻」的手法，以兰草、杜若比崔少府，其芬芳之香随处可闻。', '从弟：堂弟。
斋：书房。
山阴：今浙江绍兴。
崔少府：即崔国辅，开元十四年（726）进士及第，授职山阴（浙江绍兴）县尉。少府，官名，秦置，为九卿之一，次于县令。唐代科第出身的士子也任其职。
帷：一作「帐」，帘幕。
澹（dàn）：水缓缓地流。
演漾：水流摇荡。
冉（rǎn）冉：一作「荏苒」，渐渐。指时间的推移。几盈虚：月亮圆缺反复多次。
澄澄：清亮透明，指月色。
美人：旧时也指自己思暮的人，这里指崔少府。
越吟：楚国庄舄（xì）唱越歌以寄托乡思。这是以越切山阴，意谓想必在越中苦吟诗篇。
共：一作「其」。
如何：一作「何如」。
吹：一作「出」。
兰杜：兰花和杜若，都是香草。兰，一作「芳」。', '我和从弟在南斋高卧的时候，掀开窗帘玩赏那初升的玉兔。
淡淡月光泻在水上泄在树上，轻悠悠的波光涟漪荡入窗户。
光阴苒苒这窗月已几盈几虚，清光千年依旧世事不同今古。
德高望重崔少府在清江河畔，他今夜必定如庄舄思越之苦。
千里迢迢可否共赏醉人婵娟？微风吹拂着清香四溢的兰杜。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ac305cf0801816d9f", "shortContent": "此诗为赏月兼怀友人之作。其主题为“玩月”，所以诗歌前六句皆与月色相关。而后四句，即是诗人怀想友人崔少府的感慨。王昌龄不以古体诗见长，而这首古体诗却写得恬淡悠远，亦令人心生怡然之意。\n首句“高卧南斋时，开帷月初吐”，诗人高卧南斋，推开帷幕，见银月初露。“高卧”表现了诗人怡然自得的神态。而一“初”字，描绘出了明月初上，月色微盈的美妙景象。\n而后皓月渐升，“清辉澹水木，演漾在窗户”。月亮的清辉缓缓流泻在...", "authors": ["孟佳"], "pressName": "崇文书局"}]', '', 'center', 1416671512, '57b9892a7db2a20054f70dca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10475, '寻西山隐者不遇', NULL, 210, 14, 1, 1, '丘为', NULL, 10120, '57b9a054a633bd005d2dca9b', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383051.htm', '', '绝顶一茅茨，直上三十里。
扣关无僮仆，窥室唯案几。
若非巾柴车，应是钓秋水。
差池不相见，黾勉空仰止。
草色新雨中，松声晚窗里。
及兹契幽绝，自足荡心耳。
虽无宾主意，颇得清净理。
兴尽方下山，何必待之子。', '此诗描写隐逸生活情趣，其重点不是写不遇的失望，而是抒发对隐居环境的迷恋，表现了有心去寻、无心相见的飘逸。诗的前八句，写隐者独居高处，远离尘嚣，寻访者不辞山高，等到叩关无人，才略生怅惘，于是猜想隐者乘车出游，临水垂钓，表现隐者的生活恬适雅趣；后八句宕开一层，写周围的草色松声使寻访者陶然，结句暗用了著名的晋王子猷雪夜访戴的故事来自抒旷怀，因而寻访不遇亦无所谓，使其悟出隐者生活的情趣。全诗构思新颖，意蕴深远，堪称佳作。', '茅茨：茅屋。
扣关：敲门。
僮仆：指书童。
唯案几：只有桌椅茶几，表明居室简陋。
巾柴车：指乘小车出游。
钓秋水：到秋水潭垂钓。
差池：原为参差不齐，这里指此来彼往而错过。
黾勉：勉力，尽力。
仰止：仰望，仰慕。
“草色新雨中，松声晚窗里”句：这是诗人经过观察后亦真亦幻地描写隐者居所的环境。
及兹：来此。
契：惬意。
荡心耳：涤荡心胸和耳目。
“及兹契幽绝，自足荡心耳”句：一本无此二句。
“虽无宾主意，颇得清净理”句：意谓虽没有受到主人待客的厚意，却悟得了修养身心的真理。
兴尽：典出《世说新语》晋王子猷雪夜访戴的故事。
之子：一作“夫子”，这个人，这里指隐者。', '高高的山顶上有一座茅屋，从山下走上去足有三十里。
轻扣柴门竟无童仆回问声，窥看室内只有桌案和茶几。
主人不是驾着巾柴车外出，一定是到秋水碧潭去钓鱼。
错过了时机不能与他见面，空负了殷勤仰慕一片心意。
新雨中草色多么青翠葱绿，晚风将松涛声送进窗户里。
这清幽境地很合我的雅兴，足可以把身心和耳目荡涤。
我虽然还没有和主人交谈，却已经领悟到清净的道理。
玩到兴尽就满意地下山去，何必非要和这位隐者相聚。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92992e6a6b501f95bfb5", "shortContent": "这是一首描写隐逸高趣的诗。从思想上说，这类诗在中国古典诗歌中所在多有，并没有什么分外高奇的地方，但细读起来，又令人感到有些新颖别致。这新颖别致来自什么地方呢？主要来自构思。我们看，这首诗以“寻西山隐者不遇”为题，到山中专程去寻访隐者，当然是出于对这位隐者的友情或景仰了，而竟然“不遇”，按照常理，这一定会使访者产生无限失望、惆怅之情。但却出人意料之外，这首诗虽写“不遇”，却偏偏把隐者的生活和性格表现...", "authors": ["禇斌杰"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ac305cf0801816da0", "shortContent": "入山寻隐者而不遇，这本该是件令人失望惆怅的事情。而本诗的特别之处就在于诗人虽未能够遇见隐士，却另辟蹊径，将隐士的生活、山中的妙境淋漓尽致地描绘出来，表现了诗人的幽情雅趣与旷达情怀。\n\n“绝顶一茅茨，直上三十里。”“茅茨”即茅屋。“绝顶”、“直上”突出了茅屋所处之地的险峻和寻找它的艰难，也点明了隐士远离俗世的归隐之心和诗人不辞辛劳的探访之心。\n\n“扣关无僮仆，窥室唯案几”，写诗人寻隐者不遇。轻叩柴门...", "authors": ["孟佳"], "pressName": "崇文书局"}]', '萧涤非《唐诗鉴赏辞典》：这是一首描写隐逸高趣的诗。诗以“寻西山隐者不遇”为题，到山中专程去寻访隐者，当然是出于对这位隐者的友情或景仰了，而竟然“不遇”，按照常理，这一定会使访者产生无限失望、惆怅之情。但却出人意料之外，这首诗虽写“不遇”，却偏偏把隐者的生活和性格表现得历历在目；却又借题“不遇”，而淋漓尽致地抒发了自己的幽情雅趣和旷达的胸怀，似乎比相遇了更有收获，更为心满意足。正是由于这一立意的新颖，而使这首诗变得有很强的新鲜感。', 'center', 1416671756, '57b2c7c7a341310060fe714b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10476, '宿王昌龄隐居', NULL, 313, 55, 1, 1, '常建', NULL, 10117, '57b9bf5ac4c9710061480f1c', '唐', 'shi', '诗', 'http://baike.baidu.com/view/352770.htm', '', '清溪深不测，隐处唯孤云。
松际露微月，清光犹为君。
茅亭宿花影，药院滋苔纹。
余亦谢时去，西山鸾鹤群。', '此诗通过对王昌龄隐居处自然环境的细致描绘，赞颂了王昌龄的清高品格和隐居生活的高尚情趣。开头两句写王昌龄隐居之所在、乃隐居佳境，别有洞天；中间四句写夜宿此地之后，顿生常住之情，即景生情，一目了然；最后两句写自己的归志，决心跃然。全诗描述平实，意味含蓄，在平易的写景中蕴含着比兴寄喻，意在言外，发人深思。
这是一首写山水的隐逸诗。开头两句写王昌龄隐居之所在、乃隐居佳境，别有洞天。中间四句写夜宿此地之后，顿生常住之情，即景生情，一目了然。最后两句写自己的归志，决心跃然。全诗善于在平易的写景中，蕴含深长的比兴寄喻，形象明朗，诗旨含蓄，而意向显豁，发人联想。“茅亭宿花影，药院滋苔纹”可见炼字功深，又可作对仗效法。', '测：一作“极”。
隐处：隐居的地方。唯：只有。
犹：还，仍然。
宿：比喻夜静花影如眠。
药院：种芍药的庭院。滋：生长着。
余：我。谢时：辞去世俗之累。
鸾鹤：古常指仙人的禽鸟。群：与……为伍。', '清溪之水深不可测，隐居之处只有孤云。
松林中间明月微露，洒下清辉似为郎君。
茅亭花影睡意正浓，芍药园圃滋生苔纹。
我也想要谢绝世俗，来与西山鸾鹤合群。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92bf03048e64fbd914c3", "shortContent": "这是一首山水隐逸诗，在盛唐已传为名篇；到清代，更受“神韵派”的推崇，同《题破山寺后禅院》并为常建代表作品。\n常建和王昌龄是开元十五年（727）同科进士及第的宦友和好友，但在出仕后的经历和归宿却不大相同。常建“沦于一尉”，只做过盱眙县尉，此后便辞官归隐于武昌樊山，即西山。王昌龄虽然仕途坎坷，却并未退隐。题曰“宿王昌龄隐居”，一是指王昌龄出仕前隐居之处，二是说当时王昌龄不在此地。\n王昌龄及第时大约已有...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ac305cf0801816da2", "shortContent": "常建为盛唐时著名诗人，其存诗虽少，却佳作迭出，《四库全书总目》誉其“卓然与王、孟抗行者，殆十之六七”。此五律与诗人的《题破山寺后禅院》，并列为唐代隐逸诗的名篇。\n\n首联叙好友王昌龄隐居之所在。这是一片隐居修身的好去处，清澈的溪水流入石门山的深处，幽静的深山中早已不见主人的踪迹，唯留下孤寂的白云与天地相伴。此联既是实写，也属虚意。天宝中叶，常建辞官西归，途经王昌龄隐居的石门山，在此夜宿，可惜室去人空...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706c9761253910e9053e", "shortContent": "常建为盛唐时著名诗人，其存诗虽少，却佳作迭出，《四库全书总目》誉其“卓然与王、孟抗行者，殆十之六七”。此五律与诗人的《题破山寺后禅院》，并列为唐代隐逸诗的名篇。\n\n首联叙好友王昌龄隐居之所在。这是一片隐居修身的好去处，清澈的溪水流人石门山的深处，幽静的深山中早已不见主人的踪迹，惟留下孤寂的白云与天地相伴。此联既是实写，也属虚意。天宝中叶，常建辞官西归，途经王昌龄隐居的石门山，在此夜宿，可惜室去人空...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127105c9ebcc6fbea1a465", "shortContent": "常建为盛唐时著名诗人，其存诗虽少，却佳作迭出，《四库全书总目》誉其“卓然与王、孟抗行者，殆十之六七”。此五律与诗人的《题破山寺后禅院》，并列为唐代隐逸诗的名篇。\n\n首联叙好友王昌龄隐居之所在。这是一片隐居修身的好去处，清澈的溪水流入石门山的深处，幽静的深山中早已不见主人的踪迹，唯留下孤寂的白云与天地相伴。此联既是实写，也属虚意。天宝中叶，常建辞官西归，途经王昌龄隐居的石门山，在此夜宿，可惜室去人空...", "authors": ["乐云"], "pressName": "崇文书局"}]', '《唐诗归》：钟云：幽严（“隐处”句下）。谭云：是昌龄一幅小像。钟云：“为”字说林月灵妙（“松际”一联下）。
《唐诗选脉会通评林》：周敬曰：征君诗神气清朗，如此篇与《题破山寺》意趣俱到，可谓吃着丹头。地水火风皆可助我变化者，是天然学问人，刘辰翁曰：清远沉冥，不类色相，景同意别。
《唐诗归折衷》：唐云：字字超凡。
《唐诗成法》：王之清才，死后松月犹若绻恋，生时不见用，此所以感而欲隐也。读此方知李颀“物在人亡”一首俗浅。
《唐诗别裁》：清澈之笔，中有灵悟。', 'center', 1416671879, '57b90fbfd342d3005ac7a1c9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10477, '春泛若耶溪', NULL, 241, 24, 1, 2, '綦毋潜', NULL, 10121, '57bc533c7db2a20068d17a46', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383053.htm', '', '幽意无断绝，此去随所偶。
晚风吹行舟，花路入溪口。
际夜转西壑，隔山望南斗。
潭烟飞溶溶，林月低向后。
生事且弥漫，愿为持竿叟。', '全诗扣紧题目中的“泛”字，在曲折回环的扁舟行进中，对不同的景物进行描摹，使寂静的景物富有动感，恍惚流动，流露轻松舒适之感。
开首两句以“幽意”点出了全诗的主旨，是幽居独处，放任自适的意趣。因此，驾舟出游，任其自然，流露了随遇而安的情绪。接着写泛舟的时间、路线和沿途景物，以春江、月夜、花路、扁舟等景物，创造出一种幽美、寂静、迷蒙的境界。最后两句写心怀隐居之人，在此环境中，愿作持竿垂钓的隐者，追慕“幽意”的人生。', '若耶溪：在今浙江省绍兴市东南，相传为西施浣纱处。《寰宇记》记载：“若耶溪在会稽县东二十八里。”《水经注》记载：“若耶溪水，上承嶕岘麻溪，溪之下孤潭周数亩，麻潭下注若耶溪。水至清，照众山倒影，窥之如画。”
幽意：寻幽的心意。
偶：遇。刘熙《释名·释亲属》：“二人相对遇也。”
晚：一作“好”。
花路：一路鲜花。
际夜：至夜。
壑（hè）：山谷。
南斗：星宿名称，夏季位于南方上空。古以二十八宿与地理相应来划分区域，称分野，南斗与吴越相应。
潭烟：水潭上如烟的水汽夜雾。烟，雾气。
溶溶：形容汽雾柔和迷离。
生事：世事。
弥漫：渺茫无尽。
持竿叟：持竿垂钓的老翁。竿，指钓竿。', '我寻幽探胜的心意没有定止，随着一路看见的景色生发不已。晚风吹送我的行舟，沿着开满鲜花的河岸荡入溪口。星夜又转过西边的山岭，隔山仰望天上的南斗。潭底升起溶溶的烟雾，林中月亮仿佛低落在行舟的背后。世事何等地纷繁渺茫，不如做一名隐居的钓叟。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92932cee9a0c24ecf7bf", "shortContent": "这首五言古体诗大约是诗人归隐后的作品。若耶溪在今浙江绍兴市东南，相传为西施浣纱处，水清如镜，照映众山倒影，窥之如画。诗人在一个春江花月之夜，泛舟溪上，自然会滋生出无限幽美的情趣。\n开篇“幽意无断绝”句，以“幽意”二字透露了全诗的主旨，即幽居独处，不与世事，放任自适的意趣。这种“幽意”支配着他的人生，不曾“断绝”，因此，他这次出游只是轻舟荡漾，任其自然，故云“此去随所偶”。“偶”即“遇”。诗人在这里...", "authors": ["李敬一"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ac305cf0801816da1", "shortContent": "若耶溪，在今浙江绍兴，今称平水江。相传有七十二支流，自平水而北，会三十六溪之水，汇于禹陵，又分为两股，一脉流入鉴湖，一脉流北向入海。若耶溪风景如画，溪畔青山叠翠，溪流澄澈如镜，湖光山色，幽静深邃。\n\n綦毋潜归隐江东，泛舟若耶，以寄闲情，于是写下了这首《春泛若耶溪》。诗题已经把时间、地点、情事交代明确。季节为春天，万物生长，有溪边青山叠翠之美。情事是泛舟溪上，若耶溪是一路泛舟所在。\n\n首句云“幽意无...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312703bf2af4e09d55b6727", "shortContent": "若耶溪，在今浙江绍兴，今称平水江。溪畔青山叠翠，溪流澄澈如镜，相传有七十二支流。自平水而北，会三十六溪之水，汇于大禹陵，又分为两股，一脉流入鉴湖，一脉流走百里北向入海。若耶溪有群山峻岭，有道观寺庙。湖光山色，猿啼鸟鸣，幽静深邃。\n\n綦毋潜归隐江东，泛舟若耶，以寄闲情，于是写下了这首《春泛若耶溪》。诗题已经把时间、地点、情事交代明确。季节为春天，万物生长，有溪边青山叠翠之美。情事是泛舟溪上，若耶溪是...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312706ac305cf0801816fe5", "shortContent": "若耶溪，在今浙江绍兴，今称平江水。溪畔青山叠翠，溪流澄澈如镜，相传有七十二支流。自平水而北，会三十六溪之水，汇于大禹陵，又分为两股，一脉流入鉴湖，一脉流走百里北向入海。若耶溪有群山峻岭，有道观寺庙。湖光山色，猿啼鸟鸣，幽静深邃。\n\n綦毋潜归隐江东，泛舟若耶，以寄闲情，于是写下了这首《春泛若耶溪》。诗题已经把时间、地点、情事交代明确。季节为春天，万物生长，有溪边青山叠翠之美。情事是泛舟溪上，若耶溪是...", "authors": ["张春晓"], "pressName": "崇文书局"}]', '《唐诗解》：秀古。
《唐诗归》：钟云：有气力（“此去”句下）。谭云：好境（“花路”句下）。谭云：妙语浮出，如不经心手者。钟云：静中看出（“潭烟”二句下）。
《唐诗选脉会通评林》：陈继儒曰：遗其形迹、动乎天机，诗至此进乎技矣。
《历代诗法》：景色佳胜，呈露笔端。
《唐贤三昧集笺注》：第四奇句。第七五平，亦一异例也。
《王闿运手批唐诗选》：真景实赋，便成奇句。', 'center', 1416672070, '57b921630a2b58005c9356c3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10478, '与高适薛据同登慈恩寺浮图', NULL, 171, 405, 2, 1, '岑参', NULL, 10096, '57b97daec4c971005593ac34', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3321676.htm', '', '塔势如涌出，孤高耸天宫。
登临出世界，磴道盘虚空。
突兀压神州，峥嵘如鬼工。
四角碍白日，七层摩苍穹。
下窥指高鸟，俯听闻惊风。
连山若波涛，奔凑似朝东。
青槐夹驰道，宫馆何玲珑。
秋色从西来，苍然满关中。
五陵北原上，万古青濛濛。
净理了可悟，胜因夙所宗。
誓将挂冠去，觉道资无穷。', '唐玄宗天宝十一年（公元752年）秋，岑参自安西回京述职，相邀高适、薛据、杜甫、储光羲等同僚诗友，出城郊游，来到慈恩寺，见宝塔巍峨俊逸，拾级而上，触景生情，遂吟诗唱和以助兴。高适首唱，作《同诸公登慈恩寺塔》，其馀人相和，岑参此诗就是当时的和诗之一。
此诗前十八句描摹慈恩寺塔的孤高、突兀、超逸绝伦的气势，以及佛塔周围苍茫、古寂、清幽的环境，烘托出一派超脱虚空的气氛；末尾四句，抒发情怀，流露出怅惘之情。全诗主要描写了佛塔孤高危耸的情态，表达了作者登临后忽然领悟禅理，产生出世的念头，并暗寓对国是无可奈何的情怀。', '高适：唐朝边塞诗人，景县（今河北景县）人。薛据，荆南人，《唐诗纪事》作河中宝鼎人。开元进士，终水部郎中，晚年终老终南山下别业。
慈恩寺浮图：即今西安市的大雁塔，本唐高宗为太子时纪念其母文德皇后而建，故曰慈恩。浮图，原是梵文佛陀的音译，这里指佛塔。
涌出：形容拔地而起。
出世界：高出于人世的境界。世界，人世的境界。
磴（dèng）：石级。
盘：曲折。
突兀：高耸貌。
峥嵘（zhēngróng）：形容山势高峻。
鬼工：非人力所能。
四角：塔的四周。
碍：阻挡。
七层：塔本六级，后渐毁损，武则天时重建，增为七层。
惊风：疾风。
驰道：可驾车的大道。
宫馆：宫阙。
关中：指今陕西中部地区。
五陵：指汉代五个帝王的陵墓，即高祖长陵、惠帝安陵、景帝阳陵、武帝茂陵及昭帝平陵。
净理：佛家的清净之理。
胜因：佛教因果报应中的极好的善因。
夙：素来。
挂冠：辞官归隐。
觉道：佛教的达到消除一切欲念和物我相忘的大觉之道。', '宝塔宛如平地涌出，孤高巍峨耸入天宫。
登上去像走出人间，蹬踏梯道盘旋空中。
高峻突出镇定神州，峥嵘胜过鬼斧神工。
四角伸展挡住白日，七层紧紧连着苍穹。
下看飞鸟屈指可数，俯听山风呼啸迅猛。
山连山如波涛起伏，汹涌澎湃奔流向东。
青槐夹着笔直驰道，楼台宫殿何等玲珑。
秋天秀色从西而来，苍苍茫茫弥漫关中。
长安城北汉代五陵，万古千秋一派青葱。
清净佛理完全领悟。善因素来为人信从。
立誓归隐辞官而去，信奉佛道其乐无穷。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ac305cf0801816da3", "shortContent": "天宝十一年（752）秋，岑参与高适、薛据、杜甫、储光羲五人同登长安慈恩寺塔，五人均有诗记其事，岑诗以其雄奇峻拔，为世所称。慈恩寺浮图，即今陕西西安大雁塔，为唐高宗永徽三年（652）唐僧玄奘所建。\n\n“塔势如涌出，孤高耸天宫。”该诗起式即卓尔不凡，如“大将旗鼓相当，皆万人敌”。一“涌”字，化静势为动势，将巍然宝塔从地下涌出，凭空高耸之势衬托得淋漓尽致。此二句，奠定了全诗雄奇壮阔、苍劲挺拔的情感基调。...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127068f2af4e09d55b6774", "shortContent": "天宝十一载（752）秋，岑参与高适、薛据、杜甫、储光羲五人同登长安慈恩寺塔，五人均有诗记其事，岑诗以其雄奇峻拔，为世所称。慈恩寺浮图，即今陕西西安大雁塔，为唐高宗永徽三年（652）唐僧玄奘所建。\n\n“塔势如涌出，孤高耸天宫”。该诗起式即卓尔不凡，如“大将旗鼓相当，皆万人敌”。一“涌”字，化静势为动势，将巍然宝塔从地下涌出，凭空高耸之势衬托得淋漓尽致。此二句，奠定了全诗雄奇壮阔、苍劲挺拔的情感基调。...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270e0f2af4e09d55b67fe", "shortContent": "天宝十一年（752）年秋，岑参与高适、薛据、杜甫、储光羲五人同登长安慈恩寺塔，五人均有诗记其事，岑诗以其雄奇峻拔，为世所称。慈恩寺浮图，即今陕西西安大雁塔，为唐高宗永徽三年（652）唐僧玄奘所建。\n\n“塔势如涌出，孤高耸天宫”。该诗起式即卓尔不凡，如“大将旗鼓相当，皆万人敌”。一“涌”字，化静势为动势，将巍然宝塔从地下涌出，凭空高耸之势衬托得淋漓尽致。此二句，奠定了全诗雄奇壮阔、苍劲挺拔的情感基调...", "authors": ["乐云"], "pressName": "崇文书局"}]', '明·高棅《唐诗品汇》：唐人倡和之诗，多是感激，各臻其妙。……登慈恩寺塔诗，杜甫云：“高标跨苍穹，烈风无时休。俯视同一气，焉能辨皇州。”高适云：“秋风昨夜至，秦塞多清旷。千里何茫茫。五陵郁相望。”岑参云：“秋色从西来，苍然满关中。五陵北原上，万古青蒙蒙。”此类甚多，是皆雄浑悲壮，足以凌跨百代。
明·谭元春《唐诗归》：谭云：“从西来”妙，妙！诗人惯将此等无指实处说得确然，便奇（“秋色”句）。“万古”字入得博大，“青蒙蒙”字下得幽眇。秋色又四语写尽空远，少陵以“齐鲁青未了”五字尽之，详略各妙。（“万古”句）。又云：岑塔诗惟秋色四语，吋敌储光养、杜甫，馀写高远处俱有极力形容之迹。
明·袁宏道《唐诗训解》：极状塔高，布势有驰骋。
明·陆时雍《唐诗镜》：形状绝色，语气复雄。
明·李攀龙《唐诗选》：“下窥”二句，调高而占，凄然不堪再读。
明·周珽《唐诗选脉会通评林》：此等诗真狮子捉物，视兔如象。
明·毛先舒《诗辩坻》：“四角”二语，拙不入古，酷为钝语。至“秋色从西来，苍然满关中。五陵北原上，万古青蒙蒙”，词意奇工，陈隋以上人所不为，亦复不办，此处乃见李唐古诗真色。
清·刘邦彦《唐诗归折衷》：形容处皆板拙可憎（“峥嵘”句）。前幅尘气，后幅腐理，几不成诗。赖有“秋色”四语，一开眼界。
清·吴煊《唐贤三昧集笺注》：老杜、高、岑诸大家同登慈恩寺塔诗，如大将旗鼓相当，皆万人敌。
清·黄子云《野鸿诗的》：岑有“秋色正西来，苍然满关中。五陵北原上，方古青蒙渌”四语，洵称奇伟；而上下文不称，末乃逃入释氏，不脱伧父伎俩。
清·沈德潜《唐诗别裁》：登慈恩塔诗，少陵下应推此作，高达夫、储太祝皆不及也。
清·宋宗元《网师园唐诗笺》：句亦如涌出（首二句）。
清·张文荪《唐贤清雅集》：起句突兀。苍浑似刘司空、颜光禄，气更流逸。
清·王文濡《历代诗评注读本》：雄浑悲壮，凌跨百代，而“秋色”四句，写尽空远之景，尤令人神往不已。', 'center', 1416690315, '57b91bd5d342d3005ac80d0e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10479, '贼退示官吏', NULL, 127, 102, 1, 1, '元结', NULL, 10122, '57babb92128fe1005f8da377', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383055.htm', '癸卯岁，西原贼入道州，焚烧杀掠，几尽而去。明年，贼又攻永破邵，不犯此州边鄙而退。岂力能制敌与？盖蒙其伤怜而已。诸使何为忍苦征敛，故作诗一篇以示官吏。', '昔岁逢太平，山林二十年。
泉源在庭户，洞壑当门前。
井税有常期，日晏犹得眠。
忽然遭世变，数岁亲戎旃。
今来典斯郡，山夷又纷然。
城小贼不屠，人贫伤可怜。
是以陷邻境，此州独见全。
使臣将王命，岂不如贼焉？
今彼征敛者，迫之如火煎。
谁能绝人命，以作时世贤！
思欲委符节，引竿自刺船。
将家就鱼麦，归老江湖边。', '这是一首斥责统治者横征暴敛的诗作。诗序交代了历史背景，诗中表现了官吏不顾人民死活的社会现状。此诗对“今彼征敛者，迫之如火煎”的现象发出了愤怒的谴责，揭露了安史之乱以后官吏对人民横征暴敛的罪行，批判了征敛害民的官吏，控诉了官不如贼的黑暗社会，作者表示宁愿弃官归隐，也绝不做残害人民以邀功之人。全诗质朴自然，直抒胸臆，毫无雕饰之感。', '癸卯岁：即唐代宗广德元年（763年）。
道州：今湖南县道县。
永、邵：永州和邵州，今均属湖南省。
边鄙：边境。
与：通“欤”，吗。
昔岁：从前。
庭户：庭院。
洞壑（hè）：山洞，沟壑。
井：即“井田”；井税：这里指赋税。
晏：晚。
世变：指安史之乱所带来的社会动荡。
戎旃（zhān）：战旗，一说为军帐。
典：治理、掌管。
见全：被保全。
将王命：奉皇上的旨意。
绝：断绝。
委：弃。符节：古代朝廷传达命令或征调兵将用的凭证。委符节：辞官。
引竿：拿钓竿，代指隐居。刺船：撑船。
将：带着。就：靠近。
湖：一作“海”。', '癸卯年，西原贼人攻入道州城，焚烧杀戮掠夺，几乎扫光全城才走。第二年，贼人又攻打永州并占领邵州，却不侵犯道州边境而去。难道道州官兵能有力制敌吗？不过是蒙受贼人的哀怜而巳。催缴赋税的官吏为什么还如此忍心苦苦搜括呢？因此作诗一篇给官吏们看看。
我早年遇到了太平世道，在山林中隐居了二十年。
清泉水流经过我家门口，山涧洞谷对着我家门前。
田租赋税有个固定期限，日上三竿依然安稳酣眠。
忽然间遭遇到世道突变，数年来亲自从军上前线。
如今我来治理这个郡县，又遇到蛮夷来骚扰侵犯。
县城太小蛮夷无意洗劫，百姓贫穷他们也觉可怜。
因此他们攻陷邻县境界，唯有这个道州独自保全。
奉皇命来收租税的使臣，难道还比不上盗贼慈善？
现在那横征暴敛的官吏，催赋逼税恰如火烧油煎。
谁忍心断绝人民的生路，换取时世所称赞的忠贤？
我想辞去官职丢弃符节，拿起竹篙自己动手撑船。
带领全家回到鱼米之乡，告老归隐住在那江湖边。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b32e6a6b501f95c203", "shortContent": "此诗和《舂陵行》都是作者反映社会现实，同情人民疾苦的代表作，而在斥责统治者对苦难人民的横征暴敛上，此诗词意更为深沉，感情更为愤激。\n诗前的序交代了作诗的原委。癸卯岁，即唐代宗广德元年（763），十二月，广西境内的少数民族“西原蛮”发动了反对唐王朝的武装起义，曾攻占道州（州治在今湖南道县）达一月余。第二年五月，元结任道州刺史，七月“西原蛮”又攻破了邻近的永州（州治在今湖南零陵）和邵州（州治在今湖南邵...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac26845f3e157ce321", "shortContent": "此诗和《舂陵行》都是作者反映社会现实，同情人民疾苦的代表作，而在斥责统治者对苦难人民的横征暴敛上，此诗词意更为深沉，感情更为愤激。\n\n诗前的序交待了作诗的原委。癸卯岁，即唐代宗广德元年（763），十二月，广西境内的少数民族“西原蛮”发动了反对唐王朝的武装起义，曾攻占道州（州治在今湖南道县）达一月余。第二年五月，元结任道州刺史，七月“西原蛮”又攻破了邻近的永州（州治在今湖南零陵）和邵州（州治在今湖南...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ac305cf0801816da4", "shortContent": "此诗是一首针砭时弊的讽刺诗。唐代宗广德元年（763）十二月，“西原蛮”（古时对广西西原少数民族的贬称）攻陷道州（今湖南道县）。次年五月，元结任道州刺史。七月，“西原蛮”又攻永州、破邵州，但未侵犯道州。道州经历兵燹，民生困顿，社会凋敝，却不幸又逢朝廷派来的官吏横征暴敛，民怨沸腾有加。诗人有感于民生之困顿与官吏之残暴，乃作诗以赋志。\n\n“昔岁逢太平”六句，诗人追忆曾在山林中二十余年的太平生活。当时的情...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127069c305cf0801816fc7", "shortContent": "此诗是一首针砭时弊的讽刺诗。唐代宗广德元年（763）十二月，“西原蛮”（古代统治者对广西西原少数民族的贬称）攻陷道州（今湖南道县）。次年五月，元结任道州刺史。七月，“西原蛮”又攻破永州，但未侵犯道州。道州经历兵燹，民生困顿，社会凋敝，却不幸又逢朝廷派来的官吏横征暴敛，民怨沸腾有加。诗人有感于民生之困顿与官吏之残暴，乃作诗以赋志。\n\n“昔岁逢太平”六句，诗人追忆曾在山林中生活二十余年的太平生活。当时...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270e1f2af4e09d55b6807", "shortContent": "此诗是一首针砭时弊的讽刺诗。唐代宗广德元年（763）十二月，“西原蛮”（广西西原少数民族的贬称）攻陷道州（今湖南道县）。次年五月，元结任道州刺史。七月，“西原蛮”又攻破永州，但未侵犯道州。道州经历兵燹，民生困顿，社会凋敝，却不幸又逢朝廷派来的官吏横征暴敛，民怨沸腾有加。诗人有感于民生之困顿与官吏之残暴，乃作诗以赋志。\n\n“昔岁逢太平”六句，诗人追忆曾在山林中生活二十余年的太平生活。当时的情况是：井...", "authors": ["乐云"], "pressName": "崇文书局"}]', '《韵语阳秋》：杜子美褒称元结《舂陵行》兼《贼退示官吏》二诗云：“两章对秋水，一字偕华星。致君唐虞际，淳朴忆大庭。”……盖非专称其文也。至于李义山，乃谓次山之作以自然为祖，以元气为根，无乃过乎？秦少游《漫郎》诗云：“字偕华星章对月，漏泄元气烦挥毫”，盖用子美、义山语也。
《唐诗援》：人皆知次山诗朴老古淡，在盛唐自成一家，惟子美《舂陵行序》云：“今盗贼未息，知民疾苦，得结辈十数公，落落然参错天下为邦伯。万物吐气，天下少安可得矣！”数语真次山知己。
《唐贤三昧集笺注》：真朴恻怛，如读“变风”、“小雅”。不独有仁慈之心，亦可以为诗史也。
《茧斋诗谈》：若纯作刺时语，亦伤厚道。看首尾词意和平，可知古人用笔之妙。
《岘佣说诗》：诗忌拙直，然如元次山《舂陵行》、《贼退示官吏》诸诗，愈拙直，愈可爱。盖以仁心结为真气，发为愤词，字字悲痛，《小雅》之哀音也。', 'center', 1416690698, '57b930652e958a005fa6e06e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10480, '初发扬子寄元大校书', NULL, 219, 570, 1, 3, '韦应物', NULL, 10115, '57b9b835128fe1005f860400', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383078.htm', '', '凄凄去亲爱，泛泛入烟雾。
归棹洛阳人，残钟广陵树。
今朝此为别，何处还相遇。
世事波上舟，沿洄安得住！', '这首诗写作者在乘船离开广陵赴任洛阳的途中，对友人元大的离别之情。联想到世事的难测，写得很有情致，也吐露了诗人被罢官以后的心情。首联写别离之“初发”。颔联写诗人乘舟归去。颈联写期望重逢。尾联以舟行不定，喻世事之顺逆翻复，难以自主。全诗借景抒情，寓情于景。', '扬子：指扬子津，在长江北岸，近瓜州。元大：未详何人。校书：官名。唐代的校书郎，掌管校书籍。
去：离开。亲爱：相亲相爱的朋友，指元大。
泛泛：行船漂浮。
归棹（zhào）：归去的船。棹，船桨。指从扬子津出发乘船北归洛阳。
“残钟”句：意谓回望广陵，只听得晓钟的残音传自林间。广陵：江苏扬州的古称。在唐代，由扬州经运河可以直达洛阳。
今朝（zhāo）：现在，今天。此：此处。为别：作别。
还：再。
世事：世上的事
沿洄（huí）：顺流而下为沿，逆流而上为洄，这里指处境的顺逆。安得住：怎能停得住？', '凄然地辞别了好朋友，驶向烟雨濛濛的江心。
在乘船返回洛阳之际，传来广陵树间的钟声。
此时我们在扬州惜别，不知何处才能再相逢。
世间事如同浪里行舟，不论顺流逆流怎能停。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b90ce818559d0587c3", "shortContent": "这首诗写于韦应物离开广陵（今江苏扬州）回洛阳去的途中。元大（“大”是排行第一，其人名字已不可考）是他在广陵的朋友，诗中用“亲爱”相称，可见彼此感情颇深。所以诗人在还能望见广陵城外的树和还能听到寺庙钟声的时候，就想起要写诗寄给元大了。\n这首诗是以“归棹洛阳人，残钟广陵树”十个字著名的。为什么这十个字能脍炙人口呢？\n诗人和元大分手，心情很悲伤。可是船终于还是开行了。船儿飘荡在烟雾之中，他还不住回头看着...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a8d", "shortContent": "这首诗写于韦应物离开广陵（今江苏扬州）回洛阳去的途中。元大（“大”是排行第一，其人名字已不可考）是他在广陵的朋友，诗中用“亲爱”相称，可见彼此感情颇深。所以诗人在还能望见广陵城外的树和还能听到寺庙钟声的时候，就想起要写诗寄给元大了。\n\n这首诗是以“归棹洛阳人，残钟广陵树”十个字著名的。为什么这十个字能脍炙人口呢？\n\n诗人和元大分手，心情很悲伤。可是船终于还是开行了。船儿飘荡在烟雾之中，他还不住回头...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ac305cf0801816da6", "shortContent": "这是一首离别诗。代宗广德元年（763），韦应物被任命为洛阳丞。乘船离广陵赴任洛阳的途中，因思念友人元大，故作此诗。\n\n“凄凄去亲爱”，诗人怀着凄怆的心情告别朋友元大。以“亲爱”二字称友人，足见二人交谊的深厚与分别时的依依不舍。“泛泛入烟雾”，但船终于启行了，荡漾着慢慢驶入大江茫茫烟雾之中。“泛泛”，荡漾的样子、浮动的样子。诗人惆怅若失的心恰如荡漾在烟雾迷蒙的江面上的客船，景物也似不自觉地染上了诗人...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '《韦孟全集》：刘云：至浓至淡，便是苏州笔意。
《汇编唐诗十集》：唐云：浅浅说出，自然超凡。
《唐诗善鸣集》：韦诗醇古，之内又复坚深，用笔甚微。如此诗，令选者似可舍却，终不可舍却，细咏之，自得其味。
《唐诗笺要》：数字内无数逗露，无数包含，了却情人多少公案。元明间才人为一“情”字作传奇千百出，不敌这首。
《唐诗别裁集》：写离情不可过于凄惋，含蓄不尽，愈见情探，此种可以为法。
《唐宋诗举要》：六朝佳句（“归棹”二句下）。', 'center', 1416691883, '57b8eed05bbb50005b77b38d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10481, '寄全椒山中道士', NULL, 360, 570, 3, 2, '韦应物', NULL, 10115, '57b9b835128fe1005f860400', '唐', 'shi', '诗', 'http://baike.baidu.com/view/346231.htm', '', '今朝郡斋冷，忽念山中客。
涧底束荆薪，归来煮白石。
欲持一瓢酒，远慰风雨夕。
落叶满空山，何处寻行迹？', '此诗作于公元783年（唐德宗建中四年）或公元784年（兴元元年）秋日。安史之乱后，玄宗奔蜀，韦应物立志读书，进士及第，官至洛阳丞，后被迫辞职后又任滁州刺史。此诗创作正值作者在滁州刺史任上。
此诗抒写秋风秋雨之夕，诗人怀念山中的一位道士，想携酒去安慰老友又无从寻觅的惆怅之情，寄托了诗人深挚的情愫和淡远的情趣。全诗语言简洁，平淡无奇，然感情跳荡反复，形象鲜明自然，情味幽远。', '寄：寄赠。全椒：今安徽省全椒县，唐属滁州。
郡斋：滁州刺史衙署的斋舍。山中客：指全椒县西三十里神山上的道士。
涧：山间流水的沟。束：捆。荆薪：杂柴。白石：《神仙传》云：“白石先生者，中黄丈人弟子也，常煮白石为粮，因就白石山居，时人故号曰白石先生。”此指山中道士艰苦的修炼生活。
瓢：将干的葫芦挖空，分成两瓣，叫做瓢，用来作盛酒浆的器具。风雨夕：风雨之夜。
空山：空寂的深山。行迹：来去的踪迹。', '今天郡斋里很冷，忽然想起山中隐居的人。你一定在涧底打柴，回来以后煮些清苦的饭菜。想带着一瓢酒去看你，让你在风雨夜里得到些安慰。可是秋叶落满空山，什么地方能找到你的行迹？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b92e6a6b501f95c259", "shortContent": "这首诗乍看无甚惊人之句，好像一潭秋水，泠然而清，颇有陶渊明的风格，向来被称为韦诗中的名篇。有人说它“一片神行”，有人说是“化工笔”（见高步瀛《唐宋诗举要》），评价很高。\n题目叫《寄全椒山中道士》。既然是“寄”，自然会吐露对山中道士的忆念之情。但忆念只是一层，还有更深的一层，需要细心领略。\n诗的关键在于那个“冷”字。全诗所透露的也正是在这个“冷”字上。首句既是写出郡斋气候的冷，更是写出诗人心头的冷。...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a8f", "shortContent": "这首诗乍看无甚惊人之句，好像一潭秋水，泠然而清，颇有陶渊明的风格，向来被称为韦诗中的名篇。有人说它“一片神行”，有人说是“化工笔”（见高步瀛《唐宋诗举要》），评价很高。\n\n题目叫《寄全椒山中道士》。既然是“寄”，自然会吐露对山中道士的忆念之情。但忆念只是一层，还有更深的一层，需要细心领略。\n\n诗的关键在于那个“冷”字。全诗所透露的也正是在这个“冷”字上。首句既是写出郡斋气候的冷，更是写出诗人心头的...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ac305cf0801816da7", "shortContent": "此诗作于德宗建中五年（784）秋日，时韦应物在滁州刺史任上，表达了对山中道士的忆念之情。全椒，今安徽全椒县，唐属滁州。\n\n秋风秋雨，诗人因斋舍寒冷而忽然想起了山中的友人。“冷”一方面指出当时气候的寒冷，更是写诗人心头的“冷”，即孤寂。诗人自己在城中的官舍里尚感寒冷，更何堪山中的友人呢？推己及人，体现了作者与山中客深厚的情谊。此时的友人在做什么呢？一定是在山沟里打柴，准备归来后用来炼丹。煮白石，葛洪...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '《彦周诗话》：“落叶满空山，何处寻行迹。”东坡用其韵曰：“寄语庵中人，飞空本无迹。”此非才不逮，盖绝唱不当和也。
《容斋随笔》：韦应物在滁州，以酒寄全椒山中道士，作诗云云。其为高妙超诣，固不容夸说，而结尾两句，非复语句思索可到。
《韦孟全集》：刘云：其诗自多此景意，及得意如此亦少。妙语佳言，非人意想所及。
《批点唐诗正声》：全首无一字不佳，语似冲泊，而意兴独至，此所谓“良工心独苦”也。
《唐诗归》：钟云：此等诗妙处在工拙之外。
《唐诗选脉会通评林》：周敬曰：通篇点染，情趣恬古。一结出自天然，若有神助。
《唐风定》：语语神境。作者不知其所以然，后人欲和之，知其拙矣。
《唐诗别裁》：化工笔，与渊明“采菊东篱下，悠然见南山”，妙处不关语言意思。
《茧斋诗谈》：无烟火气，亦无云雾光，一片空明，中涵万象。
《网师园唐诗笺》：妙夺化工（末句下）。
《唐贤清雅集》：东坡所谓“发纤秾于简古，寄至味于淡泊，”正指此种。
《王闿运手批唐诗选》：超妙极矣，不必有深意。然不能数见，以其通首空灵，不可多得也。
《岘佣说诗》：《寄全椒山中道士》一作，东坡刻意学之而终不似。盖东坡用力，韦公不用力；东坡尚意，韦公不尚意，微妙之谓也。
《唐宋诗举要》：一片神行。', 'center', 1416691999, '57b453f08ac24700643cbb46', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10482, '长安遇冯著', NULL, 188, 570, 1, 1, '韦应物', NULL, 10115, '57b9b835128fe1005f860400', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383080.htm', '', '客从东方来，衣上灞陵雨。
问客何为来，采山因买斧。
冥冥花正开，飏飏燕新乳。
昨别今已春，鬓丝生几缕。', '韦应物于大历四年至十三年（公元769年-公元778年）在长安，而冯著在大历四年离长安赴广州，约在大历十二年再到长安。这诗可能作于大历四年（公元769年）或十二年（公元777年）。据韦诗所写，冯著是一位有才有德而失志不遇的名士。他先在家乡隐居，清贫守真，后来到长安谋仕，颇擅文名，但仕途失意。约在大历四年（公元769年）应征赴幕到广州。十年过去，仍未获官职。后又来到长安。韦应物对这样一位朋友是深为同情的，故而创作这首诗。
这首赠诗，以亲切诙谐的笔调，对失意沉沦的冯著深表理解、同情、体贴和慰勉。开头写冯著从长安以东而来，一派名流兼隐士风度。接着以诙谐打趣形式劝导冯著对前途要有信心。再进一步劝导他要相信自己，正如春花乳燕焕发才华，会有人关切爱护的。整篇诗情意深长，生动活泼。它的感人之处，首先在于诗人的心胸坦荡，思想开朗，对生活充满信心，对前途充满希望，对朋友充满热情。因此，韦应物能对一位邂逅的失意朋友，充分理解，真诚同情，体贴入微，而积极勉励。诗在叙事中写景，借写景以寄托寓意。情调和风格，犹如小河流水，清新明快，委曲宛转，读来一览无馀，品尝则又回味不尽。', '冯著：韦应物友人。
灞（bà）陵：即霸上，又作霸陵。在今西安市东。因汉文帝葬在这里，改名灞陵。
客：即指冯著。
采山：砍材。
采山因买斧：意指归隐山林。「采山」是成语。左思《吴都赋》：「煮海为盐，采山铸钱。」谓入山采铜以铸钱。「买斧」化用《易经·旅卦》：「旅于处，得其资斧，我心不快。」意谓旅居此处作客，但不获平坦之地，尚须用斧斫除荆棘，故心中不快。「采山」句是俏皮话，打趣语，大意是说冯著来长安是为采铜铸钱以谋发财的，但只得到一片荆棘，还得买斧斫除。其寓意即谓谋仕不遇，心中不快。
冥冥：形容造化默默无语的情态。
飏飏（yángyáng）：鸟轻快飞翔的样子。
燕新乳：指小燕初生。
昨别：去年分别。
鬓丝（bìn）：两鬓白髮如丝。', '客人从东方过来，衣服上还带着灞陵的雨。问客人为什么来，客人说为了上山砍伐树木来买斧头。百花正在悄悄地盛开，轻盈的燕子正在哺乳新雏。去年一别如今又是春天，两鬓的头发不知又生出多少。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b90ce818559d0587c9", "shortContent": "冯著是韦应物的朋友，其事失传，今存诗四首。韦应物赠冯著诗，也存四首。据韦诗所写，冯著是一位有才有德而失志不遇的名士。他先在家乡隐居，清贫守真，后来到长安谋仕，颇擅文名，但仕途失意。约在大历四年（769）应征赴幕到广州。十年过去，仍未获官职。后又来到长安。韦应物对这样一位朋友是深为同情的。\n韦应物于大历四年至十三年在长安，而冯著在大历四年离长安赴广州，约在大历十二年再到长安。这诗可能作于大历四年或十...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ac305cf0801816da8", "shortContent": "这首赠诗，以亲和风趣的笔调，对仕途不顺的朋友冯著表示同情和劝慰。\n开头两句中，“客”即指冯著。灞陵，即霸陵，在长安东郊山区，东汉逸士梁鸿曾隐于此，卖药的韩康也曾隐遁于此。这两句主要是说冯著刚从东边来到长安，风度翩翩，大有名士兼隐士作派。\n\n至于冯著来长安的目的和处境，作者当然是知道的。不过他没有直接点出，否则就没有诗意了。他以自问自答的方式作了诙谐的处理。“问客何为来？采山因买斧。”“采山”是个典...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '', 'center', 1416692127, '57b930725bbb50005b79b7b3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10483, '夕次盱眙县', NULL, 219, 570, 2, 1, '韦应物', NULL, 10115, '57b9b835128fe1005f860400', '唐', 'shi', '诗', 'http://baike.baidu.com/view/346227.htm', '', '落帆逗淮镇，停舫临孤驿。
浩浩风起波，冥冥日沉夕。
人归山郭暗，雁下芦洲白。
独夜忆秦关，听钟未眠客。', '这是一首写羁旅风波，泊岸停宿，客居不眠，顿生乡思的诗。诗的前四句为第一段，是写傍晚因路途风波，不得不停舫孤驿。后四句为第二段，是写人雁归宿、夜幕降临，自夜到晓不能入眠而生乡思客愁。全诗富有生活气息，侃侃诉说，淡淡抒情，看是写景，景中寓情，情由景生，景令情动。', '次：停泊。
盱眙（Xū Yí）：今属江苏，地处淮水南岸。
逗：停留。
淮镇：淮水旁的市镇，指盱眙。
舫：船。
临：靠近。
驿：供邮差和官员旅宿的水陆交通站。
浩浩：盛大的样子。
冥冥：昏暗、昏昧。
「人归山郭暗」句：日落城暗，人也回去休息了。
芦洲：芦苇丛生的水泽。
秦关：指长安。秦，今陕西的别称，因战国时为秦地而得名。
「听钟未眠客」句：孤独之夜，怀念家乡。客，诗人自称。', '降落白帆，逗留河边小镇。停下行船，面对孤独客栈。浩浩晚风，吹起一河碧波；彤彤夕阳，沉于冥冥溪边。行人已归，城郭渐暗，平沙落雁，芦花点点，月夜独忆家乡，听钟未能成眠。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ac305cf0801816da9", "shortContent": "此诗作于唐建中四年（783）夏，韦应物自京赴滁州途中。诗人夜泊盱眙，乃赋诗以抒乡愁。\n\n开头两句，交代了时间地点以及事由。时间是落帆之时，黄昏已近。地点是淮镇，即盱眙。盱眙临淮水，唐时属临淮郡，故有“淮镇”之说。诗人停船靠岸，在这偏僻的“孤驿”驻脚。“驿”是唐代供邮差和官员旅宿的水陆交通站，诗人当晚在此歇息，以缓一路奔波之苦。从“落帆”与“孤驿”之意象，奠定了凄冷孤寂、愁绪满怀的感情基调。\n\n三、...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706a7f0b9738b369b217", "shortContent": "此诗作于唐建中三年（782）夏，韦应物自京赴滁州途中。诗人曾夜宿江苏盱眙，乃赋诗以抒乡愁。\n\n开头两句，交代了诗人行程的时间地点以及事由。时间是落帆之时，黄昏已近。地点是淮镇，即盱眙，唐时盱眙属淮南道楚州，故有“淮镇”之说。诗人停船靠岸，在这偏僻的“孤驿”歇息。“驿”是唐代供邮差和官员旅宿的水陆交通站，诗人当晚在此歇息，以缓一路奔波之苦。从“落帆”与“孤驿”之意象，奠定了全诗凄冷孤寂，愁绪满怀的感...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270f7f2af4e09d55b6824", "shortContent": "此诗作于唐建中三年（782）夏，韦应物自京赴滁州途中。诗人曾夜宿江苏盱眙，乃赋诗以抒乡愁。\n\n开头两句，交代了诗人行程的时间地点以及事由。时间是落帆之时，黄昏已近。地点是淮镇，即盱眙。\n\n唐时盱眙属淮南道楚州，故有“淮镇”之说。诗人停船靠岸，在这偏僻的“孤驿”驻脚。“驿”是唐代供邮差和官员旅宿的水陆交通站。诗人当晚在此歇息，以缓一路奔波之苦。\n\n从“落帆”与“孤驿”之意象，奠定了凄冷孤寂，愁绪满怀...", "authors": ["乐云"], "pressName": "崇文书局"}]', '明代高棅《批点唐诗正声》：「白」字入妙，正见夕暗之态。
余成教《石园诗话》：韦诗如「微雨夜来过，不知春草生」、「人归山郭暗，雁下芦洲白」、「乔木生夏凉，流云吐华月」、「寒雨暗深更，流萤度高阁」、「落叶满空山，何处寻行迹」、「微风时动牖，残灯尚留壁」、「浮云一别后，流水十年间」、「寒山独过雁，暮雨远来舟，」、「寒树依微远天外，夕阳明灭乱流中」、「怪来诗思清入骨，门对寒流雪满山」，有合于刘须溪所谓「诵一二语，高处有山泉极品之味」也。
清代乔亿《剑溪说诗·卷上》：淡然无意，而真率之气自不可掩。', 'center', 1416692206, '57b92246a633bd00665e6a40', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10484, '东郊', NULL, 127, 570, 1, 1, '韦应物', NULL, 10115, '57b9b835128fe1005f860400', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383082/9455927.htm', '', '吏舍跼终年，出郊旷清曙。
杨柳散和风，青山澹吾虑。
依丛适自憩，缘涧还复去。
微雨霭芳原，春鸠鸣何处。
乐幽心屡止，遵事迹犹遽。
终罢斯结庐，慕陶直可庶。', '这首诗是大历十四年（779）春在鄠县令任上作。此诗抒写了诗人久困官舍偶尔郊游时，面对充满生命力的美好春光陶然而醉的闲适心情，以及由此产生的弃官归隐的念头，表现了诗人对官场束缚的厌憎和对自由散淡生活的向往。诗中描绘的是平凡的事物和平常的景色，却蕴涵着无限的诗情画意。这首诗反映了作者的人格和诗风都颇类陶渊明。', '跼（jú）：拘束。
旷清曙：在清幽的曙色中得以精神舒畅。
澹（dàn）：澄净。虑：思绪。
丛：树林。憩（qì）：休息。
缘：沿着。涧：山沟。还复去：徘徊往来。
霭（ǎi）：云气，这里作动词，笼罩。
“乐幽”二句：意谓自己颇爱这地方的幽静，想住下来，却又几次终止，就因公事在身，形迹上还是显得很匆忙。
“终罢”二句：典出陶渊明"结庐在人境，而无车马喧"表面要效仿陶渊明辞官归隐。斯，一作“期”。慕陶，指归隐。直，或作真，就。庶，庶几，差不多。', '困守官舍，使我终年地烦闷。漫步郊野，曙光荡涤我的胸襟。杨柳依依，在和风里摇曳不定。青山如画，淡泊了我的尘念俗情。斜倚树丛，我休息得多么安宁；沿着山涧，继续信步前行。微雨过后，芬芳的原野更加滋润清新，斑鸠声声，却不知在哪里欢鸣。我向来喜爱幽静，可惜总难以遂心。公务缠绕，生活常感觉迫促不宁。我终将辞谢官职，去营造茅屋一进，追随陶潜的步履，但愿得到那清雅的风情。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ac305cf0801816daa", "shortContent": "此诗为韦应物任滁州刺史任上所作，其“萧散冲淡”的诗风与“高雅闲澹”的意境，透露出淡淡的弃官归隐之意。\n\n“吏舍跼终年，出郊旷清曙。”开篇即交代诗歌创作的缘由与事由。诗人天天被官场俗务缠身，一年操劳到头，终于有机会到涂州的东郊游玩，领略郊外清朗的曙色，不是令人心境开阔，心旷神怡吗？一“跼”字，一“旷”字，对照映衬出诗人官场生涯的拘束与烦闷和郊外游玩的舒缓与惬意。\n\n三、四句则写诗人漫步郊野之所见所感...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706a7f0b9738b369b212", "shortContent": "此诗为韦应物任滁州刺史任上所作，其“萧散冲淡”的诗风与“高雅闲谵”的意境，透露出淡淡的弃官归隐之意。\n\n“吏舍跼终年，出郊旷清曙。”交代诗歌创作的缘由与事由。诗人天天被官场俗务缠身，一年操劳到头，终于有机会到涂州的东郊游玩，领略郊外清朗的曙色，不是令人心境开阔，心旷神怡吗？一“跼”字，一“旷”字，对照出诗人官场生涯的拘束与烦闷，与郊外游玩的舒缓与惬意。\n\n三、四句则写诗人漫步郊野之所见所感。在和煦...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270f073206168b2e0229a", "shortContent": "此诗为韦应物任滁州刺史任上所作，其“萧散冲淡”的诗风与“高雅闲澹”的意境，透露出淡淡的弃官归隐之意。\n\n“吏舍跼终年，出郊旷清曙。”交代诗歌创作的缘由与事由。诗人天天被官场俗务缠身，一年操劳到头，终于有机会到涂州的东郊游玩，领略郊外清朗的曙色，不是令人心境开阔，心旷神怡吗？一“跼”字，一“旷”字，对照出诗人官场生涯的拘束与烦闷，与郊外游玩的舒缓与惬意。\n\n三、四句则写诗人漫步郊野之所见所感。在和煦...", "authors": ["乐云"], "pressName": "崇文书局"}]', '', 'center', 1416692311, '57b8ec8e79bc44005b9e2143', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10485, '送杨氏女', NULL, 115, 570, 0, 1, '韦应物', NULL, 10115, '57b9b835128fe1005f860400', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383083.htm', '', '永日方戚戚，出行复悠悠。
女子今有行，大江溯轻舟。
尔辈苦无恃，抚念益慈柔。
幼为长所育，两别泣不休。
对此结中肠，义往难复留。
自小阙内训，事姑贻我忧。
赖兹托令门，任恤庶无尤。
贫俭诚所尚，资从岂待周。
孝恭遵妇道，容止顺其猷。
别离在今晨，见尔当何秋。
居闲始自遣，临感忽难收。
归来视幼女，零泪缘缨流。', '这是一首送女出嫁、表达自己伤别心情的诗篇。诗人早年丧妻，留下两女相依为命。当大女儿出嫁之时，送其出行，万千叮咛；怜其无恃，反复诫训。此诗写得情真语挚，泪满诗行，愁惨凄恻，朴实无华，骨肉之情，跃然纸上。', '杨氏女：指女儿嫁给杨姓的人家。
永日：整天。戚戚：悲伤忧愁。
行：出嫁。悠悠：遥远。
溯（sù）：逆流而上。
尔辈：你们，指两个女儿。无恃：指幼时无母。恃，是依靠的意思，以小孩对母亲有依赖感，所以又以代指母亲。
幼为长所育：此句下有注：“幼女为杨氏所抚育”，指小女是姐姐抚育大的。
结中肠：心中哀伤之情郁结。
义往：指女大出嫁，理应前往夫家。
自小阙内训：此句下有注：“言早无恃。”阙：通“缺”。内训：母亲的训导。
事姑：侍奉婆婆。贻：带来。
令门：好的人家，或是对其夫家的尊称。这里指女儿的夫家。
任恤：信任体恤。任，任从，引申为宽容。庶：希望。尤：过失。
尚：崇尚。
资从：指嫁妆。待：一作“在”。周：周全，完备。
容止：这里是一举一动的意思。猷：规矩礼节。
尔：你，指大女儿。当何秋：当在何年。
居闲：闲暇时日。自遣：自我排遣。
临感：临别感伤。
零泪：落泪。缘：通“沿”。缨：帽的带子，系在下巴下。', '我整日忧郁而悲悲戚戚，女儿就要出嫁遥远地方。
今天她要远行去做新娘，乘坐轻舟沿江逆流而上。
你姐妹自幼尝尽失母苦，念此我就加倍慈柔抚养。
妹妹从小全靠姐姐养育，今日两人作别泪泣成行。
面对此情景我内心郁结，女大当嫁你也难得再留。
你自小缺少慈母的教训，侍奉婆婆的事令我担忧。
幸好依仗你夫家好门第，信任怜恤不挑剔你过失。
安贫乐俭是我一贯崇尚，嫁妆岂能做到周全丰厚。
望你孝敬长辈遵守妇道，仪容举止都要符合潮流。
今晨我们父女就要离别，再见到你不知什么时候。
闲居时忧伤能自我排遣，临别感伤情绪一发难收。
回到家中看到孤单小女，悲哀泪水沿着帽带滚流。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ac305cf0801816dab", "shortContent": "此诗是韦应物诗作中较少见的写亲情的送别诗。杨氏女，指的是韦应物的长女。她即将嫁入杨姓人家，身为父亲的诗人自是无限伤感，心情异常复杂。但为女儿人生幸福的考虑，诗人又千叮咛万嘱托，期冀女儿在夫家恪守妇道，孝顺公婆，睦邻乡里，做一名识大体、有妇德的贤妻良母。\n\n起首四句叙女儿出嫁时父亲的忧愁与伤感。“戚戚”，语出《诗经•大雅•行苇》，“戚戚兄弟，莫远具尔”，喻亲人离别之忧伤状。“悠悠”二字则蕴涵两层意思...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706a7f0b9738b369b215", "shortContent": "此诗是韦应物诗作中较少见的写亲情的送别诗。杨氏女，指的是韦应物的长女，她即将嫁入杨姓人家，身为父亲的诗人自是无限伤感，心情异常复杂，但为女儿人生幸福的考虑，诗人又千叮咛，万嘱托，期冀女儿在夫家恪守妇道，孝顺公婆，睦邻乡里，做一名识大体、有妇德的贤妻良母。\n\n起首四句叙女儿出嫁时父亲的忧愁与伤感。“戚戚”，语出《诗经·大雅》“戚戚兄弟，莫远具尔”，喻指亲人离别之忧伤状。“悠悠”二字则蕴涵两层意思，一...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270f7f2af4e09d55b6823", "shortContent": "此诗是韦应物诗作中较少见的写亲情的送别诗。杨氏女，指的是韦应物的长女。她即将嫁入杨姓人家，身为父亲的诗人自是无限伤感，心情异常复杂，但为女儿人生幸福的考虑，诗人又千叮咛，万嘱托，期冀女儿在夫家恪守妇道，孝顺公婆，睦邻乡里，做一名识大体、有妇德的贤妻良母。\n\n起首四句叙女儿出嫁时父亲的忧愁与伤感。“戚戚”，语出《诗经·大雅》“戚戚兄弟，莫远具尔”，喻指亲人离别之忧伤状。“悠悠”二字则蕴涵两层意思，一...", "authors": ["乐云"], "pressName": "崇文书局"}]', NULL, 'center', 1416692910, '57b9b86fd342d3006bdfdb3f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10486, '晨诣超师院读禅经', NULL, 211, 243, 2, 2, '柳宗元', NULL, 10055, '57b9042f7db2a2005426b940', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383085.htm', '', '汲井漱寒齿，清心拂尘服。
闲持贝叶书，步出东斋读。
真源了无取，妄迹世所逐。
遗言冀可冥，缮性何由熟。
道人庭宇静，苔色连深竹。
日出雾露余，青松如膏沐。
澹然离言说，悟悦心自足。', '此首诗为诗人被贬永州时所作，约写于元和元年（806年）。当时，柳宗元住永州龙兴寺。龙兴寺在城南，住持僧为重巽，坐禅于龙兴寺净土院，与住在龙兴寺西厢的柳宗元相邻。由于重巽是楚之南的“善言佛者”，故称其为“超师”。柳宗元于永州好佛求其道，主要是拜重巽为师，或请其讲“佛道”，或到净土院读佛经。
此诗写出晨读禅经的情景和感受，曲折地表达了埋藏在心底的抑郁之情，抒发了诗人的哲学见解。前半部写诗人到禅院读经，指责世人追逐的乃是那些荒诞的事情，而不去了解佛经的真正含义。后半部写他认为佛家的精义与儒家之道有相通之处，但如何修养本性，却难以精熟。然而，他对禅院的清静幽雅却流连玩赏。全诗描写了习禅的心境，以及深得禅趣那种轻松、愉悦、闲适的心态。', '诣（yì）：到，往。超师院：指永州龙兴寺净土院；超师指住持僧重巽。禅经：佛教经典。
汲（jí）：从井里取水。
拂：抖动。
贝叶书：一作“贝页书”，又叫“贝书”。在贝多树叶上写的佛经，也作佛经之泛称。古印度人多用贝多罗树叶经水沤后代纸，用以写佛经，故名。
东斋（zhāi）指净土院的东斋房。
真源：指佛理“真如”之源，即佛家的真意。了（liăo）：懂得，明白。
妄迹：迷信妄诞的事迹。
遗言：指佛经所言。冀：希望。冥：暗合。
缮性：修养本性。熟：精通而有成。
道人：指僧人重巽。缮：修持。
膏：润发的油脂。沐（mù）：湿润、润泽。
澹（dàn）然：亦写作“淡然”，恬静，冲淡，宁静状。
悟悦：悟道的快乐。', '汲来清凉井水漱口刷牙，心清了再拂去衣上尘土。
悠闲地捧起佛门贝叶经，信步走出东斋吟咏朗读。
佛经真谛世人并无领悟，迷信荒诞被世人所追逐。
佛儒精义原也可望暗合，但修养本性我何以精熟。
道人禅院多么幽雅清静，绿色鲜苔连接竹林深处。
太阳出来照着晨雾余露，苍翠松树宛若沐后涂脂。
清静使我恬淡难以言说，悟出佛理内心畅快满足。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1bc305cf0801816dac", "shortContent": "此诗为柳宗元被贬永州时所作，时柳宗元住在永州龙兴寺。住持重巽为楚之南“善言佛者”，故称其为“超师”。柳宗元参与政治革新而被贬，壮志难酬，心情抑郁苦闷，故于佛道中求得宁静与解脱。\n\n首句就有出尘之想。汲上清冽的井水漱口，冰冷的井水刺得牙齿发寒。清理自己的心灵，让心灵归于静谧。拂去沾染了灰尘的衣服，恭敬地进入超师的禅院之中，取经而读。起句就像诗中描写的井水一样，甘凉而清冽。\n超师是僧人，这里的经自然是...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '', 'center', 1416693116, '57b021170a2b58006322d463', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10487, '溪居', NULL, 244, 243, 1, 1, '柳宗元', NULL, 10055, '57b9042f7db2a2005426b940', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383087/5814222.htm', '', '久为簪组累，幸此南夷谪。
闲依农圃邻，偶似山林客。
晓耕翻露草，夜榜响溪石。
来往不逢人，长歌楚天碧。', '此诗是唐代文学家柳宗元被贬永州后所作。这首诗描写他被贬官到有“南荒”之称的永州后，在溪边筑室而居，过着闲适的生活。表面上自我排遣，也自得其乐，实际上曲折地表达被贬谪的幽愤，字里行间隐含了作者壮志难酬的苦闷之情。', '溪居：指在冉溪居住的生活。诗人贬谪永州司马后，曾于此筑室而居，后改冉溪为“愚溪”，在今湖南省永州市东南。
簪（zān）组：古代官吏的饰物。簪，冠上的装饰；组，系印的绶带。此以簪组指做官。
累：束缚，牵累。
南夷：南方少数民族或其居住的地区，这里指永州。
农圃（pǔ）：田园，此借指老农。
邻：邻居。
偶似：有时好像。
山林客：指隐士。
露草：带有露水的杂草。
榜（bàng）：船桨。这里用如动词，划船。一作“塝”，孔孟切。
响溪石：触着溪石而发出响声。
人：此指故人、知交。
长歌：放歌。
楚天：这里指永州的天空。春秋战国时期，永州属楚国。', '长久地为做官所羁累着，庆幸贬到永州得以解脱。
自在闲居且与农家相邻，有时还像山林中的隐士。
清晨踏着朝露耕田除草，夜晚泛船观赏青山绿水。
去来都看不到世事俗法，仰望碧空蓝天自由高歌。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92cbc6e67846a920ed26", "shortContent": "元和五年（810），柳宗元在零陵（治今湖南永州）西南游览时，发现了曾为冉氏所居的冉溪，因爱其风景秀丽，便迁居是地，并改名为愚溪。\n这首诗写他迁居愚溪后的生活。诗的大意是说：我久为做官所羁累，幸好有机会贬谪到这南方少数民族地区中来，解除了我的无穷烦恼。闲居无事，便与农田菜圃为邻，有时就仿佛是个山林隐逸之士。清晨，踏着露水去耕地除草；有时荡起小舟，去游山玩水，直到天黑才归来。独往独来，碰不到别人，仰望...", "authors": ["吴文治"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1bc305cf0801816dad", "shortContent": "这首诗是柳宗元被贬为永州（今湖南零陵）司马时所作。元和五年（810），柳宗元在游览永州西山时，发现了曾为冉氏所居的冉溪，因为喜爱那里秀丽而宜人的美景，便筑屋而居，并把溪名改为愚溪。这首五言诗就是写迁居愚溪后的闲适生活。此诗貌似闲适，字里行间却无不流露着诗人内心隐含着的郁闷和怨愤，实为强作闲适，而我们又可以发现，这首诗的韵味也恰恰就在这些地方。\n\n“久为簪组累，幸此南夷谪”，开门见山地道出来永州的原...", "authors": ["董镇菲"], "pressName": "崇文书局"}, {"bookId": "645d12f76de2f61f4bb3feb6", "bookTitle": "柳宗元诗文鉴赏辞典", "articleId": "646c4db3902ee364cc7d1d0a", "shortContent": "元和五年（810），柳宗元在永州（治今湖南永州）西南游览时，发现了曾为冉氏所居的冉溪，因爱其风景秀丽，便迁居是地，并改名为愚溪。\n这首诗写他迁居愚溪后的生活。诗的大意是说：我久为做官所羁累，幸好有机会贬谪到这南方少数民族地区中来，解除了我的无穷烦恼。闲居无事，便与农田菜圃为邻，有时就仿佛是个山林隐逸之士。清晨，踏着露水去耕地除草；有时荡起小舟，去游山玩水，直到天黑才归来。独往独来，碰不到别人，仰望...", "authors": ["吴文治"], "pressName": "上海辞书出版社"}]', '', 'center', 1416738483, '57b8ee60d342d3005ac6b94a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10488, '塞下曲 · 其一', NULL, 214, 202, 1, 3, '王昌龄', NULL, 10051, '57b91963128fe10054ca5788', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3727036.htm', '', '蝉鸣空桑林，八月萧关道。
出塞入塞寒，处处黄芦草。
从来幽并客，皆共尘沙老。
莫学游侠儿，矜夸紫骝好。', '此诗为王昌龄《塞下曲四首》组诗的第一首，抒发了诗人的非战之情。
“蝉鸣空桑林，八月萧关道。出塞入塞寒，处处黄芦草。”这四句写边塞秋景，无限肃杀悲凉，寒蝉、桑林、萧关、边塞、秋草都是中国古代诗歌意象里悲情的代名词，诗歌开篇刻意描写肃杀的秋景是为后来的反战主题作背景和情感上的铺垫。写戍边征人，寄寓深切同情。“从来幽并客，皆共沙尘老”，与王翰的“醉卧沙场君莫笑，古来征战几人回”，可谓英雄所见，异曲同工，感人至深。幽州和并州都是唐代边塞之地，也是许多读书人“功名只向马上取”、“宁为百夫长，胜作一书生”的追逐名利的地方。然而，诗人从这些满怀宏图大志的年轻人身上看到的却是“皆共沙尘老”的无奈结局。末两句，以对比作结，通过对自恃勇武，炫耀紫骝善于驰骋，耀武扬威地游荡，甚至惹是生非而扰民的所谓游侠的讽刺，深刻地表达了作者对于战争的厌恶，对于和平生活的向往。前面讲的幽并客的时候，作者还没有什么贬意，字里行间里还隐约可见对于献身沙场壮士的惋惜之情。用“游侠儿”来形容那些只知道夸耀自己养有良马的市井无赖，作者的反战情绪有了更深层次的表达。
本诗写边塞秋景，有慷慨悲凉的建安遗韵；写戍边征人，又有汉乐府直抒胸臆的哀怨之情；讽喻市井游侠，又让人看到了唐代锦衣少年的浮夸风气。', '空桑林：桑林因秋来落叶而变得空旷、稀疏。
萧关：宁夏古关塞名。
入塞寒：一作复入塞。
幽并：幽州和并州，今河北、山西和陕西一部分。
共尘沙：一作向沙场。
游侠儿：都市游侠少年。
矜：自夸。
紫骝：紫红色的骏马。', '知了在枯秃的桑林鸣叫，八月的萧关道气爽秋高。
出塞后再入塞气候变冷，关内关外尽是黄黄芦草。
自古来河北山西的豪杰，都与尘土黄沙伴随到老。
莫学那自恃勇武游侠儿，自鸣不凡地把骏马夸耀。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1bc305cf0801816daf", "shortContent": "《塞下曲》是盛唐边塞诗人王昌龄创作的组诗，总计四首，此为第一首和第二首。第一首，诗人通过描写边塞景色，表达自己反对战争的思想。第二首，诗人从荒凉的边塞环境入手，着重表现军旅生活的艰辛与战争的残酷，发人深省。\n\n第一首侧重描写边塞的异域风光，并表达对战争残酷性的看法。前四句着重描绘边塞的萧瑟秋景。“蝉鸣空桑林，八月萧关道。”意思是知了在枯秃的桑林中鸣叫，八月的萧关道上秋高气爽。“出塞入塞寒，处处黄芦...", "authors": ["乐云"], "pressName": "崇文书局"}]', '', 'center', 1416739103, '57b93509128fe10054cb450e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (34753, '写怀寄吴下一二知己', NULL, 1, 131, 0, 1, '周砥', NULL, 10931, '5858e5f7128fe10069b23cae', '元', 'shi', '诗', NULL, NULL, '朔风吹庭树，寒雨集杨园。
此时怀故旧，悽怆不可言。
忆向吴门道，挟书访遗老。
两公即相知，把袂日倾倒。
别来今几龄，白日不留停。
五见枇杷树，开花拂草亭。
相思乱心绪，摇摇无定处。
飘若天上云，随风忽东去。
知君卧紫烟，清真如晋贤。
手持玉麈尾，相对谈重玄。
我若不得志，岩居非本意。
宝匣剑空鸣，金尊日长醉。
吐气如长虹，古人敢追踪。
子云天禄阁，宋玉兰台宫。
奈何出门去，荆棘满中路。
当伺天□□，骑龙跃云雾。
君非知我深，何能说胸襟。
聊兹写情素，非为庄舄吟。', NULL, NULL, NULL, NULL, NULL, 'center', 1525432682, '585cdeaa128fe1006de45d13', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10490, '关山月', NULL, 1382, 1052, 2, 8, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/21431/5330156.htm', '', '明月出天山，苍茫云海间。
长风几万里，吹度玉门关。
汉下白登道，胡窥青海湾。
由来征战地，不见有人还。
戍客望边邑，思归多苦颜。
高楼当此夜，叹息未应闲。', '此诗是唐代伟大诗人李白借乐府旧题创作的一首五古。全诗分为三层，开头四句，主要写关、山、月三种因素在内的辽阔的边塞图景，从而表现出征人怀乡的情绪；中间四句，具体写到战争的景象，战场悲惨残酷；后四句写征人望边地而思念家乡，进而推想妻子月夜高楼叹息不止。此诗如同一幅由关山明月、沙场哀怨、戍客思归三部分组成的边塞图长卷，以怨情贯穿全诗，色调统一，浑然一体，气象雄浑，风格自然。', '关山月：乐府旧题，属横吹曲辞，多抒离别哀伤之情。《乐府古题要解》：“‘关山月’，伤离别也。”
天山：即祁连山。在今甘肃、新疆之间，连绵数千里。因汉时匈奴称“天”为“祁连”，所以祁连山也叫做天山。
玉门关：故址在今甘肃敦煌西北，古代通向西域的交通要道。
“长风几万里，吹度玉门关。”句：谓秋风自西方吹来，吹过玉门关。
下：指出兵。
白登：今山西大同东有白登山。汉高祖刘邦领兵征匈奴，曾被匈奴在白登山围困了七天。《汉书·匈奴传》：“（匈奴）围高帝于白登七日。”颜师古注：“白登山在平城东南，去平城十馀里。”
胡：此指吐蕃。
窥：有所企图，窥伺、侵扰。
青海湾：即今青海省青海湖，湖因青色而得名。
由来：自始以来；历来。《易·坤》：“臣弑其君，子弑其父，非一朝一夕之故，其由来者渐矣。”
戍客：征人也。驻守边疆的战士。
边邑：一作“边色”，边境。
高楼：古诗中多以高楼指闺阁，这里指戍边兵士的妻子。曹植《七哀诗》：“明月照高楼，流光正徘徊。思妇高楼上，悲叹有馀哀。”此二句当本此。', '一轮明月从祁连山升起，穿行在苍茫的云海之间。
浩荡的长风吹越几万里，吹过将士驻守的玉门关。
当年汉兵直指白登山道，吐蕃觊觎青海大片河山。
自古以来兵家必争之地，出征将士很少能够生还。
戍守兵士远望边城景象，思归家乡不禁满面愁容。
此时将士的妻子在高楼，哀叹何时能见远方亲人。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929b5914587d02f4e66d", "shortContent": "“关山月”是乐府旧题。《乐府古题要解》：“‘关山月’，伤离别也。”李白的这首诗，在内容上继承了古乐府，但又有极大的提高。\n开头四句，可以说是一幅包含着关、山、月三种因素在内的辽阔的边塞图景。我们在一般文学作品里，常常看到“月出东海”或“月出东山”一类描写，而天山在我国西部，似乎应该是月落的地方，何以说“明月出天山”呢？原来这是就征人角度说的。征人戍守在天山之西，回首东望，所看到的是明月从天山升起的...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc40934", "shortContent": "“关山月”是乐府旧题。《乐府古题要解》：“‘关山月’，伤离别也。”李白的这首诗，在内容上继承了古乐府，但又有极大的提高。\n\n开头四句，可以说是一幅包含着关、山、月三种因素在内的辽阔的边塞图景。我们在一般文学作品里，常常看到“月出东海”或“月出东山”一类描写，而天山在我国西部，似乎应该是月落的地方，何以说“明月出天山”呢？原来这是就征人角度说的。征人戍守在天山之西，回首东望，所看到的是明月从天山升起...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1bc305cf0801816db0", "shortContent": "这是李白的一首边塞诗。关山月，是乐府旧题，属横吹曲辞，多写征戍、远别之苦。《乐府古题要解》：“‘关山月’，伤离别也。”李白即以古乐府题写戍客望归与思妇盼归之情。\n\n开头四句，描绘了辽阔的边塞图景：明月在天山上升起，云海苍茫，时隐时现。萧瑟的秋风吹拂着明月，从万里之外，吹过玉门关。这几句所写景物，“明月”、“天山”、“玉门关”，呼应诗题“关”、“山”、“月”，构思精巧。绵绵群山、苍莽云海，本已景象壮...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6466e35c7da2f75ac7f0bb24", "shortContent": "“关山月”是乐府旧题。《乐府古题要解》:“‘关山月’，伤离别也。”李白的这首诗，在内容上继承了古乐府，但又有极大的提高。\n\n开头四句，可以说是一幅包含着关、山、月三种因素在内的辽阔的边塞图景。我们在一般文学作品里，常常看到“月出东海”或“月出东山”一类描写，而天山在我国西部，似乎应该是月落的地方，何以说“明月出天山”呢？原来这是就征人角度说的。征人戍守在天山之西，回首东望，所看到的是明月从天山升起...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}]', '宋代胡仔《苕溪渔隐丛话前集》卷五引吕祖谦语：气盖一世。
宋代吕本中《童蒙诗训》：李太白诗如“晓月出天山，苍茫云海间，长风一万里，吹度玉门关”，及“沙墩至梁苑，二十五长亭，大舶类双橹，中流鹅鹳鸣”之类，皆气盖一世，学者能熟味之，自然不褊浅矣。
明代胡应麟《诗薮》：青莲“明月出天山，苍茫云海间。长风几万里，吹度五门关”，浑雄之中，多少闲雅！
清代唐汝询《汇编唐诗十集》：唐云：绝无乐府气。
清高宗敕编《唐宋诗醇》：朗如行玉山，可作白自道语。格高气浑、双关作收，弥有逸致。
清代宋宗元《网师园唐诗笺》：飘举欲仙（首四句下）。
近藤元粹《李太白诗醇》：严云：“天山”亦若“云海”，皆虚境。若以某处山名实之谓与“玉门关”不远，即曲为解，亦相去万里矣。又云：“由来”二句，极惨、极旷。又曰：似近体。入古不碍，真仙才也。', 'center', 1416739767, '57b40d66c4c971005f886ec5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10491, '把酒问月', NULL, 765, 1052, 1, 2, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/120673.htm', '故人贾淳令予问之。', '青天有月来几时？我今停杯一问之。
人攀明月不可得，月行却与人相随。
皎如飞镜临丹阙，绿烟灭尽清辉发。
但见宵从海上来，宁知晓向云间没。
白兔捣药秋复春，嫦娥孤栖与谁邻？
今人不见古时月，今月曾经照古人。
古人今人若流水，共看明月皆如此。
唯愿当歌对酒时，月光长照金樽里。', '此诗写诗人端着酒杯向月亮发问，从饮酒问月开始，以邀月临酒结束，反映了人类对宇宙的困惑不解。诗人以纵横恣肆的笔触，从多侧面、多层次描摹了孤高的明月形象，通过海天景象的描绘以及对世事推移、人生短促的慨叹，展现了作者旷达博大的胸襟和飘逸潇洒的性格。全诗从酒写到月，从月归到酒；从空间感受写到时间感受。其中将人与月反反复复加以对照，又穿插以景物描绘与神话传说，塑造了一个崇高、永恒、美好而又神秘的月的形象，于中也显露着一个孤高出尘的诗人自我。虽然意绪多端，随兴挥洒，但潜气内转，脉络贯通，极回环错综之致、浑成自然之妙；加之四句转韵，平仄互换，抑扬顿挫，更觉一气呵成，有宫商之声，可谓音情理趣俱好，历来为人所激赏。', '题下作者自注：故人贾淳令予问之。
丹阙：朱红色的宫殿。
绿烟：指遮蔽月光的浓重的云雾。
但见：只看到。
宁知：怎知。
没（mò）：隐没。
白兔捣药：神话传说月中有白兔捣仙药。西晋·傅玄《拟天问》：“月中何有，白兔捣药”。
嫦娥：神话中的月中女神。传说她原是后羿的妻子，偷吃了羿的仙药，成为仙人，奔入月中。见《淮南子·览冥训》。
当歌对酒时：在唱歌饮酒的时候。曹操《短歌行》：“对酒当歌，人生几何？”金樽：精美的酒具。', '青天上明月高悬起于何时？我现在停下酒杯且一问之。
人追攀明月永远不能做到，月亮行走却与人紧紧相随。
皎洁得如镜飞升照临宫阙，绿烟散尽发出清冷的光辉。
只能看见每晚从海上升起，谁能知道早晨在云间隐没。
月亮里白兔捣药自秋而春，嫦娥孤单地住着与谁为邻？
现在的人见不到古时之月，现在的月却曾经照过古人。
古人与今人如流水般流逝，共同看到的月亮都是如此。
只希望对着酒杯放歌之时，月光能长久地照在金杯里。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a00f8fda5565055407", "shortContent": "《把酒问月》这诗题就是作者绝妙的自我造像，那飘逸浪漫的风神惟谪仙人方能有之。题下原注：“故人贾淳令予问之。”彼不自问而令予问之，一种风流自赏之意溢于言表。\n悠悠万世，明月的存在对于人间是一个魅人的宇宙之谜。“青天有月来几时”的劈头一问，对那无限时空里的奇迹，大有神往与迷惑交驰之感。问句先出，继而具体写其人神往的情态。这情态从把酒“停杯”的动作见出。它使人感到那突如其来的一问分明带有几分醉意，从而倍...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac821a74606fc40947", "shortContent": "《把酒问月》这诗题就是作者绝妙的自我造像，那飘逸浪漫的风神惟谪仙人方能有之。题下原注：“故人贾淳令予问之。”彼不自问而令予问之，一种风流自赏之意溢于言表。\n\n悠悠万世，明月的存在对于人间是一个魅人的宇宙之谜。“青天有月来几时”的劈头一问，对那无限时空里的奇迹，大有神往与迷惑交驰之感。问句先出，继而具体写其人神往的情态。这情态从把酒“停杯”的动作见出。它使人感到那突如其来的一问分明带有几分醉意，从而...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127052c305cf0801816f62", "shortContent": "月与酒，大概是李白最忠实的朋友，无论身处何方，无论是失志沮丧还是志得意满，他都要向月亮倾诉，要用美酒慰藉或庆祝。高兴的时候，“人生得意须尽欢，莫使金樽空对月”（《将进酒》）；孤独失意的时候，“举杯邀明月”，“我歌月徘徊”（《月下独酌》）。“小时不识月，呼作白玉盘”（《古朗月行》），月亮可以算作他的“总角之交”；“举杯邀明月，对影成三人”（《月下独酌》），月亮是他在寂寞时的朋友，永远不会离他而去；“...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6467617530675327e194adfc", "shortContent": "《把酒问月》这诗题就是作者绝妙的自我造像，那飘逸浪漫的风神惟谪仙人方能有之。题下原注：“故人贾淳令予问之。”彼不自问而令予问之，一种风流自赏之意溢于言表。\n\n悠悠万世，明月的存在对于人间是一个魅人的宇宙之谜。“青天有月来几时”的劈头一问，对那无限时空里的奇迹，大有神往与迷惑交驰之感。问句先出，继而具体写其人神往的情态。这情态从把酒“停杯”的动作见出。它使人感到那突如其来的一问分明带有几分醉意，从而...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '明末清初学者唐汝询《汇编唐诗十集》：唐云：收敛豪气，信笔写成，取其雅淡可矣。谓胜《蜀道》诸作，则未敢许。
明末清初思想家、文学家王夫之《唐诗评选》：于古今为创调。乃歌行，必以此为质。然后得施其裁制。供奉特地显出稿木，遂觉直尔孤行，不知独参汤原为诸补中方药之本也！辛幼安、唐子畏未许得与此旨。
日本儒学家、汉学家近藤元粹《李太白诗醇》：奇想自天外来。圆活自在，可谓笔端有舌矣（“但见宵从”二句下）。严沧浪曰：缠绵不堕纤巧，当与《峨眉山月歌》同看。', 'center', 1416739852, '57b8f6f4165abd0054bf8c13', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10492, '烈女操', NULL, 201, 501, 1, 1, '孟郊', NULL, 10030, '57b96453165abd0054c35040', '唐', 'shi', '诗', 'http://baike.baidu.com/view/576772.htm', '', '梧桐相待老，鸳鸯会双死。
贞妇贵殉夫，舍生亦如此。
波澜誓不起，妾心古井水。', '这是一首颂扬贞妇烈女的诗。此诗以男子之心愿，写烈女之情志，可歌可泣。梧桐树相依持老，鸳鸯鸟同生共死。旧世贞烈女，夫死而终生不嫁，夫死而以身相殉。守节以表从一之志，殉节以明坚贞之心。结句「波澜誓不起，妾心古井水」，一片贞心，下语坚决，精警异常。成语「心如古井」源自于此。刘禹锡《竹枝词》名句：「长恨人心不如水，等闲平地起波澜。」从此翻出。烈女节义肝肠，坚贞不渝，固可针砭浮靡；然苛苦迂执，以一身青春配殉，不由刿目怵心，读之令人生怜。据考，当时对女子贞操并不看重。诗人或许另有寄托，籍烈女之吟，抒志洁行廉、孤高耿介之士人气节。', '烈女操：乐府中《琴曲》歌辞。烈女，贞洁女子；操，琴曲中的一种体裁。
梧桐：传说梧为雄树，桐为雌树，其实梧桐树是雌雄同株。
相待老：指梧和桐同长同老。
会：终当。
贞妇：按封建礼教提倡的不失身、不改嫁的女子。
殉：以死相从。
「波澜誓不起，妾心古井水」句：意谓我的心如同古井之水，永远不会泛起情感波澜。古，同「枯」。', '古老的梧桐树总是同生同长，彼此相守到枯老。河中的鸳鸯绝不独生，成双成对厮守终身。贞节妇女的美德，是嫁夫以死相随，舍弃自己的生命也理应如此。我的心静如古井里的水，风再大也掀不起任何波澜。', NULL, '', 'center', 1416740114, '57b92f962e958a005fa6da4c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10493, '登幽州台歌', NULL, 2641, 129, 2, 15, '陈子昂', NULL, 10123, '57babc5e5bbb500063fd70c7', '唐', 'shi', '诗', 'http://baike.baidu.com/view/29192.htm', '', '前不见古人，后不见来者。
念天地之悠悠，独怆然而涕下！', '这是一首吊古伤今的生命悲歌，从中可以看出诗人孤独遗世、独立苍茫的落寞情怀。此诗通过描写登楼远眺，凭今吊古所引起的无限感慨，抒发了诗人抑郁已久的悲愤之情，深刻地揭示了封建社会中那些怀才不遇的知识分子遭受压抑的境遇，表达了他们在理想破灭时孤寂郁闷的心情，具有深刻的典型社会意义。全诗语言苍劲奔放，富有感染力，结构紧凑连贯，又留有充分的空间：前二句俯仰古今，写出时间漫长；第三句登楼眺望，写出空间辽阔；在广阔无垠的时空背景中，第四句描绘了诗人孤独寂寞苦闷的情绪，两相映照，分外动人，读来酣畅淋漓又余音缭绕。', '幽州：古十二州之一，现今北京市。
幽州台：即黄金台，又称蓟北楼，故址在今北京市大兴，是燕昭王为招纳天下贤士而建。
前：过去。.
古人：古代那些能够礼贤下士的圣君。
后：未来。
来者：后世那些重视人才的贤明君主。
念：想到。
悠悠：形容时间的久远和空间的广大。
怆（chuàng）然：悲伤凄恻的样子。
涕：古时指眼泪。', '向前看不见古之贤君，向后望不见当今明主。
一想到天地无穷无尽，我倍感凄凉独自落泪。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e928e2e6a6b501f95be67", "shortContent": "《登幽州台歌》这首短诗，由于深刻地表现了诗人怀才不遇、寂寞无聊的情绪，语言苍劲奔放，富有感染力，成为历来传诵的名篇。\n陈子昂是一个具有政治见识和政治才能的文人。他直言敢谏，对武后朝的不少弊政，常常提出批评意见，不为武则天采纳，并曾一度因“逆党”株连而下狱。他的政治抱负不能实现，反而受到打击，这使他心情非常苦闷。\n武则天万岁通天元年（696），契丹李尽忠、孙万荣等攻陷营州。武则天委派武攸宜率军征讨，...", "authors": ["王运熙"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389abbb31680ae4c4b738", "shortContent": "《登幽州台歌》这首短诗，由于深刻地表现了诗人怀才不遇、寂寞无聊的情绪，语言苍劲奔放，富有感染力，成为历来传诵的名篇。\n\n陈子昂是一个具有政治见识和政治才能的文人。他直言敢谏，对武后朝的不少弊政，常常提出批评意见，不为武则天采纳，并曾一度因“逆党”株连而下狱。他的政治抱负不能实现，反而受到打击，这使他心情非常苦闷。\n\n武则天万岁通天元年（696），契丹李尽忠、孙万荣等攻陷营州。武则天委派武攸宜率军征...", "authors": ["王运熙"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0c7", "shortContent": "武则天万岁通天元年（696），陈子昂任武攸宜幕府参谋，随同武攸宜出征契丹。次年，因武攸宜不识机变，轻率冒进，被契丹李尽忠和孙万荣等人击败，情况危急。陈子昂屡次建言，武攸宜不但不听，还将他降为军曹。在这种逆境中，诗人登上幽州台，写下了这首震烁千古的名作。\n\n幽州古属燕地，战国时代的燕国国小民贫，被齐国攻击，几至亡国。燕昭王励精图治，巩黄金台以招揽贤士，礼遇乐毅、郭槐等人，终于在良臣谋士的帮助下成功复...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270309761253910e904cd", "shortContent": "武则天万岁通天元年（696），陈子昂任武攸宜幕府参谋，随同武攸宜出征契丹。次年，因武攸宜不识机变，轻率冒进，被契丹李尽忠和孙万荣等人击败，情况危急。陈子昂屡次建言，武攸宜不但不听，还将他降为军曹。在这种逆境中，诗人登上幽州台，写下了这首流传千古的名作。\n幽州古属燕地，战国时代的燕国国小民贫，被齐国攻击，几至亡国。燕昭王励精图治，礼遇乐毅、郭隗等人，终于在良臣谋士的帮助下成功复仇。陈子昂本以游侠知名...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270537ccdb86c49f29235", "shortContent": "武则天万岁通天元年（696），陈子昂任武攸宜幕府参谋，随同武攸宜出征契丹。次年，因武攸宜不识机变，轻率冒进，被契丹李尽忠和孙万荣等人击败，情况危急。陈子昂屡次建言，武攸宜不但不听，还将他降为军曹。在这种逆境中，诗人登上幽州台，写下了这首震烁千古的名作。\n幽州古属燕地，战国时期的燕国国小民贫，被齐国攻击，几至亡国。燕昭王励精图治，礼遇乐毅、郭隗等人，终于在良臣谋士的帮助下成功复仇。陈子昂本以游侠知名...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f41fb6a81d0c532b3886", "shortContent": "武则天万岁通天元年(696)，契丹李尽忠、孙万荣等攻陷营州。武则天委派武攸宜率军征讨，陈子昂在武攸宜幕府担任参谋，随同出征。武为人轻率，少谋略。次年兵败，情况紧急，陈子昂请求遣万人作前驱以击敌，武不允。稍后，陈子昂又向武进言，不听，反把他降为军曹。诗人接连受到挫折，眼看报国宏愿成为泡影，因此登上蓟北楼（即幽州台，遗址在今北京市），慷慨悲吟，写下了《登幽州台歌》以及《蓟丘览古赠卢居士藏用七首》等诗篇...", "authors": ["王运熙"], "pressName": "上海辞书出版社"}]', '杨慎《升庵诗话》：其辞简质，有汉魏之风。
黄周星《唐诗快·卷二》：胸中自有万古，眼底更无一人。古今诗人多矣，从未有道及此者。此二十二字，真可以泣鬼。
宋长白《柳亭诗话》：阮步兵登广武城，叹曰：「时无英雄，遂使竖子成名。」眼界胸襟，令人捉摸不定。陈拾遗会得此意，《登幽州台歌》曰：「前不见古人，后不见来者。念天地之悠悠，独怆然而涕下」，假令陈、阮邂逅路歧，不知是哭是笑。', 'center', 1416740277, '57b8e0eedf0eea006334387f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10494, '古意', NULL, 159, 124, 2, 2, '李颀', NULL, 10124, '57b9a05e8ac2470063fdd3af', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/158115/6415619.htm', '', '男儿事长征，少小幽燕客。
赌胜马蹄下，由来轻七尺。
杀人莫敢前，须如猬毛磔。
黄云陇底白雪飞，未得报恩不能归。
辽东小妇年十五，惯弹琵琶解歌舞。
今为羌笛出塞声，使我三军泪如雨。', '此诗是唐代诗人李颀创作的一首古体诗。首六句写戍边豪侠的风流潇洒，勇猛刚烈。后六句写见得白云，闻得羌笛，顿觉故乡渺远，不免怀思落泪。离别之情，征战之苦，跃然纸上。语言含蓄顿挫，血脉豁然贯通，跌宕起伏，情韵并茂。', '古意：拟古诗，托古喻今之作。
事长征：从军远征。
幽燕：今河北、辽宁一带。古代幽燕地区遊侠之风盛行。
赌胜：较量胜负。
马蹄下：卽驰骋疆场之意。
「由来轻七尺」句：好男儿向来就轻视性命。七尺，七尺之躯。古时尺短，七尺相当于一般成人的高度。
「杀人莫敢前」句：杀人而对方不敢上前交手，即所向无敌之意。
「须如猬毛磔（zhé）」句：鬍须好像刺猬的毛一样纷纷张开，形容威武凶猛。磔，纷张。
黄云：指战场上升腾飞扬的尘土。
陇：泛指山地。
白雪飞：又作“白云飞”。
不能归：一作“不得归”。
小妇：少妇。
解歌舞：擅长歌舞。解，懂得、通晓。
羌（qiāng）笛：又称羌管，我国古代的一种单簧气鸣乐器。羌，古代西北地区少数民族。
塞（sài）：边塞。
三军：指骑马打仗的前、中、後三军。', '好男儿远去从军戍边，他们从小就遊历幽燕。
个个爱在疆场上逞能，为取胜不把生命依恋。
厮杀时顽敌不敢上前，鬍须象猬毛直竖满面。
陇山黄云笼罩白雪纷飞，不曾立过战功怎想回归？
有个辽东少妇妙龄十五，一向善弹琵琶又善歌舞。
她用羌笛吹奏出塞歌曲，吹得三军将士泪挥如雨。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9292911759740c9b19f9", "shortContent": "此诗题为“古意”，标明是一首拟古诗。开始六句，把一个在边疆从军的男儿描写得神形毕肖，栩栩如生，活跃在读者眼前。第一句“男儿”两字先给读者一个大丈夫的印象。第二句“少小幽燕客”，交代从事长征的男儿是自古多慷慨悲歌之士的幽燕一带人，为下面描写他的刚勇犷悍张本。这两句总领以下四句。他在马蹄之下与伙伴们打赌比输赢，从来就不把七尺之躯看得那么重，所以一上战场就奋勇杀敌，杀得敌人不敢向前。“赌胜马蹄下，由来轻...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0c8", "shortContent": "这首诗写一位勇士的侠骨柔情，由外到内，从形象不断深入内心的多元。\n首先以“事长征”、“幽燕客”数语，简笔勾勒出一位有志男儿的形象。这位勇士以国事为己任，长年征战在幽燕边庭。他勇猛异常：在战马奔驰之际较量胜负，从来没有把自己的性命看成一回事；厮杀时顽敌不敢上前。他长得也极其粗犷，胡须像刺猬毛一样纷张，威武凶猛。从事迹到外貌，豪迈勇敢、视死如归的勇士形象一步步生动起来。\n\n这时，作者宕开笔去。因为勇猛...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127036c9ebcc6fbea1a3a5", "shortContent": "这首诗是一首拟古诗，写一位勇士的侠骨柔情。首先以“事长征”、“幽燕客”数语，简笔勾勒出一位有志男儿的形象。这位勇士以国事为己任，长年征战在幽燕边庭。他勇猛异常：在战马奔驰之际较量胜负，从来没有把自己的性命当作一回事；在战场上奋勇杀敌，杀得敌人胆战心惊。他长得也极其粗犷：胡须像刺猬的刺一样，又短又硬，显示出边塞男儿的勇猛气概。从事迹到外貌，一个豪迈勇敢、视死如归的勇士形象逐渐生动起来。\n\n这时，作者...", "authors": ["张春晓"], "pressName": "崇文书局"}]', '张文荪《唐闲清雅集》：奇气逼人，下忽变作凄苦音调，妙极自然。', 'center', 1416740468, '57b99c39c4c971005594c8ff', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10495, '送陈章甫', NULL, 152, 124, 2, 2, '李颀', NULL, 10124, '57b9a05e8ac2470063fdd3af', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383108.htm', '', '四月南风大麦黄，枣花未落桐阴长。
青山朝别暮还见，嘶马出门思旧乡。
陈侯立身何坦荡，虬须虎眉仍大颡。
腹中贮书一万卷，不肯低头在草莽。
东门酤酒饮我曹，心轻万事皆鸿毛。
醉卧不知白日暮，有时空望孤云高。
长河浪头连天黑，津口停舟渡不得。
郑国游人未及家，洛阳行子空叹息。
闻道故林相识多，罢官昨日今如何。', '此诗是唐代诗人李颀写给友人陈章甫的赠别之作。开头四句写送别，轻快舒坦，情怀旷达；中间八句，写陈章甫志节操守，说他光明磊落，清高自重；最后六句，用比兴手法暗喻仕途险恶，世态炎凉。诗人以豁达的情怀，表现了友人的性格和遭遇，表达了诗人对友人的情谊。全诗用语轻松，格调豪放，虽为送别之作，但绝无儿女沾巾之态，别具一格。', '陈章甫：江陵（今湖北省江陵县）人。
阴：同「荫」，一作「叶」。
「青山朝别暮还见，嘶马出门思旧乡」句：谓陈章甫因朝夕相见的青山而起思乡之情。一说因为思乡很快就回来了，意即早晨辞别故乡的青山，晚上又见到了。嘶，马鸣。
陈侯：对陈章甫的尊称。
虬须：卷曲的胡子。虬，蜷曲。
大颡（sǎng）：宽大的脑门。颡，前额。
贮：保存。
「不肯低头在草莽」句：谓不肯埋没草野，想出仕作一番事业。陈章甫曾应制科及第，但因没有登记户籍，吏部不予录用。经他上书力争，吏部只得请示破例录用，这事受到天下士子赞美，陈章甫也因此名扬天下，但一直仕途不顺。
酤（gū）酒：买酒。
饮：使……喝。
曹：辈，侪。
皆：一作「如」。
鸿毛：雁羽，喻极轻之物。
「东门酤酒饮我曹，心轻万事皆鸿毛」句：谓陈章甫虽仕实隐，只和作者等人饮酒醉卧，却把万世看得轻如鸿毛。
津口：渡口。一作「津吏」，管渡口的官员。
郑国游人：指陈章甫，河南在春秋时郑国故地，陈章甫曾在河南居住很近，故作者称其为「郑国游人」。
洛阳行子：李颀自称，因李颀曾任新乡县尉，地近洛阳，故名「洛阳行子」。
故林：故乡。陶渊明《归园田居》：「羁鸟恋故林。」
「闻道故林相识多，罢官昨日今如何」句：听说你在故乡相识很多，你已经罢了官，现在他们会如何看待你呢？', '四月南风吹大麦一片金黄，枣花未落梧桐叶子已抽长。
早晨辞别青山晚上又相见，出门闻马鸣令我想念故乡。
陈侯的立身处世襟怀坦荡，虬须虎眉前额宽仪表堂堂。
你胸藏诗书万卷学问深广，怎么能够低头埋没在草莽。
在城东门买酒同我们畅饮，心宽看万事都如鸿毛一样。
喝醉酒酣睡不知天已黄昏，有时独自将天上孤云眺望。
今日黄河波浪汹涌连天黑，行船在渡口停驻不敢过江。
你这郑国的游人不能返家，我这洛阳的行子空自叹息。
听说你在家乡旧相识很多，罢官回去他们如何看待你？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9292911759740c9b19f6", "shortContent": "李颀的送别诗，以善于描述人物著称。本诗即为一首代表作。\n陈章甫是个很有才学的人，原籍不在河南，不过长期隐居嵩山。他曾应制科及第，但因没有登记户籍，吏部不予录用。经他上书力争，吏部辩驳不了，特为请示执政，破例录用。这事受到天下士子的赞美，使他名扬天下。然其仕途并不通达，因此无意官事，仍然经常住在寺院郊外，活动于洛阳一带。这首诗大约作于陈章甫罢官后登程返乡之际，李颀送他到渡口，以诗赠别。前人多以为陈章...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0c9", "shortContent": "陈章甫，曾官任太常博士。这首诗送别故人，不仅道出了临别珍重之意，更把陈章甫的风采和个性生动地描绘出来。\n\n“四月”二句写物候特征，“青山”二句点明自己的客居身份。客居无聊，骑着马儿出门排遣思乡之情，早上出门，晚上归来，看到的却还是那座青山，不免更让人怀念故乡了。难耐乡愁之际，又要送走失意的朋友，诗人的心情可想而知。\n\n“陈侯”以下八句写陈章甫。陈侯即陈章甫，侯为尊称。其为人处事立身坦荡，开朗豪放。...", "authors": ["张春晓"], "pressName": "崇文书局"}]', '《批点唐音》：首二句化腐处须自得。接二句浅浅说便佳。「有时空望孤云高」，豪语胜前多矣。
《增订评注唐诗正声》：起四语浅妙，中段豪甚，不见其谀。
《唐诗解》：叙别有次第，中段数语何等心胸！
《唐诗选脉会通评林》：吴山民曰：高华悲壮，李集佳篇。「虬须」句，道子写真岂复过此？「醉卧」、「不知」二语，知是高调。结系钵手。
《唐诗评选》：颀集绝技，骨脉自相均适。
《唐贤三昧集笺注》：读来神韵悠然（「四月南风」四句下）。丰骨超然（「醉卧不知」二句下）。
《唐贤清雅集》：开局宏敞，音节自然。写奇崛如见。收得妙。
《昭昧詹言》：何等警拔，便似嘉州、达夫。起二句奇景涌出。「东门沾酒」句换气。', 'center', 1416757781, '57b941e48ac2470062e1c02d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10496, '琴歌', NULL, 216, 124, 2, 2, '李颀', NULL, 10124, '57b9a05e8ac2470063fdd3af', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383109/10129730.htm', '', '主人有酒欢今夕，请奏鸣琴广陵客。
月照城头乌半飞，霜凄万树风入衣。
铜炉华烛烛增辉，初弹渌水后楚妃。
一声已动物皆静，四座无言星欲稀。
清淮奉使千余里，敢告云山从此始。', '这首诗记一次宴会听琴的情景。前六句以室外凄清的秋景来反衬华堂上炉火融融、红烛高烧的温暖欢乐。后四句以琴声一响万簌俱静，听者沉醉无言，并且引动诗人辞官归隐的念头，来表现音乐神奇的感染力量。', '琴歌：听琴有感而歌。歌是诗体名，《文体明辨》：「其放情长言，杂而无方者日歌。」
主人：东道主。
广陵客：广陵在今江苏扬州，唐淮南道治所。古琴曲有《广陵散》，魏嵇康临刑奏之。「广陵客」指琴师。
乌：乌鸦。
半飞：分飞。
霜凄万树：夜霜使树林带有凄意。
铜炉：铜制熏香炉。华烛：饰有文采的蜡烛。
渌水、楚妃：都是古琴曲。渌，清澈。
星欲稀：后夜近明时分。
清淮：淮水。时李颀即将赴任新乡尉，新乡临近淮水，故称清淮。
奉使：奉使命。
敢告：敬告。
云山：代指归隐。', '主人摆酒今晚大家欢聚，琴师拨动琴弦助兴酒宴。
明月照向城头乌鸦纷飞，寒霜降临寒风吹透衣衫。
炉火暖融融华烛添光辉。艺人先弹《渌水》后奏《楚妃》。
万物均已静静悄悄，只有琴声在空中荡漾;四座听琴的人鸦雀无声，沉浸在美妙的乐声之中，不觉天都快亮了。
奉命去远离乡关清淮，敬告大家我要归隐云山。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0ca", "shortContent": "李颀是盛唐时代最善于描写音乐的诗人之一。琴、笳、觱篥，这些乐器演奏的情景均能完美地在他笔下再现。本首诗就是描写琴的演奏的。\n\n起句颇似南朝诗歌韵味。“主人有酒欢今夕”，南朝《子夜歌》有“今夕已欢别，合会在何时”之句。贤主人热情好客，酒已满上，今夕且尽欢！座上有广陵之客，请奏鸣琴，与宾主尽欢。此句简洁地交代了奏琴的场合。广陵，即今江苏省扬州市，三国时嵇康有名曲《广陵散》，嵇康刑于东市，长叹曰：“《广...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '', 'center', 1416757883, '57b59af3165abd0065d1e51b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10497, '听董大弹胡笳声兼寄语弄房给事', NULL, 96, 124, 2, 1, '李颀', NULL, 10124, '57b9a05e8ac2470063fdd3af', '唐', 'shi', '诗', 'http://baike.baidu.com/view/4384843.htm', '', '蔡女昔造胡笳声，一弹一十有八拍。
胡人落泪沾边草，汉使断肠对归客。
古戍苍苍烽火寒，大荒沉沉飞雪白。
先拂商弦后角羽，四郊秋叶惊摵摵。
董夫子，通神明，深山窃听来妖精。
言迟更速皆应手，将往复旋如有情。
空山百鸟散还合，万里浮云阴且晴。
嘶酸雏雁失群夜，断绝胡儿恋母声。
川为静其波，鸟亦罢其鸣。
乌孙部落家乡远，逻娑沙尘哀怨生。
幽音变调忽飘洒，长风吹林雨堕瓦。
迸泉飒飒飞木末，野鹿呦呦走堂下。
长安城连东掖垣，凤凰池对青琐门。
高才脱略名与利，日夕望君抱琴至。', '全诗写董大以琴弹奏《胡笳弄》这一历史名曲，意在描摹琴声，明以赞董大，暗以颂房给事。全诗巧妙地把董大之演技、琴声，以及历史背景、历史人物的感情结合起来，既周全细致又自然浑成。最后称颂房给事，也寄托自身的倾慕之情。诗以惊人的想象力，把风云山川，鸟兽迸泉，以及人之悲泣，人为描摹琴声的各种变化，使抽象的琴声变成美妙具体的形象，使读者易于感受，是一首较早描写音乐的好诗。', '', '', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92932e6a6b501f95bee4", "shortContent": "李颀此诗，约作于天宝六七载（747—748）间。董大即董庭兰，是当时著名的琴师。所谓“胡笳声”，也就是《胡笳弄》，是按胡笳声调翻为琴曲的。所以董大是弹琴而非吹奏胡笳。\n这首七言古体长诗，通过董大弹奏《胡笳弄》这一历史名曲，来赞赏他高妙动人的演奏技艺，也以此寄房给事（房琯），带有为他得遇知音而高兴的心情。\n诗开首不提“董大”而说“蔡女”，起势突兀。蔡女指东汉末年的蔡琰（文姬）。文姬归汉时，感笳之音，...", "authors": ["姚奠中"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0fd", "shortContent": "李颀此诗，约作于天宝六、七载（747—748）间。董大即董庭兰，是当时著名的琴师。所谓“胡笳声”，也就是《胡笳弄》，是按胡笳声调翻为琴曲的。所以董大是弹琴而非吹奏胡笳。\n\n这首七言古体长诗，通过董大弹奏《胡笳弄》这一历史名曲，来赞赏他高妙动人的演奏技艺，也以此寄房给事（房琯），带有为他得遇知音而高兴的心情。\n\n诗开首不提“董大”而说“蔡女”，起势突兀。蔡女指东汉末年的蔡琰（文姬）。文姬归汉时，感笳...", "authors": ["姚奠中"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0cb", "shortContent": "董大，名董庭兰，是玄宗时期著名的琴师，时为门下省给事中房琯的门客。这首七言古诗通过描述董大弹奏《胡笳弄》来赞赏他高超的音乐造诣，祝贺他得遇房琯赏识，也暗寓了诗人的身世感慨。\n\n前六句写《胡笳弄》曲，将读者引入一种幽邃的艺术境界。当年蔡琰曾作胡笳曲，弹奏此曲总共有十八节。《胡笳十八拍》为哀曲悲声，“胡笳动兮边马鸣，孤雁归兮声嘤嘤”。三、四两句即写文姬操琴时胡人、汉使悲切断肠的场面，反衬琴曲的感人魅力...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '', 'center', 1416758062, '57b8ff750a2b58005c9233ad', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10498, '听安万善吹觱篥歌', NULL, 99, 124, 3, 1, '李颀', NULL, 10124, '57b9a05e8ac2470063fdd3af', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383133.htm', '', '南山截竹为觱篥，此乐本自龟兹出。
流传汉地曲转奇，凉州胡人为我吹。
傍邻闻者多叹息，远客思乡皆泪垂。
世人解听不解赏，长飙风中自来往。
枯桑老柏寒飕飗，九雏鸣凤乱啾啾。
龙吟虎啸一时发，万籁百泉相与秋。
忽然更作渔阳掺，黄云萧条白日暗。
变调如闻杨柳春，上林繁花照眼新。
岁夜高堂列明烛，美酒一杯声一曲。', '此诗写诗人听了胡人乐师安万善吹奏觱篥，称赞他高超的演技，同时写觱篥之声凄清，闻者悲凉。前六句先叙篥的来源及其声音的凄凉；中间十句写其声多变，为春为秋，如凤鸣如龙吟；末两句写诗人身处异乡，时值除夕，闻此尤感孤寂凄苦。诗在描摹音乐时，不仅以鸟兽树木之声作比，同时采用通感手法，写得形象生动，富有感染力。', '觱篥（bìlì）：亦作：“筚篥”、“悲篥”，又名“笳管”。簧管古乐器，似唢呐，以竹为主，上开八孔（前七后一），管口插有芦制的哨子。汉代由西域传入，几近失传。
龟兹（qiūcí）：古西域城国名，在今新疆库车、沙雅一带。
曲转奇：曲调变得更加新奇、精妙。
凉州：在今甘肃一带。
傍：靠近、临近，意同“邻”。
远客：漂泊在外的旅人。
解：助动词，能、会。苏轼《六月二十日夜渡海》：“苦雨终风也解晴。”
飙（biāo）：暴风，这里用如形容词。自：用在谓语前，表示事实本来如此，或虽有外因，本身依然如故。可译为“本来，自然”。《史记》：“桃李不言，下自成蹊。”
飕飗（sōuliú）：拟声词，风声。
九雏鸣凤：典出古乐府“凤凰鸣啾啾，一母将九雏”，形容琴声细杂清越。
万籁：自然界的各种天然音响。百泉：百道流泉之声音。相与：共同、一起。陶渊明《移居二首》：“奇文共欣赏，疑义相与析。”
渔阳掺：渔阳一带的民间鼓曲名，这里借代悲壮、凄凉的之声。
黄云：日暮之云。李白《乌夜啼》：“黄云城边乌欲栖，归飞哑哑枝上啼。”萧条：寂寥、冷落。
杨柳：指古曲名《折杨柳》，曲调轻快热闹。
上林：即上林苑，古宫苑名，有两处：一为秦都咸阳时置，故址在今陕西西安市西；一为东汉时置，故址在今河南洛阳市东。新：清新。
岁夜：除夕。
声：动词，听。谭嗣同《仁学》：“目不得而色，耳不得而声，口鼻不得而臭味。”', '从南山截段竹筒做成觱篥，这种乐器本来是出自龟兹。
流传到汉地曲调变得新奇，凉州胡人安万善为我奏吹。
座旁的听者个个感慨叹息，思乡的游客人人悲伤落泪。
世人只晓听曲不懂得欣赏，乐人就像独行于暴风之中。
又像风吹枯桑老柏沙沙响，还像九只雏凤鸣叫啾啾啼。
好似龙吟虎啸同时都爆发，又如万籁齐响秋天百泉汇。
忽然变作渔阳掺低沉悲壮，顿使白日转昏暗乌云翻飞。
再变如同杨柳枝热闹欢快，仿佛看到上林苑繁花似锦。
除夕夜高堂上明烛放光芒，喝杯美酒再欣赏一曲觱篥。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92925e272d4b2254317a", "shortContent": "李颀有三首涉及音乐的诗。一首写琴（《琴歌》），以动静二字为主，全从背景着笔。一首写胡笳（《听董大弹胡笳弄兼寄语房给事》），以两宾托出一主，正写胡笳。这一首写觱篥，以赏音为全诗筋脊，正面着墨。三首诗的机轴，极容易相同，诗人却写得春兰秋菊，各极一时之妙。这首诗的转韵尤为巧妙，一共只有十八句，依诗情发展，变换了七个不同的韵脚，声韵意境，相得益彰。\n“南山截竹为觱篥”，先点出乐器的原材料；“此乐本自龟兹出...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0cc", "shortContent": "本诗写觱篥之乐。觱篥，一种簧管乐器，以竹为管，管口插有芦制哨子，有九孔，出自西域龟兹，故曰“南山截竹为觱篥，此乐本自龟兹出”。南山，指长安南边的终南山；龟兹，汉西域诸国之一，地在今天山南麓。开篇即交代觱篥之乐的缘起。\n\n觱篥在西域，毕竟音域未广，曲目不丰。流传汉地之后，其曲愈转愈奇。凉州胡人，指安万善。安为昭武九姓之一，地在今中亚地区。安万善应为昭武九姓灭国后流落至中原的胡人，善吹觱篥，故其曲吹出...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '《唐诗归》：谭云：与世人学舞只是舞，同一高寄之言，而“长飙风中”句形容聋聩人光景可笑（“世人解听”二句下）。
《历代诗法》：行间善自裁制，故不至于烦芜，而笔情所向，又多油然惬适。
《唐贤三昧集笺注》：步步踏实，绝不空衍。亦是对叠，妙乃如此（“傍邻闻者”二句下）。都是叠，甚得声韵。换韵平仄互用，吋多用二句一解，自觉音调急促。', 'center', 1416758253, '57b946d3a633bd00665fae67', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10513, '石鼓歌', NULL, 58, 482, 0, 1, '韩愈', NULL, 10125, '57ba30008ac247006301a306', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/350138/16470172.htm', '', '张生手持石鼓文，劝我试作石鼓歌。
少陵无人谪仙死，才薄将奈石鼓何。
周纲陵迟四海沸，宣王愤起挥天戈。
大开明堂受朝贺，诸侯剑佩鸣相磨。
蒐于岐阳骋雄俊，万里禽兽皆遮罗。
镌功勒成告万世，凿石作鼓隳嵯峨。
从臣才艺咸第一，拣选撰刻留山阿。
雨淋日炙野火燎，鬼物守护烦撝呵。
公从何处得纸本，毫发尽备无差讹。
辞严义密读难晓，字体不类隶与蝌。
年深岂免有缺画，快剑斫断生蛟鼍。
鸾翔凤翥众仙下，珊瑚碧树交枝柯。
金绳铁索锁钮壮，古鼎跃水龙腾梭。
陋儒编诗不收入，二雅褊迫无委蛇。
孔子西行不到秦，掎摭星宿遗羲娥。
嗟余好古生苦晚，对此涕泪双滂沱。
忆昔初蒙博士征，其年始改称元和。
故人从军在右辅，为我度量掘臼科。
濯冠沐浴告祭酒，如此至宝存岂多。
毡包席裹可立致，十鼓只载数骆驼。
荐诸太庙比郜鼎，光價岂止百倍过。
圣恩若许留太学，诸生讲解得切磋。
观经鸿都尚填咽，坐见举国来奔波。
剜苔剔藓露节角，安置妥帖平不颇。
大厦深檐与盖覆，经历久远期无陀。
中朝大官老于事，讵肯感激徒媕婀。
牧童敲火牛砺角，谁复着手为摩挲。
日销月铄就埋没，六年西顾空吟哦。
羲之俗书趁姿媚，数纸尚可博白鹅。
继周八代争战罢，无人收拾理则那。
方今太平日无事，柄任儒术崇丘轲。
安能以此上论列，愿借辩口如悬河。
石鼓之歌止于此，呜呼吾意其蹉跎。', '此诗从石鼓的起源到论述它的價值，其创作目的是呼吁朝廷予以重视与保护。开头四句是总起，自谦没有李杜之才，不敢作歌。「周纲」十二句是追叙石鼓来历久远。「公从」十句是叙石鼓的文字和字体及其保留的價值。「陋儒」六句是叙怀疑《诗经》不收石鼓文，乃是孔子的粗心。「忆昔」十八句，是叙发现石鼓的经过和建议留置太学。「中朝」十句是叙当局不纳诗人建议，叹惜石鼓文物的废除。最後六句，希望在尊崇儒学的时代，能把石鼓移置太学。
全诗表达了诗人对古代文物的珍视之情，同时对朝中重臣和「陋儒」们进行了无情的嘲讽。章法整齐、辞严义密，音韵铿锵，诗人在描绘石鼓文书法的妙处时，运用了多種比喻，进行淋漓尽致的渲染，颇有感染力。', '张生：據《全唐诗》校「生即籍」，可知此指张籍。
石鼓文：这是指从石鼓上搨印下来的文字。
才薄：是说自己的才力薄弱，不能像杜少陵、李太白他们那樣，有纵横驰骋的诗笔。
将奈石鼓何：是说像我这樣才力薄弱的人，将怎能作好这石鼓歌呢？
周纲；周朝的纲纪法度，亦即政治秩序。
陵迟：衰落、衰败。
四海沸：指天下动荡不安。
宣王：周宣王，姓姬名静，一作靖，周厉王的儿子，旧时被认为是周朝的中兴之主。
挥天戈：指周宣王对淮夷、西戎、狁等用兵的事。
明堂：天子颁布政教，朝见诸侯，举行祭祀的地方。
剑佩鸣相磨：是说到天子明堂来朝贺的诸侯很多，以致彼此佩带的刀剑互相磨擦而发出声响。
蒐（sōu）于歧阳：是说周宣王在一个春天裏于歧山南面打猎。蒐，春天打猎；岐阳，歧山之南（山南为阳）。
万里禽兽皆遮罗：广阔的猎场裏的禽兽都将被拦捕了来。遮罗，拦捕。
镌（juān）功：指将功业刻在石鼓上。镌、勒，都是刻的意思；成，成就，与「功」同义。
告万世：即告示後代于万世。
凿石作鼓隳嵯峨（huīcuóé）：为了製作石鼓而开山凿石。隳，毁坏；嵯峨，山势高峻的樣子，这裏是指高山。
从臣：指随从周宣王的臣子。
咸第一：都是第一等的。
撰刻：指撰写文字刻于石鼓之上。
山阿：泛指山陵。
「雨淋日炙（zhì）野火燎，鬼物守护烦撝（huī）呵。」句是说，这石鼓经受聘发长期的日晒雨淋和野火的燎烤，竟能这樣安然无恙；那是有劳鬼神的护持，不让它们遭到伤害。日灸，日晒；烦，劳；撝，同「挥」；呵，喝叱。
公：张生，指张籍。
纸本：指从石鼓上搨印下来的文字纸本。
毫发尽备无差讹：搨印下来的文本极为完整，不有丝毫的差错。讹，错误。
辞严义密：指搨本的文字庄严，义理精密。
不类：不像。
蝌：蝌蚪文，周时所用文字，因其头大尾小，形似蝌蚪文。石鼓文的文字当为籀文，即大篆。
缺画：是说石鼓上的文字因年深日久，不可避免会有向导笔漏画的。
蛟：蛟龙，古代传说中的一種神异动物。
鼍（tuó）：鼍龙，俗称猪婆龙，是鱷鱼的一種。这裏的蛟鼍即蛟龙，因押韵，故改龙为鼍。
快剑斫断生蛟鼍：石鼓文上那些向导笔漏画的地方，像是快剑把活生生的蛟龙斫断了一樣。这是极力形容古代文字形体气势的生动有力。
翔、翥（zhù）：都是飞的意思。
珊瑚树：因珊瑚形状像树枝，故称珊瑚碧树。
「鸾翔凤翥众仙下，珊瑚碧树交枝柯。」句：石鼓上的文字像是仙人乘着鸾凤翩翩而下，又像是珊瑚碧树似的枝柯扶疏。这都是极办形容石鼓文的体势飞动和笔锋奇丽。
金绳铁索：比喻石鼓文的笔锋奇劲如金绳铁索一般。
锁纽：比喻石鼓文的的结体如锁纽般的钩连。
古鼎跃水：相传周显王四十二所，九鼎没于四水，秦始皇时派人入水不得。
龙腾梭：《晋书·陶侃传》：「侃少时，渔于雷泽，网得一织梭，以挂于壁。有顷雷雨自化为龙而去。」这句是形容石鼓文字体的变化莫测。
陋儒：见识短浅的儒生，指当时采风编诗者。
诗：指《诗经》。
二雅：指《诗经》的《大雅》和《小雅》。
褊（biǎn）迫：局促。
委蛇（wēituó）：宽大从容的樣子。这句是说二雅没有把石鼓文收进去，是由于时采风编诗者的见识短浅。
秦：秦国，今陕西一带，即石鼓所在的地方。石鼓于唐初在天兴（今陕西省宝鸡市）三畦原出土。
掎摭（jǐzhí）：采取。
遗：丢了。
羲：羲和，为日驾车的人，这裏代指日。
娥：嫦娥，这裏指月。
「孔子西行不到秦，掎摭星宿遗羲娥。」句：孔子西行没有到过秦国，结果编诗未收石鼓文，那就像是拾了星星，却等待以了太阳和月亮。
好古：爱好古代文化。
生苦晚：苦于出生太晚。
此；指石鼓文。
双滂沱：指眼泪和鼻涕一同流出。意即令人无限感伤而泪如雨下了。
蒙：蒙受。
博士：官名。唐时有太学、国子诸博士，并为教授之官。
其年：那一年，即韩昌黎自江陵法曹参军被召回长安任国子监博士的元和元年（西元八〇六年）。
故人：不详。
从军在右辅：《三辅黄图》：「太初元年（西元前一〇四年）以渭城以西属右扶风，长安以东属京兆尹，长陵以北属左冯翊，以辅京师，谓之三辅。」右辅，即右扶风，为凤翔府。韩昌黎故人为凤翔节度府从事，所以说「从军在右辅」。
度（duó）量：计划。
掘：挖。
臼科：坑穴，指安放石鼓的地方。
濯冠：洗帽子。
沐：洗头。
浴：洗澡。这都是表示诚敬的意思。
祭酒：官名。唐时为国子监的主管官。
至宝：极为贵重的宝物。
「毡包席裹可立致，十鼓只载数骆驼。」句：是说十隻石鼓只要幾匹骆驼运载就行了。
荐：进献。
诸：是「之于」二字的合音，用意亦同。
太庙：皇家的祠堂。
郜（gào）鼎：郜国所造的鼎。《左传·桓公二年》；「四月，取郜大鼎于宋，戊申，纳于太庙。」郜国在今山东省城武县。
光價：光荣的声價。
「荐诸太庙比郜鼎，光價岂止百倍过。」句：把石鼓荐之于太庙和郜鼎并比，那声價何止超过百倍呢？
圣恩：皇恩。
太学：指国子监。
诸生：指在太学进修的学生。
切磋：指对学问的钻研，这裏是指对石鼓的钻研。
观经鸿都：汉灵帝光和元年（西元一七八年），置鸿门学士。鸿都门为藏书的处所。又汉灵帝熹平四年（西元一七五年），蔡邕奏请正定六经文字，并刻石碑，立于太学门外，即熹平石经。从此，每天前来观看和摹写的人很多，十分拥挤，阻塞街道。
填咽（yè）：阻塞，形容人多拥挤。
坐：即将。坐见：即将看到。
剜（wān）：刀挖。
剔：剔除。
节角：指石鼓文字笔画的棱角。
安置妥帖：安放妥当。
不颇（pō）：不偏斜。
檐：屋檐、深檐，也是「大厦」的意思。
覆：遮盖。
期无佗（tuó）：希望石鼓没有任何的损坏。无佗，同「无他」。
中朝：即朝中，朝廷裏。
老于事：实指老于世故，即办事拖沓、保守的意思。
肯：岂肯。
感激：感动激发。
徒：只。
媕婀（ānē）：无主见的意思。
敲火：指牧童无知，随便在石鼓上敲击时爆出火星，有损石鼓。
砺：磨擦。
着手：即用手。
摩挲（suō）：常指对文物古玩的抚摩，表示爱惜的意思。
销：熔化金属。
铄（shuò）：指金属熔化。
就：趋向、归于。
六年：即元和六年（西元八一一年）。
西顾：指西望石鼓所在地岐阳。岐阳即岐山南面，山在长安、洛阳西，故称「西顾」。
空吟哦：空费心思的意思。
俗书：沈归愚《唐诗别裁》：「隶书风俗通行，别于古篆，故云俗书，无贬右军意。」认为俗书是对古书而言，是时俗之俗，非俚俗之俗，不是贬意。但就韩昌黎对石鼓文字的无比推崇来看，王羲之的书法自然会被他认为是俗的了，实含贬意。
趁姿媚：追求柔媚的姿态。
博白鹅：换白鹅。據《晋书·王羲之传》载，他很喜欢鹅，曾用「数纸」自己所写的《道德经》去换取山阴道士的鹅。
八代：所指不明，泛指秦汉之後诸朝。一说是秦、汉、魏、晋、元魏、齐、周、隋；又说是东汉、魏、晋、宋、齐、梁、陈、隋。
收拾：指把散乱的会物收集起来。这裏是指把石鼓收集起来加以保存的意思。
则那（nuò）：又奈何。
柄任儒术：即重用儒学之士的意思。柄，权柄；任，用。
崇丘轲：尊崇孔子、孟子。
论列：议论、建议。
悬河：比喻有辩才，即善于辞令。《晋书·郭象传》：「太尉王衍每云，听象语（说话）如悬河泻水，注而不竭。」
止于此：到此为止。
其：将。
蹉跎：本指岁月虚度，这裏作失意解，即白费了心思。与前文的「空吟哦」意同，且相照应。', '张生手拿周朝石鼓文的拓本，劝我写一首咏赞它的石鼓歌。
少陵太白才华盖世但都作古，薄才之人面对石鼓无可奈何。
周朝政治衰败全国动荡不安，周宣王发愤起兵挥起了天戈。
庆功之时大开明堂接受朝贺，诸侯接踵而至剑佩叮当撞磨。
宣王田猎驰骋岐阳多么英俊，四方禽兽无处躲藏都被网罗。
为把英雄功业刻石扬名万世，凿山石雕石鼓毁坏高山嵯峨。
随从之臣才艺都是世上第一，挑选优秀撰写刻石放在山坡。
任凭长年雨打日晒野火焚烧，仗着鬼神守护石鼓永不湮没。
你从哪裏得来这拓本的底稿？丝毫都很完备一点也无差错。
言辞严谨内容奥密难于理解，字体不像隶书蝌文自成一格。
年代久远难免受损笔画残缺，仍像得剑斩断活生生的蛟鼍。
字迹有如鸾凤翔飞众仙飘逸，笔画恰似珊瑚碧树枝柯交错。
苍劲钩连像金绳铁索穿锁钮，浑然又像织梭化龙九鼎沦没。
浅见儒士编纂诗经却不收入，大雅小雅内容狭窄并不壮阔。
孙子周遊未到秦地无知难怪，采诗不全像取星宿却漏羲娥。
啊我虽好古却苦于生得太晚，对着石鼓文我哭得涕泪滂沱。
想当年我蒙召做国子监博士，那年正改纪元年号称着元和。
我的朋友在凤翔府任职从事，曾经为我设计挖掘石鼓坑窝。
我刷帽沐浴禀告国子监祭酒：“如此至宝文物世上能存幾多？
只要包毡裹席就能立即运到，十个石鼓运载只需幾匹骆驼。
进献太庙把它比作文物郜鼎，那声價百倍于郜鼎岂是太过？
皇恩浩荡如果准许留在太学，诸生就能钻研解说一起切蹉。
汉朝时鸿都门观经尚且拥塞，将会看见全国上下为此奔波。
剜剔藓苔泥尘露出文字棱角，把它放得平平稳稳不偏不颇。
高楼大厦深檐厚瓦把它覆盖，经历久远不受意外损坏伤挫。”
朝中的大官个个都老于世故，他们空无主见岂肯感奋奔波？
牧童在鼓上敲火牛用它磨角，谁能再用手把这个宝物抚摸？
长年累月风化销铄将被埋没。六年来向西遥望我空叹吟哦！
王羲之书法时俗趁機显秀媚，书写数张还可换回一群白鹅。
继周之後八代争战已经结束，至今无人收拾整理又可奈何？
如今正是天下太平国泰民安，皇上重视儒术推崇孔丘孟轲。
怎么纔能把此事向皇帝建议，愿借善辩之人发挥口若悬河。
石鼓歌写到这裏就算结束吧，哎呀我的意愿大概会是白说！', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f092fd", "shortContent": "这首诗作于唐宪宗元和六年（811）。初唐时有石鼓出土于凤翔府天兴县（今陕西宝鸡），系中国最早的石刻诗文，但当时朝中人对此反应索然，并不在意。韩愈之前，杜甫只在《李潮八分小篆歌》中带过一笔，此后韦应物有《石鼓歌》，但缺少热情和文采。及至韩愈以他特有的文学家、史学家的敏感看到石鼓对研究我国古代文学和历史学的重要意义，感慨石鼓文物的废弃，力谏当局保护石鼓而不得采纳，因而大发牢骚，写下长诗《石鼓歌》，从石...", "authors": ["阮森丽"], "pressName": "崇文书局"}, {"bookId": "645d0e35e745e33de3130007", "bookTitle": "韩愈诗文鉴赏辞典", "articleId": "647acef0e49f46528a3fdd86", "shortContent": "《石鼓歌》作于唐宪宗元和六年（811）。石鼓是十块鼓形刻石，初唐时出土于凤翔府天兴县（今陕西凤翔）三畤原，每块刻四言诗一首，书体是大篆。石鼓的年代现在普遍认为是秦始皇以前的秦代，记述了周秦贵族的田猎生活，而在韩愈的时代，学者们广泛认为是周宣王的纪功之作。之前杜甫的《李潮八分小篆歌》、韦应物的《石鼓歌》都对石鼓有过描写，而细致深入地对石鼓进行刻画和赞美的则以韩愈此诗为首。\n诗分三段，第一段叙述了《石...", "authors": ["孔燕妮"], "pressName": "上海辞书出版社"}]', '《邵氏闻见後录》：退之《石鼓诗》体，子美《八分歌》也。
《老学菴笔记》：胡基仲尝言：「韩退之《石鼓诗》云：『羲之俗书趁姿媚。』狂肆甚矣。」予对曰：「此诗至云：『陋儒编诗不收入，二雅褊迫无委蛇。』其言羲之『俗书』，未为可骇也。」基仲为之绝倒。
《环溪诗话》：韩愈之妙，在用叠句。如「黄簾绿幕朱户间」，是一句能叠三物。如「洗妆拭面著冠帔，白咽红颊长眉青」，是两句叠六物。惟其叠多，故事实而语健。又诸诗《石鼓歌》最工，而叠语亦多。如「雨淋日炙野火烧」，「鸾翔凤翥众仙下」，「金绳铁索锁钮壮，古鼎跃水龙腾梭」，韵韵皆叠。每句之中，少者两物，多者三物乃至四物，幾乎是一律。惟其叠语，故句健，是以为好诗也。韩诗无非《雅》也，然则有时乎近《风》。……如题南岳、歌石鼓，调张籍而歌李杜，则《颂》之类也。虽风、颂若不足，而雅正则有馀矣。
《馀师录》：退之诗，惟《虢园二十一咏》为最工，语不过二十字，而意思含蓄过于数千百言者。至为《石鼓歌》，极其致思，凡累数百言，曾不得鼓之仿佛。岂其注意造作，求以过人与？夫不假琢磨，得之自然者，遂有间邪？由是观之，凡人为文，言约而事该，文省而旨远者为佳。
《黄氏日钞》：《石鼓歌》、《双鸟诗》尤怪特。
《辑注唐韩昌黎集》：蒋之翘曰：退之《石鼓歌》颇工于形似之语。韦苏州，苏眉山皆有作，不及也。
《唐诗快》：可谓极力摹写（「快剑斫断」五句下）。诗之珠翠斑驳，正如石鼓。石鼓得此诗而不磨，诗亦并石鼓而不朽矣。
《诗辩坻》：《石鼓歌》全以文法为诗，大乖风雅。唐音云亡，宋响渐逗，斯不能无归狱焉者。陋儒哓哓颂韩诗，亦震于其名耳。
《批韩诗》：朱彝尊曰：作歌起（首二句下）。起四句似杜。退之有此段意思，故尔详述，然亦繁而不厌（「经历久远」句下）。作歌收，叹意不遂（末句下）。大约以苍劲胜，力量自有馀。然气一直下，微嫌乏藻润转折之妙。何焯曰：二句结上生下，有神力（「嗟余好古」二句下）。
《义门读书记》：文章只一句点过，专论字体，得之（「辞严义密」句下）。横插此二句，势不直（「年深岂免」二句下）。此刘彦和所谓「夸饰」。然在此题诗，反成病累（「陋儒编诗」四句下）。元人缘公此诗，乃置石鼓于太学。然公之在唐尝为祭酒，竟不暇自实斯言，何独切责于中朝大官哉（「圣恩若许」句下）。对籀文言之，乃俗书耳。《尘史》之云，愚且妄矣（「羲之俗书」句下）。
《初白菴诗评》：谦退处自占地步（「才薄将奈」句下）。
《带经堂诗话》：《笔墨闲录》云：「退之《石鼓歌》全学子美《李潮八分小篆歌》。」此论非是。杜此歌尚有败笔，韩《石鼓》诗雄奇怪伟，不啻倍蓰过之，岂可谓後人不及前人也！後子瞻作《凤翔八观》诗，中《石鼓》一篇，别与出奇，乃是韩公勍敌。
《载酒园诗话又编》：韩诗至《石鼓歌》而才情纵恣已极。
《唐诗别裁》：「陋儒」指当时采风者，言《二雅》不载，孔子无从采取也，焉有不满孔子意（「陋儒编诗」四句下）？隶书风俗通行，别于古篆，故云「俗书」，无贬右军意（「羲之俗书」二句下）。于今石鼓永留太学，昌黎诗为之先声也。典重和平，与题相称。
《网师园唐诗笺》：纔说到张生所持纸本（「公从何处」句下）。警句（「鸾翔凤翥」二句下）。追叙。见公好古心切（「对此涕泪」句下）。此乃作歌本旨（「安能以此」句下）。
《老生常谈》：人当读李、杜诗後，忽得昌黎《石鼓》等诗读之，如遊深山大泽、奔雷急电後，忽入万间广厦，商彝周鼎，罗列左右，稍稍憩息亍其中，觉耳目心思；又别作宽广名贵之状，迥非人世所有，大快人意。
《诗法简易录》：第二字平，提起通篇之势，声调大振（「周纲陵迟」句下）。
《援鹑堂笔记》：韩昌黎《石鼓歌》，阮亭尝云：「杜《李潮八分歌》，不及韩、苏《石鼓歌》壮伟可喜。」余谓少陵此诗不及二百字，而往复顿挫，一出一入，竟只烟波老境，岂他人所场到！（方东）树按：往时海峰先生言：「东坡《石鼓》诗如不能胜韩，必不作。」今观之，但奇恣使才为佳耳，胜韩，未也，以校杜《八分歌》，则益为冗长。阮亭乃谓杜不及之，岂知言乎？若钱牧斋《西岳华山庙碑诗》，则益为扶墙扪壁，不可耐矣。
《瓯北诗话》：盘空硬语，须有精思结撰，若徒挦摭奇字，诘曲其同，务为不可读，以骇人耳目，此非真警策也。……其实《石鼓歌》等杰作，何尝有一语奥涩，而磊落豪横，自然挫笼万有。又如《喜雪献裴尚书》、《咏月和崔舍人》以及《叉鱼》、《咏雪》等诗，更复措思极细，遣词极工，虽工于试帖者，亦逊其稳丽。此则大才无所不办，并以见诗之工，固在此不在彼也。
《唐宋诗醇》：典重瑰奇，良足铸之金而磨之石。後半旁皇珍惜，更见怀古情深。
《剑溪说诗》：诗与题称乃佳。如《石鼓歌》三篇，韩、苏为合作，韦左司殊未尽致。
《石洲诗话》：渔洋论诗，以格调撑架为主，所以独喜昌黎《石鼓歌》也。《石鼓歌》固卓然大篇，然较之此歌（按指少陵《李潮八分小篆歌》），则杜有停畜抽放，而韩稍直下矣。但谓昌黎《石鼓歌》学杜，则亦不然，韩此篇又自有妙处。苏诗此歌（按指东坡《石鼓歌》）魄力雄大，不让韩公。然至描写止面处，以「古器」、「众星」、「缺月」、「嘉禾」错列于後，以「郁律蚊蛇」、「指肚」、「钳口」浑举于前，尤较韩为斟酌动宕矣。时韩则「快剑斫蛟」一连五句，撑空而出，其气魄横绝万古，固非苏所能及。方信铺张实阽，非易事也。（东坡）《安州老人食蜜歌》结四句云：「因君寄与双龙饼，镜空一照双龙影。三吴六月水如汤，老人心似双龙井。」亦若韩《石鼓歌》起四句句法，此可见起结一樣音节也。然又各有抽放平仄之不同。
《七言诗平仄举隅》：《石鼓歌》：须此「文」字平声撑空而起，所以三句「石」字皆仄（首句下）。此句五六上去互扭，是篇中小作推宕（「字体不类」句下）。此句末字用子声峙起，此是中间顿宕，全以撑拄为能（「孔子西行」句下）。此句乃双层之句，在韩公最为宛转矣。所以下句仅换第五字，亦与篇中诸句之换仄者不同（「牧童敲火」句下）。平声正调，长篇一韵到底之正式（末句下）。
《古诗选批》：「收拾」二字，合上讲解切磋义俱在其中。韩公之愿力，深且切矣。
《声调谱》：拗律句（「辞严义密」句下）。拗律句（「鸾翔凤翥」句下）。律句（「孔子西行」句下）。律句（「忆昔初蒙」句下）。律句少拗（「大厦深檐」句下）。拗律句（「日销月铄」句下）。拗律句（「石鼓之歌」句）。
《岘佣说诗》：《石鼓歌》，退之一副笔墨，东坡一副笔墨，古之名大家，必自具面目如此。
《昭昧詹言》：诗文以瑰怪玮丽为奇，然非粗犷伧俗，客气矜张，饾饤句字，而气骨轻浮者，可貌袭也。……又如韩、苏《石鼓》，自然奇伟，而吴渊颖《观秦承相斯峄山刻石墨本碑》则为有意搜用字料，而伧俗饾饤，气骨轻浮。至钱牧翁《西岳华山碑》，益为无取。东坡《石鼓》，飞动奇纵，有不可一世之概，故自佳，然似有意使才，又贪使事，不及韩气体肃穆沉重。海峰谓苏胜韩，非笃论也。以余较之，坡《石鼓》不如韩，韩《石鼓》又不如杜《李潮八分小篆歌》文法纵横，高古奇妙。要之，此三诗更古今天壤，如华岳三峰矣。至义山《韩碑》，前辈谓足匹韩，愚谓此诗虽句法雄杰，而气窒势平，所以然者，韩深于古文，义山仅以骈俪体作用之，但加梢炼琢造，句法老成已耳。一段来历，一段写字，一段叙初年己事，抵一篇传记。夹叙夹议；容易解，但其字句老炼，不易及耳。
《望雲诗话》：《石洲诗话》谓东坡《石鼓》不如昌黎。愚按：昌黎作于强盛之年，东坡作《石鼓》时，年仅逾冠，何可较景？七古押平韵到底者，单句末一字不宜用平声。若长篇气機与音节拍凑处，偶见一二，尚无妨碍，如杜《冬狩行》「东西南北西裏间」、「况今摄行大将权」，韩《石鼓歌》「孔子西行不到秦」、「忆昔初蒙博士征」之类是也。
《历代诗法》：大开大阖，段落章法井然，是一篇绝妙文字。
《求阙斋读书录》：自「周纲陵迟」以下十二句，叙周宣搜狩镌功勒石。自「火从何处」以下十四句，叙搨本之精、文字之古。自「嗟余好古」以下二十句，议请移鼓于太学。自「中朝大官」至末十六句，慨移鼓之议不遽施行，恐其无人收拾。
《十八家诗钞》：刘、姚渚公皆谓苏《石鼓》胜于昌黎意。苏诚奇恣，然纯以议论行之，尚是少年有意为文之态，气体风骨，未及此诗之雄劲也。
《增评韩苏诗钞》：三溪曰：《石鼓歌》，昌黎集中第一篇杰作，虽有继者，不得出其右，要俾昌黎擅场耳。
《韩诗臆说》：国初以来诸公为七言古者，多模此篇。其实此殊无甚深意，非韩诗之至者，持取其体势宏敞，音韵铿訇耳。
《山泾草堂诗话》：如许长篇，不明章法，妙处殊难领会。全诗应分四段。首段叙石鼓来历，次段写石鼓正面，三段从空中著笔作波澜，四段以感慨结。妙处全在三段凌空议论，无此即嫌平直。古诗章法通古文，观此益信。「快剑斫断生蛟鼍」以下五句，雄浑光怪，句奇语重，镇得住纸，此之谓大手笔。
《唐宋诗举要》：吴（北江）曰：挺接（「少陵无人」句下）。以上虚冒点题（「才薄将奈」句下）。跌下句（「周纲陵迟」句下）。以上叙作鼓源始（「鬼物守护」句下）。以上赞叹纸本（「掎摭星宿」句下）。收句幽咽苍凉不尽。句奇语重，能字字顿挫出筋节，最是此篇胜处。', 'center', 1416840182, '57b9bac8a633bd005d2ef04e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10499, '夜归鹿门歌', NULL, 280, 266, 2, 3, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/414626.htm', '', '山寺钟鸣昼已昏，渔梁渡头争渡喧。
人随沙岸向江村，余亦乘舟归鹿门。
鹿门月照开烟树，忽到庞公栖隐处。
岩扉松径长寂寥，惟有幽人自来去。', '此诗通过描写诗人夜归鹿门山的所见所闻所感，抒发了诗人的隐逸情怀。整首诗按照时空顺序，分别写了江边和山中两个场景，上个场景着眼于钟鸣、争渡、向江村、归鹿门等人物的动态描绘，下个场景侧重于月照、岩扉、松径等静态刻画，先动后静，以动衬静，写出鹿门清幽的景色，表现诗人恬静的心境，同时在清闲脱俗的隐逸情趣中也隐寓着孤寂无奈的情绪。全诗笔法顺畅，语言质朴，情感真挚。', '鹿门：山名，在襄阳。
昼已昏：天色已黄昏。
渔梁：洲名，在湖北襄阳城外汉水中。《水经注·沔水》中记载：「襄阳城东沔水中有渔梁洲，庞德公所居。」
喧：吵闹。
开烟树：指月光下，原先烟雾缭绕下的树木渐渐显现出来。
庞公：庞德公，东汉襄阳人，隐居鹿门山。荆州刺史刘景升请他做官，不久后，携妻登鹿门山采药，一去不回。
岩扉：指山岩相对如门。
幽人：隐居者，诗人自称。', '韵译
黄昏时山寺的钟声回荡山谷，渔梁渡口处一片喧闹的声音。
人们沿着沙岸向江村走过去，我也乘坐一叶小舟返回鹿门。
鹿门的月光使山树显现出来，我忽然来到了庞公隐居之地。
清冷的山岩路寂静的林间道，唯有隐居的人在此飘逸来去。
散译
天色已近黄昏，山寺里的钟声响起，渔梁渡口人们争着过河，喧闹不已。行人沿着沙岸向江村走去，我也乘着小舟返回鹿门山。皎洁的月光照映着鹿门山，山树一片迷朦。忽然，仿佛不知不觉就到了庞公曾隐居的地方，也到了我现在的栖身之地。如门的山岩、松间的小路幽幽静静，只有隐者独自来去，与这美妙的大自然融为一体。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929103048e64fbd912ae", "shortContent": "孟浩然家在襄阳城南郊外，岘山附近，汉江西岸，名曰“南园”或“涧南园”。题中鹿门山则在汉江东岸，沔水南畔与岘山隔江相望，距离不远，乘船前往，数时可达。汉末著名隐士庞德公，因拒绝征辟，携家隐居鹿门山，从此鹿门山就成了隐逸圣地。孟浩然早先一直隐居岘山南园的家里，四十岁赴长安谋仕不遇，游历吴、越数年后返乡，决心追步乡先贤庞德公的行迹，特为在鹿门山辟一住处。偶尔也去住住，其实是个标榜归隐性质的别业，所以题曰...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0f5", "shortContent": "孟浩然家在襄阳城南郊外，岘山附近，汉江西岸，名曰“南园”或“涧南园”。题中鹿门山则在汉江东岸，沔水南畔与岘山隔江相望，距离不远，乘船前往，数时可达。汉末著名隐士庞德公，因拒绝征辟，携家隐居鹿门山，从此鹿门山就成了隐逸圣地。孟浩然早先一直隐居岘山南园的家里，四十岁赴长安谋仕不遇，游历吴、越数年后返乡，决心追步乡先贤庞德公的行迹，特为在鹿门山辟一住处。偶尔也去住住，其实是个标榜归隐性质的别业，所以题曰...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0cd", "shortContent": "孟浩然诗绝大部分为五言短篇，而歌行体则极少见。此诗用古体写山水田园与隐逸，风格一仍其旧，“气象清远，心悰孤寂”，而“出语洒落，洗脱凡近”（《唐音癸签》引徐献忠语），是孟诗中的名篇。\n\n鹿门山在汉江东岸，沔水南畔，与岘山隔江相望。汉末著名隐士庞德公因拒绝征辟，携家人隐居于此，鹿门山因此成了隐逸圣地。孟浩然早先一直隐居岘山南园的家里，四十岁到长安求仕不成，云游江南数年后返乡。世道的冷漠和仕途的艰险，使...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127036c9ebcc6fbea1a38d", "shortContent": "孟浩然的诗以短小绝句有名，而歌行体则少见佳作，此诗是孟氏少数几篇歌行佳作，为后人推赞。此诗取得成功的关键在于融进了自己的人生情思。\n\n题中“鹿门山”在汉江东岸，沔水南畔，与孟浩然的家乡襄阳隔江相望。汉末著名隐士庞德公，因拒绝出仕，携家人隐居于此，鹿门山因此成了隐逸圣地。所以题目就透出隐逸情趣。我们知道，孟浩然四十岁到长安求仕不成，云游江南数年后返乡。世道的冷漠和仕途的艰险，使诗人自然产生隐逸之情。...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127069c305cf0801816fdc", "shortContent": "孟浩然的诗以短小绝句最为有名，而歌行体则少见佳作。此诗是孟氏少数几篇歌行佳作，为后人推赞。诚如《王孟诗评》所说：“此诗为昔人所甚赏，尚非孟胜场，作手自辨。”此诗取得成功的关键在于融进了作者自己的人生情思。\n\n题中“鹿门山”在汉江东岸，沔水南畔，与孟浩然的家乡襄阳隔江相望。汉末著名隐士庞德公，因拒绝出仕，携家人隐居于此，鹿门山因此成了隐逸圣地。所以题目就透出隐逸情趣。我们知道，孟浩然四十岁到长安求仕...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '宋·刘须溪《王孟诗评》：此诗为昔人所甚赏，尚非孟胜场，作手自辨。
明·高漫士《批点唐诗正声》：浩然作《鹿门歌》，其本象清彻闲淡备至。
明·钟退谷《唐诗归》：幽细之调，得此一转有力（「余亦」句）。
明·唐仲言《唐诗解》：此篇不加斧凿，字字超凡。
明·唐仲言《汇编唐诗十集》：浅浅说去，自然不同，此老胸中有泉石。
明·周珽《唐诗选脉会通评林》：清彻，真澄水明霞。陈继儒曰：明月在天，清风徐引，一种高气，凌虚欲下。知此可读孟诗。
清·张揔《唐风怀》：窈然幽绝。
清·刘邦彦《唐诗归折衷》：「幽」之一字，非孟襄阳其谁与？然篇不多见，即此五十六字，亦足当诸家工百言。
清·吴瑞荣《唐诗笺要》：韵事佳题，词不烦而意有馀，更妙在「庞公」不多铺张。
清·张谦宜《茧斋诗谈》：句句下韵，紧调也。脉却舒徐。
清·宋宗元《网师园唐诗笺》：入画（「余亦」句）。
清·张文荪《唐贤清雅集》：幽秀至此，直是诗中精灵。
清·施均甫《岘佣说诗》：孟公边幅太窘，然如《夜归鹿门》一首，精幽绝妙，才力小者，学步此仲，参之李东川派，亦可名家。', 'center', 1416758485, '57b9873ad342d30063991fb3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10500, '庐山谣寄卢侍御虚舟', NULL, 395, 1052, 5, 3, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/162592.htm', '', '我本楚狂人，凤歌笑孔丘。
手持绿玉杖，朝别黄鹤楼。
五岳寻仙不辞远，一生好入名山游。
庐山秀出南斗傍，屏风九叠云锦张，
影落明湖青黛光。
金阙前开二峰长，银河倒挂三石梁。
香炉瀑布遥相望，回崖沓嶂凌苍苍。
翠影红霞映朝日，鸟飞不到吴天长。
登高壮观天地间，大江茫茫去不还。
黄云万里动风色，白波九道流雪山。
好为庐山谣，兴因庐山发。
闲窥石镜清我心，谢公行处苍苔没。
早服还丹无世情，琴心三叠道初成。
遥见仙人彩云里，手把芙蓉朝玉京。
先期汗漫九垓上，愿接卢敖游太清。', '这首诗作于唐肃宗上元元年（公元760年），即诗人流放夜郎途中遇赦回来的次年。李白遇赦后从江夏（今湖北武昌）往浔阳（今江西九江）重游庐山时，作此诗寄卢虚舟。当时李白已经历尽磨难，始终不愿向折磨他的现实低头，求仙学道的心情更加迫切。
此诗先写作者之行踪，次写庐山之景色，末写隐退幽居之愿想；不仅浓墨重彩地描绘了庐山秀丽雄奇的景色，更主要的是表现了诗人狂放不羁的性格以及政治理想破灭后想要寄情山水的心境，流露了诗人一方面想摆脱世俗的羁绊，进入飘渺虚幻的仙境，一方面又留恋现实，热爱人间的美好风物的矛盾复杂的内心世界。全诗风格豪放飘逸，境界雄奇瑰玮，笔势错综变化，诗韵亦随着诗人情感的变化几次转换，跌宕多姿，极尽抑扬顿挫之美，富于浪漫主义色彩。', '谣：不合乐的歌，一种诗体。
卢侍御虚舟：卢虚舟，字幼真，范阳（今北京大兴县）人，唐肃宗时曾任殿中侍御史，相传“操持有清廉之誉”（见清王琦注引李华《三贤论》），曾与李白同游庐山。
楚狂人：春秋时楚人陆通，字接舆，因不满楚昭王的政治，佯狂不仕，时人谓之“楚狂”。
凤歌笑孔丘：孔子适楚，陆通游其门而歌：“凤兮凤兮，何德之衰……”劝孔不要做官，以免惹祸。这里，李白以陆通自比，表现对政治的不满，而要像楚狂那样游览名山过隐居的生活。
绿玉杖：镶有绿玉的杖，传为仙人所用。
五岳：即东岳泰山，西岳华山，南岳衡山，北岳恒山，中岳嵩山。此处泛指中国名山。
南斗：星宿名，二十八宿中的斗宿。古天文学家认为浔阳属南斗分野（古时以地上某些地区与天某些星宿相应叫分野）。这里指秀丽的庐山之高，突兀而出。
屏风九叠：指庐山五老峰东的九叠屏，因山九叠如屏而得名。
“影落明湖青黛（dài）光”句：指庐山倒映在明澈的鄱阳湖中。青黛，青黑色。
金阙（què）：阙为皇宫门外的左右望楼，金阙指黄金的门楼。这里借指庐山的石门——庐山西南有铁船峰和天池山，二山对峙，形如石门。
银河：指瀑布。
三石梁：一说在五老峰西，一说在简寂观侧，一说在开先寺（秀峰寺）旁，一说在紫霄峰上。近有人考证，五老峰西之说不谬。
香炉：南香炉峰。瀑布：黄岩瀑布。
回崖沓（tà）嶂：曲折的山崖，重叠的山峰。
凌：高出。
苍苍：青色的天空。
“鸟飞不到吴天长”句：连鸟也难以飞越高峻的庐山和它辽阔的天空。吴天，九江春秋时属吴国。
大江：长江。
黄云：昏暗的云色。
白波九道：九道河流。古谓长江流至浔阳分为九条支流。李白在此沿用旧说，并非实见九道河流。
雪山：白色的浪花。形容白波汹涌，堆叠如山。
石镜：古代关于石镜有多种说法，诗中的石镜应指庐山东面的“石镜”。传说在庐山东面有一圆石悬岩，平滑如镜，可照人影。
清我心：清涤心中的污浊。
谢公：南朝宋谢灵运。谢灵运曾进彭蠡湖口，登庐山，有“攀崖照石镜”诗句（《谢康乐集·入彭蠡湖口》）。
服：服食。
还丹：道家炼丹，将丹烧成水银，积久又还成丹，故谓“还丹”。
琴心三叠：道家修炼术语，一种心神宁静的境界。
玉京：传说元始天尊居处。道教称元始天尊在天中心之上，名玉京山。
先期：预先约好。
汗漫：无边无际，意谓不可知，这里比喻神仙。一说为造物者。
九垓（gāi）：九天之外。
卢敖：战国时燕国人。《淮南子·道应训》载，卢敖游北海，遇见一怪仙迎风而舞，想同他做朋友而同游，怪仙笑道：“吾与汗漫期于九垓之外，吾不可以久驻。”遂纵身跳入云中。
太清：最高的天空。', '我本是像那个接舆楚狂人，高声唱着凤歌去嘲笑孔丘。
手里拿一根镶绿玉的棍杖，大清早辞别著名的黄鹤楼。
攀登五岳寻仙道不畏路远，这一生就喜欢踏上名山游。
秀美的庐山挺拔在南斗旁，九叠云屏像锦绣云霞铺张，
湖光山影相互映照泛青光。
金阙岩前双峰矗立入云端，三叠泉如银河倒挂三石梁。
香炉峰瀑布与它遥遥相望，重崖叠嶂耸云霄莽莽苍苍。
翠云红霞与朝阳相互辉映，鸟儿也飞不过吴天广又长。
登高远望天地间壮观景象，大江悠悠东流去永不回还。
天上万里黄云变动着风色，江流波涛九道如雪山奔淌。
我喜欢为雄伟的庐山歌唱，这兴致因庐山风光而滋长。
闲时观看石镜使心神清净，谢灵运足迹早被青苔掩藏。
我要早服仙丹去掉尘世情，琴心三叠的境界就能初成。
远远望见仙人正在彩云里，手里捧着芙蓉花朝拜玉京。
早已约好神仙在九天会面，希望迎接你一同邀游太清。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929edbb8b379ee09599c", "shortContent": "李白流放夜郎途中遇赦后，于上元元年（760）从江夏（今湖北武汉）往浔阳（今江西九江）游庐山时作了这首诗。卢虚舟，字幼真，范阳（今北京大兴县）人，肃宗时任殿中侍御史，相传“操持有清廉之誉”（见清王琦注引李华《三贤论》），曾与李白同游庐山。\n“我本楚狂人，凤歌笑孔丘。”起句即用典，开宗明义表达胸襟：我本来就像楚狂接舆，高唱凤歌嘲笑孔丘。孔子曾去楚国，游说楚王。接舆在他车旁唱道：“凤兮凤兮，何德之衰？往...", "authors": ["何国治"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac821a74606fc4093f", "shortContent": "李白流放夜郎途中遇赦后，于上元元年（760）从江夏（今湖北武汉）往浔阳（今江西九江）游庐山时作了这首诗。卢虚舟，字幼真，范阳（今北京大兴区）人，肃宗时任殿中侍御史，相传“操持有清廉之誉”（见清王琦注引李华《三贤论》），曾与李白同游庐山。\n\n“我本楚狂人，凤歌笑孔丘。”起句即用典，开宗明义表达胸襟：我本来就像楚狂接舆，高唱凤歌嘲笑孔丘。孔子曾去楚国，游说楚王。接舆在他车旁唱道：“凤兮凤兮，何德之衰？...", "authors": ["何国治"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0ce", "shortContent": "此诗作于肃宗上元元年（760），即李白被流放夜郎而中途遇赦的次年。遇赦后，李白从江夏往浔阳（今江西九江），重游庐山而作此诗。此时，李白仕途遭挫，而年已六十，寄情山水之余，求仙学道的心思更切，故“笔下殊有仙气”（沈德潜《唐诗别裁集》卷六）。卢侍御，即殿中侍御史卢虚舟（字幼直），他也爱好青山绿水，李白在《和卢侍御通塘曲》诗中说：“君夸通塘好，通塘胜耶溪。”\n\n首六句为第一部分，是序曲。诗人说他本来就像...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127052c305cf0801816f5b", "shortContent": "此诗作于上元元年（760），当时李白在浔阳。卢侍御，即殿中侍御史卢虚舟（字幼真），他也爱好青山绿水，李白在《和卢侍御通塘曲》中说：“君夸通塘好，通塘胜耶溪。”这首诗“先写庐山形胜，后言寻幽不如学仙，与卢敖同游太清，此素愿也”（沈德潜《重订唐诗别裁集》卷六）。\n\n诗人说他本来就像楚国狂人接舆，有隐居的夙愿。当年孔子去游说楚王，接舆在车旁唱歌嘲笑：“凤兮凤兮，何德之衰？往者不可谏，来者犹可追！已而！已...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "64670131b6a81d0c53fd074e", "shortContent": "李白流放夜郎途中遇赦后，于上元元年（760）从江夏（今湖北武汉）往浔阳（今江西九江）游庐山时作了这首诗。卢虚舟，字幼真，范阳（今北京大兴县）人，肃宗时任殿中侍御史，相传“操持有清廉之誉”（见清王琦注引李华《三贤论》），曾与李白同游庐山。\n\n“我本楚狂人，凤歌笑孔丘。”起句即用典，开宗明义表达胸襟：我本来就像楚狂接舆，高唱凤歌嘲笑孔丘。孔子曾去楚国，游说楚王。接舆在他车旁唱道：“凤兮凤兮，何德之衰？...", "authors": ["何国治"], "pressName": "上海辞书出版社"}]', '《批点唐诗正声》：方外玄语，不拘流例。全篇开阖佚荡，冠绝古今，即使杜工部为之，未易及此，高、岑辈恐亦胁息。又襟期雄旷，辞旨慨慷，音节浏亮，无一不可。结句非素胎仙骨，必无此诗。
《李杜诗选》：刘须溪曰：为此桀态。
《李诗辨疑》：辞有纯驳，强弱不一，为可疑也。
《唐诗快》：伯敬云：读李白诗，当于雄快中察其静远精出处。又云：太白有饮酒、学仙两路语，资浅俗人口角，言俱不谬。若如此等诗、则有雄快而无浅俗矣。
《唐诗别裁》：先写庐山形胜，后言寻幽不如学仙，与卢敖同游太清，此素愿也。笔下殊有仙气。
《唐宋诗醇》：天马行空，不可羁绁。
《昭昧詹言》：“庐山”以下正赋。“早服”数句应起处，而提笔另起，是以不平。章法一线乃为通，非乱杂无章不通之比。
《王闿运手批唐诗选》：此就山中典故铺叙，非游山之景（“庐山秀出”句下）。
《唐宋诗举要》：吴曰：壮阔称题。', 'center', 1416758763, '57b31811128fe10055d375cd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10501, '金陵酒肆留别', NULL, 469, 1052, 2, 2, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155344.htm', '', '风吹柳花满店香，吴姬压酒唤客尝。
金陵子弟来相送，欲行不行各尽觞。
请君试问东流水，别意与之谁短长。', '此诗是唐代伟大诗人李白即将离开金陵东游扬州时留赠友人的一首话别诗，篇幅虽短，却情意深长。此诗由写仲夏胜景引出逸香之酒店，铺就其乐融融的赠别场景；随即写吴姬以酒酬客，表现吴地人民的豪爽好客；最后在觥筹交错中，主客相辞的动人场景跃然纸上，别意长于流水般的感叹水到渠成。全诗热情洋溢，反映了李白与金陵友人的深厚友谊及其豪放性格；流畅明快，自然天成，清新俊逸，情韵悠长，尤其结尾两句，兼用拟人、比喻、对比、反问等手法，构思新颖奇特，有强烈的感染力。', '金陵：今江苏省南京市。
酒肆：酒店。
留别：临别留诗给送行者。
风吹：一作「白门」。
吴姬：吴地的青年女子，这里指酒店中的侍女。
压酒：压糟取酒。古时新酒酿熟，临饮时方压糟取用。
唤：一作「劝」，一作「使」。
子弟：指李白的朋友。
欲行：将要走的人，指诗人自己。
不行：不走的人，即送行的人，指金陵子弟。
尽觞（shāng）：喝尽杯中的酒。觞，酒杯。
试问：一作「问取」。', '春风吹拂柳絮满店飘酒香，吴姬捧出美酒请客人品尝。
金陵的朋友们纷纷来相送，主客畅饮频频举杯共尽觞。
请你们问问这东流的江水，离情别意与它比谁短谁长？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929e911759740c9b1a3c", "shortContent": "杨花飘絮的时节，江南水村山郭的一家小酒店里，即将离开金陵的诗人，满怀别绪，独坐小酌。骀荡的春风，卷起了垂垂欲下的杨花，轻飞乱舞，扑满店中；当垆的姑娘，捧出新压榨出来的美酒，劝客品尝。这里，柳絮濛濛，酒香郁郁，扑鼻而来，也不知是酒香，还是柳花香。这么一幅令人陶醉的春光春色的画面，该用多少笔墨来表现！只“风吹柳花满店香”七字，就将风光的骀荡，柳絮的精神，以及酒客沉醉东风的情调，生动自然地浮现在纸面之上...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac821a74606fc40941", "shortContent": "杨花飘絮的时节，江南水村山郭的一家小酒店里，即将离开金陵的诗人，满怀别绪，独坐小酌。骀荡的春风，卷起了垂垂欲下的杨花，轻飞乱舞，扑满店中；当垆的姑娘，捧出新压榨出来的美酒，劝客品尝。这里，柳絮蒙蒙，酒香郁郁，扑鼻而来，也不知是酒香，还是柳花香。这么一幅令人陶醉的春光春色的画面，该用多少笔墨来表现！只“风吹柳花满店香”七字，就将风光的骀荡，柳絮的精神，以及酒客沉醉东风的情调，生动自然地浮现在纸面之上...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0d0", "shortContent": "此诗作于开元十四年（726）的春天，李白出蜀离川已经两年了。两年中，大半年的时间是金陵度过的。在这里，他饱览江南风光，结交了许多朋友。暮春时节，惬意的日子终于结束了，他要继续自己的旅程，离开金陵，前往扬州。临行之际，朋友们依依不舍，齐聚在江滨一家小酒店里为他送行，诗人写下了这首诗。“此咏金陵留别而言其情之长也。风吹柳花，飘落于满店香者，如人之无定也。吴姬压酝美酒以劝客尝，盖为祖饯之意耳。金陵子弟来...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127052c305cf0801816f5d", "shortContent": "这是开元十四年（726）的春天，李白出蜀离川已经两年了。两年中，大半年的时间是在金陵度过的。在这里，他饱览了江南风光，结交了许多朋友。暮春时节，惬意的日子终于结束了，他要继续自己的旅程，离开金陵，前往扬州。临行之际，朋友们依依不舍，齐聚在江滨一家小酒店里为他送行，诗人写下了这首诗。“此咏金陵留别而言其情之长也。风吹柳花，飘落于满店香者，如人之无定也。吴姬压酝美酒以劝客尝，盖为祖饯之意耳。金陵子弟来...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270a5e6f69b71e93f632a", "shortContent": "这是开元十四年（726）的春天，李白出蜀离川已经两年了。两年中，大半年的时间是在金陵度过的。在这里，他饱览了江南风光，结交了许多朋友。暮春时节，惬意的日子终于结束了，他要继续自己的旅程，离开金陵，前往扬州。临行之际，朋友们依依不舍，齐聚在江滨一家小酒店里为他送行，诗人写下了这首诗。“此咏金陵留别而言其情之长也。风吹柳花，飘落于满店香者，如人之无定也。吴姬压酝美酒以劝客尝，盖为祖饯之意耳。金陵子弟来...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "646702377f27182da35db786", "shortContent": "杨花飘絮的时节，江南水村山郭的一家小酒店里，即将离开金陵的诗人，满怀别绪，独坐小酌。骀荡的春风，卷起了垂垂欲下的杨花，轻飞乱舞，扑满店中；当垆的姑娘，捧出新压榨出来的美酒，劝客品尝。这里，柳絮濛濛，酒香郁郁，扑鼻而来，也不知是酒香，还是柳花香。这么一幅令人陶醉的春光春色的画面，该用多少笔墨来表现！只“风吹柳花满店香”七字，就将风光的骀荡，柳絮的精神，以及酒客沉醉东风的情调，生动自然地浮现在纸面之上...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}]', '《苕溪渔隐丛话》：《诗眼》云：好句须要好字。如李太白诗「吴姬压酒唤客尝」，见新酒初熟，江南风物之美，工在「压」字。
《云麓漫钞·卷十》：李太白诗「吴姬压酒唤客尝」，说者以为工在「压」字上，殊不知乃吴人方言耳。至今酒家有旋压酒子相待之语。
《诗人玉屑》：山谷言：学者不见古人用意处，似得其皮毛，所以去之更远。如「风吹柳花满店香」，若人复能为此句，亦未是太白。至于「吴姬压酒唤客尝」，「压酒」二字他人亦难及。「金陵子弟来相送，欲行不行各尽觞」，益不同。「请君试问东流水，别意与之谁短长」，至此乃真太白妙处，当潜心焉。
《唐诗品汇》：刘须溪云：终是太白语别（末二句下）。
《升庵诗话》：李太白诗：「风吹柳花满店香。」温庭筠《咏柳》诗：「香随静婉歌尘起，影伴娇娆舞袖垂。」传奇诗：「莫唱踏春阳，令人离肠结。郎行久不归，柳自飘香雪。」其实柳花亦有微香，诗人之言非诬也。柳花之香，非太白不能道；竹之香，非子美不能道。
《四溟诗话》：太白《金陵留别》诗「请君试问东流水，别意与之谁短长」，妙在结语。使坐客同赋，谁更擅场？谢宣城《夜发新林》诗：「大江流日夜，客心悲未央。」阴常侍《晓发金陵》诗：「大江一浩荡，悲离足几重。」二语突然而起，造语雄深，六朝亦不多见。太白能变化为法，令人叵测，奇哉！诗有简而妙者，若刘桢「仰视白日光，皎皎高且悬」，不如傅玄「日月光太清」。亦有简而弗佳者，若……刘禹锡「欲问江深浅，应如远别情」，不如太白「请君试问东流水，别意与之谁短长」。
《李杜二家诗钞评林》：不浅不深，自是锺情之语。
《唐诗归》：锺云：不须多，亦不须深，写得情出。
《唐诗评选》：供奉一味本色，诗则如此，在歌行诚为大家。
《唐诗别裁》：语不必深，写情已足。
《唐诗归折衷》：唐云：将「桃花潭水」参看，知诗中变化法（「别意与之」句下）。吴敬夫云：豪爽之语最易一往而竭，兹何含蓄不尽也！凡意致深沉者，当看其斩载处，不然则胶矣；词气疏快者，当看其蕴籍处，不然则粗矣。
《古唐诗合解》：此篇短调念节，情景各胜。
《唐宋诗醇》：言有尽而意无穷，味在酸咸之外。
《网师园唐诗笺》：深情婉转（末二句下）。
《唐诗合选详解》：吴绥眉曰：短章天然入妙。
《王闿运手批唐诗选》：无情有情（「欲行不行」句下）。
《李太白诗醇》：严云：首句既飘然不群，柳花说香更精微。又云：「欲行不行」四字内，不独情深，已藏「短长」意。', 'center', 1416758869, '57b914247db2a20054273eef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10502, '走马川行奉送封大夫出师西征', NULL, 281, 405, 4, 9, '岑参', NULL, 10096, '57b97daec4c971005593ac34', '唐', 'shi', '诗', 'http://baike.baidu.com/item/走马川行奉送封大夫出师西征', '', '君不见走马川行雪海边，平沙莽莽黄入天。
轮台九月风夜吼，一川碎石大如斗，随风满地石乱走。
匈奴草黄马正肥，金山西见烟尘飞，汉家大将西出师。
将军金甲夜不脱，半夜军行戈相拨，风头如刀面如割。
马毛带雪汗气蒸，五花连钱旋作冰，幕中草檄砚水凝。
虏骑闻之应胆慑，料知短兵不敢接，车师西门伫献捷。', '此诗作于唐玄宗天宝十三载（西元七五四年）或天宝十四载（西元七五五年），当时岑嘉州担任安西北庭节度使判官。这期间，封常清曾几次出兵作战。岑嘉州对当时征战的艰苦、胜利的欢乐，都有比较深的体会，曾经写了不少诗歌来反映。这是岑嘉州封常清出兵西征而创作的送行诗，与《轮台歌奉送封大夫出师西征》係同一时期、为同一事件、馈赠同一对象之作。
此诗抓住有边地特征的景物来状写环境的艰险，从而衬托士卒们大无畏的英雄气概。开头极力渲染环境恶劣、风沙遮天蔽日；接着写匈奴藉草黄马壮之机入侵，而封将军不畏天寒地冻、严阵以待；最后写敌军闻风丧胆，预祝唐军凯旋。诗虽叙征战，却以叙寒冷为主，暗示冒雪征战之伟功。语句豪爽，如风发泉涌，真实动人。全诗句句用韵，三句一转，节奏急切有力，激越豪壮，别具一格。', '走马川：即车尔成河，又名左未河，在今新疆境内。
行：诗歌的一种体裁。
封大夫：即封常清，唐朝将领，蒲州猗氏人，以军功擢安西副大都护、安西四镇节度副大使、知节度事，後又陞任北庭都护，持节安西节度使。
西征：一般认为是出征播仙。
走马川行雪海边：一作「走马沧海边」。
雪海：在天山主峰与伊塞克湖之间。
轮台：地名，在今新疆米泉境内。
匈奴：泛指西域游牧民族。
金山：指今新疆乌鲁木齐东面的博格多山。
汉家：唐代诗人多以汉代唐。
戈相拨：兵器互相撞击。
五花连钱：五花，连钱指马斑驳的毛色。
草檄（xí）：起草讨伐敌军的文告。
短兵：指刀剑一类武器。
车师：为唐北庭都护府治所庭州，今新疆乌鲁木齐东北。蘅塘退士本作「军师」。
伫：久立，此处作等待解。
献捷：献上贺捷诗章。', '您难道不曾看见吗？那辽阔的走马川紧靠着雪海边缘，茫茫无边的黄沙连接云天。
轮台九月整夜里狂风怒号，走马川的碎石块块大如斗，狂风吹得斗大乱石满地走。
这时匈奴牧草繁茂军马肥，侵入金山西面烟尘滚滚飞，汉家的大将率兵开始征西。
将军身著铠甲夜里也不脱，半夜行军戈矛彼此相碰撞，凛冽寒风吹到脸上如刀割。
马毛挂着雪花还汗气蒸腾，五花马的身上转眼结成冰，营幕中写檄文砚墨也冻凝。
敌军听到大军出征应胆惊，料他不敢与我们短兵相接，我就在车师西门等待报捷。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b12cee9a0c24ecf8e8", "shortContent": "岑参诗的特点是意奇语奇，尤其是边塞之作，奇气益著。《白雪歌送武判官归京》是奇而婉，侧重在表现边塞绮丽瑰异的风光，给人以清新俊逸之感；这首诗则是奇而壮，风沙的猛烈，人物的豪迈，都给人以雄浑壮美之感。诗人在任安西北庭节度判官时，封常清出兵去征播仙，他便写了这首诗为封送行。\n为了表现边防将士高昂的爱国精神，诗人用了反衬手法，极力渲染、夸张环境的恶劣，来突出人物不畏艰险的精神。\n首先围绕“风”字落笔，描写...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac26845f3e157ce31c", "shortContent": "岑参诗的特点是意奇语奇，尤其是边塞之作，奇气益著。《白雪歌送武判官归京》是奇而婉，侧重在表现边塞绮丽瑰异的风光，给人以清新俊逸之感；这首诗则是奇而壮，风沙的猛烈，人物的豪迈，都给人以雄浑壮美之感。诗人在任安西北庭节度判官时，封常清出兵去征播仙，他便写了这首诗为封送行。\n\n为了表现边防将士高昂的爱国精神，诗人用了反衬手法，极力渲染、夸张环境的恶劣，来突出人物不畏艰险的精神。\n\n首先围绕“风”字落笔，...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0d2", "shortContent": "岑参的边塞诗以奇情壮采取胜，此诗则较成功地体现了这一特征。作此诗时，作者在安西节度使封常清幕中。封奉命西征，岑写此诗送行。有学者经过一番考证，认为诗中所涉地名，实不可一一确指。诗人或许是以尺幅千里之笔，随意撷取西北边庭之地理风物以成诗境。我们读诗，特别是读岑参奇情异彩的边塞诗作，未尝不可作如是观。\n\n诗人首先向我们展示了边庭环境的严酷。在写作中，作者只注目于一“风”字，但读者却由此可飞腾想象，让无...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127068f2af4e09d55b6779", "shortContent": "岑参的边塞诗以奇情壮采取胜，此诗则较成功地体现了这一特征。作此诗时，作者在安西节度使封常清幕中。封奉命西征，岑写此诗送行。有学者经过一番考证，认为诗中所涉地名，实不可一一确指。诗人或许是以尺幅千里之笔，随意撷取西北边庭之地理风物以成诗境。我们读诗，特别是读岑参奇情异彩的边塞诗作，未尝不可作如是观。\n\n诗人首先向我们展示了边庭环境的严酷。在写作中，作者只注目于一个“风”字，但读者却可飞腾想象，让无数...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270e0f2af4e09d55b6801", "shortContent": "岑参的边塞诗以奇情壮采取胜，此诗则较成功地体现了这一特征。作此诗时，作者在安西节度使封常清幕中。封奉命西征，岑写此诗送行。有学者经过一番考证，认为诗中所涉地名，实不可一一确指。诗人或许是以尺幅千里之笔，随意撷取西北边庭之地理风物以成诗境。我们读诗，特别是读岑参奇情异彩的边塞诗作，未尝不可作如是观。\n\n诗人首先向我们展示了边庭环境的严酷。在写作中，作者只注目于一个“风”字，但读者却可飞腾想象，让无数...", "authors": ["刘琴"], "pressName": "崇文书局"}]', '《唐贤三昧集笺注》：第一解二句，余皆三句一解，格法甚奇。「大如斗」者尚谓之「碎石」，是极写风势，此见用字之诀。奇句，亦是用字之妙（「马毛带雪」二句下）。其精悍处似独辟一面目，杜亦未有此。老杜《饮中八仙歌》中，多甲三句一解而不换韵，此首六解换韵，平仄互用，别自一奇格也。
《唐诗别裁》：势险节短。句句用韵，三句一转、此《峄山碑》文法也，《唐中兴颂》亦然。
《网师园唐诗笺》：奇景以奇结状出（「一川碎石」句下）。险绝怕绝，中夜读之，毛发竖起。逐句用韵，每三句一转，促节危弦，无诘屈赘牙之病，嘉州之所以颉颃李、杜，而超出于樊宗师、卢仝辈也。
《唐贤清雅集》：纔作起笔，忽然陡插「风吼」、「石走」三句，最奇。下略平叙舒其气，复用「马毛带雪」三句，跌荡一番。急以促节收住，微见颂扬，神完气固。谋篇之妙，与《白雪歌》同工异曲，三句一转都用韵，是一格。
《昭昧詹言》：奇才奇气，风发泉涌。「平沙」句，奇句。', 'indent', 1416759022, '57b906ae8ac2470062dfc41f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10503, '轮台歌奉送封大夫出师西征', NULL, 110, 405, 2, 3, '岑参', NULL, 10096, '57b97daec4c971005593ac34', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383137.htm', '', '轮台城头夜吹角，轮台城北旄头落。
羽书昨夜过渠黎，单于已在金山西。
戍楼西望烟尘黑，汉兵屯在轮台北。
上将拥旄西出征，平明吹笛大军行。
四边伐鼓雪海涌，三军大呼阴山动。
虏塞兵气连云屯，战场白骨缠草根。
剑河风急雪片阔，沙口石冻马蹄脱。
亚相勤王甘苦辛，誓将报主静边尘。
古来青史谁不见，今见功名胜古人。', '此诗是唐代诗人岑参送别封常清西征之作，是写边地战争的诗歌。诗中直写军情战事，写战局之凶险与气候之严酷，反衬出唐军誓师出征之声威与高昂士气，表现出全军将士坚韧不拔、雄视一切的豪迈气概。起首六句先写战前两军对垒的紧张状态；紧接四句写白昼出师接仗；然后写奇寒与牺牲，讴歌将士抗敌奋不顾身；末四句照应题目，预祝凯旋，以颂扬作结。全诗有描写，有烘托，有想象，有夸张，手法多样，结构严谨，抑扬顿挫，情调激昂，充满浪漫主义激情和边塞生活的气息，生动地反映了盛唐时期蓬勃向上的时代精神。', '封大夫：即封常清，唐朝将领，蒲州猗氏人，以军功擢安西副大都护、安西四镇节度副大使、知节度事，后又升任北庭都护，持节安西节度使。西征：此次西征事迹未见史书记载。
角：军中乐器，吹奏以报时，类似今日的军号。
旄（máo）头：星名，二十八宿中的昴星。古人认为它主载胡人兴衰。旄头落：为胡人失败之兆。
羽书：即羽檄，军中的紧急文书，上插羽毛，以表示加急。
渠黎：汉代西域国名，在今新疆轮台东南。
单（chán）于：汉代匈奴君长的称号，此指西域游牧民族首领。
金山：指乌鲁木齐东面的博格多山，一说指阿尔泰山。
戍楼：军队驻防的城楼。
汉兵：一作“汉军”。
上将：即大将，指封常清。
旄：节旄，军权之象征。古代出征的大将或出使的使臣，都以节旄用以标明身份的信物，为君王所赐。节旄用金属或竹子做成，而以牦牛尾装饰在端部，称旄。
平明：一作“小胡”。
伐鼓：一作“戍鼓”。
雪海：西域湖泊名，在天山主峰与伊塞克湖之间。
三军：泛指全军。
阴山：在今内蒙古自治区中部。
虏塞：敌国的军事要塞。
兵气：战斗的气氛。
剑河：地名，在今新疆境内。一说即今俄罗斯境内的叶尼赛河上游。
雪片：一作“云片”。
沙口：一作“河口”，地理位置待考。或指剑河河口。
亚相：指御史大夫封常清。在汉代御史大夫位置仅次于宰相，故称亚相。
勤王：勤劳王事，为国效力。
静边尘：犹言平定边患。
青史：史籍。古代以竹简记事，色泽作青色，故称青史。', '轮台城头夜里吹起号角，轮台城北旄头星正降落。
军书昨夜连夜送过渠黎，单于已在金山以西入侵。
从哨楼向西望烟尘滚滚，汉军就屯扎在轮台北境。
上将手持符节率兵西征，黎明笛声响起大军起程。
战鼓四起犹如雪海浪涌，三军呐喊阴山发出共鸣。
敌营阴沉杀气直冲云霄，战场上白骨还缠着草根。
剑河寒风猛烈大雪鹅毛，沙口石头寒冷马蹄冻脱。
亚相勤于王政甘冒辛苦，立誓报效国家平定边境。
古来青垂史名屡见不鲜，如今将军功名胜过古人。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b1d635634aee3ded4b", "shortContent": "这首七古与《走马川行》系同一时期、为同一事、赠同一人之作。但《走马川行》未写战斗，而是通过将士顶风冒雪的夜行军情景烘托必胜之势；此诗则直写战阵之事，具体手法与前诗也有所不同。此诗可分四层。\n起首六句写战斗以前两军对垒的紧张状态。虽是制造气氛，却与《走马川行》从自然环境落笔不同。那里是飞沙走石，暗示将有一场激战；而这里却直接从战阵入手：军府驻地的城头，角声划破夜空，呈现出一种异样的沉寂，暗示部队已进...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0d3", "shortContent": "岑参是盛唐诗人中最擅长描写边塞的诗人。他的诗歌，雄壮豪迈，善于运用边疆特有的地名、景物来创造出中原读者所不熟悉的画面和意境，从而获得审美认知的效果。\n本诗作于轮台，在唐代属安西都护府。封常清的此次西征，不知是哪一次战争，现已失考。起句便用肃穆的诗句勾勒出了警拔庄重的画面：轮台的城头吹起了凄厉的军角之声，轮台城北的夜空中，旄头星从长空中坠落。因为旄头星代表着胡人，所以，它的坠落，预示着胡人将在这场战...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472a52ab6a81d0c532d0b03", "shortContent": "这首七古是诗人在任安西北庭节度判官时，封常清出兵去征播仙，他便写了两首诗为封送行。这是其中的一首。此诗直写战阵之事，可分四层。\n\n起首六句写战斗以前两军对垒的紧张状态。这里直接从战阵入手：军府驻地的城头，角声划破夜空，呈现出一种异样的沉寂，暗示部队已进入紧张的备战状态。古人认为旄头跳跃主胡兵大起，而“旄头落”则主胡兵覆灭。“轮台城头夜吹角，轮台城北旄头落”，连用“轮台城”三字开头，造成连贯的语势，...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '周珽《唐诗选脉会通评林》：起伏结构，语语壮健。
吴煊、胡棠《唐贤三昧集笺注》：何减少陵！二句一解，平仄互用，末一解四句作收结，格法森严。
李锳《诗法易简录》：此诗前十四句，句句用韵，两韵一换，节拍甚紧，后一韵衍作四句，以舒其气，声调悠扬有余音矣。
张文荪《唐贤清雅集》：送大将出师，岂宜妄作感慨？如此闲闲着笔，既有情致，又不犯口，音节亦自然，读古人诗须识其苦心，学其妙法，向有长进处。
施补华《岘佣说诗》：《轮台歌》：“四边伐鼓雪海浦，三军大呼阴山动。”《走马川行》轮台九月风怒吼，一川碎石大如斗，随风满地石乱走”、“半夜军行戈相拨，风头如刀面如割”等句，兵法所谓其节短、其势险也。
高步瀛《唐宋诗举要》：吴曰：起首特为警湛。沈曰：起法磊磊落落，送别之作，应以嘉州为则。', 'center', 1416821526, '57b92bd77db2a20054280dbb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10504, '韦讽录事宅观曹将军画马图', NULL, 67, 1416, 2, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383155.htm', '', '国初已来画鞍马，神妙独数江都王。
将军得名三十载，人间又见真乘黄。
曾貌先帝照夜白，龙池十日飞霹雳。
内府殷红玛瑙盘，婕妤传诏才人索。
盘赐将军拜舞归，轻纨细绮相追飞。
贵戚权门得笔迹，始觉屏障生光辉。
昔日太宗拳毛騧，近时郭家狮子花。
今之新图有二马，复令识者久叹嗟。
此皆骑战一敌万，缟素漠漠开风沙。
其馀七匹亦殊绝，迥若寒空动烟雪。
霜蹄蹴踏长揪间，马官厮养森成列。
可怜九马争神骏，顾视清高气深稳。
借问苦心爱者谁，后有韦讽前支遁。
忆昔巡幸新丰宫，翠华拂天来向东。
腾骧磊落三万匹，皆与此图筋骨同。
自从献宝朝河宗，无复射蛟江水中。
君不见金粟堆前松柏里，
龙媒去尽鸟呼风。', '此诗从画马说到画家的受宠幸，从画马说到真马，从真马说到时事，从玄宗的巡幸说到升遐，诗思不断拓展，寄托了诗人对玄宗的深情眷念。诗人经历了玄宗、肃宗、代宗三朝，自有人世沧桑，浮生若梦之感。因而在诗中明以写马，暗以写人。写马重在筋骨气概，写人寄托情感抱负。赞九马图之妙，生今昔之感，字里行间流露作者对先帝忠诚之意。', '将军：因为曹霸官至左武卫将军，故以「将军」代曹霸以显尊敬。
三：一作「四」。
乘黄：马名，其状如狐，背上有两角，出《山海经》，此诗特借以形容马的神奇骏健。
貌：描画。
先帝：指唐玄宗。
照夜白：马名。玄宗坐骑。
龙池：在唐宫内。
缟素：画绢。
支遁：东晋名僧，字道林，本姓关。养马数匹，有人说道人养马不清高，答：「贫道爱其神骏。」此处比喻韦讽极爱曹霸的画马。
「自从献宝朝河宗」：此句意指玄帝已经去世。
翠华：皇帝仪仗中用翠鸟羽毛作装饰的旗帜。
金粟堆：玄宗的陵墓，在今陕西省蒲城县东。', '开国以来善画鞍马的画家中，画技最精妙传神只数江都王。
曹将军画马出名已有三十载，人间又见古代真正神马“乘黄”。
他曾描绘玄宗先帝的“照夜白”，画得像池龙腾飞十日声如雷。
皇宫内库珍藏的殷红玛瑙盘，婕妤传下御旨才人将它取来。
将军接受赐盘叩拜皇恩回归，轻纨细绮相继赐来快速如飞。
贵戚们谁得到曹将军亲笔迹，谁就觉得府第屏障增加光辉。
当年唐太宗著名宝马“拳毛”，近代郭子仪家中好驹“狮子花”。
而今新画之中就有这两匹马，使得识马的人久久感慨赞夸。
这两匹战场上万人敌的神骏，展开画绢如见奔马扬起风沙。
其馀七匹也都是特殊而奇绝，远远看去象寒空中飘动烟雪。
霜蹄骏马蹴踏在长楸大道间，专职马倌和役卒肃立排成列。
可爱的九匹马神姿争俊竞雄，昂首阔视显得高雅深沉稳重。
请问有谁真心喜爱神姿骏马？后世韦讽前代支遁名传天下。
想当年玄宗皇上巡幸新丰宫，车驾上羽旗拂天浩荡朝向东。
腾飞跳跃精良好马有三万匹，匹匹与画图中马的筋骨雷同。
譬如河宗献宝之后穆王归天，唐玄宗再也不能去射蛟江中。
你没看见金粟堆前松柏林里，良马去尽徒见林鸟啼雨呼风。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0d5", "shortContent": "此诗为咏画之作。咏画诗是诗歌中较难着手的一体，因为吟咏生动的实景易，描写已确定画面与基调的纸上之画难。它需要对图画内容、艺术表现形式以及画外的气韵有着通盘的把握，然后将之还原到现实之中，再进行诗歌语言的转换。这种类似于反复编码的过程，非常考验诗人的诗歌技巧。\n\n杜甫却是一位写咏画诗的好手。他的咏画诗，不但能栩栩如生地反映画面的内容，还能够结合现实，在当下与历史之间徜徉，找到其最吻合的契合点，达到一...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270597f0b9738b369b1db", "shortContent": "此诗为咏画之作。咏画诗是诗歌中较难着手的一体，因为吟咏生动的实景易，描写已确定画面与基调的纸上之画难。它需要对图画内容、艺术表现形式以及画外的气韵有着通盘的把握，然后将之还原到现实之中，再进行诗歌语言的转换。这种类似于反复编码的过程，非常考验诗人的诗歌技巧。\n\n杜甫确是一位写咏画诗的好手。他的咏画诗，不但能栩栩如生地反映画面的内容，还能够结合现实，在当下与历史之间徜徉，找到其最吻合的契合点，达到一...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '杨伦《杜诗镜铨》评「可怜九马争神骏，顾视清高气深稳」二句：「警句。」
陆时雍《唐诗镜》：「画中见真，真中带画，尤难。」
浦起龙《读杜心解》说：「身历兴衰，感时抚事，惟其胸中有泪，是以言中有物。」', 'center', 1416821772, '57b965b98ac2470062e317ea', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10505, '丹青引赠曹将军霸', NULL, 141, 1416, 2, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/2991702.htm', '', '将军魏武之子孙，于今为庶为清门。
英雄割据虽已矣，文彩风流今尚存。
学书初学卫夫人，但恨无过王右军。
丹青不知老将至，富贵于我如浮云。
开元之中常引见，承恩数上南薰殿。
凌烟功臣少颜色，将军下笔开生面。
良相头上进贤冠，猛将腰间大羽箭。
褒公鄂公毛发动，英姿飒爽来酣战。
先帝天马玉花骢，画工如山貌不同。
是日牵来赤墀下，迥立阊阖生长风。
诏谓将军拂绢素，意匠惨澹经营中。
斯须九重真龙出，一洗万古凡马空。
玉花却在御榻上，榻上庭前屹相向。
至尊含笑催赐金，圉人太仆皆惆怅。
弟子韩幹早入室，亦能画马穷殊相。
幹惟画肉不画骨，忍使骅骝气凋丧。
将军画善盖有神，偶逢佳士亦写真。
即今漂泊干戈际，屡貌寻常行路人。
途穷反遭俗眼白，世上未有如公贫。
但看古来盛名下，终日坎壈缠其身。', '曹霸是盛唐时期著名的画马大师，安史之乱後，潦倒漂泊。唐代宗广德二年（西元七六四年），杜少陵和他在成都相识，十分同情他的遭遇，写下了这首《丹青引赠曹将军霸》。
此诗开头四句统摄全篇。接着写曹霸在书画上的师承渊源，进取精神，刻苦态度和高尚情操。「开元」以下八句，转入主题，高度赞扬曹霸在人物画上的辉煌成就。「先帝」以下八句，诗人细腻地描写了画玉花骢的过程。「玉花」以下八句，诗人进而形容画马的艺术魅力。最後八句，又以苍凉的笔调描写曹霸流入民间的落魄境况。作者以诗摹写画意，评画论画，诗画结合，富有浓郁的诗情画意，把深邃的现实主义画论和诗传体的特写融为一炉，具有独特的美学意义。', '丹青：指绘画。
曹将军霸：指曹霸，唐代名画家，以画人物及马著称，颇得唐高宗的宠幸，官至左武卫将军，故称他曹将军。
魏武：指魏武帝曹操。
庶：即庶人、平民。
清门：即寒门，清贫之家。唐玄宗末年，曹霸因得罪朝廷，被削职免官。
虽：一作「皆」。
犹：一作「今」。
卫夫人：即卫铄，字茂猗。晋代有名的女书法家，擅长隶书及正书。
无：一作「未」。
王右军：即晋代书法家王羲之，官至右军将军。
「丹青不知老将至，富贵于我如浮云。」句：曹霸—生精诚研求画艺甚至到了忘老的程度，同时他还看轻利禄富贵，具有高尚的情操。
开元：唐玄宗的年号（公元713年—公元741年）。
中：一作「年」。
引见：皇帝召见臣属。
承恩：获得皇帝的恩宠。
南薰殿：唐代宫殿名。
凌烟：即凌烟阁，唐太宗为了褒奖文武开国功臣，于贞观十七年（公元643年）命阎立本等在凌烟阁画二十四功臣图。少颜色：指功臣图像因年久而褪色。
开生面：展现出如生的面貌。
进贤冠：古代成名、文儒者的服饰。
大羽箭：大杆长箭。
褒公：即段志玄，唐代开国名将，凌烟阁功臣之一，封褒国公。
鄂公：即尉迟恭，唐代开国名将，凌烟阁功臣之一，封鄂国公。
爽：一作「飒」。
来：一作「犹」。
先帝：指唐玄宗，死于宝应元年（公元762年）。
天：一作「御」。
五花骢（cōng）：唐玄宗所骑的骏马名。骢，青白色的马
山：众多的意思。
貌不同：画得不—样，即画得不像。貌，在这里作动词用。
赤墀（chí）：也叫丹墀。宫殿前的台阶。
迥（jiǒng）：一作「夐」，高。
阊阖（chānghé）：宫门。
诏：皇帝的命令。
意匠：指画家的立意和构思。意，一作「法」。
惨澹（dàn）：费心良苦。
经营：即绘画的「经营位置，结构安排。
「意匠惨澹经营中。」句：曹霸在画马前经过审慎的酝酿，胸有全局而後落笔作画。
九重：代指皇宫，因天子有九重门。真龙、古人称马高八尺为龙，这里比喻所画的玉花骢。
圉（yǔ）人：管理御马的官吏。
太仆：管理皇帝车马的官吏。
韩幹：唐代名画家。善画人物，更擅长鞍马。他初师曹霸，注重写生，後来自成一家。
穷殊相：极尽各种不同的形姿变化。相，一作「状」。
画：一作「盖」。
善：一作「妙」。
盖有神：大概有神明之助，极言曹霸画艺高超。
偶：一作「必」。
写真：指画肖像。
「将军画善盖有神，偶逢佳士亦写真。」句：曹霸画马仅得形似，不能传神。
干戈：战争，指安史之乱。
貌：即写真。
「世上未有如公贫」句：一作「他富至今我徒贫」。
坎壈（lǎn）：穷困、困顿。', '曹将军是魏武帝曹操後代子孙，而今却沦为平民百姓成为寒门。
英雄割据的时代一去不复返了，曹家文章丰采却在你身上留存。
当年为学书法你先拜师卫夫人，只恨得没有超过王羲之右将军。
你毕生专攻绘画不知老之将至，荣华富贵对于你却如空中浮云。
开元年间你常常被唐玄宗召见，承恩载德你曾多次登上南薰殿。
凌烟阁的功臣画象年久褪颜色，曹将军你挥笔重画又别开生面。
良相们的头顶都戴上了进贤冠，猛将们的腰间皆佩带着大羽箭。
褒公鄂公的毛发似乎都在抖动，他们英姿飒爽好象是正在酣战。
开元时先帝的天马名叫玉花骢，多少画家画出的都与原貌不同。
当天玉花骢被牵到殿中红阶下，昂首屹立宫门更增添它的威风。
皇上命令你展开丝绢准备作画，你匠心独运惨淡经营刻苦用功。
片刻间九天龙马就在绢上显现，一下比得万代凡马皆成了平庸。
玉花骢图如真马倒在皇帝榻上，榻上马图和阶前屹立真马相同。
皇上含笑催促左右赏赐你黄金，太仆和马倌们个个都迷惘发怔。
将军的门生韩干画技早学上手，他也能画马且有许多不凡形象。
韩干只画外表画不出内在精神，常使骅骝好马的生气凋敝失丧。
将军的画精美美在画中有神韵，偶逢真名士才肯为他动笔写真。
而今你漂泊沦落在战乱的社会，平常所画的却是普通的行路人。
你到晚年反而遭受世俗的白眼，人世间还未有人象你这般赤贫。
只要看看历来那些负盛名的人，有谁不终日坎坷穷愁纠缠其身？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ae911759740c9b1a97", "shortContent": "曹霸是盛唐著名画马大师，安史之乱后，潦倒漂泊。唐代宗广德二年（764），杜甫和他在成都相识，十分同情他的遭遇，写下这首《丹青引》。\n诗起笔洗练，苍凉。先说曹霸是魏武帝曹操之后，如今削籍，沦为寻常百姓。据清仇兆鳌《杜诗详注》：“明皇末年（756），霸得罪，削籍为庶人。”然后宕开一笔，颂扬曹霸祖先。曹操称雄中原的业绩虽成往史，但其诗歌的艺术造诣高超，辞采美妙，流风余韵，至今犹存。开头四句，抑扬起伏，跌...", "authors": ["何国治"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a84", "shortContent": "曹霸是盛唐著名画马大师，安史之乱后，潦倒漂泊。唐代宗广德二年（764），杜甫和他在成都相识，十分同情他的遭遇，写下这首《丹青引》。\n\n诗起笔洗练、苍凉。先说曹霸是魏武帝曹操之后，如今削籍，沦为寻常百姓。据清仇兆鳌《杜诗详注》：“明皇末年（756），霸得罪，削籍为庶人。”然后宕开一笔，颂扬曹霸祖先。曹操称雄中原的业绩虽成往史，但其诗歌的艺术造诣高超，辞采美妙，流风余韵，至今犹存。开头四句，抑扬起伏，...", "authors": ["何国治"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0d6", "shortContent": "此诗或题为《丹青引赠曹将军霸》。此为安史之乱后，杜甫于广德二年（764）在成都所作。曹霸为开元、天宝之际的书画名家，战乱后流落至蜀，杜甫写此诗赠给他，实为画家曹霸一生小传。题为《丹青引》，自然是着重曹霸在画艺上的成就。\n\n首句相当于传记中的介绍其家世里居，追本而溯源。曹霸本为魏朝皇室曹髦之后，为魏武（曹操）的子孙，但传至唐代，已为庶人，家世贫寒。\n“英雄割据虽已矣，文彩风流今尚存”，前句为其显赫家...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270597f0b9738b369b1dd", "shortContent": "此诗或题为《丹青引赠曹将军霸》。此为安史之乱后，杜甫于广德二年（764）在成都所作。曹霸为开元、天宝之际的书画名家，战乱后流落至蜀，杜甫写此诗赠给他，实为画家曹霸一生小传。题为《丹青引》，自然是着重曹霸在画艺上的成就。\n\n首句相当于传记中的介绍其家世里居，追本而溯源。曹霸本为魏朝皇室曹髦之后，为魏武帝（曹操）的子孙，但传至唐代，已为庶人，家世贫寒。“英雄割据虽已矣，文采风流犹尚存”，前句为其显赫家...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "646607ebc0471b0062d2e517", "shortContent": "曹霸是盛唐著名画马大师，安史之乱后，潦倒飘泊。唐代宗广德二年（764），杜甫和他在成都相识，十分同情他的遭遇，写下这首《丹青引》。\n\n诗起笔洗练，苍凉。先说曹霸是魏武帝曹操之后，如今削籍，沦为寻常百姓。据清仇兆鳌《杜诗详注》：“明皇末年（756），霸得罪，削籍为庶人。”然后宕开一笔，颂扬曹霸祖先。曹操称雄中原的业绩虽成往史，但其诗歌的艺术造诣高超，辞采美妙，流风余韵，至今犹存。开头四句，抑扬起伏，...", "authors": ["何国治"], "pressName": "上海辞书出版社"}]', '《彦周诗话》：老杜作《曹将军丹青引》云：「一洗万古凡马空。」东坡《观吴道子画壁诗》云：「笔所未到气已吞。」吾不得见其画矣。此二句，二公之诗各可以当之。东坡作《妙善师写御容诗》，美则美矣，然不若《丹青引》云「将军下笔开生面」，又云「褒公鄂公毛髮动，英姿飒爽来酣战」。後说画玉花骢马，而曰：「至尊含笑催赐金，圉人太仆皆惆怅。」此诗微而显，《春秋》法也。
《诚斋诗话》：七言长韵古诗，如杜少陵《丹青引曹将军画马》《奉先县刘少府山水障歌》等篇，皆雄伟宏放，不可捕捉。学诗者于李、杜、苏、黄诗中，求此等类，诵读沈酣，深得其意味，则落笔自绝矣。
《韵语阳秋》：杜子美《曹将军丹青引》云：「将军魏武之子孙，幹今为庶为清门。」元微之《去杭州》诗亦云：「房杜王魏之子孙，虽及百代为清门。」则知老杜于当时已为诗人所钦服如此。残膏剩馥，沾丐後代，宜哉！
《吴礼部诗话》：又凡作诗，难用经句，老杜则不然，「丹青不知老将至，富贵于我如浮云」，若自己出。
《唐诗品汇》：刘云：起语激昂慷慨，少有及此（「于今为庶」句下）。刘云：突兀四语，能事志意，毕竟往复浩荡，只在里许（「学书初学」四句下）。又云：自是笔意至此，非思致所及。谢无勉云：此自然不做底语到及至处者也（「富贵于我」句下）。刘云：「迥立」，意从容（「迥立阊阖」句下）。刘云：首尾悲壮动荡，皆名言。
《唐诗援》：申凫盟谓此首：首尾振荡，句句作意。
《唐诗归》：锺云：此语作负真癖人不知（「丹青不知」句下）。锺云：「意匠惨淡经营中」，此入想光景，无处告诉，只「颠狂此技成光景」上句俦众中有之，下句幽独中有之，苦心作诗文人知此二语之妙（「意匠惨淡」句下）。锺云：五字说出帝王鉴赏风趣在目（「至尊含笑」句下）。锺云：骂尽凡手（「幹惟画肉」句下）。谭云：骨气挺然语，古今豪杰停读。锺云：韩幹名手，老杜说得如此，是何等胆识！然今人犹知有韩幹马而不闻曹霸，安知负千古盛名，非以画肉之战乎（「忍使骅骝」句下）。锺云：写即有品（「必逢佳士」句下）。锺云：可怜（「即今漂泊」二句下）。
《唐诗选脉会通评林》：顾璘曰：直语，亦是有生动处。陆时雍曰：「斯须九重」二语是杰句，「幹惟画肉」二语，此便是画家妙诀，不类泛常题诗。周珽曰：选语妙合处如龙行空中，鳞爪皆化为烟云。
《唐风定》：沉雄顿挫，妙境别开，气骨过王、李，风韵亦逊之，谓诗歌之变体，自非虚语。
《唐风怀》：南村曰：叙事历落，如生龙活虎，真诗中马迁，而「画肉」、「画骨」一语，尤感慨深长。
《唐诗快》：此又是一起法，笔力俱足千钧（首二句下）。笔趣横流（「丹青不知」二句下）。闪烁怕人，「子璋髑髅」之句可以辟疟，何不用此句乎（「英姿飒爽」句下）？使观者亦复惨淡（「意匠惨淡」句下）。忽然眼张心动（「斯须九重」二句下）。骅骝丧气乎？英雄丧气乎（「忍使骅骝」句下）？俗眼青且不可，何况于白！然不白不成其俗（「途穷反遭」句下）。
《杜诗说》：就家势起，起法从容；不即入画、先赞其书，更从容。「弟子」四句，乃抑彼扬此法，插此四句，更觉气局排荡。
《而庵说唐诗》：此歌起处，写将军之当时，极其巃嵷；结处写将军之今日，极其慷慨；中间叙其丹青之思遇，以画马为主；马之前後，又将功臣、佳士来衬，起头之上，更有起头，结尾之下，又有结尾。气厚力大，沉酣夭矫。看其局势，如百万雄兵团团围住，独马单枪杀进去又杀出来，非同小可，子美，歌行中大将，此首尤为旗鼓。可见行兵、行文、作诗、作画，无异法也。
《杜诗解》：（此诗）波澜叠出，分外争奇，却一气混成，真乃匠心独运之笔。
《原诗》：少陵七言长篇，变化神妙，极惨淡经营之奇。就《赠曹将军丹青引》一篇论之：起手「将军魏武之子孙」四句，如天半奇峰，拔地陡起；他人于此下便欲接丹青等语，用转韵矣。忽接「学书」二句，又接「老至」「浮云」二句，却不转韵，诵之殊觉缓时无谓；然一起奇峰高插，使又连一峰，将来如何撒手？故即跌下陂陀，沙泺石确，使人蹇裳委步，无可盘桓，故作画蛇添足，拖沓迤逦，是遥望中峰地步。接「开元引见」二句，方转入曹将军正而。……接「凌烟」「下笔」二句，盖将军丹青是主，先以学书作宾；转韵画马是主，又先以画功臣作宾，章法经营，极奇而整。……按「良相」「猛士」四句，宾中之宾，益觉无谓；不知其层次养局，故纡折其途，以渐升极高极峻处，令人目前忽划然天开也。至此方入画马正面，一韵八句，连峰互映，万笏凌霄，是中峰绝顶处。转韵接「玉花」「御榻」四句，峰势稍平，蜿蟺游衍出之，忽接「弟子韩幹」四句。他人于此必转韵。更将韩幹作排场，仍不转韵，以韩幹作找足语，盖此处不当更以宾作排场，重复掩主，便失体段；然後咏叹将军画，包罗收拾，以感慨系之篇终焉。章法如此，极森严，极整暇。
《义门读书记》：《类本》云：此等，太史公《列传》也。多少事，多少议论，多少气魄！
《茧斋诗谈》：《丹青引》与《画马图》一祥做法，细按之，彼如神龙在天，此如狮子跳踯，有平涉、飞腾之分；此在手法上论。所以古人文章贵于超忽变化也。「褒公鄂公毛髮动，英姿飒爽来酣战」，人是活的、马是活的可想。映衬双透，只用「玉花宛在御榻上」二句已足，此是何等手法！
《唐宋诗醇》：起笔老横，「开元之中」以下，叙昔日之遇，正为末段反照；丹青之妙，见赠言之义明矣。通篇浏漓顿挫，节奏之妙于斯为极。
《唐诗别裁》：不以正统与之，诗中史笔（「英雄割据」二句下）。神来纸上，如堆阜突出（「一洗万古」三句下），反衬霸之尽善，非必贬幹也（「幹惟画肉」二句下）。推开作结（「但看古来」二句下）。画人画马，宾主相形，纵横跌宕，此得之于心，应之于手，有化工而无人力，观止矣。
《读杜心解》：「佳士」句，补笔引下。须知将军画不止前二项，故以写佳士补之。其前只铺排奉诏所作者，正与此处「屡貌寻常」相照耀。见今昔异时，喧寂顿判：此则赠曹感遇本旨也。结联又推开作解譬语，而寄慨转探。
《杜诗镜铨》：神来之笔。申曰：与「堂上不合生枫树」同一落想，而出语更奇（「斯须九重」二句下）。张惕庵曰：此太史公列传也。多少事实，多少议论，多少顿挫，俱在尺幅中。章法跌宕纵横，如神龙在霄，变化不可方物。
《岘佣说诗》：《丹青引》画人是宾，画马是主。却从善书引起善画，从画人引起画马，又用韩幹之画肉，垫将军之画骨，末後搭到画人，章法错综绝妙。……唯收处悲飒，不可学。
《昭昧詹言》：起势飘忽，似从天外来。第三句宕势，此是加倍色法。四句合，乃不直率。「学书」一衬，就势一放，不致短促。……「开元」句笔势纵横。「凌烟」句，又衬。褒公」二句与下「斯须」句、「至尊」句，皆是起棱，皆是汁浆。于他人极忙之处，却偏能闲雅从容，真大手笔也。古今惟此老一人而已，所谓放之中，要句字留住，不尔便伤直率。「先帝」句又衬，又出波澜。叙事未了，忽入议论，牵扯之妙，太史公文法。「迥立」句夹写夹叙。「诏谓」以下，磊落跌宕，有文外远致。……此诗处处皆有开合，通身用衬，一大法门。
《唐宋诗举要》：前人有谓作诗戒用经语，恐其陈腐也。此二句令人忘其为经者，全在笔妙（「丹青不知」二句下）。二句真马、画马合写，何等精灵（「榻上庭前」句下）。方曰：此与《曹将军画马图》有起有讫，波澜明画，轨度可寻，而其妙处在神来气来，纸上起棱，凡诗文之妙者无不起棱，有浆汁，有兴象。不然，非神品也。', 'center', 1416822094, '57b8fefa79bc44005b9e9115', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10506, '寄韩谏议注', NULL, 104, 1416, 2, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383157.htm', '', '今我不乐思岳阳，身欲奋飞病在床。
美人娟娟隔秋水，濯足洞庭望八荒。
鸿飞冥冥日月白，青枫叶赤天雨霜。
玉京群帝集北斗，或骑麒麟翳凤凰。
芙蓉旌旗烟雾落，影动倒景摇潇湘。
星宫之君醉琼浆，羽人稀少不在旁。
似闻昨者赤松子，恐是汉代韩张良。
昔随刘氏定长安，帷幄未改神惨伤。
国家成败吾岂敢，色难腥腐餐枫香。
周南留滞古所惜，南极老人应寿昌。
美人胡为隔秋水，焉得置之贡玉堂。', '这首诗作于唐代宗大历元年（公元766年）秋，杜少陵出蜀居留夔州之时。从作品看，诗中的韩注大概是杜少陵的一位好友，曾出任谏言，于国有功，且富有才干。但他在朝廷却受到小人排挤，于是辞官归隐于岳阳，修神仙之道，杜少陵为朋友感到惋惜，于是写这首劝他去辅国佐君。
诗前六句为第一段，写怀念韩某远在洞庭，日月更迭，思念益切。「玉京」六句为第二段，写朝廷小人得势，而贤臣远去。点出韩某已罢官去国。「似闻」六句为第三段，写听到韩某罢官原因，以张良比之，颂其高洁有才。末四句为第四段，抒写自己感想，并望韩某再度出山，为国出力。诗思严慎细致周密，写得隐晦曲折。格调却清新激昂，铿锵有力。', '韩谏议注：韩注，生平不详，由此诗看当为楚人。谏议是其曾任官职，唐门下省属官有谏议大夫，正五品上，掌侍从赞相，规谏讽谕。
岳阳：今湖南岳阳，当是韩注所在地。
奋飞：插翅飞去。
美人：指所思慕之人，男女都可用，用于男性则指其才德美。《离骚》：「惟草木之零落兮，恐美人之迟暮」。娟娟：秀美状。
濯足洞庭：《楚辞·渔父》引古歌：「沧浪之水清兮，可以濯我缨；沧浪之水浊兮，可以濯吾足。」据《楚辞》旧注，沧浪水近在楚都。当与洞庭同一水系。洞庭，湖名，在今湖南、湖北交界处。
八荒：四方四隅称八荒。
鸿飞冥冥：指韩己遁世。冥冥，远空。
玉京：玉京山，道家仙山，元始天尊居处。
群帝：此指群仙。
北斗：北斗是人君之象，号令之主（《晋书·天文志》）。
「或骑麒麟翳凤凰」句：《集仙录》记：群仙毕集，位高者乘鸾，次乘麒麟，次乘龙。翳，语助词。
倒景：即「倒影」。
摇潇湘：指倒影在潇湘水中荡漾。潇、湘是二水，于湖南零陵汇合。
星宫之君：承「集北斗」，当指北斗星君，借指皇帝。
羽人：飞仙，借指远贬之人。两句谓君上昏醉，贤人远去。
「似闻昨者赤松子，恐是汉代韩张良」句：张良字子房，韩国旧贵族，后为刘邦谋臣，刘邦得天下，张良说：「愿去人间事，从赤松子游耳。」见《汉书，张良传》。后道教附会张良真随赤松子仙去。赤松子是神农时雨师。
「昔随刘氏定长安，帷幄未改神惨伤」句：《汉书·高祖纪》载刘邦言：「运筹帷幄之中，决胜千里之外，吾不如子房功。」此借用言韩注有功于朝廷，旧迹未改，而人事已非，不由黯然神伤。定长安，建都长安。帷惺，军幕。
「国家成败吾岂敢，色难腥腐餐枫香」句：前句化用诸葛亮《出师表》：「至于成败利钝，非臣之明所能逆睹也。」吾，是以韩的口气说话。后句化用《庄子·秋水》寓言，说鹓雏（鸾凤之属）非梧桐不止，非练实不食，非醴泉不饮。有鸱鸮（猫头鹰）得一腐鼠，见鹓雏飞过，怕来夺食，就「吓」声以驱赶鹓雏。不知鹓雏根本无意于此。鸱鸮喻宵小之徒，鹓雏言避世贤者。鲍照《升天行》「何时与尔曹，逐腐共吞腥」，鲍诗是愤激反语，这里正说。色难，面有难色，不愿之意。枫香，《尔雅注》说枫似白杨有脂而香，称枫香。道家常以枫香和药，餐枫香喻持操隐居。
「周南留滞古所惜」句：《史记·太史公自序》：「是岁天子始建汉家之封，而太史公留滞周南，不得与从事。」
南极老人：《晋书·天文志》言，南极星，又名老人星，见则天下治平，主掌寿昌。
胡为：何为，为什么。
贡：献，这里是荐举之意。
玉堂：汉未央宫有玉堂。这里指朝廷。', '我的心情恺郁思念着岳阳，想要鼓翼奋飞却辗转在病床。远隔秋水的伊人是多么美好，你在洞庭湖边洗脚，一面向四方遥望。鸿雁飞向遥远的高天，皓洁的日月放射光芒。秋风染红青枫的绿叶，秋空中降下寒霜。玉京的天帝们聚集在北斗星宫，有的乘驾麒麟，有的骑着凤凰。芙蓉装饰的旌旗招展，如烟雾漫天，旗影摇动那映着丽日的潇湘。星宫的帝君在那里畅饮美酒，可惜飞仙稀少，远在他方。听说你已经归隐，跟从仙人赤松子，像汉代的张良一样。你曾经安邦定国，建立功绩，运筹决策的政务使你烦倦，神情惨伤。你说你不能左右国家的命运，想去求仙访道，不愿留在污浊的尘世上。太史公怅恨滞留洛阳，你又为什么隐居潇湘？当天空出现老人星，世上就会太平、安康。你为什么同我远隔秋水不得相见？几时你才肯重新出山来辅佐朝堂？', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0d7", "shortContent": "本诗中的韩谏议是什么人，一向为注家争论不休。有人认为即李泌，然而杜甫作诗，颇有史识，不会为此藏头露尾之事，如果真是李泌，杜甫定会明白说出，不会故作狡狯，而以隐语出之。朱鹤龄注较可取，他说：“韩谏议不可考。其人大似李邺侯，必肃宗收京时尝与密谋，后屏居衡湘，修神仙羽化之道。公思之而作，‘似闻’以下，美其功在帷幄，翛然远引；‘周南’以下，惜其留滞秋水，而不得大用也。”（《杜诗详注》引）此说平实，可从。\n...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270597f0b9738b369b1e1", "shortContent": "本诗中的韩谏议是什么人，一向为注家争论不休。有人认为即李泌，然而杜甫作诗，颇有史识，不会为此藏头露尾之事，如果真是李泌，杜甫定会明白说出，不会故作狡狯，而以隐语出之。朱鹤龄注较可取，他说：“韩谏议不可考。其人大似李邺侯，必肃宗收京时尝与密谋，后屏居衡湘，修神仙羽化之道。公思之而作，‘似闻’以下，美其功在帷幄，翛然远引；‘周南’以下，惜其留滞秋水，而不得大用也。”（《杜诗详注》引）此说平实，可从。\n...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '', 'center', 1416822187, '57b8f304c4c97100558ec5fb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10507, '古柏行', NULL, 77, 1416, 1, 2, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383159.htm', '', '孔明庙前有老柏，柯如青铜根如石。
霜皮溜雨四十围，黛色参天二千尺。
君臣已与时际会，树木犹为人爱惜。
云来气接巫峡长，月出寒通雪山白。
忆昨路绕锦亭东，先主武侯同閟宫。
崔嵬枝干郊原古，窈窕丹青户牖空。
落落盘踞虽得地，冥冥孤高多烈风。
扶持自是神明力，正直原因造化功。
大厦如倾要梁栋，万牛回首丘山重。
不露文章世已惊，未辞剪伐谁能送。
苦心岂免容蝼蚁，香叶终经宿鸾凤。
志士幽人莫怨嗟，古来材大难为用。', '此诗采用比兴体，借赞久经风霜、挺立寒空的古柏，以称雄才大略、耿耿忠心的诸葛亮。诗写古柏古老，借以兴起君臣际会，以老柏孤高，喻武侯忠贞，表现了诗人对诸葛亮的崇敬之情，并借以抒发了自己愿意报效朝廷但不能用事、壮志难酬的悲愤之情。全诗比喻精当，语多双关，寄意深远，是咏物诗的名篇。', '成都的武侯祠附在先主庙中，夔州的孔明庙则和先主庙分开，这是夔州的孔明庙。
这句写柏之古老。柯，枝柯。
此二句写柏之高大，是夸大的写法。霜皮，一作苍皮，形容皮色的苍白。溜雨，形容皮的光滑。四十围，四十人合抱。
这两句是插叙。张上若云：“补出孔明生前德北一层，方有原委。”按意谓由于刘备和孔明君臣二人有功德在民，人民不加剪伐，故柏树才长得这般高大；柏树的高大，正说明孔明的遗爱。际会，犹遇合。
这两句再承三四句极力形容咏叹柏树之高大。赵次公云：“巫峡在夔之下（按当言东），巫峡之云来而柏之气与接；雪山在夔之西，雪山之月出而柏之寒与通，皆言其高大也。”宋人刘须溪认为云来二句当在君臣二句前，君臣二句当在云来二句后（仇兆鳌把这四句倒置，就是依据刘说的），实太生观大胆。因为这样一来，似乎是通顺些，但文章却显得乎庸没有气势，所以黄生斥为“小儿之见”。——以上是第一段，是咏古柏的正文。
此下四句宕开，以成都古柏作陪。杜甫是前一年才离开成都的，所以说忆昨。杜甫成都草堂紧靠锦江（《杜鹃》诗：“结庐锦水边。”），草堂中有亭（《寄题江外草堂》诗：“台亭随高下，敞熬当清川。”），所以说锦享（严武有《寄题杜二锦江野亭》诗）。武侯祠在亭东，所以说路绕锦亭东。亭，一作“城”。
先主：指刘备。閟宫，即祠庙。
仇兆鳌注：“郊原古，有古致也。卢牖空，虚无人也。”窈窕，深邃貌。
落落：独立不苟合。
此下四句收归夔州古柏。是说夔州庙柏生在高山，苦于烈风，不如成都庙柏之生于平原。落落，出群貌。因生在孔明庙前，有人爱惜，故曰得地，但树高招风，又在高山上，就更要经常为烈风所撼。冥冥，高空的颜色。
不为烈风所拨，似有神灵呵护，故曰神明力。柏之正直。本出自然，故日造化功。正因为正直，故得神明扶持，二句语虽对，而意实一贯。——以上是第二段。由古柏之高大，进一步写出古柏之正直。
这以下又宕开，借古柏之难载，以喻大才之难为世用。《文中子》：“大厦之倾，非一本所支。”古柏重如丘山，故万头牛也拖不动。
不露文章：指古柏没有花叶之美。
此二句中有着杜甫自己的影子。古柏不知自炫，故曰不露文章。古柏本可作栋梁，故曰未辞剪伐。这就杜甫为人来说，即不怕牺牲，与“我能剖心血，饮啄慰孤愁”，“济时敢爱死，寂寞壮心惊”正是一副心肠。送，就木说，是移送：就人说，是保送或推荐。
柏心味苦，故曰苦心。柏叶有香气，故曰香叶。这两句也含有身世之感。
结二句吐出本意，但材大二字仍包括吉柏在年。在封建社会，一个真正想为国家人民作点事的人，是并不为统治者所欢迎的。古来，是说不独今日如此，从古以来就如此。——以上是第三段。', '孔明庙前有一株古老的柏树，枝干色如青铜根柢固如盘石。
树皮洁白润滑树干有四十围，青黑色朝天耸立足有二千尺。
刘备孔明君臣遇合与时既往，至今树木犹在仍被人们爱惜。
柏树高耸云雾飘来气接巫峡，月出寒光高照寒气直通岷山。
想昔日小路环绕我的草堂东，先生庙与武侯祠在一个閟宫。
柏树枝干崔嵬郊原增生古致，庙宇深邃漆绘连绵门窗宽空。
古柏独立高耸虽然盘踞得地，但是位高孤傲必定多招烈风。
它得到扶持自然是神明伟力，它正直伟岸原于造物者之功。
大厦如若倾倒要有梁栋支撑，古柏重如丘山万年也难拉动。
它不露花纹彩理使世人震惊，它不辞砍伐又有谁能够采送？
它虽有苦心也难免蝼蚁侵蚀，树叶芳香曾经招来往宿鸾凤。
天下志士幽人请你不要怨叹，自古以来大材一贯难得重用。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1c7f0b9738b369b0d8", "shortContent": "本诗作于代宗大历元年（766），时杜甫在夔州。史载诸葛亮逝世之后，蜀中百姓感其恩义，于所在处处为其立庙。杜甫在夔州也见到了武侯庙，但是，他的注意力却被庙前的一棵古柏吸引住了。\n\n这棵古柏不知生长了多少年了，它的枝条像青铜般坚硬，它的树根固如磐石。在不知多少年的风雨中，它的树皮被风吹雨打得成了苍白的颜色，表面也光滑得可以直接让雨水沿着树皮滑溜下来。这棵古柏是如此巨大，要四十个人才能合抱；深青色的柏树...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270607f0b9738b369b1e9", "shortContent": "本诗是杜甫在夔州（今属重庆）所作。\n\n诸葛武侯在唐代的剑南道地区（即今四川、重庆一带）可谓是家喻户晓，史载诸葛亮逝世之后，蜀中百姓感其恩义，于所在处处为其立庙。杜甫在夔州也见到了武侯庙，但是，他的注意力却被庙前的一棵古柏吸引住了。\n这棵古柏不知生长了多少年了，它的枝条像青铜般坚硬，它的树根固如磐石。在不知多少年的风雨中，它的树皮被风吹雨打得成了苍白的颜色，表面也光滑得可以直接让雨水沿着树皮滑溜下来...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '', 'center', 1416822293, '57b965c57db2a200542a2ecf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10508, '观公孙大娘弟子舞剑器行', NULL, 204, 1416, 3, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/810143.htm', '大历二年十月十九日，夔府别驾元持宅，见临颍李十二娘舞剑器，壮其蔚跂，问其所师，曰：「余公孙大娘弟子也。」开元三载，余尚童稚，记于郾城观公孙氏，舞剑器浑脱，浏漓顿挫，独出冠时，自高头宜春梨园二伎坊内人洎外供奉，晓是舞者，圣文神武皇帝初，公孙一人而已。玉貌锦衣，况余白首，今兹弟子，亦非盛颜。既辨其由来，知波澜莫二，抚事慷慨，聊为《剑器行》。昔者吴人张旭，善草书书帖，数常于邺县见公孙大娘舞西河剑器，自此草书长进，豪荡感激，即公孙可知矣。', '昔有佳人公孙氏，一舞剑器动四方。
观者如山色沮丧，天地为之久低昂。
㸌如羿射九日落，矫如群帝骖龙翔。
来如雷霆收震怒，罢如江海凝清光。
绛唇珠袖两寂寞，晚有弟子传芬芳。
临颍美人在白帝，妙舞此曲神扬扬。
与余问答既有以，感时抚事增惋伤。
先帝侍女八千人，公孙剑器初第一。
五十年间似反掌，风尘澒洞昏王室。
梨园子弟散如烟，女乐馀姿映寒日。
金粟堆南木已拱，瞿唐石城草萧瑟。
玳筵急管曲复终，乐极哀来月东出。
老夫不知其所往，足茧荒山转愁疾。', '全诗气势雄浑，沉郁悲壮。见《剑器》而伤往事，抚事慷慨，大有时序不同，人事蹉跎之感。诗以咏李氏，而思公孙；咏公孙而思先帝，寄托作者念念不忘先帝盛世，慨叹当今衰落之情。语言富丽而不浮艳，音节顿挫而多变。', '公孙大娘：唐玄宗时的舞蹈家。
弟子：指李十二娘。
剑器：指唐代流行的武舞，舞者为戎装女子。
大历二年：公元七六七年。
开元三载：公元七一七年。
剑器浑脱：《浑脱》是唐代流行的一种武舞，把《剑器》和《浑脱》综合起来，成为一种新的舞蹈。
骖（cān）：古代驾在车前两侧的马。
瞿（qú）唐：即瞿塘峡。
玳（dài）筵：玳瑁筵。', '唐大历二年十月十九日，我在夔府别驾元持家里，观看临颍李十二娘跳剑器舞，觉得舞姿矫健多变非常壮观，就问她是向谁学习的？她说：「我是公孙大娘的学生」。玄宗开元三年，我还年幼，记得在郾城看过公孙大娘跳《剑器》和《浑脱》舞，流畅飘逸而且节奏明朗，超群出众，当代第一，从皇宫内的宜春、梨园弟子到宫外供奉的舞女中，懂得此舞的，在唐玄宗初年，只有公孙大娘一人而已。当年她服饰华美，容貌漂亮，如今我已是白首老翁，眼前她的弟子李十二娘，也已经不是年轻女子了。既然知道了她舞技的渊源，看来她们师徒的舞技一脉相承，抚今追昔，心中无限感慨，姑且写了《剑器行》这首诗。听说过去吴州人张旭，他擅长书写草书字帖，在邺县经常观看公孙大娘跳一种《西河剑器》舞，从此草书书法大有长进，豪放激扬，放荡不羁，由此可知公孙大娘舞技之高超了。
从前有个漂亮女人，名叫公孙大娘，每当她跳起剑舞来，就要轰动四方。
观看人群多如山，心惊魄动脸变色，天地也被她的舞姿感染，起伏震荡。
剑光璀灿夺目，有如后羿射落九日，舞姿矫健敏捷，恰似天神驾龙飞翔，
起舞时剑势如雷霆万钧，令人屏息，收舞时平静，好象江海凝聚的波光。
鲜红的嘴唇绰约的舞姿，都已逝去，到了晚年，有弟子把艺术继承发扬。
临颍美人李十二娘，在白帝城表演，她和此曲起舞，精妙无比神采飞扬。
她和我谈论好久，关于剑舞的来由，我忆昔抚今，更增添无限惋惜哀伤。
当年玄宗皇上的侍女，约有八千人，剑器舞姿数第一的，只有公孙大娘。
五十年的光阴，真好比翻一下手掌，连年战乱烽烟弥漫，朝政昏暗无常。
那些梨园子弟，一个个地烟消云散，只留李氏的舞姿，掩映冬日的寒光。
金粟山玄宗墓前的树木，已经合抱，瞿塘峡白帝城一带，秋草萧瑟荒凉。
玳弦琴瑟急促的乐曲，又一曲终了，明月初出乐极生悲，我心中惶惶。
我这老夫，真不知哪是要去的地方，荒山里迈步艰难，越走就越觉凄伤。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b003048e64fbd91411", "shortContent": "大历二年十月十九日，夔府别驾元持宅见临颍李十二娘舞剑器，壮其蔚跂。问其所师，曰：“余公孙大娘弟子也。”开元五载，余尚童稚，记于郾城观公孙氏舞剑器浑脱，浏漓顿挫，独出冠时。自高头宜春、梨园二伎坊内人洎外供奉，晓是舞者，圣文神武皇帝初，公孙一人而已。玉貌锦衣，况余白首；今兹弟子，亦匪盛颜。既辨其由来，知波澜莫二。抚事慷慨，聊为《剑器行》。昔者吴人张旭，善草书书帖，数常于邺县见公孙大娘舞西河剑器，自此草...", "authors": ["廖仲安"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f092f8", "shortContent": "读此诗作，有如阅尝一部姿态万千的武侠小说，更妙似欣赏一部声响画面俱佳的影视作品。\n\n故事有一个序幕：话说大历二年（767）十月十九日，杜甫作客于夔州府别驾元持的府上。在宅中，他无意间欣赏到了临颍李十二娘的剑器舞，觉其神奇，“壮其蔚跂”，不由发问：“请问姑娘师出何人，乃有此等造诣？”十二娘极为自豪地回答：“我乃公孙大娘的弟子。”\n \n闻此，杜甫的思绪飘回至开元五年（717），时甫尚年幼，但他却清楚地...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127066c305cf0801816fba", "shortContent": "读此诗作，有如阅尝一部姿态万千的武侠小说，更妙似欣赏一部声响画面俱佳的影视作品。\n\n故事有一个序幕：话说大历二年（767）十月十九日，杜甫作客于夔州别驾元持的府上。在宅中，他无意间欣赏到了临颍李十二娘的剑器舞，觉其神奇，“壮其蔚跤”，不由发问请问：“姑娘师出何人，乃有此等造诣？”十二娘极为自豪地回答：“我乃公孙大娘的弟子。”\n\n闻此，杜甫的思绪飘回至开元五载（717），时甫尚年幼，但他却清楚地记得...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270d4c26cbf3417f0950b", "shortContent": "读此诗作，有如阅尝一部姿态万千的武侠小说，更妙似欣赏一部声响画面俱佳的影视作品。\n\n故事有一个序幕：话说大历二年（767）十月十九日，杜甫作客于夔州别驾元持的府上。在宅中，他无意间欣赏到了临颍李十二娘的剑器舞，觉其神奇，“壮其蔚跂”，不由发问：“请问姑娘师出何人，乃有此等造诣？”十二娘极为自豪地回答：我乃公孙大娘的弟子。\n\n闻此，杜甫的思绪飘回至开元五载（717），时甫尚年幼，但他却清楚记得于郾城...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "64662c4d45e4710056cad669", "shortContent": "有人说，杜甫是以诗为文，韩愈是以文为诗。杜甫这个序，正是以诗为文，不仅主语虚词大半省略，而且在感慨转折之处，还用跳跃跌宕的笔法。不过，序文的内容仍然是清楚的：他先叙大历二年（767）在夔州看了公孙大娘弟子所表演的剑器舞，然后回忆开元五载（717）自己童年时在郾城亲见公孙大娘的舞蹈，说明当唐玄宗初年，公孙大娘的剑器舞在内外教坊独享盛名的情况。抚今思昔，深有感慨，因而写成这首《剑器行》。这篇序写得很有...", "authors": ["廖仲安"], "pressName": "上海辞书出版社"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "64662f545e6bb82b8ccae5e9", "shortContent": "杜诗之有序的共三篇，一为《同元使君舂陵行》，一为《苏大侍御访江浦赋八韵记异》，一即此篇，而以此篇写得最有情致，与诗相称，故可作小品读。\n\n安史之乱前，长安的梨园，就像清代北京的升平署（南府），颇受王室的赏识。在梨园子弟中，张野狐的觱篥，雷海青的琵琶，李龟年的歌唱，公孙大娘的舞蹈，尤为擅扬，名动公卿。\n\n安史乱起，玄宗出亡，万户伤心，雷海青因不愿在叛军前奏乐，竟被支解示众（郑处晦《明皇杂录》）。其他...", "authors": ["金性尧"], "pressName": "上海辞书出版社"}]', '《后村诗话》：《舞剑器行》，世所脍炙，绝妙好词也。内云：「先帝侍女八千人……乐极哀来月东出。」余谓「壮士轩昂赴敌场」，一如「儿女恩怨相尔汝」。杜有建安黄初气骨，白未脱长庆体耳。
《唐诗品汇》：刘云：浓至惨黯，如野笛中断，闻者自不堪也。
《唐诗归》：钟云：题是公孙大娘弟子，而序与诗，情事俱属公孙氏，便自穆然深思。钟云：此一语独妙（「罢如江海」句下）。
《唐诗选脉会通评林》：刘辰翁曰：……「耀如」四句，名状得意，「收」字谓其犹隐隐有声也。但舞一剑，若谓其如雷如霆则非也。周启琦曰：「罢如江海凝清光」，妙。连上三句，觉有精采。
《杜臆》：「来如雷灵收震怒」，凡雷霆震怒，轰然之后。累累远驰，赫有余怒，故「收」字之妙，若轰然一声，阕然而止，虽震怒不为奇也。诗云「感时抚事增惋伤」，则「五十余年似反掌」数句，乃其陚诗本旨；「足茧荒山」，从此而来，尤使人穆然深思也。
《批点唐诗正声》：沉着痛黯，读者无不感慨。
《唐诗快》：乐极哀来，何以即接「月东出」？倒句自奇。（「玳筵急管」句下）。一起有排山倒海之势，后却平平。
《义门读书记》：曲折三致。
《茧斋诗谈》：只「传芬芳」、「神洋洋」六字，已将前叙舞意勾起，不用再说，此烦简相生之妙。
《古欢堂集杂著》：余尝谓白香山《琵琶行》一篇，从杜子美《观公孙大娘弟子舞剑器行》诗得来。「临颍美人在白帝……感时抚事增惋伤」。杜以四语，白成数行，所谓演法也。凫胫何短，鹤胫何长，续之不能，截之不可，各有大然之致，不惟诗也，文亦然。
《唐宋诗醇》：俞如山之嶙峋，后如海之波澜，前半极其浓至，后半感叹，「音响一何悲，弦急知柱促」也。
《读杜心解》：「绛唇」六句，落到李娘，为篇中叙事处。舞之妙，已就公孙详写，此只以「神扬扬」又字括之，可识虚实互用之法。「感时抚事」句，逗出作诗本旨。「先帝」六句，往事之憾，此本旨也。言公孙而统及女乐，言女乐即是感深先帝。故下段竟以「金粟堆」作转接，此下正写惋伤之情。一句着先帝，一句收归本身。……结二句，所谓对此茫茫，百端交集。行失其所往，止失其所居，作者读者，俱欲噭然一哭。
《杜诗镜铨》：蒋云：《序》中「浏漓顿挫」，「豪荡感激」，便是此诗妙境。形容尽致（「㸌如羿射」句下）。省得妙（「与予问答」句下）。邵云：忽然收转，真是笔有神助（「梨园弟子」四句下）。
《昭昧詹言》：「感时」句是一篇前后脉络章法也，却入于出题中藏之。「金粟堆」又从先帝意中起棱，柯觉身世之戚，兴亡之感，交赴腕下。此诗亦「豪宕感激，浏亮顿挫，独出冠时」。自大历至今，先生一人而已。
《岘佣说诗》：读《公孙大娘弟子舞剑器》诗，叙天宝事只数语而无限凄凉，可悟《长恨歌》之繁冗。
《十八家诗钞》：张云：「瞿塘」（原诗作「唐」）句一语收入，笔力超绝，而著语不即不离，尤极浑妙。它手为之，便不免钝滞矣。', 'center', 1416822430, '57b8efecc4c97100558eb4d3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (49293, '如梦令', NULL, 8, 2, 0, 1, '袁介', NULL, 11176, '5858e6351b69e60056f60fe7', '元', 'ci', '词', NULL, NULL, '今夜盛排筵宴。准拟寻芳一遍。春去已多时，问甚红深红浅。
不见。不见。还你一方白绢。', NULL, NULL, NULL, NULL, NULL, 'indent', 1512669629, '585cee4561ff4b00580c6921', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639335, '水浒传 · 第六十七回 · 宋江赏马步三 关胜降水火二将', NULL, 0, 124, 0, 1, '施耐庵', NULL, 10333, '57b9ebb3a633bd005d30998b', '明', 'wen', '文', '', '', '词曰：
呻哙庄公臂断截，灵辄车轮亦能折。
专诸鱼肠数寸锋，姬光座上流将血。
路旁手发千钧锤，秦王副车烟尘飞。
春秋壮士何可比，泰山一死如毛羽。
豫让酬恩荆轲烈，分尸碎骨如何说。
吴国要离刺庆忌，赤心赴刃亦何丑。
得人小恩施大义，剜心刎颈那回首。
丈夫取义能舍生，岂学儿曹夸大口。
话说当下梁中书、李成、闻达慌速寻得败残军马，投南便走。正行之间，又撞着两队伏兵，前后掩杀。李成当先，闻达在后，护着梁中书，并力死战，撞透重围，脱得大难。头盔不整，衣甲飘零，虽是折了人马，且喜三人逃得性命，投西去了。樊瑞引项充、李衮乘势追赶不上，自与雷横、施恩、穆春等同回北京城内听令。
再说军师吴用在城中传下将令，一面出榜安民，一面救灭了火。梁中书、李成、闻达、王太守各家老小，杀的杀了，走的走了，也不来追究。便把大名府库藏打开，应有金银宝物，段匹绫锦，都装载上车了。又开仓廒，将粮米俵济满城百姓了，余者亦装载上车，将回梁山泊仓用。号令众头领人马，都皆完备，把李固、贾氏钉在陷车内，将军马摽拨作三队，回梁山泊来。正是：鞍上将敲金镫响，步军齐唱凯歌回。却叫戴宗先去报宋公明。
宋江会集诸将下山迎接，都到忠义堂上。宋江见了卢俊义，纳头便拜。卢俊义慌忙答礼。宋江道：“我等众人，欲请员外上山，同聚大义。不想却遭此难，几被倾送，寸心如割！皇天垂祐，今日再得相见，大慰平生。”卢俊义拜谢道：“上托兄长虎威，深感众头领之德，齐心并力，救拔贱体，肝胆涂地，难以报答！”便请蔡庆、蔡福拜见宋江，言说：“在下若非此二人，安得残生到此！”称谢不尽。当下宋江要卢员外为尊。卢俊义拜道：“卢某是何等之人，敢为山寨之主！若得与兄长执鞭坠镫，愿为一卒，报答救命之恩，实为万幸。”宋江再三拜请，卢俊义那里肯坐。只见李逵道：“哥哥若让别人做山寨之主，我便杀将起来！”武松道：“哥哥只管让来让去，让得弟兄们心肠冷了！”宋江大喝道：“汝等省得甚么！不得多言！”卢俊义慌忙拜道：“若是兄长苦苦相让，着卢某安身不牢。”李逵叫道：“今朝都没事了，哥哥便做皇帝，教卢员外做丞相，我们都做大官，杀去东京，夺了鸟位子，却不强似在这里鸟乱！”宋江大怒，喝骂李逵。吴用劝道：“且教卢员外东边耳房安歇，宾客相待。等日后有功，却再让位。”宋江方才喜欢。就叫燕青一处安歇。另拨房屋叫蔡福、蔡庆安顿老小。关胜家眷，薛永已取到山寨。
宋江便叫大设筵宴，犒赏马、步、水三军，令大小头目，并众喽啰军健，各自成团作队去吃酒。忠义堂上设宴庆贺，大小头领相谦相让，饮酒作乐。卢俊义起身道：“淫妇奸夫擒捉在此，听候发落。”宋江笑道：“我正忘了。叫他两个过来！”众军把陷车打开，拖出堂前。李固绑在左边将军柱上，贾氏绑在右边将军柱上。宋江道：“休问这厮罪恶，请员外自行发落。”卢俊义得令，手拿短刀，自下堂来，大骂泼妇贼奴。就将二人割腹剜心，凌迟处死，抛弃尸首，上堂来拜谢众人。众头领尽皆作贺，称赞不已。
且不说梁山泊大设筵宴，犒赏马、步、水三军，却说梁中书探听得梁山泊军马退去，再和李成、闻达引领败残军马入城来，看觑老小时，十损八九。众皆嚎哭不已。比及邻近取军追赶梁山泊人马时，已自去得远了。且教各自收军。梁中书的夫人躲得在后花园中，逃得性命，便教丈夫写表申奏朝廷，写书教太师知道，早早调兵遣将，剿除贼寇报仇。抄写民间被杀死者五千余人，中伤者不计其数。各部军马，总折却三万有余。首将赍了奏文密书上路，不则一日，来到东京太师府前下马。门吏转报，太师教唤入来。首将直至节堂下拜见了，呈上密书申奏，诉说打破北京，贼寇浩大，难以抵敌。蔡京见了大怒，且教首将退去。
次日五更，景阳钟响，待漏院众集文武群臣。蔡太师为首，直临玉阶，面奏道君皇帝。天子览奏大惊，与众臣曰：“此寇累造大恶，克当何如？”有谏议大夫赵鼎出班奏道：“前者差蒲东关胜领兵征剿，收捕不全，累至失陷。往往调兵征发，皆折兵将。盖因失其地利，以至如此。以臣愚意，不若降敕赦罪招安，诏取赴阙，命作良臣，以防边境之害。此为上策。”蔡京听了大怒，喝叱道：“汝为谏议大夫，反灭朝廷纲纪，猖獗小人，罪合赐死！”天子曰：“如此，目下便令出朝，无宣不得入朝！”当日革了赵鼎官爵，罢为庶人。当朝谁敢再奏。有诗为证：
玺书招抚是良谋，赵鼎名言孰与俦。
堪笑蔡京多误国，反疏忠直快私仇。
天子又问蔡京曰：“似此贼人猖獗，可遣谁人剿捕此寇？”蔡太师奏曰：“臣量这等山野草贼，安用大军。臣举凌州有二将：一人姓单名廷圭，一人姓魏名定国，见任本州团练使。伏乞陛下圣旨，星夜差人调此一枝军马，克日扫清水泊。”天子大喜，随即降写敕符，着枢密院调遣。天子驾起，百官退朝。众官暗笑。次日，蔡京会省院差官，赍捧圣旨敕符投凌州来。
再说宋江水浒寨内，将北京所得的府库金宝财物，给赏与马、步、水三军。连日杀牛宰马，大排筵宴，庆贺卢员外。虽无炮凤烹龙，端的肉山酒海。众头领酒至半酣，吴用对宋江等说道：“今为卢员外，打破北京，杀损人民，劫掠府库，赶得梁中书等离城逃奔。他岂不写表申奏朝廷，况他丈人是当朝太师，怎肯干罢？必然起军发马，前来征讨。”宋江道：“军师所虑，最为得理。何不使人连夜去北京探听虚实，我这里好做准备。”吴用笑道：“小弟已差人去了，将次回也。”正在筵会之间，商议未了，只见原差探事人到来，报说：“北京梁中书果然申奏朝廷，要调兵征剿。有谏议大夫赵鼎奏请招安，致被蔡京喝骂，削了赵鼎官职。如今奏过天子，差人赍捧敕符，往凌州调遣单廷圭、魏定国两个团练使，起本州军马前来征讨。”宋江便道：“似此如何迎敌？”吴用道：“等他来时，一发捉了。”关胜起身对宋江、吴用道：“关某自从上山，深感仁兄重待，不曾出得半分气力。单廷圭、魏定国，蒲城多曾相会。久知单廷圭那厮，善能用水浸兵之法，人皆称为圣水将军。魏定国这厮，熟精火攻兵法，上阵专能用火器取人，因此呼为神火将军。凌州是本境，兼管本州兵马，取此二人为部下。小弟不才，愿借五千军兵，不等他二将起行，先往凌州路上接住。他若肯降时，带上山来。若不肯投降，必当擒来奉献。兄长亦不须用众头领张弓挟矢，费力劳神。不知尊意若何？”宋江大喜，便叫宣赞、郝思文二将，就跟着一同前去。关胜带了五千军马，来日下山。次早，宋江与众头领在金沙滩寨前饯行，关胜三人引兵去了。
众头领回到忠义堂上，吴用便对宋江说道：“关胜此去，未保其心。可以再差良将随后监督，就行接应。”宋江道：“吾看关胜义气凛然，始终如一。军师不必见疑。”吴用道：“只恐他心不似兄长之心。可再叫林冲、杨志领兵，孙立、黄信为副将，带领五千人马，随即下山。”李逵便道：“我也去走一遭。”宋江道：“此一去用你不着，自有良将建功。”李逵道：“兄弟若闲便要生病。若不叫我去时，独自也要去走一遭。”宋江喝道：“你若不听我的军令，割了你头！”李逵见说，闷闷不已，下堂去了。
不说林冲、杨志领兵下山接应关胜。次日，只见小军来报：“黑旋风李逵，昨夜二更，拿了两把板斧，不知那里去了。”宋江见报，只叫得苦：“是我夜来冲撞了他这几句言语，多管是投别处去了。”吴用道：“兄长非也！他虽粗卤，义气倒重，不到得投别处去。多管是过两日便来。兄长放心！”宋江心慌，先使戴宗去赶，后着时迁、李云、乐和、王定六四个首将，分四路去寻。有诗为证：
李逵斗胆人难及，便要随军报不平。
只为宋江军令肃，手持双斧夜深行。
且说李逵是夜提着两把板斧下山，抄小路径投凌州去，一路上自寻思道：“这两个鸟将军，何消得许多军马去征他！我且抢入城中，一斧一个，都砍杀了，也教哥哥吃一惊，也和他们争得一口气。”走了半日，走得肚饥。原来贪慌下山，又不曾带得盘缠。多时不做这买卖，寻思道：“只得寻个鸟出气的。”正走之间，看见路旁一个村酒店。李逵便入去里面坐下，连打了三角酒，二斤肉吃了，起身便走。酒保拦住讨钱。李逵道：“待我前头去寻得些买卖，却把来还你。”说罢，便动身。只见外面走入个彪形大汉来，喝道：“你这黑厮好大胆！谁开的酒店，你来白吃不肯还钱！”李逵睁着眼道：“老爷不拣那里，只是白吃。”韩伯龙道：“我对你说时，惊得你尿流屁滚！老爷是梁山泊好汉韩伯龙的便是，本钱都是宋江哥哥的。”李逵听了暗笑：“我山寨里那里认的这个鸟人！”原来韩伯龙曾在江湖上打家劫舍，要来上梁山泊入伙，却投奔了旱地忽律朱贵，要他引见宋江。因是宋公明生发背疮在寨中，又调兵遣将，多忙少闲，不曾见得。朱贵权且教他在村中卖酒。当时李逵去腰间拔出一把板斧，看着韩伯龙道：“把斧头为当。”韩伯龙不知是计，舒手来接。被李逵手起，望面门上只一斧，肐地砍着。可怜韩伯龙做了半世强人，死在李逵之手。两三个火家，只恨爷娘少生了两只脚，望深村里走了。李逵就地下掳掠了盘缠，放火烧了草屋，望凌州去了。
行不得一日，正走之间，官道旁边只见走过一条大汉，直上直下相李逵。李逵见那人看他，便道：“你那厮看老爷怎地？”那汉便答道：“你是谁的老爷？”李逵便抢将入来。那汉子手起一拳，打个搭墩。李逵寻思：“这汉子倒使得好拳！”坐在地下，仰着脸问道：“你这汉子姓甚名谁？”那汉道：“老爷没姓，要厮打便和你厮打。你敢起来？”李逵大怒，正待跳将起来，被那汉子肋罗里又只一脚，踢了一跤。李逵叫道：“赢他不得！”扒将起来便走。那汉叫住，问道：“这黑汉子，你姓甚名谁？那里人氏？”李逵道：“我说与你，休要吃惊。我是梁山泊黑旋风李逵的便是。”那汉道：“你端的是不是？不要说谎。”李逵道：“你不信，只看我这两把板斧。”那汉道：“你既是梁山泊好汉，独自一个投那里去？”李逵道：“我和哥哥鳖口气，要投凌州去杀那姓单姓魏的两个。”那汉道：“我听得你梁山泊已有军马去了。你且说是谁？”李逵道：“先是大刀关胜领兵，随后便是豹子头林冲、青面兽杨志领军策应。”那汉听了，纳头便拜。李逵道：“你端的姓甚名谁？”那汉道：“小人原是中山府人氏，祖传三代相扑为生。却才手脚，父子相传，不教徒弟。平生最无面目，到处投人不着。山东、河北都叫我做没面目焦挺。近日打听得寇州地面有座山，名为枯树山，山上有个强人，平生只好杀人，世人把他比做丧门神，姓鲍名旭。他在那山里打家劫舍，我如今待要去那里入伙。”李逵道：“你有这等本事，如何不来投奔俺哥哥宋公明？”焦挺道：“我多时要投奔大寨入伙，却没条门路。今日得遇兄长，愿随哥哥。”李逵道：“我却要和宋公明哥哥争口气了，下山来，不杀得一个人，空着双手怎地回去？你和我去枯树山，说了鲍旭，同去凌州，杀得单、魏二将，便好回山。”焦挺道：“凌州一府城池，许多军马在彼。我和你只两个，便有十分本事，也不济事，枉送了性命。不如且去枯树山，说了鲍旭，都去大寨入伙，此为上计。”两个正说之间，背后时迁赶将来，叫道：“哥哥忧得你苦！便请回山。如今分四路去赶你也。”李逵引着焦挺，且教与时迁厮见了。时迁劝李逵回山：“宋公明哥哥等你。”李逵道：“你且住！我和焦挺商量定了，先去枯树山说了鲍旭，方才回来。”时迁道：“使不得。哥哥等你，即便回寨。”李逵道：“你若不跟我去，你自先回山寨，报与哥哥知道。我便回也。”时迁惧怕李逵，自回山寨去了。焦挺却和李逵自投寇州来，望枯树山去了。
话分两头，却说关胜与同宣赞、郝思文，引领五千军马接来，相近凌州。且说凌州太守接得东京调兵的敕旨，并蔡太师扎付，便请兵马团练单廷圭、魏定国商议。二将受了扎付，随即选点军兵，关领军器，拴束鞍马，整顿粮草，指日起行。忽闻报说：“蒲东大刀关胜，引军到来，侵犯本州。”单廷圭、魏定国听得大怒，便收拾军马出城迎敌。两军相近，旗鼓相望。门旗下关胜出马。那边阵内鼓声响处，圣水将军出马。怎生打扮？
戴一顶浑铁打就四方铁帽，顶上撒一颗斗来大小黑缨，披一副熊皮砌就嵌缝沿边乌油铠甲，穿一领皂罗绣就点翠团花秃袖征袍，着一双斜皮踢镫嵌线云跟靴，系一条碧鞓钉就叠胜狮蛮带，一张弓，一壶箭，骑一匹深乌马，使一条黑杆枪。
前面打一把引军按北方皂纛旗，上书七个银字：“圣水将军单廷圭”。又见这边鸾铃响处，转出这员神火将军魏定国来出马。怎生打扮？
戴一顶朱红缀嵌点金束发盔，顶上撒一把扫帚长短赤缨，披一副摆连环吞兽面猊铠，穿一领绣云霞飞怪兽绛红袍，着一双刺麒麟间翡翠云缝锦跟靴，带一张描金雀画宝雕弓，悬一壶凤翎凿山狼牙箭，骑坐一匹胭脂马，手使一口熟铜刀。
前面打一把引军按南方红绣旗，上书七个银字：“神火将军魏定国”。两员虎将一齐出到阵前。关胜见了，在马上说道：“二位将军，别来久矣！”单廷圭、魏定国大笑，指着关胜骂道：“无才关胜，背反狂夫，上负朝廷之恩，下辱祖宗名目，不知死活，引军到来，有何理说？”关胜答道：“你二将差矣！目今主上昏昧，奸臣弄权，非亲不用，非仇不谈。兄长宋公明仁德施恩，替天行道。特令关某等到来，招请二位将军。倘蒙不弃，便请过来，同归山寨。”单、魏二将听得大怒，聚马齐出。一个似北方一朵乌云，一个如南方一团烈火，飞出阵前。关胜却待去迎敌，左手下飞出宣赞，右手下奔出郝思文，两对儿在阵前厮杀。刀对刀，迸万道寒光；枪对枪，起一天杀气。关胜遥见神火将越斗越精神，圣水将无半点惧色。正斗之间，两将拨转马头，望本阵便走。郝思文、宣赞随即追赶，冲入阵中。只见魏定国转入左边，单廷圭转过右边。随后宣赞赶着魏定国，郝思文追住单廷圭。且说宣赞正赶之间，只见四五百步军，都是红旗红甲，一字儿围裹将来，挠钩齐下，套索飞来，和人连马活捉去了。再说郝思文追赶单廷圭到右边，只见五百来步军，尽是黑旗黑甲，一字儿裹转来。脑后众军齐上，把郝思文生擒活捉去了。可怜二将英雄，到此翻成画饼。一面把人解入凌州，各领五百精兵，杀出阵门，却似乌云卷地，犹如烈火飞来。众军卷杀过对阵。关胜举手无措，大败输亏，望后便退。随即单廷圭、魏定国拍马在背后追来。关胜正走之间，只见前面冲出二将。关胜看时，左有林冲，右有杨志，从两肋罗里撞将出来，杀散凌州军马。关胜收住本部残兵，与林冲、杨志相见，合兵一处。随后孙立、黄信，一同见了。权且下寨。
却说水火二将捉得宣赞、郝思文，得胜回到城中。张太守接着，置酒作贺。一面教人做造陷车，装了二人，差一员偏将，带领三百步军，连夜解上东京，申达朝廷。
且说偏将带领三百人马，临押宣赞、郝思文上东京来，迤逦前行，来到一个去处，只见满山枯树，遍地芦芽。一声锣响，撞出一伙强人。当先一个，手搦双斧，声喝如雷，正是梁山泊黑旋风李逵。随即后面带着这个好汉。端的是谁？正是：
相扑丛中人尽伏，拽拳飞脚如刀毒。
劣性发时似山倒，焦挺从来没面目。
李逵、焦挺两个好汉，引着小喽啰拦住去路，也不打话，便抢陷车。偏将急待要走，背后又撞出一个好汉。正是：
狰狞鬼脸如锅底，双睛叠暴露狼唇。
放火杀人提阔剑，鲍旭名映丧门神。
这个好汉正是丧门神鲍旭，向前把偏将手起剑落，砍下马来。其余人等，撇下陷车尽皆逃命去了。
李逵看时，却是宣赞、郝思文，便问了备细来由。宣赞见李逵，亦问：“你怎生在此？”李逵说道：“为是哥哥不肯教我来厮杀，独自一个走下山来。先杀了韩伯龙，后撞见焦挺，引我在此。鲍旭一见如故，便和亲兄弟一般接待。却才商议，正欲去打凌州，只见小喽啰山头上望见这伙人马，监押陷车到来。只道是官兵捕盗，不想却是你二位。”鲍旭邀请到寨内，杀羊置酒相待。郝思文道：“兄弟既然有心上梁山泊入伙，不若将引本部人马，就同去凌州，并力攻打，此为上策。”鲍旭道：“小可与李兄正如此商议。足下之言，说的最是。我山寨之中，也有三二百匹好马。”带领五七百小喽啰，五筹好汉，一齐来打凌州。
却说逃难军士奔回来报与张太守说道：“半路里有强人夺了陷车，杀了首将。”单廷圭、魏定国听得大怒，便道：“这番拿着，便在这里施刑。”只听得城外关胜引兵搦战。单廷圭争先出马，开城门放下吊桥，引一千军马出城迎敌。门旗中飞出五百玄甲军来，到于阵前，走出一员大将，争先出马，乃是圣水将军。端的好表人物。怎生打扮？有诗为证：
凤目卧蚕眉，虬髯黑面皮。
锦袍笼獬豸，宝甲嵌狻猊。
马跨东洋兽，人擎北斗旗。
凌州圣水将，英雄单廷圭。
当下单廷圭出马，大骂关胜道：“辱国败将，何不就死！”关胜听了，舞刀拍马。两个斗不到二十余合，关胜勒转马头，慌忙便走。单廷圭随即赶将来，约赶十余里，关胜回头喝道：“你这厮不下马受降，更待何时！”单廷圭挺枪直取关胜后心。关胜使出神威，拖起刀背，只一拍，喝一声：“下去！”单廷圭落马。关胜下马、向前扶起，叫道：“将军恕罪。”单廷圭惶恐伏礼，乞命受降。关胜道：“某与宋公明哥哥面前，多曾举你。特来相招二位将军，同聚大义。”单廷圭答道：“不才愿施犬马之力，同共替天行道。”两个说罢，并马而行出来。林冲接见二人并马而行，便问其故。关胜不说输赢，答道：“山僻之内，诉旧论新，招请归降。”林冲等众皆大喜。单廷圭回至阵前，大叫一声，五百玄甲军兵一哄过来。其余人马，奔入城中去了。连忙报知太守。
魏定国听了大怒。次日，领起军马出城交战。单廷圭与同关胜、林冲，直临阵前。只见门旗开处，神火将军出马。怎生打扮？有诗为证：
朗朗明星露双目，团团虎面如紫玉。
锦袍花绣荔枝红，衬袄云铺鹦鹉绿。
行来好似火千团，部领绛衣军一簇。
世间人号神火将，此是凌州魏定国。
当时魏定国出马，见了单廷圭顺了关胜，大骂：“忘恩背主负义匹夫！”关胜大怒，拍马向前迎敌。二马相交，军器并举。两将斗不到十合，魏定国望本阵便走。关胜却欲要追，单廷圭大叫道：“将军不可去赶！”关胜连忙勒住战马。说犹未了，凌州阵内早飞出五百火兵，身穿绛衣，手执火器，前后拥出有五十辆火车，车上都满装芦苇引火之物。军人背上，各拴铁葫芦一个，内藏硫黄焰硝五色烟药，一齐点着，飞抢出来。人近人倒，马遇马伤。关胜军兵四散奔走，退四十余里扎住。
魏定国收转军马回城，看见本州烘烘火起，烈烈烟生。原来却是黑旋风李逵与同焦挺、鲍旭，带领枯树山人马，都去凌州背后，打破北门，杀入城中，放起火来，劫掳仓库钱粮。魏定国知了，不敢入城，慌速回军。被关胜随后赶上追杀，首尾不能相顾。凌州已失，魏定国只得退走，奔中陵县屯驻。关胜引军，把县四下围住。便令诸将调兵攻打。魏定国闭门不出。
单廷圭便对关胜、林冲等众位说道：“此人是一勇之夫。攻击得紧，他宁死而不辱。事宽即完，急难成效。小弟愿往县中，不避刀斧，用好言招抚此人，束手来降，免动干戈。”关胜见说大喜，随即叫单廷圭单人匹马到县。小校报知，魏定国出来相见了，邀请上厅而坐。单廷圭用好言说道：“如今朝廷不明，天下大乱，天子昏昧，奸臣弄权。我等归顺宋公明，且归水泊。久后奸臣退位，那时临朝，去邪归正，未为晚矣。”魏定国听罢，沉吟半晌，说道：“若是要我归顺，须是关胜亲自来请，我便投降。他若是不来，我宁死而不辱。”单廷圭即便上马回来，报与关胜。关胜见说，便道：“大丈夫作事，何故疑惑。”便与单廷圭匹马单刀而去。林冲谏道：“兄长，人心难忖，三思而行。”关胜道：“好汉作事无妨。”直到县衙。魏定国接着，大喜，愿拜投降。同叙旧情，设宴管待。当日带领五百火兵，都来大寨，与林冲、杨志并众头领俱各相见已了，即便收军回梁山泊来。宋江早使戴宗接着，对李逵说道：“只为你偷走下山，空教众兄弟赶了许多路。如今时迁、乐和、李云、王定六四个先回山去了。我如今先去报知哥哥，免至悬望。”
不说戴宗争先去了。且说关胜等军马回到金沙滩边，水军头领棹船接济军马，陆续过渡。只见一个人气急败坏跑将来。众人看时，却是金毛犬段景住。林冲便问道：“你和杨林、石勇去北地里买马，如何这等慌速跑来？”
段景住言无数句，话不一席，有分教：宋江调拨军兵，来打这个去处。重报旧仇，再雪前恨。正是：情知语是钩和线，从头钓出是非来。毕竟段景住对林冲等说出甚言语来，且听下回分解。', '', '', '', NULL, '', 'indent', 1537289246, '5ba0b72efb4ffe005ce67829', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10509, '石鱼湖上醉歌', NULL, 205, 102, 2, 1, '元结', NULL, 10122, '57babb92128fe1005f8da377', '唐', 'shi', '诗', 'http://baike.baidu.com/view/4613148.htm', '漫叟以公田米酿酒，因休暇则载酒于湖上，时取一醉。欢醉中，据湖岸引臂向鱼取酒，使舫载之，遍饮坐者。意疑倚巴丘酌于君山之上，诸子环洞庭而坐，酒舫泛泛然触波涛而往来者，乃作歌以长之。', '石鱼湖，似洞庭，夏水欲满君山青。
山为樽，水为沼，酒徒历历坐洲岛。
长风连日作大浪，不能废人运酒舫。
我持长瓢坐巴丘，酌饮四座以散愁。', '元结在代宗时，曾任道州刺史，其时他写了好几首吟石鱼湖的诗。他的《石鱼湖上作序》云：「泉南上有独石在水中，状如游鱼。鱼凹处，修之可以贮酒。水涯四匝，多欹石相连，石上堪人坐，水能浮小舫载酒，又能绕石鱼洄流，及命湖曰石鱼湖，镌铭於湖上，显示来者，又作诗以歌之。」有诗云：「吾爱石鱼湖，石鱼在湖里，鱼背有酒樽，绕鱼是湖水」。
此诗乃歌咏石鱼湖风景，抒发诗人淡于仕途进取，意欲归隐的胸怀。诗起首以洞庭湖作比石鱼湖，以君山作比石鱼；接着叙述在石鱼的寻欢作乐；最後说明即使有大风大浪，也不能阻止饮酒作乐，藉以忘忧。诗的格调清新自然，乘兴而发，毫无拘束，足见诗人胸襟之开阔，和及时行乐的思绪。', '漫叟：元次山自号。元次山《漫歌八曲》序：「壬寅中，漫叟得免职事，漫家樊上，修耕钓以自资，作《漫歌八曲》。」
休暇：休假。唐王子安《秋日登洪府滕王阁饯别序》：「十旬休暇，胜友如云。」
引臂：伸臂，举臂。唐白乐天《三游洞序》：「初见石如叠如削，其怪者，如引臂，如垂幢。」
「意疑」三句：写作者对石鱼湖饮酒的感受，意思是，这时我简直以为我身倚巴丘而举杯饮酒却在君山上边；又好像我的客人们都围绕洞庭湖坐着，载酒的船漂漂荡荡地冲开波涛，一来一往。巴丘：山名，在湖南岳阳县洞庭湖边。君山：山名，在洞庭湖中。洞庭：湖名，古代时是中国最大的淡水湖。泛泛：也作凡凡或汜汜，漂荡的样子。《诗经·邶风·二子乘舟》：「二子乘舟，凡凡其逝。」《楚辞·卜居》：「宁昂昂若千里之驹乎？将汜汜若水中之凫，与波上下，偷以全吾躯乎？」
长：放声歌唱。《礼记·乐记》：「歌之为言也，长言之也。」注：「长言之，引其声也。」这里是放声高歌的意思。
沼（zhǎo）：水池。
历历：分明可数。清晰貌。《古诗十九首·明月皎夜光》：「玉衡指孟冬，众星何历历。」洲岛：水中陆地。南朝宋谢灵运《入彭蠡湖口》诗：「洲岛骤回合，圻岸屡崩奔。」
废：阻挡，阻止。
酒舫（fǎng）：供客人饮酒游乐的船。宋黄庭坚《省中烹茶怀子瞻用前韵》：「但恐次山胸磊隗，终便酒舫石鱼湖。」
长瓢：饮酒器。
酌（zhuó）饮：挹取流质食物而饮。此指饮酒。
四坐：指四周座位上的人。', '我用公田产出的粮食来酿酒，常藉休假之闲，载酒到石鱼湖上，暂且博取一醉。在酒酣欢快之中，靠着湖岸，伸臂向石鱼取酒，叫船载着，使所有在座的人都痛饮。好像靠着巴陵山，而伸手向君山上舀酒一般，同游的人，也像绕洞庭湖而坐。酒舫漫漫地触动波涛，来来往往添酒。于是作了这首醉歌，歌咏此事。
湖南道州的石鱼湖，真像洞庭，夏天水涨满了，君山翠绿苍苍。
且把山谷作酒杯，湖水作酒池，酒徒济济，围坐在洲岛的中央。
管他连日狂风大作，掀起大浪，也阻遏不了，我们运酒的小舫。
我手持酒葫芦瓢，稳坐巴丘山，为四座斟酒，藉以消散那愁肠。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f092f9", "shortContent": "此诗是唐代诗人元结的作品，其山水诗有清新自然的特色。诗前序言交代写作背景，叙述作者在闲暇时分与友属来到石鱼湖上饮酒的事及作者对此事的感受。诗人写畅饮时倚岸伸臂在石鱼的凹槽中舀酒，好似是身靠着巴丘山，向君山顶舀酒，可见醉意朦胧又兴致极高，故而诗人与友人坐于载酒的小船在湖光中飘飘荡荡时，就飘然写了这首诗来赞美。此诗主要表现悠闲自在的生活，反映封建士大夫以酒为戏、借饮取乐的生活情趣。\n\n一、二句写石鱼湖...", "authors": ["阮森丽"], "pressName": "崇文书局"}]', '明代鍾退谷、谭鹄湾《唐诗归》：鍾云：道州七言古数首，几于忘情学草木矣，然直谓草木无情，则不能看元诗。
清代张絸斋《絸斋诗谈》：简而远，此境最不易到。
清代张文荪《唐贤清雅集》：不着一字，尽得风流，结处深情无限。太白所谓「泪亦不能为之堕，声亦不能为之哀」也。
清代吴煊、胡棠《唐贤三昧集笺注》：短古，奇格可爱。', 'center', 1416822583, '57b8f7f20a2b58005c920072', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10510, '山石', NULL, 123, 482, 4, 1, '韩愈', NULL, 10125, '57ba30008ac247006301a306', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/154777/9294390.htm', '', '山石荦确行径微，黄昏到寺蝙蝠飞。
升堂坐阶新雨足，芭蕉叶大栀子肥。
僧言古壁佛画好，以火来照所见稀。
铺床拂席置羹饭，疏粝亦足饱我饥。
夜深静卧百虫绝，清月出岭光入扉。
天明独去无道路，出入高下穷烟霏。
山红涧碧纷烂漫，时见松枥皆十围。
当流赤足踏涧石，水声激激风吹衣。
人生如此自可乐，岂必局束为人鞿？
嗟哉吾党二三子，安得至老不更归！', '诗题为“山石”，但并非咏山石，而是一篇诗体的山水游记。此诗按时间顺序记叙了游览惠林寺的所见所感，描绘了从黄昏至入夜再到黎明的清幽景色，抒发了作者不愿为世俗羁绊的心情。记叙时由黄昏而深夜至天明，层次分明，环环相扣，前后照应，耐人寻味。前四句写黄昏到寺之所见，点出初夏景物；“僧言”四句，是写僧人的热情接待；“夜深”二句，写山寺之夜的清幽，留宿的惬意；“天明”六句，写凌晨辞去，一路所见所闻的晨景；“人生”四句，写对山中自然美，人情美的向往。“人生如此自可乐，岂必局促为人鞿”是全诗主旨。全诗颇显韩愈“以文为诗”的特色，其突出特点是运用了赋体的“铺采摛文”手法，气势遒劲，风格壮美，数为后人所称道。', '山石：这是取诗的首句开头二字为题，乃旧诗标题的常见用法，它与诗的内容无关。此诗西窗烛版本据《韩昌黎诗系年集释》卷二。
荦（luò）确：指山石险峻不平的样子。
行径：行下次的路径。
微：狭窄。
蝙蝠：哺乳动物，夜间在空中飞翔，捕食蚊、蛾等。这是写山寺黄昏的景象并点明到寺的时间。
升堂：进入寺中厅堂。
阶：厅堂前的台阶。
新雨：刚下过的雨。
栀子：常绿灌水，夏季开白花，香气浓郁。栀，一作“支”，字同。
“升堂坐阶新雨足，芭蕉叶大栀子肥。”句：进入厅堂后坐在台阶上，这刚下过的一场雨水该有多么充足；那吸饱了雨水的芭蕉叶子更加硕大，而挺立枝头的梔子花苞也显得特别肥壮。诗人热情地赞美了这山野生机勃勃的动人景象。
佛画：画的佛画像。
所见稀：即少见的好画。稀：依稀，模糊，看不清楚。一作“珍稀”解。
“僧言古壁佛画好，以火来照所见稀。”句：和尚告诉我说，古壁上面的佛像很好，并拿来灯火观看，尚能依稀可见。
置：供。
羹（gēng）：菜汤。这里是泛指菜蔬。
疏粝（lì）：糙米饭。这里是指简单的饭食。
饱我饥：给我充饥。
百虫绝：一切虫鸣声都没有了。
清月：清朗的月光。
出岭：指清月从山岭那边升上来。夜深月出，说明这是下弦月。
光入扉（fēi）：指月光穿过门户，照时室内。扉，门。
无道路：指因晨雾迷茫，不辨道路，随意步行的意思。
出入高下：指进进出出于高高低低的山谷径路的意思。
穷烟霏：空尽云雾，即走遍了云遮雾绕的山径。霏，氛雾。
山红涧碧：即山花红艳、涧水清碧。
纷：繁盛。
烂漫：光彩四射的样子。
枥（lì）：同“栎”，落叶乔木。
十围：形容树幹非常粗大。两手合抱一周称一围。
当流：对着流水。
赤足踏涧石：是说对着流水就打起赤脚，踏着涧中石头淌水而过。
人生如此；指上面所说的山中赏心乐事。
局束：拘束，不自由的意思。
鞿（jī）：马缰绳。这里作动词用，比喻受人牵制、束缚。
吾党二三子：指和自己志趣相合的几个朋友。
安得：怎能。
不更归：不再回去了，表示对官场的厌弃。', '山石峥嵘险峭，山路狭窄像羊肠，蝙蝠穿飞的黄昏，来到这座庙堂。
登上庙堂坐台阶，刚下透雨一场，经雨芭蕉枝粗叶大，山栀更肥壮。
僧人告诉我说，古壁佛画真堂皇，用火把照看，迷迷糊糊看不清爽。
为我铺好床席，又准备米饭菜汤，饭菜虽粗糙，却够填饱我的饥肠。
夜深清静好睡觉，百虫停止吵嚷，明月爬上了山头，清辉泻入门窗。
天明我独自离去，无法辨清路向，出入雾霭之中，我上下摸索踉跄。
山花鲜红涧水碧绿，光泽又艳繁，时见松栎粗大十围，郁郁又苍苍。
遇到涧流当道，光着脚板踏石淌，水声激激风飘飘，掀起我的衣裳。
人生在世能如此，也应自得其乐，何必受到约束，宛若被套上马缰？
唉呀，我那几个情投意合的伙伴，怎么能到年老，还不再返回故乡？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c103048e64fbd91536", "shortContent": "诗以开头“山石”二字为题，却并不是歌咏山石，而是一篇叙写游踪的诗。这诗汲取了散文中有悠久传统的游记文的写法，按照行程的顺序，叙写从“黄昏到寺”、“夜深静卧”到“天明独去”的所见、所闻和所感，是一篇诗体的山水游记。在韩愈以前，记游诗一般都是截取某一侧面，选取某一重点，因景抒情。汲取游记散文的特点，详记游踪，而又诗意盎然，《山石》是有独创性的。\n按照时间顺序依次记述游踪，很容易弄成流水账。诗人手段高明...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad9820695e6503ffd3", "shortContent": "诗以开头“山石”二字为题，却并不是歌咏山石，而是一篇叙写游踪的诗。这诗汲取了散文中有悠久传统的游记文的写法，按照行程的顺序，叙写从“黄昏到寺”“夜深静卧”到“天明独去”的所见、所闻和所感，是一篇诗体的山水游记。在韩愈以前，纪游诗一般都是截取某一侧面，选取某一重点，因景抒情。汲取游记散文的特点，详记游踪，而又诗意盎然，《山石》是有独创性的。\n\n按照时间顺序依次记述游踪，很容易弄成流水账。诗人手段高明...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f092fa", "shortContent": "这是一篇汲取散文养料的写景游踪体诗歌，写得畅快淋漓，诗意盎然。一般认为写于唐德宗贞元十七年（801）夏秋间韩愈闲居洛阳时。所游者当为洛阳北面的惠林寺，同游者有李景兴、侯喜、尉迟汾。读罢全诗，读者宛如身临其境，与韩愈等人一起在空灵、宏阔的山林之中自由地游览了一番！\n\n诗人一行人走在山间的羊肠小道上，毫无郁郁不得志之感，出来了就应该完全拥抱大自然，把生命与自然相交融。不知不觉，幽暗的黄昏已经笼罩了大地...", "authors": ["叶洁洪"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706fc9ebcc6fbea1a3f8", "shortContent": "这是一篇汲取散文养料的写景游踪体诗歌，写得畅快淋漓，诗意盎然。一般认为写于唐德宗贞元十七年（801）夏秋间韩愈闲居洛阳时。所游地当为洛阳北面的惠林寺，同游者有李景兴、侯喜、尉迟汾。读罢全诗，读者宛如身临其境，与韩愈等人一起在空灵、宏阔的山林之中自由地游览了一番！\n\n诗人一行人走在山间的羊肠小道上，毫无郁郁不得志之感，出来了就应该完全拥抱大自然，把生命与自然相交融。不知不觉，幽暗的黄昏已经笼罩了大地...", "authors": ["叶洁洪"], "pressName": "崇文书局"}, {"bookId": "645d0e35e745e33de3130007", "bookTitle": "韩愈诗文鉴赏辞典", "articleId": "647acc2782772d45947ea715", "shortContent": "诗以开头“山石”二字为题，却并不是歌咏山石，而是一篇叙写游踪的诗。这诗汲取了散文中有悠久传统的游记文的写法，按照行程的顺序，叙写从“黄昏到寺”、“夜深静卧”到“天明独去”的所见、所闻和所感，是一篇诗体的山水游记。在韩愈以前，记游诗一般都是截取某一侧面，选取某一重点，因景抒情。汲取游记散文的特点，详记游踪，而又诗意盎然，《山石》是有独创性的。\n按照时间顺序依次记述游踪，很容易弄成流水账。诗人手段高明...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '黄震《黄氏日钞》：《山石》诗，清峻。
元好问《遗山先生文集·论诗三十首》：有情芍药含春泪，无力蔷薇卧晚枝。拈出退之《山石》句，始知渠是女郎诗。
瞿佑《归田诗话》：元遗山《论诗三十首》，内一首云：“有情芍药含春泪……”初不晓所谓。后见《诗文自警》一编，亦遗山所着，谓“有情芍药含舂泪，无力蔷薇卧晚枝”，此秦少游《春雨》诗也，非不工巧，然以退之《山石》句观之，渠乃女郎诗也。破却工夫，何至作女郎诗？按昌黎诗云：“山石荦确行径微……芭蕉叶大栀子肥。”遗山固为此论，然诗亦相题而作，又不可拘以一律。如老杜云：“香雾云鬟湿，清辉玉臂寒”；“具飞蛱蝶元相逐，并蒂芙蓉本自双”，亦可谓女郎诗耶？
陆时雍《唐诗镜》：语如清流啮石，激激相注。李、杜虚境过形，昌黎当境实写。
冯时可《雨航杂录》：此诗叙游如画如记，悠然澹然，在《古剑》篇诸作之上。余尝以雨夜入山寺，良久月出，深忆公诗之妙。其“嗟哉吾党”二句，后人添入、非公笔也。
何焯《义门读书记》：直书即目，无意求工，而文自至，一变谢家模范之迹，如画家之有荆、关也。从晦中转到明（“清月出岭”句下）。“穷烟霏”三字是山中平明真景。从明中仍带晦，都是雨后兴象。又即发端“荦确”、“黄昏”二句中所包蕴也（“出入高下”句下）。顾“雨足”（“当流赤足”句下）。
查慎行《初白庵诗评》：意境俱别。查晚晴曰：写景无意不刻、无语不僻。取径无处断，无意不转。屡经荒山古寺来，读此始愧未曾道着只字，已被东坡翁攫之而趋矣。
汪森《韩柳诗选》：句烹字炼而无雕琢之迹，缘其于淡中设色，朴处生姿耳。七言古诗，唐初多整丽之作，大抵前句转韵，音调铿锵，然自少陵始变为生拗之体，而公诗益畅之，意境为之一换。
《唐宋诗醇》：“以火来照所见稀”，与《岳庙作》“神纵欲福难为功”略同，于法则随手撇脱，于意则素所不满之事，即随处自然流露也。顾嗣立曰：七言古诗易入整丽，而亦近平熟，自老杜始为拗体，如《杜鹃行》之类。公之七言皆祖此种，而中间偏有极鲜丽处，不事雕琢，更见精采，有声有色，自公大家。
袁枚《随园诗话》：元遗山讥秦少游云：“有情芍药含春泪……”此论大谬。芍药、蔷薇，原近女郎，不近山石，二者不可相提而并论。诗题各有境界，各有宜称。杜少陵诗光焰万丈，然而“香雾云鬤湿，清辉玉臂寒”，“分飞蛱蝶原相逐，并蒂芙蓉本是双”；韩退之诗“横空盘硬语”，然“银烛未销窗送曙，金钗半醉坐添春”，又何尝不是“女郎诗”耶？《东山》诗：“其新孔嘉，其旧如之何？”周公大圣人，亦且善谑。
张文荪《唐贤清雅集》：寓潇洒于浑劲，昌黎七古最近人之作。昌黎诗体占奥奇横，自辟户庭，此种清而厚、丽而逸，亦公独得妙境，后惟山谷能学之，其笔力正相肖。
《古诗选批》：全以劲笔撑空而出，若句句提笔者。
方东树《昭味詹言》：凡结句都要不从人间来，乃为匪夷所思，奇险不测。他人百思所不解，我却如此结，乃为我之诗。如韩《山石》是也。不然，人人胸中所可有，手笔所可到，是为凡近。不事雕琢，自见精彩，真大家手笔。许多层事，只起四语了之。虽是顺叙，却一句一样境界，如展画图，触目通层在眼，何等笔力！五句、六句又一画。下句又一画。“天明”六句，共一幅早行图画。收入议。从昨日追叙，夹叙夹写，情景如见，句法高古。只是一篇游记，而叙写简妙，犹是古文手笔。他人数语方能明者，此须一句，即全现出，而句法复如有馀地，此为笔力。
刘熙载《艺概》：昌黎诗陈言务去，故有倚天拔地之意。《山石》一作，辞奇意幽，可为《楚辞·招隐士》对，如柳州《天对》例也。
程学恂《韩诗臆说》：李、杜《登太山》、《梦天姥》、《望岱》、《西岳》等篇，皆浑言之，不尽游山之趣也，故不可一例论。子瞻游山诸作，非不快妙，然与此比并，便觉小耳，此惟子瞻自知。
《说韩》：“山石荦确行径微”一篇，此尽人所称道者也。学昌黎者，亦惟此稍易近，缘与他家诗境近也。
汪佑南《山泾草堂诗话》：是宿寺后补作。以首二字“山石”标题，此古人通例也。“山石”四句，到寺即景。“僧言”四句，到寺后即事。“夜深”二句，宿寺写景。“天明”六句，出寺写景。“人生”四句，写怀结。通体写景处，句多浓丽；即事写怀，以淡语出之。浓淡相间，纯任自然，似不经意，而实极经意之作也。
吴学濂《增评韩苏诗钞》：三溪曰：起笔四句细写山寺荒凉景况，刻画逼真。前半篇极沈厚笔，下半篇极用平淡笔，正是浓淡相极、险夷并行之作法。茶山云结句气似衰杀，今按结意，自出题外，全不觉衰杀，是适茶山所不好耳。', 'center', 1416822780, '57b8e1daa633bd00665ca663', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10511, '八月十五夜赠张功曹', NULL, 82, 482, 1, 2, '韩愈', NULL, 10125, '57ba30008ac247006301a306', '唐', 'shi', '诗', 'http://baike.baidu.com/view/350132.htm', '', '纤云四卷天无河，清风吹空月舒波。
沙平水息声影绝，一杯相属君当歌。
君歌声酸辞且苦，不能听终泪如雨。
洞庭连天九疑高，蛟龙出没猩鼯号。
十生九死到官所，幽居默默如藏逃。
下床畏蛇食畏药，海气湿蛰熏腥臊。
昨者州前捶大鼓，嗣皇继圣登夔皋。
赦书一日行万里，罪从大辟皆除死。
迁者追回流者还，涤瑕荡垢清朝班。
州家申名使家抑，坎轲只得移荆蛮。
判司卑官不堪说，未免捶楚尘埃间。
同时辈流多上道，天路幽险难追攀。
君歌且休听我歌，我歌今与君殊科：
一年明月今宵多，人生由命非由他，
有酒不饮奈明何？', '此诗表达的是诗人对人生的感慨，以一种无可奈何的心情，用「人生由命」的宿命观慰藉友人，并自我解嘲。开首四句，恰似序文，铺叙环境：清风明月，万籁俱寂；接着写张署所歌内容：叙述谪迁之苦，宦途险恶，令人落泪；最後写「我歌」，却衹写月色，人生有命，应藉月色开怀痛饮等等，故作旷达。明写张功曹谪迁赦回经历艰难，实则自述同病相怜之困苦。笔调近似散文，语言古朴，直陈其事。诗中写「君歌」「我歌」和衷共诉，尽致淋漓。全诗抑扬开阖，波澜曲折，音节多变，韵脚灵活，既雄浑恣肆，又宛转流畅，极好地表达了诗人感情的变化。', '纤云：微云。
河：银河。
月舒波：月光四射。
属（zhǔ）：劝酒。
洞庭：洞庭湖。
九疑：又名苍梧山，在今湖南宁远县境。
猩：猩猩。
鼯（wú）：鼠类的一种。
如藏逃：有如躲藏的逃犯。
药：指蛊毒。南方人喜将多种毒虫放在一起饲养，使之互相吞噬，最后剩下的毒虫叫做蛊，制成药后可杀人。
海气：卑湿的空气。
蛰：潜伏。
嗣皇：接着做皇帝的人，指宪宗。
登：进用。
夔皋：夔和皋陶，传说是舜的两位贤臣。
赦书：皇帝发布的大赦令。
大辟：死刑。
除死：免去死刑。
迁者：贬谪的官吏。
流者：流放在外的人。
瑕：玉石的杂质。
班：臣子上朝时排的行列。
州家：刺史。
申名：上报名字。
使家：观察使。
抑：压制。
坎轲：这里指命运不好。
荆蛮：今湖北江陵。
判司：唐时对州郡诸曹参军的总称。
捶楚：棒杖一类的刑具。
上道：上路回京。
天路：指进身于朝廷的道路。
幽险：幽昧险碍。
殊科：不一样，不同类。', '薄云四处飘散还不见银河，清风吹开云雾月光放清波。
沙滩里水平波息声影消失，斟杯美酒相劝请你唱支歌。
你的歌声酸楚歌辞也悲苦，没有听完热泪就纷纷下落。
洞庭湖水连天九疑山高峻，湖中的蛟龙出没猩鼯哀号。
九死一生到达这被贬官所，默默地幽居远地好像潜逃。
下床怕蛇咬吃饭又怕毒药，潮气与毒气相杂到处腥臊。
昨日州衙前忽然擂动大鼓，新皇继位要举用夔和皋陶。
大赦文书一日万里传四方，犯有死罪的一概免除死刑。
被贬谪的召回放逐的回朝，革除弊政要剪除朝中奸佞。
刺史提名赦免观察使扣压，命运坎坷衹能够迁调荒漠。
判司原本是小官不堪一提，未免跪地挨打有苦向谁说。
一起被贬谪的大都已回京，进身朝廷之路比登天难攀。
你的歌声暂且停止听我唱，我的歌声和你绝不是同科。
一年的明月今夜月色最好，人生由命又何必归怨其他，
有酒不饮怎对得天上明月？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c12cee9a0c24ecf983", "shortContent": "这首诗以接近散文的笔法，古朴的语言，直陈其事，不用譬喻，不用寄托，主客互相吟诵诗句，一唱一和，我中有你，你中有我，衷情共诉，洒脱疏放，别具一格。\n诗里写了张署的“君歌”和作者的“我歌”。题为“赠张功曹”，却没有以“我歌”作为描写的重点，而是反客为主，把“君歌”作为主要内容，借张署之口，淋漓尽致地抒发了诗人自己的块垒不平。\n诗的前四句描写八月十五日夜主客对饮的环境，如文的小序：碧空无云，清风明月，万...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f092fb", "shortContent": "从诗题来看，此诗为韩愈题赠好友张署的一首赠诗。其时诗人与张署谪居异乡，时逢八月中秋，两人举杯对饮，诗人联想到彼此遇赦回归受阻的政治困境与人生理想的缥缈无根，不禁感慨良多，夜不能寐，遂成此篇。宋人黄震《黄氏日钞》评此诗“感慨多兴”，此诗之“兴”，正在于抒发一种世事无常与天涯飘零的苦闷情绪。\n\n开篇即以大气磅礴之笔，着意渲染作者所处洞庭湖之优美情境。\n\n在烟波浩渺的洞庭湖上，远处的薄云四处飘散，不见银...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706d9761253910e9054e", "shortContent": "从诗题来看，此诗为韩愈题赠好友张署的一首赠诗。其时诗人与张署谪居异乡，时逢八月中秋，两人举杯对饮，诗人联想到彼此遇赦回归受阻的政治困境与人生理想的缥渺无根，不禁感慨良多，夜不能寐，遂成此篇。宋人黄震《黄氏日钞》评此诗“感慨多兴”，此诗之“兴”，正在于抒发一种世事无常与天涯飘零的苦闷情绪。\n\n开篇即以大气磅礴之笔，着意渲染作者所处洞庭湖之优美情境。在烟波浩渺的洞庭湖上，远处的薄云四处飘散，不见银河；...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645d0e35e745e33de3130007", "bookTitle": "韩愈诗文鉴赏辞典", "articleId": "647acd8482772d45947eaf82", "shortContent": "这首诗以接近散文的笔法，古朴的语言，直陈其事，不用譬喻，不用寄托，主客互相吟诵诗句，一唱一和，我中有你，你中有我，衷情共诉，洒脱疏放，别具一格。\n诗里写了张署的“君歌”和作者的“我歌”。题为“赠张功曹”，却没有以“我歌”作为描写的重点，而是反客为主，把“君歌”作为主要内容，借张署之口，淋漓尽致地抒发了诗人胸中的块垒。\n诗的前四句描写八月十五日夜主客对饮的环境，如文的小序：碧空无云，清风明月，万籁俱...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}]', '《苕溪渔隐丛话後集》：《昌黎集》中，酬赠张十一功曹署诗颇多，而署诗绝不见，惟《韩子年谱》载其一篇，云：「九疑峰畔二江前，恋阙思乡日抵年。简趋朝曾并命，苍梧左宦亦联翩。鲛人远泛渔舟火，鹏鸟闲飞雾里天。涣汗几时流率土，扁舟西下共归田。」署与退之同为御史，又同迁滴，故诗中皆言之。退之答署诗云：「山净江空水见沙，哀猿啼处两三家。筼筜竞长纤纤笋，踯躅初开艳艳花。未报恩波知死所，莫令炎瘴送生涯。吟君诗罢看双鬓，斗觉霜毛一半加。」又有祭署文云：「我落阳山，君飘临武。君止于县，我又南逾。」临武属郴州，在阳山之北。二诗皆此时作也。
《韩文考异》：言张之歌同酸苦，而己直归之于命，盖反《骚》之意，而其词气抑扬顿挫，正一篇转换用力处也（「我歌今与」句下）。
《黄氏日钞》：《八月十五夜赠张功曹》，感慨多兴。
《竹庄诗话》：《集注》云：公与张曙以贞元二十一年二月赦自南方，俱徙掾江陵。至是俟命于郴，而作是诗，怨而不乱，有《小雅》之风。
《唐诗镜》：每读昌黎七言古诗，觉有飞舞翔翥之势。
《批韩诗》：朱竹垞曰：写景语净（「沙平水息」句下）。藉张作宾主，又藉歌分悲乐，总是抑人扬己（「我歌今与」句下）。汪琬曰：虚者实之，实者虚之，得反客为主之法。观起结自知。
《初白菴诗评》：用意在起结，中间不过述迁谪最移之苦耳。
《韩柳诗选》：起结清旷超脱，是太白风度，然亦从楚《骚》变来。
《声调谱拾遗》：纯用古调，无一联是律者，转韵亦极变化。
《古诗选批》：韩诗七古之最有停蓄顿折者。
《昭昧詹言》：一篇古文章法。前叙，中间以正意苦语重语作宾，避实法也。一线言中秋，中间以实为虚，亦一法也。收应起，笔力转换。
《求阙斋读书录》：自「洞庭连天」至「难追攀」句，皆张署之歌词。末五句，韩公之歌词。
《十八家诗钞》：顾侠君曰：起即嵇叔夜「微风清扇，云气四除，皎皎亮月，丽于高隅」意，而兴象尤清旷。
《增评韩苏诗钞》：三溪曰：声清句稳，无一点尘滓气，可谓不食人间烟火矣。
《评注韩昌黎诗集》：用韵殊变化，首尾极轻清之致，是以圆巧胜皆，集中亦不多见。
《韩诗臆说》：此诗料峭悲凉，源出楚《骚》。入後换调，正所谓一唱三叹有遗音者矣。
《唐宋诗举要》：吴北江曰：写哀之词，纳入客语，运实于虚（「海气湿蛰」句下）。一句中顿挫（「州家申名」句下）。此转尤胜（「天路幽险」句下）。高阆仙曰：以上代张署歌辞。贬谪之苦，判司之移，皆于张歌同出之，所谓避实法也（「天路幽险」句下）。以上韩公歌辞。高朗雄秀，情韵兼美（末句下）。', 'center', 1416822853, '57b91195c4c97100558fb0c7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10512, '谒衡岳庙遂宿岳寺题门楼', NULL, 43, 482, 1, 1, '韩愈', NULL, 10125, '57ba30008ac247006301a306', '唐', 'shi', '诗', 'http://baike.baidu.com/view/350136.htm', '或无“庙”字。《尔雅》：“霍山为南岳。”一名衡山。公前后两谪南方。初自阳山北还过衡，在八月，至潭适当残秋。诗云：“我来正逢秋雨节。”故知此诗自阳山还时永贞元年秋作也。后自潮州移刺袁州，则元和十五年十月，非秋雨节时也。东坡《潮州庙碑》云：“公之精诚，能开衡山之云。”即此诗意。', '五岳祭秩皆三公，四方环镇嵩当中。
火维地荒足妖怪，天假神柄专其雄。
喷云泄雾藏半腹，虽有绝顶谁能穷。
我来正逢秋雨节，阴气晦昧无清风。
潜心默祷若有应，岂非正直能感通。
须臾静扫众峰出，仰见突兀撑青空。
紫盖连延接天柱，石廪腾掷堆祝融。
森然魄动下马拜，松柏一径趋灵宫。
粉墙丹柱动光彩，鬼物图画填青红。
升阶伛偻荐脯酒，欲以菲薄明其衷。
庙令老人识神意，睢盱侦伺能鞠躬。
手持杯珓导我掷，云此最吉余难同。
窜逐蛮荒幸不死，衣食才足甘长终。
侯王将相望久绝，神纵欲福难为功。
夜投佛寺上高阁，星月掩映云朣朦。
猿鸣钟动不知曙，杲杲寒日生于东。', '此诗叙写作者谒祭衡山庙神、占卜吉凶和投宿庙寺等情况，抒发对仕途坎坷的不满情怀。全诗融写景、叙事、抒情于一体，然章法井然，境界开阔，色彩浓重，古朴苍劲，且一韵到底，一气呵成，给人一种清新开阔的美感。', '谒：拜见。衡岳：南岳衡山，在今湖南。
祭秩：祭祀仪礼的等级次序。
三公：周朝的太师、太傅、太保称三公，以示尊崇，后来用作朝廷最高官位的通称。
五岳祭秩皆三公：《礼记》：“天子祭天下名山大川，五岳视三公秩次也。”皆，一作“比”，非是。
“四方环镇嵩当中。”句：是说东、西、南、北四岳各镇中国一方，环绕着中央的中岳嵩山。《白虎通》曰：“嵩山夹居四方之中，故曰‘嵩’。”
火维：古代五行学说以木、火、水、金、土分属五方，南方属火，故火维属南方。维，隅落。
假：授予。
柄：权力。
穷：穷尽，这里用作动词。
秋雨节：韩愈登衡山，正是南方秋雨季节。
晦昧：阴暗无光。
清：一作“晴”。
“潜心默祷若有应”句：暗自在心里默默祈祷天气转晴，居然有所应验。
正直能感通：《诗经·小雅·北山之什》：“靖共尔位，正直是与。神之听之，式穀以女。”
静扫：形容清风吹来，驱散阴云。
众峰：衡山有七十二峰。
突兀：高峰耸立的样子。
青：一作“晴”。
“紫盖连延接天柱，石廪腾掷堆祝融。”两句：衡山有五大高峰，即紫盖峰、天柱峰、石廪峰（一名石囷峰）、祝融峰、芙蓉峰，这里举其四峰，写衡山高峰的雄伟。苏东坡《登州观海市》诗云：“潮阳太守南迁归，喜见石廪堆祝融。”《过太行诗序》云：“予南迁其必返乎！此退之登衡山之祥也。”意皆本此。腾掷，形容山势起伏。
森然：敬畏的样子。
魄动：心惊的意思。
拜：拜谢神灵应验。
松柏一径：一路两旁，都是松柏。柏，一作作“桂”。
趋：朝向。
灵宫：指衡岳庙。
丹柱：红色的柱子。
动光彩：光彩闪耀。
“鬼物图画填青红”句：墙上和柱子上画满了彩色的鬼怪图形。
伛偻（yǔlǚ）：驼背，这里形容弯腰鞠躬，以示恭敬。
荐：进献。
脯（fǔ）酒：祭神的供品。脯，肉乾。
菲薄：微薄的祭品。
明其衷：出自内心的诚意。
庙令：官职名。唐代五岳诸庙各设庙令一人，掌握祭神及祠庙事务。令，一作“内”。
识神意：懂得神的意旨。
睢盱（suīxū）：仰視貌，抬起头来、睁大眼睛看。《列子》：“老子而睢睢而盱盱。”
侦伺：形容注意察言观色。
杯珓（jiào）：古时的一种卜具。珓：方从唐本作“校”。云《广韵》作“珓”，谓古者以玉为之也。《朝野佥载》作“角”，“角”与“校”音义皆相近。魏野有《咏竹校子》诗，只作“校”字。《荆楚岁时记》又作“教”。今按：当从《广韵》及众本。
余难同：其他的卦象都不能相比。
“手持杯珓导我掷，云此最吉余难同。”句：是指庙令教韩愈占卜，并断定占到了最吉利的兆头。
窜逐蛮荒：流放到南方边荒地区。
甘长终：甘愿如此度过馀生。
“侯王将相望久绝，神纵欲福难为功。”句：封侯拜相，这种追求功名富贵的愿望久已断绝，即使神灵要赐给我这样的福禄，也不行了。纵，即使；难为功，很难做成功。
高阁：即诗题中的“门楼”。《扁鹊传》：“长终而不得返。”
朣朦：月光隐约的样子。《文选·秋兴赋》：“月朣朦而含光。”从日者非。今按：《广韵》：朣字只有从日，无从月者。朣朦，本日出貌，然前辈月诗多用之。如梁孝绰《月诗》“朣朦入床簟”之类也。更当考。
钟动：古代寺庙打钟报时，以便作息。
“猿鸣钟动不知曙”句：猿鸣钟响，不知不觉天已亮了。
杲（gǎo）杲：形容日光明亮。《诗经·国风·卫风·伯兮》：“杲杲出日。”', '祭五岳典礼如同祭祀三公，五岳中四山环绕嵩山居中。
衡山地处荒远多妖魔鬼怪，上天授权南岳神赫赫称雄。
半山腰喷泄云雾迷迷茫茫，虽然有绝顶谁能登上顶峰。
我来这里正逢秋雨绵绵时，天气阴暗没有半点儿清风。
心里默默祈祷仿佛有应验，岂非为人正直能感应灵通？
片刻云雾扫去显出众峰峦，抬头仰望山峰突兀插云空。
紫盖峰绵延连接着天柱峰，石廪山起伏不平连着祝融。
严森险峻惊心动魄下马拜，沿着松柏小径直奔神灵宫。
粉色墙映衬红柱光彩夺目，壁柱上鬼怪图画或青或红。
登上台阶弯腰奉献上酒肉，想借菲薄祭品表示心虔衷。
主管神庙老人能领会神意，凝视窥察连连地为我鞠躬。
手持杯蛟教导我掷占方法，说此卜兆最吉他人难相同。
我被放逐蛮荒能侥幸不死，衣食足甘愿在此至死而终。
做侯王将相的欲望早断绝，神纵使赐福于我也难成功。
此夜投宿佛寺住在高阁上，星月交辉掩映山间雾朦胧。
猿猴啼时钟响不觉到天亮，东方一轮寒日冉冉升高空。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c12cee9a0c24ecf984", "shortContent": "贞元十九年（803），京畿大旱。韩愈因上书请宽民徭，被贬为连州阳山（今属广东）令。永贞元年（805）遇大赦，离阳山到郴州（治今湖南郴州）待命。九月，由郴州赴江陵府（治今湖北荆州）任法曹参军，途中游衡山时写下这首诗。诗中深沉地抒发了他对仕途坎坷的不满情怀。\n衡山耸立在湖南衡阳盆地北端，气势雄伟。山上的衡岳庙，是游人向往的名胜。诗的开头六句，写衡岳的形势和气象，起笔高远，用语不凡。先总叙五岳，再专叙衡...", "authors": ["吴文治"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f092fc", "shortContent": "贞元十九年（803），京畿大旱，饿殍遍地。韩愈上书皇帝，请宽民徭，触犯唐德宗及权贵，被贬为连州阳山（今属广东清远）令。永贞元年（805）遇大赦，离阳山到郴州（今湖南郴县）待命。九月，由郴州赴江陵府（今湖北江陵）任法曹参军，途中游衡山时写下这首诗。\n\n诗人借景抒情、托物言志，通过仰望衡岳诸峰、谒祭衡岳庙神、占卜仕途吉凶和投宿庙寺高阁等情况的叙写，抒发了个人的深沉感慨，一方面为自己投身蛮荒之地终于活着...", "authors": ["阮森丽"], "pressName": "崇文书局"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "64733f0d45e471005600fc0d", "shortContent": "贞元十九年（803），京畿大旱。韩愈因上书请宽民徭，被贬为连州阳山（今属广东）令。永贞元年（805）遇大赦，离阳山到郴州（今湖南郴县）待命。九月，由郴州赴江陵府（今湖北江陵）任法曹参军，途中游衡山时写下这首诗。诗中深沉地抒发了他因仕途坎坷而萌生的不满情怀。\n\n衡山耸立在湖南衡阳盆地北端，气势雄伟。山上的衡岳庙，是游人向往的名胜。诗的开头六句，写衡岳的形势和气象，起笔高远，用语不凡。先总叙五岳，再专...", "authors": ["吴文治"], "pressName": "上海辞书出版社"}, {"bookId": "645d0e35e745e33de3130007", "bookTitle": "韩愈诗文鉴赏辞典", "articleId": "647acde8c98d685fd9d5927b", "shortContent": "贞元十九年（803），京畿大旱。韩愈因上书请宽民徭，被贬为连州阳山（今属广东）令。永贞元年（805）遇大赦，离阳山到郴州（治今湖南郴州）待命。九月，由郴州赴江陵府（治今湖北荆州）任法曹参军，途中游衡山时写下这首诗。诗中深沉地抒发了他对仕途坎坷的不满情怀。\n衡山耸立在湖南衡阳盆地北端，气势雄伟。山上的衡岳庙，是游人向往的名胜。诗的开头六句，写衡岳的形势和气象，起笔高远，用语不凡。先总叙五岳，再专叙衡...", "authors": ["吴文治"], "pressName": "上海辞书出版社"}]', '《对床夜语》：《谒衡岳庙》：“手持杯珓导我掷，云此最吉余难同。”下三字似平趁韵，而实有工于押韵者。
《黄氏日钞》：《谒衡岳祠》，恻怛之忱，正直之操，坡老所谓“能开衡山之云”者也。
《滹南诗话》：退之《谒衡岳》诗云：“手持杯投导我掷，云此最吉余难同。”“吉”字不安，但言灵应之意可也。
《唐诗镜》：语如凿翠。
《批韩诗》：朱彝尊曰：二语朗快（“须臾静扫”二句下）。此下须用虚景语点注，似更活。今却用四峰排一联，微觉板实（“紫盖连延”二句下）。汪琬曰：起势雄杰（“天假神柄”句下）。
《义门读书记》：顶上“云雾”（“我来正逢”句下）。顶上“绝顶”（“紫盖连延”句下）。顶上“穷”字（“松柏一径”句下）。顾“阴晦”（“星月掩映”句下）。反照“阴气”（末句下）。
《寒厅诗话》：韩昌黎诗句句有来历，而能务去陈言者，全在于反用。……《岳庙》诗，本用谢灵运“猿动诚知曙”句，偏云“猿鸣钟动不知曙”，此等不可枚举。学诗者解得此秘，则臭腐化为神奇矣。
《唐诗别裁》：“横空盘硬语，妥帖力排奡”，公诗足当此语。
《七言诗平仄举隅》：此始以句句第五字用平矣，是阮亭先生所讲七言平韵到底之正调也。盖七古之气局，至韩、苏而极其致尔。
《老生常谈》：昌黎《谒衡岳庙》诗，读去觉其宏肆中有肃穆之气，细看去却是文从字顺，未尝矜奇好怪，如近人论诗所谓说实话也。后人遇此大题目，便以哏涩堆砌为能，去古日远矣。“王侯将相”二句，启后来东坡一种，苏出于韩，此类是也。然苏较韩更觉浓秀凌跨，此之谓善于学古，不似后人依样葫芦。
《昭昧詹言》：庄起陪起。此典重大题，首以议为叙，中叙中夹写，意境词句俱奇创，以己收。凡分三段，“森然”句奇纵。
《养一斋诗话》：退之诗“我能屈曲自世间，安能随汝巢神山”，“王侯将相念久绝，神纵欲福难为功”，高心劲气，千古无两，诗者心声，信不诬也。同时惟东野之古骨，可以相亚，故终身推许，不遗馀力。虽柳子厚之诗，尚不引为知己，况乐天、梦得耶！
《增评韩苏诗钞》：三溪曰：一篇登岳，有韵记文，读者不觉为有韵语，盖以押韵自在，句无强押也。
《韩诗臆说》：七古中此为第一。后来惟苏子瞻解得此诗，所以能作《海市》诗。“潜心默祷若有应，岂非正直能感通？”曰“若有应”，则不必真有应也。我公至大至刚，浩然之气，忽于游嬉中无心现露。“庙令老人识神意”数语，纯是谐谑得妙。末云“王侯将相望久绝，神纵欲福难为功”，我公富贵不能移，威武不能屈之节操，忽于嬉笑中无心现露。公志在传道，上接孟子，即《原道》及此诗可证也。文与诗义自各别，故公于《原道》、《原性》诸作，皆正言之以垂教也。而于诗中多谐言之以写情也。即如此诗，于阴云暂开，则曰：此独非吾正直之所感乎？所感仅此，则平日之不能感者多矣。于庙祝妄祷，则曰我已无志，神安能福我乎？神且不能强我，则平日之不能转移于人可明矣。然前则托之开云，后则以谢庙祝、皆跌宕游戏之词，非正言也。假如作言志诗，云我之正直，可感天地，世之勋名，我所不屑，则肤阔而无昧矣。读韩诗与读韩文迥别，试按之，然否？
《山泾草堂诗话》：竹咤批（按指朱彝尊评“紫盖连延”二句语），余意不谓然。是登绝顶写实景，妙用“众峰出”领起。盖上联虚，此联实，虚实相生。下接“森然魄动”句，复虚写四峰之高峻，的是占诗神境。朗诵数过，但见其排荡，化堆垛为烟云，何板实之有？首六句从五岳落到衡岳，步骤从容，是典制题开场大局面，领起游意。“我来正逢”十二句，是登衡岳至庙写景。“升阶伛偻”六句叙事。“窜逐蛮荒”四句写怀。“夜投佛寺”四句结宿意。精警处在写怀四句。明哲保身，是圣贤学问，隐然有敬鬼神而远之意。庙令老人，目为寻常游客，宁非浅视韩公？
《唐宋诗举要》：吴曰：此东坡所谓“能开衡山之云”者，最足见公之志节。此诗质健，乃韩公本色。', 'center', 1416839951, '57b9b7f58ac2470063fedb84', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10514, '韩碑', NULL, 46, 603, 0, 1, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383195.htm', '', '元和天子神武姿，彼何人哉轩与羲。
誓将上雪列圣耻，坐法宫中朝四夷。
淮西有贼五十载，封狼生貙貙生罴。
不据山河据平地，长戈利矛日可麾。
帝得圣相相曰度，贼斫不死神扶持。
腰悬相印作都统，阴风惨澹天王旗。
愬武古通作牙爪，仪曹外郎载笔随。
行军司马智且勇，十四万众犹虎貔。
入蔡缚贼献太庙，功无与让恩不訾。
帝曰汝度功第一，汝从事愈宜为辞。
愈拜稽首蹈且舞：金石刻画臣能为。
古者世称大手笔，此事不系于职司。
当仁自古有不让，言讫屡颔天子颐。
公退斋戒坐小阁，濡染大笔何淋漓。
点窜尧典舜典字，涂改清庙生民诗。
文成破体书在纸，清晨再拜铺丹墀。
表曰臣愈昧死上，咏神圣功书之碑。
碑高三丈字如斗，负以灵鳌蟠以螭。
句奇语重喻者少，谗之天子言其私。
长绳百尺拽碑倒，粗砂大石相磨治。
公子斯文若元气，先时已入人肝脾。
汤盘孔鼎有述作，今无其器存其辞。
呜呼圣王及圣相，相与烜赫流淳熙。
公之斯文不示后，曷与三五相攀追。
愿书万本颂万过，口角流沫右手胝。
传之七十有二代，以为封禅玉检明堂基。', '宪宗元和十二年（817），宰相裴度率兵平定淮西，但首先破蔡州生擒叛者吴元济的是大将李愬。宪宗命韩愈撰《平淮西碑》时，韩主要是突出了裴度在执行宪宗旨意后的运筹帷幄，引起李愬不满。愬妻（唐安公主之女）进宫诉说碑文不实，宪宗就命翰林学士段文昌重新撰文勒石，观点迥然不同。李商隐完全赞同韩愈的观点，诗中强烈地表达以对《韩碑》被磨去的愤慨，热情地歌颂了这篇碑文，含蓄的批判了李愬自私自利的行为。', '元和：唐宪宗年号。
轩、羲：轩辕、伏羲氏，代表三皇五帝。
列圣：前几位皇帝。
法宫：君王主事的正殿。
四夷：泛指四方边地。
淮西有贼：指盘踞蔡州的藩镇势力。
封狼：大狼。
貙（chū）、罴（pí）：野兽，喻指叛将。
日可麾：用鲁阳公与韩人相争援戈挥日的典故。此喻反叛作乱。麾，通“挥”。
度：即裴度。
都统：招讨藩镇的军事统帅。
天王旗：皇帝仪仗的旗帜。
愬（sù）武古通：愬，李愬；武，韩公武；古，李道古；通，李文通，四人皆裴度手下大将。
仪曹外郎：礼部员外郎李宗闵。
行军司马：指韩愈。
虎貔（pí）：猛兽。喻勇猛善战。
蔡：蔡州。
贼：指叛将吴元济。
无与让：即无人可及。
不訾（zī）：即“不赀”，不可估量。
从事：州郡官自举的僚属。
愈：韩愈。
为辞：指撰《平淮西碑》。
稽（qǐ）首：叩头。
蹈且舞：指古代臣子朝拜皇帝时手舞足蹈的一种礼节。
金石刻画：指为钟鼎石碑撰写铭文。
大手笔：指撰写国家重要文告的名家。
职司：指掌管文笔的翰林院。
屡颔天子颐：使皇帝多次点头称赞。颐，指面颊。
公：指韩愈。
斋戒：沐浴更衣。
濡染：浸沾。
点窜：同涂改为运用的意思。
尧典、舜典：《尚书》中篇名。
清庙、生民：《诗经》中篇名。
破体：指文能改变旧体，另一说为行书的一种。
丹墀（chí）：宫中红色台阶。
昧死：冒死，上书用谦语。
圣功：指平定淮西的战功。
灵鳌：驭负石碑的，形似大龟。
蟠（pán）以螭（chī）：碑上所刻盘绕的龙类饰纹。
喻：领悟，理解。
谗：进言诋毁。
拽：用力拉。
磨治：指磨去碑上的刻文。
斯文：此文。
若：像。
元气：无法消毁的正气。
汤盘：商汤浴盆，《史记正义》：“商汤沐浴之盘而刻铭为戒”。
孔鼎：孔子先祖正考夫鼎。此以汤盘、孔鼎喻韩碑。
相与：相互。
赫：显耀。
淳熙：鲜明的光泽。
曷（hé）：何，怎么。
书：抄写。
胝（zhī）：因磨擦而生厚皮，俗称老茧。
明堂基：明堂的基石。', '元和天子禀赋神武英姿，可比古来的轩辕、伏羲。他立誓要洗雪历代圣王的耻辱，坐镇皇宫接受四夷的贡礼。淮西逆贼为祸五十年，割据一方世代绵延。自恃强大，不去占山河却来割据平地；梦想挥戈退日，胆敢反叛作乱。
圣君得到贤相名叫裴度，逆贼暗杀未成，自有神灵卫护。他腰悬相印，统兵上战场，天子的军旗在寒风中飘扬。得力的将官有、武、古、通，仪曹外郎任书记随军出征；还有那智勇双全的行军司马韩愈，十四万大军，龙腾虎跃陷阵冲锋。攻下了蔡州，擒住叛贼献俘太庙，功业盖世皇上加恩无限；天子宣布裴度功劳第一，命令韩愈撰写赞辞。
韩愈在朝堂拜舞行礼接受诏命说歌功的文章他能够胜任。从来撰述都推崇大手笔，此事本不属佐吏的职司；既然自古有当仁不让的箴言，韩愈欣然领受圣上的旨意。天子听完这番言辞，频频点头大加赞许。韩公退朝后斋戒沐浴坐于小阁，笔蘸饱墨挥洒淋漓。推敲《尧典》《舜典》的古奥文字，化用《清庙》《生民》的庄严笔意。一纸雄文，别具一格，朝拜时铺展在玉陛丹墀。上表说“臣韩愈冒死呈览”，歌颂圣君贤相的功业，刻写在石碑之上。
碑高三丈字大如斗，灵鳌驼负，螭龙盘围。文句奇特语意深长，世俗难以理解；有人便向皇上进谗，诬蔑此文偏私失实。百尺长绳把韩碑拽倒，粗砂大石磨去了字迹。韩公此文浩浩真气却无法磨灭，已经深入众人的肝脾；正象那汤盘孔鼎的铭文，古器虽早就荡然无存，世间却永远流传着文辞。啊，圣王与贤相的不朽功勋，显耀人寰辉煌无比。韩公碑文倘不能昭示百代，宪宗的帝业，又怎得与三皇五帝遥相承继！我甘愿抄写一万本、吟诵一万遍，哪怕是我口角流沫，右手磨出茧皮！让它流传千秋万代，好作封禅的祭天玉检、明堂的万世基石。', '[{"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d87c26cbf3417f090bf", "shortContent": "义山推崇韩愈的诗文，少年时代即从堂叔学为古文，“以古文出诸公间”。义山的七言古诗学韩愈、李贺，古拙奇峭，骨力雄强，《韩碑》一篇，风格更接近韩诗《石鼓歌》，大气鼓荡，畅沛淋漓，追步昌黎，饶多古意。本篇通过赞美韩愈的《平淮西碑》来歌颂裴度统率大军讨平淮西藩镇吴元济的赫赫之功；通过歌颂裴度巧妙地影射“万古之良相”李德裕相武宗，攘回纥，定泽、潞的丰功伟绩。开头四句谓唐宪宗即位，雄姿英发，可比三皇五帝，发誓...", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f09301", "shortContent": "宪宗元和十二年（817），宰相裴度率兵平定淮西，其时韩愈作为行军司马。淮蔡平定以后，他随裴度还朝，宪宗诏其撰写“平淮西碑”。韩愈以为淮西之役是裴度能坚持宪宗的主张取胜，在碑文中稍侧于称赞裴度的运筹帷幄之功。但破蔡州生擒吴元济的是大将李愬，因而引起李愬不满。愬妻（唐安公主之女）进宫诉说碑文不实，宪宗就下令磨去韩文，命翰林学士段文昌重新撰文勒石，观点迥然不同。但攻破蔡州，李愬确立大功，然而裴度却是整个...", "authors": ["阮森丽"], "pressName": "崇文书局"}]', '《艇斋诗话》：李义山诗雕镌，唯《咏平淮西碑》一篇，诗极雄健，不类常日作。如“点窜《尧典》《舜典》字，涂改《清庙》《生民》诗”及“帝得圣相相曰度，贼斫不死神扶持”等语，甚雄健。
《彦周诗话》：李义山诗，字字锻炼，用事婉约，仍多近体，唯有《韩碑》诗一首是古体。有曰：“涂改《尧典》《舜典》字，点窜《清庙》《生民》诗。”岂立段碑时躁词耶？
《唐诗镜》：宏达典雅，其品不在《淮西碑》下。
《唐诗归》：钟云：特识（“此事不系”句下）。钟云：二语是此诗大主意（“点窜《尧典》”二句下）。钟云：文章定价，说得帝王无权（“公之斯文”二句下）。谭云：比例甚妙（“汤盘孔鼎”二句下）。钟云：一篇典谟、雅颂大文字，出自纤丽手中，尤为不测。潭云：文章语作诗，毕竟要看来是诗，不是文章。
《诗源辨体》：（义山）七言唯《韩碑》、《安平公》二诗稍类退之，而《韩碑》为工。
《李义山诗集辑评》：朱彝尊曰；题赋《韩碑》，诗定学韩文，神物之善变如此。纪昀：笔笔挺拔，步步顿挫，不肯作一流易语。
《五朝诗善鸣集》：此大手笔也，出之纤浓艳丽之人，令人不测，非唯晚唐，亦初、盛、中有数文字。
《义门读书记》：可继《石鼓歌》，字字古茂，句句典雅，颂美之体，讽刺之遗也。
《唐音审体》：诗咏韩碑，即用韩文叙事笔法。然是学韩文，非学韩诗也，识者辨之。
《载酒园诗话又编》：《韩碑》诗亦甚肖韩，仿佛《石鼓歌》气概，造语更胜之。
《中晚唐诗叩弹集》：义山古诗奇丽，有酷似长吉处，独此篇直追退之，荆公谓其得老杜藩篱，亦以近体言之耳。
《古欢堂集杂著》：李商隐《韩碑》一首，媲杜凌韩，音声节奏之妙，令人含咀无尽。每怪义山用事隐僻，而此诗又别辟一境，诗人莫测如此。
《野鸿诗的》：（李商隐）唯《韩碑》一首乃为可取，惜“彼何人哉轩与羲”句，恶劣不堪颂耳。
《消寒诗话》：义山《韩碑》，在其诗中另自一体，直拟退之，殆复过之。
《古诗选·七言诗凡例》：杜七言千古标准，自钱、刘、元、白以来无能步趋者。贞元、元和间，学杜者唯韩文公一人耳……李义山《韩碑》一篇，直追昌黎。
《唐诗观澜集》：玉溪诗以纤丽胜，此独古质，纯以气行，而句奇语重，直欲上步韩碑，乃全集中第一等作。“封狼生貙貙生罴”，句奇。
《唐诗别裁》：晚唐人古诗，秾鲜柔媚，近诗余矣。即义山七古，亦以辞胜。独此篇，意则正正堂堂，辞则鹰扬风翙，在尔时如景星庆云，偶然一见。
《唐诗易简录》：七仄句作提笔，倍见峭劲，叠用“相”字，其和转筋脉在此，其古趣横生亦在此（“帝得圣相”句下）。
《唐贤清雅集》：义山自负杜诗韩文，此篇即本碑体成诗。渔洋山人谓直追昌黎，愚意有过之无不及也。叙事简明，极似碑文。一路烟云缭绕，至此三峰连合，脱卸到作碑着重司马一层（“行军司马”句下）。众写得十分郑重，与后“拽碑倒”相激射点窜，确亦可谓大笔淋漓，句奇语重（“濡染大笔”句下）。大段排宕，至此“一落千丈强”；故意用“长绳”、“粗砂”、“大石”等字，增其气焰，亦自学韩得来（“长绳百尺”二句下）。仍用总束回应成章法，归重碑文作结。余尝言不熟《史记》法，不能作七古大篇。观此知非臆说，作七古最要紧是气，最好熟读千万遍，自然异人。
《唐贤小三昧集续集》：星心月口，忽变为伟调雄文，才人固不可测。
《网师园唐诗笺》：昌黎出人头地，正在句奇语重，咏韩诗便似韩笔，才人能事，无所不可。
《七言诗平仄举隅》：中间顿宕纡回，于此第五字用平处见之（“帝曰汝度”句下）。第四字变换者二句，皆极力摹仿韩公之撑住也。而前句以二“貙”字相磨戛出之，尚不自觉；后句以“功”字撑出，又以“书”字硬接，则劲势到二十分矣。此句内五平问以二仄，而其势较前句之七平者更劲：是岂得以七仄、七平之例泥之乎（“咏神圣功”句下）！
《读雪山房唐诗序例》：李义山《韩碑》，句奇语重，追步退之。
《选玉溪生诗补说》：淮西之役，晋公以宰相督师，则功罪系焉。韩碑归美天子，推重晋公，《春秋》法也，况碑文于愬功原未尝略，前人论之详矣。义山此摩昌黎酷肖。或云义山与段文昌之子成式交，故不敢贬段。愚谓诗取蕴藉，极力推重韩碑，则段碑自见，义山原未尝有讳也。若侈口诋段，岂复成风雅乎！
《玉溪生诗笺注》：今以其赋元和时事，煌煌巨篇，实当弁冕全集，故首登之，无嫌少通其例。
《唐诗三百首》：咏《韩碑》即学韩体，才大者无所不可也。', 'center', 1416840591, '57b9678ad342d3005acacbe7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10515, '燕歌行', NULL, 195, 259, 2, 7, '高适', NULL, 10126, '57b9bf2e165abd00661e158f', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/160276/5062208.htm', '开元二十六年，客有从元戎出塞而还者，作《燕歌行》以示，适感征戍之事，因而和焉。', '汉家烟尘在东北，汉将辞家破残贼。
男儿本自重横行，天子非常赐颜色。
摐金伐鼓下榆关，旌旆逶迤碣石间。
校尉羽书飞瀚海，单于猎火照狼山。
山川萧条极边土，胡骑凭陵杂风雨。
战士军前半死生，美人帐下犹歌舞！
大漠穷秋塞草腓，孤城落日斗兵稀。
身当恩遇常轻敌，力尽关山未解围。
铁衣远戍辛勤久，玉箸应啼别离后。
少妇城南欲断肠，征人蓟北空回首。
边庭飘飖那可度，绝域苍茫更何有！
杀气三时作阵云，寒声一夜传刁斗。
相看白刃血纷纷，死节从来岂顾勋？
君不见沙场征战苦，至今犹忆李将军。', '此诗主要是揭露主将骄逸轻敌，不恤士卒，致使战事失利。全篇大体可分四段：首段八句写出师。其中前四句说战尘起于东北，将军奉命征讨，天子特赐光彩，已见得宠而骄，为后文轻敌伏笔；后四句接写出征阵容。旌旗如云，鼓角齐鸣，一路上浩浩荡荡，大模大样开赴战地，为失利时狼狈情景作反衬。第二段八句写战鬭经过。其中前四句写战初敌人来势凶猛，唐军伤亡惨重，后四句说至晚已兵少力竭，不得解围。第三段八句写征人，思妇两地相望，重会无期。末段四句，两句写战士在生还无望的处境下，已决心以身殉国；两句诗人感慨，对战士的悲惨命运深寄同情。全诗气势畅达，笔力矫健，气氛悲壮淋漓，主旨深刻含蓄。', '燕歌行：乐府《相和歌辞·平调曲》旧题，曹丕、萧绎、庾信所作，多为思妇怀念征夫之意。
张公：指张守珪，开元二十三年因与契丹作战有功，拜辅国大将军兼御史大夫。
汉家：借指唐朝。
烟尘：战地的烽烟和飞尘，此指战争警报。开元十八年（公元730年）五月，契丹及奚族叛唐，此后唐与契、奚之间战事不断。
汉将：指张守珪将领。
「非常赐颜色」句：破格赐予荣耀。赐，一作「借」。
摐（chuāng）金伐鼓：军中鸣金击鼓。摐金，敲锣。
榆关：山海关。
逶迤：曲折行进貌。碣石：山名，在今河北昌黎县北。此借指东北沿海一带。
尉：武官，官阶次于将军。
羽书：羽檄，插有羽毛的紧急军事文书。
瀚海：大沙漠。
单于：秦汉时匈奴君主的称号，此指敌酋。
猎火：狩猎时所举之火。
狼山：阴山山脉西段，在今内蒙古自治区中部。此外借瀚海、狼山泛指当时战场。
凭陵：逼压、凭信威力侵凌别人。
穷秋：深秋。
腓（féi）：一作「衰」，病，枯萎。隋·虞世基《陇头吟》：「穷秋塞草腓，塞外胡尘飞。」
「身当恩遇恒轻敌，力尽关山未解围。」句：一写主帅受皇恩而轻敌；一写战士拼死苦战也未能冲破敌人的包围。常轻敌，一作「恒轻敌」。
铁衣：借指将士。《木兰辞》：「寒光照铁衣」。
玉箸：即玉筯、玉筷，白色的筷子，借喻眼泪，這里指思妇的泪水如注。刘孝威《独不见》：「谁怜双玉箸，流面复流襟。」
城南：长安住宅区在城南，故云。沈佺期《独不见》：「丹凤城南秋夜长。」
蓟北：蓟州、幽州一带，今河北省北部地区。此泛指东北战场。
边庭飘飖（yáo）：一作「边风飘飘」，指形势动荡、险恶。
那可度：一作「那可越」。
绝域：更遥远的边陲。
苍茫：一作「苍黄」。
更何有：一作「何所有」，更加荒凉不毛。
三时：早、午、晚。一作「三日」。
阵云：战云。
寒声：一作「寒风」。
血纷纷：一作「雪纷纷」、一作「徒纷纷」。
刁斗：古代军中煮饭用的铜锅，夜里可用作巡更敲击报时的铜器。
李将军：指李广。善用兵，爱惜士卒，守右北平，匈奴畏之不敢南侵，称为飞将军。事见《史记·李将军传》。', '唐玄宗开元二十六年，有个随从主帅出塞回来的人，写了《燕歌行》诗一首给我看。我感慨于边疆战守的事，因而写了这首《燕歌行》应和他。
唐朝边境举烟火狼烟东北起尘土，唐朝将军辞家去欲破残忍之边贼。
战士们本来在战场上就所向无敌，皇帝又特别给予他们丰厚的赏赐。
锣声响彻重鼓棰声威齐出山海关，旌旗迎风又逶迤猎猎碣石之山间。
校尉紧急传羽书飞奔浩瀚之沙海，匈奴单于举猎火光照已到我狼山。
山河荒芜多萧条满目凄凉到边土，胡人骑兵仗威力兵器声里夹风雨。
战士拼鬭军阵前半数死去半生还，美人却在营帐中还是歌来还是舞！
时值深秋大沙漠塞外百草尽凋枯，孤城一片映落日战卒越斗越稀少。
身受皇家深恩义常思报国轻寇敌，边塞之地尽力量尚未破除匈奴围。
身穿铁甲守边远疆场辛勤已长久，珠泪纷落挂双目丈夫远去独啼哭。
少妇孤单住城南泪下凄伤欲断肠，远征军人驻蓟北望家园空自回头。
边境飘渺多遥远怎可轻易来奔赴，绝远之地尽苍茫更是人烟何所有。
杀气春夏秋三季腾起阵前似乌云，一夜寒风声声里如泣更声惊耳鼓。
互看白刃乱飞舞夹杂着鲜血纷飞，从来死节为报国难道还求著功勋？
你没看见拼杀在沙场战鬭多惨苦，现在还在思念有勇有谋的李将军。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a42e6a6b501f95c130", "shortContent": "《燕歌行》不仅是高適的“第一大篇”（近人赵熙评语），而且是整个唐代边塞诗中的杰作，千古传诵，良非偶然。\n开元十五年（727），高適曾北上蓟门。二十年，信安王李祎征讨奚、契丹，他又北去幽燕，希望到信安王幕府效力，未能如愿：“岂无安边书，诸将已承恩。惆怅孙吴事，归来独闭门”（《蓟中作》）。可见他对东北边塞军事，下过一番研究工夫。开元二十一年后，幽州节度使张守珪经略边事，初有战功。但二十四年，张让平卢讨...", "authors": ["徐永年"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d113", "shortContent": "《燕歌行》不仅是高适的“第一大篇”（近人赵熙评语），而且是整个唐代边塞诗中的杰作，千古传诵，良非偶然。\n\n开元十五年（727），高适曾北上蓟门。二十年，信安王李祎征讨奚、契丹，他又北去幽燕，希望到信安王幕府效力，未能如愿：“岂无安边书，诸将已承恩。惆怅孙吴事，归来独闭门”（《蓟中作》）。可见他对东北边塞军事，下过一番研究工夫。开元二十一年后，幽州节度使张守珪经略边事，初有战功。但二十四年，张让平卢...", "authors": ["徐永年"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f09303", "shortContent": "开元年间，契丹屡屡入侵犯边，东北边境烽烟四起，百姓处于水深火热之中。坐镇东北的是辅国大将军兼御史大夫张守珪，战功卓著。但开元二十四年（736），张让平卢讨击使安禄山讨奚、契丹，禄山恃勇轻进而败北。开元二十六年（738），张守珪部将赵堪、白真陀罗假借张之命令，逼令平卢军使乌知义奔击叛奚余部于潢水之北，先胜后败，但是“守珪隐其状，而妄奏克获之功”（《旧唐书•张守珪传》）。根据诗前小序可知，诗人当是据此...", "authors": ["褚菊萍"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127055e6f69b71e93f628e", "shortContent": "开元年间，契丹屡屡入侵，东北边境烽烟四起，尘土弥漫，老百姓处于水深火热之中。好男儿挺身而出，为讨伐入侵的贼敌，辞家上了前线。当时坐镇东北的是御史大夫兼大将军张守珪，他率领将士纵横驰骋，英勇杀敌，势不可挡，屡建战功。皇帝对此非常满意，重重封赏了他们。\n\n开元二十六年（738），张守珪部将赵堪、白真陀罗假借张之命令，逼令平卢军使乌知义奔击叛奚。当时出征的军队，浩浩荡荡，气势雄壮。敲锣打鼓，队伍雄赳赳开...", "authors": ["褚菊萍"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270c69761253910e905a6", "shortContent": "开元年间，契丹屡屡入侵，东北边境烽烟四起，尘土弥漫，老百姓处于水深火热之中。好男儿挺身而出，为讨伐入侵的贼敌，辞家上了前线。当时坐镇东北的是大将军兼御史大夫张守珪，他率领将士纵横驰骋，英勇杀敌，势不可挡，屡建战功。皇帝对此非常满意，重重封赏了他们。\n\n二十六年（738），张守珪部将赵堪、白真陀罗假借张之命令，逼令平卢军使乌知义奔击叛奚。当时出征的军队，浩浩荡荡，气势雄壮。敲锣打鼓，队伍雄赳赳开出山...", "authors": ["褚菊萍"], "pressName": "崇文书局"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f2e5b5e6bb82b8cf09fcf", "shortContent": "《燕歌行》不仅是高适的“第一大篇”（近人赵熙评语），而且是整个唐代边塞诗中的杰作，千古传诵，良非偶然。\n开元十五年(727)，高适曾北上蓟门。二十年，信安王李祎征讨奚、契丹，他又北去幽燕，希望到信安王幕府效力，未能如愿：“岂无安边书，诸将已承恩。惆怅孙吴事，归来独闭门”（《蓟中作》）。可见他对东北边塞军事，下过一番研究工夫。开元二十一年后，幽州节度使张守珪经略边事，初有战功。但二十四年，张让平卢讨...", "authors": ["徐永年"], "pressName": "上海辞书出版社"}]', '唐汝询《唐诗解·卷十六》：言烟尘在东北，原非犯我内地，汉将所破特馀寇耳。盖此辈本重横行，天子乃厚加礼貌，能不生边衅乎？
王夫之《唐诗评选》：词浅意深，铺排中即为讽刺。此道自「三百篇」来，至唐而微，至宋而绝。', 'center', 1416840753, '57b903acd342d3005ac7411e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10516, '古从军行', NULL, 175, 124, 3, 5, '李颀', NULL, 10124, '57b9a05e8ac2470063fdd3af', '唐', 'shi', '诗', 'http://baike.baidu.com/view/345752.htm', '', '白日登山望烽火，黄昏饮马傍交河。
行人刁斗风沙暗，公主琵琶幽怨多。
野云万里无城郭，雨雪纷纷连大漠。
胡雁哀鸣夜夜飞，胡儿眼泪双双落。
闻道玉门犹被遮，应将性命逐轻车。
年年战骨埋荒外，空见蒲桃入汉家。', '此诗以汉喻唐，借写汉武帝的开边，讽刺当时唐玄宗的开边，充满反战思想。开首先写紧张的从军生活：白日黄昏繁忙，夜里刁斗悲呛，琵琶幽怨，景象肃穆凄凉。接着渲染边陲的环境：军营所在，四顾荒野，大雪荒漠，夜雁悲鸣，一片凄冷酷寒景象。最后写如此恶劣环境，本应班师回朝，然而皇上不准；而千军万马拼死作战的结果，却只换得葡萄种子归国，足见君王之草菅人命。全诗句句蓄意，步步逼紧，最后才画龙点睛，着落主题，显出其讽刺笔力。', '烽火：古代一种警报。
饮（yìn）马：给马喂水。
傍：顺着。
交河：古县名，故城在今新疆吐鲁番西面。
行人：出征战士。
刁斗：古代军中铜制炊具，容量一斗。白天用以煮饭，晚上敲击代替更柝。
公主琵琶：汉武帝时以江都王刘建女细君嫁乌孙国王昆莫，恐其途中烦闷，故弹琵琶以娱之。
“闻道”两句：汉武帝曾命李广利攻大宛，欲至贰师城取良马，战不利，广利上书请罢兵回国，武帝大怒，发使至玉门关，曰：“军有敢入，斩之！”两句意谓边战还在进行，只得随着将军去拼命。
蒲桃：今作“葡萄”。', '白天登山观察报警的烽火台，黄昏时牵马饮水靠近交河边。
昏暗的风沙传来阵阵刁斗声，如同汉代公主琵琶充满幽怨。
旷野云雾茫茫万里不见城郭，雨雪纷纷笼罩着无边的沙漠。
哀鸣的胡雁夜夜从空中飞过，胡人士兵个个眼泪双双滴落。
听说玉门关已被挡住了归路，战士只有追随将军拼命奔波。
年年战死的尸骨埋葬于荒野，换来的只是西域葡萄送汉家。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92922e6a6b501f95bee0", "shortContent": "“从军行”是乐府古题。此诗写当代之事，由于怕触犯忌讳，所以题目加上一个“古”字。它对当代帝王的好大喜功，穷兵黩武，视人民生命如草芥的行径，加以讽刺，悲多于壮。\n诗开首先写紧张的从军生活。白天爬上山去观望四方有无举烽火的边警；黄昏时候又到交河边上让马饮水（交河在今新疆吐鲁番西面，这里借指边疆上的河流）。三、四句的“刁斗”，是古代军中铜制炊具，容量一斗。白天用以煮饭，晚上敲击代替更柝。“公主琵琶”是指...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0fc", "shortContent": "“从军行”是乐府古题。此诗写当代之事，由于怕触犯忌讳，所以题目加上一个“古”字。它对当代帝王的好大喜功，穷兵黩武，视人民生命如草芥的行径，加以讽刺，悲多于壮。\n\n诗开首先写紧张的从军生活。白天爬上山去观望四方有无举烽火的边警；黄昏时候又到交河边上让马饮水（交河在今新疆吐鲁番西面，这里借指边疆上的河流）。三、四句的“刁斗”，是古代军中铜制炊具，容量一斗。白天用以煮饭，晚上敲击代替更柝。“公主琵琶”是...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f09304", "shortContent": "诗题为《古从军行》，实为以古讽今。以汉事喻唐事，是唐代诗人的习惯，诸解多指此诗针对唐玄宗穷兵黩武而发。\n\n“白日”两句以时间、空间的推移写征人的日常生活。白日、黄昏，代表时间的流逝；登山、饮马，表明空间的转移；烽火、交河，说明边庭烽烟战事。烽火，是古代预警入侵的信号；交河，在今新疆吐鲁番，其河出交河县北天山。从清晨到黄昏，从登山望烽火到河边饮马，在时间与空间的转换中展现出广阔的边庭。\n\n“行人”两...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127036c9ebcc6fbea1a3a3", "shortContent": "诗题为《古从军行》，实为以古讽今。以汉事喻唐事，是唐代诗人的习惯，诸解多指此诗针对唐玄宗穷兵黩武而发。\n\n“白日”两句以时间、空间的推移写征人的日常生活。白日、黄昏，代表时间的流逝；登山、饮马，表明空间的转移；烽火、交河，说明边庭烽烟战事。烽火，是古代预警入侵的信号；交河，在今新疆吐鲁番西面，此处借指边疆上的河流。从清晨到黄昏，从登山望烽火到河边饮马，在时间与空间的转换中展现出广阔的边庭。\n\n“行...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312706ac305cf0801816fe2", "shortContent": "诗题为《古从军行》，实为以古讽今。以汉事喻唐事，是唐代诗人的习惯，诸解多指此诗针对唐玄宗穷兵黩武而发。\n“白日”两句以时间、空间的推移写征人的日常生活。白日、黄昏，代表时间的流逝；登山、饮马，表明空间的转移；烽火、交河，说明边庭烽烟战事。烽火，是古代预警入侵的信号；交河，在今新疆维吾尔族自治区吐鲁番市治西，其河出交河县北天山。从清晨到黄昏，从登山望烽火到河边饮马，在时间与空间的转换中展现出广阔的边...", "authors": ["张春晓"], "pressName": "崇文书局"}]', '', 'center', 1416840933, '57b99c605bbb500053484dff', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10517, '洛阳女儿行', NULL, 73, 394, 1, 2, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/323613/5767470.htm', '', '洛阳女儿对门居，才可容颜十五馀。
良人玉勒乘骢马，侍女金盘脍鲤鱼。
画阁朱楼尽相望，红桃绿柳垂檐向。
罗帏送上七香车，宝扇迎归九华帐。
狂夫富贵在青春，意气骄奢剧季伦。
自怜碧玉亲教舞，不惜珊瑚持与人。
春窗曙灭九微火，九微片片飞花琐。
戏罢曾无理曲时，妆成只是熏香坐。
城中相识尽繁华，日夜经过赵李家。
谁怜越女颜如玉，贫贱江头自浣纱。', '写洛阳贵妇生活的富丽豪贵，夫婿行为的骄奢放荡，揭示了高层社会的骄奢淫逸。诗开头八句是叙洛阳女出身骄贵和衣食住行的豪富奢侈。「狂夫」八句是叙洛阳女丈夫行为之骄奢放荡和作为玩物的贵妇的娇媚无聊。「城中」四句是写她们的交住尽是贵戚。并以西施出身寒微作为反衬，发抒作者的感慨。', '洛阳女儿：取梁武帝萧衍《河中之水歌》中「河中之水向东流，洛旧女儿名莫愁」语。
才可：恰好。
容颜：一作「颜容」。
十五馀：十五六岁。梁简文帝《怨歌行》：「十五颇有馀。」
良人：古代妻对夫的尊称。
玉勒：玉饰的马衔。
骢（cōng）马：青白色的马。
脍（kuài）鲤鱼：切细的鲤鱼肉。脍：把鱼、肉切成薄片。
罗帷：丝织的帘帐。
七香车：旧注以为以七种香木为车。
宝扇：古代贵妇出行时遮蔽之具，用鸟羽编成。
九华帐：鲜艳的花罗帐。
狂夫：犹拙夫，古代妇女自称其夫的谦词，唐·李太白《捣衣篇》：「狂夫犹戍交河北。」
剧：戏弄，意谓可轻视石崇。唐·李太白《长干行》：「拆花门前剧」。
季伦：晋石崇字季伦，家甚豪富。
怜：爱怜。
碧玉：《乐府诗集》以为刘宋汝南王妾名。这里指洛阳女儿。
「不惜珊瑚持与人」句：《世说新语·侈汰》记，王恺以晋武帝所赐二尺珊瑚示石崇，崇以铁如意击之。王恺斥之，崇乃命人搬来三四尺高珊瑚六七枝偿还之。
曙（shǔ）：天明。
九微灯：汉武帝供王母使用的灯，这里指平常的灯火。
片片：指灯花。
花琐：指雕花的连环形窗格。
曾无：从无。
理：温习。
熏（xūn）香：用香料熏衣服。
赵李家：汉成帝的皇后赵飞燕、婕妤李平。这里泛指贵戚之家。
越女：指春秋时期越国美女西施。越，这里指今浙东。', '洛阳有一位女子住在我家对门，正当十五六的芳年容颜非常美丽。她的丈夫骑一匹青白相间的骏马，马具镶嵌着珍贵的美玉。她的婢女捧上黄金的盘子，里面盛着烹制精细的鲤鱼。她家彩绘朱漆的楼阁一幢幢遥遥相望，红桃绿柳在廊檐下排列成行。她乘坐的车子是用七种香木做成，绫罗的帷幔装在车上。仆从们举着羽毛的扇子，把她迎回绣着九花图案的彩帐。她的丈夫青春年少正得志，骄奢更胜过石季伦。他亲自教授心爱的姬妾学习舞蹈，名贵的珊瑚树随随便便就送给别人。他们彻夜寻欢作乐，窗上现出曙光才熄去灯火，灯花的碎屑片片落在雕镂的窗棱。她成天嬉戏游玩，竟没有温习歌曲的空暇，打扮得整整齐齐，只是熏着香成天闲话。相识的全是城中的豪门大户，日夜来往的都是些贵戚之家。有谁怜惜貌美如玉的越女，身处贫贱，只好在江头独自洗纱。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f09305", "shortContent": "此诗应为王维年轻时所作。这位女子的身份，可能先是歌女，后被豪贵收为姬妾。\n\n起句简单介绍洛阳女儿。这位对门而居的少女，容颜才十五岁左右。她的丈夫骑着一匹青白相间的骏马，马具上镶嵌着珍贵的美玉；她的侍女捧上金盘，里面盛着烹制精细的鲤鱼脍。这两句用她的丈夫和侍女侧笔映衬出她的华丽富贵。她家彩绘朱漆的楼阁一幢幢遥遥相望，红桃绿柳在廊檐下排列成行。想出个门吧，长长的罗帏遮蔽着她，一直送上七香车中；晚上归来...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '', 'center', 1416841078, '57ba9362c4c97100614de551', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10518, '老将行', NULL, 91, 394, 2, 2, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/344237.htm', '', '少年十五二十时，步行夺得胡马骑。
射杀山中白额虎，肯数邺下黄须儿。
一身转战三千里，一剑曾当百万师。
汉兵奋迅如霹雳，虏骑崩腾畏蒺藜。
卫青不败由天幸，李广无功缘数奇。
自从弃置便衰朽，世事蹉跎成白首。
昔时飞箭无全目，今日垂杨生左肘。
路旁时卖故侯瓜，门前学种先生柳。
苍茫古木连穷巷，寥落寒山对虚牖。
誓令疏勒出飞泉，不似颍川空使酒。
贺兰山下阵如云，羽檄交驰日夕闻。
节使三河募年少，诏书五道出将军。
试拂铁衣如雪色，聊持宝剑动星文。
愿得燕弓射大将，耻令越甲鸣吾君。
莫嫌旧日云中守，犹堪一战取功勋。', '此诗写一老将年少勇战，转战沙场，后因“无功”被弃，然而他自不服老，在边地烽火重燃时，他壮心复起，仍想为国立功。全诗分三部分，开头十句是第一部分，写老将青少年时代的智勇、功绩和不平遭遇；中间十句为第二部分，写老将被遗弃的清苦生活；最后十句为第三部分，写边烽未息，老将时时怀着请缨卫国杀敌的衷肠。诗中大量用典，几乎句句对仗，层次分明，自始至终洋溢着爱国激情，格调苍凉悲壮，但哀而不伤。', '“步行”句：汉名将李广，为匈奴骑兵所擒，广时已受伤，便即装死。后于途中见一胡儿骑着良马，便一跃而上，将胡儿推在地下，疾驰而归。见《史记·李将军列传》。夺得：一作“夺取”。
“射杀”句：与上文连观，应是指李广为右北平太守时，多次射杀山中猛虎事。白额虎（传说为虎中最凶猛一种），则似是用晋名将周处除三害事。南山白额虎是三害之一。见《晋书·周处传》。中山：一作“山中”，一作“阴山”。
肯数：岂可只推。邺下黄须儿：指曹彰，曹操第二子，须黄色，性刚猛，曾亲征乌丸，颇为曹操爱重，曾持彰须曰：“黄须儿竟大奇也。”这句意谓，岂可只算黄须儿才是英雄。邺下，曹操封魏王时，都邺（今河北临漳县西）。
蒺藜：本是有三角刺的植物，这里指铁蒺藜，战地所用障碍物。
卫青：汉代名将，汉武帝皇后卫子夫之弟，以征伐匈奴官至大将军。卫青姊子霍去病，也曾远入匈奴境，却未曾受困折，因而被看作“有天幸”。《史记·卫将军骠骑列传》载：“去病所将常选，然亦敢深入，常与壮骑先其大军。军亦有天幸，未尝困绝也。”“天幸”本霍去病事，然古代常卫、霍并称，这里当因卫青而联想霍去病事。
“李广”句：李广曾屡立战功，汉武帝却以他年老数奇，暗示卫青不要让李广抵挡匈奴，因而被看成无功，没有封侯。缘，因为。数，命运。奇，单数。偶之对称，奇即不偶，不偶即不遇。
飞箭无全目：鲍照《拟古诗》：“惊雀无全目。”李善注引《帝王世纪》：吴贺使羿射雀，贺要羿射雀左目，却误中右目。这里只是强调羿能使雀双目不全，于此见其射艺之精。飞箭：一作“飞雀”。
垂杨生左肘：《庄子·至乐》：“支离叔与滑介叔观于冥柏之丘，昆仑之虚，黄帝之所休，俄而柳生其左肘，其意蹶蹶然恶之。”沈德潜以为“柳，疡也，非杨柳之谓”，并以王诗的垂杨“亦误用”。他意思是说，庄子的柳生其左肘的柳本来即疡之意，王维却误解为杨柳之柳，因而有垂云云。高步瀛说：“或谓柳为瘤之借字，盖以人肘无生柳者。然支离、滑介本无其人，生柳寓言亦无不可。”高说似较胜。
故侯瓜：召平，本秦东陵侯，秦亡为平民，贫，种瓜长安城东，瓜味甘美。
先生柳：晋陶渊明弃官归隐后，因门前有五株杨柳，遂自号“五柳先生”，并写有《五柳先生传》。
苍茫：一作“茫茫”。连：一作“迷”。
寥：一作“辽”。牖（yǒu）：窗户。
“誓令”句：后汉耿恭与匈奴作战，据疏勒城，匈奴于城下绝其涧水，恭于城中穿井，至十五丈犹不得水，他仰叹道：“闻昔贰师将军（李广利）拔佩刀刺山，飞泉涌出，今汉德神明，岂有穷哉。”旋向井祈祷，过了一会，果然得水。事见《后汉书·耿恭传》。疏勒：指汉疏勒城，非疏勒国。疏勒城，在今新疆疏勒县。
颍川空使酒：灌夫，汉颍阴人，为人刚直，失势后颇牢骚不平，后被诛。使酒：恃酒逞意气。
贺兰山：山名，在今宁夏中部。
聊持：且持。星文：指剑上所嵌的七星文。
大将：一作“天将”。
“耻令”句：意谓以敌人甲兵惊动国君为可耻。《说苑·立节》：越国甲兵入齐，雍门子狄请齐君让他自杀，因为这是越甲在鸣国君，自己应当以身殉之，遂自刎死。呜：这里是惊动的意思。吴军：一作“吾君”。
云中守：指汉文帝时的云中太守魏尚。
取：一作“树”。', '当年十五二十岁青春之时，徒步就能夺得胡人战马骑。
年轻力壮射杀山中白额虎，数英雄岂止邺下的黄须儿？
身经百战驰骋疆场三千里，曾以一剑抵挡了百万雄师。
汉军声势迅猛如惊雷霹雳，虏骑互相践踏是怕遇蒺藜。
卫青不败是由于天神辅助，李广无功却缘于命运不济。
自被摈弃不用便开始衰朽，世事随时光流逝人成白首。
当年象后羿飞箭射雀无目，如今不操弓疡瘤生于左肘。
象故侯流落为民路旁卖瓜，学陶令门前种上绿杨垂柳。
古树苍茫一直延伸到深巷，寥落寒山空对冷寂的窗牖。
誓学耿恭在疏勒祈井得泉，不做颍川灌夫为牢骚酗酒。
贺兰山下战士们列阵如云，告急的军书日夜频频传闻。
持节使臣去三河招募兵丁，招书令大将军分五路出兵。
老将揩试铁甲光洁如雪色，且持宝剑闪动剑上七星纹。
愿得燕地的好弓射杀敌将，绝不让敌人甲兵惊动国君。
莫嫌当年云中太守又复职，还堪得一战为国建立功勋。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92955914587d02f4e515", "shortContent": "这首诗叙述了一位老将的经历。他一生东征西战，功勋卓著，结果却落得个“无功”被弃、不得不以躬耕叫卖为业的可悲下场。边烽再起，他又不计恩怨，请缨报国。作品揭露了统治者的赏罚蒙昧，冷酷无情，歌颂了老将的高尚节操和爱国热忱。\n全诗分三段。开头十句为第一段，是写老将青壮年时代的智勇、功绩和不平遭遇。先说他少时就有李广之智勇，“步行”夺得过敌人的战马，引弓射杀过山中最凶猛的“白额虎”。接着改用曹操的次子曹彰故...", "authors": ["傅经顺"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f09306", "shortContent": "这首诗写一个老将军一生的经历。他曾经建功立勋，却得不到统治者应有的犒赏，只落得路边叫卖为生的悲惨下场。但是当国家危难之时，他又不计前嫌，挺身而出。诗中引用了大量典故，表现了诗人深厚的文学功底和运用自如的娴熟技巧，也是诗人前期慷慨激昂诗作的代表。\n\n老将军年轻的时候，非常的英勇善战。少年时代就有了汉朝名将李广的机智和英勇，竟能步行夺过敌人的战马并且逃脱敌手，也曾引弓射杀过山中最凶猛的白额虎。曹操的次...", "authors": ["虞盈盈"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270447ccdb86c49f2922e", "shortContent": "这首诗写了一个老将军一生经历的故事。他曾经建立功勋，却得不到应有的赏赐，只落得路边叫卖为生的悲惨下场。但是当国家危难之时，他又不计前嫌，挺身而出，报效祖国。诗中引用了大量典故，表现了诗人深厚的文学功底和运用自如的娴熟技巧，也是其前期慷慨激扬的爱国诗作的代表。\n\n老将军年轻的时候，非常的英勇善战。少年时代就有了汉朝名将李广的机智和英勇，竟能步行夺过敌人的战马并且逃脱敌手，也曾引弓射杀过山中最凶猛的白...", "authors": ["虞盈盈"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "64639fc830675327e1850a42", "shortContent": "这首诗叙述了一位老将的经历。他一生东征西战，功勋卓著，结果却落得个“无功”被弃、不得不以躬耕叫卖为业的可悲下场。边烽再起，他又不计恩怨，请缨报国。作品揭露了统治者的赏罚蒙昧，冷酷无情，歌颂了老将的高尚节操和爱国热忱。\n\n全诗分三段。开头十句为第一段，是写老将青壮年时代的智勇、功绩和不平遭遇。先说他少时就有李广之智勇，“步行”夺得过敌人的战马，引弓射杀过山中最凶猛的“白额虎”。接着改用曹操的次子曹彰...", "authors": ["傅经顺"], "pressName": "上海辞书出版社"}]', '《王孟诗评》：满篇风致，收拾处常嫩而短，使人情事欲绝。起语娇嫩，复胜老语。愈出愈奇（“苍茫古木”句下）。
《唐诗镜》：轻轻说起有法，接语天然，“自从弃置”句以下，写出老退。“贺兰山下”后，又突起一节，老当益壮，引用“云中守”结方有力。
《唐诗解》：对偶严整，转换有法，长篇之圣者。史称右丞晚年长斋奉佛，无仕进意，然观此诗，宦兴亦自不浅。
《唐诗选脉会通评林》：周珽曰：……“卫青”、“李广”二句，天然偶对。“苍茫”、“寥落”二句，忽入景，妙。尾数语雄浑，力可鞭策龙虎。吴山民曰：陡然起便劲健。次六语何等猛烈。“卫青”句正不必慕，“李广”句便自可叹。“苍茫”二句说得冷落。“誓令”二句猛气犹存。末六句老赶何如。
《唐风定》：绝去雕组，独行风骨，初唐气运至此一变。歌行正宗、千秋标准，有外此者，一切邪道矣。
《此木轩论诗汇编》：凡三章，章五韵，最整之格。每一韵为一章，一章之中又各两小章，而意则各于末句见之。前二章之末韵犹所谓过文，“卫青”二句渡下，“李广”句自谓也，“誓令”二句又渡下。结二句勿连读……章法最为清明整肃者也。看摩诘写此老将，何等有志气、有身份，不但本事绝人而已。如“李广无功”云云，实命不犹，悲而不怨，诗人之致也。“誓令疏勒”云云，赤心报主，说礼敦诗，名将之风也。推此类可见，不能一一具言之。
《历代诗法》：右丞七古，和平宛委，无蹈厉莽之态，最不易学。
《唐诗别裁》：此种诗纯以队仗胜。学诗者不能从李、杜人，右丞、常侍自有门径可寻。
《唐贤三昧集笺注》：从少说起。写得闲散，意象如画（“寥落寒山”句下）。前路迤逦，其势蓄极，到此乃喷薄而出，须知其谐处俱不失其健（“贺兰山下”句下）。此段驰骤，须放缓来收。音节乃尽抑扬之妙。
《唐贤清雅集》：起势飘忽，骇人心目。七古长篇概用对句，错落转换，全以气胜，否则支离节解矣。转接补干，用法精细，大家见识。
《唐宋诗举要》：高步瀛曰：雄姿飒爽，步伐整齐。', 'center', 1416841194, '57b9ab4d165abd00661d491b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10519, '桃源行', NULL, 124, 394, 2, 3, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/181981/11122156.htm', '', '渔舟逐水爱山春，两岸桃花夹古津。
坐看红树不知远，行尽青溪忽视人。
山口潜行始隈隩，山开旷望旋平陆。
遥看一处攒云树，近入千家散花竹。
樵客初传汉姓名，居人未改秦衣服。
居人共住武陵源，还从物外起田园。
月明松下房栊静，日出云中鸡犬喧。
惊闻俗客争来集，竞引还家问都邑。
平明闾巷扫花开，薄暮渔樵乘水入。
初因避地去人间，及至成仙遂不还。
峡里谁知有人事，世中遥望空云山。
不疑灵境难闻见，尘心未尽思乡县。
出洞无论隔山水，辞家终拟长游衍。
自谓经过旧不迷，安知峰壑今来变。
当时只记入山深，青溪几曲到云林。
春来遍是桃花水，不辨仙源何处寻。', '王维的诗以抒写山水著称，此诗尤胜。历来评价王诗有“诗中有画，画中有诗”的说法，细读这首诗才知此话不假。
诗以陶潜的《桃花源记》为蓝本，取其大意，变文为诗，进行艺术的再创造，开拓了诗的意境，具有它独特的艺术价值。为此，它能与散文《桃花源记》并传于世。这首诗段落与陶潜的散文相仿，但画面却比陶文来得生动优美，绚烂多彩。全诗笔力舒健，韵脚多变，平仄相间，从容雅致，活跃多姿。', '逐水：顺着溪水。
古津：古渡口。去，一作“去”。
坐：因为。
行尽青溪忽视人：一说“行尽不见青溪人”，一说“行尽青溪忽值人”，见人，遇到路人。
隈：山、水弯曲的地方。
旷望：指视野开阔。
旋：不久。
攒云树：云树相连。攒，聚集。
散花竹：指到处都有花和竹林。
樵客：原本指打柴人，这里指渔人。
武陵源：指桃花源，相传在今湖南桃源县（晋代属武陵郡）西南。武陵，即今湖南常德。
物外：世外。
房栊：房屋的窗户。
喧：叫声嘈杂。
俗客：指误入桃花源的渔人。
引：领。
都邑：指桃源人原来的家乡。
平明：天刚亮。
闾巷：街巷。
开：指开门。
薄暮：傍晚。
避地：迁居此地以避祸患。
去：离开。
灵境：指仙境。
尘心：普通人的感情。
乡县：家乡。
游衍：留连不去。
自谓：自以为。
不迷：不再迷路。
峰壑：山峰峡谷。
青溪几曲到云林：又作“清溪几度到云林”。
云林：云中山林。
桃花水：春水，桃花开时河流涨溢。', '渔舟顺溪而下，追寻那美妙的春景，夹岸桃花映红了古渡口两旁。花树缤纷，忘记了路程远近；行到青溪尽处，忽然隐约似见人烟。走入了幽深曲折的山口，再往前，豁然开朗一片平川。远望去丛丛绿树有如云霞绮聚集，进村见户户门前翠竹鲜花掩映。第一次才听说汉以后的朝代，村民穿戴的还是秦代衣装。他们世代聚居在武陵源，在这里共建了世外田园。明月朗照，松下房栊寂静；旭日升起，村中鸡犬声响起。村人惊讶地把外客迎接，争相邀请，询问那世上的消息。清晨的街巷，家家打扫花径；傍晚的溪边，渔樵乘船回村。当初因避乱世逃出尘寰，寻到这桃源仙境便不归还。从此隐居峡谷，再不管外间变化；世人求访异境，不过是空望云山。渔人不怀疑这是难得的仙境，但凡心未尽只把家园挂牵；出洞后他不顾隔山隔水，又决定辞家来此仙源。自认为来过的地方不会迷路，怎知道眼前的峰壑全然改变。当时曾记得山径幽深，沿青溪几回弯曲才到桃林。此日又逢春天，依然遍地桃花水；仙源何处，已杳杳难寻，不辨道路！', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92952cee9a0c24ecf7eb", "shortContent": "这是王维十九岁时写的一首七言乐府诗，题材取自晋陶渊明的叙事散文《桃花源记》。清人吴乔在《围炉诗话》中曾说：“意思，犹五谷也。文，则炊而为饭；诗，则酿而为酒也。”好的诗应当像醇酒，读后能令人陶醉。因此，要将散文的内容改用诗歌表现出来，绝不仅仅是一个改变语言形式的问题，还必须进行艺术再创造。王维这首《桃源行》，正是由于成功地进行了这种艺术上的再创造，因而具有独立的艺术价值，得以与散文《桃花源记》并世流...", "authors": ["刘德重"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f09307", "shortContent": "这首诗很容易让我们想到陶渊明的《桃花源记》，显然王维在题材上是取自于此，但是他又进行了自己的再创造。诗人用七言乐府诗的形式，加之清新凝练的语言，向我们描绘了一幅意境飘忽、画面灵动的桃源仙境图。\n\n渔人被大好的春光所吸引，泛舟前行。只见河流两岸的桃花开得十分烂漫，团团簇簇，像燃烧的火焰一样，把道路都给遮蔽了。他坐在船上，痴迷于这红艳的桃树，不知不觉中已经忘却走了有多远。一直行到青溪的尽头，却还是连一...", "authors": ["虞盈盈"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "64639fdf7da2f75ac7e3ee4d", "shortContent": "这是王维十九岁时写的一首七言乐府诗，题材取自晋陶渊明的叙事散文《桃花源记》。清人吴乔在《围炉诗话》中曾说：“意思，犹五谷也。文，则炊而为饭；诗，则酿而为酒也。”好的诗应当像醇酒，读后能令人陶醉。因此，要将散文的内容改用诗歌表现出来，绝不仅仅是一个改变语言形式的问题，还必须进行艺术再创造。王维这首《桃源行》，正是由于成功地进行了这种艺术上的再创造，因而具有独立的艺术价值，得以与散文《桃花源记》并世流...", "authors": ["刘德重"], "pressName": "上海辞书出版社"}]', '清代王士禛《池北偶谈》：唐宋以来，作《桃源行》最佳者，王摩诘（王维）、韩退之（韩愈）、王介甫（王安石）三篇。观退之、介甫二诗，笔力意思甚可喜。及读摩诘诗，多少自在；二公便如努力挽强，不免面红耳热，此盛唐所以高不可及。
翁方纲《石洲诗话》：古今咏桃源事者，至右丞而造极。
沈德潜评此诗：顺文叙事，不须自出意见，而夷犹容与，令人味之不尽。', 'center', 1416859942, '57b915108ac2470062e03acf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10520, '长相思（其一）', NULL, 797, 1052, 2, 3, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3135259.htm', '', '长相思，在长安。
络纬秋啼金井阑，微霜凄凄簟色寒。
孤灯不明思欲绝，卷帷望月空长叹。
美人如花隔云端。
上有青冥之高天，下有渌水之波澜。
天长路远魂飞苦，梦魂不到关山难。
长相思，摧心肝。', '这首诗是李白离开长安后回忆往日情绪时所作，豪放飘逸中兼有含蓄。诗人通过对秋虫、秋霜、孤灯等景物的描写抒发了感情。表现出相思的痛苦。「美人如花隔云端」是全诗的中心句，其中含有托兴意味。我国古代经常用「美人」比喻所追求的理想。「长安」这个特定的地点更加暗示「美人」在这里是个政治托寓，表明此诗目的在于抒发诗人追求政治理想而不能的郁闷之情。诗人将意旨隐含在形象之中，隐而不露，自有一种含蓄的韵味。', '长安：今陕西省西安市。
络纬：昆虫名，又名莎鸡，俗称纺织娘。
金井阑：精美的井阑。
簟（diàn）色寒：指竹席的凉意。簟，凉席。
帷：窗帘。
青冥：青云。
渌水：清水。
关山难：关山难渡。
摧：伤。', '日日夜夜地思念啊，我思念的人在长安。
秋夜里纺织娘在井栏啼鸣，
微霜浸透了竹席分外清寒。
孤灯昏暗暗思情无限浓烈，
卷起窗帘望明月仰天长叹。
亲爱的人相隔在九天云端。
上面有长空一片渺渺茫茫，
下面有清水卷起万丈波澜。
天长路远日夜跋涉多艰苦，
梦魂也难飞越这重重关山。
日日夜夜地思念啊，相思之情痛断心肝。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929c911759740c9b1a2d", "shortContent": "开元十八年（730），李白自安陆（治所在今湖北云梦县）取道南阳（治所在今河南南阳市），西入长安（今陕西西安市），干谒玉真公主不遇。当年秋天，被安置于公主别馆。别馆距长安百里，当时已是一所荒园。诗人遭此冷遇，曾作《玉真公主别馆苦雨赠卫尉张卿二首》向驸马张垍陈情。本篇情景与之相近，当为同期之作。\n“长相思”本汉代诗中语（如《古诗》：“客从远方来，遗我一书札。上言长相思，下言久离别”），六朝诗人多以名篇...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f09309", "shortContent": "长相思，古代乐府中属《杂曲歌辞》，多以“长相思”起首，末以三字作结，咏男女相思缠绵之意。李白所作《长相思》共三首，本处选其二首，均表达闺中少妇对远戍丈夫的思念之深、相思之苦。\n\n第一首从长安闺中少妇的无穷思念起笔，表达对丈夫痛断心肝的强烈思念。身在深闺中的少妇，身处秋夜，对丈夫的思念无时无刻，无处不在。“络纬秋啼金井阑，微霜凄凄簟色寒。”秋夜的庭院，纺织娘在井栏啼鸣，微霜浸透了竹席，显得分外清凉。...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6466e742b6a81d0c53fc7681", "shortContent": "开元十八年（730），李白自安陆（治所在今湖北云梦县）取道南阳（治所在今河南南阳市），西入长安（今陕西西安市），干谒玉真公主不遇。当年秋天，被安置于公主别馆。别馆距长安百里，当时已是一所荒园。诗人遭此冷遇，曾作《玉真公主别馆苦雨赠卫尉张卿二首》向驸马张垍陈情。本篇情景与之相近，当为同期之作。\n\n“长相思”本汉代诗中语（如《古诗》:“客从远方来，遗我一书札。上言长相思，下言久离别”），六朝诗人多以名...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '王薑斋：题中偏不欲显，象外偏令有馀，一以为风度，一以为淋漓，乌乎，观止矣。', 'indent', 1416860395, '57b1971ca633bd00570c1c7f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10521, '长相思（其二）', NULL, 242, 1052, 1, 2, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/415893.htm', '', '日色欲尽花含烟，月明欲素愁不眠。
赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。
此曲有意无人传，愿随春风寄燕然。
忆君迢迢隔青天，
昔日横波目，今作流泪泉。
不信妾肠断，归来看取明镜前。', '此诗以春花春风起兴，写女思男。望月怀思，抚琴寄情，忆君怀君，悱恻缠绵，真有“人比黄花瘦”之叹。
白描了思妇弹琴寄意、借曲传情、流泪断肠、望眼欲穿的情景，表现思妇对远征亲人的深情怀念。', '欲素：一作“如素”。
素：洁白的绢。
赵瑟：一种絃乐器，相传古代赵国人善奏瑟。
蜀琴：一种絃乐器，古人诗中以蜀琴喻佳琴。
燕然：山名，即杭爱山，在今蒙古人民共和国境内。此处泛指塞北。
横波：指眼波流盼生辉的样子。', '日色将尽花儿如含着烟雾，
月光如水心中愁闷难安眠。
刚停止弹拨凤凰柱的赵瑟，
又拿起蜀琴拨动那鸳鸯弦。
只可惜曲虽有意无人相传，
但愿它随着春风飞向燕然。
思念你隔着远天不能相见。
过去那双顾盼生辉的眼睛，
今天已成泪水奔淌的清泉。
假如不相信我曾多么痛苦，
请回来明镜里看憔悴容颜。', NULL, '', 'center', 1416860470, '57b8f64fdf0eea0063349b32', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10522, '兵车行', NULL, 249, 1416, 4, 5, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155566.htm', '', '车辚辚，马萧萧，行人弓箭各在腰，
耶娘妻子走相送，尘埃不见咸阳桥。
牵衣顿足拦道哭，哭声直上干云霄。
道旁过者问行人，行人但云点行频。
或从十五北防河，便至四十西营田。
去时里正与裹头，归来头白还戍边。
边庭流血成海水，武皇开边意未已。
君不闻，汉家山东二百州，
千村万落生荆杞。
纵有健妇把锄犁，禾生陇亩无东西。
况复秦兵耐苦战，被驱不异犬与鸡。
长者虽有问，役夫敢申恨？
且如今年冬，未休关西卒。
县官急索租，租税从何出。
信知生男恶，反是生女好。
生女犹得嫁比邻，生男埋没随百草。
君不见，青海头，古来白骨无人收。
新鬼烦冤旧鬼哭，天阴雨湿声啾啾。', '此诗是唐代伟大诗人杜甫创作的叙事诗。全诗以「道旁过者问行人」为界分为两段：首段摹写送别的惨状，是纪事；次段传达征夫的诉苦，是纪言。此诗具有深刻的思想内容，借征夫对老人的答话，倾诉了人民对战争的痛恨，揭露了唐玄宗长期以来的穷兵黩武，连年征战，给人民造成了巨大的灾难。全诗寓情于叙事之中，在叙述次序上参差错落前后呼应，变化开阖井然有序，并巧妙运用过渡句和习用词语，造成了回肠荡气的艺术效果。诗人自创乐府新题写时事，为中唐时期兴起的新乐府运动作出了开创性的贡献。', '兵车行：杜甫自创的乐府新题。行，本是乐府歌曲中的一种体裁。
辚（lín）辚：车行走时的声音。
萧萧：马蹄声。
行人：从军出征的人。
耶娘妻子：父亲、母亲、妻子、儿女的并称。从军的人既有十几岁的少年，也有四十多岁的成年人，所以送行的人有出征者的父母，也有妻子和孩子。
咸阳桥：又叫便桥，汉武帝时建，唐代称咸阳桥，后来称渭桥，在咸阳城西渭水上，是长安西行必经的大桥。
干（gān）：冲。
过者：路过的人。这里指诗人自己。
点行频：点名征兵频繁。点行，按户籍名册强徵服役。
或从十五北防河：有的人从十五岁就从军到西北区防河。唐玄宗时，吐蕃常于秋季入侵，抢掠百姓的收获。为抵御侵扰，唐王朝每年征调大批兵力驻扎河西（今甘肃河西走廊）一带，叫「防秋」或「防河」。
营田：即屯田。戍守边疆的士卒，不打仗时须种地以自给，称为营田。
里正与裹头：里正，唐制凡百户为一里，置里正一人管理。与裹头，给他裹头巾。新兵入伍时须着装整，因年纪小，自己还裹不好头巾，所以里正帮他裹头。
戍边：守卫边疆。
边庭：即边疆。
血流成海水：形容战死者之多。
武皇：汉武帝，这里借指唐玄宗。唐诗中借武皇代指玄宗。
武皇开边意未已：武皇扩张领土的意图仍没有停止。开边，用武力扩张领土。
汉家：汉朝，这里借指唐朝。
山东：古代秦居西方，秦地以东（或函谷关以东）统称「山东」。
二百州：唐代函谷关以东共二百一十七州，这里说「二百州」是举其整数。
汉家山东二百州：汉朝秦地以东的二百个州。
荆杞：荆棘和枸杞，泛指野生灌木。
千村万落生荆杞：成千上万的村落灌木丛生。这里形容村落的荒芜。
禾生陇亩无东西：庄稼长在田地里不成行列。陇亩，田地；陇，同「垄」；无东西，不成行列。
况复秦兵耐苦战：更何况关中兵能经受艰苦的战斗。况复，更何况；秦兵，关中兵，即这次出征的士兵。
长者：对老年人的尊称。这里是说话者对杜甫的称呼。
役夫：应政府兵役的人，这里是说话者的自称之词。
敢：副词，用于反问，这里是「岂敢」的意思。
申恨：诉说怨恨。
役夫敢申恨：我怎么敢申诉怨恨呢？
关西卒：函谷关以西的士兵，即秦兵。
县官：这里指官府。
信知：确实知道。
犹得嫁比邻：还能够嫁给同乡。得，能够。比邻，同乡。
青海头：指今青海省青海湖边。唐和吐蕃的战争，经常在青海湖附近进行。
烦冤：不满、愤懑。
啾啾：象声词，形容凄厉的叫声。', '大路上车轮滚滚战马嘶叫，出征的青年弓箭挂在腰间。
父母和妻儿纷纷跑来相送，灰尘弥漫天空不见咸阳桥。
亲人们牵衣领足拦路痛哭，凄惨的哭声直冲九天云霄。
过路的人站在旁边询问原因，回说官府征兵实在太频繁。
有人十五岁就到北方驻防，四十岁又被派到河西去营田。
走时年少里长替他缠头巾，归来时发已白又要去戍边。
边疆的战士已经血流成河，而皇上扩张领土没有穷尽。
你没听说华山东边二百里州，千村万寨野草丛生田荒芜。
即使那有健壮妇人来耕种，田里庄稼东倒西歪不成行。
即使关中兵能吃苦耐鏖战，被人驱遣与鸡狗没有两样。
老人说征夫怎敢诉说苦怨，今冬关西兵仍打仗未休整。
县官紧催租租税从哪里出？百姓相信生儿不如生女好。
生女还能嫁到街坊四邻处，生儿白死埋没在荒郊野草里。
你没看见在那青海的边上，自古以来白骨遍野无人收。
那里的新鬼含冤旧鬼痛哭，阴天冷雨凄惨哀叫声不断。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a703048e64fbd9137f", "shortContent": "天宝以后，唐王朝对西北、西南少数民族的战争越来越频繁。这连年不断的大规模战争，不仅给边疆少数民族带来沉重灾难，也给广大中原地区人民带来同样的不幸。\n据《资治通鉴》卷二百一十六载：“天宝十载（751）四月，剑南节度使鲜于仲通讨南诏蛮，大败于泸南。时仲通将兵八万，……军大败，士卒死者六万人，仲通仅以身免。杨国忠掩其败状，仍叙其战功。……制大募两京及河南北兵以击南诏。人闻云南多瘴疠，未战，士卒死者什八九...", "authors": ["郑庆笃"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d11c", "shortContent": "天宝以后，唐王朝对西北、西南少数民族的战争越来越频繁。这连年不断的大规模战争，不仅给边疆少数民族带来沉重灾难，也给广大中原地区人民带来同样的不幸。\n\n据《资治通鉴》卷二百一十六载：“天宝十载（751）四月，剑南节度使鲜于仲通讨南诏蛮，大败于泸南。时仲通将兵八万，……军大败，士卒死者六万人，仲通仅以身免。杨国忠掩其败状，仍叙其战功。……制大募两京及河南北兵以击南诏。人闻云南多瘴疠，未战，士卒死者什八...", "authors": ["郑庆笃"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f1ec26cbf3417f0930c", "shortContent": "战争与徭役总是给普通民众带来无边的灾难与痛苦。从《诗经》开始，中华文人就开始关注这一题材，抒写大众的这份苦难。至汉代，至唐代，世世传承，代未能衰。作为一位关心人民的诗人，杜甫也饱尝战乱流离之苦，故对此感触尤深。在这一领域，他倾注了较多的情感与笔墨，诗作成就也尤为突出。\n\n这首《兵车行》，即以雄浑饱满又低沉回环的笔墨，艺术地再现了兵役给人民带来的不幸。诗人情感的抒发在一个场景、一段“倾诉”中得以完成...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270607f0b9738b369b1eb", "shortContent": "战争与徭役总是给普通民众带来无边的灾难与痛苦。从《诗经》开始，中华文人就开始关注这一题材，抒写大众的这份苦难。至汉代，至唐代，世世传承，代未能衰。作为一位关心人民的诗人，杜甫也饱尝战乱流离之苦，故对此感触尤深。在这一领域，他倾注了较多的情感与笔墨，诗作成就也尤为突出。\n\n这首《兵车行》，即以雄浑饱满又低沉回环的笔墨，艺术地再现了兵役给人民带来的不幸。诗人情感的抒发在一个场景、一段“倾诉”中得以完成...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6464d6477f27182da3555b9d", "shortContent": "天宝以后，唐王朝对西北、西南少数民族的战争越来越频繁。这连年不断的大规模战争，不仅给边疆少数民族带来沉重灾难，也给广大中原地区人民带来同样的不幸。\n\n据《资治通鉴》卷二百一十六载：“天宝十载（751）四月，剑南节度使鲜于仲通讨南诏蛮，大败于泸南。时仲通将兵八万，……军大败，士卒死者六万人，仲通仅以身免。杨国忠掩其败状，仍叙其战功。……制大募两京及河南北兵以击南诏。人闻云南多瘴疠，未战，士卒死者什八...", "authors": ["郑庆笃"], "pressName": "上海辞书出版社"}]', '蔡启《蔡宽夫诗话》：齐梁以来，文士喜为乐府词，唯老杜《兵车行》、《悲青坂》、《无家别》等篇，皆因时事，自出己意立题，略不更蹈前人陈迹，真豪杰也。
胡应麟《诗薮》：乐府则太白擅奇古今，少陵嗣迹风雅，《蜀道难》、《远别离》等篇，出鬼入神，倘恍莫测；《兵车行》、《新婚别》等作，述情陈事，恳例如见。张王欲以拙胜，所谓差之厘毫；温李欲以巧胜，所谓谬以千里。
清高宗弘历《唐宋诗醇》：此体创自老杜，讽刺时事而托为征夫问答之词。言之者无罪，闻之者足以为戒，《小雅》遗音也。篇首写得行色匆匆，笔势汹涌，如风潮骤至，不可逼视。以下出点行之频，出开边之非，然后正说时事，末以惨语结之。词意沉郁，音节悲壮，此天地商声，不可强为也。
何焯《义门读书记》：篇中逐层相接，累累珠贯，弊中国以缴边功，农桑废而赋敛盖急，不待禄山作逆，而山东已有土崩之势矣。况畿辅根本亦空虚如是，一朝有事，谁与守耶？借汉喻唐，借山东以切关西，尤得体。
沈德潜《唐诗别裁集》：以人哭始，以鬼哭终，照应在有意无意。诗为明皇用兵吐蕃而作，设为问答，声音节奏，纯从古乐府得来。
王道俊《杜诗博议》：王深父云：时方用兵吐蕃，故托汉武事为刺，此说是也，黄鹤谓天宝十载，鲜于仲通丧师沪南，制大募兵击南诏，人莫肯应，杨国忠遣御史分道捕人，连枷送诣军前，故有「牵衣顿足」等语。按：明皇季年，穷兵吐蕃，征戍驿骚，内郡几遍，当时点行愁怨者不独征南一役，故公托为征夫自诉之词，以讥切之。若云惧杨国忠贵盛而诡其词于关西，则尤不然。太白《古风》云：「渡泸及五月，将赴云南征。怯卒非壮士，南方难远行。长号别严亲，日月惨光晶。位尽继以血，心摧两无声。」已明刺之矣，太白胡独不畏国忠耶？', 'center', 1416860632, '57b943e2128fe10054cbd00a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10523, '丽人行', NULL, 122, 1416, 4, 2, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/121580/5143417.htm', '', '三月三日天气新，长安水边多丽人。
态浓意远淑且真，肌理细腻骨肉匀。
绣罗衣裳照暮春，蹙金孔雀银麒麟。
头上何所有，翠微㔩叶垂鬓唇。
背后何所见，珠压腰衱稳称身。
就中云幕椒房亲，赐名大国虢与秦。
紫驼之峰出翠釜，水精之盘行素鳞。
犀箸厌饫久未下，鸾刀缕切空纷纶。
黄门飞鞚不动尘，御厨络绎送八珍。
箫鼓哀吟感鬼神，宾从杂遝实要津。
后来鞍马何逡巡，当轩下马入锦茵。
杨花雪落覆白蘋，青鸟飞去衔红巾。
炙手可热势绝伦，慎莫近前丞相嗔。', '唐代自武后以来，外戚擅权已成为统治阶层中一种通常现象，他们形成了一个特殊的利益集团，引起了广大人民的强烈不满，这也是后来酿成安史之乱的主因。《旧唐书·杨贵妃传》载：“玄宗每年十月，幸华清宫，国忠姊妹五家扈从。每家为一队，着一色衣；五家合队，照映如百花之焕发。而遗钿坠舄，瑟瑟珠翠，璨瓓芳馥于路。而国忠私于虢国，而不避雄狐之刺；每入朝，或联镳方驾，不施帷幔。每三朝庆贺，五鼓待漏，靓妆盈巷，蜡炬如昼。”又杨国忠于天宝十一年（公元752年）十一月拜右丞相兼文部尚书，势倾朝野。这首诗大约作于天宝十二年（公元753年）春。
此诗通过描写杨氏兄妹曲江春游的情景，揭露了统治者荒淫腐朽作威作福的丑态，从一个角度反映了安史之乱前夕的社会现实。诗分三段：先泛写游春仕女的体态之美和服饰之盛，引出主角杨氏姐妹的娇艳姿色；次写宴饮的豪华及所得的宠幸；最后写杨国忠的骄横。全诗场面宏大，鲜艳富丽，笔调细腻生动，讽刺含蓄不露，通篇只是写“丽人”们的生活情形，却正如前人所说的，达到了“无一刺讥语，描摹处语语刺讥；无一慨叹声，点逗处声声慨叹”的艺术效果。', '三月三日：为上巳日，唐代长安士女多于此日到城南曲江游玩踏青。
态浓：姿态浓艳。
意远：神气高远。
淑且真：淑美而不做作。
肌理细腻：皮肤细嫩光滑。
骨肉匀：身材匀称适中。
“绣罗衣裳（cháng）照暮春，蹙金孔雀银麒麟。”句：用金银线镶绣着孔雀和麒麟的华丽衣裳与暮春的美丽景色相映生辉。
翠微：薄薄的翡翠片。微，一本作“为”。
㔩（è）叶：一种首饰。
珠压：谓珠按其上，使不让风吹起，故下云“稳称身”。
腰衱（jié）：裙带。
就中：其中。
云幕：指宫殿中的云状帷幕。
椒房：汉代皇后居室，以椒和泥涂壁。后世因称皇后为椒房，皇后家属为椒房亲。
“赐名大国虢与秦”句：指天宝七载（公元748年）唐玄宗赐封杨贵妃的大姐为韩国夫人，三姐为虢国夫人，八姐为秦国夫人。
紫驼之峰：即驼峰，是一种珍贵的食品。唐贵族食品中有“驼峰炙”。
翠釜：形容锅的色泽。釜，古代的一种锅。
水精：即水晶。
行：传送。
素鳞：指白鳞鱼。
犀箸（zhù）：犀牛角作的筷子。
厌饫（yù）：吃饱，吃腻。
鸾刀：带鸾铃的刀。
缕切：细切。
空纷纶：厨师们白白忙乱一番。贵人们吃不下。
黄门：宦官。
飞鞚（kòng），即飞马。
八珍：形容珍美食品之多。
宾从：宾客随从。
杂遝（tà）：众多杂乱。
要津：本指重要渡口，这里喻指杨国忠兄妹的家门，所谓“虢国门前闹如市”。
后来鞍马：指杨国忠，却故意不在这里明说。
逡（qūn）巡：原意为欲进不进，这里是顾盼自得的意思。
“杨花雪落覆白蘋”句：是隐语，以曲江暮春的自然景色来影射杨国忠与其从妹虢国夫人（嫁裴氏）的暧昧关系，又引北魏胡太后和杨白花私通事，因太后曾作“杨花飘荡落南家”，及“愿衔杨花入窠里”诗句。后人有“杨花入水化为浮萍”之说，萍之大者为蘋。杨花、萍和蘋虽为三物，实出一体，故以杨花覆蘋影射兄妹苟且乱伦。据史载：“虢国素与国忠乱，颇为人知，不耻也。每入谒，并驱道中，从监、侍姆百余骑，炬密如昼，靓妆盈里，不施帏障，时人谓为雄狐。”
青鸟：神话中鸟名，西王母使者。相传西王母将见汉武帝时，先有青鸟飞集殿前（见《汉武故事》）。后常被用作男女之间的信使。
丞相：指杨国忠，天宝十一年（公元752年）十一月为右丞相。
“炙手可热势绝伦，慎莫近前丞相嗔（chēn）。”句：言杨氏权倾朝野，气焰灼人，无人能比。嗔，发怒。', '三月三日阳春时节天气清新，长安曲江河畔聚集好多美人。
姿态凝重神情高远文静自然，肌肤丰润胖瘦适中身材匀称。
绫花绫罗衣裳映衬暮春风光，金丝绣的孔雀银丝刺的麒麟。
头上戴的是什么珠宝首饰呢？翡翠玉做的花饰垂挂在两鬓。
在她们的背后能看见什么呢？珠宝镶嵌的裙腰多稳当合身。
其中有几位都是后妃的亲戚，里面有虢国和秦国二位夫人。
青黑色的蒸锅端出褐色驼峰，水晶圆盘送来鲜美的白鳞鱼。
她们捏着犀角筷子久久不动，厨师们快刀细切空忙了一场。
宦官骑马飞驰不敢扬起灰尘，御厨络绎不绝送来海味山珍。
笙箫鼓乐缠绵宛转感动鬼神，宾客随从满座都是达官贵人。
有一个骑马官人是何等骄横，车前下马从绣毯上走进帐门。
白雪似的杨花飘落覆盖浮萍，青鸟飞去衔起地上的红丝帕。
杨家气焰很高权势无与伦比，切勿近前以免丞相发怒斥人！', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a8dbb8b379ee0959cb", "shortContent": "《旧唐书·杨贵妃传》载：“玄宗每年十月，幸华清宫，国忠姊妹五家扈从。每家为一队，着一色衣；五家合队，照映如百花之焕发。而遗钿坠舄，瑟瑟珠翠，璨瓓芳馥于路。而国忠私于虢国，而不避雄狐之刺；每入朝，或联镳方驾，不施帷幔。每三朝庆贺，五鼓待漏，靓妆盈巷，蜡炬如昼。”又杨国忠于天宝十一载（752）十一月为右相。这首诗当作于十二载春，讽刺了杨家兄妹骄纵荒淫的生活，曲折地反映了君王的昏庸和时政的腐败。\n成功的...", "authors": ["陈贻焮"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151b8", "shortContent": "此诗为杜诗中直刺时事者，具体来说，是讽刺唐玄宗时代的宠妃杨氏及其家族骄奢淫乱的，是杜甫歌行中的名篇。\n\n三月三日，正是上巳节日，此日长安士女多喜游曲江。这天，杜甫也来到了曲江之边。作为一位旅食京华、求乞权门希望能得到荐引的寒士，杜甫虽然过着“朝扣富儿门，暮逐肥马尘”（《奉赠韦左丞丈二十二韵》）的生活，但在这和熙的春日，老杜总也有着游春的自由和兴致的。天下的美景，本来就是寒士与富贵人家所共有的啊。\n...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270607f0b9738b369b1ee", "shortContent": "此诗为杜诗中直刺时事者，具体来说，是讽刺唐玄宗时代的宠妃杨氏及其家族骄奢淫逸的，是杜甫歌行中的名篇。\n\n三月三日，正是上巳节，此日长安士女多喜游曲江。这天，杜甫也来到了曲江之边。作为一位旅食京华、求乞权门希望能得到荐引的寒士，杜甫虽然过着“朝扣富儿门，暮逐肥马尘”（《奉赠韦左丞丈二十二韵》）的生活，但在这和煦的春日，老杜总也有着游春的自由和兴致的。天下的美景，本来就是寒士与富贵人家所共有的啊！\n\n...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6464d99f45e4710056c558b4", "shortContent": "《旧唐书·杨贵妃传》载：“玄宗每年十月，幸华清宫，国忠姊妹五家扈从。每家为一队，着一色衣；五家合队，照映如百花之焕发。而遗钿坠舄，瑟瑟珠翠，璨[插图]芳馥于路。而国忠私于虢国，而不避雄狐之刺；每入朝，或联镳方驾，不施帷幔。每三朝庆贺，五鼓待漏，靓妆盈巷，蜡炬如昼。”又杨国忠于天宝十一载（752）十一月为右相。这首诗当作于十二载春，讽刺了杨家兄妹骄纵荒淫的生活，曲折地反映了君王的昏庸和时政的腐败。\n...", "authors": ["陈贻焮"], "pressName": "上海辞书出版社"}]', '《彦周诗话》：老杜作《丽人行》云：“赐名大国虢与秦。”其卒曰：“慎勿近前丞相嗔！”虢国、秦国何预国忠事，而近前即嗔耶？东坡言：老杜似司马迁。盖深知之。
《李杜诗选》：刘曰：三、四语便尔亲切，盖身亲见之，自与想象次第不同。此亦所当识也。又曰：画出次第宛然。“杨花”、“青鸟”二语，极当时拥从如云、冲拂开合、绮丽骄捷之盛；作者之意，自不必人人通晓也。
《唐诗归》：钟云：本是讽刺，而诗中直叙富丽，若深羡不容口者，妙，妙！如此富丽，一片清明之气行其中，标出以见富丽之不足为诗累。
《唐诗镜》：诗，言穷则尽，意亵则丑，韵软则卑。杜少陵《丽人行》，一以雅道行之，故君子言有则也。色古而厚，点染处，不免墨气太重。
《唐诗选脉会通评林》：周敬曰：起结中情，铺叙得体，气脉调畅，的从古乐府摹出，另成老杜乐府。吴山民曰：“头上”数语是真乐府，又跌宕而雅。周珽曰：“态浓”以后十句，模写丽人妖艳入神。想其笔兴酣时，不觉大家伎俩自不可禁。
《杜臆》：自“态浓意远”至“穿凳银”（按：杨用修谓“稳称身”后，尚有“穿凳银”等二句），极状姿色、服饰之盛；而后接以“就中云幕”二句，突然又起“紫驼之峰”四句，极状馔食之丰侈；而后接以“黄门飞鞚”二句，皆弇州所谓“倒插法”，唯杜能之者。……“紫驼之峰”二句，语对、意对而词义不对，与“裙拖六幅”“髻挽巫山”俱别一对法，诗联变体。……至“杨花”、“青鸟”两语，似不可解，而驺徒拥从之盛可想见于言外，真化工之笔。
《姜斋诗话》：“赐名大国虢与秦”，与“美孟姜矣”、“美孟弋矣”、“美孟孱矣”一辙，古有不讳之言也，乃《国风》之怨而诽、直而绞者也。夫子存而弗删以见卫之政散民离，人诬其上；而子美以得“诗史”之誉。
《唐诗评选》：可谓“入不言兮出不辞，乘回风兮载云旗”矣。是杜集中第一首乐府。杨用修犹嫌其末句之露，则为已甚。
《唐诗快》：通篇俱描画豪贵浓艳之景而讽刺自在言外。少陵岂非诗史？实有所指，转若无所指，故妙（首二句下）。何以体认亲切至此（“态浓意远”二句下）。
《杜诗详注》：此诗刺诸杨游宴曲江之事。……本写秦、虢冶容，乃概言丽人以檃括之，此诗家含蓄得体处。
《杜诗话》：《卫风·硕人》美之曰：“其颀”，自手而肤，而领而齿，而首而眉，而口而目，一一传神，此即《洛神赋》蓝本。《丽人行》为刺诸杨作，本写秦、虢冶容，首段却泛言游女以檃括之。曰“态浓意远淑且真”，状其丰神之丽也；“肌理细腻骨肉均”，状其体貌之丽也；“绣罗衣裳照暮春，蹙金孔雀银麒麟”，状其服色之丽也；头上“翠微㔩叶”，背后“珠压腰衱”，通身华丽俱见，与《洛神赋》另样写法。若如杨升庵伪本，添出“足下何所著”，尚成何诗体耶？
《唐诗别裁》：大意本《君子偕老》之诗，而风刺意较显。“态浓意远”下，倒插秦、虢；“当轩下马”下，倒插丞相；他人无此笔法。
《读杜心解》：“绣罗”一段，陈衣妆之丽，“紫驼”一段，陈厨膳之侈。而秦虢诸姨，却在两段中间点出，笔法活变。……末段以国忠正后作收，而“丞相”字直到煞句点出，冷隽。……“杨花雪落”、“青鸟衔巾”，隐语秀绝，妙不伤雅无一刺讥语，描摹处语语刺讥；无一慨叹声，点逗处声声慨叹。
《杜诗镜铨》：李安溪云：欧阳文忠言《春秋》之义，痛之深则词益隐，“一般卒”是也；刺之切则旨益微，《君子偕老》是也。此诗实与“美目巧笑”、“象揥绉絺”同旨。诗至老杜，乃可与《风》《雅》代兴耳。宋辕文曰：唐人不讳宫掖，拟之乐府，亦《羽林郎》之亚也。蒋弱六曰：美人相、富贵相、妖淫相，后乃现出罗刹相，真可笑可畏。', 'center', 1416860814, '57b934072e958a005fa6ff60', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (49503, '送华山隐之宗阳宫', NULL, 0, 264, 0, 1, '马祖常', NULL, 11184, '5858e637570c350069179ea8', '元', 'shi', '诗', NULL, NULL, '江阁鱼龙近，山房雾雨多。
地清天不暑，池曲水无波。
笋箨迎书带，樱桃送锦窠。
呦呦呼伴鹿，唼唼换经鹅。
养素行编屦，乘闲坐织蓑。
几篇餐玉法，一帙醮星科。
香灺沈银叶，衣裾佩紫荷。
丹光留海月，绛景出松萝。
醉忆泉浮乳，幽怜石烂柯。
神君攀绿桂，天女踏青莎。
邀客登山顶，寻真入涧阿。
洞箫吹道曲，云纸写鱼歌。
予发今如此，君心可奈何！
高谈见明月，为我问娑罗。', NULL, NULL, NULL, NULL, NULL, 'center', 1525426204, '585cee70da2f60006582f7e4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10524, '哀江头', NULL, 78, 1416, 2, 4, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155627.htm', '', '少陵野老吞声哭，春日潜行曲江曲。
江头宫殿锁千门，细柳新蒲为谁绿。
忆昔霓旌下南苑，苑中万物生颜色。
昭阳殿里第一人，同辇随君侍君侧。
辇前才人带弓箭，白马嚼啮黄金勒。
翻身向天仰射云，一箭正坠双飞翼。
明眸皓齿今何在，血污游魂归不得。
清渭东流剑阁深，去住彼此无消息。
人生有情泪沾臆，江水江花岂终极。
黄昏胡骑尘满城，欲往城南望城北。', '此诗前半首回忆唐玄宗与杨贵妃游幸曲江的盛事，後半首感伤贵妃之死和玄宗出逃，哀叹曲江的昔盛今衰，描绘了长安在遭到安史叛军洗劫後的萧条冷落景象，表达了诗人真诚的爱国情怀，及对国破家亡的深哀巨恸之情。全诗层次清晰，结构严整，首尾照应，艺术构思缜密，语言形象精练，给人以身临其境之感。
该诗作于至德二年（西元七五六年）春天。在这前一年诗人去灵武投奔肃宗的途中，被安禄山的叛兵俘虏带到了长安，後来逃出。诗中所写的就是当时在长安所见到的荒凉情景，回想起从前的盛况，悲愤之情贯穿全篇。在这首诗里，诗人流露的感情是深沉的，也是复杂的。当他表达出真诚的爱国激情的时候，也流露出对蒙难君王的伤悼之情。李唐盛世的挽歌，也是国势衰微的悲歌。全篇表现的，是对国破家亡的深哀巨恸。', '少陵：杜子美祖籍长安杜陵。少陵是汉宣帝许皇后的陵墓，在杜陵附近。杜子美曾在少陵附近居住过，故自称「少陵野老」。
吞声哭：哭时不敢出声。
潜行：因在叛军管辖之下，衹好偷偷地走到这里。
曲江曲：曲江的隐曲角落之处。
江头宫殿：《旧唐书·文宗纪》：「上（文宗）好为诗，每诵杜甫《曲江行》（即此篇）……乃知天宝以前，曲江四岸皆有行宫臺殿、百司廨署。」明·王于越《杜臆·卷二》：「曲江，帝与妃游幸之所，故有宫殿。」
「江头宫殿锁千门」句：写曲江边宫门紧闭，游人绝迹。
为谁绿：意思是国家破亡，连草木都失去了故主。
霓旌：云霓般的彩旗，指天子之旗。《文选·〈司马相如·上林赋〉》：「拖蜺（同『霓』）旌。」李善注引张揖曰：「析羽毛，染以五采，缀以缕为旌，有似虹蜺之气也。」南苑：指曲江东南的芙蓉苑。因在曲江之南，故称。
生颜色：万物生辉。
昭阳殿：汉代宫殿名。汉成帝皇后赵飞燕之妹为昭仪，居住于此。唐人多以赵飞燕比杨贵妃。
第一人：最得宠的人。
辇：皇帝乘坐的车子。古代君臣不同辇，此句指杨贵妃的受宠超出常规。
才人：宫中的女官。
嚼啮：齩。
黄金勒：用黄金做的衔勒。
仰射云：仰射云间飞鸟。
一箭：一作「一笑」，杨贵妃因才人射中飞鸟而笑。
正坠双飞翼：或亦暗寓唐玄宗和杨贵妃的马嵬驿之变。
「明眸皓齿今何在，血污游魂归不得」句：写安史之乱起，玄宗从长安奔蜀，路经马嵬驿，禁卫军逼迫玄宗缢杀杨贵妃。《旧唐书·杨贵妃传》：「及潼关失守，从幸至马嵬，禁军大将陈玄礼密启太子，诛国忠父子。既而四军不散，玄宗遣力士宣问，对曰：‘贼本尚在。’盖指贵妃也。力士复奏，帝不获已，与妃诀，遂缢死于佛室。时年三十八，瘗于驿西道侧。」
血污游魂：指杨贵妃缢死马嵬驿。
清渭：即渭水。
剑阁：即大剑山，在今四川省剑阁县的北面，是由长安入蜀必经之道。《太平御览·卷一六七》引《水经注》：「益昌有小剑城，去大剑城三十里，连山绝险，飞阁通衢，故谓之剑阁也。」
「清渭东流剑阁深，去住彼此无消息」句：明·仇兆鳌《杜少陵集详注·卷四》注：「马嵬驿，在京兆府兴平县（今属陕西省），渭水自陇西而来，经过兴平。盖杨妃藳葬渭滨，上皇（玄宗）巡行剑阁，市区住西东，两无消息也。」
去住彼此：指唐玄宗、杨贵妃。
「人生有情泪沾臆，江水江花岂终极」句：意谓江水江花年年依旧，而人生有情，则不免感怀今昔而生悲。以无情衬托有情，越见此情难以排遣。
终极：犹穷尽。
胡骑：指叛军的骑兵。
城北：一作「南北」。
望城北：走向城北。望，一作「忘」，北方口语，说向为望；
「欲往城南望城北」句：写极度悲哀中的迷惘心情。原注：「甫家住城南。」', '祖居少陵的野老（杜子美自称）无声地痛哭，春天偷偷地来到了曲江边。
江岸的宫殿千门闭锁，细细的柳丝和新生的水蒲为谁而绿？回忆当初皇帝的彩旗仪仗下了南苑，苑里的万物都生出光辉。
昭阳殿里的第一美人也同车出游，随侍在皇帝身旁。
车前的宫中女官带着弓箭，白马套着带嚼子的黄金马勒。
翻身朝天上的云层射去，一笑之间双飞的一对鸟儿便坠落在地。
杨贵妃明亮的眼睛和洁白的牙齿在哪里呢？鲜血玷污了她的游魂，再也不能归来！
清清的渭水向东流去，而玄宗所在的剑阁是那么深远。
走的和留下的彼此没有消息。
人生有情，泪水沾湿了胸臆，江水的流淌和江花的开放哪里会有尽头呢？
黄昏时，胡骑扬起满城的尘土，我想去城南，却走向城北。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a9911759740c9b1a73", "shortContent": "唐肃宗至德元年（756）秋天，杜甫离开鄜州（今陕西富县）去投奔刚即位的唐肃宗，不巧，被安史叛军抓获，带到沦陷了的长安。旧地重来，触景伤怀，诗人的内心是十分痛苦的。第二年春天，诗人沿长安城东南的曲江行走，感慨万千，哀恸欲绝。《哀江头》就是当时心情的真实记录。\n全诗分为三部分。\n前四句是第一部分，写长安沦陷后的曲江景象。曲江原是长安有名的游览胜地，经过开元年间疏凿修建，亭台楼阁参差，奇花异卉争芳，一到...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151b9", "shortContent": "这是一个凄恻哀伤的故事。\n\n故事背景：一位老人独自背负行囊，匆匆赶赴灵武。因为他刚刚听闻，在那里，肃宗即位！他暗自感叹，终于，收复长安有望了！（此前不久，长安为安史叛军所占。）不料，突然遭遇叛军，混乱之中，老人连同很多人一起都为叛军所获，被押赴长安！但因官微职小，老人得以幸免于囹圄。\n\n场景一：同样的地方，不一样的心情，在矛盾痛苦中，老人忍受了严冬的酷冷，眼见春回大地了。一天，他默默走出蜗居，来到...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270597f0b9738b369b1e4", "shortContent": "这是一个凄恻哀伤的故事。\n\n故事背景：一位老人独自背负行囊，匆匆赶赴灵武。因为他刚刚听闻，在那里，肃宗即位！他暗自感叹，终于，收复长安有望了！（此前不久，长安为安史叛军所占。）不料，突然遭遇叛军，混乱之中，老人连同很多人一起，都为叛军所获，被押赴长安！但因官微职小，老人得以幸免于难。\n\n场景一：同样的地方，不一样的心情，在矛盾痛苦中，老人忍受了严冬的酷冷，眼见春回大地了。一天，他默默走出蜗居，来到...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6464dd8930675327e18a5eea", "shortContent": "唐肃宗至德元年（756）秋天，杜甫离开鄜州（今陕西富县）去投奔刚即位的唐肃宗，不巧，被安史叛军抓获，带到沦陷了的长安。旧地重来，触景伤怀，诗人的内心是十分痛苦的。第二年春天，诗人沿长安城东南的曲江行走，感慨万千，哀恸欲绝。《哀江头》就是当时心情的真实记录。\n\n全诗分为三部分。前四句是第一部分，写长安沦陷后的曲江景象。曲江原是长安有名的游览胜地，经过开元年间疏凿修建，亭台楼阁参差，奇花异卉争芳，一到...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}]', '北宋·司马溫公《迂叟诗话》：唐曲江，开元天宝间旁有殿宇，安史乱後，其地尽废。文宗览杜甫诗云：「江头宫殿锁千门，细柳新蒲为谁绿。」因建紫云楼、落霞亭，岁时赐宴，又诏百司于两岸建亭馆焉。
北宋·苏颍滨《诗病五事》：《大雅·绵》九章，初诵太王迁邠，建都邑，营宫室而已。至其八章，乃曰「肆不殄厥愠，亦不陨厥问」，始及昆夷之怒，尚可也。至其九章，乃曰「虞芮质厥成，文王蹶厥生。予曰有疏附，予曰有先後，予曰有奔奏，予曰有御侮。」事不接，文不属，如连山断岭，虽相去绝远，而气象连络，观者知其脉理之为一也。盖附离不以凿枘，此最为文之高致耳。老杜陷贼时有诗曰：「少陵野老吞声哭……」予爱其词气如百金战马，注坡蓦涧，如履平地，得诗人之遗法。如白乐天诗词甚工，然拙于纪事，才步不遗，犹恐失之，此所以望老杜之藩垣而不及也。
南宋·魏菊庄《诗人玉屑·卷十四》：其词气如百金战马，注坡蓦涧，如履平地，得诗人之遗法。
南宋·张定复《岁寒堂诗话》：杨太真事，唐人吟咏至多，然类皆无礼。太真配至尊，岂可以儿女黩之耶？惟杜子美则不然。《哀江头》云：「昭阳殿里第一人，同辇随君侍君侧。」不待石「娇侍夜」、「醉和春」，而太真之专宠可知；不待云「玉容」、「梨花」，而太真之绝色可想也。至于言一时行乐事，不斥言太真，而但言辇前才人，此意尤不可及。如云：「翻身向天仰射云，一笑（「箭」一作「笑」）正坠双飞翼。」不待云「缓歌慢舞凝丝竹，尽日君王看不足」，而一时行乐可喜事，笔端画出，宛在目前。「江水江花岂终极」，不待云「比冀鸟」、「连理枝」、「此恨绵绵无尽期」，而无穷之恨、泰离麦秀之悲，寄于言外。……其词婉而雅，其意微而有礼，真可谓得风人之旨者。……元、白（《连昌宫词》、《长恨歌》）数十百言竭力摹写，不若子美一句，人才高下乃如此。
明·凌天池《唐诗广选》：李耆卿曰：此诗妙在「清渭」二句。明皇、肃宗一去一住，两无消息，父子之间，人所难言，子美能言之，非但「细柳新蒲」之感而已。
明·周青羊《唐诗选脉会通评林》：单复曰：同不迫而意已独至。刘辰翁曰：如何一句道尽（按指「细泖新蒲」句）！第常诵之云耳。周敬曰：「吞声哭」三字含悲无限！「清渭」二语怨深却又蕴藉，所以高妙。陆时雍曰：总于起结见情，中间叙事，以老拙见奇。吴山段曰：「潜行」二句有深意，尾句从「潜行」字说出。
明·王于越《杜臆》：「一箭」，山谷定为「一笑」，甚妙。曰「中翼」，则箭不必言；而鸟下云中，凡同在者虽百千人，无不哑然发笑，此宴游乐事。
明·仇知几《杜诗详注》：潘氏《杜诗博议》云：赵次公注引苏黄门尝谓其侄在进云：《哀江头》即《长恨歌》也。《长恨歌》费数百言而後成。杜言太真被宠，衹「昭阳殿里第一人」足矣；言从幸，衹「白马嚼啮黄金勒」足矣；言马嵬之死，衹「血污游魂归不得」足矣。
明末清初·潘力田《杜诗博议》：赵次公注引苏黄门，尝谓其侄在进云：《哀江头》即《长恨歌》也。《长恨歌》费数百言而後成，杜言太真被宠，衹「昭阳殿里第一人」足矣。言从幸，衹「白马嚼啮黄金勒」足矣。言马嵬之死，衹「血污游魂归不得」足矣。按黄门此论，上言诗法繁简不同耳，但《长恨歌》本因《长恨传》而作，公安得预知其事而为之兴哀。《北征》诗「不闻殷夏衰，中自诛褒妲」，公方以贵妃之死，卜国家中兴，岂应于此诗为天长地久之恨乎？
清·黄扶孟《杜诗说》：诗意本哀贵妃，不敢斥言，故借江头行幸处，标为题目耳。此诗半露半含，若悲若讯。天宝之乱，实扬氏为祸阶，杜公身事明皇，既不可直陈，又不敢曲违，如此用笔，浅深极为合宜。善述事者，但举一事，时众端可以包括，使人自得于其言外。若纤悉备记，文愈繁而味愈短矣。《长恨歌》，今古脍炙，而《哀江头》无称焉。雅音之不谐俗耳如此。
清·朱树田《增订唐诗摘钞》：写低头暗思，景象如画，此为善写「潜行」二字。
清·张絸斋《茧斋诗谈》：叙事檃括，不烦不简，有骏马跳涧之势。
清·乾隆帝《唐宋诗醇》：所谓对此茫茫，百端交集，何睱计及风刺乎？叙乱离处全以唱叹出之，不用实叙，笔力之高，真不可及。
清·沈归愚《唐诗别裁》：贵妃曰「同」、曰「随」、曰「侍」，似不免乎复；然《诗》有「高朗令终」，《传》有「远哉遥遥」等语，不必苛责（「同辇随君」句下）。「彼此无消息」，犹《长恨歌》云「一别人间两渺茫」也。结出心迷目乱，与入手「潜行」关照（「黄昏胡骑」二句下）。
清·浦起龙《读杜心解》：起四，写哀标意，浮空而来。次八，点清所哀之人，追叙其盛。「明眸」以下，跌落目前；而「去住彼此」，并体贴出明皇心事。「泪沾」、「花草」，则作者之哀声也，又回映多姿。
清·杨西木《杜诗镜铨》：蒋弱六云：苦音急调，千古魂消。邵子湘云：转折矫健，略无痕迹，苏黄门谓「如百金战马，注坡蓦涧，如履平地」，信然（《明眸皓齿」二句下）。
清·翁覃溪《石洲诗话·渔洋评杜摘记》：「乱离事衹叙得两句，『清渭』以下，以唱叹出之，笔力高不可攀，乐天《长恨歌》便觉相去万里。即两句亦是唱叹，不是实叙。」按：此西樵评，所说皆合，佴不必以《长恨歌》相较量耳。
清·施补华《岘佣说诗》：亦乐府。《丽人行》何等繁华，《哀江头》何等悲惨！两两相比，诗可以兴。
清末民国·高阆仙《唐宋诗举要》：「一箭」句叙苑中射猎，已暗中关合贵妃死马嵬事，何等灵妙！吴曰：更折入深处（「去住彼此」二句下）。悱恻缠绵，令人寻味无尽（「江水江花」句下）。', 'center', 1423215580, '57b93270165abd0054c16fd2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10525, '哀王孙', NULL, 28, 1416, 1, 2, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383217/10251131.htm', '', '长安城头头白乌，夜飞延秋门上呼。
又向人家啄大屋，屋底达官走避胡。
金鞭断折九马死，骨肉不待同驰驱。
腰下宝玦青珊瑚，可怜王孙泣路隅。
问之不肯道姓名，但道困苦乞为奴。
已经百日窜荆棘，身上无有完肌肤。
高帝子孙尽隆准，龙种自与常人殊。
豺狼在邑龙在野，王孙善保千金躯。
不敢长语临交衢，且为王孙立斯须。
昨夜东风吹血腥，东来橐驼满旧都。
朔方健儿好身手，昔何勇锐今何愚。
窃闻天子已传位，圣德北服南单于。
花门剺面请雪耻，慎勿出口他人狙。
哀哉王孙慎勿疏，五陵佳气无时无。', '此诗作于唐天宝十五年（756）安禄山犯长安后几个月。此诗先写安史之乱起，唐玄宗仓猝逃往成都的情景，再记叙王孙亲贵避乱匿身，后写国家乱极将治。作者在诗中既写了唐宗室逃离长安时连子弟都不能相顾的惊恐和王孙流落生的哀伤，也表现了诗人对他们的关切同情和对肃宗的希望。全诗写景抒情，真切生动，荡人胸怀，叙事利索，语气亲切，词色古泽，气魄宏大。', '白头乌：白头乌鸦，不祥之物。南朝梁末侯景作乱，有白头乌万计集于朱雀楼。
延秋门：唐玄宗曾由此出逃。
金鞭断折：指唐玄宗以金鞭鞭马快跑而金鞭断折。九马：皇帝御马。
宝玦：玉佩。
隅：角落。
高帝子孙：汉高祖刘邦的子孙。这里是以汉代唐。隆准：高鼻。
豺狼在邑：指安禄山占据长安。邑：京城。龙在野：指唐玄宗奔逃至蜀地。
临交衢：靠近大路边。衢：大路。
斯须：一会儿。
东风吹血腥：指安史叛军到处屠杀。
“朔方”句：指唐将哥舒翰守潼关的河陇、朔方军二十万，为安禄山叛军大败的事。
“窃闻”句：天宝十五载八月，玄宗在灵武传位于肃宗。
花门：即回纥。剺（lí）面：匈奴风俗在宣誓仪式上割面流血，以表诚意。这里指回纥坚决表示出兵助唐王朝平定安史之乱。
狙（jū）：伺察，窥伺。
五陵：五帝陵。佳气：兴旺之气。无时无：时时存在。', '长安城头，伫立着一只白头乌鸦，夜暮了，还飞进延秋门上叫哇哇。
这怪物，又向大官邸宅啄个不停，吓得达官们，为避胡人逃离了家。
玄宗出奔，折断金鞭又累死九马，皇亲国戚，来不及和他一同驱驾。
有个少年，腰间佩带玉玦和珊瑚，可怜呵，他在路旁哭得嗓子嘶哑。
千问万问，总不肯说出自己姓名，只说生活困苦，求人收他做奴伢！
已经有一百多天，逃窜荆棘丛下，身上无完肤，遍体是裂痕和伤疤。
凡是高帝子孙，大都是鼻梁高直，龙种与布衣相比，自然来得高雅。
豺狼在城称帝，龙种却流落荒野，王孙呵，你一定要珍重自己身架。
在十字路口，不敢与你长时交谈，只能站立片刻，交待你重要的话。
昨天夜里，东风吹来阵阵血腥味，长安东边，来了很多骆驼和车马。
北方军队，一贯是交战的好身手，往日勇猛，如今何以就流水落花。
私下听说，皇上已把皇位传太子，南单于派使拜服，圣德安定天下。
他们个个割面，请求雪耻上前线，你要守口如瓶，以防暗探的缉拿。
多可怜呵王孙，你万万不要疏忽，五陵之气葱郁，大唐中兴有望呀！', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151ba", "shortContent": "前人称少陵诗为诗史，史者，重在传述历史的真实面貌。杜甫在安史之乱时曾陷在长安围城之中，他的官位不高，还未被安史叛军重点搜捕，因此他在围城中见到了颇多当时的历史画面，再用他的如椽诗笔记录下来，便是最好的诗史之作。\n\n《哀王孙》一诗，是诗人为唐王朝宗室成员的命运而发。唐至德元年（756）七月，安禄山使人杀霍国长公主及王妃驸马等，又杀王孙及郡县主二十余人，唐王朝宗室留于长安者，面临着被集体屠杀的命运。此...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '王嗣奭《杜臆》：通篇哀痛顾惜，潦倒淋漓，似乱似整，断而复续，无一懈语，无一死字，真下笔有神。', 'center', 1416860992, '57b965de5bbb50005b7bb382', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10526, '经邹鲁祭孔子而叹之', NULL, 63, 76, 1, 1, '李隆基', NULL, 10127, '57bba5de7db2a20068cb2c28', '唐', 'shi', '诗', 'http://baike.baidu.com/view/346225.htm', '', '夫子何为者，栖栖一代中。
地犹鄹氏邑，宅即鲁王宫。
叹凤嗟身否，伤麟怨道穷。
今看两楹奠，当与梦时同。', '此诗是唐玄宗李隆基在公元725年亲祭孔子时所作的一首诗，诗中嗟叹了孔子复杂坎坷、栖遑不遇的一生，对孔子生前的际遇深表同情，对他寄予了深深的悼念。诗中连用数典，比较集中地概括了孔子心怀壮志而始终不得志的一生，表现了对孔子的尊崇，是中国封建社会中尊儒思想的反映。全诗命意严正，构思精巧，语言朴实，风格沉郁。', '鲁：今山东曲阜，为春秋时鲁国都城。
夫子：这里是对孔子的敬称。何为者：犹“何为乎”。者：无义。
栖栖：忙碌不安的样子，形容孔子四方奔走，无处安身。《论语·宪问》：“丘何为是栖栖者欤？”
鄹：春秋时鲁地，在今山东曲阜县东南。孔子父叔梁纥为鄹邑大夫，孔子出生于此，后迁曲阜。鄹氏邑：鄹人的城邑。
“宅即”句：相传汉鲁共（恭）王刘余（景帝子）曾坏孔子旧宅，以广其及升堂，闻金石丝竹之音，乃不敢坏。
“叹凤”句：《论语·子罕》：“子曰：凤鸟不至，河不出图，吾已矣夫。”说凤至象征圣人出而受瑞，今凤凰既不至，故孔子遂有身不能亲见圣之叹。否（pǐ）：不通畅，不幸。身否：身不逢时之意。
“伤麟”句：麟，瑞兽，象征太平盛世。相传孔子见人捕获了麟，曾大为悲痛地说：麟出而死，我的愿望无法实现了。见《公羊传·哀公十四年》：“麟者仁兽也，有王者则至，无王者则不至。有以告者，曰：‘有麕而角者。’孔子曰：‘孰为来哉！孰为来哉！’反袂拭面，涕沾袍。颜渊死，子曰：‘噫，天丧予！’子路死，子曰：‘噫，天祝予！’西狩获麟，孔子曰：‘吾道穷矣！’”
“今看”句：《礼记·檀弓上》，记孔子曾语子贡云：“予畴昔之夜，坐奠于两楹之间。……予殆将死也。”两楹奠：指人死后灵柩停放于两楹之间，喻祭祀的庄严隆重。两楹：指殿堂的中间。楹：堂前直柱。奠：致祭。
末二句大意为：孔子说他曾经夜梦自己坐于两柱之间受人祭奠，他的梦于今天实现了。', '尊敬的孔老夫子，你一生劳碌奔波，周游列国，究竟想要做成什么呢？如今这地方还是鄹县的城邑，你终被安葬在了出生的土地，然而你的旧宅曾被后人毁坏，改建为鲁王宫。在你生活的当时，凤鸟不至，你叹息命运不好；麒麟出现，你又忧伤哀怨，感叹世乱道穷。你一生不如意，看今日你端坐在堂前两楹间，接受后人的顶礼祭奠，正如同你生前梦境中所见的一样，想必你也该稍感慰藉了吧。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151bc", "shortContent": "此诗是唐玄宗于开元十三年（725）封禅泰山，还至曲阜时所作。\n\n“夫子何为者，栖栖一代中”，发语庄重而雄健。此处引《论语·宪问》：“微生亩谓孔子曰：‘丘何为？是栖栖者与？无乃为佞乎？’”写尽孔子一生事迹。栖栖是忙碌不安之貌，孔子为着“克己复礼”的理想，忙碌一生，少有安定之时。但在大时代中，像孔子这样的人不嫌其多，只嫌其少，因为孔子的伟大，就体现在他这忙碌的一生之中。“一代中”三个字，气势阔大沉雄，...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '沈德潜：孔子之道，从何处赞叹？故只就不遇立言，此即运意高处。
纪昀：只以唱叹取神最妙。”“五六句叹嗟伤怨，用字重复，虽初体常有之，然不可为训。', 'center', 1416909099, '57b9695e79bc44005ba24f94', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10527, '送杜少府之任蜀州', NULL, 1501, 132, 1, 18, '王勃', NULL, 10034, '57b9109fa633bd00665dcd5d', '唐', 'shi', '诗', 'http://baike.baidu.com/view/162637.htm', '', '城阙辅三秦，风烟望五津。
与君离别意，同是宦游人。
海内存知己，天涯若比邻。
无为在歧路，儿女共沾巾。', '此诗意在慰勉友人勿在离别之时悲哀。首联描画出送别地与友人出发地的形势和风貌，隐含送别的情意，严整对仗；颔联为宽慰之辞，点明离别的必然性，以散调相承，以实转虚，文情跌宕；颈联奇峰突起，高度地概括了「友情深厚，江山难阻」的情景，使友情升华到一种更高的美学境界；尾联点出「送」的主题，而且继续劝勉、叮咛朋友，也是自己情怀的吐露。此诗开合顿挫，气脉流通，意境旷达，堪称送别诗中的不世经典，全诗仅仅四十个字，却纵横捭阖，变化无穷，仿佛在一张小小的画幅上，包容着无数的丘壑，有看不尽的风光，至今广泛流传。', '少府：官名。之：到、往。蜀州：今四川崇州。
城阙（què）辅三秦：城阙，即城楼，指唐代京师长安城。辅，护卫。三秦，指长安城附近的关中之地，即今陕西省潼关以西一带。秦朝末年，项羽破秦，把关中分为三区，分别封给三个秦国的降将，所以称三秦。这句是倒装句，意思是京师长安三秦作保护。五津：指岷江的五个渡口白华津、万里津、江首津、涉头津、江南津。这里泛指蜀川。辅三秦：一作「俯西秦」。
风烟望五津：「风烟」两字名词用作状语，表示行为的处所。全句意为江边因远望而显得迷茫如啼眼，是说在风烟迷茫之中，遥望蜀州。
君：对人的尊称，相当于「您」。
同：一作「俱」。
宦（huàn）游：出外做官。
海内：四海之内，即全国各地。古代人认为我国疆土四周环海，所以称天下为四海之内。
天涯：天边，这里比喻极远的地方。
比邻：并邻，近邻。
无为：无须、不必。
歧（qí）路：岔路。古人送行常在大路分岔处告别。
沾巾：泪水沾湿衣服和腰带。意思是挥泪告别。', '雄伟长安城由三秦之地拱卫，透过那风云烟雾遥望着五津。
和你离别心中怀着无限情意，因为我们同是在宦海中浮沉。
只要在世上还有你这个知己，纵使远在天涯也如近在比邻。
绝不要在岔路口上分手之时，像小儿女那样悲伤泪湿佩巾。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e928c2e6a6b501f95be5e", "shortContent": "这是一首送别诗。首联属“工对”中的“地名对”，极壮阔，极精整。第一句写长安的城垣、宫阙被辽阔的三秦之地所“辅”（护持、拱卫），气势雄伟，点送别之地。第二句里的“五津”指岷江的五大渡口白华津、万里津、江首津、涉头津、江南津，泛指“蜀川”，点杜少府即将宦游之地；而“风烟”、“望”，又把相隔千里的秦、蜀两地连在一起。自长安遥望蜀川，视线为迷濛的风烟所遮，微露伤别之意，已摄下文“离别”、“天涯”之魂。\n因...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389abbb31680ae4c4b72f", "shortContent": "这是一首送别诗。首联属“工对”中的“地名对”，极壮阔，极精整。第一句写长安的城垣、宫阙被辽阔的三秦之地所“辅”（护持、拱卫），气势雄伟，点送别之地。第二句里的“五津”指岷江的五大渡口白华津、万里津、江首津、涉头津、江南津，泛指“蜀川”，点杜少府即将宦游之地；而“风烟”“望”，又把相隔千里的秦、蜀两地连在一起。自长安遥望蜀川，视线为迷蒙的风烟所遮，微露伤别之意，已摄下文“离别”“天涯”之魂。\n\n因首...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151be", "shortContent": "少府即县尉。杜少府是王勃的一位朋友，与王勃境遇相似，此次入蜀去赴县尉任，仍是偏佐之职。写作此诗时，王勃正在京城长安，任沛王府侍读，过着寄人篱下的生活。两个年轻人，虽然身处下僚，但他们对生活和未来仍有着很高的期望和希冀，对自己的才华也深信不疑，从而使这首送别诗劲爽刚健，具有同一般离别诗不一样的特色。\n \n首联发语浑厚。“城阙辅三秦”，点明送别的地点是在长安。唐时期的长安是世界上数一数二的大都市，更兼...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63126fe1f2af4e09d55b66d2", "shortContent": "少府即县尉。杜少府是王勃的一位朋友，与王勃境遇相似，此次人蜀去赴县尉任，仍是偏佐之职。写作此诗时，王勃正在京城长安，任沛王府侍读，过着寄人篱下的生活。两个年轻人，虽然身处下僚，但他们对生活和未来仍有着很高的期望和希冀，对自己的才能也深信不疑，从而使这首送别诗劲爽刚健，具有同一般离别诗不一样的特色。\n\n首联发语浑厚。“城阙辅三秦”，点明送别的地点是在长安。唐时期的长安是世界上数一数二的大都市，更兼其...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312702e9761253910e904bf", "shortContent": "少府即县尉。杜少府是王勃的一位朋友，与王勃境遇相似，此次入蜀去赴县尉任，仍是偏佐之职。写作此诗时，王勃正在京城长安，任沛王府侍读，过着寄人篱下的生活。两个年轻人，虽然身处下僚，但他们对生活和未来仍有着很高的期望和希冀，对自己的才能也深信不疑，从而使这首送别诗劲爽刚健，具有同一般离别诗不一样的特色。\n\n首联发语浑厚。“城阙辅三秦”，点明送别的地点是在长安。唐时期的长安是世界上数一数二的大都市，更兼其...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471eb73b6a81d0c532b112a", "shortContent": "这是一首送别诗。首联属“工对”中的“地名对”，极壮阔，极精整。第一句写长安的城垣、宫阙被辽阔的三秦之地所“辅”（护持、拱卫），气势雄伟，点送别之地。第二句里的“五津”指岷江的五大渡口白华津、万里津、江首津、涉头津、江南津，点杜少府即将宦游之地；而“风烟”“望”，又把相隔千里的秦、蜀两地连在一起。自长安遥望蜀州，视线为迷蒙的风烟所遮，微露伤别之意，已摄下文“离别”“天涯”之魂。\n因首联已对仗工稳，为...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '《批点唐音》：读《送卢主簿》并《白下驿》及此诗，乃知初唐所以盛，晚唐所以衰。
《增订评注唐诗正声》：郭云：苍然率然，多少感慨，说无为愁，我始欲愁。
《唐诗广选》：顾华玉曰：多少叹息，不见愁语。胡元瑞曰：唐初五言律唯王勃《送薛华》及此诗，终篇不着景物而气骨苍然，实首启盛、中妙境。
《唐诗镜》：此是高调，读之不觉其高，以气厚故。
《唐诗归》：此等作，取其气完而不碎，真律成之始也。其工拙自不必论，然诗文有创有修，不可靠定此一派，不复求变也。
《唐诗矩》：前后两截格。前二句实，后六句悉虚，恐笔力不到则易疏弱，此体固不足多尚。
《唐诗意》：慰安其情，开广其急，可作正小雅。
《唐诗三百首》：陈婉俊补注云：赠别不作悲酸语，魄力自异。
《古唐诗合解》：此等诗气格浑成，不以景物取妍，具初唐之风骨。
《唐诗近体》：前四句言宦游中作别，后四句翻出达见，语意迥不犹人，洒脱超诣，初唐风格。
《唐宋诗举要》：吴北江曰：壮阔精整（首二句下）。又曰：凭空挺起，是大家笔力（「海内」二句下）。姚曰：用陈思《赠白马王彪》诗意，实自浑转。
《诗境浅说》：一气贯注，如娓娓清谈，极行云流水之妙。大凡作律诗，忌支节横断，唐人律诗，无不气脉流通。此诗尤显。作七律亦然。
陈德公《闻鹤轩初盛唐近体读本》：通首质序，未免起率易之嫌。顾尔时开拓此境，声情婉上，正是绝尘处。陈伯玉之近调，高达夫之先驱也。五六直作腐语，气旺笔婉，不同学究。结强言耳，黯然之意，弥复神伤。', 'center', 1416909187, '57ad2ccac4c971005467dfc8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10528, '和晋陵陆丞早春游望', NULL, 168, 43, 3, 6, '杜审言', NULL, 10128, '57b44d79d342d3005b852f8b', '唐', 'shi', '诗', 'http://baike.baidu.com/view/350102.htm', '', '独有宦游人，偏惊物候新。
云霞出海曙，梅柳渡江春。
淑气催黄鸟，晴光转绿蘋。
忽闻歌古调，归思欲沾巾。', '此诗写诗人宦游他乡，春光满地不能归省的伤情。诗一开头就发出感慨，说明离乡宦游，对异土之「物候」才有「惊新」之意。中间二联具体写「惊新」，写江南新春景色，诗人怀念中原故土的情意。尾联点明思归和道出自己伤春的本意。这是一首和诗，采用拟人手法，写江南早春，历历如画。对仗工整，结构细密，字字锤炼。', '和：指用诗应答。
晋陵：现江苏省常州市。
宦游人：离家作官的人。
物候：指自然界的气象和季节变化．
淑气：和暖的天气。
绿蘋（pín）：浮萍。
古调：指陆丞写的诗，即题目中的《早春游望》。
巾：一作「襟」。', '只有远离故里外出做官之人，特别敏感自然物候转化更新。
海上云霞灿烂旭日即将东升，江南梅红柳绿江北却才回春。
和暖的春气催促着黄莺歌唱，晴朗的阳光下绿萍颜色转深。
忽然听到你歌吟古朴的曲调，勾起归思情怀令人落泪沾襟。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e928c2e6a6b501f95be5a", "shortContent": "这是一首和诗。原唱是晋陵陆丞作的《早春游望》。晋陵即今江苏常州，唐代属江南东道毗陵郡。陆丞，作者的友人，不详其名，时在晋陵任县丞。大约武则天永昌元年（689）前后，杜审言在江阴县任职，与陆某是同郡邻县的僚友。他们同游唱和，可能即在其时。陆某原唱已不可知。杜审言这首和诗是用原唱同题抒发自己宦游江南的感慨和归思。\n诗人在唐高宗咸亨元年（670）中进士后，仕途失意，一直充任县丞、县尉之类小官。到永昌元年...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389abbb31680ae4c4b72d", "shortContent": "这是一首和诗。原唱是晋陵陆丞作的《早春游望》。晋陵即今江苏常州，唐代属江南东道毗陵郡。陆丞，作者的友人，不详其名，时在晋陵任县丞。大约武则天永昌元年（689）前后，杜审言在江阴县任职，与陆某是同郡邻县的僚友。他们同游唱和，可能即在其时。陆某原唱已不可知。杜审言这首和诗是用原唱同题抒发自己宦游江南的感慨和归思。\n\n诗人在唐高宗咸亨元年（670）中进士后，仕途失意，一直充任县丞、县尉之类小官。到永昌元...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151c0", "shortContent": "杜审言是使唐代近体诗走向成型的重要诗人。本诗是他的名作。\n\n本诗是和诗，是和常州陆丞的《早春游望》诗的。但陆丞原诗早已不存，陆审言此诗却流传千载，实是诗歌的优劣使然。\n\n起句即突兀而警策。一个“独”字，一个“偏”字，惊矫不群，如凌云孤鹤，破空直上。一年之间物候的变化，感受最深的一定不是当地居家的人，而是由异地来此的宦游之人。“独”与“偏”两字，写尽了宦游之人的无奈与辛酸。他们的触觉是非常敏锐的，当...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '', 'center', 1416909585, '57b44d927db2a200546c77e3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639336, '水浒传 · 第六十八回 · 宋公明夜打曾头市 卢俊义活捉史文恭', NULL, 0, 124, 0, 1, '施耐庵', NULL, 10333, '57b9ebb3a633bd005d30998b', '明', 'wen', '文', '', '', '诗曰：
恢恢天网实无端，消息盈虚未易观。
不向公家尊礼度，却从平地筑峰峦。
宋江水浒心初遂，晁盖泉台死亦安。
天道好还非谬语，身亡家破不胜叹。
话说当时段景住跑来，对林冲等说道：“我与杨林、石勇前往北地买马。小弟到彼，选得壮窜有筋力好毛片骏马，买了二百余匹。回至青州地面，被一伙强人，为头一个唤做险道神郁保四，聚集二百余人，尽数把马劫夺，解送曾头市去了。石勇、杨林不知去向。小弟连夜逃来报知，可差人去讨马回山。”
关胜见说，教且回山寨与哥哥相见了，却商议此事。众人且过渡来，都到忠义堂上，见了宋江。关胜引单廷圭、魏定国与大小头领俱各相见了。李逵把下山杀了韩伯龙，遇见焦挺、鲍旭，同去打破凌州之事说了一遍。宋江听罢，又添四个好汉，正在欢喜。
段景住备说夺马一事，宋江听了，大怒道：“前者夺我马匹，今又如此无礼！晁天王的冤仇未曾报得，旦夕不乐。若不去报此仇，惹人耻笑！”吴用道：“即目春暖，正好厮杀。前者进兵失其地利，如今必用智取。”宋江道：“此仇深入骨髓，不报得誓不还山！”吴用道：“且教时迁，他会飞檐走壁，可去探听消息一遭，回来却作商量。”时迁听命去了。无三二日，只见杨林、石勇逃得回寨，备说曾头市史文恭口出大言，要与梁山泊势不两立。宋江见说，便要起兵。吴用道：“再待时迁回报，却去未迟。”宋江怒气填胸，要报此仇，片时忍耐不住，又使戴宗飞去打听，立等回报。不过数日，却是戴宗先回来说：“这曾头市要与凌州报仇，欲起军马。见今曾头市口扎下大寨，又在法华寺内做中军帐，五百里遍插旌旗，不知何路可进。”次日，时迁回寨报说：“小弟直到曾头市里面，探知备细。见今扎下五个寨栅。曾头市前面，二千余人守住村口。总寨内是教师史文恭执掌，北寨是曾涂与副教师苏定，南寨内是次子曾参，西寨内是三子曾索，东寨内是四子曾魁，中寨内是第五子曾升与父亲曾弄守把。这个青州郁保四，身长一丈，腰阔数围，绰号险道神，将这夺的许多马匹都喂养在法华寺内。”
吴用听罢，便教会集诸将，一同商议，“既然他设五个寨栅，我这里分调五支军将，可作五路去打他五个寨栅。”卢俊义便起身道：“卢某得蒙救命上山，未能报效，今愿尽命向前，未知尊意若何？”宋江大喜，便道：“员外如肯下山，便为前部。”吴用谏道：“员外初到山寨，未经战阵，山岭崎岖，乘马不便，不可为前部先锋。别引一支军马，前去平川埋伏，只听中军炮响，便来接应。”吴用主意只恐卢俊义捉得史文恭，宋江不负晁盖之遗言，让位与他，因此不允。宋江大意只要卢俊义建功，乘此机会，教他为山寨之主，不负晁盖遗言。吴用不肯，立主叫卢员外带同燕青，引领五百步军，平川小路听号。再分调五路军马：曾头市正南大寨，差马军头领霹雳火秦明、小李广花荣，副将马麟、邓飞，引军三千攻打；曾头市正东大寨，差步军头领花和尚鲁智深、行者武松，副将孔明、孔亮，引军三千攻打；曾头市正北大寨，差马军头领青面兽杨志、九纹龙史进，副将杨春、陈达，引军三千攻打；曾头市正西大寨，差步军头领美髯公朱仝，插翅虎雷横，副将邹渊、邹润，引军三千攻打；曾头市正中总寨，都头领宋公明，军师吴用、公孙胜，随行副将吕方、郭盛、解珍、解宝、戴宗、时迁，领军五千攻打。合后步军头领黑旋风李逵、混世魔王樊瑞，副将项充、李衮，引马步军兵五千。其余头领各守山寨。怎见得五军进发？但见：
梁山泊五军先锋，马军遇水叠桥；水浒寨六丁神将，步卒逢山开路。七星旗带，飘飘散天上乌云；八卦阵图，隐隐动山前虎豹。鞍上将齐披铁铠，坐下马都带铜铃。九洞妖魔离海内，十方神将降人间。
当下宋江部领五军兵将大进，正是枪刀流水急，人马撮风行。且说曾头市探事人探知备细，报入寨中。曾长官听了，便请教师史文恭、苏定商议军情重事。史文恭道：“梁山泊军马来时，只是多使陷坑，方才捉得他强兵猛将。这伙草寇，须是这条计，以为上策。”曾长官便差庄客人等，将了锄头、铁锹，去村口掘下陷坑数十处，上面虚浮土盖，四下里埋伏了军兵，只等敌军来到。又去曾头市北路，也掘下十数处陷坑。比及宋江军马起行时，吴用预先暗使时迁又去打听。数日之间，时迁回来报说：“曾头市寨南寨北尽都掘下陷坑，不计其数，只等俺军马到来。”吴用见说，大笑道：“不足为奇！”引军前进，来到曾头市相近。此时日午时分，前队望见一骑马来，项带铜铃，尾拴雉尾，马上一人，青巾白袍，手执短枪。前队望见，便要追赶，吴用止住。便教军马就此下寨，四面掘了濠堑，下了铁蒺藜。传令下去，教五军各自分投下寨，一般掘下濠堑，下了蒺藜。
一住三日，不出交战。吴用再使时迁扮作伏路小军，去曾头市寨中探听他不出何意；所有陷坑，暗暗地记着有几处，离寨多少路远，总有几处。时迁去了一日，都知备细，暗地使了记号，回报军师。次日，吴用传令，教前队步军各执铁锄，分作两队，又把粮车一百有余，装载芦苇干柴，藏在中军。当晚传令与各寨诸军头领：来日巳牌，只听东西两路步军先去打寨。再教攻打曾头市北寨的杨志、史进，把马军一字儿摆开。如若那边擂鼓摇旗，虚张声势，切不可进。吴用传令已了。
再说曾头市史文恭只要引宋江军马打寨，便着他陷坑。寨前路狭，待走那里去！次日巳牌，只听得寨前炮响。追兵大队都到南门。次后只见东寨边来报道：“一个和尚轮着铁禅杖，一个行者舞起双戒刀，攻打前后。”史文恭道：“这两个必是梁山泊鲁智深、武松。”犹恐有失，便分人去帮助曾魁。只见西寨边又来报道：“一个长髯大汉，一个虎面贼人，旗号上写着美髯公朱仝，插翅虎雷横，前来攻打甚急。”史文恭听了，又分拨人去帮助曾索。又听得寨前炮响，史文恭按兵不动，只要等他入来塌了陷坑，山后伏兵齐起，接应捉人。这里吴用却调马军，从山背后两路抄到寨前。前面步军只顾看寨，又不敢去；两边伏兵都摆在寨前，背后吴用军马赶来，尽数逼下坑去。史文恭却待出来，吴用鞭梢一指，军寨中锣响，一齐推出百余辆车子来，尽数把火点着，上面芦苇、干柴、硫黄、焰硝一齐着起，烟火迷天。比及史文恭军马出来，尽被火车横拦当住，只得回避，急待退军。公孙胜早在阵中挥剑作法，借起大风，刮得火焰卷入南门，早把敌楼、排栅尽行烧毁。已自得胜，鸣金收军。四下里入寨，当晚权歇。史文恭连夜修整寨门，两下当住。
次日，曾涂对史文恭计议道：“若不先斩贼首，难以追灭。”分付教师史文恭牢守寨栅。曾涂率领军兵，披挂上马，出阵搦战。怎生打扮？
头戴金盔，身披铁铠，腰系绒绦，坐骑快马。
弯弓插箭，体挂绯袍，脚踏宝镫，手拈钢枪。
当日曾涂上马，飞出阵来。宋江在中军闻知曾涂搦战，带领吕方、郭盛相随，出到前军。门旗影里看见曾涂，心怀旧恨，用鞭指道：“谁与我先捉这厮，报往日之仇，消向者之恨？”小温侯吕方拍坐下马，挺手中方天画戟，直取曾涂。两马交锋，军器并举。斗到三十合已上，郭盛在门旗下，看见两个中间将及输了一个。原来吕方本事迭不得曾涂，三十合已前，兀自抵敌得住，三十合已后，戟法乱了，只办得遮架躲闪。郭盛只恐吕方有失，便骤坐下马，拈手中方天画戟，飞出阵来，夹攻曾涂。三骑马在阵前绞做一团。原来两枝戟上都拴着金钱豹尾，吕方、郭盛要捉曾涂，两枝戟齐举。曾涂眼明，便用枪只一拨，却被两条豹尾搅住朱缨，夺扯不开。三个各要掣出军器使用。小李广花荣在阵中看见，恐怕输了两个，便纵马出来，左手拈起雕弓，右手急取鈚箭，搭上箭，拽满弓，望着曾涂射来。这曾涂却好掣出枪来，那两枝戟兀自搅做一团。说时迟，那时疾，曾涂掣枪，便望吕方项根搠来。花荣箭早先到，正中曾涂左臂，翻身落马，头盔倒卓，两脚蹬空。吕方、郭盛双戟并施，曾涂死于非命。十数骑马军飞奔回来，报知史文恭，转报中寨。曾长官听得大哭。有诗为证：
拍马横枪要出尖，当场挑战势翩翩。
不知暗中雕翎箭，一命悠悠赴九泉。
只见旁边恼犯了一个壮士曾升，武艺绝高，使两口飞刀，人莫敢近。当时听了大怒，咬牙切齿，喝教：“备我马来，要与哥哥报仇！”曾长官拦当不住。全身披挂，绰刀上马，直奔前寨。史文恭接着劝道：“小将军不可轻敌。宋江军中智勇猛将极多，若论史某愚意，只宜坚守五寨，暗地使人前往凌州，便教飞奏朝廷，调兵选将，多拨官军，分作两处征剿：一打梁山泊，一保曾头市。令贼无心恋战，必欲退兵急奔回山。那时史某不才，与汝弟兄一同追杀，必获大功。”说言未了，北寨副教师苏定到来，见说坚守一节，便道：“梁山泊吴用那厮，诡计多谋，不可轻敌，只宜退守。待救兵到来，从长商议。”曾升叫道：“杀我亲兄，此冤不报，更待何时！直等养成贼势，退敌则难。”史文恭、苏定阻当不住。曾升上马，带领数十骑马军，飞奔出寨搦战。
宋江闻知，传令前军迎敌。当时秦明得令，舞起狼牙棍，正要出阵斗这曾升。只见黑旋风李逵手搦板斧，直奔军前，不问事由，抢出垓心。对阵有人认的，说道：“这个是梁山泊黑旋风李逵。”曾升见了，便叫放箭。原来李逵但是上阵，便要脱膊，全得项充、李衮蛮牌遮护。此时独自抢来，被曾升一箭，腿上正着，身如泰山倒在地下。曾升背后马军齐抢过来。宋江阵上秦明、花荣飞马向前死救，背后马麟、邓飞、吕方、郭盛一齐接应归阵。曾升见了宋江阵上人多，不敢再战，以此领兵还寨。宋江也自收军驻扎。次日，史文恭、苏定只是主张不要对阵。怎禁得曾升催并道：“要报兄仇。”史文恭无奈，只得披挂上马。那匹马便是先前夺的段景住的千里龙驹照夜玉狮子马。宋江引诸将摆开阵势迎敌。对阵史文恭出马。怎生打扮？
头上金盔耀日光，身披铠甲赛冰霜。
坐骑千里龙驹马，生执朱缨丈二枪。
斯时史文恭出马，横杀过来。宋江阵上秦明要夺头功，飞奔坐下马来迎。二骑相交，军器并举。约斗二十余合，秦明力怯，望本阵便走。史文恭奋勇赶来，神枪到处，秦明后腿股上早着，倒攧下马来。吕方、郭盛、马麟、邓飞四将齐出，死命来救。虽然救得秦明，军兵折了一阵。收回败军，离寨十里驻扎。宋江叫把车子载了秦明，一面使人送回山寨将息，再与吴用商量。教取大刀关胜、金枪手徐宁，并要单廷圭、魏定国四位下出，同来协助。
宋江自己焚香祈祷，占卜一课。吴用看了卦象，便道：“虽然此处可破，今夜必主有贼兵入寨。”宋江道：“可以早作准备。”吴用道：“请兄长放心，只顾传下号令。”先去报与三寨头领，今夜起，东西二寨，便教解珍在左，解宝在右。其余军马，各于四下里埋伏已定。是夜，天晴月白，风静云闲。史文恭在寨中对曾升道：“贼兵今日输了两将，必然惧怯，乘虚正好劫寨。”曾升见说，便教请北寨苏定，南寨曾参，西寨曾索，引兵前来，一同劫寨。二更左侧，潜地出哨，马摘鸾铃，人披软战，直到宋江中军寨内。见四下无人，劫着空寨，急叫中计，转身便走。左手下撞出两头蛇解珍，右手下撞出双尾蝎解宝，后面便是小李广花荣，一发赶上。曾索在黑地里被解珍一钢叉搠于马下。放起火来，后寨发喊，东西两边，进兵攻打寨栅，混战了半夜。史文恭夺路得回。
曾长官又见折了曾索，烦恼倍增。次日，请史文恭写书投降。史文恭也有八分惧怯，随即写书，速差一人赍擎，直到宋江大寨。小校报知曾头市有人下书。宋江传令，教唤入来。小校将书呈上。宋江拆开看时，写道：
“曾头市主曾弄顿首再拜宋公明统军头领麾下：日昨小男倚仗一时之勇，误有冒犯虎威。向日天王率众到来，理合就当归附。奈何无端部卒施放冷箭，更兼夺马之罪，虽百口何辞。原之实非本意。今顽犬已亡，遣使讲和。如蒙罢战休兵，将原夺马匹尽数纳还，更赍金帛犒劳三军。此非虚情，免致两伤。谨此奉书，伏乞照察。”
宋江看罢来书，心中大怒，扯书骂道：“杀我兄长，焉肯干休！只待洗荡村坊，是我本愿。”下书人俯伏在地，凛颤不已。虽用慌忙劝道：“兄长差矣！我等相争，皆为气耳。既是曾家差人下书讲和，岂为一时之忿，以失大义。”随即便写回书，取银十两赏了来使。回还本寨，将书呈上。曾长官与史文恭拆开看时，上面写道：
“梁山泊主将宋江手书回复曾头市主曾弄帐前：国以信而治天下，将以勇而镇外邦。人无礼而何为，财非义而不取。梁山泊与曾头市自来无仇，各守边界。奈缘尔将行一时之恶，惹数载之冤。若要讲和，便须发还二次原夺马匹，并要夺马凶徒郁保四，犒劳军士金帛。忠诚既笃，礼数休轻。如或更变，别有定夺。草草具陈，情照不宣。”
曾长官与史文恭看了，俱各惊扰。次日，曾长官又使人到来言说：“若肯讲和，各请一人质当。”宋江不肯。吴用便道：“无伤！”随即便差时迁、李逵、樊瑞、项充、李衮五人前去为信。临行时，吴用叫过时迁，附耳低言：“如此如此，休得有误。”不说五人去了，却说关胜、徐宁、单廷圭、魏定国到了，当时见了众人，就在中军扎驻。
且说时迁引四个好汉来见曾长官。时迁向前说道：“奉哥哥将令，差时迁引李逵等四人前来讲和。”史文恭道：“吴用差遣五个人来，必然有谋。”李逵大怒，揪住史文恭便打。曾长官慌忙劝住。时迁道：“李逵虽然粗卤，却是俺宋公明哥哥心腹之人，特使他来，休得疑惑。”曾长官中心只要讲和，不听史文恭之言，便叫置酒相待，请去法华寺寨中安歇，拨五百军人前后围住，却使曾升带同郁保四来宋江大寨讲和。二人到中军相见了，随后将原夺二次马匹并金帛一车送到大寨。宋江看罢道：“这马都是后次夺的，正有先前段景住送来那匹千里白龙驹照夜玉狮子马，如何不见将来？”曾升道：“是师父史文恭乘坐着，以此不曾将来。”宋江道：“你疾忙快写书去，教早早牵那匹马来还我！”曾升便写书，叫从人还寨讨这匹马来。史文恭听得，回道：“别的马将去不吝，这匹马却不与他！”从人往复走了几遭，宋江定死要这匹马。史文恭使人来说道：“若还定要我这匹马时，着他即便退军，我便送来还他。”
宋江听得这话，便与吴用商议。尚然未决，忽有人来报道：“青州、凌州两路有军马到来。”宋江道：“那厮们知得，必然变卦！”暗传下号令，就差关胜、单廷圭、魏定国去迎青州军马，花荣、马麟、邓飞去迎凌州军马。暗地叫出郁保四来，用好言抚恤他，十分恩义相待，说道：“你若肯建这场功劳，山寨里也教你做个头领。夺马之仇，折箭为誓，一齐都罢。你若不从，曾头市破在旦夕。任从你心。”郁保四听言，情愿投拜，从命帐下。吴用授计与郁保四道：“你只做私逃还寨，与史文恭说道：‘我和曾升去宋江寨中讲和，打听得真实了。如今宋江大意，只要赚这匹千里马，实无心讲和。若还与了他，必然翻变。如今听得青州、凌州两路救兵到了，十分心慌。正好乘势用计，不可有误。’他若信从了，我自有处置。”郁保四领了言语，直到史文恭寨里，把前事具说一遍。史文恭引了郁保四来见曾长官，备说宋江无心讲和，可以乘势劫他寨栅。曾长官道：“我那曾升当在那里，若不翻变，必然被他杀害。”史文恭道：“打破他寨，好歹救了。今晚传令与各寨，尽数都起，先劫宋江大寨。如断去蛇首，众贼无用。回来却杀李逵等五人未迟。”曾长官道：“教师可以善用良计。”当下传令与北寨苏定、东寨曾魁、南寨曾参，一同劫寨。郁保四却闪来法华寺大寨内，看了李逵等五人，暗与时迁走透这个消息。
再说宋江同吴用说道：“未知此计若何？”吴用道：“如是郁保四不回，便是中俺之计。他若今晚来劫我寨，我等退伏两边，却教鲁智深、武松引步军杀入他东寨，朱仝、雷横引步军杀入他西寨，却令杨志、史进引马军截杀北寨。此名番犬伏窝之计，百发百中。”
当晚却说史文恭带了苏定、曾参、曾魁，尽数起发。是夜，月色朦胧，星辰昏暗。史文恭、苏定当先，曾参、曾魁押后，马摘鸾铃，人披软战，尽都来到宋江总寨。只见寨门不关，寨内并无一人，又不见些动静。情知中计，即便回身。急望本寨去时，只见曾头市里锣鸣炮响，却是时迁爬去法华寺钟楼上撞起钟来。声响为号，东西两门火炮齐响，喊声大举，正不知多少军马杀将入来。却说法华寺中李逵、樊瑞、项充、李衮一齐发作，杀将出来。史文恭等急回到寨时，寻路不见。曾长官见寨中大闹，又听得梁山泊大军两路杀将入来，就在寨里自缢而死。曾参径奔西寨，被朱仝一朴刀搠死。曾魁要奔东寨时，乱军中马踏为泥。苏定死命奔出北门，却有无数陷坑，背后鲁智深、武松赶杀将来，前逢杨志、史进，乱箭射死苏定。后头撞来的人马都攧入陷坑中去，重重叠叠，陷死不知其数。宋江众将得胜，在曾头市卷杀八面残兵，掳掠财物。有诗为证：
可怪曾家事不谐，投降特地贡书来。
宋江要雪天王恨，半夜驱兵卷杀来。
且说史文恭得这千里马行得快，杀出西门，落荒而走。此时黑雾遮天，不分南北。约行了二十余里，不知何处，只听得树林背后一声锣响，撞出四五百军来。当先一将，手提杆棒，望马脚便打。那匹马是千里龙驹，见棒来时，从头上跳过去了。史文恭正走之间，只见阴云冉冉，冷气飕飕，黑雾漫漫，狂风飒飒，虚空中一人当住去路。史文恭疑是神兵，勒马便回。东西南北四边，都是晁盖阴魂缠住。史文恭再回旧路，却撞着浪子燕青，又转过玉麒麟卢俊义来，喝一声：“强贼待走那里去！”腿股上只一朴刀，搠下马来，便把绳索绑了，解投曾头市来。燕青牵了那匹千里龙驹，径到大寨。宋江看了大喜。仇人相见，分外眼明。心中一喜一怒：喜者得卢员外见功；怒者恨史文恭射杀晁天王，冤仇未曾报得。先把曾升就本处斩首，曾家一门老少，尽数不留。抄掳到金银财宝，米麦粮食，尽行装载上车，回梁山泊给散各部头领，犒赏三军。
且说关胜领军杀退青州军马，花荣领兵杀散凌州军马，都回来了。大小头领不缺一个，又得了这匹千里龙驹照夜玉狮子马，其余物件尽不必说。陷车内囚了史文恭。便收拾军马，回梁山泊来。所过州县村坊，并无侵扰。
回到山寨忠义堂上，都来参见晁盖之灵。宋江传令，教圣手书生萧让作了祭文。令大小头领人人挂孝，个个举哀。将史文恭剖腹剜心，享祭晁盖已罢。宋江就忠义堂上与众弟兄商议立梁山泊之主。吴用便道：“兄长为尊，卢员外为次，其余众弟兄各依旧位。”宋江道：“向者晁天王遗言：‘但有人捉得史文恭者，不拣是谁，便为梁山泊之主。’今日卢员外生擒此贼，赴山祭献晁兄，报仇雪恨，正当为尊，不必多说。”卢俊义道：“小弟德薄才疏，怎敢承当此位！若得居末，尚自过分。”宋江道：“非宋某多谦，有三件不如员外处。第一件，宋江身材黑矮，貌拙才疏；员外堂堂一表，凛凛一躯，有贵人之相。第二件，宋江出身小吏，犯罪在逃，感蒙众弟兄不弃，暂居尊位；员外出身豪杰之子，又无至恶之名，虽然有些凶险，累蒙天祐，以免此祸。第三件，宋江文不能安邦，武又不能附众，手无缚鸡之力，身无寸箭之功；员外力敌万人，通今博古，天下谁不望风而降。尊兄有如此才德，正当为山寨之主。他时归顺朝廷，建功立业，官爵升迁，能使弟兄们尽生光彩。宋江主张已定，休得推托。”卢俊义恭谦拜于地下，说道：“兄长枉自多谈。卢某宁死，实难从命。”吴用劝道：“兄长为尊，卢员外为次，人皆所伏。兄长若如是再三推让，恐冷了众人之心。”原来吴用已把眼视众人，故出此语。只见黑旋风李逵大叫道：“我在江州，舍身拚命，跟将你来，众人都饶让你一步。我自天也不怕，你只管让来让去做甚鸟！我便杀将起来，各自散火！”武松见吴用以目示人，也发作叫道：“哥哥手下许多军官，受朝廷诰命的，也只是让哥哥，他如何肯从别人？”刘唐便道：“我们起初七个上山，那时便有让哥哥为尊之意。今日却要让别人？”鲁智深大叫道：“若还兄长推让别人，洒家们名自都散！”宋江道：“你众人不必多说，我自有个道理，尽天意看是如何，方才可定。”吴用道：“有何高见，便请一言。”宋江道：“有两件事。”正是：教梁山泊内重添两个英雄，东平府中又惹一场灾祸。直教天罡尽数投忠义，地煞齐临水浒来。毕竟宋江说出那两件事来，且听下回分解。', '', '', '', NULL, '', 'indent', 1537289380, '5ba0b7531b69e6005bd949fb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10529, '杂诗', NULL, 86, 154, 3, 2, '沈佺期', NULL, 10129, '57beed37c4c97100616ffaba', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/130767/9946122.htm', '', '闻道黄龙戍，频年不解兵。
可怜闺里月，长在汉家营。
少妇今春意，良人昨夜情。
谁能将旗鼓，一为取龙城。', '这是一首反战诗，是沈佺期的传世名作。这首诗极写闺中少妇与塞上征人的两地相忆，通过写闺中怨情揭露了战争给人民生活带来的痛苦，表达了诗人对人民的关切和同情。起句先说卫戌黄龙冈边土，年年不休。接着写一对情人各自东西，同披月光：闺中营中，清辉共照，柔情相忆，彼此黯然伤神。共同的愿望是有个名将能率领军队，一举破敌，结束战争，使天下亲人团聚。全诗抒发厌恶战争，渴望和平的心绪。', '闻道：听说。黄龙戍：即黄龙，在今辽宁开原县西北，为唐时边防要地，常戎兵于此。频年：连年。解兵：罢兵，撤兵。
今春：今年，实指年年，与“频年”照应。良人：古代妻子对丈夫的称呼。昨夜：实指夜夜。
将：率领。旗鼓：旗和鼓，军中表示号令之务。这里指代军队。龙城：匈奴祭天之处，在今蒙古人民共和国境内。', '早就听说黄龙城有战争，连续多年不见双方撤兵。
可怜闺中寂寞独自看月，她们思念之心长在汉营。
今晚上少妇的相思情意，正是昨夜征夫想家之情。
何时高举战旗擂鼓进军，但愿一鼓作气拿下龙城。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e928d7d0ac114549536eb", "shortContent": "这是沈佺期的传世名作之一。诗人类似“无题”的《杂诗》共有三首，都写闺中怨情，流露出明显的反战情绪。这一首诗除了怨恨“频年不解兵”外，还希望有良将早日结束战事，是思想上较为积极的一首，艺术上也颇具特色。\n首联叙事，交代背景：黄龙戍一带，常年战事不断，至今没有止息。一种强烈的怨战之情溢于字里行间。\n颔联抒情，借月抒怀，说今夜闺中和营中同在这一轮明月的照耀下，有多少对征夫思妇两地对月相思。在征夫眼里，这...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389abbb31680ae4c4b736", "shortContent": "这是沈佺期的传世名作之一。诗人类似“无题”的《杂诗》共有三首，都写闺中怨情，流露出明显的反战情绪。这一首诗除了怨恨“频年不解兵”外，还希望有良将早日结束战事，是思想上较为积极的一首，艺术上也颇具特色。\n\n首联叙事，交代背景：黄龙戍一带，常年战事不断，至今没有止息。一种强烈的怨战之情溢于字里行间。\n\n颔联抒情，借月抒怀，说今夜闺中和营中同在这一轮明月的照耀下，有多少对征夫思妇两地对月相思。在征夫眼里...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151c1", "shortContent": "这是一首闺怨诗，但诗里面有金戈铁马的壮丽之声。\n \n谁能将旗鼓，一为取龙城。\n\n黄龙戍在今辽宁开原西北，唐时为东北边防的要塞。首联借少妇之口，写出战事发生之地，而战事发生之地也就是这位独自伤神的少妇的丈夫所戍守的地方。“频年不解兵”，一个“频”字强调了战争之繁，间接表现了这位少妇的厌兵之感。\n\n“可怜闺里月，长在汉家营”，唐人多以汉代唐，为唐诗习语，而这位少妇与她的丈夫夫妻分离，唯一能将他们联系起...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270317f0b9738b369b195", "shortContent": "这是一首闺怨诗，但诗里面有金戈铁马的壮丽之声。\n\n黄龙戍在今辽宁开原西北，唐时为东北边防的要塞。首联借少妇之口，写出战事发生之地，而战事发生之地也就是这位独自伤神的少妇的丈夫所戍守的地方。“频年不解兵”，一个“频”字强调了频率之繁，间接表现了这位少妇的厌兵之感。\n\n“可怜闺里月，长在汉家营”，唐人多以汉代唐，为唐诗习语，而这位少妇与她的丈夫夫妻分离，唯一能将他们联系起来的就是天上的这轮明月。照在少...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '', 'center', 1416909949, '57bb0fabc4c9710061526027', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10530, '题大庾岭北驿', NULL, 139, 209, 2, 2, '宋之问', NULL, 10130, '57b9a06a2e958a00693191e7', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383242.htm', '', '阳月南飞雁，传闻至此回。
我行殊未已，何日复归来。
江静潮初落，林昏瘴不开。
明朝望乡处，应见陇头梅。', '此诗通过描写诗人在流放途中所见的景物及所想象的意象，借景抒情，引用一则“雁过梅岭”的奇妙传说，再结合自己当前的处境，抒发了诗人对官场坎坷的慨叹和思念家乡的感情。诗旨在写“愁”，全诗却未着“愁”字，情致凄婉，愁绪满怀，以情布景，又以景衬情，使情景融合，传情达意，因而情真意切，动人心弦。', '大庾（yǔ）岭：在江西、广东交界处，为五岭之一。北驿：大庾岭北面的驿站。
阳月：阴历十月。
传闻：传说，听说。
“我行”句：意谓自己要去的贬谪之地还远，所以自己还不能停下。殊未已：远远没有停止。殊，还。
瘴（zhàng）：旧指南方湿热气候下山林间对人有害的毒气。
望乡处：远望故乡的地方，指站在大庾岭处。
陇头梅：大庾岭地处南方，其地气候和暖，故十月即可见梅，旧时红白梅夹道，故有梅岭之称。陇头：即为“岭头”。陇，山陇。', '十月份南飞的大雁，听说到这就往回飞。
我的行程远没停止，不知何时还能回来？
江面平静潮水刚落，山林昏暗瘴气不开。
明晨登高望乡之处，应见岭头初绽红梅。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e928d5914587d02f4e424", "shortContent": "这是宋之问流放钦州（治所在今广西钦州东北）途经大庾岭时，题于岭北驿的一首五律。大庾岭在今江西大庾，岭上多生梅花，又名梅岭。古人认为此岭是南北的分界线，因有十月北雁南归至此，不再过岭的传说。\n本来，在武后、中宗两朝，宋之问颇得宠幸，睿宗执政后，却成了谪罪之人，发配岭南，其心中的痛苦哀伤自是可知。所以当他到达大庾岭北驿时，眼望那苍茫山色、长天雁群，想到明日就要过岭，一岭之隔，与中原便咫尺天涯，顿时迁谪...", "authors": ["张秉戍"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389abbb31680ae4c4b734", "shortContent": "这是宋之问流放钦州（治所在今广西钦州东北）途经大庾岭时，题于岭北驿的一首五律。大庾岭在今江西大余，岭上多生梅花，又名梅岭。古人认为此岭是南北的分界线，因有十月北雁南归至此，不再过岭的传说。\n\n本来，在武后、中宗两朝，宋之问颇得宠幸，睿宗执政后，却成了谪罪之人，发配岭南，其心中的痛苦哀伤自是可知。所以当他到达大庾岭北驿时，眼望那苍茫山色、长天雁群，想到明日就要过岭，一岭之隔，与中原便咫尺天涯，顿时迁...", "authors": ["张秉戍"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151c2", "shortContent": "唐中宗景龙元年（707），宋之问以谄附张易之兄弟，流放钦州。钦州在今广西，大庾岭是南下的必经之路。这就是宋之问在大庾岭北边的驿站里题的诗。\n\n首联的阳月，指农历的十月，这个月阳气始生，故称阳月。传说中北雁南飞，至湖南衡山而止。此处的“传闻”，当是另一异说。《唐会要》称：“五岭之外，翔雁不到。”极言五岭之险峻。前四句的诗意，是说十月雁南飞，据传到此岭而回。可我还有漫漫长路要跋涉，翻过了大庾岭去啊，何...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270309761253910e904da", "shortContent": "唐中宗景龙元年（707），宋之问以谄附张易之兄弟，流放钦州。钦州在今广西，大庾岭是南下的必经之路。这就是宋之问在大庾岭北边的驿站里题的诗。\n\n首联的阳月，指农历的十月，这个月阳气始生，故称阳月。传说中北雁南飞，至湖南衡山而回。此处的“传闻”，当是另一异说。《唐会要》称：“五岭之外，翔雁不到。”极言五岭之险峻。前四句的诗意，是说十月雁南飞，据传到此岭而回。可我还有漫漫长路要跋涉，翻过了大庾岭去啊，何...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '明代邢昉《唐风定》：凄咽欲绝。
清代姚鼐《五七言今体诗钞》：沉亮凄婉。
清代蘅塘退士《唐诗三百首》：四句一气旋折，神味无穷（首四句下）。', 'center', 1416910248, '57b953ab5bbb50005b7afe98', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10531, '寄左省杜拾遗', NULL, 97, 405, 2, 2, '岑参', NULL, 10096, '57b97daec4c971005593ac34', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383245.htm', '', '联步趋丹陛，分曹限紫微。
晓随天仗入，暮惹御香归。
白发悲花落，青云羡鸟飞。
圣朝无阙事，自觉谏书稀。', '这是一首委婉而含讽的诗，采用曲折隐晦的手法，感慨身世遭遇和发泄对朝廷不满的愤懑之情，名为赞朝廷无讽谏之事，实含深隐的讽刺之意。此诗辞藻华丽，雍容华贵，寓贬于褒，绵里藏针，有寻思不尽之妙。', '左省：门下省，居左署，故称「左省」。
杜拾遗：即杜甫，曾任左拾遗。
「联步趋丹陛」句：意为两人一起同趋，然后各归东西。联步：同行。丹陛：皇宫的红色台阶，借指朝廷。
曹：官署。
限：阻隔，引申为分隔。
紫微：古人以紫微星垣比喻皇帝居处，此指朝会时皇帝所居的宣政殿。中书省在殿西，门下省在殿东。
天仗：即仙仗，皇家的仪仗。
惹：沾染。
御香：朝会时殿中设炉燃香。
鸟飞：隐喻那些飞黄腾达者。
阙事：指缺点、过错。
自：当然。
谏书：劝谏的奏章。', '上朝时齐步同登红色台阶，分署办公又和你相隔紫微。
早晨跟着天子的仪仗入朝，晚上身染御炉的香气回归。
满头增白发悲叹春花凋落，遥望青云万里羡慕鸟高飞。
圣明的朝堂大概没有错事，规谏皇帝的奏章日渐稀疏。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b103572034f659e45d", "shortContent": "诗题中的“杜拾遗”，即杜甫。岑参与杜甫在唐肃宗至德二年至乾元元年初（757—758），同仕于朝；岑任右补阙，属中书省，居右署；杜任左拾遗，属门下省，居左署，故称“左省”。“拾遗”和“补阙”都是谏官。岑、杜二人，既是同僚，又是诗友。这是他们的唱和之作。\n前四句是叙述与杜甫同朝为官的生活境况。诗人连续铺写“天仗”、“丹陛”、“御香”、“紫微”，表面看，好像是在炫耀朝官的荣华显贵；但揭开“荣华显贵”的帷...", "authors": ["何庆善"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151c6", "shortContent": "此诗是岑参寄给同事杜甫的诗。此时岑参任右补阙，与杜甫左拾遗官职相近，职责亦相近，故有诗歌相和。其时间大概在肃宗乾元元年（758）。\n\n首联云“联步趋丹陛，分曹限紫微”，是讲两人有同事之谊，上朝之时，位列相近，共同并肩走上宫殿的台阶。后半句说明两人一居中书，一在门下，其所隶机构并不相同。时岑参为右补阙，属中书省，开元时中书省曾改为紫薇省；杜甫为左拾遗，属门下省，在禁中之东，故称。首联为起句，开始建构...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '《巩溪诗话》：岑参《寄杜拾遗》云：「圣朝无阙事，自觉谏书稀：退之《赠崔补阙》云：「年少得途未要忙，时清谏疏尤宜罕。」皆谬承荀卿「有所从，无谏诤」之语，遂使阿谀轩佞用以藉口。以是知凡造意立言，不可不预为天下后世虑。
《唐诗广选》：「白发」二语，托兴堪咏。
《唐诗直解》：写得雍容，有体有度，与子美《左掖》诗相敌。
《唐诗归》：谭云：伊、吕之言（「自觉」句下）。钟云：勿忽作颂圣谀语（「自觉」句下）。
《唐诗训解》：首二句言同朝不同曹者。结有体。
《唐诗归折衷》：吴敬夫云：多少规讽，寓于浑厚之中。
《唐诗观澜集》：气格苍浑，词旨温远，探得古人赠言之义，直堪与少陵旗鼓相当。
《唐诗别裁》：下半自伤迟暮无可建白也。感叹语以回护出之，方是诗人之旨。
《一瓢诗话》：岑嘉州「圣朝无阙事，自觉谏书稀」，正谓阙事甚多，不能诊缕上陈，托此微词。后人不察其心，至有以奸谀目之，亦属恨事。
《网师园唐诗笺》：婉而多风。
《闻鹤轩初盛唐近体读本》：陈德公曰：摩诘五律能备诸言，嘉州各篇惟工美隽，顾其赋分自天，姿韵绝俗，与王并配，岂有闲言。非有他警，而句字矜琢，体韵安雅，读之令人矜浮之气俱尽，岂非移情盛音也！汪献公曰：结笔犹是温然。
《瀛奎律髓汇评》：陆贻典：落句有含蓄。何义门：第七反言之，末句自省之词。「自觉」者，问心常有自负也，故是少陵同调语。「花落」则君子渐消，「鸟飞」则智士先去，是皆谏臣所不容坐视者也。句句有两层。纪昀：子美以建言获谴，平时必多露圭角，此诗有规之之意，而但言自甘衰朽，浮沉时世，则诗人温厚之旨也。五六寓意深微，末二句语尤婉至。圣朝既以为无阙，则谏书不得不稀矣。非颂语，乃愤语也。或乃缕陈天束阙窜驳此句，殆不足与言诗。无名氏：腹联炼沉思于五字，情景俱到。
《唐宋诗举要》：吴曰：能茹咽怀抱于笔墨之外，所以为绝调。', 'center', 1416910372, '57b8ee39c4c97100558eaaa4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10532, '赠孟浩然', NULL, 637, 1052, 4, 1, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155333.htm', '', '吾爱孟夫子，风流天下闻。
红颜弃轩冕，白首卧松云。
醉月频中圣，迷花不事君。
高山安可仰，徒此揖清芬。', '此诗是唐代诗人李白在湖北所作的一首五言律诗，全诗推崇孟浩然风雅潇洒的品格，全诗采用抒情、描写、抒情的方式，以一种舒展唱叹的语调，表达诗人的敬慕之情。
首联点题，抒发了对孟浩然的钦慕之情。二、三两联描绘了孟浩然摒弃官职，白首归隐，醉月中酒，迷花不仕的高雅形象。尾联直接抒情，把孟氏的高雅比为高山巍峨峻拔，令人仰止。', '孟夫子：指孟浩然。夫子，古时对男子的尊称。
风流：古人以风流赞美文人，主要是指有文采，善词章，风度潇洒，不钻营苟且等。王士源《孟浩然集序》说孟“骨貌淑清，风神散朗，救患释纷，以立义表。灌蔬艺竹，以全高尚。”
红颜：指孟浩然少壮时期。
白首：白头，指孟浩然晚年的时候。
卧松云：隐居。
中圣：“中圣人”的简称，即醉酒。曹魏时徐邈喜欢喝酒，称酒清者为“圣人”，酒浊者为贤人。中：读去声，动词，“中暑”、“中毒”之“中”，此为饮清酒而醉，故曰中圣。
“醉月频中圣”句：月下醉饮。
迷花：迷恋花草，此指陶醉于自然美景。
事君：侍奉皇帝。
高山：言孟品格高尚，令人敬仰。《诗经·小雅·车舝》：“高山仰止，景行行止”。
“徒此揖清芬”句：只有在此向您清高的人品致敬了。李白出蜀后，游江陵、潇湘、庐山、金陵、扬州、姑苏等地，然后回头又到了江夏。他专程去襄阳拜访孟浩然，不巧孟已外游，李白不无遗憾地写了这首诗，表达敬仰和遗憾之情。“高山安可仰，徒此揖清芬”二句，即透出仰慕而未能一见之意。', '我非常敬重孟先生的庄重潇洒，他为人高尚风流倜傥闻名天下。
少年时鄙视功名不爱官冕车马，高龄白首又归隐山林摒弃尘杂。
明月夜常常饮酒醉得非凡高雅，他不事君王迷恋花草胸怀豁达。
高山似的品格怎么能仰望着他？只在此揖敬他芬芳的道德光华！', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929dd635634aee3deb52", "shortContent": "本诗大致写在李白寓居湖北安陆时期（727—736），此时他常往来于襄汉一带，与比他长十二岁的孟浩然结下了深厚友谊。诗的风格自然飘逸，描绘了孟浩然风流儒雅的形象，同时也抒发了李白与他思想感情上的共鸣。\n李白的律诗，不屑为格律所拘束，而是追求古体的自然流走之势，直抒胸臆，透出一股飘逸之气。前人称：“太白于律，犹为古诗之遗，情深而词显，又出乎自然，要其旨趣所归，开郁宣滞，特于风骚为近焉。”（《李诗纬》）...", "authors": ["黄宝华"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151c7", "shortContent": "安陆可谓李白的第二故乡，在《上安州裴长史书》中，他写道：“见乡人相如大夸云梦之事，云楚有七泽，遂来观焉。”壮丽的风景吸引了他，在这里诗人大约度过了十年的时光，其间有些不太愉快的记忆，他多次干谒当地官员未成，反而得罪安州刺史，以致“谤言忽生，终口攒毁”，后来他把自己这段生活总结为“酒隐安陆，蹉跎十年”（《秋于敬亭送从侄耑游庐山序》）。但这十年，也有一些甜蜜与温馨的回忆。他高歌豪饮，语惊四座，得到了唐...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312704d73206168b2e021e6", "shortContent": "安陆可谓是李白的第二故乡，在《上安州裴长史书》中，他写道：“见乡人相如大夸云梦之事，云楚有七泽，遂来观焉。”壮丽的风景吸引了他，在这里诗人大约度过了十年的时光，其间有些不太愉快的记忆，他多次干谒当地官员未成，反而得罪安州刺史，以致“镑言忽生，众口攒毁”，后来他把自己这段生活总结为“酒隐安陆，蹉跎十年”（《秋於敬亭送从侄耑游庐山序》）。但这十年，也有一些甜蜜与温馨的回忆。他高歌豪饮，语惊四座，得到了...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6466fe5a45e4710056cdb07c", "shortContent": "本诗大致写在李白寓居湖北安陆时期（727—736），此时他常往来于襄汉一带，与比他长十二岁的孟浩然结下了深厚友谊。诗的风格自然飘逸，描绘了孟浩然风流儒雅的形象，同时也抒发了李白与他思想感情上的共鸣。\n\n李白的律诗，不屑为格律所拘束，而是追求古体的自然流走之势，直抒胸臆，透出一股飘逸之气。前人称：“太白于律，犹为古诗之遗，情深而词显，又出乎自然，要其旨趣所归，开郁宣滞，特于风骚为近焉。”（《李诗纬》...", "authors": ["黄宝华"], "pressName": "上海辞书出版社"}]', '《四溟诗话》：太白赠孟浩然诗，前云“红颜弃轩冕”，后云“迷花不事君”，两联意颇相似。刘文房《灵祐上人故居》诗，既云“几日浮生哭故人”，又云“雨花垂泪共沾巾”，此与太白同病。兴到而成，失于检点。意重一联，其势使然；两联意重，法不可从。
《唐宋诗举要》：吴曰：疏宕中仍自精炼（“醉月”二句下）。吴曰：开—笔（“高山”句下）。吴曰：一气舒卷，用孟体也，而其质健豪迈，自是太白手段，孟不能及。
《李太白诗醇》：严沧浪曰：矫然不变，三四十字尽一生。', 'center', 1416918370, '57b8c46ec4c97100558e3123', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10546, '送梓州李使君', NULL, 117, 394, 2, 1, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383315.htm', '', '万壑树参天，千山响杜鹃。
山中一夜雨，树杪百重泉。
汉女输橦布，巴人讼芋田。
文翁翻教授，不敢倚先贤。', '此诗是唐代诗人王维为送李使君入蜀赴任而创作的一首诗。诗人想象友人为官的梓州山林的壮丽景象以及风俗和民情，勉励友人在梓州创造业绩，超过先贤。此诗选取最能表现蜀地特色的景物，运用夸张手法加以描写，气象壮观开阔。全诗没有一般送别诗的感伤气氛，情绪积极开朗，格调高远明快，是唐诗中写送别的名篇之一。', '梓州：《唐诗正音》作「东川」。梓州是隋唐州名，治所在今四川三台。
李使君：李叔明，先任东川节度使、遂州刺史，后移镇梓州。
壑（hè）：山谷。
杜鹃：鸟名，一名「杜宇」，又名子规。
一夜雨：一作「一半雨」。
树杪（miǎo）：树梢。
汉女：汉水的妇女。
橦（tóng）布：橦木花织成的布，为梓州特产。
「巴人讼芋田」句：巴人常为农田事发生讼案。巴，古国名；芋田：蜀中产芋，当时为主粮之一。
文翁：汉景时为郡太守，政尚宽宏，见蜀地僻陋，乃建造学宫，诱育人才，使巴蜀日渐开化。
翻：翻然改变，通「反」。
先贤：已经去世的有才德的人。这里指汉景帝时蜀郡守。最后两句，纪昀说是「不可解」。赵殿成说是「不敢，当是敢不之误」。高眇瀛云：「末二句言文翁教化至今已衰，当更翻新以振起之，不敢倚先贤成绩而泰然无为也。此相勉之意，而昔人以为此二句不可解，何邪？」赵、高二说中，赵说似可采。', '万壑古树高耸云天，千山深处杜鹃啼啭。
山中春雨一夜未停，树丛梢头流淌百泉。
汉女辛劳织布纳税，巴人地少诉讼争田。
望你发扬文翁政绩，奋发有为不负先贤。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92950ce818559d058653", "shortContent": "赠别之作，多从眼前景物写起，即景生情，抒发惜别之意。王维此诗，立意则不在惜别，而在劝勉，因而一上来就从悬想着笔，遥写李使君赴任之地梓州（治今四川三台县）的自然风光，形象逼真，气韵生动，令人神往。\n开头两句互文见义，起得极有气势：万壑千山，到处是参天的大树，到处是杜鹃的啼声。既有视觉形象，又有听觉感受，读来使人恍如置身其间，大有耳目应接不暇之感。这两句气象阔大，神韵俊迈，被后世诗评家引为律诗工于发端...", "authors": ["刘德重"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e020a7", "shortContent": "这是一首赠别之作。梓州是隋唐州名，治所在今四川三台。友人将赴任梓州，王维作诗送别。王维送别诗颇多名篇，这首诗即其中之一。送别之作一般抒发对行人的思念与不舍，情感低回。但初盛唐诗歌中颇多跳出常格的佳作，如王勃《送杜少府之任蜀州》高唱“海内存知己，天涯若比邻”，高适《别董大》劝慰友人“莫愁前路无知己，天下谁人不识君”，都表现出开朗乐观情调。王维这首《送梓州李使君》同样能不落窠臼。诗人舍弃对临别情景的描...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646455095fc8182fe99c4983", "shortContent": "赠别之作，多从眼前景物写起，即景生情，抒发惜别之意。王维此诗，立意则不在惜别，而在劝勉，因而一上来就从悬想着笔，遥写李使君赴任之地梓州（治今四川三台县）的自然风光，形象逼真，气韵生动，令人神往。\n\n开头两句互文见义，起得极有气势：万壑千山，到处是参天的大树，到处是杜鹃的啼声。既有视觉形象，又有听觉感受，读来使人恍如置身其间，大有耳目应接不暇之感。这两句气象阔大，神韵俊迈，被后世诗评家引为律诗工于发...", "authors": ["刘德重"], "pressName": "上海辞书出版社"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "64645b20c0471b0062cb45e0", "shortContent": "赠别之作，多从眼前景物写起，即景生情，抒发惜别之意。王维此诗，立意则不在惜别，而在劝勉，因而一上来就从悬想着笔，遥写李使君赴任之地梓州（治今四川绵阳市三台县）的自然风光，形象逼真，气韵生动，令人神往。\n\n开头两句互文见义，起得极有气势：万壑千山，到处是参天的大树，到处是杜鹃的啼声。既有视觉形象，又有听觉感受，读来使人恍如置身其间，大有耳目应接不暇之感。这两句气象阔大，神韵俊迈，被后世诗评家引为律诗...", "authors": ["刘德重"], "pressName": "上海辞书出版社"}]', '《瀛奎律髓》：风土诗多因送人之官及远行，指言其方所习俗之异，清新隽永，唐人如此者极多。如许棠云「王租只贡金」，如周繇云「官俸请丹砂」，皆是。《王孟诗评》：顾云：「响」字奇。
《唐诗镜》：三四是山中人得景深后语。
《唐诗归》：谭云：玲然妙语，乃于送行诗得之，更妙（「树杪」句下）。锺云：「讼」字人不肯说，诗中说风土宜如此（「巴人」句下）。
《汇编唐诗十集》：唐云：好讼之俗宜先威明，不当倚文翁之教授。此见古人投赠有主意，不若今人竞作套语。
《唐诗选脉会通评林》：前四句通即送李之时景而成咏，音调高朗，缚有逸趣。陆伯生曰：起开爽有天趣。徐充曰：三四句对而意连极佳。陆放翁「小楼一夜听春雨，深巷明朝卖杏花」用此体。
《唐诗评选》：明明两截，幸其不作折合，五六一似景语故也。意至则事自恰合，与求事切题者雅俗冰炭。右丞工于用意，尤工于达意，景亦意，事亦意，前无古人，后无嗣者，文外独绝，不许有两。
《围炉诗话》：读王右丞诗，使人密气尘心都尽。《送梓州李使君》诗云：「万壑树参天，千山响杜鹃。山中一夜雨，树杪百重泉。」竟是山林隐逸诗。欲避近熟，故于梓州山境说起。下文……方说李使君。
《唐诗成法》：将梓州山水直写四句，声调高亮，令人陡然一惊，全不似送使君，只似闲适诗，妙极。下方写风俗、使君，七八有余意。
《近体秋阳》：形拟高雅，赠送周旋，无此天然恰称者矣。
《唐诗别裁》：斗绝（「万壑」句下）。从上蝉联而下，而本句中复用流水对，古人中亦偶见（「山中」二句下）。结意言时之所急在征戍，而文翁治蜀，翻在教授，准之当今，恐不敢倚先贤也。然此亦须活看。
《唐贤三昧集笺注》：好气势。前半如画。顾云：五六风俗俭薄处，亦见事简。又云：「不敢」二字勉词，若曰「得谓不敢乎」。
《网师园唐诗笺》：起势何等卓越（首四句下）！
《诗法易简录》：此诗起势尤为斗绝，三句承次句「山」字，四句承首句「树」字，一气相生相促，洵杰作也。
《瀛奎律髓汇评》：冯班：寻常景，写不出。钱湘灵；三联不是眼前语，他人何以道不出？查慎行：字字挑选。纪昀：起四句高调摩云，结二句不可解。
《唐贤清雅集》：落笔神妙，炼意工夫最深，人以为容易，不知其意匠经营惨淡也。
《唐宋诗举要》：吴曰：逆起神韵俊迈（「千山」联下）。吴曰：撰出奇语（「树杪」联下）。方植之曰：分顶上二语，而一气赴之，尤为龙跳虎卧之笔（「树杪」联下）。', 'center', 1416995563, '57b917c05bbb50005b78e6ba', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10533, '渡荆门送别', NULL, 1228, 1052, 3, 14, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/143065.htm', '', '渡远荆门外，来从楚国游。
山随平野尽，江入大荒流。
月下飞天镜，云生结海楼。
仍怜故乡水，万里送行舟。', '此诗是唐代伟大诗人李白青年时期在出蜀漫游的途中写下的一首五言律诗。诗由写远游点题始，继写沿途见闻和观感，后以思念作结，全诗意境高远，风格雄健，形象奇伟，想象瑰丽，以其卓越的绘景取胜，景象雄浑壮阔，表现了作者少年远游、倜傥不群的个性及浓浓的思乡之情。', '荆门：山名，位于今湖北省宜都县西北长江南岸，与北岸虎牙山对峙，地势险要，自古即有楚蜀咽喉之称。
远：远自。
楚国：楚地，指湖北一带，春秋时期属楚国。
平野：平坦广阔的原野。
江：长江。
大荒：广阔无际的田野。
月下飞天镜：明月映入江水，如同飞下的天镜。下，移下。
海楼：海市蜃楼，这里形容江上云霞的美丽景象。
仍：依然。
怜：怜爱。一本作「连」。
故乡水：指从四川流来的长江水。因诗人从小生活在四川，把四川称作故乡。
万里：喩行程之远。', '我乘舟渡江来到遥远的荆门外，来到战国时期楚国的境内游览。
高山渐渐隐去平野慢慢舒展开，江水一片仿佛流进广阔的莽原。
波中月影宛如天上飞来的明镜，空中彩云结成绮丽的海市蜃楼。
但我还是更爱恋故乡滔滔江水，它奔流不息陪伴着我万里行舟。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929e0f8fda55650553fc", "shortContent": "这首诗是李白出蜀时所作。荆门，即荆门山，位于今湖北宜都县西北，长江南岸，与北岸虎牙山隔江对峙，形势险要，自古即有楚蜀咽喉之称。\n李白这次出蜀，由水路乘船远行，经巴渝，出三峡，直向荆门山之外驶去，目的是到湖北、湖南一带楚国故地游览。“渡远荆门外，来从楚国游”，指的就是这一壮游。这时候的青年诗人，兴致勃勃，坐在船上沿途纵情观赏巫山两岸高耸云霄的峻岭。一路看来，眼前景色逐渐变化，船过荆门一带，已是平原旷...", "authors": ["何国治"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac821a74606fc40943", "shortContent": "这首诗是李白出蜀时所作。荆门，即荆门山，位于今湖北宜都西北，长江南岸，与北岸虎牙山隔江对峙，形势险要，自古即有楚蜀咽喉之称。\n\n李白这次出蜀，由水路乘船远行，经巴渝，出三峡，直向荆门山之外驶去，目的是到湖北、湖南一带楚国故地游览。“渡远荆门外，来从楚国游”，指的就是这一壮游。这时候的青年诗人，兴致勃勃，坐在船上沿途纵情观赏巫山两岸高耸云霄的峻岭。一路看来，眼前景色逐渐变化，船过荆门一带，已是平原旷...", "authors": ["何国治"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151c8", "shortContent": "青春年少的李白终于出川而来了。家乡之外的风物景色，从百家之书中他获得过基本印象，从种种传闻故事中他知道了大致轮廓，而想象的翅膀又曾多少次飞跃山川，进入楚天吴地。如今，放舟东来，顺流而下，一日千里，外面的世界即将出现在眼前，年轻的诗人怎能不激动万分？幽深的峡谷中，湍急的江面上，小舟如离弦之箭，两岸风光纷至沓来，层见叠出，令人眼花缭乱。\n\n冲出西陵峡，江流平缓，江面开阔，风景与峡中迥然不同。《水经注•...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127052c305cf0801816f5f", "shortContent": "青春年少的李白终于出川而来了。家乡之外的风物景色，从百家之书中他获得过基本印象，从种种传闻故事中他知道了大致轮廓，而想象的翅膀又曾多少次飞跃山川，进入楚天吴国。如今，放舟东来，顺流而下，一日千里，外面的世界即将出现在眼前，年轻的诗人怎能不激动万分。幽深的峡谷中，湍急的江面上，小舟如离弦之箭，两岸风光纷至沓来，层见叠出，令人眼花缭乱。\n \n冲出西陵峡，江流平缓，江面开阔，风景与峡中迥然不同。《水经注...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270a5e6f69b71e93f632c", "shortContent": "青春年少的李白终于出川而来了。家乡之外的风物景色，他从百家之书中获得过基本印象，从种种传闻故事中知道了大致轮廓，而想象的翅膀又曾多少次飞跃山川，进入楚天吴国。如今，放舟东来，顺流而下，一日千里，外面的世界即将出现在眼前，年轻的诗人怎能不激动万分。幽深的峡谷中，湍急的江面上，小舟如离弦之箭，两岸风光纷至沓来，层见叠出，令人眼花缭乱。\n\n冲出西陵峡，江流平缓，江面开阔，风景与峡中迥然不同。《水经注·江...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "646711945fc8182fe9a8003c", "shortContent": "这首诗是李白出蜀时所作。荆门，即荆门山，位于今湖北宜都县西北，长江南岸，与北岸虎牙山隔江对峙，形势险要，自古即有楚蜀咽喉之称。\n\n李白这次出蜀，由水路乘船远行，经巴渝，出三峡，直向荆门山之外驶去，目的是到湖北、湖南一带楚国故地游览。“渡远荆门外，来从楚国游”，指的就是这一壮游。这时候的青年诗人，兴致勃勃，坐在船上沿途纵情观赏巫山两岸高耸云霄的峻岭。一路看来，眼前景色逐渐变化，船过荆门一带，已是平原...", "authors": ["何国治"], "pressName": "上海辞书出版社"}]', '《升菴诗话》：太白《渡金（荆）门》诗：「仍怜故乡水，万里送行舟。」……寓怀乡之意。
《诗薮》：「山随平野阔，江入大荒流」，太白壮语也；杜「星垂平野阔，月涌大江流」，骨力过之。
《唐诗解》：此自蜀入楚，渡荆门而赋，其形胜如此。
《唐诗镜》：诗太近人，其病有二，浅而近人者，率也；易而近人者，俗也。如《荆门送别》诗，便不免此病。
《唐诗选脉会通评林》：周敬曰：三四雄壮，好形胜。
《唐诗评选》：明丽杲如初日。结二语，得象外于圜中。「飘然思不穷」，唯此当之。泛滥钻研者，正由思穷于本分耳。
《李太白全集》：王琦注：丁龙友曰：胡元瑞谓「山随平野尽，江入大荒流」，此太白壮语也；子美诗「星随平野阔，月涌大江流」二语，骨力过之。予谓李是昼景，杜是夜景；李是行舟暂视，杜是停舟细观：未可概论。
《精选五七言律耐吟集》：包举宇宙气象。
《石洲诗话》：太白云「山随平野尽，江入大荒流。」少陵云：「星随平野阔，月涌大江流。」此等句皆适与手会，无意相合，固不必谓相为倚傍，亦不容区分优劣也。
《闻鹤轩初盛唐近体读本》：三、四写形势，确不可易，复尔苍亮。五、六亦是平旷所见，语复警异。观此结，太白允是蜀人，语亦有情，未经人道。
《唐诗近体》：炼句雄阔，与杜匹敌（「山随」二句下）。
《唐宋诗举要》：语言倜傥，太白本色。
《诗境浅说》：太白天才超绝，用笔若风樯阵马，一片神行。……此诗首二句，言送客之地。中二联，写荆门空阔之景。惟收句见送别本意。图穷匕首见，一语到题。昔人诗文，每有此格。次联气象壮阔，楚蜀山脉，至荆州始断；大江自万山中来，至此千里平原，江流初纵，故山随野尽，在荆门最切。四句虽江行皆见之景，而壮健与上句相埒。后顾则群山渐远，前望则一片混茫也。五、六句写江中所见：以「天镜」喻月之光明，以「海楼」喻云之奇特。惟江天高旷，故所见如此；若在院宇中观云月，无此状也。末二句叙别意，言客踪所至，江水与之俱远，送行者心亦随之矣。', 'center', 1416918470, '57b9336079bc44005ba045ef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10534, '送友人', NULL, 1416, 1052, 4, 12, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/172276/5767490.htm', '', '青山横北郭，白水绕东城。
此地一为别，孤蓬万里征。
浮云游子意，落日故人情。
挥手自兹去，萧萧班马鸣。', '此诗是唐代诗人李白创作的一首充满诗情画意的送别诗，写得新颖别致，不落俗套。诗中青山，流水，红日，白云，相互映衬，色彩璀璨。班马长鸣，形象新鲜活泼，组成了一幅有声有色的画面。自然美与人情美交织在一起，写得有声有色，气韵生动，画面中流荡着无限温馨的情意，感人肺腑。', '郭：古代在城外修筑的一种外墙。
白水：清澈的水。
一：助词，加强语气。名做状。
别：告别。
蓬：古书上说的一种植物，乾枯后根株断开，遇风飞旋，也称「飞蓬」。诗人用「孤蓬」喻指远行的朋友。
征：远行。
浮云游子意：曹丕《杂诗》：「西北有浮云，亭亭如车盖。惜哉时不遇，适与飘风会。吹我东南行，行行至吴会。」后世用为典实，以浮云飘飞无定喻游子四方漂游。浮云，飘动的云；游子，离家远游的人。
兹：声音词。此。
萧萧：马的呻吟嘶叫声。
班马：离群的马，这里指载人远离的马。班，一作「斑」，分别、离别。', '青翠的山峦横卧在城墙的北面，波光粼粼的流水围绕着城的东边。
在此地我们相互道别，你就像孤蓬那样随风飘荡，到万里之外远行去了。
浮云像游子一样行踪不定，夕阳徐徐下山，似乎有所留恋。
挥挥手从此分离，友人骑的那匹将要载他远行的马萧萧长鸣，似乎不忍离去。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929f03048e64fbd9135a", "shortContent": "这是一首充满诗情画意的送别诗，诗人与友人策马辞行，情意绵绵，动人肺腑。\n首联“青山横北郭，白水绕东城”，点出告别的地点。诗人已经送友人来到了城外，然而两人仍然并肩缓辔，不愿分离。只见远处，青翠的山峦横亘在外城的北面，波光粼粼的流水绕城东潺潺而过。这两句，“青山”对“白水”，“北郭”对“东城”，首联即写成工丽的对偶句，确是别开生面；而且“青”、“白”相间，色彩明丽。“横”字勾勒青山的静姿，“绕”字描...", "authors": ["何国治"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac821a74606fc40944", "shortContent": "这是一首充满诗情画意的送别诗，诗人与友人策马辞行，情意绵绵，动人肺腑。\n\n首联“青山横北郭，白水绕东城”，点出告别的地点。诗人已经送友人来到了城外，然而两人仍然并肩缓辔，不愿分离。只见远处，青翠的山峦横亘在外城的北面，波光粼粼的流水绕城东潺潺而过。这两句，“青山”对“白水”，“北郭”对“东城”，首联即写成工丽的对偶句，确是别开生面；而且“青”“白”相间，色彩明丽。“横”字勾勒青山的静姿，“绕”字描...", "authors": ["何国治"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151c9", "shortContent": "友人即将远行，诗人不忍遽然相别，一路相送，直至东门之外。抬头眺望，横亘在城郭北侧的青山阻挡了诗人的视线；低头顾视，波光粼粼的流水绕城东潺潺而过，又阻挡着他们前行的步伐。送君千里，终有一别。两人并肩缓辔，低声喁语。友人此行，将如同孤飞的蓬草一样随风飘转，飞越万里之外。其行踪飘忽不定，又如天空中的白云。这次离别，不知何日才能再相见。聚散两依依，心中满是离情愁思，眼前景色也都沾染着离别的思绪。即将落山的...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127052c305cf0801816f60", "shortContent": "友人即将远行，诗人不忍遽然相别，一路相送，直至东门之外。抬头眺望，横亘在城郭北侧的青山阻挡了诗人的视线；低头顾视，波光粼粼的流水绕城东潺潺而过，又阻挡着他们前行的步伐。送君千里，终有一别。两人并肩缓辔，低声喁语。友人此行，将如同孤飞的蓬草一样随风飘转，飞越万里之外。其行踪飘忽不定，又如天空中的白云。这次离别，不知何日才能再相见。聚散两依依，心中满是离情愁思，眼前景色也都沾染着离别的思绪。即将落山的...", "authors": ["闲泽平"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270a5e6f69b71e93f632d", "shortContent": "友人即将远行，诗人不忍遽然相别，一路相送，直至东门之外。抬头眺望，横亘在城郭北侧的青山阻挡了诗人的视线；低头顾视，波光粼粼的流水绕城东潺潺而过，又阻挡着他们前行的步伐。送君千里，终有一别。两人并肩缓辔，低声喁语。友人此行，将如同孤飞的蓬草一样随风飘转，飞越万里之外。其行踪飘忽不定，又如天空中的白云。这次离别，不知何日才能再相见。聚散两依依，心中满是离情愁思，眼前景色也都沾染着离别的思绪。即将落山的...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6467137c45e4710056ce184c", "shortContent": "这是一首充满诗情画意的送别诗，诗人与友人策马辞行，情意绵绵，动人肺腑。\n\n首联“青山横北郭，白水绕东城”，点出告别的地点。诗人已经送友人来到了城外，然而两人仍然并肩缓辔，不愿分离。只见远处，青翠的山峦横亘在外城的北面，波光粼粼的流水绕城东潺潺而过。这两句，“青山”对“白水”，“北郭”对“东城”，首联即写成工丽的对偶句，确是别开生面；而且“青”、“白”相间，色彩明丽。“横”字勾勒青山的静姿，“绕”字...", "authors": ["何国治"], "pressName": "上海辞书出版社"}]', '仇兆鳌：太白诗「浮云游子意，落日故人情」对景怀人，意味深远。
朱谏《李诗选注》：句法清新，出于天授。唐人之为短律，率多雕琢，白自脑中流出，不求巧而自巧，非唐人所能及也。
沈德潜《唐诗别裁》：「三、四流走，竟亦有散行者，然起句必须整齐。苏、李赠言，多唏嘘语而无蹶蹙声，知古人之意在不尽矣，太白犹不失斯意。」
凌宏宪《唐诗广选》：蒋春甫曰：不如此接，便无生气（「此地」二句下）。
吴烻《唐诗直解》：评：不刻不浅，自是爽词。
《唐风怀》：质公曰：倏忽万里，念此黯然销魂。
《唐诗归折衷》：唐云：起极弘远（首二句下）。唐云：接得轻便（「此地」二句下）。唐云：结更凄楚（末二句下）。吴敬夫云：深情婉转，老致纷披，便可与老杜「带甲满天地」同读。
王尧衢《古唐诗合解》：前解叙送别之地，后解言送友之情。
屈复《唐诗成法》：「青山」、「白水」，先写送别之地，如此佳景为「孤篷万里」对照。「此地」紧接上二句，「一别」，送者、去者合写。五、六又分写。「自兹」二字，人、地总结。八止写「马鸣」，黯然销魂，见于言外。
爱新觉罗·弘历《唐宋诗醇》：首联整齐，承则流走，而下联健劲，结有萧散之致。大匠运斤，自成规矩。
施重光《唐诗近体》：每句整齐。结得洒脱，悠然不尽。
《精选五七言律耐吟集》：青莲五律无一首不意在笔先，扫尽人千百言，破空而下。
藤元粹《李太白诗醇》：严沧浪曰；五、六澹荡凄远，胜多多语。', 'center', 1416918569, '57b8facfd342d3005ac6ffb4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10535, '夜泊牛渚怀古', NULL, 173, 1052, 1, 2, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/172281.htm', '', '牛渚西江夜，青天无片云。
登舟望秋月，空忆谢将军。
余亦能高咏，斯人不可闻。
明朝挂帆席，枫叶落纷纷。', '此诗叙写诗人望月怀古，抒发不遇知音之伤感。首联开门见山点明“牛渚夜泊”及其夜景；颔联由望月过渡到怀古；颈联是由怀古回到现实，发出感慨，抒发不遇知音的深沉感喟；末联宕开写景，想象明朝挂帆远去的情景，烘托不遇知音之凄凉寂寞。全诗结构层次分明，波澜起伏，意象瑰丽，写景清新隽永而不粉饰，抒情豪爽豁达而不忸怩作态，意境高远，风格宏伟。', '牛渚：山名，在今安徽当涂县西北。诗题下有注：此地即谢尚闻袁宏咏史处。
西江：从南京以西到江西境内的一段长江，古代称西江。牛渚也在西江这一段中。
谢将军：东晋谢尚，今河南太康县人，官镇西将军，镇守牛渚时，秋夜泛舟赏月，适袁宏在运租船中诵己作《咏史》诗，音辞都很好，遂大加赞赏，邀其前来，谈到天明。袁从此名声大振，后官至东阳太守。
高咏：谢尚赏月时，曾闻诗人袁宏在船中高咏，大加赞赏。
斯人：指谢尚。
挂帆席：一作“洞庭去”。
挂帆：扬帆。
落：一作“正”。', '牛渚西江之夜万籁无声，无边无际的青天空无片云。
登船仰望秋月，想起了晋代谢尚将军。
我也能如袁宏吟诗，只是再也难遇知音，
明天扬帆而去，枫叶纷纷飘落。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a15e272d4b225431d0", "shortContent": "牛渚，是安徽当涂西北紧靠长江的一座山，北端突入江中，即著名的采石矶。诗题下有原注说：“此地即谢尚闻袁宏咏史处。”据《晋书·文苑传》记载：袁宏少时孤贫，以运租为业。镇西将军谢尚镇守牛渚，秋夜乘月泛江，听到袁宏在运租船上讽咏他自己的咏史诗，非常赞赏，于是邀宏过船谈论，直到天明。袁宏得到谢尚的赞誉，从此声名大著。题中所谓“怀古”，就是指这件事。\n从南京以西到江西境内的一段长江，古代称西江。首句开门见山，...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151cb", "shortContent": "作为中国古典诗词中的一种重要创作题材，怀古诗多以历史事件、历史人物、历史陈迹为题材，借登高望远、咏叹史实、怀念古迹来达到感慨兴衰、寄托哀思、托古讽今等目的。李白这首怀古诗，以夜宿牛渚山为起点，以晋代谢尚袁宏事为起兴，在追思先贤之余，抒发世无知音、个人不遇的深沉感喟。\n\n首联点明诗题，写牛渚山夜景。牛渚山坐落于西江之上，地势险峻，峭拔云天。夜凉如水，湛蓝的天空上没有一丝云彩。此处既交代了诗人秋夜行舟...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "646768285fc8182fe9a9dda8", "shortContent": "牛渚，是安徽当涂西北紧靠长江的一座山，北端突入江中，即著名的采石矶。诗题下有原注说：“此地即谢尚闻袁宏咏史处。”据《晋书·文苑传》记载：袁宏少时孤贫，以运租为业。镇西将军谢尚镇守牛渚，秋夜乘月泛江，听到袁宏在运租船上讽咏他自己的咏史诗，非常赞赏，于是邀宏过船谈论，直到天明。袁宏得到谢尚的赞誉，从此声名大著。题中所谓“怀古”，就是指这件事。\n\n从南京以西到江西境内的一段长江，古代称西江。首句开门见山...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '王士禛：不着一字，尽得风流。诗至于此，色相俱空，正如羚羊挂角，无迹可求，画家所谓逸品是也。
王琦：文从字顺，音韵铿锵。无一句属对，而调则无一字不律。', 'center', 1416918673, '57b9b0177db2a20068bdfb8a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10536, '春望', NULL, 1856, 1416, 3, 18, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/155622/4964449.htm', '', '国破山河在，城春草木深。
感时花溅泪，恨别鸟惊心。
烽火连三月，家书抵万金。
白头搔更短，浑欲不胜簪。', '天宝十四年（西元七五五年）十一月，安禄山起兵叛唐。次年六月，叛军攻陷潼关，唐玄宗匆忙逃往四川。七月，太子李亨即位于灵武（今属宁夏），世称肃宗，改元至德。杜少陵闻讯，即将家属安顿在都州，隻身一人投奔肃宗朝廷，结果不幸在途中被叛军俘获，解送至长安，后因官职卑微才未被囚禁。至德二年春，身处沦陷区的少陵目睹了长安城一片萧条零落的景象，百感交集，便写下了这首传诵千古的名作。
这首诗的前四句写春日长安凄惨破败的景象，饱含着兴衰感慨；后四句写诗人挂念亲人、心系国事的情怀，充溢着凄苦哀思。这首诗格律严整，颔联分别以「感时花溅泪」应首联国破之叹，以「恨别鸟惊心」应颈联思家之忧，尾联则强调忧思之深导致发白而稀疏，对仗精巧，声情悲壮，表现了诗人爱国之情。', '国：国都，指长安（今陕西西安）。
破：陷落。
山河在：旧日的山河仍然存在。
城：长安城。
草木深：指人烟稀少。
感时：为国家的时局而感伤。
溅泪：流泪。
恨别：怅恨离别。
烽火：古时边防报警的烟火，这里指安史之乱的战火。
三月：正月、二月、三月。
抵：值，相当。
白头：这里指白髮。
搔：用手指轻轻的抓。
浑：简直。
欲：想，要，就要。
不胜：受不住，不能。
簪：一种束发的首饰。古代男子蓄长髮，成年后束髮于头顶，用簪子横插住，以免散开。', '长安沦陷，国家破碎，只有山河依旧；春天来了，人烟稀少的长安城里草木茂密。
感于战败的时局，看到花开而潸然泪下，内心惆怅怨恨，听到鸟鸣而心惊胆战。
连绵的战火已经延续了一个春天，家书难得，一封抵得上万两黄金。
愁绪缠绕，搔头思考，白发越搔越短，简直要不能插簪了。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a9d635634aee3decc2", "shortContent": "唐肃宗至德元载（756）六月，安史叛军攻下唐都长安。七月，杜甫听到唐肃宗在灵武即位的消息，便把家小安顿在鄜州（今陕西富县）的羌村，去投奔肃宗。途中为叛军俘获，带到长安。因他官卑职微，未被囚禁。《春望》写于次年三月。\n诗的前四句写春城败象，饱含感叹；后四句写心念亲人境况，充溢离情。全诗沉着蕴藉，真挚自然。\n“国破山河在，城春草木深。”开篇即写春望所见：国都沦陷，城池残破，虽然山河依旧，可是乱草遍地，...", "authors": ["徐应佩", "周溶泉"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a74", "shortContent": "唐肃宗至德元载（756）六月，安史叛军攻下唐都长安。七月，杜甫听到唐肃宗在灵武即位的消息，便把家小安顿在鄜州（今陕西富县）的羌村，去投奔肃宗。途中为叛军俘获，带到长安。因他官卑职微，未被囚禁。《春望》写于次年三月。\n\n诗的前四句写春城败象，饱含感叹；后四句写心念亲人境况，充溢离情。全诗沉着蕴藉，真挚自然。\n\n“国破山河在，城春草木深。”开篇即写春望所见：国都沦陷，城池残破，虽然山河依旧，可是乱草遍...", "authors": ["徐应佩", "周溶泉"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151cc", "shortContent": "也许在我们尚未知道这首诗作的整体内容时，便早已熟悉了千古名句“感时花溅泪，恨别鸟惊心”。唐玄宗天宝十五载（756）六月，安史叛军攻陷长安，七月，太子李亨即位于灵武，世称肃宗。杜甫得闻，便把家小安置在鄜州（今陕西富县）的羌村，只身投奔肃宗。不料途中为叛军所获，被带到长安。但他终因位卑职小，未受囚禁。次年三月，感念国难，忆及亲人，杜甫满含深情写下此诗。\n转眼间，在乱离之中，又逢阳春三月。一个鸟语花香的...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270607f0b9738b369b1ef", "shortContent": "也许在我们尚未知道这首诗作的整体内容时，便早已熟悉了千古名句“感时花溅泪，恨别鸟惊心”。唐肃宗至德元载（756）六月，安史叛军攻陷长安，七月，肃宗即位灵武。杜甫得闻，便把家小安置在鄜州（今陕西富县）的羌村，只身投奔肃宗。不料途中为叛军所获，带到长安。但他终因位卑职小，未受囚禁。次年三月，感念国难、忆及亲人，杜甫满含深情写下此诗。\n\n转眼间，在乱离之中，又逢阳春三月。一个鸟语花香的晴日，诗人迈步在城...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270d3c26cbf3417f094fd", "shortContent": "也许在我们尚未知道这首诗作的整体内容时，便早已熟悉了千古名句“感时花溅泪，恨别鸟惊心”。唐肃宗至德元年（756）六月，安史叛军攻陷长安，七月，肃宗即位灵武。杜甫得闻，便把家小安置在鄜州（今陕西富县）的羌村，只身投奔肃宗。不料途中为叛军所获，带到长安。但他终因位卑职小，未受囚禁。次年三月，感念国难、忆及亲人，杜甫满含深情写下此诗。\n\n转眼间，在乱离之中，又逢阳春三月。一个鸟语花香的晴日，诗人迈步在城...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6464dd3445e4710056c56d8f", "shortContent": "唐肃宗至德元载（756）六月，安史叛军攻下唐都长安。七月，杜甫听到唐肃宗在灵武即位的消息，便把家小安顿在鄜州（今陕西富县）的羌村，去投奔肃宗。途中为叛军俘获，带到长安。因他官卑职微，未被囚禁。《春望》写于次年三月。\n\n诗的前四句写春城败象，饱含感叹；后四句写心念亲人境况，充溢离情。全诗沉着蕴藉，真挚自然。\n\n“国破山河在，城春草木深。”开篇即写春望所见：国都沦陷，城池残破，虽然山河依旧，可是乱草遍...", "authors": ["徐应佩", "周溶泉"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f6c330675327e1c0ec9d", "shortContent": "唐肃宗至德元载(756)六月，安史叛军攻下唐都长安。七月，杜甫听到唐肃宗在灵武即位的消息，便把家小安顿在鄜州（今陕西富县）的羌村，去投奔肃宗。途中为叛军俘获，带到长安。因他官卑职微，未被囚禁。《春望》写于次年三月。\n诗的前四句写春城败象，饱含感叹；后四句写心念亲人境况，充溢离情。全诗沉着蕴藉，真挚自然。\n“国破山河在，城春草木深。”开篇即写春望所见：国都沦陷，城池残破，虽然山河依旧，可是乱草遍地，...", "authors": ["徐应佩", "周溶泉"], "pressName": "上海辞书出版社"}]', '宋·司马温公《温公续诗话》：古人为诗，贵于意在言外，使人思而得之，故言之者无罪，闻之者足以耐也。近世诗人，唯杜子美最得诗人之体，如「国破山河在，城春草木深。感时花溅泪，恨别鸟惊心」。山河在，明无余物矣；草木深，明无人矣：花鸟，平时可娱之物，见之而泣，闻之而悲，则时可知矣。他皆类此，不可遍举。
宋·方虛谷《瀛奎律髓》：此第一等好诗。想天宝、至德以至大历之乱，不忍读也。
明·鍾退谷《唐诗归》：所谓愁思，看春不当春也。
明·胡赤城《唐音癸签》：对偶未尝不精，而纵横变幻，尽越陈规，浓淡浅深，动夺天巧，百代而下，当无复继。
明·王嗣奭《杜臆》：落句方思济世，而自伤其老。
清·何义门《义门读书记》：起联笔力千钧。……「感时」心长，「恨别」意短，落句故置家言国也。匡复无期，趋朝望断，不知此身得睹司隶章服否？只以「不胜簪」终之，凄凉含蓄。
清·吴齐贤《杜诗论文》：杜诗有点一字而神理俱出者，如「国破山河在」，「在」字则兴废可悲；「城春草木深」，「深」字则荟蔚满目矣。
清·陈石遗《石遗室诗话》：老杜五律，高调似初唐者，以「国破山河在」一首为最。
民国·高阆仙《唐宋诗举要》引吴汝伦曰：字字沉著，意境直似离骚。
今·李庆甲《瀛奎律髓汇评》引纪昀曰：语语沉着，无一毫做作，而自然深至。
今·顾驼菴《驼菴诗话》：（首联）在雄伟中有秀雅，壮美中有顾优美。
今·萧涤非《杜甫诗选》：关于「感时」句，有人认为花并不溅泪，但诗人有这样的感觉，因此，由带着露水的花联想到它也在流泪。按果如此说，溅字就很难讲通……溅是迸发，有跳跃义。……故此处「泪」仍以属人为是，所谓「正是花时堪下泪」也。又白乐天《闻早莺》有「鸟声信如一，分别在人情」，可与「鸟惊心」互参。
近·郁达夫《奉赠》诗之五：一纸家书抵万金，少陵此语感人深。
今·徐应佩、周溶泉等评此诗曰：意脉贯通而不平直，情景兼备而不游离，感情强烈而不浅露，内容丰富而不芜杂，格律严谨而不板滞。', 'center', 1416918782, '57b8feee0a2b58005c922fd5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (11853, '鹊桥仙 · 七夕送陈令举', NULL, 17, 3406, 1, 1, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', 'http://baike.baidu.com/subview/534337/9494845.htm', '', '缑山仙子，高情云渺，不学痴牛騃女。凤箫声断月明中，举手谢时人欲去。
客槎曾犯，银河波浪，尚带天风海雨。相逢一醉是前缘，风雨散、飘然何处？', '「缑山仙子，髙高情云渺，不学痴牛騃女」赞美王子乔仙心超远，若有若无，不去学习牛郎织女身陷情网，作茧自缚。「凤箫声断月明中，举手谢时人欲去」承接前文，刻画王子乔超凡脱俗的形象。王子乔吹箫奏凤凰之鸣，挥手告别时人，乘鹤而去，令人羡慕。王子乔放浪形骸、超凡成仙的形象，和放弃仙位陷于情网的织女形成强烈的对比，表现出词人渴望像王子乔一样能够遗世独立、羽化成仙的情志，也是词人对陈令举离别情思的开导之语。
「客槎曾犯，银河波浪，尚带天风海雨」借用晋人遇仙的神话故事，比况几位友人曾冲破银浪泛舟而行。「相逢一醉是前缘，风雨散、飘然何处」写欢乐的地方很少，很快就面临离别。「相逢一醉是前缘」，写自己和友人的相聚，「风雨散、飘然何处」，写朋友分别之後各自离去。「一醉是前缘」，含慰藉之意，「飘然何处」，蕴含无限的感慨之情。
全词不但摆脱了儿女艳情的旧套，借以抒写送别的友情，而且用事上紧扣七夕，格调上用飘逸超旷取代缠绵悱恻之风，读来深感词人的超凡脱俗以及卓而不群的姿态。', '鹊桥仙：词牌名。《风俗记》：「七夕，织女当渡河，使鹊为桥。」因取以为曲名，以咏牛郎织女相会事。此调有两体。五十六字者始自欧阳永叔，因词中有「鹊迎桥路接天津」句，取为调名。周美成词名《鹊桥仙令》；《梅苑》词名《忆人人》；韩涧泉词取秦少游词句，名《金风玉露相逢曲》；张东泽词有「天风吹送广寒秋」句，名《广寒秋》。元高拭词注「仙吕调」。以《淮海词》为正体，前後阕各两仄韵，一韵到底，亦有前後阕各四仄韵者，前後阕首两句要求对仗。八十八字者，始自柳屯田，《乐章集》注云：「歇指调」。
「七夕送陈令举」：吴讷钞本、《二妙集》本、毛本作「七夕」。
陈令举：龙榆生笺引《钦定大清一统志·卷五十四·〈湖州府·人物·陈舜俞〉》：「陈舜俞，字令举，乌程人。博学强记，登进士，又举制科第一。熙宁中，知山阴县。青苗法行，舜俞不奉令，上疏自劾，谪监南康军酒税，卒。苏轼为文哭之，称其学术才能，兼百人之器具。」
缑（Gōu）山仙子：龙榆生笺引《列仙传·王子乔》：「王子乔者，周灵王太子晋也。好吹笙，作凤凰鸣。游伊洛之间，道士浮丘公接以上嵩高山三十馀年。後求之于山上，见桓良曰：『告我家，七月七日待我于缑氏山巅。』至时，果乘白鹤驻山头，望之不得到。举手谢时人，数日而去。亦立祠于缑氏山下，及嵩高山首焉。」龙案缑氏山在今河南偃师县南。
痴牛騃（ái）女：指牛郎织女。此代指痴迷于俗世之芸芸众生。龙榆生笺引南朝梁·宗懔《荆楚岁时记》：「天河之东有织女，天帝之女也，年年机杼劳役，织成云锦天衣，容貌不暇整。天帝怜其独处，许嫁河西牵牛郎，嫁後遂废织纴（rèn）。天帝怒，责令归河东，许一年一度相会。」龙榆生笺、傅子立注并引唐·玉川子《月蚀》诗：「痴牛与騃女，不肯勤农桑。徒劳含淫思，夕旦遥相望。」刘尚荣按：「『夕旦』原作『旦夕』。」
举手谢时人：傅子立注：「《列仙传》：『王子晋者，周灵王太子也，好吹笙作凤鸣。游仙洛之间，道士浮丘公接上山，三十馀年，後来于山上告桓良曰：「我家七月七日，待我于缑氏山。」至日，果乘白鹤驻山头，望之不得到。举手谢时人而去。』」刘尚荣按：「事详《列仙传·王子乔》，又见《艺文聚类·卷四·〈岁时部·七月七日〉》、《艺文聚类·卷七·〈山部·嵩高山〉》及《太平广记·卷四·〈神仙·王子乔〉》，傅注多讹脱，至文理不通。今据《太平广记》录《列仙传》原文如次：『王子乔者，周灵王太子﹝晋﹞也。好吹笙，作凤鸣。游伊洛之间，道士浮丘公接以上嵩山，三十馀年。後求之于山，见桓良曰：『告我家，七月七日待我于缑氏山巅。』﹝至日﹞果乘白鹤，驻山头，望之不到。举手谢时人，数日而去。亦立祠于缑氏及嵩山。』」
客槎：傅子立注：「《博物志》：『近世有人居海上，每年八月，见海槎来，不违时。赍一年粮，乘之到天河。见妇人织，丈夫饮牛，问之不答。遣归，问严君平：「某年某月日，客星犯牛斗。」即此人也。』又云：『天河与海通。』」刘尚荣按：「晋·张茂先《博物志·卷十·杂说下》：『旧说云天河与海通，近世有人居海渚者，年年八月有浮槎去来，不失期。人有奇志，立飞阁于槎上，多赍粮，乘槎而去。十馀日中，犹观星月日辰，自後茫茫忽忽，亦不觉昼夜。去十馀日，奄至一处，有城郭状，屋舍甚严。遥望宫中多织妇，见天丈夫牵牛渚次饮之。牵牛人乃惊问曰：「何由至此？」此人具说来意，并问此是何处，答曰：「君还至蜀郡访严君平则知之。」竟不上岸，因还如期。後至蜀，问君平，曰：「某年月日有客星犯牵牛宿。」计年月，正是此人到天河时也。』傅注盖撮述大意而删略失当，致使文意不明矣。」
波浪：吴讷钞本、《二妙集》本、毛本作「微浪」。
风雨散：傅子立注：「《文选》曹子建诗：『风流云散，一别如雨。』」刘尚荣按：「此乃王仲宣《赠蔡子笃》诗句，见《文选·卷二十三·〈诗丙·赠答·王仲宣赠蔡子笃诗〉》。傅注误标作者。」', '缑山仙子王子乔性情高远，不像牛郎织女要下凡人间。皎洁的月光中停下吹凤箫，摆一摆手告别人间去成仙。
听说黄河竹筏能直上银河，一路上还挟带着天风海雨。今天相逢一醉是前生缘分，分别后谁知道各自向何方？', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74b25e272d4b2253bb4a", "shortContent": "此词调寄《鹊桥仙》，以七夕为题，是咏调名本意，为送别友人陈令举而作，非必写于七月七日。陈舜俞，字令举，乌程（今浙江湖州市）人。熙宁中做过山阴知县，因抵制青苗法，遭贬居家。熙宁七年（1074）秋九月，苏轼同杨元素、陈令举、张子野等曾到湖州拜访知州李公择，作有《菩萨蛮·席上和陈令举》词，本篇之作大约亦在此时，为分别时所写。农历七月七日夜，称为七夕，古代民间神话，每年七夕，牛郎织女渡天河相会。向来写七夕...", "authors": ["刘乃昌"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b82cee9a0c24ed9e4e", "shortContent": "此词调寄《鹊桥仙》，以七夕为题，是咏调名本意，为送别友人陈令举而作，非必写于七月七日。陈舜俞，字令举，乌程（今浙江湖州市）人。熙宁中做过山阴知县，因抵制青苗法，遭贬居家。熙宁七年（1074）秋九月，苏轼同杨元素、陈令举、张子野等曾到湖州拜访知州李公择，作有《菩萨蛮·席上和陈令举》词，本篇之作大约亦在此时，为分别时所写。农历七月七日夜，称为七夕，古代民间神话，每年七夕，牛郎织女渡天河相会。向来写七夕...", "authors": ["刘乃昌"], "pressName": "上海辞书出版社"}, {"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e79f2af4e09d55b6505", "shortContent": "朱本、龙本编于熙宁七年甲寅（1074）九月，与词意不合，所谓“高情云渺，不学痴牛女”，明显是言七夕。薛本、邹王本即编于是年七月七日，时东坡在杭州。孔《谱》云：“熙宁七年（1074）七月七日，赋《鹊桥仙》赠陈舜俞（令举）。时舜俞专程来杭相别。”《苏轼文集》卷六十三《祭陈令举文》：“予与令举别二年而令举没。”王文诰《苏诗总案》卷十四：熙宁九年五月，“闻陈舜俞没，公甚悼之”。", "authors": [], "pressName": "崇文书局"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "646834ea5e6bb82b8cd282af", "shortContent": "此词调寄《鹊桥仙》，以七夕为题，是咏调名本意，为送别友人陈令举而作，非必写于七月七日。陈舜俞，字令举，乌程（今浙江湖州市）人。熙宁中做过山阴知县，因抵制青苗法，遭贬居家。熙宁七年（1074）秋九月，苏轼同杨元素、陈令举、张子野等曾到湖州拜访知州李公择，作有《菩萨蛮·席上和陈令举》词，本篇之作大约亦在此时，为分别时所写。农历七月七日夜，称为七夕，古代民间神话，每年七夕，牛郎织女渡天河相会。向来写七夕...", "authors": ["刘乃昌"], "pressName": "上海辞书出版社"}]', '南宋·陆放翁《渭南文集》：昔人作七夕诗，率不免有珠栊绮梳惜别之意，唯东坡此篇，居然是星汉上语，歌之曲终，觉天风海雨逼人。
', 'indent', 1476230043, '57fd0b1ba0bb9f00584e4033', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10537, '月夜', NULL, 296, 1416, 4, 5, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/155613/4876214.htm', '', '今夜鄜州月，闺中只独看。
遥怜小儿女，未解忆长安。
香雾云鬟湿，清辉玉臂寒。
何时倚虚幌，双照泪痕干。', '天宝十五载（756年）春，安禄山由洛阳攻潼关。五月，杜甫从奉先移家至潼关以北的白水（今陕西白水县）的舅父处。六月，长安陷落，玄宗逃蜀，叛军入白水，杜甫携家逃往鄜州羌村。七月，肃宗在灵武（今宁夏灵武县）即位，杜甫获悉即从鄜州只身奔向灵武，不料途中被安史叛军所俘，押回长安。八月，作者被禁长安望月思家而作此诗。诗中借助想象，抒写妻子对自己的思念，也写出自己对妻子的思念。全诗构想新奇，情真意切，深婉动人。', '鄜（fū）州：今陕西省富县。当时杜甫的家属在鄜州的羌村，杜甫在长安。
闺中：内室。看，读平声kān。
怜：想。
未解：尚不懂得。
香雾云鬟（huán）湿，清辉玉臂寒：写想象中妻独自久立，望月怀人的形象。香雾：雾本来没有香气，因为香气从涂有膏沐的云鬟中散发出来，所以说“香雾”。望月已久，雾深露重，故云鬟沾湿，玉臂生寒。杨慎谓：“雨未尝有香，而无微之诗云：‘雨香云淡觉微和。’云未尝有香，而卢象诗云：‘云气香流水。’今按：雾本无香，香从鬟中膏沐生耳。如薛能诗‘和花香雪九重城’，则以香雪借形柳花也。梁章隐《咏素馨花》诗：‘细花穿弱缕，盘向绿云鬟。’”云鬟，古代妇女的环形发饰。
清辉：阮籍诗《咏怀》其十四：“明月耀清晖。”
虚幌：透明的窗帷。幌，帷幔。
双照：与上面的"独看"对应，表示对未来团聚的期望。泪痕：隋宫诗《叹疆场》“泪痕犹尚在。”', '今夜里鄜州上空那轮圆月，只有你在闺房中独自遥看。
可怜我那些鄜州的小儿女，不理解你思念长安的心思。
染香的雾气打湿你的鬓发，明月的清光使你玉臂生寒。
何时能并肩坐在薄帷帐下，月光照你我尽把泪痕擦干。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a80ce818559d058711", "shortContent": "天宝十五载（756）六月，安史叛军攻进潼关，杜甫带着妻小逃到鄜州（今陕西富县），寄居羌村。七月，肃宗即位于灵武（今属宁夏）。杜甫便于八月间离家北上延州（今陕西延安），企图赶到灵武，为平叛效力。但当时叛军势力已膨胀到鄜州以北，他启程不久，就被叛军捉住，送到沦陷后的长安；望月思家，写下了这首千古传诵的名作。\n题为《月夜》，作者看到的是长安月。如果从自己方面落墨，一入手应该写“今夜长安月，客中只独看”。...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a73", "shortContent": "天宝十五载（756）六月，安史叛军攻进潼关，杜甫带着妻小逃到鄜州（今陕西富县），寄居羌村。七月，肃宗即位于灵武（今属宁夏）。杜甫便于八月间离家北上延州（今陕西延安），企图赶到灵武，为平叛效力。但当时叛军势力已膨胀到鄜州以北，他启程不久，就被叛军捉住，送到沦陷后的长安；望月思家，写下了这首千古传诵的名作。\n\n题为《月夜》，作者看到的是长安月。如果从自己方面落墨，一入手应该写“今夜长安月，客中只独看”...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2477683d19330151cd", "shortContent": "天宝十五载（756）六月，安史叛军攻进长安，杜甫携家逃难，寄居鄜州（今陕西富县）。七月，肃宗即位于灵武，杜甫前往投效，途中为叛军所俘，被带到长安。幸因官职卑微，未被囚禁。身处沦陷的长安，望月思家，心有所触，写下这首情感细腻深厚的《月夜》。\n\n身处长安，按常理，诗人应写长安之月，但诗人却转移笔墨，写鄜州之月。面对同一洒下清辉的明月，一是客中独看，一是闺中独看，共把怀思与挂念遥寄对方。诗人不从自己着墨...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270597f0b9738b369b1e0", "shortContent": "天宝十五载（756）六月，安史叛军攻进长安，杜甫携家逃难，寄居鄜州（今陕西富县）。七月，肃宗即位于灵武（今宁夏回族自治区灵武县），杜甫前往投效，途中为叛军所俘，带到长安。幸因官职卑微，未被囚禁。身处沦陷的长安，望月思家，心有所触，写下这首情感细腻深厚的《月夜》。\n\n作者身处长安，按常理，诗人应写长安之月，但诗人却转移笔墨，透过一层，写鄜州之月。面对同一洒下清辉的明月，一是客中独看，一是闺中独看，共...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270c79761253910e905b4", "shortContent": "天宝十五载（756）六月，安史叛军攻进长安，杜甫携家逃难，寄居鄜州（今陕西富县）。七月，肃宗即位于灵武（今宁夏回族自治区灵武县），杜甫前往投效，途中为叛军所俘，带到长安。幸因官职卑微，未被囚禁。身处沦陷的长安，望月思家，心有所触，写下这首情感细腻深厚的《月夜》。\n\n作者身处长安，按常理，诗人应写长安之月，但诗人却转移笔墨，透过一层，写鄜州之月。面对同一洒下清辉的明月，一是客中独看，一是闺中独看，共...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6464dc455e6bb82b8cc56751", "shortContent": "天宝十五载（756）六月，安史叛军攻进潼关，杜甫带着妻小逃到鄜州（今陕西富县），寄居羌村。七月，肃宗即位于灵武（今属宁夏）。杜甫便于八月间离家北上延州（今陕西延安），企图赶到灵武，为平叛效力。但当时叛军势力已膨胀到鄜州以北，他启程不久，就被叛军捉住，送到沦陷后的长安；望月思家，写下了这首千古传诵的名作。\n\n题为《月夜》，作者看到的是长安月。如果从自己方面落墨，一入手应该写“今夜长安月，客中只独看”...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '《瀛奎律髓》：八句皆思家之言，三、四及“儿女”，六句全是忆内，与乃祖诗骨格声音相似。
《唐诗品汇》：刘云：愈缓愈悲，俯仰俱足（“未解”句下）。
《唐诗归》：谭云：“遍插茱萸少一人”、“霜鬓明朝又一年”，皆客中人遥想中相忆之词，已难堪矣。此又想其“未解忆”，又是客中一种愁苦，然看得前二绝意明，方知“遥怜”、“未解”之趣（“遥怜”二句下）。钟云：“泪痕干”，苦境也，但以“双照”为望，即“庶往共饥渴”意（末句下）。
《杜臆》：“云鬓”、“玉臂”，语丽而情更悲。
《义门读书记》：衬拓“独”字，逼起落句，精神百倍，转变更奇（“香雾”二句下）。
《瀛奎律髓汇评》：纪昀：言儿女不解忆，正言闺人相忆耳。故下文直接“香雾云鬟湿”一联。虚谷以为未及儿女，殊失诗意。入手便摆落现境，纯从对面着笔。蹊径甚别。后四句又纯为预拟之词，通首无一笔着正面，机轴奇绝。冯舒：只起二句，已见家在鄜州矣。第四句说身在长安，说得浑合无迹。五、六紧应“闺中”，落句紧接鄜州、长安。如此诗是天生成，非人工碾就，如此方称“诗圣”。许印芳：《三百篇》为诗祖，少陵此等诗从《陟岵》篇化出。对面着笔，不言我思家人，却言家人思我。又不直言思我，反言小儿女不解思我，而思我者之苦衷已在言外，……写闺中人，语要情悲。结语“何时”与起句“今夜”相应，“双照”与起句“独看”相应。首尾一气贯注，用笔精而运法密，宜细玩之。
《雨村诗话》：诗有借叶衬花之法。如杜诗“今夜鄜州月，闺中只独看，”自应说闺中之忆长安，却接“遥怜小儿女，未解忆长安”，此借叶衬花也。总之古人善用反笔，善用傍笔，故有伏笔，有起笔，有淡笔，有浓笔，今人曾梦见否？
《唐音审体》：映出上“独看”也。意虽直下，字句未尝不对（“未解”句下）。
《唐宋诗醇》：王士正曰：不言思儿女，情在言外。
《唐诗别裁》：“只独看”正忆长安，儿女无知，未解忆长安者苦衷也。反复曲折，寻味不尽。五、六语丽情悲，非寻常秾艳。
《读杜心解》：心已驰神到彼，诗从对面飞来，悲婉微至，精丽绝伦，又妙在无一字不从月色照出也。
《杜诗镜铨》：邵云：一气如话。
《闻鹤轩初盛唐近体读本》：此杜老初年始解言情之作。三、四正用形闺中独看人可念耳，五、六仍极写之。结笔更无聊作兴语。
《唐诗矩》：尾联见意格。结云云，则今夕天各一方，泪无干痕可知，此加一层用笔法。题是《月夜》，诗是思家，看他只用“双照”二字，轻轻绾合，笔有神力。
《岘佣说诗》：诗犹文也，忌直贵曲。少陵“今夜鄜州月，闺中只独看”，是身在长安，忆其妻在鄜州看月也。下云：“遥怜小儿女，未解忆安长，”用旁衬之笔；儿女不解忆，则解忆者独其妻矣。“香雾云鬟”、“清辉玉臂”，又从对面写，由长安遥想其妻在鄜州看月光景。收处作期望之词，恰好去路，“双照”紧对“独看”，可谓无笔不曲。
《唐宋诗举要》：吴汝纶曰：专从对面着想，笔情敏妙。', 'center', 1416918892, '57b91885a633bd00665e161a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10538, '春宿左省', NULL, 109, 1416, 1, 3, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383269.htm', '', '花隐掖垣暮，啾啾栖鸟过。
星临万户动，月傍九霄多。
不寝听金钥，因风想玉珂。
明朝有封事，数问夜如何？', '这首五律作于唐肃宗乾元元年（758）。至德二载（757）九月，唐军收复了被安史叛军所控制的京师长安；十月，肃宗自凤翔还京，杜甫于是从鄜州到京，仍任左拾遗。唐时左拾遗掌供奉讽谏，大事廷诤，小事上封事。
诗中描写作者上封事前在门下省值夜时的心情，表现了他居官勤勉，尽职尽忠，一心为国的精神。全诗八句，前四句写宿省之景，后四句写宿省之情，叙述详明而富于变化，描写真切而生动传神，体现了杜甫律诗结构既严谨又灵动，诗意既明达又蕴藉的特点。', '宿：指值夜。左省：即左拾遗所属的门下省，和中书省同为掌机要的中央政府机构，因在殿庑之东，故称“左省”。
掖垣：门下省和中书省位于宫墙的两边，像人的两腋，故名。
临：居高临下。
九霄：在此指高耸入云的宫殿。
金钥：即金锁。指开宫门的锁钥声。
珂：马铃。
封事：臣下上书奏事，为防泄漏，用黑色袋子密封，因此得名。', '左偏殿矮墙遮隐花丛，日已将暮，投宿的鸟儿，一群群鸣叫着飞过。
星临宫中，千门万户似乎在闪烁，靠近天庭，所得的月光应该更多。
夜不敢寝，听到宫门开启的钥锁，晚风飒飒，想起上朝马铃的音波。
明晨上朝，还有重要的大事要做，心里不安，多次地探问夜漏几何？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a9d635634aee3decd8", "shortContent": "至德二载（757）九月，唐军收复了被安史叛军所控制的京师长安；十月，肃宗自凤翔（今属陕西）还京，杜甫于是从鄜州（今陕西富县）到京，仍任左拾遗。左拾遗掌供奉讽谏，大事廷诤，小事上封事。所谓“封事”，就是密封的奏疏。这首作于乾元元年（758）的五律，描写作者上封事前在门下省值夜时的心情，表现了他忠勤为国的思想。诗题中的“宿”，指值夜；“左省”，即左拾遗所属的门下省，和中书省同为掌机要的中央政府机构，因...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e02098", "shortContent": "此诗是唐肃宗至德年间杜甫任左拾遗时所作。\n\n左拾遗隶属门下省，门下省在大内之东，故称左省、左掖。虽官职不大，只有从八品，但供奉讽谏，其责甚重。春天的夜晚，杜甫在此值班，宿于左省之中，却一夜难寐，作此诗。\n\n“花隐掖垣暮”，起句即照应篇题。篇题中有“春”字，正与“花”相照应。此时天色已晚，薄暮笼罩，原本鲜明的花色在夜色中逐渐隐隐约约起来。忽然传来啾啾之声，抬头望时，归巢的栖鸟从头顶掠过。一个“过”字...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6464e0aee49f46528aa6d719", "shortContent": "至德二载（757）九月，唐军收复了被安史叛军所控制的京师长安；十月，肃宗自凤翔（今属陕西）还京，杜甫于是从鄜州（今陕西富县）到京，仍任左拾遗。左拾遗掌供奉讽谏，大事廷诤，小事上封事。所谓“封事”，就是密封的奏疏。这首作于乾元元年（758）的五律，描写作者上封事前在门下省值夜时的心情，表现了他忠勤为国的思想。诗题中的“宿”，指值夜；“左省”，即左拾遗所属的门下省，和中书省同为掌机要的中央政府机构，因...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}]', '《韵语阳秋》：“明朝有封事，数问夜如何？”盖忧君谏政之心切，则通夕为之不寐。想其犯颜逆耳，必不为身谋也。
《唐诗广选》：赵子常曰：凡为五言，工在一字。谓之句眼。如此诗三、四“动”字、“多”字……之类是也。山谷云：“拾遗句中有眼”，推此可见。刘会孟曰：“星临”句与“风连西极动”相近，“星临”较奇。
《诗薮》：“九衢寒雾敛，万井曙钟多”，右丞壮语也，杜“里临万户动，月傍九霄多”，精彩过之。
《杜诗说》：五、六是腹中有事、忧上猜疑，写得逼真。
《唐诗选脉会通评林》：周敬曰：正大冠冕，近臣规度。赵云龙曰：情思宛然，故自可想。
《唐诗评选》：前四句皆不寝之景，一字不妄。杜陵早岁诗，固有典型。
《唐诗摘钞》：“宫云去殿低”、“月傍九霄多”，皆形容宫殿之高耳。五恐宫门已开，六恐朝上已集，及数问夜漏如何，极尽胸中有事，竞夜无眠光景。又云：五、六本一意，看他句法不合掌。不寝即不寐，用寐字便不老。
《杜诗解》：此诗之妙，妙于将题劈头写尽，却出已意，得大宽转。
《唐诗归折衷》：唐云：“花”见“春”，“暮”见“宿”，五字写尽题目（“花隐”句下）。钟云：“动”字之景，在“万户”上看出。敬夫云：“动”字有神气（“星临”句下）。敬夫云：山野之言易工，仁宦之诗每俗。如“避人焚谏草”、“明朝有封事”，仕宦事也。沉冠冕之中，风神掩映矣。二诗神韵悉敌，以法律论之，稍逊“尽刻传呼”之作。
《瀛奎律髓汇评》：陆贻典：尽忠补过之意，溢于言表。查慎行：灵武即位以后，缺事多矣。岑嘉州云：“圣朝无缺事。”不如老杜“明朝有封事”为纪实也。何义门：“金钥”自内出，“玉珂”从外入。纪昀：平正妥帖，但无深味。三、四赋现景，诗话穿凿无理。结二句是五、六注解。无名氏（甲）：因星月而抚民之爱，事主之忠，具见于此，所谓“文章有神”也。无名氏（乙）：神采贯古，五、六展拓虚空。
《杜诗详注》：赵汸曰：唐人五言，工在一字，谓之“句眼”。如此诗，三、四“动”字，“多”字，乃“眼”之在句底者。山谷云：“拾遗句中有眼”，篇篇有之。
《原诗》：又《宿左省》作“月傍九霄多”句。从来言月者，只有言圆缺，言明暗，言升沉，言高下，未有言多少者。若俗儒不曰“月傍九霄明”，则曰：“月傍九霄高”，以为景象真而使字切矣。……试想当时之情景，非言明、言高、言升可得；而惟此“多”字可以尽括此夜宫殿当前之景象。
《载酒园诗话又编》：老杜五言委，善写幽细之景，余万喜其正大者，如“避人焚谏草，骑马欲鸡栖”、“明朝有封事，数问夜如何”……真堪羽翼《风》《雅》。
《读杜心解》：按三、四，只是写景，而帝居高迥，全已画出。后四，本贴“宿”字，反用“不寝”二字，翻出远神，都无滞相。
《唐诗近体》：“动”字警，“多”字有义味，他人不敢下。
《闻鹤轩初盛唐近体读本》：起有秀致，三、四雄亮名句，然一险一爽。在五、六自趋问结耳。
《岘佣说诗》：“星临万户动，月傍九霄多”，是华贵语。', 'center', 1416919357, '57b965e95bbb50005b7bb3e6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10539, '出此门有悲往事', NULL, 33, 1416, 1, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/4689283.htm', '', '至德二载，甫自京金光门出，间道归凤翔。乾元初，从左拾遗移华州掾，与亲故别，因出此门，有悲往事。
此道昔归顺，西郊胡正繁。
至今残破胆，应有未招魂。
近侍归京邑，移官岂至尊。
无才日衰老，驻马望千门。', '安史乱中，杜甫曾被叛军捉住，押往长安。至德二载（757），他从长安西门中的金光门混出城，由小路逃往凤翔见唐肃宗，被任命为左拾遗。当年十月在长安收复后，他随皇帝回京。次年（乾元元年，758）因上书营救好友房琯而得罪，被贬为华州司功参军，恰好又从金光门出城，作者抚今追昔，悲慨万分，写下此诗。
这首诗前四句回忆当年奔窜的惊险经历，辗转拜见圣上，可见其拳拳爱国报君之志。后四句写其被贬的感受，蒙冤遭贬，又兼伤己之老迈和别亲友之悲切，含蓄的表达了对统治者的不满。', '至德二载：公元757年。载，唐自玄宗天宝三年改“年”为“载”，至肃宗乾元元年又改为“年”。京：指长安。金光门：长安外城有三座门，中间一座叫金光门。间道：偏僻的小路。凤翔：在今陕西，肃宗时一度改名西京，当时肃宗驻跸于此。左拾遗，职司规谏君主，荐举人才，属门下省。移：这里是贬降的意思。华州：今陕西华县。掾：属官的通你。这里指当时降为华州司功参军。因出此门：浦起龙《读社心解》云：“华在东而出西面门，为与亲故别，亲故有在西者也。”
此道：指金光门。昔归顺：指至德二载投奔凤翔时，长安西边的胡骑正甚繁乱。归顺：指逃脱叛军归凤翔，投奔肃宗。
正：一作“骑”。胡：这里指安禄山部队。
破胆：丧胆，惊骇。
未招魂：指活人的神魂，意谓推想叛军占据时，臣民神魂惊散之常，应有未招而不归之魂。未，一作“犹”。
近侍：指拜左拾遗。侍，一作“得”。京邑：指华州，因系畿县，距京城长安不远。
移官：调动官职，指由左拾遗外放为华州司功参军。岂至尊，难道出自皇帝之意。岂，一作“远”。
千门：原指宫中的门户，这里借代宫殿，形容其建筑宏伟，门户很多。', '当年由金光门这条路，去投奔凤翔，长安西郊，到处是安史叛军正作乱。
直到如今想起来，仍叫人心惊胆颤，有人神魂尚未招回，依然诚恐诚惶。
我拜近得左拾遗，回到了京畿地方，贬我华州掾，这旨意难道出自至尊。
算了吧，我这庸才已逐日衰老鬓苍，告别长安，驻马回望千门宫殿檐房！', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e02099", "shortContent": "乾元元年（758），杜甫由左拾遗移华州司功参军，出长安金光门，与亲故相别。因想到至德二载（757），自己从安史叛军盘踞的长安城逃奔凤翔时，正是从此门出。此时想起往事，不由悲伤不已，因作此诗。\n\n首联“此道昔归顺，西郊胡正繁”，老杜能够当上左拾遗的官职，与他从长安围城中投奔唐肃宗的行在有关，类似于此的从胡中还朝者，皆被认为心系大唐，故给予优待。当时安史叛军仍然占据长安，故称“胡正繁”。此事对老杜来说...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '', 'center', 1416919544, '57b965ec2e958a005fa8e5c0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10540, '月夜忆舍弟', NULL, 609, 1416, 3, 8, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155719.htm', '', '戍鼓断人行，边秋一雁声。
露从今夜白，月是故乡明。
有弟皆分散，无家问死生。
寄书长不达，况乃未休兵。', '这首诗托物咏怀，层次井然。首联和颔联写景，烘托出战争的氛围。颈联和尾联在此基础上写兄弟因战乱而离散，居无定处，杳无音信，于是思念之情油然而生，特别是在入秋以后的白露时节，在戍楼上的鼓声和失群孤雁的哀鸣声的映衬之下，这种思念之情越发显得深沉和浓烈。全诗语句精工，格调沉郁哀伤，真挚感人。', '舍弟：家弟。杜甫有四弟：杜颍、杜观、杜丰、杜占。
戍鼓：戍楼上用以报时或告警的鼓声。断人行：指鼓声响起后，就开始宵禁。
边秋：一作“秋边”，秋天边远的地方，此指秦州。一雁：孤雁。古人以雁行比喻兄弟，一雁，比喻兄弟分散。
露从今夜白：指在气节“白露”的一个夜晚。
分散：一作“羁旅”。
无家：杜甫在洛阳附近的老宅已毁于安史之乱。
长：一直，老是。不达：收不到。达，一作“避”。
况乃：何况是。未休兵：此时叛将史思明正与唐将李光弼激战。', '戍楼上响起禁止通行的鼓声，秋季的边境传来孤雁的哀鸣。
今天是白露节更怀念家里人，还是觉得家乡的月亮更明亮。
虽有兄弟但都离散各去一方，已经无法打听到他们的消息。
寄书信询问也不知送往何处，何况天下依旧战乱不能太平。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ab0f8fda556505544c", "shortContent": "这首诗是乾元二年（759）秋杜甫在秦州（治所在今甘肃天水）所作。这年九月，史思明从范阳引兵南下，攻陷汴州，西进洛阳，山东、河南都处于战乱之中。当时，杜甫的几个弟弟正分散在这一带，由于战事阻隔，音信不通，引起他强烈的忧虑和思念。《月夜忆舍弟》即是他当时思想感情的真实记录。在古典诗歌中，思亲怀友是常见的题材，这类作品要力避平庸，不落俗套，单凭作者生活体验是不够的，还必须在表现手法上匠心独运。杜甫正是在...", "authors": ["张明非"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a78", "shortContent": "这首诗是乾元二年（759）秋杜甫在秦州（治所在今甘肃天水）所作。这年九月，史思明从范阳引兵南下，攻陷汴州，西进洛阳，山东、河南都处于战乱之中。当时，杜甫的几个弟弟正分散在这一带，由于战事阻隔，音信不通，引起他强烈的忧虑和思念。《月夜忆舍弟》即是他当时思想感情的真实记录。在古典诗歌中，思亲怀友是常见的题材，这类作品要力避平庸，不落俗套，单凭作者生活体验是不够的，还必须在表现手法上匠心独运。杜甫正是在...", "authors": ["张明非"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e0209a", "shortContent": "一个清冷的夜晚，耳畔传来了单调的更鼓声，不由让人的心绪也变得单调、沉闷了。一位孤单的满怀愁绪的诗人，此时正月夜独坐，头脑一片空白。蓦然响起的更鼓声刹那间惊醒了他，突然，他感到了一丝清冷，猛然意识到，又是秋令时节了！\n\n在这样一个夜晚，伴随沉闷的更鼓之声，诗人感到了分外的寂寞。这不，路上连一个行人也没有，偌大的天地似乎只有诗人自己孤单地呼吸着寂寞的空气。不！不只他一人！还有秋雁呢！听，那不是它们欢快...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127068f2af4e09d55b676d", "shortContent": "一个清冷的夜晚，耳畔传来了单调的更鼓声，不由让人的心绪也变得单调、沉闷了。一位孤单的满怀愁绪的诗人，此时正月夜独坐，头脑一片空白。蓦然响起的更鼓声刹那间惊醒了他，突然，他感到了一丝清冷，猛然意识到，又是秋令时节了！\n\n在这样一个夜晚，伴随沉闷的更鼓之声，诗人感到了分外的寂寞。这不，路上连一个行人也没有，偌大的天地似乎只有诗人自己孤单地呼吸着寂寞的空气。不！不只他一人！还有秋雁呢！听，那不是它们欢快...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270d4c26cbf3417f0950f", "shortContent": "一个清冷的夜晚，耳畔传来了单调的更鼓声，不由让人的心绪也变得单调、沉闷了。一位孤单的满怀愁绪的诗人，此时正月夜独坐，头脑一片空白。蓦然响起的更鼓声刹那间惊醒了他，突然，他感到了一丝清冷，猛然意识到，又是秋令时节了！\n\n在这样一个夜晚，伴随沉闷的更鼓之声，诗人感到了分外的寂寞。这不，路上连一个行人也没有，偌大的天地似乎只有诗人自己孤单地呼吸着寂寞的空气。不！不只他一人！还有秋雁呢！听，那不是它们欢快...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6465ddef7da2f75ac7ecd3ab", "shortContent": "这首诗是乾元二年（759）秋杜甫在秦州（治所在今甘肃天水）所作。这年九月，史思明从范阳引兵南下，攻陷汴州，西进洛阳，山东、河南都处于战乱之中。当时，杜甫的几个弟弟正分散在这一带，由于战事阻隔，音信不通，引起他强烈的忧虑和思念。《月夜忆舍弟》即是他当时思想感情的真实记录。在古典诗歌中，思亲怀友是常见的题材，这类作品要力避平庸，不落俗套，单凭作者生活体验是不够的，还必须在表现手法上匠心独运。杜甫正是在...", "authors": ["张明非"], "pressName": "上海辞书出版社"}]', '《诗人玉屑》：杜子美善于用故事及常语，多离析或颠倒其句而用之，盖如此则语崚而体健，意亦深稳矣（《麈史》）。如“露从今夜白，月是故乡明”之类是也。
《李杜诗选》：此二句（按指“露从”一联）妙绝古今矣，原其始从江淹《别赋》“明月白露”一句四字翻作十字，而精神如此，《文选》真母头哉。
《唐诗归》：钟云：只说境，含情往复不可言（“露从”二句下）。
《唐诗选脉会通评林》：刘辰翁曰：浅浅语使人愁。周珽曰：……结联所谓“人稀不到，兵在见何由”也。征战不已，道路阻隔，音书杳莫，存亡难保，伤心断肠之语。令人读不能终篇。
《杜臆》：只“一雁声”便是忆弟。对明月而忆弟，觉露增其白，伹月不如故乡之明，忆在故乡兄弟故也，盖情异而景为之变也。
《瀛奎律髓汇评》：何义门；“戍鼓”兴“未休兵”。“一雁”兴“寄书”。五、六，正拈忆弟。纪昀：平正之中，自饶情致。无名氏（乙）：句句转。“戍鼓”是领句，突接“雁声”妙。
《茧斋诗谈》：“戍鼓断人行，秋边一雁声。”若作“雁一声”，便浅俗；“一雁声”便沉雄。诗之贵炼，只在字法颠倒间便定。
《读杜心解》：上四，突然而来，若不为弟者，精神乃字字忆弟、句里有魂也。……不曰“月傍”，而曰“月是”，便使两地皆悬。
《杜诗镜铨》：凄楚不堪多读。起突兀（“戍鼓”二句下）。', 'center', 1416919680, '57b912ce165abd0054c06426', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10545, '酬张少府', NULL, 282, 394, 3, 2, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383293.htm', '', '晚年惟好静，万事不关心。
自顾无长策，空知返旧林。
松风吹解带，山月照弹琴。
君问穷通理，渔歌入浦深。', '此诗是唐代诗人王维酬答友人的作品。前四句全是写情，隐含着诗人伟大抱负不能实现的矛盾苦闷心情。颈联写隐逸生活的情趣。末联是即景悟情，以问答形式作结，故作玄解，以不管作答，含蓄而富有韵味，洒脱超然，发人深省。
此诗“松风”两句，情景浑成，物我两忘，以动写静，以声显寂，为高人达士作了传神的写照。诗人着意自述“好静”之志趣，写自己对闲适生活的快意，并表示自己对天地间的大道理有所领悟，已经能超然物外，从表面上看似乎很达观，但从诗意中，还是透露出一点点失落、苦闷的气息。', '酬：以诗词酬答。
张少府：当指张九龄，字子寿，一名博物。韶州曲江（今属广东）人。官至中书侍郎同中书门下平章事。后遭李林甫排挤罢相。
少府：唐人称县尉为少府。从“君问穷通理”句看，张少府亦是诗人同道之人。
晚年：年老之时。唐·包佶《发襄阳后却寄公安人》诗：“晚年多疾病，中路有风尘。”
唯：亦写作“惟”，只。
好（hào）：爱好。
自顾：自念、自视。三国魏·曹植《赠白马王彪》诗：“自顾非金石，咄唶令心悲。”李善注：“郑玄《毛诗笺》曰：‘顾，念也。’”
长策：犹良计。《史记·平津侯主父列传》：“靡毙中国，快心匈奴，非长策也。”
空知：徒然知道。
旧林：指禽鸟往日栖息之所。这里比喻旧日曾经隐居的园林。晋·陶潜《归园田居》诗之一：“羁鸟恋旧林，池鱼思故渊。”
吹解带：吹着诗人宽解衣带时的闲散心情。《三国志·蜀志·诸葛亮传》：“亮深谓备雄姿杰出，遂解带写诚，厚相结纳。”解带，表示熟不拘礼，或表示闲适。
君：一作“若”。
穷：不能当官。
通：能当官。
理：道理。
渔歌：隐士的歌。暗用《楚辞·渔父》的典故：“渔父莞尔而笑，鼓枻而去，乃歌曰：‘沧浪之水清兮，可以濯吾缨；沧浪之水浊兮，可以濯吾足。’遂去，不复而言。”浦深：河岸的深处。
“君问穷通理，渔歌入浦深。”句：这是劝张少府达观，也即要他像渔樵那样，不因穷通而有得失之患。', '人到晚年特别喜好安静，对人间万事都漠不关心。
自思没有高策可以报国，只要求归隐家乡的山林。
宽解衣带对着松风乘凉，山月高照正好弄弦弹琴。
君若问穷困通达的道理，请听水浦深处渔歌声音。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929534a8757d5a0e1bdb", "shortContent": "这是一首赠友诗。题目冠以“酬”字，当是张少府先有诗相赠，王维再写此诗为酬。\n这首诗，一上来就说，自己人到晚年，惟好清静，对什么事情都漠不关心了。乍一看，生活态度消极之至，但这是表面现象。仔细推求起来，这“惟好静”的“惟”字大有文章。是确实“只”好静呢，还是“动”不了才“只得”好静呢？既云“晚年”，那么中年呢？早年呢？为什么到了晚年变得“惟好静”起来呢？底下三、四两句，透露了个中消息。\n王维早年，原...", "authors": ["刘德重"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc4091f", "shortContent": "这是一首赠友诗。题目冠以“酬”字，当是张少府先有诗相赠，王维再写此诗为酬。\n\n这首诗，一上来就说，自己人到晚年，惟好清静，对什么事情都漠不关心了。乍一看，生活态度消极之至，但这是表面现象。仔细推求起来，这“惟好静”的“惟”字大有文章。是确实“只”好静呢，还是“动”不了才“只得”好静呢？既云“晚年”，那么中年呢？早年呢？为什么到了晚年变得“惟好静”起来呢？底下三、四两句，透露了个中消息。\n\n王维早年...", "authors": ["刘德重"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e020a5", "shortContent": "回首往事，感慨万千。年少壮志时的我，曾经拥有怎样的政治抱负啊！张九龄任宰相时，我对现实充满希望。然而，没过多久，张九龄罢相贬官，朝政大权落到奸相李林甫手中，忠贞正直之士一个个受到排斥、打击，政治局面日趋黑暗，我的理想随之破灭。我该何去何从？值得庆幸的是直到暮年我还洁身自好。\n\n一年之计在于春，人生也是如此。人生漫漫，我已走到暮年，再没什么追求和理想，只想静静地来，轻轻地去，两耳不闻窗外事，一心只想...", "authors": ["黄蓓"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270447ccdb86c49f29229", "shortContent": "回首往事，感慨万千。年少壮志时的我，曾经拥有怎样的政治抱负啊！张九龄任宰相时，我对现实充满希望。然而，没过多久，张九龄罢相贬官，朝政大权落到奸相李林甫手中，忠贞正直之士一个个受到排斥、打击，政治局面日趋黑暗，我的理想随之破灭。我该何去何从？值得庆幸的是直到暮年我还洁身自好。\n\n一年之计在于春，人生也是如此。人生漫漫，我已走到暮年，再没什么追求和理想，只想静静地来，轻轻地去，两耳不闻窗外事，一心只想...", "authors": ["（黄蓓）"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127077f2af4e09d55b6799", "shortContent": "回首往事，感慨万千。年少时的我，曾经拥有怎样的政治抱负啊！张九龄任宰相时，我对现实充满希望。然而，没过多久，张九龄罢相贬官，朝政大权落到奸相李林甫手中，忠贞正直之士一个个受到排斥、打击，政治局面日趋黑暗，我的理想随之破灭。我该何去何从？值得庆幸的是直到暮年我还洁身自好。\n\n一年之计在于春，人生也是如此。人生漫漫，我已走到暮年，再没什么追求和理想，只想静静地来，轻轻地去，两耳不闻窗外事，一心只想乐逍...", "authors": ["黄蓓"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "64645470e49f46528aa3afae", "shortContent": "这是一首赠友诗。题目冠以“酬”字，当是张少府先有诗相赠，王维再写此诗为酬。\n\n这首诗，一上来就说，自己人到晚年，惟好清静，对什么事情都漠不关心了。乍一看，生活态度消极之至，但这是表面现象。仔细推求起来，这“惟好静”的“惟”字大有文章。是确实“只”好静呢，还是“动”不了才“只得”好静呢？既云“晚年”，那么中年呢？早年呢？为什么到了晚年变得“惟好静”起来呢？底下三、四两句，透露了个中消息。\n\n这首诗，...", "authors": ["刘德重"], "pressName": "上海辞书出版社"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "6464558c45e4710056c242d0", "shortContent": "这是一首赠友诗。题目冠以“酬”字，当是张少府先有诗相赠，王维再写此诗为酬。\n\n这首诗，一上来就说，自己人到晚年，唯好清静，对什么事情都漠不关心了。乍一看，生活态度消极之至，但这是表面现象。仔细推求起来，这“惟好静”的“惟”字大有文章。是确实“只”好静呢，还是“动”不了才“只得”好静呢？既云“晚年”，那么中年呢？早年呢？为什么到了晚年变得“惟好静”起来呢？底下三、四两句，透露了个中消息。\n\n王维早年...", "authors": ["刘德重"], "pressName": "上海辞书出版社"}]', '明·李沂《唐诗援》：意思闲畅，笔端高妙，此是右丞第一等诗，不当于一字一句求之。
明·鍾惺、谭元春《唐诗归》：鍾云：妙在酬答，只似一首闲居诗，然右丞庙堂诗亦皆是闲居。谭云：妙绝（尾联下）。
明·唐汝询《汇编唐诗十集》：唐云：庙堂酬答亦多不切闲居者，钟自不采耳。
清·焦袁熹《此木轩论诗汇编》：“自顾无长策，空自返旧林”，无一毫作伪，无一毫诡秘。
清·屈复《唐诗成法》：一二后即当接“松风”、“山月”，却横插“自顾”二句，意遂深厚。
清·吴煊、胡棠《唐贤三昧集笺注》：宕开收，言不尽意，此亦一法（“渔歌”句下）。顾云：末酬张少府用《离骚·渔父》篇意，俊逸。
清·沈德潜《唐诗别裁》：收束或放开一步，或宕出远神，或本位收住……王右丞“君问穷通理，渔歌人浦深”，从“解带”、“弹琴”宕出远神也。结意以不答答之。
清代宋宗元《网师园唐诗笺》：悠然神远（“松风”句下）。
清·张文荪《唐贤清雅集》：起接四句一气，下承“旧林”，转结到“酬”字意，兴趣最远。理会了彻，随口都成灵籁。
清·张谦宜《绲斋诗谈》：“晚年惟好静，万事不关心”，含一篇之脉，此方是起法。三、四虚承，五、六实地，用笔浅深俱到，章法之妙也。', 'center', 1416941251, '57b928d7c4c9710055907a52', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10541, '天末怀李白', NULL, 202, 1416, 2, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155727.htm', '', '凉风起天末，君子意如何。
鸿雁几时到，江湖秋水多。
文章憎命达，魑魅喜人过。
应共冤魂语，投诗赠汨罗。', '这是唐代大诗人杜少陵写的一首思念李太白的诗作。此诗以凉风起兴，对景相思，设想李太白于深秋时节在流放途中，从长江经过洞庭湖一带的情景，表达了作者对李太白深切的牵挂、怀念和同情，并为他的悲惨遭遇愤慨不平。全诗情感真切深挚，风格婉转沉郁，为历代广为传诵的抒情名篇。', '天末：天的尽头。秦州地处边塞，如在天之尽头。当时李太白因永王李璘案被流放夜郎，途中遇赦还至湖南。
君子：指李太白。
鸿雁：喩指书信。古代有鸿雁传书的说法。
江湖：喩指充满风波的路途。这是为李太白的行程担忧之语。
「文章憎命达」句：有文才的人总是薄命遭忌。命，命运，时运；文章，这里泛指文学。
「魑（chī）魅喜人过」句：指魑魅喜欢幸灾乐祸，说明李太白被贬是被诬陷的。魑魅，鬼怪，这里指坏人或邪恶势力；过，过错、过失。
冤魂：指屈原。屈原被放逐，投汨罗江而死。杜少陵深知李太白从永王李璘实出于爱国，却蒙冤放逐，正和屈原一样。所以说，应和屈原一起诉说冤屈。
汨（mì）罗：汨罗江，在湖南湘阴县东北。', '凉风飕飕从天边颳起，不知此时你心境怎样。
鸿雁捎的消息何时到？衹恐江湖秋水多风浪。
文采卓绝薄命遭忌恨，山精水怪喜诬陷他人。
想必你会与屈原共语，投诗汨罗江诉不平事。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ab2e6a6b501f95c14d", "shortContent": "这首诗为诗人客居秦州（治所在今甘肃天水）时所作。时李白坐永王璘事长流夜郎（治所在今贵州正安西北），途中遇赦还至湖南，杜甫因赋诗怀念他。\n首句以秋风起兴，给全诗笼罩一片悲愁。时值凉风乍起，景物萧疏，怅望云天，此意如何？只此两句，已觉人海沧茫，世路凶险，无限悲凉，凭空而起。次句不言自己心境，却反问远人：“君子意如何？”看似不经意的寒暄，而于许多话不知应从何说起时，用这不经意语，反表现出最关切的心情。这...", "authors": ["孙艺秋", "王启兴"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e0209b", "shortContent": "又是一个秋末天气，凉风骤起，更吹皱了诗人本就颇不平静的心。杜甫时客居秦州（治所在今甘肃天水），北国风物，此时更是一片萧索。放眼四顾，找不到一丝生机与活力，怅望云天，更增愁绪无数。回顾自身遭际，深感人海茫茫，世事难料，无限悲凉涌上心头，悲秋情绪挥之难去。适闻友人李白流放夜郎，途中被赦，还至湖南，不由想对挚友聊抒一番心曲。\n \n“凉风起天末，君子意如何？”这样的时节，这样的天气，我的心情是孤独，我的情...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127067c305cf0801816fc2", "shortContent": "又是一个秋末天气，凉风骤起，更吹皱了诗人本就颇不平静的心。杜甫时客居秦州（治所在今甘肃天水），北国风物，此时更是一片萧索。放眼四顾，找不到一丝生机与活力，怅望云天，更增愁绪无数。回顾自身遭际，深感人海茫茫，世事难料，无限悲凉，涌上心头，悲秋情绪，挥之难去。适闻友人李白流放夜郎，途中被赦，还至湖南，不由想对挚友聊抒一番心曲。\n\n“凉风起天末，君子意如何？”这样的时节，这样的天气，我的心情是孤独，我的...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270d4c26cbf3417f0950e", "shortContent": "又是一个秋末天气，凉风骤起，更吹皱了诗人本就颇不平静的心。杜甫时客居秦州（治所在今甘肃天水），北国风物，此时更是一片萧索。放眼四顾，找不到一丝生机与活力，怅望云天，更增愁绪无数。回顾自身遭际，深感人海茫茫，世事难料，无限悲凉，涌上心头，悲秋情绪，挥之难去。适闻友人李白流放夜郎，途中被赦，还至湖南，不由想对挚友聊抒一番心曲。\n\n“凉风起天末，君子意如何？”这样的时节，这样的天气，我的心情是孤独，我的...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6465ddb45b7b0d4f45160369", "shortContent": "这首诗为诗人客居秦州（治所在今甘肃天水）时所作。时李白坐永王璘事长流夜郎（治所在今贵州正安西北），途中遇赦还至湖南，杜甫因赋诗怀念他。\n\n首句以秋风起兴，给全诗笼罩一片悲愁。时值凉风乍起，景物萧疏，怅望云天，此意如何？只此两句，已觉人海沧茫，世路凶险，无限悲凉，凭空而起。次句不言自己心境，却反问远人：“君子意如何？”看似不经意的寒暄，而于许多话不知应从何说起时，用这不经意语，反表现出最关切的心情。...", "authors": ["孙艺秋", "王启兴"], "pressName": "上海辞书出版社"}]', '《汇编唐诗十集》：唐云：此首才堪入选，是一片真情写成。
《读杜诗说》：三联：文与命仇意，而「憎」字惊极。不言远贬，而曰：「魑魅喜人过」，将欲伺人而食之也，语险更惊。不曰「吊」而曰「赠」，说得冤魂活现（「投诗」句下）。
《唐诗归》：鍾云：真元气（首四句下）。鍾云：大发愤，却是实历语。谭云：十字读不得，然深思正耐多读（「文章」二句下）。鍾云：「赠」字说得精神与古人相关，若用「吊」字则浅矣（末二句下）。
《杜臆》：陆士衡诗：「借问欲何为？凉风起天末。」全用起语而倒转之，此用古之一法。「江湖水多」，鲤不易得，使事脱化。
《杜诗详注》：盖文章不遇，魑魅见侵，夜郎一窜，几与汨罗同冤，说到流离生死，千里关情，真堪声泪交下，此怀人之最惨怛者。
《义门读书记》：嵇叔夜耻与魑魅争光。此句指与白争进者言之。鬼神忌才，喜伺过失（「魑魅」句下）。
《拜经楼诗话》：少陵「水流心不竞，云在意俱迟」一联，古今以为名句。明人云：「鸿雁几吋到？江湖秋水多。」却有自然之妙。
《唐诗成法》：文章知己，一字一泪，而味在字句之外，所谓「羚羊挂角，无迹可寻」也。七、八从三、四来，法密。
《唐诗归折衷》：吴敬夫云：六句，刘须溪谓：魑魅犹知此人之来以为喜，则朝廷之上，不如魑魅多矣。如此解，于接下二语较有情。
《唐宋诗醇》：悲歌慷慨，一气舒卷，李杜交好，其诗特地精神。
《唐诗别裁》：沉郁（「文章」二句下）。
《读杜心解》：太白仙才，公诗起四语，亦便有仙气，竞似太白语。五、六，直隐括《天问》、《招魂》两篇。
《杜诗镜铨》：蒋云：向空摇望，喃喃作声，此等诗真得《风》、《骚》之意。
《精选五七言律耐吟集》：胸中有千万言说不出，忽有此起十字米。
《网师园唐诗笺》：「鸿雁」四句，《骚》经之遗。
《唐宋诗举要》：邵曰：一「憎」一「喜」，遂令文人无置身地（「文章」二句下）。吴曰：深至语自然沉痛，非太白不能当（末二句下）。', 'center', 1416940680, '57b8a401c4c97100558de7b6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10542, '奉济驿重送严公四韵', NULL, 52, 1416, 1, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383271.htm', '', '远送从此别，青山空复情。
几时杯重把，昨夜月同行。
列郡讴歌惜，三朝出入荣。
江村独归处，寂寞养残生。', '奉济驿，在成都东北的绵阳县。严公，即严武，曾两度为剑南节度使。762年（宝应元年）四月，唐肃宗死，唐代宗即位，六月，召严武入朝，杜甫送别赠诗，因之前已写过《送严侍郎到绵州同登杜使君江楼宴》，故称“重送”。律诗双句押韵，八句诗四个韵脚，故称“四韵”。严武有文才武略，品性与杜甫相投。镇蜀期间，亲到草堂探视杜甫，并在经济上给予接济；彼此赠诗，相互敬重，结下了深厚的友谊。
此诗既赞美严武，也发出他自己“寂寞养残生”的叹息。诗意在送严武奉召还朝。诗人曾任严武幕僚，深得严武关怀，所以心中那种依依不舍的别离之情，不必再用言语解释。这首诗语言质朴含情，章法谨严有度，平直中有奇致，浅易中见沉郁，情真意挚，凄楚感人。', '列郡：指东西两川属邑。
三朝：指唐玄宗、唐肃宗、唐代宗三朝。
江村：指成都浣花溪边的草堂。', '远送你从这里就要分别了，青山空自惆怅，倍增离情。什么时候能够再举杯共饮，昨天夜里我们还在月色中同行。各郡的百姓都讴歌你，不忍心你离去，你在三朝为官，多么光荣。送走你我独自回到江村，寂寞地度过剩下的岁月。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ad2cee9a0c24ecf8d3", "shortContent": "奉济驿，在成都东北的绵阳县。严公，即严武，曾两度为剑南节度使。宝应元年（762）四月，肃宗死，代宗即位；六月，召严武入朝，杜甫送别赠诗。因前已写过《送严侍郎到绵州同登杜使君江楼宴》，故称“重送”。律诗双句押韵，八句诗四个韵脚，故称“四韵”。\n严武有文才武略，品性与杜甫相投。镇蜀期间，亲到草堂探视杜甫，并在经济上给予接济；彼此赠诗，相互敬重，结下了深厚的友谊。\n诗一开头，点明“远送”，可见意深而情长...", "authors": ["傅经顺"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e0209c", "shortContent": "代宗召严武入朝，杜甫作此诗赠别。奉济驿，地名，在成都东北的绵阳。严公即严武，曾两度为剑南节度使，与杜甫甚为相得。题为“重送”，乃因前此杜甫有诗作《送严侍郎到绵州同登杜使君江楼宴》。\n\n诗作开篇即直切“送别”主题。诗人相伴友人走了一程又一程，真想就这样一直陪伴下去，但送君千里，终须一别。在此分别之际，哪怕有万分不舍，也只能忍泪吞下，又何必为离人更添伤感呢。“青山空复情”，道路两旁伫立的青山，仿佛也同...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6465ed225fc8182fe9a36b01", "shortContent": "奉济驿，在成都东北的绵阳县。严公，即严武，曾两度为剑南节度使。宝应元年（762）四月，肃宗死，代宗即位；六月，召严武入朝，杜甫送别赠诗。因前已写过《送严侍郎到绵州同登杜使君江楼宴》，故称“重送”。律诗双句押韵，八句诗四个韵脚，故称“四韵”。\n\n严武有文才武略，品性与杜甫相投。镇蜀期间，亲到草堂探视杜甫，并在经济上给予接济；彼此赠诗，相互敬重，结下了深厚的友谊。\n\n诗一开头，点明“远送”，可见意深而...", "authors": ["傅经顺"], "pressName": "上海辞书出版社"}]', NULL, 'center', 1416940790, '57b965f5165abd0054c36050', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10543, '别房太尉墓', NULL, 72, 1416, 1, 2, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383290.htm', '', '他乡复行役，驻马别孤坟。
近泪无干土，低空有断云。
对棋陪谢傅，把剑觅徐君。
唯见林花落，莺啼送客闻。', '房太尉即房琯，他在唐玄宗来到四川时拜相，为人比较正直。至德二年（757年），为唐肃宗所贬。杜甫曾毅然上疏力谏，结果得罪肃宗，几遭刑戮。房琯罢相后，于宝应二年（763年）拜特进、刑部尚书。在路遇疾，卒于阆州。死后赠太尉（见《旧唐书·房琯传》）。两年后杜甫经过阆州，特来看看老友的坟，写下了此诗。
此诗是诗人经过阆州看望老友房琯之墓时创作，表达了诗人对老友的思念和内心对国事的殷忧和叹息之情。全诗写得既雍容典雅，又一往情深，深沉含蓄。', '房太尉：房琯。
复行役：指一再奔走。
近泪句：意谓泪流处土为之不干。
对棋：对弈、下棋。谢傅：指谢安。以谢安的镇定自若、儒雅风流来比喻房琯是很高妙的，足见其对房琯的推崇备至。
把剑句：春秋时吴季札聘晋，路过徐国，心知徐君爱其宝剑，及还，徐君已死，遂解剑挂在坟树上而去。意即早已心许。', '我东西漂泊，一再奔走他乡异土，今日歇脚阆州，来悼别你的孤坟。
泪水沾湿了泥土，心情十分悲痛，精神恍惚，就像低空飘飞的断云。
当年与你对棋，比你为晋朝谢安，而今在你墓前，像季札拜别徐君。
不堪回首，眼前只见这林花错落，离去时，听得黄莺啼声凄怆难闻。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ae5e272d4b225432db", "shortContent": "房太尉即房琯，玄宗幸蜀时拜相，为人比较正直。至德二载（757），为肃宗所贬。杜甫曾毅然上疏力谏，结果得罪肃宗，几遭刑戮。房琯罢相后，于宝应二年（763）拜特进、刑部尚书，在路遇疾，卒于阆州（治今四川阆中），死后赠太尉。（见《旧唐书·房琯传》）二年后杜甫经过阆州，特来看看老友的坟。\n“他乡复行役，驻马别孤坟。”——既在他乡，复值行役之中，公事在身，行色匆匆。尽管如此，诗人还是驻马暂留，来到孤坟前，向...", "authors": ["徐永端"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e0209d", "shortContent": "孤独的坟墓前，孤独的老人默然而立，浇下一杯祭奠的热泪，寄与一番深挚的理解，再蓦然回首、离去，身后留下寂然的坟墓。这首诗感情浓烈而意象凄冷，是诗人复杂内心世界的沉痛表白。\n\n房太尉，即房琯，玄宗幸蜀时拜相，为人正直，杜甫对他甚为钦慕。至德二载（757）四月，杜甫从长安逃出，辗转至凤翔，肃宗褒奖。房琯兵败罢相，杜甫时任左拾遗，上疏言：“罪细，不宜免大臣。”触怒肃宗，险遭刑戮，而终为所疏。房琯罢相，后遇...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127066c305cf0801816fb4", "shortContent": "孤独的坟墓前，孤独的老人默然而立，浇下一杯祭奠的热泪，寄予一番深挚的理解，再蓦然回首、离去，身后留下寂然的坟墓。这首诗感情浓烈而意象凄冷，是诗人复杂内心世界的沉痛表白。\n\n房太尉，即房琯，玄宗幸蜀时拜相，为人正直，杜甫对他甚为钦慕。至德二载（757）四月，杜甫从长安逃出，辗转至凤翔，获肃宗褒奖。房琯兵败罢相，杜甫时任左拾遗，上疏言：“罪细，不宜免大臣。”触怒肃宗，险遭刑戮，而终为所疏。房琯罢相，后...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "646605c37f27182da35a07ee", "shortContent": "房太尉即房琯，玄宗幸蜀时拜相，为人比较正直。至德二载（757），为肃宗所贬。杜甫曾毅然上疏力谏，结果得罪肃宗，几遭刑戮。房琯罢相后，于宝应二年（763）拜特进、刑部尚书，在路遇疾，卒于阆州（治今四川阆中），死后赠太尉。（见《旧唐书·房琯传》）二年后杜甫经过阆州，特来看看老友的坟。\n\n“他乡复行役，驻马别孤坟。”——既在他乡，复值行役之中，公事在身，行色匆匆。尽管如此，诗人还是驻马暂留，来到孤坟前，...", "authors": ["徐永端"], "pressName": "上海辞书出版社"}]', '《瀛奎律髓》：第一句自十分好：他乡已为客矣，于客之中又复行役，则愈客愈远，此句中折旋法也。“近泪无干土”，尤佳。“泪”一作“哭”，可谓痛之至而哭之多矣。“对棋”、“把剑”一联，一指生前房公之待少陵为何如，一指身后少陵之所以感房公为何如，诗之不苟如此。
《四溟诗话》：诗中泪字若“沾衣”、“沾裳”，通用不为剽窃。多有出奇荐，潘岳曰“涕泪应情倾”，子美曰“近泪无干土”。
《唐诗品汇》：刘曰：祌情苦语，着“低”、“近”二字，唯孟东野有之（“近泪”二句下）。好景，凄绝（末句下）。
《唐诗选脉会通评林》：赵云龙曰：用事典切，末语多思，愈觉惆怅。吴山民曰：三、四语悲，下句更悲。
《瀛奎律髓汇评》：冯舒：不谓之“诗圣”不可。纪昀：情至之语，然却不十分精警。三句太着迹，须是四句一旁托。五句“陪”字不似追叙，且复“对”字。
《围炉诗话》：《别房太尉墓》云：“他乡复行役，驻马别孤坟。”亦有三层苦境苦情。“近泪无干土，低空有断云”，上句意中事也，下句不知从何而来。在今思之，实存然者，当是意困境生耳。
《答万季野诗问》：问：诗唯情景，其用处何如？答：……在今卑之无甚高论，但能融景入情，如少陵之“近泪无干土，低空有断云”；寄情于景，如严维之“柳塘春水漫，花坞夕阳迟”。哀乐之意宛然，斯尽善矣。', 'center', 1416940900, '57b9bb9d79bc4400639c51d6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10544, '归嵩山作', NULL, 186, 394, 1, 2, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383292.htm', '', '清川带长薄，车马去闲闲。
流水如有意，暮禽相与还。
荒城临古渡，落日满秋山。
迢递嵩高下，归来且闭关。', '此诗通过描写作者辞官归隐嵩山途中所见的景色，抒发了作者恬静淡泊的闲适心情。首联写归隐出发时的情景；颔联写水写鸟，其实乃托物寄情，写自己归山悠然自得之情，如流水归隐之心不改，如禽鸟至暮知还；颈联写荒城古渡，落日秋山，是寓情于景，反映诗人感情上的波折变化；尾联写山之高，点明作者的归隐地点和归隐宗旨。全诗质朴清新，自然天成，尤其是中间两联，移情于物，寄情于景，意象疏朗，感情浓郁，诗人随意写来，不见斧凿之迹，却得精巧蕴藉之妙。', '嵩山：五岳之一，称中岳，地处河南省登封市西北面。
清川：清清的流水，当指伊水及其支流。清：一作“晴”。川：河川。带：围绕，映带。薄：草木丛生之地，草木交错曰薄。
去：行走。闲闲：从容自得的样子。
暮禽：傍晚的鸟儿。禽：一作“云”。相与：相互作伴。
荒城：按嵩山附近如登封等县，屡有兴废，荒城当为废县。临：当着，靠着。古渡：指古时的渡口遗址。
迢递：遥远的样子。递：形容遥远。嵩高：嵩山别称嵩高山。
且：将要。闭关：佛家闭门静修。这里有闭户不与人来往之意。闭：一作“掩”。', '清澈的川水环绕一片草木，驾车马徐徐而去从容悠闲。
流水好像对我充满了情意，傍晚的鸟儿随我一同回还。
荒凉的城池靠着古老渡口，落日的余晖洒满金色秋山。
在遥远又高峻的嵩山脚下，闭上门谢绝世俗度过晚年。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9296d635634aee3deb2a", "shortContent": "这首诗写作者辞官归隐途中所见的景色和心情。嵩山，古称“中岳”，在今河南登封县北。\n“清川带长薄，车马去闲闲。”首联描写归隐出发时的情景，扣题目中的“归”字。清澈的河川环绕着一片长长的草木丛生的草泽地，离归的车马缓缓前进，显得那样从容不迫。这里所写望中景色和车马动态，都反映出诗人归山出发时一种安详闲适的心境。\n中间四句进一步描摹归隐路途中的景色。第三句“流水如有意”承“清川”，第四句“暮禽相与还”承...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e020a3", "shortContent": "开元年间，唐玄宗常住东都洛阳，所以王维在洛阳附近的嵩山也有隐居之所。这首诗就是王维从长安（今陕西省西安市）回嵩山时所作的。诗中描写嵩山景物，以及一路的心情。\n\n“清川带长薄，车马去闲闲”，写清澈的水流映带着绵延不绝、草木丛生的林地，诗人的车马悠闲地行进。这两句描绘出一派心无挂碍、从容自在的景象。“薄”，指草木丛生之地。\n\n“流水如有意，暮禽相与还”，写傍晚场景。流水潺潺，伴人一路前行，仿佛含情脉脉...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "6464593d5fc8182fe99c6511", "shortContent": "这首诗写作者辞官归隐途中所见的景色和心情。嵩山，古称“中岳”，在今河南登封市北。\n\n清川带长薄，车马去闲闲。”首联描写归隐出发时的情景，扣题目中的“归”字。清澈的河川环绕着一片长长的草木丛生的草泽地，离归的车马缓缓前进，显得那样从容不迫。这里所写望中景色和车马动态，都反映出诗人归山出发时一种安详闲适的心境。\n\n中间四句进一步描摹归隐路途中的景色。第三句“流水如有意”承“清川”，第四句“暮禽相与还”...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "6464660fc0471b0062cb7b00", "shortContent": null, "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646464e5e49f46528aa404ad", "shortContent": "这首诗写作者辞官归隐途中所见的景色和心情。嵩山，古称“中岳”，在今河南登封市北。\n\n“清川带长薄，车马去闲闲。”首联描写归隐出发时的情景，扣题目中的“归”字。清澈的河川环绕着一片长长的草木丛生的草泽地，离归的车马缓缓前进，显得那样从容不迫。这里所写望中景色和车马动态，都反映出诗人归山出发时一种安详闲适的心境。\n\n中间四句进一步描摹归隐路途中的景色。第三句“流水如有意”承“清川”，第四句“暮禽相与还...", "authors": ["吴小林"], "pressName": "上海辞书出版社"}]', NULL, 'center', 1416941131, '57b90de3c4c97100558f8f0c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (50914, '苏幕遮', NULL, 0, 26, 0, 1, '高道宽', NULL, 11195, '5858e6398d6d810065c3153c', '元', 'ci', '词', NULL, NULL, '觅元因，恰一对。七返真药，雨味丹才配。火候刀圭深青翠。上下升降，睹面人不会。
下功夫，休贪睡。不属中间，要妙非内外。夹脊双关飞紫瑞。一颗明珠，飞上苍龙背。', NULL, NULL, NULL, NULL, NULL, 'indent', 1529685192, '585cefbab123db0065a64058', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10547, '望洞庭湖赠张丞相', NULL, 492, 266, 2, 14, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155044.htm', '', '八月湖水平，涵虚混太清。
气蒸云梦泽，波撼岳阳城。
欲济无舟楫，端居耻圣明。
坐观垂钓者，徒有羡鱼情。', '玄宗开元二十一年（公元733年），张九龄为丞相，作者西游长安，以此诗献之，以期录用。前两联描绘洞庭湖壮丽阔大而充满活力的景色；后两联抒情，表达了作者希望有人援引他入仕从政的理想。全诗“体物写志”，诗人托物抒怀，曲笔擒旨，于浩淼阔大、汹涌澎湃的自然之景中流露了心声。此诗含蓄委婉，独标风韵，不落俗套，艺术上自有特色。', '洞庭湖：中国第二大淡水湖，在今湖南省北部。
张丞相：指张九龄，唐玄宗时宰相。
涵虚：包含天空，指天空倒映在水中。涵，包容；虚，虚空、空间。
混太清：与天混为一体。清，指天空。
云梦泽：古代云梦泽分为云泽和梦泽，指湖北南部、湖南北部一带低洼地区。洞庭湖是它南部的一角。
撼：一作“动”。
岳阳城：在洞庭湖东岸。
气蒸云梦泽，波撼岳阳城：云梦大泽水汽蒸腾，洞庭湖的波涛摇撼着岳阳城。
济：渡。
楫：划船用具，船桨。
欲济无舟楫：想渡湖而没有船只，比喻想做官而无人引荐。
端居：闲居。
圣明：指太平盛世，古时认为皇帝圣明，社会就会安定。
端居耻圣明：生在太平盛世自己却闲居在家，因此感到羞愧。
坐观：一作“徒怜”。
徒：只能。一作“空”。
羡鱼：《淮南子·说林训》中说：“临河而羡鱼，不如归家织网。”', '八月洞庭湖水暴涨几与岸平，水天一色交相辉映迷离难辨。
云梦大泽水气蒸腾白白茫茫，波涛汹涌似乎把岳阳城撼动。
想要渡湖却苦于找不到船只，圣明时代闲居又觉愧对明君。
坐看垂钓之人多么悠闲自在，可惜只能空怀一片羡鱼之情。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92912cee9a0c24ecf762", "shortContent": "这是一首干谒诗。唐玄宗开元二十一年（733），孟浩然西游长安，写了这首诗赠当时在相位的张九龄，目的是想得到张的赏识和录用，只是为了保持一点身分，才写得那样委婉，极力泯灭那干谒的痕迹。\n秋水盛涨，八月的洞庭湖涨得满满的，和岸上几乎平接。远远望去，水天一色，洞庭湖和天空接合成了完完整整的一块。开头两句，写得洞庭湖极开朗也极涵浑，汪洋浩阔，与天相接，润泽着广袤大地，容纳了大大小小的河流。\n三、四句实写湖...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0f6", "shortContent": "这是一首干谒诗。唐玄宗开元二十一年（733），孟浩然西游长安，写了这首诗赠当时在相位的张九龄，目的是想得到张的赏识和录用，只是为了保持一点身份，才写得那样委婉，极力泯灭那干谒的痕迹。\n\n秋水盛涨，八月的洞庭湖涨得满满的，和岸上几乎平接。远远望去，水天一色，洞庭湖和天空接合成了完完整整的一块。开头两句，写得洞庭湖极开朗也极涵浑，汪洋浩阔，与天相接，润泽着广袤大地，容纳了大大小小的河流。\n\n三、四句实...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e020aa", "shortContent": "唐代人要进入仕途，往往需贵人引荐，写诗作文给有名望的人看，以期得到赏识提携，时称干谒。这首诗主要表现了孟浩然积极入世的思想和希望在政治上得到援引的心情。孟浩然一生中的绝大多数时间都在隐居，政治上不得意。因此，他迫切需要贵人的引荐，故作了这首有名的干谒诗。\n\n八月的洞庭湖水高涨，水面几乎与湖岸持平。湖面浩渺无边，水天相接，含混一片。云梦二泽水气蒸腾，波涛汹涌，似乎要把岳阳城撼动。想渡水却苦于找不到船...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127036c9ebcc6fbea1a38e", "shortContent": "唐代人要进入仕途，往往需贵人引荐，写诗作文给有名望的人看，以期得到赏识提携，时称干谒。这首诗主要表现了孟浩然积极入世的思想和希望在政治上得到援引的心情。孟浩然一生中的绝大多数时间都在隐居，政治上不得意。因此，他迫切需要贵人的引荐，这首诗就是一首有名的干谒诗。\n\n八月的洞庭湖水高涨，水面几乎与湖岸持平。湖面浩渺无边，水天相接，含混一片。云梦泽水气蒸腾，波涛汹涌似乎要把岳阳城撼动。想渡水却苦于找不到船...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127069c305cf0801816fdd", "shortContent": "唐代人要进入仕途，往往需贵人引荐，写诗作文给有名望的人看，以期得到赏识提携，时称干谒。这首诗主要表现了孟浩然积极入世的思想和希望在政治上得到援引的心情。孟浩然一生中的绝大多数时间都在隐居，政治上不得意。因此，他迫切需要贵人的引荐，这首诗就是一首有名的干谒诗。\n八月的洞庭湖水高涨，水面几乎与湖岸持平。湖面浩渺无边，水天相接，含混一片。云梦二泽水气蒸腾，波涛汹涌似乎要把岳阳城撼动。想渡水却苦于找不到船...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '《西清诗话》：洞庭天下壮观，骚人墨客题者众矣，终未若此诗颔联一语气象。
《王孟诗评》：刘云：托兴可伤。又云：起得浑浑，称题。“蒸”、“撼”偶然，不是下字，而气概横绝，朴不可易。“端居”兴感深厚。末语意长。
《升庵诗话》：孟浩然“八月湖水平，涵虚混太清”，虽律也，而含古意，皆起句之妙，可以为法。
《唐诗镜》：浑浑不落边际。三、四惬当，浑若天成。
《唐诗归》：钟云：此诗，人知其雄大，不知其温厚。
《唐诗选脉会通评林》：周敬曰：起便别。三、四典重，句法最为高唱。后托兴可伤。
《诗源辨体》：浩然“八月湖水平”一篇，前四句甚雄壮、后稍不称；且“舟楫”、“圣明”以赋对比，亦不工。或以此为孟诗压卷，故表明之。
《唐诗从绳》：此篇望人援手，不直露本意，但微以比兴出之，幽婉可法。此前后两切格。前叙望洞庭，后半赠张，故名两切，五、六呼应句，又是正呼反应法。
《唐诗归折衷》：唐云：气势在“蒸”、“撼”二宇。
《唐风定》：孟诗本自清澹，独此联气胜，与少陵敌，胸中几不可测（“气蒸”一联下）。
《唐诗评选》：襄阳律其可取者在一致，而气局拘迫，十九沦于酸馅，又往往于情景分界处为格法所束，安排无生趣，于盛唐诸子，品居中下，犹齐梁之有沈约，取合于浅人，非风雅之遗音也。此作力自振拔，乃貌为高，而格亦未免卑下。宋人之鼻祖，开、天之下驷，有心目中当共知之。
《姜斋诗话》：孟浩然以“舟辑”、“垂钓”钩锁含题，却自全无干涉。
《诗辩坻》：襄阳《洞庭》之篇，皆称绝唱，至欲取压唐律卷。余谓起句平平，三四雄，而“蒸”、“撼”语势太矜，句无馀力；“欲济无舟楫”二语感怀已尽，更增结语，居然蛇足，无复深味。又上截过壮，下截不称。世目同赏，予不敢谓之然也。襄阳五言律体无他长，只清苍酝藉，遂自名家，佳什亦多。《洞庭》一章，反见索露，古人以此作孟公声价，良不解也。
《唐风怀》：南村曰：起得最高。当时皆惊“云梦”二语为名句，其气概故自横绝，不知“涵虚”句尤为雄浑，下二语皆从此生。
《然灯记闻》：为诗须有章法、句法、字法……如“气蒸云梦泽，波撼岳阳城”，“蒸”字、“撼”、字，何等响，何等确，何等警拔也！
《唐诗成法》：前半何等气势，后半何其卑弱！
《唐诗别裁》：起法高深，三、四雄阔，足与题称。读此诗知襄阳非甘于隐遁者。
《闻鹤轩初盛唐近体读本》：此诗脍炙止在三、四，未尝锤炼，自然雄警，故是不易名句。后半述意正得稳婉。
《瀛奎律髓汇评》：冯舒：通篇出“临”字（按诗题一作《临洞庭湖》），无起炉造灶之烦，但见雄浑而兼潇洒，后四句似但言情，却是实做“临”字。此诗家之浅深虚实法。冯班：次联毕竟妙，与寻常作壮语者不同。纪昀：前半望洞庭湖，后半赠张相公，只以望洞庭托意，不露干乞之痕。无名氏：三、四雄奇，五、六道浑又过之。起结都含象外之意景，当与杜诗俱为有唐五律之冠。
《唐宋诗举要》：吴曰：唐人上达官诗文，多干乞之意，此诗收句亦然，而同意则超绝矣。', 'center', 1416997511, '57b339db8ac247005f235d5a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10548, '与诸子登岘山', NULL, 206, 266, 3, 1, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383319.htm', '', '人事有代谢，往来成古今。
江山留胜迹，我辈复登临。
水落鱼梁浅，天寒梦泽深。
羊公碑字在，读罢泪沾襟。', '此诗因作者求仕不遇心情苦闷而作，诗人登临岘山，凭吊羊公碑，怀古伤今，抒发感慨，想到自己空有抱负，不觉分外悲伤，泪湿衣襟。全诗借古抒怀，融写景、抒情和说理于一炉，感情真挚深沉，平淡中见深远。', '岘（xiàn）山：一名岘首山，在今湖北襄阳以南。
诸子：指诗人的几个朋友。
代谢：交替变化。
往来：旧的去，新的来。
登临：登山观看。
复登临：对羊祜（字叔子）曾登岘山而言。羊叔子镇襄阳时，常与友人到岘山饮酒诗赋，有过江山依旧人事短暂的感伤。
鱼梁：沙洲名，在襄阳鹿门山的沔水中。
梦泽：云梦泽，古大泽，即今江汉平原。
字：一作「尚」。
羊公碑：后人为纪念西晋名将羊叔子而建。', '人间之事有兴有衰，日往月来从古到今。
江山遗留名胜古迹，我们今天又来登临。
水落江浅露出鱼梁，秋来天寒梦泽更深。
羊公遗碑至今尚在，读罢碑文泪湿衣襟。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9291d635634aee3deacc", "shortContent": "这是一首吊古伤今的诗。所谓吊古，是凭吊岘首山的羊公碑。据《晋书·羊祜传》，羊祜镇荆襄时，常到此山置酒言咏。有一次，他对同游者喟然叹曰：“自有宇宙，便有此山。由来贤达胜士，登此远望如我与卿者多矣，皆湮灭无闻，使人悲伤！”羊祜生前有政绩，死后，襄阳百姓于岘山建碑立庙，“岁时飨祭焉。望其碑者，莫不流涕。”作者登上岘首山，见到羊公碑，自然会想到羊祜。由吊古而伤今，不由感叹起自己的身世来。\n“人事有代谢，往...", "authors": ["李景白"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0f8", "shortContent": "这是一首吊古伤今的诗。所谓吊古，是凭吊岘首山的羊公碑。据《晋书·羊祜传》，羊祜镇荆襄时，常到此山置酒言咏。有一次，他对同游者喟然叹曰：“自有宇宙，便有此山。由来贤达胜士，登此远望如我与卿者多矣，皆湮灭无闻，使人悲伤！”羊祜生前有政绩，死后，襄阳百姓于岘山建碑立庙，“岁时飨祭焉。望其碑者，莫不流涕”。作者登上岘首山，见到羊公碑，自然会想到羊祜。由吊古而伤今，不由感叹起自己的身世来。\n\n“人事有代谢，...", "authors": ["李景白"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e020ab", "shortContent": "登山临水，即景抒怀，是古典诗词的一大情结。这首诗是孟浩然在登临襄阳岘山时所写的遣兴之作，不事雕饰，即景会心。\n\n全诗以“人事有代谢，往来成古今”揭题，古今人事的新陈代谢是社会历史发展的规律。这是一个平凡而伟大的真理。大至朝代的更替小至一家的兴衰，以及人们的悲欢离合，生老病死，人事总是在不停顿地代谢——变化着。正是这种变化才有了整个人类社会的古往今来。《王孟诗评》说此诗“起调高古，略无粉色，而情味倶...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "6473278ba5f1e74f958c1a8e", "shortContent": "据《晋书•羊祜传》，羊祜镇荆襄时，常到此山置酒言咏。有一次，他对同游者喟然叹曰：“自有宇宙，便有此山，由来贤达胜士，登此远望如我与卿者多矣，皆湮灭无闻，使人悲伤！”羊祜生前有政绩，死后，襄阳百姓于岘首山建碑立庙，“岁时飨祭焉。望其碑者，莫不流涕”。作者登上岘首山，见到羊公碑，自然会想到羊祜。由吊古而伤今，不由感叹起自己的身世来。\n“人事有代谢，往来成古今。”这是一个平凡的真理。大至朝代更替，小至一...", "authors": ["李景白"], "pressName": "上海辞书出版社"}]', '《王孟诗评》：起得高古，略无粉色，而情景俱称。悲慨胜于形容，真岘山诗也。复有能言，亦在下风。不必苦思，自然好。苦思复不能及。
《唐诗援》：结语妙在不翻案。后人好议论，殊觉多事，乃知诗中著议论定非佳境。孟诗一味简淡，意足便止，不必求深，自可空前绝后。子美云：「吾爱襄阳孟浩然，新诗句句尽堪传。」太白云：「吾爱孟夫子，风流天下闻。」二公推服如此，岂虚语哉！
《唐风定》：风神兴象，空灵澹远，一味神化。中晚涉意，去之千里矣。
《唐律消夏录》：结语妙在前半首说得如此旷达，而究竟不免于堕泪也，悲夫！
《唐诗归折衷》：吴曰：死后有知，魂魄犹应登此。昔人所为兴慨也。读罢沾襟，能自已乎？
《唐诗矩》：前四语略率，得五、六一联精警，振起其势。「一」字大妙，有聊复尔尔之意。
《而庵说唐诗》：「我辈」二字，浩然何等自负，却在「登临」上说，尤妙。
《历代诗法》：浩气回旋，前六句含情抱感，末一句一点，通体皆灵。
《唐诗意》：羊公百世后能令人思，以比己之他日，可有人思之否，意在及时修德，正风也。
《此木轩论诗汇编》：前半首似泛而实切，此起法之高也。「羊公碑尚在」，推门落日矣。「人事有代谢」云云，直是恰好，不知者道是遇山便可如此起。
《唐诗别裁》：清远之作、不烦攻苦著力。
《茧斋诗谈》：流水对法，一气滚出，遂为最上乘。意到气足，自然浑成，逐句摹拟不得（「江山」一句下）。
《闻鹤轩初盛唐近体读本》：陈德公先生曰：前半本色高浑之笔，所谓神足。五六承以景联，章法方称，而第六尤稳，结仍浑然，有起句故有结句，亦有结意故有起句耳。慨当以慷，无限牢骚形于登眺。落句「尚」不如「字」，「字在」乃可读也。
《唐诗近体》：起四语凭空落笔，若不著题，而与羊公登山意自然神会。移置他处登山，便成泛语。
《诗境浅说》：前四句俯仰今古，寄慨苍凉。凡登临怀古之作，无能出其范围，句法一气挥洒，若鹰隼摩空而下，盘折中有劲疾之势。', 'center', 1416997573, '57b98fb5a633bd00619f8657', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10549, '宴梅道士山房', NULL, 98, 266, 1, 3, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383320.htm', '', '林卧愁春尽，搴帷览物华。
忽逢青鸟使，邀入赤松家。
金灶初开火，仙桃正发花。
童颜若可驻，何惜醉流霞。', '此诗吟咏道士山房中的景物，反映了作者失意之余的离俗之感。诗的前半部分写作者在赏玩春景时，忽然被邀到梅道士家；诗的后半部分热情赞叹梅道士的生涯。全诗巧妙运用了与道士有关的术语及典故，涉笔成趣，幽默明快，自然天成。', '梅道士：生平不详。孟浩然有《寻梅道士》《梅道士水亭》等诗，可见梅道士当是隐居近邻。诗题一作《清明宴梅道士山房》，或作《清明日宴梅道士山房》。
林卧：林下高卧，指隐居。
搴帷：掀开帷幕，一作“开轩”。
物华：自然风光。
青鸟：据《汉武故事》载，西王母欲见汉武帝，先有青鸟飞来，后以青鸟比喻使者。《山海经·西山经》：“又西二百二十里，曰三危之山，三青鸟居之。”郭璞注：“三青鸟主为西王母取食者，别自栖息于此山也。”这里指梅道士派人来请诗人赴宴。
赤松：赤松子，传说中的仙人名。《列仙传》谓：“赤松子者，神农时雨师也，服水玉以教神农，能入火自烧。往往至昆仑山上，常止西王母石室中，随风雨上下。炎帝少女追之，亦得仙俱去。至高辛时复为雨师，今之雨师本是焉。”《汉书·张良传》：“愿弃人间事，欲从赤松游耳。”这里指梅道士。
金灶：指道家炼丹的丹炉。王勃《秋日仙游观赠道士》：“雾浓金灶静，云暗玉坛空。”
仙桃：《汉武帝内传》称西王母曾以玉盘承仙桃送汉武帝：“又命侍女更索桃果。须臾，以玉盘盛仙桃七颗，大如鸭卵，形圆青色，以呈王母。母以四颗与帝，三颗自食。桃味甘美，口有盈味。”这里借指梅道士家的桃树。
童颜：像儿童一样的容颜。
驻：保持。
流霞：仙酒名。王充《论衡》：河东项曼斯好道，去乡三年而反，曰：“去时，有数仙人将上天，离月数里而止，月之旁甚寒凄怆。饥欲食，辄饮我流霞一杯，每饮辄数月不饥。”这里借指梅道士宴上的酒。', '我高卧在山林，揭开帐子欣赏山中的自然美景。
忽然梅道士派人送来书信，邀我去他那里赴宴。
房里炼丹炉刚刚点起火，屋外桃花正灼灼盛开。
如果说饮此酒能永葆青春，那我一定一醉方休。', NULL, '', 'center', 1416997639, '57baa5b2a633bd005d359a9c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10550, '岁暮归南山', NULL, 112, 266, 2, 1, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383322.htm', '', '北阙休上书，南山归敝庐。
不才明主弃，多病故人疏。
白发催年老，青阳逼岁除。
永怀愁不寐，松月夜窗虚。', '此诗系诗人归隐之作，诗中发泄了一种怨悱之情。首联两句记事，叙述停止追求仕进，归隐南山；颔联两句说理，抒发怀才不遇的感慨；颈联两句写景，自叹虚度年华，壮志难酬；尾联两句阐发愁寂空虚之情。全诗语言丰富，层层辗转反复，风格悠远深厚，富有韵味。', '岁暮：年终。南山：唐人诗歌中常以南山代指隐居题。这里指作者家乡的岘山。一说指终南山。
北阙：皇宫北面的门楼，汉代尚书奏事和群臣谒见都在北阙，后因用作朝廷的别称。《汉书·高帝纪》注：“尚书奏事，渴见之徒，皆诣北阙。”休上书：停止进奏章。
敝庐：称自己破落的家园。
不才：不成材，没有才能，作者自谦之词。明主：圣明的国君。
多病：一作“卧病”。故人：老朋友。疏：疏远。
老：一作“去”。
青阳：指春天。逼：催迫。岁除：年终。
永怀：悠悠的思怀。愁不寐：因忧愁而睡不着觉。寐：一作“寝”。
虚：空寂。一作“堂”。', '不再在朝廷宫门前陈述已见，返归终南山我那破旧的茅屋。
没有才能才使君主弃我不用，又因多染病痛朋友与我离疏。
白发渐渐增多催人慢慢老去，岁暮已至新春已经快要临近。
心怀愁绪万千使人夜不能寐，松影月光映照窗户一片空寂。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9292dbb8b379ee095956", "shortContent": "约在开元十六年（728），四十岁的孟浩然来长安应进士举落第了，心情很苦闷。他曾“为文三十载，闭门江汉阴”，学得满腹文章，又得到王维、张九龄为之延誉，已经颇有诗名。这次应试失利，使他大为懊丧，他想直接向皇帝上书，又很犹豫。这首诗是在这样心绪极端复杂的情况下写出来的。他有一肚子的牢骚而又不好发作，因而以自怨自艾的形式抒发仕途失意的幽思。表面上是一连串的自责自怪，骨子里却是层出不尽的怨天尤人；说的是自己...", "authors": ["傅经顺崔闽"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f2b73206168b2e020ad", "shortContent": "关于此诗有一个广为流传的故事，事见《新唐书•文艺传下》：“（王）维私邀（孟浩然）入内署，俄而玄宗至，浩然匿床下。维以实对，帝喜曰：‘朕闻其人而未见也，何惧而匿？’诏浩然出。帝问其诗，浩然再拜，自诵所为，至‘不才明主弃’之句，帝曰：‘卿不求仕，而朕未尝弃卿，奈何诬我？’因放还。”我们认为，故事可能是小说家言，未必可信。不过，此诗倒因有这一段故事而广为传诵。\n\n开元十六年（728），孟浩然赴长安应进士...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '《新唐书·文艺传下》：（王）维私邀（孟浩然）入内署，俄而玄宗至，浩然匿床下。维以实对，帝喜曰：“朕闻其人而未见也，何惧而匿？”诏浩然出。帝问其诗，浩然再拜，自诵所为，至“不才明主弃”之句，帝曰：“卿不求仕，而朕未尝弃卿，奈何诬我？”因放还。
王之望《上宰相书》：孟浩然在开元中诗名亦高，本无宦情，语亦俨淡。及“北阙”、“南山”之诗，作意为愤躁语，此不出乎情性，而失其音气之和，果终弃工明主。
刘辰翁《王孟诗评》：刘云：他人有此起，无此结，每见短气。又云：是其最得意之诗，亦其最失意之日，故为明皇诵之。
方回《瀛奎律髓》：八句皆超绝尘表。
《唐诗归》：钟云：五字恕（“北阀”句下）。谭云：自言自语妙。钟云：浩然于明皇前诵此二句，自是山人草野气（“不才”一联下）。
《唐诗选脉会通评林》：周珽曰：三、四二语不朽，识力名言，真投之天地劫火中，亦可历劫不变。
《增订唐诗摘钞》：结句是寂寥之甚，然只写景，不说寂寥，含蓄有味。
黄生《唐诗矩》：写景结，隽永。此诗未免怨，然语言尚温厚。卢纶亦有《下第归终南别业》诗，与此相较，便见盛唐人身份。
徐增《而庵说唐诗》：此作字字真性情，当是浩然极得手之作。
《唐贤三昧集笺注》：纯是真气贯注。
《闻鹤轩初盛唐近体读本》：陈德公曰：三、四婉笔叙质语，意尽而更饶隽韵，此最不易。宋人为之，败矣。诗联风花易构，质语难工，以此。五、六“青阳”二字，对出人意。岁前春与岁后春皆可作也，而岁后春作此更有情。
《瀛奎律髓汇评》：冯舒：一生失意之诗，千古得意之作。纪昀：三、四亦尽和平，不幸而遇明皇尔。或以为怨怒太甚，不及老杜“官应老病休”句之温厚，则是以成败论人也。结句亦前人所称，意境殊为深妙。然“永怀愁不寐”句尤见缠绵笃挚，得诗人风旨。
张谦宜《茧斋诗谈》：绝不怒张，浑成如铁铸。
《唐诗合选详解》：吴绥眉曰：此种最为清雅，不求工而自合。
高步瀛《唐宋诗举要》：结句意境深妙。', 'center', 1423215600, '57b95d1bd342d3005aca5be6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10551, '过故人庄', NULL, 1539, 266, 3, 18, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155078.htm', '', '故人具鸡黍，邀我至田家。
绿树村边合，青山郭外斜。
开轩面场圃，把酒话桑麻。
待到重阳日，还来就菊花。', '此诗写应邀到一位农村老朋友家做客的经过。在淳朴自然的田园风光之中，举杯饮酒，闲谈家常，充满了乐趣，抒发了诗人和朋友之间真挚的友情。这首诗初看似乎平淡如水，细细品味就像是一幅画着田园风光的中国画，将景、事、情完美地结合在一起，具有强烈的艺术感染力。', '过：拜访。
故人庄：老朋友的田庄。庄，田庄。
具：准备，置办。
鸡黍（shǔ）：指农家待客的豐盛饭食（字面指鸡和黄米饭）。黍：黄米，古代认为是上等的粮食。
合：环绕。
郭：古代城墙有内外两重，内为城，外为郭。这里指村庄的外墙。
场圃：场，打穀场、稻场；圃，菜园。
把酒：端着酒具，指饮酒。
把：拿起。端起。
话桑麻：闲谈农事。桑麻，桑树和麻。这裏泛指庄稼。
重阳日：指夏历的九月初九。古人在这一天有登高、饮菊花酒的习俗。
还（huán）：返，来。
就菊花：指饮菊花酒，也是赏菊的意思。就，靠近，指去做某事。', '老朋友预备丰盛的饭菜，邀请我到好客的农家。
翠绿的树林围绕着村落，苍青的山峦在城外横卧。
推开窗戸面对谷场菜园，手举酒杯闲谈庄稼情况。
等到九九重阳节到来时，再请君来这里观赏菊花。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929134a8757d5a0e1b9e", "shortContent": "清沈德潜称孟浩然的诗“语淡而味终不薄”（《唐诗别裁集》）。也就是说，读孟诗，应该透过它淡淡的外表，去体会内在的韵味。《过故人庄》在孟诗中虽不算是最淡的，但它用省净的语言，平平地叙述，几乎没有一个夸张的句子，没有一个使人兴奋的词语，也已经可算是“淡到看不见诗”（闻一多《孟浩然》）的程度了。它的诗味究竟表现在哪里呢？\n“故人具鸡黍，邀我至田家。”这一开头似乎就像是日记本上的一则记事。故人“邀”而我“至...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0f9", "shortContent": "清沈德潜称孟浩然的诗“语淡而味终不薄”（《唐诗别裁集》）。也就是说，读孟诗，应该透过它淡淡的外表，去体会内在的韵味。《过故人庄》在孟诗中虽不算是最淡的，但它用省净的语言，平平地叙述，几乎没有一个夸张的句子，没有一个使人兴奋的词语，也已经可算是“淡到看不见诗”（闻一多《孟浩然》）的程度了。它的诗味究竟表现在哪里呢？\n\n“故人具鸡黍，邀我至田家。”这一开头似乎就像是日记本上的一则记事。故人“邀”而我“...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f0931c", "shortContent": "中国是礼仪之邦，中国人也素来热情好客。这种热情不是停留在表面形式上，而是深入到日常言行之中，好客是发自内心的。因为是发自内心，所以不讲形式。因为不讲形式，客人也言行自然，有“宾至如归”之感。中国人这种真诚好客的民族情结表现在许多经典诗文之中。孟浩然的这首诗就以清新自然的语句写出了自己做客的经历。\n\n首联“故人具鸡黍，邀我至田家”，点题，开门见山，入笔自然。如叙家常一样娓娓道来，显得轻松自如，简单随...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127036c9ebcc6fbea1a396", "shortContent": "中国是礼仪之邦，中国人也素来热情好客。这种热情不是停留在表面形式上，而是深入到日常言行之中，好客是发自内心的。因为是发自内心，所以不讲形式。因为不讲形式，客人也言行自然，有“宾至如归”之感。中国人这种真诚好客的民族情结表现在许多经典诗文之中。孟浩然的这首诗就以清新自然的语句写出了自己做客的经历。\n\n首联“故人具鸡黍，邀我至田家”，点题，开门见山，入笔自然。如叙家常一样娓娓道来，显得轻松自如，简单随...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127069c305cf0801816fde", "shortContent": "中国是礼仪之邦，中国人也素来热情好客。这种热情不是停留在表面形式上，而是深入到日常言行之中，好客是发自内心的。因为是发自内心，所以不讲形式。因为不讲形式，客人也言行自然，有“宾至如归”之感。中国人这种真诚好客的民族情结表现在许多经典诗文之中。孟浩然的这首诗就以清新自然的语句写出了自己做客的经历。\n首联“故人具鸡黍，邀我至田家”，点题，开门见山，入笔自然。如叙家常一样娓娓道来，显得轻松自如，简单随和...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '《王孟诗评》：刘云：每以自在相凌厉者，极是。
《瀛奎律髓》：此诗句句自然，无刻划之迹。
《升庵诗话》：孟集有「到得重阳日，还来就菊花」之句，刻本脱一「就」宇，有拟补者，或作「醉」，或作「赏」，或作「泛」，或作「对」，皆不同，后得善本是「就」字，乃知其妙。
《唐诗摘钞》：全首俱以信口道出，笔尖幾不着点墨。浅之至而深，淡之至而浓，老之至而媚。火候至此，并烹炼之迹俱化矣。王、孟并称，意尝不满于孟。若此作，吾何间然？结句係孟对故人语，觉一片真率款曲之意溢于言外。
《增订唐诗摘钞》：「就」字百思不到，若用「看」字，便无味矣。
《唐诗成法》：以古为律，得闲適之意，使靖节为近体，想亦不过如此而已。
《唐诗别裁》：通体清妙。末句「就」字作意，而归于自然。
《网师园唐诗笺》：野景幽情（「把酒」句下）。
《闻鹤轩初盛唐近体读本》：一意淡，结作小致。虽古今不同，居然元亮品格。第五欲作异使，对句亦逸，「就」字新。
《瀛奎律髓汇评》：冯舒：字字珠玉，「就」字真好。纪昀：王、孟诗大段相近，而体格又自微别。王清而远，孟清而切。学王不成，流为空腔；学孟不成，流为浅语。如此诗之自然冲淡，初学遽躐等而效之，不为滑调不止也。
《唐诗近体》：通体樸实，而语意清妙。', 'center', 1416997791, '57b31b2f5bbb500062e8829f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (50915, '苏幕遮', NULL, 0, 26, 0, 1, '高道宽', NULL, 11195, '5858e6398d6d810065c3153c', '元', 'ci', '词', NULL, NULL, '采壶中，凝日月。片饷工夫，锻炼无休歇。满岸芦花白如雪。丹蕊飞来，教我如何说。
道无明，真一诀。得也第庐，自在闲守拙。直待鹤来方外接。白日飞升，有分朝金阙。', NULL, NULL, NULL, NULL, NULL, 'indent', 1529685193, '585cefba1b69e600560ed6df', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (50916, '苏幕遮', NULL, 0, 26, 0, 1, '高道宽', NULL, 11195, '5858e6398d6d810065c3153c', '元', 'ci', '词', NULL, NULL, '玉炉中，烧丹药。锻炼三成，最上真个妙。海底龟蛇勤收捉。纳在壶中，炼就圆明觉。
照无边，光灼灼。顺手拈来，直下长生勺。功行十分凭戒约。一对芒鞋，穿上踏云脚。', NULL, NULL, NULL, NULL, NULL, 'indent', 1529944449, '585cefba61ff4b00580c74ca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10552, '秦中感秋寄远上人', NULL, 97, 266, 1, 1, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/414624.htm', '', '一丘常欲卧，三径苦无资。
北土非吾愿，东林怀我师。
黄金燃桂尽，壮志逐年衰。
日夕凉风至，闻蝉但益悲。', '从这首诗的内容看，当为孟浩然在长安落第之后的作品。寄给名叫远的僧人，报告客居逢秋的苦情，诉说欲隐无处，欲仕非愿，进退两难之苦。
首联诉说自己隐居的愿望和无力隐居的苦衷；颔联写自己北上求仕的违背心愿的羡慕跳出尘世的远上人；颈联写困居长安的境况，雄心壮志逐年衰减；尾联描写黄昏、秋风、鸣蝉，一派萧瑟景象，突出了客中的抑郁心情。全诗反映了作者当时困苦的境地和对仕途的失望，寄赠是表，抒发不遇之感是实。', '秦中：此指长安。远上人：上人是对僧人的敬称，远是法号。事迹未详。
一丘：即一丘一壑，意指隐居山林。语出《晋书·谢鲲传》。
三径：《三辅决录》卷一谓“蒋翊归乡里，荆棘塞门，舍中有三径，不出，唯求仲、羊仲从之游”。后指归隐后所住的田园。资：钱财。
“北土”句：谓说不愿留京从仕。北土，指秦中。
东林：指庐山东林寺，东晋高僧慧远在庐山的禅舍。这里借指远上人所在的寺院。
“黄金”句：《战国策·楚策三》谓“楚国之食贵于玉，薪贵于桂”。这里喻处境窘困。燃桂，烧贵如桂枝的柴。
日夕：傍晚。
闻蝉：听蝉鸣能引起人悲秋之感。卢思道《听鸣蝉篇》有“听鸣蝉，此听悲无极”。益：增加。', '韵译
本想长久地归隐山林，又苦于无钱举步维艰。
滞留长安不是我心愿，心向东林把我师怀念。
黄金像烧柴一般耗尽，壮志随岁月逐日衰减。
黄昏里吹来萧瑟凉风，听晚蝉声声愁绪更添。
散译
我常常想要归卧丘山，苦于没有资财把庭院经营。滞留西秦不是我的夙愿，我向往那高僧所在的东林。囊中黄金已在羁旅中用尽，壮志一年年渐渐地消沉。傍晚时分，凉风吹来，又听见秋蝉哀鸣，我的心情越发悲伤起来。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9291d635634aee3deaa9", "shortContent": "从这首诗的内容看，当为孟浩然在长安落第之后的作品。诗中充满了失意、悲哀与追求归隐的情绪，是一首坦率的抒情诗。\n第一联从正面写“所欲”。作者的所欲，本为隐逸；但诗中不用隐逸而用“一丘”、“三径”的典故。“一丘”颇具山野形象，“三径”自有园林风光。用形象以表明隐逸思想，是颇为自然的。然而“苦无资”三字却又和所欲发生了矛盾，透露出作者穷困潦倒的景况。\n“北土非吾愿”，是从反面写“不欲”。“北土”指“秦中...", "authors": ["李景白"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f0931d", "shortContent": "这首诗，有论者以为当为孟浩然在长安落第后的作品，诗中充满了失意、悲哀与追求归隐的情绪。因为缺少材料支撑，是否为落第后所作，不能确指，但是诗中确实充满了“失意、悲哀”的情绪。至于“追求归隐”云云，从表面上看的确有之，然而文人失意后发发牢骚也是常有的事，况且从文本证之，似乎写此诗时孟浩然尚未下定决心归隐。\n\n首联讲欲归隐而不得。一丘，即一丘一壑，意指隐居山林。《三辅决录》卷一谓“蒋翊归乡里，荆棘塞门，...", "authors": ["李曙光"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127036c9ebcc6fbea1a38f", "shortContent": "秋，是一个让人容易伤感的季节，落叶萧萧，勾起的是失意人难以排遣的苦涩和抑郁不得志的感怀。有那样一个诗人，在长安的一个秋天，无奈赋诗，留给后人咏叹。\n\n孟浩然，少时隐居鹿门山，四十岁时到长安应进士举，失意而归，张九龄镇荆州时，招至幕府，其间一直想让张九龄援引以实现自己的政治愿望，但终未能如愿，后病疽死。\n\n《秦中感秋寄远上人》正是这样一首悲情诗，诗中写了诗人向“远上人”诉说他求仕不成，不得已才想要去...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '宋·刘辰翁《孟浩然诗集》引：非不经思，只是吐出。
明·李梦阳《孟浩然诗集》引：“黄金燃桂尽”，终伤气。结句好。', 'center', 1416997885, '57b93e2fc4c97100559135fd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10553, '宿桐庐江寄广陵旧游', NULL, 127, 266, 1, 2, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155050.htm', '', '山暝听猿愁，沧江急夜流。
风鸣两岸叶，月照一孤舟。
建德非吾土，维扬忆旧游。
还将两行泪，遥寄海西头。', '此诗是作者离开长安东游时，途中寄给旧友的。前四句描绘了一幅月夜行舟图：猿声在夜中传来江流滔滔不断，树叶萧萧而下，极写景色的寥落凄寂，同作者凄凄惶惶的心情互为衬映。后四句借景生情，怀念友人，情景融合得很自然。月夜宿孤舟，心中愁闷，自然而生怀友之情，因而热泪横流。', '桐庐江：即桐江，在今浙江省桐庐县境。广陵：今江苏省扬州市。旧游：指故交。
暝：指黄昏。
沧江：指桐庐江。沧同“苍”，因江色苍青，故称。
建德：唐时郡名，今浙江省建德县一带。汉代，建德桐庐同属富春县。此外以建德代指桐庐。
非吾土：不是我的故乡。王粲《登楼赋》：“虽信美而非吾土兮，曾何足以少留。”
维扬：扬州的别称。《洞书·禹贡》：“淮海维扬州。”
遥寄：远寄。海西头：指扬州。隋炀帝《泛龙舟歌》：“借问扬州在何处，淮南江北海西头。”因古扬州幅员辽阔，东临大海，故称。
海西头：指扬州。古扬州幅员广阔，东滨大海，在海之西，故云。', '山色昏暗，猿啼声声，听来忧愁。夜色之中，大江急流，令人思归。
晚风吹来，两岸树叶萧萧；月光之下，一叶孤舟飘摇。
建德不是我的家乡，遥想扬州旧日友人。
思乡伤感，无可奈何，只能将两行热泪，遥寄到大海西头。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92912cee9a0c24ecf765", "shortContent": "这首诗在意境上显得清寂或清峭，情绪上则带着比较重的孤独感。\n诗题点明是乘舟停宿桐庐江的时候，怀念广陵（即扬州）友人之作。桐庐江为钱塘江流经桐庐县一带的别称。“山暝听猿愁，沧江急夜流。”首句写日暮、山深、猿啼。诗人伫立而听，感觉猿啼似乎声声都带着愁情。环境的清寥，情绪的黯淡，于一开始就显露了出来。次句沧江夜流，本来已给舟宿之人一种不平静的感受，再加上一个“急”字，这种不平静的感情，便简直要激荡起来了...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f0931e", "shortContent": "忆旧，是中老年的思维习惯。在他们的心里，旧时的朋友是那么的真诚，昔日的生活环境是那么的温馨，以前的生活是那么的美好。这种忆旧恋旧的情结，很大程度上来源于现实生活的不如意。今昔对比，故乡、故土、故人成了诗人心中永恒的向往。\n\n这是作者乘船停泊桐庐江时，怀念广陵（今扬州）朋友而作。此时的作者求官不成，四处奔波，故而怀念旧日友人。“山暝听猿愁，沧江急夜流。”山色昏暗，猿猴啼叫，声声都带着悲愁，夜里苍江水...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', NULL, 'center', 1417168262, '57b9018d128fe10054c9905f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10554, '留别王侍御维 / 留别王维', NULL, 178, 266, 3, 2, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/item/留别王侍御维', '', '寂寂竟何待，朝朝空自归。
欲寻芳草去，惜与故人违。
当路谁相假，知音世所稀。
只应守索寞，还掩故园扉。', '此诗是唐代诗人孟浩然将离长安时赠别王维之诗作。诗中先述说自己在京没有什么希望，天天在寂寞失望中度日，想离京却又可惜与好友分别，表达了心中的怅惘和矛盾。接着慨叹自己无人援引，只好甘守寂寞，回乡隐居。全诗语调低沉，有对朝廷压抑人才的怨愤，有不忍远别知心朋友的留恋，还有怀才不遇的嗟叹。语言浅显，表达直率，对偶不求工整，但却自然流畅，显示出一种不事雕琢的自然之美。', '王侍御维：即唐代诗人王维。唐代称殿中侍御史、监察御史为侍御。
寂寂：落寞。汉秦嘉《赠妇诗》：“寂寂独居，寥寥空室。”竟何待：要等什么。
朝（zhāo）朝：天天；每天。《列子·仲尼》：“子列子亦微焉，朝朝相与辩。”空自：独自。南朝梁何逊《哭吴兴柳恽》诗：“樽酒谁为满，灵衣空自披。”
芳草：本义为香草，古诗中常比喻为美好的品德。此处指美好的处所，暗喻隐逸生活。《楚辞·离骚》：“何昔日之芳草兮，今直为此萧艾也。”
故人：旧交；老友。《庄子·山木》：“夫子出于山，舍于故人之家。”违：分离。
当路：身居要职的当权者。宋陈亮《庶弟昭甫墓志铭》：“畴昔之年，当路欲置我于死地，病馀而继以囚系。”假：宽假，优容的意思。
知音：知己。《列子·汤问》载：伯牙善鼓琴，钟子期善听琴。伯牙琴音志在高山，子期说“峨峨兮若泰山”；琴音意在流水，子期说“洋洋兮若江河”。伯牙所念，钟子期必得之。后世遂以“知音”比喻知己，同志。
索：一作“寂”。
故园：旧家园；故乡。唐骆宾王《晚憩田家》诗：“唯有寒潭菊，独似故园花。”扉（fēi）：门扇。', '这样寂寞我还在等待什么？天天出门求仕却一无所获。
本打算归隐山林寻找佳境，又因与故友离别深感惋惜。
身居高位者谁能保荐我呢？可惜世上知音人稀若晨星。
我这寒士只应该甘守寂寞，还是回到故园闭门隐居吧！', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92910ce818559d05863a", "shortContent": "据《旧唐书·文苑传》载，孟浩然“年四十，来游京师，应进士不第，还襄阳”。这首诗便是临行前留给王维的，怨怼之中，又带有辛酸意味，感情真挚动人。\n第一联写落第后的景象：门前冷落，车马稀疏。“寂寂”两字，既是写实，又是写虚，既表现了门庭的景象，又表现了作者的心情。一个落第士子，又有谁来理睬，又有谁来陪伴？只有孤单单地“空自归”了。在这种情形下，长安虽好，也没有什么可留恋的。他考虑到返回故乡了，“竟何待”...", "authors": ["李景白"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f0931f", "shortContent": "孟浩然四十岁时赴长安应进士第，落第还乡，临行前告别王维时作了这首诗。一个仕途落寞又颇有书生脸面的人给一个功成名就的朋友写诗，内含失落、渴望举荐又不好明说，种种复杂的心理一起涌上心头，辛酸怨怼又感情真挚。\n\n首联“寂寂竟何待，朝朝空自归。”“寂寂”，即落寞，指作者落第后的落寞处境；“竟何待”，即竟待何，还等待什么的意思。朝朝空归，写出了作者落第处境与失落心态。在这样寂寞无聊的日子还有什么可期待的呢？...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127036c9ebcc6fbea1a391", "shortContent": "孟浩然四十岁时赴长安应进士第，落第还乡，作者临行前告别王维时作了这首诗。一个仕途落寞又颇有书生脸面的人给一个功成名就的朋友写诗，内含失落、渴望举荐又不好明说，种种复杂的心理一起涌上心头，辛酸怨怼又感情真挚。\n\n首联“寂寂竟何待，朝朝空自归”。“寂寂”的意思是作者当时的落寞的处境，“竟何待”即竟待何，还等待什么的意思。朝朝空归，写出了作者落第处境与失落心态。这样寂寞无聊的日子还有什么可期待的呢？“我...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '宋代刘辰翁《王孟诗评》：个中人，个中语，看着便不同（首四句下）。末意更悲。
清代吴煊、胡棠《唐贤三昧集笺注》：三、四醇茂，胎息汉人。
清代沈德潜《唐诗别裁》：客中无聊之况（“寂寂”句下）。
清代王闿运《王闿运手批唐诗选》：真情（“欲寻”二句下）。', 'center', 1417168376, '57b91beb79bc44005b9f8182', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10555, '早寒江上有怀 / 早寒有怀 / 江上思归', NULL, 191, 266, 1, 5, '孟浩然', NULL, 10029, '57b9247a165abd0054c0fc61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/435310.htm', '', '木落雁南度，北风江上寒。
我家襄水曲，遥隔楚云端。
乡泪客中尽，孤帆天际看。
迷津欲有问，平海夕漫漫。', '此诗是唐代诗人孟浩然所作的一首怀乡思归的抒情诗。诗从萧索的秋景入手，写出客居异地时对家乡的无限思念，以及面对隐居与从政的抉择时的迷茫心情。诗人在异乡遥望故乡，深深地眷念襄阳、襄水，但故乡可望而不可及，只能垂下思乡之泪、遥看天际孤帆。这一种飘零之感只有羁旅中人才能深切地体会到。这首诗透露出作者长安碰壁之后的牢骚和惘然，思乡之情和写景之句浑然一体，深沉含蓄。全诗情景交融，言淡而意远。而发自内心对寒江的怀念之情，由此引发了首尾呼应。', '木落：树木的叶子落下来。
雁南度：大雁南飞。度，一作“渡”。南，一作“初”。
“木落雁南度，北风江上寒。”句：从鲍照《登黄鹤矶》“木落江渡寒，雁还风送秋”句脱化而来。
襄（xiāng）水曲（qū）：在汉水的转弯处。襄水，汉水流经襄阳（今属湖北）境内的一段。曲，一作“上”，江水曲折转弯处，即河湾。襄，一作“湘”，又作“江”。
楚云端：长江中游一带云的尽头。云，一作“山”。
乡泪客中尽：思乡眼泪已流尽，客旅生活无比辛酸。
孤：一作“归”。
天际：天边。一作“天外”。
迷津：迷失道路。津，渡口。
平海：长江下游入海口附近江面宽阔，水势浩大，称为“平海”。
“迷津欲有问，平海夕漫漫”句：表示自己落拓失意，前途渺茫之叹。《论语微子》记载，孔子曾经在旅途中迷失方向，让子路向正在耕种的隐士长沮、桀溺询问渡口（迷津）。', '树叶飘落，大雁飞向南方，北风萧瑟因而江上分外寒冷。家乡就在弯弯曲曲的襄水边，远隔楚云之端。思乡的眼泪已流尽，客旅的生活无比辛酸，看归来的帆在天边徜徉。风烟迷失了去渡口的道路，茫茫江水在夕阳下荡漾。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92915914587d02f4e437", "shortContent": "这是一首抒情诗。根据诗的内容看，大约是作者漫游长江下游时的作品。当时正是秋季，天却相当寒冷。睹物伤情，不免想到故乡，引起了思乡之泪。再加以当时作者奔走于长江下游各地，既为隐士，而又想求官；既羡慕田园生活，而又想在政治上有所作为。因而此诗流露的感情是相当复杂的。\n“木落雁南度，北风江上寒”，这两句是写景。作者捕捉了当时带有典型性的事物，点明季节。木叶渐脱，北雁南飞，这是最具代表性的秋季景象。但是单说...", "authors": ["李景白"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0f7", "shortContent": "这是一首抒情诗。根据诗的内容看，大约是作者漫游长江下游时的作品。当时正是秋季，天却相当寒冷。睹物伤情，不免想到故乡，引起了思乡之泪。再加以当时作者奔走于长江下游各地，既为隐士，而又想求官；既羡慕田园生活，而又想在政治上有所作为。因而此诗流露的感情是相当复杂的。\n\n“木落雁南度，北风江上寒”，这两句是写景。作者捕捉了当时带有典型性的事物，点明季节。木叶渐脱，北雁南飞，这是最具代表性的秋季景象。但是单...", "authors": ["李景白"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f09320", "shortContent": "孟浩然自幼生活于“襄阳美会稽”的秀丽山水中，受其陶冶，又受到故乡古代隐逸高风的熏染，形成了时怀隐逸、流连山水的情怀。但孟浩然并不是一个一生只求高卧云山的隐士，他小时就怀有“鸿鹄志”，济时用世的愿望很强烈。他早期的隐居，实是为出仕而隐，本希望通过隐居著文和结交干谒获得社会声誉，谋取王公大臣的荐举，以实现入仕的目的。可惜这条路很难走通，他转而出山应进士试，结果落第。尔后又尝试其他求官之路，最终都未成功...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127036c9ebcc6fbea1a390", "shortContent": "孟浩然自幼生活于“襄阳美会稽”的秀丽山水中，受其陶冶，又受到故乡古代隐逸高风的熏陶，形成了时怀隐逸、流连山水的情怀。但孟浩然并不是一个一生只求高卧云山的隐士，他小时就怀有“鸿鹄志”，济时用世的愿望很强烈。他早期的隐居，实是为出仕而隐，本希望通过隐居著文和结交干谒获得社会声誉，谋取王公大臣的荐举，以实现入仕的目的。可惜这条路很难走通，他转而出山应进士试，结果落第。尔后又尝试其他求官之路，最终都未成功...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '', 'center', 1417168458, '57ba2878a633bd005d317e45', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10561, '淮上喜会梁州故人', NULL, 288, 570, 2, 2, '韦应物', NULL, 10115, '57b9b835128fe1005f860400', '唐', 'shi', '诗', 'http://baike.baidu.com/view/414638.htm', '', '江汉曾为客，相逢每醉还。
浮云一别后，流水十年间。
欢笑情如旧，萧疏鬓已斑。
何因北归去，淮上对秋山。', '此诗写作者在淮水边重逢阔别十年的梁州老朋友的喜悦之情，颇有感慨。首联概括了以前的交谊；颔联统包了分别十年繁複的世事人情；颈联和末联写重逢情景。写相聚、痛饮和欢笑，写环境、形貌和心思，是诗的主体。全诗结构细密，情意曲折，重点突出，韵致悠远。', '淮上：淮水边，即今江苏淮阴一带。
梁州：唐州名，在今陕西南郑县东。
江汉：汉江，流经梁州。
「浮云一别后，流水十年间」句：谓人生聚散无常而时光逝如流水。
萧疏：稀疏。
斑：头髮花白。
北归去：一作「不归去」。
对秋山：一作「有秋山」。', '我俩曾一同客居在江汉，每次相逢定要酣醉而还。
自从离别后飘游如云浮，十年岁月宛如大江流水。
今日相见我们欢笑如故，我们已两鬓斑白发稀疏。
你问我为何不返回家乡，只因贪恋淮上美丽秋山。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b803048e64fbd91445", "shortContent": "这首诗描写诗人在淮上（今江苏淮阴一带）遇见了梁州（治今陕西汉中市）故人的情况和感慨。他和这位老朋友，十年前在梁州江汉一带有过交往。诗题曰“喜会”故人，诗中表现的却是“此日相逢思旧日，一杯成喜亦成悲”那样一种悲喜交集的感情。\n诗的开头，写诗人昔日在江汉作客期间与故人相逢时的乐事，概括了以前的交谊。那时他们经常欢聚痛饮，扶醉而归。诗人写这段往事，仿佛是试图从甜蜜的回忆中得到慰藉，然而其结果反而引起岁月...", "authors": ["林东海"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a8c", "shortContent": "这首诗描写诗人在淮上（今江苏淮阴一带）遇见了梁州（治今陕西汉中市）故人的情况和感慨。他和这位老朋友，十年前在梁州江汉一带有过交往。诗题曰“喜会”故人，诗中表现的却是“此日相逢思旧日，一杯成喜亦成悲”那样一种悲喜交集的感情。\n\n诗的开头，写诗人昔日在江汉作客期间与故人相逢时的乐事，概括了以前的交谊。那时他们经常欢聚痛饮，扶醉而归。诗人写这段往事，仿佛是试图从甜蜜的回忆中得到慰藉，然而其结果反而引起岁...", "authors": ["林东海"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f09329", "shortContent": "按古人的说法，人生有四大喜事，其中就有“他乡遇故知”一喜。在他乡昧生之地遇上故朋旧友，自然喜出望外。这首诗就写这种情景。\n\n在淮上（今天江苏淮阴一带），韦应物遇见了旧时在梁州（今陕西汉中市）时的好朋友。诗题为“喜会”，似乎讲的是相逢后极其快乐的心情，但诗中表现的却是一种喜后生悲的复杂感情。\n\n诗歌从回忆往事开始写起。当年，我们都客居江汉，经常聚在一起喝酒。那时多欢快啊，常常是喝得酩酊大醉而归。人生...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706a7f0b9738b369b211", "shortContent": "按古人的说法，人生有几大喜事，其中就有“他乡遇故知”一喜。在他乡陌生之地遇上故朋旧友，自然喜出望外。这首诗就写这种情景。\n\n在淮上（今江苏淮阴一带），韦应物遇见了旧时在梁州（今陕西汉中）时的好朋友。诗题为“喜会”，似乎讲的是相逢后极其快乐的心情，但诗中表现的却是一种喜后生悲的复杂感情。\n\n诗歌从回忆往事开始写起。当年，我们都客居江汉，经常聚在一起喝酒。那时多欢快啊，常常是喝得酩酊大醉而归。人生无常...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270f073206168b2e02299", "shortContent": "按古人的说法，人生有几大喜事，其中就有“他乡遇故知”一喜。在他乡陌生之地遇上故朋旧友，自然喜出望外。这首诗就写这种情景。\n在淮上（今天江苏淮阴一带），韦应物遇见了旧时在梁州（今陕西汉中）时的好朋友。诗题为“喜会”，似乎讲的是相逢后极其快乐的心情，但诗中表现的却是一种喜后生悲的复杂感情。\n\n诗歌从回忆往事开始写起。当年，我们都客居江汉，经常聚在一起喝酒。那时多欢快啊，常常是喝得酩酊大醉而归。人生无常...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '《四溟诗话》：此篇多用虚字，辞达有味。
《唐诗选脉会通评林》：周珽曰：人如浮云易散，一别十年，又若流水去无还期，二语道尽别离情绪。他如「旧国应无业，他乡到是归」，其悲慨之思可想。
《瀛奎律髓汇评》：查慎行：五六浅语，却气格高。纪昀：清圆可诵。无名氏（甲）：大抵平淡诗非有深情者不能为，若一直平淡，竟如槁木死灰，曾何足取？此苏州三首，极有深情，所谓「看似寻常最奇崛，成如容易却艰难」也。
《唐诗近体》：情景婉至（「浮云」二句下）。结意佳。
《唐诗三百首》：一气旋折，八句如一句。
《唐宋诗举要》：似王、孟。', 'center', 1417179163, '57b985300a2b58005fc6e326', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10556, '秋日登吴公台上寺远眺', NULL, 164, 492, 3, 2, '刘长卿', NULL, 10113, '57b9a043165abd00661cbf89', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383367.htm', '', '古台摇落后，秋日望乡心。
野寺来人少，云峰隔水深。
夕阳依旧垒，寒磬满空林。
惆怅南朝事，长江独至今。', '此诗描写了诗人登吴公台所见的萧瑟荒凉的景象，深刻反映了唐朝中期安史之乱后荒凉破败的景象，也反映了作者忧国忧民的心声。全诗抚今追昔，感慨深沉，风格悲壮苍凉，意境深远悠长。有人认为，最后两句有「大江东去，浪淘尽千古风流人物」之气韵。', '吴公台：在今江苏省江都县，原为南朝沈庆之所筑，后陈将吴明彻重修。
摇落：零落。凋残。这里指臺已倾废。语出宋玉《九辨》：「悲哉秋之为气也，萧瑟兮摇落而变衰。」
野寺：位于偏地的寺庙。这里指吴公台上寺。
依：靠，这里含有「依恋」之意。
旧垒：指吴公台。垒：军事工事。按吴公台本为陈将吴明彻重筑的弩台。
寒磬：清冷的磬声。磬：寺院中敲击以召集众僧的鸣器，这里指寺中报时拜神的一种器具。因是秋天，故云「寒磬」。空林：因秋天树叶脱落，更觉林空。
惆怅：失意，用来表达人们心理的情绪。
南朝事：因吴公台关乎到南朝的宋和陈两代事，故称。南朝，宋、齐、梁、陈，据地皆在南方，故名。', '古台破败草木已经凋落，秋天景色引起我的乡思。
荒野的寺院来往行人少，隔水眺望云峰更显幽深。
夕阳依恋旧城迟迟下落，空林中回荡着阵阵磬声。
感伤南朝往事不胜惆怅，只有长江奔流从古到今。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f09321", "shortContent": "此诗作于刘长卿旅居扬州之时。安史之乱爆发后，刘长卿流寓江南，秋日登临吴公台，写下这首吊古之作。吴公台本为南朝宋时沈庆之攻竟陵王诞时所筑之弩台，后来陈朝名将吴明彻围攻北齐敬子猷，增筑以射城内，因以得名。诗题所言“吴公台上寺”，当为绕台所建的寺庙。\n\n首联写景物所触发的情感。诗人在一个秋日来到吴公台，秋风萧瑟，黄叶飘飞，不由得引起了思乡之情。“摇落”虽然接在“古台”之后，但并非形容“古台”，而是形容树...", "authors": ["李曙光"], "pressName": "崇文书局"}]', '《大历诗略》：空明萧瑟，长庆诸公无此墙也。
《诗式》：发句上句点「台」字，下句点「秋日」，「望」字起「登」字意。颔联上句入「寺」字，下句切「远眺」。颈联上句切题意，盖寺为吴公战场也；下句切台上寺，寺在高处，磬声散落，故空林俱满。此联「依」字、「满」字，为炼字法。落句就题意收，盖吴公为陈将，南朝战场今已为寺，故可「惆怅」，惟长江自流耳。此以吊古作收者，下句并切「台上」、「远眺」等字，此结句余意无穷法也。凄清。', 'center', 1417168562, '57b8ee9cdf0eea006334714a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10557, '送李中丞归汉阳别业', NULL, 80, 492, 1, 1, '刘长卿', NULL, 10113, '57b9a043165abd00661cbf89', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383369.htm', '', '流落征南将，曾驱十万师。
罢归无旧业，老去恋明时。
独立三边静，轻生一剑知。
茫茫江汉上，日暮欲何之。', '此诗以深挚的感情颂扬了李将军的英雄气概、忠勇精神和卓著功绩，对老将晚年罢归流落的遭遇表示了无限的同情。诗的前六句，都是刻画老将形象的，用语豪壮，老将舍身为国、英勇奋战的神威形象表现得非常突出有力。结尾一联，寓情于景，以景衬情，含蓄地表现老将日暮途穷的不幸遭遇。全诗情调悲怆，感人至深。', '李中丞：生平不详。中丞，官职名，御史中丞的简称，唐时为宰相以下的要职。
流落：漂泊失所。
征南将：指李中丞。
师：军队。
旧业：在家乡的产业。
明时：对当时朝代的美称。
三边：指汉代幽、幷、凉三州，其地皆在边疆。此处泛指边疆。
轻生：不畏死亡。
江汉：指汉阳，汉水注入长江之处。
日暮：天晚，语意双关，暗指朝廷不公。
何之：何往，何处去。', '这位漂泊流离的征南老将，当年曾经指挥过十万雄师。
后来他罢职回乡没有产业，到老年他还留恋贤明之时。
少壮时独立功勋三边平静，为国轻生只有随身佩剑知。
在茫茫的汉江上飘来荡去，日到黄昏你还想要去哪里？', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f09322", "shortContent": "这是一首送别诗，诗题中的“李中丞”不知何人。从诗中来看，他本是一位纵横沙场、叱咤风云的老将，但不知何故被罢职遣乡。诗人为其鸣不平，所以写了这首诗，但在语气上却并不激切，而是寓悲愤沉郁于温柔敦厚之中。\n\n首联“流落征南将，曾驱十万师”，由今溯昔，于今昔对比之中，体现李中丞之不幸遭遇。“流落”，叙写今日处境。“征南将”，点出昔日身份。下句“曾驱十万师”补足“征南将”之意。“十万”极言兵士之多，渲染中丞...", "authors": ["李曙光"], "pressName": "崇文书局"}]', '陆时雍《唐诗镜》：三、四老气深衷。
周珽《唐诗选脉会通评林》：章法明练，句律雄浑，中唐佳品。
乔亿《大历诗略》：清壮激昂，而意自浑浑。', 'center', 1417168670, '57b92229165abd0054c0e96b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10558, '饯别王十一南游', NULL, 118, 492, 1, 2, '刘长卿', NULL, 10113, '57b9a043165abd00661cbf89', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383371.htm', '', '望君烟水阔，挥手泪沾巾。
飞鸟没何处，青山空向人。
长江一帆远，落日五湖春。
谁见汀洲上，相思愁白蘋。', '此诗抒发自己对友人的真挚情意，描写了挥手远望直到陷入思念，愁肠百结，写得动人心弦。全诗没有“别离”二字，只写离别后的美景，然而浓浓的离情别绪已完全融入景中，曲折婉转，首尾呼应，手法新颖，别具匠心，离思深情，悠然不尽。诗人借助眼前景物，通过遥望和凝思，来表达离愁别绪。手法新颖，不落俗套。', '饯别：设酒食送行。
王十一：名不详，排行十一。
烟水：茫茫的水面。
飞鸟：比喻远行的人。
没何处：侧写作者仍在凝望。没，消失。
空向人：枉向人，意思是徒增相思。
落日：指王十一到南方后，当可看到夕照下的五湖春色。
五湖：这里指太湖。此句与下面“谁见”两句均出自梁朝柳恽《江南曲》：“汀洲采白蘋，落日江南春。洞庭有归客，潇湘逢故人。故人何不返，春花复应晚。不道新知乐，只言行路远。”
汀（tīng）洲：水边或水中平地。
白蘋（pín）：水中浮草，花白色，故名。', '望着你的小船驶向茫茫云水，频频挥手惜别泪水沾湿佩巾。
你像一只飞鸟不知归宿何处，留下这一片青山空对着行人。
江水浩浩一叶孤帆远远消失，落日下你将欣赏着五湖之美。
谁能见我伫立汀洲上怀念你，望着白蘋心中充满无限愁情。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a65e272d4b225432b4", "shortContent": "这首送别诗，着意写与友人离别时的心情。诗人借助眼前景物，通过遥望和凝思，来表达离愁别绪。手法新颖，不落俗套。\n诗题虽是“饯别”，但诗中看不到饯别的场面，甚至一句离别的话语也没有提及。诗一开始，他的朋友王十一（此人名字、爵里不详）已经登舟远去，小船行驶在浩渺的长江之中。诗人远望着烟水空茫的江面，频频挥手，表达自己依依之情。此时，江岸上只留下诗人自己。友人此刻又如何，读者已无从知道，但从诗人送别的举动...", "authors": ["李", "琳"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f09323", "shortContent": "没有告别的场面，没有离别的话语，仿佛电影画面，一开始就推远了镜头，烟水辽阔，片帆远去，微风轻拂，只见水波荡漾，恍如人的心潮起伏。诗人在岸边驻足，频频挥动手臂，传递自己的依依深情，尽管友人也许早已看不见这些，但他坚信，南游的朋友一定能够感受到他的一份浓浓情意。\n\n透过朦胧的泪眼，诗人远望孤帆，又见飞鸟从头顶掠过，追随友人的小舟而去。不，也许这里的小鸟只是友人南游的隐喻，诗人的无限牵挂与担忧正渗透在这...", "authors": ["刘琴"], "pressName": "崇文书局"}]', '', 'center', 1417168740, '57b919195bbb50005b78f196', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10559, '新年作', NULL, 161, 492, 1, 3, '刘长卿', NULL, 10113, '57b9a043165abd00661cbf89', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383374.htm', '', '乡心新岁切，天畔独潸然。
老至居人下，春归在客先。
岭猿同旦暮，江柳共风烟。
已似长沙傅，从今又几年。', '此诗是唐代诗人刘长卿被贬时创作的一首诗，抒写作者的无限离愁及失意悲愤之情。首联写情，新岁怀乡；颔联写景寓情，感叹春归我先；颈联即景生情，身处孤境悲愁；末联借贾谊自况，抒发贬谪悲愤。全诗抒情多于写景，意境深远，用词精炼，情景合一，感人至深。', '天畔：天边，指潘州南巴，即今广东茂名。潸（shān）然：流泪的样子。
居人下：指官人，处于人家下面。客：诗人自指。
“春归”句：春已归而自己尚未回去。
岭：指五岭。作者时贬潘州南巴，过此岭。
长沙傅：指贾谊。曾受谗被贬为长沙王太傅，这里借以自喻。', '新年来临思乡之心更切，独立天边不禁热泪横流。
到了老年被贬居于人下，春归匆匆走在我的前头。
山中猿猴和我同度昏晓，江边杨柳与我共分忧愁。
我已和长太傅一样遭遇，这样日子须到何时才休？', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f09325", "shortContent": "唐肃宗至德三年（758）春天，作者因事由苏州长洲尉被贬潘州南巴（今属广东茂名）尉，此诗当为迁至潘州次年，即乾元二年（759）后所作。题为“新年作”，新年本为万象更新、举家团圆之际，是中华民族最盛大的传统节日。但作者以其谪居岭南之身，在新年之时反倒涌起无限凄楚，在诗中抒发了浓郁的思乡之愁和贬谪之怨，哀婉凄清，真挚感人。\n\n首联仅十字，却点出时间（新岁）、地点（天畔）、处境（独身一人）、心情（思乡心切...", "authors": ["李曙光"], "pressName": "崇文书局"}]', '《碛砂唐诗》：涪曰：苏、李居前，沈、宋比肩，即如此篇，工力悉敌，自是不可及。
《瀛奎律髓》：三、四费无限思索乃得之，否则有感而自得。
《瀛奎律髓汇评》：纪昀：三四乃初唐之晚唐，似从薛道衡《人日思归》诗化出。三、四二句，渐以心思相胜，非复从前堆垛之习矣。妙于巧密而浑成，故为大雅。许印芳：三、四细炼，初唐无此巧密。
《唐诗镜》：三、四隽甚，语何其炼！
《诗镜总论》：刘长卿体物情深，工于铸意，其胜处有迥出盛唐者。“黄叶减余年”，的是庾信、王褒语气。“老至居人下，春归在客先”，“春归”句何减薛道衡《人日思归》语！
《唐律消夏录》：句句从“切”字说出，便觉沉著，五、六以“同”、“共”二字形容出“独”字来，甚妙。
《唐诗别裁》：巧句。别于盛唐，正在此（“春归”句下）。
《诗式》：发句上句出“新岁”二字点题面，冠以“乡心”二字，题意亦已点明。下句承上句写足，题面、题意俱到。颔联上句承发句下句，以写其不得志。下句承发句上句，以写其不得归。颈联写景兼写情，所谓情景兼到者。落句上句点在南巴，下句归到新岁，词尽而意不尽，言从今兹新岁起，不知还有若干年在此也，与上“乡心”二字亦有回应之意。通首尤以颔联下句为得神。（品）凄丽。', 'center', 1417169126, '57b9a04a8ac2470063fdd30b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10560, '谷口书斋寄杨补阙', NULL, 88, 435, 1, 1, '钱起', NULL, 10114, '57bbbb372e958a00694032d7', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383376.htm', '', '泉壑带茅茨，云霞生薜帷。
竹怜新雨后，山爱夕阳时。
闲鹭栖常早，秋花落更迟。
家僮扫萝径，昨与故人期。', '这是邀约的一首诗，约杨补阙前来书斋叙谈。诗中着力描绘作者自己书斋附近的自然环境，分层次地写出了书斋虽是茅屋草舍，但依壑傍泉，四周景色幽雅秀丽，意在表达对杨补阙的盛情，期待他能如期来访。全诗内涵丰富，耐人寻味。', '谷口：古地名，指陕西蓝田辋川谷口，钱起在蓝田的别业所在。
补阙：官名，职责是向皇帝进行规谏，有左右之分。
泉壑：这里指山水。
茅茨（cí）：原指用茅草盖的屋顶，此指茅屋。
怜：可爱。
新雨：刚下过的雨。
山：即谷口。
迟：晚。
家僮：：即家童，旧时对私家奴仆的统称。
昨：先前。', '山泉沟壑绕着我的茅舍，云霞掩映帷幕般的薜荔。
新雨过后青竹更是苍翠，夕阳晖中山色增添秀美。
悠闲的白鹭早早就栖息，秋日的花朵迟迟不凋谢。
家僮清扫着松萝的小径，早与故人相约盼他到来。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f09328", "shortContent": "此诗是一首邀约朋友的诗，诗人着力刻画山中精舍的雅致与清幽，表达自己盛情邀约，期待友人如约而至的心情。补阙，官名，有左右之分，职责是向皇帝进行劝谏。谷口在陕西蓝田，作者时居于此。\n\n首联写书斋的雅致。有山有泉，如一幅水墨山水，在山泉环抱之处，有几间茅屋，这就是作者在谷口的书斋所在。墙上爬满了薜荔，浮云彩霞从上升腾而起，恰似五彩帷幕。首联雅淡精致，写山中精舍极有风致。\n\n颔联笔致精巧。对句皆为倒装，正...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '', 'center', 1417169251, '57b8fbd3c4c97100558efdc5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10562, '赋得暮雨送李胄', NULL, 91, 570, 2, 2, '韦应物', NULL, 10115, '57b9b835128fe1005f860400', '唐', 'shi', '诗', 'http://baike.baidu.com/view/651824.htm', '', '楚江微雨里，建业暮钟时。
漠漠帆来重，冥冥鸟去迟。
海门深不见，浦树远含滋。
相送情无限，沾襟比散丝。', '这是一首咏暮雨的送别诗，虽是送别，却重在写景。首联写送别之地，扣紧“雨”、“暮”主题。二、三两联渲染朦胧暗淡的景色；暮雨中航行江上，鸟飞空中，海门不见，浦树含滋，境地极为开阔，极为邈远。末联写离愁无限，潸然泪下。全诗一脉贯通，前后呼应，浑然一体。', '赋得：分题赋诗，分到的什么题目，称为“赋得”。这里分得的题目是“暮雨”，故称“赋得暮雨”。李胄，一作李曹，又作李渭，其人，其事，以及他与韦应物的关系，似已无考。从此诗看，想必两人的交谊颇深。
楚江：指长江，因长江自三峡以下至濡须口，皆为古代楚国境。
建业：今江苏南京。战国时亦楚地，与楚江为互文。暮钟时：敲暮钟的时候。
漠漠：水气迷茫的样子。
冥冥：天色昏暗的样子。
海门：长江入海处，在今江苏省海门市。
浦：近岸的水面。含滋：湿润，带着水汽。滋，润泽。
沾襟：打湿衣襟。此处为双关语，兼指雨、泪。散丝：指细雨，这里喻流泪。晋张协《杂诗》：“密雨如散丝。”', '楚江笼罩在细细微雨里，建业城正敲响暮钟之时。
雨丝繁密船帆显得沉重，天色错暗鸟儿飞得迟缓。
长江流入海门深远不见，江边树木饱含雨滴润滋。
送别老朋友我情深无限，沾襟泪水像江面的雨丝。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b903572034f659e4f5", "shortContent": "这是一首送别诗。李曹，一作李胄，又作李渭。其人，其事，以及他与韦应物的关系，已无考；从此诗看，想必两人的交谊颇深。诗中的“楚江”、“建业”，是送别之地。长江自三峡以下至濡须口（在今安徽省境内），古属楚地，所以叫楚江。建业，原名秣陵，三国时吴主孙权迁都于此，改称建业，旧城在今江苏南京市南。虽是送别，却重在写景，全诗紧扣“暮雨”和“送”字着墨。\n首联“楚江微雨里，建业暮钟时”，起句点“雨”，次句点“暮...", "authors": ["周锡炎"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f0932a", "shortContent": "此诗是唐代诗人韦应物创作的一首五言律诗，也是咏暮雨的送别诗，重在写景。诗中的“楚江”、“建业”，是送别之地。诗人伫立在暮雨中为友人送行，暮雨纷纷好像也饱含着情谊，友人要到遥远的地方，不免惜别难舍。泪水与雨丝同时落下，情与景也巧妙融合。全篇以疏淡有致的笔墨，绘出一幅动静相生、富有情味的江上烟雨图，表现诗人对自然景物细致的观察和精微的刻画。\n\n首联写送别之地，扣紧“雨”、“暮”主题。起句点“雨”，次句...", "authors": ["阮森丽"], "pressName": "崇文书局"}]', '《艇斋诗话》：唐人诗用“迟”字皆得意。……韦苏州《细雨》诗：“漠漠帆来重，冥冥鸟去迟。”亦佳句。
《韦孟全集》：起甚佳，余复称是。
《瀛奎律髓》：三四绝妙，天下诵之。
《四溟诗话》：梁简文曰：“湿花枝觉重，宿鸟羽飞迟。”苏州曰：“漠漠帆来重，冥冥鸟去迟。”……虽有所祖，然青愈于蓝矣。
《唐诗笺要》：通首无一语松放“暮雨”，此又以细切见精神者，韦苏州之不可方物如此。
《唐诗观澜集》：冲淡夷犹，读之令人神往。
《网师园唐诗笺》：双起点题（首二句下）。
《瀛奎律髓汇评》：查慎行：三四与老杜“湛湛长江去，冥冥细雨来”各尽其妙。纪昀：净细。', 'center', 1417179227, '57b90de50a2b58005c92a8ce', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10563, '酬程延秋夜即事见赠', NULL, 39, 165, 2, 1, '韩翃', NULL, 10131, '57bdc0b17db2a20068dc6903', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383413.htm', '', '长簟迎风早，空城澹月华。
星河秋一雁，砧杵夜千家。
节候看应晚，心期卧已赊。
向来吟秀句，不觉已鸣鸦。', '此诗描写诗人卧病深秋的寂寞心情，并对友人赠诗表示谢意。前半首写秋夜，声色俱全。颔联属对，尤其自然秀逸。颈联写更深夜阑，心期而不得入眠。末联写吟咏赠诗，不觉已鸦噪天曙，结构颇为严密。
全诗结构严谨，清幽淡雅。诗人为了酬诗，而通宵未眠，足见彼此心期之切。又赞扬友人寄赠的诗章，感情真挚，表现出诗人与友人的真挚友谊。', '程延：人名，事迹不祥，从诗题看，当是诗人的诗友。
簟：竹名。《说郛》载：“簟竹，叶疏而大，一节相去六七尺。”
空：形容秋天清虚景象。
月华：月光。
砧杵：捣衣用具，古代捣衣多在秋夜。砧：捣衣石。杵：捣衣棒。
节候：节令气候。
心期：心愿。
赊：落空。
向来：刚才。', '修长的竹枝早早迎接着秋风，淡淡的月华洒满了空城。
一只鸿雁向银河飞去，寂静的夜里，传来千家万户捣衣的砧声。
季节飞快地推移，转眼已秋冬，闲散里，我空怀着未曾了却的心意。
我反复吟诵你秀美的诗句，不觉天色将晓，已听见早鸦乱啼。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f0932b", "shortContent": "此诗是诗人韩翃的五言律诗，也是一首酬赠诗。友人程近写了一首《秋夜即事》赠给诗人，诗人写此诗作酬答，描写了秋夜清远疏淡的景色，赞扬友人寄赠的诗章，表现出诗人与友人的真挚友谊，同时写出时序更迭引起诗人心事未了的惆怅。\n\n全诗结构严谨，意境开阔，清幽淡雅。首联写秋夜，声色俱全。“长簟迎风早”写秋风过早地来到庭院，长簟被秋风吹得窸窣咋响。一个“早”字写出卧病之人对秋风的突出感受。“迎风”二字写出一片萧瑟的...", "authors": ["阮森丽"], "pressName": "崇文书局"}]', '《瀛奎律髓》：“砧杵夜千家”，必旅中。
《瀛奎律髓汇评》：纪昀：何必旅中方有砧声？此说固甚。又：三四清远纤秀，通体亦皆清妥。结和字密。
《初白庵诗评》：“秋”、“夜”二字极寻常，一经炉锤，便成诗眼。', 'center', 1417179404, '57bf081a7db2a20068e7d481', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10564, '阙题', NULL, 305, 15, 3, 1, '刘眘虚', NULL, 10369, '57bb0ea20a2b58006cbab9c9', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383414.htm', '', '道由白云尽，春与青溪长。
时有落花至，远随流水香。
闲门向山路，深柳读书堂。
幽映每白日，清辉照衣裳。', '阙题，即缺题。唐殷璠《河岳英灵集》在辑录此诗时就没有题目，于是给它安上「阙题」二字。此诗所描绘的景物及其所表达的意境来看，不是写自己山居的闲适，而是写友人山中隐居的幽趣。全诗清新自然，婉转流畅，按空间顺序写来，使读者仿佛随着诗人走访了这位隐者的别墅。由远及近，从外向里而行，余韵萦绕，有一种异乎寻常的艺术魅力。
', '阙题：即缺题。「阙」通「缺」。因此诗原题在流传过程中遗失，后人在编诗时以「阙题」为名。
道由白云尽：指山路在白云尽处，也即在尘境之外。
春：春意，即诗中所说的花柳。
随：一作“闻”。
闲门：指门前清净，环境清幽，俗客不至的门。
深柳：即茂密的柳树。
幽映：指「深柳」在阳光映照下的浓荫。', '山路被白云隔断在尘境之外，春光宛若清清溪流源远流长。
不时有落花随溪水飘流而至，远远地就可闻到水中的芳香。
闲静的荆门面对蜿蜒的山路，柳荫深处蕴藏着读书的斋堂。
每当太阳光穿过柳荫的幽境，清幽的光辉便洒满我的衣裳。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a2c6e67846a920ea5a", "shortContent": "这首诗原来应是有个题目的，后来不知怎样失落了。唐殷璠《河岳英灵集》在辑录这首诗的时候就没有题目，后人只好给它安上“阙题”二字。\n这首诗句句写景，画意诗情，佳句盈篇，可推为刘眘虚的代表作。诗描写深山中一座别墅及其幽美环境。一开头就写进入深山的情景。“道由白云尽”，是说通向别墅的路是从白云尽处开始的，可见这里地势相当高峻。这样开头，便已藏过前面爬山一大段文字，省掉了许多拖沓。同时，它暗示诗人已是走在通...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f0932c", "shortContent": "这首诗的原题可能失落，唐代殷璠《河岳英灵集》在辑录这首诗的时候没有题目，后人只好给它安上“阙题”二字。\n\n刘眘虚为人淡泊，脱略势利，壮年辞官归田，寄情山水。这首诗句句写景，诗情画意满卷，好词佳句盈篇，是刘眘虚的代表作。\n\n诗描写的是隐藏在深山中的一座别墅。开篇写进入深山的情景，“道由白云尽”，说明通向别墅的路是从白云尽头开始的，山路被白云隔断在尘境之外，可见这里已是高耸入云。以此起笔，暗示前面爬山...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127053e6f69b71e93f6277", "shortContent": "这首诗的原题可能失落，唐代殷璠《河岳英灵集》在辑录这首诗的时候没有题目，后人只好给它安上“阙题”二字。\n\n\n\n刘眘虚为人淡泊，脱略势利，在壮年辞官归田，寄意山水。这首诗句句写景，诗情画意满卷，好词佳句盈篇，是刘眘虚的代表作。\n\n诗描写的是隐藏在深山中的一座别墅。开篇写进入深山的情景，“道由白云尽”，说明通向别墅的路是从白云尽头开始的，山路被白云隔断在尘境之外，可见这里地势高峻。以此起笔，暗示前面爬...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "645fc22c5e6bb82b8caff682", "bookTitle": "历代咏春诗鉴赏：春江花月夜", "articleId": "6472f65482772d45942b5621", "shortContent": "这首诗原来应是有个题目的，后来不知怎样失落了。唐殷璠《河岳英灵集》在辑录这首诗的时候就没有题目，后人只好给它安上“阙题”二字。但从内容来看，它实在是一首歌咏春日的佳作。\n\n这首诗句句写景，画意诗情，佳句盈篇，可推为刘眘虚的代表作。诗描写深山中一座别墅及其幽美环境。一开头就写进入深山的情景。“道由白云尽”，是说通向别墅的路是从白云尽处开始的，可见这里地势相当高峻。这样开头，便已藏过前面爬山一大段文字...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}]', '《唐诗归》：钟云：骨似王、孟，而气运隆厚或过之。
《汇编唐诗十集》：严整幽细，五言拗体中之佳者。
《唐律消夏录》：水远、花香、山探、林密，书堂正当其处，何乐如云！看他「长」字、「时」字、「至」字、「远」字、「香」字，回环勾锁，一字不虚。「道由白云尽」是望见，「闲门向山路」是到来，非重复也。
《唐诗成法》：「幽映」总上六句，「白日」应「春」字，「清辉」应「幽映」字。
《唐贤三昧集笺注》：此中有元气，后人拟之，便浅薄无味。
《近体秋阳》：清宕傲逸，纯乎古作，不徒所谓拗律已也。
《唐诗别裁》：每事过求，则当前妙境，忽而不领。解此意，方见其自然之趣。
《网师园唐诗笺》：纯乎天籁（「时有」二句下）。
《唐诗三百首》：此以「深柳」句为主，言由白云尽处而来，见溪水长流，落花浮至，而门向山开，堂极深窈，虽白口唯清辉幽映耳（「闲门」二句下）。
《越缦堂诗话》：「时有落花至，远随流水香」，十字亦有禅谛。
《唐宋诗举要》：王孟胜景（「时有」二句下）。
《诗境浅说》：此寺起结皆不用谐律，弥见古雅。初学效之，恐有举鼎绝膑之患，仍以谐音为妥贴。', 'center', 1417179595, '57b8c5cb7db2a2005425b4b8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10565, '江乡故人偶集客舍', NULL, 100, 275, 2, 1, '戴叔伦', NULL, 10133, '57b9191ac4c97100558ff29d', '唐', 'shi', '诗', 'http://baike.baidu.com/view/246762.htm', '', '天秋月又满，城阙夜千重。
还作江南会，翻疑梦里逢。
风枝惊暗鹊，露草覆寒蛩。
羁旅长堪醉，相留畏晓钟。', '此诗描写在羁旅途中和同乡偶然聚会的情景。前二联写秋夜客途与老朋友相逢，充分表现了惊喜交集的感情。第三联写秋夜景色，表现客居他乡的凄凉。尾联「羁旅长堪醉，相留畏晓鐘」以畏怕分离时间到来作结，深刻表现对同乡聚会的珍惜和友情的深厚。这首诗的中心是写「故人偶聚」，但由于聚会的地点在客舍，大家都在异乡，因此，除了有重逢的喜悦外，更多的是对羁旅的嗟叹。', '偶集：偶然与同乡聚会。
天秋：谓天行秋肃之气；时令已值清秋。唐·李白《秋思》诗：「天秋木叶下，月冷莎鸡悲。」
城阙（què）：宫城前两边的楼观，泛指城池。《诗经·郑风·子衿》：「佻兮达兮，在城阙兮。」孔颖达疏：「谓城上之别有高阙，非宫阙也。」
千重：千层，层层迭迭，形容夜色浓重。《后汉书·马融传》：「群师叠伍，伯校千重。」
会：聚会。
翻疑：反而怀疑。
翻：义同「反」。
风枝：风吹拂下的树枝。宋·曾慥《高斋漫录》：「南唐有画，黄头子数十枚集于风枝上。」
惊暗鹊：一作「鸣散鹊」。
露草：沾露的草。唐·李华《木兰赋》：「露草白兮山凄凄，鹤既唳兮猿复啼。」
寒蛩（qióng）：深秋的蟋蟀。唐·韦应物《拟古诗》之六：「寒蛩悲洞房，好鸟无遗音。」
覆寒蛩：指秋虫在草中啼叫如同哭泣。
羁（jī）旅：指客居异乡的人。《周礼·地官·遗人》：「野鄙之委积，以待羁旅。」郑玄注：「羁旅，过行寄止者。」
长：一作「常」。
相留：挽留。
晓鐘：报晓的鐘声。唐·沈佺期《和中书侍郎杨再思春夜宿直》：「千庐宵驾合，五夜晓鐘稀。」', '秋月又一次盈满，城中夜色深浓。你我在江南相会，我怀疑是梦中相逢。晚风吹动树枝，惊动了栖息的鸟鹊。秋草披满霜露，伴随着悲吟的寒虫。你我客居他乡，应该畅饮以排遣愁闷，留你长饮叙旧，只担心天晓鸣鐘。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f0932d", "shortContent": "此诗是唐朝诗人戴叔伦创作的一首五言古诗，写于作者江南入幕期间。一个秋天的夜晚，诗人于江南旅店之中，偶然遇见离别多年的同乡旧识，不觉满怀惊喜。但是相逢苦短，天亮又将分别，不知下一次相会将在何时何地，引起诗人的满腹惆怅与对羁旅的嗟叹，故题诗与同乡告别。\n\n首联和颔联写秋夜客途与老朋友相逢，充分表现了惊喜交集的感情。首联写秋夜里一轮圆月高高地挂在天空，城池沉浸在夜色重重的包围之中。“满”字，写出了秋月之...", "authors": ["阮森丽"], "pressName": "崇文书局"}]', '淸·贺裳《载酒园诗话》：（谢榛《诗家直说》）又曰：「诗有简而妙者，如阮籍『一身不自保，何况恋妻子』，不如裴说『避乱一身多』戴叔伦『还作江南会，翻疑梦里逢』，不如司空曙『乍见翻疑梦』。……」信如所云，诗只作一句耶？文人得心应手，偶尔写怀，简者非缩两句为一句，烦者非演一句为两句也。承接处各有气脉，一篇自有大旨，那得如此苛断！
淸·贺裳《载酒园诗话又编》：（叔伦）近体诗亦多可观。如「风枝惊暗鹊，露草覆寒蛩」、「对酒惜馀景，问程愁乱山」、「竹暗闲房雨，茶香别院风」，语皆清警。', 'center', 1417179730, '57b96fb68ac2470062e382d1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (50917, '苏幕遮', NULL, 0, 26, 0, 1, '高道宽', NULL, 11195, '5858e6398d6d810065c3153c', '元', 'ci', '词', NULL, NULL, '这无为，先天造。有有无无，端的无穷妙。最上不空谁曾到。强曰为名，假作字之号。
道真常，大秘奥。觉象圆明，得一元顿教。代代相承心印宝。压尽傍门，独显真大道。', NULL, NULL, NULL, NULL, NULL, 'indent', 1529685199, '585cefbb61ff4b00580c74d2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (50918, '苏幕遮', NULL, 0, 26, 0, 1, '高道宽', NULL, 11195, '5858e6398d6d810065c3153c', '元', 'ci', '词', NULL, NULL, '闭玄关，通三昧。采药仙翁，收得真消息。柳岸芦花添青翠。满地白云，只许人不会。
但拈来，偏如意。本分家风，分付真心地。一颗神珠明丽丽。照破尘沙，相遇人授记。', NULL, NULL, NULL, NULL, NULL, 'indent', 1529685200, '585cefbbb123db0065a64066', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10566, '送李端', NULL, 93, 341, 2, 0, '卢纶', NULL, 10014, '57b9c2f6c4c97100614832f4', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383416.htm', '', '故关衰草遍，离别自堪悲。
路出寒云外，人归暮雪时。
少孤为客早，多难识君迟。
掩泪空相向，风尘何处期？', '此诗抒写乱离中的离别之情。前两联写诗人在故乡衰草遍地的严冬送别友人，后两联记叙与友人离别之后，诗人在孤独寂寞中感叹自己少年孤苦飘零。全诗情文并茂，哀婉感人。', '《全唐诗》此诗题下有注：一作严维诗，题作“送李端”。李端：作者友人，与作者同属“大历十才子”。
故关：故乡。衰草：冬草枯黄，故曰衰草。南朝梁沈约《岁暮悯衰草》诗：“悯衰草，衰草无容色。憔悴荒径中，寒荄不可识。”
自：一作“正”。
“路出”句：意为李端欲去的路伸向云天外，写其道路遥远漫长。
少孤：少年丧父、丧母或父母双亡。早：一作“惯”。
多难：多患难。《诗经·周颂·小毖》：“未堪家多难。”郑玄笺：“我又会于辛苦，遇三监及淮夷之难也。”
掩泪：一作“掩泣”。
“风尘”句：意为在动乱年代，不知后会何期。风尘：指社会动乱。《后汉书·班固传下》：“设后北虏稍彊，能为风尘，方复求为交通，将何所及？”', '故乡遍地都是衰败的枯草，我们的离别本就令人伤悲。
远去的路延伸到云天之外，我归来在傍晚雪花纷飞时。
少年孤苦漂泊他乡恨过早，多难之时与你结识又太迟。
向着你去的方向空自流泪，世事纷繁哪还有见面之期？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ba34a8757d5a0e1d2f", "shortContent": "这是一首感人至深的诗章，以一个“悲”字贯串全篇。\n首联写送别的环境气氛，从衰草落笔，时令当在严冬。郊外枯萎的野草，正迎着寒风抖动，四野苍茫，一片凄凉的景象。在这样的环境中送别故人，自然大大加重了离愁别绪。“离别自堪悲”这一句写来平直、刻露，但由于是紧承上句脱口而出的，应接自然，故并不给人以平淡之感，相反倒是为本诗定下了深沉感伤的基调，起了提挈全篇的作用。\n诗的第二联写送别的情景，仍紧扣“悲”字。“...", "authors": ["刘永年"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f0932e", "shortContent": "元代傅若金《诗法正论》云：“作诗成法有起、承、转、合四字。”该诗就是一首标准的以起、承、转、合构筑全篇的诗歌。首联是起，点出送别时的环境氛围，严冬故关，衰草遍野，四野苍茫。“黯然销魂者，唯别而已矣。”第二句的“悲”字奠定了全诗凄凉感伤的基调。颔联紧承首联，“路出寒云外”是写故人渐行渐远。寒云低垂，道路好像伸出寒云之外一般。“人归暮雪时”写作者目送友人良久，一直到了傍晚，从中可见作者与李端的深厚情谊...", "authors": ["陈鹏"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706a73206168b2e02202", "shortContent": "元代傅若金《诗法正论》云：“作诗成法有起、承、转、合四字。”该诗就是一首标准的以起、承、转、合构筑全篇的诗歌。首联是起，点出送别时的环境氛围，严冬故关，衰草遍野，四野苍茫。“黯然销魂者，唯别而已矣。”第二句的“悲”字奠定了全诗凄凉感伤的基调。颔联紧承首联，“路出寒云外”是写故人渐行渐远。寒云低垂，道路好像伸出寒云之外一般。“人归暮雪时”写作者目送友人良久，一直到了傍晚，从中可见作者与李端的深厚情谊...", "authors": ["陈鹏"], "pressName": "崇文书局"}]', '清代胡本渊《唐诗近体》：“少孤”句悲李，“多难”句自悲。“掩泪”二句，送。
清代潘德舆《养一斋诗话》：“少孤句，皆字字从肺肝中流露，写情到此，乃为入骨。虽是律体，实《三百篇》、汉魏之苗裔也。
近代俞陛云《诗境浅说》：诗为乱离送友，满纸皆激楚之音。前四句言岁寒送别，念征途之递迢，值暮雪之纷飞，不过以平实之笔写之。后半篇沉郁激昂，为作者之特色。
近代高步瀛《唐宋诗举要》：沉至（“少孤”二句下）。', 'center', 1417179855, '57b965c17db2a200542a2ea7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10567, '云阳馆与韩绅宿别', NULL, 110, 165, 2, 1, '司空曙', NULL, 10021, '57b967b98ac2470062e32d9a', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383418.htm', '', '故人江海别，几度隔山川。
乍见翻疑梦，相悲各问年。
孤灯寒照雨，湿竹暗浮烟。
更有明朝恨，离杯惜共传。', '此诗抒写了友人离别多年而乍相会又分别时的心理历程。作者与老友久别重逢，竟以为在梦中，而明朝还要分别，两人在孤灯下饮着离别的酒，不觉恋恋不舍，表现出两人的情谊及对友谊的珍惜。全诗句式工整，淡淡道来，却是情深意长。', '云阳：县名，县治在今陕西泾阳县西北。
韩绅：《全唐诗》注：「一作韩升卿。」韩昌黎的四叔名绅卿，与司空曙同时，曾在泾阳任县令，可能即为此人。宿别：同宿后又分别。
江海：指上次的分别地，也可理解为泛指江海天涯，相隔遥远。
几度：几次，此处犹言几年。
「乍见翻疑梦」句：多年不见，乍一相逢，反而怀疑这是梦境。乍：骤，突然；翻，反而。
年：年时光景。
湿竹：一作「深竹」。
离杯：饯别之酒。杯，酒杯，此代指酒。
惜：珍惜。
共传：互相举杯。', '自从和老友在江海分别，隔山隔水已度过多少年。
突然相见反而怀疑是梦，悲伤叹息互相询问近况。
孤灯暗淡照着窗外冷雨，幽深的竹林漂浮着云烟。
明朝更有一种离愁别恨，难得今夜聚会传杯痛饮。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b62e6a6b501f95c24e", "shortContent": "云阳，县名，县治在今陕西泾阳县西北。韩绅，《全唐诗》注：“一作韩升卿。”韩愈四叔名绅卿，与司空曙同时，曾在泾阳任县令，可能即为其人。\n这是首惜别诗，但一开始却从上次的别离说起，接写此次相会，然后才写到叙谈和惜别，描写曲折，富有情致。\n上次别后，已历数年，山川阻隔，相会不易，其间的相思，自在言外。正因为相会不易，相思心切，所以才生发出此次相见时的“疑梦”和惜别的感伤心情来。首联和颔联，恰成因果关系。...", "authors": ["孙其芳"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac26845f3e157ce328", "shortContent": "云阳，县名，县治在今陕西泾阳县西北。韩绅，《全唐诗》注：“一作韩升卿。”韩愈四叔名绅卿，与司空曙同时，曾在泾阳任县令，可能即为其人。\n\n这是首惜别诗，但一开始却从上次的别离说起，接写此次相会，然后才写到叙谈和惜别，描写曲折，富有情致。\n\n上次别后，已历数年，山川阻隔，相会不易，其间的相思，自在言外。正因为相会不易，相思心切，所以才生发出此次相见时的“疑梦”和惜别时的感伤心情来。首联和颔联，恰成因果...", "authors": ["孙其芳"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f34c26cbf3417f09330", "shortContent": "云阳，唐县名，在今陕西省三原县境内。馆，即驿馆，旅客中途休息的地方。宿别，同住一夜后分手。这首诗写诗人与一位多年不见的老友在旅途邂逅，又匆匆分手的人生片段，感情真挚动人。\n\n首联写阔别多年的故人久别重逢。首先点明两人的关系，即是故人。次写别离时间之久，距离之遥远。“江海别”，“隔山川”，是极写相隔之远，说明别离之难会。“几度”，是写故人久未相逢，聚少离多，说明相聚之弥足珍贵。\n\n颔联写重逢有如梦境...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127069e6f69b71e93f62a5", "shortContent": "云阳，唐县名，在今陕西省三原县境内。馆，即驿馆，旅客中途休息的地方。宿别，同住一夜后分手。这首诗写诗人与一位多年不见的老友在旅途邂逅，又匆匆分手的人生片段，感情真挚动人。\n\n一、二句写阔别多年的故人久别重逢。首先点明两人的关系，即是故人。次写别离时间之久，距离之遥远。江海别，隔山川，是极写相隔之远，说明别离之难会。几度，是写故人久未相逢，聚少离多，说明相聚之弥足珍贵。\n\n三、四句写重逢有如梦境，感...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270ef73206168b2e02288", "shortContent": "云阳，唐县名，县治在今陕西省泾阳县西北。馆，即驿馆，旅客中途休息的地方。宿别，同住一夜后分手。这首诗写诗人与一位多年不见的老友在旅途邂逅，又匆匆分手的人生片段，感情真挚动人。\n\n一、二句写阔别多年的故人久别重逢。首先点明两人的关系，即是故人。次写别离时间之久，距离之遥远。江海别，隔山川，是极写相隔之远，说明别离之难会。几度，是写故人久未相逢，聚少离多，说明相聚之弥足珍贵。\n二、\n三、四句写重逢有如...", "authors": ["张春晓"], "pressName": "崇文书局"}]', '《对床夜语》：「故人江海别，几度隔山川……」「暮蝉不可听，落叶岂堪闻……」，前一首司空曙，后一首郎士元，皆前虚后实之格，今之言唐诗者多尚此。
《瀛奎律髓》：三、四一联，乃久别忽逢之绝唱也。
《四溟诗话》：诗有简而妙者……戴叔伦「还作江南会，翻疑梦里逢」，不如司空曙「乍见翻疑梦」。
《诗镜总论》：司空曙「相悲各问年」，更自应手犀快。风尘阅历，有此苦语。
《全唐风雅》：黄云：叙别后再会之情，且悲且喜，宛然在目。
《唐诗解》：此诗本中唐绝唱，然江海、山川未免重叠。
《唐诗成法》：情景兼写，不失古法。
《唐诗别裁》：三、四写别久忽遇之情，五、六夜中共宿之景，通体一气，无饾饤习，尔时已为高格矣。
《大历诗略》：真情实语，故自动人。
《网师园唐诗笺》：真景真情（「乍见」一联下）。
《瀛奎律髓汇评》：纪昀：四句更胜。
《唐宋诗举要》：吴北江曰：三、四千古名句，能传久别初见之神。
《诗式》：发句先叙别况，曰「几度」，见相见之难矣。颔联叙相见：曰「乍见」，言别久忽见也；曰「翻疑梦」，言未信为真，反疑是梦也；曰「相悲」，言相叙别情，不觉悲感也；曰「各问年」，言别久人亦老大，不能记其年岁，故各须相问也。颈联写云阳馆之景况。夜本凄清，况是孤灯，又相照附中乎？故曰「寒」。夜本迷茫，况是深竹，何能见烟浮乎？故曰「暗」。落句想到又别日，更有系缴上意，言此情此景，相对本是寡欢，况来朝又欲别乎？故更添恨事，今夜传杯相劝，即是离杯，只共惜离情而已。落到题后，尤妙在托空也。（品）悲慨。', 'center', 1417179979, '57b69e975bbb50005b690ed1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10568, '贼平后送人北归', NULL, 106, 165, 2, 1, '司空曙', NULL, 10021, '57b967b98ac2470062e32d9a', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383420.htm', '', '世乱同南去，时清独北还。
他乡生白发，旧国见青山。
晓月过残垒，繁星宿故关。
寒禽与衰草，处处伴愁颜。', '此诗前半部分诗人先回忆安史之乱爆发时与友人一起逃往南方；再写战乱平定后友人一人北归，诗人送行；后设想在这长长的岁月里，大家都在辗转他乡的过程中头生白发，战后故乡当残破不堪，也只有青山依旧了。诗的后半部分想像友人一路上早行晚停，回归故里，见到的只能是寒禽衰草。诗人写出了惜别友人之意，并曲折地表达了故国残破的悲痛之情。', '贼平：指唐代宗广德元年（763年）正月，叛军首领史朝义率残部逃到范阳，走投无路，自缢身亡，“安史之乱”最终被朝廷平定。北归：指由南方回到故乡，
时清：指时局已安定。
“旧国”句：意谓你到故乡，所见者也惟有青山如故。旧国：指故乡。
残垒：即残破的壁垒，泛指战争遗留下来的痕迹。', '战乱时我和你一同逃到南方，时局安定你却独自北归家园。
流落他乡头上已经生出白发，战后的家乡也只能见到青山。
晓行要经过许多残破的营垒，夜里只能披星露宿荒凉故关。
旷野里的飞禽与枯黄的野草，将处处伴随着你的悲苦愁颜。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f0933a", "shortContent": "从诗题推测，此诗当作于唐代宗广德元年（763）安史之乱刚结束不久。其时司空曙身处南方，战乱甫平，诗人送同来避难的友人北归，伤感之下，写下了这首送别诗。\n\n首联交代送友人北归的来龙去脉。当年战乱之时，我们一起逃到南方避难，如今时局定定，你却独自北归家园，好友相别，怎不令人悲伤？司空曙是广平人，据考证在今河北或北京境内，是“安史之乱”的重灾区。友人北归而诗人滞留南方，是因为不忍目睹家乡战乱后的凋零残状...", "authors": ["乐云"], "pressName": "崇文书局"}]', '《唐诗分类绳尺》：中唐雅调。颔联甚不费力，甚不浅促。观其结句，犹不免有悲伤之意，其与《诗经》“鸿雁于飞，哀鸣嗷嗷”，同一用意。
《唐诗选脉会通评林》：此与“旧时闻笛泪”一章，悲调自饶神韵，不必深远。
《唐诗别裁》：四语与“残阳见旧山”同妙（末句下）。
《增订唐诗摘钞》：刘文房《穆陵关作》独三、四两语居胜，全首雅润，尚不及此篇。', 'center', 1417180053, '57b939027db2a20054287e41', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10569, '蜀先主庙', NULL, 146, 815, 2, 3, '刘禹锡', NULL, 10047, '57b922b57db2a2005427bf3a', '唐', 'shi', '诗', 'http://baike.baidu.com/view/159313.htm', '', '天地英雄气，千秋尚凛然。
势分三足鼎，业复五铢钱。
得相能开国，生儿不象贤。
凄凉蜀故妓，来舞魏宫前。', '此诗意在赞誉英雄，鄙薄庸碌，赞扬了刘备的功业，慨叹蜀汉事业后继非人，总结蜀汉亡国的历史教训。首联写先主庙堂威势逼人，颔联赞刘备的英雄业绩，颈联为刘备功业未成、嗣子不肖而叹息，尾联感叹后主亡国。全诗措词精警凝炼，对仗警辟工整，风格沉着超迈，前半写功德，后半写衰败，以形象垂戒当世。', '蜀先主：即汉昭烈帝刘玄德。诗题下原有注：「汉末谣，黄牛白腹，五铢当复。」
天地英雄：一作「天下英雄」。《三国志·蜀志·先主传》：曹孟德曾对刘玄德说：「天下英雄，唯使君与操耳」。
「势分三足鼎」句：指刘玄德创立蜀汉，与魏、吴三分天下。
五铢钱：汉武帝元狩五年（西元前一一八年）铸行的一种钱币。此代指刘汉帝业。
「业复五铢钱」句：王莽代汉时，曾废五铢钱，至东汉初年，光武帝又依照马伏波的奏议重铸，天下称便。这里以光武帝恢复五铢钱，喻刘玄德想复兴汉室。
相：此指诸葛亮。
不象贤：此言刘备之子刘禅不肖，不能守业。
「凄凉蜀故妓，来舞魏宫前」句：蜀汉后主降魏后，被东迁到洛阳，封为安乐县公。魏太尉司马子上在宴会中使蜀国的女乐表演歌舞，旁人见了都为后主感慨，独后主「喜笑自若」，乐不思蜀（《三国志·蜀志·后主传》裴注引《汉晋春秋》）。妓，女乐，实际也是俘虏。', '先主刘备英雄气概充满天地，千秋万代一直令人肃然起敬。
建国与吴魏三分天下成鼎足，恢复五铢钱币志在汉室振兴。
拜诸葛亮为丞相开创了国基，可惜生个儿子不像其父贤明。
最凄惨的是那蜀宫中的歌伎，在魏宫歌舞刘禅也毫无羞情。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c4d635634aee3deda3", "shortContent": "《蜀先主庙》是刘禹锡五律中传诵较广的一首。蜀先主就是刘备。先主庙在夔州（治所在今重庆奉节东），本诗当是刘禹锡任夔州刺史时所作。\n首联“天下英雄气，千秋尚凛然”，高唱入云，突兀劲挺。细品诗味，其妙有三：一、境界雄阔绝伦。“天下”两字囊括宇宙，极言“英雄气”之充塞六合，至大无垠；“千秋”两字贯串古今，极写“英雄气”之万古长存，永垂不朽。遣词结言，又显示出诗人吞吐日月、俯仰古今之胸臆。二、使事无迹。“天...", "authors": ["吴汝煜"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f0933b", "shortContent": "此诗是刘禹锡任夔州刺史（821—824年）时，过蜀先主刘备庙而作的怀古诗。其意不仅在赞誉英雄，鄙薄庸碌，更在于借古讽今，表达对国事衰祚之下君王不思进取的深深忧虑。\n\n首联以大气弘阔之笔，赞誉曾经开创一代基业的天下英雄刘备。当年刘备气冲牛斗，豪气干云，其英雄气概充溢天地，千秋万代以来，一直令人肃然起敬。用“天下”与“千秋”相对，从空间与时间的视域彰显出刘备的英雄气概。诗人伫立于刘备庙前，联想起当年曹...", "authors": ["乐云"], "pressName": "崇文书局"}]', '刘后村《后村诗话》：刘梦得五言如《蜀先主庙》云：「天地英雄气，千秋尚凛然……」（七言如）《哭吕温公》云：「遗草一函归太史，旅坟三尺近要离。」《金陵怀古》云：「山围故国周遭在，潮打空城寂寞回。」诗雄浑老苍，沉着痛快，小家数不能及也。
方虚谷《瀛奎律髓》：梦得此诗用「三足鼎」、「五铢钱」，可谓精当，然末句非事实也。蜀固亡矣，魏亦岂为存哉？
查初白《初白庵诗评》：中两联字字确切，惜结句不称。
黄九烟《唐诗快》：五字有千钧之力（首句下）。先主有知，亦当泪下（未句下）。
方虚谷《瀛奎律髓汇评》：纪昀：句句精拔。起二句确是先主庙，妙似不用事者。后四句沉着之至，不病其直。许印芳：凡祠庙坟墓等题，总宜从人着笔，不可引纠缠祠墓。盖祠墓是公共之物，略用关合足矣。人是木题正位，宜用重笔发挥，乃合体栽。如此诗全说先主，于「庙」字无一语道及，而起结皆扣住「庙」字。起语足从庙貌看出，结语则以魏官对照蜀庙也。
余成教《石园诗话》：《先主庙》云：「得相能开国，生儿不象贤。」论断简切。
王文濡《历代诗评注读本》：前写先主英雄，何等气概！后及后左昏暗，致堕先业，而蜀妓之舞，正其明证，足为后主之殷鉴。', 'center', 1417302150, '57b90d29d342d3005ac78cb5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10570, '没蕃故人', NULL, 68, 444, 1, 1, '张籍', NULL, 10134, '57b9c2fd7db2a20068bebb37', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383444.htm', '', '前年戍月支，城下没全师。
蕃汉断消息，死生长别离。
无人收废帐，归马识残旗。
欲祭疑君在，天涯哭此时。', '《没蕃故人》是唐代诗人张籍所作的五言律诗，是《全唐诗》的第三百八十四卷第一百一十一首。此诗首联以叙事的方式交待全军覆没的时间和地点；颔联承接上文写诗人与友人消息断绝、不知生死的沉痛之情；颈联用一组特写镜头，想象全军覆没后的惨景；尾联情真意切，诚堪呜咽，揭示诗人内心两为其难、望涯痛哭的曲折心情。全诗不着议论，但字里行间充溢着对没蕃故人和唐军将士的深切同情，而对战争的痛恨和对国事的忧虑亦隐寓其中。', '没蕃（fān）：是陷入蕃人之手，古代称异族为「蕃」。據「前年戍月支」句，此处当指大食，卽阿拉伯帝国。
戍：驻守。
月支：一作「月氏」。唐羁縻都督府名。龙朔元年在吐火罗境内阿缓城置。故地在今阿富汗东北部孔杜兹城附近。约公元八世纪中叶因大食国势力东进而废弃。
没全师：全军覆没。
蕃汉：吐蕃和唐朝。
废帐：战后废弃的营帐。
残旗：残留的军旗。', '前年驻守月支，在城下全军覆没。
吐蕃和唐朝断了音讯，我与你生死两隔，长久别离。
战场上无人收拾废弃的营帐，归来的战马还认识残破的军旗。
想祭奠你又怀疑你还活着，此时只能朝着天边痛哭流涕。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f0933c", "shortContent": "此诗是作者怀念在唐朝与吐蕃战争中失踪的老朋友所作。其思念之凄切，伤怀之沉痛，弥漫全篇，令人涕泪。\n\n首联交代故人失踪的时间、地点及事由。前年故人出征月支，结果不幸在城下全军覆没。“没全师”，极尽战争之惨烈。“前年”二字，则交代时间之绵远。前年之事，为何如今诗人才诉说？实在是因为音信不通，虽然全军覆没，但故人下落不明，故而依然心怀期盼，盼望故人有朝一日能回到自己身边。由此可见，两年之间，诗人该是怎样...", "authors": ["乐云"], "pressName": "崇文书局"}]', '', 'center', 1417304648, '57b9093a0a2b58005c92804c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (50919, '苏幕遮', NULL, 0, 26, 0, 1, '高道宽', NULL, 11195, '5858e6398d6d810065c3153c', '元', 'ci', '词', NULL, NULL, '聚三华，合四象。一气流通，上下频升降。飞入泥丸光百丈。岁久年深，炼成琉璃帐。
证先天，朝无上。当位中庸，三五三十棒。打就不来亦不往。这个家风，端的无虚妄。', NULL, NULL, NULL, NULL, NULL, 'indent', 1529685192, '585cefbb128fe1006ba0940c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10571, '赋得古原草送别', NULL, 1728, 2952, 4, 10, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', 'http://baike.baidu.com/view/159123.htm', '', '离离原上草，一岁一枯荣。
野火烧不尽，春风吹又生。
远芳侵古道，晴翠接荒城。
又送王孙去，萋萋满别情。', '此诗是唐代诗人白居易的成名作，通过对古原上野草的描绘，抒发送别友人时的依依惜别之情。它可以看成是一曲野草颂，进而是生命的颂歌。诗的前四句侧重表现野草生命的历时之美，后四句侧重表现其共时之美。全诗章法谨严，用语自然流畅，对仗工整，写景抒情水乳交融，意境浑成，是“赋得体”中的绝唱。', '赋得：借古人诗句或成语命题作诗。诗题前一般都冠以“赋得”二字。这是古代人学习作诗或文人聚会分题作诗或科举考试时命题作诗的一种方式，称为“赋得体”。
离离：青草茂盛的样子。
一岁一枯荣：枯，枯萎。荣，茂盛。野草每年都会茂盛一次，枯萎一次。
远芳侵古道：芳，指野草那浓郁的香气。远芳：草香远播。侵，侵占，长满。远处芬芳的野草一直长到古老的驿道上。
晴翠：草原明丽翠绿。
王孙：本指贵族后代，此指远方的友人。
萋萋（qī）：形容草木长得茂盛的样子。', '原野上长满茂盛的青草，年年岁岁枯萎了又苍翠。
原野上的大火无法烧尽，春风一吹它又生机勃发。
芳草的馨香弥漫着古道，阳光照耀下碧绿连荒城。
又送游子远行踏上古道，满怀离情望着萋萋芳草。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c87d0ac114549538f4", "shortContent": "此诗作于贞元三年（787），作者时年十六。诗是应考的习作。按科场考试规矩，凡指定、限定的诗题，题目前须加“赋得”二字；作法与咏物相类，须缴清题意，起承转合要分明，对仗要精工，全篇要空灵浑成，方称得体。束缚如此之严，故此体向少佳作。据载，作者这年始自江南入京，谒名士顾况时投献的诗文中即有此作。起初，顾况看着这年轻士子说：“米价方贵，居亦弗易。”虽是拿居易的名字打趣，却也有言外之意，说京城不好混饭吃。...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad4797a92d5e4fd900", "shortContent": "此诗作于贞元三年（787），作者时年十六。诗是应考的习作。按科场考试规矩，凡指定、限定的诗题，题目前须加“赋得”二字；作法与咏物相类，须缴清题意，起承转合要分明，对仗要精工，全篇要空灵浑成，方称得体。束缚如此之严，故此体向少佳作。据载，作者这年始自江南入京，谒名士顾况时投献的诗文中即有此作。起初，顾况看着这年轻士子说：“米价方贵，居亦弗易。”虽是拿居易的名字打趣，却也有言外之意，说京城不好混饭吃。...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f0933d", "shortContent": "重读这首儿时每每脱口而出的诗作，似乎因太过熟悉而产生了陌生的感觉。一闭上眼，就幻出一群小伙伴拍手而歌此作的情景，耳旁响起的，是他们稚嫩而清脆的声音。诗作的旋律因他们的吟唱而久久在耳际跳跃、回响。\n\n诗作构思巧妙，从草写到古原，写到送别，把草与送别极自然地关合起来，完成了诗题。\n\n诗歌前四句，抒写春草的旺盛生命力。“离离”是草茂盛的样子。“一岁一枯荣”是写草的自然生长机理。草为一年生植物，春荣秋枯，...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270727f0b9738b369b225", "shortContent": "重读这首儿时每每脱口而出的诗作，似乎因太过熟悉而产生了陌生化的感觉。一闭上眼，就幻出一群小伙伴拍手而歌此作的情景，耳旁响起的，是他们稚嫩而清脆的声音。诗作的旋律因他们的吟唱而久久在耳际跳跃、回响。\n\n诗作构思巧妙，从草写到古原，写到送别，把草与送别极自然地关合起来，完成了诗题。\n\n诗歌前四句，抒写春草的旺盛生命力。“离离”是草茂盛的样子。“一岁一枯荣”是写草的自然生长机理。草为一年生植物，春荣秋枯...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127115e6f69b71e93f6390", "shortContent": "重读这首儿时每每脱口而出的诗作，似乎因太过熟悉而产生了陌生化的感觉。一闭上眼，就幻出一群小伙伴拍手而歌此作的情景，耳旁响起的，是他们稚嫩而清脆的声音。诗作的旋律因他们的吟唱而久久在耳际跳跃、回响。\n\n诗作构思巧妙，从草写到古原，写到送别，把草与送别极自然地关合起来，完成了诗题。\n\n诗歌前四句，抒写春草的旺盛生命力。“离离”是草茂盛的样子。“一岁一枯荣”是写草的自然生长机理。草为一年生椬物，春荣秋枯...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645d09bbec56251f2eeb5b78", "bookTitle": "白居易诗文鉴赏辞典", "articleId": "6462cfe530675327e1806b70", "shortContent": "此诗作于贞元三年（787），作者时年十六。诗是应考的习作。按科场考试规矩，凡指定、限定的诗题，题目前须加“赋得”二字；作法与咏物相类，须缴清题意，起承转合要分明，对仗要精工，全篇要空灵浑成，方称得体。束缚如此之严，故此体向少佳作。据载，作者这年始自江南入京，谒名士顾况时投献的诗文中即有此作。起初，顾况看着这年轻士子说：“米价方贵，居亦弗易。”虽是拿居易的名字打趣，却也有言外之意，说京城不好混饭吃。...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471a10f82772d4594264120", "shortContent": "古原草的特性就是具有顽强的生命力，它是斩不尽、锄不绝的，只要残存一点根须，来年会更青更长，很快蔓延原野。作者抓住这一特点，不说“斩不尽、锄不绝”，而写作“野火烧不尽”，便造就一种壮烈的意境。野火燎原，烈焰可畏，瞬息间，大片枯草被烧得精光。而强调毁灭的力量，毁灭的痛苦，是为着强调再生的力量，再生的欢乐。烈火是能把野草连茎带叶统统“烧尽”的，然而作者偏说它“烧不尽”，大有意味。因为烈火再猛，也无奈那深...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '《古欢堂集杂著》：刘孝绰妹诗：“落花扫更合，丛兰摘复生”。孟浩然“林花扫更落，径草踏还生”。此联岂出自刘欤？……古人作诗，皆有所本，而脱化无穷，非蹈袭也。
《唐诗成法》：不必定有深意，一种宽然有余地气象，便不同啾啾细声，此大小家之别。
《唐诗三百首》：诗以喻小人也。消除不尽，得时即生，干犯正路。文饰鄙陋，却最易感人。
《诗境浅说》：诵此诗者，皆以为喻小人去之不尽，如草之滋蔓。作者正有此意，亦未可知。然取喻本无确定，以为喻世道，则治乱循环；以为喻天心，则贞元起伏。虽严寒盛雪，而春意已萌。见仁见智，无所不可。', 'center', 1417304934, '57b8a5371532bc005b99da51', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10572, '旅宿', NULL, 108, 501, 1, 2, '杜牧', NULL, 10109, '57b9836cc4c971005593dfec', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383445.htm', '', '旅馆无良伴，凝情自悄然。
寒灯思旧事，断雁警愁眠。
远梦归侵晓，家书到隔年。
沧江好烟月，门系钓鱼船。', '此诗是一首羁旅怀乡之作。诗人离家已久，客居旅馆，没有知音，家书传递也很困难，在凄清的夜晚不禁怀念起自己的家乡。诗中抒发了自己寂寞沉郁的心情和对家乡的深切思念。全诗含蓄蕴藉，凄绝哀惋，结构谨严，意境深远。', '良伴：好朋友。
凝情：凝神沉思。悄然：忧伤的样子。这里是忧郁的意思。
寒灯：昏冷的灯火。这里指倚在寒灯下面。思旧事：思念往事。
断雁：失群之雁，这里指失群孤雁的鸣叫声。警：惊醒。
远梦归：意谓做梦做到侵晓时，才是归家之梦，家远梦亦远，恨梦归之时也甚短暂，与下句家书隔年方到，恨时间之久，相对而更增烦愁。侵晓：破晓。沧江：泛指江，一作“湘江”。
好烟月：指隔年初春的美好风景。
门：门前。', '韵译
住在旅馆中并无好的旅伴；忧郁的心情恰似凝固一般。
对着寒灯回忆起故乡往事；就像失群的孤雁警醒愁眠。
家乡太远归梦到破晓未成；家书寄到旅馆已时隔一年。
我真羡慕门外沧江的烟月；渔人船只就系在自家门前。
直译
旅馆里没有知心朋友，我独自静静地沉思凝神。对着寒灯回忆往事，孤雁的叫声，惊醒了凄寂梦魂。乡关道路迢远，梦魂拂晓时才得归去，家人的书信要等来年方能寄到此地。沧江上月色含烟，风光是多么美好，钓鱼船就系在我家门前。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f0933e", "shortContent": "此诗据传为杜牧外放江西时，因客居旅馆，思乡情切而作，是一首典型的羁旅怀乡诗。清章燮《唐诗三百首注疏》云：“以幽闲之意结之，益见旅人跋涉之苦，则思乡之情更难堪矣。”此评可作此诗之注解。\n\n首联破题，点明旅宿的情境与心境。诗人独宿旅店，没有一个知心朋友共话衷肠，无奈之下只有独自静静沉思凝神，其思乡念亲的情绪喷薄而出，无法自抑。作为古典诗歌中的重要题材，羁旅愁思一般表达的是无伴的孤独寂寞以及对远方亲人的...", "authors": ["乐云"], "pressName": "崇文书局"}]', '清章燮《唐诗三百首注疏》：以幽闲之意结之，益见旅人跋涉之苦，则思乡之情更难堪矣。渔船何等清闲以赏烟月，而我独跋涉风尘，不得在家赏玩，何不如渔翁之自在也。', 'center', 1417304991, '57b99ca4165abd005a6d9cf9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10573, '秋日赴阙题潼关驿楼', NULL, 170, 509, 3, 2, '许浑', NULL, 10135, '57b998ee7db2a20054f7a08c', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383447.htm', '', '红叶晚萧萧，长亭酒一瓢。
残云归太华，疏雨过中条。
树色随关迥，河声入海遥。
帝乡明日到，犹自梦渔樵。', '潼关，在今陕西省潼关县北部，位于陕西、山西、河南三省要冲，是从洛阳进入长安必经的咽喉重镇，形势险要，景色宜人，地位特殊。历代诗人路经此地，往往要题诗纪胜。许浑从故乡润州丹阳（今属江苏）第一次到长安去，途经潼关，也为其山川形势和自然景色所深深吸引，兴致淋漓，挥笔写下了这首诗作。
此诗开头两句勾勒出一幅秋日行旅图，透露出悲凉的意绪，传达出旅途的况味；中间四句大笔勾画四周景色，雄浑苍茫，全是潼关的典型风物；最后两句含蓄地表白了自己的意趣。', '阙：指唐都城长安。潼关：关名，在今陕西省潼关县境内。
红叶晚萧萧：一作「南北断蓬飘」。
长亭：古时道路每十里设长亭，供行旅停息。
太华：即西岳华山，在今陕西省华阴县境内。
过：一作「落」。
中条：山名，一名雷首山，在今山西永济县东南。
关：一作「山」。
迥：远。
海：一作「塞」。
帝乡：京都，指长安。
梦：向往。末两句一作「劳歌此分手，风急马萧萧」。', '晚风中的红叶萧萧落下，长亭里痛饮下别酒一瓢。
天上残云飞回太华山上，稀疏的细雨越过中条岭。
苍莽的树色随城关远去，黄河呼啸流进遥远海洋。
明日里就要抵达都城中，我仍在做那渔人樵夫梦。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d5d635634aee3deeb8", "shortContent": "潼关，在今陕西省潼关县境内，当陕西、山西、河南三省要冲，是从洛阳进入长安必经的咽喉重镇，形势险要，景色动人。历代诗人路经此地，往往要题诗纪胜。直到清末，谭嗣同还写下他那“河流大野犹嫌束，山入潼关不解平”（《潼关》）的名句。可知它在诗人们心目中的位置了。\n许浑从故乡润州丹阳（今属江苏）第一次到长安去，途经潼关，也为其山川形势和自然景色所深深吸引，兴会淋漓，挥笔写下了这首“高华雄浑”（清代吴汝纶语）的...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389aecdc25963feee1aaf", "shortContent": "潼关，在今陕西省潼关县境内，当陕西、山西、河南三省要冲，是从洛阳进入长安必经的咽喉重镇，形势险要，景色动人。历代诗人路经此地，往往要题诗纪胜。直到清末，谭嗣同还写下他那“河流大野犹嫌束，山入潼关不解平”（《潼关》）的名句。可知它在诗人们心目中的位置了。\n\n许浑从故乡润州丹阳（今属江苏）第一次到长安去，途经潼关，也为其山川形势和自然景色所深深吸引，兴会淋漓，挥笔写下了这首“高华雄浑”（清代吴汝纶语）...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f0933f", "shortContent": "许浑第一次去长安，从故乡润州丹阳（今属江苏）出发途经潼关（陕西省潼关县境内）时，被其险要的山川形势和动人的自然景色所深深吸引。诗人感物兴发，题诗纪胜，兴会淋漓写下这首遒劲雄浑的五言律诗。\n\n开头两句，诗人先勾勒出一幅秋日行旅图，把读者引入一个秋浓似酒、旅况萧瑟的境界。“红叶晚萧萧”，以景透出人物一缕缕悲凉的意绪；“长亭酒一瓢”，用叙事传出客子旅途况味，用笔干净利落。此诗另一版本题作“行次潼关，逢魏...", "authors": ["李晶晶"], "pressName": "崇文书局"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "6473402a5e6bb82b8c00a411", "shortContent": "潼关，在今陕西省潼关县境内，当陕西、山西、河南三省要冲，是从洛阳进入长安必经的咽喉重镇，形势险要，景色动人。历代诗人路经此地，往往要题诗记胜。\n\n许浑从故乡润州丹阳（今属江苏）第一次到长安去，途经潼关，也为其山川形势和自然景色所深深吸引，兴会淋漓，挥笔写下了这首“高华雄浑”（清代吴汝纶语）的诗作。\n\n开头两句，作者先勾勒出一幅秋日行旅图，把读者引入一个秋浓似酒、旅况萧瑟的境界。“红叶晚萧萧”，用写...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}]', '《唐诗镜》：语虽浅近，致各自成。
《五朝诗善鸣集》：仲晦如此诗，虽与刘文房分据「长城」岈也，何拙鲁？若陈后山者，亦复疵之太过。
《历代诗法》：景近趣遥。
《唐贤小三昧集续集》：亦阔大、亦高华，晚唐中之近开、宝名句也（「残云」二句下）。
《重订中晚唐诗主客图》：博大，得登眺意（「残云」二句下）。与许文化义自不同。
《唐诗三百首》：格、意直追初盛。
《精选评注五朝诗学津梁》：此诗神味秾郁，「条」、「遥」两韵，非后学所能通畿。
《小清华园诗谈》：唐人之诗，有清和纯粹可诵而可法者，如许浑之「红叶晚萧萧……」。
《养一斋诗话》：五律之「红叶晚萧萧」，全局俱动，为晚唐之翘秀也。
《唐宋诗举要》：吴北江曰：高华雄浑，丁卯压卷之作。
《诗境浅说》：凡作客途风景诗者，山川形势，最宜明了；笔气能包扫一切，而句法复雄宕高超，斯为上乘：许诗其佳选也。开篇从秋日说起，若仙人跨鹤，翩然自空而降；首句即押韵，神味尤隽。三四句皆潼关左右之名山；太华在关西，中条在关东，皆数百里而近；残云挟雨，自东而西，应过中条而归太华，地望固确，诗句弥工。五句以雍州为积高之壤，入关以后迤逦而登，故树色亦随关而迥。余曾在风陵渡河望潼关树色，高入云中，深叹其「迥」字之妙。六句言大河横亘关前，浩浩黄流，遥通沧海，表里山河之险，涌现毫端。以上皆纪客途风景。篇终始言赴阙，觚棱在望，而故乡回首，犹梦渔樵，知其荣利之淡也。', 'center', 1417305132, '57aca12b128fe10055a2c73e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10574, '早秋', NULL, 99, 509, 1, 2, '许浑', NULL, 10135, '57b998ee7db2a20054f7a08c', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383448/7982955.htm', '', '遥夜泛清瑟，西风生翠萝。
残萤栖玉露，早雁拂金河。
高树晓还密，远山晴更多。
淮南一叶下，自觉洞庭波。', '此诗描绘初秋景色。前四句写早秋的夜景，五、六两句写早秋的昼景，在描绘秋景的过程中，诗人注重高低远近，落笔细致而层次井然。「一叶落而知天下秋」，最后两句运用《淮南子》与《楚辞》典故，浑然一体，神气十足，又将身世感叹暗寓于其中。', '遥夜：即长夜。
泛：弹，犹流荡。
清瑟（sè）：清细的瑟声。瑟，拨弦乐器，形似琴，二十五弦。
残萤（yíng）：残馀的萤火虫。据《礼记·月令》「（夏季之月）腐草为萤」的说法，萤火虫兴盛于夏季，秋天一到则所剩无几。
栖玉露：萤火虫栖息于沾着露珠的草叶上。
拂：掠过。
金河：即银河。五行学说称秋天为金，故称秋天的银河为金河。
还密：尚未凋零。
一叶下：《淮南子·说山训》：「以小明大，见一叶落，而知岁之将暮。」
洞庭波：用屈原《楚辞·九歌·湘夫人》「袅袅兮秋风，洞庭波兮木叶下」语意。正是《淮南子》上所说的「见一叶落而知岁之将暮」的时候，情不自禁想到《湘夫人》中所写的洞庭湖上生起的秋波。', '【直译】
长夜里一片清凉，绿色萝叶间吹起了西风。
残萤栖息在露珠晶莹的草间，雁群掠过初秋的星空。
晨光里高大的树木，依旧是枝繁叶密。晴空下重叠的远山，更显得分外清晰。
当枝头飘落下黄叶一片，我料想洞庭湖波浪涌起。
【韵译】
漫漫长夜中泛流着琴瑟的清音；青萝轻拂好像有西风飕飕而生。
白露凝珠的野草栖留几只残萤；秋之晨雁群掠过银河向南飞腾。
高大的树木拂晓看来尚未凋零；阳光下遥望远山层次格外分明。
淮南子有一叶落而知岁暮之句；我悟到洞庭波兮木叶下的诗情。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f09340", "shortContent": "此诗是一首描绘早秋景物的咏物诗。诗人在夏末秋初中独具慧眼，以敏锐独到的眼光发现了初秋到来的痕迹进而兴发感物，付诸笔端。原题三首，此为第一首。此诗句句扣紧早秋景色，细致而层次井然，疏朗有致，写景逼真，宛然一幅早秋立体图画。\n\n前四句写夜间景象。首联写早秋萧瑟凄清气氛。“遥夜泛清瑟，西风生翠萝”，“遥”字即“长”，写出秋夜进入秋天，就变成昼短夜长了。在寂静的夜里，诗人似乎听到有清细的瑟声在浮动，仔细辨...", "authors": ["李晶晶"], "pressName": "崇文书局"}]', '', 'center', 1417305202, '57b960a8c4c97100559282f0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10598, '酬郭给事（亦名《赠郭给事》）', NULL, 18, 394, 0, 1, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383522.htm', '', '洞门高阁霭馀晖，桃李阴阴柳絮飞。
禁里疏钟官舍晚，省中啼鸟吏人稀。
晨摇玉佩趋金殿，夕奉天书拜琐闱。
强欲从君无那老，将因卧病解朝衣。', '这是一首唱和诗，郭给事有诗给王右丞，所以王右丞作诗应答。此类应酬性的诗，总是称赞对方，感慨自身的，这首诗即意在称道郭给事。首联写郭给事的显达。第一句写皇恩普照；第二句写他桃李满天下，门生显达。颔联写郭给事奉职贤劳，居官清廉闲静，所以吏人稀少，讼事无多，时世清平。颈联直接写郭给事本人，早晨盛装朝拜、傍晚捧诏下达，不辞辛劳。尾联感慨自己老病，无法相从，表达了诗人的出世思想。', '郭给事：郭承嘏，字复卿。「给事」，即给事中，是唐代门下省的要职，常在皇帝周围，掌宣达诏令，驳正政令之违失，地位是十分显赫的。
洞门：指深宫中重重相对相通的门。
霭馀辉：遮蔽住落日的光辉。
阴阴：枝叶茂密的样子。
禁里：禁里：禁中，即皇宫中。
省：指唐门下省。
玉佩：官员身上佩带的玉石饰物。
趋：小步而行。
奉：「捧」的本字。
天书：皇帝的诏书。
拜琐闱：指毕恭毕敬地离开宫门。琐闱，宫门。因宫门上刻着连琐图案并以青色饰之，故得名。
强：勉强。
从君：喻在朝做官。
无那：无奈。
卧病：生病卧床。
解朝衣：喻不再做官。', '高高的宫门和楼阁冰浴在夕阳的馀晖中，桃李枝叶茂密，柳絮随风飞舞。
皇宫里钟声稀疏，官舍中办公的官吏已经很少，门下省里只听见鸟鸣。
早晨步入金殿时玉佩摇晃，夜晚捧着皇帝的诏书拜别宫门。
想勉强跟着您一同进退，无奈我已衰老，会因病卧床而解下我这身官袍。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92972cee9a0c24ecf7f3", "shortContent": "这首酬和诗，是王维晚年酬赠与给事中郭某的。“给事”，即给事中，是唐代门下省的要职，常在皇帝周围，掌宣达诏令，驳正政令之违失，地位是十分显赫的。王维的后半生，虽然过着半官半隐的生活，然而在官场上却是“昆仲宦游两都，凡诸王驸马豪右贵势之门，无不拂席迎之”（《旧唐书·王维传》）。因此，在他的诗作中，这类应酬的题材甚多。这首诗，既颂扬了郭给事，同时也表达了王维想辞官隐居的思想。写法上，诗人又别具机杼。最突...", "authors": ["李", "琳"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d1933015205", "shortContent": "七律这种体裁在初唐刚起步，用这种体裁作诗的人并不多，直到杜甫，才将之完善，并影响了后世大多数诗人。但杜甫的这种完善之功，也包含了盛唐诸家的贡献，这其中即有王维对于七律这种诗体的开拓。王维所写七律不多，据统计只有20首，而且应制的即有7首，此外还有酬赠诗、山水田园诗等。以酬赠诗来说，除为所赠之人说些揄扬的话之外，总体情调总是让人心生凄恻。历来论王维诗歌风格的诗评家多认为其多愁善感，但在他的酬赠送别七...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270437ccdb86c49f2921b", "shortContent": "七律这种体裁在初唐刚起步，用这种体裁作诗的人并不多，直到杜甫，才将之完善，并影响了后世大多数诗人。但杜甫的这种完善之功，也包含了盛唐诸家的贡献，这其中即有王维对于七律这种诗体的开拓。王维所写七律不多，据统计只有20首，而且应制的即有7首，此外还有酬赠诗、山水田园诗等。以酬赠诗来说，除为所赠之人说些揄扬的话之外，总体情调总是让人心生凄恻。历来论王维诗歌风格的诗评家多认为其多愁善感，但在他的酬赠送别七...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646470477da2f75ac7e6b5d4", "shortContent": "这首酬和诗，是王维晚年酬赠与给事中郭某的。“给事”，即给事中，是唐代门下省的要职，常在皇帝周围，掌宣达诏令，驳正政令之违失，地位是十分显赫的。王维的后半生，虽然过着半官半隐的生活，然而在官场上却是“昆仲宦游两都，凡诸王驸马豪右贵势之门，无不拂席迎之”（《旧唐书·王维传》）。因此，在他的诗作中，这类应酬的题材甚多。这首诗，既颂扬了郭给事，同时也表达了王维想辞官隐居的思想。写法上，诗人又别具机杼。最突...", "authors": ["李琳"], "pressName": "上海辞书出版社"}]', '', 'center', 1417443361, '57ba16de0a2b58006cb28294', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10575, '蝉', NULL, 94, 603, 2, 2, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/21638/5122266.htm', '', '本以高难饱，徒劳恨费声。
五更疏欲断，一树碧无情。
薄宦梗犹泛，故园芜已平。
烦君最相警，我亦举家清。', '李商隐平生曾两度入官秘书省，但最终未能得志，处境每况愈下。该诗就是表达了他虽仕途不顺，却坚守清高之志。全诗层层深入，阐发主题。先是描写蝉的境遇，后面直接跳到自身的遭遇上来，直抒胸臆，感情强烈，最后却又自然而然地回到蝉身上，首尾圆融，意脉连贯。', '以：因。高难饱：古人认为蝉栖于高处，餐风饮露，故说“高难饱”。
恨费声：因恨而连声悲鸣。费，徒然。
五更（gēng）：中国古代把夜晚分成五个时段，用鼓打更报时，所以叫“五更”。疏欲断：指蝉声稀疏，接近断绝。
碧：绿。
薄宦：官职卑微。梗犹泛：典出《战国策·齐策》：土偶人对桃梗说：“今子东国之桃梗也，刻削子以为人，降雨下，淄水至，流子而去，则子漂漂者将何如耳。”后以梗泛比喻漂泊不定，孤苦无依。梗，指树木的枝条。
故园：对往日家园的称呼，故乡。芜已平：荒草已经平齐没胫，覆盖田地。芜，荒草。平，指杂草长得齐平。
君：指蝉。警：提醒。
亦：也。举家清：全家清贫。举，全。清，清贫，清高。', '你栖身高枝之上才难以饱腹，悲鸣传恨无人理会白费其声。
五更以后疏落之声几近断绝，满树碧绿依然如故毫不动情。
我官职卑下像桃梗漂流不定，家园长期荒芜杂草早已长平。
烦劳你的鸣叫让我能够警醒，我是一贫如洗全家水一样清。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92db0ce818559d0588f3", "shortContent": "古人有云：“昔诗人篇什，为情而造文。”（南朝梁刘勰《文心雕龙·情采》）这首咏蝉诗，就是抓住蝉的特点，结合作者的情思，“为情而造文”的。诗中的蝉，也就是作者自己的影子。\n“本以高难饱，徒劳恨费声”，首句闻蝉鸣而起兴。“高”指蝉栖高树，暗喻自己的清高；蝉在高树吸风饮露，所以“难饱”，这又与作者身世感受暗合。由“难饱”而引出“声”来，所以哀中又有“恨”。但这样的鸣声是白费，是徒劳，因为不能使它摆脱难饱的...", "authors": ["周振甫"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9820695e6503fff2", "shortContent": "古人有云：“昔诗人篇什，为情而造文。”（南朝梁刘勰《文心雕龙·情采》）这首咏蝉诗，就是抓住蝉的特点，结合作者的情思，“为情而造文”的。诗中的蝉，也就是作者自己的影子。\n\n“本以高难饱，徒劳恨费声”，首句闻蝉鸣而起兴。“高”指蝉栖高树，暗喻自己的清高；蝉在高树吸风饮露，所以“难饱”，这又与作者身世感受暗合。由“难饱”而引出“声”来，所以哀中又有“恨”。但这样的鸣声是白费，是徒劳，因为不能使它摆脱难饱...", "authors": ["周振甫"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d8873206168b2e01ea1", "shortContent": "首联谓蝉因高洁而食不果腹，悲鸣传恨，徒费其声也。次联谓蝉一夜哀鸣不息，至五更鸣声渐稀，几欲断绝，然而所栖之碧树竟似漠然无闻，何其无情也。三联谓己官职卑微而且飘浮不定，故园荒芜，蔓草与禾稼齐平。末谓听蝉鸣如好友对我提醒，我亦举家清贫也。通篇以蝉自喻，有神无迹，颇难征实，堪称绝唱。", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f09341", "shortContent": "在盛夏溽暑时节，蝉是最活跃的动物，它们独特的知了声此起彼伏地喧嚣着，增添了人们的烦躁之感。然而，在诗人的吟咏中，蝉往往被赋予了高洁的人格特质，寄托着作者遥深的情感。在初唐诗人虞世南的《蝉》中，蝉已被看作高洁脱俗的形象，它们渴饮清冽的露水，生长于稀疏高耸的梧桐树里自由地长鸣不已；“居高声自远，非是藉秋风”一句，寓含着诗人的寄托，以蝉不假外力而将声音远播，来完成诗人自我精神的展现和升华。骆宾王也有《咏...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64630d507da2f75ac7e0cea0", "shortContent": "古人有云：“昔诗人篇什，为情而造文。”（南朝梁刘勰《文心雕龙·情采》）这首咏蝉诗，就是抓住蝉的特点，结合作者的情思，“为情而造文”的。诗中的蝉，也就是作者自己的影子。\n\n“本以高难饱，徒劳恨费声”，首句闻蝉鸣而起兴。“高”指蝉栖高树，暗喻自己的清高；蝉在高树吸风饮露，所以“难饱”，这又与作者身世感受暗合。由“难饱”而引出“声”来，所以哀中又有“恨”。但这样的鸣声是白费，是徒劳，因为不能使它摆脱难饱...", "authors": ["周振甫"], "pressName": "上海辞书出版社"}]', '《汇编唐诗十集》：唐云：堪与骆临海、张曲江并驰。
《唐诗归》：钟云：五字名士赞（首句下）。钟云：三字冷极，幻极（“一树”句下）。钟云：自处不苟（末句下）。
《唐诗选脉会通评林》：周敬云：虞世南云“居高声自远”，骆宾王“清畏人知”、义山“本以高难饱”语，皆善言蝉之德。
《唐诗快》：说得有品有操，竟似虫中夷齐（“本以”句下）。
《唐律消夏录》：首二句写蝉之鸣，三四写蝉之不鸣；“一树碧无情”，真是追魂取气之句。五六先作“清”字地步，然后借“烦君”二字折出结句来，法老笔高，中晚一人也。
《五朝诗善鸣集》：清绝。
《围炉诗话》：义山《蝉》诗，绝不描写用古，诚为杰作。
《唐音审体》：神句非复思议可通，所谓不宜释者是也（“一树”句下）。
《唐诗成法》：三四流水对，言蝉声忽断忽续，树色一碧。五六说目前客况，开一笔，结方有力。
《李义山诗集笺注》：姚培谦曰：此以蝉自况也。蝉之自处既高矣，何恨之有？三承“声”字，四承“恨”字。五六言我今实无异于蝉。听此声声相唤，岂欲以警我耶？不知我举家清况已惯，毫无怨尤，不劳警得也。
《唐诗观澜集》：追魂之笔，对句更可思而不可言（“五更”二句下）。
《历代诗法》：炉锤极妙，此题更无敌手。
《唐诗别裁》：取题之神（“五更”句下）。
《唐贤小三昧集续集》：十字神妙（“五更”二句下）。
《玉溪生诗说》：起二句斗入有力，所谓意在笔先。前半写蝉，即自喻；后半自写，仍归到蝉。隐显分合，章法可玩。
《网师园唐诗笺》：咏物而揭其神，乃非漫咏（“五更”二句下）。
《唐贤清雅集》：比体，末点明正意。“一树碧无情”，比孟襄阳“空翠落庭阴”更微妙，玩起结自见。
《唐诗三百首》：无求于世，不平则鸣；鸣则萧然，止则寂然。上四句借蝉喻己，以下直抒己意。
《岘佣说诗》：三百篇比兴为多，唐人犹得此意。同一咏蝉，虞世南“居高声自远，端不藉秋风”，是清华人语；骆宾王“露重飞难进，风多响易沉”，是患难人语；李商隐“本以高难饱，徒劳恨费声”，是牢骚人语。比兴不同如此。
《诗境浅说》：学作诗者，读宾王《咏蝉》，当惊为绝调；及见玉溪诗，则异曲同工，可见同此一题，尚有馀义，若以他题咏物，深思善体，不患无着手处也。', 'center', 1417305282, '57b96792a633bd006660f3cf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10576, '风雨', NULL, 175, 603, 2, 2, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/34018/8050422.htm', '', '凄凉宝剑篇，羁泊欲穷年。
黄叶仍风雨，青楼自管弦。
新知遭薄俗，旧好隔良缘。
心断新丰酒，销愁斗几千。', '这是一首作者以风雨比喻自己境遇的咏怀诗。这首诗首联借《宝剑篇》的典故发端，反衬自己长年漂泊凄凉的身世。颔联通过对比抒发自己对不平境遇的怨愤。颈联直接写明由于陷入党争，致使新知，旧友都已疏远冷落，更具体表现了自己孤凄寂寞的身世。尾联写自己本欲断酒，但由于忧愁，又不断饮酒消愁。全诗意境悲凉，表现诗人沉沦孤独的感情和遭遇，真切感人。', '题解：这首诗取第三句诗中「风雨」二字为题，实为无题。
宝剑篇：为唐初郭震（字元振）所作诗篇名。《新唐书·郭震传》载，武则天召他谈话，索其诗文，郭即呈上《宝剑篇》，中有句云：「非直接交游侠子，亦曾亲近英雄人。何言中路遭捐弃，零落飘沦古岳边。虽复沉埋无所用，犹能夜夜气冲天。」武则天看后大加称赏，立即加以重用。
羁泊：即羁旅飘泊。
穷年：终生。
黄叶：用以自喻。
仍：仍旧、依然。
青楼：青色的高楼。此泛指精美的楼房，即富贵人家。
新知：新的知交。
遭薄俗：遇到轻薄的世俗。
旧好：旧日的好友。
隔：阻隔、断绝。
心断：意绝。
新丰：地名，在今陕西省临潼县东，古时以产美酒闻名。《新唐书·马周传》载，马周不得意时，宿新丰旅店，店主人对他很冷淡，马周便要了一斗八升酒独酌。后得常何推荐，受到唐太宗的赏识，授监察御史。
销愁：一作“消愁”。
几千：指酒价，美酒价格昂贵。', '我虽然胸怀匡国之志，也有郭元振《宝剑篇》那样充满豪气的篇，但却不遇明主，长期羁旅在外虚度华年。黄叶已经衰枯，风雨仍在摧毁，豪门贵族的高楼里，阔人们正在轻歌曼舞，演奏着急管繁弦。新交的朋友遭到浇薄世俗的非难，故旧日的老友又因层层阻隔而疏远无缘。心中想要断绝这些苦恼焦烦，要用新丰美酒来销愁解闷，管它价钱是十千还是八千。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dcdbb8b379ee095d24", "shortContent": "这首诗大约作于诗人晚年羁泊异乡期间。这时，长期沉沦漂泊、寄迹幕府的诗人已经到了人生的穷途。这篇《风雨》，正像是这位饱受人世风雨摧残的一代才人，在生命之火将要熄灭之前所唱出的一曲慷慨不平的悲歌。\n“凄凉宝剑篇，羁泊欲穷年。”诗一开头就在一片苍凉沉郁的气氛中展示出理想抱负与实际境遇的矛盾。《宝剑篇》是唐代前期名将郭元振落拓未遇时所写的托物寓怀之作。诗借古剑尘埋托寓才士不遇，在磊落不平中显示出积极用世的...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d8b73206168b2e01eb3", "shortContent": "诗题曰《风雨》，谓风雨中羁旅异乡，愁绪万端，乃作此篇也。首联谓己如同龙泉宝剑，可是被弃置不用，长期飘泊在外。次联谓己如同风雨飘摇之黄叶，屡遭不幸；而富贵利达者，自是得意。三联谓遭遇新交之轻视嫉妒，而旧交“不念携手好，弃我如遗迹”也。末谓望断新丰之酒，不知需多少美酒才可以消此不尽之愁也。冯、张皆以为是客游江东之作。", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f09342", "shortContent": "此诗当作于唐宣宗大中十一年（857）游江东时，作者自伤身世，慨叹飘零沦落、怀才不遇的苦闷。此诗题名“风雨”，实则暗示诗人凄风苦雨、坎坷艰难的一生。\n\n首联用郭震《宝剑篇》典故起笔，表达胸怀大志却不遇明主的伤感。据《新唐书•郭震传》载，郭震少有大志，武则天闻其名召见，索其诗文，郭即呈上《宝剑篇》，中有句曰：“非直结交游侠子，亦曾亲近英雄人。何言中路遭弃捐，零落飘沦古狱边。虽复尘埋无所用，犹能夜夜气冲...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64631b367da2f75ac7e10caf", "shortContent": "这首诗大约作于诗人晚年羁泊异乡期间。这时，长期沉沦漂泊、寄迹幕府的诗人已经到了人生的穷途。这篇《风雨》，正像是这位饱受人世风雨摧残的一代才人，在生命之火将要熄灭之前所唱出的一曲慷慨不平的悲歌。\n\n“凄凉宝剑篇，羁泊欲穷年。”诗一开头就在一片苍凉沉郁的气氛中展示出理想抱负与实际境遇的矛盾。《宝剑篇》是唐代前期名将郭元振落拓未遇时所写的托物寓怀之作。诗借古剑尘埋托寓才士不遇，在磊落不平中显示出积极用世...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '明·陆时雍《唐诗镜》：三、四语极自在。诗以不做为佳。中、晚刻核之极，有翻入自然者。然未易多摘耳。
清·姚培谦《李义山诗集笺注》：凄凉羁泊，以得意人相形，愈益难堪。风雨自风雨，管自管弦，宜愁人之肠断也。夫新知既日薄，而旧好且终睽，此时虽十千买酒，也消此愁不得，遑论新丰价值哉？
清·纪晓岚《玉谿生诗说》：神力完足。「仍」字、「自」字多少悲凉。芥舟谓「旧好」句疵，余谓「新知」句亦露骨，此诗累于此二句。
清·薛雪《一瓢诗话》：老杜善用「自」字。……李义山「青楼自管弦」、「秋池不自冷」、「不识寒郊自转蓬」之类，未始非无穷感慨之情，所以直登老杜之堂，亦有由矣。
清·蘅塘退士《唐诗三百首》：「仍」字、「自」字诗眼。', 'center', 1417305371, '57b906b0df0eea0063350e21', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10577, '落花', NULL, 118, 603, 0, 1, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/341647/5143816.htm', '', '高阁客竟去，小园花乱飞。
参差连曲陌，迢递送斜晖。
肠断未忍扫，眼穿仍欲归。
芳心向春尽，所得是沾衣。', '这是一首专咏落花的诗。首联写落花与人的心情，含蓄蕴籍耐人寻味。颔联从不同角度描写落花「乱飞」的具体情状。颈联直接抒发情感，巴望花不再落而不能。末联写花为装点春天而开，却落得飘零沾衣的结局。表达了素怀壮志，不见用于世的凄婉和感慨。全诗洋溢着伤春惜花之感，情思如痴，委婉动人。', '客竟去：客人竟然都离去了。
参差：错落不齐的样子。曲陌：曲折的小径。
迢递（tiáodì）：高远貌。此处指落花飞舞之高远者。
仍欲归：仍然希望其能归还枝头。
芳心：这里既指花的精神灵魂，又指怜爱花的人的心境。
沾衣：这里既指落花依依沾在人的衣服之上，又指怜爱花的人伤心而抛洒的泪滴。', '高阁上的游客们已经竞相离去；小园的春花随风凋零纷纷乱飞。
花影参差迷离接连着弯弯小径；远望落花回舞映着斜阳的余晖。
我的肝肠欲断不忍把落红扫去；望眼欲穿盼来春天却匆匆回归。
爱花惜花自然要怨春去得太早；春尽花谢所得的只是落泪沾衣。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dd2e6a6b501f95c54f", "shortContent": "这首咏物诗作于会昌六年（846）闲居永乐期间。当时，李商隐因娶王茂元之女一事已构怨于牛党的令狐绹，境况很不如意。自然景物的变化极易触发他的忧思羁愁，于是便借园中落花隐约曲折地吐露自己的心曲。\n诗一起便写落花景象，前人称赞它发端“超忽”。其实，“小园花乱飞”一句不过是人皆可道之景，手法平平，并不新奇；妙就妙在首联两句之间的联系。落花是一种自然现象，和客去本无必然的联系，但诗人却说花是因客去才“乱飞”...", "authors": ["张明非"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d827f0b9738b369aee5", "shortContent": "此篇写惜花伤春以寄慨。一二句谓客去花飞，心意茫然。三四句谓落花在斜阳中飘洒不断，残红满径。五六句谓为落花而伤心，不忍清扫；极目远望，飞花越飘越少。末二句谓惜花之心随着春天的过尽而彻底失望，只剩几片残花沾在衣襟。惜花伤春，写得飘忽有神，毫无粘滞的感觉，格调超迈，一结无限深情。", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f09343", "shortContent": "这首诗写于会昌六年（846），作者正闲居永乐（今山西永济）。当时，李商隐陷入牛李党争之中，境况不佳，心情郁闷，以落花寓慨身世，流露出幽恨怨愤之情。\n\n首联起笔叙事：酒宴散去，客人终于离去。曲终人散，人去楼空，剩下我一个人独自徘徊在小园里，看落花满地，随风乱飞。诗人赋闲无事，落寞无成，心境颓然，恰逢朋友来聚，宽慰心怀。岂知欢聚后留下的寂寞与悲凉比往日更深几层！前一句叙事，看似平淡，实则为后文写景抒情...", "authors": ["林妙芝"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707a73206168b2e02223", "shortContent": "这首诗写于会昌六年（846），作者正闲居永业。当时，李商隐陷入牛李党争之中，境况不佳，心情郁闷，以落花寓慨身世，流露出幽恨怨愤之情。\n\n首联起笔叙事：酒宴散去，客人终于离去。曲终人散，人去楼空，剩下我一个人独自徘徊在小园里，看落花满地，随风乱飞。诗人赋闲无事，落寞无成，心境颓然，恰逢朋友来聚，宽慰心怀。岂知欢聚后留下的寂寞与悲凉比往日更深几层！前一句叙事，看似平淡，实则为后文写景抒情铺一高台，尤其...", "authors": ["林妙芝"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "646361955fc8182fe998c587", "shortContent": "这首咏物诗作于会昌六年（846）闲居永乐期间。当时，李商隐因娶王茂元之女一事已构怨于牛党的令狐绹，境况很不如意。自然景物的变化极易触发他的忧思羁愁，于是便借园中落花隐约曲折地吐露自己的心曲。\n\n诗一起便写落花景象，前人称赞它发端“超忽”。其实，“小园花乱飞”一句不过是人皆可道之景，手法平平，并不新奇；妙就妙在首联两句之间的联系。落花是一种自然现象，和客去本无必然的联系，但诗人却说花是因客去才“乱飞...", "authors": ["张明非"], "pressName": "上海辞书出版社"}]', '《唐诗归》：锺云：俗儒谓温、李作《落花》诗，不知如何纤媚，讵意高雅乃尔！锺云：落花如此起，无谓而有至情。谭云：调亦高（首句下）。锺云：深情苦语（「肠断」句下）。锺云：「所得」二字苦甚（末句下）。
《五朝诗善鸣集》：落花诗全无脂粉气，真是艳诗好手。
《围炉诗话》：《落花》起句奇绝，通篇无实语，与《蝉》同，结亦奇。
《李义山诗集辑评》：何焯云：起得超忽，连「落花」，看得有意，结亦双关。一结无限深情，「得」字意外巧妙。
《唐律消夏录》：客去凭栏，正无聊赖，风飘万点，不觉伤心。三四写乱飞，并写高阁，亦得神理。
《唐诗成法》：人但知赏首句，赏结句者甚少。一二乃倒叙法，故警策，若顺之，则平庸矣。首句如彩云从空而坠，令人茫然不知所为；结句如腊月二十三日夜听唱「你若无心我便休」，令人心死。
《玉溪生诗意》：「芳心」紧承五六，是进一步法。
《唐诗别裁》：题易粘腻，此能扫却臼科。
《玉溪生诗集笺注》：田兰芳曰：起超忽，连落花亦看作有情矣。结亦双关。杨守智曰：一结无限深情。
《玉溪生诗说》：宋弼云：好起结，非人所及。纪昀：起句亦非人意中所无，但不免放在中间。后面写寂莫之景耳。得神在倒跌而入。戈诗云：起句真是超绝，「眼穿」、「肠断」，吾不喜之。
《筱园诗话》：李玉溪之「高阁客竞去，小园花乱飞」，马戴之「孤云与归鸟，千里片时间」……佳处不一，皆高格响调，起句之极有力、最得势者，可为后学法式。
《唐诗三百首》：花落则无人相赏，故竟去也（首二句下）。望春留而春自归（「眼穿」句下）。
《唐宋诗举要》：得神在逆折而入（首句下）。何曰：一结无限深情，「得」字意外巧妙。
《义山诗集笺注》：姚培谦说：此因落花而发身世之感也。天下无不散之客，又岂有不落之花？至客散时，乃得谛视此落花情状。三、四句，花落乡在客者。五句，花落之在斟乜者。六句，花落之犹在树者，此正波斯匿王所谓沉思谛观刹那，刹那不得留住者也。人生世间，心为形役，流浪生死，何以异此！只落得有情人一点眼泪耳。', 'center', 1417305454, '57b93743128fe10054cb58ab', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10578, '凉思', NULL, 47, 603, 0, 1, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383450.htm', '', '客去波平槛，蝉休露满枝。
永怀当此节，倚立自移时。
北斗兼春远，南陵寓使迟。
天涯占梦数，疑误有新知。', '此诗是一首因时光流逝，对凉秋而怀旧的作品。流露作者盼望友人来信，却大失所望之心情，最终竟怀疑对方已有新交，唯恐为人所弃。诗人在凉秋中回忆友人离去的情景，寄托了无限的思念，也暗喻出自已难展抱负的愁怀。全诗用词简练，意蕴温婉，清新淡雅，情深意长。', '凄凉的思绪。唐李贺《昌谷诗》：“鸿珑数铃响，羁臣发凉思。”
槛（jiàn）：栏杆。
蝉休：蝉声停止，指夜深。
永怀：即长想，长久思念。《诗经·周南·卷耳》：“我姑酌彼金罍，维以不永怀。”此节：此刻。
倚立：意谓今日重立槛前，时节已由春而秋。移时：历时、经时。即时间流过，经历一段时间。《后汉书·吴祐传》：“祐越坛共小史雍丘、黄真欢语移时，与结友而别。”
北斗：即北斗星，因为它屹立天极，众星围绕转动，古人常用来比喻君主，这里指皇帝驻居的京城长安。兼春：即兼年，两年。
南陵：今安徽繁昌县，唐时属宣州。此指作者怀客之地。寓使：指传书的使者。寓：寄，托。
占梦：占卜梦境，卜度梦的吉凶。《诗经·小雅·正月》：“召彼故老，讯之占梦。”郑玄笺：“召之不问政事，但问占梦，不尚道德而信徵祥之甚。”数：屡次。
新知：新结交的知己。语本《楚辞·九歌·少司命》：“悲莫悲兮生别离，乐莫乐兮新相知。”', '当初你离去时春潮漫平栏杆；如今秋蝉不鸣露水挂满树枝。
我永远怀念当时那美好时节；今日重倚槛前不觉时光流逝。
你北方的住处像春天般遥远；我在南陵嫌送信人来得太迟。
远隔天涯我屡次占卜着美梦；疑心你有新交而把老友忘记。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92e103572034f659e5c1", "shortContent": "这是写诗人初秋夜晚的一段愁思。\n首联写愁思产生的环境。访客已经离去，池水涨平了栏槛，知了停止噪鸣，清露挂满树枝，好一幅水亭秋夜的清凉图景！但是，诗句的胜处不光在于写景真切，它还细致地传达出诗人心理感受的微妙变化。如“客去”与“波平槛”，本来是互不相关的两件事，为什么要连在一起叙述呢？细细推敲，大有道理。大凡人在热闹之中，是不会去注意夜晚池塘涨水这类细节的。只有当客人告退、孤身独坐时，才会突然发现：...", "authors": ["陈伯海"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d8477683d1933014fdc", "shortContent": "本篇是义山奉使至南郡时的作品。《樊南文集补编·为荥阳公上宣州裴尚书启》云：“李处士艺术深博，议论纵横，敢曰贤于仲尼，且虑失之子羽。云于江沔，要有淹留，便假以节巡，托之好币，十一月初离此讫。”大中元年十月，义山奉郑亚之命至南郡（今湖北江陵县），李处士与其同行。十一月初，李处士往宣州谒见裴休尚书，义山代为《上裴尚书启》。江陵别后，故有凉思之作。首联谓客散后夜深人静，槛外波平，看去江波似与栏杆齐平；蝉声...", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f09344", "shortContent": "这是一首以女性口吻写的闺怨诗。题目“凉思”两字点明了思念的季节——正值凉风初起之时，又抒由思念引发的凄凉心情。初念此题目，凉意已从肌肤渗出。诗以“思”字贯穿全诗：首联写思的起因，颔联写思的时间之长，颈联与尾联均写思的具体内容。\n\n首联，客人已经离去，剩下女主角一人伫立门前水亭栏杆，远眺池水涨起，几与栏杆一般高；白日的蝉已经停止鸣叫，此刻清露挂满树枝。此联写景，选取一池秋水、高树鸣蝉、月下清露这些物...", "authors": ["林妙芝"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707a73206168b2e02226", "shortContent": "这是一首以女性口吻写的闺怨诗。题目“凉思”两字点明了思念的季节：正值凉风初起之时；又抒因思念而心境凄凉。初初念此题目，凉意已从肌肤渗出。诗以“思”字贯穿全诗。\n\n首联写思的起因；颔联写思的时间之长；颈联与尾联均写思的具体内容。\n\n首联，客人已经离去，剩下女主角一人伫立门前水亭栏杆，远眺池水涨起，几与栏杆一般高；白日的蝉已经停止鸣叫，此刻清露挂满树枝。此联写景，选取一池秋水、高树鸣蝉、月下清露这些物...", "authors": ["林妙芝"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64638b615e6bb82b8cbf96b7", "shortContent": "这是写诗人初秋夜晚的一段愁思。\n\n首联写愁思产生的环境。访客已经离去，池水涨平了栏槛，知了停止噪鸣，清露挂满树枝，好一幅水亭秋夜的清凉图景！但是，诗句的胜处不光在于写景真切，它还细致地传达出诗人心理感受的微妙变化。如“客去”与“波平槛”，本来是互不相关的两件事，为什么要连在一起叙述呢？细细推敲，大有道理。大凡人在热闹之中，是不会去注意夜晚池塘涨水这类细节的。只有当客人告退、孤身独坐时，才会突然发现...", "authors": ["陈伯海"], "pressName": "上海辞书出版社"}]', '沈厚塽《李义山诗集辑评》：朱彝尊曰；首二句“凉”，下六句“思”。何焯曰：“思”字入神（“倚立”句下）。又曰：落句衬出“思”字，意足。纪昀：起四句一气涌出，气格殊高。五句在可解不可解之间，然其妙可思。结句承“寓使迟”来，言家在天涯，不知留滞之故，几疑别有新知也。
何焯《义门读书记》：起联写水亭秋夜，读之亦觉凉气侵肌。
蘅塘退士《唐诗三百首》：“凉”字分四层。', 'center', 1417305560, '57b967aa165abd0054c37400', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10579, '北青萝', NULL, 431, 603, 2, 1, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383460/15344239.htm', '', '残阳西入崦，茅屋访孤僧。
落叶人何在，寒云路几层。
独敲初夜磬，闲倚一枝藤。
世界微尘里，吾宁爱与憎。', '首联写诗人寻访僧人之事和点出造访的时间，诗人希望与僧人精神交流获得启示，以解除自身的苦恼。颌联写诗人寻访所经之路程、所见之景物，写景而兼记行踪，言简意丰，蕴藏极富；颈联写诗人黄昏时才寻到僧人，以精炼的笔墨描绘了僧人的简静生活；末联写抒发感慨，忽悟禅理之意，今后不再纠缠爱憎，以淡泊之怀面对仕途荣辱。
此诗语言凝炼，富于蕴藏，层次清晰。诗中诗人访的是孤僧，以“独敲”、“一枝”、“人何在”等点染出“孤”字，表现了诗人在苦闷彷徨之时，不满现实，希望从佛教思想中得到解脱的情绪。', '青萝：一种攀生在石崖上的植物，此处代指山。南朝江淹《江上之山赋》：“挂青萝兮万仞，竖丹石兮百重。”
崦（yān）：即“崦嵫（zī）”，山名，在甘肃。古时常用来指太阳落山的地方。《山海经》载：鸟鼠同穴山西南有山名崦嵫，日所入处。
初夜：黄昏。
磬（qìng）：古代打击乐器，形状像曲尺，用玉、石制成，可悬挂。佛寺中使用的一种钵状物，用铜铁铸成，既可作念经时的打击乐器，亦可敲响集合寺众。
“世界”句：语本《法华经》：“书写三千大千世界事，全在微生中。”意思是大千世界俱是微生，我还谈什么爱和恨呢？《楞严经》说：“人在世间，直微尘耳。何必拘于憎爱而苦此心也！”宁：为什么。', '夕阳落入崦嵫山，我去茅屋里探访孤独的僧人。
满地落叶，僧人何在？遍山寒云，山路要走多久？
初夜时分只听他独自敲磬，闲适中靠着一枝青藤。
大千世界都在微尘里，我为什么要有喜爱和憎恨？', '[{"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d827ccdb86c49f28e87", "shortContent": "此日暮访僧感怀之作。前半谓夕阳在山，访茅屋之孤僧。落叶满地，寒云四起，山路迢遥，心中尚不知孤僧在否？后半谓既见之后的情景。入夜时，他独自击磬焚香，既毕，倚杖与我闲聊。他说，大千世界渺若微尘，我们岂以爱憎自扰耶？全篇高妙超脱，五六句尤其古雅，结句亦自然。", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f09345", "shortContent": "此诗写诗人在北青萝访孤僧一事，属于叙事诗。首联交代时间、地点和事件：西边一道残阳斜斜照在崦嵫山上，色彩温暖但乏而无力。诗人拾级而上，特意来拜访山上得道高僧。寺庙深藏于山林之间，诗人停于一茅屋之前，久叩柴门却不见有人相迎。\n\n颔联借景抒情，诗人伫立茅屋之前，不见孤僧踪影，只见落叶翩然；又见远处天边云层凝固冷寂，山路曲折盘旋。此联写寻隐者不遇，情景交融，气氛凄凉冷寂，悄怆幽邃，暗隐了孤凄与冷寂，失落与...", "authors": ["林妙芝"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707a73206168b2e02229", "shortContent": "此诗写诗人在北青萝访孤僧一事，属于叙事诗。首联交代时间、地点和事件：西边一道残阳斜斜照在崦嵫山上，色彩温暖但乏而无力。诗人拾级而上，特意来拜访山上得道高僧。寺庙深藏于山林之间，诗人停于一茅屋之前，久叩柴门却不见有人相迎。\n\n颔联借景抒情，诗人伫立茅屋之前，不见孤僧踪影，只见落叶翩然；又见远处天边云层凝固冷寂，山路曲折盘旋几处弯。此联写寻隐者不遇，情景交融，气氛凄凉冷寂，悄怆幽邃，暗隐了孤凄与冷寂，...", "authors": ["林妙芝"], "pressName": "崇文书局"}]', '', 'center', 1417392374, '57b8ee240a2b58005c91c99e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10580, '送人东游', NULL, 105, 394, 2, 1, '温庭筠', NULL, 10069, '57b93da179bc44005ba0a318', '唐', 'shi', '诗', 'http://baike.baidu.com/view/341656.htm', '', '荒戍落黄叶，浩然离故关。
高风汉阳渡，初日郢门山。
江上几人在，天涯孤棹还。
何当重相见，樽酒慰离颜。', '此诗写送别，“浩然离故关”一句确立了诗的基调，由于离人意气昂扬，就使得黄叶飘零、天涯孤棹等景色显得悲凉而不低沉，因而慷慨动人。诗的最后一句透露出依依惜别的情怀，虽是在秋季送别，却无悲秋的凄楚。全诗意境雄浑壮阔，慷慨悲凉，有秋景而无伤秋之情，与人别而不纵悲情，毫无作者“花间词派”婉约纤丽的文风。', '荒戍：荒废的边塞营垒。
浩然：意气充沛、豪迈坚定的样子，指远游之志甚坚。《孟子·公孙丑下》：“予然后浩然有归志。”
汉阳渡：湖北汉阳的长江渡口。
郢门山：位于今湖北宜都县西北长江南岸，即荆门山。
江：指长江。
几人：犹言谁人。
孤棹：孤舟。棹，原指划船的一种工具，后引申为船。
何当：何时。
樽酒：犹杯酒。樽，古代盛酒的器具。
离颜：离别的愁颜。', '荒弃的营垒上黄叶纷纷飘落，心怀壮志你告别了古塞险关。
飒飒秋风将送你到汉阳渡口，初升的太阳会迎你在郢门山。
江东亲友有几人正望眼欲穿，等候着你的孤舟从天涯回还。
什么时候我们才能再次相见，举杯畅饮以抚慰离人的愁颜。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92da7d0ac11454953a54", "shortContent": "诗题为“送人东归”，所送何人不详。看诗中地名都在今湖北省，可知是温庭筠宣宗大中十三年（859）贬随县尉之后、懿宗咸通三年（862）离江陵东下之前的作品，很可能作于江陵，诗人时年五十左右。\n关于本诗的发端，清人沈德潜曰：“起调最高。”（《唐诗别裁集》）试想：地点既傍荒凉冷落的古堡，时令又值落叶萧萧的寒秋，此时此地送友人远行，那别绪离愁，将何以堪！然而出人意料，接下去诗思却陡然一振：“浩然离故关”——...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f09346", "shortContent": "这是一首送别之作，采用较为近古的五律形式，格调却倾向高古一路，造语浑朴，意境深远。\n\n起句“荒戍落黄叶”即显出苍凉劲直的气象：荒芜的营垒，萧萧的落木，为飒爽的秋色进一步增添了凛冽肃杀的气氛，颇有“悲哉秋之为气也，萧瑟兮草木摇落而变衰”（宋玉《九辩》）的气格。试想在这样萧瑟的环境中送别友人，难免会滋长悲怨惆怅的情绪。然而接下来“浩然离故关”却令人精神一振，友人的远行，竟带着滔滔浩然之气，其胸襟之阔远...", "authors": ["王颖"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270799761253910e90561", "shortContent": "这是一首送别之作，采用较为近古的五律形式，格调亦倾向高古一路，造语浑朴，意境深远。\n\n起句“荒戍落黄叶”即显出苍凉劲直的气象：荒芜的城墙，萧萧的落木，为飒爽的秋色进一步增添了凜冽肃杀的气氛，颇有“悲哉秋之为气也，萧瑟兮草木摇落而变衰”（宋玉《九辩》）的气格，试想在这样萧瑟的环境中送别友人，难免会滋长悲怨惆怅的情绪，然而接下来“浩然离故关”却令人精神一振，友人的远行，竟带着滔滔浩然之气，其胸襟之阔远...", "authors": ["王颖"], "pressName": "崇文书局"}]', '王士禛《带经堂诗话》：律诗贵工于发端，承接二句尤贵得势，如懒残履衡岳之石，旋转而下，此非有伯昏无人之气者不能也。如“万壑树参天，千山响杜鹃”，下即云“山中一夜雨，树杪百重泉”……“古戍落黄叶，浩然离故关”，下云“高风汉阳渡，初日郢门山”……此皆转石万仞手也。
沈德潜《唐诗别裁》：贾长江“秋风吹渭水，落叶满长安”，温飞卿“占戍落黄叶，浩然离故关”，卑靡时乃有此格。后唯马戴亦间有之。（《说诗晬语》）又曰：起调最高。
黄叔灿《唐诗笺注》：首联领起，通篇有势，中四语结撰亦称。如此写离情，直觉有浩然之气。
宋宗元《网师园唐诗笺》：中晚罕此起笔，竟体亦极浑脱（首四句下）。
周咏棠《唐贤小三昧集续集》：高朗明健，居然盛唐格调。晚唐五言似此者，亿不得一。
纪昀《删正二冯先生评阅才调集》：苍苍莽莽，高调入云。温、李有此笔力，故能熔铸一切浓艳之词，无堆排之迹。
蘅塘退士《唐诗三百首》：直逼初、盛。
管世铭《读雪山房唐诗序例》：温庭筠“古戍落黄叶”，刘绮庄“桂楫木兰舟”，韦庄“清瑟怨遥夜”，便觉开、宝去人不远。可见文章虽限于时代，豪杰之士终不为风气所囿也。', 'center', 1417392483, '57b8e8f11532bc005b9a7fc4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10581, '灞上秋居', NULL, 202, 173, 2, 4, '马戴', NULL, 10136, '57ba27a25bbb500063f87848', '唐', 'shi', '诗', 'http://baike.baidu.com/view/52229.htm', '', '灞原风雨定，晚见雁行频。
落叶他乡树，寒灯独夜人。
空园白露滴，孤壁野僧邻。
寄卧郊扉久，何年致此身。', '此诗写作者客居灞上而感秋来寂寞，情景萧瑟。首联写灞原上空萧森的秋气，秋风秋雨已定，雁群频飞；颔联写在他乡异土见落叶时的酸楚和寒夜独处时的悲凄况味；颈联写秋夜寂静，卧听滴露，孤单无依，与僧为邻，更进一步写出孤独的心境；尾联抒发诗人的感慨，表达怀才不遇，进身渺茫的悲愤之情。全诗意境浑厚，情景交融，写景朴实无华，写情真切感人。', '灞上：古代地名，也称“‘霸上”，在今陕西省西安市东，因地处灞陵高原而得名，唐代求功名的人多寄居此处。
灞（bà）原：即灞上。
雁行（háng）：鸿雁飞时的整齐行列。南朝梁简文帝《杂句从军行》：“逦迤观鹅翼，参差睹雁行。”频：连续不断。
他乡：异乡，家乡以外的地方。《乐府诗集·相和歌辞十三·饮马长城窟行》：“梦见在我傍，忽觉在他乡。”
寒灯：寒夜里的孤灯。多以形容孤寂、凄凉的环境。南朝齐谢朓《冬绪羁怀示萧咨议虞田曹刘江二常侍》诗：“寒灯耿宵梦，清镜悲晓发。”独夜：一人独处之夜。汉王粲《七哀诗》之二：“独夜不能寐，摄衣起抚琴。”
白露：秋天的露水。《诗经·秦风·蒹葭》：“蒹葭苍苍，白露为霜。”
野僧：山野僧人。唐张籍《赠王秘书》诗：“身屈祗闻词客说，家贫多见野僧招。”
寄卧：寄居。郊扉：郊居。指长安的郊外。扉：门。这里指屋舍。南朝齐谢朓《休沐重还道中》诗：“岁华春有酒，初服偃郊扉。”
何门：一作“何年”。致此身：意即以此身为国君报效尽力。致：达到，实现。', '灞原上已经风停雨定，傍晚时只见雁行频频。
落叶纷纷这是异乡树，寒灯闪闪独照不眠人。
寂静的空园白露滴滴，隔壁野僧是我的近邻。
寄居郊外柴门已很久，不知何门能进用此身？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92e3c6e67846a920edb3", "shortContent": "此诗纯写闭门寥落之感。整首诗篇好似一幅形象鲜明、艺术精湛的画卷。\n我们把画卷慢慢地打开，首先映入眼帘的是灞原上空萧森的秋气：撩人愁思的秋风秋雨直到傍晚才停歇下来，在暮霭沉沉的天际，接连不断的雁群自北向南急急飞过。连番的风雨，雁儿们已经耽误了不少行程，好不容易风停雨歇，得赶在天黑之前找到一个宿处。这里用一个“频”字，既表明了雁群之多，又使人联想起雁儿们急于投宿的惶急之状。古人每见雁回，易惹乡思。\n下...", "authors": ["王松"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f09347", "shortContent": "晚唐诗人中，马戴以善五律著称，严羽称其“在晚唐诸人之上”（《沧浪诗话》），翁方纲则誉之“直可与盛唐诸贤侪伍”（《石洲诗话》）。此诗写诗人客居灞上而感秋来萧瑟，抒发羁旅之思和失意之慨，为马戴五律诗作中的名篇。\n\n首联写秋天傍晚灞原之上的衰飒萧条气象。撩人的秋风秋雨直到傍晚才停歇下来，放眼眺望，天上的大雁成群结队地南去不停。所谓“悲哉秋之为气也，萧瑟兮草木摇落而变衰”（宋玉《九辩》），此处写秋风秋雨，...", "authors": ["乐云"], "pressName": "崇文书局"}]', '许学夷《诗源辨体》：语出贾岛。
范大士《历代诗发》：秀洁。
李怀民《重订中晚唐诗主客图》：意兴孤僻，纯是贾想。极写荒僻（“空园”二句下）。结应在此（末二句下）。
蘅塘退士《唐诗三百首》：二句十层（“落叶”二句下）。
俞陛云《诗境浅说》：此诗纯写闭门寥落之感。首句即言灞原风雨，秋气可悲。迨雨过而见雁行不断，唯其无聊，久望长天，故雁飞频见，明人诗所谓“不是关山万里客，那识此声能断肠”也。三四言落叶而在他乡，寒灯而在独夜，愈见凄寂之况，与“乱山残雪夜，孤烛异乡人”之句相似；凡用两层夹写法，则气厚而力透，不仅用之写客感也。五句言露滴似闻微响，以见其园之空寂；六句言为邻仅有野僧，以见其壁之孤峙。末句言士不遇本意，叹期望之虚悬，岂诗人例合穷耶！', 'center', 1417392688, '57b8a4080a2b58005c9108d9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10582, '楚江怀古', NULL, 219, 173, 3, 1, '马戴', NULL, 10136, '57ba27a25bbb500063f87848', '唐', 'shi', '诗', 'http://baike.baidu.com/view/240747.htm', '', '露气寒光集，微阳下楚丘。
猿啼洞庭树，人在木兰舟。
广泽生明月，苍山夹乱流。
云中君不见，竟夕自悲秋。', '唐宣宗大中初年，诗人由山西太原幕府掌书记。被贬为龙阳尉，自江北来江南，行于洞庭湖畔，触景生情，追慕先贤，感伤身世，而写下了《楚江怀古》三首，这是第一首。
第一首虽题“怀古”，却泛咏洞庭景致。诗人履楚江而临晚秋，时值晚唐，不免“发思古之幽情”，感伤自身不遇。首联先点明薄暮时分；颔联上句承接“暮”字，下句才点出人来，颈联就山水两方面写夜景，“夹”字犹见凝练；尾联才写出“怀古”的主旨，为后两首开题，而以悲愁作结。
全诗风格清丽婉约，感情细腻低徊。李元洛评曰：“在艺术上清超而不质实，深微而不粗放，词华淡远而不艳抹浓妆，含蓄蕴籍而不直露奔迸。”', '微阳：落日的残照。楚丘：泛指湖南的山岭。
木兰舟：船的美称。典出《述异记》：“木兰洲在浔阳江中，多木兰树，七里洲中有鲁班刻木兰为舟。”
广泽：指青草湖，周长二百六十五里，与洞庭湖相连，是古代云梦泽的遗迹。
云中君：云神。屈原《九歌》有《云中君》篇，此处亦兼指屈原。
竟夕：整个晚上。', '雾露团团凝聚寒气侵人，夕阳已落下楚地的山丘。
猿在洞庭湖畔树上啼叫，人乘木兰舟在湖中泛游。
明月从广漠的湖上升起，两岸青山夹着滔滔乱流。
云中仙君怎么都不见了？我竟通宵达旦独自悲秋。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92e30f8fda55650557c3", "shortContent": "唐宣宗大中初年，原任山西太原幕府掌书记的马戴，因直言被贬为龙阳（今湖南汉寿）尉。从北方来到江南，徘徊在洞庭湖畔和湘江之滨，触景生情，追慕前贤，感怀身世，写下了《楚江怀古》五律三章。这是其中第一篇。\n近人俞陛云在《诗境浅说》中说：“唐人五律，多高华雄厚之作，此诗以清微婉约出之，如仙人乘莲叶轻舟，凌波而下也。”他以“清微婉约”四字标举此诗的艺术风格，确实别具只眼。\n秋风摇落的薄暮时分，江上晚雾初生，楚...", "authors": ["李元洛"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9ae60d368fd3d12a", "shortContent": "唐宣宗大中初年，原任山西太原幕府掌书记的马戴，因直言被贬为龙阳（今湖南汉寿）尉。从北方来到江南，徘徊在洞庭湖畔和湘江之滨，触景生情，追慕前贤，感怀身世，写下了《楚江怀古》五律三章。这是其中第一篇。\n\n近人俞陛云在《诗境浅说》中说：“唐人五律，多高华雄厚之作，此诗以清微婉约出之，如仙人乘莲叶轻舟，凌波而下也。”他以“清微婉约”四字标举此诗的艺术风格，确实别具只眼。\n\n秋风摇落的薄暮时分，江上晚雾初生...", "authors": ["李元洛"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f09348", "shortContent": "唐宣宗大中（847—859）初年，马戴被贬龙阳（今湖南汉寿）尉，途经洞庭湖畔和湘江之滨，诗人触景生情，追慕先贤，感怀身世，写下《楚江怀古》组诗三首，此诗为第一首。全诗借景抒怀，在缅怀屈原的高洁情怀时，亦传递出感时伤世、知音难遇之人生感叹。\n \n首联以大开大阖之笔，总写洞庭湖的夕阳美景。夜幕降临，寒气初露，落日的余晖洒在湖面上，泛起万点粼光。一“集”字，一“下”字，将洞庭湖之烟波浩渺与湖光山色渲染得...", "authors": ["乐云"], "pressName": "崇文书局"}]', '《升庵诗话》：前联虽柳恽不是过也，晚唐有此，亦希声乎！严羽卿称戴诗为晚唐第一，信非溢美。
《艺苑卮言》：权德舆、武元衡、马戴、刘沧五言，皆铁中铮铮者。“猿啼洞庭树，人在木兰舟”，真不减柳吴兴；《回乐峰》一章，何必王龙标、李供奉！
《诗薮》：晚唐“猿啼洞庭树，人在木兰舟”，宋人“雨砌堕危芳，风轩纳絮绵”，皆句格之近六朝。
《唐诗归》：谭云：“光集”妙，承“气”字尤妙（首句下）。钟云：二语以连续为情景（“猿啼”二句下）。
《唐诗评选》：神情光气何殊王子安？固非高廷礼辈所知。“广泽生明月”较之“乾坤日夜浮”，孰正孰变，孰雅孰俗，必有知者。“云中君不降”五字一直下语，而曲折已尽，可谓笔外有墨气，奇绝。
《五朝诗善鸣集》：读虞臣中两联，赞叹不足，唯令人顶礼。我欲如李洞之铸浪仙。
《唐诗摘钞》：尾联见意。三、四二语，真脍炙千古。韦庄亦有“鸟栖彭蠡树，月上建昌船”，句法与此同，何以不为人所称？此以景事衬对，句中便含有悲秋意故也；韦句地名亦不佳。……结见怀古之意。
《唐律消夏录》：“广泽”二句只写闲景，不曾含蓄得怀古意，故结句便觉直率。
《渔洋诗话》：尝见皇甫少玄、百泉兄弟论诗，五言以“猿啼洞庭树，人在木兰舟”为极则。
《唐诗成法》：三四王渔洋以为诗之极致。五六作“梦泽”、“巫山”方切，但与“楚丘”、“洞庭”用地名太多，故浑言“广泽”、“苍山”耳。有议其不切者，非。
《唐诗笺要》：诗至会昌，气最薄而情最幻。薄极乃幻，幻则无复能厚之理矣。此间关系气运甚微，恐主之者非人事也。
《唐贤小三昧续集》：次联下字令人揽结不尽，皇甫兄弟谓此为五言极则，洵具眼也。
《重订中晚唐诗主客图》：次联意景较宽，声响较大，不知者认为初盛，胜贾、喻也《“猿啼”二句下）。
《唐诗近体》：二句连读，乃见标格（“猿啼”二句下）。怀古（末二句下）。
《问花楼诗话》：《楚江怀古》一首，柳吴兴无以过之。严羽推为晚唐之冠，信哉！', 'center', 1417392856, '57b92039a633bd00665e590d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10583, '书边事', NULL, 70, 168, 1, 1, '张乔', NULL, 10137, '57c6c37379bc440063fbc46f', '唐', 'shi', '诗', 'http://baike.baidu.com/view/356530.htm', '', '调角断清秋，征人倚戍楼。
春风对青冢，白日落梁州。
大漠无兵阻，穷边有客游。
蕃情似此水，长愿向南流。', '此诗是写作者游历边塞的所见所闻，抒发了诗人美好的愿望。首联写边塞军旅生活和安宁，征人安闲无事；颔联虚写昭君墓秋来依然春风吹拂，梁州边城一派日丽平和，再次伸述民族团结，边防安定；颈联极言广漠边塞无蕃兵阻扰，游客到这里观光，反复渲染和平景象。尾联抒写作者民族团结的心愿。全诗描写了宁静的边塞，一片没有战事安宁的景象，意境高阔而深远，气韵直贯而又抑扬顿挫，写景抒情，别具一格。', '调角：犹吹角。角是古代军中乐器，相当于军号。断：尽或占尽的意思。
戍楼：防守的城楼。
春风：指和煦凉爽的秋风。青冢：指西汉王昭君的坟墓。
白日：灿烂的阳光。梁州：当时指凉州。唐梁州为今陕西南郑一带，非边地，而乐曲《凉州》也有作《梁州》的。凉州，地处今甘肃省境内，曾一度被吐蕃所占。
大漠：一作“大汉”。
穷边：绝远的边地。
蕃：指吐蕃。情：心情。似：一作“如”。此水：不确指，可能指黄河。', '清秋的边地号角划断宁静，征人悠闲地倚着哨楼远望。
阵阵和风吹拂着昭君坟墓，边城梁州普照着和煦阳光。
浩瀚沙漠看不见军兵阻扰，边疆塞外也常有客人游赏。
蕃人的情意好像这条流水，愿永久归附中原流向南方。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92e82e6a6b501f95c5b1", "shortContent": "唐朝自肃宗以后，河西、陇右一带长期被吐蕃所占。宣宗大中五年（851）沙州民众起义首领张议潮，在出兵收取瓜、伊、西、甘、肃、兰、鄯、河、岷、廓十州后，派遣其兄张议潭奉沙、瓜等十一州地图入朝，宣宗因以张议潮为归义军节度使；大中十一年，吐蕃将尚延心以河湟降唐，其地又全归唐朝所有。自此，唐代西部边塞地区才又出现了一度和平安定的局面。本诗的写作背景大约是在上述情况之后。\n诗篇一展开，呈现在读者面前的就是一幅...", "authors": ["陶光友"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f09349", "shortContent": "此诗为张乔游历边塞时所作，主要描写边塞安宁平静、没有战事的景象，从中亦表达了诗人的美好愿望。\n\n首联描写边塞的军旅生活。边塞是民族矛盾最为集中的地方，故历来都属于军事重地，然而诗人却在这里描绘出另外一番景致。在这深秋时分，悠扬嘹亮的号角声忽然响起，声音在空中久久回荡，而征边的人则倚在戍楼上仿佛正在仔细倾听。这两句中，“断”字和“倚”字用得极妙。\n“断”，有划破、划开的意思。悠扬悦耳的号角竟然划破秋...", "authors": ["余春丽"], "pressName": "崇文书局"}]', '黄生：前后两截格。凡五言律，首尾相称、位置停匀者，正调也。前半警策，后半更不用力，如此诗及岑参《寄严许二山人》诗者，变调也。后半亦非不用力，但声势气局为前段所摄，只以平平衬带过去耳。（《唐诗矩》）
俞陛云：此诗高视阔步而出，一气直书，而仍有顿挫。亦高格之一也。前半首言正秋寒绝塞、角声横断之时，登戍楼而凭眺：近望则阴山之麓、明妃香冢、青草依然；远望则白日西沈、云天低尽处，约略是甘凉大野。五六乃转笔写登楼之客，因大漠销兵，行人无阻，乃能作出塞壮游。末句愿蕃人向化，如水向南流，与“不作边城将，谁知恩遇深”同一诗人忠爱之思。（《诗境浅说》）', 'center', 1417393161, '57b9550f7db2a2005429888a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10599, '蜀相', NULL, 519, 1416, 2, 10, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/4546.htm', '', '丞相祠堂何处寻？锦官城外柏森森。
映阶碧草自春色，隔叶黄鹂空好音。
三顾频烦天下计，两朝开济老臣心。
出师未捷身先死，长使英雄泪满襟。', '此诗是唐代诗人杜甫定居成都草堂後，翌年游览武侯祠时创作的一首咏史怀古诗，表达了诗人对蜀汉丞相诸葛亮雄才大略、辅佐两朝、忠心报国的称颂以及对他出师未捷而身死的惋惜之情。诗中既有尊蜀正统的观念，又有才困时艰的感慨，字里行间寄寓感物思人的情怀。这首七律章法曲折宛转，自然紧凑。前两联记行写景，洒洒脱脱；後两联议事论人，忽变沉郁。全篇由景到人，由寻找瞻仰到追述回顾，由感叹缅怀到泪流满襟，顿挫豪迈，几度层折。全诗所怀者大，所感者深，雄浑悲壮，沉郁顿挫，具有震撼人心的巨大力量。', '蜀相：三国蜀汉丞相，指诸葛武侯。诗题下有注：诸葛亮祠在昭烈庙西。
丞相祠堂：即诸葛武侯祠，在今成都市武侯区，晋李雄初建。
锦官城：成都的别名。
柏（bǎi）森森：柏树茂盛繁密的样子。
映阶碧草自春色，隔叶黄鹂空好（hǎo）音：这两句写祠内景物。杜甫极推崇诸葛亮，他此来并非为了赏玩美景，「自」「空」二字含情。是说碧草映阶，不过自为春色；黄鹂隔叶，亦不过空作好音，他并无心赏玩、倾听。因为他所景仰的人物已不可得见。空：白白的。
三顾频烦天下计：意思是刘备为统一天下而三顾茅庐，问计于诸葛亮。这是在赞美在对策中所表现的天才预见。频烦，犹「频繁」，多次。
两朝开济：指诸葛亮辅助刘备开创帝业，後又辅佐刘禅。两朝：刘备、刘禅父子两朝。开，开创；济，扶助。
「出师未捷身先死，长使英雄泪满襟（jīn）」句：出师还没有取得最後的胜利就先去世了，常使後世的英雄泪满衣襟。指诸葛亮多次出师伐魏，未能取胜，至蜀建兴十二年（西元二三四年）卒于五丈原（今陕西岐山东南）军中。出师，出兵。', '诸葛丞相的祠堂去哪里寻找？锦官城外翠柏长得郁郁苍苍。
碧草映照石阶自有一片春色，黄鹂在密叶间空有美妙歌声。
当年先主屡次向您求教大计，辅佐先主开国扶助后主继业。
可惜您却出师征战病死军中，长使古今英雄感慨泪湿衣襟。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ab03048e64fbd913f4", "shortContent": "题曰“蜀相”，而不曰“诸葛祠”，可知老杜此诗意在人而不在祠。然而诗又分明自祠写起。何也？盖人物千古，莫可亲承；庙貌数楹，临风结想。因武侯祠庙而思蜀相，亦理之必然。但在学诗者，虚实宾主之间，诗笔文情之妙，人则祠乎？祠岂人耶？看他如何着墨，于此玩索，宜有会心。\n开头一句，以问引起。祠堂何处？锦官城外，数里之遥，远远望去，早见翠柏成林，好一片葱葱郁郁，气象不凡——那就是诸葛武侯祠所在了。这首一联，开门见...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a79", "shortContent": "题曰“蜀相”，而不曰“诸葛祠”，可知老杜此诗意在人而不在祠。然而诗又分明自祠写起。何也？盖人物千古，莫可亲承；庙貌数楹，临风结想。因武侯祠庙而思蜀相，亦理之必然。但在学诗者，虚实宾主之间，诗笔文情之妙，人则祠乎？祠岂人耶？看他如何着墨，于此玩索，宜有会心。\n\n开头一句，以问引起。祠堂何处？锦官城外，数里之遥，远远望去，早见翠柏成林，好一片葱葱郁郁，气象不凡——那就是诸葛武侯祠所在了。这首一联，开门...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d1933015206", "shortContent": "唐肃宗上元元年（760）春，经过了四年多漂泊流离生活的老杜，来到了成都西郊的浣花溪畔。在友人的资助下，终于有了一个暂时安居栖身之所——草堂。这里恬静优雅的环境让诗人疲惫的心得以沉淀休憩，那曾经千万遍思量的开济老臣怀抱却不时跳将出来，敲击诗人渐趋平静的心。于是，一个风和日丽的春日里，老杜打点一下行装，带着朝圣般的虔诚，去那锦官城外的武侯祠。但这绝不是一篇记游之作，怀人的心情远甚于游览的兴致，故而诗题...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127067c305cf0801816fc1", "shortContent": "唐肃宗上元元年（760）春，经过了四年多漂泊流离生活的老杜，来到了成都西郊的浣花溪畔，在他人的资助下，终于有了一个暂时安居栖身之所草堂。这里恬静优雅的环境让诗人飘浮疲惫的心得以沉淀休憩，那曾经千万遍思量的开济老臣怀抱却不时跳将出来，敲击诗人渐趋平静的心。于是，一个风和日丽的春日里，老杜打点一下行装，带着朝圣般的虔诚，去那锦官城外的诸葛祠堂。但这绝不是一篇记游之作，怀人的心情远甚于游览的兴致，故而诗...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270d4c26cbf3417f0950d", "shortContent": "唐肃宗上元元年（760）春，经过了四年多漂泊流离生活的老杜，来到了成都西郊的浣花溪畔，在他人的资助下，终于有了一个暂时安居栖身之所——草堂。这里恬静优雅的环境让诗人飘浮疲惫的心得以沉淀休憩，那曾经千万遍思量的开济老臣怀抱却不时跳将出来，敲击诗人渐趋平静的心。于是，一个风和日丽的春日里，老杜打点一下行装，带着朝圣般的虔诚，去那锦官城外的诸葛祠堂。但这绝不是一篇记游之作，怀人的心情远甚于游览的兴致，故...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6465ded37f27182da3593751", "shortContent": "题曰“蜀相”，而不曰“诸葛祠”，可知老杜此诗意在人而不在祠。然而诗又分明自祠写起。何也？盖人物千古，莫可亲承；庙貌数楹，临风结想。因武侯祠庙而思蜀相，亦理之必然。但在学诗者，虚实宾主之间，诗笔文情之妙，人则祠乎？祠岂人耶？看他如何着墨，于此玩索，宜有会心。\n\n开头一句，以问引起。祠堂何处？锦官城外，数里之遥，远远望去，早见翠柏成林，好一片葱葱郁郁，气象不凡——那就是诸葛武侯祠所在了。这首一联，开门...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "646f2ebf5fc8182fe9cafad6", "shortContent": "题曰“蜀相”，而不曰“诸葛祠”，可知老杜此诗意在人而不在祠。然而诗又分明自祠写起。何也？盖人物千古，莫可亲承；庙貌数楹，临风结想。因武侯祠庙而思蜀相，亦理之必然。但在学诗者，虚实宾主之间，诗笔文情之妙，人则祠乎？祠岂人耶？看他如何着墨，于此玩索，宜有会心。\n开头一句，以问引起。祠堂何处？锦官城外，数里之遥，远远望去，早见翠柏成林，好一片葱葱郁郁，气象不凡——那就是诸葛武侯祠所在了。这首一联，开门见...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}]', '《苕溪渔隐丛话》：苕溪渔隐曰：半山老人《题双庙诗》云：「北风吹树急，西日照窗凉。」细详味之，其托意深远，非止咏庙中景物而已……此深得老杜句法。如老杜题蜀相庙诗云：「映阶碧草自春色，隔叶黄鹂空好音。」亦自别托意在其中矣。
《瀛奎律髓》：子美流落剑南，拳拳于武侯不忘。其《咏怀古迹》，于武侯云：「伯仲之间见伊吕，指挥若定失萧曹。」及此诗，皆善颂孔明者。
《唐诗品汇》：刘云：全首如此一字一泪矣。又云：千年遗下此语，使人意伤。
《唐诗援》：起语萧散悲凉，便堪下泪。
《唐诗选脉会通评林》：王安石曰：三、四止咏武侯庙，而托意在其中。董益曰：次联只用一「自」字与「空」字，有无限感怆之意。吴山民曰：次句纪地。三、四纪祠之冷落，「天下计」见其雄略，「老臣心」见其苦衷。结语逗漏宋人议论。
《杜臆》：此与「诸葛大名」一首意正相发……盖不止为诸葛悲之，而千古英雄有才无命者，皆括于此，言有尽而意无穷也。
《唐七律隽》：悲凉慷慨，吊古深情，淋淳于楮墨之间。胡元瑞谓结句滥觞宋人，浅视之矣。
《杜诗解》：三、四，碧草春色，黄鹂好音，入一「自」字、「空」字，便凄清之极。……第七句「未」字、「先」字妙，竟似后曾恢复而老臣未及身见之者，体其心而为言也。当日有未了之事，在今日长留一未了之计、未了之心。
《唐诗摘钞》：后半四句，就公始末以寓感慨，笔力简劲，宋人专学此种，流为议论一派，未免为公累耳。
《唐诗快》：呜呼！诗之感人至此，益信圣人「兴、观，群、怨」之言不妄。
《九家集注杜诗》：赵彦材云：悼之深矣。郭知达云：闵其志不遂也。
《删订唐诗解》：起句率。
《瀛奎律髓汇评》：纪昀：前四句疏疏洒洒，后四句忽变沉郁，魄力绝大。赵熙：沈郁、博大。
《杜诗详注》：「天下计」，见匡时雄略：「老臣心」，见报国苦衷。有此二句之沉挚悲壮，结作痛心酸鼻语，方有精神。宋宗简公归殁时诵此二语，千载英雄有同感也。
《唐诗贯珠》：「森森」二字有精神。
《唐宋诗醇》：老杜入蜀，于孔明三致意焉，其志有在也。诗意豪迈哀顿，具有无数层折，后来匹此，惟李商隐《筹笔驿》耳。世人论此二诗，互有短长，或不置轩轾，其实非有定见。今略而言之，此为谒祠之作，前半用笔甚淡，五六写出孔明身份，七、八转折而下，当时后世，悲感并到，正意注重后半。李诗因地兴感，故将孔明威灵撮入十四字中，写得十分满足，接笔一转，几将气焰扫尽，五、六两层折笔，末仍收归本事，非有神力者不能。二诗局阵各异，工力悉敌，悠悠耳食之论，未足与议也。
《唐诗别裁》：檃括武侯生平，激昂痛快。（「三顾频烦」二句下）。「开济」言开基济美，合二朝言之。
《杜诗镜铨》：邵子湘云：牢壮浑劲，此为七律正宗。自始至终，一生功业心事，只用四语括尽（「三顾频烦」四句下）。俞犀月云：真正痛快激昂，八句诗便抵一篇绝大文字。
《十八家诗钞》：张云：后四句极开阖驰骤、沉郁顿挫之妙，须作一气读，乃得其用意湛至处。
《网师园唐诗笺》：只下「何处」二字，已见祠宇荒芜。「三顾」至尾，沉雄檃括，抱负自见。
《历代诗法》：前四句伤其人之不可见，后四句叹其功之不能成，凭吊最深。
《昭昧詹言》：此亦咏怀古迹。起句叙述点题，三、四写景，后半论议缔情，人所同有，但无其雄杰明卓，及沉痛真至耳。
《读杜心解》：五、六，实拈，句法如兼金铸成，其贴切武侯，亦如熔金浑化……后来武侯庙诗，名作林立，然必枚举一事为句。始信此诗统体浑成，尽空作者。
《闻鹤轩初盛唐近体读本》：陈德公曰：五、六稳尽，结亦洒然。评：三、四写祠堂物色，只着「自」、「空」二句眼于中，便已悲凉欲绝，而肃穆深沈之象，更与荒芜零落者不同。
《历代诗评注读本》：悲壮雄劲，此为七律正宗。
《唐宋诗举要》：吴曰：起严庄凝重，此为正格。然亦自有开阖，不可平直（「丞相祠堂」四句下）。吴曰：顿转作收，用笔提空。故异常得势。', 'center', 1417443472, '57b93410a633bd00665efd4a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10584, '除夜有怀', NULL, 93, 106, 1, 4, '崔涂', NULL, 10138, '57bc49fe2e958a0069458254', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383461.htm', '', '迢递三巴路，羁危万里身。
乱山残雪夜，孤烛异乡人。
渐与骨肉远，转于僮仆亲。
那堪正漂泊，明日岁华新。', '此诗写除夕之夜旅居之感怀。首联即对，起句点地，次句点人，气象阔大；颔联写除夕客居异地的孤独；颈联写亲眷远离，僮仆成了至亲，再烘托“独”字；尾联点出时逢除夕，更不堪漂泊。全诗流露出浓烈的离愁乡思和对羁旅的厌倦情绪。', '除夜有怀：一作「除夜」。
迢（tiáo）递：遥远的样子。
三巴：汉末益州牧刘季玉设「巴郡」、「巴东」、「巴西」三郡，故合称「三巴」，今四川省东部地区，相当今四川嘉陵江和綦江流域以东的大部分地区。後亦多泛指四川。
羁（jī）危：指漂泊于三巴的艰险之地。羁，寄寓异乡；危，艰危困苦。
万里身：此身离家万里之外，路途遥远。
残雪：残馀的积雪。
孤烛：一支烛。这并非实指，而是说自己在这除夕之夜，孤独独照，更感到离家万里的异乡人了。
「孤烛异乡人」句：一作「孤烛异乡春」或「孤独异乡人」。
骨肉：指有血统关系的骨肉亲人。
僮（tóng）：未成年仆人。
亲：亲近。
岁华：年华。', '三巴的道路多么迢远，我走在万里艰危的征程。
乱山上残雪在黑夜里闪光，一支烛火陪伴着我这异乡的人。
离开亲人们已越来越远，和僮仆的感情分外加深。
哪堪漂泊在天涯，又适逢明朝岁华更新。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f0934a", "shortContent": "关于这首诗，自古而今曾有过著作权之争。《全唐诗》中收录此诗，归在孟浩然名下。古代诸多丛书、选本，如《文苑英华》、《唐诗品汇》等，也都定为孟浩然作。然今人李嘉言先生通过校读《全唐诗》，已辨之凿凿，确为崔涂作。\n\n晚唐黄巢之义军攻克潼关，唐僖宗仓皇奔蜀。当时的读书人如崔涂辈，为应举，曾历尽艰辛赴蜀。崔涂这首《除夜有怀》，全称《巴山道中除夜书怀》，当是其羁留蜀中，孑然一身，逢年望乡而作。\n\n这首诗的核心...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707e73206168b2e0223e", "shortContent": "关于这首诗，自古而今曾有过著作权之争。《全唐诗》中收录此诗，归在孟浩然名下。古代诸多丛书、选本，如《文苑英华》、《唐诗品汇》等，也都定为孟浩然作。然今人李嘉言先生通过校读《全唐诗》，已辨之凿凿，确为崔涂作。\n\n晚唐黄巢之义军攻克潼关，唐僖宗仓皇奔蜀。当时的读书人如崔涂辈，为应举，曾历尽艰辛赴蜀。崔涂这首《除夜有怀》，全称《巴山道中除夜书怀》，当是其羁留蜀中，孑然一身，逢年望乡而作。\n\n这首诗的核心...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312716573206168b2e02308", "shortContent": "关于这首诗，自古而今曾有过著作权之争。《全唐诗》中收录此诗，归在孟浩然名下。古代诸多丛书、选本，如《文苑英华》《唐诗品汇》等，也都定为孟浩然作。然今人李嘉言先生通过校读《全唐诗》，已辨之凿凿，确为崔涂作。\n晚唐黄巢之义军攻克潼关，唐僖宗仓皇奔蜀。当时的读书人如崔涂辈，为应举，曾历尽艰辛赴蜀。崔涂这首《除夜有怀》，全称《巴山道中除夜书怀》，当是其羁留蜀中，孑然一身，逢年望乡而作。\n这首诗的核心皆围绕...", "authors": ["刘晓亮"], "pressName": "崇文书局"}]', '', 'center', 1417393323, '57b270378ac247005f1be56f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10585, '孤雁', NULL, 50, 106, 2, 1, '崔涂', NULL, 10138, '57bc49fe2e958a0069458254', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383462/5087464.htm', '', '几行归塞尽，念尔独何之。
暮雨相呼失，寒塘欲下迟。
渚云低暗度，关月冷相随。
未必逢矰缴，孤飞自可疑。', '这是一首咏孤雁的诗，作者借此以喻自己孤栖忧虑的羁旅之情。一联写同伴归尽，唯尔独去，写“离群”切题。二联写孤雁神态，先写失群原因，再写失群后的仓皇。三联写失群之苦楚。尽管振羽奋飞，仍然是只影无依，凄凉寂寞。四联写疑虑受箭丧生，表达诗人的良好愿望和矛盾心情。今人徐培均以为此诗“字字珠玑，没有一处是闲笔；而且余音袅袅，令人回味无穷，可称五律诗中的上品。”', '几行（háng）：几排（大雁）。归塞尽：全部回到塞上。归，回。塞，边塞。尽，完。
“念尔”句：不知大雁独自飞向哪里。念，惦记，想。尔，你。独，独自。何之，倒装结构，到哪里。之，往，去。
暮：傍晚。失：失群。
寒塘：寒冷的池塘。
渚（zhǔ）：水中的小洲。度：度过，飞越。
关月：指关塞上的月亮。
矰缴（zēngzhuó）：猎取飞鸟的工具。缴，即在短箭上的丝绳。
孤：独自。', '几行归雁消失在遥远的塞外，不知你形单影只要往何处飞？
暮雨中呼唤同伴已失去联系，想要落下寒塘却只畏惧迟疑。
沙洲上层云低垂慢慢地穿过，只有关山冷月与你紧紧相随。
虽说不一定会遇到强弓暗箭，独自奋飞难免让人疑虑凝眉。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ed0ce818559d058a62", "shortContent": "这首诗题名《孤雁》，全篇皆实赋孤雁，“诗眼”就是一个“孤”字。一个“孤”字将全诗的神韵、意境凝聚在一起，浑然天成。\n为了突出孤雁，首先要写出“离群”这个背景。所以诗人一开头便说：“几行归塞尽，念尔独何之？”作者本是江南人，一生中常在巴、蜀、湘、鄂、秦、陇一带作客，多天涯羁旅之思。此刻想是站在驿楼上，极目远望：只见天穹之下，几行鸿雁，展翅飞行，向北而去。渐渐地，群雁不见了，只留下一只孤雁，在低空盘旋...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389af4797a92d5e4fd923", "shortContent": "这首诗题名《孤雁》，全篇皆实赋孤雁，“诗眼”就是一个“孤”字。一个“孤”字将全诗的神韵、意境凝聚在一起，浑然天成。\n\n为了突出孤雁，首先要写出“离群”这个背景。所以诗人一开头便说：“几行归塞尽，念尔独何之？”作者本是江南人，一生中常在巴、蜀、湘、鄂、秦、陇一带作客，多天涯羁旅之思。此刻想是站在驿楼上，极目远望：只见天穹之下，几行鸿雁，展翅飞行，向北而去。渐渐地，群雁不见了，只留下一只孤雁，在低空盘...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f0934b", "shortContent": "在唐代的众多咏雁诗中，杜甫和崔涂的两首《孤雁》诗一直倍受后世推崇。二诗不但描写“孤”字入神，而且成功地将孤雁和诗人自己的形象融合在一起，以至于千年之后的读者仍能够通过吟咏其诗，想见其人。\n\n首联即描述此雁的孤单失群，点明题中的“孤”字。“几行归塞尽，念尔独何之？”两句先以“几行”和“尔独”进行对比，然后又以诗人的疑问发出，这样就造成了一种震撼人心的艺术效果，越发突出孤雁的孤单、可怜。也正因为如此孤...", "authors": ["余春丽"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707e73206168b2e0223d", "shortContent": "在唐代的众多咏雁诗中，杜甫和崔涂的两首《孤雁》诗一直倍受后世推崇。二诗不但描写“孤”字入神，而且成功地将孤雁和诗人自己的形象融合在一起，以至于千年之后的读者仍能够通过吟咏其诗，想见其人。\n\n首联即描述此雁的孤单失群，点明题中的“孤”字。“几行归塞尽，念尔独何之？”两句先以“几行”和“尔独”进行对比，然后又以诗人的疑问发出，这样就造成了一种震撼人心的艺术效果，越发突出孤雁的孤单、可怜。也正因为如此孤...", "authors": ["余春丽"], "pressName": "崇文书局"}]', '《瀛奎律髓》：老杜云：“谁怜一片影，相失万重云。”此云：“暮雨相呼疾，寒塘欲下迟。”亦有味，而不及老杜之万钧力也。为江湖孤客者，当以此尾句观之。
《唐诗选脉会通评林》：何新之为平淡体。李梦阳曰：起句即悲，通篇情景相称，优柔不迫，佳作也。徐充曰：此咏物体。周伯弼所谓于和易宽缓之中而精切者。周珽曰：首二语已尽孤雁面目，便含怜悯深心。三四写其失群彷徨之景。五六写其孤飞索莫之态。结用宽语，致相悲相惜之意，以应起联；何等委婉顿挫！夫一孤雁微物，行止犹撄人念如此，士君子涉世，落落寡合、流离无偶者，何异于是？此诗诚可以观。
《五朝诗善鸣集》：写猿缥缈，写雁悲凉。
《初白庵诗评》：结意更深。
《瀛奎律髓汇评》：何义门：“念”字贯注到落句。纪昀：“相呼”则不孤矣，三句有病。“寒塘”句不言孤而是孤，不言雁而是雁，此为句外传神。“渚云”二句反衬出“孤”字。结处展过一步，曲折深至，语切境真，寓情无限。许印芳：孤雁乃失偶之雁，而未尝无群，“相呼”者呼其群也。晓岚訾之，非是。
《重订中晚唐诗主客图》：何尝有心自况，然寄托处妙甚，显然唐诗所以高也。起不作意而能得其分，正是水部（首二句下）。一结真感深情，宛转无极（末二句下）。
《唐诗三百首》：四句（按指中四句）二十层。十字（按指末二句）切“孤”。
《诗境浅说》：通篇皆实陚孤雁。首二句言雁行归尽，念此天空独雁，怅怅何之。以首句衬出次句，乃借宾定主之法。三四言暮雨苍茫，相呼失侣，将欲寒塘投宿，而孤踪自怯，几度迟徊。二句皆替雁着想，如庄周之以身化蝶，故入情入理。犹咏鸳鸯之“暂分烟岛犹回首，只渡寒塘亦并飞”，替鸳鸯着想，皆妙入毫颠也。五六言相随者惟“渚云”“关月”，见只影之无依。末句谓未必遽逄弋者，而独往易生疑惧。客子畏人，咏雁亦以自喻，此诗乃赋而兼比者也。三四句即以表面而论，三句言其失群之由，四句言失群仓皇之态，亦复佳绝。', 'center', 1417393436, '57b903ec5bbb50005b783dd4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10586, '春宫怨', NULL, 99, 334, 2, 1, '杜荀鹤', NULL, 10139, '57b9b39aa633bd005d2ea72a', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/93593/13613547.htm', '', '早被婵娟误，欲妆临镜慵。
承恩不在貌，教妾若为容。
风暖鸟声碎，日高花影重。
年年越溪女，相忆采芙蓉。', '此诗是唐末诗人杜荀鹤创作的代宫女抒怨的代言诗，载于《全唐诗》卷六百九十一。此诗含有自叹无人赏识之意。首联写因貌美而入宫，受尽孤寂，不愿梳妆；颔联写取宠不在容貌，因而不必妆扮了；颈联写景，春风骀荡，风和日丽，鸟语花香，借以烘托春心受残，寂寞空虚的情感；末联写往日之悲苦，更露其怨情。其中「风暖鸟声碎，日高花影重」两句是历来为人所推崇的名句。', '《全唐诗》此诗题下注：一作周朴诗。
婵娟：形容姿容、形态美好。
慵：懒。
若为容：如何去妆饰自己。《诗经·国风·卫风·伯兮》「岂无膏沐，谁适为容？」
碎：形容鸟鸣声纷纭杂沓，非一鸟独鸣，而是数鸟共语。
越溪女：指西施浣纱时的女伴。
芙蓉：莲花。', '早年因为容貌美丽被误选入宫中；想要对镜梳妆打扮却又意态懒慵。
承蒙君王宠爱不在于美丽的容貌，那教我如何还有心思去梳妆饰容。
春风和煦温暖鸟儿啼声清脆悦耳；正午艳阳高照花影才会叠叠重重。
每年此时我都会想起乡间的女伴，怀念当年自由欢快地采撷着芙蓉。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ec0ce818559d058a5a", "shortContent": "历来写宫怨的诗大多不着“春”字，即使是写春宫之怨的，也没有一首能像杜荀鹤这首那样传神地把“春”与“宫怨”密合无间地表现出来。\n前两句是发端。“婵娟”，是说容貌美好。宫女之被选入宫，就因为长得好看。入宫以后，伴着她的却只是孤苦寂寞，因而拈出一个“误”字，慨叹“今日在长门，从来不如丑”（于濆《宫怨》）。此刻，她正对着铜镜，顾影自怜，本想梳妆打扮一番，但一想到美貌误人，又不免迟疑起来，懒得动手了。上句一...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389af4797a92d5e4fd921", "shortContent": "历来写宫怨的诗大多不着“春”字，即使是写春宫之怨的，也没有一首能像杜荀鹤这首那样传神地把“春”与“宫怨”密合无间地表现出来。\n\n前两句是发端。“婵娟”，是说容貌美好。宫女之被选入宫，就因为长得好看。入宫以后，伴着她的却只是孤苦寂寞，因而拈出一个“误”字，慨叹“今日在长门，从来不如丑”（于濆《宫怨》）。此刻，她正对着铜镜，顾影自怜，本想梳妆打扮一番，但一想到美貌误人，又不免迟疑起来，懒得动手了。上句...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f0934c", "shortContent": "杜荀鹤少有壮志，据《嘉靖池州府志》卷七《人物篇•贤哲》记载：“杜荀鹤，字彦之，甫七岁，资颖豪迈，志存经史。忽家人令向东作，怒曰：‘吾岂耕夫耶！尔燕雀安知鸿鹊之志哉！’”另据史书载，杜氏一家三代近百口人聚居在一起，而他和弟侄都有自己的读书堂，可见家庭条件比较优越。正因为有如此优越的条件，又兼从小就萌生的雄心壮志，所以奠定了其日后“致君尧舜”之志。然大唐末世，仕途偃蹇，直到46岁那年，才以第八名的成绩...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707e73206168b2e02239", "shortContent": "杜荀鹤少有壮志，据《嘉靖池州府志》卷七《人物篇·贤哲》记载：“杜荀鹤字彦之，甫七岁，资颖豪迈，志存经史。忽家人令向东作，怒曰：吾岂耕夫耶！尔燕雀安知鸿鹊之志哉！”另据史书载，杜氏一家三代近百口人聚居在一起，而他和弟侄都有自己的读书堂，可见家庭条件比较优越。正因为有如此优越的条件，又兼从小就萌生的雄心壮志，所以奠定了其日后“致君尧舜”之志。然大唐末世，仕途偃蹇，直到46岁那年，才以第八名的成绩登第。...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312716573206168b2e02305", "shortContent": "杜荀鹤少有壮志，据《嘉靖池州府志》卷七《人物篇·贤哲》记载：“杜荀鹤字彦之，甫七岁，资颖豪迈，志存经史。忽家人令向东作，怒曰：吾岂耕夫耶！尔燕雀安知鸿鹊之志哉！”另据史书载，杜氏一家三代近百口人聚居在一起，而他和弟侄都有自己的读书堂，可见家庭条件比较优越。正因为有如此优越的条件，又兼从小就萌生的雄心壮志，所以奠定了其日后“致君尧舜”之志。然大唐末世，仕途偃蹇，直到46岁那年，才以第八名的成绩登第。...", "authors": ["刘晓亮"], "pressName": "崇文书局"}]', '《六一诗话》：唐之晚年，诗人无复李、杜豪放之格，然亦务以精意相高。如周朴者，构思尤艰，每有所得，必极其雕琢，故时人称朴诗「月锻季炼，未及成篇，已播人口」、其名重当时如此，而今不复传矣。余少时犹见其集，其句有云：「风暖鸟声碎，日高花影重。」又云；「晓来山鸟闹，雨过杏花稀。」诚佳句也。
《苕溪渔隐丛话》：故谚云：杜诗三百首，惟在一联中，「风暖鸟声碎，日高花影重」是也。
《观林诗话》：杜荀鹤诗句鄙恶，世所传《唐风集》首篇「风暖鸟声碎，日高花影重」者，余甚疑不类荀鹤语。他日观唐人小说，见此诗乃周朴所作，而欧阳文忠公亦云耳。盖借此引编，已行千世矣。
《幕府燕闲录》：杜荀鹤诗鄙俚近俗，惟《宫词》为唐第一，云：「早被婵娟误……」故谚云「杜诗三百首，惟在一联中。风暖鸟声碎，日高花影重」是也。
《瀛奎律髓》：譬之事君而不遇者，初亦恃才，而卒为才所误。愈欲自炫，而愈不见知。盖宠不在貌，则难乎其容矣，女为悦己者容是也。风景如此，不思从平生贫贱之交可乎？
《艺苑巵言》：王勃「河桥不相送，江树远含情」，杜荀鹤「承恩不在貌，教妾若为容」，皆五言律也，然去后四句作绝乃妙。
《唐诗镜》：三四善怨，五六缛绣语。
《雪涛小书》：有评者曰：「杜诗三百首，妙在一联中。风急鸟声晬，日高花影重。」余玩之，终不如次联更妙。「承恩不在貌，教妾若为容」，二语寥寥，而居臣上下遇合处，情皆若此。杜以两语括之，可谓简而尽、怨而不怒者矣。
《唐诗归》：锺云：（鸟声碎）三字开诗余思路（「风暖」句下）。
《唐诗选脉会通评林》：何新之为富艳体。唐汝询曰：起道尽悔情。次联十字怨甚。张次璧谓「次句即『威仪棣棣，不可选也』」，意想虽深，与上二句不洽。结二语无聊，正与起句相洽。吴山民曰：次联深得《国风》和婉之致。周启琦曰：三四善怨。五六缛绣。细玩五六，终不如三四更妙。周珽曰：魏菊庄以三四为自然句法，五六为绮丽句法；不知结语托意更深，想头又远，此诗若无此结，终入寻常套调。此篇构同转析，含情真至。
《薑斋诗话》：晚唐饾凑，宋人支离，俱令生气顿绝。「承恩不在貌，教妾若为容？风暖鸟声碎，日高花影重。」医家名为关格，死不治。
《古诗评选》：「风急鸟声碎，日高花影重」，词相比而事不相属，斯以为恶诗矣。
《才调集补注》：默菴云：奇妙在落句，得力在颔联。默菴云：怨（首二句下）。春宫怨（「风暖」二句下）。
《唐诗摘钞》：此感士不遇之作也。
《唐三体诗评》：落句收足「早」字、「貌」字。
《载酒园诗话又编》：《春宫怨》不唯杜集首冠，即在全唐亦属佳篇。「承恩不在貌，教妾若为容」，此千古透论。卫硕人不见答，非貌寝也；张良娣擅权，非色胜也。陈鸿《长恨传》曰：「非徒殊艳尤态独能致是，盖才智明慧，善巧便佞，先意希旨，有不可形容者焉。」即此诗转语。读此觉义山之「未央宫里三千女，但保红颜莫保恩」，尚非至论。
《带经堂诗话》：晚唐人诗「风暖鸟声碎，日高花影重」、「晓来山鸟闹，雨过杏花稀」……皆佳句也，然总不如右丞「兴阑啼鸟缓，坐久落花多」自然入妙。
《唐律消夏录》：三四临镜低徊，有无限意思在。五六虽佳，与结句却不合笱。
《唐诗别裁》：恃貌而误（首句下）。不得已而随俗（「承恩」二句下）。回忆盛年以自伤也。须曲体此意。
《唐诗笺要》：负色人难得此透亮语（首二句下）。宫怨题，能为律诗，难矣。终首不露「怨」字痕迹，可谓和平。
《近体秋阳》：第三句即首二句所以然之故，不说破更妙，说破便损起联之气。晚唐之所以不如初盛者，识此故也。思致清迥，文气高老。
《瀛奎律髓汇评》：冯舒：五六写出春宫，落句不测。冯班：全首俱妙，腹联人所共知也。精极。何义门：五六是「慵」字神味。入宫见妒，岂若与采莲者之无猜乎？落句怨之甚也。纪昀：前四句微觉太露，然晚唐诗又别作一格论。结句妙，于对面落笔，便有多少微婉。
《唐贤小三昧集续集》：点破春情，鬼当夜哭（「承恩」句下）。
《唐诗快》：当时谚云：「杜诗三百首，唯在一联中。」即此「风暖」一联也。故《唐风集》以之压卷，想当不谬。
《养一斋诗话》：杜荀鹤以「风暖鸟声碎」一联得名，愚按不如「暮天新雁起汀洲，红寥花疏水国秋」清艳入骨也。
《诗境浅说》：题面纯为宫怨而作。首言早擅倾城之貌，自赏翻以自误，寸心灰尽，临明镜而多慵。三四谓粉黛三千，谁为丽质，而争宠取怜者，各工其术，则己之膏沐，宁用施耶，五六赋「春」字，五句言天寒鸟声多噤，至风暖则细晬而多；六句言朝辉夕照之时，花多侧影，至日当亭午，则骈枝叠叶，花影重重。用「碎」字、「重」字，固见体物之工，更见宫女无聊，借春光以自遣，故鸟声花影体会入微。末句忆当年女伴，搴芳水次，何等萧闲，遥望若耶溪上，如笼乌之羡翔云，池鱼之思纵壑也。此诗虽为宫人写怨，哀窈窕时感贤才，作者亦以自况。失意文人望君门如万里，与寂寞宫花同其幽怨已。', 'center', 1417394068, '57b99cb779bc44006029a8df', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10587, '章台夜思', NULL, 136, 380, 2, 1, '韦庄', NULL, 10140, '57b9c08d79bc4400639c80ea', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383464.htm', '', '清瑟怨遥夜，绕弦风雨哀。
孤灯闻楚角，残月下章台。
芳草已云暮，故人殊未来。
乡书不可寄，秋雁又南回。', '这是一首身在外地思念家乡的诗。诗以「夜思」为题，开篇却不写思，而写秋夜所闻所见，写尽寄居他乡的孤独、悲凉。诗的后半，写「思」的内容：芳草已暮，韶华已逝，故人不来，乡思难寄。最后点出时当秋节，更令人愁思不断。诗中表达了一种无可奈何的恨。全诗一气呵成，感情真挚，幽怨清晰，感人至深。', '章台：即章华台，宫名，故址在今陕西长安。在今湖北省监利县西北。《左传·昭公七年》：「楚子城（筑）章华之台。」
瑟：古代弦乐器。多为二十五弦。弦乐器，这里指乐声。清瑟，即凄清的瑟声。
遥夜：长夜。
楚角：楚地吹的号角。其声悲凉。
下：落下。
芳草：这里指春光。
已云暮：已经晚暮了，指春光快要消歇了。云，「又」义。
殊：竟，尚。
乡书：指家书，家信。
不可寄：是说无法寄。
雁又南回：因雁是候鸟，秋天从此南来，春天又飞往北方。古时有雁足寄书的传说，事书《汉书·苏武传》。', '忧怨的琴声在长夜中回荡，弦音悲切似凄风苦雨缭绕。
孤灯下又听见楚角的哀声，清冷的残月徐徐沉下章台。
茂盛的芳青已经开始枯萎，期盼的亲人故友都没有来。
家中的书信不能够寄回去，因为大雁已经向南方飞去。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f39c26cbf3417f0934d", "shortContent": "刘若愚先生说：“中国诗人似乎永远悲叹流浪和希望还乡。”自古而今，怀乡念归，是中国古典文学中的一条精神纽带，维系着士人的精神漂泊。不管穷达沉浮，不管用舍行藏，故乡永远是内心的回望。身处晚唐末世的韦庄，身经动乱，不得不离开家乡杜陵而远至江南避难，及至后来的入蜀，但不管到了哪里，故乡都时时牵动着他的心弦。\n\n章台，《左传•邵公七年》：“楚子城章华之台。”故址在今湖北监利。这首《章台夜思》，当是诗人在楚地...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707bf2af4e09d55b67b9", "shortContent": "刘若愚先生说：“中国诗人似乎永远悲叹流浪和希望还乡。”自古而今，怀乡念归，是中国古典文学中的一条精神纽带，维系着士人的精神漂泊。不管穷达沉浮，不管用舍行藏，故乡永远是内心的回望。身处晚唐末世的韦庄，身经动乱，不得不离开家乡杜陵而远至江南避难，及至后来的入蜀，但不管到了哪里，故乡都时时牵动着他的心弦。\n\n章台，故址在今陕西长安，汉时此地已成为了游览胜地。这首《章台夜思》，当是诗人在长安时因思念远在第...", "authors": ["刘晓亮"], "pressName": "崇文书局"}]', '', 'center', 1417394315, '57b8fdaad342d3005ac71323', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10619, '遣悲怀（其二）', NULL, 119, 890, 2, 2, '元稹', NULL, 10082, '57b9bf37d342d3006be01c7b', '唐', 'shi', '诗', 'http://baike.baidu.com/view/159046.htm', '', '昔日戏言身后意，今朝都到眼前来。
衣裳已施行看尽，针线犹存未忍开。
尚想旧情怜婢仆，也曾因梦送钱财。
诚知此恨人人有，贫贱夫妻百事哀。', '此诗为《遣悲怀》组诗的第二首，主要写妻子死后的“百事哀”。诗人写了在日常生活中引起哀思的几件事。人已仙逝，而遗物犹在。为了避免见物思人，便将妻子穿过的衣裳施舍出去；将妻子做过的针线活仍然原封不动地保存起来，不忍打开。诗人想用这种消极的办法封存起对往事的记忆，而这种做法本身恰好证明他无法摆脱对妻子的思念。还有，每当看到妻子身边的婢仆，也引起自己的哀思，因而对婢仆也平添一种哀怜的感情。白天事事触景伤情，夜晚梦魂飞越冥界相寻。梦中送钱，似乎荒唐，却是一片感人的痴情。苦了一辈子的妻子去世了，如今生活在富贵中的丈夫不忘旧日恩爱，除了“营奠复营斋”以外，已经不能为妻子做些什么了。于是积想成梦，出现送钱给妻子的梦境。末两句，从“诚知此恨人人有”的泛说，落到“贫贱夫妻百事哀”的特指上。夫妻死别，固然是人所不免的，但对于同贫贱共患难的夫妻来说，一旦永诀，是更为悲哀的。末句从上一句泛说推进一层，着力写出自身丧偶不同于一般的悲痛感情。', '戏言：开玩笑的话。
身后意：一作“身后事”，关于死后的设想。
行看尽：眼看快要完了。
怜：怜爱，痛惜。
诚知：确实知道。', '往昔曾经戏言我们身后的安排，如今都按你所说的展现在眼前。
你穿过的衣裳已经快施舍完了，你的针线盒我珍存着不忍打开。
因怀念你我对婢仆也格外怜爱，多次梦到你我便为你焚纸烧钱。
诚知这种哀思人人都会经历，但共贫穷共患难的夫妻更加哀痛。', NULL, '', 'center', 1417514137, '57b9111d165abd0054c053b4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10588, '寻陆鸿渐不遇', NULL, 94, 485, 1, 1, '皎然', NULL, 10141, '57b9a0835bbb500063f4cbf3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383466.htm', '', '移家虽带郭，野径入桑麻。
近种篱边菊，秋来未著花。
扣门无犬吠，欲去问西家。
报道山中去，归来每日斜。', '此诗为访友不遇之作，描写了隐士闲适清静的生活情趣。诗人选取种养桑麻菊花、邀游山林等一些平常而又典型的事物，刻画了一位生活悠闲的隐士形象。全诗有乘兴而来、兴尽而返的情趣，语言朴实，吐属自然，不加雕饰，流畅潇洒，层次分明，音调和谐。', '陆鸿渐：名羽，终生不仕，隐居在苕溪（今浙江湖州境内），以擅长品茶著名，著有《茶经》一书，被后人奉为“茶圣”、“茶神”。
虽：一作“唯”。带：近。郭：外城，泛指城墙。
篱边菊：语出陶渊明《饮酒》诗：“采菊东篱下，悠然见南山。”
著花：开花。
扣门：敲门。
西家：西邻。
报道：回答道，报，回报，回答。去：一作“出”。
归时每日斜：一作“归来日每斜”。日斜：日将落山，暮时也。', '他把家迁徙到了城郭一带，乡间小路通向桑麻的地方。
近处篱笆边都种上了菊花，秋天到了却尚未见它开放。
敲门竟连一声犬吠都没有，要去向西家邻居打听情况。
邻人报说他是到山里去了，回来时总要西山映着斜阳。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b65914587d02f4e812", "shortContent": "陆鸿渐，名羽，终生不仕，隐居在苕溪（今浙江吴兴），以擅长品茶著名，著有《茶经》一书，被后人奉为“茶圣”、“茶神”。他和皎然是好友。这首诗当是陆羽迁居后，皎然过访不遇所作。\n陆羽的新居离城不远，但已很幽静，沿着野外小径，直走到桑麻丛中才能见到。开始两句，颇有晋陶渊明“结庐在人境，而无车马喧”（《饮酒二十首》其五）的隐士风韵。\n陆羽住宅外的菊花，大概是迁来以后才种上的，虽到了秋天，还未曾开花。这二句，...", "authors": ["唐永德"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3ac26cbf3417f0934e", "shortContent": "陆鸿渐，名羽，著有《茶经》，被后人尊为“茶圣”。他终生不仕，隐居在浙江苕溪。这首诗是诗僧皎然在陆羽搬家后不久前去拜访的经历，虽然寻访不遇，但是通过居住环境的点染、邻人言及的诸种侧面描写，陆羽超然出世的风采已经卓然呈现。\n\n一、二句交代事由。陆羽刚搬家，虽然离城不远，但很幽僻，要穿过无人的野径走入一片桑麻地，才能找到他的家。不仅写及陆羽新家的位置，诗人穿行于城外野径，寻幽访友的足迹亦清晰可见。桑麻，...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127069e6f69b71e93f62aa", "shortContent": "陆鸿渐，名羽。著有《茶经》，被后人尊为“茶圣”。他终生不仕，隐居在浙江苕溪。这首诗是诗僧皎然在陆羽搬家后不久前去拜访的经历，虽然寻访不遇，但是通过居住环境、邻人言语等诸种侧面描写，陆羽超然出世的风采已经卓然呈现。\n\n一、二句交代事由。陆羽刚搬家，虽然离城不远，但很幽僻，要穿过无人的野径走入一片桑麻地，才能找到他的家。不仅写及陆羽新家的位置，诗人穿行于城外野径，寻幽访友的足迹亦清晰可见。桑麻，是典型...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270ef73206168b2e0228a", "shortContent": "陆鸿渐，名羽。著有《茶经》，被后人尊为“茶圣”。他终生不仕，隐居在浙江苕溪。这首诗是诗僧皎然在陆羽搬家后不久前去拜访的经历，虽然寻访不遇，但是通过居住环境的点染、邻人言语等诸种侧面描写，陆羽超然出世的风采已经卓然呈现。\n\n一、二句交代事由。陆羽刚搬家，虽然离城不远，但很幽僻，要穿过无人的野径走入一片桑麻地，才能找到他的家。不仅写及陆羽新家的位置，诗人穿行于城外野径，寻幽访友的足迹亦清晰可见。桑麻，...", "authors": ["张春晓"], "pressName": "崇文书局"}]', '《升庵诗话》：五言律八句不对，太白、浩然集有之，乃是平仄稳贴古诗也。僧皎然有《访陆鸿渐不遇》一首……虽不及李白之雄丽，亦清致可喜。
《唐诗归》：钟云：不遇之妙，在此二语，不须下文注明（“近种”二句下）。
《才调集补注》：默庵云：寻（首二句下）。不遇（“叩门”句下）。
《唐诗快》：只如未曾作诗，岂非无字禅耶？
《唐诗摘钞》：极淡极真，绝似孟襄阳笔意。此全首不对格，太白、浩然集中多有之。二公皆古诗手，不喜为律所缚，故但变古诗之音节而创为此体也。
《碛砂唐诗选》：与古意稍远。
《唐三体诗评》：上四句“寻”字，下四句“不遇”。诗至此都无笔墨之痕。
《唐诗别裁》：通首散语，存此以识标格。
《说诗晬语》：（五律）又有通体俱散者，李太白《夜泊牛渚》、孟浩然《晚泊浔阳》、释皎然《寻陆鸿渐》等章，兴到成诗，人力无与；匪垂典则，偶存标格而已。
《诗境浅说》：此诗晓畅，无待浅说，四十字振笔写成，清空如活。庙人五律间有此格，李白《牛渚夜泊》诗亦然。作诗者于声律对偶之馀，偶效为之，以畅其气，如五侯鲭馔，杂以蔬笋烹芼。别有隽味；苦多作，则流于空滑。况李白诗之英气盖世。此诗之萧洒出尘，有在章句外者，非务为高调也。
《五七言今体诗钞》：似孟公。', 'center', 1417394491, '57b903a35bbb50005b783ba0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10589, '行经华阴', NULL, 54, 46, 1, 3, '崔颢', NULL, 10093, '57b9a826a633bd005d2e2d61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383481.htm', '', '岧峣太华俯咸京，天外三峰削不成。
武帝祠前云欲散，仙人掌上雨初晴。
河山北枕秦关险，驿路西连汉畤平。
借问路旁名利客，何如此处学长生。', '此诗描写了诗人途经华阴时所见的华山三峰雄奇险峻的景色，表现了祖国山河的壮美瑰丽，抒发了诗人对奔走名利者的不耻以及对学道求仙的向往之情。首联写远景，起句不凡，以华山之高峻和三峰的高矗天际，压倒京都之豪富，暗寓出世高于追名逐利；颔联写晴雨时的景色，是近景；颈联写想象中的幻景，描述华阴地势的险要和汉畤的形胜，即景生感，隐含倦于风尘退隐山林之意；尾联反诘，借向旁人劝喻，说明凡争名夺利的人，就不得安心息影学长生之术。全诗打破了律诗的起承转合的格式，别具神韵。诗境雄浑壮阔，寓意深刻。', '华阴：今陕西省华阴县，位于华山北面。一作「华山」。
岧嶤（yáo）：山势高峻的样子。
太华：即华山。咸京：即咸阳，今陕西西安。《旧唐书·地理志》：「京师，秦之咸阳，汉之长安也。」所以此诗把唐都长安称为咸京。
三峰：指华山的芙蓉、玉女、明星三峰。一说莲花、玉女、松桧三峰。
武帝祠：即巨灵祠。汉武帝登华山顶后所建。帝王祭天地五帝之祠。
仙人掌：峰名，为华山最峭的一峰。相传华山为巨灵神所开，华山东峰尚存其手迹。
秦关：指秦代的潼关。一说是华阴县东灵宝县的函谷关，故址在今河南省灵宝县。
驿路：指交通要道。
汉畤（zhì）：汉帝王祭天地、五帝之祠。畤，古代祭祀天地五帝的固定处所。
名利客：指追名逐利的人。
学长生：指隐居山林，求仙学道，寻求长生不老。', '在高峻华山上俯视京都长安，三峰伸向天外不是人工削成。
在武帝祠前的乌云将要消散，雨过天晴仙人掌峰一片青葱。
秦关北靠河山地势多么险要，驿路通过长安往西连着汉畤。
借问路旁那些追名逐利的人，为何不到此访仙学道求长生？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a334a8757d5a0e1c55", "shortContent": "诗题《行经华阴》，既是“行经”，必有所往；所往之地，就是求名求利的集中地——“咸京”（今陕西西安）。《旧唐书·地理志》：“京师，秦之咸阳，汉之长安也。”所以此诗把唐都长安称为咸京。诗中提到的“太华”、“三峰”、“武帝祠”、“仙人掌”、“秦关”、“汉臝”……都是唐代京都附近的名胜与景物。当时京师的北面是雍县，秦文公曾在这里作鄜臝（臝，谓“神灵所止之地”，即后世神坛之类）。到汉高祖作北臝止，这里共有五...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d19330151fa", "shortContent": "这是崔颢从中州西赴长安行经华阴时所写的一首诗，用雄浑沉壮之笔，写出了西岳华山的气势，较之杜甫之咏泰山，轩轾难分。华山自古以“险”著称，又是道教灵山，而崔颢这首诗不仅生动地描绘了华山之险，也将华山的仙气萦绕于字里行间。\n\n首联起笔即不凡，用一“俯”字，突出了华山的气势凌人。岧峣为高峻貌。从华山之顶，可以俯瞰咸阳。以秦帝京之雄，衬出华山之峭拔。下句“天外三峰”，《广舆记》载：“华山石壁直立，如削成。最...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127053e6f69b71e93f627d", "shortContent": "这是崔颢从中州西赴长安行经华阴时所写的一首诗，用雄浑沉壮之笔，写出了西岳华山的气势，较之杜甫之咏泰山，轩轾难分。华山自古以“险”著称，又是道教灵山，而崔颢这首诗不仅生动地描绘了华山之险，也将华山的仙气萦绕于字里行间。\n\n首联起笔即不凡，用一“俯”字，突出了华山的气势凌人，“岧峣”则写出了华山的高峻，使“俯”字更有说服力。从华山之顶，可以俯瞰咸阳，以秦帝京之雄，衬出华山之峭拔。下句“天外三峰”，《广...", "authors": ["（刘晓亮）"], "pressName": "崇文书局"}]', '', 'center', 1417427194, '57b97386165abd0054c3f597', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10590, '望蓟门', NULL, 145, 36, 4, 4, '祖咏', NULL, 10142, '57b9bf0ac4c9710061480c6e', '唐', 'shi', '诗', 'http://baike.baidu.com/view/356513.htm', '', '燕台一望客心惊，笳鼓喧喧汉将营。
万里寒光生积雪，三边曙色动危旌。
沙场烽火连胡月，海畔云山拥蓟城。
少小虽非投笔吏，论功还欲请长缨。', '此诗写诗人到边地见到壮丽景色，抒发立功报国的壮志。诗一开始就用“心惊”二字，表示诗人对国事的担忧；接着写听到军中不断传来鼓角声，使人感到浓厚的战争气氛；中间四句进一步具体地描绘了登台所见的紧张情况，从而激发了诗人投笔从戎、平定边患、为国立功的壮志。全诗意境辽阔雄壮，充满阳刚之美，带有浓郁的盛唐时期的慷慨之气，写景状物中又寄寓着诗人热爱祖国山河的豪情和投身疆场为国立功的壮志，是一篇催人奋进的爱国主义乐章。', '蓟门：在今北京西南，唐时属河北道所辖，幽州（范阳郡）治所，是唐朝屯驻重兵之地。
燕台：原为战国时燕昭王所筑的黄金台，这里代称燕地，用以泛指平卢、范阳这一带。
一望：一作“一去”。
客：诗人自称。
笳：汉代流行于塞北和西域的一种类似于笛子的管乐器，此处代指号角。
三边：古称幽、并、凉为三边。这里泛指当时东北、北方、西北边防地带。
危旌：高扬的旗帜。一作“行旌”。
烽火：古代用于军事通信的设施，遇敌情时点燃狼粪，以传警报。
投笔吏：汉人班超家贫，常为官府抄书以谋生，曾投笔叹曰：“大丈夫当立功异域以取封侯，安能久事笔砚间。”后终以功封定远侯。
论功：指论功行封。
请长缨：汉人终军曾自向汉武帝请求：“愿受长缨，必羁南越王而致之阙下。”后被南越相所杀，年仅二十馀。缨，绳。', '登上燕台眺望不禁感到震惊，笳鼓喧闹之地原是汉将兵营。
万里积雪笼罩着冷冽的寒光，边塞曙光映照着飘动的旌旗。
战场烽火连天遮掩边塞明月，南渤海北云山拱卫着蓟门城。
少年时虽不像班超投笔从戎，论功名我想学终军自愿请缨。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929403048e64fbd912c9", "shortContent": "唐代的范阳道，以今北京西南的幽州为中心，统率十六州，为东北边防重镇。它主要的防御对象是契丹。玄宗开元二年（714），即以并州长史薛讷为同紫薇黄门三品，将兵御契丹；二十二年，幽州节度使张守珪斩契丹王屈烈及可突干。这首诗的写作时期，大约在这二十年之间，其时祖咏当系游宦范阳。\n燕台原为战国时燕昭王所筑的黄金台，这里代称燕地，用以泛指平卢、范阳这一带。“燕台一去”犹说“一到燕台”，四字倒装，固然是诗律中平...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d105", "shortContent": "唐代的范阳道，以今北京西南的幽州为中心，统率十六州，为东北边防重镇。它主要的防御对象是契丹。玄宗开元二年（714），即以并州长史薛讷为同紫薇黄门三品，将兵御契丹；二十二年，幽州节度使张守珪斩契丹王屈烈及可突干。这首诗的写作时期，大约在这二十年之间，其时祖咏当系游宦范阳。\n\n燕台原为战国时燕昭王所筑的黄金台，这里代称燕地，用以泛指平卢、范阳这一带。“燕台一去”犹说“一到燕台”，四字倒装，固然是诗律中...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d19330151fb", "shortContent": "蓟门，又称蓟城，即今北京。幽蓟一带是唐代东北地区的军事要地。这首诗抒写诗人初到这一要地观察的景象和感想，表达出立功报国的志向。据说，战国时燕昭王为了招聘有才能的人才，曾经筑起一座高台，上面放置黄金，这就是黄金台，也叫燕台。这个台在蓟门一带，所以诗人用“燕台”来代指蓟门，泛指平卢、范阳这一带。唐代的范阳道，以今北京西南的幽州为中心，统率十六州，为东北边防重镇。它主要的防御对象是契丹。玄宗开元二年（7...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312703bf2af4e09d55b6733", "shortContent": "蓟门，又称蓟城，即今北京市。幽蓟一带是唐代东北地区的军事要地。这首诗抒写诗人初到这一要地观察的景象和感想，表达出立功报国的志向。据说，战国时燕昭王为了招纳有才能的人才，曾经筑起一座高台，上面放置黄金，这就是黄金台，也叫燕台。这个台在蓟门一带，所以诗人用“燕台”来代指蓟门，泛指平卢、范阳这一带。唐代的范阳道，以今北京西南的幽州为中心，统率十六州，为东北边防重镇。它主要的防御对象是契丹。唐玄宗开元二年...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312706ac305cf0801816fec", "shortContent": "蓟门，又称蓟城，即今北京市。幽蓟一带是唐代东北地区的军事要地。这首诗抒写诗人初到这一要地观察的景象和感想，表达出立功报国的志向。据说，战国时燕昭王为了招纳有才能的人才，曾经筑起一座高台，上面放置黄金，这就是黄金台，也叫燕台。这个台在蓟门一带，所以诗人用“燕台”来代指蓟门，泛指平卢、范阳这一带。唐代的范阳道，以今北京西南的幽州为中心，统率十六州，为东北边防重镇。它主要的防御对象是契丹。玄宗开元二年（...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "645fc31a5fc8182fe989e62f", "bookTitle": "历代励志诗鉴赏：生当作人杰", "articleId": "6472a3a430675327e1c2afd3", "shortContent": "唐代的范阳道，以今北京西南的幽州为中心，统率十六州，为东北边防重镇。它主要的防御对象是契丹。玄宗开元二年，即以并州长史薛讷为同紫薇黄门三品，将兵御契丹；二十二年，幽州节度使张守珪斩契丹王屈烈及可突干。这首诗的写作时期，大约在这二十年之间，其时祖咏当系游宦范阳。\n\n燕台原为战国时燕昭王所筑的黄金台，这里代称燕地，用以泛指平卢、范阳这一带。“燕台一去”犹说“一到燕台”，四字倒装，固然是诗律中平仄声排列...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}]', '《批点唐诗正声》：壮健之气，直欲与卫、霍同出塞上。
《唐诗直解》：调高语壮，“生”、“动”、“连”、“拥”四字犯。
《批选唐诗》：此等诗全不著事理，直以声华胜，近体多类此。
《唐诗分类绳尺》：善状物色，清兴洒然。
《唐诗训解》：此因临边而有志于立功也。次联语顿挫又雄壮。
《唐风定》：整峻高亮。睥睨王、李。
《诗源辩体》：“燕台一去”一篇，实为于鳞诸子鼻祖。
《汇编唐诗十集》：唐云：调高语壮，是盛唐最上格。
《唐诗选脉会通评林》：周珽曰：起寓讥边将，便有耻为碌碌尸素之想。中四句极状边庭之景。未以班超、终军自许，树勋报国之志挺然。蒋一梅曰：气象朗开。结壮。薛蕙曰：铺叙得体，词意正大。
《贯华堂选批唐才子诗》：
此诗已是异样神彩，乃读末句，又见特添“少小”二字，便觉神彩再加十倍。
《唐诗绎》：
此诗见蓟城为防胡险要之地，望之动立功塞上之思。一气旋转，浑成无迹。
《删订唐诗解》：气象自佳，而中四句太相似。
《唐诗贯珠笺释》：通首有气色，是盛唐格调。
《唐贤三昧集笺注》：亦是盛唐正声。气格雄浑，以为盛唐正声洵然。
《唐诗成法》：法亦紧严。中四句法稍同，亦是小疵。通首雄丽，读之生人壮心。
《历代诗法》：高响不浮。
《网师园唐诗笺》：悲壮称题（“万里”一联下）。
《唐诗笺要》：格调高秀，自不待言。“生”、“动”、“侵”、“拥”，皆炼第五字。
《山满楼笺注唐诗七言律》：开口先补出“燕台”二字，此身便有着落。“客心惊”，一“惊”字包得下文七句之义；而“汉将营”三字，又七句中之提纲也。
《读雪山房唐诗序例》：调高气厚，为七言律正始之音，惜不多见。
《唐诗三百首》：字字是“望”，非泛咏蓟门也。
《唐诗五七言近体五七言绝句选评》：黄钟大吕，音响铿锵。
《昭昧詹言》：六句写蓟城之险，而以首句一“望”字包之，收托意，有澄清之志。岂是时范阳已有萌芽耶？
潘德舆评点《唐贤三昧集》：通体遒俊。三四尤得穷边陈垒情色。
《唐诗近体》：“望”字空洞。
《唐宋诗举要》：吴曰：前六句皆写边隅景象，盖自恨来此穷裔，故云“客心惊”也，而末句乃掉转，意思故佳。', 'center', 1417427352, '57b8f34dc4c97100558ec7e5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10591, '九日登望仙台呈刘明府容', NULL, 59, 16, 1, 1, '崔曙', NULL, 10143, '57bbc0778ac24700630ca044', '唐', 'shi', '诗', 'http://baike.baidu.com/view/576758.htm', '', '汉文皇帝有高台，此日登临曙色开。
三晋云山皆北向，二陵风雨自东来。
关门令尹谁能识，河上仙翁去不回。
且欲近寻彭泽宰，陶然共醉菊花杯。', '此诗写诗人重九登高邀请友人痛饮，写得不落常套，独具特色，在抒写怀念友人的情思中，隐含着知音难遇的喟叹。首联言登台之事；颔联字面写四季变换，实际上是感叹历史变迁；颈联继续抒发历史感慨；尾联言志：功名利禄都是过眼云烟，不如饮酒自娱。全诗融写景、怀古、抒情于一炉，气势雄浑，酣畅淋漓，转承自然，一气呵成。', '九日：指农历九月九日重阳节。
望仙台：据说汉河上公授汉文帝《老子章句》四篇而去，後来文帝築台以望河上公，後即望仙台，在今河南陕县西南。刘明府容：名容，生平不详。明府，唐代对县令的尊称。
高台：指望仙台。
曙色开：朝日初出、阳光四照的样子。
三晋：指古晋国，春秋末韩、魏、赵三家分晋，故有此称。在今山西、河南一带。北向：形容山势向北偏去。
二陵：指崤山南北的二陵，在今河南洛宁、陕县附近。据《左传》载，崤山南陵是夏帝皋的陵墓，北陵是周文王避风雨的地方。
东：一作「西」。
关：函谷关。
令尹：守函谷关的官员尹喜，相传他忽见紫气东来，知有圣人至。不一会果然老子骑青牛过关。尹喜留下老子，于是老子写《道德经》一书。尹喜後随老子而去。谁能识：谁还能遇到关门令尹呢？
河上仙翁：即河上公，汉文帝时人，传说其後羽化成仙。
彭泽宰：晋陶渊明曾为彭泽令。渊明嗜酒而爱菊。有一次重阳节无酒喝，久坐于菊丛中，刚好王弘送酒至，即便就酌，醉後而归。这里暗用其「九日」事。彭泽宰借指刘明府。
陶然：欢乐酣畅的样子。
共醉：一作「一醉」。
菊花杯：意谓对菊举杯饮酒。', '韵译
汉文皇帝修建高高的望仙台，今日登临时天边曙色刚散开。
三晋的重重云山全向着北方，崤山二陵的风雨从东边飘来。
像关门令尹谁能够认识清楚，仙翁河上公一去便不再返回。
远求神仙不如就近寻彭泽宰，一起畅饮共为重阳菊花干杯。
散译
汉文帝在这里筑了一座高台，今天我来到台上时，太阳才刚出来。三晋一带，山岭都向北蜿蜒而去；崤山二陵那里的风雨，都从东方袭来。函谷关尹子潜修有道，又有谁知道呢？河上仙翁不肯留下，一去不回。既然仙人难见，姑且就近找找陶渊明吧，让我们共饮菊花酒，喝他个酩酊大醉。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d19330151fc", "shortContent": "这是一首重阳节登览感怀而邀饮之作。据《太平寰宇记》所载，望仙台在陕州陕县西南，为汉文帝刘恒所筑，以望祭河上公。“河上公”何许人？据晋葛洪《神仙传》所载：河上公者，不知其姓名。汉文帝时，在黄河岸边结草为庵，研究《老子经》颇有造诣。而为史家誉称的“文景之治”，其思想基础恰好也是老庄哲学，于是，文帝常以治国安民之策向这位道家高人请教。文帝所筑望仙台经历了八个世纪的沧桑，至唐玄宗开元间，又迎来中国历史新的...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127055e6f69b71e93f6293", "shortContent": "这是一首登览感怀之作。据《太平寰宇记》所载，望仙台在陕州陕县（今属河南三门峡）西南，为汉文帝刘恒所筑，以望祭河上公。\n\n“河上公”何许人？据晋朝人葛洪《神仙传》所载：河上公者，不知其姓名。汉文帝时，在黄河岸边结草为庵，研究《道德经》颇有造诣。而为史家艳称的“文景之治”，其思想基础恰好也是老庄哲学，于是，文帝常以治国安民之策向这位道家高人请教。文帝所筑望仙台经历了八个世纪的沧桑，至唐玄宗开元间，又迎...", "authors": ["杨军"], "pressName": "崇文书局"}]', '明·顾麟《批点唐音》：此篇句律典重，通篇匀称，情景分明，又一意直下，固足为法。但看音律不雄浑，绝似中唐。
明·郭浚《增订评注唐诗正声》：慷慨写意，中唐人无此气骨。
明·玉遮《唐诗选》：三、四即境用事，甚切。
清·金圣叹《贯华堂选批唐才子诗》：「曙色开」妙。一是高台久受湮没，气象忽得一开；一是登高台人久抱抑郁，情思忽得一畅（「此日」句）。
清·朱之荆《增订唐诗摘钞》：起联见题，次联写景，中联叙事，末联寓意。格法严正，风调高古，兴象玲珑，悉备此作。昔人取七言律压卷者，或以沈佺期《独不见》，或出崔颢《黄鹤楼》，然沈中二联语意微重，崔起四句非律诗正格，必求尽善，恐无过此篇也。一气舒卷，毫无痕迹。
清·王锡等《唐七律选》：何许气象，何许神兴，千秋绝调（「三晋」二句）。一气转合，就题有法。
清·吴煊《唐贤三昧集笺注》：堂堂正正。三、四有李、杜口吻，自是盛唐正声。
清·宋宗元《网师园唐诗笺》：名句浑成（「二陵」句）。
清·张文荪《唐贤清雅集》：形势物候俱确切，不独诗格雄健，古人学问真实如此。
近代·高步瀛《唐宋诗举要》：宜看其兴象高华，不在追求字面。', 'center', 1417427506, '57b9331f165abd0054c17577', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10592, '送魏万之京', NULL, 146, 124, 3, 3, '李颀', NULL, 10124, '57b9a05e8ac2470063fdd3af', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383490.htm', '', '朝闻游子唱离歌，昨夜微霜初渡河。
鸿雁不堪愁里听，云山况是客中过。
关城树色催寒近，御苑砧声向晚多。
莫见长安行乐处，空令岁月易蹉跎。', '此诗意在抒发别离的情绪。首联用倒戟法落笔，点出出发前，微霜初落，深秋萧瑟；颔联写离秋，写游子面对云山，黯然伤神；颈联介绍长安秋色，暗寓此地不可长留；末联以长者风度，嘱咐魏万，长安虽乐，不要虚掷光阴，要抓紧成就一番事业。诗人把叙事、写景、抒情融合在一起，以自己的心情来设想、体会友人跋涉的艰辛，表现了诗人与友人之间深切的友情，抒发了诗人的感慨，并及时对友人进行劝勉。全诗自然真切，情深意长，遣词炼句尤为后人所称道。', '魏万：又名颢。唐高宗上元（西元六七四年—西元六七六年）初进士。曾隐居王屋山，自号王屋山人。
游子：指魏万。
离歌：离别的歌。
初渡河：刚刚渡过黄河。魏万家住王屋山，在黄河北岸，去长安必须渡河。
「鸿雁不堪愁里听，云山况是客中过。」句：设想魏万在途中的寂寞心情。
客中：即作客途中。
关城：指潼关。
树色：一作「曙色」，黎明前的天色。
催寒近：寒气越来越重，一路上天气愈来愈冷。
御苑：皇宫的庭苑。这里借指京城。
砧声：捣衣声。
向晚多：愈接近傍晚愈多。
「莫见长安行乐处」句：勉励魏万及时努力，不要虚度年华。
蹉跎：此指虚度年华。《说文新附》：「蹉跎，失时也。」', '清晨听到游子高唱离别之歌，昨夜下薄霜你一早渡过黄河。
怀愁之人最怕听到鸿雁鸣叫，云山冷寂更不堪落寞的过客。
潼关晨曦催促寒气临近京城，京城深秋捣衣声到晚上更多。
请不要以为长安是行乐所在，以免白白地把宝贵时光消磨。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929303048e64fbd912ba", "shortContent": "魏万后改名魏颢。他曾求仙学道，隐居王屋山。天宝十三载（754），因慕李白名，南下到吴、越一带访寻，最后在广陵（今江苏扬州）与李白相遇，计程不下三千里。李白很赏识他，并把自己的诗文让他编成集子，临别时，还写了一首《送王屋山人魏万还王屋》的长诗送他。魏万比李颀晚一辈，然而从此诗看，两人像是情意十分密切的“忘年交”。李颀晚年家居颍阳而常到洛阳，此诗可能就写于洛阳。\n一开首，“朝闻游子唱离歌”，先说魏万的...", "authors": ["姚奠中"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d0fe", "shortContent": "魏万后改名魏颢。他曾求仙学道，隐居王屋山。天宝十三载（754），因慕李白名，南下到吴、越一带访寻，最后在广陵（今江苏扬州）与李白相遇，计程不下三千里。李白很赏识他，并把自己的诗文让他编成集子，临别时，还写了一首《送王屋山人魏万还王屋》的长诗送他。魏万比李颀晚一辈，然而从此诗看，两人像是情意十分密切的“忘年交”。李颀晚年家居颍阳而常到洛阳，此诗可能就写于洛阳。\n\n一开首，“朝闻游子唱离歌”，先说魏万...", "authors": ["姚奠中"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d19330151fd", "shortContent": "魏万，诗人的晚辈朋友，曾隐居王屋山，号王屋山人。首句从眼前即景写起，交代时间、人物、事由。时间是清晨；事情是唱离歌，即道离别；人物身份是游子：由此确立了客中送客的主题。此时此景交代足，笔墨一宕到了昨天夜里。原来，这位即将远行的游子是昨天夜里专程赶来道别的。这番心意已足深厚，更何况是微霜，说明天气寒凉，而路途还要渡河。冒着风霜，跋山涉水，只是一夜就匆匆告别。不写送别多么不舍，仅从乘夜赶来短暂相聚话别...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127036c9ebcc6fbea1a3a6", "shortContent": "魏万，住在王屋山，号王屋山人。首句从眼前即景写起，交代时间、人物、事由。时间是清晨，事情是唱离歌，即道离别。人物身份是游子，由此确立了客中送客的主题。\n\n此时此景交代足，笔墨一宕到了昨天夜里。原来，这位即将远行的游子是昨天夜里专程赶来道别的。这番心意已足深厚，更何况是微霜，说明天气寒凉，而路途还要渡河。冒着风霜，跋山涉水，只是一夜就匆匆告别。不写送别多么不舍，仅从乘夜赶来短暂相聚话别一事，已经将深...", "authors": ["张春晓"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312706ac305cf0801816fe3", "shortContent": "首句从眼前即景写起，交代时间、人物、事由。时间是清晨，事情是唱离歌，即道离别。人物身份是游子，由此确立了客中送客的主题。\n\n此时此景交代足，笔墨一宕到了昨天夜里。原来，这位即将远行的游子是昨天夜里专程赶来道别的。这番心意已足深厚，更何况是微霜，说明天气寒凉，而且途中还要渡河。冒着风霜，跋山涉水，只是一夜就匆匆告别。不写送别多么不舍，仅从乘夜赶来短暂相聚话别一事，已经将深情厚谊写足。其下写难堪之情。...", "authors": ["张春晓"], "pressName": "崇文书局"}]', '《批点唐音》：此篇起语平平，接句便新，初联优柔，次联奇拔，结蕴可兴，含蓄不露，最为佳作。
《唐诗广选》：颐华玉曰：不知多少宛转。
《唐诗直解》：其致酸楚，其语流利。「近」字好，「多」字工。
《诗薮》：盛唐脍炙佳作，如李颀「朝闻游子唱离歌……」，「朝」、「曙」、「晚」、「暮」四字重用，惟其诗工，故读之不觉。然一经点勘，即为白璧之瑕，初学首所当戒。
《唐诗镜》：五六老秀，结语寄况无限。
《唐诗归》：鍾云：净亮无浮响，铢两亦称。谭云：起得清厉（首联后）。
《唐诗选脉会通评林》：何景明曰：多少宛转，诵之悠然。徐中行曰：词意大雅，爱情更深。蒋一葵曰：宛转流亮，愈玩愈工。
《唐风定》：高华俊亮，与摩诘各成一调。
《贯华堂选批唐才子诗》：质言之，只是如此四句（按指前四句），而其手法转接离即，妙至于此，真绝调也。
《唐诗归折衷》：唐云：逗漏大历气（「云山况是」句下）。
《唐诗贯珠笺释》：三承二，四承起，用虚字为脉，诸句皆灵活。五六笔承第二，言到京之景。
《此木轩五言律七言律诗选读本》：作者本自从喉中唱出，奈学舌头者多何？
《唐诗成法》：通首有缠绵之致。
《唐贤三昧集笺注》：景中情（首四句下）。此种和平之作，后人终拟不到，能辨此作，七律方有归宿处，可知庾词替语、剑拔弩张，二者皆非也。
《昭昧詹言》：《送魏万之京》言咋夜微霜游子，今朝渡河耳，却炼句入妙。中四情景交写，而语有次第。三四送别之情。五六渐次至京。收句勉其立身立名。初唐人只以意兴温婉轻轻赴题，不著豪情重语。杜公出，乃开雄奇快健，穷极笔势耳。
《诗境浅说》：此诗首二句平衍而已。三四句叙客况，句中以「不堪」、「况是」四字相呼应，遂见生动，与「江客不堪频北望，塞鸿何事亦南飞」同一句法。六句之向晚砧多，承五句关城寒近而来。收句谓此去长安当以功名自奋，勿以游乐自荒，绕朝赠策，犹有古风。', 'center', 1417427581, '57b9138dd342d3005ac7c53c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (50920, '苏幕遮', NULL, 0, 26, 0, 1, '高道宽', NULL, 11195, '5858e6398d6d810065c3153c', '元', 'ci', '词', NULL, NULL, '药无穷，频收采。丹鼎纯烹，一味通三昧。万法都无真个会。清静家风，最上为精粹。
付知音，偏可意。开口参同，方外生智慧。乾里圆明添活计。了见之时，衲被蒙头睡。', NULL, NULL, NULL, NULL, NULL, 'indent', 1529944450, '585cefbc1b69e6006cc9b9af', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10593, '送李少府贬峡中王少府贬长沙', NULL, 66, 259, 1, 1, '高适', NULL, 10126, '57b9bf2e165abd00661e158f', '唐', 'shi', '诗', 'http://baike.baidu.com/view/350108.htm', '', '嗟君此别意何如，驻马衔杯问谪居。
巫峡啼猿数行泪，衡阳归雁几封书。
青枫江上秋帆远，白帝城边古木疏。
圣代即今多雨露，暂时分手莫踌躇。', '此诗是诗人为送两位被贬官的友人而作，寓有劝慰鼓励之意。一诗同赠两人，内容铢两悉称。诗除了首尾合起来总写外，中间两联双双分写，不偏祜。颔联上句写巫峡风光，以古民谣典故来暗示李少府所去的峡中荒凉之地；下句写衡阳，暗示王少府去长沙，并希望他能多寄书函。颈联上句写长沙青枫江的帆船，是再写王少府；下句写白帝城，远在古原始森林的巴东，是再写李少府。双双交错进行，结构严密，情感交织。最后两句，是劝藉二人尽可放心而去，不久即可召还。全诗情感不悲观，也不消极。', '峡中：此指夔州巫山县（今属重庆）。
谪（zhé）居：贬官的地方。
巫峡：地名，在今重庆市巫山县东。古民谣《巴东三峡歌》：「巴东三峡巫峡长，猿鸣三声泪沾裳。」
衡阳：地名，今属湖南。相传每年秋天，北方的南飞之雁，至衡阳的回雁峰，便折回北方。这是由长沙想到衡阳，意思要王少府至长沙后多写信来。
青枫江：地名，在花溪。
秋帆：指秋风吹着小舟，送友人远去。', '此次离别不知你们心绪何如，停住马饮酒询问被贬的去处。
巫峡猿猴悲啼令人伤心流泪，衡阳的归雁会为我捎来回书。
秋日青枫江上孤帆远远飘去，白帝城边黄叶飘零古木稀疏。
圣明朝代如今定会多施雨露，暂时分手希望你们不要踌躇。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d1933015200", "shortContent": "送别之作往往满含依依不舍之情，然高适的送别诗却显得豁达、豪情，如“莫愁前路无知己，天下谁人不识君”（《别董大》）。这首送李、王二少府之作也是如此。少府是县尉，李、王二人皆不详事迹，峡中泛指四川东部。通观这首诗看不出送别之地在哪里，时节当在秋季，送别之不舍虽不无显露，但大体是劝慰。\n\n首联通过“嗟”、“意何如”、“问谪居”，表达了对李、王二少府遭受贬谪的同情，以及对分别的惋惜。接下来则通过工整的对句...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127055e6f69b71e93f6291", "shortContent": "送别之作往往满含依依不舍之情，然高适的送别诗却显得豁达、豪迈，如“莫愁前路无知己，天下谁人不识君”（《别董大》）。这首送二少府之作也是如此。少府是县尉，李、王二人皆不详事迹，峡中泛指四川东部一带。通观这首诗看不出送别之地在哪里，时节当在秋季，送别之不舍虽不无显露，但大体是劝慰。\n\n首联通过“嗟”、“意何如”、“问谪居”，表达了对李、王二少府遭受贬谪的同情，以及对分别的惋惜。接下来则通过工整的对句分...", "authors": ["刘晓亮"], "pressName": "崇文书局"}]', '盛传敏《碛砂唐诗纂释·卷二》：中联（指中间二联）以二人谪地分说，恰好切潭峡事，极工确，且就中便含别思。
《瀛奎律髓》：中四句指士俗所尚，末句开以早还，亦一体也。
《唐诗援》：似怨似嘲，大无聊赖。
《批选唐诗》：清宛流畅，不损天真。
《唐诗选》：中联以二人谪地分说，恰好切峡中、长沙事，何等工确，目就中便含别态。末复收拾，以应起句。
《唐诗选脉会通评林》：周珽曰：脉理计线错落，自不知所内来。周敬曰：造联天然巧制，结撰相慰情真。
《唐诗摘钞》：此虽律诗八句，其实一席老炼人情世故说话也。
《山满楼笺注唐诗七言律》：「驻译衔杯」一连五句，俱承「嗟君此别」来，惟其嗟之，是以问之，而巫峡、长沙种种不堪之景况，皆足令人扼腕，是朋友之情所必至也。「圣代」「即今」二句紧照「意何如」三字。唯其嗟之，是以宽之慰之，丁宁苦诚之。
《唐三体诗评》：「几封书」乃对「暂」字，五六则言瞻望伫立之情也。中二联工整中仍错综变换。
《唐体肤诠》：中四句景物如何分虚实先后？盖「巫峡」二句于景中寓事，便为实中之虚，且承谪居意下，其势宜在前；后联可不烦言而解矣。
《唐诗笺要》：只似送一人，唐人高脱处（首句下）。
《而庵说唐诗》：「青枫汗上秋天远，白帝城边古木疏」，青枫江在长沙，内帝城在峡中。峡中远，长沙近；工少府先到，李少府后到。计其到时、王少府当在秋尽，故云「秋天远」；李少府当在冬初，故云「古木疏」：真做到极尽义处。
《唐贤三昧集笺注》：唤起法，须知不可滑易。中四句不可全写景，后人便不管。第七句提振得起，到后来老杜「西蜀地形天下险」、「鱼龙寂寞秋江冷」，则更挥斥沉顿矣。
沈德潜《唐诗别裁》：连用四地名，究非律诗所宜。五六浑言之，斯善矣。
《瀛奎律髓汇评》：冯班：中二联从次句生下。何义门：中四句神往形留，直是与之俱去。结句才非世情常语，乃嗟惜之极致也。纪昀：通体清老，结更和平不逼。
《湘绮楼说诗》：「巫峡啼猿数行汨，衡阳归雁几封书」，二联选声配色，开晚唐一派。
高步瀛《唐宋诗举要》：吴汝纶曰：起得丰神（首句下）。又曰：分疏有色泽敷佐，便不枯寂（「巫峡啼猿」联下）。又曰：意思沉着。又曰：一气舒卷，复极高华朗曜，盛唐诗极盛之作。', 'center', 1417427915, '57b958d0128fe10054cc96a0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10594, '和贾至舍人早朝大明宫之作', NULL, 48, 394, 1, 2, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383494.htm', '', '绛帻鸡人报晓筹，尚衣方进翠云裘。
九天阊阖开宫殿，万国衣冠拜冕旒。
日色才临仙掌动，香烟欲傍衮龙浮。
朝罢须裁五色诏，佩声归到凤池头。', '此诗是唐代大诗人王维为唱和贾至的《早朝大明宫》而作的一首诗。诗中写了早朝前、早朝中、早朝后三个层次，利用细节描写和场景渲染，描绘了大明宫早朝时庄严华贵的气氛与皇帝的尊贵与威严。作为和诗，此诗不和韵，只和其意，用语堂皇，造句伟丽，格调和谐，独具特色。', '和：即和诗，是用来和答他人诗作的诗，依照别人诗词的格律或内容作诗词。可和韵，可不和韵。舍人：即中书舍人，时贾至任此职。大明宫：宫殿名，在长安禁苑南。
绛帻（jiànɡzé）：用红布包头似鸡冠状。鸡人：古代宫中，于天将亮时，有头戴红巾的卫士，于朱雀门外高声喊叫，好像鸡鸣，以警百官，故名鸡人。晓筹：即更筹，夜间计时的竹签。
尚衣：官名。隋唐有尚衣局，掌管皇帝的衣服。翠云裘（qiú）：饰有绿色云纹的皮衣。
九天：极言天之崇高广阔。古人认为天有九野、九重。此处借指帝宫。阊阖（chānghé）：天门，此处指皇宫正门。
衣冠：指文武百官。冕旒（miǎnliú）：古代帝王、诸侯及卿大夫的礼冠。旒，冠前后悬垂的玉串，天子之冕十二旒。这里指皇帝。
仙掌：掌为掌扇之掌，也即障扇，宫中的一种仪仗，用以蔽日障风。
衮（gǔn）龙：犹卷龙，指皇帝的龙袍。浮：指袍上锦绣光泽的闪动。
裁：拟写。五色诏：用五色纸所写的诏书。
到：一说“向”。
凤池：指凤凰池。', '韵译
头戴红巾的卫士不住报说寒夜欲晓，尚衣官员给天子呈上了翠绿的云裘。
早朝的百官曙色中走进辉煌的宫殿，同万国使节向加冕悬旒的皇帝叩头。
初出的日光晃动着君王的雉尾掌扇，浮动的香烟飘向了皇上的衮龙袍绣。
罢朝后把天子的圣旨写在五色纸上，紫服玉佩的中书文官此刻纷忙不休。
散译
戴着红巾的卫士在宫门报晓，尚衣官员向天子进上绣着翠云的皮袍。层层叠叠的宫殿如九重天门迤逦打开，异邦万国的使臣一齐向着皇帝跪见朝拜。日色刚刚照临到殿堂，仪仗已排列成扇形屏障。御炉中香烟袅袅，缭绕着天子的龙袍浮动飘忽。早朝过后中书省的官员退到凤凰池上，用五色彩纸起草皇上的诏书。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92967d0ac11454953715", "shortContent": "贾至写过一首《早朝大明宫》，全诗是：“银烛朝天紫陌长，禁城春色晓苍苍。千条弱柳垂青琐，百啭流莺满建章。剑佩声随玉墀步，衣冠身惹御炉香。共沐恩波凤池里，朝朝染翰侍君王。”当时颇为人注目，杜甫、岑参、王维都曾作诗相和。王维的这首和作，利用细节描写和场景渲染，写出了大明宫早朝时庄严华贵的气氛，别具艺术特色。\n诗一开头，诗人就选择了“报晓”和“进翠云裘”两个细节，显示了宫廷中庄严、肃穆的特点，给早朝制造气...", "authors": ["汤贵仁"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d1933015202", "shortContent": "乾元元年（758）的早朝，中书舍人（掌管草拟诏令）贾至写了一首《早朝大明宫呈两省僚友》，引起诸僚友的共鸣，于是杜甫、岑参、王维纷纷和作。通过一首同题之作，恰可见诸诗人的不同。\n\n玄宗天宝十四载（755）安禄山于范阳起兵，大唐王朝在一阵渔阳鼙鼓中开始渐渐远离盛世的荣耀。王维虽在乱中被迫接受了伪职，但因为一首《凝碧诗》，再加上其弟王缙削己官位以赎兄罪，肃宗遂宽免了他。乾元元年春，王维复官，责授太子中允...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312703bf2af4e09d55b6739", "shortContent": "乾元元年（758）的早朝，中书舍人（掌管草拟诏令）贾至写了一首《早朝大明宫呈两省僚友》，引起诸僚友的共鸣，于是杜甫、岑参、王维纷纷和作。通过一首同题之作，恰可见诸诗人诗风的不同。\n\n天宝十四载（755），安禄山于范阳起兵，大唐王朝在一阵渔阳鼙鼓中开始渐渐远离盛世的荣耀。王维虽在乱中被迫接受了伪职，但因为一首《凝碧诗》，再加上其弟王缙削己官位以赎兄罪，肃宗遂宽免了他。乾元元年春王维复官，责授太子中允...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "646470285b7b0d4f450fc408", "shortContent": "贾至写过一首《早朝大明宫》，全诗是：“银烛朝天紫陌长，禁城春色晓苍苍。千条弱柳垂青琐，百啭流莺满建章。剑佩声随玉墀步，衣冠身惹御炉香。共沐恩波凤池里，朝朝染翰侍君王。”当时颇为人注目，杜甫、岑参、王维都曾作诗相和。王维的这首和作，利用细节描写和场景渲染，写出了大明宫早朝时庄严华贵的气氛，别具艺术特色。\n\n诗一开头，诗人就选择了“报晓”和“进翠云裘”两个细节，显示了宫廷中庄严、肃穆的特点，给早朝制造...", "authors": ["汤贵仁"], "pressName": "上海辞书出版社"}]', '宋·刘辰翁《王孟诗评》：帖子语颇不痴重（“万国”句）。此为铺写，景象雄浑，富丽造作，句律温厚深长，皆足为法。
元·杨载《诗法家数》：荣遇之诗，要富贵尊严、典雅温厚。写意要闲雅美丽清细。如王维、贾至诸公《早朝》之作，气格雄深，句意严整，如宫商迭奏，音韵铿锵。真麟游灵沼，凤鸣朝阳也。学者熟之，可以一洗寒陋。后来诸公应诏之作，多用此体，然多志骄气盈。处富贵而不失其正者，几希矣。此又不可不知。
明·顾璘《批点唐音》：右丞此篇真与老杜颉颃，后惟岑参及之，它皆不及，盖气象阔大，音律雄浑，句法典重，用字清新，无所不备故也。或犹未全美，以用衣眼字太多耳。
明·李攀龙《唐诗直解》：王维曰“尚衣方进翠云裘”、“万国衣冠拜冕旒”，二公重字，不害为人家。
明·胡应麟《诗薮》：王、岑二作俱神妙，间未易优劣。昔人谓王服色太多，余以它句犹可，至“冕旒”、“衮龙”之犯，断不能为辞。
明·胡震亨《唐音癸签》：《早朝》四诗，名手汇此一题，觉右丞檀场，嘉州称亚，独老杜为滞钝无色。
明·周珽《唐诗选脉会通评林》：庙廊声响，自然庄重。
清·金圣叹《批选唐诗》：意象俱足、庄严稳祢，较胜诸作。
清·金圣叹《贯华堂选批唐才子诗》：此全依贾舍人样，前解通写早朝，后解专写两省也。若其中间措手义有不同者，贾乃于起一句便安“银烛朝天紫陌长”之七字，是预从“早”字，先已用意；于是而三四写“朝”字，便无过只是闲笔。此却于第四句始安“万国衣冠拜冕旒”之七字，是直到“朝”字，方乃用意；于是一二写“早”字亦无过只是闲笔。此则为两先生各自匠心也。
清·邢昉《唐风定》：雄浑天然。非初唐富丽之比。
清·毛先舒《诗辩坻》：典重可讽，而冕服为病。结又失严。
清·何焯《唐律偶评》：诸篇但叙入朝，此独从天子视朝之早发端，善变而有体。落句用裁诏收舍人，仍不离天子，是照应之密。
清·李因培《唐诗观澜集》：此诗如日月五星，光华灿烂。后人嗤点流传，以为用衣太多，此井蛙之见也。
清·屈复《唐诗成法》：“衣裳”字太多，前人已言之矣。“早朝”字未合写，亦一病。
清·沈德潜《唐诗别裁》：《早朝》倡和诗，右丞正大，嘉州明秀，有鲁、卫之目。贾作平平，杜作无朝之正位，不存可也。
清·赵臣瑗《山满楼笺注唐诗七言律》：并未别出手眼。而高华典赡，无美不备。
清·宋宗元《网师园唐诗笺》：博大昌明（“日色”句）。
清·纪昀《瀛奎律髓汇评》：盛丽极矣，字面太杂。才气驾驭，何尝觉杂？毕竟右丞第一。末句太犯，然名句相接便不觉。次联君臣两面都写到，所谓有体要也。精彩飞动，虽叠用衣佩字面，位置当在第二。
清·吴烶《唐诗选胜直解》：应制诗庄重典雅，斯为绝唱。
清·朱庭珍《筱园诗话》：“九天”、“冕旒”，气象阔大，而稍欠精切。', 'center', 1417428184, '57b9c0f35bbb500063f62a18', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10595, '奉和中书舍人贾至早朝大明宫', NULL, 42, 405, 1, 3, '岑参', NULL, 10096, '57b97daec4c971005593ac34', '唐', 'shi', '诗', 'http://baike.baidu.com/view/2189319.htm', '', '鸡鸣紫陌曙光寒，莺啭皇州春色阑。
金阙晓钟开万户，玉阶仙仗拥千官。
花迎剑佩星初落，柳拂旌旗露未干。
独有凤凰池上客，阳春一曲和皆难。', '此诗是以咏「早朝」为题的唱和诗，内容尽力铺设早朝的庄严隆重。诗围绕「早朝」两字作文章；「曙光」「晓钟」「星初落」「露未干」都切「早」字；而「金阙」「玉阶」「仙仗」「千官」「旌旗」，皆切「朝」字。末联点出酬和之意，推崇对方，表示谦卑，都恰到好处。', '和（hè）：即和诗，是用来和答他人诗作的诗，依照别人诗词的格律或内容作诗词。可和韵，可不和韵。
中书舍人：官名，时贾幼隣任此职。
大明宫：宫殿名，在长安禁苑南。
紫陌：指京师的街道。
曙（shǔ）光：破晓时的阳光。
啭（zhuàn）：婉转的叫声。
皇州：京都。
阑：尽。
金阙（què）：皇宫金殿。
万户：指皇宫中宫门。
玉阶：指皇宫中大明宫臺阶。
仙仗：天子的仪仗。
剑佩：带剑、垂佩绶，都为高官之饰物，此指禁卫军的武装。
旌（jīng）旗：旗帜的总称。
凤凰池上客：指贾幼隣。凤凰池，也称凤池，这裏指中书省。
阳春：古曲名，即宋玉《对楚王问》中提到的《阳春》《白雪》，「国中属而和者不过数十人」，後以之比喻作品高妙而懂得的人很少。', '【韵译】
雄鸡啼鸣京城曙色光寒，莺啼婉转皇宫春色正阑。
宫殿报晓钟声催开万户，玉石台阶仪仗拥簇千官。
花迎朝臣佩剑繁星初落，柳拂旌旗仙人盛露未干。
只有凤凰池上舍人诸客，阳春高雅一曲和歌皆难。
【散译】
雄鸡啼唱，大路上洒满黎明的寒光。黄莺鸟鸣声婉啭，京城处处是一派暮春景象。宫里的晓钟敲过，千门万户一齐开敞，天子的仪仗排列在玉阶两边，环拥着百官进入朝堂。殿前花色与佩剑的闪光交加辉映，天边的晨星纔刚刚消隐。飘扬的旌旗轻拂着柳枝，枝头还沾带着夜来的清露。凤凰池上歌一曲阳春白雪，谁想唱和可真会知难却步。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d1933015201", "shortContent": "岑参的这首和诗与贾至原作、王维和作从结构上基本一致：开始写早朝前，通过时间交代清楚；接着写宫殿的堂皇及群臣朝见天子的威仪；最后以凤池作结。且三诗各有千秋，难分轩轾。不过，若从整体上来看，岑参之作应在王、贾之上。\n\n首联通过听觉（“鸡鸣”、“莺啭”）、视觉（“春色阑”）、通感手法（由视觉之“曙光”而感“寒”）等多种角度、技巧来渲染早朝前的时间流转，在光与影、声与色的交织中烘托出早朝。\n\n接下来以长虹...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127068f2af4e09d55b6778", "shortContent": "岑参的这首和诗与贾至原作、王维和作在结构上基本一致：开始写早朝前的景象；接着写宫殿的堂皇及群臣朝见天子的威仪；最后以凤池作结。且三诗各有千秋，难分轩轾。不过，若从整体上来看，岑参之作应在王、贾之上。\n\n首联通过听觉（“鸡鸣”、“莺啭”）、视觉（“春色阑”）、通感手法（由视觉之“曙光”而感“寒”）等多种角度、技巧来渲染早朝前的时间流转，在光与影、声与色的交织中烘托出早朝前的气氛。故而，接下来以长虹贯...", "authors": ["刘晓亮"], "pressName": "崇文书局"}]', '宋·杨诚斋《诚斋诗话》：七言褒颂功德，如少陵、幼隣诸人倡和《早朝大明宫》，乃为典雅重大。和此诗者，岑嘉州云：「花迎剑佩星初落，柳拂旌旗露未干」，最佳。
元·方虚谷《瀛奎律髓》：四人早朝之作，俱伟丽可喜。
明·顾东桥《批点唐音》：岑嘉州最善七言，兴意音律不减王摩诘，乃盛唐宗匠。此篇颉颃王、杜，千古脍炙，贵乎皆见「早朝」二字。中间二联分大小景，结引故实，亲切条畅。
明·凌叔度《唐诗广选》：诸公倡和，此当为首，惜「寒」、「阑」、「干」、「难」四韵不佳耳。
明·胡元瑞《诗薮》：岑通章八句，皆精工整密，字字天成。颈联绚烂鲜明，早朝意宛然在目。独颔联虽绝壮丽，而气势迫促，遂至全篇音韵微乖。不尔，当为七言律冠矣。王起语意偏，不若岑之大体；结语思窘，不若岑之自然；颈联甚活，终未若岑之骈切；独颔联高华博大，而冠冕和乎，前後映带，遂令全首改色，称最当时。大概二诗力量相等，岑以格胜，王以调胜；岑以篇胜，王以句胜；岑极精严缜匝，王较宽裕悠扬。
明·陆仲昭《唐诗镜》：唐人《早朝》唯岑嘉州一首最为正当，亦语文悉称，但格力稍平耳。
明·唐仲言《唐诗解》：贾、杜、岑、王诗并入选，然岑、王矫不相下，舍人则雁行，少陵当退舍。盖「尺有所短，寸有所长」也。
明·周青羊《唐诗选脉会通评林》：「皇」、「紫」假对，「星」、「露」二字实诗眼。通篇心灵、脉融、语秀，作廊庙古衣冠法物，令人对之魂肃神敛。不特《早朝》诸什此为首唱，即举唐七律取为压卷，何让？诸家取唐七言律压卷者，或推崔司勋《黄鹤楼》，或推沈詹事《独不见》，或推杜工部「玉树雕残」、「明池水」、「老去悲秋」、「风急天高」等篇，然音响重薄，气格高下，前有确论。珽谓冠冕壮丽，无如嘉州《早朝》；淡雅幽寂，莫过右丞《积雨》。澹斋翁以二诗得廊庙、山林之神髓，欲取以压卷，直足空古准今。质之诸家，亦必以为然也。
清·康熙帝《增订评注唐诗正声》：雄浑足敌王、李，而神彩独胜。
清·邢石臼《唐风定》：早朝诗第一，在右丞上。杜公不足骖驾。
清·金圣叹《贯华堂选批唐才子诗》：此亦全依贾舍人样，前解通写早朝，後解专写两省也。若其争奇竞胜，义各有不同者：看他欲写千官人朝，却将一、二反先写千官未入朝时。夫千官未入朝时，则只须「鸡鸣」七字，便写「早」字无不已尽。而今又更别添「莺啭」七字者，意言风日如此韶丽，谁不诗情满抱？然而下朝以后，各供乃职，王事蹇蹇，竟成不暇，便早为结句「独有」字、「皆难」字，反衬出异样妙色。此又为右丞之所未到也（前四句）。五、六，不惟星落露干，只就看见花柳，便是朝散解严之役也。此时合殿千官，无不纷纷并散，而独有凤池诸客，共以和曲为难。呜呼！因读书得作官，既作官仍读书，言和曲虽难，然此难岂复他官之所有哉！（后四句）。
清·王船山《唐诗评选》：刻写入冥，如两镜之取影。《毛诗》：「庭燎有辉，言观其旂」，以状夜向晨之象，景外独绝。千裁后乃得「花迎剑佩」一联，星落乃知花之相迎，旌之拂柳也。《三百篇》后，不可无唐律者以此。
清·毛稚黄《诗辩坻》：嘉州句语停匀华净，而体稍轻飏，又结句承上，神脉似断。工部音节过厉，「仙桃」、「珠玉」近俚，结使事亦粘带，自下驷耳。四诗互有轩轾，予必贾、王、岑、杜为次也。
清·盛传敏《碛砂唐诗》：又闻研之者谓诸公倡和，此当为首，唯「寒」、「阑」、「干」、「难」四韵不佳。此虽不必泥，然应制作中最恐有人摘破也。
清·黄扶孟《唐诗摘钞》：此题贾幼隣首倡，王摩诘、杜子美、岑嘉州三人和之。贾作平平耳，王衣服字太多，杜五句遽云朝罢，稍觉伤促，固当推此作擅场。看他「紫陌」、「春色」、「莺」、「柳」、「剑佩」、「凤池」等字皆公然取之贾诗，则运用不同，气色迥别，与此作并观，低昂不待辨矣。结美其首倡，唐人和诗必如此。
清·何义门《唐律偶评》：倡和诸篇，斯为稍弱。又：「曙光」下接一「寒」字，早意生动。「皇州」以「黄」字借对，「紫陌」平起，却不觉其板。
清·吴昌祺《删定唐诗解》：此诗用意周密，格律精严，当为第一。「花迎」二句或谓为两截语，非也，盖言迎於星落之时，拂於露湛之际耳。「独」、「皆」二字相唤。
清·屈金粟《唐诗成法》：一明写「早」字；二暗写「朝」字，又点春时，三、四分写，五、六合写。七、八「和」，「独」、「皆」字又相呼应。题是「早朝」，「早」字最要紧，看其分合照应，花团锦簇，天衣无缝。诸早朝诗此首第一。
清·赵臣瑗《山满楼笺注唐诗七言律》：此诗亦是六句专写早朝，末联纔归重两省者。而其写早朝也，正大之中，复饶风致。其归重两省也，则专主称美贾舍人之作，虽各出手眼，固可并垂不朽。
清·黄牧村《唐诗笺注》：结语王、杜俱收到舍人，此独以和贾说，亦各见笔墨。
清·宋少光《网师园唐诗笺》：明丽。
清·纪晓岚《瀛奎律髓汇评》：此首当居第三。首联对句不觉。五、六两句不脱早朝。五、六句方说晓景，末二句如何突接？究竟仓皇少绪。此首虽不及杜，然较之於王，又觉通利，无夹杂之病。精工着题。论者推此为四诗之弁，然人工则跻极，天峻不可羁，当逊贾、王。
清·杨成栋《精选五七言律耐吟集》：如仙乐之竞作，似丹风之长鸣。
清·方仪卫《昭昧詹言》：起二句「早」字，三、四句大明宫早朝。五、六正写朝时。收和诗，匀称。原唱及摩诘、子美无以过之。
清·施均甫《岘佣说诗》：《和贾至舍人早朝》诗，究以岑嘉州为第一。「花迎剑佩」、「柳拂旌旗」，何等华贵自然！摩诘「九天阊阑」一联，失之廓落，少陵「九重春色醉仙桃」，更不妥矣。诗有一日短长，虽大手笔不免也。
清·胡愚溪《唐诗近体》：早朝倡和诗，明秀莫过於嘉州，王右丞亦正大，原倡平平，杜作无朝之正面，自是不及。
近代·高阆仙《唐宋诗举要》：庄雅秾丽，唐人律诗此为正格。', 'center', 1417428520, '57ba773ba633bd005d33e592', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10596, '奉和圣制从蓬莱向兴庆阁道中留春雨中春望之作应制', NULL, 57, 394, 1, 4, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383495.htm', '', '渭水自萦秦塞曲，黄山旧绕汉宫斜。
銮舆迥出千门柳，阁道回看上苑花。
云里帝城双凤阙，雨中春树万人家。
为乘阳气行时令，不是宸游玩物华。', '此诗是唐代大诗人王维写唐玄宗阁道出游的应制诗。从“望”字着笔，从广阔的空间展现长安宫阙的形胜之要，再写唐玄宗出游盛况：车驾穿过垂柳夹道的重重宫门，进入专用复道，车中观赏宫苑中的百花，皇城的巍峨壮丽，长安城的绿树浓阴、细细春雨，诗人心中当心怡气爽。全诗寥寥数语，尽显唐朝的盛大气象，笔势雄浑，色彩明丽，结构圆熟，被后人奉为应制诗的楷模。', '圣制：皇帝写的诗；蓬莱：宫名，谓大明宫；兴庆：兴庆宫，唐玄宗为诸王时以旧宅改建；唐代宫城位于长安东北，而大明宫又位于宫城东北。兴庆宫在宫城东南角。阁道：谓大明宫入曲江芙蓉园的复道。应制：指应皇帝之命而作。
渭水：即渭河，黄河最大支流，在陕西中部。
秦塞：谓长安城郊，古为秦地。塞：一作“甸”。这一带古时本为秦地。
黄山：黄麓山，在今陕西兴平县北。
汉宫：也指唐宫。
銮舆（luányú）：皇帝的乘舆。
迥出：远出。
千门：指宫内的重重门户。此句意谓銮舆穿过垂柳夹道的重重宫门而出。
上苑：泛指皇家的园林。
双凤阙：指大明宫含元殿前东西两侧的翔鸾、栖凤二阙。阙：宫门前的望楼。
阳气：指春气。
行时令：谓行迎春之礼。
宸（chén）游：指皇帝出游。宸：北辰所居，借指皇帝居处，后又引伸为帝王的代称。
物华：美好的景物。后两句意谓，皇帝本为乘此顺应时令，随阳气而宣导万物，并非只为赏玩美景。', '弯弯曲曲的渭水萦抱着秦塞，河边的黄山盘绕旧日的汉宫。
天子的车驾行走在半空中，远远高出宫门的柳丛。
从阁道上回身望去，御苑里繁花姹紫嫣红。
云雾弥漫，一切都显得缥缈，独有帝城有一双凤阙高耸突兀。
春雨绵绵，树色葱茏，掩映着千家万户。
天子出行并不是为了赏玩景物，乘着阳气要把农事的政令传布。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92967d0ac11454953714", "shortContent": "这首诗题中的蓬莱宫，即唐大明宫。唐代宫城在长安东北，而大明宫又在宫城东北。兴庆宫在宫城东南角。开元二十三年（735），从大明宫经兴庆宫，一直到城东南的风景区曲江，筑阁道相通。帝王后妃，可由阁道直达曲江。王维的这首七律，就是唐玄宗由阁道出游时在雨中春望赋诗的一首和作。所谓“应制”，指应皇帝之命而作。当时以同样题目写诗的，还有李憕等人，可以说是由唐玄宗发起的一次比较热闹的赛诗活动。\n王维的诗，高出众人...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d1933015203", "shortContent": "从这首诗的题目可以看出，首先“奉和”两字说明这是一首奉命酬和之作，其次从“圣制”二字可以看出所酬和的是皇帝的一首诗。诗题中的蓬莱指的是唐大明宫，在皇宫的东北方；兴庆也是宫名，在长安城东南。据《旧唐书•地理志》载，大明宫经兴庆宫至曲江芙蓉园，有夹城复道相通。另诗题中的“圣”指的是唐玄宗，王维所和之作是唐玄宗由阁道出游时雨中春望所赋的诗。\n\n首联从大处着眼，先写出了唐长安城的地理位置。“秦塞”指长安，...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270447ccdb86c49f2922c", "shortContent": "从这首诗的题目来看，首先“奉和”两字说明这是一首奉命酬和之作，其次从“圣制”二字可以看出所酬和的是皇帝的一首诗。诗题中的蓬莱指的是唐大明宫，在皇宫的东北方；兴庆也是宫名，在长安城东南。据《旧唐书•地理志》载，大明宫与兴庆宫之间，有夹城复道相通。另诗题中的“圣”指的是唐玄宗，王维所和之作是唐玄宗一首描写雨中春望的诗。\n\n首联从大处着眼，先写出了唐长安城的地理位置。“秦塞”指长安一带，因长安古属秦地，...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "64646ffbc0471b0062cba8fa", "shortContent": "这首诗题中的蓬莱宫，即唐大明宫。唐代宫城在长安东北，而大明宫又在宫城东北。兴庆宫在宫城东南角。开元二十三年(735)，从大明宫经兴庆宫，一直到城东南的风景区曲江，筑阁道相通。帝王后妃，可由阁道直达曲江。王维的这首七律，就是唐玄宗由阁道出游时在雨中春望赋诗的一首和作。所谓“应制”，指应皇帝之命而作。当时以同样题目写诗的，还有李憕等人，可以说是由唐玄宗发起的一次比较热闹的赛诗活动。\n\n王维的诗，高出众...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}]', '', 'center', 1417428599, '57b9047e0a2b58005c925b2c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10597, '积雨辋川庄作', NULL, 209, 394, 2, 6, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/154760.htm', '', '积雨空林烟火迟，蒸藜炊黍饷东菑。
漠漠水田飞白鹭，阴阴夏木啭黄鹂。
山中习静观朝槿，松下清斋折露葵。
野老与人争席罢，海鸥何事更相疑。', '此诗描写辋川山庄久雨初停时的景色，前四句写诗人静观所见，后四句写诗人的隐居生活。诗人把自己幽雅清淡的禅寂生活与辋川恬静优美的田园风光结合起来描写，创造了一个物我相惬、情景交融的意境。全诗如同一幅淡雅的水墨画，清新明净，形象鲜明，表现了诗人隐居山林、脱离尘俗的闲情逸致。', '积雨：久雨。
辋（wǎng）川庄：即王维在辋川的宅第，在今陕西蓝田终南山中，是王维隐居之地。
空林：疏林。唐·孟浩然《题大禹寺义公禅房》诗：「义公习禅处，结宇依空林。」
烟火迟：因久雨林野润湿，故烟火缓升。
藜（lí）：一年生草本植物，嫩叶可食。
黍（shǔ）：谷物名，古时为主食。
饷东菑（zī）：给在东边田里干活的人送饭。饷，送饭食到田头。菑，已经开垦了一年的田地，此泛指农田。
漠漠：形容广阔无际。唐·罗隐《省试秋风生桂枝》诗：「漠漠看无际，萧萧别有声。」
阴阴：幽暗的样子。唐·李端《送马尊师》诗：「南入商山松路深，石床溪水昼阴阴。」
夏木：高大的树木，犹乔木。夏：大。
啭（zhuàn）：小鸟婉转的鸣叫。鸟的宛转啼声。
黄鹂：黄莺。
习静：谓习养静寂的心性。亦指过幽静生活。南朝梁·何逊《苦热》诗：「习静閟衣巾，读书烦几案。」
槿（jǐn）：植物名。落叶灌木，其花朝开夕谢。古人常以此物悟人生枯荣无常之理。其花早开晚谢。故以此悟人生荣枯无常之理。
「山中习静观朝槿」句：意谓深居山中，望着槿花的开落以修养宁静之性。
清斋：谓素食，长斋。晋·支遁《五月长斋》诗：「令月肇清斋，德泽润无疆。」
露葵：经霜的葵菜。葵为古代重要蔬菜，有「百菜之主」之称。
野老：村野老人，此指作者自己。
争席罢：指自己要隐退山林，与世无争。争席：典出《庄子·杂篇·寓言》：杨朱去从老子学道，路上旅舍主人欢迎他，客人都给他让座；学成归来，旅客们却不再让座，而与他「争席」，说明杨朱已得自然之道，与人们没有隔膜了。
「海鸥何事更相疑」句：典出《列子·黄帝篇》：海上有人与鸥鸟相亲近，互不猜疑。一天，父亲要他把海鸥捉回家来，他又到海滨时，海鸥便飞得远远的，心术不正破坏了他和海鸥的亲密关系。这里借海鸥喻人事。何事，一作「何处」。', '连日雨后，树木稀疏的村落里炊烟冉冉升起。烧好的粗茶淡饭是送给村东耕耘的人。
广阔平坦的水田上一行白鹭掠空而飞；田野边繁茂的树林中传来黄鹂宛转的啼声。
我在山中修身养性，观赏朝槿晨开晚谢；在松下吃着素食，和露折葵不沾荤腥。
我已经是一个从追名逐利的官场中退出来的人，而鸥鸟为什么还要猜疑我呢？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92972e6a6b501f95bf4d", "shortContent": "辋川庄，在今陕西蓝田终南山中，是王维隐居之地。《旧唐书·王维传》记载：“维兄弟俱奉佛，居常蔬食，不茹荤血，晚年长斋，不衣文彩。”在这首七律中，诗人把自己幽雅清淡的禅寂生活与辋川恬静优美的田园风光结合起来描写，创造了一个物我相惬、情景交融的意境。\n“积雨空林烟火迟，蒸藜炊黍饷东菑。”首联写田家生活，是诗人山上静观所见：正是连雨时节，天阴地湿，空气潮润，静谧的丛林上空，炊烟缓缓升起来，山下农家正烧火做...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc40926", "shortContent": "辋川庄，在今陕西蓝田终南山中，是王维隐居之地。《旧唐书·王维传》记载：“维兄弟俱奉佛，居常蔬食，不茹荤血，晚年长斋，不衣文彩。”在这首七律中，诗人把自己幽雅清淡的禅寂生活与辋川恬静优美的田园风光结合起来描写，创造了一个物我相惬、情景交融的意境。\n\n“积雨空林烟火迟，蒸藜炊黍饷东菑。”首联写田家生活，是诗人山上静观所见：正是连雨时节，天阴地湿，空气潮润，静谧的丛林上空，炊烟缓缓升起来，山下农家正烧火...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d1933015204", "shortContent": "论及王维七言律的特色，明代的许学夷说：“摩诘七言律亦有三种：有一种宏赡雄丽者，有一种华藻秀雅者，有一种淘洗澄净者。”（《诗源辩体》）清代的施补华在其《岘佣说诗》中引用许印芳的话说：“摩诘七律，有高华一体，有清远一体，皆可效法。”又近代的陈衍谓其七律兼有“华丽、雄壮、清适三种笔意”（《石遗室诗话》）。“淘洗澄净”、“清远”和“清适”是一个意思，都抓住了王维诗“清”的一面。而王维又笃信禅宗，在参禅悟道...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270447ccdb86c49f2922f", "shortContent": "论及王维七言律的特色，明代的许学夷说：“摩诘七言律亦有三种：有一种宏赡雄丽者，有一种华藻秀雅者，有一种淘洗澄净者。”（《诗源辩体》）清代的施补华在其《岘佣说诗》冲引用许印芳的话说：“摩诘七律，有高华一体，有清远一体，皆可效法。”又近代的陈衍谓其七律兼有“华丽、雄壮、清适三种笔意”（《石遗室诗话》）。“淘洗澄净”、“清远”和“清适”是一个意思，都抓住了王维诗“清”的一面。而王维又笃信禅宗，在参禅打坐...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127078f2af4e09d55b679d", "shortContent": "论及王维七言律的特色，明代的许学夷说：“摩诘七言律亦有三种：有一种宏赡雄丽者，有一种华藻秀雅者，有一种淘洗澄净者。”（《诗源辩体》）清代的施补华在其《岘佣说诗》中引用许印芳的话说：“摩诘七律，有高华一体，有清远一体，皆可效法。”又近代的陈衍谓其七律兼有“华丽、雄壮、清适三种笔意”（《石遗室诗话》）。“淘洗澄净”、“清远”和“清适”是一个意思，都抓住了王维诗“清”的一面。而王维又笃信禅宗，在参禅打坐...", "authors": ["刘晓亮"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "64647726b6a81d0c53f24a98", "shortContent": "辋川庄，在今陕西蓝田终南山中，是王维隐居之地。《旧唐书·王维传》记载：“维兄弟俱奉佛，居常蔬食，不茹荤血，晚年长斋，不衣文彩。”在这首七律中，诗人把自己幽雅清淡的禅寂生活与辋川恬静优美的田园风光结合起来描写，创造了一个物我相惬、情景交融的意境。\n\n“积雨空林烟火迟，蒸藜炊黍饷东菑。”首联写田家生活，是诗人山上静观所见：正是连雨时节，天阴地湿，空气潮润，静谧的丛林上空，炊烟缓缓升起来，山下农家正烧火...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}]', '《石林诗话》：诗下双字极难，须是七言、五言之间除去五字、三字外，精神兴致全见于两言，方为工妙。唐人谓「水田飞白鹭，夏木啭黄鹂」为李嘉祐诗，摩诘窃取之，非也。此两句好处，正在添「漠漠」、「阴阴」四字，此乃摩诘为嘉祐点化，以自见其妙，如李光弼将郭子仪军，一号令之，精彩数倍。
《王孟诗评》：写景自然，造语又极辛苦。顾云：结语用庄子忘机之事，无迹，此诗首述田家时景。次述己志空泊，末写事实，又叹俗人之不知己也。东坡云：摩诘「诗中有画，画中有诗」者，此耳。
《增订评注唐诗正声》：周云：妙在四叠字，易此便如嚼蜡。
《批点唐诗正声》：「水田飞白鹭，夏木啭黄鹂」，人皆能为，比诸惟下「漠漠」、「阴阴」四字，诗意便胜。
《唐诗归》：钟云：「烟火迟」又妙于烟火新，然非积雨说不出（「积雨空林」句下）。谭云：悟矣（「山中习静」句下）。
《唐诗选脉会通评林》：周敬曰：清脱无尘，出世人语。摩诘诗往往多道气，要非寻常韵律间者。周珽曰：全从真景真趣摹写，灵机秀色，读之如在镜中游。陈继儒曰：语气殊静，蒋一梅曰：用事切题，做法更不可移动。
《唐诗贯珠笺释》：第二承烟火也。三四雨后之景，用叠字独能句圆神旺。五言看破荣枯，六言甘于清虚。
《碛砂唐诗》：敏曰：今人每用叠字，非惟觉得单弱，且与全句精神俱失。试观此联，偏似无此叠字，径直无情，加此叠字，情景活现，则用叠字之法具在矣。况乎七言最忌五言句泛加二字，惟此真是七字句，并非五言泛加二字也（「漠漠水田」一联下）。
《唐三体诗评》：悟富贵之无常，乃弥陈于藿食，无妨为农没世，人鸥群而不乱也。五六递对，无复笔墨之痕。
《历代诗法》：诗中写生画手，人境皆活，耳目长新，真是化机在掌握矣。
《唐贤三昧集笺注》：顾云：下「迟」字妙。又云：三四自然如画。又云：此必有为而云，游思悠远恬澹，胸中绝无微尘。
《昭昧詹言》：此题命脉，在「积雨」二字。起句叙题。三四写景极活现，万古不磨之句。后四句，言己在庄上。事与情如此。
《唐宋诗举要》：方曰：写景极活现（「阴阴夏木」句下）。赵松谷曰：淡雅幽寂。', 'center', 1417443219, '57b90862df0eea0063351ae2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10600, '野望', NULL, 88, 1416, 1, 2, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383525/10504564.htm', '', '西山白雪三城戍，南浦清江万里桥。
海内风尘诸弟隔，天涯涕泪一身遥。
惟将迟暮供多病，未有涓埃答圣朝。
跨马出郊时极目，不堪人事日萧条。', '这首诗虽是写郊游野望的感触，忧家忧国，伤己伤民的感情，迸溢于字里行间。诗的首联写从高低两处望见的景色。颔联是抒情，由野望想到兄弟的飘散和自我孤身浪迹天涯。颈联继续抒写迟暮多病不能报效国家之感。末联以出郊极目，点明主题「野望」，以人事萧条总结中间两联。全诗感情真挚，语言淳朴。', '西山：在成都西，主峰雪岭终年积雪。三城：指松（今四川松潘县）、维（故城在今四川理县西）、保（故城在理县新保关西北）三州。
城：一作「年」，一作「奇」。
戍：防守。三城为蜀边要镇，吐蕃时相侵犯，故驻军守之。
南浦：南郊外水边地。
清江：指锦江。
万里桥：在成都城南。蜀汉费祎访问吴国，临行时曾对诸葛亮说：「万里之行，始于此桥。」这两句写望。
风尘：指安史之乱导致的连年战火。
诸弟：杜甫四弟：颖、观、丰、占。唯杜占随他入蜀，其他三弟都散居各地。
迟暮：这时杜甫年五十。
供多病：交给多病之身了。供，付托。
涓埃：滴水、微尘，指毫末之微。
日：一作「自」。', '西山白雪皑皑护卫三城重镇，南浦边清江水长横跨万里桥。
四海之内战火不断兄弟失散，只身远在天涯不禁涕泪涟涟。
迟暮之年只有一身疾病相伴，未有丝毫劳绩报答圣明朝廷。
骑马来到郊外不住纵目远望，世事日益萧条令人悲伤怅惘。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d1933015208", "shortContent": "此诗作于肃宗上元二年（761），杜甫时在成都。\n\n首联对仗工稳。西山在成都之西，因常年积雪，又称雪岭，杜甫另有诗云“窗含西岭千秋雪”（《绝句四首》），彼处的“西岭”也就是这里的西山。三城，指松、维、堡三城，为唐代备御吐蕃所修的军城。这一句是写从城郊西望所见的远景，下句则写近景。城南有清水河流过，有江有浦，并能看见中和门外的万里桥。这两句诗实写远近之景，又另有他意：前者见西山白雪而思三城戍（唐备吐蕃...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '', 'center', 1417443717, '57b8f17ba633bd00665ceb48', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10601, '登楼', NULL, 184, 1416, 2, 7, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/151503/6164753.htm', '', '花近高楼伤客心，万方多难此登临。
锦江春色来天地，玉垒浮云变古今。
北极朝廷终不改，西山寇盗莫相侵。
可怜后主还祠庙，日暮聊为梁甫吟。', '此诗是一首感时抚事的诗。作者写登楼望见无边春色，想到万方多难，浮云变幻，不免伤心感喟。进而想到朝廷就像北极星座一样，不可动摇，即使吐蕃入侵，也难改变人们的正统观念。最后坦露了自己要效法诸葛亮辅佐朝廷的抱负，大有澄清天下的气概。
全诗寄景抒情，写登楼的观感，俯仰瞻眺，融山川古迹、个人情思为一体，语壮境阔，寄慨遥深，都从空间着眼，体现了诗人沉郁顿挫的艺术风格。', '客心：客居者之心。
登临：登高观览。临，从高处往下看。
锦江：即濯锦江，流经成都的岷江支流。成都出锦，锦在江中漂洗，色泽更加鲜明，因此命名濯锦江。
来天地：与天地俱来。
玉垒：山名，在四川灌县西、成都西北。变古今，与古今俱变。
玉垒浮云变古今：是说多变的政局和多难的人生，捉摸不定，有如山上浮云，古往今来一向如此。
北极：星名，北极星，古人常用以指代朝廷。
终不改：终究不能改，终于没有改。
西山：指今四川省西部当时和吐蕃交界地区的雪山。
寇盗：指入侵的吐蕃集团。
“北极朝廷终不改，西山寇盗莫相侵。”句：这位两句是说唐代政权是稳固的，不容篡改，吐蕃还是不要枉费心机，前来侵略。唐代宗广德年间九月，吐蕃军队东侵，泾州刺史高晖投降吐蕃，引导吐蕃人攻占唐都长安，唐代宗东逃陕州。十月下旬，郭子仪收复长安。十二月，唐代宗返回京城。同年十二月，吐蕃人又向四川进攻，占领了松州、维州等地。
后主：刘备的儿子刘禅，三国时蜀国之后主。曹魏灭蜀，他辞庙北上，成亡国之君。
还祠庙：意思是，诗人感叹连刘禅这样的人竟然还有祠庙。这事借眼前古迹慨叹刘禅荣幸佞臣而亡国，暗讽唐代宗信用宦官招致祸患。成都锦官门外有蜀先主（刘备）庙，西边为武侯（诸葛亮）祀，东边为后主祀。还，仍然。
聊为：不甘心这样做而姑且这样做。
梁甫吟：古乐府中一首葬歌。这里代指此诗。。《三国志》说诸葛亮躬耕陇亩，好为《梁甫吟》。借以抒发空怀济世之心，聊以吟诗以自遣。这里的《梁甫吟》即指这首诗。', '登上高楼满怀伤感看繁花，万方多艰难令人触目惊心。
在这战乱时候我登上此楼，世事如玉垒山变幻的浮云。
圣朝就像北极星永保气运，盗寇侵河山只能徒劳兴叹。
可怜后主只剩祠庙可归还，姑且在黄昏时吟诵《梁甫吟》。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ae0f8fda556505545c", "shortContent": "这首诗写于成都，时在代宗广德二年（764）春，诗人客蜀已是第五个年头。上年正月，官军收复河南河北，安史之乱平定；十月便有吐蕃陷长安、立傀儡、改年号，代宗奔陕州事；随后郭子仪复京师，乘舆反正；年底吐蕃又破松、维、保等州（在今四川北部），继而再陷剑南、西山诸州。诗中“西山寇盗”即指吐蕃；“万方多难”也以吐蕃入侵为最烈，同时，也指宦官专权、藩镇割据、朝廷内外交困、灾患重重的日益衰败景象。\n首联提挈全篇，...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a80", "shortContent": "这首诗写于成都，时在代宗广德二年（764）春，诗人客蜀已是第五个年头。上年正月，官军收复河南河北，安史之乱平定；十月便有吐蕃陷长安、立傀儡、改年号，代宗奔陕州事；随后郭子仪复京师，乘舆反正；年底吐蕃又破松、维、保等州（在今四川北部），继而再陷剑南、西山诸州。诗中“西山寇盗”即指吐蕃；“万方多难”也以吐蕃入侵为最烈，同时，也指宦官专权、藩镇割据、朝廷内外交困、灾患重重的日益衰败景象。\n\n首联提挈全篇...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d193301520b", "shortContent": "“登楼”是诗人们笔下常见的题目，即景抒怀，伤时而又自伤，也是常见的表现手法。但读杜甫这首《登楼》总会觉得不同一般，那深沉丰厚的思想感情和炉火纯青的艺术技巧，总令人低回吟咏于无穷。\n\n诗的前两联侧重叙事和写景，但不是单纯的叙述和描写，而是带着浓厚的主观感情色彩，从而使景语化为情语，让读者触景生情。诗的后两联侧重抒怀，但所抒思想感情又是因登楼所见景物触发的，让人觉得真实可信，从而和作者的思想感情产生强...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270617f0b9738b369b1fa", "shortContent": "“登楼”是诗人们笔下常见的题目，即景抒怀，伤时而又自伤，也是常见的表现手法。但读杜甫这首《登楼》总会觉得不同一般，那深沉丰厚的思想感情和炉火纯青的艺术技巧，总令人低回吟味于无穷。\n\n诗的前两联侧重叙事和写景，但不是单纯的叙述和描写，而是带着浓厚的主观感情色彩，从而使景语化为情语，让读者触景生情。诗的后两联侧重抒怀，但所抒思想感情又是因登楼所见景物触发的，让人觉得真实可信，从而和作者的思想感情产生强...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "646606905b7b0d4f4516e7e5", "shortContent": "这首诗写于成都，时在代宗广德二年（764）春，诗人客蜀已是第五个年头。上年正月，官军收复河南河北，安史之乱平定；十月便有吐蕃陷长安、立傀儡、改年号，代宗奔陕州事；随后郭子仪复京师，乘舆反正；年底吐蕃又破松、维、保等州（在今四川北部），继而再陷剑南、西山诸州。诗中“西山寇盗”即指吐蕃；“万方多难”也以吐蕃入侵为最烈，同时，也指宦官专权、藩镇割据、朝廷内外交困、灾患重重的日益衰败景象。\n\n首联提挈全篇...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}]', '《石林诗话》：七言难于气象雄浑，句中有力，而纡徐不失言外之意。自老杜“锦江春色来天地，玉垒浮云变古今”与“五更鼓角声悲壮，三峡星河影动摇”等句之后，常恨无复继者。
《瀛奎律髓》：老杜七言律诗一百五十九首，当写以常玩，不可暂废。今“登览”中选此为式。“锦江”、“玉垒”一联，景中寓情；后联却明说破，道理如此，岂徒模写江山而已哉！
《唐诗品汇》：刘云：“先主庙中乃亦有后主，此亡国者何足祠！徒使人思诸葛《梁父》之恨而已。《梁甫吟》亦兴废之感也。武侯以之。”
《唐诗归》：谭云：“常人以‘花近高楼’，何伤心之有？心亦有粗细雅俗，非其人不知。”鍾云：“对花伤心，亦诗中常语，情景生于‘近高楼’三字（首句下）。”鍾云：“动不得，却不板样（‘锦江春色’二句下）。”鍾云：“七字蓄意无穷（‘可怜后主’句下）。”
《杜臆》：此诗妙在突然而起，情理反常，令人错愕；而伤之故，至末始尽发之，时竟不使人知，此作诗者之苦心也……首联写登临所见，意极愤懑，词犹未露，此亦急来缓受，文法固应如是。言锦江春水与天地俱来，而玉垒云浮与古今俱变，俯视宏阔，气笼宇宙，可称奇杰。而佳不在是，止借作过脉起下。云“北极朝廷”如锦江水源远流长，终不为改；而“西山寇盗”如玉垒浮云，悠起悠灭，莫来相侵。……“终”、“莫”二字有微意在。
《瀛奎律髓汇评》：冯班：“拘情景便非高手。”查慎行：“发端悲壮，得笼罩之势。”纪昀：“何等气象！何等寄托！如此种诗，如日月终古常见而光景常新。”无名氏（乙）：“起情景悲辏，三、四壮丽不板，五、六忠赤生动，结苍深，一字不懈，殆亦可冠长句。”
《唐诗镜》：三、四空头，且带俚气，凡说豪、说霸、说高、说大、说奇、说怪，皆非本色，皆来人憎。第五句有疵，结二语浑浑大家。
《杜诗集评》：李因笃云：“造意大，命格高，真可度越诸家。”
《唐诗训解》：起二句呼应。后六句皆所以伤心之实。因登楼而望西北，上句有兴亡之感，落句公以自况。
《唐诗选脉会通评林》：周敬曰：“三、四宏丽奇幻，结含意深浑，自是大家”，蒋一葵曰：“起二句呼应，后六句皆所以伤心之实。第三句野马絪缊，极自万里；第四句苍狗变化，瞬息千年。五、六因登楼而望西北，末上句有兴亡之感，落句自况。”徐中行曰：“天地、古今，直包括许多景象情事。”郭浚曰：“此诗悲壮，句句有力，须看他用字之妙。”黄家鼎曰：“触时感事，一读一悲怆。”周珽曰：“酸心之语，惊心之笔，落纸自成悲风凄雨之状。”
《唐风定》：胸中阔大，亦自诸家不及。
《杜诗详注》：朱瀚曰：“俯视江流，仰观山色，矫首而北，矫首而西，切登楼情事；又登楼以望荒祠，因念及卧龙一段忠勤，有功于后主，伤今无是人，以致三朝鼎沸，寇盗频仍，遂彷徨徙倚，至于日暮，犹为《梁甫吟》，而不忍下楼，其自负亦可见矣。”
《唐诗归折衷》：吴敬夫云：“气色语，然已藏下感时意矣（‘玉垒浮云’句下）。”唐士雅云：“警吐蕃须峻，三字甚健。”敬夫云：“词气太婉，于情事未称（‘西山寇盗’句下）。”
《唐诗贯珠》：五、六与“今”字有血脉，结则吊古之意。
《唐宋诗醇》：申涵光曰：“‘北极’、‘南山’二语，可抵一篇《王命论》。”
《唐诗别裁》：气象雄伟，笼盖宇宙，此杜诗之最上者。
《杜诗镜铨》：首二句倒装突兀。李子德云：“造意大，命格高，真可度越诸家。”吴东岩曰：“‘可怜’字、‘还’字、‘聊为’字，伤心之故，只在吞吐中流出。”
《唐诗近体》：律法甚细，隐衷极厚，不独以雄浑高阔之象，陵轹千古。妙在倒装（“花近高楼”二句下）。
《增订唐诗摘钞》：次句只了“伤客心”三字。下最难接。看此词句浑雅，而兴韵无亏，绝不堕怒骂一流。首二句在后人必云：“花近高楼此一临，万方多难客伤心。”盖不知唐贤运意曲折，造句参差之妙耳。若尾联之寓意保曲，更万非所及。全诗以“伤客心”三字作骨。
《网师园唐诗笺》：雄浑天成，茏罩一切。钱笺谓代宗任用程元振、鱼朝恩致蒙尘之祸，故以后主之任黄皓比之。
《历代诗法》：虚处取神，其实一字不闲投，逐句接递，故为奇绝。
《岘佣说诗》：起得沉厚突兀。若倒装一转，“万方多难此登临，花近高楼伤客心”，便是平调。此秘决也。
《唐七律选》：自“花近高楼”起便意兴勃发。下句虽奇廓，然故平实有至理，总是纵横千万里，上下千百年耳（首四句下）。', 'center', 1417443875, '57b96601c4c971005592b9d6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10602, '宿府', NULL, 75, 1416, 3, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/151535.htm', '', '清秋幕府井梧寒，独宿江城蜡炬残。
永夜角声悲自语，中庭月色好谁看。
风尘荏苒音书绝，关塞萧条行路难。
已忍伶俜十年事，强移栖息一枝安。', '此诗是依人作客，抒写旅愁，有一种百无聊赖之情。前四句写景，后四句抒情。首联写独宿江城，环境清寒；颔联写“独宿”的所闻所见；颈联写战乱未息，处世艰难；末联写漂泊十年，如今暂且栖安。全诗表达了作者悲凉深沉的情感，流露了怀才不遇的心绪。', '府：幕府。古代将军的府署。杜甫当时在严武幕府中。
井梧：梧桐。叶有黄纹如井，又称金井梧桐。梧，一作“桐”。
炬：一作“烛”。
“永夜角声悲自语”句：意谓长夜中唯闻号角声像在自作悲语。永夜，整夜；自语，自言自语。
中庭：一作“中天”，半空之中。
风尘荏苒：指战乱已久。荏苒，犹辗转，指时间推移。
关塞：边关、边塞。
萧条：寂寞冷落、凋零。
伶俜（pīng）：流离失所。
十年事：杜甫饱经丧乱，从天宝十四年（公元755年）安史之乱爆发至作者写诗之时，正是十年。
“强移栖息一枝安”句：用《庄子·逍遥游》“鹪鹩巢于深林，不过一枝”意，喻自己之入严幕，原是出于为一家生活而勉强以求暂时的安居。强移，勉强移就；一枝安，指他在幕府中任参谋一职。', '金井梧桐在秋夜的风中抖动，只有蜡烛残光照着孤单的我。
长夜里号角声悲壮似在自语，天空中的月色虽好谁与我共赏。
光阴荏苒哪里寻觅亲人音信？关塞一片萧条寻找归路艰难。
我已忍受十年的飘零生活，把家安在这里不过勉强栖身。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ae5914587d02f4e7e3", "shortContent": "代宗广德二年（764）六月，新任成都尹兼剑南节度使严武保荐杜甫为节度使幕府的参谋。做这么个参谋，每天天刚亮就得上班，直到夜晚才能下班。杜甫家住成都城外的浣花溪，下班后来不及回家，只好长期住在府内。这首诗，就写于这一年的秋天。所谓“宿府”，就是留宿幕府的意思。因为别人都回家了，所以他常常是“独宿”。\n首联倒装。按顺序说，第二句应在前。其中的“独宿”二字，是一诗之眼。“独宿”幕府，眼睁睁地看着“蜡炬残...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d193301520c", "shortContent": "此诗作于广德二年（764），杜甫当时在剑南节度使严武的幕府。严武是杜甫的好友严挺之子，杜甫刚到蜀中，孤苦无依，严武入蜀为节度后，照顾了这位父亲的老友，杜甫过了几年比较安定的生活。本诗就是杜甫夜宿于严武的幕府，感怀而作。\n\n“清秋幕府井梧寒”，首句即勾勒出清秋高爽之景，井边的梧桐，在寒风中瑟瑟作响，带来了秋天的萧瑟之意。此时，杜甫独宿江城，桌上蜡烛已经烧残，可见夜色已晚。四处俱静，可杜甫却毫无睡意。...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "64660887b6a81d0c53f97173", "shortContent": "代宗广德二年（764）六月，新任成都尹兼剑南节度使严武保荐杜甫为节度使幕府的参谋。做这么个参谋，每天天刚亮就得上班，直到夜晚才能下班。杜甫家住成都城外的浣花溪，下班后来不及回家，只好长期住在府内。这首诗，就写于这一年的秋天。所谓“宿府”，就是留宿幕府的意思。因为别人都回家了，所以他常常是“独宿”。\n\n首联倒装。按顺序说，第二句应在前。其中的“独宿”二字，是一诗之眼。“独宿”幕府，眼睁睁地看着“蜡炬...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '《瀛奎律髓》：此严武幕府秋夜直宿时也。三、四与“五更鼓角声悲壮，三峡星河影动摇”，同一声调，诗之样式极矣。
《唐诗品汇》：刘云：上、下沉着（“永夜角声”二句下）。
《汇编唐诗十集》：八句皆对，韵度不乏，非老杜不能。
《唐诗选脉会通评林》：虞伯生曰：第二联雄壮工致。当时夜深无寐独宿之情，宛然可见。唐陈彝曰：“悲自语”二字，说“角声”，妙，妙。妆点联法，在“荏苒”、“萧条”四虚字。唐孟庄曰：好不能看，方见其苦。周珽曰：孤衷幽绪，低徊慨切。
《杜臆》：“永夜角声悲”、“中天月色好”为句，而缀以“自语”、“谁看”，此句法之奇者，乃府中不得意之语。……余初笺将三、四联“悲”、“好”，连上为句法之奇。今细思之，终不成语。盖“悲”、“好”当作活字看。
《瀛奎律髓汇评》：纪昀：八句终有拙意。许印芳：八句对。八句收到“宿府”，回应首句，法律细密。晓岚以词语之工拙苛求古人，吾所不取。冯舒：三、四之高妙，亦不在于声调。
《杜诗详注》：朱瀚曰；“一枝”应“井梧”，“栖息”应“独宿”，格意精妍。
《杜少陵集详注》：此秋夜“宿府”而有感也。上四叙景，下四言情。首句点“府”，次句点“宿”。角声惨栗，悲哉自语；月色分明，好与谁看：此“独宿”凄凉之况也。乡书阔绝，归路艰难；流落多年，借栖幕府：此“独宿”伤感之意也。玩“强移”二字，盖不得已而暂依幕下耳。”
《唐诗贯珠》：此诗对起对结，而气自流走。
《唐宋诗醇》：多少心事，于无聊中出之，字字沉郁。
《读杜心解》：“独宿”二字，诗之眼。“悲自语”、“好谁看”，正即景自伤“独宿”之况也。“荏苒”、“萧条”，则从“自语”、“谁看”中追写其故。而总束之曰“伶俜十年”，见此身甘任飘蓬矣。
《历代诗法》：写“独宿”之境，真主悲惋。令人想见其枕上踌躇，不能成寐。
《岘佣说诗》：“永夜角声悲自语，中天月色好谁看？”“悲”字、“好”字，作一顿挫，实七律奇调，令人读之烂不觉耳。
《唐宋诗举要》：吴北江曰：“永夜”二句皆中夜不眠凄恻之景，而不明言，故佳。', 'center', 1417443936, '57b95a76a633bd0066606961', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10603, '阁夜', NULL, 253, 1416, 2, 6, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/93348.htm', '', '岁暮阴阳催短景，天涯霜雪霁寒宵。
五更鼓角声悲壮，三峡星河影动摇。
野哭千家闻战伐，夷歌数处起渔樵。
卧龙跃马终黄土，人事音书漫寂寥。', '这首诗是诗人在大历元年（766）寓于夔州西阁所作。全诗写冬夜景色，有伤乱思乡的意思。首联点明冬夜寒怆；颔联写夜中所闻所见；颈联写拂晓所闻；末联写极目武侯、白帝两庙而引出的感慨。以诸葛亮和公孙述为例，说明贤愚忠逆都同归于尽，个人的寂寞就更无所谓了。全诗气象雄阔，大有上天下地，俯仰古今之概。', '阴阳：指日月。短景：指冬季日短。景：通“影”，日光。
霁（jì）：雪停。
三峡：指瞿塘峡、巫峡、西陵峡。瞿塘峡在夔州东。
野哭：战乱的消息传来，千家万户的哭声响彻四野。战伐：崔旰（gàn）之乱。
夷歌：指四川境内少数民族的歌谣。夷，指当地少数民族。
数处：几处。一作“是处”。
人事：指交游。音书：指亲朋间的慰藉。漫：徒然、白白的。', '年中白日的光阴逐渐缩短，寒夜霜雪笼罩着荒远天涯。
破晓时军营中鼓角的悲壮，星河的影子在三峡上荡漾。
荒野中的人家为战争痛哭，远处传来渔夫悲凄的歌声。
英雄的业绩最终成了黄土，我何必介意书信音讯即少。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92af2cee9a0c24ecf8e2", "shortContent": "这是大历元年（766）冬杜甫寓居夔州（治今重庆奉节）西阁时所作。当时西川军阀混战，连年不息；吐蕃也不断侵袭蜀地。而杜甫的好友郑虔、苏源明、李白、严武、高適等，都先后死去。感时忆旧，他写了这首诗，表现出异常沉重的心情。\n开首二句点明时间。首句“岁暮”，指冬季；“阴阳”，指日月；“短景”，指冬天日短。一“催”字，形象地说明夜长昼短，使人觉得光阴荏苒，岁序逼人。次句“天涯”，指夔州，又有沦落天涯意。当此...", "authors": ["陶道恕"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389accdc25963feee1a87", "shortContent": "这是大历元年（766）冬杜甫寓居夔州（治今重庆奉节）西阁时所作。当时西川军阀混战，连年不息；吐蕃也不断侵袭蜀地。而杜甫的好友郑虔、苏源明、李白、严武、高适等，都先后死去。感时忆旧，他写了这首诗，表现出异常沉重的心情。\n\n开首二句点明时间。首句“岁暮”，指冬季；“阴阳”，指日月；“短景”，指冬天日短。一“催”字，形象地说明夜长昼短，使人觉得光阴荏苒，岁序逼人。次句“天涯”，指夔州，又有沦落天涯意。当...", "authors": ["陶道恕"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3c77683d193301520d", "shortContent": "本诗作于大历元年（766），杜甫时在夔州。\n\n起句即工整老劲。岁暮，指明时令在冬日；阴阳，日月；短景，夜长昼短。日月如梭，在冬日里白天本来就短，此处用一“催”字，使其频率更加快捷，从而更凸显出黑夜之长。天涯者，指诗人所居之地夔州，距离自己的家乡的确是有天涯之远。在寒冷的夜晚，雪过天晴，霜雪发出银白色的反光，映得静寂的长夜越发辽远绵长。\n\n而颔联则从这霁雪的寒宵中引申而出。五更的鼓角，在辽阔的天际回...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "64662a5830675327e18fb1e7", "shortContent": "这是大历元年（766）冬杜甫寓居夔州（治今重庆奉节）西阁时所作。当时西川军阀混战，连年不息；吐蕃也不断侵袭蜀地。而杜甫的好友郑虔、苏源明、李白、严武、高適等，都先后死去。感时忆旧，他写了这首诗，表现出异常沉重的心情。\n\n开首二句点明时间。首句“岁暮”，指冬季；“阴阳”，指日月；“短景”，指冬天日短。一“催”字，形象地说明夜长昼短，使人觉得光阴荏苒，岁序逼人。次句“天涯”，指夔州，又有沦落天涯意。当...", "authors": ["陶道恕"], "pressName": "上海辞书出版社"}]', '《苕溪渔隐丛话》：《西清诗话》云：杜少陵云：“作诗用事，要如禅家语：水中着盐，饮水乃知盐味。”此说，诗家秘密藏也。如“五更鼓角声悲壮，三峡星河影动摇”，人徒见凌轹造化之工，不知乃用事也。《弥衡传》：“挝《渔阳操》，声悲壮。”《汉武故事》：“星辰动摇，东方朔谓：民劳之应。”则善用事者，如系风捕影，岂有迹耶！
《瀛奎律髓》：“悲壮”、“动摇”一联，诗势如之。“卧龙跃马俱黄土”，谓诸葛、公孙，贤愚俱尽。……感慨豪荡，他人所无。
《唐诗品汇》：刘云：第三、第四句对看，自是无穷俯仰之悲。
《唐诗广选》：刘会孟曰：三、四二句只见奇丽。若上句何足异？评诗未易，以此。
《唐诗直解》：光芒四射，若令人不敢正视。
《唐诗镜》：三、四意尽无余。
《唐诗选脉会通评林》：蒋一梅曰：鼓角，阁上所闻；星河，阁上所见。野哭夷歌，是倒装法。周启琦曰：杜《刈稻咏怀》云：“野哭初闻战，樵歌稍出村。”只此五、六意。说诗者何必多喙。单复曰：结语愈缓而意愈切。
《杜臆》：此诗全干起结着意。而向来论诗止称“五更”一联，并不知其微意之所在也。“卧龙”句终为自家才不得施，志不得展而发，非笑诸葛也。
《杜诗解》：一解写“夜”……笔势又沉郁，又精悍，反复吟之，使人增长意气百倍（首四句下）。
《杜诗详注》：卢世㴶云：杜诗，如《登楼》、《阁夜》、《黄草》、《白帝》、《九日》二首，一题不止为一事，一诗不止了一题，意中言外，怆然有无穷之思，当与《诸将》、《古迹》、《秋兴》诸章，相为表里，读者宜知其关系至重也。
《瀛奎律髓汇评》：查慎行：对起极警拔，三、四尤壮阔。纪昀：前格凌跨一切，结句费解。凡费解便非诗之至者。三、四只是现景，宋人诗话穿凿可笑。冯舒：无首无尾，自成首尾；无转无接，自成转接。何见悲壮动人，诗至此而《律髓》之选法于是乎穷。
《唐宋诗醇》：音节雄浑，波澜壮阔，不独“五更鼓角”、“三峡星河”脍炙人口为足赏也。李因笃曰：壮采以朴气行之，非泛为声调者可比。
《网师园唐诗笺》：“五更”二句，与“锦江春色”同一笔力。
《读杜心解》：“天涯”、“短景”，直呼动结联。而流对作起，则以阴晴不定，托出“寒宵”忽“霁”。三、四，从“霁寒霄”生出；“鼓角”不值“五更”，则“声”不透；“五更”，最凄切时也，再著“悲壮”字，直刺睡醒耳根也。“星河”不映“三峡”，则“影”不烁；“三峡”，最湍急处也，再著“动摇”字，直闪蒙胧眼光也。……彼定乱之“卧龙”，起乱之“跃马”，总归黄土，则“野哭”、“夷歌”，行且眨时变灭，顾犹以耳“悲”目“动”，寄虚愿于纷纷漠漠之世情，天涯短景，其与几何？曰“漫寂寥”，任运之旨也。噫！其词似宽，其情弥结矣。
《杜诗镜铨》：吴瞻泰云：“人事”绾上“野哭”“夷歌”，“音书”绾上“天涯”“三峡”，关锁极密。
《闻鹤轩初盛唐近体读本》：前四写景，后四言情。笔力坚苍，两俱称惬。千古绝调，公独擅之。
《批点唐诗正声》：全首悲壮慨慷，无不适意。中二联皆将明之景，首联雄浑动荡，卓冠千古。次联哀乐皆眼前景，人亦难道。结以忠逆同归自慰，然音节尤婉曲。
《昭昧詹言》：起二句夜，三、四切阁夜，并切在蜀。东坡赏此二句。此自写景，钱以为早摇民乱，不必如此解。五、六情。
《十八家诗钞》：张云卿云：勿学其壮阔，须玩其沉至。', 'center', 1417444014, '57b25cc4a633bd005710c889', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10604, '咏怀古迹（其一）', NULL, 74, 1416, 1, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3688255.htm', '', '支离东北风尘际，飘泊西南天地间。
三峡楼台淹日月，五溪衣服共云山。
羯胡事主终无赖，词客哀时且未还。
庾信平生最萧瑟，暮年诗赋动江关。', '此诗为杜甫《咏怀古迹》五首中的第一首。开首咏怀的是诗人庾信，这是因为作者对庾信的诗赋推崇备至，极为倾倒。他曾经说：“清新庾开府”，“庾信文章老更成”。另一方面，当时他即将有江陵之行，情况与庾信漂泊有相通之处。
首联写安史之乱起，漂泊入蜀居无定处。颔联写流落三峡、五溪，与夷人共处。颈联写安禄山狡猾反复，正如梁朝的侯景；自己飘泊异地，欲归不得，恰似当年的庾信。末联写庾信晚年《哀江南赋》极为凄凉悲壮，暗寓自己的乡国之思。全诗写景写情，均属亲身体验，深切真挚，议论精当，耐人寻味。', '支离：流离。风尘：指安史之乱以来的兵荒马乱。
楼台：指夔州地区的房屋依山而建，层迭而上，状如楼台。淹：滞留。日月：岁月，时光。
五溪：指雄溪、樠溪、酉溪、潕溪、辰溪，在今湘、黔、川边境。共云山：共居处。
羯（jié）胡：古代北方少数民族，指安禄山。
词客：诗人自谓。未还：未能还朝回乡。
庾（yǔ）信：南北朝诗人。
动江关：指庾信晚年诗作影响大。“江关”指荆州江陵，梁元帝都江陵。
', '战乱时颠沛流离在东北方，如今我又漂泊到西南地区。
滞留在三峡一带已有多年，和服饰不同的异族共生活。
可恨不讲信义的胡虏之人，这混乱的年代有家不能回。
庾信的一生最为坎坷悲凉，但晚年的诗赋震撼了江关。', NULL, '《杜臆》：五首各一古迹。第一首古迹不曾说明，盖庾信宅也。借古以咏怀，作咏古迹也。……公于此自称“词客”，盖将自比庾信，先用引起下句，而以己之“哀时”比信之《哀江南》也。
《唐诗评选》：本以咏庾信，只似带出，妙于取象。
《义门读书记》：《哀江南赋》云：“诛茅宋玉之宅，开径临江之府”。公误以为子山亦尝居此，故咏古迹及之。恐漂泊羁旅同子山之身世也。“宅”字于次篇总见，与后二首相对为章法。
《杜诗详注》：首章咏怀，以庾信自方也。……五、六宾主双关，盖禄山叛唐，犹侯景叛梁；公思故国，犹庾信哀江南。
《唐音审体》：以庾信自比，非咏信也。下皆咏蜀事。信非蜀人。
《唐诗别裁》：此章以庾信自况，非专咏庾也。五、六语已与庾信双关；以上，少陵自叙。
《读杜心解》：三、四，正咏“飘泊”。五、六，流水，乃首尾关键。“终无赖”申“支离”，“且未还”起“萧瑟”。
《杜诗镜铨》：自叙起，为五诗总冒。俞云：二句作诗本旨（“支离东北”二句下）。
《杜诗集评》：李因笃云：格严整而意沉着。吴家祥云：声调悲凉。
《闻鹤轩初盛唐近体读本》：陈德公曰：此章纯是自述，非关古迹矣，故有作《咏怀》一章、《古迹》四首者。
《唐诗绎》：此因寓羁不得归，而自伤飘泊也。
《昭昧詹言》：首章前六句，先发己哀为总冒。庾信宅在荆州，公未到荆州而将有江陵之行，流寓等于庾信，故先及之。', 'center', 1417461393, '57b955458ac2470062e2765f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10605, '咏怀古迹（其二）', NULL, 78, 1416, 3, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3688339.htm', '', '摇落深知宋玉悲，风流儒雅亦吾师。
怅望千秋一洒泪，萧条异代不同时。
江山故宅空文藻，云雨荒台岂梦思。
最是楚宫俱泯灭，舟人指点到今疑。', '此诗为杜甫《咏怀古迹》五首的第二首。诗的前半感慨宋玉生前怀才不遇，后半则为其生后所不平。诗是作者亲临实地凭吊后写成的，因而体会深切，议论精辟，发人深省。诗中的草木摇落，景物萧条，江山云雨，故宅荒台，舟人指点的情景，都是诗人触景生情，所抒发出来的感慨。它把历史陈迹和诗人哀伤交融在一起，深刻地表现了主题。全诗铸词溶典，精警切实。有人认为，杜甫之“怀宋玉，所以悼屈原；悼屈原者，所以自悼也。”这种说法自有见地。', '摇落：凋残，零落。
风流儒雅：指宋玉文采华丽潇洒，学养深厚渊博。
“萧条异代不同时”句：意谓自己虽与宋玉隔开几代，萧条之感却是相同。
故宅：江陵和归州（秭归）均有宋玉宅，此指秭归之宅。空文藻：斯人已去，只有诗赋留传下来。
云雨荒台：宋玉在《高唐赋》中述楚之“先王”游高唐，梦一妇人，自称巫山之女，临别时说：“妾在巫山之阳，高丘之岨，旦为行云，暮为行雨，朝朝暮暮，阳台之下。”阳台，山名，在今重庆市巫山县。
“最是楚宫俱泯灭，舟人指点到今疑。”句：意谓最感慨的是，楚宫今已泯灭，因后世一直流传这个故事，至今船只经过时，舟人还带疑似的口吻指点着这些古迹。', '草木凋零是因知宋玉的悲伤，文采洒脱学问渊博可当我师。
遥想千秋往事不禁泪洒衣襟，我们虽不同世却是同样失意。
故居里你枉然留下斐然文采，巫山云雨旧事难道只是说梦。
可叹的是楚宫已经完全消失，有船夫指点遗迹却令人怀疑。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92af5914587d02f4e7e9", "shortContent": "《咏怀古迹五首》是杜甫大历元年（766）在夔州（治今重庆奉节）写成的一组诗。夔州和三峡一带本来就有宋玉、王昭君、刘备、诸葛亮、庾信等人留下的古迹，杜甫正是借这些古迹，怀念古人，同时也抒写自己的身世家国之感。这首《咏怀古迹》是杜甫凭吊楚国著名辞赋作家宋玉的。宋玉的《高唐赋》、《神女赋》写楚襄王和巫山神女梦中欢会故事，因而传为巫山佳话；又相传在江陵有宋玉故宅。所以杜甫暮年出蜀，过巫峡，至江陵（今湖北荆...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "646629455fc8182fe9a4bcac", "shortContent": "《咏怀古迹五首》是杜甫大历元年（766）在夔州（治今重庆奉节）写成的一组诗。夔州和三峡一带本来就有宋玉、王昭君、刘备、诸葛亮、庾信等人留下的古迹，杜甫正是借这些古迹，怀念古人，同时也抒写自己的身世家国之感。这首《咏怀古迹》是杜甫凭吊楚国著名辞赋作家宋玉的。宋玉的《高唐赋》、《神女赋》写楚襄王和巫山神女梦中欢会故事，因而传为巫山佳话；又相传在江陵有宋玉故宅。所以杜甫暮年出蜀，过巫峡，至江陵（今湖北荆...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}]', '《杜臆》：玉悲“摇落”，而公云“深知”，则悲与之同也。故“怅望千秋”，为之“洒泪”；谓玉萧条于前代，公萧条于今代，但不同时耳。不同时而同悲也……知玉所存虽止文藻，而有一段灵气行乎其间，其“风流儒雅”不曾死也，故吾愿以为师也。
《杜诗详注》：（“怅望千秋”一联）二句乃流对。此诗起二句失粘。
《唐音审体》：义山诗“楚天云雨俱堪疑”从此生出。
《唐宋诗醇》：顾宸曰：李义山诗云：“襄王枕上元无梦，莫枉阳台一段云。”得此诗之旨。
《唐诗别裁》：谓高唐之赋乃假托之词，以讽淫惑，非真有梦也。怀宋玉亦所以自伤。言斯人虽往，文藻犹存，不与楚宫同其泯灭，其寄概深矣。
《读杜心解》：此下四首，分咏峡口古迹也，俱就各人时事寄概……三、四，空写，申“知悲”；五、六，实拈，申“吾师”。……结以“楚宫泯灭”，与“故宅”相形，神致吞吐，抬托愈高。
《杜诗镜铨》：流水对，一往情深（“怅望千秋”二句下）。意在言外（“最是楚宫”二句下）。“亦”字承庾信来，有岭断云连之妙。
《杜诗集评》：如此诗亦自“风流儒雅”。
《杜诗言志》：此第二首，则将自己怀抱与宋玉古事引为同调。
《昭昧詹言》：一意到底不换，而笔势回旋往复，有深韵。七律固以句法坚峻、壮丽、高朗为贵，又以机趣凑泊、本色自然天成者为上乘。
《唐宋诗举要》：吴曰：次首以宋玉自况，深曲精警，不落恒蹊，有神交千载之契。', 'center', 1417461658, '57b8f62879bc44005b9e551c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10606, '咏怀古迹（其三）', NULL, 413, 1416, 3, 3, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3688432.htm', '', '群山万壑赴荆门，生长明妃尚有村。
一去紫台连朔漠，独留青冢向黄昏。
画图省识春风面，环珮空归夜月魂。
千载琵琶作胡语，分明怨恨曲中论。', '此诗为杜甫《咏怀古迹》五首的第三首，是诗人经过昭君村时所作的咏史诗。想到昭君生于名邦，殁于塞外，去国之怨，难以言表。因此，主题落在「怨恨」二字，「一去」二字，是怨的开始，「独留」两字，是怨的终结。作者既同情昭君，也感慨自身。沈德潜说：「咏昭君诗此为绝唱。」', '荆门：山名，在今湖北宜都西北。
明妃：王昭君，名嫱（qiáng），汉元帝宫人，西晋时避晋文帝司马昭的名讳，改称“明妃”。汉元帝竟宁元年（前33）被嫁匈奴呼韩邪（yé）单于。
去：离开。
紫台：汉宫，紫宫，宫廷。
朔漠：北方的沙漠。
青冢：指王昭君墓，在今内蒙古呼和浩特南，传说冢上草色长青，故名“青冢”。
画图：汉元帝按图招幸宫人，宫人都贿赂画工。王昭君自持貌美，不肯行贿，被画工丑化，不得皇帝召见。后来汉与匈奴和亲，令王昭君远嫁，汉元帝才知道她的美貌为后宫第一，传说因此杀了许多画工。
省：曾经。
春风面：形容王昭君的美貌。
环珮：一作「环佩」，妇女戴的装饰物。
夜月：一作「月夜」。
千载琵琶作胡语：传说王昭君在匈奴曾作“冤思之歌”，感叹在汉宫受到的冷遇。古乐府有《昭君怨》《明君词》《昭君叹》等曲辞。胡语；胡音。
怨恨曲中论（lún）：乐曲中诉说着昭君的怨恨。', '穿过千山万壑一直奔向荆门，这是美丽的昭君生长的村庄。
她离开汉宫踏入渺远的荒漠，只留下青冢空向凄凉的黄昏。
糊涂的君王依据画像辨美丑，昭君的灵魂能在月夜中归来。
千百年来琵琶声回荡在空中，那是昭君无穷的怨恨和诉说。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92af2e6a6b501f95c1c6", "shortContent": "这是《咏怀古迹五首》中的第三首，诗人借咏昭君村、怀念王昭君来抒写自己的怀抱。\n“群山万壑赴荆门，生长明妃尚有村”。诗的发端两句，首先点出昭君村所在的地方。据《一统志》说：“昭君村，在荆州府归州东北四十里。”其地址，即在今湖北秭归县的香溪。杜甫写这首诗的时候，正住在夔州（治今重庆奉节）白帝城。这是三峡西头，地势较高。他站在白帝城高处，东望三峡东口外的荆门山及其附近的昭君村。远隔数百里，本来是望不到的...", "authors": ["廖仲安"], "pressName": "上海辞书出版社"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6466299a7f27182da35ac211", "shortContent": "这是《咏怀古迹五首》中的第三首，诗人借咏昭君村、怀念王昭君来抒写自己的怀抱。\n\n“群山万壑赴荆门，生长明妃尚有村”。诗的发端两句，首先点出昭君村所在的地方。据《一统志》说：“昭君村，在荆州府归州东北四十里。”其地址，即在今湖北秭归县的香溪。杜甫写这首诗的时候，正住在夔州（治今重庆奉节）白帝城。这是三峡西头，地势较高。他站在白帝城高处，东望三峡东口外的荆门山及其附近的昭君村。远隔数百里，本来是望不到...", "authors": ["廖仲安"], "pressName": "上海辞书出版社"}]', '《后村诗话》：《昭君村》云：「画图省识春风面，环佩空归月夜魂，亦佳句。
《唐诗品汇》：刘云：起得磊落（「群山万壑」二句下）。
《汇编唐诗十集》：吴云：此篇温雅深邃，杜集中之最佳者。钟、谭求深而不能探此，恐非网珊瑚手。
《唐诗选脉会通评林》：徐常吉曰：「画图」句，言汉恩浅，不言不识，而言「省识」，婉词。郭浚曰：悲悼中，难得如此风韵。五、六分承三、四有法。周珽曰：写怨境愁思，灵通清回，古今咏昭君无出其右。陈继儒曰：怨情悲响，胸中骨力，笔下风电。
《杜臆》：因昭君村而悲其人。昭君有国色，而入宫见妒；公亦国士，而入朝见嫉：正相似也。悲昭以自悲也。……「月夜」当作「夜月」，不但对「春风」，而与夜月俱来，意味迥别。
《唐诗评选》：只是现成意思，往往点染飞动，如公输刻木为鸢，凌空而去。首句是极大好句，但施之于「生长明妃」之上，则佛头加冠矣。故虽有佳句，失所则为疵颣。平收不作记赞，方成诗体。
《杜诗解》：咏明妃，为千古负材不偶者，十分痛惜。「省」作省事之省。若作实字解，何能与「空归」对耶？
《唐诗快》：昔人评「群山万壑」句，颇似生长英雄，不似生长美人。固哉斯言！美人岂劣于英雄耶？
《杜诗详注》：朱瀚曰；起处，见钟灵毓秀而出佳人，有几许珍惜；结处，言托身绝域而作胡语，含许多悲愤。陶开虞曰：此诗风流摇曳，杜诗之极有韵致者。
《围炉诗话》：子美「群山万壑赴荆门」等语，浩然一往中，复有委婉曲折之致。
《唐宋诗醇》：破空而来，文势如天骥下坂，明珠走盘。咏明妃者，此首第一；欧阳修、王安石诗犹落第二乘。
《唐诗别裁》：咏昭君诗，此为绝唱，馀皆平平。至杨凭「马驼弦管向阴山」，风斯下矣。
《读杜心解》：结语「怨恨」二字，乃一诗之归宿处。……中四，述事申哀，笔情缭绕。「一去」，怨恨之始也；「独留」，怨恨所结也。「画图识面」，生前失宠之「怨恨」可知；「环佩归魂」，死后无依之「怨恨」何极！
《杜诗镜铨》：起句：从地灵说入，多少郑重。李子德云：只叙明妃，始终无—语涉议论，而意无不包，后来诸家总不能及。王阮亭云：青邱专学此种。
《诗法易简录》：起笔亦有千岩竞秀、万壑争辉之势。
《网师园唐诗笺》：奔腾而来，悲壮浑成，安得不推绝唱！
《随园诗话》：同一著述，文曰作，诗曰吟，可知音节之不可不讲。然音节一事，难以言传。少陵「群山万壑赴荆门」，使改「群」字为「千」字，便不入调。……字义一也，时差之毫厘，失以千里，其他可以类推。
《闻鹤轩初盛唐近体读本》：陈德公曰：三、四笔老峭而情事已尽，后半沈郁，结最缠绵。评：开口气象万千，全为「明妃村」三字作势。而下文「紫台」、「青冢」亦俱托起矣。且「赴」字、「尚有」字、「独留」字，字字相生，不同泛率，故是才大而心细。
《唐宋诗举要》：吴曰：庾信、宋玉皆词人之雄，作者所以自负。至于明妃，若不伦矣；而其身世流离，固与己同也。篇末归重琵琶，尤其微旨所寄，若曰：虽千载已上之胡曲，苟有知音者聆之，则怨恨分明若面论也。此自喻其寂寥千载之感也。
《诗境浅说》：咏明妃诗多矣，沈归愚推此诗为绝唱，以能包举其生平，而以苍凉激楚出之也。首句咏荆门之地势，用一「赴」字，沉着有力。', 'center', 1417461665, '57b966172e958a005fa8e783', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10607, '咏怀古迹（其四）', NULL, 45, 1416, 1, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3688467.htm', '', '蜀主窥吴幸三峡，崩年亦在永安宫。
翠华想象空山里，玉殿虚无野寺中。
古庙杉松巢水鹤，岁时伏腊走村翁。
武侯祠屋常邻近，一体君臣祭祀同。', '此诗为杜甫《咏怀古迹》五首的第四首，诗人称颂了三国时刘备和诸葛亮的君臣关系，抒发了自己不受重用抱负难展的悲怨之情。作者借村翁野老对刘备诸葛亮君臣的祭祀，烘托其遗迹之流泽。诗歌先叙刘备进袭东吴失败而卒于永安宫，继叹刘备的复汉大业一蹶不振，当年的翠旗行帐只能在空山想象中觅得踪迹，玉殿虚无缥缈，松杉栖息水鹤。歌颂了刘备的生前事业，叹惋大业未成身先去，空留祠宇在人间的荒凉景象。最后赞刘备诸葛亮君臣一体，千百年受人祭祀，表达了无限敬意，发抒了无限感慨。', '蜀主：指刘备。
永安宫：在今四川省奉节县。
野寺：原注今为卧龙寺，庙在宫东。
伏腊：伏天腊月。指每逢节气村民皆前往祭祀。
祠屋：一作“祠堂”。', '刘备出兵伐吴就驻扎在三峡，无奈战败归来去世在永安宫。
昔日翠旗飘扬空山浩浩荡荡，永安宫湮灭在这荒郊野庙中。
古庙里杉松树上水鹤做了巢，每逢节令仍举行隆重的祭祀。
丞相的祠庙就在先王庙临近，君臣共同享受着礼仪和祭礼。	', NULL, '《杜臆》：其四：咏先主祠。而所以怀之，重其君臣之相契也。……幸三峡而崩永安，直述而悲愤自见。
《杜诗解》：前解，首句如疾雷破山，何等声势！次句如落日掩照，何等苍凉！虚想当年，四，实笑今日也。……「翠华」、「玉殿」，又极声势，「空山」、「野寺」，又极苍凉。只一句中，上下忽变，真是异样笔墨。
《义门读书记》：先主失计，莫过窥吴，丧败涂地，崩殂随之；汉室不可复兴，遂以蜀主终矣。所赖托孤诸葛心神不二，犹得支数十年之祚耳。此篇叙中有断言，婉而辨，非公不能。
《读杜心解》：三、四语意，一显一隐，空山殿字，神理如是。五、六流水递下。……结以「武侯」伴说，波澜近便，鱼水「君臣」，殁犹「邻近」；由废斥漂零之人对之，有深感焉。
《杜诗镜铨》：曰「幸」曰「崩」，尊昭烈为正统也。是《春秋》书法。
《闻鹤轩初盛唐近体读本》：起二便是峭笔。三、四低徊，凭吊备极迷离。五、六「巢」、「走」二字法高，而「走」字尤似出意。结腐而峭，笔可排山。
《唐诗笺注》：此诗似无咏怀意，然俯仰中有无限感慨。
《杜诗集评》：抑扬反复，其于虚实之间，可谓踌躇满志。
《杜诗言志》：此一首是咏蜀主。而己怀之所系，则在于「一体君臣」四字中。盖少陵生平，只是君臣义重，所恨不能如先主武侯之明良相际耳。
《昭昧詹言》：「古庙」二句，就事指点，以寓哀寂。山谷《樊侯庙》所出。
《唐宋诗举要》：吴曰：先主一章，特以引起武侯。', 'center', 1417462063, '57b944b92e958a005fa79fbe', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10608, '咏怀古迹（其五）', NULL, 126, 1416, 3, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3688522.htm', '', '诸葛大名垂宇宙，宗臣遗像肃清高。
三分割据纡筹策，万古云霄一羽毛。
伯仲之间见伊吕，指挥若定失萧曹。
运移汉祚终难复，志决身歼军务劳。', '此诗为杜甫《咏怀古迹》五首的末篇。全诗以议论为主，称颂诸葛亮的英才挺出，惋惜其志不成。诗议而不空，句句含情，层层深入，荡人胸襟、动尔情怀。', '垂：流传。
宇宙：兼指天下古今。
宗臣：为后世所敬仰的大臣。
肃清高：为诸葛亮的清风亮节而肃然起敬。
三分割据：指魏、蜀、吴三国鼎足而立。
纡（yū）：屈，指不得施展。
筹策：谋略。
云霄一羽毛：凌霄的飞鸟，比喻诸葛亮绝世独立的智慧和品德。
伊吕：指伊尹、吕尚。
萧曹：指萧何、曹参。
运：运数。
祚（zuò）：帝位。
复：恢复、挽回。
志决：志向坚定，指诸葛亮《出师表》所云“鞠躬尽瘁，死而后已”。
身歼：身死。', '诸葛亮大名垂宇宙且万古流芳，他清高的品性真令人无比敬仰。
三分天下是他苦心筹划的结果，他犹如展翅高翔在云霄的鸾凤。
才华超绝与伊尹吕尚难分高下，指挥千军万马非曹参萧何能比。
汉朝的气运已经衰落难以恢复，他意志坚决终因军务繁忙殉职。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92af2cee9a0c24ecf8e1", "shortContent": "这是《咏怀古迹五首》中的最末一篇。当时诗人瞻仰了武侯祠，衷心敬慕，发而为诗。作品以激情昂扬的笔触，对其雄才大略进行了热烈的颂扬，对其壮志未遂叹惋不已！\n“诸葛大名垂宇宙”，上下四方为宇，古往今来曰宙，“垂宇宙”，将时间空间共说，给人以“名满寰宇，万世不朽”的具体形象之感。首句如异峰突起，笔力雄放。次句“宗臣遗像肃清高”，进入祠堂，瞻望诸葛遗像，不由肃然起敬；遥想一代宗臣，高风亮节，更添敬慕之情。“...", "authors": ["傅经顺"], "pressName": "上海辞书出版社"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "64662a04b6a81d0c53fa233a", "shortContent": "这是《咏怀古迹五首》中的最末一篇。当时诗人瞻仰了武侯祠，衷心敬慕，发而为诗。作品以激情昂扬的笔触，对其雄才大略进行了热烈的颂扬，对其壮志未遂叹惋不已！\n\n“诸葛大名垂宇宙”，上下四方为宇，古往今来曰宙，“垂宇宙”，将时间空间共说，给人以“名满寰宇，万世不朽”的具体形象之感。首句如异峰突起，笔力雄放。次句“宗臣遗像肃清高”，进入祠堂，瞻望诸葛遗像，不由肃然起敬；遥想一代宗臣，高风亮节，更添敬慕之情。...", "authors": ["傅经顺"], "pressName": "上海辞书出版社"}]', '《后村诗话》：“……武侯祠屋长邻近，一体君臣祭祀同。”又云“万古云霄一羽毛”，又云“伯仲之间见伊吕”。卧龙公没已千载，而有志世道者，皆以三代之佐评之。如云“万古云霄一羽毛”，如侪之伊吕伯仲间，而以萧曹为不足道，此论皆自子美发之。考亭、南轩近世大儒，不能发也。
《唐诗品汇》：刘云：两语气概别，足掩上句之劣。知己语，赞孔明者不能复出此也（“伯忡之间”二句下）。
《四溟诗话》：七言绝律，起句借韵，谓之“孤雁出群”，宋人多有之。宁用仄字，勿借平字，若子美“先帝贵妃俱寂寞”、“诸葛大名垂宇宙”是也。
《词源辩体》：（杜甫）七言多稚语、累语，……“志决身歼军务劳”……等句，皆累语也。胡元瑞云：“子美利钝杂陈，正变互出，后来沾溉者无穷，诖误者亦不少”。
《杜臆》：通篇一气呵成，宛转呼应，五十六字多少曲折，有太史公笔力。薄宋诗者谓其带议论，此诗非议论乎？
《唐诗归》：钟云：对法奇。又云：下句好眼！真不以成败论古人（“伯仲之间”二句下）。
《唐诗选脉会通评林》：周敬曰：通篇笔力议论，妙绝古今。中联知己之语，千载神交。陆深曰：疏卤悲愤，无复绳墨可寻。周启堕曰；……余谓鼎足之业，武侯自视不过万古云霄中一羽毛之轻，故下云：“伯仲伊吕”、“运失萧曹”，意脉同甚联属。
《杜诗说》：此诗先表其才之挺出，后惜其志之不践，武候平生出处，直以五十六字论定。
《杜诗解》：“羽毛”状其“清”，“云霄”状其“高”也……前解慕其大名不朽，后解惜其大功不成。慕是十分慕，惜是十分惜。
《义门读书记》：带“迹”字（“宗臣遗象”句下）。直判定千年大公案，不特无一字无来处（“伯仲之间”二句下）。
《杜诗详注》：“三分割据”，见时势难为；“万占云霄”，见才品杰出。
《载酒园诗话又编》：如咏诸葛：“伯仲之间见伊吕，指挥若定失萧曹”。言简而尽，胜读一篇史论。
《唐诗贯珠》：全是颂体。……有时流言三、四不对，不知起已对，此亦“偷春格”，而况气苍局大耶！
《唐诗别裁》：“云霄”、“羽毛”，犹鸾凤高翔，状其才品不可及也。文中子谓“诸葛武侯不死，礼乐其有兴乎？”即“失萧曹”之旨，此议论之最高者。后人谓诗不必著议论，非通言也。
《读杜心解》：“宗臣”，一诗之颂；“伊吕”，一诗之的……八句一气转掉，言此“名垂宇宙”、“肃然清高”者，非所谓“宗臣”也哉？功业所见，纡策三分，居之特轻若一羽耳。……胸中拿定“运移汉祚”四字，便已识得帝统所归。知前篇曰“幸”曰“崩”，及“翠华”、“玉殿”等字，不得浪下也。
《杜诗镜铨》：四联皆一扬一抑。对笔奇险（“万古云霄”句下）。二语确是孔明身分，具见论世卓识（“伯仲之间”二句下）。陈秋田云：小视三分，抬高诸葛，一结归之于天。识高笔老，而章法之变，直横绝古今。
《唐诗成法》：此首通篇论断，吊古体所忌，然未经人道过，故佳，若拾他人唾余，便同土壤。
《杜诗言志》：此第五首，则咏武侯以自况。盖第三首之以明妃自喻，犹在遭际不幸一边，而此之以武侯自喻，则并其才具气节而一概举似之。
《唐宋诗举要》：吴曰：前幅尤壮伟非常，淋漓独绝。全篇精神所注在此，故以力结束。', 'center', 1417462170, '57b932ce0a2b58005c93eb1a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10609, '江州重别薛六柳八二员外', NULL, 24, 492, 1, 1, '刘长卿', NULL, 10113, '57b9a043165abd00661cbf89', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383573.htm', '', '生涯岂料承优诏，世事空知学醉歌。
江上月明胡雁过，淮南木落楚山多。
寄身且喜沧洲近，顾影无如白发何。
今日龙钟人共老，愧君犹遣慎风波。', '作者一生中两次遭贬。诗是他第二次贬往南巴（属广东）经过江州与二友人话别时写的。诗人虽遭贬谪，却说「承优诏」，这是正话反说，抒发胸中不平。明明是老态龙钟，白发丛生，顾影自怜，无可奈何，却说「寄身且喜沧洲近」，把凄凉伤心掩饰，委婉地抒发不满情绪。全诗虽感叹身世，抒发悲愤，却不敢面对当权，其矛盾心绪，溢于言表。', '江州：今江西九江市。
薛六、柳八：名未详。六、八，是他们的排行。
员外：员外郎的简称。原指正额的成员以外郎官，为中央各司次官。
生涯：犹生计。
优诏：优厚待遇的诏书。根据上下文，此当为反语。
醉歌：醉饮歌唱。
胡雁：指从北方来的雁。
「淮南」句：江州在淮南，其地又在古代楚国境。楚山多，木叶零落，所见之山也多了。
沧洲：滨海的地方，也用以指隐士居处。
顾：回看。
无如：无奈。
龙钟：指老态迟钝貌。
老：一作「弃」。
遣：使，这里是叮咛之意。
慎风波：慎于宦海风波。', '多年沦落的生涯，谁知竟得到天子的厚恩。世间万事我都已参破，只想学醉饮狂歌的古人。江上的月色分外清明，胡雁从夜空飞掠而过。秋风吹起，淮南已树木凋尽，楚地山头的落叶想必更多。且喜暂时可以寄身的地方，在那沧海近旁。对着明镜来回照影，萧萧白发徒然地令人心伤。如今你们同我都已经老去，都一样是这般步履龙钟。你们还叮嘱我要留意风波险恶，真叫我深深惭愧无限感动。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290ae", "shortContent": "代宗大历十一年（776），刘长卿因为性格刚强，得罪了鄂岳观察使吴仲孺，被诬贪赃，由鄂岳转运留后贬为睦州（今浙江淳安）司马。此诗作于南下睦州途中路经江州（今天江西九江）之时，抒发了诗人遭贬的愤懑之情和自伤老大的感慨。\n\n首联写诗人被贬。起句字面上称美皇恩浩荡，实是春秋笔法，“承优诏”云云，实是反说，愤激不平才是其真意。下句则由上句之婉讽陡然转为无可奈何的一声浩叹，淋漓尽致地倾吐真情，也将上句隐含的讽...", "authors": ["阮森丽"], "pressName": "崇文书局"}]', '', 'center', 1417463605, '57c18adf0a2b58006ced5b66', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (50921, '苏幕遮', NULL, 0, 26, 0, 1, '高道宽', NULL, 11195, '5858e6398d6d810065c3153c', '元', 'ci', '词', NULL, NULL, '出五行，修方外。彼岸芦花，郁郁彤云坠。浩浩风光贪困睡。唤觉从头，点对都交会。
雪中月，壶中日。独跨扁舟，虚运松风瑞。妙本将来医尔醉。普劝诸公，休把元初昧。', NULL, NULL, NULL, NULL, NULL, 'indent', 1529685194, '585cefbc1b69e6006cc9b9b1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (50922, '苏幕遮', NULL, 0, 26, 0, 1, '高道宽', NULL, 11195, '5858e6398d6d810065c3153c', '元', 'ci', '词', NULL, NULL, '妙还元，镇常在。丹药白银，那个人不爱。武士将来教君解。琢就银壶，提向街头卖。
要三成，弃两坏。最上功夫，巧造十分大。圆满一旬遍饮快。醉赴蟠桃，归去君休怪。', NULL, NULL, NULL, NULL, NULL, 'indent', 1529685193, '585cefbcda2f6000658301fb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10610, '长沙过贾谊宅', NULL, 158, 492, 2, 3, '刘长卿', NULL, 10113, '57b9a043165abd00661cbf89', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383574.htm', '', '三年谪宦此栖迟，万古惟留楚客悲。
秋草独寻人去后，寒林空见日斜时。
汉文有道恩犹薄，湘水无情吊岂知？
寂寂江山摇落处，怜君何事到天涯！', '诗似是作者赴潘州（今广东茂名市）贬所，路过长沙时所作。首联写贾谊三所谪官，落得「万古」留悲。明写贾谊，暗寓自身迁谪。颔联写古宅萧条冷落的景色，「秋草」、「寒林」、「人去」、「日斜」，一派黯然气象。颈联写贾谊见疏，当年凭吊屈子。隐约联系自己而今凭吊贾谊。尾联写宅前徘徊，暮色更浓，秋色更深，抒发放逐天涯的哀惋叹喟。全诗虽是吊古，实在伤今，借怜贾以自怜。语言含蓄蕴藉，感情哀楚动人。', '贾谊：西汉文帝时政治家、文学家。后被贬为长沙王太傅，长沙有其故址。
谪宦：贬官。栖迟：淹留。像鸟儿那样的敛翅歇息，飞不起来。
楚客：流落在楚地的客居，指贾谊。长沙旧属楚地，故有此称。一作「楚国」。
独：一作「渐」。
汉文：指汉文帝。
摇落处：一作「正摇落」。', '你被贬于此寂寞地住了三载，万古留下你客居楚地的悲哀。
踏着秋草独自寻觅你的足迹，只有黯淡的斜阳映照着寒林。
为何明君却独对你恩疏情薄，湘水无情怎知我对你的深情？
江山已经冷落草木已经凋零，可怜你究竟何故被贬此地呢！', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a603048e64fbd9137c", "shortContent": "这是一篇堪称唐诗精品的七律。诗的内容，与作者的迁谪生涯有关。刘长卿“刚而犯上，两遭迁谪”（唐高仲武《中兴间气集》）。第一次迁谪在唐肃宗至德三年（758）春天，由苏州长洲县尉被贬为潘州南巴（今广东茂名南）县尉；第二次在唐代宗大历八年（773）至十二年间的一个深秋，因被诬陷，由淮西鄂岳转运留后被贬为睦州（浙江建德）司马。从这首诗所描写的深秋景象来看，诗当作于第二次迁谪来到长沙的时候，那时正是秋冬之交，...", "authors": ["徐竹心"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d119", "shortContent": "这是一篇堪称唐诗精品的七律。诗的内容，与作者的迁谪生涯有关。刘长卿“刚而犯上，两遭迁谪”（唐高仲武《中兴间气集》）。第一次迁谪在唐肃宗至德三年（758）春天，由苏州长洲县尉被贬为潘州南巴（今广东茂名南）县尉；第二次在唐代宗大历八年（773）至十二年间的一个深秋，因被诬陷，由淮西鄂岳转运留后被贬为睦州（浙江建德）司马。从这首诗所描写的深秋景象来看，诗当作于第二次迁谪来到长沙的时候，那时正是秋冬之交，...", "authors": ["徐竹心"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290af", "shortContent": "在一个深秋的傍晚，刘长卿只身于秋风萧瑟荒草凄迷中，独自来“过”访贾谊旧宅。看着这荒草遍地、荒凉寂寞的故宅，刘长卿不禁思绪万千。贾谊是汉文帝时著名的政论家、文学家，才华横溢，深受文帝器重，因遭守旧大臣的妒忌和中伤，被贬为长沙王太傅。他的不幸遭遇，引得多少贤人志士为之悲痛。悲其世道昏暗，痛其直臣被贬。\n\n刘长卿轻轻踱步于宅院之中，彷徨瞻顾。稀疏的秋草划过裤角，又有阵阵秋风袭面，他顿了顿步，不禁黯然长叹...", "authors": ["董镇菲"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270597f0b9738b369b1d7", "shortContent": "在一个深秋的傍晚，刘长卿于秋风萧瑟荒草凄迷中，独自来“过”访追悼贾谊旧宅，看着这荒草遍地、荒凉寂寞的故宅，刘长卿的思绪不禁萦绕向贾谊。回想西汉文帝时，贾谊是著名的政治家，才华横溢，深受文帝器重，因遭守旧大臣的妒忌和中伤，被贬出使为长沙王太傅。他的不幸遭遇，引得多少贤人志士为之悲痛。悲其世道昏暗，痛其直臣被贬。\n\n刘长卿轻轻踱步于宅院之中，彷徨瞻顾。稀疏的秋草划过裤角，又有阵阵秋风袭面，他顿了顿步，...", "authors": ["董镇菲"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270c79761253910e905b0", "shortContent": "在一个深秋的傍晚，刘长卿于秋风萧瑟荒草凄迷中，独自来“过”访追悼贾谊旧宅，看着这荒草遍地、荒凉寂寞的故宅，刘长卿的思绪不禁萦绕向贾谊。回想西汉文帝时，贾谊是著名的政治家，才华横溢，深受文帝器重，因遭守旧大臣的妒忌和中伤，被贬出使为长沙王太傅。他的不幸遭遇，引得多少贤人志士为之悲痛。悲其世道昏暗，痛其直臣被贬。\n\n刘长卿轻轻踱步于宅院之中，彷徨瞻顾。稀疏的秋草划过裤角，又有阵阵秋风袭面。他顿了顿步，...", "authors": ["董镇菲"], "pressName": "崇文书局"}]', '《唐诗品汇》：刘云：怨甚（「汉文有道」二句下）。
《唐音癸签》：「秋草独寻人去后，寒林空见日斜时。」初读之似海语，不知其最确切也，谊《鵩赋》云：「四月孟夏，庚子日斜，野鸟入室，主人将去。」「日斜」、「人去」，即用谊语，略无痕迹。
《唐诗选脉会通评林》：周敬曰：哀怨之甚，《鵩赋》中语，自然妙合。周珽曰：以风雅之神，行感忾之思，正如《鵩鸟》一赋，直欲悲吊千古。吴山民云；三、四无限凄伤，一结黯然。
《唐风定》：深悲极怨，乃复妍秀温和，妙绝千古。
《唐诗贯珠》：松秀轻圆，中唐风致。
《增订唐诗摘钞》：黄生曰：后四句语语打到自家身上，怜贾正所以自怜也。三、四「人去」、「日斜」，皆《鵩赋》中字，妙在用事无痕。
《山满楼笺注唐诗七言律》：笔法顿挫，言外有无穷感慨，不愧中唐高调。
《大历诗略》：极沉挚以澹缓出之，结乃深悲而反咎之也。读此诗须得其言外自伤意，苟非迁客，何以低回如此？
《唐诗笺要》：怨语难工，难在澹宕婉深耳。「秋草」、「湘水」二语，尤当隽绝千古。
《唐诗别裁》：谊之迁谪，本因被谗，今云何事而来，含情不尽。
《精选七律耐吟集》：「一唱三叹息，慷慨有余哀」，此种是也。
《昭昧詹言》：首二句叙贾谊宅，三四「过」字，五六入议，收以自己托意，亦全是言外有作诗人在，过宅人在。
《湘绮楼说诗》：运典无痕迹。
《岘佣说诗》：「汉文有道」一联可谓工矣。上联「芳草独寻人去后，寒林空见日斜时」疑为空写，不知「人去」句即用《鵩赋》「主人将去」，「日斜」句即用「庚子日斜」。可悟运典之妙，水中着盐，如是如是。', 'center', 1417463694, '57bce639c4c97100615db9d2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10611, '自夏口至鹦鹉洲夕望岳阳寄源中丞', NULL, 88, 492, 2, 1, '刘长卿', NULL, 10113, '57b9a043165abd00661cbf89', '唐', 'shi', '诗', 'http://baike.baidu.com/view/576765.htm', '', '汀洲无浪复无烟，楚客相思益渺然。
汉口夕阳斜渡鸟，洞庭秋水远连天。
孤城背岭寒吹角，独树临江夜泊船。
贾谊上书忧汉室，长沙谪去古今怜。', '这首诗是遭贬后触景感怀之作。诗中对被贬于岳阳的源中丞，表示怀念和同情，也是借怜贾谊贬谪长沙，以喻自己的遭贬谪。
首联写诗人为身边景物所触动，而想到贬于洞庭湖畔岳阳城友人，通过写江上浪烟来寄托对友人的思念之情。中间两联写诗人由夏口至鹦鹉洲一路的所见所闻。尾联为劝慰元中丞语，忧愤之语倾泻而出，以同情友人在政治上遭受打击的境遇作结，也是作者自己人生遭际的写照。全诗语言圆熟，意境开阔，结构紧密，是艺术上较成熟的作品。', '夏口：唐鄂州治，今属湖北武汉，在汉水入江处。汉水自沔阳以下称夏水，故汉水长江汇合处称夏口。
鹦鹉洲：在长江中，正对黄鹤矶。唐以后渐渐西移，今与汉阳陆地相接。
岳阳：今属湖南，滨临洞庭湖。
中丞：御史中丞的简称，唐常代行御史大夫职务。
汀洲：水中沙洲。指鹦鹉洲。
楚客：客居楚地之人。此为诗人自指，也暗指屈原。
渺然：遥远的样子。
汉口：即上夏口。这里指汉水入口处。
鸟：暗合鹦鹉。
洞庭：洞庭湖，在湖南北部，长江以南。
孤城：指汉阳城。
角：古代军队中的一种吹乐器。
树：一作“戍”。
贾谊上书：贾谊曾向汉文帝上《治安策》。
长沙谪去：指贾谊被贬为长沙王太傅。谪去，一作“迁谪”。', '放船时汀洲上多么睛朗，没有风浪也没有烟霭迷离，我这楚地客子的相思，就像江流浩渺无际。在汉口的夕阳中不时可见渡江的鸟雀侧身奋飞；洞庭湖满涨的秋水，和远天连成蔚蓝一气。背山的孤城响彻号角，一声声透出凄寒，临江的那棵独树，黑夜里停泊着我的小船。贾谊上书只因他心忧国事，为了汉室的长治久安，他不幸远谪长沙，古今来令人深深地哀惋。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290b0", "shortContent": "此诗是唐代诗人刘长卿创作的一首七言律诗，写于至德间任鄂州转运留后到夏口一带出巡时，是诗人遭贬后触景感怀之作。诗中对被贬于岳阳的源中丞，表示怀念和同情，也借怜贾谊贬谪长沙以喻自身。全诗以写景为主，又处处切题，以“汀洲”切“鹦鹉洲”，以“汉口”切“夏口”，以“孤城”切“岳阳”。最后即景生情，抒发被贬的感慨，揭示出向源中丞寄诗的意图。\n\n首联写船到鹦鹉洲时所见江间水波不兴、烟霭一空的景象，诗人为身边景物...", "authors": ["阮森丽"], "pressName": "崇文书局"}]', '', 'center', 1417463760, '57b92e04c4c971005590a3c9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10612, '赠阙下裴舍人', NULL, 41, 435, 1, 1, '钱起', NULL, 10114, '57bbbb372e958a00694032d7', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383576.htm', '', '二月黄鹂飞上林，春城紫禁晓阴阴。
长乐钟声花外尽，龙池柳色雨中深。
阳和不散穷途恨，霄汉常悬捧日心。
献赋十年犹未遇，羞将白发对华簪。', '此诗以其用景色隐含的请求提携之意，和不落窠臼的恭维手段而闻名。前半部分以写景为主，但融情于景；后半部分以抒情为主，但思与景谐。诗人含蓄地赞颂了裴舍人，并委婉地陈述了自己的心事。全诗未有一句是明写作者自己之情，却在景色和感情的描写中点明了自己的想法，富丽精工，又不流于藻饰堆砌，由此颇见作者娴熟的艺术技巧。', '阙下：宫阙之下，指帝王所居之地。阙是宫门前的望楼。裴舍人：生平不详。舍人：指中书舍人，其职责是草拟诏书，任职者须有文学资望。
黄莺：一作“黄鹂”。上林：指上林苑，汉武帝时据旧苑扩充修建的御苑。此处泛指宫苑。
紫禁：皇宫。一作“紫陌”。阴阴：一作“沈沈”。
长乐：即长乐宫。西汉主要宫殿之一，在长安城内。这里借指唐代长安宫殿。
龙池：唐玄宗登位前王邸中的一个小湖，后王邸改为兴庆宫，玄宗常在此听政，日常起居也多在此。
阳和：指二月仲春，与开头二月相应。
霄汉：指高空。长怀：一作“长悬”。
献赋：西汉时司马相如向汉武帝献赋而被进用，后为许多文人效仿。此指参加科举考试。遇：遇时，指被重用。
华簪：古人戴帽，为使帽子固定，便用簪子连帽穿结于发髻上。有装饰的簪，就是华簪，是达官贵人的冠饰。', '二月天黄莺鸟飞到上林苑，春天早上紫禁城郁郁葱葱。
长乐宫钟声消逝在花丛外，龙池杨柳沐春雨翠色更深。
和煦春日也难消穷途遗恨，耿耿胸中永怀着捧日忠心。
献赋十年至今仍未得恩遇，如今白发丛生羞对裴舍人。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b334a8757d5a0e1d1b", "shortContent": "这首诗，是写给一个姓裴的舍人。写诗的目的，是为了向裴舍人请求援引。\n开头四句，诗人像并不在意求援似的，描画了一幅秾丽的宫苑春景图：早春二月，在上林苑里，黄鹂成群地飞鸣追逐，好一派活跃的春的气氛！紫禁城中更是充满春意，拂晓的时候，在树木葱茏之中，洒下一片淡淡的春阴。长乐宫的钟敲响了，钟声飞过宫墙，飘到空中，又缓缓散落在花树之外。那曾经是玄宗皇帝发祥之地的龙池，千万株春意盎然的杨柳，在细雨之中越发显得...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290b1", "shortContent": "此诗是唐代诗人钱起的作品。这是一首投赠诗，当作于大历四年（769），时钱起48岁，任蓝田尉已十年，作此诗求裴舍人引荐。唐代皇帝身边的职官，有通事舍人、起居舍人、中书舍人。这些“侍从之臣”每天都要随侍皇帝左右，过问机密大事，实际权力很大。此诗的弦外之音，是希望裴舍人给予援引，历来以用景色隐含的请求提携之意和不落窠臼的恭维手段而闻名。此诗后钱起果然得到推举，任司勋员外郎。\n\n诗歌前半部分以写景为主，但...", "authors": ["阮森丽"], "pressName": "崇文书局"}]', '《批点唐诗正声》：禁体极为佳语，贵在有无点缀。
《唐诗广选》：刘会孟曰：有情、有味，有体，色深可观。
《唐诗镜》：中唐七律时见偃纵，故体格不严。
《诗源辨体》：气亦不薄。
《唐风定》：天然富丽，气象宏远，文房之所不及。
《唐诗评选》：“花外尽”，乃以写花蹊之远，借钟作假，对以灵绝。
《载酒园诗话又编》：昔人推钱诗者，多举“长乐钟声花外尽，龙池柳色雨中深”。予以二语诚一篇警策，但读其全篇，终似公厨之馔，餍腹有余，爽口不足，去王维、李颀尚远。
《唐诗绎》：通首逐层顶接，丝缕细密。
《唐诗贯珠》：法脉细极。
《增订唐诗摘钞》：“花外尽”者，不闻于外也；“雨中深”者，独蒙其泽也。
《唐诗别裁》：诗格近李东川（首句下）。
《唐诗成法》：前半羡舍人之得志，后半伤己之不遇。
《网师园唐诗笺》：华赡，更余风致（“长乐钟声”一联下）。
《大历诗略》：颔联比兴微妙，非徒丽句也。结似气尽，然向达官而叹老嗟卑，此岂无意耶？
《历代诗法》：工致流丽，中唐佳律也。
《唐诗笺注》：上四句从阙下想象着笔，下半悲不遇，故有“羞对华簪”之句。
《唐诗向荣集》：钟声从里面一层一层想出来，柳色从外面一层一层看进去，才觉得“尽”字、“深”字之妙，而神韵悠长，气味和厚，殊难遽造此诣，宜当时之脍炙人口。
《唐诗三百首》：句句从阙下生情。
《唐诗笺要》：气格虽逊宝应以前，而不落软媚。员外之雄迈，所以直继右丞也。
《匡山丛话》：“长乐钟声花外尽，龙池柳色雨中深”，不减盛唐之音。
《昭昧詹言》：前四句写阁景气象，真朴自然，不减盛唐王摩诘，后四句托赠常语，平平耳。
《唐诗五七言近体五七言绝句选评》：何减东川风调？唯结意平直。', 'center', 1423215622, '57b90253a633bd00665d59a3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10613, '寄李儋元锡', NULL, 168, 570, 4, 2, '韦应物', NULL, 10115, '57b9b835128fe1005f860400', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383597.htm', '', '去年花里逢君别，今日花开又一年。
世事茫茫难自料，春愁黯黯独成眠。
身多疾病思田里，邑有流亡愧俸钱。
闻道欲来相问讯，西楼望月几回圆。', '此诗描述了诗人与友人分别之后的思念。开首二句即景生情，花开花落，引起对茫茫世事的感叹。接着直抒情怀，写因多病而想辞官归田，反映内心的矛盾。“邑有流亡愧俸钱”，不仅是仁人自叹未能尽责，也流露进退两难的苦闷。结尾道出寄诗的用意，是极需友情的慰勉，渴望和友人畅叙。全诗起于分别，终于相约，体现了朋友间的深挚友谊，感情细腻动人，同时章法严密，对仗工整，用语婉转，堪为七律名篇。', '李儋（dān）元锡：李儋，曾任殿中侍御史，为作者密友；
元锡：字君贶（kuàng），为作者在长安鄠县时旧友。
春愁：因春季来临而引起的愁绪。
黯黯：一作「忽忽」。低沉暗淡。
思田里：想念田园乡里，即想到归隐。
邑有流亡：指在自己管辖的地区内还有百姓流亡。
愧俸钱：感到惭愧的是自己食国家的俸禄，而没有把百姓安定下来。
问讯：探望。', '去年那花开时节我们依依惜别，如今花开时节我们分别已一年。
世事渺茫自我的命运怎能预料，只有黯然的春愁让我孤枕难眠。
多病的身躯让我想归隐田园间，看着流亡的百姓愧对国家俸禄。
早听说你将要来此地与我相见，我到西楼眺望几度看到明月圆。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b90ce818559d0587c6", "shortContent": "这首七律是韦应物晚年在滁州（治今安徽滁州市）刺史任上的作品。唐德宗建中四年（783）暮春入夏时节，韦应物从尚书比部员外郎调任滁州刺史，离开长安，秋天到达滁州任所。李儋，字元锡，是韦应物的诗交好友，当时任殿中侍御史，在长安与韦应物分别后，曾托人问候。次年春天，韦应物写了这首诗寄赠李儋以答。诗中叙述了别后的思念和盼望，抒发了国乱民穷造成的内心矛盾和苦闷。\n在韦应物赴滁州任职的一年里，他亲身接触到人民生...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a8e", "shortContent": "这首七律是韦应物晚年在滁州（治今安徽滁州市）刺史任上的作品。唐德宗建中四年（783）暮春入夏时节，韦应物从尚书比部员外郎调任滁州刺史，离开长安，秋天到达滁州任所。李儋，字元锡，是韦应物的诗交好友，当时任殿中侍御史，在长安与韦应物分别后，曾托人问候。次年春天，韦应物写了这首诗寄赠李儋以答。诗中叙述了别后的思念和盼望，抒发了国乱民穷造成的内心矛盾和苦闷。\n\n在韦应物赴滁州任职的一年里，他亲身接触到人民...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290b2", "shortContent": "作为山水田园诗派代表的韦应物作诗、为人常学陶潜，然其性情却少了陶的那份古质豁达，或仕或隐的矛盾常使他陷入苦闷的状态中。这首七律寄赠诗借叙别后对友人之思，表达出了诗人内心强烈的矛盾。\n\n此诗作于韦应物晚年滁州刺史任上，为感怀时事，思念友人之作。建中四年（783）冬，泾原兵变，导致朝政紊乱，民生凋敝。韦应物在地方为官，曾多次派人北上探听消息，皆无音讯。李儋，给事中李升期之子，曾官殿中侍御史，是诗人密友...", "authors": ["何月燕"], "pressName": "崇文书局"}]', '《巩溪诗话》：节苏州《赠李儋》云：「身多疾病思田里，邑有流亡愧俸钱。」《郡中燕集》云：「自惭居处崇，未睹斯民康。」余谓有官君子当切切作此语。彼有一意供祖，专事土木，而视民如仇者，得无愧此诗乎？
《韦孟全集》：简淡之怀，百世犹为兴慨。
《瀛奎律髓》：朱文公盛称此诗五、六好，以唐人仕宦多夸美州宅风土。此独谓「身多疾病」、「邑有流亡」，贤矣。
《唐音癸签》：韦左司「身多疾病思田里，邑有流亡愧俸钱」，仁者之言也。刘辰翁谓其居官自愧，闵闵有恤人之心，正味此两语得之。若高常侍「拜迎官长心欲碎、鞭挞黎庶令人悲」、亦似厌作官者，但语微带傲，未必真有退心如左司之一向淡耳。
《此木轩论诗汇编》：「邑有流亡」句，高在闲放在第六句，只与上下文一般随口说，不是特地说，如云我之用心如此如此也。此不是为作诗者说法，乃是看诗之法，闻其乐而知其德也。
《唐律偶评》：此句中暗藏「望」字（「今日花开」句下）。
《唐体肤诠》：中四句自述近况，寄怀意唯于起结作呼应。然次句击动三、四，七句暗承五、六，又未尝不关照也。
《唐七律隽》：此等诗只家常话、烂熟调耳，然少时读之，白首而不厌者，何也？与老杜《寄旻上人》之作，可称伯仲。
《瀛奎律髓汇评》：冯舒：圆熟却轻茜。纪昀：上四句竟是闺情语，殊为疵累。五、六亦是淡语，然出香山辈手便俗浅，此于意境辨之。七律虽非苏州所长，然气韵不俗，胸次本高故也。许印芳：晓岚讥前半为闺情语，虽是刻核太过，然亦可见诗人措词各有体裁，下笔时检点偶疏，便有不伦不类之病，作者不自知其非，观者亦不觉其谬，病在诗外故也。
《唐宋诗举要》：吴曰：情景交融（「世事茫茫」二句下）。蔼然仁者之言（「邑有流亡」句下）。曰：本言今日思寄，却追述前此，益见情真，亦是补法。三句承「一年」，放空一句，四句兜回自己，五六接写自己怀抱，末始入今日寄意。', 'center', 1417463893, '57b97867165abd0054c42321', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10620, '遣悲怀（其三）', NULL, 123, 890, 1, 2, '元稹', NULL, 10082, '57b9bf37d342d3006be01c7b', '唐', 'shi', '诗', 'http://baike.baidu.com/view/159046.htm', '', '闲坐悲君亦自悲，百年都是几多时。
邓攸无子寻知命，潘岳悼亡犹费词。
同穴窅冥何所望，他生缘会更难期。
惟将终夜常开眼，报答平生未展眉。', '此诗为《遣悲怀》组诗的第三首。由妻子的早逝，想到了人寿的有限。人生百年，也没有多长时间。诗中引用了邓攸、潘岳两个典故。邓攸心地如此善良，却终身无子，这就是命运的安排。潘岳《悼亡诗》写得再好，对于死者来说，也没有什么意义，等于白费笔墨。诗人以邓攸、潘岳自喻，故作达观无谓之词，却透露出无子、丧妻的深沉悲哀。接着从绝望中转出希望来，寄希望于死后夫妇同葬和来生再作夫妻。但是，再冷静思量：这仅是一种虚无缥缈的幻想，更是难以指望的，因而更为绝望：死者已矣，过去的一切永远无法补偿了！诗情愈转愈悲，不能自已，最后逼出一个无可奈何的办法：「惟将终夜长开眼，报答平生未展眉。」诗人仿佛在对妻子表白自己的心迹：我将永远永远地想着你，要以终夜「开眼」来报答你的「平生未展眉」。真是痴情缠绵，哀痛欲绝。', '都是：一作“多时”。
邓攸：西晋人，字伯道，官河西太守。《晋书·邓攸传》载：永嘉末年战乱中，他舍子保侄，后终无子。
潘岳：西晋人，字安仁，妻死，作《悼亡诗》三首。这两句写人生的一切自有命定，暗伤自己无妻无子的命运。
窅冥：深暗的样子。
常：一作「长」。', '闲坐无事为你悲伤为我感叹，人生短暂百年时间又多长呢！
邓攸没有后代是命运的安排，潘岳悼念亡妻只是徒然悲鸣。
即使能合葬也无法倾诉衷情，来世结缘是多么虚幻的企望。
只能睁着双眼整夜把你思念，报答你平生不得伸展的双眉。', '[{"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad4797a92d5e4fd90e", "shortContent": "这是元稹悼念亡妻韦丛（字蕙丛）所写的三首七言律诗。韦氏是太子少保韦夏卿的幼女，二十岁时嫁与元稹。七年后，即元和四年（809）七月，韦氏去世。此诗约写于元和六年前，时元稹在监察御史分务东台任上。\n\n第一首追忆妻子生前的艰苦处境和夫妻情爱，并抒写自己的抱憾之情。一、二句引用典故，以东晋宰相谢安最宠爱的侄女谢道韫借指韦氏，以战国时齐国的贫士黔娄自喻，其中含有对方屈身下嫁的意思。“百事乖”，任何事都不顺遂...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127075e6f69b71e93f62dd", "shortContent": "中国历史上，悼亡诗写得较好的有潘岳与元稹，而元稹所有悼亡诗中，《遣悲怀》被公认为最佳，其情真意切，为后世传诵不已。\n\n此诗约作于元和四年（809），这一年，诗人爱妻韦氏因病去世。韦氏，即韦丛，字蕙丛，太子少保韦夏卿之幼女，二十岁时嫁与元稹，孰料七年之后便撒手人寰，遗一女。可以想见，妻子病亡时仅仅二十七岁，诗人也不过三十出头，正是少年夫妻恩爱之时，却不料遭此大祸。诗人饱受丧妻之痛，写下了三首《遣悲怀...", "authors": ["乐云"], "pressName": "崇文书局"}]', '', 'center', 1417514277, '57b9bfd27db2a20068be9c39', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (50923, '苏幕遮', NULL, 0, 26, 0, 1, '高道宽', NULL, 11195, '5858e6398d6d810065c3153c', '元', 'ci', '词', NULL, NULL, '大真元，超法界。锻炼精华，历劫常不坏。七朵金莲神通大。普度群迷，同赴蟠桃会。
紫金丹，白玉块。处处圆明，朗朗常现在。一派清流通方外。遍体阳神，出入谁能赛。', NULL, NULL, NULL, NULL, NULL, 'indent', 1529685194, '585cefbd128fe10069cb13b3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10614, '同题仙游观', NULL, 26, 165, 1, 1, '韩翃', NULL, 10131, '57bdc0b17db2a20068dc6903', '唐', 'shi', '诗', 'http://baike.baidu.com/view/350118.htm', '', '仙台初见五城楼，风物凄凄宿雨收。
山色遥连秦树晚，砧声近报汉宫秋。
疏松影落空坛静，细草香闲小洞幽。
何用别寻方外去，人间亦自有丹丘。', '此诗通过对景物的艺术再现，表达了诗人心境的空灵和出世之念。首联点明时地，切题“仙游观”；颔联写观外景物，先是“见”“秦树”，后是“闻”“砧声”；颈联写观内景物，先写高处“空坛”的静，后写低处“小洞”的幽，点明是道士居处；尾联称赞这地方是神仙居处的丹丘妙地，不必再去寻找“方外”之地了。全诗语言清新，文字秀美，韵律和谐，含蓄隽永，极富情趣。', '同题仙游观：一本无“同”字。仙游观：在今河南嵩山逍遥谷内。初唐时道士潘师正居住在当地的逍遥谷，唐高宗李治对他十分敬重，下令在逍遥谷口修筑仙游门，在谷中修筑道观。
仙台，高处的观景台。初：一作“下”。五城楼：道观的房舍。《史记·封禅书》记方士曾言：“黄帝时为五层十二楼，以候神人于执期，命曰迎年”，这里借指仙游观。
宿雨：隔宿的雨。
砧（zhēn）声：在捣衣石上捣衣的声音。
空坛：与下小洞皆指道观景物。
闲：一作“开”。
方外：尘世以外，《庄子·大宗师》“孔子曰：彼游方外者也，用丘游方之内者。”后引申为神仙居住的地方。
丹丘：指神仙居处，昼夜长明。', '在仙台上刚见到五城楼，夜雨初停景物冷落凄清。
晓山翠色遥连秦地树木，汉宫砧声报讯寒秋来临。
空坛澄清疏松影落水底，小洞清幽细草芳香沁人。
何必去寻找世外的仙境，人世间就有美好的桃源。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290b3", "shortContent": "题咏诗大致兴盛于唐玄宗时期，诗题大都冠有“题”字，多为诗人即兴而成，因此题中常含所咏之物。此诗是一首游览道观的七律题咏之作，是韩翃题咏诗中较为出名的一首。\n\n这首诗围绕“仙游观”层层展开。首联开篇点题，“五层楼”即指仙游观。第二句点明了游道观的时间是宿雨初收、风物凄清的深秋。诗人描摹出了仙游观的大致轮廓，故其所处的位置应在外围。\n\n颔联和颈联为细致的景物描写，用语对仗工整，值得称赏。诗人描景由远及...", "authors": ["何月燕"], "pressName": "崇文书局"}]', NULL, 'center', 1417510859, '57b99cd879bc44006029a9d7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10615, '春思', NULL, 39, 228, 1, 1, '皇甫冉', NULL, 10145, '57b9a095d342d3006bdecc8d', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/151545/10830343.htm', '', '莺啼燕语报新年，马邑龙堆路几千。
家住层城临汉苑，心随明月到胡天。
机中锦字论长恨，楼上花枝笑独眠。
为问元戎窦车骑，何时返旆勒燕然。', '这首诗是借闺妇抒写春怨，期望早日了结战事，征夫能功成名遂。诗的首联点明题意，首句点“春”，次句点路遥“相思”。颔联写少妇和征人所在之地，一在汉，一在胡，相隔千里。颈联写离恨，写春情。末联故作问语，问征夫何时功成返乡。全诗流露非战情绪，也是借汉咏唐，讽刺穷兵黩武。', '马邑：秦所筑城名，今山西朔县，汉时曾与匈奴争夺此城。龙堆：白龙堆得简称，指沙漠。
层城：因京城分内外两层，故称。苑：这里指行宫。
“机中”一句：窦滔为苻坚秦州刺史，后谪龙沙，其妻苏蕙能文，颇思滔，乃织锦为回文旋图诗寄之。共八百四十字，纵横反覆，皆成文意。论：表露，倾吐。
“为问”二句：后汉窦宪为车骑将军，大破匈奴，遂登燕然山，命班固作铭，刻石而还。元戎：犹主将。返旆：犹班师。勒：刻。燕然：燕然山，即今蒙古人民共和国杭爱山。', '莺歌燕语预报了临近新年，马邑龙堆是几千里的疆边。
家住京城比邻着汉室宫苑，心随明月飞到边陲的胡天。
织锦回文诉说思念的长恨，楼上花枝取笑我依然独眠。
请问你主帅车骑将军窦宪，何时班师回朝刻石燕然山。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290b4", "shortContent": "此诗以妇人之语而抒春怨，通过叙写妇人对征夫的相思之情，表达诗人强烈的反战情绪。诗人皇甫冉虽处盛唐，但边疆战事频发，征戍离情仍旧是诗人们反复吟咏的主题。\n\n首联点明“春思”主题，景物对比鲜明，情感动人心弦。“莺啼燕语”对应“马邑龙堆”，前者为春天生机勃勃之景，色彩绚烂明丽；后者为沙漠边城，生机稀落，漫天黄土。“报新年”对应“路几千”，前者喜庆团圆，后者远在千里，独守边戍。两组对比，氛围一温馨一落寞，...", "authors": ["何月燕"], "pressName": "崇文书局"}]', '', 'center', 1417511010, '57b975ef165abd0054c40cc6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10616, '晚次鄂州', NULL, 140, 341, 3, 2, '卢纶', NULL, 10014, '57b9c2f6c4c97100614832f4', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383604.htm', '', '云开远见汉阳城，犹是孤帆一日程。
估客昼眠知浪静，舟人夜语觉潮生。
三湘愁鬓逢秋色，万里归心对月明。
旧业已随征战尽，更堪江上鼓鼙声。', '这是一首卽景抒怀的诗。首联写「晚次鄂州」的心情。浓云散开，江天晴明，举目远眺，汉阳城依稀可见，因为「远」，还不可及，船行尚须一天。这样，今晚就不得不在鄂州停泊了。诗人由江西溯长江而上，必须经过鄂州（治所在今湖北武汉市武昌），直抵湖南。汉阳城在汉水北岸，鄂州之西。起句卽点题，述说心情的喜悦，次句突转，透露沉郁的心情，用笔腾挪跌宕，使平淡的语句体现微妙的思致。诗人在战乱中风波漂泊，对行旅生涯早已厌倦，巴不得早些得个安憩之所。因此，一到云开雾散，见到汉阳城时，不禁喜从中来。「犹是」两字，突显诗人感情的骤落。这二句，看似平常叙事，却彷彿使人听到诗人在拨动着哀婉缠绵的琴弦，倾诉着孤凄苦闷的心曲，透纸贯耳，情韵不匮。
颔联写「晚次鄂州」的景况。诗人简笔勾勒船舱中所见所闻：同船的商贾白天水窗倚枕，不觉酣然入梦，不言而喻，此刻江上扬帆，风平浪静；夜深人静，忽闻船夫相唤，杂着加缆扣舷之声，不问而知夜半涨起江潮来了。诗人写的是船中常景，然而笔墨中却透露出他昼夜不宁的纷乱思绪。所以尽管这些看惯了的舟行生活，似乎也在给他平增枯涩乏味的生活感受。
颈联写「晚次鄂州」的联想。诗人情来笔至，借景抒怀：时值寒秋，正是令人感到悲凉的季节，无限的惆怅已使我两鬓如霜了；我人往三湘去，心却驰故乡，独对明月，归思更切！「三湘」，是诗人此行的目的地。而诗人的家乡则在万里之遥的蒲州（今山西永济）。秋风起，落叶纷下，秋霜落，青枫凋，诗人无赏异地的秋色之心，却有思久别的故乡之念。一个「逢」字，将诗人的万端愁情与秋色的万般凄凉联系起来，移愁情于秋色，妙合无垠。「万里归心对月明」，其中不尽之意见于言外，有迢迢万里不见家乡的悲悲戚戚，亦有音书久滞萦怀妻儿的凄凄苦苦，真可谓愁肠百结，煞是动人肺腑。
尾联写「晚次鄂州」的感慨，写诗人有家不可归，衹得在异域他乡颠沛奔波的原因。最後二句，把忧心愁思更加地深化了：田园家计，事业功名，都随着不停息的战乱丧失殆尽，而烽火硝烟未灭，江上仍然传来干戈鸣响，战鼓声声。诗人虽然远离了沦为战场的家乡，可是他所到之处又无不是战云密布，这就难怪他愁上加愁了。诗的最後两句，把思乡之情与忧国愁绪结合起来，使此诗具有更大的社会意义。
这首诗，诗人衹不过截取了飘泊生涯中的一个片断，却反映了广阔的社会背景，写得连环承转，意脉相连，而且迂徐从容，曲尽情致。在构思上，不用典故来支撑诗架；在语言上，不用艳藻来求其绮丽；在抒情上，不用泼墨来露出筋骨。全诗淡雅而含蓄，平易而炽热，饶有韵味。', '晚次：指晚上到达。
鄂州：唐时属江南道，在今湖北武昌。
汉阳城：今湖北汉阳，在汉水北岸，鄂州之西。
一日程：指一天的水路。
估客：同行的贩货的行商。
舟人夜语觉潮生：因为潮生，故而船家相呼，众声杂作。舟人，船夫；夜语，晚上说话。
三湘：湘江的三条支流漓湘、潇湘、蒸湘的总称。在今湖南境内。由鄂州上去卽三湘地。这里泛指汉阳、鄂州一带。
衰鬓逢秋色：衰鬓承受着秋色。这里的鬓髮已衰白，故也与秋意相应。衰鬓，一作「愁鬓」。
征战：指安史之乱。
更堪：更难堪，犹岂能再听。
江：指长江。
鼓鼙（pí）：军用大鼓和小鼓，後也指战事。', '眼前的浓雾渐渐散开，似乎能远远的望见汉阳城，还要独自漂泊一日就要回到家乡了。船上的一些商贾白天睡足了觉，只觉得外面风平浪静，晚上船夫与他谈话时，方听到阵阵潮声，而我，今夜注定无眠。秋意正浓，我的鬓发也渐渐斑白。内心急切的思归之情，只有对着明月默默倾诉。曾经家乡的旧业已随着连年战火烟消云散，耳边似乎还听到江边振振战鼓声。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ba2e6a6b501f95c25b", "shortContent": "《全唐诗》于本篇题下注“至德中作”。至德（756—758），唐肃宗李亨年号，时当在安史之乱的前期。由于战乱，诗人被迫浪迹异乡，流徙不定。在南行途中，他写了这首诗。\n首联写“晚次鄂州”的心情。浓云散开，江天晴明，举目远眺，汉阳城依稀可见；因为“远”，还不可及，船行尚须一天。这样，今晚就不得不在鄂州停泊了。诗人由江西溯长江而上，必须经过鄂州（治所在今湖北武汉市武昌），直抵湖南。汉阳城在汉水北岸，鄂州之...", "authors": ["周溶泉徐应佩"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290b5", "shortContent": "南宋严羽《沧浪诗话》言：“唐人好诗，多是征戍、迁谪、行旅、离别之作，往往能感动激动人意。”此诗为卢纶乘船夜宿于鄂州时的感兴伤怀之作，当时正值安史之乱前期，诗人为避战祸，背井离乡，受尽颠沛流离之苦，因此这首诗情感真实直露，常为后世文人所称赏。\n\n思念深切之时，最易产生错觉。诗人避乱客居鄱阳，乘船游历三湘。云开雾散，江天晴明，诗人举目远眺，汉阳城似乎依稀可见。但事实距汉阳还有一日的水路，而日暮已晚，只...", "authors": ["何月燕"], "pressName": "崇文书局"}]', '《艇斋诗话》：「估客」一联，曲尽江行之景，真善写物也。予每诵之。
《批点唐诗》：第四句尤妙，但对上句却浅。五、六迥别。结宛转，极悲。
《唐诗正声》：旲逸一评：次联老江湖语，三联语忽不测，结悲，酷入情。
《批选唐诗》：清通熟爽，是近体佳篇。
《唐诗选脉会通评林》：何景明曰；二联妙。田艺衡曰：乱後之辞，可怜。陈继湍曰：旅思动人。伤感却不作异调，故佳。郭浚曰：情景不堪萧瑟。
《唐诗鼓吹笺注》：总是彻夜未眠急归情绪也，後四句一气赶下，是倒卷（「估客昼眠」二句下）。
《唐风定》：初联世所共称，不知次联更胜。
《贯华堂选批唐才子诗》：前解写尽急归神理。言望见汉阳，便欲如隼疾飞，立抵汉阳，而无奈计其远近，尚必再须一日也。三、四承之，言虽明知再须一日，而又心头眼底，不沉忽忽欲云。于是厌他估客，胡故昼眠；喜他舟人，斗地夜语。盖昼眠，便是不思速归之人，夜语，便有可以速云之理也。若衹作写景读之，则既云「浪静」，又云「潮生」，此成何等文法哉！後解言吾今欲归所以如此急者，实为鬓对三湘，心驰万里，传闻旧业，已无可归，而连日江行，鼓鼙不歇，谁复能遣？尚堪一朝乎哉！
《五朝诗善鸣集》：诗有高静之气，故白描而绝远于俚。
《唐诗贯珠》：「浪静」映「公开」，「夜语」由于「晚次」。三、四构句，曲尽水程情景，气度大方精妙。
《唐三体诗评》：何焯云：惊魂不定，贪程难待，合下四句读之，其意味更长。
《唐律偶评》：前半极写归心之迫，却不露所以「次」之故，至结解码器方说明，读之但沉其如画耳。浪静则可以兼程，潮生更宜夜发，乃胡为淹此留也？发「次」字，暗呼起江上兵阻，非无眼之铺叙。
《唐体肤诠》：屈复云：一归心急，二有咫尺千里意。中四「衰鬓」、「归心」，人眼中耳中无限悲凉，故客眠人语，秋色月明，种种堪愁。用意深妙，全以神行，若无题无涉者，结言归亦无益，将来不知作何景象，愁无已时也。
《大历诗略》：有情景，有声调，气势亦足，大历名篇。
《山满楼笺注唐诗七言律》：第六句中「归心」二字，是一篇之眼。前五句写归心之急，後二句写归心所以如此急之故。「万进而逢秋色」则愁鬓不胜憔悴。「对月明」则归心愈觉凄惶，字字真情，字字实理。
《网师园唐诗笺》：写景亲切（「舟人夜语」句下）。
《昭昧詹言》：起句点题。次句缩转。用笔转折有势。三、四兴在象外，卓然名句，五、六亦兼情景，而平平无奇。收切鄂州，有远想。
《诗境浅说》：作客途诗，起笔须切合所在之境，而能领起全篇，乃为合作。此诗前半首尤佳。其起句言：江天浩莽，已远见汉阳城郭，而江阔帆迟，尚费行程竟日，情景真切，句法亦纡徐有致。三句言：浪平舟稳，估客高眠。丹在湍急处行舟，篙舻声终日不绝，唯江上扬帆，但闻船唇啮浪，吞吐作声，四十我人语，水窗倚枕，不沉寐之酣也。四句言：野岸维舟，夜静闻舟人相唤，加缆扣舷。众声杂作，不闻而知为夜潮来矣。诵此二句，宛若身在江船容与之中。可见诗贵天然，不在专工雕琢。', 'center', 1417511102, '57b8f0a00a2b58005c91d6fc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10617, '登柳州城楼寄漳汀封连四州', NULL, 98, 243, 4, 3, '柳宗元', NULL, 10055, '57b9042f7db2a2005426b940', '唐', 'shi', '诗', 'http://baike.baidu.com/view/159531.htm', '', '城上高楼接大荒，海天愁思正茫茫。
惊风乱飐芙蓉水，密雨斜侵薜荔墙。
岭树重遮千里目，江流曲似九回肠。
共来百越文身地，犹自音书滞一乡。', '此诗是唐代文学家柳宗元于唐宪宗元和十年（公元815年）创作并寄与际遇相同的韩泰、韩晔、陈谏、刘禹锡的一首七律。诗中寄赠四位共患难而天各一方的朋友，抒写思念朋友而难以见面之意，表现出一种真挚的友谊，虽天各一方，却有无法自抑的相思之苦。此外，“海天愁思”中亦当包括身世坎坷、世事莫测、仕途险恶之叹。诗人写风雨侵颭、岭树遮挡，不仅仅是言自然现象，也蕴含了诗人遭贬以后忧恐烦乱的心境特点。', '柳州：今属广西。
漳：漳州。
汀：汀洲，今属福建。
封：封州。
连：连州，今属广东。《旧唐书·宪宗纪》：“乙酉（元和十年）三月，以虔州司马韩泰为漳州（今福建漳州）刺史，永州司马柳宗元为柳州（今广西柳州）刺史，饶州司马韩晔为汀州（今福建长汀县）刺史，朗州司马刘禹锡为播州刺史，台州司马陈谏为封州，（今广东封川县）。御史中丞裴度以禹锡母老，请移近处，乃改授连州（今广东连县）刺史。”
接：连接。一说，目接，看到。
大荒：泛指荒僻的边远地区。
海天愁思：如海如天的愁思。
惊风：急风、狂风。曹植《赠徐幹》：“惊风飘白日，忽然归西山。”
乱飐（zhǎn）：吹动。《说文》：“风吹浪动也。”芙蓉：指荷花。崔豹《古今注·卷下》：“芙蓉，一名荷华，生池泽中，实曰莲，花之最秀异者。”沈德潜曰：“惊风、密雨，言在此而意不在此。”
薜荔：一种蔓生植物，也称木莲。
重遮：层层遮住。
千里目：这里指远眺的视线。
江：指柳江。
九回肠：愁肠九转，形容愁绪缠结难解。司马迁《报任少卿书》：“肠一日而九回。”梁简文帝《应全诗》：“望邦畿兮千里旷，悲遥夜兮九回肠。”
共来：指和韩泰、韩华、陈谏、刘禹锡四人同时被贬远方。百越：即百粤，泛指五岭以南的少数民族。贾谊《过秦论》：“南取百越之地，以为桂林、象郡。”
文身：身上文刺花绣，古代有些民族有此习俗。文，通“纹”，用作动词。《庄子·逍遥游》：“越人断髮文身。”《淮南子·原道训》：“九嶷之南，陆事寡而水事众，于是民人披髮文身，以象鳞虫。”
犹自：仍然是。
音书：音信。
滞：阻隔。', '登上高楼远眺，眼前一片荒凉，令人愁思无限。
狂风四起，惊动了水中荷花；暴雨骤下，抽打着墙上的薜荔。
想起同遭贬逐的朋友，怎奈崇山密林，遮住了千里的目光，让我无法远望。
柳江曲折，又似那九回的愁肠，叫我更加郁闷。在这偏僻的蛮荒之地，就是互通音讯，也是困难重重。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92cb0f8fda55650555b6", "shortContent": "这是首抒情诗，赋中有比，象中含兴，展现了一幅情景交融的动人图画；而抒情主人公的神态和情怀，也依稀可见。这情怀，是特定的政治斗争环境所触发的。\n公元805年，唐德宗李适死，太子李诵（顺宗）即位，改元永贞，重用王叔文、柳宗元等革新派人物，但由于保守势力的反扑，仅五个月，“永贞革新”就遭到残酷镇压。王叔文、王伾被贬斥而死，革新派的主要成员柳宗元、刘禹锡等八人分别谪降为远州司马。这就是历史上所说的“二王八...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad4797a92d5e4fd909", "shortContent": "这是首抒情诗，赋中有比，象中含兴，展现了一幅情景交融的动人图画；而抒情主人公的神态和情怀，也依稀可见。这情怀，是特定的政治斗争环境所触发的。\n\n公元805年，唐德宗李适死，太子李诵（顺宗）即位，改元永贞，重用王叔文、柳宗元等革新派人物，但由于保守势力的反扑，仅五个月，“永贞革新”就遭到残酷镇压。王叔文、王伾被贬斥而死，革新派的主要成员柳宗元、刘禹锡等八人分别谪降为远州司马。这就是历史上所说的“二王...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290b6", "shortContent": "贞元二十一年（805），王叔文领导的永贞革新宣告失败，其主要人物十人均被贬斥，史称“二王八司马”，柳宗元是八司马之一。元和十年（815），柳宗元等人循例被召至京师，大臣中虽有人主张起用他们，终因有人梗阻，再度被贬。柳宗元改迁柳州刺史，韩泰、韩晔、陈谏、刘禹锡也分别出任漳州、汀州、封州、连州刺史。\n\n他们五人在参加政治改革运动时已建立了深厚的友谊，作者曾有过“皇恩若许归田去，晚岁当为邻舍翁”（《衡阳...", "authors": ["王萍"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127074e6f69b71e93f62cc", "shortContent": "元和十年（815），柳宗元与韩泰、韩晔、陈谏、刘禹锡等五人奉召回京，结果是被分派到南方做刺史，虽然官位提升了，却是被分派到更荒凉的“百越”之地。他们五人在参加政治改革运动时已建立了深厚的友谊，作者曾有过“皇恩若许归田去，晚岁当为邻舍翁”（《重别梦得》）的愿望。一到柳州，诗人首先做的事就是登上高楼，寻找朋友的处所，希望借高楼来实现“千里目”。然而站在高高的城楼之上，眺望到的却只是旷漠空寂的原野。疾风...", "authors": ["王萍"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127123e6f69b71e93f63a9", "shortContent": "元和十年（815），柳宗元与韩泰、韩晔、陈谏、刘禹锡四人奉召回京，结果是被分派到南方做刺史，虽然官位提升了，却是被分派到更荒凉的“百越”之地。他们五人在参加政治改革运动时已建立了深厚的友谊，作者曾有过“皇恩若许归田去，晚岁当为邻舍翁”（《重别梦得》）的愿望。一到柳州，诗人首先做的事就是登上高楼，寻找朋友的处所，希望借高楼来实现“千里目”。然而站在高高的城楼之上，眺望到的却只是旷漠空寂的原野。疾风阵...", "authors": ["王萍"], "pressName": "崇文书局"}, {"bookId": "645d12f76de2f61f4bb3feb6", "bookTitle": "柳宗元诗文鉴赏辞典", "articleId": "646c155e30675327e1a7b6db", "shortContent": "这是首抒情诗，赋中有比，象中含兴，展现了一幅情景交融的动人图画；而抒情主人公的神态和情怀，也依稀可见。这情怀，是特定的政治斗争环境所触发的。\n公元805年，唐德宗李适死，太子李诵（顺宗）即位，改元永贞，重用王叔文、柳宗元等革新派人物，但由于保守势力的反扑，仅五个月，“永贞革新”就遭到残酷镇压。王叔文、王伾被贬斥而死，革新派的主要成员柳宗元、刘禹锡等八人分别谪降为远州司马。这就是历史上所说的“二王八...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '廖文炳《唐诗鼓吹注解》：此子厚登城楼怀四人而作，首言登楼远望，海阔连天，愁思与之弥漫，不可纪极也。三四句唯“惊风”，故云“乱颴”，唯“细雨”，故云“斜侵”，有风雨萧条，触物兴怀意。至“岭树重遮”、“江流曲转”，益重相思之感矣。当时“共来百越”，意谓易于相见，今反音问疏隔，将何以慰所思哉？
查慎行《初白庵诗评》：（首二句）起势极高，与少陵''花近高楼''两句同一手法。
沈德潜《唐诗别裁》：从高楼起，有百感交集之感惊风、密雨，言在此而意不在此。
俞陛云《诗境浅说·丙编》：唐代韩柳齐名，皆遭屏逐。昌黎《蓝关》诗，见忠愤之气，子厚柳州诗，多哀怨之音。起笔音节高亮，登高四顾，有苍茫百感之慨。三、四言临水芙蓉，覆墙薜荔，本有天然之态，乃密雨惊风横加侵袭，致嫣红生翠，全失其度。以风雨喻谗人之高张，以薜荔芙蓉喻贤人之摈斥，犹楚词之以兰蕙喻君子，以雷雨喻摧残，寄慨遥深，不仅写登城所见也。五、六言岭树云遮，所思不见，临江迟客，肠转车轮。恋阙怀人之意，兼而有之。收句归到寄诸友本意，言同在瘴乡，已伤谪宦，况音书不达，雁渺鱼沉，愈悲孤寂矣。', 'center', 1417511212, '57b907bc5bbb50005b785ba4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10618, '遣悲怀（其一）', NULL, 67, 890, 1, 2, '元稹', NULL, 10082, '57b9bf37d342d3006be01c7b', '唐', 'shi', '诗', 'http://baike.baidu.com/view/159046.htm', '', '谢公最小偏怜女，自嫁黔娄百事乖。
顾我无衣搜荩箧，泥他沽酒拔金钗。
野蔬充膳甘长藿，落叶添薪仰古槐。
今日俸钱过十万，与君营奠复营斋。', '此诗为《遣悲怀》组诗的第一首，追忆妻子生前的艰苦处境和夫妻情爱，并抒写自己的抱憾之情。一、二句引用典故，以东晋宰相谢安最宠爱的侄女谢道韫借指韦氏，以战国时齐国的贫士黔娄自喻，其中含有对方屈身下嫁的意思。「百事乖」，任何事都不顺遂，这是对韦氏婚后七年间艰苦生活的简括，用以领起中间四句。「泥」，软缠。「长藿」，长长的豆叶。中间这四句是说：看到我没有可替换的衣服，就翻箱倒柜去搜寻；我身边没钱，死乞活赖地缠她买酒，她就拔下头上金钗去换钱。平常家里只能用豆叶之类的野菜充饥，她却吃得很香甜；没有柴烧，她便靠老槐树飘落的枯叶以作薪炊。这几句用笔干净，既写出了婚后「百事乖」的艰难处境，又能传神写照，活画出贤妻的形象。这四个叙述句，句句浸透着诗人对妻子的赞叹与怀念的深情。末两句，仿佛诗人从出神的追忆状态中突然惊觉，发出无限抱憾之情：而今自己虽然享受厚俸，却再也不能与爱妻一道共享荣华富贵，只能用祭奠与延请僧道超度亡灵的办法来寄托自己的情思。「复」，写出这类悼念活动的频繁。这两句，出语虽然平和，内心深处却是极其凄苦的。', '谢公：东晋宰相谢安，他最偏爱侄女谢道韫。
黔娄：战国时齐国的贫士。此自喻。言韦丛以名门闺秀屈身下嫁。百事乖：什么事都不顺遂。
荩箧：竹或草编的箱子。
泥：软缠，央求。
藿：豆叶，嫩时可食。
奠：祭奠，设酒食而祭。', '你如同谢公最受偏爱的女儿，嫁给我这个贫士事事不顺利。
你见我没有衣衫就在箱子找，你拔下金钗因我相求而买酒。
你用野蔬充饥却说食物甘美，你用落叶作薪你用枯枝做炊。
如今我高官厚禄你却离人间，为你祭奠延请僧道超度士灵。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92cd03572034f659e55e", "shortContent": "这是元稹悼念亡妻韦丛（字蕙丛）所写的三首七言律诗。韦氏是太子少保韦夏卿的幼女，二十岁时嫁与元稹。七年后，即元和四年（809）七月，韦氏去世。此诗约写于元和六年前，时元稹在监察御史分务东台任上。\n第一首追忆妻子生前的艰苦处境和夫妻情爱，并抒写自己的抱憾之情。一、二句引用典故，以东晋宰相谢安最宠爱的侄女谢道韫借指韦氏，以战国时齐国的贫士黔娄自喻，其中含有对方屈身下嫁的意思。“百事乖”，任何事都不顺遂，...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f09352", "shortContent": "中国历史上，悼亡诗写得较好的有潘岳与元稹，而元稹所有悼亡诗中，《遣悲怀》被公认为最佳，其情真意切，为后世传诵不已。\n\n此诗作约作于元和四年（809），这一年，诗人爱妻韦氏因病去世。韦氏，即韦丛，字蕙丛，太子少保韦夏卿之幼女，二十岁时嫁与元稹，殊料七年之后便撒手人寰，遗一女。可以想见，妻子病亡时仅仅二十七岁，诗人也不过三十出头，正是少年夫妻恩爱之时，却不料遭此大祸。诗人饱受丧妻之痛，写下了三首《遣悲...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271317ccdb86c49f292ee", "shortContent": "中国历史上，悼亡诗写得较好的有潘岳与元稹，而元稹所有悼亡诗中，《遣悲怀》被公认为最佳，其情真意切，为后世传诵不已。\n此诗约作于元和四年（809），这一年，诗人爱妻韦氏因病去世。韦氏，即韦丛，字蕙丛，太子少保韦夏卿之幼女，二十岁时嫁与元稹，孰料七年之后便撒手人寰，遗一女。可以想见，妻子病亡时仅仅二十七岁，诗人也不过三十出头，正是少年夫妻恩爱之时，却不料遭此大祸。诗人饱受丧妻之痛，写下了三首《遣悲怀》...", "authors": ["乐云"], "pressName": "崇文书局"}]', '', 'center', 1417511425, '57b99cdf7db2a20054f7c52e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10621, '望月有感', NULL, 223, 2952, 3, 6, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383618.htm', '自河南经乱，关内阻饥，兄弟离散，各在一处。因望月有感，聊书所怀，寄上浮梁大兄、於潜七兄、乌江十五兄，兼示符离及下邽弟妹。', '时难年荒世业空，弟兄羁旅各西东。
田园寥落干戈后，骨肉流离道路中。
吊影分为千里雁，辞根散作九秋蓬。
共看明月应垂泪，一夜乡心五处同。', '此诗描写了动乱时期田园荒芜、骨肉分离的情景，表现了战乱给人民带来的灾难，抒发了兄弟姐妹间的思念之情。全诗句句扣紧主题，言辞清丽，不加雕饰，淡而有致，意蕴精深，情韵动人。', '河南：唐时河南道，辖今河南省大部和山东、江苏、安徽三省的部分地区。
关内：关内道，辖今陕西大部及甘肃、宁夏、内蒙的部分地区。
阻饥：遭受饥荒等困难。
浮梁大兄：白居易的长兄白幼文，贞元十四、五年（798~799年）间任饶州浮梁（今属江西景德镇）主簿。
於潜七兄：白居易叔父白季康的长子，时为於潜（今浙江临安县）县尉。
乌江十五兄：白居易的从兄白逸，时任乌江（今安徽和县）主簿。
符离：在今安徽宿县内。白居易的父亲在彭城（今江苏徐州）作官多年，就把家安置在符离。
下邽：县名，治所在今陕西省渭南县。白氏祖居曾在此。
时难年荒：指遭受战乱和灾荒。荒，一作“饥”。
世业：祖传的产业。唐代初年推行授田制度，所授之田分“口分田”和“世业田”，人死后，子孙可以继承“世业田”。
羁旅：漂泊流浪。
寥落：荒芜零落。
干戈：古代两种兵器，此代指战争。
吊影：一个人孤身独处，形影相伴，没有伴侣。
千里雁：比喻兄弟们相隔千里，皆如孤雁离群。
辞根：草木离开根部，比喻兄弟们各自背井离乡。
九秋蓬：深秋时节随风飘转的蓬草，古人用来比喻游子在异乡漂泊。九秋，秋天。
乡心：思亲恋乡之心。
五处：即诗题所言五处。', '自从河南地区经历战乱，关内一带漕运受阻致使饥荒四起，我们兄弟也因此流离失散，各自在一处。因为看到月亮而有所感触，便随性写成诗一首来记录感想，寄给在浮梁的大哥、在於潜的七哥，在乌江的十五哥和在符离、下邽的弟弟妹妹们看。
家业在灾年中荡然一空，兄弟分散各自你西我东。
战乱过后田园荒芜寥落，骨肉逃散在异乡道路中。
吊影伤情好像离群孤雁，漂泊无踪如断根的秋蓬。
同看明月都该伤心落泪，一夜思乡心情五地相同。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c8911759740c9b1be9", "shortContent": "白居易所处的中唐是一个多难的时代，他从十多岁开始，即因战乱而离家四处漂泊。德宗贞元十五年（799）春，宣武军（治所在今河南开封）节度使董晋死，其部下举兵叛乱。继之彰义军（治所在河南汝南）节度使吴少诚亦叛，唐朝廷不得不发兵征讨，河南一带再次沦为战乱的中心。由于漕运受阻，加上旱荒频仍，关内（今陕西省中部、北部及甘肃一部分地区）饥馑十分严重。就在这一年秋，白居易为宣州刺史所贡，第二年春在长安考中进士，旋...", "authors": ["左成文"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad4797a92d5e4fd901", "shortContent": "白居易所处的中唐是一个多难的时代，他从十多岁开始，即因战乱而离家四处漂泊。德宗贞元十五年（799）春，宣武军（治所在今河南开封）节度使董晋死，其部下举兵叛乱。继之彰义军（治所在河南汝南）节度使吴少诚亦叛，唐朝廷不得不发兵征讨，河南一带再次沦为战乱的中心。由于漕运受阻，加上旱荒频仍，关内（今陕西省中部、北部及甘肃一部分地区）饥馑十分严重。就在这一年秋，白居易为宣州刺史所贡，第二年春在长安考中进士，旋...", "authors": ["左成文"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f09353", "shortContent": "据白居易研究专家朱金城先生考证，此诗大约作于贞元十五年（799），此时白居易在洛阳。世乱时离，望月怀远，因作此诗。\n\n十几年前的建中、兴元年间，河南、关内均有乱事。河南有李希烈之乱，关内有朱泚之乱，白居易一家在乱离之中，流散四方。浮梁，即今江西省浮梁县，唐时属饶州，白居易长兄幼文曾任浮梁知县。於潜，在今浙江省临安市，唐属杭州，白居易从兄曾官於潜尉。乌江，在今安徽和县，唐属和州，白居易从兄白逸曾任乌...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645d09bbec56251f2eeb5b78", "bookTitle": "白居易诗文鉴赏辞典", "articleId": "6462d0ed5fc8182fe9958668", "shortContent": "白居易所处的中唐是一个多难的时代，他从十多岁开始，即因战乱而离家四处漂泊。德宗贞元十五年（799）春，宣武军（治所在今河南开封）节度使董晋死，其部下举兵叛乱。继之彰义军（治所在河南汝南）节度使吴少诚亦叛，唐朝廷不得不发兵征讨，河南一带再次沦为战乱的中心。由于漕运受阻，加上旱荒频仍，关内（今陕西省中部、北部及甘肃一部分地区）饥馑十分严重。就在这一年秋，白居易为宣州刺史所贡，第二年春在长安考中进士，旋...", "authors": ["左成文"], "pressName": "上海辞书出版社"}]', '', 'center', 1417514485, '57b926235bbb50005b7961de', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10622, '隋宫', NULL, 110, 603, 3, 1, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/162817/9499234.htm', '', '紫泉宫殿锁烟霞，欲取芜城作帝家。
玉玺不缘归日角，锦帆应是到天涯。
于今腐草无萤火，终古垂杨有暮鸦。
地下若逢陈后主，岂宜重问后庭花。', '此诗是唐代诗人李商隐创作的一首咏史吊古诗，内容虽是歌咏隋宫，其实乃讽刺隋炀帝杨广的荒淫亡国。此诗写隋炀帝为了寻欢作乐，无休止地出外巡游，奢侈昏庸，开凿运河，建造行宫，劳民伤财，终于为自己制造了亡国的条件，成了和陈后主一样的亡国之君。讽古是为喻今，诗人把隋炀帝当作历史上以荒淫奢华著称的暴君的典型，来告诫晚唐的那些荒淫腐朽、醉生梦死的统治者。全诗采用比兴手法，写得灵活含蓄，色彩鲜明，音节铿锵。', '隋宫：指隋炀帝杨广在江都（今江苏扬州市）所建的行宫。
紫泉：即紫渊，长安河名，因唐高祖名李渊，为避讳而改。司马相如《上林赋》描写皇帝的上林苑“丹水亘其南，紫渊径其北”。此用紫泉宫殿代指隋朝京都长安的宫殿。锁烟霞：空有烟云缭绕。
“欲取”句：《隋书·炀帝纪》：“大业元年三月，发河南诸郡男女百余万开通济渠，······八月，上御龙舟幸江都。”芜城，即广陵（今扬州）。帝家，帝都。
玉玺（xǐ）：皇帝的玉印。日角：额角突出，古人以为此乃帝王之相。此处指唐高祖李渊。《旧唐书·唐俭传》：“高祖乃召入，密访时事，俭曰：‘明公日角龙庭，李氏又在图牒，天下属望’。”《后汉书·光武纪》注引郑玄《尚书中候注》：“日角，谓庭中骨起状如日。”朱建平《相书》：“额有龙犀入发，左角日，右角月，王天下。”刘孝标《辨命论》：“龙犀日角，帝王之表。”
锦帆：隋炀帝所乘的龙舟，其帆用华丽的宫锦制成。《开河记》：“帝自洛阳迁驾大梁，诏江淮诸州造大船五百只，······龙舟既成，泛江沿淮而下，······时舳舻相继，连接千里，自大梁至淮口，联绵不绝。锦帆过处，香闻百里。”
腐草无萤火：《礼记·月令》：“腐草为萤。”古人以为萤火虫是腐草变化出来的。《隋书·炀帝纪》：“大业十二年，上于景华宫征求萤火，得数斛，夜出游山放之，光遍岩谷。”这句采取夸张的手法，说炀帝已把萤火虫搜光了。
垂杨：隋炀帝自板诸引河达于淮，河畔筑御道，树以柳，名曰隋堤，一千三百里。《开河记》：“诏民间有柳一株赏一缣，百姓争献之。又令亲种，帝自种一株，群臣次第种栽毕，帝御笔写赐垂杨柳姓杨，曰杨柳也。”
“地下”二句：陈后主：南朝陈末代皇帝陈叔宝，荒淫亡国之君。后庭花：即《玉树后庭花》，陈后主所创，歌词绮艳。《隋遗录》载隋炀帝在江都，“昏腼滋深，往往为妖祟所惑。尝游吴公宅鸡台，恍惚间与陈后主相遇。后主舞女数十许，中一人迥美，帝屡目之，后主云：‘即丽华也。’因请丽华舞《玉树后庭花》。丽华徐起，终一曲。”', '韵译
长安的殿阁内弥漫着一片烟霞，杨广还想把芜城作为帝王之家。
如果不是李渊得到传国的玉玺，那么他的龙舟还会游遍到天涯。
如今隋朝的宫苑中已不见萤虫，只有低垂的杨柳和归巢的乌鸦。
如果杨广在地下和陈后主相遇，有心欣赏淫逸辱国的后庭花吗？
散译
长安的殿阁千门闲闭，空自笼罩着一片烟霞，又想在繁丽的江都，把宫苑修建得更加豪华。若不是皇帝的玉印归到了李家；隋炀帝的锦帆或许会游遍天涯。当年放萤的场所只剩下腐草，萤火早就断绝了根芽；多少年来隋堤寂寞凄冷，两边的垂杨栖息着归巢乌鸦。他若是在地下与陈后主重逢，难道能再去赏一曲《后庭花》？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dc0f8fda556505566e", "shortContent": "题目《隋宫》，指的是杨广在江都营建的行宫江都宫、显福宫和临江宫等。\n首联点题。诗人把长安的宫殿和“烟霞”联系起来，意在表明它巍峨壮丽，高耸入云。王维的“云里帝城双凤阙”（《奉和圣制从蓬莱向兴庆阁道中留春雨中春望之作应制》），白居易的“宫阙入烟云”（《登乐游园望》），都可作为例证。用“紫泉”（长安的一条水。“泉”，本作“渊”，因避唐高祖李渊讳而改）代替长安，也是为了选取有色彩的字面与“烟霞”相映衬，...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d8b73206168b2e01eb1", "shortContent": "首联谓长安宫殿深闭，为烟锁云封，闲置不用。隋炀帝另图以江都为帝都。次联谓若不是隋朝政权为唐朝取代，隋炀帝的龙舟恐怕将要游遍天涯海角了。三联谓场帝当年搜尽流萤，如今腐草也不生萤火了；长久以来，只见隋堤上的垂柳与暮鸦相伴，显出一派凄凉景象。末联谓炀帝在阴间若再遇上陈后主，难道还要观赏张丽华的《玉树后庭花》舞蹈吗？本篇是义山咏史诗中的绝作。讽刺辛辣，寓意深广，跌宕有致，结句奇警。", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f09356", "shortContent": "此诗约作于唐宣宗大中十一年（857），当时李商隐因柳仲郢推荐，任盐铁推官，游江东。隋宫，隋炀帝杨广在江都（今江苏扬州）所建的行宫。炀帝在位十四年，开凿了两千余里的运河，三次巡游江都，沿河广建行宫，耗尽民脂民膏，最后因兵变死于江都行宫。李商隐从国家的兴亡着眼，写了这首讽刺前朝以警当世的咏史诗。\n\n首联“紫泉宫殿锁烟霞，欲取芜城作帝家”点题。紫泉，即紫渊，长安河名，因避讳唐高祖李渊名而改，代指隋都长安...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4dc26cbf3417f09396", "shortContent": "诗人南游广陵，面对隋宫遗址的丘墟，联想到当年隋炀帝纵情游玩、奢靡无度，终至亡身灭国的历史事实，以此为题材创作了一系列的诗歌，这是其中之一。\n\n“乘兴南游”，说明隋炀帝南游江都并非出于关心民瘼的治国目的，只是一时兴起，想去尽情地游玩一番罢了。皇帝出行，按照规定，要实行戒严，以确保安全无虞，但隋炀帝自视甚高，以为天下太平，居然拒绝了戒严。而当时隋朝内忧外患，各地起义力量正在积聚。由此可见，隋炀帝耽迷享...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64631d0645e4710056bd2f35", "shortContent": "题目《隋宫》，指的是杨广在江都营建的行宫江都宫、显福宫和临江宫等。\n\n首联点题。诗人把长安的宫殿和“烟霞”联系起来，意在表明它巍峨壮丽，高耸入云。王维的“云里帝城双凤阙”（《奉和圣制从蓬莱向兴庆阁道中留春雨中春望之作应制》），白居易的“宫阙入烟云”（《登乐游园望》），都可作为例证。用“紫泉”（长安的一条水。“泉”，本作“渊”，因避唐高祖李渊讳而改）代替长安，也是为了选取有色彩的字面与“烟霞”相映衬...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "6463612030675327e183ba28", "shortContent": "这首七绝，通过精心的选材和独创性的构思，讽咏隋炀帝杨广奢侈嬉游之事。\n\n杨广当政十四年，把绝大部分时间用于佚游享乐。诗人举南游江都以概其余，已经显示了选材上的艺术匠心；又从三次南游江都中，抓住几个典型事例，略作点化，就收到了借一斑以窥全豹的艺术效果。\n\n开头两句先借南游刻画人物。第一句单刀直入，点明“南游”。而以“乘兴”作状语，展现了杨广贪图享乐、不惜民力、骄横任性、无所顾忌、为所欲为的性格特征。...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '范晞文《对床夜语》：前辈云：诗家病使事太多，盖皆取其与题合者类之，如此乃是编事，虽工何益？……若《隋宫》诗云：“玉玺不缘归日角，锦帆应是到天涯。”又《筹笔驿》云：“管乐有才真不忝，关张无命欲何如！”则融化斡旋，如自己出，精粗顿异也。
方回《瀛奎律髓》：“日角”、“天涯”巧。
吴师道《吴礼部诗话》：“日角”、“锦帆”、“萤火”、“垂杨”是实事，却以他字面交蹉对之，融化自称，亦其用意深处，真佳句也。
顾麟《批点唐音》：此篇句句用故实，风格何在？况又俗，且用小说语，非古作者法律。初联、结语亦俗，大抵晚唐起结少有好语。
周珽《唐诗选脉会通评林》：周弼以此为四虚体。周秉伦曰：通篇以虚意挑剔讥意。即结语，不曰难面阴灵于文帝，而曰岂宜问淫曲于后主，见殷鉴不远，致覆成业于前车。可笑、可哭之甚，殊有深思。评者病其风格不雅，则可；如谓其用小说语，彼稗官野史，何者非古今人文赋中料耶！
金圣叹《贯华堂选批唐才子诗》：“于今”妙！只二字，便是冷水兜头蓦浇。“终古”妙！只二字，便是傀儡通身线断，直更不须“腐草”、“垂杨”之十字也）。
陆次云《五朝诗善鸣集》：五六是他人结语，用在诗腹，别以新奇之意作结，机杼另出，义山当日所以独步于开成、会昌之间。
冯班、冯舒《二冯先生评点才调集》：腹联慷慨，专以巧句为义山，非知义山者也。
何焯《义门读书记》：无句不佳，三四尤得杜家骨髓。前半展拓得开，后半发挥得足，真大手笔。后半讽刺更觉有力。
贺裳《载酒园诗话又编》：义山《隋宫》诗：“玉玺不缘归日角，锦帆应是到天涯。”飞卿《春江花月夜》曰：“十幅锦帆风力满，连天展尽金芙容。”虽竭力描写豪奢，不及李语更能状其无涯之欲。
胡以梅《唐诗贯珠》：按诗情乃凭吊凄凉之事，而用事取物却一片华润。本来西昆出笔不宜淡薄，加以炀帝始终以风流淫荡灭亡，非关时危运尽之故，故作者犹带脂粉，即以诮之耳，最为称题。
朱曾武《唐诗绎》：此诗全以议论驱驾事实，而复出以嵌空玲珑之笔，运以纵横排宕之气，无一笔呆写，无一句实砌，斯为咏史怀史之极。
黄子云《野鸿诗的》：《隋宫》诗：“玉玺不缘归日角，锦帆应是到天涯。”“日角”非太宗然也，前代之君亦有之；况二字究未有稳贴，明知先有下句，不得已借以强对。然只此一联，语虽工，而作意何在？
沈德潜《唐诗别裁》：言天命若不归唐，游幸岂止江都而已！用笔灵活，后人只铺叙故实，所以板滞也。
黄叔灿《唐诗笺注》：五十六字中以议论运实事，翻空排宕，与《南朝》诗同一笔意。
张文荪《唐贤清雅集》：参用活法夹写，便动荡有情，古今凭吊绝作。
李锳《诗法易简录》：言外有无限感叹，无限警醒。
方南堂《辍锻录》：李商隐之“于今腐草无萤火，终古垂杨有暮鸦”，不过写景句耳，而生前侈纵，死后荒凉，一一托出，又复光彩动人，非惊人语乎？
徐元梦《历代诗法》：风华典雅，真可谓百宝流苏，千丝铁网。
冒春荣《葚原诗说》：其造语幽深，律法精密，有出常情之外者。
李庆甲《瀛奎律髓汇评》：钱湘灵云：此首以工巧为能，非玉溪妙处。查慎行：前四句中转折如意。三四有议论，但“锦帆”事实，“玉玺”宇凑。纪昀：中四句步步逆挽，句句跌脱。结句佻甚，盛唐人决不如此。
纪昀《玉溪生诗说》：纯用衬贴活变之笔，一气流走，无复排偶之迹。首二句一起一落，上句顿，下句转，紧呼三四句。“不缘”、“应是”四字，跌宕生动之极。无限逸游，如何铺叙？三四只作推算语，便连未有之事，一并托出，不但包括十三年中事也，此非常敏妙之笔。结句是晚唐别于盛唐处。
方东树《昭昧詹言》：先君云：“寓议论于叙事，无使事之迹，无论断之迹，妙极妙极。”又曰：“纯以虚字作用，五六句兴在象外，活极妙极，可谓杰作。”
张采田《李义山诗辨正》：结以冷剌作收，含蓄不尽，佥觉味美于回，律诗寓比兴之意，玉溪惯法也。
俞陛云《诗境浅说续编》：凡作咏古诗，专咏一事，通篇固宜用本事，而须活泼出之；结句更须有意，乃为佳构。玉溪之《马嵬》、《隋宫》二诗，皆运古入化，最宜取法。首句总写隋宫之景。次句言芜城之地何足控制宇内，而欲取作“帝家”，言外若讥其无识也。三四言天心所眷，若不归日角龙颜之唐王，则锦帆游荡，当不知其所止。五六言于今腐草江山，更谁取流萤十斛；怅望长堤，唯有流水栖鸦，带垂杨萧瑟耳。萤火垂杨，即用隋宫往事，而以感叹出之。句法复摇曳多姿。末句言亡国之悲，陈、隋一例。与后主九原相见，当同伤宗稷之沦亡，玉树荒嬉，岂宜重问耶！', 'center', 1417524952, '57b96ea97db2a200542a9186', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10623, '筹笔驿', NULL, 26, 603, 1, 1, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/162784/5785737.htm', '', '猿鸟犹疑畏简书，风云常为护储胥。
徒令上将挥神笔，终见降王走传车。
管乐有才原不忝，关张无命欲何如。
他年锦里经祠庙，梁父吟成恨有余。', '这是一首凭吊诗，大中十年（856）冬，诗人罢去梓州幕府，随柳仲郢还京，途经筹笔驿时所作。诗中盛赞诸葛亮的政治军事才能，为他未能统一中国而惋惜。同时对懦弱昏庸、终于投降魏国的后主刘禅加以贬斥。
全诗运用拟人化的手法，以精炼的笔墨描绘诸葛亮长于治军，军纪严明，余威犹存，用以展示出他作为一个历史上著名军事家的形象特征。接着以刘禅和关张这两类不同典型人物与其构成鲜明对比。由于刘禅的昏庸，使诸葛亮一生的谋划付之东流。关羽违反了诸葛亮抗魏的策略，而使蜀汉兵挫地削，招致自己和张飞的亡身之祸。通过对比，更显诸葛亮的政治才能之卓越。', '筹笔驿：旧址在今四川省广元北。《方舆胜览》：“筹笔驿在绵州绵谷县北九十九里，蜀诸葛武侯出师，尝驻军筹划于此。”
“猿鸟”句：诸葛亮治军以严明称，这里意谓至今连鱼鸟还在惊畏他的简书。猿：一作“鱼”。疑：惊。简书：指军令。古人将文字写在竹简上。
储胥：指军用的篱栅。
上将：犹主帅，指诸葛亮。
终：一作“真”。降王：指后主刘禅。走传车：魏元帝景元四年（263年），邓艾伐蜀，后主出降，全家东迁洛阳，出降时也经过筹笔驿。传车：古代驿站的专用车辆。后主是皇帝，这时却坐的是传车，也隐含讽喻意。
管：管仲。春秋时齐相，曾佐齐桓公成就霸业。乐：乐毅。战国时人，燕国名将，曾大败强齐。
原不忝：真不愧。诸葛亮隐居南阳时，每自比管仲、乐毅。
欲：一作“复”。
他年：作往年解。锦里：在成都城南，有武侯祠。
梁父吟：两句意谓，往年曾谒锦里的武侯祠，想起他隐居时吟咏《梁父吟》的抱负，不曾得到舒展，实在令人遗憾。', '鱼鸟犹疑是惊畏丞相的严明军令，风云常常护着他军垒的藩篱栏栅。
诸葛亮徒然在这里挥笔运筹划算，后主刘禅最终却乘坐邮车去投降。
孔明真不愧有管仲和乐毅的才干。关公张飞已死他又怎能力挽狂澜？
往年我经过锦城时进谒了武侯祠，曾经吟诵了梁父吟为他深表遗憾！', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dc34a8757d5a0e1e3b", "shortContent": "筹笔驿在今四川广元县北，相传三国时蜀汉诸葛亮出兵伐魏，曾驻此筹划军事。大中九年（855）李商隐罢梓州幕随柳仲郢回长安，途经此驿，写下这首咏怀古迹的诗篇。此诗同多数凭吊诸葛亮的作品一样，颂其威名，钦其才智；同时借以寄托遗恨，抒发感慨。不过本篇在表现手法上有其独到之处，大要有三：议论以抑扬交替之法，衬托以宾主拱让之法，用事以虚实结合之法。\n诗写诸葛亮之威、之智、之才、之功，不是一般的赞颂，而是集中写个...", "authors": ["林东海"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d8ae6f69b71e93f5fc9", "shortContent": "大中十年春，义山随柳仲郢还朝，途经广元筹笔驿，因作此篇。首联谓筹笔驿一带山势险峻，猿鸟犹畏诸葛亮当年的军令之森严，此地风云屯聚，仿佛长久护卫当年的军防屏障。颔联谓诸葛亮谋划如神，却无力挽回蜀汉的命运，终见后主出降，蜀国败亡。颈联谓诸葛亮真不愧是管仲、乐毅一样的政治家、军事家；可是关、张早死，诸葛亮又有什么办法？末联谓前时经过成都武侯祠，悲歌《梁甫吟》，就已经叹恨不尽了。本诗主旨是咏史，情景交融，属...", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f09358", "shortContent": "这是作者宣宗大中九年（855）冬，随柳仲郢还朝途经筹笔驿时咏怀古迹之作。\n\n诸葛亮是古往今来忠臣良将的典范，作者路过当年他行军布阵之处，见猿鸟都远远地离开，仿佛是惊畏诸葛亮森严的军令，数百年之后仍不敢相扰。这是因诸葛亮治军严明，故作者有此联想。而猿鸟远离，亦可见诸葛亮凛然不可侵犯之气度。再远望筹笔驿上，风云屯聚，好像长久地护卫着当年的藩篱壁垒。这两句极写诸葛亮之能。\n\n接着又以“神笔”喻诸葛亮之料...", "authors": ["张力"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707a73206168b2e02227", "shortContent": "\n诸葛亮是古往今来忠臣良将的典范，作者路过当年他行军布阵之处，见猿鸟都远远地离开，仿佛是惊畏诸葛亮森严的军令，数百年之后仍不敢相扰。这是因诸葛亮治军之严，故作者有此联想。而猿鸟远离，亦可见诸葛亮凛然不可侵犯之气度。再远望筹笔驿上，风云屯聚，好像长久地护卫着当年的藩篱壁垒。这两句极写诸葛亮之能。接着又以“神笔”，喻诸葛亮之料敌如神。可徒然有这样优秀的人才，仍然无法改变蜀国灭亡的命运，即不免见到降王刘...", "authors": ["张力"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64631db45fc8182fe997452b", "shortContent": "筹笔驿在今四川广元市北，相传三国时蜀汉诸葛亮出兵伐魏，曾驻此筹划军事。大中九年（855）李商隐罢梓州幕随柳仲郢回长安，途经此驿，写下这首咏怀古迹的诗篇。此诗同多数凭吊诸葛亮的作品一样，颂其威名，钦其才智；同时借以寄托遗恨，抒发感慨。不过本篇在表现手法上有其独到之处，大要有三：议论以抑扬交替之法，衬托以宾主拱让之法，用事以虚实结合之法。\n\n诗写诸葛亮之威、之智、之才、之功，不是一般的赞颂，而是集中写...", "authors": ["林东海"], "pressName": "上海辞书出版社"}]', '《潜溪诗眼》：“管乐有才真不忝，关张无命欲何如”，属对亲切，又自有议论，他人亦不能及也。
《瀛奎律髓》：起句十四字，壮哉！五六痛恨至矣。
《批点唐音》：此篇八句匀停，略成晚唐诗一体。
《唐诗选脉会通评林》：周弼列为四虚体。苏轼曰：诵首二句，使人凛然复见孔明风烈。周珽曰：此追忆武侯而深致感伤之意。谓其法度忠诚，本足感天人，垂后世，然筹划虽工，汉祚难移，盖才高而命不在也。他年经武侯祠庙，而恨功之徒劳，与武侯赋《梁父吟》所以恨三良者更有馀也。联属清切又有意，他人不能及。
《唐诗快》：少陵之叹武侯“诸葛大名”一首，正可与此诗相表里。
《唐诗贯珠》：起得凌空突兀……猿鸟无知，用“疑”；风云神物，直用“长为”矣，有分寸。
《初白庵诗评》：“管乐”、“关张”皆实事，胜前者（按指《隋宫》）“玉玺”、“锦帆”。
《山满楼笺注唐诗七言律》：鱼鸟风云，写得诸葛武侯生气奕奕。“徒令”一转，不禁使人嗒焉欲丧……此诗一二擒题。三四感事。五承一二、六承三四，尚论也。七八总收，以致其惓惓之意焉。
《唐诗成法》：一二壮丽，意亦超脱。以下四句是武侯论，非筹笔驿诗。七八犹有馀意。
《唐体馀编》：为驿作衬，兼入凭吊意。首尾相映有笔力。
《唐诗别裁》：瓣香老杜，故能神完气足，边幅不窘。
《网师园唐诗笺》：起势突兀，通首一气呵成。
《唐贤小三昧集续集》：千锤百炼，乃有此起（首二句下）。五六跌荡有神。
《瀛奎律髓汇评》：冯舒：荆州失，益德死，蜀事终矣。第六句是巨眼。冯班：好议论。何焯：议论固高，尤当观其抑扬顿挫处，使人一唱三叹，转有馀味。纪昀：起二句斗然抬起，三四句斗然抹倒，然后以五句解首联，六句解次联，此真杀活在手之本领，笔笔有龙跳虎卧之势。许印芳：沉郁顿挫，意境宽然有馀，义山学杜，此真得其骨髓矣。笔法之妙，纪批尽之。
《历代诗评注》：通用故事，操纵自如，而意亦曲折尽达，此西昆体之最上乘者。
《昭昧詹言》：义山此等诗，语意浩然，作用神魄，真不愧杜公。前人推为一大家，岂虚也哉！
《唐诗近体》：武侯威灵，十四字写得满足（首二句下）。接笔一转，几将气焰写尽。五六两层折笔，末仍收归本事，非有神力者不能。
宋弼则以此诗与杜甫的《蜀相》比美：起二句本意已尽，下面无可措手矣；三四句作开笔，五六收转，两意相承，字字顿挫；七八振开作结。与少陵“丞相祠堂”作，不可妄置优劣也。
范仲温《诗眼》云：“惟义山‘鱼鸟’云云，‘简书’盖军中法令约束，言号令严明，虽千百年之后，‘鱼鸟’犹畏之；‘储胥’盖军中藩篱，言忠义贯于神明，‘风云’犹为护其壁垒也。', 'center', 1417525091, '57bd9b9e8ac24700631baf1a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10624, '无题', NULL, 93, 603, 2, 1, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3691881.htm', '', '凤尾香罗薄几重，碧文圆顶夜深缝。
扇裁月魄羞难掩，车走雷声语未通。
曾是寂寥金烬暗，断无消息石榴红。
斑骓只系垂杨岸，何处西南任好风。', '这是抒写一女子爱情失意的幽怨和长相思的苦闷心情。诗的首联写女主人公深夜缝制罗帐，表现她对往事的追忆和对会合的深情期待。颔联回忆最后一次邂逅的情状，表达她追思往事时，那种惋惜、怅惘而又深情地回味的复杂心情。颈联写别后的相思寂廖，春光已尽，石榴花开，所思之人断无消息。表达了流光易逝，青春虚度的怅惘和感伤之情。尾联写日夜思念的人，或许相隔非远，只是咫尺天涯，无缘会合罢了。
诗活用了曹植的《七哀诗》中“愿为西南风，长逝入君怀”的名句，表达会合难期之苦。诗中所流露的感情真挚而深厚。看来女主人公似乎是单相思。虽然相思无望，然而追求却十分执着。正是这种纯情，这种痴情，赋予诗歌强烈的感染力。', '任：一作“待”。', '', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92e103048e64fbd91699", "shortContent": "李商隐的七律“无题”，艺术上最成熟，最能代表其无题诗的独特艺术风貌。这两首七律“无题”，内容都是抒写青年女子爱情失意的幽怨，相思无望的苦闷，又都采取女主人公深夜追思往事的方式，因此，女主人公的心理独白就构成了诗的主体。她的身世遭遇和爱情生活中某些具体情事就是通过追思回忆或隐或显地表现出来的。\n第一首起联写女主人公深夜缝制罗帐。“凤尾香罗”，是一种织有凤纹的薄罗；“碧文圆顶”，指有青碧花纹的圆顶罗帐...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d8277683d1933014fb0", "shortContent": "【其一】\n两首都是爱情诗。第一首不说自己思念所恋伊人，却想象闺中人渴望与自己相见，于是一个渴慕爱情，期待好合的女性形象，悄悄地浮现在我们面前。首联写闺中女子夜间赶制罗帐等待情人的到来。“凤尾香罗”已点明女子的贵族身份。颔联写女子第一次与男子晤面之前的羞怯心态，本以为很有把握相会，所以情不自禁地以团扇遮面，哪知男子有公务在身，驱车匆匆而过（或是“走马兰台”），竟未能与女方接语，令她大失所望。颈联写闺...", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f0935b", "shortContent": "在李商隐的《无题》诗中，此二首均描写幽闺女子相思寂寥之情，虽流传不广，但其对幽闺女子复杂心理的描摹，寄托之深远，“其造意幽深，律切精密，有出常情之外者”（明高棅《唐诗品汇》）。\n\n第一首叙幽闺女子的独处经历与相思记忆。首联写女主人公深夜缝制罗帐。“凤尾香罗”与“碧文圆顶”，一是喻示着闺中女子身份高贵，生活非同常人，二是象征着男女相爱相合。为何她要深夜缝制罗帐呢？诗中没有交代，但我们从女主人公默默地...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "646389a07da2f75ac7e37bfc", "shortContent": "李商隐的七律“无题”，艺术上最成熟，最能代表其无题诗的独特艺术风貌。这两首七律“无题”，内容都是抒写青年女子爱情失意的幽怨，相思无望的苦闷，又都采取女主人公深夜追思往事的方式，因此，女主人公的心理独白就构成了诗的主体。她的身世遭遇和爱情生活中某些具体情事就是通过追思回忆或隐或显地表现出来的。\n\n第一首起联写女主人公深夜缝制罗帐。“凤尾香罗”，是一种织有凤纹的薄罗；“碧文圆顶”，指有青碧花纹的圆顶罗...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '', 'center', 1417525232, '57b9259c5bbb50005b795dd3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10625, '无题', NULL, 336, 603, 2, 1, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/1754884/14348458.htm', '', '重帷深下莫愁堂，卧后清宵细细长。
神女生涯原是梦，小姑居处本无郎。
风波不信菱枝弱，月露谁教桂叶香。
直道相思了无益，未妨惆怅是清狂。', '此诗抒写女主人公自伤不遇的身世。开头先写环境氛围的幽静，衬出长夜的孤寂；接着以楚王梦遇巫山神女和乐府《青溪小姑曲》的“小姑所居，独处无郎”的典故，抒写自己曾经有过幻想和追求，但到头来只好梦一场，依然独居；再写风波凶恶，菱枝柔弱，无力反抗，桂叶自有清香，却无月露润香；最后写即使如此，还要执着追求。意境深远开阔，措辞婉转沉痛，感情细腻坚贞，是一首很好的爱情诗。', '莫愁：唐石城女子，善歌谣。
神女：宋玉《高唐赋序》称楚王游高唐梦见神女，神女称“旦为朝云，暮为行雨。”，传说为天帝小女。
小姑：乐府《青溪小姑曲》：“开门白水，侧近桥梁。小姑所居，独处无郎。”
清狂：《汉书·昌邑王传》：“清狂不惠。”指不狂似狂。', '重重帷幕深垂，我孤居莫愁堂；独卧不眠，更觉静夜漫漫长长。楚王艳遇巫山神女，原是梦幻；青溪小姑住所，本就独处无郎。我是柔弱菱枝，偏遭风波摧残；我是铃芳桂叶，却无月露芳香。虽然深知沉溺相思，无益健康；我却痴情到底，落个终身清狂。', NULL, '《唐诗评选》：艳诗别调。
《唐诗快》：义山最工为情语。所谓“情之所钟，正在我辈”，非义山其谁归？
《唐诗贯珠》：此以莫愁比所思之人也。
《李义山诗集辑评》：何焯曰：义山无题数诗，不过自伤不逢，无聊怨题，此篇乃直露本意。
《李义山诗解》：此篇言相思无益，不若且置，而自适其啸志歌怀之得也。
《李义山诗集笺注》：姚培谦曰：此义山自言其作诗之旨也。重帏自锁，清宵自长，所谓神女小姑，即《楚辞》“望美人兮南浦”之意，非果有其人也。
《玉溪生诗意》：“梦”字承秋宵，“居处”承奠愁堂，“风波”承白水居处，“月露”承神女梦，“相思”总结上六句，“惆怅”、“清狂”中说七句也。
《龙性堂诗话初集》：“直道相思了无益，未妨惆怅是清狂”、“平明钟后更何事，笑倚墙边梅树花”、“若是晓珠明又定，一生长对水晶盘”，觉欲界缠人，过后嚼蜡，即色即空之义也。
《玉溪生诗集笺注》：此种真沉沦悲愤、一字一泪之篇，乃不解者引入歧途，粗解者未披重雾，可慨久矣
《唐诗三百首》：明知无益，时惆怅不已，直清狂本色耳。
《李义山诗辨正》：通篇反复自伤，不作一决绝语，真一字一泪之诗也。
《李义山诗偶评》：义山诸无题，以此二首为最得风人之旨。察其饷，纯托之于守礼而不佻之处子，与杜陵所谓空谷佳人，殆均不愧幽贞。时解者多以为有思而不得之词，失之甚矣。', 'center', 1417525319, '57b93bd8a633bd00665f4402', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10626, '利州南渡', NULL, 81, 394, 1, 1, '温庭筠', NULL, 10069, '57b93da179bc44005ba0a318', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383679.htm', '', '澹然空水对斜晖，曲岛苍茫接翠微。
波上马嘶看棹去，柳边人歇待船归。
数丛沙草群鸥散，万顷江田一鹭飞。
谁解乘舟寻范蠡，五湖烟水独忘机。', '诗写日暮渡口的景色，抒发欲步范蠡後尘忘却俗念，没有心机，功成隐退的归隐之情。诗的起句写渡口和时间，接着写江岸和江中景色，进而即景生情，点出题意，层次清晰，色彩明朗。', '利州：唐代属山南西道，治所在今四川广元，嘉陵江流经其西北面。南渡：指渡嘉陵江。
澹（dàn）然：水波闪动的样子。
对：一作「带」。
翠微：指青翠的山气。
「波上马嘶看棹（zhào）去」句：指未渡的人，眼看着马鸣舟中，随波而去。波上：一作「坡上」。棹，船桨，代指船。
「数丛沙草群鸥散」句：指船过草丛，惊散群鸥。
范蠡（lǐ）：字少伯，春秋时楚国人，为越大夫，从越王勾践二十馀年，助勾践灭吴国後，辞官乘舟而去，泛于五湖，莫知所终。
五湖烟水：据《吴越春秋》称，范蠡功成身退，乘扁舟出入三江五湖，没人知道他最终到哪里去了。五湖，指太湖和它附近的几个湖，这里泛指江湖。
忘机：旧谓鸥鹭忘机，这里有双关意，指心愿淡泊，与人无争。', '夕阳正斜照在空阔的水面上，曲折的小岛连接翠绿的群山。
江面上传来马的嘶鸣看船归，柳荫下的人们等待着船靠岸。
广阔沙草从中群鸥四处飞散，万顷江田上空孤鹭展翅飞翔。
谁能像范蠡一样乘着小木船，在辽阔的江湖上面自由飘荡。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f0935c", "shortContent": "此诗写利州（今四川广元）南渡之人事，写嘉陵江上之晚色，看似处处写景，实则寓情于景，情景交融，透露出诗人倦怠红尘，欲效仿范蠡归隐江湖之意。全诗清新自然，境界旷远，但落魄飘零之感深蕴其中。\n\n首联写嘉陵江两畔的美丽景色。诗人从利州南渡嘉陵江，来到江畔，他不免被江畔的美景所陶醉。开阔澄澈的江面上，波光粼粼，夕阳残照在江面泛起万点荧光。蜿蜒曲折的岛岸与翠绿葱茏的远山交相辉映，呈现出一片苍茫宏阔的气象。此二...", "authors": ["乐云"], "pressName": "崇文书局"}]', '', 'center', 1417525396, '57b98defd342d30063995a87', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10627, '苏武庙', NULL, 64, 394, 2, 1, '温庭筠', NULL, 10069, '57b93da179bc44005ba0a318', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383681.htm', '', '苏武魂销汉使前，古祠高树两茫然。
云边雁断胡天月，陇上羊归塞草烟。
回日楼台非甲帐，去时冠剑是丁年。
茂陵不见封侯印，空向秋波哭逝川。', '这一首凭吊古人的诗。诗颂扬了富有民族气节、忠贞不屈、心向故国的苏武。晚唐国势衰颓，民族矛盾尖锐；表彰民族气节，歌颂忠贞不屈，心向祖国的时代的需要。温庭筠这首诗正是塑造了一位坚持民族气节的英雄形象。颈联的对仗颇为工巧，且用「逆挽法」，先说「回日」再说「去时」，灵活而不呆板，生动而不拘泥。', '苏武：汉武帝时出使匈奴被扣多年，坚贞不屈，汉昭帝时始被迎归。
使：一作「史」。
古祠：指苏武庙。
茫然：茫然不解。
雁断：指苏武被羁留匈奴后与汉廷音讯隔绝。
断：一作「落」。
胡：指匈奴。
陇关：这里以陇关之外喻匈奴地。陇，通「垄」。
甲帐：据《汉武故事》记载：武帝「以琉璃、珠玉、明月、夜光错杂天下珍宝为甲帐，其次为乙帐。甲以居神，乙以自居。」「非甲帐」意指汉武帝已死。
冠剑：指出使时的装束。
剑：一作「盖」。
丁年：壮年。唐朝规定二十一至五十九岁为丁。
茂陵：汉武帝陵。苏武归汉时武帝已死，此借指汉武帝。封侯：封拜侯爵。
逝川：喻逝去的时间。语出《论语·子罕》：「子在川上，曰：逝者如斯夫。」这里指往事。', '苏武初遇汉使，悲喜交集感慨万端；而今古庙高树，肃穆庄严久远渺然。
羁留北海音书断绝，头顶胡天明月；荒陇牧羊回来，茫茫草原已升暮烟。
回朝进谒楼台依旧，甲帐却无踪影；奉命出使加冠佩剑，正是潇洒壮年。
封侯受爵缅怀茂陵，君臣已不相见；空对秋水哭吊先皇，哀叹时光不还。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92da5e272d4b2254353a", "shortContent": "苏武是历史上著名的坚持民族气节的英雄人物。汉武帝天汉元年（前100）他出使匈奴，被扣留。匈奴多次逼降，他坚贞不屈。后被流放到北海牧羊，直至昭帝始元六年（前81），才返回汉朝，前后长达十九年。这首诗就是作者瞻仰苏武庙后追思凭吊之作。\n首联两句分点“苏武”与“庙”。汉昭帝时，匈奴与汉和亲。汉使到匈奴后，得知苏武尚在，乃诈称汉朝皇帝射雁上林苑，得苏武系在雁足上的帛书，知武在某泽中，匈奴方才承认，并遣武回...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f0935d", "shortContent": "这是作者瞻仰苏武庙后的凭吊咏怀之作。苏武以汉臣出使匈奴，被扣留异族长达十九年，始终不接受匈奴的逼降，“仗汉节牧羊，卧起操持，节旄尽落”（《汉书•苏武传》），为后人所景仰。\n\n诗的开端设想苏武归朝前在异域见到汉使的情景。根据《汉书》的记载，汉昭帝即位后，“匈奴与汉和亲。汉求武等，匈奴诡言武死。后汉使复至匈奴。常惠请其守者与俱，得夜见汉使，具自陈道。教使者谓单于言：‘天子射上林中，得雁足有系帛书，言武...", "authors": ["王颖"], "pressName": "崇文书局"}]', '《风月堂诗话》：「回日楼台非甲帐，去时冠剑是丁年。」尝见前辈论诗云：用事属对如此者罕见。
《后村诗话》：温飞卿《苏武庙》云：「回日楼台非甲帐，去时冠剑是丁年。」「甲帐」是武帝事，「丁年」用李陵书「丁年奉使，皓首而归」之语，颇有思致。
《瀛奎律髓》：「甲帐」、「丁年」甚工，亦近义山体。
《初白庵诗评》：三四用子卿事，点缀景物，与他手不同。
《唐诗绎》：首点苏武，提「魂消汉使前」五字，最为篇主。
《唐七律选》：「丁年」亦是俊语，然使高手作此，则「回日」、「去时」不如是板煞矣（「回日楼台」二句下）。
《唐诗别裁》：五六与「此日六军同驻马」一联，俱属逆挽法，律诗得此，化板滞为跳脱矣。
《历代诗发》：子卿一生大节，八句中包括无遗。
《瀛奎律髓汇评》：冯班：自是飞卿。何义门：五六不但工致，正逼出落句，落句自伤。纪昀：五六生动，余亦无甚佳处。结少意致。
《兰丛诗话》：温之《苏武庙》结句：「空向秋波哭逝川」，「波」字误。既「川」复「波」，涉于侵复。且「波」专言「秋」，亦觉不稳，上有何来路乎？老杜云「赋诗新句稳」，名手有不稳耶？当是「风」字，用汉武帝《秋风辞》乃非泛设凑句，乃与通篇之用事实者称。
《精选五七言律耐吟集》：全以议论行之，何尝有意属对？近人学之，便如优孟衣冠矣。
《小清华园诗谈》：如此诸作，其凄侧既足以动人，其抑扬复足以惩劝，犹有诗人之遗意也。
《筱园诗话》：玉溪生「此日六军同驻马，当时七夕笑牵牛」，飞卿「回日楼台非甲帐，去时冠剑是丁年」此二联皆用逆挽句法，倍觉生动，故为名句。所谓逆挽者，倒扑本题，先入正位，叙现在事，写当下景，而后转溯从前，追述已往，以反衬相形，因不用平笔顺拖，而用逆笔倒挽，故名。且施于五六一联，此系律诗筋节关键处……二诗能于此一联提笔振起，逆而不顺，遂倍精采有力，通篇为之添色，是以传诵人口；亦非以「马」「牛」、「丁」「甲」见长，故求工对仗也。', 'center', 1417525483, '57b92278a633bd00665e6bbb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10628, '宫词', NULL, 45, 83, 1, 1, '薛逢', NULL, 10146, '57bbc8542e958a006940901b', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/33421/8302471.htm', '', '十二楼中尽晓妆，望仙楼上望君王。
锁衔金兽连环冷，水滴铜龙昼漏长。
云髻罢梳还对镜，罗衣欲换更添香。
遥窥正殿帘开处，袍袴宫人扫御床。', '这是一首宫怨诗，内容是代写宫妃的怨恨的。诗一落笔就写宫妃企望君王来幸，然而从早到午，百般打扮却不见皇帝到来，于是越发觉得度日如年。最后发觉宫人打扫御床，说明皇上准备降幸正宫，企望已经破灭，猛然觉得自己远不及那些洒扫的宫女接近皇上，心里益加怨恨。
全诗对人物的心理状态，刻画极其细腻、逼真。首联总写望幸之意以后，以下三联即把这种“望”的心情，融化在对周围环境的描画，对人物动作的状写，以及对人物间的外境的反衬之中，生动地反映了宫妃们的空虚苦闷。', '十二楼：《史记·封禅书》：“黄帝时为五城十二楼，以侯神人于执期，命曰迎年。”此指后宫楼台。晓妆：晨起梳妆打扮。
望仙楼：唐内苑有望仙楼。元稹《连昌宫词》：“上皇正在望仙楼，太真同凭栏杆立。”又会昌五年唐武宗于神策军建望仙楼。此用成词。
金兽：指镀金的兽形门环。
水滴铜龙：龙纹漏壶。漏壶为古时计时器，盛沙或水，有标尺刻度，沙水由细口漏出，刻度渐显以计时。
云髻（jì）：高耸的发髻。
罗衣：指轻软丝织品制成的衣服。
正殿：此指后宫正殿，在中央，是君王正寝。
袍袴（kù）宫人：穿袍着裤的宫人，为任事役的低级宫女。袴，同“裤”。御床：皇帝用的坐卧之具。', '韵译
清早十二楼宫女都在忙梳妆，在望仙楼上盼望临幸的君王。
宫门上的金兽含锁冷冷清清，听着水滴铜龙觉得白日太长。
梳完云髻还要对着镜子修饰，换上华贵的罗衣又添上芳香。
傍晚远远地窥望正殿帘开处，袍袴宫女正为君主清扫御床。
散译
十二楼的宫女，清晨都忙着刻意梳妆，她们在望仙楼上翘盼，等候临幸的君王。兽形的门环冰冷，整天紧紧地锁上，铜龙缓缓滴水，白昼异样地漫长。梳理好乌云般的发髻，又对着明镜再三端详，把罗衣重新更换，浓浓地熏得芳香。远远窥见正殿里掀开帘幕，穿着短袍绣袴的宫女在打扫御床。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92e35914587d02f4e964", "shortContent": "宫怨是唐诗中屡见的题材。薛逢的这首《宫词》，从望幸着笔，刻画了宫妃企望君王恩幸而不可得的怨恨心理，情致委婉，有其独特风格。\n诗的首联，即点明人物身份和全诗主旨：“十二楼中尽晓妆，望仙楼上望君王。”“十二楼”、“望仙楼”皆指宫妃的住处。《史记·封禅书》记，方士言“黄帝时为五城十二楼，以候神人于执期”；又，《旧唐书·武宗本纪》记，“会昌五年（845）作望仙楼于神策军”。诗中用“十二楼”、“望仙楼”代指...", "authors": ["李敬一"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f0935e", "shortContent": "此诗从宫人望幸着笔，细致描摹出宫中嫔妃们企望皇帝宠幸而不得的幽怨心理。其刻画之生动形象，其情思之委婉深致，在宫怨诗中别具一格。\n \n首联以大开大阖之笔渲染宫女清晨望幸的壮观景象，点明此诗之主旨——“望君王”。\n\n清晨晓露未散，十二楼的嫔妃们已打扮梳妆，她们齐齐登上望仙楼，翘首以盼君王的临幸。一“尽”字，表明嫔妃动作的统一，亦暗示后宫嫔妃之声势浩大。一“望”字，将嫔妃们盼望宠幸的焦虑心理呈现得淋漓尽...", "authors": ["乐云"], "pressName": "崇文书局"}]', '元·郝天挺《唐诗鼓吹注解》：近侍有人，御床方扫，我反不得如袍裤宫人一侍左右也。长门玉阶之怨，亦宁有穷乎？
清·钱朝鼒《唐诗鼓吹笺注》：只一起“望君王”三字，写尽士人抑郁无聊、痴痴想望神理。结句有含讽意。
清·何焯《唐诗鼓吹评注》：三四是叙可望而不可亲，五六则不敢怨而益自修饰也。
清·陆次云《五朝诗善鸣集》：谩立远视而望幸焉，情态毕出。
清·焦袁熹《此木轩唐七言律诗读本》：通首是比。虽是唐人陋态，亦庶几怨而不怒者矣。
清·胡以梅《唐诗贯珠》：通首直赋，虽无玲珑之致，亦取华润。
清·邹弢《精选评注五朝诗学津梁》：信手拈来，而深怨之情，寓乎其内。
清·宋宗元《唐诗笺注》：通首只写“望君王”三字，
清·梅成栋《精选七律耐吟集》：意经千锤，语经百炼。', 'center', 1417525635, '57b99cfe7db2a20054f7c64a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10629, '贫女', NULL, 118, 39, 2, 1, '秦韬玉', NULL, 10147, '57bb23f41532bc006577b32b', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383010.htm', '', '蓬门未识绮罗香，拟托良媒益自伤。
谁爱风流高格调，共怜时世俭梳妆。
敢将十指夸针巧，不把双眉斗画长。
苦恨年年压金线，为他人作嫁衣裳。', '此诗诉说贫女悲惨的处境和难言的苦衷。诗人把贫女放在社会环境的矛盾冲突中，通过独白揭示贫女内心深处的苦痛，着意刻画贫女持重清高的品行，对贫女给予深切同情，也寄寓着作者的不平和感慨。全诗没有典故，不用比拟，语言质朴，以广泛深刻的内涵，浓厚的生活哲理，使诗作蕴有重大的社会意义。其中最后“为他人作嫁衣裳”一句广为流传，是人所共称的佳句。', '蓬门：用蓬茅编扎的门，指穷人家。绮罗：华贵的丝织品或丝绸制品。这里指富贵妇女的华丽衣裳。
拟：打算。托良媒：拜托好的媒人。益：更加。
风流高格调：指格调高雅的妆扮。风流：指意态娴雅。高格调：很高的品格和情调。
怜：喜欢，欣赏。时世俭梳妆：当时妇女的一种妆扮。称“时世妆”，又称“俭妆”。时世：当世，当今。一说此处“俭”作“险”解，俭梳妆意为奇形怪状的打扮。
针：《全唐诗》作“偏”，注“一作纤”。
斗：比较，竞赛。
苦恨：非常懊恼。压金线：用金线绣花。“压”是刺绣的一种手法，这里作动词用，是刺绣的意思。', '贫家的女儿不识绮罗的芳香，想托个良媒说亲更感到悲伤。
谁能爱我高尚的品格和情调？却都喜欢时下正流行的俭妆。
敢夸十指灵巧针线做得精美，决不天天描眉与人争短比长。
深恨年年手里拿着金线刺绣，都是替富人家小姐做嫁衣裳。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ed5914587d02f4e99c", "shortContent": "这首诗，以语意双关、含蕴丰富而为人传诵。全篇都是一个未嫁贫女的独白，倾诉她抑郁惆怅的心情，而字里行间却流露出诗人怀才不遇、寄人篱下的感恨。\n“蓬门未识绮罗香，拟托良媒益自伤。”主人公的独白从姑娘们的家常——衣着谈起，说自己生在蓬门陋户，自幼粗衣布裳，从未有绫罗绸缎沾身。开口第一句，便令人感到这是一位纯洁朴实的女子。因为贫穷，虽然早已是待嫁之年，却总不见媒人前来问津。抛开女儿家的羞怯矜持，请人去作媒...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389af4797a92d5e4fd924", "shortContent": "这首诗，以语意双关、含蕴丰富而为人传诵。全篇都是一个未嫁贫女的独白，倾诉她抑郁惆怅的心情，而字里行间却流露出诗人怀才不遇、寄人篱下的感恨。\n\n“蓬门未识绮罗香，拟托良媒益自伤。”主人公的独白从姑娘们的家常——衣着谈起，说自己生在蓬门陋户，自幼粗衣布裳，从未有绫罗绸缎沾身。开口第一句，便令人感到这是一位纯洁朴实的女子。因为贫穷，虽然早已是待嫁之年，却总不见媒人前来问津。抛开女儿家的羞怯矜持，请人去作...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f0935f", "shortContent": "这是诗人自伤身世之作。全诗以贫女自喻，通过她的独白、自述，塑造出一个品性高洁但不为世人理解的贫女形象，从而寄托诗人怀才不遇之感和抑郁不平之气。\n\n诗歌一开篇便是贫女诉说自己的不幸遭遇。这位女子因为自小生长于穷苦人家，所以穿的都是粗布麻衣，从不曾有机会穿戴华丽的衣饰。虽然物质贫乏，她却没有因此而自卑难过，反倒是世人的嫌弃让她伤心不已。明明自己已到待嫁年龄，却始终无人上门提亲，如何不令她黯然神伤呢？有...", "authors": ["余春丽"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707e73206168b2e02240", "shortContent": "这是诗人自伤身世之作。全诗以贫女自喻，通过她的独白、自述，塑造出一个品性高洁但不为世人理解的贫女形象，从而寄托诗人自己的怀才不遇之感和抑郁不平之情。\n\n诗歌一开篇便是贫女诉说自己的不幸遭遇。这位女子因为自小生长于穷苦人家，所以穿的都是粗布麻衣，从不曾有机会穿戴华丽的衣饰。虽然物质贫乏，她却没有因此而自卑难过，反倒是世人的嫌弃让她伤心不已。明明自己已到待嫁年龄，却始终无人上门提亲，如何不令她黯然神伤...", "authors": ["余春丽"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312716573206168b2e0230a", "shortContent": "这是诗人自伤身世之作。全诗以贫女自喻，通过她的独白、自述，塑造出一个品性高洁但不为世人理解的贫女形象，从而寄托诗人自己的怀才不遇之感和抑郁不平之情。\n诗歌一开篇便是贫女诉说自己的不幸遭遇。这位女子因为自小生长于穷苦人家，所以穿的都是粗布麻衣，从不曾有机会穿戴华丽的衣饰。虽然物质贫乏，她却没有因此而自卑难过，反倒是世人的嫌弃让她伤心不已。明明自己已到待嫁年龄，却始终无人上门提亲，如何不令她黯然神伤呢...", "authors": ["余春丽"], "pressName": "崇文书局"}]', '《鉴诫录》：李山甫有《咏贫女》，天下称奇，秦韬玉之诗意转殊妙。
《瀛奎律髓》：此诗世人盛传诵之。
《唐诗鼓吹注解大全》：此韬玉伤时未遇，托贫女以自况也。
《唐诗选脉会通评林》：周珽曰：晋罗友好学，醒温虽以才遇之，许而不用。人有得郡者，温为席送别，罗友后至。温问之，对曰：“旦出，逢一鬼揶揄云：‘我见汝送人，不见人送汝。’惭怖却回，不觉淹缓。”温心愧，遂以为襄阳守。罗之语，其即“为他人作嫁衣裳”之谓乎？衡文者闻是诗，亦有淹没贤才之愧否？此伤时未遇，而托“贫女”以自况也。首联喻己素贫贱，不托荐以求进。次联喻有才德者，见弃于世。二句一气读下，若谓此俱好修容者，谁人能怜取俭饰之士也。第五句见不以才夸人。六句见不以德自骄。末伤己少有著述措置，徒供藉人作进阶耳。
《唐律偶评》：有人画眉，则已嫁之妇也，反醒“女”字，诗律精密，上句亦用纤纤女手也。此即所谓贫女难嫁也，却不便自说要嫁人，结句借他人说，极巧。
《载酒园诗话又编》：秦韬玉诗无足言，独《贫女》篇遂为古今口古。“苦恨年年压金线，为他人作嫁衣裳”，读之辄为短气，不减江州夜月、商妇琵琶也。
《山满楼笺注唐诗七言律》：此盖自伤不遇而托言也。贫士贫女，古今一辙，仕路无媒，何由自拔，所从来久矣。
《唐诗成法》：格调既高，所以不遇良媒；梳妆之俭，以其生长蓬门：（三四）分承一二。五六自伤。七结五，八结六。六句皆平头，是一病。有托而言，通首灵动，结好，遂成故事。
《唐诗别裁》：语语为贫士写照。
《瀛奎律髓汇评》：冯班：托兴可哀。何义门：高髻险妆，见《唐书·车服志》。此句就他人一面说。纪昀：格调太卑。
《诗境浅说》：此篇语语皆贫女自伤，而实为贫士不遇者，写牢愁抑塞之怀。首二句言生长蓬门，青裙椎髻，从不知罗绮之妍华，以待字之年，将托良媒以通辞，料无嘉耦，只益伤心。三四谓自抱高世之格，甘弃铅华，不知者翻怜我梳妆之俭陋也。五六谓以艺而论，则十指神针，未输薛女；以色而论，则双眉远翠，不让文君，而藐姑独处，从不向采芳女伴夸绝艺而竞新妆。末句言季女斯饥，固自安命薄。所恨者年年辛苦徒为新嫁娘费金线之功，人孰无情，谁能遣此耶！孟郊诗“坐甘冰抱晚，永谢酒怀春”，“冰抱”为难堪之境，而栖迟至晚，枯坐自甘；“酒怀”喻声利之场，乃春色虽多，孤踪永谢。与《贫女》诗意境相似，而以五言隽永出之，弥觉有味。老友章霜根翁最喜诵之。', 'center', 1417525722, '57b8e8f85bbb50005b779952', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10667, '集灵台二首', NULL, 48, 500, 2, 1, '张祜', NULL, 10152, '57baf998efa631005a803402', '唐', 'shi', '诗', 'http://baike.baidu.com/view/1124257.htm', '', '【其一】
日光斜照集灵台，红树花迎晓露开。
昨夜上皇新授籙，太真含笑入帘来。
【其二】
虢国夫人承主恩，平明骑马入宫门。
却嫌脂粉污颜色，淡扫蛾眉朝至尊。', '《集灵台二首》是唐代诗人张祜的组诗作品。这两首诗以明扬暗抑的手法嘲讽唐玄宗宠爱杨贵妃姐妹。
第一首诗讽唐玄宗夺儿媳寿王妃杨玉环为己有的丑事。杨玉环原系唐玄宗十八子寿王李瑁的妃子，玄宗召入禁中为女官，号太真，后来大加宠幸，进而册封为贵妃。首句说，旭日的光辉斜照着集灵台。集灵台是清静祀神所在，诗人指出玄宗不该在这里行道教授给秘文仪式。次句说，娇艳的花朵迎着晨露含苞开放，描写了华清宫周围美丽的景色，也是暗喻杨玉环的得宠。后两句说，昨夜唐玄宗新授道籙，集灵台又多了一位新道徒，只见微笑的太真仪态万方地走入帘来。这里指出贵妃在这时“含笑”入内，自愿为女道士，与唐玄宗配合默契，用假象掩人耳目，足见其轻薄风骚。
第二首诗讽虢国夫人的骄纵风骚。虢国夫人是杨玉环的三姊，嫁给裴家，是当时名声极坏的人。她并非“后妃”，却“承主恩”，而且“骑马入宫”“朝至尊”。自恃美艳，不施脂粉，足见她的轻佻，也可见玄宗的昏庸。', '集灵台：即长生殿，在华清宫，是祭祀求仙之所。灵，一作“虚”。
上皇：指唐玄宗。
籙：道教的灵文秘言。
太真：杨贵妃为女道士时号太真，住内太真宫。
虢国夫人：杨贵妃三姊的封号。
平明：天刚亮时。
至尊：最尊贵的位置，特指皇位。
', '【其一】
灿烂的阳光斜照着集灵台，绿树红花沐浴着晓露盛开。
昨夜玄宗皇帝新授予道箓，女道徒太真含笑走进帘来。
【其二】
虢国夫人受到皇上的宠恩，天刚亮就骑马进入了宫门。
讨厌脂粉会玷污她的美艳，淡描蛾眉就进去朝见至尊。
', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92cf0ce818559d0588b0", "shortContent": "《集灵台》诗共两首，这是第二首。集灵台在骊山之上，为祀神之所。\n杨贵妃得宠于唐玄宗，杨氏一门皆受封爵。据《旧唐书·杨贵妃传》所载，其大姐封韩国夫人，三姐封虢国夫人，八姐封秦国夫人，“并承恩泽，出入宫掖，势倾天下”。这首诗通过虢国夫人朝见唐玄宗的描写，讥讽他们之间的暧昧关系和杨氏专宠的气焰。\n首句中“承主恩”三字已暗示讽意。因为虢国夫人并非玄宗嫔妃，居然“承主恩”，实为不正常之怪事。第二句“平明骑马...", "authors": ["唐永德"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290f3", "shortContent": "张祜诗多从宫闱琐事取材，寄寓盛衰之感与讥刺君王昏庸误国之意。这组诗，以华丽辞采极力铺陈恭维杨贵妃与虢国夫人之得意与娇纵，实则嘲讽唐玄宗宠爱的杨氏姐妹之飞扬跋扈与嚣张气焰，其批判的矛头直指唐玄宗的贪色误国，发人警醒。\n\n据《旧唐书•列传一》载：“太真姿质丰艳，善歌舞，通音律，智算过人。每倩盼承迎，动移上意。宫中呼为‘娘子’，礼数实同皇后。有姊三人，皆有才貌，玄宗并封国夫人之号：长曰大姨，封韩国；三姨...", "authors": ["乐云"], "pressName": "崇文书局"}]', '《杨太真外传》：（天宝）七载，加钊御史大夫，权京兆尹，赐名国忠。封大姨为韩国夫人，三姨为虢国夫人，八姨为秦国夫人。同日拜命，皆月给钱十万，为脂粉之资。然虢国不施妆粉，自炫美艳，常素面朝天。当时杜甫（一作张拈）有诗云：“虢国夫人承主恩……”
《增订评注唐诗正声》：王云：同寓感慨，更有箴规。郭云：就事起兴，妙。
《唐诗训解》：刺时还以蕴藉为尚。
《唐诗解》：此赋事实，讽刺自见。
《诗辩坻》：“虢国夫人”一首，张承吉之作，又见杜集。然调既不类杜绝句，且拾遗诗发语忠爱，即使讽时，必不作此佻语，应属祜作无疑。
《碛砂唐诗》：谦曰：具文见意，中冓不可道矣。
《增订唐诗摘钞》：只言虢国以美自矜，而所以蛊惑人主者自在言外。“承主恩”三字，乃《春秋》之笔也。真正美人自不烦脂粉，真正才士自不买声名，真正文章自不假枝叶，以此律之，世间之“淡扫蛾眉”者寡也。
《唐贤小三昧集续集》：如睹其人。
《说诗晬语》：诗有当时盛称而品不贵者，……张祜之“淡扫蛾眉朝至尊”、李商隐之“薛王沉醉寿王醒”，此轻薄派也。
《而庵说唐诗》：虢国既为贵妃之妹，玄宗贵之可也，何至“平明骑马入金门”以承主恩？大是丑事。后即云：“却嫌脂粉污颜色，淡扫蛾眉朝至尊”，则承恩竟以貌矣。不事脂粉，天然妙丽，若说“却嫌”，虢国隐然要胜过其姊矣。……此讥刺太甚，因诗佳绝，殊不为觉。
《古唐诗合解》：此诗讥刺太甚，然却极佳。
《养一斋诗话》：前谓刺讥诗贵含蓄，论异代事犹当如此，臣子于其本朝，直可绝口不作诗耳。张祜《虢国夫人》诗：“却嫌脂粉污颜色，淡扫蛾眉朝至尊。”李商隐《骊山》诗：“平明每幸长生殿，不从金舆惟寿王。”唐人多犯此恶习。
《诗境浅说续编》：宫禁森严之地，虢国夫人纵骑而入，言其宠之渥也；脂粉转嫌污面，蛾眉不费黛螺，言其色之丽也。', 'center', 1417684865, '57b99d8ca633bd0061a01738', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10630, '独不见', NULL, 61, 154, 3, 2, '沈佺期', NULL, 10129, '57beed37c4c97100616ffaba', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383685.htm', '', '卢家少妇郁金堂，海燕双栖玳瑁梁。
九月寒砧催木叶，十年征戍忆辽阳。
白狼河北音书断，丹凤城南秋夜长。
谁为含愁独不见，更教明月照流黄。', '这是一首拟古乐府之作，刻画了一位对远戍丈夫刻骨相思的闺中贵妇形象。诗人通过环境描写烘托思妇的哀怨，以双飞双栖的燕子反衬思妇的孤独；以寒砧催落叶、明月照流黄来烘托离愁别恨。全诗辞藻典雅，华美艳丽，情景结合，意境鲜明，被历代诗评家认为是温丽高古之佳篇。', '独不见：乐府旧题，属《杂曲歌辞》。《乐府解题》：「独不见，伤思而不见也。」诗题一作《古意呈补阙乔知之》。
卢家少妇：泛指少妇。郁金堂：以郁金香料涂抹的堂屋。堂，一作「香」。梁朝萧衍《河中之水歌》：「河中之水向东流，洛阳女儿名莫愁。……十五嫁为卢家妇，十六生儿字阿侯。卢家兰室桂为梁，中有郁金苏合香。」
海燕：又名越燕，燕的一种。因产于南方滨海地区（古百越之地），故名。
玳瑁（dàimào）：海生龟类，甲呈黄褐色相间花纹，古人用为装饰品。
寒砧（zhēn）：指捣衣声。砧，捣衣用的垫石。古代妇女缝制衣服前，先要将衣料捣过。为赶制寒衣妇女每于秋夜捣衣，故古诗常以捣衣声寄思妇念远之情。
辽阳：辽河以北，泛指辽东地区。
白狼河：今辽宁省境内之大凌河。
音：一作「军」。
丹凤城：此指长安。相传秦穆公女儿弄玉吹箫，引来凤凰，故称咸阳为丹凤城。后以凤城称京城。唐时长安宫廷在城北，住宅在城南。长安大明宫正南门为丹凤门（见《两京城坊考》卷一）。
谁为：即「为谁」。为，一作「谓」。
教（jiāo）：使。
流黄：黄紫色相间的丝织品，此指帷帐，一说指衣裳。
更教：一作「使妾」。
照：一作「对」。', '郁金香涂饰在卢家少妇的楼堂，海燕栖息在用玳瑁装饰的屋梁。
在九月的捣衣声中树叶已落尽，思念着在辽阳征戍十年的丈夫。
丈夫在渺茫的白狼河音讯不通，京城中的我总觉日夜过得漫长。
谁能够看见她的孤独她的悲愁，只把那明月清辉洒落在纱帐上。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e928d911759740c9b19e0", "shortContent": "这首七律，是借用了乐府古题“独不见”。宋郭茂倩《乐府诗集》解题云：“独不见，伤思而不得见也。”本诗的主人公是一位长安少妇，她所“思而不得见”的是征戍辽阳十年不归的丈夫。诗人以委婉缠绵的笔调，描述女主人公在寒砧处处、落叶萧萧的秋夜，身居华屋之中，心驰万里之外，辗转反侧，久不能寐的孤独愁苦情状。\n“卢家少妇郁金堂，海燕双栖玳瑁梁。”卢家少妇，名莫愁，梁武帝萧衍诗中的人物，后来用作少妇的代称。郁金是一种...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389abbb31680ae4c4b737", "shortContent": "这首七律，是借用了乐府古题“独不见”。宋郭茂倩《乐府诗集》解题云：“独不见，伤思而不得见也。”本诗的主人公是一位长安少妇，她所“思而不得见”的是征戍辽阳十年不归的丈夫。诗人以委婉缠绵的笔调，描述女主人公在寒砧处处、落叶萧萧的秋夜，身居华屋之中，心驰万里之外，辗转反侧，久不能寐的孤独愁苦情状。\n\n“卢家少妇郁金堂，海燕双栖玳瑁梁。”卢家少妇，名莫愁，梁武帝萧衍诗中的人物，后来用作少妇的代称。郁金是一...", "authors": ["赵庆培"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f09361", "shortContent": "《独不见》是乐府旧题，写“伤思而不得见”（《乐府解题》）的题材。初唐的七言律多有乐府的根源，此诗也不例外。此诗另题为《古意呈乔补阙知之》，是沈佺期诗中的压卷之作，也是初唐七律的神品。\n\n卢家少妇，原指南朝乐府歌中的洛阳女子莫愁，后泛称少妇，在这首诗里，她就是抒情的主体。郁金堂是用香料抹壁的厅堂，玳瑁梁指涂饰成玳瑁彩纹的屋梁。此联写少妇住处之华美，又以“海燕双栖”来比喻夫妻双宿双飞之状。原本这位少妇...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270317f0b9738b369b196", "shortContent": "此诗另题为《古意呈乔补阙知之》，是沈佺期诗中的压卷之作，也是初唐七律的神品。\n\n《独不见》是乐府旧题，写“伤思而不得见”（《乐府解题》）的题材。初唐的七言律多有乐府的根源，此诗也不例外。\n\n卢家少妇，原指南朝乐府歌中的洛阳女子莫愁，后泛称少妇，在这首诗里，她就是抒情的主体。郁金堂是用香料抹壁的厅堂，玳瑁梁指涂饰成玳瑁彩纹的屋梁。此联写少妇住处之华美，又以“海燕双栖”来比喻夫妻双宿双飞之状。原本这位...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270547ccdb86c49f2923f", "shortContent": "此诗另题为《古意呈乔补阙知之》，是沈佺期诗中的压卷之作，也是初唐七律的神品。\n《独不见》是乐府旧题，写“伤思而不得见”（《乐府解题》）的题材。初唐的七言律多有乐府的根源，此诗也不例外。\n卢家少妇，原指南朝乐府歌中的洛阳女子莫愁，后泛称少妇，在这首诗里，她就是抒情的主体。“郁金堂”是用香料抹壁的厅堂，“玳瑁梁”指涂饰成玳瑁彩纹的屋梁。此联写少妇住处之华美，又以“海燕双栖”来比喻夫妻双宿双飞之状。原本...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '胡元瑞《诗薮·内编》卷五：卢家少妇体格丰神，良称独步，惜颔颇偏枯，结非本色。同乐府语也，同一人诗也。然起句千古骊珠，结语几成蛇足。
方仪卫《昭昧詹言》：本以燕之双栖兴少妇独居，却以「郁金堂」、「玳瑁梁」等字攒成异彩，五色并驰，令人目眩，此得齐梁之秘而加神妙者。三四不过叙流年时景，而措语沉着重稳。五六句分写行者，居者，匀配完足，复以「白狼」、「丹凤」攒染设色。收拓并一步，正跌进一步。曲折圆转，如弹丸脱手，远包齐梁，高振唐音。
胡赤城《唐音癸签》：沈诗篇题原名《独不见》，一结翻题取巧，六朝乐府变声，非律诗正格也。
沈归愚《说诗晬语》卷上：云卿《独不见》一章，骨高，气高，色泽情韵俱高，视中唐「莺啼燕语报新年」诗，味薄语纤，床分上下。', 'center', 1417525788, '57b99e98a633bd0061a020a4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10631, '鹿柴', NULL, 1734, 394, 2, 7, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/view/95032.htm', '', '空山不见人，但闻人语响。
返景入深林，复照青苔上。', '此诗描写鹿柴傍晚时分的幽静景色。诗的绝妙处在于以动衬静，以局部衬全局，清新自然，毫不做作。落笔先写「空山」寂绝人迹，接着以「但闻」一转，引出「人语响」来。空谷传音，愈见其空；人语过后，愈添空寂。最后又写几点夕阳馀晖的映照，愈加触发人幽暗的感觉。', '鹿柴（zhài）：王维辋川别墅之一（在今陕西省蓝田县西南）。柴：通「寨」、「砦」，用树木围成的栅栏。
但：衹。
返景（yǐng）：同「返影」，太阳将落时通过云彩反射的阳光。
复：又。', '山中空旷寂静看不见人，只听得说话的人语声响。
夕阳的金光直射入深林，又照在幽暗处的青苔上。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92977d0ac1145495371a", "shortContent": "这是王维后期的山水诗代表作——五绝组诗《辋川集》二十首中的第四首。鹿柴（zhài），是辋川的地名。\n诗里描绘的是鹿柴附近的空山深林在傍晚时分的幽静景色。第一句“空山不见人”，先正面描写空山的杳无人迹。王维似乎特别喜欢用“空山”这个词语，但在不同的诗里，它所表现的境界却有区别。“空山新雨后，天气晚来秋”（《山居秋暝》），侧重于表现雨后秋山的空明洁净；“人闲桂花落，夜静春山空”（《鸟鸣涧》），侧重于表...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc40927", "shortContent": "这是王维后期的山水诗代表作——五绝组诗《辋川集》二十首中的第四首。鹿柴（狕犺à犻），是辋川的地名。\n\n诗里描绘的是鹿柴附近的空山深林在傍晚时分的幽静景色。第一句“空山不见人”，先正面描写空山的杳无人迹。王维似乎特别喜欢用“空山”这个词语，但在不同的诗里，它所表现的境界却有区别。“空山新雨后，天气晚来秋”（《山居秋暝》），侧重于表现雨后秋山的空明洁净；“人闲桂花落，夜静春山空”（《鸟鸣涧》），侧重于...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f40c26cbf3417f09363", "shortContent": "鹿柴，是王维在辋川别业的胜景之一。辋川有胜景二十处，王维逐处作诗，每景一诗，并有好友裴迪同咏，收录为《辋川集》，这首诗是其中的第五首。清沈德潜《唐诗别裁》说：“佳处不在语言，与陶公‘采菊东篱下，悠然见南山’同。”王维此诗与陶渊明的空灵、隐逸有相似的境界。宋刘辰翁《唐诗品汇》亦说：“无言而有画意。”这些评语都表达了一致的内容，那就是“诗中有画”。\n\n本诗是一首山水诗，诗中表达了作者对大自然的热爱，同...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270437ccdb86c49f2921c", "shortContent": "鹿柴，是王维在辋川别业的胜景之一。辋川有胜景二十处，王维逐处作诗，每作一诗，并有好友裴迪同咏，收录为《辋川集》，这首诗是其中的第五首。清沈德潜《唐诗别裁》说：“佳处不在语言，与陶公‘采菊东篱下，悠然见南山’同。”王维此诗与陶渊明的空灵、隐逸有相似的境界。《唐诗品汇》引宋刘辰翁评：“无言而有画意。”这些评语都表达了一致的内容，那就是“诗中有画”。\n\n本诗是一首山水诗，诗中表达了作者对大自然的热爱，同...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127077f2af4e09d55b6791", "shortContent": "鹿柴，是王维在辋川别业的胜景之一。辋川有胜景二十处，王维逐处作诗，每景一诗，并有好友裴迪同咏，收录为《辋川集》，这首诗是其中的第五首。清代沈德潜《唐诗别裁》卷十九说：“佳处不在语言，与陶公‘采菊东篱下，悠然见南山’同。”王维此诗与陶渊明的空灵、隐逸有相似的境界。而宋代刘辰翁在《唐诗品汇》卷三十九中说：“无言而有画意。”这些评语都表达了一致的内容，那就是“诗中有画”。\n\n本诗是一首山水诗，诗中表达了...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "6464775c7f27182da3531308", "shortContent": "这是王维后期的山水诗代表作——五绝组诗《辋川集》二十首中的第四首。鹿柴(zhài)，是辋川的地名。\n\n诗里描绘的是鹿柴附近的空山深林在傍晚时分的幽静景色。第一句“空山不见人”，先正面描写空山的杳无人迹。王维似乎特别喜欢用“空山”这个词语，但在不同的诗里，它所表现的境界却有区别。“空山新雨后，天气晚来秋”（《山居秋暝》），侧重于表现雨后秋山的空明洁净；“人闲桂花落，夜静春山空”（《鸟鸣涧》），侧重于...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f0beae49f46528ad170da", "shortContent": "如果只读第一句，也许会觉得它比较平常，但在“空山不见人”之后紧接“但闻人语响”，却境界顿出。“但闻”二字颇可玩味。通常情况下，寂静的空山尽管“不见人”，却非一片静默死寂。啾啾鸟语，唧唧虫鸣，瑟瑟风声，潺潺水响，相互交织，大自然的声音其实是非常丰富多彩的。然而，现在这一切都杳无声息，只是偶尔传来一阵人语声，却看不到人影（由于山深林密）。这“人语响”，似乎是破“寂”的，实际上是以局部的、暂时的“响”反...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '《王孟诗评》：无言而有画意。顾云：此篇写出幽深之景。
《批点唐诗正声》：不言处反胜有，言复不佳。
《唐诗广选》：李宾之曰：诗贵淡不贵浓，贵远不贵近。如杜诗「钩帘宿鹭起，丸药流莺转」、李诗「桃花流水杳然去，别有天地非人间」与摩诘「返景」二语，皆淡而浓、近而远，可为知者道，难与俗人言也。
《唐诗直解》：无言而有画意，「复照」妙甚。
《唐诗训解》：不见人，幽矣；闻人语，则非寂灭也。景照青苔，冷淡自在。摩诘出入渊明，独《辋川》诸作最近，探索其趣，不拟其词。如「结庐在人境，而无车马喧」，喧中之幽也；「空山不见人，但闻人语响」，幽中之喧也。如此变化，方入三昧法门。
《唐诗选注》：玉遮曰：衹四语，令人应接不暇。
《唐诗笺要》：景到处有情，情到处生景，可思不可象，摩诘真五绝圣境。
《而菴说唐诗》：此首眼目在「空山」二字。右丞笔下直是大光明藏，无有一字在也。
《唐贤三昧集笺注》：五绝乃五古之短章，最难简古浑妙。唐人此体，右丞可称妙手。
《唐诗别裁》：佳处不在语言，与陶公「采菊东篱下，悠然见南山」同。
《唐诗笺注》：「不见人」、「闻人语」，以林深也。林深少日，易长青苔，而反景照入，空山阒寂，真麋鹿场也。诗细甚。
《诗法易简录》：人语响，是有声也；返景照，是有色也。写空山不从无声无色处写，偏从有声有色处写，而愈见其空。严沧浪所谓「玲珑剔透」者，应推此种。沈归愚谓其「佳处不可语言」，然诗之神韵意象，虽超于字句之外，实不能不寓于字句之间，善学者须就其所已言者，而玩索其不言之蕴，以得于字句之外可也。
《唐贤清雅集》：空而非空，宛而不宛，闲淡入妙。
《唐人万首绝句选评》：写出幽深。
《诗境浅说续编》：深林中苔翠阴阴，日光所不及，惟夕阳自林间斜射而入，照此苔痕，深碧浅红，相映成采。此景无人道及，惟妙心得之，诗笔复能写出。', 'center', 1417545806, '57b8ffa3128fe10054c9814d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10632, '杂诗三首', NULL, 565, 394, 1, 7, '王维', NULL, 10075, '57b9841f2e958a005e6bbb17', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/130767/9946121.htm', '', '【其一】
家住孟津河，门对孟津口。
常有江南船，寄书家中否。
【其二】
君自故乡来，应知故乡事。
来日绮窗前，寒梅著花未？
【其三】
已见寒梅发，复闻啼鸟声。
心心视春草，畏向玉阶生。', '《杂诗三首》，是王维拟江南乐府民歌风格所作的一组抒写男女别后相思之情的五言绝句。
第一首，描写闺人怀远以及盼望音书的心情。
第二首，描写游子思念家人，向故乡来人询问家中情形的话。诗以白描记言的手法，简洁而形象地刻划了主人公思乡的情感。对于离乡游子而言，故乡可怀念的东西很多。然而诗不写眷怀山川景物，风土人情，却写眷念窗前「寒梅着花未？」，可谓「于细微处见精神」，寓巧于朴，韵味浓郁，栩栩如生。
第三首，写思妇给丈夫回信中的话。三首诗写出一种缠绵深婉之情，或直抒胸臆，或托物寄怀，都不事雕琢。', '孟津河：指河南洛阳北部的黄河南岸一带，是「武王伐纣，与八百诸侯会盟」之地，为古代交通要道。
君：对对方的尊称，您。
故乡：家乡，这里指作者的故乡。
来日：来的时候。
绮窗：雕画花纹的窗户。
寒梅：冬天绽放的梅花。
著（zhuó）花未：开花没有？著花，开花；未，用于句末，相当于「否」，表疑问。
玉阶：《万首唐人绝句》作「阶前」。', '【其一】
家住在孟津河旁，家门与孟津渡口相对。每天沿河有来自江南的小船，是否有丈夫从江南寄回的书信呢？
【其二】
您是刚从我们家乡来的，一定了解家乡的人情世态。请问您来的时候我家雕画花纹的窗户前，那一株梅花开了没有？
【其三】
看见梅花已经开了，又听见鸟儿的啼叫声。一颗充满忧愁的心看着春草生长，愈来愈茂盛的春草眼看就要连到阶前，禁不住惶恐起来了。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9298911759740c9b1a13", "shortContent": "诗中的抒情主人公（“我”，不一定是作者），是一个久在异乡的人，忽然遇上来自故乡的旧友，首先激起的自然是强烈的乡思，是急欲了解故乡风物、人事的心情。开头两句，正是以一种不加修饰、接近于生活的自然状态的形式，传神地表达了“我”的这种感情。“故乡”一词迭见，正表现出乡思之殷；“应知”云云，迹近噜苏，却表现出了解乡事之情的急切，透露出一种儿童式的天真与亲切。纯用白描记言，却简洁地将“我”在特定情形下的感情...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab821a74606fc4092a", "shortContent": "诗中的抒情主人公（“我”，不一定是作者），是一个久在异乡的人，忽然遇上来自故乡的旧友，首先激起的自然是强烈的乡思，是急欲了解故乡风物、人事的心情。开头两句，正是以一种不加修饰、接近于生活的自然状态的形式，传神地表达了“我”的这种感情。“故乡”一词迭见，正表现出乡思之殷；“应知”云云，迹近噜苏，却表现出了解乡事之情的急切，透露出一种儿童式的天真与亲切。纯用白描记言，却简洁地将“我”在特定情形下的感情...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e9038c", "shortContent": "这首小诗一如《山中送别》（“山中相送罢，日暮掩柴扉。春草明年绿，王孙归不归？”）那样直白、朴质，仿佛就把大白话搬进诗作——“君自故乡来，应知故乡事”。说一个久在异乡的人，突然在他乡遇到了一位来自故乡的旧时友人，这时就不仅是“他乡遇故知”的那份惊喜和感动，其中还包含着对友人带来故乡讯息的殷切期待。友人从遥远的故乡而来，理应知道故乡的人事变化。这绝对是无理之语！仿佛若不带来故乡的消息，就有愧于友人的期...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270447ccdb86c49f29223", "shortContent": "这首小诗一如《山中送别》（“山中相送罢，日暮掩柴扉。春草明年绿，王孙归不归？”）那样直白、朴质，仿佛就把大白话搬进诗作——“君自故乡来，应知故乡事”。说一个久在异乡的人，突然在他乡遇到了一位来自故乡的旧时友人，这时就不仅是“他乡遇故知”的那份惊喜和感动，其中还包含着对友人带来故乡讯息的殷切期待。友人从遥远的故乡而来，理应知道故乡的人事变化。这绝对是无理之语！仿佛若不带来故乡的消息，就有愧于友人的期...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127077f2af4e09d55b6797", "shortContent": "这首小诗一如《山中送别》（“山中相送罢，日暮掩柴扉。春草明年绿，王孙归不归？”）那样直白、朴质。仿佛就把大白话搬进诗作——“君自故乡来，应知故乡事。”说一个久在异乡的人，突然在他乡遇到了一位来自故乡的旧时友人，这时就不仅是“他乡遇故知”的那份惊喜和感动，其中还包含着对友人带来故乡讯息的殷切期待。友人从遥远的故乡而来，理应知道故乡的人事变化。这绝对是无理之语！仿佛若不带来故乡的消息，就有愧于友人的期...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646c2ebbb6a81d0c53127f97", "shortContent": "家铉翁是眉州（治所在今四川眉山）人，长期在南宋朝廷做官，亡国时已官至端明殿学士、签署枢密院事。因不署招降檄文而招怨元军，随吴坚使元被扣留，但拒不出仕，始终眷念故国，所以元人修的《宋史》也说他“义不二君，辞无诡对”。这首《寄江南故人》，就是羁留燕京时所作。\n\n“曾向钱塘住”,“钱塘”指南宋都城临安，“向”犹“在”。“闻鹃忆蜀乡”，是说对故乡四川，虽然早就离开，但只要一听到那“不如归去”的杜鹃声，便勾...", "authors": ["程一中"], "pressName": "上海辞书出版社"}, {"bookId": "645d142de745e33de3132d73", "bookTitle": "王维诗鉴赏辞典", "articleId": "6464782145e4710056c2f043", "shortContent": "诗中的抒情主人公（“我”，不一定是作者），是一个久在异乡的人，忽然遇上来自故乡的旧友，首先激起的自然是强烈的乡思，是急欲了解故乡风物、人事的心情。开头两句，正是以一种不加修饰、接近于生活的自然状态的形式，传神地表达了“我”的这种感情。“故乡”一词迭见，正表现出乡思之殷；“应知”云云，迹近噜苏，却表现出了解乡事之情的急切，透露出一种儿童式的天真与亲切。纯用白描记言，却简洁地将“我”在特定情形下的感情...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '宋·刘须溪《王孟诗评》：三首皆淡中含情。
清·宋顾乐《唐人万首绝句选》评此诗（《杂诗》其二）：以微物悬念，传出件件关心，思家之切。
陈建生：王右丞《杂诗》三首，娴熟运用中国画的留白艺术，使诗歌产生很强的艺术张力，留下更多想象的审美空间。', 'center', 1417546979, '57b910f3df0eea00633562cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10633, '崔九欲往南山马上口号与别', NULL, 129, 30, 1, 2, '裴迪', NULL, 10148, '57b9595b2e958a005fa8644b', '唐', 'shi', '诗', 'http://baike.baidu.com/view/10396139.htm', '', '归山深浅去，须尽丘壑美。
莫学武陵人，暂游桃源里。', '作者生活的时代大约属于唐玄宗和唐肃宗时期，这首大约作于唐玄宗后期。那个时候由于唐玄宗任用奸相李林甫，宠幸杨贵妃，政治十分黑暗，下层知识分子无法入仕。崔九即崔兴宗，盛唐诗人，早年与裴迪、王维隐居唱和，后来出仕为官，官至右补阙，但不久即对官场生活产生厌恶情绪，去官归隐。裴迪为之饯行送别，作此诗以劝勉。
此诗劝勉崔九既要隐居，就必须坚定不移，不要三心两意，入山复出，不甘久隐。全诗用语浅淡，近乎口语，或暗用典，或明用典，或正劝，或反讽，喻之以理，晓之以情，在看似平淡的外表下蕴涵着浓郁的朋友情谊，含意颇为深远。', '诗题又作《送崔九》。
崔九：即崔兴宗，尝与王维、裴迪同居辋川。
南山：即辋川南边的终南山，故诗中说他“归山”。
马上口号：在马背上顺口吟成诗句。《全唐诗》此诗题下注：一作“留别王维”。
丘壑：既指丘陵川壑，也是暗用典故，含劝友人隐逸山林，莫改初衷之意。《世说新语·品藻》载：“明帝问谢鲲：‘君自谓何如庾亮？’答曰：‘端委庙堂，使百僚准则，臣不如亮；一丘一壑，自谓过之。’”
武陵人：指陶潜《桃花源记》中的武陵渔人。', '你若要归山无论深处浅处都要去看看；要尽情地赏玩山峦沟壑的清净秀美。千万别学陶渊明笔下那个武陵人，只在桃花源暂时游了游就匆匆出山。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e9038d", "shortContent": "《送崔九》又名《崔九欲往南山马上口号与别》。崔九即崔兴宗，盛唐诗人，早年与裴迪、王维隐居唱和，后来出仕为官，官至右补阙，但不久即对官场生活产生厌恶情绪，去官归隐。裴迪为之饯行送别，作此诗以劝勉。此诗大约作于唐玄宗后期，玄宗任用奸相李林甫，宠幸杨贵妃，政治十分黑暗。下层知识分子像裴迪、崔兴宗这样的寒士，入仕无门，所以他们宁愿隐居山林，过一种与世隔绝的生活。\n\n诗的一、二句是在告诉友人如若入山去，不论...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127068f2af4e09d55b6782", "shortContent": "《送崔九》又名《崔九欲往南山马上口号与别》。崔九即崔兴宗，盛唐诗人，早年与裴迪、王维隐居唱和，后来出仕为官，官至右补阙，但不久即对官场生活产生厌恶情绪，去官归隐。裴迪为之饯行送别，作此诗以劝勉。这首诗大约作于唐玄宗后期。那个时候由于唐玄宗任用奸相李林甫，宠幸杨贵妃，政治十分黑暗，下层知识分子无法入仕，像裴迪、崔兴宗这样的寒士没有出路。所以他们宁愿隐居山林，过一种与世隔绝的生活。\n\n这是一首劝勉诗，...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270e1f2af4e09d55b6805", "shortContent": "《送崔九》又名《崔九欲往南山马上口号与别》。崔九即崔兴宗，盛唐诗人，早年与裴迪、王维隐居唱和，后来出仕为官，官至右补阙，但不久即对官场生活产生厌恶情绪，去官归隐。裴迪为之饯行送别，作此诗以劝勉。这首诗大约作于唐玄宗后期。那个时候由于唐玄宗任用奸相李林甫，宠幸杨贵妃，政治十分黑暗，下层知识分子无法入仕，像裴迪、崔兴宗这样的寒士没有出路。所以他们宁愿隐居山林，过一种与世隔绝的生活。\n\n这是一首劝勉诗，...", "authors": ["林锦萍"], "pressName": "崇文书局"}]', '', 'center', 1417547233, '57ba4dfc5bbb500063f957b2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10634, '终南望余雪', NULL, 293, 36, 2, 3, '祖咏', NULL, 10142, '57b9bf0ac4c9710061480c6e', '唐', 'shi', '诗', 'http://baike.baidu.com/view/356506.htm', '', '终南阴岭秀，积雪浮云端。
林表明霁色，城中增暮寒。', '此诗主要描写终南山的余雪，通过山峰与阳光的向背表现了各处不同的景象，又联想到山头的积雪消融后，丛林明亮，低处的城中反会增寒，景色虽好，不知有多少寒士受冻。全诗咏物寄情，意在言外，精练含蓄，朴实俏丽，意境清幽，给人以清新之美。', '终南：终南山，在唐京城长安（今陕西西安）南面六十里处。馀（yú）雪：指未融化之雪。馀，即余。
阴岭：北面的山岭，背向太阳，故曰阴。
林表：林外，林梢。霁（jì）：雨、雪后天气转晴。
暮寒：傍晚的寒气。', '韵译
从长安望终南山北景色秀美，远看岭上积雪似乎浮在云端。
雨雪晴后夕阳微光染亮树梢，长安城中傍晚反增阵阵轻寒。
散译
终南山北坡一片清丽，皑皑积雪似白云飘浮在天际。林梢被初晴的阳光映照得分外透明，黄昏的城里又增添了阵阵寒气。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e9294d635634aee3deb23", "shortContent": "据元辛文房《唐诗纪事》卷二十记载，这首诗是祖咏在长安应试时作的。按照规定，应该作成一首六韵十二句的五言排律，但他只写了这四句就交卷。有人问他为什么，他说：“意思已经完满了。”这真是无话即短，不必画蛇添足。\n题意是望终南馀雪。从长安城中遥望终南山，所见的自然是它的“阴岭”（山北叫“阴”）；而且，惟其“阴”，才有“馀雪”。“阴”字下得很确切。“秀”是望中所得的印象，既赞颂了终南山，又引出下句。“积雪浮...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e9038e", "shortContent": "据《唐诗纪事》卷二十记载，唐玄宗开元十二年（724），祖咏在长安应进士试，这首诗是他的应试诗。按例，应试诗应为五言六韵十二句，但祖咏写了这四句就交卷，考官问他何故，他回答说“意尽”。也就是说，他认为已经将意思表达清楚了，无须画蛇添足。\n\n这首诗写雪晴后，从长安城南望终南山的景象。“终南阴岭秀”，从长安城中遥望终南山，见到的自然是它的“阴岭”（山北叫“阴”）；而且，惟其“阴”，才会有“馀雪”，阳光普...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312703bf2af4e09d55b6734", "shortContent": "据《唐诗纪事》卷二十记载，唐玄宗开元十二年（724），祖咏在长安应进士试，这首诗是他的应试诗。按例，应试诗应为五言六韵十二句，但祖咏写了这四句就交卷，考官问他何故，他回答说“意尽”。也就是说，他认为已经将意思表达清楚了，无须画蛇添足。\n\n这首诗写雪晴后，从长安城南望终南山的景象。“终南阴岭秀”，从长安城中遥望终南山，见到的自然是它的“阴岭”（山北叫“阴”）；而且，唯其“阴”，才会有“馀雪”，阳光普...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312706ac305cf0801816fed", "shortContent": "据《唐诗纪事》卷二十记载，唐玄宗开元十二年（724），祖咏在长安应进士试，这首诗是他的应试诗。按例，应试诗应为五言六韵十二句，但祖咏写了这四句就交卷，考官问他何故，他回答说“意尽”。也就是说，他认为已经将意思表达清楚了，无须画蛇添足。\n\n这首诗写雪晴后，从长安城南望终南山的景象。“终南阴岭秀”，从长安城中遥望终南山，见到的自然是它的“阴岭”（山北叫“阴”）；而且，唯其“阴”，才会有“馀雪”，阳光普...", "authors": ["易文翔"], "pressName": "崇文书局"}]', '明·高棅《增订评注唐诗正声》：凛凛有寒色。
明·徐用吾《唐诗分类绳尺》：结句有讽。
明·李攀龙《唐诗训解》：已霁犹寒，越见积雪。
明·钟惺《唐诗归》：说得缥缈森秀。
明·玉遮《唐诗选》：“浮”字极好，诗亦佳绝，但只赋得积雪，不赋得余雪。
清·王夫之《诗绎》：庸手必刻画残雪正面矣，作者三四只用托笔写意，体格高浑。
清·吴敬夫《唐诗归折衷》：可见诗不论何体，终期意尽而止。凡绝句意不尽者，皆未成之律诗也。
清·焦袁熹《此木轩论诗汇编》：如此不拘，诗安得不高？意尽即不须续，更难在举场中作如此事。
清·徐增《而庵说唐诗》：此首须看其安放题面次第，如月吐层云，光明渐现，闭目犹觉宛然也。此诗处处针线细密，真绣鸳鸯手也。······此外真更不能添一语也。
清·宋宗元《网师园唐诗笺》：写“残”字高浑。
清·施补华《岘佣说诗》：苍秀之笔，与韦相近。
近代·高步瀛《唐宋诗举要》：古今雪诗，惟羊孚一赞及陶渊明“倾耳无希声，在目皓已洁”，及祖咏“终南阴岭秀”一篇，右丞“洒空深巷静，积素广庭宽”，韦左司“门对寒流雪满山”句，最佳。
近代·俞陛云《诗境浅说续编》：咏高山积雪，若从正面着笔，不过言山之高，雪之色，及空翠与皓素相映发耳。此诗从侧面着想，言遥望雪后南山，如开霁色，而长安万户，便觉生寒，则终南之高寒可想。用流水对句，弥见诗心灵活。且以霁色为喻，确是积雪，而非飞雪，取譬殊工。', 'center', 1417547306, '57b96d640a2b58005c96251e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (50924, '苏幕遮', NULL, 0, 26, 0, 1, '高道宽', NULL, 11195, '5858e6398d6d810065c3153c', '元', 'ci', '词', NULL, NULL, '灭无争，真火候。升降全凭，一点丹无漏。锁定元初兴宇宙。月到离宫，自有神明祐。
炼天和，真药就。片饷工夫，看是谁参透。玉笋钻冰仙乐奏。朝现三清，万劫长春寿。', NULL, NULL, NULL, NULL, NULL, 'indent', 1529944451, '585cefbdac502e00672127db', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (50925, '苏幕遮', NULL, 0, 26, 0, 1, '高道宽', NULL, 11195, '5858e6398d6d810065c3153c', '元', 'ci', '词', NULL, NULL, '大参同，人难会。点开圆明，照觉迷天睡。举动施为明与昧。乾里丹元，休把真空背。
坤中药，方以类。采得将来，付与丁公配。合就一丸先天味。食了登仙，鹤驾游方外。', NULL, NULL, NULL, NULL, NULL, 'indent', 1529944444, '585cefbd61ff4b00580c74e2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10635, '送灵澈上人', NULL, 547, 492, 2, 8, '刘长卿', NULL, 10113, '57b9a043165abd00661cbf89', '唐', 'shi', '诗', 'http://baike.baidu.com/view/576767.htm', '', '苍苍竹林寺，杳杳钟声晚。
荷笠带斜阳，青山独归远。', '此诗前两句写灵澈上人欲回竹林寺的情景，后两句写诗人目送灵澈上人辞别归去的情景，抒发了诗人对友人离别的伤感与依依不舍之情，表达了对灵澈的深厚情意，也表现了灵澈清寂的风度以及诗人虽然失意却闲适淡泊的情怀。全诗纯为写景，恍如图画，借景抒情，构思精致，语言精炼，素朴秀美，意境闲淡，是一首感情深沉的送别诗，也是一幅构图美妙的景物画，为唐代山水诗的名篇。', '灵澈（chè）上人：唐代著名僧人，本姓杨，字源澄，会稽（今浙江绍兴）人，后为云门寺僧。上人，对僧人的敬称。
苍苍：深青色。竹林寺：在今江苏丹徒南。
杳（yǎo）杳：深远的样子。
荷（hè）笠：背着斗笠。荷，背着。', '苍翠的丛林掩映着竹林寺，远远地传来黄昏的钟鸣声。
身背斗笠在夕阳的映照下，正独自沿着青山走向远方。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e90395", "shortContent": "自肃宗上元二年（761）从贬谪地南巴（今广东茂名南）归来，到唐代宗大历四年（769）左右再度回到吴中，前后大约十年光景，刘长卿一直失意待官，四处漂游，心情郁闷。\n\n正当刘长卿闲游润州之时，碰到了自己多年未见的好友灵澈僧。灵澈俗姓汤，字源澄，会稽（今浙江绍兴）人，出家的本寺就在会稽云门山云门寺。源澄为人秉性耿直，忤权贵，遭贬斥，乃弃官归隐云门寺，与刘长卿相友善，两人一直情谊深挚。好友多年未见，本该举...", "authors": ["董镇菲"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270597f0b9738b369b1d8", "shortContent": "自上元二年（761）从贬谪地南巴（今广东茂名南）归来，到唐代宗大历四年（769）左右再度回到吴中，前后大约十年光景，刘长卿一直失意待官，四处漂泊，心情郁闷。\n\n正当刘长卿闲游润州之时，碰到了自己多年未见的好友灵澈僧。灵澈俗姓汤，字源澄，会稽（今浙江绍兴）人，出家的本寺就在会稽云门山云门寺。源澄为人秉性耿直，忤权贵，遭贬斥，乃弃官归隐云门寺，与刘长卿相友善，两人一直情谊深挚。好友多年未见，本该举杯把...", "authors": ["董镇菲"], "pressName": "崇文书局"}]', '', 'center', 1417597585, '57b90887128fe10054c9c750', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10636, '听弹琴', NULL, 418, 492, 2, 3, '刘长卿', NULL, 10113, '57b9a043165abd00661cbf89', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383722.htm', '', '泠泠七弦上，静听松风寒。
古调虽自爱，今人多不弹。', '这是一首借咏古调的冷落，不为人所重视，来抒发怀才不遇，世少知音的小诗。前两句描摹音乐境界，后两句抒发情怀。全诗从对琴声的赞美，转而对时尚慨叹，流露了诗人孤高自赏，不同凡俗，稀有知音的情操。
从弹古调而引起对时俗的感慨。既叹知音稀少，又感平生失意是因为不合时宜，和前面秦韬玉的“谁爱风流离格调”有相似感。琴是我国古代传统民族乐器，由七条弦组成，所以首句以“七弦”作琴的代称，意象也更具体。“泠泠”形容琴声的清越，逗起“松风寒”三字。“松风寒”以风入松林暗示琴声的凄清，极为形象，引导读者进入音乐的境界。“静听”二字描摹出听琴者入神的情态，可见琴声的超妙。高雅平和的琴声，常能唤起听者水流石上、风来松下的幽清肃穆之感。而琴曲中又有《风入松》的调名，一语双关，用意甚妙。', '泠（líng）泠：形容清凉、清淡，也形容声音清越。丝：一作“弦”。
松风：以风入松林暗示琴声凄凉。琴曲中有《风入松》的调名。
古调：古时的曲调。', '七弦琴奏出清凉的曲调悠扬起伏，细细倾听就像那滚滚的松涛声。
我虽然很喜爱这首古时的曲调，但在今天人们大多已不去弹奏了。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a65e272d4b225432ac", "shortContent": "诗题一作《弹琴》，此据《刘随州集》。从诗中“静听”二字细味，题目以有“听”字为妥。\n琴，亦称“七弦琴”，俗称“古琴”，是我国古代传统民族乐器，由七条弦组成。所以首句以“七弦”作琴的代称，意象也更具体。“泠泠”形容琴声的清越，逗起“松风寒”三字。“松风寒”以风入松林暗示琴声的凄清，极为形象，引导读者进入音乐的境界。“静听”二字描摹出听琴者入神的情态，可见琴声的超妙。高雅平和的琴声，常能唤起听者水流石...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d117", "shortContent": "诗题一作《弹琴》，此据《刘随州集》。从诗中“静听”二字细味，题目以有“听”字为妥。\n\n琴，亦称“七弦琴”，俗称“古琴”，是我国古代传统民族乐器，由七条弦组成。所以首句以“七弦”作琴的代称，意象也更具体。“泠泠”形容琴声的清越，逗起“松风寒”三字。“松风寒”以风入松林暗示琴声的凄清，极为形象，引导读者进入音乐的境界。“静听”二字描摹出听琴者入神的情态，可见琴声的超妙。高雅平和的琴声，常能唤起听者水流...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e90396", "shortContent": "汉魏六朝南方清乐尚用琴瑟。而到唐代，音乐发生变革，“燕乐”成为一代新声，乐器则以西域传入的琵琶为主，公众的欣赏趣味也变了。\n\n这是一首托物言志诗，又名《弹琴》。前两句是描写音乐的境界，后两句则是议论性抒情。刘长卿清才冠世，一生两遭迁斥，有满腹不合时宜和一种与流俗落落寡合的情调。本诗写诗人静听弹琴，弹琴人技艺高超，琴声幽清美妙，并借古调受冷遇以抒发自己怀才不遇的抑郁自伤之情，感叹世上知音罕有，表达了...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270597f0b9738b369b1d5", "shortContent": "汉魏六朝南方清乐尚用琴瑟，而到唐代，音乐发生变革，“燕乐”成为一代新声，乐器则以西域传入的琵琶为主，公众的欣赏趣味也变了。刘长卿清才冠世，一生两遭迁斥，有满腹不合时宜和一种与流俗落落寡合的情调。\n\n这是一首托物言志诗，又名《弹琴》。前两句是描写音乐的境界，后两句则是议论性抒情。写诗人静听弹琴，弹琴人技艺高超，琴声幽清美妙，并借古调受冷遇以抒发自己怀才不遇的抑郁自伤之情，感叹世上知音罕有，表达了诗人...", "authors": ["林錦萍"], "pressName": "崇文书局"}]', '', 'center', 1417597641, '57b8f70a8ac2470062df5501', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10637, '送方外上人 / 送上人', NULL, 38, 492, 0, 2, '刘长卿', NULL, 10113, '57b9a043165abd00661cbf89', '唐', 'shi', '诗', 'http://baike.baidu.com/view/576769.htm', '', '孤云将野鹤，岂向人间住。
莫买沃洲山，时人已知处。', '这是一首送别诗，前两句以凌云的野鹤形容僧人，贴切有味，理应不失孤云野鹤般脱俗的品性；末两句写诗人对方外上人的讽喻规劝，劝上人隐居冷寂的深山，而不要到热闹的名胜去沽名钓誉。
此诗写得妙趣横生、闲情逸趣，流露出诗人很看重灵澈孤云野鹤般脱俗的境界，向往隐居深山之中，规劝方外上人“莫买沃洲山”，表现出诗人规劝方外上人领悟真隐和假隐之真谛，莫隐居变成趋时，亦体现出诗人与方外上人之间的真挚友谊。', '上人：对僧人的敬称。
“孤云”句：张祜在《寄灵澈诗》中有“独树月中鹤，孤舟云外人”句，与此用意正相同。将：和，共。
沃洲山：在浙江省新昌县东，相传为晋代高僧支遁放鹤养马处，有放鹤峰，养马坡，道家列为第十二洞天福地。', '野鹤驾着孤云高飞天空，岂肯在人间居住？
你不必到著名的沃洲山福地，那可是人们最熟悉的去处。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e90397", "shortContent": "这是一首送行诗。诗中的上人，指的是灵澈。灵澈上人是中唐时期一位著名诗僧，俗姓汤，字源澄，会稽（今浙江绍兴）人，在会稽云门山云门寺出家。与刘禹锡、刘长卿、吕温交往甚密，互有诗相赠，享誉当时诗坛。\n\n诗中第一、二句说孤云陪伴着野鹤居住在天上，又怎么能到人间来住呢？“野鹤”指的是世外高人，超脱世俗之人，这里指的是灵澈上人。反问的语气突出了上人的清高，也为下文对入山隐居提出的警示埋下伏笔。\n\n诗中第三、四...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270597f0b9738b369b1d6", "shortContent": "灵澈上人是中唐时期一位著名诗僧，俗姓杨，字源澄，会稽（今浙江绍兴）人，在会稽云门山云门寺出家。与刘禹锡、刘长卿、吕温交往甚密，互有诗相赠，享誉当时诗坛。刘长卿为灵澈留下许多诗作，多为送别，都表达了两人深厚的友谊和惜别不舍之情。\n\n这是一首送行诗。诗中的上人，指的正是灵澈。诗人以野鹤喻灵澈，恰合其身份。后二句含有讥讽灵澈入山不深的意味，讽劝其不应到沃洲山去凑热闹，那个地方已被世人所熟知，不能说是隐居...", "authors": ["林锦萍"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270c79761253910e905af", "shortContent": "灵澈上人是中唐时期一位著名诗僧，俗姓杨，字源澄，会稽（今浙江绍兴）人，在会稽云门山云门寺出家。与刘禹锡、刘长卿、吕温交往甚密，互有诗相赠，享誉当时诗坛。刘长卿为灵澈留下许多诗作，多为送别，都表达了两人深厚的友谊和惜别不舍之情。\n\n这是一首送行诗。诗中的上人，指的正是灵澈。诗人以野鹤喻灵澈，恰合其身份。后二句含有讥讽灵澈入山不深的意味，讽劝其不应到沃洲山去凑热闹，那个地方已被世人所熟知，不能说是隐居...", "authors": ["林锦萍"], "pressName": "崇文书局"}]', '明代陆时雍《唐诗镜》：貌古而唐，以有做作在。
清代沈德潜《唐诗别裁》：有“三宿桑下，已嫌其迟”意，盖讽之也。
清代宋宗元《网师园唐诗笺》：峭刻浑成。', 'center', 1417597736, '57bc59342e958a00694612df', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10638, '秋夜寄丘二十二员外/秋夜寄邱员外', NULL, 441, 570, 2, 4, '韦应物', NULL, 10115, '57b9b835128fe1005f860400', '唐', 'shi', '诗', 'http://baike.baidu.com/view/9680572.htm', '', '怀君属秋夜，散步咏凉天。
空山松子落，幽人应未眠。', '这是一首怀人诗。诗人与丘二十二员外在苏州时过往甚密，丘临平山学道时，诗人写此诗以寄怀。诗的首两句，写自己因秋夜怀人而徘徊沉吟的情景；後两句想象所怀的人这时也在怀念自己而难以成眠。隐士常以松子为食，因而想到松子脱落季节卽想起对方。一样秋色，异地相思。着墨虽淡，韵味无穷；语浅情深，言简意长。全诗以其古雅闲淡的风格美，给人回味无穷的艺术享受。', '丘二十二员外：名丹，苏州人，曾拜尚书郎，後隐居平山上。丘，一作「邱」。
属：正值，适逢，恰好。
山空：一作「空山」，据古刻本《临平记》及明·李沧溟《古今诗删》正。
幽人：幽居隐逸的人，悠闲的人。此处指丘员外。', '怀念你竟在这深秋的夜晚，散步咏叹多么寒凉的霜天。
想此刻空山中正掉落松子，幽居的友人一定还未安眠。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b9d635634aee3ded6f", "shortContent": "韦应物的五言绝句，一向为诗论家所推崇。明胡应麟在《诗薮》中说：“中唐五言绝，苏州最古，可继王、孟。”清沈德潜在《说诗晬语》中说：“五言绝句，右丞之自然、太白之高妙、苏州之古淡，并入化境。”上面这首诗是他的五绝代表作之一。它给予读者的艺术享受，首先就是这一古雅闲淡的风格美。清施补华在《岘傭说诗》中曾称赞这首诗“清幽不减摩诘，皆五绝中之正法眼藏也”。它不以强烈的语言打动读者，只是从容下笔，淡淡着墨，而...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a90", "shortContent": "韦应物的五言绝句，一向为诗论家所推崇。明胡应麟在《诗薮》中说：“中唐五言绝，苏州最古，可继王、孟。”清沈德潜在《说诗晬语》中说：“五言绝句，右丞之自然、太白之高妙、苏州之古淡，并入化境。”上面这首诗是他的五绝代表作之一。它给予读者的艺术享受，首先就是这一古雅闲淡的风格美。清施补华在《岘佣说诗》中曾称赞这首诗“清幽不减摩诘，皆五绝中之正法眼藏也”。它不以强烈的语言打动读者，只是从容下笔，淡淡着墨，而...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e90398", "shortContent": "这是一首怀人诗。一、二句写怀念友人的自己。邱二十二员外，名丹，曾拜尚书郎，后隐居临平山。秋夜和凉天，点明了时间是在秋天的一个凉爽的晚上，作者因为怀念故人难以入眠，索性就闲庭信步吧。这两句从容入笔，语言自然而情韵悠长，耐人寻味。\n\n三、四两句写在临平山学道的丹邱。这两句在艺术上别具匠心，诗人不是直说自己如何如何思念对方，而是从对方写起，诗情飞到对方。\n\n陆机在《文赋》说：“观古今于须臾，抚四海于一瞬...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '《韦孟全集》：幽情淡景，触处成诗，苏州用意闲妙若此。
《唐诗广选》：蒋仲舒曰：浅而远，自是苏州本色。
《汇编唐诗十集》：唐云：以我揣彼，无限情致。
《诗绎》：中唐五言绝，苏州最古。寄邱员外作，悠然有盛唐风格。三四思邱之思己，应念我未眠，妙在含蓄不尽。
《增订唐诗摘钞》：妙在第三句宛是幽人，故末句脱口而出。
《网师园唐诗笺》：悠然神往。
《唐诗选胜直解》：孤怀寂寞，谁与唱酬，忽忆良朋，正当秋夜，散步庭除之际，吟诗寄远，因念幽居，想亦未眠，以吟咏为乐，书去恍如觌面也。情致委曲，句调雅淡。
《唐人万首绝句选评》：淡而远，是苏州本色。第三句将写景一衬，落句便有情味。
《岘佣说诗》：韦公「怀君属秋夜」一首，淸幽不改摩诘，皆五绝之正法眼藏也。', 'center', 1417597831, '57b923075bbb50005b794870', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10639, '听筝', NULL, 170, 240, 1, 2, '李端', NULL, 10149, '57ba67182e958a0069371f52', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/264965/5820189.htm', '', '鸣筝金粟柱，素手玉房前。
欲得周郎顾，时时误拂弦。', '该诗描写一位弹筝女子为了所爱慕的人顾盼自己，故意将弦拨错，塑造了一个可爱的弹筝女形象，透视心理状态，洞察入微，语句传神，意蕴丰富。', '鸣筝：弹奏筝曲。
金粟：古也称桂为金粟，这里当是指弦轴之细而精美。
柱：定弦调音的短轴。
素手：指弹筝女子纤细洁白的手。
玉房：指玉制的筝枕。房，筝上架弦的枕。
周郎：指三国时吴将周瑜。他二十四岁为大将，时人称其为“周郎”。他精通音乐，听人奏错曲时，即使喝得半醉，也会转过头看一下奏者。当时人称：“曲有误，周郎顾。”
拂弦：拨动琴弦。', '金粟轴的古筝发出优美的声音，那素手拨筝的美人弹奏着玉制的筝枕。想尽了办法为博取周郎的青睐，你看她故意地时时拨错了琴弦。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b62cee9a0c24ecf95a", "shortContent": "筝是古代一种弹拨乐器，即今称“古筝”。“鸣筝”谓弹奏筝曲。题一作“听筝”，则谓听奏筝有感，就听者立题。从诗意看，以作“鸣筝”为有味。这首小诗写一位弹筝女子为博取青睐而故意弹筝出错的情态，写得婉曲细腻，富有情趣。\n前二句写弹筝美人坐在华美的房舍前，拨弄筝弦，优美的乐声从弦轴里传送出来。“柱”是系弦的部件。“金粟”形容筝柱的装饰华贵。“素手”表明弹筝者是女子。后二句即写鸣筝女故意弹错以博取青睐。“周郎...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac26845f3e157ce329", "shortContent": "筝是古代一种弹拨乐器，即今称“古筝”。“鸣筝”谓弹奏筝曲。题一作“听筝”，则谓听奏筝有感，就听者立题。从诗意看，以作“鸣筝”为有味。这首小诗写一位弹筝女子为博取青睐而故意弹筝出错的情态，写得婉曲细腻，富有情趣。\n\n前二句写弹筝美人坐在华美的房舍前，拨弄筝弦，优美的乐声从弦轴里传送出来。“柱”是系弦的部件。“金粟”形容筝柱的装饰华贵。“素手”表明弹筝者是女子。后二句即写鸣筝女故意弹错以博取青睐。“周...", "authors": ["倪其心"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e90399", "shortContent": "这首诗通过弹筝女子一个小小的动作，将其狡黠的心意播绘得生动真切。\n\n一、二句交代事由与人物。鸣筝，说明人物是弹奏古筝的乐师。素手，点明这位乐师是一位女子。金粟柱，柱，是古筝系弦之物；金粟，形容筝柱装饰华美，点明乐器之华丽贵重。玉房，说明屋舍之精致典雅。琴极珍贵，屋极雅致，说明这是富贵人家的一次家宴，而女子正在宴会上为大家弹奏乐曲。这本是再寻常不过的酒会歌台，可是诗人却注意到了非常有趣的细节。这位弹...", "authors": ["张春晓"], "pressName": "崇文书局"}]', '', 'center', 1417598120, '57b9015ad342d3005ac72e80', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10679, '金谷园', NULL, 188, 501, 2, 1, '杜牧', NULL, 10109, '57b9836cc4c971005593dfec', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/350263/14675712.htm', '', '繁华事散逐香尘，流水无情草自春。
日暮东风怨啼鸟，落花犹似坠楼人。', '这是一首即景生情诗。诗人经过西晋富豪石崇的金谷园遗址而兴吊古情思。前句写金谷园昔日的繁华，今已不见；二句写人事虽非，风景不殊；三、四两句即景生情，听到啼鸟声声似在哀怨；看到落花满地，想起当年坠楼自尽的石崇爱妾绿珠。句句写景，层层深入，景中有人，景中寓情。写景意味隽永，抒情凄切哀婉。', '金谷园：金谷本地名，在河南洛阳市西北，西晋卫尉石崇筑园于此，园极奢丽。
香尘：沉香之末。石崇为教练家中舞妓步法，以沉香屑铺象牙床上，使她们践踏，无迹者赐以珍珠。
流水无情：流水一去不回，毫无情意。多用以比喻事物的发展不依人的意志为转移。流水，指金谷水。《水经注·谷水注》：“谷水又东，左会金谷水，水出自太白原，东南流历金谷，谓之金水。东南流，经晋卫尉卿石崇之故居也。”
坠楼人：谓石崇的爱妾绿珠。绿珠（？-300），石崇家歌妓，善吹笛。时赵王司马伦杀贾后，自称相国，专擅朝政，石崇与潘岳等谋劝淮南王司马允、齐王司马冏倚靠司马伦，谋未发。司马伦有嬖臣孙秀，家世寒微，与司马冏结仇，得司马伦赏识后，又向石崇求绿珠，石崇不许。此时力劝司马伦杀石崇，母兄妻子十五人皆死。甲士到门逮捕石崇，石崇对绿珠说：“我今为尔得罪。”绿珠边泣边说：“当效死于官前。”因自坠于楼下而死。事见《晋书·石崇传》及《世说新语·仇隙篇》。杨炫之《洛阳伽蓝记》卷一：“昭仪寺有池，······后隐士赵逸云：‘此地是晋侍中石崇家池，池南有绿珠楼。’”', '繁华的往事已随着香尘散尽，没能够留下半点踪迹，如茵的春草年年自绿，流水无情地悄悄逝去。黄昏时啼鸟在东风里噬怨声声，飘飞的落花还像那坠楼的人。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d95e272d4b22543532", "shortContent": "金谷园故址在今河南洛阳西北，是西晋富豪石崇的别墅，繁荣华丽，极一时之盛。唐时园已荒废，成为供人凭吊的古迹。据《晋书·石崇传》记载：石崇有妓曰绿珠，美而艳。孙秀使人求之，不得，矫诏收崇。崇正宴于楼上，谓绿珠曰：“我今为尔得罪。”绿珠泣曰：“当效死于君前。”因自投于楼下而死。杜牧过金谷园，即景生情，写下了这首咏春吊古之作。\n面对荒园，首先浮现在诗人脑海的是，金谷园繁华的往事，随着芳香的尘屑消散无踪。“...", "authors": ["唐永德"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4dc26cbf3417f09392", "shortContent": "清人吴乔在《围炉诗话》中曾说：“古人咏史，但叙事而不出己意，则史也，非诗也。出己意，发议论，而斧凿铮铮，又落宋人之病。”杜牧的咏史绝句，虽好为翻案文章，却能力避窠臼，别出心裁，自成高格，正可谓“用意隐然，最为得体”（吴乔《围炉诗话》）。\n\n金谷，在河南洛阳市西北，西晋巨富石崇在此筑园，故名金谷园。史载，金谷园极奢丽，内藏奇珍异宝，后世被喻为豪奢享乐之地。据《晋书•石崇传》记载，石崇有爱妾绿珠，美艳...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645d0ac98258810260dbe044", "bookTitle": "杜牧诗文鉴赏辞典", "articleId": "6461f0fcc0471b0062c159ce", "shortContent": "金谷园故址在今河南洛阳西北，是西晋富豪石崇的别墅，繁荣华丽，极一时之盛。唐时园已荒废，成为供人凭吊的古迹。据《晋书·石崇传》记载：石崇有妓曰绿珠，美而艳。孙秀使人求之，不得，矫诏收崇。崇正宴于楼上，谓绿珠曰：“我今为尔得罪。”绿珠泣曰：“当效死于君前。”因自投于楼下而死。杜牧过金谷园，即景生情，写下了这首咏春吊古之作。\n\n面对荒园，首先浮现在诗人脑海的是，金谷园繁华的往事，随着芳香的尘屑消散无踪。...", "authors": ["唐永德"], "pressName": "上海辞书出版社"}]', NULL, 'center', 1417685894, '57b91fe98ac2470062e09a0f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10640, '新嫁娘三首', NULL, 91, 516, 2, 1, '王建', NULL, 10150, '57be56e47db2a20068dfa3b2', '唐', 'shi', '诗', 'http://baike.baidu.com/view/339465.htm', '', '【其一】
邻家人未识，床上坐堆堆。
郎来傍门户，满口索钱财。
【其二】
锦幛两边横，遮掩侍娘行。
遣郎铺簟席，相并拜亲情。
【其三】
三日入厨下，洗手作羹汤。
未谙姑食性，先遣小姑尝。', '诗描摹一位新嫁娘巧思慧心的情态。第一次烧饭菜。为了把握婆婆的口味，先遣婆婆养大的小姑尝试。语虽浅白。却颇为得体，合情合理。新娘的机灵聪敏，心计巧思，跃然纸上。「先遣小姑尝」，真是于细微处见精神。', '未识：一作「不识」。
锦幛：色彩鲜明的华丽的幛子。
侍娘行：一作「待娘行」。
亲情：亲戚。
三日：古代风俗，新媳妇婚后三日须下厨房做饭菜。
羹：泛指做成浓的菜肴。
谙：熟悉。
姑食性：婆婆的口味。
遣：让。
小姑：一作「小娘」。丈夫的妹妹。也称小姑子。', '【其三】
新婚三天来到厨房，洗手亲自来作羹汤。
不知婆婆什么口味，做好先让小姑品尝。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c05e272d4b2254345a", "shortContent": "“新媳妇难当”——在旧社会人们普遍有这种看法。但也有些新媳妇在新嫁的处境中找到了办法，应付了难局，使得事情的发展带有戏剧性，甚至富有诗趣。像王建的这首诗所写的，即属于此类。这也是唐代社会封建礼教控制相对放松，妇女们的巧思慧心多少能够得以表现出来的一种反映。\n“三日入厨下，洗手作羹汤。”古代女子嫁后的第三天，俗称“过三朝”，依照习俗要下厨房做菜。“三日”，正见其为“新嫁娘”。“洗手作羹汤”，“洗手”...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad9820695e6503ffd1", "shortContent": "“新媳妇难当”——在旧社会人们普遍有这种看法。但也有些新媳妇在新嫁的处境中找到了办法，应付了难局，使得事情的发展带有戏剧性，甚至富有诗趣。像王建的这首诗所写的，即属于此类。这也是唐代社会封建礼教控制相对放松，妇女们的巧思慧心多少能够得以表现出来的一种反映。\n\n“三日入厨下，洗手作羹汤。”古代女子嫁后的第三天，俗称“过三朝”，依照习俗要下厨房做菜。“三日”，正见其为“新嫁娘”。“洗手作羹汤”，“洗手...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e9039a", "shortContent": "王建是中唐擅长妇女题材的大家。他往往将目光聚焦女子于婚姻家庭中的种种际遇，以优柔之性观妇女之事，体妇女之情，在妇女日常生活琐事中提炼素材，尽骋才情，这首《新嫁娘》便是其中之一。该诗是一首新题乐府，塑造了一位聪敏、灵巧的小媳妇，语言通俗，叙事直白，捕捉生活中最富表现力的细节来刻画人物，读来生动有趣，贴切自然。\n\n“三日入厨下，洗手作羹汤。”“三日”是指新媳妇过门后的第三天，依照古代婚嫁习俗的惯例，这...", "authors": ["唐靓"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706d9761253910e90546", "shortContent": "王建是中唐擅长妇女题材的大家，他往往将目光聚焦于女子婚姻家庭中的种种际遇，以优柔之性观妇女之事，体妇女之情，在妇女日常生活琐事中提炼素材，尽骋才情，这首《新嫁娘》便是其中之一。该诗是一首新题乐府，塑造了一位聪敏、灵巧的新媳妇的形象，语言通俗，叙事直白，由于善于捕捉生活中最富表现力的细节刻画人物，读来生动有趣，贴切自然。\n\n“三日入厨下，洗手作羹汤。”“三日”是指新媳妇过门后的第三天，依照古代婚嫁习...", "authors": ["唐靓"], "pressName": "崇文书局"}]', '《后村诗话》：王建《新嫁娘》：「未谙姑食性，先遣小姑尝。」张文潜《寄衣曲》：「别来不见身长短，试比小郎衣更长，二诗当以建为胜。
《唐诗绝句类选》：前辈教人作绝句，令诵「三日入厨下」、「打起黄莺儿」、「画松一似真松树」，恃自肺腑中流出，无牵强斧凿痕。
《唐诗摘钞》：极细事，道出便妙，只是一真。
《增订唐诗摘钞》：同朴语庄，不作丽语。得酒食是议意。
《唐诗别裁》：诗至真处，一字不可移易。
《说诗晬语》：五言绝句，右丞之自然，太白之高妙，苏州之古淡，并人化机。……他如崔颢《长干曲》、金昌绪《春怨》、王建《新嫁娘》，张祜《宫词》等篇，虽非专家，亦称绝调。
《唐诗笺注》：新妇与姑未习，小姑易亲，转圜机绪慧转甚。入情入理，语亦天然。
《读雪山房唐诗钞序例》：王建之《新嫁娘》，即其乐府。
《唐人绝句精华》：佳处在朴素而又生动，有民间歌谣之趣。', 'center', 1417598351, '57b8ece25bbb50005b77aa91', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10641, '玉台体 其十一', NULL, 30, 389, 0, 1, '权德舆', NULL, 10151, '57beed8dc4c97100616ffe6f', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383726/10296457.htm', '', '昨夜裙带解，今朝蟢子飞。
铅华不可弃，莫是藁砧归。', '这是一首描写妇女盼望丈夫回还的诗。开头以“裙带解”、“蟢子飞”即征兆喜事的习俗进入题意，三句以梳妆打扮，点出内心的喜悦，结句和盘托出主题。感情真挚，朴素含蓄，语俗而不伤雅，情乐又不淫靡。', '玉台体：南朝徐陵编诗选《玉台新咏》，多为艳诗或言情诗，以此得名。
裙带解：古代女子裙举忽然松开为喜兆。
蟢子：小蜘蛛脚长者，俗称蟢子。
铅华：指脂粉。
藁砧：丈夫的隐语。', '昨晚我裙带忽然松弛解开，早晨又看见蟢子双双飞来。
要赶紧描眉擦粉梳妆打扮，莫非是我的丈夫快要回来？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92bf2e6a6b501f95c324", "shortContent": "南朝徐陵曾把梁代以前的诗选作十卷，定名《玉台新咏》。宋严羽说：“或者但谓纤艳者玉台体，其实则不然。”（《沧浪诗话》）可知这一诗集，香艳者居多。权德舆此首，标明仿效“玉台体”，写的是闺情，感情真挚，朴素含蓄，可谓俗不伤雅，乐而不淫。\n人在寂寞烦忧之时，常常要左顾右盼，寻求解脱苦恼的征兆。特别当春闺独守，更易表现出这种情绪和心理。我国古代妇女，结腰系裙之带，或丝束，或帛缕，或绣绦，一不留意，有时就难免...", "authors": ["傅经顺"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e9039b", "shortContent": "这是一首描写独守春闺的妇女思念丈夫的思妇闺怨诗。人在寂寞烦忧之时，常常要左顾右盼，寻求解脱苦恼的征兆。特别当春闺独守，更易表现出这种情绪和心理。诗中通过捕捉女性的外部动作和内心细腻的心理感受，把妻子思念远方丈夫的婉约缠绵、幽怨感伤写得悠长含蓄，耐人寻味。丈夫出门后，女主人公的处境、心思、生活情态如何，诗人都未作说明，但从思妇的心理独白中，通过“裙带解”、“蟢子飞”等不一般人不注意的小事，确见女主人...", "authors": ["李晶晶"], "pressName": "崇文书局"}]', '', 'center', 1417598540, '57bc4ebdefa631005a896f42', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10642, '行宫', NULL, 139, 890, 1, 1, '元稹', NULL, 10082, '57b9bf37d342d3006be01c7b', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383727/6682172.htm', '', '寥落古行宫，宫花寂寞红。
白头宫女在，闲坐说玄宗。', '这是一首抒发盛衰之感的诗。首句点明地点：古行宫；二句暗示时间：红花盛开之季；三句介绍人物；白头宫女；四句描绘动作：闲坐说玄宗。构筑了一幅完整动人的图画。当年花容月貌，娇姿艳质，辗转落入宫中，寂寞幽怨；如今青春消逝，红颜憔悴；闲坐无聊，只有谈论已往。此情此景，好不凄绝！', '寥（liáo）落：寂寞冷落。
行宫：皇帝在京城之外的宫殿。这里指当时东都洛阳的皇帝行宫上阳宫。
宫花：行宫里的花。
白头宫女：据白居易《上阳白发人》，一些宫女天宝末年被“潜配”到上阳宫，在这冷宫里一闭四十多年，成了白发宫人。
说：谈论。
玄宗：指唐玄宗。', '空旷冷落的古旧行宫，只有宫花寂寞地艳红。
几个满头白发的宫女，闲坐无事谈论唐玄宗。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92cddbb8b379ee095ce7", "shortContent": "元稹的这首《行宫》可与白居易《上阳白发人》参互并观。这里的古行宫即洛阳行宫上阳宫，白头宫女即“上阳白发人”。据白居易《上阳白发人》，这些宫女天宝末年被“潜配”到上阳宫，在这冷宫里一闭四十多年，成了白发宫人。这首短小精悍的五绝具有深邃的意境，富有隽永的诗味，倾诉了宫女无穷的哀怨之情，寄托了诗人深沉的盛衰之感。\n诗人塑造意境，艺术上主要运用了两种表现手法。一是以少总多。我国古典诗歌讲究精练，写景、言情...", "authors": ["林东海"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ad4797a92d5e4fd90f", "shortContent": "元稹的这首《行宫》可与白居易《上阳白发人》参互并观。这里的古行宫即洛阳行宫上阳宫，白头宫女即“上阳白发人”。据白居易《上阳白发人》，这些宫女天宝末年被“潜配”到上阳宫，在这冷宫里一闭四十多年，成了白发宫人。这首短小精悍的五绝具有深邃的意境，富有隽永的诗味，倾诉了宫女无穷的哀怨之情，寄托了诗人深沉的盛衰之感。\n\n诗人塑造意境，艺术上主要运用了两种表现手法。一是以少总多。我国古典诗歌讲究精练，写景、言...", "authors": ["林东海"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e9039e", "shortContent": "元稹的《行宫》诗通过宫女们的悲惨遭遇，反映出在深宫幽闭的岁月里，葬送了无数妇女的青春和幸福，从而揭露了封建宫廷广选妃嫔这一制度的残酷与罪恶。此诗当与白居易长诗《上阳白发人》对照欣赏。此诗只有四句共二十个字，却在极有限的篇幅中传达了十分丰富的内容。在这里，笔墨的节省仅仅是表面特征，关键在于造语凝练、精确，富于表现力，像绘画中的速写一样，笔触洗练、流畅、肯定，取其神似。\n\n诗的首句点题，主语是“行宫”...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127075e6f69b71e93f62d7", "shortContent": "元稹的《行宫》诗通过宫女们的悲惨遭遇，反映出在深宫幽闭的岁月里，葬送了无数妇女的青春和幸福，从而揭露了封建宫廷广选妃嫔这一制度的残酷与罪恶。全诗只有四句共二十个字，在极有限的篇幅中传达了十分丰富的内容。在这里，笔墨的节省仅仅是表面特征，关键在于造语凝练、精确，富于表现力，像绘画中的速写一样，笔触洗练、流畅、肯定，取其神似。\n\n诗的首句点题，主语是“行宫”，用“古”和“寥落”两个形容词修饰古”的含义...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127123e6f69b71e93f63b7", "shortContent": "元稹的《行宫》诗通过宫女们的悲惨遭遇，反映出在深宫幽闭的岁月里，葬送了无数妇女的青春和幸福，从而揭露了封建宫廷广选妃嫔这一制度的残酷与罪恶。全诗只有四句共二十个字，在极有限的篇幅中传达了十分丰富的内容。在这里，笔墨的节省仅仅是表面特征，关键在于造语凝练、精确，富于表现力，像绘画中的速写一样，笔触洗练、流畅、肯定，取其神似。\n\n诗的首句点题，主语是“行宫”，用“古”和“寥落”两个形容词修饰：“古”的...", "authors": ["杨军"], "pressName": "崇文书局"}]', '宋代洪迈《容斋随笔》卷二：语少意足，有无穷之味。
明代胡应麟《诗薮·内编》卷六：语意绝妙，合（王）建七言《宫词》百首，不易此二十字也。
清代沈德潜《唐诗别裁集》：只四语，已抵一篇《长恨歌》矣。”“说元宗而不说元宗长短，佳绝。
近代刘永济：此诗可谓《连昌宫词》之缩写。', 'center', 1417610452, '57b9bfe3165abd00661e1c7d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10643, '何满子', NULL, 263, 500, 2, 1, '张祜', NULL, 10152, '57baf998efa631005a803402', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/1124248/14262693.htm', '', '故国三千里，深宫二十年。
一声何满子，双泪落君前。', '这是一首短小的宫怨诗。首句写宫女离家遥远；二句写入宫多年；三句写悲愤到达极点；四句写君前落泪以示抗议。一般宫怨诗多写宫女失宠或不得幸之苦，而此诗却一反其俗，写在君前挥泪怨恨，还一个被夺去幸福与自由的女性的本来面目。这是独到之所在。
全诗只用了「落」字一个动词。其他全部以名词组成，因而显得特别简括凝炼，强烈有力；又每句嵌入数目字，把事件表达得清晰而明确。', '何满子：唐教坊曲名。《乐府诗集》载白乐天语：「何满子，开元中沧州歌者，临刑进此曲以赎死，竞不得免。」《何满子》曲调悲绝，白乐天《河满子》诗中说它「一曲四词歌八叠，从头便是断肠声。」
故国：故乡。此为代宫女而言。
深宫：指皇宫。
君：指唐武宗。', '故乡远在三千里之外，关闭在皇宫整整二十年。我唱一曲悲凉的《何满子》，眼泪不由得双双落在唐武宗的面前。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f429761253910e903a0", "shortContent": "这是一首宫怨诗，一反宫怨诗含蓄委婉的传统，直叙其事，展示了一幅宫人生活全图，直截了当地表达了宫人埋藏极深、蓄积极久的悲怨。\n\n“故国三千里”，比喻宫人离家之远；“深宫二十年”，比喻进宫之久。前两句使用对应的手法，从空间和时间上交代了女主角所处的状态。两句话有四个意象，“故国”与“深宫”是实指，“三千里”和“二十年”是虚指，实指交代诗歌发生的背景，虚指旨在增强诗歌的感染力。女主角虽然还未露面，但通过...", "authors": ["徐昌盛"], "pressName": "崇文书局"}]', '宋·王归叟《王直方诗话》：张祜有《观猎诗》并《宫词》，白傅称之。《宫词》云：「故国三千里……」小杜守秋浦，与祜为诗友，酷爱祜《宫词》，赠诗曰：「如何故国三千里，虚唱歌词满六宫。」
宋·葛懶眞《韵语阳秋》：张祜诗云：「故国三千里，深宫二十年。」杜牧赏之，作诗云：「可怜故国三千里，虚唱歌词满六宫。」故郑谷云：「张生故国三千里，知者惟应杜紫薇。」诸贤品题如是，祜之诗名安得不重乎？
明·髙漫士《批点唐诗正声》：衷情苦韵。
清·贺檗斋《载酒园诗话又编》：宫体请诗，实皆浅淡，即「故国三千里，深宫二十年」，亦甚平常，不知何以合誉至此！
清·范大士《历代诗法》：一气奔注。
清·王阮亭《唐人万首绝句选评》：《何满子》其声最悲，乐天诗云：「一曲四词歌八叠，从头便是断肠声。」此诗更悲在上二句，如此而唱悲歌，那禁泪落！', 'center', 1417610576, '57b909fba633bd00665d9373', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10644, '寻隐者不遇', NULL, 1653, 408, 1, 10, '贾岛', NULL, 10153, '57b928ae8ac2470062e0e27d', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/114317/8470689.htm', '', '松下问童子，言师采药去。
只在此山中，云深不知处。', '此诗首句写寻者问童子，后三句都是童子的答话，诗人采用了寓问于答的手法，把寻访不遇的焦急心情，描绘得淋漓尽致。诗中以白云比隐者的高洁，以苍松喻隐者的风骨，写寻访不遇，愈衬出寻者对隐者的钦慕高仰之情。全诗遣词通俗清丽，言繁笔简，情深意切，白描无华，是一篇难得的言简意丰之作。', '寻：寻访。隐者：隐士，隐居在山林中的人。古代指不肯做官而隐居在山野之间的人。一般指的是贤士。不遇：没有遇到，没有见到。
童子：没有成年的人，小孩。在这里是指“隐者”的弟子、学生。
言：回答，说。
云深：指山上的云雾。处：行踪，所在。', '苍松下，我询问了年少的学童；他说，师傅已经采药去了山中。　　他还对我说，就在这座大山里，可山中云雾缭绕，不知他行踪。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92cfc6e67846a920ed39", "shortContent": "贾岛是以“推敲”两字出名的苦吟诗人。一般认为他只是在用字方面下工夫，其实他的“推敲”不仅着眼于锤字炼句，在谋篇构思方面也是同样煞费苦心的。此诗就是一个例证。\n这首诗的特点是寓问于答。“松下问童子”，必有所问，而这里把问话省略了，只从童子所答“师采药去”这四个字而可想见当时松下所问是“师往何处去”。接着又把“采药在何处”这一问句省掉，而以“只在此山中”的童子答辞，把问句隐括在内。最后一句“云深不知处...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae4797a92d5e4fd915", "shortContent": "贾岛是以“推敲”两字出名的苦吟诗人。一般认为他只是在用字方面下功夫，其实他的“推敲”不仅着眼于锤字炼句，在谋篇构思方面也是同样煞费苦心的。此诗就是一个例证。\n\n这首诗的特点是寓问于答。“松下问童子”，必有所问，而这里把问话省略了，只从童子所答“师采药去”这四个字而可想见当时松下所问是“师往何处去”。接着又把“采药在何处”这一问句省掉，而以“只在此山中”的童子答辞，把问句隐括在内。最后一句“云深不知...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f449761253910e903a2", "shortContent": "贾岛不以五绝著称，诗歌风格也偏于奇僻险峻。尽管如此，并不妨碍《寻隐者不遇》成为他绝句的压卷之作。\n \n题目交代诗人寻访隐士却遭遇了空舍，淡淡的失望之情显而易见。于是诗人不由得仔细观察起隐士房舍周围的景物。《三国演义》写刘备三顾茅庐，为了给诸葛亮的出现制造气氛，以衬托出他的高风亮节，对诸葛茅庐周围环境进行了详细描写。然而诗歌不可能像小说那样铺张，因此诗人极其经济地拈取了“松下”这一典型的意象。松在古...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127075e6f69b71e93f62e6", "shortContent": "贾岛不以五绝著称，诗歌风格也偏于奇僻险峻。尽管如此，并不妨碍《访隐者不遇》成为他绝句的压卷之作。\n\n诗歌内容简单浅显，如与老妪对话，毋庸细解。诗歌之所以久负盛名，为大众所喜闻乐见，其妙处就在于意象的选择和意境的营造上。题目交代诗人寻访归藏山林的隐士却遭遇了空舍，诗人淡淡的失望之情溢于言表。于是诗人不由得仔细观察起隐士房舍周围的景物。《三国演义》写刘备三顾茅庐，为了给诸葛亮的出现制造气氛，以衬托出他...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271317ccdb86c49f292f2", "shortContent": "贾岛不以五绝著称，诗歌风格也偏于奇僻险峻。尽管如此，并不妨碍《访隐者不遇》成为他绝句的压卷之作。\n诗歌内容简单浅显，如与老妪对话，毋庸细解。诗歌之所以久负盛名，为大众所喜闻乐见，其妙处就在于意象的选择和意境的营造上。题目交代诗人寻访归藏山林的隐士却遭遇了空舍，诗人淡淡的失望之情溢于言表。于是诗人不由得仔细观察起隐士房舍周围的景物。\n《三国演义》写刘备三顾茅庐，为了给诸葛亮的出现制造气氛，以衬托出他...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471a21ae49f46528adbe4a5", "shortContent": "贾岛是以“推敲”两字出名的苦吟诗人。一般认为他只是在用字方面下功夫，其实他的“推敲”不仅着眼于锤字炼句，在谋篇构思方面也是同样煞费苦心的。此诗就是一个例证。\n这首诗的特点是寓问于答。“松下问童子”，必有所问，而这里把问话省略了，只从童子所答“师采药去”这四个字而可想见当时松下所问是“师往何处去”。接着又把“采药在何处”这一问句省掸，而以“只在此山中”的童子答辞，把问句隐括在内。最后一句“云深不知处...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}]', '明高棅《唐诗正声》：吴逸一评：自是妙音，所谓不用意而得者。
明李攀龙、叶羲昂《唐诗直解》：愈近愈杳。
明蒋一葵《唐诗选汇解》：首句问，下三句答，直中有婉，婉中有直。
明凌宏宪《唐诗广选》：俞仲蔚曰：意味闲雅，脍炙人口。
明唐汝询《唐诗解》：设为童子之言，以状山居之幽。
明王夫之《姜斋诗话》：《十九首》及《上山采蘼芜》等篇，止以一笔入圣证。自潘岳以凌杂之心作芜乱之调，而后元声几熄。唐以后间有能此者，多得之绝句耳。——意之中但取一句，“松下问童子”是已。如“怪来妆阁闭”，又止半句，愈入化境。
明徐增《而庵说唐诗》：夫寻隐者不遇，则不遇而已矣，却把一童子来作波折，妙极！有心寻隐者，何意遇童子，而此童子又恰是所寻隐者之弟子，则隐者可以遇矣。问之，“言师采药去”，则又可以遇矣……曰“只在此山中”，“此山中”见甚近，“只在”见不往别处，则又可以遇矣。岛方喜形于色，童子却又云：“是便是，但此山中云深，卒不知其所在，却往何处去寻？”是隐者终不可遇矣。此诗一遇一不遇，可遇而终不遇，作多少层折！今人每每趁笔直下。古人有云：“笔扫千军，词流三峡”，误尽后贤，此唐已后所以无诗也。
清黄叔灿《唐诗笺注》：语意真率，无复人间烟火气。
清李锳《诗法易简录》：一句问，下三句答，写出隐者高致。
清吴烶《唐诗选胜直解》：设为童子之言，以答寻问之意，不必实有此事。不露题字，而意已见。
近代王文濡《唐诗评注读本》：此诗一问一答，四句开合变化，令人莫测。', 'center', 1419108722, '57b996a50a2b58005fc797c9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10655, '桃花溪', NULL, 325, 14, 1, 5, '张旭', NULL, 10158, '57b91728df0eea0063359a02', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/356526/10043553.htm', '', '隐隐飞桥隔野烟，石矶西畔问渔船。
桃花尽日随流水，洞在清溪何处边。', '此诗为张旭借陶渊明《桃花源记》的意境而创作的写景诗。通过描写桃花溪幽美的景色和作者对渔人的询问，抒写一种向往世外桃源，追求美好生活的心情。诗由远外落笔，写山谷深幽，迷离恍惚，隔烟朦胧，其境若仙；然后镜头移近，写桃花流水，渔舟轻泛，问讯渔人，寻找桃源。全诗构思婉曲，情韵悠长，创造了一个饶有画意、充满情趣的幽深境界。', '桃花溪：水名，在湖南省桃源县桃源山下。
飞桥：高桥。
石矶：水中积石或水边突出的岩石、石堆。渔船：源自陶渊明《桃花源记》中语句。
尽日：整天，整日。
洞：指《桃花源记》中武陵渔人找到的洞口。', '一座高桥隔着云烟出现，在岩石的西畔询问渔船。
桃花整天随着流水流淌，桃源洞口在清溪的哪边？', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f459761253910e903ae", "shortContent": "据《清一统志》载：“湖南常德府，桃花溪在桃源县西南二十五里，源出桃花山，北流入沅。”溪岸多桃林，暮春时节，落英缤纷，随波逐流。相传东晋陶渊明的《桃花源记》就是以这里为背景的。\n\n史载张旭曾为常熟尉，后入京官拜金吾长史，并无确证说他曾到过桃花溪，但这并不妨碍诗人创作。因为经过南北朝、隋直到唐代，由于《桃花源记》的广泛流传和对陶渊明隐逸情怀、高洁人格的认同和追慕，使得“桃花源”已成为世人精神世界和文化...", "authors": ["唐磊"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127053e6f69b71e93f6285", "shortContent": "据《清一统志》载：“湖南常德府，桃花溪在桃源县西南二十五里，源出桃花山，北流入沅。”溪岸多桃林，暮春时节，落英缤纷，随波逐流。相传东晋陶渊明的《桃花源记》就是以这里为背景的。\n\n史载张旭曾为常熟尉，后人京官拜金吾长史，并无确证说他曾到过桃花溪，但这并不妨碍诗人创作。因为经过南北朝、隋直到唐代，由于《桃花源记》的广泛流传和对陶渊明隐逸情怀、高洁人格的认同和追慕，使得“桃花源”已成为世人精神世界和文化...", "authors": ["唐磊"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270c69761253910e905a1", "shortContent": "据《清一统志》载：“湖南常德府，桃花溪在桃源县西南二十五里，源出桃花山，北流入沅。”溪岸多桃林，暮春时节，落英缤纷，随波逐流。相传东晋陶渊明的《桃花源记》就是以这里为背景的。\n\n史载张旭曾为常熟尉，后人京官拜金吾长史，并无确证说他曾到过桃花溪，但这并不妨碍诗人创作。因为经过南北朝、隋直到唐代，由于《桃花源记》的广泛流传和对陶渊明隐逸情怀、高洁人格的认同和追慕，“桃花源”已成为世人精神世界和文化谱系...", "authors": ["唐磊"], "pressName": "崇文书局"}]', '蘅塘退士：四句抵得上一篇《桃花源记》。', 'center', 1417644960, '57b8f9ccd342d3005ac6f936', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639337, '水浒传 · 第六十九回 · 东平府误陷九纹龙 宋公明义释双枪将', NULL, 0, 124, 0, 1, '施耐庵', NULL, 10333, '57b9ebb3a633bd005d30998b', '明', 'wen', '文', '', '', '诗曰：
神龙失势滞飞升，得遇风雷便不情。
豪杰相逢鱼得水，英雄际会弟投兄。
千金伪买花娘俏，一让能成俊义名。
水战火攻人罕敌，绿林头领宋公明。
话说当下梁山泊忠义堂上，宋江打了曾头市，卢俊义捉得史文恭，祭献晁天王已了，宋江不负晁盖遗言，要把主位让与卢员外，众人不服。宋江又道：“如此众志不定，于心不安。目今山寨钱粮缺少，梁山泊东有两个州府，却有钱粮。一处是东平府，一处是东昌府。我们自来不曾搅扰他那里百姓。今去问他借粮，公然不肯。今写下两个阄儿，我和卢员外各拈一处。如先打破城子的，便做梁山泊主。如何？”吴用道：“也好。听从天命。”卢俊义道：“休如此说。只是哥哥为梁山泊之主，某听从差遣。”此时不由卢俊义，当下便唤铁面孔目裴宣写下两个阄儿。焚香对天祈祷已罢，各拈一个。宋江拈着东平府，卢俊义拈着东昌府。众皆无语。
当日设筵，饮酒中间，宋江传令调拨人马。宋江部下：林冲、花荣、刘唐、史进、徐宁、燕顺、吕方、郭盛、韩滔、彭玘、孔明、孔亮、解珍、解宝、王矮虎、一丈青、张青、孙二娘、孙新、顾大嫂、石勇、郁保四、王定六、段景住，大小头领二十五员，马步军兵一万，水军头领三员，阮小二、阮小五、阮小七，领水军驾船接应。卢俊义部下：吴用、公孙胜、呼延灼、朱仝、雷横，索超、关胜、杨志、单廷圭、魏定国、宣赞、郝思文、燕青、杨林、欧鹏、凌振、马麟、邓飞、施恩、樊瑞、项充、李衮、时迁、白胜，大小头领二十五员，马步军兵一万，水军头领三员，李俊、童威、童猛，引水手驾船策应。其余头领并中伤者，看守寨栅。宋江分俵已定。此是一时进兵，去打两处州郡。有诗为证：
尧舜推贤万古无，禹汤传后亦良图。
谁知聚啸山林者，揖让谦恭有盛谟。
且说宋江与众头领去打东平府，卢俊义与众头领去打东昌府，众多头领各自下山。此是三月初一日的话。日暖风和，草青沙软，正好厮杀。
却说宋江领兵前到东平府，离城只有四十里路，地名安山镇，扎住军马。宋江道：“东平府太守程万里和一个兵马都监，乃是河东上党郡人氏。此人姓董名平，善使双枪，人皆称为双枪将。有万夫不当之勇。虽然去打他城子，也和他通些礼数，差两个人，赍一封战书去那里下。若肯归降，免致动兵。若不听从，那时大行杀戮，使人无怨。谁敢与我先去下书？”只见部下走过一人，身长一丈，腰阔数围。那人是谁？有诗为证：
不好资财惟好义，貌似金刚离古寺。
身长唤做险道神，此是青州郁保四。
郁保四道：“小人认得董平，情愿赍书去下。”又见部下转过一人，瘦小身材，叫道：“我帮他去。”那人是谁？有诗为证：
蚱蜢头尖光眼目，鹭鹚瘦腿全无肉。
路遥行走疾如飞，扬子江边王定六。
这两个便道：“我们不曾与山寨中出得些气力，今情愿去走一遭。”宋江大喜，随即写了战书与郁保四、王定六两个去下。书上只说借粮一事。
且说东平府程太守，闻知宋江起军马到了安山镇住扎，便请本州兵马都监双枪将董平商议军情重事。正坐间，门人报道：“宋江差人下战书。”程太守教唤至。郁保四、王定六当府厮见了，将书呈上。程万里看罢来书，对董都监说道：“要借本府钱粮，此事如何？”董平听了大怒，叫推出去即便斩首。程太守谏道：“不可！自古两国争战，不斩来使。于礼不当。只将二人各打二十讯棍，发回原寨，看他如何？”董平怒气未息，喝把郁保四、王定六一索捆翻，打得皮开肉绽，推出城去。两个回到大寨，哭告宋江说：“董平那厮无理，好生眇视大寨！”
宋江见打了两个，怒气填胸，便要平吞州郡。先叫郁保四、王定六上车，回山将息。只见九纹龙史进起身说道：“小弟旧在东平府时，与院子里一个娼妓有染，唤做李瑞兰，往来情熟。我如今多将些金银，潜地入城，借他家里安歇。约定时日，哥哥可打城池。只等董平出来交战，我便扒去更鼓楼上放起火来，里应外合，可成大事。”宋江道：“最好！”史进随即收拾金银，安在包袱里，身边藏了暗器，拜辞起身。宋江道：“兄弟善觑方便。我且顿兵不动。”
且说史进转入城中，径到西瓦子李瑞兰家。大伯见是史进，吃了一惊，接入里面，叫女儿出来厮见。李瑞兰生的甚是标格出尖。有诗为证：
万种风流不可当，梨花带雨玉生香。
翠禽啼醒罗浮梦，疑是梅花靓晓妆。
李瑞兰引去楼上坐了，遂问史进道：“一向如何不见你头影？听的你在梁山泊做了大王，官司出榜捉你。这两日街上乱哄哄地说宋江要来打城借粮，你如何却到这里？”史进道：“我实不瞒你说：我如今在梁山泊做了头领，不曾有功。如今哥哥要来打城借粮，我把你家备细说了。如今我特地来做细作，有一包金银相送与你，切不可走透了消息。明日事完，一发带你一家上山快活。”李瑞兰葫芦提应承，收了金银，且安排些酒肉相待，却来和大娘商量道：“他往常做客时，是个好人，在我家出入不妨。如今他做了歹人，倘或事发，不是耍处。”大伯说道：“梁山泊宋江这伙好汉，不是好惹的。但打城池，无有不破。若还出了言语，他们有日打破城子入来，和我们不干罢！”虔婆便骂道：“老蠢物！你省得甚么人事！自古道：蜂刺入怀，解衣去赶。天下通例，自首者即免本罪。你快去东平府里首告，拿了他去，省得日后负累不好。”李公道：“他把许多金银与我家，不与他担些干系，买我们做甚么？”虔婆骂道：“老畜生！你这般说，却似放屁！我这行院人家，坑陷了千千万万的人，岂争他一个！你若不去首告，我亲自去衙前叫屈，和你也说在里面！”李公道：“你不要性发，且教女儿款住他，休得打草惊蛇，吃他走了。待我去报与做公的，先来拿了，却去首告。”
且说史进见这李瑞兰上楼来，觉得面色红白不定。史进便问道：“你家莫不有甚事，这般失惊打怪？”李瑞兰道：“却才上胡梯踏了个空，争些儿吃了一跤，因此心慌撩乱。”史进虽是英勇，又吃他瞒过了，更不猜疑。有诗为证：
可叹虔婆伎俩多，粉头无奈苦教唆。
早知暗里施奸狡，错用黄金买笑歌。
当下李瑞兰相叙间阔之情。争不过一个时辰，只听得胡梯边脚步响，有人奔上来。窗外呐声喊，数十个做公的抢到楼上。史进措手不及，正如鹰拿野雀，弹打斑鸠，把史进似抱头狮子绑将下楼来，径解到东平府里厅上。程太守看了大骂道：“你这厮胆包身体，怎敢独自个来做细作！若不是李瑞兰父亲首告，误了我一府良民。快招你的情由，宋江教你来怎地？”史进只不言语。董平便道：“两边公吏狱卒牢子，这等贼骨头，不打如何肯招！”程太守喝道：“与我加力打这厮！”又将冷水来喷，两边腿上各打一百大棍。史进由他拷打，不招实情。董平道：“且把这厮长枷木杻，送在死囚牢里，等拿了宋江，一并解京施行。”
却说宋江自从史进去了，备细写书与吴用知道。吴用看了宋公明来书，说史进去娼妓李瑞兰家做细作，大惊。急与卢俊义说知，连夜来见宋江，问道：“谁叫史进去来？”宋江道：“他自愿去。说这李行首是他旧日的表子，好生情重，因此前去。”吴用道：“兄长欠这些主张。若吴某在此，决不叫去。常言道：娼妓之家，讳‘者扯丐漏走’五个字。得便熟闲，迎新送旧，陷了多少才人。更兼水性，无定准之意，纵有恩情，也难出虔婆之手。此人今去，必然吃亏。”宋江便问吴用请计。吴用便叫顾大嫂：“劳烦你去走一遭。可扮做贫婆，潜入城中，只做求乞的。若有些动静，火急便回。若是史进陷在牢中，你可去告狱卒，只说有旧情恩念，我要与他送一口饭。捵入牢中，暗与史进说知：‘我们月尽夜黄昏前后，必来打城。你可就水火之处，安排脱身之计。’月尽夜，你就城中放火为号。此间进兵方好成事。——兄长可先打汶上县，百姓必然都奔东平府。却叫顾大嫂杂在数内，乘势入城，便无人知觉。”吴用设计已罢，上马便回东昌府去了。宋江点起解珍、解宝，引五百余人攻打汶上县。果然百姓扶老挈幼，鼠窜狼奔，都奔东平府来。有诗为证：
史进怆惶已就擒，当官拷掠究来音。
若非顾媪通消息，怎救圜中万死身。
欲避兵戈，逃生匿迹，合城纷扰，都不在话下。却说顾大嫂头髻蓬松，衣服蓝缕，杂在众人里面，捵入城来，绕街求乞。到于衙前，打听得果然史进陷在牢中，方知吴用智亮如神。次日，提着饭罐，只在司狱司前往来伺候。见一个年老公人从牢里出来，顾大嫂看着便拜，泪下如雨。那年老公人问道：“你这贫婆哭做甚么？”顾大嫂道：“牢中监的史大郎，是我旧的主人，自从离了，又早十年。只说道在江湖上做买卖，不知为甚事陷在牢里。眼见得无人送饭，老身叫化得这一口儿饭，特要与他充饥。哥哥怎生可怜见，引进则个，强如造七层宝塔。”那公人道：“他是梁山泊强人，犯着该死的罪。谁敢带你入去。”顾大嫂道：“便是一刀一剐，自教他瞑目而受。只可怜见引老身入去送这口儿饭，也显得旧日之情。”说罢又哭。那老公人寻思道：“若是个男子汉，难带他入去。一个妇人家有甚利害？”当时引顾大嫂直入牢中来，看见史进项带沉枷，腰缠铁索。史进见了顾大嫂，吃了一惊，则声不得。顾大嫂一头假啼哭，一头喂饭。别的节级便来喝道：“这是该死的歹人！狱不通风，谁放你来送饭？即忙出去，饶你两棍！”顾大嫂见监牢内人多，难说备细，只说得：“月尽夜打城，叫你牢中自挣扎。”史进再要问时，顾大嫂被小节级打出牢门。史进只记得“月尽夜”。
原来那个三月却是大尽。到二十九，史进在牢中与两个节级说话，问道：“今朝是几时？”那个小节级却错记了，回说道：“今朝是月尽夜，晚些买贴孤魂纸来烧。”史进得了这话，巴不得晚。一个小节级吃的半醉，带史进到水火坑边。史进哄小节级道：“背后的是谁？”赚得他回头，挣脱了枷。只一枷梢，把那小节级面上正着一下，打倒在地。就拾砖头敲开木杻，睁着鹘眼，抢到亭心里。几个公人都酒醉了，被史进迎头打着，死的死了，走的走了。拔开牢门，只等外面救应。又把牢中应有罪人尽数放了，总有五六十人，就在牢内发喊起来，一齐走了。有人报知太守。程万里惊得面如土色，连忙便请兵马都监商议。董平道：“城中必有细作，且差多人围困了这贼！我却乘此机会，领军出城去捉宋江。相公便紧守城池，差数十个人围定牢门，休教走了。”董平上马点军去了。程太守便点起一应节级、虞候、押番，各执枪棒，去大牢前呐喊。史进在牢里不敢轻出。外厢的人又不敢进去。顾大嫂只叫得苦。
却说都监董平，点起兵马，四更上马，杀奔宋江寨来。伏路小军报知宋江。宋江道：“此必是顾大嫂在城中又吃亏了。他既杀来，准备迎敌！”号令一下，诸军都起。当时天色方明，却好接着董平军马，两下摆开阵势。董平出马，真乃英雄盖世，谋勇过人。有诗为证：
两面旗牌耀日月，简银铁铠似霜凝。
水磨凤翅头盔白，锦绣麒麟战袄青。
一对白龙争上下，两条银蟒递飞腾。
河东英勇风流将，能使双枪是董平。
原来董平心灵机巧，三教九流，无所不通，品竹调弦，无有不会。山东、河北皆号他为风流双枪将。宋江在阵前，看了董平这表人品，一见便喜。又见他箭壶中插一面小旗，上写一联道：“英勇双枪将，风流万户侯”。宋江随即遣韩滔出马迎敌。韩滔得令，手执铁槊，直取董平。董平那对铁枪，神出鬼没，人不可当。宋江再教金枪手徐宁，仗钩镰枪前去交战，替回韩滔。徐宁得令，飞马便出，接住董平厮杀。两个在征尘影里，杀气丛中，斗到五十余合，不分胜败。交战良久，宋江恐怕徐宁有失，便教鸣金收军。徐宁勒马回来。董平手举双枪，直追杀入阵来。宋江鞭梢一展，四下军兵一齐围住。宋江勒马，上高阜处看望，只见董平围在阵内。他若投东，宋江便把号旗望东指，军马向东来围他。他若投西，号旗便望西指，军马便向西来围他。董平在阵中横冲直撞，两枝枪，直杀到申牌已后，冲开条路，杀出去了。宋江不赶董平，驱兵大进。董平因见交战不胜，当晚收军回城去了。宋江连夜起兵，直抵城下，团团调兵围住。顾大嫂在城中未敢放火，史进又不得出来，两下拒住。
原来程太守有个女儿，十分大有颜色。董平无妻，累累使人去求为亲，程万里不允。因此日常间有些言和意不和。董平当晚领军入城，其日，使个就里的人，乘势来问这头亲事。程太守回说：“我是文官，他是武官，相赘为婿，正当其理。只是如今贼寇临城，事在危急，若还便许，被人耻笑。待得退了贼兵，保护城池无事，那时议亲，未为晚矣。”那人把这话却回复董平，董平虽是口里应道：“说得是。”只是心中踌躇，不十分欢喜。恐怕他日后不肯。
这里宋江连夜攻城得紧，太守催请出战。董平大怒，披挂上马，带领三军出城交战。宋江亲在阵前门旗下喝道：“量你这个寡将，怎敢当吾！岂不闻古人有言：大厦将倾，非一木可支。你看我手下雄兵十万，猛将千员，替天行道，济困扶危。早来就降，免受一死。”董平大怒，回道：“文面小吏，该死狂徒，怎敢乱言！”说罢，手举双枪，直奔宋江。左有林冲，右有花荣，两将齐出，各使军器，来战董平。约斗数合，两将便走，宋江军马佯败，四散而奔。董平要逞功劳，拍马赶来。宋江等却好退到寿张县界。宋江前面走，董平后面追。离城有十数里，前至一个村镇，两边都是草屋，中间一条驿道。董平不知是计，只顾纵马赶来。宋江因见董平了得，隔夜已使王矮虎、一丈青、张青、孙二娘四个，带一百余人，先在草屋两边埋伏，却拴数条绊马索在路上，又用薄土遮盖，只等来时鸣锣为号，绊马索齐起，准备捉这董平。董平正赶之间，来到那里，只听得背后孔明、孔亮大叫：“勿伤吾主！”恰好到草屋前，一声锣响，两边门扇齐开，拽起绳索。那马却待回头，背后绊马索齐起，将马绊倒，董平落马。左边撞出一丈青、王矮虎，右边走出张青、孙二娘，一齐都上，把董平捉了。头盔、衣甲、双枪、只马，尽数夺了。两个女头领，将董平捉住，用麻绳背剪绑了。两个女将各执钢刀，监押董平来见宋江。
却说宋江过了草房，勒住马，立在绿杨树下，迎见这两个女头领解着董平。宋江随即喝退两个女将：“我教你去相请董将军，谁教你们绑缚他来！”二女将喏喏而退。宋江慌忙下马，自来解其绳索，便脱护甲锦袍与董平穿着，纳头便拜。董平慌忙答礼。宋江道：“倘蒙将军不弃微贱，就为山寨之主。”董平答道：“小将被擒之人，万死犹轻。若得容恕安身，实为万幸！”宋江道：“敝寨地连水泊，素无扰害。今为缺少粮食，特来东平府借粮，别无他意。”董平道：“程万里那厮，原是童贯门下门馆先生，得此美任，安得不害百姓。若是兄长肯容董平，今去赚开城门，杀入城中，共取钱粮，以为报效。”宋江大喜，便令一行人将过盔甲枪马，还了董平，披挂上马。董平在前，宋江军马在后，卷起旗幡，都到东平城下。董平军马在前，大叫：“城上快开城门！”把门军士将火把照时，认得是董都监，随即大开城门，放下吊桥。董平拍马先入，砍断铁锁，背后宋江等长驱人马杀入城来。都到东平府里。急传将令，不许杀害百姓，放火烧人房屋。董平径奔私衙，杀了程太守一家人口，夺了这女儿。宋江先叫开放大牢，救出史进。便开府库，尽数取了金银财帛，大开仓廒，装载粮米上车，先使人护送去梁山泊金沙滩，交割与三阮头领，接递上山。史进自引人去西瓦子里李瑞兰家，把虔婆老幼，一门大小，碎尸万段。宋江将太守家私，俵散居民，仍给沿街告示，晓谕百姓：“害民州官，已自杀戮。汝等良民，各安生理。”告示已罢，收拾回军。
大小将校再到安山镇，只见白日鼠白胜飞奔前来，报说东昌府交战之事，虚实胜败。宋江听罢，神眉剔竖，怪眼圆睁，大叫：“众多兄弟，不要回山，且跟我来，再去这个去处降兵捉将！”正是：再施忠义轻舒手，复夺资储锦绣城。毕竟宋江再引军马投何处来，且听下回分解。', '', '', '', NULL, '', 'indent', 1537289269, '5ba0b7b7570c3500638aa848', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10645, '湘口送友人', NULL, 209, 206, 1, 2, '李频', NULL, 10154, '57bb187a165abd006628abc1', '唐', 'shi', '诗', 'http://baike.baidu.com/view/8826443.htm', '', '中流欲暮见湘烟，岸苇无穷接楚田。
去雁远冲云梦雪，离人独上洞庭船。
风波尽日依山转，星汉通霄向水悬。
零落梅花过残腊，故园归醉及新年。', '此诗以写景见长，诗人把孤舟离人放在中心的位置上，围绕这个中心层层设景；又从孤舟离人逗出情思，把诸多景物有机地串联起来。全诗显得章法齐整，中心突出，而且融情入景，情景交融，与一味作感伤语的送别诗不同，自有一番悠悠远思的风韵。', '岸苇：一传作“苇岸”。
楚：湘江流域在古时候为楚国的属地，故称楚。
田：一作“天”。
去雁：北飞的大雁。
云梦：云梦泽，在今洞庭湖北岸，湖南、湖北两省境内。
雪：一作“泽”。
转：指友人所乘之船，终日在风浪中行转。
星汉：银河。
向水悬：“悬”一传作“连”。
零落梅花过残腊：一作“回首羡君偏有我”。
腊：腊月，阴历十二月。
归醉及新年：一作“归去又新年”，一作“归去醉新年”。
醉：沉浸。', '傍晚时分，湘江水流在暮霭的笼罩之下更加浩渺，两岸漫无边际的芦苇连接着广袤的田野。严冬快要过去了，大雁冲起云梦泽的积雪，准备往北飞去了。在这样的日子里，友人来到洞庭湖边登上了北去的航船。友人归去，一路上将日夜兼程。白天劈波斩浪，顺着水势依山而转；夜里仰望星河，望着星空笼罩着浩瀚的洞庭湖面。梅花凋零腊月将尽，友人回到家刚好赶上新年，与家人团聚将是多么幸福啊。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92e234a8757d5a0e1e61", "shortContent": "这是一首送别诗。“湖”，指洞庭湖，诗人即在湘江入洞庭湖的渡口送别友人。全诗大半写景，不见伤别字面，只是将一片离情融入景中。\n一、二两联写“湖口”所见：先是放眼湘江水岸，看到暮霭、芦苇、田野；接着远眺云梦，但见飞雪、去雁；最后注目孤舟离人。诗的前三句，境界阔大，气象雄浑。“中流欲暮见湘烟”，“中流”即江心，这是江面宽阔的地方，此时在暮霭的笼罩下更显得苍苍莽莽。“岸苇无穷接楚田”，“楚田”即田野，春秋...", "authors": ["周锡炎"], "pressName": "上海辞书出版社"}]', '《唐诗选脉会通评林》：周弼列为四虚体。徐用吾曰：清新可爱，次联尽有意思。吴山民曰：起直景，第四句“独上”有情。唐汝询曰：“离人独上”语稍佳，恨援“去雁”作对。
《删订唐诗解》：吴昌棋曰：诗在君平、君虞之间。三、四言雁以群飞，人惟独往。五、六言洞庭之远而阔。结言岁暮未能到家也。
《五朝诗善鸣集》：风神奕奕。
《唐诗评选》：成响不杂（首句下）。
《唐诗摘钞》：起写别景，所以伤离。五、六写舟中景，所以怀远。七写客中景，所以自悲。三句虽系衬景，作者意谓己在羁旅，今日眼中所见，不惟有归人，且有去雁，如之何己独在羁旅耶？此名写景，而实写情；若与上二句例观，便不成章法矣。一本作“回首羡君偏有我，故园归醉及新年”，则诗意尽露，不见法度矣。
《贯华堂选批唐才子诗》：一句是面前湘江，二句是江之隔岸，三句是极望前途。由面前，而隔岸，而极望，盖先默忖别事，悄窥船势，一递一递，转远转远。然则此间斗地分手，便是杳不相见，而如之何可以放离人独上船也。看他一解，先次第写一、二、三句，下独接第四一句，又一斩新章法（首四句下）。前解写未上洞庭船已前，此解写既上洞庭船已后也。“风波尽日”，是写洞庭船昼行；“星汉通霄”，是写洞庭船夜行。七、八，言如此昼夜兼行，则冬春之交必得到家，然而独奈我何哉（末四句下）。
《唐三体诗评》：发端画出“独”字。第三用反衬，为添毫极貌孤穷之况。送别诗，六句剧道行路险艰，落句忽然翻转，可谓蹈险争奇手也。
《碛砂唐诗》：敏曰：“离人独上洞庭船”七字，含蓄无限情思。细观其妙：洞庭渺渺，烟波孤棹，当其天涯落落，行李长征，只用“独上”二字衬出。
《唐体肤诠》：地经楚服，即效楚吟，触景兴怀，情味无限。刘文房之《岳阳》、卢允言之《鄂州》，得此而三矣。
《唐诗贯珠》：此是中流送别，非陆路分手。起处幽情寓思，精妙之极。
《唐诗成法》：先写湘水连天，为下离人独往凄凉一衬。又用“去雁”一陪，况涉洞庭之远险，为新年始到起。以“去雁”承“楚天”，以“云梦雪”点时，以“洞庭”承“苇岸”，以“尽日”承暮前，以“通宵”承暮后，以“风波”、“向水”承“中流”，以“梅花”、“残腊”遥应“雪”字，以“及新年”伤己之未能归在言外。
《唐诗别裁》：犹近大历十子。
《唐贤清雅集》：天骨开张，气魄甚大，自是唐季好手。
《唐贤小三昧集续集》：飘然欲仙，只此一语便是妙绝（首句下）', 'center', 1417610847, '57b90c54165abd0054c02af3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10646, '春怨', NULL, 254, 1, 2, 2, '金昌绪', NULL, 10155, '57baf6877db2a20068c7fbc8', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383736/6393765.htm', '', '打起黄莺儿，莫教枝上啼。
啼时惊妾梦，不得到辽西。', '这首诗运用层层倒叙的手法，描写一位女子对远征辽西的丈夫的思念。首句写妇女“打起黄莺”的动作，次句写“打起”的原因是“莫教啼”，三句写“莫教啼”的目的是不使其“惊妾梦”，四句又写“妾梦”是到辽西会见丈夫。全诗意蕴深刻，构思新巧，独具特色。', '春怨：一题“伊州歌”。
打起：打得飞走。
莫教：不让。
妾：女子的自称。
辽西：大约指唐代辽河以西营州、燕州一带地方。即今辽宁省锦州、朝阳至北京市东北怀柔、顺义一带，隋代因秦汉旧名曾于此地置辽西郡，寄治于营州，唐初改曰燕州，州治在辽西县。', '我敲打树枝把黄莺儿赶走，
不让它在那里声声啼鸣。
鸣声会惊破我的好梦，
到不了辽西去会见亲人。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92eb34a8757d5a0e1e99", "shortContent": "这首诗，语言生动活泼，具有民歌色彩，而且在章法上还有其与众不同的特点：它通篇词意联属，句句相承，环环相扣，四句诗形成了一个不可分割的整体，达到了清王夫之在《夕堂永日绪论》中为五言绝句提出的“就一意圆净成章”的要求。这一特点，人所共称。明谢榛在《四溟诗话》中曾把诗的写法分为两种：一种是“一句一意”，“摘一句亦成诗”，如杜甫诗“日出篱东水，云生舍北泥。竹高鸣翡翠，沙僻舞鹍鸡”（《绝句六首》之一），属于...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9ae60d368fd3d13b", "shortContent": "这首诗，语言生动活泼，具有民歌色彩，而且在章法上还有其与众不同的特点：它通篇词意联属，句句相承，环环相扣，四句诗形成了一个不可分割的整体，达到了清王夫之在《夕堂永日绪论》中为五言绝句提出的“就一意圆净成章”的要求。这一特点，人所共称。明谢榛在《四溟诗话》中曾把诗的写法分为两种：一种是“一句一意”，“摘一句亦成诗”，如杜甫诗“日出篱东水，云生舍北泥。竹高鸣翡翠，沙僻舞鹍鸡”（《绝句六首》之一），属于...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f449761253910e903a4", "shortContent": "这首诗记录了一位思妇春日睡醒时的一段愁怀离绪。这愁绪是由黄莺引发的，诗境便围绕黄莺展开。首句“打起黄莺儿”如奇峰陡起，造成一个悬念。尽人皆知，黄莺本是春天的使者，它飞来飞去，为春天唱着赞歌，十分逗人喜爱。今天偶尔停在这位诗中人庭树枝头上，既无老鹰捕捉小鸡的歹念，又不似鸱鸱预示什么不祥，可以说哪一点也不会惹着谁，而诗中人却要“打起黄莺儿”，真不太近情理了。有了这个悬念，读者便急于弄个明白，究竟是怎么...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707de6f69b71e93f6310", "shortContent": "这首诗记录了一位思妇春日睡醒时的一段愁怀离绪。这愁绪是由黄莺引发的，诗境便围绕黄莺展开。首句“打起黄莺儿”如奇峰陡起，造成一个悬念。尽人皆知，黄莺本是春天的使者，它飞来飞去，为春天唱着赞歌，十分逗人喜爱。今天偶尔停在这位诗中人庭树枝头上，既无老鹰捕捉小鸡的歹念，又不似鸱鸮预示什么不祥，可以说哪一点也不会惹着谁，而诗中人却要“打起黄莺儿”，真不太近情理了。有了这个悬念，读者便急于弄个明白，究竟是怎么...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312716473206168b2e02301", "shortContent": "这首诗记录了一位思妇春日睡醒时的一段愁怀离绪。这愁绪是由黄莺引发的，诗境便围绕黄莺展开。首句“打起黄莺儿”如奇峰陡起，造成一个悬念。尽人皆知，黄莺本是春天的使者，它飞来飞去，为春天唱着赞歌，十分逗人喜爱。今天偶尔停在这位诗中人庭树枝头上，既无老鹰捕捉小鸡的歹念，又不似鸱鸮预示什么不祥，可以说哪一点也不会惹着谁，而诗中人却要“打起黄莺儿”，真不太近情理了。有了这个悬念，读者便急于弄个明白，究竟是怎么...", "authors": ["杨军"], "pressName": "崇文书局"}]', '', 'center', 1418812980, '57b94d2b7db2a20054293f0c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10647, '哥舒歌', NULL, 150, 1, 1, 1, '西鄙人', NULL, 11760, '5858e6c261ff4b006875c5e7', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383737.htm', '', '北斗七星高，哥舒夜带刀。
至今窥牧马，不敢过临洮。', '这是西域边境人民歌颂哥舒翰战功的诗。诗以北斗起兴，喻哥舒翰的功高；以胡人“至今”“不敢”南下牧马，喻哥舒翰功劳的影响深远。全诗内容平淡素雅，音节铿锵和顺，既有民歌的自然流畅，又不失五言诗的典雅逸秀。所以，沈德潜说：“与《敕勒歌》同是天籁，不可以工拙求之。”然而，即使以工拙求之之，难道就失其俊美感人吗？', '哥舒：指哥舒翰，是唐玄宗的大将，突厥族哥舒部的后裔。哥舒是以部落名称作为姓氏。《全唐诗》题下注：“天宝中，哥舒翰为安西节度使，控地数千里，甚著威令，故西鄙人歌此。”
北斗七星：大熊座的一部分。
窥：窃伺。牧马：指吐蕃越境放牧，指侵扰活动。
临洮：今甘肃省洮河边的岷县。一说今甘肃省临潭县。秦筑长城西起于此。', '黑夜里北斗七星挂得高高，哥舒翰勇猛守边夜带宝刀。
吐蕃族至今牧马只敢远望，他们再不敢南来越过临洮。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f449761253910e903a5", "shortContent": "西鄙人，泛指西北边镇百姓。此诗是唐代西北边民对唐朝名将哥舒翰的颂歌，约作于唐玄宗天宝十二年（753）间。时值陇右节度使哥舒翰领兵大破吐蕃，以致“吐蕃屏足不敢近青海”，因而有民谣说：“北斗七星高，哥舒夜带刀。吐蕃总杀却，更筑两重壕。”此诗即为对这首民谣进行艺术加工后的作品。\n\n首句以北斗起兴，用天空高悬的北斗七星，象征哥舒翰的功高震世，为万人景仰。古人所称之“北斗”，其涵意源于两处：一是从天象学来说...", "authors": ["乐云"], "pressName": "崇文书局"}]', '凌宏宪《唐诗广选》：气骨高劲，不域于中唐者。
李攀龙《唐诗训解》：为中国长气。
周珽《唐诗选脉会通评林》：唐汝询曰：哥舒御吐蕃，信悍勇。潼关之败，髦矣。此歌盖不欲以一眚掩之。
沈德潜《唐诗别裁》：与《敕勒歌》同是天籁，不可以工拙求之。
蘅塘退士《唐诗三百首》：先着此五字，比兴极奇（首句下）。
俞陛云《诗境浅说续编》：《诗三百篇》，无作者姓氏，天怀陶写，不以诗鸣，而诗传千古。三代下唯恐不好名，汉魏以降，作者林立矣……此西鄙之人，姓氏湮没，而高歌慷慨，与“敕勒川，阴山下”之歌，同是天籁。如风高大漠，古戍闻笳，令壮心飞动也。首句排空疾下，与卢纶之“月黑雁飞高”皆工干发端，惟卢诗含意不尽，此诗意尽而止，各极其妙。', 'center', 1417611100, '57b8e214d342d3005ac6858d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10648, '长干行 其一', NULL, 278, 46, 1, 3, '崔颢', NULL, 10093, '57b9a826a633bd005d2e2d61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/9135287.htm', '', '君家何处住，妾住在横塘。
停船暂借问，或恐是同乡。', '此诗为男女相悦的问答诗，恰如民歌中的对唱。以白描手法，朴素自然的语言，刻划了一对经历相仿，萍水相逢的男女的相识恨晚之情。清脆洗练，玲珑剔透，天真无邪，富有魅力。', '长干行：乐府曲名。是长干里一带的民歌，长干里在今江苏省南京市南面。
君：古代对男子的尊称。
妾：古代女子自称的谦词。
横塘：现江苏省南京市江宁区。
暂：暂且、姑且。
借问：请问一下。
或恐：也许。', '请问大哥你的家在何方。我家是住在建康的横塘。
停下船吧暂且借问一声，听口音恐怕咱们是同乡。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92a3911759740c9b1a53", "shortContent": "这两首抒情诗抓住了人生片断中富有戏剧性的一刹那，用白描的手法，寥寥几笔，就使人物、场景跃然纸上，栩栩如生。它不以任何色彩映衬，似墨笔画；它不用任何妆饰烘托，是幅素描；它不凭任何布景借力，犹如一曲男女声对唱；它截头去尾，突出主干，又很像独幕剧。题材是那样地平凡，而表现手法却是那样地不平凡。\n先看第一首的剪裁：一个住在横塘的姑娘，在泛舟时听到邻船一个男子的话音，于是天真无邪地问一下：你是不是和我同乡？...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac9ae60d368fd3d110", "shortContent": "这两首抒情诗抓住了人生片断中富有戏剧性的一刹那，用白描的手法，寥寥几笔，就使人物、场景跃然纸上，栩栩如生。它不以任何色彩映衬，似墨笔画；它不用任何妆饰烘托，是幅素描；它不凭任何布景借力，犹如一曲男女声对唱；它截头去尾，突出主干，又很像独幕剧。题材是那样地平凡，而表现手法却是那样地不平凡。\n\n先看第一首的剪裁：一个住在横塘的姑娘，在泛舟时听到邻船一个男子的话音，于是天真无邪地问一下：你是不是和我同乡...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127053e6f69b71e93f627c", "shortContent": "长干里，在南京秦淮河南岸今雨花台至长干桥一带。长干居民往来水上，衍生出如许动人的情怀和歌吟，为六朝乐府的成型奠定了深厚的民间基础。所谓《长干曲》，是乐府《杂曲歌辞》调名，原为长江下游一带民歌，内容多写江上渔家生活。崔颢这两首诗继承了前代民歌的遗风，但这两首“爱情诗”既不艳丽柔媚，也非浪漫热烈，女主角情怀的吐露到“或恐是同乡”为止，男主角的回应也以“生小不相识”为限，风格朴素真率、干净健康。\n\n茫茫...", "authors": ["易文翔"], "pressName": "崇文书局"}]', '', 'center', 1417611939, '57ba3e9c2e958a006935beec', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10649, '长干行 其二', NULL, 65, 46, 0, 1, '崔颢', NULL, 10093, '57b9a826a633bd005d2e2d61', '唐', 'shi', '诗', 'http://baike.baidu.com/view/8905737.htm', '', '家临九江水，来去九江侧。
同是长干人，生小不相识。', '此诗为男女相悦的问答诗，恰如民歌中的对唱。以白描手法，朴素自然的语言，刻划了一对经历相仿，萍水相逢的男女的相识恨晚之情。清脆洗练，玲珑剔透，天真无邪，富有魅力。', '长干行：乐府曲名。是长干里一带的民歌，长干里在今江苏省南京市南面。
临：靠近。
九江：今江西九江市。
长干：地名，在今江苏江宁县。
生小：自小，从小时候起。', '', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f449761253910e903a8", "shortContent": "秦淮河两岸，是距今三千至五千年前的南京居民生息繁衍的所在。长干里，就在秦淮河南岸今雨花台至长干桥一带。长干居民往来水上，衍生了如许动人的情怀和歌吟，为六朝乐府的成型奠定了深厚的民间基础。所谓《长干曲》，便是乐府《杂曲歌辞》调名，原为长江下游一带民歌，内容多写江上渔家生活。崔颢这两首诗继承了前代民歌的遗风，但这两首“爱情诗”既不艳丽柔媚，也非浪漫热烈，女主角情怀的吐露到“或恐是同乡”为止，男主角的回...", "authors": ["易文翔"], "pressName": "崇文书局"}]', '诗的语言朴素自然，有如民歌。民歌中本有男女对唱的传统，在《乐府诗集》中就称为“相和歌辞”。所以第一首女声起唱之后，就是男主角的答唱了。“家临九江水”答复了“君家何处住”的问题；“来去九江侧”说明自己也是风行水宿之人，不然就不会有这次的萍水相逢。这里初步点醒了两人的共同点。“同是长干人”落实了姑娘“或恐是同乡”的想法，原来老家都是建康（今江苏南京）长干里。一个“同”字把双方的共同点又加深了一层。这三句是男主角直线条的口吻。现在只剩最后一句了:只有五个字，该如何着墨？如用“今日得相识”之类的幸运之辞作结束，未免失之平直。诗人终于转过笔来把原意一翻，与其说今日之幸而相识，倒不如追惜往日之未曾相识。
《长干曲》是南朝乐府中“杂曲古辞”的旧题。崔颢这首诗继承了前代民歌的遗风，但既不是艳丽而柔媚，又非浪漫而热烈，却以素朴真率见长，写得干净健康。针对第一首诗女主角的抒怀只到“或恐是同乡”为止，男主角的表情在本诗中只以“生小不相识”为限。这样的蕴藉无邪，是抒情诗中的上乘。（沈熙乾）', 'center', 1417611934, '57bc798a128fe1005f9a6d4c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10871, '翠楼吟', NULL, 13, 288, 3, 1, '姜夔', NULL, 10049, '57b97702a633bd006661948c', '宋', 'ci', '词', 'http://baike.baidu.com/view/2836588.htm', '淳熙丙午冬，武昌安远楼成，与刘去非诸友落之，度曲见志。余去武昌十年，故人有泊舟鹦鹉洲者，闻小姬歌此词，问之，颇能道其事；还吴，为余言之，兴怀昔游，且伤今之离索也。', '月冷龙沙，尘清虎落，今年汉酺初赐。新翻胡部曲，听毡幕元戎歌吹。层楼高峙，看槛曲萦红，檐牙飞翠。人姝丽，粉香吹下，夜寒风细。
此地宜有词仙，拥素云黄鹤，与君游戏。玉梯凝望久，叹芳草萋萋千里。天涯情味，仗酒祓清愁，花销英气。西山外，晚来还卷，一帘秋霁。', '此词为庆贺武昌安远楼落成之作。孝宗淳熙十三年（公元1186）姜夔离汉阳赴浙江湖州，途经武昌时作。上阕一开始便将高楼暂搁一旁，而将战地风光描写了一番。明月的冷光映照着寒冷的边塞沙碛，围护城堡四周的竹篱战尘静寂，今年朝廷开始赏赐臣民饮酒欢聚。弹奏起塞北的乐曲，听到元帅的军帐歌吹荡激。有了前面的龙沙虎落、毡幕元戎，“层楼”六句，写红槛翠檐，丽人粉香，则不觉气格纤弱。安远楼层层耸立，看它那红色栏杆萦绕环曲，翠碧楼檐飞展。那位小姬容貌艳丽，从她身上吹下阵阵粉香，寒夜里风儿轻轻细细。上片先写楼外，次写楼内。
下阕有“玉梯凝望”，但见“芳草萋萋千里”，意境亦是深远阔大。登上高楼久久地凝神望远，可叹芳草萋萋，绵绵千里。“天涯”三句，漂泊天涯的游子情怀凄寂，仗着酒力减轻闲愁，借着赏花消磨志气。迷惘变为凄厉，清丽变为悲壮，末以景结情，西山之外，黄昏时又卷起，一帘秋雨过後的晴丽，与篇首冷寂的静景相应，突出了本词登高沉思的主调。', '翠楼吟：词牌名，姜夔自度“双调”曲。
安远楼：即武昌南楼，在黄鹤楼上。
刘去非：作者友人，生平未详。
鹦鹉洲：在今湖北汉阳西南长江中，东汉末，黄祖为江夏（今武昌）太守，祖长子射，大会宾客，有人献鹦鹉，祢衡作《白鹦鹉赋》洲因此得名。
小姬：指年轻女子。
兴怀：引起感触。
离索：离群索居。
龙沙：《後汉书·班超传赞》：“坦步葱岭，咫尺龙沙。”後世泛指塞外之地为龙沙。
虎落：遮护城堡或营寨的竹篱。《汉书·鼂错传》：“要害之处，通川之道，调立城邑，毋下千家，为中周虎落。
汉酺（pú）初赐：汉律，三人以上无故不得聚饮，违者罚金四两。朝廷有庆祝之事，特许臣民会聚欢饮，称赐酺。《汉书·文帝纪》诏：“朕初即位，其赦天下，赐民爵一级，女子百户牛酒，酺五日。”後来历代王朝，遇新皇帝登位，帝后诞日，丰收，平定叛乱等事，常有赐酺之举。酺，合聚饮食。此处所指事见题解。
胡部曲：一种以琵琶为主的音乐。唐时西凉地方乐曲。《新唐书·礼乐志》：“开元二十四年（公元736年），升胡部于堂上……後又诏道调、法曲与胡部新声合作。”此处泛指异族音乐。
毡幕：指用毛毡制作的帐篷。
元戎：主将，军事长官。《汉书·董贤传》：“统辟无戎。”注：“元戎，大众也。”
高峙：高高耸立。
人姝丽：容貌美丽指漂亮的人。《後汉书·邓皇后纪》：“后长七尺二寸，姿颜姝丽，绝异于众。”
此地：崔颢《黄鹤楼》诗：“昔人已乘黄鹤去，此地空余黄鹤楼。黄鹤一去不见返，白云千载空悠悠。睛川历历汉阳树，芳草萋萋鹦鹉洲。日暮乡关何处是？烟波江上使人愁。”此处化用其意。
素云：指白云楼。
玉梯：指玉楼。
祓（fú）：原指古代为除灾去邪而举行仪式的习俗。此处指消除。
西山外：王勃《滕王阁诗》：“滕王高阁临江渚，佩玉鸣鸾罢歌舞。画栋朝飞南浦云，珠帘暮卷西山雨。闲云潭影日悠悠，物换星移几度秋。阁中帝子今何在？槛外长江空自流。”此处化用其意，一帘秋霁，“秋”字这修饰语，非实指，因作者游“安远楼”为冬季。
霁（jì）：雨後天晴。', '淳熙丙午年冬，武昌安远楼建成。我和刘去非等几位朋友去参加落成典礼。因此创作此首词。我离开武昌十年，有老朋友在鹦鹉洲泊舟住宿，听到年轻的歌女演唱这首词。我向她询问，她还能详细地讲述旧事。友人回到吴地，向我讲述了这件事。我听後怀念起昔日曾经同游的好友，更加为今日的孤单而感伤。
明月的冷光映照着边塞的风沙，围护城保四周的竹篱一片寂静。今年朝廷开始赏赐尘民饮酒欢聚。弹奏起塞北新曲，听到元帅的军帐歌声清越。安远楼耸立入云霄，看它那红色栏杆萦绕楼檐，飞展一片翠碧。那位佳人美丽动人，从她身体上飘散一股幽香，寒夜里风儿轻轻地吹。
就在此地，正该有潇洒的词友，像仙人一样，同登楼观蟾的朋友尽兴游戏。我一个人登上高楼久久地凝神望远，却只见芳草萋萋，绵绵不尽。飘泊天涯的游子，心中的孤苦有何人知道，只好借酒消愁，借着赏花忘记豪情。此刻西山之外，黄昏时又卷起，一帘秋雨过後的晴丽。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74f403572034f65963f5", "shortContent": "淳熙十三年丙午（1186）秋天，姜夔在汉阳府汉川县其姊家居住。入冬，武昌黄鹤山上新建成安远楼一座，词人偕友人刘去非（事迹不详）等前往参加落成典礼，自度此曲以纪其事。十年后，姜夔的朋友在汉阳江边还听到年轻歌女演唱这首词，并能道出作词的本事。姜夔从朋友处得知这种情况，很有感触，便补写了词序。\n此词为新楼落成而作，前五句就“安远”字面着想，虚构了一番境界，也客观地显示了起楼的时代背景。“龙沙”语出《后汉...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5f62cee9a0c24ed9f0e", "shortContent": "淳熙十三年丙午（1186）秋天，姜夔在汉阳府汉川县其姊家居住。入冬，武昌黄鹤山上新建成安远楼一座，词人偕友人刘去非（事迹不详）等前往参加落成典礼，自度此曲以纪其事。十年后，姜夔的朋友在汉阳江边还听到年轻歌女演唱这首词，并能道出作词的本事。姜夔从朋友处得知这种情况，很有感触，便补写了词序。\n此词为新楼落成而作，前五句就“安远”字面着想，虚构了一番境界，也客观地显示了起楼的时代背景。“龙沙”语出《后汉...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f52f2af4e09d55b6661", "shortContent": "这是姜夔为武昌黄鹤山上建起安远楼所作的词。词的小序写于作词十年之后。淳熙十三年（1186）丙午冬，词人参加该楼的落成典礼，曾携友人刘去非前往一游，写下此词；十年之后，一个朋友在汉阳江边听到歌女在唱此词，后同词人说起此事，昔日情景历历在目，于是姜夔在词之前补上了这个小序。\n词的上片，起始两句是迎合楼名“安远”，所谓安远，指的是与北边金国的和平局面。“龙沙”一词语出《后汉书·班超传赞》，“坦步葱岭，咫...", "authors": ["陈庆之"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312704a77683d193301537f", "shortContent": "这是姜夔为武昌黄鹤山上建起安远楼所作的词。词的小序写于作词十年之后。淳熙十三年（1186）丙午冬，词人参加该楼的落成典礼，曾携友人刘去非前往一游，写下此词；十年之后，一个朋友在汉阳江边听到歌女在唱此词，后同词人说起此事，昔日情景历历在目，于是姜夔在词之前补上了这个小序。\n\n词的上片，起始两句是迎合楼名“安远”，所谓安远，指的是与北边金国的和平局面。“龙沙”一词语出《后汉书·班超传赞》，“坦步葱岭，...", "authors": ["陈庆之"], "pressName": "崇文书局"}, {"bookId": "645d10a9e745e33de31310c7", "bookTitle": "姜夔诗词鉴赏辞典", "articleId": "6468a2625b7b0d4f45218fad", "shortContent": "淳熙十三年丙午（1186）秋天，姜夔在汉阳府汉川县其姊家居住。入冬，武昌黄鹤山上新建成安远楼一座，词人偕友人刘去非（事迹不详）等前往参加落成典礼，自度此曲以纪其事。十年后，姜夔的朋友在汉阳江边还听到年轻歌女演唱这首词，并能道出作词的本事。姜夔从朋友处得知这种情况，很有感触，便补写了词序。\n\n此词为新楼落成而作，前五句就“安远”字面着想，虚构了一番境界，也客观地显示了起楼的时代背景。“龙沙”语出《后...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '许昂霄《词综偶评》：“月冷龙沙”五句，题前一层，即为题後铺叙，手法最高。“玉梯凝望久”五句，凄婉悲壮，何减王粲《登楼赋》。', 'indent', 1419165061, '57bc5985c4c97100615b306f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10650, '玉阶怨', NULL, 247, 1052, 1, 2, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383742/6734465.htm', '', '玉阶生白露，夜久侵罗袜。
却下水晶帘，玲珑望秋月。', '此诗写一位妇女寂寞和惆怅的心情。前两句写女主人公无言独立玉阶，露水浓重，浸透了罗袜，她却还在痴痴等待；后两句写寒气袭人，女主人公回房放下窗帘，却还在凝望秋月。前两句写久等显示人的痴情；后两句以月亮的玲珑，衬托人的幽怨。全诗无一语正面写怨情，然而又似乎让人感到漫天愁思飘然而至，不著怨意而怨意很深，有幽邃深远之美。', '玉阶怨：乐府古题，是专写“宫怨”的曲题。郭茂倩《乐府诗集》卷四十三列于《相和歌辞·楚调曲》。
罗袜：丝织的袜子。
却下：回房放下。
却：还。
水晶帘：即用水晶石穿制成的帘子。
“玲珑望秋月”句：虽下帘仍望月而待，以至不能成眠。玲珑：透明貌。玲珑，一作“聆胧”。聆胧，月光也。
水晶：一作“水精”，与水晶同义。', '玉砌的台阶夜里已滋生了白露，夜深久伫立露水便浸湿了罗袜。
只好回到室内放下了水晶帘子，仍然隔着透明的帘子凝望秋月。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929b7d0ac11454953729", "shortContent": "《玉阶怨》，见宋郭茂倩《乐府诗集》，属《相和歌·楚调曲》，与《婕妤怨》、《长信怨》等曲，从古代所存歌辞看，都是专写“宫怨”的乐曲。\n李白的《玉阶怨》，虽曲名标有“怨”字，诗作中却只是背面敷粉，全不见“怨”字。无言独立阶砌，以至冰凉的露水浸湿罗袜；以见夜色之浓，伫待之久，怨情之深。“罗袜”，见人之仪态、身份，有人有神。夜凉露重，罗袜知寒，不说人而已见人之幽怨如诉。二字似写实，实用三国魏曹子建“凌波微...", "authors": ["孙艺秋"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac821a74606fc40938", "shortContent": "《玉阶怨》，见宋郭茂倩《乐府诗集》，属《相和歌·楚调曲》，与《婕妤怨》《长信怨》等曲，从古代所存歌辞看，都是专写“宫怨”的乐曲。\n\n李白的《玉阶怨》，虽曲名标有“怨”字，诗作中却只是背面敷粉，全不见“怨”字。无言独立阶砌，以至冰凉的露水浸湿罗袜；以见夜色之浓，伫待之久，怨情之深。“罗袜”，见人之仪态、身份，有人有神。夜凉露重，罗袜知寒，不说人而已见人之幽怨如诉。二字似写实，实用三国魏曹子建“凌波微...", "authors": ["孙艺秋"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f449761253910e903a9", "shortContent": "明代学者许学夷曾评价李白五言绝句时说：“五言绝，太白、摩诘多入于圣矣……太白如‘绿水明秋月’、‘美人卷珠帘’、‘懒摇白羽扇’等篇，皆超绝者也”。玉阶怨，乐府古题，是专写“宫怨”的曲题，郭茂倩《乐府诗集》卷四十三列于《相和歌辞·楚调曲》，此为李白拟作。作为五绝圣手，李白在宫怨题材上驾轻就熟，写怨情娓娓动人，不露声色，展现出高超的艺术构思与幽深之致。\n\n一、二句写景叙事，为读者呈现出女主人公百无聊赖却...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6466e5167da2f75ac7f0c552", "shortContent": "《玉阶怨》，见宋郭茂倩《乐府诗集》，属《相和歌·楚调曲》，与《婕妤怨》、《长信怨》等曲，从古代所存歌辞看，都是专写“宫怨”的乐曲。\n\n李白的《玉阶怨》，虽曲名标有“怨”字，诗作中却只是背面敷粉，全不见“怨”字。无言独立阶砌，以至冰凉的露水浸湿罗袜；以见夜色之浓，伫待之久，怨情之深。“罗袜”，见人之仪态、身份，有人有神。夜凉露重，罗袜知寒，不说人而已见人之幽怨如诉。二字似写实，实用三国魏曹子建“凌波...", "authors": ["孙艺秋"], "pressName": "上海辞书出版社"}]', '王拾遗：《玉阶怨》这首小诗，艺术上构思非常奇特，诗人只是抓住宫女生活中的一个细节，及其一时的心理动态，便概括地反映出宫女生活的孤独清凄。至于语言的洁练、精美，人物形象的惟妙惟肖，更是超乎常人，堪称古诗中的珍品。', 'center', 1417643858, '57b91cffdf0eea006335cddd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10651, '塞下曲 其一', NULL, 74, 341, 1, 3, '卢纶', NULL, 10014, '57b9c2f6c4c97100614832f4', '唐', 'shi', '诗', 'http://baike.baidu.com/view/11751679.htm', '', '鹫翎金仆姑，燕尾绣蝥弧。
独立扬新令，千营共一呼。', '组诗的第一首，歌咏边塞景物，描写将军发号时的壮观场面。前两句对仗工整，在严整中收敛力量；后两句改为散句，将内敛的力量忽然一放，气势不禁奔涌而出。这一敛一放，在极少的文字中，包孕了极为丰富的内容，显示出强大的力量。', '张仆射：一说为张延赏，一说为张建封。塞下曲：古时的一种军歌。
鹫翎：箭尾羽毛。金仆姑：神箭名。
燕尾：旗的两角叉开，若燕尾状。蝥（máo，一说音wù）弧：旗名。
独立：犹言屹立。扬新令：扬旗下达新指令。', '身佩雕羽制成的金仆姑好箭，旌旗上扎成燕尾蝥弧多鲜艳。大将军威严地屹立发号施令，千军万马一呼百应动地惊天。', NULL, '《唐诗笺注》：此首写托装束气概。下二句与“宁为百夫长，胜作一书生”，意趣略同。
《诗境浅说续编》：前二句言弓矢精良，见戎容之暨暨，三句状阃帅之尊严，四句状号令之整肃。寥寥二十字中，有军容荼火之观。', 'center', 1417644285, '57b8efe4d342d3005ac6c15d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10652, '塞下曲 其四', NULL, 62, 341, 1, 2, '卢纶', NULL, 10014, '57b9c2f6c4c97100614832f4', '唐', 'shi', '诗', 'http://baike.baidu.com/view/655314.htm', '', '野幕敞琼筵，羌戎贺劳旋。
醉和金甲舞，雷鼓动山川。', '此诗为卢纶《塞下曲》组诗的第四首，描写边防将士取得重大胜利后，边地兄弟民族在营帐前设宴劳军的场面，气氛热烈融洽，同时也描绘了将士“醉和金甲舞”的欢乐神态，赞颂了边地人民和守边将士团结一心，保卫国家安宁与统一的豪迈气概，也说明了将士们的得到兄弟民族的支持的。此诗取材典型，剪裁大胆，洋溢着民族间和睦团结的气氛。全诗语言精炼含蓄，情态活跃鲜明，写得慷慨而豪迈，爽朗而明快。', '敞：一本作“蔽”。
琼筵：盛宴。
雷鼓：即“擂鼓”。', '在野外天幕下设下劳军盛宴，边疆兄弟民族都来祝贺我军凯旋。
喝醉酒后还要和着金甲跳舞，欢腾的擂鼓声震动了周围的山川。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f449761253910e903aa", "shortContent": "【其一】\n卢纶《塞下曲》共有六首，分别写发号施令、射猎破敌、奏凯庆功等军营生活。此为第一首，写军队整饬待发、将军发号施令的场面。\n\n一、二句着力刻画战士出征前将军威武矫健的英雄形象。他身佩着雕羽制成的金仆姑名箭，他手上高擎着蝥弧军旗，在烈烈秋风中，显得如此绚丽耀眼。此处，诗人有意选取弓箭、军旗等物件，特意凸显将军的矫健神勇与英姿飒爽。据《左传·庄公十一年》载：“乘丘之役，公以金仆姑射南宫长万。”《...", "authors": ["乐云", "陈鹏", "杨军", "乐云"], "pressName": "崇文书局"}]', '《诗境浅说续编》：边氛既扫，乃宏开野幕，飨士策勋。醉余起舞，金甲犹擐，击鼓其镗，雷鸣山应。玉关生入，不须“醉卧沙场”矣。唐人善边塞诗者，推岑嘉州。卢之四诗，音词壮健，可与抗手。宜其在大历十子中，与韩翃、钱起齐名也。', 'center', 1417644385, '57b938ded342d3005ac900d9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10653, '江南曲', NULL, 53, 166, 1, 1, '李益', NULL, 10112, '57b9bd658ac2470063ff0efa', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/246754/9261652.htm', '', '嫁得瞿塘贾，朝朝误妾期。
早知潮有信，嫁与弄潮儿。', '此诗以白描手法叙述了丈夫常年在外经商的妇人的闺怨之情。后两句“早知潮有信，嫁与弄潮儿”，突然从平地翻起波澜，以空际运转之笔，曲折而传神地表达了这位少妇的怨情。从一个不同寻常的角度展示了闺中少妇由盼生怨、由怨而悔的内心活动，更深刻地展示了这她的苦闷和怨恨心情。', '江南曲：古代歌曲名。诗题《江南曲》原是乐府《相和歌》的曲名，为《江南弄》七曲之一。这是一首很有民歌色彩的拟乐府。
瞿塘贾：在长江上游一带作买卖的商人。瞿（qú）塘：指瞿塘峡，长江三峡之一。贾（gǔ）：商人。
妾：古代女子自称的谦词。
潮有信：潮水涨落有一定的时间，叫“潮信”。
弄潮儿：潮水涨时戏水的人，或指潮水来时，乘船入江的人。', '我真悔恨嫁做瞿塘商人妇，他天天把相会的佳期耽误。
早知潮水的涨落这么守信，还不如嫁一个弄潮的丈夫。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92bcc6e67846a920ec11", "shortContent": "这是一首闺怨诗。在唐代，以闺怨为题材的诗主要有两大内容：一是思征夫词，一是怨商人语。这是有其历史原因、社会背景的。由于唐代疆域辽阔，边境多事，要征调大批将士长期戍守边疆，同时，唐代商业已很发达，从事商品远途贩卖，长年在外经商的人日见增多，因而作为这两类人的妻子不免要空闺独守，过着孤单寂寞的生活。这样一个社会问题必然要反映到文学作品中来，抒写她们怨情的诗也就大量出现了。\n这首诗以白描的手法传出了一位...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389adcdc25963feee1a97", "shortContent": "这是一首闺怨诗。在唐代，以闺怨为题材的诗主要有两大内容：一是思征夫词，一是怨商人语。这是有其历史原因、社会背景的。由于唐代疆域辽阔，边境多事，要征调大批将士长期戍守边疆，同时，唐代商业已很发达，从事商品远途贩卖，长年在外经商的人日见增多，因而作为这两类人的妻子不免要空闺独守，过着孤单寂寞的生活。这样一个社会问题必然要反映到文学作品中来，抒写她们怨情的诗也就大量出现了。\n\n这首诗以白描的手法传出了一...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f449761253910e903ab", "shortContent": "唐代商业发达，商人长年累月出外经商，致使他们的妻子离别经年，独守空房，便生出许多怨望来。白居易《琵琶行》中那个“老大嫁作商人妇”的琵琶女，也因“商人重利轻别离”，而落得“去来江口守空船”。李益的这首《江南曲》就属于此类闺怨诗，反映了当时较为普遍的社会现象。《江南曲》原是乐府民歌的旧题，为《江南弄》七曲之一。因为是民歌体，所以李益有意用民间的口语写作。\n\n瞿塘是长江三峡之一，在今四川巫山、奉节两县之...", "authors": ["陈鹏"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706a73206168b2e0220b", "shortContent": "随着唐代商业的发达，嫁作商人妇的少女越来越多。商人长年累月出外经商，致使他们的妻子离别经年，独守空房，便生出许多怨恨来。此类闺怨诗反映了当时较为普遍的社会现象。白居易《琵琶行》中那个“老大嫁作商人妇”的琵琶女，也因“商人重利轻别离”，而落得“去来江口守空船”。李益的这首《江南曲》就属于此类闺怨诗。《江南曲》原是乐府民歌的旧题，为《江南弄》七曲之一。因为是民歌体，所以李益有意用民间的口语写作。\n\n瞿...", "authors": ["陈鹏"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270f7f2af4e09d55b682c", "shortContent": "随着唐代商业的发达，嫁作商人妇的少女越来越多。商人长年累月出外经商，致使他们的妻子离别经年，独守空房，便生出许多怨望来。此类闺怨诗反映了当时较为普遍的社会现象。白居易《琵琶行》中那个“老大嫁作商人妇”的琵琶女，也因“商人重利轻别离”，而落得“去来江口守空船”。李益的这首《江南曲》就属于此类闺怨诗。《江南曲》原是乐府民歌的旧题，为《江南弄》七曲之一。因为是民歌体，所以李益有意用民间的口语写作。\n\n瞿...", "authors": ["陈鹏"], "pressName": "崇文书局"}]', '钟惺《唐诗归》：荒唐之想，写怨情却真切。
贺裳《载酒园诗话》：诗又有无理而妙者，如李益“早知潮有信，嫁与弄潮儿”，此呵以理求乎？然自是妙语。
乔亿《大历诗略》：俚语不见身分，方是贾人妇口角，亦《子夜》、《读曲》之遗。
黄叔灿《唐诗笺注》：不知如何落想，得此急切情至语，乃知《郑风》“子不我思，岂无他人，”是怨怅之极词也。
李锳《诗法易简录》：极言夫婿之无情，借潮信作翻波，便有无限曲折。
俞陛云《诗境浅说续编》：潮来有信而郎去不归，喻巧而怨深。古乐府之借物见意者甚多，皆喻曲而有致，此诗其嗣响也。
刘永济《唐人绝句精华》：此写商人妇之怨情也。商人好利，久客不归，其妇怨之也。人情当怨深时，有此想法，诗人为之道出。
陈邦炎：这一由盼生怨、由怨而悔的内心活动过程，正合乎这位诗中人的心理状态，并不违反生活真实。', 'center', 1417644444, '57bc7966d342d3006bf448db', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10654, '回乡偶书二首 · 其一', NULL, 2442, 23, 2, 9, '贺知章', NULL, 10157, '57b9bee88ac2470063ff1d71', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/5137141/18862864.htm', '', '少小离家老大回，乡音无改鬓毛衰。
儿童相见不相识，笑问客从何处来。', '这是一首久客异乡、返回故里的感怀诗。全诗抒发了山河依旧，人事不同，人生易老，世事沧桑的感慨。一、二句，诗人置于熟悉而又陌生的故乡环境中，心情难于平静。首句写数十年久客他乡的事实，次句写自己的“老大”之态，暗寓乡情无限。三、四句虽写自己，却从儿童方面的感觉着笔，极富生活情趣。诗的感情自然、逼真，内容虽平淡，人情味却浓足。语言朴实无华，毫不雕琢，细品诗境，别有一番天地。全诗在有问无答中作结，哀婉备至，动人心絃，千百年来为人传诵，老少皆知。', '偶书：随便写的诗。
少小离家：贺知章三十七岁中进士，在此以前就离开家乡。老大：年纪大了。贺知章回乡时已年逾八十。
乡音：家乡的口音。
无改：没什么变化。一作“难改”。
鬓毛：额角边靠近耳朵的头髮。一作“面毛”。
鬓毛衰（cuī）：老年人头发稀疏减少。
相见：即看见我；相，带有指代性的副词。
不相识：即不认识我。
笑问：一本作“却问”，一本作“借问”。', '我从小离开家乡年老才返回，我的乡音没变头发却已稀疏。家乡的儿童看我是远方的客人，他们笑着问我从何处来。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e928e0f8fda55650553bc", "shortContent": "贺知章在天宝三载（744），辞去朝廷官职，告老返回故乡越州永兴（今浙江杭州萧山区），时已八十六岁。这时，距他离乡已有五十多个年头了。人生易老，世事沧桑，心头有无限感慨。《回乡偶书》的“偶”字，不只是说诗作得之偶然，还泄露了诗情来自生活、发于心底的这一层意思。\n第一首写于初来乍到之时，抒写久客伤老之情。在第一、二句中，诗人置身于故乡熟悉而又陌生的环境之中，一路迤逦行来，心情颇不平静：当年离家，风华正...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389abbb31680ae4c4b73a", "shortContent": "贺知章在天宝三载（744），辞去朝廷官职，告老返回故乡越州永兴（今浙江杭州萧山区），时已八十六岁。这时，距他离乡已有五十多个年头了。人生易老，世事沧桑，心头有无限感慨。《回乡偶书》的“偶”字，不只是说诗作得之偶然，还泄露了诗情来自生活、发于心底的这一层意思。原诗二首，此选其一。\n\n这首诗写于初来乍到之时，抒写久客伤老之情。在第一、二句中，诗人置身于故乡熟悉而又陌生的环境之中，一路迤逦行来，心情颇不...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f459761253910e903ad", "shortContent": "贺知章算不上是唐代第一流的诗人，但这首七绝却无愧为第一流的唐诗。清人李德举《唐诗真趣编》评价此诗说：“人皆知气象开展、音节洪亮为盛唐，不知盛唐中有如此淡瘦一种，却未尝不是高调。”此诗之妙处，不仅在于风格之淡瘦高调，更在于以朴实细腻之笔，勾勒出“近乡情更怯，不敢问来人”的人类普遍情感。\n\n唐玄宗天宝二年（743），贺知章以85岁高龄告老还乡。次年，诗人回到阔别五十多年的故乡越州永兴（今浙江萧山），面...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270317f0b9738b369b19b", "shortContent": "贺知章算不上是唐代第一流的诗人，但这首七绝却无愧为第一流的唐诗。清人李德举《唐诗真趣编》评价此诗说：“人皆知气象开展、音节宏亮为盛唐，不知盛唐中有如此淡瘦一种，却未尝不是高调。”此诗之妙处，不仅在于风格之淡瘦高调，更在于以朴实细腻之笔，勾勒出“近乡情更怯，不敢问来人”的人类普遍情感。\n\n唐玄宗天宝二年（743），贺知章以85岁高龄告老还乡，次年，诗人回到阔别50多年的故乡越州永兴（今浙江萧山），面...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270547ccdb86c49f29242", "shortContent": "天宝二年（743），贺知章请求出家为道士，得到准许后，他于天宝三年（744）回到阔别了五十多年的越州永兴（今浙江萧山）的故乡。临行时文人墨客、达官显宦送行者甚多，称一时之盛。这两首《回乡偶书》就是他初回家乡时所作。\n作品充满了生活气息，但也有深厚的人生哲理在内。\n第一首诗中，“少小离家老大回”。贺知章早年在吴中一带，中年离乡，此处是泛指。“老大回”却是实情，因为贺知章此次回乡，已是八十六岁高龄，在...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文208篇（小学、初中）", "articleId": "646e0e7b7da2f75ac70fcfb7", "shortContent": "贺知章在天宝三载(744)，辞去朝廷官职，告老返回故乡越州永兴（今浙江杭州萧山区），时已八十六岁。这时，距他离乡已有五十多个年头了。人生易老，世事沧桑，心头有无限感慨。\n在第一、二句中，诗人置身于故乡熟悉而又陌生的环境之中，一路迤逦行来，心情颇不平静：当年离家，风华正茂；今日返归，鬓毛疏落，不禁感慨系之。首句用“少小离家”与“老大回”的句中自对，概括写出数十年久客他乡的事实，暗寓自伤“老大”之情。...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f09bc5e6bb82b8cefcb97", "shortContent": "贺知章在天宝三载(744)，辞去朝廷官职，告老返回故乡越州永兴（今浙江杭州萧山区），时已八十六岁。这时，距他离乡已有五十多个年头了。人生易老，世事沧桑，心头有无限感慨。\n在第一、二句中，诗人置身于故乡熟悉而又陌生的环境之中，一路迤逦行来，心情颇不平静：当年离家，风华正茂；今日返归，鬓毛疏落，不禁感慨系之。首句用“少小离家”与“老大回”的句中自对，概括写出数十年久客他乡的事实，暗寓自伤“老大”之情。...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}]', '', 'center', 1417644639, '57b8a3995bbb50005b76f00c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (78203, '同诸客携酒早看樱桃花', NULL, 0, 2952, 0, 2, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', NULL, NULL, '晓报樱桃发，春携酒客过。
绿饧黏盏杓，红雪压枝柯。
天色晴明少，人生事故多。
停杯替花语，不醉拟如何。', NULL, NULL, NULL, NULL, NULL, 'center', 1525426220, '585d08cdac502e006721ee33', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10656, '春宫曲', NULL, 51, 202, 1, 1, '王昌龄', NULL, 10051, '57b91963128fe10054ca5788', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/93593/13613548.htm', '', '昨夜风开露井桃，未央前殿月轮高。
平阳歌舞新承宠，帘外春寒赐锦袍。', '诗写春宫之怨，却无怨语怨字。作者着力于背面敷粉，以侧面打光的手法，使其明暗清晰。诗明写新人受宠的情状，暗抒旧人失宠之怨恨。虚此实彼，言近意远：似乎无怨，怨至深；似乎无恨，恨至长。实弦外有音的手法。', '春宫曲：一作“殿前曲”。
露井：指没有井亭覆盖的井。
未央：即未央宫，汉宫殿名，汉高祖刘邦所建。也指唐宫。
平阳歌舞：指卫子夫，她原是平阳公主家中的歌女，后被汉武帝召入宫中，大得宠幸，以至废去原来的皇后陈阿娇，立她为皇后。
新承：一作“承新”，受到宠幸。', '', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92935e272d4b2254317e", "shortContent": "天宝年间，唐玄宗宠纳杨玉环，淫佚无度，诗人以汉喻唐，拉出汉武帝宠幸卫子夫、遗弃陈皇后的一段情事，为自己的讽刺诗罩上了一层“宫怨”的烟幕。更为巧妙的是，诗人写宫怨，字面上却看不出一点怨意，只是从一个失宠者的角度，着力描述新人受宠的情状，这样，“只说他人之承宠，而己之失宠，悠然可会”（清沈德潜《唐诗别裁集》）。\n全诗通篇都是失宠者对“昨夜”的追述之词。“昨夜风开露井桃”点明时令，切题中“春”字；露井（...", "authors": ["崔", "闽"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f459761253910e903b2", "shortContent": "这是一首宫怨诗。在王昌龄一百八十余首作品中，将近十分之一是宫怨诗。本诗开篇即言“昨夜”，说明通篇情事都已经发生过了，而诗中人至今想来仍然历历在目，耿耿于怀，则诗中人对于昨夜情事感触之深可见一斑。诗中并没有交代所感所伤，只是淡淡地说景说事，其情不言自明。\n\n昨夜春风吹拂，露井边的桃树已经开花。万物生长，盎然的春意带着新生的喜悦，和诗题遥相呼应，点明春的节令。未央殿，点明地点是宫中，诗中人的身份由此而...", "authors": ["张春晓"], "pressName": "崇文书局"}]', '王尧衢《古唐诗合解》云：“不寒而寒，赐非所赐，失宠者思得宠者之荣，而愈加愁恨，故有此词也。”这些说法，尽管不为无见，但此诗的旨义乃叙春宫中未承宠幸的宫人的怨思，从而讽刺皇帝沉溺声色，喜新厌旧。这种似此实彼、言近旨远的艺术手法，正体现出王昌龄七绝诗“深情幽怨，意旨微茫，令人测之无端，玩之不尽”的特色。
沈德潜《唐诗别裁》说：只说他人之承宠，而己之失宠，悠然可会。', 'center', 1417651632, '57bb100bd342d3006bea5e2e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10657, '黄鹤楼送孟浩然之广陵', NULL, 2341, 1052, 2, 15, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155340.htm', '', '故人西辞黄鹤楼，烟花三月下扬州。
孤帆远影碧空尽，唯见长江天际流。', '这是一首送别诗，寓离情于写景。诗作以绚丽斑驳的烟花春色和浩瀚无边的长江为背景，极尽渲染之能事，绘出了一幅意境开阔、情丝不绝、色彩明快、风流倜傥的诗人送别画。此诗虽为惜别之作，却写得飘逸灵动，情深而不滞，意永而不悲，辞美而不浮，韵远而不虚。全诗没一个「离别」，但又句句写着离别；没有直接抒情，但却处处透着深情。', '黄鹤楼：中国著名的名胜古迹，故址在今湖北武汉市武昌蛇山的黄鹄矶上，属于长江下游地带，传说三国时期的费祎于此登仙乘黄鹤而去，故称黄鹤楼。原楼已毁，现存楼为1985年修葺。
孟浩然：李白的朋友。
之：往、到达。
广陵：扬州。
故人：老朋友，这里指孟浩然。其年龄比李白大，在诗坛上享有盛名。李白对他很敬佩，彼此感情深厚，因此称之为「故人」。
辞：辞别。
烟花：形容柳絮如烟、鲜花似锦的春天景物，指艳丽的春景。下：顺流向下而行。
碧空尽：消失在碧蓝的天际。尽，尽头、消失了；碧空，一作「碧山」。
唯见：只看见。
天际流：流向天边。天际：天边。
', '友人在黄鹤楼向我挥手告别，阳光明媚的三月他要去扬州。
他的帆影渐渐消失在碧空中，只看见滚滚长江在天边奔流。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929e5e272d4b225431be", "shortContent": "这首送别诗有它自己特殊的情味。它不同于王勃《送杜少府之任蜀川》那种少年刚肠的离别，也不同于王维《渭城曲》那种深情体贴的离别。这首诗，可以说是表现一种充满诗意的离别。其所以如此，是因为这是两位风流潇洒的诗人的离别。还因为这次离别跟一个繁华的时代、繁华的季节、繁华的地区相联系，在愉快的分手中还带着诗人李白的向往，这就使得这次离别有着无比的诗意。\n李白与孟浩然的交往，是在他刚出四川不久，正当年轻快意的时...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac821a74606fc40942", "shortContent": "这首送别诗有它自己特殊的情味。它不同于王勃《送杜少府之任蜀川》那种少年刚肠的离别，也不同于王维《渭城曲》那种深情体贴的离别。这首诗，可以说是表现一种充满诗意的离别。其所以如此，是因为这是两位风流潇洒的诗人的离别。还因为这次离别跟一个繁华的时代、繁华的季节、繁华的地区相联系，在愉快的分手中还带着诗人李白的向往，这就使得这次离别有着无比的诗意。\n\n李白与孟浩然的交往，是在他刚出四川不久，正当年轻快意的...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f459761253910e903b4", "shortContent": "黄鹤楼上，诗人祖饯送别。丝竹声中，孟浩然登上舟船，挥挥手，挂帆东去。诗人伫立楼头，凭栏目送远去的风帆，久久不愿离去。一片孤帆，在辽阔的江面渐行渐远，慢慢只能望见一个模糊的影子，最后连这影子也消融在水天相接之处。唯剩下一江春水，在碧空掩映之下，无语东流。\n\n开元十六年（728）的春天，孟浩然即将前往繁华的扬州，李白的心情颇为复杂。来到江汉平原后，李白虽然结识了许多朋友，最为倾慕的却只有孟浩然。现在这...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127052c305cf0801816f5e", "shortContent": "黄鹤楼上，诗人祖饯送别。丝竹声中，孟浩然登上舟船，挥挥手，挂帆东去。诗人伫立楼头，凭栏目送远去的风帆，久久不愿离去。一片孤帆，在辽阔的江面渐行渐远，慢慢只能望见一个模糊的影子，最后连这影子也消融在水天相接之处，唯剩下一江春水，在碧空掩映之下，无语东流。\n\n开元十六年（728）的春天，孟浩然即将前往繁华的扬州，李白的心情颇为复杂。来到江汉平原后，李白虽然结识了许多朋友，最为倾慕的却只有孟浩然。现在这...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270a5e6f69b71e93f632b", "shortContent": "黄鹤楼上，诗人祖饯送别。丝竹声中，孟浩然登上舟船，挥挥手，挂帆东去。诗人伫立楼头，凭栏目送远去的风帆，久久不愿离去。一片孤帆，在辽阔的江面渐行渐远，慢慢只能望见一个模糊的影子，最后连这影子也消融在水天相接之处，唯剩下一江春水，在碧空掩映之下，无语东流。\n\n开元十六年（728）的春天，孟浩然即将前往繁华的扬州，李白的心情颇为复杂。来到江汉平原后，李白虽然结识了许多朋友，最为倾慕的却只有孟浩然。现在这...", "authors": ["鲁林华"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6467026a5b7b0d4f451a9cf4", "shortContent": "这首送别诗有它自己特殊的情味。它不同于王勃《送杜少府之任蜀川》那种少年刚肠的离别，也不同于王维《渭城曲》那种深情体贴的离别。这首诗，可以说是表现一种充满诗意的离别。其所以如此，是因为这是两位风流潇洒的诗人的离别。还因为这次离别跟一个繁华的时代、繁华的季节、繁华的地区相联系，在愉快的分手中还带着诗人李白的向往，这就使得这次离别有着无比的诗意。\n\n李白与孟浩然的交往，是在他刚出四川不久，正当年轻快意的...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "646f0dd25fc8182fe9ca3391", "shortContent": "李白与孟浩然的交往，是在他刚出四川不久，正当年轻快意的时候，他眼里的世界，还几乎像黄金一般美好。比李白大十多岁的孟浩然，这时已经诗名满天下。他给李白的印象是陶醉在山水之间，自由而愉快，所以李白在《赠孟浩然》诗中说：“吾爱孟夫子，风流天下闻。红颜弃轩冕，白首卧松云。”再说这次离别正是开元盛世，太平而又繁荣，季节是烟花三月、春意最浓的时候，从黄鹤楼到扬州，这一路都是繁花似锦。而扬州呢？更是当时整个东南...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}]', '陆游《入蜀记· 卷五》：八月二十八日访黄鹤楼故址，太白登此楼送孟浩然诗云：「孤帆远映碧山尽，唯见长江天际流。」盖帆樯映远，山尤可观，非江行久不能知也。
《唐诗正声》：《送梁六》之作，直以落句见情，便不能与青莲此诗争雄。
《唐诗绝句类选》：末二句写别时怅望之景，而情在其中。
《唐诗直解》：更不说在人上，妙，妙。
《唐诗解》：「黄鹤」分别之地，「扬州」所往之乡，「烟花」叙别之景，「三月」纪别之时。帆影尽，则目力已极；江水长，则离思无涯。怅望之情，俱在言外。
《汇编唐诗十集》：说「孤帆」即是说人。
陈继儒《唐诗选脉会通评林》：送别诗之祖，情意悠渺，可想不可说。
《唐诗摘钞》：不见帆影，惟见长江，怅别之情，尽在言外。
《增订唐诗摘钞》：「烟花三月」四字，插入轻婉；「三月」时也，「烟花」景也。第三句只接写「辞」字、「下」字。
《而庵说唐诗》：有神理在内。诗中用字须板，用意须活。板则不可移动，活则不可捉摸也。
《唐宋诗醇》：语近情遥，有「手挥五弦，目送飞鸿」之妙。
《网师园唐诗笺》：语近情遥（末二句下）。
《唐诗选胜直解》：首二句将题面说明，后一句写景，而送别之意已见言表。孤帆远影，以目送也；长江天际，以心送也。极浅极深，极淡极浓，真仙笔也。
《唐人万首绝句选评》：不必作苦语，此等语如朝阳鸣风。
《唐诗三百首》：陈婉俊补注：千古丽句（「烟花三月」句下）。
《诗境浅说续编》：送行之作夥矣，莫不有南浦销魂之意。太白与襄阳，皆一代才人，而兼密友，其送行宜累笺不尽。乃此诗首二句仅言自武昌至扬州。后二句叙别意，言天末孤帆，江流无际，止寥寥十四字，似无甚深意者。盖此诗作于别后，襄阳此行，江程迢递，太白临江送别，直望至帆影向空而尽，惟见浩荡江流，接天无际，尚怅望依依，帆影尽而离心不尽。十四字中，正复深情无限，曹子建所谓「爱至望苦深」也。
《唐诗绝句精华》：善写情者不贵质言，但将别时景象有感于心者写出，即可使诵其诗者发生同感也。', 'center', 1417651807, '57b8f306128fe10054c92fb8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10658, '逢入京使', NULL, 660, 405, 2, 14, '岑参', NULL, 10096, '57b97daec4c971005593ac34', '唐', 'shi', '诗', 'http://baike.baidu.com/view/155241.htm', '', '故园东望路漫漫，双袖龙钟泪不干。
马上相逢无纸笔，凭君传语报平安。', '此诗描写了诗人远涉边塞，路逢回京使者，托带平安口信，以安慰悬望的家人的典型场面，具有浓烈的人情味。诗文语言朴实，不加雕琢，却包含着两大情怀：思乡之情与渴望功名之情，亲情与豪情交织相融，真挚自然，感人至深。', '入京使：进京的使者。
故园：指长安和自己在长安的家。
漫漫：形容路途十分遥远。
龙钟：涕泪淋漓的样子。卞和《退怨之歌》：「空山歔欷泪龙钟。」这里是沾湿的意思。
凭：托、烦、请。
传语：捎口信。', '向东遥望长安家园路途遥远，思乡的泪沾湿双袖模糊面容。
在马上匆匆相逢没有纸和笔，只托你给我的家人报个平安。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b203048e64fbd91420", "shortContent": "天宝八载（749），岑参第一次远赴西域，充安西节度使高仙芝幕府书记。他告别了在长安的妻子，跃马踏上漫漫征途。\n也不知走了多少天，就在通西域的大路上，他忽地迎面碰见一个老相识。立马而谈，互叙寒温，知道对方要返京述职，顿时想到请他捎封家信回长安去。此诗就描写了这一情景。\n第一句是写眼前的实景。“故园”指的是在长安自己的家。“东望”是点明长安的位置。离开长安已经好多天，回头一望，只觉长路漫漫，尘烟蔽天。...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac26845f3e157ce31e", "shortContent": "天宝八载（749），岑参第一次远赴西域，充安西节度使高仙芝幕府书记。他告别了在长安的妻子，跃马踏上漫漫征途。\n\n也不知走了多少天，就在通西域的大路上，他忽地迎面碰见一个老相识。立马而谈，互叙寒温，知道对方要返京述职，顿时想到请他捎封家信回长安去。此诗就描写了这一情景。\n\n第一句是写眼前的实景。“故园”指的是在长安自己的家。“东望”是点明长安的位置。离开长安已经好多天，回头一望，只觉长路漫漫，尘烟蔽...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f459761253910e903b6", "shortContent": "岑参曾两次出塞，此诗作于他第一次远赴西域充任安西节度使高仙芝幕僚之际。时为天宝八载（749），诗人34岁，功名不如意，故西出阳关，任职边塞。如果每日与亲人相伴，便不懂得珍惜亲人间相聚的美好；如果不是时空的阻隔，便难以体会相思怀念的痛楚。此诗不作一生僻字眼，也看不出任何斧凿的痕迹，但诗人浓烈的情感是无以复加的。\n\n作别了亲人，作别了故园。行人每走一步，离故乡妻子便越远一步。当已身处漫漫征途，离家日远...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127068f2af4e09d55b6776", "shortContent": "岑参曾两次出塞，此诗作于他第一次远赴西域充任安西节度使高仙芝幕僚之际。作别了妻子，跃马踏上漫漫征途。如果每日与亲人相伴，便不懂得珍惜亲人间相聚的美好，如果不是时空的阻隔，便难以体会相思怀念的痛楚。此诗不作一生僻字眼，也看不出任何斧凿的痕迹，但诗人浓烈的情感是无以复加的。\n\n作别了亲人，作别了故园。行人每走一步，离故乡妻子便越远一步。当已身处漫漫征途，离家日远之际，转首回望，哪里还有故园的踪迹，哪里...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270e0f2af4e09d55b6800", "shortContent": "岑参曾两次出塞，此诗作于他第一次远赴西域充任安西节度使高仙芝幕僚之际。作别了妻子，跃马踏上漫漫征途。如果每日与亲人相伴，便不懂得珍惜亲人间相聚的美好，如果不是时空的阻隔，便难以体会相思怀念的痛楚。此诗不作一生僻字眼，也看不出任何斧凿的痕迹，但诗人浓烈的情感是无以复加的。\n\n作别了亲人，作别了故园。行人每走一步，离故乡妻子便越远一步。当已身处漫漫征途，离家日远之际，转首回望，哪里还有故园的踪迹，哪里...", "authors": ["刘琴"], "pressName": "崇文书局"}]', '《唐诗归·卷十三》：人人有此事，从来不曾写出，后人蹈袭不得。所以可久。
《唐诗解》：叙事真切，自是客中绝唱。
《而庵说唐诗》：「马上相逢无纸笔」，此句人人道好，惟在玉关故妙，若在近处则不为妙矣。
《删订唐诗解》：其情惨矣，乃不报客况而报平安，含蓄有味。
《艺概·诗概》：诗能于易处见工，便觉亲切有味。
《唐诗别裁集》卷十九：人人胸臆中语，却成绝唱。', 'center', 1417652211, '57b92218df0eea006335f923', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10659, '寒食', NULL, 724, 165, 2, 9, '韩翃', NULL, 10131, '57bdc0b17db2a20068dc6903', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/1027/5757661.htm', '', '春城无处不飞花，寒食东风御柳斜。
日暮汉宫传蜡烛，轻烟散入五侯家。', '诗的前两句写的是白昼风光，描写了整个长安柳絮飞舞，落红无数的迷人春景和皇宫园林中的风光；后两句则是写夜晚景象，生动地画出了一幅夜晚走马传烛图，使人如见蜡烛之光，如闻轻烟之味。全诗用白描手法写实，刻画皇室的气派，充溢着对皇都春色的陶醉和对盛世承平的歌咏。从当时皇帝到一般朝士，都偏爱该诗，历来评价也很高。
有人认为这首诗选取典型的意象描写宫廷寒食节的情况，是诗人借古讽今，含蓄表达了对宦官得宠专权的腐败现象的嘲讽。也有意见认为由于作者未曾刻意求深，只是沉浸在打动了自己的形象与情感之中，发而为诗，反而使诗更含蓄，更富于情韵。', '春城：暮春时的长安城。
寒食：古代在清明节前两天的节日，禁火三天，只吃冷食，所以称寒食。
御柳：御苑之柳，皇城中的柳树。
汉宫：这里指唐朝皇宫。
传蜡烛：寒食节普天下禁火，但权贵宠臣可得到皇帝恩赐而得到燃烛。《唐辇下岁时记》“清明日取榆柳之火以赐近臣”。
五侯：汉成帝时封王皇后的五个兄弟王谭、王商、王立、王根、王逢时皆为候，受到特别的恩宠。这里泛指天子近幸之臣。', '暮春时节，长安城处处柳絮飞舞、落红无数，寒食节东风吹拂着皇家花园的柳枝。
夜色降临，宫里忙着传蜡烛，袅袅轻烟散入王侯贵戚的家里。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b52cee9a0c24ecf958", "shortContent": "寒食是我国古代一个传统节日，一般在冬至后一百零五天，清明前两天。古人很重视这个节日，按风俗家家禁火，只吃现成食物，故名寒食。由于节当暮春，景物宜人，自唐至宋，寒食便成为游玩的好日子，宋人就说过：“人间佳节惟寒食”（邵雍《春游》）。唐代制度，到清明这天，皇帝宣旨取榆柳之火赏赐近臣，以示皇恩。唐代诗人窦叔向有《寒食日恩赐火》诗纪其实：“恩光及小臣，华烛忽惊春。电影随中使，星辉拂路人。幸因榆柳暖，一照草...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac26845f3e157ce327", "shortContent": "寒食是我国古代一个传统节日，一般在冬至后一百零五天，清明前两天。古人很重视这个节日，按风俗家家禁火，只吃现成食物，故名寒食。由于节当暮春，景物宜人，自唐至宋，寒食便成为游玩的好日子，宋人就说过：“人间佳节惟寒食”（邵雍《春游》）。唐代制度，到清明这天，皇帝宣旨取榆柳之火赏赐近臣，以示皇恩。唐代诗人窦叔向有《寒食日恩赐火》诗纪其实：“恩光及小臣，华烛忽惊春。电影随中使，星辉拂路人。幸因榆柳暖，一照草...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290e9", "shortContent": "韩翃广为传诵的一首七绝即是《寒食》。关于这首诗，还有一段为后代津津乐道的佳话。元代辛文房的《唐才子传》是这样说的：“德宗时，制诰阙人，中书两进除目，御笔不点，再请之，批曰：‘与韩翃。’时有同姓名者为江淮刺史，宰相请孰与，上复批曰：‘春城无处不飞花韩翃也。’俄以驾部郎中知制诰。终中书舍人。”因一首诗而为皇上赏识并授予职位，这在古代是非常少见的。这一点类似宋代的陈与义。在科举年代，凭自己的才华而得官是...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127069c305cf0801816fda", "shortContent": "韩翃广为传诵的一首七绝即是《寒食》。关于这首诗，还有一段为后代津津乐道的佳话。元代辛文房的《唐才子传》（卷四）是这样说的：“德宗时，制诰阙人，中书两进除目，御笔不点，再请之，批曰：‘与韩翃。’时有同姓名者为江淮刺史，宰相请孰与，上复批曰：‘春城无处不飞花韩翃也。’俄以驾部郎中知制诰。终中书舍人。”因一首诗而为皇上赏识并授予职位，这在古代是非常少见的。这一点类似宋代的陈与义。在科举年代，凭自己的才华...", "authors": ["吴中胜"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270e1f2af4e09d55b6811", "shortContent": "韩翃广为传诵的一首七绝即是《寒食》。关于这首诗，还有一段为后代津津乐道的佳话。元代辛文房的《唐才子传》（卷四）是这样说的：“德宗时，制诰阙人，中书两进除目，御笔不点，再请之，批曰：‘与韩翃。’时有同姓名者为江淮刺史，宰相请孰与，上复批曰：‘春城无处不飞花韩翃也。’俄以驾部郎中知制诰。终中书舍人。”因一首诗而为皇上赏识并授予职位，这在古代是非常少见的。这一点类似宋代的陈与义。在科举年代，凭自己的才华...", "authors": ["吴中胜"], "pressName": "崇文书局"}]', '《批点唐音》：大家语。
《批点唐诗正声》：禁体不事雕琢语，富贵闲雅自见。
《载酒园诗话又编》：君平以《寒食》诗得名，宋亡而天下不复禁烟，今人不知钻燧，又不深习唐事，因不解此诗立言之妙。如「春城无处不飞花，寒食东风御柳斜」二语，犹只淡写。至「日暮汉宫传蜡烛，轻烟散入五侯家」，上句言新火，下句言赐火也。此诗作于天宝中，其时扬氏擅宠，国忠、铦与秦、虢、韩三姨号为五家，豪贵荣盛，莫之能比，故借汉王氏五侯喻之。即赐火一事，而恩泽先沾于戚畹，非他人可望，其余锡予之滥，又不待言矣。寓意远，托兴微，真得风人之遗。
《围炉诗话》：唐之亡国，由于宦官握兵，实代宗授之以柄。此诗在德宗建中初，只「五侯」二字见意，唐诗之通于《春秋》者也。
《唐诗别裁》：「五侯」或指王氏五侯，或指宦官灭梁冀之五侯，总之先及贵近家也。
《网师园唐诗笺》：不用禁火而用赐火，烘托入妙（末二句下）。
《唐人万首绝句选评》：气骨高妙不待言，用「五侯」寓讽更微。
《大历诗略》：气象词调，居然江宁、嘉州。
《读雪山房杂著》：韩君平「春城何处不飞花」，只说侯家富贵，而对面之寥落可知，与少伯「昨夜风开露井桃」一例，所谓怨而不怒也。
《诗境浅说续编》：二十八字中，想见五剧春浓，八荒无事，宫廷之闲暇，贵族之沾恩，皆在诗境之内。以轻丽之笔，写出承平景象，宜其一时传诵也。', 'center', 1417652381, '57b995f65bbb5000534801a7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10665, '后宫词', NULL, 171, 2952, 1, 1, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', 'http://baike.baidu.com/view/576770.htm', '', '泪湿罗巾梦不成，夜深前殿按歌声。
红颜未老恩先断，斜倚熏笼坐到明。', '这是代宫人所作的怨词。首句写夜来不寐，梦想君王临幸；二句写忽闻前殿歌声，君王来幸无望；三句写红颜犹在，君恩已断之苦；四句写再幻想君王可能来幸，于是斜倚熏笼，坐待至天明，终成泡影。全诗语言明快自然，感情真挚而多层次，细腻地刻划了失宠宫女千回百转的心理状态。', '泪湿：犹湿透。
湿：一作「尽」。
罗巾：丝制手巾。
前殿：正殿。
按歌声：依照歌声的韵律打拍子。
红颜：此指妃子。
恩：指皇帝对她的恩宠。
倚：靠。
熏笼：覆罩香炉的竹笼。香炉用来熏衣被，为宫中用物。', '丝帕揩尽眼泪，好梦却难做成；
深夜，前殿传来有节奏的歌声。
红颜尚未衰老，恩宠却已断绝；
她独倚着熏笼，一直坐到天明。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c92cee9a0c24ecf9b2", "shortContent": "这首诗是代宫人所作的怨词。前人曾批评此诗过于浅露，这是不公正的。诗以自然浑成之语，传层层深入之情，语言明快而感情深沉，一气贯通而绝不平直。\n诗的主人公是一位不幸的宫女。她一心盼望君王的临幸而终未盼得，时已深夜，只好上床，已是一层怨怅。宠幸不可得，退而求之好梦；辗转反侧，竟连梦也难成，见出两层怨怅。梦既不成，索性揽衣推枕，挣扎坐起。正当她愁苦难忍，泪湿罗巾之时，前殿又传来阵阵笙歌，原来君王正在那边寻...", "authors": ["赖汉屏"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290f1", "shortContent": "作为一位男性诗人，白居易却以一位诗人的锐感对女性的命运感受真切：“人生莫作妇人身，百年苦乐由他人。”（《太行路》）对身处囹圄般的宫廷女性，他给予了更为同情的笔墨，她们离隔亲族，“三千宫女胭脂面，几个春来无泪痕”（《后宫词》），有幽闭怨旷之苦（《请拣放后宫内人》），有的甚至“一生遂向空房宿”，独自咀嚼“夜长无寐天不明”、“日迟独坐天难暮”（《上阳白发人》）的痛楚。\n\n这首《后宫词》采用对比的手法结构...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "645d09bbec56251f2eeb5b78", "bookTitle": "白居易诗文鉴赏辞典", "articleId": "6462dd40c0471b0062c4ac0f", "shortContent": "这首诗是代宫人所作的怨词。前人曾批评此诗过于浅露，这是不公正的。诗以自然浑成之语，传层层深入之情，语言明快而感情深沉，一气贯通而绝不平直。\n\n诗的主人公是一位不幸的宫女。她一心盼望君王的临幸而终未盼得，时已深夜，只好上床，已是一层怨怅。宠幸不可得，退而求之好梦；辗转反侧，竟连梦也难成，见出两层怨怅。梦既不成，索性揽衣推枕，挣扎坐起。正当她愁苦难忍，泪湿罗巾之时，前殿又传来阵阵笙歌，原来君王正在那边...", "authors": ["赖汉屏"], "pressName": "上海辞书出版社"}]', '《诗人玉屑》：诗有句含蓄者，老杜曰：「勋业频看镜，行藏独倚楼」……有句意俱含蓄者，如《九日》诗曰：「明年此会知谁健，更把茱萸子细看」……又白乐天云：「泪满罗巾梦未成……」
《唐诗选脉会通评林》：徐用吾曰：浅易中有思致。何仲德为富艳体。周珽曰：色衰宠弛，情之常也。红颜未老而恩先断，非有夺爱在中，即为谗妒使然也。闻歌而泪尽，梦不成而坐到明，一腔幽思，谁得知之？怀才未试，贬黜旋及，何以异此！
《唐人万首绝句选评》：极直致而味不减，所以妙也。
《精选评注五朝诗学津梁》：十分幽怨，十分寂寞，禁宫中辄唤奈何。
《诗境浅说续编》：作宫词者，多借物以寓悲。此诗独直书其事，四句皆倾怀而诉，而无穷幽怨皆在「坐到明」三字之中。
《唐人绝句精华》：白诗每喜作快语、尽语，如「红颜」句，皆嫌快，嫌尽，不免刻露。', 'center', 1417684666, '57b97f29128fe10054ce2589', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10660, '月夜', NULL, 687, 25, 1, 10, '刘方平', NULL, 10159, '57b9a0a279bc4400639b2ac0', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/155613/4876215.htm', '', '更深月色半人家，北斗阑干南斗斜。
今夜偏知春气暖，虫声新透绿窗纱。', '这首诗记叙作者对初春月夜气候转暖的独特感受。诗的前二句写景，记叙星月西斜，夜深人静。诗的后二句记所闻、所感，因虫声透过窗纱传来，感到已到春暖时节。诗中描绘了一种优美宁静而富有生机的境界，令人感到物候在变化，又是静美的。', '更深：夜深。古时计算时间，一夜分成五更。
月色半人家：月光只照亮了人家房屋的一半，另一半隐藏在黑暗里。
北斗：在北方天空排列成斗形的七颗亮星。
阑干：这里指横斜的样子。
南斗：有星六颗。在北斗星以南，形似斗，故称「南斗」。
偏知：才知，表示出乎意料。
新：初。新透：第一次透过。', '夜色深沉，月光斜照半边庭院。北斗南斗，不知不觉已经横斜。
今夜十分意外，感觉初春暖意，一声清脆的虫鸣透入绿色窗纱。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b20f8fda556505546e", "shortContent": "刘方平是盛唐时期一位不很出名的诗人，存诗不多。但他的几首小诗却写得清丽、细腻、新颖、隽永，在当时独具一格。\n据皇甫冉说，刘方平善画，“墨妙无前，性生笔先”（《刘方平壁画山水》），这首诗的前两句就颇有画意。夜半更深，朦胧的斜月映照着家家户户，庭院一半沉浸在月光下，另一半则笼罩在夜的暗影中。这明暗的对比越发衬出了月夜的静谧，空庭的阒寂。天上，北斗星和南斗星都已横斜。这不仅进一步从视觉上点出了“更深”，...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac26845f3e157ce320", "shortContent": "刘方平是盛唐时期一位不很出名的诗人，存诗不多。但他的几首小诗却写得清丽、细腻、新颖、隽永，在当时独具一格。\n\n据皇甫冉说，刘方平善画，“墨妙无前，性生笔先”（《刘方平壁画山水》），这首诗的前两句就颇有画意。夜半更深，朦胧的斜月映照着家家户户，庭院一半沉浸在月光下，另一半则笼罩在夜的暗影中。这明暗的对比越发衬出了月夜的静谧，空庭的阒寂。天上，北斗星和南斗星都已横斜。这不仅进一步从视觉上点出了“更深”...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290ea", "shortContent": "刘方平在盛唐诗人中不算知名，存诗以乐府体和绝句为主，但他往往能把这些小诗写得情趣盎然，《月夜》即是一例。\n\n首句“更深月色”四字点题，接下来诗人用“半人家”三字巧妙地破题。更深夜重时，月已东倾将半，连绵的户舍一半在月光下，一半沉于夜色中，只三字就将“更深月色”的景象准确地表现出来。\n\n写罢月色，诗人把目光投向苍穹。那里，北斗星和南斗星静静地斜挂在星空，从夜月到星空。视域扩张，而思域也从宁静的人间转...", "authors": ["唐磊"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127068f2af4e09d55b677e", "shortContent": "刘方平在盛唐诗人中不算知名，存诗以乐府体和绝句为主，但他往往能把这些小诗写得情趣盎然，《夜月》即是一例。\n\n首句“更深月色”四字点题，接下来诗人用“半人家”三字巧妙地破题。更深夜重时，月已东倾将半，连绵的户舍一半在月光下，一半沉于夜色中，只三字就将“更深月色”的景象准确地表现出来。\n\n写罢月色，诗人把目光投向苍穹，那里，北斗星和南斗星静静地斜挂在星空。从夜月到星空，视域扩张，而思域也从宁静的人间转...", "authors": ["唐磊"], "pressName": "崇文书局"}]', '顾贞观：二十有八字无可用者，其「透」一字妙甚，故言唐人村田之诗善者当此绝句。', 'center', 1417652762, '57b90d12a633bd00665dafcf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10661, '春怨', NULL, 151, 25, 1, 2, '刘方平', NULL, 10159, '57b9a0a279bc4400639b2ac0', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383736/6393766.htm', '', '纱窗日落渐黄昏，金屋无人见泪痕。
寂寞空庭春欲晚，梨花满地不开门。', '这首宫怨诗，意在写宫人色衰失宠而生怨思的。起句写时间：黄昏，渲染凄凉气氛；二句写人物：宫人，幽闭金屋伤心落泪；三句写环境：满庭空寂，春色迟暮，衬托衰落难堪；四句写心情：以落花映心境，凄凄惨惨戚戚。重叠渲染，反复勾勒，深曲委婉，味中有味。', '纱窗：蒙纱的窗户。
金屋：汉武帝幼时，曾对长公主（武帝姑母）说：“若得阿娇（长公主的女儿）作妇，当作金屋贮之。”这里指妃嫔所住的华丽宫室。
空庭：幽寂的庭院。欲：一作“又”。', '纱窗上的日影已经落下，黄昏正渐渐来临，华丽的宫室她一人独在，只见她满面挂着泪痕。寂寞幽深庭院里春天将尽，梨花满地，紧闭着院门。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b25914587d02f4e7f7", "shortContent": "这是一首宫怨诗。点破主题的是诗的第二句“金屋无人见泪痕”。句中的“金屋”，用汉武帝幼小时愿以金屋藏阿娇（陈皇后小名）的典故，表明所写之地是与人世隔绝的深宫，所写之人是幽闭在宫内的少女。下面“无人见泪痕”五字，可能有两重含意：一是其人因孤处一室、无人作伴而不禁下泪；二是其人身在极端孤寂的环境之中，纵然落泪也无人得见，无人同情。这正是宫人命运之最可悲处。句中的“泪痕”两字，也大可玩味。泪而留痕，可见其...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290eb", "shortContent": "这首春怨诗并非写一般人之春怨，因二句有“金屋”一词，一般唐诗用“金屋”，不是用来形容天宫之富丽，就是借用汉武帝金屋藏娇的典故，来指代皇帝的深宫。此诗显然写的是人间事，所以显然是一首宫怨诗。\n\n唐人宫怨诗不乏佳篇，如元稹著名的《行宫》诗云：“寥落古行宫，宫花寂寞红。白头宫女在，闲坐说玄宗。”像这样一类宫怨诗，除了表现宫女的寂寥外，也表达了作者对这些女子美好青春孤独流逝的同情。就主题而言，刘方平这首诗...", "authors": ["唐磊"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127068f2af4e09d55b677f", "shortContent": "这首春怨诗并非写一般人之春怨，因二句有“金屋”一词，一般唐诗用“金屋”，不是用来形容天宫之富丽，就是借用汉武帝金屋藏娇的典故，来指代皇帝的深宫。此诗显然写的是人间事，所以显然是一首宫怨诗。\n\n\n\n唐人宫怨诗不乏佳篇，如元稹的《行宫》诗：“寥落古行宫，宫花寂寞红。白头宫女在，闲坐说玄宗。”像这样一类宫怨诗，除了表现宫女的寂寥外，也表达了作者对这些女子美好青春孤独流逝的同情。就主题而言，刘方平这首诗并...", "authors": ["唐磊"], "pressName": "崇文书局"}]', '', 'center', 1417652853, '57b99d77a633bd0061a0167b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10662, '征人怨', NULL, 130, 12, 2, 2, '柳中庸', NULL, 10160, '57c10c63efa631005aaf8866', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383772.htm', '', '岁岁金河复玉关，朝朝马策与刀环。
三春白雪归青冢，万里黄河绕黑山。', '此诗抒写了征人在边塞久戌，感到痛苦不堪，面对着荒凉的环境更是心生怨苦，表现了诗人对统治者穷兵黩武的谴责。诗中没有一字是怨，只是客观地记录征人岁岁朝朝征战的生活情况，描绘边地荒凉寒苦的景象，而征人深深的怨情已寓于其中。全诗语言精美，对仗精工，笔法巧妙，境界阔大。', '岁岁：年复一年，年年月月。金河：即黑河，在今呼和浩特市城南。玉关：即甘肃玉门关。
朝（zhāo）朝：每天，日日夜夜。马策：马鞭。刀环：刀柄上的铜环，喻征战事。
三春：春季的三个月或暮春，此处指暮春。青冢（zhǒng）：西汉时王昭君的坟墓，在今内蒙古呼和浩特之南，当时被认为是远离中原的一处极僻远荒凉的地方。传说塞外草白，惟独昭君墓上草色发青，故称青冢。
黑山：一名杀虎山，在今内蒙古呼和浩特市东南。', '年年岁岁戍守金河保卫玉关，日日夜夜挥舞马鞭手握刀环。
时届暮春白雪飘飞归来塞外，万里奔波渡过黄河绕过黑山。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92b8dbb8b379ee095ae0", "shortContent": "这是一首传诵极广的边塞诗。诗中写到的金河、青冢、黑山，都在今内蒙古自治区境内，唐时属单于都护府。由此可以推断，这首诗写的是一个隶属于单于都护府的征人的怨情。全诗四句，一句一景，表面上似乎不相连属，实际上却统一于“征人”的形象，都围绕着一个“怨”字铺开。\n前两句就时记事，说的是：年复一年，东西奔波，往来边城；日复一日，跃马横刀，征战不休。“金河”，即大黑河，在今内蒙古呼和浩特市南。“玉关”，即甘肃玉...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290ec", "shortContent": "这是一首传诵极广的边塞诗。诗中提到的金河、青冢、黑山，都在现今内蒙古自治区境内，唐时属单于都护府。唐朝自安史之乱后，国势衰微，边患日益严重，被征调的士兵长年戍守边境不能归乡与家人团聚，必然产生怨愤之情。这首诗便是以一个隶属于单于都护府的征人身份，写出了这份怨情。\n\n唐诗中写征怨的诗作不少，这首诗避开征人回首、佳人断肠的通用题材。以就时记事开篇，首句写戍守边关时间之长、扎营地点不断转换：年复一年，东...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706a7f0b9738b369b20a", "shortContent": "这是一首传诵极广的边塞诗。诗中提到的金河、青冢、黑山，都在现今内蒙古自治区境内，唐时属单于都护府。唐朝自安史之乱后，国势衰微，边患日益严重，被征调的士兵长年戍守边境不能归乡与家人团聚，必然产生怨愤之情。这首诗便是以一个隶属于单于都护府的征人身份，写出了这份怨情。\n\n唐诗中写征怨的诗作不少，这首诗避开征人回首、佳人断肠的通用题材。以就时记事开篇，首句写戍守边关时间之长、扎营地点不断转换：年复一年，东...", "authors": ["易文翔"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631270ef73206168b2e02294", "shortContent": "这是一首传诵极广的边塞诗。诗中提到的金河、青冢、黑山，都在现今内蒙古自治区境内，唐时属单于都护府。唐朝自安史之乱后，国势衰微，边患日益严重，被征调的士兵长年戍守边境不能归乡与家人团聚，必然产生怨愤之情。这首诗便是以一个隶属于单于都护府的征人身份，写出了这份怨情。\n\n唐诗中写征怨的诗作不少，这首诗避开征人回首、佳人断肠的通用题材。以就时记事开篇，首句写戍守边关时间之长、扎营地点不断转换：年复一年，东...", "authors": ["易文翔"], "pressName": "崇文书局"}]', '清代乔亿《大历诗略》：工对不板。洗发“怨”字偏壮丽。
清代宋顾乐《唐人万首绝句选评》：直写得出，气格亦好。
近代俞陛云《诗境浅说续编》：四句皆作对语，格调雄厚。前二句言情；后二句写景，嵌“白”、“青”、“黄”、“黑”四字，句法浑成。', 'center', 1417652986, '57b9272fa633bd00665e91d6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10663, '宫词', NULL, 69, 244, 1, 1, '顾况', NULL, 10161, '57b98f33a633bd00619f826b', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/33421/8302468.htm', '', '玉楼天半起笙歌，风送宫嫔笑语和。
月殿影开闻夜漏，水晶帘卷近秋河。', '这首宫怨诗与其他宫怨诗的不同处，是采用对比的手法。前二句写听到玉楼笙歌笑语；后二句写自己锁闭幽宫的孤凄冷落。如此相形比作，即使不言怨情，而怨情早已显露。', '玉楼：华丽的高楼，指官嫔的居所。天半：形容楼高。
宫嫔：指嫔妃。和：伴随。
漏：古代滴水计时的工具，这里指夜深。
秋河：秋天星夜的银河。', '高入云天的玉楼，奏起阵阵笙歌；随风飘来宫嫔的笑语，与它伴和。
月宫影移，只听得夜漏单调嘀嗒；卷起水晶帘来，我似乎靠近银河。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290ed", "shortContent": "唐诗中写宫怨之作甚夥，但这首诗却因其巧妙的构思与精妙的艺术表达，为后人所称颂。清人吴瑞荣评曰：“宫词多作怨望，此独不然，当是逋翁特地出脱处。”（《唐诗笺要》）此诗之“出脱处”，就在于诗人采用对比的手法，写出嫔妃们一得宠一失宠的迥异遭遇，以一边的欢歌笑语反衬出一边的孤独寂寞，正所谓“以乐景写哀，以哀景写乐，一倍增其哀乐”（王夫之《姜斋诗话》）。\n\n一、二句写宫中受宠者的欢乐场景。“玉楼”和“天半”相...", "authors": ["乐云"], "pressName": "崇文书局"}]', '', 'center', 1417684449, '57b9584e0a2b58005c954c4f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10664, '和乐天春词', NULL, 157, 815, 2, 2, '刘禹锡', NULL, 10047, '57b922b57db2a2005427bf3a', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3231739.htm', '', '新妆宜面下朱楼，深锁春光一院愁。
行到中庭数花朵，蜻蜓飞上玉搔头。', '此诗为唐代诗人刘禹锡为友人白居易的《春词》创作的一首和诗。抒写宫怨闺情，但与其他同类诗迥然不同，描写一位宫女扮好新妆却无人赏识，只能百无聊赖地独自数花朵解闷，引得蜻蜓飞上头来的别致情景。诗人通过对宫女神态的传神刻画，表现了她不胜幽怨之情。诗意别出心裁，富有韵味。', '春词：春怨之词。“春词”为白居易原诗题目。
宜面：脂粉涂抹得与容颜相宜，给人一种匀称和谐的美感。一作“粉面”。朱楼：髹以红漆的楼房，多指富贵女子的居所。
春光：春天的风光、景致。南朝宋吴孜《春闺怨》诗：“春光太无意，窥窗来见参。”
中庭：庭院；庭院之中。汉司马相如《上林赋》：“醴泉涌于清室，通川过于中庭。”
蜻蜓：暗指头上之香。玉搔头：玉簪，可用来搔头，故称。', '浓妆艳抹打扮一新下红楼，深深庭院春光虽好只添愁。
走到庭中查数新开的花朵，蜻蜓有情飞到了玉簪上头。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92c60f8fda5565055593", "shortContent": "这首诗的标题写得很清楚，它是和白居易《春词》一诗的。所以，不妨先看一看白居易的《春词》：“低花树映小妆楼，春入眉心两点愁。斜倚栏杆背鹦鹉，思量何事不回头？”白居易此诗，先描绘一个斜倚栏杆、背向鹦鹉、眉目含愁的青年女子形象，接着以“思量何事不回头”的问句，轻轻一拨，引而不发，意味深长。而刘禹锡的和诗，也写闺中女子之愁，然而却写得更为婉曲新颖，别出蹊径。\n白诗开头是以“低花树映小妆楼”来暗示青年女子，...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290f0", "shortContent": "一栋别致的小楼，漆以朱色，别致中透出几分贵气，贵气中携以清爽。在那精致的窗棂背后，有一位女子曼妙的身影。\n\n这绝对是一个爱美的女子，她对自己的呵护是多么细致。我们仿佛看见，她正端坐镜前，轻匀粉面。那装束的每一个细节都恰到好处，是“淡妆浓抹总相宜”的到位与得体。细细地打扮好自己，女子带着雀跃的心情—步步走下朱红色的小楼。小楼掩映在满园春色之中，女子的目光正是为这大好春色所牵引，院落里的每一片新绿，每...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312706fc9ebcc6fbea1a3ff", "shortContent": "一栋别致的小楼，漆以朱色，别致中透出几分贵气，贵气中携以清爽。在那精致的窗棂背后，有一位女子曼妙的身影。\n\n这绝对是一个爱美的女子，她对自己的呵护是多么细致。我们仿佛看见，她正端坐镜前，轻匀粉面。那装束的每一个细节都恰到好处，是淡妆浓抹总相宜的到位与得体。细细地打扮好自己，女子带着雀跃的心情一步步走下朱红色的小楼。小楼掩映在满园春色之中，女子的目光正是为这大好春色所牵引，院落里的每一片新绿，每一个...", "authors": ["刘琴"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127114e6f69b71e93f6387", "shortContent": "一栋别致的小楼，漆以朱色，别致中透出几分贵气，贵气中携以清爽。在那精致的窗棂背后，有一位女子曼妙的身影。\n\n这绝对是一个爱美的女子，她对自己的呵护是多么细致。我们仿佛看见，她正端坐镜前，轻匀粉面。那装束的每一个细节都恰到好处，是淡妆浓抹总相宜的到位与得体。细细地打扮好自己，女子带着雀跃的心情一步步走下朱红色的小楼。小楼掩映在满园春色之中，女子的目光正是为这大好春色所牵引，院落里的每一片新绿，每一个...", "authors": ["刘琴"], "pressName": "崇文书局"}]', '清人宋顾乐《唐人万首绝句选评》：末句无谓自妙，细味之，乃亭其凝立如痴光景耳。
近人俞陛云《诗境浅说续编》：此春怨词也，乃仅曰“春词”，故但写春庭闲事，而怨在其中。第二句言一院春愁，即其本意。', 'center', 1423215702, '57b9266adf0eea0063361d7d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (223124, '再咏茄和董玄宰太史', NULL, 0, 1570, 0, 1, '区大相', NULL, 16249, '5858eac6128fe1006dcc463c', '明', 'shi', '诗', NULL, NULL, '名瓜不引蔓，囊粟未经陈。
虽共彤胡荐，何曾玉箸亲。
助羹餐不厌，抱瓮力常勤。
君问登盘实，应知学圃人。', NULL, NULL, NULL, NULL, NULL, 'center', 1525432578, '585db682128fe10069cf4c09', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10669, '题金陵渡', NULL, 137, 500, 1, 1, '张祜', NULL, 10152, '57baf998efa631005a803402', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383808.htm', '', '金陵津渡小山楼，一宿行人自可愁。
潮落夜江斜月里，两三星火是瓜洲。', '此诗为唐代诗人张祜所作的一首客愁杰作。前两句交代诗人夜宿的地点，点出诗人的心情；后两句实写长江金陵渡口美好的夜景，借此衬托出诗人孤独落寞的羁旅情怀。全诗紧扣江（落潮、夜江）、月（落月、斜月）、灯火（渔火、星火）等景，以一“愁”字贯穿全篇，诗旨甚明，神韵悠远，在艺术结构方面更是独具匠心。', '金陵渡：渡口名，在今江苏省镇江市附近，非指南京。
津：渡口。小山楼：渡口附近小楼，作者当时寄居之地。
宿：过夜。行人：旅客，指作者自己。可：当。
斜月：下半夜偏西的月亮。星火：形容远处三三两两像星星一样闪烁的火光。
瓜洲：长江北岸，今江苏省邗江县南部，与镇江市隔江相对，向来是长江南北水运的交通要冲。', '夜宿金陵渡口的小山楼，辗转难眠心中满怀旅愁。
斜月朦胧江潮正在下落，对岸星火闪闪便是瓜洲。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92cf2e6a6b501f95c3c0", "shortContent": "这是张祜漫游江南时写的一首小诗。\n“金陵津渡小山楼”，此“金陵”指古之京口，即今江苏镇江，非指南京。（详见宋人王楙《野客丛书》卷二十《北固甘罗》条）“小山楼”是诗人当时寄居之地。首句点题，轻灵妥帖。\n“一宿行人自可愁”，点明羁旅之愁。“行人”的身份，是“愁”之所自；“一宿”的时间，见出“愁”之深长。用一“可”字，毫不费力。“可”当作“合”解，而比“合”字轻松。这一句是全诗主意所在。\n“潮落夜江斜月...", "authors": ["钱仲联", "徐永端"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae4797a92d5e4fd917", "shortContent": "这是张祜漫游江南时写的一首小诗。\n\n“金陵津渡小山楼”，此“金陵”指古之京口，即今江苏镇江，非指南京。（详见宋人王楙《野客丛书》卷二十《北固甘罗》条）“小山楼”是诗人当时寄居之地。首句点题，轻灵妥帖。\n\n“一宿行人自可愁”，点明羁旅之愁。“行人”的身份，是“愁”之所自；“一宿”的时间，见出“愁”之深长。用一“可”字，毫不费力。“可”当作“合”解，而比“合”字轻松。这一句是全诗主意所在。\n\n“潮落夜...", "authors": ["钱仲联", "徐永端"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290f4", "shortContent": "诗人客游江南，经历了一个辗转难眠的夜晚，拂晓时分，面对渡口清丽的夜景，写下了这首名篇。\n\n首两句交代了诗人当时的地理位置，以及漂泊江南的人生状态。“金陵津渡”，在今江苏省镇江市，津、渡，均为渡口。“小山楼”，渡口附近小楼，是作者的栖息之地。“行人”即旅人，指客游江南的诗人。“自可愁”，是自然而然地惆怅。“愁”是全诗的基调。长期的客游生活，诗人一定对家乡满怀忆念。思乡之情的煎熬，使诗人一夜辗转反侧，...", "authors": ["徐昌盛"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "63127075e6f69b71e93f62eb", "shortContent": "诗人客游江南，经历了一个辗转难眠的夜晚，拂晓时分，面对渡口清丽的夜景，写下了这首名篇。\n\n“金陵津渡”，在今江苏省镇江市，津、渡，均为渡口。“小山楼”，是盖在小山的楼，是作者的栖息之地。“行人”即旅人，指客游江南的诗人。首两句交代了诗人当时的地理位置，以及漂泊江南的人生状态。“自可愁”，是自然而然的应该惆怅。“愁”是全诗的基调。长期的客游生活，诗人一定对家乡满怀忆念。思乡之情的煎熬，使诗人一夜辗转...", "authors": ["徐昌盛"], "pressName": "崇文书局"}]', '洪迈《唐人万首绝句选评》：情景悠然。
《精选评注五朝诗学津梁》：江中夜景如画。
潘德舆《养一斋诗话》：吾独惜以承吉之才，能为“晴空一鸟渡，万里秋江碧”、“河流出郭静，山色对楼寒”、“海明先见日，江白迥闻风”、“此盘山入海，河绕国连天”、“仰砌池光动，登楼海气来”、“风帆彭蠡疾，云水洞庭宽”、“人行中路月生海，鹤语上方星满天”、“潮落夜江斜月里，两三星火是瓜洲”诸句，可以直跨元、白之上，而竟为微之所短，又为乐天所遗也。', 'center', 1417685030, '57b91750c4c97100558fe389', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10670, '宫中词', NULL, 55, 173, 2, 1, '朱庆馀', NULL, 10162, '57b9a13279bc4400639b30e4', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383809.htm', '', '寂寂花时闭院门，美人相并立琼轩。
含情欲说宫中事，鹦鹉前头不敢言。', '此诗表达宫女幽禁深宫的苦愁思绪，构思独特，新辟蹊径。一般的宫怨诗主人公是一位孤凄的宫女，这首诗却写两位宫女。诗从写景开篇，以景衬情，以热衬冷。百花盛开的阳春，应是热闹非凡，然而宫门却寂寂锁闭。宫女赏春，本是欢欣乐事，然而久已失宠，感怀无限，心中郁闷，极愿互吐，却恐鹦鹉饶舌，竟不敢言。全诗含蓄蕴藉，在极有情趣中留给人们作种种想象去探索宫女们内心隐秘的天地和痛苦。', '寂寂：寂静无声貌。花时：百花盛开的时节，常指春日。
琼轩：对廊台的美称。轩：长廊。', '宫中重门紧闭，花开也觉寂寞。华美窗户之前，美人并肩而立。两眼合情脉脉，想说宫中故事。学舌鹦鹉在前，不敢轻易开口。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d00ce818559d0588b7", "shortContent": "在一般宫怨诗，特别是以绝句体裁写的宫怨诗里，大多只让一位女主角在极端孤独之中出场。在这首诗里，我们却看见两位女主角同时出场，相依相并，立在轩前。而就在这样一幅动人的双美图中，诗人以别出心裁的构思，巧妙而曲折地托出了怨情，点出了题旨。\n诗从写景入手。它的首句“寂寂花时闭院门”，既是以景衬情，又是景中见情。就以景衬情而言，它是以春花盛开之景从反面来衬托这首诗所要表达的美人幽怨之情，从而收到清王夫之在《...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae4797a92d5e4fd919", "shortContent": "在一般宫怨诗，特别是以绝句体裁写的宫怨诗里，大多只让一位女主角在极端孤独之中出场。在这首诗里，我们却看见两位女主角同时出场，相依相并，立在轩前。而就在这样一幅动人的双美图中，诗人以别出心裁的构思，巧妙而曲折地托出了怨情，点出了题旨。\n\n诗从写景入手。它的首句“寂寂花时闭院门”，既是以景衬情，又是景中见情。就以景衬情而言，它是以春花盛开之景从反面来衬托这首诗所要表达的美人幽怨之情，从而收到清王夫之在...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290f5", "shortContent": "宫词是一种特殊的体裁，它主要描写幽囚在深宫中的女性的思绪。有趣的是，写宫词的人并不是宫女们，而是男性诗人在代替她们发抒忧郁的情绪。这种代言体用男性的视角来审视这个特殊的女性群体，往往会有这样那样的偏差。但写得好的宫词，却能体贴入微地写出宫中女子的感受来。朱庆余的这首宫词，就具有这样的艺术效果。\n\n花时寂寂，院门紧闭。花时之寂象征着暮春的到来，花时已过，芳心何许？紧闭的院门将青春的心灵也关在了深宫大...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', NULL, 'center', 1423215655, '57b961b3128fe10054ccf349', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10671, '近试上张籍水部/闺意献张水部', NULL, 120, 173, 1, 1, '朱庆馀', NULL, 10162, '57b9a13279bc4400639b30e4', '唐', 'shi', '诗', 'http://baike.baidu.com/view/356522.htm', '', '洞房昨夜停红烛，待晓堂前拜舅姑。
妆罢低声问夫婿，画眉深浅入时无。', '此诗是唐代诗人朱庆馀在应进士科举前所作的呈现给张籍的行卷诗。诗以新妇自比，以新郎比张籍，以公婆比主考官，借以征求张籍的意见。全诗选材新颖，视角独特，以“入时无”三字为灵魂，将自己能否踏上仕途与新妇紧张不安的心绪作比，寓意自明，令人玩味。', '张籍：唐代诗人。
水部：水部司，官署名。隋朝始置，为工部所属四司之一。当时张籍任水部员外郎。
洞房：新婚卧室。
停红烛：让红烛通宵点着。停，留置。
舅姑：公婆。
深浅：浓淡。
入时无：是否时髦。这里借喻文章是否合适。', '【韵译】
洞房里昨夜花烛彻夜通明，等待拂晓拜公婆讨个好评。
打扮好了轻轻问丈夫一声：我的眉画得浓淡可合时兴？
【散译】
洞房里，昨天夜里留着的红烛一夜没熄；新媳妇等待天亮到堂前去拜见公婆。
她梳妆打扮完低声问丈夫：我描画的眉毛，颜色深浅是否合宜？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d003048e64fbd91650", "shortContent": "以夫妻或男女爱情关系比拟君臣以及朋友、师生等其他社会关系，乃是我国古典诗歌中从《楚辞》就开始出现并在其后得到发展的一种传统表现手法。此诗也是用这种手法写的。\n这首诗又题为《近试上张水部》。这另一个标题可以帮助读者明白诗的作意。唐代应进士科举的士子有向名人行卷的风气，以希求其称扬和介绍于主持考试的礼部侍郎。朱庆馀此诗投赠的对象，是官水部郎中的张籍。张籍当时以擅长文学而又乐于提拔后进与韩愈齐名。朱庆馀...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae4797a92d5e4fd91a", "shortContent": "以夫妻或男女爱情关系比拟君臣以及朋友、师生等其他社会关系，乃是我国古典诗歌中从《楚辞》就开始出现并在其后得到发展的一种传统表现手法。此诗也是用这种手法写的。\n\n这首诗又题为《近试上张水部》。这另一个标题可以帮助读者明白诗的作意。唐代应进士科举的士子有向名人行卷的风气，以希求其称扬和介绍于主持考试的礼部侍郎。朱庆余此诗投赠的对象，是官水部郎中的张籍。张籍当时以擅长文学而又乐于提拔后进与韩愈齐名。朱庆...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f487ccdb86c49f290f6", "shortContent": "中国古典诗歌有一个悠久的传统，即以夫妻或男女关系来比喻君臣上下的关系。此风最早由《离骚》开端，其后历代都有人使用这种手法。朱庆余此诗也不例外。\n\n张水部即张籍，时官水部员外郎，故称。唐代士子参加进士考试前，往往有投卷的风气，即将自己的得意之作抄成卷子，投给当时喜奖掖后进的名人，求得其赞誉，希冀自己的名字能因此达于主管科举的礼部侍郎之前。张籍是一位喜欢提拔后进的人，朱庆余向他投卷之后，写了这首诗以征...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707677683d19330153c9", "shortContent": "中国古典诗歌有一个悠久的传统，即以夫妻或男女关系来比喻君臣上下的关系。此风最早由《离骚》开端，其后历代都有人使用这种手法。朱庆馀此诗也不例外。\n\n张水部即张籍，时官水部郎中，故称。唐代士子参加进士考试前，往往有投卷的风气，即将自己的得意之作抄成卷子，投给当时喜奖掖后进的名人，求得其赞誉，希冀自己的名字能因此达于主管科举的礼部侍郎之前。张籍是一位喜欢提拔后进的人，朱庆馀向他投卷之后，写了这首诗以征询...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "631271317ccdb86c49f292fa", "shortContent": "中国古典诗歌有一个悠久的传统，即以夫妻或男女关系来比喻君臣上下的关系。此风最早由《离骚》开端，其后历代都有人使用这种手法。朱庆馀此诗也不例外。\n张水部即张籍，时官水部郎中，故称。唐代士子参加进士考试前，往往有投卷的风气，即将自己的得意之作抄成卷子，投给当时喜奖掖后进的名人，求得其赞誉，希冀自己的名字能因此达于主管科举的礼部侍郎之前。张籍是一位喜欢提拔后进的人，朱庆馀向他投卷之后，写了这首诗以征询他...", "authors": ["黄鸣"], "pressName": "崇文书局"}]', '宋·刘克庄《后村诗话》：肚称朱庆馀“妆罢低声问夫婿，画眉深浅入时无”之句，却不入选，岂嫌其自鬻耶？放翁云：“谁言田家不入时？小姑画得城中眉。”比庆馀尤工。
明·周珽《唐诗选脉会通评林》：此诗不言美丽，而味其词意，非绝色第一，不足以当之。后二句，审时证己，敛德避妒，可谓善藏其用。与王仲初“三日入厨下，携手作羹汤。未谙姑食性，先遣小姑尝”，一不恃才妄作，一不敢轻试违时，具有无限深意。
清·史承豫《唐贤小三昧集》：托喻既深，何嫌近亵！
近代·刘永济《唐人绝句精华》：此托之新妇见舅姑，以比举子见考官。籍有酬朱庆馀诗曰：“越女新妆出镜心……”其称许特甚，可见古人爱士之心。', 'center', 1417685234, '57b99db179bc44006029b22e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10672, '将赴吴兴登乐游原', NULL, 139, 501, 2, 1, '杜牧', NULL, 10109, '57b9836cc4c971005593dfec', '唐', 'shi', '诗', 'http://baike.baidu.com/view/350142.htm', '', '清时有味是无能，闲爱孤云静爱僧。
欲把一麾江海去，乐游原上望昭陵。', '杜牧于宣宗大中四年（850年）将离长安到湖州任刺史时所作。这首诗表达了杜牧想出守外郡为国出力，又不忍离京的忠君爱国之情。以登乐游原起兴，以望昭陵戛止。热爱祖国，追怀盛世之情自在，为国捐躯，抱负未能施展之意自见。通过这首诗，杜牧表现了对朝政的无言讽刺。', '吴兴：唐郡名，即今浙江省吴兴县，隋代改称湖州。
乐游原：在长安城南，地势高敞，唐时为登览胜地，故址在今陕西省西安市南。
清时句：意谓当这清平无所作为之时，自己所以有此闲情。
无能：无所作为。
闲：闲情逸兴。
僧：僧人。
把：持、握。
麾（huī）：古代指挥用的旌旗，这里指出任地方官的符节。
江海：指太湖，吴兴滨临太湖。
昭陵：唐太宗的陵墓。', '天下太平之时，像我这般无大才的过得很有兴味，闲时喜欢如孤云般逍遥悠闲，静时就如老僧的静空恬淡。
我将手持符节，远去江海，临去之前，到乐游原上去西望那位文治武功煊赫一时的明君唐太宗的陵墓。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d603572034f659e58b", "shortContent": "在唐人七绝中，也和在整个古典诗歌中一样，以赋、比二体写成的作品较多，兴而比或全属兴体的较少。杜牧这首诗采用了“托事于物”的兴体写法，称得上是一首“言在此而意在彼”、“言已尽而意有馀”的名篇。\n这首诗是作者于宣宗大中四年（850）将离长安到吴兴（即湖州，今浙江湖州市）任刺史时所作。乐游原在长安城南，地势高敞，可以眺望，是当时的游览胜地。\n杜牧不但长于文学，而且具有政治、军事才能，渴望为国家作出贡献。...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389aecdc25963feee1ab2", "shortContent": "在唐人七绝中，也和在整个古典诗歌中一样，以赋、比二体写成的作品较多，兴而比或全属兴体的较少。杜牧这首诗采用了“托事于物”的兴体写法，称得上是一首“言在此而意在彼”“言已尽而意有余”的名篇。\n\n这首诗是作者于宣宗大中四年（850）将离长安到吴兴（即湖州，今浙江湖州市）任刺史时所作。乐游原在长安城南，地势高敞，可以眺望，是当时的游览胜地。\n\n杜牧不但长于文学，而且具有政治、军事才能，渴望为国家作出贡献...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f497ccdb86c49f290f7", "shortContent": "唐宣宗大中四年（850），杜牧离开长安，将赴吴兴任湖州刺史。临行前，他特意登上长安的知名游览胜地乐游原。诗人寄情山水，遥望昭陵，追怀盛世之余，亦传递出抱负未展、壮志未酬的人生遗憾。\n\n一、二句写诗人自身处境与澹然心境。在京城为官，看起来令人艳羡，却是有名无实的闲职。胸怀壮志的人，为何却无所事事，碌碌无为？或许是因为自己“无能”吧。淡淡的自嘲中，透露出诗人多少有心报国却报国无门的辛酸与无奈？我喜欢那...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645d0ac98258810260dbe044", "bookTitle": "杜牧诗文鉴赏辞典", "articleId": "646198ba30675327e17b6669", "shortContent": "在唐人七绝中，也和在整个古典诗歌中一样，以赋、比二体写成的作品较多，兴而比或全属兴体的较少。杜牧这首诗采用了“托事于物”的兴体写法，称得上是一首“言在此而意在彼”“言已尽而意有余”的名篇。\n\n这首诗是作者于宣宗大中四年（850）将离长安到吴兴（即湖州，今浙江湖州市）任刺史时所作。乐游原在长安城南，地势高敞，可以眺望，是当时的游览胜地。\n\n杜牧不但长于文学，而且具有政治、军事才能，渴望为国家作出贡献...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}]', '《石林诗话》：此盖不满于当时，故末有“望昭陵”之句。（宋人江辅之被贬）谢表有云：“清时有味，白首无能。”蔡持正为侍御史，引杜牧诗为证，以为怨望，遂复罢。
《懒真子》：“清时有味是无能……”右杜牧之自尚书郎出为郡守之作，其意深矣。盖乐游原者，汉宣帝之寝庙在焉。昭陵，即唐太宗之陵也。牧之之意，盖自伤不遇宣帝、太宗之时，而远为郡守也。藉使意不出此，以景趣为意，亦自不凡，况感寓之深乎？此所以不可及也。
《唐诗绝句类选》：前二句乏逸俊。
《唐音戊签》：旧史云：牧自负才略，兄惊隆盛于时，而牧居下位，心不乐。“望昭陵”者，不得志于时而思明君之世，盖怨也。首云“清时”，反辞也。
《唐诗快》：遂成名言（首二句下）。此岂得意人语耶（末句下）？
《唐贤清雅集》：昭陵为唐创业守成英主，后世子孙陵夷不振，故牧之于去国时登高寄慨，词意浑含，得风人遗意。
《诗境浅说续编》：司勋将远宦吴兴，登乐游原而遥望昭陵，追怀贞观，有江湖魏阙之思。前二句诗意尤深。', 'center', 1417685274, '57b99db9165abd005a6da742', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10673, '赤壁', NULL, 627, 501, 2, 13, '杜牧', NULL, 10109, '57b9836cc4c971005593dfec', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/49046/5458011.htm', '', '折戟沉沙铁未销，自将磨洗认前朝。
东风不与周郎便，铜雀春深锁二乔。', '这首咏史吊古诗，似是讥讽周瑜成功的侥幸。诗的开头二句，借物起兴，慨叹前朝人物事迹，后二句议论：赤壁大战，周瑜火攻，倘无东风，东吴早灭，二乔将被虏去，历史就要改观。诗的构思极为精巧，点染用功。', '折戟：折断的戟。戟，古代兵器。
销：销蚀。
将：拿起。
磨洗：磨光洗净。
认前朝：认出戟是东吴破曹时的遗物。
东风：指火烧赤壁事
周郎：指周瑜，字公瑾，年轻时即有才名，人乎周郎。后任吴军大都督。
铜雀：即铜雀台，曹操在今河北省临漳县建造的一座楼台，楼顶里有大铜雀，台上住姬妾歌妓，是曹操暮年行乐处。
二乔：东吴乔公的两个女儿，一嫁前国主孙策（孙权兄），称大乔，一嫁军事统帅周瑜，称小乔，合称“二乔”。', '一支折断了的铁戟沉没在水底沙中还没有销蚀掉，经过自己又磨又洗发现这是当年赤壁之战的遗物。假如东风不给周瑜以方便，结局恐怕是曹操取胜，二乔被关进铜雀台了。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d85e272d4b2254352c", "shortContent": "这首诗是作者经过赤壁（即今湖北武汉赤矶山）这个著名的古战场，有感于三国时代的英雄成败而写下的。诗以地名为题，实则是怀古咏史之作。\n发生于汉献帝建安十三年（208）十月的赤壁之战，是对三国鼎立的历史形势起着决定性作用的一次重大战役。其结果是孙、刘联军击败了曹军，而三十四岁的孙吴军统帅周瑜，乃是这次战役中的头号风云人物。\n诗篇开头借一件古物来兴起对前朝人物和事迹的慨叹。在那一次大战中遗留下来的一支折断...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389aecdc25963feee1ab6", "shortContent": "这首诗是作者经过赤壁（即今湖北武汉赤矶山）这个著名的古战场，有感于三国时代的英雄成败而写下的。诗以地名为题，实则是怀古咏史之作。\n\n发生于汉献帝建安十三年（208）十月的赤壁之战，是对三国鼎立的历史形势起着决定性作用的一次重大战役。其结果是孙、刘联军击败了曹军，而三十四岁的孙吴军统帅周瑜，乃是这次战役中的头号风云人物。\n\n诗篇开头借一件古物来兴起对前朝人物和事迹的慨叹。在那一次大战中遗留下来的一支...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f497ccdb86c49f290f8", "shortContent": "赤壁（今湖北嘉鱼县东北），因三国时期著名的赤壁之战发生于此而蜚声海内外，并成为后世文人歌咏的对象。同为咏赤壁，杜牧却能自出机杼，不从正面描摹周瑜如何大破曹军，却从人们意想不到的“东风”着眼，翻说为奇，警拔精悍，读来令人耳目一新。\n\n起首两句借古战场遗留下来的一件古兵器伸展开去，寄托对前朝人事的感叹。这支折断的铁戟，沉没于水底沙中，已悄然沉睡了六百年。一朝被人发现了，经过一番磨洗，却原来是当年赤壁之...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270787ccdb86c49f2927b", "shortContent": "赤壁（今湖北嘉鱼县东北），因三国时期著名的赤壁之战发生于此而蜚声海内外，并成为后世文人歌咏的对象。同为咏赤壁，杜牧却能自出机杼，不从正面描摹周瑜如何大破曹军，却从人们意想不到的“东风”着眼，翻说为奇，警拔精悍，读来令人耳目一新。\n\n起首两句借古战场遗留下来的一件古兵器伸展开去，寄托对前朝人事的感叹。这支折断的铁戟，沉没于水底沙中，已悄然沉睡了六百年。一朝被人发现了，经过一番磨洗，却原来是当年赤壁之...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312713e73206168b2e022d4", "shortContent": "赤壁（今湖北嘉鱼东北），因三国时期著名的赤壁之战发生于此而蜚声海内外，并成为后世文人歌咏的对象。同为咏赤壁，杜牧却能自出机杼，不从正面描摹周瑜如何大破曹军，却从人们意想不到的“东风”着眼，翻说为奇，警拔精悍，读来令人耳目一新。\n起首两句借古战场遗留下来的一件古兵器伸展开去，寄托对前朝人事的感叹。这支折断的铁戟，沉没于水底沙中，已悄然沉睡了六百年。一朝被人发现了，经过一番磨洗，却原来是当年赤壁之战残...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645d0ac98258810260dbe044", "bookTitle": "杜牧诗文鉴赏辞典", "articleId": "6461df77cd12b001c6da27b1", "shortContent": "这首诗是作者经过赤壁（即今湖北武汉赤矶山）这个著名的古战场，有感于三国时代的英雄成败而写下的。诗以地名为题，实则是怀古咏史之作。\n\n发生于汉献帝建安十三年（208）十月的赤壁之战，是对三国鼎立的历史形势起着决定性作用的一次重大战役。其结果是孙、刘联军击败了曹军，而三十四岁的孙吴军统帅周瑜，乃是这次战役中的头号风云人物。\n\n诗篇开头借一件古物来兴起对前朝人物和事迹的慨叹。在那一次大战中遗留下来的一支...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f93f7f27182da38c1317", "shortContent": "后来的诗论家对于杜牧在这首诗中所发表的议论，也有一番议论。宋人许（左岂右页）《彦周诗话》云：“杜牧之作《赤壁》诗……意谓赤壁不能纵火，为曹公夺二乔置之铜雀台上也。孙氏霸业，系此一战。社稷存亡，生灵涂炭都不问，只恐被捉了二乔，可见措大不识好恶。”这一既浅薄而又粗暴的批评，曾经引起许多人的反对。如《四库提要》云：“（许（左岂右页））讥杜牧《赤壁》诗为不说社稷存亡，惟说二乔。不知大乔乃孙策妇，小乔为周瑜...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}]', '许顗《彦周诗话》：杜牧之作《赤壁》诗······意谓赤壁不能纵火，为曹公夺二乔置之铜雀台上也。孙氏霸业，系此一战。社稷存亡，生灵涂炭都不问，只恐被捉了二乔，可见措大不识好恶。
纪昀等《四库提要》：（许顗）讥杜牧《赤壁》诗为不说社稷存亡，惟说二乔，不知大乔乃孙策妇，小乔为周瑜妇，二人入魏，即吴亡可知。此诗人不欲质言，故变其词耳。
何文焕《历代诗话考索》：牧之之意，正谓幸而成功，几乎家国不保。
王尧衢《古唐诗合解》：杜牧精于兵法，此诗似有不足周郎处。', 'center', 1417685335, '57b931b5165abd0054c169a3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (78225, '船夜援琴', NULL, 109, 2952, 1, 1, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', 'http://baike.baidu.com/view/6197552.htm', '', '鸟栖鱼不动，月照夜江深。
身外都无事，舟中只有琴。
七弦为益友，两耳是知音。
心静即声淡，其间无古今。', '', '', '', NULL, '', 'center', 1482772659, '585d08d31b69e6006cca7aa1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10674, '泊秦淮', NULL, 1357, 501, 2, 16, '杜牧', NULL, 10109, '57b9836cc4c971005593dfec', '唐', 'shi', '诗', 'http://baike.baidu.com/view/159987.htm', '', '烟笼寒水月笼沙，夜泊秦淮近酒家。
商女不知亡国恨，隔江犹唱后庭花。', '此诗是诗人夜泊秦淮时触景感怀之作，前半段写秦淮夜景，后半段抒发感慨，借陈后主（陈叔宝）因追求荒淫享乐终至亡国的历史，讽刺那些不从中汲取教训而醉生梦死的晚唐统治者，表现了作者对国家命运的无比关怀和深切忧虑的情怀。全诗寓情于景，意境悲凉，感情深沉含蓄，语言精当锤炼，艺术构思颇具匠心，写景、抒情、叙事有机结合，具有强烈的艺术感染力。', '秦淮：即秦淮河，发源于江苏句容大茅山与溧水东庐山两山间，经南京流入长江。相传为秦始皇南巡会稽时开凿的，用来疏通淮水，故称秦淮河。历代均为繁华的游赏之地。
烟：烟雾。
泊：停泊。
商女：以卖唱为生的歌女。
后庭花：歌曲《玉树后庭花》的简称。南朝陈皇帝陈叔宝（即陈后主）溺于声色，作此曲与后宫美女寻欢作乐，终致亡国，所以后世把此曲作为亡国之音的代表。', '迷离月色和轻烟笼罩寒水和白沙，夜晚船泊在秦淮靠近岸上的酒家。
卖唱的歌女不懂什么叫亡国之恨，隔着江水仍在高唱着玉树后庭花。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d80f8fda556505565d", "shortContent": "建康（今江苏南京）是六朝都城，秦淮河穿过城中流入长江，两岸酒家林立，是当时豪门贵族、官僚士大夫享乐游宴的场所。唐王朝的都城虽不在建康，然而秦淮河两岸的景象却一如既往。\n有人说作诗“发句好尤难得”（宋严羽《沧浪诗话》）。这首诗中的第一句就是不同凡响的，那两个“笼”字就很引人注目。“烟”、“水”、“月”、“沙”四者，被两个“笼”字和谐地融合在一起，绘成一幅极其淡雅的水边夜色。它是那么柔和幽静，而又隐含...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389aecdc25963feee1ab7", "shortContent": "建康（今江苏南京）是六朝都城，秦淮河穿过城中流入长江，两岸酒家林立，是当时豪门贵族、官僚士大夫享乐游宴的场所。唐王朝的都城虽不在建康，然而秦淮河两岸的景象却一如既往。\n\n有人说作诗“发句好尤难得”（宋严羽《沧浪诗话》）。这首诗中的第一句就是不同凡响的，那两个“笼”字就很引人注目。“烟”“水”“月”“沙”四者，被两个“笼”字和谐地融合在一起，绘成一幅极其淡雅的水边夜色。它是那么柔和幽静，而又隐含着微...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f497ccdb86c49f290f9", "shortContent": "秦淮河流经金陵一段，自六朝以来，一直是商旅集散之地，河两岸秦楼楚馆林立，至唐末杜牧的时代繁华亦不减当年。如果说金陵在六朝时期的兴衰史足以证明世事的反复无常，那么秦淮河的繁华不减，似乎又给人某种启示。《泊秦淮》要表达的便是作者途经此地所触发的怀古意绪。\n\n诗的首句描绘了秦淮河的夜景：月光淡淡，烟水迷蒙，风景如画。第二句叙事，补足前句，说明景色为夜泊所见；又引起下文，说明商女所唱，是因为“近酒家”才得...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270787ccdb86c49f29280", "shortContent": "秦淮河流经金陵一段，自六朝以来，一直是商旅集散之地，河两岸秦楼楚馆林立，至唐末杜牧的时代繁华不减当年。如果说金陵在六朝时期的兴衰史足以证明世事的反复无常，那么秦淮河的繁华不减，似乎又给人某种启示。《泊秦淮》要表达的便是作者途经此地所触发的怀古意绪。\n\n诗的首句描绘了秦淮河的夜景：月光淡淡，烟水迷濛，风景如画。第二句叙事，补足前句，说明景色为夜泊所见。又引起下文，说明商女所唱，是因为“近酒家”才得以...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312713e73206168b2e022d8", "shortContent": "秦淮河流经金陵一段，自六朝以来，一直是商旅集散之地，河两岸秦楼楚馆林立，至唐末杜牧的时代繁华不减当年。如果说金陵在六朝时期的兴衰史足以证明世事的反复无常，那么秦淮河的繁华不减，似乎又给人某种启示。《泊秦淮》要表达的便是作者途经此地所触发的怀古意绪。\n\n晚唐诗人中，擅长表达细腻绵长感情的诗人，除李商隐外，便要数杜牧了。这首七绝，尽管只有短短二十八个字，却将情人离别时缠绵悱恻、悲切流转的复杂情绪描摹得...", "authors": ["乐云", "杨军"], "pressName": "崇文书局"}, {"bookId": "645d0ac98258810260dbe044", "bookTitle": "杜牧诗文鉴赏辞典", "articleId": "6461dfe9cd12b001c6da2ae9", "shortContent": "建康（今江苏南京）是六朝都城，秦淮河穿过城中流入长江，两岸酒家林立，是当时豪门贵族、官僚士大夫享乐游宴的场所。唐王朝的都城虽不在建康，然而秦淮河两岸的景象却一如既往。\n\n有人说作诗“发句好尤难得”（宋严羽《沧浪诗话》）。这首诗中的第一句就是不同凡响的，那两个“笼”字就很引人注目。“烟”“水”“月”“沙”四者，被两个“笼”字和谐地融合在一起，绘成一幅极其淡雅的水边夜色。它是那么柔和幽静，而又隐含着微...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471f984e49f46528adda3db", "shortContent": "商女，是侍候他人的歌女。她们唱什么是由听者的趣味而定，可见诗说“商女不知亡国恨”，乃是一种曲笔，真正“不知亡国恨”的是那座中的欣赏者———封建贵族、官僚、豪绅。《后庭花》，即《玉树后庭花》，据说是南朝荒淫误国的陈后主所制的乐曲。这靡靡之音，早已使陈朝寿终正寝了。可是，如今又有人在这衰世之年，不以国事为怀，反用这种亡国之音来寻欢作乐，这怎能不使诗人产生历史又将重演的隐忧呢！“隔江”二字，承上“亡国恨...", "authors": ["侧"], "pressName": "上海辞书出版社"}]', '《唐诗正声》：吴逸一曰：国已亡矣，时靡靡之音深入人心，孤泊骤闻，自然兴慨。
《批点唐诗正声》：写景命意俱妙，绝处怨体反言，与诸作异。
《增订评注唐诗正声》：周云：亡国之音，自不堪听，又当此景。
《唐诗选脉会通评林》：周弼为用事体。何仲德为熔意体。
《唐诗绎》：首句写景荒凉，已为“亡国恨”钩魂摄魄。三四推原亡国之故，妙就现在所闻犹是亡国之音感叹，索性用“不知”二字，将“亡国恨”三字扫空，文心幻曲。
《而庵说唐诗》：“烟笼寒水”，水色碧，故云“烟笼”。“月笼沙”，沙色白，故云“月笼”。下字极斟酌。夜泊秦淮、而与酒家相近，酒家临河故也。商女，是以唱曲作生涯者，唱《后庭花》曲，唱而已矣，那知陈后主以此亡国，有恨于其内哉！杜牧之隔江听去，有无限兴亡之感，故作是诗。
《唐诗别裁》：绝唱。
《网师园唐诗笺》：后之咏秦淮者，更从何处措词？
《诗法易简录》：首句写秦淮夜景。次句点明夜泊，而以“近酒家”三字引起后二句。“不知”二字感慨最深，寄托甚微。通首音节神韵，无不入妙，宜沈归愚叹为绝唱。
《唐诗笺要》：盱目刺怀，含毫不尽。“千里枫树烟雨深，无朝无暮听猿吟”，凄不过此。
《读雪山房唐诗序例》：王阮亭司寇删定洪氏《唐人万首绝句》，以王维之《渭城》、李白之《白帝》、王昌龄之“奉帚平明”、王之涣之“黄河远上”为压卷，韪于前人之举“蒲萄美酒”、“秦时明月”者矣。近沈归愚宗伯亦效举数首以续之。今按其所举，惟杜牧“烟笼寒水”一首为角。
《唐绝诗钞注略》：何焯云：发端一片亡国恨。王尧冲云：“近酒家”，歌声所由来矣。
《诗式》：首句状景起。烟、水色青，故“烟笼水”；月、沙色白，故“月笼沙”：此秦淮景色也。次句点“泊秦淮”。泊近酒家，为下商女唱曲之所从来处，已伏三句之根。三句变换，四句发之，谓杜牧听隔江歌声。知《玉树后庭花》曲系陈后主亡国之音，足动兴亡之感，而商女不知曲中有恨，但唱曲而已。
《诗境浅说续编》：《后庭》一曲，在当日琼枝璧月之场，狎客传笺，纤儿按拍，无愁之天子，何等繁荣！乃同此珠喉清唱，付与秦淮寒夜，商女重唱，可胜沧桑之感？……独有孤舟行客，俯仰兴亡，不堪重听耳。
《唐人绝句精华》：首二句写夜泊之景。三句非责商女，特借商女犹唱《后庭花》曲以叹南朝之亡耳。六朝之局，以陈亡而结束，诗人用意自在责陈后主君臣轻荡，致召危亡也。', 'center', 1417685378, '57b90eed5bbb50005b7898c8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10675, '寄扬州韩绰判官', NULL, 439, 501, 1, 5, '杜牧', NULL, 10109, '57b9836cc4c971005593dfec', '唐', 'shi', '诗', 'http://baike.baidu.com/view/160007.htm', '', '青山隐隐水迢迢，秋尽江南草未凋。
二十四桥明月夜，玉人何处教吹箫。', '此诗为唐代诗人杜牧之离开扬州後怀念昔日同僚韩绰判官而作。诗中着意刻画深秋的扬州依然绿水青山、草木葱茏，二十四桥月夜仍然乐声悠扬，调侃友人生活的闲逸，表达了作者对过往扬州生活的深情怀念。全诗意境优美，清丽俊爽，情趣盎然。', '韩绰：事不详，杜牧之另有《哭韩绰》诗。
判官：观察使、节度使的属官。时韩绰似任淮南节度使判官。
迢迢：指江水悠长遥远。一作「遥遥」。
草未凋（diāo）：一作「草木凋」。凋：凋谢。
二十四桥：一说为二十四座桥。北宋·沈存中《梦溪笔谈·补笔谈·卷三》中对每座桥的方位和名称一一做了记载。一说有一座桥名叫二十四桥，清·李艾塘《扬州画舫录·卷十五》：「廿四桥即吴家砖桥，一名红药桥，在熙春台後，……扬州鼓吹词序云，是桥因古二十四美人吹箫于此，故名。」
玉人：貌美之人。这里是杜牧对韩绰的戏称。一说指扬州歌妓。', '青山隐隐约约绿水千里迢迢，秋时已尽江南草木还未枯凋。
二十四桥明月映照幽幽清夜，你这美人现在何处教人吹箫？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d8dbb8b379ee095d1f", "shortContent": "扬州之盛，唐世艳称，历代诗人为它留下了多少脍炙人口的诗篇。这首诗风调悠扬，意境优美，千百年来为人们传诵不衰。韩绰不知何人，杜牧集中赠他的诗共有两首，另一首是《哭韩绰》，看来两人友情甚笃。杜牧于大和七年至九年间（833—835）曾在淮南节度使牛僧孺幕中作推官，后来转为掌书记。这首诗当作于他离开扬州以后。\n此诗首句从大处落墨，化出远景：青山逶迤，隐于天际；绿水如带，迢递不断。“隐隐”和“迢迢”这一对叠...", "authors": ["葛晓音"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389aecdc25963feee1ab8", "shortContent": "扬州之盛，唐世艳称，历代诗人为它留下了多少脍炙人口的诗篇。这首诗风调悠扬，意境优美，千百年来为人们传诵不衰。韩绰不知何人，杜牧集中赠他的诗共有两首，另一首是《哭韩绰》，看来两人友情甚笃。杜牧于大和七年至九年间（833—835）曾在淮南节度使牛僧孺幕中作推官，后来转为掌书记。这首诗当作于他离开扬州以后。\n\n此诗首句从大处落墨，化出远景：青山逶迤，隐于天际；绿水如带，迢递不断。“隐隐”和“迢迢”这一对...", "authors": ["葛晓音"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f497ccdb86c49f290fa", "shortContent": "唐朝时扬州之盛况，世所共称，所谓“扬一益二”，扬州以其独特魅力向世人呈现出一派旖旎繁华景象。杜牧年轻时在扬州做官，留下过诸多美好的青春记忆，感受自是非同一般。譬如其歌咏扬州之诗句有“谁家唱《水调》，明月满扬州”（《扬州三首》其一），“谁知竹西路，歌吹是扬州”（《题扬州禅智寺》），“春风十里扬州路，卷上珠帘总不如”（《赠别》），“十年一觉扬州梦，赢得青楼薄幸名”（《遣怀》），足见诗人对于扬州的偏爱。...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270789761253910e90559", "shortContent": "唐朝时扬州之盛况，世所共称，所谓“扬一益二”，扬州以其独特魅力向世人呈现出一派旖旎繁华景象。杜牧年少时在扬州做官，留下过诸多美好的青春记忆，感受自是非同一般。譬如其歌咏扬州之诗句有“谁家唱《水调》，明月满扬州”，“谁知竹西路，歌吹是扬州”，“春风十里扬州路，卷上珠帘总不如”，“十年一觉扬州梦，赢得青楼薄幸名”，足见诗人对于扬州的偏爱。\n\n诗题“寄扬州韩绰判官”，表明该诗乃题赠一位叫韩绰的判官朋友。...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312713e73206168b2e022df", "shortContent": "唐朝时扬州之盛况，世所共称，所谓“扬一益二”，扬州以其独特魅力向世人呈现出一派旖旎繁华景象。杜牧年少时在扬州做官，留下过诸多美好的青春记忆，感受自是非同一般。譬如其歌咏扬州之诗句有“谁家唱《水调》，明月满扬州”，“谁知竹西路，歌吹是扬州”，“春风十里扬州路，卷上珠帘总不如”，“十年一觉扬州梦，赢得青楼薄幸名”，足见诗人对于扬州的偏爱。\n诗题“寄扬州韩绰判官”，表明该诗乃题赠一位叫韩绰的判官朋友。判...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645d0ac98258810260dbe044", "bookTitle": "杜牧诗文鉴赏辞典", "articleId": "6461e1775e6bb82b8cb80d64", "shortContent": "扬州之盛，唐世艳称，历代诗人为它留下了多少脍炙人口的诗篇。这首诗风调悠扬，意境优美，千百年来为人们传诵不衰。韩绰不知何人，杜牧集中赠他的诗共有两首，另一首是《哭韩绰》，看来两人友情甚笃。杜牧于大和七年至九年间（833—835）曾在淮南节度使牛僧孺幕中作推官，后来转为掌书记。这首诗当作于他离开扬州以后。\n\n此诗首句从大处落墨，化出远景：青山逶迤，隐于天际；绿水如带，迢递不断。“隐隐”和“迢迢”这一对...", "authors": ["葛晓音"], "pressName": "上海辞书出版社"}]', '《注解选唐诗》：情虽切而辞不露。
《唐诗品汇》：刘云：韩之风致可想，书记薄幸自道耳。
《升庵诗话》：唐诗绝句，今本多误字……《寄扬州韩绰判官》云「秋尽江南草未凋」，俗本作「草木凋」。秋尽而草木凋，自是常事，不必说也；况江南地暖，草本不凋乎！此诗杜牧在淮南而寄扬州者，盖厌淮南之摇落，而羡江南之繁华。若作「草木凋」，则与「青山明月」、「玉人吹箫」不是一套事矣。余戏谓此二诗（另一指《江南春》）绝妙，「十里莺啼」，俗人添一撇坏了；「草未凋」，俗人减一画坏了。甚矣，士俗不可医也！
《批点唐音》：优柔平实，有似中唐。
《唐诗选脉会通评林》：胡次焱曰：对草木凋谢之秋，思月桥吹箫之夜，寂寞之恋喧哗，始不胜情。「何处」二字最佳。陆时雍曰：杜牧七言绝句，婉转多情，韵亦不乏，自刘梦得以後一人。牧之诗有「十年一觉扬州梦」之句，素恋其景物奇美。此不过谓韩判官当此零落之候，教箫于月中，不知「二十四桥」之夜在于何处？含无限意绪耳。
《唐诗摘钞》：作「草未凋」，本句始有意；若作「木」字，读之索然矣……扬州本行乐之地，故以此（按指「玉人」句）讯韩，言外有羡之意。
《唐诗笺注》：「十年一觉扬州梦」，牧之于扬州绻恋久矣。「二十四桥」一句，有神往之致，借韩以发之。
《精选评注五朝诗学津梁》：风流秀曼，一片精神。
《历代诗发》：丰神摇曳。
《唐贤小三昧集续集》：只此七字，便已妙绝（末句下）。
《唐人万首绝句选评》：深情高调，晚唐中绝作，可以媲美盛唐名家。
《唐诗三百首》：二语与谪仙「烟花三月」七字，皆千古丽句（末二句下）。
《唐绝诗钞注略》：《天禄识馀》：「教」、「学」，古文通用。唐人「玉人」云云，乃学吹箫也。唐诗中「教」字皆乎用，无去声字；且「学吹箫」煞有风致，「教吹箫」有何意味耶？', 'center', 1417685434, '57b343c58ac247005f23a2b7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10676, '秋夕', NULL, 1245, 501, 2, 10, '杜牧', NULL, 10109, '57b9836cc4c971005593dfec', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/154727/5805082.htm', '', '银烛秋光冷画屏，轻罗小扇扑流萤。
天阶夜色凉如水，坐看牵牛织女星。', '这是一首宫怨诗，描写一名孤单的宫女，于七夕之夜，仰望天河两侧的牛郎织女，不时扇扑流萤，排遣心中寂寞，反映了宫廷妇女不幸的命运，表现了一位宫女举目无亲、百无聊赖的苦闷心情。', '秋夕：秋天的夜晚。
银烛：银色而精美的蜡烛。银，一作「红」。
画屏：画有图案的屏风。
轻罗小扇：轻巧的丝质团扇。
流萤：飞动的萤火虫。
天阶：露天的石阶。天，一作「瑶」。
坐看：坐着朝天看。坐，一作「卧」。
牵牛织女星：两个星座的名字，指牵牛星、织女星。亦指古代神话中的人物牵牛和织女。', '在秋夜里烛光映照着画屏，手拿着小罗扇扑打萤火虫。
夜色里的石阶清凉如冷水，静卧寝宫凝视牛郎织女星。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d9911759740c9b1ca4", "shortContent": "这诗写一个失意宫女的孤独生活和凄凉心情。\n前两句已经描绘出一幅深宫生活的图景。在一个秋天的晚上，白色的蜡烛发出微弱的光，给屏风上的图画添了几分暗淡而幽冷的色调。这时，一个孤单的宫女正用小扇扑打着飞来飞去的萤火虫。“轻罗小扇扑流萤”，这一句十分含蓄，其中含有三层意思：第一，古人说腐草化萤，虽然是不科学的，但萤总是生在草丛冢间那些荒凉的地方。如今，在宫女居住的庭院里竟然有流萤飞动，宫女生活的凄凉也就可...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9820695e6503ffe8", "shortContent": "这诗写一个失意宫女的孤独生活和凄凉心情。\n\n前两句已经描绘出一幅深宫生活的图景。在一个秋天的晚上，白色的蜡烛发出微弱的光，给屏风上的图画添了几分暗淡而幽冷的色调。这时，一个孤单的宫女正用小扇扑打着飞来飞去的萤火虫。“轻罗小扇扑流萤”，这一句十分含蓄，其中含有三层意思：第一，古人说腐草化萤，虽然是不科学的，但萤总是生在草丛冢间那些荒凉的地方。如今，在宫女居住的庭院里竟然有流萤飞动，宫女生活的凄凉也就...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4dc26cbf3417f09390", "shortContent": "这首诗通过描写宫女的生活场景，委婉含蓄地表现了她生活的孤独和内心的苦闷。在一个秋天的晚上，淡淡的月光照进宫中，白色的蜡烛发出微弱的光。烛光、月光映照在画屏上，给屏风上的图画添了几分暗淡、幽冷的色调。诗的首句渲染了环境的冷寂，接着描绘诗中人的活动：她是这座宫殿的“主人”，正手持轻罗小扇，在庭院里追扑飞来飞去的萤火虫。\n\n萤火虫本是生活在草木丛生的阴湿之地的，现在宫女住的地方竟然有流萤飞动，这就进一步...", "authors": ["杨军"], "pressName": "崇文书局"}, {"bookId": "645d0ac98258810260dbe044", "bookTitle": "杜牧诗文鉴赏辞典", "articleId": "6461e48a5e6bb82b8cb81f02", "shortContent": "这诗写一个失意宫女的孤独生活和凄凉心情。\n\n前两句已经描绘出一幅深宫生活的图景。在一个秋天的晚上，白色的蜡烛发出微弱的光，给屏风上的图画添了几分暗淡而幽冷的色调。这时，一个孤单的宫女正用小扇扑打着飞来飞去的萤火虫。“轻罗小扇扑流萤”，这一句十分含蓄，其中含有三层意思：第一，古人说腐草化萤，虽然是不科学的，但萤总是生在草丛冢间那些荒凉的地方。如今，在宫女居住的庭院里竟然有流萤飞动，宫女生活的凄凉也就...", "authors": ["袁行霈"], "pressName": "上海辞书出版社"}]', '《冷斋夜话》：（诗）有意含蓄者，如《宫词》曰：「银烛秋光冷画屛……」。
《艇斋诗话》：小杜《秋夜》宫词云：「银烛秋光冷画屛……」含蓄有思致。星象甚多，而独言牛女，此所以见其为宫词也。
《注解选唐诗》：此诗为宫中怨女作也。牵牛织女，一年一会，秦宫人望幸，至有三十六年不得见者。「卧看牵牛织女星」，隐然说一生不蒙幸，愿如牛女一夕之会，亦不可得。怨而不怒，真风人之诗。
《唐诗正声》：吴逸一评：词亦浓丽，意却凄婉。末句玩「看」字。
《增订评注唐诗正声》：杨云：幽怨自见。郭云：小妆点，入诗馀便为佳境。落句似浅。
《唐诗镜》：冷然情致。「坐看」不若「卧看」佳。
《唐诗选脉会通评林》：同弼为直接体。
《删订唐诗解》：吴昌祺曰：隽而小。
《三体唐诗评》：崔颢《七夕》后四句公：「长信秋深夜转幽，瑶阶金阁数萤流。班姬此夕愁无限，河汉三更看斗牛。」此篇点化其意。次句再用团扇事，亦浑成无迹。
《唐诗摘钞》：《苕溪渔隐》云：此诗断句极佳，意在言外，其幽怨之情不待明言而见也。敖清江云：落句即牛女会合之难，喻君臣际会之难。
《增订唐诗摘钞》：烛光屛冷，情之所由生也。扑萤以戏，写忧也。看牛女，羡之也。
《载酒园诗话又编》：亦即「参昴衾裯」之义。但古人兴意在前，此倒用于后。昔人感叹中犹带庆幸，故情辞悉露，此诗全写凄凉，反多含蓄。
《精选评注五朝诗学津梁》：细腻熨贴，善写秋夕家庭。
《唐人万首绝句选评》：诗中不着一意，言外含情无限。
《唐诗三百首》：层层布景，是一幅着色人物画。只「坐看」二字逗出情思，便通身灵动。
《唐诗评注读本》：此宫中秋怨诗也，自初夜写至夜深，层层绘出，宛然为宫人作一幅幽怨图。
《诗境浅说续编》：为秋闺咏七夕情事。前三句写景极清丽，宛若静院夜凉，见伊人逸致。结句仅言坐看双星，凡离合悲欢之迹，不着毫端，而闺人心事，尽在举头坐看之中。
《唐人绝句精华》：此亦闺情诗也。不明言相怨之情，但以七夕牛女会合之期，坐看不睡，以见独处无郎之意。', 'center', 1417685504, '57b8f7c80a2b58005c91ff85', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10677, '赠别 其一', NULL, 532, 501, 2, 4, '杜牧', NULL, 10109, '57b9836cc4c971005593dfec', '唐', 'shi', '诗', 'http://baike.baidu.com/view/9375819.htm', '', '娉娉袅袅十三余，豆蔻梢头二月初。
春风十里扬州路，卷上珠帘总不如。', '此诗为杜牧《赠别》组诗的第一首，是诗人在大和九年（公元835年），调任监察御史，离扬州赴长安时，与歌女分别之作。诗中着重写其美丽，赞扬她是扬州歌女中美艳第一。首句描摹少女身姿体态，妙龄丰韵；二句以花喻人，写她娇小秀美；三、四两句，以星拱月，写扬州佳丽极多，唯她独俏。手法上强此弱彼，大有「除却巫山不是云」之概。语言精萃麻利，挥洒自如，情感真挚明朗，荡然肺腑。', '豆蔻：喻处女，后因称十三四岁女子为豆蔻年华。', '姿态美好举止轻盈正是十三年华，
活像二月初含苞待放一朵豆蔻花。
看遍扬州城十里长街的青春佳丽，
卷起珠帘卖俏粉黛没有比得上她。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d82cee9a0c24ecface", "shortContent": "文学艺术要不断求新，因陈袭旧是无出息的。即使形容取喻，也贵独到。从这个角度看看杜牧《赠别》，也不能不承认他做诗的“天才”。\n此诗是诗人赠别一位相好的歌妓的，从同题另一首（“多情却似总无情”）看，彼此感情相当深挚。不过那一首诗重在“惜别”，这一首却重在赞颂对方的美丽，引起惜别之意。第一句就形容了一番：“娉娉袅袅”是身姿轻盈美好的样子，“十三馀”则是女子的芳龄。七个字中既无一个人称，也不沾一个名词，却...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4dc26cbf3417f09391", "shortContent": "【其一】\n\n《赠别》为诗人即将离开扬州时赠别一位相好的歌妓所写的组诗。诗一共有两首，此为其一，意在赞美歌妓的美丽，从而引起惜别之情。\n\n首句用“娉娉袅袅”来形容这位女子的身姿轻盈婀娜之态。“十三余”则指女子的芳龄。既赞歌妓之美，却不从相貌容颜入手，而抓住她的身材与年龄着眼。身姿是风流袅娜的，年龄是含胎待放的，由此，美人的形象呼之欲出。\n\n二句“豆蔻梢头二月初”，以花喻美人，本来易落入俗套，但诗人此...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270787ccdb86c49f2927e", "shortContent": "此诗为诗人即将离开扬州时赠别一位相好的歌妓所写。诗一共有两首，此为其一，意在赞美歌妓的美丽，从而引起惜别之情。\n\n首句用“娉娉袅袅”来形容这位女子的身姿轻盈婀娜之态。“十三余”则指女子的芳龄。既赞歌妓之美，却不从相貌容颜入手，而抓住她的身材与年龄着眼。身姿是风流袅娜的，年龄是含苞待放的，由此，美人的形象呼之欲出。\n\n二句“豆蔻梢头二月初”，以花喻美人，本来易落入俗套，但诗人此处却新意迭出，以二月之...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312713e73206168b2e022d7", "shortContent": "其一\n此诗为诗人即将离开扬州时赠别一位相好的歌妓所写。诗一共有两首，此为其一，意在赞美歌妓的美丽，从而引起惜别之情。\n首句用“娉娉袅袅”来形容这位女子的身姿轻盈婀娜之态。“十三余”则指女子的芳龄。既赞歌妓之美，却不从相貌容颜入手，而抓住她的身材与年龄着眼。身姿是风流袅娜的，年龄是含苞待放的，由此，美人的形象呼之欲出。\n二句“豆蔻梢头二月初”，以花喻美人，本来易落入俗套，但诗人此处却新意迭出，以二月...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645d0ac98258810260dbe044", "bookTitle": "杜牧诗文鉴赏辞典", "articleId": "6461e21e5b7b0d4f45051af8", "shortContent": "文学艺术要不断求新，因陈袭旧是无出息的。即使形容取喻，也贵独到。从这个角度看看杜牧《赠别》，也不能不承认他作诗的“天才”。\n\n此诗是诗人赠别一位相好的歌妓的，从同题另一首（“多情却似总无情”）看，彼此感情相当深挚。不过那一首诗重在“惜别”，这一首却重在赞颂对方的美丽，引起惜别之意。第一句就形容了一番：“娉娉袅袅”是身姿轻盈美好的样子，“十三余”则是女子的芳龄。七个字中既无一个人称，也不沾一个名词，...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '', 'center', 1417685615, '57b8d83ddf0eea0063341ebe', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10678, '赠别', NULL, 279, 501, 2, 2, '杜牧', NULL, 10109, '57b9836cc4c971005593dfec', '唐', 'shi', '诗', 'http://baike.baidu.com/view/3252014.htm', '', '多情却似总无情，唯觉樽前笑不成。
蜡烛有心还惜别，替人垂泪到天明。', '这是杜樊川《赠别》组诗的第二首，是诗人在大和九年（西元八三五年），调任监察御史，离扬州赴长安，与妓女分别之作，描绘与她的筵席上难分难舍的情怀。
这一首着重写惜别，描绘与她的筵席上难分难舍的情怀。首名写离筵之上压抑无语，似乎冷淡无情；次句以「笑不成」点明原非无情，而是郁悒感伤，实乃多情，回应首句。
齐、梁之间的江淹曾经把离别的感情概括为「黯然销魂」四字。但这种感情的表现，却因人因事的不同而千差万别，这种感情本身，也不是「悲」、「愁」二字所能了得。杜牧此诗不用「悲」、「愁」等字，却写得坦率、真挚，道出了离别时的真情实感。
诗人同所爱不忍分别，又不得不分别，感情是千头万绪的。「多情却似总无情」，明明多情，偏从「无情」着笔，著一「总」字，又加强了语气，带有浓厚的感情色彩。诗人爱得太深、太多情，以至使他觉得，无论用怎样的方法，都不足以表现出内心的多情。别筵上，凄然相对，像是彼此无情似的。越是多情，越显得无情，这种情人离别时最真切的感受，诗人把它写出来了。「唯觉樽前笑不成」，要写离别的悲苦，他又从「笑」字入手。一个「唯」字表明，诗人是多么想面对情人，举樽道别，强颜欢笑，使所爱欢欣！但因为感伤离别，却挤不出一丝笑容来。想笑是由于「多情」，「笑不成」是由于太多情，不忍离别而事与愿违。这种看似矛盾的情态描写，把诗人内心的真实感受，说得委婉尽致，极有情味。
题为「赠别」，当然是要表现人的惜别之情。然而诗人又撇开自己，去写告别宴上那燃烧的蜡烛，借物抒情。诗人带着极度感伤的心情去看周围的世界，于是眼中的一切也就都带上了感伤色彩。这就是刘勰所说的：「属采附声，亦与心而徘徊」（《文心雕龙·物色》）。「蜡烛」本是有烛芯的，所以说「蜡烛有心」；而在诗人的眼里烛芯却变成了「惜别」之心，把蜡烛拟人化了。在诗人的眼里，它那彻夜流溢的烛泪，就是在为男女主人的离别而伤心了。「替人垂泪到天明」，「替人」二字，使意思更深一层。「到天明」又点出了告别宴饮时间之长，这也是诗人不忍分离的一种表现。
诗人用精炼流畅、清爽俊逸的语言，表达了悱恻缠绵的情思，风流蕴藉，意境深远，馀韵不尽。就诗而论，表现的感情还是很深沉、很真挚的。杜牧为人刚直有节，敢论列大事，却也不拘小节，好歌舞，风情颇张，本诗亦可见此意。', '', '聚首如胶似漆作别却像无情；只觉得酒筵上要笑笑不出声。
案头蜡烛有心它还依依惜别；你看它替我们流泪流到天明。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92d85914587d02f4e92a", "shortContent": "这一首抒写诗人对妙龄歌女留恋惜别的心情。\n齐、梁之间的江淹曾经把离别的感情概括为“黯然销魂”四字。但这种感情的表现，却因人因事的不同而千差万别；这种感情本身，也不是“悲”、“愁”二字所能了得。杜牧此诗不用“悲”、“愁”等字，却写得坦率、真挚，道出了离别时的真情实感。\n诗人同所爱不忍分别，又不得不分别，感情是千头万绪的。“多情却似总无情”，明明多情，偏从“无情”着笔；著一“总”字，又加强了语气，带有...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389aecdc25963feee1ab9", "shortContent": "这一首抒写诗人对妙龄歌女留恋惜别的心情。\n\n齐、梁之间的江淹曾经把离别的感情概括为“黯然销魂”四字。但这种感情的表现，却因人因事的不同而千差万别；这种感情本身，也不是“悲”“愁”二字所能了得。杜牧此诗不用“悲”“愁”等字，却写得坦率、真挚，道出了离别时的真情实感。\n\n诗人同所爱不忍分别，又不得不分别，感情是千头万绪的。“多情却似总无情”，明明多情，偏从“无情”着笔；著一“总”字，又加强了语气，带有...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "631270787ccdb86c49f2927f", "shortContent": "如果说前一首诗是以饱含深情的笔调赞美爱人娇憨可爱的话，那么这首诗则将浓浓的离情别意呈现在我们面前。\n\n关于离别，齐梁诗人江淹曾经咏叹出千古名句：“黯然销魂者，惟别而已矣。”不过，对于不同的时空变幻，不同的人物境遇来说，其黯然之处却不尽相同。此诗写诗人因仕途失意而被迫与朝思暮想的爱人分别，其内心的不舍与缠绵自是常人难以体味。\n\n一、二句以“多情”与“无情”这一矛盾心境对比，足见诗人匠心独具。一对恩爱...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "645d0ac98258810260dbe044", "bookTitle": "杜牧诗文鉴赏辞典", "articleId": "6461e28945e4710056b809f3", "shortContent": "这一首抒写诗人对妙龄歌女留恋惜别的心情。\n\n齐、梁之间的江淹曾经把离别的感情概括为“黯然销魂”四字。但这种感情的表现，却因人因事的不同而千差万别；这种感情本身，也不是“悲”“愁”二字所能了得。杜牧此诗不用“悲”“愁”等字，却写得坦率、真挚，道出了离别时的真情实感。\n\n诗人同所爱不忍分别，又不得不分别，感情是千头万绪的。“多情却似总无情”，明明多情，偏从“无情”着笔；著一“总”字，又加强了语气，带有...", "authors": ["张燕瑾"], "pressName": "上海辞书出版社"}]', '', 'center', 1417685856, '57b932797db2a200542843e5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (68294, '题顾氏长江图', NULL, 0, 310, 0, 1, '戴良', NULL, 11600, '5858e69d75c4cd65cbee77b3', '元', 'shi', '诗', '', '', '天下几人画山水，虎头子孙世莫比。
何年写此《长江图》，多少江山归笔底。
巴陵三峡天所开，远势似向岷峨来。
洞庭潇湘仅毫末，楚客湘君安在哉？江上一朝风雨急，老
我曾来踏舟立。
鼓枻既闻潭畔吟，抱琴复听竹间泣。
别来几日世已非，忽此披图忆曩时。
早知避地多处所，昔逐红尘千里归。
林下一夫巾屦似，亦有舟人与渔子。
能添野老烟波里，便与同生复同死。 ', '', '', '', NULL, '', 'indent', 1555497811, '585cff7a1b69e600560f53bf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10680, '寄令狐郎中', NULL, 110, 603, 1, 2, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/view/181964.htm', '', '嵩云秦树久离居，双鲤迢迢一纸书。
休问梁园旧宾客，茂陵秋雨病相如。', '这是诗人闲居洛阳时所作。这首诗以感谢故人关心之名籍以修好，意在不言，诗中有感念旧恩故交之意，却无卑屈趋奉之态；有感慨身世落寞之辞，却无乞援望荐之意；情意虽谈不上浓至深厚，却比较真诚，表现了诗人与友人之间平等而真诚的关系。', '令狐郎中：即令狐绹，其时在朝中任考功郎中。
嵩：嵩山，在今河南省。
秦：指今陕西。意即一在洛阳（作者），一在长安（令狐绹）。
双鲤：指书信。古乐府《饮马长城窟行》：“客从远方来，遗我双鲤鱼。呼童烹鲤鱼，中有尺素书。”
迢迢：遥远的样子。
休问：别问。
梁园：汉梁孝王刘武的园林，此喻指楚幕，司马相如等文士都曾客游梁园。此处比喻自己昔年游于令狐门下。
茂陵：在今陕西省兴平县东北，以汉武帝陵墓而得名。司马相如因患病，家居茂陵，作者此时也卧病洛阳。', '情谊缱绻，只因为我们天各一方，无奈的山高路远，却欣喜你珍贵的书信，慰藉我落寞的思念。
不要问我的遭遇，我是梁园的旧客，病卧在茂陵他乡，仿佛绵绵的秋雨，伤情绵绵，绵绵情伤。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dc5e272d4b225435a8", "shortContent": "这是会昌五年（845）秋天，作者闲居洛阳时回寄给在长安的旧友令狐绹的一首诗。令狐绹当时任右司郎中，所以题称“寄令狐郎中”。\n首句嵩、秦分指自己所在的洛阳和令狐所在的长安。“嵩云秦树”化用杜甫《春日忆李白》中即景寓情的名句：“渭北春天树，江东日暮云。”云、树是分居两地的朋友即目所见的景物，也是彼此思念之情的寄托。“嵩云秦树”之所以不能用“京华洛下”之类的词语替代，正是因为后者只说明京、洛离居的事实，...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d83f2af4e09d55b63dd", "shortContent": "义山与令狐绹很久没有往来，彼此关系也十分疏淡。故本篇无求于令狐，只有落漠和愁病的感叹。", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4dc26cbf3417f09394", "shortContent": "此诗是李商隐晚年退闲而作。李商隐一生困于牛李党争，自身实为党争中的一颗棋子，命运播迁，不由自主。他早年受知于令狐绹之父令狐楚，与令狐绚交游甚笃，后娶李德裕党王茂元之女为妻。令狐父子为牛僧孺党，与李党水火不容，李商隐在两党之间，成了“夹心人”，一生蹉跎。晚年的李商隐退居于故乡郑州，接到了少时挚友令狐绚的来信，感慨系之，写下了这首著名的诗篇。\n\n嵩云，指嵩山之云，李商隐退居于郑州，与嵩山相近，故曰“嵩...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64631bdc5e6bb82b8cbd24a3", "shortContent": "这是会昌五年（845）秋天，作者闲居洛阳时回寄给在长安的旧友令狐绹的一首诗。令狐绹当时任右司郎中，所以题称“寄令狐郎中”。\n\n首句嵩、秦分指自己所在的洛阳和令狐所在的长安。“嵩云秦树”化用杜甫《春日忆李白》中即景寓情的名句：“渭北春天树，江东日暮云。”云、树是分居两地的朋友即目所见的景物，也是彼此思念之情的寄托。“嵩云秦树”之所以不能用“京华洛下”之类的词语替代，正是因为后者只说明京、洛离居的事实...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '《唐涛绝句类选》：义山此诗落句以相如自况，此足用古事为今事。用死事为活事。
《增定评注唐诗正声》：以死事为活事，妙妙（首句下）。俗甚（“双鲤迢迢”句下）。于二鳞七绝多此句法（末句下）。
《唐涛解》：嵩云秦树，天各一方，所可达者唯书耳。然我秋雨抱疴，无足问也。
《唐诗选脉会通评林》：义山才华倾世，初见重于时相，每以梁园宾客自负，后因被斥，所向不如其志，故此托卧病茂陵以致慨。
《玉豁生诗意》：求荐达之意在言外。
《玉豁生诗笺注》：杨守智云：其词甚悲，意在修好。
《李义山诗集辑评》：纪昀曰：一唱三叹，格韵俱高。
《唐人万首绝句选评》：布置工妙，神昧隽永，绝句之正鹄也。
《诗境浅说续编》：义山与令狐相知久。退闲以后，得来书而却寄以诗，不作乞怜语，亦不涉觖望语，鬓丝病榻，犹回首前尘，得诗人温柔悲悱之旨。', 'center', 1417701462, '57b930d62e958a005fa6e485', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10681, '为有', NULL, 67, 603, 1, 1, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/view/167097.htm', '', '为有云屏无限娇，凤城寒尽怕春宵。
无端嫁得金龟婿，辜负香衾事早朝。', '此诗写闺怨，抒情主人公是一位富家女子，她嫁得意中人，夫妻恩爱，因而在云屏深处娇嗔缱绻，春宵苦短。偏偏丈夫要早起上朝，于是引起她“端”的抱怨，“辜负香衾”的怅恨。作品将夫妻厮守与事早朝对立起来，以无情写多情，以多情怨无情，心理刻画极为细致，风格含蓄深沉。', '云屏：云母屏风。指雕饰着云母图案的屏风，古代皇家或富贵人家所用。无限娇：称代娇媚无比的少妇。
凤城：此指京城。
无端：没来由。金龟婿：佩带金龟（即做官）的丈夫。《新唐书·车服志》：“天授二年，改佩鱼皆为龟，其后三品以上龟袋饰以金。”', '云母屏风后面的美人格外娇，京城寒冬已过却怕短暂春宵。
无端地嫁了个做高官的丈夫，不恋温暖香衾只想去上早朝。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dd5914587d02f4e948", "shortContent": "这首诗大约写作于会昌六年（846）至大中五年（851）之间，即李德裕罢相以后，诗人妻王氏去世之前。这段时间李商隐个人和家庭的处境都十分困难。\n诗歌描述的是一对宦家夫妇的怨情。开头用“为有”二字把怨苦的缘由提示出来。“云屏”，云母屏风，指闺房陈设富丽；“无限娇”称代娇媚无比的少妇。金屋藏娇，两情缱绻，当春风送暖，京城寒尽之时，便双双地怕起春宵来了。这个“怕”字用得蹊跷。丈夫既富且贵，妻子年轻貌美，两...", "authors": ["朱世英"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d81c305cf0801816b97", "shortContent": "本篇通过写贵家少妇内心的苦闷，揭示出富贵利禄与人性的矛盾。一二句谓因为有云母屏风的遮掩，闺中少妇如金屋藏娇；可是京城的寒冬已尽，春宵苦短，故令她忧惧也。三四句谓不料嫁给高官贵婿之后，反因贵婿常上早朝而不能贪享床上的温馨，辜负了香被的轻暖啊！世人从虚假中寻求幸福，不料虚假给世人带来痛苦。言外有刺，寓理于情，可与王昌龄的“悔教夫婿觅封侯”媲美。", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4dc26cbf3417f09395", "shortContent": "这是李商隐的一首立意尖新的诗。或以为是李商隐大中六年（852）补太学博士时作，清赵彦传《唐绝诗钞注略》：“程云：公《镜槛》诗云：‘岂能’、‘抛断’、‘梦听鼓’‘事朝珂’，即‘辜负’云云之意。按：据此，似大中六年，补太学博士作。”然而读李商隐诗如同猜谜者多矣，仅凭此证，无法确定此诗所作之时。\n\n首句“为有云屏无限娇”，云屏是用云母装饰的屏风或绘有云彩图饰的屏风，不管是哪一种，都是华贵之物。云屏之内，...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "64636253e49f46528aa0279f", "shortContent": "这首诗大约写作于会昌六年（846）至大中五年（851）之间，即李德裕罢相以后，诗人妻王氏去世之前。这段时间李商隐个人和家庭的处境都十分困难。\n\n诗歌描述的是一对宦家夫妇的怨情。开头用“为有”二字把怨苦的缘由提示出来。“云屏”，云母屏风，指闺房陈设富丽；“无限娇”称代娇媚无比的少妇。金屋藏娇，两情缱绻，当春风送暖，京城寒尽之时，便双双地怕起春宵来了。这个“怕”字用得蹊跷。丈夫既富且贵，妻子年轻貌美，...", "authors": ["朱世英"], "pressName": "上海辞书出版社"}]', '《李义山诗集辑评》：何焯曰：此与“悔教夫婿觅封侯”同意，而用意较尖刻。
《李义山诗集笺注》：姚培谦曰：此作细意体贴之词。“无端”二字下得妙，其不言之意应如此。
《玉溪生诗意》：屈复：玉溪以绝世香艳之才，终老幕职，晨入昏出，簿书无暇，与嫁贵婿、负香衾者何异？其怨宜也。
《玉溪生诗集笺注》：言外有刺。
《唐绝诗钞注略》：程云：公《镜槛》诗云：“岂能”、“抛断”、“梦听鼓”、“事朝珂”，即“辜负”云云之意。按：据此，似大中六年，补太学博士作。
《诗境浅说续编》：正闺人满志之时，乃转怨金阙之晓钟，破锦帏之同梦：人生欲望，安有满足之期！以诗而论，绮思妙笔，固《香屑集》中佳选也。', 'center', 1417701527, '57b97f027db2a20054f6b59c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10682, '隋宫', NULL, 29, 603, 1, 2, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/162817/9499233.htm', '', '乘兴南游不戒严，九重谁省谏书函。
春风举国裁宫锦，半作障泥半作帆。', '此诗选取典型题材，讽咏隋炀帝杨广奢侈嬉游之事。首二句写炀帝任兴恣游，肆行无忌，且滥杀忠谏之士，遂伏下杀身之祸。次二句取裁锦一事写其耗费之巨，将一人与举国、宫锦与障泥和船帆对比，突出炀帝之骄奢淫逸。然而全诗无一议论之语，于风华流美的叙述之中，暗寓深沉之虑，令人鉴古事而思兴亡。全诗在艺术方法上将实写与虚写巧妙地运用在一起，一实一虚展示了前朝皇帝与当朝皇帝的昏庸，讽刺意味浓厚，具有力度，此诗长于思想性，不失为政治讽刺诗佳作。', '隋宫：隋炀帝杨广建造的行宫。《舆地纪胜》：“淮南东路，扬州江都宫，炀帝于江都郡置宫，号江都宫。”《嘉庆一统志》：“江苏省扬州府古迹：临江宫在江都县南二十里，隋大业七年，炀帝升钓台临扬子津，大燕百僚，寻建临江宫于此。显福宫在甘泉县东北，隋城外离宫。……江都宫在甘泉县西七里，故广陵城内。中有成象殿，水精殿及流珠堂，皆隋炀帝建。……十宫在甘泉县北五里，隋炀帝建。”《寰宇记》：“十宫在江都县北五里，长阜苑内，依林傍涧，高跨冈阜，随城形置焉。曰归雁、回流、九里、松林、枫林、大雷、小雷、春草、九华、光汾。”
南游：隋炀帝为满足其荒淫享乐的欲望，曾多次巡游江都。不戒严：古代皇帝外出，要实行戒严，隋炀帝南游，为显示天下太平了自己的华贵气派，不加戒严。《晋书·舆服志》：“凡车驾亲戎，中外戒严。”此言不戒严，意谓炀帝骄横无忌，毫无戒备。
九重：指皇帝居住的深宫。省（xǐng）：明察，懂得。谏书函：给皇帝的谏书。《隋书·炀帝纪》载：隋炀帝巡游，大臣上表劝谏被杀数人，遂无人敢谏。公元618年（大业十四年），在行宫被其部下宇文化及所弑。
举国：全国。宫锦：按照宫廷规定的格式织成的供皇家使用的高级锦缎。
障泥：马鞯，垫在马鞍的下面，两边下垂至马蹬，用来挡泥土。《隋书·食货志》：“大业元年（605），造龙舟，凤榻、黄龙、赤舰、楼船、篾舫……幸江都……舳舻相接，二百余里。”', '隋炀帝为南游江都不顾安全，九重宫中有谁理会劝谏书函。
春游中全国裁制的绫罗锦缎，一半作御马障泥一半作船帆。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dd7d0ac11454953a6f", "shortContent": "这首七绝，通过精心的选材和独创性的构思，只用寥寥二十八字，就在惊人的广度和深度上揭露了隋炀帝杨广荒淫害民的反动本质。\n杨广当政十四年，把绝大部分时间用于佚游享乐。诗人举南游江都以概其余，已经显示了选材上的艺术匠心；又从三次南游江都中，抓住几个典型事例，略作点化，就收到了借一斑以窥全豹的艺术效果。\n开头两句先借南游刻画人物。第一句单刀直入，点明“南游”。而以“乘兴”作状语，展现了杨广贪图享乐、不惜民...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d7e73206168b2e01e80", "shortContent": "首联谓大军东征，朝廷日费万金，几乎用尽了中原的财力，以厚赏鼓舞士气。颔联谓朝廷赏罚不当，对败坏军纪者不绳之以法；对谎报军功者却给予赏赐。颈联谓假若只许贤臣在朝，岂容藩镇割据？尾联谓可惜沧、景地区经历战乱之后，尸骸遍野，愁云漫天，满目凄凉。本篇借隋炀帝东征高丽而言时事，批评朝廷号令不严，徒以赏赐贿赂将士，至使平叛战争久未成功，给国家和人民造成巨大损失。起句劲挺，结句沉痛。是诗人在天平军节度使令狐楚幕...", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d8b73206168b2e01eb0", "shortContent": "隋场帝在位十四年，居京不足一年，大部分年月出外淫游，其腐败昏暴在历史上最为突出。本篇一二句谓其轻狂和残暴，三四句谓其多次南游，耗尽民脂民膏。", "authors": [], "pressName": "崇文书局"}]', '何焯：借锦帆事点化，得水陆绎骚，民不堪命之状，如在目前。', 'center', 1417701664, '57b99dea5bbb500053485c9b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10683, '瑶池', NULL, 60, 603, 0, 1, '李商隐', NULL, 10009, '57b92a9fd342d3005ac88ad5', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/162644/5080999.htm', '', '瑶池阿母绮窗开，黄竹歌声动地哀。
八骏日行三万里，穆王何事不重来。', '晚唐迷信神仙之风极盛，最高统治者尤最，好几个皇帝因服丹药妄求长生而丧命。这首诗是借周穆王西游遇仙人西王母的神话，加以生发，讥刺皇帝求仙的虚妄。全诗虚构了西王母盼不到周穆王重来，暗示穆王已故的故事情节，显示了求仙妄想与死亡不可避免的对立。诗人不作正面议论，而却以西王母心中的疑问作诘。构思巧妙，用心良苦，讽刺辛辣，韵味无穷。', '瑶池阿母：《穆天子传》卷三：“天子宾于西王母，天子觞西王母于瑶池之上。西王母为天子谣曰：‘白云在天，山陵自出。道里悠远，山川间之。将子无死，尚能复来。’天子答之曰：‘予归东土，和治诸夏。万民平均，吾顾见汝。比及三年，将复而野。’”《武帝内传》称王母为“玄都阿母”。绮窗：绘饰如绮之窗户。吕向注：“绮窗，雕画若绮也。”
黄竹歌：逸诗，也作《黄竹诗》。《穆天子传》卷五：“丙辰，天子游黄台之丘，猎于苹泽，有阴雨，天子乃休。日中大寒，北风雨雪，有冻人。天子作诗三章以哀民。词曰‘我祖黄竹，囗员閟寒’云云。”按此借《黄竹》哀歌以寓穆王之崩。
八骏：传说周穆王有八匹骏马，可日行三万里。《列子》、《穆天子传》等记载不一。', '西王母在瑶池上把绮窗打开；
只听得黄竹歌声音动地悲哀。
八骏神马的车子日行三万里；
周穆王为了何事违约不再来？', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92dfd635634aee3def5b", "shortContent": "晚唐好几个皇帝迷信神仙之道，服食丹药，妄求长生，以至服金丹中毒死去。这首诗便是讽刺求仙之虚妄。\n瑶池是古代神话中仙人西王母居住的地方。诗中的“阿母”即西王母，《汉武故事》中称西王母为“玄都阿母”。据《穆天子传》记载：周穆王西游至昆仑山，遇西王母，西王母在瑶池设宴招待他。临别，西王母作歌赠之曰：“白云在天，山陵自出。道里悠远，山川间之。将（希望）子毋死，尚能复来。”穆王答歌曰：“比及三年，将复（返）...", "authors": ["王思宇"], "pressName": "上海辞书出版社"}, {"bookId": "6277fad376f8c26690f8ec57", "bookTitle": "李商隐诗全集", "articleId": "63126d8377683d1933014fc4", "shortContent": "前二句谓西王母在瑶池打开绮窗等待周穆王重来相会，她耳畔还留着《黄竹歌》的悲声，甚是思念。后二句谓穆王有八骏，西行并不困难，为何不再来呢？暗示穆王已死，求仙虚妄。", "authors": [], "pressName": "崇文书局"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4dc26cbf3417f09397", "shortContent": "本诗是李商隐的一首隐约幽微之作。\n\n《穆天子传》载，周穆王西游至昆仑山，西王母宴之于瑶池。临别，西王母为天子谣，曰：“白云在天，山陵自出。道里悠远，山川间之。将子无死，尚能复来？”天子答之，曰：“予归东土，和治诸夏。万民平均，吾顾见汝。比及三年，将复而野。”表示三年之后再来。诗作前两句说西王母在瑶池上把雕饰精美的窗户打开等待，只听得黄竹歌声音动地悲哀。瑶池，西王母所居之地。阿母，即西王母，《武帝内...", "authors": ["黄鸣"], "pressName": "崇文书局"}, {"bookId": "645d11d4e745e33de31320ff", "bookTitle": "李商隐诗文鉴赏辞典", "articleId": "646380e845e4710056bf5a4a", "shortContent": "晚唐好几个皇帝迷信神仙之道，服食丹药，妄求长生，以至服金丹中毒死去。这首诗便是讽刺求仙之虚妄。瑶池是古代神话中仙人西王母居住的地方。诗中的“阿母”即西王母，《汉武故事》中称西王母为“玄都阿母”。据《穆天子传》记载：周穆王西游至昆仑山，遇西王母，西王母在瑶池设宴招待他。临别，西王母作歌赠之曰：“白云在天，山陵自出。道里悠远，山川间之。将（希望）子毋死，尚能复来。”穆王答歌曰：“比及三年，将复（返）而...", "authors": ["王思宇"], "pressName": "上海辞书出版社"}]', '', 'center', 1417701756, '57b99df08ac2470062e52c1f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10684, '瑶瑟怨', NULL, 143, 394, 1, 3, '温庭筠', NULL, 10069, '57b93da179bc44005ba0a318', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383832.htm', '', '冰簟银床梦不成，碧天如水夜云轻。
雁声远过潇湘去，十二楼中月自明。', '此诗描绘的是抒情主人公寂寞难眠而鼓瑟听瑟的各种感受，以表达别离之怨。全诗像是几种衔接紧密的写景镜头，表现了女主人公的心理活动和思想感情。冰簟、银床、碧空、明月、轻云、雁声、潇湘和月光笼罩下的玉楼，组成了一组离人幽怨的秋夜图，渲染了一种和主人公离怨情绪统一和谐的情调和氛围。虽没有正面描写女主人公清夜独自弹瑟传达怨情，但幽怨之情表现得很充分。作品含蓄温婉，诗意浓郁，耐人寻味。', '瑶瑟：玉镶的华美的瑟。
冰簟（diàn）：清凉的竹席。银床：指洒满月光的床。
碧天：青天；蓝色的天空。
远：一作“还”。过：一作“向”。潇湘：二水名，在今湖南境内。此代指楚地。
十二楼：原指神仙的居所，此指女子的住所。', '秋夜床席冰冷梦也难以做成，天空碧蓝如水夜云像沙样轻。
雁声凄厉远远地飞过潇湘去，十二楼中的明月空自放光明。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92da03048e64fbd91673", "shortContent": "诗的题目和内容都很含蓄。瑶瑟，是玉镶的华美的瑟。瑟声悲怨，相传“泰帝使素女鼓五十弦瑟，悲，帝禁不止，故破其瑟为二十五弦”（《汉书·郊祀志》）。在古代诗歌中，它常和别离之悲联结在一起。题名“瑶瑟怨”，正暗示诗所写的是女子别离的悲怨。\n头一句正面写女主人公。“冰簟银床”，指冰凉的竹席和银饰的床。“梦不成”三字很可玩味。它不是一般地写因为伤离念远难以成眠，而是写她寻梦不成。会合渺茫难期，只能将希望寄托在...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9820695e6503ffee", "shortContent": "诗的题目和内容都很含蓄。瑶瑟，是玉镶的华美的瑟。瑟声悲怨，相传“泰帝使素女鼓五十弦瑟，悲，帝禁不止，故破其瑟为二十五弦”（《汉书·郊祀志》）。在古代诗歌中，它常和别离之悲联结在一起。题名“瑶瑟怨”，正暗示诗所写的是女子别离的悲怨。\n\n头一句正面写女主人公。“冰簟银床”，指冰凉的竹席和银饰的床。“梦不成”三字很可玩味。它不是一般地写因为伤离念远难以成眠，而是写她寻梦不成。会合渺茫难期，只能将希望寄托...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4dc26cbf3417f0939a", "shortContent": "瑟是一种古老的弦乐器。《诗经》中有“琴瑟友之”的诗句，故瑟常与琴并奏，以示夫妇百年好合。而《汉书•郊祀记》中说：“太帝命素女鼓五十弦瑟，悲，帝禁不能止，故破其瑟为二十五弦。”说明瑟的乐声具有悲怨的特点。此诗名为“瑶瑟怨”，“瑶”示华美之意，然有瑟无琴，兼以“怨”名，暗示内容为闺中怀人，情绪哀怨。\n\n首句写怀人的环境：冰凉的枕席，银饰的床幔，触目之处皆为冰寒的色调，毫无一般闺房的绮丽娇艳。现在到秋天...", "authors": ["王颖"], "pressName": "崇文书局"}]', '谢枋得《注解选唐诗》：此诗铺陈一时光景，略无悲怆怨恨之辞，枕冷衾寒、独寐寤叹之意在其中矣。
胡应麟《诗薮》：此等入盛唐亦难辨，惜他作殊不尔。温庭筠《瑶瑟怨》、陈陶《陇西行》、李洞《绣岭词》、卢弼《四时词》，皆乐府也，然音响自是唐人，与五言绝稍异。
周珽《唐诗选脉会通评林》：展转反侧，所闻所见，无非悲思，含怨可知。
黄周星《唐诗快》：不言瑟而瑟在其中，何必“二十五弦弹夜月”耶！
黄生《唐诗摘钞》：因夜景清寂，梦不可成，却倒写景于后。《瑶瑟》用雁事，亦如《归雁》用瑟事。
宋宗元《网师园唐诗笺》：深情遥寄（末句下）。
范大士《历代诗发》：“月自明”，不必言怨，而怨已深。
宋顾乐《唐人万首绝句选评》：此作清音渺思，直可追中、盛名家。
胡本渊《唐诗近体》：只此三字（按指“梦不成”）露怨意。通幅布景，正以浑含不尽为妙。
俞陛云诗境浅说续编：通首纯写秋闺之景，不着迹象，而自有一种清怨……首句“梦不成”略露闺情，以下由云天而闻雁，而南及潇湘，浙推渐远，怀人者亦随之神往。四句仍归到秋闺，剩有亭亭孤月，留伴妆楼，不言愁而愁与秋宵俱永矣。此诗高浑秀丽，作词境论，亦五代冯、韦之先河也。
刘永济《唐人绝句精华》：瑟有柱以定声之高下，瑟弦二十五，柱亦如之，斜列如雁行，故以雁声形容之。结言独处，所谓“怨”也。', 'center', 1417701853, '57b904e70a2b58005c925e1b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (78635, '西湖留别', NULL, 2, 2952, 0, 1, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', NULL, NULL, '征途行色惨风烟，祖帐离声咽管弦。
翠黛不须留五马，皇恩只许住三年。
绿藤阴下铺歌席，红藕花中泊妓船。
处处回头尽堪恋，就中难别是湖边。', NULL, NULL, NULL, NULL, NULL, 'center', 1554893508, '585d0947128fe1006ba15ac4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (223905, '大雪日微霰下庭看小儿积霰为戏', NULL, 0, 1570, 0, 1, '区大相', NULL, 16249, '5858eac6128fe1006dcc463c', '明', 'shi', '诗', NULL, NULL, '小雪初过大雪晨，微云微霰点轻尘。
谁言蓟北无花日，亦有江南咏絮人。', NULL, NULL, NULL, NULL, NULL, 'center', 1582024383, '585db79161ff4b006cd5b8b9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10685, '马嵬坡', NULL, 25, 19, 0, 1, '郑畋', NULL, 10163, '57bba9682e958a00693fa2e8', '唐', 'shi', '诗', 'http://baike.baidu.com/view/356525.htm', '', '玄宗回马杨妃死，云雨难忘日月新。
终是圣明天子事，景阳宫井又何人。', '此诗以“马嵬事变”作为背景。前两句写唐玄宗回马长安，杨贵妃却已死。尽管山河依旧，然而却难忘旧情。“云雨难忘”与“日月新”对举，表达玄宗欣喜与长恨兼有的复杂心理。后两句以南朝陈后主偕宠妃躲在景阳宫井中，终为隋兵所虏的事，对比唐玄宗马嵬坡赐杨贵妃自缢的举动，对玄宗既有体谅，也有婉讽。', '马嵬（wéi）坡：即马嵬驿，因晋代名将马嵬曾在此筑城而得名，在今陕西兴平市西，为杨贵妃缢死的地方。
回马：指唐玄宗由蜀还长安。
云雨：出自宋玉《高唐赋》“旦为朝云，暮为行雨”，后引申为男女欢爱。此句意谓玄宗、贵妃之间的恩爱虽难忘却，而国家却已一新。
景阳宫井：故址在今江苏省南京市玄武湖边。南朝的昏昧陈后主陈叔宝听说隋兵已经攻进城来，就和宠妃张丽华、孙贵嫔躲在景阳宫井中，结果还是被隋兵俘虏。', '玄宗返回长安杨贵妃早已死，旧时恩爱难忘国家开始振兴。
处死杨妃也是玄宗英明决策，不然就会步陈后主亡国后尘。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92e45e272d4b22543629", "shortContent": "“马嵬坡”即马嵬驿，在今陕西兴平县西。天宝十五载（756）六月，安禄山叛军攻破潼关，危及长安，玄宗仓皇出逃。经过马嵬坡时，扈从部队因怨愤而哗变，自行处死奸相杨国忠，并要求玄宗杀死杨贵妃。这就是历史上有名的马嵬之变。\n此诗首句的“玄宗回马”，指大乱平定、两京收复之后，成了太上皇的玄宗从蜀中回返长安。其时距“杨妃死”已很久了。两下并提，意谓玄宗能重返长安，正是以牺牲杨妃换来的。一存一殁，意味深长。玄宗...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9ae60d368fd3d12c", "shortContent": "“马嵬坡”即马嵬驿，在今陕西兴平西。天宝十五载（756）六月，安禄山叛军攻破潼关，危及长安，玄宗仓皇出逃。经过马嵬坡时，扈从部队因怨愤而哗变，自行处死奸相杨国忠，并要求玄宗杀死杨贵妃。这就是历史上有名的马嵬之变。\n\n此诗首句的“玄宗回马”，指大乱平定、两京收复之后，成了太上皇的玄宗从蜀中回返长安。其时距“杨妃死”已很久了。两下并提，意谓玄宗能重返长安，正是以牺牲杨妃换来的。一存一殁，意味深长。玄宗...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4dc26cbf3417f0939b", "shortContent": "马嵬坡，旧址在今陕西省兴平市西，是著名的马嵬之变的发生地。唐玄宗天宝十五年（756）六月，安禄山叛军攻破潼关，唐玄宗携杨贵妃、杨国忠仓皇奔蜀。行至马嵬驿时，六军忽然不进，杀死杨国忠后，又坚决要求处死杨贵妃。玄宗不得已，下令赐死。\n\n有唐一代，描写马嵬之事的诗歌非常多，思想内容也很丰富，有讥刺唐玄宗、杨贵妃的，如张祜的《马嵬坡》；有赞美杨贵妃忠君的，如徐夤的《马嵬坡》；有为杨贵妃祸国鸣不平的，如韦庄...", "authors": ["余春丽"], "pressName": "崇文书局"}]', '高彦休《唐阙史》：马嵬佛寺，杨贵妃缢所。迩后才士文人，经过赋咏以导幽怨者，不可胜记，莫不以翠翘香钿，委于尘土，红凄碧怨，令人悲伤，虽调苦词清，而无逃此意。独丞相荥阳公郑畋为凤翔从事日，题诗曰：“玄宗回马杨妃死，云雨难忘日月新。终是圣明天子事，景阳宫井又何人。”
魏泰《临汉隐居诗话》：唐人咏马嵬之事者多矣……《唐阙史》载郑畋《马嵬》诗，命意似矣，而词句凡下，比说无状，不足道也。
吴开《优古堂诗话》：《唐阙史》称郑相畋吟《马嵬》诗……观者以为真辅国之句，予以谓畋盖取杜诗“不闻夏殷衰，中自诛褒姐”之意。
吴乔《围炉诗话》：用意隐然，最为得体。
蘅塘退士《唐诗三百首》：唐人马嵬诗极多，唯此诗深得温柔敦厚之旨。
陆次云《五朝诗善鸣集》：得体。当时读此诗者，以为有宰辅气，许得不错。
李锳《诗法易简录》：立言得体。“可怜金谷坠楼人”，高一层衬；此低一层衬。
王渔洋《唐贤小三昧集续集》：论既得体，调亦琅然。', 'center', 1417702056, '57b99dfe165abd005a6da9cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10686, '已凉', NULL, 51, 341, 1, 1, '韩偓', NULL, 10164, '57b9272dd342d3005ac86d7a', '唐', 'shi', '诗', 'http://baike.baidu.com/view/350124.htm', '', '碧阑干外绣帘垂，猩色屏风画折枝。
八尺龙须方锦褥，已凉天气未寒时。', '此诗以工笔画的手法，用旖旎秾艳的色彩，精细入微地描写了诗人所钦慕的美人深闺绣户中精巧典雅的陈设布置，点出已凉未寒的特有时令气氛。诗中主人公始终没有露面，但床上锦褥的暗示和折枝图的烘托，隐约展示了主人公在深闺寂寞之中渴望爱情生活的情怀。全诗情思深远，委婉含蓄，构思颇费心思。', '绣帘：一作“翠帘”。
猩血：一作“猩色”，猩红色。屏风：一种用来遮挡和做隔断的东西。画折枝：一作“画柘枝”，指图绘花卉草木。
龙须：属灯心草科，茎可织席。这里指草席。', '翠绿色的栏杆外绣帘儿低垂，猩红的屏风上画着草木花卉。
龙须草织成的席子铺上锦褥，天气已凉却还未到寒冷时候。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ea5e272d4b2254369e", "shortContent": "韩偓《香奁集》里有许多反映男女情爱的诗歌，这是最为脍炙人口的一篇。其好处全在于艺术构思精巧，笔意含蓄。\n展现在我们眼前的，是一间华丽精致的卧室。镜头由室外逐渐移向室内，透过门前的阑干、当门的帘幕、门内的屏风等一道道阻障，聚影在那张铺着龙须草席和织锦被褥的八尺大床上。房间结构安排所显示出的这种“深而曲”的层次，分明告诉我们，这是一位贵家少妇的金闺绣户。\n布局以外，景物吸引我们视线的，还有它那斑驳陆离...", "authors": ["陈伯海"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ae9ae60d368fd3d138", "shortContent": "韩偓《香奁集》里有许多反映男女情爱的诗歌，这是最为脍炙人口的一篇。其好处全在于艺术构思精巧，笔意含蓄。\n\n展现在我们眼前的，是一间华丽精致的卧室。镜头由室外逐渐移向室内，透过门前的阑干、当门的帘幕、门内的屏风等一道道阻障，聚影在那张铺着龙须草席和织锦被褥的八尺大床上。房间结构安排所显示出的这种“深而曲”的层次，分明告诉我们，这是一位贵家少妇的金闺绣户。\n\n布局以外，景物吸引我们视线的，还有它那斑驳...", "authors": ["陈伯海"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4dc26cbf3417f0939c", "shortContent": "此诗是唐末诗人韩偓创作的一首闺情诗，以工笔画写闺情，颇有南北朝时期宫体诗之秾丽雅致。\n\n一、二句以简约绚烂之妙笔，勾勒出女主人公闺房绣阁之华丽锦绣。翠绿色的栏杆外绣帘低垂，猩红色的屏风上点缀着草木花卉。栏杆是翠绿色的，绣帘是低垂的，屏风是猩红的，折枝是雅致的，诗人在此用四个颇具代表性的意象，为我们呈现出一间华丽精致的闺房卧室的场景。\n\n三、四句则从室外转入室内，进一步铺陈室内的陈设以及与季节变化的...", "authors": ["乐云"], "pressName": "崇文书局"}]', '《唐贤小三昧集续集》：中具多少情事，妙在不明说，令人思时得之。
《随园诗话》：人问：诗要耐想，如何而耐人想？余应之曰：“八尺龙须方锦褥，已凉天气未寒时”、“狎客沦亡丽华死，他年江令独来时”……皆耐想也。
《精选评注五朝诗学津梁》：句法整齐。
《唐诗三百首》：通首布景，并不露情思，而情愈深远。
《王闿运手批唐诗选》：龙须席上加方锦褥，是“已凉”也；然不必咏。
《诗境浅说续编》：由阑干、绣帘而至锦褥，迤逦写来，纯是景物，而景中有人。丽不伤雅，《香奁集》中隽咏也。
《唐人绝句精华》：《已凉》一首如工笔仕女图，古今传诵以此。', 'center', 1417702166, '57b99e0279bc44006029b51e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10687, '金陵图', NULL, 145, 380, 1, 1, '韦庄', NULL, 10140, '57b9c08d79bc4400639c80ea', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383833.htm', '', '谁谓伤心画不成？画人心逐世人情。
君看六幅南朝事，老木寒云满故城。', '此诗是作者看了六幅描写南朝史事的彩绘后有感而写的吊古伤今之作，诗中指出这组画并没有为南朝统治者粉饰升平，而是画出它的凄凉衰败。全诗语调激昂，寓意深刻，不仅对那些粉饰太平、不尊重历史事实的行为作了有力的驳斥，并点明了发生这种现象的社会原因，而且对敢于反映历史真实的六幅“伤心画”给予了高度的评价，体现了作者朴素的历史唯物主义精神。', '', NULL, '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4ec26cbf3417f0939d", "shortContent": "此诗《全唐诗》题作《台城》，《金陵图》为题的是另外一首诗：“谁谓伤心画不成？画人心逐世人情。君看六幅南朝事，老木寒云满故城。”从这两首诗的内容来看，《唐诗三百首》所选的这首题作《台城》无疑更恰当。台城，一名苑城，旧为六朝台省和宫殿所在，曾是天下最繁华之处。然而，待到诗人韦庄登临之时，却早已是今非昔比，一片荒芜了。韦庄生当唐亡前夕，抚今追昔，不免生出许多感伤情绪。\n\n首句即从美好的江南春景写起。诗人...", "authors": ["余春丽"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707bf2af4e09d55b67b6", "shortContent": "晚唐以后，由于社会衰败和国家危亡，诗人普遍表现出一种伤悼的情绪。这在很多作品中都有反映，韦庄的这首诗也不例外。它虽然只是一首题画之作，但由于图画主要描绘六朝首都——金陵的形胜与史迹，故诗中同样流露出浓重的悼古伤今情调。\n\n首句即作惊人语，以感情强烈的反问句起，不但突出了诗人无比沉痛的心情，而且极大地引发了读者的好奇心，究竟是谁说伤心不能画成以至于韦庄如此激烈地反驳呢？显然，这一诗句是有鲜明的针对性...", "authors": ["余春丽"], "pressName": "崇文书局"}]', '', 'center', 1417702209, '57b8ee7f2e958a005fa4d589', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10688, '寄人', NULL, 197, 29, 1, 1, '张泌', NULL, 10165, '57bbbc41c4c9710061556337', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383834.htm', '', '别梦依依到谢家，小廊回合曲阑斜。
多情只有春庭月，犹为离人照落花。', '此诗是作者与情人别后的寄怀诗，描写梦境及梦醒后的情景，写出了诗人的相思之深切与苦怨。诗的首句写梦中重聚，难舍难离；二句写依旧当年环境，往日欢情；三句写明月有情，伊人无义；四句写落花有恨，慰藉无人。前两句写入梦的原因与梦中所见的景物，是向对方表明自己思忆之深；后两句写出多情的明月依旧照人，是对这位女子的埋怨之情。以明月有情，寄希望于对方，含蓄深厚，曲折委婉，真切感人，动人心弦。', '谢家：泛指闺中女子。晋谢奕之女谢道韫、唐李德裕之妾谢秋娘等皆有盛名，故后人多以“谢家”代闺中女子。
“小廊”句：指梦中所见景物。回合：回环、回绕。阑：栏杆。
“多情”句：指梦后所见。
离人：这里指寻梦人。', '别后思念深深，经常梦到你家。院中风景依旧，小廊曲阑仍在。
再也不见倩影，令人魂牵梦绕，只有明月多情，遍照片片落花。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ef34a8757d5a0e1ead", "shortContent": "以诗代柬，来表达自己心里要说的话，这是古代常有的事。这首题为《寄人》的诗，就是用来代替一封信的。\n从这诗深情宛转的内容看来，诗人曾与一女子相爱，后来却彼此分手了。然而诗人对她始终没有忘怀。在封建宗法社会的“礼教”阻隔下，既不能直截痛快地倾吐衷肠，只好借用诗的形式，曲折而又隐约地加以表达，希望她到底能够了解自己。这是题为《寄人》的原因。\n诗是从叙述一个梦境开始的。“谢家”，代指女子的家，盖以东晋才女...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389af4797a92d5e4fd929", "shortContent": "以诗代柬，来表达自己心里要说的话，这是古代常有的事。这首题为《寄人》的诗，就是用来代替一封信的。\n\n从这诗深情宛转的内容看来，诗人曾与一女子相爱，后来却彼此分手了。然而诗人对她始终没有忘怀。在封建宗法社会的“礼教”阻隔下，既不能直截痛快地倾吐衷肠，只好借用诗的形式，曲折而又隐约地加以表达，希望她到底能够了解自己。这是题为《寄人》的原因。\n\n诗是从叙述一个梦境开始的。“谢家”，代指女子的家，盖以东晋...", "authors": ["刘逸生"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4ec26cbf3417f0939f", "shortContent": "此诗主要抒写别后相思，但是又不平常写出，而是俱托梦境表现。\n\n诗的一开篇就直接以梦境起。“别梦依依到谢家”，意思是说诗人梦见自己回到了心中思念的那位女子之家。“谢家”，原指东晋才女谢道韫的家，此处则借为诗人所思念女子的家。一个“别”字，点明相思和产生此梦的原因。因为分别不能相见，所以相思至深；相思至深却又不得纾解，只好梦中寻之，以求相聚。这一句不但把诗人的相思之情渲染得深重缠绵，而且还生动传神地刻...", "authors": ["余春丽"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707e73206168b2e02248", "shortContent": "此诗主要抒写别后相思，但是又不寻常写出，而是俱托梦境表现。\n\n诗的一开篇就直接以梦境起。“别梦依依到谢家”，意思是说诗人梦见自己回到了心中思念的那位女子之家。“谢家”，原指东晋才女谢道韫的家，此处则借为诗人所思念女子的家。一个“别”字，点明相思和产生此梦的原因。因为分别不能相见，所以相思至深；相思至深却又不得纾解，只好梦中寻之，以求相聚。这一句不但把诗人的相思之情渲染得深重缠绵，而且还生动传神地刻...", "authors": ["余春丽"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127173c305cf08018170a1", "shortContent": "此诗主要抒写别后相思，但是又不寻常写出，而是俱托梦境表现。\n诗的一开篇就直接以梦境起。“别梦依依到谢家”，意思是说诗人梦见自己回到了心中思念的那位女子之家。“谢家”，原指东晋才女谢道韫的家，此处则借为诗人所思念女子的家。一个“别”字，点明相思和产生此梦的原因。因为分别不能相见，所以相思至深；相思至深却又不得纾解，只好梦中寻之，以求相聚。这一句不但把诗人的相思之情渲染得深长缠绵，而且还生动传神地刻画...", "authors": ["余春丽"], "pressName": "崇文书局"}]', '《唐诗绝句类选》：末二句无情翻出有情。
《唐诗选脉会通评林》：张泌《寄人》二诗，俱情痴之语。
《网师园唐诗笺》：蕴藉（末二句下）。
《精选评注五朝诗学津梁》：以多情春光为寓意，末二句结构佳妙。
《词苑丛谈》：张泌仕南唐为内史舍人，初与邻女浣衣相善，作《江神子》词云：“浣花溪上见卿卿，眼波明，黛眉轻。高绾绿云，低簇小蜻蜓。好是问他知得么？和笑道，莫多情。”后经年不复相见。张夜梦之，寄绝句云：“别梦依依到谢家……”
《养一斋诗话》：佖（泌）有《寄人》一绝，云：“别梦依依到谢家……”比之司空表圣“故国春归未有涯，小栏高槛别人家。五更惆怅回孤枕，犹自残灯照落花”，风流略似。', 'center', 1417702344, '57b90541165abd0054bff1b3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10689, '杂诗', NULL, 59, 377, 0, 2, '无名氏', NULL, 10156, '57b9dc73a633bd005d303896', '唐', 'shi', '诗', 'http://baike.baidu.com/view/6826087.htm', '', '近寒食雨草萋萋，著麦苗风柳映堤。
等是有家归未得，杜鹃休向耳边啼。', '这是歌咏游客居外不得返乡之情的诗。意思是在说寒食、清明将到，客居不能返乡，却听得杜鹃悲泣，更为伤感，大有“每逢佳节倍思亲”之慨。诗的节奏独特，首两句节拍为“一、二、三”，然而却谐绝句平仄韵，这是绝句中少见的。句写六朝往事如梦，台城早已破败；三、四句写风景依旧，人世沧桑。触景生情，借景寄慨，暗寓伤今。语言含蓄蕴藉，情绪无限感伤。', '著：吹入。
等是：为何。
杜鹃：鸟名，即子规。', NULL, '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4ec26cbf3417f093a0", "shortContent": "所谓“杂诗”，抒发的大抵是关于人生的零星感想和琐事琐忆。自汉魏以来，诗人常以“杂诗”为题写诗，内容多感叹人生或离别相思。此诗作者姓名无可稽考，但却能于平淡处写羁客之思乡情绪，是一首不可多得的寒食诗。\n\n寒食节，是中国唐宋时期一个非常重要的节日，在清明前一日或二日。相传春秋时晋文公负其功臣介之推，介愤而隐于绵山。文公悔悟，烧山逼令出仕，之推抱树焚死。人们同情介之推的遭遇，相约于其忌日禁火冷食，以为悼...", "authors": ["乐云）"], "pressName": "崇文书局"}]', '', 'center', 1417702405, '57ba82b75bbb500063fb42fc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (79416, '杭州回舫', NULL, 7, 2952, 0, 2, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', 'https://baike.baidu.com/item/%E6%9D%AD%E5%B7%9E%E5%9B%9E%E8%88%AB/1000220?fr=aladdin', '', '自别钱塘山水后，不多饮酒懒吟诗。
欲将此意凭回棹，报与西湖风月知。', '《杭州回舫》是唐代诗人白居易所作诗词之一。以描写西湖的景色，抒发自己的情感。', '', '', NULL, '', 'center', 1554893544, '585d0a34128fe10069cbe5fa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (224135, '咏茄', NULL, 0, 1570, 0, 1, '区大相', NULL, 16249, '5858eac6128fe1006dcc463c', '明', 'shi', '诗', NULL, NULL, '紫茄时被陇，舒叶自亏蔽。
登君玉盘内，得耦嘉蔬味。
结花讵能芳，垂实迥连带。
虽微蹲鸱用，颇胜匏瓜系。', NULL, NULL, NULL, NULL, NULL, 'center', 1525432487, '585db7d6da2f600065874224', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10690, '秋夜曲', NULL, 127, 8, 1, 2, '王涯', NULL, 50593, '6493076806326254dc21bfd1', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/383836/5086409.htm', '', '桂魄初生秋露微，轻罗已薄未更衣。
银筝夜久殷勤弄，心怯空房不忍归。', '这是一首闺怨诗。此诗前两句是写景，写得颇为悠闲，秋夜微凉，景物凄清；末两句是写情，主人公寂寞难寝，殷勤弄筝。此诗语极委婉，情极细腻，把儿女羞涩的情感遮掩得严严实实：少妇独守空闺，沉浸于相思，不忍更衣；借弹筝自遣寂寞，又不忍回屋。
诗人借用女主人公心理活动来展示其独守空房的哀怨，曲尽其妙；代写思妇心境，抒发内心空虚的痛苦，更显深刻细腻生动，流露出女主人公独守空房、思念丈夫的怨情，表现出诗人诗艺的功力。', '秋夜曲：属乐府《杂曲歌辞》，是一首宛转含蓄的闺怨诗。
桂魄：即月亮。相传月中有桂树，又月初生时的微光曰魄，故称初生之月为桂魄。
轻罗：轻盈的丝织品，宜做夏装，在此代指夏装。
已薄：已觉单薄。
筝：拨弦乐器，十三弦。
殷勤弄：频频弹拨。
空房：谓独宿无伴。', '月亮初升时秋露已经稀微，身着单薄的罗衣并未更换别的衣裳。
漫漫长夜满怀深情地银筝拨动，心中害怕独守空房，不忍进屋睡觉。', '[{"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4ec26cbf3417f093a3", "shortContent": "这是一首“雅而不纤”（《唐诗选脉会通评林》）的闺怨诗。关于此诗作者，虽然选者力证王维所作，但学术界普遍认为是王涯所作，一是《王右丞集》并无此诗，二是其他唐诗选本亦注明王涯所作。\n\n首句点明时令时间，时令是初秋，时间是初夜。此时，夜幕初临，月亮从东方冉冉升起，泛起细细的微光。已经是秋天了，秋露在不经眼中已悄然侵入，但尚且微薄稀少，故而虽有凉意，却并不寒冷。闺中之人此时依然身披夏天的轻薄纱衣，虽不免单...", "authors": ["乐云"], "pressName": "崇文书局"}]', '', 'center', 1417702778, '57b91bc0a633bd00665e32ed', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10691, '长信秋词', NULL, 103, 202, 1, 1, '王昌龄', NULL, 10051, '57b91963128fe10054ca5788', '唐', 'shi', '诗', 'http://baike.baidu.com/view/383838.htm', '', '奉帚平明金殿开，暂将团扇共徘徊。
玉颜不及寒鸦色，犹带昭阳日影来。', '这首宫怨诗是借咏汉班婕妤而慨叹宫女失宠之怨的。婕妤初受汉成帝宠幸，后来成帝偏幸赵飞燕姐妹，她即求供养太后于长信宫。诗的首句即写供奉太后之事；二句写婕妤曾作「团扇诗」《怨歌行》，自比扇子，恐怕秋凉被弃箧中；三、四句写虽颜美如玉，失宠之后却不如丑陋的乌鸦。以颜色比颜色，虽不同伦类，却显得奇特精巧，写出宫女失宠之后，对其同类的嫉羡之情。', '奉帚：持帚洒扫。多指嫔妃失宠而被冷落。
平明：指天亮。金殿：指宫殿。一作「秋殿」。
团扇：即圆形的扇子。班婕妤曾作《团扇诗》。
暂：一作「且」。
共：一作「暂」。
玉颜：指姣美如玉的容颜，这里暗指班婕妤自己。
寒鸦：寒天的乌鸦；受冻的乌鸦。暗指掩袖工谄、心狠手辣的赵飞燕姐妹。
昭阳：汉代宫殿名，代指赵飞燕姐妹与汉成帝居住之处。', '天亮就拿起扫帚打扫金殿尘埃，百无聊赖时手执团扇且共徘徊。
美丽的容颜还不如乌鸦的姿色，它还能带着昭阳殿的日影飞来。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92940ce818559d058648", "shortContent": "《长信秋词》是拟托汉代班婕妤在长信宫中某一个秋天的事情而写作的。古乐府歌辞中有《怨歌行》一篇，其辞是：“新裂齐纨素，皎洁如霜雪。裁为合欢扇，团团似明月。出入君怀袖，动摇微风发。常恐秋节至，凉飚夺炎热。弃捐箧笥中，恩情中道绝。”此诗相传是班婕妤所作，以秋扇之见弃，比君恩之中断。王昌龄这篇诗写宫廷妇女的苦闷生活和幽怨心情，即就《怨歌行》的寓意而加以渲染，借长信故事反映唐代宫廷妇女的生活。\n诗中前两句写...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b9434bfda01e0eab209", "bookTitle": "唐宋小说鉴赏辞典", "articleId": "610f43dadbb8b379ee0afee9", "shortContent": "本篇采自薛用弱的《集异记》。小说叙述了著名的旗亭画壁的故事。就像一幕精彩的生活短剧，文笔清新简洁，画面风趣生动，有较强的舞台艺术效果。\n在微雪轻飏的背景下，首先上场的是唐代三位“风尘未偶，而游处略同”的著名诗人王昌龄、高适、王涣之（系王之涣之误），他们虽然生活清苦，囊中羞涩，然而诗酒之豪，丝毫未减；其次上场的是十几位梨园伶官，登楼会宴；再次上场的是四位“奢华艳曳，都冶颇极”的妙龄歌妓，所奏之乐，皆...", "authors": ["陈惠琴"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ab9ae60d368fd3d102", "shortContent": "《长信秋词》是拟托汉代班婕妤在长信宫中某一个秋天的事情而写作的。古乐府歌辞中有《怨歌行》一篇，其辞是：“新裂齐纨素，皎洁如霜雪。裁为合欢扇，团团似明月。出入君怀袖，动摇微风发。常恐秋节至，凉飚夺炎热。弃捐箧笥中，恩情中道绝。”此诗相传是班婕妤所作，以秋扇之见弃，比君恩之中断。王昌龄这首诗写宫廷妇女的苦闷生活和幽怨心情，即就《怨歌行》的寓意而加以渲染，借长信故事反映唐代宫廷妇女的生活。\n\n诗中前两句...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4ec26cbf3417f093a4", "shortContent": "此题又作《长信秋词》，原有五首，此其三，是唐代宫怨诗的名篇。诗人借咏汉代才女班婕妤的深宫幽居遭遇，表达对深宫女子凄凉人生的伤感与哀叹。\n\n长信宫是汉代三宫之一，位于西汉长安城内东南隅，是汉代太后的寝宫。据《汉书》载，班婕妤入宫后，曾深得汉成帝宠幸，后因赵飞燕而失宠，班婕妤因担心赵飞燕加害，请求到长信宫伺奉太后，自此困守冷宫，直至终老。在长信宫中，班婕妤曾创作过《怨歌行》等名篇，其不幸遭遇也一再被后...", "authors": ["乐云"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312703bf2af4e09d55b672c", "shortContent": "此题又作《长信秋词》，原有五首，此其三，被誉为唐代宫怨诗的名篇。诗人借咏汉代才女班婕妤的深宫幽居遭遇，表达对深宫女子凄凉人生的伤感与哀叹。\n\n长信宫是汉代三宫之一，位于西汉长安城内东南隅，是汉代太后的寝宫。长信宫之所以著名，与汉代才女班婕妤密切相关。据《汉书》载，班婕妤入宫后，曾深得汉成帝宠近，后因赵飞燕而失宠，班婕妤因担心赵飞燕加害，请求到长信宫侍奉太后，自此困守冷宫，直至终老。在长信宫中，班婕...", "authors": ["乐云"], "pressName": "崇文书局"}]', '', 'center', 1417703068, '57b95bf3a633bd00666076f3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10692, '清平调（其一）', NULL, 1604, 1052, 1, 3, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/1190736.htm', '', '云想衣裳花想容，春风拂槛露华浓。
若非群玉山头见，会向瑶台月下逢。', '此诗为李白《清平调》组诗的第一首，是李白在长安为翰林时所作。有一次，唐明皇与杨贵妃在沉香亭观赏牡丹，因命李白作新乐章，李白奉旨作了这三章。首句以云霞比衣服，以花比容貌；二句写花受春风露华润泽，犹如妃子受君王宠幸；三句以仙女比贵妃；四句以嫦娥比贵妃。这样反复作比，塑造了艳丽有如牡丹的美人形象。然而，诗人采用云、花、露、玉山、瑶台、月色，一色素淡字眼，赞美了贵妃的丰满姿容，却不露痕迹。', '清平调：一种歌的曲调，「平调、清调、瑟调」皆周房中之遗声。
「云想」句：见云之灿烂想其衣之华艳，见花之艳丽想美人之容貌照人。实际上是以云喻衣，以花喻人。
槛：栏杆；露华浓：牡丹花沾着晶莹的露珠更显得颜色艳丽。
群玉：山名，传说中西王母所住之地。
「若非……会向……」：相当于「不是……就是……」的意思。全句形容贵妃貌美惊人，怀疑她不是群玉山头所见的仙子，就是瑶台殿前月光照耀下的神女。', '见云之灿烂想其衣裳之华艳，
见花之艳丽想人之容貌照人。
春风吹拂栏杆，露珠润泽花色更浓。
如此天姿国色，若不见于群玉山头，
那一定只有在瑶台月下，才能相逢！', '[{"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892bbb31680ae4c4b4ab", "shortContent": "李白为唐明皇和杨贵妃所作的《清平调》共有三首，这里选其一。按乐史为李太白集所作的序中所记：“开元中，禁中初重木芍药，即今牡丹也。得四本红、紫、浅红、通白者，上因移植于兴庆池东沉香亭前。会花方繁开，上乘照夜车，太真妃以步辇从，诏选梨园弟子中尤者得乐一十六色。李龟年以歌擅一时之名，手捧檀板，押众乐前，将欲歌之。上曰：‘赏名花，对妃子，焉用旧乐辞焉！’遽命龟年持金花笺宣赐翰林供奉李白，立进《清平调》词三...", "authors": ["刘竞飞"], "pressName": "上海辞书出版社"}, {"bookId": "62ddfbd370a8fc34fafa144e", "bookTitle": "唐诗三百首", "articleId": "630389ac821a74606fc40939", "shortContent": "这三首诗是李白在长安供奉翰林时所作。一日，玄宗和杨妃在宫中观牡丹花，因命李白写新乐章，李白奉诏而作。在三首诗中，把木芍药（牡丹）和杨妃交互在一起写，花即是人，人即是花，把人面花光浑融一片，同蒙唐玄宗的恩泽。从篇章结构上说，第一首从空间来写，把读者引入蟾宫阆苑；第二首从时间来写，把读者引入楚襄王的阳台，汉成帝的宫廷；第三首归到目前的现实，点明唐宫中的沉香亭北。诗笔不仅挥洒自如，而且相互钩带。第一首中...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4e7ccdb86c49f29106", "shortContent": "《清平调词》三首，是李白于天宝初年入长安供奉翰林时所作。《李翰林别集序》（乐史）记载：“开元中，禁中初重木芍药，即今牡丹也。得数本，红、紫、浅红、通白者，上因移植于兴庆池东沉香亭前。会花方繁开，上乘照夜车，太真妃以步辇从。诏选梨园弟子中尤者，得乐一十六色。李龟年以歌擅一时之名，手捧檀板，拥众乐前，将欲歌之。上曰：‘赏名花，对妃子，焉用旧乐词为！遽命龟年持金花笺，宣赐翰林学士李白立进《清平调词》三篇...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312704d73206168b2e021de", "shortContent": "《清平调词》三首，是李白于天宝初年入长安供奉翰林时所作。《李翰林别集序》（乐史）记载：“开元中，禁中初重木芍药，即今牡丹也。得四本红、紫、浅红、通白者，上因移植于兴庆池东沉香亭前。会花方繁开，上乘照夜车，太真妃以步辇从。诏选梨园弟子中尤者，得乐一十六色。李龟年以歌擅一时之名，手捧檀板，押众乐前，将欲歌之，上曰：‘赏名花，对妃子，焉用旧乐辞焉！’遽命龟年持金花笺，宣赐翰林供奉李白立进《清平调词》三章...", "authors": ["闵泽平"], "pressName": "崇文书局"}, {"bookId": "645fb5e45b7b0d4f45fca5de", "bookTitle": "李白诗歌鉴赏辞典", "articleId": "6466e58b7f27182da35d17e1", "shortContent": "这三首诗是李白在长安供奉翰林时所作。一日，玄宗和杨妃在宫中观牡丹花，因命李白写新乐章，李白奉诏而作。在三首诗中，把木芍药（牡丹）和杨妃交互在一起写，花即是人，人即是花，把人面花光浑融一片，同蒙唐玄宗的恩泽。从篇章结构上说，第一首从空间来写，把读者引入蟾宫阆苑；第二首从时间来写，把读者引入楚襄王的阳台，汉成帝的宫廷；第三首归到目前的现实，点明唐宫中的沉香亭北。诗笔不仅挥洒自如，而且相互钩带。第一首中...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}]', '《碧鸡漫志》：《松窗杂录》云：开元中，禁中初种木芍药，得四本，红、紫、浅红、通白繁开。上乘照夜白，太真妃以步辇从，李龟年手捧擅板，押众乐前，将欲歌之。上曰：焉用旧词为？命龟年宣翰林学士李白立进《清平调》三章，白承诏赋词，龟年以进。上命梨园弟子约格调、抚丝竹，促龟年歌，太真妃笑领歌意甚厚。张君房《脞说》指此为《清平乐》曲。
《唐诗绝句类选》：蒋仲舒曰：「想」、「想」，妙，难以形容也。次句下得陡然，令人不知。
《李杜二家诗钞评林》：「想」字妙，得恍惚之致。
《汇编唐诗十集》：唐云：声响调高，神彩焕发，喉间有寒酸气者读不得。
《唐诗摘钞》：二「想」字是咏妃后语。
《而庵说唐诗》：「春风拂槛露华浓」，此句须略重。花上风拂，喻妃子之摇曳；露浓，喻君恩之郑重。
《李太白全集》：王琦注：琦按蔡君谟书此诗，以「云想」作「叶想」，近世吴舒凫遵之，且云「叶想衣裳花想容」，与王昌龄「荷叶罗裙一色裁，芙蓉向脸两边开」，俱从梁简文「莲花乱脸色，荷叶杂衣香」脱出。而李用二「想」字，化实为虚，尤见新颖，不知何人误作「云」字，而解者附会《楚辞》「青云衣兮白霓裳」，甚觉无谓云云。不知改「云」作「叶」，便同嚼蜡，索然无味矣。此必君谟一时落笔之误，非有意点金成铁，若谓太白原本是「叶」字，则更大谬不然。
《唐诗笺注》：此首咏太真，着二「想」字妙。次句人接不出，却映花说，是「想」之魂。「春风拂槛」想其绰约，「露华浓」想其芳艳，脱胎烘染，化工笔也。
《诗法易简录》：三首人皆知合花与人言之，而不知意实重在人，不在花也，故以「花想容」三字领起。「春风拂槛露华浓」，乃花最鲜艳、最风韵之时，则其容之美为何如？说花处即是说人，故下二句极赞其人。
《填词杂说》：「云想衣裳花想容」，此太白佳境。柳屯田：「拟把名花比，恐旁人笑我，谈何容易！」大畏唐突，尤见温存，又可悟翻旧换新之法。
《雨村词话》：李调元云：太白词有「云想衣裳花想容」，已成绝唱。韦庄效之「金似衣裳玉似身」，尚堪入目，而向子湮「花容仪，柳想腰」之句，毫无生色，徒生厌憎。
《李太白诗醇》：清便宛转，别自成风调。谢云：褒美中以寓箴规之意。严沧浪曰：想望缥缈，不得以熟目忽之。', 'center', 1417703226, '57b93f115bbb50005b7a3a61', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10693, '清平调（其二）', NULL, 388, 1052, 2, 2, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/1190736.htm', '', '一枝红艳露凝香，云雨巫山枉断肠。
借问汉宫谁得似，可怜飞燕倚新妆。', '此诗为李白《清平调》组诗的第二首，是李白在长安为翰林时所作。有一次，唐明皇与杨贵妃在沉香亭观赏牡丹，因命李白作新乐章，李白奉旨作了这三章。首句写花受香露，衬托贵妃君王宠幸；二句写楚王遇神女的虚妄，衬托贵妃之沐实惠；三、四句写赵飞燕堪称绝代佳人，却靠新妆专宠，衬托贵妃的天然国色。诗人用抑扬法，抑神女与飞燕，以扬杨贵妃的花容月貌。', '红艳：红艳艳的牡丹花滴着露珠，好像凝结着袭人的香气。红，一作「秾」。
巫山云雨：传说中三峡巫山神女与楚王欢会接受楚王宠爱的神话故事。
飞燕：赵飞燕。
倚新妆：形容女子艳服华妆的姣好姿态。', '像枝红牡丹沐浴雨露散芳香，有杨妃不再思慕神女空自伤。
请问汉宫佳丽谁能和她媲美，就算赵飞燕也要靠精心化妆。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e929b2e6a6b501f95c06b", "shortContent": "这三首诗是李白在长安供奉翰林时所作。一日，玄宗和杨妃在宫中观牡丹花，因命李白写新乐章，李白奉诏而作。在三首诗中，把木芍药（牡丹）和杨妃交互在一起写，花即是人，人即是花，把人面花光浑融一片，同蒙唐玄宗的恩泽。从篇章结构上说，第一首从空间来写，把读者引入蟾宫阆苑；第二首从时间来写，把读者引入楚襄王的阳台，汉成帝的宫廷；第三首归到目前的现实，点明唐宫中的沉香亭北。诗笔不仅挥洒自如，而且相互钩带。第一首中...", "authors": ["沈熙乾"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b9434bfda01e0eab209", "bookTitle": "唐宋小说鉴赏辞典", "articleId": "610f43e52e6a6b501f975ec6", "shortContent": "杨贵妃，小字玉环，弘农华阴[1]人也。后徙居蒲州永乐[2]之独头村。高祖令本，金州[3]刺史。父玄琰，蜀州司户[4]。贵妃生于蜀，尝误坠池中，后人呼为落妃池。池在导江[5]县前。妃早孤，养于叔父河南府士曹[6]玄璬家。开元二十二年十一月，归于寿[7]邸。二十八年十月，玄宗幸温泉宫，使高力士取杨氏女于寿邸，度为女道士，号太真，住内太真宫。天宝四载七月，册左卫中郎将韦昭训女配寿邸。是月，于凤凰园册太真...", "authors": ["马珏玶"], "pressName": "上海辞书出版社"}]', '《唐诗直解》：结妙有风致。
《唐诗摘钞》：首句承「花想容」来，言妃之美，惟花可比，彼巫山神女，徒成梦幻，岂非「枉断肠」乎！必求其似，惟汉宫飞燕，倚其新装，或庶几耳。
《唐诗合选详解》：梅禹金云；萧（士赞）注谓神女刺明皇之聚麀，飞燕讥贵妃之微贱，亦太白醉中应诏，想不到此，但巫山妖梦、昭阳祸水，微文隐意，风人之旨。
《李太白全集》：王琦注：力士之谮恶矣，萧氏所解则尤甚。而揆之太白起草之时，则安有是哉！巫山云雨、汉宫飞燕，唐人用之已为数见不鲜之典实。若如二子之说，巫山一事只可以喻聚淫之艳冶，飞燕一事只可以喻微贱之宫娃，外此皆非所宜言，何三唐诸子初不以此为忌耶？古来《新台》、《艾豭》诸作，言而无忌者，大抵出自野人之口，若《清平调》是奉诏而作，非其比也。乃敢以宫闱暗昧之事，君上所讳言者而微辞隐喻之，将蕲君知之耶，亦不蕲君知之耶？如其不知，言亦何益？如其知之，是批龙之逆鳞而履虎尾也。非至愚极妄之人，当不为此。
《唐诗笺注》：此首亦咏太真，却竞以花比起，接上首来。
《李杜二家诗钞评林》：巫山妖梦，昭阳祸水，微文隐讽，风人之旨。
《诗法易简录》：仍承「花想容」言之，以「一枝」作指实之笔，紧承前首。三、四句作转，言如花之容，虽世非常有，而现有此人，实如一枝名花，俨然在前也。两首一气相生，次首即承前首作转。如此空灵飞动之笔，非谪仙孰能有之？
《李太白诗醇》：驰思泉涌，敷藻云浮，而却得诗祸！人世遭遇，总出意表，可谓奇矣。谢云：以巫山娇梦，昭阳祸水入调，盖微讽之也。

《唐詩直解》：結妙有風致。
《唐詩摘鈔》：首句承「花想容」來，言妃之美，惟花可比，彼巫山神女，徒成夢幻，豈非「枉斷腸」乎！必求其似，惟漢宮飛燕，倚其新裝，或庶幾耳。
《唐詩合選詳解》：梅禹金雲；蕭（士贊）注謂神女刺明皇之聚麀，飛燕譏貴妃之微賤，亦太白醉中應詔，想不到此，但巫山妖夢、昭陽禍水，微文隱意，風人之旨。
《李太白全集》：王琦注：力士之譖惡矣，蕭氏所解則尤甚。而揆之太白起草之時，則安有是哉！巫山雲雨、漢宮飛燕，唐人用之已爲數見不鮮之典實。若如二子之説，巫山一事只可以喻聚淫之艶冶，飛燕一事只可以喻微賤之宮娃，外此皆非所宜言，何三唐諸子初不以此爲忌耶？古來《新臺》、《艾豭》諸作，言而無忌者，大抵出自野人之口，若《清平調》是奉詔而作，非其比也。乃敢以宮闈闇昧之事，君上所諱言者而微辭隱喻之，將蘄君知之耶，亦不蘄君知之耶？如其不知，言亦何益？如其知之，是批龍之逆鱗而履虎尾也。非至愚極妄之人，當不爲此。', 'center', 1417703293, '57b8eeac5bbb50005b77b2cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10694, '清平调（其三）', NULL, 345, 1052, 1, 2, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'http://baike.baidu.com/view/1190736.htm', '', '名花倾国两相欢，长得君王带笑看。
解释春风无限恨，沉香亭北倚阑干。', '此诗为李白《清平调》组诗，是李白在长安为翰林时所作。有一次，唐明皇与杨贵妃在沉香亭观赏牡丹，因命李白作新乐章，李白奉旨作了这三章。首句写名花与倾国相融；二句写君王的欢愉，「带笑看」三字，贯穿了三者，把牡丹、贵妃、明皇三位一体化了。三、四句写君王在沉香亭依偎贵妃赏花，所有胸中忧恨全然消释。全诗语言艳丽，句句金玉，字字流葩，人花交映，迷离恍惚。', '名花：牡丹花。倾国：喻美色惊人，此指杨贵妃。典出汉·李延年《佳人歌》：「一顾倾人城，再顾倾人国。」
解释：了解，体会。释，一作「识」。
春风：指唐玄宗。。
沉香：亭名，沉香木所筑。', '名花伴着绝色美人令人心欢，赢得君王满面带笑不停地看。
春风中消解了君王无限怅恨，在沉香亭北共同倚靠着阑干。', NULL, '《唐诗直解》：四出媚态，不以刻意工，亦非刻意所能工。
《诗薮》：「明月自来还自去，更无人倚玉阑干」、「解释东风无限恨，沈香亭北倚阑干」，崔鲁、李白同咏玉环事，崔则意极精工，李则语由信笔，然不堪并论者，直是气象不同。
《唐诗解》：太白于极欢之际，加一「恨」字，意甚不浅。
《汇编唐诗十集》：唐云：三诗俱铄金石，此篇更胜。字字得沈香亭真境。
《唐诗选脉会通评林》：同敬曰：「带笑」字下得有情，第三句描贵妃心事。
《唐诗摘钞》：释恨即从「带笑」来。本无恨可释，而云然者，即《左传》（野太子申生）：「君非姬氏（指鲡姬），居不安，食不饱」之意。
《增订唐诗摘钞》：婉腻动人，「解释」句情多韵多。
《古唐诗合解》：此章方写唐皇同妃子同赏木芍药。
《唐诗别裁》：本岂释天户之愁恨，托以「春风」，措词微婉。
《诗法易简录》：此首乃实赋其事而结归明皇也。只「两相欢」三字，直写出美人绝代风神，并写得花亦栩栩欲活，所谓诗中有魂，第三句承次句，末句应首句，章法最佳。
《李太白诗醇》：严沧浪曰：旖旎动人。锦心绣口。
《唐人绝句精华》：第三首总结，点明名花、妃子皆能长邀帝宠者，以能「舞释存风无限恨」也。', 'center', 1417703415, '57b98d22165abd005a6cf8f5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (79597, '奉和令公绿野堂种花', NULL, 110, 2952, 1, 0, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'shi', '诗', 'http://baike.baidu.com/view/8913740.htm', '', '绿野堂开占物华，路人指道令公家。
令公桃李满天下，何用堂前更种花。', '这首七言绝句运用借代的修辞，以桃李代学生，绿野堂指的是唐代裴度的房子名。这首诗通过写裴度房子不用种花就占尽了万物的精华（房子显眼气派）。表现了对一个老师桃李满天下芳名远播的赞美。', '', '绿野堂开着占尽了万物的精华，路人说那就是令公的家。
令公的学生遍布天下，何须在房前再种花呢？', NULL, '', 'center', 1485358741, '585d0a66128fe1006de5be87', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10695, '金缕衣', NULL, 796, 1, 2, 1, '杜秋娘', NULL, 10166, '57b9a1360a2b58006caf0777', '唐', 'shi', '诗', 'http://baike.baidu.com/subview/339513/11924942.htm', '', '劝君莫惜金缕衣，劝君惜取少年时。
花开堪折直须折，莫待无花空折枝。', '这首诗歌寓意人们不要爱惜荣华富贵，而应爱惜少年时光，就像那盛开的鲜花，要及时采摘，如果采摘不及时，等到春残花落之时，就只能折取花枝了。', '金缕衣：缀有金线的衣服，比喻荣华富贵。
堪：可以，能够。
直须：不必犹豫。直：直接，爽快。
莫待：不要等到。', '韵译
我劝你不要顾惜华贵的金缕衣，
我劝你一定要珍惜青春少年时。
花开宜折的时候就要抓紧去折，
不要等到花谢时只折了个空枝。
直译
不要爱惜荣华富贵，一定要爱惜少年时光。就像那盛开枝头的鲜花，要及时采摘。如果采摘不及时，等到春残花落之时，就只能折取花枝了。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ef0ce818559d058a6b", "shortContent": "这是中唐时的一首流行歌词。据说元和时镇海节度使李锜酷爱此词，常命侍妾杜秋娘在酒宴上演唱（见杜牧《杜秋娘诗》及自注）。歌词的作者已不可考。有的唐诗选本径题为杜秋娘作或李锜作，是不确的。\n此诗含意很单纯，可以用“莫负好时光”一言以蔽之。这原是一种人所共有的思想感情。可是，它使读者感到其情感虽单纯却强烈，能长久在人心中缭绕，有一种不可思议的魅力。它每个诗句似乎都在重复那单一的意思：“莫负好时光！”而每句...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "60fc32b023353c0ba53dd945", "bookTitle": "历代女性诗词鉴赏辞典", "articleId": "610ec78703572034f65a8e7c", "shortContent": "这是中唐时的一首流行歌词。据说元和时镇海节度使李锜酷爱此词，常命侍妾杜秋娘在酒宴上演唱。原诗可能并非杜秋娘所作，因《唐诗三百首》等选本将其归于杜氏名下，相沿已久，并有盛名，故仍其旧。\n一、二句用赋，句式相同，都以“劝君”开始。劝你不要贪恋豪华富贵的生活，劝你也不要虚度少年时期的大好时光。“金缕衣”，以金线制成的华丽衣裳，虽是贵重之物，却“劝君莫惜”，可见还有远比它更为珍贵的东西。下一句紧接着就道出...", "authors": ["邓田田"], "pressName": "上海辞书出版社"}, {"bookId": "62777ee88efdff05d7d4e3c9", "bookTitle": "唐诗三百首鉴赏辞典", "articleId": "63126f4e7ccdb86c49f29108", "shortContent": "关于此词作者，向来有两种说法：一是唐代无名氏所作，一是杜秋娘所作。据说，杜秋娘是唐时金陵人，原为节度使李锜妾，善唱《金缕衣》。后入宫，为唐宪宗所宠。穆宗立，为皇子保姆。皇子被废，杜秋娘返回故乡，老无所依。大概因其善唱此曲，故多将此诗题作杜秋娘作。\n\n这是一首充满人生哲理的诗歌。诗的语言虽然浅显通俗，但却讲述了一个珍惜韶光、努力进取的深刻道理，很能引起人们的共鸣，因而千百年来一直广为传诵。\n\n“劝君...", "authors": ["余春丽　乐云"], "pressName": "崇文书局"}]', '陆昶《历代名媛诗词》：词气明爽，手口相应，其「莫惜」、「惜取」、「堪折」、「须折」、「空折」，层层跌宕，读之不厌，可称能事。', 'center', 1417703771, '57b92bdca633bd00665eb99e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10696, '宴山亭 · 北行见杏花', NULL, 786, 455, 2, 1, '赵佶', NULL, 10167, '57b92136c4c9710055903a48', '宋', 'ci', '词', 'http://baike.baidu.com/view/763760.htm', '', '裁剪冰绡，轻叠数重，淡著燕脂匀注。新样靓妆，艳溢香融，羞杀蕊珠宫女。易得凋零，更多少、无情风雨。愁苦，问院落凄凉，几番春暮？
凭寄离恨重重，者双燕，何曾会人言语？天遥地远，万水千山，知他故宫何处？怎不思量？除梦里有时曾去。无据，和梦也新来不做。', '《宴山亭·北行见杏花》是北宋宋徽宗赵佶的词作。徽宗皇帝在被掳北行途中，忽见杏花盛开如火，不禁万感交集，写下这首如泣如诉之词。上片明写杏花，借杏花的娇艳及被风雨摧残的衰败景象象征美好事物的逝去，寄托着对帝王生活的痛苦回忆。也暗示自已的境遇，怜花怜己，语带双关。下片抒写离恨哀情，借燕子与做梦层层深入，道出从期望到失望，由失望而绝望的哀痛心情，末尾几句写连在梦里见一见故国宫殿的慰藉也得不到，因为连梦也做不成。抒情上有递进关系，真挚深沉，真可说是字字泣血，百折千回，悲凉哀婉。', '宴山亭：词牌名。一作《燕山亭》。与《山亭宴》无涉。以宋徽宗赵佶词为准。双阕九十九字。上阕十一句五仄韵，下阕十句五仄韵。上阕第八句为上三下四句式。第九句二字，多为感叹词语，第十句首字领格，引领两个四言句。下阕第二句首字领格。下阕第八句为上三下四句式。下阕第九句多为感叹词语。第十句为上三下四句式。此调有宋徽宗、毛圱、王之道、张雨诸词可校。
冰绡：洁白的丝绸，比喻花瓣。
燕脂：即“胭脂”。
靓（jìng）妆：美丽的妆饰。
蕊珠宫女：指仙女。蕊珠，道家指天上仙宫。
问院：一作“闲院”，然“闲”格律不符，语意不明，故不取。
凭寄：凭谁寄，托谁寄。
者：同“这”。
无据：不知何故。
和：连。', '剪裁好白色的丝绸，轻轻叠成数层，又将淡淡的胭脂均匀地涂抹，时髦的漂亮衣服，艳丽的色彩融入四溢的清香，简直羞杀了天上的蕊珠宫的仙女。红颜易凋零，更何况，经历了多少无情的风雨，面对愁苦的情景，扣问凄凉的院落，还要经受几番春暮。
谁帮我寄去重重的离愁，这双飞的燕子哪里懂得人间的苦痛。天遥地远，万水千山阻隔，哪里知道故园今在何处？只有在梦中有时曾去。就连梦也难做成，因我痛苦地彻夜难眠。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74d0dbb8b379ee08df0b", "shortContent": "宋徽宗赵佶因荒淫失国，在公元1127年与其子钦宗赵桓被金兵掳往北方五国城，囚禁至死。在北行途中，忽见如火的杏花，不禁万感交集，写下了这首词。这是他生活遭遇最悲惨的实录，也可以说是一篇血书。他不仅工书善画，而且知乐能词，足以与南唐李后主媲美。\n这首词上片描绘杏花，运笔极其细腻，好似在作工笔画，由杏花的外形到它的神态，勾勒出一幅绚烂的画面，接着突然一转，描写杏花遭到风雨摧残以后的黯淡场景，从它的极盛到...", "authors": ["唐圭璋"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5d40f8fda55650604d9", "shortContent": "宋徽宗赵佶因荒淫失国，在公元1127年与其子钦宗赵桓被金兵掳往北方五国城，囚禁至死。在北行途中，忽见如火的杏花，不禁万感交集，写下了这首词。这是他生活遭遇最悲惨的实录，也可以说是一篇血书。他不仅工书善画，而且知乐能词，足以与南唐李后主媲美。\n这首词上片描绘杏花，运笔极其细腻，好似在作工笔画，由杏花的外形到它的神态，勾勒出一幅绚烂的画面，接着突然一转，描写杏花遭到风雨摧残以后的黯淡场景，从它的极盛到...", "authors": ["唐圭璋"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592544b56e213e6848047", "shortContent": "宋徽宗赵佶因荒淫失国，在公元1127年与其子钦宗赵桓被金兵掳往北方五国城，囚禁至死。在北行途中，忽见如火的杏花，不禁万感交集，写下了这首词。这是他生活遭遇最悲惨的实录，也可以说是一篇血书。他不仅工书善画，而且知乐能词，足以与南唐李后主媲美。\n\n这首词上片描绘杏花，运笔极其细腻，好似在作工笔画，由杏花的外形到它的神态，勾勒出一幅绚烂的画面，接着突然一转，描写杏花遭到风雨摧残以后的黯淡场景，从它的极盛...", "authors": ["唐圭璋"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f49c26cbf3417f0937e", "shortContent": "《燕山亭》，词牌名。一作《宴山亭》。以宋徽宗赵佶词为准。双片九十九字。\n\n\n\n这首词作于靖康二年（1127），是宋徽宗赵佶与其子钦宗赵桓被金兵掳往北方的途中所写。九五之尊沦为阶下囚，巨大的落差，悲惨的遭遇带来的冲击是巨大的。但是对自然体察入微，工于工笔花鸟画的赵佶，仍然能发现身边的美，北行路上，他的眼光瞟到了春暮的杏花。此时体物的心情与山河破碎的悲痛交织在一起，不是纯粹的写景，而是将自己的身世与杏...", "authors": ["邓安琪"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312703be6f69b71e93f6234", "shortContent": "《燕山亭》，词牌名。一作《宴山亭》。以宋徽宗赵佶词为准，双片九十九字。\n\n这首词作于靖康二年（1127），是宋徽宗赵佶与其子钦宗赵桓被金兵掳往北方的途中所写。九五之尊沦为阶下囚，巨大的落差，悲惨的遭遇带来的冲击是巨大的。但是对自然体察入微，工于工笔花鸟画的赵佶，仍然能发现身边的美，北行路上，他的眼光瞟到了春暮的杏花。此时体物的心情与山河破碎的悲痛交织在一起，不是纯粹的写景，而是将自己的身世与杏花的...", "authors": ["邓安琪"], "pressName": "崇文书局"}]', '唐圭璋《唐宋词简释》：此词为赵佶被俘北行见杏花之作。起首六句，实写杏花。前三句，写花片重叠，红白相间。后三句，写花容艳丽，花气浓郁。“羞杀”一句，总束杏花之美。“易得”以下，转变徵之音，怜花怜己，语带双关。花易凋零一层、风雨摧残一层、院落无人一层，愈转愈深，愈深愈痛。换头，因见双燕穿花，又兴孤栖膻慕之感。燕不会人言语一层、望不见故宫一层、梦里思量一层、和梦不做一层，且问且叹，如泣如诉。总是以心中有万分委曲，故有此无可奈何之哀音，忽吞咽，忽绵邈，促节繁音，回肠荡气。况蕙风云：“真”字是词骨，若此词及后主之作，皆以“真”胜者。', 'indent', 1418770860, '57b33848c4c971005496781b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10697, '玉楼春', NULL, 822, 105, 4, 1, '钱惟演', NULL, 10168, '57bb0ee6165abd006628622b', '宋', 'ci', '词', 'http://baike.baidu.com/view/2832676.htm', '', '城上风光莺语乱，城下烟波春拍岸。绿杨芳草几时休，泪眼愁肠先已断。
情怀渐觉成衰晚，鸾镜朱颜惊暗换。昔年多病厌芳尊，今日芳尊惟恐浅。', '词中用清丽的语言描绘了春声、春色，首句的「乱」字用得极好，将春景渲染得十分生动热闹，而群莺乱啼已是暮春天气，这里也暗含春光将尽之意。作者又用明丽的景色来反衬自己凄黯的心情，以及对于年光飞逝，生命无多的感伤。末二句以借酒浇愁来表现他无可奈何的心情，又隐约地显示了他对生命的留恋，尤其传神。', '玉楼春：词牌名。《词谱》谓五代后蜀顾夐词起句有「月照玉楼春漏促」、「柳映玉楼春欲晚」句；欧阳炯起句有「日照玉楼花似锦」、「春早玉楼烟雨夜」句，因取以调名。亦称《木兰花》、《春晓曲》、《西湖曲》、《惜春容》、《归朝欢令》等。双调五十六字，前后阕格式相同，各三仄韵，一韵到底。
莺语：黄莺婉转鸣叫好似低语。
拍岸：拍打堤岸。
鸾镜：镜子。古有「鸾睹镜中影则悲」的说法，以後常把照人的镜子称为「鸾镜」。
朱颜：这里指年轻的时候。
芳尊：盛满美酒的酒杯，也指美酒。', '城上春光明媚莺啼燕啭，城下碧波荡漾拍打堤岸。绿杨芳草几时才会衰败？我泪眼迷蒙愁肠寸断。
人到晚年渐觉美好情怀在衰消，面对鸾镜惊看红颜已暗换。想当年曾因多病害怕举杯，而如今却唯恐酒杯不满。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749c911759740c9aa29f", "shortContent": "据胡仔《苕溪渔隐丛话后集》卷三十九引《侍儿小名录》载：“钱思公谪汉东（即随州，今湖北随县）日，撰《玉楼春》词云云，每酒阑歌之则泣下。后阁有白发姬，乃邓王（惟演父俶）歌鬟惊鸿也，遽言：‘先王将薨，预戒挽铎中歌《木兰花》（即《玉楼春》）引绋为送，今相公亦将亡乎？’果薨于随州。邓王旧曲，亦尝有‘帝乡烟雨锁春愁，故国山川空泪眼’之句。”宋仁宗明道二年（1033）三月，垂帘听政的刘太后崩，仁宗开始亲政，即着...", "authors": ["陈允吉", "胡中行"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a47d0ac1145495e851", "shortContent": "据胡仔《苕溪渔隐丛话后集》卷三十九引《侍儿小名录》载：“钱思公谪汉东（即随州，今湖北随县）日，撰《玉楼春》词云云，每酒阑歌之则泣下。后阁有白发姬，乃邓王（惟演父俶）歌鬟惊鸿也，遽言：‘先王将薨，预戒挽铎中歌《木兰花》（即《玉楼春》）引绋为送，今相公亦将亡乎？’果薨于随州。邓王旧曲，亦尝有‘帝乡烟雨锁春愁，故国山川空泪眼’之句。”宋仁宗明道二年（1033）三月，垂帘听政的刘太后崩，仁宗开始亲政，即着...", "authors": ["陈允吉", "胡中行"], "pressName": "上海辞书出版社"}, {"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126df6c305cf0801816c24", "shortContent": "此词又传为曹勋作，见《松隐文集》。又《南唐二主词》原注云：“传自曹功显节度家。”又云：“墨迹旧在京师梁门外李王寺。”疑曹勋尝书此词，后人遂以为勋作也。\n\n《全唐诗·附词》作“木兰花”，注：“一名‘玉楼春’，一名‘春晓曲’，一名‘惜芳容’，”", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f39e6f69b71e93f6185", "shortContent": "《木兰花》又名《玉楼春》，是词人临死前的伤春之作。宋仁宗明道二年（1033）三月，垂帘听政的刘太后。仁宗亲政，迅速清除刘太后党羽，其中包括作为刘太后姻亲的钱惟演。九月，钱惟演即因擅议宗庙罪而被免除平章事的官职，贬为崇信军节度使，谪居汉东（今湖北随州）。该词就写于这个时期。作品借丽景抒哀情，首句一“乱”字可谓词眼，将春景的声色和暮年的凄黯两相对比，反差强烈，凄婉动人。\n\n上阕由景入情，下阕直抒愁怀。...", "authors": ["何光顺"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe47ccdb86c49f29173", "shortContent": "《木兰花》又名《玉楼春》，是词人临死前的伤春之作。宋仁宗明道二年（1033）三月，垂帘听政的刘太后。仁宗亲政，迅速清除刘太后党羽，其中包括作为刘太后姻亲的钱惟演。九月，钱惟演即因擅议宗庙罪而被免除平章事的官职，贬为崇信军节度使，谪居汉东（今湖北随州）。该词就写于这个时期。作品借丽景抒哀情，首句一“乱”字可谓词眼，将春景的声色和暮年的凄黯两相对比，反差强烈，凄婉动人。\n\n上阕由景入情，下阕直抒愁怀。...", "authors": ["何光顺"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127174c305cf08018170a9", "shortContent": "《木兰花》又名《玉楼春》，是词人临死前的伤春之作。宋仁宗明道二年（1033）三月，垂帘听政的刘太后死。仁宗亲政，迅速清除刘太后党羽，其中包括作为刘太后姻亲的钱惟演。九月，钱惟演即因擅议宗庙罪而被免除平章事的官职，贬为崇信军节度使，谪居汉东（今湖北随州）。该词就写于这个时期。作品借丽景抒哀情，首句一“乱”字可谓词眼，将春景的声色和暮年的凄黯两相对比，反差强烈，凄婉动人。\n上阕由景入情，下阕直抒愁怀。...", "authors": ["何光顺"], "pressName": "崇文书局"}]', '宋·胡元任《苕溪渔隐丛话》：侍儿小名录云：钱恩公谪汉东日（指钱思王晚年谪随州），撰《玉楼春》词曰：「城上风光莺语乱，城下烟波春拍岸。绿杨芳草几时休，泪眼愁肠先已断。情怀渐变成衰晚，鸾镜朱颜惊暗换。往年多病厌芳樽，今日芳樽惟恐浅。」每酒阑歌之，则泣下。後阁有白发姬，乃邓王歌鬟惊鸿也。遽言：「先王将薨，预戒挽铎中歌木兰花引绋为送。今相公亦将亡乎。」果薨于随州。
宋·黄玉林《花菴词选》：此公暮年之作，极凄惋。
明·李沧溟：妙处俱在末结语传神。
沈震峰《草堂诗馀正集》：芳尊恐浅，正断肠处，情尤真笃。
清·张藕村《词林纪事》：公谪汉东日，撰玉楼春词，酒阑歌之，必为泣下。', 'indent', 1418770988, '57b46826c4c971005f8b7268', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10698, '御街行 · 秋日怀旧', NULL, 712, 328, 6, 4, '范仲淹', NULL, 10032, '57b9849979bc44006028bbf4', '宋', 'ci', '词', 'http://baike.baidu.com/view/14584926.htm', '', '纷纷坠叶飘香砌，夜寂静，寒声碎。真珠帘卷玉楼空，天淡银河垂地。年年今夜，月华如练，长是人千里。
愁肠已断无由醉，酒未到，先成泪。残灯明灭枕头攲，谙尽孤眠滋味。都来此事，眉间心上，无计相回避。', '这是一首秋夜怀思情人的词。上阕写秋夜景，或就地面刻画秋声，或就天宇描摹夜色，以寒夜秋声衬托主人公所处环境的冷寂，突出人去楼空的落寞感，并抒发了良辰美景无人与共的愁情。沈震峰居《草堂诗馀隽》称赏「天淡」句写景空灵。下阕专就离情宣发。「愁肠」三句折进一层，言离愁之深。「残灯」二句再现实境，一盏如豆的青灯忽明忽暗，独自凭栏斜倚，尝尽这孤眠的滋味。末以离愁「眉间心上」无所不在，倍增酸楚。「都来此事」几句为李易安《一剪梅》词所袭用，化作「此情无计可消除，才下眉头，却上心头」，向来为词评家所赞誉。这首词虽写似水柔情，却骨力道劲，绝不流于软媚。李沧溟云：「月光如昼，泪深于酒，情景两到」，可谓佳评。', '香砌：有落花的台阶。
寒声碎：寒风吹动落叶发出的轻微细碎的声音。
真珠：珍珠。
天淡：天空清澈无云。
月华：月光。
练：白色的丝绸。
无由：无法。
明灭：忽明忽暗。
攲（qī）：倾斜，斜靠。
谙（ān）尽：尝尽。
都来：算来。', '纷纷杂杂的树叶飘落在透着清香的石阶上，当夜深人静之时，那悉悉索索的落叶声更增添了秋天的凉意。卷起珍珠串成的锦帘，华丽的楼阁上空空荡荡，只见到高天淡淡，银河的尽头像垂到大地。年年今天的夜里，都能见到那素绡般的皎月，而年年今天的夜里，心上人都远在千里之外。
愁肠已经寸断，想要借酒浇愁，也难以使自己沉醉。酒还没有入口，却先化作了辛酸的眼泪。夜已深，灯已残，灯火明灭之间，只好斜靠枕头，聊作睡去，这无休无止的孤栖，真让人尝尽了孤独相思的滋味。算来这苦苦的等待尚遥遥无期，虽说是终日眉头紧锁，心绪万千，也没有一点办法可以解脱回避。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749d5914587d02f465b9", "shortContent": "这词一本有副题“秋日怀旧”，是一首怀人之作，其间洋溢着一片柔情。即所谓“铁石心肠人亦作此消魂语”（许昂霄《词综偶评》）。上片描绘秋夜寒寂的景象，下片抒写孤眠愁思的情怀，由景入情，情景交融。\n秋夜景象，作者只抓住秋声和秋色，便很自然地引出秋思。欧阳修《秋声赋》说：“星月皎洁，明河在天，四无人声，声在树间。”这首词上片写的正是这种境界。一叶落知天下秋，到了秋天树叶大都变黄飘落。树叶纷纷飘坠在香砌（香阶...", "authors": ["林东海"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a50ce818559d063ad2", "shortContent": "这词一本有副题“秋日怀旧”，是一首怀人之作，其间洋溢着一片柔情。即所谓“铁石心肠人亦作此消魂语”（许昂霄《词综偶评》）。上片描绘秋夜寒寂的景象，下片抒写孤眠愁思的情怀，由景入情，情景交融。\n秋夜景象，作者只抓住秋声和秋色，便很自然地引出秋思。欧阳修《秋声赋》说：“星月皎洁，明河在天，四无人声，声在树间。”这首词上片写的正是这种境界。一叶落知天下秋，到了秋天树叶大都变黄飘落。树叶纷纷飘坠在香砌（香阶...", "authors": ["林东海"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252ccce4d48ba496d7a", "shortContent": "这词一本有副题“秋日怀旧”，是一首怀人之作，其间洋溢着一片柔情。即所谓“铁石心肠人亦作此消魂语”（许昂霄《词综偶评》）。上片描绘秋夜寒寂的景象，下片抒写孤眠愁思的情怀，由景入情，情景交融。\n\n秋夜景象，作者只抓住秋声和秋色，便很自然地引出秋思。欧阳修《秋声赋》说：“星月皎洁，明河在天，四无人声，声在树间。”这首词上片写的正是这种境界。一叶落知天下秋，到了秋天树叶大都变黄飘落。树叶纷纷飘坠在香砌（香...", "authors": ["林东海"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3a7ccdb86c49f29097", "shortContent": "这是一首秋夜怀人的词作，上阕细致描写了秋夜寒冷孤寂的凄清景象，下阕抒发了词人孤枕难眠的情怀。全篇由景入情，情景交融，愁绪万千。\n\n上阕起于落叶的声音。清寂长夜漫漫，树叶扑簌下落的细碎声不绝于耳，不时便铺满台阶。“纷纷”，既是繁多落叶，亦是作者心中的万千愁绪。一个“寒”字，写景陈情兼而有之，是时节寒凉，更是独居一隅的孤苦凄寒。词人未着一字于秋，然耳边乃叶落声声，身边系寒意阵阵。听觉与感觉兼而有之，不...", "authors": ["吴璐薇"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe9f2af4e09d55b66e0", "shortContent": "这是一首秋夜怀人的词作，上阕细致描写了秋夜寒冷孤寂的凄清景象，下阕抒发了词人孤枕难眠的情怀。全篇由景入情，情景交融，愁绪万千。\n\n上阕起于落叶的声音。清寂长夜漫漫，树叶扑簌下落的细碎声不绝于耳，不时便铺满台阶。“纷纷”，既是繁多落叶，亦是作者心中的万千愁绪。一个“寒”字，写景陈情兼而有之，是时节寒凉，更是独居一隅的孤苦凄寒。词人未着一字于秋，然耳边乃叶落声声，身边系寒意阵阵。听觉与感觉兼而有之，不...", "authors": ["吴璐薇"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312717c73206168b2e02326", "shortContent": "这是一首秋夜怀人的词作，上阕细致描写了秋夜寒冷孤寂的凄清景象，下阕抒发了词人孤枕难眠的情怀。全篇由景入情，情景交融，愁绪万千。\n上阕起于落叶的声音。清寂长夜漫漫，树叶扑簌下落的细碎声不绝于耳，不时便铺满台阶。“纷纷”，既是繁多落叶，亦是作者心中的万千愁绪。一个“寒”字，写景陈情兼而有之。是时节寒凉，更是独居一隅的孤苦凄寒。词人未着一字于秋，然耳边乃叶落声声，身边系寒意阵阵。听觉与感觉兼而有之，不言...", "authors": ["吴璐薇"], "pressName": "崇文书局"}]', '', 'indent', 1418771351, '57b91b140a2b58005c931cdf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10704, '菩萨蛮', NULL, 258, 267, 3, 2, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'http://baike.baidu.com/view/1648739.htm', '', '哀筝一弄湘江曲，声声写尽湘波绿。纤指十三弦，细将幽恨传。
当筵秋水慢，玉柱斜飞雁。弹到断肠时，春山眉黛低。', '这首词描写了一位弹筝歌伎的美貌和高超的技艺，并刻画了她内心深处的哀怨，表现了她丰富而美好的感情，给我们塑造了一个内在和外貌一样美好的歌女形象。全词语辞清美婉丽，情感真挚凄哀，风格含蓄深沉。', '弄：演奏乐曲。
湘江曲：曲名，即《湘江怨》。相传舜帝南巡苍梧，二妃追至南方，闻舜卒，投江而死。后人以此为题材写成乐曲。
十三弦：汉史游《急就篇》之三颜师古注：“筝，亦小瑟类也，本十二弦，今则十三。”
秋水：秋天的水，比喻人（多指女人）清澈明亮的眼睛。
慢：形容眼神凝注。
玉柱斜飞雁：古筝弦柱斜列如雁行，故又称雁柱。
春山：喻美人的眉峰。
眉黛：古代女子用黛画眉，故称眉为眉黛，黛，青黑色的颜料。', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74adc6e67846a9206b02", "shortContent": "晏幾道早年风流浪漫，与沈廉叔、陈君龙友善，每作词，授两家歌女莲、鸿、蘋、云等演唱，以为娱乐。他的词大部分为这些歌女而作，本篇也是如此。词中虽有音乐描写，但意旨不在音乐，而是借写弹筝来表现那位当筵演奏的歌妓。《小山词》中有多处提到筝，如《鹧鸪天》：“手撚香笺忆小莲，欲将遗恨倩谁传。……秦筝算有心情在，试写离声入旧弦。”《木兰花》：“小莲未解论心素，狂似钿筝弦底柱。”筝和小莲往往并提，这首词里所写的弹...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b334a8757d5a0eca81", "shortContent": "晏几道早年风流浪漫，与沈廉叔、陈君龙友善，每作词，授两家歌女莲、鸿、蘋、云等演唱，以为娱乐。他的词大部分为这些歌女而作，本篇也是如此。词中虽有音乐描写，但意旨不在音乐，而是借写弹筝来表现那位当筵演奏的歌妓。《小山词》中有多处提到筝，如《鹧鸪天》“手撚香笺忆小莲，欲将遗恨倩谁传。……秦筝算有心情在，试写离声入旧弦”，《木兰花》“小莲未解论心素，狂似钿筝弦底柱”。筝和小莲往往并提，这首词里所写的弹筝者...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592534b56e213e6848035", "shortContent": "晏几道早年风流浪漫，与沈廉叔、陈君龙友善，每作词，授两家歌女莲、鸿、\"、云等演唱，以为娱乐。他的词大部分为这些歌女而作，本篇也是如此。词中虽有音乐描写，但意旨不在音乐，而是借写弹筝来表现那位当筵演奏的歌妓。《小山词》中有多处提到筝，如《鹧鸪天》“手撚香笺忆小莲，欲将遗恨倩谁传。……秦筝算有心情在，试写离声入旧弦”，《木兰花》“小莲未解论心素，狂似钿筝弦底柱”。筝和小莲往往并提，这首词里所写的弹筝者...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}, {"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "6467918a7da2f75ac7f48e2e", "shortContent": "晏幾道早年风流浪漫，与沈廉叔、陈君龙友善，每作词，授两家歌女莲、鸿、[插图]、云等演唱，以为娱乐。他的词大部分为这些歌女而作，本篇也是如此。词中虽有音乐描写，但意旨不在音乐，而是借写弹筝来表现那位当筵演奏的歌妓。《小山词》中有多处提到筝，如《鹧鸪天》“手撚香笺忆小莲，欲将遗恨倩谁传。……秦筝算有心情在，试写离声入旧弦”，《木兰花》“小莲未解论心素，狂似钿筝弦底柱”。筝和小莲往往并提，这首词里所写的...", "authors": ["余恕诚"], "pressName": "上海辞书出版社"}]', '黄蓼园《蓼园词评》：按，写筝耶？寄托耶？意致却极凄婉。末句意浓而韵远，妙在能蕴藉。', 'indent', 1418810179, '57b908415bbb50005b785ffd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10699, '千秋岁', NULL, 414, 190, 2, 3, '张先', NULL, 10169, '57bac637c4c97100614fdfe7', '宋', 'ci', '词', 'http://baike.baidu.com/view/2800793.htm', '', '数声鶗鴂，又报芳菲歇。惜春更把残红折，雨轻风色暴，梅子青时节。永丰柳，无人尽日花飞雪。
莫把幺弦拨，怨极弦能说。天不老，情难绝，心似双丝网，中有千千结。夜过也，东窗未白孤灯灭。', '这首词是惜春怀人，抒写爱情横遭阻抑的幽怨之作。上阕描写残春之景、惜春之情。开首即把鸣声悲切的鶗鴂提出来，说它向人们报道美好的春光又过去了。「又报」二字，显然表明作者对「芳菲」爱恋之深长已非一年，而此情却粗暴地频遭打击。「雨轻风色暴，梅子青时节」，这两句表面是写时令、写景物，实是说爱情遭受破坏，「梅子黄时雨」这是正常的，谁料梅子青时，便被无情的风暴突袭，青春初恋遭此打击，其何以堪！下阕抒情，承上阕「惜春」而生发出爱春、恋春之意，表现出情感的大幅度的跳跃和升华，而这爱春、恋春之意恰恰基于对「风色暴」的怨恨。「心似双丝网，中有千千结」是全词表达思想感情的高峰。情思未了，不觉春宵已经过去，这时东窗未白，残月犹明，如此作结，可谓恰到好处。此词写景寓情，亦景亦情，借景物隐喻、象征人生情感的历程和隐秘；抒情热烈、果决，倾吐心声，爱憎鲜明。情韵高远，既深婉、含蓄，又直率、激越。', '千秋岁：词牌名。
鶗鴂（tíjué）：即子规、杜鹃。《离骚》：「恐鶗鴂之未先鸣兮，使夫百草为之不劳。」
芳菲：花草，亦指春时光景。
永丰柳：唐时洛阳永丰坊西南角荒园中有垂柳一株被冷落，白乐天赋《杨柳枝词》：「永丰西角荒园里，尽日无人属阿谁。」以喻家妓小蛮。後传入乐府，因以「永丰柳」泛指园柳，喻孤寂无靠的女子。
花飞雪：指柳絮。一作：飞花雪。
把：持，握。
幺弦：琵琶的第四弦，各弦中最细，故称。亦泛指短弦、小弦。
孤灯灭：一作“凝残月”。
', '数声杜鹃的鸣啼，又报告烂漫春光将要凋谢。惜春人更想将那残花折。怎奈何雨虽轻柔风却猛烈，正赶上这梅子发青的暮春时节。看那永丰坊的柳树，在无人的园中整日撒飞絮如飘雪。
切莫把琵琶的细弦拨动，我深深的哀怨细弦也难倾泻。天如有情不会老，真情永不会灭绝。多情的心就像那双丝网，中间有千千万万个结。此夜悄然过去了，东方还未白，孤灯先已灭。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74a103572034f6596255", "shortContent": "这首词是写爱情横遭阻抑的幽怨情怀和坚决不移的信念。\n作者张先以“不如桃杏，犹解嫁东风”及“云破月来花弄影”诸名句蜚声北宋词坛。在现存一百八十首词中，内容涉及爱情、友谊、风土等多方面。尤其擅长写悲欢离合之情，能曲尽其妙。此词就是其中之一。词调《千秋岁》声情激越，宜于抒发抑郁的情怀，秦观写的一首（水边沙外）也是如此。\n本词上片沉痛地回顾爱情遭到破坏，但无一语明说。完全运用描写景物来烘托、暗示，让读者自...", "authors": ["宛敏灏"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a934a8757d5a0eca66", "shortContent": "这首词是写爱情横遭阻抑的幽怨情怀和坚决不移的信念。\n作者张先以“不如桃杏，犹解嫁东风”及“云破月来花弄影”诸名句蜚声北宋词坛。在现存一百八十首词中，内容涉及爱情、友谊、风土等多方面。尤其擅长写悲欢离合之情，能曲尽其妙。此词就是其中之一。词调《千秋岁》声情激越，宜于抒发抑郁的情怀，秦观写的一首（水边沙外）也是如此。\n本词上片沉痛地回顾爱情遭到破坏，但无一语明说。完全运用描写景物来烘托、暗示，让读者自...", "authors": ["宛敏灏"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252251899613caec099", "shortContent": "这首词是写爱情横遭阻抑的幽怨情怀和坚决不移的信念。\n\n作者张先以“不如桃杏，犹解嫁东风”及“云破月来花弄影”诸名句蜚声北宋词坛。在现存一百八十首词中，内容涉及爱情、友谊、风土等多方面。尤其擅长写悲欢离合之情，能曲尽其妙。此词就是其中之一。词调《千秋岁》声情激越，宜于抒发抑郁的情怀，秦观写的一首（水边沙外）也是如此。\n\n本词上片沉痛地回顾爱情遭到破坏，但无一语明说。完全运用描写景物来烘托、暗示，让读...", "authors": ["宛敏灏"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3a7ccdb86c49f29099", "shortContent": "这是一首伤春怀人的词作。上阕着力写景，通过景物描写来烘托、暗示美好爱情横遭阻抑的沉痛之情。疾风细雨，吹落遍地繁花；杜鹃啼血，哀鸣声声入耳；青梅挂枝，柳絮似雪，转眼春已迟暮。林花谢了春红，惜春的词人穿梭于花丛间，采摘着雨打风吹后的那一点残红。首句源出《离骚》：“恐鶗鴂之先鸣兮，使夫百草为之不芳。”鶗鴂，即杜鹃，传说中蜀帝杜宇的化身，啼鸣于暮春时节，声音凄切，此处乃词人情感受挫的愁苦之音。“残红”，象...", "authors": ["吴璐薇"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe9f2af4e09d55b66e2", "shortContent": "这是一首伤春怀人的词作。上阕着力写景，通过景物描写来烘托、暗示美好爱情横遭阻抑的沉痛之情。疾风细雨，吹落遍地繁花；杜鹃啼血，哀鸣声声入耳；青梅挂枝，柳絮似雪，转眼春已迟暮。林花谢了春红，惜春的词人穿梭于花丛间，采摘着雨打风吹后的那一点残红。首句源出《离骚》：“恐鶗鴂之先鸣兮，使夫百草为之不芳。”鶗鴂，即杜鹃，传说中蜀帝杜宇的化身，啼鸣于暮春时f节，声音凄切，此处乃词人情感受挫的愁苦之音。“残红”，...", "authors": ["吴璐薇"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312717d73206168b2e02328", "shortContent": "这是一首伤春怀人的词作。上阕着力写景，通过景物描写来烘托、暗示美好爱情横遭阻抑的沉痛之情。疾风细雨，吹落遍地繁花；杜鹃啼血，哀鸣声声入耳；青梅挂枝，柳絮似雪，转眼春已迟暮。林花谢了春红，惜春的词人穿梭于花丛间，采摘着雨打风吹后的那一点残红。首句源出《离骚》“恐鶗鴂之先鸣兮，使夫百草为之不芳。”鶗鴂，即杜鹃，传说中蜀帝杜宇的化身，啼鸣于暮春时节，声音凄切，此处乃词人情感受挫的愁苦之音。“残红”，象征...", "authors": ["吴路薇"], "pressName": "崇文书局"}]', '', 'indent', 1418771648, '57b93a24165abd0054c1b37a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10700, '醉垂鞭', NULL, 347, 190, 1, 1, '张先', NULL, 10169, '57bac637c4c97100614fdfe7', '宋', 'ci', '词', 'http://baike.baidu.com/view/2800666.htm', '', '双蝶绣罗裙，东池宴，初相见。朱粉不深匀，闲花淡淡春。
细看诸处好，人人道，柳腰身。昨日乱山昏，来时衣上云。', '这首词描绘了一位酒宴上的美丽的歌伎。上片写酒宴初见此伎的第一印象。首先映入眼帘的是彩绣双蝶的罗裙，这表明她步态轻盈曼妙，罗裙飘飘，双蝶似随之翩然飞舞。此乃乍见此伎而尚未仔细端详的第一印象，也正是此伎服饰、步态的突出特征。“朱粉”二句描绘她的容颜：略施朱粉，淡妆素雅，仿佛春意淡淡中开放的一朵平常小花，给人一种清新淡雅的感觉。
下片写对此伎美态、神韵的特殊印象。“细看”二句写词人与众宾客对此伎美态的交口赞叹：人人赞她“柳腰身”，作者赞她“诸处好”，前者强调她腰身的柔婉、曼妙，后者强调她浑身的谐和、优美。“双蝶绣罗裙”，原来是她的舞裙。此妓的舞姿、神韵如何呢？从“人人道”的侧面反应和作者的主观感受烘染了她舞姿的美妙。“昨日”两句似离题横出，其实是作者对其舞容的强烈印象：“乱山昏”是形容她舞蹈时眼前似乎从群山腾起云霞缭乱、迷濛。
综上而言，上片“闲花”意象，出之于客观比较，是静态写意；下片“乱云”意象，出之于主观感受，是动态传神。特别是“昨日”二句意象新妙，想象出奇，亦真亦幻，耐人深味。这正是张先小令“韵高”之典型。', '醉垂鞭：词牌名。张先创调。双调四十二字，前后段各五句，三平韵、两仄韵。
“双蝶绣罗裙”句：罗裙上绣着双飞的蝴蝶。
“朱粉不深匀”句：脸上涂着淡淡的胭脂。', '池东的酒宴上初次见到你，穿的是绣有双蝶的罗裙。娇美的脸上只涂着淡淡的白粉，恰如一朵野花，恬淡而幽雅地沐浴着芳春。
细细端详，你真是尽善尽美，人人都夸赞你细柳般的腰身。你的到来，莫不是昨晚从巫山深处飘然而至？因为你来的时候，衣服上还像带着浮动的白云。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74a05914587d02f465c3", "shortContent": "这首词是酒筵中赠妓之作，以写其人的装束开头，但只写了一半，即她所穿的裙子。罗裙上绣着双飞的蝴蝶，已经很漂亮了，但等到读了结句，才知道，更漂亮的、能够使人产生丰富的联想的，还不是她的裙，而是她的衣。\n“东池”两句，记相见之地———东池、相见之因———宴，并且点明她“侑酒”的身份。“朱粉”两句，接着写其人之面貌，而着重于化妆的特征———淡妆。词人在这里，摆脱一切正面描绘，而代之以一个确切的、具体的比喻...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a8d635634aee3e9a5f", "shortContent": "这首词是酒筵中赠妓之作，以写其人的妆束开头，但只写了一半，即她所穿的裙子。罗裙上绣着双飞的蝴蝶，已经很漂亮了，但等到读了结句，才知道，更漂亮的、能够使人产生丰富的联想的，还不是她的裙，而是她的衣。\n“东池”两句，记相见之地———东池、相见之因———宴，并且点明她“侑酒”的身份。“朱粉”两句，接着写其人之面貌，而着重于化妆的特征———淡妆。词人在这里，摆脱一切正面描绘，而代之以一个确切的、具体的比喻...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252ccce4d48ba496d88", "shortContent": "这首词是酒筵中赠妓之作，以写其人的妆束开头，但只写了一半，即她所穿的裙子。罗裙上绣着双飞的蝴蝶，已经很漂亮了，但等到读了结句，才知道，更漂亮的、能够使人产生丰富的联想的，还不是她的裙，而是她的衣。\n\n“东池”两句，记相见之地——东池、相见之因——宴，并且点明她“侑酒”的身份。“朱粉”两句，接着写其人之面貌，而着重于化妆的特征——淡妆。词人在这里，摆脱一切正面描绘，而代之以一个确切的、具体的比喻，这...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3a7ccdb86c49f2909b", "shortContent": "张先的词作以反映士大夫的诗酒生活和男女之情居多。《醉垂鞭》是他首创的词调，全词塑造了一个别具风姿的舞妓形象。\n开场便是一个特写镜头，使读者目光迅速聚焦于所写主人公身上。丝罗织就的长裙上绣着成对的彩蝶，令人不禁遐想伊人轻移莲步时，双蝶随着裙摆翻飞而振翅欲舞的动人景象。“东池宴，初相见”交代词作背景，点明女主人公是宴席上一名劝酒助兴的舞妓。回看前一句，蓦然发现词人选择的观察视角正符合“酒宴初见”的情形...", "authors": ["丘　悦"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe9f2af4e09d55b66e4", "shortContent": "张先的词作以反映士大夫的诗酒生活和男女之情居多。《醉垂鞭》是他首创的词调，全词塑造了一个别具风姿的舞妓形象。\n\n开场便是一个特写镜头，使读者目光迅速聚焦于所写主人公身上。丝罗织就的长裙上绣着成对的彩蝶，令人不禁遐想伊人轻移莲步时，双蝶随着裙摆翻飞而振翅欲舞的动人景象。“东池宴，初相见”交代词作背景，点明女主人公是宴席上一名劝酒助兴的舞妓。回看前一句，蓦然发现词人选择的观察视角正符合“酒宴初见”的情...", "authors": ["丘悦"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312717d73206168b2e0232a", "shortContent": "张先的词作以反映士大夫的诗酒生活和男女之情居多。《醉垂鞭》是他首创的词调，全词塑造了一个别具风姿的舞伎形象。\n开场便是一个特写镜头，使读者目光迅速聚焦于所写主人公身上。丝罗织就的长裙上绣着成对的彩蝶，令人不禁遐想伊人轻移莲步时，双蝶随着裙摆翻飞而振翅欲舞的动人景象。\n“东池宴，初相见”交代词作背景，点明女主人公是宴席上一名劝酒助兴的舞伎。回看前一句，蓦然发现词人选择的观察视角正符合“酒宴初见”的情...", "authors": ["丘悦"], "pressName": "崇文书局"}]', '周济《宋四家词选》：横绝。', 'indent', 1418771733, '57b8fe802e958a005fa53985', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10701, '一丛花', NULL, 285, 190, 2, 2, '张先', NULL, 10169, '57bac637c4c97100614fdfe7', '宋', 'ci', '词', 'http://baike.baidu.com/view/2928822.htm', '', '伤高怀远几时穷？无物似情浓。离愁正引千丝乱，更东陌，飞絮蒙蒙。嘶骑渐遥，征尘不断，何处认郎踪？
双鸳池沼水溶溶，南北小桡通。梯横画阁黄昏后，又还是斜月帘栊。沉恨细思，不如桃杏，犹解嫁东风。', '这是一首闺怨词，写一位女子念远伤怀的情状。上片用倒叙的手法先着意渲染女主人公的愁绪。开首“伤高”二句写登阁远望，以爱怨交织的激情向高天远地提出质问，发泄强烈的伤怀、无穷的悲呼，仿佛自问自答。“无物似情浓”，言世间无物能比我之相思情爱更浓，对“情”做了富有哲理性的概括，强调了世间唯有情最浓，揭示了女主人公伤怀无穷的原因。
下片写相思无奈的“沉恨”和空虚。“双鸳”两句写女主人公登阁所见南北小舟交通的池沼。“池中双鸳”正如当年情侣欢聚爱恋的情景，它引发女子对昔日欢情的甜蜜回忆，也触动她此刻的孤单寂寞的情怀。更难堪者是“黄昏后”的寂寞，当家家夫妻团聚，情侣“人约黄昏后”的欢聚时刻，自己却“梯横画阁”，闷坐空闺，当年从画阁竖梯窗下迎候情郎登阁欢会的情事已化为虚空，只剩下一弯冷月斜照窗帘！在极度空虚中，她发出人生之“沉恨”：“不如桃杏，犹解嫁东风”，倾诉了人不如物的伤感。
整首词紧扣“伤高怀远”，从登楼远望回忆，收归近处的池沼、眼前的楼阁，最后收拍到自身，由远而近，次第井然。', '千丝：指很多柳条。丝，指杨柳的长条。
陌：田间小路。
嘶骑：嘶叫的马声。
溶溶：宽广的样子。
桡：划船的桨，这里指船。
梯横：是说可搬动的梯子已被横放起来，即撤掉了。画阁：有彩绘装饰的楼阁。
帘栊：带帘子的窗户。
解：知道，能。嫁东风：原意是随东风飘去，即吹落。嫁，这里用其比喻义。李贺《南园十三首》诗之一：“可怜日暮嫣香落，嫁与东风不用媒。”', '登高怀远，心中的伤痛何时能了，世间万物没有什么比情还浓的。离愁就像那千万枝柳条随风乱舞，还有那东街纷扬的飞絮一片迷蒙。嘶叫的马儿渐渐远去，扬起的尘土绵绵不断，到哪里去寻觅情郎的行踪？
池塘里春水溶溶，一对鸳鸯纵情嬉戏，池中小船儿往来于南北两岸。黄昏后我走下画阁收起梯子，又看见一弯斜月照进帘栊。满怀着幽恨，细细想来，真不如那桃花杏花，还知道及时嫁给东风，随风而去呢。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74a1c6e67846a9206acd", "shortContent": "张先的词，工于刻画景物，锻炼字句，但往往伤于纤巧，但他这首抒写“伤高怀远”之情的《一丛花令》，却既有警句俊语，又极富抒情气氛，在他的词作中是意境浑融、富于情韵的。\n劈头一句，便用重笔直接抒慨：“伤高怀远几时穷？”这是在经历了长久的离别、体验过多次伤高怀远之苦以后，盘郁萦绕在胸中的感情的倾泻。它略去了前此的许多情事，也概括了前此的许多情事。起得突兀有力，感慨深沉。\n紧接着一句“无物似情浓”，是对“几...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a82cee9a0c24ed9e22", "shortContent": "张先的词，工于刻画景物，锻炼字句，但往往伤于纤巧，但他这首抒写“伤高怀远”之情的《一丛花令》，却既有警句俊语，又极富抒情气氛，在他的词作中是意境浑融，富于情韵的。\n劈头一句，便用重笔直接抒慨：“伤高怀远几时穷？”这是在经历了长久的离别、体验过多次伤高怀远之苦以后，盘郁萦绕在胸中的感情的倾泻。它略去了前此的许多情事，也概括了前此的许多情事。起得突兀有力，感慨深沉。\n紧接着一句“无物似情浓”，是对“几...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252251899613caec097", "shortContent": "张先的词，工于刻画景物，锻炼字句，但往往伤于纤巧，但他这首抒写“伤高怀远”之情的《一丛花令》，却既有警句俊语，又极富抒情气氛，在他的词作中是意境浑融，富于情韵的。\n\n劈头一句，便用重笔直接抒慨：“伤高怀远几时穷？”这是在经历了长久的离别、体验过多次伤高怀远之苦以后，盘郁萦绕在胸中的感情的倾泻。它略去了前此的许多情事，也概括了前此的许多情事。起得突兀有力，感慨深沉。\n\n紧接着一句“无物似情浓”，是对...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3a7ccdb86c49f2909c", "shortContent": "此词由题材观之，不过是寻常的闺怨词。唯其情挚感人，故成为惯写男欢女爱的张先笔下一抹夺目的殊色。由结构观之，沈祖棻概其“上片情中之景，下片景中之情”，读来或难以分清景语与情语的界限，可见词中情景交融。\n上阕追忆别时情景，围绕一“情”字，直陈离恨。开篇两句抛出词眼“伤高怀远”，在问答开阖间将所写感情堆砌到无与伦比的高度。起首即发问，看似突兀，却沉淀了对过往种种情感经历的深沉体验。当郁结于胸的哀怨借问句...", "authors": ["丘　悦"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe9f2af4e09d55b66e5", "shortContent": "此词由题材观之，不过是寻常的闺怨词。唯其情挚感人，故成为惯写男欢女爱的张先笔下一抹夺目的殊色。由结构观之，沈祖棻概其“上片情中之景，下片景中之情”，读来或难以分清景语与情语的界限，可见词中情景交融。\n\n上阕追忆别时情景，围绕一“情”字，直陈离恨。开篇两句抛出词眼“伤高怀远”，在问答开阖间将所写感情堆砌到无与伦比的高度。起首即发问，看似突兀，却沉淀了对过往种种情感经历的深沉体验。当郁结于胸的哀怨借问...", "authors": ["丘悦"], "pressName": "崇文书局"}]', '', 'indent', 1418771988, '57b92cdf128fe10054caffb4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10702, '天仙子 · 时为嘉禾小倅，以病眠不赴府会', NULL, 535, 190, 3, 3, '张先', NULL, 10169, '57bac637c4c97100614fdfe7', '宋', 'ci', '词', 'http://baike.baidu.com/item/天仙子·时为嘉禾小倅以病眠不赴府会?sefr=enterbtn', '', '水调数声持酒听，午醉醒来愁未醒。送春春去几时回？临晚镜，伤流景，往事后期空记省。
沙上并禽池上暝，云破月来花弄影。重重帘幕密遮灯，风不定，人初静，明日落红应满径。', '这首词是张先的佳作，也是宋词名作。此词内容平泛，描写作者在嘉禾做小官时的平常生活。上阕写送春伤别、低徊往事的心绪。听歌饮酒欲解愁，愁不可解，而惜春伤别情绪愈益增重，末句点出原委。「空」字写出襟怀之寥落孤寂。下阕以周围环境和景物予以烘染。禽鸟成双，而作者却形单影只，孤寂萧索，则隐然暗示出对青春年华情侣燕尔的往事之追忆。花月弄影，由反面衬跌；垂帘挑灯，风紧人静，作正面渲染。收拍绾合惜春伤离，馀韵不尽。「云破月来花弄影」句，下字精美，意境高妙，一向传诵人口。《后山诗话》云：「尚书郎张先善著词，有云：『云破月来花弄影』，『帘幕卷花影』，『堕轻絮无影』，世称诵之，号张三影。」', '天仙子：唐教坊舞曲名，后用为词牌名。唐词单调，宋代张先重叠一阕为之，遂为双调。
嘉禾：秀州别称，治所在今浙江省嘉兴市。
倅（cuì）：副职，时张先任秀州通判。
不赴府会：未去官府上班。
水调：曲调名。唐·杜牧《扬州》诗之一：「谁家唱《水调》，明月满扬州。」自注：「炀帝凿汴渠成，自造《水调》。」
临晚镜：就镜自照而感伤衰老。
流景：如流水般消逝的光景。景，通「影」，日光。唐·武平一《妾薄命》诗：「流景一何速，年华不可追。」
往事后期：以往的欢情，以后的期约。后期，瞻望未来。
空记省（xǐng）：白白留在记忆中。记，记忆、思念；省，醒悟、明白。
并禽：成对的鸟儿。这里指鸳鸯。
暝（míng）：日色昏暗。
弄影：谓物动使影子也随着摇晃或移动。弄，摆弄。
「云破月来花弄影」句：据说张先得句于此，并自建花月亭。
重（chóng）重：犹层层。
帘幕：用于门窗处的帘子与帷幕。
落红：缤纷的落花。', '饮着美酒听着《水调曲》，午间喝醉后已经醒来，可心中的愁苦却不曾排遣。送走了春天，春天什么时候能再回来？晚上对镜自照，惋惜青春年少、似水流年，往日相约，白白记得很清楚，后来却如同云烟。
沙滩上双宿的鸳鸯鸟已栖息，风吹走了流云，月光下花儿孤影自怜。一层层的帘幕密密地遮住了灯光，人声渐渐地安静下来了，风却依旧在吹个不停。明天清晨，一定有许多花瓣被风吹落，铺满院间的小径。', '[{"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a97d0ac1145495e85f", "shortContent": "这是北宋词中名篇之一，也是张先享誉之作。而其所以得名，则由于词中有“云破月来花弄影”之句。据陈师道《后山诗话》及胡仔《苕溪渔隐丛话》所引各家评论，都说到张先所创作的词中以三句带有“影”字的佳句为世所称，人们誉之为“张三影”。\n这首词调下有注云：“时为嘉禾小倅，以病眠，不赴府会。”说明词人感到疲怠，百无聊赖，对酣歌妙舞的府会不感兴趣，这首词写的正是这种心情。\n其实作者未尝不想借听歌饮酒来解愁。但在这...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252251899613caec098", "shortContent": "这是北宋词中名篇之一，也是张先享誉之作。而其所以得名，则由于词中有“云破月来花弄影”之句。据陈师道《后山诗话》及胡仔《苕溪渔隐丛话》所引各家评论，都说到张先所创作的词中以三句带有“影”字的佳句为世所称，人们誉之为“张三影”。\n\n这首词调下有注云：“时为嘉禾小倅，以病眠，不赴府会。”说明词人感到疲怠，百无聊赖，对酣歌妙舞的府会不感兴趣，这首词写的正是这种心情。\n\n其实作者未尝不想借听歌饮酒来解愁。但...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3a7ccdb86c49f2909d", "shortContent": "由小序可知，此词应作于张先任嘉禾（今浙江嘉兴）判官期间，据考约为宋仁宗庆历元年（1041），词人时年五十二岁。沈祖棻认为词中所写情事与小序内容很不相干，推测是时人偶记词作于何时何地，误作词序流传至今。\n此词蜚声北宋词坛，张先被人誉为“张三影”，正源于他自举平生所得意之三词：“云破月来花弄影”（《天仙子》），“娇柔懒起，帘幕卷花影”（《归朝欢》），“柳径无人，堕絮飞无影”（《剪牡丹》）。陈师道《后山...", "authors": ["丘　悦"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe9f2af4e09d55b66e6", "shortContent": "由小序可知，此词应作于张先任嘉禾（今浙江嘉兴）判官期间，据考约为宋仁宗庆历元年（1041），词人时年五十二岁。沈祖棻认为词中所写情事与小序内容很不相干，推测是时人偶记词作于何时何地，误作词序流传至今。\n\n此词蜚声北宋词坛，张先被人誉为“张三影”，正源于他自举平生所得意之三词：“云破月来花弄影”（《天仙子》），“娇柔懒起，帘幕卷花影”（《归朝欢》），“柳径无人，堕絮飞无影”（《剪牡丹》）。陈师道《后...", "authors": ["丘悦"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312717d73206168b2e0232b", "shortContent": "由小序可知，此词应作于张先任嘉禾（今浙江嘉兴）判官期间，据考约在宋仁宗庆历元年（1041），词人时年五十二岁。沈祖棻认为词中所写情事与小序内容很不相干，推测是时人偶记词作于何时何地，误作词序流传至今。\n此词蜚声北宋词坛，张先被人誉为“张三影”，正来源于他自举平生所得意之三词：“云破月来花弄影”（《天仙子》）；“柳径无人，堕絮飞花影”（《归朝欢》）；“柔柳摇摇，坠轻絮无影”（《剪牡丹》）。陈师道《后...", "authors": ["丘悦"], "pressName": "崇文书局"}]', '宋·陈师道《后山诗话》：尚书郎张先善著词，有云：「云破月来花弄影」、「帘压卷花影」、「堕飞絮无影」，世称诵之，谓之「张三影」。
宋·胡仔《苕溪渔隐丛话》前集卷三十七引《古今诗话》：有客谓子野曰：「人皆谓公张三中，即心中事、眼中泪、意中人也。」子野曰：「何不目之为张三影？」客不晓。公曰：「『云破月来花弄影。』『娇柔懒起，帘压卷花影。』『柳径无人，堕风絮无影。』此余生平所得意也。」
宋·陈正敏《遯斋闲览》：张子野郎中，以乐章擅名一时。宋子京尚书奇其才，先往见之，遣将命者谓曰：「尚书欲见『云破月来花弄影』郎中。」子野屏后呼曰：「得非『红杏枝头春意闹』尚书耶？」遂出，置酒，甚欢。盖二人所举，皆其警策也。
明·杨慎《词品》：「云破月来花弄影」，景物如画，画亦不能至此，绝倒绝倒！
明·沈际飞《草堂诗馀正集》：「云破月来」句，心与景会，落笔即是，着意即非，故当脍炙。
清·黄苏《蓼园词选》：听《水调》而愁，自伤卑贱也。「送春」四句，伤流光易去，后期茫茫也。「沙上」二句，言所居岑寂，以沙禽与花自喻也。「重重」三句，言多障蔽也。结句仍缴送春本题，恐其时之晚也。
近·王国维《人间词话·卷上》：「红杏枝头春意闹」，著一「闹」字而境界全出。「云破月来花弄影」，著一「弄」字而境界全出矣。
现·唐圭璋《唐宋词简释》：此首不作发语之语，而自然韵高。中间自午至晚，自晚至夜，写来情景宛然。
现·沈祖棻《宋词赏析》：这首词乃是临老伤春之作，与词中习见的少男少女的伤春不同。……叹老嗟卑，是封建社会不得志的文人的常见的情绪，其中也包含有一些优秀人物在那种黑暗时代被迫无所作为的愤惋，对于今天的读者来说，是有其认识作用的。', 'indent', 1418772140, '57b8f470a633bd00665cfc6e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10703, '青门引', NULL, 436, 190, 2, 3, '张先', NULL, 10169, '57bac637c4c97100614fdfe7', '宋', 'ci', '词', 'http://baike.baidu.com/view/2801440.htm', '', '乍暖还轻冷，风雨晚来方定。庭轩寂寞近清明，残花中酒，又是去年病。
楼头画角风吹醒，入夜重门静。那堪更被明月，隔墙送过秋千影。', '这是感春怀人的小词。词中写出从风雨初定的黄昏直到月明之夜，孤独的作者触景伤心的种种感受。此词用字非常新警，如“楼头画角风吹醒”句，“醒”字极尖利，给人触目惊心之感。末二句不实写打秋千的人，而借秋千影来显示他人对春残花落的无知无感和作者的多愁善感，以及他人欢乐而己独伤悲的难堪情状，意味隽永。', '青门引：词牌名。
中酒：喝醉。见《史记·樊哙传》，亦见《汉书》，酒酣也，意即醉了。《汉书》颜师古注：“饮酒之中也，不醉不醒故谓之中。中音竹仲反。“其说稍异。杜牧《睦州四韵》：”残春杜陵客，中酒落花前“，与此词意近。
病：字承上”中酒“来，言酒病。
画角：古代军队中绘有彩色图案的管乐器。
那：为”奈何“之合音，读平声，亦读上声。
秋千影：言秋千影，人影可知。盖值寒食佳节，明月中有人在打秋千。一说秋千架的影儿被明月送过墙来，是怀人寂寞境界，亦通。但此处以动态结静境，有人影似较好。薛能《寒食日题》：“夜半无灯还有睡，秋千悬在月明中。“这秋千也空着，却与”隔墙送影“不同。', '刚刚转暖还带着一丝寒意，凄风冷雨到傍晚方才消停。庭院寂寞且时节已近清明，因痛惜残花借酒浇愁直到醉，这又是去年时种下的旧病。
楼头画角声和风把我惊醒，夜已深重门闭锁万籁寂静。更那堪忍受那溶溶的月光，隔墙有少女荡秋千的清影。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74a203048e64fbd892ed", "shortContent": "南宋吴文英作词，论者谓其善于表现锐敏尖新的感觉。其实早在北宋，张先已在这一艺术造诣上导其先路。这首小词可以为证。\n起笔二句，写自己对春天气候的感触。短短一天里，天气发生了频繁的变化。“乍暖”，见得是由春寒忽然变暖。“还”字一转，引出又一次变化：风雨忽来，轻冷袭人。虽说春天之冷，较冬日为“轻”，但这“冷”是紧接“暖”而来，所以格外容易感觉。轻寒的风雨，一直到晚才止住了。词人感触之敏锐，不但体现在对天...", "authors": ["宛敏灏", "邓小军"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a92cee9a0c24ed9e2a", "shortContent": "南宋吴文英作词，论者谓其善于表现锐敏尖新的感觉。其实早在北宋，张先已在这一艺术造诣上导其先路。这首小词可以为证。\n起笔二句，写自己对春天气候的感触。短短一天里，天气发生了频繁的变化。“乍暖”，见得是由春寒忽然变暖。“还”字一转，引出又一次变化：风雨忽来，轻冷袭人。虽说春天之冷，较冬日为“轻”，但这“冷”是紧接“暖”而来，所以格外容易感觉。轻寒的风雨，一直到晚才止住了。词人感触之敏锐，不但体现在对天...", "authors": ["宛敏灏", "邓小军"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252251899613caec09b", "shortContent": "南宋吴文英作词，论者谓其善于表现锐敏尖新的感觉。其实早在北宋，张先已在这一艺术造诣上导其先路。这首小词可以为证。\n\n起笔二句，写自己对春天气候的感触。短短一天里，天气发生了频繁的变化。“乍暖”，见得是由春寒忽然变暖。“还”字一转，引出又一次变化：风雨忽来，轻冷袭人。虽说春天之冷，较冬日为“轻”，但这“冷”是紧接“暖”而来，所以格外容易感觉。轻寒的风雨，一直到晚才止住了。词人感触之敏锐，不但体现在对...", "authors": ["宛敏灏", "邓小军"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3a7ccdb86c49f2909e", "shortContent": "《青门引》，词牌名。调见《乐府雅词》及《天机余锦》词。属小令，双调五十二字，上片五句，下片四句。\n本篇以春日怀人为词旨，上片写词人由暮春季节物象变迁衍生的宏观感受，怀旧与孤寂的情思满溢字里行间；下片写词人凭酒浇愁未成，清醒时分越发触景生情，每每于细微处生发无限思量。\n由“乍暖还轻冷，风雨晚来方定”可见出词人体物的敏感和用字的精妙。两个虚字“乍”和“还”放在对比鲜明的“暖”和“冷”之间，表现了天气变...", "authors": ["丘　悦"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe9f2af4e09d55b66e7", "shortContent": "《青门引》，词牌名。调见《乐府雅词》及《天机余锦》词。属小令，双调五十二字，上片五句，下片四句。\n\n本篇以春日怀人为词旨，上片写词人由暮春季节物象变迁衍生的宏观感受，怀旧与孤寂的情思满溢字里行间；下片写词人凭酒浇愁未成，清醒时分越发触景生情，每每于细微处生发无限思量。\n\n由“乍暖还轻冷，风雨晚来方定”可见出词人体物的敏感和用字的精妙。两个虚字“乍”和“还”放在对比鲜明的“暖”和“冷”之间，表现了天...", "authors": ["丘悦"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312717d73206168b2e0232c", "shortContent": "《青门引》，词牌名。调见《乐府雅词》及《天机余锦》词。属小令，双调五十二字，上片五句，下片四句。\n本篇以春日怀人为词旨，上片写词人由暮春季节物象变迁衍生的宏观感受，怀旧与孤寂的情思满溢字里行间；下片写词人凭酒浇愁未成，清醒时分越发触景生情，每每于细微处生发无限思量。\n由“乍暖还轻冷，风雨晚来方定”可见出词人体物的敏感和用字的精妙。两个虚字“乍”和“还”放在对比鲜明的“暖”和“冷”之间，表现了天气变...", "authors": ["丘悦"], "pressName": "崇文书局"}]', NULL, 'indent', 1418772218, '57b14f782e958a00545f7df1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (85735, '道一大尹存之庭美二学士简于圣明自致霄汉皆与舍弟昔年还往牧支离穷悴窃于一麾书美歌诗兼自言志因成长句四韵', NULL, 1, 501, 0, 1, '杜牧', NULL, 10109, '57b9836cc4c971005593dfec', '唐', 'shi', '诗', NULL, NULL, '九金神鼎重丘山，五玉诸侯杂佩环。
星座通霄狼鬣暗，戍楼吹笛虎牙闲。
斗间紫气龙埋狱，天上洪炉帝铸颜。
若念西河旧交友，鱼符应许出函关。', NULL, NULL, NULL, NULL, NULL, 'center', 1554893908, '585d10da8d6d810065dce6c0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10705, '木兰花•和孙公素别安陆', NULL, 317, 190, 1, 1, '张先', NULL, 10169, '57bac637c4c97100614fdfe7', '宋', 'ci', '词', 'http://baike.baidu.com/view/9062547.htm', '', '相离徒有相逢梦，门外马蹄尘已动。怨歌留待醉时听，远目不堪空际送。
今宵风月知谁共？声咽琵琶槽上凤。人生无物比多情，江水不深山不重。', '原题作“和孙公素别安陆”。此词言送别，没用一般写景伤怀或凄楚哀怨的苦调，而是以谙尽别离况味的超然态度，从虚处着笔，靠对惯常送别程式之否定，以突出自己体验到的离愁。
首句写离别，却用别后盼相逢已是徒劳魂梦，将再“相逢”的意愿及难再逢的事实点明，以少胜多，思力惊力。李白《送孟浩然之广陵》有“孤帆远影碧空尽，惟见长江天际流”，表示目送去帆，久久伫立，直至看不到，还不忍离去的痴情。但词人却用翻案技法，否定这种送别方式，认为“远目不堪空际送”，写出不忍心望行人远去的心情，更其幽咽。
“今宵”句与柳永“今宵酒醒何处？杨柳岸，晓风残月”有异曲同工之妙。“人生无物比多情”认为“多情”是最可珍贵的，无物可比，与沈邈“情多是病”（《剔银灯》）语意相悖，意旨却同。“江水不深山不重”，一反前人咏愁言情以水、山类比的俗套，亦属避俗就生之法。全词一处用“无”，三处用“不”，此种谋篇布局，可称为“否定式”结构。', '槽上凤：琵琶上端雕刻成凤头状。槽：即将弦柱之槽口，在凤头下方。', '', NULL, '', 'indent', 1418810283, '57b8f3c35bbb50005b77ceec', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10706, '破阵子', NULL, 632, 351, 2, 8, '晏殊', NULL, 10170, '57ba3dadefa631005a794b55', '宋', 'ci', '词', 'http://baike.baidu.com/view/2785291.htm', '', '燕子来时新社，梨花落后清明。池上碧苔三四点，叶底黄鹂一两声。日长飞絮轻。
巧笑东邻女伴，采桑径里逢迎。疑怪昨宵春梦好，元是今朝斗草赢。笑从双脸生。', '在《珠玉词》中，这是一首清新活泼的作品，具有淳朴的乡间泥土芬芳。上阕写自然景物。「燕子」、「梨花」、「碧苔」、「黄鹂」、「飞絮」，五色杂陈，秀美明丽，写足春色之娇娆媚人。下阕写人物。撷取烂熳春色中一位年轻村姑之天真形象和幼稚心态进行表现。「巧笑」已闻其声，见其容；「逢迎」更察其色，观其形。「疑怪」两句通过观察者心理活动，用虚笔再现「女伴」「昨宵春梦」和「今朝斗草」的生活细节，惟妙惟肖，将村姑的天真可爱一笔写足，与上阕生气盎然的春光形成十分和谐的画面美与情韵美。「笑从双脸生」，特写，绾合换头「巧笑」语意，收束全篇春光无限之旨。全词浑成优美，音节浏亮，意境清秀，场面轻快，洋溢着诱人的青春魅力。尤其上下阕的构思，景与人对应着写，将春天的生命写活了。其中巧笑的东邻女伴，仿佛春天的女神，给人间带来生气、美丽与活力。', '破阵子：《破阵子》，唐教坊曲，一名《十拍子》。陈旸《乐书》：「唐《破阵乐》属龟兹部，秦王（唐太宗李世民）所制，舞用二千人，皆画衣甲，执旗旆。外藩镇春衣犒军设乐，亦舞此曲，兼马军引入场，尤壮观也。」按《秦王破阵乐》为唐开国时之大型武舞曲，震惊一世。玄奘往印度取经时，一国王曾询及之，见所著《大唐西域记》。此双调小令，当是截取舞曲中之一段为之，犹可想见激壮声容。双调六十二字，上下阕各五句三平韵。唐太宗李世民任秦王时制大型舞曲，名《破阵乐》。本是七言绝句，后因旧曲名，另倚新声。始见晏殊词。
新社：社日是古代祭土地神的日子，以祈丰收，有春秋两社。新社即春社，时间在立春后、清明前。
碧苔：碧绿色的苔草。
飞絮：飘荡着的柳絮。
巧笑：形容少女美好的笑容。
逢迎：相逢。
疑怪：诧异、奇怪。这里是「怪不得」的意思。
斗草：古代妇女的一种游戏，也叫「斗百草」。其玩法大抵如下：比赛双方先各自采摘具有一定韧性的草，（楼兰案：多为车前草，车前草多年生草本植物，多生路边、沟壑旁、田埂等处。无茎，具多数细长之须根；叶自根际丛出，薄纸质，具五条主叶脉，全缘或波状，或有疏钝齿，长达十五至三十厘米；具绿白色疏生花，花冠四裂，雄蕊四枚；果实成熟后会如盖子般掀开，释出四至六颗棕黑色种子，其长长的花轴，用来斗草的好材料。）然后相互交叉成「十」字状并各自用劲拉扯，以不断者为胜。所谓「武斗」。王建《宫词》，吟咏斗草游戏的情状：「水中芹叶土中花，拾得还将避众家，总待别人般数尽，袖中拈出郁金芽」斗草除有「武斗」外，还有「文斗」。所谓「文斗」，就是对花草名，女孩们采来百草，以对仗的形式互报草名，谁采的草种多，对仗的水平高，坚持到最后，谁便赢。因此玩这种游戏没点植物知识和文学修养是不行的。
双脸：指脸颊。', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74a45914587d02f465da", "shortContent": "二十四节气，春分连接清明———这正是一年春光最堪留恋的时节。春已中分，新燕将至，此时恰值社日也将到来，古人称燕子为社燕，以为它常是春社来，秋社去。词人所说的新社，指的即是春社了。那时每年有春秋两个社日，而尤重春社，邻里大聚会，来行祀社（大地之神也）之礼，酒食分餐，赛会腾欢，极一时一地之盛。闺中少女，也“放”了“假”，正所谓“问知社日停针线”，连女红也是可以放下的，呼姊唤妹，许可门外游观。词篇开头一...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ab34a8757d5a0eca6e", "shortContent": "二十四节气，春分连接清明———这正是一年春光最堪留恋的时节。春已中分，新燕将至，此时恰值社日也将到来，古人称燕子为社燕，以为它常是春社来，秋社去。词人所说的新社，指的即是春社了。那时每年有春秋两个社日，而尤重春社，邻里大聚会，来行祀社（大地之神也）之礼，酒食分餐，赛会腾欢，极一时一地之盛。闺中少女，也“放”了“假”，正所谓“问知社日停针线”，连女红也是可以放下的，呼姊唤妹，许可门外游观。词篇开头一...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059253251899613caec0a6", "shortContent": "二十四节气，春分连接清明——这正是一年春光最堪留恋的时节。春已中分，新燕将至，此时恰值社日也将到来，古人称燕子为社燕，以为它常是春社来，秋社去。词人所说的新社，指的即是春社了。那时每年有春秋两个社日，而尤重春社，邻里大聚会，来行祀社（大地之神也）之礼，酒食分餐，赛会腾欢，极一时一地之盛。闺中少女，也“放”了“假”，正所谓“问知社日停针线”，连女红也是可以放下的，呼姊唤妹，许可门外游观。词篇开头一句...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "64679040b6a81d0c53001e81", "shortContent": "二十四节气，春分连接清明——这正是一年春光最堪留恋的时节。春已中分，新燕将至，此时恰值社日也将到来，古人称燕子为社燕，以为它常是春社来，秋社去。词人所说的新社，指的即是春社了。那时每年有春秋两个社日，而尤重春社，邻里大聚会，来行祀社（大地之神也）之礼，酒食分餐，赛会腾欢，极一时一地之盛。闺中少女，也“放”了“假”，正所谓“问知社日停针线”，连女红也是可以放下的，呼姊唤妹，许可门外游观。词篇开头一句...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}, {"bookId": "645fc22c5e6bb82b8caff682", "bookTitle": "历代咏春诗鉴赏：春江花月夜", "articleId": "6472fe44a5f1e74f958b3e1e", "shortContent": "二十四节气，春分连接清明——这正是一年春光最堪留恋的时节。春已中分，新燕将至，此时恰值社日也将到来，古人称燕子为社燕，以为它常是春社来，秋社去。词人所说的新社，指的即是春社了。那时每年有春秋两个社日，而尤重春社，邻里大聚会，来行祀社（大地之神也）之礼，酒食分餐，赛会欢腾，极一时一地之盛。闺中少女，也“放”了“假”，正所谓“问知社日停针线”，连女红也是可以放下的，呼姊唤妹，许可门外游观。词篇开头一句...", "authors": ["周汝昌"], "pressName": "上海辞书出版社"}]', '', 'indent', 1418810457, '57b8fda40a2b58005c92263a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10707, '浣溪沙 · 一曲新词酒一杯', NULL, 1467, 351, 2, 17, '晏殊', NULL, 10170, '57ba3dadefa631005a794b55', '宋', 'ci', '词', 'http://baike.baidu.com/view/1899523.htm', '', '一曲新词酒一杯，去年天气旧亭台。夕阳西下几时回？
无可奈何花落去，似曾相识燕归来。小园香径独徘徊。', '本词为晏殊的名篇之一，抒写悼惜春残花落，好景不长的愁怀，又暗寓相思离别之情。语意十分蕴藉含蓄，通篇无一字正面表现思情别绪，读者却能从“去年天气旧亭台”、“燕归来”、“独徘徊”等句，领会到作者对景物依旧、人事全非的暗示和深深的叹恨。词中“无可奈何花落去”一联工巧而流丽，风韵天然，向称名句。', '浣溪沙：唐玄宗时教坊曲名，后用为词调。沙，一作“纱”。
一曲新词酒一杯：此句化用白居易《长安道》诗意：“花枝缺入青楼开，艳歌一曲酒一杯”。一曲，一首。因为词是配合音乐唱的，故称“曲”。新词，刚填好的词，意指新歌。酒一杯，一杯酒。
去年天气旧亭台：是说天气、亭台都和去年一样。此句化用五代郑谷《和知己秋日伤怀》诗：“流水歌声共不回，去年天气旧池台。”晏词“亭台”一本作“池台”。去年天气，跟去年此日相同的天气。旧亭台，曾经到过的或熟悉的亭台楼阁。旧，旧时。', '填曲新词品尝一杯美酒，时令气候亭台池榭依旧，西下的夕阳几时才能回转？无可奈何中百花再残落，似曾相识的春燕又归来，独自在花香小径里徘徊。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74a203048e64fbd892f0", "shortContent": "这是晏殊一首脍炙人口的小令。它语言圆转流利，明白如话，意蕴却虚涵深广，能给人以一种哲理性的启迪。\n“一曲新词酒一杯，去年天气旧亭台。”起句写对酒听歌的现境。从复叠错综的句式、轻快流利的语调中可以体味出，词人在面对现境时，开始是怀着轻松喜悦的感情，带着潇洒安闲的意态的。但边听边饮，这现境却又不期然而然地触发对“去年”所历类似境界的追忆：也是和今年一样的暮春天气，面对的也是和眼前一样的楼台亭阁，一样的...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5aa5914587d02f58fc5", "shortContent": "这是晏殊一首脍炙人口的小令。它语言圆转流利，明白如话，意蕴却虚涵深广，能给人以一种哲理性的启迪。\n“一曲新词酒一杯，去年天气旧亭台。”起句写对酒听歌的现境。从复叠错综的句式、轻快流利的语调中可以体味出，词人在面对现境时，开始是怀着轻松喜悦的感情，带着潇洒安闲的意态的。但边听边饮，这现境却又不期然而然地触发了他对“去年”所历类似境界的追忆：也是和今年一样的暮春天气，面对的也是和眼前一样的楼台亭阁，一...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252251899613caec09c", "shortContent": "这是晏殊一首脍炙人口的小令。它语言圆转流利，明白如话，意蕴却虚涵深广，能给人以一种哲理性的启迪。\n\n“一曲新词酒一杯，去年天气旧亭台。”起句写对酒听歌的现境。从复叠错综的句式、轻快流利的语调中可以体味出，词人在面对现境时，开始是怀着轻松喜悦的感情，带着潇洒安闲的意态的。但边听边饮，这现境却又不期然而然地触发了他对“去年”所历类似境界的追忆：也是和今年一样的暮春天气，面对的也是和眼前一样的楼台亭阁，...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3a7ccdb86c49f290a1", "shortContent": "晏殊《浣溪沙》是一首春恨词，写一种日常化的淡淡的愁情，而又渗入了一种悠悠不尽的哲思。如上阕“去年天气旧亭台”说明时间和空间的重复回返，以显现出生活陷入同质化的单调乏味而只能借助作诗饮酒略作排遣的落寞和忧伤。夕阳西下，何时回返？“花落”而“燕来”，或可聊慰枯燥人生。而其中“无可奈何花落去，似曾相识燕归来”遂因着这种慨叹而成千古名句，并向为世人称道。清初诗论家王士稹（渔洋山人）即有从这两句入手作过“诗...", "authors": ["何光顺"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe9f2af4e09d55b66ea", "shortContent": "晏殊《浣溪沙》是一首春恨词，写一种日常化的淡淡的愁情，而又渗入了一种悠悠不尽的哲思。如上阕“去年天气旧亭台”说明时间和空间的重复回返，以显现出生活陷入同质化的单调乏味而只能借助作诗饮酒略作排遣的落寞和忧伤。夕阳西下，何时回返？“花落”而“燕来”，或可聊慰枯燥人生。而其中“无可奈何花落去，似曾相识燕归来”遂因着这种慨叹而成千古名句，并向为世人称道。清初诗论家王士稹（渔洋山人）即有从这两句入手作过“诗...", "authors": ["何光顺"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312717d73206168b2e0232e", "shortContent": "晏殊《浣溪沙》是一首春恨词，写一种日常化的淡淡的愁情，而又渗入了一种悠悠不尽的哲意之思。如上阕“去年天气旧亭台”说明时间和空间的重复回返，以显现出生活陷入同质化的单调乏味，而只能借助作诗饮酒略作排遣的落寞和忧伤。夕阳西下，何时回返？“花落”而“燕来”，或可聊慰枯燥人生。而其中“无可奈何花落去，似曾相识燕归来”遂因着这种慨叹而成千古名句，并向为世人称道。清初诗论家王士镇（渔洋山人）即有从这两句人手作...", "authors": ["何光顺"], "pressName": "崇文书局"}, {"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "64678e3230675327e195ad89", "shortContent": "这是晏殊一首脍炙人口的小令。它语言圆转流利，明白如话，意蕴却虚涵深广，能给人以一种哲理性的启迪。\n\n“一曲新词酒一杯，去年天气旧亭台。”起句写对酒听歌的现境。从复叠错综的句式、轻快流利的语调中可以体味出，词人在面对现境时，开始是怀着轻松喜悦的感情，带着潇洒安闲的意态的。但边听边饮，这现境却又不期然而然地触发了他对“去年”所历类似境界的追忆：也是和今年一样的暮春天气，面对的也是和眼前一样的楼台亭阁，...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文（小学、初中）", "articleId": "6471fb5882772d45942809ec", "shortContent": "“无可奈何花落去，似曾相识燕归来。”这首词的出名，和这一联工巧而浑成、流利而含蓄的对句很有关系，在用虚字构成工整的对仗、唱叹传神方面表现出词人的巧思深情。但更值得玩索的倒是这一联所含的意蕴。花的凋落，春的消逝，时光的流逝，都是不可抗拒的自然规律，虽然惋惜流连也无济于事，所以说：“无可奈何”，这一句承上“夕阳西下”；然而在这暮春天气中，所感受到的并不只是无可奈何的凋衰消逝，而是还有令人欣慰的重现，那...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '杨慎《词品》：“无可奈何”二语工丽，天然奇偶。
沈际飞《草堂诗余正集》：“无可奈何花落去”，律诗俊语也，然自是天成一段词，着诗不得。
张宗橚《词林纪事》：细玩“无可奈何”一联，意致缠绵，语调谐婉，的是倚声家语，若作七律，未免软弱矣。', 'indent', 1418810574, '57b8e635128fe10054c8f39c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10708, '蝶恋花/鹊踏枝', NULL, 1091, 1229, 3, 2, '欧阳修', NULL, 10018, '57b98d625bbb50005347ace1', '宋', 'ci', '词', 'http://baike.baidu.com/view/879645.htm', '', '庭院深深深几许？杨柳堆烟，帘幕无重数。玉勒雕鞍游冶处，楼高不见章台路。
雨横风狂三月暮，门掩黄昏，无计留春住。泪眼问花花不语，乱红飞过秋千去。', '这是深闺佳人的伤春词。作者以含蕴的笔法描写了幽居深院的少妇伤春及怀人的复杂思绪和怨情。不写佳人先写佳人居处。三迭「深」字，则佳人禁锢高门，内外隔绝、闺房寂落之况，可以想见。树多雾浓、帘幕严密，愈见其深。「章台路」当指伊人「游冶处」，望而不见正由宅深楼高而来。可知物质环境之华贵，终难弥补感情世界之凄清。望所欢而不见，感青春之难留，佳人眼中之景，不免变得暗淡萧索。感花摇落而有泪，含泪而问花，花乱落而不语。伤花实则自伤，佳人与落花同一命运。是花是人？物我合一，情景交融，含蕴最为深沉。整首词如泣如诉，凄婉动人，意境浑融，语言清丽，尤其是最后两句，向为词评家所赞誉。', '几许：多少。许，估计数量之词。
堆烟：形容杨柳浓密。
玉勒雕鞍：极言车马的豪华。玉勒，玉制的马衔。雕鞍，精雕的马鞍。
游冶处：指歌楼妓院。
章台：汉长安街名。《汉书·张敞传》有「走马章台街」语。唐许尧佐《章台柳传》，记妓女柳氏事。后因以章台为歌妓聚居之地。
雨横：指急雨、骤雨。
乱红：这里形容各种花片纷纷飘落的样子。', '深深的庭院不知有多深？一排排杨柳堆起绿色的云，一重重帘幕多得难以计数。华车骏马如今在哪里游冶，我登上高楼也不见章台路。
风狂雨骤的暮春三月，时近黄昏掩起门户，却没有办法把春光留住。我泪眼汪汪问花，花默默不语，只见散乱的落花飞过秋千去。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74a87d0ac1145494bb4f", "shortContent": "这首词亦见于冯延巳的《阳春集》。清人刘熙载说：“冯延巳词，晏同叔得其俊，欧阳永叔得其深。”（《艺概·词曲概》）在词的发展史上，宋初词风径承南唐，没有太大的变化，而欧与冯俱仕至宰执，政治地位与文化素养基本相似。因此他们两人的词风大同小异，有些作品，往往混淆在一起。此词据李清照《临江仙》词序云：“欧阳公作《蝶恋花》，有‘深深深几许’之句，予酷爱之，用其语作‘庭院深深’数阕。”李清照去欧阳修未远，所云当...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5af5914587d02f58fd7", "shortContent": "这首词亦见于冯延巳的《阳春集》。清人刘熙载说：“冯延巳词，晏同叔得其俊，欧阳永叔得其深。”（《艺概·词曲概》）在词的发展史上，宋初词风径承南唐，没有太大的变化，而欧与冯俱仕至宰执，政治地位与文化素养基本相似。因此他们两人的词风大同小异，有些作品，往往混淆在一起。此词据李清照《临江仙》词序云：“欧阳公作《蝶恋花》，有‘深深深几许’之句，予酷爱之，用其语作‘庭院深深’数阕。”李清照去欧阳修未远，所云当...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592534b56e213e684802a", "shortContent": "这首词亦见于冯延巳的《阳春集》。清人刘熙载说：“冯延巳词，晏同叔得其俊，欧阳永叔得其深。”（《艺概·词曲概》）在词的发展史上，宋初词风径承南唐，没有太大的变化，而欧与冯俱仕至宰执，政治地位与文化素养基本相似。因此他们两人的词风大同小异，有些作品，往往混淆在一起。此词据李清照《临江仙》词序云：“欧阳公作《蝶恋花》，有‘深深深几许’之句，予酷爱之，用其语作‘庭院深深’数阕。”李清照去欧阳修未远，所云当...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3c7f0b9738b369b0f3", "shortContent": "此词为明道元年（1032）春，欧公与友人梅尧臣洛阳城东旧地重游有感而作。此词拟深闺佳人之口吻，抒其寂寞伤春之情。\n\n上阕首句即用三迭“深”字，前两个深状佳人居处之幽深，后面的“深几许”则于提问中暗含怨艾；“杨柳堆烟，帘幕无重数”状院中之孤寂冷清，“堆”本为动词，“堆烟”是指杨柳色青，静静地立在庭院旁，仿佛笼罩着一层青雾，以动摹静，更显院落寂寥孤清。然而就在这重重朱门、层层珠帘之中，一位深闺佳人独倚...", "authors": ["马瑶"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702d77683d1933015339", "shortContent": "此词为明道元年（1032）春，欧公与友人梅尧臣洛阳城东旧地重游有感而作。此词拟深闺佳人之口吻，抒其寂寞伤春之情。\n\n上阕首句即用三迭“深”字，前两个深状佳人居处之幽深，后面的“深几许”则于提问中暗含怨艾；“杨柳堆烟，帘幕无重数”状院中之孤寂冷清，“堆”本为动词，“堆烟”是指杨柳色青，静静地立在庭院旁，仿佛笼罩着一层青雾，以动摹静，更显院落寂寥孤清。然而就在这重重朱门、层层珠帘之中，一位深闺佳人独倚...", "authors": ["马瑶"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702d77683d193301533a", "shortContent": "本词归在欧阳修名下是有争议的。在《宋词三百首》里是欧阳修为作者，而唐圭璋先生在《宋词互见考》里则考证两家词集完成时间，以及后世序跋所言，推论其作者应为冯延巳。也有学者从作家风格意境判断，以为冯偏刚，欧偏柔，而此词风格柔婉，应为欧阳修所作较为合理。支持唐圭璋先生的学者认为仔细观察冯延巳其他词作，会发现他在抒发时间、青春流逝的无奈情感上，较为接近《蝶恋花》的意境格调。对于这样的争议应作如是观：这是个历...", "authors": ["黄晓鋆"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702d77683d193301533b", "shortContent": "蝶恋花》是一首由伤春而引发的抒情之作，所抒的是难以实指的浓重的感伤之情。词的上阕直抒胸臆，表达每到春天，“惆怅还依旧”的愁闷心情。下阕则用丽景抒发哀愁，对这种愁闷心理进行追述。\n\n“谁道闲情抛弃久？每到春来，惆怅还依旧。”词人开篇即发问：谁说愁闷的心情已被抛弃良久？接着自问自答，每当春天到来，惆怅的心情还一如从前，挥之不去。\n\n“日日花前常病酒，不辞镜里朱颜瘦”，词人日日在花下醉酒，还是改变不了逐...", "authors": ["吕青霞"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312718cc26cbf3417f0957f", "shortContent": "此词为明道元年（1032）春，欧公与友人梅尧臣洛阳城东旧地重游有感而作。此词拟深闺佳人之口吻，抒其寂寞伤春之情。\n上阕首句即用三迭“深”字，前两个深状佳人居处之幽深，后面的“深几许”则于提问中暗含怨艾；“杨柳堆烟，帘幕无重数”状院中之孤寂冷清，“堆”本为动词，“堆烟”是指杨柳色青，静静地立在庭院旁，仿佛笼罩着一层青雾，以动摹静，更显院落寂寥孤清。然而就在这重重朱门，层层珠帘之中，一位深闺佳人独倚高...", "authors": ["马瑶"], "pressName": "崇文书局"}, {"bookId": "646a05a345e4710056dab21f", "bookTitle": "欧阳修诗文鉴赏辞典（珍藏本）", "articleId": "646c8ac07da2f75ac708ea5c", "shortContent": "这首词亦见于冯延巳的《阳春集》。清人刘熙载说：“冯延巳词，晏同叔得其俊，欧阳永叔得其深。”（《艺概·词曲概》）在词的发展史上，宋初词风径承南唐，没有太大的变化，而欧与冯俱仕至宰执，政治地位与文化素养基本相似。因此他们两人的词风大同小异，有些作品，往往混淆在一起。此词据李清照《临江仙》词序云：“欧阳公作《蝶恋花》，有‘深深深几许’之句，予酷爱之，用其语作‘庭院深深’数阕。”李清照去欧阳修未远，所云当...", "authors": ["徐培均"], "pressName": "崇文书局"}]', '明代茅暎：凄如送别。
清代黄苏《蓼园词选》：首阕因杨柳烟多，若帘幕之重重者，庭院之深以此，即下旬章台不见，亦以此。总以见柳絮之迷人，加之雨横风狂，即拟闭门，而春已去矣。不见乱红之尽飞乎？语意如此，通首诋斥，看来必有所指。第词旨浓丽，即不明所指，自是一首好词。
毛先舒：人愈伤心，花愈恼人，语愈浅而意愈人，又绝无刻画费力之迹，谓非层深而浑成耶？然作者初非措意，直如化工生物，笋未出而苞节已具，非寸寸为之也。
俞陛云《唐五代两宋词选释》：此词帘深楼迥、及「乱红飞过」等句，殆有寄托，不仅送春也。
唐圭璋《唐宋词简释》：此首写闺情，层深而浑成。首三句，但写一华丽之庭院，而人之矜贵可知。「玉勒」两句，写行人游冶不归，一则深院凝愁，一则章台驰骋，两句射照，哀乐毕见。换头，因风雨交加，更起伤春怀人之情。「泪眼」两句，……观毛氏此言，可悟其妙。', 'indent', 1418810646, '57b9002d8ac2470062df9172', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10709, '鹊踏枝 · 谁道闲情抛掷久', NULL, 485, 105, 2, 2, '冯延巳', NULL, 10045, '57b90551128fe10054c9ae3e', '五代十国', 'ci', '词', 'http://baike.baidu.com/view/2924324.htm', '', '谁道闲情抛掷久？每到春来，惆怅还依旧。日日花前常病酒，不辞镜里朱颜瘦。
河畔青芜堤上柳，为问新愁，何事年年有？独立小桥风满袖，平林新月人归后。', '本词抒写了一片难以指实的、浓重的感伤之情，大有「春花秋月何时了，往事知多少」的那种对于整个人生的迷惘和得不到解脱的苦闷，词中也同时包含着主人公对美好事物的无限眷恋，以及他甘心为此憔悴的执着感情。「独立小桥风满袖，平林新月人归后」两句，表现了主人公如有所待、又若有所失的情状，语淡而意远。', '「谁道闲情抛掷久」句：《阳春集笺》引近人梁启超云：「稼轩《摸鱼儿》起处从此脱胎。文前有文，如黄河液流，莫穷其源。」。闲情，闲愁、春愁。
病酒：饮酒沉醉。《晏子春秋·谏上三》：「景公饮酒，酲，三日而后发。晏子见曰：『君病酒乎？』公曰：『然。』」
不辞：不避、不怕。一作“敢辞”
朱颜：青春红润的面色。
青芜：青草。
小桥：一作“小楼”。
平林：平原上的树林。唐·李白《菩萨蛮》：「平林漠漠烟如织。」
新月：阴历每月初出的弯形月亮。', '谁说闲情被忘记了太久？每到新春来到，我的惆怅心绪一如故旧。为了消除这种闲愁，我天天在花前痛饮，让自己放任大醉，不惜身体消瘦，对着镜子自己容颜已改。
河边上芳草萋萋，河岸上柳树成荫。见到如此美景，我忧伤地暗自思量，为何年年都会新添忧愁？我独立在小桥，清风吹拂着衣袖。只有远处那一排排树木在暗淡的月光下影影绰绰，与我相伴。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e748fdbb8b379ee08dda3", "shortContent": "冯延巳实在应该是五代词人中一位极为重要的作者，他的作品在五代北宋之间，对于词之发展曾经产生过非常值得重视的影响。然而历代评词和选词的人，对于他的成就都似乎未曾予以应有的重视。那就因为他的词从表面看来，似乎也并未曾脱除五代一般小令的风格，其所叙写者，也不过仅是一些闺阁园亭之景，伤春怨别之情而已。然而若就其意境言之，则冯词却实在已形成了一种重要的开拓。盖词之初起原为歌筵酒席间之艳词，本无鲜明之个性及深...", "authors": ["叶嘉莹"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892cbb31680ae4c4b4d5", "shortContent": "冯延巳实在应该是五代词人中一位极为重要的作者，他的作品在五代北宋之间，对于词之发展曾经产生过非常值得重视的影响。然而历代评词和选词的人，对于他的成就都似乎未曾予以应有的重视。那就因为他的词从表面看来，似乎也并未曾脱除五代一般小令的风格，其所叙写者，也不过仅是一些闺阁园亭之景，伤春怨别之情而已。然而若就其意境言之，则冯词却实在已形成了一种重要的开拓。盖词之初起原为歌筵酒席间之艳词，本无鲜明之个性及深...", "authors": ["叶嘉莹"], "pressName": "上海辞书出版社"}]', '王静安《人间词话》：温、韦之精艳，所以不如正中者，意境有深浅也。
陈亦峰《云韶集·卷一》：“独立”二语，仙境？凡境？断非凡笔。
唐季特《唐宋词简释》：末两句，只写一美境，而愁自寓焉。
陈亦峰《白雨斋词话·卷六》：可谓沉著痛快之极，然却是从沉郁顿挫来。', 'indent', 1418810748, '57b91a39d342d3005ac7feca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (267273, '旅夜书怀', NULL, 0, 2504, 0, 1, '邓云霄', NULL, 17260, '5858eba5b123db00658da74c', '明', 'shi', '诗', NULL, NULL, '马首东风弱柳垂，关山迢递杳难期。
谁知游子中宵饭，正是闺人掩泪时。
红豆不须携满袖，江南何处寄相思。
巡檐夜步空庭月，宿鸟双栖自一枝。', NULL, NULL, NULL, NULL, NULL, 'center', 1525464830, '585df501b123db0065ac15fd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10710, '鹊踏枝 · 几日行云何处去', NULL, 279, 105, 3, 3, '冯延巳', NULL, 10045, '57b90551128fe10054c9ae3e', '五代十国', 'ci', '词', 'http://baike.baidu.com/view/1848206.htm', '', '几日行云何处去？忘却归来，不道春将暮。百草千花寒食路，香车系在谁家树？
泪眼倚楼频独语。双燕来时，陌上相逢否？撩乱春愁如柳絮，依依梦里无寻处。', '《鹊踏枝·几日行云何处去》为五代南唐词人冯正中以女子口气所作的一首闺怨词。写一位痴情女子对冶遊不归的男子既怀怨望又难割捨的缠绵感情。
词的上阕写男子治遊不归。
「几日行云何处去？忘了归来，不道春将暮」，这三句是闺中少妇的幽怨之词，表达她对情郎的惦念。这里以「行云」喻在外四处遊荡的情郎，非常形象贴切。「忘了归来，不道春将暮。」这两句为女子的自问自答之词，充满无尽悲叹：美好的春光将要逝去了，而情郎仍不见归来。「春将暮。」字面上是指春光将尽，亦指女子美好的年华将逝。
「百草千花寒食路，香车繫在谁家树？」「寒食」是指寒食节，是为纪念春秋时期晋国的名臣义士介子推而设立的节日，后来逐渐增加了祭扫、踏青、遊乐等风俗，现已基本和清明节合而为一了。「香车」指用香木做的车，这里代指华美的车或轿，也有「香艳」之意在。这两句表面上是思量心上的人面对春天踏青路上的美景，此时不知又在哪里驻足留连了；其实还暗含着另一层意思，他面对着花花草草的诱惑，此时竟不知在哪个花街柳巷里流连忘返？反映了女子思之深念之切，不免多想而心生的醋意。
词的下阕写女子的痴情与怨愤。
「泪眼倚楼频独语，双燕来时，陌上相逢否？」她想到自己的丈夫在外纵行放荡，心中是多么的悲伤呀。「泪眼」写其忧伤；「倚楼」写她对丈夫的盼望。「双燕」两句是她的询问，她频频问那归来的双燕是否见到自己的夫君。燕子无情，怎听得懂她的语言，这一问极写女主人之痴。
「撩乱春愁如柳絮，悠悠梦里无寻处。」问燕燕无语，这令她多么惆怅，多么悲痛，心中那春愁顿时如柳絮一般，凌乱无序。这里词人以柳絮喻词愁，将无形之愁具体化，极写其纷乱。「悠悠梦里无寻处。」既然他不归她又那般惦念他，那么便到梦里将他寻觅吧，但梦却那般悠长，令她茫然而不得寻觅。这最后两句写得千回百转，情意缠绵，形象地表达了女主人公的哀怨与痴情。
全词语言淸丽婉约，悱恻感人，生动地表达了她对爱人的思念和痴情，塑造了一个情怨交织内心的闺中思妇形象，也涵纳了更广泛的人生体验。', '行云：战国楚·宋玉《高唐赋序》记巫山神女云：「妾在巫山之阳，高丘之阻。旦为行云，暮为行雨，朝朝暮暮，阳台之下。」后世多借指行踪无定的美人，此指所思情郎。
不道：清末近现代初·张献之《诗词曲语辞汇释·卷四》：「不道，扰云不知也；不觉也；不期也。冯延已《蝶恋花》词：『几日行云何处去？忘了归来，不道春将暮。』言不觉春将暮也。」
百草千花：词意双关，即指寒食时节的实景，也暗喻花街柳巷的妓女。唐·白香山《赠长安妓女阿软》：「绿水红莲一朵开，千花百草无颜色。」
寒食：节令名，在清明前一日。
香车：指情郎的马车。
陌上：本指田间的小路，这里泛指应指马路。
撩乱春愁如柳絮：烦乱的春愁就如同满天纷飞的柳絮。', '我那如天上行云般来去的爱人呀，你飘遊到了哪里？你竟忘了归来，没想到春天即将过去。一年一度的寒食节又到了，遊人双双走在百草千花的踏青路，你把香车宝马系在谁家的树上了？剩我一人多么孤独。
噙着泪眼倚凭在高楼，对天上双飞的燕喃喃自语：燕子呀燕子，你来自何处？在飞来的路上，可曾遇见我的爱人否？春愁如到处乱飞的柳絮，撩得我心乱动；即使在幽幽梦中，也无法寻找到我的爱人在何处。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e748f34a8757d5a0d9d32", "shortContent": "这是一首闺情词，写一位痴情的女子对冶游不归的男子既怀怨望又难割舍的缠绵感情。一说此词为欧阳修作。\n一开头用问语提起。“行云”原出宋玉《高唐赋》：“旦为朝云，暮为行雨。”通常用于喻指女性，这里却借指男子———那位像行云一样在外寻欢觅爱的薄情人。几日不见他的踪迹，不知道又飘浮到什么地方去了。问语中有疑惑，更有叹息和怨嗟。“忘却归来，不道春将暮。”“不道”，这里含有不想一想的意思。春将暮，既指春天的消逝...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892dbb31680ae4c4b4db", "shortContent": "这是一首闺情词，写一位痴情的女子对冶游不归的男子既怀怨望又难割舍的缠绵感情。一说此词为欧阳修作。\n\n一开头用问语提起。“行云”原出宋玉《高唐赋》：“旦为朝云，暮为行雨。”通常用于喻指女性，这里却借指男子——那位像行云一样在外寻欢觅爱的薄情人。几日不见他的踪迹，不知道又飘浮到什么地方去了。问语中有疑惑，更有叹息和怨嗟。“忘却归来，不道春将暮。”“不道”，这里含有不想一想的意思。春将暮，既指春天的消逝...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3c7f0b9738b369b0f4", "shortContent": "本词归在欧阳修名下是有争议的。在《宋词三百首》里是欧阳修为作者，而唐圭璋先生在《宋词互见考》里则考证两家词集完成时间，以及后世序跋所言，推论其作者应为冯延巳。也有学者从作家风格意境判断，以为冯偏刚，欧偏柔，而此词风格柔婉，应为欧阳修所作较为合理。支持唐圭璋先生的学者认为仔细观察冯延巳其他词作，会发现他在抒发时间、青春流逝的无奈情感上，较为接近《蝶恋花》的意境格调。对于这样的争议应作如是观：这是个历...", "authors": ["黄晓鋈"], "pressName": "崇文书局"}]', '宋·史温《钓矶立谈》：学问渊博，文章颖发，辩说纵横。
清·刘融斋《艺概》：冯延巳词，晏同叔得其俊，欧阳永叔得其深。
清·谭复堂《复堂词话》：行云、百草、千花、香车、双燕，必有所託。
清·陈亦峰《云韶集》：正中词为五代之冠，高处入飞卿之室，却不相沿袭，时或过之。
清·陈亦峰《词则·大稚集·卷一》：「双燕」二语映首章。
清·周介存《介存斋论词杂著》：李后主词，如生马驹，不受控捉。毛嫱西施，天下美妇人也。严妆佳，淡妆亦佳，粗服乱头，不掩国色。飞卿，严妆；正中，淡妆也。
清·王静安《人间词话》：冯正中词虽不失五代风格而堂庑特大，开北宋一代风气。
清·王静安《人间词话》：「终日驰车走，不见所问津」，诗人之忧世也。「百草千花寒食路，香车繫在谁家树」，似之。”
民国·陈秋帆《阳春集笺》：宛转绸缪，与温飞卿《菩萨蛮》、《更漏子》同一情致。
近现代·唐季特《唐宋词简释》：末两句，揭出愁思无已之情，即梦里亦无寻处，缠绵悱侧，一往情深。
近现代·蔡厚示《唐宋词鉴赏》：这首词较明显地寄托了作者个人的感慨。他把自己比作被遗弃的女子，用以宣泄政治上的失意情绪。这比花间派词人专门描写妇女的服饰、容貌等一类作品，内容上毕竟深厚些。这种写法对北宋晏同叔和欧阳文忠诸人有着明显的影响。', 'indent', 1418810815, '57b98efea633bd00619f80e1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10711, '玉楼春 · 别后不知君远近', NULL, 368, 1229, 4, 3, '欧阳修', NULL, 10018, '57b98d625bbb50005347ace1', '宋', 'ci', '词', 'http://baike.baidu.com/item/玉楼春·别后不知君远近', '', '别后不知君远近，触目凄凉多少闷！渐行渐远渐无书，水阔鱼沉何处问？
夜深风竹敲秋韵，万叶千声皆是恨。故攲单枕梦中寻，梦又不成灯又烬。', '这是一首别后相思愁怨词。上片描写思妇别后的孤凄苦闷和对远人深切的怀念之情。上片以“别”字领起，下片以“恨”字相映，简括出此词主旨。上片侧重从思妇情思追踪行人的角度抒情，下片则变换视角，侧重从思妇自身处境的角度描写思妇秋夜难眠、独伴孤灯的愁苦。全词写愁恨由远到近，自外及内，从现实到幻想，又从幻想回归到现实。且抒情写景，情景两得，写景句寓含着婉曲之情，言情句挟带着凄凉之景，表现出特有的深曲婉丽的艺术风格。', '玉楼春：词牌名。《词谱》谓五代后蜀顾夐词起句有“月照玉楼春漏促”“柳映玉楼春欲晚”句；欧阳炯起句有“日照玉楼花似锦”“春早玉楼烟雨夜”句，因取以调名。亦称“木兰花”“春晓曲”“西湖曲”“惜春容”“归朝欢令”等。双调五十六字，前后阕格式相同，各三仄韵，一韵到底。
多少：不知多少之意。
书：书信。
鱼沉：鱼不传书。古代有鱼雁传书的传说，这里指音讯全无。
秋韵：即秋声。此谓风吹竹声。
攲（qī）：斜，倾。单枕：孤枕。
烬（jìn）：灯芯烧尽成灰。', '分别后不知你的行程远近，满目凄凉心中有说不尽的苦闷。你越走越远渐渐断了书信；鱼书不传我去哪里问讯？
深夜里风吹竹叶萧萧不停，千声万声都是别愁离恨。我斜倚单枕想到梦中见你，谁知道梦没有做成灯芯又燃尽。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74a703048e64fbd89305", "shortContent": "词是写闺中思妇深沉凄绝的别恨。发端句“别后不知君远近”是恨的缘由。因不知亲人行踪，故触景皆生出凄凉、郁闷，亦即无时无处不如此。“多少”，“不知多少”之意，以模糊语言极状其多。三、四两句再进一层，抒写了远别的情状与愁绪。“渐行渐远渐无书”，一句之内重复叠用了三个“渐”字，将思妇的想象意念从近处逐渐推向远处，仿佛去追寻爱人的足迹，然而雁绝鱼沉，天涯何处寻觅踪影！“无书”应首句的“不知”，且欲知无由，她...", "authors": ["吴翠芬"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ae5914587d02f58fd4", "shortContent": "词是写闺中思妇深沉凄绝的别恨。发端句“别后不知君远近”是恨的缘由。因不知亲人行踪，故触景皆生出凄凉、郁闷，亦即无时无处不如此。“多少”，“不知多少”之意，以模糊语言极状其多。三、四两句再进一层，抒写了远别的情状与愁绪。“渐行渐远渐无书”，一句之内重复叠用了三个“渐”字，将思妇的想象意念从近处逐渐推向远处，仿佛去追寻爱人的足迹，然而雁绝鱼沉，天涯何处寻觅踪影！“无书”应首句的“不知”，且欲知无由，她...", "authors": ["吴翠芬"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3c7f0b9738b369b0f6", "shortContent": "全词着力描写闺中思妇深沉凄绝的离愁别恨。\n\n上阕首句“别后不知君远近”是引发思妇怨恨的因由：因为无法得知心上人的行踪，所以凡思妇所触之景皆生出凄凉郁闷之情。“多少”即是“不知多少”之意，极言苦闷心绪之多。第三、四句再进一层，引出第二重“恨”的缘由：“无书”及“鱼沉”。这两句抒写了游子远别思妇的情状和愁绪。“渐行渐远渐无书”，重复连用三个“渐”字，使读者仿佛随着思妇的想象意念从近处逐渐推向游子远行之...", "authors": ["黄晓鋆"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702d77683d193301533c", "shortContent": "全词着力描写闺中思妇深沉凄绝的离愁别恨。\n\n上阕首句“别后不知君远近”是引发思妇怨恨的因由：因为无法得知心上人的行踪，所以凡思妇所触之景皆生出凄凉郁闷之情。“多少”即是“不知多少”之意，极言苦闷心绪之多。第三、四句再进一层，引出第二重“恨”的缘由：“无书”及“鱼沉”。这两句抒写了游子远别思妇的情状和愁绪。“渐行渐远渐无书”，重复连用三个“渐”字，使读者仿佛随着思妇的想象意念从近处逐渐推向游子远行之...", "authors": ["黄晓鋆"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312718cc26cbf3417f09582", "shortContent": "全词着力描写闺中思妇深沉凄绝的离愁别恨。\n上阕首句“别后不知君远近”是引发思妇怨恨的因由：因为无法得知心上人的行踪，所以凡思妇所触之景皆生出凄凉郁闷之情。“多少”即是“不知多少”之意，极言苦闷心绪之多。第三、四句再进一层，引出第二重“恨”的缘由：“无书”及“鱼沉”。这两句抒写了游子远别思妇的情状和愁绪。“渐行渐远渐无书”，重复连用三个“渐”字，使读者仿佛随着思妇的想象意念从近处逐渐推向游子远行之处...", "authors": ["黄晓鋈"], "pressName": "崇文书局"}, {"bookId": "646a05a345e4710056dab21f", "bookTitle": "欧阳修诗文鉴赏辞典（珍藏本）", "articleId": "646c880d30675327e1aa3afa", "shortContent": "词是写闺中思妇深沉凄绝的别恨。发端句“别后不知君远近”是恨的缘由。因不知亲人行踪，故触景皆生出凄凉、郁闷，亦即无时无处不如此。“多少”，“不知多少”之意，以模糊语言极状其多。三、四两句再进一层，抒写了远别的情状与愁绪。“渐行渐远渐无书”，一句之内重复叠用了三个“渐”字，将思妇的想象意念从近处逐渐推向远处，仿佛去追寻爱人的足迹，然而雁绝鱼沉，天涯何处寻觅踪影！“无书”应首句的“不知”，且欲知无由，她...", "authors": ["吴翠芬"], "pressName": "崇文书局"}]', '唐圭璋《唐宋词简释》：此首写别恨，两句一意，次第显然。分别是一恨。无书是一恨。夜闻风竹，又揽起一番离恨。而梦中难寻，恨更深矣。层次深入，句句沉着。', 'indent', 1418810872, '57b8beb279bc44005b9da875', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10712, '青玉案 · 一年春事都来几', NULL, 169, 1229, 0, 2, '欧阳修', NULL, 10018, '57b98d625bbb50005347ace1', '宋', 'ci', '词', 'http://baike.baidu.com/view/879631.htm', '', '一年春事都来几？早过了、三之二。绿暗红嫣浑可事。绿杨庭院，暖风帘幕，有个人憔悴。
买花载酒长安市，又争似家山见桃李？不枉东风吹客泪，相思难表，梦魂无据，惟有归来是。', '这是一首伤春怀乡词。上阕写赏花伤春。「一年」二句交待「春事」已过三分之二，「绿暗红嫣」，讲暮春尚馀可心乐事之景，暗寓了「夕阳无限好」之意。「绿杨」二句以镜头推进的方式，穿庭院，开帘幕，再映出一个憔悴之人。是谁呢？联系下阕「相思难表」来看，显然是词人的爱妻。这几句是词人赏花伤春而联想到如花爱妻的红颜憔悴，遂引发下阕之怀人思归。「买花」二句，将「长安买花」与「家山桃李」对照、比较，显示出对家乡爱妻的深情与爱重。「不枉」句，讲不要错怪春风吹落了感伤的泪水，词人没有像一些词家怨天尤物，责备春风惹恨，花草添愁，而是朴厚、坦诚地讲：「相思难表，梦魂无据」。最后词人表示而今唯有归返家乡最好，趁桃李芳华，享受团圆美满，以慰藉孤独、寂寞，流露出对仕途迁延的厌倦。全词语言浑成，感情真挚，情思由近及远，构思新巧。', '都来：算来。
几：若干、多少。
三之二：三分之二。
红嫣：红艳、浓丽的花朵。
浑可事：都是愉快的事。浑，全；可事，可心的乐事。
长安：指开封汴梁。
争似：怎像。
家山：家乡的山，指故乡。
不枉：不要冤枉、不怪。
是：正确。', '一年的春光算来能占几分？到如今早过了三分之二。绿叶葱翠红花娇艳都是乐事。可是在绿杨婆娑的庭院中，在暖风吹动的帘幕下，却有个人忧心忡忡面容憔悴。
就算是天天在长安买花载酒，又哪能比得上在故乡山里观赏桃李？不要怪春风吹落异乡人的眼泪，相思之情难以表白，梦魂也飘忽无依，只有回到家乡才称心如意。', '[{"bookId": "6277f84f8efdff05d7d6839b", "bookTitle": "李清照全集", "articleId": "6312258b77683d193300d3d0", "shortContent": "此词明·胡桂芳编《类编草堂诗余》、《古今词统》题作《春日怀旧》。杨金本《草堂诗余》题作《春情》。仅汲古阁未刻词本《漱玉词》收为李清照词。沈际飞本《草堂诗余》正集注：“一刻易安”。《类编草堂诗余》等认为此首是欧阳修作。列存疑作，疑之在作者。", "authors": [], "pressName": "崇文书局"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3c7f0b9738b369b0fa", "shortContent": "此词为欧阳修老年时借春遣思、怀乡思归之作，具体创作时间及创作背景，已不可考。\n\n欧词向来以清雅柔丽、自然浑成著称，这首《青玉案》虽是伤春旧格，但因作者浓重的情思，别致的语言，依然独立于一众伤春怀人词中，别具一格。此词上阕状景，首句便是一句轻叹：一年春光能有多少呢？早已过了三分之二了。自问自答间，散发着若有似无的淡淡无奈。“绿暗红嫣浑可事”，暮春时节，满院花柳明媚，红绿分明，本应是赏花乐事，然而在这...", "authors": ["马　瑶"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702d77683d1933015341", "shortContent": "此词为欧阳修老年时借春遣思、怀乡思归之作，具体创作时间及创作背景，已不可考。\n\n欧词向来以清雅柔丽、自然浑成著称，这首《青玉案》虽是伤春旧格，但因作者浓重的情思，别致的语言，依然独立于一众伤春怀人词中，别具一格。此词上阕状景，首句便是一句轻叹：一年春光能有多少呢？早已过了三分之二了。自问自答间，散发着若有似无的淡淡无奈。“绿暗红嫣浑可事”，暮春时节，满院花柳明媚，红绿分明，本应是赏花乐事，然而在这...", "authors": ["马瑶"], "pressName": "崇文书局"}]', '', 'indent', 1418819772, '57b9c34f8ac2470063ff49c5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10713, '曲玉管', NULL, 112, 225, 2, 1, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/view/2792145.htm', '', '陇首云飞，江边日晚，烟波满目凭阑久。立望关河萧索，千里清秋，忍凝眸。
杳杳神京，盈盈仙子，别来锦字终难偶。断雁无凭，冉冉飞下汀洲、思悠悠。
暗想当初，有多少、幽欢佳会；岂知聚散难期，翻成雨恨云愁。阻追游，每登山临水，惹起平生心事，一场消黯，永日无言，却下层楼。', '本词描叙作者登高望远，触景生情，感叹羁旅行役生活的愁苦，抒发无限相思之情。第一片以写萧瑟清秋晚景为主．羁旅之愁寓于其中。山岭上暮云纷飞，江边暮霭迷茫，满目烟波浩渺，词人凭栏很久，凝神注视远方。一眼望去，山河冷落萧条，清秋万里凄凉，不忍心再望。
第二片回忆想念恋人，抒离愁别恨，寄托无穷相思。在那遥远的神京汴梁，有位美女，光彩照人如仙人一样，自从分手以来，再也无法得到她的音信，令“我”不胜忧伤，望断南飞的大雁，也毫无用处，只会追引我的忧思更加悠长。
第三片忆旧欢，诉今愁惹起平生心事，令人忧郁无限。暗想当初，有多少幽会欢娱的美好时光，岂知聚散难以预想，当时的欢乐，反而酿成今日的无限怅惘。千里阻隔，我们无从相见，只有相互思念。每当登山临水，都会惹起“我”对往事的回想，总是暗自销魂，神情沮丧，终日里闷闷无言，独自默默地走下楼廊。全词以写景抒情为脉络，层层铺叙，步步深入，言浅意丰，平白如水。', '曲玉管：词牌名。
陇首：亦称陇坻、陇坂，为今陕西宝鸡与甘肃交界处险塞。
凭阑：即凭栏，倚靠着楼台的栏杆。
关河：关塞河流，这里泛指山河。
忍：怎能忍受。
凝眸：目光凝聚在一起。
杳（yǎo）杳：遥远渺茫。
神京：帝京，京都，这里指汴京（今开封）。
盈盈：形容女子娇媚可爱的神态。
仙子：比喻美女，这里指词人所爱的歌女。
锦字：又称织绵回文。事见《晋书·窦滔妻苏氏传》，云“窦滔妻苏氏，始平人也。名蕙，字若兰。善属文。滔，苻坚时为秦州刺史，被徙流沙。苏氏思之，织锦为回文旋图诗以赠滔，宛转循环以读之，词甚凄惋，凡八百四十字”。后用以指妻寄夫之书信。
难偶：难以相遇。
断雁：鸿雁传书，这里指雁没有担负起传书的任务。
冉冉：形容慢慢飞落的样子。
冉冉：慢慢、渐渐。
汀：水中或水边之平地。
思悠悠：思念之情绵绵不绝。
雨恨云愁：指两人的爱情不能成功，心头充满悔恨哀愁。
阻追游：被某种力量阻碍而不能自由追寻自己的所爱。
消黯：黯然销魂。
永日：长日。长，兼指时间或空间。
却下层楼：只得无精打采地走下高楼。', '山岭之上，黄昏的云彩纷飞，晚上江边，暮霭沉沉。眼前是一片烟波万里，我凭栏久久望去，只见山河是那么清冷萧条，清秋处处凄凉，让人心中不忍难受。在那遥远的神京，有一位盈盈的如仙佳人。自从分手以来，再也没有她的音信，令我思念悠悠。我望断南飞的大雁，也未等到来任何的凭据，只能使我的愁思更长。回想当初有多少相见的美好时光，谁知聚散不由人，当时的欢乐，反变成今日的无限愁怨。千里之外我们无从相见，只有彼此思念。每当我又见山水美景，都会勾起我的回忆，只好默默无语，独自下楼去。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749d2e6a6b501f9541c2", "shortContent": "这首词是写离别之恨与羁旅之愁的。作者登高怀远，触景伤情，而将情景打成一片，往复交织，前后照应，针线尤为细密。\n全词共分三叠。凡是三叠的词，以音律论，前两叠是双拽头，后一叠才是换头（一称过片）。故文词也每每是前两叠大体一意，后一叠另作一意，使声情相应。此词第一叠“陇首”三句，是当前景物和情况。“云飞”、“日晚”，隐含下“凭阑久”。“亭皋木叶下，陇首秋云飞”，是梁柳恽的名句。陇首，犹言山头。云、日、烟...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a55914587d02f58fb9", "shortContent": "这首词是写离别之恨与羁旅之愁的。作者登高怀远，触景伤情，而将情景打成一片，往复交织，前后照应，针线尤为细密。\n全词共分三叠。凡是三叠的词，以音律论，前两叠是双拽头，后一叠才是换头（一称过片）。故文词也每每是前两叠大体一意，后一叠另作一意，使声情相应。此词第一叠“陇首”三句，是当前景物和情况。“云飞”、“日晚”，隐含下“凭阑久”。“亭皋木叶下，陇首秋云飞”，是梁柳恽的名句。陇首，犹言山头。云、日、烟...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f39e6f69b71e93f6189", "shortContent": "此词作于仁宗景祐元年（1034），柳永进士及第后离开汴京赴外任职期间。此词抒写了登山临水所触发的旅思离怀，羁旅行役中的都市风情，高远悲凉的气象中揉入了旖旎冶艳的情思，这正是柳词突破传统宦游题材所呈现的特色。\n本词为三叠长调。前二调是双拽头，平列出两段情景相交织。上片写眼前所见的秋天景色：“陇首云飞，江边日晚，烟波满目凭阑久。”“陇首”即山头。“云飞”即云阵飞行。“阑”通“栏”，即栏杆之意。意思是，...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe47ccdb86c49f29177", "shortContent": "此词作于仁宗景祐元年（1034），柳永进士及第后离开汴京赴外任职期间。此词抒写了登山临水所触发的旅思离怀，羁旅行役中的都市风情，高远悲凉的气象中揉入了旖旎冶艳的情思，这正是柳词突破传统宦游题材所呈现的特色。\n\n本词为三叠长调。前二调是双拽头，平列出两段情景相交织。上片写眼前所见的秋天景色：“陇首云飞，江边日晚，烟波满目凭阑久。”“陇首”即山头。“云飞”即云阵飞行。“阑”通“栏”，即栏杆之意。意思是...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d125c7af6de1647100d8a", "bookTitle": "柳永词鉴赏辞典", "articleId": "646d8ddc30675327e1ae700b", "shortContent": "这首词是写离别之恨与羁旅之愁的。作者登高怀远，触景伤情，而将情景打成一片，往复交织，前后照应，针线尤为细密。\n\n全词共分三叠。凡是三叠的词，以音律论，前两叠是双拽头，后一叠才是换头（一称过片）。故文词也每每是前两叠大体一意，后一叠另作一意，使声情相应。此词第一叠“陇首”三句，是当前景物和情况。“云飞”、“日晚”，隐含下“凭阑久”。“亭皋木叶下，陇首秋云飞”，是梁柳恽的名句。陇首，犹言山头。云、日、...", "authors": ["沈祖棻"], "pressName": "上海辞书出版社"}]', '', 'indent', 1418819898, '57b98f08165abd005a6d0a4e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10714, '采莲令', NULL, 90, 225, 0, 1, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/view/3428728.htm', '', '月华收，云淡霜天曙。西征客、此时情苦。翠娥执手送临歧、轧轧开朱户。千娇面、盈盈伫立，无言有泪，断肠争忍回顾？
一叶兰舟，便恁急桨凌波去。贪行色、岂知离绪。万般方寸，但饮恨、脉脉同谁语？更回首、重城不见，寒江天外，隐隐两三烟树。', '这首词写离别情。上阕写离别时月落云收，霜天欲曙，即将西行的客子，此刻的心情最为痛苦。随着吱吜吱吜的声音，一层层打开红色的门户，美人紧拉他的手，一直送到岔道口。「千娇面」三句，生动细腻地描绘了离人内心的痛苦。她千娇百媚，难以自持，亭亭伫立在那里，默默无语，唯有满脸的泪珠，那神情、令人肝肠寸断，又怎忍心回头一望？下阕写离人别后无限惆怅和无尽的留恋。他感到自己所乘的扁舟「急桨凌波」而去，他人只贪看两岸景色，哪里知道离人此时的离情别绪，心如刀割、纷乱至极。而又无人可与之诉说愁苦，只能暗自含恨。其哀其痛，实是不堪忍受。末以景收，回头望去，层层的城门早已不见，只有那充满寒意的江天之外，隐隐约约，可以看到三两棵树木。全词以景起兴，以景作结，景中寓情，景黯情凄，语言浅淡而意深情挚。', '月华收：指月亮落下，天气将晓。
临歧：岔路口。此指临别。
轧轧：象声词，门轴转动的声音。
争忍：怎忍。
方寸：指心绪，心情。
脉脉：含情貌。', '月亮已收起了光华，云淡淡的，地上有霜。天色已黎明。将远行西去的人，此时心情最苦。美人儿紧握着我的手，为了送我上分别的岔路，她把朱红的大门轧轧地打开。千娇百媚的脸庞、婀娜轻盈的身姿，她久久地站着，没有话，只流泪。我肠都要痛断了，又怎么忍心回头再看她一眼呢？
我乘坐的一叶扁舟，便如此急急地随着水波去了。临去前，我只顾准备走，行色匆匆，哪知离别的心绪，会万般千种地袭来心头呢！我只得心怀怨恨，含情脉脉，这满腹的话又能对谁去说呢？待到我再回过头去时，重城已看不到了。寒飕飕的秋江上，唯见天外隐隐约约地有两三株烟蒙蒙的远树而已。', '[{"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f39e6f69b71e93f618c", "shortContent": "这首词也是写与恋人的离别之情。唐圭璋《唐宋词简释》云：“此首，初点月收天曙之景色，次言客心临别之凄楚。‘翠娥’以下，皆送行人之情态。执手劳劳，开户轧轧，无言有泪，记事既生动，写情亦逼真。‘断肠’一句，写尽两面依依之情。换头，写别后舟行之速。‘万般’两句，写别后心中之恨。‘更回首’三句，以远景作收，笔力千钧。上片之末言回顾，谓人。此则谓舟行已远，不独人不见，即城亦不见，但见烟树隐隐而已。一顾再顾，总...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe47ccdb86c49f2917a", "shortContent": "这首词也是写与恋人的离别之情。唐圭璋《唐宋词简释》云：“此首，初点月收天曙之景色，次言客心临别之凄楚。‘翠娥’以下，皆送行人之情态。执手劳劳，开户轧轧，无言有泪，记事既生动，写情亦逼真。‘断肠’一句，写尽两面依依之情。换头，写别后舟行之速。‘万般’两句，写别后心中之恨。‘更回首’三句，以远景作收，笔力千钧，上片之末言回顾，谓人。此则谓舟行已远，不独人不见，即城亦不见，但见烟树隐隐而已。一顾再顾，总...", "authors": ["周密"], "pressName": "崇文书局"}]', '', 'indent', 1418820003, '57b9cde27db2a20068bf329a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (362614, '减字浣溪沙 · 美人颈1912', NULL, 0, 208, 0, 1, '况周颐', NULL, 21606, '5836b80cd20309005fec0d1d', '清', 'ci', '词', '', '', '延秀雒川鹤未翔。蝤蛴玉映镜中妆。低垂腻粉却羞郎。
书雁迟回劳引望，绣鸳偎傍惯交相。溜钗情味亸鬟香。', '', '', '', NULL, '', 'indent', 1543315642, '585e970c61ff4b0063fa92e3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10715, '浪淘沙慢', NULL, 86, 225, 2, 1, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/view/8173191.htm', '', '梦觉，透窗风一线，寒灯吹息。那堪酒醒，又闻空阶，夜雨频滴。嗟因循久作天涯客。负佳人、几许盟言，更忍把、从前欢会，陡顿翻成忧戚。
愁极。再三追思，洞房深处，几度饮散歌阑，香暖鸳鸯被，岂暂时疏散，费伊心力。殢雨尤云，有万般千种，相怜相惜。恰到如今，天长漏永，无端自家疏隔。知何时、却拥秦云态，愿低帏昵枕，轻轻细说与，江乡夜夜，数寒更思忆。', '这首词是抒写对所恋秦楼歌妓相思、愁戚之作。全词两片。上片以“梦觉”、“酒醒”写离别后羁旅江乡的忧戚，穿插寒灯、空阶、夜雨之意象加以烘染，构成寒瑟、空寂、暗淡的夜境，显示出词人孤独煎熬的寂寞与悲戚。下片从上片“忧戚”转入“愁极”，承“从前欢会”而追思往昔热恋情景。接着又感叹“无端自家疏隔”，揭明造成今日忧戚、疏隔，还是“自家”的因循宦途所致，颇有自责自悔之意。词人于愁极无奈中，生出对未来欢聚之期愿：悬想虚拟将来重逢团聚之时，再细说我而今“江乡夜夜，数寒更思忆”之情景。这首词的特点是将相思离别之情刻画得淋漓尽致，没有一点含蓄，这种露骨地表达感情的方式显然受到民间俚曲的影响。', '浪淘沙慢：柳永创调。双调一百三十三字，前段九句四仄韵，后段十六句五仄韵。
因循：不振作之意。迟延拖拉，漫不经心。
几许盟言：多少山盟海誓的话。
陡顿：突然。
殢（tì）雨尤云：贪恋男女欢情。殢：恋昵。尤：相娱、相恋之意。
漏永：古人以铜壶滴漏计算时间，这里指时间过得慢。这里指夜深。
疏隔：疏远阻隔。
秦云：秦楼云雨。形容男欢女爱。
低帏：放下帏帐。
昵：亲近，亲昵。
数（shuò）：多次。', '一觉醒来时，一缕寒风透过窗棂吹进房中，把孤灯吹熄。酒醒后的凄凉本已难耐，又听见屋外台阶上的落雨点点滴滴。可叹我迁延漂泊，孑然一身，沦落天涯。如今想起来，真是辜负了佳人的一片真情，多少山盟海誓竟成空言，又怎能忍心把从前的两情欢愉，陡然间变成眼下这孤独忧戚。
愁闷之极！反复地回忆，想当初那洞房深处，多少次畅饮欢歌，双双游嬉于鸳鸯被底。那时节我尽心奉承，生怕耗费她一点气力。万种柔情，千般亲昵，我二人缠绵无尽，两情相依相惜。看如今，漫漫长夜漏壶永滴，就这样两地相思隔绝千里。我真是自寻离愁，却让你牵肠挂肚徒悲凄。不知要等到哪日，你我重拥鸳鸯被，共度欢情，如胶似漆。到那时，愿帷幕低垂玉枕亲昵。我会轻轻细说告诉你，在这偏远的寒江水乡，我夜夜难眠，数着寒更把你思念，把你惦记。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749e0ce818559d050742", "shortContent": "这是柳永创制慢词的一个范例。唐五代所传之《浪淘沙》词，或为二十八字体，或为五十四字体，皆为令词小调。柳永这首词，则衍之为一百三十五字之长篇巨制，共三片。第一片写主人公夜半酒醒时的忧戚情思；第二片追思以往相怜相惜之情事；第三片写眼下的相思情景。体制扩大，容量增加，主人公的全部心理状态及情思活动过程，都得到了充分的表现。\n词作从“梦觉”时所见、所闻写起，说窗风吹息寒灯，夜雨频滴空阶，可知并非天亮觉醒，...", "authors": ["施议对"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a67d0ac1145495e855", "shortContent": "这是柳永创制慢词的一个范例。唐五代所传之《浪淘沙》词，或为二十八字体，或为五十四字体，皆为令词小调。柳永这首词，则衍之为一百三十五字之长篇巨制，共三片。第一片写主人公夜半酒醒时的忧戚情思；第二片追思以往相怜相惜之情事；第三片写眼下的相思情景。体制扩大，容量增加，主人公的全部心理状态及情思活动过程，都得到了充分的表现。\n词作从“梦觉”时所见、所闻写起，说窗风吹息寒灯，夜雨频滴空阶，可知并非天亮觉醒，...", "authors": ["施议对"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f39e6f69b71e93f618d", "shortContent": "柳永善写羁旅行役之苦与相思愁情之痛，但他与很多先前的诗人或词人喜欢借用女子的口吻来抒写离情别怨不同，他总是毫不掩饰自己的情感，直接大胆地表露自己的内心世界，没有一点含蓄，这种露骨地表达感情的方式显然受到民间俚曲的影响，也因此他的词作中主体形象更加鲜明。\n《浪淘沙》词多为小令，柳永此词则衍化成一百三十五字的长调，分三叠，体制扩大，容量增加，用如今——往昔——如今的结构，充分表现了主人公全部心理状态及...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe47ccdb86c49f2917b", "shortContent": "柳永善写羁旅行役之苦与相思愁情之痛，但他与很多先前的诗人或词人喜欢借用女子的口吻来抒写离情别怨不同，他总是毫不掩饰自己的情感，直接大胆地表露自己的内心世界，没有一点含蓄，这种露骨地表达感情的方式显然受到民间俚曲的影响，也因此他的词作中主体形象更加鲜明。\n\n《浪淘沙》词多为小令，柳永此词则衍化成一百三十五字的长调，分三叠，体制扩大，容量增加，用如今——往昔——如今的结构，充分表现了主人公全部心理状态...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127174c305cf08018170af", "shortContent": "柳永善写羁旅行役之苦与相思愁情之痛，但他与很多先前的诗人或词人喜欢借用女子的口吻来抒写离情别怨不同，他总是毫不掩饰自己的情感，直接大胆地表露自己的内心世界，没有一点含蓄。这种露骨地表达感情的方式显然受到民间俚曲的影响，也因此他的词作中主体形象更加鲜明。\n《浪淘沙》词多为小令，柳永此词则衍化成一百三十五字的长调，分三叠，体制扩大，容量增加，用如今一往昔一如今的结构，充分表现了主人公全部心理状态及情思...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d125c7af6de1647100d8a", "bookTitle": "柳永词鉴赏辞典", "articleId": "646d8e967da2f75ac70d0e55", "shortContent": "这是柳永创制慢词的一个范例。唐五代所传之《浪淘沙》词，或为二十八字体，或为五十四字体，皆为令词小调。柳永这首词，则衍之为一百三十五字之长篇巨制，共三片。第一片写主人公夜半酒醒时的忧戚情思；第二片追思以往相怜相惜之情事；第三片写眼下的相思情景。体制扩大，容量增加，主人公的全部心理状态及情思活动过程，都得到了充分的表现。\n\n词作从“梦觉”时所见、所闻写起，说窗风吹息寒灯，夜雨频滴空阶，可知并非天亮觉醒...", "authors": ["施议对"], "pressName": "上海辞书出版社"}]', '刘熙载《艺概》：绮罗香泽之态，所在多有，故觉风期未上耳。', 'indent', 1418820140, '57b939470a2b58005c942386', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10716, '定风波 · 自春来惨绿愁红', NULL, 143, 225, 5, 2, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/item/定风波·自春来惨绿愁红', '', '自春来、惨绿愁红，芳心是事可可。日上花梢，莺穿柳带，犹压香衾卧。暖酥消、腻云亸、终日厌厌倦梳裹。无那。恨薄情一去，音书无个。
早知恁么，悔当初、不把雕鞍锁。向鸡窗，只与蛮笺象管，拘束教吟课。镇相随、莫抛躲，针线闲拈伴伊坐。和我，免使年少，光阴虚过。', '这是柳永俚词的代表作之一。作者用明白透彻的语言，大胆而直露地描写一位女子的相思别离之情。上片写自新春以来思妇没精打采，疏懒厌倦的情绪和神态。太阳光已上了花梢，黄莺在柳树上穿飞跳挪，思妇依旧拥着熏香的锦被，终日里慵闲懒散。云样的秀发蓬松散乱，红润的面容憔悴瘦削，终日百无聊赖，懒得梳洗打扮，搽搽抹抹。“无那”一声长叹，点出所以然之故，只恨薄情人一去，踪影全无，连书信也不捎回一个。下片展现思妇的内心活动，她后悔当初不把他的马鞍子紧紧上锁，把他留在家中，让他坐在窗前，给他些纸张笔墨，终日苦读，温习功课，自己整日陪伴，方不至虚度青春。全词以家常口语，铺展闺房生活细节，体现市民女性炽烈的爱情追求。', '芳心：指女子的心境。
是事可可：对什么事情都不在意，无兴趣。一切事全含糊过去。可可：无关紧要；不在意。
暖酥：极言女子肌肤之好。
腻云亸：头发散乱。亸（duǒ）：下垂貌。
梳裹：梳妆打扮。《二十年目睹之怪现状》第八九回：“这里姨妈招呼着和少奶奶重新梳裹已毕。”
无那：无奈。
恁么：这么。
鸡窗：指书窗或书房。语出《幽明录》："晋兖州刺史沛国宋处宗尝得一长鸣鸡，爱养甚至，恒笼著窗间。鸡遂作人语，与处宗谈论极有言智，终日不辍。处宗因此言巧大进。“（《艺文类聚·鸟部》卷九十一引）。
蛮笺象管：纸和笔。蛮笺：古时四川所产的彩色笺纸。象管：即象牙做的笔管。
镇：镇日，整天。
和：允诺。
光阴虚过：时光白白度过。光阴：时间；虚：空。', '自入春以来见那红花绿叶全带着愁苦，每件事都让我心烦意乱。太阳已升到了花树梢头，黄莺已在柳条间鸣啼穿梭，我还在锦被里躺着。腰身消瘦了，秀发低垂散乱，整天无精打采，懒得把胭脂抹。真无奈，可恨那薄情郎一去之后，从不把书信捎。
早知如此，后悔当初没有把他的宝马锁起来。真该把他留在书房里，只让他与彩笺毛笔为伍，让他吟诗作功课。就这样，他与我日日紧相随，不分开。我手拿着针线与他相倚相挨。我们要快快活活长厮守，免得使青春年少的光阴虚度，苦苦等待。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749e5914587d02f465bd", "shortContent": "关于这首词，曾经有过一则故事。宋人张舜民《画墁录》记载：柳永因作《醉蓬莱》词忤仁宗之后，曾求谒当时的政府长官晏殊改放他官，晏殊问柳：“贤俊作曲子（词）么？”柳永答曰：“只如相公亦作曲子。”晏殊即道：“殊虽作曲子，（却）不曾道‘彩线慵拈伴伊坐’（“彩线慵拈伴伊坐”和本文所引的“针线闲拈伴伊坐”系版本不同所致。晏殊所举出的，正是这首《定风波》词。）。”柳永只得告退。从中我们可以感觉到，正统的士大夫文人...", "authors": ["杨海明"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a6911759740c9bcb0e", "shortContent": "关于这首词，曾经有过一则词坛故事。据宋人张舜民《画墁录》记载：柳永因作《醉蓬莱》词忤仁宗之后，曾求谒当时的政府长官晏殊改放他官，晏殊问柳：“贤俊作曲子（词）么？”柳永答曰：“只如相公亦作曲子。”晏殊即道：“殊虽作曲子，（却）不曾道‘彩线慵拈伴伊坐’[1]。”柳永只得告退。从中我们可以感觉到，正统的士大夫文人和柳永之间，其艺术趣味是有所不同的。\n这首《定风波》表现的是思妇的闺怨。它用代言体的口吻、放...", "authors": ["杨海明"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252ccce4d48ba496d7e", "shortContent": "关于这首词，曾经有过一则词坛故事。宋人张舜民《画墁录》记载：柳永因作《醉蓬莱》词忤仁宗之后，曾求谒当时的政府长官晏殊改放他官，晏殊问柳：“贤俊作曲子（词）么？”柳永答曰：“只如相公亦作曲子。”晏殊即道：“殊虽作曲子，（却）不曾道‘彩线慵拈伴伊坐’[1]。”柳永只得告退。从中我们可以感觉到，正统的士大夫文人和柳永之间，其艺术趣味是有所不同的。\n\n这首《定风波》表现的是思妇的闺怨。它用代言体的口吻、放...", "authors": ["杨海明"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f39e6f69b71e93f618e", "shortContent": "《定风波》原为唐玄宗时教坊曲名，后来用为词牌。\n这首闺怨词以一个少妇（或妓女）的口吻写作，抒写她同恋人分别后的相思之情，是柳永词中具市井气的俗词代表作之一。\n词一开篇就写得别具情致。\n自从春天来临后，我看到的是柳叶绿得惨淡，桃花红得愁苦。“惨绿愁红”四个字，写尽了这女子透过绿叶红花含蓄而准确地表达出来的那股思春之情，所以“芳心是事可可”，因为相思的心好寂寞啊，我干什么都无情无绪，终日慵散无聊。外面...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe47ccdb86c49f2917c", "shortContent": "《定风波》原为唐玄宗时教坊曲名，后来用为词牌。这首闺怨词以一个少妇（或妓女）的口吻写作，抒写她同恋人分别后的相思之情，是柳永词中具市井气的俗词代表作之一。\n\n词一开篇就写得别具情致。自从春天来临后，我看到的是柳叶绿得惨淡，桃花红得愁苦。“惨绿愁红”四个字，写尽了这女子透过绿叶红花含蓄而准确地表达出来的那股思春之情，所以“芳心是事可可”，因为相思的心好寂寞啊，我干什么都无情无绪，终日慵散无聊。外面艳...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d125c7af6de1647100d8a", "bookTitle": "柳永词鉴赏辞典", "articleId": "646d8ecce49f46528acae227", "shortContent": "关于这首词，曾经有过一则词坛故事。据宋人张舜民《画墁录》记载：柳永因作《醉蓬莱》词忤仁宗之后，曾求谒当时的政府长官晏殊改放他官，晏殊问柳：“贤俊作曲子（词）么？”柳永答曰：“只如相公亦作曲子。”晏殊即道：“殊虽作曲子，（却）不曾道‘彩线慵拈伴伊坐’（‘彩线慵拈伴伊坐’和本文所引的‘针线闲拈伴伊坐’系版本不同所致。晏殊所举出的，正是这首《定风波》词。）。”柳永只得告退。从中我们可以感觉到，正统的士大...", "authors": ["杨海明"], "pressName": "上海辞书出版社"}]', '', 'indent', 1418820259, '57b969198ac2470062e33c67', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10717, '少年游', NULL, 452, 225, 3, 4, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/view/570500.htm', '', '长安古道马迟迟，高柳乱蝉嘶。夕阳鸟外，秋风原上，目断四天垂。
归云一去无踪迹，何处是前期？狎兴生疏，酒徒萧索，不似少年时。', '这首词描写作者落魄潦倒时茕茕独处的凄凉情形。上阕写词人在长安古道上马行迟迟，秋蝉在高高的柳树上鸣叫，声音纷乱哀凄，夕阳在飞鸟外的远方渐渐沉落，旷野荒原上秋风习习，极目四望，没有人烟，只有旷阔的天空如幕帐般向下四垂。下阕写所爱离去，一去后便再无踪迹。如今冶游狎妓的兴致已经衰减，昔日酒友也寥寥无几，一切都如虚如幻，不像少年时那样狂放不羁，无所顾忌。全词表露出世态炎凉、人情冷暖的悲绪。', '马迟迟：马行缓慢的样子。
乱蝉嘶：一作「乱蝉栖」。
鸟外：一作「岛外」。岛，指河流中的洲岛。
原上：乐游原上，在长安西南。
目断：极目望到尽头。
四天垂：天的四周夜幕降临。
归云：飘逝的云彩。这里比喻往昔经历而现在不可复返的一切。此句一作「归去一云无踪迹」。
前期：以前的期约。既可指往日的志愿心期又可指旧日的欢乐约期。
狎兴：游乐的兴致。狎，亲昵而轻佻。
酒徒：酒友。
萧索：零散、稀少，冷落、寂寞。
少年时：又作「去年时」。', '我骑马在长安古道缓慢前行，秋蝉在高高的柳树上不住鸣。夕阳在高外的远方渐渐沉落，旷野荒原之上秋天之风习习，极目四望旷阔天空幕帐四垂。
时光逝去永远不会再次回来，旧日的期望和约定何处去寻？寻欢作乐的兴致早已经淡漠，那些一起喝酒的朋友也散去，再也不像少年之时狂放不羁。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749fd635634aee3d7128", "shortContent": "一般人论及柳永词者，往往多着重于他在长调慢词方面的拓展，其实他在小令方面的成就，也是极可注意的。我以前在《论柳永词》一文中，曾经谈到柳词在意境方面的拓展，以为唐五代小令中所叙写的“大多只不过是闺阁园亭伤离怨别的一种‘春女善怀’的情意”，而柳词中一些“自抒情意的佳作”，则写出了“一种‘秋士易感’的哀伤”。这种特色，在他的一些长调的佳作，如《八声甘州》《曲玉管》《雪梅香》诸词中，都曾经有很明白的表现。...", "authors": ["叶嘉莹"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a65914587d02f58fbe", "shortContent": "一般人论及柳永词者，往往多着重于他在长调慢词方面的拓展，其实他在小令方面的成就，也是极可注意的。我以前在《论柳永词》一文中，曾经谈到柳词在意境方面的拓展，以为唐五代小令中所叙写的“大多只不过是闺阁园亭伤离怨别的一种‘春女善怀’的情意”，而柳词中一些“自抒情意的佳作”，则写出了“一种‘秋士易感’的哀伤”。这种特色，在他的一些长调的佳作，如《八声甘州》、《曲玉管》、《雪梅香》诸词中，都曾经有很明白的表...", "authors": ["叶嘉莹"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f39e6f69b71e93f618f", "shortContent": "叶嘉莹在论及柳永词时指出：“北宋初的词人，如晏殊、欧阳修，只用很少几个牌调，如《浣溪沙》、《玉楼春》等。柳永《乐章集》中的牌调比任何人都丰富。柳永也写短小的令词，而且也写得很好，即如我们讲义中所选的《少年游》及《凤栖梧》等，便都是极耐人寻味的富有感发和含蕴的令词。”这首《少年游》小词，就是柳永将其“秋士易感”的失志之悲，写入了令词的一篇代表作。柳永词写情多较直露，这首小令却有些含蓄蕴藉。因为构思上...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe47ccdb86c49f2917d", "shortContent": "叶嘉莹在论及柳永词时指出：“北宋初的词人，如晏殊、欧阳修，只用很少几个牌调，如《浣溪沙》、《玉楼春》等。柳永《乐章集》中的牌调比任何人都丰富。柳永也写短小的令词，而且也写得很好，即如我们讲义中所选的《少年游》及《凤栖梧》等，便都是极耐人寻味的富有感发和含蕴的令词。”这首《少年游》小词，就是柳永将其“秋士易感”的失志之悲，写入了令词的一篇代表作。柳永词写情多较直露，这首小令却有些含蓄蕴藉。因为构思上...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127174c305cf08018170b0", "shortContent": "叶嘉莹在论及柳永词时指出：“北宋初的词人，如晏殊、欧阳修，只用很少几个牌调，如《浣溪沙》《玉楼春》等。柳永《乐章集》中的牌调比任何人都丰富。柳永也写短小的令词，而且也写得很好，即如我们讲义中所选的《少年游》及《凤栖梧》等，便都是极耐人寻味的富有感发和含蕴的令词。”这首《少年游》小词，就是柳永将其“秋士易感”的失志之悲，写人了令词的一篇代表作。柳永词写情多较直露，这首小令却有些含蓄蕴藉。因为构思上把...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d125c7af6de1647100d8a", "bookTitle": "柳永词鉴赏辞典", "articleId": "646d8ef17f27182da379637d", "shortContent": "一般人论及柳永词者，往往多着重于他在长调慢词方面的拓展，其实他在小令方面的成就，也是极可注意的。我以前在《论柳永词》一文中，曾经谈到柳词在意境方面的拓展，以为唐五代小令中所叙写的“大多只不过是闺阁园亭伤离怨别的一种‘春女善怀’的情意”，而柳词中一些“自抒情意的佳作”，则写出了“一种‘秋士易感’的哀伤”。这种特色，在他的一些长调的佳作，如《八声甘州》、《曲玉管》、《雪梅香》诸词中，都曾经有很明白的表...", "authors": ["叶嘉莹"], "pressName": "上海辞书出版社"}]', '', 'indent', 1418820327, '57b92f1b5bbb50005b79aced', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10718, '戚氏', NULL, 152, 225, 2, 1, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/view/1044462.htm', '', '晚秋天，一霎微雨洒庭轩。槛菊萧疏，井梧零乱，惹残烟。凄然，望江关，飞云黯淡夕阳间。当时宋玉悲感，向此临水与登山。远道迢递，行人凄楚，倦听陇水潺湲。正蝉吟败叶，蛩响衰草，相应喧喧。
孤馆度日如年，风露渐变，悄悄至更阑。长天净，绛河清浅，皓月婵娟。思绵绵，夜永对景，那堪屈指暗想从前。未名未禄，绮陌红楼，往往经岁迁延。
帝里风光好，当年少日，暮宴朝欢。况有狂朋怪侣，遇当歌对酒竞留连。别来迅景如梭，旧游似梦，烟水程何限？念利名、憔悴长萦绊，追往事、空惨愁颜。漏箭移，稍觉轻寒，渐呜咽、画角数声残。对闲窗畔，停灯向晓，抱影无眠。', '此词为抒写羁旅行役情怀的代表作。全词三阕。首阕叙述晚秋行旅的悲凄。以微雨、疏菊、零梧、残烟等关合秋景的意象，描摹驿馆庭轩荒寂、冷落之境。中阕再叙长夜幽思，承首阕「夕阳」而转入「更阑」，暗示彻夜失眠，以「孤馆度日如年」概括首阕之凄楚悲感的沉郁、深长。尾阕是对年少风流旧游的回忆和对名禄羁绊的苦闷：前者以热笔写未名未禄的「暮宴朝欢」，後者以冷笔写利名萦绊的「空惨愁颜」，而藉漏箭、轻寒、角声点染旧游梦破，抱影无眠的愁惨悲寒的气氛。全词铺叙展衍，结构缜密，抒情酣畅，藉景点染，将今日的黄昏之悲、长夜之苦与往日的「暮宴朝欢」之乐交错映现，突出今昔剧变的苍凉之感。', '戚氏：词牌名，为柳耆卿所创，长调慢词，《乐章集》收入「中吕调」。全词三叠，计二百一十二字，为北宋长调慢词之最，亦堪称柳词压轴之作。
一霎：一阵。
庭轩：庭院里有敞窗的厅阁。
槛菊：栏杆外的菊花。
井梧：井旁挺拔的梧桐古树。源自唐·薛洪度《井梧吟》：「庭除一古桐，耸干入云中。枝迎南北鸟，叶送往来风。」
江关：疑即指荆门，荆门、虎牙二山（分别在今湖北省枝城市和宜昌市）夹江对峙，古称江关，战国时为楚地。
宋玉悲感：战国楚·宋玉作《九辩》，曾以悲秋起兴，抒孤身逆旅之寂寞，发生不逢时之感慨。
迢递：遥不可及貌。迢：高貌。
陇水：疑非河流名，实为陇头流水之意。北朝乐府有《陇头歌辞》，词曰：「陇头流水，流离山下。念吾一身，飘然旷野。」「陇头流水，鸣声呜咽。遥望秦川，心肝断绝。」
潺湲（chán yuán）：水流貌。
蛩（qióng）：蟋蟀也。
更（gēng）阑：五更将近，天快要亮了。犹言夜深。
绛河：即银河。天空称为绛霄，银河称为绛河。
婵娟：美好貌。
夜永：夜长也。
绮陌红楼：犹言花街青楼。
绮陌：繁华的道路。
经岁：经年，以年为期。
迁延：羁留也。
狂朋怪侣：狂放狷傲的朋友。
竞：竞相也。
迅景：岁月也，光阴易逝，故称。
程：即路程。
萦绊：犹言纠缠。
漏箭：古时以漏壶滴水计时，漏箭移即光阴动也。
画角：古时军用管乐器，以竹木或皮革製成，发声哀厉髙亢，多用於晨昏报时或报警，因表面有綵绘，故称画角。
停灯：即吹灭灯火。
抱影无眠：守着自己的孤影，一夜没有睡着。', '时值深秋，短促的细雨飘洒在院落庭中。栏边的秋菊已谢，天井旁的梧桐也已然凋残。被似雾的残烟笼罩。多么凄然的景象，远望江河关山，黯然的晚霞在落日馀晖里浮动。想当年，多愁善感的宋玉看到这晚秋是多么悲凉，曾经临水登山。千万里路途艰险，行路者是那么的凄惨哀楚，特别厌恶听到陇水潺潺的水声。这个时候，正在落葉中哀鸣的秋蝉和枯草中不停鸣叫的蟋蟀，此起彼伏地相互喧闹着。
在驿馆里形影单只，度日如年。秋风和露水都开始变得寒冷，在深夜时刻，胸中愁苦更甚。浩瀚的苍穹万里无云，清浅的银河中一轮皓月明亮。绵绵相思，长夜里对着如此的景色不堪忍受，掐指细算，回忆往昔。那时功名未就，却在歌楼妓院等游乐之所出入，一年年时光耗费。
美景无限的京城，让我想起了年少时光，每天衹想着寻欢作乐。况且那时还有很多狂怪的朋友相伴，遇到对酒当歌的场景就流连忘返。然而别离後，时光如梭，那些曾经的玩乐寻欢情景就好似梦境，前方一片烟雾渺茫。什么时候才能到岸？都是那些功名利禄害的我如此憔悴，将我羁绊。追忆过去，空留下残容愁颜。滴漏的箭头轻移，寒意微微，画角的呜咽之声从远方徐徐飘来，馀音袅袅。静对着窗户，把青灯熄灭等候黎明，形影单隻彻夜难眠。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749f34a8757d5a0d9d86", "shortContent": "柳永的《乐章集》以工于抒写行役羁旅见称。本词刻画驿馆的旅思，正是其长技之所在。据词里提到“宋玉悲感，向此临水与登山”诸语，可知作于湖北江陵。柳永外放荆南，已经年过五十。由于他爱同伶工乐妓交往，不为宋仁宗所喜，久不调职，难立于朝，只得外放州郡小官，心情是很郁闷的。这种情绪也深深地反映到词里来了。\n这首词是三片的长调。在结构上，作者以时间为线索，从傍晚、深夜直写到翌日破晓，脉络井井，有条不紊。先写凄清...", "authors": ["周笃文"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a7c6e67846a9219086", "shortContent": "柳永的《乐章集》以工于抒写行役羁旅见称。本词刻画驿馆的旅思，正是其长技之所在。据词里提到“宋玉悲感，向此临水与登山”诸语，可知作于湖北江陵。柳永外放荆南，已经年过五十。由于他爱同伶工乐妓交往，不为宋仁宗所喜，久不调职，难立于朝，只得外放州郡小官，心情是很郁闷的。这种情绪也深深地反映到词里来了。\n这首词是三片的长调。在结构上，作者以时间为线索，从傍晚、深夜直写到翌日破晓，脉络井井，有条不紊。先写凄清...", "authors": ["周笃文"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f39e6f69b71e93f6190", "shortContent": "《戚氏》是柳永首创的长调，在其《乐章集》中篇幅最长，收入“中吕调”。全词三叠，计二百一十二个字，字数上为北宋长调慢词之最，为词史上第二长词，仅次于南宋时吴文英的《莺啼序》。\n此词为三片的长调。结构上，以时间为线索，从傍晚、深夜直写至翌日破晓，脉络清晰，有条不紊。第一片抒发悲秋之感。晚秋时节，一阵微雨洒落在庭院的台轩。槛外菊花稀疏已残，井边梧桐凌乱飘飞，沾惹着一缕残黄枯冷的轻烟，情景凄然。这里是近景...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe47ccdb86c49f2917e", "shortContent": "《戚氏》是柳永首创的长调，在其《乐章集》中篇幅最长，收入“中吕调”。全词三叠，计二百一十二个字，字数上为北宋长调慢词之最，为词史上第二长词，仅次于南宋时吴文英的《莺啼序》。\n\n此词为三片的长调。结构上，以时间为线索，从傍晚、深夜直写至翌日破晓，脉络清晰，有条不紊。第一片抒发悲秋之感。晚秋时节，一阵微雨洒落在庭院的台轩。槛外菊花稀疏已残，井边梧桐凌乱飘飞，沾惹着一缕残黄枯冷的轻烟，情景凄然。这里是近...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d125c7af6de1647100d8a", "bookTitle": "柳永词鉴赏辞典", "articleId": "646d8f155fc8182fe9c3788d", "shortContent": "柳永的《乐章集》以工于抒写行役羁旅见称。本词刻画驿馆的旅思，正是其长技之所在。据词里提到“宋玉悲感，向此临水与登山”诸语，可知作于湖北江陵。柳永外放荆南，已经年过五十。由于他爱同伶工乐妓交往，不为宋仁宗所喜，久不调职，难立于朝，只得外放州郡小官，心情是很郁闷的。这种情绪也深深地反映到词里来了。\n\n这首词是三片的长调。在结构上，作者以时间为线索，从傍晚、深夜直写到翌日破晓，脉络井井，有条不紊。先写凄...", "authors": ["周笃文"], "pressName": "上海辞书出版社"}]', '王颐堂《碧鸡漫志》：《离骚》寂寞千载後，《戚氏》凄凉一曲终。', 'indent', 1418820508, '57b92cef8ac2470062e104f5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10780, '过秦楼', NULL, 44, 239, 2, 2, '周邦彦', NULL, 10111, '57ba6fafa34131005b0e18bd', '宋', 'ci', '词', 'http://baike.baidu.com/view/2805073.htm', '', '水浴清蟾，叶喧凉吹，巷陌马声初断。闲依露井，笑扑流萤，惹破画罗轻扇。人静夜久凭阑，愁不归眠，立残更箭。叹年华一瞬，人今千里，梦沉书远。
空见说鬓怯琼梳，容消金镜，渐懒趁时匀染。梅风地溽，虹雨苔滋，一架舞红都变。谁信无聊为伊，才减江淹，情伤荀倩。但明河影下，还看稀星数点。', '这是一首即景思人之作。词抒写怀人之痛，上片通过今昔对比，表现环境的凄凉寂寞，追念当初的欢乐情景，虚实相映。下片前前设想情人为思念自己而无心打扮，后几句写自己的钟情，用典贴切生动。全篇时空轮转，虚虚实实，意象纷繁，灵动多姿，全以一股深沉的情思驾驭，颇能令人动容。', '过秦楼：词牌名。调见《岳府雅词》，作者李甲。因词中有“曾过秦楼”句，遂取以为名。109字，前11句5平，后11句4平后9句是领字格。据《词谱》考证，周邦彦《片玉词》，后人把他的《选官子》词刻作《过秦楼》，各谱遂名周词《选官子》为仄韵《过秦楼》。但两体不一，不能将《过秦楼》调另分仄体韵。苏武慢：又名《选官子》、《选冠子》、《惜余春慢》、《仄韵过秦楼》。
清蟾：明月。
露井：没有覆盖的井。
笑扑流萤：扑捉萤火虫。
画罗轻扇：用有画饰的丝织品做的扇子。唐杜牧《秋夕》：“银烛秋光冷画屏，轻罗小扇扑流萤。”
凭阑：凭栏，身倚栏杆。
更箭：计时的铜壶滴中标有时间刻度的浮尺。
梦沉：梦灭没而消逝。
琼梳：饰以美玉的发梳。
金镜：铜镜。
趁时匀染：赶时髦而化妆打扮。
梅风：梅子成熟季节的风。
溽（rù）：湿润。
虹雨：初夏时节的雨。
舞红：指落花。
才减江淹：相传江淹少时梦人授五色笔而文思大进，而后梦郭璞取其笔，才思竭尽。即后世所称“江郎才尽”。
情伤荀倩：荀粲，字奉倩。其妻曹氏亡，荀叹曰：“佳人难再得!”不哭而神伤，未几亦亡。', '圆圆的明月，倒映在清澈的池塘里，像是在尽情沐浴。树叶在风中簌簌作响，街巷中车马不再喧闹。我和她悠闲地倚着井栏，她嬉笑着扑打飞来飞去的流萤，弄坏了轻罗画扇。夜已深，人已静，我久久地凭栏凝思，往昔的欢聚，如今的孤伶，更使我愁思绵绵，不想回房，也难以成眠，直站到更漏将残。可叹青春年华，转眼即逝，如今你我天各一方相距千里，不说音信稀少，连梦也难做!
听说她相思恹恹，害怕玉梳将鬓发拢得稀散，面容消瘦而不照金镜，渐渐地懒于赶时髦梳妆打扮。眼前正是梅雨季节，潮风湿雨，青苔滋生，满架迎风摇动的蔷薇已由盛开时的艳红夺目，变得零落凋残。有谁会相信百无聊赖的我，像才尽的江淹，无心写诗赋词，又像是伤情的荀倩，哀伤不已，这一切都是由于对你热切的思念!举目望长空，只见银河茫茫，还有几颗稀疏的星星，点点闪闪。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74c5d635634aee3d7213", "shortContent": "这是一首怀人的词。\n上片“人静夜久凭阑，愁不归眠，立残更箭”是全词的关键。周济说：“美成思力，独绝千古。”又说：“勾勒之妙，无如清真；他人一勾勒便薄，清真愈勾勒愈浑厚。”（《介存斋论词杂著》）这三句勾勒极妙，上面好像是写现在的六句词，经这几句的勾勒，变成了忆旧。在一个夏天的晚上，词人独倚阑干，凭高念远，离绪万端，难以归睡。由黄昏而至深夜，由深夜而至天将晓，耳听更鼓将歇，但他依旧倚栏望着，想着离别已...", "authors": ["万云骏"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5cb7d0ac1145495e8c5", "shortContent": "这是一首怀人的词。\n上片“人静夜久凭阑，愁不归眠，立残更箭”是全词的关键。周济说：“美成思力，独绝千古。”又说：“勾勒之妙，无如清真；他人一勾勒便薄，清真愈勾勒愈浑厚。”（《介存斋论词杂著》）这三句勾勒极妙，上面好像是写现在的六句词，经这几句的勾勒，变成了忆旧。在一个夏天的晚上，词人独倚阑干，凭高念远，离绪万端，难以归睡。由黄昏而至深夜，由深夜而至天将晓，耳听更鼓将歇，但他依旧倚栏望着，想着离别已...", "authors": ["万云骏"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f44c9ebcc6fbea1a2c3", "shortContent": "这是一首伤春怀人的词。上片由景而情。“水浴清蟾”三句写此时的环境：水面映着圆月，仿佛月亮在水中沐浴。凉风吹拂，树叶沙沙作响，街巷中的车马声渐渐消歇。“闲依露井”三句，思绪回到从前：词人所思念的女子，悠闲地依在井栏边，笑着扑打空中飞舞的萤火虫，弄破了轻罗小扇。这个生活细节，充满情趣，写活了当日的甜蜜生活。\n“人静夜久凭阑”三句写实，视线再度回到当下，词人倚栏远眺，久久伫立在夜色中，愁情满怀，迟迟不肯...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "631270359761253910e904f3", "shortContent": "这是一首伤春怀人的词。上片由景而情。“水浴清蟾”三句写此时的环境：水面映着圆月，仿佛月亮在水中沐浴。凉风吹拂，树叶沙沙作响，街巷中的车马声渐渐消歇。“闲依露井”三句，思绪回到从前：词人所思念的女子，悠闲地依在井栏边，笑着扑打空中飞舞的萤火虫，弄破了轻罗小扇。这个生活细节，充满情趣，写活了当日的甜蜜生活。\n\n“人静夜久凭阑”三句写实，视线再度回到当下，词人倚栏远眺，久久伫立在夜色中，愁情满怀，迟迟不...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "645d152a7af6de1647101bdf", "bookTitle": "周邦彦词鉴赏辞典", "articleId": "6469bf435e6bb82b8cd90042", "shortContent": "这是一首怀人的词。上片“人静夜久凭阑，愁不归眠，立残更箭”是全词的关键。周济说：“美成思力，独绝千古。”又说：“勾勒之妙，无如清真；他人一勾勒便薄，清真愈勾勒愈浑厚。”（《介存斋论词杂著》）这三句勾勒极妙，上面好像是写现在的六句词，经这几句的勾勒，变成了忆旧。在一个夏天的晚上，词人独倚阑干，凭高念远，离绪万端，难以归睡。由黄昏而至深夜，由深夜而至天将晓，耳听更鼓将歇，但他依旧倚栏望着，想着离别已久...", "authors": ["万云骏"], "pressName": "上海辞书出版社"}]', '陈洵《海绡翁说词稿》：篇法之妙，不可思议。', 'indent', 1418929392, '57b94b638ac2470062e21b30', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639338, '水浒传 · 第七十回 · 没羽箭飞石打英雄 宋公明弃粮擒壮士', NULL, 0, 124, 0, 1, '施耐庵', NULL, 10333, '57b9ebb3a633bd005d30998b', '明', 'wen', '文', '', '', '诗曰：
龙虎山中降敕宣，锁魔殿上散霄烟。
致令煞曜离金阙，故使罡星下九天。
战马频嘶杨柳岸，征旗布满藕花船。
只因肝胆存忠义，留得清名万古传。
话说宋江打了东平府，收军回到安山镇，正待要回山寨，只见白胜前来报说：“卢俊义去打东昌府，连输了两阵。城中有个猛将，姓张名清，原是彰德府人，虎骑出身，善会飞石打人，百发百中，人呼为没羽箭。手下两员副将：一个唤做花项虎龚旺，浑身上刺着虎斑，脖项上吞着虎头，马上会使飞枪；一个唤做中箭虎丁得孙，面颊连项都有疤痕，马上会使飞叉。卢员外提兵临境，一连十日，不出厮杀。前日张清出城交锋，郝思文出马迎敌，战无数合，张清便走，郝思文赶去，被他额角上打中一石子，跌下马来。却得燕青一弩箭，射中张清战马，因此救得郝思文性命。输了一阵。次日，混世魔王樊瑞引项充、李衮，舞牌去迎，不期被丁得孙从肋窝里飞出标叉，正中项充。因此又输了一阵。二人见在船中养病。军师特令小弟来请哥哥早去救应。”宋江见说了，叹曰：“卢俊义直如此无缘！特地教吴学究、公孙胜帮他，只想要他见阵成功，山寨中也好眉目，谁想又逢敌手。既然如此，我等众弟兄引兵都去救应。”当时传令，便起三军。诸将上马，跟随宋江直到东昌境界。卢俊义等接着，具说前事，权且下寨。
正商议间，小军来报：“没羽箭张清搦战。”宋江领众便起，向平川旷野摆开阵势。大小头领一齐上马，随到门旗下。宋江在马上看对阵时，阵排一字，旗分五色。三通鼓罢，没羽箭张清出马。怎生打扮？有一篇《水调歌》，赞张清的英勇：
头巾掩映茜红缨，狼腰猿臂体彪形。锦衣绣袄，袍中微露透深青。雕鞍侧坐，青玉勒马轻迎。葵花宝镫，振响熟铜铃。倒拖雉尾，飞走四蹄轻。金环摇动，飘飘玉蟒撒朱缨。锦袋石子，轻轻飞动似流星。不用强弓硬弩，何须打弹飞铃。但着处，命归空。东昌马骑将，没羽箭张清。
宋江在门旗下见了喝采。张清在马上荡起征尘，往来驰走。门旗左边闪出那个花项虎龚旺。有诗为证：
手执标枪惯飞舞，盖世英雄诚未睹。
斑烂锦体兽吞头，龚旺名为花项虎。
又见张清阵内门旗影里，右边闪出这个中箭虎丁得孙。亦有诗为证：
虎骑奔波出阵门，双腮连项露疤痕。
到处人称中箭虎，手搦飞叉丁得孙。
三骑马来到阵前。张清手指宋江骂道：“水洼草贼，愿决一阵！”宋江问道：“谁可去战张清？”傍边恼犯这个英雄，忿怒跃马，手舞钩镰枪，出到阵前。宋江看时，乃是金枪手徐宁。宋江暗喜，便道：“此人正是对手！”徐宁飞马直取张清，两马相交，双枪并举。斗不到五合，张清便走，徐宁去赶。张清把左手虚提长枪，右手便向锦袋中摸出石子，扭回身，觑得徐宁面门较近，只一石子，可怜悍勇徐宁，石子眉心早中，翻身落马。龚旺、丁得孙便来捉人。宋江阵上人多，早有吕方、郭盛，两骑马，两枝戟，救回本阵。宋江等大惊，尽皆失色。再问：“那个头领接着厮杀？”宋江言未尽，马后一将飞出。看时，却是锦毛虎燕顺。宋江却待阻当，那骑马已自去了。燕顺接住张清，斗无数合，遮拦不住，拨回马便走。张清望后赶来，手取石子，看燕顺后心一掷，打在镗甲护镜上，铮然有声，伏鞍而走。宋江阵上一人大叫：“匹夫何足惧哉！”拍马提槊飞出阵去。宋江看时，乃是百胜将韩滔，不打话便战张清。两马方交，喊声大举。韩滔要在宋江面前显能，抖擞精神，大战张清。不到十合，张清便走。韩滔疑他飞石打来，不去追赶。张清回头不见赶来，翻身勒马便转。韩滔却待挺槊来迎，被张清暗藏石子，手起，望韩滔鼻凹里打中。只见鲜血迸流，逃回本阵。彭玘见了大怒，“量这等小辈，何足惧哉！”不等宋公明将令，手舞三尖两刃刀，飞马直取张清。两个未曾交马，被张清暗藏石子在手，手起，正中彭玘面额，丢了三尖两刃刀，奔马回阵。
宋江见输了数将，心内惊惶，便要将军马收转。只见卢俊义背后一人大叫：“今日将威折了，来日怎地厮杀！且看石子打得我么！”宋江看时，乃是丑郡马宣赞，拍马舞刀，直奔张清。张清便道：“一个来，一个走！两个来，两个逃！你知我飞石手段么？”宣赞道：“你打得别人，怎近得我！”说言未了，张清手起一石子，正中宣赞嘴边，翻身落马。龚旺、丁得孙却待来捉，怎当宋江阵上人多，众将救了回阵。
宋江见了，怒气在心，掣剑在手，割袍为誓：“我若不拿得此人，誓不回军！”呼延灼见宋江说誓，便道：“兄长此言，要我们弟兄何用！”就拍踢雪乌骓，直临阵前，大骂张清：“小儿得宠，一力一勇！认得大将呼延灼么？”张清便道：“辱国败将之人，也遭我毒手！”言未绝，一石子飞来。呼延灼见石子飞来，急把鞭来隔时，却中在手腕上。早着一下，便使不动钢鞭，回归本阵。
宋江道：“马军头领，都被损伤。步军头领，谁敢捉这张清？”只见部下刘唐手拈朴刀，挺身出阵。张清见了大笑，骂道：“你那败将，马军尚且输了，何况步卒！”刘唐大怒，径奔张清。张清不战，跑马归阵。刘唐赶去，人马相迎。刘唐手疾，一朴刀砍去，却砍着张清战马。那马后蹄直踢起来，刘唐面门上扫着马尾，双眼生花，早被张清只一石子，打倒在地。急待挣扎，阵中走出军来，横拖倒拽，拿入阵中去了。宋江大叫：“那个去救刘唐？”只见青面兽杨志便舞刀直取张清。张清虚把枪来迎。杨志一刀刺去，张清镫里藏身，杨志却砍了个空。张清手拿石子，喝声道：“着！”石子从肋罗里飞将过去。张清又一石子，铮的打在盔上，吓得杨志胆丧心寒，伏鞍归阵。宋江看了，转转寻思：“若是今番输了锐气，怎生回梁山泊！谁与我出得这口气？”朱仝听得，目视雷横说道：“捉了刘唐去，却值甚的！一个不济事，我两个同去夹攻。”朱仝居左，雷横居右，两条朴刀，杀出阵前。张清笑道：“一个不济，又添一个！由你十个，更待如何！”全无惧色。在马上藏两个石子在手。雷横先到，张清手起，势如招宝七郎，石子来时，面门上怎生躲避，急待抬头看时，额上早中一石子，扑然倒地。朱仝急来快救，脖项上又一石子打着。关胜在阵上看见中伤，大挺神威，轮起青龙刀，纵开赤兔马，来救朱仝、雷横。刚抢得两个奔走还阵，张清又一石子打来。关胜急把刀一隔，正打着刀口，迸出火光。关胜无心恋战，勒马便回。
双枪将董平见了，心中暗忖：“吾今新降宋江，若不显我些武艺，上山去必无光彩。”手提双枪，飞马出阵。张清看见，大骂董平：“我和你邻近州府，唇齿之邦，共同灭贼，正当其理。你今缘何反背朝廷？岂不自羞！”董平大怒，直取张清。两马相交，军器并举。两条枪阵上交加，四双臂环中撩乱。约斗五七合，张清拨马便走。董平道：“别人中你石子，怎近得我！”张清带住枪杆，去锦袋中摸出一个石子，手起处真如流星掣电，石子来吓得鬼哭神惊。董平眼明手快，拨过了石子。张清见打不着，再取第二个石子，又打将去，董平又闪过了。两个石子打不着，张清却早心慌。那马尾相衔，张清走到阵门左侧，董平望后心刺一枪来。张清一闪，镫里藏身，董平却搠了空，那条枪却搠将过来。董平的马和张清的马两厮并着。张清便撇了枪，双手把董平和枪连臂膊只一拖，却拖不动。两个搅做一块。宋江阵上索超望见，轮动大斧，便来解救。对阵龚旺、丁得孙两骑马齐出，截住索超厮杀。张清、董平又分拆不开。索超、龚旺、丁得孙三匹马搅做一团。林冲、花荣、吕方、郭盛四将，一齐尽出，两条枪、两枝戟来救董平、索超。张清见不是头，弃了董平，跑马入阵。董平不舍，直撞入去，却忘了提备石子。张清见董平追来，暗藏石子在手，待他马近，喝声道：“着！”董平急躲，那石子抹耳根上擦过去了。董平便回。索超撇了龚旺、丁得孙，也赶入阵来。张清停住枪，轻取石子，望索超打来。索超急躲不迭，打在脸上。鲜血迸流，提斧回阵。
却说林冲、花荣把龚旺截住在一边，吕方、郭盛把丁得孙也截住在一边。龚旺心慌，便把飞枪摽将来，却摽不着花荣、林冲。龚旺先没了军器，被林冲、花荣活捉归阵。这边丁得孙不敢弃叉，死命抵敌吕方、郭盛，不提防浪子燕青在阵门里看见，暗忖道：“我这里被他片时连打了一十五员大将！”手中弃了杆棒，身边取出弩弓，搭上弦，放一箭去，一声响，正中了丁得孙马蹄，那马便倒，却被吕方、郭盛捉过阵来。张清要来救时，寡不敌众，只得拿了刘唐，且回东昌府去。太守在城上看见张清前后打了梁山泊一十五员大将，虽然折了龚旺、丁得孙，也拿得这个刘唐。回到州衙，先把刘唐长枷送狱，却再商议。
张清神手拨天关，暗里能将石子攀。
一十五人都打坏，脚瘸手跛奔梁山。
且说宋江收军回寨，把龚旺、丁得孙先送上梁山泊。宋江再与卢俊义、吴用道：“我闻五代时，大梁王彦章，日不移影，连打唐将三十六员。今日张清无一时连打我一十五员大将，真是不在此人之下，也当是个猛将。”众人无语。宋江又道：“我看此人，全仗龚旺、丁得孙为羽翼。如今手足羽翼被擒，可用良策捉获此人。”吴用道：“兄长放心。小生见了此将出没，已自安排定了。虽然如此，且把中伤头领送回山寨，却教鲁智深、武松、孙立、黄信、李立，尽数引领水军，安排车仗船只，水陆并进，船骑相迎，赚出张清，便成大事。”吴用分拨已定。
再说张清在城内与太守商议道：“虽是赢得，贼势根本未除，暗使人去探听虚实，却作道理。”只见探事人来回报：“寨后西北上，不知那里将许多粮米，有百十辆车子，河内又有粮草船，大小约有五百余只。水陆并进，船马同来。沿路有几头领监管。”太守道：“这厮们莫非有计？恐遭他毒手。再差人去打听，端的果是粮草也不是。”次日，小军回报说：“车上都是粮，尚且撒下米来。水中船只，虽是遮盖着，尽有米布袋露出将来。”张清道：“今晚出城，先截岸上车子，后去取他水中船只。太守助战，一鼓而得。”太守道：“此计甚妙，只可善觑方便。”叫军汉饱餐酒食，尽行披挂，捎驮锦袋。张清手执长枪，引一千军兵，悄悄地出城。
是夜月色微明，星光满天。行不到十里，望见一簇车子，旗上明写“水浒寨忠义粮”。张清看了，见鲁智深担着禅杖，皂直裰拽扎起来，当头先走。张清道：“这秃驴脑袋上着我一下石子！”鲁智深担着禅杖，此时自望见了，只做不知，大踏步只顾走，却忘了提防他石子。正走之间，张清在马上喝声：“着！”一石子正飞在鲁智深头上，打得鲜血迸流，望后便倒。张清军马一齐呐喊，都抢将来。武松急挺两口戒刀，死去救回鲁智深，撇了粮车便走。张清夺得粮车，见果是粮米，心中欢喜，不来追赶鲁智深，且押送粮车，推入城来。太守见了大喜，自行收管。张清道：“再抢河中粮船。”太守道：“将军善觑方便。”张清上马，转到南门。此时望见河港内粮船不计其数。张清便叫开城门，一齐呐喊，抢到河边。只见阴云布满，黑雾遮天，马步军兵回头看时，你我对面不见。此是公孙胜行持道法。张清看见，心慌眼暗，却待要回，进退无路。四下里喊声乱起，正不知军兵从那里来。林冲引铁骑军兵，将张清连人和马都赶下水去了。河内却是李俊、张横、张顺、三阮、两童八个水军头领，一字儿摆在那里。张清便有三头六臂，也怎生挣扎得脱。被阮氏三雄捉住，绳缠索绑，送入寨中。水军头领飞报宋江。
吴用便催大小头领连夜打城。太守独自一个怎生支持得住。听得城外四面炮响，城门开了，吓得太守无路可逃。宋江军马杀入城中，先救了刘唐。次后便开仓库，就将钱粮一分发送梁山泊，一分给散居民。太守平日清廉，饶了不杀。
宋江等都在州衙里聚集，众人会面。只见水军头领早把张清解来。众多兄弟都被他打伤，咬牙切齿，尽要来杀张清。宋江见解将来，亲自直下堂阶迎接，便陪话道：“误犯虎威，请勿挂意。”邀上厅来。说言未了，只见阶下鲁智深，使手帕包着头，拿着铁禅杖，径奔来要打张清。宋江隔住，连声喝退：“怎肯教你下手！”张清见宋江如此义气，叩头下拜受降。宋江取酒奠地，折箭为誓：“众弟兄若要如此报仇，皇天不祐，死于刀剑之下。”众人听了，谁敢再言。也是天罡星合当聚会，自然义气相投。昔日老郎有一篇言语，赞张清道：
祖代英雄播英武，义胆忠肝咸若古。
披坚自可为干城，佐郡应须是公辅。
东昌骁将名张清，豪气凌霄真可数。
阵云冉冉飘征旗，劲气英英若痴虎。
龙鳞铁甲披凤毛，宫锦花袍明绣补。
坐骑一匹大宛驹，袖中暗器真难睹。
非鞭非简亦非枪，阵上陨石如星舞。
飞来猛将不能逃，中处应令倒旗鼓。
感人义气成大恩，此日归心甘受虏。
天降罡星大泊中，烨烨英声传水浒。
宋江在东昌府州衙堂上折箭盟誓已罢，“众弟兄勿得伤情！”众皆大笑，人各听令，尽皆欢喜。收拾军马，都要回山。只见张清在宋公明面前举荐：“东昌府一个兽医，复姓皇甫，名端。此人善能相马，知得头口寒暑病症，下药用针，无不痊可，真有伯乐之才。原是幽州人氏。为他碧眼黄须，貌若番人，以此人称为紫髯伯。梁山泊亦有用他处。可唤此人带引妻小，一同上山。乞取钧旨。”宋江闻言大喜：“我虽在中原，不晓其理。若果皇甫端肯去相聚，大称予怀。”张清见宋江相爱甚厚，随即便去唤到兽医皇甫端来，拜见宋江并众头领。大小众将看了，尽皆欢喜。有篇七言古风诗，道皇甫端医术：
传家艺术无人敌，安骥年来有神力。
回生起死妙难言，拯惫扶危更多益。
鄂公乌骓人尽夸，郭公駬来渥洼。
吐蕃枣骝号神驳，北地又羡拳毛。
驣骧駝皆经见，衔橛背鞍亦多变。
天闲十二旧驰名，手到病除能应验。
古人已往名不刊，只今又见皇甫端。
解治四百零八病，双瞳炯炯珠走盘。
天集忠良真有意，张清鹗荐诚良计。
梁山泊内添一人，号名紫髯伯乐裔。
宋江看了皇甫一表非俗，碧眼重瞳，虬须过腹。皇甫端见了宋江如此义气，心中甚喜，愿从大义。宋江大喜。
抚谕已了，传下号令，诸多头领，收拾车仗、粮食、金银，一齐进发。鞍上将鞭敲金镫响，步下卒齐唱凯歌声。把这两府钱粮，运回山寨。前后诸军都起，于路无话。早回到梁山泊忠义堂上。宋江叫放出龚旺、丁得孙来，亦用好言抚慰。二人叩首拜降。又添了皇甫端，在山寨专工医兽。董平、张清亦为山寨头领。宋江欢喜，忙叫排宴庆贺。都在忠义堂上，各依次席而坐。宋江看了众多头领，却好一百单八员。宋江开言说道：“我等弟兄，自从上山相聚，但到处并无疏失，皆是上天护佑，非人之能。今来扶我为尊，皆托众弟兄英勇。一者合当聚义，二乃我再有句言语，烦你众兄弟共听。”吴用便道：“愿请兄长约束，共听号令。”
宋江对着众头领，开口说这个主意下来。正是，有分教：三十六天罡临化地，七十二地煞闹中原。毕竟宋公明说出甚么主意，且听下回分解。', '', '', '', NULL, '', 'indent', 1537289264, '5ba0b7da570c3500638aa9b1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10719, '夜半乐', NULL, 62, 225, 2, 1, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/view/2792344.htm', '', '冻云黯淡天气，扁舟一叶，乘兴离江渚。渡万壑千岩，越溪深处。怒涛渐息，樵风乍起，更闻商旅相呼。片帆高举，泛画鹢、翩翩过南浦。
望中酒旆闪闪，一簇烟村，数行霜树。残日下、渔人鸣榔归去。败荷零落，衰杨掩映，岸边两两三三，浣纱游女，避行客、含羞笑相语。
到此因念，绣阁轻抛，浪萍难驻。叹后约丁宁竟何据？惨离怀、空恨岁晚归期阻。凝泪眼、杳杳神京路，断鸿声远长天暮。', '这首词描写旅途所见风光景色，抒发去国怀乡的愁思哀情。上阕写泛舟离江浦之景。冷云阴沉天气寒，驾一叶小舟，乘着游兴离开了沙洲江岸。越过了万道深壑、千道高岩，浣纱溪幽深的水湾。狂涛渐渐平息、山风突然刮起，还听到商贾旅客互相呼唤。一片征帆高悬，航船浮游，轻悠悠驶过南岸。
中阕写途中所历渔村黄昏物象。一面酒旗飘飘闪闪，一座烟雾团簇的村落，几行树霜花斑斑。夕阳残照下，归家的渔人挥棒敲响船舷。枯败的荷花零落了，晚霞透过衰残的杨柳忽掩忽现。岸边三三两两，浣洗衣物的姑娘，躲避着游客的窥探，含羞带笑悄语娇憨。
下阕抒去国情怀，恨岁晚，凝泪眼、离思、凄婉，长天断鸿，景中有比，馀韵不尽。全词前两阕以写景为主，景中寓情，末阕以抒情为主，情寄于景。写景笔意简洁明快，抒情笔意沉着抑郁，以明快的美景铺垫、蓄势，推宕出沉郁的哀情。首尾景语遥映，以「黯淡」始，以「断鸿」终，游宦离恨之意脉如草蛇灰线遥接远注，使铺叙曲折完整。', '夜半乐：唐教坊曲，后用为词牌。《乐章集》入「中吕调」。段安节《乐府杂录》：「明皇自潞州入平内难，半夜斩长乐门关，领兵入宫剪逆人，后撰此曲，名《还京乐》。」又有谓《夜半乐》与《还京乐》为二曲者。常以柳永词为准。一百四十四字，分三段，前段、中段四仄韵，后段五仄韵。前段第四句是上一、下四句式。全曲格局开展，中段雍容不迫，后段声拍促数。
冻云：冬天浓重聚积的云。扁舟：小船。乘兴离江渚：自己乘兴离开了江边。江渚：江边。渚：水中沙洲，此指水边。
万壑千岩：出自《世说新语·言语》：顾恺之自会稽归来，盛赞那里的山川之美，说：」千岩竞秀，万壑争流。「这里指千山万水。越溪：特指会稽山南之若耶溪。
樵风：指顺风。乍起：指山风突然的吹起来。商旅：行商之旅客，这里泛指旅客。
画鹢（yì）：船其首画鹢鸟者，以图吉利。鹢是古书上说的一种水鸟，不怕风暴，善于飞翔。这里以「画鹢」代指舟船。翩翩：形容穿行轻快的样子。南浦：南岸的水边，泛指水滨。
望中：在视野里。酒旆：酒店用来招引顾客的旗幌。一簇烟村：一处冒着炊烟的村庄。
鸣榔：用木长棒敲击船舷。渔人有时用他敲船，使鱼受惊入网；有时用它敲船以为唱歌的节拍，这里用后者，即渔人唱着渔歌回家。
浣纱游女：水边洗衣劳作的农家女子。
因：这里是」于是「，」就「的意思。绣阁轻抛：轻易抛弃了偎红倚翠的生活。浪萍难驻：漂泊漫游如浪中浮萍一样行踪无定。
后约：约定以后相见的日期。
丁宁：同「叮咛」，临别郑重嘱咐。
何据：有什么根据，是说临别时相互的约定、嘱咐都不可靠，都无法实现。
空恨：徒恨。
杳杳：遥远的意思。
神京：指都城汴京。
断鸿：失群的孤雁。
长天暮：远天出现茫茫暮色。', '严冬的阴云遮蔽着天空，我乘坐一叶小小扁舟，乘兴离开了沙洲的江岸。越过万道深壑千道高岩，进入若耶溪幽深的水湾，狂涛渐渐将要平息下去，山风却又突然刮起了风来，听到商贾旅客互相呼唤。一片征帆高悬航船浮游、轻轻悠悠地驶过了南岸。
放眼望去远处酒旗晃动，一座烟笼村落霜花斑斑。夕阳残照渔人敲响船舷。枯败的荷花都纷纷零落，晚霞透过杨柳忽掩忽现。岸边两三三浣纱姑娘，躲避着游客羞涩地笑语。
猛想到轻易地抛弃亲人，像浪游的浮萍难寻立身。可叹约会誓言怎能为据？惨淡啊那些离别的情怀，徒叹又将岁暮归期受阻。泪眼凝神远看京都大路，孤雁远远呼唤长空暮色。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749f5e272d4b2253ba16", "shortContent": "柳永词“工于羁旅行役”（陈振孙《直斋书录解题》卷二十一《乐章集》解题），“善于叙事”（刘熙载《艺概》卷四《词曲概》）。《夜半乐》之值得重视，正因为它体现了柳词的这一基本特色。\n全词分为三叠。第一叠叙述舟行的经历，第二叠描写舟中的见闻，都是写景；第三叠发抒感慨，是写情。首叠中的“越溪”，特指会稽县南之若耶溪，非泛指越地的河流。“万壑千岩”出于《世说新语·任诞篇》。晋人顾恺之称赞会稽（今浙江绍兴）的山...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a72e6a6b501f967281", "shortContent": "柳永词“工于羁旅行役”（陈振孙《直斋书录解题》卷二十一《乐章集》解题），“善于叙事”（刘熙载《艺概》卷四《词曲概》）。《夜半乐》之值得重视，正因为它体现了柳词的这一基本特色。\n全词分为三叠。第一叠叙述舟行的经历，第二叠描写舟中的见闻，都是写景；第三叠发抒感慨，是写情。首叠中的“越溪”，特指会稽县南之若耶溪，非泛指越地的河流。“万壑千岩”出于《世说新语·任诞篇》。晋人顾恺之称赞会稽（今浙江绍兴）的山...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252ccce4d48ba496d7f", "shortContent": "柳永词“工于羁旅行役”（陈振孙《直斋书录解题》卷二十一《乐章集》解题），“善于叙事”（刘熙载《艺概》卷四《词曲概》）。《夜半乐》之值得重视，正因为它体现了柳词的这一基本特色。\n\n全词分为三叠。第一叠叙述舟行的经历，第二叠描写舟中的见闻，都是写景；第三叠发抒感慨，是写情。首叠中的“越溪”，特指会稽县南之若耶溪，非泛指越地的河流。“万壑千岩”出于《世说新语·任诞篇》。晋人顾恺之称赞会稽（今浙江绍兴）的...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f39e6f69b71e93f6191", "shortContent": "“冻云黯淡天气，扁舟一叶，乘兴离江渚。”“冻云”指冬天聚拢的浓重的云。这里开头点明时间、地点，词人出发了。虽然在这暗淡的背景下，但是词人的游兴却很浓。从这里开始，词人一段一段写下去，由此铺陈开来。离开江边，渡过了万壑千岩，经过了越溪深处，让人不由感觉到“轻舟已过万重山”的轻快，看来词人游历了很长的一段路程。然后到了比较开阔的江面上，这时候，“怒涛渐息，樵风乍起”，浪涛渐渐变小了，吹起了顺风，听到有...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe47ccdb86c49f2917f", "shortContent": "“冻云黯淡天气，扁舟一叶，乘兴离江渚。”“冻云”指冬天聚拢的浓重的云。这里开头点明时间、地点，词人出发了。虽然在这暗淡的背景下，但是词人的游兴却很浓。从这里开始，词人一段一段写下去，由此铺陈开来。离开江边，渡过了万壑千岩，经过了越溪深处，让人不由感觉到“轻舟已过万重山”的轻快，看来词人游历了很长的一段路程。然后到了比较开阔的江面上，这时候，“怒涛渐息，樵风乍起”，浪涛渐渐变小了，吹起了顺风，听到有...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d125c7af6de1647100d8a", "bookTitle": "柳永词鉴赏辞典", "articleId": "646d8f68902ee364cc82b820", "shortContent": "柳永词“工于羁旅行役”（陈振孙《直斋书录解题》卷二十一《乐章集》解题），“善于叙事”（刘熙载《艺概》卷四《词曲概》）。《夜半乐》之值得重视，正因为它体现了柳词的这一基本特色。\n\n全词分为三叠。第一叠叙述舟行的经历；第二叠描写舟中的见闻，都是写景；第三叠发抒感慨，是写情。首叠中的“越溪”，特指会稽县南之若耶溪，非泛指越地的河流。“万壑千岩”出于《世说新语·任诞篇》。晋人顾恺之称赞会稽（今浙江绍兴）的...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}]', '', 'indent', 1418820555, '57ba057d2e958a006934d87d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10720, '玉蝴蝶 · 望处雨收云断', NULL, 285, 225, 3, 3, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/item/玉蝴蝶·望处雨收云断?sefr=enterbtn', '', '望处雨收云断，凭栏悄悄，目送秋光。晚景萧疏，堪动宋玉悲凉。水风轻、蘋花渐老；月露冷、梧叶飘黄。遣情伤，故人何在？烟水茫茫。
难忘，文期酒会，几孤风月，屡变星霜。海阔山遥，未知何处是潇湘？念双燕、难凭远信；指暮天、空识归航。黯相望，断鸿声里，立尽斜阳。', '柳永《玉蝴蝶》一词，风格与其《八声甘州》相近，它通过描绘萧疏清幽的秋景，来抒写对朋友的思念之情。上阕写景。以水风、蘋花、月露、梧叶诸意象组合成一幅暮秋萧瑟景象，而借轻、老、冷、黄点染暮秋孤寂冷清气氛。下阕回忆。难忘「文期酒会」，乃指词人与狂朋怪侣的秦楼欢宴之放浪生活，而辜负「风月」乃指良辰美景与佳人欢会。而今与旧日恋人「海阔山遥」，欲寻无踪：「何处是潇湘」用「潇湘」指代娥皇、女英，以隐喻词人旧日恋人，抒發别离之苦。復以「双燕」意象反衬自身劳燕分飞，难托音信；「归航」意象显现遥望江天，归舟渺渺的失落和惆怅。最後「黯相望」以景结情，用「断鸿」意象隐喻自身离群独处、哀吟凄厉；借「斜阳」寄托黄昏寂寞时怀念故人的无尽情思，给人以无穷意韵的回味。这首词俗中有雅，平中见奇，隽永有味，故能雅俗共赏。', '玉蝴蝶：词牌名。此调有小令及长调两体，小令为唐温庭筠所创，双调，上阕四句，押三平韵，二十一字；下阕四句，押三平韵，二十字，共四十一字。长调始于宋人柳永，又称为《玉蝴蝶慢》，双调，九十九字，平韵。亦有九十八字体。
雨收云断：雨停云散。
萧疏：清冷疏散，稀稀落落。堪：可以。
宋玉悲凉：指宋玉《九辩》，引申为悲秋。宋玉《九辩》有「悲哉！秋之为气也，萧瑟兮草木摇落而变衰！」
蘋花：一种夏秋间开小白花的浮萍。
遣情伤：令人伤感。遣，使得。
文期酒会：文人们相约饮酒赋诗的聚会。期，约。
几孤风月：辜负了多少美好的风光景色。几，多少回；孤，通「辜」，辜负；风月，美好的风光景色。
屡变星霜：经过了好几年。星霜，星一年一周天，霜每年而降，因称一年为一星霜，亦以之喻年月也。
潇湘：湘江的别称。这里指所思念的人居住的地方。
暮天：傍晚时分。
空：白白地。
归航：返航的船。
立尽斜阳：在傍晚西斜的太阳下立了很久，直到太阳落山。', '我悄悄地倚栏凝望，雨已停歇，云已散去，目送着秋色消逝于天边。秋天的傍晚，景色萧瑟凄凉，真让人兴發宋玉悲秋之叹。轻风拂过水面，白蘋花渐渐衰残，凉月使露水凝住，梧桐树也禁不住月夜寒露的侵袭，叶子已片片枯黄。此情此景，不由人寂寞感伤。我的故朋旧友，不知你们都在何方？眼前所见只有一望无际的秋水，烟雾迷茫。
文人的雅集，纵情的欢宴，如今仍历历在目，令人难忘。离别後辜负了多少风月时光，斗转星移，都只为你我相距遥远，天各一方。相隔如此之遥，相逢相会不知何处何年？让人感到凄苦彷徨。想那双双飞去的燕子，难以靠它给故友传音送信；企盼故友归来，遥指天际苍茫，辨识归来航船，谁知过尽千帆皆不是，也是枉自空等企望。我默默伫立，黯然相望，只见斜阳已尽，孤雁哀鸣声仍在天际飘荡。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e749f7d0ac1145494bb2b", "shortContent": "柳永《玉蝴蝶》一词，风格与其《八声甘州》相近，它通过描绘萧疏、清幽的秋景，来抒写对朋友的思念之情。\n起句以写景入题。“望处雨收云断”，是写即目所见之景，可以看出远处天边风云变幻的痕迹，使清秋之景，显得更加疏朗。“凭阑悄悄”四字，写出了独自倚阑远望时的忧思。这种情怀，又落脚到“目送秋光”上。“悄悄”，忧愁的样子。《诗·邺风·柏舟》：“忧心悄悄。”后来辛弃疾《踏莎行》词云：“吾道悠悠，忧心悄悄，最无聊...", "authors": ["刘文忠"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a703572034f65a8b0e", "shortContent": "柳永《玉蝴蝶》一词，风格与其《八声甘州》相近，它通过描绘萧疏、清幽的秋景，来抒写对朋友的思念之情。\n起句以写景入题。“望处雨收云断”，是写即目所见之景，可以看出远处天边风云变幻的痕迹，使清秋之景，显得更加疏朗。“凭阑悄悄”四字，写出了独自倚阑远望时的忧思。这种情怀，又落脚到“目送秋光”上。“悄悄”，忧愁的样子。《诗·邺风·柏舟》：“忧心悄悄。”后来辛弃疾《踏莎行》词云：“吾道悠悠，忧心悄悄，最无聊...", "authors": ["刘文忠"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059252ccce4d48ba496d82", "shortContent": "柳永《玉蝴蝶》一词，风格与其《八声甘州》相近，它通过描绘萧疏、清幽的秋景，来抒写对朋友的思念之情。\n\n起句以写景入题。“望处雨收云断”，是写即目所见之景，可以看出远处天边风云变幻的痕迹，使清秋之景，显得更加疏朗。“凭阑悄悄”四字，写出了独自倚阑远望时的忧思。这种情怀，又落脚到“目送秋光”上。“悄悄”，忧愁的样子。《诗·邺风·柏舟》：“忧心悄悄。”后来辛弃疾《踏莎行》词云：“吾道悠悠，忧心悄悄，最无...", "authors": ["刘文忠"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f39e6f69b71e93f6192", "shortContent": "这首《玉蝴蝶》与《八声甘州》（对潇潇暮雨洒江天）蹊径仿佛，将羁旅行役之苦、志士失意之悲与相思离别之情完全揉合在一起，这也是柳词最大的特色。这首词以抒情为主，把写景和叙事、忆旧和怀人、羁旅和离别、时间和空间，融汇为一个浑然的艺术整体，具有很强的艺术感染力。\n起调写景入题。登高往远处望去，雨收了，云也散了，我独自悄悄凭栏而立，忧心忡忡，目送着绵延无际的秋光。“雨收云断”，气氛清凉。“悄悄”，显出忧愁的...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127174c305cf08018170b2", "shortContent": "这首《玉蝴蝶》与《八声甘州》（对潇潇暮雨洒江天）蹊径仿佛，将羁旅行役之苦、志士失意之悲与相思离别之情完全糅合在一起，这也是柳词最大的特色。这首词以抒情为主，把写景和叙事、忆旧和怀人、羁旅和离别、时间和空间，融汇为一个浑然的艺术整体，具有很强的艺术感染力。\n起调写景入题，“望断”二字统摄全篇。登高往远处望去，雨收了，云也散了，我独自悄悄凭栏而立，忧心忡忡，目送着绵延无际的秋光。“雨收云断”，气氛清凉...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d125c7af6de1647100d8a", "bookTitle": "柳永词鉴赏辞典", "articleId": "646d8f8445e4710056e97e6a", "shortContent": "柳永《玉蝴蝶》一词，风格与其《八声甘州》相近，它通过描绘萧疏、清幽 的秋景，来抒写对朋友的思念之情。\n\n起句以写景入题。“望处雨收云断”，是写即目所见之景，可以看出远处天边风云变幻的痕迹，使清秋之景，显得更加疏朗。“凭阑悄悄”四字，写出了独自倚阑远望时的忧思。这种情怀，又落脚到“目送秋光”上。“悄悄”，忧愁的样子。《诗·邺风·柏舟》:“忧心悄悄。”后来辛弃疾《踏莎行》词云：“吾道悠悠，忧心悄悄，最...", "authors": ["刘文忠"], "pressName": "上海辞书出版社"}]', '俞樂靜《唐五代两宋词选释》：「水风」二句善状萧疏晚景，且引起下文离思。「情伤」以下至结句黯然魂消，可抵江淹《别赋》，令人增《蒹葭》怀友之思。', 'indent', 1418820624, '57b96936d342d3005acadf71', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10721, '迷神引', NULL, 48, 225, 1, 1, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/view/2793426.htm', '', '一叶扁舟轻帆卷，暂泊楚江南岸。孤城暮角，引胡笳怨。水茫茫，平沙雁，旋惊散。烟敛寒林簇，画屏展，天际遥山小，黛眉浅。
旧赏轻抛，到此成游宦。觉客程劳，年光晚。异乡风物，忍萧索，当愁眼。帝城赊，秦楼阻，旅魂乱。芳草连空阔，残照满，佳人无消息，断云远。', '此词是柳永晚年游宦时羁旅行役之作。作者仕途不得志，直到仁宗景祐元年（1034）才进士及第，此时年已约五十岁，此后长期任地方小官，久经辗转，四处游宦。这首词是他行役途中写作的。
上片写晚景。孤城上响起黄昏的号角，像胡笳吹奏出古老的悲怨。江水茫茫，平旷的沙滩上落满了大雁，忽而惊得四散。雾霭从空中收敛，显露出一簇簇寒秋的树林，犹如画屏展现。辽阔的天边，远山那么微小，就像淡淡的黛色描出蛾眉弯弯。
下片抒愁情。只觉得客游他乡，旅程劳烦，一年光阴又近岁晚。异乡的风光景物，怎忍看萧条、冷落，遮住忧愁的双眼。京城遥远归路难，佳人远阻难相见，搅得词人客旅神魂迷乱。芳草连绵，伸延到空阔的天边，夕阳残照的余晖将大地铺满，佳人音信皆无，像扯断的彩云越飘越远。全词寓情于景，情景交融，语言哀愁缠绵，气韵含蓄沉郁，完全呈现出游宦失意的凄凉晚景。', '迷神引：词牌名。
泊：停泊。楚江：泛指南方的河流。
角：画角，古代军中乐器，上有绘画装饰，其音高亢哀厉。
引：乐曲体裁之一，有“序曲”的意思。
旋：随即。
敛：收起，散尽。簇：丛聚。
黛眉浅：古诗文中有将山比作女子的眉毛。黛眉：女子的眉毛。浅：形容颜色浅淡。
旧赏：指往日的欢快如意之事。
游宦：在官场上奔波漂泊。
劳：困顿疲惫。
秦楼阻：心爱的佳人被阻隔在远方。秦楼：出自汉乐府《陌上桑》：“日出东南隅，照我秦氏楼。”后以秦楼代指女子。
旅魂乱：在宦途上奔波的征人心情沮丧，烦乱不堪。魂：心灵，情绪。
断云：片云。', '一叶小舟上轻帆舒卷，暂时停泊在楚江南岸。孤城中响起阵阵角声，又引出一曲胡笳呜咽哀怨。江水白茫茫，沙滩上栖息的大雁，顷刻间全部被惊散。暮霭如烟般笼罩在林间，一丛丛秋林像画屏一般在眼前铺展。看天边遥遥群山是那么细小，如同美人的弯弯黛眉一样浅淡。
轻易地离开了心上人，到这里成了游宦。深深感到旅途劳顿，一年又到岁晚。不忍看异乡风物，一片萧索，进入眼中又添愁烦。京城是这般遥远，秦楼楚馆也被阻难去，让我心烦意乱。芳草萋萋伸向空阔的天边，夕阳洒满河山，佳人杳无音信，像被风吹走的浮云一样远去不返。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74a0911759740c9aa2ba", "shortContent": "柳永屡次下第，经过艰难曲折，终于在仁宗景祐元年（1034）考中进士，旋即踏入仕途。这时词人约近五十岁了。他入仕之后长期担任地方州郡的掾吏、判官等职，久困选调，辗转宦游各地，很不得志。这首《迷神引》便是他入仕后所写的羁旅行役之词。\n楚江是泛指楚地某处之江，柳永宦游经此。舟人将风帆收卷，靠近江岸，作好停泊准备。“暂泊”表示天色将晚，暂且止宿，明朝又将继续舟行。前人说柳永“尤工羁旅行役之词”，从此词起两...", "authors": ["谢桃坊"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a75914587d02f58fc2", "shortContent": "柳永屡次下第，经过艰难曲折，终于在仁宗景元年（1034）考中进士，旋即踏入仕途。这时词人约近五十岁了。他入仕之后长期担任地方州郡的掾吏、判官等职，久困选调，辗转宦游各地，很不得志。这首《迷神引》便是他入仕后所写的羁旅行役之词。\n楚江是泛指楚地某处之江，柳永宦游经此。舟人将风帆收卷，靠近江岸，作好停泊准备。“暂泊”表示天色将晚，暂且止宿，明朝又将继续舟行。前人说柳永“尤工羁旅行役之词”，从此词起两...", "authors": ["谢桃坊"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f39e6f69b71e93f6194", "shortContent": "此词依然是柳永在江南追思怀念帝京生活的一首，从词中提到的“游宦”来看，应该是晚年所作。因为柳永早年屡赴科举不第，待他考中进士为官时，已经50岁了。本词依然承前一贯的风格，将对“帝城”里“秦楼”的“佳人”的思念融入秋日行役的漂泊羁愁之中，情愈深，愁愈浓，加之年老，比起早年浪游羁旅之词更多凄苦怨怀。\n此词用自创曲调《迷神引》，三字句多，错杂以四、五言句，节奏急促、顿挫，与表现凄楚沉郁的宦游情怀，颇为相...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe47ccdb86c49f29182", "shortContent": "此词依然是柳永在江南追思怀念帝京生活的一首，从词中提到的“游宦”来看，应该是晚年所作。因为柳永早年屡赴科举不第，待他考中进士为官时，已经50岁了。本词依然承前一贯的风格，将对“帝城”里“秦楼”的“佳人”的思念融入秋日行役的漂泊羁愁之中，情愈深，愁愈浓，加之年老，比起早年浪游羁旅之词更多凄苦怨怀。\n\n此词用自创曲调《迷神引》，三字句多，错杂以四、五言句，节奏急促、顿挫，与表现凄楚沉郁的宦游情怀，颇为...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "63127174c305cf08018170b4", "shortContent": "此词依然是柳永在江南追思怀念帝京生活的一首，从词中提到的“游宦”来看，应该是晚年所作。因为柳永早年屡赴科举不第，待他考中进士为官时，已经五十岁了。本词依然承前一贯的风格，将对“帝城”里“秦楼”的“佳人”的思念融入秋日行役的漂泊羁愁之中，情愈深，愁愈浓，加之年老，比起早年浪游羁旅之词更多凄苦怨怀。\n此词用自创曲调《迷神引》，三字句多，错杂以四、五言句，节奏急促、顿挫，与表现凄楚沉郁的宦游情怀，颇为相...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d125c7af6de1647100d8a", "bookTitle": "柳永词鉴赏辞典", "articleId": "646d8fc6902ee364cc82b9b2", "shortContent": "柳永屡次下第，经过艰难曲折，终于在仁宗景祐元年（1034）考中进士，旋即踏入仕途。这时词人五十岁了。他入仕之后长期担任地方州郡的掾吏、判官等职，久困选调，辗转宦游各地，很不得志。这首《迷神引》便是他入仕后所写的羁旅行役之词。\n\n楚江是泛指楚地某处之江，柳永宦游经此。舟人将风帆收卷，靠近江岸，作好停泊准备。“暂泊”表示天色将晚，暂且止宿，明朝又将继续舟行。前人说柳永“尤工羁旅行役之词”，从此词起两句...", "authors": ["谢桃坊"], "pressName": "上海辞书出版社"}]', NULL, 'indent', 1418828347, '57ba0595128fe1005f8831eb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10722, '竹马子', NULL, 117, 225, 3, 1, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', 'http://baike.baidu.com/view/2793438.htm', '', '登孤垒荒凉，危亭旷望，静临烟渚。对雌霓挂雨，雄风拂槛，微收烦暑。渐觉一叶惊秋，残蝉噪晚，素商时序。览景想前欢，指神京、非雾非烟深处。
向此成追感，新愁易积，故人难聚。凭高尽日凝伫，赢得消魂无语。极目霁霭霏微，暝鸦零乱，萧索江城暮。南楼画角，又送残阳去。', '这是一首描写登高望远，忆昔怀人的词。上片写登上孤立的营垒满目荒凉，从高耸的亭台远望，静默地俯视着沙洲。面对着一弯虹霓挂起陶幕，一阵雄猛的大风吹拂栏杆，微微收敛了烦躁的暑热。渐渐惊觉到一片飘零的落叶送来了秋寒，几只残喘的秋蝉鸣噪着日暮的悲楚，开始了寒秋时节的冷肃。览景生情，不由追忆往昔在帝京时的欢乐，指点京都，在那似烟非烟、似雾非雾的彩云深处。下片感叹愁怀难遣，故人难聚，极目处雨后晴云，薄雾弥漫像迷濛的细雨，黄昏里归巢的乌鸦乱纷纷聚在一起，萧条冷落的江城已是暮色迷离。城南角楼吹响的号角，又送走一抹残阳沉入大地。全词景凄情哀，铺叙有致，意境开阔，格调清雅，悲楚动人。', '竹马子：词牌名。
孤垒：孤零零的昔日营垒。垒：军用建筑物。
危亭旷望：在高亭上远望。
烟渚：笼罩着雾气的水中沙洲。
雌霓挂雨：彩虹横空，天地间还带有雨水的湿气。雌霓：彩虹双出，色彩鲜艳为主虹，色彩暗淡为副虹，雌霓是副虹。
雄风拂槛：强劲之风吹拂栏杆。
微收烦暑：闷热的暑气稍有收敛。烦：一作“残”。
一叶惊秋：见一片黄叶落下，猛地意识到秋天来了。
残蝉噪晚：经历了夏天而残余的蝉在晚暮时分叫得更加起劲。
素商时序：秋天接着次序即将代替夏天到来。素商：秋天。时序：春夏秋冬的代换次序。
前欢：从前与故人欢聚的情景。
尽日：整天。
赢得：换得。消魂：情思惆怅。
极目：尽力远望。霏微：朦胧的样子。
暝：天黑。
萧索：萧疏冷落。
画角：古管乐器。传自西羌。形如竹筒，本细末大，以竹木或皮革等制成，因表面有彩绘，故称。发声哀厉高亢，古时军中多用以警昏晓，振士气，肃军容。帝王出巡，亦用以报警戒严。', '登上孤立的营垒，看去一片荒凉，从危亭上从台上远望，静视着沙洲上都是烟云茫茫。面对着雌霓下起雨来，突然一阵狂风吹拂栏槛，微微赶走了夏季的炎热。渐渐感到一片飘零的落叶，送来了秋寒，几只鸣叫的秋蝉呜噪着，天晚的悲楚，开始了寒秋时节的新景。我观览着眼前景物，想起往日的欢情，指点京都，就是那似烟非烟的彩云深处。面对如此情景，我不由得伤感，新愁添加，故人难于相见。我登高凭栏整日里望远，最后百感交集。极目处雨后晴云，薄雾弥漫像迷蒙的细雨，黄昏里归巢的乌鸦乱纷纷聚在一起，萧条冷落的江城已是暮色迷离。城南角楼吹响了音乐，又送走一抹残阳沉入大地。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74a07d0ac1145494bb2d", "shortContent": "柳永除写大量俗词之外，也写有一部分较雅致的词。苏轼说：“世言柳耆卿曲俗，非也。如《八声甘州》云‘霜风凄紧，关河冷落，残照当楼’，此语于诗句不减唐人高处。”（宋赵令畴《侯鲭录》引）这是就其雅词而言的。《竹马子》也属柳永的雅词，而且也达到了“唐人高处”的境界。\n这首词虽然是词人漫游江南时抒写离情别绪之作，而所表现的景象却是雄浑苍凉的，其情绪是极其沉郁的。词人所登临旷望之地是古时战争留下的残壁废垒，而且...", "authors": ["谢桃坊"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5a7911759740c9bcb11", "shortContent": "柳永除写大量俗词之外，也写有一部分较雅致的词。苏轼说：“世言柳耆卿曲俗，非也。如《八声甘州》云‘霜风凄紧，关河冷落，残照当楼’，此语于诗句不减唐人高处。”（宋赵令畴《侯鲭录》引）这是就其雅词而言的。《竹马子》也属柳永的雅词，而且也达到了“唐人高处”的境界。\n这首词虽然是词人漫游江南时抒写离情别绪之作，而所表现的景象却是雄浑苍凉的，其情绪是极其沉郁的。词人所登临旷望之地是古时战争留下的残壁废垒，而且...", "authors": ["谢桃坊"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3a7ccdb86c49f29093", "shortContent": "《竹马子》是柳永的自度曲，从意境上讲，本词属于柳永的雅词一类。这首词的题材与前一首《迷神引》几乎一样，写的时间也是差不多同时段，其蹊径都相仿佛，差异只在《迷神引》是写孤舟停泊岸边的所见所感，《竹马子》是在登孤垒危亭时远眺而作。尽管如此，二者并不雷同。\n此词的开头和结尾均写初秋之景，上下片之间的中幅则抒发“神京”遥远、“故人难聚”之情，这种情景的安排，突破了柳永常用的上片景，下片情的格局。全篇若舍弃...", "authors": ["周　密"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63126fe47ccdb86c49f29183", "shortContent": "《竹马子》是柳永的自度曲，从意境上讲，本词属于柳永的雅词一类。这首词的题材与前一首《迷神引》几乎一样，写的时间也是差不多同时段，其蹊径都相仿佛，差异只在《迷神引》是写孤舟停泊岸边的所见所感，《竹马子》是在登孤垒危亭时远眺而作。尽管如此，二者并不雷同。\n\n此词的开头和结尾均写初秋之景，上下片之间的中幅则抒发“神京”遥远、“故人难聚”之情，这种情景的安排，突破了柳永常用的上片景，下片情的格局。全篇若舍...", "authors": ["周密"], "pressName": "崇文书局"}, {"bookId": "645d125c7af6de1647100d8a", "bookTitle": "柳永词鉴赏辞典", "articleId": "646d8fb97f27182da37968a3", "shortContent": "柳永除写大量俗词之外，也写有一部分较雅致的词。苏轼说：“世言柳耆卿曲俗，非也。如《八声甘州》云‘霜风凄紧，关河冷落，残照当楼’，此语于诗句不减唐人高处。”（宋赵令畴《侯鲭录》引）这是就其雅词而言的。《竹马子》也属柳永的雅词，而且也达到了“唐人高处”的境界。\n\n这首词虽然是词人漫游江南时抒写离情别绪之作，而所表现的景象却是雄浑苍凉的，其情绪是极其沉郁的。词人所登临旷望之地是古时战争留下的残壁废垒，而...", "authors": ["谢桃坊"], "pressName": "上海辞书出版社"}]', NULL, 'indent', 1418828433, '57b90fcd8ac2470062e00d58', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10723, '千秋岁引', NULL, 158, 1836, 1, 1, '王安石', NULL, 10067, '57b93713c4c971005590f52a', '宋', 'ci', '词', 'http://baike.baidu.com/view/3385882.htm', '', '别馆寒砧，孤城画角，一派秋声入寥廓。东归燕从海上去，南来雁向沙头落。楚台风，庾楼月，宛如昨。
无奈被些名利缚，无奈被他情担阁，可惜风流总闲却。当初漫留华表语，而今误我秦楼约。梦阑时，酒醒后，思量着。', '作为一代风云人物的政治家，王安石也并未摆脱旧时知识分子的矛盾心理：在兼济天下与独善其身两者中间徘徊。他一面以雄才大略，执拗果断著称于史册，另一方面，在激烈的政治漩涡中也时时泛起激流勇退，功名误身的感慨。上片写秋景。以悲秋诗词习用的“寒砧”、“画角”意象，与别馆、孤城相交融，借声写境，交织成一幅秋声凄切哀婉，萧条寒瑟的秋色图。下片抒情。辞意顿折，以两个“无奈”强烈表达羁身宦途，身不由己的苦衷，揭明词人悲秋原因：“名利缚”，“情担阁”，即名缰利锁缚人心性，世情俗态耽搁人生。“可惜”句讲多少风流俊雅之韵事，都因羁身官场名利俗情而丢脱不顾，流露了深深惋惜与自悔。“当初”二句追思嘉祐三年（1058），年轻气盛地向仁宗上万言书建议变法，遂导致“而今误我秦楼约”，明写空负与爱妻团聚的期约和私诺，暗写自己所眷恋之美人的失落，实为比兴式意象，隐喻空怀“华表留语”之抱负，却落得“秦楼误约”，理想落空之残局。最后，复以“梦阑”、“酒醒”皆思量，抒写词人对新政变法理想破灭的深思和悲哀。此词意在表达作者的一种情感，写来空灵回荡，真如空中之色，镜中之像，然情意真挚，恻恻动人。', '千秋岁引：词牌名，为《千秋岁》变格。八十二字，前片四仄韵，后片五仄韵。
别馆：客馆。砧（zhēn）：捣衣石。这里指捣衣声。
画角：古代军中乐器。
寥廓（liáokuò）：空阔，此处指天空。
楚台风：楚襄王兰台上的风。宋玉《风赋》：“楚王游于兰台，有风飒至，王乃披襟以当之曰：‘快哉此风！’”
庾（yǔ）楼月：庾亮南楼上的月。《世说新语》：“晋庾亮在武昌，与诸佐吏殷浩之徒乘夜月共上南楼，据胡床咏谑。”
他情：暗指皇上的恩情。担阁：延误。
漫：徒然，白白地。华表语：指向皇上进谏的奏章。华表，又名诽谤木，立于殿堂前。
秦楼约：指与恋人的约会。秦楼，代指女子居住处。
梦阑（lán）：梦醒。阑，残，尽。', '传入旅舍的捣衣声，应和着孤城城头的画角，一片秋声在广阔的天地间回荡。归去的燕子向东从海上飞走，南来的大雁自空中落下，栖息在沙滩上。这儿有楚王携宋玉游兰台时感受到的惬意的凉风，有庾亮与殷浩辈在南楼吟咏戏谑时的大好月色，清风明月的景象，还都与当年一样。
真是无可奈何啊！我被那微不足道的名利所羁缚，又被那难以割舍的感情所耽搁，可惜那些风流韵事都被丢到一边了。当初徒然许下功成身退时，要去求仙访道，潇潇度日的诺言。到如今，反误了我与佳人的秦楼约会。当睡梦觉来时、酒醉清醒后，我细细地思量着这一切。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74aa7d0ac1145494bb56", "shortContent": "作为一代风云人物的政治家，王安石也并未摆脱旧时知识分子的矛盾心理：在兼济天下与独善其身两者中间徘徊。他一面以雄才大略、执拗果断著称于史册；另一面，在激烈的政治旋涡中也时时泛起急流勇退、功名误身的感慨。这首小词便是他后一方面思想的表露。无怪明代的杨慎说：“荆公此词，大有感慨，大有见道语。既勘破乃尔，何执拗新法，铲除正人哉？”（《词品》）杨慎对王安石政治上的评价未必得当，但以此词为表现了作者思想中与热...", "authors": ["王镇远"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b1c6e67846a92190a0", "shortContent": "作为一代风云人物的政治家，王安石也并未摆脱旧时知识分子的矛盾心理：在兼济天下与独善其身两者中间徘徊。他一面以雄才大略、执拗果断著称于史册；另一面，在激烈的政治漩涡中也时时泛起激流勇退、功名误身的感慨。这首小词便是他后一方面思想的表露。无怪明代的杨慎说：“荆公此词，大有感慨，大有见道语。既勘破乃尔，何执拗新法，铲除正人哉？”（《词品》）杨慎对王安石政治上的评价未必得当，但以此词为表现了作者思想中与热...", "authors": ["王镇远"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592534b56e213e684802d", "shortContent": "作为一代风云人物的政治家，王安石也并未摆脱旧时知识分子的矛盾心理：在兼济天下与独善其身两者中间徘徊。他一面以雄才大略、执拗果断著称于史册；另一面，在激烈的政治漩涡中也时时泛起急流勇退、功名误身的感慨。这首小词便是他后一方面思想的表露。无怪明代的杨慎说：“荆公此词，大有感慨，大有见道语。既勘破乃尔，何执拗新法，铲除正人哉？”（《词品》）杨慎对王安石政治上的评价未必得当，但以此词为表现了作者思想中与热...", "authors": ["王镇远"], "pressName": "上海辞书出版社"}, {"bookId": "62de4ae858b41e188206f9ca", "bookTitle": "王安石诗文鉴赏辞典", "articleId": "6305a39130a1d3054c756153", "shortContent": "作为一代风云人物的政治家，王安石也并未摆脱旧时知识分子的矛盾心理：在兼济天下与独善其身两者中间徘徊。他一面以雄才大略、执拗果断著称于史册；另一面，在激烈的政治漩涡中也时时泛起急流勇退、功名误身的感慨。这首小词便是他后一方面思想的表露。无怪明代的杨慎说：“荆公此词，大有感慨，大有见道语。既勘破乃尔，何执拗新法，铲除正人哉？”（《词品》）杨慎对王安石政治上的评价未必得当，但以此词为表现了作者思想中与热...", "authors": ["王镇远"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3d73206168b2e020be", "shortContent": "寒冷的旅馆传来捣衣砧声，画角悲鸣，响彻孤城，一派秋声散入寥廓无边的天空。东归的燕子从海上飞去，南来的大雁向沙头降落。楚王兰台的快哉之风，庾亮南楼的皎备月色，如今仍与当年一样。\n\n无奈被些许名利束缚，无奈被俗事耽搁了人生，可惜浪费了那些风流美景。当初努力进谏，白白提交了那么多有关国家政治方面的意见，反耽误了情人期约。午夜梦回，酒醒之后，总深深思量着。\n\n这首词创作年代不详，大约是词人晚年变法失败退居...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702d77683d1933015346", "shortContent": "寒冷的旅馆传来捣衣砧声，画角悲鸣，响彻孤城，一派秋声散入寥廓无边的天空。东归的燕子从海上飞去，南来的大雁向沙头降落。楚王兰台的快哉之风，庾亮南楼的皎洁月色，如今仍与当年一样。\n\n无奈被些许名利束缚，无奈被俗事耽搁了人生，可惜浪费了那些风流美景。当初努力进谏，白白提交了那么多有关国家政治方面的意见，反耽误了情人期约。午夜梦回，酒醒之后，总深深思量着。\n\n这首词创作年代不详，大约是词人晚年变法失败退居...", "authors": ["冯丽霞"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312718dc26cbf3417f09588", "shortContent": "寒冷的旅馆传来捣衣砧声，画角悲鸣，响彻孤城，一派秋声散入寥廓无边的天空。东归的燕子从海上飞去，南来的大雁向沙头降落。楚王兰台的快哉之风，庾亮南楼的皎洁月色，如今仍与当年一样。\n无奈被些许名利束缚，无奈被俗事耽搁了人生，可惜浪费了那些风流美景。当初努力进谏，白白提交了那么多有关国家政治方面的意见，反耽误了情人期约。午夜梦回，酒醒之后，总深深思量着。\n这首词创作年代不详，大约是词人变法失败晚年退居金陵...", "authors": ["冯丽霞"], "pressName": "崇文书局"}]', '杨慎《词品》：荆公此词，大有感慨，大有见道语，既勘破乃尔，何执拗新法，铲灭正人哉？
李攀龙《草堂诗余隽》：不着一愁语，而寂寂景色，隐隐在目，洵一幅秋光图，最堪把玩。
卓人月《古今词统》卷十一：末句不言愁，使人自愁。
沈际飞：介甫有游仙之意，悟矣。必待“梦闺”、“酒醒”、“思量着”，又何迟也。媚出于老，流动出于整齐，其笔墨自不可议。
先著、程洪《词洁》：“无奈”数语鄙俚，然首尾实是词家法门。阅北宋词须放一线道，往往北宋人一二语，又是南渡以后丹头，故不可轻弃也。
黄苏《蓼园词选》：按是必其退居金陵时作也。意致清迥，愉然有出尘之致。', 'indent', 1418828554, '57b8feda8ac2470062df87a9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (90738, '渔父词一十八首 · 自无忧', NULL, 0, 321, 0, 1, '吕岩', NULL, 12581, '5835b348128fe10062cb8166', '唐', 'ci', '词', 'https://baike.baidu.com/item/%E6%B8%94%E7%88%B6%E8%AF%8D%E4%B8%80%E5%8D%81%E5%85%AB%E9%A6%96%C2%B7%E8%87%AA%E6%97%A0%E5%BF%A7/19278910', '', '学道初从此处修，断除贪爱别娇柔。长守静，处深幽，服气餐霞饱即休。', '', '', '', NULL, '', 'indent', 1530289387, '585d162b1b69e6005610093a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10724, '清平乐 · 春晚', NULL, 170, 64, 2, 2, '王安国', NULL, 10171, '57bb156ea633bd005d3989f5', '宋', 'ci', '词', 'http://baike.baidu.com/view/1047948.htm', '', '留春不住，费尽莺儿语。满地残红宫锦污，昨夜南园风雨。
小怜初上琵琶，晓来思绕天涯。不肯画堂朱户，春风自在杨花。', '古来伤春悲秋的诗词很多。这类被人嚼烂了的题材，却是历代不乏佳篇，非但不使人感到老一套，相反，永远有新鲜之感。这首词就是这样的好词。上阕写景伤春。由「风雨」导致「残红」，由「残红」而触发「莺语留春」，词人以奇特构思颠倒顺序，将「无可奈何花落去」的无计留春之伤感，巧妙地借莺儿乱语突现句首，旁托曲致，新颖而有情趣。
下阕借人抒情。「小怜」二句写歌女初次弹奏琵琶演唱歌曲，正是在南园莺啼花艳的明媚春光中。从上阕之「昨夜」与下阕之「晓来」，时间前后承接自然，故知「初上琵琶」在「昨夜风雨」之前，而「思绕天涯」乃在「昨夜风雨」之后的清晓。「不肯」二句写小怜再不肯在豪门贵胄的画堂朱户歌舞献艺虚耗青春，而希望像沐浴春风的自在梨花！「杨花」意象亦并非现景描绘，而是对未来美景的向往与期冀。此词在众多的伤春词中能出乎其类而拔乎其萃，正是因为它融进了自己的生活，写出了自己的性情。', '清平乐（yuè）：唐教坊曲名，后用为词牌名。又名《清平乐令》、《醉东风》《忆萝月》。《宋史·乐志》入「大石调」，《金奁集》《乐章集》并入「越调」。
宫锦：宫廷监制并特有的锦缎。这里喻指落花。
「满地残红宫锦污，昨夜南园风雨。」句：应作倒装理解。
小怜：北齐后主淑妃冯小怜，善弹琵琶。这里借指弹琵琶的歌女。
杨花：一作「梨花」。', '怎么也未能把春天留住，白白地让黄莺唱个不停。满地都是脏污的红锦落花，是昨夜一场风雨的侵凌。
小怜姑娘刚刚弹起琵琶，拂晓她思绪万千萦绕天庭。看那不肯进入豪门大户的杨花，自由自在地漫舞春风。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74aa0f8fda556504d974", "shortContent": "古来伤春悲秋的诗词多得不可胜数。这类被人嚼烂了的题材，却是历代不乏佳篇，非但不使人感到老一套，相反，永远有新鲜之感。王安国这首《清平乐》就是这样的好词。\n词写残春景象。且看词人如何着笔：“留春不住，费尽莺儿语。满地残红宫锦污，昨夜南园风雨。”显然，由于“昨夜雨疏风骤”，南园今朝满地残红了。词人面对这万花凋谢的景象，自然不胜伤感。此时耳边传来了黄莺儿不停的啼唱，于是，他仿佛感觉到多情的莺儿也正在为落...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b10ce818559d063aff", "shortContent": "古来伤春悲秋的诗词多得不可胜数。这类被人嚼烂了的题材，却是历代不乏佳篇，非但不使人感到老一套，相反，永远有新鲜之感。王安国这首《清平乐》就是这样的好词。\n词题为《春晚》，顾名思义是写残春景象。且看词人如何着笔：“留春不住，费尽莺儿语。满地残红宫锦污，昨夜南园风雨。”显然，由于“昨夜雨疏风骤”，南园今朝满地残红了。词人面对这万花凋谢的景象，自然不胜伤感。此时耳边传来了黄莺儿不停的啼唱，于是，他仿佛感...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3d73206168b2e020c0", "shortContent": "“清平乐”原是唐教坊曲名，关于其名来由说法不一。或曰寄予了海内清平的祈求，或说取自汉乐府“清乐”、“平乐”这两个乐调。《尊前集》载有李白词四首，虽是此调首见，但疑为后人委托。又名《清平乐令》（见《花庵词选》）、《醉东风》（张翥词有“明朝来醉东风”句）和《忆萝月》（张辑词有“忆著故山萝月”句）。\n\n上片描画暮春风物，体察入微而融情于景。起笔先声夺人，不同凡响：词人自出机抒，将自己对春逝的怅叹与不舍，...", "authors": ["丘　悦"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702d77683d1933015348", "shortContent": "“清平乐”原是唐教坊曲名，关于其名来由说法不一。或曰寄予了海内清平的祈求，或说取自汉乐府“清乐”、“平乐”这两个乐调。《尊前集》载有李白词四首，虽是此调首见，但疑为后人伪托。又名《清平乐令》（见《花庵词选》）、《醉东风》（张翥词有“明朝来醉东风”句）和《忆萝月》（张辑词有“忆著故山萝月”句）。\n\n上片描画暮春风物，体察入微而融情于景。起笔先声夺人，不同凡响：词人自出机杼，将自己对春逝的怅叹与不舍，...", "authors": ["丘悦"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312719b73206168b2e02343", "shortContent": "“清平乐”原是唐教坊曲名，关于其名来由说法不一。或曰寄予了海内清平的祈求，或说取自汉乐府“清乐”“平乐”这两个乐调。《尊前集》载有李白词四首，虽是此调首见，但疑为后人伪托。又名《清平乐令》（见）《花庵词选》、《醉东风》（张翥词有“明朝来醉东风”句）和《忆萝月》（张辑词有“忆著故山萝月”句）。\n上片描画暮春风物，体察入微而融情于景。起笔先声夺人，不同凡响：词人自出机杼，将自己对春逝的怅叹与不舍，转嫁...", "authors": ["丘悦"], "pressName": "崇文书局"}, {"bookId": "645fc22c5e6bb82b8caff682", "bookTitle": "历代咏春诗鉴赏：春江花月夜", "articleId": "6473052cb5420e2767932c04", "shortContent": "古来伤春悲秋的诗词多得不可胜数。这类被人嚼烂了的题材，却是历代不乏佳篇，非但不使人感到老一套，相反，永远有新鲜之感。王安国这首《清平乐》就是这样的好词。\n\n词题为《春晚》，顾名思义是写残春景象。且看词人如何着笔：“留春不住，费尽莺儿语。满地残红宫锦污，昨夜南园风雨。”显然，由于“昨夜雨疏风骤”，南园今朝满地残红了。词人面对这万花凋谢的景象，自然不胜伤感。此时耳边传来了黄莺儿不停的啼唱，于是，他仿佛...", "authors": ["高原"], "pressName": "上海辞书出版社"}]', '宋·周少隐《竹坡老人诗话·卷一》：大梁罗叔共为余言：“顷在建康士人家，见王荆公亲写小词一纸，其家藏之甚珍。其词云：‘留春不住’云云。荆公平生不作是语，而有此，何也？”仪真沈彦述谓余言：“荆公诗，如：‘繁绿万枝红一点，动人春色不须多’‘春色恼人眠不得，月移花影上栏干’等篇，皆平父诗，非荆公诗也。”沈乃元龙家婿，故尝见之耳。叔共所见，未必非平甫词也。
清·谭献评《词辨·卷二》：倒装二句（“满地残红宫锦污，昨夜南园风雨”）以见笔力。结笔（“不肯画堂朱户，春风自在杨花”）品格自高。', 'indent', 1418828657, '57b8ed36128fe10054c91223', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10725, '蝶恋花', NULL, 281, 267, 3, 2, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'http://baike.baidu.com/view/2966165.htm', '', '梦入江南烟水路，行尽江南，不与离人遇。睡里消魂无说处，觉来惆怅消魂误。
欲尽此情书尺素。浮雁沉鱼，终了无凭据。却倚缓弦歌别绪，断肠移破秦筝柱。', '这首词写对恋人的无穷相思和无尽的离愁别绪。上阕写梦寻。“梦入江南”直接切入梦境，借“烟水”意象点染江南水乡迷茫、浩渺的景物特征，也显示出梦境的迷离恍惚。“行尽江南”几千里，写其在江南四方求索之急切与艰苦。“离人”句方始点明词人苦苦求索之对象与目的，而“不遇”则流露了梦寻离别美人情侣的失落与怅恨。“睡里”、“觉来”两句则概括了词人对情侣魂牵梦系，日思夜想的苦恋情怀，“消魂”伤神之状。下阕写梦寻不见，托鱼雁传书也无准信，再去倚筝絃以寄托相思，却是抚奏遍筝柱缓絃，奏出来的都是离愁别绪的悲曲。全词不着一“愁”字，但处处言愁。', '蝶恋花：又名《鹊踏枝》、《凤栖梧》。唐教坊曲。《乐章集》《张子野词》并入“小石调”，《清真集》入“商调”。双调六十字，上下阕各四仄韵。
消魂：魂魄消灭。多以名悲伤愁苦之状。江淹《别赋》有“黯然销魂者，惟别而已矣”。
惆怅：因失望或失意而哀伤。
消魂：一作“佳期”。
尺素：书写用之尺长素绢，借指简短书信。古人为书，多写于白绢上。素，白绢。
浮雁沉鱼：古代诗文中常以鸿雁和鱼作为传递书信的使者。古乐府《饮马长城窟行》有“客从远方来，遗我双鲤鱼。呼儿烹鲤鱼，中有尺素书。长跪读素书，书中竟何如。上有加餐食，下有长相忆。”又《汉书·苏武传》有“教使者谓单于，言天子射上林中，得雁，足有繫帛书”，因合称书信为鱼雁，亦有以鳞代鱼，以鸿作雁者。另亦指传书信者。
终了：纵了，即使写成。
无凭据：不可靠、靠不住。
破：唐宋大曲术语。大曲十馀遍，分散序、中序、破三大段。张相《诗词曲语辞汇释》：“破，犹尽也，遍也，煞也。”
移破：犹云移尽或移遍也。', '梦中走向了烟水迷蒙的江南路，走遍了江南大地，也未能与离别的心上人相遇。梦境里黯然销魂无处诉说，醒后惆怅不已全因梦中消魂误。
想诉说我的相思提笔给你写信，但是雁去鱼沉，到头来这封信也没能寄出。无可奈何缓缓弹筝抒发离情别绪，移破了筝柱也难把怨情抒。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74abd635634aee3d715e", "shortContent": "岑参《春梦》诗：“洞房昨夜春风起，遥忆美人湘江水。枕上片时春梦中，行尽江南数千里。”晏幾道是否到过江南，是否有“心上人”在江南，难以稽考；这首词上片起三句“梦入江南烟水路，行尽江南，不与离人遇”，似用岑诗语意，未必是写实。它说梦游江南，梦中始终找不到离别的“心上人”。“行尽”二字，状梦境倏忽和求索之苦；求索之苦又反映思念之深，出于梦中的潜意识活动，深更可知。“烟水路”三字写出江南景物特征，使梦境显...", "authors": ["陈祥耀"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b22e6a6b501f96729d", "shortContent": "岑参《春梦》诗：“洞房昨夜春风起，遥忆美人湘江水。枕上片时春梦中，行尽江南几千里。”晏几道是否到过江南，是否有“心上人”在江南，难以稽考；这首词上片起三句：“梦入江南烟水路，行尽江南，不与离人遇”，似用岑诗语意，未必是写实。它说梦游江南，梦中始终找不到离别的“心上人”。“行尽”二字，状梦境倏忽和求索之苦；求索之苦又反映思念之深，出于梦中的潜意识活动，深更可知。“烟水路”三字写出江南景物特征，使梦境...", "authors": ["陈祥耀"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592534b56e213e6848031", "shortContent": "岑参《春梦》诗：“洞房昨夜春风起，遥忆美人湘江水。枕上片时春梦中，行尽江南几千里。”晏几道是否到过江南，是否有“心上人”在江南，难以稽考；这首词上片起三句：“梦入江南烟水路，行尽江南，不与离人遇”，似用岑诗语意，未必是写实。它说梦游江南，梦中始终找不到离别的“心上人”。“行尽”二字，状梦境倏忽和求索之苦；求索之苦又反映思念之深，出于梦中的潜意识活动，深更可知。“烟水路”三字写出江南景物特征，使梦境...", "authors": ["陈祥耀"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3d73206168b2e020d0", "shortContent": "晏几道虽出身豪门，然一生仕途落拓，晚年由乾宁军通判转开封府推官。叔原高傲独立，亦不依傍权贵，惟寄其志于文章翰墨间，歌其情于乐府诗馀中。中年之时与黄庭坚交好，黄庭坚曾言叔原平生有“四痴”：“仕宦连蹇，而不能一傍贵人之门，是一痴也；论文自有体，不肯作一新进士语，又一痴也；费资千百万，家人寒饥，而面有孺子之色，此又一痴也；人百负之而不恨，己信人，终不疑其欺己，此又一痴也。”叔原有《小山词》传世，而“梦”...", "authors": ["梁晓琳"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "6312702f7ccdb86c49f29201", "shortContent": "晏几道虽出身豪门，然一生仕途落拓，晚年由乾宁军通判转开封府推官。叔原高傲独立，亦不依傍权贵，惟寄其志于文章翰墨间，歌其情于乐府诗馀中。中年之时与黄庭坚交好，黄庭坚曾言叔原平生有“四痴”：“仕宦连蹇，而不能一傍贵人之门，是一痴也；论文自有体，不肯作一新进士语，又一痴也；费资千百万，家人寒饥，而面有孺子之色，此又一痴也；人百负之而不恨，己信人，终不疑其欺己，此又一痴也。”叔原有《小山词》传世，而“梦”...", "authors": ["梁晓琳"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312719b73206168b2e02346", "shortContent": "晏几道虽出身豪门，然一生仕途落拓，晚年由乾宁军通判转开封府推官。叔原高傲独立，亦不依傍权贵，惟寄其志于文章翰墨间，歌其情于乐府诗馀中。中年之时与黄庭坚交好，黄庭坚曾言叔原平生有“四痴”：“仕宦连蹇，而不能一傍贵人之门，是一痴也；论文自有体，不肯作一新进士语，又一痴也；费资千百万，家人寒饥，而面有孺子之色，此又一痴也；人百负之而不恨，己信人，终不疑其欺己，此又一痴也。”叔原有《小山词》传世，而“梦”...", "authors": ["梁晓琳"], "pressName": "崇文书局"}, {"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "646790c45e6bb82b8cd0be4c", "shortContent": "岑参《春梦》诗：“洞房昨夜春风起，遥忆美人湘江水。枕上片时春梦中，行尽江南几千里。”晏幾道是否到过江南，是否有“心上人”在江南，难以稽考；这首词上片起三句：“梦人江南烟水路，行尽江南，不与离人遇”，似用岑诗语意，未必是写实。它说梦游江南，梦中始终找不到离别的“心上人”。“行尽”二字，状梦境倏忽和求索之苦；求索之苦又反映思念之深，出于梦中的潜意识活动，深更可知。“烟水路”三字写出江南景物特征，使梦境...", "authors": ["陈祥耀"], "pressName": "上海辞书出版社"}]', '', 'indent', 1418828777, '57b8e3e32e958a005fa4a86f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10726, '蝶恋花', NULL, 256, 267, 3, 2, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'http://baike.baidu.com/view/2966186.htm', '', '醉别西楼醒不记，春梦秋云，聚散真容易。斜月半窗还少睡，画屏闲展吴山翠。
衣上酒痕诗里字，点点行行，总是凄凉意。红烛自怜无好计，夜寒空替人垂泪。', '这首小词写别后的凄哀愁情。上阕写醉梦醒来，记得的只是因离别痛苦难遣而大醉以浇离愁，醒来更感慨人生如梦如云，聚无由，散去容易，眼下只剩自己一人独对斜月画屏，凄凉孤寂不尽。开篇破空而起，直陈与伊人醉中分别。紧接化用唐诗，形容聚会之短，分别之易。以下专就月夜忆人着笔生发。画屏闲展见出卧不合眼，环境空寂。下阕写聚时的酒痕诗字，现在睹物怀人，无不都是凄凉哀伤，连红烛油流，也觉得替人流伤心泪。全词语淡情深，句句凄哀。结尾赋红烛以人性，更显凄凉。风格婉约，手法精妙。', '蝶恋花：唐教坊曲名，后用作词牌名。又名《鹊踏枝》、《凤栖梧》。
西楼：泛指欢宴之所。
春梦秋云：喻美好而又虚幻短暂、聚散无常的事物。白乐天《花非花》诗：「来如春梦不多时，去似秋云无觅处。」晏同叔《木兰花》：「长于春梦几多时，散似秋云无觅处。」
吴山：画屏上的江南山水。
「红烛自怜无好计，夜寒空替人垂泪」句：化用唐杜樊川《赠别二首·其二》：「蜡烛有心还惜别，替人垂泪到天明。」将蜡烛拟人化。', '醉别西楼的情景醒后全都忘记。犹如春梦秋云，人生聚散实在太容易。月光斜照窗棂，我难以入睡，闲看画屏上吴山的葱翠。
衣上的酒痕和诗里的字，一点点，一行行，都是那凄凉的情意。可怜的红烛自怜没有好办法，只能在寒夜中白白地为人垂泪。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74abd635634aee3d715d", "shortContent": "这是一首怀旧词。\n首句忆昔，凌空而起。往日醉别西楼（泛指欢宴之所），醒后却浑然不记。这似乎是追忆往日某一幕具体的醉别，又像是泛指所有的前欢旧梦。似实似虚，笔意殊妙。晏幾道自作《小山词序》中说他自己的词，“所记悲欢、合离之事，如幻，如电，如昨梦、前尘”。沈祖棻《宋词赏析》借此说这句词，“极言当日情事‘如幻、如电，如昨梦、前尘’，不可复得”，“抚今追昔，浑如一梦，所以一概付之‘不记’”，是善体言外之意...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b27d0ac1145495e876", "shortContent": "这是一首怀旧词。\n首句忆昔，凌空而起。往日醉别西楼（泛指欢宴之所），醒后却浑然不记。这似乎是追忆往日某一幕具体的醉别，又像是泛指所有的前欢旧梦。似实似虚，笔意殊妙。晏几道自作《小山词序》中说他自己的词，“所记悲欢合离之事，如幻如电，如昨梦前尘”。沈祖棻《宋词赏析》借此说这句词，“极言当日情事‘如幻如电，如昨梦前尘’，不可复得”，“抚今追昔，浑如一梦，所以一概付之‘不记’”，是善体言外之意的。不过，...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592534b56e213e6848030", "shortContent": "这是一首怀旧词。\n\n首句忆昔，凌空而起。往日醉别西楼（泛指欢宴之所），醒后却浑然不记。这似乎是追忆往日某一幕具体的醉别，又像是泛指所有的前欢旧梦。似实似虚，笔意殊妙。晏几道自作《小山词序》中说他自己的词，“所记悲欢合离之事，如幻如电，如昨梦前尘”。沈祖棻《宋词赏析》借此说这句词，“极言当日情事‘如幻如电，如昨梦前尘’，不可复得”，“抚今追昔，浑如一梦，所以一概付之‘不记’”，是善体言外之意的。不过...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3d73206168b2e020d1", "shortContent": "本词大约是晏几道晚年的作品。晏几道晚年穷困潦倒，每回忆其平生之悲欢离合，也不禁感慨道：“如幻如电。”小晏似乎更倾向认为人的生命是缺少实质性的东西而不可捉摸的，它借着时间而获得现实的体现，又因为时间的流逝而终成虚幻。本词也正是基于一种对生命的虚耗万般无奈之下展开的。\n\n上片以“醉别西楼”切入，与第三句的“聚散真容易”之“聚散”相呼应。“西楼”在词作中一向指代欢宴的场地，所以“西楼”为“聚”，而醉别为...", "authors": ["梁晓琳"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127030c26cbf3417f09454", "shortContent": "本词大约是晏几道晚年的作品。晏几道晚年穷困潦倒，每回忆其平生之悲欢离合，也不禁感慨道：“如幻如电。”小晏似乎更倾向认为人的生命是缺少实质性的东西而不可捉摸的，它借着时间而获得现实的体现，又因为时间的流逝而终成虚幻。本词也正是基于一种对生命的虚耗万般无奈之下展开的。\n\n上片以“醉别西楼”切入，与第三句的“聚散真容易”之“聚散”相呼应。“西楼”在词作中一向指代欢宴的场地，所以“西楼”为“聚”，而醉别为...", "authors": ["梁晓琳"], "pressName": "崇文书局"}, {"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "646790bc7f27182da360bb11", "shortContent": "这是一首怀旧词。\n\n首句忆昔，凌空而起。往日醉别西楼（泛指欢宴之所），醒后却浑然不记。这似乎是追忆往日某一幕具体的醉别，又像是泛指所有的前欢旧梦。似实似虚，笔意殊妙。晏幾道自作《小山词序》中说他自己的词，“所记悲欢合离之事，如幻如电，如昨梦前尘”。沈祖棻《宋词赏析》借此说这句词，“极言当日情事‘如幻如电，如昨梦前尘’，不可复得”，“抚今追昔，浑如一梦，所以一概付之‘不记’”，是善体言外之意的。不过...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '', 'indent', 1418828837, '57b931e4d342d3005ac8c5ad', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10727, '生查子', NULL, 161, 267, 1, 2, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'http://baike.baidu.com/view/3428787.htm', '', '关山魂梦长，鱼雁音尘少。两鬓可怜青，只为相思老。
归梦碧纱窗，说与人人道：「真个别离难，不似相逢好。」', '这首词抒写相思怀远之情。前阕怀旧。以「关山」总领词人怀归思亲之根由。词人以显贵公子远涉关山，突感孤单寂寞，魂牵梦系于家中亲人，欲归不得，遂怨关山太长；又不见亲人书信得以慰藉，遂怨替人传递书信的鱼雁太少。以痴语写真情，令人莞尔。「两鬓」二句写词人闷时对镜，见两鬓青青，正是青春华茂，遂觉远离家乡实为虚耗青春，便突发感慨：「哎，可怜哟！我这满头青丝，就要为相思变老喽！」故作誇张，憨态可掬，情趣盎然，颇见性情。
后阕梦归，纯由想象生发。词人怀归情切，于是忽然「梦归碧纱窗」，与爱侣在碧纱窗之闺阁梦中相见，大感快慰，遂向亲爱的人儿倾诉衷肠：「离别实在太难太苦，真不如相逢团聚好！」这是词人亲身感受的一句实话，也是向爱侣表达思慕的一句痴语：「可想死你了！」此又是词人至性痴情的真率发露。此词以简约的文辞抒写至痴真情，真实而亲切，于平淡中见韵味。', '生查（zhā）子：词牌名。原为唐教坊曲，后用为词调。文人词始见于晚唐韩致尧所作。《考正白香词谱》注云：「本名《生楂子》，其后从省笔作『查』。五言八句，唐时作者，平仄多无定...至宋以后始奉魏承班一首为律。」《尊前集》注「双调」。元高拭词注「南吕宫」。朱希真词有「遥望楚云深」句，名《楚云深》。韩涧泉词有「山意入春晴，都是梅和柳」句，名《梅和柳》。又有「晴色入青山」句，名《晴色入青山》。有双调五体，字数有四十、四十一、四十二三种。正体双调，四十字。前后阕各四句，两仄韵。各家平仄颇有出入，与作仄韵五言绝句诗相仿，多抒怨抑之情。
关山：泛指关隘和山川。
鱼雁音尘少：一作“塞雁音书少”。
鱼雁：指书信。《乐府诗集·相和歌辞十三·饮马长城窟行之一》：「呼儿烹鲤鱼，中有尺素书。」《汉书·苏武传》：「教使者谓单于，言天子射上林中，得雁，足有系帛书。」后因以「鱼雁」代称书信。
音尘：音信，消息。
怜：怜惜。
归梦碧纱窗：一作“归傍碧纱窗”。
归梦：归乡之梦。
碧纱窗：装有绿色薄纱的窗。
人人：对所亲近的人的昵称。
真个：确实、真正。', '荒漠凄凉的关山，常常令我魂牵梦萦，那远在塞外的亲人难以寄家信回来。可惜我两鬓秀美的青丝，只因为日日盼望、夜夜相思而渐渐变白了。
到他回来的时候，我要依偎在他怀里，傍着碧绿的纱窗共诉衷肠。我一定要告诉他：“那别离的凄苦真是难耐，哪有团聚在一起好度时光。”', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecca1c6e67846a9219ac0", "shortContent": "张华写有五首《情诗》，这是第五首，是表现游子对妻子的思念之情。\n诗一开始就写游子在野外观览。他的“游目”“逍遥”，显得似乎很悠闲、自在，但从“独延伫”的情状看，又是那么心事重重、有着解不开的愁闷。下面写他目接之景：“兰蕙缘清渠，繁华荫绿渚。”芬芳的兰蕙沿着清清的水渠，美丽的花朵覆盖着碧绿的沙洲，这景色多美啊。从对景物的观赏引起情致的发动，他随即产生下面的联想：“佳人不在兹，取此欲谁与？”原来他的心...", "authors": ["汤华泉"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290bb", "shortContent": "这首词抒发了相思怀远之情。上阕描写远在关外的男儿因思念恋人，两髮逐渐斑白；下阕则叙述因相思之切，故在梦中向恋人倾诉思念之情。最后以“真个别离难，不似相逢好”的感叹作结，既浅显易懂，又饱含深情，发人深省。“人生最苦是别离”，谁又道不是呢？\n“关山魂梦长，鱼雁音尘少”，梦里关山，阻隔重深，极少能够收到恋人的书信。“关山”这一地理空间不仅阻碍了恋人之间的千里传书，更阻断了他们会面的可能，然而却加深了词人...", "authors": ["吕青霞"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127030c26cbf3417f09458", "shortContent": "这首词抒发了相思怀远之情。上阕描写远在关外的男儿因思念恋人，两鬓逐渐斑白；下阕则叙述因相思之切，故在梦中向恋人倾诉思念之情。最后以“真个别离难，不似相逢好”的感叹作结，既浅显易懂，又饱含深情，发人深省。“人生最苦是别离”，谁又道不是呢？\n\n“关山魂梦长，鱼雁音尘少”，梦里关山，阻隔重深，极少能够收到恋人的书信。“关山”这一地理空间不仅阻碍了恋人之间的千里传书，更阻断了他们会面的可能，然而却加深了词...", "authors": ["吕青霞"], "pressName": "崇文书局"}]', '', 'indent', 1418829048, '57b91aa60a2b58005c931960', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10728, '木兰花', NULL, 151, 267, 2, 1, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'http://baike.baidu.com/view/2763430.htm', '', '东风又作无情计，艳粉娇红吹满地。碧楼帘影不遮愁，还似去年今日意。
谁知错管春残事，到处登临曾费泪。此时金盏直须深，看尽落花能几醉。', '这首词抒写伤春惜花之悲情。上片写东风无情，践踏粉红。以“东风无情”总领词人伤春根由。词人运用移情化的拟人手法赋以“东风”意象辣手摧花的无情品格，它将“艳粉娇红”之繁花吹得满地狼藉，繁华美景转瞬消逝，怎不触目伤情？“碧楼”二句点出抒情主人公藏身碧楼，透过珠帘看见东风吹得落花残影纷纷飘坠，遂又生出对珠帘的恼怨，恼怨珠帘遮不住落花残影，又像去年今日惹起了伤春愁绪。一怨东风，二怨珠帘，实为惜花人的痴语，伤心人的至性，借恼怨传达沉痛的悲愁。
下片惜花。“谁知”二句词意顿折，从上片恼怨东风忽反笔转作自恼自怨：“错管”二字乃讲词人不忍心落花狼藉，任人践踏，遂登山临水管起了暮春残花之事。上述三层恼怨，顿挫曲折，将词人自己逼进“疑无路”的境地，于是“此时”二句又作顿转，以“金盏直须深”的痛饮求醉，在落花残尽之前陪落花再陶醉几番！表面上自解自慰，说伤春惜花费泪无益，不如痛饮美酒，恣赏落花，语极旷达，实际上却极为沉痛，较之惋惜更深一层。全词语辞深婉清劲，更显沉痛悲怆之愁怀。', '艳粉娇红：指娇艳的花。
金盏：酒杯的美称。
直须：只管，尽管。', '东风又施行着无情的心计，娇艳的红花被它吹落了满地。青楼上珠帘透入落花残影遮不住零星愁，犹如去年今日又惹伤春意。谁知误管了暮春残红的情事，到处登山临水竟耗费我多少春泪。金杯美酒，此刻只求痛深举杯，直把落花看尽，人生在世，青春短暂，有多少欢乐，还能有几次陶醉！', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74ad911759740c9aa30b", "shortContent": "全词抒写花落春残的感伤。首句“东风又作无情计”，破空而来，笔力沉重。起始就直怨东风，东风无情，而且这种无情并非偶尔，完全出于有意算计，着一“又”字，则不仅是今年如此，远射下面“去年”，着力写出东风的“无情”，同时也就烘衬出内心的愁怨之深，此意直贯全篇。第二句的“艳粉娇红吹满地”，正面描写落花，“粉”是“艳”，“红”是“娇”，不仅描绘了花的色彩，而且写出了花的艳丽娇冶如人。着力写花的美，也就更反衬出...", "authors": ["钟", "陵"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b303572034f65a8b32", "shortContent": "全词抒写花落春残的感伤。首句“东风又作无情计”，破空而来，笔力沉重。起始就直怨东风，东风无情，而且这种无情并非偶尔，完全出于有意算计，着一“又”字，则不仅是今年如此，远射下面“去年”，着力写出东风的“无情”，同时也就烘衬出内心的愁怨之深，此意直贯全篇。第二句的“艳粉娇红吹满地”，正面描写落花，“粉”是“艳”，“红”是“娇”，不仅描绘了花的色彩，而且写出了花的艳丽娇冶如人。着力写花的美，也就更反衬出...", "authors": ["钟", "陵"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592534b56e213e6848036", "shortContent": "全词抒写花落春残的感伤。首句“东风又作无情计”，破空而来，笔力沉重。起始就直怨东风，东风无情，而且这种无情并非偶尔，完全出于有意算计，着一“又”字，则不仅是今年如此，远射下面“去年”，着力写出东风的“无情”，同时也就烘衬出内心的愁怨之深，此意直贯全篇。第二句的“艳粉娇红吹满地”，正面描写落花，“粉”是“艳”，“红”是“娇”，不仅描绘了花的色彩，而且写出了花的艳丽娇冶如人。着力写花的美，也就更反衬出...", "authors": ["钟　陵"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290bc", "shortContent": "晏几道虽出身贵胄，为故相之子，但为人磊落耿直，不愿仰仗父荫。独持清节，不趋时趣，因常遭人排挤，一生仕途蹇仄，陆沉下僚，晚景甚为凄凉。其词作亦多发感怀伤世，自怜自哀之叹，此《木兰花》便是一首惜春伤花之作。\n起笔便是一句长叹，情感沉重，怨东风无情。然而东风无情，人却有情，以人之情反衬东风之无情，更加重了词人内心的哀愁怨怼。“艳粉娇红吹满地”，写春风过后，满地落花之景。“艳粉娇红”极言花事之繁盛，与后面...", "authors": ["马瑶"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127030c26cbf3417f09459", "shortContent": "晏几道虽出身贵胄，为故相之子，但为人磊落耿直，不愿仰仗父荫。独持清节，不趋时趣，因常遭人排挤，一生仕途蹇仄，陆沉下僚，晚景甚为凄凉。其词作亦多发感怀伤世，自怜自哀之叹，此《木兰花》便是一首惜春伤花之作。\n\n起笔便是一句长叹，情感沉重，怨东风无情。然而东风无情，人却有情，以人之情反衬东风之无情，更加重了词人内心的哀愁怨怼。“艳粉娇红吹满地”，写春风过后，满地落花之景。“艳粉娇红”极言花事之繁盛，与后...", "authors": ["马瑶"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312719b73206168b2e0234a", "shortContent": "晏几道虽出身贵胄，为故相之子，但为人磊落耿直，不愿仰仗父荫。独持清节，不趋时趣，因常遭人排挤，一生仕途蹇仄，陆沉下僚，晚景甚为凄凉。其词作亦多发感怀伤世，自怜自哀之叹，此《木兰花》便是一首惜春伤花之作。\n起笔便是一句长叹，情感沉重，怨东风无情。然而东风无情，人却有情，以人之情反衬东风之无情，更加重了词人内心的哀愁怨怼。“艳粉娇红吹满地”，写春风过后，满地落花之景。“艳粉娇红”极言花事之繁盛，与后面...", "authors": ["马瑶"], "pressName": "崇文书局"}]', '王国维《人间词话》：冯梦华《宋六十一家词选·序》谓：“淮海、小山，古之伤心人也。其淡语皆有味，浅语皆有致。”余谓此唯淮海足以当之。小山矜贵有余，但可方架子野、方回，未足抗衡淮海也。', 'indent', 1418829110, '57b9dae98ac2470063002d99', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10729, '木兰花', NULL, 59, 267, 1, 1, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'http://baike.baidu.com/view/2763395.htm', '', '秋千院落重帘暮，彩笔闲来题绣户。墙头丹杏雨余花，门外绿杨风后絮。
朝云信断知何处？应作襄王春梦去。紫骝认得旧游踪，嘶过画桥东畔路。', '这是一首怀旧之词。上片写旧地重游，此乃词人乘紫骝过桥东寻旧游所见。下片追思小云。结尾二句不说词人对这位佳人的住地很熟悉，而用拟人化的手法，托诸骏马。马而有情，何况人乎？紫骝骄嘶，柳映画桥，意境极美，这是虚中有实，实中有虚。“如幻如电，如昨梦前尘”，正是此词的风格所在。词人旧地重游，闲窥绣户，仿佛重睹芳华，这是幻境；佳人有如朝云，飘然远逝，另赴襄王之约，也是幻境；最后骏马骄嘶过画桥，词人更觅游踪去，则将幻境与真境糅合在一起，尤富于浪漫色彩。全词以“秋千院”始，以“东畔路”终，倒卷遥映；上片写景，亦真亦幻；下片怀人，亦虚亦实。善于在瞬间现景中叠现今昔时空之意象，情蕴深婉而有韵致。', '彩笔：江淹有五彩笔，因而文思敏捷。　　襄王春梦：实为先王梦之误传。“先王”游高唐，梦神女荐枕，临去，神女有“旦为行云，暮为行雨”语。（见宋玉《高唐赋序》）　　紫骝：本来指一种马，这里泛指骏马。', '院落里秋千摇曳，重重的帘幕低垂，闲暇时在华丽的门上挥笔题诗。墙里佳人犹如出墙红杏雨后花，门外游子好像绿杨飞絮随风飘。
音讯断了，犹如飞逝的轻云，不知她身处何方？就做个襄王觅神女的好梦让我归去。紫骝马还认得旧时游玩路迹，嘶叫着跑过了画桥东边路。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74acc6e67846a9206b00", "shortContent": "晏幾道友人沈廉叔、陈君龙家，有莲、鸿、蘋、云四歌妓，宴会则清歌娱客，幾道“每得一解，即以草授诸儿”（见《小山词》自序）。及沈、陈或死或病，诸姬亦离散。幾道将词稿缀辑成篇，“考其篇中所记悲欢离合之事，如幻，如电，如昨梦前尘”（同上）。这首词所写的怀旧之思，正是以这样的生活情事为背景的。\n起首二句写旧地重游，似曾相识的情景。在这秋千院落、垂帘绣户之内，仿佛有一位佳人在把笔题诗。佳人是谁，词中未作交代。...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b32cee9a0c24ed9e41", "shortContent": "晏几道友人沈廉叔、陈君龙家，有莲、鸿、蘋、云四歌妓，宴会则清歌娱客，几道“每得一解，即以草授诸儿”（见《小山词》自序）。及沈、陈或死或病，诸姬亦离散。几道将词稿缀辑成篇，“考其篇中所记悲欢合离之事，如幻如电，如昨梦前尘”（同上）。这首词所写的怀旧之思，正是以这样的生活情事为背景的。\n起首二句写旧地重游，似曾相识的情景。在这秋千院落、垂帘绣户之内，仿佛有一位佳人在把笔题诗。佳人是谁，词中未作交代。然...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592534b56e213e6848034", "shortContent": "晏几道友人沈廉叔、陈君龙家，有莲、鸿、\"、云四歌妓，宴会则清歌娱客，几道“每得一解，即以草授诸儿”（见《小山词》自序）。及沈、陈或死或病，诸姬亦离散。几道将词稿缀辑成篇，“考其篇中所记悲欢合离之事，如幻如电，如昨梦前尘”（同上）。这首词所写的怀旧之思，正是以这样的生活情事为背景的。\n\n起首二句写旧地重游，似曾相识的情景。在这秋千院落、垂帘绣户之内，仿佛有一位佳人在把笔题诗。佳人是谁，词中未作交代。...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290bd", "shortContent": "这是一篇记录故地重游的词作，词人回忆起往昔的经历，由此抒发现实的感伤。晏几道在《小山词·自跋》中回忆，友人沈廉叔、陈君龙家有莲、鸿、蘋、云四歌妓，她们时常在宴会上助兴。那时的晏几道，“每得一解，即以草授诸儿”。沈、陈去世后，这些歌妓也四处离散。晏几道把这些词稿整理成篇，“考其篇中所记悲欢离合之事，如幻如电，如昨梦前尘”。\n词的上阕描写园中景致。在黄昏时分，词人到达旧地，物是人非。暮霭朦胧之中大门半...", "authors": ["叶璐熠"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127030c26cbf3417f0945a", "shortContent": "这是一篇记录故地重游的词作，词人回忆起往昔的经历，由此抒发现实的感伤。晏几道在《小山词·自跋》中回忆，友人沈廉叔、陈君龙家有莲、鸿、蘋、云四歌妓，她们时常在宴会上助兴。那时的晏几道，“每得一解，即以草授诸儿”。沈、陈去世后，这些歌妓也四处离散。晏几道把这些词稿整理成篇，“考其篇中所记悲欢离合之事，如幻如电，如昨梦前尘”。\n\n词的上阕描写园中景致。在黄昏时分，词人到达旧地，物是人非。暮霭朦胧之中大门...", "authors": ["叶璐熠"], "pressName": "崇文书局"}, {"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "64679166e49f46528ab22d6e", "shortContent": "晏幾道友人沈廉叔、陈君龙家，有莲、鸿、[插图]、云四歌妓，宴会则清歌娱客，幾道“每得一解，即以草授诸儿”（见《小山词》自序）。及沈、陈或死或病，诸姬亦离散。幾道将词稿缀辑成篇，“考其篇中所记悲欢合离之事，如幻如电，如昨梦前尘”（同上）。这首词所写的怀旧之思，正是以这样的生活情事为背景的。\n\n起首二句写旧地重游，似曾相识的情景。在这秋千院落、垂帘绣户之内，仿佛有一位佳人在把笔题诗。佳人是谁，词中未作...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}]', '', 'indent', 1418829167, '57b95a998ac2470062e2a7ba', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10730, '清平乐', NULL, 238, 267, 1, 2, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'http://baike.baidu.com/view/2786251.htm', '', '留人不住，醉解兰舟去。一棹碧涛春水路，过尽晓莺啼处。
渡头杨柳青青，枝枝叶叶离情。此后锦书休寄，画楼云雨无凭。', '通观全词，当是托为歌女送别情人之作。离别在一个渡口，时间是春天的一个早晨。上阕写送别。“留人”二句以一“留”、一“去”点出送者与行者不同的心态：一方挽留而留不住，一方身不由己，去意已决。表面看留者似落花有意，去者若流水无情。实则一个“醉”字透出其中隐曲：去者亦非寡情绝意，正因离别愁深，遂借酒释愁，以免临别之际在情人面前失态落泪。“一棹”二句写送者目送兰舟远去：一只船桨划破碧波，船儿驶出一条春水路，从两岸清晨黄莺啼叫的杨柳中间穿过，消失到远方。“过尽”二字显现出送者整个目送兰舟由近而远，渐远渐无的空间推移过程，流露出送者情系兰舟的深长眷恋和心逐流水的绵绵离思。
下阕写别情。送者伫立空荡的渡头，唯余青青杨柳，徒然触动离情。“此后”二句抒发怨爱交集的负气之言，其中暗含难言之隐。二句表现的心情是矛盾的。全词先是脉脉含情之语，后转为决绝语，二者相反相成，因多情而生绝望，绝望恰表明不忍割舍之情。', '留人不住：郑文宝《柳枝词》：“亭亭画舸系春潭，直到行人酒半酣。不管烟波与风雨，载将离恨过江南。”此处翻用其意。
兰舟：木兰舟，以木兰树所造之船。此处泛指船只。
锦书：书信的美称。前秦苏若兰织锦为字成回文诗，寄给丈夫窦滔。后世泛称情书为锦书。
云雨：隐喻男女交合之欢。
无凭：靠不住。', '想留住情郎却无济于事，他酒醉后登上画船，扬帆而去。碧波荡漾的春江中，那船儿一定乘风疾驶，黄莺啼晓之声，会充满他的耳际。渡口空空荡荡只剩下杨柳郁郁青青，枝枝叶叶都满含着别意离情。从此后休要寄锦书再诉衷情，画楼里的欢娱不过是一场春梦，那山盟海誓毕竟空口无凭。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74ac0ce818559d05078a", "shortContent": "通观全词，当是托为妓女送别情人之作。离别在一个渡口，时间是春天的一个早晨。\n前六句主写景，但无往非情。“留人不住”四字，扼要地写出送者、行者双方不同的情态：一个曾诚意挽留，一个却去意已定。妓、客身份，见于言外。“留”而“不住”，已启末二句之怨思。从次句看，分手前有一个饯行酒宴。席间那个不忍别的送行女子，想必是“将来的酒共食，尝着似土和泥”，哪里吃得下去；而即将登舟上路的男子，却喝了个“醉”。这又是...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b30ce818559d063b04", "shortContent": "通观全词，当是托为妓女送别情人之作。离别在一个渡口，时间是春天的一个早晨。\n前六句主写景，但无往非情。“留人不住”四字，扼要地写出送者、行者双方不同的情态：一个曾诚意挽留，一个却去意已定。妓、客身份，见于言外。“留”而“不住”，已启末二句之怨思。从次句看，分手前有一个饯行酒宴。席间那个不忍别的送行女子，想必是“将来的酒共食，尝着似土和泥”，哪里吃得下去；而即将登舟上路的男子，却喝了个“醉”。这又是...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290be", "shortContent": "此词是晏几道在中年失意后创作的作品。那时晏几道时常有机会接触青楼女子，但大多只能是萍水相逢，无法进行深入交往。该词与那些送别双方依依不舍的送别词不同，它描绘了一种“不对等”的送别。送者苦苦挽留，行者却去意已决。整首词展现了一位风尘女子对情人的留恋和不舍，基调颇为“残酷”，在美好的春景面前，女子只能眼睁睁地看着情人离开，而自己却对此无能为力。\n全词以女性视角展开。词的上阕以“留人不住”开篇，一来就给...", "authors": ["叶璐熠"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127030c26cbf3417f0945b", "shortContent": "此词是晏几道在中年失意后创作的作品。那时晏几道时常有机会接触青楼女子，但大多只能是萍水相逢，无法进行深入交往。该词与那些送别双方依依不舍的送别词不同，它描绘了一种“不对等”的送别。送者苦苦挽留，行者却去意已决。整首词展现了一位风尘女子对情人的留恋和不舍，基调颇为“残酷”，在美好的春景面前，女子只能眼睁睁地看着情人离开，而自己却对此无能为力。\n\n全词以女性视角展开。词的上阕以“留人不住”开篇，一来就...", "authors": ["叶璐熠"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312719b73206168b2e0234b", "shortContent": "此词是晏几道在中年失意后创作的作品。那时晏几道时常有机会接触青楼女子，但大多只能是萍水相逢，无法进行深入交往。该词与那些送别双方依依不舍的送别词不同，它描绘了一种“不对等”的送别。送者苦苦挽留，行者却去意已决。整首词展现了一位风尘女子对情人的留恋和不舍，基调颇为“残酷”，在美好的春景面前，女子只能眼睁睁地看着情人离开，而自己却对此无能为力。\n全词是以女性视角展开的。词的上阕以“留人不住”开篇，一来...", "authors": ["叶璐熠"], "pressName": "崇文书局"}, {"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "6467914b5e6bb82b8cd0c085", "shortContent": "通观全词，当是托为妓女送别情人之作。离别在一个渡口，时间是春天的一个早晨。\n\n前六句主写景，但无往非情。“留人不住”四字，扼要地写出送者、行者双方不同的情态：一个曾诚意挽留，一个却去意已定。妓、客身份，见于言外。“留”而“不住”，已启末二句之怨思。从次句看，分手前有一个饯行酒宴。席间那个不忍别的送行女子，想必是“将来的酒共食，尝着似土和泥”，哪里吃得下去；而即将登舟上路的男子，却喝了个“醉”。这又...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '', 'indent', 1418839395, '57b913a2165abd0054c06b68', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10731, '阮郎归', NULL, 130, 267, 2, 2, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'http://baike.baidu.com/view/2763483.htm', '', '旧香残粉似当初，人情恨不如。一春犹有数行书，秋来书更疏。
衾凤冷，枕鸳孤，愁肠待酒舒。梦魂纵有也成虚，那堪和梦无。', '这是一首思念行人的闺情词。上片怨行者：由物及人，以“旧香”比“人情”，人不如物，旧日用残的香粉，芳馥似当初，人儿的情意淡了，反恨不如从前。春去秋来，书讯渐少，人情随时光流逝而淡薄。下片述居者：衾冷枕孤离恨长，借酒舒愁愁不解，求之于虚幻的梦境，无奈好梦难成。由行者到居者，由往日到当今，步步递进，收尾更翻进一层，尤见凄婉。其后宋徽宗思故国有“和梦也新来不做”语（《燕山亭》），或即由此脱胎。', '阮郎归：词牌名。
旧香残粉：指旧日残剩的香粉。香粉，女性化妆用品。
疏：稀少。
衾凤：绣有凤凰图纹的彩被。
枕鸳：绣有鸳鸯图案的枕头。
舒：宽解，舒畅。
和：连。', '旧日用残的香粉芳馥似当初，人儿的情意淡了反恨不如。一个春天还寄来几行书信，到了秋天书信越见稀疏。绣凤被儿冷，鸳鸯枕儿孤，郁郁愁肠只待酒来宽舒。梦魂儿纵然有相逢把晤也成虚无，怎忍受连想做个虚幻的梦儿也无路。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74ad5e272d4b2253bb2e", "shortContent": "这是一首居者忆行者的词，也是一首表达男女相思的词。但在欣赏这首词时，先要解答一个问题：词中的居者到底是男方，还是女方？有人认定行者是女方，而居者就是晏幾道本人。这当然不失为一种解释。可是，写男女间别后相思，本是诗词中常见的题材，多半是虚拟。对这首词，如无本事可考，似不必坐实为作者本人忆念其离去的情侣。而这类题材的作品，往往写居者是女方、行者是男方的，生活中多半也是如此。\n词的上片写怨情，怨行者之薄...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b3d635634aee3e9a74", "shortContent": "这是一首居者忆行者的词，也是一首表达男女相思的词。但在欣赏这首词时，先要解答一个问题：词中的居者到底是男方，还是女方？有人认定行者是女方，而居者就是晏几道本人。这当然不失为一种解释。可是，写男女间别后相思，本是诗词中常见的题材，多半是虚拟。对这首词，如无本事可考，似不必坐实为作者本人忆念其离去的情侣。而这类题材的作品，往往写居者是女方、行者是男方的，生活中多半也是如此。\n词的上片写怨情，怨行者之薄...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290bf", "shortContent": "这是一首闺怨词，全词的抒情主人公是一位独守空闺的女子。词中女子埋怨男子的薄情，也述说了自己的惆怅和孤独。字里行间浸透着女子对男子的思念之情，但女子终究未在词中明言这份思念。\n词的开篇“旧香残粉”一句看似口吻平淡，却很有震撼力，似乎是对薄情男子的棒喝。女为悦己者容，但此时，“悦己者”身处他乡异地，相隔遥远。因为无人欣赏她的妆容，这位女子越来越无心打扮，香气淡了，脂粉残了。这里借用《诗经·伯兮》中的“...", "authors": ["叶璐熠"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127030c26cbf3417f0945c", "shortContent": "这是一首闺怨词，全词的抒情主人公是一位独守空闺的女子。词中女子埋怨男子的薄情，也述说了自己的惆怅和孤独。字里行间浸透着女子对男子的思念之情，但女子终究未在词中明言这份思念。\n\n词的开篇“旧香残粉”一句看似口吻平淡，却很有震撼力，似乎是对薄情男子的棒喝。女为悦己者容，但此时，“悦己者”身处他乡异地，相隔遥远。因为无人欣赏她的妆容，这位女子越来越无心打扮，香气淡了，脂粉残了。这里借用《诗经·伯兮》中的...", "authors": ["叶璐熠"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312719b73206168b2e0234c", "shortContent": "这是一首闺怨词，全词的抒情主人公是一位独守空闺的女子。在词中，女子埋怨男子的薄情，也述说了自己的惆怅和孤独。字里行间浸透着女子对男子的思念之情，但女子终究未在词中明言这份思念。\n词的开篇“旧香残粉”一句看似口吻平淡，却很有震撼力，似乎是对薄情男子的棒喝。女为悦己者容，但此时，“悦己者”身处他乡异地，相隔遥远。因为无人欣赏她的妆容，这位女子越来越无心打扮，香气淡了，脂粉残了。这里借用《诗经·伯兮》中...", "authors": ["叶璐熠"], "pressName": "崇文书局"}, {"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "646791d05e6bb82b8cd0c2e9", "shortContent": "这是一首居者忆行者的词，也是一首表达男女相思的词。但在欣赏这首词时，先要解答一个问题：词中的居者到底是男方，还是女方？有人认定行者是女方，而居者就是晏幾道本人。这当然不失为一种解释。可是，写男女间别后相思，本是诗词中常见的题材，多半是虚拟。对这首词，如无本事可考，似不必坐实为作者本人忆念其离去的情侣。而这类题材的作品，往往写居者是女方、行者是男方的，生活中多半也是如此。\n\n词的上片写怨情，怨行者之...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}]', NULL, 'indent', 1418839462, '57b9243b0a2b58005c936f17', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10732, '六幺令', NULL, 82, 267, 2, 1, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'http://baike.baidu.com/view/9945323.htm', '', '绿阴春尽，飞絮绕香阁。晚来翠眉宫样，巧把远山学。一寸狂心未说，已向横波觉。画帘遮匝。新翻曲妙，暗许闲人带偷掐。
前度书多隐语，意浅愁难答。昨夜诗有回文，韵险还慵押。都待笙歌散了，记取来时霎。不消红蜡，闲云归后，月在庭花旧阑角。', '此词描述一位歌女与情人传情密约的内心活动。「绿阴」二句不仅点出季节时令，柳絮的飞舞环绕也是一层比喻，它把歌女因有约会而产生的兴奋紧张的心情做了一番引人联想的比拟。「晚来」二句推出香阁歌女，夜晚时描画远山翠眉，「巧学」显出她的刻意精心。「一寸」、「画帘」数句写歌女在画帘遮护的晚间宴会上「新翻曲妙」的表演。「狂心」、「横波」写出歌女动于心而形于目的激动情绪。「前度」二句讲情人「书多隐语」，难以体会其中隐曲深意，以致犯愁难答。「昨夜」二句讲情人不见回信，又写回文诗寄情，却不料「韵险」，使她懒得苦吟押险韵，诗未和成。「都待」、「不消」数句，便是密约他笙歌散尽，暂留片刻，悄悄到「庭花旧栏角」去等我！那「记取」、「不消」的叮嘱，微妙地显出她对爱情追求的大胆与真率，活脱脱地描绘了一幅「月上柳梢头，人约黄昏后」的爱情场景。全词以客观描述方式叙事抒情，整个过程有一旁观者清的人在，那就是词人，是词人对歌女心理做了细腻微妙的刻画。', '香阁：指女子闺阁。
翠眉：形容女子眉毛青翠。
远山学：即远山眉，又称远山黛，形容女子眉毛如远山清山。
一寸狂心：指女子狂乱激动的春心。
横波：指眼神，目光流转如水波横流。
遮匝：周围，围绕。
偷掐：暗暗地依曲调记谱。掐：掐算，此指按着手指计拍节记谱。
回文：诗体的一种，顺读倒读都可成文。
韵险：难押的韵。
不消：不需要。', '绿树成阴，春天已过完了，柳絮绕着楼阁闺房在飞。傍晚时，我把黛眉巧画成宫中流行的远山眉式样。春心荡漾，难以平静，却什么也没说，但从我乜斜的眼波中已可觉察出来。彩绘的帘幕四围，奏起新谱的曲子，音调真妙啊！我心里暗暗地允许外界闲人偷听到学了去。
上一次来信中，你用了许多隐语，意思倒浅显，我却愁难以作答；昨夜惠赠的诗中，又有回文，韵押得太险了，我还是懒得费神去步你的韵。等到笙歌散尽后，请你记住来时那一瞬间，不需要持红烛照明，闲云归去后，月儿自然就会照在庭院花丛边原来那个栅栏角落里的。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74ad03572034f6596299", "shortContent": "晏幾道的词，多以歌妓舞女为描写对象，题材范围是比较狭窄的，但是，他又能够在这个狭窄的范围之内进行相对广阔的开掘，写出歌妓舞女们的众多生活侧面来，故而并不单调。同时，由于作者熟悉他所描写的对象，对她们关切，同情，所以作品中流露的感情是真挚的，再加上新颖的构思、精美的语言和生动的描绘，于是形成了小晏词的独特的艺术风格。\n这首《六么令》写一位歌女和情人的约会，题材的角度比较新颖；通过这样一个角度，展现女...", "authors": ["王双启"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b42cee9a0c24ed9e43", "shortContent": "晏几道的词，多以歌妓舞女为描写对象，题材范围是比较狭窄的，但是，他又能够在这个狭窄的范围之内进行相对广阔的开掘，写出歌妓舞女们的众多生活侧面来，故而并不单调。同时，由于作者熟悉他所描写的对象，对她们关切、同情，所以作品中流露的感情是真挚的，再加上新颖的构思、精美的语言和生动的描绘，于是形成了小晏词的独特的艺术风格。\n这首《六么令》写一位歌女和情人的约会，题材的角度比较新颖；通过这样一个角度，展现女...", "authors": ["王双启"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290c1", "shortContent": "本词内容颇具故事性，情节丰富，将一位歌女和其情人间的诗文传情写得清新活泼，又丝毫没有半点造作扭捏。上片开篇便点出了晚春时节，“绿阴春尽，飞絮绕香阁”，在这春光渐逝，夏日渐临的时节，柳絮伴春风绕着香阁漫天飞舞，营造了一种纷扬而躁动的氛围。下两句接言“晚来翠眉宫样，巧把远山学”，女主人公终于登场了。这位歌女细描翠眉，殷勤理妆，又巧学“远山眉”的模样，借着对这些局部细节的描写，便已塑造出一位伶俐美貌的歌...", "authors": ["梁晓琳"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127030c26cbf3417f0945d", "shortContent": "本词内容颇具故事性，情节丰富，将一位歌女和其情人间的诗文传情写得清新活泼，又丝毫没有半点造作扭捏。上片开篇便点出了晚春时节，“绿阴春尽，飞絮绕香阁”，在这春光渐逝，夏日渐临的时节，柳絮伴春风绕着香阁漫天飞舞，营造了一种纷扬而躁动的氛围。下两句接言“晚来翠眉宫样，巧把远山学”，女主人公终于登场了。这位歌女细描翠眉，殷勤理妆，又巧学“远山眉”的模样，借着对这些局部细节的描写，便已塑造出一位伶俐美貌的歌...", "authors": ["梁晓琳"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312719c73206168b2e0234e", "shortContent": "本词内容颇具故事性，情节丰富，将一位歌女和其情人间的诗文传情写得清新活泼，又丝毫没有半点造作扭捏。上片开篇便点出了晚春时节，“绿阴春尽，飞絮绕香阁”，在这春光渐逝，夏日渐临的时节，柳絮伴春风绕着香阁漫天飞舞，营造了一种纷扬而躁动的氛围。下两句接言“晚来翠眉宫样，巧把远山学”，女主人公终于登场了。这位歌女细描翠眉，殷勤理妆，又巧学“远山眉”的模样，借着对这些局部细节的描写，便已塑造出一位伶俐而美貌的...", "authors": ["梁晓琳"], "pressName": "崇文书局"}, {"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "6467921c5fc8182fe9aac1a9", "shortContent": "晏幾道的词，多以歌妓舞女为描写对象，题材范围是比较狭窄的，但是，他又能够在这个狭窄的范围之内进行相对广阔的开掘，写出歌妓舞女们的众多生活侧面来，故而并不单调。同时，由于作者熟悉他所描写的对象，对她们关切、同情，所以作品中流露的感情是真挚的，再加上新颖的构思、精美的语言和生动的描绘，于是形成了小晏词的独特的艺术风格。\n\n这首《六么令》写一位歌女和情人的约会，题材的角度比较新颖；通过这样一个角度，展现...", "authors": ["王双启"], "pressName": "上海辞书出版社"}]', '', 'indent', 1418839589, '57b9328b165abd0054c1709a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (10733, '御街行', NULL, 41, 267, 1, 2, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'http://baike.baidu.com/view/2768499.htm', '', '街南绿树春饶絮，雪满游春路。树头花艳杂娇云，树底人家朱户。北楼闲上，疏帘高卷，直见街南树。
阑干倚尽犹慵去，几度黄昏雨。晚春盘马踏青苔，曾傍绿阴深驻。落花犹在，香屏空掩，人面知何处？', '这是一首忆旧怀人的小词，所怀念的当是往昔眷恋的一位女子。“街南绿树”四句为一层，写登楼怅望所见之景，绿树阴浓、杨花铺路、柔云缭绕处有一所朱门宅院，为当年伊人所居。“北楼闲上”到“几度黄昏雨”五句为一层，写自身登楼望人的情态心绪。“晚春盘马”以下为一层，由追忆往日朱门欢会折转到今夕物是人非。融化崔护诗，点明题旨。全词用大量的篇幅描写旧地春景：街南绿树成阴，柳絮如雪铺路，树头花艳如云，花下朱户人家；北楼高矗，帘幕卷起；佳人久倚栏杆远眺，和恋人共度几多黄昏暮雨；二人骑马出游也曾在绿阴深处密语。这大量的忆旧篇幅，反衬出结尾花在楼存，时异人非的今时冷落，令人怅惘不已。全词铺叙有序，结构巧妙，以崔护诗意作结，意味尽犹未尽，咀之无穷。', '御街行：词牌名，又名《孤雁儿》。
饶：充满，多。
雪：这里以形容白色的柳絮。
闲：高大的样子。
疏帘：也作“踩帘”，指稀疏的竹织窗帘，张耒《夏日》有“落落疏帘邀月影，嘈嘈虚枕纳溪声”。
慵去（yōng qù）：懒得离去。
盘马：骑马驰骋盘旋。', '街南绿树浓荫，春天多柳絮，柳絮如雪飘满游春的道路。树顶上杂映着艳花交织的娇云，树荫下是居住人家的朱红门户。闲懒地登上北楼，疏散的珠帘向上高卷，一眼看到遮护艳女朱户的城南树。
倚遍栏杆还懒得离去，经过了几度黄昏细雨。记得暮春时她曾骑马徘徊踏过青苔，曾靠在绿荫深处停马驻足。昔日落花今犹在，华美的屏风却空掩，谁知桃花人面在何处？', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74ad5914587d02f46618", "shortContent": "此词写故地重游中恋旧的情怀，容易令人想起唐诗人崔护《题都城南庄》：“去年今日此门中，人面桃花相映红。人面不知何处去，桃花依旧笑春风。”二者的心情颇类，但小晏词并不落崔诗的窠臼。\n崔诗是从昔到今顺叙，此词却从眼前景象咏起，渐渐勾起回忆，是倒说。上片的开头与结句数字重复（“街南绿树”与“街南树”），颇为别致。细玩词意，原来前四句与后三句乃是倒装，重复处恰是衔接的标志。“街南绿树春饶絮”四句，是北楼南望...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b4911759740c9bcb2a", "shortContent": "此词写故地重游中恋旧的情怀，容易令人想起唐诗人崔护《题都城南庄》：“去年今日此门中，人面桃花相映红。人面不知何处去，桃花依旧笑春风。”二者的心情颇类，但小晏词并不落崔诗的窠臼。\n崔诗是从昔到今顺叙，此词却从眼前景象咏起，渐渐勾起回忆，是倒说。上片的开头与结句数字重复（“街南绿树”与“街南树”），颇为别致。细玩词意，原来前四句与后三句乃是倒装，重复处恰是衔接的标志。“街南绿树春饶絮”四句，是北楼南望...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3e7ccdb86c49f290c2", "shortContent": "本词以景语开篇，“街南绿树春饶絮，雪满游春路”，上片前二句写词人街南游春，柳絮满街飞舞，一如飘雪。这里反用了晋代谢道蕴“柳絮因风起”之句，当时谢氏以柳絮喻飘雪，清新雅致，而小晏反以冬雪形容春物，又是另一番滋味。“树头花艳杂娇云，树底人家朱户”，树上繁花似锦，一片烂漫，“杂”字写出了树上花间中见天边彩云，花与云交相映衬，越发明艳动人。在那“艳花娇云”的掩隐下，在影影绰绰之间，独见一朱门深隐其中。词人...", "authors": ["梁晓琳"], "pressName": "崇文书局"}, {"bookId": "62729e619d822e20f6f7ce92", "bookTitle": "宋词鉴赏辞典", "articleId": "63127030c26cbf3417f0945e", "shortContent": "本词以景语开篇，“街南绿树春饶絮，雪满游春路”，上片前二句写词人街南游春，柳絮满街飞舞，一如飘雪。这里反用了晋代谢道蕴“柳絮因风起”之句，当时谢氏以柳絮喻飘雪，清新雅致，而小晏反以冬雪形容春物，又是另一番滋味。“树头花艳杂娇云，树底人家朱户”，树上繁花似锦，一片烂漫，“杂”字写出了树上花间中见天边彩云，花与云交相映衬，越发明艳动人。在那“艳花娇云”的掩隐下，在影影绰绰之间，独见一朱门深隐其中。词人...", "authors": ["梁晓琳"], "pressName": "崇文书局"}, {"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "64679264b6a81d0c53002a45", "shortContent": "此词写故地重游中恋旧的情怀，容易令人想起唐诗人崔护《题都城南庄》:“去年今日此门中，人面桃花相映红。人面不知何处去，桃花依旧笑春风。”二者的心情颇类，但小晏词并不落崔诗的窠臼。\n\n崔诗是从昔到今顺叙，此词却从眼前景象咏起，渐渐勾起回忆，是倒说。上片的开头与结句数字重复（“街南绿树”与“街南树”），颇为别致。细玩词意，原来前四句与后三句乃是倒装，重复处恰是衔接的标志。“街南绿树春饶絮”四句，是北楼南...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '', 'indent', 1418839638, '57b98f92c4c9710055944b08', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639339, '水浒传 · 第七十一回 · 忠义堂石碣受天文 梁山泊英雄排座次', NULL, 4, 124, 0, 1, '施耐庵', NULL, 10333, '57b9ebb3a633bd005d30998b', '明', 'wen', '文', '', '', '诗曰：
光耀飞离土窟间，天罡地煞降尘寰。
说时豪气侵肌冷，讲处英风透胆寒。
仗义疏财归水泊，报仇雪恨下梁山。
堂堂一卷天文字，付与诸公仔细看。
话说宋公明一打东平，两打东昌，回归山寨忠义堂上，计点大小头领共有一百八员，心中大喜，遂对众兄弟道：“宋江自从闹了江州，上山之后，皆赖托众弟兄英雄扶助，立我为头。今者共聚得一百八员头领，心中甚喜。自从晁盖哥哥归天之后，但引兵马下山，公然保全，此是上天护佑，非人之能。纵有被掳之人，陷于缧绁，或是中伤回来，且都无事。被擒捉者，俱得天佑，非我等众人之能也。今者一百八人，皆在面前聚会，端的古往今来，实为罕有！如今兵刃到处，杀害生灵，无可禳谢大罪。我心中欲建一罗天大醮，报答天地神明眷佑之恩。一则祈保众兄弟身心安乐；二则惟愿朝廷早降恩光，赦免逆天大罪，众当竭力捐躯，尽忠报国，死而后已；三则上荐晁天王早生仙界，世世生生，再得相见。就行超度横亡恶死，火烧水溺，一应无辜被害之人，惧得善道。我欲行此一事，未知众弟兄意下若何？”众头领都称道：“此是善果好事，哥哥主见不差。”吴用便道：“先请公孙胜一清主行醮事，然后令人下山，四边邀请得道高士，就带醮器赴寨。仍使人收买一应香烛纸马，花果祭仪，素馔净食，并合用一应物件。”商议选定四月十五日为始，七昼夜好事。山寨广施钱财，督并干办。日期已近，向那忠义堂前，挂起长幡四首。堂上扎缚三层高台，堂内铺设七宝三清圣像。两班设二十八宿，十二宫辰，一切主醮星官真宰。堂外仍设监坛崔、卢、邓、窦神将。摆列已定，设放醮器齐备。请到道众，连公孙胜共是四十九员。
是日晴明的好，天和气朗，月白风清。宋江、卢俊义为首，吴用与众头领为次拈香，公孙胜作高功，主行斋事，关发一应文书符命，不在话下。当日醮筵，但见：
香腾瑞霭，花簇锦屏。一千条画烛流光，数百盏银灯散彩。对对高张羽盖，重重密布幢幡。风清三界步虚声，月冷九天垂沆瀣。金钟撞处，高功表进奏虚皇；玉佩鸣时，都讲登坛朝玉帝。绛绡衣星辰灿烂，芙蓉冠金碧交加。监坛神将狰狞，直日功曹勇猛。道士齐宣宝忏，上瑶台酌水献花；真人密诵灵章，按法剑踏罡布斗。青龙隐隐来黄道，白鹤翩翩下紫宸。
当日公孙胜与那四十八员道众，都在忠义堂上做醮，每日三朝，至第七日满散。宋江要求上天报应，特教公孙胜专拜青词，奏闻天帝，每日三朝。却好至第七日三更时分，公孙胜在虚皇坛第一层，众道士在第二层，宋江等众头领在第三层，众小头目并将校都在坛下，众皆恳求上苍，务要拜求报应。是夜三更时候，只听得天上一声响，如裂帛相似，正是西北乾方天门上。众人看时，直竖金盘，两头尖，中间阔，又唤做天门开，又唤做天眼开。里面毫光射人眼目，霞彩缭绕，从中间卷出一块火来，如栲栳之形，直滚下虚皇坛来。那团火绕坛滚了一遭，竟攒入正南地下去了。此时天眼已合，众道士下坛来。宋江随即叫人将铁锹锄头掘开泥土，跟寻火块。那地下掘不到三尺深浅，只见一个石碣，正面两侧各有天书文字。有诗为证：
蕊笈琼书定有无，天门开阖亦糊涂。
滑稽谁造丰亨论？至理昭昭敢厚诬。
当下宋江且教化纸满散，平明，斋众道士，各赠与金帛之物，以充衬资。方才取过石碣看时，上面乃是龙章凤篆蝌蚪之书，人皆不识。众道士内有一人，姓何，法讳玄通，对宋江说道：“小道家间祖上留下一册文书，专能辨验天书。那上面自古都是蝌蚪文字，以此贫道善能辨认。译将出来，便知端的。”宋江听了大喜，连忙捧过石碣，教何道士看了，良久说道：“此石都是义士大名，镌在上面。侧首一边是‘替天行道’四字，一边是‘忠义双全’四字。顶上皆有星辰南北二斗，下面却是尊号。若不见责，当以从头一一敷宣。”宋江道：“幸得高士指迷，拜谢不浅！若蒙先生见教，实感大德！唯恐上天见责之言，请勿藏匿，万望尽情剖露，休遗片言。”宋江唤过圣手书生萧让，用黄纸誊写。何道士乃言：“前面有天书三十六行，皆是天罡星。背后也有天书七十二行，皆是地煞星。下面注着众义士的姓名。”观看良久，教萧让从头至后，尽数抄誊。
石碣前面书梁山泊天罡星三十六员：
天魁星呼保义宋江、天罡星玉麒麟卢俊义、天机星智多星吴用、天闲星入云龙公孙胜、天勇星大刀关胜、天雄星豹子头林冲、天猛星霹雳火秦明、天威星双鞭呼延灼、天英星小李广花荣、天贵星小旋风柴进、天富星扑天雕李应、天满星美髯公朱仝、天孤星花和尚鲁智深、天伤星行者武松、天立星双枪将董平、天捷星没羽箭张清、天暗星青面兽杨志、天祐星金枪手徐宁、天空星急先锋索超、天速星神行太保戴宗、天异星赤发鬼刘唐、天杀星黑旋风李逵、天微星九纹龙史进、天究星没遮拦穆弘、天退星插翅虎雷横、天寿星混江龙李俊、天剑星立地太岁阮小二、天竟星船火儿张横、天罪星短命二郎阮小五、天损星浪里白跳张顺、天败星活阎罗阮小七、天牢星病关索杨雄、天慧星拚命三郎石秀、天暴星两头蛇解珍、天哭星双尾蝎解宝、天巧星浪子燕青、石碣背面书地煞星七十二员：、地魁星神机军师朱武、地煞星镇三山黄信、地勇星病尉迟孙立、地杰星丑郡马宣赞、地雄星井木犴郝思文、地威星百胜将韩滔、地英星天目将彭玘、地奇星圣水将单廷圭、地猛星神火将魏定国、地文星圣手书生萧让、地正星铁面孔目裴宣、地阔星摩云金翅欧鹏、地阖星火眼狻猊邓飞、地强星锦毛虎燕顺、地暗星锦豹子杨林、地轴星轰天雷凌振、地会星神算子蒋敬、地佐星小温侯吕方、地祐星赛仁贵郭盛、地灵星神医安道全、地兽星紫髯伯皇甫端、地微星矮脚虎王英、地慧星一丈青扈三娘、地暴星丧门神鲍旭、地然星混世魔王樊瑞、地猖星毛头星孔明、地狂星独火星孔亮、地飞星八臂那吒项充、地走星飞天大圣李衮、地巧星玉臂匠金大坚、地明星铁笛仙马麟、地进星山洞蛟童威、地退星翻江蜃童猛、地满星玉幡竿孟康、地遂星通臂猿侯健、地周星跳涧虎陈达、地隐星白花蛇杨春、地异星白面郎君郑天寿、地理星九尾龟陶宗旺、地俊星铁扇子宋清、地乐星铁叫子乐和、地捷星花项虎龚旺、地速星中箭虎丁得孙、地镇星小遮拦穆春、地嵇星操刀鬼曹正、地魔星云里金刚宋万、地妖星摸着天杜迁、地幽星病大虫薛永、地伏星金眼彪施恩、地僻星打虎将李忠、地空星小霸王周通、地孤星金钱豹子汤隆、地全星鬼脸儿杜兴、地短星出林龙邹渊、地角星独角龙邹润、地囚星旱地忽律朱贵、地藏星笑面虎朱富、地平星铁臂膊蔡福、地损星一枝花蔡庆、地奴星催命判官李立、地察星青眼虎李云、地恶星没面目焦挺、地丑星石将军石勇、地数星小尉迟孙新、地阴星母大虫顾大嫂、地刑星菜园子张青、地壮星母夜叉孙二娘、地劣星霍闪婆王定六、地健星险道神郁保四、地耗星白日鼠白胜、地贼星鼓上蚤时迁、地狗星金毛犬段景住。
当时何道士辨验天书，教萧让写录出来。读罢，众人看了，俱惊讶不已。宋江与众头领道：“鄙猥小吏，原来上应星魁。众多弟兄，也原来都是一会之人。今者上天显应，合当聚义。今已数足，上苍分定位数，为大小二等。天罡、地煞星辰，都已分定次序。众头领各守其位，各休争执，不可逆了天言。”众人皆道：“天地之意，物理数定，谁敢违拗！”宋江遂取黄金五十两酬谢何道士。其余道众，收得经资，收拾醮器，四散下山去了。有诗为证：
忠义堂前启道场，敬伸丹悃醮虚皇。
精诚感得天书降，凤篆龙章仔细详。
月明风冷醮坛深，鸾鹤空中送好音。
地煞天罡排姓字，激昂忠义一生心。
且不说众道士回家去了。只说宋江与军师吴学究、朱武等计议。堂上要立一面牌额，大书“忠义堂”三字。断金亭也换个大牌扁。前面册立三关。忠义堂后建筑雁台一座，顶上正面大厅一所，东西各设两房。正厅供养晁天王灵位；东边房内，宋江、吴用、吕方、郭盛；西边房内，卢俊义、公孙胜、孔明、孔亮。第二坡左一带房内，朱武、黄信、孙立、萧让、裴宣；右一带房内，戴宗、燕青、张清、安道全、皇甫端。忠义堂左边，掌管钱粮仓廒收放，柴进、李应、蒋敬、凌振；右边花荣、樊瑞、项充、李衮。山前南路第一关，解珍、解宝守把；第二关，鲁智深、武松守把；第三关，朱仝、雷横守把。东山一关，史进、刘唐守把；西山一关，杨雄、石秀守把；北山一关，穆弘、李逵守把。六关之外置立八寨，有四旱寨，四水寨。正南旱寨，秦明、索超、欧鹏、邓飞；正东旱寨，关胜、徐宁、宣赞、郝思文；正西旱寨，林冲、董平、单廷圭、魏定国；正北旱寨，呼延灼、杨志、韩滔、彭玘。东南水寨，李俊、阮小二；西南水寨，张横、张顺；东北水寨，阮小五、童威；西北水寨，阮小七、童猛。其余各有执事。从新置立旌旗等项。山顶上立一面杏黄旗，上书“替天行道”四字。忠义堂前绣字红旗二面：一书“山东呼保义”，一书“河北玉麒麟”。外设飞龙飞虎旗，飞熊飞豹旗，青龙白虎旗，朱雀玄武旗，黄钺白旄，青幡皂盖，绯缨黑纛。中军器械外，又有四斗五方旗，三才九曜旗，二十八宿旗，六十四卦旗，周天九宫八卦旗，一百二十四面镇天旗。尽是侯健制造。金大坚铸造兵符印信。一切完备。选定吉日良时，杀牛宰马，祭献天地神明。挂上“忠义堂”、“断金亭”牌额，立起“替天行道”杏黄旗。堂前柱上，立朱红牌二面，各有金书七个字，道是：“常怀贞烈常忠义，不爱资财不扰民”。
宋江当日大设筵宴，亲捧兵符印信，颁布号令：
“诸多大小兄弟，各各管领，悉宜遵守，毋得违误，有伤义气。如有故违不遵者，定依军法治之，决不轻恕。
