INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636554, '鹧鸪天 · 有怀京师上元，与韩叔夏司谏、王夏卿侍郎、曹仲谷少卿同赋', NULL, 0, 180, 1, 1, '向子諲', NULL, 27126, '5835d63467f3560065efd5db', '宋', 'ci', '词', '', '', '紫禁烟花一万重，鳌山宫阙倚晴空。玉皇端拱彤云上，人物嬉游陆海中。
星转斗，驾回龙。五侯池馆醉春风。而今白发三千丈，愁对寒灯数点红。', '向薌林是一位生活在两宋之交的词人。他将自己创作的诗词编为《酒边词》，此书分成「江南新词」和「江北旧词」前后两卷。这样的编排，词人用意很深。南宋胡寅认为他「退江北所作于后，而进江南所作于前，以枯木之心，幻出葩华；酌玄酒之尊，弃置醇味」（《题酒边词》），这种说法大致正确。向薌林前半生亲见北宋社会表面繁荣兴盛，而且在金兵进犯、宋室南渡后，他力主抗金，因得罪秦桧，于是被贬还乡，居保在江西临江。向薌林的晚年词作，多抒写淡泊名利的闲适生活情趣，但也常常怀念北宋徽宗时代的繁盛。这类感旧伤时之作，隐寓着深沉的忧国伤己之恨。这首《鹧鸪天》只注明「有怀京师上元」，未注明作于何年。作者集中另一首词有《清平乐·岩桂盛开戏呈韩叔夏司谏》云：「而今老我薌林，世间百不关心。独喜爱香韩寿，能来同醉花阴。」绍兴九年己未（西元一一三九年）归隐以后词人与韩叔夏常唱和往来，所以这首词亦当为此后数年间所作。
这首词打破了结构上分阕的定格。从文义看，前七句和后两句，是意境迥异、对比鲜明的。
前七句，词人从怀旧入手，以流利轻快的笔法，描绘了汴京紫禁城内外欢度上元佳节的盛况。正月十五之夜，华灯宝柜与月色焰火交辉，华灯叠成的鳌山与华丽的宫殿髙耸云天，至尊的帝王端坐于髙楼之上，万民百姓则嬉戏游玖于街衢之间。斗转星移，龙驾回宫此时万众狂欢更趋髙潮。这幅上元节情景，完全是记实。据南宋孟元老《东京梦华录》回忆，上元的汴京「灯山上彩，金碧相射，锦绣交辉。⋯⋯宣德楼上，皆垂黄缘帘，中一位乃御座。⋯⋯万姓皆在露台下观看，乐人时引万姓山呼。」此外该书还记载的：「别有深坊小巷，绣额珠帘，巧制新妆，竞夸华丽，春情荡飏，酒兴融恰，雅会幽欢，寸阴可惜，景色浩闹，不觉更阑。宝骑马骎骎，香轮辘辘，五陵年少，满路行歌，万戸千门，笙簧未彻。」这从一侧面反映了民间情景，由此我们可以想见豪贵之家此夕宴乐之盛，但如其自序所云「未尝经从」，故从阙略罢了。「五侯」，这是个典故是说汉代外戚、宦官有五人同时封侯之的。故以后用它泛称权贵之家为侯家。
如此良辰美景，是何等繁盛、万众何等欢乐，但在最后两句，词意陡转，在我们面前突现了一个萧索凄清的境界：「而今白发三千丈，愁对寒灯数点红。」「而今」二字，把上元狂欢的画面抛到了遥远的过去，成了一个幻境，这是化实为虚的妙笔；同时，又把词人所处的现实环境一下子推到读者眼前。词人抚今追昔，真有恍若隔世的感觉：当年身为贵胄（向薌林是宋神宗钦圣宪肃皇后之再从姪），曾出入宫闱，备受恩宠，如今却是一个皤然老翁；当年目睹京城繁华，亲历北宋盛况，如今僻居乡里，只能与数点寒灯作伴。
王船山《薑斋诗话》说：「以乐景写哀，以哀景写乐，一倍增其哀乐。」的确如王船山所说这首词将今昔两个画面加以对比，这种盛与衰、乐与哀相互对比的手法，确实收到了强烈的艺术效果。「白发三千丈」借用李白名句，表现愁绪满怀的词人「愁对寒灯数点红」凝聚着词人多少深沉的感慨：是对昔日繁华生活的眷恋？是对往事若梦的人生喟叹？还是因国破家亡而产生的怅恨？抑或是「流水落花春去也，天上人间」的失落感？⋯⋯这一切，词人用一个「愁 」字点破了。
「白发」、「寒灯」二句中，两个描写色彩的字「白」与「红」又互相映衬，渲染了一种凄清的境界。结句凝重，含蕴无穷，以少总多，發人遐思，是全篇传神之笔。', '紫禁：指汴京皇宫。烟花一万重：形容春色浓郁。
烟花：烟云与花朵。
鳌山：元宵节之灯山。
端拱：端坐拱手，无为而治。
玉帝：指皇帝。
五侯：后汉桓帝一日封五个侯爵。此指贵家池馆。', '', '[{"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592544b56e213e6848056", "shortContent": "向子諲是一位生活在南北宋之交的词人。他将自己所作编为《酒边词》，分成“江南新词”和“江北旧词”前后两卷。这样的编排，用意很深，南宋胡寅认为他“退江北所作于后，而进江南所作于前，以枯木之心，幻出葩华；酌玄酒之尊，弃置醇味”（《题酒边词》），大致正确。向子諲前半生亲睹北宋之盛，金兵进犯、宋室南渡后，他力主抗金，因得罪秦桧，于是挂冠还乡，卜居江西临江。晚年词作，多抒写淡于名利的闲适生活情趣，但也常常萦念...", "authors": ["方智范"], "pressName": "上海辞书出版社"}]', '', 'indent', 1527780627, '5ab1f3369f54541c7b20fbb7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636556, '人间词话 ·  第一则', NULL, 190, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '词以境界为最上。有境界，则自成高格，自有名句。五代、北宋之词所以独绝者在此。', '', '', ' 评论诗词以境界为最高标准。一首词如果有境界，自然显得格调高迈、超逸不群。这也正是五代和北宋期间的词之所以独到绝妙的地方啊。 ', NULL, '', 'indent', 1521648550, '5ab2131e17d009688762303e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636557, '人间词话 · 第二则', NULL, 110, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '有造境，有写境，此“理想”与“写实”二派之所由分。然二者颇难分别，因大诗人所造之境必合乎自然，所写之境亦必邻于理想故也。', '', '', '从词人的表现手法上看，境界可以分为“造境”和“写境”两种，这也是西方“理想派”和“写实派”得以区分的缘由。但两种境界比较难以分别。因为大诗人通过想象所构造出来的境地，是一定要与现实生活相符的；而通过写实所描摹出来的境地，也必定是接近于理想化的。', NULL, '', 'indent', 1521648590, '5ab2134c2f301e003684c51e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636558, '人间词话 · 第三则', NULL, 147, 210, 2, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '有有我之境，有无我之境。「泪眼问花花不语，乱红飞过秋千去。」「可堪孤馆闭春寒，杜鹃声里斜阳暮。」有我之境也。「采菊东篱下，悠然见南山。」「寒波澹澹起，白鸟悠悠下。」无我之境也。有我之境，以我观物，故物我皆着我之色彩。无我之境，以物观物，故不知何者为我，何者为物。古人为词，写有我之境者为多，然未始不能写无我之境，此在豪杰之士能自树立耳。', '', '欧阳修的《蝶恋花》：「庭院深深深几许？杨柳堆烟，帘幕无重数。玉勒雕鞍游冶处，楼高不见章台路。　雨横风狂三月暮，门掩黄昏，无计留春住。泪眼问花花不语，乱红飞过秋千去。」
秦少游《踏莎行》：「雾失楼台，月迷津渡，桃源望断无寻处。可堪孤馆闭春寒，杜鹃声里斜阳暮。　驿寄梅花，鱼传尺素，砌成此恨无重数。郴江幸自绕郴山，为谁流下潇湘去！」
陶渊明《饮酒诗·其五》：「结庐在人境，而无车马喧。问君何能尔，心远地自偏。采菊东篱下，悠然见南山。山气日夕佳，飞鸟相与还。此中有真意，欲辨已忘言。」
元遗山《颖亭留别》：「故人重分携，临流驻归驾。乾坤展清眺，万景若相借。北风三日雪，太素秉元化。九山郁峥嵘，了不受陵跨。寒波澹澹起，白鸟悠悠下。怀归人自急，物态本闲暇。壶觞负吟啸，尘土足悲咤。回首亭中人，平林淡如画。」', '从创作的主体关系上看，境界又可以分为「有我之境」和「无我之境」两种。譬如：欧阳永叔《蝶恋花》词中「泪眼问花花不语，乱红飞过秋千去」之句、秦少游《踏莎行》词中「可堪孤馆闭春寒，杜鹃声里斜阳暮」之句，都是属于「有我之境」；而陶渊明《饮酒》诗中「采菊东篱下，悠然见南山」之句、元遗山《颍川留别》诗中「寒波澹澹起，白鸟悠悠下」之句，则都是属于「无我之境」。「有我之境」是站在作者本人的角度去观察认识事物，借物抒怀，所以事物全部显现出作者本人的色彩。「无我之境」则是站在事物的角度去观察认识事物，物我两相忘，最后都分不清哪里是作者，哪里是事物了。古人作词，一般写「有我之境」的比较多，但并不是说就没有人能够写「无我之境」，这在豪迈杰出的人当中自然能够得到完成。 ', NULL, '', 'indent', 1521648731, '5ab213d7ee920a00454c943a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636559, '人间词话 · 第四则', NULL, 73, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '无我之境，人惟于静中得之。有我之境，于由动之静时得之。故一优美，一宏壮也。', '', '', '要写“无我之境”，词人只有在超脱世俗、散淡静谧的心境中才能得到。要写“有我之境”，词人却必须是在强烈情感的动态作用下，保持一种平静的心态去抒发才能得到的。所以，前者显得优美，后者显得宏壮。', NULL, '', 'indent', 1521648768, '5ab213fe2f301e003684c98b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636560, '人间词话 · 第五则', NULL, 72, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '自然中之物，互相关系，互相限制。然其写之于文学及美术中也，必遗其关系限制之处。故虽写实家，亦理想家也。又虽如何虚构之境，其材料必求之于自然，而其构造亦必从自然之法律。故虽理想家，亦写实家也。', '', '', '自然界中万事万物，都是互相联系、互相限制的。但如果将它们体现在文学或美术作品当中，必定要遗弃这些联系和限制的地方。所以说，写实家其实也是理想家。另外，不管怎么去虚构出一种境地，它所用的这些材料，又必然来自于现实中的自然界，而且其中的构造还必须遵从自然界的法则。所以说，理想家其实也是写实家呀。', NULL, '', 'indent', 1521648850, '5ab21448ac502e57c9337bc2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636561, '人间词话 · 第六则', NULL, 68, 210, 1, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '境非独谓景物也，喜怒哀乐亦人心中之一境界。故能写真景物真感情者，谓之有境界。否则谓之无境界。', '', '', '我们所谓的“境”，并非单指景物一种，喜怒哀乐，也是人们心中的一种境界。所以，能写真景物、真感情的，就叫有境界；否则就是无境界。 ', NULL, '', 'indent', 1521649042, '5ab21510a22b9d0045d5bbd5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636562, '人间词话 · 第七则', NULL, 59, 210, 1, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '「红杏枝头春意闹」，着一「闹」字，而境界全出。「云破月来花弄影」，着一「弄」字，而境界全出矣。', '', '宋祁《玉楼春·春景》：「东城渐觉风光好。縠皱波纹迎客棹。绿杨烟外晓寒轻，红杏枝头春意闹。浮生长恨欢娱少。肯爱千金轻一笑。为君持酒劝斜阳，且向花间留晚照。」
张先《天仙子·时为嘉禾小倅，以病眠，不赴府会》：「水调数声持酒听，午醉醒来愁未醒。送春春去几时回？临晚镜，伤流景，往事后期空记省。沙上并禽池上暝，云破月来花弄影。重重帘幕密遮灯，风不定，人初静，明日落红应满径。」', '宋祁《玉楼春》词中有「红杏枝头春意闹」的句子，仅仅是使用了一个「闹」字，整首词的境界就全都出来了。张先《天仙子》词中有「云破月来花弄影」的句子，仅仅是使用了一个「弄」字，整首词的境界也就全都出来了。', NULL, '', 'indent', 1521649163, '5ab21580a22b9d0045d5bf07', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (638376, '杏花天', NULL, 0, 109, 0, 1, '高观国', NULL, 30620, '5858f80e1b69e6006cb18441', '宋', 'ci', '词', '', '', '霁烟消处寒犹嫩。乍门巷、愔愔昼永。池塘芳草魂初醒。秀句吟春未稳。
仙源阻、春风瘦损。又燕子、来无芳信。小桃也自知人恨。满面羞红难问。 ', '', '', '', NULL, '', 'indent', 1532518700, '5b57f0b6808ca4006fa94411', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636563, '人间词话 ·  第八则', NULL, 48, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '境界有大小，不以是而分优劣。“细雨鱼儿出，微风燕子斜。”何遽不若“落日照大旗，马鸣风萧萧。”“宝帘闲挂小银钩”，何遽不若“雾失楼台，月迷津渡”也？', '', '杜甫【水槛遣心二首】之一："去郭轩楹敞，无村眺望赊。澄江平少岸，幽树晚多花。细雨鱼儿出，微风燕子斜。城中十万户，此地两三家。"
杜甫【后出塞五首】之一："朝进东门营，暮上河阳桥。落日照大旗，马鸣风萧萧。平沙列万幕，部伍各见招。中天悬明月，令严夜寂寥。悲笳数声动，壮士惨不骄。借问大将谁，恐是霍嫖姚。"
秦观【浣溪沙】："漠漠轻寒上小楼，晓阴无赖似穷秋，淡烟流水画屏幽。自在飞花轻似梦，无边丝雨细如愁，宝帘闲挂小银钩。"', '境界有大有小，但不能根据它来区分优劣。譬如：杜甫《水槛遣心》诗中的“细雨鱼儿出，微风燕子斜”虽是小境界，怎么就不如他《后出塞》诗中“落日照大旗，马鸣风萧萧”的大境界呢？秦观《浣溪沙》词中的“宝帘闲挂小银钩”虽是小境界，怎么就不如他《踏莎行》词中“雾失楼台，月迷津渡”的大境界呢？', NULL, '', 'indent', 1521649216, '5ab215be9f54541c7b21e430', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636564, '人间词话 ·  第九则', NULL, 40, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '严沧浪《诗话》谓：“盛唐诸公唯在兴趣，羚羊挂角，无迹可求。故其妙处，透澈玲珑，不可凑拍，如空中之音，相中之色，水中之影，镜中之象，言有尽而意无穷。”余谓北宋以前之词亦复如是。然沧浪所谓“兴趣”，阮亭所谓“神韵”，犹不过道其面目，不若鄙人拈出“境界”二字为探其本也。', '', '凑拍：一作“凑泊”。', '南宋的严羽在他的《诗话》里说过：“盛唐诸人，惟在兴趣，羚羊挂角，无迹可求，故其妙处，莹彻玲珑，不可凑拍，如空中之音，相中之色，水中之月，镜中之像，言有尽而意无穷。”我说：北宋以前的词，也是这样的。但严羽所谓的“兴趣”，王士祯所谓的“神韵”，都只不过是说了诗词的面目而已，不如我拈出的“境界”二字直接探求其根本啊。', NULL, '', 'indent', 1521649263, '5ab215ed2f301e003684d89f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636565, '人间词话 ·  第十则', NULL, 33, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '太白纯以气象胜。“西风残照，汉家陵阙”，寥寥八字，遂关千古登临之口。后世唯范文正之《渔家傲》，夏英公之《喜迁莺》，差足继武，然气象已不逮矣。', '', '李白【忆秦娥】："箫声咽，秦娥梦断秦楼月。秦楼月，年年柳色，灞陵伤别。乐游原上清秋节，咸阳古道音尘绝。音尘绝，西风残照，汉家陵阙。"此词现已经考证被认为并非李白之作。
范仲淹【渔家傲】（秋思）："塞下秋来风景异，衡阳雁去无留意。四面边声连角起。千嶂里，长烟落日孤城闭。浊酒一杯家万里，燕然未勒归无计。羌管悠悠霜满地。人不寐，将军白发征夫泪。"
夏竦【喜迁莺令】："霞散绮，月垂钩。帘卷未央楼。夜凉银汉截天流，宫阙锁清秋。瑶台树，金茎露。凤髓香盘烟雾。三千珠翠拥宸游，水殿按凉州。"', '李白的诗作，纯粹依靠整体风貌和格局取胜。他在《忆秦娥》词中写道“西风残照，汉家陵阙”，寥寥八个字，就关闭了千百年来登临者之口。后世只有范仲淹的《渔家傲》和夏竦的《喜迁莺》，勉强可以追随他的足迹，但在气象方面却已是赶不上了。', NULL, '', 'indent', 1521649309, '5ab2161c9f545416f0e9cbb7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636566, '人间词话 ·  第十一则', NULL, 27, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '张皋文谓飞卿之词“深美闳约”，余谓此四字唯冯正中足以当之。刘融斋谓“飞卿精艳绝人”，差近之耳。', '', '张惠言《词选序》："唐之词人，温庭筠最高，其言深美闳约。"
刘熙载《艺概》卷四《词曲概》："温飞卿词精妙绝人，然类不出乎绮怨。"', '张惠言评论说：唐代温庭筠的词“深美闳约”。我说：这四个字只有南唐冯延巳的词才足以担当。刘熙载说：“温庭筠的词精艳绝人”，这个评论差不多接近了。', NULL, '', 'indent', 1521649361, '5ab2164f9f545406e72ccdbb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636567, '人间词话 ·  第十二则', NULL, 23, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '“画屏金鹧鸪”，飞卿语也，其词品似之。“弦上黄莺语”，端己语也，其词品亦似之。正中词品，若欲于其词句中求之，则“和泪试严妆”，殆近之欤？ ', '', '温庭筠【更漏子】："柳丝长，春雨细。花外漏声迢递。惊塞雁，起城乌。画屏金鹧鸪。　香雾薄，透帘幕。惆怅谢家池阁。红烛背，绣帘垂。梦长君不知。"
韦庄【菩萨蛮】："红楼别夜堪惆怅，香灯半卷流苏帐。残月出门时，美人和泪辞。　琵琶金翠羽，弦上黄莺语。劝我早归家，绿窗人似花。"
冯延巳【菩萨蛮】："娇鬟堆枕钗横凤，溶溶春水杨花梦。红烛泪阑干，翠屏烟浪寒。锦壶催画箭，玉佩天涯远。和泪试严妆，落梅飞晓霜。"', '“画屏金鹧鸪”，这是温庭筠所作的词句，他词作的品格和它相似；“弦上黄莺语”，这是韦庄所作的词句，他词作的品格也和它相似。至于冯延巳词作的品格，如果也要他在的词句中找一个，那么，“和泪试严妆”这一句应该差不多接近了吧。', NULL, '', 'indent', 1521649417, '5ab2168844d90418a21243ad', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636568, '人间词话 ·  第十三则', NULL, 24, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '南唐中主词：“菡萏香销翠叶残，西风愁起绿波间。”大有众芳芜秽，美人迟暮之感。乃古今独赏其“细雨梦回鸡塞远，小楼吹彻玉笙寒。”故知解人正不易得。', '', '李璟【浣溪沙】："菡萏香销翠叶残，西风愁起绿波间。还与韶光共憔悴，不堪看。　细雨梦回鸡塞远，小楼吹彻玉笙寒。多少泪珠何限恨，倚阑干。"', '南唐中主李璟在《摊破浣溪沙》一词中写道：“菡萏香销翠叶残，西风愁起绿波间”，给人一种繁花变得荒芜污秽，美人进入暮年的感觉。但自古至今，世人都欣赏词中的另一句：“细雨梦回鸡塞远，小楼吹彻玉笙寒”。由此可知知心人是多么的难得啊。', NULL, '', 'indent', 1521649454, '5ab216adac502e57c9338afd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636569, '人间词话 ·  第十四则', NULL, 22, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '温飞卿之词，句秀也；韦端己之词，骨秀也；李重光之词，神秀也。 ', '', '', '温庭筠的词，辞句秀美。韦庄的词，骨质秀美。李煜的词，神韵秀美。 ', NULL, '', 'indent', 1521649479, '5ab216c69f54541c7b21ea1d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637538, '登眺天目绝顶', NULL, 1, 253, 0, 1, '高濂', NULL, 10013, '57ba82a88ac2470063045693', '明', 'wen', '文', '', '', '武林万山，皆自天目分发，故《地钤》有“天目生来两乳长”偈。冬日木落，作天目看山之游。时得天气清朗，烟云净尽，扶策蹑巅，四望无际。两山东引，高下起伏，屈曲奔腾，隐隐到江始尽，真若龙翔凤舞。目极匹练横隔，知为钱塘江也。外此茫茫，是为东海。几簇松筠，山僧指云：“往宋王侯废冢。”噫！山川形胜，千古一日，曾无改移，奈何故宫黍离，陵墓丘壑，今几变迁哉？重可慨也。', '', '', '', NULL, '', 'indent', 1525454390, '5aec25b1a22b9d00443604a4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636570, '人间词话 ·  第十五则', NULL, 21, 210, 1, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '词至李后主而眼界始大，感慨遂深，遂变伶工之词而为士大夫之词。周介存置诸温、韦之下，可谓颠倒黑白矣。“自是人生长恨水长东”，“流水落花春去也，天上人间”，《金荃》、《浣花》能有此气象耶？', '', '周济《介存斋论词杂著》："毛嫱，西施，天下美妇人也。严妆佳，淡妆亦佳，粗服乱头，不掩国色。飞卿，严妆也。端己，淡妆也。后主则粗服乱头矣。"
后主【相见欢】："林花谢了春红，太匆匆，无奈朝来寒雨晚来风。胭脂泪，相留醉，几时重？自是人生长恨水长东！"
后主【浪淘沙】："帘外雨潺潺，春意阑珊。罗衾不耐五更寒。梦里不知身是客，一晌贪欢。独自莫凭栏，无限江山，别时容易见时难。流水落花春去也，天上人间。"', '词写到南唐后主李煜的时候，眼界才开始雄阔宏大，感慨才开始深远隽永，于是改变戏子浅薄的唱词为士族大夫的诗词。周济竟将李煜搁置在温庭筠和韦庄的下面，简直是颠倒黑白啊。你看看李煜“自是人生长恨水长东”、“流水落花春去也，天上人间”等词句，温庭筠的《金荃集》和韦庄的《浣花集》能有这般气象吗？', NULL, '', 'indent', 1521649528, '5ab216f6ac502e57c9338ce2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636574, '张衡传', NULL, 17, 6, 0, 3, '范晔', NULL, 35882, '5858fcde128fe1006dccddd3', '南北朝', 'wen', '文', '', '', '张衡字平子，南阳西鄂人也。衡少善属文，游于三辅，因入京师，观太学，遂通五经，贯六艺。虽才高于世，而无骄尚之情。常从容淡静，不好交接俗人。永元中，举孝廉不行，连辟公府不就。时天下承平日久，自王侯以下莫不逾侈。衡乃拟班固《两都》作《二京赋》，因以讽谏。精思傅会，十年乃成。大将军邓骘奇其才，累召不应。
衡善机巧，尤致思于天文阴阳历算。安帝雅闻衡善术学，公车特征拜郎中，再迁为太史令。遂乃研核阴阳，妙尽璇玑之正，作浑天仪，著《灵宪》、《算罔论》，言甚详明。
顺帝初，再转复为太史令。衡不慕当世，所居之官辄积年不徙。自去史职，五载复还。
阳嘉元年，复造候风地动仪。以精铜铸成，员径八尺，合盖隆起，形似酒尊，饰以篆文山龟鸟兽之形。中有都柱，傍行八道，施关发机。外有八龙，首衔铜丸，下有蟾蜍，张口承之。其牙机巧制，皆隐在尊中，覆盖周密无际。如有地动，尊则振龙，机发吐丸，而蟾蜍衔之。振声激扬，伺者因此觉知。虽一龙发机，而七首不动，寻其方面，乃知震之所在。验之以事，合契若神。自书典所记，未之有也。尝一龙机发而地不觉动，京师学者咸怪其无征。后数日驿至，果地震陇西，于是皆服其妙。自此以后，乃令史官记地动所从方起。
时政事渐损，权移于下，衡因上疏陈事。后迁侍中，帝引在帷幄，讽议左右。尝问天下所疾恶者。宦官惧其毁己，皆共目之，衡乃诡对而出。阉竖恐终为其患，遂共谗之。衡常思图身之事，以为吉凶倚仗，幽微难明，乃作《思玄赋》以宣寄情志。
永和初，出为河间相。时国王骄奢，不遵典宪；又多豪右，共为不轨。衡下车，治威严，整法度，阴知奸党名姓，一时收禽，上下肃然，称为政理。视事三年，上书乞骸骨，征拜尚书。年六十二，永和四年卒。', '本文是一篇典型的人物传记，以翔实的文笔全面记述了张衡的一生，描述了他在科学、政治、文学等领域的诸多才能。而且详略突出，重点介绍了他在科学上的贡献，其间贯穿了作者对张衡品德的由衷景仰之情。层次清晰，条理分明，一位博学多才、从容淡泊的文人学者形象如在眼前。文章可分为三部分。
第一部分即文章的第1段。记述张衡的学业、品德和文学上的成就。开头两句按历史人物传记的格式，记述张衡的姓名、籍贯与家世。接着介绍其在文学上的造诣。“少善属文”说明他具有先天的禀赋，而“游于三辅，因入京师，观太学”说明他注重社会实践。也正是因为他在青少年时代就打下了如此深厚扎实的基础，并不断自我提高，所以才能“通五经，贯六艺”。在叙述了其“才”后紧接着叙述其德。“虽才高于世，而无骄尚之情，常从容淡静，不好交接俗人。”具有谦虚稳重、超尘拔俗的品格，而面对统治者的招罗，作者连用“不行”“不就”“不应”等词语表现他的不慕荣利的高洁品德。而《二京赋》进一步证实其文学才能及精研精神。
第二部分即文章第2～4段，介绍张衡在科学技术上的成就。重点介绍候风地动仪的结构和功用。第2、3段从整体上概括了张衡在科学上的成就，包括科学发明和理论著作两部分。在介绍其特长时与其职官联系起来，侧面反映了二者互为因果的关系。第四段着重介绍了能代表其成就的候风地动仪。介绍地动仪虽不足二百字，但详尽记述制造时间、质地、大小、形状、内外结构、装饰、功用等，文字精简平实。如介绍构造特点时用“中”“傍”“外”“下”四个方位词为序，便从里到外，从上到下简要而清楚地写出其构造特点。以“似酒尊”描写其形状非常形象具体，用“验之以事，合契若神”的夸张描写和“自书典所记，未之有也”的热烈赞叹着力描写了仪器的准确无误。最后附述了生动有趣的事件验证其功效，使文章于平实中透出情致。
第三部分即文章的第5、6段，介绍张衡在政治上的才干。文章仅选取两件事作为切入点，一是《思玄赋》的由来，表现了张衡心思细密、小心谨慎的形象。一是出任河间相时与奸党斗争一事。“阴知奸党姓名，一时收禽”表现其政治智慧，“上下肃然，称为政理”表现其卓然政绩。这样，笔墨寥寥却写出了一位真实可感、形神丰满的廉吏。
语言凝练平实是本文的突出特点，作者写作时绝少用形容词，尽量抓住史实，描绘时惜墨如金，无一句赘言。但平实精谨中有精彩之处，如候风地动仪一段描写生动形象，说明作者胸中自有丘壑，所以能繁简得体，伸缩自如。也唯其如此，才能将张衡一生中在诸多领域中的大事交代得清楚详明，有条不紊。', '南洋西鄂：南阳郡的西鄂县，在今河南南阳。
属（zhǔ）文：写文章。属，连缀。
游于三辅：在三辅一带游学。游，游历、游学。
京师：指东汉首都洛阳（今河南省洛阳市）。
太学：古代设在京城的全国最高学府，西汉武帝开始设立。
遂：于是。
通：通晓，全面透彻地理解。
贯：贯通，与「通」为近义词。
五经：汉武帝时将《诗》、《书》、《礼》、《易》、《春秋》定名为「五经」。
六艺：指礼、乐、射、御、书、数六种学问和技艺。
高于世：比世上的人高明。于，比。
骄尚之情：骄傲自大的情绪。尚，矜夸自大。
从容：从容稳重，不急躁。
淡静：恬淡宁静，不追慕名利。
永元：东汉和帝刘肇的年号（公元89年-105年）。
连：屡次。
辟：（被）召请（去做官）。
公府，三公的官署。东汉以太尉、司徒、司空为三公。
不就：不去就职。
承平：太平，指国家持续地太平安定。
王侯：封王封侯的大官贵族。
莫：无指代词，表示「没有谁」的意思。
逾侈：过度奢侈。
乃：于是，就。
拟：模仿。
班固：字孟坚，东汉著名的史学家和文学家。
《两都》：指《两都赋》，分《西都赋》、《东都赋》。
《二京赋》：指《西京赋》、《东京赋》。
因：介词，通过。后省宾语「之」。
以：连词。
讽谏：用委婉的语言进行规劝而不直言其事。
精思傅会：精心创作的意思。
乃：才。
邓骘（zhi）：东汉和帝邓皇后的哥哥，立安帝，以大将军的身份辅佐安帝管理政事。
奇其才：认为他的才能出众。奇，认为……奇，形容词的意动用法。奇，奇特、少有的。
累召：多次召请。
应：接受。
机巧：设计制造机械的技艺。巧，技巧、技艺。
致思：极力钻研。致，极、尽。
阴阳：指日月运行规律。
历算：指推算年月日和节气。
雅闻：常听说。雅，副词，素来，常。
术学：关于术数方面的学问，指天文、历算等。
公车：汉代官署名称，设公车令。
特征：对有特出才德的人指名征召，为的与平常的乡举里选相区别，故称特征。
拜：任命，授给官职。
郎中：官名。
再迁：两次调动官职。
太史令：东汉时掌管天文、历数的官，与西汉以前掌管天象历法兼有修史之责的太史令职责不完全相同。
遂乃：于是就。
研核：研究考验。
阴阳：哲学名词，指两种对立的事物，如日月，寒暑等，这里指天象、历算。
妙尽：精妙地研究透了。
璇玑：玉饰的测天仪器。
正：道理。
浑天仪：一种用来表示天象的仪器，类似的天球仪。
《灵宪》：一部历法书。
《算罔》：一部算术书。
详明：详悉明确。
再转：两次调动官职。第一次由太史令调任公车司马令，第二次由公车司马令又调任太史令。
复：又。
当世，指权臣大官。
辄：常常、总是。
积年：多年。
徙：指调动官职。
阳嘉：东汉顺帝刘保的年号（公元132--135）。
候风地动仪：测验地震的仪器。据竺可桢考证，这是两种仪器，一是测验风向的候风仪，一是测验地震的地动仪。
以：用。
员径：圆的直径。员，通「圆」。
合盖隆起：上下两部分相合盖住，中央凸起。隆，高。
尊：同「樽」，古代盛酒器。
饰：装饰。「饰」后省宾语「之」，「之」代候风地动仪。
以：用。据有人研究，候风地动仪外部八方书写不同的篆文以表明方位，脚部装饰山形，东南西北分别绘画代表四方的龙、朱雀、虎、玄武（龟蛇）。
都柱：大铜柱。即地动仪中心的震摆，它是一根上大下小的柱子，哪个方向发生地震，柱子便倒向哪边。都，大。
傍，同「旁」，旁边。
施关发机：设置关键（用来）拔动机件，意思是每组杠杆都装上关键，关键可以拨动机件（指下句所说的「龙」）。
蟾牙机巧制：互相咬合制作精巧的部件。
尊中：酒樽形的仪器里面。
覆盖周密无际：指仪器盖子与樽形仪器相接处没有缝隙。
地动：地震。
机发：机件拨动。
激扬：这里指声音响亮。
伺者：守候观察候风地动仪的人。
发机：拨动了机件。
七首：指其馀七龙之首。龙、首，互文，都指龙首。
验之以事，即以事验之：验，检验、验证。
驿：驿使，古时驿站上传递文书的人。
陇西：汉朝郡名，在今甘肃省兰州市、临洮县、陇西县一带。「陇西」前省介词「于」（在）。
所从方起：从哪个方位发生。
时：当时。
损：腐败。
因：于是。
迁：升迁。
帷幄：指帝王。天子居处必设帷幄，故称。
讽议：讽谏议论；婉转地发表议论。
左右：身边。
疾恶：憎恨坏人坏事。
目之：给他递眼色。
诡对：不用实话对答。
阉竖：对宦官的蔑称。
谗：毁谤。
图身之事：图谋自身安全的事。
吉凶倚伏：祸福相因。出《老子》：「祸兮福所倚，福兮祸所伏。」
幽微难明：幽深微妙，难以看清。
宣寄情志：表达和寄托自己的情意。
永和：也是东汉顺帝的年号（公元136-141）。
国王：即河间王刘政。典宪，制度法令。
豪右：豪族大户，指权势盛大的家族。
不轨：指行动越出常轨的事，即违反法纪的事。
下车：官员初到任。
阴知：暗中察知。
肃然：这里是敬畏恭顺不敢为非做歹的意思。
视事：这里指官员到职工作。
乞骸（hái）骨：古代官吏因年老请求退职的一种说法。
尚书：官名，不同朝代的尚书职权不一样，东汉时是在宫廷中协助皇帝处理政务的官。
卒：死。', '张衡，字平子，是南阳郡西鄂县人。张衡年轻时就擅长写文章，曾到「三辅」一带游学，趁机进了洛阳，在太学学习，于是通晓五经，贯通六艺，虽然才华比一般的人高，但并不因此而骄傲自大。（他）平时举止从容，态度平静，不喜欢与世俗之人交往。永元年间，他被推举为孝廉，却不应荐，屡次被公府征召，都没有就任。此时社会长期太平无事，从王公贵族到一般官吏，没有不过度奢侈的。张衡于是摹仿班固的《两都赋》写了《二京赋》，用它来（向朝廷）讽喻规劝。（这篇赋，他）精心构思润色，用了十年才完成。大将军邓骘认为他的才能出众，屡次征召他，他也不去应召。
张衡善于器械制造方面的巧思，尤其在天文、气象和历法的推算等方面很用心。汉安帝常听说他擅长术数方面的学问，命公车特地征召他，任命他为郎中。两次迁升为太史令。于是，张衡就精心研究、考核阴阳之学（包括天文、气象、历法诸种学问），精辟地研究出测天文仪器的正确道理，制作浑天仪，著成《灵宪》《算罔论》等书籍，论述极其详尽。
（汉）顺帝初年，（张衡）又两次转任，又做了太史令之职。张衡不趋附当时的那些达官显贵，他所担任的官职，总是多年得不到提升。自他从太史令上离任后，过了五年，又回到这里。
顺帝阳嘉元年，张衡又制造了候风地动仪。这个地动仪是用纯铜铸造的，直径有8尺，上下两部分相合盖住，中央凸起，样子像个大酒樽。外面用篆体文字和山、龟、鸟、兽的图案装饰。内部中央有根粗大的铜柱，铜柱的周围伸出八条滑道，还装置着枢纽，用来拨动机件。外面有八条龙。龙口各含一枚铜丸，龙头下面各有一个蛤蟆，张着嘴巴，准备接住龙口吐出的铜丸。仪器的枢纽和机件制造得很精巧，都隐藏在酒尊形的仪器中，覆盖严密得没有一点缝隙。如果发生地震，仪器外面的龙就震动起来，机关发动，龙口吐出铜丸，下面的蛤蟆就把它接住。铜丸震击的声音清脆响亮，守候机器的人因此得知发生地震的消息。地震发生时只有一条龙的机关发动，另外七个龙头丝毫不动。按照震动的龙头所指的方向去寻找，就能知道地震的方位。用实际发生的地震来检验仪器，彼此完全相符，真是灵验如神。从古籍的记载中，还看不到曾有这样的仪器。有一次，一条龙的机关发动了，可是洛阳并没有感到地震，京城的学者都奇怪它这次没有应验。几天后，驿站上传送文书的人来了，证明果然在陇西地区发生地震，大家这才都叹服地动仪的绝妙。从此以后，朝廷就责成史官根据地动仪记载每次地震发生的方位。
当时政治昏暗，中央权力向下转移，张衡于是给皇帝上书陈述这些事。后来被升为侍中，皇帝让他进皇宫，在皇帝左右，对国家的政事提意见。皇帝曾经向张衡问起天下人所痛恨的是谁。宦官害怕张衡说出他们，都给他使眼色，张衡于是没对皇帝说实话。但那些宦党终究害怕张衡成为祸患，于是一起诋毁他。张衡常常思谋自身安全的事，认为福祸相因，幽深微妙，难以看清，于是写了《思玄赋》表达和寄托自己的情思。
（汉顺帝）永和初年，张衡调离京城，担任河间王的相。当时河间王骄横奢侈，不遵守制度法令；又有很多豪族大戸，豪门大户他们一起胡作非为。张衡上任之后治理严厉，整饬法令制度，暗中探得奸党的姓名，一下子同时逮捕，拘押起来，于是上下敬畏恭顺，称赞政事处理得好。（张衡）在河间相位上任职三年，给朝廷上书，请求辞职回家，朝廷任命他为尚书。张衡活了六十二岁，于永和四年去世。', NULL, '', 'indent', 1521676432, '5ab2800ba22b9d0045d8a59e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636587, '幼学琼林·卷二·朋友宾主', NULL, 4, 35, 1, 1, '程登吉', NULL, 36895, '5ab306149f545437fe84c7b2', '明', 'wen', '文', '', '', '取善辅仁，皆资朋友；往来交际，迭为主宾。尔我同心，曰金兰；朋友相资，曰丽泽。东家曰东主，师傅曰西宾。父所交游，尊为父执；己所共事，谓之同袍。心志相孚为莫逆，老幼相交曰忘年。刎颈交，相如与廉颇；总角好，孙策与周瑜。
胶漆相投，陈重之与雷义；鸡黍之约，元伯之与巨卿。与善人交，如入芝兰之室，久而不闻其香；与恶人交，如入鲍鱼之肆，久而不闻其臭。肝胆相照，斯为腹心之友；意气不孚，谓之口头之交。彼此不合，谓之参商；尔我相仇，如同冰炭。民之失德，乾糇以愆；他山之石，可以攻玉。落月屋梁，相思颜色；暮云春树，想望丰仪。
王阳在位，贡禹弹冠以待荐；杜伯非罪，左儒宁死不徇君。分首判袂，叙别之辞；拥彗扫门，迎迓之敬。陆凯折梅逢驿使，聊寄江南一枝春；王维折柳赠行人，遂唱《阳关三叠》曲。频来无忌，乃云入慕之宾；不请自来，谓之不速之客。醴酒不设，楚王戊待土之意怠；投辖于井，汉陈遵留客之心诚。
蔡邕倒屣以迎宾，周公握发而待士。陈蕃器重徐稚，下榻相延；孔子道遇程生，倾盖而语。伯牙绝弦失子期，更无知音之辈；管宁割席拒华歆，调非同志之人。分金多与，鲍叔独知管仲之贫；绨袍垂爱，须贾深怜范叔之窘。要知主宾联以情，须尽东南之美；朋友合以义，当展切偲之诚。', '', '取善辅仁，皆资朋友；往来交际，迭为主宾。善：长处。仁：仁义。资：凭借，依靠。迭：交替，轮流。
尔我同心，曰金兰；朋友相资，曰丽泽。《易经》有云“二人同心，其利断金；同心之言，其臭如兰”
东家曰东主，师傅曰西宾。古人待客，主人在东，宾客在西。
父所交游，尊为父执；己所共事，谓之同袍。执：至交，好友。
心志相孚为莫逆，老幼相交曰忘年。孚：相应，符合。
刎颈交，相如与廉颇；总角好，孙策与周瑜。总角：古代儿童将头发梳成一个向上的小辫，这里指童年时代。
胶漆相投，陈重之与雷义；鸡黍之约，元伯之与巨卿。陈重、雷义：汉代人。人们称他们的关系就象胶漆一样坚固。汉人范巨卿在太学与张元伯分手时约定两年后探望张元伯的母亲。两年后张元伯让母亲准备好鸡与黍招待，他母亲说：“分别两年，千里之外，难以认真。”张元伯说：“范巨卿是信人，一定不会违约。”结果范巨卿果然如期而来。
与善人交，如入芝兰之室，久而不闻其香；与恶人交，如入鲍鱼之肆，久而不闻其臭。鲍鱼：腌鱼。
肝胆相照，斯为腹心之友；意气不孚，谓之口头之交。孚：相应，符合。
彼此不合，谓之参商；尔我相仇，如同冰炭。
民之失施，干糇以愆；他山之石，可以攻玉。干糇以愆：一块干粮也会引来纠纷。糇：干粮。愆：差错，失误。攻：琢磨。
落月屋梁，相思颜色；暮云春树，想望丰仪。颜色：指面容。丰仪：仪表。
王阳在位，贡禹弹冠以待荐；杜伯非罪，左儒宁死不拘君。王阳、贡禹：汉人，二人是挚友。王阳担任益州刺史，贡禹就弹冠相庆，等待他推荐自己。杜伯、左儒：周宣王时人。周宣王无故杀杜伯，左儒力争，后杜伯被杀，左儒也跟着死了。
分首判袂，叙别之辞；拥彗扫门，迎迓之敬。分手：分头。判袂：握在一起的袖子分开。魏文候拿着扫帚打扫门前，迎接朋友。
陆凯折梅逢驿使，聊寄江南一枝春；王维折柳赠行人，遂唱阳关三叠曲。晋陆凯赋诗寄与范晔“折梅逢驿使，寄与陇头人，江南无所有，聊寄一枝春。”
频来无忌，乃云人幕之宾；不请自来，谓之不速之客。幕：指帷帐。速：邀请。
醴酒不设，楚王戊待土之意怠；投辖于井，汉陈遵留客之心诚。楚元王与穆生交情很好，穆生不喜欢喝酒，元王每次设宴就为他准备甜酒，后楚王戊继位，忘了准备甜酒，穆生说：“可以离去了”。汉代陈遵每次宴请宾客，总是把客人的车辖投入井中，不让客人走。
蔡邕倒屣以迎宾，周公握发而待士。
陈蕃器重徐稚，下榻相延；孔子道遇程生，倾盖而语。汉代豫章太守陈蕃很器重隐士徐稚，专门一个坐榻接待他。倾盖：车盖接在一起。
伯牙绝弦失子期，更无知音之辈；管宁割席拒华歆，谓非同志之人。绝：断，拉断。
分金多与，鲍叔独知管仲之贫；绨袍垂爱，须贾深怜范叔之窘。齐国人鲍督牙曾与管仲一起经商，因管仲家贫，总是多分钱与管仲。战国时范睢曾受须贾陷害，后逃去秦国任相国。须贾出使秦，范睢破衣去见，须贾送他一件绨袍。第二天，须贾才发现范睢已担任秦国相国。
要知主宾联以情，须尽东南之美；朋友合以义，当展切偲之诚。《滕王阁序》“宾主尽东南之美”。意思是说宾主都是东南地区优秀的人士。切：肯切。偲：音思，劝勉；又音猜，美好之意。', '', NULL, '', 'indent', 1521712002, '5ab30af617d009688766df74', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636610, '人间词话 ·  第十六则', NULL, 23, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '词人者，不失其赤子之心者也。故生于深宫之中，长于妇人之手，是后主为人君所短处，亦即为词人所长处。', '', '', '词人应该是保持着一颗赤子之心的人，绝假纯真，排除世俗杂念。所以说，出生在深宫大院之中，成长于妇人之手，是李煜作为一名君主的短处，但也是他作为一名词人的长处。 ', NULL, '', 'indent', 1521731457, '5ab356fc9f54543b189d4e4f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636611, '人间词话 ·  第十七则', NULL, 22, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '客观之诗人不可不多阅世，阅世愈深则材料愈丰富、愈变化，《水浒传》、《红楼梦》之作者是也。主观之诗人不必多阅世，阅世愈浅则性情愈真，李后主是也。', '', '', '客观的诗人，不能不多去阅历世俗风情。在社会生活中经历越深入的人，所写的材料就能越丰富，越显得变化多端，譬如《水浒传》、《红楼梦》的作者就是这样的。而主观的诗人，不必多去阅历世俗风情。在社会生活中经历越浅薄的人，他的性情就越真切纯粹，譬如李煜就是这样的人。 ', NULL, '', 'indent', 1521731529, '5ab357482f301e1c2c2ac86b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636612, '人间词话 ·  第十八则', NULL, 33, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '尼采谓：“一切文学，余爱以血书者。”后主之词，真所谓以血书者也。宋道君皇帝《燕山亭》词亦略似之。然道君不过自道身世之戚，后主则俨有释迦、基督担荷人类罪恶之意，其大小固不同矣。 ', '', '宋徽宗【燕山亭】（北行见杏花）："裁翦冰绡，轻叠数重，淡著燕脂匀注。新样靓妆，艳溢香融，羞杀蕊珠宫女。易得凋零，更多少无情风雨。愁苦。闲院落凄凉，几番春暮。　凭寄离恨重重，这双燕何曾，会人言语。天遥地远，万水千山，知他故宫何处？怎不思量？除梦里有时曾去。无据。和梦也、新来不做。"', '德国哲学家尼采说：“一切文学，我爱用血来书写的人。”李煜的词，真可以说是用血来写就的了。宋徽宗赵佶那首《燕山亭》的词略微有点相似。但赵佶只不过自己说自己的身世悲戚罢了，李煜则俨然有释迦牟尼和耶稣基督背负人类罪恶、拯救世人的感觉，两者思想境界的大小是完全不一样的。 ', NULL, '', 'indent', 1521731569, '5ab3576e9f545437fe8712f0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636613, '人间词话 ·  第十九则', NULL, 14, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '冯正中词虽不失五代风格，而堂庑特大，开北宋一代风气。与中、后二主词皆在《花间》范围之外，宜《花间集》中不登其只字也。', '', '龙沐勋《唐宋名家词选》："案《花间集》多西蜀词人，不采二主及正中词，当由道里隔绝，又年岁不相及有以致然。非因流派不同，遂尔遗置也。王说非是。"', '冯延巳的词虽然保留有五代的风格，但堂庑格局显得特别开阔宏大，开启了北宋一代词作的风气，与李璟、李煜的词都在《花间集》的范围之外，所以不宜在《花间集》中登录他们的片词只字呀。', NULL, '', 'indent', 1521731609, '5ab357919f54541d2c3aa1d4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636657, '妙法莲华经 · 常不轻菩萨品第二十', NULL, 0, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%A6%99%E6%B3%95%E8%8E%B2%E5%8D%8E%E7%BB%8F/1772696?fr=aladdin', '', '尔时，佛告得大势菩萨摩诃萨：汝今当知！若比丘、比丘尼、优婆塞、优婆夷持法花经者，若有恶口、骂詈、诽谤，获大罪报，如前所说;其所得功德，如向所说，眼、耳、鼻、舌、身、意清净。得大势！乃往古昔，过无量无边不可思议阿僧祇劫，有佛名威音王如来、应供、正遍知、明行足、善逝、世间解、无上士、调御丈夫、天人师、佛、世尊。劫名离衰，国名大成。其威音王佛，于彼世中，为天、人、阿修罗说法，为求声闻者，说应四谛法，度生老病死，究竟涅槃;为求辟支佛者，说应十二因缘法;为诸菩萨，因阿耨多罗三藐三菩提，说应六波罗蜜法，究竟佛慧。
得大势！是威音王佛，寿四十万亿那由他恒河沙劫;正法住世劫数，如一阎浮提微尘;像法住世劫数，如四天下微尘。其佛饶益众生已，然后灭度。正法、像法灭尽之后，于此国土复有佛出，亦号威音王如来、应供、正遍知、明行足、善逝、世间解、无上士、调御丈夫、天人师、佛、世尊。如是次第有二万亿佛，皆同一号。
最初威音王如来既已灭度，正法灭后，于像法中，增上慢比丘有大势力。尔时有一菩萨比丘名常不轻。得大势！以何因缘名常不轻？是比丘，凡有所见——若比丘、比丘尼、优婆塞、优婆夷——皆悉礼拜赞叹而作是言：我深敬汝等，不敢轻慢。所以者何？汝等皆行菩萨道，当得作佛。而是比丘，不专读诵经典，但行礼拜，乃至远见四众，亦复故往礼拜赞叹而作是言：我不敢轻于汝等，汝等皆当作佛。四众之中，有生嗔恚、心不净者，恶口骂詈言：是无智比丘从何所来？自言：我不轻汝。而与我等授记，当得作佛。我等不用如是虚妄授记。如此经历多年，常被骂詈，不生嗔恚，常作是言：汝当作佛。说是语时，众人或以杖木瓦石而打掷之，避走远住，犹高声唱言：我不敢轻于汝等，汝等皆当作佛。以其常作是语故，增上慢比丘、比丘尼、优婆塞、优婆夷，号之为常不轻。
是比丘临欲终时，于虚空中，具闻威音王佛先所说法华经二十千万亿偈，悉能受持，即得如上眼根清净、耳鼻舌身意根清净。得是六根清净已，更增寿命二百万亿那由他岁，广为人说是法华经。
于时增上慢四众——比丘、比丘尼、优婆塞、优婆夷——轻贱是人，为作不轻名者，见其得大神通力、乐说辩力、大善寂力，闻其所说，皆信伏随从。是菩萨复化千万亿众，令住阿耨多罗三藐三菩提。命终之后，得值二千亿佛，皆号日月灯明，于其法中，说是法华经。以是因缘，复值二千亿佛，同号云自在灯王，于此诸佛法中，受持读诵，为诸四众说此经典故，得是常眼清净，耳、鼻、舌、身、意诸根清净，于四众中说法，心无所畏。得大势！是常不轻菩萨摩诃萨，供养如是若干诸佛，恭敬、尊重、赞叹、种诸善根，于后复值千万亿佛，亦于诸佛法中说是经典，功德成就，当得作佛。
得大势！于意云何？尔时常不轻菩萨岂异人乎？则我身是。若我于宿世不受持读诵此经、为他人说者，不能疾得阿耨多罗三藐三菩提。我于先佛所，受持读诵此经、为人说故，疾得阿耨多罗三藐三菩提。得大势！彼时四众——比丘、比丘尼、优婆塞、优婆夷——以嗔恚意轻贱我故，二百亿劫常不值佛、不闻法、不见僧，千劫于阿鼻地狱受大苦恼。毕是罪已，复遇常不轻菩萨，教化阿耨多罗三藐三菩提。
得大势，于汝意云何？尔时四众常轻是菩萨者，岂异人乎？今此会中跋陀婆罗等五百菩萨、师子月等五百比丘、尼思佛等五百优婆塞，皆于阿耨多罗三藐三菩提不退转者是。
得大势！当知是法华经，大饶益诸菩萨摩诃萨，能令至于阿耨多罗三藐三菩提。是故诸菩萨摩诃萨，于如来灭后，常应受持、读诵、解说、书写是经。
尔时世尊欲重宣此义，而说偈言：
　　过去有佛，号威音王，神智无量，
　　将导一切，天人龙神，所共供养。
　　是佛灭后，法欲尽时，有一菩萨，
　　名常不轻。时诸四众，计着于法。
　　不轻菩萨，往到其所，而语之言：
　　我不轻汝，汝等行道，皆当作佛。
　　诸人闻已，轻毁骂詈;不轻菩萨，
　　能忍受之。其罪毕已，临命终时，
　　得闻此经，六根清净。神通力故，
　　增益寿命，复为诸人，广说是经。
　　诸着法众，皆蒙菩萨，教化成就，
　　令住佛道。不轻命终，值无数佛，
　　说是经故，得无量福，渐具功德，
　　疾成佛道。
　　彼时不轻，则我身是。时四部众，
　　着法之者，闻不轻言：汝当作佛。
　　以是因缘，值无数佛。此会菩萨，
　　五百之众，并及四部，清信士女，
　　今于我前，听法者是。我于前世，
　　劝是诸人，听受斯经，第一之法。
　　开示教人，令住涅槃，世世受持，
　　如是经典。
　　亿亿万劫，至不可议，时乃得闻，
　　是法华经。亿亿万劫，至不可议，
　　诸佛世尊、时说是经。是故行者，
　　于佛灭后，闻如是经，勿生疑惑。
　　应当一心、广说此经，世世值佛，
　　疾成佛道。
', '妙法莲华经（Saddharmapundarika-sutra），简称《法华经》，在古印度、尼泊尔等地长期流行。在克什米尔、尼泊尔和中国新疆、西藏等地有40多种梵文版本，分为尼泊尔体系、克什米尔体系（基尔基特）和新疆体系。尼泊尔体系版本约为11世纪后作品，保持完整，已出版5种校订本。1983年北京民族文化宫图书馆用珂罗版彩色复制出版了由尼泊尔传入、珍藏于西藏萨迦寺的法华经。', '', '这时，释迦牟尼佛告诉大势至菩萨说：你现在应当知道，如果比丘、比丘尼、男女居士能够受持这部《法华经》，那么，若有谁对他们恶言相加、辱骂诽谤，如前面所说，谁便会获得很大的罪报，而受持《法华经》者因此所提到的功德，却如刚才所说，能获得眼、耳、鼻、舌、身、意等六根的清净。大势至，从现在向往昔过无量无边不可胜数阿僧祇劫的漫长岁月，在这个极其遥远的时代里，有一位佛，名叫威音王如来，同时具备十种称号，即应供、正遍知、明行足、善逝、世间解、无上士、调御丈夫、天人师、佛、世尊。
当时所处的劫，名叫离衰;所居住的国，名叫大成。这位威音王佛，在他所处的时代中，为天神、人类和阿修罗等三善道中的众生说法。其中为求声闻果的人说苦、集、灭、道的四谛之法，以救度他们的生、老、病、死诸苦，达到终极的涅槃境界，为求辟支佛果的人讲十二因缘之法;为求证至高无上的佛智的菩萨们讲布施、持戒、忍辱、精进、禅定、智慧等六波罗蜜之法，使他们最终成就佛的智慧。
大势至菩萨，这位威音王佛的寿命长达四十万亿兆恒河的所有沙数那么多的劫数。这位佛的正法存在于世的劫数相当于一个阎浮提洲粉为微尘总数。这位佛的像法存在于世的劫数，相当于四大部洲粉为微尘所得的微尘总数。这位如来世尊使所有的众生受到教益、得到救度之后，便进入涅槃，自我灭度。此佛的正法、像法完全消亡之后，在他的那块国土上又有一佛出世，此佛的名字也叫威音王如来，同时具备十种称号，即应供、正遍知、明行足、善逝、世间解、无上士、调御丈夫、天人师、佛、世尊。像这样依次辗转，一共有二万亿个佛先后主持教化，他们的名号完全一样。
最初的那位威音王如来灭度之后，直到他的正法也消灭无闻的像法时代中，轻狂傲慢的比丘拥有强大的势力。那时，有一位修菩萨法门的比丘，名叫常不轻。大势至菩萨，你知道他为什么叫常不轻呢？因为这位比丘对凡是他所遇到的人，不论其是比丘还是比丘尼，不论是男居士还是女居士，都要施行叩拜，称扬赞叹，并对他们说：我深深地敬仰你们，不敢对你们有半点轻慢，为什么呢？因为你们都修行菩萨之道，将会成为如来世尊。而这位常不轻比丘，并不专一地读诵经典，只是遍行礼拜甚至远远看见比丘、比丘尼、男居士、女居士等四众弟子，他也要特意走上前去，对他们施行礼叩拜，称扬赞叹，并且说道：我不敢轻慢你们，你们皆当作佛。
四众弟子中有的人心地不净，产生瞋怒，恶言恶语地骂道：这个没有智慧的比丘，从什么地方跑到这里，自言自语什么我不轻慢你们，甚至为我们授记作佛。我们不需要这种虚妄的授记。这样，经历了好多年，常不轻经常被骂，但他从不生气发怒，始终这么说：你将成佛。说这种话时，众人有时用手杖、木条、瓦块、石头等打他。他只好躲避，跑到很远的地方，但嘴里依然高声大呼：我不敢轻慢你们，你们皆当作佛！因为这位比丘经常说这样的说，所以，轻狂傲慢的比丘、比丘尼、男居士、女居士便给他取了一个名号叫常不轻。
这位比丘年老临终之时，从虚空中完全听到威音王佛先所说的《法华经》二千万亿句，并对此完全能够受持，于是他便获得了如上所述的眼根清净以及耳根、鼻根、舌根、身根、意根等六根清净。获得了广泛为众人演说这部《法华经》。
这个时候，那些轻狂傲慢的比丘、比丘尼、男居士、女居士，特别是轻贱此人并为他起名常不轻的人，见他获得了巨大的神通之力以及乐说雄辨的演讲能力和身心善良的忍辱能力，于是，他们听了这位比丘的说法，便全部信受拜伏，随从他一起修道。这位常不轻菩萨又教化了千万亿个众生，使他们都获得了至高无上的圣智。命终之后，他又多次转生，遇到了二千亿个佛，这些佛的名号都叫日月灯明。他在这些佛的法化事业中，继续演说这部《法华经》，由于这个缘故，他又遇到了二千亿个佛，这些佛的名号都叫作自在灯王佛。
在这些佛的法化事业中，他依然受持、读诵并为四众弟子演说这部经典。由于这个缘故，他又获得了眼根清净、耳根、鼻根、舌根、身根、意根等六根清净，所以，他在四众弟子中说法，心中没有任何怖畏。大势至菩萨，这位常不轻大菩萨供养了这么多的如来世尊都非常恭敬，非常尊重，并进行了称颂赞叹，从而种下了很多善根。此后，这位常不轻菩萨又遇到了千万亿个佛，在这些佛的法化事业中，他还是演说这部经典，终于成就了所有的功德，应当就要作佛了。
大势至菩萨，在你看来，那时的常不轻菩萨是旁人吗？其实，那时的常不轻菩萨就是我释迦牟尼佛的前身。如果我在前世不受持、读诵这部经典，不为他人演说，那么，我就不会这么快地得到至高无上的圣智。因我在原先的如来世尊那里，受持、读诵这部经典，并为他人演说，所以，我才很快地得到了至高无上的圣智。大势至菩萨，那时的四众弟子，即比丘、比丘尼、男居士、女居士，以瞋怒的心态轻视我、卑贱我，因此，他们在二百亿劫的岁月中，一直遇不到佛，听不到法，看不到僧。他们无缘遇到佛、法、僧三宝，所以在长达一千劫的时间里，他们转生于无间地狱中遭受巨大的痛苦。等受完了这些罪报之后，他们又转生人世，再次遇到常不轻菩萨，受其教化，走上了求证至高无上的圣智的道路。
大势至菩萨，在你看来，那时四众弟子中经常轻视这位菩萨的人难道是旁人吗？其实，他们就是今天法华会上的跋陀婆罗等五百位菩萨、师子月等五百位比丘、尼思佛等五百位男居士。他们如今已在求证至高无上的圣智的道路上，全部达到了不退转的阶位。
大势至菩萨，你应当知道，这部《法华经》对所有的菩萨、大菩萨都是有巨大的益处，能使他们成就至高无上的圣智。所以，一切的菩萨、大菩萨在如来灭度之后都应该时常受持、读诵、解说、书写这部经典。
这时，释迦牟尼佛欲重宣此义，便又以偈颂格式复述道：过去有位佛，名叫威音王，此佛的神通无量、智慧无量。他接引并指导一切众生，受到天神、人类和各种龙神的共同供养。此佛灭度后，佛法将灭时，有一位菩萨，名叫常不轻。那时，四众弟子执著于法相，故而滋生了轻狂傲慢的心理。常不轻菩萨来到他们所在的地方，对他们说：我不轻视你们，你们都在修道，都会成佛。这些人听了之后，对他轻视、诽谤、辱骂，常不轻菩萨皆能忍受。
这位菩萨之所以受到如此轻视与毁骂，都是前世所造罪业的缘故。当这种罪业完毕之后，常不轻菩萨得以听到这部《法华经》，获得六根清净的神通之力，从而延长了寿命，又为其他人广泛讲说此经。原来执著于法相的那些四众弟子都蒙这位菩萨教化，有所成就，从而进住于无上的佛道。常不轻菩萨此生命终之后，又多次转生，生生世世之中遇到无数个佛。由于他继续演说此经，所以获得了无量的福报，逐渐具足了功德，从而迅速成就了佛道。
那时的常不轻菩萨，就是我的前身。那时执著于法相的四众弟子，因为听到常不轻菩萨说：你当作佛，所以他们后来曾遇到无数位佛。现在法会中的五百位菩萨及比丘、比丘尼、男居士、女居士等四众弟子，如今正在我的面前听闻佛法，他们就是当时执著于法相的那些四众弟子。我在前世曾劝这些人听受此经的第一妙法，不断地开示教化他们，使他们能够进住于涅槃解脱的境界，并生生世世受持这部经典。
经过亿亿万劫甚至不可思议长的劫数，才能够听到这部《法华经》。经过亿亿万劫甚至不可思议长的劫数，诸佛才讲这部《法华经》。所以，修行者在佛灭度之后，若能听到这部经典，就不要产生疑惑，应当一心一意地广泛演说此经。果能如此，那么，他们生生世世都会遇到如来世尊，从而能够很快地成就佛道。', NULL, '', 'indent', 1526663447, '5ab526f0ac502e57c9459e1c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642073, '幽梦影 · 卷一 · 四十二', NULL, 3, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '一岁诸节，以上元为第一，中秋次之，五日、九日又次之。', '', '五日：指端午节。
九日：指重阳节。', '', NULL, '', 'indent', 1556016632, '5cbe7d77a3180b7832e6c7fc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636614, '人间词话 ·  第二十则', NULL, 16, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '正中词除《鹊踏枝》、《菩萨蛮》十数阕最煊赫外，如《醉花间》之“高树鹊衔巢，斜月明寒草”，余谓韦苏州之“流萤渡高阁”，孟襄阳之“疏雨滴梧桐”不能过也。 ', '', '冯延巳【醉花间】："晴雪小园春未到。池边梅自早。高树鹊衔巢，斜月明寒草。　山川风景好。自古金陵道。少年看却老。相逢莫厌醉金杯，别离多，欢会少。"
韦应物【寺居独夜寄崔主簿】："幽人寂无寐，木叶纷纷落。寒雨暗深更，流萤渡高阁。坐使青灯晓，还伤夏衣薄。宁知岁方晏，离居更萧索。"
《全唐诗》卷六：孟浩然句，"微云淡河汉，疏雨滴梧桐。"唐王士源《孟浩然集》序云："浩然尝闲游秘省，秋月新霁，诸英华赋诗作会。浩然句云「微云淡河汉，疏雨滴梧桐。」举座嗟其清绝，咸阁笔不复为继。"', '冯延巳的词除了《鹊踏枝》、《菩萨蛮》等十数阕最煊赫外，如《醉花间》中“高树鹊衔巢，斜月明寒草”的词句，我觉得韦应物的“流萤渡高阁”和孟浩然的“疏雨滴梧桐”，都不能超过它。', NULL, '', 'indent', 1521731648, '5ab357bf9f54543687b171d2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636615, '人间词话 ·  第二十一则', NULL, 18, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '欧九《浣溪沙》词“绿杨楼外出秋千”，晁补之谓只一“出”字，便后人所不能道。余谓此本于正中《上行杯》词“柳外秋千出画墙”，但欧语尤工耳。', '', '欧阳修【浣溪沙】："堤上游人逐画船，拍堤春水四垂天。绿杨楼外出秋千。　白发戴花君莫笑，六么催拍盏频传。人生何处似尊前。"
冯延巳【上行杯】："落梅著雨消残粉，云重烟轻寒食近。罗幕遮香，柳外秋千出画墙。　春山颠倒钗横凤，飞絮入帘春睡重。梦里佳期，只许庭花与月知。"', '欧阳修《浣溪沙》词中有一句：“绿杨楼外出秋千”。晁补之认为：只这一个“出”，便说出了后人所不能说的味道。我说：其实，冯延巳早已在《上行杯》一词中写过“柳外秋千出画墙”，但欧阳修的显得更加工巧罢了。 ', NULL, '', 'indent', 1521731685, '5ab357e22f301e1c2c2acccc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636616, '人间词话 ·  第二十二则', NULL, 15, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '梅圣俞《苏幕遮》词：“落尽梨花春又了。满地残阳，翠色和烟老。”刘融斋谓少游一生似专学此种。余谓冯正中《玉楼春》词：“芳菲次第长相续，自是情多无处足，尊前百计得春归，莫为伤春眉黛促。”永叔一生似专学此种。', '', '梅尧臣【苏幕遮】（草）："露堤平，烟墅杳。乱碧萋萋，雨后江天晓。独有庚郎年最少。窣地春袍，嫩色宜相照。接长亭，迷远道。堪怨王孙，不记归期早。落尽梨花春又了。满地残阳，翠色和烟老。"
刘熙载《艺概》卷四《词曲概》引此词云："此一种似为少游开先。"
冯延巳【玉楼春】："雪云乍变春云簇，渐觉年华堪送目。北枝梅蕊犯寒开，南蒲波纹如酒绿。芳菲次第还相续，不奈情多无处足。尊前百计得春归，莫为伤春眉黛促。"', '梅尧臣《苏幕遮》一词有：“落尽梨花春事了。满地斜阳，翠色和烟老”句。刘熙载说：秦观一生似乎专学这种风格。按此，我认为：冯延巳《玉楼春》一词有：“芳菲次第长相续，自是情多无处足。尊前百计得春归，莫为伤春眉黛促”句，欧阳修一生似乎专学这种风格。', NULL, '', 'indent', 1521731733, '5ab3580f9f54543b189d5623', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636617, '人间词话 ·  第二十三则', NULL, 17, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '人知和靖《点绛唇》、圣俞《苏幕遮》、永叔《少年游》三阕为咏春草绝调，不知先有正中“细雨湿流光”五字，皆能摄春草之魂者也。 ', '', '林逋【点绛唇】（草）："金谷年年，乱生春色谁为主。余花落处，满地和烟雨。　又是离愁，一阕长亭暮。王孙去。萋萋无数，南北东西路。"
梅尧臣【苏幕遮】见二二注。
欧阳修【少年游】："阑干十二独凭春，晴碧远连云。千里万里，二月三月，行色苦愁人。　谢家池上，江淹浦畔，吟魄与离魂。那堪疏雨滴黄昏，更特地忆王孙。"
冯延巳【南乡子】："细雨湿流光，芳草年年与恨长。烟锁凤楼无限事，茫茫。鸾镜鸳衾两断肠。　魂梦任悠扬，睡起杨花满绣床。薄幸不来门半掩，斜阳。负你残春泪几行。"', '大家都知道林逋的《点绛唇》、梅尧臣的《苏幕遮》和欧阳修的《少年》三阕词为歌咏春草的绝佳词作，却不知已先有冯延巳“细雨湿流光”五个字，都是能摄取春草魂魄的词句啊！ ', NULL, '', 'indent', 1521731781, '5ab3583f2f301e1c2c2aced6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636618, '人间词话 ·  第二十四则', NULL, 15, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '《诗 · 蒹葭》一篇最得风人深致。晏同叔之“昨夜西风凋碧树。独上高楼，望尽天涯路。”意颇近之。但一洒落，一悲壮耳。 ', '', '《诗经·蒹葭》："蒹葭苍苍，白露为霜。所谓伊人，在水一方。溯洄从之，道阻且长。溯游从之，宛在水中央。蒹葭凄凄，白露未晞。所谓伊人，在水之湄。溯洄从之，道阻且跻。溯游从之，宛在水中坻。蒹葭采采，白露未已。所谓伊人，在水之涘，溯洄从之，道阻且右。溯游从之，宛在水中沚。"
晏殊【蝶恋花】："槛菊愁烟兰泣露。罗幕轻寒，燕子双飞去。明月不谙别离苦，斜光到晓穿朱户。　昨夜西风凋碧树。独上高楼，望尽天涯路。欲寄彩笺兼尺素，山长水阔知何处。"', '《诗·秦风·蒹葭》这首诗，最能体现出诗人真挚的情感，而又写得生动自然。晏殊《蝶恋花》中“昨夜西风凋碧树，独上高楼，望尽天涯路”的词句，意境和它比较接近。但还是有所区别的，前者洒落，后者悲壮。 ', NULL, '', 'indent', 1521731849, '5ab358872f301e1c2c2ad04d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636619, '人间词话 ·  第二十五则', NULL, 13, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '“我瞻四方，蹙蹙靡所骋。”诗人之忧生也。“昨夜西风凋碧树。独上高楼，望尽天涯路”似之。“终日驰车走，不见所问津。”诗人之忧世也。“百草千花寒食路。香车系在谁家树”似之。 ', '', '《诗经·小雅·节南山》："驾彼四牡，四牡项领。我瞻四方，蹙蹙靡所骋。"
晏殊【蝶恋花】见二四注。
陶潜【饮酒】第二十首："羲农去我久，举世少复真。汲汲鲁中叟，弥缝使其纯。凤鸟虽不至，礼乐暂得新。洙泗绝微响，漂流逮狂秦。诗书复何罪，一朝成灰尘。区区诸老翁，为事诚殷勤。如何绝世下，六籍无一亲？终日驰车走，不见所问津。若复不快饮，空负头上巾。但恨多谬误，君当恕罪人。"
冯延巳【鹊踏枝】："几日行云何处去，忘却归来，不道春将暮！百草千花寒食路，香车系在谁家树？　泪眼倚楼频独语：双燕来时，陌上相逢否？撩乱春愁如柳絮，悠悠梦里无寻处。"', '《诗·小雅·节南山》诗句：“我瞻四方，蹙蹙靡所骋”，这是诗人忧生之作。晏殊的“昨夜西风凋碧树，独上高楼，望尽天涯路”和它相似。陶渊明《饮酒》诗句：“终日驰车走，不见所问津”，这是诗人忧世之作。冯延巳的“百草千花寒食路，香车系在谁家树”和它相似。 ', NULL, '', 'indent', 1521732102, '5ab3596d9f54541d2c3aad20', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636620, '人间词话 ·  第二十六则', NULL, 98, 210, 4, 2, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '古今之成大事业、大学问者，必经过三种之境界。“昨夜西风凋碧树，独上高楼，望尽天涯路”，此第一境也。“衣带渐宽终不悔，为伊消得人憔悴”，此第二境也。“众里寻他千百度，蓦然回首，那人却在，灯火阑珊处”，此第三境也。此等语皆非大词人不能道。然遽以此意解释诸词，恐为晏、欧诸公所不许也。', '', '晏殊【蝶恋花】见二四注。
柳永【蝶恋花】："伫倚危楼风细细。望极春愁，黯黯生天际。草色烟光残照里。无言谁会凭栏意。拟把疏狂图一醉，对酒当歌，强乐还无味。衣带渐宽终不悔，为伊消得人憔悴。"
辛弃疾【青玉案】（元夕）："东风夜放花千树。更吹落、星如雨。宝马雕车香满路，凤箫声动，玉壶光转，一夜鱼龙舞。蛾儿雪柳黄金缕。笑语盈盈暗香去。众里寻它千百度。蓦然回首，那人却在，灯火阑珊处。"', '自古至今，能够取得大事业、做得大学问的人，无不经过三种境界：“昨夜西风凋碧树，独上高楼，望尽天涯路”，这是第一境。“衣带渐宽终不悔，为伊消得人憔悴”，这是第二境。“众里寻他千百度，蓦然回首，那人却在，灯火阑珊处”，这是第三境。这些语句，不是大词人是说不出来的。但从这层意义上去解释诗词，恐怕晏殊、欧阳修诸人是不会允许的。', NULL, '', 'indent', 1521732191, '5ab359dd9f54543687b17e3c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636621, '人间词话 ·  第二十七则', NULL, 18, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '永叔“人生自是有情痴，此恨不关风与月”，“直须看尽洛城花，始与东风容易别”，于豪放之中有沉著之致，所以尤高。', '', '欧阳修【玉楼春】："尊前拟把归期说，未语春容先惨咽。人生自是有情痴，此恨不关风与月。离歌且莫翻新阕，一曲能教肠寸结。直须看尽洛城花，始共春风容易别。"', '欧阳修《玉楼春》中“人生自是有情痴，此恨不关风与月”、“直须看尽洛城花，始共春风容易别”等词句，在豪放中有沉着的意趣，所以更加高深。', NULL, '', 'indent', 1521732247, '5ab35a1675657116a3a0ac8d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636622, '人间词话 ·  第二十八则', NULL, 9, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '冯梦华《宋六十一家词选·序例》谓：「淮海、小山，古之伤心人也，其淡语皆有味，浅语皆有致。」余谓此唯淮海足以当之。小山矜贵有余，但可方驾子野、方回，未足抗衡淮海也。', '', '', '冯煦在《宋六十一家词选·序例》中说道：「秦观、晏几道，是古时的伤心人呀，他们平淡的语句中都别有回味，浅显的语句中都别有情趣。」我认为，这句话只有秦观能够相称。晏几道矜持自贵有馀，衹可与张先、贺铸等人并驾齐驱，如果要与秦观抗衡就有所不足了。 ', NULL, '', 'indent', 1521732277, '5ab35a33ee920a396f19e86d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636623, '人间词话 ·  第二十九则', NULL, 9, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '少游词境最凄婉。至“可堪孤馆闭春寒，杜鹃声里斜阳暮。”则变而凄厉矣。东坡赏其后二语，犹为皮相。 ', '', '秦观【踏莎行】见三注。东坡绝爱其尾两句，自书于扇曰："少游已矣，虽万人何赎。"', '秦观词作的意境显得最凄婉。写到“可堪孤馆闭春寒，杜鹃声里斜阳暮”这样的词句时，就变为凄厉了。苏轼欣赏他该词最后两句：“郴江幸自绕郴山，为谁流下潇湘去”，特别表面。 ', NULL, '', 'indent', 1521732318, '5ab35a5c9f54541d2c3ab31c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636624, '人间词话 ·  第三十则', NULL, 9, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '“风雨如晦，鸡鸣不已”，“山峻高以蔽日兮，下幽晦以多雨。霰雪纷其无垠兮，云霏霏而承宇”，“树树皆秋色，山山唯落晖”，“可堪孤馆闭春寒，杜鹃声里斜阳暮”，气象皆相似。', '', '《诗·郑风·风雨》："风雨凄凄，鸡鸣喈喈。既见君子，云胡不夷。风雨潇潇，鸡鸣胶胶。既见君子，云胡不瘳。风雨如晦，鸡鸣不已。既见君子，云胡不喜。"
《楚辞．九章．涉江》（辞长不录）。
王绩【野望】："东皋薄暮望，徒倚欲何依。树树皆秋色，山山唯落晖。牧人驱犊返，猎马带禽归。相顾无相识，长歌怀采薇。"
秦观【踏莎行】见三注。', '《诗经．郑风．风雨》中：“风雨如晦，鸡鸣不已”句、《楚辞．九章．涉江》中：“山峻高以蔽日兮，下幽晦以多雨。霰雪纷其无垠兮，云霏霏而承宇”、王绩《野望》中：“树树皆秋色，山山唯落晖”句、秦观《踏莎句》中：“可堪孤馆闭春寒，杜鹃声里斜阳暮”句，气象都相似。', NULL, '', 'indent', 1521732358, '5ab35a7fac502e57c93a5569', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636631, '人间词话 ·  第三十一则', NULL, 9, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '昭明太子称陶渊明诗“跌宕昭彰，独超众类。抑扬爽朗，莫之与京”。王无功称薛收赋“韵趣高奇，词义晦远。嵯峨萧瑟，真不可言”。词中惜少此二种气象，前者唯东坡，后者唯白石，略得一二耳。 ', '', '见萧统《陶渊明集》序。
见《王无功集》卷下【答冯子华处士书】。所称薛收赋，谓系【白牛溪赋】。', '南梁昭明太子萧统说：陶渊明的诗“跌宕昭彰，独超众类。抑扬爽朗，莫之与京”。唐代诗人王绩说：薛收的辞赋“韵趣高奇，词义晦远。嵯峨萧瑟，真不可言”。可惜词中少这两种气象，前者只有苏轼，后者只有姜夔，稍稍得到一二罢了。', NULL, '', 'indent', 1521818865, '5ab4ac7017d009688770af0c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636632, '人间词话 ·  第三十二则', NULL, 14, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '词之《雅》、《郑》，在神不在貌。永叔、少游虽作艳语，终有品格。方之美成，便有淑女与倡伎之别。', '', '', '区分词是否色情猥亵，要通过神韵而不是面貌去辨别。譬如欧阳修和秦观的词虽然也写艳情的语言，但终归有品格。比之于周邦彦，便有淑女和妓女的区别了。', NULL, '', 'indent', 1521818895, '5ab4ac8e9f54541d2c425107', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636633, '人间词话 ·  第三十三则', NULL, 12, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '美成深远之致不及欧、秦，唯言情体物，穷极工巧，故不失为一流之作者。但恨创调之才多，创意之才少耳。', '', '', '周邦彦的词，在意趣深远方面不如欧阳修和秦观，只是表达情感、描述事物时，极其精致巧妙，所以仍可列入第一流的词作者。恨只恨他创调方面的才能多，而创意的才气少啊。 ', NULL, '', 'indent', 1521818921, '5ab4aca8ee920a396f2198ed', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636668, '人间词话 · 第四十六则', NULL, 8, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '苏、辛词中之狂，白石犹不失为狷，若梦窗、梅溪、玉田、草窗、中麓辈，面目不同，同归于乡愿而已。', '', '', '苏轼和辛弃疾，是词人中的狂者。姜夔，仍然可以算作是狷者。至于吴文英、史达祖、张炎、周密、陈允平等词人，虽然各有风格，同样终归于乡愿一路。', NULL, '', 'indent', 1521895291, '5ab5d6f99f54543687bf9590', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642074, '幽梦影 · 卷一 · 四十三', NULL, 4, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '雨之为物，能令昼短，能令夜长。', '', '', '', NULL, '', 'indent', 1556016657, '5cbe7d8fa91c9377aab349d2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636634, '人间词话 ·  第三十四则', NULL, 10, 210, 1, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '词忌用替代字。美成《解语花》之“桂华流瓦”，境界极妙。惜以“桂华”二字代“月”耳。梦窗以下，则用代字更多。其所以然者，非意不足，则语不妙也。盖意足则不暇代，语妙则不必代。此少游之“小楼连苑”，“绣毂雕鞍”所以为东坡所讥也。 ', '', '周邦彦【解语花】（元宵）："风销焰蜡，露浥烘炉，花市光相射。桂华流瓦。纤云散，耿耿素娥欲下。衣裳淡雅。看楚女、纤腰一把。箫鼓喧、人影参差，满路飘香麝。因念都城放夜。望千门如昼，嬉笑游冶。钿车罗帕。相逢处、自有暗尘随马。年光是也。唯只见、旧情衰谢。清漏移、飞盖归来，从舞休歌罢。"
秦观【水龙吟】："小楼连苑横空，下窥绣毂雕鞍骤。朱帘半卷，单衣初试，清明时候。破暖轻风，弄晴微雨，欲无还有。卖花声过尽，斜阳院落，红成阵、飞鸳甃。玉佩丁东别后。怅佳期、参差难又。名韁利锁，天还知道，和天也瘦。花下重门，柳边深巷，不堪回首。念多情，但有当时皓月，向人依旧。"
《历代诗余》卷五引曾慥《高齐词话》："少游自会稽入都见东坡。东坡问作何词，少游举''小楼连苑横空，下窥绣毂雕鞍骤。''东坡曰：''十三字只说得一个人骑马楼前过。''"', '作词忌讳用替代字。周邦彦《解语花》中的“桂华流瓦”一句，境界极妙，可惜用“桂华”二字来替代“月光”。再到吴文英以后，用替代字的人更多了。之所以出现这种情况，不是情感不强烈深厚，就是语言不够高超精妙。因为如果意足，根本没有时间去找替代字，如果语妙，根本没有必要去找替代字。秦观曾经使用替代字而受苏轼的讥笑，根据俞文豹《吹剑三录》记载，秦观在《水龙吟》一词中写道：“小楼连苑横空，下窥绣毂雕鞍骤”，东坡看后说：“十三个字，仅仅是说一个人骑马从楼前经过。” ', NULL, '', 'indent', 1521818980, '5ab4acdb9f54543687b935d4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636635, '人间词话 ·  第三十五则', NULL, 13, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '沈伯时《乐府指迷》云：“说桃不可直说破桃，须用‘红雨’、‘刘郎’等字。咏柳不可直说破柳，须用‘章台’、‘灞岸’等字。”若惟恐人不用代字者。果以是为工，则古今类书具在，又安用词为耶？宜其为《提要》所讥也。', '', '《四库提要》集部词曲类二沈氏《乐府指迷》条："又谓说桃须用''红雨''、''刘郎''等字，说柳须用''章台''、''灞岸''等字，说书须用''银钩''等字，说泪须用''玉箸''等字，说发须用''绛云''等字，说簟须用''湘竹''等字，不可直说破。其意欲避鄙俗，而不知转成涂饰，亦非确论。"', '南宋沈义夫在《乐府指迷》中说：“说桃，不可直说破桃，须用‘红雨’、‘刘郎’等字；说柳，不可直说破柳，须用‘章台’、‘灞岸’等字。”好像害怕别人不用替代字人心似的。如果说只有按他那样写才叫工巧的话，那么古今各类书都在，又何须用词来表达情感呢？也难怪他后来被《四库提要》所讥笑。', NULL, '', 'indent', 1521819013, '5ab4ad04ee920a396f219b07', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636636, '人间词话 ·  第三十六则', NULL, 10, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '美成《苏幕遮》词：“叶上初阳干宿雨。水面清圆，一一风荷举。”此真能得荷之神理者。觉白石《念奴娇》、《惜红衣》二词，犹有隔雾看花之恨。', '', '周邦彦【苏幕遮】："燎沈香，消溽暑，鸟雀呼晴，侵晓窥檐语。叶上初阳干宿雨。水面清圆，一一风荷举。故乡遥，何日去？家住吴门，久作长安旅。五月渔郎相忆否？小楫轻舟，梦入芙蓉浦。"
姜夔【念奴娇】："闹红一舸，记来时，尝与鸳鸯为侣。三十六陂人未到，水佩风裳无数。翠叶吹凉，玉容销酒，更洒菰蒲雨。嫣然摇动，冷香飞上诗句。日暮。青盖亭亭，情人不见，争忍凌波去。只恐舞衣寒易落，愁入西风南浦。高柳垂阴，老鱼吹浪，留我花间住。田田多少？几回沙际归路。"
姜夔【惜红衣】："簟枕邀凉，琴书换日，睡余无力。细洒冰泉，并刀破甘碧。墙头唤酒，谁问讯城南诗客？岑寂。高柳晚蝉，说西风消息。虹梁水陌，鱼浪吹香，红衣半狼籍。维舟试望故国。眇天北。可惜渚边沙外，不共美人游历。问甚时同赋，三十六陂秋色？"', '周邦彦《青玉案》词中：“叶上初阳干宿雨，水面清圆，一一风荷举”句，真是深得荷花神采肌理的好句子啊。而姜夔《念奴娇》、《惜红衣》这两首同样写荷花的词作，怎么看都如同隔雾看花的遗憾。', NULL, '', 'indent', 1521819043, '5ab4ad229f54541326cdc16d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636637, '人间词话 ·  第三十七则', NULL, 10, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '东坡《水龙吟·咏杨花》，和韵而似原唱。章质夫词，原唱而似和韵。才之不可强也如是。', '', '苏轼【水龙吟】（次韵章质夫杨花词）："似花还似非花，也无人惜从教坠。抛家傍路，思量却是，无情有思。萦损柔肠，困酣娇眼，欲开还闭。梦随风万里，寻郎去处，又还被、莺呼起。不恨此花飞尽，恨西园、落红难缀。晓来雨过，遗踪何在，一池萍碎。春色三分，二分尘土，一分流水。细看来不是杨花，点点是离人泪。"
章质夫【水龙吟】（杨花）："燕忙莺懒芳残，正堤上、杨花飘坠。轻飞乱舞，点画青林，全无才思。闲趁游丝，静临深院，日长门闭。傍珠帘散漫，垂垂欲下，依前被、风扶起。兰帐玉人睡觉，怪春衣、雪沾琼缀。绣床渐满，香球无数，才圆欲碎。时见蜂儿，仰粘轻粉，鱼吞池水。望章台路杳，金鞍游荡，有盈盈泪。"', '苏轼《水龙吟》一词歌咏杨花，本是和韵，却好像原唱。章质夫《水龙花》咏柳絮，本是元唱，却好像是和韵。所以说，词人的才华和文采是不可强求的。', NULL, '', 'indent', 1521819075, '5ab4ad429f545437fe8ec4e4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636638, '人间词话 ·  第三十八则', NULL, 10, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '咏物之词，自以东坡《水龙吟》为最工，邦卿《双双燕》次之。白石《暗香》、《疏影》，格调虽高，然无一语道着，视古人“江边一树垂垂发” 等句何如耶？ ', '', '史达祖【双双燕】（咏燕）："过春社了，度帘幕中间，去年尘冷。差池欲往，试入旧巢相并。还相雕梁藻井，又软语商量不定。飘然快拂花梢，翠尾分开红影。　芳径，芹泥雨润。爱贴地争飞，竞夸轻俊。红楼归晚，看足柳暗花暝。应自栖香正稳，便忘了、天涯芳信。愁损翠黛双娥，日日画栏独凭。"
姜夔【暗香】：（辛亥之冬，予载雪诣石湖。止既月，授简索句，且征新声，作此两曲。石湖把玩不已，使工妓肆习之，音节谐婉，乃名之曰暗香、疏影。）"旧时月色，算几番照我，梅边吹笛？唤起玉人，不管清寒与攀摘。何逊而今渐老，都忘却春风词笔。但怪得竹外疏花，香冷入瑶席。江国，正寂寂，叹寄与路遥，夜雪初积。翠尊易泣，红萼无言耿相忆。长记曾携手处，千树压西湖寒碧。又片片吹尽也，几时见得？"
姜夔【疏影】："苔枝缀玉，有翠禽小小，枝上同宿。客里相逢，篱角黄昏，无言自倚修竹。昭君不惯胡沙远，但暗忆江南江北。想佩环月夜归来，化作此花幽独。　犹记深宫旧事，那人正睡里，飞近蛾绿。莫似春风，不管盈盈，早与安排金屋。还教一片随波去，又却怨玉龙哀曲。等恁时、重觅幽香，已入小窗横幅。"
杜甫【和裴迪登蜀州东亭送客逢早梅相忆见寄】："东阁官梅动诗兴，还如何逊在杨州。此时对雪遥相忆，送客逢春可自由。幸不折来伤春暮，若为看去乱乡愁。江边一树垂垂发，朝夕催人自白头。"', '咏物的词作，当然以苏轼的《水龙吟》最为工巧，史达祖的《双双燕》排第二。至于姜夔的《暗香》、《疏影》二词，格调虽然很高，但却没有一句能够说中根本，显得不真切，你看古人“江边一树垂垂发”这样的诗句如何呀？ ', NULL, '', 'indent', 1521819126, '5ab4ad6fac502e57c942117a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636648, '秋暮遣怀', NULL, 22, 1, 1, 0, '陶宗亮', NULL, 36896, '5ab500f144d90418a2233ca9', '清', 'shi', '诗', '', '', '人生天地一叶萍，利名役役三秋草。
秋草能为春草新，苍颜难换朱颜好。
篱前黄菊未开花，寂寞清樽冷怀抱。
秋风秋雨愁煞人，寒宵独坐心如捣。
出门拔剑壮盘游，霜华拂处尘氛少。
朝凌五岳暮三洲，人世风波岂能保。
不如归去卧糟丘，老死蓬蒿事幽讨。', '“秋风秋雨愁煞人”， 此句作为著名爱国巾帼女士的遗言而广为传诵。故此许多人以为为秋瑾所作，但实际是秋瑾引用了清代诗人陶澹人（即）的诗句。 而流传在外出自秋瑾手笔的文为：“篱前黄菊未开花，寂寞清樽冷怀抱。秋风秋雨愁煞人，寒宵独坐心如捣。”正是引用其中。
秋天在我国文学意味上多带有悲凉肃杀色彩，自古逢秋悲寂寥，有“春女思，秋士悲”之说。仅从字面也可以想象出萧索秋天的场景：绵绵秋雨，伴着寒冷的秋风，天空一定是昏黄的，肃杀的冬季就要来了，大地上没有了勃勃生机，正是万物凋零的时节，在秋风秋雨之中，心情更是惆怅哀凉。
这一诗句，充分表达了秋瑾对封建黑暗统治的不满，对吃人礼教的反抗，对国家和民族的深情。也表达一位女革命家忧国忧民、壮志未酬、面对死亡的悲愤心情。', '', '', '[{"bookId": "60d939cea06dc908f045ad24", "bookTitle": "元明清诗鉴赏辞典（新一版）", "articleId": "610e8d1a03048e64fbd8f869", "shortContent": "此诗中“秋雨秋风愁煞人”一句，曾被秋瑾引作就义前临刑时的“供词”而闻名于世；世人亦因此将其看作秋瑾的《绝命词》而把它作为断句辑入《秋瑾集》中，并由此取义，将修建于绍兴轩亭口的秋瑾烈士纪念亭，名曰“风雨亭”。\n原诗作者陶宗亮，“君为五柳先生之裔，宗亮其名”（毕宪曾《沧江红雨楼诗集序》）。因先人陶渊明字元亮，追慕其人，故名“宗亮”，诸生出身，隐居太仓娄江（今浏河）支流桃源泾畔，以诗画自娱，《秋暮遣怀》...", "authors": ["王杏根"], "pressName": "上海辞书出版社"}]', '', 'center', 1521840892, '5ab502789f54543687bbdabf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636715, '解佩令 · 春', NULL, 12, 96, 1, 0, '蒋捷', NULL, 10071, '57ac9514c4c9710054655e3c', '宋', 'ci', '词', '', '', '春晴也好。春阴也好。著些儿、春雨越好。春雨如丝，绣出花枝红袅。怎禁他、孟婆合皂。
梅花风小。杏花风小。海棠风、蓦地寒峭。岁岁春光，被二十四风吹老。楝花风、尔且慢到。', '', '', '', NULL, '', 'indent', 1553547003, '5ab86035a22b9d0045f89763', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636639, '人间词话 ·  第三十九则', NULL, 13, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '白石写景之作，如「二十四桥仍在，波心荡、冷月无声」，「数峰清苦，商略黄昏雨」，「高树晚蝉，说西风消息」，虽格韵高绝，然如雾里看花，终隔一层。梅溪、梦窗诸家写景之病，皆在一「隔」字。北宋风流，渡江遂绝。抑真有运会存乎其间耶？', '', '姜白石《扬州慢》：「淮左名都，竹西佳处，解鞍少驻初程。过春风十里，尽荠麦青青。自胡马、窥江去后，废池乔木，犹厌言兵。		渐黄昏，清角吹寒，都在空城。杜郎俊赏，算而今、重到须惊。纵豆蔻词工，青楼梦好，难赋深情。二十四桥仍在，波心荡、冷月无声。念桥边红药，年年知为谁生？」
姜白石《点绛唇》：「燕雁无心，太湖西畔随云去。数峰清苦。商略黄昏雨。		第四桥边，拟共天随往。今何许？凭栏怀古，残柳参差舞。」
姜白石《惜红衣》：「汉渚羁愁，苕溪浪迹，野云谁识。旧说西塍，吟魂寄幽宅。斜阳蔓草，空怅望、春风词笔。悽忆。香暗影疏，掩梅花仙魄。		漂零楚客，抔土长留，湖山恣游历。繁华梦去，故国已无觅。好属小红珠泪，莫向冷枫啼湿。怕洞箫清怨，吹咽六陵秋色。」', '姜白石写景的词作当中，譬如「二十四桥仍在，波心荡，冷月无声」、「数峰清苦，商略黄昏雨」、「高树晚蝉，说西风消息」等词句，虽然格调高雅绝妙，但读来如同雾里看花，终归隔了一层。另外，史达祖、吴梦窗等词人写景的弊病，也都在这一个「隔」字。都说北宋风流在渡江南下以后就绝迹了，难道真有运数在这其间存在流转吗？', NULL, '', 'indent', 1521819169, '5ab4ad99756571108cd8a842', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636640, '人间词话 ·  第四十则', NULL, 10, 210, 1, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '问“隔”与“不隔”之别，曰：陶、谢之诗不隔，延年则稍隔矣。东坡之诗不隔，山谷则稍隔矣。“池塘生春草”、“空梁落燕泥”等二句，妙处唯在不隔。词亦如是。即以一人一词论，如欧阳公《少年游•咏春草》上半阙云：“阑干十二独凭春，晴碧远连云。千里万里，二月三月，行色苦愁人。”语语都在目前，便是不隔。至云“谢家池上，江淹浦畔”，则隔矣。白石《翠楼吟》：“此地，宜有词仙，拥素云黄鹤，与君游戏。玉梯凝望久，叹芳草萋萋千里。” 便是不隔。至“酒祓清愁，花消英气”，则隔矣。然南宋词虽不隔处，比之前人，自有浅深厚薄之别。 ', '', '谢灵运【登池上楼】："潜虬媚幽姿，飞鸿响远音。薄霄愧云浮，栖川怍渊沈。进德智所拙，退耕力不任。徇禄反穷海，卧疴对空林。衾枕昧节候，褰开暂窥临。倾耳聆波澜，举目眺岖嵚。初景革绪风，新阳改故阴。池塘生春草，园柳变鸣禽。祁祁伤豳歌，萋萋感楚吟。索居易永久，离群难处心，持操岂独占，无闷征在今。"
薛道衡【昔昔盐】："垂柳覆金堤，蘼芜叶复齐。水溢芙蓉沼，花飞桃李蹊。采桑秦氏女，织锦窦家妻。关山别荡子，风月守空闺。恒敛千金笑，长垂双玉啼。盘龙随镜隐，彩凤逐帷低。飞魂同夜鹊，倦寝忆晨鸡。暗牖悬蛛网，空梁落燕泥。前年过代北，今岁往辽西。一去无消息，那能惜马蹄。"
欧阳修【少年游】见二三注。
姜夔【翠楼吟】"月冷龙沙，尘清虎落，今年汉酺初赐。新翻胡部曲，听毡幕、元戎歌吹。层楼高峙。看槛曲萦红，檐牙飞翠。人姝丽。粉香吹下，夜寒风细。　此地。宜有词仙，拥素云黄鹤，与君游戏。玉梯凝望久，叹芳草、萋萋千里。天涯情味。仗酒祓清愁，花销英气。西山外。晚来还卷，一帘秋霁。"', '有人问“隔”与“不隔”之间的区别，我举例来说明：陶渊明、谢灵运的诗不隔，颜延之的诗就稍微隔了。苏轼的诗不隔，黄庭坚的诗就稍微隔了。“池塘生春草”、“空梁落燕泥”这两句诗，它的妙处就是不隔。词也一样。如果用一人一词来评论的话，欧阳修《少年游》咏春草上半阕所写的“阑干十二独凭春，晴碧远连云。千里万里，二月三月，行色苦愁人”，每句话读来如在眼前，这便是不隔。至于写到“谢家池上，江淹浦畔”，也就隔了。姜夔《翠楼吟》所写的“此地。宜有词仙，拥素云黄鹤，与君游戏。玉梯凝望久，叹芳草、萋萋千里”，这便是不隔。至于写到“酒祓清愁，花消英气”，也就隔了。但是，南宋的词作虽说有不隔处，与前人相比的话，还是有深浅厚薄的差别。 ', NULL, '', 'indent', 1521819219, '5ab4adc9ac502e57c942139e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636641, '人间词话 ·  第四十一则', NULL, 10, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '“生年不满百，常怀千岁忧。昼短苦夜长，何不秉烛游？”“服食求神仙，多为药所误。不如饮美酒，被服纨与素。”写情如此，方为不隔。“采菊东篱下，悠然见南山。山气日夕佳，飞鸟相与还。”“天似穹庐，笼盖四野。天苍苍，野茫茫。风吹草低见牛羊。”写景如此，方为不隔。', '', '《古诗十九首》第十五："生年不满百，常怀千岁忧。昼短苦夜长，何不秉烛游，为乐当及时，何能待来兹。愚者爱惜费，但为后世嗤。仙人王子乔，难可与等期。"
《古诗十九首》第十三："驱车上东门，遥望郭北墓。白杨何萧萧，松柏夹广路。下有陈死人，杳杳即长暮。潜寐黄泉下，千载永不寤。浩浩阴阳移，年命如朝露。人生忽如寄，寿无金石固。万岁更相送，圣贤莫能度。服食求神仙，多为药所误。不如饮美酒，被服纨与素。"
陶潜【饮酒诗】见三注。
斛律金【敕勒歌】："敕勒川，阴山下。天似穹庐，笼盖四野。天苍苍，野茫茫，风吹草低见牛羊。"', '《古诗十九首》中写道：“生年不满百，常怀千岁忧。昼短苦夜长，何不秉烛游”、“服食求神仙，多为药所误。不如饮美酒，被服纨与素”，写情能到这个份上，才可以说不隔。陶渊明“采菊东篱下，悠然见南山。山气日夕佳，飞鸟相与还”、“天似穹庐，笼盖四野。天苍苍，野茫茫，风吹草低见牛羊，写景写到这个份上，也才可以说不隔。', NULL, '', 'indent', 1521819271, '5ab4ae019f54541326cdc82d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636642, '人间词话 ·  第四十二则', NULL, 9, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '古今词人格调之高，无如白石。惜不于意境上用力，故觉无言外之味，弦外之响，终不能与于第一流之作者也。', '', '', '自古至今，词人论格调高绝，没有比得上姜夔的。可惜他不在意境上下功夫，所以总觉得他的词没有言外之味、弦外之响，最终仍不能把他列为第一流的词作者。 ', NULL, '', 'indent', 1521819306, '5ab4ae299f545437fe8ecdeb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636643, '人间词话 ·  第四十三则', NULL, 16, 210, 1, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '南宋词人，白石有格而无情，剑南有气而乏韵。其堪与北宋人颉颃者，唯一幼安耳。近人祖南宋而祧北宋，以南宋之词可学，北宋不可学也。学南宋者，不祖白石，则祖梦窗，以白石、梦窗可学，幼安不可学也。学幼安者率祖其粗犷、滑稽，以其粗犷、滑稽处可学，佳处不可学也。幼安之佳处，在有性情，有境界。即以气象论，亦有“傍素波、干青云”之概，宁后世龌龊小生所可拟耶？ ', '', '萧统《陶渊明集》序：其文章"横素波而傍流，干青云而直上。"', '南宋的词人，姜夔的词有格调但无情趣，陆游的词有气势但无韵味。其中能够与北宋词人一比高低的，只有辛弃疾一人了。近人把南宋当作自己的祖宗，却把北宋当作远祖进行迁移，这是因为南宋的词易学，而北宋的词难学的缘故啊。再说学南宋词的人，不是师从姜夔就是吴文英，这是因为他们两个的词易学，而辛弃疾的词难学的缘故啊。也有学辛弃疾的人，全部学他的粗犷和滑稽，因为这些东西易学，而真正的好处难学啊。辛弃疾的好处在于有性情、有境界，如果单从气象来说，也有“傍素波、干青云”的气概，这哪是后人当中那些龌龊的小辈所能比拟的呢？ ', NULL, '', 'indent', 1521819334, '5ab4ae4544d90418a220b74f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (638377, '杏花天', NULL, 2, 109, 0, 1, '高观国', NULL, 30620, '5858f80e1b69e6006cb18441', '宋', 'ci', '词', '', '', '远山学得修眉翠。看眉展、春愁无际。雨痕半湿东风外。不管梨花有泪。
西园路、青鞋暗记。怕行入、秋千径里。一春多少相思意。说与新来燕子。 ', '', '', '', NULL, '', 'indent', 1532518753, '5b57f0e29f54540035e2e4bd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636658, '妙法莲华经 · 如来神力品第二十一', NULL, 1, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%A6%99%E6%B3%95%E8%8E%B2%E5%8D%8E%E7%BB%8F/1772696?fr=aladdin', '', '尔时千世界微尘等菩萨摩诃萨、从地涌出者，皆于佛前、一心合掌，瞻仰尊颜，而白佛言：“世尊，我等于佛灭后，世尊分身所在国土、灭度之处，当广说此经，所以者何。我等亦自欲得是真净大法，受持、读诵、解说、书写、而供养之。”
尔时世尊于文殊师利等、无量百千万亿旧住娑婆世界菩萨摩诃萨、及诸比丘、比丘尼、优婆塞、优婆夷、天龙、夜叉、乾闼婆、阿修罗、迦楼罗、紧那罗、摩侯罗伽、人非人、等，一切众前，现大神力，出广长舌上至梵世，一切毛孔、放于无量无数色光，皆悉遍照十方世界。众宝树下、师子座上诸佛，亦复如是，出广长舌、放无量光。释迦牟尼佛、及宝树下诸佛、现神力时、满百千岁，然后还摄舌相。一时謦欬、俱共弹指，是二音声，遍至十方诸佛世界，地皆六种震动。其中众生，天龙、夜叉、乾闼婆、阿修罗、迦楼罗、紧那罗、摩侯罗伽、人非人、等，以佛神力故，皆见此娑婆世界、无量无边百千万亿众宝树下、师子座上诸佛，及见释迦牟尼佛、共多宝如来、在宝塔中、坐师子座，又见无量无边百千万亿菩萨摩诃萨、及诸四众，恭敬围绕释迦牟尼佛，既见是已，皆大欢喜，得未曾有。
即时诸天、于虚空中、高声唱言：“过此无量无边百千万亿阿僧祇世界，有国、名娑婆，是中有佛、名释迦牟尼，今为诸菩萨摩诃萨说大乘经，名妙法莲华、教菩萨法、佛所护念，汝等当深心随喜，亦当礼拜供养释迦牟尼佛。”彼诸众生、闻虚空中声已，合掌向娑婆世界、作如是言：“南无释迦牟尼佛。南无释迦牟尼佛。”以种种华、香、璎珞、幡盖、及诸严身之具、珍宝妙物，皆共遥散娑婆世界。所散诸物、从十方来，譬如云集，变成宝帐，遍覆此间诸佛之上。于时十方世界，通达无碍，如一佛土。
尔时佛告上行等菩萨大众：“诸佛神力，如是无量无边、不可思议，若我以是神力，于无量无边百千万亿阿僧祇劫，为嘱累故、说此经功德，犹不能尽。以要言之，如来一切所有之法，如来一切自在神力，如来一切所秘要之藏，如来一切甚深之事，皆于此经、宣示显说。是故汝等于如来灭后，应一心受持、读诵、解说、书写、如说修行。所在国土，若有受持、读诵、解说、书写、如说修行，若经卷所住之处，若于园中，若于林中，若于树下，若于僧坊，若白衣舍，若在殿堂，若山谷旷野，是中皆应起塔供养。所以者何。当知是处、即是道场，诸佛于此、得阿耨多罗三藐三菩提，诸佛于此、转于法錀，诸佛于此、而般涅槃。”
尔时世尊欲重宣此义，而说偈言：
　　诸佛救世者， 住于大神通， 为悦众生故， 现无量神力，
　　舌相至梵天， 身放无数光， 为求佛道者、 现此稀有事。
　　诸佛謦欬声、 及弹指之声， 周闻十方国， 地皆六种动。
　　以佛灭度后、 能持是经故， 诸佛皆欢喜， 现无量神力。
　　嘱累是经故， 赞美受持者， 于无量劫中、 犹故不能尽。
　　是人之功德， 无边无有穷， 如十方虚空， 不可得边际。
　　能持是经者， 则为已见我， 亦见多宝佛、 及诸分身者，
　　又见我今日、 教化诸菩萨。 能持是经者， 令我及分身、
　　灭度多宝佛， 一切皆欢喜。 十方现在佛、 并过去未来，
　　亦见亦供养， 亦令得欢喜。 诸佛坐道场， 所得秘要法，
　　能持是经者， 不久亦当得。 能持是经者， 于诸法之义、
　　名字及言辞， 乐说无穷尽， 如风于空中， 一切无障碍。
　　于如来灭后， 知佛所说经， 因缘及次第， 随义如实说，
　　如日月光明， 能除诸幽冥。 斯人行世间， 能灭众生闇，
　　教无量菩萨、 毕竟住一乘。 是故有智者、 闻此功德利，
　　于我灭度后， 应受持斯经， 是人于佛道， 决定无有疑。', '妙法莲华经（Saddharmapundarika-sutra），简称《法华经》，在古印度、尼泊尔等地长期流行。在克什米尔、尼泊尔和中国新疆、西藏等地有40多种梵文版本，分为尼泊尔体系、克什米尔体系（基尔基特）和新疆体系。尼泊尔体系版本约为11世纪后作品，保持完整，已出版5种校订本。1983年北京民族文化宫图书馆用珂罗版彩色复制出版了由尼泊尔传入、珍藏于西藏萨迦寺的法华经。', '', '这时，一千世界微尘数那么多的菩萨、大菩萨，即从地下涌出的那些菩萨大众，都在释迦牟尼佛面前专心一意地合起双掌，瞻仰佛的尊颜，对佛说道：世尊，我们在佛灭度之后，将在世尊分身所在国土的灭度之处，广泛演说这部经典。为什么呢？因为我们也想得到这种既真实又清净的大法，并受持、读诵、解说、书写、供养这部经典。
这时，释迦牟尼佛在文殊师利等无量百千万亿过去曾住在这个娑婆世界的菩萨、大菩萨面前，在各位比丘、比丘尼、男居士、女居士等四众弟子面前，在天神、龙神、乾闼婆、阿修罗、迦楼罗、紧那罗、摩睺罗伽等八部众面前，在一切人和非人面前，显示出巨大的神通之力。他伸出既广又长的舌头，向上直达色界大梵天。佛身上所有的毛孔，都发放出无量无数、色彩斑斓的光芒。照遍了十方世界的各个角落。坐在各种宝树狮子座上的各位分身佛也是如此，伸出既广又长的舌头，放出无量无的光芒。释迦牟尼佛。及坐在宝树下的各位分身佛显现神通之力的时间，延续了整整一百个千年之后，才收摄了这种广长舌相。他们同时发出轻咳声和弹指声，这两种声音响彻十方一切佛国世界，大地也随之发生了六种类型的震动。
置身于法华会中的所有众生如天神、龙神、乾闼婆、阿修罗、迦楼罗、紧那罗、摩睺罗伽以及人和各种非人的恶鬼、冥众等，凭借佛的神力，都看见了这个娑婆世界无量无边百千万亿棵宝树下狮子座上坐著的各位如来世尊，也看见了释迦牟尼佛和多宝如来在宝塔之中坐在狮子座上，还看见了无量无边百千万亿个菩萨、大菩萨以及四众弟子正恭恭敬敬地围绕著释迦牟尼佛。看见了这种景象之后，大家无不欣乐欢喜，赞叹这是从未有过的妙事。
紧接著，诸位天神在虚空之中高声说道：由此再过无量无边百千万亿阿僧祇个世界，那里有一处国土，名叫娑婆。在此国土之中，有一位如来世尊，名叫释迦牟尼，现在正为诸菩萨、大菩萨讲说一部名叫《妙法莲华经》的大乘经典。此经是教化菩萨的妙法，是佛对众生护持与忆念。你们应当衷心随顺其义，欢喜信受，也应当礼拜、供养释迦牟尼佛。
所有众生听到虚空中的这种声音之后，都合掌面向娑婆世界，并口中说道：南无释迦牟尼佛！南无释迦牟尼佛！众生们以各种鲜花、妙香、璎珞、宝幡、宝盖及各种装饰身体的用品和其他各类珍宝、妙物，一起向遥远的娑婆世界散去。所散之物从十方世界汇集而来，犹如云团相聚、变成了宝帐，周遍地覆盖在此间的各伴如来世尊的上空。这时，十方世界，通达无碍，犹如一块完整的佛土。
这时，释迦牟尼佛告诉上行等菩萨大众说：诸佛神力如此无量无边，不可思议。假如我以这种神力在长达无量无边百千万亿阿僧祇劫的时间里，因为再三嘱托众生信受的缘故，不断讲述此经的功德，但依然是说不尽道不完的。总而言之，如来所拥有的一切教法，如来所具备的一切自在神力，如来所宣示的一切要法藏，如来所作的一切深妙法事，所有这一切都在此经中作了宣讲、指示的明明白白的叙说。所以，你们在如来世尊灭度之后，应一心一意地受持、读诵、解说、书写《法华经》，并按照经中所说的道理去修行，或者只要是这部经典所在的地方，如：花园、丛林、树下、僧院、民宅、殿堂、山谷、旷野，等等，所有这些地方都应该建起宝塔来供养。为什么呢？应该知道，这些地方就是道场，诸位如来世尊就是在这里得了至高无上的圣智，诸位如来世尊就是在这里转动法轮，教化众生，诸位如来世尊就是在这里进入涅槃。
这时，释迦牟尼佛欲重宣此义，便又以偈颂格式重述道：诸佛是世界一切众生的救度者，为了使众生获得究竟的快乐，所以他们进住于神通之地，并显现其所拥有的神通之力。诸佛首先现出神妙的舌相，舌头变得又广大长，直达梵天之境，诸佛之身也发放无量光芒，五彩缤纷。佛是为求佛道的众生，才现出这种稀有的现象。诸佛轻咳之声和弹指之声，遍闻十笔国土，所到之处，大地都出现了六种震动。因为闭佛灭度之后有人能受持此经，所以，诸佛均十分欢喜，故而现此神力。佛为了表示再三叮咛，故而赞美受持《法华经》的人，在长达无量劫漫漫岁月中，这种赞叹依然不能穷尽。所以，受持《法华经》的人，其所获得的功德，是无边无际，永无穷尽的，就像十方虚空一样，不可找到它的边际。能够受持这部经典的人，就等于见到了我的身相，也见到了多宝如来和我所有分身诸佛，也就等于见到了我今日在此教化所有菩萨的情景。能受持这部经典的人，即可令我和我的所有分身佛以及业已灭度的多宝佛，都感到十分欢喜。也能见到，也能供养十方世界内的现在诸佛和过去诸佛、未来诸佛也能使他们得到欢喜。
所有这一切如来世尊，他们坐在道场中所悟得的秘要之法，对于受持《法华经》的人来说，他们不久也将得到。能受持这部经典的人，对于诸佛所说各种法义，如经中的名相、经中的言辞，能得到乐说无碍的辨才境界，好像风在空中一样，没有任何的限制与阻碍。在佛灭度之后，要是知道佛所说的经典，佛说法的因缘与次序，并随顺经中的义理，如实的解说，那么，就好比日月之光明，能消除一切黑暗之处。这些人在世间行道，能消灭众生心中的暗昧，规律教化无量菩萨，使他们最终进入佛乘，证成佛果。所以，凡是有智慧的人，听到受持这部经典能有这样的功德利益，他们在我灭度之后，就应当受持这部经典。那么，他们在成佛这个问题上，是绝对没有任何疑问的。', NULL, '', 'indent', 1526662577, '5ab52777ee920a396f251add', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636659, '妙法莲华经 · 嘱累品第二十二', NULL, 0, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%A6%99%E6%B3%95%E8%8E%B2%E5%8D%8E%E7%BB%8F/1772696?fr=aladdin', '', '尔时释迦牟尼佛从法座起，现大神力，以右手摩无量菩萨摩诃萨顶，而作是言：“我于无量百千万亿阿僧祇劫、修习是难得阿耨多罗三藐三菩提法，今以付嘱汝等，汝等应当一心流布此法，广令增益。”如是三摩诸菩萨摩诃萨顶、而作是言：“我于无量百千万亿阿僧祇劫、修习是难得阿耨多罗三藐三菩提法，今以付嘱汝等，汝等当受持、读诵、广宣此法，令一切众生、普得闻知。所以者何。如来有大慈悲，无诸悭吝，亦无所畏，能与众生、佛之智慧、如来智慧、自然智慧，如来是一切众生之大施主。汝等亦应随学如来之法，勿生悭吝，于未来世，若有善男子、善女人、信如来智慧者，当为演说此法华经，使得闻知，为令其人得佛慧故。若有众生不信受者，当于如来余深法中、示教利喜，汝等若能如是，则为已报诸佛之恩。”
时诸菩萨摩诃萨、闻佛作是说已，皆大欢喜、遍满其身，益加恭敬，屈躬、低头、合掌向佛，俱发声言：“如世尊敕，当具奉行，唯、然，世尊，愿不有虑。”诸菩萨摩诃萨众，如是三反、俱发声言：“如世尊敕，当具奉行，唯、然，世尊，愿不有虑。”尔时释迦牟尼佛令十方来诸分身佛、各还本土，而作是言：“诸佛各随所安，多宝佛塔、还可如故。”说是语时，十方无量分身诸佛、坐宝树下师子座上者，及多宝佛，并上行等无边阿僧祇菩萨大众，舍利弗等声闻四众，及一切世间、天、人、阿修罗、等，闻佛所说，皆大欢喜。', '妙法莲华经（Saddharmapundarika-sutra），简称《法华经》，在古印度、尼泊尔等地长期流行。在克什米尔、尼泊尔和中国新疆、西藏等地有40多种梵文版本，分为尼泊尔体系、克什米尔体系（基尔基特）和新疆体系。尼泊尔体系版本约为11世纪后作品，保持完整，已出版5种校订本。1983年北京民族文化宫图书馆用珂罗版彩色复制出版了由尼泊尔传入、珍藏于西藏萨迦寺的法华经。', '', '这时，释迦牟尼佛从法座上站走来，显现了巨大的神通之力。他伸出右手，抚摩无量无数个菩萨、大菩萨的头顶，对他们这样说道：我在无量百千万亿阿僧祇劫那么长的漫漫岁月中，修习这种难得的无上圣智之法，今天，我把这种妙法嘱托于你们，你们应当专一其心地流布此法，以更广泛地增加受益的范围。像这样，先后三次抚摩诸位菩萨、大菩萨的头顶之后，释迦牟尼佛又说：我在无量百千万亿阿僧祇劫那么长的漫漫岁月中，修习这种难得的无上圣智之法，今天，我把这种妙法嘱托于你们，你们应当受持、读诵、广泛宣传这种妙法，使一切众生都能听闻得知。为什么呢？因为，如来有大慈大悲之心，没有一丝一毫的悭吝，没有一丝一毫和畏惧，能够给予众生佛的智慧、如来的智慧和自性本有的智慧。所以，如来是一切众生的大施主，你闪也应当跟随如来学习佛法，不要产生悭吝之心。在未来的时候，如果善男子、善女子相信如来的智慧，那么，就应当为他们演说这部《法华经》。使其闻知此经，就是为了使其获得佛的智慧。如果有的众生不信受这部《法华经》，则应当在佛的其他深奥之法中，开示他，令他得到利益，从而主生欢喜之心。你们若能如此去作，那就等于报答了诸位如来世尊的恩情。
这时，诸位菩萨、大菩萨听佛说了这样的话之后，皆大欢喜。他们全身充满欣喜，对佛更加恭敬，于是个个弯腰低头，合掌向佛致礼，同声说道：世尊的敕令，我们自当完全奉行，所以，还请世尊不要有什么顾虑。诸位菩萨、大菩萨这样反复了三遍之后，又同声说道：世尊的敕令，我们自当完全奉行，所以，还请世尊不要有什么顾虑。
这时，释迦牟尼佛命令从十方来的所有分身佛各还本土，他这样说道：诸位分身佛现在可以各随所安，回到各自安住的国土。多宝佛塔也可返回原来的地方。释迦牟尼佛说话时，坐在宝树下狮子座上那些从十方来的无数个分身佛和多宝佛以及上行等无数个菩萨，还有舍利弗等声闻乘的四众弟子与所有世间的天神、人类、阿修罗等众生，听了佛的说法，个个心中充满了欢喜。', NULL, '', 'indent', 1526662592, '5ab5282117d009688774480a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636660, '妙法莲华经 · 药王菩萨本事品第二十三', NULL, 3, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%A6%99%E6%B3%95%E8%8E%B2%E5%8D%8E%E7%BB%8F/1772696?fr=aladdin', '', '尔时宿王华菩萨白佛言：“世尊，药王菩萨、云何游于娑婆世界，世尊，是药王菩萨、有若干百千万亿那由他难行苦行，善哉、世尊，愿少解说。”诸天、龙、神、夜叉、乾闼婆、阿修罗、迦楼罗、紧那罗、摩侯罗伽、人非人、等，又他国土、诸来菩萨，及此声闻众，闻皆欢喜。
尔时佛告宿王华菩萨：“乃往过去无量恒河沙劫，有佛、号日月净明德如来、应供、正遍知、明行足、善逝世间解、无上士、调御丈夫、天人师、佛、世尊。其佛有八十亿大菩萨摩诃萨，七十二恒河沙大声闻众，佛寿四万二千劫，菩萨寿命亦等。彼国无有女人、地狱、饿鬼、畜生、阿修罗、等，及以诸难，地平如掌，琉璃所成，宝树庄严，宝帐覆上，垂宝华幡，宝瓶香炉、周遍国界，七宝为台，一树一台，其树去台、尽一箭道。此诸宝树，皆有菩萨、声闻、而坐其下，诸宝台上，各有百亿诸天、作天伎乐，歌叹于佛，以为供养。”
“尔时彼佛为一切众生喜见菩萨、及众菩萨、诸声闻众、说法华经。是一切众生喜见菩萨，乐习苦行，于日月净明德佛法中、一精一进经行，一心求佛、满万二千岁已，得现一切色身三昧。得此三昧已，心大欢喜，即作念言，我得现一切色身三昧，皆是得闻法华经力，我今当供养日月净明德佛、及法华经。即时入是三昧，于虚空中、雨曼陀罗华、摩诃曼陀罗华、细末坚黑栴檀，满虚空中、如云而下，又雨海此岸栴檀之香，此香六铢、价值娑婆世界，以供养佛。”
作是供养已，从三昧起，而自念言：“我虽以神力供养于佛，不如以身供养。”即服诸香，栴檀、薰陆、兜楼婆、毕力迦、沉水、胶香，又饮瞻卜诸华香油，满千二百岁已，香油涂身，于日月净明德佛前，以天宝衣而自缠身，灌诸香油，以神通力愿、而自燃身，光明遍照八十亿恒河沙世界。其中诸佛、同时赞言：“善哉、善哉，善男子，是真一精一进，是名真法供养如来。若以华、香、璎珞、烧香、末香、涂香、天缯、幡盖、及海此岸栴檀之香、如是等种种诸物供养，所不能及，假使国城、妻子、布施，亦所不及。善男子，是名第一之施，于诸施中、最尊最上，以法供养诸如来故。”作是语已，而各默然。其身火燃、千二百岁，过是已后，其身乃尽。一切众生喜见菩萨、作如是法供养已，命终之后，复生日月净明德佛国中，于净德王家、结跏趺坐，忽然化生。即为其父而说偈言：
　　大王今当知， 我经行彼处， 即时得一切， 现诸身三昧，
　　勤行大一精一进， 舍所爱之身， 供养于世尊、 为求无上慧。
“说是偈已，而白父言：“日月净明德佛、今故现在。我先供养佛已，得解一切众生语言陀罗尼，复闻是法华经八百千万亿那由他、甄迦罗、频婆罗、阿婆、等，偈。大王，我今当还供养此佛。”白已即坐七宝之台，上升虚空，高七多罗树，往到佛所，头面礼足，合十指爪，以偈赞佛：
　　容颜甚奇妙， 光明照十方， 我适曾供养， 今复还亲觐。
尔时一切众生喜见菩萨说是偈已，而白佛言：“世尊，世尊犹故在世。”尔时日月净明德佛、告一切众生喜见菩萨：“善男子，我涅槃时到，灭尽时至，汝可安施床座，我于今夜、当般涅槃。”又敕一切众生喜见菩萨：“善男子，我以佛法、嘱累于汝、及诸菩萨、大弟子，并阿耨多罗三藐三菩提法，亦以三千大千七宝世界、诸宝树、宝台、及给侍诸天、悉付于汝，我灭度后，所有舍利、亦付嘱汝，当令流布，广设供养，应起若干千塔。”如是日月净明德佛、敕一切众生喜见菩萨已，于夜后分、入于涅槃。
尔时一切众生喜见菩萨见佛灭度，悲感、懊恼，恋慕于佛，即以海此岸栴檀为□、供养佛身，而以烧之。火灭已后，收取舍利，作八万四千宝瓶、以起八万四千塔，高三世界，表刹庄严，垂诸幡盖，悬众宝铃。
“尔时一切众生喜见菩萨复自念言：“我虽作是供养，心犹未足，我今当更供养舍利。”便语诸菩萨大弟子、及天龙、夜叉、等一切大众：“汝等当一心念，我今供养日月净明德佛舍利。”作是语已，即于八万四千塔前，燃百福庄严臂七万二千岁、而以供养，令无数求声闻众、无量阿僧祇人、发阿耨多罗三藐三菩提心，皆使得住现一切色身三昧。”
“尔时诸菩萨、天、人、阿修罗、等，见其无臂，忧恼悲哀、而作是言：“此一切众生喜见菩萨，是我等师，教化我者，而今烧臂，身不具足。”于时一切众生喜见菩萨、于大众中立此誓言：“我舍两臂，必当得佛金色之身，若实不虚，令我两臂还复如故。”作是誓已，自然还复，由斯菩萨福德智慧淳厚所致。当尔之时，三千大千世界、六种震动，天雨宝华，一切人天、得未曾有。”

　　佛告宿王华菩萨：“于汝意云何，一切众生喜见菩萨，岂异人乎，今药王菩萨是也，其所舍身布施，如是无量百千万亿那由他数。宿王华，若有发心欲得阿耨多罗三藐三菩提者，能燃手指、乃至足一指、供养佛塔，胜以国城妻子、及三千大千国土山林河池、诸珍宝物、而供养者，若复有人，以七宝满三千大千世界，供养于佛、及大菩萨、辟支佛、阿罗汉，是人所得功德，不如受持此法华经、乃至一四句偈，其福最多。”
“宿王华，譬如一切川流江河，诸水之中，海为第一，此法华经、亦复如是，于诸如来所说经中，最为深大。又如土山、黑山、小铁围山、大铁围山、及十宝山，众山之中，须弥山为第一，此法华经、亦复如是，于诸经中、最为其上。又如众星之中，月天子最为第一，此法华经亦复如是，于千万亿种诸经法中、最为照明。又如日天子能除诸闇，此经亦复如是，能破一切不善之闇。又如诸小王中，转轮圣王最为第一，此经亦复如是，于众经中、最为其尊。又如帝释、于三十三天中王，此经亦复如是，诸经中王。又如大梵天王、一切众生之父，此经亦复如是，一切贤圣、学、无学、及发菩萨心者之父。又如一切凡夫人中，须陀洹、斯陀含、阿那含、阿罗汉、辟支佛、为第一，此经亦复如是，一切如来所说、若菩萨所说、若声闻所说、诸经法中，最为第一，有能受持是经典者，亦复如是，于一切众生中、亦为第一。一切声闻辟支佛中，菩萨为第一，此经亦复如是，于一切诸经法中、最为第一。如佛为诸法王，此经亦复如是，诸经中王。”
“宿王华，此经能救一切众生者，此经能令一切众生离诸苦恼，此经能大饶益一切众生，充满其愿。如清凉池、能满一切诸渴乏者，如寒者得火，如裸者得衣，如商人得主，如子得母，如渡得船，如病得医，如暗得灯，如贫得宝，如民得王，如贾客得海，如炬除暗，此法华经亦复如是，能令众生离一切苦、一切病痛，能解一切生死之缚。若人得闻此法华经，若自书，若使人书，所得功德，以佛智慧、筹量多少，不得其边。若书是经卷，华、香、璎珞、烧香、末香、涂香，幡盖、衣服，种种之灯，酥灯、油灯、诸香油灯、瞻卜油灯、须曼那油灯、波罗罗油灯、婆利师迦油灯、那婆摩利油灯、供养，所得功德，亦复无量。”
“宿王华，若有人、闻是药王菩萨本事品者，亦得无量无边功德。若有女人、闻是药王菩萨本事品，能受持者，尽是女身，后不复受。若如来灭后、后五百岁中，若有女人、闻是经典，如说修行，于此命终，即往安乐世界，阿弥陀佛、大菩萨众，围绕住处，生莲华中，宝座之上，不复为贪欲所恼，亦复不为嗔恚愚痴所恼，亦复不为憍慢嫉妒诸垢所恼，得菩萨神通、无生法忍。得是忍已，眼根清净，以是清净眼根，见七百万二千亿那由他恒河沙等诸佛如来。是时诸佛遥共赞言：“善哉、善哉，善男子，汝能于释迦牟尼佛法中、受持读诵思惟是经，为他人说，所得福德、无量无边，火不能烧，水不能漂，汝之功德，千佛共说、不能令尽。汝今已能破诸魔贼，坏生死军，诸余怨敌、皆悉摧灭。善男子，百千诸佛，以神通力、共守护汝，于一切世间、天人之中，无如汝者，惟除如来，其诸声闻、辟支佛、乃至菩萨，智慧禅定、无有与汝等者。”宿王华，此菩萨成就如是功德智慧之力。”
“若有人闻是药王菩萨本事品，能随喜赞善者，是人现世、口中常出青莲华香，身毛孔中常出牛头栴檀之香，所得功德，如上所说。是故宿王华，以此药王菩萨本事品、嘱累于汝，我灭度后、后五百岁中，广宣流布于阎浮提，无令断绝，恶魔、魔民、诸天龙、夜叉、鸠盘荼等，得其便也。”
“宿王华，汝当以神通之力、守护是经。所以者何。此经则为阎浮提人、病之良药，若人有病，得闻是经，病即消灭，不老不死。宿王华，汝若见有受持是经者，应以青莲花、盛满末香，供散其上，散已、作是念言：“此人不久、必当取草坐于道场，破诸魔军，当吹法螺、击大法鼓，度脱一切众生、老病死海。”是故求佛道者、见有受持是经典人，应当如是生恭敬心。”
说是药王菩萨本事品时，八万四千菩萨、得解一切众生语言陀罗尼。多宝如来、于宝塔中赞宿王华菩萨言：“善哉、善哉，宿王华，汝成就不可思议功德，乃能问释迦牟尼佛如此之事，利益无量一切众生。”', '妙法莲华经（Saddharmapundarika-sutra），简称《法华经》，在古印度、尼泊尔等地长期流行。在克什米尔、尼泊尔和中国新疆、西藏等地有40多种梵文版本，分为尼泊尔体系、克什米尔体系（基尔基特）和新疆体系。尼泊尔体系版本约为11世纪后作品，保持完整，已出版5种校订本。1983年北京民族文化宫图书馆用珂罗版彩色复制出版了由尼泊尔传入、珍藏于西藏萨迦寺的法华经。', '', '这时，宿王华菩萨对释迦牟尼佛说：世尊，药王菩萨是何因缘来到这个娑婆世界游历的？世尊，这位药王菩萨修习过若干百千万亿兆种难以修行的苦行，好啊！世尊，愿您为我们稍作解说。法会上的各位天神、龙神、乾闼婆、阿修罗、迦楼罗、紧那罗、摩睺罗伽等天龙八部和人与非人的鬼神等，另外还有其他国土来的诸位菩萨以及此方的声闻弟子等，听了宿王华菩萨向佛请问后，都十分欢喜。
这时，释迦牟尼佛告诉宿王华菩萨说：从现在向过去追溯无量条恒河的所有沙数那么多的劫数，那时，有一位佛名叫日月净明德如来，同时具足十种称号，即：应供、正遍知、明行足、善逝、世间解、无上士、调御丈夫、天人师、佛、世尊。这位佛身边有八十亿个大菩萨，有七十二条恒河沙数那么多的大声闻弟子。佛的寿命达四万二千劫，菩萨和寿命也是这么长。这个佛国中没有女人，没有地狱、饿鬼、畜生等三种恶道，也没有各种灾难和痛苦。大地平坦得犹如手掌一般，全都是琉璃铺成。大地上，宝树成行，一派庄严。宝树上，宝帐覆盖，宝华披挂，宝幡下垂。宝瓶与香炉，遍布全国各地。七宝作成高台，每有一树即有一台，宝树与宝台相距一箭之地。这些宝树下都坐有菩萨和声闻弟子。所有的宝台上，各有百亿天神演奏天乐，表演伎艺，歌颂佛陀，作为供养。
那时，日月净明德佛为一切众生都喜欢见到的菩萨以及其他各位菩萨、各位声闻乘弟子演说《法华经》。这位名叫一切众生喜见的菩萨喜欢修习苦行，他在日月净明德佛的正法中，精进修行，一心追求佛果。经过整整一万二千年之后，终于获得了变现一切色身的禅定神力。获得了这种禅定神力后，一切众生喜见菩萨心中十分欢喜，于是他这样说道：我之所以能获得变现一切色身的禅定之力，都是因为得闻《法华经》的力量所致，所以，我应当供养日月净明德佛和《法华经》。于是，他立即进入这种禅定状态，升于虚空之中，像下雨一样将小曼陀花、大曼陀花和坚硬的黑色栴檀香末细末散落下来，一时间，整个天空犹如密云相聚，缤纷而下。同时，还像下雨一样洒下北海南岸产的栴檀之香，这种香的六铢重理，其价值相当于一个娑婆世界。如今，一切众生喜见菩萨把它拿来供养日月净明德佛。
作完了这些供养之后，一切众生喜见菩萨从禅定中起来，心中暗自想道：我虽然以神力供养了佛，不如以身躯来供养佛。于是，他立即饮服各种妙香，如栴檀香、薰陆香、兜楼婆香、毕力迦香、沉水香、胶香。他又饮下了瞻卜等鲜花制成的香油。如此经过一千二百年，他又用香油涂抹身体，然后，在日月净明德佛前，用天上的宝衣将自己的身躯缠绕起来，再灌下各种香油。这时，一切众生喜见菩萨以其神通愿力，自焚其身。火光照遍了八十亿恒沙数那么多的世界。这些世界之中的每一位佛都异中同声地赞叹道：好啊！好啊！善男子，这才是真正的精进修行，这才是真正法供养如来。以华、香、璎珞以及各种烧香、末香、涂香以及天缯、幡盖和北海此岸的栴檀香等种种东西供养，比不上这种以身体而进行的供养，即使以国城、以妻子进行布施，也比不上这种以身躯而进行的布施。善男子，你这各焚身供佛的布施叫作第一布施，这是所有布施中最尊贵、最上第的布施，因为，这实际上是在以法来供养所有的如来世尊。说完这些话后，诸位如来世尊便各种黯然不语。一千二百年后，一切众生喜见菩萨的身躯才全部焚烧而尽。
一切众生喜见菩萨作完这种法供养之后，生命便完结了。由此他又转生到日月净明德佛的佛国中，在一个名叫净德的王室之家双膝打坐，忽然间便化成一个童子，并对其托生的父亲以偈语格式说道：大王现在应当知道，我当年游历到你这里时，获得了变现一切色身的禅定神力。我勤加修行这种法门，勇猛精进不息，后来，便舍去了所有爱惜的身躯，把它供养给了世尊，以求得至高无上的智慧。
说完这些偈语之后，又对其父亲说：日月净明德佛今天依然还在这个世界中。我原先供养了这位如来世尊后，获得了通晓一切众生语言的陀罗尼法门，接著又从此佛处听到这部《法华经》中的八百千万亿兆甄伽罗、频婆罗、阿閦婆等为数巨大的经偈词句。大王，我今应当再回去供养这位日月净明德佛。说完之后，一切众生喜见菩萨托生的童子便坐到七宝台上，自行上升到空中，高达七棵多罗树。来到佛的住地后，他走下宝台，在佛面前顶礼膜拜，双手合十，以偈颂格式赞叹佛说：佛的容颜极为奇妙，佛的光明遍照十方。我前生时曾供养于您，今天，我再来亲自觐见于您。
一切从生喜见菩萨说完这首偈之后，又对日月净明德佛这样说：世尊啊世尊，您依然在这世上！这时，日月净明德佛告诉一切从生喜见菩萨说：善男子，我涅槃的时候到了，灭尽的时期来临了。你现在可以安置床座，我于今天夜里，将要进入涅槃。 日月净明德佛又敕令一切从生喜见菩萨说：善男子，我把佛法嘱托给你和各位菩萨、各位大弟子。除了这无上圣智之法外，我把三千大千世界的七种珍宝、各世界中的所有宝树、宝台以及专门从事供给与奉持的各位天神也都交付于你。我灭度之后，所得的全部舍利也交付嘱托于你，你应当把它们分散各地，广设供养，建起数千座宝塔。如此一一嘱托完毕之后，日月净明德佛才进入了涅槃。
一切从生喜见菩萨见佛去世灭度，悲感交集，懊恼不已。出于对佛的恋慕，他便用北海此岸的名贵栴檀木作为薪柴，先对佛的身躯作了供养，然后佛点火烧之。火灭之后，他又收取佛的舍利，建起了八万四千座佛舍利塔，每座塔都有三个世界那么高，塔刹非常庄严，上面垂挂著各种宝幡、宝盖，还悬挂著各种宝玲。这时，一切众生喜见菩萨又暗自想道：我虽然作了这些供养，可对佛的心愿并未满足，我现在应当再供养佛的舍利。于是，他就对各位菩萨大弟子及天神、龙神、夜叉等所有大众说：你们应当一心念，我现在要供养日月净明德佛的舍利了。说完这话之后，一切众生喜见菩萨就在八万四千座舍利塔前，将自己那以百福严饰的胳臂燃烧起来，足足烧了七万二千岁，以此作为对佛舍利的供养 ，也使无数追求声闻果位的弟子和其他无量无数的人都发下了求证至高无上圣智的心愿，使他们都能进住于变现一切色身的禅定神通之中。
这时，诸位菩萨以及天神、人类、阿修罗等，看见一切众生喜见菩萨没有了胳臂，所以都非常忧愁烦恼，悲伤哀怜，他们说：这位一切众生喜见菩萨是教化我们的师父，他如今燃臂供佛，致使身体残缺。这时，一切众生喜见菩萨在大众中立下誓言说：我虽舍去了两臂，却必将得到佛的金色之身。若此话真实不虚，就让我两臂恢复原状吧！发了这个誓愿之后，一切众生喜见菩萨的双臂果真自然复原如初。这都是这位菩萨的福德与智慧非常淳厚所致。当此之时，三千大千世界发生了六种震动，天空之中下雨般降下了各种宝花，所有的人和天神都经历了一次前所未有的盛事。
释迦牟尼佛对宿王华菩萨说：在你看来，一切众生喜见菩萨难道是旁人吗？他其实就是现在的药王菩萨。他这样舍身布施，已有无量百千万亿兆的次数了。宿王华，如果哪位发愿欲得无上圣智的人能燃手指或脚中的一指，以供养佛塔，那么，他的布施便胜过以国城、妻子及三千大千世界的国土、山林、河池与各种珍宝所进行的供养。如果又有人把七种珍宝布满整个三千大千世界，拿来代养于佛以及菩萨、辟支佛、阿罗汉，那么此人所获得的功德，不如受持这部《法华经》甚至只受持其中的一首四句诗颂所获得的功德。受持《法华经》的功德是最多的。
宿王华，譬如所有川流江河等诸水之中，海为第一，这部《法华经》也是如此，在诸位如来世尊所说的各种佛经中，《法华经》最为深奥，最为博大。又譬如，在土山、黑山、小铁围山、大铁围山以及十宝山等众山之中，须弥山为第一，这部《法华经》也是如此，在所有的佛经中地位最高。又譬如，在群星之中，月亮为第一，这部《法华经》也是如此，在千万亿经法之中，此经的光辉最为明亮，又譬如太阳，它能照破一切黑暗，这部经典也是这样，它能照破一切不善的黑暗。又譬如在各种国王之中，持轮圣王为第一，此经也是如此，它在诸经中最为尊贵。又譬如天帝是三十三天中所有天神的大王，此经也是如此，它是所有佛经中的王。又譬如大梵天王，他是一切众生的父亲，此经也是如此，它是一切圣贤和证得小乘有学果和无学果的圣者以及发愿修菩萨道的菩萨们的父亲。又譬如在一切凡夫面前，须陀洹、斯陀含、阿那含、阿罗汉、辟支佛位处第一，此经也是如此，在所有如来世尊所说或菩萨、声闻所说的各种经法之中，此经位处第一。受持这部经典的人也是这样，他在一切众生之中位处第一。在所有的声闻、辟支佛面前，菩萨位处第一，此经也是如此，在一切经法之中，此经位处第一。再如来世尊为一切佛法中的法王，此经也是如此，是一切经典之王。
宿王华，这部经典能充当一切众生的救度者，它能使一切众生离开各种苦恼，能为一切众生带来巨大的利益，使所有众生圆满自己的心愿。譬如清凉和水池能满足一切干渴困乏的人，又如寒者得火，裸者得衣，如商人得到顾主，游子得到母亲，又如渡河得船，病中得医，如黑暗时见到光明，贫困时得到宝贝，如人民遇到英明的国王，商贾得到海中的珠宝，如火炬驱除一切黑暗，这部《法华经》也是这样，它能使众生远离一切痛苦、一切疾病，能够自己抄写或让他人抄写，那么，他所得的功德，即使以佛的智慧来筹算其多少，也难以穷其边际。如果抄写了这部经卷之后，还能用鲜花、香料、璎珞、烧香、末香、涂香、宝幡、宝盖、衣服、各种灯明如酥油灯、香油灯、各种混合香油灯、金色花油灯、悦意花油灯、重生花油灯、夏生花油灯、、杂色花油灯等各种各样供具来供养经卷，那么，由此所得的功德，也是不可计量的。
宿王华菩萨，如果有人听到了《法华经》中的这篇《药王菩萨本事品》，那么，此人由此也可获得无边的功德。如果哪位女人听到了这篇《药王菩萨本事品》后，能够信受、持行，那么，她此生的女身完结之后，来世转生将不再是女人。在佛灭度之后五个五百岁的最后一个五百岁中，若有女人听到这部经典，并按经中所说去修行，那么，她在此生命终之后，即可往生西方极乐世界阿弥陀佛和围绕在阿弥陀佛身边的大菩萨众生的住处，从莲花中化生，在宝座上安坐，不再为贪欲所恼乱，也不再为瞋怒、愚痴所恼乱，也为再为傲慢和嫉妒等尘垢所恼乱，获得了菩萨的神通，证到了安住于不生不灭的真如实相理体的智慧。获得了这种智慧之后，他的眼根变得清净无染，从而看到了七百万二千亿兆恒河所有沙数那么多的如来世尊。此时，这些如来世尊各自从遥远的地方称赞道：善哉！善哉！善男子，你能在释迦牟尼的法佛中，受持、读诵、思惟这部《法华经》，为他人演说，所以，你所获得的福德是无量无边的。大火不能烧毁，洪水不能漂没，你的功德，就是千佛共说也不能穷尽。你现已能破除各种魔贼，尽享清净之乐;毁坏生死之军，不受轮回之苦。其他各种怨敌，也都能摧灭。善男子，成百上千的佛以神通之力共同守护著你。在所有世间的一切天神与人类之中，没有谁能像你一样。除过如来世尊之外，在一切摆脱世间轮回的圣者之中，声闻、辟支佛甚至菩萨，在智慧与禅定方面，都不能与你相比。
宿王华，这位闻经修行、往生净土的菩萨，他的确能获得这样的功德，成就这样的智慧之力。若有人听到这篇《药王菩萨本事品》后，能够随顺经义，生欢喜之心，赞其美好，那么，此人在现世中，口里经常可以呼出青莲花那么样的香味，身上各毛孔中也能时常放出牛头栴檀的香气。他所获得的功德，和上面所说的功德完全一样。所以，宿王华，我要将这篇《药王菩萨本事品》嘱托于你，你应在我灭度之后的最后一个五百年中，在这个人类居住的阎浮提洲广泛宣讲此品经文，不要让它中断消失，以免恶魔、魔民、某些天神、龙神、夜叉以及恶鬼等有可趁之机。宿王华，你应当以神通之力守护此经，为什么呢？因为，此经是这个阎浮提洲所有人治病的良药。如果有人病了，听到这部经典，疾病即可祛除，甚至不会衰老，不会死亡。宿王华，你如果看见有人受持这部经典，就应当以青莲花供养他，同时盛满末香，散布在他的身上。散毕之后，这样想：此人不久必将取草为座，坐在菩提道场之中，破除各路魔军。他必将吹响大法螺，击响大法鼓，把一切众生从生、老、病、死的苦海之中度脱出来。所以，凡是要求证佛道的人，如果看到有人受持这部经典，就应当对其生起恭敬之心。
释迦牟尼佛讲说《药王菩萨本事品》时，有八万四千菩萨获得了通晓一切众生语言的陀罗尼法门。多宝如来在宝塔中称赞宿王华菩萨说：善哉！善哉！宿王华，你成就了不可思议的功德，因此你能向释迦牟尼佛询问这样的事缘，使无量无边众生都由此获得了利益。', NULL, '', 'indent', 1526662605, '5ab528c017d0096887744a74', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636663, '妙法莲华经 · 妙音菩萨品第二十四', NULL, 1, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%A6%99%E6%B3%95%E8%8E%B2%E5%8D%8E%E7%BB%8F/1772696?fr=aladdin', '', '尔时释迦牟尼佛放大人相、肉髻光明，及放眉间白毫相光，遍照东方百八万亿那由他恒河沙等诸佛世界。过是数已，有世界、名净光庄严，其国有佛，号净华宿王智如来、应供、正遍知、明行足、善逝世间解、无上士、调御丈夫、天人师、佛、世尊，为无量无边菩萨大众恭敬围绕、而为说法，释迦牟尼佛白毫光明遍照其国。
尔时一切净光庄严国中，有一菩萨、名曰妙音，久已植众德本，供养亲近无量百千万亿诸佛，而悉成就甚深智慧，得妙幢相三昧、法华三昧、净德三昧、宿王戏三昧、无缘三昧、智印三昧、解一切众生语言三昧、集一切功德三昧、清净三昧、神通游戏三昧、慧炬三昧、庄严王三昧、净光明三昧、净藏三昧、不共三昧、日旋三昧、得如是等百千万亿恒河沙等诸大三昧。释迦牟尼佛光照其身，即白净华宿王智佛言：“世尊，我当往诣娑婆世界，礼拜、亲近、供养、释迦牟尼佛，及见文殊师利法王子菩萨、药王菩萨、勇施菩萨、宿王华菩萨、上行意菩萨、庄严王菩萨、药上菩萨。”
尔时净华宿王智佛告妙音菩萨：“汝莫轻彼国，生下劣想。善男子，彼娑婆世界，高下不平，土石诸山、秽恶充满，佛身卑小，诸菩萨众、其形亦小，而汝身四万二千由旬，我身六百八十万由旬，汝身第一端正，百千万福、光明殊妙，是故汝往、莫轻彼国、若佛菩萨、及国土，生下劣想。”妙音菩萨白其佛言：“世尊，我今诣娑婆世界，皆是如来之力，如来神通游戏，如来功德智慧庄严。”于是妙音菩萨不起于座，身不动摇，而入三昧，以三昧力，于耆阇崛山、去法座不远，化作八万四千众宝莲华，阎浮檀金为茎，白银为叶，金刚为须，甄叔迦宝以为其台。
尔时文殊师利法王子、见是莲华，而白佛言：“世尊，是何因缘，先现此瑞，有若干千万莲华，阎浮檀金为茎，白银为叶，金刚为须，甄叔迦宝以为其台。”尔时释迦牟尼佛告文殊师利：“是妙音菩萨摩诃萨，欲从净华宿王智佛国，与八万四千菩萨、围绕而来，至此娑婆世界，供养、亲近、礼拜、于我，亦欲供养、听法华经。”
文殊师利白佛言：“世尊，是菩萨种何善本？修何功德？而能有是大神通力？行何三昧？愿为我等说是三昧名字，我等亦欲勤修行之，行此三昧，乃能见是菩萨色相大小，威仪进止。惟愿世尊以神通力，彼菩萨来，令我得见。”尔时释迦牟尼佛告文殊师利：“此久灭度多宝如来、当为汝等而现其相。”
时多宝佛告彼菩萨：“善男子、来，文殊师利法王子欲见汝身。”于时妙音菩萨于彼国没，与八万四千菩萨、俱共发来，所经诸国，六种震动，皆悉雨于七宝莲华，百千天乐，不鼓自鸣。是菩萨目如广大青莲华叶，正使和合百千万月，其面貌端正、复过于此，身真金色，无量百千功德庄严，威德炽盛，光明照曜，诸相具足，如那罗延坚固之身。入七宝台，上升虚空，去地七多罗树，诸菩萨众恭敬围绕、而来诣此娑婆世界耆阇崛山。
到已下七宝台，以价值百千璎珞、持至释迦牟尼佛所，头面礼足，奉上璎珞，而白佛言：“世尊，净华宿王智佛问讯世尊，少病、少恼，起居轻利，安乐行否，四大调和否，世事可忍否，众生易度否，无多贪欲、嗔恚、愚痴、嫉妒、悭慢否，无不孝父母、不敬沙门、邪见、不善心、不摄五情否，世尊，众生能降伏诸魔怨否，久灭度多宝如来在七宝塔中、来听法否，又问讯多宝如来，安隐、少恼，堪忍久住否。世尊，我今欲见多宝佛身，惟愿世尊，示我令见。”
尔时释迦牟尼佛语多宝佛：“是妙音菩萨欲得相见。”时多宝佛告妙音言：“善哉、善哉，汝能为供养释迦牟尼佛、及听法华经，并见文殊师利等，故来至此。”
尔时华德菩萨白佛言：“世尊，是妙音菩萨，种何善根，修何功德，有是神力。”佛告华德菩萨：“过去有佛，名云雷音王多陀阿伽度、阿罗诃、三藐三佛陀，国名现一切世间，劫名喜见，妙音菩萨于万二千岁，以十万种伎乐、供养云雷音王佛，并奉上八万四千七宝钵，以是因缘果报，今生净华宿王智佛国，有是神力。华德，于汝意云何，尔时云雷音王佛所、妙音菩萨，伎乐供养、奉上宝器者，岂异人乎，今此妙音菩萨摩诃萨是。华德，是妙音菩萨，已曾供养亲近无量诸佛，久植德本，又值恒河沙等百千万亿那由他佛。”
“华德，汝但见妙音菩萨、其身在此，而是菩萨、现种种身，处处为诸众生说是经典，或现梵王身，或现帝释身，或现自在天身，或现大自在天身，或现天大将军身，或现毗沙门天王身，或现转轮圣王身，或现诸小王身，或现长者身，或现居士身，或现宰官身，或现婆罗门身，或现比丘、比丘尼、优婆塞、优婆夷身，或现长者居士妇女身，或现宰官妇女身，或现婆罗门妇女身，或现童男童女身，或现天龙、夜叉、乾闼婆、阿修罗、迦楼罗、紧那罗、摩侯罗伽、人非人、等身，而说是经。诸有地狱、饿鬼、畜生、及众难处，皆能救济，乃至于王后宫，变为女身、而说是经。”

　　“华德，是妙音菩萨，能救护娑婆世界诸众生者，是妙音菩萨如是种种变化现身，在此娑婆国土，为诸众生说是经典，于神通、变化、智慧、无所损减。是菩萨，以若干智慧、明照娑婆世界，令一切众生、各得所知，于十方恒河沙世界中，亦复如是，若应以声闻形得度者，现声闻形而为说法，应以辟支佛形得度者，现辟支佛形而为说法，应以菩萨形得度者，现菩萨形而为说法，应以佛形得度者，即现佛形而为说法，如是种种、随所应度而为现形，乃至应以灭度而得度者，示现灭度，华德，妙音菩萨摩诃萨、成就大神通智慧之力，其事如是。”
尔时华德菩萨白佛言：“世尊，是妙音菩萨、深种善根，世尊，是菩萨、住何三昧，而能如是在所变现，度脱众生？”佛告华德菩萨：“善男子，其三昧、名现一切色身，妙音菩萨住是三昧中，能如是饶益无量众生。”说是妙音菩萨品时，与妙音菩萨俱来者八万四千人，皆得现一切色身三昧，此娑婆世界无量菩萨，亦得是三昧、及陀罗尼。
尔时妙音菩萨摩诃萨供养释迦牟尼佛、及多宝佛塔已，还归本土，所经诸国，六种震动，雨宝莲华，作百千万亿种种伎乐。既到本国，与八万四千菩萨、围绕至净华宿王智佛所，白佛言：“世尊，我到娑婆世界、饶益众生，见释迦牟尼佛、及见多宝佛塔，礼拜、供养，又见文殊师利法王子菩萨，及见药王菩萨、得勤一精一进力菩萨、勇施菩萨等，亦令是八万四千菩萨、得现一切色身三昧。说是妙音菩萨来往品时，四万二千天子、得无生法忍，华德菩萨、得法华三昧。”', '妙法莲华经（Saddharmapundarika-sutra），简称《法华经》，在古印度、尼泊尔等地长期流行。在克什米尔、尼泊尔和中国新疆、西藏等地有40多种梵文版本，分为尼泊尔体系、克什米尔体系（基尔基特）和新疆体系。尼泊尔体系版本约为11世纪后作品，保持完整，已出版5种校订本。1983年北京民族文化宫图书馆用珂罗版彩色复制出版了由尼泊尔传入、珍藏于西藏萨迦寺的法华经。', '', '这时，释迦牟尼佛从三十二种大人相中的肉髻相中放出光明，又从两眉之间放出白毫相光，这两种佛光照遍东方一百八十万亿兆恒河所有沙数那么多的佛国世界。越过这些数目的世界，有一个佛，名叫净华宿王智如来，此佛同时具足十号，即：应供、正遍知、明行足、善逝、世间解、无上士、调御丈夫、天人师、佛、世尊。净华宿王智如来为恭敬围绕在他身边的无量大无边的菩萨大众讲经说法。释迦牟尼佛的白毫相光照遍了其国。
那时，这个一切净光庄严佛国中有一个菩萨名叫妙音。此菩萨在很久很久之前，就已种下了许多善根，供养、亲近过无量百千万亿的佛，所以成就了甚深的智慧，获得了各种三昧即妙定的境界，如：妙幢相三昧、法华三昧、净德三昧、宿王戏三昧、无缘三昧、智印三昧、解一切众生语言三昧、集一切功德三昧、清净三昧、神通游戏三昧、慧炬三昧、庄严王三昧、净光明三昧、净藏三昧、不共三昧、日旋三昧，等等，共获得了百千万亿恒河沙数那么多的三昧。释迦牟尼佛的光明照耀在妙音菩萨身上，妙音菩萨便对净华宿王智佛说：世尊，我应当前往娑婆世界礼拜、亲近、供养释迦牟尼佛，并拜见文殊师利菩萨、药王菩萨、勇施菩萨、宿王华菩萨、上行意菩萨、庄严王菩萨、药上菩萨。
这时，净华宿王智佛告诉妙音菩萨说：你不要轻视那个国土，不要产生下劣的想法。善男子，那个娑婆世界高低不平，充满了各种土山、石山和污秽、恶浊。那里的佛陀，身材矮小，诸菩萨大众的身材也很小，而你的身高四万二千由旬，我的身高六百八十万由旬。你的身相最为端正，具备了百千万种福相，又能放出清净而殊妙的光明，所以，你到娑婆世界，切莫轻慢那里的一切，譬如不要对那里的佛、菩萨和国土产生下劣的想法。
妙音菩萨对净华宿王智佛说：世尊，我现在到娑婆世界去，都是凭佛的力量，佛的神通游戏，佛的功德智慧来庄严自己。于是，妙音菩萨仍然坐在座上，既不站起，也不摇动，而是进入禅定状态，并以这种定力来到娑婆世界的耆阇崛山，在离释迦牟尼佛法座不远的地方，化出八万四千朵众宝而成的莲花，这种莲花以阎浮檀金为茎，以白银为叶，以金刚为花须，用甄叔迦宝石作为花台。
这时，文殊师利法王子见到这些殊胜的莲花，便对释迦牟尼佛说：世尊，是什么因缘而现出这样的祥瑞景象呢？那成千上万朵莲花，个个以阎浮檀金为茎，以白银为叶，以金刚为花须，用赤红的甄叔迦宝石作为花台。
释迦牟尼佛告诉文殊师利菩萨说：这是妙音大菩萨想与围绕在他身边的八万四千菩萨，从净华宿王智佛的东方净光庄严佛国，来到这个到娑婆世界，前来供养我，亲近人，礼拜我，也是为了供养并聆听《法华经》。
文殊师利菩萨对佛说：世尊，这位菩萨种下了何种善根？修下了何种功德？怎么会有这么大的神通之力呢？他修得的是什么样的禅定呢？愿你为我们讲说这种妙定的名称，我们也想勤奋修习这种妙定。因为，修行这种妙定，才能看见这位菩萨身相大小，才能看见他的行、住之威议。等那位菩萨来到后，愿世尊以神通力使我们能够看见。
这时，释迦牟尼佛告诉文殊师利菩萨说：这位久已灭度的多宝如来将为你们现出妙音菩萨的景象。这时，多宝佛告诉妙音菩萨说：善男子，请你来吧，文殊师利法王子想见到你的身相。
当此之时，妙音菩萨在他所处的佛国中隐没了。他率领八万四千菩萨一起出发，直奔娑婆世界而来，途中所经过的每一个佛国，大地均发出了六种震动，天空下雨般散下七宝莲花，成百上千种天乐，不用鼓动，自然响彻云霄。这位妙音菩萨的双目就像宽大的莲花叶，目光犹如百千万个月亮交相辉映。其面貌炎端正更胜过这种情景。他的身体是真金的颜色。无量的功德使其无处不美丽，无处不庄严，所以，他的威德如火般炽盛，他的身光，灿烂明亮，照耀一切，他的外相，无不具足，无不庄严，就像金刚力士那样健壮而潇洒。妙音菩萨坐在七宝莲花台上，上升到虚空之中，离地面有七棵多罗树那么高，在那些菩萨大众的恭敬围绕下，来到了这个到娑婆世界的耆阇崛山。
来到耆阇崛山之后，妙音菩萨从七宝台上下来，手持价值连城的百千种璎珞，来到释迦牟尼佛面前，顶礼膜拜，奉上璎珞，对佛说：世尊，净华宿王智佛向您问好，您没有病痛，没有烦恼吧？您日常起居轻松顺利吧？您行、住、坐、卧安稳快乐吧？众生容易救度吧？众生不会有太多的贪欲、瞋怒、愚痴、嫉妒、悭慢吧？没有不孝敬父母、不恭敬沙门的众生吧？没有充满邪见和不善之心、不能收摄喜、怒、爱、恶、欲等五种情感的众生吧？世尊，众生能降伏一切魔怨吧？久已灭度的多宝如来在七宝塔中也来听您说法吧？净华宿王智佛还让我向多宝如来问好，他近来身心安稳、无忧无恼吧，还能忍耐久住吧？世尊，我现在就想见到多宝如来的身相，惟愿世尊指示以便让我见到这位如来世尊。这时，释迦牟尼佛对多宝佛说：这位妙音菩萨想与你相见。
这时，多宝佛告诉妙音菩萨说：善哉！善哉！你为了供养释迦牟尼佛和聆听《法华经》并拜见文殊师利等菩萨，而来到这个到娑婆世界。
这时，法会中有一位名叫华德的菩萨对佛说：世尊，这位妙音菩萨，他在往昔因地时种下何种善根？修下了何各功德？怎么会有这样的神力呢？
释迦牟尼佛告诉华德的菩萨说：很早以前，有一位佛，名叫云雷音王佛，他有如来、应供、正遍知等称号。当时的国名叫现一切世间，所处的劫，名叫喜见。妙音菩萨在一万二千年当中，以十万种伎乐供养云雷音王佛，并为佛奉献了八万四千个七宝制成的宝钵，由于这个原因和果报，他现在才生在净华宿王智佛国，并具备了这样的神力。华德菩萨，在你看来，那时在云雷音王佛面前，以伎乐进行供养并奉上宝钵的妙音菩萨难道是另一个人吗？他就是现在的这位妙音大菩萨。华德，这位妙音菩萨已曾供养、亲近过无数位如来世尊，很久很久以来，就种下了善根，另外，他所遇到的佛，有恒河沙那么多的成百上千直至万亿兆。
华德，你只看见妙音菩萨的身躯在此，其实，这位菩萨能现各种身相，到处为各类众生演说这部《法华经》。他或者现梵王身，或者现天帝身，或者现自在天身，或者现大自在天身，或者现天大将军身，或者现四大天王中的毗沙门天王身，或者现持轮宝的神圣国王身，或者现各种小王身，或者现长者身，或者现宰官身，或者现婆罗门身，或者现比丘身、比丘尼身、男居士身、女居士身，或者现长者妇身、居士妇人身，或者现官吏妇人身，或者现婆罗门妇人身，或者现童男、童女身，或者现天神、龙神、乾闼婆、阿修罗、迦楼罗、紧那罗、摩睺罗伽等天龙八部以及人与非人等的身相。通过示现这些不同的身相而为不同的众生讲说这部《法华经》。在地狱、饿鬼，畜生之中以及各种困难的场合，他都能前去救济，甚至变成女身，深入国王的后宫之中，为宫女们讲说这部经典。华德，这位妙音菩萨是能救护娑婆世界所有众生的菩萨。这位妙音菩萨如此显现各种各样的变化身相，在这个娑婆世界，为所有众生讲说《法华经》，可是，他的神通力、他的显化力以及他的智慧，却毫无损减。
这位菩萨用他的种种智慧光明来照耀我们这个娑婆世界，使一切众生各自得到应该知道的佛法。不但在娑婆世界如此，就是在十方恒沙数那么多的世界中，妙音菩萨也是这样来救度众生。如果有应该以声闻身形获得救度的众生，妙音菩萨就示现声闻形身而为其说法;如果有应该以辟支佛身形获得救度的众生，妙音菩萨就现示辟支佛身形而为其说法;如果应该以菩萨身形获得救度的众生，妙间菩萨就示现菩萨身形而为其说法;如果有应该以佛的身形而获得救度的众生，妙音菩萨便示现佛的身形为其而说法。如此各种各样的身形，都是随著所应救度的众生的不同身形而显现出相应的身形，甚至遇到应该以灭度的涅槃身形获得救度的众生，妙音菩萨还会示现灭度之相。华德，妙音大菩萨所成就的巨大神通与智慧之力，就是这样。
这时华德菩萨对佛说：世尊，这位妙音菩萨的确深深种下了善根。世尊，此菩萨安住于何种妙定而能如此随时随地变化示现不同的身相，以求度众生脱离苦难？
释迦牟尼佛告诉华德的菩萨说：善男子，妙音菩萨所安住的妙定境界，名叫现一切色身。妙音菩萨住在这种妙定之中，所以，能像刚才所说的那样给众生带来很大的好处。
释迦牟尼佛讲说这篇《妙音菩萨品》时，与妙音菩萨一同前往来的八万四千人都证得了名叫现一切色身的妙定。这个娑婆世界中的无数菩萨也获得了这种妙定以及陀罗尼的法门。
妙音大菩萨供养释迦牟尼佛及多宝佛塔后，便返回自己所在的国土。途中所经过的各个国土都发生了六种震动，天空中像下雨一样散下宝莲之花，并自然出现了百千万亿种歌舞与妙乐。到达本国之后，妙音菩萨与围绕在他周围的八万四千菩萨来到净华宿王智佛面前，对佛说：世尊，我这次到娑婆世界去，使那里的众生蒙益受惠，我还见到了释迦牟尼佛，见到了多宝佛塔，并对其都进行了礼拜和供养。我还见到了文殊师利法王子菩萨，见到了药王菩萨、得勤精进力菩萨、勇施菩萨等大菩萨，也使与人随形的八万四千菩萨都获得了名叫现一切色身的妙定。
释迦牟尼佛讲说这部《妙音菩萨来往品》时，有四万二千名天子证得了安住为生不灭之实相理体的无生法忍，华德菩萨则证得了依据《法华经》思惟谛观中道实相之理的法华三昧。', NULL, '', 'indent', 1526662620, '5ab529669f54547d1c3e401b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636664, '妙法莲华经 · 观世音菩萨普门品第二十五', NULL, 7, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%A6%99%E6%B3%95%E8%8E%B2%E5%8D%8E%E7%BB%8F/1772696?fr=aladdin', '', '尔时无尽意菩萨、即从座起，偏袒右肩，合掌向佛、而作是言：“世尊，观世音菩萨、以何因缘、名观世音？”佛告无尽意菩萨：“善男子，若有无量百千万亿众生、受诸苦恼，闻是观世音菩萨，一心称名，观世音菩萨即时观其音声，皆得解脱。若有持是观世音菩萨名者，设入大火，火不能烧，由是菩萨威神力故。若为大水所漂，称其名号，即得浅处。若有百千万亿众生，为求金、银、琉璃、砗磲、玛瑙、珊瑚、琥珀、真珠、等宝，入于大海，假使黑风吹其船舫、飘堕罗刹鬼国，其中若有乃至一人、称观世音菩萨名者，是诸人等，皆得解脱罗刹之难。以是因缘，名观世音。”
“若复有人、临当被害，称观世音菩萨名者，彼所执刀杖、寻段段坏，而得解脱。若三千大千国土，满中夜叉、罗刹，欲来恼人，闻其称观世音菩萨名者，是诸恶鬼、尚不能以恶眼视之，况复加害。设复有人，若有罪、若无罪，杻械、枷锁、检系其身，称观世音菩萨名者，皆悉断坏，即得解脱。若三千大千国土、满中怨贼，有一商主，将诸商人，赍持重宝、经过险路，其中一人、作是唱言：“诸善男子、勿得恐怖，汝等应当一心称观世音菩萨名号，是菩萨能以无畏施于众生，汝等若称名者，于此怨贼、当得解脱。”众商人闻，俱发声言：“南无观世音菩萨。”称其名故，即得解脱。”
“无尽意，观世音菩萨摩诃萨威神之力、巍巍如是。若有众生、多于淫欲，常念恭敬观世音菩萨，便得离欲。若多嗔恚，常念恭敬观世音菩萨，便得离嗔。若多愚痴，常念恭敬观世音菩萨，便得离痴。无尽意，观世音菩萨、有如是等大威神力，多所饶益，是故众生、常应心念。若有女人、设欲求男，礼拜供养观世音菩萨，便生福德智慧之男，设欲求女，便生端正有相之女，宿植德本，众人爱敬。无尽意，观世音菩萨有如是力，若有众生、恭敬礼拜观世音菩萨，福不唐捐，是故众生皆应受持观世音菩萨名号。”
“无尽意，若有人、受持六十二亿恒河沙菩萨名字，复尽形供养饮食、衣服、卧具、医药，于汝意云何，是善男子、善女人、功德多否？”
无尽意言：“甚多，世尊。”佛言：“若复有人、受持观世音菩萨名号，乃至一时礼拜、供养，是二人福，正等无异，于百千万亿劫、不可穷尽，无尽意，受持观世音菩萨名号，得如是无量无边福德之利。”
无尽意菩萨白佛言：“世尊，观世音菩萨、云何游此娑婆世界，云何而为众生说法，方便之力，其事云何？”佛告无尽意菩萨：“善男子，若有国土众生、应以佛身得度者，观世音菩萨即现佛身而为说法。应以辟支佛身得度者，即现辟支佛身而为说法。应以声闻身得度者，即现声闻身而为说法。应以梵王身得度者，即现梵王身而为说法。应以帝释身得度者，即现帝释身而为说法。应以自在天身得度者，即现自在天身而为说法。应以大自在天身得度者，即现大自在天身而为说法。应以天大将军身得度者，即现天大将军身而为说法。应以毗沙门身得度者，即现毗沙门身而为说法。应以小王身得度者，即现小王身而为说法。应以长者身得度者，即现长者身而为说法。应以居士身得度者，即现居士身而为说法。应以宰官身得度者，即现宰官身而为说法。应以婆罗门身得度者，即现婆罗门身而为说法。应以比丘、比丘尼、优婆塞、优婆夷身得度者，即现比丘、比丘尼、优婆塞、优婆夷身而为说法。应以长者、居士、宰官、婆罗门妇女身得度者，即现妇女身而为说法。应以童男、童女身得度者，即现童男、童女身而为说法。应以天龙、夜叉、乾闼婆、阿修罗、迦楼罗、紧那罗、摩侯罗伽、人非人、等身、得度者，即皆现之而为说法。应以执金刚神得度者，即现执金刚神而为说法。”
“无尽意，是观世音菩萨成就如是功德，以种种形、游诸国土，度脱众生，是故汝等应当一心供养观世音菩萨。是观世音菩萨摩诃萨，于怖畏急难之中、能施无畏，是故此娑婆世界、皆号之为施无畏者。”
无尽意菩萨白佛言：“世尊，我今当供养观世音菩萨。”即解颈众宝珠璎珞、价值百千两金，而以与之，作是言：“仁者，受此法施珍宝璎珞。”时观世音菩萨不肯受之。无尽意复白观世音菩萨言：“仁者，愍我等故，受此璎珞。”
尔时佛告观世音菩萨：“当愍此无尽意菩萨、及四众、天、龙、夜叉、乾闼婆、阿修罗、迦楼罗、紧那罗、摩侯罗伽、人非人、等故，受是璎珞。”即时观世音菩萨愍诸四众、及于天、龙、人非人、等，受其璎珞，分作二分，一分奉释迦牟尼佛，一分奉多宝佛塔。“无尽意，观世音菩萨有如是自在神力，游于娑婆世界。”
尔时无尽意菩萨以偈问曰：
世尊妙相具，我今重问彼，佛子何因缘，名为观世音。
具足妙相尊，偈答无尽意。汝听观音行，善应诸方所，
宏誓深如海，历劫不思议，侍多千亿佛，发大清净愿。
我为汝略说，闻名及见身，心念不空过，能灭诸有苦。
假使兴害意，推落大火坑，念彼观音力，火坑变成池。
或漂流巨海，龙鱼诸鬼难，念彼观音力，波浪不能没。
或在须弥峰、为人所推堕，念彼观音力，如日虚空住。
或被恶人逐，堕落金刚山，念彼观音力，不能损一毛。
或值怨贼绕，各执刀加害，念彼观音力，咸即起慈心。
或遭王难苦，临刑欲寿终，念彼观音力，刀寻段段坏。
或囚禁枷锁，手足被杻械，念彼观音力，释然得解脱。
咒诅诸毒药、所欲害身者，念彼观音力，还著于本人。
或遇恶罗刹、毒龙诸鬼等，念彼观音力，时悉不敢害。
若恶兽围绕，利牙爪可怖，念彼观音力，疾走无边方。
蚖蛇及蝮蝎，气毒烟火燃，念彼观音力，寻声自回去。
云雷鼓掣电，降雹澍大雨，念彼观音力，应时得消散。
众生被困厄，无量苦逼身，观音妙智力，能救世间苦。
具足神通力，广修智方便，十方诸国土，无刹不现身。
种种诸恶趣，地狱鬼畜生，生老病死苦，以渐悉令灭。
真观清净观，广大智慧观，悲观及慈观，常愿常瞻仰。
无垢清净光、慧日破诸闇，能伏灾风火，普明照世间。
悲体戒雷震，慈意妙大云，澍甘露法雨，灭除烦恼焰。
诤讼经官处，怖畏军阵中，念彼观音力，众怨悉退散。
妙音观世音、梵音海潮音，胜彼世间音，是故须常念，
念念勿生疑。观世音净圣，于苦恼死厄、能为作依怙。
具一切功德，慈眼视众生，福聚海无量，是故应顶礼。
尔时持地菩萨即从座起，前白佛言：“世尊，若有众生、闻是观世音菩萨品、自在之业，普门示现神通力者，当知是人功德不少。”佛说是普门品时，众中八万四千众生，皆发无等等阿耨多罗三藐三菩提心。', '妙法莲华经（Saddharmapundarika-sutra），简称《法华经》，在古印度、尼泊尔等地长期流行。在克什米尔、尼泊尔和中国新疆、西藏等地有40多种梵文版本，分为尼泊尔体系、克什米尔体系（基尔基特）和新疆体系。尼泊尔体系版本约为11世纪后作品，保持完整，已出版5种校订本。1983年北京民族文化宫图书馆用珂罗版彩色复制出版了由尼泊尔传入、珍藏于西藏萨迦寺的法华经。', '', '这时，无尽意菩萨从座位上站起来，裸露右肩，双手合十向释迦牟尼佛致礼，开口言道：世尊，观世音菩萨以什么因缘，而立名为观世音呢？释迦牟尼佛告诉无尽意菩萨说：善男子，如果有无量百千万亿那么多的众生，他们遭受到种种苦恼现在听说过观世音菩萨之后，只要一心称念他的名号，观世音菩萨就会立即观察到这音声，使那些身处苦恼的人都得到解脱。如果有人奉持称诵观世音菩萨的名号，那么即使他不幸陷入大火之中，大火也不能将其烧著，这是因为此菩萨有大威力大神力的缘故。假如有人不幸被大水卷走，只要他有称念观世音菩萨的名号，他就能很快到达浅处。假如有百千万亿那么多的众生，为了寻求金、银、琉璃、砗磲、玛瑙、珊瑚、琥珀，珍珠等宝物，乘船进入大海，即使正好碰上狂风，将其船只吹到罗刹鬼国，如果其中有人，甚至仅仅一人，称念观世音菩萨的名号，那么所遇难的人都能从鬼国中解脱出来。因为这种因缘，所以就称其为观世音菩萨。
假如有人，在他临能被害之际，只要能称念观世音菩萨的名号，那么，杀人者手里的刀杖，就会应声折坏为碎段，使受害者从危难中得到解脱。假如在三千大千世界的国土中，到处都是夜叉鬼和罗刹鬼，它们想伤害别人，然而只要一听到有人称念观世音菩萨的名号，这些恶鬼连睁开眼睛看看都不可能，何况加害于人呢？又假使有人，无论是有罪或是无罪，如果手脚被戴上镣铐，全身被枷锁缚绑，可他只要称念观世音菩萨的名号，那么所有刑具都会自动断坏，使其从束缚国得到解脱。假如在三千大千世界国土上，到处都有谋财害命的盗贼，有一位商主，率领许多商人，携带贵重珍宝，经过一段险峻的道路，其中一个商人建议大家说：善男子，大家不要惊恐，你们只要能一心一意地念诵观世音菩萨的名号，这位菩萨能将其无畏神力布施给大家，你们就能从怨贼的危害中获得解脱。众商人听完他的话后，都大声念道：南无观世音菩萨。因为诵念了观世音菩萨的名号的缘故，他们都立即众危难中解脱出来。
无尽意菩萨，这位菩萨众中的大菩萨观世音菩萨，他的威德神力就是如此，巍巍宏大。
假如有众生过度沉弱于淫欲，只要常常念诵并恭敬观世音菩萨，就会自然脱离淫欲。若有众生常常瞋怒，只要经常念诵并恭敬观世音菩萨，便能自然脱离瞋恨。若有人十分愚痴，只要经常念诵观世音菩萨，就会自然脱离愚痴。无尽意菩萨啊！观世音菩萨有如此种种大威德神力，能使一切众生得到益处，因此，众生常应在内心虔诚地念诵观世音菩萨的名号。如果有女人想求男孩，只要礼拜、供养观世音菩萨，就会生下一个既有福德又有智慧的男孩;假如她想求一个妇女孩，便会生下一个相貌端正的女孩，而且这个女孩在前世就种下了善根，因此众人都很喜爱并尊敬她。
无尽意菩萨，观世音菩萨有如此神奇的威力，假使众生，能恭敬、礼拜观世音菩萨，他的福报绝不会落空。因此，众生都应该受持、念诵观世音菩萨名号。无尽意菩萨，如果有人能信奉护持六十二亿恒河沙数那样多的菩萨名号，又能终生供养饮食、衣服、卧具、医药，在你看来，这样的善男子、善女子，他们的功德多不多呢？
无尽意菩萨回答说：当然非常多啊！世尊。
释迦牟尼佛说：假使另外有人受持念诵观世音菩萨名号，甚至作短时间的礼拜和供养，那么，他所获得的福报，与前面所说的善男子、善女子所获得的福报，完全相等而毫无差异，在百千万亿劫那么多的时间里，也不能穷尽他们的福服。无尽意菩萨啊！念诵观世音菩萨的名号，就能得到如此无量无边的福德利益。
无尽意菩萨对佛说：世尊，观世音菩萨怎样游历这个娑婆世界？怎样为众生说法？他教化众生的方便神力是怎样的呢？
释迦牟尼佛告诉无尽意菩萨说：善男子，在三千大千世界的国土中，若有众生应以佛身而获得救度，观世音菩萨即现佛身为其说法;应以辟支佛身获得救度的，即现辟支佛身为其说法;应以声闻身获得救度的，即现声闻身为其说法;应以梵王身获得救度的，即现梵王身为其说法;应以帝释身获得救度的，即现帝释身为其说法;应以自在天身获得救度的，即现自在天身为其说法;应以大自在天身获得救度的，即现大自在天身为其说法;应以天上大将军身获得救度的，即现天上大将军身为其说法;应以毗沙门身获得救度的，即现毗沙门身为其说法;应以小王身获得救度的，即现小王身为其说法;应以长者身获得救度的，即现长者身为其说法;应以居士身获得救度的，即现居士身为其说法;应以婆罗门身获得救度的，即现婆罗门身为其说法;应以比丘、比丘尼、男居士、女居士身获得救度的，即现比丘、比丘尼、男居士、女居士身为其说法;应以长者、居士、宰官、婆罗门的妇女身获得救度的，即现相应的妇女身为其说法;应以童男、童女身获得救度的，即现童男、童女身为其说法;应以天神、龙神、乾闼婆、阿修罗、迦楼罗、紧那罗、摩睺罗伽以及人和非人之身获得救度的，即现各之自身为其说法;应以金刚神身获得救度的，即现金刚神身为其说法。
无尽意，这位观世音成就了如此的功德，能够以各种身形游历各个国土，救度那里的众生，所以，你们应当一心一意地供养观世音菩萨。这位观世音菩萨能在众生遇到恐怖与危急、灾难之时，把无畏布施给众生，所以，这个娑婆世界都称观世音菩萨为施无畏者。
无尽意菩萨对释迦牟尼佛说：世尊，我现在就应当供养观世音菩萨。于是，无尽意解下脖子上的各种宝珠与璎珞，总计价值达百千两黄金，把它们供给观世音菩萨，说道：仁慈有德的菩萨啊，请接受这如法布施的珠宝与璎珞吧！这时，观世音菩萨不肯接受。无尽意菩萨又对观世音菩萨说：仁慈有德的菩萨啊，请您怜悯我们，收下这些璎珞吧！这时，释迦牟尼佛告诉观世音菩萨说：你应当怜悯这位无尽意菩萨以及四众弟子和天神、龙神、乾闼婆、阿修罗、迦楼罗、紧那罗、摩睺罗伽，还有人与非人等，因此你就接受这些璎珞吧！于是，观世音菩萨出于对四众弟子及天龙八部、人与非人等的怜悯，便立即收下了这些璎珞。他把这些璎珞分作两份，一份奉献给释迦牟尼佛，一份供奉多宝佛塔。
释迦牟尼佛对无尽意说：无尽意，观世音菩萨有如上所述的自在神力，所以他才能自由地游历于这个娑婆世界。
这时，无尽意菩萨以偈颂格式重问道：具足各种妙相的世尊啊，我现在再问一问那位观世音菩萨，这位佛子以什么因缘而名叫观世音呢。
具足各种妙相的世尊也以偈颂格式回答无尽意菩萨说：你听著，观世音菩萨的行持，善于应化于十方一切处所。他救度众生的宏誓就像大海一样深厚，即使经历许多劫数，也很难思议其程度。他奉持过千亿那么多的佛，并发下了清净的大愿。我现在为你略加讲述，如果听到观世音菩萨的名字，见到观世音菩萨的身相，心中不停地念诵菩萨的名号，那么就可以消灭三界中的各种苦难。假使有谁兴起害人之心，把某人推入大火坑中，通过念诵那个观音名号所获得的感应之力，就可使火坑变成清凉水池。或者有人漂流于大海之中，遇到毒龙、大鱼及各种鬼怪的灾难，通过念诵观音的名号获得的感应之力，即使再大的波浪也淹没不了他。或者当某人在须弥山峰上，被人推下山岩，通过念诵观音的名号获得的感应之力，就可使他像太阳住在虚空一样堕落不下。或者某人被坏人追逐，跌落到金刚山下，通过念诵那个观音菩萨名号获得的感应之力，就可使他不损一毛。或者有人遇到怨贼包围，各自持刀加害于他，通过念诵那个观音菩萨名号获得的感应之力，就可使所有的怨贼立即生出仁慈之心。或者有人遭受到国王相加的危难之苦，死亡即将临头时，通过虔诚念诵那位观音菩萨名号获得的感应之力，就可使行刑之刀接连断成几节。或者有人被枷锁囚禁起来，手与足均被镣铐束缚，通过念诵那位观音菩萨名号获得的感应之力，就可使他获释而得解脱。如果有人遇到诅咒或各种毒药加害其身，通过念诵那位观音菩萨名号获得的感应之力，就可使这些诅咒和毒药不能害他，还回到发出的人这里。
如果有人遇到凶恶的罗刹鬼以及毒龙和其他鬼怪等，通过念诵那位观音菩萨名号获得的感应之力，就可立即使它们全都不敢加害。如果某人被凶恶的野兽包围，这些野兽露出锐利的牙齿和爪子，十分可怖，通过念诵观音菩萨名号获得的感应之力，就可使这些野兽迅速跑到天边的远方。如果有人遇到蚖蛇、蝮蛇和蝎子，被如同燃烧著的烟火一样剧烈的毒气所威胁，通过念诵观音菩萨的名号获得的感应之力，就可使这些毒虫闻声布各自退回。如果遇到乌云密布，打雷闪电，降下冰雹或倾盆大雨，通过念诵那位观音菩萨名号获得的感应之力，就可使这种状况即时得到消散。
众生深陷于困苦危厄之中，无量无数的痛苦逼迫其身心。观音菩萨的妙智力能够救度世间的苦难。观音菩萨具足神通之力，广泛修习智慧与方便法门，在十方的所有国土之中，无处不现其身。各种恶道即地狱、饿鬼、畜生以及善道中的生、老、病、死等各种痛苦，观音菩萨都可逐渐使其全部消灭。观音菩萨具备看破外相的真空观、毫不执著的清净观、广大圆满的智慧观，还具备拔出一切苦的悲观和给予众生一切乐的慈观，所以，你们应当时常祝愿，时常瞻仰观音菩萨。观音菩萨远离一切尘垢，所以才会有微妙的清净之光。他的智慧像太阳一样把一切黑暗全都照破了，把一切风火之灾都降伏了，从而使其智慧之光遍照一切世间。观音菩萨收持戒而获得的大悲之法体如同天雷震动一样，观音菩萨的慈悲心怀好似天上的彩云一样微妙，从而降下了甘露般的法雨，灭除了众生心头的烦恼之焰。如果争斗诉讼到官府那里，或者在两军阵前的恐惧之中，通过念诵那位观音菩萨名号获得的感应之力，就可使一切怨恨全都退散。
观世音菩萨具有微妙的声音，就像其本身的名号之音一样。观世音的音声不但微妙，而且清净，犹如大海的潮音。观世音菩萨的声音胜过了世间所有的声音，所以，你们要经常念诵观世音，每念一下都不生出疑惑之心观世音菩萨这位清净的圣者，能在众生遇到痛苦烦恼之时，或面临死亡危险之时，作为众生的依靠。他具备了一切功德，以慈父的眼光看侍一切众生，所修的福德像众水聚成大海一样无边无量，所以，你们应该顶礼膜拜观音菩萨。
这时，持地菩萨从座上站起来，走向前来对释迦牟尼佛说：世尊，若有众生听到这篇《观世音菩萨品》，知道观音菩萨自在无碍的业行，了解观音菩萨广开无量法门，示现各种神通之力救度众生，那么，我们就应当知道，此人所获得的功德的确不少。
释迦牟尼佛讲说这篇《普门品》时，参加法会的大众中有八万四行众生都发下求证至高无上圣智的誓愿。', NULL, '', 'indent', 1526662633, '5ab52a819f54547d1c3e4446', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636665, '妙法莲华经 · 陀罗尼品第二十六', NULL, 0, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%A6%99%E6%B3%95%E8%8E%B2%E5%8D%8E%E7%BB%8F/1772696?fr=aladdin', '', '尔时药王菩萨、即从座起，偏袒右肩，合掌向佛、而白佛言：“世尊，若善男子、善女人，有能受持法华经者。若读诵通利，若书写经卷，得几所福？”佛告药王：“若有善男子、善女人，供养八百万亿那由他恒河沙等诸佛，于汝意云何，其所得福、宁为多否？”“甚多，世尊。”佛言：“若善男子、善女人，能于是经，乃至受持一四句偈，读诵、解义，如说修行，功德甚多。”尔时药王菩萨白佛言：“世尊，我今当与说法者陀罗尼咒、以守护之。”即说咒曰：
　　安尔 曼尔 摩祢 摩摩祢 旨隶 遮梨第 赊咩 赊履多玮 膻帝 目帝 目多履 娑履 阿玮娑履 桑履 娑履 叉裔 阿叉裔 阿耆腻 膻帝 赊履 陀罗尼 阿卢伽婆娑簸蔗毗叉腻 祢毗剃 阿便哆逻祢履剃 阿亶哆波隶输地 欧究隶 牟究隶 阿罗隶 波罗隶 首迦差 阿三磨三履 佛陀毗吉利袠帝 达磨波利差帝 僧伽涅瞿沙祢 婆舍婆舍输地 曼哆逻 曼哆逻叉夜多 邮楼哆 邮楼哆憍舍略 恶叉逻 恶叉冶多冶 阿婆卢 阿磨若那多夜
“世尊，是陀罗尼神咒，六十二亿恒河沙等诸佛所说，若有侵毁此法师者，则为侵毁是诸佛已。”
时释迦牟尼佛赞药王菩萨言：“善哉、善哉，药王，汝愍念拥护此法师故，说是陀罗尼，于诸众生、多所饶益。”
尔时勇施菩萨白佛言：“世尊，我亦为拥护读诵受持法华经者，说陀罗尼，若此法师得是陀罗尼，若夜叉、若罗刹、若富单那、若吉遮、若鸠盘荼、若饿鬼、等，伺求其短，无能得便。”即于佛前而说咒曰：
　　痤隶 摩诃痤隶 郁枳 目枳 阿隶 阿罗婆第 涅隶第 涅隶多婆第 伊致柅 韦致柅 旨致柅 涅隶墀柅 涅犁墀婆底
“世尊，是陀罗尼神咒，恒河沙等诸佛所说，亦皆随喜，若有侵毁此法师者，则为侵毁是诸佛已。”
尔时毗沙门天王护世者白佛言：“世尊，我亦为愍念众生、拥护此法师故，说是陀罗尼。”即说咒曰：
　　阿梨 那梨 [少/免]那梨 阿那卢 那履 拘那覆
“世尊，以是神咒、拥护法师，我亦自当拥护持是经者，令百由旬内、无诸衰患。”
尔时持国天王、在此会中，与千万亿那由他乾闼婆众，恭敬围绕，前诣佛所，合掌白佛言：“世尊，我亦以陀罗尼神咒、拥护持法华经者。”即说咒曰：
　　阿伽祢 伽祢 瞿利 乾陀利 旃陀利 摩蹬耆 常求利 浮楼莎柅 頞底
“世尊，是陀罗尼神咒，四十二亿诸佛所说，若有侵毁此法师者，则为侵毁是诸佛已。”
尔时有罗刹女等，一名蓝婆，二名毗蓝婆，三名曲齿，四名华齿，五名黑齿，六名多发，七名无厌足，八名持璎珞，九名睾帝，十名夺一切众生一精一气，是十罗刹女，与鬼子母、并其子、及眷属，俱诣佛所，同声白佛言：“世尊，我等亦欲拥护读诵受持法华经者，除其衰患，若有伺求法师短者，令不得便。”即于佛前，而说咒曰：
　　伊提履 伊提泯 伊提履 阿提履 伊提履 泥履 泥履 泥履 泥履 泥履 楼醯 楼醯 楼醯 楼醯 多醯 多醯 多醯 兜醯 [少/免]醯
“宁上我头上，莫恼于法师。若夜叉、若罗刹、若饿鬼、若富单那、若吉遮、若毗陀罗、若犍驮、若乌摩勒伽、若阿跋摩罗、若夜叉吉遮、若人吉遮、若热病、若一日、若二日、若三日、若四日、乃至七日、若常热病，若男形、若女形、若童男形、若童女形，乃至梦中，亦复莫恼。”即于佛前、而说偈言：
　　若不顺我咒， 恼乱说法者， 头破作七分， 如阿梨树枝。
　　如杀父母罪， 亦如压油殃， 斗秤欺诳人， 调达破僧罪。
　　犯此法师者， 当获如是殃。
诸罗刹女说此偈已，白佛言：“世尊，我等亦当身自拥护受持、读诵、修行、是经者，令得安隐，离诸衰患，消众毒药。”佛告诸罗刹女：“善哉、善哉，汝等但能拥护受持法华名者，福不可量，何况拥护具足受持，供养经卷，华、香、璎珞，末香、涂香、烧香，幡盖、伎乐，燃种种灯，酥灯、油灯、诸香油灯、苏摩那华油灯、瞻卜华油灯、婆师迦华油灯、优钵罗华油灯，如是等百千种供养者。睾帝，汝等及眷属，应当拥护如是法师。”说是陀罗尼品时，六万八千人、得无生法忍。', '妙法莲华经（Saddharmapundarika-sutra），简称《法华经》，在古印度、尼泊尔等地长期流行。在克什米尔、尼泊尔和中国新疆、西藏等地有40多种梵文版本，分为尼泊尔体系、克什米尔体系（基尔基特）和新疆体系。尼泊尔体系版本约为11世纪后作品，保持完整，已出版5种校订本。1983年北京民族文化宫图书馆用珂罗版彩色复制出版了由尼泊尔传入、珍藏于西藏萨迦寺的法华经。', '', '这时，药王菩萨从座位上站起来，他身披袒露右肩的袈裟，双手合十，向释迦牟尼佛致礼，开口言道：世尊，如果有善男子、善女子能够信受这部《法华经》，或者非常流利地阅读背诵或者抄写经卷，那么，他们能得到多少福呢？
释迦牟尼佛告诉药王菩萨说：如果有善男子、善女子供养与八百万亿兆恒河的所有沙数那么多的如来世尊，在你看来，他获得的福报多不多呢？药王菩萨回答说：非常多，世尊。释迦牟尼佛说：如果有善男子、善女子能在此经中甚至只受持一首四句偈颂，对其读诵、解释，并按其所说义理修行，那么，此人的功德也同样是很多的。
这时，药王菩萨对释迦牟尼佛说：世尊，我现在应当给讲说《法华经》的法师说陀罗尼神咒，以守护他们。于是，药王菩萨便说出了如下神咒：
安尔。曼尔。摩祢。摩摩祢。旨隶。遮黎第。赊·。赊履多玮。·帝。目帝。目多履。娑履。阿玮娑履。桑履。娑履。叉裔。阿叉裔。阿耆腻。·帝。赊履。陀罗尼。阿庐伽婆娑簸蔗毗叉腻。祢毗剃。阿便哆逻祢履剃。阿·哆波隶输地。欧究隶。牟究隶。阿罗隶。波罗隶。首迦差。阿三磨三履。佛陀毗吉利·帝。达磨波利差帝。僧伽涅瞿沙祢。婆舍婆舍输地。曼哆逻。曼哆逻叉夜多，邮楼哆。邮楼哆·舍略。恶叉逻。恶叉治多治。阿婆庐。阿摩若那多夜。
说完以上咒语，药王菩萨又对释迦牟尼佛说：世尊，这个陀罗尼神咒乃是过去六十二亿恒河沙数那么多的如来世尊所说出来的，如果有谁侵扰诋毁这位说《法华经》的法师，那他就是侵扰诋毁这些如来世尊。这时，对释迦牟尼佛称赞药王菩萨说：善哉！善哉！药王，你怜悯、关怀、拥护讲说《法华经》的法师，所以才说出这个陀罗尼神咒，这对于所有的众生，都是大有裨益的。
这时，一位名叫勇施的菩萨对释迦牟尼佛说：世尊，我也为拥护、读诵、受持《法华经》的法师们说一个陀罗尼神咒。如果这些法师得到了这个陀罗尼神咒，那么，即使遇到或者夜叉鬼，或者罗刹鬼，或者富单那鬼，或者吉蔗鬼，或者鸠盘荼鬼，或者饿鬼，不论这些恶鬼如何寻找他们的短处，他们也不会为恶鬼留下可乘之机。于是，勇施菩萨便在释迦牟尼佛面前说出如下咒语：
痤隶。摩诃痤隶。郁枳。目枳。阿隶。阿罗婆第。涅隶第。涅隶多婆第。伊致·。韦致·。旨致·。涅隶墀·。涅·墀婆底。
说完如上咒语，勇施的菩萨又对释迦牟尼佛说：世尊，这个陀罗尼神咒是与恒河沙数一样多的如来世尊所说的，而且，这些如来世尊都随顺此咒，心生欢喜。如果有谁侵扰诋毁这些讲说《法华经》的法师，那么，谁就是侵扰诋毁这恒河沙数一样多的如来世尊。
这时，四大天王中守护北方世界毗沙门天王对释迦牟尼佛说：世尊，我也有怜悯、关怀众生，拥护讲说《法华经》的法师，而说一个陀罗尼神咒。于是，这位天王便说出如下咒语：
　阿梨。阿梨。·那梨。阿那庐。那履。拘那履。
说完如上咒语，毗沙门天王又对释迦牟尼佛说：世尊，除了用这种神咒拥护讲说《法华经》的法师外，我本身也应当拥护受持这部经典的所有众生，使他们在一百由旬之内，没有任何衰退与祸患。
那时，四大天王中的持国天王，也在法华会上，他与恭敬围绕在他身边的千万亿兆乾闼婆神走到释迦牟尼佛的面前，双手合掌，对佛说道：世尊，我也以陀罗尼神咒来拥护受持《法华经》的法师。于是，持国天王说出如下咒语：
阿伽祢。伽祢。瞿利。干陀利。·陀利。摩蹬耆。常求利。浮楼莎·。·底。
说完如上咒语，持国天王又对释迦牟尼佛说：这个陀罗尼神咒，是从前四十二亿位如来世尊所说的。如果有谁侵扰诋毁这些受持《法华经》的法师，那他就等于是侵扰诋毁这四十二亿如来世尊。
这时，法华会中有十位罗刹女，第一位名叫蓝婆，第二位名叫毗蓝婆，第三位名叫曲齿，第四位名叫华齿，第一五名叫黑齿，第六位名叫多发，第七位名叫无厌足，第八位名叫持璎珞，第九位名叫皋帝，第十位名叫夺一切众生精气。这十位罗刹女与鬼母及其儿子与眷属一同来到佛的面前，同声对佛说道：世尊，我们也想拥护那些读诵、受持《法华经》的法师，以消除他们的衰退与祸患。如果有谁寻找法师的短处，使他们不能得逞。于是这位罗刹女等便在释迦牟尼佛前说出如下咒语：
伊提履。伊提泯。伊提履。阿提履。伊提履。泥履。泥履。泥履。泥履。泥履。楼酰。楼酰。楼酰。楼酰。多酰。多酰。多酰。兜酰。·酰。
说完如上咒语，罗刹女等又继续说：我们宁愿诸鬼在我们头上为所欲为，也不让他们去扰乱受持《法华经》的法师。这些恶鬼，如夜叉鬼、罗刹鬼、饿鬼、富单那鬼、吉蔗鬼、毗陀罗鬼、犍驮鬼、乌摩勒伽鬼、阿跋摩罗鬼、夜叉吉蔗鬼、热病鬼。假使在一日、二日、三日，四日甚至七日之中，常有热病鬼出没，不论其以男形还是女形，不论其以童男形还是童女形，甚至在梦中，都不能扰乱这些受持《法华经》的法师。
罗刹女等又在释迦牟尼佛前说偈语道：如果谁不顺从我的咒语，扰乱讲说《法华经》的法师，那么，谁的头就会被破成七份，就像阿梨树枝一样坠落于地上，破碎为七片。如同杀父母的大罪，也如同压油压死其他生命的灾殃，以大斗小秤来欺骗他人所获致的恶报，也好像提婆达多破坏僧团的罪业，凡是侵犯这位讲说《法华经》的法师的众生，就会获致如上这些灾殃。
罗刹女们说完这些偈语之后，对释迦牟尼佛说：世尊，我们也应当亲自拥护那些受持、读诵《法华经》并依《法华经》而修行的法师，使他们身心得到安稳，远离各种衰退与祸患，消除各种害人的毒药。
释迦牟尼佛告诉罗刹女们说：善哉！善哉！你们即使仅仅拥护那些受持《法华经》的名字的人，所获得的福报已不可限量，何况拥护那些受持整个《法华经》并供养经卷的人。这些供养经卷的人，或者以鲜花、香料、璎珞供养，或者以未香、涂香、烧香供养，或者以宝幡、宝盖、歌舞供养，或者点燃各种油灯供养，如酥油灯、香油灯、酥摩那花油灯、瞻卜花油灯、婆师迦花油灯、优钵罗花油灯。诸如此类通过成百上千种方式来供养《法华经》的法师，皋帝，你们这些鬼众与眷属应当拥护这些法师。
释迦牟尼佛说这篇《陀罗尼品》时，法会中有六万八千人获得了安住不生不灭实相理体的无生法忍。', NULL, '', 'indent', 1526662650, '5ab52b359f545437fe924ae7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636666, '妙法莲华经 · 妙庄严王本事品第二十七', NULL, 0, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%A6%99%E6%B3%95%E8%8E%B2%E5%8D%8E%E7%BB%8F/1772696?fr=aladdin', '', '尔时佛告诸大众：“乃往古世、过无量无边不可思议阿僧祇劫，有佛、名云雷音宿王华智、多陀阿伽度、阿罗诃、三藐三佛陀，国名光明庄严，劫名喜见。”
“彼佛法中有王，名妙庄严，其王夫人、名曰净德，有二子，一名净藏，二名净眼。是二子、有大神力，福德智慧，久修菩萨所行之道，所谓檀波罗蜜、尸罗波罗蜜、羼提波罗蜜、毗梨耶波罗蜜、禅波罗蜜、般若波罗蜜、方便波罗蜜，慈悲喜舍，乃至三十七品助道法、皆悉明了通达。又得菩萨净三昧、日星宿三昧、净光三昧、净色三昧、净照明三昧、长庄严三昧、大威德藏三昧，于此三昧、亦悉通达。”
“尔时彼佛欲引导妙庄严王、及愍念众生故，说是法华经。时净藏净眼二子、到其母所，合十指爪掌、白言：‘愿母往诣云雷音宿王华智佛所，我等亦当侍从、亲近供养礼拜。所以者何。此佛于一切天人众中、说法华经，宜应听受。’母告子言：‘汝父信受外道，深著婆罗门法，汝等应往白父，与共俱去。’净藏、净眼、合十指爪掌白母：‘我等是法王子，而生此邪见家。’母告子言：‘汝等当忧念汝父，为现神变，若得见者，心必清净，或听我等，往至佛所。’”
“于是二子念其父故，涌在虚空，高七多罗树，现种种神变，于虚空中、行住坐卧，身上出水、身下出火，身下出水、身上出火，或现大身满虚空中，而复现小，小复现大，于空中灭，忽然在地，入地如水，履水如地，现如是等种种神变，令其父王心净信解。时父见子神力如是，心大欢喜，得未曾有，合掌向子言：‘汝等、师为是谁，谁之弟子？’二子白言：‘大王，彼云雷音宿王华智佛，今在七宝菩提树下、法座上坐，于一切世间天人众中、广说法华经，是我等师，我是弟子。’父语子言：‘我今亦欲见汝等师，可共俱往。’于是二子从空中下，到其母所，合掌白母：‘父王今已信解，堪任发阿耨多罗三藐三菩提心。我等为父、已作佛事，愿母见听，于彼佛所、出家修道。’”
尔时二子欲重宣其意，以偈白母：
　　愿母放我等、 出家作沙门， 诸佛甚难值， 我等随佛学。
　　如优昙钵华， 值佛复难是， 脱诸难亦难， 愿听我出家。

　　“母即告言：‘听汝出家。所以者何。佛难值故。’于是二子白父母言：‘善哉、父母，愿时往诣云雷音宿王华智佛所、亲近供养，所以者何。佛难得值，如优昙钵罗华，又如一眼之龟，值浮木孔。而我等宿福深厚，生值佛法，是故父母当听我等，令得出家。所以者何。诸佛难值，时亦难遇。’”
“彼时妙庄严王后宫八万四千人，皆悉堪任受持是法华经。净眼菩萨、于法华三昧、久已通达，净藏菩萨、已于无量百千万亿劫、通达离诸恶趣三昧，欲令一切众生离诸恶趣故。其王夫人、得诸佛集三昧，能知诸佛秘密之藏。二子如是以方便力、善化其父，令心信解，好乐佛法。于是妙庄严王、与群臣眷属俱，净德夫人、与后宫婇女眷属俱，其王二子、与四万二千人俱，一时共诣佛所，到已，头面礼足，绕佛三匝，却住一面。”
“尔时彼佛为王说法，示教利喜。王大欢悦。尔时妙庄严王、及其夫人、解颈真珠璎珞、价值百千，以散佛上，于虚空中、化成四柱宝台，台中有大宝床，敷百千万天衣，其上有佛、结跏趺坐，放大光明。尔时妙庄严王作是念：‘佛身稀有、端严殊特，成就第一微妙之色。’时云雷音宿王华智佛告四众言：‘汝等见是妙庄严王、于我前合掌立否。此王、于我法中、作比丘、一精一勤修习，助佛道法，当得作佛，号娑罗树王，国名大光，劫名大高王。其娑罗树王佛，有无量菩萨众、及无量声闻，其国平正，功德如是。’其王即时以国付弟，与夫人、二子、并诸眷属，于佛法中、出家修道。王出家已，于八万四千岁，常勤一精一进、修行妙法华经，过是已后，得一切净功德庄严三昧。即升虚空，高七多罗树，而白佛言：‘世尊，此我二子、已作佛事，以神通变化、转我邪心，令得安住于佛法中，得见世尊。此二子者，是我善知识，为欲发起宿世善根，饶益我故，来生我家。’”
“尔时云雷音宿王华智佛告妙庄严王言：‘如是、如是，如汝所言，若善男子、善女人，种善根故，世世得善知识，其善知识、能作佛事，示教利喜，令入阿耨多罗三藐三菩提，大王，当知善知识者、是大因缘，所谓化导令得见佛，发阿耨多罗三藐三菩提心。大王，汝见此二子否。此二子、已曾供养六十五百千万亿那由他恒河沙诸佛，亲近恭敬，于诸佛所、受持法华经，愍念邪见众生，令住正见。’妙庄严王即从虚空中下，而白佛言：‘世尊，如来甚稀有，以功德智慧故，顶上肉髻、光明显照，其眼长广、而绀青色，眉间毫相、白如珂月，齿白齐密，常有光明，唇色赤好、如频婆果。’尔时妙庄严王、赞叹佛如是等无量百千万亿功德已，于如来前，一心合掌，复白佛言：‘世尊，未曾有也，如来之法，具足成就不可思议微妙功德，教诫所行，安隐快善，我从今日，不复自随心行，不生邪见、憍慢嗔恚诸恶之心。’说是语已，礼佛而出。”
佛告大众：“于意云何，妙庄严王、岂异人乎，今华德菩萨是。其净德夫人，今佛前光照庄严相菩萨是，哀愍妙庄严王及诸眷属故，于彼中生。其二子者，今药王菩萨、药上菩萨是，是药王药上菩萨、成就如此诸大功德，已于无量百千万亿诸佛所、植众德本，成就不可思议诸善功德，若有人、识是二菩萨名字者，一切世间诸天人民、亦应礼拜。”佛说是妙庄严王本事品时，八万四千人、远尘离垢，于诸法中、得法眼净。', '妙法莲华经（Saddharmapundarika-sutra），简称《法华经》，在古印度、尼泊尔等地长期流行。在克什米尔、尼泊尔和中国新疆、西藏等地有40多种梵文版本，分为尼泊尔体系、克什米尔体系（基尔基特）和新疆体系。尼泊尔体系版本约为11世纪后作品，保持完整，已出版5种校订本。1983年北京民族文化宫图书馆用珂罗版彩色复制出版了由尼泊尔传入、珍藏于西藏萨迦寺的法华经。', '', '这时，释迦牟尼佛告诉法华会上的大众说：远古之世，从现在向过去追溯无量无边不可思议阿僧祇那么多的劫数，那时，有一位佛名叫云雷音宿王华智，同时具足如来、应供、正遍知等各种称号。佛所在的国土，名叫光明庄严，所处的时劫，名叫喜见。在这位如来世尊的法化范围之中，有一位国王，名叫妙庄严，国王的夫人名叫净德。妙庄严王人两个儿子，一个名叫净藏，一个名叫净眼。这两位儿子皆有很大的神通之力，福德与智慧同时兼备。他们很久以来就修大乘菩萨所行的道法，即谓布施波罗蜜、持戒波罗蜜、忍辱波罗蜜、精进波罗蜜、禅定波罗蜜、般若波罗蜜、方便波罗蜜，还有大慈、大悲、大喜、大舍直至三十七品助道法，他们全都明了而通达。净藏和净眼二位王子还证得了大乘菩萨的各种清净妙定，如：日星宿妙定、净光妙定、净色妙定、净照明妙定、长庄严妙定、大威德藏妙定。对于这些妙定，二王子也都能通达无碍。
当时，那位云雷音宿王华智佛欲引导妙庄严王并出于对一切众生怜湣关怀的缘故，所以便开讲这部《法华经》。这时，净藏、净眼二两位王子来到母亲的住所，双手合十，对母亲说：愿母后前去云雷音宿王华智佛那里，我们也应当随您一同前去，以便侍从、亲近、供养这位如来世尊。为什么呢？因为此佛在所有天神与人类大众中讲说《法华经》，所以我们应该前去聆听受教。母亲告诉儿子说：你们的父亲信受外道，深深地执著于婆罗门教法。你们应该前去告诉父亲，让他与我们一同去。 净藏、净眼双手合十，对母亲说：我们是法王如来的弟子，竟生在这个执持邪见的家庭。母亲净德后告诉两位儿子说：你们当为父亲感到担忧，为父亲多想想。若能为父亲示现各种神通变化，他看见以后，内心会清净，那时，他或许会听我们的劝告，与我们一同到佛的住所听闻佛法。
于是，两位王子出于对父亲的关怀忆念，便以神通力，涌向空中，距地面有七颗多罗树那么高。二人在空中示现出各种神变景象，他们在空中行走、站立、打坐、睡卧。一会儿身上出水，身下出火;一会儿身下出水， 身上出火。有时又示现巨大的身躯，以至遍满整个虚空;忽而他们又示现小身，又由小身变为大身。甚至又在虚空中消失，忽然间，却处在地上。能像入水一样地中，又能像走平地一样行走在水面。他们示现这些神变，以使父王心地清净，能生信解佛法之心。
这时，父亲看见儿子有这般神通之力，心中十分欢喜，深感此乃从未有过的奇事。于是妙庄严王双手合掌对儿子说：你们的师父是谁？你们是谁的弟子？两位儿子回答说：大王，那位云雷音宿王华智佛现在正在七宝树下的法座上坐著，在一切世间的天神与人类大众中广泛演说《法华经》。此佛是我们的师父，我们是他的弟子。父亲对儿子说：我现在也想拜见你们的师父，我们可以一同前往。
　于是，两位王子从空中下来，来到他们母亲的住所，双手合掌，对母亲说：父王现已信解佛法，可以在此基础上发下求证至高无上之圣智的誓愿。我们已为父亲作了佛事，愿母亲允许我们在那位如来世尊的住所出家修道。
这时，两位王子欲重申其意，便以偈颂格式向母亲复述道：愿母亲放我们出家作沙门。诸佛很难遇到，现在有佛出世，我们要去随佛学习。就好三千年才开一次的优昙钵罗花，很难遇到，要遇到佛也是这样的难啊！救世的佛陀难遇，要脱离各种苦难也就很难很难。所以，愿母亲允许我们出家。
母亲便告诉儿子说：我同意你们出家，为什么呢？困为佛陀千载难逢啊。于是两位儿子对父母双亲说：善哉！愿我们即时前去云雷音宿王华智佛的住所，亲近，供养这位如来世尊。为什么呢？因为佛很难遇，就像优昙钵罗花历久才得一现一样，又像独眼之龟在大海上要找一个浮末的小孔一样。可由于我们先世已种下了深厚的善根，有了这样好的福报，今生得以出家。为什么呢？因为诸佛难遇，时机也是千载难逢。
那时，妙庄严王后宫的八万四千宫女都已能够受持这部《法华经》。净眼菩萨很久以来就已通达了法华三昧，净藏菩萨已在无量百千万亿劫那么长的岁月中，为了使一切众生远离各种恶道，通达了离诸恶道和妙定。国王夫人净德也获得了名叫诸佛集的妙定，能够知晓诸佛的秘密法藏。两位王子就这样，以方便法门的力量，谆谆善诱，化导了他们的父亲，使其产生了相信并了解佛法的心意，从而喜爱上了佛法。
于是，妙庄严王与群臣及其眷属一起，净德夫人与后宫嫔妃及其眷属一起，两位王子与四万二千人一起，大家一时间都动身前往佛的住所。到达佛的住所以后，他们向佛行头面礼足的顶礼，绕佛三周，退而站在一旁。这时，那位云雷音宿王华智佛向国王说法，开示教法，赐以利乐。国王听后，十分高兴。妙庄严王及其夫人便解下脖子上的珍珠、璎珞，把这些价值百千黄金的珍宝散在佛的身上。这些珍珠、璎珞在虚空中化成有四根柱子的宝台，台中有一宽大的宝床，宝床上敷盖著百千万种天衣，天衣上有一位如来世尊，正在双膝打坐，身放出耀眼的光明。这时，妙庄严王心想，佛身真是稀有难得，端庄威严，奇特无比，成就了最为微妙的色身宝相。
这时，云雷音宿王华智佛对四众弟子说：你们看见这位妙庄严王在我面前合掌站著吗？此国王将在我的佛法中作比丘，他精勤修习，助佛弘道，日后必将成佛，佛号为娑罗树王，国名叫光大，劫名叫大高王。这位娑罗树王佛拥有无数菩萨大众和无数声闻弟子。他的佛国平坦方正。他的功德就是如此的巨大。这位妙庄严王便立即把国家交付给弟弟治理，自己与 母亲便告诉儿子说：我同意你们出家，为什么呢？困为佛陀千载难逢啊。于是两位儿子对父母双亲说：善哉！愿我们即时前去云雷音宿王华智佛的住所，亲近，供养这位如来世尊。为什么呢？因为佛很难遇，就像优昙钵罗花历久才得一现一样，又像独眼之龟在大海上要找一个浮末的小孔一样。可由于我们先世已种下了深厚的善根，有了这样好的福报，今生得以出家。为什么呢？因为诸佛难遇，时机也是千载难逢。
那时，妙庄严王后宫的八万四千宫女都已能够受持这部《法华经》。净眼菩萨很久以来就已通达了法华三昧，净藏菩萨已在无量百千万亿劫那么长的岁月中，为了使一切众生远离各种恶道，通达了离诸恶道和妙定。国王夫人净德也获得了名叫诸佛集的妙定，能够知晓诸佛的秘密法藏。两位王子就这样，以方便法门的力量，谆谆善诱，化导了他们的父亲，使其产生了相信并了解佛法的心意，从而喜爱上了佛法。
这时，云雷音宿王华智佛对四众弟子说：你们看见这位妙庄严王在我面前合掌站著吗？此国王将在我的佛法中作比丘，他精勤修习，助佛弘道，日后必将成佛，佛号为娑罗树王，国名叫光大，劫名叫大高王。这位娑罗树王佛拥有无数菩萨大众和无数声闻弟子。他的佛国平坦方正。他的功德就是如此的巨大。这位妙庄严王便立即把国家交付给弟弟治理，自己与夫人、两位王子和所有眷属们，在佛法中出家修道。
国王出家以后，在长达八万四千年之中，勤奋不息，精进不怠，依《妙法莲华经》从事修行。经过如此长时间的修行之后，妙庄严获得了名叫一切净功德庄严三昧的妙定神力。于是，妙庄严王升上虚空中，距地面高达七棵多罗树。他在空中对云雷音宿王华智佛说：世尊，我的两个儿子在过去已经大作佛事，从而获得了许多神通妙用。他们以神通变化的方式转变了我的邪心，使我得以安住于佛法之中，得以见到世尊。这两位儿子是我的良师，他们为发起我前世种下的善根，为使我从佛法中蒙益受惠，故而前来投生于我家。
这时，云雷音宿王华智佛对妙庄严王说：是这样！是这样！正像你所说的，如果善男子、善女人能够种下善根，那么，他们每一世都可以得到良师的指点。他所遇到的良师能大作佛事，指示众生，教化众生，使众生获得利乐，并最终证入至高无上的圣智。大王，你应当知道，良师益友是一个非常重要的因缘，他能教化指导众生使其得以见到佛陀，并发了求证至高无上之圣智的心愿。大王，你看见你的这两位儿子吗？这两个儿子在过去曾供养过六十五百千万亿兆恒河沙那么多的如来世尊，对这些佛表示了亲近和恭敬。在这些佛那里，他们受持《法华经》，怜悯关怀持邪见的众生，使这些众生转而安住于正见的佛法中。
妙庄严王便从虚空中下来，对云雷音宿王华智佛说：世尊，如来真是稀有难得，因为有功德，有智慧的缘故，头顶上的肉髻大放光明，照亮了一切。如来的双眼既宽又长，呈绀青之色。如来的两眉之间有非凡的白毫光相，白如珂月一样的清洁。如来的牙齿，洁白，整齐，密实，时常发放光明。如来的唇色像频果一样鲜红而润泽。妙庄严王对佛的这些无量百千万亿种功德大加赞叹之后，在云雷音宿王华智佛面前，一心合掌，又向佛说：世尊，真是亘古未有啊！如来的教法非常圆满，可以成就不可思议的微妙功德，教戒众生，诸恶莫作，众善奉行，令众生得到安稳和快乐。我从今日起，不再随心所欲，妄自行事，再不生邪见之心，不生骄慢之心，不生瞋恨等各种恶劣之心。说完这些话后，妙庄严王向佛再次行礼，然后退了出去。
释迦牟尼佛对法华会上的大众说：在你们看来，妙庄严王难道是旁人吗？他就是现在的华德菩萨。那位净德夫人就是现在站在佛座前的名叫光照庄严相的菩萨。她当年因为哀怜妙庄严王及其所有眷属，所以在这个家中投生。国王的两个儿子，就是现在的药王菩萨和药上菩萨。药王菩萨和药上菩萨成就了如此巨大的功德，他们已于过去在无量百千万亿个如来世尊那里种下了各种功德和根子，从而成就了今日不可思议的各种善功与福德。如果有人能识得这两位菩萨的名字，那么一切世间内的所有天神、人民也便应该礼拜这两位菩萨。
释迦牟尼佛说完这篇《妙庄严王本事品》时，有八万四千人远离了尘垢，在各种佛法中获得了观察并通晓世间一切现象的法眼清净境界。', NULL, '', 'indent', 1526662668, '5ab52bdbee920a396f252d2d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636667, '妙法莲华经 · 普贤菩萨劝发品第二十八', NULL, 0, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%A6%99%E6%B3%95%E8%8E%B2%E5%8D%8E%E7%BB%8F/1772696?fr=aladdin', '', '尔时普贤菩萨、以自在神通力，威德名闻，与大菩萨无量无边不可称数、从东方来，所经诸国，普皆震动，雨宝莲华，作无量百千万亿种种伎乐。又与无数诸天、龙、夜叉、乾闼婆、阿修罗、迦楼罗、紧那罗、摩侯罗伽、人非人、等，大众围绕，各现威德神通之力。到娑婆世界、耆阇崛山中，头面礼释迦牟尼佛，右绕七匝，白佛言：“世尊，我于宝威德上王佛国，遥闻此娑婆世界、说法华经，与无量无边百千万亿诸菩萨众、共来听受，惟愿世尊当为说之，若善男子、善女人，于如来灭后，云何能得是法华经？”
佛告普贤菩萨：“若善男子、善女人，成就四法，于如来灭后，当得是法华经，一者、为诸佛护念，二者、植众德本，三者、入正定聚，四者、发救一切众生之心，善男子、善女人，如是成就四法，于如来灭后，必得是经。”
尔时普贤菩萨白佛言：“世尊，于后五百岁、浊恶世中，其有受持是经典者，我当守护，除其衰患，令得安隐，使无伺求、得其便者，若魔、若魔子、若魔女、若魔民、若为魔所著者、若夜叉、若罗刹、若鸠盘荼、若毗舍阇、若吉遮、若富单那、若韦陀罗、等，诸恼人者，皆不得便。是人若行、若立、读诵此经，我尔时乘六牙白象王，与大菩萨众、俱诣其所，而自现身，供养守护，安慰其心，亦为供养法华经故。是人若坐、思惟此经，尔时我复乘白象王、现其人前，其人若于法华经、有所忘失一句一偈，我当教之，与共读诵，还令通利。尔时受持读诵法华经者、得见我身，甚大欢喜，转复一精一进，以见我故，即得三昧、及陀罗尼，名为旋陀罗尼、百千万亿旋陀罗尼、法音方便陀罗尼，得如是等陀罗尼。”
“世尊，若后世后五百岁、浊恶世中，比丘、比丘尼、优婆塞、优婆夷，求索者，受持者，读诵者，书写者，欲修习是法华经，于三七日中、应一心一精一进，满三七日已，我当乘六牙白象，与无量菩萨而自围绕，以一切众生所喜见身、现其人前、而为说法，示教利喜，亦复与其陀罗尼咒，得是陀罗尼故，无有非人、能破坏者，亦不为女人之所惑乱，我身亦自常护是人，惟愿世尊听我说此陀罗尼咒。”
即于佛前而说咒曰：
　　阿檀地 檀陀婆地 檀陀婆帝 檀陀鸠舍隶 檀陀修陀隶 修陀隶 修陀罗婆底佛驮波膻祢 萨婆陀罗尼阿婆多尼 萨婆婆沙阿婆多尼 修阿婆多尼 僧伽婆履叉尼 僧伽涅伽陀尼 阿僧祇 僧伽波伽地 帝隶阿惰僧伽兜略 阿罗帝婆罗帝 萨婆僧伽三摩地伽兰地 萨婆达磨修波利刹帝 萨婆萨埵楼驮憍舍略阿[少/免]伽地 辛阿毗吉利地帝
“世尊，若有菩萨得闻是陀罗尼者，当知普贤神通之力，若法华经、行阎浮提，有受持者，应作此念：‘皆是普贤威神之力。’若有受持、读诵，正忆念，解其义趣，如说修行，当知是人、行普贤行，于无量无边诸佛所、深种善根，为诸如来、手摩其头。若但书写，是人命终，当生忉利天上，是时八万四千天女、作众伎乐而来迎之，其人即著七宝冠，于婇女中、娱乐快乐，何况受持、读诵，正忆念，解其义趣，如说修行。若有人受持，读诵，解其义趣，是人命终，为千佛授手，令不恐怖、不堕恶趣，即往兜率天上、弥勒菩萨所，弥勒菩萨、有三十二相大菩萨众所共围绕，有百千万亿天女眷属，而于中生，有如是等功德利益。是故智者，应当一心自书，若使人书，受持、读诵，正忆念，如说修行。”
“世尊，我今以神通力故、守护是经，于如来灭后、阎浮提内，广令流布，使不断绝。”
尔时释迦牟尼佛赞言：“善哉、善哉，普贤，汝能护助是经，令多所众生、安乐利益，汝已成就不可思议功德、深大慈悲，从久远来，发阿耨多罗三藐三菩提意，而能作是神通之愿，守护是经，我当以神通力，守护能受持普贤菩萨名者。”
“普贤，若有受持、读诵，正忆念，修习书写是法华经者，当知是人、则见释迦牟尼佛，如从佛口、闻此经典，当知是人、供养释迦牟尼佛，当知是人、佛赞善哉，当知是人、为释迦牟尼佛手摩其头，当知是人、为释迦牟尼佛衣之所覆，如是之人，不复贪著世乐，不好外道经书、手笔，亦复不喜亲近其人、及诸恶者，若屠儿、若畜猪羊鸡狗、若猎师、若炫卖女色，是人心意质直，有正忆念，有福德力，是人不为三毒所恼，亦复不为嫉妒、我慢、邪慢、增上慢、所恼，是人少欲知足，能修普贤之行。”
“普贤，若如来灭后、后五百岁，若有人、见受持读诵法华经者，应作是念：‘此人、不久当诣道场，破诸魔众，得阿耨多罗三藐三菩提，转法錀，击法鼓，吹法螺，雨法雨，当坐天人大众中、师子法座上。’”
“普贤，若于后世、受持读诵是经典者，是人不复贪着衣服、卧具、饮食、资生之物，所愿不虚，亦于现世得其福报，若有人轻毁之，言、汝狂人耳，空作是行，终无所获，如是罪报，当世世无眼，若有供养赞叹之者，当于今世得现果报。若复见受持是经者，出其过恶，若实、若不实，此人现世得白癞病，若有轻笑之者，当世世牙齿疏缺，丑唇、平鼻，手脚缭戾，眼目角睐，身体臭秽，恶疮、脓血、水腹、短气、诸恶重病，是故普贤，若见受持是经典者，当起远迎，当如敬佛。”
说是普贤劝发品时、恒河沙等无量无边菩萨、得百千万亿旋陀罗尼，三千大千世界微尘等诸菩萨、具普贤道。佛说是经时，普贤等、诸菩萨，舍利弗等、诸声闻，及诸天、龙、人非人、等，一切大会，皆大欢喜，受持佛语，作礼而去。', '妙法莲华经（Saddharmapundarika-sutra），简称《法华经》，在古印度、尼泊尔等地长期流行。在克什米尔、尼泊尔和中国新疆、西藏等地有40多种梵文版本，分为尼泊尔体系、克什米尔体系（基尔基特）和新疆体系。尼泊尔体系版本约为11世纪后作品，保持完整，已出版5种校订本。1983年北京民族文化宫图书馆用珂罗版彩色复制出版了由尼泊尔传入、珍藏于西藏萨迦寺的法华经。', '', '这时，以自在无碍的神通之力和声威与德行著称的普贤菩萨，与无量无边不可称数的大菩萨一起，从东方前来这个娑婆世界的耆阇崛山。途中所经诸国，大地普皆震动，天空中像下雨一样散下宝莲之花，并出现了百千万亿种歌舞与音乐。与普贤同行的还有天神、龙神、夜叉、乾闼婆、阿修罗、迦楼罗、紧那罗、摩睺罗伽八部神以及人与非人等。他们恭敬地围绕在普贤菩萨的周围，各自都现示出威严、福德与神通之力。普贤率领这些大众来到娑婆世界的耆阇崛山中，向释迦牟尼佛行以己之头礼佛之足的顶礼，又由右向左绕佛七周以示敬拜，然后对佛说：世尊，我在宝威德上王佛的国土中，遥闻娑婆世界正在讲说《法华经》，于是，我便率领无量无边百千万亿的菩萨大众同来听讲领受，惟愿世尊为我们演说。譬如在如来灭度之后，善男子、善女人如何才能得到这部《法华经》呢？
释迦牟尼佛告诉普贤菩萨说：如果善男子善女人能够成就四种法，那么，在如来世尊灭度之后，他们就可得到这部《法华经》。这四种法是：第一，得到诸佛的爱护与关怀;第二，种下各种福德的根子;第三，进入破除颠倒妄想、必能最终证悟者的行列;第四，发下了救度一切众生的誓愿。善男子、善女人若能成就这四种法，那么，就是在如来灭度之后，他们也能得到这部经典。
这时，普贤菩萨对释迦牟尼佛说：世尊，在您灭度之后的最后一个五百年中，正处五浊恶世之时，此时如果有受持这部经典的众生，我就会守护他，消除他的衰败与患祸，使他得到安稳，使如下魔鬼无可乘之机，如魔王、魔子、魔女、魔民、为魔附体者、夜叉鬼、罗刹鬼、鸠盘头鬼、毗舍阇鬼、吉遮、富单那鬼，韦陀罗鬼等等。所有这一切恼人的妖魔鬼怪都没有可乘之机去伤害受持《法华经》的众生。五浊恶世中受持《法华经》的人，不论他行走还是站立，只要他读诵这部经典，我便于那时骑乘长有六牙的白象王，与大菩萨众一起去到他的跟前，然后自己现出身相，供养并守护他，安慰他的心灵，当然这也是为了供养《法华经》。
此人如果在打坐中思惟此经，那时，我出会骑乘白象王，现身在他的面前。此人如果对《法华经》中的某句话或某个偈颂一时忘记了，我就会去教他，与他一起读诵，使他恢复到流利的程度。那时，受持、读诵《法华经》的人可以看到我的身相，所以，他会极其欢喜，由此更加精进。因为看见我的缘故，他便会得到妙定和总持一切佛法的真言神咒，其名为在法门中旋转自在的旋陀罗尼，共有百千万亿种这样的旋陀罗尼，还有应机说法、方便自在的法音方便陀罗尼。总而言之，他能够得到如此神妙、如此众多的陀罗尼。
世尊，如果在后世最后五百年的恶浊之世中，比丘、比丘尼、男居士、女居士中有人求 索《法华经》，有人受持《法华经》，有人读诵《法华经》，有人书写《法华经》，总之就是想依据《法华经》而修行，那么，他们就应该在三个七日即二十一天之内，专心致志，精进不怠。满二十一天后，我将骑乘六牙白象，在无数菩萨的围绕下，以一切众生所喜欢看见的身相，显现在他们的面前，为他们说法，开示、教导他们，使他们获得利乐，同时再给予他们陀罗尼神咒。由于他们获得了这个陀罗尼神咒，所以，不可能再有什么非人的鬼怪之类妖邪之徒来破坏他们，他们由此也不会被女人所迷惑和扰乱，我的法身也会时常亲自守护这些人。现在，就请世尊允许我说这陀罗尼咒。
于是，普贤菩萨在释迦牟尼佛前说出如下咒语：
说完如上咒语，普贤菩萨接著又对释迦牟尼佛说：世尊，如果有哪位菩萨听到这个陀罗尼神咒，那么他应该知道这是普贤菩萨的神通力量所成就的。如果《法华经》流行于人类居住的阎浮提洲，那么，其中受持《法华经》的人就应该这样想：这全靠普贤菩萨的威神之力。如果有人受持、读诵《法华经》，并正确无误地忆念，理解经中的义趣，根据经中所说而修行，那么应当知道此人是在修行普贤的行门，这人必然已在无数个佛的住所，深深地种下了善根，并为这些如来世尊摩顶授记。如果有人只是抄写《法华经》，那么，此人今生生命终之后，将转生于忉利天上。那时，会有八万四千个天女演奏起各种各样的歌舞音乐来迎接他。此人便会戴上七种珍宝所成的宝冠，在众多的美女之中，享受各种娱乐，快乐无比。仅仅抄写经书尚且如此，何况受持、读诵《法华经》，并正确忆念，理解其中义趣，根据经中所说而修行，那福德就更大了。
如果有人受持、读诵《法华经》，并理解其中义趣，那么，此人命终时，会有上千位如来世尊为他伸手，使他毫不恐惧，使他不转生堕于诸恶道中，而是往生于兜率天中弥勒菩萨的住所。弥勒菩萨具足三十二种超凡脱俗的妙相，大菩萨们围绕在他的周围，还有百千万亿的天女眷属也生活在这里。既然有如此的功德与利益，所以，有智慧的人应当专心致志地亲自抄写或让别人抄写此经，受持、读诵此经，正确忆念此经，并根据经中所说而修行，世尊，我现在以神通之力守护这部经典，在如来灭度后，将使此经在人类居住的阎浮提洲内，广泛流布，永不断绝。
释迦牟尼佛称赞普贤菩萨说：善哉！善哉！普贤，你能守护《法华经》并帮助其流通于世，使许多地方的众生获得安乐与利益，你已成就了不可思议的功德和大慈大悲的心愿。你从久远的时代以来，立下求证至高无上之圣智的心愿，所以，才能在今日发下这种种神通愿力，表示要永远守护这部《法华经》。我将以神通之力守护那些能受持普贤菩萨名号的人。普贤菩萨，如果有人能受持、读诵、正确忆念、修习、书写这部《法华经》，那么，应当知道，此人就等于是见到了释迦牟尼佛，就好像是从佛的口中亲闻这部经典一样;同时也应当知道，此人就等于在供养释迦牟尼佛;还应当知道，此人为佛所赞叹叫好;另外还应当知道，此人就等于被释迦牟尼佛用手摩顶;最后还应当知道，此人就等于被释迦牟尼佛用佛衣覆盖。
像这样的人，已不再贪念于世俗的享乐，不会喜欢外道的经书和外道的手笔，也不会再去亲近外道信徒和其他各类造作恶业的人，如屠夫、畜养猪羊鸡狗的人、猎人、出卖色相的妓女等;此人心地质朴直率，有正确的心念，有福德的力时;此人不为贪欲、瞋恨、愚痴等三毒所恼乱，也不再为嫉妒、我慢、邪慢以及自以为业已修行证果的增上慢等恶习所恼乱;此人少欲知足，能修行普贤菩萨的行门。
普贤，如来灭度之后的最后一个五百年，如果有人看见人受持、读诵《法华经》的人，那么，他就应该这么想：此人不久将去道场，破除各类魔众，证得至高无上的圣智，众而成佛果，并由此而恩法轮、击法鼓，吹法螺、雨法雨，此人将在天神的人类大众之中高坐于佛的宝座即狮子法座上教化众生。普贤，如果能在后世人受持、读诵这部经典，那么，此人就不会再贪著于衣服、卧床、饭食以及其他生活用品，他就会有求必应，心愿绝不落空，而且还能在现世获得福报。如果有人轻视而诋毁他说：你真是个疯子，白白地作了这些修行，最终却是一无所获。此人因为这种诋毁所获的罪报，将于以后的每一世中，转生这无眼的众生。
如果有人见了受持《法华经》的人，对他进行供养和称赞，那么，此人今生就可获得善报。如果还有一部分人看见受持这部经典的人之后，说出人家过去的各种恶行，以进行打击和中伤，那么，不管这种恶行是真的还是假的，这些中伤别人的人现世就会患上白癞病。如果有人轻视讥笑受持《法华经》的人，那么，他所获得的果报是生生世世牙齿疏松、缺漏，口唇丑陋，鼻子扁平，手脚弯曲，双眼歪斜，身上臭秽，并患恶疮、脓血、水肿、气喘等各种重病。所以，普贤，如果见到受持这部经典的人，就应当起身远迎，就像敬拜如来世尊一样敬拜他。
释迦牟尼佛讲说这篇《普贤劝发品》时，与恒河沙数一样无量无边的菩萨获得了百千万亿种名叫旋陀罗尼的自在无碍的总持法门。与三千大千世界所有微尘数一样多的菩萨都完全掌握了普贤菩萨所行的道法。
释迦牟尼佛说此经时，普贤等各位大乘菩萨、舍利弗等各位小乘声闻弟子以及各位天神、龙神等人部神众、人及非人的鬼神等法会上的一切大众，都非常欢喜，他们受持了佛所宣说的一切法语，向佛致礼后离开了法会。', NULL, '', 'indent', 1526662683, '5ab52c7a9f54547d1c3e4ca6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642075, '幽梦影 · 卷一 · 四十四', NULL, 3, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '古之不传于今者，啸也、剑术也、弹棋也、打球也。', '', '', '', NULL, '', 'indent', 1556016671, '5cbe7d9ec8959c00752d5b80', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636669, '人间词话 · 第四十七则', NULL, 13, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '稼轩中秋饮酒达旦，用《天问》体作《木兰花慢》以送月，曰：“可怜今夕月，向何处、去悠悠？是别有人间，那边才见，光景东头。”词人想象，直悟月轮绕地之理，与科学家密合，可谓神悟。 ', '', '辛弃疾【木兰花慢】（中秋饮酒将旦，客谓：前人诗词，有赋待月，无送月者。因用【天问】体赋。）："可怜今夕月，向何处、去悠悠？是别有人间，那边才见，光景东头。是天外空汗漫，但长风、浩浩送中秋。飞镜无根谁系？姮娥不嫁谁留？　谓经海底问无由。恍惚使人愁。怕万里长鲸，纵横触破，玉殿琼楼。虾蟆故堪浴水，问云何、玉兔解沈浮？若道都齐无恙，云何渐渐如钩？"', '辛弃疾在《中秋饮酒达旦，用<天问>体作<木兰花慢>以送月》中写道：“可怜今夜月，向何处，去悠悠？是别有人间，那边才见，光景东头。”词人依靠自己的想像，居然直观地领悟出月亮围绕地球运行的天理，与当今科学家的研究成果符合，可以称之为神悟了。 ', NULL, '', 'indent', 1521895324, '5ab5d71a9f545437fe951341', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636670, '人间词话 · 第四十八则', NULL, 8, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '周介存谓“梅溪词中喜用‘偷’字，足以定其品格。”刘融斋谓 “周旨荡而史意贪。”此二语令人解颐。 ', '', '见周济《介存斋论词杂著》。
刘熙载《艺概》卷四《词曲概》："周美成律最精审。史邦卿句最警炼。然未得为君子之词者，周旨荡而史意贪也。"', '周济说：“史达祖的词中，喜欢用‘偷’字，完全可以用这个字来断定他这个人的品格了。”刘熙载也说：“周邦彦词作旨趣放荡，而史达祖的词作旨意贪婪。”这两句评论读来让人不禁为之展颜微笑。', NULL, '', 'indent', 1521895363, '5ab5d7429f54543b18ab4fdb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636671, '人间词话 · 第四十九则', NULL, 11, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '介存谓梦窗词之佳者，如“水光云影，摇荡绿波，抚玩无极，追寻已远。”余览《梦窗甲乙丙丁稿》中，实无足当此者。有之，其“隔江人在雨声中，晚风菰叶生秋怨”二语乎？', '', '吴文英【踏莎行】："润玉笼绡，檀樱倚扇。绣圈犹带脂香浅。榴心空垒舞裙红，艾枝应压愁鬟乱。午梦千山，窗阴一箭。香瘢新褪红丝腕。隔江人在雨声中，晚风菰叶生愁怨。"', '周济评论说：吴文英写得好的词，如同“天光云影，摇荡绿波，抚玩无极，追寻已远”。我看完吴文英的《梦窗甲乙丙丁稿》，却觉得当中实在没有一阕词足以和以上的评论相称。如果真的有，“隔江人在雨声，晚风菰叶生秋怨”这两句算不算？', NULL, '', 'indent', 1521895402, '5ab5d76844d90418a2270c2f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636672, '人间词话 · 第五十则', NULL, 10, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '梦窗之词，吾得取其词中之一语以评之，曰：“映梦窗凌乱碧。” 玉田之词，余得取其词中之一语以评之，曰：“玉老田荒。” ', '', '吴文英【秋思】（荷塘为括苍名姝求赋其听雨小阁。）："堆枕香鬟侧。骤夜声，偏称画屏秋色。风碎串珠，润侵歌板，愁压眉窄。动罗箑清商，寸心低诉叙怨抑。映梦窗零乱碧。待涨绿春深，落花香泛，料有断红流处，暗题相忆。欢酌。檐花细滴。送故人，粉黛重饰。漏侵琼瑟，丁东敲断，弄晴月白。怕一曲''霓裳''未终，催去骖凤翼。欢谢客犹未识。漫瘦却东阳，镫前无梦到得。路隔重云雁北。"
张炎【祝英台近】（与周草窗话旧）："水痕深，花信足。寂寞汉南树。转首青阴，芳事顿如许。不知多少消魂，夜来风雨。犹梦到、断红流处。最无据。长年息影空山。愁入庾郎句。玉老田荒，心事已迟暮。几回听得啼鹃，不如归去。终不似、旧时鹦鹉。"', '吴文英的词，我从他的词作中挑一句出来进行评价，叫做“映梦窗，凌乱碧”。张炎的词，我也从他的词作中挑一句出来进行评价，叫做“玉老田荒”。 ', NULL, '', 'indent', 1521895437, '5ab5d78cee920a396f27ffa4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636673, '人间词话 · 第五十一则', NULL, 10, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '“明月照积雪”、“大江流日夜”、“中天悬明月”、“长河落日圆”，此种境界，可谓千古壮观。求之于词，唯纳兰容若塞上之作，如《长相思》之“夜深千帐灯”，《如梦令》之“万帐穹庐人醉，星影摇摇欲坠”差近之。', '', '谢灵运【岁暮】："殷忧不能寐，苦此夜难颓。明月照积雪，朔风劲且哀。运往无淹物，年逝觉已催。"
谢朓【暂使下都夜发新林至京邑赠同僚】："大江流日夜，客心悲未央。徒念关山近，终知反路长。秋河曙耿耿，寒渚夜苍苍。引顾见京室，宫雉正相望。金波丽鸱鹊，玉绳低建章。驱车鼎门外，思见昭丘阳。驰晖不可接，何况隔两乡？风云有鸟路，江汉限无梁，常恐鹰隼击，时菊委严霜。寄言罻罗者，寥廓已高翔。"
杜甫【后出塞】（之二）："朝进东门营，暮上河阳桥。落日照大旗，马鸣风萧萧。平沙列万幕，部伍各见招。中天悬明月，令严夜寂寥。悲笳数声动，壮士惨不骄。借问大将谁？恐是霍嫖姚。"
王维【使至塞上】："单车欲问边，属国过居延。征蓬出汉塞，归雁入胡天。大漠孤烟直，长河落日圆。萧关逢候骑，都护在燕然。"
纳兰性德【长相思】："山一程，水一程。身向榆关那畔行，夜深千帐灯。风一更，雪一更。聒碎乡心梦不成，故园无此声。"
纳兰性德【如梦令】："万帐穹庐人醉，星影摇摇欲坠。归梦隔狼河，又被河声搅碎。还睡，还睡。解道醒来无味。"', '“明月照积雪”、“大江流日夜”、“中天悬明月”、“长河落日圆”，这些诗句所体现的种种境界，都可以说上千古壮观了。如果要在词中找出类似的句子来，只有纳兰容若的塞上之作，譬如《长相思》中的“夜深千帐灯”，《如梦令》中的“万帐穹庐人醉，星影摇摇欲坠”这两句比较接近了。', NULL, '', 'indent', 1521895484, '5ab5d7ba44d90418a2270e06', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636674, '人间词话 · 第五十二则', NULL, 25, 210, 1, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '纳兰容若以自然之眼观物，以自然之舌言情。此由初入中原，未染汉人风气，故能真切如此。北宋以来，一人而已。', '', '', '纳兰容若能够以自然之眼观物，以自然之舌言情，这是因为他刚从关外进入中原，没有被汉人的不良风气所沾染，所以才能有真切的性情。北宋以来，只有他一个人能够这样了。', NULL, '', 'indent', 1521895512, '5ab5d7d69f545437fe951847', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636675, '人间词话 · 第五十三则', NULL, 9, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '陆放翁跋《花间集》，谓：“唐季五代，诗愈卑，而倚声者辄简古可爱。能此不能彼，未可以理推也。”《提要》驳之，谓：“犹能举七十斤者，举百斤则蹶，举五十斤则运掉自如。”其言甚辨。然谓词必易于诗，余未敢信。善乎陈卧子之言曰：“宋人不知诗而强作诗，故终宋之世无诗。然其欢愉愁苦之致，动于中而不能抑者，类发于诗余，故其所造独工。”五代词之所以独胜，亦以此也。 ', '', '《四库提要》集部词曲类一《花间集》："后有陆游二跋。……其二称：''唐季五代，诗愈卑，而倚声者辄简古可爱。能此不能彼，未易以理推也。''不知文之体格有高卑，人之学历有强弱。学力不足副其体格，则举之不足。学力足以副其体格，则举之有余。律诗降于古诗，故中晚唐古诗多不工，而律诗则时有佳作。词又降于律诗，故五季人诗不及唐，词乃独胜。此犹能举七十斤者，举百斤则蹶，举五十则运用自如，有何不可理推乎？"
陈子龙《王介人诗余序》："宋人不知诗而强作诗。其为诗也，言理而不言情，故终宋之世无诗焉。然宋人亦不可免于有情也。故凡其欢愉愁怨之致，动于中而不能抑者，类发于诗余，故其所造独工，非后世可及。盖以沈至之思而出之必浅近，使读之者骤遇如在耳目之表，久诵而得沈永之趣，则用意难也。以儇利之词，而制之实工链，使篇无累句，句无累字，圆润明密，言如贯珠，则铸词难也。其为体也纤弱，所谓明珠翠羽，尚嫌其重，何况龙鸾？必有鲜妍之姿，而不藉粉泽，则设色难也。其为境也婉媚，虽以警露取妍，实贵含蓄，有余不尽，时在低回唱欢之际，则命篇难也。惟宋人专力事之，篇什既多，触景皆会。天机所启，若出自然。虽高谈大雅，而亦觉其不可废。何则？物有独至，小道可观也。"', '陆游在为《花间集》作跋的时候说道：“唐宋五代以来，诗越来越卑微，而词却显得更加的简古可爱，能写词不能写诗，真不知是什么道理呀。”《四库提要》驳斥他说：“这就好比是举重，能举七十斤的人，让他举一百斤就会蹶倒，而让他举五十斤就轻松自如了。”这话好像是把道理辨别得很清楚了。但如果要说词比诗容易写，我是不能信服的。还是明末的陈子龙说得好：“宋人不知道什么叫诗却要强写诗，所以终宋都没有什么好诗。但他们欢愉愁苦到了极点，情动于衷而无法抑制的时候，于是凭借诗以外的载体来抒发情感，所以独擅词作，妙绝一代。”五代的词作之所以独占鳌头，也是这个缘故啊。 ', NULL, '', 'indent', 1521895548, '5ab5d7faac502e57c94880ac', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637539, '山居听人说书', NULL, 0, 253, 0, 1, '高濂', NULL, 10013, '57ba82a88ac2470063045693', '明', 'wen', '文', '', '', '老人畏寒，不涉世故，时山居曝背，茅檐看梅初放，邻友善谈，炙？共食，令说宋江最妙回数，欢然抚掌，不觉日暮。吾观道左丰碑，人间铭颂，是亦《水浒传》耳，岂果真实不虚故说？更惜未必得同此传，世传人口。', '', '', '', NULL, '', 'indent', 1525454429, '5aec25db0b61605533e0c945', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636676, '人间词话 · 第五十四则', NULL, 9, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '四言敝而有《楚辞》，《楚辞》敝而有五言，五言敝而有七言，古诗敝而有律绝，律绝敝而有词。盖文体通行既久，染指遂多，自成习套。豪杰之士，亦难于其中自出新意，故遁而作他体，以自解脱，一切文体所以始盛终衰者，皆由于此。故谓文学后不如前，余未敢信。但就一体论，则此说固无以易也。', '', '', '四言败坏了有《楚辞》，《楚辞》败坏了有五言，五言败坏了有七言，古诗败坏了有律诗绝句，律绝败坏了有词。这是因为一种文体通行久了，写的人也就多了，慢慢地就会形成套路和习气。最后即使是诗词中的豪杰能人，也很难从中自出机杼，写出什么新意来，于是避开另创新文体，从新的文体中去求得自由和新意。一切文体，往往是从开始的繁盛发展到最后的衰败，都是由于这个原因。有人说，在文学发展的历史进程中，总是后者不如前者，我从不信服。但如果单就某一种文体来说，这种说法则又是必然的，千古不易。', NULL, '', 'indent', 1521895583, '5ab5d81d756571108cdf09f6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636677, '人间词话 · 第五十五则', NULL, 11, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '诗之三百篇、十九首，词之五代、北宋，皆无题也。非无题也，诗词中之意，不能以题尽之也。自《花庵》、《草堂》每调立题，并古人无题之词亦为之作题。如观一幅佳山水，而即曰此某山某河，可乎？诗有题而诗亡，词有题而词亡。然中材之士，鲜能知此而自振拔者矣。', '', '', '《诗经》三百篇、《古诗十九首》，五代、北宋的词，都是无题的。其实并非真的无题，而是词中的旨意，无法用标题进行概括道尽。自《花庵词选》和《草堂诗余》以来，对每一诗词都进行标题，甚至连同古人原本无题的词作也加了标题。这就如同欣赏一幅绝好的山水画，你却明确地告诉观画人说：这是某山某河，能行吗？诗有题而诗亡，词有题而词亡。但对于才学一般的人来说，很少有能够明白其中道理并且振奋自拔的。 ', NULL, '', 'indent', 1521895618, '5ab5d83c9f54543687bf9d8b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636678, '人间词话 · 第五十六则', NULL, 15, 210, 1, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '大家之作，其言情也必沁人心脾，其写景也必豁人耳目，其词脱口而出，无矫揉妆束之态。以其所见者真，所知者深也。诗词皆然。持此以衡古今之作者，可无大误矣。', '', '', '对于达到大家级别的人来说，他的作品所抒发的情感必是沁人心脾的，所描写的景物也必是令人耳目一新的。文中所用的辞句脱口而出，毫无矫揉造作、堆砌束缚的感觉。这是因为大家对所见的事物真切明了，所了解的道理深邃透彻。同样，作诗作词也如此。我们按照这个标准去衡量古今的诗词作者是否大家，基本就没有什么误差了。', NULL, '', 'indent', 1521895646, '5ab5d85c9f54543687bf9e61', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636679, '人间词话 · 第五十七则', NULL, 9, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '人能于诗词中不为美刺投赠之篇，不使隶事之句，不用粉饰之字，则于此道已过半矣。', '', '', '如果一个人能够在诗词创作中，不作虚伪的歌功颂德、惩恶劝世的作品，不作投赠应酬的作品，在作品中不使用典故，不使用替代字，那么，他在诗词创作的道路上已经成功一半了。 ', NULL, '', 'indent', 1521895671, '5ab5d8749f545437fe951c1c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636680, '人间词话 · 第五十八则', NULL, 11, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '以《长恨歌》之壮采，而所隶之事，只“小玉双成”四字，才有余也。梅村歌行，则非隶事不办。白、吴优劣，即于此见。不独作诗为然，填词家亦不可不知也。 ', '', '白居易【长恨歌】有"转教小玉双成"句为隶事。至吴伟业之【圆圆曲】，则入手即用"鼎湖"事，以下隶事句不胜指数。', '以白居易《长恨歌》这样的鸿篇诗作，它所用的典故，也只有“小玉双成”四个字，才学仍留有余地。吴伟业咏歌行文，是不用典故就不能写。白居易和吴伟业两人水平的优劣由此可见。不仅是作诗如此，填词的人也不可不知这个道理呀。 ', NULL, '', 'indent', 1521895711, '5ab5d89717d0096887772a1f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636681, '人间词话 · 第五十九则', NULL, 7, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '近体诗体制，以五七言绝句为最尊，律诗次之，排律最下。盖此体于寄兴言情，两无所当，殆有韵之骈体文耳。词中小令如绝句，长调似律诗，若长调之《百字令》、《沁园春》等，则近于排律矣。', '', '', '在近体诗的体制中，以五、七言绝句为最尊贵，律诗第二，排律则最卑下。这是因为绝句无论寄兴还是言情，都非常的适宜，几乎可与骈体文平分秋色了。词中的小令如同绝句，长调则与律诗相似，而长调中的《百字令》、《沁园春》等，就差不多接近排律了。', NULL, '', 'indent', 1521895780, '5ab5d8df9f54547d1c411c8f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636682, '人间词话 · 第六十则', NULL, 37, 210, 2, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '诗人对宇宙人生，须入乎其内，又须出乎其外。入乎其内，故能写之；出乎其外，故能观之。入乎其内，故有生气；出乎其外，故有高致。美成能入而不能出，白石以降，于此二事皆未梦见。', '', '', '诗人对待宇宙人生，必须能够深入到内部去，又必须能够跳出到外面来。深入内部去，所以才能写它；跳出外面来，所以才能观察它。深入内部去，所以有生气。跳出外面来，所以才有高致。周邦彦能入不能出。而自姜夔以来的词人，对于出与入这两件事连做梦都没有看见。 ', NULL, '', 'indent', 1521895815, '5ab5d90317d0096887772d20', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636683, '人间词话 · 第六十一则', NULL, 9, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '诗人必有轻视外物之意，故能以奴仆命风月。又必有重视外物之意，故能与花草共忧乐。', '', '', '诗人必须有轻视外物的态度，这样才能够把风月当作奴仆一样来使唤。但同时又必须要有重视外物的态度，那样才能够与花鸟共同感受忧乐。 ', NULL, '', 'indent', 1521895867, '5ab5d937ee920a396f280b1b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636726, '论语 · 尧曰篇', NULL, 10, 327, 0, 1, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '尧曰：“咨！尔舜，天之历数在尔躬，允执其中。四海困穷，天禄永终。”舜亦以命禹。曰：“予小子履，敢用玄牡，敢昭告于皇皇后帝：有罪不敢赦，帝臣不蔽，简在帝心。朕躬有罪，无以万方；万方有罪，罪在朕躬。”周有大赉，善人是富。“虽有周亲，不如仁人。百姓有过，在予一人。”谨权量，审法度，修废官，四方之政行焉。兴灭国，继绝世，举逸民，天下之民归心焉。所重：民、食、丧、祭。宽则得众，信则民任焉，敏则有功，公则说。
子张问于孔子曰：“何如斯可以从政矣？”子曰：“尊五美，屏四恶，斯可以从政矣。”子张曰：“何谓五美？”子曰：“君子惠而不费，劳而不怨，欲而不贪，泰而不骄，威而不猛。”子张曰：“何谓惠而不费？”子曰：“因民之所利而利之，斯不亦惠而不费乎？择可劳而劳之，又谁怨？欲仁而得仁，又焉贪？君子无众寡，无小大，无敢慢，斯不亦泰而不骄乎？君子正其衣冠，尊其瞻视，俨然人望而畏之，斯不亦威而不猛乎？”子张曰：“何谓四恶？”子曰：“不教而杀谓之虐；不戒视成谓之暴；慢令致期谓之贼；犹之与人也，出纳之吝谓之有司。”
孔子曰：“不知命，无以为君子也；不知礼，无以立也；不知言，无以知人也。”', '', '', '尧说：“啧啧！你这位舜！上天的大命已经落在你的身上了。诚实地保持那中道吧！假如天下百姓都隐于困苦和贫穷，上天赐给你的禄位也就会永远终止。”舜也这样告诫过禹。（商汤）说：“我小子履谨用黑色的公牛来祭祀，向伟大的天帝祷告：有罪的人我不敢擅自赦免，天帝的臣仆我也不敢掩蔽，都由天帝的心来分辨、选择。我本人若有罪，不要牵连天下万方，天下万方若有罪，都归我一个人承担。”周朝大封诸侯，使善人都富贵起来。（周武王）说：“我虽然有至亲，不如有仁德之人。百姓有过错，都在我一人身上。”认真检查度量衡器，周密地制定法度，全国的政令就会通行了。恢复被灭亡了的国家，接续已经断绝了家族，提拔被遗落的人才，天下百姓就会真心归服了。所重视的四件事：人民、粮食、丧礼、祭祀。宽厚就能得到众人的拥护，诚信就能得到别人的任用，勤敏就能取得成绩，公平就会使百姓公平。
子张问孔子说：“怎样才可以治理政事呢？”孔子说：“尊重五种美德，排除四种恶政，这样就可以治理政事了。”子张问：“五种美德是什么？”孔子说：“君子要给百姓以恩惠而自已却无所耗费；使百姓劳作而不使他们怨恨；要追求仁德而不贪图财利；庄重而不傲慢；威严而不凶猛。”子张说：“怎样叫要给百姓以恩惠而自己却无所耗费呢？”孔子说：“让百姓们去做对他们有利的事，这不就是对百姓有利而不掏自己的腰包嘛！选择可以让百姓劳作的时间和事情让百姓去做。这又有谁会怨恨呢？自己要追求仁德便得到了仁，又还有什么可贪的呢？君子对人，无论多少，势力大小，都不怠慢他们，这不就是庄重而不傲慢吗？君子衣冠整齐，目不邪视，使人见了就让人生敬畏之心，这不也是威严而不凶猛吗？”子张问：“什么叫四种恶政呢？”孔子说：“不经教化便加以杀戮叫做虐；不加告诫便要求成功叫做暴；不加监督而突然限期叫做贼，同样是给人财物，却出手吝啬，叫做小气。”
孔子说：“不懂得天命，就不能做君子；不知道礼仪，就不能立身处世；不善于分辨别人的话语，就不能真正了解他。”', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b44d4e49f46528a428401", "shortContent": " 在《论语》最后一篇中孔子先是总结古代的政治思想。第一章前半部按照历史的顺序，依次引用了古代圣王的话语，这实际是以孔子“述而不作”的方法来表达他的政治理念；后半部则提出了孔子的治国大纲。他在政治理念上的继往开来突出地表现于他的爱民思想，具体说来它有以下几个方面内容：\n\n首先，富民。尧说：“四海困穷，天禄永终”，而尧的继位者舜又将这一教诲传给大禹，《论语》以此强调富民是古代圣王世代相传的政治理念，而...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1576193234, '5ab863eeee920a396f3604cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636684, '人间词话 · 第六十二则', NULL, 11, 210, 2, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '“昔为倡家女，今为荡子妇。荡子行不归，空床难独守。”“何不策高足，先据要路津？无为久贫贱，轗轲长苦辛。”可谓淫鄙之尤。然无视为淫词、鄙词者，以其真也。五代、北宋之大词人亦然。非无淫词，读之者但觉其亲切动人。非无鄙词，但觉其精力弥满。可知淫词与鄙词之病，非淫与鄙之病，而游词之病也。“岂不尔思，室是远而。”而子曰：“未之思也，夫何远之有？”恶其游也。 ', '', '【古诗十九首】第二："青青河畔草，郁郁园中柳。盈盈楼上女，皎皎当窗牖。娥娥红粉妆，纤纤出素手。昔为倡家女，今为荡子妇。荡子行不归，空床难独守。"
【古诗十九首】第四："今日良宴会，欢乐难具陈。弹筝奋逸响，新声妙入神。令德唱高言，识曲听其真。齐心同所愿，含意俱未申。人生寄一世，奄忽若飙尘。何不策高足，先据要路津？无为守穷贱，轗轲长苦辛。"
金应圭《词选》后序："规模物类，依托歌舞。哀乐不衷其性，虑欢无与乎情。连章累篇，义不出乎花鸟。感物指事，理不外乎酬应。虽既雅而不艳，斯有句而无章。是谓游词。"
《论语·子罕》："唐棣之华，偏其反而。岂不尔思，室是远而。子曰：未之思也，夫何远之有？"', '《古诗十九首》：“昔为倡家女，今为荡子妇。荡子行不归，空床难独守”、“何不策高足，先据要路津？无为久贫贱，感轲长苦辛”，这两首诗可以说是淫荡卑鄙到极点了。但没有人把它们当作淫词和鄙词来读，因为它们表达的是真情感。五代、北宋的大词人也是这样的。并不是没有淫词，读后反而觉得亲切动人；也并不是没有鄙词，读后反而觉得精气弥漫。由此可知淫词与鄙词真正的弊病，不在于淫荡和卑鄙，而是由言不由衷、虚情假意的“游词”所造成的。在《论语．子罕》中，有一句古诗说：“难道我不思念你吗？是因为你居住得太远了”，孔子反驳说：“这是没有真正思念呀，如果真的思念了，那还有什么遥远不遥远的呢？”孔子也是厌恶那虚假的游词的。', NULL, '', 'indent', 1521895910, '5ab5d96217d0096887773009', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636685, '人间词话 · 第六十三则', NULL, 8, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '“枯藤老树昏鸦。小桥流水人家。古道西风瘦马。夕阳西下。断肠人在天涯。”此元人马东篱《天净沙》小令也。寥寥数语，深得唐人绝句妙境。有元一代词家，皆不能办此也。', '', '按此曲见诸元刊本《乐府新声》卷中、元刊本周德清《中原音韵定格》、明刊本蒋仲舒《尧山堂外纪》卷六十八、明刊本张禄《词林摘艳》及《知不足斋丛书》本盛如梓《庶斋老学丛谈》等书者，"平沙"均作"人家"，即观堂《宋元戏曲史》所引亦同。惟《历代诗余》则作"平沙"，又"西风"作"凄风"，盖欲避去复字耳。观堂此处所引，殆即本《诗余》也。', '“枯藤老树昏鸦。小桥流水人家。古道西风瘦马。夕阳西下，断肠人在天涯。”这是元朝马致远的小令《天净沙》。寥寥几句话，却深得唐人绝句高妙的境界。在元朝一代其他的词人当中，都不能写出这样的小令来。', NULL, '', 'indent', 1521895950, '5ab5d98a9f54543b18ab5f54', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636686, '人间词话 · 第六十四则', NULL, 8, 210, 0, 1, '王国维', NULL, 10070, '57b93fe87db2a2005428bfcd', '清', 'wen', '文', '', '', '白仁甫《秋夜梧桐雨》剧，沉雄悲壮，为元曲冠冕。然所作《天籁词》，粗浅之甚，不足为稼轩奴隶。岂创者易工而因者难巧欤？抑人各有能有不能也？读者观欧、秦之诗远不如词，足透此中消息。 ', '', '', '白朴所作的戏剧《秋夜梧桐雨》，沉雄悲壮，堪称元曲当中的冠军之作。但他所写的《天籁词》，极其粗糙浅显，连给辛弃疾当奴隶都不配。难道说，开创文体的人比较容易写得工巧，而承袭的人却难以企及？还是说人各有自己的长处和短处？读者试看，欧阳修和秦观的诗远不如他们的词写的好，这应该足以说明其中的道理了吧。
', NULL, '', 'indent', 1521895983, '5ab5d9ac9f54541326d42de1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636687, '少年游', NULL, 12, 395, 0, 1, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', 'https://baike.baidu.com/item/%E5%B0%91%E5%B9%B4%E6%B8%B8%C2%B7%E7%AE%97%E6%9D%A5%E5%A5%BD%E6%99%AF%E5%8F%AA%E5%A6%82%E6%96%AF/564609?fr=aladdin', '', '算来好景只如斯，惟许有情知。寻常风月，等闲谈笑，称意即相宜。
十年青鸟音尘断，往事不胜思。一钩残照，半帘飞絮，总是恼人时。', '《少年游·算来好景只如斯》是清朝著名诗人纳兰性德的所写的一首词。该词上阕写热恋时的甜蜜幸福，下阕写离别的苦楚，表达了词人对亡妻的思念之情。全诗对比鲜明，简淡清新，自然道来，直而见婉。', '这首词的词牌名得名于宋晏殊《珠玉词》中的“长似少年时”一句，别名《小阑干》、《玉腊梅枝》等。该词牌有多种体格，但都是双调。本首为其中一首，上下阕各五句，共十五句。上阕的一、二、五句和下阕的二、五句押平声韵。
斯：代词，意为“这”，表示语境中所指的事物。
寻常：普通，一般。风月：本指清风明月，后代指男女情爱。
称意：合乎心意。相宜：合适，符合。
青鸟：神话传说中为西王母取食传信的神鸟。《山海经·西山经》：“又西二百二十里，曰三危之山，三青鸟居之。”郭璞注：“三青鸟主为西王母取食者，别自栖息于此山也。”又，汉班固《汉武故事》云：“七月七日，上于承华殿斋，正中，忽有一青鸟从西方来，集殿前。上问东方朔，朔曰：‘此西王母欲来也。’有顷，王母至，有两青鸟如乌，侠侍王母傍。”后遂以“青鸟”为信使的代称。
残照：指月亮的余晖。', '只求你知道，只要懂得，因为有你，才是好景，才能称意，哪怕十年音尘绝，回想起来也只有彼时是美好的，否则就算一样月钩精巧、柳絮轻盈，也只是憔悴人看憔悴景，一发凄清。', NULL, '清代国学大师王国维《人间词话》：纳兰容若以自然之眼观物，以自然之舌言情。此初入中原未染汉人风气，故能真切如此，北宋以来，一人而已。
晚清词人况周颐《蕙风词话》：容若短调，清新婉丽，诚如其自道所云。并誉其为国初第一词手。
浙江省文物管理委员会常务委员张任政《纳兰性德年谱·丛录》：聂晋人曰：少工填词，香艳中更觉清新，婉丽处又极俊逸。真所谓笔花四照，一字动移不得者也。', 'indent', 1521898419, '5ab5e329756571108cdf59e7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636698, '江城子 · 咏史', NULL, 7, 395, 2, 1, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', 'https://baike.baidu.com/item/%E6%B1%9F%E5%9F%8E%E5%AD%90%C2%B7%E5%92%8F%E5%8F%B2/1936071', '', '湿云全压数峰低。影凄迷，望中疑。非雾非烟，神女欲来时、若问生涯原是梦，除梦里，没人知。', '《江城子·咏史》是清朝纳兰性德所作，《江城子·咏史》该词是一篇咏史之作。词之第一句出以景语，句中即含如梦如幻之感。又以生疑、凄迷之感受承接，便增添了梦幻之意。下二句用楚王梦神女之典故，进一步烘托这梦幻一般的感受。结句点明这感受唯自己能知，遂透露了凄迷寂寞、悲凉伤感的心情。', '若问句：李商隐《无题二首》之二：“神女生涯原是梦”。这里改“神女”为“若问”更突出了梦幻之感受。', '', '[{"bookId": "60fc157134bfda01e0e91549", "bookTitle": "元明清词鉴赏辞典（新一版）", "articleId": "610e865e2cee9a0c24ecc4dc", "shortContent": "不以特定的历史人物立论，也不以具体的历史事件阐述，只是凭藉着对神话的演绎，从心灵的体验发抒对历史的独特感悟，这首词题为咏史，却是别出心裁、别具一格、别有韵味。\n首句以景语切入：“湿云全压数峰低。”湿重的云雾，布满广袤的苍穹，严严匝匝地笼盖着数重山峰，仿佛将高耸的峰峦都压低了。“湿”、“压”、“低”，连下三字，渲染出一种阴沉、凝重、压抑的氛围。\n接着两句：“影凄迷，望中疑。”一“望”一“疑”，表露自...", "authors": ["吉明周"], "pressName": "上海辞书出版社"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e4077683d19330150a9", "shortContent": "词借巫山神女之故实，咏男女之间迷蒙惝恍之情事，似与史实无所关涉。词中所言，只是对情事有所感而已，似花非花，似雾非雾，道不明，理不清，并非一定眼见雨中数峰矗立之景。", "authors": [], "pressName": "崇文书局"}]', '', 'indent', 1521900142, '5ab5e9e3ee920a396f287e83', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636699, '昭君怨', NULL, 2, 395, 0, 1, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', 'https://baike.baidu.com/item/%E6%98%AD%E5%90%9B%E6%80%A8%C2%B7%E6%B7%B1%E7%A6%81%E5%A5%BD%E6%98%A5%E8%B0%81%E6%83%9C/820433?fr=aladdin', '', '深禁好春谁惜，薄暮瑶阶伫立。别院管弦声，不分明。
又是梨花欲谢，绣被春寒今夜。寂寂锁朱门，梦承恩。', '《昭君怨·深禁好春谁惜》是清代词人纳兰性德所写的一首词。这首小词委婉缠绵，深挚动人。词人借“宫禁”中一女子的形象抒写其相思相恋的苦情婉曲含蓄，且能得到更为深透的艺术效果。', '昭君怨：词牌名，本调四十字，前后阕相同。第一、二、三句，正与﹝如梦令﹞句法相同；惟﹝如梦令﹞第三句不用韵，此则换用平韵。第四句三字，即协平韵，句法为仄平平，不可移易。
深禁：深宫。禁，帝王之宫殿。
薄暮：傍晚，太阳快落山的时候。
瑶阶：玉砌的台阶，亦用为石阶的美称，这里指宫中的阶砌。
管弦声：音乐声。
绣被：带花和文字的被褥。
朱门：指古代王侯贵族的府第大门漆成红色，以示尊贵，後泛指富贵人家。
承恩：蒙受恩泽，谓被君王宠幸。', '深宫中大好的春色有谁怜惜？傍晚时分，她站在石阶上久久伫立。别院传来管弦之声，隐隐约约，不甚分明。
又到了梨花将谢之时，今晚的绣花被依旧透着春寒。将朱门锁上，冷冷清清。梦中，她得到了君王的宠幸。', '[{"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e41c305cf0801816c5f", "shortContent": "词写宫怨，当为传统题材。与白居易《宫词》“泪尽罗巾梦不成，夜深前殿按歌声”、韦庄《小重山》“一闭昭阳春又春，夜寒宫漏永，梦君恩”等，同出一机抒，惟情感更为蕴藉。但作宫词者，历来多借物以寓悲。故读者或以为抒写词人身世之感，寓其郁郁不得志之情。这或许为过度阐释。而前人又按之实事，声称纳兰所钟爱者被纳入宫中，故为词以写其遗恨，更不免失之附会。", "authors": [], "pressName": "崇文书局"}]', '近代学者张任政《纳兰性德年谱·后记》：“其末两句，最足注意，所谓‘锁朱门’何地也？‘梦承恩夕何事也？除宫闱以外，更何有承恩之事！……‘又是梨花欲谢’一句，已置身题内，且有所指，非为咏宫怨明矣。入宫之事，本诸相传，无确实证据，近读其词，特拈而书之，以见作者身世之感受，惜其时其人未得所详。”这又是一种说法。', 'indent', 1521900225, '5ab5ea2217d009688777a49c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642076, '幽梦影 · 卷一 · 四十五', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '诗僧时复有之，若道士之能诗，不啻空谷足音，何也？', '', '', '', NULL, '', 'indent', 1556016689, '5cbe7dafa673f51cbdf32aef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636718, '论语 · 颜渊篇', NULL, 89, 327, 11, 3, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '颜渊问仁，子曰：“克己复礼为仁。一日克己复礼，天下归仁焉。为仁由己，而由人乎哉？”颜渊曰：“请问其目？”子曰：“非礼勿视，非礼勿听，非礼勿言，非礼勿动。”颜渊曰：“回虽不敏，请事斯语矣。”
仲弓问仁，子曰：“出门如见大宾，使民如承大祭。己所不欲，勿施于人。在邦无怨，在家无怨。”仲弓曰：“雍虽不敏，请事斯语矣。”
司马牛问仁，子曰：“仁者，其言也讱。”曰：“其言也讱，斯谓之仁已乎？”子曰：“为之难，言之得无讱乎？”
司马牛问君子，子曰：“君子不忧不惧。”曰：“不忧不惧，斯谓之君子已乎？”子曰：“内省不疚，夫何忧何惧？”
司马牛忧曰：“人皆有兄弟，我独亡。”子夏曰：“商闻之矣：死生有命，富贵在天。君子敬而无失，与人恭而有礼，四海之内皆兄弟也。君子何患乎无兄弟也？”
子张问明，子曰：“浸润之谮，肤受之愬，不行焉，可谓明也已矣；浸润之谮、肤受之愬不行焉，可谓远也已矣。”
子贡问政，子曰：“足食，足兵，民信之矣。”子贡曰：“必不得已而去，于斯三者何先？”曰：“去兵。”子贡曰：“必不得已而去，于斯二者何先？”曰：“去食。自古皆有死，民无信不立。”
棘子成曰：“君子质而已矣，何以文为？”子贡曰：“惜乎，夫子之说君子也！驷不及舌。文犹质也，质犹文也。虎豹之鞟犹犬羊之鞟。”
哀公问于有若曰：“年饥，用不足，如之何？”有若对曰：“盍彻乎？”曰：“二，吾犹不足，如之何其彻也？”对曰：“百姓足，君孰与不足？百姓不足，君孰与足？”
子张问崇德辨惑，子曰：“主忠信，徙义，崇德也。爱之欲其生，恶之欲其死；既欲其生又欲其死，是惑也。‘诚不以富，亦只以异。’”
齐景公问政于孔子，孔子对曰：“君君，臣臣，父父，子子。”公曰：“善哉！信如君不君、臣不臣、父不父、子不子，虽有粟，吾得而食诸？”
子曰：“片言可以折狱者，其由也与？”子路无宿诺。
子曰：“听讼，吾犹人也。必也使无讼乎。”
子张问政，子曰：“居之无倦，行之以忠。”
子曰：“博学于文，约之以礼，亦可以弗畔矣夫。”
子曰：“君子成人之美，不成人之恶；小人反是。”
季康子问政于孔子，孔子对曰：“政者，正也。子帅以正，孰敢不正？”
季康子患盗，问于孔子。孔子对曰：“苟子之不欲，虽赏之不窃。”
季康子问政于孔子曰：“如杀无道以就有道，何如？”孔子对曰：“子为政，焉用杀？子欲善而民善矣。君子之德风，小人之德草，草上之风必偃。”
子张问：“士何如斯可谓之达矣？”子曰：“何哉尔所谓达者？”子张对曰：“在邦必闻，在家必闻。”子曰：“是闻也，非达也。夫达也者，质直而好义，察言而观色，虑以下人。在邦必达，在家必达。夫闻也者，色取仁而行违，居之不疑。在邦必闻，在家必闻。”
樊迟从游于舞雩之下，曰：“敢问崇德、修慝、辨惑。”子曰：“善哉问！先事后得，非崇德与？攻其恶，无攻人之恶，非修慝与？一朝之忿，忘其身，以及其亲，非惑与？”
樊迟问仁，子曰：“爱人。”问知，子曰：“知人。”樊迟未达，子曰：“举直错诸枉，能使枉者直。”樊迟退，见子夏，曰：“乡也吾见于夫子而问知，子曰：‘举直错诸枉，能使枉者直’，何谓也？”子夏曰：“富哉言乎！舜有天下，选于众，举皋陶，不仁者远矣。汤有天下，选于众，举伊尹，不仁者远矣。”
子贡问友，子曰：“忠告而善道之，不可则止，毋自辱焉。”
曾子曰：“君子以文会友，以友辅仁。”', '', '', '颜渊问怎样做才是仁。孔子说：“克制自己，一切都照着礼的要求去做，这就是仁。一旦这样做了，天下的一切就都称赞仁了。实行仁德，完全在于自己，难道还在于别人吗？”颜渊说：“请问实行仁的条目。”孔子说：“不合于礼的不要看，不合于礼的不要听，不合于礼的不要说，不合于礼的不要做。”颜渊说：“我虽然愚笨，也要照您的这些话去做。”
仲弓问怎样做才是仁。孔子说：“出门办事如同去接待贵宾，使唤百姓如同去进行重大的祭祀，（都要认真严肃。）自己不愿意要的，不要强加于别人；做到在诸侯的朝廷上没人怨恨（自己）；在卿大夫的封地里也没人怨恨（自己）。”仲弓说：“我虽然笨，也要照您的话去做。”
司马牛问怎样做才是仁。孔子说：仁人说话是慎重的。”司马牛说：“说话慎重，这就叫做仁了吗？”孔子说：“做起来很困难，说起来能不慎重吗？”
司马牛问怎样做一个君子。孔子说：“君子不忧愁，不恐惧。”司马牛说：“不忧愁，不恐惧，这样就可以叫做君子了吗？”孔子说：“自己问心无愧，那还有什么忧愁和恐惧呢？”
司马牛忧愁地说：“别人都有兄弟，唯独我没有。”子夏说：“我听说过：‘死生有命，富贵在天。’君子只要对待所做的事情严肃认真，不出差错，对人恭敬而合乎于礼的规定，那么，天下人就都是自己的兄弟了。君子何愁没有兄弟呢？”
子张问怎样做才算是明智的。孔子说：“像水润物那样暗中挑拨的坏话，像切肤之痛那样直接的诽谤，在你那里都行不通，那你可以算是明智的了。暗中挑拨的坏话和直接的诽谤，在你那里都行不通，那你可以算是有远见的了。”
子贡问怎样治理国家。孔子说，“粮食充足，军备充足，老百姓信任统治者。”子贡说：“如果不得不去掉一项，那么在三项中先去掉哪一项呢？”孔子说：“去掉军备。”子贡说：“如果不得不再去掉一项，那么这两项中去掉哪一项呢？”孔子说：“去掉粮食。自古以来人总是要死的，如果老百姓对统治者不信任，那么国家就不能存在了。”
棘子成说：“君子只要具有好的品质就行了，要那些表面的仪式干什么呢？”子贡说：“真遗憾，夫子您这样谈论君子。一言既出，驷马难追。本质就像文采，文采就像本质，都是同等重要的。去掉了毛的虎、豹皮，就如同去掉了毛的犬、羊皮一样。”
鲁哀公问有若说：“遭了饥荒，国家用度困难，怎么办？”有若回答说：“为什么不实行彻法，只抽十分之一的田税呢？”哀公说：现在抽十分之二，我还不够，怎么能实行彻法呢？”有若说：“如果百姓的用度够，您怎么会不够呢？如果百姓的用度不够，您怎么又会够呢？”
子张问怎样提高道德修养水平和辨别是非迷惑的能力。孔子说：“以忠信为主，使自己的思想合于义，这就是提高道德修养水平了。爱一个人，就希望他活下去，厌恶起来就恨不得他立刻死去，既要他活，又要他死，这就是迷惑。（正如《诗》所说的：‘即使不是嫌贫爱富，也是喜新厌旧。’）”
齐景公问孔子如何治理国家。孔子说：“做君主的要像君的样子，做臣子的要像臣的样子，做父亲的要像父亲的样子，做儿子的要像儿子的样子。”齐景公说：“讲得好呀！如果君不像君，臣不像臣，父不像父，子不像子，虽然有粮食，我能吃得上吗？”
孔子说：“只听了单方面的供词就可以判决案件的，大概只有仲由吧。”子路说话没有不算数的时候。
孔子说：“审理诉讼案件，我同别人也是一样的。重要的是必须使诉讼的案件根本不发生！”
子张问如何治理政事。孔子说：“居于官位不懈怠，执行君令要忠实。”
孔子说:君子广泛地学习文化知识，再用礼来加以约束，这样也就不会离经叛道了。”
孔子说：“君子成全别人的好事，而不助长别人的恶处。小人则与此相反。”
季康子问孔子如何治理国家。孔子回答说：“政就是正的意思。您本人带头走正路，那么还有谁敢不走正道呢？”
季康子担忧盗窃，问孔子怎么办。孔子回答说：“假如你自己不贪图财利，即使奖励偷窃，也没有人偷盗。”
季康子问孔子如何治理政事，说：“如果杀掉无道的人来成全有道的人，怎么样？”孔子说：“您治理政事，哪里用得着杀戮的手段呢？您只要想行善，老百姓也会跟着行善。在位者的品德好比风，在下的人的品德好比草，风吹到草上，草就必定跟着倒。”
子张问：“士怎样才可以叫做通达？”孔子说：“你说的通达是什么意思？”子张答道：“在国君的朝廷里必定有名望，在大夫的封地里也必定有名声。”孔子说：“这只是虚假的名声，不是通达。所谓达，那是要品质正直，遵从礼义，善于揣摩别人的话语，对察别人的脸色，经常想着谦恭待人。这样的人，就可以在国君的朝廷和大夫的封地里通达。至于有虚假名声的人，只是外表上装出的仁的样子，而行动上却正是违背了仁，自己还以仁人自居不惭愧。但他无论在国君的朝廷里和大夫的封地里都必定会有名声。”
樊迟陪着孔子在舞雩台下散步，说：“请问怎样提高品德修养？怎样改正自己的邪念？怎样辨别迷惑？”孔子说：“问得好！先努力致力于事，然后才有所收获，不就是提高品德了吗？检讨自己的邪念了吗？由于一时的气愤，就忘记了自身的安危，以至于牵连自己的亲人，这不就是迷惑吗？”
樊迟问什么是仁。孔子说：“爱人。”樊迟问什么是智，孔子说：“了解人。”樊迟还不明白。孔子说：“选拔正直的人，罢黜邪恶的人，这样就能使邪者归正。”樊迟退出来，见到子夏说：“刚才我见到老师，问他什么是智，他说‘选拔正直的人，罢黜邪恶的人，这样就能使邪者归正。这是什么意思？”子夏说：“这话说得多么深刻呀！舜有天下，在众人中挑选人才，把皋陶选拔出来，不仁的人就被疏远了。汤有了天下，在众人中挑选人才，把伊尹选拔出来，不仁的人就被疏远了。”
子贡问怎样对待朋友。孔子说：“忠诚地劝告他，恰当地引导他，如果不听也就罢了，不要自取其辱。”
曾子说：“君子以文章学问来结交朋友，依靠朋友帮助自己培养仁德。”', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a700251899613caf301f", "shortContent": "“亡”同“无”。\n\n司马牛名耕，字子牛，宋国人。此人平时多忧虑，曾问孔子怎样的人才算得上君子。孔子针对他的性格特点说：“君子不忧不惧”，并且进一步补充说：“内省不疚，夫何忧何惧？”（《颜渊》）在这一章中他忧虑的是自己没有兄弟。\n\n对于司马牛无兄弟之说，过去的注家还有另外一种解释。《左传·哀公十四年》记载宋国司马（主管军事）桓魋作乱，其弟司马牛表示反对，后流亡卫、齐、吴等国，誓不与其兄共事宋君。这些...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b4394e49f46528a427e3a", "shortContent": "本篇围绕两个论题展开：即论仁、论政。这两个论题紧密地结合在一起：孔子阐发仁的观念时探讨了治国的实际问题，而在论政时他又按照仁的观念确立政治原则，规定应有的政治品质，这样他就为儒家的仁政学说奠定了思想基础。\n\n第二十二章中孔子答樊迟问仁时说“爱人”，这是仁的概念的经典性定义。但是他不把仁限制于个人的一种品质这一范围之内，而是大大地深化和扩展了仁的观念的意义，用以规定理想的人格、心理状态、精神特质、人...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1545383883, '5ab8616e9f54540613b469c4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636719, '论语 · 子路篇', NULL, 45, 327, 1, 1, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '子路问政，子曰：“先之，劳之。”请益，曰：“无倦。”
仲弓为季氏宰，问政，子曰：“先有司，赦小过，举贤才。”曰：“焉知贤才而举之？”曰：“举尔所知。尔所不知，人其舍诸？”
子路曰：“卫君待子而为政，子将奚先？”子曰：“必也正名乎！”子路曰：“有是哉，子之迂也！奚其正？”子曰：“野哉由也！君子于其所不知，盖阙如也。名不正，则言不顺；言不顺，则事不成；事不成，则礼乐不兴；礼乐不兴，则刑罚不中；刑罚不中，则民无所错手足。故君子名之必可言也，言之必可行也。君子于其言，无所苟而已矣。”
樊迟请学稼，子曰：“吾不如老农。”请学为圃，曰：“吾不如老圃。”樊迟出，子曰：“小人哉樊须也！上好礼，则民莫敢不敬；上好义，则民莫敢不服；上好信，则民莫敢不用情。夫如是，则四方之民襁负其子而至矣，焉用稼？”
子曰：“诵《诗》三百，授之以政，不达；使于四方，不能专对；虽多，亦奚以为？”
子曰：“其身正，不令而行；其身不正，虽令不从。”
子曰：“鲁卫之政，兄弟也。”
子谓卫公子荆，“善居室。始有，曰：‘苟合矣。’少有，曰：‘苟完矣。’富有，曰：‘苟美矣。’”
子适卫，冉有仆，子曰：“庶矣哉！”冉有曰：“既庶矣，又何加焉？”曰：“富之。”曰：“既富矣，又何加焉？”曰：“教之。”
子曰：“苟有用我者，期月而已可也，三年有成。”
子曰：“‘善人为邦百年，亦可以胜残去杀矣。’诚哉是言也！”
子曰：“如有王者，必世而后仁。”
子曰：“苟正其身矣，于从政乎何有？不能正其身，如正人何？”
冉子退朝，子曰：“何晏也？”对曰：“有政。”子曰：“其事也。如有政，虽不吾以，吾其与闻之。”
定公问：“一言而可以兴邦，有诸？”孔子对曰：“言不可以若是其几也。人之言曰：‘为君难，为臣不易。’如知为君之难也，不几乎一言而兴邦乎？”曰：“一言而丧邦，有诸？”孔子对曰：“言不可以若是其几也。人之言曰：‘予无乐乎为君，唯其言而莫予违也。’如其善而莫之违也，不亦善乎？如不善而莫之违也，不几乎一言而丧邦乎？”
叶公问政，子曰：“近者说，远者来。”
子夏为莒父宰，问政，子曰：“无欲速，无见小利。欲速则不达，见小利则大事不成。”
叶公语孔子曰：“吾党有直躬者，其父攘羊，而子证之。”孔子曰：“吾党之直者异于是。父为子隐，子为父隐，直在其中矣。”
樊迟问仁，子曰：“居处恭，执事敬，与人忠。虽之夷狄，不可弃也。”
子贡问曰：“何如斯可谓之士矣？”子曰：“行己有耻，使于四方不辱君命，可谓士矣。”曰：“敢问其次。”曰：“宗族称孝焉，乡党称弟焉。”曰：“敢问其次。”曰：“言必信，行必果，踁踁然小人哉！抑亦可以为次矣。”曰：“今之从政者何如？”子曰：“噫！斗筲之人，何足算也！”
子曰：“不得中行而与之，必也狂狷乎！狂者进取，狷者有所不为也。”
子曰：“南人有言曰：‘人而无恒，不可以作巫医。’善夫！”“不恒其德，或承之羞。”子曰：“不占而已矣。”
子曰：“君子和而不同，小人同而不和。”
子贡问曰：“乡人皆好之，何如？”子曰：“未可也。”“乡人皆恶之，何如？”子曰：“未可也。不如乡人之善者好之，其不善者恶之。”
子曰：“君子易事而难说也，说之不以道不说也，及其使人也器之；小人难事而易说也，说之虽不以道说也，及其使人也求备焉。”
子曰：“君子泰而不骄，小人骄而不泰。”
子曰：“刚、毅、木、讷近仁。”
子路问曰：“何如斯可谓之士矣？”子曰：“切切偲偲，怡怡如也，可谓士矣。朋友切切偲偲，兄弟怡怡。”
子曰：“善人教民七年，亦可以即戎矣。”
子曰：“以不教民战，是谓弃之。”', '', '', '子路问怎样管理政事。孔子说：“做在老百姓之前，使老百姓勤劳。”子路请求多讲一点。孔子说：“不要懈怠。”
仲弓做了季氏的家臣，问怎样管理政事。孔子说：“先责成手下负责具体事务的官吏，让他们各负其责，赦免他们的小过错，选拔贤才来任职。”仲弓又问：“怎样知道是贤才而把他们选拔出来呢？”孔子说：“选拔你所知道的，至于你不知道的贤才，别人难道还会埋没他们吗？”
子路（对孔子）说：“卫国国君要您去治理国家，您打算先从哪些事情做起呢？”孔子说：“首先必须正名分。”子路说：“有这样做的吗？您想得太不合时宜了。这名怎么正呢？”孔子说：“仲由，真粗野啊。君子对于他所不知道的事情，总是采取存疑的态度。名分不正，说起话来就不顺当合理，说话不顺当合理，事情就办不成。事情办不成，礼乐也就不能兴盛。礼乐不能兴盛，刑罚的执行就不会得当。刑罚不得当，百姓就不知怎么办好。所以，君子一定要定下一个名分，必须能够说得明白，说出来一定能够行得通。君子对于自己的言行，是从不马马虎虎对待的。”
樊迟向孔子请教如何种庄稼。孔子说：“我不如老农。”樊迟又请教如何种菜。孔子说：“我不如老菜农。”樊迟退出以后，孔子说：“樊迟真是小人。在上位者只要重视礼，老百姓就不敢不敬畏；在上位者只要重视义，老百姓就不敢不服从；在上位的人只要重视信，老百姓就不敢不用真心实情来对待你。要是做到这样，四面八方的老百姓就会背着自己的小孩来投奔，哪里用得着自己去种庄稼呢？“
孔子说：“把《诗》三百篇背得很熟，让他处理政务，却不会办事；让他当外交使节，不能独立地办交涉；背得很多，又有什么用呢？”
孔子说：“自身正了，即使不发布命令，老百姓也会去干，自身不正，即使发布命令，老百姓也不会服从。”
孔子说：“鲁和卫两国的政事，就像兄弟（的政事）一样。”
孔子谈到卫国的公子荆时说：“他善于管理经济，居家理财。刚开始有一点，他说：‘差不多也就够了。’稍为多一点时，他说：‘差不多就算完备了。’更多一点时，他说：‘差不多算是完美了’。”
孔子到卫国去，冉有为他驾车。孔子说：“人口真多呀！”冉有说：“人口已经够多了，还要再做什么呢？”孔子说：“使他们富起来。”冉有说：“富了以后又还要做些什么？”孔子说：“对他们进行教化。”
孔子说：“如果有人用我治理国家，一年便可以搞出个样子，三年就一定会有成效。”
孔子说：“善人治理国家，经过一百年，也就可以消除残暴，废除刑罚杀戮了。这话真对呀！”
孔子说：“如果有王者兴起，也一定要三十年才能实现仁政。”
孔子说：“如果端正了自身的行为，管理政事还有什么困难呢？如果不能端正自身的行为，怎能使别人端正呢？”
冉求退朝回来，孔子说：“为什么回来得这么晚呀？”冉求说：“有政事。”孔子说：“只是一般的事务吧？如果有政事，虽然国君不用我了，我也会知道的。”
鲁定公问：“一句话就可以使国家兴盛，有这样的话吗？”孔子答道：“不可能有这样的话，但有近乎于这样的话。有人说：‘做君难，做臣不易。’如果知道了做君的难，这不近乎于一句话可以使国家兴盛吗？”鲁定公又问：“一句话可以亡国，有这样的话吗？”孔子回答说：“不可能有这样的话，但有近乎这样的话。有人说过：‘我做君主并没有什么可高兴的，我所高兴的只在于我所说的话没有人敢于违抗。’如果说得对而没有人违抗，不也好吗？如果说得不对而没有人违抗，那不就近乎于一句话可以亡国吗？”
叶公问孔子怎样管理政事。孔子说：“使近处的人高兴，使远处的人来归附。”
子夏做莒父的总管，问孔子怎样办理政事。孔子说：“不要求快，不要贪求小利。求快反而达不到目的，贪求小利就做不成大事。”
叶公告诉孔子说：“我的家乡有个正直的人，他的父亲偷了人家的羊，他告发了父亲。”孔子说：“我家乡的正直的人和你讲的正直人不一样：父亲为儿子隐瞒，儿子为父亲隐瞒。正直就在其中了。”
樊迟问怎样才是仁。孔子说：“平常在家规规矩矩，办事严肃认真，待人忠心诚意。即使到了夷狄之地，也不可背弃。”
子贡问道：“怎样才可以叫做士？”孔子说：“自己在做事时有知耻之心，出使外国各方，能够完成君主交付的使命，可以叫做士。”子贡说：“请问次一等的呢？”孔子说：“宗族中的人称赞他孝顺父母，乡党们称他尊敬兄长。”子贡又问：“请问再次一等的呢？”孔子说：“说到一定做到，做事一定坚持到底，不问是非地固执己见，那是小人啊。但也可以说是再次一等的士了。”子贡说：“现在的执政者，您看怎么样？”孔子说：“唉！这些器量狭小的人，哪里能数得上呢？”
孔子说：“我找不到奉行中庸之道的人和他交往，只能与狂者、狷者相交往了。狂者敢作敢为，狷者对有些事是不肯干的。”
孔子说：“南方人有句话说：‘人如果做事没有恒心，就不能当巫医。’这句话说得真好啊！”“人不能长久地保存自己的德行，免不了要遭受耻辱。”孔子说：“（这句话是说，没有恒心的人）用不着去占卦了。”
孔子说：“君子讲求和谐而不同流合污，小人只求完全一致，而不讲求协调。”
子贡问孔子说：“全乡人都喜欢、赞扬他，这个人怎么样？”孔子说：“这还不能肯定。”子贡又问孔子说：“全乡人都厌恶、憎恨他，这个人怎么样？”孔子说：“这也是不能肯定的。最好的人是全乡的好人都喜欢他，全乡的坏人都厌恶他。”
孔子说：“为君子办事很容易，但很难取得他的欢喜。不按正道去讨他的喜欢，他是不会喜欢的。但是，当他使用人的时候，总是量才而用人；为小人办事很难，但要取得他的欢喜则是很容易的。不按正道去讨他的喜欢，也会得到他的喜欢。但等到他使用人的时候，却是求全责备。”
孔子说：“君子安静坦然而不傲慢无礼，小人傲慢无礼而不安静坦然。”
孔子说：“刚强、果敢、朴实、谨慎，这四种品德接近于仁。”
子路问孔子道：“怎样才可以称为士呢？”孔子说：“互助督促勉励，相处和和气气，可以算是士了。朋友之间互相督促勉励，兄弟之间相处和和气气。”
孔子说：“善人教练百姓用七年的时候，也就可以叫他们去当兵打仗了。”
孔子说：“如果不先对老百姓进行作战训练，这就叫抛弃他们。”', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f962cee9a0c24ee7956", "shortContent": "郎瑛《七修类稿》本是笔记之类杂书。共分天地、国事、义理、辨证、诗文、事物、奇谑等七个门类。本篇选自“事物”类，看似仅搜奇志异，实则亦有耐人品味之处。故事中丹客出门前，问其怀双胎之妻，是否要携带雨具，腹中胎儿，一个大声答曰“无雨”，一个说是“虽不落，也有几点”，而且，竟如所料。其后有言，无不应验。此确为罕见奇事。《搜神记》中曾记“儿啼腹中”之事，已是荒诞难信。而孕妇腹中胎儿能言会道，且能未卜先知，其...", "authors": ["徐振贵张玉芹"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9c5e272d4b2255c258", "shortContent": "本篇分两个独立的部分。第一部分为鸟语，第二部分为蝉兆。\n《聊斋志异》内容涉及天上、地下、人间鬼界、海上龙宫、山川河湖，乃至过去的历史、现实的幻景、大千世界的神奇怪异，无不包容其间。在这篇《鸟语》中，作者将文章做在道士身上，让道士去接触现实社会中各式各样的人，从普通老百姓和邑令对鸟语的预警所采取的不同态度，来揭露统治者的罪恶。小说中，写老百姓对道士前倨后恭。开始，道士听到黄鹂的鸣叫，便让主人家防火，...", "authors": ["陈云发", "周美旭"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42c834a8757d5a0fb168", "shortContent": "本篇选自清代笔记小说集《客窗闲话》。\n本篇虽然题名为《金山寺医僧》，但主要笔墨并不在于塑造金山寺医僧，而在于描写清代著名医生叶天士。作品对叶天士的描写，又不是按照历史人物的真实面貌亦步亦趋去进行刻画，而是加以作者的虚构和创造。因此，此篇作品就脱离了历史史实的局限，而成为一部很有趣味和教育意义的短篇文言小说。作品中叶天士医术高明，当“某孝廉”因感冒风寒就医时，叶天士从其脉象中就已经看出其必患“消渴症...", "authors": ["曹炳建赵东丽"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b43b330675327e1245320", "shortContent": " 本篇继续阐述上一篇提出的仁政思想。第十六章说为政的一个目标是“近者悦，远者来”，也是强调统治者必须以惠民政策争取人民的真心拥护。第六、第十三章说统治者“其身正，不令而行；其身不正，虽令不从”，再次指明统治者在伦理道德上的表率作用是治国成败的关键因素。第九章重申了孔子的富民思想。第十一章提出的“胜残去杀”的治国目标则是上一篇表达的“无讼”的德治理想的又一表述。此外，还有些语录进一步说明了孔子的“举...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1553546657, '5ab861c49f545447796504f5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636720, '论语 · 宪问篇', NULL, 15, 327, 0, 2, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '宪问耻，子曰：“邦有道，谷；邦无道，谷，耻也。”“克、伐、怨、欲不行焉，可以为仁矣？”子曰：“可以为难矣，仁则吾不知也。”
子曰：“士而怀居，不足以为士矣。”
子曰：“邦有道，危言危行；邦无道，危行言孙。”
子曰：“有德者必有言，有言者不必有德。仁者必有勇，勇者不必有仁。”
南宫适问于孔子曰：“羿善射，奡荡舟，俱不得其死然；禹、稷躬稼而有天下。”夫子不答。南宫适出，子曰：“君子哉若人！尚德哉若人！”
子曰：“君子而不仁者有矣夫，未有小人而仁者也。”
子曰：“爱之，能勿劳乎？忠焉，能勿诲乎？”
子曰：“为命，裨谌草创之，世叔讨论之，行人子羽修饰之，东里子产润色之。”
或问子产，子曰：“惠人也。”问子西，曰：“彼哉，彼哉！”问管仲，曰：“人也。夺伯氏骈邑三百，饭疏食，没齿无怨言。”
子曰：“贫而无怨难，富而无骄易。”
子曰：“孟公绰为赵、魏老则优，不可以为滕、薛大夫。”
子路问成人，子曰：“若臧武仲之知、公绰之不欲、卞庄子之勇、冉求之艺，文之以礼乐，亦可以为成人矣。”曰：“今之成人者何必然？见利思义，见危授命，久要不忘平生之言，亦可以为成人矣。”
子问公叔文子于公明贾曰：“信乎，夫子不言，不笑，不取乎？”公明贾对曰：“以告者过也。夫子时然后言，人不厌其言；乐然后笑，人不厌其笑；义然后取，人不厌其取。”子曰：“其然？岂其然乎？”
子曰：“臧武仲以防求为后于鲁，虽曰不要君，吾不信也。”
子曰：“晋文公谲而不正，齐桓公正而不谲。”
子路曰：“桓公杀公子纠，召忽死之，管仲不死，曰未仁乎？”子曰：“桓公九合诸侯不以兵车，管仲之力也。如其仁，如其仁！”
子贡曰：“管仲非仁者与？桓公杀公子纠，不能死，又相之。”子曰：“管仲相桓公霸诸侯，一匡天下，民到于今受其赐。微管仲，吾其被发左衽矣。岂若匹夫匹妇之为谅也，自经于沟渎而莫之知也。”
公叔文子之臣大夫僎与文子同升诸公，子闻之，曰：“可以为‘文’矣。”
子言卫灵公之无道也，康子曰：“夫如是，奚而不丧？”孔子曰：“仲叔圉治宾客，祝鮀治宗庙，王孙贾治军旅，夫如是，奚其丧？”
子曰：“其言之不怍，则为之也难。”
陈成子弑简公，孔子沐浴而朝，告于哀公曰：“陈恒弑其君，请讨之。”公曰：“告夫三子。”，孔子曰：“以吾从大夫之后，不敢不告也，君曰‘告夫三子’者！”之三子告，不可。孔子曰：“以吾从大夫之后，不敢不告也。”
子路问事君，子曰：“勿欺也，而犯之。”
子曰：“君子上达，小人下达。”
子曰：“古之学者为己，今之学者为人。”
蘧伯玉使人于孔子，孔子与之坐而问焉，曰：“夫子何为？”对曰：“夫子欲寡其过而未能也。”使者出，子曰：“使乎！使乎！”
子曰：“不在其位，不谋其政。”曾子曰：“君子思不出其位。”
子曰：“君子耻其言而过其行。”
子曰：“君子道者三，我无能焉：仁者不忧，知者不惑，勇者不惧。”子贡曰：“夫子自道也。”
子贡方人，子曰：“赐也贤乎哉？夫我则不暇。”
子曰：“不患人之不己知，患其不能也。”
子曰：“不逆诈，不亿不信，抑亦先觉者，是贤乎！”
微生亩谓孔子曰：“丘何为是栖栖者与？无乃为佞乎？”孔子曰：“非敢为佞也，疾固也。”
曰：“骥不称其力，称其德也。”
或曰：“以德报怨，何如？”子曰：“何以报德？以直报怨，以德报德。”
子曰：“莫我知也夫！”子贡曰：“何为其莫知子也？”子曰：“不怨天，不尤人，下学而上达。知我者其天乎！”
公伯寮愬子路于季孙。子服景伯以告，曰：“夫子固有惑志于公伯寮，吾力犹能肆诸市朝。”子曰：“道之将行也与，命也；道之将废也与，命也。公伯寮其如命何？”
子曰：“贤者辟世，其次辟地，其次辟色，其次辟言。”子曰：“作者七人矣。”
子路宿于石门，晨门曰：“奚自？”子路曰：“自孔氏。”曰：“是知其不可而为之者与？”
子击磬于卫，有荷蒉而过孔氏之门者，曰：“有心哉，击磬乎！”既而曰：“鄙哉，硁硁乎！莫己知也，斯己而已矣。深则厉，浅则揭。”子曰：“果哉！末之难矣。”
子张曰：“《书》云，‘高宗谅阴，三年不言。’何谓也？”子曰：“何必高宗，古之人皆然。君薨，百官总己以听于冢宰三年。”
子曰：“上好礼，则民易使也。”
子路问君子，子曰：“修己以敬。”曰：“如斯而已乎？”曰：“修己以安人。”曰：“如斯而已乎？”曰：“修己以安百姓。修己以安百姓，尧、舜其犹病诸！”
原壤夷俟，子曰：“幼而不孙弟，长而无述焉，老而不死，是为贼！”以杖叩其胫。
阙党童子将命，或问之曰：“益者与？”子曰：“吾见其居于位也，见其与先生并行也。非求益者也，欲速成者也。”', '', '', '原宪问孔子什么是可耻。孔子说：“国家有道，做官拿俸禄；国家无道，还做官拿俸禄，这就是可耻。”原宪又问：“好胜、自夸、怨恨、贪欲都没有的人，可以算做到仁了吧？”孔子说：“这可以说是很难得的，但至于是不是做到了仁，那我就不知道了。”
孔子说：“士如果留恋家庭的安逸生活，就不配做士了。”
孔子说：“国家有道，要正言正行；国家无道，还要正直，但说话要随和谨慎。”
孔子说：“有道德的人，一定有言论，有言论的人不一定有道德。仁人一定勇敢，勇敢的人都不一定有仁德。”
南宫适问孔子：“羿善于射箭，奡善于水战，最后都不得好死。禹和稷都亲自种植庄稼，却得到了天下。”孔子没有回答，南宫适出去后，孔子说：“这个人真是个君子呀！这个人真尊重道德。”
孔子说：“君子中没有仁德的人是有的，而小人中有仁德的人是没有的。”
孔子说：“爱他，能不为他操劳吗？忠于他，能不对他劝告吗？”
孔子说：“郑国发表的公文，都是由裨谌起草的，世叔提出意见，外交官子羽加以修饰，由子产作最后修改润色。”
有人问子产是个怎样的人。孔子说：“是个有恩惠于人的人。”又问子西。孔子说：“他呀！他呀！”又问管仲。孔子说：“他是个有才干的人，他把伯氏骈邑的三百家夺走，使伯氏终生吃粗茶淡饭，直到老死也没有怨言。”
孔子说：“贫穷而能够没有怨恨是很难做到的，富裕而不骄傲是容易做到的。”
孔子说：“孟公绰做晋国越氏、魏氏的家臣，是才力有余的，但不能做滕、薛这样小国的大夫。”
子路问怎样做才是一个完美的人。孔子说：“如果具有臧武仲的智慧，孟公绰的克制，卞庄子的勇敢，冉求那样多才多艺，再用礼乐加以修饰，也就可以算是一个完人了。”孔子又说：“现在的完人何必一定要这样呢？见到财利想到义的要求，遇到危险能献出生命，长久处于穷困还不忘平日的诺言，这样也可以成为一位完美的人。”
孔子向公明贾问到公叔文子，说：“先生他不说、不笑、不取钱财，是真的吗？”公明贾回答道：“这是告诉你话的那个人的过错。先生他到该说时才说，因此别人不厌恶他说话；快乐时才笑，因此别人不厌恶他笑；合于礼要求的财利他才取，因此别人不厌恶他取。”孔子说：“原来这样，难道真是这样吗？”
孔子说：“臧武仲凭借防邑请求鲁君在鲁国替臧氏立后代，虽然有人说他不是要挟君主，我不相信。”
孔子说：“晋文公诡诈而不正派，齐桓公正派而不诡诈。”
子路说：“齐桓公杀了公子纠，召忽自杀以殉，但管仲却没有自杀。管仲不能算是仁人吧？”孔子说：“桓公多次召集各诸侯国的盟会，不用武力，都是管仲的力量啊。这就是他的仁德，这就是他的仁德。”
子贡问：“管仲不能算是仁人了吧？桓公杀了公子纠，他不能为公子纠殉死，反而做了齐桓公的宰相。”孔子说：“管仲辅佐桓公，称霸诸侯，匡正了天下，老百姓到了今天还享受到他的好处。如果没有管仲，恐怕我们也要披散着头发，衣襟向左开了。哪能像普通百姓那样恪守小节，自杀在小山沟里，而谁也不知道呀。”
公叔文子的家臣僎和文子一同做了卫国的大夫。孔子知道了这件事以后说：“（他死后）可以给他‘文’的谥号了。”
孔子讲到卫灵公的无道，季康子说：“既然如此，为什么他没有败亡呢？”孔子说：“因为他有仲叔圉接待宾客，祝鮀管理宗庙祭祀，王孙贾统率军队，像这样，怎么会败亡呢？”
孔子说：“说话如果大言不惭，那么实现这些话就是很困难的了。”
陈成子杀了齐简公。孔子斋戒沐浴以后，随即上朝去见鲁哀公，报告说：“陈恒把他的君主杀了，请你出兵讨伐他。”哀公说：“你去报告那三位大夫吧。”孔子退朝后说：“因为我曾经做过大夫，所以不敢不来报告，君主却说‘你去告诉那三位大夫吧’！”孔子去向那三位大夫报告，但三位大夫不愿派兵讨伐，孔子又说：“因为我曾经做过大夫，所以不敢不来报告呀！”
子路问怎样事奉君主。孔子说：“不能欺骗他，但可以犯颜直谏。”
孔子说：“君子向上通达仁义，小人向下通达财利。”
孔子说：“古代的人学习是为了提高自己，而现在的人学习是为了给别人看。”
蘧伯玉派使者去拜访孔子。孔子让使者坐下，然后问道：“先生最近在做什么？”使者回答说：“先生想要减少自己的错误，但未能做到。”使者走了以后，孔子说：“好一位使者啊，好一位使者啊！”
孔子说：“不在那个职位，就不要考虑那个职位上的事情。”曾子说：“君子考虑问题，从来不超出自己的职位范围。”
孔子说：“君子认为说得多而做得少是可耻的。”
孔子说：“君子之道有三个方面，我都未能做到：仁德的人不忧愁，聪明的人不迷惑，勇敢的人不畏惧。”子贡说：“这正是老师的自我表述啊！”
子贡评论别人的短处。孔子说：“赐啊，你真的就那么贤良吗？我可没有闲工夫去评论别人。”
孔子说：“不忧虑别人不知道自己，只担心自己没有本事。”
孔子说：“不预先怀疑别人欺诈，也不猜测别人不诚实，然而能事先觉察别人的欺诈和不诚实，这就是贤人了。”
微生亩对孔子说：“孔丘，你为什么这样四处奔波游说呢？你不就是要显示自己的口才和花言巧语吗？”孔子说：“我不是敢于花言巧语，只是痛恨那些顽固不化的人。”
孔子说：“千里马值得称赞的不是它的气力，而是称赞它的品德。”
有人说：“用恩德来报答怨恨怎么样？”孔子说：“用什么来报答恩德呢？应该是用正直来报答怨恨，用恩德来报答恩德。”
孔子说：“没有人了解我啊！”子贡说：“怎么能说没有人了解您呢？”孔子说：“我不埋怨天，也不责备人，下学礼乐而上达天命，了解我的只有天吧！”
公伯寮向季孙告发子路。子服景伯把这件事告诉给孔子，并且说：“季孙氏已经被公伯寮迷惑了，我的力量能够把公伯寮杀了，把他陈尸于市。”孔子说：“道能够得到推行，是天命决定的；道不能得到推行，也是天命决定的。公伯寮能把天命怎么样呢？”
孔子说：“贤人逃避动荡的社会而隐居，次一等的逃避到另外一个地方去，再次一点的逃避别人难看的脸色，再次一点的回避别人难听的话。”孔子又说：“这样做的已经有七个人了。”
子路夜里住在石门，看门的人问：“从哪里来？”子路说：“从孔子那里来。”看门的人说：“是那个明知做不到却还要去做的人吗？”
孔子在卫国，一次正在敲击磬，有一位背扛草筐的人从门前走过说：“这个击磬的人有心思啊！”一会儿又说：“声音硁硁的，真可鄙呀，没有人了解自己，就只为自己就是了。（好像涉水一样）水深就穿着衣服趟过去，水浅就撩起衣服趟过去。”孔子说：“说得真干脆，没有什么可以责问他了。”
子张说：“《尚书》上说，‘高宗守丧，三年不谈政事。’这是什么意思？”孔子说：“不仅是高宗，古人都是这样。国君死了，朝廷百官都各管自己的职事，听命于冢宰三年。”
孔子说：“在上位的人喜好礼，那么百姓就容易指使了。”
子路问什么叫君子。孔子说：“修养自己，保持严肃恭敬的态度。”子路说：“这样就够了吗？”孔子说：“修养自己，使周围的人们安乐。”子路说：“这样就够了吗？”孔子说：“修养自己，使所有百姓都安乐。修养自己使所有百姓都安乐，尧舜还怕难于做到呢？”
原壤叉开双腿坐着等待孔子。孔子骂他说：“年幼的时候，你不讲孝悌，长大了又没有什么可说的成就，老而不死，真是害人虫。”说着，用手杖敲他的小腿。
阙里的一个童子，来向孔子传话。有人问孔子：“这是个求上进的孩子吗？”孔子说：“我看见他坐在成年人的位子上，又见他和长辈并肩而行，他不是要求上进的人，只是个急于求成的人。”', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b43d930675327e12453d9", "shortContent": "本篇论述的人与事非常广泛，但是其中心思想十分明确，就是大力倡导自我修养，培育完美的人格。虽然孔子在其一生不同时期竭力强调要实行的思想和要做的事情多种多样，但是在他看来，实现这一切的关键、所有的事情中最重要的事情是自我培育理想人格。关于自我修养，孔子提出了许多深刻的思想，形成了一个完备的思想体系。本篇的文字涉及这一思想体系的许多重要方面。\n\n儒家自我修养学说的一个理论基点是自我应是人们关注的焦点，即...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1576193185, '5ab8623a9f54544779650802', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636721, '论语 · 卫灵公篇', NULL, 69, 327, 4, 3, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E8%AE%BA%E8%AF%AD_%E5%8D%AB%E7%81%B5%E5%85%AC/9771646', '', '卫灵公问陈于孔子，孔子对曰：“俎豆之事，则尝闻之矣；军旅之事，未之学也。”明日遂行。
在陈绝粮，从者病莫能兴。子路愠见曰：“君子亦有穷乎？”子曰：“君子固穷，小人穷斯滥矣。”
子曰：“赐也，女以予为多学而识之者与？”对曰：“然，非与？”曰：“非也，予一以贯之。”
子曰：“由，知德者鲜矣。”
子曰：“无为而治者其舜也与！夫何为哉？恭己正南面而已矣。”
子张问行，子曰：“言忠信，行笃敬，虽蛮貊之邦行矣；言不忠信，行不笃敬，虽州里行乎哉？立则见其参于前也；在舆则见其倚于衡也，夫然后行。”子张书诸绅。
子曰：“直哉史鱼！邦有道如矢，邦无道如矢。君子哉蘧伯玉！邦有道则仕，邦无道则可卷而怀之。”
子曰：“可与言而不与之言，失人；不可与言而与之言，失言。知者不失人亦不失言。”
子曰：“志士仁人无求生以害仁，有杀身以成仁。”
子贡问为仁，子曰：“工欲善其事，必先利其器。居是邦也，事其大夫之贤者，友其士之仁者。”
颜渊问为邦，子曰：“行夏之时，乘殷之辂，服周之冕，乐则《韶》、《舞》；放郑声，远佞人。郑声淫，佞人殆。”
子曰：“人无远虑，必有近忧。”
子曰：“已矣乎！吾未见好德如好色者也。”
子曰：“臧文仲其窃位者与！知柳下惠之贤而不与立也。”
子曰：“躬自厚而薄责于人，则远怨矣。”
子曰：“不曰‘如之何、如之何’者，吾末如之何也已矣。”
子曰：“群居终日，言不及义，好行小慧，难矣哉！”
子曰：“君子义以为质，礼以行之，孙以出之，信以成之。君子哉！”
子曰：“君子病无能焉，不病人之不己知也。”
子曰：“君子疾没世而名不称焉。”
子曰：“君子求诸己，小人求诸人。”
子曰：“君子矜而不争，群而不党。”
子曰：“君子不以言举人，不以人废言。”
子贡问曰：“有一言而可以终身行之者乎？”子曰：“其恕乎！己所不欲，勿施于人。”
子曰：“吾之于人也，谁毁谁誉？如有所誉者，其有所试矣。斯民也，三代之所以直道而行也。”
子曰：“吾犹及史之阙文也，有马者借人乘之，今亡矣夫！”
子曰：“巧言乱德，小不忍，则乱大谋。”
子曰：“众恶之，必察焉；众好之，必察焉。”
子曰：“人能弘道，非道弘人。”
子曰：“过而不改，是谓过矣。”
子曰：“吾尝终日不食、终夜不寝以思，无益，不如学也。”
子曰：“君子谋道不谋食。耕也馁在其中矣，学也禄在其中矣。君子忧道不忧贫。”
子曰：“知及之，仁不能守之，虽得之，必失之；知及之，仁能守之，不庄以莅之，则民不敬；知及之，仁能守之，庄以莅之，动之不以礼，未善也。”
子曰：“君子不可小知而可大受也，小人不可大受而可小知也。”
子曰：“民之于仁也，甚于水火。水火，吾见蹈而死者矣，未见蹈仁而死者也。”
子曰：“当仁不让于师。”
子曰：“君子贞而不谅。”
子曰：“事君，敬其事而后其食。”
子曰：“有教无类。”
子曰：“道不同，不相为谋。”
子曰：“辞达而已矣。”
师冕见，及阶，子曰：“阶也。”及席，子曰：“席也。”皆坐，子告之曰：“某在斯，某在斯。”师冕出。子张问曰：“与师言之道与？”子曰：“然，固相师之道也。”', '《论语·卫灵公》本篇包括42章，本篇内容涉及到孔子的“君子小人”观的若干方面、孔子的教育思想和政治思想，以及孔子在其他方面的言行。', '①陈：同“阵”，即布阵。②俎（zǔ）豆：古代的礼器，盛物的器皿。俎豆之事：关于礼制的事情。③陈：古代诸侯国，地域在今河南东部和安徽北部。在陈绝粮：孔子周游列国时从陈国去蔡的途中被陈国人包围，绝粮七天。④愠（yùn）：恼怒。⑤固：安守。⑥滥：为非作歹。⑦女：同“汝”。⑧鲜（xiǎn）：少。⑨正南面：遵守正道坐于王位之上。⑩行：主张的实行。⑪蛮貊（mò）：古代对边疆少数民族的贬称。⑫其：指忠信笃敬。参：列，显现。⑬舆：车。衡：车辕前的横木。⑭绅：束在腰间、一头垂下的宽带。⑮史鱼：名䲡（qiú），字子鱼，卫国大夫。⑯矢：箭。如矢：比喻直。⑰卷：收起来。之：指其主张。⑱知：同“智”。⑲时：历法，以正月为岁首，自汉武帝至清代皆用夏时。⑳辂（lù）：大车。商辂为木制，朴素牢固。周人多饰以金玉，比较奢侈。㉑韶：指《韶》乐，古代歌颂舜的功德的乐舞。舞：指歌颂周武王的乐舞《武》。㉒放：排斥。郑声：郑国的民间音乐。㉓远：远离。佞人：善于花言巧语、阿谀奉承的人。㉔臧文仲：鲁国大夫臧孙辰，孔子曾批评他“不仁”，生活奢侈。窃位：窃居权位。㉕柳下惠：春秋中期鲁国大夫，姓展，名获，又名禽，柳下是其封地，谥为“惠”。㉖与立：与之并立于朝，即推荐、任用他。㉗自厚：严格要求自己，多责备自己。㉘如之何：怎么办。㉙末如之何：（对他们）没有办法。㉚行小慧：卖弄小聪明。㉛质：根本。㉜孙：同“逊”。出：表达。㉝病：忧虑。㉞疾：痛恨。没世：死亡。名不称：不能显身扬名。㉟诸：“之于”的合音。㊱矜：庄重。㊲恕：宽容，推己及人。㊳有所试：经过一定的考验。㊴三代：指夏、商、周三代。㊵及：看到。史：史官。阙：同“缺”。阙文：缺少的字。㊶此语与上文无关，可能是窜入的错简。㊷弘：弘扬，扩充。㊸馁（něi）：饥饿。㊹知：同“智”。之：指官职，一说指事理。㊺涖（lì）：同“蒞”，临。㊻小知：从小事上看一个人。大受：承担重任。㊼甚于水火：（对仁的需要）比对水火的需要更迫切。㊽贞：正而坚定。谅：诚信，这里指不论是非，盲目地守于信。㊾类：族类，种类、宗族区分。㊿师：乐师，当时的乐师大多是盲人。冕：乐师的名字。〔51〕相：帮助，辅助。', '卫灵公向孔子问军队列阵之法。孔子回答说：“祭祀礼仪方面的事情，我还听说过；用兵打仗的事，从来没有学过。”第二天，孔子便离开了卫国。
（孔子一行）在陈国断了粮食，随从的人都饿病了。子路很不高兴地来见孔子，说道：“君子也有穷得毫无办法的时候吗？”孔子说：“君子虽然困境，但还是坚持着；小人一遇困境就无所不为了。”
孔子说：“赐啊！你以为我是学习得多了才一一记住的吗？”子贡答道：“是啊，难道不是这样吗？”孔子说：“不是的。我是用一个根本的东西把它们贯彻始终的。”
孔子说：“由啊！懂得德的人太少了。”
孔子说：“能够无所作为而治理天下的人，大概只有舜吧？他做了些什么呢？只是庄严端正地坐在朝廷的王位上罢了。”
子张问如何才能使自己到处都能行得通。孔子说：“说话要忠信，行事要笃敬，即使到了蛮貊地区，也可以行得通。说话不忠信，行事不笃敬，就是在本乡本土，能行得通吗？站着，就仿佛看到忠信笃敬这几个字显现在面前，坐车，就好像看到这几个字刻在车辕前的横木上，这样才能使自己到处行得通。”子张把这些话写在腰间的大带上。
孔子说：“史鱼真是正直啊！国家有道，他的言行像箭一样直；国家无道，他的言行也像箭一样直。蘧伯玉也真是一位君子啊！国家有道就出来做官，国家无道就（辞退官职）把自己的主张收藏在心里。
孔子说：“可以同他谈的话，却不同他谈，这就是失掉了朋友；不可以同他谈的话，却同他谈，这就是说错了话。有智慧的人既不失去朋友，又不说错话。”
孔子说：“志士仁人，没有贪生怕死而损害仁的，只有牺牲自己的性命来成全仁的。”
子贡问怎样实行仁德。孔子说：“做工的人想把活儿做好，必须首先使他的工具锋利。住在这个国家，就要事奉大夫中的那些贤者，与士人中的仁者交朋友。”
颜渊问怎样治理国家。孔子说：“用夏代的历法，乘殷代的车子，戴周代的礼帽，奏《韶》乐，禁绝郑国的乐曲，疏远能言善辩的人，郑国的乐曲浮靡不正派，侫人太危险。”
孔子说：“人没有长远的考虑，一定会有眼前的忧患。”
孔子说：“完了，我从来没有见像好色那样好德的人。”
孔子说：“臧文仲是一个窃居官位的人吧！他明知道柳下惠是个贤人，却不举荐他一起做官。”
孔子说：“多责备自己而少责备别人，那就可以避免别人的怨恨了。”
孔子说：“从来遇事不说‘怎么办，怎么办’的人，我对他也不知怎么办才好。”
孔子说：“整天聚在一块，说的都达不到义的标准，专好卖弄小聪明，这种人真难教导。”
孔子说：“君子以义作为根本，用礼加以推行，用谦逊的语言来表达，用忠诚的态度来完成，这就是君子了。”
孔子说：“君子只怕自己没有才能，不怕别人不知道自己。”
孔子说：“君子担心死亡以后他的名字不为人们所称颂。”
孔子说：“君子求之于自己，小人求之于别人。”
孔子说：“君子庄重而不与别人争执，合群而不结党营私。”
孔子说：“君子不凭一个人说的话来举荐他，也不因为一个人不好而不采纳他的好话。”
子贡问孔子问道：“有没有一个字可以终身奉行的呢？”孔子回答说：“那就是恕吧！自己不愿意的，不要强加给别人。”
孔子说：“我对于别人，诋毁过谁？赞美过谁？如有所赞美的，必须是曾经考验过他的。夏商周三代的人都是这样做的，所以三代能直道而行。”
孔子说：“我还能够看到史书存疑的地方，有马的人（自己不会调教，）先给别人使用，这种精神，今天没有了罢。”
孔子说：“花言巧语就败坏人的德行，小事情不忍耐，就会败坏大事情。”
孔子说：“大家都厌恶他，我必须考察一下；大家都喜欢他，我也一定要考察一下。”
孔子说：“人能够使道发扬光大，不是道使人的才能扩大。”
孔子说：“有了过错而不改正，这才真叫错了。”
孔子说：“我曾经整天不吃饭，彻夜不睡觉，去左思右想，结果没有什么好处，还不如去学习为好。”
孔子说：“君子只谋求道行道，不谋求衣食。耕田，也常要饿肚子；学习，可以得到俸禄。君子只担心道不能行，不担心贫穷。”
孔子说：“凭借聪明才智足以得到它，但仁德不能保持它，即使得到，也一定会丧失。凭借聪明才智足以得到它，仁德可以保持它，不用严肃态度来治理百姓，那么百姓就会不敬；聪明才智足以得到它，仁德可以保持它，能用严肃态度来治理百姓，但动员百姓时不照礼的要求，那也是不完善的。”
孔子说：“君子不能让他们做那些小事，但可以让他们承担重大的使命。小人不能让他们承担重大的使命，但可以让他们做那些小事。”
孔子说：“百姓们对于仁（的需要），比对于水（的需要）更迫切。我只见过人跳到水火中而死的，却没有见过实行仁而死的。”
孔子说：“面对着仁德，就是老师，也不同他谦让。”
孔子说：“君子固守正道，而不拘泥于小信。”
孔子说：“事奉君主，要认真办事而把领取傣禄的事放在后面。”
孔子说：“人人都可以接受教育，不分族类。”
孔子说：“主张不同，不互相商议。”
孔子说：“言辞只要能表达意思就行了。”
乐师冕来见孔子，走到台阶沿，孔子说：“这儿是台阶。”走到坐席旁，孔子说：“这是坐席。”等大家都坐下来，孔子告诉他：“某某在这里，某某在这里。”师冕走了以后，子张就问孔子：“这就是与乐师谈话的道吗？”孔子说：“这就是帮助乐师的道。”', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8b7d0ac1145496bc4d", "shortContent": "《定婚店》一文问世后，月下老人开始逐渐产生影响。一千多年以来，人们都尊称为婚嫁奔忙的媒人为“月下老人”或“月老”。\n封建社会是封闭性的，青年男女没有自己选择对象的自由，也没有什么正常的社会活动，根本很难有机会接触异性。因此婚姻问题的解决基本上就决定于“父母之命，媒妁之言”。\n虽然《定婚店》中出现的从事媒妁活动的是一位老人，但在现实生活之中，往往并不如此，一般地说，那些专业的或半专业的，则以女性为主...", "authors": ["蒋星煜"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8e03572034f65b5db9", "shortContent": "唐经安史之乱后，日益变得黑暗，时代心理也为之一变，史云：“元和之风尚怪也。”本篇《江叟》的故事从一个追求出世、否定现实的侧面，曲折地反映了社会现实的矛盾在人们心灵中的冲突和震荡。从表面来看，小说叙述的似乎是一个江叟学道游仙的故事，但在深层含义上，它所讲述的主题实际上正是小说中荆山槐对盘豆槐所作的一段微言大义。这段微言大义既是对社会矛盾恐惧的反映，也可以当作江叟学道的人生启示录来看待。它的中心要点是...", "authors": ["赵莱静"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fab7d0ac1145496bcfe", "shortContent": "本篇写一个落第举子，在女狐仙的悉心指导与点拨之下，终于“文思大进”，并再试奏捷登第的故事。\n“红袖添香夜读书”，是古代读书人心向往之的境界。然而，在封建社会中，“男女授受不亲”，这种读书的境界虽然心憧憬之，却难以在现实生活中实现，想入非非的读书人只能诉诸梦中。本篇正是作者这种“白日梦”的曲折反映。\n作者梦想中的这位“添香夜读书”的“红袖”，是一位“姿容绝代”的年轻女子。她不但外貌美丽，而且内秉异质...", "authors": ["储有明"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42bddbb8b379ee0af990", "shortContent": "本文采自张潮《虞初新志》卷十三，是一篇根据真人真事加工创作的传奇小说，虽然不出才子佳人的范畴，却具有丰富的内涵和划时代的思想意义。首先，男女主人公皆实有其人，都是受早期民主思想的影响，初具个性解放意识的进步青年形象，具有一定的典型意义。明朝是一个宋明理学占统治地位、政治极端专制的时代，又是一个处于封建末期，封建专制制度已开始走下坡路的时代。特别是从明代中叶开始，由于皇帝或醉生梦死、惑于玄修，或荒淫...", "authors": ["王恒展"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42c10f8fda556506f15d", "shortContent": "清代文人余怀，著有《板桥杂记》，描写明末秦淮河长板桥地方的妓女生涯，《李十娘》即是其中一篇。作者文笔清新简洁，仿佛是一幅写意画，寥寥几笔，勾勒出一个资质纯洁美好的风尘女子形象。在外貌描写上，着重表现人物所特有的清丽脱俗之美，并且通过一些侧面描写来烘托人物那飘逸幽雅的风神意态，例如作者用细致笔触写她的居住环境，是幽静的“曲房密室”，庭院中种有“花时香雪”的梅树、“翠色可餐”的梧桐和修竹；再写她的淡泊...", "authors": ["孙丽华"], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70030a1d3054c757352", "shortContent": "这句名言在现代汉语中已经成为一条成语，表示人们不可只关心眼前鼻子底下的一些微不足道的小事，而应当有远大的计划和谋划，对事件的未来的发展方向、可能出现的问题和危险要有一些预见、心理准备和预防措施，不然一旦有事，猝不及防，举止失当，造成重大的损失。孔子最信任“临事而惧，好谋而成者”（《述而》）。因此他告诫世人说“人无远虑，必有近忧”。这句名言表达了一种很有价值的谋事智慧。\n\n然而，对于孔子来说，这句话...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70030a1d3054c757353", "shortContent": "人们常说“言为心声”，然而事情未必尽然如此。一个人的思想、人格与他的言辞有时是不一致的，甚至是矛盾的。孔子教人重视这一现象，由此正确地评价和对待一个人及其言辞。\n\n古代文明都十分重视语言表达能力。在古希腊，修辞即雄辩术是教育的基本科目，在中国这种能力也受到孔子的重视，他在评价其弟子的时候，首先是讲德行，其次就是言语，接下来是政事和文学（见《先进》）。但是与古希腊不同的是，儒家认为对于人格的全面发展...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70030a1d3054c757354", "shortContent": "子贡（公元前520—前456）是孔子的弟子，姓端木，名赐，字子贡，卫国人。善经商，又有理论才华，治国才能，曾为官于鲁、卫等国。\n\n仅从这条语录我们也可以看到，孔子对“己所不欲，勿施于人”一语是多么的重视，他是把它作为终身奉行的人生格言送给子贡的。孔子很可能经常用这一思想教育其弟子，所以不同的弟子都有记录。如《颜渊》第二章记载，他的学生仲弓问仁时，他在教以治国理政之道的时候把这八个大字连同其他教诲一...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70030a1d3054c757355", "shortContent": "所谓“道不同”，是指信仰不同，理想不同，志向不同；“道不同，不相为谋”就是保持独立的人格，走自己的人生道路。\n\n孔子这句箴言可能首先是主张对统治者应当采取的态度，这是孔子所代表的士，即知识分子阶层所面对的一个重大问题。在古代社会，君主或权臣掌握着臣下的生死予夺之大权：获得他们的欢心，就可以受到重用，得到荣华富贵，能够荣宗耀祖；违背了他们的意志，冒犯了他们的威严，就会受到无情的压制，甚至残酷的打击。...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b43f766a763596afeb18b", "shortContent": "上一篇《宪问》中“为己”的理念在本篇得到了进一步的展开。第二十一章中孔子说：“君子求诸己，小人求诸人。”这句话表达了自我创新的要求。话中的“求”字有“责求”之义，因此“求诸己”就是严格要求自己，与第十五章“躬自厚而薄责于人”的意义相一致。无论是“求诸己”还是“躬自厚”都是诉诸个体的自觉性，要求增强内在的精神生命力，自我奋斗，自我创造，不要一味地依赖他人，盲目地效法他人。\n\n孔子有自我实现的强烈意识...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1553547152, '5ab862aba22b9d0045f8a78e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636722, '论语 · 季氏篇', NULL, 1109, 327, 5, 6, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '季氏将伐颛臾，冉有、季路见于孔子，曰：「季氏将有事于颛臾。」孔子曰：「求，无乃尔是过与？夫颛臾，昔者先王以为东蒙主，且在邦域之中矣，是社稷之臣也。何以伐为？」冉有曰：「夫子欲之，吾二臣者皆不欲也。」孔子曰：「求，周任有言曰：『陈力就列，不能者止。』危而不持，颠而不扶，则将焉用彼相矣？且尔言过矣，虎兕出于柙，龟玉毁于椟中，是谁之过与？」冉有曰：「今夫颛臾固而近于费，今不取，后世必为子孙忧。」孔子曰：「求，君子疾夫舍曰欲之而必为之辞。丘也闻，有国有家者，不患寡而患不均，不患贫而患不安。盖均无贫，和无寡，安无倾。夫如是，故远人不服则修文德以来之，既来之，则安之。今由与求也，相夫子，远人不服而不能来也，邦分崩离析而不能守也，而谋动干戈于邦内。吾恐季孙之忧不在颛臾，而在萧墙之内也。」
孔子曰：「天下有道，则礼乐征伐自天子出；天下无道，则礼乐征伐自诸侯出。自诸侯出，盖十世希不失矣；自大夫出，五世希不失矣；陪臣执国命，三世希不失矣。天下有道，则政不在大夫；天下有道，则庶人不议。」
孔子曰：「禄之去公室五世矣，政逮于大夫四世矣，故夫三桓之子孙微矣。」
孔子曰：「益者三友，损者三友。友直、友谅、友多闻，益矣；友便辟、友善柔、友便佞，损矣。」
孔子曰：「益者三乐，损者三乐。乐节礼乐、乐道人之善、乐多贤友，益矣；乐骄乐、乐佚游、乐宴乐，损矣。」
孔子曰：「侍于君子有三愆：言未及之而言谓之躁，言及之而不言谓之隐，未见颜色而言谓之瞽。」
孔子曰：「君子有三戒：少之时，血气未定，戒之在色；及其壮也，血气方刚，戒之在斗；及其老也，血气既衰，戒之在得。」
孔子曰：「君子有三畏：畏天命，畏大人，畏圣人之言。小人不知天命而不畏也，狎大人，侮圣人之言。」
孔子曰：「生而知之者上也，学而知之者次也；困而学之又其次也。困而不学，民斯为下矣。」
孔子曰：「君子有九思：视思明，听思聪，色思温，貌思恭，言思忠，事思敬，疑思问，忿思难，见得思义。」
孔子曰：「见善如不及，见不善如探汤；吾见其人矣。吾闻其语矣。隐居以求其志，行义以达其道；吾闻其语矣，未见其人也。」
齐景公有马千驷，死之日，民无德而称焉；伯夷、叔齐饿于首阳之下，民到于今称之。其斯之谓与？」
陈亢问于伯鱼曰：「子亦有异闻乎？」对曰：「未也。尝独立，鲤趋而过庭，曰：『学《诗》乎？』对曰：『未也。』『不学《诗》，无以言。』鲤退而学《诗》。他日，又独立，鲤趋而过庭，曰：『学《礼》乎？』对曰：『未也。』『不学《礼》，无以立。』鲤退而学《礼》。闻斯二者。」陈亢退而喜曰：「问一得三，闻《诗》，闻《礼》，又闻君子之远其子也。」
邦君之妻，君称之曰夫人，夫人自称曰小童；邦人称之曰君夫人，称诸异邦曰寡小君；异邦人称之亦曰君夫人。', '这一章又反映出孔子的反战思想。他不主张通过军事手段解决国际、国内的问题，而希望采用礼、义、仁、乐的方式解决问题，这是孔子的一贯思想。此外，这一章里孔子还提出了「不患寡而患不均，不患贫而患不安」。朱熹对此句的解释是：「均，谓各得其分；安，谓上下相安。」这种思想对后代人的影响很大，甚至成为人们的社会心理。就今天而言，这种思想有消极的一面，基本不适宜现代社会，这是应该指出的。「天下无道」指什么？孔子这里讲，一是周天子的大权落入诸侯手中，二是诸侯国家的大权落入大夫和家臣手中，三是老百姓议论政事。对于这种情况，孔子极感不满，认为这种政权很快就会垮台。他希望回到「天下有道」的那种时代去，政权就会稳定，百姓也相安无事。三桓掌握了国家政权，这是春秋末期的一种政治变革，对此，孔子表示不满。本章里孔子对当时社会政治形势提出了自己的认识和态度。孔子的观点是，社会政治变革就是「天下无道」，这还是基于他的「礼治」的思想，希望变为「天下有道」的政治局面。以上这几章，主要讲的是社会交往过程中应当注意的问题。交朋友要结交那些正直、诚信、见闻广博的人，而不要结交那些逢迎谄媚、花言巧语的人，要用礼乐调节自己，多多地称道别人的好处，与君子交往要注意不急躁、不隐瞒等等，这些对我们都有一定的参考价值。这是孔子对人从少年到老年这一生中需要注意的问题作出的忠告。孔子虽说有「生而知之者」，但他不承认自己是这种人，也没有见到这种。他说自己是经过学习之后才知道的。他希望人们勤奋好学，不要等遇到困难再去学习。俗话说：书到用时方恨少，就是讲的这个道理。至于遇到困难还不去学习，就不足为训了。这对今天的人们还是很有必要注意的。本章通过孔子所谈的「君子有九思」，把人的言行举止的各个方面都考虑到了，他要求自己和学生们一言一行都要认真思考和自我反省，这里包括个人道德修养的各种规范，如温、良、恭、俭、让、忠、孝、仁、义、礼、智等等，所有这些，是孔子关于道德修养学说的组成部分。套称号是周礼的内容之一。这是为了维护等级名分制度，以达到「名正言顺」的目的。', '颛臾（zhuānyú）：鲁国的附属国，在今山东省费县西。
有事：指有军事行动，用兵作战。
东蒙主：东蒙，蒙山。主，主持祭祀的人。
周任：人名，周代史官。
陈力就列：陈力，发挥能力，按才力担任适当的职务。
相：搀扶盲人的人叫相，这里是辅助的意思。
兕（sì）：雌性犀牛。
柙（xiá）：用以关押野兽的木笼。
椟（dú）：匣子。
费：季氏的采邑。
五世：指鲁国宣公、成公、襄公、昭公、定公五世。
逮：及。
四世：指季孙氏文子、武子、平子、桓子四世。
三桓：鲁国孟孙、叔孙、季孙都出于鲁桓公，所以叫三桓
萧墙：照壁屏风。指宫廷之内。
直：正直。
谅：诚实而有信。
多闻：见闻广博。
便辟：偏离正道，故意回避他人错误。
善柔：和颜悦色，阿谀奉承。
便侫：巧言善辩，逢迎谄媚。
贤：德才兼备。
齐：看齐。
自省：自我检查。
厚：检点。
节礼乐：孔子主张用礼乐来节制人。
骄乐：骄纵不知节制的乐。
佚：同「逸」。
宴乐：沉溺于宴饮取乐。
愆（qiān）：过失。
瞽（gǔ）：盲人。
陈亢（gāng）：即陈子禽。
异闻：这里指不同于对其他学生所讲的内容。
远（yuàn）：不亲近，不偏爱。', '季氏将要讨伐颛臾。冉有、子路去见孔子说：「季氏快要攻打颛臾了。」孔子说：「冉求，恐怕应该责怪你吧？颛臾从前是周天子让它主持东蒙的祭祀的，而且已经在鲁国的疆域之内，是国家的臣属啊，为什么要讨伐它呢？」冉有说：「季孙大夫想去攻打，我们两个人都不愿意。」孔子说：「冉求，周任有句话说：『尽自己的力量去负担你的职务，实在做不好就辞职。』有了危险不去扶助，跌倒了不去搀扶，那还用辅助的人干什么呢？而且你说的话错了。老虎、犀牛从笼子里跑出来，龟甲、玉器在匣子里毁坏了，这是谁的过错呢？」冉有说：「现在颛臾城墙坚固，而且离费邑很近。现在不把它夺取过来，将来一定会成为子孙的忧患。」孔子说：「冉求，君子痛恨那种不肯实说自己想要那样做而又一定要找出理由来为之辩解的作法。我听说，对于诸侯和大夫，不怕贫穷，而怕财富不均；不怕人口少，而怕不安定。由于财富均了，也就没有所谓贫穷；大家和睦，就不会感到人少；安定了，也就没有倾覆的危险了。因为这样，所以如果远方的人还不归服，就用仁、义、礼、乐招徕他们；已经来了，就让他们安心住下去。现在，仲由和冉求你们两个人辅助季氏，远方的人不归服，而不能招徕他们；国内民心离散，你们不能保全，反而策划在国内使用武力。我只怕季孙的忧患不在颛臾，而是在自己的内部呢！」
孔子说：「天下有道的时候，制作礼乐和出兵打仗都由天子作主决定；天下无道的时候，制作礼乐和出兵打仗，由诸侯作主决定。大概经过十代很少有不垮台的；由大夫决定，经过五代很少有不垮台的。由陪臣执掌国家政权，经过三代很少有不垮台的。天下有道，国家政权就不会落在大夫手中。天下有道，老百姓也就不会议论国家政治了。」
孔子说：「鲁国失去国家政权已经有五代了，政权落在大夫之手已经四代了，所以三桓的子孙也衰微了。」
孔子说：「有益的交友有三种，有害的交友有三种。同正直的人交友，同诚信的人交友，同见闻广博的人交友，这是有益的。同惯于走邪道的人交朋友，同善于阿谀奉承的人交朋友，同惯于花言巧语的人交朋友，这是有害的。」
孔子说：「有益的喜好有三种，有害的喜好有三种。以礼乐调节自己为喜好，以称道别人的好处为喜好，以有许多贤德之友为喜好，这是有益的。喜好骄傲，喜欢闲游，喜欢大吃大喝，这就是有害的。」
孔子说：「侍奉在君子旁边陪他说话，要注意避免犯三种过失：还没有问到你的时候就说话，这是急躁；已经问到你的时候你却不说，这叫隐瞒；不看君子的脸色而贸然说话；这是瞎子。」
孔子说：「君子有三种事情应引以为戒：年少的时候，血气还不成熟，要戒除对女色的迷恋；等到身体成熟了，血气方刚，要戒除与人争斗；等到老年，血气已经衰弱了，要戒除贪得无厌。」
孔子说：「君子有三件敬畏的事情：敬畏天命，敬畏地位高贵的人，敬畏圣人的话，小人不懂得天命，因而也不敬畏，不尊重地位高贵的人，轻侮圣人之言。」
孔子说：「生来就知道的人，是上等人；经过学习以后才知道的，是次一等的人；遇到困难再去学习的，是又次一等的人；遇到困难还不学习的人，这种人就是下等的人了。」
孔子说：「君子有九种要思考的事：看的时候，要思考看清与否；听的时候，要思考是否听清楚；自己的脸色，要思考是否温和，容貌要思考是否谦恭；言谈的时候，要思考是否忠诚；办事要思考是否谨慎严肃；遇到疑问，要思考是否应该向别人询问；忿怒时，要思考是否有后患，获取财利时，要思考是否合乎义的准则。」
孔子说：「看到善良的行为，就担心达不到，看到不善良的行动，就好像把手伸到开水中一样赶快避开。我见到过这样的人，也听到过这样的话。以隐居避世来保全自己的志向，依照义而贯彻自己的主张。我听到过这种话，却没有见到过这样的人。」
齐景公有马四千匹，死的时候，百姓们觉得他没有什么德行可以称颂。伯夷、叔齐饿死在首阳山下，百姓们到现在还在称颂他们。说的就是这个意思吧。
陈亢问伯鱼：「你在老师那里听到过什么特别的教诲吗？」伯鱼回答说：「没有呀。有一次他独自站在堂上，我快步从庭里走过，他说：『学《诗》了吗？』我回答说：『没有。』他说：『不学诗，就不懂得怎么说话。』我回去就学《诗》。又有一天，他又独自站在堂上，我快步从庭里走过，他说：『学礼了吗？』我回答说：『没有。』他说：『不学礼就不懂得怎样立身。』我回去就学礼。我就听到过这两件事。」陈亢回去高兴地说：「我提一个问题，得到三方面的收获，听了关于《诗》的道理，听了关于礼的道理，又听了君子不偏爱自己儿子的道理。」
国君的妻子，国君称她为夫人，夫人自称为小童，国人称她为君夫人；对他国人则称她为寡小君，他国人也称她为君夫人。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d0dbb8b379ee0a1487", "shortContent": "《论语》主要记录孔子和门下弟子的问答之词或躬行心得的话，一般是几句话，像本篇这样几次往复论难，在《论语》中就算是篇幅长的了。孔子的时代，不但周王室不再有统率诸侯的力量，而且诸侯的权力也落到卿大夫手中，鲁国的季孙、孟孙、叔孙就把持国政，季孙权更集中。冉有、季路在孔子门下弟子中是以“政事”著名的，他俩都在季孙手下做事。季孙想扩大地盘，借口消灭一些附庸，先想攻颛臾，怕孔子反对，所以让冉有、子路去探探口气...", "authors": ["周本淳"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f882e6a6b501f974b78", "shortContent": "一提起“枯骨之精”，人们很容易便会想到《西游记》里那个外貌狰狞、内心狠毒、善于变化、诡计多端、千方百计要吃唐僧肉的白骨精来。其实在古代的志怪小说中，“枯骨之精”并非全如《西游记》的白骨精，而是也有不害人，不吃人，反倒十分可爱、可亲、可敬者的。本篇所写的中条山里的“山南枯骨之精”，便是一例。\n此精本形“容貌殊丽”，从她对金友章“谁家丽人，频来汲水”的回答中，可见其大方、聪慧。“涧下流泉，本无常主。须...", "authors": ["何均地"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文(高中)", "articleId": "6471e0d5e49f46528add29e1", "shortContent": "《论语》主要记录孔子和门下弟子的问答之词或躬行心得的话，一般是几句话，像本篇这样几次往复论难，在《论语》中就算是篇幅长的了。孔子的时代，不但周王室不再有统率诸侯的力量，而且诸侯的权力也落到卿大夫手中，鲁国的季孙、孟孙、叔孙就把持国政，季孙权更集中。冉有、季路在孔子门下弟子中是以“政事”著名的，他俩都在季孙手下做事。季孙想扩大地盘，借口消灭一些附庸，先想攻颛臾，怕孔子反对，所以让冉有、子路去探探口气...", "authors": ["周本淳"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b4427b5420e2767ee9182", "shortContent": "本篇表达了孔子政治思想方面的三个理念，它们形成了古代中国的政治传统，对二千年来中国的国家的治理、社会的发展和民族关系的处理，产生了深远的影响。\n\n第一，中央集权的理念，就是孔子所说的“天下有道，则礼乐征伐自天子出”（第二章）。这一理念的负面效应是赋予天子以绝对的权力，加强君主的专制统治。所谓“天下有道，则庶人不议”（同上），虽然可以理解为国家政治清明，老百姓没有什么政事可以批评政府，但是极易被利用...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1545329391, '5ab862e5a22b9d0045f8a8f6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636723, '论语 · 阳货篇', NULL, 23, 327, 0, 2, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '阳货欲见孔子，孔子不见，归孔子豚。孔子时其亡也而往拜之，遇诸涂。谓孔子曰：“来，予与尔言。”曰：“怀其宝而迷其邦，可谓仁乎？”曰：“不可。”“好从事而亟失时，可谓知乎？”曰：“不可！”“日月逝矣，岁不我与！”孔子曰：“诺，吾将仕矣。”
子曰：“性相近也，习相远也。”
子曰：“唯上知与下愚不移。”
子之武城，闻弦歌之声。夫子莞尔而笑，曰：“割鸡焉用牛刀？”子游对曰：“昔者偃也闻诸夫子曰：‘君子学道则爱人，小人学道则易使也。’”子曰：“二三子，偃之言是也！前言戏之耳。”
公山弗扰以费畔，召，子欲往。子路不说，曰：“末之也已，何必公山氏之之也？”子曰：“夫召我者而岂徒哉？如有用我者，吾其为东周乎！”
子张问仁于孔子，孔子曰：“能行五者于天下为仁矣。”请问之，曰：“恭、宽、信、敏、惠。恭则不侮，宽则得众，信则人任焉，敏则有功，惠则足以使人。”
佛肸召，子欲往。子路曰：“昔者由也闻诸夫子曰：‘亲于其身为不善者，君子不入也。’佛肸以中牟畔，子之往也，如之何？”子曰：“然，有是言也。不曰坚乎，磨而不磷；不曰白乎，涅而不缁。吾岂匏瓜也哉？焉能系而不食？”
子曰：“由也，女闻六言六蔽矣乎？”对曰：“未也。”“居！吾语女。好仁不好学，其蔽也愚；好知不好学，其蔽也荡；好信不好学，其蔽也贼；好直不好学，其蔽也绞；好勇不好学，其蔽也乱；好刚不好学，其蔽也狂。”
子曰：“小子何莫学夫《诗》？《诗》可以兴，可以观，可以群，可以怨。迩之事父，远之事君，多识于鸟兽草木之名。”
子谓伯鱼曰：“女为《周南》、《召南》矣乎？人而不为《周南》、《召南》，其犹正墙面而立也与！”
子曰：“礼云礼云，玉帛云乎哉？乐云乐云，钟鼓云乎哉？”
子曰：“色厉而内荏，譬诸小人，其犹穿窬之盗也与？”
子曰：“乡愿，德之贼也。”
子曰：“道听而涂说，德之弃也。”
子曰：“鄙夫可与事君也与哉？其未得之也，患得之；既得之，患失之。苟患失之，无所不至矣。”
子曰：“古者民有三疾，今也或是之亡也。古之狂也肆，今之狂也荡；古之矜也廉，今之矜也忿戾；古之愚也直，今之愚也诈而已矣。”
子曰：“巧言令色，鲜矣仁。”
子曰：“恶紫之夺朱也，恶郑声之乱雅乐也，恶利口之覆邦家者。”
子曰：“予欲无言。”子贡曰：“子如不言，则小子何述焉？”子曰：“天何言哉？四时行焉，百物生焉，天何言哉？”
孺悲欲见孔子，孔子辞以疾。将命者出户，取瑟而歌，使之闻之。
宰我问：“三年之丧，期已久矣！君子三年不为礼，礼必坏；三年不为乐，乐必崩。旧谷既没，新谷既升，钻燧改火，期可已矣。”子曰：“食夫稻，衣夫锦，于女安乎？”曰：“安！”“女安则为之！夫君子之居丧，食旨不甘，闻乐不乐，居处不安，故不为也。今女安，则为之！”宰我出，子曰：“予之不仁也！子生三年，然后免于父母之怀。夫三年之丧，天下之通丧也，予也有三年之爱于其父母乎！”
子曰：“饱食终日，无所用心，难矣哉！不有博弈者乎？为之犹贤乎已。”
子路曰：“君子尚勇乎？”子曰：“君子义以为上。君子有勇而无义为乱，小人有勇而无义为盗。”
子贡曰：“君子亦有恶乎？”子曰：“有恶。恶称人之恶者，恶居下流而讪上者，恶勇而无礼者，恶果敢而窒者。”曰：“赐也亦有恶乎？”“恶徼以为知者，恶不孙以为勇者，恶讦以为直者。”
子曰：“唯女子与小人为难养也，近之则不逊，远之则怨。”
子曰：“年四十而见恶焉，其终也已。”', '', '', '阳货想见孔子，孔子不见，他便赠送给孔子一只熟小猪，想要孔子去拜见他。孔子打听到阳货不在家时，往阳货家拜谢，却在半路上遇见了。阳货对孔子说：“来，我有话要跟你说。”（孔子走过去。）阳货说：“把自己的本领藏起来而听任国家迷乱，这可以叫做仁吗？”（孔子回答）说：“不可以。”（阳货）说：“喜欢参与政事而又屡次错过机会，这可以说是智吗？”（孔子回答）说：“不可以。”（阳货）说：“时间一天天过去了，年岁是不等人的。”孔子说：“好吧，我将要去做官了。”
孔子说：“人的本性是相近的，由于习染不同才相互有了差别。”
孔子说：“只有上等的智者与下等的愚者是改变不了的。”
孔子到武城，听见弹琴唱歌的声音。孔子微笑着说：“杀鸡何必用宰牛的刀呢？”子游回答说：“以前我听先生说过，‘君子学习了礼乐就能爱人，小人学习了礼乐就容易指使。’”孔子说：“学生们，言偃的话是对的。我刚才说的话，只是开个玩笑而已。”
公山弗扰据费邑反叛，来召孔子，孔子准备前去。子路不高兴地说：“没有地方去就算了，为什么一定要去公山弗扰那里呢？”孔子说：“他来召我，难道只是一句空话吗？如果有人用我，我就要在东方复兴周礼，建设一个东方的西周。”
子张向孔子问仁。孔子说：“能够处处实行五种品德。就是仁人了。”子张说：“请问哪五种。”孔子说：“庄重、宽厚、诚实、勤敏、慈惠。庄重就不致遭受侮辱，宽厚就会得到众人的拥护，诚信就能得到别人的任用，勤敏就会提高工作效率，慈惠就能够使唤人。”
佛肸召孔子去，孔子打算前往。子路说：“从前我听先生说过：‘亲自做坏事的人那里，君子是不去的。’现在佛肸据中牟反叛，你却要去，这如何解释呢？”孔子说：“是的，我有过这样的话。不是说坚硬的东西磨也磨不坏吗？不是说洁白的东西染也染不黑吗？我难道是个苦味的葫芦吗？怎么能只挂在那里而不给人吃呢？”
孔子说：“由呀，你听说过六种品德和六种弊病了吗？”子路回答说：“没有。”孔子说：“坐下，我告诉你。爱好仁德而不爱好学习，它的弊病是受人愚弄；爱好智慧而不爱好学习，它的弊病是行为放荡；爱好诚信而不爱好学习，它的弊病是危害亲人；爱好直率却不爱好学习，它的弊病是说话尖刻；爱好勇敢却不爱好学习，它的弊病是犯上作乱；爱好刚强却不爱好学习，它的弊病是狂妄自大。”
孔子说：“学生们为什么不学习《诗》呢？学《诗》可以激发志气，可以观察天地万物及人间的盛衰与得失，可以使人懂得合群的必要，可以使人懂得怎样去讽谏上级。近可以用来事奉父母，远可以事奉君主；还可以多知道一些鸟兽草木的名字。”
孔子对伯鱼说：“你学习《周南》、《召南》了吗？一个人如果不学习《周南》、《召南》，那就像面对墙壁而站着吧？”
孔子说：“礼呀礼呀，只是说的玉帛之类的礼器吗？乐呀乐呀，只是说的钟鼓之类的乐器吗？”
孔子说：“外表严厉而内心虚弱，以小人作比喻，就像是挖墙洞的小偷吧？”
孔子说：“没有道德修养的伪君子，就是破坏道德的人。”
孔子说：“在路上听到传言就到处去传播，这是道德所唾弃的。”
孔子说：“可以和一个鄙夫一起事奉君主吗？他在没有得到官位时，总担心得不到。已经得到了，又怕失去它。如果他担心失掉官职，那他就什么事都干得出来了。”
孔子说：“古代人有三种毛病，现在恐怕连这三种毛病也不是原来的样子了。古代的狂者不过是愿望太高，而现在的狂妄者却是放荡不羁；古代骄傲的人不过是难以接近，现在那些骄傲的人却是凶恶蛮横；古代愚笨的人不过是直率一些，现在的愚笨者却是欺诈啊！”
孔子说：“我厌恶用紫色取代红色，厌恶用郑国的声乐扰乱雅乐，厌恶用伶牙利齿而颠覆国家这样的事情。”
孔子说：“我想不说话了。”子贡说：“你如果不说话，那么我们这些学生还传述什么呢？”孔子说：“天何尝说话呢？四季照常运行，百物照样生长。天说了什么话呢？”
孺悲想见孔子，孔子以有病为由推辞不见。传话的人刚出门，（孔子）便取来瑟边弹边唱，（有意）让孺悲听到。
宰我问：“服丧三年，时间太长了。君子三年不讲究礼仪，礼仪必然败坏；三年不演奏音乐，音乐就会荒废。旧谷吃完，新谷登场，钻燧取火的木头轮过了一遍，有一年的时间就可以了。”孔子说：“（才一年的时间，）你就吃开了大米饭，穿起了锦缎衣，你心安吗？”宰我说：“我心安。”孔子说：“你心安，你就那样去做吧！君子守丧，吃美味不觉得香甜，听音乐不觉得快乐，住在家里不觉得舒服，所以不那样做。如今你既觉得心安，你就那样去做吧！”宰我出去后，孔子说：“宰予真是不仁啊！小孩生下来，到三岁时才能离开父母的怀抱。服丧三年，这是天下通行的丧礼。难道宰子对他的父母没有三年的爱吗？”
孔子说：“整天吃饱了饭，什么心思也不用，真太难了！不是还有玩博和下棋的游戏吗？干这个，也比闲着好。”
子路说：“君子崇尚勇敢吗？”孔子答道：“君子以义作为最高尚的品德，君子有勇无义就会作乱，小人有勇无义就会偷盗。”
子贡说：“君子也有厌恶的事吗？”孔子说：“有厌恶的事。厌恶宣扬别人坏处的人，厌恶身居下位而诽谤在上者的人，厌恶勇敢而不懂礼节的人，厌恶固执而又不通事理的人。”孔子又说：“赐，你也有厌恶的事吗？”子贡说：“厌恶偷袭别人的成绩而作为自己的知识的人，厌恶把不谦虚当做勇敢的人，厌恶揭发别人的隐私而自以为直率的人。”
孔子说：“只有女子和小人是难以教养的，亲近他们，他们就会无礼，疏远他们，他们就会报怨。”
孔子说：“到了四十岁的时候还被人所厌恶，他这一生也就终结了。”', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa05914587d02f66fb1", "shortContent": "本篇在《续子不语》中，是比较重要的一篇，至少在作者的主观意图中是如此。\n首先是本篇中有神怪名“子不语娘娘”，尽管故事中女主人公不是她，而是她的主人，但仍以之名篇，可见是作者有意点出的。而“子不语”又是这部五十万字，正、续长达三十四卷的志怪小说的书名。袁枚在该书《自序》中说：“书成，初名《子不语》，后见元人说部有雷同者，乃改为《新齐谐》云。”书名虽改了，但在序言中他仍然解释了以“子不语”为名的用意。...", "authors": ["姚品文"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42b234a8757d5a0fb102", "shortContent": "音音音，你负心，你真负心，孤负我到如今。记得当时，低低唱，浅浅斟；一曲值千金。如今寂寞古墙阴，秋风荒草白云深，断桥流水何处寻？凄凄切切，冷冷清清，教奴怎禁！\n〔注〕①嘉熙：南宋理宗的年号（1237—1240）。②秀州：州名。辖境为今浙江嘉兴至上海市所辖吴淞江以南一带，故治即今嘉兴，北宋称秀州，南宋改嘉兴府。③招提寺：佛寺。招提，梵语，本意为四方，汉译后渐转为寺庙意。④鲁男子：不好色的男子。《诗·国...", "authors": ["曾", "良"], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70030a1d3054c757356", "shortContent": "后世儒家，尤其是自宋朝以后的儒家，受孟子影响，喜欢谈心性。与他们不同，孔子直接讲人性的话不多，关于人性当然还没有形成系统的观点，所以弟子子贡说：“夫子之文章，可得而闻也；夫子之言性与天道，不可得而闻也。”（《公冶长》）尽管如此，孔子关于人的精神的许多论述实际上涉及人性的问题，他在这方面的思想仍然值得高度注意。\n\n对于人性，孔子的根本观点是“性相近，习相远”。这就是说，人性基本上是差不多的，不同的人...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b444866a763596afeb2ef", "shortContent": "孔子思想与世界上其他伟大的精神传统、宗教理论明显不同的地方是他将自我精神修养与经世致用相结合，本篇文字集中地反映了这一特点。\n\n孔子有强烈而迫切的参政意识。第一章写孔子在路上邂逅阳货，他对此人从来没有好感，一直设法回避，可是阳货简单的几句话，竟然能立即在孔子心中激发起在政治上显身手的欲望，当下决定要出来任职。孔子一贯反对犯上作乱的行为，但是公山弗扰在费邑造反、并邀请孔子前往时，他又动心了，想利用这...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1576193217, '5ab86342ee920a396f35fee1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636724, '论语 · 微子篇', NULL, 15, 327, 0, 2, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '微子去之，箕子为之奴，比干谏而死。孔子曰：“殷有三仁焉。”
柳下惠为士师，三黜。人曰：“子未可以去乎？”曰：“直道而事人，焉往而不三黜？枉道而事人，何必去父母之邦？”
齐景公待孔子曰：“若季氏，则吾不能。”以季、孟之间待之，曰：“吾老矣，不能用也。”孔子行。
齐人归女乐，季桓子受之，三日不朝，孔子行。”
楚狂接舆歌而过孔子曰：“凤兮凤兮，何德之衰？往者不可谏，来者犹可追。已而已而，今之从政者殆而！”孔子下，欲与之言，趋而辟之，不得与之言。
长沮、桀溺耦而耕，孔子过之，使子路问津焉。长沮曰：“夫执舆者为谁？”子路曰：“为孔丘。”曰：“是鲁孔丘与？”曰：“是也。”曰：“是知津矣。”问于桀溺，桀溺曰：“子为谁？”曰：“为仲由。”曰：“是鲁孔丘之徒与？”对曰：“然。”曰：“滔滔者天下皆是也，而谁以易之？且而与其从辟人之士也，岂若从辟世之士？”耰而不辍。子路行以告，夫子怃然曰：“鸟兽不可与同群，吾非斯人之徒与而谁与？天下有道，丘不与易也。”
子路从而后，遇丈人，以杖荷蓧。子路问曰：“子见夫子乎？”丈人曰：“四体不勤，五谷不分，孰为夫子？”植其杖而芸，子路拱而立。止子路宿，杀鸡为黍而食之，见其二子焉。明日，子路行以告，子曰：“隐者也。”使子路反见之，至则行矣。子路曰：“不仕无义。长幼之节不可废也，君臣之义如之何其废之？欲洁其身而乱大伦。君子之仕也，行其义也，道之不行已知之矣。”
逸民：伯夷、叔齐、虞仲、夷逸、朱张、柳下惠、少连。子曰：“不降其志，不辱其身，伯夷、叔齐与！”谓：“柳下惠、少连降志辱身矣，言中伦，行中虑，其斯而已矣。”谓：“虞仲、夷逸隐居放言，身中清，废中权。我则异于是，无可无不可。”
太师挚适齐，亚饭干适楚，三饭缭适蔡，四饭缺适秦，鼓方叔入于河，播鼗武入于汉，少师阳、击磬襄入于海。
周公谓鲁公曰：“君子不施其亲，不使大臣怨乎不以，故旧无大故则不弃也，无求备于一人。”
周有八士：伯达、伯适、仲突、仲忽、叔夜、叔夏、季随、季騧。', '', '', '微子离开了纣王，箕子做了他的奴隶，比干被杀死了。孔子说：“这是殷朝的三位仁人啊！”
柳下惠当典狱官，三次被罢免。有人说：“你不可以离开鲁国吗？”柳下惠说：“按正道事奉君主，到哪里不会被多次罢官呢？如果不按正道事奉君主，为什么一定要离开本国呢？”
齐景公讲到对待孔子的礼节时说：“像鲁君对待季氏那样，我做不到，我用介于季氏孟氏之间的待遇对待他。”又说：“我老了，不能用了。”孔子离开了齐国。
齐国人赠送了一些歌女给鲁国，季桓子接受了，三天不上朝。孔子于是离开了。
楚国的狂人接舆唱着歌从孔子的车旁走过，他唱道：“凤凰啊，凤凰啊，你的德运怎么这么衰弱呢？过去的已经无可挽回，未来的还来得及改正。算了吧，算了吧。今天的执政者危乎其危！”孔子下车，想同他谈谈，他却赶快避开，孔子没能和他交谈。
长沮、桀溺在一起耕种，孔子路过，让子路去寻问渡口在哪里。长沮问子路：“那个拿着缰绳的是谁？”子路说：“是孔丘。”长沮说；“是鲁国的孔丘吗？”子路说：“是的。”长沮说：“那他是早已知道渡口的位置了。”子路再去问桀溺。桀溺说：“你是谁？”子路说：“我是仲由。”桀溺说：“你是鲁国孔丘的门徒吗？”子路说：“是的。”桀溺说：“像洪水一般的坏东西到处都是，你们同谁去改变它呢？而且你与其跟着躲避人的人，为什么不跟着我们这些躲避社会的人呢？”说完，仍旧不停地做田里的农活。子路回来后把情况报告给孔子。孔子很失望地说：“人是不能与飞禽走兽合群共处的，如果不同世上的人群打交道还与谁打交道呢？如果天下太平，我就不会与你们一道来从事改革了。”
子路跟随孔子出行，落在了后面，遇到一个老丈，用拐杖挑着除草的工具。子路问道：“你看到我的老师吗？”老丈说：“四肢不劳动，五谷分不清。谁是你的老师呢？”说完，便扶着拐杖去除草。子路拱着手恭敬地站在一旁。老丈留子路到他家住宿，杀了鸡，做了小米饭给他吃，又叫两个儿子出来与子路见面。第二天，子路赶上孔子，把这件事向他作了报告。孔子说：“这是个隐士啊。”叫子路回去再看看他。子路到了那里，老丈已经走了。子路说：“不做官是不对的。长幼间的关系是不可能废弃的；君臣间的关系怎么能废弃呢？想要自身清白，却破坏了根本的君臣伦理关系。君子做官，只是为了实行君臣之义的。至于道的行不通，早就知道了。”
被遗落的人有：伯夷、叔齐、虞仲、夷逸、朱张、柳下惠、少连。孔子说：“不降低自己的意志，不屈辱自己的身分，这是伯夷叔齐吧。”说柳下惠、少连是“被迫降低自己的意志，屈辱自己的身分，但说话合乎伦理，行为合乎人心。”说虞仲、夷逸“过着隐居的生活，说话很随便，能洁身自爱，离开官位合乎权宜。”“我却同这些人不同，可以这样做，也可以那样做。”
太师挚到齐国去了，亚饭干到楚国去了，三饭缭到蔡国去了，四饭缺到秦国去了，打鼓的方叔到了黄河边，敲小鼓的武到了汉水边，少师阳和击磬的襄到了海滨。
周公对鲁公说：“君子不疏远他的亲属，不使大臣们抱怨不用他们。旧友老臣没有大的过失，就不要抛弃他们，不要对人求全责备。”
周代有八个士：伯达、伯适、伯突、仲忽、叔夜、叔夏、季随、季。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d00ce818559d064c3b", "shortContent": "本文选自《论语·微子》。\n春秋末年，西周遗制正处于瓦解之际。孔子从他的核心思想“仁”出发，仍然顽强地高举着“兴灭国，继绝世，举逸民”（《论语·尧曰》）的理想旗帜，周游宋、卫、陈、蔡、齐等国，不遗余力地宣传自己的救世主张。然而，灭国不可能再兴，绝世不可能复续，天下大势，如洪水滔滔，万牛莫挽。所以“知其不可而为之”（《论语·宪问》）的孔子所志不遂，处境狼狈。《长沮桀溺耦而耕章》所写的内容正是在这个背景...", "authors": ["周先民"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b446582772d4594815871", "shortContent": " 本篇既记述了孔子的无可无不可的人生态度，又描写了他与命运、世道抗争的悲壮情怀，在这两方面的结合中显示了孔子精神的卓越和人格的魅力。\n\n对于人们应当采取何种特殊的生活方式，孔子从来不作死板的规定。第八章中孔子评价了古代七个隐士，他把他们分为三类，但是他们在不同的社会环境中都能表现出美好的人格品质，这是孔子所赞赏的。其中伯夷、叔齐遁世，柳下惠、少连“降志辱身”，虞仲、夷逸隐居放言，各有缺陷，他们那种...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1576193230, '5ab863752f301e1c2c46d6cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636725, '论语 · 子张篇', NULL, 24, 327, 2, 2, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '子张曰：“士见危致命，见得思义，祭思敬，丧思哀，其可已矣。”
子张曰：“执德不弘，信道不笃，焉能为有？焉能为亡？”
子夏之门人问交于子张，子张曰：“子夏云何？”对曰：“子夏曰：‘可者与之，其不可者拒之。’”子张曰：“异乎吾所闻。君子尊贤而容众，嘉善而矜不能。我之大贤与，于人何所不容？我之不贤与，人将拒我，如之何其拒人也？”
子夏曰：“虽小道必有可观者焉，致远恐泥，是以君子不为也。”
子夏曰：“日知其所亡，月无忘其所能，可谓好学也已矣。”
子夏曰：“博学而笃志，切问而近思，仁在其中矣。”
子夏曰：“百工居肆以成其事，君子学以致其道。”
子夏曰：“小人之过也必文。”
子夏曰：“君子有三变：望之俨然，即之也温，听其言也厉。”
子夏曰：“君子信而后劳其民，未信，则以为厉己也；信而后谏，未信，则以为谤己也。”
子夏曰：“大德不逾闲，小德出入可也。”
子游曰：“子夏之门人小子，当洒扫应对进退则可矣。抑末也，本之则无，如之何？”子夏闻之，曰：“噫，言游过矣！君子之道，孰先传焉？孰后倦焉？譬诸草木，区以别矣。君子之道焉可诬也？有始有卒者，其惟圣人乎！”
子夏曰：“仕而优则学，学而优则仕。”
子游曰：“丧致乎哀而止。”
子游曰：“吾友张也为难能也，然而未仁。”
曾子曰：“堂堂乎张也，难与并为仁矣。”
曾子曰：“吾闻诸夫子，人未有自致者也，必也亲丧乎！”
曾子曰：“吾闻诸夫子，孟庄子之孝也，其他可能也；其不改父之臣与父之政，是难能也。”
孟氏使阳肤为士师，问于曾子。曾子曰：“上失其道，民散久矣。如得其情，则哀矜而勿喜！”
子贡曰：“纣之不善，不如是之甚也。是以君子恶居下流，天下之恶皆归焉。”
子贡曰：“君子之过也，如日月之食焉。过也人皆见之，更也人皆仰之。”
卫公孙朝问于子贡曰：“仲尼焉学？”子贡曰：“文武之道未坠于地，在人。贤者识其大者，不贤者识其小者，莫不有文武之道焉，夫子焉不学？而亦何常师之有？”
叔孙武叔语大夫于朝曰：“子贡贤于仲尼。”子服景伯以告子贡，子贡曰：“譬之宫墙，赐之墙也及肩，窥见室家之好；夫子之墙数仞，不得其门而入，不见宗庙之美、百官之富。得其门者或寡矣，夫子之云不亦宜乎！”
叔孙武叔毁仲尼，子贡曰：“无以为也，仲尼不可毁也。他人之贤者，丘陵也，犹可逾也；仲尼，日月也，无得而逾焉。人虽欲自绝，其何伤于日月乎？多见其不知量也。”
陈子禽谓子贡曰：“子为恭也，仲尼岂贤于子乎？”子贡曰：“君子一言以为知，一言以为不知，言不可不慎也。夫子之不可及也，犹天之不可阶而升也。夫子之得邦家者，所谓立之斯立，道之斯行，绥之斯来，动之斯和。其生也荣，其死也哀，如之何其可及也？”', '', '', '子张说：“士遇见危险时能献出自己的生命，看见有利可得时能考虑是否符合义的要求，祭祀时能想到是否严肃恭敬，居丧的时候想到自己是否哀伤，这样就可以了。”
子张说：“实行德而不能发扬光大，信仰道而不忠实坚定，（这样的人）怎么能说有，又怎么说他没有？”
子夏的学生向子张寻问怎样结交朋友。子张说：“子夏是怎么说的？”答道：“子夏说：‘可以相交的就和他交朋友，不可以相交的就拒绝他。’”子张说：“我所听到的和这些不一样：君子既尊重贤人，又能容纳众人；能够赞美善人，又能同情能力不够的人。如果我是十分贤良的人，那我对别人有什么不能容纳的呢？我如果不贤良，那人家就会拒绝我，又怎么谈能拒绝人家呢？”
子夏说：“即使是小技艺，也一定有可取之处，但执着钻研这些小技艺，恐怕会妨碍从事远大的事业，所以君子不做这些事。”
子夏说：“每天学到一些过去所不知道的东西，每月都不能忘记已经学会的东西，这就可以叫做好学了。”
子夏说：“博览群书广泛学习而已记得牢固，就与切身有关的问题提出疑问并且去思考，仁就在其中了。”
子夏说：“各行各业的工匠住在作坊里来完成自己的工作，君子通过学习来掌握道理。”
子夏说：“小人犯了过错一定要掩饰。”
子夏说：“君子有三变：远看他的样子庄严可怕，接近他又温和可亲，听他说话语言严厉不苟。”
子夏说：“君子必须取得信任之后才去役使百姓，否则百姓就会以为是在虐待他们。要先取得信任，然后才去规劝；否则，（君主）就会以为你在诽谤他。”
子夏说：“大节上不能超越界限，小节上有些出入是可以的。”
子游说：“子夏的学生，做些打扫和迎送客人的事情是可以的，但这些不过是末节小事，根本的东西却没有学到，这怎么行呢？”子夏听了，说：“唉，子游错了。君子之道先传授哪一条，后传授哪一条，这就像草和木一样，都是分类区别的。君子之道怎么可以随意歪曲，欺骗学生呢？能按次序有始有终地教授学生们，恐怕只有圣人吧！”
子夏说：“做官还有余力的人，就可以去学习，学习有余力的人，就可以去做官。”
子游说：“丧事做到尽哀也就可以了。”
子游说：“我的朋友子张可以说是难得的了，然而还没有做到仁。”
曾子说：“子张外表堂堂，难于和他一起做到仁的。”
曾子说：“我听老师说过，人不可能自动地充分发挥感情，（如果有，）一定是在父母死亡的时候。”
曾子说：“我听老师说过，孟庄子的孝，其他人也可以做到，但他不更换父亲的旧臣及其政治措施，这是别人难以做到的。”
孟氏任命阳肤做典狱官，阳肤向曾子请教。曾子说：“在上位的人离开了正道，百姓早就离心离德了。你如果能弄清他们的情况，就应当怜悯他们，而不要自鸣得意。”
子贡说：“纣王的不善，不像传说的那样厉害。所以君子憎恨处在下流的地方，使天下一切坏名声都归到他的身上。”
子贡说：“君子的过错好比日月蚀。他犯过错，人们都看得见；他改正过错，人们都仰望着他。”
卫国的公孙朝问子贡说：“仲尼的学问是从哪里学来的？”子贡说：“周文王武王的道，并没有失传，还留在人们中间。贤能的人可以了解它的根本，不贤的人只了解它的末节，没有什么地方无文王武王之道。我们老师何处不学，又何必要有固定的老师传播呢？”
叔孙武叔在朝廷上对大夫们说：“子贡比仲尼更贤。”子服景伯把这一番话告诉了子贡。子贡说：“拿围墙来作比喻，我家的围墙只有齐肩高，老师家的围墙却有几仞高，如果找不到门进去，你就看不见里面宗庙的富丽堂皇，和房屋的绚丽多彩。能够找到门进去的人并不多。叔孙武叔那么讲，不也是很自然吗？”
叔孙武叔诽谤仲尼。子贡说：“（这样做）是没有用的！仲尼是毁谤不了的。别人的贤德好比丘陵，还可超越过去，仲尼的贤德好比太阳和月亮，是无法超越的。虽然有人要自绝于日月，对日月又有什么损害呢？只是表明他不自量力而已。”
陈子禽对子贡说：“你是谦恭了，仲尼怎么能比你更贤良呢？”子贡说：“君子的一句话就可以表现他的智识，一句话也可以表现他的不智，所以说话不可以不慎重。夫子的高不可及，正像天是不能够顺着梯子爬上去一样。夫子如果得国而为诸侯或得到采邑而为卿大夫，那就会像人们说的那样，教百姓立于礼，百姓就会立于礼，要引导百姓，百姓就会跟着走；安抚百姓，百姓就会归顺；动员百姓，百姓就会齐心协力。（夫子）活着是十分荣耀的，（夫子）死了是极其可惜的。我怎么能赶得上他呢？”', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed20134a8757d5a0edbb4", "shortContent": "南宋末年的著名词人张炎，字叔夏，号玉田，又号乐笑翁，著有词集《山中白云词》八卷，词论专著《词源》二卷。张炎出身于世代贵显之家。六世祖张俊，为南宋初年大将。曾祖张镃，父亲张枢，都是诗词创作方面的行家。词人的青少年时代是在南宋度过的，而后半生则生活在元朝统治之下。戴表元的这篇文章写于元大德三年（1299），叙写了这位曾是贵族公子的风流词人在社会巨变中的变化，抒写了深沉的沧桑之感。\n序文从忆旧开始，追写...", "authors": ["钟", "陵"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42b65914587d02f67d6f", "shortContent": "翩翩书剑事长征，欲别相看不忍行。砧急万家催别泪，月明千里共离情。鸣鸡野店征人梦，落照荒城画角声。回首秋风知鹗荐[6]，白头吟就暮云横。\n仆一识荆[45]，遽以为欢欣偕老，不意为友拉之赴试，竟致身病长安，家生反意之变。藉使归日，非叔先知，仆或必罹虎口。然犹冀叔幸秋闱，得以申舌，而今已矣。郭、桃势焰，力实不堪支也。近隐身令表兄处，因得以前托沈婆，今又蒙令表兄慨许臂力，是以附达。万望女郎鉴仆，无他以图，...", "authors": ["郝薇莉"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b448430675327e12456cb", "shortContent": "本篇辑录的多为孔子弟子的言行，这说明《论语》一书成于孔子诸弟子及再传弟子之手。他们的言行所反映的思想与孔子的观念相一致，属于孔学范畴。他们的言论中特别值得注意的是子贡对孔子的评价，它们是孔子弟子中具有代表性的观点，对孔子在中国思想史上地位的确立产生了深远的影响。\n\n子贡被称为孔子的四大弟子之一，他与孔子接触很多，关系密切。从《论语》可知，他的领悟能力强，对孔子所说能举一反三，触类旁通，孔子表扬他能...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1553546758, '5ab863c0ac502e57c95686aa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636855, '山海经 · 山经 · 东山经', NULL, 8, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E4%B8%9C%E5%B1%B1%E7%BB%8F/19829101?fr=aladdin', '', '东山之首，曰樕?之山。北临乾昧，食水出焉，而东北流注于海。其中多鳙鳙之鱼，其状如犁牛，其音如彘鸣。
又南三百里，曰藟山，其上有玉，其下有金。湖水出焉，东流注于食水，其中多活师。
又南三百里，曰栒状之山，其上多金玉，其下多青碧石。有兽焉，其状如犬，六足，其名曰从从，其鸣自詨。有鸟焉，其状如鸡而鼠毛，其名曰䖪鼠，见则其邑大旱。水出焉。而北流注于湖水。其中多箴鱼，其状如囗，其喙如箴，食之无疫疾。
又南三百里，曰勃垒之山，无草木，无水。
又南三百里，曰番条之山，无草木，多沙。减水出焉，北流注于海，其中多鳡鱼。
又南四百里，曰姑儿之山，其上多漆，其下多桑柘。姑儿之水出焉，北流注于海，其中多鳡鱼。
又南四百里，曰高氏之山，其上多玉，其下多箴石。诸绳之水出焉，东流注于泽，其中多金玉。
又南三百里，曰岳山，其上多桑，其下多樗。泺水出焉，东流注于泽，其中多金玉。
又南三百里，曰豺山，其上无草木，其下多水，其中多堪㐨之鱼。有兽焉，其状如夸父而彘毛，其音如呼，见则天下大水。
又南三百里，曰独山，其上多金玉，其下多美石末涂之水出焉，而东流注于沔，其中多？庸，其状如黄蛇，鱼翼，出入有光，见则其邑大旱。
又南三百里，曰泰山，其上多玉，其下多金。有兽焉，其状如豚而有珠，名曰狪狪，其鸣自詨。环水出焉，东流注于江，其中多水玉。
又南三百里，曰竹山，錞于江，无草木，多瑶碧。激水出焉，而东流注于娶檀之水，其中多茈羸。
凡东山经之首，自樕鼄之山以至于竹山，凡十二山，三千六百里。其神状皆人身龙首。祠：毛用一犬祈，衈用鱼。
东次二经之首，曰空桑之山，北临食水，东望沮吴，南望沙陵，西望涮湣泽。有兽焉，其状如牛而虎文，其音如钦。其名曰軨軨，其鸣自詨，见则天下大水。
又南六百里，曰曹夕之山，其下多囗而无木，多鸟兽。
又西南四百里，曰峄皋之山，其上多金玉，其下多白垩。峄皋之水出焉，东流注于激女之水，其中多蜃珧。
又南水行五百里，流沙三进里，至于葛山之尾，无草木，多砥砺。
又南三百八十里，曰葛山之首，无草木。澧水出焉，东流注于余泽，其中多珠鳖鱼，其状如囗而有目，六足有珠，其味酸甘，食之无疠。
又南三百八十里，曰余峨之山。其上多梓枬，其下多荆杞。杂余之水出焉，东流注于黄水。有兽焉，其状如菟而鸟类喙，鸱目蛇尾，见人则眠，名犰狳，其鸣自詨，见则螽蝗为败。
又南三百里，曰杜父之山，无草木，多水。
又南三百里，曰耿山，夫草木，多水碧，多大蛇。有兽焉，其状如狐而鱼翼，其名曰朱獳，其鸣自詨见则其国有恐。
又南三百里，曰卢其之山，无草木，多沙石，沙水出焉，南流注于涔水，其中多囗鹕，其状如鸳鸯而人足，其鸣自詨，见则其国多土功。
又南三百八十里，曰姑射之山，无草木，多水。
又南水行三百里，流沙百里，曰北姑射之山，无草木，多石。
又南水行三百里，曰北姑射之山，无草木，多水。
又南三百里，曰碧山，无草木，多蛇，多碧、多玉。
又南五百里，曰缑氏之山，无草木，多金玉。原水出焉，东流注于沙泽。
又南三百里，曰姑逢之山，无草木，多金玉。有兽焉，其状如狐而有翼，其音如鸿雁，其名曰獙々，见则天下大旱。
又南五百里，曰凫丽之山，其上多金玉，其下多箴石，有兽焉，其状如狐，而九尾、九首、虎爪，名曰蠪侄，其音如婴儿，是食人。
又南五百里，曰䃌山，南临？垔水，东望湖泽，有兽焉，其状如马，而羊目、四角、牛尾，其音如獆狗，其名曰峳峳。见则其国多狡客。有鸟焉，其状如凫而鼠尾，善登木，其名曰絜钩，见则其国多疫。
凡东次二经之首，自空桑之山至于䃌山，凡十七山，六千六百四十里。其神状皆兽身人面载觡。其祠：毛用一鸡祈，婴用一壁瘗。
又东次三经之首，曰尸胡之山，北望（歹羊）山，其上多金玉，其下多棘。有兽焉，其状如麋而鱼目，名曰妴胡，其鸣自詨。
又南水行七百里，曰诸钅句之山，无草木，多沙石。是山也，广员百里，多寐鱼。
又南水行七百里，曰中父之山，无草木，多沙。
又东水行千里，曰胡射之山，无草木，多沙石。
又南水行七百里，曰孟子之山，其木多梓桐，多桃李，其草多菌浦，其兽多麋鹿。是山也，广员百里。其上有水出焉，名曰碧阳，其中多鳣鲔。
又南水行五百里，曰流沙，行五百里，有山焉，曰跂踵之山，广员二百里，无草木，有大蛇，其上多玉。有水焉，广员四十里皆涌，其名曰深泽，其中多大龟。有鱼焉，其状如鲤。而六足鸟尾，名曰鮯鮯之鱼，其名自詨。
又南水行九百里，曰踇隅之山，其上多草木，多金玉，多赭。有兽焉，其状如牛而马尾，名曰精精，其鸣自詨。
又南水行五百里，流沙三百里，至于无皋之山，南望幼海，东望囗木，无草木，多风。是山也，广员百里。
凡东次三经之首，自尸胡之山至于无皋之山，凡九山，六千九百里。其神状皆人身而羊角。其祠：用一牡羊，米用黍。是神也，见则风雨水为败。
又东次四经之首，曰北号之山，临于北海。有木焉，其状如杨，赤华，其实如枣而无核，其味酸甘，食之不疟。食水出焉，而东北流注于海。有兽焉，其状如狼，赤首鼠目，其音如豚，名曰猲狙，是食人。有鸟焉，其状如鸡而白首，鼠足而虎爪，其名曰鬿誉亦食人。
又南三百里，曰旄山，无草木。苍体之水出焉，而西浪注于展水，其中多鱃鱼，其状如鲤而大首，食者不疣。
又南三百二十里，曰东始之山，上多苍玉。有木焉，其状如杨而赤理，其汁如血，不实，其名曰芑，可以服马，泚水出焉，而东北流注于海，其中多美贝，多茈鱼，其状如鲋，一首而十身，其臭如蘪芜食之不？费。
又东南三百里，曰女烝之山，其上无草木，石膏水出焉，而西流注于鬲水，其中多薄鱼，其状如鳣鱼而一目，其音如欧，见则天下大旱。又东南二百里，曰钦山，多金玉而无石。师水出焉，而北流注于皋泽，其中多鱃鱼，多文贝。有兽焉，其状如豚而有牙，其名曰当康，其鸣自詨，见则天下大穰。
又东南二百里，曰钦山。多金玉而无石。师水出焉，而北流注于皋泽，其中多鱃鱼，多文贝。有兽焉，其状如豚而有牙，其名当康，其鸣自叫，见则天下大穰。
又东南二百里，曰子桐之山。子桐之水出焉，而西流注于余如之泽。其中多骨鱼，其状如鱼而鸟翼，出入有光。其音如鸳鸯，见则天下大旱。
又东北二百里，曰剡山，多金玉。有兽焉，其状如彘而人面。黄身而赤尾，其名曰合窳，其音如婴儿，是兽也，食人，亦食虫蛇，见则天下大水。
又东北二百里，曰太山，上多金玉桢木。有兽焉，其状如牜而白首，一目而蛇尾，其名曰蜚，行水则竭，行草则死，见则天下大疫，钩水出焉，而北流注于劳水，其中多鱃鱼。
凡东次四经之首，自北号之山至于太山，凡八山，一千七百二十里。
右东经之山志，凡四十六山，万八千八百六十里。', '《山海经·东山经》是创作于战国时期的一篇散文，出自《山海经》，作者不详。', '', '（注释：■为打不出来的字）
东方第一列山系之首座山，叫做樕■山，北面与乾昧山相邻。食水从这座山发源，然后向东北流入大海。水中有很多鳙鳙鱼，形状像犁牛，发出的声音如同猪叫。再往南三百里，是座藟山，山上有玉，山下有金。湖水从这座山发源，向东流入食水，水中有很多蝌蚪。再往南三百里，是座栒状山，山上有丰富的金属矿物和玉石，山下有丰富的青石碧玉。山中有一种野兽，形状像一般的狗，却长着六只脚，名称是从从，它发出的叫声便是自身名称的读音。山中有一种禽鸟，形状像普通的鸡却长着老鼠一样的尾巴，名称是■鼠，在哪个地方出现那里就会有大旱灾。■水从这座山发源，然后向北流入湖水。水中有很多箴鱼，形状像儵鱼，嘴巴像长针，人吃了它的肉就不会染上瘟疫病。再往南三百里，是座勃亝山，没有花草树木，也没有水。再往南三百里，是座番条山，没有花草树木，到处是沙子。减水从这座山发源，向北流入大海，水中有很多鳡鱼。再往南四百里，是座姑儿山，山上有茂密的漆树，山下有茂密的桑树、柘树。姑儿水从这座山发源，向北流入大海，水中有很多鳡鱼再往南四百里，是座高氏山，山上盛产玉石，山下盛产箴石。诸绳水从这座山发源，向东流入湖泽，水中有许多金属矿物和玉石再往南三百里，是座岳山，山上有茂密的桑树，山下有茂密的臭椿树。泺水从这座山发源，向东流入湖泽，水中有许多金属矿物和玉石。再往南三百里，是座豺山，山上不生长花草树木，山下到处流水，水中有很多堪鱼。山中有一种野兽，形状像猿猴却长着一身猪毛，发出的声音如同人呼叫，一出现而天下就会发生水灾。
再往南三百里，是座独山，山上有丰富的金属矿物和玉石，山下多的是美观漂亮的石头。未涂水从这座山发源，然后向东南流入沔水，水中有很多，形状与黄蛇相似，长着鱼一样的鳍，出入水中时闪闪发光，在哪个地方出现那里就会有大旱灾。再往南三百里，是座泰山，山上盛产玉，山下盛产金。山中有一种野兽，形状与一般的猪相似而体内却有珠子，名称是狪狪，它发出的叫声便是自身名称的读音。环水从这座山发源，向东流入汶水，水中有很多水晶石。再往南三百里，是座竹山，座落于汶水边上，这座山没有花草树木，到处是瑶、碧一类的玉石。激水从竹山发源，然后向东南流入娶檀水，水中有很多紫色螺。总计东方第一列山系之首尾，自樕山起到竹山止，一共十二座山，途经三千六百里。诸山山神的形貌都是人的身子龙的头。祭祀山神：在毛物中用一只狗作为祭品来祭祀，祷告时要用鱼。
东方第二列山系之首座山，叫做空桑山，北面临近食水，在山上向东可以望见沮吴，向南可以望见沙陵，向西可以望见湣泽。山中有一种野兽，形状像普通的牛却有老虎一样的斑纹，发出的声音如同人在呻吟，名称是軨軨，它发出的叫声便是自身名称的读音，一出现而天下就会发生水灾。再往南六百里，是座曹夕山，山下到处是构树，却没有水流，还有许多禽鸟野兽。
再往西南四百里，是座峄皋山，山上有丰富的金属矿物和玉石，山下有丰富的白垩土。峄皋水从这座山发源，向东流入激女水，水中有很多大蛤和小蚌。再往南行五百里水路，经过三百里流沙，便到了葛山的尾端，这里没有花草树木，到处是粗细磨石再往南三百八十里，就是葛山的首端，这里没有花草树木。澧水从此发源，向东流入余泽，水中有很多珠蟞鱼，形状像动物的一叶肺器官却有四只眼睛，还有六只脚而且能吐珠子，这种珠蟞鱼的肉味是酸中带甜，人吃了它的肉就不会染上瘟疫病。
再往南三百八十里，是座余峨山，山上有茂密的梓树和楠木树，山下有茂密的牡荆树和枸杞树。杂余水从这座山发源，向东流入黄水。山中有一种野兽，形状像一般的兔子却是鸟的嘴，鹞鹰的眼睛和蛇的尾巴，一看见人就躺下装死，名称是犰狳，发出的叫声便是它自身名称的读音，一出现就会有螽斯蝗虫出现而为害庄稼。再往南三百里，是座杜父山，不生长花草树木，到处流水。再往南三百里，是座耿山，没有花草树木，到处是水晶石，还有很多大蛇。山中有一种野兽，形状像狐狸却长着鱼鳍，名称是朱獳，发出的叫声便是它自身名称的读音，在哪个国家出现而那个国家里就会有恐怖的事发生。再往南三百里，是座卢其山，不生长花草树木，到处是沙子石头。沙水从这座山发源，向南流入涔水，水中有很多鹈鹕鸟，形状像一般的鸳鸯却长着人一样的脚，发出的叫声便是它自身名称的读音，在哪个国家出现那个国家里就会有水土工程的劳役。再往南三百八十里，是座姑射山，没有花草树木，到处流水。
再往南行三百里水路，经过一百里流沙，是座北姑射山，没有花草树木，到处是石头。再往南三百里，是座南姑射山，没有花草树木，到处流水。再往南三百里，是座碧山，没有花草树木，有许多大蛇。还盛产碧玉、水晶石。再往南五百里，是座缑氏山，不生长花草树木，有丰富的金属矿物和玉石。原水从这座山发源，向东流入沙泽。再往南三百里，是座姑逢山，没有花草树木，有丰富的金属矿物和玉石。山中有一种野兽，形状像一般的狐狸却有翅膀，发出的声音如同大雁鸣叫，名称是獙獙，一出现而天下就会发生大旱灾。再往南五百里，是座凫丽山，山上有丰富的金属矿物和玉石，山下盛产箴石。山中有一种野兽，形状像一般的狐狸，却有九条尾巴、九个脑袋、虎一样的爪子，名称是侄，发出的声音如同婴儿啼哭，是能吃人的。再往南五百里，是座山，南面临近水，从山上向东可以望见湖泽。山中有一种野兽，形状像普通的马，却长着羊一样的眼睛、四只角、牛一样的尾巴，发出的声音如同狗叫，名称是峳峳，在哪个国家出现那个国家里就会有很多奸猾的政客。山中还有一种禽鸟，形状像野鸭子却长着老鼠一样的尾巴，擅长攀登树木，名称是絜钩，在哪个国家出现那个国家里就多次发生瘟疫病。总计东方第二列山系之首尾，自空桑山起到山止，一共十七座山，途经六千六百四十里。诸山山神的形貌都是野兽的身子人的面孔而且头上戴着觡角。祭祀山神：在毛物中用一只鸡献祭，在祀神的玉器中用一块玉璧献祭后埋入地下。
东方第三列山系之首座山，叫做尸胡山，从山上向北可以望见山，山上有丰富的金属矿物和玉石，山下有茂密的酸枣树。山中有一种野兽，形状像麋鹿却长着鱼一样的眼睛，名称是妴胡，它发出的叫声便是自身名称的读音。再往南行八百里水路，是座岐山，山中的树木大多是桃树和李树，而野兽大多是老虎再往南行五百里水路，是座诸钩山，没有花草树木，到处是沙子石头。这座山，方圆一百里，有很多寐鱼。再往南行七百里水路，是座中父山，没有花草树木，到处是沙子。再往东行一千里水路，是座胡射山，没有花草树木，到处是沙子石头。再往南行七百里水路，是座孟子山，山中的树木大多是梓树和桐树，还生长着茂密的桃树和李树，山中的草大多是菌蒲，山中的野兽大多是麋、鹿。这座山，方圆一百里。有条河水从山上流出，名称是碧阳，水中生长着很多鳣鱼和鲔鱼。
再往南行五百里水路，经过流沙五百里，有一座山，叫做踵踵山，方圆二百里，没有花草树木，有大蛇，山上有丰富的玉石。这里有一水潭，方圆四十里都在喷涌泉水，名称是深泽，水中有很多蠵龟。水中还生长着一种鱼，形状像一般的鲤鱼，却有六只脚和鸟一样的尾巴，名称是鮯鮯鱼，发出的叫声便是它自身名称的读音。再往南行九百里水路，是座踇隅山，山上有茂密的花草树木，有丰富的金属矿物和玉石，还有许多赭石。山中有一种野兽，形状像一般的牛却长着马一样的尾巴，名称是精精，它发出的叫声便是自身名称的读音。再往南行五百里水路，经过三百里流沙，便到了无皋山，从山上向南可以望见幼海，向东可以望见榑木，这里不生长花草树木，到处刮大风。这座山，方圆一百里。总计东方第三列山系之首尾，自尸胡山起到无皋山止，一共九座山，途经六千九百里。诸山山神的形貌都是人的身子却长着羊角。祭祀山神：在毛物中用一只公羊作祭品，祀神的米用黄米。这些山神，一出现就会起大风、下大雨、发大水而损坏庄稼。
东方第四列山系之首座山，叫做北号山，屹立在北海边上。山中有一种树木，形状像普通的杨树，开红色花朵，果实与枣子相似但没有核，味道是酸中带甜，吃了它就能使人不患上疟疾病。食水从这座山发源，然后向东北流入大海。山中有一种野兽，形状像狼，长着红脑袋和老鼠一样的眼睛，发出的声音如同小猪叫，名称是獦狚，是能吃人的。山中还有一种禽鸟，形状像普通的鸡却长着白脑袋，老鼠一样的脚足和老虎一样的爪子，名称是鬿雀，也是能吃人的。
再往南三百里，是座旄山，没有花草树木。苍体水从这座山发源，然后向西流入展水，水中生长着很多鱃鱼，形状像鲤鱼而头长得很大，吃了它的肉就能使人皮肤上不生瘊子。再往南三百二十里，是座东始山，山上多出产苍玉。山中有一种树木，形状像一般的杨树却有红色纹理，树干中的液汁与血相似，不结果实，名称是芑，把液汁涂在马身上就可使马驯服。泚水从这座山发源，然后向东北流入大海，水中有许多美丽的贝，还有很多茈鱼，形状像一般的鲫鱼，却长着一个脑袋而十个身子，它的气味与蘼芜草相似，人吃了它就不放屁。
再往东南三百里，是座女烝山，山上没有花草树木。石膏水从这座山发源，然后向西流入鬲水，水中有很多薄鱼，形状像一般的鳝鱼却长着一只眼睛，发出的声音如同人在呕吐，一出现而天下就会发生大旱灾。再往东南二百里，是座钦山，山中有丰富的金属矿物和玉石却没有石头。师水从这座山发源，然后向北流入皋泽，水中有很多鱃鱼，还有很多色彩斑斓的贝。山中有一种野兽，形状像小猪却长着大獠牙，名称是当康，它发出的叫声就是自身名称的读音，一出现而天下就要大丰收。再往东南二百里，是座子桐山。子桐水从这座山发源，然后向西流入余如泽。水中生长着很多鱼，形状与一般的鱼相似却长着禽鸟翅膀，出入水中时闪闪发光，发出的声音如同鸳鸯鸣叫，一出现而天下就会发生大旱灾。再往东北二百里，是座剡山，有丰富的金属矿物和玉石。山中有一种野兽，形状像猪却是人的面孔，黄色的身子上长着红色尾巴，名称是合窳，发出的声音如同婴儿啼哭。这种合窳兽，是吃人的，也吃虫和蛇，一出现而天下就会发生水灾。再往东二百里，是座太山，山上有丰富的金属矿物和玉石、茂密的女桢树。山中有一种野兽，形状像一般的牛却是白脑袋，长着一只眼睛和蛇一样的尾巴，名称是蜚，它行经有水的地方水就干涸，行经有草的地方草就枯死，一出现而天下就会发生大瘟疫。钩水从这座山发源，然后向北流入劳水，水中有很多鱃鱼。
总计东方第四列山系之首尾，自北号山起到太山止，一共八座山，途经一千七百二十里。
以上是东方经历之山的记录，总共四十六座山，途径一万八千八百六十里。', NULL, '', 'indent', 1522504330, '5abf22039f545433515b0b01', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636733, '圆觉经 · 序分', NULL, 6, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', '', '', '如是我闻。一时，婆伽婆，入于神通大光明藏，三昧正受，一切如来光严住持，是诸众生清净觉地，身心寂灭，平等本际，圆满十方，不二随顺，于不二境，现诸净土。
与大菩萨摩诃萨十万人俱。其名曰文殊师利菩萨，普贤菩萨，普眼菩萨，金刚藏菩萨，弥勒菩萨，清净慧菩萨，威德自在菩萨，辩音菩萨，净诸业障菩萨，普觉菩萨，圆觉菩萨，贤善首菩萨等而为上首，与诸眷属皆入三昧，同住如来平等法会。', '《圆觉经》是《大方广圆觉修多罗了义经》的简称，又作《大方广圆觉经》、《圆觉修多罗了义经》、《圆觉了义经》，佛教大乘之经典。内容是佛为文殊、普贤等十二位菩萨宣说如来圆觉的妙理和观行方法，全经分作序、正、流通三分，是唐、宋、明以来教（贤首、天台）、禅各宗盛行讲习的经典。
此为本经的“序分”部分，表明当时佛说法时证入的境界，以及参与法会的大众，并强调经中所载法门确实为佛陀所说，内容真实可信。', '如是我闻：即我闻如是，意为我听到佛这样说。如是，指这部经文。我，阿难自称。闻，从佛陀处亲闻。此语出于佛涅槃前。当时，以“多闻第一”著称的阿难问佛：“一切经首置何字？”佛回答：“一切经首置‘如是我闻’等言。”
婆伽婆：梵语音译。也称“婆伽梵”、“薄伽梵”，意译为“世尊”，为佛的尊号。有自在、炽盛、端严、名称、吉祥、尊贵六种含义。
神通大光明藏：即指佛说法的处所，不是指具体的外在场所，而是指自性境界。神，则莫测。通，则无碍。大光明，即智慧。藏，即一切法所依之平等真如法性体。
三昧：梵语。又译“三摩地”，意译为“定”或“正定”。即摒除杂念，心不散乱，专注于一境。正受：是与“三昧”相应的禅定。
光严：光明庄严。住持：久住护持佛法。
清净觉地：正觉的境界。因正觉之体离染污，故称“清净。
寂灭：即指涅槃，是没有烦恼和生死的境界。
本际：根本究竟的边际，即绝对平等的理体。此指涅槃而言。
圆满：周遍充足，无所缺减。
不二：又作“无二”、“离两边”，指对一切现象应无分别，或超越各种区别。随顺：随从他人之意而不拂逆。
净土：指佛所居的处所，全称“清净土”、“清净国土”、“清净佛刹”，又作“净刹”、“净世界”、“佛国”。与此相对，世俗众生居住之所，有烦恼污秽，故称“秽土”、“秽国”。
大菩萨摩诃（hē）萨：大菩萨即摩诃萨，摩诃萨为梵语音译，又称“大有情”、“大众生”，此大众生的愿大、行大、度众生大，在世间诸众生中为最上。
文殊师利菩萨：文殊，是“妙”的意思；师利，是“德”或“吉的意思。文殊师利即妙吉祥的意思。该菩萨以大智著称，与普贤菩萨常侍于释迦如来左右。
普贤菩萨：是具足无量行愿、普现于一切佛刹的大乘圣者。
普眼菩萨：因其能普观一切众生故称。
金刚藏菩萨：此菩萨能以智慧破除愚暗，表现为忿怒的形象，或持金刚杵以伏恶魔，也称“金刚藏王”。
弥勒菩萨：弥勒为梵语音译，意译为“慈氏”。依《弥勒上生经》、《弥勒下生经》所载，弥勒出生于婆罗门家庭，后成为佛的弟子，先佛入灭，以菩萨身为天人说法，住于兜率天。据传此菩萨因发心不食肉，故名为“慈氏”。
清净慧菩萨：此菩萨得自在，同佛境界，从法而生，故称“法生”，即从自性清净之法而生。
威德自在菩萨：可畏为威，可爱为德，进退无碍、心离烦恼的系缚为自在。
辩音菩萨：能以声音做佛事而利益众生。
净诸业障菩萨：能为众生除去各自所作种种恶业。
普觉菩萨：能够普遍地觉悟众生。
圆觉菩萨：显示圆满的灵觉，对世间一切事理，无不底了知其事实真相。
贤善首菩萨：贤而行善者，又同前十一位菩萨共居十万大菩萨眷属之首，故名“贤善首菩萨”。上首：大众中之主位，称为“上首”。或举其中一人为上首，或举多人为上首。
眷属：指亲近、顺从者。眷为亲爱，属为隶属。
法会：讲说佛法及供佛施僧等所举行的集会。', '我听佛这样说的。那时，佛得入神通大光明藏，心念大定，一切佛都久住此光明庄严境界，这也是所有众生能够真正清净觉悟的本性境界。身心无生无灭，寂静无为，涅槃平等，遍足十方，超越了分别，随顺迎合了涅槃正道。在这个境界中，可以显现出佛国净土。
佛陀当时与十万大菩萨在一起。名为文殊师利菩萨、普贤菩萨、普眼菩萨、金刚藏菩萨、弥勒菩萨、清净慧菩萨、威德自在菩萨、辩音菩萨、净诸业障菩萨、普觉菩萨、圆觉菩萨、贤善首菩萨的十二大士坐在上席，并率各自眷属一起入于心定安住的境界，他们和佛一样安住在此净土法会。', NULL, '北都藏海寺道诠法师《疏》又云：羯湿弥罗三藏法师佛陀多罗，长寿二年（693）龙集癸巳，持于梵本方至神都，于白马寺翻译，四月八日毕。其度语、笔受、证义诸德，具如别录。不知此说本约何文？素承此人学广道高，不合孟浪。（中略）然入藏诸经，或失译主，或无年代者亦多，古来诸德皆但以所诠义宗定其真伪矣。’
同《疏钞》卷四之上又说（卍续14•563下）：‘言龙集者，有释云高宗大帝，（中略）此说恐谬：（中略）长寿年是则天之代，然今亦未委其指的也，待更寻检。疏具如别录者，复不知是何图录，悉待寻勘。’可见古德对此经的翻译记载多有所疑，但都相信其真诠不谬，而并致其笃信之忱。
此经的内容，是佛为文殊、普贤等十二位菩萨宣说如来圆觉的妙理和观行方法。全经一般分作序、正、流通三分。
初，序分，叙述佛入于神通大光明藏三昧，诸佛众生清净寂灭平等圆满不二所现净土，有文殊师利等十二大菩萨为上首的十万大菩萨众，皆入此三昧，住于如来平等法会。
次，正宗分，叙佛因文殊师利等十二大菩萨次第请问，而依次宣说圆觉的义理和观行，即分十二章，每章先以长行问答说法，后以偈颂重宣其义。其中：
（1）文殊章：是一经的宗趣所在。宣说有大陀罗尼──圆觉法门，流出一切清净真如、菩提、涅槃及波罗蜜。显示佛菩萨的因行果相都不外乎修证本有的圆觉道理。以下各章即说其观行。
（2）普贤章：说示圆觉境界的修行方便，远离一切幻妄境界，知幻即离，离幻即觉。
（3）普眼章：说示修习圆觉，应当正念，远离诸幻，先依奢摩他行，坚持净戒，宴坐静观身心幻垢、人法二空，乃至幻灭垢尽，一切清净，觉性平等不动。
（4）金刚藏章：说示圆觉本性平等不坏，众生有思惟心，不能测度如来境界，故应先断无始轮回根本。
（5）弥勒章：说示爱欲为轮回根本，一切众生由本贪欲，发挥无明，显出五性差别，依事理二障而现深浅。应发大愿，求善知识，渐断诸障，证大圆觉。
（6）清净慧章：说示圆觉自性本无取证，但于除灭一切幻化修证位中，有凡夫随顺觉性、菩萨未入地者随顺觉性、菩萨已入地者随顺觉性、如来随顺觉性诸位差别。
（7）威德自在章：说示修行的方便，依着众生的根性而有三种差别：奢摩他，三摩钵提，禅那。此三法门若得圆证，即成圆觉。
（8）辩音章：说示单修奢摩他或三摩钵提或禅那一法，乃至或先或后齐修二法乃至三法等二十五种清净定轮的修行方法。
（9）净诸业障章：说示觉性本净，但由众生从无始以来，妄执有我、人、众生、寿命，认四颠倒为实我体，妄生嗔爱，生妄业道，不能入于清净觉海。
（10）普觉章：说示欲求圆觉，应除作、任、止、灭四种病相，以及去除诸病，求证圆觉之道。
（11）圆觉章：说示修行大圆觉者，长期、中期、下期三种安居的方法，以及修习奢摩他、三摩钵提、禅那三观等方便。
（12）贤善首章：说示此经名《大方广圆觉陀罗尼》，亦名《修多罗了义》等五名，并信闻受持此经的功德利益等。', 'indent', 1522076678, '5ab89b80ac502e57c95803dc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636734, '减字木兰花', NULL, 10, 395, 0, 1, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', 'https://baike.baidu.com/item/%E5%87%8F%E5%AD%97%E6%9C%A8%E5%85%B0%E8%8A%B1%C2%B7%E7%9B%B8%E9%80%A2%E4%B8%8D%E8%AF%AD/10603544?fr=aladdin', '', '相逢不语，一朵芙蓉著秋雨。小晕红潮，斜溜鬟心只凤翘。
待将低唤，直为凝情恐人见。欲诉幽怀，转过回阑叩玉钗。', '《减字木兰花·相逢不语》是清代词人纳兰性德的作品。这首词描写容若和他的青梅竹马的表妹在皇宫里见面的情景。词的上片侧重静态的刻画，写出了少女外貌的美丽动人。下片侧重于动态的摩画，将其一刹那间复杂娇羞的心理表现的惟妙惟肖。全篇情景俱到，形神俱佳，生动感人，是词人爱情词的艺术高峰之一。', '芙蓉”又称为“荷”、“莲”。象征义：一是取荷美好形象营造一种雅致的景象，或宁静或欢愉；二是取败荷的形象营造一种衰败意境，或对逝去光阴叹惋，或对生活环境破败惋惜；三是取“芙蓉出污泥而不染”的品质，托物言志，寄寓自己不愿同流合污的高尚节操。这里则刻画了一位如荷般美丽、和谐、恬静的女子。
小晕红潮：谓脸色微微泛起了红晕。
鬟（huán），总发也。
凤翘：古代女子凤形的头饰。
直为句：意思是由于害怕别人发现自己的多情。　直为，只是由于……。　凝情，深细而浓烈的感情。
回阑：曲折的栏干。阑，同“栏”。', '相逢时你默默不语，像一朵芙蓉，在秋雨中轻颤。容颜娇羞而红润，凤翘斜插在你的鬟间。
等到想要低声唤你，又怕深情凝望，叫别人看见。想要一诉离愁，可你已转过身去，只能拔下玉钗在回阑轻叩。', NULL, '顾贞观评价说：“吾友容若其门第才华，直越晏小山之上。”从风格上看，这首词写得相当婉约缠绵，是爱情词的上品。', 'indent', 1522080338, '5ab8a9d1756571108cef2291', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636745, '正宫 · 黑漆弩 · 游金山寺（并序）', NULL, 0, 485, 0, 1, '王恽', NULL, 10639, '5858e5b7b123db00658d7784', '元', 'qu', '曲', 'https://baike.baidu.com/item/%E9%BB%91%E6%BC%86%E5%BC%A9%C2%B7%E6%B8%B8%E9%87%91%E5%B1%B1%E5%AF%BA/6457309?fr=aladdin', '', '邻曲子严伯昌，尝以《黑漆弩》侑酒。省郎仲先谓余曰：“词虽佳，曲名似未雅。若就以‘江南烟雨’目之何如？”予曰：“昔东坡作《念奴》曲，后人爱之，易其名为《酹江月》，其谁曰不然？”仲先因请余效颦。遂追赋《游金山寺》一阕，倚其声而歌之。昔汉儒家畜声伎，唐人例有音学。而今之乐府，用力多而难为工，纵使有成，未免笔墨劝淫为侠耳。渠辈年少气锐，渊源正学，不致费日力于此也。其词曰：
苍波万顷孤岑矗，是一片水面上天竺。金鳌头满咽三杯，吸尽江山浓绿。蛟龙虑恐下燃犀，风起浪翻如屋。任夕阳归棹纵横，待偿我平生不足。', '《黑漆弩·游金山寺》是王恽的散曲作品。这支小令上片扣“金山寺”，下片扣“游”，以风物的雄丽宕开心胸，又以快意的壮游反衬金山寺的非凡魅力。曲前原有序，表明了他写词曲不蹈袭前人“笔墨劝淫”的狭路的观点，他主张学习苏东坡《念奴娇》的词风。本曲写金山寺风光，立意新奇，构思巧妙，气象豪迈，富有浪漫主义色彩，颇类东坡风格。', '金山寺：始建于东晋，初名泽心寺，至唐起称金山寺。在镇江西北长江中的金山上（金山至清初始与南岸相连）。
邻曲：邻人。
侑酒：为饮酒助兴。
省郎：中书省的郎官（郎中或员外郎）。
江南烟雨：元白贲《鹦鹉曲》（即《黑漆弩》）有“睡煞江南烟雨”的名句（参见本书所选该曲），故仲先有径取“江南烟雨”为曲牌名代称的设想。
《念奴》曲：指苏轼名作《念奴娇·赤壁怀古》词，末句为“一尊还酹江月”，故后人亦以《酹江月》为《念奴娇》词牌的别名。
效颦：西施病心而颦（皱眉），里中丑妇模仿，反增其丑，事见《庄子》。这里是自谦之词。
侠：称雄。
渠辈：他们，指严伯昌、仲先等人。
岑：底小而高耸的山。
天竺：寺名，在杭州灵隐山南。这里指雄伟的佛寺。
金鳌头：指金山。金山一名金鳌山。
燃犀：晋代温峤点燃犀角，投入牛渚矶的深水中，照见底下有许多奇形怪状的水中生物，因受扰而不安。', '我的邻居严伯昌，曾经唱《黑漆弩》这支曲子来劝酒。中书省郎中仲先对我说：“词虽然好，曲牌子名称似乎欠文雅，不妨用‘江南烟雨’来称呼它，如何？”我说：“从前苏东坡作《念奴娇》，后人喜欢它，将词名改为《酹江月》，这谁说不可以。”仲先请我给《黑漆弩》作一篇词，于是就追写了这首《游金山寺》，按照这个曲牌子的音调来演唱。先前汉朝士大夫家里专门养着善唱的歌妓，唐朝富贵人家也讲究学习音乐。而现今大家作散曲，虽然用力不少，但很难达到精妙的境地，即使作品甚多，但有些笔墨化在色情的渲染上，以为那是曲的正路。这些作者年轻气盛，正在继承圣贤的学问，并不把写曲子当成正经事，不在这方面耗费气力。
在苍茫辽阔的长江中孤零零地屹立着金山，金山上有庄严的寺庙，那是水面上的一处佛教圣境！站在金鳌峰满满地饮了三杯，那饮下的似乎不是酒，而是吸尽了江山浓浓的春色。江水深处潜伏的蛟龙，惧怕有人点燃镇凶避邪的犀角，于是掀起房屋般的巨浪。夕阳西下，游人纷纷划桨而归，让他们离开吧，我依然要在江中流连，补偿我人生阅历的不足。', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2755914587d02f58a23", "shortContent": "元人作〔黑漆弩〕曲最著名的是白贲（字无咎），王恽此曲序言中说他的邻居严伯昌常使人唱〔黑漆弩〕以劝酒，就是指唱白贲之曲，白曲第四句作“睡煞江南烟雨”，所以王恽的友人（仲先）建议把〔黑漆弩〕改称为“江南烟雨”。王恽以苏轼作〔念奴娇〕词，后人因词中有“一樽还酹江月”，改称作〔酹江月〕为例，同意他朋友的意见。他们的讨论还促使王恽写作此曲。作曲时间不明，但大致可断定在大德六年（1302）以前，因据冯子振的〔...", "authors": ["邓绍基"], "pressName": "上海辞书出版社"}, {"bookId": "62de2d8a3bba5677642ac2d1", "bookTitle": "元曲三百首", "articleId": "630593d130a1d3054c75036b", "shortContent": "元人作【黑漆弩】曲最著名的是白贲（字无咎），王恽此曲序言中说他的邻居严伯昌常使人唱【黑漆弩】以劝酒，就是指唱白贲之曲，白曲第四句作“睡煞江南烟雨”，所以王恽的友人（仲先）建议把【黑漆弩】改称为“江南烟雨”。王恽以苏轼作〔念奴娇〕词，后人因末句“一尊还酹江月”而改词调名为〔酹江月〕为例，同意朋友的意见。他们的讨论还促使王恽写作此曲。作曲时间不明，但大致可断定在大德六年（1302）以前，因据冯子振的【...", "authors": ["邓绍基"], "pressName": "上海辞书出版社"}, {"bookId": "6277bbb9f716b7243c7bdff3", "bookTitle": "元曲鉴赏辞典", "articleId": "63126ecc9761253910e90302", "shortContent": "这篇序言记述了作者创作《黑漆弩》的动因以及创作散曲并非易事。为了便于读者理解序意，兹将此序译成现代汉语：\n邻人的儿子严昌伯，曾经用《黑漆弩》劝酒。中书省郎中仲先对我说：“白贲的《黑漆弩》词虽好，但曲名不高雅，如果就用‘江南烟雨’作为曲名，怎么样呢？”我说：“往日苏轼作《念奴娇·赤壁怀古》词，后人非常喜爱它，改词牌名为《酹江月》，谁说不可以呢？”仲先请我模仿白贲曲，于是随之写了《游金山寺》这首小令，...", "authors": ["杨合鸣"], "pressName": "崇文书局"}]', '', 'indent', 1522081570, '5ab8aea1ee920a396f38396a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636747, '双调 · 蟾宫曲', NULL, 9, 101, 0, 3, '卢挚', NULL, 10372, '57ba86ad79bc440063a1ca7d', '元', 'qu', '曲', 'https://baike.baidu.com/item/%E8%9F%BE%E5%AE%AB%E6%9B%B2%C2%B7%E6%B2%99%E4%B8%89%E4%BC%B4%E5%93%A5%E6%9D%A5%E5%97%8F/7142159?fr=aladdin', '', '沙三伴哥来嗏！两腿青泥，只为捞虾。太公庄上，杨柳阴中，磕破西瓜。小二哥昔涎剌塔，碌轴上渰着个琵琶。看荞麦开花，绿豆生芽。无是无非，快活煞庄家。', '该曲有人有景，通过捕捉描写农村忙里偷闲的闲适生活片段，歌咏了劳动人民摆脱人世是非纷扰的淳朴愉悦，表达了作者对官场钩心斗角竞争的反感和对隐居平和生活的向往。该曲是一首非常具有口语特色和元曲风味的本色作品。', '沙三伴哥：及下文的“小二哥”，都是元曲中常用的农村青壮年人名。
嗏（chā）：语尾助词，略同于“呀”或“着呀”。
太公：元曲中对农村大户人家老主人的习称。
昔涎剌（là）塔：元人方言，垂涎三尺的样子。
碌（lù）轴：即碌碡，石碾子，碾谷及平整场地用的农具。
渰（yǎn）：此同“弇”，合覆，这里是背朝上合扑之意。
庄家：农民。', '来了这沙三、伴哥两个田舍郎，因为下水捞虾，青泥的痕迹还留在两腿上。他们进了太公的田庄，赶到杨柳树下歇凉，取出带来的西瓜砸开就尝。一旁的小二哥无缘分享，馋得口水滴答流淌，背朝天趴在碌碡上，活像一面琵琶扣放。放眼四望，荞麦花雪白白开，豆苗儿碧油油长。乡村生活没有是非竞争，一切都平静如常，真是一派农家乐的景象。', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2750f8fda556505ff80", "shortContent": "这首曲所写，是田家生活的一个剪影：两位农家少年，一个叫沙三，一个叫伴哥，刚刚从河里捞虾回来，两条腿上还沾满了青泥。他们来到了太公的庄上，在绿阴掩映的杨柳树下，撞开西瓜，大吃一顿。另外一位少年小二哥，因为吃不到西瓜，躺在碌碡上，口水直流。附近，是一望碧绿的田野。\n描写人物的生动，是这首曲的最大特点。三个人物，可以分为互有联系的两组：一组是两个捞虾的少年，作者只描写了他们的“两腿青泥”和大吃西瓜，这是...", "authors": ["洪柏昭"], "pressName": "上海辞书出版社"}, {"bookId": "62de2d8a3bba5677642ac2d1", "bookTitle": "元曲三百首", "articleId": "630593d1f6542516c6de8820", "shortContent": "这首曲所写，是田家生活的一个剪影：两位农家少年，一个叫沙三，一个叫伴哥，刚刚从河里捞虾回来，两条腿上还沾满了青泥。他们来到了太公的庄上，在绿荫掩映的杨柳树下，撞开西瓜，大吃一顿。另外一位少年小二哥，因为吃不到西瓜，躺在碌碡上，口水直流。附近，是一望碧绿的田野。\n\n描写人物的生动，是这首曲的最大特点。三个人物，可以分为互有联系的两组：一组是两个捞虾的少年，作者只描写了他们的“两腿青泥”和大吃西瓜，这...", "authors": ["洪柏昭"], "pressName": "上海辞书出版社"}]', '当代戏曲史家蒋星煜：作者真觉得与险恶的官场相比，这儿就是桃花源了。厌倦机心，才会深感“无是无非，快活煞庄家”。', 'indent', 1522081950, '5ab8b01c17d0096887875d83', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636749, '双调 · 蟾宫曲', NULL, 0, 2, 0, 1, '庾天锡', NULL, 36900, '5ab8b26c44d90418a23758cc', '元', 'qu', '曲', 'https://baike.baidu.com/item/%E8%9F%BE%E5%AE%AB%E6%9B%B2%C2%B7%E7%8E%AF%E6%BB%81%E7%A7%80%E5%88%97%E8%AF%B8%E5%B3%B0/731978?fr=aladdin', '', '环滁秀列诸峰。山有名泉，泻出其中。泉上危亭，僧仙好事，缔构成功。四景朝暮不同。宴酣之乐无穷，酒饮千钟。能醉能文，太守欧翁。
滕王高阁江干。佩玉鸣鸾，歌舞阑珊。画栋朱帘，朝云暮雨，南浦西山。物换星移几番，阁中帝子应笑，独倚危栏。槛外长江，东注无还。', '《蟾宫曲·环滁秀列诸峰》是元代作家庾天锡的一首散曲。这首小令赋欧阳修的《醉翁亭记》事，有怀才不遇、借酒浇愁之意，作者在自己和欧阳修之间发现了身世经历的相似之处。', '庾天锡这首《蟾宫曲》乃隐括欧阳修《醉翁亭记》一文而成。
“环滁”句：此句概括了《醉翁亭记》“环滁皆山也，其西南诸峰，林壑尤美，望之蔚然而深秀者，琅琊也”五句。滁，今安徽滁州。
“山有”二句：此是“山行六七里，渐闻水声潺潺，而泻出于两峰之间者，酿泉也”四句的概括。
“泉上”三句：这是概括“峰回路转，有亭翼然，临于泉上者，醉翁亭也。作亭者谁，山之僧曰智仙也；名之者谁，太守自谓也”。
“四景”三句：这是概括“若夫日出而林霏开，云归而岩穴暝，晦明变化者，山间之朝暮也。野芳发而幽香，佳木秀而繁阴，风霜高洁，水落而石出者，山间之四时也。朝而往，暮而归，四时之景不同，而乐亦无穷也”一段。
“能醉”二句：这是概述“醉能同其乐，醒能述以文者，太守也。太守谓谁，庐陵欧阳修也”的语意。
这支曲是概括王勃《滕王阁》诗。
“滕王”句：这是删改了王勃诗第一句“滕王高阁临江渚”。
“佩玉”二句：这是“佩玉鸣鸾罢歌舞”一语的改写。佩玉鸣鸾，都是歌伎衣物上的妆饰品。鸾，响铃。阑珊，是形容歌舞盛况由繁华转向衰微。
“画栋”三句：这是“画栋朝飞南浦云，朱帘暮卷西山雨”一联的概括。画栋，涂有彩画的梁栋。这是写滕王殁后滕王阁的冷落情况。
“物换”句：这是改写了“物换星移几度秋”一句。
“阁中”二句：这是“阁中帝子今何在”句的点化。帝子，指滕王。危栏，高高的栏杆。
“槛外”二句：这是改写了“槛外长江空自流”一句。槛，栏杆。长江，这里指赣江。东注，向东奔流。
', '', '[{"bookId": "6277bbb9f716b7243c7bdff3", "bookTitle": "元曲鉴赏辞典", "articleId": "63126ed0c305cf0801816d00", "shortContent": "这首小令是对欧阳修《醉翁亭记》的改写。\n首先是环境描写。作者用三句话概括了原文九句的内容：“环滁皆山也，其西南诸峰，林壑尤美，望之蔚然深秀者，琅琊也。山行六七里，渐闻水声潺潺，而泻出于两峰之间者，酿泉也。”庾天锡略去了原文记游的特点，没有方位交代，没有游者行动，没有地名介绍，只求将景致呈现出来。“泉上危亭”的“危”字用得很妙，比原文“有亭翼然，临于泉上者”更显亭之居高临下的气势。接下来的两句，是说...", "authors": ["曾倩"], "pressName": "崇文书局"}]', '', 'indent', 1522082591, '5ab8b29e756571108cef5d57', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636755, '双调 · 折桂令', NULL, 0, 3, 0, 1, '鲜于必仁', NULL, 29227, '5858f6b961ff4b006cb93085', '宋', 'qu', '曲', 'https://baike.baidu.com/item/%E5%8F%8C%E8%B0%83%C2%B7%E6%8A%98%E6%A1%82%E4%BB%A4%C2%B7%E8%8A%A6%E6%B2%9F%E6%99%93%E6%9C%88/4279580?fr=aladdin', '', '【芦沟晓月】
出都门鞭影摇红，山色空蒙，林景玲珑。桥俯危波，车通运塞，栏倚长空。起宿霭千寻卧龙，掣流万云万丈垂虹，路杳疏钟，似蚁行人，如步蟾宫。
【西山晴雪】
玉嵯峨高耸神京，峭壁排银，叠石飞琼，地展雄藩天开图画，户判围屏。分曙色流云有影，冻晴光老树无声。醉眼空惊，樵子归来，蓑笠青青。', '', '这是作者《燕山八景》组曲，今选其二。
芦沟晓月：元代燕山（今北京地区）八景之一，地点在今北京市西南芦沟桥，桥为金大定（1161—1189年）时所建，跨永定河上。
“起宿霭千寻卧龙”二句：形容声沟桥姿态的雄伟美丽。
蟾宫：月宫，俗传月中有蟾蜍，故称月为蟾宫。
西山晴雪：元代燕山八景之一。西山在今北京市西北。
地展雄藩：意指西山为北京屏障。雄藩，雄伟的屏藩', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2882cee9a0c24ed9991", "shortContent": null, "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "62777f94f716b7243c7b102b", "bookTitle": "元曲三百首鉴赏辞典 ", "articleId": "63126efa7ccdb86c49f2904f", "shortContent": "“草茫茫秦汉陵阙”，开篇描绘出一幅雄浑苍凉的广阔图画。陵阙指帝王的坟墓。秦汉帝王的坟墓已经埋在茫茫草野之下，他们的赫赫功业也早已烟消云散了。这与李白《忆秦娥》“西风残照，汉家陵阙”，可谓同一机杼。作者生活在元末，凭吊秦汉遗迹，回顾前朝旧事，免不了有今之视昔，犹后之视今之感。如果执政者不能从秦汉兴亡的历史中汲取深刻经验和教训，那么只能重蹈前辙。苏轼称“人有悲欢离合，月有阴晴圆缺”（《水调歌头》），作...", "authors": ["陈鹏"], "pressName": "崇文书局"}, {"bookId": "62777f94f716b7243c7b102b", "bookTitle": "元曲三百首鉴赏辞典 ", "articleId": "63126f0bf2af4e09d55b65f5", "shortContent": "鲜于必仁的【双调·折桂令】是一组咏史之作，有七篇，共咏写了七个人物，分别是严光、诸葛亮、陶渊明、李白、杜甫、韩愈和苏轼。本曲是其中一支，主要咏写了三国诸葛亮的事迹，表现了作者对于诸葛亮的推崇以及对于他不幸遭遇的无限同情。诸葛武侯，即三国时期的诸葛亮，死后被追谥为忠武侯，故后世常以武侯、诸葛武侯尊称诸葛亮。\n“草庐当日楼桑，任虎战中原，龙卧南阳”写的是诸葛亮曾隐居于草庐，并概括了当时天下的形势。草庐...", "authors": ["王琳"], "pressName": "崇文书局"}]', '', 'indent', 1522083278, '5ab8b54c9f54543687d006b5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636756, '正宫 · 塞鸿秋', NULL, 17, 131, 0, 1, '张养浩', NULL, 10090, '57b921e95bbb50005b793fa9', '元', 'qu', '曲', '', '', '春来时香雪梨花会，夏来时云锦荷花会，秋来时霜露黄花会，冬来时风月梅花会。春夏与秋冬，四季皆佳会。主人此意谁能会。', '', '此曲运用了独木桥体，句末皆用了相同的“会”字，“会”字含义还有变化，写出曲家妙赏生活之闲趣。
黄花：菊花。
会：懂得，明白。', '', NULL, '', 'indent', 1522083376, '5ab8b5aeac502e57c9590368', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636757, '南吕 · 四块玉 · 酷吏', NULL, 0, 7, 0, 1, '曾瑞', NULL, 36856, '5a19a9388d6d810062727137', '元', 'qu', '曲', '', '', '官况甜，公途险，虎豹重关整威严。仇多恩少人皆厌。业贯盈，横祸添，无处闪。', '', '酷吏：指使用残酷的方法进行统治的官吏。
公途：指仕途。
虎豹重关：虎豹守着重叠的门，形容门禁森严。屈原《招魂》：“虎豹九关，啄害下人些。”
业贯盈：谓罪恶满盈。业，梵语“羯磨”的意译，有造作之义。佛教称人的行为、言语、思念为业。业有善恶之分，但一般指恶业。
', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2940f8fda556505ffe1", "shortContent": "元散曲作者感时伤世，常常会不约而同地慨叹宦海的险恶，反映出当时的一种文人心理与社会现象。一方面是用世与热中功名的传统习尚；另一方面，吏治的窳败，官场的倾轧，又不禁使身历其境者谈虎色变，余悸在心。仕途即畏途，功名如鸡肋，敝屣官宦的过来人固然不屑一顾，即便是恋栈的个中人亦不无怨望。于是，或以愤激词一吐抑塞，或作豁达语暂掩辛酸，成了流行的风尚；而借助不忌直露的散曲体式，显然比用崇尚敦厚含蓄的诗词要来得直...", "authors": ["史良昭"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522083647, '5ab8b6b89f545419e4eda212', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636758, '中吕 · 山坡羊 · 讥时', NULL, 0, 7, 0, 1, '曾瑞', NULL, 36856, '5a19a9388d6d810062727137', '元', 'qu', '曲', '', '', '繁花春尽，穷途人困，太平分的清闲运。整乾坤，会经纶，奈何不遂风雷信？朝市得安为大隐。咱，装做蠢；民，何受窘！', '', '分（fèn）：命中注定。清闲运：不做官而享清闲的命运，这是愤激及反讽之辞。
整乾坤，会经纶：比喻自己有治理国家的才能。
风雷：比喻巨大的力量，指施展才华的机会。
大隐：按古人有所谓大隐、中隐、小隐之说，谓小隐隐于山林，大隐隐于市朝。
', '', NULL, '', 'indent', 1522083728, '5ab8b70f9f5454477967b2a8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636776, '念奴娇', NULL, 1, 395, 1, 0, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', '', '', '人生能几？总不如休惹、情条恨叶。刚是尊前同一笑，又到别离时节。灯灺挑残，炉烟爇尽，无语空凝咽。一天凉露，芳魂此夜偷接。
怕见人去楼空，柳枝无恙，犹扫窗间月。无分暗香深处住，悔把兰襟亲结。尚暖檀痕，犹寒翠影，触绪添悲切。愁多成病，此愁知向谁说？', '', '情条：指纷乱的情绪。
爇：燃烧。
凝咽：犹哽咽，哭时不能痛快出声。
芳魂：谓美人的魂魄。
兰襟：芬芳的衣襟，比喻知心朋友。
檀：即檀粉。', '', NULL, '', 'indent', 1522253097, '5abb4ca775657100458e335e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636794, '木兰花慢 · 立秋夜雨送梁汾南行', NULL, 18, 395, 0, 2, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', 'https://baike.baidu.com/item/%E6%9C%A8%E5%85%B0%E8%8A%B1%E6%85%A2%C2%B7%E7%AB%8B%E7%A7%8B%E5%A4%9C%E9%9B%A8%E9%80%81%E6%A2%81%E6%B1%BE%E5%8D%97%E8%A1%8C/16818636?fr=aladdin', '', '盼银河迢递，惊入夜，转清商。乍西园蝴蝶，轻翻麝粉，暗惹蜂黄。炎凉。等闲瞥眼，甚丝丝、点点搅柔肠。应是登临送客，别离滋味重尝。
疑将。水墨画疏窗，孤影淡潇湘。倩一叶高梧，半条残烛、做尽商量。荷裳。被风暗剪，问今宵、谁与盖鸳鸯。从此羁愁万叠，梦回分付啼螀。', '《木兰花慢·立秋夜雨送梁汾南行》是清代词人纳兰容若创作的一首词。词的上片，词人开门见山地表述了他与好友聚少离多的现实，所以分别的时候二人才愈加地难分难捨。到了下片，词人笔锋一转，在桂花飘香的时节要如约归来。全词从景物着手，营造离别的氛围，悲凉凄切之情更为细密深透。', '木兰花慢：词牌名。原为唐教坊曲。《金奁集》入“林钟商调”，五十五字，前后片各三仄韵，不同部换叶。
梁汾：顾贞观（1637一1714年），又名华文，字华峰，一作华封，号梁汾，江苏无锡人。清康熙十五年（1676年）与纳兰性德相识，从此交契，直至纳兰性德病殁。
迢递（tiáodì）：高远貌。
清商：古代五音之一，即商音，其调悲凉凄切。此处借指入夜后的秋雨之声。
西园：本为园林名，后亦泛指园林。
麝（shè）粉：香粉，代指蝴蝶翅膀。
蜂黄：本指妇女涂额之黄色妆饰，此处代指蜜蜂。
疑将：仿佛、类似。将，助词。唐王勃《郊园即事》：“断山疑画障，悬溜泄鸣琴。”
炎凉：是暖是寒。炎：热。凉：冷。
水墨：浅黑色，常形容或借指烟云。疏窗：雕刻有花纹图案的窗户。
潇湘：本指湘江，或指潇水、湘水，此处代指竹子。
倩：倚近、靠近。
商量：斟酌、思考之意。洪咨夔《念奴娇·老人用僧仲殊韵咏荷花横披谨和》：“香山老矣，正商量不下，去留蛮素。”
荷裳（hécháng）：用荷叶做衣服，这里指荷叶。
羁愁：旅人的愁思。万叠，形容愁情的深厚浓重。
螿（jiāng）：即寒蝉，蝉的一种，比较小，墨色，有黄绿色的斑点，秋天出来鸣叫。', '盼望着银河的出现，入夜的时候却偏偏下起了悲凄的秋雨。刹那间，园里的蝴蝶和蜜蜂纷纷飞起，匆匆躲避。是暖是寒。入秋夜雨本是等闲之事，但今晚那丝丝点点的雨声却令人搅断柔肠。应该是因为此时正是别离送友的时刻，所以这秋雨才这样让人断肠吧。
秋夜雨洒落在疏窗上，那雨痕仿佛是屏风上画出的水墨画。能否请求高高的梧桐树和烧残的灯烛细做掂量，不要在此时再增加更多的愁绪，荷叶已经被秋风吹残，那今夜谁来代替荷叶为鸳鸯们遮风挡雨呢？你将上路远行，从此旅途劳顿，梦醒之时，唯有悲切的寒蝉声相伴。', '[{"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3e73206168b2e01f50", "shortContent": "康熙二十年（1681）立秋之夜，顾贞观因母丧，仓皇雨中南归，容若赋此词送之。秋风萧索，蝴蝶翻飞，一片凄凉。秋雨丝丝点点，更增添了几分凄迷的氛围。此时登高送别，可谓柔肠寸断。词人此间所写《送梁汾》诗，可对读：“西窗凉雨过，一灯乍明灭。沉忧从中来，绵绵不可绝。如何此际心，更当与君别。南北三千里，同心不得说。秋风吹寥花，清泪忽成血。”", "authors": [], "pressName": "崇文书局"}]', '华东师范大学教授徐燕婷、朱惠国《纳兰词评注》：“此词为送别之作。全词直写离别，恰如靖蜓点水点到即止。更多的是从景物着手，用景物烘托，秋风秋雨，疏影残烛，营造离别的氛围，映衬感伤的心境。”', 'indent', 1522336339, '5abc91d19f545400459aa309', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636797, '浣溪沙', NULL, 0, 395, 1, 0, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', 'https://baike.baidu.com/item/%E6%B5%A3%E6%BA%AA%E6%B2%99%C2%B7%E8%82%A0%E6%96%AD%E7%8F%AD%E9%AA%93%E5%8E%BB%E6%9C%AA%E8%BF%98/714323?fr=aladdin', '', '肠断班骓去未还，绣屏深锁凤箫寒。一春幽梦有无间。
逗雨疏花浓淡改，关心芳草浅深难。不成风月转摧残。', '《浣溪沙·肠断班骓去未还》是清代纳兰性德的一首描写女子闺怨的词。浣溪沙，唐代教坊名，后用于词牌名。分平仄两体，字数以四十二字居多，还有四十四字和四十六字两种。最早采用此调的是唐人韩偓，通常以其词为正体，另有四种变体。全词分两片，上片三句全用韵，下片末二句用韵。此调音节明快，为婉约、豪放两派词人所常用。', '逗雨二句：谓春雨洒在了稀疏的花上，花色改变了浓淡的颜色。令人伤情的芳草也浅深难辨。
不成句：不成，犹难道。风月，春日的风光，此处喻为男女间情爱之事。前蜀韦庄《多情》：“一生风月供惆怅，到处烟花恨别离。”
', '一袭白衣的忧伤男子。他不是归人，而是个过客。他达达的马蹄已远去。只剩下，你庭院深深的心事，被锁在寂寞的黄昏。钥匙已被他带走。再没有呜咽的洞箫划过南，没有归棹的桨声轻叩季节。你有的仅是一春幽梦，倾国倾城。梦中有微微的雨，的花，萋萋的芳草，缕缕的情丝。你说，我不愿醒来，你不要追问。东风来时，三月的柳絮满天飞舞。', '[{"bookId": "60fc157134bfda01e0e91549", "bookTitle": "元明清词鉴赏辞典（新一版）", "articleId": "610e865e03048e64fbd8dac7", "shortContent": "这首词代思妇抒念远之情，写她对久出不归的丈夫无穷思念和由此而产生的种种疑虑，对他们之间的爱情表现出担心和不安。\n首句“班骓”“班”通“斑”，“斑骓”是毛色黑白相间的马。他离开家门时骑着一匹这样的马，至今没有回来，令我难过伤心。“肠断”即伤心的意思。说“去未还”，表明他走的时候说好了一定早早归来，也许还预约了归期，否则她不致如此苦苦盼望。伊人当归不归，这位深情的少妇百无聊赖，她把绣户关上，连平常喜爱...", "authors": ["赖汉屏"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522336605, '5abc92dcac502e006399845d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636801, '沁园春', NULL, 11, 395, 2, 0, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', 'https://baike.baidu.com/item/%E6%B2%81%E5%9B%AD%E6%98%A5%C2%B7%E4%B8%81%E5%B7%B3%E9%87%8D%E9%98%B3%E5%89%8D%E4%B8%89%E6%97%A5/1125198?fr=aladdin', '丁巳重阳前三日，梦亡妇淡妆素服，执手哽咽，语多不复能记。但临别有云：“衔恨愿为天上月，年年犹得向郎圆。”妇素未工诗，不知何以得此也，觉后感赋。
', '瞬息浮生，薄命如斯，低徊怎忘。记绣榻闲时，并吹红雨；雕阑曲处，同倚斜阳。梦好难留，诗残莫续，赢得更深哭一场。遗容在，只灵飙一转，未许端详。
重寻碧落茫茫。料短发、朝来定有霜。便人间天上，尘缘未断，春花秋叶，触绪还伤。欲结绸缪，翻惊摇落，减尽荀衣昨日香。真无奈，倩声声邻笛，谱出回肠。', '《沁园春·丁巳重阳前三日》这首词作于康熙十六年（1677）九月，是以记梦的形式所写的悼亡之作，历来为人称赏。其徘侧缠绵、声声血泪，全可与苏轼的《江城子》记梦词相媲美。', '丁巳重阳前三日：指康熙十六年（1677}农历九月初六日，即重阳节前三日。此时亡妻已病逝三个多月。
并吹红雨：唐虞世南《奉和咏风应魏王教》云：“动枝生乱影，吹花送远香。”宋杨万里《九月四日生辰》有“重九吹花节，千龄梦日时”之句，故本谓风吹花动，而后演变为重阳节之意。胡翼龙《满庭芳》：“吹花题叶事，如梦里，记得依然。”是说重阳佳节曾有游赏吟咏之事。纳兰此句是说曾与爱妻共度过美好时光，有所赏心乐事。又，李贺《将进酒》有“桃花乱落如红雨”之句，故红雨指桃花，谓落花时节曾与爱妻共度。
灵飙：灵风。这里指梦中爱妻飘乎之身影。
重寻句：语出白居易《长恨歌》：“上穷碧落下黄泉，两处茫茫皆不见。”此谓梦醒之后，爱妻之音容俱逝，天地茫茫，无处可寻，不胜凄怆。
绸缪：指夫妻之恩爱。
减尽句：《太平御览》卷七○三引晋习凿齿《襄阳记》云：“刘季和曰：‘荀令君（荀彧）至人家，坐处三日香。’"后以“荀衣”“荀香”“荀令衣香”等，或喻人之风流倜傥，或喻惆怅之情，或喻花卉异香。此处是作者自喻，说自己往日的风流神采早已消损殆尽了。宋刘克庄《风入松？福清道中作》：“改尽潘郎鬓发，消残荀令衣香。”
邻笛：晋向秀《思旧赋·序》：“余与稳康、吕安居止接近。其人并有不羁之才，然嵇志远而疏，吕心旷而放。其后各以事见法。……余适将西迈，经其旧庐。于时日薄虞渊，寒冰凄然。邻人有吹笛者，发声寥亮。追思囊昔游宴之好，感音而叹，故作赋云。”后多以此典表示笛声凄婉，或表示怀旧伤逝、心绪惆怅等。如袁去华《兰陵王次周美成韵》：“正难续幽梦，厌闻邻笛。”这里是说一声声幽怨哀感、回肠荡气的笛声，更使人怅惘难耐。', '夜已阑，月满西楼，深院锁着寂寞的梧桐，秋虫低吟一曲惆怅。你凝视摇红的烛影，不觉睡去，白日所思夜入梦来：“丁巳重阳三日，梦亡妇淡妆素服，执手哽咽……临别有云：‘衔恨愿为天上月，年年犹得向郎圆’。”思念在梦中哽咽着，片片碎了，飞落似春尽溪畔散落的桃花，而爱却如大漠孤坟上的青草，至死都坚持着葱茏之色！你叹，“瞬息浮生，薄命如斯，低徊怎忘？”。你忆，“锈榻闲时，并吹红雨；雕栏曲处，同倚斜阳”。你悲，“梦好难留，诗残莫续，赢得更深哭一场”。风轻云淡，月华如水，今夕何夕？纵有红巾翠袖，谁又能拭你腮边之。
梦醒了，伊人软语仿佛仍在耳边徘徊，伊人泪眼仿佛仍在眼前婆娑，然而伊人何在？词人竟沉溺于梦境不能自拔，披衣而起，在茫茫“碧落”中“寻寻觅觅”。又有谁能见证这一夜的辗转，一夜的奔波，一夜的背情呢？或许只有早落在头发上的秋霜吧。真是秋霜？还是“朝如青丝暮成雪”（李白《将进酒》）？谁知道呢。“便人间天上，尘缘未断”，“死者长已矣”（杜甫《石壕吏》），又怎么能再续前缘？只有未亡人的回忆、愁绪还在不断的滋长吧！看着曾经一起流连过的“春花秋叶”，又一次勾起了莫名的伤感。怎么能够承受如此痛苦的煎熬？还是把你忘却吧！抹去了你留在我生活中的印痕。然而邻院幽幽的笛声，又一次把你带回我的身旁。“真无奈”！', '[{"bookId": "6464506e7f27182da3524606", "bookTitle": "元明清词三百首鉴赏辞典", "articleId": "646b4b515b7b0d4f452cb948", "shortContent": "纳兰性德肯定是古代悼亡词写得最好的词人之一。他的《通志堂词》中，题目标有悼亡的有七首。此外，虽未标明悼亡而词情实是悼念亡妇、追思旧情的尚有三四十篇，这首《沁园春》是他的代表作之一。\n\n此词写作背景在小序中已作了交代。所云“亡妇”，指其妻卢氏。卢氏是两广总督、兵部尚书、都察院右都御史卢兴祖的女儿，十八岁时嫁给纳兰性德，被封为淑人，二十一岁时去世，时为康熙十六年（1677）五月三十日。小序中的“丁巳”...", "authors": ["徐培均"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522336815, '5abc93ae2f301e0065e0253d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636808, '国语 · 祭公谏征犬戎', NULL, 8, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', 'https://baike.baidu.com/item/%E7%A5%AD%E5%85%AC%E8%B0%8F%E5%BE%81%E7%8A%AC%E6%88%8E/9425000?fr=aladdin', '', '穆王将征犬戎，祭公谋父谏曰：“不可。先王耀德不观兵。夫兵，戢而时动，动则威；观则玩，玩则无震。是故周文公之《颂》曰：‘载戢干戈，载櫜弓矢；我求懿德，肆于时夏。允王保之。’先王之于民也，茂正其德，而厚其性；阜其财求，而利其器用；明利害之乡，以文修之，使务利而避害，怀德而畏威，故能保世以滋大。
昔我先世后稷，以服事虞夏。及夏之衰也，弃稷弗务，我先王不窋，用失其官，而自窜于戎翟之间。不敢怠业，时序其德，纂修其绪，修其训典；朝夕恪勤，守以惇笃，奉以忠信，奕世戴德，不忝前人。至于武王，昭前之光明，而加之以慈和，事神保民，莫不欣喜。商王帝辛，大恶于民，庶民弗忍，欣戴武王，以致戎于商牧。是先王非务武也，勤恤民隐，而除其害也。
夫先王之制：邦内甸服，邦外侯服，侯、卫宾服，夷、蛮要服，戎、狄荒服。甸服者祭，侯服者祀，宾服者享，要服者贡，荒服者王。日祭，月祀，时享，岁贡，终王，先王之训也。
有不祭，则修意；有不祀，则修言；有不享，则修文；有不贡，则修名；有不王，则修德。序成而有不至，则修刑。于是乎有刑不祭，伐不祀，征不享，让不贡，告不王。于是乎有刑罚之辟，有攻伐之兵，有征讨之备，有威让之令，有文告之辞。布令陈辞，而又不至，则又增修于德，无勤民于远。
是以近无不听，远无不服。今自大毕、伯士之终也，犬戎氏以其职来王，天子曰：‘予必以不享征之’，且观之兵，其无乃废先王之训，而王几顿乎？吾闻夫犬戎树椁，能帅旧德，而守终纯固，其有以御我矣。”王不听，遂征之，得四白狼、四白鹿以归。自是荒服者不至。', '《祭公谏征犬戎》是春秋时期创作的散文，作者是左丘明。', '穆王：周天子，名满。康王之孙，昭王的儿子。犬戎：我国古代西方民族名，即昆戎。商朝和周朝时，在今陕西泾水渭水流域游牧。
祭公谋父周穆王的大臣，封于祭，故叫祭公。谋父是他的字。祭（zhài），父（fǔ）。
戢（jí）：聚集，收藏。时动：按照一定的季节行动。如春夏务家，冬于讲武。
震：惧怕。
周文公：即周公，“文”是他的谥号。周公是周武王的弟弟，名旦，也称叔旦。
载：语助词，无义。干戈：兵器名。
櫜（gāo）：古时收藏弓箭的袋子。这里用作动词，把弓箭收藏起来。
懿德：美德。
时：是，这。夏：中国。
允：信，相信。王：指周武王。
茂：通“懋”，勉励。德，道德。
阜（fù）：大，多。
乡（xiang）：所在。
滋：增益，加多。
不窋（zhú）：古代周族部落首领。
绪：前人未完成的事业、功业绪功绪业继未尽之绪。
恪：恭敬、谨慎。惇：敦厚。奕世：累世、代代。忝（tiǎn）：辱、有愧于。
要通“邀”，希求。
辟（pì）：法、条例。
顿：破坏。', '周穆王将征伐犬戎，祭公谋父劝阻说：“不行。先王显示德行而不炫耀武力。兵力是储存起来到一定时候动用的，一动用就使人畏惧；炫耀武力就会滥用，滥用就不能使人畏惧。所以周文公的《诗经·周颂·时迈》说：‘将兵器好好收藏，将弓箭藏在皮囊；我们君王寻求美德，施予这华夏之邦。君王定能保持天命久长。’先王对于百姓，努力端正他们的德行，使他们的性情更加宽厚；扩大他们的财源，改进他们的工具；指明利害的方向，用礼法整顿他们，使他们追求利益而避免祸害，怀念恩德而畏惧威力，所以能保证周王室世代相承，日益壮大。
从前我们先王世代做农官之长，服事虞、夏两朝。到夏朝衰落的时候，废除了农官，不再致力于农业，我们先王不窋，因而失去了官职，隐藏到戎狄中间。他仍然不敢怠慢祖业，时常称道祖先的功德，继续完成祖先留下的事业，研习祖先的训令和典章；早晚谨慎勤恳，忠实地遵守，诚恳地奉行，世代继承祖先的功德，不辱前人。到了武王，发扬前代光明的德行，再加上仁慈与温和，事奉神灵，保养百姓，莫不欢欣喜悦。商王帝辛，大为百姓所憎恶，百姓不能忍受，欣然拥戴武王，在商朝国都郊外的牧野地方作战。这不是先王致力于武力，而是为了尽力体恤百姓的痛苦，除掉他们的祸害。
先王的制度：王畿以内五百里的地方称甸服，王畿以外五百里的地方称侯服，侯服以外至卫服以内的地方称宾服，宾服以外的蛮、夷地方称要服，要服以外的戎、狄地方称荒服。甸服地方的诸侯供给天子祭祀祖父、父亲的祭品，侯服地方的诸侯供给天子祭祀高、曾祖的祭品，宾服地方的诸侯供给天子祭祀远祖的祭品，要服地方的诸侯供给天子祭神的祭品，荒服地方的诸侯则朝见天子。祭祖父、父亲的祭品一日一次，祭高、曾祖的祭品一月一次，祭远祖的祭品一季一次，祭神的祭品一年一次，朝见天子一生一次。这是先王的遗训。
如有不逐日进贡的，天子就修省内心；有不按月进贡的，天子就修明法令；有不按季进贡的，天子就修明礼仪；有不进岁贡的，天子就修明尊卑名分；有不朝见的，天子就修明德行。这几个方面依次做到而仍有不来的，天子就修明刑法。这时就有惩罚不逐日进贡的，讨伐不按月进贡的，征讨不按季进贡的，责备不进岁贡的，晓谕不来朝见的。这时也就有惩治的法律，有攻伐的军队，有征讨的装备，有严厉谴责的命令，有用文字晓喻的文告。发布命令，公布文告，而再有不来的，天子就在德行上增强修养，不让百姓到远方去受苦。
所以近处的诸侯无不听命，远方的诸侯无不归顺。大毕、伯士一去世，新即位的犬戎国君就带着贡品前来朝见，天子却说：‘我一定要以不享的罪名征讨他’，并且向他炫耀武力，这样做恐怕会废弃先王的遗训，而使朝见天子之礼濒于破坏吧？我听说那犬戎国君秉性敦厚，能遵循祖先的遗德，遵守终生朝见一次之礼，专一不二，他们会有防御我们的准备的。”穆王不听，去征战犬戎，只得到四只白狼、四只白鹿带回来了。从此以后，荒服地方的诸侯就不来朝见了。', NULL, '', 'indent', 1522338055, '5abc98839f54540038d1e2a4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636809, '国语 ·  单子知陈必亡', NULL, 5, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%8D%95%E5%AD%90%E7%9F%A5%E9%99%88%E5%BF%85%E4%BA%A1/9420770?fr=aladdin', '', '定王使单襄公聘于宋。遂假道于陈，以聘于楚。火朝觌矣，道茀不可行也。侯不在疆，司空不视涂，泽不陂，川不梁，野有庾积，场功未毕，道无列树，垦田若蓺，膳宰不置饩，司里不授馆，国无寄寓，县无旅舍。民将筑台于夏氏。及陈，陈灵公与孔宁、仪行父南冠以如夏氏，留宾不见。
单子归，告王曰：“陈侯不有大咎，国必亡。”王曰：“何故？”对曰：“夫辰角见而雨毕，天根见而水涸，本见而草木节解，驷见而陨霜，火见而清风戒寒。故《先王之教》曰：‘雨毕而除道，水涸而成梁，草木节解而备藏，陨霜而冬裘具，清风至而修城郭宫室。’故《夏令》曰：‘九月除道，十月成梁。’其时儆曰：“收而场功，偫而畚梮，营室之中，土功其始，火之初见，期于司里。’此先王所以不用财贿，而广施德于天下者也。今陈国火朝觌矣，而道路若塞，野场若弃，泽不陂障，川无舟梁，是废先王之教也。”
“《周制》有之曰：‘列树以表道，立鄙食以守路，国有郊牧，疆有寓望，薮有圃草，囿有林池，所以御灾也，其余无非谷土，民无悬耜，野无奥草。不夺民时，不蔑民功。有优无匮，有逸无罢。国有班事，县有序民。’今陈国道路不可知，田在草间，功成而不收，民罢于逸乐，是弃先王之法制也。
“周之《秩官》有之曰：‘敌国宾至，关尹以告，行理以节逆之，候人为导，卿出郊劳，门尹除门，宗祝执祀，司里授馆，司徒具徒，司空视途，司寇诘奸，虞人入材，甸人积薪，火师监燎，水师监濯，膳宰致饔，廪人献饩，司马陈刍，工人展车，百官以物至，宾入如归。是故小大莫不怀爱。其贵国之宾至，则以班加一等，益虔。至于王吏，则皆官正莅事，上卿监之。若王巡守，则君亲监之。’今虽朝也不才，有分族于周，承王命以为过宾于陈，而司事莫至，是蔑先王之官也。
“《先王之令》有之曰：‘天道赏善而罚淫，故凡我造国，无从非彝，无即慆淫，各守尔典，以承天休。’今陈侯不念胤续之常，弃其伉俪妃嫔，而帅其卿佐以淫于夏氏，不亦嫔姓矣乎？陈，我大姬之后也。弃衮冕而南冠以出，不亦简彝乎？是又犯先王之令也。
“昔先王之教，懋帅其德也，犹恐殒越。若废其教而弃其制，蔑其官而犯其令，将何以守国？居大国之间，而无此四者，其能久乎？”
六年，单子如楚。八年，陈侯杀于夏氏。九年，楚子入陈。', '公元前601年，单襄公受周定王委派，前去宋国、楚国等国聘问。路过陈国时，他看到路上杂草丛生，边境上也没有迎送宾客的人，到了国都，陈灵公跟大臣一起戴着楚国时兴的帽子去了著名的寡妇夏姬家，丢下周天子的代表不接见。单襄公回到京城后，跟定王说，陈侯本人如无大的灾难，陈国也一定会灭亡。单襄公的预言很快实现了。两年后，与夏姬私通的陈灵公在谈笑中侮辱夏姬的儿子夏征舒，被夏征舒射死。', '定王：周定王。单（shàn）襄公：名朝，定王的卿士。
火：即二十八宿中的心宿，又叫商星，是一颗恒星。觌（dí）见：见。此指夏历十月，心宿早见于东方。
道茀（fú）：野草塞路。
候：候人。路上迎送宾客的官吏。
司空：官名。西周始置，春秋、战国时沿用。它的职责是掌管工程建设，包括修治道路。
泽：水积聚的地方。这里指水塘。陂（bēi）：泽边堵水的堤岸。
梁：桥梁。
庾（yǔ）：露。积：积聚之物。
场功：指收割庄稼。场，打粮、晒粮的地方。
列树：古时候在道路两旁种树作为标记。
垦田：已开垦的田地。蓺（yì）：茅芽。
膳宰：即膳夫。宣达王命以及主管王的饮食等事的官吏。饩（xì）：活的牲畜。
司里：掌管客馆的官。
寄寓：犹言旅馆。
夏氏：指陈大夫夏征舒家。陈灵公与征舒母夏姬公开淫乱，所以要老百姓给夏氏筑台。
陈灵公：名平国。孔宁、仪行父：都是陈国的大夫。南冠：楚国的帽子。
梮：抬土的器具。
奥草：茂密的野草。
罢：通“疲”，疲惫。
彝：常理，法理。', '周定王派单襄公出使宋国，此后又借道陈国去访问楚国。已是清晨能见到大火星的季节了，道路上杂草丛生无法通行，负责接待宾客的官员不在边境迎候，司空不巡视道路，湖泽不筑堤坝，河流不架桥梁，野外堆放着谷物，谷场还没有修整，路旁没有种植树木，田里的庄稼稀稀拉拉，膳夫不供应食物，里宰不安排住处，都邑内没有客房，郊县里没有旅舍，百姓将去为夏氏修筑台观。到了陈国都城，陈灵公与大臣孔宁、仪行父穿戴着楚地流行的服饰到夏氏家玩乐，丢下客人不会见。
单襄公回朝后告诉周定王说：“陈侯如果不遭凶灾，国家也一定要灭亡。”周定王问：“为什么呢？”单襄公答道：“角星在早晨出现时表示雨水结束，天根在早晨出现时表示河流将干枯，氐星在早晨出现时表示草木将凋落，房星在早晨出现时便要降霜了，大火星在早晨出现时表示天气已冷，该准备过冬了。所以先王的教诲说：‘雨季结束便修整道路，河流干枯便修造桥梁，草木凋谢便储藏谷物，霜降来临使备好冬衣，寒风吹起就修整城郭宫室。’所以《夏令》说：‘九月修路，十月架桥。’届时又提醒人们说：‘结束场院的农活，备好土箕和扁担，当营室之星见于中天时，营造工作就要开始。在大火星刚出现时，到司里那儿去集合。’这正是先王能够不费钱财而向民众广施恩惠的原因啊。现今陈国早晨已能见到大火星了，但是道路已被杂草堵塞，农村的谷场已被废弃，湖泊不筑堤坝，河流不备舟桥，这是荒废了先王的遗教。
“周代的制度规定：‘种植树木以标明道路，郊外提供食宿以款待旅客。国家有专设的牧场，边境有接待宾客的设施，洼地里有茂盛的水草，园苑中有林木和水池，这都是用来防备灾害的。其余的地方无不是农田，百姓没有闲置的农具，田野没有丛生的杂草。农时不被耽误，劳力不被浪费。生活富裕而不穷困，百姓安逸而不疲惫。都城中各类人员职责分明，郊外的民众劳作井然有序。’如今陈国的道路无法辨认，农田埋没在杂草丛中，庄稼熟了无人收割，百姓为国君的享乐而疲于劳作，这是抛弃了先王的法度。
“周的《秩官》上说：‘地位相等国家的宾客来访，关尹便向上报告，行理手持符节去迎接，候人引路，卿士到郊外表示慰问，门尹清扫门庭，宗祝陪同客人行祭礼，司里安排住处，司徒调派仆役，司空视察道路，司寇查禁奸盗，虞人供应物品，甸人运送燃料，火师照看火烛，水师料理盥洗，膳宰进送熟食，廪人献奉粮米，司马备齐草料，工人检修车辆，百官各按职责照应，客人来访如同回到了家里。因此大小宾客无不感到满意。如果大国的客人到了，接待的规格就提高一个等级，更加恭敬。至于天子派官员到来，则由各部门的长官接待，上卿加以督察。如果天子下来巡视，就由国君亲临督察。’如今臣虽然没有什么才能，但还是天子的亲族，是奉了天子的使命作为宾客而途经陈国，然而主管的官员却不来照应，这是蔑视先王所制定的官职。
“先王的法令中说：‘天道是奖善惩恶的，所以凡由我们周室治国，不允许违背法令，不迁就怠惰放纵，各自遵守你们的职责，以接受上天的赐福。’如今陈侯不顾念历代相承的法度，抛弃自己的夫人妃嫔，带领下属到夏氏那里去恣意淫乐，这不是亵渎了姬姓吗？陈侯是我们大姬的后裔，却丢弃正式的礼服而穿戴楚地的服饰外出，这不是简慢了礼制吗？这又违背了先王的政令。
“过去先王的教诲，即使认真遵行还恐怕有所差池。像这样荒废先王的遗教、抛弃先王的法度、蔑视先王的分职、违背先王的政令，那凭什么来保守国家呢？地处大国的中间而不仰仗先王的遗教、法度、分职、政令，能够支持长久吗？”
周定王六年，单襄公到楚国。定王八年，陈灵公被夏征舒杀害。定王九年，楚庄王攻入陈国。', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa334a8757d5a0fa502", "shortContent": "这是一篇讽刺小说。诚如作者所云：凡有真才实学的人不必装腔作势，做“大幌子”吓人，而平凡人中未必没有奇异之士，问题是人们往往迷信名人大家，其实，真正能办实事者可能就是生活在我们周围的普通人。本文旨在劝诫人们，不必去迷信表面，而应注重实际本领。这是很有现实意义的。\n文中描绘的“天师”就是一个“装大幌子”而不做实际事情的人物。作品细致入微地刻画了两个人，一是天师，一是上清宫道人。表面上看，天师气派很大，...", "authors": ["罗怀臻"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522338514, '5abc9a4fa22b9d0045286f0b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636810, '国语 ·  展禽论祀爰居', NULL, 3, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%95%E7%A6%BD%E8%AE%BA%E7%A5%80%E7%88%B0%E5%B1%85', '', '海鸟曰“爰居”，止于鲁东门之外二日。臧文仲使国人祭之。展禽曰：“越哉，臧孙之为政也！夫祀，国之大节也，而节，政之所成也。故慎制祀以为国典。今无故而加典，非政之宜也。
“夫圣王之制祀也，法施于民则祀之，以死勤事则祀之，以劳定国则祀之，能御大灾则祀之，能捍大患则祀之。非是族也，不在祀典。昔烈山氏之有天下也，其子曰柱，能植百谷百蔬。夏之兴也，周弃继之，故祀以为稷。共工氏之伯九有也，其子曰后土，能平九土，故祀以为社。黄帝能成命百物，以明民共财。颛顼能修之，帝喾能序三辰以固民，尧能单均刑法以仪民，舜勤民事而野死，鲧障洪水而殛死，禹能以德修鲧之功，契为司徒而民辑，冥勤其官而水死，汤以宽治民而除其邪，稷勤百谷而山死，文王以文昭，武王去民之秽。故有虞氏禘黄帝而祖颛顼，郊尧而宗舜；夏后氏禘黄帝而祖颛顼，郊鲧而宗禹；商人禘舜而祖契，郊冥而宗汤；周人禘喾而郊稷，祖文王而宗武王。幕，能帅颛顼者也，有虞氏报焉；杼，能帅禹者也，夏后氏报焉；上甲微，能帅契者也，商人报焉；高圉、太王，能帅稷者也，周人报焉。凡禘、郊、祖、宗、报，此五者，国之典祀也。加之以社稷山川之神，皆有功烈于民者也。及前哲令德之人，所以为民质也；及天之三辰，民所以瞻仰也；及地之五行，所以生殖也；及九州名山川泽，所以出财用也。非是，不在祀典。今海鸟至，已不知而犯之，以为国典，难以为仁且知矣。夫仁者讲功，而知者处物。无功而祀之，非仁也；不知而不问，非知也。今兹海其有灾乎？夫广川之鸟兽，恒知而避其灾也。”
是岁也，海多大风，冬暖。文仲闻柳下季之言，曰：“信吾过也。季子之言，不可不法也。”使书以为三策。', '《展禽论祀爰居》是春秋时期创作的散文，作者是左丘明。记述臧文仲叫国人去祭祀海鸟“爰居”，引起展禽的一番大议论。这番议论反映出：祭祀是当时国家的大事，但只有为人民建立了功劳的人以及有益于人民的事物，大家才把它当作神来祭祀。虽然有迷信的色彩，但主张“仁者讲功，智者处物”，反对“淫祀”，在古代却是颇有见地的。', '越：指越礼。展禽，即柳下惠（季），鲁大夫。
烈山氏：即神农氏。
弃：传说为周之始祖，尧舜时农官。
共工氏：传说不一，一说为水官。九有：即九州。
九土：九州的土地。社：土地神。
命：名。成命：定百物之名。
颛顼：音专须，即高阳氏，黄帝之孙。
帝喾：音酷。即高辛氏，黄帝之曾孙。三辰：日、月、星。固：安定。
单：通“殚”，尽。仪：善。
契：传说为商之始祖。辑：和睦。
冥：契六世孙，夏时水官。
稷：即弃。
禘、祖、郊、宗、报：均为祭礼名。帅：遵循。
质：诚信。
五行：金、木、水、火、土。
策：古代写字用的竹简或木板。', '名叫“爰居”的海鸟，停在鲁国国都东门外已经两天了。臧文仲命令国都里的人都去祭祀它，展禽说：“臧孙治理政事太越礼了！祭祀，是国家的大法，而法度，则是政治成功的基础。所以要慎重地制定祀典作为国家的常法。现今无故增加祀典，不是治理政事的正确方法。
“圣明的先王制定祀典的准则是，对百姓执行法度就祭祀他，努力王事而死就祭祀他，安定国家有功就祭祀他，能防止重大灾害就祭祀他，能抵御重大祸患就祭祀他，不是这一类的，不在祀典之内。从前神农氏拥有天下，他的后代名叫柱，能种植各种谷物和菜蔬；夏朝建立以后，周的始祖弃继承了柱的事业，所以作为谷神祭祀他。共工氏称霸九州，他的后代担任土官之长，称为后土，因能治理九州的土地，所以作为土神祭祀他。黄帝能替各种事物命名，使百姓了解事物的名称，供给所需的财赋，颛顼又能进一步加以修定；帝喾能序列日、月、星辰以安定百姓，尧能竭力平均刑法以为百姓的准则，舜努力民事而死于野外，鲧堵洪水而被杀，禹能以德行修正鲧的事业，契任司徒而百姓和睦，冥尽水官的职责而死于水中，汤以宽大治理百姓并替他们除掉邪恶的人，后稷致力于谷物种植而死在山间，文王以文德昭著，武王除掉百姓所唾弃的坏人。所以有虞氏禘祭黄帝而祖祭颛顼，郊祭尧而宗祭舜；夏后氏禘祭黄帝而祖祭颛顼，郊祭鲧而宗祭禹；商朝人禘祭帝喾而祖祭契，郊祭冥而宗祭汤；周朝人禘祭帝喾而郊祭后稷，祖祭文王而宗祭武王。幕是能继承颛顼的人，有虞氏为他举行报恩祭；季杼是能继承夏禹的人，夏后氏为他举行报恩祭；上甲微是能继承殷契的人，商朝人为他举行报恩祭，高圉、太王是能继承后稷的人，周朝人为他们举行报恩祭。总共有禘、郊、祖、宗、报，这五种，是国家的祭祀大典。加上土神、谷神、山川之神，都是对百姓有功绩的；还有，前代有智慧和美德的人，是百姓所信赖的；天上的日、月、星辰，是百姓所仰望的；地上的金、木、水、火、土，是万物赖以生长繁殖的；九州的大山川泽，是赖以出产财富的。不是上述这些，不在祀典之内。现在海鸟飞来，自己不懂而去祭祀它，当作国家的大典，这就难以算是仁爱和智慧了。仁者善于评价功劳，智者善于处理事物。海鸟无功而祭祀它，不是仁；自己不懂又不问，不是智。现在这一带海上恐怕将有灾害吧？大江大海的鸟兽，总是预先知道并躲避即将到来的灾害的。”
这年，海上多大风，暖冬。文仲听了柳下季的话说：“确实是我的错啊！季先生的话，不可不当做原则啊！”让属下写了三个竹简分送给司马、司空、司徒。', NULL, '', 'indent', 1522338569, '5abc9a87ac502e006399b4c4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636811, '国语 ·  里革断罟匡君', NULL, 5, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', 'https://baike.baidu.com/item/%E9%87%8C%E9%9D%A9%E6%96%AD%E7%BD%9F%E5%8C%A1%E5%90%9B', '', '宣公夏滥于泗渊，里革断其罟而弃之，曰：“古者大寒降，土蛰发，水虞于是乎讲罛罶，取名鱼，登川禽，而尝之寝庙，行诸国，助宣气也。鸟兽孕，水虫成，兽虞于是乎禁罝罗，矠鱼鳖，以为夏槁，助生阜也。鸟兽成，水虫孕，水虞于是乎禁罜䍡，设阱鄂，以实庙庖，畜功用也。且夫山不槎蘖，泽不伐夭，鱼禁鲲鲕，兽长麑{上鹿下夭}，鸟翼鷇卵，虫舍蚔蝝，蕃庶物也，古之训也。今鱼方别孕，不教鱼长，又行网罟，贪无艺也。”
公闻之，曰：“吾过而里革匡我，不亦善乎！是良罟也！为我得法。使有司藏之，使吾无忘谂。”师存侍，曰：“藏罟不如置里革于侧之不忘也。”', '《里革断罟匡君》是春秋时期创作的散文，作者是左丘明。写鲁宣公不顾时令，下网捕鱼，里革当场割破鱼网，强行劝阻的经过。情节虽简，却极尽起伏变化之妙；事情虽小，却蕴含深刻的道理。', '宣公：即鲁宣公。滥：这里是沉浸的意思。泗：水名。发源于山东蒙山南麓。渊：水深处。里革：鲁国大夫，断：这里是割破的意思。罟（gǔ）；网。匡：纠正。
滥：渍，浸。泗：水名，在鲁城北面。渊：深水。弃：抛弃。
降：降下。土蛰：（－zhé）：动物冬眠时潜伏在土中或洞穴中不食不动的状态。这里指在地下冬眠的动物。发：奋起。这里是说醒过来，钻出土来。
水虞：古代官名，掌管水产。讲：研究，练习。罛（gū）：大鱼网。罶（liǔ）：捕鱼的竹笼。大口窄颈，腹大而长，无底。名：大。登：通“得”，求取。
川禽：水中动物，如鳖蜃之类。尝：尝新，古代秋祭名。寝庙：古代宗庙。古代宗庙分庙和寝两部分。供祀祖宗的前殿称庙，藏祖宗衣冠的后殿称寝，合称寝庙。诸：“之于”的合音，其中“之”是前面动词“行”的宾语，代上文提到的“取名鱼，登川禽”。国：1978年上海古籍出版社排印本《国语》作“国”，不作“国人”，据改。宣：发泄，散发。气：指阳气。
孕：怀胎。兽虞：古代官名，掌管鸟兽的禁令等。罝（jū）：捕兽的网。罗：捕鸟的网。矠（zé）：刺取。槁：干枯。这里指干的鱼。阜：生长。
罜䍡（zhǔlù）：小鱼网。原选本作“罝”，今据1978年上海古籍出版社排印本《国语》改。阱：为猎取野兽而设的陷坑。鄂（é）：埋有尖木桩的陷坑。
槎（zhà）；。蘖（niè）；树木的嫩芽。也指树木被砍伐后所生的新芽。
泽：聚水的洼地。伐：砍伐。夭（ǎo）：初生的草木。鲲（kùn）：鱼子。鲕（èr）：鱼卵。长：使成长，抚养。麑：幼鹿。{上鹿下夭}：（yǎo）：幼麋。翼：用翼遮护，保护。鷇（kóu）：待哺食的雏鸟。卵：鸟蛋。虫：昆虫，虫子。舍：舍弃，放弃。蚔（chí）：蚁卵。蝝（yuán）：蝗的幼虫，是古人做酱的原料。蕃（fán）：繁殖，滋生。庶物：万物。
贪：贪欲。艺：限度。
过：过失，错误。
有司：官吏。古代设官分职，各有专司，因称官吏为“有司”。谂（shěn）：规谏。
师：乐师，名存。', '鲁宣公在夏天到泗水的深潭中下网捕鱼，里革割破他的鱼网，把它丢在一旁，说：“古时候，大寒以后，冬眠的动物便开始活动，水虞这时才计划用鱼网、鱼笱，捕大鱼，捉龟鳖等，拿这些到寝庙里祭祀祖宗，同时这种办法也在百姓中间施行，这是为了帮助散发地下的阳气。当鸟兽开始孕育，鱼鳖已经长大的时候，兽虞这时便禁止用网捕捉鸟兽，只准刺取鱼鳖，并把它们制成夏天吃的鱼干，这是为了帮助鸟兽生长。当鸟兽已经长大，鱼鳖开始孕育的时候，水虞便禁止用小鱼网捕捉鱼鳖，只准设下陷阱捕兽，用来供应宗庙和庖厨的需要，这是为了储存物产，以备享用。而且，到山上不能砍伐新生的树枝，在水边也不能割取幼嫩的草木，捕鱼时禁止捕小鱼，捕兽时要留下小鹿和小驼鹿，捕鸟时要保护雏鸟和鸟卵，捕虫时要避免伤害蚂蚁和蝗虫的幼虫，这是为了使万物繁殖生长。这是古人的教导。现在正当鱼类孕育的时候，却不让它长大，还下网捕捉，真是贪心不足啊！”
宣公听了这些话以后说：“我有过错，里革便纠正我，不是很好的吗？这是一挂很有意义的网，它使我认识到古代治理天下的方法，让主管官吏把它藏好，使我永远不忘里革的规谏。”有个名叫存的乐师在旁伺候宣公，说道：“保存这个网，还不如将里革安置在身边，这样就更不会忘记他的规谏了。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1cf5914587d02f59ffa", "shortContent": "本文选自《国语·鲁语上》，写鲁宣公不顾节令，在鱼孕期捕鱼，被大夫里革断网制止，引用古训批评他贪得无厌；宣公虚心纳谏，赞扬里革匡正了自己的过失，并令有司保存断网，以示不忘告诫。情节虽简，却极尽起伏变化之妙；事情虽小，却蕴含着深刻的理趣启迪。\n文章一开头写鲁宣公在正值鱼孕产子期的夏季，把鱼网沉到泗水深渊捕鱼，大夫里革见了，尚未开言就毅然割断其网（罟）而弃之。只两句，即交待了时间、地点、人物、事件。臣对...", "authors": ["熊", "笃"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522338620, '5abc9ab9ee920a0045f479f0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637540, '扫雪烹茶玩画', NULL, 3, 253, 0, 1, '高濂', NULL, 10013, '57ba82a88ac2470063045693', '明', 'wen', '文', '', '', '茶以雪烹，味更清冽，所谓半天河水是也。不受尘垢，幽人啜此，足以破寒。时乎南窗日暖，喜无觱发恼人，静展古人画轴，如《风雪归人》、《江天雪桌》、《溪山雪竹》、《关心雪运》等图，即假对真，以观古人摹拟笔趣。要知世景画图，俱属造化机局，即我把图，是人玩景，对景观我，谓非我在景中？千古尘缘，孰为真假，当就图画中了悟。', '', '', '', NULL, '', 'indent', 1525454464, '5aec25fda22b9d0044360782', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636812, '国语 ·  襄王不许请隧', NULL, 3, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', 'https://baike.baidu.com/item/%E8%A5%84%E7%8E%8B%E4%B8%8D%E8%AE%B8%E8%AF%B7%E9%9A%A7/9421452?fr=aladdin', '', '晋文公既定襄王于郏，王劳之以地，辞，请隧焉。王弗许，曰：“昔我先王之有天下也，规方千里，以为甸服，以供上帝山川百神之祀，以备百姓兆民之用，以待不庭、不虞之患。其馀，以均分公、侯、伯、子、男，使各有宁宇，以顺及天地，无逢其灾害。先王岂有赖焉？内官不过九御，外官不过九品，足以供给神祇而已，岂敢厌纵其耳目心腹，以乱百度？亦唯是死生之服物采章，以临长百姓而轻重布之，王何异之有？”
“今天降祸灾于周室，余一人仅亦守府，又不佞以勤叔父，而班先王之大物以赏私德，其叔父实应且憎，以非余一人，余一人岂敢有爱也？先民有言曰：‘改玉改行。’叔父若能光裕大德，更姓改物，以创制天下，自显庸也，而缩取备物，以镇抚百姓，余一人其流辟于裔土，何辞之有与？若犹是姬姓也，尚将列为公侯，以复先王之职，大物其未可改也。叔父其茂昭明德，物将自至，余何敢以私劳变前之大章，以忝天下，其若先王与百姓何？何政令之为也？若不然，叔父有地而隧焉，余安能知之？”
文公遂不敢请，受地而还。', '《襄王不许请隧》是春秋时期创作的散文，作者是左丘明。讲述的是晋文公使周襄王在郏邑恢复王位，襄王拿块土地酬谢他。晋文公辞谢，要求襄王允许他死后埋葬用天子的隧礼。襄王不许。阐明了对古代宗法礼仪制度的尊重。', '晋文公：春秋五霸之一。襄王：周襄王。郏：今河南洛阳西。
隧：掘墓道安葬。古时天子的葬礼。
甸服：国都近郊之地。
不庭：不来进贡。不虞：意料不到的事。
神祇：天神和地神。
百度：各种法令、法度。
天降祸灾：周王朝发生内乱。余一人：古代帝王的谦称。
不佞：谦词，不才。叔父：天子对同姓诸侯的称呼。
更姓改物：改朝换代。显庸：显示功能。
流：放逐。辟：受刑罚。', '晋文公使周襄王在郏邑恢复王位，襄王拿块土地酬谢他。晋文公辞谢，要求襄王允许他死后埋葬用天子的隧礼。襄王不许，说：“从前我先王掌管天下，划出方圆千里之地作为甸服，以供奉上帝和山川百神，以供应百姓兆民的用度，以防备诸侯不服朝廷或意外的患难。其余的土地就平均分配给公侯伯子男，使人们各有地方安居，以顺应天地尊卑的法则，而不受灾害。先王还有什么私利呢？他宫内女官只有九御，宫外官员只有九卿，足够供奉天地神灵而已，岂敢尽情满足他耳目心腹的嗜好而破坏各种法度？只有死后生前衣服用具的色彩花纹有所区别，以便君临天下、分别尊卑罢了。此外，天子还有什么不同？
如今上天降祸周朝，寡人也只是谨守先王故府的遗规，加以自己无能，不得不麻烦叔父；如果再分出先王的大礼来报答寡人的私德，那么，叔父也会厌恶寡人，责备寡人了。否则，寡人岂敢有所吝惜？前人说过：‘身上的佩玉改了样，走路的气派不一样。’如果叔父能发扬伟大的美德，改姓换代，开创一统天下的大业，显示自己的丰功伟绩，自然可用天子的服饰文采以安抚百姓，寡人也许会流放边疆，还有什么话可说？如果叔父仍保持姬姓，位列公侯，以恢复先王规定的职分；那么，天子所用的大礼就不可更改了。叔父还是努力发扬德行吧，您所需要的事物自然会来的。就算我敢因酬私德而改变先王的制度，从而玷辱了天下，又如何对得起先王和百姓？又如何推行政令？否则，叔父有的是土地，就是开通墓道举行隧礼，寡人又从何知道呢？”
晋文公于是不敢请隧礼，接受赏赐的土地，回国去了。', NULL, '', 'indent', 1522338725, '5abc9b229f5454003875e6b3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636814, '国语 ·  邵公谏厉王弭谤', NULL, 33, 300, 1, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', 'https://baike.baidu.com/item/%E9%82%B5%E5%85%AC%E8%B0%8F%E5%8E%89%E7%8E%8B%E5%BC%AD%E8%B0%A4', '', '厉王虐，国人谤王。邵公告曰：“民不堪命矣！”王怒，得卫巫，使监谤者。以告，则杀之。国人莫敢言，道路以目。
王喜，告邵公曰：“吾能弭谤矣，乃不敢言。”
邵公曰：“是障之也。防民之口，甚于防川。川壅而溃，伤人必多，民亦如之。是故为川者决之使导，为民者宣之使言。故天子听政，使公卿至于列士献诗，瞽献曲，史献书，师箴，瞍赋，曚诵，百工谏，庶人传语，近臣尽规，亲戚补察，瞽、史教诲，耆、艾修之，而后王斟酌焉，是以事行而不悖。
民之有口也，犹土之有山川也，财用于是乎出；犹其原隰之有衍沃也，衣食于是乎生。口之宣言也，善败于是乎兴。行善而备败，其所以阜财用衣食者也。夫民虑之于心而宣之于口，成而行之，胡可壅也？若壅（yōng）其口，其与能几何？”
王弗听，于是国人莫敢出言。三年，乃流王于彘。', '《邵公谏厉王弭谤》选自《国语》上篇。故篇名亦作《国语·邵公谏厉王弭谤》，题中，邵公亦作召公。《左传》称厉王为"王心戾虐，万民弗忍"。自然引起像召公这样有识之士的忧虑，便介绍了其被逐的过程，文章简洁分明，逻辑清晰，是《国语》名篇。', '厉王：指周厉王，他是周夷王之子，名胡，在位三十七年（前878——前842）。
国人：居住在国都里的人，这里指平民百姓。
邵公：名虎，周王朝卿士，谥穆公。邵，一作召。
命：指周厉王苛虐的政令。
卫巫：卫国的巫者。巫，以装神弄鬼为职业的人。
弭（mǐ）：消除，止。
障：堵塞。
为川者：治水的人。
宣：疏导，放开。
天子：古代帝王的称谓。
公卿：指执政大臣。古代有三公九卿之称。《尚书·周官》：“立太师、太傅、太保，兹惟三公。”九卿指少师、少傅、少保、冢宰、司徒、宗伯、司马、司寇、司空。
列士：古代官员有上士、中士、下士之分，统称列士。位在大夫之下。
诗：指有讽谏意义的诗篇。
瞽（gǔ）：盲人。因古代乐官多由盲人担任，故也称乐官为瞽。
史：史官。
书：指史籍。
师：少师，乐官。
箴：一种具有规戒性的文辞。
瞍（sǒu）：没有眼珠的盲人。
赋：有节奏地诵读。
曚（méng）：有眼珠的盲人。瞍曚均指乐师。
百工：周朝职官名。指掌管营建制造事务的官员。
庶人：平民。
亲戚：指君王的内外亲属。
耆（qí）艾：年六十叫耆，年五十叫艾。这里指年长的师傅。
修：整理修饰。
悖（bèi）：违背道理。
原隰（xí）：平原和低湿之地。
衍沃：指平坦肥沃的良田。《左传·襄公二十五年》中有“井衍沃”的句子。
疏：“衍沃并是平美之地。衍是高平而美者，沃是低平而美者，二者并是良田。”
兴：兴起、表露之意。
阜：丰盛。
夫（fú）：发语词，无义。
与：语助词，无义。一说为“偕从”之意，意思是：“老百姓跟从你的能有多少？”语意也是通顺的。
国人：“国”下原无“人”字，据别本补。
三年：周厉王于公元前842年被国人放逐到彘，据此邵公谏厉王事当在公元前845年。
流：放逐。
彘（zhì）：地名，在今山西霍县东北。谤：形声兼会意。从言，旁声。本义：在背后公开地议论或批评某人的短处）', '周厉王残暴无道，老百姓纷纷责骂他。邵穆公对厉王说：“老百姓已不堪忍受暴虐的政令啦！”厉王听了勃然大怒，找到一个卫国的巫者，派他暗中监视敢于指责自己的人，一经巫者告密，就横加杀戮。于是人们都不敢随便说话，在路上相遇，也只能以眼神表达内心的愤恨。
周厉王颇为得意，告诉邵公说：“我能制止毁谤啦，老百姓再也不敢吭声了。”邵公回答说：“你这样做只能堵住人们的嘴。可是阻止人民说话的危害，超过了堵塞河川的危害。河道因堵塞而造成决口，就会伤害很多人。倘使堵住老百姓的口，后果也将如此。因而治水者只能排除壅塞而加以疏通，治民者只能善于开导而让人说话。所以君王处理政事，让三公九卿以至各级官吏进献讽喻诗，乐师进献民间乐曲，史官进献有借鉴意义的史籍，少师诵读箴言，无眸子的盲人吟咏诗篇，有眸子的盲人诵读讽谏之言，掌管营建事务的百工纷纷进谏，平民则将自己的意见转达给君王，近侍之臣尽规劝之责，君王的内亲外戚都能补其过失，察其是非，乐师和史官以歌曲、史籍加以谆谆教导，年长的师傅再进一步修饰整理，然后由君王斟酌取舍，付之实施，这样，国家的政事得以实行而不背理。老百姓有口，就像大地有高山河流一样，社会的物资财富全靠它出产；又像高原和低地都有平坦肥沃的良田一样，人类的衣食物品全靠它产生。人们用嘴巴发表议论，政事的成败得失就能表露出来。人们以为好的就尽力实行，以为失误的就设法预防，这样社会的衣食财富就会日益丰富，不断增加。人们心中所想通过嘴巴表达出来，朝廷以为行得通的就照着实行，怎么可以堵呢？如果硬是堵住老百姓的嘴，那又能堵多久呢？”
周厉王不听，于是老百姓再也不敢公开发表言论指斥他。过了三年，人们终于把这个暴君放逐到彘地去了。', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f83dbb8b379ee0aec28", "shortContent": "此篇写豫章太守顾邵与鬼庐君斗争的故事。情节曲折，冲突尖锐，戏剧性极强。双方的冲突由顾邵毁庙引起，庐君为此前来寻衅报复，因此庐君处于主动进攻一边。斗争可分五个回合：第一回合，庐君以头蒙熊皮的可怕面貌出现，企图将顾邵吓倒，但顾邵却自己一人“独对之”，并很有礼貌地请他入座。庐君失败了，只得乖乖入座。第二回合是智斗。庐君知道顾邵以熟读《春秋左传》闻名，因此想通过谈论来难倒他，从而打开缺口，让他露出破绽，以...", "authors": ["唐葆祥"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522338959, '5abc9c019f545400443ab274', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636815, '国语 ·  敬姜论劳逸', NULL, 7, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', 'https://baike.baidu.com/item/%E6%95%AC%E5%A7%9C%E8%AE%BA%E5%8A%B3%E9%80%B8', '', '公父文伯退朝，朝其母，其母方绩，文伯曰：“以歜之家而主犹绩，惧干季孙之怒也。其以歜为不能事主乎？”其母叹曰：“鲁其亡乎？使僮子备官而未之闻耶？居，吾语女。昔圣王之处民也，择瘠土而处之，劳其民而用之，故长王天下。夫民劳则思，思则善心生；逸则淫，淫则忘善；忘善则恶心生。沃土之民不材，淫也。瘠土之民，莫不向义，劳也。
是故天子大采朝日，与三公九卿，祖识地德，日中考政，与百官之政事。师尹惟旅牧相，宣序民事。少采夕月，与太史司载纠虔天刑。日入，监九御，使洁奉禘、郊之粢盛，而后即安。诸侯朝修天子之业命，昼考其国职，夕省其典刑，夜儆百工，使无慆淫，而后即安。卿大夫朝考其职，昼讲其庶政，夕序其业，夜庀其家事，而后即安。士朝受业，昼而讲贯，夕而习复，夜而计过，无憾，而后即安。自庶人以下，明而动，晦而休，无日以怠。王后亲织玄紞，公侯之夫人，加之纮、綖。卿之内子为大带，命妇成祭服。列士之妻，加之以朝服。自庶士以下，皆衣其夫。社而赋事，烝而献功，男女效绩，愆则有辟。古之制也！君子劳心，小人劳力，先王之训也！自上以下，谁敢淫心舍力？
今我寡也，尔又在下位，朝夕处事，犹恐忘先人之业。况有怠惰，其何以避辟？吾冀而朝夕修我，曰：‘必无废先人。’尔今曰：‘胡不自安？’以是承君之官，余惧穆伯之绝祀也？”
仲尼闻之曰：“弟子志之，季氏之妇不淫矣！”', '《敬姜论劳逸》是春秋时期创作的散文，作者是左丘明。敬姜的一番长论，是希望自己做高官的儿子忠于职守，做好本职工作的同时，一定要谨记勤俭节约，不要贪图安逸。她认为贪图安逸会触发人们内心的贪欲，贪欲最终会葬送儿子的前程乃至生命。', '公父文伯：鲁大夫。季悼子的孙子，公父穆伯的儿子。
朝：古时候去见君王叫朝，谒见尊敬的人也可以叫朝。母：公父文伯的母亲，即敬姜。
绩：纺麻。
歜（chù）：公父文伯，名歜。文伯自称其名。主：主母。
干：犯。季孙：即季康子。当时担任鲁国的正卿，是季悼子的曾孙。季氏是鲁是的大族，敬姜是季康子从叔祖母，所以文伯这样说。
僮子：即童子。备官：充任官职。
居：坐下。
瘠土：不肥沃的土地。
大采：五采。朝日：天子以春分朝日。
祖：熟习。识：知。地德：古人认为地能生产百物，养育人民，这便是地之德。
师尹：大夫官。惟：表并列，与，和。旅：众士。牧：州牧。相：国相。宣序：全面安排。
少采：三采。夕月：天子每年秋分之夜祭祀月亮的仪式。
庀（pǐ）：治理
列士：士的总称，周代分元士，中士，庶士三种。
社：春社，每年春分时祭祀土地神。烝：特指冬天的祭祀。愆：罪过，过失。辟：刑法。
而：你。修：勉励。
淫：贪图安逸。', '公父文伯退朝之后，去看望他的母亲，他的母亲正在纺线，文伯说：“象我公父歜这样的人家还要母亲亲自纺线，这恐怕会让季孙恼怒。他会觉得我公父歜不愿意孝敬母亲吧？”他的母亲叹了一口气说：“鲁国要灭亡了吧？让你这样的顽童充数做官却不把做官之道讲给你听？坐下来，我讲给你听。过去圣贤的国王为老百姓安置居所，选择贫瘠之地让百姓定居下来，使百姓劳作，发挥他们的才能，因此（君主）就能够长久地统治天下。老百姓要劳作才会思考，要思考才能（找到）改善生活（的好办法）；闲散安逸会导致人们过度享乐，人们过度享乐就会忘记美好的品行；忘记美好的品行就会产生邪念。居住在沃土之地的百姓不成材，是因为过度享乐啊。居住在贫瘠土地上的百姓，没有不讲道义的，是因为他们勤劳啊。
因此天子穿着五彩花纹的衣服隆重地祭祀太阳，让叁公九卿，熟习知悉农业生产，中午考察政务，交代百官要做的事务。京都县邑各级官员在牧、相的领导下，安排事务使百姓得到治理。天子穿着三采花纹的衣服祭祀月亮，和太史、司载详细记录天象；日落便督促嫔妃们，让她们清洁并准备好禘祭、郊祭的各种谷物及器皿，然后才休息。诸侯们清早听取天子布置事务和训导，白天完成他们所负责的日常政务，傍晚反复检查有关典章和法规，夜晚警告众官，告诫他们不要过度享乐，然后才休息。卿大夫清早统筹安排政务，白天与属僚商量处理政务，傍晚梳理一遍当天的事务，夜晚处理他的家事，然后才休息。贵族青年清早接受早课，白天讲习所学知识，傍晚复习，夜晚反省自己有无过错直到没有什么不满意的地方，然后才休息。从平民以下，日出而作，日落而息，没有一天懈怠的。王后亲自编织冠冕上用来系瑱的黑色丝带，公侯的夫人还要编织系于颌下的帽带以及覆盖帽子的装饰品。卿的妻子做腰带，所有贵妇人都要亲自做祭祀服装。各种士人的妻子，还要做朝服。普通百姓，都要给丈夫做衣服穿。春分之后祭祀土地接着开始耕种，冬季祭祀时献上谷物和牲畜，男女（都在冬祭上）展示自己的劳动成果（事功），有过失就要避开不能参加祭祀。这是上古传下来的制度！君王操心，小人出力，这是先王的遗训啊。自上而下，谁敢挖空心思偷懒呢？如今我守了寡，你又做官，早晚做事，尚且担心丢弃了祖宗的基业。倘若懈怠懒惰，那怎么躲避得了罪责呢！我希望你早晚提醒我说：‘一定不要废弃先人的传统。’你今天却说：‘为什么不自己图安逸啊？’以你这样的态度承担君王的官职，我恐怕你父亲穆伯要绝后了啊。”
仲尼听说这件事后说：“弟子们记住，季家的老夫人不图安逸！”', NULL, '', 'indent', 1522339037, '5abc9c5b9f54540038d1fb72', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636816, '国语 ·  叔向贺贫', NULL, 12, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%8F%94%E5%90%91%E8%B4%BA%E8%B4%AB/5777050?fr=aladdin', '', '叔向见韩宣子，宣子忧贫，叔向贺之。宣子曰：“吾有卿之名而无其实，无以从二三子，吾是以忧，子贺我，何故？”
对曰：“昔栾武子无一卒之田，其宫不备其宗器，宣其德行，顺其宪则，使越于诸侯。诸侯亲之，戎狄怀之，以正晋国。行刑不疚，以免于难。及桓子，骄泰奢侈，贪欲无艺，略则行志，假货居贿，宜及于难，而赖武之德以没其身。及怀子，改桓之行，而修武之德，可以免于难，而离桓之罪，以亡于楚。夫郤昭子，其富半公室，其家半三军，恃其富宠，以泰于国。其身尸于朝，其宗灭于绛。不然，夫八郤，五大夫，三卿，其宠大矣，一朝而灭，莫之哀也，唯无德也。今吾子有栾武子之贫，吾以为能其德矣，是以贺。若不忧德之不建，而患货之不足，将吊不暇，何贺之有？”
宣子拜，稽首焉，曰：“起也将亡，赖子存之，非起也敢专承之，其自桓叔以下，嘉吾子之赐。” ', '《叔向贺贫》是春秋时期创作的散文，作者是左丘明。它的教育意义是叔向借晋栾氏、郤氏两大家族兴亡史，说明人应忧德之不建，不应忧货之不足。', '选自《国语》。《国语》相传是春秋时左丘明作，二十一卷，主要记西周末年和春秋时期鲁国等国贵族的言论。叔向，春秋晋国大夫羊舌肸（xī），字叔向。
韩宣子：名起，是晋国的卿。卿的爵位在公之下，大夫之上。
实：这里指财富。
无以从二三子：意思是家里贫穷，没有供给宾客往来的费用，不能跟晋国的卿大夫交往。二三子，指晋国的卿大夫。
栾武子：即栾书，晋大夫，于鲁成公四年升任执政大臣，将中军。
无一卒之田：没有一百人所有的田亩。古代军队编制，一百人为"卒"。一卒之田，100顷。是上大夫的俸禄。
宗器：祭器。
宪则：法制。
越：本意为高扬，这里指传播。
刑：法，就是前边的"宪则"。
行刑不疚（jiù）：指栾书弑杀晋厉公而不被国人责难。
以免于难：因此避免了祸患。意思是没有遭到杀害或被迫逃亡。
桓子：栾武子的儿子。
骄泰：骄慢放纵。
艺：度，准则。
略则行志：忽略法制，任意行事。
假货居贿：把财货借给人家从而取利。贿，财。
而赖武之德：但是依靠栾武子的德望。
以没其身：终生没有遭到祸患。
怀子：桓子的儿子。
修：研究，学习。
离桓之罪：（怀子）因桓子的罪恶而遭罪。离，同"罹"，遭到。
以亡于楚：终于逃亡到楚国。
郤（xì）昭子：晋国的卿。
其富半公室：他的财富抵得过半个晋国。公室，公家，指国家。
其家半三军：他家里的佣人抵得过三军的一半。当时的兵制，诸侯大国三军，合三万七千五百人。一说郤家人占据了晋国三军中一半的职位。晋国有三军，三军主将与将佐，合称为“六卿”。
宠：尊贵荣华。
以泰于国：就在国内非常奢侈。泰，过分、过甚。
其身尸于朝：（郤昭子后来被晋厉公派人杀掉，）他的尸体摆在朝堂（示众）。
其宗灭于绛：他的宗族在绛这个地方被灭掉了。绛，晋国的旧都：在如今山西省翼城县东南。
八郤，五大夫，三卿：郤氏八个人，其中五个大夫，三个卿。
吾子：您，古时对人的尊称。
能其德矣：能够行他的道德了。
吊：忧虑。
稽首：顿首，把头叩到地上。
起：韩宣子自称他自己的名字。
专承：独自一个人承受。
桓叔：韩氏的始祖。', '叔向去拜见韩宣子，韩宣子正为贫困而发愁，叔向却向他表示祝贺。
宣子说："我有卿大夫的名称，却没有卿大夫的财富，没有什么荣誉可以跟其他的卿大夫们交往，我正为此发愁，你却祝贺我，这是什么缘故呢？"
叔向回答说："从前栾武子没有一百顷田，家里穷的连祭祀的器具都备不齐全；可是他能够传播德行，遵循法制，名闻于诸侯各国。各诸侯国都亲近他，一些少数民族都归附他，因此使晋国安定下来，执行法度，没有弊病，因而避免了灾难。传到桓子时，他骄傲自大，奢侈无度，贪得无厌，犯法胡为，放利聚财，该当遭到祸难，但依赖他父亲栾武子的余德，才得以善终。传到怀子时，怀子改变他父亲桓子的行为，学习他祖父武子的德行，本来可以凭这一点免除灾难；可是受到他父亲桓子的罪孽的连累，因而逃亡到楚国。那个郤昭子，他的财产抵得上晋国公室财产的一半，他家里的佣人抵得上三军的一半，他依仗自己的财产和势力，在晋国过着极其奢侈的生活，最后他的尸体在朝堂上示众，他的宗族在绛这个地方被灭亡了。如果不是这样的话，那八个姓郤的中有五个做大夫，三个做卿，他们的权势够大的了，可是一旦被诛灭，没有一个人同情他们，只是因为没有德行的缘故！现今你有栾武子的清贫境况，我认为你能够继承他的德行，所以表示祝贺，如果不忧愁德行的建立，却只为财产不足而发愁，我表示哀怜还来不及，哪里还能够祝贺呢？"
宣子于是下拜，并叩头说："我正在趋向灭亡的时候，全靠你拯救了我。你的恩德不敢独自承受，恐怕从我的祖宗桓叔以下的子孙，都要感谢您的恩赐。"', NULL, '', 'indent', 1522339165, '5abc9cdc9f545400459aec12', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636817, '国语 ·  王孙圉论楚宝', NULL, 4, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', 'https://baike.baidu.com/item/%E7%8E%8B%E5%AD%99%E5%9C%89%E8%AE%BA%E6%A5%9A%E5%AE%9D/8819179?fr=aladdin', '', '王孙圉聘于晋，定公飨之。赵简子鸣玉以相，问于王孙圉曰：“楚之白珩犹在乎？”对曰“然。”简子曰：“其为宝也几何矣？”曰：“未尝为宝。楚之所宝者，曰观射父，能作训辞，以行事于诸侯，使无以寡君为口实。又有左史倚相，能道训典，以叙百物，以朝夕献善败于寡君，使寡君无忘先王之业；又能上下说乎鬼神，顺道其欲恶，使神无有怨痛于楚国。又有薮曰云，连徒洲，金、木、竹、箭之所生也。龟、珠、角、齿，皮、革、羽、毛，所以备赋用以戒不虞者也。所以共币帛，以宾享于诸侯者也。若诸侯之好币具，而导之以训辞，有不虞之备，而皇神相之。寡君其可以免罪于诸侯，而国民保焉。此楚国之宝也。若夫白珩，先王之玩也，何宝之焉？
“圉闻国之宝，六而已。明王圣人能制议百物，以辅相国家，则宝之；玉足以庇荫嘉谷，使无水旱之灾，则宝之；龟足以宪臧否，则宝之；珠足以御火灾，则宝之；金足以御兵乱，则宝之；山林薮泽足以备财用，则宝之。若夫哗嚣之美，楚虽蛮夷，不能宝也。”', '《王孙圉论楚宝》是春秋时杰出史学家左丘明所写的一篇散文，文章主要记载王孙圉论宝的故事。楚国大夫王孙圉出使于晋，在晋定公为之举行的宴会上，晋国大夫赵简子鸣其佩玉，向王孙圉炫耀，并讯问楚国佩玉“白珩”之玉的价值。王孙圉回答，楚于“白珩”未尝为宝；楚之所宝，是辅君治国之贤臣观射父、倚相，是出产众多物资之云梦，是一切足以使国家得福利弭灾祸之财物；而不以玩饰之物为宝。王孙圉和赵简子对何者为宝的认识，立足有高低之分，着眼有公私之别。王孙圉在论楚宝时，针锋相对，义正辞严，滔滔不绝，见解卓越，而讥刺之意，溢于言表。', '王孙圉（yǔ）：楚国的大夫。定公：晋国国君，名午。飨（xiǎng）：用酒食招待客人。
赵简子：名鞅，晋国大夫。鸣玉：贵族衣服的佩玉随行走而碰击鸣响。相：主持礼仪。白珩（héng）：美玉名。
观射父（guānyìfù）：楚国大夫。
左史：史官名。倚相：人名。说：同“悦”。
薮（sǒu）：湖泊。云：云梦。箭：一种竹子，可以作箭。
不虞（yú）：没有料到的祸难。
共：同“供”。
皇：大。相：辅助。
庇荫（bìyìn）：庇护。
臧否（pǐ）：吉凶、善恶。', '楚国大夫王孙圉去晋国行聘问之礼，晋定公设宴款待他。赵简子主持礼仪，他的佩玉叮当作响。赵简子问王孙圉说：“楚国的白珩还在吗？”王孙圉回答道：“还在。”简子说：“它作为楚国的宝物有多久了？”王孙圉说：“楚国从没有把它当宝物，楚国视为宝物的，叫观射父，他擅长辞令，出使诸侯国，不会让敝国国君成为话柄。还有一位左史，名叫倚相，他能够引经据典以说明各种事物，成天向敝国国君进献历史上的成败，让敝国国君不忘记先王的功业；他还善于取悦于天地鬼神，顺着他们的好恶，让神灵们对楚国没有怨气。还有一片沼泽地叫云梦，它连接着徒洲，这里盛产金、木、竹、箭，宝龟、珍珠、犀角、象牙、皮革、羽毛，这些是用来供给兵赋，防备不测的；是提供礼物，以便接待宾客，进献给诸侯国。如果诸侯喜欢这些礼物，再辅之以优美的辞令，还有对不可预料事件的防备，加上神明的保佑，敝国国君大概可以不得罪于诸侯国，而国家和百姓能得以保全。这些才是楚国的宝物。至于那个白珩，不过是先王的玩物罢了，算得上什么宝物呢？
“鄙人听说国宝有六种。圣明之人能够制作评议各种事物，凭这个辅助国家，国家就把他当作宝贝；玉器足以保护庄稼，使上天没有水旱灾害，国家就把它当作宝贝；灵龟足以显示善恶好坏，国家就把它当作宝贝；珍珠足以抗御火灾，国家就把它当作宝贝；金足以抵御兵乱，国家就把它当作宝贝；山林湖泽足以提供财物用品，国家就把它当作宝贝。至于那些叮当作响、徒有其表的美玉，楚国虽然是蛮夷之国，也不会把它当作宝物的。”', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1cf03572034f65a9abc", "shortContent": "本文选自《国语·楚语下》，记叙春秋时期晋国大夫赵简子和楚国使者王孙圉在一次外交宴会上论辩宝物的谈话，反映出两种截然不同的价值观念和生活态度。全文紧扣“楚宝”这一中心论题，以赵简子发难为宾，以王孙圉答辩为主，以宾衬主，宾略主详，从而形成两种针锋相对的思想比照。作者虽未加一语臧否，而其褒贬态度全从人物的问答比照中隐然可见。\n文章开头只用两句话极其扼要地交待了人物及谈话背景：晋定公设宴招待楚国聘问的使者...", "authors": ["熊", "笃"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522339199, '5abc9cfe2f301e0065e0622e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (638378, '杏花天（清明）', NULL, 1, 114, 0, 1, '史达祖', NULL, 10213, '57ba7284a34131005b0e3271', '宋', 'ci', '词', '', '', '软波拖碧蒲芽短。画桥外、花晴柳暖。今年自是清明晚。便觉芳情较懒。
春衫瘦、东风剪剪。过花卩乌、香吹醉面。归来立马斜阳岸。隔岸歌声一片。 ', '', '', '', NULL, '', 'indent', 1532518810, '5b57f1229f5454003c08a9e4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636818, '国语 ·  诸稽郢行成于吴', NULL, 4, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', 'https://baike.baidu.com/item/%E8%AF%B8%E7%A8%BD%E9%83%A2%E8%A1%8C%E6%88%90%E4%BA%8E%E5%90%B4/3226981?fr=aladdin', '', '吴王夫差起师伐越，越王勾践起师逆之江。
大夫种乃献谋曰：“夫吴之与越，唯天所授，王其无庸战。夫申胥、华登，简服吴国之士于甲兵，而未尝有所挫也。夫一人善射，百夫决拾，胜未可成。夫谋必素见成事焉，而后履之，不可以授命。王不如设戎，约辞行成，以喜其民，以广侈吴王之心。吾以卜之于天，天若弃吴，必许吾成而不吾足也，将必宽然有伯诸侯之心焉；既罢弊其民，而天夺之食，安受其烬，乃无有命矣。”
越王许诺，乃命诸稽郢行成于吴，曰：“寡君勾践使下臣郢，不敢显然布币行礼，敢私告于下执事曰：‘昔者，越国见祸，得罪于天王，天王亲趋玉趾，以心孤句践，而又宥赦之。君王之于越也，繄起死人而肉白骨也。孤不敢忘天灾，其敢忘君王之大赐乎？今勾践申祸无良，草鄙之人，敢忘天王之大德，而思边陲之小怨，以重得罪于下执事？勾践用帅二三之老，亲委重罪，顿颡于边。今君王不察，盛怒属兵，将残伐越国。越国固贡献之邑也，君王不以鞭棰使之，而辱军士，使寇令焉！勾践请盟。一介嫡女，执箕帚以晐姓于王宫；一介嫡男，奉盘匜以随诸御。春秋贡献，不解于王府。天王岂辱裁之？亦征诸侯之礼也。’”
夫谚曰：“‘狐埋之而狐搰之，是以无成功。’今天王既封殖越国，以明闻于天下，而又刈亡之，是天王之无成劳也。虽四方之诸侯，则何实以事吴？敢使下臣尽辞，唯天王秉利度义焉！”', '《诸稽郢行成于吴》是春秋时期创作的散文，作者是左丘明。讲述了越王派诸稽郢向吴求和的历史事件。目的是赢得时间以备强国讨伐吴王。', '逆：迎战。
大夫种：即文种，越国大夫。庸：用。
申胥：即伍子胥，封于申，故又称申胥。华登：吴国大夫。简服：训练。挫：败。
决拾：射箭用具。
素：预先。履：实行。授命：送命。
约辞：委婉的言辞。行成：求和。
广侈：扩张，使其生骄心。
不吾足：不把我们放在心上。
伯：通“霸”，称霸。
罢：通“疲”，疲劳。
烬：灰烬。
诸稽郢：越国大人。
币：礼品。下执事：供役使的人。
天王：对吴王夫差的尊称。得罪：指勾践射伤吴王之父阖闾。亲趋玉趾：亲劳大驾。孤：舍弃。
繄：就是。
边陲：边境。
用：因此。老：老臣。顿颡：叩头直至额触地。
属：会集。残伐：杀伐。
鞭棰：鞭子。寇令：抵御盗寇的命令。
箕帚：畚箕、笤帚。晐姓：贡纳诸姓妇子到天子之宫。槃匜：洗手脸的用具。解：同“懈”。
辱：谦词。征诸侯：向诸侯征税。
搰：掘出。
封殖：培植。这是以草木自比。
刈：芟草。
实：信实。秉：拿，执。度：衡量。', '吴王夫差出兵攻越，越王勾践带兵迎击。大夫文种献计说：“吴越谁存谁亡，只看天意如何，用不着打仗了。伍子胥和华登练出来的吴国士兵，从来没打过败仗，只要有一人精于射箭，就会有百人拉起弓弦练习。我们很难战胜他啊。凡是谋划一件事情，必须预见到成功才实行，决不可轻易拼命。君王不如保全兵力，严守阵地，用谦卑的言辞向吴国求和，让吴民高兴，让吴王的野心一天天膨胀。我们可由此占卜天意，果真天弃吴国，吴人定会答应议和，不把我国放在眼里，而放心大胆去中原争霸。等他百姓疲惫了，再遇上天灾歉收，我们稳稳当当去收拾残局，吴国就失去上天的保佑了。”
越王同意了，派诸稽郢向吴求和，说：“敝国君主勾践，派遣小臣诸稽郢前来，不敢公然献上玉帛，在天王驾前行礼，只好冒昧的私下向天王左右的官员说：从前，越国不幸冒犯天王，天王亲自出动玉趾，本来打算灭我勾践，又宽恕了我。天王对我越国的恩德，真是让死人复活，让白骨生肌，我勾践既不敢忘记天降的灾祸，又怎敢忘记天王的厚赐呢？如今我勾践既因无德而重遭天祸，我们这些草野的鄙贱之人，又怎敢忘记天王的大德，只因边境的小怨而耿耿于怀，以至再次得罪天王的左右呢？勾践因此率领几个老臣，亲自承担重罪，在边境上叩着响头。天王未了解下情，勃然大怒，出兵讨伐。越国本来就是向天王称臣进贡的城邑啊，天王不用鞭子驱使它，却使您尊贵的将士们受屈，来执行讨伐，更使越国不安了。因此勾践请求盟约。今送来一个嫡生的女儿，在王宫拿着簸箕扫帚；还送来一个嫡生的儿子，捧着盘子和脸盆，随同侍卫们服侍天王。春秋两季，向天王的府库进贡，决不丝毫懈怠。天王又何必御驾亲征？这本是天子向诸侯征税之礼啊！谚语说：‘狐狸埋下它，狐狸又扒出来，所以劳而无功。’如今天王既已扶植了越国，您的明智已传遍天下；倘又消灭它，天王岂不也是劳而无功吗？如何使四方的诸侯信服吴国呢？因此命我下臣把话儿说清楚，请天王就利和义两方面多加权衡吧！”', NULL, '', 'indent', 1522339240, '5abc9d269f5454003875f630', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636819, '国语 ·  申胥谏许越成', NULL, 9, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', 'https://baike.baidu.com/item/%E7%94%B3%E8%83%A5%E8%B0%8F%E8%AE%B8%E8%B6%8A%E6%88%90/4015863?fr=aladdin', '', '吴王夫差乃告诸大夫曰：“孤将有大志于齐，吾将许越成，而无拂吾虑。若越既改，吾又何求？若其不改，反行，吾振旅焉。”申胥谏曰：“不可许也。夫越非实忠心好吴也，又非慑畏吾甲兵之强也。大夫种勇而善谋，将还玩吴国于股掌之上，以得其志。夫固知君王之盖威以好胜也，故婉约其辞，以从逸王志，使淫乐于诸夏之国，以自伤也。使吾甲兵钝弊，民人离落，而日以憔悴，然后安受吾烬。夫越王好信以爱民，四方归之，年谷时熟，日长炎炎，及吾犹可以战也。为虺弗摧，为蛇将若何？”吴王曰：“大夫奚隆于越？越曾足以为大虞乎？若无越，则吾何以春秋曜吾军士？”乃许之成。
将盟，越王又使诸稽郢辞曰：“以盟为有益乎？前盟口血未干，足以结信矣。以盟为无益乎？君王舍甲兵之威以临使之，而胡重于鬼神而自轻也。”吴王乃许之，荒成不盟。', '《申胥谏许越成》是春秋时期创作的散文，作者是左丘明。记载越国派使向吴国求和的历史事件。大臣申胥谏阻吴王不许答应求和，但是没有成功。', '孤：王侯的自谦之词。有大志于齐：要攻打齐国，北上称霸。
而：你们。拂：违背。
反：同“返”，指伐齐回来。
振旅：整顿部队。
慑：恐惧，害怕。
种：越大夫文种。
还（xuán）：转动。玩：玩弄。
盖：崇尚。
婉约：委婉而谦卑。
从：同“纵”。
诸夏：中原的其他诸侯国，如晋、齐、鲁、宋、郑、卫等。
钝：不利。弊：困。
离落：离散。', '吴国国王夫差便告诉各位大夫说：“我还对齐国有大的企图，我就同意越国的求和，你等不要违背我的意愿。如果越国已经改过，我（对它）还有什么要求呢？如果它不悔改，（等我从齐国）回来，我挥师讨伐它。”申胥劝道：“不能同意求和啊。越国不是诚心和吴国和好，也不是害怕我们的军队的强大。（他们的）大夫文种有勇有谋，（他）将把（我们）吴国在股掌之上玩得团团转，来实现他的愿望。他本来就知道君王您喜欢逞威斗胜，所以说婉转驯服地言辞，来纵容国王您的心志，使您沉浸在征服中原各国的快乐中，来让你自己伤害自己。使我们的军队困顿疲惫，民众流离失所，而日益憔悴，然后他们安全地收拾我们的残局。而越王信用好爱惜民众，四方百姓都归顺他，年年谷物按时节成熟，日子过得蒸蒸日上。在我们还能够（跟他们）打仗的时候，是小蛇的时候不摧毁它，成为大蛇将怎么办？”吴王说：“大夫你干嘛长越国的威风，越国能够足以成为大患吗？如果没有越国，那我春秋演习向谁炫耀我的军队啊？”便同意了越国的求和。
将要盟约时，越王又派诸稽郢砌词说：“要认为盟誓有用吗？上次盟誓时涂在嘴上的血还没干呢，足以保证信用啊。要认为盟誓没用吗？君王家的军队的威武降临便能使唤我们，干吗要看重鬼神而看轻您自己的威力啊。”吴王便同意讲和，空有讲和没有盟誓。', NULL, '', 'indent', 1522339269, '5abc9d3f9f54540038d2013c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636820, '公羊传 · 春王正月', NULL, 3, 2, 0, 1, '公羊高', NULL, 36903, '5abc9eb69f545400459af77d', '秦', 'wen', '文', 'https://baike.baidu.com/item/%E6%98%A5%E7%8E%8B%E6%AD%A3%E6%9C%88/4286192?fr=aladdin', '', '元年者何？君之始年也。春者何？岁之始也。王者孰谓？谓文王也。曷为先言王而后言正月？王正月也。何言乎王正月？大一统也。公何以不言即位？成公意也。何成乎公之意？公将平国而反之桓。曷为反之桓？桓幼而贵，隐长而卑；其为尊卑也微，国人莫知。隐长又贤，诸大夫扳隐而立之。隐于是焉而辞立，则未知桓之将必得立也。且如桓立，则恐诸大夫之不能相幼君也。故凡隐之立，为桓立也。隐长又贤，何以不宜立？立嫡，以长不以贤；立子，以贵不以长。桓何以贵？母贵也。母贵则子何以贵？子以母贵，母以子贵。', '《春王正月》出自《公羊传》，通过周朝时隐公与桓公对继承王位的历史事件来说明“子以母贵，母以子贵。”的道理。', '元年：指鲁隐公元年。
文王：周文王。
曷：为什么。正月：阴历每年第一个月。
王正月：指周历正月。古时改朝换代即改正朔（正月的第一天）。周历以建子之月（即夏历的十一月）为岁首。
大一统：天下统一。
平国而反之桓：隐公打算平治鲁国后，把政权归还桓公。
隐长而卑、桓幼而贵：桓公的母亲仲子是鲁惠公的夫人。隐公的母亲声子只是随嫁来的姐妹。
扳：拥戴。
适：同“嫡”。
立子：立庶子。
名句：
“立适以长不以贤，立子以贵不以长。”
立夫人所生的嫡子为国君，只凭年长，不凭贤明；立妾的儿子为国君，只凭尊贵，不凭年长。', '“元年”两个字是什么意思？是指国君即位的头一年。“春”字是什么意思？是一年的开始。“王”指的是谁？是指周文王。为什么先说王而后说正月，这是为了说明是周王朝的正月。为什么说周王朝的正月？是为了尊重周天子的一统天下。隐公为什么不说即位？是为了成全隐公的意愿。为什么说是成全隐公的意愿？因为隐公准备治理好国家，然后还政于桓公。为什么还政于桓公？因为桓公年幼却地位尊贵，隐公年长却地位卑下；他们之间尊卑的差别是很小的，国都里的人没有知道的。隐公年长而有德行，众大夫攀援隐公而立他为国君。隐公在这时要是推辞即位，就不知道桓公是否一定能立为国君；如果桓公立为国君，又恐怕众大夫不能辅佐幼君。所以，总的说来，隐公的即位，正是为了桓公将来即位。隐公年长而有德行，为什么不宜立为国君？这是因为，立嫡子，凭年长不凭德行；立庶子，凭尊贵不凭年长。桓公为什么尊贵？因为他的母亲尊贵。母亲尊贵，儿子为什么就尊贵？母凭子贵，子凭母贵。', NULL, '', 'indent', 1522339720, '5abc9ef217d009006144146d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636822, '公羊传 · 吴子使札来聘', NULL, 3, 2, 0, 1, '公羊高', NULL, 36903, '5abc9eb69f545400459af77d', '秦', 'wen', '文', 'https://baike.baidu.com/item/%E5%90%B4%E5%AD%90%E4%BD%BF%E6%9C%AD%E6%9D%A5%E8%81%98/6939738?fr=aladdin', '', '吴无君，无大夫，此何以有君，有大夫？贤季子也。何贤乎季子？让国也。其让国奈何？谒也，馀祭也，夷昧也，与季子同母者四。季子弱而才，兄弟皆爱之，同欲立之以为君。谒曰：“今若是迮而与季子国，季子犹不受也。请无与子而与弟，弟兄迭为君，而致国乎季子。”皆曰诺。故诸为君者皆轻死为勇，饮食必祝，曰：“天苟有吴国，尚速有悔于予身。”故谒也死，馀祭也立。馀祭也死，夷昧也立。夷昧也死，则国宜之季子者也，季子使而亡焉。僚者长庶也，即之。季之使而反，至而君之尔。阖庐曰：“先君之所以不与子国，而与弟者，凡为季子故也。将从先君之命与，则国宜之季子者也；如不从先君之命与子，我宜当立者也。僚恶得为君？”于是使专诸刺僚，而致国乎季子。季子不受，曰：“尔杀吾君，吾受尔国，是吾与尔为篡也。尔杀吾兄，吾又杀尔，是父子兄弟相杀，终身无已也。”去之延陵，终身不入吴国。故君子以其不受为义，以其不杀为仁，贤季子。则吴何以有君，有大夫？以季子为臣，则宜有君者也。札者何？吴季子之名也。春秋贤者不名，此何以名？许夷狄者，不一而足也。季子者，所贤也，曷为不足乎季子？许人臣者必使臣，许人子者必使子也。', '《吴子使札来聘》鲁襄公二十九年（公元前544），吴国派公子扎访问鲁国，《左传》对经过情形有详细记载。当时的吴王馀祭是公子扎的二哥。吴国在公子扎的父亲寿梦就位时（公元前585年）就已称王。但中原诸国还是视吴国为蛮夷之邦，《春秋》记事称之为“吴子”，“子”的爵位在公、侯、伯之下，所以实际上是贬称。而《公羊传》出于“诸夏”的民族偏见和地域偏见，甚至否认吴国“有君、有大夫”，对《春秋》记事用语理解为抬高了吴国的地位。本文就是《公羊传》解释《春秋》为什么用“吴子”肯定吴国“有君”，用“聘”肯定吴国“有大夫”的。全文层层设问，步步深入，以事实说明公子扎的贤、仁、深明大义，使吴国在诸夏心目中的地位得到了提高。', '“吴子使札来聘”：这句话是该文引用的《春秋》里的句子。
聘：古代诸侯国之间派使者相问的一种礼节。使者代表国君，他的身分应是卿；“小聘”则派大夫。
贤：用作以动词。
季子：公子扎是吴王寿梦的小儿子，古以伯、仲、叔、季排行，因此以“季子”为字。《史记》称他“季扎”。
让国：辞让国君之位。据《史记·吴世家》记载，寿梦生前就想立季扎，季扎力辞，才立长子诸樊（即谒）。寿梦死后，诸樊又让位季扎，季扎弃其室而耕，乃止。
谒：寿梦长子，一作“遏”，号诸樊。《春秋》经写作“吴子遏”，《左传》、《史记》称“诸樊”。
馀祭：寿梦次子，《左传》记其名一作“戴吴”，马王堆三号墓出土帛书《春秋事语》作“余蔡”。
夷昧：寿梦三子。《左传》作“夷末”，《史记》作“馀昧”。
迮（zé，又读zuò）：仓促。
尚：佑助。
悔：咎，灾祸，这里指亡故。
谒也死：谒在位十三年，前548年（鲁襄公二十五年）在伐楚战争中，中冷箭死于巢（今安徽巢县）。
馀祭也死：馀祭在位四年（《史记》误作十七年），前544年（鲁襄公二十九年）在视察战船时被看守战船的越国俘虏行刺身亡。
夷昧也死：夷昧在位十七年（《史记》误作四年），前527年（鲁昭公十五年）卒。
使而亡：出使在外。《史记·吴世家》所记与此不同：“王馀眛卒，季扎让，逃去。”认为季扎是为让位而逃走的。
僚：《公羊传》这里说他是“长庶”，即吴王寿梦妾所生的长子，季扎的异母兄。《史记·吴世家》则说他是“王馀眛之子”。以《公羊传》为是。
阖庐（lǘ）：公子光即吴王位后的号，《史记》说他是诸樊之子，《世本》说他是夷昧之子。
专诸：伍子胥为公子光找到的勇士，前515年（吴王僚十三年）四月，公子光请王僚喝酒，使专诸藏匕首于炙鱼之中，进食时取出匕首刺王僚胸而杀之。
致国乎季子：把王位给季扎。《史记·吴世家》谓阖庐刺杀王僚后即承吴王位，无让国于季扎之意。
延陵：春秋吴邑，今江苏常州。季扎食邑于此，所以又号“延陵季子”。
不名：不直称名。古人生三月取名，年二十行冠礼，另取字。对人表示尊敬，就称其字而不称名。
不一而足：不因为一事一物就认为够条件了。与今义不同。', '“吴子派札来（鲁国）访问。”
吴国本无所谓国君，无所谓大夫，这则记载为什么承认它有国君，有大夫呢？为了表明季子的贤啊。季子贤在哪里呢？辞让国君的位置啊。他辞让君位是怎么一回事呢？谒、馀祭、夷昧跟季子是一母所生的四兄弟，季子年幼而有才干，兄长们都爱他，一起想立他做国君。谒说：“现在如果就这样仓促地把君位给他，季子还是不接受的。我愿不传位给儿子而传位给弟弟，由弟弟依次接替哥哥做国君，最后把君位传给季子。”馀祭、夷昧都说行。所以几个哥哥在位时都勇敢不怕死，每次就餐必定祈祷，说：“上天如果让吴国存在下去，就保祐我们早点遭难吧。”所以谒死了，馀祭做国君。馀祭死了，夷昧做国君。夷昧死了，国君的位置应当属于季子了。季子出使在外，僚是寿梦的庶长子，就即位了。季子出访回国，一到就把僚当作国君。阖闾说：“先君所以不传位给儿子，而传位给弟弟，都是为了季子的缘故。要是遵照先君的遗嘱呢，那么国君应该季子来做；要是不照先君的遗嘱呢，那么我该是国君。僚怎么能做国君呢？”于是派专诸刺杀僚，而把国家交给季子。季子不接受，说：“你杀了我的国君，我受了你给予的君位，这样我变成跟你一起篡位了。你杀了我哥哥，我又杀你，这样父子兄弟相残杀，一辈子没完没了了。”就离开国都到了延陵，终身不入吴国宫廷。所以君子以他的不受君位为义，以他的反对互相残杀为仁，称许季子的贤德。
那么吴国为什么有国君，有大夫呢？既承认季子是臣，就应该有君啊。扎是什么呢？吴季子的名啊。《春秋》对贤者不直称其名，这则记载为什么称名呢？认可夷狄，不能只凭一事一物就认为够条件了。季子是被认为贤的，为什么季子还不够条件呢？认可做人臣子的，一定要使他像个臣子；认可做人儿子的，一定要使他像个儿子。（言外之意是：季子是夷狄之邦的臣子，是夷狄之王的儿子，就要在用语遣词上显示出这一点来。这就是所谓“《春秋》笔法”。）', NULL, '', 'indent', 1522339860, '5abc9f8e17d00900614418fb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636856, '山海经 · 山经 · 中山经', NULL, 7, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E4%B8%AD%E5%B1%B1%E7%BB%8F/19829092', '', '中山经薄山之首，曰甘枣之山，共水出焉，而西流注于河。其上多杻木。其下有草焉，葵本而杏叶。黄华而荚实，名曰箨，可以已懵。有兽焉，其状如囗鼠而文题，其名曰㔮，食之已瘿。
又东二十里，曰历儿之山，其上多囗，多杤木，是木也，方茎而员叶，黄华而毛，其实如拣，服之不忘。
又东十五里，曰渠猪之山，其上多竹，渠猪之水出焉，而南流注于河。其中是多豪鱼，状如鲔，赤喙尾赤羽，可以已白癣。又东三十五里，曰葱聋之山，其中多大谷，是多白垩，黑、青、黄垩。
又东十五里，曰涹山，其上多赤铜，其阴多铁。又东七十里，曰脱扈之山。有草焉，其状如葵叶而赤华，荚实，实如棕荚，名曰植褚，可以已癙，食之不眯。又东二十里，曰金星之山，多天婴，其状如龙骨，可以已痤。
又东七十里，曰泰威之山。其中有谷，曰枭谷，其中多铁。又东十五里，曰囗谷之山。其中多赤铜。
又东百二十里，曰吴林之山，其中多囗草。又北三十里，曰牛首之山。有草焉，名曰鬼草，其叶如葵而赤茎，其秀如禾，服之不忧。劳水出焉，而西流注于囗水，是多飞鱼，其状如鲋鱼，食之已痔衕。
又北四十里，曰霍山，其木多楮。有兽焉，其状如狸，而白尾有鬣，名曰朏朏，养之可以已忧。
又北五十二里，曰合谷之山，是多薝棘。
又北三十五里，曰阴山，多砺石、文石。少水出焉，其中多雕棠，其叶如榆叶而方，其实如赤菽，食之已聋。
又东北四百里，曰鼓镫之山，多赤铜。有草焉，名曰荣草，其叶如柳，其本如鸡卵，莨之已风。凡薄山之首，白甘枣之山至于鼓镫之山，凡十五山，六千六百七十里。历儿、冢也，其祠礼：毛，太牢之具，县以吉玉。其余十三者，毛用一羊，县婴用桑封，瘗而不糈。桑封者，桑主也，方其下而锐其上，而中穿之加金。中次二经注山之首，曰辉诸之山，其上多桑，其兽多闾麋，其鸟多鹖。
又西南二百里，曰发视之山，其上多金玉，其下多砥砺。即鱼之水出焉，而西流注于伊水。
又西三百里，曰豪山，其上多金玉而无草木。又西三百里，曰鲜山，多金玉，无草木，鲜水出焉，而北流注于伊水。其中多鸣蛇，其状如蛇而四翼，其音如磬，见则其邑大旱。又西三百里，曰阳山，多石，无草木。阳水出焉，而北流注于伊水。其中多化蛇，其状如人面而豺身，鸟翼而蛇行，其音如叱呼，见其邑大水。
又西二百里，曰昆吾之山，其上多赤铜。有兽焉，其状如彘而有角，其音如号，名曰蠪蚔，食之不眯。又西百二十里，曰荔山。荔水出焉，而北流注于伊水，其上多金玉，其下多青雄黄。有木焉，其状如棠而赤时，名曰芒草，可以毒鱼。
又西一百五十里，曰蔓渠之山，其上多金玉，其下多竹箭。伊水出焉，而东流注于洛。有兽焉，其名曰马腹，其状如人面虎身，其音如婴儿，是食人。凡济山之首，自辉诸之山至于蔓渠之山，凡九山，一千六百七十里，其神皆人面而鸟身。祠用毛，用一吉玉，投而不糈。中次三以萯山之首，曰敖岸之山，其阳多㻬琈之玉，其阴多赭、黄金。神熏池居之。是常出美玉。北望河林，其状如茜如举。有兽焉，其状如白鹿而四角，名曰夫诸，见则其邑大水。
又东十里，曰青要之山，实惟帝之密都。北望河曲，是多驾鸟。南望墠渚，禹父之所化，中多仆累、蒲卢。䰠武罗司之，其状人面而豹文，小要而白齿，而穿耳以囗，其鸣如鸣玉。是山也，宜女子。畛水出焉，而北流注于河。其中有鸟焉，名曰鴢，其状如凫，青身而朱目赤尾，食之宜子。？有草焉，其状如囗，而方茎黄华赤实，其本如稿木，名曰荀草，服之美人色。又东十里，曰騩山，其上有美枣，其阴有㻬琈之玉。正回之水出焉，而北流注于河。其中多飞鱼，其状如豚而赤文，服之不畏雷，可以御兵。又东四十里，曰宜苏之山，其上多金玉，其下多蔓居之木。滽滽之水出焉，而北流注于河，是多黄贝。合而北流注于河，其中多苍玉。吉神泰逢司之，其状如人而虎尾，是好居于萯山之阳，出入有光。泰逢神动天地气也。凡萯之首，自敖岸之山至于和山，凡五山，四百四十里。其祠：泰逢、熏池、武罗皆一牡羊副，婴用吉玉。其二神用一雄鸡瘗之。糈用稌。
中次四经厘山之首，曰鹿蹄之山，其上多玉，其下多金。甘水出下，而北流注于洛，其中多泠石。西五十里，曰扶猪之山，其上多礝石。有兽焉，其状如貉而人目，其名曰䴦。虢水出焉，而北流注于洛，其中多礝石。又西一百二十里，曰厘山，其阳多玉，其阴多蒐。有兽焉，其状如牛。苍身，其音如婴儿，是食人，其名曰犀渠。
滽滽之水出又西一百二十里，曰厘山，其阳多玉，其阴多蒐。有兽焉，其状如牛。苍身，其音如婴儿，是食人，其名曰犀渠。滽滽之水出焉，而南流注于伊水。有兽焉，名曰【犭颉】，其状如獳犬而有鳞，其毛如彘鬣。又西二百里，曰箕尾之山，多楮，多涂石，其上多㻬琈之玉。又西二百里，曰箕尾之山，基个多玉，其下多铜。滔雕之水出焉，而北流注于洛。其中多羬羊。有木焉，其状如樗，其叶如桐而荚实，其名曰茇，可以毒鱼。
又西二百里，曰白边之山，其上多金玉，其下多青雄黄。又西二百里，曰熊耳之山，其上多漆，其下多棕。浮濠之水出焉，而西流注于洛，其中多水玉，多人鱼。有草焉，其状如苏而赤华，名曰葶苎，可以毒鱼。
又西三百里，曰牡山，其上多文石，其下多竹箭竹䉋，其兽多㸲牛、羬羊，鸟多赤鷩。
又西三百五十里，曰囗举之山。雒水出焉，而东北流注于玄扈之水，其中多肠之物。此二山者，洛间也。凡厘册之首，自鹿蹄之山至于玄扈之山，凡九山，千六百里七十里。其神状皆人面兽身。其祠之，毛用一白鸡，祈而不糈，以采衣之。
中次五经薄山之苟，曰苟床之山，无草木，多怪石。东三百里，曰首山，其阴多楮柞，其草多?芫，其阳多㻬琈之玉，木多槐。其阴有谷，曰机谷，多䲦鸟，其状如录，食之已垫。', '《山海经·中山经》是创作于战国时期的一篇散文，出自《山海经》，作者不详。', '', '（注释“凡■为打不出来的字）
中央第一列山系：薄山山系之首座山，叫做甘枣山。共水从这座山发源，然后向西流入黄河。山上有茂密的杻树。山下有一种草，葵菜一样的茎干杏树一样的叶子，开黄色的花朵而结带荚的果实，名称是箨，人吃了它可以治愈眼睛昏花。山中还有一种野兽，形状像■鼠而额头上有花纹，名称是【左上革左下夫右能】，吃了它的肉就能治好人脖子上的赘瘤。再往东二十里，是座历儿山，山上有茂密的橿树，还有茂密的杤树，这种树木，茎干是方形的而叶子是圆形的，开黄色花而花瓣上有绒毛，果实像楝树结的果实，人服用它可以增强记忆而不忘事。再往东十五里，是座渠猪山，山上有茂盛的竹子。渠猪水从这座山发源，然后向南流入黄河。水中有很多豪鱼，形状像一般的鲔鱼，但长着红嘴巴和带羽毛的红尾巴，人吃了它的肉就能治愈白癣病。
再往东三十五里，是座葱聋山，山中有许多又深又长的峡谷，到处是白垩土，还有黑垩土、青垩土、黄垩土。再往东十五里，是座涹山，山上有丰富的黄铜，山北面盛产铁。又往东七十里，是座脱扈山。山中有一种草，形状像葵菜的叶子而是红花，结的是带荚的果实，果实的荚像棕树的果荚，名称是植楮，可以用它治愈精神抑忧症，而服食它就能使人不做恶梦。再往东二十里，是座金星山，山中有很多天婴，形状与龙骨相似，可以用来医治痤疮。再往东七十里，是座泰威山。山中有一道峡谷叫做枭谷，那里盛产铁。再往东十五里，是座橿谷山，山中有丰富的黄铜。再往东一百二十里，是座吴林山，山中生长着茂盛的兰草。再往北三十里，是座牛首山。山中生长着一种草，名称是鬼草，叶子像葵菜叶却是红色茎干，开的花像禾苗吐穗时的花絮，服食它就能使人无忧无虑。劳水从这座山发源，然后向西流入潏水，水中有很多飞鱼，形状像一般的鲫鱼，人吃了它的肉就能治愈痔疮和痢疾。再往北四十里，是座霍山，这里到处是茂密的构树。山中有一种野兽，形状像一般的野猫，却长着白尾巴，脖子上有鬃毛，名称是胐胐，人饲养它就可以消除忧愁。再往北五十二里，是座合谷山，这里到处是薝棘。再往北三十五里，是座阴山，多的是粗磨石、色彩斑斓的漂亮石头。少水从这座山发源。山中有茂密的雕棠树，叶子像榆树叶却呈四方形，结的果实像红豆，服食它就能治愈人的耳聋病。再往东四百里，是座鼓镫山，有丰富的黄铜。山中有一种草，名称是荣草，叶子与柳树叶相似，根茎与鸡蛋相似，人吃了它就能治愈风痹病。总计薄山山系之首尾，自甘枣山起到鼓镫山止，一共十五座山，途经六千六百七十里。历儿山，是诸山的宗主，祭祀宗主山山神：在毛物中，用猪、牛、羊齐全的三牲作祭品，再悬挂上吉玉献祭。祭祀其余十三座山的山神，在毛物中用一只羊作祭品，再悬挂上祀神玉器中的藻珪献祭，祭礼完毕把它埋入地下而不用米祀神。所谓藻珪，就是藻玉，下端呈长方形而上端有尖角，中间有穿孔并加上金饰物。
中央第二列山系：济山山系之首座山，叫做辉诸山，山上有茂密的桑树，山中的野兽大多是山驴和麋鹿，而禽鸟大多是鹖鸟。再往西南二百里，是座发视山，山上有丰富的金属矿物和玉石，山下多出产磨石。即鱼水从这座山发源，然后向西流入伊水。再往西三百里，是座豪山，山上有丰富的金属矿物和玉石而没有花草树木。再往西三百里，是座鲜山，有丰富的金属矿物和玉石，但不生长花草树木。鲜水从这座山发源，然后向北流入伊水。水中有很多鸣蛇，形状像一般的蛇却长着四只翅膀，叫声如同敲磐的声音，在哪个地方出现那里就会发生大旱灾。再往西三百里，是座阳山，到处是石头，没有花草树木。阳水从这座山发源，然后向北流入伊水。水中有很多化蛇，形状是人的面孔却长着豺一样的身子，有禽鸟的翅膀却像蛇一样地爬行，发出的声音如同人在呵斥，在哪个地方出现那里就会发生水害。
再往西二百里，是座昆吾山，山上有丰富的赤铜。山中有一种野兽，形状像一般的猪却长着角，发出的声音如同人号啕大哭，名称是蠪蚳，吃了它的肉就会使人不做恶梦。再往西一百二十里，是座葌山。葌水从这座山发源，然后向北流入伊水。山上盛产金属矿物和玉石，山下盛产石青、雄黄。山中有一种树木，形状像棠梨树而叶子是红色的，名称是芒草，能够毒死鱼。再往西一百五十里，是座独苏山，这里没有花草树木而到处是水流。再往西二百里，是座蔓渠山，山上有丰富的金属矿物和玉石，山下到处是小竹丛。伊水从这座山发源，然后向东流入洛水。山中有一种野兽，名称是马腹，形状是人一样的面孔虎一样的身子，发出的声音如同婴儿啼哭，是能吃人的。总计济山山系之首尾，自辉诸山起到蔓渠山止，一共九座山，途经一千六百七十里。诸山山神的形状都是人的面孔鸟的身子。祭祀山神要用毛物作祭品，再用一块吉玉，把这些投向山谷而不用米祀神。
中央第三列山系：萯山山系之首座山，叫做敖岸山，山南面多出产【王雩】琈玉，山北面多出产赭石、黄金。天神熏池住在这里。这座山还常常生出美玉来。从山上向北可以望见奔腾的黄河和葱郁的丛林，它们的形状好像是茜草和榉柳。山中有一种野兽，形状像一般的白鹿却长着四只角，名称是夫诸，在哪个地方出现那里就会发生水灾。再往东十里，是座青要山，确实是天帝的密都。从青要山上向北可以望见黄河的弯曲处，这里有许多野鹅。从青要山向南可以望见墠渚，是大禹的父亲鲧变化成为黄熊的地方，这里有很多蜗牛、蒲卢。山神武罗掌管着这里，这位山神的形貌是人的面孔却浑身长着豹子一样的斑纹，细小的腰身洁白的牙齿，而且耳朵上穿挂着金银环，发出的声音像玉石碰击作响。这座青要山，适宜女子居住。畛水从这座山发源，然后向北流入黄河。山中有一种禽鸟，名称是鴢，形状像野鸭子，青色的身子却是浅红色的眼睛深红色的尾巴，吃了它的肉就能使人多生孩子。山中生长着一种草，形状像兰草，却是四方形的茎干黄色的花朵、红色的果实，根部像稿本的根，名称是荀草，服用它就能使人的肤色洁白漂亮。
再往东十里，是座騩山，山上盛产味道甜美的枣子，山北阴面还盛产【王雩】琈玉。正回水从这座山发源，然后向北流入黄河。水中生长着许多飞鱼，形状像小猪却浑身是红色斑纹，吃了它的肉就能使人不怕打雷，还可以辟兵器。再往东四十里，是座宜苏山，山上有丰富的金属矿物和玉石，山下有繁茂的蔓荆。滽滽水从这座山流出，然后向北流入黄河，水中有很多黄色的贝。再往东二十里，是座和山，山上不生长花草树木而到处是瑶、碧一类的美玉，确实是黄河中的九条水源所汇聚的地方。这座山盘旋回转了五层，有九条水从这里发源，然后汇合起来向北流入黄河，水中有很多苍玉。吉神泰逢主管这座山，他的形貌像人却长着虎一样的尾巴，喜欢住在萯山向阳的南面，出入时都有闪光。泰逢这位吉神能兴起风云。总计萯山山系之首尾，自敖岸山起到和山止，一共五座山，途经四百四十里。祭祀诸山山神：泰逢、熏池、武罗三位神都是把一只公羊劈开来祭祀，祀神的玉器要用吉玉。其余二位山神是用一只公鸡献祭后埋入地下。祀神的米用稻米。
中央第四列山系：釐山山系之首座山，叫做鹿蹄山，山上盛产玉，山下盛产金。甘水从这座山发源，然后向北流入洛水，水中有很多汵石。往西五十里，是座扶猪山，山上到处是礝石。山中有一种野兽，形状像貉却长着人的眼睛，名称是【上鹿下言】。虢水从这座山发源，然后向北流入洛水，水中有很多礝石。再往西一百二十里，是座厘山，山南面有很多玉石，山北面有茂密的茜草。山中有一种野兽，形状像一般的牛，全身青黑色，发出的声音如同婴儿啼哭，是能吃人的，名称是犀渠。滽滽水从这座山发源，然后向南流入伊水。这里还有一种野兽，名称是【犭颉】，形状像獳犬却全身有鳞甲，长在鳞甲间的毛像猪鬃一样。再往西二百里，是座箕尾山，有茂密的构树，盛产涂石，山上还有许多【王雩】琈玉。
再往西二百五十里，是座柄山，山上盛产玉，山下盛产铜。滔雕水从这座山发源，然后向北流入洛水。山中有许多羬羊。山中还有一种树木，形状像臭椿树，叶子像梧桐叶而结出带荚的果实，名称是茇，是能毒死鱼的。
再往西二百里，是座白边山，山上有丰富的金属矿物和玉石，山下盛产石青、雄黄。再往西二百里，是座熊耳山，山上是茂密的漆树，山下是茂密的棕树。浮濠水从这座山发源，然后向西流入洛水，水中有很多水晶石，还有很多人鱼。山中有一种草，形状像苏草而开红花，名称是葶苎，是能毒死鱼的。再往西三百里，是座牡山，山上到处是色彩斑斓的漂亮石头，山下到处是竹箭、竹【上⺮下媚】之类的竹丛。山中的野兽以【牜乍】牛、羬羊最多，而禽鸟以赤鷩最多。再往西三百五十里，是讙举山。雒水从这座山发源，然后向东北流入玄扈水。玄扈山中生有很多马肠这样的怪物。在讙举山与玄扈山之间，夹着一条洛水。总计厘山山系之首尾，自鹿蹄山起到玄扈山止，一共九座山，途经一千六百七十里。诸山山神的形貌都是人的面孔而兽的身子。祭祀山神：在毛物中用一只白色鸡献祭，祀神不用米，用彩色帛把鸡包裹起来。
中央第五列山系：薄山山系之首座山，叫做苟林山，不生长花草树木，到处是奇形怪状的石头往东三百里，是座首山，山北面有茂密的构树、柞树，这里的草以■草、芫华居多。山南面盛产■琈玉，这里的树木以槐树居多。这座山的北面有一峡谷，叫做机谷，峡谷里有许多■鸟，形状像猫头鹰却长着三只眼睛，还有耳朵，发出的声音如同鹿鸣叫，人吃了它的肉就会治好湿气病。再往东三百里，是座县■山，没有花草树木，到处是色彩斑斓的漂亮石头。再往东三百里，是座葱聋山，没有花草树木，到处是■石。往东北五百里，是座条谷山，这里的树木大多是槐树和桐树，而草大多是芍药、门冬草。
再往北十里，是座超山，山北面到处是苍玉，山南面有一眼水泉，冬天有水而到夏天就干枯了。
再往东五百里，是座成侯山，山上是茂密的櫄树，这里的草以秦艽居多再往东五百里，是座朝歌山，山谷里多出产优良垩土。再往东五百里，是座槐山，山谷里有丰富的金和锡。再往东十里，是座历山，这里的树大多是槐树，山南面多出产玉石。再往东十里，是座尸山，到处是苍玉，这里的野兽以麖居多。尸水从这座山发源，向南流入洛水，水中有很多优良玉石再往东十里，是座良余山，山上有茂密的构树和柞树，没有石头。余水从良余山北麓流出，然后向北流入黄河；乳水从良余山南麓流出，然后向东南流入洛水。再往东南十里，是座蛊尾山，盛产粗磨石、黄铜。龙余水从这座山发源，然后向东南流入洛水。再往东北二十里，是座升山，这里的树以构树、柞树、酸枣树居多，而草以山药、惠草居多，还有茂密的寇脱草。黄酸水从这座山发源，然后向北流入黄河，水中有很多璇玉。
再往东二十里，是座阳虚山，盛产金，阳虚山临近玄扈水。总计薄山山系之首尾，自苟林山起到阳虚山止，一共十六座山，途经二千九百八十二里。升山，是诸山的宗主，祭祀升山山神的典礼：在毛物中用猪、牛、羊齐全的三牲作祭品，祀神的玉器要用吉玉。首山，是神灵显应的大山，祭祀首山山神用稻米、整只黑色皮毛的猪、牛、羊、美酒；手持盾牌起舞，摆上鼓并敲击应和；祀神的玉器用一块玉璧。尸水，是上通到天的，要用肥壮的牲畜作祭品献祭；用一只黑狗作祭品供在上面，用一只母鸡作祭品供在下面，杀一只母羊，献上血。祀神的玉器要用吉玉，并用彩色帛包装祭品，请神享用。
中央第六列山系缟羝山山系之首座山，叫做平逢山，从平逢山上向南可以望见伊水和洛水，向东可以望见谷城山，这座山不生长花草树木，没有水，到处是沙子石头。山中有一山神，形貌像人却长着两个脑袋，叫做骄虫，是所有螫虫的首领，也确实是各种蜜蜂聚集做巢的地方。祭祀这位山神，用一只公鸡作祭品，在祈祷后放掉而不杀。往西十里，是座缟羝山，没有花草树木，有丰富的金属矿物和玉石。再往西十里，是座廆山，山上盛产■浮玉。在这座山的阴面有一道峡谷，叫做雚谷，这里的树木大多是柳树、构树。山中有一种禽鸟，形状像野鸡却拖着一条长长的尾巴，身上通红如火却是青色嘴巴，名称是鸰■，它发出的叫声便是自身名称的读音，吃了它的肉就能使人不做恶梦。交觞水从这座山的南麓流出，然后向南流入洛水；俞随水从这座山的北麓流出，然后向北流入谷水。
再往西三十里，是座瞻诸山，山南面盛产金属矿物，山北面盛产带有花纹的漂亮石头。■水从这座山发源，然后向东南流入洛水；少水从这座山的北麓流出，然后向东流入谷水。再往西三十里，是座娄涿山，没有花草树木，有丰富的金属矿物和玉石。瞻水从这座山的南麓流出，然后向东流入洛水；陂水从这座山的北麓流出，然后向北流入谷水，水中有很多紫颜色的石头、带有花纹的漂亮石头。再往西四十里，是座白石山。惠水从白石山的南麓流出，然后向南流入洛水，水中有很多水晶石。涧水从白石山的北麓流出，向西北流入谷水，水中有很多画眉石、黑丹沙。再往西五十里，是座谷山，山上是茂密的构树，山下是茂密的桑树。爽水从这座山发源，然后向西北流入谷水，水中有很多孔雀石。
再往西七十二里，是座密山，山南面盛产玉，山北面盛产铁。豪水从这座山发源，然后向南流入洛水，水中有很多旋龟，形状像鸟一样的头而鳖一样的尾巴，发出的声音好像劈木头声。这座山不生长花草树木。再往西一百里，是座长石山，没有花草树木，有丰富的金属矿物和玉石。这座山的西面有一道峡谷，叫做共谷，生长许多竹子。共水从这座山发源，向西南流入洛水，水中多产鸣石。再往西一百四十里，是座傅山，没有花草树木，到处是瑶、碧之类的美玉。厌染水从这座山的南麓流出，然后向南流入洛水，水中有很多人鱼。这座山的西面有一片树林，叫做墦冢。谷水从这里流出，然后向东南流入洛水，水中有很多珚玉。再往西五十里，是座橐山，山中的树木大多是臭椿树，还有很多■树，山南面有丰富的金属矿物和玉石，山北面有丰富的铁，还有茂密的萧草。橐水从这座山发源，然后向北流入黄河。水中有很多脩辟鱼，形状像一般的蛙却长着白色嘴巴，发出的声音如同鹞鹰鸣叫，人吃了它的肉就能治愈白癣病。
往西九十里，是座常烝山，没有花草树木，有多种颜色的垩土。潐水从这座山发源，然后向东北流入黄河，水中有很多苍玉。菑水也从这座山发源，然后向北流入黄河。再往西九十里，是座夸父山，山中的树木以棕树和楠木树最多，还有茂盛的小竹丛，山中的野兽，以■牛、羬羊最多，而禽鸟以赤鷩最多，山南面盛产玉，山北面盛产铁。这座山北面有一片树林，叫做桃林，这片树林方圆三百里，林子里有很多马。湖水从这座山发源，然后向北流入黄河，水中多出产珚玉。
再往西九十里，是座阳华山，山南面有丰富的金属矿物和玉石，山北面盛产石青、雄黄，山中的草以山药最多，还有茂密的苦辛草，形状像楸木，结的果实像瓜，味道是酸中带甜，人服食它就能治愈疟疾。杨水从这座山发源，然后向西南流入洛水，水中有很多人鱼。门水也从这座山发源，然后向东北流入黄河，水中有很多黑色磨石。■姑水从阳华山北麓流出，然后向东流入门水，■姑水两岸山间有丰富的铜。从门水到黄河，流经七百九十里后注入■水。总计缟羝山山系之首尾，自平逢山起到阳华山止，一共十四座山，途经七百九十里。有大山岳在这一山系中，在每年六月祭祀它，一如祭祀其它山岳的方法，那么天下就会安宁。
中央第七列山系苦山山系之首座山，叫做休与山。山上有一种石子，是神仙帝台的棋，它们有五种颜色并带着斑纹，形状与鹌鹑蛋相似。神仙帝台的石子，是用来祷祀百神的，人佩带上它就会不受邪毒之气侵染。休与山还有一种草，形状像一般的蓍草，红色的叶子而根茎连结丛生在一起，名称是夙条，可以用来做箭杆。往东三百里，是座鼓钟山，神仙帝台正是在此演奏钟鼓之乐而宴会诸位天神的。山中有一种草，方形的茎干上开着黄色花朵，圆形的叶子重叠为三层，名称是焉酸，可以用来解毒。山上多出产粗磨石，山下多出产细磨石。再往东二百里，是座姑媱山，天帝的女儿就死在这座山，她的名字叫女尸，死后化成了■草，叶子都是一层一层的，花儿是黄色的，果实与菟丝子的果实相似，女子服用了就能使她漂亮而讨人喜爱。
再往东二十里，是座苦山。山中有一种野兽，名称是山膏，形状像普通的小猪，身上红得如同丹火，喜欢骂人。山上有一种树木，名称是黄棘，黄色花而圆叶子，果实与兰草的果实相似，女人服用了它就不生育孩子。山中又有一种草，圆圆的叶子而没有茎干，开红色花却不结果实，名称是无条，服用了它就能使人的脖子不生长肉瘤。再往东二十七里，是座堵山，神人天愚住在这里，所以这座山上时常刮起怪风下起怪雨。山上生长着一种树木，名称是天匾，方方的茎干而像葵菜形状，服用了它就能使人吃饭不噎住。再往东五十二里，是座放皋山。明水从这座山发源，向南流入伊水，水中有很多苍玉。山中有一种树木，叶子与槐树叶相似，开黄色花却不结果实，名称是蒙木，服用了它就能使人不糊涂。山中有一种野兽，形状像蜜蜂，长着分叉的尾巴和倒转的舌头，喜欢呼叫，名称是文文。
再往东五十里，是座大■山，盛产■琈玉，还有许多麋玉。山中有一种草，叶子与榆树叶相似，方方的茎干上长满刺，名称是牛伤，根茎上有青色斑纹，服用了它就能使人不得昏厥病，还能辟兵器。狂水从这座山的南麓流出，向西南流入伊水，水中有很多长着三只脚的龟，吃了它的肉就能使人不生大病，还能消除痈肿。再往东七十里，是座半石山。山上长着一种草，一出土就结子实，高一丈多，红色叶子红色花，开花后不结子实，名称是嘉荣，服用它就能使人不畏惧霹雳雷响。来需水从半石山南麓流出，然后向西流入伊水，水中生长着很多■鱼，浑身长满黑色斑纹，形状像普通的鲫鱼，人吃了它的肉不感觉瞌睡。合水从半石山北麓流出，然后向北流入洛水，水中生长着很多鱼，形状像一般的鳜鱼，隐居水底洞穴，浑身青色斑纹却拖着一条红尾巴，人吃了它的肉就不患痈肿病，还可以治好瘘疮。
再往东五十里，是座少室山，各种花草树木丛集像圆的谷仓。山上有一种树木，名称是帝休，叶子的形状与杨树叶相似，树枝相互交叉着伸向四方，开黄色花结黑色果实，服用了它就能使人心平气和不恼怒。少室山上有丰富的玉石，山下有丰富的铁。休水从这座山发源，然后向北流入洛水，水中有很多■鱼，形状像猕猴却有长长的像公鸡一样的爪子，白白的足趾而相对着，人吃了它的肉就没了疑心病，还能辟兵器。
再往东三十里，是座泰室山。山上有一种树木，叶子的形状像梨树叶却有红色纹理，名称是栯木，人服用了它就没了嫉妒心。山中还有一种草，形状像苍术或白术，开白色花结黑色果实，果实的光泽就像野葡萄，名称是■草，服用了它就能使人的眼睛明亮不昏花。山上还有很多漂亮的石头。再往北三十里，是座讲山，山上盛产玉石，有很多的柘树、许多的柏树。山中有一种树木，名称是帝屋，叶子的形状与花椒树叶相似，长着倒勾刺而结红色果实，可以辟凶邪之气。
再往北三十里，是座婴梁山，山上盛产苍玉，而苍玉都附着在黑色石头上面。再往东三十里，是座浮戏山。山中生长着一种树木，叶子的形状像臭椿树叶而结红色果实，名称是亢木，人吃了它可以驱虫辟邪。汜水从这座山发源，然后向北流入黄河。在浮戏山的东面有一道峡谷，因峡谷里有很多蛇而取名叫蛇谷，峡谷上面还多产细辛。
再往东四十里，是座少陉山。山中有一种草，名称是■草，叶子形状与葵菜叶相似，又是红色的茎干白色的花，果实很像野葡萄，服食了它就能使人增长智慧而不笨拙。器难水从这座山发源，然后向北流入役水。再往东南十里，是座太山。山里有一种草，名称是梨，叶子的形状像蒿草叶而开红色花，可以用来治疗痈疽。太水从这座山的南麓流出，然后向东南流入役水；承水从这座山的北麓流出，然后向东北流入役水。再往东二十里，是座末山，山上到处是黄金。末水从这座山发源，向北流入役水。再往东二十五里，是座役山，山上有丰富的白银，还有丰富的铁。役水从这座山发源，向北流入黄河。再往东三十五里，是座敏山。山上生长着一种树木，形状与牡荆相似，开白色花朵而结红色果实，名称是■柏，吃了它的果实就能使人不怕寒冷。敏山南面还盛产■琈玉。
再往东三十里，是座大騩山，山北面有丰富的铁、优质玉石、青色垩土。山中有一种草，形状像蓍草却长着绒毛，开青色花而结白色果实，名称是■，人服食了它就能不夭折而延年益寿，还可以医治肠胃上的各种疾病。总计苦山山系之首尾，自休与山起到大騩山止，一共十九座山，途经一千一百八十四里。其中有十六座山的山神，形貌都是猪的身子而人的面孔。祭祀这些山神：在毛物中用一只纯色的羊献祭，祀神的玉器用一块藻玉而在祭祀后埋入地下。苦山、少室山、太室山都是诸山的宗主。祭祀这三座山的山神：在毛物中用猪、牛、羊齐全的三牲作祭品，在祀神的玉器中用吉玉。这三个山神的形貌都是人的面孔却长着三个脑袋。另外那十六座山的山神都是猪的身子而人的面孔。
中央第八列山系荆山山系之首座山，叫做景山，山上有丰富的金属矿物和玉石，这里的树木以柞树和檀树最多。雎水从这座山发源，向东南流入江水，水中有很多粟粒大小的丹沙，还生长着许多有彩色斑纹的鱼。往东北一百里，是座荆山，山北面有丰富的铁，山南面有丰富的黄金，山中生长着许多犛牛，还有众多的豹子和老虎，这里的树木以松树和柏树最多，这里的花草以丛生的小竹子最多，还有许多的橘子树和柚子树。漳水从这座山发源，然后向东南流入雎水，水中盛产黄金，并生长着很多鲨鱼。山中的野兽以山驴和麋鹿最多。再往东北一百五十里，是座骄山，山上有丰富的玉石，山下有丰富的青雘，这里的树木以松树和柏树居多，到处是桃枝和钩端一类的丛生小竹子。神仙■围居住在这座山中，形貌像人而长着羊一样的角，虎一样的爪子，常常在雎水和漳水的深渊里畅游，出入时都有闪光。
再往东北一百二十里，是座女几山，山上盛产玉石，山下盛产黄金，山中的野兽以豹子和老虎最多，还有许许多多的山驴、麋鹿、麖、麂，这里的禽鸟以白■最多，还有很多的长尾巴野鸡，很多的鸩鸟。再往东北二百里，是座宜诸山，山上多出产金属矿物和玉石，山下多出产青雘。洈水从这座山发源，然后向南流入漳水，水中有很多白色玉石。再往东北二百里，是座纶山，在山中茂密的丛林中多的是梓树、楠木树，又有很多丛生的桃枝竹，还有许多的柤树、栗子树、橘子树、柚子树，这里的野兽以山驴、麈、羚羊、■最多。再往东二百里，是座陆■山，山下盛产■琈玉，山下盛产各种颜色的垩土，这里的树木以杻树和橿树居多。再往东一百三十里，是座光山，山上到处有碧玉，山下到处流水。神仙计蒙居住在这座山里，形貌是人的身子而龙的头，常常在漳水的深渊里畅游，出入时一定有旋风急雨相伴随。
再往东一百五十里，是座岐山，山南面多出产黄金，山北面多出产白色珉石，山上有丰富的金属矿物和玉石，山下有丰富的青雘，这里的树木以臭椿树居多。神仙涉■就住在这座山里，形貌是人的身子而方形面孔和三只脚。再往东一百三十里，是座铜山，山上有丰富的金、银、铁，这里的树木以构树、柞树、柤树、栗子树、橘子树、柚子树最多，而野兽多是长着豹子斑纹的犳。再往东北一百里，是座美山，山中的野兽以兕、野牛最多，又有很多山驴、麈，还有许多野猪、鹿，山上多出产金，山下多出产青雘。再往东北一百里，是座大尧山，在山里的树木中以松树和柏树居多，又有众多的梓树和桑树，还有许多机木树，这里的草大多是丛生的小竹子，而野兽以豹子、老虎、羚羊、■最多。再往东北三百里，是座灵山，山上有丰富的金属矿物和玉石，山下盛产青雘，这里的树木大多是桃树、李树、梅树、杏树。再往东北七十里，是座龙山，山上到处是寄生树，还盛产碧玉，山下有丰富的红色锡土，而草大多是桃枝、钩端之类的小竹丛。再往东南五十里，是座衡山，山上有许多寄生树、构树、柞树，还盛产黄色垩土、白色垩土。再往东南七十里，是座石山，山上多出产金，山下有丰富的青雘，还有许多寄生树。
再往南一百二十里，是座若山，山上多出产■琈玉，又多出产赭石，也有很多封石，到处长着寄生树，还生长着许许多多的柘树。再往东南一百二十里，是座彘山，有很多漂亮的石头，到处生长着柘树。再往东南一百五十里，是座玉山，山上有丰富的金属矿物和玉石，山下有丰富的碧玉、铁，这里的树木以柏树居多。再往东南七十里，是座讙山，这里的树木大多是檀树，还盛产封石，又多出产白色锡土。郁水从这座山顶上发源，潜流到山下，水中有很多磨石。再往东北一百五十里，是座仁举山，这里的树木以构树和柞树居多，山南面有丰富的黄金，山北面多出产赭石再往东五十里，是座师每山，山南面多出产磨石，山北面多出产青雘，山中的树木以柏树居多，又有很多檀树，还生长着大量柘树，而草大多是丛生的小竹子。再往东南二百里，是座琴鼓山，这里的树木大多是构树、柞树、椒树、柘树，山上多出产白色珉石，山下多出产洗石，这里的野兽，以野猪、鹿最多，还有许多白色犀牛，而禽鸟大多是鸩鸟。总计荆山山系之首尾，自景山起到琴鼓山止，一共二十三座山，途经二千八百九十里。诸山山神的形貌都是鸟的身子而人的面孔。祭祀山神：在毛物中用一只公鸡祭祀后埋入地下，并用一块藻圭献祭，祀神的米用稻米。骄山，是诸山之宗主。祭祀骄山山神：用进献的美酒和猪、羊来祭祀而后埋入地下，在祀神的玉器中用一块玉璧。
中央第九列山系岷山山系之首座山，叫做女几山，山上多出产石涅，这里的树木以杻树、橿树居多，而花草以野菊、苍术或白术居多。洛水从这座山发源，向东流入长江。山里到处有雄黄，而野兽以老虎、豹子最多。再往东北三百里，是座岷山。长江从岷山发源，向东北流入大海，水中生长着许多优良的龟，还有许多鼍。山上有丰富的金属矿物和玉石，山下盛产白色珉石。山中的树木以梅树和海棠树最多，而野兽以犀牛和大象最多，还有大量的夔牛，这里的禽鸟大多是白翰鸟和赤鷩鸟。
再往东北一百四十里，是座崃山。江水从这座山发源，向东流入长江。山南面盛产黄金，山北面到处有麋鹿和麈，这里的树木大多是檀树和柘树，而花草大多是野薤菜和野韭菜，还有许多白芷和寇脱。
再往东一百五十里，是座崌山。江水从这座山发源，向东流入长江，水中生长着许多怪蛇，还有很多■鱼。这里的树木以楢树和杻树居多，还有很多梅树与梓树，而野兽以夔牛、羚羊、■、犀牛、兕最多。山中有一种禽鸟，形状像一般的猫头鹰却是红色的身子白色的脑袋，名称是窃脂，人饲养它可以辟火。再往东一百五十里，是座崌山。江水从这座山发源，向东流入长江，水中生长着许多怪蛇，还有很多■鱼。这里的树木以楢树和杻树居多，还有很多梅树与梓树，而野兽以夔牛、羚羊、■、犀牛、兕最多。山中有一种禽鸟，形状像一般的猫头鹰却是红色的身子白色的脑袋，名称是窃脂，人饲养它可以辟火。
再往东三百里，是座高梁山，山上盛产垩土，山下盛产磨石，这里的草木大多是桃枝竹和钩端竹。山中生长着一种草，形状像葵菜却是红色的花朵、带荚的果实、白色的花萼，给马吃了它就能使马跑得快。再往东四百里，是座蛇山，山上多出产黄金，山下多出产垩土，这里的树木以栒树最多，还有许多豫章树，而花草以嘉荣、细辛最多。山中有一种野兽，形状像一般的狐狸，却长着白尾巴和长耳朵，名称是■狼，在哪个国家出现哪个国家就会有战争。
再往东五百里，是座鬲山，山南面盛产金，山北面盛产白色珉石。蒲鹳水从这座山发源，然后向东流入长江，水中有很多白色玉石。山中的野兽以犀牛、大象、熊、罴最多，还有许多猿猴、长尾猿。再往东北三百里，是座隅阳山，山上有丰富的金属矿物和玉石，山下有丰富的青雘，这里的树木大多是梓树和桑树，而草大多是紫草。徐水从这座山发源，向东流入长江，水中有许多粟粒大小的丹沙。再往东二百五十里，是座岐山，山上有丰富的白银，山下有丰富的铁，这里的树木以梅树和梓树居多，还有许多杻树和楢树。减水从这座山发源，向东南流入长江。
再往东三百里，是座勾■山，山上盛产玉石，山下盛产黄金，这里的树木大多是栎树和柘树，而花草大多是芍药。再往东一百五十里，是座风雨山，山上多出产白银，山下多出产石涅，这里的树木以棷：树和椫树居多，杨树也不少。宣余水从这座山发源，向东流入长江，水中有很多水蛇。山里的野兽以山驴和麋鹿最多，还有许多的麈、豹子、老虎，而禽鸟大多是白■。再往东二百里，是座玉山，山南面多出产铜，山北面多出产黄金，这里的树木以豫章树、楢树、杻树最多，而野兽以野猪、鹿、羚羊、■最多，禽鸟大多是鸩鸟。再往东一百五十里，是座熊山。山中有一洞穴，是熊的巢穴，也时常有神人出入。洞穴一般是夏季开启而冬季关闭；就是这个洞穴，如果冬季开启就一定发生战争。山上多出产白色玉石，山下多出产白银。山里的树木以臭椿树和柳树居多，而花草以寇脱草最多见。
再往东一百四十里，是座騩山，山南面盛产美玉黄金，山北面盛产铁，这里的草木以桃枝竹、牡荆树、枸杞树最多。再往东二百里，是座葛山，山上多出产黄金，山下多出产瑊石，这里的树木以柤树、栗子树、橘子树、柚子树、楢树、杻树居多，而野兽以羚羊和■居多，花草大多是嘉荣。再往东一百七十里，是座贾超山，山南面多出产黄色垩土，山北面多出产精美赭石，这里的树木大多是柤树、栗子树、橘子树、柚子树，山中的草以龙须草最多。总计岷山山系之首尾，自女几山起到贾超山止，一共十六座山，途经三千五百里，诸山山神的形貌都是马的身子而龙的脑袋。祭祀山神：在毛物中用一只公鸡作祭品埋入地下，祀神的米用稻米。文山、勾■山、风雨山、騩山，是诸山的宗主。祭祀这几座山的山神：进献美酒，用猪、羊作祭品，在祀神的玉器中用一块吉玉。熊山，是诸山的首领。祭祀这个山神：进献美酒，用猪、牛、羊齐全的三牲作祭品，在祀神的玉器中用一块玉璧。手拿盾牌舞蹈，为了禳除战争灾祸；祈求福祥，就穿戴礼服并手持美玉而舞蹈。
中央第十列山系之首座山，叫做首阳山，山上有丰富的金属矿物和玉石，没有花草树木。再往西五十里，是座虎尾山，这里树木以花椒树、椐树最多，到处有封石，山南面有丰富的黄金，山北面有丰富的铁。再往西南五十里，是座繁缋山，这里的树木大多是楢树和杻树，而草大多是桃枝、钩端之类的小竹丛。再往西南二十里，是座勇石山，不生长花草树木，有丰富的白银，到处流水。再往西二十里，是座复州山，这里的树木以檀树居多，山南面有丰富的黄金。山中有一种禽鸟，形状像一般的猫头鹰，却长着一只爪子和猪一样的尾巴，名称是跂踵，在哪个国家出现哪个国家就会发生大瘟疫。
再往西三十里，是座楮山，生长着茂密的寄生树，到处是花椒树、椐树，柘树也不少，还有大量的垩土。再往西二十里，是座又原山，山南面有丰富的青雘，山北面有丰富的铁，这里的禽鸟以八哥最多。再往西五十里，是座涿山，这里的树木大多是构树、柞树、杻树，山南面多出产■琈玉。再往西七十里，是座丙山，这里的树木大多是梓树、檀树，还有很多弞杻树。总计首阳山山系之首尾，自首阳山起到丙山止，一共九座山，途经二百六十七里。诸山山神的形貌都是龙的身子而人的面孔。祭祀山神：在毛物中用一只公鸡献祭后埋入地下，祀神的米用五种粮米。堵山，是诸山的宗主，祭祀这个山神：用猪、羊二牲作祭品，进献美酒来祭祀，在玉器中用一块玉璧，祀神后埋入地下。騩山，是诸山的首领，祭祀騩山山神要进献美酒，用猪、牛、羊齐全的三牲作祭品；让女巫师和男祝师二人一起跳舞，在玉器中用一块玉璧来祭祀。
中央第十一列山系荆山山系之首座山，叫做翼望山。湍水从这座山发源，向东流入济水；贶水也从这座山发源，向东南流入汉水，水中有很多蛟。山上到处是松树和柏树，山下有茂密的漆树和梓树，山南面多出产黄金，山北面多出产珉石。再往东北一百五十里，是座朝歌山。■水从这座山发源，向东南流入荥水，水中生长着很多人鱼。山上有茂密的梓树、楠木材，这里的野兽以羚羊、麋鹿最多。山中有一种草，名称是莽草，能够毒死鱼的。再往东南二百里，是座帝囷山，山南面有丰富的■琈玉，山北面有丰富的铁。帝囷水从这座山顶上发源，潜流到山下，水中有很多长着四只翅膀的鸣蛇。再往东南五十里，是座视山，山上到处是野韭菜。山中有一口井，叫做天井，夏天有水，冬天枯竭。山上有茂密的桑树，还有丰富的优良垩土、金属矿物、玉石。再往东南二百里，是座前山，这里的树木以槠树居多，还有不少的柏树，山南面盛产金，山北面盛产赭石。再往东南三百里，是座丰山。山中有一种野兽，形状像猿猴，却长着红眼睛、红嘴巴、黄色的身子，名称是雍和，在哪个国家出现那个国家里就会发生大恐怖。神仙耕父住在这座山里，常常在清泠渊畅游，出入时都有闪光，在哪个国家出现那个国家就要衰败。这座山还有九口钟，它们都应和霜的降落而鸣响。山上有丰富的金，山下有茂密的构树、柞树、杻树、橿树。
再往东北八百里，是座兔床山，山南面有丰富的铁，山里的树木以槠树和芧树最多，而花草以鸡谷草最多，它的根茎像鸡蛋似的，味道是酸中带甜，服食它是对人的身体有益的。再往东六十里，是座皮山，有大量的垩土，还有大量的赭石，这里的树木大多是松树和柏树。再往东六十里，是座瑶碧山，这里的树木以梓树和楠木树最多，山北阴面盛产青雘，山南面盛产白银。山中有一种禽鸟，形状像一般的野鸡，常吃蜚虫，名称是鸩。再往东四十里，是座攻离山。淯水从这座山发源，向南流入汉水。山中有一种禽鸟，名称是婴勺，形状像普通的喜鹊，却长着红眼睛、红嘴巴、白色的身子，尾巴与酒勺的形状相似，它发出的叫声便是自身名称的读音。这座山中还有很多■牛、羬羊。
再往东北五十里，是座祑■山，山上有茂密的松树、柏树、桤树、桓树。再往西北一百里，是座堇理山，山上有茂密的松树柏树，还有很多优良梓树，山北阴面多出产青雘，并且有丰富的金，这里的野兽以豹子和老虎最多。山中有一种禽鸟，形状像一般的喜鹊，却是青色的身子白色的嘴巴，白色的眼睛白色的尾巴，名称是青耕，人饲养它可以辟瘟疫，它发出的叫声便是自身名称的读音。再往东南三十里，是座依轱山，山上有茂密的杻树和橿树，柤树也不少。山中有一种野兽，形状像普通的狗，长着老虎一样的爪子而身上又有鳞甲，名称是獜，擅长跳跃腾扑，吃了它的肉就能使人不患风痹病。
再往东南三十五里，是座即谷山，这里多出产优良玉石，有很多黑豹，还有不少的山驴和麈，羚羊和■也很多。山南阳面盛产珉石，山北阴面盛产青雘。再往东南四十里，是座鸡山，山上到处是优良梓树，还有茂密的桑树，而花草以野韭菜为最多。再往东南五十里，是座高前山。这座山上有一条溪水，非常冰凉而又特别清澈，是神仙帝台所用过的浆水，饮用了它就能使人不患心痛病。山上有丰富的金，山下有丰富的赭石。再往东南三十里，是座游戏山，这里有茂密的杻树、橿树、构树，还有丰富的玉石，封石也很多。再往东南三十五里，是座从山，山上到处是松树和柏树，山下有茂密的竹丛。从水由这座山顶上发源，潜流到山下，水中有很多三足鳖，长着叉开的尾巴，吃了它的肉就能使人不患疑心病。再往东南三十里，是座婴■山，山上到处是松树柏树，山下有茂密的梓树、櫄树。再往东南三十里，是座毕山。帝苑水从这座山发源，向东北流入瀙水，水中多出产水晶石，还有很多蛟。山上有丰富的■琈玉。
再往东南二十里，是座乐马山。山中有一种野兽，形状像一般的刺猬，全身赤红如丹火，名称是■，在哪个国家出现那个国家里就会发生大瘟疫。
再往东南二十五里，是座葴山，瀙水从这座山发源，向东南流入汝水，水中有很多人鱼，又有很多蛟，还有很多的颉。再往东四十里，是座婴山，山下有丰富的青雘，山上有丰富的金属矿物和玉石。再往东三十里，是座虎首山，有茂密的柤树、椆树、椐树。再往东二十里，是座婴矦山，山上多出产封石，山下多出产红色锡土。再往东五十里，是座大孰山。杀水从这座山发源，向东北流入瀙水，沿岸到处是白色垩土。再往东四十里，是座卑山，山上有茂密的桃树、李树、柤树、梓树，还有很多紫藤树。再往东三十里，是座倚帝山，山上有丰富的玉石，山下有丰富的金。山中有一种野兽，形状像鼣鼠，长着白耳朵白嘴巴，名称是狙如，在哪个国家出现那个国家里就会发生大战争。
再往东三十里，是座鲵山。鲵水从这座山顶上发源，潜流到山下，这里有很多优良垩土。山上有丰富的金，山下有丰富的青雘。再往东三十里，是座雅山。澧水从这座山发源，向东流入瀙水，水中有很多大鱼。山上有茂密的优良桑树，山下有茂密的柤树，这里还多出产黄金。再往东五十里，是座宣山。沦水从这座山发源，向东南流入瀙水，水中有很多蛟。山上有一种桑树，树干合抱有五十尺粗细，树枝交叉伸向四方，树叶方圆有一尺多，红色的纹理、黄色的花朵、青色的花萼，名称是帝女桑。
再往东四十五里，是座衡山，山上盛产青雘，还有茂密的桑树，这里的禽鸟以八哥最多。再往东四十里，是座丰山，山上多出产封石，这里的树木大多是桑树，还有大量的羊桃，形状像一般的桃树却是方方的茎干，可以用它医治人的皮肤肿胀病。再往东七十里，是座妪山，山上盛产优良玉石，山下盛产金，这里的花草以鸡谷草最为繁盛。再往东三十里，是座鲜山，这里的树木以楢树、杻树、柤树最多，花草以蔷薇最多，山南阳面有丰富的金，山北阴面有丰富的铁。山中有一种野兽，形状像膜犬，长着红嘴巴、红眼睛、白尾巴，在哪个地方出现那里就会有火灾，名称是■即。再往东三十里，是座章山，山南阳面多出产金，山北阴面多出产漂亮的石头。皋水从这座山发源，向东流入澧水，水中有许多脃石再往东二十五里，是座大支山，山南阳面有丰富的金，这里的树木大多是构树和柞树，但不生长草。再往东五十里，是座区吴山，这里的树木以柤树为最繁盛。
再往东五十里，是座声匈山，这里有茂密的构树，到处是玉石，山上还盛产封石。再往东五十里，是座大騩山，山南阳面多出产黄金，山北阴面多出产细磨石。再往东十里，是座踵臼山，不生长花草树木。再往东北七十里，是座历石山，这里的树木以牡荆和枸杞最多，山南阳面盛产黄金，山北阴面盛产细磨石。山中有一种野兽，形状像野猫，却长着白色的脑袋老虎一样的爪子，名称是梁渠，在哪个国家出现那个国家里就会发生大战争。再往东南一百里，是座求山，求水从这座山顶上发源，潜流到山下，这里有很多优良赭石。山中到处是柤树，还有矮小丛生的■竹。山南阳面有丰富的金，山北阴面有丰富的铁。再往东二百里，是座丑阳山，山上有茂密的椆树和椐树。山中有一种禽鸟，形状像一般的乌鸦却长着红色爪子，名称是■■，人饲养它可以辟火。
再往东三百里，是座奥山，山上有茂密的松树、杻树、橿树，山南阳面盛产■琈玉。奥水从这座山发源，向东流入瀙水。再往东三十五里，是座服山，这里的树木以柤树最多，山上有丰富的封石，山下多出产红色锡土。再往东三百一十里，是座杳山，山上到处是嘉荣草，还有丰富的金属矿物和玉石。再往东三百五十里，是座■山，这里的树木，以楢树、檀树、杻树最多，而草类主要是各种香草。山中有一种野兽，形状像普通的猪，却是黄色的身子、白色的脑袋、白色的尾巴，名称是闻膦，一出现天下就会刮起大风。总计荆山山系之首尾，自翼望山起到■山止，一共四十八座山，途经三千七百三十二里。诸山山神的形貌都是猪的身子而人的头。祭祀山神：在毛物中用一只公鸡来祭祀后而埋入地下，在祀神的玉器中用一块玉珪献祭，祀神的米用黍、稷、稻、粱、麦五种粮米。禾山，是诸山的首领。祭祀禾山山神：在毛物中用猪、牛、羊齐全的三牲作祭品，进献后埋入地下，而且将牲畜倒着埋；在祀神的玉器中用一块玉璧献祭，但也不必三牲全备。堵山、玉山，是诸山的宗主，祭祀后都要将牲畜倒着埋掉，进献的祭祀品是用猪、羊，在祀神的玉器中要用一块吉玉。
中央第十二列山系洞庭山山系之首座山，是座篇遇山，这里不生花草树木，蕴藏着丰富的黄金。再往东南五十里，是座云山，不生长花草树木。但有一种桂竹，毒性特别大，枝叶刺着人就必死。山上盛产黄金，山下盛产■琈玉。再往东南一百三十里，是座龟山，这里的树木以构树、柞树、椆树、椐树最为繁盛，山上多出产黄金，山下多出产石青、雄黄，还有很多扶竹。再往东七十里，是座丙山，有茂密的桂竹，还有丰富的黄金、铜、铁，但没有树木。再往东南五十里，是座风伯山，山上有丰富的金属矿物和玉石，山下盛产痠石、色彩斑斓的漂亮石头，还盛产铁，这里的树木以柳树、杻树、檀树、构树最盛多。在风伯山东面有一片树林，叫做莽浮林，其中有许多的优良树木和禽鸟野兽。
再往东一百五十里，是座夫夫山，山上多出产黄金，山下多出产石青、雄黄，这里的树木以桑树、构树最多，而花草以竹子、鸡谷草最为繁盛。神仙于儿就住在这座山里，形貌是人的身子却手握两条蛇，常常游玩于长江水的深渊中，出没时都有闪光。再往东南一百二十里，是座洞庭山，山上多出产黄金，山下多出产银和铁，这里的树木以柤树、梨树、橘子树、柚子树居多，而花草以兰草、蘪芜、芍药、芎等香草居多。天帝的两个女儿住在这座山里，她俩常在长江水的深渊中游玩。从澧水和沅水吹来的清风，交会在幽清的湘水渊潭上，这里正是九条江水汇合的中间，她俩出入时都有旋风急雨相伴随。洞庭山中还住着很多怪神，形貌像人而身上绕着蛇，左右两只手也握着蛇。这里还有许多怪鸟。再往东南一百八十里，是座暴山，在茂密的草木中以棕树、楠木树、牡荆树、枸杞树和竹子、箭竹、■竹、箘竹居多，山上多出产黄金、玉石，山下多出产彩色花纹的漂亮石头、铁，这里的野兽以麋鹿、鹿、麂居多，这里的禽鸟大多是鹫鹰。再往东南二百里，是座即公山，山上多出产黄金，山下多出产■琈玉，这里的树木以柳树、杻树、檀树、桑树最多。山中生长着一种野兽，形状像一般的乌龟，却是白身子红脑袋，名称是蛫，人饲养它可以辟火。再往东南一百五十九里，是座尧山，山北阴面多出产黄色垩土，山南阳面多出产黄金，这里的树木以牡荆树、枸杞树、柳树、檀树最多，而草以山药、苍术或白术最为繁盛。
再往东南一百里，是座江浮山，山上盛产银、磨石，这里没有花草树木，而野兽以野猪、鹿居多。再往东二百里，是座真陵山，山上多出产黄金，山下多出产玉石，这里的树木以构树、柞树、柳树、杻树最多，而草大多是可以医治风痹病的荣草。再往东南一百二十里，是座阳帝山，到处是优质铜，这里的树木大多是橿树、杻树、山桑树、楮树，而野兽以羚羊和麝香鹿最多。再往南九十里，是座柴桑山，山上盛产银，山下盛产碧玉，到处是柔软如泥的汵石、赭石，这里的树木以柳树、枸杞树、楮树、桑树居多，而野兽以麋鹿、鹿居多，还有许多白色蛇、飞蛇。再往东二百三十里，是座荣余山，山上多出产铜，山下多出产银，这里的树木大多是柳树、枸杞树，这里的虫类有很多怪蛇、怪虫。总计洞庭山山系之首尾，自篇遇山起到荣余山止，一共十五座山，途经二千八百里。诸山山神的形貌都是鸟的身子龙的脑袋。祭祀山神：在毛物中宰杀一只公鸡、一头母猪作祭品，祀神的米用稻米。凡夫夫山、即公山、尧山、阳帝山，都是诸山的宗主，祭祀这几座山的山神：都要陈列牲畜、玉器而后埋入地下，祈神用美酒献祭，在毛物中用猪、羊二牲作祭品，在祀神的玉器中要用吉玉。洞庭山、荣余山，是神灵显应之山，祭祀这二位山神：都要陈列牲畜、玉器而后埋入地下，祈神用美酒及猪、牛、羊齐全的三牲献祭，祀神的玉器要用十五块玉圭十五块玉璧，用青、黄、赤、白、黑五样色彩绘饰它们。
总计天下名山共有五千三百七十座，分布在大地之东西南北中各方，一共六万四千零五十六里。', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f77911759740c9ca2da", "shortContent": "希腊神话中有“阿喀琉斯的足踵”之传说：勇士阿喀琉斯，遍体刀枪不入，所向无敌，后敌人知其足踵系唯一致命弱点，乃刺之，勇士竟以此死。本文中的风生兽，也颇有阿喀琉斯之风，火燃锤锻，皆不能死之，惜其鼻子，却是阿氏的足踵一流，被“石上菖蒲”（此物亦不易得，可见杀中国神兽难于杀外国勇士）一堵，马上就一命呜呼了。这则故事，大可资今日之从事比较文学者一用。\n不过，要杀死风生兽，也诚是难事。火攻不成，几大车的柴，统...", "authors": ["沈维藩"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522504706, '5abf237b7565710045a396bf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636823, '穀梁传 · 郑伯克段于鄢', NULL, 4, 4, 0, 1, '穀梁子', NULL, 36790, '586e4968da2f600055d635c5', '周', 'wen', '文', '', '', '克者何？能也。何能也？能杀也。何以不言杀？见段之有徒众也。
段，郑伯弟也。何以知其为弟也？杀世子、母弟目君，以其目君知其为弟也。段，弟也，而弗谓弟；公子也，而弗谓公子。贬之也。段失子弟之道矣，贱段而甚郑伯也。何甚乎郑伯？甚郑伯之处心积虑成于杀也。
于鄢，远也，犹曰取之其母之怀之云尔，甚之也。
然则为郑伯者，宜奈何？缓追，逸贼，亲亲之道也。
', '', '', '克是什么意思？就是能够的意思。能够做什么呢？能够杀人。为什么不直接说杀呢？因为要表示出追随共叔段的人很多。
共叔段是郑伯的弟弟，怎么知道他是弟弟的呢？因为假如国君杀了嫡亲的长子，或者同母所生的弟弟，便用国君的爵号称呼他，文中既然已经称呼郑伯，那么也就知道共叔段是郑伯的弟弟了。共叔段既然是国君的弟弟，却不称他为弟弟；共叔段应当是公子，也不称他为公子，这是对他的贬斥，因为共叔段已经丧失了一个公子和弟弟所应有的道德以为。但是《春秋》鄙视郑伯的程度超过了对共叔段的批评。在什么地方超过了对共叔段的批评？因为经文并未对郑伯想尽一切方式，想要杀掉弟弟的意愿提出批评。
但经文说在鄢这个地方杀掉共叔段的，表明共叔段已经跑到远离郑国都城的地方了。就好比说是从母亲的怀中夺过婴儿杀掉，这又是郑伯做得过分的地方。
既然这样，那么对郑伯来说最好的方法是什么呢？就是不要急着追杀已经逃远了的乱臣，而应该遵循兄弟之间相亲相敬的道德。', NULL, '', 'indent', 1522340155, '5abca0b99f54540038760dd3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636837, '忆江南', NULL, 75, 395, 1, 0, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', '', '', '春去也，人在画楼东。芳草绿粘天一角，落花红沁水三弓。好景共谁同？', '', '画楼：雕饰华丽的楼房。
弓：旧时丈量地亩用的器具和计算单位。', '', NULL, '', 'indent', 1522422444, '5abde22a9f54541656d117b1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636844, '穀梁传 · 虞师晋师灭夏阳', NULL, 6, 4, 0, 1, '穀梁子', NULL, 36790, '586e4968da2f600055d635c5', '周', 'wen', '文', 'https://baike.baidu.com/item/%E8%99%9E%E5%B8%88%E6%99%8B%E5%B8%88%E7%81%AD%E5%A4%8F%E9%98%B3/9269334?fr=aladdin', '', '非国而曰灭，重夏阳也。虞无师，其曰师，何也？以其先晋，不可以不言师也。其先晋何也？为主乎灭夏阳也。夏阳者，虞、虢之塞邑也。灭夏阳而虞、虢举矣。虞之为主乎灭夏阳何也？晋献公欲伐虢，荀息曰：“君何不以屈产之乘、垂棘之璧，而借道乎虞也？”公曰：“此晋国之宝也。如受吾币而不借吾道，则如之何？”荀息曰：“此小国之所以事大国也。彼不借吾道，必不敢受吾币。如受吾币而借吾道，则是我取之中府，而藏之外府；取之中厩，而置之外厩也。”公曰：“宫之奇存焉，必不使受之也。”荀息曰：“宫之奇之为人也，达心而懦，又少长于君。达心则其言略，懦则不能强谏；少长于君，则君轻之。且夫玩好在耳目之前，而患在一国之后，此中知以上乃能虑之。臣料虞君中知以下也。”公遂借道而伐虢。宫之奇谏曰：“晋国之使者，其辞卑而币重，必不便于虞。”虞公弗听，遂受其币，而借之道。宫之奇又谏曰：“语曰：‘唇亡齿寒。’其斯之谓与！”挈其妻、子以奔曹。献公亡虢，五年而后举虞。荀息牵马操璧而前曰：“璧则犹是也，而马齿加长矣。”', '《虞师晋师灭夏阳》是战国时期穀梁子的散文。《穀梁传》它用简练的语言述评了晋国灭亡虞国、虢国的历史事件，深刻地说明了“唇亡齿寒”的道理。', '虞：周文王时就已建立的姬姓小国，在今山西省平陆县北。
晋：西周始封姬姓国，晋献公时都于绛（今山西省翼城县东南）。
师：可泛指军队，也可专指古代军队的编制单位。《荀子·礼论》：“师旅有制。”五百人为旅，五旅为师。下面传文说“虞无师”，就是专指二千五百人的军队编制。
夏阳：虢邑，在今山西省平陆县东北约三十五里。《左传》作下阳，因另有上阳，以作下阳为是。夏、下同音通假。
虢：周初始封姬姓国，有东、西、北虢之分，东虢、西虢已先亡于郑、秦。晋献公所伐为北虢，占地当今河南三门峡和山西平陆一带，建都上阳（今河南陕县李家窑村）。
举：攻克，占领。
晋献公（？——前651）：名诡诸，晋武公之子，在位二十六年。在此期间伐灭了周围一些小国，为其子晋文公称霸打下了基础。据《史记·晋世家》，晋献公伐虢的借口是虢国在晋国内乱中支持了他先君的政敌。
荀息（？——前651）：晋献公最亲信的大夫，食邑于荀，亦称荀叔。献公病危时以荀息为相托以国政，献公死后在宫廷政变中为里克所杀。
屈：即北屈，晋地名，在今山西省吉县东北。
乘（shèng）：古以一车四马称为一乘。这里专指马。
垂棘：晋地名，在今山西省潞城县北。
府：古时国家收藏财物、文书的地方。
宫之奇：虞大夫，刘向《说苑·尊贤》说：“虞有宫之奇，晋献公为之终死不寐。”
曹：西周始封姬姓国，都陶丘（今山东省定陶县西南）。
马齿：马每岁增生一齿。
加长（zhǎng）：增添。', '不是国都而说灭，是看重夏阳。虞国的军队不足一个师，《春秋》说是师，为什么呢？因为虞国写在晋国之前，不可以不说师。它写在晋国之前是为什么呢？灭夏阳是它为主的。夏阳，是虞、虢交界处虢国的一个要塞。夏阳一失，虞、虢两国都可占领了。虞国为什么要为主灭夏阳呢？晋献公想要讨伐虢国，荀息说：“君主为什么不用北屈出产的马，垂棘出产的璧，向虞国借路呢？”献公说：“这是晋的国宝，如果受了我的礼物而不借路给我，那又拿它怎么办？”荀息说：“这些东西是小国用来服事大国的。它不借路给我们，一定不敢接受我们的礼物。如受了我们的礼而借路给我们，那就是我们从里面的库藏里拿出来，而藏在外面的库藏里，从里面的马房里拿出来，而放在外面的马房里。”献公说：“宫之奇在，一定不让的。”荀息说：“宫之奇的为人，心里明白，可是怯懦，又比虞君大不了几岁。心里明白，话就说得简短，怯懦就不能拚命谏阻，比虞君大不了几岁，虞君就不尊重他。再加上珍玩心爱的东西就在耳目之前，而灾祸在一个国家之后，这一点要有中等智力以上的人才能考虑到。臣料想虞君是中等智力以下的人。”献公就借路征伐虢国。宫之奇劝谏说：“晋国的使者言辞谦卑而礼物隆重，一定对虞国没有好处。”虞公不听，就接受了晋国的礼物而借路给晋国。宫之奇又谏道：“俗语说：‘唇亡齿寒。’岂不就说的这件事吗！”他带领自己的老婆孩子投奔到曹国去了。晋献公灭了虢国，五年以后占领了虞国。荀息牵着马捧着璧，走上前来说：“璧还是这样，而马的牙齿增加了。”', NULL, '', 'indent', 1522423473, '5abde61517d00900614b3a20', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636845, '礼记 · 檀弓 · 晋献公杀世子申生', NULL, 2, 16, 0, 1, '无名氏', NULL, 11747, '5858e6c01b69e60056f614c4', '秦', 'wen', '文', 'https://baike.baidu.com/item/%E6%99%8B%E7%8C%AE%E5%85%AC%E6%9D%80%E4%B8%96%E5%AD%90%E7%94%B3%E7%94%9F/8541558?fr=aladdin', '', '晋献公将杀其世子申生，公子重耳谓之曰：「子盍言子之志于公乎？」世子曰：「不可。君安骊姬，是我伤公之心也。」曰：「然则盍行乎？」世子曰：「不可。君谓我欲弑君也。天下岂有无父之国哉？吾何行如之？」
使人辞于狐突曰：「申生有罪，不念伯氏之言也，以至于死。申生不敢爱其死。虽然，吾君老矣，子少，国家多难。伯氏不出而图吾君，伯氏苟出而图吾君，申生受赐而死。」再拜稽首，乃卒。是以为恭世子也。', '本文选自《礼记·檀弓上》，描写晋国世子申生为奉行「忠孝」，甘受骊姬诬陷，在面临死亡时的心理状态。这个史实是晋国史上著名的「骊姬之难」的一个插曲。事详见《国语·晋语》和《左传·僖公四年》。', '晋献公：晋国国君。公元前六七六年至公元前六五一年在位。世子：又称太子，是天子或诸侯的嫡长子，君位继承人。申生：晋献公嫡长子，夫人齐姜所生。献公宠妾骊姬生子奚齐，骊姬恃宠欲废申生而立奚齐，借献公出外打猎之时，骊姬让太子申生去曲沃祭祀其生母，太子把祭肉祭酒带回献给献公，骊姬在酒肉里下了毒药，待献公打猎回来献上去，以酒祭地，土突起；以肉饲犬，犬死。骊姬诬陷太子弑父。献公听信谗言，逼迫申生自缢。公子重耳、夷吾也被牵连，为避祸而出逃。
重耳：申生异母弟，即晋文公。
盍（hé）：通“何”，何不。
安：安逸，安适，舒服。
何行如之：到哪里去呢？如，到……去。
辞：辞别，诀别。
狐突：姓狐，名突，字伯行，申生的师傅，重耳的外祖父。
伯氏：对狐突的敬称。念：记住。伯氏之言：鲁闵公二年，晋献公命申生领兵伐东山皋落氏（赤狄别种，在今山西垣曲东南），狐突劝申生乘机出逃，申生没有采纳他的意见。
爱其死：吝惜其死。
子：君之子，指骊姬之子奚齐，时年六岁。国家多难：申生预料死后，其弟兄将因争夺君位而相互残杀。“伯氏”二句：是两个相关的假设句。不出：狐突劝申生出逃，申生没有听从，狐突在伐东山皋落氏以后，就推托有病，在家不出。图吾君：为吾君图。图，谋划，策划。赐：恩惠。稽首：叩头到地，最恭敬的跪拜礼。恭：申生的谥号。“恭”是敬顺事上的意思。申生明知父命是错误的，却仍然顺从而自杀，所以谥“恭”。', '晋献公要杀死他的世子申生，公子重耳对申生说：「你怎么不把心中的委屈向父亲表明呢？」世子说：「不行。君王要有骊姬才舒服，我要是揭发她对我的诬陷，那就太伤老人家的心了。」重耳又说：「既然这样，那么你何不逃走呢？」世子说：「不行。君王认准我要谋害他。天下哪有没有父亲的国家呢？（谁会收留背着弑父罪名的人）我能逃到哪里去呢？」
于是申生派人去向师傅狐突诀别说：「申生有罪，没有听从您的教导，以至难免一死。申生不敢贪生怕死。然而，我的国君老了，他的爱子奚齐还年幼，国家将会多灾多难。您不出来为国君谋划政事也就罢了，如果您出来为国君筹划政事，申生虽死也蒙受您的恩惠。」于是拜了两拜，叩了头，就自杀了。因此他的谥号为「恭世子」。

这篇一百五十字的短文，没有议论，没有说教，甚至没有一句客观的描述和抒情的词语，有的只是一段对话，一段独白，完全通过人物自己的语言来塑造人物形象。然而，它却写得委婉曲折，血泪交织，十分动情。
晋献公宠爱骊姬，骊姬为使自己亲生儿子奚齐能继承君位就诬陷太子，说太子要谋杀其父献公，献公轻信骊姬，逼迫太子申生自尽。申生在被谗蒙冤的情况下，既不申辩以伤君父之心，也不出逃以扬君父之过，终于含冤自杀。文章头一句「晋献公将杀其世子申生」，开始就造成一种恐怖、紧张而充满悬念的气氛。骊姬因阴谋得逞而偷着乐的得意神情，老而昏聩的献公要杀亲子的愤怒与沉痛，尽在不言中。而申生众多的兄弟们，满朝的文武大臣们，亲者，仇者又会有什么反应？申生自己有什么反应？都令读者产生悬念。然而被杀者申生却坦然自若，从容面对死亡。作者把残酷的环境与申生坦然的心境加以强烈地对比，并在对比的反差中，揭示人物的忠孝之心，塑造人物的形象。先是重耳与申生的对话。申生对重耳的「盍言」、「盍行」的回答，一不辩白，是怕伤老父的心；二不出走，是怕扬父之过。一般情况下的忠孝，不会引人注目；儿子蒙受亲生父亲的冤屈，能无怨无恨，从容就死，就不能不给人留下深刻印象。如果说申生与重耳的对话，表现了申生尽忠尽孝于生前；那么，申生派人代表他与老师狐突的诀别辞，乃是尽忠孝于身后。「伯氏」二句，表明申生在临死前，念念不忘的还是君国，想的还是在自己死后贤士大夫如何帮助君上治国安邦。「吾君老矣，子少，国家多难。」这十个字，既表现了他临死前的清醒认识，也显示了他对国家命运的忧患以及对老父、幼弟的深切关爱。饱含感情，一字一泪。这种愚忠愚孝，今天看来，过于迂腐，未免可笑，但此文之所以催人泪下，似乎也正在于一个「愚」字。', NULL, '', 'indent', 1522423687, '5abde7052f301e0065e7b6c2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636846, '礼记 · 檀弓 · 曾子易箦', NULL, 6, 16, 0, 1, '无名氏', NULL, 11747, '5858e6c01b69e60056f614c4', '秦', 'wen', '文', 'https://baike.baidu.com/item/%E6%9B%BE%E5%AD%90%E6%98%93%E7%AE%A6/7804241?fr=aladdin', '', '曾子寝疾，病。乐正子春坐于床下，曾元、曾申坐于足，童子隅坐而执烛。童子曰：「华而睆，大夫之箦与？」子春曰：「止！」曾子闻之，瞿然曰：「呼！」曰：「华而睆，大夫之箦与？」曾子曰：「然。斯季孙之赐也，我未之能易也。元，起易箦。」曾元曰：「夫子之病革矣，不可以变。幸而至于旦，请敬易之。」曾子曰：「尔之爱我也不如彼。君子之爱人也以德，细人之爱人也以姑息。吾何求哉？吾得正而毙焉斯已矣。」举扶而易之。反席未安而没。', '曾子易箦选自《礼记》檀弓上，《古文观止》中亦有收录。曾子，姓曾，名参，字子舆，春秋末年鲁国南武城（现山东省今济宁市嘉祥县）人。孔子弟子之一。曾子是一个视守礼法甚于生命的人，他没有做过大夫，无意中用了大夫专用的席子。假如他死在大夫专用的席子上，那就是「非礼」了，哪怕是处于弥留之际，也依然命令儿子给他更换席子，刚换完，他就无憾而终了。文中曾子的形象惟妙惟肖，他以身护礼，言行一致的学者的风度得以充分的表现。', '曾子：即曾参，孔子弟子。
寝疾：病倒，卧病，此偏向于病倒。寝，睡卧。疾，小病。
乐正子春：曾参的弟子。
曾元、曾申：都是曾子的儿子。
隅：名词作状语，在角落。
华而睆（huǎn）：华美，光滑。
箦（zé）：席子。
瞿然：惊叹的样子。
季孙︰鲁国大夫；曾子受其赐箦，非礼也。
革：通「亟」，指病重。
变：在此指移动
姑息：无原则的宽容
正而毙︰谓合于正礼而殁。
反：同「返」。
没：同：「殁」，死。', '曾子躺在床上，病危。曾子的弟子子春坐在床旁边，曾元、曾申坐在床脚下，童仆坐在角落拿着蜡烛。童仆说：「华美而光洁，（那是）大夫（才能享用）的竹席啊！」子春说：「住嘴！」曾子听见这话，惊惧地说：「啊！」（童仆又）说：「华美而光洁，（那是）大夫（才能享用）的竹席啊！」曾子说：「是的。那是季孙送的，我没有啊。（曾）元，（扶我）起来换竹席。」曾元说：「您的病非常严重啊，不能移动（您的身体啊）。（如果）幸运地到了早晨，一定遵从您的意思换了它。」曾子说：「你爱我不如他（童仆）。按照道德标准去爱护人，小人爱人以无原则迁就。我还有什么苛求啊？我能得到（封建礼教的）正道而死去，也就足够了。」（曾元）扶着抬起（他的身体）然后更换竹席，把他送回席子，还没躺好就死了。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d30ce818559d064c40", "shortContent": "这三则小故事选自《礼记·檀弓》。《礼记》是西汉戴圣编纂的儒家关于礼的一些文字，过去列为儒家的经典。《檀弓》分上下二篇。郑玄解释这个篇名说：“名曰檀弓者，以其善于礼，故著姓名以显之，檀姓，弓名。”清孙希旦《礼记集解》不赞成郑玄这个解释说：“愚谓此篇盖七十子之弟子所作。篇首记檀弓事，故以檀弓名篇，非因其善礼著之也。”现在从孙说较多。\n第一则选自《檀弓上》。也有的选本加个名字叫《曾子易箦》。故事先写曾子...", "authors": ["周本淳"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522423747, '5abde7419f54540045a23249', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636847, '礼记 · 檀弓 · 有子之言似夫子', NULL, 5, 16, 0, 1, '无名氏', NULL, 11747, '5858e6c01b69e60056f614c4', '秦', 'wen', '文', 'https://baike.baidu.com/item/%E6%9C%89%E5%AD%90%E4%B9%8B%E8%A8%80%E4%BC%BC%E5%A4%AB%E5%AD%90/8544828?fr=aladdin', '', '有子问于曾子曰：「问丧于夫子乎？」曰：「闻之矣：‘丧欲速贫，死欲速朽’。」有子曰：「是非君子之言也。」曾子曰：「参也闻诸夫子也。」有子又曰：「是非君子之言也。」曾子曰：「参也与子游闻之。」有子曰：「然。然则夫子有为言之也。」
曾子以斯言告于子游。子游曰：「甚哉，有子之言似夫子也！昔者，夫子居于宋，见桓司马自为石椁，三年而不成。夫子曰：‘若是其靡也，死不如速朽之愈也。’‘死之欲速朽’，为桓司马言之也。南宫敬叔反，必载宝而朝。夫子曰：‘若是其货也，丧不如速贫之愈也。’丧之欲速贫，为敬叔言之也。」
曾子以子游之言告于有子。有子曰：「然！吾固曰非夫子之言也。」曾子曰：「子何以知之？」有子曰：「夫子制于中都：四寸之棺，五寸之椁。以斯知不欲速朽也。昔者夫子失鲁司寇，将之荆，盖先之以子夏，又申之以冉有。以斯知不欲速贫也。」', '本文记叙的是孔子的弟子对「丧欲速贫，死欲速朽」的含义的相互探讨。由于思考方法的不同，对同一句话，弟子们有着不同的理解。有子能够不片面、不孤立地去判断，而且和孔子的一贯言行相联；子游能够根据孔子讲话的背景，针对的问题进行分析；曾子则是句句照搬，孤立、片面地理解。文章分析问题的方式对今人仍有很大的借鉴作用。', '有子：孔子的弟子有若。
问：当作「闻」（依《经典释文》）。
丧：失去。此处置失去了官职。（依《古文观止》）。
丧欲速贫：失去官位之后，只想穷的快点才好。
参：曾子，名参，字子舆。
有为言之：有所指而言，即「有所为言」。
桓司马：宋人，名魋（tuí）
椁（guǒ）：套在棺材外面的大棺材。
靡：浪费、奢侈。
愈：较好、胜过。
南宫敬叔：鲁孟僖子之子仲孙阅，曾失位离开鲁国，返时载宝物朝见鲁君。
反：同「返」。
货：贿赂。
制：立规定，定制度。
申：申明。', '有子问曾子道：「在先生（孔子）那里听说过失去官职方面的事情吗？」（曾子）说：「听他说的是：‘希望丢官后赶快贫穷，希望死后赶快腐烂’。」有子说：「这不是君子说的话。」曾子说：「我（的确是）从先生（孔子）那听来的。」有子又说：「这不是君子说的话。」曾子说：「我是和子游一起听见这话的。」有子说：「的确（说过）。但先生这样说肯定是有原因的。」 曾子将这话告诉子游。子游说：「有子说话很象先生啊！那时先生住在宋国，看见桓司马给自己做石椁，三年还没完成。先生说：‘像这样奢靡，（人）不如死了赶快腐烂掉越快越好啊。希望（人）死了赶快腐烂，是针对桓司马而说的。 南宫敬叔（他原来失去官职，离开了鲁国）回国，必定带上宝物朝见国王。先生说：‘像这样对待钱财（行贿），丢掉官职（以后）不如赶紧贫穷越快越好啊。’希望丢掉官职以后迅速贫穷，是针对敬叔说的啊。」 曾子将子游的话告诉有子。有子说：「是啊。我就说了不是先生的话吗。」曾子说：「您怎么知道的呢？」有子说：「先生给中都制定的礼法中有：棺材（板）四寸，椁（板）五寸。依据这知道（先生）不希望（人死后）迅速腐烂啊。从前先生失去鲁国司寇的官职时，打算前往楚国，就先让子夏去（打听），又让冉有去申明（自己的想法）。依据这知道（先生）不希望（失去官职后）迅速贫穷。」', NULL, '', 'indent', 1522423884, '5abde7cba22b9d00452fd688', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636848, '礼记 · 檀弓 · 公子重耳对秦客', NULL, 2, 16, 0, 1, '无名氏', NULL, 11747, '5858e6c01b69e60056f614c4', '秦', 'wen', '文', 'https://baike.baidu.com/item/%E5%85%AC%E5%AD%90%E9%87%8D%E8%80%B3%E5%AF%B9%E7%A7%A6%E5%AE%A2/5156787?fr=aladdin', '', '晋献公之丧，秦穆公使人吊公子重耳，且曰：「寡人闻之，亡国恒于斯，得国恒于斯。虽吾子俨然在忧服之中，丧亦不可久也，时亦不可失也，孺子其图之！」
以告舅犯。舅犯曰：「孺子其辞焉。丧人无宝，仁亲以为宝。父死之谓何？又因以为利，而天下其孰能说之？孺子其辞焉！」公子重耳对客曰：「君惠吊亡臣重耳。身丧父死，不得与于哭泣之哀，以为君忧。父死之谓何？或敢有他志，以辱君义。」稽颡而不拜，哭而起，起而不私。
子显以致命于穆公。穆公曰：「仁夫公子重耳！夫稽颡而不拜，则未为后也，故不成拜。哭而起，则爱父也。起而不私，则远利也。」 ', '', '吊：致吊唁
恒：经常
斯：此，这
惠：施予恩惠
丧：流亡在外
或：表疑问
稽颡（qǐsǎng）：古代一种跪拜礼，屈膝下拜，以额触地，表示极度的虔诚。
後：後嗣，继承人。根据古时候的丧礼，先稽颡而后拜，那是继承人答谢客人的敬礼。
远：避开', '晋国献公的丧期，秦国穆公派人慰问公子重耳，并且传达自己的话说：「寡人听说：失去国家（君主权）常常在这个时候，得到国家（君主权也）常常在这个时候。虽然我的先生您恭敬严肃，在忧伤的服丧期间，居丧也不可太久，时机也不可失去啊，年轻人，请考虑一下吧！」
（重耳）将这事告诉舅舅子犯。舅舅子犯说：「年轻人还是推辞吧。居丧之人没有值得宝贵的东西，可珍贵的只有仁爱和亲情。父亲死去这是何等重大的事情啊？还要用这事来谋利，那么天下谁能说清（我们无罪过）啊？年轻人还是推辞吧。」公子重耳（便）对（秦国的）客人说：「君王赏脸吊唁流亡的我重耳，（我）在父亲死去居丧（的时候），不能参与到哭泣（表达）悲哀的丧礼中去，而让您操心了。父亲死去这是何等重大的事情啊？（我）哪里还有其他的图谋来辜负您（来慰问我）的情义啊？」（重耳）行稽颡之礼但不拜谢（秦国来的客人），哭着起身，起身后但不（跟秦国来的客人）私下交谈。
子显复命将事情告诉穆公。穆公说：「仁人啊，公子重耳！叩拜但不拜谢，是他没已晋献公的继承人而自居，所以没有拜谢。哭着起身，就表示敬爱父亲。起身但不私谈，就表示远离个人利益啊。」', NULL, '', 'indent', 1522424034, '5abde861a22b9d00452fdb01', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636849, '礼记 · 檀弓 · 杜蒉扬觯', NULL, 2, 16, 0, 1, '无名氏', NULL, 11747, '5858e6c01b69e60056f614c4', '秦', 'wen', '文', 'https://baike.baidu.com/item/%E6%9D%9C%E8%92%89%E6%89%AC%E8%A7%AF/7001731?fr=aladdin', '', '知悼子卒，未葬．平公饮酒，师旷、李调侍，鼓钟。杜篑自外来，闻钟声，曰：「安在？」曰：「在寝。」杜篑入寝，历阶而升．酌曰：「旷饮斯。」又酌曰：「调饮斯．」又酌，堂上北面坐饮之。降，趋而出。
平公呼而进之，曰：「蒉，曩者尔心或开予，是以不与尔言。尔饮旷，何也？」曰：「子卯不乐。知悼子在堂，斯其为子卯也大矣！旷也，太师也，不以诏．是以饮之也。」「尔饮调，何也？」曰：「调也，君之亵臣也，为一饮一食，亡君之疾。是以饮之也．」「尔饮，何也？」曰：「篑也，宰夫也，非刀匕是共，又敢与知防．是饮之也．」平公曰：「寡人亦有过焉。酌而饮寡人！」杜篑洗而扬觯。
公谓侍者曰：「如我死，则必无废是爵也！」至于今，既毕献，斯扬觯，谓之「杜举」。', '杜蒉扬觯是属于《杜蒉扬觯》的一个故事，出处《礼记·檀弓》。', '知（zhì）悼子：春秋时晋国大夫，知罃。知庄公的儿子。悼是他的谥号。
平公：晋平公，名彪。
师旷：晋国的乐官。
李调：晋平公的近臣。
侍：作陪。
鼓钟：敲钟。
杜篑（kuì）：《左传》作「屠蒯（kuǎi）」，晋国的宰夫。寝：寝宫。古时天子的叫燕寝，诸侯的叫路寝。
酌：斟酒。
堂上北面坐饮之：古时人君的位置朝南，臣子见君时则面向北。杜篑北面而坐，以面向国君行臣礼了。坐：即跪。因为古时席地而坐，坐时两膝跪在席上，屁股坐在脚后跟上，屁股稍稍离开脚后跟就成为跪了，所以跪也叫坐。但坐不可以叫跪。
降：下阶。
趋：快走。
曩者：刚纔。
子卯不乐：夏桀以乙卯日死，商纣以甲子日亡，古人把它叫做疾日，所以做国君的不举乐。
在堂：指知悼子的灵柩还放在家里没有下葬。
斯其为子卯也大矣：古时国君对于卿大夫，人刚死不举乐，人刚下葬不吃肉。悼子是亲近的大臣，死了还没有下葬，人君的哀痛，应当甚于桀纣的疾日，所以说大于子卯。
太师：乐官之长。
亵臣：轻慢的近臣。
疾：疾日，犹言恶日、忌日。
宰夫：主管国君膳食的小官。
匕：古代指饭勺。
与：参与，与闻。知：知谏。防：防闲。敢与知防，是说杜蒉不过是一个宰夫，又敢参与知谏争防闲之事，这是越级行为。
爵：酒器。
扬：举起。
觯（zhì）：古时饮酒用的器皿。', '知悼子死，还没有下葬。平公饮酒（作乐），师旷、李调陪伴侍奉，敲击编钟（演奏乐曲）。杜蒉从外面来，听到编钟声，说：「（平公）在哪？」（仆人）说：「在寝宫。」杜蒉前往寝宫，拾阶而上。斟酒道：「师旷干了这杯。」又斟酒道：「李调乾了这杯。」又斟酒，在大厅的北面（面对平公）坐下乾了酒。走下台阶，跑着出去。
平公喊他进来，说：「蒉，刚纔我心想你可能要开导我，因此不跟你说话。你罚师旷喝酒，是为什么啊？」（杜蒉）说：「子日和卯日不演奏乐曲（据说夏朝的桀王逃亡在山西安邑县于乙卯日死亡；商朝的纣王在甲子日自焚死亡。后代君王引以为戒，以子卯日为『疾日』，不演奏乐曲）。知悼子还在堂上（停灵），这事与子卯日相比大多了！师旷，是太师啊。（他）不告诉您道理，因此罚他喝酒啊。」「你罚李调喝酒，（又是）为什么呢？」（杜蒉）说：「李调，是君主身边的近臣。为了一点喝的一点吃食忘记了君主的忌讳，因此罚他喝酒啊。」「你自己（罚自己）喝酒，（又是）为什么呢？」（杜蒉）说：「我杜蒉，膳食官而已，不去管刀勺的事务，却敢干预（对君主）讲道理防范错误的事，因此罚自己喝酒。」平公说：「我也有过错啊。斟酒来罚我。」杜蒉洗乾净然后高高举起酒杯。平公对侍从们说：「如果我死了，千万不要丢弃这酒杯啊。」
直到今天，（人们）敬完酒后，都要高举酒杯，叫作「杜举」。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1e2d635634aee3eab31", "shortContent": "从魏晋时代起，诙谐嘲戏一类作品的写作兴盛起来，故刘勰《文心雕龙·谐隐》云：“魏晋滑稽，盛相驱扇。”此类作品，使人开颜一笑，解乏消忧，也可表现作者之巧思，故一些著名文士，都有所作，南朝时作者仍然不少。刘宋袁淑，史称其“博涉多通，好属文，辞采遒艳，纵横有才辩”（《宋书》本传）；当皇室内乱、弑逆将行之际，他宁死不从逆谋，被称为“怀忠陨难”，“义重乎生”（同上）。总之，他是一个博学能文、性格倔强的人。而他...", "authors": ["杨", "明"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522424096, '5abde89fee920a0045fbf729', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636850, '礼记 · 檀弓 · 晋献文子成室', NULL, 5, 16, 0, 1, '无名氏', NULL, 11747, '5858e6c01b69e60056f614c4', '秦', 'wen', '文', 'https://baike.baidu.com/item/%E6%99%8B%E7%8C%AE%E6%96%87%E5%AD%90%E6%88%90%E5%AE%A4/4109590?fr=aladdin', '', '晋献文子成室，晋大夫发焉。张老曰：“美哉，轮焉！美哉，奂焉！歌于斯，哭于斯，聚国族于斯！”文子曰：“武也，得歌于斯，哭于斯，聚国族于斯，是全要领以从先大夫于九京也！”北面再拜稽首。君子谓之善颂善祷。', '《晋献文子成室》出自《礼记·檀弓下》，该文讲的是晋国赵文子宫室落成，晋国的大夫发礼前往致贺之事。全文未分段落，但可以分三个层次来赏析。成语“美轮美奂”的典故出于此文。本篇反映的虽然只是当时卿大夫之间的应酬之辞，但张老的颂辞，别出心裁，文子的答话，也与众不同。', '献：进献礼物，引申为祝贺。
文子：赵武（西元前五九六年—西元前五四五年）的谥号。这是后人追记，所以称谥号。
成室：新屋落成。
发：送礼庆贺。
张老：前去送礼物的晋大夫张孟。张氏是姬姓的一个分支，三家分晋后，多属韩国。
轮：盘旋屈曲而上，引申为高大。
奂：通“焕”，华丽。
歌于斯：在这里祭祀时奏乐唱诗。歌，此处代指祭礼。斯，此。
哭于斯：死丧哭泣在这屋里。哭，指家族死丧哭泣之事。
聚国族：聚，聚会。国，国宾。族，宗族。
武：赵武自称。
全要领：免于斩戮之刑。要，通“腰”。领，脖颈。古时罪重则腰斩，罪轻则戮颈，砍头。
先大夫：自称已故的祖、父。赵氏自赵衰以来世代为晋卿。
九京：当作“九原”。晋国卿大夫的墓地，在今山西绛县北。
北面：面向北。古代堂礼，长辈面南而坐，小辈北向而拜。
再拜：拱手礼两次。稽（qǐ）首：叩头。
稽（qǐ）首：叩头到地，伏地停留片刻方起，叫稽首。是九拜（九种拜的礼节）中最恭敬的。
善：擅长。', '晋国献文子的新居落成，晋国的大夫们都去送礼致贺。张老说：“多美呀，如此高大宽敞！多美呀，如此金碧辉煌！既可以在这里祭祀唱诗，也可以在这里居丧哭泣，还可以在这里宴请国宾、聚会宗族！”文子说：“我赵武能够在这里祭祀唱诗，在这里居丧哭泣，在这里宴请国宾、聚会宗族，这说明我可以免于刑戮而善终，能跟先祖、先父一起长眠在九原！”说完，朝北拜了两拜，叩头致谢。君子都称赞他们一个善于赞颂，一个善于祈祷。', NULL, '', 'indent', 1522424156, '5abde8da4773f7005d3b3ffd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636852, '山海经 · 山经 · 南山经', NULL, 135, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E5%8D%97%E5%B1%B1%E7%BB%8F/19831181?fr=aladdin', '', '南山经之首曰鹊山。其首曰招摇之山，临于西海之上。多桂多金玉。有草焉，其状如韭而青华，其名曰祝馀，食之不饥。有木焉，其状如榖而黑理，其华四照。其名曰迷榖，佩之不迷。有兽焉，其状如禺而白耳，伏行人走，其名曰狌狌，食之善走。丽麂之水出焉，而西流注于海，其中多育沛，佩之无瘕疾。
又东三百里曰堂庭之山。多棪木，多白猿，多水玉，多黄金。
又东三百八十里曰猨翼之山。其中多怪兽，水多怪鱼。多白玉，多蝮虫，多怪蛇，多怪木，不可以上。
又东三百七十里曰杻阳之山。其阳多赤金。其阴多白金。有兽焉，其状如马而白首，其文如虎而赤尾，其音如谣，其名曰鹿蜀，佩之宜子孙。怪水出焉，而东流注于宪翼之水。其中多玄鱼，其状如龟而鸟首虺尾，其名曰旋龟，其音如判木，佩之不聋，可以为底。
又东三百里柢山。多水，无草木。有鱼焉，其状如牛，陵居，蛇尾有翼，其羽在魼下，其音如留牛，其名曰鯥，冬死而复生。食之无肿疾。
又东三百里曰亶爰之山。多水，无草木，不可以上。有兽焉，其状如狸而有髦，其名曰类，自为牝牡，食者不妒。
又东三百曰基山。其阳多玉，其阴多怪木。有兽焉，其状如羊，九尾四耳，其目在背，其名曰猼訑，佩之不畏。有鸟焉，其状如鸡而三首、六目、六足、三翼，其名曰??，食之无卧。
又东三百里曰青丘之山。其阳多玉，其阴多青。有兽焉，其状如狐而九尾，其音如婴儿，能食人，食者不蛊。有鸟焉，其状如鸠，其音如呵，名曰灌灌，佩之不惑。英水出焉，南流注于即翼之泽。其中多赤鱬，其状如鱼而人面，其音如鸳鸯，食之不疥。
又东三百五十里曰箕尾之山，其尾踆于东海，多沙石。汉水出焉，而南流注于淯，其中多白玉。
凡鹊山之首，自招摇之山以至箕尾之山，凡十山，二千九百五十里，其神状皆鸟身而龙首。其祠之礼：毛，用一璋玉瘗；糈用稌米，一壁，稻米、白莹为席。
南次二山之首曰柜山，西临流黄，北望诸?，东望长右。英水出焉，西南流注于赤水。其中多白玉，多丹粟。有兽焉，其状如豚，有距，其音如狗吠，其名曰狸力，见则其县多土功。有鸟焉，其状如鸱而人手，其音如痹，其名曰鴸，其名自号也，见则其县多放士。
东南四百五十里曰长右之山。无草木，多水。有兽焉，其状如禺而四耳，其名长右，其音如吟，见则郡县大水。
又东三百四十里曰尧光之山。其阳多玉，其阴多金。有兽焉，其状如人而彘鬣，穴居而冬蛰，其名曰猾褢，其音如斫木，见则县有大繇。
又东三百五十里曰羽山。其下多水，其上多雨，无草木，多蝮虫。
又东三百七十里曰瞿父之山。无草木，多金玉。
又东四百里曰句余之山。无草木，多金玉。
又东五百里曰浮玉之山。北望具区，东望诸?。有兽焉，其状如虎而牛尾，其音如吠犬，其名曰彘，是食人。苕水出于其阴，北流至于具区，其中多鮆鱼。
又东五百里曰成山。四方而三坛，其上多金玉，其下多青雘，?水出焉，而南流注于虖勺，其中多黄金。
又东五百里曰会稽之山，四方。其上多金玉，其下多砆石。勺水出焉，而南流注于湨。
又东五百里曰夷山。无草木，多沙石，湨水出焉，而南流注于列涂。
又东五百里曰仆勾之山，其上多金玉，其下多草木。无鸟兽，无水。
又东五百里曰咸阴之山，无草木，无水。
又东四百里曰洵山。其阳多金，其阴多玉，有兽焉，其状如羊而无口，不可杀也，其名曰䍺。洵水出焉，而南流注于阏之泽，其中多芘蠃。
又东四百里曰虖勺之山。其上多梓枏，其下多荆杞。滂水出焉，而东流注于海。
又东五百里曰区吴之山。无草木，多沙石，鹿水出焉，而南流注于滂水。
又东五百里曰鹿吴之山。上无草木，多金石。泽更之水出焉，而南流注于滂水。水有兽焉，名曰蛊雕，其状如雕而有角，其音如婴儿之音，是食人。
东五百里曰漆吴之山。无草木，多博石，无玉。处于东海，望丘山，其光载出载入，是惟日次。
凡南次二山之首，自柜山至于漆吴之山，凡十七山，七千二百里。其神状皆龙身而鸟首。其祠：毛，用一壁瘗，糈用稌。
南次三山之首，曰天虞之山。其下多水，不可以上。东五百里曰祷过之山，其上多金玉，其下多犀兕多象，有鸟焉，其状如鵁而白首三足人面，其名曰瞿如，其鸣自号也。泿水出焉，而南流注于海。其中有虎蛟，其状鱼身而蛇尾，其音如鸳鸯，食者不肿，可以已痔。
又东五百里曰丹穴之山。其上多金玉。丹水出焉，而南流注于渤海。有鸟焉，其状如鸡，五采而文，名曰凤皇，首文曰德，翼文曰义，背文曰礼，膺文曰仁，腹文曰信。是鸟也，饮食自然，自歌自舞，见则天下安宁。
又东五百里曰发爽之山。无草木，多水，多白猿。泛水出焉，而南流注于勃海。
又东四百里至于旄山之尾，其南有谷，曰育遗，多怪鸟，凯风自是出。
又东四百里，至于非山之首。其上多金玉，无水，其下多蝮虫。
又东五百里曰阳夹之山。无草木，多水。
又东五百里曰灌湘之山。上多木，无草，多怪鸟，无兽。
又东五百里曰鸡山。其上多金，其下多丹雘。黑水出焉，而南流注于海。其中有鱄鱼，其状如鲋而彘毛，其音如豚，见则天下大旱。
又东四百里曰令丘之山。无草木，多火。其南有谷焉，曰中谷，条风自是出。有鸟焉，其状如袅，人面四目而有耳，其名曰顒，其鸣自号也，见则天下大旱。
又东三百七十里曰仑者之山。其上多金玉，其下多青雘。有木焉，其状如榖而赤理，其汗如漆，其味如饴，食者不饥，可以释劳，其名曰白䓘，可以血玉。
又东五百八十里曰禺槀之山。多怪兽，多大蛇。
又东五百八十里，曰南禺之山。其上多金玉，其下多水。有穴焉，水出辄入，夏乃出，冬则闭。佐水出焉，而东南流注于海，有凤皇、鵷雏。
凡南次三山之首，自天虞之山以至南禺之山，凡一十四山，六千五百三十里。其神皆龙身而人面。其祠皆一白狗祈，稰用稌。
右南经之山志，大小凡四十山，万六千三百八十里。', '《山海经·南山经》是创作于战国时期的一篇散文，出自《山海经》，作者不详。', '', '南方首列山系叫做鹊山山系。鹊山山系的头一座山是招摇山，屹立在西海岸边，生长着许多桂树，又蕴藏着丰富的金属矿物和玉石。山中有一种草，形状像韭菜却开着青色的花朵，名称是祝馀，人喫了它就不感到饥饿。山中又有一种树木，形状像构树却呈现黑色的纹理，并且光华照耀四方，名称是迷谷，人佩带它在身上就不会迷失方向。山中还有一种野兽，形状像猿猴但长着一双白色的耳朵，既能匍伏爬行，又能像人一样直立行走，名称是狌狌，喫了它的肉可以使人走得飞快。丽水从这座山发源，然后往西流入大海，水中有许多叫做育沛的东西，人佩带它在身上就不会生蛊胀病。
再往东三百里，是座堂庭山，山上生长着茂密的棪木，又有许多白色猿猴，还盛产水晶石，并蕴藏着丰富的黄金。
再往东三百八十里，是座即翼山。山上生长着许多怪异的野兽，水中生长着许多怪异的鱼，还盛产白玉，有很多蝮虫，很多奇怪的蛇，很多奇怪的树木，人是不可上去的。
再往东三百七十里，是杻阳山。山南面盛产铜，山北面盛产白银。山中有一种野兽，形状像马却长着白色的头，身上的斑纹像老虎而尾巴却是红色的，吼叫的声音像人唱歌，名称是鹿蜀，人穿戴上它的毛皮就可以多子多孙。怪水从这座山发源，然后向东流入宪翼水。水中有众多暗红色的龟，形状像普通乌龟却长着鸟一样的头和蛇一样的尾巴，名称是旋龟，叫声像劈开木头时发出的响声，佩带上它就能使人的耳朵不聋，还可以治愈脚底老茧。
再往东三百里，是座柢山，山间多水流，没有花草树木。有一种鱼，形状像牛，栖息在山坡上，长着蛇一样的尾巴并且有翅膀，而翅膀长在胁骨上，鸣叫的声音像犁牛，名称是鯥，冬天蛰伏而夏天复苏，喫了它的肉就能使人不患痈肿疾病。
再往东三百里，是座亶爰山，山间多水流，没有花草树木，不能攀登上去。山中有一种野兽，形状像野猫却长着像人一样的长头发，名称是类，一身具有雄雌两种性器官，喫了它的肉就会使人不产生妒忌心。
再往东三百里，是座基山，山南阳面盛产玉石，山北阴面有很多奇怪的树木。山中有一种野兽，形状像羊，长着九条尾巴和四隻耳朵，眼睛也长在背上，名称是猼訑，人穿戴上它的毛皮就会不产生恐惧心。山中还有一种禽鸟，形状像鸡却长着三个脑袋、六隻眼睛、六隻脚、三隻翅膀，名称是？？，喫了它的肉就会使人不感到瞌睡。
再往东三百里，是座青丘山，山南阳面盛产玉石，山北阴面多出产青雘。山中有一种野兽，形状像狐狸却长着九条尾巴，吼叫的声音与婴儿啼哭相似，能吞食人；喫了它的肉就能使人不中妖邪毒气。山中还有一种禽鸟，形状像斑鸠，鸣叫的声音如同人在互相斥骂，名称是灌灌，把它的羽毛插在身上使人不迷惑。英水从这座山发源，然后向南流入即翼泽。泽中有很多赤鱬，形状像普通的鱼却有一副人的面孔，发出的声音如同鸳鸯鸟在叫，喫了它的肉就能使人不生疥疮.
再往东三百五十里，是座箕尾山，山的尾端坐落于东海岸边，沙石很多。汸淯水从这座山发源，然后向南流入水，水中多产白色玉石。
总计鹊山山系之首尾，从招摇山起，直到箕尾山止，一共是十座山，途经二千九百五十里。诸山山神的形状都是鸟的身子龙的头。祭祀山神的典礼；是把畜禽和璋一起埋入地下，祀神的米用稻米，用白茅草来做神的座席。
南方第二列山系的首座山是柜山，西边临近流黄酆氏国和流黄辛氏国，在山上向北可以望见诸山，向东可以望见长右山。英水从这座山发源，向西南流入赤水，水中有很多白色玉石，还有很多粟粒般大小的丹沙。山中有一种野兽，形状像普通的小猪，长着一双鸡爪，叫的声音如同狗叫，名称是狸力，哪个地方出现狸力而那里就一定会有繁多的水土工程。山中还有一种鸟，形状像鹞鹰却长着人手一样的爪子，啼叫的声音如同痹鸣，名称是鴸，它的鸣叫声就是自身名称的读音，哪个地方出现而那里就一定会有众多的文士被流放。
从柜山往东南四百五十里，是座长右山，没有花草树木，但有很多水。山中有一种野兽，形状像猿猴却长着四隻耳朵，名称是长右，叫的声音如同人在呻吟，任何郡县一出现长右就会发生大水灾。
再往东三百四十里，是座尧光山，山南阳面多产玉石，山北阴面多产金。山中有一种野兽，形状像人却长有猪那样的鬣毛，冬季蛰伏在洞穴中，名称是猾褢，叫声如同砍木头时发出的响声，哪个地方出现猾褢那里就会有繁重的徭役。
再往东三百五十里，是座羽山，山下到处流水，山上经常下雨，没有花草树木，蝮虫很多。
再往东三百七十里，是座瞿父山，山上没有花草树木，但有丰富的金属矿物和玉石。
再往东四百里，是座句馀山，山上没有花草树木，但有丰富的金属矿物和玉石。
再往东五百里，是座浮玉山，在山上向北可以望见具区泽，向东可以望见诸水，山中有一种野兽，形状像老虎却长着牛的尾巴，发出的叫声如同狗叫，名称是彘，是能喫人的。苕水从这座山的北麓发源，向北流入具区泽。它里面生长着很多鮆鱼。
再往东五百里，是座成山，呈现四方形而像三层土坛，山上盛产金属矿物和玉石，山下多产青雘。水从这座山发源，然后向南流入虖勺水，水中有丰富的黄金。
再往东五百里，是座会稽山，呈现四方形，山上有丰富的金属矿物和玉石，山下盛产晶莹透亮的砆石。勺水从这座山发源，然后向南流入湨水。
再往东五百里，是座夷山，山上没有花草树木，到处是细沙石子。湨水从这座山发源，然后向南流入列涂水。
再往东五百里，是座仆勾山，山上有丰富的金属矿物和玉石，山下有茂密的花草树木，但没有禽鸟野兽，也没有水。
再往东五百里，是座咸阴山，没有花草树木，也没有水。
再往东四百里，是座洵山，山南阳面盛产金属矿物，山北阴面多出产玉石。山中有一种野兽，形状像普通的羊却没有嘴巴，不喫东西也能活着而不死，名称是羊患。洵水从这座山发源，然后向南流入阏泽，水中有很多紫色螺。
再往东四百里，是座虖勺山，山上到处是梓树和楠木树，山下生长许多牡荆树和苟杞树。滂水从这座山发源，然后向东流入大海。
再往东五百里，是座区吴山，山上没有花草树木，到处是沙子石头。鹿水从这座山发源，然后向南流入滂水。
再往东五百里，是座鹿吴山，山上没有花草树木，但有丰富的金属矿物和玉石。泽更水从这座山发源，然后向南流入滂水。水中有一种野兽，名称是蛊雕，形状像普通的雕鹰却头上长角，发出的声音如同婴儿啼哭，是能喫人的。
再往东五百里，是座漆吴山，山中没有花草树木，多出产可以用作棋子的博石，不产玉石。这座山位于东海之滨，在山上远望是片丘陵，有光影忽明忽暗，那是太阳停歇之处。
总计南方第二列山系之首尾，从柜山起到漆吴山止，一共十七座山，途经七千二百里。诸山山神的形状都是龙的身子鸟的头。祭祀山神：是把畜禽和玉璧一起埋入地下，祀神的米用稻米。
南方第三列山系的头一座山，是座天虞山，山下到处是水，人不能上去。
从天虞山往东五百里，是座祷过山，山上盛产金属矿物和玉石，山下到处是犀、兕，还有很多大象。山中有一种禽鸟，形状像䴔却是白色的脑袋，长着三隻脚，人一样的脸，名称是瞿如，它的鸣叫声就是自身名称的读音。泿水从这座山发源，然后向南流入大海。水中有一种虎蛟，形状像普通鱼的身子却拖着一条蛇的尾巴，脑袋如同鸳鸯鸟的头，喫了它的肉就能使人不生痈肿疾病，还可以治愈痔疮。
再往东五百里，是座丹穴山，山上盛产金属矿物和玉石。丹水从这座山发源，然后向南流入渤海。山中有一种鸟，形状像普通的鸡，全身上下是五彩羽毛，名称是凤凰，头上的花纹是「德」字的形状，翅膀上的花纹是「羲」字的形状，背部的花纹是「礼」字的形状，胸部的花纹是「仁」字的形状，腹部的花纹是「信」字的形状。这种叫做凤凰的鸟，喫喝很自然从容，常常是自个儿边唱边舞，一出现天下就会太平。
再往东五百里，是座发爽山，没有花草树木，到处流水，有很多白色的猿猴。泛水从这座山发源，然后向南流入渤海。
再往东四百里，便到了旄山的尾端。此处的南面有一峡谷，叫做育遗，生长着许多奇怪的鸟，南风就是从这里吹出来的。
再往东四百里，便到了非山的顶部。山上盛产金属矿物和玉石，没有水，山下到处是蝮虫。
再往东五百里，是座阳夹山，没有花草树木，到处流水。
再往东五百里，是座灌湘山，山上到处是树木，但没有花草；山中有许多奇怪的禽鸟，却没有野兽。
再往东五百里，是座鸡山，山上有丰富的金属矿物，山下盛产丹雘。黑水从这座山发源，然后向南流入大海。水中有一种鲭鱼，形状像鲫鱼却长着猪毛，发出声音如同小猪叫，它一出现就会天下大旱。
再往东四百里，是座令丘山，没有花草树木，到处是野火。山的南边有一峡谷，叫做中谷，东北风就是从这里吹出来的。山中有一种禽鸟，形状像猫头鹰，却长着一副人脸和四隻眼睛而且有耳朵，名称是颙，它发出的叫声就是自身名称的读音，一出现而天下就会大旱。
再往东三百七十里，是座仑者山，山上有丰富的金属矿物和玉石，山下盛产青雘。山中有一种树木，形状像一般的构树却是红色的纹理，枝干流出的汁液似漆，味道是甜的，人喫了它就不感到饥饿，还可以解除忧愁，名称是白呙，可以用它把玉石染得鲜红。
再往东五百八十里，是座禺稿山，山中有很多奇怪的野兽，还有很多大蛇。
再往东五百八十里，是座南禺山，山上盛产金属矿物和玉石，山下到处流水。山中有一个洞穴，水在春天就流入洞穴，在夏天便流出洞穴，在冬天则闭塞不通。佐水从这座山发源，然后向东南流入大海，佐水流经的地方有凤凰和鹓雏栖息。
总计南方第三列山系之首尾，从天虞山起到南禺山止，一共十四座山，途经六千五百三十里。诸山山神都是龙的身子人的脸面。祭祀山神全部是用一条白色的狗作供品祈祷，祀神的米用稻米。
以上是南方经历之山的记录，大大小小总共四十座，一万六千三百八十里。', NULL, '', 'indent', 1522503193, '5abf1d329f54541656d861d1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636853, '山海经 · 山经 · 西山经', NULL, 34, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E8%A5%BF%E5%B1%B1%E7%BB%8F/19831180?fr=aladdin', '', '西山经华山之首，曰钱来之山，其上多松，其下多洗石。有兽焉，其状如羊而马尾，名曰羬羊，其脂可以已腊。
西四十五里，曰松果之山。濩水出焉，北流注于渭，其中多铜。有鸟焉，其名曰䳋渠，其状如山鸡，黑身赤足，可以已?。
又西六十里，曰太华之山，削成而四方，其高五千仞，其广十里，鸟兽莫居。有蛇焉，名曰肥?，六足四翼，见则天下大旱。
又西八十里，曰小华之山，其木多荆杞，其兽多㸲牛，其阴多磬石，其阳㻬琈之玉。鸟多赤鷩，可以御火。其草有萆荔，状如乌韭，而生于石上，赤缘木而生，食之已心痛。
又西八十里，曰符禺之山，其阳多铜，其阴多铁。其上有木焉，名曰文茎，其实如枣，可以已聋。其草多条，其状如葵，而赤华黄实，如婴儿舌，食之使人不惑。符禺之水出焉，而北流注于渭。其兽多葱聋，其状如羊而赤鬣。其鸟多鴖，其状如翠而赤喙，可以御火。
又西六十里，曰石脆之山，其木多棕枬，其草多条，其状如韭，而白华黑实，食之已疥。其阳多㻬琈之玉，其阴多铜。灌水出焉，而北流注于禺水。其中有流赭，以涂牛马无病。
又西七十里，曰英山，其上多杻橿，其阴多铁，其阳多赤金。禺水出焉，北流注于招水，其中多䰷鱼，其状如鳖，其音如羊。其阳多箭䉋，兽多㸲牛、羬羊。有鸟焉，其状如鹑，黄身而赤喙，其名曰肥遗，食之已疠，可以杀虫。
又西五十二里，曰竹山，其上多乔木，其阴多铁。有草焉，其名曰黄雚，其状如樗，其叶如麻，白华而赤实，其状如赭，浴之已疥，又可以已胕。竹水出焉，北流注于渭，其阳多竹箭，多苍玉。丹水出焉，东南流注于洛水，其中多水玉，多人鱼。有兽下，其状如豚而白毛，大如筓而黑端，名曰豪彘。
又西百二十里，曰浮山，多盼木，枳叶而无伤，木虫居之。有草焉，名曰薰草，麻叶而方茎，赤华而黑实，臭如蘼芜，佩之可以已疠。
又西七十里，曰羭次之山，漆水出焉，北流注于渭。其上多棫囗，其下多竹箭，其阴多赤铜，其阳多婴垣之玉。有兽焉，其状如禺而长臂，善投，其名曰嚣。有鸟焉，其状如枭，人面而一足，曰橐?，冬见夏蛰，服之不畏雷。
又西百五十里，曰时山，无草木。逐水出焉，北海注于渭，其中多又西百七十里，曰南山，上多丹粟。丹水出焉，北流注于渭。兽多猛豹，鸟多尸鸠。
又西四百八十里，曰大时之山，上多楮柞，下多杻橿，阴多银，阳多白玉。涔水出焉，北流注于渭。清水出焉，南流注于汉水。
又西三百二十里，曰嶓冢之山，汉水出焉，而东南流注于沔；嚣水出焉，北流注于汤水。其上多桃枝钩端，兽多犀兕熊罴，鸟多白翰赤鷩。有草焉，其叶如蕙，其本如桔梗，黑华而不实，名曰蓇蓉。食之使人无子。
又西三百五十里，曰天帝之山，多棕枬；下多菅蕙。有兽焉，其状如狗，名曰溪边，席其皮者不蛊。有鸟焉，其状如鹑，黑文而赤翁，名曰栎，食之已痔。有草焉，其状如共葵，共其臭如蘼芜，名曰杜衡，可以走马，食之已瘿。
西南三百八十里，曰皋涂之山，蔷水出焉，西流注于诸资之水；涂水出焉，南流注于集获之水。其阳多丹粟，其阴多银、黄金，其上多桂木。有白石焉，其名曰囗，可以毒鼠。有草焉，其状如稿芨，其叶如葵赤背，名曰无条，可以毒鼠。有兽焉，其状如鹿而白尾，马足人手而四角，名曰玃如。有鸟焉，其状如鸱而人足，名曰数斯，食之已瘿。
又西百八十里，曰黄山，无草木，多竹箭。盼水出焉，西流注于赤水，其中多玉。有兽焉，其状如牛，而苍黑大目，其状曰?。有鸟焉，其状如鸮，青羽赤喙，人舌能言，名曰鹦鹉。
又西二百里，曰翠山，其上多棕枬，其下多竹箭，其阳多黄金、玉，其多鸓，其状如鹊，赤黑而两首四足，可以御火。
又西二百五十里，曰騩山，是錞于西海，无草木，多玉。凄水出焉，西流注于海，其中多采石、黄金，多丹粟。
凡西经之首，自钱来之山至于山，凡十九山，二千九百五十七里。华山冢也，其祠之礼：太牢。囗山神也，祠之用烛，斋百日以百牺，瘗用百瑜，汤其酒百樽，婴以百珪百壁。其余十七山之属，皆毛牷用一羊祠之。烛者，百草之未灰，白席采等纯之。
西次二经之首，曰钤山，其上多铜，其下多玉，其木多杻橿。
西二百里，曰泰冒之山，其阳多玉，其阴多铁。浴水出焉，东流注于河，其中多藻玉，多白蛇。
又西一百七十里，曰数历之山，其上多黄金，其下多银，其木多杻、橿，其鸟多鹦。楚水出焉，而南流注于渭，其中多白珠。
又西百五十里高山，其上多银，其下多青碧、雄黄，其木多棕，其草多竹。泾水出焉，而东流注于渭，其中多馨石、青碧。
西南三百里，曰女床之山，其阳多赤铜，其阴多石涅，其兽多虎豹犀兕。有鸟焉，其状如翟而五彩纹，名曰鸾鸟，见则天下安宁。
又西二百里，曰龙首之山，其阳多黄金，其阴多铁。苕水出焉，东海流注于泾水，其中多美玉。
又西二百里，曰鹿台之山，其上多白玉，其下多银，其兽多㸲牛、羬羊、白豪。有鸟焉，其状如雄鸡而人面，名曰凫徯，其鸣自叫也，见则有兵。
西南二里，曰鸟危之山，其阳多馨石，其阴多檀楮，其中多女床。鸟危之水出焉，西流注于赤水，其中多丹粟。
又西四百里，曰小次之山，其上多白玉，其下多赤铜。有兽焉其状如猿，而白首赤足，名曰朱厌，见则大兵。
又西三百里，曰大次之山，其阳多垩，其阴多碧，其兽多㸲羊、麢羊。
又西四百里，曰薰吴之山，无草木，多金玉。
又西四百里，曰厎阳之山，其木多稷、枬、豫章，其兽多犀、兕、虎、犳、㸲牛。
又西二百五十里，曰众兽之山，其上多㻬琈之玉，其下多檀楮，多黄金，其兽多犀兕。
又西五百里，曰皇人之山，其上多金玉，其下多青雄黄。皇水出焉，西流注于赤水，其中多丹粟。
又西三百里，曰中皇之山，其上多黄金，其下多蕙、棠。
又西三百五十里，曰西皇之山，其阳多黄金，其阴多铁，其兽多麋、鹿、㸲牛。
又西三百里五十里，曰莱山，其木多檀楮，其鸟多罗罗，是食人。
凡西次二经之首，自钤山至于莱山，凡十七山，四千一百四十里。其十神者，皆人面而马身。其七神皆人面而牛身，四足而一臂，操杖以行，是为飞兽之神。其祠之，毛用少牢，白菅为席。其十辈神者，其祠之毛一雄鸡，钤而不糈：毛采。
西次三经之首，曰崇吾之山，在河之南，北望冢遂，南望䍃之泽，西望帝之捕兽之丘，东望䗡渊。有木焉，员叶而白柎，赤华而黑理，其实如枳，食之宜子孙。有兽焉，其状如凫，而一翼一日，相得乃飞，名曰蛮蛮，见则天下大水。
西北三百里，曰长沙之山。泚水出焉，北流注于泑水，无草木，多青雄黄。
又西北三百七十里，曰不周之山。北望诸䗡之山，临彼岳崇之山，东望泑泽，河水所潜也，其原浑浑泡泡。爰有嘉果，其实如桃，其叶如枣，黄华而赤柎，食之不劳。
又西北四百二十里，曰峚山，其上多丹木，员叶而赤茎，黄华而赤实，其味如饴，食之不饥。丹水出焉，西流注于稷泽，其中多白玉。是有玉膏，其原沸沸汤汤，黄帝是食是飨。是生玄玉。玉膏所出，以灌丹木，丹木五岁，五色乃清，五味乃馨。黄帝乃取峚山之玉荣，而投之钟山之阳。瑾瑜之玉为良，坚粟精密，浊泽有而色。五色发作，以和柔刚。天地鬼神，是食是飨；君子服之，以御为祥。自峚山至于钟山，四百六十里，其间尽泽也。是多奇鸟、怪兽、奇鱼，皆异物焉。
又西北四百二十里，曰钟山。其子曰鼓，其状如人面而龙身，是与钦䲹杀葆江于昆仑之阳，帝乃戮之钟山之东曰?崖。钦䲹化为大鹗，其状如雕而墨文曰首，赤喙而虎爪，其音如晨鹄，见则有大兵；鼓亦化为鵕鸟，其状如鸱，赤足而直喙，黄文而白首，其音如鹄，见即其邑大旱。
又西百八十里，曰泰器之山。观水出焉，西流注于流沙。是多文鳐鱼，状如鲤鱼，鱼身而鸟翼，苍文而白首赤喙，常行西海，游于东海，以夜飞。其音如鸾鸡，其味酸甘，食之已狂，见则天下大穰。
又西三百二十里，曰槐江之山。丘时之水出焉，而北流注于泑水。其中多蠃其上金青雄黄，多藏琅？、黄金、玉，其阳多丹粟。其了有多采黄金银。实惟帝之平圃，神英招司之，其状马身而人面，虎文而鸟翼，徇于四海，其音如榴。南望昆仑，其光熊熊，其气魂魂。西望大泽，后稷所潜也。其中多玉，其阴多榣木之有若。北望诸毗，槐鬼离仑居之，鹰鸇之所宅也。东望恒山四成，有穷鬼居之，各在一搏。爰有淫水，其清洛洛。有天神焉，其状如牛，而八足二首马尾，其音如勃皇，见则其邑有兵。
西南四百里，曰昆仑之丘，是实惟帝之下都，神陆吾司之。其神状虎身而九尾，人面而虎爪；是神也，司天之九部及帝之囿时，有兽焉，其状如羊而四角，名曰土蝼，是食人。有鸟焉，其状如蜂，大如鸳鸯，名曰钦原，蠚鸟兽则死，蠚木则枯，有鸟焉，其名曰鹑鸟，是司帝之百服。有木焉，其状如棠，黄华赤实，其味如李而无核，名曰沙棠，可以御水，食之使人不溺。有草焉，名曰薲草，其状如葵，其味如葱，食之已劳。河水出焉，而南流注于无达。赤水出焉，而东南流注于泛天之水。洋水出焉，而西南流注于丑涂之水。墨水出焉，而四海流注于大杆。是多怪鸟兽。
又西三百七十里，曰乐游之山。桃水出焉，西流注于稷泽，是多白玉，其中多䱻鱼，其状如蛇而四足，是食鱼。
西水行四百里，曰流沙，二百里至于嬴母之山，神长乘司之，是天之九德也。其神状如人而豹尾。其上多玉，其下多青石而无水。
又西北三百五十里，曰玉山，是西王母所居也。西王母其状如人，豹尾虎齿而善啸，蓬发戴胜，是司天之厉及五残。有兽焉，其状如犬而豹文，其角如牛，其名曰狡，其音如吠犬，见则其国大穰。有鸟焉，其状如翟而赤，名曰胜遇，是食鱼，其音如录，见则其国大水。
又西四百八十里，曰轩辕之丘，无草木。洵水出焉，南流注于黑水，其中多丹粟，多青雄黄。
又西三百里，曰积石之山，其下有石门，河水冒以西流，是山也，万物无不有焉。
又西二百里，曰长留之山，其神白帝少昊居之。其兽皆文尾，其鸟皆文首。是多文玉石。实惟员神磈氏之宫。是神也，主司反景。
又西二百八十里，曰章莪之山，无草木，多瑶碧。所为甚怪。有兽焉，其状如赤豹，五尾一角，其音如击石，其名如狰。有鸟焉，其状如鹤，一足，赤文青质而白喙，名曰毕文，其鸣自叫也，见则其邑有譌火。
又西三百里，曰阴山。浊浴之水出焉，而南流注于番泽，其中多文贝。有兽焉，其状如狸而白首，名曰天狗，其音如榴榴，可以御凶。
又西二百里，曰符惕之山，其上多棕枬，下多金玉。神江疑居之。是山也，多怪雨，风云之所出也。
又西二百二十里，曰三危之山，三青鸟居之。是山也，广员百里。其上有兽焉，其状如牛，白身四角，其豪如披蓑，其名曰??，是食有。有鸟焉，一首而三身，其状如?，其名曰鸱。
又西一百九十里，曰騩山，其上多玉而无石。神耆童居之，其音常如钟磬。其下多积蛇。
又西三百五十里，曰天山，多金玉，有青雄黄。英水出焉，而西南流注于汤谷。有神焉，基状如黄囊，赤如丹水，六足四翼，浑敦无而目，是识歌舞，实为帝江也。
又西二百九十里，曰泑山，神蓐收居之。其上多婴短之玉，其阳多瑾瑜之玉，其阴多青雄黄。是山也，西望日之所入，其气员，神红光之所司也。
西水行百里，至于翼望之山，无草木，多金玉。有兽焉，其状如狸，一日而三尾，名曰谨，其音如夺百声，是可以御凶，服之已瘅。有鸟焉，其状如乌，三首六尾而善笑，名曰鵸鵌，服之使人不厌，又可以御凶。
凡西次三经之首，崇吾之山至于翼望之山，凡二十三山，六千七百四十四里。其神状皆羊身人面。其祠之礼，用一吉玉瘗，糈用稷米。
西次四经之首，曰阴山，上多楮，无石，其草多茆、蕃。阴水出焉，西流注于洛。
北五十里，曰劳山，多茈草。弱水出焉，而西流注于洛。
西五十里，曰罢父之山，洱水出焉，而西流注于洛，其中多茈、碧。
北七十里，曰中山，其上多楮柞，其下多杻橿，其阳多金玉。区水出焉，而江流注于河。
北二百里，曰鸟山，其上多桑，其焉多楮，其阴多铁，其阳多玉。辱水出焉，而东流注于河。
又北百二里，曰上申之山，上无草木，而多硌石，下多榛楛，兽多白鹿。其鸟多当扈，其状如雉，以其髯飞，食之不眴目。汤水出焉，东流注于河。
又北百八十里，曰诸次之山，诸次之水出焉，而东流注于河。是山也，多木无草，鸟兽莫居，是多众蛇。
又北百八十里，曰号山，其木多漆、棕，其草多药、芎䓖。多冷石。端水出焉，而东流注于河。
又北二百二十里，曰盂山，其阴多铁，其阳多铜，其兽多白狼白虎，其鸟多白雉白翟。生水出焉，而东流注于河。
西二百五十里，曰白于之山，上多松柏，下多栎檀，其兽多㸲牛、羬羊，其鸟多鸮。洛水出于其阳，而东流注于渭；夹水出于其阴，东流注于生水。
西北三百里，曰申首之山，无草木，冬夏雪。申水出于其上。潜于其下，是多白玉。
又西五十五里，曰泾谷之山。泾水出焉，东南流注于渭，是多白金白玉。
又西百二十里，曰刚山，多柒木，多㻬琈之玉。刚水出焉，北流注于渭。是多神?，其状人面兽身，一足一手，其音如钦。
又西二百里，至刚山之尾。洛水出焉，而北流注于河。其中多蛮蛮，其状鼠身而鳖首，其音如吠犬。
又西三百五十里，曰英鞮之山，上多漆木，下多金玉，鸟兽尽白。靼涴水出焉，而北流注於陵羊之泽。是多冉遗之鱼，鱼身蛇首六足，其目如观耳，食之使人不眯，可以御凶。
又西三百里，曰中曲之山，其阳多玉，其阴多雄黄、白玉及金。有兽焉，其状如马而白身黑尾，一角，虎牙爪，音如鼓音，其名曰驳，是食虎豹，可以御兵。有木焉，其状如棠，而员叶赤实，实大如木瓜，名曰杯木，食之多力。
又西二百六十里，曰邽山。其上有兽焉，其状如牛，猬毛，名曰穷奇，音如獆狗，是食人。蒙水出焉，南流注于洋水，其中多黄贝；嬴鱼，鱼身而鸟翼，音如鸳鸯，见则其邑大水。
又西二百二十里，曰鸟鼠同穴之山，其上多白虎、白玉。渭水出焉，而东流注于河。其中多鳋鱼，其状如鱣鱼，动则其邑有大兵。滥水出于其西，西流注于汉水，多?魮之鱼，其状如覆铫，鸟首而鱼翼，音如磬石之声，是生珠玉。
西南三百六十里，曰崦嵫之山，其上多丹木，其叶如楮，其实大如瓜，赤符而黑理，食之已瘅，可以御火。其阳多龟，其阴多玉。苕水出焉，而西流注于海，其中多砥励。有兽焉，其状马身而鸟翼，入面蛇尾，是好举人，名曰孰湖。有鸟焉，其状如鸮而人面，蜼身犬尾，其名自号也，见则其邑大旱。
凡西次四经自阴山以下，至于崦嵫之山，凡十九山，三千六百八十里。其神祠礼，皆用一白鸡祈，糈以稻米，白菅为席。
右西经之山，凡七十七山，一万七千五百一十七里。', '《山海经·西山经》是创作于战国时期的一篇散文，出自《山海经》，作者不详。', '', '西方第一列山系华山山系之首座山，叫做钱来山，山上有许多松树，山下有很多洗石。山中有一种野兽，形状像普通的羊却长着马的尾巴，名称是羬羊，羬羊的油脂可以护理治疗干裂的皮肤。
从钱来山往西四十五里，是座松果山。濩水从这座山发源，向北流入渭水，其中多产铜。山中有一种禽鸟，名称是䳋渠，形状像一般的野鸡，黑色的身子和红色的爪子，可以用来治疗皮肤干皱。
再往西六十里，是座太华山，山崖陡峭像刀削而呈现四方形，高五千仞，宽十里，禽鸟野兽无法栖身。山中有一种蛇，名称是肥遗，长着六只脚和四只翅膀，一出现就会天下大旱。
再往西八十里，是座小华山，山上的树木大多是牡荆树和枸杞树，山中的野兽大多是㸲牛，山北阴面盛产磬石，山南阳面盛产㻬琈玉。山中有许多赤鷩鸟，饲养它就可以辟火。山中还有一种叫做萆荔的草，形状像乌韭，但生长在石头上面，也攀缘树木而生长，人喫了它就能治癒心痛病。
再往西八十里，是座符禺山，山南阳面盛产铜，山北阴面盛产铁。山上有一种树木，名称是文茎，结的果实像枣子，可以用来治疗耳聋。山中生长的草大多是条草，形状与葵菜相似，但开的是红色花朵而结的是黄色果实，果实的样子像婴儿的舌头，喫了它就可使人不迷惑。符禺水从这座山发源，然后向北流入渭水。山中的野兽大多是葱聋，形状像普通的羊却长有红色的鬣毛。山中的禽鸟大多是鴖鸟，形状像一般的翠鸟却是红色的嘴巴，饲养它可以辟火。
再往西六十里，是座石脆山，山上的树大多是棕树和楠木树，而草大多是条草，形状与韭菜相似，但是开的是白色花朵而结的是黑色果实，人喫了这种果实就可以治癒疥疮。山南面盛产㻬琈玉，而山北面盛产铜。灌水从这座山发源，然后向北流入禺水。这条水里有硫黄和赭黄，将这种水涂洒在牛马的身上就能使牛马健壮不生病。
再往西七十里，是座英山，山上到处是杻树和橿树，山北阴面盛产铁，而山南阳面盛产黄金。禺水从这座山发源，向北流入招水，水中有很多䰷鱼，形状像一般的鳖，发出的声音如同羊叫。山南面还生长有很多箭竹和䉋竹，野兽大多是㸲牛、羬羊。山中有一种禽鸟，形状像一般的鹌鹑鸟，是黄身子而红嘴巴，名称是肥遗，人喫了它的肉就能治癒麻疯病，还能杀死体内寄生虫。
再往西五十二里，是座竹山，山上到处是高大的树木，山北面盛产铁。山中有一种草，名称是黄雚，形状像樗树，但叶子像麻叶，开白色的花朵而结红色的果实，果实外表的颜色像赭色，用它洗浴就可治癒疥疮，又可以治疗浮肿病。竹水从这座山发源，向北流入渭水，竹水的北岸有很多的小竹丛，还有许多青色的玉石。丹水也发源于这座山，向东南流入洛水，水中多出产水晶石，又有很多人鱼。山中有一种野兽，形状像小猪却长着白色的毛，毛如簪子粗细而尖端呈黑色，名称是豪彘。
再往西一百二十里，是座浮山，到处是盼木，长着枳树一样的叶子却没有刺，树木上的虫子寄生于此。山中有一种草，名称是熏草，叶子像麻叶却长着方方的茎干，开红色的花朵而结黑色的果实，气味像蘼芜，把它插在身上就可以治疗麻疯病。
再往西七十里，是座羭次山。漆水发源于此，向北流入渭水。
山上有茂密的棫树和橿树，山下有茂密的小竹丛，山北阴面有丰富的赤铜，而山南阳面有丰富的婴垣玉。山中有一种野兽，形状像猿猴而双臂很长，擅长投掷，名称是嚻。山中还有一种禽鸟，形状像一般的猫头鹰，长着人一样的面孔而只有一只脚，叫做橐？，常常是冬天出现而夏天蛰伏，把它的羽毛插在身上就使人不怕打雷。
再往西一百五十里，是座时山，没有花草树木。逐水从这座山发源，向北流入渭水。水中有很多水晶石。
再往西一百七十里，是座南山，到处是粟粒大小的丹沙。丹水从这座山发源，向北流入渭水。山中的野兽大多是猛豹，而禽鸟大多是布穀鸟。
再往西一百八十里，是座大时山，山上有很多构树和栎树，山下有很多杻树和僵树，山北面多出产银，而山南面有丰富的白色玉石。涔水从这座山发源，向北流入渭水。清水也从这座山发源，却向南流入汉水。
再往西三百二十里，是座。冢山，汉水发源于此，然后向东南流入沔水；嚻水也发源于此，向北流入汤水。山上到处是葱茏的桃枝竹和钩端竹，野兽以犀牛、兕、熊、罴最多，禽鸟却以白翰和赤鷩最多。山中有一种草，叶子长得像蕙草叶，茎干却像桔梗，开黑色花朵但不结果实，名称是蓇蓉，喫了它就会使人不生育孩子。
再往西三百五十里，是座天帝山，山上是茂密的棕树和楠木树，山下主要生长茅草和蕙草。山中有一种野兽，形状像普通的狗，名称是溪边，人坐卧时铺垫上溪边兽的皮就不会中妖邪毒气。山中又有一种禽鸟，形状像一般的鹌鹑鸟，但长着黑色的花纹和红色的颈毛，名称是栎，人喫了它的肉可以治癒痔疮。山中还有一种草，形状像葵菜，散发出和蘼芜一样的气味，名称是杜衡，给马插戴上它就可以使马跑得很快，而人喫了它就可以治癒脖子上的赘瘤病。
往西南三百八十里，是座皋涂山，蔷水发源于此，向西流入诸资水；涂水也发源于此，向南流入集获水。山南面到处是粟粒大小的丹沙，山北阴面盛产银、黄金，山上到处是桂树。山中有一种白色的石头，名称是礜，可以用来毒死老鼠。山中又有一种草，形状像藁茇，叶子像葵菜的叶子而背面是红色的，名称是无条，可以用来毒死老鼠。山中还有一种野兽，形状像普通的鹿却长着白色的尾巴，马一样的脚蹄、人一样的手而又有四只角，名称是玃如。山中还有一种禽鸟，形状像鹞鹰却长着人一样的脚，名称是数斯，喫了它的肉就能治癒人脖子上的赘瘤病。
再往西一百八十里，是座黄山，没有花草树木，到处是郁郁葱葱的竹丛。盼水从这座山发源，向西流入赤水，水中有很多玉石。山中有一种野兽，形状像普通的牛，却长着苍黑色的皮毛大大的眼睛，名称是？。山中又有一种禽鸟，形状像一般的猫头鹰，却长着青色的羽毛和红色的嘴，像人一样的舌头能学人说话，名称是鹦䳇。
再往西二百里，是座翠山，山上是茂密的棕树和楠木树，山下到处是竹丛，山南面盛产黄金、玉，山北面有很多牦牛、羚羊、麝。山中的禽鸟大多是鸓鸟，形状像一般的喜鹊，却长着红黑色羽毛和两个脑袋、四只脚，人养着它可以辟火。
再往西二百五十里，是座騩山，它坐落在西海边上，这里没有花草树木，却有很多玉石。凄水从这座山发源，向西流入大海，水中有许多采石、黄金，还有很多粟粒大小的丹沙。
总计西方第一列山系之首尾，自钱来山起到騩山止，一共十九座山，途经二千九百五十七里。华山神是诸山神的宗主，祭祀华山山神的典礼：用猪、牛、羊齐全的三牲作祭品。羭山神是神奇威灵的，祭祀羭山山神用烛火，斋戒一百天后用一百只毛色纯正的牲畜，随一百块瑜埋入地下，再烫上一百樽美酒，祀神的玉器用一百块玉珪和一百块玉璧。祭祀其余十七座山山神的典礼相同，都是用一只完整的羊作祭品。所谓的烛，就是用百草制作的火把但未烧成灰的时候，而祀神的席是用各种颜色等差有序地将边缘装饰起来的白茅草席。
西方第二列山系之首座山，叫做钤山，山上盛产铜，山下盛产玉，山中的树大多是杻树和橿树。
向西二百里，是座泰冒山，山南面多出产金，山北面多出产铁。洛水从这座山发源，向东流入黄河，水中有很多藻玉，还有很多白色的水蛇。
再往西一百七十里，是座数历山，山上盛产黄金，山下盛产银，山中的树木大多是杻树和橿树，而禽鸟大多是鹦䳇。楚水从这座山发源，然后向南流入渭水，水中有很多白色的珍珠。
再往西北五十里，是座高山，山上有丰富的白银，山下到处是青碧、雄黄，山中的树木大多是棕树，而草大多是小竹丛。泾水从这座山发源，然后向东流入渭水，水中有很多磬石、青碧。
往西南三百里，是座女床山，山南面多出产黄铜，山北面多出产石涅，山中的野兽以老虎、豹子、犀牛和兕居多。山里还有一种禽鸟，形状像野鸡却长着色彩斑斓的羽毛，名称是鸾鸟，一出现天下就会安宁。
再往西二百里，是座龙首山，山南面盛产黄金，山北面盛产铁。苕水从这座山发源，向东南流入泾水，水中有很多美玉。
再往西二百里，是座鹿台山，山上多出产白玉，山下多出产银，山中的野兽以㸲牛、羬羊、白豪居多。山中有一种禽鸟，形状像普通的雄鸡却长着人一样的脸面，名称是凫徯，它的叫声就是自身名称的读音，一出现则天下就会有战争。
往西南二百里，是座鸟危山，山南面多出产磬石，山北面到处是檀树和构树，山中生长着很多女肠草。鸟危水从这座山发源，向西流入赤水，水中有许多粟粒大小的丹沙。
再往西四百里，是座小次山，山上盛产白玉，山下盛产黄铜。山中有一种野兽，形状像普通的猿猴，但头是白色的、脚是红色的，名称是朱厌，一出现就会大起战事。
再往西三百里，是座大次山，山南面多出产垩土，山北面多出产碧玉，山中的野兽以㸲牛、羚羊居多。再往西四百里，是座熏吴山，山上没有花草树木，而有丰富的金属矿物和玉石。
再往西四百里，是座厎阳山，山中的树木大多是水松树、楠木树、樟树，而野兽大多是犀牛、兕、老虎、犳、㸲牛。
再往西二百五十里，是座众兽山，山上遍布㻬琈玉，山下到处是檀树和构树，有丰富的黄金，山中的野兽以犀牛、兕居多。
再往西五百里，是座皇人山，山上有丰富的金属矿物和玉石，山下有丰富的石青、雄黄。皇水从这座山发源，向西流入赤水，水中有很多粟粒大小的丹沙。
再往西三百里，是座中皇山，山上多出产黄金，山下长满了蕙草、棠梨树。
再往西三百五十里，是座西皇山，山南面多出产金，山北面多出产铁，山中的野兽以麋、鹿、麋牛居多。
再往西三百五十里，是座莱山，山中的树木大多是檀树和构树，而禽鸟大多是罗罗鸟，是能喫人的。
总计西方第二列山系之首尾，自钤山起到莱山止，一共十七座山，途经四千一百四十里。其中十座山的山神，都是人的面孔而马的身子。还有七座山的山神都是人的面孔而牛的身子，四只脚和一条臂，扶着拐杖行走，这就是所谓的飞兽之神，祭祀这七位山神，在毛物中用猪、羊作祭品，将其放在白茅草席上。另外那十位山神，祭祀的典礼，在毛物中用一只公鸡，祭祀神时不用米作祭品；毛物的颜色要杂而不必纯一。
西方第三列山系之首座山，叫做崇吾山，它雄居于黄河的南岸，在山上向北可以望见冢遂山，向南可以望见䍃泽，向西可以望见天帝的搏兽山，向东可以望见䗡渊。山中有一种树木，圆圆的叶子白色的花萼，红色的花朵上有黑色的纹理，结的果实与枳实相似，喫了它就能使人多子多孙。山中又有一种野兽，形状像猿猴而臂上却有斑纹，有豹子一样的尾巴而擅长投掷，名称是举父。山中还有一种禽鸟，形状像一般的野鸭子，却只长了一只翅膀和一只眼睛，要两只鸟合起来才能飞翔，名称是蛮蛮，一出现而天下就会发生水灾。
往西北三百里，是座长沙山。泚水从这里发源，向北流入泑水，山上没有花草树木，多的是石青、雄黄。
再往北三百七十里，是座不周山。在山上向北可以望见诸毗山，高高的居于岳崇山之上，向东可以望见泑泽，是黄河源头所潜在的地方，那源头之水喷涌而发出浑浑泡泡的响声。这里有一种特别珍贵的果树，结出的果实与桃子很相似，叶子却很像枣树叶，开着黄色的花朵而花萼却是红红的，喫了它就能使人解除烦恼忧愁。
再往西北四百二十里，是座峚山，山上到处是丹木，红红的茎干上长着圆圆的叶子，开黄色的花朵而结红色的果实，味道是甜的，人喫了它就不感觉饥饿。丹水从这座山发源，向西流入稷泽，水中有很多白色玉石。这里有玉膏，玉膏之源涌出时一片沸沸腾腾的景象，黄帝常常服食享用这种玉膏。这里还出产一种黑色玉石。用这涌出的玉膏，去浇灌丹木，丹木再经过五年的生长，便会开出光艳美丽的五色花朵，结下味道香甜的五色果实。黄帝于是就采撷峚山中玉石的精华，而投种在钟山向阳的南面。后来便生出瑾和瑜这类美玉，坚硬而精密，润厚而有光泽。五种颜色的符彩一同散发出来相互辉映，那就有刚有柔而非常和美。无论是天神还是地鬼，都来服食享用；君子佩带它，能抵御妖邪不祥之气的侵袭。
从峚山到钟山，长四百六十里，其间全部是水泽。在这里生长着许许多多奇怪的禽鸟、怪异的野兽、神奇的鱼类，都是些罕见的怪物。
再往西北四百二十里，是座钟山。钟山山神的儿子叫做鼓，鼓的形貌是人的脸面而龙的身子，他曾和钦丕神联手在昆仑山南面杀死天神葆江，天帝因此将鼓与钦丕诛杀在钟山东面一个叫？崖的地方。钦丕化为一只大鹗，形状像普通的雕鹰却长有黑色的斑纹和白色的脑袋，红色的嘴巴和老虎一样的爪子，发出的声音如同晨鹄鸣叫，一出现就有大的战争；鼓也化为鵕鸟，形状像一般的鹞鹰，但长着红色的脚和直直的嘴，身上是黄色的斑纹而头却是白色的，发出的声音与鸿鹄的鸣叫很相似，在哪个地方出现那里就会有旱灾。
再往西一百八十里，是座泰器山，观水从这里发源，向西流入流沙。这观水中有很多文鳐鱼，形状像普通的鲤鱼，长着鱼一样的身子和鸟一样的翅膀，浑身是苍色的斑纹却是白脑袋和红嘴巴，常常在西海行走，在东海畅游，在夜间飞行。它发出的声音如同鸾鸡鸟啼叫，而肉味是酸中带甜，人喫了它的肉就可治好癫狂病，一出现而天下就会五谷丰登。
再往西三百二十里，是座槐江山。丘时水从这座山发源，然后向北流入泑水。水中有很多蠃母，山上蕴藏着丰富的石青、雄黄，还有很多的琅玕、黄金、玉石，山南面到处是粟粒大小的丹沙，而山北阴面多产带符彩的黄金白银。这槐江山确实可以说是天帝悬在半空的园圃，由天神英招主管着，而天神英招的形状是马的身子而人的面孔，身上长有老虎的斑纹和禽鸟的翅膀，巡行四海而传布天帝的旨命，发出的声音如同用辘轳抽水。在山上向南可以望见昆仑山，那里火光熊熊，气势恢宏。
向西可以望见大泽，那里是后稷死后埋葬之地。大泽中有很多玉石，大泽的南面有许多榣木，而在它上面又有若木。向北可以望见诸毗山，是叫做槐鬼离仑的神仙所居住的地方，也是鹰鸇等飞禽的栖息地。向东可以望见那四重高的桓山，有穷鬼居住在那里，各自分类聚集于一起。这里有大水下泻，清清冷冷而汩汩流淌。有个天神住在山中，他的形状像普通的牛，但却长着八只脚、两个脑袋并拖着一条马的尾巴，啼叫声如同人在吹奏乐器时薄膜发出的声音，在哪个地方出现那里就有战争。
往西南四百里，是座昆仑山，这里确实是天帝在下界的都邑，天神陆吾主管它。这位天神的形貌是老虎的身子却有九条尾巴，一副人的面孔可长着老虎的爪子；这个神，主管天上的九部和天帝苑圃的时节。山中有一种野兽，形状像普通的羊却长着四只角，名称是土蝼，是能喫人的。山中有一种禽鸟，形状像一般的蜜蜂，大小与鸳鸯差不多，名称是钦原，这种钦原鸟刺螫其它鸟兽就会使它们死去，刺螫树木就会使树木枯死。山中还有另一种禽鸟，名称是鹑鸟，它主管天帝日常生活中各种器用服饰。山中又有一种树木，形状像普通的棠梨树，却开着黄色的花朵并结出红色的果实，味道像李子却没有核，名称是沙棠，可以用来辟水，人喫了它就能漂浮不沉。山中还有一种草，名称是薲草，形状很像葵菜，但味道与葱相似，喫了它就能使人解除烦恼忧愁。黄河水从这座山发源，然后向南流而东转注入无达山。赤水也发源于这座山，然后向东南流入汜天水。洋水也发源于这座山，然后向西南流入丑涂水。黑水也发源于这座山，然后向西流到大杆山。这座山中有许多奇怪的鸟兽。
再往西三百七十里，是坐乐游山。桃水从这座山发源，向西流入稷泽，这里到处有白色玉石，水中还有很多䱻鱼，形状像普通的蛇却长着四只脚，是能喫鱼类的。
往西行四百里水路，就是流沙，再行二百里便到蠃母山，天神长乘主管这里，他是天的九德之气所生。这个天神的形貌像人却长着犳的尾巴。山上到处是玉石，山下到处是青石而没有水。
再往西三百五十里，是座玉山，这是西王母居住的地方。西王母的形貌与人一样，却长着豹子一样的尾巴和老虎一样的牙齿而且喜好啸叫，蓬松的头发上戴着玉胜，是主管上天灾厉和五刑残杀之气的。山中有一种野兽，形状像普通的狗却长着豹子的斑纹，头上的角与牛角相似，名称是狡，发出的声音如同狗叫，在哪个国家出现就会使那个国家五谷丰登。山中还有一种禽鸟，形状像野鸡却通身是红色，名称是胜遇，是能喫鱼类的，发出的声音如同鹿在鸣叫，在哪个国家出现就会使那个国家发生水灾。
往西四百八十里，是座轩辕丘，这里没有花草树木。洵水从轩辕丘发源，向南流入黑水，水中有很多粟粒大小的丹沙，还有很多石青、雄黄。
再往西三百里，是座积石山，山下有一个石门，黄河水漫过石门向西南流去。这座积石山，是万物俱全的。
再往西二百里，是座长留山，天神白帝少昊居住在这里。山中的野兽都是花尾巴，而禽鸟都是花脑袋。山上盛产彩色花纹的玉石。它实是员神磈氏的宫殿。这个神，主要掌管太阳落下西山时光线射向东方的反影。
再往西二百八十里，是座章莪山，山上没有花草树木，到处是瑶、碧一类的美玉。山里常常出现十分怪异的物象。山中有一种野兽，形状像赤豹，长着五条尾巴和一只角，发出的声音如同敲击石头的响声，名称是狰。山中还有一种禽鸟，形状像一般的鹤，但只有一只脚，红色的斑纹和青色的身子而有一张白嘴巴，名称是毕方，它鸣叫的声音就是自身名称的读音，在哪个地方出现那里就会发生怪火。
再往西三百里，是座阴山。浊浴水从这座山发源，然后向南流入蕃泽，水中有很多五彩斑斓的贝壳。山中有一种野兽，形状像野猫却是白脑袋，名称是天狗，它发出的叫声与“猫猫”的读音相似，人饲养它可以辟凶邪之气。再往西二百里，是座符惕山，山上到处是棕树和楠木树，山下有丰富的金属矿物和玉石。一个叫江疑的神居住于此。这座符惕山，常常落下怪异之雨，风和云也从这里兴起再往西二百二十里，是座三危山，三青鸟栖息在这里。这座三危山，方圆百里。山上有一种野兽，形状像普通的牛，却长着白色的身子和四只角，身上的硬毛又长又密好像披着蓑衣，名称是？？，是能喫人的。山中还有一种禽鸟，长着一个脑袋却有三个身子，形状与？鸟很相似，名称是鸱。
再往西一百九十里，是座騩山，山上遍布美玉而没有石头。天神耆童居住在这里，他发出的声音常常像是敲钟击磬的响声。山下到处是一堆一堆的蛇。
再往西三百五十里，是座天山，山上有丰富的金属矿物和玉石，也出产石青、雄黄。英水从这座山发源，然后向西南流入汤谷。山里住着一个神，形貌像黄色口袋，发出的精光红如火，长着六只脚和四只翅膀，浑浑沌沌没有面目，他却知道唱歌跳舞，原本是帝江。
再往西二百九十里，是座泑山，天神蓐收居住在这里。山上盛产一种可用作颈饰的玉石，山南面到处是瑾、瑜一类美玉，而山北面到处是石青、雄黄。站在这座山上，向西可以望见太阳落山的情景，那种气象浑圆，由天神红光所主管。
往西行一百里水路，便到了翼望山，山上没有花草树木，到处是金属矿物和玉石。山中有一种野兽，形状像一般的野猫，只长着一只眼睛却是三条尾巴，名称是讙，发出的声音好像能赛过一百种动物的鸣叫，饲养它可以辟凶邪之气，人喫了它的肉就能治好黄疸病。山中还有一种禽鸟，形状像普通的乌鸦，却长着三个脑袋、六条尾巴并且喜欢嘻笑，名称是鵸鵌，喫了它的肉就能使人不做恶梦，还可以辟凶邪之气。
总计西方第三列山系之首尾，从崇吾山起到翼望山止，一共二十三座山，途经六千七百四十四里。诸山山神的形貌都是羊的身子人的面孔。祭祀山神的典礼，是把祀神的一块吉玉埋入地下，祀神的米用稷米。
西方第四列山系之首座山，叫做阴山，山上生长着茂密的构树，但没有石头，这里的草以莼菜、蕃草居多。阴水从这座山发源，向西流入洛水。往北五十里，是座劳山，这里有茂盛的紫草。弱水从这座山发源，然后向西流入洛水。
往西五十里，是座罢谷山，洱水从这里发源，然后向西流入洛水，水中多出产紫色美石、碧色玉石。
往北一百七十里，是座申山，山上是茂密的构树和柞树，山下是茂密的杻树和僵树，山南面还有丰富的金属矿物和玉石。区水从这座山发源，然后向东流入黄河。
往北二百里，是座鸟山，山上到处是桑树，山下到处是构树，山北面盛产铁，而山南面盛产玉石。辱水从这座山发源，然后向东流入黄河。
再往北二十里，是座上申山，山上没有花草树木，但到处是大石头，山上是茂密的榛树和楛树，野兽以白鹿居多。山里最多的禽鸟是当扈鸟，形状像普通的野鸡，却用髯毛当翅膀来奋起高飞，喫了它的肉就能使人不眨眼睛。汤水从这座山发源，向东流入黄河。
再往北八十里，是座诸次山，诸次水从这座山发源，然后向东流入黄河。这座诸次山，到处生长着树木却不生长花草，也没有禽鸟野兽栖居，但有许多蛇聚集在山中。
再往北一百八十里，是座号山，山里的树木大多是漆树、棕树，而草以白芷草、虈草、芎草居多。山中还盛产汵石。端水从这座山发源，然后向东流入黄河。
再往北二百二十里，是座盂山，山北面盛产铁，山南面盛产铜，山中的野兽大多是白色的狼和白色的虎，禽鸟也大多是白色的野鸡和白色的翠鸟。生水从这座山发源，然后向东流入黄河。
往西二百五十里，是座白于山，山上是茂密的松树和柏树，山下是茂密的栎树和檀树，山中的野兽大多是㸲牛、羬羊，而禽鸟以猫头鹰之类的居多。洛水发源于这座山的南面，然后向东流入渭水；夹水发源于这座山的北面，向东流入生水。
往西北三百里，是座由首山，没有花草树木，而冬季夏季都有积雪。申水从这座山上发源，潜流到山下，水中有很多白色玉石。
再往西五十五里，是座泾谷山。泾水从这座山发源，向东南流入渭水，这里多出产白银和白玉。
再往西一百二十里，是座刚山，到处是茂密的漆树，多出产㻬琈玉。刚水从这座山发源，向北流入渭水。这里有很多神？，形状是人的面孔野兽的身子，长着一只脚一只手，发出的声音像人呻吟。
再往西二百里，便到了刚山的尾端。洛水就发源于此，然后向北流入黄河。这里有很多的蛮蛮兽，形状像普通的老鼠却长着甲鱼的脑袋，发出的声音如同狗叫。
再往西三百五十里，是座英鞮山，山上生长着茂密的漆树，山下蕴藏着丰富的金属矿物和玉石，禽鸟野兽都是白色的。涴水从这座山发源，然后向北流入陵羊泽。水里有很多冉遗鱼，长着鱼的身子蛇的头和六只脚，眼睛长长的像马耳朵，喫了它的肉就能使人睡觉不做恶梦，也可以辟凶邪之气。
再往西三百里，是座中曲山，山南阳面盛产玉石，山北阴面盛产雄黄、白玉和金属矿物。山中有一种野兽，形状像普通的马却长着白身子和黑尾巴，一只角，老虎的牙齿和爪子，发出的声音如同击鼓的响声，名称是驳，是能喫老虎和豹子的，饲养它可以辟兵器。山中还有一种树木，形状像棠梨，但叶子是圆的并结红色的果实，果实像木瓜大小，名称是櫰木，人喫了它就能增添气力。
再往西二百六十里，是座邽山。山上有一种野兽，形状像一般的牛，但全身长着刺猬毛，名称是穷奇，发出的声音如同狗叫，是能喫人的。蒙水从这座山发源，向南流入洋水，水中有很多黄贝；还有一种蠃鱼，长着鱼的身子却有鸟的翅膀，发出的声音像鸳鸯鸟鸣叫，在哪个地方出现那里就会有水灾。
再往西二百二十里，是座鸟鼠同穴山，山上有很多白色的虎、洁白的玉。渭水从这座山发源，然后向东流入黄河，水中生长着许多鳋鱼，形状像一般的鳣鱼，在哪个地方出没那里就会有大战发生。滥水从鸟鼠同穴山的西面发源，向西流入汉水，水中有很多？魮鱼，形状像反转过来的铫，但长着鸟的脑袋而鱼一样的鳍和尾巴，叫声就像敲击磬石发出的响声，是能吐出珠玉的。
西南三百六十里，是座崦嵫山，山上生长着茂密的丹树，叶子像构树叶，结出的果实像瓜大小，红色的花萼却带着黑色的斑纹，人喫了它就可以治癒黄疸病，还可以辟火。山南面有很多乌龟，而山北阴面到处是玉石。苕水从这座山发源，然后向西流入大海，水中有很多磨石。山中有一种野兽，形状是马的身子而鸟的翅膀，人的面孔而蛇的尾巴，是很喜欢把人抱着举起的，名称是孰湖。山中还有一种禽鸟，形状像一般的猫头鹰而长着人的面孔，蜼一样的身子却拖着一条狗尾巴，它发出的叫声就是自己的名字，在哪个地方出现那里就会有大旱灾。
总计西方第四列山系，从阴山开始，直到崦嵫山为止，一共十九座山，途经三千六百八十里。祭祀诸山山神的典礼，都是用一只白色鸡献祭，祀神的米用稻米，拿白茅草来做神的座席。
以上是西方经历之山的记录，总共七十七座山，一万七千五百一十七里。', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f7c0ce818559d0711c0", "shortContent": "在古代，剑是既便于随身携带又攻防皆宜的短兵器，不论王公贵族，还是壮士书生，乃至一般平民，都希望能有一把特别锋利的剑。但是，真正特别锋利的宝剑，难遇难得，因此或出于期冀之心，或出于羡慕之情，便幻想、编造出了一些有关宝剑的神怪的故事来。本篇就是其中之一。\n本篇《昆吾山》，实质上是一首宝剑赞。从总体上来看，它是由两部分构成的。前一部分可称之为“越王八剑赞”，即对八剑直接赞颂。作者采用了排比的手法，逐一说...", "authors": ["何均地"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522503529, '5abf1e7e9f54541656d86a0c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636854, '山海经 · 山经 · 北山经', NULL, 18, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E5%8C%97%E5%B1%B1%E7%BB%8F/19829087?fr=aladdin', '', '北山经之首，曰单狐之山，多机木，其上多华草。逢漨水出焉，而西流注于泑水，其中多芘石文石。
又北二百五十里，曰求如之山，其上多玉，无草木。滑水出焉，而西流注于诸毗之水。其中多滑鱼。其状如鱓，赤背，其音如梧，食之已疣。其中多水马，其状如马，文臂牛尾，其音如呼。
又北三百里，曰带山，其上多玉，其下多青碧。有兽焉，其状如马，一角有错，其名曰灌疏，可以辟火。有鸟焉，其状如乌，五采而赤文，名曰鵸余？，是自为牝牡，食之不疽。彭水出焉，而西流注于芘湖之水，中多鯈鱼，其状如鸡而赤毛，三尾六足四首，其音如鹊，食之可以已忧。
又北四百里，曰谯明之山。谯水出焉，西流注于河。其中多何罗之鱼，一首而十身，其音如吠犬，食之已痈。有兽焉，其状如貆而赤毫，其音如榴榴，名曰孟槐，可以御凶。是山也，无草木，多青雄黄。
又北三百五十里，曰涿光之山。嚣水出焉，而西流注于河。其中多<同习>々之鱼，其状如鹊而十翼，鳞皆在羽端，其音如鹊，可以御火，食之不瘅。其上多松柏，其下多棕橿，其兽多{鹿霝}羊，其鸟多蕃。
又北三百八十里，曰虢山，其上多漆，其下多桐椐。其阳多玉，其阴多铁。伊水出焉，西流注于河。其兽多橐驼，其鸟多窝，状如鼠而鸟翼，其音如羊，可以御兵。
又北四百里，至于虢山之尾，其上多玉而无石。鱼水出焉，西流注于河，其中多文贝。
又北二百里，曰丹熏之山，其上多樗柏，其草多韭韭，多丹囗。熏水出焉，而西流注于棠水。有兽焉，其状如鼠，而菟首麋身，其音如獆犬，以其尾飞，名曰耳鼠，食之不？采，又可以御百毒。
又北二百八十里，曰石者之山，其上无草木，多瑶碧。泚水出焉，西流注于河。有兽焉，其状如豹，而文题白身，名曰孟极，是善伏，其鸣自呼。
又北百一十里，曰边春之山，多葱、葵、韭、桃、李。杠水出焉，而西流注于泑泽。有兽焉，其状如禺而文身，善笑，见人则卧，名曰幽鴳，其鸣自呼。
又北二百里，曰蔓联之山，其上无草木，有兽焉，其状如禺而有鬣，牛尾、文臂、马虒，见人则呼，名曰足訾，其鸣自呼。有鸟焉，群居而朋飞，其毛如雌雉，名曰，其鸣自呼，食之已风。
又北八百里，曰单张之山，其上无草木。有兽焉，其状如豹而长尾，人首而牛耳，一目，名曰诸犍，善咤，行则衔其尾。有鸟焉，其状如雉，而文首、白翼、黄足，名曰白鵺，食之已嗌痛，可以已痸。栎水出焉，在而南流注于杠水。
又北三百二十里，曰灌题之山，其上多樗柘，其下多流沙，多砥。有兽焉，其状如牛而白尾，其音如詨，名曰那父。有鸟焉，其状如雌雉而人面，见人则跃，名曰竦斯，其鸣自呼也。匠韩之水出焉，而西流注于泑泽，其中多磁石。
又北二百里，曰潘侯之山，其上多松柏，其下多榛楛，其阳多玉，其阴多铁。有兽焉，基状如牛，而四节生毛，或曰旄牛。边水出焉，而南流注于栎泽。
又北二百三十里，曰小咸之山，无草木，冬夏有雪。
北二百八十里，曰大咸之山，无草木，其下多玉。是山也，四方，不可以上。有蛇名曰长蛇，其毛如彘豪，其音如鼓柝。
又北三百二十里，曰敦薨之山，其上多棕枬，其下多茈草。敦薨之水出焉，而西流注于泑泽。出于昆仑之东北隅，实惟河原。其中多赤鲑，其兽多兕，旄牛，其鸟多柝鸠。
又北二百里，曰少咸之山，无草木，多青碧。有兽焉，其状如牛，而赤身、人面、马足，名曰窥窳，其音如婴儿，是食人。敦水出焉，东流注于雁门之水，其中多？市市之鱼。食之杀人。
又北二百里，曰狱法之山。瀼泽之出焉，而东北流注于泰泽。其中多？巢鱼，其状如鲤而鸡足，食之已疣。有兽焉，其状如犬而人面，善投，见人则笑，其名山？，其行如风，见则天下大风。
又北二里，曰北岳之山，多枳棘刚木。有兽焉，其状如牛，而四角、人、耳、彘耳，其名曰诸怀，基音如鸣雁，是食人。诸怀之水出焉，而西流注于嚣水，水中多鮨鱼，鱼身而犬首，其音如婴儿，食之已狂。
又北百八十里，曰浑夕之山，无草木，多铜玉。嚣水出焉，而西流注于海。有蛇一首两身，名曰肥遗，见则其国大旱。
又北五十里，曰北单之山，无草木，多葱韭。
又北百里，曰罴差之山，无草木，多马。
又北百八十里，曰北鲜之山，是多马，鲜水出焉，而西北流注于涂吾之水。
又北百七十里，曰堤山，多马。有兽焉，其状如豹而文首，名曰狕。堤水出焉，而东流注于泰泽，其中多龙龟。
凡北山经之首，自单狐之山至于堤山，凡二十五山，五千四百九十里，其神皆人面蛇身。其祠之，毛用一雄鸡彘瘗，吉玉用一珪，瘗而为不糈。其山北人，皆生食不火之物。
北次二经之首，在河之东，其首枕汾，其名曰管涔之山。其上无木而多草，其下多玉。汾水出焉，而西流注于河。
又西二百五十里，曰少阳之山，其上多玉，其下多赤银。酸水出焉，而东流注于汾水，其中多美赭。
又北五十里，曰县雍之山，其上多玉，其下多铜，其兽多闾麋，其鸟多白翟白有？。晋水出焉，而东南流注于汾水。其中多鮆鱼，其状如囗而赤麟，其音如叱，食之不骄。
又北二百里，曰狐岐之山，无草木，多青碧。胜水出焉，而东北流注于汾水，其中多苍玉。
又北三百五十里，曰白沙山，广员三百里，尽沙也，无草木鸟兽。鲔水出于其上，潜于其下，是多白玉。
又北四百里，曰尔是之山，无草木，无水。
又北三百八十里，曰狂山，无草木，是山也，冬夏有雪。狂水出焉，而西流注于浮水，其中多美玉。
又北三百八十里，曰诸余之山，其上多铜玉，其下多松柏。诸余之水出焉，而东流注于旄水。
又北三百五十里，曰敦头之山，其上多金玉，无草木。旄水出焉，而东流注于印泽。其中多？孛马，牛尾而白身，一角，其音如呼。
又北三五十里，曰钅句吾之山，其上多玉，其下多铜。有兽焉，其状如羊身人面，其目在腋下，虎齿人爪，其音如婴儿，名曰狍鸮，是食人。
又北三百里，曰北嚣之山，无石，其阳多玉。有兽焉，其状如虎，而白身犬首，马尾彘鬣，名曰独？。有鸟焉，其状如乌，人面，名曰囗冒？，宵飞而昼伏，食之已？曷。涔水出焉，而东流注于邛泽。
又北三百五十里，曰梁渠之山，无草木，多金玉。修水出焉，而东流注于雁门，其兽多居暨，其状如囗而赤毛，其音如豚。有鸟焉，其状如夸父，四翼、一目、犬尾，名曰嚣，其音如鹊，食之已腹痛，可以止衕。
又北四百里，曰姑灌之山，无草木。是山也，科夏有雪。
又北三百八十里，曰湖灌之山，其阳多玉，其阴多碧，多马，湖灌之水出焉，而东流注于海，其中多？旦。有木器厂焉，其叶如柳而赤理。
又北水行五百里，流沙三百里，至于洹山，其上多金玉。三桑生之，其树皆无枝，其高百仞。百果树生之。其下多怪蛇。
又北三百里，曰敦题之山，无草木，多金玉。是錞于北海。
凡北次二经之首，自管涔之山至于敦题之山，凡十七山，五千六百九十里。其神皆蛇身人面。其祠；毛用一雄鸡彘瘗；用一璧一珪，投而不糈。
北次三经之首，曰太行之山。其首曰归山，其上有金玉，其下有碧。有兽焉，其状如囗羊而四角，马尾而有距，其名曰？军，善还，其名自詨有鸟焉，其状台鹊，白身、赤尾、六足，其名曰囗，是善惊，其鸣自詨。
又东北二百里，曰龙侯之山，无草木，多金玉。决决之水出焉，而东流注于河。其中多人鱼，其状如？帝鱼，四足，其音如婴儿，食之无痴疾。
又东北二百里，曰马成之山，其上多文石，其阴多金玉。有兽焉，其状如白犬而黑头，见人则飞，其名曰天马，其鸣自詨，有鸟焉，其状如乌，首白而身青、足黄，是名曰鶌鶋。其名自詨，食之不饥，可以已寓。
又东北七十里，曰咸山，其上有玉，其下多铜，是多松柏，草多茈草。条菅之水出焉，而西南流注于长泽。其中多器酸，三岁一成，食之已疠。
又东北二百里，曰天池之山，其上无草木，多文石。有兽焉，其状如兔而鼠首，以其背飞，其名曰飞鼠。渑水出焉，潜于其下，其中多黄垩。
又东三百里，曰阳山，其上多玉，其下多金铜。有兽焉，其状如牛而尾，其颈，其状如句瞿，其名曰领胡，其鸣自詨，食之已狂。有鸟焉，其状如赤雉，而五采以文，是自为牝牡，名曰象蛇，其名自詨。留水出焉，而南流注于河。其中有<？臽>父之鱼，其状如鲋鱼，鱼首而彘身，食之已呕。
又东三百五十里，曰贲闻之山，其上多苍玉，其下多黄垩，多涅石。
又北百里，曰王屋之山，是多石。氵联水出焉，而西北流注于泰泽。
又东北三百里，曰教山，其上多玉而无石。教水出焉，西流注于河，是水冬干而夏流，实惟干河。其中有两山。是山也，广员三百步，其名曰发丸之山，其上有金玉。
又南三百里，曰景山，南望盐贩之泽，北望少泽。其上多草、薯薁，其草多秦椒，其阴多赭，其阳多玉。有鸟焉，其状如蛇，而四翼、六目、六足，名曰酸与，其鸣自詨，见则其邑有恐。
又东南三百二十里，曰孟门之山，其上多苍玉，多金，其下多黄垩，多涅石。
又东南三百二十里，曰平山。平水出于其上，潜于其下，是多美玉。
又东二百里，曰京山，有美玉，多漆木，多竹，其阳有赤铜，其阴有玄？肃。高水出焉，南流注于河。
又东二百里，曰虫尾之山，其上多金玉，其下多竹，多青碧。丹水出焉，南流注于河；薄水出焉，而东南流注于黄泽。
又东三百里，曰彭毗之山，其上无草木，多金玉，其下多水。蚤林之水出焉，东南流注于河。肥水出焉，而南流注于床水，其中多肥遗之蛇。
又东百八十里，曰小侯之山。明漳之水出焉，南流注于黄泽。有鸟焉，其状如乌而白文，名曰鸪，食之不灂。
又东三百七十里，曰泰头之山。共水出焉，南流注于池。其上多金玉，其下多竹箭。
又东北二百里，曰轩辕之山，其上多铜，其下多竹。有鸟焉，其状如枭白首，其名曰黄鸟，其鸣自詨，食之不妒。
又北二百里，曰谒戾之山，其上多松柏，有金玉。沁水出焉，南流注于河。其东有林焉，名曰丹林。丹林之水出焉，南流注于河。婴侯之水出焉，北流注于汜水。
东三百里，曰沮洳之山，无草木，有金玉。濝水出焉，南流注于河。
又北三百里，曰神囷之山，具上有文石，其下有白蛇，有飞虫。黄水出焉，而东流注于洹；滏水出焉，而东流注于欧水。
又北二百里，曰发鸠之山，其上多柘木。有鸟焉，其状如乌，文首、白喙、赤足，名曰精卫，其鸣自詨。是炎帝之少女名曰女娃，女娃游于东海，溺而不返，故为精卫。常衔西山之木石，以堙于东海。漳水出焉，东流注于河。
又东北百二十里，曰少山，其上有金玉，其下有铜。清漳之水出焉，东流注于浊漳之水。
又东北二百里，曰锡山，其上多玉，其下有砥。牛首之水出焉，而东流注于滏水。
又北二百里，曰景山，有美玉。景水出焉，东南流注于海泽。
又北百里，曰题首之山，有玉焉，多石，无水。
又北百里，曰绣山，其上有玉、青碧，其木多栒，其草多芍药、芎藭。洧水出焉，而东流注于河，其中有囗、黾。
又北百二十里，曰松山。阳水出焉，东北流注于河。
又北百二十里，曰敦与之山，其上无草木，有金玉。溹水出于其阳，而东流注于泰陆之水；泜水出于其阴，而东流注于彭水；槐水出焉，而东流注于泜泽。
又北百七十里，曰柘山，其阳有金玉，其阴有铁。历聚之水出焉，而北流注于洧水。
又北二百里，曰维龙之山，其上有碧玉，其阳有金，其阴有铁。肥水出焉，而东流注于皋泽，其中多礨石。敞铁之水出焉，而北于大泽。
又北百八十里，曰白马之山，其阳多石玉，其阴多铁，多赤铜。木马之水了出焉，而东北流注于虖沱。
又北二百里，曰空桑之山，无草木，冬夏有雪。
空桑空桑之水出焉，东流注于虖沱。
又北三百里，曰泰戏之山，无草木，多金玉。有兽焉，其状如羊，一角一目，目在耳后，其名曰东々，其鸣自詨。虖沱之水出焉，而东流注于溇水。液女之水出于其阳，南流注于沁水。
又北三百里，曰石山，多藏金玉。濩濩之水出焉，而东流注于虖沱；鲜于之水出焉，而南流注于虖沱。
又北二百里，曰童戎之山。皋涂之水出焉，而东流注于溇液水。
又北三百里，曰高是之山。滋水出焉，而南流注于虖沱。其木多棕，其草多条。滱水出焉，东流注于河。
又北三百里，曰陆山，多美玉。美玉姜阝水出焉，而东流注于河。
又北二百里，曰沂山般水出焉，而东流注于河。
北百二十里，曰燕山，多婴石。燕水出焉，东流注于河。
又北山行五百里，水行五百里，至于饶山。是无草木，多瑶碧，其兽多橐？？，其鸟多鹠。历虢之水出焉，而东流注于河，其中有师鱼，食之杀人。
又北四百里，曰乾山，无草木，其阳有金玉，其阴有铁而无水。有兽焉，其状如牛而三足，其名曰獂，其鸣自詨。
又北五百里，曰伦山。伦水出焉，而东流注于河。有兽焉，其状如麋，其川在尾上，其名曰罴。
又北五百里，曰碣石之山。绳水出焉，而东流注于河，其中多蒲夷之鱼。基上有玉，其下多青碧。
又北水行五百里，至于雁门之山，无草木。
又北水行四百里，至于泰泽。其中有山焉，曰帝都之山，广员百里，无草木，有金玉。
又北五百里，曰錞于毋逢之山，北望鸡号之山，其风如䬅。西望幽都之山，浴水出焉。是有朋蛇，赤首白身，其音如牛，见则其邑大旱。
凡北次三经之首，自太行之山以至于无逢之山，凡四十六山，万二千三百五十里。其神状皆马身而人面者廿神。其祠之，皆用一藻茝瘗之。其十四神状皆彘身而载玉。其祠之，皆玉，不瘗。其十神状皆彘身而八足蛇尾。其祠之，皆用一壁瘗之。大凡四十四神，皆用稌糈米祠之。此皆不火食。
右北经之山志，凡八十七山，二万三千二百三十里。', '《山海经·北山经》是创作于战国时期的一篇散文，出自《山海经》，作者不详。', '', '（注释：■为打不出来的字）
北方第一列山系之首座山，叫做单狐山，有茂密的桤木树，也有茂盛的华草。漨水从这座山发源，然后向西流入泑水，水中有很多紫石、文石。再往北二百五十里，是座求如山，山上蕴藏着丰富的铜，山下有丰富的玉石，但没有花草树木。滑水从这座山发源，然后向西流入诸水。水中有很多滑鱼，形状像一般的鳝鱼，却是红色的脊背，发出的声音像人支支吾吾的话语，吃了它的肉就能治好人的疣赘病。水中还生长着很多水马，形状与一般的马相似，但前腿上长有花纹，并拖着一条牛尾巴，发出的声音像人呼喊。再往北三百里，是座带山，山上盛产玉石，山下盛产青石碧玉。山中有一种野兽，形状像普通的马，长的一只角有如粗硬的磨石，名称是疏，人饲养它可以辟火。山中还有一种禽鸟，形状像普通的乌鸦，但浑身是带着红色斑纹的五彩羽毛，名称是鵸，这种鵸鸟自身有雌雄二种性器官，吃了它的肉就能使人不患痈疽病。彭水从这座山发源，然后向西流入芘湖水，水中有很多儵鱼，形状像一般的鸡却长着红色的羽毛，还长着三条尾巴、六只脚、四只眼睛，它的叫声与喜鹊的鸣叫相似，吃了它的肉就能使人无忧无虑。再往北四百里，是座谯明山。谯明水从这座山发源，向西流入黄河。水中生长着很多何罗鱼，长着一个脑袋却有十个身子，发出的声音像狗叫，人吃了它的肉就可以治愈痈肿病。山中有一种兽，形状像豪猪却长着柔软的红毛，叫声如同用辘轳抽水的响声，名称是孟槐，人饲养它可以辟凶邪之气。这座谯明山，没有花草树木，到处是石青、雄黄。再往北三百五十里，是座涿光山。嚻水从这座山发源，然后向西流入黄河。水中生长着很多鳛鳛鱼，形状像一般的喜鹊却长有十只翅膀，鳞甲全长在羽翅的尖端，发出的声音与喜鹊的鸣叫相似，人饲养它可以辟火，吃了它的肉就能治好人的黄疸病。山上到处是松树和柏树，而山下到处是棕树和橿树，山中的野兽以羚羊居多，禽鸟以蕃鸟居多。再往北三百八十里，是座虢山，山上是茂密的漆树，山下是茂密的梧桐树和椐树，山南阳面盛产玉石，山北阴面盛产铁。伊水从这座山发源，向西流入黄河。山中的野兽以橐驼最多，而禽鸟大多是寓鸟，形状与一般的老鼠相似却长着鸟一样的翅膀，发出的声音像羊叫，人饲养它可以辟兵器。再往北四百里，便到了虢山的尾端，山上到处是美玉而没有石头。鱼水从这里发源，向西流入黄河，水中有很多花纹斑斓的贝。再往北二百里，是座丹熏山，山上有茂密的臭椿树和柏树，在众草中以野韭菜和野薤菜最多，还盛产丹雘。熏水从这座山发源，然后向西流入棠水。山中有一种野兽，形状像一般的老鼠，却长着兔子的脑袋和麋鹿的耳朵，发出的声音如同狗嗥叫，用尾巴飞行，名称是耳鼠，人吃了它的肉就不会生膨胀病，还可以辟百毒之害。再往北二百八十里，是座石者山，山上没有花草树木，但到处是瑶、碧之类的美玉。泚水从这座山发源，向西流入黄河。山中有一种野兽，形状像普通的豹子，却长着花额头和白身子，名称是孟极，善于伏身隐藏，它叫的声音便是自身名称的读音。再往北一百一十里，是座边春山，山上到处是野葱、葵菜、韭菜、野桃树、李树。杠水从这座山发源，然后向西流入泑泽。山中有一种野兽，形状像猿猴而身上满是花纹，喜欢嘻笑，一看见人就假装睡着，名称是幽鴳，它叫的声音便是自身名称的读音。再往北二百里，是座蔓联山，山上没有花草树木。山中有一种野兽，形状像猿猴却长着鬣毛，还有牛一样的尾巴、长满花纹的双臂、马一样的蹄子，一看见人就呼叫，名称是足訾，它叫的声音便是自身名称的读音。山中又有一种禽鸟，喜欢成群栖息而又结队飞行，尾巴与雌野鸡相似，名称是鵁。它叫的声音便是自身名称的读音，人吃了它的肉就能治好风痹病。又北百八十里，曰单张之山，其上无草木。有兽焉，其状如豹而长尾，人首而牛耳，一目，名曰诸犍，善咤再往北一百八十里，是座单张山，山上没有花草树木。山中有一种野兽，形状像豹子却拖着一条长长的尾巴，还长着人一样的脑袋和牛一样的耳朵，一只眼睛，名称是诸犍，喜欢吼叫，行走时就用嘴衔着尾巴，卧睡时就将尾巴盘蜷起来。山中又有一种禽鸟，形状像普通的野鸡，却长着花纹脑袋、白色翅膀、黄色脚，名称是白■，人吃了它的肉就能治好咽喉疼痛的病，还可以治愈疯癫病。栎水从这座山发源，然后向南流入杠水。再往北三百二十里，是座灌题山，山上是茂密的臭椿树和柘树，山下到处是流沙，还多出产磨石。山中有一种野兽，形状像普通的牛却拖着一条白色的尾巴，发出的声音如同人在高声呼唤，名称是那父。山中还有一种禽鸟，形状像一般的雌野鸡却长着人的面孔，一看见人就跳跃，名称是竦斯，它叫的声音便是自身名称的读音。匠韩水从这座山发源，然后向西流入泑泽，水中有很多磁铁石。再往北二百里，是座潘侯山，山上是茂密的松树和柏树，山下是茂密的榛树和楛树，山南阳面蕴藏着丰富的玉石，山北阴面蕴藏着丰富的铁。山中有一种野兽，形状像一般的牛，但四肢关节上都有长长的毛，名称是牦牛。边水从这座山发源，然后向南流入栎泽。再往北二百三十里，是座小咸山，没有花草树木，67冬天和夏天都有积雪。往北二百八十里，是座大咸山，没有花草树木，山下盛产玉石。这座大咸山，呈现四方形，人不能攀登上去。山中有一种蛇叫做长蛇，身上的毛与猪脖子上的硬毛相似，发出的声音像是人在敲击木梆子。再往北三百二十里，是座敦薨山，山上是茂密的棕树和楠木树，山下是大片的紫草。敦薨水从这座山发源，然后向西流入泑泽。这泑泽位于昆仑山的东北角，确实就是黄河的源头。水中有很多赤鲑。那里的野兽以兕、牦牛最多，而禽鸟大多是布谷鸟。再往北二百里，是座少咸山，山上没有花草树木，到处是青石碧玉。山中有一种野兽，形状像普通的牛，却长着红色的身子、人的面孔、马的蹄子，名称是窫窳，发出的声音如同婴儿啼哭，是能吃人的。敦水从这座山发源，向东流入雁门水，水中生长着很多■■鱼，人吃了它的肉就会中毒而死。再往北二百里，是座狱法山。瀤泽水从这座山发源，然后向东北流入泰泽。水中生长着很多■鱼，形状像一般的鲤鱼却长着鸡爪子，人吃了它的肉就能治好赘瘤病。山中还有一种野兽，形状像普通的狗却长着人的面孔，擅长投掷，一看见人就嘻笑，名称是山■，它走起来就像刮风，一出现天下就会起大风。再往北二百里，是座北岳山，山上到处是枳树酸枣树和檀、柘一类的树木。山中有一种野兽，形状像一般的牛，却长着四只角、人的眼睛、猪的耳朵，名称是诸怀，发出的声音如同大雁鸣叫，是能吃人的。诸怀水从这座山发源，然后向西流入嚻水，水中有很多鮨鱼，长着鱼的身子而狗的脑袋，发出的声音像婴儿啼哭，人吃了它的肉就能治愈疯狂病。再往北一百八十里，是座浑夕山，山上没有花草树木，盛产铜和玉石。嚻水从这座山发源，然后向西北流入大海。这里有一种长着一个头两个身子的蛇，名称是肥遗，在哪个国家出现那个国家就会发生大旱灾。再往北五十里，是座北单山，山上没有花草树木，却生长着茂盛的野葱和野韭菜。再往北一百里，是座罴差山，没有花草树木，却有很多小个头的野马。再往北一百八十里，是座北鲜山，这里有很多小个头的野马。鲜水从这里发源，然后向西北流入涂吾水。再往北一百七十里，是座堤山，有许多小个头的野马。山中有一种野兽，形状像一般的豹子而脑袋上有花纹，名称是狕。堤水从这座山发源，然后向东流入泰泽，水中有很多龙和龟。总计北方第一列山系之首尾，自单狐山起到堤山止，一共二十五座山，途经五千四百九十里，诸山山神都是人的面孔蛇的身子。祭祀山神：把毛物中用作祭品的一只公鸡和一头猪埋入地下，在祀神的美好玉器中用一块玉珪，只是埋入地下而不需要用米来祭祀。住在诸山北面的人，都生吃未经火烤的食物。北方第二列山系之首座山，坐落在黄河的东岸，山的首端枕着汾水，这座山叫管涔山。山上没有树木却到处是茂密的花草，山下盛产玉石。汾水从这座山发源，然后向西流入黄河。再往北二百五十里，是座少阳山，山上盛产玉石，山下盛产赤银。酸水从这座山发源，然后向东流入汾水，水中有很多优良赭石。再往北五十里，是座县雍山，山上蕴藏着丰富的玉石，山下蕴藏着丰富的铜，山中的野兽大多是山驴和麋鹿；而禽鸟以白色野鸡和白翰鸟居多。晋水从这座山发源，然后向东南流入汾水。水中生长着很多鱽鱼，形状像小儵鱼却长着红色的鳞甲，发出的声音如同人的斥责声，吃了它的肉就使人没有狐骚臭。再往北二百里，是座狐岐山，山上没有花草树木，到处是青石碧玉。胜水从这座山发源，然后向东北流入汾水，水中有很多苍玉。73又北三百五十里，曰白沙山，广员三百里，尽沙也，无草木鸟兽。鲔（W7i）水出于其上，潜于其下，是多白玉。再往北三百五十里，是座白沙山，方圆三百里大小，到处是沙子，没有花草树木和禽鸟野兽。鲔水从这座山的山顶发源，然后潜流到山下，水中有很多白玉。再往北四百里，是座尔是山，没有花草树木，也没有水。再往北三百八十里，是座狂山，没有花草树木。这座狂山，冬天和夏天都有雪。狂水从这座山发源，然后向西流入浮水，水中有很多优良玉石。再往北三百八十里，是座诸余山，山上蕴藏着丰富的铜和玉石，山下到处是茂密的松树和柏树。诸余水从这座山发源，然后向东流入旄水。再往北三百五十里，是座敦头山，山上有丰富的金属矿物和玉石，但不生长花草树木。旄水从这座山发源，然后向东流入邛泽。山中有很多■马，长着牛一样的尾巴和白色身子，一只角，发出的声音如同人呼唤。再往北三百五十里，是座钩吾山，山上盛产玉石，山下盛产铜。山中有一种野兽，形状是羊的身子人的面孔。眼睛长在腋窝下，有着老虎一样的牙齿和人一样的指甲，发出的声音如同婴儿哭啼，名称是饕餮，食人，贪恋美食，在怪兽中担任厨师。往北三百里，是座北嚻山，没有石头，山南阳面多出产碧玉，山北阴面多出产玉石。山中有一种野兽，形状像一般的老虎，却长着白色身子狗脑袋，马的尾巴猪脖子上的硬毛，名称是独■。山中还有一种禽鸟，形状像一般的乌鸦，却长着人的面孔，名称是■■，在夜里飞行而在白天隐伏，吃了它的肉就能使人不中暑。涔水从这座山发源，然后向东流入邛泽。再往北三百五十里，是座梁渠山，不生长花草树木，有丰富的金属矿物和玉石，脩水从这座山发源，然后向东流入雁门水。山中的野兽大多是居暨兽，形状像汇却浑身长着红色的毛，发出的声音如同小猪叫。山中还有一种禽鸟，形状像夸父，长着四只翅膀、一只眼睛、狗一样的尾巴，名称是嚻，它的叫声与喜鹊的鸣叫相似，人吃了它的肉就可以止住肚子痛，还可以治好腹泻病。再往北四百里，是座姑灌山，没有花草树木。在这座姑灌山上，冬天夏天都有雪。再往北三百八十里，是座湖灌山，山南阳面盛产玉石，山北阴面盛产碧玉，并有许多个头小的野马。湖灌水从这座山发源，然后向东流入大海，水中有很多鳝鱼。山里生长着一种树木，叶子像柳树叶而有红色的纹理。再往北行五百里水路，然后经过三百里流沙，便到了洹山，山上蕴藏着丰富的金属矿物和玉石。山中生长着一种三桑树，这种树都不长枝条，树干高达一百仞，还生长着各种果树。山下有很多怪蛇。再往北三百里，是座敦题山，这里不长花草树木，但蕴藏有丰富的金矿物和玉石。这座山座落在北海的岸边。总计北方第二列山系之首尾，自管涔山起到敦题山止，一共十七座山，途经五千六百九十里。诸山山神都是蛇的身子人的面孔。祭祀山神：把毛物中用作祭品的一只公鸡、一头猪一起埋入地下；在祀神的玉器中用一块玉璧和一块玉珪，一起投向山中而不用米祀神。北方第三列山系之首座山，叫做太行山。太行山的首端叫归山，山上出产金属矿物和玉石，山下出产碧玉。山中有一种野兽，形状像普通的羚羊却有四只角，长着马一样的尾巴和鸡一样的爪子，名称是■，善于旋转起舞，它发出的叫声就是自身名称的读音。山中还有一种禽鸟，形状像一般的喜鹊，长着白身子、红尾巴、六只脚，名称是■，这种■鸟十分惊觉，它发出的叫声就是自身名称的读音。再往东北二百里，是座龙侯山，不生长花草树木，有丰富的金属矿物和玉石。决水从这座山发源，然后向东流入黄河。水中有很多人鱼，形状像一般的■鱼，长有四只脚，发出的声音像婴儿哭啼，吃了它的肉就能使人不得疯癫病。再往东北二百里，是座马成山，山上多出产有纹理的美石，山北阴面有丰富的金属矿物和玉石。山里有一种野兽，形状像普通的白狗却长着黑脑袋，一看见人就腾空飞起，名称是天马，它的叫声就是自身名称的读音。山里还有一种禽鸟，形状像一般的乌鸦，却长着白色的脑袋和青色的身子、黄色的足爪，名称是鶌鶋，它的叫声便是自身名称的读音，吃了它的肉使人不感觉饥饿，还可以医治老年健忘症。再往东北七十里，是座咸山，山上盛产玉石，山下盛产铜，这里到处是松树和柏树，在所生长的草中以紫草最多。条菅水从这座山发源，然后向西南流入长泽。水中多出产器酸，这种器酸三年才能收成一次，吃了它就能治愈人的麻疯病。再往东北二百里，是座天池山，山上没有花草树木，到处是带有花纹的美石。山中有一种野兽，形状像一般的兔子却长着老鼠的头，借助它背上的毛飞行，名称是飞鼠。渑水从这座山发源，然后潜流到山下，水中有很多黄色垩土。再往东三百里，是座阳山，山上有丰富的玉石，山下有丰富的金铜。山中有一种野兽，形状像普通的牛而长着红尾巴，脖子上有肉瘤，像斗的形状，名称是领胡，它发出的叫声便是自身名称的读音，人吃了它的肉就能治愈癫狂症。山中还有一种禽鸟，形状像雌性野鸡，而羽毛上有五彩斑斓的花纹，这种鸟一身兼有雄雌二种性器官，名称是象蛇，它发出的叫声便是自身名称的读音。留水从这座山发源，然后向南流入黄河。水中生长着■父鱼，形状像一般的鲫鱼，长着鱼的头而猪的身子，人吃了它的肉可以治愈呕吐。再往东三百五十里，是座贲闻山，山上盛产苍玉，山下盛产黄色垩土，也有许多涅石。再往北一百里，是座王屋山，这里到处是石头。■水从这座山发源，然后向西北流入泰泽。再往东北三百里，是座教山，山上有丰富的玉石而没有石头。教水从这座山发源，向西流入黄河，这条河水到了冬季干枯而在夏季流水，确实可说是干河。教水的河道中有两座小山，方圆各三百步，名称是发丸山，小山上蕴藏着金属矿物和玉石。再往南三百里，是座景山，在山上向南可以望见盐贩泽，向北可以望见少泽。山上生长着茂密的丛草、薯■，这里的草以秦椒最多，山北阴面多出产赭石，山南阳面多出产玉石。山里有一种禽鸟，形状像一般的蛇，却长有四只翅膀、六只眼睛、三只脚，名称是酸与，它发出的叫声便是自身名称的读音，在哪个地方出现那里就会发生使人惊恐的事情。再往东南三百二十里，是座孟门山，山上蕴藏有丰富的苍玉，还盛产金属矿物，山下到处是黄色垩土，还有许多涅石。再往东南三百二十里，是座平山。平水从这座山的顶上发源，然后潜流到山下，水中有很多优良玉石。再往东二百里，是座京山，盛产美玉，到处有漆树，遍山是竹林，在这座山的阳面出产黄铜，山北阴面出产黑色磨石。高水从这座山发源，向南流入黄河。再往东二百里，是座虫尾山，山上有丰富的金属矿物和玉石，山下到处是竹丛，还有很多青石碧玉。丹水从这座山发源，向南流入黄河。薄水也从这座山发源，向东南流入黄泽。再往东三百里，是座彭■山，山上不生长花草树木，有丰富的金属矿物和玉石，山下到处流水。蚤林水从这座山发源，向东南流入黄河。肥水也从这座山发源，然后向南流入床水，水中有很多叫做肥遗的蛇。再往东一百八十里，是座小侯山。明漳水从这座山发源，向南流入黄泽。山中有一种禽鸟，形状像一般的乌鸦却有白色斑纹，名称是鸪■，吃了它的肉就能使人的眼睛明亮而不昏花。再往东三百七十里，是座泰头山。共水从这座山发源，向南流入虖池水。山上有丰富的金属矿物和玉石，山下到处是小竹丛。再往东北二百里，是座轩辕山。山上多出产铜，山下到处是竹子。山中有一种禽鸟，形状是一般的猫头鹰却长着白脑袋，名称是黄鸟，发出的叫声便是它自身名称的读音，吃了它的肉就能使人不生妒嫉心。再往北二百里，是座谒戾山，山上到处是松树和柏树，还蕴藏着金属矿物和玉石。沁水从这座山发源，向南流入黄河。在这座山的东面有一片树林，叫做丹林。丹林水便从这里发源，向南流入黄河。婴侯水也从这里发源，向北流入氾水。往东三百里，是座沮洳山，不生长花草树木，有金属矿物和玉石。濝水从这座山发源，向南流入黄河。再往北三百里，是座神囷山，山上是带有花纹的漂亮石头，山下有白蛇，还有飞虫。黄水从这座山发源，然后向东流入洹水。滏水也从这座山发源，向东流入欧水。再往北二百里，是座发鸠山，山上生长着茂密的柘树。山中有一种禽鸟，形状像一般的乌鸦，却长着花脑袋、白嘴巴、红足爪，名称是精卫，它发出的叫声就是自身名称的读音。精卫鸟原是炎帝的小女儿，名叫女娃。女娃到东海游玩。淹死在东海里没有返回，就变成了精卫鸟，常常衔着西山的树枝和石子，用来填塞东海。漳水从这座山发源，向东流入黄河。再往东北一百二十里，是座少山，山上出产金属矿物和玉石，山下出产铜。清漳水从这座山发源，向东流入浊漳水。再往东北二百里，是座锡山，山上有丰富的玉石，山下出产磨石。牛首水从这座山发源，然后向东流入滏水。再往北二百里，是座景山，山上出产优良玉石。景水从这座山发源，向东南流入海泽。再往北一百里，是座题首山，这里出产玉石，也有许多石头，但没有水。再往北一百里，是座绣山，山上有玉石、青色碧玉，山中的树木大多是栒树，而草以芍药、芎最多。洧水从这座山发源，然后向东流入黄河，水中有鳠鱼和黾蛙。再往北一百二十里，是座松山。阳水从这座山发源，向东北流入黄河。再往北一百二十里，是座敦与山，山上不生长花草树木、蕴藏有金属矿物和玉石。溹水从敦与山的南面山脚流出，然后向东流入泰陆水；泜水从敦与山的北面山脚流出，然后向东流入彭水；槐水也从这座山发源，然后向东流入泜泽。再往北一百七十里，是座柘山，山南阳面出产金属矿物和玉石，山北阴面出产铁。历聚水从这座山发源，然后向北流入洧水。再往北三百里，是座维龙山，山上出产碧玉，山南阳面有金，山北阴面有铁。肥水从这座山发源，然后向东流入皋泽，水中有很多高耸的大石头。敞铁水也从这座山发源，然后向北流入大泽。再往北一百八十里，是座白马山，山南阳面有很多石头和玉石，山北阴面有丰富的铁，还多出产黄铜。木马水从这座山发源，然后向东北流入虖沱水。再往北二百里，是座空桑山，没有花草树木，冬天夏天都有雪。空桑水从这座山发源，向东流入虖沱水。再往北三百里，是座泰戏山，不生长花草树木，到处有金属矿物和玉石。山中有一种野兽，形状像普通的羊，却长着一只角一只眼睛，眼睛在耳朵的背后，名称是■■，它发出的叫声便是自身名称的读音。虖沱水从这座山发源，然后向东流入溇水。液女水发源于这座山的南面，向南流入沁水。再往北三百里，是座石山，山中有丰富的金属矿物和玉石。濩濩水从这座山发源，然后向东流入虖沱水；鲜于水也从这座山发源，然后向南流入虖沱水。再往北二百里，是座童戎山。皋涂水从这座山发源，然后向东流入溇液水。再往北三百里，是座高是山。滋水从这座山发源，然后向南流入虖沱水。山中的树木大多是棕树，草大多是条草。滱水也从这座山发源，然后向东流入黄河。再往北三百里，是座陆山，有很多优良玉石。■水从这座山发源，然后向东流入黄河。再往北二百里，是座沂山。般水从这座山发源，然后向东流入黄河。往北一百二十里，是座燕山，出产很多的婴石。燕水从这座山发源，向东流入黄河。再往北走五百里山路，又走五百里水路，便到了饶山。这座山不生长花草树木，到处是瑶、碧一类的美玉，山中的野兽大多是骆驼，而禽鸟大多是鸺鹠鸟。历虢水从这座山发源，然后向东流入黄河，水中有师鱼，人吃了它的肉就会中毒而死。再往北四百里，是座乾山，没有花草树木，山南阳面蕴藏着金属矿物和玉石，山北阴面蕴藏着铁，但没有水流。山中有一种野兽，形状像普通的牛却长着三只脚，名称是豲，它发出的叫声便是自身名称的读音。再往北五百里，是座伦山。伦水从这座山发源，然后向东流入黄河。山中有一种野兽，形状像麋鹿，肛门却长在尾巴上面，名称是罴九。再往北五百里，是座碣石山。绳水从这座山发源，然后向东流入黄河，水中有很多蒲夷鱼。这座山上出产玉石，山下还有很多青石碧玉。再往北行五百里水路，便到了雁门山，这里没有花草树木。再往北行四百里水路，便到了泰泽。在泰泽中屹立着一座山，叫做帝都山，方圆一百里，不生长花草树木，有金属矿物和玉石。再往北五百里，是座錞于毋逢山，从山上向北可以望见鸡号山，从那里吹出的风如强劲的■风。从錞于毋逢山向西可以望见幽都山，浴水从那里流出。这座幽都山中有一种大蛇，红色的脑袋白色的身子，发出的声音如同牛叫，在哪个地方出现那里就会有大旱灾。总计北方第三列山系之首尾，自太行山起到无逢山止，一共四十六座山，途经一万二千三百五十里。其中有二十座山山神的形状都是马一样的身子而人一样的面孔。祭祀这些山神：都是把用作祭品的藻和茝之类的香草埋入地下。另外十四座山山神的形状是猪一样的身子却佩戴着玉制饰品。祭祀这些山神：都用祀神的玉器，不埋入地下。还有十座山山神的形状都是猪一样的身子却长着八只脚和蛇一样的尾巴，祭祀这些山神：用一块玉壁祭祀后埋入地下。总共四十四个山神，都要用精米来祭祀。参加这项祭祀活动的人都生吃未经火烤的食物。以上是北方经历之山的记录，总共八十七座山，二万三千二百三十里。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1e45e272d4b2254f086", "shortContent": "如果说《三峡》以磅礴的气势，挥斥着七百里长峡的叠嶂奔浪，绘下了江行南国的清壮俊逸之境的话，《孟门山》则以粗犷的旋律，从惝恍迷离的荒古传说中，奏响了河下龙门的雄浑壮曲。\n本文的开笔，似乎是在尚无编年的洪荒时代。狂暴不羁的滚滚大河，正带着太古荒原的朴拙气息，从传说中的西昆仑啸腾奔来。它在受到吕梁山的阻挡后，便掉头南下，一改往日的憨厚之性，突然变得暴戾焦躁起来。它横蛮地扑过黄土高原，留下纵横数百里的沟沟...", "authors": ["张", "巍"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522503865, '5abf203117d0090061526b73', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636857, '山海经 · 海经 · 海外南经', NULL, 3, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E6%B5%B7%E5%A4%96%E5%8D%97%E7%BB%8F/19829106?fr=aladdin&fromid=19286469&fromtitle=%E6%B5%B7%E7%BB%8F%C2%B7%E6%B5%B7%E5%A4%96%E5%8D%97%E7%', '', '地之所载，六合之间，四海之内，照之以日月，经之以星辰，纪之以四时，要之以太岁，神灵所生，其物异形，或天或寿，唯圣人能通其道。
海外自西南陬至东南陬者。
结匈国在其西南，其为人结匈。
南山在其东南。自此山来，虫为蛇，蛇号为鱼。一曰南山在结匈东南。
比翼鸟在其东，其为鸟青、赤，两鸟比翼。一曰在南山东。
羽民国在其东南，其为人长，身生羽。一曰在比翼鸟东南，其为人长颊。
有神人二八，连臂，为帝司夜于此野。在羽民东。其为小人颊赤肩。尽十六人。
毕方鸟在其东，青水西，其为鸟人面一脚。一曰在二八神东。
讙头国在其南，其为人人面有翼，鸟喙，方捕鱼。一曰在毕方东。或曰讙朱国。
厌火国在其国南，兽身黑色。生火出其口中。一曰在讙朱东。
三株树在厌火北，生赤水上，其为树如柏，叶皆为珠。一曰其为树若彗。
三苗国在赤水东，其为人相随。一曰三毛国。
臷国在其东，其为人黄，能操弓射蛇。一曰臷国在三毛东。
贯匈国在其东，其为人匈有窍。一曰在臷国东。
交胫国在其东，其为大交胫。一曰在穿匈东。
不死民在其东，其为人黑色，寿，不死。一曰在穿匈国东。
歧舌国在其东。一曰在不死民东。
昆仑虚在其东，虚四方。一曰在歧舌东，为虚四方。
羿与凿齿战于寿华之野，羿射杀之。在昆仑虚东。羿持弓矢，凿齿持盾。一曰戈。
三首国在其东，其为人一身三首。
周饶国在东，其为人短小，冠带。一曰周饶国在三首东。
长臂国在其东，捕鱼水中，两手各操一鱼。一曰在周饶东，捕鱼海中。
狄山，帝尧葬于阳，帝喾葬于阴。爰有熊、罴、文虎、蜼、豹、离朱、视肉；吁咽、文王皆葬其所。一曰汤山。一曰爰有熊、罴、文虎、蜼、豹、离朱、【丘鸟】久、视肉、虖交。
其范林方三百里。
南祝融，兽身人面，乘两龙。', '《山海经·海外南经》是创作于战国时期的一篇散文，出自《山海经》，作者不详。', '', '', NULL, '', 'indent', 1522504897, '5abf24209f545400388477bb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636858, '山海经 · 海经 · 海外西经', NULL, 3, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E6%B5%B7%E5%A4%96%E8%A5%BF%E7%BB%8F/19829100?fr=aladdin', '', '海外自西南陬西北陬者。
灭蒙鸟在结匈国北，为鸟青，赤尾。
大运山高三百仞，在灭蒙鸟北。
大乐之野，夏后启于此舞九代，乘两龙，云盖三层。左手操翳，右手操环，佩玉璜。在大运山北。一曰大遗之野。
三身国在夏后启北，一首而三身。
一臂国在其北，一臂、一目、鼻孔。有黄马虎文，一目而一手。
奇肱之国在其北。其人一臂三目，有阴有阳，乘文马。有鸟焉，两头，赤黄色，在其旁。
形天与帝至此争神，帝断其首，葬之常羊之山。乃以乳为目，以脐为口，操干戚以舞。
女祭、女戚在其北，居两水间，戚操鱼䱇，祭操俎。
䳐鸟、【詹鸟】，其色青黄，所经国亡。在女祭北。䳐鸟人面。居山上。一曰维鸟，青鸟、黄鸟所巢。
丈夫国在维鸟北，其为人衣冠带剑。
女丑之尸，生而十日炙杀之。在丈夫北。以右手鄣其面。十日居之，女丑居山之山。
巫咸国在女丑北，右手操青蛇，左手操赤蛇。在登葆山，群巫所从上下也。
并封在巫咸东，其状如彘，前后皆有首，黑。
女子国在巫咸北，两女子居，水周之。一曰居一门中。
轩辕之国在此穷山之际，其不寿者八百岁。在女子国北。人面蛇身，尾交首上。
穷山在其北，不敢西射，畏轩辕之丘。在轩辕国北。其丘方，四蛇盯绕。
此诸夭之野，鸾鸟自歌，凤鸟自舞皇卵，民食之；甘露，民饮之：所欲自从也。百兽相与群居。在四蛇北。其人两手操卵食之，两鸟居前导之。
龙鱼陵居在其北，状如狸。一曰?。即有神圣乘此以行九野。一曰鳖鱼在夭野北，其为鱼也如鲤。
白民之国在龙鱼北，白身披发。有乘黄，其状如狐，其背上有角，乘之寿二千岁。
肃慎之国在白民北。有树名曰雄常，先入伐帝，于此取之。
长股之国在雄常北，披发。一曰长脚。
西方蓐收，左耳有蛇，乘两龙。 ', '《山海经·海外西经》是创作于战国时期的一篇散文，出自《山海经》，作者不详。', '', '（注：凡“■”为打不出来的字）海外从西南角到西北角的国家地区、山丘河川分别如下。灭蒙鸟在结胸国的北面，那里的鸟是青色羽毛，拖着红色尾巴。　　大运山高三百仞，屹立在灭蒙鸟的北面。大乐野，夏后启在这地方观看《九代》乐舞，乘驾着两条龙，飞腾在三重云雾之上。他左手握着一把华盖，右手拿着一只玉环，腰间佩挂着一块玉璜。大乐野就在大运山的北面。另一种说法认为夏后启观看乐舞《九代》是在大遗野。　　三身国在夏后启所在之地的北面，那里的人都长着一个脑袋三个身子。一臂国在三身国的北面，那里的人都是一条胳膊、一只眼睛、一个鼻孔。那里还有黄色的马，身上有老虎斑纹，长着一只眼睛和一条腿蹄。　　奇肱国在一臂国的北面。那里的人都是一条胳膊和三只眼睛，眼睛分为阴阳而阴在上阳在下，骑着名叫吉良的马。那里还有一种鸟，长着两个脑袋，红黄色的身子，栖息在他们的身旁。　　刑天与天帝争夺神位，天帝砍断了刑天的头，把他的头埋在常羊山。没了头的刑天便以乳头做眼睛，以肚脐做嘴巴，一手持盾牌一手操大斧而舞动。　　叫做祭的女巫、叫做薎的女巫住在刑天与天帝发生争斗之地的北面，正好处于两条水流的中间，女巫薎手里拿着兕角小酒杯，女巫祭手里捧着俎器。　　种■鸟、一种■鸟，它们的颜色是青中带黄，经过哪个国家那个国家就会败亡。■鸟和■鸟栖息在女巫祭的北面。■鸟长着人的面孔，立在山上。另一种说法认为这两种鸟统称维鸟，是青色鸟、黄色鸟聚集在一起的混称。　　丈夫国在维鸟的北面，那里的人都是穿衣戴帽而佩带宝剑的模样。有一具女丑的尸体，她生前是被十个太阳的热气烤死的。她横卧在丈夫国的北面。死时用右手遮住她的脸。十个太阳高高挂在天上，女丑的尸体横卧在山顶上。　　巫咸国在女丑的北面，那里的人是右手握着一条青蛇，左手握着一条红蛇。有座登葆山，是一群巫师来往于天上与人间的地方。称作并封的怪兽在巫咸国的东面，它的形状像普通的猪，却前后都有头，是黑色的。　　女子国在巫咸国的北面，有两个女子住在这里，四周有水环绕着。另一种说法认为她们住在一道门的中间。　　轩辕国在穷山的旁边，那里的人就是不长寿的也能活八百岁。轩辕国在女子国的北面，他们长着人的面孔却是蛇的身子，尾巴盘绕在头顶上。　　穷山在轩辕国的北面，那里的人拉弓射箭不敢向着西方射，是因为敬畏黄帝威灵所在的轩辕丘。轩辕丘位于轩辕国北部，这个轩辕丘呈方形，被四条大蛇相互围绕着。有个叫做沃野的地方，鸾鸟自由自在地歌唱，凤鸟自由自在地舞蹈；凤皇生下的蛋，那里的居民食用它；苍天降下的甘露，那里的居民饮用它：凡是他们所想要的都能随心如意。那里的各种野兽与人一起居住。沃野在四条蛇的北面，那里的人用双手捧着凤皇蛋正在吃，有两只鸟在前面引导着。　　既可在水中居住又可在山陵居住的龙鱼在沃野的北面，龙鱼的形状像一般的鲤鱼。另一种说法认为像鰕鱼。就有神圣的人骑着它遨游在广大的原野上。还有一种说法认为鳖鱼在沃野的北面，这种鱼的形状也与鲤鱼相似。　　白民国在龙鱼所在地的北面，那里的人都是白皮肤而披散着头发。有一种叫做乘黄的野兽，形状像一般的狐狸，脊背上有角，人要是骑上它就能活两千年的长寿。　　肃慎国在白民国的北面。有一种树木叫做雄常树，每当中原地区有圣明的天子继位，那里的人就取雄常树的树皮来做衣服。　　西方的蓐收神，左耳上有一条蛇，乘驾两条龙飞行。', NULL, '', 'indent', 1522505048, '5abf24d14773f7005d425487', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636859, '山海经 · 海经 · 海外北经', NULL, 2, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E6%B5%B7%E5%A4%96%E5%8C%97%E7%BB%8F/19829096?fr=aladdin', '', '海外自东北陬至西北陬者。
无䏿之国在长股东，为人无䏿。
钟山之神，名曰烛阴，视为昼，瞑为夜，吹为冬，呼为夏，不饮，不食，不息，息为风。身长千里。在无䏿之东。其为物，人面，蛇身，赤色，居钟山下。
一目国在其东，一目中其面而居。一曰有手足。
柔利国在一目东，为人一手一足，反䣛，曲足居上。一云留利之国，人足反折。
共工之臣曰相柳氏，九首，以食于九山。相柳之所抵，厥为泽溪。禹相柳，其血腥，不可以树五谷种。禹厥之，三仞三沮，乃以为众帝之台。在昆仑之北，柔利之东。相柳者，九首人面，蛇身面青。不敢北射，畏共工之台。台在其东。台四方，隅有一蛇，虎色，首冲南方。
深目国在其东，为人举一手一目。
无肠之国在深目东，其为人长而无肠。聂耳之国在无肠国东，使两文虎，为人两手聂其耳。县居海水中，及水所出入奇物。两虎在其东。
夸父与日逐走，入日。渴欲得饮，饮于河渭，河渭不足，北饮大泽。未至，道渴而死。弃其杖。化为邓林。
博父国在聂耳东，其为人大，右手操青蛇，左手操黄蛇。邓林在其东，二树木。一曰博父。
禹所积石之山在其东，河水所入。
拘缨之国在其东，一手把缨。一曰利缨之国。
寻木长千里，在拘缨南，生河上西北。
跂踵国在拘缨东，其为人大，两足亦大。一曰大踵。
欧丝之野大踵东，一女子跪据树欧丝。
三桑无枝，在欧丝东，其木长百仞，无枝。
范林方三百里，在三桑东，洲环其下。
务隅之山，帝颛顼葬于阳，九嫔葬于阴。一曰爰有熊、罴、文虎、离朱、【丘鸟】久、视肉。
平丘在三桑东。爰有遗玉、青鸟、视肉、杨柳、甘柤、甘华，百果所生。有两山夹上谷，二大丘居中，名曰平丘。
北海内有兽，其状如马，名曰騊駼。有兽焉，其名曰驳，状如白马，锯牙，食虎豹。有素兽焉，状如马，名曰蛩蛩。有青兽焉，状如虎，我曰罗罗。
北方禺强，人面鸟身，珥两青蛇。践两青蛇。 ', '《山海经·海外北经》是创作于战国时期的一篇散文，出自《山海经》，作者不详。', '', '海外从西北角到东北角的国家地区、山丘河川分别如下。无启国在长股国的东面，那里的人不生育子孙后代。钟山的山神，名叫烛阴，他睁开眼睛便是白昼，闭上眼睛便是黑夜，一吹气便是寒冬，一呼气便是炎夏，不喝水，不吃食物，不呼吸，一呼吸就生成风，身子有一千里长。这位烛阴神在无启国的东面。他的形貌是人一样的面孔，蛇一样的身子，全身赤红色，住在钟山脚下。一目国在钟山的东面，那里的人是在脸的中间长着一只眼睛。另一种说法认为像普通的人有手有脚。柔利国在一目国的东面，那里的人是一只手一只脚，膝盖反长着，脚弯曲朝上。另一种说法认为柔利国叫做留利国，人的脚是反折着的。天神共工的臣子叫相柳氏，有九个头，九个头分别在九座山上吃食物。相柳氏所触动之处，便掘成沼泽和溪流。大禹杀死了相柳氏，血流过的地方发出腥臭味，不能种植五谷。大禹挖填这地方，多次填满而多次蹋陷下去，于是大禹便把挖掘出来的泥土为众帝修造了帝台。
这帝台在昆仑山的北面，柔利国的东面。这个相柳氏，长着九个脑袋和人的面孔，蛇的身子而是青色。射箭的人不敢向北方射，因为敬畏共工威灵所在的共工台。共工台在相柳的东面，台是四方形的，每个角上有一条蛇，身上的斑纹与老虎相似，头向着南方。深目国在相柳氏所在地的东面，那里的人总是举起一只手。另一种说法认为深目国在共工台的东面。无肠国在深目国的东面，那里的人身体高大而肚子里却没有肠子。聂耳国在无肠国的东面，那里的人使唤着两只花斑大虎，并且在行走时用手托着自己的大耳朵。
聂耳国在海水环绕的孤岛上，所以能看到出入海水的各种怪物。有两只老虎在它的东面。神人夸父要与太阳赛跑而追赶它，已追上了太阳。这时夸父很渴，想要喝水，于是喝黄河和渭河中的水，喝完了两条河水还是不解渴，又要向北去喝大泽中的水，还没走到，就渴死在半路上了。他死时所抛掉的拐杖，变成了邓林。夸父国在聂耳国的东面，那里的人身体高大，右手握着青色蛇，左手握着黄色蛇。邓林在它的东面，其实由两棵非常大的树木形成了树林。另一种说法认为夸父国叫博父国。禹所积石山在博父国的东面，是黄河流入的地方。
拘瘿国在禹所积石山的东面，那里的人常用一只手托着脖颈上的大肉瘤。另一种说法认为拘瘿国叫做利瘿国。有种叫做寻木的树有一千里长，在拘瘿国的南面，生长在黄河岸上的西北方。跂踵国在拘瘿国的东面，那里的人都是身材高大，两只脚也非常大。另一种说法认为跂踵国叫反踵国。
欧丝野在反踵国的东面，有一女子跪倚着桑树在吐丝。三棵没有枝干的桑树，在欧丝野的东面，这种树虽高达一百仞，却不生长树枝。范林方圆三百里，在三棵桑树的东面，它的下面被沙洲环绕着。务隅山，帝颛顼埋葬在它的南面，九嫔埋葬在它的北面。另一种说法认为这里有熊、罴、花斑虎、离朱鸟、鹞鹰、视肉怪兽。平丘在三棵桑树的东面。这里有遗玉、青马、视肉怪兽、杨柳树、甘柤树、甘华树，是各种果树生长的地方。在两座山相夹的一道山谷上，有两个大丘处于其间，叫做平丘。
北海内有一种野兽，形状像一般的马，名称是騊駼。又有一种野兽，名称是驳，形状像白色的马，长着锯齿般的牙，能吃老虎和豹子。又有一种白色的野兽，形状像马，名称是蛩蛩。还有一种青色的野兽，形状像老虎，名称是罗罗。北方的禺疆神，长着人的面孔而鸟的身子，耳朵上穿挂着两条青蛇，脚底下践踏着两条青蛇。', NULL, '', 'indent', 1522505210, '5abf25772f301e0065eefbe5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636860, '山海经 · 海经 · 海外东经', NULL, 2, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E6%B5%B7%E5%A4%96%E4%B8%9C%E7%BB%8F/19831179?fr=aladdin', '', '海外自东南陬至东北陬者。
【长差】丘，爰有遗玉、青马、视肉、杨柳、甘华。甘果所生，在东海。两山夹丘，上有树木。一曰嗟丘。一曰百果所在，在尧葬东。
大人国在其北，为人大，坐而削船。一曰在【长差】丘北。
奢比尸国在其北，兽身、人面、大耳，珥两青蛇。一曰肝榆之尸在大人北。
君子国在其北，衣冠带剑，食兽，使二大虎在旁，其人好让不争。有薰华草，朝生夕死。一曰在肝榆之尸北
【上工下虫】在其北，各有两首。一曰在君子国北。朝阳之谷，神曰天吴，是为水伯。在【上工下虫】北两水间。其为兽也，八首人面，八足八尾，皆青黄。
青丘国在其北，其狐四足九尾。一曰在朝阳北。
帝命竖亥步，自东极至于西极，五亿十选九千八百步。竖亥右手把算，左手指青丘北。一曰禹令竖亥。一曰五亿十万九千八百步。
黑齿国在其北，为人黑，食稻啖蛇，一赤一青，在其旁。一曰在竖亥北，为人黑首，食稻使蛇，其一蛇赤。
下有汤谷。汤谷上有扶桑，十日所浴，在黑齿北。居水中，有大木，九日居下枝，一日居上枝。
雨师妾在其北。其为人黑，两手各操一蛇，左耳有青蛇，右耳有赤蛇。一曰在十日北，为人黑身人面，各操一龟。
玄股之国在其北。其为人衣鱼食，使两鸟夹之。一曰在雨师妾北。
毛民之国在其北，为人身生毛。一曰在玄股北。
劳民国在其北，其为人黑。或曰教民。一曰在毛民北，为人面目手足尽黑。
东方句芒，鸟身人面，乘两龙。
建平元年四月丙戊，待诏太常属臣望校治，侍中光禄勋臣龚，侍中奉车都尉光禄大夫臣秀领主省。 ', '《山海经·海外东经》是创作于战国时期的一篇散文，出自《山海经》，作者不详。', '', '（注释：凡■ 为打不出来的字）
海外从东南角到东北角的国家地区、山丘河川分别如下。 丘，这里有遗玉、青马、视肉怪兽、杨柳树、甘柤树、甘华树。结出甜美果子的树所生长的地方，就在东海边。两座山夹着？丘，上面 有树木。另一种说法认为？丘就是嗟丘。还有一种说法认为各种果树所存在 的地方，在葬埋帝尧之地的东面。
大人国在它的北面，那里的人身材高大，正坐在船上撑船。一 种说法认为大人国在？丘的北面。奢比尸神在大人国的北面，那里的人都长着野兽的身子、人的 面孔、大大的耳朵，耳朵上穿挂着两条青蛇。另一种说法认为肝榆尸神在大 人国的北面。
君子国在奢比尸神的北面，那里的人穿衣戴帽而腰间佩带着 剑，能吃野兽，使唤的两只花斑老虎就在身旁，为人喜欢谦让而不争斗。那 里有一种薰华草，早晨开花傍晚凋谢。另一种说法认为君子国在肝榆尸神的北面。
虹霓，俗称美人虹。据古人说，虹双出而颜色鲜艳的为雄，称作虹在它的北面，它的各端都有两个脑袋。另一种说法认为■ ■在君子国的北面。
朝阳谷，有一个神人叫做天吴，就是所谓的水伯。他住在■■ 北面的两条水流中间。他是野兽形状，长着八个脑袋而是人的脸面，八只爪 子八条尾巴，背部是青中带黄的颜色。
青丘国在它的北面。那里有一种狐狸长着四只爪子九条尾巴。另一种说法认为青丘国在朝阳谷的北面。
天帝命令竖亥用脚步测量大地，从最东端走到最西端，是五亿 十选九千八百步。竖亥右手拿着算筹，左手指着青丘国的北面。另一种说法 认为是大禹命令竖亥测量大地。还一种说法认为测量出五亿十万九千八百步。
黑齿国在它的北面，那里的人牙齿漆黑，吃着稻米又吃着蛇，还有一条红蛇和一条青蛇，正围在他身旁。另一种说法认为黑齿国在竖亥所 在地的北面，那里的人是黑脑袋，吃着稻米驱使着蛇，其中一条蛇是红色的。 下面有汤谷。汤谷边上有一棵扶桑树，是十个太阳洗澡的地方，在黑齿国的北面。正当大水中间，有一棵高大的树木，九个太阳停在树的下 枝，一个太阳停在树的上枝。
雨师妾国在汤谷的北面。那里的人全身黑色，两只手各握着一 条蛇，左边耳朵上挂有青色蛇，右边耳朵挂有红色蛇。另一种说法认为雨师 妾国在十个太阳所在地的北面，那里的人是黑色身子而人的面孔，两只手各 握着一只龟。 玄股国在它的北面。那里的人穿着鱼皮衣而吃鸥鸟蛋，使唤的两只鸟在身边。另一种说法认为玄股国在雨师妾国的北面。 毛民国在它的北面。那里的人全身长满了毛。另一种说法认为毛民国在玄股国的北面。
劳民国在它的北面，那里的人全身黑色。有的人称劳民国为教民国。另一种说法认为劳民国在毛民国的北面，那里的人脸面眼睛手脚全是黑的。
东方的句芒神，是鸟的身子人的面孔，乘着两条龙。', NULL, '', 'indent', 1522505347, '5abf25ff9f545433515b2684', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636869, '山海经 · 海经 · 海内经 ', NULL, 3, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E6%B5%B7%E5%86%85%E7%BB%8F/19831171?fr=aladdin', '', '东海之内，北海之隅，有国名曰朝鲜；天毒，其人水居，偎人爱之。
西海之内，流沙之中，有国名曰壑市。
西海之内，流沙之西，有国名曰氾叶。
流沙之西，有鸟山者，三水出焉。爰有黄金、璿瑰、丹货、银铁，皆流于此中。又有淮山，好水出焉。
流沙之东，黑水之西，有朝云之国、司彘之国。黄帝妻嫘祖，生昌意。昌意降处若水，生韩流。韩流擢首、谨耳、人面、豕喙、麟身、渠股、豚止，取淖子曰阿女，生帝颛顼。
流沙之东，黑水之间，有山名曰有死之山。
华山青水之东，有山名曰肇山。有人名曰柏高，柏高上下于此，至于天。
西南黑水之间，有都广之野，后稷葬焉。爰有膏菽、膏稻、膏黍、膏稷，百谷自生，冬夏播琴。鸾鸟自歌，凤鸟自舞，灵寿实华，草木所聚。爰有百兽，相群爰处。此草也，冬夏不死。
南海之外，黑水青水之间，有木名曰若木，若水出焉。
有禺中之国。有列襄之国。有灵山，有赤蛇在木上，名曰蠕蛇，木食。
有盐长之国。有人焉鸟首，名曰鸟氏。
有九丘，以水络之：名曰陶唐之丘、有叔得之丘、孟盈之丘、昆吾之丘、黑白之丘、赤望之丘、参卫之丘、武夫之丘、神民之丘。有木，青叶紫茎，玄华黄实，百仞无枝，有九欘，下有九枸，其实如麻，其叶如芒。大皞爰过，黄帝所为。
有窫窳，龙首，是食人。有青兽，人面，名是曰猩猩。
西南有巴国。大皞生咸鸟，咸鸟生乘厘，乘厘生后照，后照是始为巴人。
有国名曰流黄辛氏，其域中方三百里，其出是尘土。有巴遂山，渑水出焉。
又有朱卷之国。有黑蛇，青首，食象。
南方有赣巨人，人面长臂，黑身有毛，反踵，见人笑亦笑，唇蔽其面，因即逃也。
又有黑人，虎首鸟足，两手持蛇，方啖之。
有嬴民，鸟足，有封豕。
有人曰苗民。有神焉，人首蛇身，长如辕，左右有首，衣紫衣，冠旃冠，名曰延维，人主得而飨食之，伯天下。
有鸾鸟自歌，凤鸟自舞。凤鸟首文曰“德”，翼文曰“顺”，膺文曰“仁”，背文曰“义”，见则天下和。
又有青兽如菟，名曰菌狗，有桂山。有翠鸟。有孔鸟。
南海之内，有衡山，有菌山，有桂山。有山名三天子之都。
南方苍梧之丘，苍梧之渊，其中有九嶷山，舜之所葬，在长沙零陵界中。
北海之内，有蛇山者，蛇水出焉，东入于海。有五采之鸟，飞蔽一乡，名曰翳鸟。又有不距之山，巧倕葬其西。
北海之内，有反缚盗械、带戈常倍之佐，各曰相顾之尸。
伯夷父生西岳，西岳生先龙，先龙是始生氐羌，氐羌乞姓。
北海之内，有山，名曰幽都之山，黑水出焉。其上有玄鸟、玄蛇、玄狐蓬尾。有大玄之山。有玄丘之民。有大幽之国。有赤胫之民。
有钉灵之国，其民从厀以下有毛，马蹄善走。
炎帝之孙伯陵，伯陵同吴权之妻阿女缘妇，缘妇孕三年，是生鼓、延、殳。始为侯，鼓、延是始为钟，为乐风。
黄帝生骆明，骆明生白马，白马是为鲧。
帝俊生禺号，禺号生淫梁，淫梁生番禺，是始为舟。番禺生奚仲，奚仲生吉光，吉光是始以木为车。
少皞生般，般是始为弓矢。
帝俊赐羿彤弓素矰，以扶下国，羿是始去恤下地之百艰。
帝俊生晏龙，晏龙是为琴瑟。
帝俊有子八人，是为歌舞。
帝俊生三身，三身生义均，义均是始为巧倕，是始作下民百巧。后稷是播百谷。稷之孙曰叔均，是始作牛耕。大比赤阴，是始为国。禹、鲧是始布土，均定九州。
炎帝之妻，赤水之子听訞生炎居，炎居生节并，节并生戏器，戏器生祝融。祝融降处于江水，生共工。共工生术器，术器首方颠，是复土穰，以处江水。共工生后土，后土生噎鸣，噎鸣生岁十有二。
洪水滔天。鲧窃帝之息壤以堙洪水，不待帝命。帝命祝融杀鲧于羽郊。鲧复生禹。帝乃命禹卒布土，以定九州。', '《山海经·海内经》是创作于战国时期的一篇散文，出自《山海经》，作者不详。', '朝鲜：就是现在朝鲜半岛上的朝鲜和韩国。
天毒：据古人解说，即天竺国，有文字，有商业，佛教起源于此国中。而天竺国就是现在的印度。但印度在南，朝鲜在北，一南一北，相距很远，记在一处，不合情理，则文字上似有讹误或脱遗。
丹货：不详何物。
流：淌出。这里是出产、产生的意思。
嫘祖：相传是教人们养蚕的始祖。
擢：引拔，耸起。这里指物体因吊拉变成长竖形的样子。
谨：慎重小心，谨慎细心。这里是细小的意思。
渠股：即今天所说的罗圈腿。
取：通「娶」。
膏：这里是味道美好而光滑如膏的意思。
菽：豆类植物的总称。
稷：谷子。
播琴：即播种。这是古时楚地人的方言。
灵寿：即上文所说的椐树，所生枝节像竹节，粗细长短都正好合于拐杖，不必人工制做，所以古代老人常利用这种天然拐杖。也有一种说法，认为灵寿是一种生长在昆仑山及其附近地方的特殊树木，人吃了它结的果实就会长生不死，所以叫灵寿树。
仞：古时以八尺为一仞。
欘：树枝弯曲。
枸：树根盘错。
大皞：又叫太昊、太皓，即伏羲氏，古史传说中的上古帝王，姓风。他开始画八卦，教人们捕鱼放牧，用来充作食物。又是神话传说中的人类始祖。
衣紫衣：前一个「衣」是动词，穿的意思。后一个「衣」是名词，即衣服。冠旃冠：前一个「冠」是动词，戴的意思。后一个「冠」是名词，即帽子。旃：纯红色的曲柄旗。这里仅是红色的意思，与上一句的紫色相对。延维：即上文所说的委蛇，就是双头蛇。
人主：君主，一国之主。
飨：祭献。
伯：通「霸」。
菟：通「兔」。
翠鸟：即翡翠鸟，形状像燕子。古人说雄性的叫翡，羽毛是红色；雌性的叫翠，羽毛是青色。实际上，翡翠鸟的羽毛有好多种颜色，不止红、青二色，所以自古以来就做装饰品用。孔鸟：即孔雀鸟。
翳鸟：传说是凤凰之类的鸟。
巧倕：相传是上古帝尧时代一位灵巧的工匠。
盗械：古时，凡因犯罪而被戴上刑具就称作盗械。
戈：古代一种兵器。
倍：通「背」。背弃。
佐：辅助帝王的人。
相顾之尸：也是上文所说贰负之臣一类的人。
伯夷父：相传是帝颛顼（zhuānxū）的师傅。
厀：同「膝」。
走：跑。
炎帝：即神农氏，传说中的上古帝王。
同：通「通」。通奸。
吴权：传说中的人物。
侯：练习或比赛射箭时用的箭靶。
鲧：相传是大禹的父亲。
帝俊：这里指黄帝。
淫梁：即上文所说的禺京。
少皞：即上文所说的少昊号称金天氏，传说中的上古帝王。
彤：朱红色。
矰：一种用白色羽毛装饰并系着丝绳的箭。恤：体恤，周济。
帝俊：这里指帝舜。
帝俊：这里也是指帝舜。
义均：就是上文所说的叔均，但说是帝舜的儿子，这里却说是帝舜的孙子，属于神话传说的不同。
叔均：上文曾说叔均是后稷之弟台玺的儿子，这里又说是后稷的孙子，而且和前面说的义均也分成了二人，神话传说分歧，往往有所不同。大比赤阴：意义不明。也有学者认为可能是后稷的生母姜嫄。「比」大概为「妣」的讹文。
妣：母亲。「赤阴」的读音与「姜嫄」相近。据古史传说，后稷被封于邰地而建国，姜嫄即居住在这里，所以下面说「是始为国」。
布土：传说鲧与大禹父子二人相继治理洪水，鲧使用堵塞的方法，大禹使用疏通的方法，都需要挖掘泥土。布即施予，施行。土即土工，治河时填土、挖土工程。
均：平均，均匀。引申为度量、衡量。
九州：相传大禹治理了洪水以后，把中原划分为九个行政区域，就是九州。
颠：头顶。
滔：漫。
息壤：神话传说中的一种能够自生自长、永不耗损的土壤。复生：相传鲧死了三年而尸体不腐烂，用刀剖开肚腹，就产生了禹。「复」即「腹」的同声假借字。', '在东海以内，北海的一个角落，有个国家名叫朝鲜。还有一个国家叫天毒，天毒国的人傍水而居，怜悯慈人。
在西海以内，流沙的中央，有个国家名叫壑市国。
在西海以内，流沙的西边，有个国家名叫氾（fàn）叶国。
流沙西面，有座山叫鸟山，三条河流共同发源于这座山。这里所有的黄金、璿玉瑰石、丹货、银铁，全都产于这些水中。又有座大山叫淮山，好水就是从这座山发源的。
在流沙的东面，黑水的西岸，有朝云国、司彘国。黄帝的妻子雷祖生下昌意。昌意自天上降到若水居住，生下韩流。韩流长着长长的脑袋、小小的耳、人的面孔、猪的长嘴、麒麟的身子、罗圈着双腿、小猪的蹄子，娶淖子族人中叫阿女的为妻，生下帝颛顼。
在流沙的东面，黑水流经的地方，有座山名叫不死山。
在华山青水的东面，有座山名叫肇山。有个仙人名叫柏子高，柏子高由这里上去下来的，直至到达天上。
在西南方黑水流经的地方，有一处叫都广野，后稷就埋葬在这里。这里出产膏菽、膏稻、膏黍、膏稷，各种谷物自然成长，冬夏都能播种。鸾鸟自由自在地歌唱，凤鸟自由自在地舞蹈，灵寿树开花结果，丛草树林茂盛。这里还有各种禽鸟野兽，群居相处。在这个地方生长的草，无论寒冬炎夏都不会枯死。
在南海以内，黑水青水流经的地方，有一种树木名叫若木，而若水就从若木生长的地底下发源。
有个盐长国。这里的人长着鸟一样的脑袋，称作鸟民。
有九座山丘，都被水环绕着，名称分别是陶唐丘、叔得丘、孟盈丘、昆吾丘、黑白丘、赤望丘、参卫丘、武夫丘、神民丘。有一种树木，青色的叶子紫色的茎干，黑色的花朵黄色的果实，叫做建木，高达一百仞的树干上不生长枝条，而树顶上有九根弯蜒曲折的桠枝，树底下有九条盘旋交错的根节，它的果实像麻子，叶子像芒树叶。大皞凭借建木登上天，黄帝栽培了建木。
有一种窫窳（yàyǔ）兽，长着龙一样的脑袋，能吃人。还有一种野兽，长着人一样的面孔，名叫猩猩。
西南方有个巴国。大皞（hào）生了咸鸟，咸鸟生了乘厘，乘厘生了后照，而后照就是巴国人的始祖。
有个国家名叫流黄辛氏国，它的疆域方圆三百里，这里出产一种大鹿。还有一座巴遂山，渑水从这座山发源。
又有个朱卷国。这里有一种黑颜色的大蛇，长着青色脑袋，能吞食大象。
南方有一种赣巨人，长着人的面孔而嘴唇长长的，黑黑的身上长满了毛，脚尖朝后而脚跟朝前反长着，看见人就发笑，一发笑而嘴唇便会遮住他的脸面，人就趁此立即逃走。
还有一种黑人，长着老虎一样的脑袋禽鸟一样的爪子，两只手握着蛇，正在吞食它。
有一种人称作苗民。这地方有一个神，长着人的脑袋蛇的身子，身躯长长的像车辕，左边右边各长着一个脑袋，穿着紫色衣服，戴着红色帽子，名叫延维，人主得到它后加以奉飨祭祀，便可以称霸天下。
有鸾鸟自由自在地歌唱，有凤鸟自由自在地舞蹈。凤鸟头上的花纹是「德」字，翅膀上的花纹是「顺」字，胸脯上的花纹是「仁」字，脊背上的花纹是「义」字，它一出现就会使天下和平。
又有一种像兔子的青色野兽，名叫【上山下囷】狗。又有翡翠鸟。还有孔雀鸟。
在南海以内，有座衡山，又有座菌山，还有座桂山。还有座山叫做三天子都山。
南方有一片山丘叫苍梧丘，还有一个深渊叫苍梧渊，在苍梧丘和苍梧渊的中间有座九嶷山，帝舜就葬埋在这里。九嶷山位于长沙零陵境内。
在北海以内，有座山叫蛇山，蛇水从蛇山发源，向东流入大海。有一种长着五彩羽毛的鸟，成群地飞起而遮蔽一乡的上空，名叫翳鸟。还有座不距山，巧倕便葬在不距山的西面。
在北海以内，有一个反绑着戴刑具、带着戈而图谋叛逆的臣子，名叫相顾尸。
伯夷父生了西岳，西岳生了先龙，先龙的后代子孙便是氐羌，氐羌人姓乞。
北海以内，有一座山，名叫幽都山，黑水从这座山发源。山上有黑色鸟、黑色蛇、黑色豹子、黑色老虎，有毛蓬蓬尾巴的黑色狐狸。有座大玄山。有一种玄丘民。有个大幽国。有一种赤胫民。
有个钉灵国，这里的人从膝盖以下的腿部都有毛，长着马的蹄子而善于快跑。
炎帝的孙子叫伯陵，伯陵与吴权的妻子阿女缘妇私通，阿女缘妇怀孕三年，这才生下鼓、延、殳三个儿子。殳最初发明了箭靶，鼓、延二人发明了钟，作了乐曲和音律。
黄帝生了骆明，骆明生了白马，这白马就是鲧。
帝俊生了禺号，禺号生了淫梁，淫梁生了番禺，这位番禺最初发明了船。番禺生了奚仲，奚仲生了吉光，这位吉光最初用木头制做出车子。
少皞生了般，这位般最初发明了弓和箭。
帝俊赏赐给后羿红色弓和白色矰箭，用他的射箭技艺去扶助下界各国，后羿便开始去救济世间人们的各种艰苦。
帝俊生了晏龙，这位晏龙最初发明了琴和瑟两种乐器。
帝俊有八个儿子，他们开始创作出歌曲和舞蹈。
帝俊生了三身，三身生了义均，这位义均便是所谓的巧倕，从此开始发明了世间的各种工艺技巧。后稷开始播种各种农作物。后稷的孙子叫叔均，这位叔均最初发明了使用牛耕田。大比赤阴，开始受封而建国。大禹和鲧开始挖掘泥土治理洪水，度量划定九州。
炎帝的妻子，即赤水氏的女儿听訞生下炎居，炎居生了节并，节并生了戏器，戏器生了祝融。祝融降临到江水居住，便生了共工。共工生了术器。术器的头是平顶方形，他恢复了祖父祝融的土地，从而又住在江水。共工生了后土，后土生了噎鸣，噎鸣生了一年中的十二个月。
洪荒时代到处是漫天大水。鲧偷拿天帝的息壤用来堵塞洪水，而未等待天帝下令。天帝派遣祝融把鲧杀死在羽山的郊野。禹从鲧的遗体肚腹中生出。天帝就命令禹最后再施行土工制住了洪水，从而能划定九州区域。', NULL, '', 'indent', 1522506317, '5abf29c8ac502e0063a853f7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642077, '幽梦影 · 卷一 · 四十六', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '当为花中之萱草，毋为鸟中之杜鹃。', '', '', '', NULL, '', 'indent', 1556016705, '5cbe7dbff884af0065c054bc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636861, '山海经 · 海经 · 海内南经', NULL, 5, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E6%B5%B7%E5%86%85%E5%8D%97%E7%BB%8F/19829098?fr=aladdin', '', '海内东南陬以西者。
瓯居海中。闽在海中，其西北有山。一曰闽中山在海中。
三天子鄣山在闽西海北。一曰在海中。
桂林八树在番隅东。
伯虑国、离耳国、雕题国、北朐国皆在郁水南。郁水出湘陵南海。一曰相虑。
枭阳国在北朐之西。其为人人面长唇，黑身有毛，反踵，见人笑亦笑手操管。
兕在舜葬东，湘水南。其状如牛，苍黑，一角。
苍梧之山，帝舜葬于阳，帝丹朱葬于阴。
泛林方三百里，在东。
兕兕知人名，其为兽如豕而人面，在舜葬西。
兕兕西北有犀牛，其状如牛而黑。
夏后启之臣曰孟涂，是司神于巴。人请讼于孟涂之所，其衣有血者乃执之。是请生，在丹山西。丹山在丹阳南，丹阳居属也。
窫窳龙首，居弱水中，在兕兕知人名之西，其状如龙首，食人。
有木，其状如牛，引之有皮，若缨、黄蛇。其叶如罗，其实如栾，其木若蓲，其名曰建木。在窳西弱水上。
氐人国在建木西，其为人人面而鱼身，无足。
巴蛇食象，三岁而出其骨，君子服之，无心腹之疾。其为蛇青赤黑。一曰黑蛇青首，在犀牛西。
旄马，其状如马，四节有毛。在巴蛇西北，高山南。
匈奴、开题之国。列人之国并在西北。', '《山海经·海内南经》是创作于战国时期的一篇散文，出自《山海经》，作者不详。', '', '海内由东南角向西的国家地区、山丘河川依次如下。瓯在海中。闽在海中，它的西北方有座山。另一种说法认为闽地的山在海中。三天子鄣山在闽的西北方。另一种说法认为三天子鄣山在海中。桂林的八棵树很大而形成树林，处在番隅的东面。伯虑国、离耳国、雕题国、北朐国都在郁水的南岸。郁水发源于湘陵南山。另一种说法认为伯虑国叫做柏虑国。　　枭阳国在北朐国的西面。那里的人是人的面孔而长长的嘴唇，黑黑的身子有长毛，脚跟在前而脚尖在后，一看见人就张口大笑；左手握着一根竹筒。兕在帝舜葬地的东面，在湘水的南岸。兕的形状像一般的牛，通身是青黑色，长着一只角。苍梧山，帝舜葬在这座山的南面，帝丹朱葬在这座山的北面。氾林方圆三百里，在猩猩生活之地的东面。猩猩能知道人的姓名，这种野兽的形状像一般的猪却长着人的面孔，生活在帝舜葬地的西面。猩猩的西北面有犀牛，它的形状像一般的牛而全身是黑色。夏朝国王启的臣子叫孟涂，是主管巴　　地诉讼的神。巴地的人到孟涂那里去告状，而告状人中有谁的衣服沾上血迹的就被孟涂拘禁起来。这样就不出现冤枉而有好生之德。孟涂住在一座山上，这座山在丹山的西面。丹山在丹阳的南面，而丹阳是巴的属地。窫窳长着龙一样的头，住在弱水中，处在能知道人姓名的猩猩的西面，它的形状像貙，长着龙头，能吃人的。有一种树木，形状像牛，一拉就剥落下树皮，样子像冠帽上缨带、黄色蛇皮。它的叶子像罗网，果实像栾树结的果实，树干像刺榆，名称是建木。这种建木生长在窫窳所在地之西的弱水边上。氐人国在建木所在地的西面，那里的人都长着人的面孔却是鱼的身子，没有脚。巴蛇能吞下大象，吞吃后三年才吐出大象的骨头，有才能德品的人吃了巴蛇的肉，就不患心痛或肚子痛之类的病。　　这种巴蛇的颜色是青色、黄色、红色、黑色混合间杂的。另一种说法认为巴蛇是黑色身子青色脑袋，在犀牛所在地的西面。旄马，形状像普通的马，但四条腿的关节上都有长毛。　　旄马在巴蛇所在地的西北面，一座高山的南面。匈奴国、开题国、列人国都在西北方。', NULL, '', 'indent', 1522505431, '5abf26539f54540038848769', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636862, '山海经 · 海经 · 海内西经', NULL, 2, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E6%B5%B7%E5%86%85%E8%A5%BF%E7%BB%8F/19829094?fr=aladdin', '', '海内西南陬以北者。
贰负之臣曰危，危与贰负窫窳。帝乃梏之疏属之山，桎其右足，反缚两手与发，系之山上木。在开题西北。
大泽方百里，群鸟所生及所解。在雁门北。
雁门山，雁出其间。在氐国西。
高柳在代北。
后稷之葬，山水环之。在氐国西。
流黄酆氏之国，中方三百里；有涂四方，中有山。在后稷葬西。
流沙出钟山，西行又南行昆仑之虚，西南入海，黑水之山。
东胡在大泽东。
夷人在东胡东。
貊国在汉水东北。地近于燕，灭之。
孟鸟在貊国东北。其鸟文赤、黄、青，东乡。
海内昆仑之虚，在西北，帝之下都。
昆仑之虚，方圆八百里，高万仞。上有木禾，长五寻，大五围。
面有九井，以玉为槛。面有九门，门有开明兽守之，百神之所在。
在八隅之岩，赤水之际，非仁羿莫能上冈之岩。
赤水出东南隅，以行其东北。
河水出东北隅，以行其北，西南又入渤海，又出海外，即西而北，入禹所导积石山。
洋水、黑水出西北隅，以东，东行，又东北，南入海，羽民南。
弱水、青水出西南隅，以东，又北，又西南，过毕方鸟东。
昆仑南渊深三百仞。开明兽身大类虎而九首，皆人面，东向立昆仑上。
开明西有凤皇、鸾鸟，皆戴蛇践蛇，膺有赤蛇。
开明北有视肉、珠树、文玉树、玗琪树、不死树。凤皇、鸾鸟皆戴瞂。又有离朱、木禾、柏树、甘水、圣木曼兑，一曰挺木牙交。
开明东有巫彭、巫抵、巫阳、巫履、巫凡、巫相，夹窫窳之尸，皆操不死之药以距之。窫窳者，蛇身人面，贰负臣所杀也。
服常树，其上有三头人，伺琅玕树。
开明南有树鸟，六首；蛟、蝮、蛇、蜼、豹、鸟秩树，于表池树木，诵鸟、鶽、视肉。', '《山海经·海内西经》是创作于战国时期的一篇散文，出自《山海经》，作者不详。', '', '翻译：
　　海内由西南角向北的国家地区、山丘河川依次如下。
贰负之臣曰危①，危与贰负杀窫窳②。帝乃梏之疏属之山③，桎其右足④，反缚两手与发，系之山上木。在开题西北。
　　注解：
　　①贰负：神话传说中的天神，样子是人的脸面蛇的身子。
　　②窫窳：也是传说中的天神，原来的样子是人的脸面蛇的身子，后被贰负及其臣子杀死而化成上文所说的样子——龙头，野猫身，并且吃人。
　　③梏：古代木制的手铐。这里是械系、拘禁的意思。
　　④桎：古代拘系罪人两脚的刑具。
　　翻译：
　　贰负神的臣子叫危，危与贰负合伙杀死了窫窳神。天帝便把贰负拘禁在疏属山中，并给他的右脚戴上刑具，还用他自己的头发反绑上他的双手，拴在山上的大树下。这个地方在开题国的西北面。
大泽方百里，群鸟所生及所解。在雁门北。
　　翻译：
　　大泽方圆一百里，是各种禽鸟生卵孵化幼鸟和脱换羽毛的地方。大泽在雁门的北面。
雁门山，雁出其间。在高柳北。
　　翻译：
　　雁门山，是大雁冬去春来出入的地方。雁门山在高柳山的北面。
高柳在代北。
　　翻译：
　　高柳山在代地的北面。
后稷之葬，山水环之。在氐国西①。
　　注解：
　　①氐国：就是上文所说的氐人国。
　　翻译：
　　后稷的葬地，有青山绿水环绕着它。后稷葬地在氐人国的西面。
流黄酆氏之国，中方三百里①，有涂四方②，中有山。在后稷葬西。
　　注解：
　　①中：域中，即国内土地的意思。
　　②涂：通“途”。道路。
　　翻译：
　　流黄酆氏国，疆域有方圆三百里大小。有道路通向四方，中间有一座大山。流黄酆氏国在后稷葬地的西面。
流沙出钟山①，西行又南行昆仑之虚②，西南入海，黑水之山。
　　注解：
　　①流沙：沙子和水一起流行移动的一种自然现象。
　　②虚：大丘。即指山。
　　翻译：
　　流沙的发源地在钟山，向西流动而再朝南流过昆仑山，继续往西南流入大海，直到黑水山。
东胡在大泽东。
　　翻译：
　　东胡国在大泽的东面。
夷人在东胡东。
　　翻译：
　　夷人国在东胡国的东面。
貊国在汉水东北。地近于燕，灭之。
　　翻译：
　　貊国在汉水的东北面。它靠近燕国的边界，后来被燕国灭掉了。
孟鸟在貊国东北。其鸟文赤、黄、青，东乡①。
　　注解：
　　①乡：通“向”
　　翻译：
　　孟鸟在貊国的东北面。这种鸟的羽毛花纹有红、黄、青三种颜色，向着东方。
海内昆仑之虚，在西北，帝之下都。昆仑之虚，方八百里，高万仞①。上有木禾，长五寻②，大五围。面有九井，以玉为槛③。面有九门，门有开明兽守之，百神之所在④。在八隅之岩，赤水之际，非（仁）[夷]羿莫能上冈之岩⑤。
　　注解：
　　①仞：古代的八尺为一仞。
　　②寻：古代的八尺为一寻。
　　③槛：窗户下或长廊旁的栏杆。这里指井栏。
　　④百：并非实数，而是言其多。
　　⑤夷羿，即后羿，神话传说中的英雄人物，善于射箭，曾经射掉九个太阳，射死毒蛇猛兽，为民除害。
　　翻译：
　　海内的昆仑山，屹立在西北方，是天帝在下方的都城。昆仑山，方圆八百里，高一万仞。山顶有一棵像大树似的稻谷，高达五寻，粗细需五人合抱。昆仑山的每一面有九眼井，每眼井都有用玉石制成的围栏。昆仑山的每一面有九道门，而每道门都有称作开明的神兽守卫着，是众多天神聚集的地方。众多天神聚集的地方是在八方山岩之间，赤水的岸边，不是具有像夷羿那样本领的人就不能攀上那些山冈岩石。
赤水出东南隅，以行其东北，[西南流注南海厌火东]。
　　翻译：
　　赤水从昆仑山的东南角发源，然后流到昆仑山的东北方，又转向西南流而注到南海厌火国的东边。
河水出东北隅，以行其北，西南又入渤海，又出海外，即西而北，入禹所导积石山。
　　翻译：
　　黄河水从昆仑山的东北角发源，然后流到昆仑山的北面，再折向西南流入渤海，又流出海外，就此向西而后往北流，一直流入大禹所疏导过的积石山。
洋水、黑水出西北隅，以东，东行，又东北，南入海，羽民南。
　　翻译：
　　洋水、黑水从昆仑山的西北角发源，然后折向东方，朝东流去，再折向东北方，又朝南流入大海，直到羽民国的南面。
弱水、青水出西南隅，以东，又北，又西南，过毕方鸟东。
　　翻译：
　　弱水、青水从昆仑山的西南角发源，然后折向东方，朝北流去，再折向西南方，又流经毕方鸟所在地的东面。
昆仑南渊深三百仞。开明兽身大类虎而九首，皆人面，东向立昆仑上。
　　翻译：
　　昆仑山的南面有一个深三百仞的渊潭。开明神兽的身子大小像老虎却长着九个脑袋，九个脑袋都是人一样的面孔，朝东立在昆仑山顶。
开明西有凤皇、鸾鸟，皆戴蛇践蛇，膺有赤蛇。
　　翻译：
　　开明神兽的西面有凤皇、鸾鸟栖息，都各自缠绕着蛇踩踏着蛇，胸前还有红色的蛇。
开明北有视肉、珠树、文玉树、玕琪树、不死树①，凤皇、鸾鸟皆戴瞂②，又有离朱、木禾、柏树、甘水、圣木曼兑③。一曰挺木牙交。
　　注解：
　　①珠树：神话传说中的生长珍珠的树。文玉树：神话传说中的生长五彩美玉的树。玕琪树：神话传说中的生长红色玉石的树。不死树：神话传说中的一种长生不死的树，人服食了它可也长寿不老。
　　②瞂：盾。
　　③离朱：即太阳里的踆乌，也叫三足乌。甘水：即古人所谓的醴泉，甜美的泉水。圣木曼兑：一种叫做曼兑的圣树，服食了它可使人圣明智慧。
　　翻译：
　　开明神兽的北面有视肉怪兽、珠树、文玉树、玕琪树、不死树，那里的凤皇、鸾鸟都戴着盾牌，还有三足乌、像树似的稻谷、柏树、甘水、圣木曼兑。另一种说法认为圣木曼兑叫做挺木牙交。
开明东有巫彭、巫抵、巫阳、巫履、巫凡、巫相，夹窫窳之尸，皆操不死之药以距之①。窫窳者，蛇身人面，贰负臣所杀也。
　　注解：
　　①距：通“拒”。抗拒。
　　翻译：
　　开明神兽的东面有巫师神医巫彭、巫抵、巫阳、巫履、巫凡、巫相，他们围在窫窳的尸体周围，都手捧不死药来抵抗死气而要使他复活。这位窫窳，是蛇的身子人的面孔，被贰负和他的臣子危合伙杀死的。
服常树，其上有三头人，伺琅玕树①。
　　注解：
　　①琅玕树：传说这种树上结出的果实就是珠玉。
　　翻译：
　　有一种服常树，它上面有个长着三颗头的人，静静伺察着那就在附近的琅玕树。
开明南有树鸟，六首；蛟、蝮、蛇、蜼、豹、鸟秩树①，于表池树木②；诵鸟、鶽、视肉③。
　　注解：
　　①蛟：像蛇的样子，但有四只脚，属于龙一类。蝮：大蛇。鸟秩树：不详何种树木。
　　②树：这里是动词，环绕着、排列着的意思。
　　③诵鸟：不详何种禽鸟。鶽：雕鹰。
　　翻译：
　　开明神兽的南面有种树鸟，长着六个脑袋；那里还有蛟龙、蝮蛇、长尾猿、豹子、鸟秩树，在水池四周环绕着树木而显得华美；那里还有诵鸟、鶽鸟、视肉怪兽。', NULL, '', 'indent', 1522505555, '5abf26d1ac502e0063a83f2a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636863, '山海经 · 海经 · 海内北经 ', NULL, 7, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E6%B5%B7%E5%86%85%E5%8C%97%E7%BB%8F/18509691?fr=aladdin', '', '海内西北陬以东者。
蛇巫之山，上有人操柸而东向立。一曰龟山。
西王母梯几而戴胜杖。其南有三青鸟，为西王母取食。在昆仑虚北。
有人曰大行伯，把戈。其东有犬封国。贰负之尸在大行伯东。
犬封国曰大戎国，状如犬。有一女子，方跪进柸食。有文马，缟身朱鬣，目若黄金，名曰吉量，乘之寿千岁。
鬼国在贰负之尸北，为物人面而一目。一曰贰负神在其东，为物人而蛇身。
蜪犬如犬，青，食人从首始。
穷奇状如虎，有翼，食人从首始。所食被发。在犬北。一曰从足。
帝尧台、帝喾台、帝丹朱台、帝舜台，各二台，台四方，在昆仑东北。
大蜂，其状如螽；朱蛾，其状如蛾。
蟜，其为人虎文，胫有䏿。在穷奇东。一曰状如人，昆仑虚北所有。
阘非，人面而兽身，青色。
据比之尸，其为人折颈披发，无一手。
环狗，其为人兽首人身。一曰猬状如狗，黄色。
袜，其为物，人身黑首从目。
戎，其为人，人首三角。
林氏国有珍兽，大若虎，五采毕具，尾长于身，名曰驺吾，乘之日行千里。
昆仑虚南所，有泛林方三百里。
从极之渊深三百仞，维冰夷恒都焉，，冰夷人面，乘两龙。一曰忠极之渊。
阳污之山，河山其中，凌门之山，河出其中。
王子夜之尸，两手、两股、胸、首、齿，皆断异处。
舜夷登比氏生宵明、烛光，处河大泽，二女之灵能照此所方百里。一曰登北氏。
盖国在钜燕南，倭北。倭属燕。
朝鲜在列阳东，海北山南。列阳属燕。
列姑射在海河州中。
射姑国在海中，属列姑射。西南，山环之。
大蟹在海中。
陵鱼人面，手足，鱼身，在海中。大鯾居海中。
明组邑居海中。逢莱山在海中。大人之市在海中。', '《山海经·海内北经》是一部古代志怪经典。', '', '海内由西北角向东的国家地区、山丘河川依次如下。　　蛇巫山，上面有人拿着一根棍棒向东站着。另一种说法认为蛇巫山叫做龟山。　　西王母靠倚着小桌案而头戴玉胜。在西王母的南面有三只勇猛善飞的青鸟，正在为西王母觅取食物。西王母和三青鸟的所在地是在昆仑山的北面。　　有个神人叫大行伯，手握一把长戈。在他的东面有犬封国。贰负之尸也在大行伯的东面。　　犬封国也叫犬戎国，那里的人都是狗的模样。犬封国有一女子，正跪在地上捧着一杯酒食向人进献。那里还有文马，是白色身子红色鬃毛，眼睛像黄金一样闪闪发光，名称是吉量，骑上它就能使人长寿千岁。　　鬼国在贰负之尸的北面，那里的人物是人的面孔却长着一只眼睛。另一种说法认为贰负神在鬼国的东面，他是人的面孔而蛇的身子。　　蜪犬的形状像一般的狗，全身是青色，它吃人是从人的头开始吃起。穷奇的形状像一般的老虎，却生有翅膀，　　穷奇吃人是从人的头开始吃。正被吃的人是披散着头发的。穷奇在蜪犬的北面。另一种说法认为穷奇吃人是从人的脚开始吃起。　　帝尧台、帝喾台、帝丹朱台、帝舜台，各自有两座台，每座台都是四方形，在昆仑山的东北面。　　有一种大蜂，形状像螽斯；有一种朱蛾，形状像蚍蜉。　　蟜，长着人的身子却有着老虎一样的斑纹，腿上有强健的小腿肚子。蟜在穷奇的东面。另一种说法认为蟜的形状像人，是昆仑山北面所独有的。　　阘非，长着人的面孔却是兽的身子，全身是青色。　　天神据比的尸首，形象是折断了脖子而披散着头发，没了一只手。　　环狗，这种人是野兽的脑袋人的身子。另一种说法认为是刺猬的样子而又像狗，全身是黄色。　　袜，这种怪物长着人的身子、黑色脑袋、竖立的眼睛。　　戎，这种人长着人的头而头上却有三只角。　　林氏国有一种珍奇的野兽，大小与老虎差不多，身上有五种颜色的斑纹，尾巴比身子长，名称是驺吾，骑上它可以日行千里。　　昆仑山南面的地方，有一片方圆三百里的氾林。　　从极渊有三百仞深，只有冰夷神常常住在这里。冰夷神长着人的面孔，乘着两条龙。另一种说法认为从极渊叫做忠极渊。　　阳污山，黄河的一条支流从这座山发源；凌门山，黄河的另一条支流从这座山发源。　　王子夜的尸体，两只手、两条腿、胸脯、脑袋、牙齿，都斩断而分散在不同地方。　　帝舜的妻子登比氏生了宵明、烛光两个女儿，她们住在黄河边上的大泽中，两位神女的灵光能照亮这里方圆百里的地方。另一种说法认为帝舜的妻子叫登北氏。　　盖国在大燕国的南面，倭国的北面。倭国隶属于燕国。　　朝鲜在列阳的东面，北面有大海而南面有高山。列阳隶属于燕国。　　列姑射在大海的河州上。　　姑射国在海中，隶属于列姑射。　　射姑国的西南部，高山环绕着它大蟹生活在海里。　　陵鱼长着人的面孔，而且有手有脚，却是鱼的身子，生活在海里。大鯾鱼生活在海里。　　明组邑生活在海岛上。蓬莱山屹立在海中。大人贸易的集市在海里。', NULL, '', 'indent', 1522505640, '5abf27259f54543001f86056', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636864, '山海经 · 海经 · 海内东经', NULL, 1, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E6%B5%B7%E5%86%85%E4%B8%9C%E7%BB%8F/19829103?fr=aladdin', '', '海内东北陬以南者。
钜燕在东北陬。
国在流沙中者埻端、玺㬇，在昆仑虚东南。一曰海内之郡，不为郡县，在流沙中。
国在流沙外者，大夏、竖沙、居繇、月支之国。
西胡白玉山在大夏东，苍梧在白玉山西南，皆在流沙西，昆仑虚东南。昆仑山在西胡西。皆在西北。
雷泽中有雷神，龙首而人头，鼓其腹。在吴西。
都州在海中。一曰郁州。
琅邪台在渤海间，琅邪之东。其北有山，一曰在海间。
韩雁在海中，都州南。
始鸠在海中，辕厉南。
会稽山在大楚南。 ', '《山海经·海内东经》是创作于战国时期的一篇散文，出自《山海经》作者不详。', '', '内由东北角向南的国家地区、山丘河川依次如下。大燕国在海内的东北角。在流沙中的国家有埻端国、玺㬇国，都在昆仑山的东南面。另一种说法认为埻端国和玺㬇国是在海内建置的郡，不把它们称为郡县，是因为处在流沙中的缘故。在流沙以外的国家，有大夏国、竖沙国、居繇国、月支国。西方胡人的白玉山国在大夏国的东面，苍梧国在白玉山国的西南面，都在流沙的西面，昆仑山的东南面。昆仑山位于西方胡人所在地的西面。总的位置都在西北方。雷泽中有一位雷神，长着龙的身子人的头，他一鼓起肚子就响雷。雷泽在吴地的西面。都州在海里。一种说法认为都州叫做郁州。琅邪山位于渤海与海岸之间，在琅邪台的东面。琅邪台的北面有座山。另一种说法认为琅邪山在海中。韩雁在海中，又在都州的南面。始鸠在海中，又在韩雁的南面。会稽山在大越的南面。', NULL, '', 'indent', 1522505726, '5abf277cee920a0045031f87', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636865, '山海经 · 海经 · 大荒东经', NULL, 1, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', '', '', '东海之外大壑，少昊之国。少吴孺帝颛顼于此，弃其琴瑟。
有甘山者，甘水出焉，生甘渊。
大荒东南隅有，名皮母地丘。
东海之外，大荒之中，有山名曰大言，日月所出。
有波谷山者，有大人之国。有大人之市，名曰大人之堂。有一大人踆其上，张其两耳。
有小人国，名靖人。
有神，人面兽身，名曰犂。
有潏山，杨水出焉。
有蒍国，黍食，使四鸟：虎、豹、熊、罴。
大荒之中，有山名曰合虚，日月所出。
有中容之国。帝俊生中容，中容人食兽、木实，使四鸟：豹、虎、熊、罴。
有东口之山。有君子之国，其人衣冠带剑。
有司幽之国。帝俊生晏龙，晏龙生司幽，司幽生思土，不妻；思女，不夫。食黍，食兽，是使四鸟。
有大阿之山者。
大荒中有山，名曰明星，日月所出。
有白民之国。帝俊生帝鸿，帝鸿生白民，白民销姓，黍食，使四鸟：豹、虎、熊、罴。
有青丘之国，有狐，九尾。
有柔仆民，是维嬴土之国。
有黑齿之国。帝俊生黑齿，姜姓，囗食，使四鸟。
有夏州之国。有盖余之国。
有神人，八首人面，虎身十尾，名曰天吴。
大荒之中，有山名曰鞠陵于天、东极、离瞀，日月所出。名曰折丹－－东方曰折，来风曰俊－－处东极以出入风。
东海之渚中，有神，人面鸟身，珥两黄蛇，践两黄蛇，名曰禺䝞。黄帝生禺䝞，禺䝞生禺京。禺京处北海，禺䝞处东海，是惟海神。
有招摇山，融水出焉。有国曰玄股，黍食，使四鸟。
有困民国，勾姓而食。有人曰王亥，两手操鸟，方食其头。王亥托于有易、河伯仆牛。有易潜出，为国于兽，方食之，名曰摇民。帝舜生戏，戏生摇民。
海内有两人，名曰女丑。女丑有大蟹。
大荒之中，有山名曰孽摇頵羝。上有扶木，柱三百里，其叶如芥。有谷曰温源谷。汤谷上有扶木，一曰方至，一曰方出，皆载于乌。
有神，人面、犬耳、兽身，珥两青蛇，名曰奢比尸。
有五采之鸟，相乡弃沙。惟帝俊下友。帝下两坛，采鸟是司。
大荒之中，有山名曰猗天苏山，日月所生。
有壎民之国。有綦山。又有摇山。有䰝山，又有门户山，又有盛山。又有待山。有五采之鸟。
东荒之中，有山名曰壑明俊疾，日月所出。有中容之国。
东北海中，又有三青马、三骓、甘华。爱有遗玉、三青鸟、三骓、视肉、甘华、甘柤。百谷所在。
有女和月母之国。有人名曰䳃－－北方曰䳃，来之风曰【犭炎】－－是处东极隅以止日月，使无相间出没，司其短长。
大荒东北隅中，有山名曰凶犁土丘。应龙处南极，杀蚩尤与夸父，不得复上，故下数旱。旱而为应龙之状，乃得大雨。
东海中有流波山，入海七千里。其上有兽，状如牛，苍身而无角，一足，出入水则必风雨，其光如日月，其声如雷，其名曰夔。黄帝得之，以其皮为鼓，橛以雷兽之骨，声闻五百里，以威天下。 ', '', '', '东海以外有一深得不知底的沟壑，是少昊建国的地方。少昊就在这里抚养帝颛顼成长，帝颛顼幼年玩耍过的琴瑟还丢在沟壑里。有一座甘山，甘水从这座山发源，然后流汇成甘渊。东海以外，大荒当中，有座山叫做大言山，是太阳和月亮初出升起的地方。 　　有座波谷山，有个大人国就在这山里。有大人做买卖的集市，就在叫做大人堂的山上。有一个大人正蹲在上面，张开他的两只手臂。有个小人国，那里的人被称作靖人。有一个神人，长着人的面孔野兽的身子，叫做犂。有座潏山，杨水就是从这座山发源的。有一个蒍国，那里的人以黄米为食物，能驯化驱使四种野兽：老虎、豹子、熊、罴。在大荒当中，有座山叫做合虚山，是太阳和月亮初出升起的地方。有一个国家叫中容国。帝俊生了中容，中容国的人吃野兽的肉、树木的果实，能驯化驱使四种野兽：豹子、老虎、熊、罴。有座东口山。有个君子国就在东口山，那里的人穿衣戴帽而且腰间佩带宝剑。 　　有个国家叫司幽国。帝俊生了晏龙，晏龙生了司幽，司幽生了思土，而思土不娶妻子;司幽还生了思女，而思女不嫁丈夫。司幽国的人吃黄米饭，也吃野兽肉，能驯化驱使四种野兽。有一座山叫做大阿山。大荒当中有一座高山，叫做明星山，是太阳和月亮初出升起的地方。有个国家叫白民国。帝俊生了帝鸿，帝鸿的后代是白民，白民国的人姓销，以黄米为食物，能驯化驱使四种野兽：老虎、豹子、熊、罴。 　　有个国家叫青丘国。青丘国有一种狐狸，长着九条尾巴。有一群人被称作柔仆民，他们所在的国土很肥沃。 　　有个国家叫黑齿国。帝俊的后代是黑齿，姓姜，那里的人吃黄米饭，能驯化驱使四种野兽。 　　有个国家叫夏州国。在夏州国附近又有一个盖余国。有个神人，长着八颗头而都是人的脸面，老虎身子而十条尾巴，名叫天吴。 　　在大荒当中，有三座高山分别叫做鞠陵于天山、东极山、离瞀山，都是太阳和月亮初出升起的地方。有个神人名叫折丹，东方人单称他为折，从东方吹来的风称作俊，他就处在大地的东极主管风起风停。东海的岛屿上，有一个神人，长着人的面孔鸟的身子，耳朵上穿挂着两条黄色的蛇，脚底下踩踏着两条黄色的蛇，名叫禺猇。黄帝生了禺猇。，禺猇生了禺京。禺京住在北海，禺猇住在东海，都是海神。 　　有座招摇山，融水从这座山发源。有一个国家叫玄股国，那里的人吃黄米饭，能驯化驱使四种野兽。有个国家叫因民国，那里的人姓勾，以黄米为食物。有个人叫王亥，他用两手抓着一只鸟，正在吃鸟的头。王亥把一群肥牛寄养在有易族人、水神河伯那里。有易族人把王亥杀死，没收了那群肥牛。河伯哀念有易族人，便帮助有易族人偷偷地逃出来，在野兽出没的地方建立国家，他们正在吃野兽肉，这个国家叫摇民国。另一种说法认为帝舜生了戏，戏的后代就是摇民。 　　海内有两个神人，其中的一个名叫女丑。女丑有一只听使唤的大螃蟹。在大荒当中，有一座山名叫孽摇頵羝。山上有棵扶桑树，高耸三百里，叶子的形状像芥菜叶。有一道山谷叫做温源谷。汤谷上面也长了棵扶桑树，一个太阳刚刚回到汤谷，另一个太阳刚刚从扶桑树上出去，都负载于三足乌的背上。有一个神人，长着人的面孔、大大的耳朵、野兽的身子，耳朵上穿挂着两条青色的蛇，名叫奢比尸。有一群长着五彩羽毛的鸟，相对而舞，天帝帝俊从天上下来和它们交友。帝俊在下界的两座祭坛，由这群五彩鸟掌管着。 　　在大荒当中，有一座山名叫猗天苏门山，是太阳和月亮初出升起的地方。有个国家叫壎民国。有座綦山。又有座摇山。又有座【鬲曾】山。又有座门户山。又有座盛山。又有座待山。还有一群五彩鸟。在东荒当中，有座山名叫壑明俊疾山，是太阳和月亮初出升起的地方。这里还有个中容国。东北海外，又有三青马、三骓马、甘华树。这里还有遗玉、三青鸟、三骓马、视肉怪兽、甘华树、甘柤树。是各种庄稼生长的地方。有个国家叫女和月母国。有一个神人名叫鹓，北方人称作鹓，从那里吹来的风称作【犭炎】，他就处在大地的东北角以便控制太阳和月亮，使不要交相错乱地出没，掌握它们升起落下时间的长短。在大荒的东北角上，有一座山名叫凶犁土丘山。应龙就住在这座山的最南端，因杀了神人蚩尤和神人夸父，不能再回到天上，天上因没了兴云布雨的应龙而使下界常常闹旱灾。下界的人们一遇天旱就装扮成应龙的样子求雨，就得到大雨。东海当中有座流波山，这座山在进入东海七千里的地方。山上有一种野兽，形状像普通的牛，是青苍色的身子却没有犄角，仅有一只蹄子，出入海水时就一定有大风大雨相伴随，它发出的亮光如同太阳和月亮，它吼叫的声音如同雷响，名叫夔。 　　黄帝得到它，便用它的皮蒙鼓，再拿雷兽的骨头敲打这鼓，响声传到五百里以外，用来威震天下。', NULL, '', 'indent', 1522505872, '5abf27ff9f545433515b33be', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636866, '山海经 · 海经 · 大荒南经', NULL, 0, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', '', '', '南海之外，赤水之西，流沙之东，有兽，左右有首，名曰䟣踢。有三青兽相并，名曰双双。
有阿山者。南海之中，有泛天之山，赤水穷焉。赤水之东，有苍梧之野，舜与叔均之所葬也。爰有文贝、离俞、【丘鸟】久、鹰、贾、委维、熊、罴、象、虎、豹、狼、视肉。
有荣山、荣水出焉。黑水之南，有玄蛇，食麈。
有巫山者，西行黄鸟。帝药，八斋。黄鸟于巫山，司此玄蛇。
大荒之中，有不庭之山，荣水穷焉。有人三身，帝俊妻娥皇，生此三身之国，姚姓，黍食，使四鸟。有渊四方，四隅皆送，北属黑水，南属大荒。北旁名曰少和之渊，南旁名曰从渊，舜之所浴也。
又有成山，甘水穷焉。有季禺之国，颛顼之子，食黍。有羽民之国，其民皆生毛羽。有卵之国，其民皆生卵。
大荒之中，有不姜之山，黑水穷焉。又有贾山，汔水出焉。又有言山。又有登备之山。有恝恝之山。又有蒲山，澧水出焉。又有隗山，其西有丹，其东有玉。又南有山，漂水出焉。有尾山。有翠山。
有盈民之国，于姓，黍食。又有人方食木叶。
有不死之国，阿姓，甘木是食。
大荒之中，有山名曰去痓。南极果，北不成，去痓果。
南海渚中，有神，人面，珥两青蛇，践两赤蛇，曰不廷胡余。
有神名曰因因乎－－南方曰因乎，夸风曰乎民－－处南极以出入风。
有襄山。又有重阴之山。有人食兽，曰季厘。帝俊生季厘，故曰季厘之国。有缗渊。少昊生倍伐降处缗渊。有水四方，名曰俊坛。
有臷民之国。帝舜生无淫，降臷处，是谓巫臷民。巫臷民盼姓，食谷，不绩不经，服也；不稼不穑，食也。爱歌舞之鸟，鸾鸟自歌，凤鸟自舞。爰有百兽，相群爰处。百谷所聚。
大荒之中，有山名曰融天，海水南入焉。
有人曰凿齿，有蜮山者，有蜮民之国，桑姓，食黍，射蜮是食。有人方扞弓射黄蛇，名曰蜮人。
有宋山者，有赤蛇，名曰育蛇。有木生山上，名曰枫木。枫木，蚩尤所弃其桎梏，是为枫木。
有人方齿虎尾，名曰祖状之尸。
有小人，名曰焦侥之国，几姓，嘉谷是食。
大荒之中，有山名㱙涂之山，青水穷焉。有云雨之山，有木名曰栾。禹攻云雨。有赤石焉生栾，黄本，赤枝，青叶，群帝焉取药。
有国曰颛顼，生伯服，食黍。有鼬姓之国。有苕山。又有宗山。又有姓山，又有壑山。又有陈州山，又有东州山。又有白水山，白水出焉，而生白渊，昆吾之师所浴也。
有人名曰张宏，在海上捕鱼。海中有张宏之国，食鱼，使四鸟。
有人焉，鸟喙，有翼，方捕鱼于海。大荒之中，有人名曰欢头。鲧妻士敬，士敬子曰琰融，生欢头。头人面鸟喙，有翼，食海中鱼，杖翼而行。维宜芑苣，穋是食。有欢头之国。
帝尧、帝喾、帝舜葬于岳山。爰有文贝、离俞、【丘鸟】久、鹰、廷维、视肉、熊、罴、虎、豹；朱木、青华，玄实。有申山者。
大荒之中，有山名曰天台高山，海水入焉。
东南海之外，甘水之间，有羲和之国，有女子名曰羲和，方日浴于甘渊。羲和者，帝俊之妻，生十日。
有盖犹之山者，其上有甘柤，枝干皆赤，黄叶，白华，黑实。东又有甘华，枝干皆赤，黄叶。有青马，有赤马，名曰三骓。有视肉。
有小人，名曰菌人。
有南类之山。爰有遗玉、青马、三骓、视肉、甘华。百谷所在。 ', '', '', '在南海以外，赤水的西岸，流沙的东面，生长着一种野兽，左边右边都有一个头，名称是䟣踢。还有三只青色的野兽交相合并着，名称是双双。有座山叫阿山。南海的当中，有一座氾天山，赤水最终流到这座山。在赤水的东岸，有个地方叫苍梧野，帝舜与叔均葬在那里。这里有花斑贝、离朱鸟、鹞鹰、老鹰、乌鸦、两头蛇、熊、罴、大象、老虎、豹子、狼、视肉怪兽。有一座荣山，荣水就从这座山发源的。在黑水的南岸，有一条大黑蛇，正在吞食麈鹿。有一座山叫巫山，在巫山的西面有只黄鸟。天帝的神仙药，就藏在巫山的八个斋舍中。黄鸟在巫山上，监视着那条大黑蛇。 　　在大荒当中，有座不庭山，荣水最终流到这座山。这里有一种人长着三个身子。帝俊的妻子叫娥皇，这三身国的人就是他们的后代子孙。三身国的人姓姚，吃黄米饭，能驯化驱使四种野兽。这里有一个四方形的渊潭，四个角都能旁通，北边与黑水相连，南边和大荒相通。北侧的渊称作少和渊，南侧的渊称作从渊，是帝舜所洗澡的地方。又有一座成山，甘水最终流到这座山。有个国家叫季禺国，他们是帝颛顼的子孙后代，吃黄米饭。还有个国家叫羽民国，这里的人都长着羽毛。又有个国家叫卵民国，这里的人都产卵而又从卵中孵化生出。大荒之中，有座不姜山，黑水最终流到这座山。又有座贾山，汔水从这座山发源。又有座言山。又有座登备山。还有座恝恝山。又有座蒲山，澧水从这座山发源。又有座隗山，它的西面蕴藏有丹雘，它的东面蕴藏有玉石。又往南有座高山，漂水就是从这座山中发源的。又有座尾山。还有座翠山。有个国家叫盈民国，这里的人姓于，吃黄米饭。又有人正在吃树叶。有个国家叫不死国，这里的人姓阿，吃的是不死树。在大荒当中，有座山叫做去室山。南极果，北不成，去室果。 　　在南海的岛屿上，有一个神，是人的面孔，耳朵上穿挂着两条青色蛇，脚底下踩踏着两条红色蛇，这个神叫不廷胡余。有个神人名叫因乎，南方人单称他为因，从南方吹来的风称作民，他处在大地的南极主管风起风停。有座襄山。又有座重阴山。有人在吞食野兽肉，名叫季厘。帝俊生了季厘，所以称作季厘国。有一个缗渊。少昊生了倍伐，倍伐被贬住在缗渊。有一个水池是四方形的，名叫俊坛。有个国家叫臷民国。帝舜生了无淫，无淫被贬在臷这个地方居住，他的子孙后代就是所谓的巫臷民。巫臷民姓朌，吃五谷粮食，不从事纺织，自然有衣服穿;不从事耕种，自然有粮食吃。这里有能歌善舞的鸟，鸾鸟自由自在地歌唱，凤鸟自由自在地舞蹈。这里又有各种各样的野兽，群居相处。还是各种农作物汇聚的地方。 　　在大荒当中，有座山叫做融天山，海水从南面流进这座山。有一个神人叫凿齿，羿射死了他。有座山叫做蜮山，在这里有个蜮民国，这里的人姓桑，吃黄米饭，也把射死的蜮吃掉。有人正在拉弓射黄蛇，名叫蜮人。有座山叫做宋山，山中有一种红颜色的蛇，名叫育蛇。山上还有一种树，名叫枫木。枫木，原来是蚩尤死后所丢弃的手铐脚镣，这些刑具就化成了枫木。有个神人正咬着老虎的尾巴，名叫祖状尸。有一个由三尺高的小人组成的国家，名叫焦侥国，那里的人姓几，吃的是优良谷米。在大荒当中，有座山名叫涂山，青水最终流到这座山。还有座云雨山，山上有一棵树叫做栾。大禹在云雨山砍伐树木，发现红色岩石上忽然生出这棵栾树，黄色的茎干，红色的枝条，青色的叶子，诸帝就到这里来采药。有个国家叫伯服国，颛顼的后代组成伯服国，这里的人吃黄米饭。有个鼬姓国。有座苕山。又有座宗山。又有座姓山。又有座壑山。又有座陈州山。又有座东州山。还有座白水山，白水从这座山发源，然后流下来汇聚成为白渊，是昆吾的师傅洗澡的地方。有个人叫做张宏，正在海上捕鱼。海里的岛上有个张宏国，这里的人以鱼为食物，能驯化驱使四种野兽。有一种人，长着鸟的嘴，生有翅膀，正在海上捕鱼。 　　在大荒当中，有个人名叫欢头。鲧的妻子是士敬，士敬生个儿子叫炎融，炎融生了欢头。欢头长着人的面孔而鸟一样的嘴，生有翅膀，吃海中的鱼，凭借着翅膀行走。也把苣、穋、杨树叶做成食物吃。于是有了欢头国。帝尧、帝喾、帝舜都葬埋在岳山。这里有花斑贝、三足乌、鹞鹰、老鹰、乌鸦、两头蛇、视肉怪兽、熊、罴、老虎、豹子;还有朱木树，是红色的枝干、青色的花朵、黑色的果实。有座申山。 　　在大荒当中，有座山名叫天台山，海水从南边流进这座山中。在东海之外，甘水之间，有个羲和国。这里有个叫羲和的女子，正在甘渊中给太阳洗澡。羲和这个女子，是帝俊的妻子，生了十个太阳。有座山叫盖犹山，山上生长有甘柤树，枝条和茎干都是红的，叶子是黄的，花朵是白的，果实是黑的。在这座山的东端还生长有甘华树，枝条和茎干都是红色的，叶子是黄的。有青色马。还有红色马，名叫三骓。又有视肉怪兽。有一种十分矮小的人，名叫菌人。', NULL, '', 'indent', 1522505966, '5abf28679f54543001f86888', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636867, '山海经 · 海经 · 大荒西经', NULL, 1, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', '', '', '西北海之外，大荒之隅，有山而不合，名曰不周负子，有两黄兽守之。有水曰寒署之水。水西有湿山，水东有幕山。有禹攻共工国山。
有国名曰淑士，颛顼之子。
有神十人，名曰女娲之肠，化为神，处栗广之野；横道而处。
有人名曰石夷，来风曰韦，处西北隅以司日月之长短。
有五采之鸟，有冠，名曰狂鸟。
有大泽之长山。有白氏之国。
西北海之外，赤水东，有长胫之国。
有西周之国，姬姓，食谷。有人方耕，名曰叔均。帝俊生后稷，稷降以谷。稷之曰台玺，生叔均。叔均是代其父及稷播百谷，始作耕。有赤国妻氏。有双山。
西海之外，大荒之中，有方山者，上有青树，名曰柜格之松，日月所出入也。
西北海之外，赤水之西，有先民之国，食谷，使四鸟。
有北狄之国。黄帝之孙曰始均，始均生北狄。
有芒山。有桂山。有榣山，其上有人，号曰太子长琴。颛顼生老童，老童生祝融，祝融生太子长琴，是处榣山，始作乐风。
有五采鸟三名：一曰皇鸟，一曰鸾鸟，一曰凤鸟。
有虫状如菟，胸以后者裸不见，青如猨状。
大荒之中，有山名曰丰沮玉门，日月所入。
有灵山，巫咸、巫即、巫盼、巫彭、巫姑、巫真、巫礼、巫抵、巫谢、巫罗十巫，从此升降，百药爰在。
西有王母之山，壑山、海山。有沃之国，沃民是处。沃之野，凤鸟之卵是食，甘露是饮。凡其所欲其味尽存。爰有甘华、璇瑰、甘柤、瑶碧、白木、白柳、视肉、琅玕、白丹、青丹、多银铁。鸾凤自歌，凤鸟自舞，爰有百兽，相群是处，是谓沃之野。
有三青鸟，赤首黑目，一名曰大鵹，一曰少鵹，一名曰青鸟。
有轩辕之台，射者不敢西向射，畏轩辕之台。
大荒之中，有龙山，日月所入。有三泽水，名曰三淖，昆吾之所食也。
有人衣青，以袂蔽面，名曰女丑之尸。
有女子之国。
有桃山。有虻山。有桂山。有于土山。
有丈夫之国。
有弇州之国，五采之鸟仰天，名曰鸣鸟。爰有百乐歌舞之凤。
有轩辕之国。江山之南栖为吉。不寿者乃八百岁。
西海郩中，有神，人面鸟身，珥两青蛇，践两赤蛇，名曰弇兹。
大荒之中，有山名曰日月山，天枢也。吴姖天门，日月所入。有神，人面无臂，两足反属于头山，名曰嘘。颛顼生老童，老童生重及黎，帝令重献上天，令黎邛下地。下地是生噎，处于西极，以行日月星辰之行次。
有人反臂，名曰天虞。
有女子方浴月。帝俊妻常羲，生月十有二，此始浴之。
行玄丹之山。有五色之鸟，人面有发。爰有青鴍、黄鷔、青鸟、黄鸟，其所集者其国亡。
有池，名孟翼之攻颛顼之池。
大荒之中，有山名曰鏖鏊钜，日月所入者。
有兽，左右有首，名曰屏蓬。
有巫山者。有壑山者。有金门之山，有人名曰黄姖之尸。有比翼之鸟。有白鸟，青翼，黄尾，玄喙。有赤犬，名曰天犬，其所下者有兵。
西海之南，流沙之滨，赤水之后，黑水之前，有大山，名曰昆仑之丘。有神，人面虎身，有文有尾，皆白，处之。其下有弱水之渊环之，其外有炎火之山，投物辄然。有人戴胜，虎齿，有豹尾，穴处，名曰西王母。此山万物尽有。
大荒之中，有山名曰常阳之山，日月所入。
有寒荒之国。有二人女祭、女囗。
有寿麻之国。南岳娶州山女，名曰女虔。女虔生季格，季格生寿麻。寿麻正立无景，疾呼无响。爰有大暑，不可以往。
有人无首，操戈盾立，名曰夏耕之尸。故成汤伐夏桀于章山，克之，斩耕厥前。耕既立，无首，走厥咎，乃降于巫山。
有人名曰吴回，奇左，是无右臂。
有盖山之国。有树，赤皮枝干，青叶，名曰朱木。
有一臂民。
大荒之中，有山，名曰大荒之山，日月所入。有人焉三面，是颛顼之子，三面一臂，三面之人不死。是谓大荒之野。
西南海之外，赤水之南，流沙之西，有人珥两青蛇，乘两龙，名曰夏后开。开上三嫔于天，得《九辩》与《九歌》以下。此天穆之野，高二千仞，开焉得始歌《九招》。
有互人之国。炎帝之孙名曰灵恝生百互人，是能上下于天。
有鱼偏枯，名曰鱼妇。颛顼死即复苏。风道北来，天及大水泉，蛇乃化为鱼，是为鱼妇。颛顼死即复苏。
有青鸟，身黄，赤足，六首，名曰鸀鸟。
有大巫山。有金之山。西南，大荒之中隅，有偏句、常羊之山。', '', '', '在西北海以外，大荒的一个角落，有座山断裂而合不拢，名叫不周山，有两头黄色的野兽守护着它。有一条水流名叫寒暑水。寒暑水的西面有座湿山，寒暑水的东面有座幕山。还有一座禹攻共工国山。有个国家名叫淑士国，这里的人是帝颛顼的子孙后代。有十个神人，名叫女娲肠，就是女娲的肠子变化而成神的，在称作栗广的原野上；他们拦断道路而居住。有位神人名叫石夷，西方人单称他为夷，从北方吹来的风称作韦，他处在大地的西北角掌管太阳和月亮升起落下时间的长短。有一种长着五彩羽毛的鸟，头上有冠，名叫狂鸟。
有一座大泽长山。有一个白氏国。在西北海以外，赤水的东岸，有个长胫国。有个西周国，这里的人姓姬，吃谷米。有个人正在耕田，名叫叔均。帝俊生了后稷，后稷把各种谷物的种子从天上带到下界。后稷的弟弟叫台玺，台玺生了叔均。叔均于是代替父亲和后稷播种各种谷物，开始创造耕田的方法。有个赤国妻氏。有座双山。在西海以外，大荒的当中，有座山叫方山，山上有棵青色大树，名叫柜格松，是太阳和月亮出入的地方。在西北海以外，赤水的西岸，有个天民国，这里的人吃谷米，能驯化驱使四种野兽有个北狄国。黄帝的孙子叫始均，始均的后代子孙，就是北狄国人。有座芒山。有座桂山。有座榣山，山上有一个人，号称太子长琴。颛琐生了老童，老童生了祝融，祝融生了太子长琴，于是太子长琴住在榣山上，开始创作乐而风行世间。
有三种长着彩色羽毛的鸟：一种叫凰鸟，一种叫鸾鸟，一种叫凤鸟。有一种野兽的形状与普通的兔子相似，胸脯以后部分全露着而又分不出来，这是因为它的皮毛青得像猿猴而把裸露的部分遮住了。在大荒的当中，有座山名叫丰沮玉门山，是太阳和月亮降落的地方。有座灵山，巫咸、巫即、巫朌、巫彭、巫姑、巫真、巫礼、巫抵、巫谢、巫罗等十个巫师，从这座山升到天上和下到世间，各种各样的药物就生长在这里。有西王母山、壑山、海山。有个沃民国，沃民便居住在这里。生活在沃野的人，吃的是凤鸟产的蛋，喝的是天降的甘露。凡是他们心里想要的美味，都能在凤鸟蛋和甘露中尝到。这里还有甘华树、甘柤树、白柳树，视肉怪兽、三骓马、璇玉瑰石、瑶玉碧玉、白木树、琅玕树、白丹、青丹，多出产银、铁。鸾鸟自由自在地歌唱，凤鸟自由自在地舞蹈，还有各种野兽，群居相处，所以称作沃野。有三只青色大鸟、红红的脑袋黑黑的眼睛，一只叫做大鵹，一只叫做少鵹，一只叫做青鸟。有座轩辕台，射箭的人都不敢向西射，因为敬畏轩辕台上黄帝的威灵。大荒当中，有座龙山，是太阳和月亮降落的地方。有三个汇聚成的大水地，名叫三淖，是昆吾族人取得食物的地方。有个人穿着青色衣服，用袖子遮住脸面，名叫女丑尸。有个女子国。有座桃山。还有座虻山。又有座桂山。又有座于土山。有个丈夫国。有座弇州山，山上有一种长着五彩羽毛的鸟正仰头向天而嘘，名叫鸣鸟。因而这里有各种各样乐曲歌舞的风行。有个轩辕国。这里的人把居住在江河山岭的南边当作吉利，就是寿命不长的人也活到了八百岁。
在西海的岛屿上，有一个神人，长着人的面孔鸟的身子，耳朵上穿挂着两条青色蛇，脚底下踩踏着两条红色蛇，名叫弇兹。大荒当中，有座山名叫日月山，是天的枢纽。这座山的主峰叫吴姖天门山，是太阳和月亮降落的地方。有一个神人，形状像人而没有臂膀，两只脚反转着连在头上，名叫嘘。帝颛顼生了老童，老童生了重和黎，帝颛顼命令重托着天用力往上举，又命令黎撑着地使劲朝下按。于是黎来到地下并生了噎，他就处在大地的最西端，主管着太阳、月亮和星辰运行的先后次序。有个神人反长着臂膀，名叫天虞。有个女子正在替月亮洗澡。帝俊的妻子常羲，生了十二个月亮，这才开始给月亮洗澡。有座玄丹山。在玄丹山上有一种长着五彩羽毛的鸟，一副人的面孔而且有头发。这里还有青雘、黄鷔，这种青色的鸟、黄色的鸟，它们在哪个国家聚集栖息那个国家就会灭亡。有个水池，名叫孟翼攻颛顼池。大荒当中，有座山名叫鏖鏊钜山，是太阳和月亮降落的地方。有一种野兽，左边和右边各长着一个头，名叫屏蓬。有座叫做巫山的山。又有座叫做壑山的山。还有座金门山，山上有个人名叫黄姖尸。有比翼鸟。有一种白鸟，长着青色的翅膀，黄色的尾巴，黑色的嘴壳。有一种红颜色的狗，名叫天犬，它所降临的地方都会发生战争。在西海的南面，流沙的边沿，赤水的后面，黑水的前面，屹立着一座大山，就是昆仑山。有一个神人，长着人的面孔、老虎的身子，尾巴有花纹，而尾巴上尽是白色斑点，住在这座昆仑山上。昆仑山下有条弱水汇聚的深渊环绕着它，深渊的外边有座炎火山，一投进东西就燃烧起来。有人头上戴着玉制首饰，满口的老虎牙齿，有一条豹子似的尾巴，在洞穴中居住，名叫西王母。这座山拥有世上的各种东西。
大荒当中，有座山名叫常阳山，是太阳和月亮降落的地方。有个寒荒国。这里有两个神人分别叫女祭、女薎。有个国家叫寿麻国。南岳娶了州山的女子为妻，她的名字叫女虔。女虔生了季格，季格生了寿麻。寿麻端端正正站在太阳下不见任何影子，高声疾呼而四面八方没有一点回响。这里异常炎热，人不可以前往。有个人没了脑袋，手拿一把戈和一面盾牌立着，名叫夏耕尸。从前成汤在章山讨伐夏桀，打败了夏桀，斩杀夏耕尸于他的面前。夏耕尸站立起来后，发觉没了脑袋，为逃避他的罪咎，于是窜到巫山去了。有个人名叫吴回，只剩下左臂膀，而没了右臂膀有个盖山国。这里有一种树木，树皮树枝树干都是红色的，叶子是青色的，名叫朱木。有一种只长一条臂膀的一臂民。荒当中，有一座山，名叫大荒山，是太阳和月亮降落的地方。这里有一种人的头上的前边和左边、右边各长着一张面孔，是颛顼的子孙后代，三张面孔一只胳膊，这种三张面孔的人永远不死。这里就是所谓的大荒野。在西南海以外，赤水的南岸，流沙的西面，有个人耳朵上穿挂着两条青色蛇，乘驾着两条龙，名叫夏后启。夏后启曾三次到天帝那里做客，得到天帝的乐曲《九辩》和《九歌》而下到人间。这里就是所谓的天穆野，高达二千仞，夏后启在此开始演奏《九招》乐曲。有个氐人国。炎帝的孙子名叫灵恝，灵恝生了氐人，这里的人能乘云驾雾上下于天。有一种鱼的身子半边干枯，名叫鱼妇，是帝颛顼死了又立即苏醒而变化的。风从北方吹来，天于是涌出大水如泉，蛇于是变化成为鱼，这便是所谓的鱼妇。而死去的颛顼就是趁蛇鱼变化未定之机托体鱼躯并重新复苏的。
有一种青鸟，身子是黄色的，爪子是红色的，长有六个头，名叫鸀鸟。有座大巫山。又有座金山。在西南方，大荒的一个角落，有偏句山、常羊山。', NULL, '', 'indent', 1522506112, '5abf28d9a22b9d0045371dca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636868, '山海经 · 海经 · 大荒北经', NULL, 3, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%B1%B1%E6%B5%B7%E7%BB%8F%C2%B7%E5%A4%A7%E8%8D%92%E5%8C%97%E7%BB%8F/19829107?fr=aladdin', '', '东北海之外，大荒之中，河水之间，附禺之山，帝颛顼与九嫔葬焉。爰有【丘鸟】久、文贝、离俞、鸾鸟、皇鸟、大物、小物。有青鸟、琅鸟、玄鸟、黄鸟、虎、豹、熊、罴、黄蛇、视肉、？瑰、瑶碧，皆出卫于山。丘方员三百里，丘南帝俊竹林在焉，大可为舟。竹南有赤泽水，名曰封渊。有三桑无枝。丘西有沉渊，颛顼所浴。
有胡不与之国，烈姓，黍食。
大荒之中，有山名曰不咸，有肃慎氏之国。蜚蛭，四翼。有虫，兽身蛇身，名曰琴虫。
有人名曰大人。有大人之国，厘姓，黍食。有大青蛇，黄头，食麈。
有榆山。有鲧攻程州之山。
大荒之中，有山名曰衡天。有先民之山。有盘木千里。
有叔歜国，颛顼之子，黍食，使四鸟：虎、豹、熊、罴。有黑虫如熊状，名曰猎猎。
有北齐之国，姜姓，使虎、豹、熊、罴。
大荒之中，有山名曰先槛大逢之山，河济所入，海北注焉。其西有山，名曰禹所积石。
有阳山者。有顺山者，顺水出焉。有始州之国，有丹山。
有大泽方千里，群鸟所解。
有毛民之国，依姓，食黍，使四鸟。禹生均国，均国生役采，役采生修【革台】，修【革台】杀绰人。帝念之，潜为之国，是此毛民。
有儋耳之国，任姓禺号子，食谷。北海之渚中，有神，人面鸟身，珥两青蛇，践两赤蛇，名曰禺强。
大荒之中，有山名曰北极天柜，海水北注焉。有神，九首人面鸟身，名曰九凤。又有神衔蛇衔操蛇，其状虎首人身，四蹄长肘，名曰强良。
大荒之中，有山名曰成都，载天。有人，珥两黄蛇，把两黄蛇，名曰夸父。后土生信，信生夸父。夸父不量力，欲追日景，逮之于禺谷。将饮河而不足也，将走大泽，未至，死于此。应龙已杀蚩尤，又杀夸父，乃去南方处之，故南方多雨。
又有无肠国，是任姓。无继子，食鱼。
共工臣名曰相繇，九首蛇身，自环，食于九土。其所歍所尼，即为源泽，不辛乃苦，百兽莫能处。禹湮洪水，杀相繇，其血腥臭，不可生谷；其地多水，不可居也。禹湮之，三仞三沮，乃以为池，群帝因是以为台。在昆仑之北。
有岳之山。寻竹生焉。
大荒之中，有名山曰不句，海水入焉。
有系昆之山者，有共工之台，射者不敢北射。有人衣青衣，名曰黄帝女魃。蚩尤作兵伐黄帝，黄帝乃令应龙攻之冀州之野。应龙畜水。蚩尤请风伯雨师，纵大风雨。黄帝乃下天女曰魃，雨止，遂杀蚩尤。魃不得复上，所居不雨。叔均言之帝，后置之赤水之北。叔均乃为田祖。魃时亡之，所欲逐之者，令曰：“神北行！”先除水道，决通沟渎。
有人方食鱼，名曰深目民之国，盼姓，食鱼。
有钟山者。有女子衣青衣，名曰赤水女子献。
大荒之中。有山名曰融父山，顺水入焉。有人名曰犬戎。黄帝生苗龙，苗龙，苗龙生融吾，融吾生弄明，弄明生白犬，白犬有牝牡，是为犬戎，肉食。有赤兽，马状无首，名曰戎宣王尸。
有山名曰齐州之山、君山、【上两先下鬲】山、鲜野山、鱼山。
有人一目，当面中生。一曰是威姓，少昊之子，食黍。
有继无民，继无民任姓，无骨子，食气、鱼。
西北海外，流沙之东，有国曰中【车扁】，颛顼之子。
有国名曰赖丘。有犬戎国。有神，人面兽身，名曰犬戎。
西北海外，黑水之北，有人有翼，名曰苗民。颛顼生欢头，欢头生苗民，苗民厘姓，食肉。有山名曰章山。
大荒之中，有衡石山、九阴山、洞野之山，上有赤树，青叶赤华，名曰若木。
有牛黎之国。有人无骨，儋耳之子。
西北海之外，赤水之北，有章尾山。有神，人面蛇身而赤，直目正乘，其瞑乃晦，其视乃明，不食不寝不息，风雨是谒。是烛九阴，是烛龙。 ', '', '', '（凡■为打不出来的字）竹林的南面有红色的湖水，名叫封渊。有三棵不生长枝条的桑树，都高达一百仞。卫丘的西面有个沉渊，是帝颛顼洗澡的地方。有个胡不与国，这里的人姓烈，吃黄米。大荒当中，有座山名叫不咸山。有个肃慎氏国。有一种能飞的蛭，长着四只翅膀。有一种蛇，是野兽的脑袋蛇的身子，名叫琴虫。有一种人名叫大人。有个大人国，这里的人姓厘，吃黄米。有一种大青蛇，黄色的脑袋，能吞食大鹿。有座榆山。又有座鲧攻程州山。大荒当中，有座山名叫衡天。又有座先民山。有一棵盘旋弯曲一千里的大树。有个叔歜国，这里的人都是颛顼的子孙后代，吃黄米，能驯化驱使四种野兽：老虎、豹子、熊和罴。有一种形状与熊相似的黑虫，名叫猎猎。有个北齐国，这里的人姓姜，能驯化驱使老虎、豹子、熊和罴。 大荒当中，有座山名叫先槛大逢山，是黄河水和济水流入的地方，海水从北面灌注到这里。它的西边也有座山，名叫禹所积石山。有座阳山。又有座顺山，顺水从这座山发源。有个始州国，国中有座丹山。有一大泽方圆千里，是各种禽鸟脱去旧羽毛再生新羽毛的地方。有个毛民国，这里的人姓依，吃黄米，能驯化驱使四种野兽。　
　　大禹生了均国，均国生了役采，役采生了修鞈，修鞈杀了绰人。大禹哀念绰人被杀，暗地里帮绰人的子孙后代建成国家，就是这个毛民国。有个儋耳国，这里的人姓任，是神人禺号的子孙后代，吃谷米。在北海的岛屿上，有一个神人，长着人的面孔鸟的身子，耳朵上穿挂着两条青色蛇，脚底下踩踏着两条红色蛇，名叫禺强。大荒当中，有座山名叫北极天柜山，海水从北面灌注到这里。　有一个神人，长着九个脑袋和人的面孔鸟的身子，名叫九凤。又有一个神人，嘴里衔着蛇手中握着蛇，他的形貌是老虎的脑袋人的身子，有四只蹄子和长长的臂肘，这名叫强良。 大荒当中，有座山名叫成都载天山。有一个人的耳上穿挂着两条黄色蛇，手上握着两条黄色蛇，名叫夸父。后土生了信，信生了夸父。而夸父不衡量自己的体力，想要追赶太阳的光影，直追到禺谷。夸父想喝了黄河水解渴，却不够喝，准备跑到北方去喝大泽的水，还未到，便渴死在这里了。应龙在杀了蚩尤以后，又杀了夸父，因他的神力耗尽上不了天就去南方居住，所以南方的雨水很多。又有个无肠国，这里的人姓任。他们是无继国人的子孙后代，吃鱼类。共工有一位臣子名叫相繇，长了九个头而是蛇的身子，盘旋自绕成一团，贪婪地霸占九座神山而索取食物。他所喷吐停留过的地方，立即变成大沼泽，而气味不是辛辣就是很苦，百兽中没有能居住这里的。大禹堵塞洪水，杀死了相繇，而相繇的血又腥又臭，使谷物不能生长；那地方又水涝成灾，使人不能居住。大禹填塞它，屡次填塞而屡次塌陷，于是把它挖成大池子，诸帝就利用挖出的泥土建造了几座高台。诸帝台位于昆仑山的北面。有座岳山，一种高大的竹子生长在这座山上。 大荒当中，有座山名叫不句山，海水从北面灌注到这里。有座山叫系昆山，上面有共工台，射箭的人因敬畏共工的威灵而不敢朝北方拉弓射箭。有一个人穿着青色衣服，名叫黄帝女妭。蚩尤制造了多种兵器用来攻击黄帝，黄帝便派应龙到冀州的原野去攻打蚩尤。应龙积蓄了很多水，而蚩尤请来风伯和雨师，纵起一场大风雨。黄帝就降下名叫妭的天女助战，雨被止住，于是杀死蚩尤。女妭因神力耗尽而不能再回到天上，她居住的地方没有一点雨水。叔均将此事禀报给黄帝，后来黄帝就把女妭安置在赤水的北面。叔均便做了田神。女妭常常逃亡而出现旱情，要想驱逐她，便祷告说：“神啊请向北去吧！”事先清除水道，疏通大小沟渠。有一群人正在吃鱼，名叫深目民国，这里的人姓朌，吃鱼类。 有座钟山。有一个穿青色衣服的女子，名叫赤水女子魃。荒当中，有座山名叫融父山，顺水流入这座山。有一种人名叫犬戎。黄帝生了苗龙，苗龙生了融吾，融吾生了弄明，弄明生了白犬，这白犬有一公一母而自相配偶，便生成犬戎族人，吃肉类食物。有一种红颜色的野兽，形状像普通的马却没有脑袋，名叫戎宣王尸。有几座山分别叫做齐州山、君山、■山、鲜野山、鱼山。一种人长着一只眼睛，这只眼睛正长在脸面的中间。一种说法认为他们姓威，是少昊的子孙后代，吃黄米。有一种人称作无继民，无继民姓任，是无骨民的子孙后代，吃的是空气和鱼类。 在西北方的海外，流沙的东面，有个国家叫中■国，这里的人是颛顼的子孙后代，吃黄米。有个国家名叫赖丘。还有个犬戎国。有一种人，长着人的面孔兽的身子，名叫犬戎。在西北方的海外，黑水的北岸，有一种人长着翅膀，名叫苗民。颛顼生了欢头，欢头生了苗民，苗民人姓厘，吃的是肉类食物。还有一座山名叫章山。大荒当中，有衡石山，九阴山、灰野山，山上有一种红颜色的树木，青色的叶子红色的花朵，名叫若木。有个牛黎国。这里的人身上没有骨头，是儋耳国人的子孙后代。在西北方的海外，赤水的北岸，有座章尾山。有一个神人，长着人的面孔蛇的身子而全身是红色，身子长达一千里，竖立生长的眼睛正中合成一条缝，他闭上眼睛就是黑夜、睁开眼睛就是白昼，不吃饭不睡觉不呼吸，可以呼风唤雨。他能照耀阴暗的地方，所以称作烛龙。', NULL, '', 'indent', 1522506214, '5abf295c9f54543001f86e6c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642078, '幽梦影 · 卷一 · 四十七', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '物之穉者，皆不可厌。为驴独否。', '', '穉：同“稚”。', '', NULL, '倪永清曰：惟癖于驴者，则不厌之。', 'indent', 1556016723, '5cbe7dd2a3180b7832e6ce4c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636873, '战国策 · 赵威后问齐使', NULL, 6, 49, 0, 1, '刘向', NULL, 18105, '58540cde8e450a006c5803d4', '汉', 'wen', '文', 'https://baike.baidu.com/item/赵威后问齐使/7806672?fr=aladdin', '', '齐王使使者问赵威后。书未发，威后问使者曰：“岁亦无恙耶？民亦无恙耶？王亦无恙耶？”使者不说，曰：“臣奉使使威后，今不问王而先问岁与民，岂先贱而后尊贵者乎？”威后曰：“不然，苟无岁，何以有民？苟无民，何以有君？故有舍本而问末者耶？”
乃进而问之曰：“齐有处士曰钟离子，无恙耶？是其为人也，有粮者亦食，无粮者亦食；有衣者亦衣，无衣者亦衣。是助王养其民也，何以至今不业也？叶阳子无恙乎？是其为人，哀鳏寡，恤孤独，振困穷，补不足。是助王息其民者也，何以至今不业也？北宫之女婴儿子无恙耶？彻其环瑱，至老不嫁，以养父母。是皆率民而出于孝情者也，胡为至今不朝也？此二士弗业，一女不朝，何以王齐国，子万民乎？於陵子仲尚存乎？是其为人也，上不臣于王，下不治其家，中不索交诸侯。此率民而出于无用者，何为至今不杀乎？”', '《赵威后问齐使》出自《战国策·齐策》，赵威后即赵太后，惠文王之妻。她虽然年事已高，但对国家政治的清明有着最朴素的理解，她仅仅从国家对个别人才的褒贬任用上就指出了齐王治国政策弊端，虽然简单但却很有道理。本文通过赵威后的连续七问，都是围绕一个“民”字，表现了这位女政治家治国应该以民为本的思想，这是春秋战国时期的一种进步思想。', '齐王：战国时齐王建，齐襄王之子。赵威后：战国时赵惠文王妻。惠文王死，其子孝成王立，因年幼由威后执政。
发：启封。
岁亦无恙耶：收成还好吧？岁，收成。亦，语助词，无义。无恙，无忧，犹言“平安无事”。
说：通“悦”。
奉使使威后：奉使命出使到威后这里来。
苟：假如。
处士：有才能、有道德而隐居不仕的人。钟离子：齐国处士。钟离，复姓。子，古时对男子的尊称。
食（sì）：拿食物给人吃。
衣（yì）：拿衣服给人穿。
不业：不做官以成就他的功业。
叶（shè）阳子：齐国处士，叶阳，复姓。
鳏（guān）：老而无妻。
恤：抚恤。独，老而无子。
振：通“赈”，救济。
息：繁育。
16：、北宫之女婴儿子：北宫氏的女子婴儿子。北宫，复姓。婴儿子是人名。
彻：通“撤”，除去。环：指耳环、臂环一类的饰物。瑱：一种玉制的耳饰。
是皆率民而出于孝情者也：这些都是带领百姓行孝的行为。
不朝：不使她上朝。古时夫人受封而有封号者为“命妇”，命妇即可入朝。此句意即，为什么至今不封婴儿子为命妇，使她得以上朝见君呢？
子万民：以万民为子女，犹言“为民父母”。
于（wū）陵子仲：齐国的隐士。於陵：齐邑名，故城在今山东省长山县西南。
索：求。', '齐国国王派遣使者去问候赵威后，书信还没有启封，威后就问使者说：“今年的年成好吗？老百姓好吗？齐王好吗？”使者不高兴，说：“下臣奉齐王的使命，出使到威后这里来，现在您不问齐王，反而先问年成和百姓，岂不是把贱的放在前面，把尊贵的放在后面吗？”威后说：“不是这样。假如没有收成，哪里有百姓？假如没有百姓，哪里有国君？因而有所问，能不问根本而问末节的吗？”
威后进而又问他说：“齐国有个处士叫钟离子，平安无事吗？这个人做人呀，有粮食的人给吃，没粮食的人也给吃；有衣服的人给穿，没有衣服的人也给穿。这是帮助国君抚养老百姓的人呀，为什么到今天不让他在位成就功业？叶阳子平安无事吗？这个人做人呀，怜悯那些无妻无夫的人，顾念抚恤那些无父无子的人，救济那些困苦贫穷的人，补助那些缺衣少食的人，这是帮助国君养育百姓的人，为什么到今天不让他在位成就功业？北宫氏的女儿婴儿子平安无事吗？她摘掉耳环等装饰品，到老不嫁，来奉养父母。这是带领百姓尽孝心的人，为什么到今天还不让她上朝呢？这两个处士没有成就功业，一个孝女也不上朝，靠什么来统治齐国，做百姓的父母呢？於陵的那个子仲还在吗？这个人做人呀，对上不向国君称臣，对下不治理他的家，也不愿同诸侯交往，这是带领百姓无所作为的人，为什么到今天还不杀掉呢？', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d00f8fda5565061577", "shortContent": "赵威后是赵惠文王之妻，赵孝成王之母。公元前266年惠文王卒，子孝成王立，以其年幼，故由赵威后执政。本文就是记叙赵威后接见齐国使者的一次谈话。\n文章之奇，在于通篇只是记言。既无一句人物外貌、举止、行为、心态之类的描写，也无任何环境烘托或细节刻画，只紧扣题目中一个“问”字，主要写赵威后的七次提问，就鲜明而传神地勾画出一位洞悉别国政治民情、明察贤愚是非、具有高度民本主义思想的女政治家形象。写七问又非一气...", "authors": ["熊", "笃"], "pressName": "上海辞书出版社"}]', '清金圣叹《天下才子必读书》卷四：章法越整齐、越参差；越参差，越整齐；真可谓奇绝之文！
清林云铭《古文析义》卷五：篇中直问到底，意庄而词甚婉，读之，惟见威后灵心慧舌满纸飞动而已。
清吴楚材、吴调侯《古文观止》卷四：通篇以民为主，直问到底，而文法各变，全于用虚字处著神。问固奇，而心亦热。末一问，胆识尤自过人。
清余诚《重订古文释义新编》卷三：益民为邦本，必得休养生息，趋于善而勿流为无用。王万可以无恙，然则威后之重民，非不以重王耶！至行文之妙，纯是一片灵机缭绕，飞舞团结而成，故笔调之参差，局阵之严整，气韵之萧疏，丰神之超逸，迥异寻常，其殆入化境矣。
清高嵣《国策钞》卷上：民为治本，岁关民，君恃民。此前三问意也。后四问，皆有关于民事者，故连及之，晋人假清疏以长傲。其弊中于伪儒，於陵一问，其识尤远。通篇俱叙问词，共七问，凡三法。错落疏古，自成局段。俞桐川云：亦英雄，亦道学，亦风流。
清唐德宜《古文翼》卷三：前一问深得民惟邦本意，后一问深得为政在人意。不料战国时母后有如许大学问。', 'indent', 1522507400, '5abf2e06ac502e0063a872c8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636874, '战国策 · 鲁仲连义不帝秦', NULL, 7, 49, 0, 1, '刘向', NULL, 18105, '58540cde8e450a006c5803d4', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E9%B2%81%E4%BB%B2%E8%BF%9E%E4%B9%89%E4%B8%8D%E5%B8%9D%E7%A7%A6/7903904?fr=aladdin', '', '秦围赵之邯郸，魏安釐王使将军晋鄙救赵，畏秦，止于荡阴，不进。魏王使客将军辛垣衍间入邯郸，因平原君谓赵王曰：「秦所以急围赵者，前与齐闵王争强为帝，已而复归帝，以齐故。今齐闵王益弱，方今唯秦雄天下，此非必贪邯郸，其意欲求为帝。赵诚发使尊秦昭王为帝，秦必喜，罢兵去。」平原君犹豫，未有所决。
此时鲁仲连适游赵，会秦围赵，闻魏将欲令赵尊秦为帝，乃见平原君，曰：「事将奈何矣？」平原君日：「胜也何敢言事，百万之众折于外，今又内围邯郸而不去。魏王使客将军辛垣衍令赵帝秦，今其人在是。胜也何敢言事！」鲁连曰：「始吾以君为天下之贤公子也，吾乃今然后知君非天下之贤公子也。梁客辛垣衍安在？吾请为君责而归之。」平原君曰：「胜请为召而见之于先生。」
平原君遂见辛垣衍曰：「东国有鲁连先生，其人在此，胜请为绍介，而见之于将军。」辛垣衍曰：「吾闻鲁连先生，齐国之高士也；衍，人臣也，使事有职，吾不愿见鲁连先生也。」平原曰：「胜已泄之矣！」辛垣衍许诺。
鲁连见辛垣衍而无言。辛垣衍曰：「吾视居此围城之中者，皆有求于平原君者也。今吾视先生之玉貌，非有求于平原君者，曷为久居此围城之中而不去也？」鲁连曰：「世以鲍焦无从容而死者，皆非也。今众人不知，则为一身。彼秦，弃礼义而上首功之国也，权使其士，虏使其民，彼则肆然而为帝，过而遂正于天下，则连有赴东海而死耳，吾不忍为之民也！所为见将军者，欲以助赵也。」辛垣衍曰：「先生助之奈何？」鲁连曰：「吾将使梁及燕助之，齐楚固助之矣。」辛垣衍曰：「燕则吾请以从矣；若乃梁，则吾乃梁人也，先生恶能使梁助之耶？」鲁连曰：「梁未睹秦称帝之害故也；使梁睹秦称帝之害，则必助赵矣。」辛垣衍曰：「秦称帝之害将奈何？」鲁仲连曰：「昔齐威王尝为仁义矣，率天下诸侯而朝周，周贫且微，诸侯莫朝，而齐独朝之。居岁馀，周烈王崩，诸侯皆吊，齐后往。周怒，赴于齐曰：『天崩地坼，天子下席；东藩之臣田婴齐后至，则斫之！』威王勃然怒日：『叱嗟！而母婢也！』卒为天下笑。故生则朝周，死则叱之，诚不忍其求也。彼天子固然，其无足怪。」
辛垣衍曰：「先生独未见夫仆乎？十人而从一人者，宁力不胜，智不若邪？畏之也！」鲁仲连曰：「然梁之比于秦，若仆邪？」辛垣衍曰：「然！」鲁仲连曰：「然则吾将使秦王烹醢梁王。」辛垣衍怏然不说，曰：「嘻！亦太甚矣，先生之言也！先生又恶能使秦王烹醢梁王？」鲁仲连曰：「固也！待吾言之。昔者鬼侯、鄂侯、文王，纣之三公也。鬼侯有子而好，故入之于纣，纣以为恶，醢鬼侯。鄂侯争之急，辨之疾，故脯鄂侯。文王闻之，喟然而叹，故拘之于牖里之库百日，而欲令之死。曷为与人俱称帝王，卒就脯醢之地也？
「齐闵王将之鲁，夷维子执策而从，谓鲁人曰：『子将何以待吾君？』鲁人曰：『吾将以十太牢待子之君。』夷维子曰：『子安取礼而来待吾君？彼吾君者，天子也。天子巡狩，诸侯辟舍，纳管键，摄衽抱几，视膳于堂下，天子已食，而听退朝也。』鲁人投其钥，不果纳，不得入于鲁。将之薛，假涂于邹。当是时，邹君死，闵王欲入吊，夷维子谓邹之孤曰：『天子吊，主人必将倍殡柩，设北面于南方；然后天子南面吊也。』邹之群臣曰：『必若此，吾将伏剑而死！』故不敢入于邹。邹鲁之臣，生则不得事养，死则不得饭含，然且欲行天子之礼于邹、鲁之臣，不果纳。今秦万乘之国，梁亦万乘之国，交有称王之名。睹其一战而胜，欲从而帝之，是使三晋之大臣，不如邹、鲁之仆妾也。且秦无已而帝，则且变易诸侯之大臣，彼将夺其所谓不肖，而予其所谓贤；夺其所憎，而予其所爱。彼又将使其子女谗妾，为诸侯妃姬，处梁之宫，梁王安得晏然而已乎？而将军又何以得故宠乎？」
于是辛垣衍起，再拜，谢曰：「始以先生为庸人，吾乃今日而知先生为天下之士也！吾请去，不敢复言帝秦！」
秦将闻之，为却军五十里。适会公子无忌夺晋鄙军以救赵击秦，秦军引而去。于是平原君欲封鲁仲连，鲁仲连辞让者三，终不肯受。平原君乃置酒，酒酣，起前以千金为鲁连寿。鲁连笑日：「所贵于天下之士者，为人排患释难、解纷乱而无所取也。即有所取者，是商贾之人也，仲连不忍为也！」遂辞平原君而去，终身不复见。', '本文选自《战国策·赵策》。本文所记的是齐国人鲁仲连游历到赵，适逢秦国围赵之邯郸，鲁仲连坚持正义，力主抗秦，反对投降，并和秦国派到赵国的「亲秦派」辛垣衍展开一场激烈的论争。他引喻设比，层层铺垫，直陈要害，最终使辛垣衍心服口服，恰逢魏无忌援军到，从而解了邯郸之围。本文记叙和议论相结合，条理清晰，语言简洁有力，反复剖析，层层深入，曲折生动，引人人胜。', '鲁仲连：齐国的高士。姓鲁名连。一生不做官，好为人排难解纷。
不帝秦：不肯尊称秦王为帝。事见《史记·鲁仲连邹阳列传》。
邯郸（hándān）：赵国首都，在今河北省邯郸市。
魏安釐（xī）王：魏国国君，魏昭王子，信陵君无忌的异母兄，名圉（yǔ）。周郝王三十九年（西元前二七六年）至秦嬴政四年（西元前二四三年）在位。
晋鄙：魏国大将。晋鄙救赵事见《史记·魏公子列传》。
荡阴：当时赵、魏两国交界的地方，在今河南汤阴县。
客将军：别国人在魏国做将军称为客将军。
辛垣衍：人名，辛垣是复姓。
间人（jiàn）：趁围困不紧时偷偷地进入。
因：经由；通过。
平原君：赵氏，名胜，赵武王子，赵孝成王叔，封平原君，战国四公子之一。时任赵相。
赵王：赵孝成王，名丹。周郝王三十九年（西元前二六五年）至秦嬴政二年（西元前二四五年）在位。
「前与」三句：按周赧王二十七年（西元前二八八年），齐闵王称东帝，秦昭王称西帝。后来苏代说服齐闵王废除帝号，闵王从之，秦国也随着取消帝号。已而，不久，过后。归帝，归还帝号。指秦取消帝号。以齐故，因为齐王不称帝的缘故。因苏代劝齐闵王先取消了帝号，秦昭王因之也跟着取消了帝号，所以说「以齐故」。
今齐闵王益弱：周赧王三十一年（西元前二八四年）燕将乐毅同楚、韩、魏、燕、赵五国伐齐，齐国大败，齐闵王也在这次战争中死去。到了秦围邯郸时，齐闵王已死了二十馀年。吴师道认为这句可解释为「今之齐，视闵王已益弱」。意思是说「今天的齐国比起闵王时已更加衰弱」。方今：现在。雄：称雄。
诚：真。这里作「假设」解。
秦昭王：秦王赢稷，周赧王三十一年（西元前三〇六年）至秦昭襄王五十六年（西元前二五一年）在位。
百万之众折于外：这句指赵孝成王六年（西元前二六〇年），秦将白起大破赵军于长平（在今山西高平县西北），坑杀赵降卒四十馀万。事见《史记·赵世家》。
内：深入国内。
梁：魏迁都大梁（今河南开封）后又称梁。
安在：在哪里。安，哪里，疑问代词。
归之：使之归，即叫他回去。
东国：指齐国。因齐在赵的东方，故称东国。
高士：道德品行高尚而不做官的读书人。
泄：泄露。这里是「告诉」的意思。鲍彪注：「泄，言已白之。」之：指辛垣衍到赵国这件事。
曷为（hé）：为何。曷，何，疑问代词。
「世以」句：大意是说世人中凡是认为鲍焦由于心地狭隘而死的那些人都不对。鲁连说这句话，在于说明他自己不是为个人打算的。以，以为，认为。鲍焦，周时隐士，相传他不愿为诸侯帝王效忠，以采樵及拾橡实为生，后抱木饿死。无从容，指心地狭隘。从容，指胸襟宽大，有度量。
上首功：即崇尚战功。上，同「尚」，崇尚，注重。「上」前原选本无「而」字，今据上海古籍出版社《战国策》汇校本补。首功，斩首之功。当时以斩杀敌人首级的数目多少计算战功。秦国的制度，分爵位二十级，作战时斩得敌人的头颅越多爵位越高。
肆然：放肆地，无所忌惮地。
过：进一步。正：同「政」，指用政治力量控制。
有：含「只有」的意思。
赴：奔向。
若乃：至于。
恶（wū）：怎么。
齐威王：田氏，名婴齐，一作因齐。桓公子。在位三十六年（西元前三五六年至西元前三二〇年），改革政治，国力渐强。
为仁义：行仁义。微：弱小。
居岁馀：过了一年多的时问。
周烈王：名喜，在位七年（西元前三七五年至西元前三六九年）。
崩：封建时代帝王死的专称。
赴：同「讣」。使人奔告丧事，即报丧。
天崩地坼（chè）：比喻天子死。坼，裂开。
天子：指继承烈王的新君显王（名扁）。
下席：古时孝子守孝时，要离开宫室，寝于苫（草名）席之上。
东藩：位于东方的藩国。指齐国。「藩」的本义是「篱笆」，引申为「屏蔽」的意思。古代封建诸侯，为的是屏藩王室，所以称诸侯为藩国。齐国在东方，故称东藩。田婴齐：齐威王的姓名。
斫：砍，斩。
勃然：因生气而变脸色的样子。
叱嗟（chìjiē）：怒斥声。而：汝，你。
婢：侍婢。这句是齐威王骂周王的话。
生：指周烈王活着的时候。
朝：朝拜。
死：指周烈王死了以后。
忍：忍受。
求：苛求。
固然：本来这样。
醢（hǎi）：剁肉成酱。烹、醢都是古代的酷刑。
怏然（yàng）：郁郁不欢的样子。
「亦太甚」二句：主语部分是「先生之言」，谓语部分是「亦太甚」。谓语前置表示强烈的感叹语气。
「昔者」句：鬼侯、鄂侯、文王都是纣王封的三公。鬼侯的封地在今河南临漳县境。鄂侯的封地在今山西中阳县境。文王就是周文王，他的封地在今陕西鄂县一带。
公：这里指诸侯。
子：指女儿。在上古时代，「子」本是男女的通称。
好：貌美。
入：进献；献纳。
恶（è）：丑。
辨：通「辩」。疾：急。
脯（fǔ）：乾肉。这里用作动词，作成肉乾。
喟然（kuì）：叹气的样子。
牖里（yǒu）：一作「羡里」，古地名。在今河南汤阴县北。
库：监牢。
「曷为与人俱称帝王，卒就脯醢之地也」句：梁和秦本来都是称王的平等国家，现在梁国为什么要自居卑下受人宰割呢？曷，何。人，指秦。
齐闵王将之鲁：齐闵王四十年，燕将乐毅合五国之兵破齐，闵王逃到卫国，因态度傲慢没有被接纳，于是离开卫国要到鲁国去。
夷维子：齐人，以邑为姓。夷维，地名，今山东潍县。子，男子的美称。
策：马鞭。
太牢：牛羊猪各一称太牢。十太牢，就是牛羊猪各十隻。这是款待诸侯的礼节。
安取礼：何取礼，即选用什么礼节。安，疑问代词，哪里。因夷维子要鲁人用天子的礼节来款待闵王，所以表示不满，提出质问。
巡狩（shòu）：天子到各诸侯国视察。诸侯辟舍：天子到诸侯国中巡狩时，诸侯要离开自己的正殿不居。辟，同「避」，回避，离开。原选本作「避」，今据上海古籍出版社《战国策》排印本改。舍，指正房。
纳：交纳。
管键：钥匙。避舍、纳管键，是表示诸侯因天子在自己国中，自己在此期间不敢以一国之主自居。
衽（rèn）：衣襟。抱：捧。几：矮或小的桌子。视膳：伺候别人吃饭。
而听退朝：当作「退而听朝」。
鲁人投其筲：鲁人闭关下锁，不接纳齐王入境。筲，同「钥」。投筲，下锁。
果：表示事情和预料或期望相合。常与「不」连用表示否定。纳：使入。
薛：古国名。任姓，祖先奚仲做夏代的车正，传为车的创造者，居于薛（今山东滕县南）。一度迁于邳（今山东微山西北）。春秋后期薛国迁到下邳（今江苏邳县西南），薛成为齐邑。
假：借。
涂：通，「途」。
邹：小国名。在今山东邹县。
孤：父亲死了，儿女叫孤。这里指邹国的新君。
吊：哀悼死者，慰问丧家。
倍殡柩：把灵柩移到相反的方向就是移到南面。古代以坐北向南为正位。灵柩本来坐北朝南，因为天子下吊必须朝南，因此要把灵柩掉过头来，设一个向北的灵堂。倍，同「背」。殡，停丧。柩，已盛尸体的棺材。
伏剑而死：用剑自刎而死。这是委婉的说法，实际是表示坚决拒绝。伏，受。
事养：侍奉，供养。
饭含：把米放在死人口中叫饭，把玉放在死人口中叫含。
「生则」四句的意思是：邹、鲁国势已很微弱，国君生时，臣子们不能侍奉供养，国君死后，也不能行饭含之礼；然而当齐国叫他们向齐国行天子的礼节时，还是行不通。邹、鲁两国的臣子们还是有骨气的。
万乘之国：能出一万辆兵车的国家是大国。
交：互相；彼此。
三晋：韩、魏、赵三国是由晋国分裂而成的诸侯国，故称韩、赵、魏为三晋。这里主要指赵、魏而言，特别是指辛垣衍。
仆妾：指臣子。
无已：没有止境。
帝：用作动词，称帝。
且：将。变易：更换，撤换。予：给。
子女：这里偏指女。
谗妾：善于进谗言、毁贤嫉能的妾妇。
处：住。
晏然：平安地。
故宠：旧日的尊荣地位，指魏王对辛垣衍原有的宠幸。
适会：恰巧赶上。
公子无忌：即信陵君，魏昭王的少子，安嫠王的异母弟，战国时著名的四公子之一。他托魏王的爱妾如姬盗出兵符，假传魏王的命令，杀了晋鄙，夺得晋鄙的军队，击退秦军，救了赵国。事见《史记·魏公子列传》。
置酒：设置酒宴。
商贾（gǔ）：商人的统称。古代以贩卖货物者为商，藏货代卖者为贾。', '赵孝成王时，秦王派白起在长平前后击溃赵国四十万军队，于是，秦国的军队向东挺进，围困了邯郸。赵王很害怕，各国的救兵也没有谁敢攻击秦军。魏安釐王派出将军晋鄙营救赵国，因为畏惧秦军，驻扎在汤阴不敢前进。魏王派客籍将军辛垣衍，从隐蔽的小路进入邯郸，通过平原君的关系见赵王说：「秦军所以急于围攻赵国，是因为以前和齐湣王争强称帝，不久又取消了帝号；如今齐国更加削弱，当今只有秦国称雄天下，这次围城并不是贪图邯郸，他的意图是要重新称帝。赵国果真能派遣使臣尊奉秦昭王为帝，秦王一定很高兴，就会撤兵离去。」平原君犹豫不能决断。这时，鲁仲连客游赵国，正赶上秦军围攻邯郸，听说魏国想要让赵国尊奉秦昭王称帝，就去进见平原君说：「这件事怎么办？」平原君说：「我哪里还敢谈论这样的大事！前不久，在国外损失了四十万大军，而今，秦军打到国内围困邯郸，又不能使之退兵。魏王派客籍将军辛垣衍让赵国尊奉秦昭王称帝，眼下，那个人还在这儿。我哪里还敢谈论这样的大事？」鲁仲连说：「以前我认为您是天下贤明的公子，今天我才知道您并不是天下贤明的公子。魏国的客人辛垣衍在哪儿？我替您去责问他并且让他回去。」平原君说：「我愿为您介绍，让他跟先生相见。」于是平原君见辛垣衍说：「齐国有位鲁仲连先生，如今他就在这儿，我愿替您介绍，跟将军认识认识。」辛垣衍说：「我听说鲁仲连先生，是齐国志行高尚的人。我是魏王的臣子，奉命出使身负职责，我不愿见鲁仲连先生。」平原君说：「我已经把您在这儿的消息透露了。」辛垣衍只好应允了。
鲁仲连见到辛垣衍却一言不发。辛垣衍说：「我看留在这座围城中的，都是有求于平原君的人；而今，我看先生的尊容，不像是有求于平原君的人，为什么还长久地留在这围城之中而不离去呢？」鲁仲连说：「世人认为鲍焦没有博大的胸怀而死去，这种看法都错了。一般人不了解他耻居浊世的心意，认为他是为个人打算。那秦国，是个抛弃礼仪而只崇尚战功的国家，用权诈之术对待士卒，像对待奴隶一样役使百姓。如果让它无所忌惮地恣意称帝，进而统治天下，那么，我只有跳进东海去死，我不忍心作它的顺民，我所以来见将军，是打算帮助赵国啊。」辛垣衍说：「先生怎么帮助赵国呢？」鲁仲连说：「我要请魏国和燕国帮助它，齐、楚两国本来就帮助赵国了。」辛垣衍说：「燕国嘛，我相信会听从您的；至于魏国，我就是魏国人，先生怎么能让魏国帮助赵国呢？」鲁仲连说：「魏国是因为没看清秦国称帝的祸患，才没帮助赵国。假如魏国看清秦国称帝的祸患后，就一定会帮助赵国。」
辛垣衍说：「秦国称帝后会有什么祸患呢？」鲁仲连说：「从前，齐威王曾经奉行仁义，率领天下诸侯而朝拜周天子。当时，周天子贫困又弱小，诸侯们没有谁去朝拜，唯有齐国去朝拜。过了一年多，周烈王逝世，齐王奔丧去迟了，新继位的周显王很生气，派人到齐国报丧说：『天子逝世，如同天崩地裂般的大事，新继位的天子也得离开宫殿居丧守孝，睡在草席上，东方属国之臣田婴齐居然敢迟到，当斩。』齐威王听了，勃然大怒，骂道：『呸！您母亲原先还是个婢女呢！』最终被天下传为笑柄。齐威王所以在周天子活着的时候去朝见，死了就破口大骂，实在是忍受不了新天子的苛求啊。那些作天子的本来就是这个样子，也没什么值得奇怪的。」
辛垣衍说：「先生难道没见过奴仆吗？十个奴仆侍奉一个主人，难道是力气赶不上、才智比不上他吗？是害怕他啊。」鲁仲连说：「唉！魏王和秦王相比魏王像仆人吗？」辛垣衍说：「是。」鲁仲连说：「那么，我就让秦王烹煮魏王剁成肉酱？」辛垣衍很不高兴不服气地说：「哼哼，先生的话，也太过分了！先生又怎么能让秦王烹煮了魏王剁成肉酱呢？」鲁仲连说：「当然能够，我说给您听。从前，九侯、鄂侯、文王是殷纣的三个诸侯。九侯有个女儿长得娇美，把她献给殷纣，殷纣认为她长得丑陋，把九侯剁成肉酱。鄂侯刚直诤谏，激烈辩白，又把鄂侯杀死做成肉乾。文王听到这件事，只是长长地叹息，殷纣又把他囚禁在牖里监牢内一百天，想要他死。为什么和人家同样称王，最终落到被剁成肉酱、做成肉乾的地步呢？齐湣王前往鲁国，夷维子替他赶着车子作随员。他对鲁国官员们说：『你们准备怎样接待我们国君？』鲁国官员们说：『我们打算用于副太牢的礼仪接待您的国君。』夷维子说：『你们这是按照哪来的礼仪接待我们国君，我那国君，是天子啊。天子到各国巡察，诸侯例应迁出正宫，移居别处，交出钥匙，撩起衣襟，安排几桌，站在堂下伺候天子用膳，天子吃完后，才可以退回朝堂听政理事。』鲁国官员听了，就关闭上锁，不让齐湣王入境。齐湣王不能进入鲁国，打算借道邹国前往薛地。正当这时，邹国国君逝世，齐湣王想入境吊丧，夷维子对邹国的嗣君说：『天子吊丧，丧主一定要把灵枢转换方向，在南面安放朝北的灵位，然后天子面向南吊丧。』邹国大臣们说：『一定要这样，我们宁愿用剑自杀。』所以齐湣王不敢进入邹国。邹、鲁两国的臣子，国君生前不能够好好地侍奉，国君死后又不能周备地助成丧仪，然而想要在邹、鲁行天子之礼，邹、鲁的臣子们终于拒绝齐湣王入境。如今，秦国是拥有万辆战车的国家，魏国也是拥有万辆战车的国家。都是万乘大国，又各有称王的名分，只看它打了一次胜仗，就要顺从地拥护它称帝，这就使得三晋的大臣比不上邹、鲁的奴仆、卑妾了。如果秦国贪心不足，终于称帝，那么，就会更换诸侯的大臣。他将要罢免他认为不肖的，换上他认为贤能的人，罢免他憎恶的，换上他所喜爱的人。还要让他的儿女和搬弄是非的姬妄，嫁给诸侯做妃姬，住在魏国的宫廷里，魏王怎么能够安安定定地生活呢？而将军您又怎么能够得到原先的宠信呢？」
于是，辛垣衍站起来，向鲁仲连连拜两次谢罪说：「当初认为先生是个普通的人，我今天才知道先生是天下杰出的高士。我将离开赵国，再不敢谈秦王称帝的事了。」秦军主将听到这个消息，为此把军队后撤了五十里。恰好魏公子无忌夺得了晋鄙的军权率领军队来援救赵国，攻击秦军，秦军也就撤离邯郸回去了。
于是平原君要封赏鲁仲连，鲁仲连再三辞让，最终也不肯接受。平原君就设宴招待他，喝道酒酣耳热时，平原君起身向前，献上千金酬谢鲁仲连。鲁仲连笑着说：「杰出之士之所以被天下人崇尚，是因为他们能替人排除祸患，消释灾难，解决纠纷而不取报酬。如果收取酬劳，那就成了生意人的行为，我鲁仲连是不忍心那样做的。」于是辞别平原君走了，终身不再相见。', '[{"bookId": "60fd4b9434bfda01e0eab209", "bookTitle": "唐宋小说鉴赏辞典", "articleId": "610f43e4911759740c9cb5f5", "shortContent": "“……（前阙）三公何处来？……（约阙十字）方员足。黄金何处无？我见在朝宰贵，皆从勤学□□□□□□□。远学三二年间，若不乘轩佩即（印），誓亦不还故乡。不依此□□□□□作粪土。”是言已讫，整顿容仪，行至堂前，叉手启娘曰：“儿闻古者司马相如，未学于□□山封达名而显；苏秦不学于鬼谷，六国之印不带不归。儿闻：‘学如牛毛，成如■（麟）角。’陈之典告（诰），不可一读即成；□□见家，不可一步而至。儿今辞娘，远学三...", "authors": ["柳岳梅"], "pressName": "上海辞书出版社"}]', '唐李白诗云：齐有倜傥生，鲁连特高妙。明月出海底，一朝开光耀。却秦振英声，后世仰末照。意轻千金赠，顾向平原笑。吾亦澹荡人，拂衣可同调。
宋真德秀《文章正宗》卷六：按鲁仲连之语，不皆粹以其反复言帝秦之害，有功于当时而雄俊明辩，可为论事之法，故取焉。
清徐乾学《古文渊鉴》卷八：不帝秦，大义也；辞封爵，高节也，责新垣衍处，风旨奕奕。
清徐乾学《古文渊鉴》卷八引岳颂评：秦雄视天下，已无一人不臣妾之。连独倡大义，使梁魏不复帝秦，锄强扶弱，至今凛然有生气。文之激昂慷慨，绝似连之为人。
清林云铭《古文析义》卷五：篇中一人热，一人冷；一人扬眉张目，一人垂头丧气；机锋相对，曲曲尽致。
清吴楚材、吴调侯《古文观止》卷四：帝秦之说，不过欲纾目前之急。不知秦称帝之害。其势不如鲁连所言不止、特人未之见耳。人知连之高义，不知连之远识也。至于辞封爵，挥千金，超然远引，终身不见，正如祥麟威风，可以偶觌，而不可常亲也。自是战国第一人。
清浦起龙《古文眉诠》卷十五：语皆切对帝字，写出不甘之意。鲁连心肠热，气岸高，固非游谈希宠一流，并不似颜斶王斗，一味傲僻。
清高嵣《国策钞》卷上引俞桐川评：自首至尾，皆浩然之气，读之真令顽廉懦立。东晋恨无其人。南宋得此意者。胡寅与谢枋得耳。节奏妙绝，波澜妙绝，《国策》第一篇文字。
清高嵣《国策钞》卷上：不帝泰，大义也。却封与全，高节也。战国时第一流人物。其议论风旨，自有俊伟光明一段气象。与当时游说希宠者迥异，必谓《国策》第一篇文字，抑所谓扬之则升天与！
周昙《全唐诗·春秋战国门·鲁仲连》：「昔迸烧牛发战机，夜奔惊火走燕师。今来跃马怀骄惰，十万如无一撮时。」', 'indent', 1522507511, '5abf2e74ac502e0063a875a4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636875, '卜居', NULL, 25, 31, 0, 1, '屈原', NULL, 10031, '57b90424d342d3005ac744af', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%8D%9C%E5%B1%85/2457577?fr=aladdin', '', '屈原既放，三年不得复见。竭知尽忠而蔽障于谗。心烦虑乱，不知所从。乃往见太卜郑詹尹曰：“余有所疑，愿因先生决之。”詹尹乃端策拂龟，曰：“君将何以教之？”
屈原曰：“吾宁悃悃款款，朴以忠乎，将送往劳来，斯无穷乎？宁诛锄草茅以力耕乎，将游大人以成名乎？宁正言不讳以危身乎，将从俗富贵以偷生乎？宁超然高举以保真乎，将哫訾栗斯，喔咿儒儿，以事妇人乎？宁廉洁正直以自清乎，将突梯滑稽，如脂如韦，以洁楹乎？宁昂昂若千里之驹乎，将泛泛若水中之凫，与波上下，偷以全吾躯乎？宁与骐骥亢轭乎，将随驽马之迹乎？宁与黄鹄比翼乎，将与鸡鹜争食乎？此孰吉孰凶？何去何从？世溷浊而不清：蝉翼为重，千钧为轻；黄钟毁弃，瓦釜雷鸣；谗人高张，贤士无名。吁嗟默默兮，谁知吾之廉贞！”
詹尹乃释策而谢曰：“夫尺有所短，寸有所长；物有所不足，智有所不明；数有所不逮，神有所不通。用君之心，行君之意。龟策诚不能知此事。”', '《卜居》是《楚辞》中的一篇文章。相传为屈原所作，而现代学者多以为是楚国人在屈原死后为了悼念他而记载下来的有关传说。文章表现了当时社会的黑暗腐败，反映了屈原的愤慨和不满，歌颂了他坚持真理、不愿同流合污的斗争精神。全文以屈原问卜开篇，以詹尹“释策而谢”的答语收结，中间以连珠式的对立设问的语句贯穿，文采斐然，往复盘旋，八对设问，一以贯之，气势充沛，感情强烈。虽铺陈夸饰，句式整齐，却不板不散，亦无重复之嫌。', '卜居：占卜自己该怎么处世。卜，占卜。居，处世的方法与态度。
放：放逐。
复见：指再见到楚王。
蔽障：遮蔽、阻挠。
太卜：掌管卜筮的官。
因：凭借。
端策：数计蓍草。端，数也。拂龟：拂去龟壳上的灰尘。
悃（kǔn）悃款款：诚实勤恳的样子。
送往劳来：送往迎来。劳，慰劳。
大人：指达官贵人。
偷生：贪生。
超然：高超的样子。高举：远走高飞。保真：保全真实的本性。
哫（zú）訾（zī）：以言献媚。栗斯：阿谀奉承状。栗，恭谨，恭敬。斯，语助词。
喔咿儒儿（ní）：强颜欢笑的样子。
妇人：指楚怀王的宠姬郑袖，她与朝中重臣上官大夫等人联合排挤馋毁屈原。
突梯：圆滑的样子。滑（gǔ）稽（jī）：一种能转注吐酒、终日不竭的酒器，后借以指应付无穷、善于迎合别人。
如脂如韦：谓像油脂一样光滑，像熟牛皮一样柔软，善于应付环境。
洁楹：度量屋柱，顺圆而转，形容处世的圆滑随俗。洁，借为“絜（xié）”，《楚辞补注》引《文选》亦作“絜”。
昂昂：昂首挺胸、堂堂正正的样子。
泛泛：漂浮不定的样子。凫（fú）：水鸟，即野鸭。一本此字下有一“乎”字。
亢（kàng）轭（è）：并驾而行。亢，同“伉”，并也。轭，车辕前端的横木。
驽（nú）马：劣马。
黄鹄（hú）：天鹅。
鹜（wù）：鸭子。
溷（hùn）浊：肮脏、污浊。
千钧：代表最重的东西。古制三十斤为一钧。
黄钟：古乐中十二律之一，是最响最宏大的声调。这里指声调合于黄钟律的大钟。
瓦釜（fǔ）：陶制的锅。这里代表鄙俗音乐。
高张：指坏人气焰嚣张，趾高气扬。
吁嗟：叹息声。
释：放下。谢：辞谢，拒绝。
数：卦数。逮：及，到。', '屈原被流放后，三年不能和楚王相见。他竭尽智慧效忠国家，却被谗言谤语把他和君王遮蔽阻隔。他心烦意乱，不知如何是好。于是去见太卜郑詹尹问卜说：“我对有些事疑惑不解，希望通过您的占卜帮助我分析判断。”郑詹尹就摆正蓍草、拂去龟甲上的灰尘，问道：“先生有何见教？”
屈原说：“我宁可诚恳朴实、忠心耿耿呢，还是迎来送往、巧于逢迎而摆脱困境？宁可垦荒锄草勤劳耕作呢，还是交游权贵而沽名钓誉？宁可毫无隐讳地直言为自己招祸呢，还是顺从世俗贪图富贵而苟且偷生？宁可鹤立鸡群而保持正直操守呢，还是阿谀逢迎、强颜欢笑以侍奉那位妇人？宁可廉洁正直以保持自己的清白呢，还是圆滑诡诈、油滑适俗、趋炎附势？宁可像志行高远的千里驹呢，还是像浮游的野鸭随波逐流而保全自身？宁可与骐骥并驾齐驱呢，还是追随那劣马的足迹？宁可与天鹅比翼高飞呢，还是同鸡鸭在地上争食？上述种种，哪个是吉哪个是凶，哪个该舍弃哪个该遵从？现在的世道混浊不清：认为蝉翼是重的，千钧是轻的；黄钟大吕竟遭毁弃，瓦釜陶罐却响如雷鸣；谗佞小人嚣张跋扈，贤明之士则默默无闻。唉，沉默吧，谁人能知我廉洁忠贞的心哪！”
郑詹尹于是放下蓍草抱歉地说：“尺比寸长但也有短处，寸比尺短却也有它的长处；世间万物都有不完善的地方，人的智慧也有不明了的时候；术数有占卜不到的事情，天神也有难解之理。您还是按照自己的心志，实行自己的主张吧。龟壳蓍草实在无法知道这些事啊！”', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf4f03572034f65a97f2", "shortContent": "关于《卜居》的作时与作地，王夫之《楚辞通释》云：“此盖怀王时去位居汉北事。”怀王二十四年屈原被放汉北。联系《离骚》中两写卜疑的情节看，应是反映了同样的心态与经历。蒋骥《山带阁注楚辞》也说：“详其词意，疑在怀王斥居汉北之日也。”“殆与《思美人》相近”。而怀王时被放汉北，楚故都鄢郢在其西北，也会有占卜之官。根据其开头“三年不得复见”之语，应作于怀王二十七年前后。作于《渔父》《抽思》《思美人》《招魂》《...", "authors": ["赵逵夫"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d3911759740c9bdc86", "shortContent": "《卜居》与《渔父》，都是楚人记述屈原生平轶事的奇妙之作。关于此文作者，王逸《楚辞章句》即指为“屈原之所作”；但同书与此文相近的《〈渔父〉题解》，又有“楚人思念屈原，因叙其辞以相传焉”之语。从明人张京元《删注楚辞》，即有怀疑此二文乃后人伪作之说。也许因为构成全文主体的，乃是屈子自己言论的缘故吧，后人往往又直指其作者为屈原。\n即使是伟大的志士，也并非总是心境开朗的。不妨这样说：正是由于他们的个人遭际，...", "authors": ["潘啸龙"], "pressName": "上海辞书出版社"}, {"bookId": "60fccb5034bfda01e0ea02ff", "bookTitle": "先秦诗鉴赏辞典（新一版）", "articleId": "610f375f03572034f65b3e06", "shortContent": "还是无休无止送往迎来八面玲珑？\n还是阿谀奉承屈己从俗，奴颜婢膝地取媚妇人？\n还是圆滑嬉笑，如油脂滑腻似熟皮柔能缠柱？\n还是像水中的野鸭飘浮不定随波逐流，苟且保全身躯？\n本篇究竟为谁所作，学术界有争议。自王逸《楚辞章句》明确地说“《卜居》者，屈原之所作也”之后，直到晚清，一般学者对此并无疑义。崔述《考古续说·观书余论》则对此说断然翻案：“《卜居》《渔父》，必非屈原之所作。”五四运动以来的《楚辞》研究...", "authors": ["伏俊连"], "pressName": "上海辞书出版社"}]', '宋代朱熹《楚辞集注》：“屈原哀悯当世之人习安邪佞、违背正直，故阳为不知二者之是非可否，而将假蓍龟以决之，遂为此词，发其取舍之端，以警世俗。”
明代王世贞《艺苑卮言》：“《卜居》《渔父》便是赤壁诸公作俑，作法于谅，令人永概。”
明代许学夷《诗源辨体》：“屈原《卜居》，思若涌泉，文如贯珠，妙不容言。”', 'indent', 1522507642, '5abf2ef99f54543001f89715', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636910, '鬼谷子 · 捭阖', NULL, 35, 12, 0, 1, '鬼谷子', NULL, 36905, '5ac1d6fd9f5454300106d692', '周', 'wen', '文', 'https://baike.baidu.com/item/鬼谷子·捭阖/19832367', '', '粤若稽古，圣人之在天地间也，为众生之先。观阴阳之开阖以命物，知存亡之门户，筹策万类之终始，达人心之理，见变化之朕焉，而守司其门户。故圣人之在天下也，自古至今，其道一也。变化无穷，各有所归。或阴或阳，或柔或刚，或开或闭，或弛或张。
是故圣人一守司其门户，审察其所先后，度权量能，校其伎巧短长。夫贤、不肖、智、愚、勇、怯，有差，乃可捭，乃可阖；乃可进，乃可退；乃可贱，乃可贵：无为以牧之。审定有无与其实虚，随其嗜欲以见其志意，微排其所言，而捭反之，以求其实，实得其指，阖而捭之，以求其利。或开而示之，或阖而闭之。开而示之者，同其情也；阖而闭之者，异其诚也。可与不可，明审其计谋，以原其同异。离合有守，先从其志。
即欲捭之贵周，即欲阖之贵密。周密之贵微，而与道相追。捭之者，料其情也；阖之者，结其诚也。皆见其权衡轻重，乃为之度数，圣人因而为之虑。其不中权衡度数，圣人因而自为之虑。故捭者，或捭而出之，或捭而纳之；阖者，或阖而取之，或阖而去之。捭阖者，天地之道。捭阖者，以变动阴阳，四时开闭，以化万物。纵横、反出、反覆、反忤必由此矣。
捭阖者，道之大化，说之变也；必豫审其变化，吉凶大命系焉。口者，心之门户也；心者，神之主也。志意、喜欲、思虑、智谋，此皆由门户出入，故关之以捭阖，制之以出入。捭之者，开也、言也、阳也；阖之者，闭也，谋也、阴也。阴阳其和，终始其义。故言长生、安乐、富贵、尊荣、显名、爱好、财利、得意、喜欲为阳，曰「始」。故言死亡，忧患、贫贱、苦辱、弃损、亡利、失意、有害、刑戮、诛罚为阴，曰「终」。诸言法阳之类者，皆曰「始」，言善以始其事；诸言法阴之类者，皆曰「终」，言恶以终其谋。
捭阖之道，以阴阳试之，故与阳言者依崇高，与阴言者依卑小。以下求小，以高求大。由此言之，无所不出，无所不入，无所不可。可以说人，可以说家，可以说国，可以说天下。为小无内，为大无外。益损、去就、倍反，皆以阴阳御其事。阳动而行，阴止而藏；阳动而出，阴随而入。阳还终始，阴极反阳。以阳动者，德相生也；以阴静者、形相成也。以阳求阴，苞以德也；以阴结阳，施以力也；阴阳相求，由捭阖也。此天地阴阳之道，而说人之法也，为万事之先，是谓「圆方之门户」。', '《鬼谷子·捭阖》是春秋时期纵横家鬼谷子创作的一篇散文。捭为开启，阖为闭藏。捭阖之术，也就是开合有道、张弛有度。捭阖之术是世间万物运转的根本，也是纵横家游说的重要说术言略。', '捭：开的意思，敞开心怀积极行动，采取攻势，或接受外部事物及他人的主张和建议。
阖，闭的意思，关闭心扉，把进来的事物化为自己的事物，或不让外来事物进入，取封闭形态。
粤若稽古，粤，语助词。若，顺；稽，考察。意为按着一定的规律考察历史。
先：先知先觉，此意指尊者，指导者，先驱者。
阴阳：《易经》上的用语，指创造宇宙空间万物对应的两种气。阳意味春、光阴、君、男性，是积极的行动，阴意味着秋、夜、暗、臣、女性、消极的行动。
观阴阳之开阖以命物：观察阴阳变化来辨别事物。
存亡之门户：指生死之理。
筹策：计算策划。
万类：万物
朕：指徵兆、迹象。
守司：看守加以管理，以便救亡图存。
其道一也：大自然的规律，凡圣人的道理就有一个。
各有所归：世间一切事物各有归宿。
审察其所先后：应该先的事物应居先，应该后的事物就居后，一切都应该调查判定。
以牧，进行调查。
实：实情。
指：意同宗旨。
阖而捭之：假如明白实情；就应自行闭藏或开启。
求其利：研讨对方所说的善恶利害。
开而示之，或阖而闭之：开放使事物显现，或者封闭使事物隐藏。
原其同异：探讨事物相同与不同的特点、性质。
离合：离，不一致：合，一致。
有守：确立自己的观点而信守之。
欲捭之贵周：周，不遗漏，要行动时，必须作周密的考虑。
微：微妙。
与道相追：合乎道之理，与道相贴近。
料其情：检验实情的真伪。
结其诚：结，坚定，使诚意坚定，有好结果。
权衡轻重：衡量比较事物轻重。
为之度数：测量重量和长度的数值。
不中权衡度数，圣人因而自为之虑：如果不合一般事物规律，圣人就继续引导。
四时开闭以化万物：就像春夏秋冬，万物均在变化一样。
纵横：自由自在的变化。
反覆：或离反或复旧。
由此：根据捭阖原则。
道之大化，说之变：大化，变化。“说之变”，游说原则和主张灵活运用。
终始其义：万物始终保持着阴阳变化之理。
诸言：各种言论。
捭阖之道，以阴阳试之：或开放或闭藏，都以阴阳之道试行。
阳言者依崇高：和情之阳者交涉时，就谈论崇高并对之加以试行。
无所不可：游说人，游说家、游说国、游说天下，都没有什么不可以的。
阳还终始，阴极反阳：意为阴阳运行，彼此相生，互相转化。', '纵观古今历史，可知圣人生活在世界上，就是要成为众人的先导。通过观察阴阳两类现象的变化来对事物作出判断，并进一步了解事物生存和死亡的途径。计算和预测事物的发生过程，通晓人们思想变化的关键，揭示事物变化的徵兆，从而把握事物发展变化的关键。所以，圣人在世界上的作用始终是一样的。事物的变化是无穷无尽的，然而都各有自己的归宿；或者属阴，或者归阳；或者柔弱，或者刚强；或者开放，或者封闭；或者松驰，或者紧张。
所以，圣人要始终把握事物发展变化的关键，度量对方的智谋，测量对方的能力，再比较技巧方面的长处和短处。至于贤良和不肖，智慧和愚蠢，勇健和怯懦，都是有区别的。所有这些，可以开放，也可以封闭；可能进升，也可以辞退；可以轻视，也可以敬重，要靠无为来掌握这些。考察他们的有无与虚实，通过对他们嗜好和欲望的分析来揭示他们的志向和意愿。适当贬抑对方所说的话，当他们开放以后再反复考察，以便探察实情，切实把握对方言行的宗旨，让对方先封闭而后开放，以便抓住有利时机。或者开放，使之显现；或者封闭，使之隐藏。开放使其显现，是因为情趣相同；封闭使之隐藏，是因为诚意不一样。要区分什么可行、什么不可行，就要把那些计谋研究明白，计谋有与自己不相同的和相同的，必须有主见，并区别对待，也要注意跟踪对方的思想活动。
如果要开放，最重要的是考虑周详；如果要封闭，最重要的是严密。由此可见周全与保密的重要，应当谨慎地遵循这些规律。让对方一放，是为了侦察他的真情；让对方封闭，是为了坚定他的诚心。所有这些都是为了使对方的实力和计谋全部暴露出来，以便探测出对方的程度和数量。圣人会因此而心思索，假如不能探测出对方的程度和数量，圣人会为此而自谓封闭，或者是通过封闭来自我约束；或者是通过封闭使别人被迫离开。开放和封闭是世界上各种事物发展变化的规律。开放和封闭都是为了使事物内部对立的各方面发生变化，通过一年四季的开始和结束使万物发展变化。不论是纵横，还是离开、归复、反抗，都必须通过开放或封闭来实现。
开放和封闭是万物运行规律的一种体现，是游说活动的一种形态。人们必须首先慎重地考察这睦变化，事物的吉凶，人们的命运都系于此。口是心灵的门面和窗户，心灵是精神的主宰。意志、情欲、思想和智谋都要由这个门窗出入。因此，用开放和封闭来的把守这个关口，以控制出入。所谓「捭之」，就是开放、发言、公开；所谓「阖之」，就是封闭、缄默、隐匿。阴阳两方相谐调，开放与封闭才以有节度，才能善始善终。所以说长生、安乐、富贵、尊荣、显名、嗜好、财货、得意、情欲等，属于「阳」的一类事物，叫做「开始」。而死亡、忧患、贫贱、羞辱、毁弃、损伤、失意、灾害、刑戳、诛罚等，属于「阴」的一类事物，叫作「终止」。凡是那些遵循「阳道」的一派，都可以称为「新生派」，他们以谈论「善」来开始游说；凡是那些遵循「阴道」的一派，都可以称为「没落派」，他们以谈论「恶」来终止施展计谋。
关于开放和封闭的规律都要从阴阳两方面来试验。因此，给从阳的方面来游说的人以崇高的待遇，而给从阴的方面来游说的人以卑下的待遇。用卑下的来求索微小，以崇高来求索博大。由此看来，没有什么不能出去，没有什么不能进来，没有什么办不成的。用这个道理，可以说服人，可以说服家，可以说服国，可以说服天下。要做小事的时候没有「内」的界限；要做大事的时候没有「外」有疆界。所有的损害和补益，离去和接近，背叛和归附等等行为，都是运用阴、阳的变化来实行的。阳的方面，运动前进；阴的方面，静止、隐藏。阳的方面，活动显出；阴的方面，随行潜入。阳的方面，环行于绺和开端；阴的方面，到了极点显就反归为阳。凡是凭阳气行动的人，道德就与之相生；凡是凭阴气而静止的人，开拓热就与之相成。用阳气来追求阴气，要靠道德来包容；用阴气来结纳阳气，要用外来约束。阴阳之气相追求，是依据并启和关闭的原则，这是天地阴阳之道理，又是说服人的方法，是各种事物的先异，是天地的门户。', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf5e2e6a6b501f9681a1", "shortContent": "卢元明《剧鼠赋》是一篇颇具特色的咏物赋。\n据记载，北魏辞赋创作不少，如崔浩就有《赋集》八十六卷（见《隋书·经籍志》），然而，保存下来的作品极少，乃至于产生的错觉是，北朝在游牧民族的统治下，尚武轻文，文学之士大都在南朝。其实，这种认识是不对的。只能说在历史的长河中，北朝的文学作品大部分没有保存下来。在这样的角度看，卢元明的《剧鼠赋》有助于人们认识和了解北魏辞赋创作的情况。\n《剧鼠赋》可分三个部分。第...", "authors": ["张", "强", "邢钺莉"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522681777, '5ac1d71c9f5454335169b518', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636911, '鬼谷子 · 反应', NULL, 20, 12, 0, 1, '鬼谷子', NULL, 36905, '5ac1d6fd9f5454300106d692', '周', 'wen', '文', 'https://baike.baidu.com/item/%E9%AC%BC%E8%B0%B7%E5%AD%90%C2%B7%E5%8F%8D%E5%BA%94/19832345?fr=aladdin', '', '古之大化者，乃与无形俱生。反以观往，覆以验来；反以知古，覆以知今；反以知彼，覆以知己。动静虚实之理，不合来今，反古而求之。事有反而得覆者，圣人之意也，不可不察。
人言者，动也；己默者，静也。因其言，听其辞。言有不合者，反而求之，其应必出。言有象，事有比。其有象比，以观其次。象者象其事，比者比其辞也。以无形求有声，其钓语合事，得人实也。若张置网而取兽也，多张其会而司之。道合其事，彼自出之，此钓人之网也。常持其网驱之，其言无比，乃为之变，以象动之，以报其心，见其情，随而牧之。己反往，彼覆来，言有象比，因而定基。重之袭之，反之复之，万事不失其辞，圣人所诱愚智，事皆不疑。
古善反听者，乃变鬼神以得其情。其变当也，而牧之审也。牧之不审，得情不明；得情不明，定基不审。变象比，必有反辞，以还听之。欲闻其声反默，欲张反敛，欲高反下，欲取反与。欲开情者，象而比之，以牧其辞，同声相呼，实理同归。或因此，或因彼，或以事上，或以牧下，此听真伪、知同异，得其情诈也。动作言默，与此出入，喜怒由此以见其式，皆以先定为之法则。以反求复，观其所托。故用此者，己欲平静，以听其辞，察其事，论万物，别雄雌。虽非其事，见微知类。若探人而居其内，量其能射其意也。符应不失，如腾蛇之所指，若羿之引矢。
故知之始己，自知而后知人也。其相知也，若比目之鱼。其伺言也，若声之与响；见其形也，若光之与影也；其察言也，不失若磁石之取针，舌之取燔骨。其与人也微，其见情也疾。如阴与阳，如阳与阴；如圆与方，如方与圆。未见形圆以道之，既见形方以事之。进退左右，以是司之。已不先定，牧人不正，事用不巧，是谓「忘情失道」；己审先定以牧入，策而无形容，莫见其门，是谓「天神」。', '《鬼谷子·反应》是春秋时期纵横家鬼谷子创作的一篇散文。出自纵横家游说经验的总结《鬼谷子》，作者为周朝思想家、道家代表人物、纵横家的鼻祖，「王禅老祖」是后人对鬼谷子的称呼，为老学五派之一。', '', '在古代能以「大道」来化育万物的圣人，其所作所为都能与自然的发展变化相吻全。反顾以追溯既往，再回首以察验未来；反顾以考察历史，再回首以了解当今；反顾以洞察对方，再回首以认识自我。动静、虚实的原则，如果在未来和今天都得不到应用，那就要到过去的历史中去考察前人的经验。有些事情是要反复探索才能把握的，这是圣人的见解，不可不认真研究。
人家说话，是活动；自己缄默，是静止。要根据别人的言谈来他的辞意。如果其言辞有矛盾之处，就反复诘难，其应对之矢就要出现。语言有可以模拟的形态，事物有可以类比的规范。既有「象」和「比」存在，就可以预见其下一步的言行。所谓「象」就是模仿事物，所谓「比」，就是类比言辞。然后以无形的规律来探求有声的言辞。引诱对方说出的言辞，如果与事实相一致，就可以刺探到对方的实情。这就像张开网捕野兽一样，要多设一些网，江集在一起来等待野兽落入。如果把捕野兽的这个办法也能应用到人事上，那么对方也会自己出来的，这是钓人的「网」。但是，如果经常拿着「网」去追逐对方，其言辞就不再有平常的规范，这时就要变换方法，用「法象」来使对手感动，进而考察对方的思想，使其暴露出实情，进而控制对手。自己返过去，使对手返回来，所说的话可以比较类推了，心里就有了底数。向对手一再袭击，反反复复，所有的事情都可以通过说话反映出来，圣人可以诱惑愚者和智者，这些不必再怀疑。
古代善于从反面听别人言论的人，可以改变鬼神，从而刺探到实情。他们随机应变很得当，对对手的控制也很周到。如果控制不周到，得到的情况就不明了，得到的情况不明了，心里底数就不全面。要把模仿和类比灵活运用，就要说反话，以便观察对方的反映。想要讲话，反而先沉默；想要敞开，反而先收敛；想要升高，反而先下降；想要获取，反而先给与。要想了解对方的内情，就要善于运用模仿和类比的方法，以便把握对方的言辞。同类的声音可以彼此响应，合乎实际的道理会有共同的结果。或者由于这个原因，或者由于那个原因；或者用来侍奉君主，或者用来管理下属。这就要分辨真伪，了解异同，以分辨对手的真实情报或诡诈之术。活动、停止，应该说、沉默都要通过这些表现出来，喜怒哀乐也都要借助这些模式，都要事先确定法则。用逆反心理来追索其过去的精神寄托。所以就用这种反听的方法。自己要想平静，以便听取对方的言辞，考察事理，论说万物，辨别雄雌虽然这不是事情本身，但是可以根据轻微的征兆，探索出同类的大事。就像刺探敌情而深居敌境一般，要首先估计敌人的能力，其次再摸清敌人的意图，像验合符契一样可靠，像螣蛇一样迅速，像后羿张弓射箭一样准确。
所以要想掌握情况，要先从自己开始，只有了解自己，然后才能了解别人。对别人的了解，就旬比目鱼一样没有距离；掌握对方的言论就像声音与回响一样相符；明了对方的情形，就像光和影子一样不走样；侦察对方的言辞，就像用磁石来吸取钢针，用舌头来获取焦骨上的肉一样万无一失。自己暴露给对方的微乎其微，而侦察对手的行动十分迅速。就像阴变阳，又像阳转阴、像贺变方，又像方转贺一样自如。在情况还未明朗以前就圆略来诱惑对手，在情况明朗以后就要用方略来战胜对方。无论是向前，还是向后，无论是向左，还是向右，都可用这个方法来对待。如果自己不事先确定策略，统帅别人也无法步调一致。做事没有技巧，叫做「忘情失道」，自己首先确定斗争策略，再以此来统领众人，策略要不暴露意图，让旁人看不到其门道所在，这才要以称为「天神」。', NULL, '', 'indent', 1522681819, '5ac1d7577565710045b24261', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636920, '鬼谷子 · 决篇', NULL, 19, 12, 1, 2, '鬼谷子', NULL, 36905, '5ac1d6fd9f5454300106d692', '周', 'wen', '文', 'https://baike.baidu.com/item/%E9%AC%BC%E8%B0%B7%E5%AD%90%C2%B7%E5%86%B3%E7%AF%87/19832371?fr=aladdin', '', '凡决物，必托于疑者。善其用福，恶其用患；害至于诱也，终无惑偏。有利焉，去其利，则不受也；奇之所托。若有利于善者，隐托于恶，则不受矣，致疏远。故其有使失利者，有使离害者，此事之失。
圣人所以能成其事者有五：有以阳德之者，有以阴贼之者，有以信诚之者，有以蔽匿之者，有以平素之者。阳励于一言，阴励于二言，平素、枢机以用；四者微而施之。于事度之往事，验之来事，参之平素，可则决之。
王公大人之事也，危而美名者，可则决之；不用费力而易成者，可则决之；用力犯勤苦，然不得已而为之者，可贵则决之；去患者，可贵则决之；从福者，可则决之。故夫决情定疑，万事之基，以正治乱，决成败，难为者。故先王乃用蓍龟者，以自决也。', '《鬼谷子·决篇》是春秋时期纵横家鬼谷子创作的一篇散文。', '', '凡为他人决断事情，都是受托于有疑难的人。一般说来，人们都希望遇到有利的事，不希望碰上祸患和被骗诱，希望最终能排除疑惑。在为人作决断时，如果只对一方有利，那么没有利的一方就不会接受，就是因为依托的基础不平衡。任何决断本来都应有利于决断者的，但是如果在其中隐含着不利的因素，那么决断者就不会接受，彼此之间的关系也会疏远，这样对为人决断的人就不利了，甚至还会遭到灾难，这样决断是失误的。
圣人所以能完成大业，主要有五个途径：有用阳道来感人的；有用阴道来惩治的；有用信义来教化的；有用爱心来庇护的；有用谦洁来净化的。行阳道则努力守常如一，行阴道则努力掌握事物对立的两面。要在平时和关键时刻巧妙的运用这四方面，小心谨慎行事。推测以往的事，验证未来的事，再参考日常的事，如果可以，就作出决断。
王公大臣的事，崇高而享有美名的，如果可以就作出决断；不用费力轻易可获成功的事，如果可以就作出决断，费力气又辛苦，但不得不做的，如果可以就作出决断；能消除忧患的，如果可以就作出决断；能实现幸福的，如果可以就作出决断。因此说，解决事情，确定疑难，是万事的关键。澄清动乱，预知成败，这是一件很难做到的事。所以古代先王就用筮草和龟甲来决定一些大事。', NULL, '', 'indent', 1522682113, '5ac1d8739f5454335169c0b3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636912, '鬼谷子 · 内揵', NULL, 8, 12, 0, 1, '鬼谷子', NULL, 36905, '5ac1d6fd9f5454300106d692', '周', 'wen', '文', 'https://baike.baidu.com/item/%E9%AC%BC%E8%B0%B7%E5%AD%90%C2%B7%E5%86%85%E6%A5%97/19832339?fr=aladdin', '', '君臣上下之事，有远而亲，近而疏；就之不用，去之反求；日进前而不御，遥闻声而相思。
事皆有内揵，素结本始。或结以道德，或结以党友，或结以财货，或结以采色。用其意，欲入则入，欲出则出；欲亲则亲，欲疏则疏；欲就则就；欲去则去；欲求则求，欲思则思。若蚨母之从子也；出无间，入无朕。独往独来，莫之能止。
内者，进说辞也。楗者，楗所谋也。欲说者务稳度，计事者务循顺。阴虑可否，明言得失，以御其志。方来应时，以和其谋。详思来楗，往应时当也。夫内有不合者，不可施行也。乃揣切时宜，从便所为，以求其变。以变求内者，若管取楗。言往者，先顺辞也；说来者，以变言也。善变者审知地势，乃通于天，以化四时，使鬼神，合于阴阳，而牧人民。
见其谋事，知其志意。事有不合者，有所未知也。合而不结者，阳亲而阴疏。事有不合者，圣人不为谋也。
故远而亲者，有阴德也。近而疏者，志不合也。就而不用者，策不得也。去而反求者，事中来也。日进前而不御者，施不合也。遥闻声而相思者，合于谋待决事也。
故曰：不见其类而为之者，见逆。不得其情而说之者，见非。得其情乃制其术，此用可出可入，可楗可开。故圣人立事，以此先知而楗万物。
由夫道德仁义，礼乐忠信计谋，先取诗书，混说损益，议论去就。欲合者用内，欲去者用外。外内者，必明道数。揣策来事，见疑决之。策无失计，立功建德，治名入产业，曰楗而内合。上暗不治，下乱不窹，楗而反之。内自得而外不留，说而飞之，若命自来，己迎而御之。若欲去之，因危与之。环转因化，莫知所为，退为大仪。', '《鬼谷子·内揵》是春秋时期纵横家鬼谷子创作的一篇散文。出自纵横家游说经验的总结《鬼谷子》，内楗篇主要说的是如何给领导建议，以及如何遵守自身主张。', '', '君臣上下之间的事情，有的距离很远却很亲密，有的距离很近却很疏远。有的在身边却不被使用，有的在离去以后还受聘请。有的天天都能到君主眼前却不被信任，有的距离君主十分遥远却听到声音就被思念。凡是事物都有采纳和建议两方面，平常的东西都与本源相连结，或者靠道德相连结，或者靠朋党相连结，或者靠钱物相连结，或者靠艺术相连结。要想推行自己的主张，就要做到想进来就进来，想出去就出去；想亲近就亲近，想疏远就疏远；想接近就接近，想离去就离去；想被聘用就被聘用，想被思念就被思念。就好象母蜘蛛率领小蜘蛛一样，出来时不留洞痕，进去时不留标记，独自前往，独自返回，谁也没法阻止它。
所谓“内”就是采纳意见；所谓“揵”就是进献计策。想要说服他人，务必要先悄悄地揣测；度量、策划事情，务必要循沿顺畅的途径。暗中分析是可是否，透彻辨明所得所失，以便影响君主的赣。以道术来进言当应合时宜。以便与君主的谋划相合。详细地思考后再来进言，支适应形势。凡是内情有不合时宜的，就不可以实行。就要揣量切摩形势，从便利处入手，来改变策略。用善于变化来邹被采纳，就像以门管来接纳门楗一样顺当。
凡是谈论过去的事情，要先顺畅的言辞，凡是谈论未来的事情要采用容易、变通的言辞。善于变化的的，要详细了解地理形势，只有这样，才能沟通天道，化育四时，驱使鬼神，附合阴阳，牧养人民。要了解君主谋划的事情，要知晓君主的意图。所办的事情凡有不合君主之意的，是因为对君主的意图留于表面亲近，而背地里还有距离。如果与君主的意见没有吻合的可能，圣人是不会为其谋划的。所以说，与君主相距很远却被亲近的人，是因为能与君主心意暗合；距离君主很近却被疏远的人，是因为与君主志向不一；就职上任而不被重用的人，是因为他的计策没有实际效果；革职离去而能再被反聘的人，是因为他和主张被实践证明可行；每天都能出入君主面前，却不被信任的人，是因为他的行为不得体；距离遥远只要能扣到声音就被思念的人，是因为其主张下与决策都相合，正等他参加决断大事。所以说，在情况还没有明朗之前就去游说的人，定会事与愿违，在还不掌握实情的时候就去游说的人，定要受到非议。只有了解情况，再依据实际情况确定方法，这样去推行自己的主张，就可以出去，又可以进来；既可以进谏君主，坚持己见，又可以放弃自己的主张，随机应变。
圣人立身处世，都以自己的先见之明来议论万事万物。其先之明来源于道德、仁义、冖乐和计谋。首先摘了《经》和《书经》的教诲，再综合分析利弊得失，最后讨论就任还是离职。要想与人合作，就要把力量用在内部，要想离开现职，就要扰力量用在外面。处理内外大事必须明确理论和方法，要预测未来的事情，就要善于在各种疑难面前临机决断，在运用策略时要不失算，不断建立功业和积累德政。善于管理人民，使他们从事生产事业，这叫做“巩固内部团结”。
如果上层昏庸不理国家政务，下层份乱不明为臣事理，各执己见，事事抵触，还自鸣得意；不接受外面的新思想，还自吹自擂。在这种情况下，如果朝廷诏命自己，虽然也要迎接，但又要拒绝。要拒绝对方的诏命，要设法给人一种错觉。就像圆环旋转往复一样，使旁人看不出您想要干什么。在这种情况下，急流勇退是最好的办法。', NULL, '', 'indent', 1522681855, '5ac1d77da22b9d0045458bc7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636913, '鬼谷子 · 抵巇', NULL, 7, 12, 0, 1, '鬼谷子', NULL, 36905, '5ac1d6fd9f5454300106d692', '周', 'wen', '文', 'https://baike.baidu.com/item/鬼谷子·抵巇/19832351?fr=aladdin', '', '物有自然，事有合离。有近而不可见，有远而可知。近而不可见者，不察其辞也；远而可知者，反往以验来也。
戏者，罅也。罅者，涧也。涧者，成大隙也。戏始有朕，可抵而塞，可抵而却，可抵而息，可抵而匿，可抵而得，此谓抵巇之理也。
事之危也，圣人知之，独保其身；因化说事，通达计谋，以识细微。经起秋毫之末，挥之于太山之本。其施外，兆萌芽蘖之谋，皆由抵巇。抵巇之隙为道术用。
天下纷错，上无明主，公侯无道德，则小人谗贼，贤人不用，圣人鼠匿，贪利诈伪者作，君臣相惑，土崩瓦解而相伐射，父子离散，乖乱反目，是谓萌牙戏罅。圣人见萌牙戏罅，则抵之以法。世可以治，则抵而塞之；不可治，则抵而得之；或抵如此，或抵如彼；或抵反之，或抵覆之。五帝之政，抵而塞之；三王之事，抵而得之。诸侯相抵，不可胜数，当此之时，能抵为右。
自天地之合离终始，必有戏隙，不可不察也。察之以捭阖，能用此道，圣人也。圣人者，天地之使也。世无可抵，则深隐而待时；时有可抵，则为之谋；可以上合，可以检下。能因能循，为天地守神。', '《鬼谷子·抵巇》是春秋时期纵横家鬼谷子创作的一篇散文。', '', '万物都有规律存在，任何事情都有对立的两方面。有时彼此距离很近，却互相不了解；有时互相距离很远，却彼此熟悉。距离近而互相不了解，是因为没有互相考察言辞；距离远却能彼此熟悉，是因为经常往来，互相体察。
所谓“巇”就是“瑕罅”，而“罅”就是容器的裂痕，裂痕会由小弯大。在裂痕刚刚出现时，可以通过“抵”使其闭塞，可以通过“抵”，使其停止，可以通过“抵”使其变小，可以通过“抵”使其消失，可以通过“抵”而夺取器物。这就是“抵”的原理。
当事物出现危机之初，只有圣人才能知道，而且能单独知道它的功用，按着事物的变化来说明整理，了解各种计谋，以便观察对手的细微举动。万事万物在开始时都像秋毫之末一样微小，一量发展起来就像泰山的根基一样宏大。当圣人将行政向外推行时，奸佞小人的一切阴谋诡计，都会被排斥，可见抵原来是一种方法。
天下动乱不止，朝迁没有贤明的君主，官吏们没有社会道德。小人谗言妄为，贤良的人才不被信用，圣人逃匿躲藏起来，一些贪图利禄，奸诈虚伪的人飞黄腾达，君主和大臣之间互相怀疑，君臣关系土崩瓦解，互相征伐，父子离散，骨肉反目，就叫做“轻微的裂痕”。当圣人看到轻微的裂痕时，就设法治理。当世道可以治理时，就要采取弥补的“抵”法，使其“”得到弥合继续保持它的完整，继续让它存在下去；如果世道已坏到不可治理时，就用破坏的“抵”法（彻底把它打破“，占有它并重新塑造它。或者这样“抵”，或者那样“抵”；或者通过“抵”使其恢复原状，或者通过“抵”将其重新塑造。对五帝的圣明政治只能“抵而塞之”；三王从事的大事就是了解当时的残暴政治，从而夺得并重新建立政权。诸候之间互相征伐，斗争频繁，不可胜数，在这个混乱的时代，善于斗争的诸候才是强者。
自从天地之间有了“合离”、“终始”以来，万事万物就必然存在着裂痕，审不可不研究的问题。要想研究这个问题就要用“捭阖”的方法。能用这种方法的人，就是圣人，圣人是天地的使者。当世道不需要“抵”的时候，就深深地隐居起来，以等待时机；当世道有可以“抵”弊端时，对上层可以合作，对下属可以督查，有所依据、有所遵循，这样就成了天地的守护神。', NULL, '', 'indent', 1522681893, '5ac1d7a317d0090061612326', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636914, '鬼谷子 · 飞钳', NULL, 8, 12, 0, 1, '鬼谷子', NULL, 36905, '5ac1d6fd9f5454300106d692', '周', 'wen', '文', 'https://baike.baidu.com/item/%E9%AC%BC%E8%B0%B7%E5%AD%90%C2%B7%E9%A3%9E%E7%AE%9D/19832347?fr=aladdin', '', '凡度权量能，所以征远来近。立势而制事，必先察同异之计，别是非之语，见内外之辞，知有无之术；决安危之计，定亲疏之事；然后乃权量之。其有隐括，乃可征、乃可求、乃可用。引钩钳之辞，飞而钳之。钩钳之语，其说辞也，乍同乍异。其不可善者：或先征之，而后重累；或先重以累，而后毁之；或以重累为毁；或以毁为重累。其用或积财货、琦玮、珠玉、白璧、采邑以事之，或量能立势以钩之，或伺候见涧而钳之，其事用抵墟。
将欲用之于天下，必度权量能，见天时之盛衰，制地形之广狭，阻险之难易，人民货财之多少，诸侯之交孰亲孰疏，孰爱孰憎，心意之虑怀，审其意，知其所好恶，乃就说其所重，以飞钳之辞钩其所好，以钳求之。
用之于人，则量智能、权材力、料气势，为之枢机以迎之随之，以钳和之，以意宜之，此飞钳之缀也。
用于人，则空往而实来，缀而不失，以究其辞。可钳而纵，可钳而横；可引而东，可引而西；可引而南，可引而北；可引而反，可引而覆。虽覆能复，不失其度。', '《鬼谷子·飞钳》是春秋时期纵横家鬼谷子创作的一篇散文。出自纵横家游说经验的总结《鬼谷子》，作者为周朝思想家、道家代表人物、纵横家的鼻祖，“王禅老祖”是后人对鬼谷子的称呼，为老学五派之一。', '', '只要善于揣度人的智谋，考量人的才干，就能吸引远近人才。要造成一种声势，使事情获得成功，就得先观察人们相同和不同之处，区别议论的是与非，了解对内对外的各种进言，掌握其真假，决定事关安危的计谋，确定与谁亲近和与谁疏远。然后再看看这样做的利弊得失。衡量这些关系时，如果还有不清楚的地方，就要进行研究，进行探索，使之为我所用。借用引诱使对方说出真情，然后通过恭维来钳住对手。钩钳之语是一种游说辞令，其特点是忽同忽异。对于那些没法控制的对手，或者先对他们威胁利诱，然后再对他们反复试探；或者先对他们反复试探，然后再摧毁他们；或者在反复考验中，毁灭对方，或者把摧毁对方作为反复考验。想要重用某些人时，可先赏赐财物、珠宝、玉石、白璧和封地，以便对他们试探；或者通过衡量其才能创造气氛，来吸引他们；或者通过寻找机会来控制对方，在这个过程中要运用抵之术。
要把“飞钳”之术向天下推行，必须考量人的权谋和才干，观察天地的盛衰，掌握地形的宽窄和山川险阻的难易，以及人民财富的多少，诸侯间交往中谁与谁亲密，谁与谁疏远，谁与谁友好，谁与谁相恶。要详细考察对方的愿望和想法，了解他们的好恶，然后针对对方所重视的问题游说他，先用“飞”的方法诱出对方爱好之所在。最后再用“钳”的方法控制住对方。
如果把“飞钳”之术用于他人，就要揣摩对方的智慧和才能，度量对方的实力，估计对方的势气，然后以此为突破口与对方周旋，进而争取以“飞钳”之术达成妥协，有意识地适应对方。这就是“飞钳”的秘诀。
如果把“飞钳”之术用于外交，可用华美的辞藻套出对方的实情，保持联系，勿使失误，以便考究游说的辞令。这样就可以把握关键实现合纵，也可以实现连横；也可以引而向东，也可以引而向西；可以引而向南，也可以引而向北；可以引而返还，也可以引而复去。虽然如此，还是要小心谨慎，不可丧失其节度。', NULL, '', 'indent', 1522681923, '5ac1d7c19f54543495d24a2b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636915, '鬼谷子 · 忤合', NULL, 8, 12, 0, 1, '鬼谷子', NULL, 36905, '5ac1d6fd9f5454300106d692', '周', 'wen', '文', 'https://baike.baidu.com/item/%E9%AC%BC%E8%B0%B7%E5%AD%90%C2%B7%E5%BF%A4%E5%90%88/19832342?fr=aladdin', '', '凡趋合倍反，计有适合。化转环属，各有形势，反覆相求，因事为制。是以圣人居天地之间，立身、御世、施教、扬声、明名也；必因事物之会，观天时之宜，因知所多所少，以此先知之，与之转化。
世无常贵，事无常师；圣人无常与，无不与；无所听，无不听；成于事而合于计谋，与之为主。合于彼而离于此，计谋不两忠，必有反忤；反于是，忤于彼；忤于此，反于彼。其术也，用之于天下，必量天下而与之；用之于国，必量国而与之；用之于家，必量家而与之；用之于身，必量身材气势而与之；大小进退，其用一也。必先谋虑计定，而后行之以飞钳之术。
古之善背向者，乃协四海，包诸侯忤合之地而化转之，然后求合。故伊尹五就汤，五就桀，而不能所明，然后合于汤。吕尚三就文王，三入殷，而不能有所明，然后合于文王，此知天命之钳，故归之不疑也。
非至圣达奥，不能御世；非劳心苦思，不能原事；不悉心见情，不能成名；材质不惠，不能用兵；忠实无实，不能知人；故忤合之道，己必自度材能知睿，量长短远近孰不知，乃可以进，乃可以退，乃可以纵，乃可以横。', '《鬼谷子·忤合》是春秋时期纵横家鬼谷子创作的一篇散文。', '', '凡是有关联合或对抗的行劝，都会有相应的计策。变化和转移就像铁环一样环连而无中断。然而，变化和转移又各有各的具体情形。彼此之间环转反复，互相依赖，需要根据实际情况进行控制。所以圣人生活在世界上，立身处世都是为了说教众人，扩大影响，宣扬名声。他们还必须根据事物之间的联系来考察天时，以便抓有利时机。国家哪些方面有余，哪些方面不足，都要从这里出发去掌握，并设法促进事物向有利的方面转化。
世界上的万事万物也没有永远居于榜样地位的。圣人常常是无所不做，无所不听。办成要办的事，实现预定的计谋，都是为了自己的评价，合乎那一方的利益，就要背叛一方的利益。凡是计谋不可能同时忠于两个对立物君主，必然违背某一方的意愿。合乎这一方的意愿，就要违背另一主的意愿；违背另一方的意愿，才可能合乎这一主的意愿。这就是“忤合”之术。如果把这种“忤合”之术运用到天下，必然要把全天下都放在忤合之中；如果把这种“忤合”之术用到某个国家，就必然要把整个国家放在忤合之中；如果把这种“忤合”之术运用到某个家庭，就必然要把整个家庭都放在忤合之中；如果把这种“忤合”之术用到某一个人，就必然要把这个人的才能气势都放在忤合之中。总之，无论把这种“忤合”之术用在大的范围，还是用在小的范围，其功用是相同的。因此，无论在何时何地都要进行谋划、分析，计算准确了以后再实行“忤合”之术。
古代那些善于通过背离一方、趋向一主而横行天下的人。常常掌握四海之内的各种力量，控制各个诸候，促成“屣合”转化的趋势，然后达成“合”于圣贤君主的目的。过去伊尹五盗用臣肫商汤，五次臣服夏桀，其行动目的还未被世人所知，就决定一心臣服商汤王。吕尚三次臣服周文王，三次臣服殷纣是懂得天命的制约，所以才能归顺一主而毫不犹豫。
对于一个纵横家来说，如果没有高尚的品德，超人的智慧，不可能通晓深层的规律，就不可能驾驭天下；如果不肯用心苦苦思考，就不可能揭示事物的本来面目；如果不会全神贯注地考察事物的实际情况，就不可能功成名就；如果才能、胆量都不足，就不能统兵作战；如果只是愚忠呆实而无真知灼见，就不可能有祭人之明。所以，“忤合”的规律是：要首先自我估量聪明才智，然后度量他人的优劣长短，分析在远近范围之内还比不上谁。只有在这样知己知彼以后，才能随心所欲，可以前进，可以后退；可以合纵，可以连横。', NULL, '', 'indent', 1522681953, '5ac1d7dfac502e0063b6c347', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637055, '茶经 · 四之器', NULL, 4, 14, 0, 1, '陆羽', NULL, 13217, '584432e0c59e0d0056a3b0e9', '唐', 'wen', '文', '', '', '风炉：风炉以铜铁铸之，如古鼎形，厚三分，缘阔九分，令六分虚中，致其圬墁，凡三足。古文书二十一字，一足云“坎上巽下离于中”，一足云“体均五行去百疾”，一足云“圣唐灭胡明年铸”。其三足之间设三窗，底一窗，以为通飙漏烬之所，上并古文书六字：一窗之上书“伊公”二字，一窗之上书“羹陆”二字，一窗之上书“氏茶”二字，所谓“伊公羹陆氏茶”也。置墆㙞于其内，设三格：其一格有翟焉，翟者，火禽也，画一卦曰离；其一格有彪焉，彪者，风兽也，画一卦曰巽；其一格有鱼焉，鱼者，水虫也，画一卦曰坎。巽主风，离主火，坎主水。风能兴火，火能熟水，故备其三卦焉。其饰以连葩、垂蔓、曲水、方文之类。其炉或锻铁为之，或运泥为之，其灰承作三足，铁盘台之。
筥：筥以竹织之，高一尺二寸，径阔七寸，或用藤作，木楦，如筥形，织之六出，固眼其底，盖若利箧口铄之。
炭挝：炭挝以铁六棱制之，长一尺，锐一丰，中执细头，系一小钅展，以饰挝也。若今之河陇军人木吾也，或作锤，或作斧，随其便也。
火䇲：火䇲一名箸，若常用者圆直一尺三寸，顶平截，无葱台勾锁之属，以铁或熟铜制之。
鍑：鍑以生铁为之，今人有业冶者所谓急铁。其铁以耕刀之趄炼而铸之，内摸土而外摸沙土。滑于内，易其摩涤；沙涩于外，吸其炎焰。方其耳，以正令也；广其缘，以务远也；长其脐，以守中也。脐长则沸中，沸中则末易扬，末易扬则其味淳也。洪州以瓷为之，莱州以石为之，瓷与石皆雅器也，性非坚实，难可持久。用银为之，至洁，但涉于侈丽。雅则雅矣，洁亦洁矣，若用之恒而卒归于银也。
交床：交床以十字交之，剜中令虚，以支鍑也
夹：夹以小青竹为之，长一尺二寸，令一寸有节，节已上剖之，以炙茶也。彼竹之筱津润于火，假其香洁以益茶味，恐非林谷间莫之致。或用精铁熟铜之类，取其久也。
纸囊：纸囊以剡藤纸白厚者夹缝之，以贮所炙茶，使不泄其香也。
碾：碾以橘木为之，次以梨、桑、桐柘为臼，内圆而外方。内圆备于运行也，外方制其倾危也。内容堕而外无余木，堕形如车轮，不辐而轴焉，长九寸，阔一寸七分，堕径三寸八分，中厚一寸，边厚半寸，轴中方而执圆，其拂末以鸟羽制之。
罗合：罗末以合盖贮之，以则置合中，用巨竹剖而屈之，以纱绢衣之，其合以竹节为之，或屈杉以漆之。高三寸，盖一寸，底二寸，口径四寸。
则：则以海贝蛎蛤之属，或以铜铁竹匕策之类。则者，量也，准也，度也。凡煮水一升，用末方寸匕。若好薄者减之，嗜浓者增之，故云则也。
水方：水方以椆木、槐、楸、梓等合之，其里并外缝漆之，受一斗。
漉水囊：漉水囊若常用者，其格以生铜铸之，以备水湿，无有苔秽腥涩。意以熟铜苔秽、铁腥涩也。林栖谷隐者或用之竹木，木与竹非持久涉远之具，故用之生铜。其囊织青竹以卷之，裁碧缣以缝之，纽翠钿以缀之，又作绿油囊以贮之，圆径五寸，柄一寸五分。
瓢：瓢一曰牺杓，剖瓠为之，或刊木为之。晋舍人杜毓《荈赋》云：“酌之以匏。”匏，瓢也，口阔胫薄柄短。永嘉中，馀姚人虞洪入瀑布山采茗，遇一道士云：“吾丹丘子，祈子他日瓯牺之余乞相遗也。”牺，木杓也，今常用以梨木为之。
竹策：竹策或以桃、柳、蒲、葵木为之，或以柿心木为之，长一尺，银裹两头。
鹾簋：鹾簋以瓷为之，圆径四寸。若合形，或瓶或罍，贮盐花也。其揭竹制，长四寸一分，阔九分。揭，策也。
熟盂：熟盂以贮熟水，或瓷或沙，受二升。
碗：碗，越州上，鼎州次，婺州次，岳州次，寿州、洪州次。或者以邢州处越州上，殊为不然。若邢瓷类银，越瓷类玉，邢不如越一也；若邢瓷类雪，则越瓷类冰，邢不如越二也；邢瓷白而茶色丹，越瓷青而茶色绿，邢不如越三也。晋·杜毓《荈赋》所谓器择陶拣，出自东瓯。瓯，越也。瓯，越州上口唇不卷，底卷而浅，受半升已下。越州瓷、岳瓷皆青，青则益茶，茶作白红之色。邢州瓷白，茶色红；寿州瓷黄，茶色紫；洪州瓷褐，茶色黑：悉不宜茶。
畚：畚以白蒲卷而编之，可贮碗十枚。或用筥，其纸帕，以剡纸夹缝令方，亦十之也。
札：札缉栟榈皮以茱萸木夹而缚之。或截竹束而管之，若巨笔形。
涤方：涤方以贮涤洗之余，用楸木合之，制如水方，受八升。
滓方：滓方以集诸滓，制如涤方，处五升。
巾：巾以絁为之，长二尺，作二枚，玄用之以洁诸器。
具列：具列或作床，或作架，或纯木纯竹而制之，或木法竹黄黑可扃而漆者，长三尺，阔二尺，高六寸，其到者悉敛诸器物，悉以陈列也。
都篮：都篮以悉设诸器而名之。以竹篾内作三角方眼，外以双篾阔者经之，以单篾纤者缚之，递压双经作方眼，使玲珑。高一尺五寸，底阔一尺，高二寸，长二尺四寸，阔二尺。', '', '污墁：本为涂墙用的工具，这里指涂泥。
坎上巽下离于中：坎、巽、离都是八卦的卦名，坎为水，巽为风，离为火。
盛唐灭胡明年：盛唐灭胡，指唐平息安史之乱，时在唐肃宗至德元年（763）。盛唐灭胡明年则是公元764年。
伊公羹、陆氏茶：伊公，指商汤时的大尹伊挚。相传他善调汤味，世称“伊公羹”；陆即陆羽自己，“陆氏茶”则指陆羽煎茶。
墆（dì）㙞（niè）：意为土堆。墆，古同“滞”，储藏。《广韵》：“墆，贮也，止也。”
三足铁籭：籭，通“盘”，盘子。
莉策：用小竹蔑编成的长方形箱子。
木吾：木棒。崔豹《古今注》：“木吾，樟也”。
葱薹句鏁：葱薹，葱的籽实，长在葱的顶部，呈圆珠形。句鏁，句通“勾”，弯曲形。鏁，即“锁”的异体字。
耕刀之趄：耕刀，即锄头、犁头。趄，读音ju，艰难行走之意，成语有“趑趄不前”，此引申为坏的、旧的。
洪州：唐时州名，治所在今江西南昌一带。
莱州：唐时州名，治所在今山东掖县一带。
竹之筱：筱，竹的一种，名小箭竹。
剡藤纸：产于唐时浙江剡县、用藤为原料制成的纸，洁白细致有韧性，为唐时包茶专用纸。
竹匕：匕，匙子。
用末方寸匕：用竹匙挑起茶叶末一平方寸。陶弘景《名医别录》：“方寸匕者，作匕正方一寸，抄散取不落为度。”
漉水囊：漉，滤过。漉水囊，即滤水袋。
杜毓（265—316）：应作杜育，字方叔，西晋文人，曾任中书舍人等职。
鹾（cuó）簋（guǐ）：盐罐，鹾，即盐。《礼记.曲礼》：“盐曰咸鹾”。簋，古代盛食物的圆口竹器。
越州、鼎州、婺州：越州，治所在今浙江省绍兴地区。唐时越窑主要在余姚，所产青瓷，极名贵。鼎州，治所在今陕西省径阳三原一带。婺州，治所在今浙江省金华一带。
岳州、寿州、洪州、邢州：皆唐时州郡名。治所分别在今湖南岳阳、安徽寿县、江西南昌、河北邢台一带。
畚：读音ben。即簸箕。
滞（土旁）布，滞（土旁），读音shi，粗绸。
扃：读音jiong，可关锁的门。', '风炉，用铜或铁铸成，像古鼎的样子，壁厚三分，炉口上的边缘九分，炉多出的六分向内，其下虚空，抹以泥土。炉的下方有三只脚，铸上籕文，共二十一个字。一只脚上写''坎上巽下离于中''，一只脚上写''体均五行去百疾''。一只脚上写''圣唐灭胡明年铸''。在三只脚间开三个窗口。炉底下一个洞用来通风漏灰。三个窗口上书六个字的籕文，一个窗口上写''伊公''二字，一个窗口上写''羹陆''二字，一个窗口上写''氏茶''二字，意思就是''伊公羹，陆氏茶''。炉上设置支撑锅子用的垛，其间分三格。一格上有只野鸡图形。野鸡是火禽，画一离卦。一格上有只彪的图形。彪是风兽，画一巽卦。一格上有条鱼的图形。鱼是水虫，画一坎卦，''巽''表示风，''离''表示火，''坎''表示水。风能使火烧旺，火能把水煮开，所以要有这三卦。炉身用花卉、流水、方形花纹等图案来装饰。风炉也有用熟铁打的，也有用泥巴做的。灰承（接受灰炉的器具），作一个有三只脚的铁盘，托住炉子。
筥，用竹子编制，高一尺二寸，直径七寸。也有的先做个像筥形的木箱，再用藤子编在外面，有六出的圆眼。底和盖像箱子的口，削光滑。
炭挝，用六棱形的铁棒做，长一尺，头部尖，中间粗，握处细，握的那头套一个小环作为装饰，好象现在河陇地带的军人拿的''木吾''。有的把铁棒做成槌形，有的做成斧形，各随其便。
火夹，又叫箸，就是平常用的火钳。用铁或熟铜制成。圆直形，长一尺三寸，顶端平齐，饰有葱台、勾鏁之类的东西。
鍑（同''釜''，即锅）。用生铁做成。''生铁''是现在搞冶炼的人说的''急铁''，那铁是以用坏了的农具炼铸的。铸锅时，内面抹上泥，外面抹沙。内面抹上泥，锅面光滑，容易磨洗；外面抹上沙，锅底粗糙，容易吸热。锅耳做成方的，让其端正。锅边要宽，好伸展开。锅脐要长，使在中心。脐长，水就在锅中心沸腾；在中心沸腾，水沫易于上升；水沫易于上升，水味就淳美。洪州用瓷做锅，莱州用石做锅，瓷锅和石锅都是雅致好看的器皿，但不坚固，不耐用。用银做锅，非常清洁，但不免过于奢侈了。雅致固然雅致，清洁确实清洁，但从耐久实用说，还是铁好。
交床，用十字交叉的木架，把中间挖凹些，用来支持锅。
夹，用小青竹制成，长一尺二寸。让一头的一寸处有节，节以上剖开，用来夹着茶饼在火上烤，让那竹条在火上烤出水来，借它的香气来增加茶的香味。但不在山林间炙茶，恐怕难以弄到这青竹。有的用好铁或熟铜制作，取其耐用的长处。
纸袋，用两层又白又厚的剡藤纸做成。用来贮放烤好的茶，使香气不散失。', NULL, '', 'indent', 1522955525, '5ac603a6ac502e0063cea9cc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637328, '咏雪诗', NULL, 10, 141, 2, 1, '吴均', NULL, 10371, '57b9c6a6128fe1005f869748', '南北朝', 'shi', '诗', '', '', '微风摇庭树，细雪下帘隙。
萦空如雾转，凝阶似花积。
不见杨柳春，徒看桂枝白。
零泪无人道，相思空何益。', '', '', '', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccca0ce818559d0646ed", "shortContent": "这首诗以咏雪为题，实际上是观雪感怀。作品中所写的雪，既不是银装素裹的旷野之雪，也不是漫天飞舞的吉征瑞兆之雪，而是江南庭院中的细雪。作者立于帘下，他的眼界也未曾超出庭院的上下前后。\n首句写风摇庭院之树，是因树动而知风，并且知是微风，显然庭树之动不同于大风下之摇动。次句的“细雪”与前面的“微风”相应，都具有江南雪景的特点。“下帘隙”的“下”，正与风之微、雪之细相应，故能从竹帘缝隙中落入。“萦空”二句写...", "authors": ["许志刚"], "pressName": "上海辞书出版社"}]', '', 'center', 1581209143, '5adc07229f545471febcfee1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636916, '鬼谷子 · 揣篇', NULL, 9, 12, 0, 1, '鬼谷子', NULL, 36905, '5ac1d6fd9f5454300106d692', '周', 'wen', '文', 'https://baike.baidu.com/item/%E9%AC%BC%E8%B0%B7%E5%AD%90%C2%B7%E6%8F%A3%E7%AF%87/19832356?fr=aladdin', '', '古之善用天下者，必量天下之权，而揣诸侯之情。量权不审，不知强弱轻重之称；揣情不审，不知隐匿变化之动静。何谓量权？曰：“度于大小，谋于众寡。称货财有无，料人民多少、饶乏，有余不足几何？辨地形之险易孰利、孰害？谋虑孰长、孰短？群臣之亲疏，孰贤、孰不肖？与宾客之知睿孰少、孰多？观天时之祸福，孰吉、孰凶？诸候之亲孰用、孰不用？百姓之心去就变化，孰安、孰危？孰好、孰憎？反侧孰便、孰知？如此者，是谓量权。”
揣情者，必以其甚喜之时，往而极其欲也，其有欲也，不能隐其情；必以其甚惧之时，往而极其恶也，具有恶也，不能隐其情：情欲必知其变。感动而不知其变者，乃且错其人勿与语，而更问所亲，知其所安。夫情变于内者，形见于外；故常必以其见者，而知其隐者；此所谓测深揣情。
故计国事者，则当审量权；说人主，则当审揣情；谋虑情欲必出于此。乃可贵、乃可贱、乃可重、乃可轻、乃可利、乃可害、乃可成、乃可败，其数一也。故虽有先王之道、圣智之谋，非揣情，隐匿无所索之。此谋之本也，而说之法也。常有事于人，人莫能先。先事而至，此最难为。故曰“揣情最难守司”。言必时其谋虑，故观蜎飞蠕动，无不有利害，可以生事变。生事看，几之势也。此揣情饰言成文章，而后论之。', '《鬼谷子·揣篇》是春秋时期纵横家鬼谷子创作的一篇散文。', '', '古时候，善于治理天下的人，必然会审慎地把握国家的发展趋势，揣度各诸侯国的具体情形。如果不能周密切实地审时度势，权衡利害，就不会知道诸侯国的强弱情况。如果不能周密地揣度形势，便不知道个中隐蔽的情况的发展变化。什么叫权衡得失呢？就是能准确揣测（对方）大原小，明察多与少，衡量财货有与无，预测百姓众与寡，丰足与贫乏，不足与有余各有多少？（在战争中）分辨山川地貌的险要与平易，哪处与己有利，哪处与己有害，（研究计策时），哪个是长策，哪个是权宜之计。在君臣亲疏关系中，要知道哪些人贤德，哪些人不正派；在谋士与宾客中，哪个足智多谋，哪个是平庸之才。考察命运的福祸时，什么是吉利的，什么是凶险的；与诸侯交谊中，谁是可以效力的，谁是不能效力的；在判断老百姓的心理趋向时，哪种是平安的，哪种是具有危险的，什么是老百姓喜好的，什么是老百姓厌恶的；不顺从者，哪些要审察，哪些可相契。以此明察百姓心理变化的趋势。在准确地把握上述事态发展变化之后，才能称为审时度势，权衡利弊得失。
揣摩人情，游说人主的谋士，应在对方最高兴的时候去游说，要使其愿望极度膨胀。只要对方有欲望，他就不愿隐瞒事物的真实情况。而在对方怀疑，戒惧时去游说他，则要使其对所厌恶的事情恨至极点。倘若对方有所厌恶的事，此时也不会隐瞒其真实情况。（因为）对方在有欲求的时候，常会反映在他们外在神态变化之中。如果对方有所感动，却不显露在外部神态中，可先不要着急，不要与他直面地讨论，可与他说一些另外他能熟悉的东西，说一些使他感到亲近的事情，就可以知道他安身立命不露神色的依据。一般地说来，心中的欲求，能形之于外部神态，因此，不时地察颜观色，就能知道人的心灵深处的欲求。这就是所谓“测深揣情”。
因而，决策国家大事的人，必须会权衡得失利弊；同理，游说人主的谋士，也必须会揣摩人主的心理。策划、谋略、探察人的欲求，均同此理。揣情之术，可以使人富贵，也可以使人贫贱；可以使人有重权，也可以使人微不足道；可以使人受益，也可使人受害；可以使人成功，也可以使人失败；这些都是揣情之术产生的后果。所以，即使有贤明君王的大德，有上智之人的聪慧，若无忖度时势，探人心理的揣情之术，面对着隐藏了真实情况的事实，也依然不能识破它。由此可知，揣情之术是策划事物的基本条件，游说人主的基本法则。事情发生在人们面前，往往人们难以事先预料。（事先预料）是一般人难以做到的。所以说揣情之术是最难以把握运用的。揣情之时，必须根据不同时势、情态作出判断。在现实中，连昆虫的飞行与蠕动，都是按照自身的生理规律存在，应变于环境。世上万物都是利害共生，而且全在变化之中。事情一开始，都会产生一种微小的态势。揣情者，就要用合情合理的言词装饰成文章，而后再与对方论说。', NULL, '', 'indent', 1522681985, '5ac1d7ff4773f7005d50f55c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636917, '鬼谷子 · 摩篇', NULL, 7, 12, 0, 1, '鬼谷子', NULL, 36905, '5ac1d6fd9f5454300106d692', '周', 'wen', '文', 'https://baike.baidu.com/item/%E9%AC%BC%E8%B0%B7%E5%AD%90%C2%B7%E6%91%A9%E7%AF%87/19832352?fr=aladdin', '', '摩者，揣之术也。内符者，揣之主也。用之有道，其道必隐。微摩之以其索欲，测而探之，内符必应；其索应也，必有为之。故微而去之，是谓塞窌匿端，隐貌逃情，而人不知，故能成其事而无患。
摩之在此，符之在彼，从而用之，事无不可。古之善摩者，如操钩而临深渊，饵而投之，必得鱼焉。故曰：主事日成，而人不知；主兵日胜，而人不畏也。圣人谋之于阴，故曰神；成之于阳，故曰明，所谓主事日成者，积德也，而民安之，不知其所以利。积善也，而民道之，不知其所以然；而天下比之神明也。主兵日胜者，常战于不争不费，而民不知所以服，不知所以畏，而天下比之神明。
其摩者，有以平，有以正；有以喜，有以怒；有以名，有以行；有以廉，有以信；有以利，有以卑。平者，静也。正者，宜也。喜者，悦也。怒者，动也。名者，发也。行者，成也。廉者，洁也。信者，期也。利者，求也。卑者，谄也。故圣人所以独用者，众人皆有之；然无成功者，其用之非也。
故谋莫难于周密，说莫难于悉听，事莫难于必成；此三者唯圣人然后能任之。故谋必欲周密；必择其所与通者说也，故曰：或结而无隙也夫事成必合于数，故曰：道、数与时相偶者也。说者听，必合于情；故曰：情合者听。故物归类；抱薪趋火，燥者先燃；平地注水，湿者先濡；此物类相应，于事誓犹是也。此言内符之应外摩也如是，故曰：摩之以其类，焉有不相应者；乃摩之以其欲，焉有不听者。故曰：独行之道。夫几者不晚，成而不拘，久而化成。', '《鬼谷子·摩篇》是春秋时期纵横家鬼谷子创作的一篇散文。出自纵横家游说经验的总结《鬼谷子》，作者为周朝思想家、道家代表人物、纵横家的鼻祖，“王禅老祖”是后人对鬼谷子的称呼，为老学五派之一。', '', '所谓“摩”是一种与“揣情”相类似的方法。内心活动是“揣”的对象。进行“揣情”时，有“揣”的规律可依，而这些规律却是隐而不现的。适当地去“摩”时，要根据对方欲望投其所好进行测探，其内情就会通过外部形象反映出来。内在的感情要表现出来，必然要有所作为，这就是“摩”的作用。在“揣摩”之后，要适当地离开对方，像把地窖盖上一样隐藏起来，消除痕迹，伪装外表，回避实情，使人无法知道是谁办成的这件事。这样，办成了事，却不会留祸患。
在此处“揣摩”对方，而要在另一处，观察对方表现，顺应事物规律，使我方“揣摩”能在对方应验，则办事无所不成。古代善于“摩”的人，就像拿着钓钩到水潭边上去钓鱼一样。只要把带着饵食的钩投入水中，就一定可以钓到鱼。所以说，主办的事情一天天成功，却没有察觉；主持的军队日益压倒敌军，却没人感到恐惧（才是高明的）。圣人谋划什么行动总是在暗中进行的，所以被称为“神”，而办事成功都显现在光天化日之下，所以被称为“明”。所谓“主事日成”的人是暗中积累德行，老百姓安居乐业，却不知道为什么会享受到这些好处，他们还在暗中积累善行，老百姓生活在善政中却不知道为什么会有这样的局面。人们把“谋之于阴，成之于阳”的政治策略称为“神明”。那些主持军队而日益压倒敌人的统帅，坚持不懈的与敌军对抗，却不去争城夺地，消耗人力物力，老百姓也不知道为何敌国拜服，也不知道什么是恐惧。为此，普天下都称“谋之于阴，成之于阳”的军事策略为“神明”。
在实施“摩”时，有用和平进攻的，有用正义征服的，有用娱乐麻痹的，有用愤怒激励的，有用名望威吓的，有用行为逼迫的，有用廉洁感化的，有用信誉说服的，有用利害诱惑的，有用谦卑争取的。和平就是宁静，正义就是刚直，娱乐就是喜悦，愤怒就树威吓，名望就树声誉，行为就是实施，廉洁就是干净，信誉就是清明，利益就是求取，谦卑就是谄媚。所以，圣人所施用的“摩”之术，平常人也都可以具有，然而没有能运用成功的，那是因为他们运用不当。因此，谋划策略，最困难的就是周到慎密；进行游说，最困难的就是让对方全部听从自已的主张；主办事，最困难的就是必办成功。这三个方面只有成为圣人才能胜任。
所以说谋划必须周到慎密；游说要选择与自已观点相通的对象。所以说：“办事情要稳健，无懈可击。”要想使所主持之事取得成功，必须有适当的方法。所以说：“客观规律是与天时互相依附的。”进行游说的人必须使自已的说辞合于情理，合情合理才有人听。世界上万事万物都有各自的规律。好比抱着柴草向烈火走去，干燥的柴草就首先着火燃烧；往平地倒水，湿的地方就要先存水。这些都是与事物的性质相适应的。以此类推，其他事物也是这样的。这就是“内符”与“外摩”的相适应的道理。所以说按着事物的不同特性来实施“摩”之术，哪有不发生反应的呢？根据被游说者的欲望而施行“摩”之术，哪有不听从游说的呢？所以说只有圣人最能实行揣摩之术。大凡通晓机微的人都会把握好时机，有成绩也不居功，天长日久就一定取得成功。', NULL, '', 'indent', 1522682013, '5ac1d81b9f5454300106ddbd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636918, '鬼谷子 · 权篇', NULL, 8, 12, 0, 1, '鬼谷子', NULL, 36905, '5ac1d6fd9f5454300106d692', '周', 'wen', '文', 'https://baike.baidu.com/item/%E9%AC%BC%E8%B0%B7%E5%AD%90%C2%B7%E6%9D%83%E7%AF%87/19832838?fr=aladdin', '', '说者，说之也；说之者，资之也，饰言者，假之也；假之者，益损也。应对者，利辞也；利辞者，轻论也。成义者，明之也；明之者，符验也。难言者，却论也；却论者，钓几也。佞言者，谄而于忠：谀言者，博而于智；平言者，决而于勇；戚言者，权而于信；静言者，反而于胜。先意承欲者，谄也；繁种文辞者，博也；策选进谋者，权也。纵舍不疑者，决也；先分不足而窒非者，反也。
故口者机关也，所以关闭情意也。耳目者，心之佐助也，所以窥间见奸邪。故曰：“参调而应，利道而动。”故繁言而不乱，翱翔而不迷，变易而不危者，观要得理。故无目者，不可示以五色，无耳者，不可告以五音。故不可以往者，无所开之也；不可以来者，无所受之也。物有不通者，故不事也。古人有言曰：“口可以食，不可以言。”言有讳忌也。众口烁金，言有曲故也。
人之情，出言则欲听，举事则欲成。是故智者不用其所短，而用愚人之所长；不用其所拙，而用愚人之所工，故不困也。言其有利者，从其所长也；言其有害者，避其所短也。故介虫之捍也，必以坚厚；螫虫之动也，必以毒螫。故禽兽知用其所长，而谈者知用其所用也。
故曰：“辞言五、曰病、曰怨、曰忧、曰怒、曰喜。”故曰：“病者，感衰气而不神也；怨者，肠绝而无主也；忧者，闭塞而不泄也；怒者，妄动而不治也；喜者，宣散而无要也。”此五者，精则用之，利则行之。故与智者言，依于博；与拙者言，依于辩；与辩者言，依于要；与贵者言，依于势；与富者言，依于高；与贫者言，依于利；与贱者言，依于谦；与勇者言，依于敢；与过者言，依于锐，此其术也，而人常反之。是故与智者言，将此以明之；与不智者言，将此以教之，而甚难为也。故言多类，事多变。故终日言，不失其类，故事不乱。终日变，而不失其主，故智贵不妄，听贵聪，智贵明，辞贵奇。', '《鬼谷子·权篇》是春秋时期纵横家鬼谷子创作的一篇散文。出自纵横家游说经验的总结《鬼谷子》，作者为周朝思想家、道家代表人物、纵横家的鼻祖，“王禅老祖”是后人对鬼谷子的称呼，为老学五派之一。', '', '游说是为了说服对方。说服对方，是为了取用对方的力量。修饰言辞，是为了借助花言巧语来求助他人。求助别人，必须要说明得失。回答他人的问话，要会用外交辞令。所谓机变的外交辞令是一种轻俏的言辞。具有正义与真理价值的言论，必须要阐明真伪；而阐明真伪，就是要验证是否正确。反覆讨论焦点问题，是为了弄清事情的原委。弄清事情原委，是要诱出对方深微的机密。
说着一些奸佞之话的人，会因谄媚而显得忠诚。说着奉承话的人，会因吹捧对方而显得有智慧。说着一些平实之话的人，由于果决而显得勇敢。说忧愁话的人，由于握着权，而显得有信用，而说稳重话的人，却由于能反抗而胜利。用华美的词藻来鼓吹欲望者，就是谄媚。用夸大与吹嘘来进献谋略，博取上司欢心的人，就是揽权者。前后进退而不犹疑者，就是果决的人。自已不对而又指责他人过错的就是反抗者。一般说来，“口”就是人的“政府机关”。用它来封锁、宣传信息。耳目，就是心的辅助器官，用它来侦察奸邪。所以说，只要（口、耳、目）三者相互呼应，就会走向成功。一般说来，虽有繁琐的语言并不纷乱，虽有翱翔之物并不迷惑人，虽有局势的变化并不危险，就是要在观物时，掌握要害。由此可知，没有眼睛的人，没有必要拿五色给他们看；同理，没有耳朵的人，没必要让他们听五音；所以不可以去的地方，不必让他们去，不可以来的人，也没有必要接受他们。有些行不通的事，就不要办。古人有言，说：“嘴可以吃饭，不可以说话。”说的是讲话是有忌讳的。警惕人言可畏，那是可以把事实歪曲的。
人之常情，只要自己说出话，就希望有人听，只要办事情就希望能成功。所以一个聪明人不用自己的短处而用愚者的长处。不用自己的笨处而用愚人的善长，这样就使自己永远不会陷于窘迫。说到有利的一面，就要发挥其长处，说到有害的一面，就要避其短处。因而，甲虫防卫，是用其坚硬的甲壳。而毒虫行动，一定用那有毒的螫子。连禽兽都知道用自己的长处，何况进谏的人，更应该会用游说术了。
所以说，在外交辞令中有五种情况：一是病态之言；二是幽怨之言；三是忧郁之言；四是愤怒之言；五是喜悦之言。一般地说来，病态之言是神气衰弱，说话没精神。幽怨之言是伤心痛苦，没有主见，忧郁之言是心情郁结，不能畅言，愤怒之言是轻举妄动，不能控制自己的话。所谓喜悦之言是说话自由散漫，没有重点。以上这五种外交辞令，精要者可以使用，有利者可以付之实行。所以与智者谈话，就要以渊博为原则，与拙者说话，要以强辩为原则；与善辩的人谈话，要以简要为原则；与高贵的人谈话，要以鼓吹气势为原则；与富人谈话，要以高雅潇洒为原则；与穷人谈话，要以利害为原则；与卑贱者谈话，要以谦恭为原则；与勇敢的人谈话，要以果敢为原则；与上进者谈话，要以锐意进取为原则，这些都是与人谈话的原则。然而不少人却常常背道而驰。所以，与聪明人谈话时，就要让他明了这些方法，与笨人谈话时，就要把这些方法教给他。然而事实上很难作到。所以说谈话有各种方法，所论事情会不断变化。（掌握这些）终日谈论，也不会把事情搞乱。事情不断变化，也不会失其原则。故就智者而言重要的是要不乱不虚，听话善辨真伪，聪颖则善断是非，出言要变化莫测。', NULL, '', 'indent', 1522682043, '5ac1d8392f301e0065fd7bac', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636919, '鬼谷子 · 谋篇', NULL, 10, 12, 0, 1, '鬼谷子', NULL, 36905, '5ac1d6fd9f5454300106d692', '周', 'wen', '文', 'https://baike.baidu.com/item/%E9%AC%BC%E8%B0%B7%E5%AD%90%C2%B7%E8%B0%8B%E7%AF%87/19832920?fr=aladdin', '', '为人凡谋有道，必得其所因，以求其情。审得其情，乃立三仪。三仪者曰上、曰中、曰下。参以立焉，以生奇。奇不知其所拥，始于古之所从。故郑人之取玉也，必载司南之车，为其不惑也。夫度村、量能、揣情者，亦事之司南也。故同情而俱相亲者，其俱成者也；同欲而相疏者，其偏成者也；同恶而相亲者，其俱害者也；同恶而想疏者，其偏害者也。故相益则亲，相损则疏，其数行也，此所以察同异之分，其类一也。故墙坏于其隙，木毁于其节，斯盖其分也。故变生事，事生谋，谋生计，计生议，议生说，说生进，进生退，退生制，因以制于事。故万事一道，而百度一数也。
夫仁人轻货，不可诱以利，可使出费；勇士轻难，不可惧以患，可使据危；智者达于数，明于理，不可欺以诚，可示以道理，可使立功；是三才也。故愚者易蔽也，不肖者易惧也，贪者易诱也，是因事而裁之。故为强者积于弱也；为直者积于曲；有余者积于不足也；此其道术行也。
故外亲而内疏者说内，内亲而外疏者说外。故因其疑以变之，因其见以然之，因其说以要之，因其势以成之，因其恶以权之，因其患以斥之。摩而恐之，高而动之，微而证之，符而应之，拥而塞之，乱而惑之，是谓计谋。计谋之用，公不如私，私不如结，结而无隙者也。正不如奇，奇流而不止者也。故说人主者，必与之言奇；说人臣者，必与之言私。
其身内、其言外者疏；其身外，其言深者危。无以人之所不欲，而强之于人；无以人之所不知，而教之于人。人之有好也，学而顺之；人之有恶也，避而讳之，故阴道而阳取之也。故去之者纵之，纵之者乘之。貌者不美，又不恶，故至情托焉。可知者可用也，不可知者谋者所不用也，故曰：“事贵制人，而不贵见制于人。”制人者握权也，见制于人者制命也。故圣人之道阴，愚人之道阳；智者事易，而不智者事难。以此观之，亡不可以为存，而危不可以为安，然而无为而贵智矣。智用于众人之所不能知，用于众人之所不能见。既用见可，择事而为之，所以自为也；见不可，择事而为之，所以为人也。故先王之道阴，言有之曰：“天地之化，在高与深；圣人之道，在隐与匿。非独忠、信、仁、义也，中正而已矣。”道理达于此义者，则可与语。由能得此，则可与谷远近之义。', '《鬼谷子·谋篇》是春秋时期纵横家鬼谷子创作的一篇散文。出自纵横家游说经验的总结《鬼谷子》，作者为周朝思想家、道家代表人物、纵横家的鼻祖，“王禅老祖”是后人对鬼谷子的称呼，为老学五派之一。', '', '对于一个人来说，凡是筹划计谋都要遵循一定的法则。一定要弄清原由，以便研究实情。根据研究，来确定“三仪”。“三义”就是上、中、下。三者互相渗透，就可谋划出奇计，而奇计是所向无敌的，从古到今都是如此。所以郑国人入山采玉时，都要带上指南针，是为了不迷失方向。付度才干、估量能力、揣度情理，也类似作事时使用指南针一样。所以凡是感系疏远的。事后只能有部分人得利；凡是恶习相同而关系疏远的，一定是部分人先受到损害。所以，如果能互相带来利益，就要密切关系，如果相互牵连地造成损害，就要疏远头系。这都是有定数的事情，也是所以要考察异同的原因。凡是这类事情都是一样的道理。所以，墙壁通常因为有裂缝才倒塌，树木通常因为有节疤而折毁，这都是理所当然的。因此，事情的突变都由于事物自身的渐变引起的，而事物又生谋略，谋略生于计划，计划生义议论，议认生于游说，游说生于进取，进取生于退却，即却生于控制，事物由此得以控制。可见各种事物的道理是一致的，不论反复多少次也都是有定数的。
那些仁人君子必然轻视财货，所以不能用金钱来诱惑他们，反而可以让他们捐出资财；勇敢的壮士自然会轻视危难，所以不能用祸患来恐吓他们，反而可以让他们镇守危地；一个有智慧的人，通达礼教，明于事理，不可假装诚信去欺骗他们，反而可以给他们进清理事理，让他们建功立业。这就是所谓会仁人，勇士、智者的“三才”。因此说，愚者的人容易被蒙蔽，一个不肖之徒容易被恐吓，贪图便宜的人容易被引诱，所有这些都要根据具体情况作出判断。所以强大是由微弱积累而成；直壮是由弯由积累而成；有余是由于不足积累而成。这就是因为“道数”得到了实行。
所以，对那些外表亲善而内心入手进行游说；对那些内心亲善而外表疏远的要从表面入手进行游说。因此，要根据对方的疑问所在来改变自己游说的内容；要根据对方的表现来判断游说是否得法；要根据对方的言辞来归纳出游说的要点；要根据情势的变化适时征服对方；要根据对方可能造成的危害来权衡利弊；要根据对方可能造成的祸患来设法防范。揣摩之后加以威胁；抬高之后加以策动；削弱之后加以扶正；符验之后加以响应；拥堵之后加以阻塞；搅乱之后加以迷惑。这就叫做“计谋”。至于计谋的运用，公开不如保密，保密不如结党，结成的党内是没有裂痕的；正规策略不如奇策，奇策实行起来可以无往不胜。所以向人群进行游说时，必须与他谈论奇策。同样道理，向人臣进行游说时，必须与他谈论私情。
虽然是自己人，却说有利于外人的话，就要被疏远。如果是外人，却知道内情太多，就要有危险。不要拿别人不想要的东西，来强迫人家接受，不要拿别人不了解的事去说教别人。如果对方有某种嗜好，就要仿效以迎合他的兴趣；如果对方厌恶什么，就要加以避讳，以免引起反感。所以，要进行隐密的谋划和公开的夺取。想要除掉的人，就要放纵他，任其胡为，待其留下把柄时就乘机一举除掉他。无论遇到什么事情既不喜形于色也不怒目相待的人，是感情深觉的人，可以托之以机密大事。对于了解透彻的人，可以重用；对那些还没了解透彻的重要的是掌握人，绝对不要被人家控制。控制人的人是掌握大权的统治者；被人家控制的人，是唯命是从的被统治者。所以圣人运用谋略的原则是隐而不露，而愚人运用谋略的原则是大肆张扬。有智慧的人成事容易，没有理智慧的人成事困难。由此看来，一旦国家灭亡了就很难复兴；一旦国家骚乱了，就很难安定，所以无为和智慧是最重要的。智慧是用在众人所不知道的地方，用在众人所看不见的地方。在施展智谋和才干之后，如果证明是可行的，就要选择相应的时机来实行，这是为自己；如果发现是不可行的，也要选择相应的时机来实行，这是为别人。所以古代的先王所推行的大道是属于“阴”的，古语说“天地的造化在于高与深，圣人的治道在于陷与匿，并不是单纯讲求仁慈、义理、忠庆、信守，不过是在维护不偏不倚的正道而已”。如果能彻底认清这种道理的真义，就可以与人交谈，假如双方谈得很投机，就可以发展长远的和目前的关系。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed2107d0ac1145495f974", "shortContent": "清代出现了骈文复兴的局面，文人写作骈文者甚多，同时，也出现了各类评论骈文的著作及骈文选本。在此背景中，李兆洛历时十四年编选了《骈体文钞》，选录战国至隋七百七十余篇作品，并以序申述了自己对骈文的见解。这篇序文篇幅不长，但围绕着“相杂迭用”的中心论点来阐述骈体的意义，立意确当，论述全面。\n首先，以对天地万物自然形态的论述来确认骈体形式的不可否定。古人论文，向以道为本原，作者也从天地之道出发，指出道为一...", "authors": ["陈晓芬"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522682074, '5ac1d8589f5454300106df39', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637351, '笠翁对韵 · 上卷 · 一东', NULL, 201, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '天对地，雨对风。大陆对长空。山花对海树，赤日对苍穹。雷隐隐，雾蒙蒙，日下对天中。风高秋月白，雨霁晚霞红。牛女二星河左右，参商两曜斗西东。十月塞边，飒飒寒霜惊戍旅；三冬江上，漫漫朔雪冷渔翁。
河对汉，绿对红。雨伯对雷公。烟楼对雪洞，月殿对天宫。云叆叇，日曈曚。蜡屐对渔篷。过天星似箭，吐魄月如弓。驿旅客逢梅子雨，池亭人挹藕花风。茅店村前，皓月坠林鸡唱韵；板桥路上，青霜锁道马行踪。
山对海，华对嵩。四岳对三公。宫花对禁柳，塞雁对江龙。清暑殿，广寒宫。拾翠对题红。庄周梦化蝶，吕望兆飞熊。北牖当风停夏扇，南檐曝日省冬烘。鹤舞楼头，玉笛弄残仙子月；凤翔台上，紫箫吹断美人风。', '', '', '', NULL, '', 'indent', 1524654839, '5adff276a22b9d0045326e2b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636921, '鬼谷子 · 符言', NULL, 20, 12, 0, 1, '鬼谷子', NULL, 36905, '5ac1d6fd9f5454300106d692', '周', 'wen', '文', 'https://baike.baidu.com/item/%E9%AC%BC%E8%B0%B7%E5%AD%90%C2%B7%E7%AC%A6%E8%A8%80/19832360?fr=aladdin', '', '安徐正静，其被节先肉。善与而不静，虚心平意以待倾损。右主位。
目贵明，耳贵聪，心贵智。以天下之目视者，则无不见；以天下之耳听者，则无不闻；以天下之心思虑者，则无不知；辐辏并进，则明不可塞。右主明。
德之术曰勿坚而拒之，许之则防守，拒之则闭塞。高山仰之可极，深渊度之可测，神明之德术正静，其莫之极。右主德。
用赏贵信，用刑贵正。赏赐贵信，必验而目之所闻见，其所不闻见者，莫不谙化矣。诚畅于天下神明，而况奸者干君。右主赏。
一曰天之，二曰地之，三曰人之；四方上下，左右前后，荧惑之处安在。右主问。
心为九穷之治，君为五官之长。为善者，君与之赏；为非者，君与之罚。君因其所以求，因与之，则不劳。圣人用之，故能赏之。因之循理，故能长久。右主因。
人主不可不周；人主不周，则群臣生乱，家于其无常也，内外不通，安知所闻，开闭不善，不见原也。右主周。
一曰长目，二曰飞耳，三曰树明。明知千里之外，隐微之中，是谓洞天下奸，莫不谙变更。右主恭。
循名而为贵，安而完，名实相生，反相为情，故曰名当则生于实，实生于理，理生于名实之德，德生于和，和生于当。右主名。', '《鬼谷子·符言》是春秋时期纵横家鬼谷子创作的一篇散文。出自纵横家游说经验的总结《鬼谷子》。', '', '如果身居君位的人能做到安祥、从容、正派、沉静，既会顺又能节制，愿意给予并与世无争，这样就可以心平气和地面对下纷争。以上讲善守其位。
对眼睛来说，最重要的就是明亮；对耳朵来说，最重要的是灵敏，对心灵来说，最重要的就是智慧。人君如果能用全天下的眼睛去观看，就不会有什么看不见的；如果用全天下的耳朵去听，就不会有什么听不到的；如果用全天下的心去思考，就不人有什么不知道的。如果全天下的人都以像车辐条集辏于毂上一样，齐主协力，就可明察一切，无可阻塞。以上讲察之明。
听取情况的方法是：不要远远看见了就答应，也不要远远看见了就拒绝。如果能听信人言，就使自己多了一层保护，如果拒绝别人进言就使自己受到了封闭。高山仰望可看到顶，深渊计量可测到底，而神明的心境既正派又深觉，是无法测到底的。以上虚纳谏。
运用奖赏时，最重要的是守信用。运用刑罚时，贵在坚决。处罚与赏赐的信誉和坚决，应验证于臣民所见所闻的事情，这样对于那些没有亲眼看到的和亲耳听到的人也有潜移默化的作用。人主的诚信如果能畅达天下，那么连神明也会来保护，又何惧那些奸邪之徒犯主君尼？以上讲赏罚必信。
一叫作天时，二叫作地利，三叫作人和。四面作方，上下、左右、前后不清楚的地方在哪？以上讲多方咨询。
心是九窍的统治者，君是五官的首长。做好事的臣民，君主会给他们赏赐；做坏事的臣民，君主会给他们惩罚，君主根据据臣民的政绩来任用，斟酌实际情况给予赏赐，这样就不会劳民伤财。圣人要重用这些臣民，因此能很好地掌握他们，并且要遵循客观规律，所以才能长久，以上讲遵规循理。
作为人主必须广泛了解外界事物，如不通人情道理，那么就容易发生骚乱，世间鸦雀无声是不正常的，内外没有交往，怎么能知道世界的变化。开放和封闭不适当，就无法发现事物的根源。以上讲遍通事理。
一个叫作“长目”，一个叫作“飞耳”，一个叫作“树明”。在一千里之外的地方，隐隐约约、渺渺茫茫之外就叫作“洞”。天下的奸邪的黑暗中也是不变的。以上讲洞察奸邪。
依照名分去考察实际，根据实际来确定名分。名分与实际互为产生的条件，反过来又互相表现。名分与实际相符就能得以治理，不相符则易产生动乱。名分产生于实际，实际产生于意愿，意愿产生于分析，分析产生于智慧，智慧则产生于适当。以上讲名实相符。', NULL, '', 'indent', 1522682149, '5ac1d8a32f301e0065fd7e51', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636927, '史记 · 七十列传 · 管晏列传', NULL, 21, 139, 1, 2, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E7%AE%A1%E6%99%8F%E5%88%97%E4%BC%A0/2438267?fr=aladdin', '', '管仲夷吾者，颍上人也。少时常与鲍叔牙游，鲍叔知其贤。管仲贫困，常欺鲍叔，鲍叔终善遇之，不以为言。已而鲍叔事齐公子小白，管仲事公子纠。及小白立为桓公，公子纠死，管仲囚焉。鲍叔遂进管仲。管仲既用，任政于齐，齐桓公以霸，九合诸侯，一匡天下，管仲之谋也。
管仲曰：「吾始困时，尝与鲍叔贾，分财利多自与，鲍叔不以我为贪，知我贫也。吾尝为鲍叔谋事而更穷困，鲍叔不以我为愚，知时有利不利也。吾尝三仕三见逐于君，鲍叔不以我为不肖，知我不遭时也。吾尝三战三走，鲍叔不以我怯，知我有老母也。公子纠败，召忽死之，吾幽囚受辱，鲍叔不以我为无耻，知我不羞小睗而耻功名不显于天下也。生我者父母，知我者鲍子也。」
鲍叔既进管仲，以身下之。子孙世禄于齐，有封邑者十馀世，常为名大夫。天下不多管仲之贤而多鲍叔能知人也。
管仲既任政相齐，以区区之齐在海滨，通货积财，富国强兵，与俗同好恶。故其称曰：「仓廪实而知礼节，衣食足而知荣辱，上服度则六亲固。四维不张，国乃灭亡。下令如流水之原，令顺民心。」故论卑而易行。俗之所欲，因而予之；俗之所否，因而去之。
其为政也，善因祸而为福，转败而为功。贵轻重，慎权衡。桓公实怒少姬，南袭蔡，管仲因而伐楚，责包茅不入贡于周室。桓公实北征山戎，而管仲因而令燕修召公之政。于柯之会，桓公欲背曹沫之约，管仲因而信之，诸侯由是归齐。故曰：「知与之为取，政之宝也。」
管仲富拟于公室，有三归、反坫，齐人不以为侈。管仲卒，齐国遵其政，常彊于诸侯。后百馀年而有晏子焉。
晏平仲婴者，莱之夷维人也。事齐灵公、庄公、景公，以节俭力行重于齐。既相齐，食不重肉，妾不衣帛。其在朝，君语及之，即危言；语不及之，即危行。国有道，即顺命；无道，即衡命。以此三世显名于诸侯。
越石父贤，在缧绁中。晏子出，遭之涂，解左骖赎之，载归。弗谢，入闺。久之，越石父请绝。晏子惧然，摄衣冠谢曰：「婴虽不仁，免子于缌何子求绝之速也？」石父曰：「不然。吾闻君子诎于不知己而信于知己者。方吾在缧绁中，彼不知我也。夫子既已感寤而赎我，是知己；知己而无礼，固不如在缧绁之中。」晏子于是延入为上客。
晏子为齐相，出，其御之妻从门闲而窥其夫。其夫为相御，拥大盖，策驷马，意气扬扬甚自得也。既而归，其妻请去。夫问其故。妻曰：「晏子长不满六尺，身相齐国，名显诸侯。今者妾观其出，志念深矣，常有以自下者。今子长八尺，乃为人仆御，然子之意自以为足，妾是以求去也。」其后夫自抑损。晏子怪而问之，御以实对。晏子荐以为大夫。
太史公曰：吾读管氏牧民、山高、乘马、轻重、九府，及晏子春秋，详哉其言之也。既见其著书，欲观其行事，故次其传。至其书，世多有之，是以不论，论其轶事。
管仲世所谓贤臣，然孔子小之。岂以为周道衰微，桓公既贤，而不勉之至王，乃称霸哉？语曰「将顺其美，匡救其恶，故上下能相亲也」。岂管仲之谓乎？
方晏子伏庄公尸哭之，成礼然后去，岂所谓「见义不为无勇」者邪？至其谏说，犯君之颜，此所谓「进思尽忠，退思补过」者哉！假令晏子而在，余虽为之执鞭，所欣慕焉。', '《管晏列传》选自西汉文学家、史学家司马迁所著的《史记》，卷六十二、列传第二，是春秋中后期齐国政治家管仲和晏婴的合传。司马迁略去了二人的主要事迹，而「论其轶事」。文章着重选取了管鲍之交、晏婴推荐越石父和作者的故事，娓娓动人，天然成趣，于细微处见精神，字里行间渗透着作者的爱憎。作者惨遭李陵之祸身受腐刑，平生所交不为一言，故写管鲍之交，写晏婴赎越石父，无不是借题发挥。来抒发自己的胸怀。', '管仲：名夷吾，春秋初期政治家。他由鲍叔牙牙推荐，被齐桓公任命为卿，尊称「仲父」，曾辅佐桓公成就霸业。颍上：颍水之滨。颍水源出今河南登封县，流至今安徽寿县入淮水。
鲍叔牙：齐国大夫。
欺：意谓占便宜。
鲍叔牙事齐公子小白：鲍叔牙奉公子小白出奔莒国。公子小白，齐襄公弟，即齐桓公。管仲事公子纠：管仲、召忽奉公子纠出奔鲁国。公子纠，齐襄公弟。
「公子纠死」二句：鲁国畏齐而杀公子纠，管仲请囚。事见《左传·庄公九年》。
进：引荐。
九合诸侯：多次召集各国诸侯会盟。一匡天下：使天下归正。当时诸侯无视周天子，互相攻伐，管仲辅佐齐桓公，一度制止混乱局面。匡，正。
走：逃走。
孙世禄：子孙世世代代享受俸禄。
多：称道，赞美。
上服度则六亲固：如果当权者服御之物有度，那么六亲的关系自然稳固。服，服御，使用。度，制度。六亲，父、母、兄、弟、妻、子。
四维：指礼义廉耻。
「下令」二句：意谓下达政令要像流水的源头一样，顺流而下，使政令合乎百姓心意。
论卑而易行：政令符合下情，容易为人们所执行。
轻重：分清事情的轻重。一说，《管子·轻重》详细论述关于调节商品、货币流通和控制物价的理论，轻重指经济。权衡：衡量事情的得失。
「桓公实怒」二句：少姬即桓公夫人蔡姬，曾荡舟戏弄桓公，桓公惧而变色，禁止不听，于是发怒，遣其归蔡，但未断绝关系。蔡人却将蔡姬改嫁，因此桓公发兵攻蔡。事见《左传·僖公三年》。
拟：相比。三归：说法不一。这里指收取民众大量的市租。
反坫（diàn）：周代诸侯宴会时，在正堂两旁设有放空酒杯的土筑平台叫坫，诸侯互相敬酒后，将酒杯反置在坫上。
晏平仲婴：晏婴字平仲，春秋时齐国大夫。
莱：古国名，在今山东黄县东南。
夷维：今山东高密县。
顺命：顺着命令去做。
三世：齐灵公、庄公、景公三代国君。
越石父：齐国贤人。
缧绁（léixiè）：捆绑犯人的绳索。引申为囚禁。
涂：通「途」。骖：古代指驾在车两旁的马。
戄（jué）然：敬畏的样子。摄：整理。谢：认错，道歉。
感寤：受到感动而醒悟。寤，通「悟」。
延：聘进。
「志念」二句：志向和思想深远，经常表现出自居人下的样子。下，退让，尊人屈己。
抑损：谦逊。
《牧民》、《山高》、《乘马》、《轻重》、《九府》：均为《管子》篇名。
《晏子春秋》：旧题春秋齐晏婴撰，实际上是后人依托并采缀晏子言行而作。
孔子小之：孔子轻视他。《论语·八佾》：「子曰：‘管仲之器小哉！’」
「将顺其美」三句：意谓顺势助成其善事，纠正其过失，因此，君臣就能亲密无间。所言引自《孝经·事君》。
见义不为无勇：见到正义的事而不去做，这是没有勇气。《论语·为政》：「见义不为，无勇也。」
执鞭：为人驾驭马车，意谓给人服役，引申为景仰追随。
欣慕：欣喜爱慕。欣，同「欣」。', '管仲，名夷吾，是颍上人。他年轻的时候，常和鲍叔牙交往，鲍叔牙知道他贤明、有才干。管仲家贫，经常占鲍叔的便宜，但鲍叔始终很好地对待他，不因为这些事而有什么怨言。不久，鲍叔侍奉齐国公子小白，管仲侍奉公子纠。等到小白即位，立为齐桓公以后，桓公让鲁国杀了公子纠，管仲被囚禁。于是鲍叔向齐桓公推荐管仲。管仲被任用以后，在齐国执政，桓公凭借着管仲而称霸，并以霸主的身份，多次会合诸侯，使天下归正于一，这都是管仲的智谋。
管仲说：「我当初贫困的时候，曾经和鲍叔经商，分财利时自己常常多拿一些，但鲍叔不认为我贪财，知道我生活贫困。我曾经为鲍叔办事，结果使他更加穷困，但鲍叔不认为我愚笨，知道时机有利和不利。我曾经多次做官，多次都被君主免职，但鲍叔不认为我没有才干，知道我没有遇到好时机。我曾多次作战，多次战败逃跑，但鲍叔不认为我胆小，知道我还有老母的缘故。公子纠失败，召忽为我而死，我被关在深牢中受屈辱，但鲍叔不认为我无耻，知道我不会为小节而羞，却会因为功名不曾显耀于天下而耻。生我的是父母，了解我的是鲍叔啊！」
鲍叔推荐了管仲以后，情愿把自身置于管仲之下。他的子孙世世代代在齐国享有俸禄，得到封地的有十几代，多数是著名的大夫。因此，天下的人不称赞管仲的才干，反而赞美鲍叔能够识别人才。
管仲出任齐相执政以后，凭借着小小的齐国在海滨的条件，流通货物，积聚财富，使得国富兵强，与百姓同好恶。所以，他在《管子》一书中称述说：「仓库储备充实了，百姓才懂得礼节；衣食丰足了，百姓才能分辨荣辱；国君的作为合乎法度，「六亲」才会得以稳固」「不提倡礼义廉耻，国家就会灭亡。」「国家下达政令就像流水的源头，顺着百姓的心意流下。」所以政令符合下情就容易推行。百姓想要得到的，就给他们；百姓所反对的，就替他们废除。
管仲执政的时候，善于把祸患化为吉祥，使失败转化为成功。他重视分别事物的轻重缓急，慎重地权衡事情的利弊得失。齐桓公实际上是怨恨少姬改嫁而向南袭击蔡国，管仲就寻找借口攻打楚国，责备它没有向周王室进贡菁茅。桓公实际上是向北出兵攻打山戎，而管仲就趁机让燕国整顿召公时期的政教。在柯地会盟，桓公想背弃曹沫逼迫他订立的盟约，管仲就顺应形势劝他信守盟约，诸侯们因此归顺齐国。所以说：「懂得给予正是为了取得的道理，这是治理国家的法宝。」
管仲富贵得可以跟国君相比拟，拥有设置华丽的三归台和国君的宴饮设备，齐国人却不认为他奢侈僭越。管仲逝世后，齐国仍遵循他的政策，常常比其它诸侯国强大。此后过了百余年，齐国又出了个晏婴。
晏平仲，名婴，是齐国莱地夷维人。他辅佐了齐灵公、庄公、景公三代国君，由于节约俭仆又努力工作，在齐国受到人们的尊重。他做了齐国宰相，食不兼味，妻妾不穿丝绸衣服。在朝廷上，国君说话涉及到他，就正直地陈述自己的意见；国君的话不涉及他，就正直地去办事。国君的指示有道理，就服从命令去做，国君的指示没有道理，就根据命令斟酌情况去做。因此，他在齐灵公、庄公、景公三代，名声显扬于各国诸侯。
越石父是个贤才，正在囚禁之中。晏子外出，在路上遇到他，就解开乘车左边的马，把他赎出来，用车拉回家。晏子没有向越石父告辞，就走进内室，过了好久没出来，越石父就请求与晏子绝交。晏子大吃一惊，匆忙整理好衣帽道歉说：「我即使说不上善良宽厚，也总算帮助您从困境中解脱出来，您为什么这么快就要求绝交呢？」越石父说：「不是这样的，我听说君子在不了解自己的人那里受到委屈而在了解自己的人面前意志就会得到伸张。当我在囚禁之中，那些人不了解我。你既然已经受到感动而醒悟，把我赎买出来，这就是了解我；了解我却不能以礼相待，还不如在囚禁之中」于是晏子就请他进屋待为贵宾。
晏子做齐国宰相时，一次坐车外出，车夫的妻子从门缝里偷偷地看她的丈夫。他丈夫替宰相驾车，头上遮着大伞，挥动着鞭子赶着四匹马，神气十足，洋洋得意。不久回到家里，妻子就要求离婚，车夫问她离婚的原因，妻子说：「晏子身高不过六尺，却做了齐的宰相，名声在各国显扬，我看他外出，志向思想都非常深沉，常有那种甘居人下的态度。现在你身高八尺，才不过做人家的车夫，看你的神态，却自以为挺满足，因此我要求和你离婚。」从此以后，车夫就谦虚恭谨起来。晏子发现了他的变化，感到很奇怪，就问他，车夫也如实相告。晏子就推荐他做了大夫。
太史公说：我读了管仲的《牧民》、《山高》、《乘马》、《轻重》、《九府》和《晏子春秋》，这些书上说的太详细了！读了他们的著作，还想让人们了解他们的事迹，所以就编写了他们的合传。至于他们的著作，社会上已有很多，因此不再论述，只记载他们的佚事。
管仲是世人所说的贤臣，然而孔子小看他，难道是因为周朝统治衰微，桓公既然贤明，管仲不勉励他实行王道却辅佐他只称霸主吗？古语说：「要顺势助成君子的美德，纠正挽救他的过错，所以君臣百姓之间能亲密无间。」这大概就是说的管仲吧？
当初晏子枕伏在庄公尸体上痛哭，完成了礼节然后离去，难道是人们所说的「遇到正义的事情不去做就是没有勇气」的表现吗？至于晏子直言进谏，敢于冒犯国君的威严，这就是人们所说的「进就想到竭尽忠心，退就想到弥补过失」的人啊！假使晏子还活着，我即使替他挥动着鞭子赶车，也是我非常高兴和十分向往的啊！', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d6c6e67846a921a0fb", "shortContent": "《史记》的列传，通常是正文叙事，后加论赞，《伯夷列传》则通篇以议论为主，篇末没有论赞；《管晏列传》形式上没有《伯夷列传》那样特殊，但叙事极力概括，而抒情谈话独多，写法也很特别。\n管仲和晏婴，是春秋时齐国的两个名相，其生平行事和言论，见于《管子》、《晏子春秋》、《左传》、《国语》等书的，材料丰富，可写者多。《管晏列传》对于有关两人的著作（非尽出本人之手），只提书名和若干篇名，而于管仲略为摘引《牧民》...", "authors": ["陈祥耀"], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3d730a1d3054c7563f0", "shortContent": "管仲是周穆王的后代，名夷吾，春秋时期齐国颍上（今安徽颍上）人，史称管子，他的一生经历充满了传奇与争议。作为春秋时期最伟大的政治家与思想家，管子的许多观点即便拿到今天来看依然先进。他的伟大不仅是辅佐齐桓公成为霸主，更重要的是开创了自周统一以来，中原少有的安定团结局面，从而保护了华夏文明的传承，此外，他天才地对于政治、军事、经贸、外交等方面都作出了卓有成效的改革和规范。管仲思想汇编而成的《管子》一书，...", "authors": [], "pressName": "上海辞书出版社"}]', '清人王文濡评论说：「通篇无一实笔，纯以清空一气运转。」
现代文学家李景星：「《管晏列传》以逸胜。惊天事业，只以轻描淡写之笔出之，如神龙，然露一鳞一爪，而全神皆见，岂非绝大本领！传赞‘是以不论，论其轶事’二句，是全篇用意。」
现代文学家、历史学家梁启超：「但替两位大政治家作传，用这种走遍锋的观察法，无论如何，我总说是不应该的。因为所选之点太不关痛痒，总不成为正当的好文章。」
现代历史学家钱穆：《管晏列传》近似文学作品，实涵哲学大义，为中国一历史家，又岂止于往事而已。', 'indent', 1522683656, '5ac1de839f5454335169eb68', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (636931, '史记 · 太史公自序', NULL, 7, 139, 0, 1, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E5%A4%AA%E5%8F%B2%E5%85%AC%E8%87%AA%E5%BA%8F/10468474?fr=aladdin', '', '太史公曰：“先人有言：‘自周公卒五百岁而有孔子。孔子卒后至于今五百岁，有能绍明世、正《易传》，继《春秋》、本《诗》、《书》、《礼》、《乐》之际？’”意在斯乎！意在斯乎！小子何敢让焉！
上大夫壶遂曰：“昔孔子何为而作《春秋》哉”？太史公曰：“余闻董生曰：‘周道衰废，孔子为鲁司寇，诸侯害子，大夫雍之。孔子知言之不用，道之不行也，是非二百四十二年之中，以为天下仪表，贬天子，退诸侯，讨大夫，以达王事而已矣。’子曰：‘我欲载之空言，不如见之于行事之深切著明也。’夫《春秋》，上明三王之道，下辨人事之纪，别嫌疑，明是非，定犹豫，善善恶恶，贤贤贱不肖，存亡国，继绝世，补弊起废，王道之大者也。《易》著天地、阴阳、四时、五行，故长于变；《礼》经纪人伦，故长于行；《书》记先王之事，故长于政；《诗》记山川、溪谷、禽兽、草木、牝牡、雌雄，故长于风；《乐》乐所以立，故长于和；《春秋》辨是非，故长于治人。是故《礼》以节人，《乐》以发和，《书》以道事，《诗》以达意，《易》以道化，《春秋》以道义。拨乱世反之正，莫近于《春秋》。《春秋》文成数万，其指数千。万物之散聚皆在《春秋》。《春秋》之中，弑君三十六，亡国五十二，诸侯奔走不得保其社稷者不可胜数。察其所以，皆失其本已。故《易》曰‘失之毫厘，差之千里。’故曰‘臣弑君，子弑父，非一旦一夕之故也，其渐久矣’。故有国者不可以不知《春秋》，前有谗而弗见，后有贼而不知。为人臣者不可以不知《春秋》，守经事而不知其宜，遭变事而不知其权。为人君父而不通于《春秋》之义者，必蒙首恶之名。为人臣子而不通于《春秋》之义者，必陷篡弑之诛，死罪之名。其实皆以为善，为之不知其义，被之空言而不敢辞。夫不通礼义之旨，至于君不君，臣不臣，父不父，子不子。夫君不君则犯，臣不臣则诛，父不父则无道，子不子则不孝。此四行者，天下之大过也。以天下之大过予之，则受而弗敢辞。故《春秋》者，礼义之大宗也。夫礼禁未然之前，法施已然之后；法之所为用者易见，而礼之所为禁者难知。”
壶遂曰：“孔子之时，上无明君，下不得任用，故作《春秋》，垂空文以断礼义，当一王之法。今夫子上遇明天子，下得守职，万事既具，咸各序其宜，夫子所论，欲以何明？”
太史公曰：“唯唯，否否，不然。余闻之先人曰：‘伏羲至纯厚，作《易》八卦。尧舜之盛，《尚书》载之，礼乐作焉。汤武之隆，诗人歌之。《春秋》采善贬恶，推三代之德，褒周室，非独刺讥而已也。’汉兴以来，至明天子，获符瑞，建封禅，改正朔，易服色，受命于穆清，泽流罔极，海外殊俗，重译款塞，请来献见者不可胜道。臣下百官力诵圣德，犹不能宣尽其意。且士贤能而不用，有国者之耻；主上明圣而德不布闻，有司之过也。且余尝掌其官，废明圣盛德不载，灭功臣世家贤大夫之业不述，堕先人所言，罪莫大焉。余所谓述故事，整齐其世传，非所谓作也，而君比之于《春秋》，谬矣。”
于是论次其文。七年而太史公遭李陵之祸，幽于缧绁。乃喟然而叹曰：“是余之罪也夫。是余之罪也夫！身毁不用矣！”退而深惟曰：“夫《诗》、《书》隐约者，欲遂其志之思也。昔西伯拘羑里，演《周易》；孔子厄陈、蔡，作《春秋》；屈原放逐，著《离骚》；左丘失明，厥有《国语》；孙子膑脚，而论兵法；不韦迁蜀，世传《吕览》；韩非囚秦，《说难》、《孤愤》；《诗》三百篇，大抵贤圣发愤之所为作也。此人皆意有所郁结，不得通其道也，故述往事，思来者。”于是卒述陶唐以来，至于麟止，自黄帝始。', '《太史公自序》是西汉史学家司马迁创作的一篇文言文，收录于《史记》中。是《史记》的最后一篇，是《史记》的自序，也是司马迁的自传，人们常称之为司马迁自作之列传。不仅一部《史记》总括于此，而且司马迁一生本末也备见于此。文章气势浩瀚，宏伟深厚，是研究司马迁及其《史记》的重要资料。', '太史公：司马迁自称。
先人：指司马迁的父亲司马谈。
周公：姓姬，名旦，周武王之弟，周成王之叔。武王死时，成王尚年幼，于是就由周公摄政（代掌政权）。周朝的礼乐制度相传是由周公制定的。
《易传》：《周易》的组成部分，是儒家学者对古代占筮用《周易》所作的各种解释。
《春秋》：儒家经典，相传是孔子根据鲁国史官编的《春秋》加以整理、修订而成。
《诗》：《诗经》，儒家经典之一，是我国第一部诗歌总集。
《书》：《尚书》，儒家经典之一，是上古历史文件和部分追述古代事迹著作的汇编，《礼》：儒家经典《周礼》、《仪礼》、《礼记》三书的合作。《乐》：儒家经典之一，今已不传。《易传》、《春秋》、《诗》、《书》、《礼》、《乐》，汉时称“六艺”。
壶遂：人名，曾和司马迁一起参加太初改历，官至詹事，秩二千石，故称“上大夫”。
董生：指汉代儒学大师董仲舒。
孔子为鲁司寇：鲁定公十年（前500），孔子在鲁国由中都宰升任司空和大司寇，是年五十二岁。司寇，掌管刑狱的官。
三王：指夏、商、周三代的开国之君禹、汤、文王。
阴阳：古代以阴阳解释世间万物的发展变化，凡天地万物皆分属阴阳。四时：春、夏、秋、冬四季。五行：水、火、木、金、土等五种基本元素，古人认为它们之间会相生相克。
牝牡（ｐìｎｍǔ聘母）：牝为雌，牡为雄。
指：同“旨”。
弑（ｓｈì是）：古时称臣杀君、子杀父母曰“弑”。
社稷：土神和谷神。古时王朝建立，必先立社稷坛；灭人之国，也必先改置被灭国的社稷坛。故以社稷为国家政权的象征。
伏羲：神话中人类的始祖。曾教民结网，从事渔猎畜牧。据说《易经》中的八卦就是他画的。
尧：传说中我国父系社会后期部落联盟的领袖。舜：由尧的推举，继任部落联盟的领袖。挑选贤才，治理国家，并把治水有功的大禹推为自己的继承人。
《尚书》载之：《尚书》的第一篇《尧典》，记载了尧禅位给舜的事迹。
汤：商朝的建立者。原是商族的领袖，后任用贤相伊尹执政，积聚力量，先后十一次出征，消灭了邻近几个部落。最后一举灭夏，建立商朝。武：周武王，西周王朝的建立者。继承文王的遗志，率部东攻，在牧野（今河南淇县西南）大败商纣王部队，建立周朝。
诗人歌之：《诗经》中有《商颂》五篇，内容多是对殷代先王先公的赞颂。
三代：夏、商、周。
符瑞：吉祥的征兆。汉初思想界盛行“天人感应”之说，此曰“获符瑞”，指公元前122年，汉武帝猎获了一头白麟，于是改元“元狩”。
封禅：帝王祭天地的典礼。秦汉以后成为国家大典。封，在泰山上筑土为坛祭天。禅，在泰山下的梁父山上辟出一块场地祭地。
正朔：正是一年的开始，朔是一月的开始；正朔即指一年的第一天。古时候改朝换代，都要重新确定何时为一年的第一个月，以示受命于天。周以夏历的十一月为岁首；秦以夏历的十月为岁首；汉初承秦制，至汉武帝元封元年（前104）改用“太初历”，才用夏历的正月为岁首，从此直到清末，历代沿用。“改正朔”即指此。
易服色：更改车马、祭牲的颜色。秦汉时代，盛行“五德终始说”。认为每一个朝代在五行中必定占居一德。与此相应，每一朝代都崇尚一种颜色。所谓夏朝为水德，故崇尚黑色；商朝为金德，故崇尚白色；周朝为火德，故崇尚赤色；汉初四十年，汉人认为自己是水德，故崇尚黑色，后经许多人的抗争，到武帝时正式改定为土德，崇尚黄色。
穆清：指天。
重译：经过几重翻译。喻远方邻邦。款塞：叩关。
遭李陵之祸：李陵，陇西成纪（今甘肃秦安）人，汉名将李广之孙，善于骑射，汉武帝时官拜骑都尉。天汉二年（前99），汉武帝出兵三路攻打匈奴，以他的宠妃李夫人之弟、贰师将军李广利为主力，李陵为偏师。李陵率军深入腹地，遇匈奴主力而被围。李广利按兵不动，致使李陵兵败投降。司马迁认为李陵是难得的将才，在武帝面前为他辩解，竟被下狱问罪，处以宫刑。这就是“李陵之祸”。
缧绁（ｌéｉｘｉè雷谢）：原是捆绑犯人的绳索，这里引伸为监狱。
西伯拘羑（ｙǒｕ）里，演《周易》：周文王被殷纣王拘禁在羑里（今河南汤阴县北）时，把上古时代的八卦（相传是伏羲所作）推演成六十四卦，这就是《周易》一书的骨干。
孔子厄陈、蔡，作《春秋》：孔子为了宣传自己的政治主张，曾周游列国，但到处碰壁，在陈国和蔡国，还受到了绝粮和围攻的困厄。其后返回鲁国写作《春秋》。
屈原放逐，著《离骚》：请参阅本编所选《屈原列传》。
左丘：春秋时鲁国的史官。相传他失明以后，撰写成《国语》一书。
孙子膑脚，而论兵法：孙子，即孙膑，因受一种截去两腿膝盖上膑骨的膑刑以后得名。齐国人，曾与庞涓一起从鬼谷子学兵法。后庞涓担任魏国大将，忌孙之才，把孙膑骗到魏国，处以膑刑。孙膑后被齐威王任为军师，著有《孙膑兵法》。
不韦迁蜀，世传《吕览》：不韦即吕不韦，战国末年的大商人。秦庄襄王时，被任为相国，封文信侯。始皇即位，称吕不韦为“尚父”。他曾命门下的宾客编撰了《吕氏春秋》（又称《吕览》）一书。秦始皇亲政后，被免去相国职务，赶出都城，又令迁蜀，忧惧自杀。
韩非囚秦，《说难》、《孤愤》：韩非是战国末期法家的代表，出身韩国贵族。为李斯所谗，在狱中自杀。《说难》、《孤愤》是《韩非子》中的两篇。
《诗》三百篇：今本《诗经》共三百零五篇，这里是指约数。
陶唐：即唐尧。尧最初住在陶丘（今山东定陶县南），后又迁往唐（今河北唐县），故称陶唐氏。《史记》列为五帝之一。
至于麟止：汉武帝元狩元年（前122），猎获白麟一只，《史记》记事即止于此年。鲁哀公十四年（前481），亦曾猎获麒麟，孔子听说后，停止了《春秋》的写作，后人称之为“绝笔于获麟”。《史记》写到捕获白麟为止，是有意仿效孔子作《春秋》的意思。
黄帝：传说中中原各族的共同祖先，姬姓，号轩辕氏、有熊氏。《史记》首篇即《五帝本纪》，黄帝为五帝之首，故云。', '太史公说：“我的父亲生前曾经说过：‘自周公死后，经过五百年才有了孔子。孔子死后，到今天也有五百年了，有谁能继承圣明时代的事业，修正《易传》，续写《春秋》，本于《诗经》、《尚书》、《礼记》、《乐经》的吗？’”他老人家的意思是把希望寄托在我的身上呀！寄托在我的身上呀！小子怎么敢推辞呢！
上大夫壶遂说：“从前，孔子为什么要写《春秋》呢？”太史公说：“我曾听董生说过：‘周朝的政治衰落破败之时，孔子出任鲁国的司寇，诸侯害他，大夫们排挤他。孔子知道他的建议不会被接受了，他的政治主张再也行不通了，于是评判二百四十二年历史中的是是非非，以此作为天下人行动的准则，贬抑天子，斥退诸侯，声讨大夫，以阐明王道。’孔子说：‘我想把我的思想用空话记载下来，但不如通过具体的历史事件来表现更加深刻、明显。’《春秋》，从上而言，阐明了夏禹、商汤、周文王的政治原则；从下而言，辨明了为人处事的纲纪，分清了疑惑难明的事物，判明了是非的界限，使犹豫不决的人拿定了主意，褒善贬恶，崇敬贤能，排抑不肖，保存已经灭亡了的国家，延续已经断绝了的世系，补救政治上的弊端，兴起已经荒废的事业，这些都是王道的重要内容。《易经》显示了天地、阴阳、四时、五行的相互关系，所以长于变化；《仪礼》规定了人与人之间的关系，故长于行动；《尚书》记载了上古先王的事迹，所以长于从政；《诗经》记载了山川、溪谷、禽兽、草木、雌雄、男女，所以长于教化；《乐记》是音乐所以成立的根据，所以长于调和性情；《春秋》明辨是非，所以长于治理百姓。因此，《仪礼》是用来节制人的行为的，《乐记》是用来激发和穆的感情的，《尚书》是用来指导政事的，《诗经》是用来表达内心的情意的，《易经》是用来说明变化的，《春秋》是用来阐明正义的。把一个混乱的社会引导到正确的轨道上来，没有比《春秋》更有用了。《春秋》全书有数万字，其中的要点也有数千。万物万事的分离与聚合，都记在《春秋》里了。《春秋》中，臣杀君的有三十六起，亡国的有五十二个，诸侯四处奔走仍然不能保住国家政权的不计其数。观察他们所以会这样的原因，都在于失去了根本啊！所以《周易》说‘失之毫厘，差之千里’。因此说，‘臣杀君，子杀父，不是一朝一夕才这样的，而是长时期逐渐形成的’。所以，一国之君不可以不知道《春秋》，否则，当面有人进谗他看不见，背后有窃国之贼他也不知道。身为国家大臣的不可以不知道《春秋》，否则，处理一般的事情不知怎样做才合适，遇到出乎意料的事变不知用变通的权宜之计去对付。作为一国之君和一家之长却不懂得《春秋》中的道理，一定会蒙受罪魁祸首的恶名。作为大臣和儿子的不懂得《春秋》中的道理，一定会因为阴谋篡位和杀害君父而被诛杀，得一个死罪的名声。其实，他们都以为自己在干好事，做了而不知道应该怎么做，受了毫无根据的批评而不敢反驳。因为不通礼义的宗旨，以至于做国君的不像国君，做大臣的不像大臣，做父亲的不像父亲，做儿子的不像儿子。做国君的不像国君，大臣们就会犯上作乱；做大臣的不像大臣，就会遭到杀身之祸；做父亲的不像父亲，就是没有伦理道德；做儿子的不像儿子，就是不孝敬父母。这四种行为，是天下最大的过错。把这四种最大的过错加在这些人身上，他们也只能接受而不敢推托。所以《春秋》这部书，是关于礼义的主要经典著作。礼的作用是防患于未然，法的作用是除恶于已然；法的除恶作用容易见到，而礼的防患作用难以被人们理解。”
壶遂说：“孔子的时代，国家没有英明的国君，下层的贤才俊士得不到重用，孔子这才写作《春秋》，流传下这部用笔墨写成的著作来判明什么是礼义，以代替周王朝的法典。现在，您太史公上遇英明的皇帝，下有自己的职守，万事已经具备，都按着适当的顺序进行着，太史公所论述的，想要说明什么宗旨呢？”
太史公说：“对，对！不对，不对！不是这样的。我曾从先父那里听说：‘伏羲最纯朴厚道，他创作了《周易》中的八卦。唐尧、虞舜时代的昌盛，《尚书》上记载了，礼乐就是那时制作的。商汤、周武王时代的兴隆，古代的诗人已经加以歌颂。《春秋》歌颂善人，贬斥恶人，推崇夏、商、周三代的德政，颂扬周王朝，并非全是抨击和讥刺。’自从汉朝建立以来，直到当今的英明天子，捕获白麟，上泰山祭祀天地之神，改正历法，更换车马、祭牲的颜色。受命于上天，德泽流布远方，四海之外与汉族风俗不同的地区，也纷纷通过几重翻译叩开关门，请求前来进献物品和拜见天子，这些事说也说不完。大臣百官尽力歌颂天子的圣明功德，但还是不能把其中的意义阐述透彻。况且，贤士不被任用，这是国君的耻辱；皇上英明神圣而他的美德没能流传久远，这是史官的过错。况且，我曾经做过太史令，如果废弃皇上英明神圣的盛大美德不去记载，埋没功臣、贵族、贤大夫的事迹不去记述，丢弃先父生前的殷勤嘱托，没有什么罪过比这更大了。我所说的记述过去的事情，整理那些社会传说，谈不上创作，而你却把它同孔子作《春秋》相提并论，这就错了。”
于是编写《史记》。过了七年，我因“李陵事件”而大祸临头，被关进了监狱。于是喟然长叹：“这是我的罪过啊！这是我的罪过啊！身体被摧毁了，不会再被任用了！”退居以后又转而深思：“《诗经》和《尚书》辞意隐约，这是作者要表达他们内心的思想。从前文王被囚禁在羑里，就推演了《周易》；孔子在陈国和蔡国受到困厄，就写作《春秋》；屈原被怀王放逐，就写了《离骚》；左丘明眼睛瞎了，这才有了《国语》；孙膑遭受膑刑之苦，于是研究兵法；吕不韦谪迁蜀地，后世却流传着《吕氏春秋》；韩非子被囚禁在秦国，《说难》、《孤愤》才产生；《诗经》三百零五篇，大多是古代的圣贤之人为抒发胸中的愤懑之情而创作的。这些人都是意气有所郁结，没有地方可以发泄，这才追述往事，思念将来。”于是，终于记述了唐尧以来的历史，止于猎获白麟的元狩元年，而从黄帝开始。', NULL, '', 'indent', 1522684572, '5ac1e20f9f54543001072fea', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637012, '渔家傲 · 越女采莲江北岸', NULL, 2, 351, 0, 1, '晏殊', NULL, 10170, '57ba3dadefa631005a794b55', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E6%B8%94%E5%AE%B6%E5%82%B2%C2%B7%E8%B6%8A%E5%A5%B3%E9%87%87%E8%8E%B2%E6%B1%9F%E5%8C%97%E5%B2%B8/9751718?fr=aladdin', '', '越女采莲江北岸，轻桡短棹随风便。人貌与花相斗艳。流水慢，时时照影看妆面。
莲叶层层张绿伞，莲房个个垂金盏。一把藕丝牵不断。红日晚，回头欲去心撩乱。', '《渔家傲·越女采莲江北岸》是北宋词人晏殊所作的一首词。该词描写了采莲女在江边采莲时优雅的身姿和温婉的风情。作者从头到尾都没有使用一句俗艳之语，而是运用大量的细节描写，刻画出少女们艳丽的容颜，高尚的情操，以及她们因情爱萌动而产生的不安于烦躁。', '', '', '[{"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "646790025fc8182fe9aab817", "shortContent": "这首词是晏殊十四首《渔家傲》咏荷词的第十首，描绘了一名美丽的采莲女。这位采莲女出现在江北岸，轻桡短棹，随风来去，时而与荷花争奇斗艳，“芙蓉向脸两边开”（王昌龄《采莲曲》），时而低下头，在缓慢的流水中顾盼容颜。荷叶如伞，莲房如盏，采莲女的心中藏着无数“偶思”，那是对情人的思念。眼看红日就要落山，她乘舟欲去，却又迟疑徘徊，心中缭乱。\n\n五代与北宋词中有不少采莲词，有些是实写，有些则有譬喻意义。晏殊的这...", "authors": ["孔燕妮"], "pressName": "上海辞书出版社"}]', '', 'indent', 1528903986, '5ac3504aa22b9d00454de74f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637027, '文帝议佐百姓诏', NULL, 2, 1, 0, 1, '刘恒', NULL, 36906, '5ac478292f301e00650c118f', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E6%96%87%E5%B8%9D%E8%AE%AE%E4%BD%90%E7%99%BE%E5%A7%93%E8%AF%8F/3220677?fr=aladdin', '', '间者数年比不登，又有水旱疾疫之灾，朕甚忧之。愚而不明，未达其咎。意者朕之政有所失、而行有过与？乃天道有不顺、地利或不得、人事多失和、鬼神废不享与？何以致此？将百官之奉养或费、无用之事或多与？何其民食之寡乏也？
夫度田非益寡，而计民未加益，以口量地，其于古犹有余，而食之甚不足者，其咎安在？无乃百姓之从事于末、以害农者蕃、为酒醪以靡谷者多、六畜之食焉者众与？细大之义，吾未能得其中。其与丞相、列侯、吏二千石、博士议之，有可以佐百姓者，率意远思，无有所隐。', '《文帝议佐百姓诏》这篇文章出自《汉书·文帝纪》，属于诏令类的古文。全文表达了这位封建帝王对百姓疾苦的关心。诏中探求民众疾苦的原因，反复设问，诚意跃然纸上。', '间：jián，近、近来。
比：连续，频繁。
登：作物的成熟和收获。
咎：灾祸、祸根，也可引申为过失。这句是说，不明白它的祸根所在。
度：duó，量，计算，此处为丈量土地。
末：古有士、农、工、商的顺序，商排最末尾。有轻视商的意思。
蕃：繁多。
醪（láo）：酒。靡（mí）：浪费。
六畜：即马、牛、羊、鸡、犬、豕。
义：道理，意义。
二千石：汉代内自九卿郎将，外至郡守，俸禄为二千石。，即月俸百二十斛，这里是以禄俸为职务的代称。
博士：秦及汉初立博士，掌管古今史事待问及书籍典守。到汉武帝时，设五经博士，置弟子员，此后博士专讲经学传授，与文帝、景帝时的博士制度有区别。
率意：竭尽心意。', '近来连续几年作物欠收，又有水灾旱灾和疾病成灾，我非常担忧啊。我愚而不明，不知道导致（这些）问题的原因。我想，我的政策有过失因而执政有过错吗？是天道有不顺、地利或许没有得到、人事大都失去了和睦、鬼神被遗弃没有祭祀吗？为什么会这样呢？养官的俸禄是不是太多了，没用的事是不是做得太多了？为什么民众的粮食会匮乏呢？
计算（一下）田地没有更少，统计民众人口没有增加，按照人口来算田地，那比古人还有多余啊，但吃的东西非常不足的，它的根源在哪里呢？难道是百姓从事商业损害农业的地方很多，还是做酒浪费的谷子很多，禽畜吃掉的粮食很多吗？大大小小的道理，我没能明白它的主要原因，要与丞相、列侯、吏二千石、博士们讨论这个问题，有可以帮助百姓的办法，用心大胆地广开思路，不要有所隐瞒！', NULL, '', 'indent', 1522854089, '5ac478484773f7005d5fb426', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637499, '西泠桥畔醉红树', NULL, 5, 253, 0, 1, '高濂', NULL, 10013, '57ba82a88ac2470063045693', '明', 'wen', '文', '', '', '西泠在湖之西，桥侧为唐一庵公墓，中有枫柏数株，秋来霜红雾紫，点缀成林，影醉夕阳，鲜艳夺目，时携小艇，扶尊登桥吟赏，或得一二新句，出携囊红叶笺书之。临风掷水，泛泛随流，不知漂泊何所，幽情耿耿撩人。更于月夜相对，露湿红新，朝烟凝望，明霞艳日，岂直胜于二月花也！西风起处，一叶飞向尊前，意似秋色怜人，令我腾欢豪举，兴薄云霄，翩翩然神爽哉！何红叶之得我耶！所患一朝枯朽，摧为爨桐，使西泠秋色，色即是空，重惜不住，色相终为毕竟空也。谁能为彼破却生死大劫哉？他日因果，我当作伤时以吊。', '', '', '', NULL, '', 'indent', 1525360872, '5aeab8679f54544f1b798236', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637028, '景帝令二千石修职诏', NULL, 2, 1, 0, 1, '刘启', NULL, 36907, '5ac478a1a22b9d0045542cdd', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E6%99%AF%E5%B8%9D%E4%BB%A4%E4%BA%8C%E5%8D%83%E7%9F%B3%E4%BF%AE%E8%81%8C%E8%AF%8F/861292?fr=aladdin', '', '雕文刻镂，伤农事者也；锦绣纂组，害女红者也。农事伤，则饥之本也；女红害，则寒之原也。夫饥寒并至，而能无为非者寡矣。朕亲耕，后亲桑，以奉宗庙粢盛祭服，为天下先。不受献，减太官，省繇赋，欲天下务农蚕，素有畜积，以备灾害；强毋攘弱，众毋暴寡，老耆以寿终，幼孤得遂长。今岁或不登，民食颇寡，其咎安在？或诈伪为吏，吏以货赂为市，渔夺百姓，侵牟万民。县丞，长吏也，奸法与盗盗，甚无谓也！其令二千石修其职！不事官职耗乱者，丞相以闻，请其罪。布告天下，使明知朕意！', '刘启在位期间，推行“削藩策”，削诸侯封地，平定七国之乱，巩固中央集权，勤俭治国，继续奉行“与民休息”政策，发展生产、减轻赋税。', '雕文刻镂：指在器物上雕刻文采。镂：雕刻。
纂组︰赤色丝带。纂，音“转”。
女红︰女工，指采桑、养蚕、织衣。
为非︰做坏事。
粢盛（chéng）：古时盛在祭器内以供祭祀的谷物。
太官︰管理皇帝饮食的官。
省繇赋︰也作“徭赋”，指徭役、赋税；省：节省；减少徭役和赋税
畜积︰蓄积。
耆：古称六十岁。
遂长︰成长。
侵牟︰剥削、侵蚀。牟，害虫也。
县丞︰县令之佐，属吏之长。
奸法︰因法作奸。与盗盗︰和强盗一同抢夺。
无谓︰没有道理。
耗（mào）乱：昏乱不明。
请︰定。
民事伤：被损害', '在器物上雕镂花纹图形，是损害农业生产的事；编织精致华丽的丝带，是伤害女工的事。农业生产受到损害，就是饥饿的根原；女工受到伤害，就是受冻产生的根原。饥寒同时出现，而能不做坏事的人是很少的。我亲自耕种田地，皇后亲自种桑养蚕，为的是给祭祀祖庙时提供谷物和祭服，为天下人民作个先导。我不接受进献的物品，减少膳食，减少老百姓的徭役赋税，是要天下人民努力种田和养蚕，平时就有积蓄，用来防备灾害。要使强大的不要侵犯弱小的，人多的不要欺凌人少的；使老人能长寿而终其天年，小孩和孤儿们能顺利地成长。
今年收成不好，人民的口粮很少，原因在哪里呢？是不是有些奸诈虚伪的人担任了官职，官吏用财物作交易，掠夺百姓，侵害人民？县丞，是县吏中的首领，他们借着执法的机会做坏事，助盗为盗，这样实在是失去了朝廷设置县丞的用意。命令郡守们各自严格履行自己的职责，对于不忠于职守、昏昧不明的郡守，丞相把他们的情况报告我，要请求治他们的罪。特把这道命令宣告天下，让大家明确知道我的意图。', NULL, '', 'indent', 1522854196, '5ac478b2ee920a0045208d9c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637029, '武帝求茂才异等诏', NULL, 5, 14, 0, 1, '刘彻', NULL, 10394, '57de21b20e3dd900696e07a4', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E6%AD%A6%E5%B8%9D%E6%B1%82%E8%8C%82%E6%89%8D%E5%BC%82%E7%AD%89%E8%AF%8F/7027810?fr=aladdin', '', '盖有非常之功，必待非常之人，故马或奔踶而致千里，士或有负俗之累而立功名。夫泛驾之马，跅弛之士，亦在御之而已。其令州郡察吏民有茂材异等可为将相及使绝国者。', '《武帝求茂才异等诏》是汉武帝选拔社会人才而颁布的诏书。茂才西汉称秀才，东汉避汉光武帝刘秀之讳改称茂才，又常称作“茂才异等”。在西汉属特举科目，汉光武帝时改为岁举。茂才的选拔之是对于有特异才能和有非常之功的低级官吏的提拔。汉武帝求人才，不拘资格，不苛求小节，务期适用，表现了他的雄才大略。把“使绝国”与“将相”并提，也反映了穷兵好武的思想。', '茂才，指优秀的人才。异等：才能出类拔萃的人。
奔踶（dì）：奔驰，踢人。意谓不驯服。
泛（fěng）驾：把车子弄翻，指不受驾驭。
跅（tuo）弛：放纵不羁。
绝国：极为辽远的邦国。', '要建立不同一般的事业，必须依靠特殊的人才。有的马奔跑踢人，却能行千里；有的人受到世俗讥讽，却能建立功名。这些不受驾驭的马和放纵不羁的人，也在于如何驾驭他们罢了。我命令：各州各郡要发现官吏和百姓中那些有优秀才能，超群出众，可担任将相及出使远方的人才。', NULL, '', 'indent', 1522854274, '5ac479012f301e00650c180c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637032, '尚德缓刑书', NULL, 2, 1, 0, 1, '路温舒 ', NULL, 36910, '5ac47b11ee920a0045209dbe', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E5%B0%9A%E5%BE%B7%E7%BC%93%E5%88%91%E4%B9%A6/2401148?fr=aladdin', '', '昭帝崩，昌邑王贺废，宣帝初即位，路温舒上书，言宜尚德缓刑。其辞曰：
“臣闻齐有无知之祸，而桓公以兴；晋有骊姬之难，而文公用伯。近世赵王不终，诸吕作乱，而孝文为太宗。由是观之，祸乱之作，将以开圣人也。故桓、文扶微兴坏，尊文、武之业，
泽加百姓，功润诸侯，虽不及三王，天下归仁焉。文帝永思至德，以承天心，崇仁义，省刑罚，通关梁，一远近，敬贤如大宾，爱民如赤子，内恕情之所安而施之于海内，是以囹圄空虚，天下太平。夫继变化之后，必有异旧之恩，此贤圣所以昭天命也。“往者，昭帝即世而无嗣，大臣忧戚，焦心合谋，皆以昌邑尊亲，援而立之。然天不授命，淫乱其心，遂以自亡。深察祸变之故，乃皇天之所以开至圣也。故大将军受命武帝，股肱汉国，披肝胆，决大计，黜亡义，立有德，辅天而行，然后宗庙以安，天下咸宁。臣闻《春秋》正即位，大一统而慎始也。陛下初登至尊，与天合符，宜改前世之失，正始受命之统，涤烦文，除民疾，存亡继绝，以应天意。
“臣闻秦有十失，其一尚存，治狱之吏是也。秦之时，羞文学，好武勇，贱仁义之士，贵治狱之吏，正言者谓之诽谤，遏过者谓之妖言，故盛服先王不用于世，忠良切言皆郁于胸，誉谀之声日满于耳，虚美熏心，实祸蔽塞，此乃秦之所以亡天下也。方今天下，赖陛下恩厚，亡金革之危、饥寒之患，父子夫妻戮力安家，然太平未洽者，狱乱之也。夫狱者，天下之大命也，死者不可复生，绝者不可复属。《书》曰：“与其杀不辜，宁失不经。”今治狱吏则不然，上下相驱，以刻为明，深者获公名，平者多后患。故治狱之吏，皆欲人死，非憎人也，自安之道在人之死。是以死人之血流离于市，被刑之徒比肩而立，大辟之计岁以万数。此仁圣之所以伤也。太平之未洽，凡以此也。夫人情安则乐生，痛则思死，棰楚之下，何求而不得？做囚人不胜痛，则饰词以视之，吏治者利其然，则指道以明之，上奏畏却，则锻练而周内之；盖奏当之成，虽咎繇听之，犹以为死有余辜。何则？成练者众，文致之罪明也。是以狱吏专为深刻，残贼而亡极，媮为一切，不顾国患，此世之大贼也。故俗语曰：“画地为狱议不入；刻木为吏期不对。”此皆疾吏之风，悲痛之辞也。故天下之患，莫深于狱；败法乱正，离亲塞道，莫甚乎治狱之吏，此所谓一尚存者也。”
“臣闻乌鸢之卵不毁，而后凤凰集；诽谤之罪不诛，而后良言进。故古人有言：“山薮臧疾，川泽纳污，瑾瑜匿恶，国君含诟。”唯陛下除诽谤以招切言，开天下之口，广箴谏之路，扫亡秦之失，尊文武之德，省法制，宽刑罚，以废治狱，则太平之风可兴于世，永履和乐，与天亡极，天下幸甚。”
上善其言。', '《尚德缓刑书》是西汉著名的司法官路温舒所著，文章尖锐地揭露了封建法制运用“逼、供、信”的残忍手段，使人入罪。提出改变重刑罚、重用治狱官吏的政策，主张“尚德缓刑”，“省法制，宽刑罚”。文章除了对狱政黑暗、用刑酷烈的现象进行痛斥外，还对造成冤狱的刑讯逼供表示深恶痛绝，并进行了深入的剖析揭示。', '昭帝：汉昭帝，名刘弗陵，武帝少子。
昌邑王废：公元前74年，汉昭帝死，无嗣，昌邑王刘贺（汉武帝孙子）即位，淫戏无度。大将军霍光用太后的名义废了他，另立汉武帝的曾孙刘询为帝，是为汉宣帝。昌邑：古县名。
臣闻齐有无知之祸，而桓公以兴：无知，春秋时齐公子，自立为齐君。后被人杀死，公子小白自莒回齐即位，便是五霸之一的齐桓公。
晋有骊姬之难，而文公用伯：骊姬，春秋时晋献公宠姬。晋献公伐骊戎（古国名，在今山东临潼县东北），得骊姬，立为夫人，十分宠幸，生奚齐、卓子。不久就谮（读音zèn，诬陷，中伤）杀太子申生，奚齐为太子，公子重耳、夷吾出奔。献公死，奚齐、卓相继为国君，后被杀，骊姬亦被杀。公子重耳回到晋国，立为晋文公。晋文公使晋国成为春秋时一代霸主。
近世赵王不终，诸吕作乱，而孝文为太宗：赵王，汉高祖刘邦的宠姬戚夫人的儿子，名如意，封为赵王。刘邦死，惠帝立，太后吕雉毒死赵王如意，残害戚夫人，吕太后和她的侄儿吕台、吕产、吕禄等专权，想把“刘姓天下”改变为“吕氏王朝”。吕雉死，大臣周勃、陈平等消灭诸吕，迎立代王刘恒即位，是为孝文帝，庙号太宗。后有“文景之治”的繁荣。
关梁：关：关卡，关口。梁：桥梁。
一：统一，动词。
恕：宽容，宽厚。
囹圄：牢狱。
援：援用旧例。
股肱（gōng）：股，大腿；肱，手臂。比喻像左膀右臂一样匡扶国家，即辅佐的意思。
正：把……看得很正统、正规。《春秋》记载古代帝王诸侯即位，很讲究名分，名分正的，就写即位，名分不正的，就不写即位。
大一统：重视天下统一的事业。大，尊重，重视。
始受命：指初即位。统：法制。
文学：先秦时期曾将哲学、历史、文学等书面著作都称为文学，这里指文教方面的事。
遏过：防止过失。
盛服先王：竭力服膺先王的人。先王：指夏禹、商汤、周文王等行仁义道德的帝王。
金革：兵革，这里指战争。
戮力：并力，尽力。
洽：协调。
与其杀不辜，宁失不经：语出《尚书·大禹谟》。不经：不合常规。
大辟：死刑。
棰楚：古代刑具。棰，木棍。楚：荆条。
却：批驳退回。
锻炼：比喻酷吏枉法，多方编造罪名。周：周密。内：同“纳”，归纳。
咎繇（yáo）：舜时建立法律设立监狱的臣子。
成练：构成各种罪名。
文致：文饰而使人获罪。
贼：败坏，伤害。亡：无。
婾（tōu）：苟且，马马虎虎。
画地为狱议不入；刻木为吏期不对：相传上古时期，在地上画圈，令犯罪者立圈中，以示惩罚。画者、刻者都是假的，假的都不愿意忍受，真的就更不能忍受了。表示对监狱、酷吏的愤恨。
乌：乌鸦。鸢（yuān）：老鹰。
诟：耻辱。这四句话出于《左传·宣公十五年》。薮（sǒu）：生长着很多草的湖。瑾瑜：美玉。
箴（zhēn）：劝戒，劝告。', '汉昭帝逝世后，昌邑王刘贺刚继位就被废黜，宣帝开始登上皇位。路温舒趁这个时机上书，主张崇尚德治缓解刑法。书中说：
“我听说齐国有了公孙无知杀死襄公的祸事，桓公才能够兴起；晋国发生了骊姬进谗那样的灾难，文公才能在诸侯中称霸；近世赵王未能寿终而死，诸吕发动叛乱，而孝文帝被尊为太宗皇帝。由此看来，产生祸乱，将会为圣人出现开创机会。所以齐桓公，晋文公扶植、振兴衰败了的国家，尊崇周文王、周武王建立的功业，给百姓带来恩泽，功劳施及诸侯，虽然赶不上夏禹、商汤和周文王，可是天下人民都归附于他们的仁政。孝文帝常常想到如何具备最高的德行，来承受天意，他崇尚仁义，减轻刑罚，打通关隘、架起桥梁，远近如一，敬重贤人如同对待贵宾一样，爱护百姓如同爱护小孩，他用启己的心推想别人的心，把内心觉得安适的事情推行到全国，因此监狱空无一人，天下太平。紧接社会变化以后即位的君主，一定会给人们带来不同往日的恩惠，这是贤明的圣人用来显示天意的行为。”
“从前昭帝去世时没有儿子，大臣们忧愁得很，怀着焦急的心情共同商量，都认为昌邑王是尊贵的皇室亲属，推举他，把他立为皇帝，但是上天不肯授命，而是把他的心弄乱，于是便自己丢失了帝位。很深刻地考虑祸患事变发生的原因，这是伟大的上天用来开导最圣明的君主的手法。所以大将军霍光接受武帝的遗命，成为汉朝君主最得力的辅臣，他披肝沥胆，决定大计，黜退不讲仁义的人，立有德行的人为帝，辅助上天行事，这样祖庙才得安定，天下才都太平无事。”
“我听说《春秋》很重视君王登基的事，这是为了统一天下，为了慎重地对待开创事业。陛下刚登上帝位，与天意符合，应该纠正前代的过错，在承受天命继承帝业时慎重对待开始做的每一件事，去掉烦苛的法令，解除老百姓的疾苦，保存、继承将要消亡、断绝的好传统，用这些行动来应合天意。”
“我听说秦朝有很多失误的地方，其中一条现在还存在，就是负责审案的官吏违法判案的问题。秦朝时候，看不起文学，崇尚武勇精神，轻视奉行仁义的人，重视负责判案的官吏，正直的言论被认为是诽谤，阻拦犯错误的话被说成是妖言，所以那些衣冠整齐的儒生在那时不被重用，忠良恳切的言辞都郁积在胸中，称赞阿谀声天天响在他们耳边，虚伪的赞美迷住了心窍，而实际上存在的祸患被遮蔽、掩盖住了，这就是秦朝失去天下的原因。如今天下靠着陛下恩厚，没有战争的危险和饥饿寒冷的忧患，父子、夫妻合力安家，但是天下太平还未完全实现，原因就是判案的人把事情搞乱了。判案，这是天下最重要的事情，被处死的人不能复活，人被砍断了肢体不能再给他接起来。《书经》上说：“与其杀死无罪的人，宁愿犯不遵守成规旧法酌错误。”现在负责判案的官吏便不是这样，上下相互驱使，把苛刻当作严明，判案严厉的获得公道的名声，判案公平的后来多有祸患。所以负责判案的官吏，都想把人置于死地，并不是他们恨别人，而是他们求得自身安全的办法就在于置人于死地。因此死人的血在街上漂流，受刑的人并肩站着，处死刑的人计算起来每年数以万计。这是奉行仁义的圣人感到悲伤的原因。太平未能完全实现，都是因为这引起的。人们的常情是安适的时候就会显得快乐，痛苦的时候就想要死掉，在木棍荆杖鞭打的时候，从被打人身上有什么要求不能实现呢？所以罪犯忍受不了痛苦，就用些假话招供，审案的官吏就利用这种情况，指出某种罪名，点明罪犯应该招认的罪状，审案的官吏担心案子报上去后会被驳倒退回来，于是便违法罗织罪状，套上罪名，到了报告上级判罪结果的时候，即使是咎繇听了囚犯的罪状，也认为处死也抵偿不了他的罪过。为什么呢？这是因为审案的官吏违法陷入于罪、广列罪名，玩弄法律条文把罪状写得十分明显的缘故。因此审案的官吏专门苛刻严峻地对待犯人，残害人没有止境，办一切事情都马马虎虎，不顾国家遭到祸患，这是世上的大害。所以俗话说道：“在地上画一座监狱，也不进去；面对着木刻的狱吏，也不与他对话。”这反映出社会上痛恨狱吏的风气，是很悲痛的语言。所以天下的祸害，没有什么比得上法官判案这件事。败坏法纪，扰乱正道，使亲人分离，道义不明，没有谁比负责判案的官吏更厉害的。这就是我所说的秦朝的过错有一条至今还存在的原因。”
“我听说鹞鹰下的蛋不会遭到毁坏，然后凤凰才会停留在树上；犯了诽谤罪的人不会受到惩罚，然后才有人向朝廷说出有益的话。所以古人有种说法：“山林水泽隐藏着毒害人的东西，河流湖泊容纳污秽的东西，美玉隐藏着瑕斑，国君能容忍辱骂。”愿陛下除去诽谤人的罪名，用来招致恳切的忠言，让天下人开口说话，扩大人们规劝、进谏的渠道，扫除造成秦朝灭亡的过错，尊崇周文王、周武王的德行，减省法制条文，宽缓刑罚，用这些来清除治狱的积弊，那么天下就可以出现太平的气象，长期和平安乐，和天地一样没有穷尽，那样，人民就太幸运了。”
皇上很满意路温舒的意见。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d90ce818559d064c49", "shortContent": "西汉路温舒《尚德缓刑书》，是一篇富有文化意义的历史文献，也是一篇富有文学价值的散文作品。\n元平元年（前74），汉昭帝死，霍光等大臣迎昌邑王刘贺即皇位。昌邑王行淫乱，在位二十七日被废黜。霍光等又迎生长于民间的武帝曾孙刘询即皇位，是为汉宣帝。次年，改元本始元年（前73）。《汉书》卷五一《路温舒传》：“会昭帝崩，昌邑王贺废，宣帝初即位，温舒上书言宜尚德缓刑。”并著录上书全文。可见班史之郑重此事。本文主题...", "authors": ["邓小军"], "pressName": "上海辞书出版社"}]', '', 'indent', 1522854885, '5ac47b564773f7005d5fc9f8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637033, '报孙会宗书', NULL, 3, 2, 0, 1, '杨恽', NULL, 18110, '5858ec691b69e60056f6447b', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E6%8A%A5%E5%AD%99%E4%BC%9A%E5%AE%97%E4%B9%A6/3437016?fr=aladdin', '', '恽材朽行秽，文质无所底，幸赖先人余业，得备宿卫。遭遇时变，以获爵位。终非其任，卒与祸会。足下哀其愚，蒙赐书教督以所不及，殷勤甚厚。然窃恨足下不深惟其终始，而猥随俗之毁誉也。言鄙陋之愚心，若逆指而文过；默而息乎，恐违孔氏各言尔志之义。故敢略陈其愚，惟君子察焉。
恽家方隆盛时，乘朱轮者十人，位在列卿，爵为通侯，总领从官，与闻政事。曾不能以此时有所建明，以宣德化，又不能与群僚同心并力，陪辅朝庭之遗忘，已负窃位素餐之责久矣（。怀禄贪势，不能自退，遂遭变故，横被口语，身幽北阙，妻子满狱。当此之时，自以夷灭不足以塞责，岂意得全首领，复奉先人之丘墓乎？伏惟圣主之恩不可胜量。君子游道，乐以忘忧；小人全躯，说以忘罪。窃自念过已大矣，行已亏矣，长为农夫以末世矣。是故身率妻子，戮力耕桑，灌园治产，以给公上，不意当复用此为讥议也。
夫人情所不能止者，圣人弗禁。故君父至尊亲，送其终也，有时而既。臣之得罪，已三年矣。田家作苦。岁时伏腊，烹羊炰羔，斗酒自劳。家本秦也，能为秦声。妇赵女也，雅善鼓瑟。奴婢歌者数人，酒后耳热，仰天抚缶而呼乌乌。其诗曰：“田彼南山，芜秽不治。种一顷豆，落而为萁。人生行乐耳，须富贵何时！”是日也，奋袖低昂，顿足起舞；诚淫荒无度，不知其不可也。恽幸有余禄，方籴贱贩贵，逐什一之利。此贾竖之事，污辱之处，恽亲行之。下流之人，众毁所归，不寒而栗。虽雅知恽者，犹随风而靡，尚何称誉之有？董生不云乎：“明明求仁义，常恐不能化民者，卿大夫之意也。明明求财利，常恐困乏者，庶人之事也。”故道不同，不相为谋，今子尚安得以卿大夫之制而责仆哉〕！
夫西河魏土，文侯所兴，有段干木、田子方之遗风，漂然皆有节概，知去就之分。顷者足下离旧土，临安定，安定山谷之间，昆戎旧壤，子弟贪鄙，岂习俗之移人哉？于今乃睹子之志矣！方当盛汉之隆，愿勉旃，毋多谈。', '《报孙会宗书》选自《汉书·杨恽传》，是西汉的杨恽写给孙会宗的一封著名书信。在信中，他以嬉笑怒骂的口吻，逐点批驳孙的规劝，为自己狂放不羁的行为辩解。还赋诗讥刺朝政，明确表示“道不同，不相为谋”，与“卿大夫之制”决裂的意向。全信写得情怀勃郁，锋芒毕露，与司马迁《报任少卿书》桀骜不驯的风格如出一辙。', '材朽行秽（huì），才能低劣品行肮脏。文质，文采和质朴，指文章、道德。底，至，到，“底”通“抵”。赖，依靠。先人，指已经去世的父亲杨敞。馀业，遗留的功业。备，备员，充数。宿卫，在宫中值宿警卫，这是郎官的职责。杨恽曾任郎官。
时变，时局变故，指霍氏谋反、杨恽告发之事。以，连词，用法同“而”。爵位，指扬恽所获的“平通侯”。
终，终究。其，代第一人称。任，胜任，指胜任的官职。卒，最终，最后。会，遭遇，？碰到。
足下，古代下称上或同辈相称的敬辞，可译为“您”。哀，哀怜。其，代第一人称。愚蒙，愚笨蒙昧。教督，教导督正。所不及，没有做到的地方。殷勤，恳切的情意。
然，转折连词，可是。窃，谦指自己，私下。恨，遗憾。推，推究，推寻。其，那件事。终始，首尾经过，原委。猥（wěi），副词，随随便便地。俗，世俗，社会上一般人。毁誉，偏义复词，义偏于“毁”，毁谤。
鄙陋，浅薄粗陋。愚心，愚昧的见解。若，好像。逆指，违背来信的旨意。文（wén）过，掩饰自己的过错。默，不说话；息，歇止，停止；乎，语气词，吧；默而息乎，默不作声吧。孔氏，孔子。各言尔志，各人说说你们的志向。《论语·公冶长》：“颜渊、季路侍。子曰：‘盍各言尔志。’”
敢，表敬副词，冒昧地。略，简略地，稍微。陈，陈述。其愚，我的愚见。惟，句首语气词，表希望。君子，对孙会宗的称呼。察，审察。焉，代词兼语气词，于是。
方，正，正当。隆盛，兴盛，兴旺。朱轮，指高官所乘的马车，车轮是红色的。汉制，公卿列侯及二千石以上的官员可以乘朱轮马车。
列卿，指九卿之列。九卿是古代中央政府的九个高级官职，各朝各代名称不全相同。汉代的九卿是：太常、光禄勋、卫尉、太仆、廷尉、大鸿胪、宗正、大司农、少府。通侯，即列侯。汉制，刘姓子孙封侯者，叫诸侯；异姓功臣封侯者，叫列侯，也叫彻侯，后避武帝（刘彻）讳，改“彻侯”为“通侯”。总领，统领。从官，皇帝的侍从官。杨恽曾任“诸吏光禄勋”，所有侍从官都归他管理，并负责监察弹劾群官。与（yù）闻，参与和知晓。
曾（zēng），乃，竟。建明，建树倡明。陪辅，辅助，辅佐。负，担负，这儿指遭受。窃位，窃取官位，指不能恪尽职守。素餐，白吃，指不劳而获、白吃官俸。责，指责，责备。
怀、贪，思念，贪图。变故，意外发生的灾难，指杨恽被戴长乐上书告罪之事。
横（héng），意外地。被，遭受。口语，这儿指毁谤诬陷之语。幽，幽禁，关押。北阙，古代宫殿北面的观阙，是大臣上章奏事或被皇帝召见的地方。妻子，妻子儿女。
自以，自己认为。夷灭，消灭，指杀戮。塞责，抵塞罪责。意，意料，料想。全，保全。首领，头颈。丘墓，坟墓。
伏惟，伏在地上想，表敬之辞。圣主，皇帝，指汉宣帝。胜，尽。量，估量。
游道，游于大道，即学习道义之事，浸身道义之中。以，连词，而。说（yuè），通“悦”，？高兴。
过，过失，过错。行，品行。亏，缺失，欠缺。长（cháng），长久，永远。没（mò）世，过完一辈子。
是故，因为这个缘故，因此。戮（lù）力，合力，齐心合力。耕桑，耕田植桑，泛指农业生产。灌园，浇灌园圃。治产，治理产业。以，连词，表目的，以便，用来。给（jǐ），供给；公上，公家、主上；给公上，供给国家税收。用此，因此，以此。
夫（fú），句首语气词。人情，人之常情。止，禁止。
君父至尊亲，君至尊，父至亲。这是修辞上的“分承表示法（并提）”。送其终，为他们送终、服丧。有时，有一定时限。古代臣子为君父服丧三年。既，尽，终。
作苦，劳作辛苦。岁，指年；时，指春夏秋冬四季。伏、腊，夏天的伏日、冬天的腊日，秦汉时都是节日。伏，指夏至后第三个庚日（即初伏）；腊，冬至后的第三个戌日（后世以阴历十二月初八日为腊日，即“腊八”）。伏腊都是祭日。烹（pēng），煮；炰（páo），烤。劳（lào），慰劳。
家本秦也，我家本来是秦地人。杨恽是华阴人，华阴本属秦地。雅，甚，很。瑟（sè），一种乐器，有弦可供敲击。古代赵国妇女多善音乐。
拊（fǔ），拍，轻击。缶（fǒu），古乐器，瓦制，腹大口小，秦人歌唱时常按节击缶。乌乌，呜呜，唱歌的声音。
田，用作动词，种田。萁（qí），豆茎。须，等待。治、萁、时，押韵。这段歌词隐含了对朝廷的讽刺，唐颜师古《汉书》注引张晏云：“山高而在阳，人君之象也。芜秽不治，言朝廷之荒乱也。一顷百亩，比喻百官也。言豆者，贞实之物，零落在野，喻己见放逐也。萁曲而不直，言朝臣皆谄谀也。”
奋袖，挥舞衣袖。低昂，高低起伏。顿足，跺脚。
籴（dí），买进（粮食）。逐，追求。什一之利，十分之一的利息。
贾（gǔ），商人；竖（shù），奴仆，童仆；贾竖，对商人的贱称。污辱之处，肮脏受辱的？地方。下流，原指水的下游，这里比喻卑贱的身份和受辱的境地。归，归往一处。不寒而栗（lì），不寒冷而发抖。栗，战栗，颤抖。虽，即使，即便。犹，尚且。靡（mǐ），倒下。尚，还。何称誉之有，有何称誉，宾语前置句。
董生，董仲舒（前179—前104年），西汉哲学家，汉景帝、汉武帝时的大儒。明明，意同“皇皇”，匆急慌忙的样子。化民，感化老百姓。困乏，穷困。这两句话引自董仲舒《对贤良策》三，原文是：“夫皇皇求财利，常恐乏匮者，庶人之意也。皇皇求仁义，常恐不能化民者，大夫之意也。”
道不同，不相为谋：这是引用《论语·卫灵公》的话，意思是思想信仰不同的人，不在一起谋划事情。尚，还。安得，怎么能够。制，标准。责，要求。仆，第一人称的谦称，我。
西河魏土，战国时期魏国的西河在今陕西合阳一带，与汉代的西河郡（今内蒙古伊克昭盟东胜县）不是一个地方。杨恽故意把孙会宗的家乡讲成是战国魏地，是为了与下文的安定郡对照，讽刺孙会宗。文侯，指战国时期魏国的始创之君魏文侯（前445—前396年在位），是著名的贤君。兴，建立，创建。
段干木，战国高士，魏人。魏文侯请他作宰相，他坚辞不受，文侯乃以客礼待之，尊他为师。田子方，也是魏文侯的老师，文侯视他为国宝。遗风，遗留下来的美好风范。
凛（lǐn）然，严肃不可侵犯的样子。一本作“漂然”，意同“飘然”，高远之貌。节概，节操气概。去就，辞官隐居和出仕为官。分，分别。
顷者，最近，近来。旧土，这儿指家乡。临，光临，来到。昆戎，古代西夷的一支，即殷周时的西戎，是当时西方的一个种族。旧壤，旧地。子弟，指后辈子孙。贪鄙，贪婪卑劣。移人，改变人的志向情操。
于今，到现在。乃，才。睹，看清。隆，指鼎盛时期。愿，希望。旃（zhān），“之焉”的合音字。毋（wú），不要。', '我才能低下，行为卑污，外部表现和内在品质都未修养到家，幸而靠着先辈留下的功绩，才得以充任宫中侍从官。又遭遇到非常事变，因而被封为侯爵，但始终未能称职，结果遭了灾祸。你哀怜我的愚昧，特地来信教导我不够检点的地方，恳切的情意甚为深厚。但我私下却怪你没有深入思考事情的本末，而轻率地表达了一般世俗眼光的偏见。直说我浅陋的看法吧，那好象与你来信的宗旨唱反调，在掩饰自己的过错；沉默而不说吧，又恐怕违背了孔子提倡每人应当直说自己志向的原则。因此我才敢简略地谈谈我的愚见，希望你能细看一下。
我家正当兴盛的时候，做大官乘坐朱轮车的有十人，我也备位在九卿之列，爵封通侯，总管宫内的侍从官，参与国家大政。我竟不能在这样的时候有所建树，来宣扬皇帝的德政，又不能与同僚齐心协力，辅佐朝廷，补救缺失，已经受到窃踞高位白食俸禄的指责很久了。我贪恋禄位和权势，不能自动退职，终于遭到意外的变故，平白地被人告发，本人被囚禁在宫殿北面的楼观内，妻子儿女全关押在监狱里。在这个时候，自己觉得合族抄斩也不足以抵偿罪责，哪里想得到竟能保住脑袋，再去奉祀祖先的坟墓呢？我俯伏在地想着圣主的恩德真是无法计量。君子的身心沉浸在道义之中，快乐得忘记忧愁；小人保全了性命，快活得忘掉了自身的罪过。因此亲自率领妻子儿女，竭尽全力耕田种粮，植桑养蚕，灌溉果园，经营产业，用来向官府交纳赋税，想不到又因为这样做而被人指责和非议。
人的感情所不能限制的事情，圣人也不加以禁止。所以即使是最尊贵的君王和最亲近的父亲，为他们送终服丧，至多三年也有结束的时候。我得罪以来，已经三年了。种田人家劳作辛苦，一年中遇上伏日、腊日的祭祀，就烧煮羊肉烤炙羊羔，斟上一壶酒自我慰劳一番。我的老家本在秦地，因此我善于秦地的乐器。妻子是赵地的女子，平素擅长弹瑟。奴婢中也有几个会唱歌的。喝酒以后耳根发热，昂首面对苍天，信手敲击瓦缶，按着节拍呜呜呼唱。歌词是：“在南山上种田辛勤，荆棘野草多得没法除清。种下了一顷地的豆子，只收到一片无用的豆茎。人生还是及时行乐吧，等享富贵谁知要到什么时辰！”碰上这样的日子，我兴奋得两袖甩得高高低低，两脚使劲蹬地而任意起舞，的确是纵情玩乐而不加节制，但我不懂这有什么过错。我幸而还有积余的俸禄，正经营着贱买贵卖的生意，追求那十分之一的薄利。这是君子不屑只有商人才干的事情，备受轻视耻辱，我却亲自去做了。地位卑贱的人，是众人诽谤的对象，我常因此不寒而栗。即使是素来了解我的人，尚且随风而倒讥刺我，哪里还会有人来称颂我呢？董仲舒不是说过吗：“急急忙忙地求仁求义，常担心不能用仁义感化百姓，这是卿大夫的心意。急急忙忙地求财求利，常担心贫困匮乏，这是平民百姓的事情。”所以信仰不同的人，互相之间没有什么好商量的。现在你还怎能用卿大夫的要求来责备我呢！
西河魏地，是魏文侯兴起的地方，那里有段干木、田子方留下来的风尚，他们二位都具有高尚的节操，懂得什么时候该辞官不作、什么时候该出来做官。近来你离开了故乡，到了安定郡。安定郡位于山谷中间，是昆夷的故乡，那里的人多是贪婪卑鄙，难道是当地的风俗习惯改变了你的品性吗？在今天我才看清了你的志节！如今正当兴旺的汉朝处于鼎盛的时期，望你努力，不多谈了。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d8911759740c9bdc97", "shortContent": "杨恽是司马迁外孙，其父曾任丞相，素有才干。他初为郎官，因上告霍氏（霍光的子孙）谋反有功而被封为平通侯，旋即升中郎将，直至郎中令，在朝廷很有声望。他为人坦率，刚直无私，秉性傲岸，好“揭人阴私”，故招来许多人的怨恨和嫉妒。后遭皇帝近臣太仆戴长乐诬告，而被贬为庶人。杨恽自然心怀不满，闲居后便治产业，造宅室，引起朝臣非议。友人安定郡太守孙会宗为此心感不安，便写信告诫他，认为大臣废退，当闭门惶恐，做出一种可...", "authors": ["田和平"], "pressName": "上海辞书出版社"}]', '“行文之法，字字翻腾，段段收束，平直处皆曲折，疏散处皆紧炼，则酷肖其外祖。”（清人余诚《重订古文释义新编》卷六）', 'indent', 1522854952, '5ac47ba6ee920a004520a261', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637056, '茶经 · 五之煮', NULL, 22, 14, 0, 1, '陆羽', NULL, 13217, '584432e0c59e0d0056a3b0e9', '唐', 'wen', '文', '', '', '凡灸茶，慎勿于风烬间灸，熛焰如钻，使炎凉不均。持以逼火，屡其翻正，候炮出培塿状，虾蟆背，然后去火五寸，卷而舒则本其始，又灸之。若火干者，以气熟止；日干者，以柔止。其始若茶之至嫩者，茶罢热捣叶烂而牙笋存焉。假以力者，持千钧杵亦不之烂，如漆科珠，壮士接之不能驻其指，及就则似无禳骨也。灸之，则其节若倪，倪如婴儿之臂耳。既而承热用纸囊贮之，精华之气无所散越。候寒末之其火用炭，次用劲薪。其炭曾经燔灸，为膻腻所及，及膏木败器不用之。古人有劳薪之味，信哉！其水，用山水上，江水中，井水下。其山水，拣乳泉石池漫流者上，其瀑涌湍漱勿食之，久食令人有颈疾。又多别流于山谷者，澄浸不泄，自火天至霜郊以前，或潜龙畜毒于其间，饮者可决之以流其恶，使新泉涓涓然酌之。其江水，取去人远者。井取汲多者。其沸如鱼目，微有声为一沸，缘边如涌泉连珠为二沸，腾波鼓浪为三沸，已上水老不可食也。初沸则水合量，调之以盐味，谓弃其啜余，无乃而钟其一味乎？第二沸出水一瓢，以竹策环激汤心，则量末当中心，而下有顷势若奔涛，溅沫以所出水止之，而育其华也。凡酌置诸碗，令沫饽均。沫饽，汤之华也。华之薄者曰沫，厚者曰饽，细轻者曰花，如枣花漂漂然于环池之上。又如回潭曲渚，青萍之始生；又如晴天爽朗，有浮云鳞然。其沫者，若绿钱浮于水渭，又如菊英堕于鐏俎之中。饽者以滓煮之。及沸则重华累沫，皤皤然若积雪耳。《荈赋》所谓“焕如积雪，烨若春艹敷”，有之。第一煮水沸，而弃其沫之上，有水膜如黑云母，饮之则其味不正。其第一者为隽永，或留熟以贮之，以备育华救沸之用。诸第一与第二第三碗，次之第四第五碗，外非渴甚莫之饮。凡煮水一升，酌分五碗，乘热连饮之，以重浊凝其下，精英浮其上。如冷则精英随气而竭，饮啜不消亦然矣。茶性俭，不宜广，则其味黯澹，且如一满碗，啜半而味寡，况其广乎！其色缃也，其馨也。其味甘樌也；不甘而苦，荈也；啜苦咽甘，茶也。', '', '炮出培塿状虾蟆背：炮，烘烤。培塿，小土堆。塿读lou。 虾蟆背，有很多丘泡，不平滑，形容茶饼表面起泡如虾蟆背。
如漆科珠：科，用斗称量。《说文》：“从禾，从斗。斗者，量也”。这句意为用漆斗量珍珠，滑溜难量。
劳薪之味：劳薪，即膏木、败器。用膏木、败器之类烧烤，食物会有异味。典出《晋书 荀勖传》。
挹：挹，读yi，舀取。
自火天至霜郊：火天，七月酷暑时节。《诗经 七月》：“七月流火”。霜郊，霜初降大地。“霜降”在农历九月下旬，霜郊则指秋末冬初。
如鱼目：水初沸时冒出的小气泡，像鱼眼睛，故称鱼目。
水湄：有水草的河边。《说文》：“湄，水草交为湄”。
樽俎：樽是酒器，俎是砧板，这里指各种餐具。
皤皤然：皤，读音po。皤皤，满头白发的样子。这里形容白色水沫。
烨若春敷 ：烨，读ye，光辉明亮。敷，读fu，花。《集韵》：“敷，花之通名。', '烤饼茶，注意不要在通风的馀火上烤，因为飘忽不定的火苗像钻子，使茶受热不均匀。烤饼茶时要靠近火，不停地翻动，等到烤出突起的像虾蟆背上的小疙瘩，然后离火五寸。当卷曲的茶饼又伸展开，再按先前的办法又烤。如果制茶时是用火烘干的，以烤到冒热气为度；如果是用太阳晒干的，以烤到柔软为好。
开始，对于很柔嫩的茶叶，蒸后乘热捣杵，叶捣烂了，而茶梗还是完整的。如果只用蛮力，拿很重的杵杆也捣不烂它。这就如同圆滑的漆树子粒，虽然轻而小，但壮士反而捍不住它是一个道理。捣好后，好像一条梗子也没有了。这时来烤，柔软得像婴儿的手臂。烤好了，趁热用纸袋装起来，使它的香气不致散发，等冷了再碾成末。
烤饼茶的火，最好用木炭，其次用火力强的柴（如桑、槐之类）。曾经烤过肉，染上了腥膻油腻气味的炭，或是有油烟的柴以及朽坏的木器，都不能用。古人说：''用朽坏的木制器具烧煮食物，会有怪味''，确实如此。
煮茶的水，用山水最好，其次是江河的水，井水最差。山水，最好选取乳泉、石池漫流的水（这种水流动不急），奔涌湍急的水不要饮用，长喝这种水会使人颈部生病。几处溪流汇合，停蓄于山谷的水，水虽澄清，但不流动。从热天到霜降前，也许有龙潜伏其中，水质污染有毒，要喝时应先挖开缺口，把污秽有毒的水放走，使新的泉水涓涓流来，然后饮用。江河的水，到离人远的地方去取，井水要从有很多人汲水的井中汲取。
水煮沸了，有像鱼目的小泡，有轻微的响声，称作''一沸''。锅的边缘有泡连珠般的往上冒，称作''二沸''。水波翻腾，称作''三沸''。再继续煮，水老了，味不好，就不宜饮用了。
开始佛腾时，按照水量放适当的盐调味，把尝剩下的那点水泼掉。切莫因无味而过分加盐，否则，不就成了特别喜欢这种盐味了吗！第二沸时，舀出一瓢水，再用竹夹在沸水中转圈搅动，用''则''量茶末沿旋涡中心倒下。过一会，水大开，波涛翻滚，水沫飞溅，就把刚才舀出的水掺入，使水不再沸腾，以保养水面生成的''华''。来自微信：edutea
喝时，舀到碗里，让''沫饽''均匀。''沫饽''就是茶汤的''华''。薄的叫''沫''，厚的叫''饽''，细轻的叫''花''。''花''的外貌，很像枣花在圆形的池塘上浮动，又像回环曲折的潭水、绿洲间新生的浮萍，又像晴朗天空中的鳞状浮云。那''沫''，好似青苔浮在水边，又如菊花落入杯中。那''饽''，煮茶的渣滓时，水一沸腾，面上便堆起很厚一层白色沫子，白白的像积雪一般。《荈赋》中讲的''明亮像积雪，光彩如春花''，真是这样。
第一次煮开的水，把沫上一层像黑云母样的膜状物去掉，它的味道不好。此后，从锅里舀出的第一道水，味美味长，谓之''隽永''，通常贮放在''熟盂''里，以作育华止沸之用。以下第一、第二、第三碗，味道略差些。第四、第五碗之外，要不是渴得太厉害，就值不得喝了。一般烧水一升，分作五碗，趁热接着喝完。因为重浊不清的物质凝聚在下面，精华浮在上面，如果茶一冷，精华就随热气跑光了。要是喝得太多，也同样不好。
茶的性质''俭''，水不宜多放，多了，它的味道就淡薄。就像一满碗茶，喝了一半，味道就觉得差些了，何况水加多了呢！茶汤的颜色浅黄，香气四溢。味道甜的是''荈''，不甜的而苦的是''槚''；入口时有苦味，咽下去又有馀甘的是''茶''。', NULL, '', 'indent', 1522955608, '5ac604d52f301e0065153a43', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637034, '光武帝临淄劳耿弇', NULL, 5, 1, 0, 1, '刘秀', NULL, 36911, '5ac47dc017d0090061700988', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E5%85%89%E6%AD%A6%E5%B8%9D%E4%B8%B4%E6%B7%84%E5%8A%B3%E8%80%BF%E5%BC%87/5962959?fr=aladdin', '', '车驾至临淄，自劳军，群臣大会。帝谓弇曰：“昔韩信破历下以开基；今将军攻祝阿以发迹。此皆齐之西界，功足相方。而韩信袭击已降，将军独拔勍敌，其功乃难于信也。又田横烹郦生，及田横降，高帝诏卫尉不听为仇；张步前亦杀伏隆，若步来归命，吾当诏大司徒释其怨。又事尤相类也。将军前在南阳，建此大策，常以为落落难合，有志者事竟成也。”', '《光武帝临淄劳耿弇》是写光武帝刘秀表彰大将军耿弇的一段话。他先表彰耿弇的功劳，以淮阴侯韩信作衬托；再用“有志者事竟成”激励之。', '临淄：县者。原春秋战国时齐国的都城，在今山东淄博西北。耿弇：字伯昭，扶风茂陵人（今陕西兴平东北）人，曾随刘秀起兵，后拜建威大将军，封好畤侯。在扫平齐地割据势力张步的战争中，立有大功。
车驾：即车，皇帝外出时乘用，因代指皇帝。这里指汉光武帝刘秀。
韩信破历下：汉高帝三年，韩信袭击历下军，占领齐国首都临淄。
祝阿：地名，故地在今山东长清县。光武帝建武五年春，张步屯军祝阿，耿弇率兵讨伐，大破张步。后两军又战于临淄，时光武帝车驾亲自劳军，事在建武五年冬。
西界：历下，祝阿都是古时齐，鲁的分界，在齐国的西部。
袭击已降：韩信袭破历下之前，刘邦已派郦食其到齐，游说齐王。齐王同意与汉和好，并撤除了对汉的防御。韩信趁其不备袭击齐军，并攻灭齐国。
勍敌：劲敌。实力强大的敌人。
田横烹郦生：当韩信袭历下时，田横以为郦生出卖了自己，便将郦生烹杀。
卫尉：官名。即郦商，郦食其的弟弟，刘邦即位后封信成侯。刘邦曾警告郦商不得报仇。
张步等二句：光武帝派光禄大夫伏隆拜张步为东海太守，刘永也遣使立张步为齐王。张步接受刘永的封号，杀了伏隆。大司徒，伏隆的父亲伏湛。
将军二句：耿弇在南阳跟从刘秀，曾自请北收上谷兵（王莽时、耿父为上谷太守）、平定渔阳的彭宠，涿郡的张丰、向东消灭张步、平定齐地。刘秀同意了他的策略。', '光武帝来到临淄，亲自慰劳军队，群臣在这里隆重地聚会。光武帝对耿弇说：“从前韩信因攻破历下而开创基业，现在将军您攻取祝阿而立身扬名。历下和祝阿都是齐国的西界，你与韩信的功绩也足以相比。但韩信袭击的是已经降伏的对手，而将军却独力战胜强大的敌人，这个功绩的取得，确实要比韩信难。再说田横烹杀了郦生，等到田横投降，汉高帝下诏告诫卫尉郦商，不许他与田横结仇。张步也曾杀过伏隆，如果张步前来归降，我也要下诏给司徒伏湛，要他消除仇怨。这两件事又更加相似了。将军从前在南阳时，就提出了这项重要的计策，我原以为迂远疏阔，很难实现，现在看来，真是有志者事竟成啊！”', NULL, '', 'indent', 1522855518, '5ac47ddd4773f7005d5fdb8e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637035, '孙子兵法 · 始计篇', NULL, 83, 13, 0, 1, '孙武', NULL, 36849, '59e714859545040067513674', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%99%E5%AD%90%E5%85%B5%E6%B3%95%C2%B7%E5%A7%8B%E8%AE%A1%E7%AF%87/19828239?fr=aladdin&fromid=9033988&fromtitle=%E5%A7%8B%E8%AE%A1%E7%AF%87', '', '孙子曰：
兵者，国之大事，死生之地，存亡之道，不可不察也。
故经之以五事，校之以计，而索其情：一曰道，二曰天，三曰地，四曰将，五曰法。道者，令民与上同意也，故可以与之死，可以与之生，而不畏危。天者，阴阳、寒暑、时制也。地者，高下、远近、险易、广狭、死生也。将者，智、信、仁、勇、严也。法者，曲制、官道、主用也。凡此五者，将莫不闻，知之者胜，不知者不胜。故校之以计，而索其情，曰：主孰有道？将孰有能？天地孰得？法令孰行？兵众孰强？士卒孰练？赏罚孰明？吾以此知胜负矣。
将听吾计，用之必胜，留之；将不听吾计，用之必败，去之。
计利以听，乃为之势，以佐其外。势者，因利而制权也。
兵者，诡道也。故能而示之不能，用而示之不用，近而示之远，远而示之近。利而诱之，乱而取之，实而备之，强而避之，怒而挠之，卑而骄之，佚而劳之，亲而离之。攻其无备，出其不意。此兵家之胜，不可先传也。
夫未战而庙算胜者，得算多也；未战而庙算不胜者，得算少也。多算胜，少算不胜，而况于无算乎！吾以此观之，胜负见矣。', '《孙子兵法·始计篇》是春秋时期兵法家孙武创作的一篇散文。。讲的是庙算，即出兵前在庙堂上比较敌我的各种条件，估算战事胜负的可能性，并制订作战计划。', '兵：兵士、兵器、军队、军事，此指军事。
地：引申为领域。
道：道理，这里指的根本道理。
察：观察、了解、考察，这里指考察。
经：经度，引申为分析、研究。
校：作动词，较量、比较。
道：道理，道路。这里可引申为治国的路线或方针政策。
阴阳：我国古代一对概括宇宙万象万物内在基本矛盾的范畴。这里是从气象和天象上讲，指天气晴雨，天象昼夜的变化。
曲制：曲，指古代军队编制较小的单位，曲制即军队的编制。
官道：官，指军队中的各级指挥员，官道即指对军队各级将领的职责划分和管理形式、管理制度。
主用：主，主持，这里可解释为掌管。用，费用，这里指军队的物资费用。主用，就是指对军队后勤军需的管理。
强：强壮，这里指士兵体质强壮。
练：训练，这里指军士训练有素。
将：这里作时间副词，可引申为衡量。
计利以听：计，计较，这里引申为衡量。计利，就是指权衡利益。听，听从。
乃为之势：势，这里指形势、情势。
以佐其外：佐，辅佐，引申为有助于。其，指示代词，这里指实现战略或战役目标的计划。外，指外部环境或客观环境。
诡道也：诡，欺诈。道，这里作途径解，引申为方法、计谋。诡道，指欺诈的方法和计谋。
实而备之：实，实力。这里指敌军充实雄厚。备，准备。
怒而挠之：挠，挑逗。
庙，庙算，指庙堂上的计划与谋划。', '孙子说：战争是国家的大事，它关系到百姓的生死，国家的存亡，不能不认真地思考和研究。
因此，要通过对敌我五个方面的情况进行综合比较，来探讨战争胜负的情形：一是政治，二是天时，三是地势，四是将领，五是制度。政治，就是要让民众和君主的意愿一致，战时他们才会为君主去死，不存二心。天时，就是指昼夜、晴雨、寒冷、炎热、季节气候的变化。地势，就是指高陵洼地、路途远近、险隘平坦、进退方便等条件。将领，就是指挥者所具备的智慧、诚信、仁爱、勇猛、严明等素质。制度，就是军制、军法、军需的制定和管理。凡属这五个方面的情况，将领都不能不知。充分了解这些情况的就能取胜，相反就会作战失败。此外，还要通过比较双方的具体条件来探究战争胜负的情形，即双方君主哪一方施政清明？哪一方将帅更有才能？哪一方拥有更好的天时地利？哪一方军纪严明？哪一方兵力强大？哪一方士卒训练有素？哪一方赏罚分明？通过这些分析比较就能够判断谁胜谁负了。
若听从我的意见，用兵作战就会取胜，我就留下来；若是不从，打仗就会失败，我将会离开这里。
我的军事思想您认为能够接受，再从外交上造成大好形势作为辅助条件，就掌握了主动权。所谓态势，即是凭借有利的情况，以制定临机应变的策略。
战争，本来是一种诡诈之术。所以，能战而示之软弱；要打，装作退却；要攻近处，装作攻击远处；要想远袭，又装作近攻；敌人贪利，就用小利引诱；敌人混乱就要攻取；敌人力量充实，就要防备；敌人兵强卒锐，就避其锋头；敌人气势汹汹，就设法扰乱它；敌人谦卑就要使之骄横；敌人安逸就要使之疲劳；敌人内部和睦，就要离间他们。总之，要在敌人没有防备处攻击，在敌人料想不到的时候采取行动。这是指挥家制胜的秘诀，不可预先讲明。未战之前就能预料取胜的，是因为筹划周密，条件充分；未开战而估计取胜把握小，是具备取胜的条件少。条件充分的取胜就大，准备不充分的就会失败。何况一点条件也不具备的呢！我根据这些来观察战争，胜败也就清楚了。', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701f6542516c6deeef2", "shortContent": "这是《孙子兵法》开首《计》篇的第一句话。应该说，此言是一个警句。孙子用深沉的语调告诫人们：“兵者，国之大事，死生之地，存亡之道，不可不察也。”兵，原指兵器。《说文解字》云：“兵，械也。”后引申为战士、军队和战争。这里的“兵”，即指战争。古人说：“国之大事，在祀与戎。”（《左传·成公十三年》）可知古人把祭祀天神祖先和用兵打仗作为国家的头等大事。孙子在这里说战争是“国之大事”，还因为它是“死生之地，存...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701f6542516c6deeef3", "shortContent": "孙子认为：“兵者，诡道也”，用现代的话来说：用兵打仗，是诡诈的方法和行为。这些诡诈的方法，是兵家克敌制胜的奥妙所在。\n\n综观《孙子兵法》中的“诡道”战术，约可分为以下十四种：（一）示形。即给敌人显示假象，使其造成错觉而作出错误的行动，从而给我军以可乘之机。上引《计》篇中的“能而示之不能，用而示之不用；近而示之远，远而示之近”，都属于这一类。\n\n（二）利诱。即以利益为诱饵使敌人出击，然后歼灭他。上引...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701f6542516c6deeef4", "shortContent": "孙子在《计》篇中论述“兵者，诡道也”，然后从“能而示之不能”到“亲而离之”，列举大量运用“诡道”而胜敌的方法，最后总结道：“攻其无备，出其不意。此兵家之胜，不可先传也。”可知“攻其无备，出其不意”，乃孙子“诡道”战法的核心所在。钱基博《孙子章句训义》云：“‘能而示之不能’至‘亲而离之’十二语为目，而‘攻其无备’二语是纲，乃总结‘能而示之不能’十二语而明其妙用。”“诡道虽多，两言蔽之，不过曰‘攻其无...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1522855951, '5ac47f839f54542110b67f50', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637036, '孙子兵法 · 作战篇', NULL, 36, 13, 0, 1, '孙武', NULL, 36849, '59e714859545040067513674', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%99%E5%AD%90%E5%85%B5%E6%B3%95%C2%B7%E4%BD%9C%E6%88%98%E7%AF%87/19831518?fr=aladdin&fromid=7179065&fromtitle=%E4%BD%9C%E6%88%98%E7%AF%87', '', '孙子曰：凡用兵之法，驰车千驷，革车千乘，带甲十万，千里馈粮。则内外之费，宾客之用，胶漆之材，车甲之奉，日费千金，然后十万之师举矣。
其用战也胜，久则钝兵挫锐，攻城则力屈，久暴师则国用不足。夫钝兵挫锐，屈力殚货，则诸侯乘其弊而起，虽有智者不能善其后矣。故兵闻拙速，未睹巧之久也。夫兵久而国利者，未之有也。故不尽知用兵之害者，则不能尽知用兵之利也。
善用兵者，役不再籍，粮不三载，取用于国，因粮于敌，故军食可足也。国之贫于师者远输，远输则百姓贫；近师者贵卖，贵卖则百姓财竭，财竭则急于丘役。力屈、财殚，中原、内虚于家，百姓之费，十去其七；公家之费，破军罢马，甲胄矢弓，戟楯蔽橹，丘牛大车，十去其六。故智将务食于敌，食敌一钟，当吾二十钟；萁秆一石，当吾二十石。故杀敌者，怒也；取敌之利者，货也。车战得车十乘以上，赏其先得者而更其旌旗。车杂而乘之，卒善而养之，是谓胜敌而益强。
故兵贵胜，不贵久。
故知兵之将，生民之司命。国家安危之主也。', '《孙子兵法·作战篇》是春秋时期兵法家孙武创作的一篇散文。。讲的是庙算后的战争动员及取用于敌，胜敌益强。“作”是“兴起”之意。“作战”这里不是指战争，而是指战争前的准备和筹划，属于“未战而庙算”的范畴。本篇继《计篇》之后，在“慎战论”思想的指导下，着重分析了战争与经济的关系，战争依赖于经济，但会对经济造成一定程度的破坏。', '', '孙子说：要兴兵作战，需做的物资准备有，轻车千辆，重车千辆，全副武装的士兵十万，并向千里之外运送粮食。那么前后方的军内外开支，招待使节、策士的用度，用于武器维修的胶漆等材料费用，保养战车、甲胄的支出等，每天要消耗千金。按照这样的标准准备之后，十万大军才可出发上战场。
因此，军队作战就要求速胜，如果拖的很久则军队必然疲惫，挫失锐气。一旦攻城，则兵力将耗尽，长期在外作战还必然导致国家财用不足。如果军队因久战疲惫不堪，锐气受挫，军事实力耗尽，国内物资枯竭，其他诸侯必定趁火打劫。这样，即使足智多谋之士也无良策来挽救危亡了。所以，在实际作战中，只听说将领缺少高招难以速胜，却没有见过指挥高明巧于持久作战的。战争旷日持久而有利于国家的事，从来没有过。所以，不能详尽地了解用兵的害处，就不能全面地了解用兵的益处。
善于用兵的人，不用再次征集兵员，不用多次运送军粮。武器装备由国内供应，从敌人那里设法夺取粮食，这样军队的粮草就可以充足了。国家之所以因作战而贫困，是由于军队远征，不得不进行长途运输。长途运输必然导致百姓贫穷。驻军附近处物价必然飞涨，物价飞涨，必然导致物资枯竭，物财枯竭，赋税和劳役必然加重。在战场上，军力耗尽，在国内财源枯竭，百姓私家财产损耗十分之七。公家的财产，由于车辆破损，马匹疲惫，盔甲、弓箭、矛戟、盾牌、牛车的损失，而耗去十分之六。所以明智的将军，一定要在敌国解决粮草，从敌国搞到一钟的粮食，就相当于从本国启运时的二十钟，在当地取得饲料一石，相当于从本国启运时的二十石。所以，要使士兵拼死杀敌，就必须怒之，激励之。要使士兵勇于夺取敌方的军需物资，就必须以缴获的财物作奖赏。所以，在车战中，抢夺十辆车以上的，就奖赏最先抢得战车的。而夺得的战车，要立即换上我方的旗帜，把抢得的战车编入我方车队。要善待俘虏，使他们有归顺之心。这就是战胜敌人而使自己越发强大的方法。。所以，作战最重要、最有利的是速胜，最不宜的是旷日持久。真正懂得用兵之道、深知用兵利害的将帅，掌握着民众的的生死，主宰着国家的安危。', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701f6542516c6deeef5", "shortContent": "在阐述了用兵作战要求速胜，“久则钝兵挫锐”，“久暴师则国用不足”，以及久拖不决“则诸侯乘其弊而起”便无法收拾等论题后，孙子总结道：“夫兵久而国利者，未之有也。”其意是说，长久用兵作战而对国家有利，乃从来没有的事。这是千真万确的。\n\n比孙子时代略早的老子就说过：“兵者，不祥之器。”“大军之后，必有凶年。”唐代杜佑注《孙子》此句说：“兵者凶器，久则生变。”近人陈启天作《孙子兵法校释》云：“征之历史，凡...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701f6542516c6deeef6", "shortContent": "这是孙子对《作战》全篇思想的总结。所谓“贵胜”，就是贵在速胜。孟氏注：“贵速胜疾还也。”梅尧臣注：“速则省财用、息民力也。”张预注：“久则师老财竭，易以生变，故但贵其速胜疾归。”按照孙子的战略思想，出兵打仗，贵在速胜，胜后马上归还；不贵在与敌方持久困守，师劳力竭。\n\n孙子提倡“兵贵胜，不贵久”，是有其众多原因的。首先，“日费千金，然后十万之师举矣。”军队有众多的人员和武器装备，粮食和饲草要长途运往...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701f6542516c6deeef7", "shortContent": "这是孙子在《作战》篇最后对军队将帅重要性的总结言论。所谓“司”，即主持、掌握。全句意为：知道如何用兵的将领，是掌握民众性命的人，是国家安危的主宰者。张预注：“民之死生，国之安危，系乎将之贤否。”深得孙子本意。诸葛亮《心书》有云：“夫将者，人命之所悬也，成败之所系也，祸福之所倚也。”也是谈论将帅的重要作用的，其意与孙子所述相似，真是英雄所见略同。\n\n掌握着人民的性命、国家的安危，在历史上发挥重大作用...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1522856008, '5ac47fc69f54541656f61495', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637037, '孙子兵法 · 谋攻篇', NULL, 41, 13, 0, 1, '孙武', NULL, 36849, '59e714859545040067513674', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%99%E5%AD%90%E5%85%B5%E6%B3%95%C2%B7%E8%B0%8B%E6%94%BB%E7%AF%87/19831520?fr=aladdin&fromid=5484359&fromtitle=%E8%B0%8B%E6%94%BB%E7%AF%87', '', '孙子曰：夫用兵之法，全国为上，破国次之；全军为上，破军次之；全旅为上，破旅次之；全卒为上，破卒次之；全伍为上，破伍次之。是故百战百胜，非善之善者也；不战而屈人之兵，善之善者也。
故上兵伐谋，其次伐交，其次伐兵，其下攻城。攻城之法，为不得已。修橹轒輼，具器械，三月而后成，距堙，又三月而后已。将不胜其忿而蚁附之，杀士卒三分之一而城不拔者，此攻之灾也。
故善用兵者，屈人之兵而非战也，拔人之城而非攻也，毁人之国而非久也，必以全争于天下，故兵不顿，而利可全，此谋攻之法也。
故用兵之法，十则围之，五则攻之，倍则分之，敌则能战之，少则能逃之，不若则能避之。故小敌之坚，大敌之擒也。
夫将者，国之辅也，辅周则国必强，辅隙则国必弱。
故君之所以患于军者三：不知军之不可以进而谓之进，不知军之不可以退而谓之退，是谓縻军。不知三军之事而同三军之政者，则军士惑矣。不知三军之权而同三军之任，则军士疑矣。三军既惑且疑，则诸侯之难至矣。是谓乱军引胜。
故知胜有五：知可以战与不可以战者胜；识众寡之用者胜；上下同欲者胜；以虞待不虞者胜；将能而君不御者胜。此五者，知胜之道也。
故曰：知彼知己，百战不殆；不知彼而知己，一胜一负；不知彼，不知己，每战必殆。', '《孙子兵法·谋攻篇》是春秋时期兵法家孙武创作的一篇散文。', '全国：全，完整、完全，这里作动词，指完全地占有。全国：指完整地占有别国的领土。
全军：军，春秋时期的军队编制，每军为12500人。旅：春秋时期军队的编制，每旅为500人。卒：春秋时期军队的编制，每卒为100人。伍：春秋时期军队的编制，每伍5人。
上兵伐谋：上，上等最好的。兵，指用兵方法。伐，攻击。谋，计谋。
修橹：修，建造。橹，一种用藤草制成的大盾牌；一种用桃木制成四周用牛皮遮蔽的大型攻城战车。
蚁附：蚁，蚂蚁。附，依附。
久：这里指旷日持久的战争。
必以全争于天下：这里指的是对敌国的全国、全军、全旅、全卒、全伍的胜利。
顿，通“钝”，疲惫、挫折。
谋攻：用计谋进行攻伐。
十则围之：十，这里指的是十倍。围，包围。
倍则分之：分，分开。
少则能逃之：少，指我方兵力的数量比敌军少。
小敌之坚：坚，坚固，引申为硬拼。
大敌之擒：战争中兵力强大的一方。
国之辅：国，这里指国君。
縻军：縻，羁縻。指束缚军队的行动。
三军之政：三军，指我国古代作战设置的上、中、下或左、中、右三军，亦可泛指军队。政，是指政务。
惑，困惑。
识众寡之用：识，了解。众多。寡，寡少。识众寡之用，了解用众多的兵力或者用人数少的兵力的各种战法。
上下同欲：君主或统帅和下级军官有相同的欲望。
虞：料想，这里引申为牵制，掣肘。
知胜之道：能预测胜利的方法。
殆：危险。', '孙子说：大凡用兵的原则，使敌人举国屈服，不战而降是上策，击破敌国就次一等；使敌全军降服是上策，打败敌人的军队就次一等；使敌人一个“旅”的队伍降服是上策，击破敌人一个“旅”就次一等；使敌人全“卒”降服是上策，打败敌人一个“卒”的“队伍就次一等；使敌人全“伍”投降是上策，击破敌人的“伍”就次一等。因此，百战百胜，不算是最好的用兵策略，只有在攻城之前，先让敌人的军事能力（包括指挥能力和作战能力）严重短缺，根本无力抵抗，才算是高明中最高明的。
所以上等的用兵策略是以谋取胜，其次是以外交手段挫敌，再次是出动军队攻敌取胜，最下策才是攻城。攻城为万不得已时才使用。制造攻城的蔽橹、轒辒，准备各种攻城器械，需要花费三个月的时间。构筑攻城的土山又要三个月。将帅控制不住忿怒的情绪，驱使士卒像蚂蚁一样去爬梯攻城，使士卒伤亡三分之一而不能攻克，这便是攻城所带来的危害。
因此，善于用兵的人，使敌人屈服而不是靠战争，攻取敌人的城池而不是靠硬攻，消灭敌国而不是靠久战，用完善的计策争胜于天下，兵力不至于折损，却可以获得全胜，这就是以谋攻敌的方法。
用兵的原则是：有十倍的兵力就包围敌人，五倍的兵力就进攻敌人，两倍的兵力就分割消灭敌人，有与敌相当的兵力则可以抗击，兵力少于敌人就要避免与其正面接触，兵力弱少就要撤退远地。所以弱小的军队顽固硬拼，就会变成强大敌军的俘虏。
将帅，是国家的辅佐，辅佐周密国家就会强大；辅佐疏漏，未尽其职，国家必然衰弱。国君对军队造成的危害有三种情况：不知道军队在什么条件下可战而使其出击，不了解军队在什么情况下可退而使其撤退，这就束缚了军队的手脚。不通详三军内务，而插手三军的政事，就会使部队将士不知所从。不了解军中的权变之谋而参与军队的指挥，就会使将士们疑虑重重。军队既迷惑又疑虑，诸侯国军队乘机而进攻，灾难就降临到头上，这就是自乱其军而丧失了胜利。
预知取胜的因素有五点：懂得什么条件下可战或不可战，能取胜；懂得兵多兵少不同用法的，能取胜；全军上下一心的，能取胜；以有备之师待无备之师的，能取胜；将帅有才干而君主不从中干预的，能取胜。这五条，是预知胜利的道理。
所以说：了解对方也了解自己的，百战不败；不了解敌方而熟悉自己的，胜负各半；既不了解敌方，又不了解自己，每战必然失败。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d2c6e67846a921a0f0", "shortContent": "本文是《孙子》十三篇中的第三篇。题为“谋攻”，意思是在计谋上攻破敌人。孙武认为在局部战役中不顾条件地硬拼硬打并非上策，强调要采取全局性的战略方针，“以全争于天下”，争取最大限度的利益而使自己的损耗减少到最低限度。这是富有政治远见的。\n全文依次论述了几个问题，表面上看似不甚相干，但实际上却都紧扣中心。一、二两段首先说明总的战略原则是“不战而屈人之兵”，是“伐谋”（从谋略上攻破敌人），是“兵不顿而利可...", "authors": ["张葆全"], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701f6542516c6deeef8", "shortContent": "孙子用兵打仗，有两手策略：一为“战胜策”，即用战争手段击破敌人使其屈服；二为“全胜策”，即用威势或道德的力量保全敌人使其归服。在这两种策略中，孙子认为后者“为上”，是上策，高明的策略；前者“次之”，是次一等的策略。古代军队的编制，约有军、旅、卒、伍诸等级：一军有一万两千五百人，一旅为五百人，一卒为百人，一伍为五人。为了强调“全”胜归服为“上”策，战胜击“破”为“次”一等策略，孙子从国、军、旅、卒、...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701f6542516c6deeef9", "shortContent": "这是《孙子兵法》中最有名的话，流传甚广，影响深远。有人称“不战而屈人之兵”，是孙子兵法的核心和精髓。所谓“善之善者”，是好中之好，实际就是最好的。孙子指出：百战百胜，不是最好的；只有不战而屈人之兵，才是最好的。为什么这样说？陈启天《孙子兵法校释》注：“百战百胜何以为非最善之善者？以须破军，甚至破国也。不战而屈人之兵，何以为善之最善者？以能全国，且能全军也。百战百胜之法，为伐兵攻城之武力战；不战而屈...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701f6542516c6deeefa", "shortContent": "这是孙子对用兵方法最简练的概括，是他战略思想的清楚表述。所谓“上兵”，是上等的、最好的用兵方法。“伐谋”是以谋伐敌，即用机智的谋略进行攻伐，用较少的兵力和时间即能取胜，而不是硬拼硬打，耗费时日和人力、物力。“伐交”是以结交盟友的方式进行攻伐，尽量结交众多的盟友，形成我方的强大优势，而使敌国陷于孤立，无法对抗，以致不战而降。“伐兵”即用军队和兵器进行攻伐，它必然耗费大量的人力和财物，同时又要遭到敌国...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701f6542516c6deeefb", "shortContent": "孙子这一段经典性言论，曾被无数军事家、战略家运用指导战争。孙子认为，战前必须了解“彼”（敌方）和“己”（我方）两方面的情况，才能百战而没有危险。王晳注：“殆，危也。谓校尽彼我之情，知胜而后战，则百战不危。”如果只知道我方的情况而不了解敌方的情况，“不知彼而知己”，则胜负带有很大的不确定性，以概率而言，只能是“一胜一负”。李筌注：“自以己强，而不料敌，则胜负未定。”如果对敌我双方的情况都不知道，不掌...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1522856074, '5ac48008a22b9d004554623f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637038, '孙子兵法 · 军形篇', NULL, 23, 13, 0, 1, '孙武', NULL, 36849, '59e714859545040067513674', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%99%E5%AD%90%E5%85%B5%E6%B3%95%C2%B7%E5%86%9B%E5%BD%A2%E7%AF%87/19831521?fr=aladdin&fromid=7179505&fromtitle=%E5%86%9B%E5%BD%A2%E7%AF%87', '', '孙子曰：昔之善战者，先为不可胜，以待敌之可胜。不可胜在己，可胜在敌。故善战者，能为不可胜，不能使敌之可胜。故曰：胜可知，而不可为。
不可胜者，守也；可胜者，攻也。守则不足，攻则有余。善守者，藏于九地之下，善攻者，动于九天之上，故能自保而全胜也。
见胜不过众人之所知，非善之善者也；战胜而天下曰善，非善之善者也。故举秋毫不为多力，见日月不为明目，闻雷霆不为聪耳。古之所谓善战者，胜于易胜者也。故善战者之胜也，无智名，无勇功，故其战胜不忒，不忒者，其所措必胜，胜已败者也。故善战者，立于不败之地，而不失敌之败也。是故胜兵先胜而后求战，败兵先战而后求胜。善用兵者，修道而保法，故能为胜败之政。
兵法：一曰度，二曰量，三曰数，四曰称，五曰胜。地生度，度生量，量生数，数生称，称生胜。故胜兵若以镒称铢，败兵若以铢称镒。胜者之战民也，若决积水于千仞之溪者，形也。', '《孙子兵法·军形篇》是春秋时期兵法家孙武创作的一篇散文。讲的是具有客观、稳定、易见等性质的因素，如战斗力的强弱、战争的物质准备。', '先为不可胜：为，造成。先为不可胜，指首先造成一种不被敌军战胜的形势。
待敌之可胜：指等待敌人有可能被我军战胜的机会。
在己：在于自己，引申为决定于自己。
在敌：在于敌人，引申为决定于敌人。
不能使敌之可胜：使，强使。不能使敌之可胜，这里指不可能强使敌军提供被我军战胜的机会。
不可为：为，强求。不可为，不可以强求。
守则不足：兵力不足时应着重防守。
攻则有余：指兵力充足有余时才发起进攻。
藏于九地之下：九地，极深的地下。“九”是虚数，古人常把“九”表示数的极点。藏于九地之下，指把军队隐藏在很深很深的地下，使敌人莫测虚实。
动于九天之上：动，发动，这里可引申为进攻。动于九天之上，军队进攻如同从天而降，既出其不意又势不可挡。
见胜不过众人之所知：见，预见。见胜，预见到胜利。见胜不过众人之所知，为一般人所能预测到的胜利。
善之善：好而又好，最好的。
举秋毫不为多力：秋毫，指能举一件毫毛那样极轻极细的事物。举秋毫不为多力，指举一件像毫毛那样极轻极细的事物不能算是力量大。
明目：眼睛很亮。聪耳：耳朵听觉很灵。
战胜不忒：忒，可以译为“差”或“差错”。
胜兵先胜而后求战：胜兵，打胜战的军队。先胜，这里指事先取得必胜的形势。胜兵先胜而后求战，打胜战的军队总是事先取得必胜的形势而后才向敌国宣战。
败兵先战而后求胜：打败战的军队是因为先打战而后谋求胜利。
修道而保法：修明治道，严明法度。
为胜败之政：政，主宰。这里指成为支配用兵胜败的主宰。
度：度量，这里指土地幅员的大小。
以镒称铢：这里比喻胜兵对败兵的力量相差悬殊，胜兵的实力占有绝对优势。
决积水于千仞之溪：仞，我国古代高度单位，一仞为七尺。溪，山洞。
形也：这里的形是指由军事实力而造成的形势。', '孙子说：从前善于打仗的人，总是先创造条件使自己立于不败之地，然后捕捉战机攻胜敌人。做到不可战胜，就会掌握战争的主动权；敌人出现空隙，就乘机击破它。因而，善于作战的人，能够创造不被敌人战胜的条件，不一定使敌人被我战胜。所以说：胜利可以预测，但不可强求。
若要不被敌人战胜，必须先要作好防守工作；能战胜敌人，就要进攻。采取防守，是因为条件不充分；进攻敌人，是因为时机成熟。所以善于防御的人，隐蔽自己的军队如同深藏在地下；善于进攻的人，如同神兵自九天而降，攻敌措手不及。这样，既保全了自己，又能获得全面的胜利。
预见胜利不超过一般人的见识，不算高明中最高明的。打败敌人而普天下都说好，也不算是高明中最高明的。这就好像举起秋毫不算力大，看见太阳、月亮不算眼明，听见雷霆不算耳聪一样。古代善于作战的人，总是战胜容易战胜的敌人。因此，善于打仗的人打了胜仗，既没有卓越过人的智慧，也没有勇武显赫的名声。他们进行战争的胜利不会有差错，之所以不会出现差错，是因为他们作战的措施建立在必胜的基础上，是战胜了在气势上已失败的敌人。善于作战的人，总是使自己立于不败之地，而不放过进攻敌人的机会。因此，胜利之师是先具备必胜的条件然后再交战，失败之军总是先同敌人交战，然后期求从苦战中侥幸取胜。善于用兵的人，必须修明政治，确保法制，就能够主宰战争胜负的命运。
兵法上有五项原则：一是度，二是量，三是数，四是称，五是胜。度产生于土地的广狭，土地幅员广阔与否决定物资的多少，军赋的多寡决定兵员的数量，兵员的数量决定部队的战斗力，部队的战斗力决定胜负的优劣。所以胜利之师如同以镒对铢，是以强大的军事实力攻击弱小的敌人；而败军之师如同以铢对镒，是以弱小的军事实力对抗强大的敌方。高明的指挥员领兵作战，就像在万丈悬崖决开山涧的积水一样，这就是军事实力中的“形”。', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0e6", "shortContent": "这是孙子又一句论述善战者应如何作战的名言。张预注：“审吾法令，明吾赏罚，便吾器用，养吾武勇，是立于不败之地也。”顾福棠注：“‘地’字当虚解，言我能深沟高垒，粮足兵精，无隙可入，无懈可击，是即立于不败之地也。我既立于不败之地，旷日持久，以俟敌人。敌人无隙，我固无如彼何，一朝有隙，我即乘机以攻之，所谓不失敌之败也。”陈启天注：“谓先为不可胜，以待敌之可胜也。我常立于不败之地，以伺敌有可败之时而即乘之，...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1522856144, '5ac4804e7565710045c129df', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637074, '报刘一丈书', NULL, 1, 775, 0, 1, '宗臣', NULL, 15476, '5858ea12570c35006917c0b4', '明', 'wen', '文', 'https://baike.baidu.com/item/%E6%8A%A5%E5%88%98%E4%B8%80%E4%B8%88%E4%B9%A6/1653798?fr=aladdin', '', '数千里外，得长者时赐一书，以慰长想，即亦甚幸矣；何至更辱馈遗，则不才益将何以报焉？书中情意甚殷，即长者之不忘老父，知老父之念长者深也。
至以“上下相孚，才德称位”语不才，则不才有深感焉。夫才德不称，固自知之矣；至于不孚之病，则尤不才为甚。
且今之所谓孚者，何哉？日夕策马，候权者之门。门者故不入，则甘言媚词，作妇人状，袖金以私之。即门者持刺入，而主人又不即出见；立厩中仆马之间，恶气袭衣袖，即饥寒毒热不可忍，不去也。抵暮，则前所受赠金者，出报客曰：“相公倦，谢客矣！客请明日来！”即明日，又不敢不来。夜披衣坐，闻鸡鸣，即起盥栉，走马抵门；门者怒曰：“为谁？”则曰：“昨日之客来。”则又怒曰：“何客之勤也？岂有相公此时出见客乎？”客心耻之，强忍而与言曰：“亡奈何矣，姑容我入！”门者又得所赠金，则起而入之；又立向所立厩中。幸主者出，南面召见，则惊走匍匐阶下。主者曰：“进！”则再拜，故迟不起；起则上所上寿金。主者故不受，则固请。主者故固不受，则又固请，然后命吏纳之。则又再拜，又故迟不起；起则五六揖始出。出揖门者曰：“官人幸顾我，他日来，幸无阻我也！”门者答揖。大喜奔出，马上遇所交识，即扬鞭语曰：“适自相公家来，相公厚我，厚我！”且虚言状。即所交识，亦心畏相公厚之矣。相公又稍稍语人曰：“某也贤！某也贤！”闻者亦心许交赞之。
此世所谓上下相孚也，长者谓仆能之乎？前所谓权门者，自岁时伏腊，一刺之外，即经年不往也。闲道经其门，则亦掩耳闭目，跃马疾走过之，若有所追逐者，斯则仆之褊衷，以此长不见怡于长吏，仆则愈益不顾也。每大言曰：“人生有命，吾惟有命，吾惟守分而已。”长者闻之，得无厌其为迂乎？
乡园多故，不能不动客子之愁。至于长者之抱才而困，则又令我怆然有感。天之与先生者甚厚，亡论长者不欲轻弃之，即天意亦不欲长者之轻弃之也，幸宁心哉！', '这是明代文学家宗臣给刘一丈写的一封回信。刘名玠，字国珍，号墀石，是宗臣父亲宗周的朋友，于宗臣为长辈，因排行第一，故称为“一丈”，文中又称为“长者”。因是书信，又是写给长辈的，所以首尾两节不免寒暄客套之语，这也是一般书信的常见格式。', '（1）赐：敬词，赏，给。
（2）长想：深长的思念。
（3）何至：哪里敢。辱：屈辱（您），谦词。馈遗（kuiwei）：赠送。
（4）不才：无才，自谦之称。益：更加。何以报：即“以何报”，用什么来报答。
（5）殷：深厚。
（6）老父：作者称呼自己的父亲。即：就，从。
（7）上下相孚，才德称位：上下级互相信任，才德与官位相配。孚：信任。称：合适，称职。
（8）夫：发语词。
（9）固：本来。
（10）日夕：白天和晚上。策马：用鞭子赶马，形容奔走。策：鞭，名词用作动词。权者：有权势的人，指严嵩、严世蕃父子。
（11）故不入，故意不让进去。
（12）甘言媚词：甜言蜜语，巴结人的话。
（13）作妇人状：故意扭捏作态。
（14）袖金以私之：取出衣袖里藏着的银子，偷偷地送给守门人。私：动词，私送。
（15）即：即使，纵使。刺：名刺，谒见时用的名片。明代官场谒见，用红纸写官衔、姓名投递通报。
（16）厩（jiu）：马棚。仆马：仆人和马匹。
（17）毒热：酷热。
（18）抵：到了。
（19）相公：唐宋以后对宰相的尊称。
（20）谢客：谢绝见客。
（21）盥栉（guanzhi）：洗脸和梳头。
（22）为谁：是谁。
（23）何客之勤也：怎么你这个人来得这样勤呢。
（24）耻之：以之为耻。感到这样可耻。
（25）亡奈何：没有办法。亡：同“无”。
（26）姑：暂且。
（27）起而入之：起身开门让客进府去。入之：使之入。
（28）向：向时，先前。
（29）南面：古代以面向南坐为尊位。
（30）走：跑。匍匐（pufu）：在地上爬行，这里指趴倒。
（31）再拜：拜了又拜。
（32）所上：“所”字结构，送给的。寿金：祝寿礼金，实即贿赂。
（33）固：坚持。
（34）内：同“纳”，收下。
（35）揖（yi）：作揖，旧时躬身拱手的礼节。
（36）官人：对有官职者的尊称。顾：看得起，照顾。幸：幸而，多蒙。
（37）所交识：朋友，熟人。
（38）适：刚才。
（39）厚：厚待，看重。
（40）虚言状：虚假地描述了相公厚待的情景。
（41）畏：惊羡。
（42）某也贤：某人很有才德。某：指上文的“客”。
（43）交：交相。心计：心中盘算。
（44）仆：对自己的谦称。能之乎：能够这样吗？
（45）岁时伏腊：泛指逢年过节。岁：年节。时：四时节令。伏腊：即夏伏、冬腊，都是祭祀的节日。
（46）间：间或，有时。道经：路过。
（47）褊（bian）衷：偏狭的心胸。
（48）见悦：被喜欢。长（zhang）吏：上司。
（49）大言：扬言，这里带有对人表白自己心迹的意思。
（50）人生有命：这是化用孔子“死生有命，富贵在天”的成语，表示不钻营。
（51）守分：安分守己。
（52）得无：能不，表示推测语气。迂：迂阔，固执，不通世故。
（53）乡园多故：家乡经常闹灾。当指倭寇侵扰频繁。
（54）动客子之愁：触动游子的乡思情怀。
（55）抱才而困：有才能而陷于困厄的境地，即怀才不遇。
（56）怆（chuang）然：悲伤的样子。
（57）天之与先生者：先生的先天禀赋。
（58）亡论：无论，不要说。亡：通“无”。
（59）幸：表示希望的意思。宁心：安心。', '在数千里以外，时常得到您老人家的来信，安慰我的长久想念，这已经十分幸运了。竟然还承蒙您赠送礼物，那么我更要用什么来报答呢？您在信中表达的情意十分恳切，说明您没有忘记我的老父亲，从而也可以知道老父亲是很深切地想念您老人家的。
至于信中以“上下要互相信任，才能和品德要与职位相符合”的话教导我，正是我所亲切感受到的。我的才能和品德与职位不相符，本来我就知道的。至于不能做到上下相互信任的弊病，在我的身上表现得更厉害。
且看当今社会上所说的上下信任是怎么一回事呢？当他从早到晚骑马去权贵人家的门口恭候的时候，守门的人故意为难不肯让他进去，他就用甜言媚语装作妇人的姿态，把袖里藏着的金钱偷偷地塞给守门人。守门人拿着名帖进去之后，而主人又不立即出来接见，他就站在马棚里，与仆人和马匹相处，臭气熏着衣服，即使是饥饿寒冷或闷热得无法忍受，也不肯离去。一直到傍晚，那个先前曾经接受金钱的守门人出来对他说：“相公疲劳了，谢绝会客，客人请明天再来吧。”到了第二天，他又不敢不来。晚上他披衣坐等，一听到鸡叫就起来洗脸梳头，骑着马跑到相府门口，守门人发怒地说：“是谁？”他便回答说：“昨天的客人又来了。”守门人又怒气冲冲地说：“你这个客人倒来得这样勤！难道相公能在这个时候出来会客吗？”客人心里感到受耻辱，只有勉强忍耐着对守门人说：“没有办法啦！姑且让我进去吧！”守门人再次得到他送的一笔钱，才起身放他进去。他又站在原来站过的马棚里。幸好主人出来了，在客厅上朝南坐着，召他进去见面，他就慌慌张张地跑上去，拜伏在台阶下。主人说：“进来！”他便拜了又拜，故意迟迟不起来，起来后就献上进见的金银。主人故意不接受，他就一再请求收下；主人故意坚决不接受，他就再三请求。然后主人叫手下人把东西收起来，他便拜了又拜，故意迟迟不起，起来后又作了五六个揖才出来。出来他就对守门人作揖说：“多亏老爷关照我！下次再来，希望不要阻拦我。”守门人向他回礼，他就十分高兴地跑出来。他骑在马上碰到相识的朋友，就扬起马鞭得意洋洋地对人说：“我刚从相府出来，相公待我很好，很好！”并且虚假地叙述受到接待的情况。因此与他相识的朋友，也从心里敬畏他能得到相公的优待。相公又偶尔对别人说：“某人好，某人好。”听到这些话的人也都在心里盘算着并且一齐称赞他。这就是所说的上下信任，您老人家说我能这样做吗？
对于前面所说的权贵人家，我除了过年过节例如伏日、腊日投一个名帖外，就整年不去。有时经过他的门前，我也是捂着耳朵，闭着眼睛，鞭策着马匹飞快地跑过去，就象后面有人追逐似的。这就是我狭隘的心怀，因此经常不受长官欢迎（不被长官赏识），而我则更加不顾这一切了。我常常发表高谈阔论：“人生遭际都是由命运决定的，我只是守自己的本份罢了！”您老人家听了我的这番话，或许（恐怕）不会嫌我过于迂腐吧！
家乡多次遭遇灾祸，不能不触动旅居在外的人的愁思。至于您老人家的怀才不遇，也使我心情悲伤而有所感触。上天赋于您的才德是很优厚的，不要说您老人家不愿轻易抛弃它，就是天意也不愿让您轻易地抛弃啊。希望您安心等待吧！', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed20534a8757d5a0edbbd", "shortContent": "这是明代文学家宗臣给刘一丈写的一封回信。刘名玠，字国珍，号墀石，是宗臣父亲宗周的朋友，于宗臣为长辈，因他排行第一，故称为“一丈”，文中又称为“长者”。因是书信，又是写给长辈的，所以首尾两节不免寒暄客套之语，这也是一般书信的常见格式。\n这篇书信的主体部分是作者与刘一丈谈论“上下相孚”。本来，在刘一丈给宗臣的信中，是以“上下相孚，才德称位”相教诲的，宗臣在这个问题上深有感触，所以在复信中就专门论之。为...", "authors": ["邱鸣皋"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa734a8757d5a0fa50e", "shortContent": "秦末汉初时，“商山四皓”的名望相当大，以致汉高祖刘邦夺得天下后，多次派人请他们出山辅佐，但“商山四皓”逃而不见。后来刘邦想立戚夫人之子赵王如意为太子，吕后大为惊恐，采纳了张良的意见，让太子刘盈“卑辞安车，因使辩士固请”，果然请得“商山四皓”出山。刘邦见刘盈有此四人相助，认为“羽冀已成”，无法动摇了，便打消了废立太子的念头（见《史记·留侯世家》）。\n不过两千年来，人们对《史记》中的这段记载或是怀疑，...", "authors": ["全岳春"], "pressName": "上海辞书出版社"}]', '', 'indent', 1523289189, '5acb1be3a22b9d004578f859', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637039, '孙子兵法 · 兵势篇', NULL, 25, 13, 0, 1, '孙武', NULL, 36849, '59e714859545040067513674', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%99%E5%AD%90%E5%85%B5%E6%B3%95%C2%B7%E5%85%B5%E5%8A%BF%E7%AF%87/19828235?fr=aladdin&fromid=19973845&fromtitle=%E5%85%B5%E5%8A%BF%E7%AF%87', '', '孙子曰：凡治众如治寡，分数是也；斗众如斗寡，形名是也；三军之众，可使必受敌而无败者，奇正是也；兵之所加，如以碫投卵者，虚实是也。
凡战者，以正合，以奇胜。故善出奇者，无穷如天地，不竭如江海。终而复始，日月是也。死而复生，四时是也。声不过五，五声之变，不可胜听也；色不过五，五色之变，不可胜观也；味不过五，五味之变，不可胜尝也；战势不过奇正，奇正之变，不可胜穷也。奇正相生，如循环之无端，孰能穷之哉？
激水之疾，至于漂石者，势也；鸷鸟之疾，至于毁折者，节也。故善战者，其势险，其节短。势如彍弩，节如发机。
纷纷纭纭，斗乱而不可乱也；浑浑沌沌，形圆而不可败也。乱生于治，怯生于勇，弱生于强。治乱，数也；勇怯，势也；强弱，形也。
故善动敌者，形之，敌必从之；予之，敌必取之。以利动之，以实待之。
故善战者，求之于势，不责于人，故能择人而任势。任势者，其战人也，如转木石。木石之性，安则静，危则动，方则止，圆则行。故善战人之势，如转圆石于千仞之山者，势也。', '《孙子兵法·兵势篇》是春秋时期兵法家孙武创作的一篇散文。文章指出，必须善于顺应天时，善于利用地利，充分发挥人和。为将之人能做到这三点，就能「所向者无敌，所击者万全」了。', '治众:管理众多士卒。
分数:原指辨别数量，此指军队各级的组织编制。古代军队分级管理，军旅卒伍人数有一定的规定。如百人为卒、五人为伍。
斗众:指挥众多士兵战斗。
形名:事物的形体和名称。这里指军队指挥的方式方法。
奇正:古代兵法术语。作战以对阵交锋为正，设伏掩袭为奇;交战以正面主攻为正，机动部队侧翼、突袭为奇。
所加:所向。
碫:磨刀石，泛指石。
虚实:指兵力的以实击虚。
正合:主攻部队与敌正面交战。
以奇胜:用机动部队取胜。
四时:四季。
五声:五个音阶，宫、商、角、徵、羽。
五色:青、赤、黄、白、黑。
五味:酸、甜、苦、辛、鹹。
战势:作战的态势。
相生:相互转化。
疾:急剧而猛烈。
势也:是水势造成的。
毁折:毙命，指鸷鸟捕杀小动物。
节也:节奏快的缘故。
险:疾速而迅猛。
短:短促。
弩:拉满的弓弩。
发机:扣动弩机。
纷纷纭纭:杂乱的样子。
斗乱而不可乱也:战斗虽乱而自己不可被搞乱。
浑浑沌沌:形状模糊不清。
形圆:阵形严整。
乱生于治:敌方混乱是由于我方的纪律严明造成的。
数:军队编制。
动敌:调动敌人。
形之:显露自己军队之形，即采用诱敌之法。
从:信从。
予之:给予好处。
责:要求。
择人:选择人才;一说放弃对人的要求。择，通「释」，放弃。', '治理大军团就像治理小部队一样有效，是依靠合理的组织、结构、编制；指挥大军团作战就像指挥小部队作战一样到位，是依靠明确、高效的信号指挥系统；整个部队与敌对抗而不会失败，是依靠正确运用「奇正」的变化：攻击敌军，如同用石头砸鸡蛋一样容易，关键在于以实击虚。
大凡作战，都是以正兵作正面交战，而用奇兵去出奇制胜。善于运用奇兵的人，其战法的变化就像天地运行一样无穷无尽，像江海一样永不枯竭。像日月运行一样，终而复始；与四季更迭一样，去而复来。宫、商、角、徵、羽不过五音，然而五音的组合变化，永远也听不完；红、黄、蓝、白、黑不过五色，但五种色调的组合变化，永远看不完；酸、甜、苦、辣、鹹不过五味，而五种味道的组合变化，永远也尝不完。战争中军事实力的运用不过「奇」、「正」两种，而「奇」、「正」的组合变化，永远无穷无尽。奇正相生、相互转化，就好比圆环旋绕，无始无终，谁能穷尽呢。
湍急的流水所以能漂动大石，是因为使它产生巨大冲击力的势能；猛禽搏击雀鸟，一举可致对手于死地，是因为它掌握了最有利于爆发冲击力的时空位置，节奏迅猛。所以善于作战的指挥者，他所造成的态势是险峻的，进攻的节奏是短促有力的。「势险」就如同满弓待发的弩那样蓄势，「节短」正如搏动弩机那样突然。旌旗纷纷，人马纭纭，双方混战，战场上事态万端，但自己的指挥、组织、阵脚不能乱；混混沌沌，迷迷蒙蒙，两军搅作一团，但胜利在我把握之中。双方交战，一方之乱，是因为对方治军更严整：一方怯懦，是因为对方更勇敢；一方弱小，是因为对方更强大。军队治理有序或者混乱，在于其组织编制；士兵勇敢或者胆怯，在于部队所营造的态势和声势；军力强大或者弱小，在于部队日常训练所造就的内在实力。
善于调动敌军的人，向敌军展示一种或真或假的军情，敌军必然据此判断而跟从；给予敌军一点实际利益作为诱饵，敌军必然趋利而来，从而听我调动。一方面用这些办法调动敌军，一方面要严阵以待。
所以，善战者追求形成有利的「势」，而不是苛求士兵，因而能选择人才去适应和利用已形成的「势」。善于创造有利「势」的将领，指挥部队作战就像转动木头和石头。木石的性情是处于平坦地势上就静止不动，处于陡峭的斜坡上就滚动，方形容易静止，圆形容易滚动。所以，善于指挥打仗的人所造就的「势」，就像让圆石从极高极陡的山上滚下来一样，来势凶猛。这就是所谓的「势」。', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0e7", "shortContent": "这是孙子关于战争中如何运用正兵和奇兵的名言。什么是正兵和奇兵？如何运用？曹操注：“正者当敌，奇兵从旁击不备也。”杜佑注：“以正道合战，以奇变取胜也。”张预注：“两军相临，总以正兵与之合战，徐发奇兵或捣其旁、或击其后以胜之。”综合各家之说，陈启天《孙子兵法校释》解释最为详尽其注云。：“战，谓战斗。一切战斗，欲求获胜，必须适当配合奇正而运用之。正兵之作用在合。合者，《尔雅》‘’云：对也。按：以正合，犹...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0e8", "shortContent": "孙子认为，一个指挥者在战争中首先要“求之于势，不责于人”，即用谋略和各方面的力量，造成一种胜敌之“势”，而不可对部下求全责备。同时对部下的任用、安排，又要进行选择，不可滥竽充数，或随意乱用。这里，孙子对战争指挥者提出两方面的要求：“择人而任势”，即一方面要选择人才，安排其在适当的岗位；一方面要“任势”，利用所造的强大之“势”去击垮敌人。李筌注：“得势而战，人怯者能勇，故能择其所能任之。夫勇者可战，...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1522856331, '5ac481029f54542110b6891e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637040, '孙子兵法 · 虚实篇', NULL, 15, 13, 0, 1, '孙武', NULL, 36849, '59e714859545040067513674', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%99%E5%AD%90%E5%85%B5%E6%B3%95%C2%B7%E8%99%9A%E5%AE%9E%E7%AF%87/19831524?fr=aladdin&fromid=3719819&fromtitle=%E8%99%9A%E5%AE%9E%E7%AF%87', '', '孙子曰：凡先处战地而待敌者佚，后处战地而趋战者劳，故善战者，致人而不致于人。能使敌人自至者，利之也；能使敌人不得至者，害之也，故敌佚能劳之，饱能饥之，安能动之。出其所不趋，趋其所不意。行千里而不劳者，行于无人之地也。
攻而必取者，攻其所不守也；守而必固者，守其所不攻也。故善攻者，敌不知其所守；善守者，敌不知其所攻。微乎微乎，至于无形。神乎神乎，至于无声，故能为敌之司命。进而不可御者，冲其虚也；退而不可追者，速而不可及也。故我欲战，敌虽高垒深沟，不得不与我战者，攻其所必救也；我不欲战，画地而守之，敌不得与我战者，乖其所之也。
故形人而我无形，则我专而敌分。我专为一，敌分为十，是以十攻其一也，则我众而敌寡；能以众击寡者，则吾之所与战者，约矣。吾所与战之地不可知，不可知，则敌所备者多；敌所备者多，则吾所与战者，寡矣。
故备前则后寡，备后则前寡，备左则右寡，备右则左寡，无所不备，则无所不寡。寡者，备人者也；众者，使人备己者也。
故知战之地，知战之日，则可千里而会战。不知战地，不知战日，则左不能救右，右不能救左，前不能救后，后不能救前，而况远者数十里，近者数里乎？
以吾度之，越人之兵虽多，亦奚益于胜败哉？故曰：胜可为也。敌虽众，可使无斗。故策之而知得失之计，作之而知动静之理，形之而知死生之地，角之而知有余不足之处。故形兵之极，至于无形。无形，则深间不能窥，智者不能谋。因形而错胜于众，众不能知；人皆知我所以胜之形，而莫知吾所以制胜之形。故其战胜不复，而应形于无穷。
夫兵形象水，水之形，避高而趋下，兵之形，避实而击虚。水因地而制流，兵因敌而制胜。故兵无常势，水无常形，能因敌变化而取胜者，谓之神。
故五行无常胜，四时无常位，日有短长，月有死生。', '《孙子兵法·虚实篇》是春秋时期兵法家孙武创作的一篇散文。本篇主要是讲，如何通过分散集结、包围迂回，造成预定会战地点上的我强敌劣，以多胜少。', '趋战：趋，快步而行。趋战，仓促应战。
致人而不致于人：致，招致。人，这里指“敌人”。致人，招致敌人，可引申为调动敌人。致于人，被敌人所调动。致人而不致于人，能调动敌人而自己却不被敌人所调动。
出其所不趋：出，指出兵。出其所不趋，我军出击的地方是敌人无法救援的地方。
趋其所不意：我军奔袭之处，出乎敌方意料之处。
微乎：微，微妙。乎，语气词。
为敌之司命：司命，命运的主宰。为敌之司命，能主宰敌军，指挥敌军。
冲其虚：冲，冲击。虚，空虚，这里指防守薄弱。冲其虚，冲击敌军防守空虚的地方。
画地而守：画，界线。画地，画出界线，画地而守，据地而守。
吾所与之地不可知：所与战，指我军将要与敌军作战。不可知，之敌军不可知。敌所备者多，备，准备，指兵力防备。
备前则后寡：用兵力防备了前面，后面的兵力便少了。使人备己：使别人防备自己，使敌人防备我军。
千里而会战：奔赴千里与敌军交战。
越人之兵虽多：越人之兵，指越国的军队。孙武曾被吴王任命为将，当时吴国与越国正在争雄。所以他说越人之兵虽多。
奚益于胜败：奚，为何。益，益处。
策之而知得失之计：策，策算。得失之计，指敌方计谋的得与失。
形兵之极：形兵，伪装示形于敌之兵。极，极点。形兵之极，我军伪装示形于敌军达到了最佳状态。
应行于无穷：应，适应。形，形势，这里可指“敌情”。应行于无穷，战术应适用敌情的变化无穷。
夫兵形象水：用兵的规律就像水流的规律一样。
兵无常势：用兵打仗，没有一成不变的态势。
日有短长，月有生死：一年之中的白天有的长，有的短；月亮在一月之中也有盈有亏。', '孙子说：凡先到战地而等待敌人的就从容、主动，后到战地而仓碎应战的就疲劳、被动。所以，善于指挥作战的人，能调动敌人而不被敌人所调动。
能使敌人自己来上钩的，是以小利引诱的结果；能使敌人不能到达其预定地域的，是以各种方法阻碍的结果。所以，敌人休整得好，能设法使它疲劳；敌人给养充分，能设法使它饥饿；敌军驻扎安稳，能够使它移动。
出兵要指向敌人无法救援的地方，行动要在敌人意料不到的方向。行军千里而不疲困的，是因为行进在没有敌人及其没有设防的地区。进攻必然得手的，是因为攻击敌人不注意防守或不易守住的地方；防守必然巩固的，是因为扼守敌人不敢攻或不易攻破的地方。
所以，善于进攻的，能使敌人不知怎样防守；善于防御的，敌人不知道怎样进攻。
微妙呀！微妙到看不出一点形迹；神奇呀！神奇到听不出一点声息。这样，就能主宰敌人的命运。
前进时，敌人无法抵御的，是因为冲击敌人空虚的地方；退却时，敌人无法追及的，是因为退得迅速使敌人追赶不上。所以，我若求战，敌人即使坚守深沟高垒，也不得不出来与我交战，是由于进攻敌人所必救的地方；我若不想交战，即使画地而守，敌人也无法和我交战，是因为我设法改变了敌人的进攻方向。
所以，用示形的办法欺骗敌人，诱使其暴露企图，而自己不露形迹，使敌人捉摸不定，就能够做到自己兵力集中而使敌人兵力分散；我军兵力集中于一处，敌人兵力分散于十处，我就能以十倍于敌的兵力打击敌人，造成我众而敌寡的有利态势；能做到以众击寡，那么与我军直接交战的敌人就少了。我们所要进攻的地方使敌人不知道：不知道，它就要处处防备；敌人防备的地方越多，兵力越分散，这样，我所直接攻击的敌人就不多了。
所以，注意防备前面，后面的兵力就薄弱；注意防备后面，前面的兵力就薄弱；注意防备左翼，右翼的兵力就薄弱；注意防备右翼，左翼的兵力就薄弱；处处防备，就处处兵力薄弱。敌人兵力所以少，是由于处处防备的结果；我方兵力所以多，是由于迫使敌人分兵防我的结果。
能预料同敌“交战的地点，能预料同敌人交战的时间，就是跋涉千里也可同敌人交战，如果既不能预料交战的地点，又下能预料交战的日期，就会左不能救右，右不能救左，前不能救后，后不能救前，何况远到几十里，近的也有好几里呢！
依我分析，越国的兵虽多，对于决定战争的胜败又有什么补益呢？
所以说，胜利是可以争取到的。敌军虽多，也可以使具无法用全部力量与我交战。
所以要认真分析判断，以求明了敌人作战计划的优劣长短；挑动敌人，以求了解其行动的规律；示形诱敌，以求摸清其所处地形的有利与不利；进行战斗侦察，以求探明敌人兵力部署的虚实强弱。
所以，示形诱敌的方法运用到极妙的程度，能使人们看不出一点形迹，看不出一点形迹，即使有深藏的间谍，也无法探明我方的虚实，即使很高明的敌人，也想不出对付我的办法来。
根据敌情而取胜，把胜利摆在众人面前，众人还是看不出来。人们只知道我是根据敌情变化取胜的，但是不知道我是怎样根据敌情变化取胜的。所以每次战胜，都不是重复老一套的方法，而是适应不同的情况，变化无穷。
用兵的规律像水，水流动的规律是避开高处而向低处奔流，用兵的规律是避开敌人坚实之处而攻击其虚弱的地方。水困地势的高下而制约其流向，作战则根据敌情而决定取胜的方针。所以，作战没有固定不变的方式方法，就像水流没有固定的形态一样；能依据敌情变化而取胜的，就称得上用兵如神了。
用兵的规律就像自然现象一样，“五行”相生相克，四季依次交替，白天有短有长，月亮有缺有圆，永远处于变化之中。', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0e9", "shortContent": "陈启天注：“兵形象水，谓兵形似水形也。水之为形，高地则避之，低地则趋之，所以便于流行也。兵之为形，亦犹是也。敌之实者则避之，敌之虚者则击之，所以便于取胜也。”孙子用生动浅显的比喻，把兵形与水形作比较：水的行动习性总是“避高而趋下”，而兵为了取得胜利，其作战行动总是“避实而击虚”。这句阐述用兵规律的名言深入人心。\n\n此句名言，原来通行各本作：“夫兵形象水：水之形，避高而趋下；兵之形，避实而击虚。”近...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0ea", "shortContent": "孙子指出战争的指挥者要随着敌情的变化而不断变换自己的策略，去夺取胜利。这里的核心是：“兵因敌而制胜”，“能因敌变化而取胜”，即战争的指挥者要根据敌情的变化而灵活制定取胜的计划。刘寅注：“兵无一定之势，因敌之虚实而变；水无一定之形，因地之高下而变。能因敌之虚实变化我之奇正而取胜于彼者，谓之神妙莫测也。”陈启天注：“最要之事，在能因敌之虚实，而变化其战略战术以取胜。然此所谓‘因敌’，非‘致于人’之谓，...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1522856394, '5ac481484773f7005d5ff38e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637041, '孙子兵法 · 军争篇', NULL, 17, 13, 0, 1, '孙武', NULL, 36849, '59e714859545040067513674', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%99%E5%AD%90%E5%85%B5%E6%B3%95%C2%B7%E5%86%9B%E4%BA%89%E7%AF%87/19831526?fr=aladdin&fromid=9902619&fromtitle=%E5%86%9B%E4%BA%89%E7%AF%87', '', '孙子曰：凡用兵之法，将受命于君，合军聚众，交和而舍，莫难于军争。军争之难者，以迂为直，以患为利。　
故迂其途，而诱之以利，后人发，先人至，此知迂直之计者也。军争为利，军争为危。举军而争利则不及，委军而争利则辎重捐。是故卷甲而趋，日夜不处，倍道兼行，百里而争利，则擒三将军，劲者先，疲者后，其法十一而至；五十里而争利，则蹶上将军，其法半至；三十里而争利，则三分之二至。是故军无辎重则亡，无粮食则亡，无委积则亡。故不知诸侯之谋者，不能豫交；不知山林、险阻、沮泽之形者，不能行军；不用乡导者，不能得地利。故兵以诈立，以利动，以分和为变者也。故其疾如风，其徐如林，侵掠如火，不动如山，难知如阴，动如雷震。掠乡分众，廓地分利，悬权而动。先知迂直之计者胜，此军争之法也。　
《军政》曰：“言不相闻，故为之金鼓；视不相见，故为之旌旗。”夫金鼓旌旗者，所以一民之耳目也。民既专一，则勇者不得独进，怯者不得独退，此用众之法也。故夜战多金鼓，昼战多旌旗，所以变人之耳目也。　
三军可夺气，将军可夺心。是故朝气锐，昼气惰，暮气归。善用兵者，避其锐气，击其惰归，此治气者也。以治待乱，以静待哗，此治心者也。以近待远，以佚待劳，以饱待饥，此治力者也。无邀正正之旗，勿击堂堂之阵，此治变者也。　
故用兵之法，高陵勿向，背丘勿逆，佯北勿从，锐卒勿攻，饵兵勿食，归师勿遏，围师遗阙，穷寇勿迫，此用兵之法也。', '《孙子兵法·军争篇》是春秋时期兵法家孙武创作的一篇散文。讲的是“凡用兵之法”。通过军队对“利”的看重，进行一步步的分析，提出了“风林火山”等概念。从军队的立命之本谈起，一点点引出自己的观点。', '合军聚众：合，集合，这里引申为组织编制。合军聚众，把人们聚集起来，组成军队。
交和而舍：和，通“合”，我国古代的军门称为合门。交和而舍，指两军处于对峙状态。
军争：军，军事，这里指打战。军争，在作战中，争取夺得胜利的有利条件。
以迂为直：指把迂回曲折的弯路变为近便的道路。以患为利：指把有害的事情变为有利的事情。
后人发，先人至：比敌军后出动，比敌军先到达战地。
举军而争利，则不及：举，全，尽。举军，指全部携带武器辎重的军队。举军而争利，率领全部武器辎重的军队去争夺先机之利，就会因行动迟缓而不能按时到达。
委军争利，而辎重捐：委，委弃，选择。委军，指丢弃笨重装备和辎重的军队。委军争利，则辎重捐，整句意为率领委军去争夺先机之利，那就会把作战必须的重装备和辎重都丢掉。
擒三将军：三将军，指上、中、下或左、中、右三军将领。擒，被擒。擒三将军，三军将领都被擒。
其法十一而至：法，方法。十一，十分之一。其法十一而至，用这种方法，只有十分之一的人能按时到达目的地。
无委积：委积，储备物资。无委积，指没有储备物资。豫交：豫，通“与”。豫交，与之结交。
乡导：乡，通“向”。
徐如林：用兵舒缓是像树林那样轻轻晃动。
先知迂直之计者胜：率先了解和运用迂直之计的人会取得胜利。
言不相闻：作战时，以语言指挥，声音听不清楚。
一人之耳目：一，统一、一致。人，指士卒。一人之耳目，指进而统一士卒们的行动。
变人之耳目：变，这里作“适应”“便利”解。变人之耳目，适应士卒的耳目。
三军可夺气，将军可夺心：三军之众可以使它丧失掉锐气，也可以使将帅们失掉坚强的决心和意志。
无邀正正之旗：不要邀击旗帜严整、队列雄壮的敌军。
勿击堂堂之阵：不要去攻击阵容强大、实力雄厚的敌军。
治变：变，这里指的机变。治变，掌握机变的方法。
高陵勿向：不要去攻击占据了高地的敌军。
背丘勿逆：不要去攻击背靠着丘陵的敌军。
佯北勿从：不要去攻击假装打了败仗的敌军。
饵兵勿食：饵，钓饵。', '孙子说：用兵的原则，将领接受君命，从召集军队，安营扎寨，到开赴战场与敌对峙，没有比率先争得制胜的条件更难的事了。“军争”中最困难的地方就在于以迂回进军的方式实现更快到达预定战场的目的，把看似不利的条件变为有利的条件。所以，由于我迂回前进，又对敌诱之以利，使敌不知我意欲何去，因而出发虽后，却能先于敌人到达战地。能这么做，就是知道迂直之计的人。“军争”为了有利，但“军争”也有危险。带着全部辎重去争利，就会影响行军速度，不能先敌到达战地；丢下辎重轻装去争利，装备辎重就会损失。卷甲急进，白天黑夜不休息地急行军，奔跑百里去争利，则三军的将领有可能会被俘获。健壮的士兵能够先到战场，疲惫的士兵必然落后，只有十分之一的人马如期到达；强行军五十里去争利，先头部队的主将必然受挫，而军士一般仅有一半如期到达；强行军三十里去争利，一般只有三分之二的人马如期到达。这样，部队没有辎重就不能生存，没有粮食供应就不能生存，没有战备物资储备就无以生存。
所以不了解诸侯各国的图谋，就不要和他们结成联盟；不知道山林、险阻和沼泽的地形分布，不能行军；不使用向导，就不能掌握和利用有利的地形。所以，用兵是凭借施诡诈出奇兵而获胜的，根据是否有利于获胜决定行动，根据双方情势或分兵或集中为主要变化。按照战场形势的需要，部队行动迅速时，如狂风飞旋；行进从容时，如森林徐徐展开；攻城掠地时，如烈火迅猛；驻守防御时，如大山岿然；军情隐蔽时，如乌云蔽日；大军出动时，如雷霆万钧。夺取敌方的财物，掳掠百姓，应分兵行动。开拓疆土，分夺利益，应该分兵扼守要害。这些都应该权衡利弊，根据实际情况，相机行事。率先知道“迂直之计”的将获胜，这就是军争的原则。
《军政》说：“在战场上用语言来指挥，听不清或听不见，所以设置了金鼓；用动作来指挥，看不清或看不见，所以用旌旗。金鼓、旌旗，是用来统一士兵的视听，统一作战行动的。既然士兵都服从统一指挥，那么勇敢的将士不会单独前进，胆怯的也不会独自退却。这就是指挥大军作战的方法。所以，夜间作战，要多处点火，频频击鼓；白天打仗要多处设置旌旗。这些是用来扰乱敌方的视听的。
对于敌方三军，可以挫伤其锐气，可使丧失其士气，对于敌方的将帅，可以动摇他的决心，可使其丧失斗志。所以，敌人早朝初至，其气必盛；陈兵至中午，则人力困倦而气亦怠惰；待至日暮，人心思归，其气益衰。善于用兵的人，敌之气锐则避之，趁其士气衰竭时才发起猛攻。这就是正确运用士气的原则。用治理严整的我军来对付军政混乱的敌军，用我镇定平稳的军心来对付军心躁动的敌人。这是掌握并运用军心的方法。以我就近进入战场而待长途奔袭之敌；以我从容稳定对仓促疲劳之敌；以我饱食之师对饥饿之敌。这是懂得并利用治己之力以困敌人之力。不要去迎击旗帜整齐、部伍统一的军队，不要去攻击阵容整肃、士气饱满的军队，这是懂得战场上的随机应变。
所以，用兵的原则是：对占据高地、背倚丘陵之敌，不要作正面仰攻；对于假装败逃之敌，不要跟踪追击；敌人的精锐部队不要强攻；敌人的诱饵之兵，不要贪食；对正在向本土撤退的部队不要去阻截；对被包围的敌军，要预留缺口；对于陷入绝境的敌人，不要过分逼迫，这些都是用兵的基本原则。', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0eb", "shortContent": "这是孙子关于在打仗时可以对三军“夺气”、对将军“夺心”的名言。张预注：“气者，战之所恃也。夫含生禀血，鼓作斗争，虽死不省者，气使然也。故用兵之法，若激其士卒，令上下同怒，则其锋不可当。故敌人新来而气锐，则且以不战挫之，伺其衰倦而后击，故彼之锐气可以夺也。《尉缭子》谓‘气实则斗，气夺则走’者，此之谓也。”“心者，将之所主也。夫治乱、勇怯，皆主于心。故善制敌者，挠之而使乱，激之而使惑，迫之而使惧，故彼...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1522856504, '5ac481b44773f7005d5ff6c9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637042, '孙子兵法 · 九变篇', NULL, 9, 13, 0, 1, '孙武', NULL, 36849, '59e714859545040067513674', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%99%E5%AD%90%E5%85%B5%E6%B3%95%C2%B7%E4%B9%9D%E5%8F%98%E7%AF%87/19831529?fr=aladdin&fromid=3720928&fromtitle=%E4%B9%9D%E5%8F%98%E7%AF%87', '', '孙子曰：凡用兵之法，将受命于君，合军聚众。圮地无舍，衢地交合，绝地无留，围地则谋，死地则战。涂有所不由，军有所不击，城有所不攻，地有所不争，君命有所不受。故将通于九变之地利者，知用兵矣；将不通于九变之利者，虽知地形，不能得地之利者矣。治兵不知九变之术，虽知五利，不能得人之用矣。
是故智者之虑，必杂于利害。杂于利，而务可信也；杂于害，而患可解也。是故屈诸侯者以害，役诸侯者以业，趋诸侯者以利。故用兵之法，无恃其不来，恃吾有以待也；无恃其不攻，恃吾有所不可攻也。
故将有五危：必死，可杀也；必生，可虏也；忿速，可侮也；廉洁，可辱也；爱民，可烦也。凡此五者，将之过也，用兵之灾也。覆军杀将必以五危，不可不察也。', '《孙子兵法·九变篇》是春秋时期兵法家孙武创作的一篇散文。', '圮地无舍：圮，倒塌、毁坏。圮地，按梅尧臣注：“山林，险阻，沮泽之地。”舍，住舍，这里指的是部队宿营。圮地无舍，这里是指在山林险阴沼泽的地方不能宿营。
衢地交合：衢地，这里指与邻国相接四通八达的地方。交合，结合，这里是指与其他诸侯国结交。衢地交合，指在与多国相邻的地方要重视与邻国结交。
绝地无留：绝地，缺乏生存条件或地形十分险恶的地方。留，逗留。绝地无留，意思是指在缺乏生存条件或地形十分险恶的地方，部队不能停留。
围地则谋：围，包围，是指四面地形险恶，敌可往来，我难出入之地。谋，这里指的设谋。围地则谋，当部队进入四面地形险恶、敌军可以任意往来而我军却难以出入的地区应当设计尽快离开。
死地则战：死地，前无进路、后有追兵，必得死战之地。死战之地，当部队陷入前无进路、后有追兵的死地时只有与敌作决战之战。
涂有所不由：涂，通“途”，道路。涂有所不由，意为部队进军时，有点道路不能走。
军有所不击：对于有的敌不能进行攻击。
五利：指五变之利，具体指“涂有所不由”到“君命有所不受”的五变之利。
得人之用：人，这里指的是军队将士。用，作用，这里可引申为战斗力。得人之用，意思是指，充分发挥全军的战斗力。
智者之虑：聪明的人思考问题。
杂于利害：杂，掺杂、有混合。杂于利害，思考问题既考虑有力的一面，也要考虑有害的一面。
务可信：务，任务。信，通“伸”，这里引申为完成、成功。务可信，这里指任务可以成功。
患可解：患，灾祸。患可解，灾难可以解除。
无恃其不来：恃，依靠。其，代指敌军。无恃其不来，不要依靠寄希望于敌军不来进犯。
必生：生，这里指的是贪生。必生，一味贪生。
忿速：忿，愤怒。忿速，这里指性情急爆，容易愤怒、偏激。
爱民：这里指“仁人爱民”之心。
将之过也：将领的过失。', '孙子说：凡是用兵的法则，主将受领国君的命令，征集兵员编成军队，在“圮地”上不要驻止，在“衢地”上应结交诸侯，在“绝地”上不可停留，遇到“围地”要巧出奇谋，陷入“死地”就要殊死奋战。
有的道路不宜通过，有的敌军不宜攻击，有的城邑不宜攻占，有的地方不宜争夺，不合乎上述“九变”的，即使是国君的命令，也可以不执行。
所以，将帅能通晓九变好处的，就懂得用兵了，将帅不通晓九变好处的，虽然知道地形情况，也不能得地利。指挥军队而不知道各种机变的方法，虽然知道“五利”，也不能充分发挥军队的战斗力。
所以，明智的将帅考虑问题，总是兼顾到利和害两个方面。在有利情况下考虑到不利的方面，事情就可以顺利进行；在不利情况下考虑到有利的方面，祸患就可以避免。
能使诸侯屈服的，是用诸侯最害怕的事情去威胁它；能役使诸候的，是用危险的事情去困扰它；能使诸侯归附的，是用利益去引诱它。
所以用兵的法则，不要寄希望于敌人不来打，而要依靠自己严阵以待，充分准备；不要寄希望于敌人不来进攻，而要依靠自己有使敌人无法攻破的充足力量和办法。
将帅有五种致命弱点：有勇无谋，只知死拼，就可能被敌诱杀；临阵畏怯，贪生怕死，就可能被敌俘虏；急躁易怒，一触即跳，就可能受敌凌辱而妄动；廉洁而爱好名声，过于自尊，就可能被敌侮辱而失去理智；溺爱民众，就可能被敌烦扰而陷于被动。这五点是将帅易犯的过失，是用兵的灾害。军队的覆灭、将帅的被杀，都是由于这五种致命弱点造成的，这是做将帅的人不可不充分注意的。', NULL, '', 'indent', 1522856558, '5ac481ed9f545405e7ae3406', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637043, '孙子兵法 · 行军篇', NULL, 9, 13, 0, 1, '孙武', NULL, 36849, '59e714859545040067513674', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%99%E5%AD%90%E5%85%B5%E6%B3%95%C2%B7%E8%A1%8C%E5%86%9B%E7%AF%87/19832776?fr=aladdin&fromid=135678&fromtitle=%E8%A1%8C%E5%86%9B%E7%AF%87', '', '孙子曰：凡处军相敌：绝山依谷，视生处高，战隆无登，此处山之军也。绝水必远水；客绝水而来，勿迎之于水内，令半济而击之，利；欲战者，无附于水而迎客；视生处高，无迎水流，此处水上之军也。绝斥泽，惟亟去无留；若交军于斥泽之中，必依水草而背众树，此处斥泽之军也。平陆处易，而右背高，前死后生，此处平陆之军也。凡此四军之利，黄帝之所以胜四帝也。
凡军好高而恶下，贵阳而贱阴，养生而处实，军无百疾，是谓必胜。丘陵堤防，必处其阳，而右背之。此兵之利，地之助也。
上雨，水沫至，欲涉者，待其定也。
凡地有绝涧、天井、天牢、天罗、天陷、天隙，必亟去之，勿近也。吾远之，敌近之；吾迎之，敌背之。
军行有险阻、潢井、葭苇、山林、蘙荟者，必谨覆索之，此伏奸之所处也。
敌近而静者，恃其险也；远而挑战者，欲人之进也；其所居易者，利也。
众树动者，来也；众草多障者，疑也；鸟起者，伏也；兽骇者，覆也；尘高而锐者，车来也；卑而广者，徒来也；散而条达者，樵采也；少而往来者，营军也。
辞卑而益备者，进也；辞强而进驱者，退也；轻车先出居其侧者，陈也；无约而请和者，谋也；奔走而陈兵车者，期也；半进半退者，诱也。
杖而立者，饥也；汲而先饮者，渴也；见利而不进者，劳也；鸟集者，虚也；夜呼者，恐也；军扰者，将不重也；旌旗动者，乱也；吏怒者，倦也；粟马肉食，军无悬缻，不返其舍者，穷寇也；谆谆翕翕，徐与人言者，失众也；数赏者，窘也；数罚者，困也；先暴而后畏其众者，不精之至也；来委谢者，欲休息也。兵怒而相迎，久而不合，又不相去，必谨察之。
兵非益多也，惟无武进，足以并力、料敌、取人而已。夫惟无虑而易敌者，必擒于人。
卒未亲附而罚之，则不服，不服则难用也。卒已亲附而罚不行，则不可用也。故令之以文，齐之以武，是谓必取。令素行以教其民，则民服；令不素行以教其民，则民不服。令素行者，与众相得也。', '《孙子兵法·行军篇》是春秋时期兵法家孙武创作的一篇散文。', '处军相敌：处军，处置军队，指带领军队行军、扎营、作战等。处军相敌，带领军队行军、扎营、作战，观察判断敌情。
绝山依谷：军队穿越山地要依傍溪谷行进。
视生处高：生，生动、生机，这里引申为开阔。视生处高，要把军队驻营于地势高、视野开阔的地方。
战隆无登：隆，这里指高地。战隆无登，不要去仰攻占据高低的敌军。
绝水必远水：水，泛指河川地带。绝水必远水，军队穿越河川地带时，要在距离河流较远的地方驻扎，以免陷入背水一战的死地。
无迎水流：不要在河的下游驻扎，以免敌军在上游决水或投毒而遭失败。
亟去无留：亟，迅速。亟去无留，迅速离开不要停留驻扎。
依水草而背众树：要依傍着水草，背靠着树林扎营。
四军之利：四军，指山地、河川地、盐碱沼泽地、平原地四种地带行军打仗求取胜利的原则。
黄帝之所以胜四帝也：四帝，黄帝时代四周的部落领袖。相传黄帝先后打败了炎帝、蚩尤等部落，统一了黄河流域。黄帝之所以生四帝也，这就是当年黄帝之所以能够战胜四帝的原因。
凡军好高而恶下：军，指驻军。凡军好高而恶下，大凡军队扎营都是喜欢选择地势高的干燥地方而讨厌地势低下的潮湿地方。
养生而处实：养生，这里是指，水草丰盛，粮饷充足，军队容易修生养息。处实，指军需物资供应方便的地方。养生而处实，这里指军队扎营要选择水草丰盛、粮食充足、军需物资供应方便的地方。
上雨：上，指河流的上游。上雨，河的上游下雨。
水沫：河水的泡沫，这是洪水到来的表现。
绝涧：两岸山势峭峻，水流其间的险恶地形。
天井：四周高俊，中间低洼的地形。天牢：指一种四周地形险恶、易进难出的地形。
天陷：一种地势低洼、泥泞易陷的地形。
天隙：一种两边高山壁立，中间道路狭窄，难以行军的地势。
潢井：潢，积水池。潢井，地势低陷、积水很多的地方。
葭苇：芦苇，泛指水草。这里指水草丛生的地方。
蘙荟：草木茂盛，这里指草木茂密多障碍。
敌近而静者：靠近我军的敌军能保持安静。
所居易者：易，这里指平坦地带。所居易者，敌军在平坦地带驻扎。
散而条达：飞起的尘土散而细长。樵采：这里是指敌军砍柴伐木。
辞强而进驱：以诡诈的言语作掩护，勉强驱军前行。
陈也：陈同“阵”，这里指布阵。
无约而请和者：敌军没有陷入困境却主动请和。
　　奔走而陈兵车：敌军迅速奔跑，并且用战车摆开阵势。
杖而立：杖，兵器。杖而立，敌军依靠着武器站着。
汲而先饮：汲水的敌军争着先喝水。
军无悬缻：缻，泛指饮具。军无悬缻，军中把饮具都收拾起来了。
谆谆翕翕：这里是指敌军长官对士卒讲话显示出一副诚恳的样子。
足以并力料敌：只要能充分地判断敌情，集中使用兵力就行了。
惟无虑而易敌者：只有那不深思熟虑而又轻视敌军的人。
卒为亲附而罚之：当着士卒们还没有亲附时便施加刑罚，士卒们便会怨愤不服。
令素行以教其民：要用平素发布的军令都必定坚决执行的事情来教育士卒。
与众相得：得，亲和。与众相得，这里是指与部下关系融洽。', '孙子说：凡军队行军作战和观察判断敌情，应该注意：在通过山地时要靠近有水草的谷地；驻止时，要选择“生地”，居高向阳；如果敌人占据高地，不要仰攻。这些是在山地行军作战的处置原则。横渡江河，要在离江河稍远的地方驻扎；如果敌军渡河前来进攻，不要在江河中迎击，而要乘它部分已渡、部分未渡半渡时予以攻击，这样比较有利；如果要与敌军交战，那就不要靠近江河迎击它；在江河地带驻扎，也要居高向阳，切勿在敌军下游低凹地驻扎或布阵。这些是在江河地带行军作战的处置原则。通过盐碱沼泽地带，要迅速离开，不宜停留；如在盐碱沼泽地带与敌军遭遇，那就要占领有水草而靠树林的地方。这些是在盐碱沼泽地带行军作战的处置原则。在平原地带驻军，要选择地势平坦的地方，最好背靠高处，前低后高。这些是平原地带行军作战的处置原则。以上四种“处军”原则的好处，是黄帝所以能够战胜“四帝”的重要原因。
大凡驻军，总是喜好干燥的高地而厌恶潮湿低洼的地方，要求向阳，回避阴湿，驻扎在便于生活和地势高的地方，将士就不至于发生各种疾病，这是军队致胜的一个重要条件。丘陵、堤防驻军，必须驻扎在向阳的一面，并且要背靠着它。这些对于用兵有利的措置是得自地形的辅助的。
河流上游下暴雨，看到水沫漂来，要等水势平稳以后再渡，以防山洪暴至。
凡是遇到“绝涧”、“天井”、“天牢”、“天罗”、“天陷”、“天隙”等地形，必须迅速避开而不要靠近。我远离它，让敌军去接近它；我面向它，让敌军去背靠它。
军队在山川险阻、芦苇丛生的低洼地，草木繁茂的山林地区行动，必须仔细反复地搜索，因为这些都是容易隐藏伏兵和奸细的地方。
敌军离我很近而仍保持镇静的，是倚仗它据有险要的地形；敌军离我很远而又来挑战的，是企图诱我前进；敌军之所以不居险要而居平地，定有它的好处和用意。
树林里很多树木摇动的，是敌军向我袭来；在草丛中设有许多遮蔽物的，是敌人企图迷惑我；鸟儿突然飞起，是下面有伏兵；走兽受惊猛跑，是敌人大举来袭。飞尘高而尖的，是敌人战车向我开来；飞尘低而广的，是敌人步卒向我开来；飞尘分散而细长的，是敌人在打柴；飞尘少而时起时落的，是敌军察看地形，准备设营。
敌方使者言词谦卑而实际上又在加紧战备的，是要向我进攻；敌方使者育词强硬而军队又向我进逼的，是准备撤退；敌战车先出并占据侧翼的，是布列阵势，准备作战；敌方没有预先约定而突然来请求议和的，其中必有阴谋；敌方急速奔走并展开兵车的，是期求与我交战；敌军半进半退的，可能是伪装混乱来引诱我。
敌兵倚仗手中的兵器站立的，是饥饿缺粮；敌兵从井里打水而急于先饮的，是于渴缺水；敌人见利而不前进的，是由于疲劳过度。敌方营寨上有飞鸟停集的，说明营寨已空虚无人；敌营夜间有人惊呼的，说明敌军心里恐惧；敌营纷扰无秩序的，是其将帅没有威严；敌营旌旗乱动的，是其阵形混乱；敌官吏急躁易怒，是敌军过度困倦。敌人用粮食喂马，杀牲口吃，收起炊具，不返回营寨的，是“穷寇”；敌兵聚集一起私下低声议论，是其将领不得众心；再三犒赏士卒的。说明敌军已没有别的办法；一再重罚部属的，是敌军陷于困境；将帅先对士卒凶暴后又畏惧士卒的，说明其太不精明了；敌人借故派使者来谈判的，是想休兵息战。敌军盛怒前来，但久不接战，又不离去，必须谨慎观察其企图。
打仗不在于兵力愈多愈好，只要不轻敌冒进，并能集中兵力，判明敌情，也就足以战胜敌人了。那种无深谋远虑而又轻敌妄动的人，势必成为敌人的俘虏。
将帅在士卒尚未亲近依附时，就贸然处罚士卒，那士卒一定不服，这样就难以使用他们去打仗了；如果士卒对将帅已经亲近依附，仍不执行军纪军法，这样的军队也是不能打仗的。所以，要用“文”的手段即用政治道义教育士卒，用“武”的方法即用军纪军法来统一步调，这样的军队打起仗来就必定胜利。平素能认真执行命令、教育士卒，士卒就能养成服从的习惯；平素不认真执行命令、教育士卒，士卒就会养成不服从的习惯。平素所以能认真执行命令，是由于将帅与士卒相互取得信任的缘故。', NULL, '', 'indent', 1522856644, '5ac48242a22b9d0045547367', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637044, '孙子兵法 · 地形篇', NULL, 9, 13, 0, 1, '孙武', NULL, 36849, '59e714859545040067513674', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%99%E5%AD%90%E5%85%B5%E6%B3%95%C2%B7%E5%9C%B0%E5%BD%A2%E7%AF%87/19831530?fr=aladdin&fromid=3721861&fromtitle=%E5%9C%B0%E5%BD%A2%E7%AF%87', '', '孙子曰：地形有通者，有挂者，有支者，有隘者，有险者，有远者。我可以往，彼可以来，曰通；通形者，先居高阳，利粮道，以战则利。可以往，难以返，曰挂；挂形者，敌无备，出而胜之；敌若有备，出而不胜，难以返，不利。我出而不利，彼出而不利，曰支；支形者，敌虽利我，我无出也；引而去之，令敌半出而击之，利。隘形者，我先居之，必盈之以待敌；若敌先居之，盈而勿从，不盈而从之。险形者，我先居之，必居高阳以待敌；若敌先居之，引而去之，勿从也。远形者，势均，难以挑战，战而不利。凡此六者，地之道也；将之至任，不可不察也。
故兵有走者，有弛者，有陷者，有崩者，有乱者，有北者。凡此六者，非天之灾，将之过也。夫势均，以一击十，曰走；卒强吏弱，曰弛，吏强卒弱，曰陷；大吏怒而不服，遇敌怼而自战，将不知其能，曰崩；将弱不严，教道不明，吏卒无常，陈兵纵横，曰乱；将不能料敌，以少合众，以弱击强，兵无选锋，曰北。凡此六者，败之道也；将之至任，不可不察也。
夫地形者，兵之助也。料敌制胜，计险厄远近，上将之道也。知此而用战者必胜，不知此而用战者必败。
故战道必胜，主曰无战，必战可也；战道不胜，主曰必战，无战可也。故进不求名，退不避罪，唯人是保，而利合于主，国之宝也。
视卒如婴儿，故可与之赴深溪；视卒如爱子，故可与之俱死。厚而不能使，爱而不能令，乱而不能治，譬若骄子，不可用也。
知吾卒之可以击，而不知敌之不可击，胜之半也；知敌之可击，而不知吾卒之不可以击，胜之半也；知敌之可击，知吾卒之可以击，而不知地形之不可以战，胜之半也。故知兵者，动而不迷，举而不穷。故曰：知彼知己，胜乃不殆；知天知地，胜乃不穷。', '《孙子兵法·地形篇》是春秋时期兵法家孙武创作的一篇散文。该书主要讲的是六种不同的作战地形及相应的战术要求。', '先居高阳：先，指抢先。高阳，地势高而朝阳的地方。
利粮道，以战：选择有利于保持粮道通畅的地方作战。
出而胜之：出，出击、出战。出而胜之，这里的意思是指出战可以取得胜利。
地虽利我：敌军以利益为诱饵来引诱我军。
盈之以待敌：盈，充盈。盈之以待敌，在山间峡谷的“隘形”地带，我军抢先占据了有力地形必须用充盈的兵力堵住隘口，以等待敌军前来进攻。
盈而勿从：“盈”指敌军兵力充盈。从，跟从，这里引申为进攻。盈而勿从，当敌军已用充足的兵力把守住山隘口时，我军就不能进行攻击。
地之道：这里是指用兵打仗，利用地形的原则。
将之至任：至任，最重大的任务。将之至任，为将者最大的责任。
兵有走者：兵，指败兵。走，指逃走。兵有走者，一种临敌败逃的兵。
有驰者：弛，松弛。弛者：指兵有驰者，即指一种士气不高，纪律涣散难以约制的军队。
有崩者：一种崩溃四散的军队。
有乱者：一种官兵关系混乱紧张，列队杂乱无章的军队。
有北者：一种一遭战斗，便必打败战的军队。
夫势均已一击十曰走：在双方指挥水平、战斗力、乃至所处地形都相当的情况下，却以我方一成兵力去对付敌方十倍于我的兵力，必然会寡不敌众，见敌就跑，这就叫“走兵”。
吏强卒若曰陷：将吏勇敢，但士卒怯弱，没有战斗力，对敌作战，终将陷入覆没。这就叫“馅兵”。
对敌怼而自战：怼，愤怒。对地怼而自战，对敌人满怀怨愤而擅自出战。
将不知其能：统帅部队的主将不了解下面高级军官的才能。
兵无选锋：打战时，没有经过挑选的精锐先头部队。
兵之助：兵，指用兵打仗。兵之助，用兵打仗的辅助条件。
计险厄远近：算计地形的险要和路途的远近。
战道必胜：按照战争自身的规律办事，必然会取得胜利。
主曰无战：君主讲不能战。
可与之赴深溪：可以与人共患难。
爱而不能令：虽然很疼爱他们却又不能命令他们。
知吾卒之可以击：了解自己的军队可以作战。
动而不迷：采取某种军事行动却不致发生迷误。
举而不穷：举措千变万化，没有穷尽。胜乃可穷：可以取得完全的胜利。', '孙子说：地形有通、挂、支、隘、险、远等六类。我们可以去，敌人可以来的地域叫做通；在通形地域，应抢先占据地势高而向阳的地方，并保持粮道畅通，这样与敌交战就有利。可以前进，不易返回的地域叫做挂；在挂形地域，敌军如无防备，就要突然出击战胜它；如果敌有防备，我出击不能取胜，就难以返回，于我不利。凡是我出击不利，敌出击也不利的地方，叫做支；在支形地区，敌人虽然以利诱我，也不要出击；最好是带领部队假装离去，诱使敌军前出一半时，我突然发起攻击，这样有利。在隘形地，我若先敌占据，就要用重兵堵塞隘口，等待敌人来攻；如果敌军已先我占据隘口，并以重兵据守，那就不要进击，若敌人没有用重兵据守隘口，就迅速攻取它。在险形地区，如我先敌占领，要占据地势高而向阳的地方侍击敌人；如果敌人已先占领，那就主动撤退，不要进攻它。在远形地区，双方势均力敌，不宜挑战，勉强求战，于我不利。以上六点，是关于利用地形的原则；这是将帅的重要责任，是不可不认真考虑研究的。
军队失败的情况有走、弛、陷、崩、乱、北等六种。这六种情况，都不是由于天灾造成的，而是由于将帅的过失所致。在敌我条件相当的情况下，如果攻击十倍于我的敌人，因而失败的，叫做走。土卒强悍，将吏懦弱，因而失败的，叫做弛。将吏本领高强，士卒怯弱，因而失败的，叫做陷。部将怨怒而不服从指挥，遇到敌人忿然擅自出战，主将又不了解他的能力而加以控制，因而失败的，叫做崩。主将软弱而又缺乏威严，训练教育不明，吏卒无所遵循，布阵杂乱无章，因而失败的，叫做乱。主将不能正确判断敌情，以少击多，以弱击强，又没有精锐部队为骨干，因而失败的，叫做北。以上六种情况，必然导致军队的失败；这是将帅的重大责任，是不可不认真考虑研究的。
地形是用兵的辅助条件。正确判明敌情，制定取胜计划，研究地形的险易，计算道路的远近，这些都是将帅的职责。懂得这些道理去指导作战的，就必然胜利，不懂得这些道理去指挥作战的，就必然失败。
所以，如果根据战场实情确有必胜把握，即使国君命令不要打，也可以坚决地打；如果根据战场实情不能取胜，即使国君命令打，也可以不打。作为一个将帅，应该进不贪求战胜的功名，退不回避罪责，只求国家和军队得以保全，符合于国君的根本利益，这样的将帅才算是国家最宝贵的人材。
将帅对士卒能像对待婴儿一样体贴，士卒就可以跟随将帅赴汤蹈火；将帅对士卒能像对待自己的“爱子”一样，士卒就可以与将帅同生共死。但是，对士卒如果过分厚养而不能使用，一味溺爱而不能驱使，违犯了纪律也不能严肃处理，这样的军队，就好比“骄子”一样，也是不能用来打仗的。
只了解我军能打，而不了解敌军不可以打，取胜的可能性只有一半；只了解敌军可以打，而不了解我军不能打，取胜的可能性也只有一半；了解敌军可以打，也了解我军能打，而不了解地形条件不可以打，取胜的把握仍然只有一半。所以，真正懂得用兵的将帅，他行动起来，目的明确而不迷误，他所采取的措施变化无穷而不呆板。所以说：了解敌方，了解我方，就能必胜不败；了解天时，了解地利，胜利就不可穷尽了。', NULL, '', 'indent', 1522856709, '5ac482839f545431f970c854', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637046, '孙子兵法 · 火攻篇', NULL, 7, 13, 0, 1, '孙武', NULL, 36849, '59e714859545040067513674', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%99%E5%AD%90%E5%85%B5%E6%B3%95%C2%B7%E7%81%AB%E6%94%BB%E7%AF%87/19831532?fr=aladdin&fromid=3723134&fromtitle=%E7%81%AB%E6%94%BB%E7%AF%87', '', '孙子曰：凡火攻有五：一曰火人，二曰火积，三曰火辎，四曰火库，五曰火队。行火必有因，烟火必素具。发火有时，起火有日。时者，天之燥也；日者，月在箕、壁、翼、轸也。凡此四宿者，风起之日也。
凡火攻，必因五火之变而应之。火发于内，则早应之于外。火发兵静者，待而勿攻，极其火力，可从而从之，不可从而止。火可发于外，无待于内，以时发之。火发上风，无攻下风。昼风久，夜风止。凡军必知有五火之变，以数守之。
故以火佐攻者明，以水佐攻者强。水可以绝，不可以夺。夫战胜攻取，而不修其功者凶，命曰费留。故曰：明主虑之，良将修之。非利不动，非得不用，非危不战。主不可以怒而兴师，将不可以愠而致战；合于利而动，不合于利而止。怒可以复喜，愠可以复悦；亡国不可以复存，死者不可以复生。故明君慎之，良将警之，此安国全军之道也。', '火攻篇主要讲诉对敌作战火的使用原则，包括火攻的目标、使用火攻的条件以及火攻发起后根据战况所做的兵力调配部署。', '火人：火，作动词用，意为烧火、放火。人，此指人马。火人，放火焚烧敌军的人马。
火积：积，积蓄、积藏，这里指积藏的军用粮草。火积，放火焚烧敌军积藏的粮草。
火辎：辎，辎重包括武器、兵车，以及各种军用器械。火辎，放火焚烧敌军的各种军用物资。
月在箕、壁、翼、轸：月，星宿、星座。中国古代天文学家认为天空有二十八星宿，这箕、壁、翼、轸就是其中的四座。月在箕、壁、翼、轸，这里指当月亮运行经过箕、壁、翼、轸这四座的日子。
必因五火之变而应之：因，依据。五火之变，这里指火人、火积、火辎、火库、火队五种火攻形式所引起的敌情变化。应，相应、策应。必因五火之变而应之，必须依据五种火攻形式所引起的敌情变化分别采取相应的配合措施。
火发于内：内，指敌军营内。火发于内，在敌军军营里放火。
则早应之于外：早，提早。早应之于外，提前从外部策应。
火发兵静者：兵，指敌军。火发兵静者，火已燃起但敌军依然表现镇静。
待而勿攻：要耐心等待而不应急于进攻。
火发上风：上风相对于下风而言，指火焰起时，烟雾飞行的顺风方向。火发上风，在上风方向起了火。
凡军必知有五火之变：凡是用兵的人都必须懂得有五种火攻形式及其所引起的敌情变化。
以数守之：数，规律、法则，这里指气象变化的规律。以数守之，指按照气象变化的规律，等待火攻的时机。
以火佐攻者明：以火攻作为向敌人进攻的辅助方法效果很明显。
以水佐攻者强：用水攻的方法辅助进攻，就能使攻势大大增强。
水可以绝：用水攻的方法可以隔断敌军的联系或者断绝敌军的粮道。
不可以夺：用火攻的方法可以烧毁掉敌军的人马和物资。', '孙子说：火攻有五种目标：一是焚烧敌军的人马，二是焚烧敌军的粮草积聚，三是焚烧敌军的辎重，四是焚烧敌军的仓库，五是焚烧敌军的运输设施。实施火攻必须具备一定的条件，发火器材必须经常准备好。发火还要选择有利的时候，起火要选准有利的日期。所谓有利的时候，指的是天气干燥；所谓有利的日期，指月亮运行到“箕”、“壁”、“翼”、“轸”4个星宿的位置，凡是月亮运行到这4个星宿位置时，就是起风的日子。
凡用火攻，必须根据上述五种火攻所造成的情况变化，适时地运用兵力加以策应。从敌人内部放火，就要及早派兵从外面策应。火已烧起，而敌军仍能保持镇静的，要观察等待，不要马上进攻，等火势烧到最旺的时候，视情况可以进攻就进攻，不可以进攻就停止。火也可以从外面放，那就不必等待内应，只要时机和条件成熟就可以放火。火发于上风，不可从下风进攻。白天风刮久了，夜晚风就会停止。军队必须懂得五种火攻方法的变化运用，等候具备条件，然后实施火攻。
用火来辅助进攻的，明显地容易取胜；用水来辅助进攻的，攻势可以加强。水可以断绝敌人的联系，却不能烧毁敌人的蓄积。
凡打了胜仗，攻取了土地、城池，而不能够巩固胜利，是危险的，这就叫做“费留”。因此明智的国君一定要慎重地考虑这个问题，优秀的将帅必须认真处理这个问题。不是对国家有利，就不要采取军事行动，没有取胜的把握，就不要随便用兵，不到危急紧迫之时，就不要轻易开战。国君不可凭一时的恼怒而兴兵打仗，将帅不可凭一时的怨愤而与敌交战。符合国家利益就行动，不符合国家利益就停止。恼怒可以重新欢喜，怨愤可以重新高兴，国亡了就不能再存，人死了不能再活。所以明智的国君对战争问题一定要慎重，良好的将帅对战争问题一定要警惕，这是安定国家和保全军队的关键！', NULL, '', 'indent', 1522856960, '5ac4837eee920a004520d8d6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637047, '孙子兵法 · 用间篇', NULL, 8, 13, 0, 1, '孙武', NULL, 36849, '59e714859545040067513674', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%99%E5%AD%90%E5%85%B5%E6%B3%95%C2%B7%E7%94%A8%E9%97%B4%E7%AF%87/19832786?fr=aladdin&fromid=3723710&fromtitle=%E7%94%A8%E9%97%B4%E7%AF%87', '', '孙子曰：凡兴师十万，出征千里，百姓之费，公家之奉，日费千金；内外骚动，怠于道路，不得操事者，七十万家。相守数年，以争一日之胜，而爱爵禄百金，不知敌之情者，不仁之至也，非人之将也，非主之佐也，非胜之主也。故明君贤将，所以动而胜人，成功出于众者，先知也。先知者，不可取于鬼神，不可象于事，不可验于度，必取于人，知敌之情者也。
故用间有五：有因间，有内间，有反间，有死间，有生间。五间俱起，莫知其道，是谓神纪，人君之宝也。因间者，因其乡人而用之。内间者，因其官人而用之。反间者，因其敌间而用之。死间者，为诳事于外，令吾间知之，而传于敌间也。生间者，反报也。
故三军之事，莫亲于间，赏莫厚于间，事莫密于间。非圣智不能用间，非仁义不能使间，非微妙不能得间之实。微哉！微哉！无所不用间也。间事未发，而先闻者，间与所告者皆死。（莫亲于间：指没有比间谍更应成为亲信了。赏莫厚于间：指没有比间谍更应该得到丰富的奖赏了。事莫密于间：没有经间谍的事更应该保守机密了。间事未发：用间之事还没有开始进行。间与所告者皆死：间谍和告知用间之事的人都要处死。）
凡军之所欲击，城之所欲攻，人之所欲杀，必先知其守将，左右，谒者，门者，舍人之姓名，令吾间必索知之。
必索敌人之间来间我者，因而利之，导而舍之，故反间可得而用也。因是而知之，故乡间、内间可得而使也；因是而知之，故死间为诳事，可使告敌。因是而知之，故生间可使如期。五间之事，主必知之，知之必在于反间，故反间不可不厚也。
昔殷之兴也，伊挚在夏；周之兴也，吕牙在殷。故惟明君贤将，能以上智为间者，必成大功。此兵之要，三军之所恃而动也。', '', '百姓之费：民众百姓的消耗。公家之奉：国家开支的费用。
内外骚动：全国上上下下，每家每户里里外外骚动不安。
怠于道路：老百姓因长途辗转运用军费物资疲劳不堪。
操事：操，这里指操持农事。
七十万家：按曹操、李筌注，古代制度是一家从军，需要七家负担运输国粮等各种劳役。
相守数年：指与敌军对峙数年。
爱爵禄百金：吝惜赏给人们以官位、俸禄和钱财。
非人之将也：人，这里指用人。非人之将，指不懂用人的将领。
非胜之主：不是能主宰打胜战的人。
不可取于鬼神：不能从相信鬼神的迷信活动中了解到敌情。
不可象于事：象，比推、类比。不可象于事，不可能用对等相似事物的类比中去推想出敌情。
不可验于度：不可以用于主观机械的计度去体验所获得的敌情是否准确。
莫知其道：不知道究竟是怎样泄露了军事机密。
人君之宝：君主在战争中，用以克敌制胜的法宝。
因其乡人而用之：利用故乡的人做我的间谍。
因其官人而用之：利用敌方为官者或他们的子孙做我方的间谍。
因其敌间而用之：收买利用敌方的间谍做我方的间谍。
为诳事于外：在外面散布谣言或虚假情报。反报；回来报告敌情。
必先知其守将、左右、谒者、门者、舍人之姓名：必须先探知敌方主将以及他的幕僚亲信、负责通报和传令的官吏、卫士以及勤务人员的姓名。
必索敌人之间来见我者：一定要搜索到敌方派到我方从事间谍活动的人。
因而利之：按杜佑注，此指给以重金收买。
导而舍之：对被我方搜索到的敌方间谍经过开导后，给予任务，将其放走。
因是而知之：是，指反间提供的情报。因是而知之，从反间提供的情报而知道军事机密。
生间可使如期：生间，能活着回来报告敌情的间谍。如期，按期。生间可使如期，生间可以使他们按期回来报告敌情。
知之必在于反间：要掌握五种间谍活动的情况，都可以依靠反间的作用。
殷之兴也：殷商的兴起。
伊挚在夏：伊挚，指伊尹，原为夏桀的大臣以后归附商汤为相，在灭夏的过程中，伊尹发挥了很大的作用。
吕牙在殷：吕牙，指姜尚，又名姜子牙，原是商纣时期的隐士，后归附于周武王。
以上智为间者：用智慧高超的人做间谍。', '　　孙子说：凡兴兵10万，千里征战，百姓的耗费，国家的开支，每天要花费千金，全国上下动荡不安，民众服徭役，疲惫于道路，不能从事耕作的有70万家。战争双方相持数年，是为了胜于一旦，如果吝啬爵禄和金钱不重用间谍，以致不能了解敌人情况而遭受失败，那就太“不仁”了。这样的将帅，不是军队的好将帅，不是国君的好助手；这样的国君，不是能打胜仗的好国君。英明的国君，良好的将帅，之所以一出兵就能战胜敌人，成功地超出众人之上的，其重要原因，在于他事先了解敌情。而要事先了解敌情，不可用迷信鬼神和占卜等方法去取得，不可用过去相似的事情作类比也不可用观察日月星辰运行位置去验证，一定要从了解敌情的人那里去获得。
使用间谍有五种：有因间，有内间，有反间，有死间，有生间。五种间谍同时都使用起来，便敌人莫测高深而无从应付，这是神妙的道理，是国君制胜敌人的法宝。所谓因间，是指利用敌国乡里的普通人做间谍。所谓内间，是指收买敌国的官吏做间谍。所谓反间，是指收买或利用敌方派来的间谍为我效力。所谓死间，是指故意散布虚假情况，让我方间谍知道而传给敌方，敌人上当后往往将其处死。所谓生间，是指派往敌方侦察后能活着回报敌情的。
所以军队人事中，没有比间谍再亲信的，奖赏没有比间谍更优厚的，事情没有比用间更机密的。不是才智过人的将帅不能使用间谍；不是仁慈慷慨的将帅也不能使用间谍；不是用心精细、手段巧妙的将帅不能取得间谍的真实情报。微妙啊！微妙啊！真是无处不可使用问谍呀！用间的计谋尚未施行，就被泄露出去，间谍和知道机密的人都要处死。
凡是要攻击的敌方军队，要攻的敌人城邑，要斩杀的敌方人员，必须预先了解那些守城将帅、左右亲信、掌管传达、通报的官员、负责守门的官吏以及门客幕僚的姓名，命令我方间谍一定要侦察清楚。
必须搜索出敌方派来侦察我方的间谍，以便依据情况进行重金收买、优礼款待，要经过诱导交给任务，然后放他回去，这样，反间就可以为我所用了。从反间那里得知敌人情况之后，所以乡间、内间就可得以使用了。因从反间那里得知敌人情况，所以散布给死间的虚假情况就可以传给敌人。因从反间那里得知敌人情况，所以生间就可遵照预定的期限，回来报告敌情。五种间谍使用之事，国君都必须懂得，其中的关键在于会用反间。所以，对反间不可不给予优厚的待遇。
从前商朝的兴起，是由于重用了在夏为臣的伊尹；周朝的兴起，是由于重用了在殷为官的姜子牙。所以，明智的国君、贤能的将帅，能用极有智谋的人做间谍，一定能成就大的功业。这是用兵作战的重要一着，整个军队都要依靠间谍提供情报而采取行动。', NULL, '', 'indent', 1522857029, '5ac483c02f301e00650c61dc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637051, '青苔赋', NULL, 4, 89, 0, 1, '江淹', NULL, 10308, '57b903ee7db2a2005426b75e', '南北朝', 'fu', '赋', '', '余凿山楹为室，有青苔焉。意之所之，故为是作。', '嗟青苔之依依兮，无色类而可方；必居闲而就寂，似幽意而深伤。故其处石，则松栝交阴，泉雨长注；横涧俯视，崩壁仰顾。悲凹险兮，唯流水而驰骛，遂能崎屈上生，班驳下布，异人贵其贞精，道士悦其回趣。咀松屑以高想，捧丹经而永慕。若其在水，则镜带湖沼，锦匝池林，春塘秀色，阳鸟好音。青郊未谢兮白日照，路贯千里兮绿草深；乃生水而摇荡，遂出波而沉淫。假青条兮葱翠，借黄华兮舒金。游梁之客，徒马疲而不能去；兔园之女，虽蚕饥而不自禁。寂兮如何？苔积网罗。视青蘼之杳杳，痛百代兮恨多，故其所诣，哀以情起。感以怨来，魂虑断绝，精念徘徊。睹彼木兰与豫章，既中绳而获夭；及薜荔与蘼芜，又怀芬而见表。至哉青苔之无用，吾孰知其多少。 ', '', '', '', NULL, '', 'indent', 1586214379, '5ac5dab34773f7005d67ba75', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637052, '茶经 · 一之源', NULL, 64, 14, 0, 1, '陆羽', NULL, 13217, '584432e0c59e0d0056a3b0e9', '唐', 'wen', '文', '', '', '茶者，南方之嘉木也，一尺二尺，乃至数十尺。其巴山峡川有两人合抱者，伐而掇之，其树如瓜芦，叶如栀子，花如白蔷薇，实如栟榈，蒂如丁香，根如胡桃。
其字或从草，或从木，或草木并。其名一曰茶，二曰槚，三曰蔎，四曰茗，五曰荈。
其地，上者生烂石，中者生砾壤，下者生黄土。
凡艺而不实，植而罕茂，法如种瓜，三岁可采。野者上，园者次；阳崖阴林，紫者上，绿者次；笋者上，牙者次；叶卷上，叶舒次。阴山坡谷者，不堪采掇，性凝滞，结瘕疾。
茶之为用，味至寒，为饮最宜。精行俭德之人，若热渴、凝闷、脑疼、目涩、四肢乏、百节不舒，聊四五啜，与醍醐、甘露抗衡也。
采不时，造不精，杂以卉莽，饮之成疾。
茶为累也，亦犹人参。上者生上党，中者生百济、新罗，下者生高丽。有生泽州、易州、幽州、檀州者，为药无效，况非此者，设服荠苨，使六疾不瘳。知人参为累，则茶累尽矣。', '', '伐而掇之：伐，砍下枝条。《诗经.周南》：伐其条枚。掇，拾拣。
栟榈：棕树。《说文》：“栟榈，棕也”。栟，读音bing。
根皆下孕，兆至瓦砾：下孕，在地下滋生发育。兆，裂开，指核桃与茶树生长时根将土地撑裂，方始出土成长。
开元文字音义：字书名。唐开元二十三年（735）编辑的字书。早佚。
槚：读音jia，本为楸、梓类的美木，借指为茶。
蔎：读音she，《玉篇》：“蔎，香草也”。清人段玉裁认为应是草香。借指为茶。
荈：读音chuan。茶树老叶制成的茶。
杨执戟：即杨雄，西汉人，哲学家、文学家，执戟是其官职。
郭弘农：即郭璞，晋人，诗人、文字学家，注释过《尔雅》。
艺而不实：艺，指种植技术。
叶卷上，叶舒次：叶片卷者为初生故其质量好，舒展平直者质量次。
性凝滞，结瘕疾：凝滞，凝结不散。瘕，腹中肿块。《正字通》：“腹中肿块，坚者曰症，有物形曰瘕”。
醍醐、甘露：醍醐，酥酪上凝聚的油，味甘美。甘露，古人认为它是“天之津液”。
卉莽：野草。
上党：唐时郡名，治所在今山西长治市长子、潞城一带。
百济、新罗：唐时位于朝鲜半岛上的两个小国，百济在半岛西南部，新罗在半岛东南部。
高丽：应为高句丽，唐时位于朝鲜半岛上的小国，即今朝鲜。
泽州、易州、幽州、澶州：皆为唐时州名。治所分别在今山西晋城、河北易县、北京市区北、北京市怀柔县一带。
荠苨：一种形似人参的野果。苨，读音ni。
六疾不瘳：六疾，指人遇阴、阳、风、雨、晦、明得的多种疾病。瘳，痊愈。', '茶，是我国南方的优良树木。它高一尺、二尺。有的甚至高达几十尺。在巴山、峡川一带。有树杆粗到两人合抱的。要将树枝砍下来，才能采摘到芽叶。
茶树的树形像瓜芦。叶形像栀子。花像白蔷薇，种子像棕榈。果柄像丁香，根像胡桃。
''茶''字的结构，有的从''草''部（写作''茶''），有的从''木''部（写作''[木荼]''），有的''草''''木''兼从（写作''荼''）。荼的名称有五种：一称''茶''，二称''槚''，三称''蔎''，四称''茗''，五称''荈''。
种茶的土壤，以岩石充分风化的土壤为最好，今有碎石子的砾壤次之，黄色粘土最差。
一般说来，茶苗移栽的技术掌握不当。移栽后的茶树很少长得茂盛。种植的方法象种瓜一样。种后三年即可采茶。茶叶的品质，以山野自然生长的为好，在园圃栽种的较次。在向阳山坡，林荫覆盖下生长的茶树，芽叶呈紫色的为好，绿色的差些；芽叶以节间长，外形细长如笋的为好，芽叶细弱的较次。叶绿反卷的为好，叶面平展的次之。生长在背阴的山坡或山谷的品质不好，不值得采摘。因为它的性质凝滞，喝了会使人腹胀。
茶的功用，因为它的性质冷凉，可以降火，作为饮料最适宜。品行端正有节俭美德的人，如果发烧，口渴，胸闷，头疼，眼涩，四肢无力，关节不畅，喝上四五口，其效果与最好的饮料醍醐、甘露不相上下。但是，如果采摘的不适时，制造的不精细，夹杂着野草败叶，喝了就会生病。
茶和人参一样，产地不同，质量差异很大，甚至会带来不利影响。上等的人参出产在上党，中等的出产在百济、新罗，下等的出产在高丽。出产在泽州、易州、幽州、檀州的（品质最差），作药用，没有疗效，更何况比它们还不如的呢！倘若误把荠苨当人参服用，将使疾病不得痊愈，明白了对于人参的比喻，茶的不良影响，也就可明白了。', NULL, '', 'indent', 1522954839, '5ac601d4a22b9d00455d63e0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637053, '茶经 · 二之具', NULL, 11, 14, 0, 1, '陆羽', NULL, 13217, '584432e0c59e0d0056a3b0e9', '唐', 'wen', '文', '', '', '籝，一曰篮，一曰笼，一曰筥。以竹织之，受五升，或一斗、二斗、三斗者，茶人负以采茶也。
灶无用突者，釜用唇口者。
甑，或木或瓦，匪腰而泥，篮以箅之，篾以系之。始其蒸也，入乎箪，既其熟也，出乎箪。釜涸注于甑中，又以谷木枝三亚者制之，散所蒸牙笋并叶，畏流其膏。
杵臼，一曰碓，惟恒用者佳。
规，一曰模，一曰桊。以铁制之，或圆或方或花。
承，一曰台，一曰砧。以石为之，不然以槐、桑木半埋地中，遣无所摇动。
襜，一曰衣。以油绢或雨衫单服败者为之，以襜置承上，又以规置襜上，以造茶也。茶成，举而易之。
芘莉，一曰羸子，一曰篣筤。以二小竹长三赤，躯二赤五寸，柄五寸，以篾织，方眼如圃，人土罗阔二赤，以列茶也。
棨，一曰锥刀，柄以坚木为之，用穿茶也。
扑，一曰鞭。以竹为之，穿茶以解茶也。
焙，凿地深二尺，阔二尺五寸，长一丈，上作短墙，高二尺，泥之。
贯，削竹为之，长二尺五寸，以贯茶焙之。
棚，一曰栈，以木构于焙上，编木两层，高一尺，以焙茶也。茶之半干升下棚，全干升上棚。
穿，江东淮南剖竹为之，巴川峡山纫谷皮为之。江东以一斤为上穿，半斤为中穿，四两五两为小穿。峡中以一百二十斤为上，八十斤为中穿，五十斤为小穿。字旧作钗钏之“钏”，字或作贯串，今则不然。如磨、扇、弹、钻、缝五字，文以平声书之，义以去声呼之，其字以穿名之。
育，以木制之，以竹编之，以纸糊之，中有隔，上有覆，下有床，傍有门，掩一扇，中置一器，贮煻煨火，令煴煴然，江南梅雨时焚之以火。', '', '籯：读音ying。竹制的箱、笼、篮子等盛物器具。
筥：读音ju。圆形的盛物竹器。
黄金满籯，不如一经：语出《汉书韦贤传》。谓留给儿孙满箱黄金，不如留给他一本经书。
颜师古：唐初经学家，曾注《汉书》。
突：烟囱，成语有“曲突徙薪”。
甑：读音zeng。古代蒸炊器，似今蒸笼。
篮以箅之，篾以系之：箅，读音bi。蒸笼中的竹屉。篾，读音mie，长条细簿竹片，在此作从甑中取出箅的理耳。
襜：读音chan。系在衣服前面的围裙。《尔雅释物》：“衣蔽前谓之襜”。
芘莉：芘，读音bi。芘莉，竹制的盘子类器具。
蒡莨：读音panglang。笼、盘一类盛物器具。
棨：读音qi，穿茶饼用的锥刀。
煴煴然：煴，读音yun。没有光焰的火。煴煴然，火热微弱的样子。颜师古说：“煴，聚火无焰者也。”', '籯，又叫篮，又叫笼，又叫筥。用竹编织，容积五升，或一斗、二斗、三斗，是茶农背着采茶用的。
灶，不要用有烟囱的（使火力集中于锅底）。锅，用锅口有唇边的。
甑，木制或陶制。腰部用泥封好，甑内放竹篮作甑箅，用竹片系牢。开始蒸的时候，叶子放到箅里；等到熟了，从箅里倒出。锅里的水煮干了，从甑中加水进去。也有用三杈的榖木翻拌。蒸后的嫩芽叶及时摊开，防止茶汁流走。
忤臼，又名碓（用以捣碎蒸熟的芽叶），以经常使用的为好。
规，又叫模，又叫棬（就是模型，用以把茶压紧，并成一定的形状），用铁制成，有的圆形，有的方形，有的像花的形状。
承，又叫台，又叫砧，用石制成。如用槐树、桑树做，就要把下半截埋进土中，使它不能摇动。
檐，又叫衣，可用油绢或穿坏了的雨衣、单衣做成。把''檐''放在''承''上，''檐''上再放模型，用来制造压紧的饼茶。压成一块后，拿起来，另外换一个模型再做。
芘莉，又叫籯子或篣筤。用两根各长三尺的小竹竿，制成身长二尺五寸，手柄长五寸，宽二尺的工具，当中用篾织成方眼，好像种菜人用的土筛，用来放置茶。
棨，又叫锥刀，用坚实的木料做柄，用来给饼茶穿洞眼。
扑，又叫鞭，竹子编成，用来把茶饼穿成串，以便搬运。
焙，地上挖坑深二尺，宽二尺五寸，长一丈，上砌矮墙，高二尺，用泥抹平整。
贯，竹子削制成，长二尺五寸，用来穿茶烘培。
棚，又叫栈。用木做成架子，放在培上，分上下两层，相距一尺，用来烘焙茶。茶半干时，由架底升到下层；全干，升到上层。
穿，江东淮南劈篾做成；巴山峡川用构树皮做成，用来贯串制好的茶饼。江东把一斤称''上穿''，半斤称''中穿''，四两、五两（十六两制）称''下穿''。峡中则称一百二十斤为''上穿''，八十斤为''中穿''，五十斤为''小穿''。''穿''字，先前作钗钏的''钏''字，或作贯串。现在不同，''磨、扇、弹、钻、缝''五字，字形还是按读平声（作动词）的字形，读音却读去声，意思也按读去声的来讲（作名词）。''穿''字读去声，表示一个单位。
育，用木制成框架，竹篾编织外围，再用纸裱糊。中有间隔，上有盖，下有托盘，旁开一扇门。中间放一器皿，盛有火灰，使有火无焰。江南梅雨季节，加火除湿。', NULL, '', 'indent', 1522955026, '5ac6028d9f54541c8b9b46c1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637054, '茶经 · 三之造', NULL, 4, 14, 0, 1, '陆羽', NULL, 13217, '584432e0c59e0d0056a3b0e9', '唐', 'wen', '文', '', '', '凡采茶，在二月三月四月之间。茶之笋者生烂石沃土，长四五寸，若薇蕨始抽，凌露采焉。茶之牙者，发于丛薄之上，有三枝四枝五枝者，选其中枝颖拔者采焉，其日有雨不采，晴有云不采。晴采之，蒸之，捣之，拍之，焙之，穿之，封之，茶之干矣。
茶有千万状，卤莽而言，如胡人靴者蹙缩然，犎牛臆者廉檐然，浮云出山者轮囷然，轻飙拂水者涵澹然。有如陶家之子罗，膏土以水澄泚之。又如新治地者，遇暴雨流潦之所经，此皆茶之精腴。有如竹箨者，枝干坚实，艰于蒸捣，故其形籭簁然；有如霜荷者，至叶凋，沮易其状貌，故厥状委萃然，此皆茶之瘠老者也。
自采至于封七经目，自胡靴至于霜荷八等，或以光黑平正，言嘉者，斯鉴之下也；以皱黄坳垤言佳者；鉴之次也。若皆言嘉及皆言不嘉者，鉴之上也。何者？出膏者光，含膏者皱，宿制者则黑，日成者则黄，蒸压则平正，纵之则坳垤，此茶与草木叶一也，茶之否臧，存于口诀。', '', '丛薄：灌木、杂草丛生的地方。《汉书注》：“灌木曰丛”。杨雄《甘草同赋注》：“草丛生曰薄”。
京锥文也：京，高大。《诗经 皇矣》：“依其在京”。《诗毛传》：“京，大阜也”。锥，刀锥。文，同“纹”。全句意为：大刀锥刻钻的花纹。
臆者，廉襜然：臆，指牛胸肩部位的肉；廉，边侧。《说文》：“廉，仄也”。襜，帷幕。意为像牛胸肩的肉，像侧边的帷幕。
轮囷：轮，车轮。囷，圆顶的仓。
竹箨：竹笋的外壳。箨，读音ruo。
籭簁：籭、簁相通，读音亦同为si，皆为竹器。《说文》：“籭，竹器也”，《集韵》说是竹筛。
坳垤：土地低下处叫坳，小土堆叫垤。形容茶饼表面的凸凹不平。
否臧：否，读音pi，贬，非议；臧，褒奖。《世说新语 德行第一》：“每与人言，未尝臧否人物。”', '采茶都在（唐历）二月、三月、四月间。
肥壮如笋的芽叶，生长在有风化石碎块的土壤上，长达四至五寸，好像刚刚破土而出的薇、蕨嫩茎，清晨带着露水采摘它。次一等的芽叶（短而瘦小），发生在草木夹杂的茶树枝上。从一老枝上发生三枝、四枝、五枝的，选择其中长得挺拔的采摘。当天有雨不采，晴天有云也不采，晴天才能采，采摘的芽叶，把它们上甑蒸熟，用忤臼捣烂，放到模型里用手拍压成一定的形状，接着焙干，最后穿成串，包装好，茶就可以保持干燥了。
茶的形状千姿百态，粗略地说，有的像（唐代）胡人的靴子，皮革皱缩着；有的像封牛的胸部，有细微的褶痕；有的像浮云出山，团团盘曲；有的像轻风拂水，微波涟漪；有的像陶匠筛出细土，再用水沉淀出的泥膏那么光滑润泽；有的又像新整的土地，被暴雨急流冲刷而高低不平。这些都是精美上等的茶。有的叶像笋壳，枝梗坚硬，很难蒸捣，所以制成的茶叶形状像箩筛；有的像经霜的荷叶，茎叶凋败，变了样子，所以制成的茶外貌枯干。这些都是坏茶、老茶。
从采摘到封装，经过七道工序；从类似靴子的皱缩状到类似经霜荷叶的衰萎状，共八个等级。（对于成茶）有的人把光亮、黑色、平整作为好茶的标志，这是下等的鉴别方法。把皱缩、黄色、凸凹不平作为好茶的特征，这是次等的鉴别方法。若既能指出茶的佳处，又能道出不好处，才是最会鉴别茶的。为什么呢？因为压出了茶汁的就光亮，含着茶汁的就皱缩；过了夜制成的色黑，当天制成的色黄；蒸后压得紧的就平整，任其自然的就凸凹不平。这是茶和草木叶子共同的特点。茶制得好坏，有一套口头传授的鉴别方法。', NULL, '', 'indent', 1522955151, '5ac6030d9f54541c8b9b4a7c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637057, '茶经 · 六之饮', NULL, 14, 14, 0, 1, '陆羽', NULL, 13217, '584432e0c59e0d0056a3b0e9', '唐', 'wen', '文', '', '', '翼而飞，毛而走，去而言，此三者俱生于天地间。饮啄以活，饮之时，义远矣哉。至若救渴，饮之以浆；蠲忧忿，饮之以酒；荡昏寐，饮之以茶。茶之为饮，发乎神农氏，间于鲁周公，齐有晏婴，汉有扬雄、司马相如，吴有韦曜，晋有刘琨、张载、远祖纳、谢安、左思之徒，皆饮焉。滂时浸俗，盛于国朝，两都并荆俞间，以为比屋之饮。饮有粗茶、散茶、末茶、饼茶者，乃斫，乃熬，乃炀，乃舂，贮于瓶缶之中，以汤沃焉，谓之茶。或用葱、姜、枣、橘皮、茱萸、薄荷之等，煮之百沸，或扬令滑，或煮去沫，斯沟渠间弃水耳，而习俗不已。于戏！天育万物皆有至妙，人之所工，但猎浅易。所庇者屋屋精极，所着者衣衣精极，所饱者饮食，食与酒皆精极之。茶有九难：一曰造，二曰别，三曰器，四曰火，五曰水，六曰炙，七曰末，八曰煮，九曰饮。阴采夜焙非造也，嚼味嗅香非别也，膻鼎腥瓯非器也，膏薪庖炭非火也，飞湍壅潦非水也，外熟内生非炙也，碧粉缥尘非末也，操艰搅遽非煮也，夏兴冬废非饮也。夫珍鲜馥烈者，其碗数三；次之者，碗数五。若坐客数至，五行三碗，至七行五碗。若六人已下，不约碗数，但阙一人而已，其隽永补所阙人。', '', '呿而言：呿，读音qi，张口。《集韵》：“启口谓之呿''。这里指开口会说话的人类。
蠲忧忿：蠲，读音juan，免除。《史记太史公自序》：“蠲除肉刑”。
神农氏：传说中的上古三皇之一，教民稼穑，号神农，后世尊为炎帝。后人伪托神农作《神农本草》等书，其中提到茶，故云“发乎神农氏”。
鲁周公：名姬旦，周文王之子，辅佐武王灭商，建西周王朝，制礼作乐，后世尊为周公，因封国在鲁，又称鲁周公。后人伪托周公作《尔雅》，其中讲到茶。
晏婴（？—公元前500）：字平仲，春秋之际政治家，齐国名相。相传著有《晏子春秋》。
杨雄、司马相如：杨雄，见前注。司马相如（前178—前118），字长卿，蜀郡成都人。西汉著名文学家，著有《子虚赋》、《上林赋》等。
韦曜（220—280）：应作韦昭，字弘嗣，三国时人，在东吴历任中书仆射、太傅等要职。
刘琨、张载、远祖纳、谢安、左思之徒：
刘琨（271—318），字越石，晋中山魏昌人（今河北无极县），曾任西晋平北大将军等职；
张载，字孟阳，晋安平（今河北深县）人。文学家，有《张孟阳集》传世；
远祖纳，即陆纳（320？--395），字祖言，吴郡吴（今江苏苏州）人。东晋时任吏部尚书等职。陆羽与其同姓，故尊为远祖；
谢安（319--385），字安石，陈国阳夏人（今河南太康县）。东晋名臣；
左思（250？--305？），字太冲，山东临淄人。著名文学家，代表作有《三都赋》、《咏史》诗等。
两都并荆俞间：两都，长安和洛阳。荆州，治所在今湖北江陵。俞，或作渝。渝州，治所在今四川重庆一带。
痷：痷读an，意为病态。《博雅》：“病也”。
飞湍壅潦：飞湍，飞奔的急流。潦，雨后积水。壅潦，停滞的积水。潦，雨后积水。
操艰搅遽：操作艰难、慌乱。遽，读音ju，惶恐、窘急。', '禽鸟有翅而飞，兽类毛丰而跑，人开口能言，这三者都生在天地间。依靠喝水、吃东西来维持生命活动。可见喝饮的作用重大，意义深远。为了解渴，则要喝水；为了兴奋而消愁解闷，则要喝酒；为了提神而解除瞌睡，则要喝茶。
茶作为饮料，开始于神农氏，由周公旦作了文字记载而为大家所知道。春秋时齐国的晏婴，汉代的扬雄、司马相如，三国时吴国的韦曜，晋代的刘琨、张载、陆纳、谢安、左思等人都爱喝茶。后来流传一天天广泛，逐渐成为风气，到了我唐朝，达于极盛。在西安、洛阳两个都城和江陵、重庆等地，竟是家家户户饮茶。
茶的种类，有粗茶、散茶、末茶、饼茶。（要饮用饼茶时）用刀砍开，炒，烤干，捣碎，放到瓶缶中，用开水冲灌，这叫做''夹生茶''。或加葱、姜、枣、橘皮、茱萸、薄荷等，煮开很长的时间，把茶汤扬起变清，或煮好后把茶上的''沫''去掉，这样的茶无异于倒在沟渠里的废水，可是一般都习惯这么做！
啊，天生万物，都有它最精妙之处，人们擅长的，只是那些浅显易做的。住的是房屋，房屋构造精致极了；所穿的是衣服，衣服做的精美极了；饱肚子的是饮食，食物和酒都精美极了。（而饮茶呢？却不擅长。）概言之，茶有九难：一是制造，二是识别，三是器具，四是火力，五是水质，六是炙烤，七是捣碎，八是烤煮，九是品饮。阴天采，夜间焙，则制造不当；凭口嚼辨味，鼻闻辨香，则鉴别不当；用沾染了膻气的锅与腥气的盆，则器具不当；用有油烟的柴和烤过肉的炭，则燃料不当；用流动很急或停滞不流的水，则用水不当；烤得外熟内生，则炙烤不当；捣得太细，成了绿色的粉末，则捣碎不当；操作不熟练，搅动太急，则烧煮不当；夏天才喝，而冬天不喝，则饮用不当。
属于珍贵鲜美馨香的茶，（一炉）只有三碗。其次是五碗。假若喝茶的客人达到五人，就舀出三碗传着喝；达到七人，就舀出五碗传着喝；假若是六人，不必管碗数（意谓照五人那样舀三碗），只不过缺少一人的罢了，那就用''隽永''来补充。', NULL, '', 'indent', 1522955700, '5ac605332f301e0065153cb2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637058, '茶经 · 七之事', NULL, 11, 14, 0, 1, '陆羽', NULL, 13217, '584432e0c59e0d0056a3b0e9', '唐', 'wen', '文', '', '', '三皇炎帝。神农氏。周鲁周公旦。齐相晏婴。汉仙人丹丘子。黄山君司马文。园令相如。杨执戟雄。吴归命侯。韦太傅弘嗣。晋惠帝。刘司空琨。琨兄子兖州刺史演。张黄门孟阳。傅司隶咸。江洗马充。孙参军楚。左记室太冲。陆吴兴纳。纳兄子会稽内史俶。谢冠军安石。郭弘农璞。桓扬州温。杜舍人毓。武康小山寺释法瑶。沛国夏侯恺。馀姚虞洪。北地傅巽。丹阳弘君举。安任育。宣城秦精。敦煌单道开。剡县陈务妻。广陵老姥。河内山谦之。后魏琅琊王肃。宋新安王子鸾。鸾弟豫章王子尚。鲍昭妹令晖。八公山沙门谭济。齐世祖武帝。梁·刘廷尉。陶先生弘景。皇朝徐英公绩。
《神农·食经》：“茶茗久服，令人有力、悦志”。
周公《尔雅》：“槚，苦茶。”《广雅》云：“荆巴间采叶作饼，叶老者饼成，以米膏出之，欲煮茗饮，先灸，令赤色，捣末置瓷器中，以汤浇覆之，用葱、姜、橘子芼之，其饮醒酒，令人不眠。”
《晏子春秋》：“婴相齐景公时，食脱粟之饭，灸三戈五卯茗莱而已。”
司马相如《凡将篇》：“乌啄桔梗芫华，款冬贝母木蘖蒌，芩草芍药桂漏芦，蜚廉雚菌荈诧，白敛白芷菖蒲，芒消莞椒茱萸。”
《方言》：“蜀西南人谓茶曰葭。”
《吴志·韦曜传》：“孙皓每飨宴坐席，无不率以七胜为限。虽不尽入口，皆浇灌取尽，曜饮酒不过二升，皓初礼异，密赐茶荈以代酒。”
《晋中兴书》：“陆纳为吴兴太守，时卫将军谢安常欲诣纳，纳兄子俶怪纳，无所备，不敢问之，乃私蓄十数人馔。安既至，所设唯茶果而已。俶遂陈盛馔珍羞必具，及安去，纳杖俶四十，云：‘汝既不能光益叔父，柰何秽吾素业？’”
《晋书》：“桓温为扬州牧，性俭，每燕饮，唯下七奠，拌茶果而已。”
《搜神记》：“夏侯恺因疾死，宗人字苟奴，察见鬼神，见恺来收马，并病其妻，着平上帻单衣入，坐生时西壁大床，就人觅茶饮。”
刘琨《与兄子南兖州刺史演书》云：“前得安州干姜一斤、桂一斤、黄芩一斤，皆所须也，吾体中溃闷，常仰真茶，汝可置之。”
傅咸《司隶教》曰：“闻南方有以困蜀妪作茶粥卖，为帘事打破其器具。又卖饼于市，而禁茶粥以蜀姥何哉！”
《神异记》：“馀姚人虞洪入山采茗，遇一道士牵三青牛，引洪至瀑布山曰：‘予丹丘子也。闻子善具饮，常思见惠。山中有大茗可以相给，祈子他日有瓯牺之余，乞相遗也。’因立奠祀。后常令家人入山，获大茗焉。”
左思《娇女诗》：“吾家有娇女，皎皎颇白皙。小字为纨素，口齿自清历。有姊字惠芳，眉目粲如画。驰骛翔园林，果下皆生摘。贪华风雨中，倏忽数百适。心为茶荈剧，吹嘘对鼎䥶。”
张孟阳《登成都楼诗》云：“借问杨子舍，想见长卿庐。程卓累千金，骄侈拟五侯。门有连骑客，翠带腰吴钩。鼎食随时进，百和妙且殊。披林采秋橘，临江钓春鱼。黑子过龙醢，果馔逾蟹蝑。芳茶冠六情，溢味播九区。人生苟安乐，兹土聊可娱。”
傅巽《七诲》：“蒲桃、宛柰、齐柿、燕栗、峘阳黄梨、巫山朱橘、南中茶子、西极石蜜。”
弘君举食檄：寒温既毕，应下霜华之茗，三爵而终，应下诸蔗、木瓜、元李、杨梅、五味橄榄、悬豹、葵羹各一杯。孙楚歌：‘茱萸出芳树颠，鲤鱼出洛水泉，白盐出河东，美豉出鲁渊。姜桂茶荈出巴蜀，椒橘、木兰出高山，蓼苏出沟渠，精稗出中田。’”
华佗《食论》：“苦茶久食益意思。”
壶居士《食忌》：“苦茶久食羽化。与韭同食，令人体重。”郭璞《尔雅注》云：“树小似栀子，冬生叶，可煮羹饮，今呼早取为茶，晚取为茗，或一曰荈，蜀人名之苦茶。”
《世说》：“任瞻字育长，少时有令名。自过江失志，既下饮，问人云：‘此为茶为茗？’觉人有怪色，乃自分明云：‘向问饮为热为冷？’”
《续搜神记·晋武帝》：“宣城人秦精，常入武昌山采茗，遇一毛人长丈余，引精至山下，示以丛茗而去。俄而复还，乃探怀中橘以遗精，精怖，负茗而归。”
晋四王起事，惠帝蒙尘，还洛阳，黄门以瓦盂盛茶上至尊。
《异苑》：“剡县陈务妻少，与二子寡居，好饮茶茗。以宅中有古冢，每饮，辄先祀之。二子患之曰：‘古冢何知？徒以劳。’意欲掘去之，母苦禁而止。其夜梦一人云：吾止此冢三百余年，卿二子恒欲见毁，赖相保护，又享吾佳茗，虽潜壤朽骨，岂忘翳桑之报。及晓，于庭中获钱十万，似久埋者，但贯新耳。母告，二子惭之，从是祷馈愈甚。”
《广陵耆老传》：“晋元帝时有老姥，每旦独提一器茗，往市鬻之，市人竞买，自旦至夕，其器不减，所得钱散路傍孤贫乞人。人或异之，州法曹絷之狱中，至夜，老姥执所鬻茗器，从狱牖中飞出。”
《艺术传》：“敦煌人单道开不畏寒暑，常服小石子。所服药有松桂蜜之气，所余茶苏而已。”释道该说《续名僧传》：“宋释法瑶姓杨氏，河东人，永嘉中过江遇沈台真，请真君武康小山寺，年垂悬车，饭所饮茶，永明中敕吴兴礼致上京，年七十九。”
《宋江氏家传》：“江统字应迁，愍怀太子洗马，常上疏谏云：‘今西园卖酰面蓝子菜茶之属，亏败国体。’”
《宋录》：“新安王子鸾、豫章王子尚，诣昙济道人于八公山，道人设茶茗，子尚味之曰：此甘露也，何言茶茗。”
王微《杂诗》：“寂寂掩高阁，寥寥空广厦。待君竟不归，收领今就槚。
鲍昭妹令晖着《香茗赋》。
南齐世祖武皇帝遗诏：“我灵座上，慎勿以牲为祭，但设饼果、茶饮、干饭、酒脯而已。”
梁刘孝绰、谢晋安王饷米等，启传诏：李孟孙宣教旨，垂赐米、酒、瓜、笋、菹、脯、酢、茗八种，气苾新城，味芳云松。江潭抽节，迈昌荇之珍；疆场擢翘，越葺精之美。羞非纯束野麇，裛似雪之驴；鲊异陶瓶河鲤，操如琼之粲。茗同食粲酢，颜望楫免，千里宿舂，省三月种聚。小人怀惠，大懿难忘。陶弘景《杂录》：“苦茶轻换膏，昔丹丘子青山君服之。”
《后魏录》：“琅琊王肃仕南朝，好茗饮莼羹。及还北地，又好羊肉酪浆，人或问之：茗何如酪？肃曰：茗不堪与酪为奴。”
《桐君录》：“西阳武昌庐江昔陵好茗，皆东人作清茗。茗有饽，饮之宜人。凡可饮之物，皆多取其叶，天门冬、拔揳取根，皆益人。又巴东别有真茗茶，煎饮令人不眠。俗中多煮檀叶，并大皂李作茶，并冷。又南方有瓜芦木，亦似茗，至苦涩，取为屑茶，饮亦可通夜不眠。煮盐人但资此饮，而交广最重，客来先设，乃加以香芼辈。《坤元录》：“辰州溆浦县西北三百五十里无射山，云蛮俗当吉庆之时，亲族集会，歌舞于山上，山多茶树。”
《括地图》：“临遂县东一百四十里有茶溪。”
山谦之《吴兴记》：“乌程县西二十里有温山，出御荈。《夷陵图经》：“黄牛、荆门、女观望州等山，茶茗出焉。”
《永嘉图经》：“永嘉县东三百里有白茶山。”
《淮阴图经》：“山阳县南二十里有茶坡。”
《茶陵图经》云：“茶陵者，所谓陵谷，生茶茗焉。”《本草·木部》：“茗，苦茶，味甘苦，微寒，无毒，主瘘疮，利小便，去痰渴热，令人少睡。秋采之苦，主下气消食。注云：春采之。”
《本草·菜部》：“苦茶，一名荼，一名选，一名游冬。生益州川谷山陵道傍，凌冬不死。三月三日采干。注云：疑此即是今茶，一名荼，令人不眠。本草注。”按《诗》云“谁谓荼苦”，又云“堇荼如饴”，皆苦菜也。陶谓之苦茶，木类，非菜流。茗，春采谓之苦？茶。
《枕中方》：“疗积年瘘，苦茶、蜈蚣并灸，令香熟，等分捣筛，煮甘草汤洗，以末傅之。”
《孺子方》：“疗小儿无故惊蹶，以葱须煮服之。”', '', '归命侯：即孙皓（242—283），东吴亡国之君。公元280年，晋灭东吴，孙皓投降，封“归命侯”。
惠帝：惠帝司马衷，西晋的第二代皇帝，公元290--306年在位。
张黄门孟阳：张载字孟阳，著名诗人。但未任过黄门侍郎，任黄门侍郎的是他的弟弟、诗人张协。
傅司隶咸：傅咸（239--294），字长虞，北地泥阳（今陕西铜川）人，官至司隶校尉，简称司隶。
江洗马统：江统（？--310），字应元，陈留县（今河南杞县东）人，曾任太子洗马。
孙参军楚：孙楚（218？--293），字子荆，太原中都人（今山西平遥县），曾任扶风参军。
桓扬州温：桓温（312--373），字元子，龙亢（今安徽怀远县西）人，曾任扬州牧等职。
沛国夏侯恺：晋书无传，干宝《搜神记》中提到他。
新安任育长：任育长，生卒年不详，新安（今河南渑池）人。名瞻，字育长，曾任天门太守等职。
敦煌单道开：东晋著名佛教徒，敦煌人，《晋书》有传。
琅琊王肃：王肃（436--501）字恭懿，琅琊（今山东临沂）人，初仕南齐，因父兄被南齐武帝所杀，乃投北魏。是北魏著名文士，曾任尚书令等职。
新安王子鸾、鸾弟豫章王子尚：刘子鸾、刘子尚，都是南北朝时宋孝武帝的儿子。一封新安王，一封豫章王。但子尚为兄，子鸾为弟。
鲍昭妹令晖：鲍昭，应为鲍照（414--466），字明远，东海郡（今江苏镇江）人，南朝著名诗人。其妹令晖，擅长诗赋。《玉台新咏》载其“著香茗赋集》行于世”，但该集已佚。钟嵘《诗品》说她：“往往崭新清巧，拟古尤胜。”
八公山沙门潭济：八公山，在今安徽寿县北。沙门，佛教指出家修行的人。潭济，应为昙济，曾著《五家七宗论》，是南朝宋名僧。
世祖武帝：南北朝时南齐的第二个皇帝，名肖赜，公元483--493在位。
刘廷尉：刘孝绰（481--539），彭城（今江苏徐州）人，文学家。为梁昭明太子赏识，任太子太仆兼廷尉卿。
陶先生弘景：陶弘景（456--536），字通明，秣陵（今江苏宁县）人，著名道士，有《神农本草经集注》传世。
徐英公勣：徐世勣（592--667），字懋功，唐开国功臣，封英国公。
神农食经：古书名，已佚。
广雅：字书。三国时张辑撰，是对《尔雅》的补作。
晏子春秋：又称《晏子》，旧题齐晏婴撰，实为后人采晏子事辑成，成书约在汉初。 此处陆羽引书有误。《晏子春秋》原为：“炙三戈五卵苔菜而矣”，不是“茗菜”。
凡将篇：伪托司马相如所作的书，已佚。此处引文为后人所辑。
晋中兴书：已佚，现有清人辑存一卷。
搜神记：东晋干宝著，计三十卷，为我国志怪小说之始。
南兖州：晋时州名，治所在今江苏镇江市。
安州：晋时州名，治所在今湖北安陆县一带。
神异记：西晋道士王浮著，原书已佚。
左思《娇女诗》：原诗五十六句，陆羽所引仅为有关茶的十二句。
张孟阳《登成都楼诗》： 原诗三十二句，陆羽仅录有关茶的十六句。
华佗《食论》：华佗（约141--208），字元化，东汉名医。传说其作《食论》，已佚。
壶居士：道教传说的真人之一，又称壶公。
世说：即《世说新语》，南朝宋临川王刘义庆著，为我国志人小说之始。
续搜神记：旧题陶潜著，实为后人伪托。
晋四王起事：南朝卢綝著，原书已佚。
异苑：东晋末刘敬叔所撰，今存十卷。
翳桑之报：翳桑，古地名。春秋时晋赵盾，曾在翳桑救了将要饿死的灵辄，后来晋灵公欲杀赵盾，灵辄扑杀恶犬，救出赵盾。后世称此事为“翳桑之报”。
艺术传：即唐房玄龄所著《晋书 艺术列传》。
淮南子：又名《淮南鸿烈传》，为汉淮南王刘安及其门客所著，今存二十篇。
江氏家传：南朝宋江统著，已佚。
 怀太子：晋惠帝之子，立为太子，元康元年（300年）为贾后害死，年仅二十一岁。
醯：读xi，醋。陆德明《经典释文》：“醯，酢（醋）也。”
王微《杂诗》：王微，南朝诗人。《杂诗》原二十八句，陆羽仅录四句。
南齐世祖武帝《遗诏》：南朝齐武皇帝名肖赜。《遗诏》写于齐永十一年（493年）。
梁刘孝绰《谢晋安王饷米等启》：刘孝绰，见前注。他本名冉，孝绰是他的字。晋安王名肖纲，昭明太子卒后，继为皇太子，后登位称简文帝。
王肃事：王肃，本在南朝齐做官，后降北魏。北魏是北方少数民族鲜卑族拓跋部建立的政权，该民族习性喜食牛羊肉、鲜牛羊奶加工的酪浆。王肃为讨好新主子，所以当北魏高祖问他时，他贬低说茶还不配给酪浆作奴仆。这话传出后，北魏朝贵遂称茶为“酪奴”。
桐君录：全名《桐君采药录》，已佚。
西阳、武昌、庐江、晋陵：西阳、武昌、庐江、晋陵均为晋时郡名，治所分别在今湖北黄冈、湖北武昌、安徽舒城、江苏常州一带。
巴东：晋时郡名。治所在今四川万县一带。
交广：交州和广州。交州，在今广西合浦、北海市一带。
坤元录：古地学书名，已佚。
括地图：即《地括志》，已散佚，清人辑存一卷。
临遂：晋时县名，今湖南衡东县。
吴兴记：南朝宋山谦之著，共三卷。
乌程县：县治所在今浙江湖州市。
夷陵图经：夷陵，在今湖北宜昌地区，这是陆羽从方志中摘出自已加的书名。
黄牛、荆门、女观、望州：黄牛山在今宜昌市向北八十里处。荆门山在今宜昌市东南三十里处。女观山在今宜都县西北。望州山在今宜昌市西。
永嘉县：州治在今浙江温州市。
山阳县：今称淮安县。
茶陵：即今湖南茶陵县。
本草 ：《本草》即《唐新修本草》，又称《唐本草》，因唐英国公徐勣任该书总监。下文《本草》同。
谁谓荼苦：语出《诗经 谷风》：“谁谓荼苦，其甘如荠。” 这里是野菜。
堇荼如饴：语出《诗经 绵》：“周原[月无][月无]，堇荼如饴。”', '（共四十七则，择有关人名略记于下）神农氏（又称''炎帝''，''三皇''之一）。周公（名''旦''）。齐相晏婴。汉仙人丹邱子。黄山君。（汉）孝文园令司马相如。（汉）给事黄门侍郎（执戟）扬雄。吴归命侯、太傅韦宏嗣（韦曜）。晋惠帝。（晋）司空刘琨，琨兄之子衮州刺史刘演。（晋）张孟阳（张载）。（晋）司隶校尉傅咸。（晋）太子洗马江统。（晋）参军孙楚。（晋）记室督左太冲（左思）。（晋）吴兴人陆纳，纳兄子会稽内史陆俶。（晋）冠军谢安石（谢安）。（晋）弘农太守郭璞。（晋）扬州太守桓温。（晋）舍人杜毓。武康小山寺和尚法瑶。沛国人夏侯恺。余姚人虞洪。北地人傅巽。丹阳人弘君举。乐安人任瞻。宣城人秦精。敦煌人单道开。剡县陈务之妻。广陵一老妇人。河内人山谦之。后魏瑯琊人王肃。刘宋新安王子鸾，鸾之弟豫章王子尚。鲍照之妹鲍令晖。八公山和尚谭济。南齐世祖武皇帝。（南朝梁）廷尉刘孝绰。（南朝梁）陶弘景先生。唐朝英国公徐［责力］。
周公《尔雅》说：''槚，就是苦茶。''
《神农食经》说：''长期饮茶，使人精力饱满，兴奋。''
《广雅》说：''荆州（湖北西部）、巴州（四川东部）一带地方，采茶叶做成茶饼，叶子老的，制成茶饼后，用米汤浸泡它。想煮茶喝时，先烤茶饼，使它呈现红色，捣成碎末放置瓷器中，冲进开水。或放些葱、姜、橘子合着煎煮。喝了它可以醒酒，使人兴奋不想睡？
《晏子春秋》说：''晏婴作齐景公的相时，吃的是粗粮（菜）是烧烤的禽鸟和蛋品，除此之外，只饮茶罢了。
汉司马相如《凡将篇》在药物类中记载有：''鸟头、桔梗、芫花、款冬花、贝母、木香、黄柏、瓜蒌、黄芩、甘草、芍药、肉桂、漏芦、蟑螂、雚芦、荈茶、白蔹、白芷、菖蒲、芒硝、茵芋、花椒、茱萸。''
汉扬雄《方言》说：''蜀西南人把茶叶收做蔎。''
三国《吴志·韦曜传》说：''孙皓每次设宴，规定人人要饮酒七升，即使不全部喝下去，也都要酌取完毕。韦曜饮酒不超过二升。孙皓当初非常尊重他，暗地赐茶以代替酒。''
晋《中兴书》说：陆纳做吴兴太守时，卫将军谢安常想拜访陆纳。纳的侄子俶怪他没什么准备，但又不敢问他，便私自准备了十多人的肴馔。谢安来后，陆纳仅仅摆出茶和果品招待，陆俶于是摆上丰盛的肴馔，各种鲜味的菜全都有。等到谢安走后，陆纳打了陆俶四十板子，说：''你既不能使你叔父增加光彩，为什么破坏我廉洁的名声呢？
《晋书》说：''桓温做扬州太守，性好节俭，每次宴会，只设七个盘子的茶食、果馔罢了。''
《搜神记》说？夏侯恺因病去世，族人的儿子苟奴，看见了鬼魂。看见恺来取马匹，把他的妻子也弄成了病。苟奴看见他戴着平上帻，穿的单衣，进屋来坐到活着时常坐的靠西壁的床位上，向人要茶喝。''
刘琨给他哥哥的儿子南衮州刺史刘演写信说：''前些时收得安州干姜一斤、桂一斤、黄芩一斤，都是我需要的。我心烦意乱，精神不好，常常仰靠茶来提神解闷，你可多购买一点。''
傅咸《司隶教》说：''听说剑南蜀郡有一老婆婆，煮茶卖，廉事把她的嚣皿打破了，禁止她在市上卖茶饼和茶羹，使老婆婆陷入了困境，这究竟是为什么？''
《神异记》说：''余姚人虞洪进山采茶，遇见一道士，牵着三条青牛。他引虞洪到瀑布山，说：''我是丹邱子，听说你善于煮茶喝，常想叨你的光。山中有大茶树，可以供你采摘。希望你日后把那喝不完的茶，送些我喝。''虞洪于是设奠祭祀，后来常叫家人进山，果然寻到大茶树。''
西晋左思《娇女诗》云：''我家有娇女，长得很白皙。小名叫［纟丸］素，口齿很伶俐。姐姐叫蕙芳，眉目美如画。蹦蹦跳跳园林中，果子未熟就摘下。爱花哪管风和雨，跑出跑进上百次。看见煮茶心高兴，对着茶炉帮吹气。''
张孟阳《登成都楼》诗大意说：请问当年扬雄的住地在哪里？司马相如的故居又是哪般模样？昔日程郑、卓王孙两大豪门，骄奢淫逸，可比王侯之家。他们的门前经常是车水马龙，宾客不断，腰间飘曳着绿色的缎带，佩挂名贵的宝刀。家中山珍海味，百味调和，精妙无双。真可谓显赫权贵，百万富翁！遥望楼外，富庶的山川无边无际。秋天里，人们在橘林中采摘着丰收的柑橘；春天里，人们在江边把竿垂钓。果品胜过佳肴，鱼肉分外细嫩。四川的香茶在各种饮料中可称第一，它那美味在天下享有盛名。如果人生只是苟且地寻求安乐，那成都这个地方还是可以供人们尽情享乐的。
傅巽《七诲》说：''蒲地的桃子，宛地的苹果，齐地的柿子，燕地的板栗，恒阳的黄梨，巫山的红橘，南中的茶子，西极的石蜜。''
弘君举《食檄》说：''见央寒暄之后，先请喝浮有白沫的三杯好茶。再陈上甘蔗、木瓜、元李、杨梅、五味、橄榄。悬豹、葵羹各一杯。''
孙楚《歌》云：''茱萸出在树颠上，鲤鱼产在洛水中。白盐出在河东，美豉出于鲁渊。姜、桂、茶出巴蜀，椒、橘、木兰出高山。蓼苏长在沟渠，稗子长在田中。''
《华陀食论》说：''长期饮茶，对思考有益。''
壶居士《食忌》说：''长期饮茶，身轻体健，好似飘飘欲仙；茶与韭菜同时吃，使人增加体重。''
郭璞《尔雅注》说：''茶树矮小像栀子。冬季叶不凋零，叶子可煮茶喝。现在把早上采的叫''荼''，晚上采的叫''茗''，又有的叫''荈''，蜀地的人叫它为''苦荼''''。
《世说》云：''任瞻，字育长，青年时期有好的名声，自从过江之后变节失志。有一次到主人家作客，主人陈上茶，他问人说：''这是茶，还是茗？''，发觉旁人有奇怪不解的表情，便自己申明说：''刚才是问茶是热的，还是冷的？''''。
《续搜神记》说：''晋武帝时，宣城人秦精，常进武昌山采茶。一次遇见一个毛人，一丈多高，引秦精到山下，把一丛丛茶树指给他看了才离开，过了一会儿又回来，从怀中掏出橘子送给秦精。秦精害怕，忙背了茶叶回家。''
晋四王叛乱时，惠帝逃难到外面，回到洛阳时，黄门用陶钵盛了茶献给他喝。
《异苑》说：''剡县陈务的妻子，青年时带着两个儿子守寡，喜欢饮茶。因为住处有一古墓，所以每次饮茶总先奉祭一碗。两个儿子感到是个祸害，说：''一个古墓，它知道什么？白花力气！''想把它挖去。母亲苦苦劝说，坚决不准。当夜，梦见一人说：''我住在这墓里三百多年了，你的两个儿子总要毁平它，幸亏你保护，又拿好茶祭奠我，我虽然是地下枯骨，但怎么能忘恩不报呢？''天亮了，在院子里见到了十万串钱，像是埋了很久的，只有穿钱的绳子是新的。母亲把这件事告诉儿子们，两个儿子都很惭愧。从此祭祷更加经常和注重。''
广陵耆老传》说：''晋元帝时，有一老太婆，每天一早，独自提一器皿的茶，到市上去卖。市上的人争着买来喝。从早到晚，那器皿中的茶不减少。她把赚得的钱施舍给路旁的孤儿、穷人和乞丐。有人把她看作怪人，向官府报告，州的官吏把她捆起来，关进监狱。到了夜晚，老太婆手提卖茶的器皿，从监狱窗口飞出去了。
《艺术传》说：''敦煌人单道开，冬天不怕冷，夏天不怕热，经常服食小石子，所服的药有松、桂、蜜的香气，此外只饮茶叶、紫苏罢了。''
《释道该说续名僧传》云：''南朝宋时的和尚法瑶，本姓杨，河东人，永嘉年间过江，在武康小山寺遇见了沈台真清真君，年纪很老了，用饮茶当饭。永明中，皇上下令吴兴官吏隆重地把他送进京城，那时年纪七十九。
宋《江氏家传》说：''江统，字应元。升任愍怀太子洗马。曾经上疏谏道：''现在西园卖醋、面、蓝子、菜、茶之类，有损国家体面''''。
《宋录》说：''新安人王子鸾、王子尚到八公山拜访昙济道人，道人设茶招待他们。子尚尝了尝茶说：''这是甘露啊，怎么说是茶呢？''''
王微《杂诗》云：''静悄悄，关上高阁的门；冷清清，大厦空荡荡。等您啊，您竟迟迟不回来；失望啊，且去饮茶解愁怀。''
鲍照的妹妹令晖写了篇《香茗赋》。
南齐世祖武皇帝的遗诏称：''我的灵座上切莫用杀牲作祭品，只须摆点饼果、茶饮、干饭、酒肉罢了。''
梁刘孝绰呈《谢晋安王饷米等启》中说：''李孟孙君带来了您的告谕，赏赐我米、酒、瓜、笋、菹（酸菜）、脯（肉干）、酢（腌鱼）、茗等八种食品。酒气馨香，味道淳厚，可比新城、云松的佳酿。水边初生的竹笋，胜过菖荇之类的珍羞；田头肥硕的瓜菜，超越好上加好的美味。白茅束捆的野鹿虽好，哪及您惠赐的肉脯？陶侃瓶装的河鲤虽好，哪及您馈赠的鲊鱼？大米如玉粒晶莹，茗荈又似大米精良，酸菜一看就令人开胃。（食品如此丰盛）即使我远行千里，也用不着再筹措干粮。我记着您给我的恩惠，您的大德我永记不忘？
陶弘景《杂录》说：''苦茶能使人轻身换骨，从前丹邱子、黄山君饮用它。
《后魏录》：''琅琊王肃在南朝做官，喜欢喝茶，吃莼羹。等到回到北方，又喜欢吃羊肉，喝羊奶。有人问他：''茶和奶比，怎么样？''肃说：''茶给奶做奴仆的资格都够不上。''''
《桐君录》：''湖北黄冈、武昌、安徽庐江，江苏武进等地人喜欢饮茶，都是主人家准备的。茶有饽，喝了对人有好处。凡可作饮料的植物，大都是用它的叶，而天门冬、菝葜却是用其根，也对人有好处。又湖北巴东有真茶，煮的喝了使人兴奋没有瞌睡。当地人习惯把檀叶和大皂李叶煮当茶，两者的性质都冷。另外，南方有瓜芦树，它的叶大一点，也像茶，很苦很涩，制取为末，像喝茶一样地喝，也可以整夜不眠，煮盐的人全靠喝这。交州和广州很重视饮茶，客人来了，先用它来招待，还加一些香菜？
《坤元录》：''辰州溆浦县西北三百五十里，有无射山，据称：土人风俗，遇到吉庆的时候，亲族聚会，在山上歌舞。山上多茶树。''
《括地图》：''在临遂县以东一百四十里，有茶溪。''
山谦之《吴兴记》：''吴兴县西二十里有温山，出产进贡皇上的茶。'' ）
《夷陵图经》：''黄牛、荆门、女观、望州等山，出产茶叶？
《永嘉图经》：''永嘉县以东三百里，有白茶山。''
《淮阳图经》：''山阳县以南二十里，有茶坡。''
《茶陵图经》说：''茶陵，就是陵谷中生长着茶的意思。''
《本草·木部》：''茗，又叫苦荼。味甘苦，性微寒，没有毒。主治瘘疮，利尿，除痰，解渴，散热，使人少睡。秋天采摘有苦味，能下气，助消化。原注说：要春天采它''。
《本草·菜部》：''苦菜，又叫荼，又叫选，又叫游冬，生长在四川西部的河谷、山陵和路旁，即使在结冰的寒冬也冻不死。三月三日采下，弄干。''（陶弘景）注：怀疑这就是现在称的茶，又叫荼，喝了使人不能入睡。（苏恭）《本草注》按：''《诗经》说''谁说荼苦''，又说''乌头、苦荼像糖一样甜''，指的都是苦菜。陶弘景称的苦荼，是木本植物茶，不是菜类。茗，春季采，叫苦搽。''
《枕中方》：''治疗多年的瘘疾，把茶和蜈蚣一同放在火上烤熟，等发生香气，分成相等的两份，捣碎筛末，一份加甘草煮水洗；一份外敷。''
《孺子方》：''治疗小孩不明原因的惊厥，用苦茶和葱的发根煎水服。''', NULL, '', 'indent', 1522955972, '5ac6063d17d009006179300f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637059, '茶经 · 八之出', NULL, 2, 14, 0, 1, '陆羽', NULL, 13217, '584432e0c59e0d0056a3b0e9', '唐', 'wen', '文', '', '', '山南以峡州上，襄州、荆州次，衡州下，金州、梁州又下。
淮南以光州上，义阳郡、舒州次，寿州下，蕲州、黄州又下。
浙西以湖州上，常州次，宣州、杭州、睦州、歙州下，润州、苏州又下。
剑南以彭州上，绵州、蜀州次，邛州次，雅州、泸州下，眉州、汉州又下。
浙东以越州上，明州、婺州次，台州下。
黔中生恩州、播州、费州、夷州，江南生鄂州、袁州、吉州，岭南生福州、建州、韶州、象州。其恩、播、费、夷、鄂、袁、吉、福、建、泉、韶、象十一州未详。往往得之，其味极佳。', '', '山南：唐贞观十道之一。唐贞观元年，划全国为十道，道辖郡州，郡州辖县。
峡州： 治所在夷陵縣（今湖北宜昌市）。
远安、宜都、夷陵三县：即今湖北远安县、宜都县、宜昌市。
襄州、荆州：襄州，今湖北襄樊市；荆州，今湖北江陵县。
南漳县：今仍名南漳县。
衡州：今湖南衡阳地区。
衡山县：县治所在今衡阳朱亭镇对岸。
金州、梁州：金州，今陕西安康一带；梁州，今陕西汉中一带。
西城、安康：西城，今陕西安康市；安康，治所在今安康市城西五十里汉水西岸。
褒城、金牛：褒城，今汉中褒城镇；金牛，今四川广元。
淮南：唐贞观十道之一。
光州：今河南潢川、光山县一带。
义阳郡：今河南信阳市及其边围。
舒州：今安徽太湖安庆一带。
义阳县钟山：义阳县，今河南信阳。钟山，在信阳市东八十里。
太湖县潜山：潜山，在安徽潜山县西北三十里。
寿州：今安徽寿县一带。
盛唐县霍山：盛唐县，今安徽六安县。霍山，在今霍山县境。
蕲州：今湖北蕲春一带。
黄州：今湖北黄冈一带。
浙西：唐贞观十道之一。
湖州：又名吴兴郡，今浙江吴兴一带。
长城县：今浙江长兴县。
顾渚山：在长兴县西三十里。
白茅山悬脚岭：在长兴县渚顾山东面。
凤亭山：在长兴县西北四十里。伏翼阁、飞云寺、曲水寺，都是山里的寺院。
啄木岭：在长兴县北六十里，山中多啄木鸟。
常州：今江苏常州市一带。
义兴县：今江苏宜兴县。
君山：在宜兴县南二十里。
圈岭善权寺：善权，相传是尧时隐士。
宣州、杭州、睦州、歙州：宣州，今安徽宣城、当涂一带；杭州，今浙江杭州、余杭一带；睦州，今浙江建德、桐庐、淳安一带；歙州，今安徽歙县、祁门一带。
雅山：又称鸦山、鸭山、丫山。在今安徽省宁国县北。
上睦、临睦：太平县二乡名。
于潜县：现已并入临安县。
天目山：山脉横亘于浙江西、皖东南边境。
钱塘生天竺、灵隐二寺：钱塘县，今浙江杭州市，灵隐寺在市西灵隐山下。天竺寺分上、中、下三寺。下天竺寺在灵隐飞来峰。
润州：今江苏镇江、丹阳一带。
苏州：今江苏苏州、吴县一带。
江宁县傲山：江宁县在今南京市及江宁县。傲山在南京市郊。
长州县洞庭山：长洲县在今苏州一带。洞庭山是太湖中的小岛。
剑南：唐贞观十道之一。
彭州：今四川彭县一带。
九陇县、马鞍山至德寺、堋口：九陇县，今彭县。马鞍山，即今至德山，在鼓城西。堋口，在鼓城西。
锦州、蜀州：锦州，今四川绵阳、安县一带。蜀州，今四川崇庆、灌县一带。
龙安县、松岭关：龙安县，今四川安县。松岭关，在今龙安县西五十里。
西昌、昌明、神泉县、西山：西昌，在今四川安县东南花荄镇。昌明，在今四川江油县附近，神泉县，在安县南五十里。西山，岷山山脉之一部分。
青城县、丈人山：今四川灌县南四十里，因境内有青城山而得名。丈人山为青城山三十六峰之主峰。
邛州：今四川邛峡、大邑一带。
雅州、泸州：雅州今四川雅安一带。泸州，今四川泸州市及其周边。
百丈山、名山：百丈山，在今四川名山县东四十里。名山，在名山县北。
泸州县：今四川泸县。
眉州：今四川眉山、洪雅一带。
汉州：今四川广汉、德阳一带。
铁山、竹山：铁山，又名铁桶山，在四川丹陵县境内。竹山，即绵竹山，在四川绵竹县境内。
浙东：浙江东道节度使方镇的简称。节度使驻地浙江绍兴。
越州：今浙江绍兴、嵊县一带。
明州：今浙江宁波、奉化一带。
婺州：今浙江金华、兰溪一带。
鄮（mào）县：今浙江宁波市东南的东钱湖畔。
东白山：在今浙江东阳县巍山镇北。
台州：今浙江临海，天台一带。
始丰县：今浙江天台县。
赤城：山名。天台山十景之一。
黔中：唐开元十五道之一。
恩州、播州、费州、夷州：恩州，今贵州沿河一带。播州，今贵州遵义一带。费州，今贵州思南、德江一带。夷州：今贵州风冈、绥阳一带。
江西：江西团练观察使方镇的简称，观察使驻地在今江西南昌市。
鄂州、袁州、吉州：鄂州，今湖北武昌、黄石一带。袁州，今江西吉安、宁冈一带。
岭南：唐贞观十道之一。
福州、建州、韶州、象州：福州，今福建福州、甫田一带。建州，今福建建阳一带。韶州，今广东韶关、仁化一带。象州，今广西象州县一带。
方山：在福建福州市闽江南岸。', '山南地区的茶以峡州产的为最好，襄州、荆州产的次之，衡州产的差些，金州、梁州的又差一些。
淮南地区的茶，以光州产的为最好，义阳郡、舒州产的次之，寿州产的较差，蕲州、黄州产的又差一些。
浙西地区产的茶，以湖州产的为最好，常州产的次之，宣州、杭州、睦州、歙州产的差些，润州、苏州产的又差一些。
剑南地区的茶，以彭州产的为最好，绵州蜀州产的次之，邛州、雅州、泸州的差些，眉州、汉州又差一些。
浙东地区的茶，以越州产的为最好，明州、婺州产的次之，台州产的差些。
黔中产地是恩州、播州、费州、夷州。
江西产地是鄂州、袁州、吉州。
岭南产地是福州、建州、韶州、象州。
对于思、播、费、夷、鄂、袁、吉、福、建、韶、象这十一州所产的茶，还不大清楚，有时得到一些，品尝一下，觉得味道非常之好。', NULL, '', 'indent', 1522956151, '5ac606f49f545430011ef8a6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637060, '茶经 · 九之略', NULL, 2, 14, 0, 1, '陆羽', NULL, 13217, '584432e0c59e0d0056a3b0e9', '唐', 'wen', '文', '', '', '其造具，若方春禁火之时，于野寺山园丛手而掇，乃蒸，乃舂，乃以火干之，则又棨、朴、焙、贯、相、穿、育等七事皆废。其煮器，若松间石上可坐，则具列，废用槁薪鼎枥之属，则风炉、灰承、炭挝、火策、交床等废；若瞰泉临涧，则水方、涤方、漉水囊废。若五人已下，茶可末而精者，则罗废；若援藟跻岩，引縆入洞，于山口灸而末之，或纸包合贮，则碾、拂末等废；既瓢碗、䇲、札、熟盂、醝簋悉以一筥盛之，则都篮废。但城邑之中，王公之门，二十四器阙一则茶废矣！', '', '方春禁火之时：禁火，古时民间习俗。即在清明前一二日禁火三天，用冷食，叫“寒食节”。
援藟（lěi）跻（jī）岩：藟，藤蔓。《广雅》：“藟，藤也”。跻，登、升。《释文》：“跻，升也”。
縆（gēng）：绳索。', '可以不使用的造茶的器具是在寒食节时候。采茶后，只进行蒸、捣、烤干，所以锥刀、扑、焙、贯、相、穿、育等器具就没有什么用处。
可以不使用的煮茶的器具是在山林中，坐在林间的石头上，那么槁薪鼎枥这类工具就可以不用了，诸如风炉、灰承、炭挝、火策、交床等。
如果是在山泉旁取水饮茶，那么就可以不用水方、涤方、漉水囊。
如果总人数在五人以下，同时茶末可以磨得好点，就可以不用罗了。
如果是攀岩而上，在山洞里面饮茶，或者在洞口烤后磨好，用纸包包好，那么就不用碾和拂末了。
如果瓢、碗、䇲、扎、熟盂、醝簋这些器具都用筥来盛放，那么就可以不用都篮了。
但在城里或者是王公家，二十四种器具缺一种的话，那么整个饮茶的程序就不全了，自然就不必饮茶了。', NULL, '', 'indent', 1522956312, '5ac60796ee920a2bc7d33dee', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637061, '茶经 · 十之图', NULL, 6, 14, 0, 1, '陆羽', NULL, 13217, '584432e0c59e0d0056a3b0e9', '唐', 'wen', '文', '', '', '以绢素或四幅或六幅，分布写之，陈诸座隅，则茶之源、之具、之造、之器、之煮、之饮、之事、之出、之略，目击而存，于是《茶经》之始终备焉。', '', '', '用白绢四幅或六幅，把上述内容分别写出来，张挂在座位旁边。这样，茶的起源、采制工具、制茶方法、制茶用具、煮茶方法、饮茶方法、有关茶事的记载、产地以及茶具的省略方式等，看到了便随时都记载下来，于是茶经也就从此完备了。', NULL, '', 'indent', 1522956398, '5ac607ec9f54541c8b9b70ba', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637063, '贺进士王参元失火书', NULL, 2, 243, 0, 1, '柳宗元', NULL, 10055, '57b9042f7db2a2005426b940', '唐', 'wen', '文', 'https://baike.baidu.com/item/%E8%B4%BA%E8%BF%9B%E5%A3%AB%E7%8E%8B%E5%8F%82%E5%85%83%E5%A4%B1%E7%81%AB%E4%B9%A6/6187004?fr=aladdin', '', '得杨八书，知足下遇火灾，家无馀储。仆始闻而骇，中而疑，终乃大喜。盖将吊而更以贺也？道远言略，犹未能究知其状，若果荡焉泯焉而悉无有，乃吾所以尤贺者也。
足下勤奉养，宁朝夕，惟恬安无事是望。乃今有焚炀赫烈之虞，以震骇左右，而脂膏滫瀡之具，或以不给。吾是以始而骇也。
凡人之言，皆曰盈虚倚伏，去来之不可常。或将大有为也，乃始厄困震悸，于是有水火之孽，有群小之愠，劳苦变动，而后能光明，古之人皆然。斯道辽阔诞漫，虽圣人不能以是必信，是故中而疑也。
以足下读古人书，为文章，善小学，其为多能若是，而进不能出群士之上，以取显贵者，无他故焉，京城人多言足下家有积货，士之好廉名者，皆畏忌，不敢道足下之善，独自得之，心蓄之，衔忍而不出诸口。以公道之难明，而世之多嫌也。一出口，则嗤嗤者以为得重赂。
仆自贞元十五年见足下之文章，蓄之者盖六七年未尝言。是仆私一身而负公道久矣，非特负足下也。及为御史、尚书郎，自以幸为天子近臣，得奋其舌，思以发明足下之郁塞。然时称道于行列，犹有顾视而窃笑者。仆良恨修己之不亮，素誉之不立，而为世嫌之所加，常与孟几道言而痛之。乃今幸为天火之所涤荡，凡众之疑虑，举为灰埃。黔其庐，赭其垣，以示其无有。而足下之才能乃可显白而不污。其实出矣，是祝融、回禄之相吾子也。则仆与几道十年之相知，不若兹火一夕之为足下誉也。宥而彰之，使夫蓄于心者，咸得开其喙，发策决科者，授子而不栗，虽欲如向之蓄缩受侮，其可得乎？于兹吾有望乎尔，是以终乃大喜也。
古者列国有灾，同位者皆相吊；许不吊灾，君子恶之。今吾之所陈若是，有以异乎古，故将吊而更以贺也。
颜、曾之养，其为乐也大矣，又何阙焉？足下前要仆文章古书，极不忘，候得数十篇乃并往耳。吴二十一武陵来，言足下为《醉赋》及《对问》，大善，可寄一本。仆近亦好作文，与在京城时颇异。思与足下辈言之，桎梏甚固，未可得也。因人南来，致书访死生。不悉。宗元白。', '《贺进士王参元失火书》是唐代散文家柳宗元写给好朋友王参元的一封信。这封信第一段写自己从杨八那里得知了王参元家里失火的消息。中间五段分别说明“始而骇”、“中而疑”、“终乃大喜”三层意思，着意阐述自己所以致书祝贺朋友家失火这个违反常理的奇论的原因，层层递进。最后一段写自己想念王参元，传递了对友人的深切关爱之情，更包含着对友人前程的无限关怀之意。这封信纵横转换，曲折抑扬，淋漓酣畅，入情入理。', '杨八：名敬之，在杨族中排行第八。柳宗元的亲戚，王参元的好朋友。
仆：自谦之词，柳宗元自指。
骇：惊怕。
盖将吊而更以贺也：意谓何不把慰问更改为祝贺呢？盖，通“盍”，“何不”的意思。
荡焉泯焉：荡然无存。
炀（yàng）：焚烧。
赫烈：火势猛烈的样子。
虞：忧虑。
滫（xiǔ）：淘米水。
瀡（suǐ）：古时把使菜肴柔滑的作料叫“滑”，齐国人称之为“瀡”。
倚伏：出自《老子》“祸兮福之所倚，福兮祸之所伏”。意为祸是福依托之所，福又是祸隐藏之所，祸福可以互相转化。
小学：旧时对文字学、音韵学、训诂学的总称。
蓄：藏。
衔忍：含在口里忍住不说。
嫌：怀疑，猜忌。
奋其舌：这里指对皇帝劝谏、上疏等。
孟几道：孟简，字几道，擅长写诗，尚节好义，是柳宗元的好朋友。
涤荡：洗涤，清除。这里是焚烧殆尽的意思。
黔其庐：烧焦了房屋。黔，黑色。
赭（zhě）其垣：烧红了墙壁。赭，红色，这里做动词用。
其实出矣：您的真实情况显露出来了。
祝融、回禄：都是传说中的火神名。
宥（yòu）：宽恕。
彰：明白。
喙：鸟兽的嘴，这里借指人的嘴。
于兹：从此。
尔：您。
许不吊灾，君子恶之：据《左传》记载，鲁昭公十八年（前524年），宋、卫、陈、郑四国发生火灾，许国没有去慰问，当时的有识之士据此推测许国将要灭亡。
异乎古：与古代有些不同。
古书：具有古人风格的书法。
吴二十一武陵：即吴武陵，排行二十一，柳宗元的学生、朋友。
桎（zhì）梏（gù）甚固，未可得也：意谓束缚思想的东西甚为牢固，文章未必有可取之处。桎梏，本指刑具，这里是束缚的意思。这两句是作者的自谦词。
不悉：意谓不再一一具说了。古时书信中的套语。', '得到杨八的信，知道您遭遇火灾，家里没有一点积蓄了。我开始听到很吃惊，接着感到怀疑，最后竟然非常高兴，于是我准备慰问您，现在却改变了，要向您道喜。由于相隔很远，信里的话又很简单，我仍然不能彻底了解您家的情形，假如果真是像大水冲过一样毁灭丢失，都没有了，我就更要因此向您道喜。
您一向小心地奉养双亲，使父母早晚享受天伦之乐，只希望全家平安无事。现在竟然有一场大火肆虐的灾祸，使您震惊不安，并且调和饮食的工具，或许因此不能供应：我因此刚一听到这消息就大吃一惊。
一般人都说，盛衰祸福相互依存，得和失不会一尘不变，也许一个人将要大有作为，那么开始受到种种困苦惊吓，因此有火的灾害，有小人们的怨恨，身心经受各种劳苦颠沛的磨炼，然后能有光明坦荡的前途。古代的仁人志士都是这样。我认为这条道理太迂远，大而无当，即使古代的圣人也不认为事情确实那样发展：这是我后来疑惑的原因。
像您这样遍读古人的书，能写文章，对文字学、音韵学、训诂学三者很有研究，具备如此众多的才学，而在仕进上却不能高出于一般的士人，达到显赫的地位，这实在是没有别的原因。京城中有不少人说您府上广积财富，那些爱好廉洁名声的士大夫，都害怕、忌讳，不敢称赞您的优点，只是一个人自己知道，放在心里，长期含忍，不能把它说出口。因为公理难以伸张，世情又多猜忌。一旦有人说出称赞您的话，那班以讽刺攻击为能事的小人就以为那人必定得到您的厚礼了。
我从贞元十五年（799年），看见您写的文章，放在心里有六七年，从来没说过，这是我只顾自己而对不起公道很久了，不单对不起您呀。等到我做了御史尚书郎，自已认为有幸而做了皇上身边的臣子，可以放胆说话，想趁此彰明您受阻滞的情况。但是，我有时在同行面前称赞您时，仍然有相视而暗笑我的。我实在是痛恨自己的品德修养还不足以使人亮察，素来清白的名声还未能确立，因而遭到世人的猜忌。我经常与友人盂几道谈起这件事，并对此痛心不已。于是现在正好您的家财被天火烧得精光，众人的疑虑也一起化为灰尘。烧黑了您的屋宇，烧红了您的断垣残壁，从而表示您一无所有；而您的才能，才可以表白清楚，再不被谣言所污染。您的真相显露了。这真是祝融、回禄在帮助您啊！这样看来，我和几道十年来对您的了解，还比不上这次火灾一个晚上给您造成的好名誉。都会原谅并表扬你，可以公开宣扬你的才能了，使得那些有话藏在心里的人，都能毫无顾忌地为您说话了；主持考试的，可以大胆录取您，不再怕别人说闲话。现在，我就是想要像过去那样避免嫌疑，被人嘲笑，可能吗？从此，我对您寄予了很大希望，因此，最后我非常高兴。
在古代，哪一个诸侯国有灾祸，其他诸侯国都来慰问。有一次许国不慰问宋，卫，陈，郑的灾祸，君子都憎恶之。现在，我说明的事理是这样的，和古代的有不同，本来准备慰问您，却变得要向您道喜。
颜渊和曾参供养父母，使父母感到愉快的方面远远超过一般人，物质上的一点欠缺又有什么值得不满意的呢？您先前要我的文章古书，我始终没有忘记，只是想等到有几十篇后再一起带给您而已。吴二十一来我这里，说您写有《醉赋》及《对问》，非常好，可要寄给我一本。我近来也喜欢写文章，与在京都时很不一样，想与您这样的人说说话，可受到很严的限制，无法实现，趁着有人南来，给您一封信打探一下您的生活情况，不能详尽。宗元向您问好。', NULL, '清·林云铭《古文析义》：“是书以闻失火，改吊为贺，立论固奇。纵横转换，抑扬尽致，令罹祸者破涕为笑，则其奇处耳。”
清·张伯行《唐宋八大家文钞》：“奇思隽语，出于意外。”
清·过珙《古文评注》：“失火而贺，最是奇情恣笔。”', 'indent', 1523029065, '5ac723c6ac502e0063d48646', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637119, '地藏经 · 如来赞叹品第六', NULL, 10, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%A6%82%E6%9D%A5%E8%B5%9E%E5%8F%B9%E5%93%81%E7%AC%AC%E5%85%AD/5784396?fr=aladdin', '', '尔时世尊举身放大光明，遍照百千万亿恒河沙等诸佛世界。出大音声，普告诸佛世界一切诸菩萨摩诃萨，及天、龙、鬼、神、人、非人等。听吾今日称扬赞叹地藏菩萨摩诃萨，于十方世界，现大不可思议威神慈悲之力，救护一切罪苦之事。吾灭度后，汝等诸菩萨大士，及天龙鬼神等，广作方便，卫护是经，令一切众生证涅槃乐。
说是语已，会中有一菩萨，名曰普广，合掌恭敬而白佛言：今见世尊赞叹地藏菩萨，有如是不可思议大威神德，唯愿世尊为未来世末法众生，宣说地藏菩萨利益人天因果等事，使诸天龙八部，及未来世众生，顶受佛语。
尔时世尊告普广菩萨及四众等：谛听谛听！吾当为汝略说地藏菩萨利益人天福德之事。
普广白言：唯然！世尊，愿乐欲闻。
佛告普广菩萨：未来世中，若有善男子、善女人，闻是地藏菩萨摩诃萨名者，或合掌者、赞叹者、作礼者、恋慕者，是人超越三十劫罪。
普广，若有善男子、善女人，或彩画形像，或土石胶漆，金银铜铁、作此菩萨，一瞻一礼者，是人百返生于三十三天，永不堕于恶道。假如天福尽故，下生人间，犹为国王，不失大利。
若有女人，厌女人身，尽心供养地藏菩萨画像，及土石胶漆铜铁等像，如是日日不退，常以华香、饮食、衣服、缯彩、幢旛、钱、宝物等供养。是善女人，尽此一报女身，百千万劫，更不生有女人世界，何况复受。除非慈愿力故，要受女身，度脱众生，承斯供养地藏力故，及功德力，百千万劫不受女身。
复次普广：若有女人，厌是丑陋，多疾病者，但于地藏像前，志心瞻礼，食顷之间。是人千万劫中，所受生身，相貌圆满。是丑陋女人，如不厌女身，即百千万亿生中，常为王女，乃及王妃，宰辅大姓，大长者女，端正受生，诸相圆满。由志心故，瞻礼地藏菩萨，获福如是。
复次普广：若有善男子、善女人，能对菩萨像前，作诸伎乐，及歌咏赞叹，香华供养，乃至劝于一人多人。如是等辈，现在世中及未来世，常得百千鬼神日夜卫护，不令恶事辄闻其耳，何况亲受诸横。
复次普广：未来世中，若有恶人及恶神恶鬼，见有善男子、善女人，归敬供养赞叹瞻礼地藏菩萨形像，或妄生讥毁，谤无功德及利益事，或露齿笑，或背面非，或劝人共非，或一人非，或多人非，乃至一念生讥毁者。如是之人，贤劫千佛灭度，讥毁之报，尚在阿鼻地狱受极重罪。过是劫已，方受饿鬼。又经千劫，复受畜生。又经千劫，方得人身。纵受人身，贫穷下贱，诸根不具，多被恶业来结其心。不久之间，复堕恶道。是故普广，讥毁他人供养，尚获此报，何况别生恶见毁灭。
复次普广：若未来世，有男子女人，久处床枕，求生求死，了不可得。或夜梦恶鬼，乃及家亲、或游险道、或多魇寐、共鬼神游。日月岁深，转复尪瘵，眠中叫苦，惨凄不乐者。此皆是业道论对，未定轻重，或难舍寿、或不得愈，男女俗眼，不辨是事。
但当对诸佛菩萨像前，高声转读此经一遍。或取病人可爱之物，或衣服、宝贝，庄园、舍宅，对病人前，高声唱言：我某甲等，为是病人对经像前舍诸等物，或供养经像、或造佛菩萨形像、或造塔寺、或燃油灯、或施常住。如是三白病人，遣令闻知。
假令诸识分散，至气尽者，乃至一日、二日、三日、四日至七日以来。但高声白，高声读经。是人命终之后。宿殃重罪，至于五无间罪，永得解脱，所受生处，常知宿命。何况善男子善女人自书此经或教人书、或自塑画菩萨形像乃至教人塑画。所受果报，必获大利。
是故普广，若见有人读诵是经，乃至一念赞叹是经，或恭敬者。汝须百千方便，劝是等人，勤心莫退，能得未来、现在千万亿不可思议功德。
复次普广：若未来世诸众生等，或梦或寐，见诸鬼神乃及诸形，或悲、或啼、或愁、或叹、或恐、或怖。此皆是一生十生百生千生过去父母、男女弟妹、夫妻眷属，在于恶趣，未得出离，无处希望福力救拔，当告宿世骨肉，使作方便，愿离恶道。
普广，汝以神力，遣是眷属，令对诸佛菩萨像前，志心自读此经，或请人读，其数三遍或七遍。如是恶道眷属，经声毕是遍数，当得解脱，乃至梦寐之中，永不复见。
复次普广：若未来世，有诸下贱等人，或奴或婢，乃至诸不自由之人，觉知宿业，要忏悔者。志心瞻礼地藏菩萨形像，乃至一七日中，念菩萨名，可满万遍。如是等人，尽此报后，千万生中，常生尊贵，更不经三恶道苦。
复次普广：若未来世中，阎浮提内，刹利、婆罗门、长者、居士、一切人等，及异姓种族，有新产者，或男或女，七日之中，早与读诵此不可思议经典，更为念菩萨名，可满万遍。是新生子，或男或女，宿有殃报，便得解脱，安乐易养，寿命增长。若是承福生者，转增安乐，及与寿命。
复次普广：若未来世众生，于月一日、八日、十四日、十五日、十八日、二十三、二十四、二十八、二十九日、乃至三十日，是诸日等，诸罪结集，定其轻重。南阎浮提众生，举止动念，无不是业，无不是罪，何况恣情杀害、窃盗、邪淫、妄语、百千罪状。能于是十斋日，对佛菩萨诸贤圣像前，读是经一遍，东西南北百由旬内，无诸灾难。
当此居家，若长若幼，现在未来百千岁中，永离恶趣。能于十斋日每转一遍，现世令此居家无诸横病，衣食丰溢。是故普广，当知地藏菩萨有如是等不可说百千万亿大威神力，利益之事。
阎浮众生，于此大士有大因缘。是诸众生，闻菩萨名，见菩萨像，乃至闻是经三字五字，或一偈一句者，现在殊妙安乐，未来之世，百千万生，常得端正，生尊贵家。
尔时普广菩萨闻佛如来称扬赞叹地藏菩萨已，胡跪合掌复白佛言：世尊，我久知是大士有如此不可思议神力，及大誓愿力，为未来众生遣知利益，故问如来，唯然顶受。
世尊，当何名此经，使我云何流布？
佛告普广：此经有三名：一名地藏本愿，亦名地藏本行，亦名地藏本誓力经。缘此菩萨，久远劫来，发大重愿，利益众生，是故汝等，依愿流布。
普广闻已，合掌恭敬作礼而退。', '《如来赞叹品第六》出自佛教经典《地藏经》。在这一品中，世尊称扬赞叹地藏菩萨以大不可思议威神慈悲之力，救护一切罪苦众生，利益人天的福德之事。', '人非人：人与非人之并称。非人，指人类以外的某类众生。佛典当中对“非人”的解释，有时指天、龙、阿修罗等八部众；有时包括地狱、饿鬼等众生；有时专指鬼神所幻化而成的“变化人”。
灭度：涅槃之别称。所谓灭度者，灭生死之因果，度烦恼之瀑流，是灭即度也。
普广：谓此菩萨智满法界为普，行满虚空为广，故名普广。普者，从心发智，智弥法界也；广者，以智导行，行满虚空也。乃以智慧、修行两者自利利他，成就佛道者也。
合掌：合左右掌之十指以表吾心专一之敬礼法。又，名合二边令归于中道之义也。密教有金刚合掌，乃合掌而交叉手指也，《观无量寿经》云：“合掌叉手，赞叹诸佛”。
福德：行善所得之福利名福德，亦称一切之善行为福德。《无量寿经》云：“福德自然”。福者，利也；德者，得也，修种种善行而有所得，“善满曰得”。儒家称“五福”者，乃福寿、富贵、康宁、好德、考终也。常称“五福临门”者，此也。儒家称“五德”者，《论语》云：“子贡曰，夫子温、良、恭、俭、让”。人具五福五德者，可为极圆极善之上人也。
恋慕：恋者，依恋，有如小儿依恋父母；慕者，仰慕，如常人对圣贤有羡慕、恭敬、思齐（向他学习）之心。总表地藏菩萨德行高超，神力无边，智慧无尽，悲心无穷，令一切众生闻名而思念，恭敬、亲近、尊重、赞叹之意。
缯：缯，即彩缯。缯，是丝织品一类的织品，《汉书·灌婴传》：“灌婴，睢阳贩缯者也”。颜师古注：“缯者，帛之总名”。“”为彩之异体，彩缯乃带色彩之帛也。用带色彩的丝织品做成幢幡以为佛事装饰也，见下注。
幢幡：梵语驮缚若，为幢；梵语波吒迦，为幡。幢，音床，竿柱高秀，头安宝珠，以种种彩帛装饰者。幡，长帛下垂，为表佛、世尊威德所作之庄严具。幡具无量佛德，以顶触之，则生受轮王之灌顶，终受佛位之灌顶；故幡又名灌顶。
伎乐：伎，音寄，技艺也，伎乐者，有高能技艺之音乐。这里指众生以种种高雅、美妙悦耳之音乐供养地藏菩萨也。
诸横：横者，横死，即非自然死亡之暴死也，常称九横死：一、得病无医：无医生及医药之治疗而死者；二、王法诛戮：犯王法而被杀者；三、非人夺精气：耽于荒乐而不修身，为鬼怪乘隙夺其精气而死者；四、火焚：被火烧致死；五、水溺：被水淹死；六、恶兽啖：在于荒山野林而被猛兽所食；七、堕崖：由悬崖绝壁堕下而致死；八、毒药咒咀：为毒药或恶咒所咀咒而死；九、饥渴死：由饥渴所困而死。现代复有车祸、舟祸、飞机失事等等横死也。
贤劫千佛：贤劫：为佛典中所述之宇宙循环过程中的一阶段。指过去、现在、未来三阶段中的“现在住劫”而言。依佛典所载，现在大劫有成、住、异、灭四劫，其中住劫有千佛等贤圣出世救度众生，故称贤劫。住劫有二十增减，其前八增减中为佛之出世，于第九减劫始有佛，名拘留孙，是名千佛之第一，次为拘那含牟尼佛，次为迦叶佛，次即今之释迦牟尼佛。自此至第十增减之减劫有弥勒出世。次于第十增减劫中有佛子佛等九百九十四佛。次于第二增减劫之增劫有楼至佛出世，合计一千佛。
魇（yǎn）寐：即夜梦不安，睡梦中受到惊吓而喊叫，或觉得有东西压在身上，不能动弹。
尫瘵（wānɡzhài）：虺，胸背弯曲或瘦弱；瘵，是五痨七伤等病。
宿殃：“宿”，指过去世，有时也指今世中过去的时日；“殃”，祸，罪也。宿殃，指过去所造的恶业形成的重罪，在现在或将来须得遭报也。
五无间罪：五种重大的罪过，又称五逆或五逆罪。即杀父、杀母、杀阿罗汉、伤佛身体使流血，破坏僧团的团结等。犯了这些罪，要堕入无间地狱。
斋：梵文Uposadha，清净之意，谓忏悔罪障，或谓谨言慎行、斋戒沐浴。佛教未创之前，印度早已使用此语，佛教沿用后逐渐衍生成各种不同意义，如过午不食。斋食即正午以前所做的食事。
偈（jì）：梵文Gatha，音译为伽陀、偈他，即、颂。在佛教经、律、论中，通常会使用诗句、韵文的形式来表达思想，通常以四句为一偈。
胡跪：胡人之跪拜，又作胡跽。盖古时印度、西域地方总称为胡，故胡跪乃意味一般胡人跪拜之敬仪。长跪、互跪亦通称胡跪，而以经中所说右膝着地者为正仪。
本愿：即佛及菩萨于过去世未成佛果以前为救度众生所发起之誓愿。于因位发愿至今日得其果，故对果位而称本愿。
本行：指菩萨成佛以前在因位时的行迹，也就是成佛之因的根本行法。行，即对于知解言说之实地践行。本誓力：即本愿与本行两者的共同作用。有愿而无行，其愿要落空，无所成就。有行而无愿，其行是盲行，没有结果。所以愿必赅行，行必赅愿。誓力，即是愿行。', '这时，世尊全身放射出巨大的光辉，遍照无量百千万亿恒河沙数的佛世界，并以大音声普告诸佛世界中的一切诸菩萨摩诃萨，以及天众、龙众、鬼神等众和人类、非人类等一切众生：“在座大众，你们都听到了我刚才称扬赞叹地藏菩萨摩诃萨能在十方世界，以不可思议的慈悲威神之力，为了满足历劫所发的种种宏誓大愿、救护十方一切罪苦众生的度生事业。我灭度后，你们这些菩萨大士以及天、龙、鬼神等大众，应当以种种方便、种种善巧来卫护这部经，使一切众生能通过这部经的教导，如法修行，而证得永断生死的涅槃之乐。”佛说完这些话之后，忉利天宫大会上有一位菩萨，名字叫普广，从座位上起身，恭敬合掌对佛说：“世尊，今天听到世尊称扬赞叹地藏菩萨有种种不可思议的大威神、大福德、大神通之力。唯愿世尊为后世的末法众生宣讲一下地藏菩萨利益人天的因果之事，使天龙八部和未来世的一切众生能明了因果，领受佛的言教，依照佛法来修行。”这时，佛告诉普广菩萨及在座的人、天、龙、鬼等与会四众说：“你们仔细倾听，我现在就为你们简略地说一说地藏菩萨利益人天，使他们都得到种种福德的事迹。”普广菩萨欢喜地说：“请世尊讲说，我们大家都很想听到地藏菩萨利益人天的因果等事。”佛就告诉普广菩萨说：“在未来世中，倘若有善男子、善女人有缘听到地藏菩萨名号，继而能以恭敬心、欢喜心、虔诚心，合掌、赞叹、礼拜、仰慕地藏菩萨，以此恭敬地藏菩萨的功德，就可以超脱三十大劫的生死重罪。”“普广，若有善男子、善女人，或是自画，或是请人画，彩绘地藏菩萨的形象；或者用土、石、胶、漆或金、银、铜、铁等材料雕塑地藏菩萨的形象，恭敬瞻礼，哪怕仅有一瞻一礼，以此塑画地藏菩萨，瞻仰礼拜的功德，就可以一百次托生于三十三天享受天福，永远不会堕落到三恶道中去。假如天福享尽之时，下生到人间来的话，还可以在人间做国王，不会失去人中的利益福报。”“如果有女人，厌恶自己的女人之身，只要至心诚意地用种种庄严供具来供养菩萨的画像或土石、胶漆、铜铁铸成的塑像，从初发心到临命终，天天如此，一天不缺地用鲜花、烧香、饮食、衣服、丝绸、幢幡、钱财、珍宝等供养地藏菩萨。那么在舍去了这一世的女人之身以后，百千万劫都不会投生到有女人的世界里去，更不用说自己再受女人之身了。除非发下利益众生的大愿，以慈悲心去救度那些受苦受罪的女人们，自己愿意化作女人之身去度脱众生。”“另外，普广，倘若有的女人，由于宿世的业障，今世生得既丑陋又疾病缠身的，只要在地藏菩萨像前至心诚意瞻仰礼拜，哪怕只有一顿饭的工夫，以此功德，她也会在以后的百千万劫当中所受的生身相貌圆满，令人欢喜爱敬。如果她愿意在未来世中继续做女人的话，也可以借此礼敬功德，在未来的百千万亿生中，托生于帝王之家做公主或王妃，或者投生为宰相、官员等大户人家的千金小姐，从一生下来便健康有福，美貌端正。这都是由于以志诚心瞻仰礼拜地藏菩萨的功德才获得的福报。”“还有，普广，倘若有善男子、善女人，能够在地藏菩萨像前，或是亲自，或是请人，演奏种种高雅、美妙的音乐，以歌唱、朗诵来赞叹地藏菩萨的功德，以种种妙好的香华等供养菩萨，不仅自己这么做，还劝他人乃至多人也这么做。像这样的人，在现世及未来世中，常常会得到百千的鬼神日夜保护，不让任何恶事来干扰他，甚至连恶事之名也无法听到，更不用说亲自遭受种种苦楚与横祸了。”“另外，普广，在未来世中，倘若有恶人或恶神、恶鬼，看见善男子、善女人皈依、供养、赞叹、瞻礼地藏菩萨的形象，不随喜赞叹，反而讥笑毁谤，说这是没有任何功德与利益的。要么当面哈哈大笑，要么在背后冷嘲热讽，要么挑唆旁人或许多人一起诽谤。像这样的恶人、恶神、恶鬼，哪怕只是生起一念讥毁之心的，直到贤劫中最后的第一千位佛灭度了，其因讥毁他人供养地藏菩萨功德所生的罪报，还会令他在阿鼻地狱里受极重的罪。过了地狱罪报的劫数之后，方能从地狱中出，转到饿鬼道中受苦；在饿鬼道中经过一千大劫之后，转到畜生道中受苦；在畜生道中经过一千大劫之后，方才得到人身，即使得到人身，也是个贫穷下贱、六根残缺，一辈子经常碰到恶报，怨家、疾病、劳苦、贫穷追随一生。不久之后，由于恶业结集，又会再次堕落到恶道中去，轮回不息。因此，普广你看，讥笑毁谤他人供养地藏菩萨的罪业，尚且要得到这么重的报应，更何况自己产生别的种种阴险邪恶的念头，去诽谤损毁佛法呢。”“还有，普广，在将来世中，若有男子或女人，长时间地卧病在床，被折磨得求生不得，求死不能。或常常在夜里梦见恶鬼；或见到已故的亲人；或于梦中在危险的地方奔波；或是梦中被恶鬼扑身，吓得惊醒过来；或是被恶鬼缠缚，与之同行，这样日复一日，年复一年，年久岁深，病入膏肓，骨瘦如柴，在梦中叫苦叫痛，悲惨至极。这都是因为之前造了种种恶业，到了临欲命终之时，各种业力相互较量，而未来的去向悬而未决，所以长期卧病在床，一时难以命绝，其病又久久不得痊愈。这其中的缘由，以世间男女的俗眼，又如何能够明辨通晓呢？遇到这种情况，其家人应当赶紧在诸佛菩萨的像前，恭敬至诚地高声朗读此经一遍。同时，拿出病人最喜欢的东西，如衣服、宝贝，或是舍出自己部分的庄园、房舍，在病人面前大声宣布：我某某人，替这位病人，在佛经、佛像前诚心做此布施，或是用这些钱塑画佛菩萨形象，或是用这些钱造塔、造寺，或是用这些钱来燃灯供佛，或是用这些钱供养寺院、三宝常住。像这样在病人面前再三陈说，一定要让他清醒地意识到有人在替他做这样的功德。倘若病人已经神志昏迷失去知觉，或者已经命终气绝，那么，在一天、两天、三天、四天乃至七天之内，仍然要这样不断地高声念经，高声向病人表白。病人在命终之后，所有过去所犯下的祸殃与重罪，甚至于应堕落无间地狱的深重罪业，也能够得到永远的解脱。并且在以后所生的各世里，常常还知道过去世因果报应的情形。如果善男子、善女人能于身强体健之时，自己抄写或请别人代为抄写此经；自己塑画或是请人代为塑画地藏菩萨形象，必定能获善果，其功德利益是很大的。因此，普广，倘若见到有人读诵这部经，哪怕只是生起一念恭敬赞叹此经之心，你一定要以百千种方便来劝说这些人，千万不要退失这宝贵的初发心，而是应当勤勤恳恳、持之以恒地恭敬赞叹、受持、读诵这部经，这样做，可以得到在现在和未来千万亿不可思议的功德！”“还有，普广，倘若在未来世里有些众生，在梦中见到种种鬼神及其他种种形状的众生，有的悲伤，有的啼哭，有的忧愁，有的恐惧，这些都是他们以前一生、十生、百生、千生中的父母、兄弟、姐妹、夫妻、亲戚、朋友等堕落在恶趣中得不到解脱，希望这些众生，能做种种功德来超度他们。普广，你应当以神力方便，劝导这些众生做种种功德以使过去的亲人能够脱离恶道。恭敬地在佛菩萨像前，志诚恳切地读诵，或请人代读这部不可思议的经典，三遍或七遍。果真能这么做的话，那些身处恶道当中受苦渴望救拔的眷属，等到上述遍数的经文读诵完毕之后，当即可以得到解脱，在今后的梦里也再不会遇见了。”“另外，普广，倘若在将来世中，有些人身处下贱，或当男仆，或当女婢，以及因各种原因失去自由的人，觉悟到这种痛苦来自于过去世所造的恶业。想要诚心忏悔时，可以恭敬瞻礼地藏菩萨的形象，在一天到七天之中，每日称念地藏菩萨名号满一万遍。果真能这么做的话，他们在结束了这一世的报身寿命之后，未来千万生中，都能够投生到尊贵的家庭里，再不会到三恶道里去受苦。”“再有，普广，在未来世中阎浮提内，刹帝利、婆罗门、长者、居士、一切人等，还是其他异姓的种族，如果有新生儿降生，无论是男是女，在生后的头一个七天中，应当尽早为他（或她）读诵这部不可思议的经典，同时称念地藏菩萨的名号满一万遍。那么，这新生的男婴或女婴，倘若过去世有罪报的话，便可借此功德得以解脱，使他们在成长过程中健康安乐，容易养育，寿命增长。倘若这孩子本来就是有福之人，那么，借此功德，其寿命与福报也能大大地增长。”魔子忏悔“还有，普广，倘若未来世的众生在每月的十斋日，即初一、初八、十四、十五、十八、二十三、二十四、二十八、二十九日及三十日，都应当斋戒为善。因为这几个日子是各路神祇对阎浮提众生所犯的一切罪业清算定罪的时间。南阎浮提众生，举心动念，所作所为，可以说没有一件不是业、没有一件不是罪的，更何况那些不信因果的众生随心所欲地造下杀生、偷盗、邪淫、妄语、两舌、恶口等百千罪业。倘若能在这十斋日里，对诸佛菩萨或罗汉、辟支佛等贤圣像前读诵一遍地藏经，那么，居家东西南北一百由旬的范围内，都将没有灾难，家庭成员无论男女老少，在未来的百千年中永离种种恶道之苦。若能在这十斋日里每天念一遍地藏经，在现世，可以使家人远离种种横病，衣食丰盈有余。”“所以，普广，你现在应当知道了地藏菩萨有百千万亿威神方便之力来利益众生。阎浮提的众生，同这位大菩萨有很深的因缘，这些众生，听到地藏菩萨的名号，见到地藏菩萨的形象，哪怕能听到这部经的三字、五字，或一句、一偈的话，在现世可以得到殊胜微妙的安乐，在将来世的百千万生里，常能生得相貌端庄，投生于尊贵之家。”这时，普广菩萨在听了佛称扬赞叹地藏菩萨之后，右膝着地，恭敬合掌再对佛说：“世尊，我早就知道地藏菩萨有如此不可思议的神通誓愿之力，为了使未来世的众生能有机会知道地藏菩萨利益众生的种种功德利益之事，所以才请问如来的，当然会全心全意地信守奉行。世尊，应当如何称呼这部不可思议的经典？又应当如何让它得到更广泛的流通与传播呢？”佛告诉普广菩萨说：“这部经有三个名称，可以叫做“地藏本愿”，也可以叫做“地藏本行”，还可以叫做“地藏本誓力经”。因为这位菩萨从久远的无量劫以来，一直发种种大誓愿来利益众生，因此你们应当依据地藏菩萨不可思议的大愿去弘扬、流通这部经。”普广菩萨听了以后，恭敬合掌，向佛顶礼之后，退回到自己的座位去了。', NULL, '', 'indent', 1523465470, '5acdcc4317d00900318c1675', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637120, '地藏经 · 利益存亡品第七', NULL, 5, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%88%A9%E7%9B%8A%E5%AD%98%E4%BA%A1%E5%93%81%E7%AC%AC%E4%B8%83/5251042?fr=aladdin', '', '尔时地藏菩萨摩诃萨白佛言：世尊，我观是阎浮众生，举心动念，无非是罪。脱获善利，多退初心。若遇恶缘，念念增益。是等辈人，如履泥涂，负于重石，渐困渐重，足步深邃。若得遇知识，替与减负，或全与负。是知识有大力故，复相扶助，劝令牢脚。若达平地，须省恶路，无再经历。
世尊，习恶众生，从纤毫间，便至无量。是诸众生有如此习，临命终时，父母眷属，宜为设福，以资前路。或悬旛盖及燃油灯。或转读尊经、或供养佛像及诸圣像，乃至念佛菩萨，及辟支佛名字，一名一号，历临终人耳根，或闻在本识。是诸众生所造恶业，计其感果，必堕恶趣，缘是眷属为临终人修此圣因，如是众罪，悉皆消灭。
若能更为身死之后，七七日内，广造众善。能使是诸众生永离恶趣，得生人天，受胜妙乐，现在眷属，利益无量。
是故我今对佛世尊，及天龙八部人非人等，劝于阎浮提众生临终之日，慎勿杀害，及造恶缘，拜祭鬼神，求诸魍魉。
何以故？尔所杀害乃至拜祭，无纤毫之力，利益亡人，但结罪缘，转增深重。假使来世或现在生，得获圣分，生人天中。缘是临终被诸眷属造是恶因，亦令是命终人殃累对辩，晚生善处。何况临命终人，在生未曾有少善根，各据本业，自受恶趣，何忍眷属更为增业。
譬如有人从远地来，绝粮三日，所负担物，强过百斤，忽遇邻人，更附少物，以是之故，转复困重。
世尊，我观阎浮众生，但能于诸佛教中，乃至善事，一毛一渧，一沙一尘，如是利益，悉皆自得。
说是语时，会中有一长者，名曰大辩，是长者久证无生，化度十方，现长者身，合掌恭敬，问地藏菩萨言：大士，是南阎浮提众生，命终之后，小大眷属，为修功德，乃至设斋，造众善因，是命终人，得大利益及解脱不？
地藏答言：长者，我今为未来现在一切众生，承佛威力，略说是事。长者，未来现在诸众生等，临命终日，得闻一佛名、一菩萨名、一辟支佛名，不问有罪无罪，悉得解脱。若有男子女人，在生不修善因多造众罪。命终之后，眷属小大，为造福利一切圣事，七分之中而乃获一，六分功德，生者自利。以是之故，未来现在善男女等，闻健自修，分分己获。无常大鬼，不期而到，冥冥游神，未知罪福。七七日内，如痴如聋，或在诸司辩论业果。审定之后，据业受生。未测之间，千万愁苦，何况堕于诸恶趣等。
是命终人，未得受生，在七七日内，念念之间，望诸骨肉眷属，与造福力救拔。过是日后，随业受报。若是罪人，动经千百岁中，无解脱日。若是五无间罪，堕大地狱，千劫万劫，永受众苦。
复次长者：如是罪业众生，命终之后，眷属骨肉，为修营斋，资助业道未斋食竟，及营斋之次，米泔菜叶，不弃于地，乃至诸食未献佛僧，勿得先食。如有违食，及不精勤，是命终人，了不得力。如精勤护净奉献佛僧，是命终人，七分获一。是故长者，阎浮众生，若能为其父母乃至眷属，命终之后，设斋供养，志心勤恳。如是之人，存亡获利。
说是语时，忉利天宫，有千万亿那由他阎浮鬼神，悉发无量菩提之心，大辩长者作礼而退。', '《利益存亡品第七》出自佛教经典《地藏经》。在这一品中，地藏菩萨普劝众生修善，特别是临终之际，父母眷属，宜为设福。', '脱获：脱，倘或，或许之意，脱获者，倘若获得，偶然侥幸获得之意。此意为普通众生即使在做好事的情况下，也是不明因果，碰巧做上，故不免又为恶也。
念念：即刹那，意谓极其短暂的时间。经典中常以“念念”一词，形容现象界生、住、异、灭之迁流变化。
深邃：邃，音岁。深远也，这里‘深’，指造业深重，‘邃’，指入地狱的年代久远，即指此人业障深重，堕于大地狱而不能自拔也。
省：音醒，察看，检查，如反省、内省。《论语·学而》：“吾日三省吾身”。又知觉、醒悟，如发人深省，引申为明白。《列子·杨朱》：“实伪之辨，如此其省也”。本经此处之意指后者，意为“应当明白那是作恶，堕恶道的路子”。
幡盖：幡及伞盖乃佛殿之庄严具。造幡有降魔、延寿及不堕恶道等福德，造黄色的幡以及伞盖，在死亡之日悬于佛像之前为亡者积福，可以使亡者离去八苦，受生到十方诸佛的净土。
本识：即阿赖耶识，因阿赖耶识是有为无为诸法的根本。阿赖耶，梵文Alaya，原指储藏物品的仓库或藏，有潜藏、贮藏、执著等义。
拜祭：拜者，跪拜。中国拜法与西域佛教拜法不同，也称三跪九叩，沿用道家的礼拜方式。佛教礼拜常用头面接足礼，即跪地后两掌心向上，头安于两掌中间触地也。祭者，祭奠。以供品（如灯香花烛食品之类）供鬼神享用，达到安慰亡灵及求鬼神满已愿。
魍魉：音网两。古代传说中的精怪，多由依草附木而生。《楞严经卷八》云：“贪明为罪，是人罪毕，遇精为形，名魍魉鬼。……此等皆是自妄想业之所招引”。
圣分：圣，正也，能证正道，名之为圣。《大乘义章》云：“初地以上，息妄契真，会正名圣”。圣人者，大小乘见道以上断惑证理之人也。圣分者，能得见圣闻法的福分也。圣因者，造能得见圣闻法的因缘也。圣事者，行能得见圣闻法之事也。
殃累：以造恶所得之祸殃，连累他人或自己也。
大辩：辩才无碍之意。
无生：指不生不灭，已断尽三界烦恼的涅槃境地。涅槃之真理无生灭，故称无生。观无生之理，则可破生死烦恼也。无生法忍者，于无生灭诸法实相中，信受通达、无碍不退，是名无生忍。以无漏真智证此理，名证无生法忍。
闻健自修：“闻”者，闻经中所说命终后，为亡者修功德、造诸善因之事也；“健”者，趁现在身体尚健，一息尚存之时也；“自修”者，自修自得也。
无常：佛教认为世间一切之法，生灭迁流，刹那不住，谓之无常。此处指地狱之恶鬼。无常大鬼：无常者，梵语阿你怛也。世间一切之法，生灭迁流刹那不住，谓之无常。以无常故，生必有死也，死时有杀鬼至，名无常大鬼。《毗奈耶律三十四》曰：“于寺门屋下画生死轮……于轮上应作无常大鬼，发张口，长舒两臂，抱生死轮”。
冥冥游神：指人死之后的孤魂，它们通常寿命最长为四十九天，若是大善大恶之人，则少于此天数便转世去也。
营斋：斋，梵名乌哺沙他，又称布萨，清净之义，后又转为“时”义，指时非时也。以正午以前为“时”，正午以后为“非时”，即过午不食也。此为斋之本义，后又转为素食之义。又“斋戒”者，清心之不净为“斋”，禁身之过非为“戒”，此为斋之又一义也。又，“斋七”者，谓人死后七七日之斋会也，即以死后每七日一次斋会，以至七七四十九天的七次斋会也。营斋之会，供佛供僧，以清净之素食于午前供之，不得先食，不得染污。
菩提之心：梵文Bodhi—citta，即觉心，又称无上道心、无上道意、道心。此菩提心为一切诸佛之种子，是净法长养之良田，若发起此心，勤行精进，则得速成无上菩提。', '这时，地藏菩萨摩诃萨恭敬地对佛说：“世尊，我看阎浮提的众生，举心动念，没有一件不是起造罪因的。即使偶尔有所善举，也多是半途而废，不能够持久。倘若碰到恶因缘，碰上作恶的机会，便会于念念之中再起邪见。这些人就好像行走在淤泥沼泽中一样，身上还背着沉重的石头，步履越来越艰难，越来越沉重，脚步也越陷越深。如果能有缘得到善知的帮助，帮他减轻些负担甚至除去他身上的全部负担，这是因为善知有大力量的缘故。不仅如此，还亲自帮扶他，使他站稳，从而走出泥泞而到达平地，并且叮嘱他一定要意识到沼泽地的险恶，不要再重蹈覆辙了。”“世尊，习惯于行恶的众生，往往是从最微细的一点小恶开始，不以为然，从而越做越多，终于积累了无量无数的罪业。这些众生如果沾染了这样的恶习，在他临死之前，父母亲属应当为他做种种功德，培养种种福报，以便投生到较好的去处。在佛菩萨像前悬挂幡盖，或点燃油灯，或读诵佛经，或以种种上好供具供养佛菩萨像及圣者像。同时在临终之人面前称念佛菩萨或辟支佛的名号，一名一号，清清楚楚，使佛号或经文清晰地通过临终人的耳根，印在其八识田中。这些众生，根据其生前所造的业因，本来应当堕入到恶道中去，但因为有亲属为他做了功德，种下了善因，其过去的罪业统统消灭了。倘若还能在身死之后的七七四十九天之内，努力多做各种善事，加以回向，不但能使已死之人永远脱离恶道，得生人间、天上，享受种种美妙的安乐；对于在世的亲属来说，也能够获得无量的利益和安乐。”“因此，我今天在这大会上面对世尊，以及天龙八部、人非人等，劝告阎浮提众生：在临死之前，千万不要去杀生以及造种种恶缘，为‘保佑’亡灵，而祈求魍魉魑魅，祭神拜鬼。为什么呢？因为这样杀生以及祭拜鬼神之举，非但丝毫帮助不了死去的人，反而还结下了新的罪缘，使罪业更加深重。即使亡者在过去世或现在世曾经结过善缘、种过善根，应当可以生到人间或天界享受福报，却由于被无知的亲属造下如此的恶业，致使临终之人受到牵连，与那些被杀死的生命对辩冥司，受到责问或责罚，从而拖延了投生善道的时间。更何况命终之人在世之时，并没有多少的善业，各人将根据自己的所作所为自受其报，怎么还忍心让他由于亲属的无知，再添种种恶业，甚至堕入恶道中去呢？比如说，有人从遥远的地方长途跋涉而来，准备的食粮早已用尽，已经三天没吃上饭了，而他背负的行李又超过百斤。正在这时，忽然又遇到邻居朋友，请他再捎上一些东西，结果弄得那人更加困重不堪了。世尊，我看阎浮提的众生，只要能信受佛法，乐于为善，所为的善事哪怕小到一丝一毫、一沙一尘，这些善行所带来的利益绝不会白费，分分都可自得。”说这些话时，法会中有一位长者，名叫大辩。这位长者在很久以前就已证得无生法忍，以种种智慧方便，化现为长者的形象教化度脱十方一切众生。这时，大辩长者合掌恭敬，请问地藏菩萨说：“大士，南阎浮提众生在命终之后，家里大大小小的亲属为他做种种功德，设斋供养十方僧众，造种种善因，像这样的话，命终之人，能否得到大利益及解脱呢？”地藏菩萨回答说：“长者，承蒙佛力的加被，我现在就为未来和现在的一切众生，简略说一下这件事。长者，未来和现在的一切众生，在临命终时，能有缘听到一位佛的名字、一位菩萨的名字乃至一位辟支佛的名字的话，无论原来有罪或无罪，都能得到解脱。倘若有男子、女人活着的时候，不修善因，造了许多恶业，命终之后，家里大大小小的亲属，为他（她）修福行善，做种种功德。其修福行善所带来的利益，亡者所获有七分之一，其余的六分为活着的人所得。正因为如此，未来的和现在的善男女等，要趁着耳聪目明、身体强健的时候，努力自己修行，不要等到临死时，靠家属来代为修福。自己修行所带来的功德，分分都是自己所获的。”“无常大鬼，总是不期而至。人死之后，冥冥之中的魂神不知自己的罪报或福报有多少，便随着无常去了。在七七四十九天之内，如痴如聋，或者在各个阴司中对辩生前所作所为的善恶罪福。审定之后，个人便依据自己的业报到一定的道中去投生。在尚未审定的期间，就已经是千愁万苦，更何况有的人还得堕落到各种恶道中去呢？命终之人，在尚未托生的七七四十九天之内，念念之间，都在盼着活着的骨肉至亲为他们修福行善，做种种功德来超度他、救济他。过了四十九天之后，业报已经审定，就随着其生前所做的业因投生去了。倘若此人在生之时曾经造恶深重，其结果往往是千百年中在恶道里受苦。倘若犯了五无间的极恶重罪时，就将千劫万劫堕在无间地狱里，几乎是永无出头之日，一直要承受极端的酷刑与痛苦。”“另外，长者，那些造罪的众生在命终之后，家里的亲人为他设斋修福，并以此功德来帮助亡者消除罪业，免除恶道之苦。需要注意的是：在办斋之时以及供斋以后，淘米的泔水或菜叶等东西不能丢弃于地，更不能随意糟蹋。那些贡品食物，在供养佛、法、僧三宝之前，千万不能自己先吃。如果有人违反了上面所说的规矩，自己先吃了，或是在供养时不够恭敬、不够虔诚的话，那么这个亡人将很难得到功德利益。如果能遵守上述的规矩，以勤恳诚敬的态度，用清净妙洁的供品来供养佛僧，那么，所做功德，有七分之菩萨降魔一可以利益亡者，六分功德为办斋的眷属所得。因此，长者，阎浮提的众生若能为他们的父母或亲人在命终之后虔诚设斋供养的话，无论是死去的还是活着的，都会获得很大的利益与福报。”地藏菩萨在说完这些话时，忉利天宫有千万亿那由他、无法计数的阎浮提鬼神，都发了无量的菩提心。大辩长者恭敬作礼，退回到自己的座位上去了。', NULL, '', 'indent', 1523465562, '5acdccd67f6fd3003fc1a361', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637064, '袁州州学记', NULL, 2, 342, 0, 1, '李觏', NULL, 27895, '583ffe480ce4630057646ad6', '宋', 'wen', '文', 'https://baike.baidu.com/item/%E8%A2%81%E5%B7%9E%E5%B7%9E%E5%AD%A6%E8%AE%B0/7781398?fr=aladdin', '', '皇帝二十有三年，制诏州县立学。惟时守令，有哲有愚。有屈力殚虑，祗顺德意；有假官借师，苟具文书。或连数城，亡诵弦声。倡而不和，教尼不行。
三十有二年，范阳祖君无泽知袁州。始至，进诸生，知学宫阙状。大惧人材放失，儒效阔疏，亡以称上意旨。通判颍川陈君侁，闻而是之，议以克合。相旧夫子庙，狭隘不足改为，乃营治之东。厥土燥刚，厥位面阳，厥材孔良。殿堂门庑，黝垩丹漆，举以法。故生师有舍，庖廪有次。百尔器备，并手偕作。工善吏勤，晨夜展力，越明年成。
舍菜且有日，盱江李觏谂于众曰：“惟四代之学，考诸经可见已。秦以山西鏖六国，欲帝万世，刘氏一呼，而关门不守，武夫健将，卖降恐后，何耶？诗书之道废，人惟见利而不闻义焉耳。孝武乘丰富，世祖出戎行，皆孳孳学术。俗化之厚，延于灵、献。草茅危言者，折首而不悔；功烈震主者，闻命而释兵；群雄相视，不敢去臣位，尚数十年。教道之结人心如此。今代遭圣神，尔袁得贤君，俾尔由庠序，践古人之迹。天下治，则谭礼乐以陶吾民：一有不幸，尤当仗大节，为臣死忠，为子死孝。使人有所赖，且有所法。是睢朝家教学之意。若其弄笔墨以徼利达而已，岂徒二三子之羞，抑亦为国者之忧。”
此年实至和甲午，夏某月甲子记。', '《袁州州学记》是宋人李觏（gòu）的名作，文章记叙了宋仁宗时，任袁州知州的祖无择看到学宫破损的现状，决定兴建新学宫的过程。学宫落成之刻举行的“释菜”祭孔仪式上，在宜春讲学的李觏大为感慨，遂发表了此篇文章，感慨申论。', '皇帝：这里指宋仁宗。
祗（zhǐ）：恭敬。
范阳：古郡名，在今河北涿县一带。祖君无泽：祖无泽，字泽之，北宋上蔡（今河南上蔡县）人，历官直集贤院。袁州：治所在今江西宜春县。
通判：官名，地位略次于州府长官。陈君优（yōu）：陈优，字复之，北宋长乐（今福建长乐县）人，进士。
黝（yǒu）：淡黑色。垩（è）：白色土。
舍菜：也作“舍采”，古代入学开始时举行的一种仪式。即向孔子牌位献上芹藻一类菜蔬。舍，放下。
盱（xū）江：水名，一称抚河，又称建昌江，在今江西东部，谂（shěn）：规劝，告诉；勉励。
草茅：指在野的人。
谭：同“谈”。二三子：即“二三君子”的略称，大家，诸君。', '仁宗皇帝廿三年，下诏命令各州县设立学馆。那时的州县长官，有的贤明，有的愚昧。奉行诏令时，有的尽心竭力，恭敬地仰承皇帝旨意；有的装装门面，充当官、师，胡乱写一道奉诏文书了事。以致有些地方，一连几座城邑，听不到朗朗的读书声。上面倡导而地方不响应，使得教学受阻，不能推行。
仁宗皇帝三十二年，范阳人祖无择任袁州知州。初来时，就召见一班儒生，了解到学馆残缺破败的情况。他很担心人材流失，儒学的教化作用逐渐削弱，不能合乎皇上旨意。颍川人陈侁通判，听了很以为然，意见与祖无择完全一致。他们一同察看了旧有的夫子庙，觉得太狭窄，不适宜改建为学馆，于是决定在城的东北角上建造新学馆。那儿土地干燥坚硬，那儿地势朝南，那儿建筑材料非常优良。学馆的陶瓦、墙壁、大门、房廊，有深灰、雪白、朱红、漆黑诸色，完全合乎法度。所以学生、老师都有安身之所，厨房、粮仓都有安排之处。各种器物准备齐全，大家齐心协力建造，工匠技艺高超，官吏勤快不怠，没日没夜努力从事，过了一年，就将学馆建成。
在即将开学之时，旴江人李觏对众人勉励说：“那虞、夏、商、周四代办学之事，我们只需考察一下经书就可以知道。那秦始皇凭藉崤山以西之地，与六国大战，想万世称帝，被刘邦率军振臂一呼，却连关门也守不住。武官战将，争相投降惟恐落后，这是为什么呢？那是因为秦国废弃了诗书教化之道，使众人见利忘义的缘故。汉武帝即位于民富国强之际，光武帝出身于行伍之间，都能极力推行儒学，所以民风淳厚极了，一直影响到汉灵帝、汉献帝的时代。当时，那些在野之人而敢直言的，即使有杀身之祸也不反悔自己的忠直；那些功劳大得连皇帝也感到威摄的大臣，一听到天子的命令就放下了武器。各路诸侯虎视眈眈，却都不敢称帝，这种局面尚且维持了数十年。儒家的教化之道竟能这样地维系人心。如今躬逢圣明天子，你们袁州人又遇到了贤明的官长，使你们能通过学馆的教化，追随古代圣贤的遗迹。当天下太平的时候，则可以继承礼乐来陶冶我们百姓的性情；一旦有了变故，还可以坚持节操，做臣子的为国尽忠，当人子的为父尽孝。学了儒道，可以使人有所效法，有了精神支柱。这就是国家倡导教学之意。如果到这里来只学得一套舞文弄墨的本领以求得名利，那岂仅是你们的羞耻，而且也是治国之人的忧虑。”
至和元年夏某月甲子日作记。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1f80ce818559d064c8f", "shortContent": "宋初开国数十年间，统治者对于科举十分关注，但尚未重视兴学。朝廷只设一所国子监（国子学），学生甚少，州、县一级的学校更是寥寥无几。宋仁宗庆历三年（1043），开始设立四门学，并在藩镇立学；次年又“诏天下州县立学，更定科举法”（《宋史·仁宗纪三》），正式建立太学。从此以后，各地兴建官学成风，“州郡不置学者鲜矣”（明彭大翼《山堂肆考》商集卷三《教授》）。但兴办官学，毕竟要通过官府的努力才行。有的官府，能...", "authors": ["曾枣庄曾弢"], "pressName": "上海辞书出版社"}]', '', 'indent', 1523029352, '5ac724d59f5454147aa1b0f0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637067, '渔家傲 · 独木小舟烟雨湿', NULL, 31, 156, 1, 1, '程垓', NULL, 10191, '57c6f782efa631005ad93a9b', '宋', 'ci', '词', '', '', '独木小舟烟雨湿，燕儿乱点春江碧。江上青山随意觅，人寂寂，落花芳草催寒食。
昨夜青楼今日客，吹愁不得东风力。细拾残红书怨泣，流水急，不知那个传消息。', '程垓的《渔家傲》在写作手法上与其他诗词相比，有其独特性，这种独特性主要体现在：一是别具一格的谋篇布局。一般表现男女离别之情的词作，都是以泪洗面，依依不舍的场景描写，扣人心弦。这首词却撇开这些不写，而把描写的场面集中在离人的船上。它通过倒叙，把昨夜的聚会，叠印在今日的悲离之中，用今天的相思苦，反衬出以前的相爱之深，从而形成虚与实、悲与欢的对照。这就使得它画面集中，表现深刻。二是独辟蹊径地构想了一个极富表现力的小情节，即在结尾处所写，让残阳传达相思之苦。不过，它的真正目的，并非是通过落花来传情达意，而仅仅是表现自己的一片真心与痴情，减轻一点相思之痛苦罢了。
上阕着意描写与情人分别后船行江中的所见所感。
首三句写春江春雨景色：自己乘坐的小船在烟雨朦胧中行进，到处都是湿湿润润的；燕子在碧绿的江面上纷纷点水嬉戏；两岸的青山若隐若现，倒也可以随意寻认。这些烟雨朦胧中的景物自然是很美的，但又处处暗示出一种忧郁的气氛。「人寂寂」二句也是写景，却更带着浓厚的感情色彩。人寂寂，既指两岸人影稀少，也指自身形影相吊，象离群的孤雁。「落花芳草催寒食」是一种风趣的拟人说法，意即落花缤纷，芳草萋萋，寒食节要到了。古代的寒食节是一个以亲朋友好相聚赏花、游春为主要内容的欢乐的节日。词人于节前离开情人，想必是出于不得已，难免更添几分惆怅。
下阕着意表现不堪忍受的相思之苦。「昨夜青楼今日客」二句点明自己何以感到孤寂与忧伤，那是因为昨晚还在青楼（泛指妓女所居）与心爱的人儿欢聚，今日却成了江上的行客，这骤然离别的痛苦叫人怎么忍受得了。想借东风把心中的愁云惨雾吹散吧，只因愁恨如山，东风也吹它不动。在百般无奈中，终于想出了一个排解的新法，那就是后三句所写：将岸边、洲头飞来的落花（即残红），小心拾起，写上自己的愁苦，撒向江中。可是流水太急，不知会漂向何处，意中人怎能看到，这些爱情的使者又向谁传递消息呢？
言外之意是愁还是愁，怨还是怨，相思仍如春江水，无止无息。这几句显然是由唐人的红叶题诗的故事演化而来，不仅十分自然，其表现力也超过了原故事，实在是一种再创造。
在古代，有许多文人骚客，每当他们遇到不顺心，难以排解的事情时，譬如，科场失意，官运不佳，爱情坎坷，他们便不惜花费许多时间、金钱去青楼寻花问柳，寻求一时解脱。这首词所描绘的就是这种落魄文人的浪漫生活。这种题材在婉约派诗词中很常见，但在写作上，作者颇费心思，没有落入别人的窠臼。', '', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74e303572034f65963a7", "shortContent": "封建时代有不少知识分子，每当他们科场失意、仕途不畅，或婚姻不美满时，常常不惜花费大量的时间与金钱去怜香惜玉，卧柳眠花。这虽然可以得到暂时的欢乐与安慰，却又免不了要承受相思离别之苦。这首词所写的就是这种落拓文人的浪漫生活。这种题材是婉约派词作中最常写的，如果不在艺术上求新，很可能成为平庸或浅薄之作。作者似乎很懂得这一点，着实费了一点心思，没有落入俗套。\n上片着意描写与情人分别后船行江中的所见所感。首...", "authors": ["谢楚发"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5ef0ce818559d063c13", "shortContent": "封建时代有不少知识分子，每当他们科场失意、仕途不畅，或婚姻不美满时，常常不惜花费大量的时间与金钱去怜香惜玉，卧柳眠花。这虽然可以得到暂时欢乐与安慰，却又免不了要承受相思离别之苦。这首词所写的就是这种落拓文人的浪漫生活。这种题材是婉约派词作中最常写的，如果不在艺术上求新，很可能成为平庸或浅薄之作。作者似乎很懂得这一点，着实费了一点心思，没有落入俗套。\n上片着意描写与情人分别后船行江中的所见所感。首三...", "authors": ["谢楚发"], "pressName": "上海辞书出版社"}]', '淸·陈廷焯《白雨斋词话·卷六》：正伯词，余所赏者惟《渔家傲》结处云：「细拾残红书怨泣，流水急，不知那个传消息。」为有深婉之致。', 'indent', 1523224040, '5aca1d5f9f5454730215d72e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637069, '乞校正陆贽奏议进御札子', NULL, 2, 3406, 0, 1, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'wen', '文', 'https://baike.baidu.com/item/%E4%B9%9E%E6%A0%A1%E6%AD%A3%E9%99%86%E8%B4%BD%E5%A5%8F%E8%AE%AE%E8%BF%9B%E5%BE%A1%E6%9C%AD%E5%AD%90/2796198?fr=aladdin', '', '臣等猥以空疏，备员讲读。圣明天纵，学问日新。臣等才有限而道无穷，心欲言而口不逮，以此自愧，莫知所为。
窃谓人臣之纳忠，譬如医者之用药，药虽进于医手，方多传于古人。若已经效于世间，不必皆从于己出。
伏见唐宰相陆贽，才本王佐，学为帝师。论深切于事情，言不离于道德。智如子房而文则过，辩如贾谊而术不疏，上以格君心之非，下以通天下之志。但其不幸，仕不遇时。德宗以苛刻为能，而贽谏之以忠厚；德宗以猜疑为术，而贽劝之以推诚；德宗好用兵，而贽以消兵为先；德宗好聚财，而贽以散财为急。至于用人听言之法，治边驭将之方，罪己以收人心，改过以应天道，去小人以除民患，惜名器以待有功，如此之流，未易悉数。可谓进苦口之乐石，针害身之膏肓。使德宗尽用其言，则贞观可得而复。
臣等每退自西阁，即私相告言，以陛下圣明，必喜贽议论。但使圣贤之相契，即如臣主之同时。昔冯唐论颇、牧之贤，则汉文为之太息；魏相条、董之对，则孝宣以致中兴。若陛下能自得师，莫若近取诸贽。夫六经三史，诸子百家，非无可观，皆足为治。但圣言幽远，末学支离，譬如山海之崇深，难以一二而推择。如贽之论，开卷了然。聚古今之精英，实治乱之龟鉴。臣等欲取其奏议，稍加校正，缮写进呈。愿陛下置之坐隅，如见贽面，反覆熟读，如与贽言。必能发圣性之高明，成治功于岁月。臣等不胜区区之意，取进止。', '《乞校正陆贽奏议进御札子》是苏轼在宋哲宗即位不久，旧党上台后写的。当时王安石推行的新法被吕惠卿\章惇等弄得弊端百出，面目全非，新旧党争使百姓遭殃，国家受害。因此，苏轼进札子建议哲宗读陆贽的奏议，从中学习治国之术。', '备员：凑数。讲读：指侍讲、侍读，官名。
逮：到，及。
陆贽：任翰林学士、宰相，后受谗被贬，著有《翰苑集》，亦名《陆宣公奏议》。唐德宗时，宰相陆贽为政清廉，从来不收受任何馈赠。在与地方藩镇官员的交往中更是从不言利，分外之财分毫不取。陆贽的母亲去世，在3年的丁忧期间，各地藩镇都纷纷赠送厚礼，数量达几百份，可他硬是一份没收。对此，一些想通过送礼巴结他这位朝中重臣的地方官员便老大不满，埋怨他不近人情。这种声音传到德宗的耳朵里，德宗也觉得陆贽“清慎太过”，便私下里对陆贽说：“卿清慎太过，诸道馈遗，一概拒绝，恐事情不通，如鞭靴之类，受亦无伤。”意思是说，过于清慎廉洁，拒绝地方各级官员的馈赠，恐怕有些过分。可以不收受贵重物品，接受点儿诸如马鞭、靴鞋之类的小礼物总还是可以的。然而，陆贽却有自己的看法。他认为：“利于小者必害于大，贿道一开，展转滋甚，鞭靴不已，必及衣裘，衣裘不及，必及金璧。”并一针见血地指出：“伤风害礼，莫甚于私；暴物残人，莫大于赂。”此后，陆贽依旧保持清廉的节操，始终不渝。
名器：《左传》：“唯器与名，不可以假人。”意即赏赐不可滥。
颇：廉颇。牧：李牧。均为战国时名将。
太息：出声长叹。
晁：晁错。董：董仲舒。均为西汉时思想家。', '臣等依凭空虚浅薄的才学，在翰林院侍讲、侍读的职位上充个数目。皇上的聪明睿智是上天赋予的，学问一天比一天深厚。臣等才学有限，然而圣贤之道没有穷尽，心中虽然想表述清楚可口头上表达不出来，因此自己感到很是惭愧，不知道该怎么办。
臣等认为作为臣子向皇帝进献忠诚，就像医生对准病症去用药一样，药虽然经医生之手传过去，但药方多是从古人那里留下来的。如果药方在世间证明确实很灵验，那么就不必一定要由医生自己创造出来才用。
臣等听说唐德宗时的宰相陆贽，才能本来就是帝王的辅佐，学问足可成为帝王的老师。他的议论深刻而切合物事人情，言语从不偏离圣贤的道德规范。才能与西汉的张良（张良字子房）齐肩而文才却要胜过他，议论的才能像西汉的贾谊而方法却不粗疏。上可以纠正皇帝想法上的错误，下能够贯通天下人的心志。三代也只他一人罢了。但他不幸的是做官没能赶上良好的时机。唐德宗以严厉刻薄为能事，陆贽就以忠诚敦厚去规谏；唐德宗以猜疑忌恨去对人，陆贽就以推心置腹去劝说；唐德宗喜好用兵打仗，陆贽则认为消除战事是当时首先要做到的；唐德宗喜好敛聚财物，陆贽则认为散财于民最为迫切。至于任用人才、接受意见的方法，整治边防、驾驭将帅的策略，归罪于自身以收拢人心，改正过错以顺应天道，斥去小人以消除人民的祸患，珍惜爵位、宝器以授予有功的人，像这类合理的建议，很难列举完。陆贽真可以说是进献了苦口的良药，去诊治危害身体的重病。假使唐德宗能完全按陆贽的进言去实行，那么贞观之治的盛况便会再一次出现。
臣等每次从皇帝听讲的西阁退出，都私下相互议论，认为您是圣明的天子，一定喜欢陆贽的议论。只要使像您这样的圣明天子和像陆贽那样的贤能大臣意见相吻合，那就像圣君和贤臣处于同一时代一样了。当初冯唐高度赞扬战国时廉颇、李牧的贤能，汉文帝则为不能使用他们而深深叹息；魏相陈述了西汉晁错、董仲舒等应对当时皇帝的言语，汉宣帝就按这些言语施政而成就了汉室中兴的业绩。如果陛下能自己寻求老师，就不如从近一点的唐朝选取陆贽。再说那《诗》、《书》、《礼》、《易》、《乐》、《春秋》六经，《史记》、《汉书》、《后汉书》三部史书，以及诸子百家的著作，并不是没有可以效法的，而且依照这些史籍所阐述的道理都足以治理好国家。然而《六经》当中的圣贤言论精深奥秘，而史书、子书中存留的圣贤学说却颇不完整，犹如高山大海那样崇高深远，很难从中选择出多少可以直接推广运用的东西。而陆贽的议论，一打开书本就非常明了清楚，汇聚了古往今来的学说精华，确实是国家治乱的一面镜子。臣等想把他向皇帝的进言文章稍微加以整理校对，重新抄好进呈给陛下。希望陛下把它放在自己的座位旁边，就像亲眼见到陆贽之面一样；反复熟读它，就像和陆贽当面谈话一样。这样，一定能启发陛下天子之性的神明天资，在不长的时间内就能成就强盛国家的功业。臣等说不尽愚陋的心意，请陛下决定是否采用。', NULL, '吴楚材、吴调侯《古文观止》：东坡说宣公，便学宣公文章。讽劝鼓舞，激扬动人。宣公当时不见知于德宗，庶几今日受知于陛下，与其观六经、诸子之崇深，不如读宣公奏议之切当，尤使人主有欣然向往、恨不同时之想。', 'indent', 1523287599, '5acb15ad9f54541c8bb6ab30', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637070, '送天台陈庭学序', NULL, 2, 187, 0, 1, '宋濂', NULL, 10280, '57ba47cc7db2a20068c1a3ef', '明', 'wen', '文', 'https://baike.baidu.com/item/%E9%80%81%E5%A4%A9%E5%8F%B0%E9%99%88%E5%BA%AD%E5%AD%A6%E5%BA%8F/10252848?fr=aladdin', '', '西南山水，惟川蜀最奇，然去中州万里，陆有剑阁栈道之险，水有瞿塘、滟滪之虞。。跨马行，则竹间山高者，累旬日不见其巅际；临上而俯视，绝壑万仞，杳莫测其所穷，肝胆为之悼栗。水行则江石悍利，波恶涡诡，舟一失势尺寸，辄糜碎土沉，下饱鱼鳖。其难至如此！故非仕有力者，不可以游；非材有文者，纵游无所得；非壮强者，多老死于其地；嗜奇之士恨焉！
天台陈君庭学，能为诗，由中书左司掾屡从大将北征，有劳，擢四川都指挥司照磨，由水道至成都。成都，川蜀之要地。扬子云、司马相如、诸葛武侯之所居，英雄俊杰战攻驻守之迹，诗人文士游眺饮射、赋咏歌呼之所，庭学无不历览。既览必发为诗，以纪其景物时世之变，于是其诗益工。越三年，以例自免归，会予于京师；其气愈充，其语愈壮，其志意愈高；盖得于山水之助者侈矣。
予甚自愧：方予少时，尝有志于出游天下，顾以学未成而不暇；及年壮可出，而四方兵起，无所投足；逮今圣主兴而宇内定，极海之际，合为一家，而予齿益加耄矣！欲如庭学之游，尚可得乎？
然吾闻古之贤士，若颜回、原宪，皆坐守陋室，蓬蒿没户，而志意常充然，有若囊括于天地者，此其故何也？得无有出于山水之外者乎？庭学其试归而求焉。苟有所得，则以告予，予将不一愧而已也！', '《送天台陈庭学序》是元末明初文学家宋濂为天台学士陈庭学所做之序。行文规整，在文中也透露出作者自身的豪气和对知识的孜孜追求。和《送东阳马生序》类似，都被教学大纲选入过教材。', '川蜀：泛指今四川一带。
中州：泛指今河南一带。写此文时，宋濂正在河南龙门山讲学。
剑阁栈道：栈道名，在今四川省剑阁县东北大剑山和小剑山之间。栈道：在山势险峻无路可行的地方凿石架木所构成的通道。
瞿塘：即瞿塘峡，为长江三峡之一。滟滪：即滟滪堆，在瞿塘口，是突出在长江江心的巨石，为长江上著名的险滩。虞：忧虑。
杳：深邃朦胧貌。
悼栗：颤抖。
波恶：形容波涛很大很凶。涡诡：指怪异的旋流。
糜碎：粉碎。
天台：县名，今属淅江省。
中书左司掾：元代以中书省总领百宫，与枢密院，御史台分把政、军、监察三权。中书省下置左右司，分管省事，明初尚沿元制，掾：古代属官的通称。
擢：提升。指挥司：明代在各省设置的地方军事机关。照磨：指挥司的属官，主管文书。
扬子云，司马相如：并为西汉时期有名的辞赋家；诸葛武侯：即诸葛亮，曾封武乡侯，故后人亦称之诸葛武侯。
射：指射箭，为古代六艺之一。
侈：大，多。
顾：不过。
四方兵起：指元末全国各地的农民起义和反元战争。
耄：老。
颜回、原宪：都是孔子的学生，一生穷困而德行很高。
得无：岂不是。', '西南地区的山水，只有四川最为奇异。然而它与中原地区远隔万里，陆路有剑阁栈道的险途，水路又有瞿塘峡、滟滪堆的忧虑。骑着马，在竹林和崇山峻岭中穿行，常常是几十天都看不到峰顶。站在高处向下俯视，高峻的山谷深不可测，令人胆战心惊。从水路走，那江中的礁石凶险尖利，波涛旋涡诡异险恶，小船一旦有尺寸差池，往往粉身碎骨，沉入江底而葬身鱼腹。既然是如此艰险，因而那些没有体能的官员不可以去游历，那些有文采而无材质（感受力）的人，即使去游历也不会有收获。不是身强体壮的人，大多会老死在这个地方，为此，那些爱好奇异山水的人都会感到遗憾。
天台陈庭学君，擅长作诗，多次以中书左司掾之职而随从大将北征，建有功劳，提拔为四川都指挥司照磨，经过水路到成都。成都，是四川的要地，扬雄、司马相如、诸葛亮曾经在此生活过，英雄豪杰曾在此攻伐征战、驻扎防守过，诗人文士也曾在此游历观览、饮酒射覆、赋诗吟咏。庭学无处不去游历观览，之后必定发而为诗，用来记录这些地方景物和时序的变化，由此他的诗艺更加精湛。三年之后，庭学依惯例自己辞职归来，在京师和我相聚。他的精神更加饱满，语气更加豪壮，志趣理想更加高远，这大概是他得益于山水帮助的缘故吧。
我内心很是惭愧，正当我年少时，曾经立志要出游天下，只是由于学业未成而不得空闲。等到可以出游的壮年时，四方战乱，我无处落脚容身。到现在圣主兴起，天下太平，四海成为一家，然而我却越来越老了。想要像庭学那样游历天下，还有可能吗？
然而，我听说过古代的那些贤士，像颜回、原宪，他们都处在野草都长得埋没了门户的陋室之中，而志向和意气却始终非常高远充沛，仿佛有一种囊括天地宇宙的胸怀。这是什么原因呢？难道有超出山水之外的东西吗？庭学大概就是尝试着回去探索这方面的东西吧。如果庭学有什么收获，就要告诉我，那样的话我将不只是惭愧而已。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed2022cee9a0c24edaea2", "shortContent": "赠序是古文中习见的写送别的文章。在这篇《送陈庭学序》中，宋濂与唐宋古文大手笔一样，送别只是借题，发挥却自由我，挥洒裕如、顿挫抑扬地做成了一篇内涵深刻，思致宛然，咀嚼有味，委婉含蓄的好文章。\n山水画家谈创作三昧，有所谓“搜尽奇峰打草稿”的名言，诗文作家谈写作经验，则有“行万里路，读万卷书”的心得。“行万里路”，除了阅历人生，便是阅历山水。名山大川，湖阔海深，不仅是文艺家取之不尽的创作素材，更是陶熔胸...", "authors": ["胡光舟"], "pressName": "上海辞书出版社"}]', '', 'indent', 1523289568, '5acb175a9f5454052204065f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637072, '司马季主论卜', NULL, 10, 1624, 0, 1, '刘基', NULL, 10076, '57ba8247c4c97100614d49ee', '明', 'wen', '文', 'https://baike.baidu.com/item/%E5%8F%B8%E9%A9%AC%E5%AD%A3%E4%B8%BB%E8%AE%BA%E5%8D%9C/304890?fr=aladdin', '', '东陵侯既废，过司马季主而卜焉。季主曰：“君侯何卜也？”东陵侯曰：“久卧者思起，久蛰者思启，久懑者思嚏。吾闻之：‘蓄极则泄，闷极则达，热极则风，壅极则通。一冬一春，靡屈不伸；一起一伏，无往不复。’仆窃有疑，愿受教焉。”季主曰：“若是，则君侯已喻之矣，又何卜为？”东陵侯曰：“仆未究其奥也，愿先生卒教之。”
季主乃言曰：“呜呼！天道何亲？惟德之亲；鬼神何灵？因人而灵。夫蓍，枯草也；龟，枯骨也；物也。人，灵于物者也，何不自听而听于物乎？且君侯何不思昔者也！有昔者必有今日。是故碎瓦颓垣，昔日之歌楼舞馆也；荒榛断梗，昔日之琼蕤玉树也；露蚕风蝉，昔日之‘凤笙’、‘龙笛’也；鬼磷萤火，昔日之金缸华烛也；秋荼春荠；昔日之象白驼峰也；丹枫白荻，昔日之蜀锦齐纨也。昔日之所无，今日有之不为过；昔日之所有，今日无之不为不足。是故一昼一夜，华开者谢；一春一秋，物故者新；激湍之下必有深潭，高丘之下必有浚谷。君侯亦知之矣，何以卜为！”', '《司马季主论卜》是一篇王顾左右而言他的文章，是讲“升沉应已定，不必问君平”（唐诗），实际讲的是元代末年的种种腐败都是从前胡作非为恶性发展的结果。在现代看来，这篇对话也是对当时统治者的一声警钟。', '东陵侯：秦人邵平曾被封为东陵侯。秦亡，其于长安东种瓜为生。
司马季主：西汉初年人，以占卜闻名。卜：占卜，指古人用龟甲、蓍草等预测吉凶的活动。
蛰：虫类冬眠。启：开，出来。
懑：闷。嚏（ti）：打喷嚏。
靡：无；没有。
仆：自称谦词。
喻：明了，明白。
天道：上天的意志。
蓍：草名，古人用其茎进行占卜。
龟：即龟甲，亦为古人占卜之用具。
榛：树丛。梗：草木枯枝。
蕤：原意为花朵下垂貌，这里指花朵。
风笙龙笛：并为乐器名。因像龙凤之形或饰有龙凤彩绘，故称。这里指悦耳的音乐。
鬼磷：即磷火。夜间火焰呈淡绿色，旧时人有的认为它是鬼火。
金缸：金属容器，古时用来作灯照明。
荼：菜名，味苦。
荠：菜名，味甘。
象白：即象鼻。白，古“鼻”字。
驼峰：骆驼的肉峰。
枫：即枫树，叶经霜变红，故称丹枫。
荻：草名，其花白色，故称白荻。
蜀锦齐纨：指四川出产的锦和山东出产的纨。纨：绢。
华：花。', '东陵侯被废黜以后，到司马季主那里去占卜。
司马季主问道：“君侯您要占卜什么事呢？”东陵侯答：“久卧在床的人总想起床，长期冬眠的动物想要醒来，长期郁闷的人总想要发泄。我听说蓄积太多就需要发泄，郁闷久了就需要通达，热得太厉害就需要吹风，堵塞到了极致就需要通畅。一冬一春之间，不会总是屈而不伸的，事物间总是一起一伏，没有去而不复的。我内心对此还是有疑惑，希望得到你的指教。”司马季主说道：“照你刚才这么说，说明君侯您已经很懂得事理了，何必还要来占卜呢？”东陵侯说：“我还是觉得我还没有懂得其中的奥秘，恳请先生就此好好开导我一下。”
司马季主这才说道：“唉！天道会亲近什么人啊？它只会亲近那些有德行的人！鬼神有什么灵验呢？鬼神只是靠人事才显示出灵验来！占卜用的蓍草，只不过是枯草，龟甲也只不过是枯骨，它们都只不过是物罢了。人，总比物要有灵性，为什么不相信自己而去相信物呢？况且，君侯您为什么不想想过去呢？有一种过去就有一种今天。因而，那些碎瓦断墙，曾经是过去的舞台歌榭，那些荒木断枝，也曾经是过去的玉树琼枝。今天在风露中哀鸣的蟋蟀和蝉，也曾是以往的华美的笙笛之音，幽暗的磷光鬼火，正是过去的金灯华烛，那秋日的苦菜和春天的荠菜，也正是过去的象白驼峰，那丹枫白荻，也是过去的蜀锦齐纨。以往没有的，今天有了，这并不为过，而以往有的，今天失去了也并非显得不足。因此，一日一夜之间，花开又花落，一春一秋之间，万物凋零又复苏。湍急的流水下必定有深潭，高山之下必有深谷。这些道理，君侯您是明白的，那么您何必占卜呢？”', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed202911759740c9bdcef", "shortContent": "这是《郁离子·天道》中的一篇，它通过寓言的形式，设为问答之辞，表达了鬼神何灵、变化不居的进步思想，阐述了一切事物无不向其对立面转化的辩证观点。刘基“慷慨有大节，论天下安危，义形于色”（《明史》本传），对元末统治集团采取不合作的态度。《郁离子》是他弃官归隐时的创作，思想上受到农民起义的影响，往往通过他所勾勒的艺术形象，从不同的侧面对元末的暴政和世风，展开了深刻的批判。这里所勾勒的两个艺术形象，选择了...", "authors": ["羊春秋"], "pressName": "上海辞书出版社"}]', '', 'indent', 1523288526, '5acb194d7565712a5ae03380', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637073, '信陵君救赵论', NULL, 1, 593, 0, 1, '唐顺之', NULL, 15813, '5858ea658e450a006c7fa13f', '明', 'wen', '文', 'https://baike.baidu.com/item/%E4%BF%A1%E9%99%B5%E5%90%9B%E6%95%91%E8%B5%B5%E8%AE%BA/304773?fr=aladdin', '', '论者以窃符为信陵君之罪，余以为此未足以罪信陵也。夫强秦之暴亟矣，今悉兵以临赵，赵必亡。赵，魏之障也。赵亡，则魏且为之后。赵、魏，又楚、燕、齐诸国之障也，赵、魏亡，则楚、燕、齐诸国为之后。天下之势，未有岌岌于此者也。故救赵者，亦以救魏；救一国者，亦以救六国也。窃魏之符以纾魏之患，借一国之师以分六国之灾，夫奚不可者？
然则信陵果无罪乎？曰：又不然也。余所诛者，信陵君之心也。
信陵一公子耳，魏固有王也。赵不请救于王，而谆谆焉请救于信陵，是赵知有信陵，不知有王也。平原君以婚姻激信陵，而信陵亦自以婚姻之故，欲急救赵，是信陵知有婚姻，不知有王也。其窃符也，非为魏也，非为六国也，为赵焉耳。非为赵也，为一平原君耳。使祸不在赵，而在他国，则虽撤魏之障，撤六国之障，信陵亦必不救。使赵无平原，而平原亦非信陵之姻戚，虽赵亡，信陵亦必不救。则是赵王与社稷之轻重，不能当一平原公子，而魏之兵甲所恃以固其社稷者，只以供信陵君一姻戚之用。幸而战胜，可也，不幸战不胜，为虏于秦，是倾魏国数百年社稷以殉姻戚，吾不知信陵何以谢魏王也。
夫窃符之计，盖出于侯生，而如姬成之也。侯生教公子以窃符，如姬为公子窃符于王之卧内，是二人亦知有信陵，不知有王也。余以为信陵之自为计，曷若以唇齿之势激谏于王，不听，则以其欲死秦师者而死于魏王之前，王必悟矣。侯生为信陵计，曷若见魏王而说之救赵，不听，则以其欲死信陵君者而死于魏王之前，王亦必悟矣。如姬有意于报信陵，曷若乘王之隙而日夜劝之救，不听，则以其欲为公子死者而死于魏王之前，王亦必悟矣。如此，则信陵君不负魏，亦不负赵；二人不负王，亦不负信陵君。何为计不出此？信陵知有婚姻之赵，不知有王。内则幸姬，外则邻国，贱则夷门野人，又皆知有公子，不知有王。则是魏仅有一孤王耳。
呜呼！自世之衰，人皆习于背公死党之行而忘守节奉公之道，有重相而无威君，有私仇而无义愤，如秦人知有穰侯，不知有秦王，虞卿知有布衣之交，不知有赵王，盖君若赘旒（liú）久矣。由此言之，信陵之罪，固不专系乎符之窃不窃也。其为魏也，为六国也，纵窃符犹可。其为赵也，为一亲戚也，纵求符于王，而公然得之，亦罪也。
虽然，魏王亦不得无罪也。兵符藏于卧内，信陵亦安得窃之？信陵不忌魏王，而径请之如姬，其素窥魏王之疏也；如姬不忌魏王，而敢于窃符，其素恃魏王之宠也。木朽而蛀生之矣。古者人君持权于上，而内外莫敢不肃。则信陵安得树私交于赵？赵安得私请救于信陵？如姬安得衔信陵之恩？信陵安得卖恩于如姬？履霜之渐，岂一朝一夕也哉！由此言之，不特众人不知有王，王亦自为赘旒也。
故信陵君可以为人臣植党之戒，魏王可以为人君失权之戒。《春秋》书葬原仲、翚（huī）帅师。嗟夫！圣人之为虑深矣！', '《信陵君救赵论》以大家所熟知的“信陵君窃符救赵”的事件为题材，对已有的评论予以反驳，并陈述了自己的观点。文章开篇简练，没有过多赘述即阐明自己观点，指出赵国在军事上乃魏国的屏障，赵国灭亡，则魏国亦凶多吉少，由此得出“救赵者，亦以救魏，救一国者，亦以救六国也”的论断，因之，信陵君窃符救赵并无不可。', '符：兵符，其形如虎，故又称“虎符”。古代将帅出征时，由国君和将帅各执兵符一半，以后国君想调动军队时，须将国君所执的一半送至将帅处，与将帅所执的一半吻合后方能接受命令。
岌（jí）岌：极端危险。
平原君：战国时赵惠文王之弟，名赵胜，曾任赵相，为战国四公子之一。其夫人为信陵君之姐。当秦兵围赵时，平原君曾多次派使者向信陵君求救，并以姻亲关系来打动其心。谢：在这里是“请罪”之意，与现代用法不同。侯生：侯赢，原为魏国国都夷门的守门人，后为信陵君家中门客。当平原君向信陵君求救时，他向信陵君提出窃符之计。
曷若：何如，倘若。“如姬”句：如姬之父被人杀害，信陵君曾为之复仇，故如姬对信陵君深为感激。
穰（ránɡ）侯：魏冉，秦昭襄王之舅父，曾任秦将军、相国，握有秦国军政大权。“穰侯”为其封号。虞卿：赵孝成王时相国。他和魏国的魏齐曾为早年间的好友，其后魏齐遇难出奔，他为了帮助魏齐，竟弃官与之一起出走。赘旒（zhuìliú）：旒，同“瘤”，多余的东西。
履霜之渐：《易经·坤》：“履霜坚冰至。”说明行路时如踏到霜，则冰天雪地即将到来。
葬原仲：原仲为陈国大夫，死后，其旧友季友（鲁国的公子）私自去陈国将其埋葬。孔子认为这是非礼的行动。翚（huī）帅师：鲁隐公时，宋、陈等国进攻郑国，宋国也要鲁国出兵，鲁隐公不同意，鲁大夫翚（即羽父）未得允许便帅师而去。孔子认为这是目无君主。', '评论者拿盗窃兵符一事做为信陵君的罪过，我认为凭这一点还够不上拿来责罪于信陵君的哩。那强劲的秦国暴虐到极点了，如今把其所有的兵力来压于赵国，赵国肯定会灭亡。赵国是魏国的屏障，赵国亡了，那么魏国将要步其后尘；赵国与魏国，又是楚、燕、齐各国的屏障，赵、魏亡了，那么楚、燕、齐各国就得步其后尘了。天下的形势，再没有岌岌可危到像当时一样的了。因此，救赵国，也就是用以救魏国；救这一个国家，也就是用以救六个国家啊。盗窃魏国的兵符来解脱魏国的祸患，借用一国的军队来分担六国的灾难，这有什么不可以的！
那么信陵君真的没有罪过吗？回答是：这话又不对了。我所责备的，是信陵君的心啊！信陵君不过是一个王室公子罢了，魏国自有其君王的嘛。赵国不请求于魏王，而不断地恳切求救于信陵君，这说明赵国只知道有信陵君，不知道还有个魏王呢。平原君用亲戚情分来激将信陵君，而信陵君也自己为了亲戚的原故，想急于救赵，这说明信陵君只知道有自己的亲戚，不知道还有个君王。他的盗窃兵符，不是为了魏国，不是为了六国，而是为了赵国才如此；其实也不是为了赵国，只是为了一个平原君罢了。假使祸患不在赵国，而在其他国家，即使撤销了魏国的屏障，撤销了六国的屏障，信陵君也必然不会去救他的。假使赵国没有平原君，或者平原君不是信陵君的亲戚，纵然赵国亡了，信陵君也必然不会救他的。这就是说赵王及其国家的轻重，不能比得上一个平原公子；而且魏国的军备原是依靠它来巩固自己的国家的，如今却拿来供信陵君的一个亲戚使用了。幸而战胜了，还算是可以的；如果不幸而战不胜，做了秦国的俘虏，就是倾覆了魏国几百年来的国家命运来殉葬于自己的亲戚。如果这样，我不知道信陵君用什么来回答魏王呢？！
盗窃兵符的计谋，那是出自侯生，而由如姬来完成的。侯生教魏公子来盗窃兵符，如姬在魏王卧室里替魏公子盗窃兵符，是这两个人也只知道有信陵君，而不知道有魏王啊。我认为信陵君如果为自己打算，不如用赵、魏两国唇齿相依的形势，以激发、上谏魏王，如果不听，就用他本人的想为赵国而牺牲于秦国军中的心愿，而死在魏王面前，魏王也就必然会醒悟了。侯生为信陵君打算，不如朝见魏王来劝说他救赵，如果不听，就以想为信陵君而死的心愿，死在魏王面前，魏王也必然醒悟了。如姬既有意于报答信陵君，不如乘魏王的空闲时，日日夜夜劝他救赵，如果不听从，就用想为公子而死的心愿，而死在魏王面前，魏王也必然醒悟了。这样做，就使信陵君不辜负魏国，也不辜负赵国；侯生等二人不辜负魏王，也不辜负信陵君。为什么不提出这种计划呢？信陵君只知道有做为亲戚的赵国，不知道有魏王；里边则有宠幸的侍妾，外边则有邻国，低贱者则有像夷门监侯生等乡野之人，又是都只知道有个魏公子，却不知道还有位君王。这就是魏国仅仅有一个孤立的君王罢了。
啊！自从世运衰败以来，人们都习惯于违背公益而甘心死于私党的行为，却忘掉了守节义而奉公的道理。于是就形成只有重要的宰相而没有具有权威的君王，只有私仇而没有义愤的局面。例如秦国人只知道有穰侯魏冉，而不知道有秦王；虞卿只知道贫贱时的老朋友，而不知道有赵王。这乃是君王好像旗子一样地被人把持着已经很久很久了。由此说来，信陵君的罪过，原不在于兵符的盗窃与否，若是为了魏国，为了六国，纵然是盗窃兵符，还是可以的；若是为了赵国，为了一个亲戚，纵然请求魏王，并且公然得到了它，也是有罪过的。虽是如此，魏王也不得以为是没有罪过的。兵符既藏在卧室之内，信陵君怎么能盗窃了呢？信陵君不害怕魏王，而居然直接请托如姬，这是他平日已看到魏王的疏忽了。如姬不害怕魏王，而敢于盗窃兵符，这是她素来仗恃着魏王的宠爱。木头枯朽了，然后蛀虫就生出来了。古代的君王手握重权，而宫廷内外没有敢不肃敬的，那么信陵君怎能建立私交于赵国呢？赵国怎能私下求救于信陵君呢？如姬怎能承受信陵君的恩惠呢？信陵君怎能施卖恩德于如姬呢？《周易》的所谓“履霜，坚冰至”（踩着路上的寒霜，就意味着坚固的冰块将要出现了）的逐渐形成的道理，难道说“一朝一夕”就会突然发生的吗？由此说来，不只是众人不知道有魏王，连魏王也自以为是个被把持着的旗子呢。
因此，信陵君可以做为人臣结党营私的鉴戒，魏王可以做为人君失权的鉴戒。从《春秋》的书写“葬原仲”和“翚帅师”的笔法来看，哦，圣人考虑得是多么深远啊！', NULL, '', 'indent', 1523289038, '5acb1b4cee920a2bc7eece23', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (638379, '杏花天', NULL, 0, 15, 0, 1, '江开', NULL, 20000, '5858ee0cb123db00658dbaeb', '清', 'ci', '词', '', '', '谢娘庭院通芳径。四无人、花梢转影。几番心事无凭准。等得青春过尽。
秋千下、佳期又近。算毕竟、沉吟未稳。不成又是教人恨。待倩杨花去问。 ', '', '', '', NULL, '', 'indent', 1532519012, '5b57f1ed9f5454003c08b27e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637075, '青霞先生文集序', NULL, 5, 8, 0, 1, '茅坤', NULL, 15580, '5858ea29ac502e0067085f94', '明', 'wen', '文', 'https://baike.baidu.com/item/%E9%9D%92%E9%9C%9E%E5%85%88%E7%94%9F%E6%96%87%E9%9B%86%E5%BA%8F/7543708?fr=aladdin', '', '青霞沈君，由锦衣经历上书诋宰执，宰执深疾之。方力构其罪，赖明天子仁圣，特薄其谴，徙之塞上。当是时，君之直谏之名满天下。已而，君纍然携妻子，出家塞上。会北敌数内犯，而帅府以下，束手闭垒，以恣敌之出没，不及飞一镞以相抗。甚且及敌之退，则割中土之战没者与野行者之馘以为功。而父之哭其子，妻之哭其夫，兄之哭其弟者，往往而是，无所控吁。君既上愤疆埸之日弛，而又下痛诸将士之日菅刈我人民以蒙国家也，数呜咽欷歔；，而以其所忧郁发之于诗歌文章，以泄其怀，即集中所载诸什是也。
君故以直谏为重于时，而其所著为诗歌文章，又多所讥刺，稍稍传播，上下震恐。始出死力相煽构，而君之祸作矣。君既没，而中朝之士虽不敢讼其事，而一时阃寄所相与谗君者，寻且坐罪罢去。又未几，故宰执之仇君者亦报罢。而君之故人俞君，于是裒辑其生平所著若干卷，刻而传之。而其子襄，来请予序之首简。
茅子受读而题之曰：若君者，非古之志士之遗乎哉？孔子删《诗》，自《小弁》之怨亲，《巷伯》之刺谗而下，其间忠臣、寡妇、幽人、怼士之什，并列之为“风”，疏之为“雅”，不可胜数。岂皆古之中声也哉？然孔子不遽遗之者，特悯其人，矜其志。犹曰“发乎情，止乎礼义”，“言之者无罪，闻之者足以为戒”焉耳。予尝按次春秋以来，屈原之《骚》疑于怨，伍胥之谏疑于胁，贾谊之《疏》疑于激，叔夜之诗疑于愤，刘蕡之对疑于亢。然推孔子删《诗》之旨而裒次之，当亦未必无录之者。君既没，而海内之荐绅大夫，至今言及君，无不酸鼻而流涕。呜呼！集中所载《鸣剑》、《筹边》诸什，试令后之人读之，其足以寒贼臣之胆，而跃塞垣战士之马，而作之忾也，固矣！他日国家采风者之使出而览观焉，其能遗之也乎？予谨识之。
至于文词之工不工，及当古作者之旨与否，非所以论君之大者也，予故不著。嘉靖癸亥孟春望日归安茅坤拜手序。', '《青霞先生文集序》，明代散文，作者茅坤，出自《青霞集》。青霞先生是指沈炼，因为弹劾奸臣严嵩而被杀害，因此受到天下士人推崇，将他的作品汇编成《青霞先生文集》，这篇文章是茅坤为该文集撰写的序言。', '馘（guó）：被杀者的左耳。古时作战凭割取敌人的左耳来计功。
菅（jiān）刈：割草。菅：草名。这里指像割草一样残害百姓。蒙：欺骗。
诸什：诸篇。
阃（kǔn）寄：统兵在外的人。阃：特指部门的门槛；寄：托付。
寻：不久。坐：因。
裒（póu）辑：搜集、编辑。裒：聚。
《小弁》：《诗·小雅》篇名。相传为西周末年，周丞王听信宠妃褒姒的谗言，废掉太子宜臼。宜臼被废后，作《小弁》诗，抒发自己被弃逐以后的忧怨。
《巷伯》：《诗·小雅》篇名。相传巷伯被谗而受宫刑，气愤之下作此诗。
遽遗：骤然删除。
屈原之骚：屈原，名平，战国时楚国贵族。辅佐楚怀王。后受贵族子兰、靳尚等人谗毁，被放逐。“骚”即屈原所作的《离骚》，抒写他的理想抱负和这种抱负不能实现的悲愤心情。
伍胥之谏：伍胥，即伍子胥。春秋时吴国大夫。谏：指劝吴王拒绝越王勾践的求和，并停止伐齐，被夫差赐死。
贾谊之疏：贾谊，西汉初期杰出的文学家、政论家。他曾多次上疏批评时政，建议削弱诸侯王势力。后受排挤被贬，不久抑郁而死。
叔夜之诗：指嵇康的《幽愤诗》。嵇康，字叔夜。魏晋之际的文学家、思想家、音乐家。因不满司马氏集团，被司马昭所杀。《幽愤诗》是嵇康被捕后在狱中写的。
刘蕡（fen）之对：刘蕡，唐代人。文宗（李昂）时应贤良对策，激昂慷慨，怒斥宦官罪行而被黜落。对：指刘蕡所上对策。
荐绅：同“绅”，本指古代官员的一种装束，这里代指官员。
识（zhi）之：记下这篇序。识：记。', '青霞沈炼君，以锦衣卫经历的身份向皇帝上书斥责宰相。宰相因此非常忌恨他，正当宰相要极力罗织罪名陷害他时，幸亏皇帝仁慈圣明，特地减轻他的罪罚，只把他贬谪到塞上。当时，沈君直谏的声名传遍天下。不久，沈君满怀郁懑，携带家小，迁居塞上。正逢北方的敌人多次侵犯内地，而帅府以下的各级官员都束手无策，关闭城垒，任由敌人往来出没，连向敌人发一支箭来抵抗都做不到。甚至等到敌人退走以后，他们就割下在战争中阵亡的中原士兵和在郊野中赶路的人的耳朵来当作军功。而百姓中父亲哭儿子、妻子哭丈夫、哥哥哭弟弟的，到处都是，怨愤之情无处可诉。沈君既对上愤慨于边疆防务的日益懈怠，对下又痛心于将士们肆意残害百姓、欺骗国家。他多少次为之哭泣哀叹，于是就将他满腔郁愤表现在诗歌文章中，从而抒发他的情怀，文集中所载录的各篇就是他这类的作品。
沈君本来就因为敢于直谏而为当世人所敬重，而他所作诗文又多所讥刺，稍一传播，上下都感到震惊恐慌，于是他们就竭力造谣、陷害，而大祸也就落到了沈君头上。沈君遇害之后，那些曾身居军中要职、一同陷害沈君的人，不久也都因罪被罢官。又不久，过去仇视沈君的宰相也被罢官。而沈君的门人、给事中兼谏议大夫俞君，就搜集编纂了沈君生前的著述若干卷，并加以刊刻流传。沈君的儿子沈以敬，来请我为文集作这篇序文。
我拜读了沈君文集后，题写道：像沈君这样的人，难道不就是古代那些志行高尚的一类人吗？孔子删定《诗经》，从怨恨亲人的《小弁》、讽刺奸谗的《巷伯》以下，那些忠臣、寡妇、隐居之士、愤世嫉俗者的作品，一概被列入“国风”，并入“小雅”，这样的作品不可胜数。难道这些都是古代的合乎音律的诗歌吗？然而孔子之所以不轻易删掉它们，只是怜悯那些受谗害的人，彰显他们的志向，他还说过“这些诗歌都是发自真情实感，都合乎礼义的要求”，“说话的人没有罪，听的人完全可以把它作为借鉴”。我曾依次考察了自《春秋》以来的作品，发现屈原的《离骚》好像是在发泄怨恨，伍子胥的劝谏像是在进行威胁，贾谊的奏疏很激切，叔夜的诗歌又像是在抒发愤恨，刘蕡的对策像是在表现亢直的个性。然而按照孔子删定《诗经》的原则而收集、编辑它们，应该是未必没有值得收录的。沈君虽然已经作古，然而海内的官员大夫们，直至今日谈到他，没有一个不感到酸涩流泪的。唉！文集中所载的《鸣剑》、《筹边》等篇，假使让后人读了，那么它们完全可以使奸臣胆寒心折，令守边将士战马腾跃，振奋起同仇敌忾的义愤，这是必然的。今后，国家负责采诗的官员看到这些诗篇，难道会把它们给遗漏掉吗？在此，我怀着一片恭谨之情记在这里。
至于说到文采词藻精工还是不精工，以及是否符合古代作家的题旨，这些都不是能够说明沈君大节的东西，所以在这里我就不再论述了。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed205d635634aee3eab81", "shortContent": "有明一代，在中国封建社会中，政治上是最腐朽的朝代。大约从明成祖时，就开始了宦官干预朝政，后来逐渐发展到宦官专权专政的局面。权柄既归内竖，而朝中怀奸固宠之徒，便依附结纳，以致祸流搢绅。唯世宗朝阉宦敛迹，而严嵩父子济恶，流毒天下，人咸指目为奸臣。另一方面，也出现了不少与这些巨奸大恶作斗争的忠臣义士。仅以对严嵩的斗争来说，先后抗疏揭露其罪恶的，仅《明史》举其著者，就不下一二十人，而他们的结果差不多都是很...", "authors": ["邱鸣皋"], "pressName": "上海辞书出版社"}]', '', 'indent', 1523289309, '5acb1c5c2f301e0ef508b22d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637077, '西岳云台歌送丹丘子', NULL, 1, 1052, 0, 1, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'https://baike.baidu.com/item/%E8%A5%BF%E5%B2%B3%E4%BA%91%E5%8F%B0%E6%AD%8C%E9%80%81%E4%B8%B9%E4%B8%98%E5%AD%90/3279054?fr=aladdin', '', '西岳峥嵘何壮哉，黄河如丝天际来。
黄河万里触山动，盘涡毂转秦地雷。
荣光休气纷五彩，千年一清圣人在。
巨灵咆哮擘两山，洪波喷箭射东海。
三峰却立如欲摧，翠崖丹谷高掌开。
白帝金精运元气，石作莲花云作台。
云台阁道连窈冥，中有不死丹丘生。
明星玉女备洒扫，麻姑搔背指爪轻。
我皇手把天地户，丹丘谈天与天语。
九重出入生光辉，东来蓬莱复西归。
玉浆傥惠故人饮，骑二茅龙上天飞。', '《西岳云台歌送丹丘子》是唐代伟大诗人李白写给友人元丹丘的一首歌行诗。这首诗吟颂的是黄河中游峡谷段的壮观景色，貌似游仙诗，实则咏物抒怀。全诗以浪漫的笔法，将奇伟的山水和优美的神话巧妙结合，加以丰富多姿的想象，把华山、黄河描绘得气象万千，雄伟无比，由此抒写大河奔腾之壮丽豪情，高山仰止之真实情感，创造出奇幻飘逸的境界，全篇充盈着浪漫气息。', '西岳：即华山，亦名太华山。在今陕西华阴县南，黄河在其北二十里，在山上望中可见。《尔雅·释山》：“华山为西岳。”云台，华山北峰，此峰上冠景云，下通地脉，形如楼台，上耸入云。丹丘子，即元丹丘，又称丹丘生、元丹子，李白于安陆时所结识的一位道友，于颜阳、嵩山、石门山等处都有别业，曾为胡紫阳弟子，与玉真公主关系密切，并与玉真公王一道向唐玄宗推荐召李白入京。
峥嵘：高峻貌。
黄河如丝：据《华山记》所载，从华山的落雁峰“俯眺三秦，旷莽无际。黄河如一缕水，缭绕岳下”。
盘涡毂（gǔ）转：车轮中间车轴贯入处的圆木。这里形容水波急流，盘旋如轮转。《文选》郭璞《江赋》：盘涡毂转，凌涛山颓。李善注：涡，水旋流也。张铣注：盘涡，言水深风壮，流急相冲，盘旋作深涡，如毂之转。
荣光休气：形容河水在阳光下所呈现的光彩，仿佛一片祥瑞的气象。王琦注引《尚书中候》：尧即政七十载，修坛河、洛。荣光出河，休气四塞。郑玄注：荣光，五色，从河水中出。休，美也。
千年一清：黄河多挟泥沙而下，少有清时，古代以河清为祥瑞的象征，也以河清称颂清明的治世。晋王嘉《拾遗记》：黄河千年一清，至圣之君以为大瑞。圣人：指当时的皇帝唐玄宗。
“巨灵”二句：据《水经注·河水》引古语：“华岳本一山，当河，河水过而曲行。河神巨灵，手荡脚踏，开而为两，今掌足之迹，仍存华岩。”擘（bò）：剖开。箭：一作“流”。
三峰：指东峰朝阳峰、南峰落雁峰、西峰莲花峰。
高掌：即仙人掌，华山山峰名。王琦曰：山之东北为仙人掌，即所谓巨灵掌也。
白帝：神话中的五天帝之一，是西方之神。华山是西岳，故属白帝。道家以西方属金，故称白帝为西方之金精。慎蒙《名山诸胜一览记》：“李白诗‘石作莲花云作台’，今观山形，外罗诸山如莲瓣，中间三峰特出如莲心，其下如云台峰，自远望之，宛如青色莲花，开于云台之上也。”元气：中国古代思想家认为形成世界最元始的东西是元气，无形状可言，天地万物都由元气而生。
“石作”句：王琦注引《名山记》：李白诗“石作莲花云作台”，近观山形外罗诸山如莲瓣，中间三峰特出如莲心，其下为云台峰，自远望之，宛如青色莲花开于云台之上也。
阁道：即栈道。山路险阻，凿石架木以通行的道路。窈冥：高深不可测之处。连窈冥：一作“人不到”。
明星玉女：仙女名，据说她们住在华山上，服玉浆，白日升天。
麻姑：神话中的人物，传说为建昌人，东汉桓帝时应王方平之邀，降于蔡经家，年约十八九岁，能掷米成珠。自言曾见东海三次变为桑田。据《神仙传》说她的手像鸟爪，蔡经曾想象，用它来搔背一定很好。
我皇：指天帝。把：把持、主宰。天地户：天地之门户。《汉武帝内传》：王母命侍女法安婴歌《元灵之曲》，曰：“天地虽寥廓，我把天地户。”
谈天：即言天地之道也。战国时齐人邹衍喜欢谈论宇宙之事，人称他是“谈天衍”。与天语：与皇帝谈话。此处之“天”字，指天子、皇帝。
九重：天的极高处。一说天子之门九重，此指天子居处，即皇宫。光辉：荣耀。
东求蓬莱：即求仙也。蓬莱，东海中有蓬莱仙岛。西归，西入长安也。
玉浆：仙人所饮之浆。惠：赠也。故人：李白自指。
茅龙：据《列仙传》说，仙人使卜师呼子先与酒家妪骑二茅狗，变成飞龙，升天成仙。', '西岳华山是何等的高峻雄伟，站在云台上北望，只见黄河像游丝一样从天际蜿蜒而来。黄河奔腾万里，浪涛冲击着华山，漩涡像车轮般地转动，发出山摇地动的声音，像巨雷一样在秦川大地上回响。黄河的上空笼罩着五色云气，千年一清，圣人即将出矣。河神巨灵大吼一声，将首阳山和华山劈开，让黄河之水喷流而过，直射东海。而华山三峰，后退欲倒，在高高的崖月谷之上，留下了巨灵神的掌印。西天的金精白帝，运作元气，将华山西峰化作莲花，北峰化作云台。云台阁道层层直通幽冥，山中有位不死的神仙叫丹丘生。明星玉女为他清洁洒扫，神仙麻姑为他轻轻地搔背。吾皇御驭天下，手把天地之门户，邀丹丘子共谈天地之至道。丹丘子将从蓬莱西归京师，出入于九重之中，沐浴着圣上的光辉。倘若丹丘子的玉浆能赐故人一饮的话，我将与您一起骑上二茅龙上天而飞。', NULL, '《唐宋诗醇》：健笔凌云，一扫靡靡之调。
《老生常谈》：太白《西岳云台歌送丹丘子》中云：「云台阁道连窈冥，中有不死丹丘生。明星玉女备洒扫，麻姑搔背指爪轻。」下接仄韵云：「我皇手把天地户，丹丘谈天与天语。」每于转韵处，棱角峭厉，令人耳目顿觉醒豁。学者要从此种寻去，方有途径可通，若但貌袭其起句「石作莲花云作台」，便是钝汉。
《昭味詹言》：「中有不死」句入题。
《王闿运手批唐诗选》：只是实赋，便成奇语（「白帝金精」二句下）。
《李太白诗醇》：实叙而伟丽，自是仙笔（「三峰却立」四句下）。句句有仙气（「我皇手把」二句下）。', 'center', 1541088039, '5acb236b9f5454051ccd7ae5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637094, '荀子 · 天论篇', NULL, 29, 13, 2, 1, '荀子', NULL, 10279, '57b902bbdf0eea006334f0d0', '周', 'wen', '文', '', '', '天行有常，不为尧存，不为桀亡。应之以治则吉，应之以乱则凶。强本而节用，则天不能贫；养备而动时，则天不能病；修道而不贰，则天不能祸。故水旱不能使之饥，寒暑不能使之疾，祆怪不能使之凶。本荒而用侈，则天不能使之富；养略而动罕，则天不能使之全；倍道而妄行，则天不能使之吉。故水旱未至而饥，寒暑未薄而疾，祆怪未至而凶。受时与治世同，而殃祸与治世异，不可以怨天，其道然也。故明于天人之分，则可谓至人矣。
不为而成，不求而得，夫是之谓天职。如是者，虽深、其人不加虑焉；虽大、不加能焉；虽精、不加察焉，夫是之谓不与天争职。天有其时，地有其财，人有其治，夫是之谓能参。舍其所以参，而愿其所参，则惑矣。
列星随旋，日月递照，四时代御，阴阳大化，风雨博施，万物各得其和以生，各得其养以成，不见其事，而见其功，夫是之谓神。皆知其所以成，莫知其无形，夫是之谓天功。唯圣人为不求知天。
天职既立，天功既成，形具而神生，好恶喜怒哀乐臧焉，夫是之谓天情。耳目鼻口形能各有接而不相能也，夫是之谓天官。心居中虚，以治五官，夫是之谓天君。财非其类以养其类，夫是之谓天养。顺其类者谓之福，逆其类者谓之祸，夫是之谓天政。暗其天君，乱其天官，弃其天养，逆其天政，背其天情，以丧天功，夫是之谓大凶。圣人清其天君，正其天官，备其天养，顺其天政，养其天情，以全其天功。如是，则知其所为，知其所不为矣；则天地官而万物役矣。其行曲治，其养曲适，其生不伤，夫是之谓知天。
故大巧在所不为，大智在所不虑。所志于天者，已其见象之可以期者矣；所志于地者，已其见宜之可以息者矣：所志于四时者，已其见数之可以事者矣；所志于阴阳者，已其见和之可以治者矣。官人守天，而自为守道也。
治乱，天邪？曰：日月星辰瑞历，是禹桀之所同也，禹以治，桀以乱；治乱非天也。
时邪？曰：繁启蕃长于春夏，畜积收臧于秋冬，是禹桀之所同也，禹以治，桀以乱；治乱非时也。
地邪？曰：得地则生，失地则死，是又禹桀之所同也，禹以治，桀以乱；治乱非地也。诗曰：“天作高山，大王荒之。彼作矣，文王康之。”此之谓也。
天不为人之恶寒也辍冬，地不为人之恶辽远也辍广，君子不为小人之匈匈也辍行。天有常道矣，地有常数矣，君子有常体矣。君子道其常，而小人计其功。诗曰：“礼义之不愆，何恤人之言兮！”此之谓也。
楚王后车千乘，非知也；君子啜菽饮水，非愚也；是节然也。若夫志意修，德行厚，知虑明，生于今而志乎古，则是其在我者也。故君子敬其在己者，而不慕其在天者；小人错其在己者，而慕其在天者。君子敬其在己者，而不慕其在天者，是以日进也；小人错其在己者，而慕其在天者，是以日退也。故君子之所以日进，与小人之所以日退，一也。君子小人之所以相县者，在此耳。
星坠木鸣，国人皆恐。曰：是何也？曰：无何也！是天地之变，阴阳之化，物之罕至者也。怪之，可也；而畏之，非也。夫日月之有蚀，风雨之不时，怪星之党见，是无世而不常有之。上明而政平，则是虽并世起，无伤也；上闇而政险，则是虽无一至者，无益也。夫星之坠，木之鸣，是天地之变，阴阳之化，物之罕至者也；怪之，可也；而畏之，非也。
物之已至者，人祆则可畏也：楛耕伤稼，楛耨失岁，政险失民；田薉稼恶，籴贵民饥，道路有死人：夫是之谓人祆。政令不明，举错不时，本事不理，夫是之谓人祆。礼义不修，内外无别，男女淫乱，则父子相疑，上下乖离，寇难并至：夫是之谓人祆。祆是生于乱。三者错，无安国。其说甚尔，其菑甚惨。勉力不时，则牛马相生，六畜作祆，可怪也，而亦可畏也。传曰：“万物之怪书不说。”无用之辩，不急之察，弃而不治。若夫君臣之义，父子之亲，夫妇之别，则日切瑳而不舍也。
雩而雨，何也？曰：无何也，犹不雩而雨也。日月食而救之，天旱而雩，卜筮然后决大事，非以为得求也，以文之也。故君子以为文，而百姓以为神。以为文则吉，以为神则凶也。
在天者莫明于日月，在地者莫明于水火，在物者莫明于珠玉，在人者莫明于礼义。故日月不高，则光明不赫；水火不积，则晖润不博；珠玉不睹乎外，则王公不以为宝；礼义不加于国家，则功名不白。故人之命在天，国之命在礼。君人者，隆礼尊贤而王，重法爱民而霸，好利多诈而危，权谋倾覆幽险而亡矣。
大天而思之，孰与物畜而制之！从天而颂之，孰与制天命而用之！望时而待之，孰与应时而使之！因物而多之，孰与骋能而化之！思物而物之，孰与理物而勿失之也！愿于物之所以生，孰与有物之所以成！故错人而思天，则失万物之情。
百王之无变，足以为道贯。一废一起，应之以贯，理贯不乱。不知贯，不知应变。贯之大体未尝亡也。乱生其差，治尽其详。故道之所善，中则可从，畸则不可为，匿则大惑。水行者表深，表不明则陷。治民者表道，表不明则乱。礼者，表也。非礼，昏世也；昏世，大乱也。故道无不明，外内异表，隐显有常，民陷乃去。
万物为道一偏，一物为万物一偏。愚者为一物一偏，而自以为知道，无知也。慎子有见于后，无见于先。老子有见于诎，无见于信。墨子有见于齐，无见于畸。宋子有见于少，无见于多。有后而无先，则群众无门。有诎而无信，则贵贱不分。有齐而无畸，则政令不施，有少而无多，则群众不化。书曰：“无有作好，遵王之道；无有作恶，遵王之路。”此之谓也。', '', '', '大自然的规律永恒不变，它不为尧而存在，不为桀而灭亡。用导致安定的措施去适应它就吉利，用导致混乱的措施去适应它就凶险。加强农业这个根本而节约费用，那么天就不能使他贫穷；衣食给养齐备而活动适时，那么天就不能使他生病；遵循规律而不出差错，那么天就不能使他遭殃。所以水涝旱灾不能使他挨饿，严寒酷暑不能使他生病，自然界的反常变异不能使他遭殃。农业这个根本荒废而用度奢侈，那么天就不能使他富裕；衣食给养不足而活动又少，那么天就不能使他保全健康；违背规律而恣意妄为，那么天就不能使他吉利。所以水涝旱灾还没有来到他就挨饿了，严寒酷暑还没有迫近他就生病了，自然界的反常变异还没有出现他就遭殃了。他遇到的天时和社会安定时期相同，而灾祸却与社会安定时期不同，这不可以埋怨上天，这是他所采取的措施造成的。所以明白了大自然与人类社会的区分，就可以称作是思想修养达到了最高境界的人了。
不做就能成功，不求就能得到，这叫做自然的职能。像这种情况，即使意义深远，那思想修养达到了最高境界的人对它也不加以思考；即使影响广大，那思想修养达到了最高境界的人对它也不加以干预；即使道理精妙，那思想修养达到了最高境界的人对它也不加以审察，这叫做不和自然争职能。上天有自己的时令季节，大地有自己的材料资源，人类有自己的治理方法，这叫做能够互相并列。人如果舍弃了自身用来与天、地相并列的治理方法，而只期望于与自己相并列的天、地，那就糊涂了。
布列于天空的恒星互相伴随着旋转，太阳月亮交替照耀，四季轮流控制着节气，阴阳二气大量地化生万物，风雨普遍地施加于万物。万物各自得到了阴阳形成的和气而产生，各自得到了风雨的滋养而成长。看不见阴阳化生万物的工作过程而只见到它化生万物的成果，这就叫做神妙。人们都知道阴阳已经生成的万物，却没有人知道它那无形无踪的生成过程，这就叫做天。只有圣人是不致力于了解天的。
自然的职能已经确立，天生的功绩已经成就，人的形体也就具备而精神也就产生了，爱好与厌恶、高兴与愤怒、悲哀与欢乐等蕴藏在人的形体和精神里面，这些叫做天生的情感。耳朵、眼睛、鼻子、嘴巴、身体，就其功能来说，它们各有自己的感受对象而不能互相替代，这些叫做天生的感官。心处于身体中部空虚的胸腔内，用来管理这五种感官，这叫做天生的主宰。人类能够控制安排好与自己不是同类的万物，用它们来供养自己的同类，这叫做天然的供养。能使自己的同类顺从自己叫做福，使自己的同类反对自己叫做祸，这叫做天然的政治原则。搞昏了那天生的主宰，扰乱了那天生的感官，抛弃了那天然的供养，违反了那天然的政治原则，背离了那天生的情感，以致丧失了天生的功绩，这叫做大凶。圣人清醒自己那天生的主宰，管理好自己那天生的感官，完备那天然的供养，顺应那天然的政治原则，保养那天生的情感，从而成全了天生的功绩。像这样，就是明白了自己应该做的事了、明白了自己不应该做的事了，天地就能被利用而万物就能被操纵了，他的行动就能处处有条理，他的保养就能处处恰当，他的生命就能不受伤害，这就叫做了解了天。
所以最大的技巧在于有些事情不去做，最大的智慧在于有些事情不去考虑。对于上天所要了解的，不过是它所显现的天象中那些可以测定气候变化的天文资料罢了；对于大地所要了解的，不过是它所显现的适宜条件中那些可以便利种植庄稼的地文资料罢了；对于四季所要了解的，不过是它们所显现的规律中可以安排农业生产的节气罢了；对于阴阳所要了解的，不过是它们所显现的和气中可以治理事物的因素罢了。圣人任用别人来掌握这些自然现象而自己所做的只是去掌握治理国家的原则。
社会的安定或混乱，是由上天决定的吗？回答说：太阳月亮、行星恒星、祥瑞的历书，这在禹与桀是相同的；禹使天下安定，桀使天下混乱；可见社会的安定或混乱并不是由上天决定的。那么，是季节造成的吗？回答说：庄稼在春季、夏季纷纷发芽、茂盛地生长，在秋季、冬季积蓄、收藏，这在禹与桀又是相同的；禹使天下安定，桀使天下混乱；可见社会的安定或混乱并不是季节造成的。那么，是大地造成的吗？回答说：庄稼得到了大地就生长，失去了大地就死亡，这在禹与桀又是相同的；禹使天下安定，桀使天下混乱；可见社会的安定或混乱并不是大地造成的。《诗》云：“天生高大的岐山，太王使它大发展；太王已经造此都，文王使它长平安。”说的就是这个道理。
上天并不因为人们厌恶寒冷就取消冬季，大地并不因为人们厌恶辽远就废除宽广，君子并不因为小人的叽里呱啦就中止行动。上天有经久不变的规律，大地有经久不变的法则，君子有经久不变的规矩。君子遵行那常规，而小人计较那功利。《诗》云：“礼义上我错误不犯，何必担忧人说长道短？”说的就是这个道理。
楚王外出时随从的车子有上千辆，并不是因为他聪明；君子吃豆叶、喝白水，并不是因为他愚蠢；这种情况是时势命运的制约造成的。至于思想美好，德行敦厚，谋虑精明，生在今天而能知道古代，这些就是那取决于我们自己的事情了。所以，君子慎重地对待那些取决于自己的事情，而不去羡慕那些取决于上天的东西；小人丢下那些取决于自己的事情，而指望那些取决于上天的东西。君子慎重对待那些取决于自己的事情，而不去羡慕那些取决于上天的东西，因此天天进步；小人丢下那些取决于自己。的事情，而指望那些取决于上天的东西，因此天天退步。所以君子天天进步的原因与小人天天退步的原因，道理是一样的。君子、小人相差悬殊的原因，就在这里。
流星坠落、树木发响，国内的人都害怕，说：这是为什么呢？回答说：这没有什么啊。这是自然界的变异、阴阳二气的变化、事物中很少出现的现象啊。觉得它奇怪，是可以的；但害怕它，就错了。那太阳、月亮发生日食、月食，旋风暴雨不合时节地突然袭击，奇怪的星星偶然出现，这些现象没有哪个时代不曾有过。君主英明而政治清明，那么这些现象即使在同一时代都出现，也没有什么妨害；君主愚昧而政治黑暗，那么这些现象即使一样都没出现，也毫无裨益。那流星的坠落、树木的发响，这是自然界的变异、阴阳二气的变化、事物中很少出现的现象啊。觉得它奇怪，是可以的；但害怕它，就错了。
在已经出现的事情中，人事上的反常现象才是可怕的。粗放地耕种而伤害了庄稼，粗放地锄草而妨害了年成，政治险恶而失去了民心，田地荒芜而庄稼长不好，米价昂贵而百姓挨饿，道路上有饿死的人，这些叫做人事上的反常现象；政策法令不明确，采取措施不合时宜，具有根本意义的农业生产不加管理，发动劳役不顾农时，那么牛就会生出像马似的怪胎、马就会生出像牛似的怪胎，六畜就会出现怪异的现象，这些叫做人事上的反常现象；礼义不加整顿，内外没有分别，男女淫荡混乱，而父子互相猜疑，君臣离心离德，外寇内乱同时到来，这叫做人事上的反常现象。人事上的反常现象实产生于昏乱。上述这三类反常现象交错发生，就不会有安宁的国家了。这种人事上的反常现象解说起来道理很浅显，但它造成的灾难却很惨重。这是可怕的，但不值得奇怪。古代解释经文的书上说：“各种事物的怪现象，经书上不作解说。”没有用处的辩说，不是急需的明察，应该抛弃而不加研究。至于那君臣之间的道义，父子之间的相亲，夫妻之间的区别，那是应该每天切磋琢磨而不能丢掉的啊。
祭神求雨而得雨，为什么呢？回答说：这没有什么，即便不祭神求雨而照样下雨。发生了日食、月食而能营救它们，天气干旱了就祭神求雨，占卜算卦然后决定大事，古人并不是认为这些做法能得到所祈求的东西，而只是用它们来文饰政事罢了。所以君子把这些活动看作为一种文饰活动，但老百姓却把它们看得神乎其神。认为这是一种宣传形式是好事，把它们看得神乎其神就不是件好事了。
在天上的东西没有什么比太阳、月亮更明亮的了，在地上的东西没有什么比水、火更明亮的了，在物品之中没有什么比珍珠、宝玉更明亮的了，在人类社会中没有什么比礼义更灿烂的了。太阳、月亮如果不高挂空中，那么它们的光辉就不显著；水、火如果不积聚，那么火的光辉、水的光泽就不大；珍珠，宝玉的光彩不显露于外，那么天子、诸侯就不会把它们当作宝贝，礼义不在国内施行，那么功业和名声就不会显著。所以人的命运在天，国家的命运在礼义。统治人民的君主，推崇礼义、尊重贤人，就能称王天下；注重法治、爱护人民，就能称霸诸侯，喜欢财利、多搞欺诈，就会危险；玩弄权术、坑人害人、阴暗险恶，那就会彻底灭亡了。
认为大自然伟大而思慕它，哪里及得上把它当作物资积蓄起来而控制它？顺从自然而颂扬它，哪里及得上掌握自然规律而利用它？盼望时令而等待它，哪里及得上因时制宜而使它为我所用？依靠万物的自然增殖，哪里及得上施展人的才能而使它们根据人的需要来变化？思慕万物而把它们当作与己无关的外物，哪里及得上管理好万物而不失去它们？希望了解万物产生的原因，哪里及得上占有那已经生成的万物？所以放弃了人的努力而寄希望于天，那就违背了万物的实际情况。
各代帝王都没有改变的东西，完全可以用来作为政治原则的常规惯例。国家有时衰微有时兴盛，但君主都凭这种常规惯例去应付它。治理好这种常规惯例，国家就不会混乱。如果不了解这种常规惯例，就不知道如何应付变化。这种常规惯例的主要内容从来没有消失过。社会的混乱，产生于这常规惯例的实施出了差错；社会安定，全在于这种常规惯例的实施十分周详。所以，政治原则中那些被一般人看作为好的东西，如果符合这种常规惯例，就可以依从；如果偏离了这种常规惯例，就不可以实行；如果违反了这种常规惯例，就会造成极大的迷惑。在水中跋涉的人用标志来表明深度，如果这种标志不明确，就会使人陷入深水淹死；治理民众的君主用标准来表明政治原则，如果这种标准不明确，就会造成混乱。礼制就是治理民众的标准。违反了礼制，就是昏暗的社会；昏暗的社会，就会大乱。所以，政治原则没有照不亮的地方，它对外对内都有不同的标准，对隐蔽之事或显露之事都有永久不变的规定，那么民众的陷阱就可以除去了。
万事万物只体现了自然规律的一部分，某一种事物只是万事万物的一部分，愚昧的人只认识了某一种事物的一个方面，就自以为知道了自然规律，实在是无知。慎子对在后服从的一面有所认识，但对在前引导的一面却毫无认识；老子对委曲忍让的一面有所认识，但对积极进取的一面却毫无认识；墨子对齐同平等的一面有所认识，但对等级差别的一面却毫无认识；宋子对寡欲的一面有所认识，但对多欲的一面却毫无认识。只在后服从而不在前引导，那么群众就没有继续前进的门径；只委曲忍让而不积极进取，那么高贵和卑贱就不会有分别；只有齐同平等而没有等级差别，那么政策法令就不能贯彻实施；只求寡欲而不见多欲，那么群众就不易被感化。《尚书》上说：“不要任凭个人的爱好，要遵循君主确定的正道；不要任凭个人的厌恶，要遵循君主确定的正路。”说的就是这个。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d203572034f65a9ac7", "shortContent": "《天论》是荀子的代表作之一，是他对古代朴素唯物主义哲学思想加以总结、发展而写成的一篇著名哲学论文，在历史上有着突出的成就和贡献。\n在他以前的许多著名思想家都提出过自己的自然哲学观。如孔子虽亦主张自然之天，但同时又相信天命，他提出“君子有三畏”，第一畏就是“畏天命”；老子、庄子虽然承认天就是自然，它没有意志，不能赏善罚恶，但是又认为人们应该听命于自然，主张无为而治，不知道、甚至不承认人能够掌握、征服...", "authors": ["卢", "元"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d22e6a6b501f968548", "shortContent": "荀子在致力于运用散文形式来阐述自己的政治主张、经济构想、哲学观点、教育思想等等之余，还继承了《诗》三百篇的优秀文学遗产，发扬光大，融合变化，创造了“赋”这种前所未有的优美的文学形式，对汉赋及以后的一些说理、状物小赋都有很大影响。\n据班固《汉书·艺文志》载：孙卿（即荀卿、荀况）赋十篇，并将它列在赋二十五家之首。可惜现存的只有《赋篇》中的六篇，其余均无从查考了。这六篇赋，依次为《礼赋》、《知赋》、《云...", "authors": ["卢", "元"], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3b4", "shortContent": "天人关系是中国古代哲学的一个重要命题。先秦时期，人们认为天和人一样，是有意识的，并主宰着人类的命运。到了荀子这里，天不再是人格神，只是独立于人类社会的自然的存在。而人类不能坐等天地的恩赐，被动地顺应自然，“从天而颂之，孰与制天命而用之？”（《天论》）加强农业生产，生活上勤俭节约，即使是上天也不能使他贫穷；丰衣足食又能顺时而动，那么上天也不能使他生病；专心不二地遵行礼义大道，上天也不能使他遭祸。\n\n...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3b5", "shortContent": "在浩瀚的天空中，众星相随旋转，太阳和月亮轮流将光辉洒向大地，春夏秋冬四季交替着出现。阴阳是古代哲学思想中的一个重要概念，在荀子的时代，阴阳可以指天地、寒暑、晦明、动静等具有对立属性的事物。阴阳的变化产生了丰富的自然现象，比如寒暑变化就有了春夏秋冬，晦明变化产生了白天黑夜，冷热空气交锋形成雨，高低气压碰撞产生风。有了风雨的广施博洒，万物才得以生存发展。“万物各得其和以生”，那么“和”是一种怎样的状态...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3b6", "shortContent": "天有其时，这里的天是指自然意义上的“天”———自然界。天上的日月星辰按照一定的规律运行：地球围绕太阳一周为一年，一年中又分成春夏秋冬四时；月亮绕地球一周是一月，一月分为三旬；地球自转一周为一日，一日有二十四小时，这就是天时。先民通过长期的观察和实践，根据太阳在黄道上的运行轨道制定了二十四节气用以指导农业生产，这是顺天时。任何植物都是按照四时顺序即春生夏长秋收冬藏生长的，对于这些规律，我们当然不能改...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3b7", "shortContent": "春秋战国时期，社会正酝酿着一场大变革，思想空前解放。此时私学兴起，打破了当时“学在官府”的限制，不再是只有王公贵族的子弟才有资格接受教育，各阶层的人都有机会接受教育，出现了大量“士”。而当时各诸侯国为了能够一统天下，积极地招贤纳士，希望借着他们的聪明才智增强自己国家的经济、军事等实力。诸侯们厚待士人，使他们衣食充足，创造了宽松的思想、学术氛围。“士”还可以“择良木而栖”，奔走于各个诸侯国之间宣传自...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3ba", "shortContent": "荀子说，擅长谈论古代事情的人必定会用今天的事情作为验证。对于荀子思想的研究，一直有着“法先王”和“法后王”之争。其实，不论是“法先王”还是“法后王”，荀子的落脚点只有一个，那就是当下。荀子在提到先王的时候总是和礼义联系在一起，效法的是先王传下来的“礼”，“法先王”是为了“以古持今”即继承从古代三王流传下来的礼义，并以此来治理现今的社会；“欲观圣王之迹，则于其粲然者矣，后王是也”（《非相》），后王行...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3bb", "shortContent": "荀子认为：“人之性恶，其善者伪也。”（《性恶》）其实，人的本性如“饥而欲饱，寒而欲暖，劳而欲休”（同上），并无所谓善恶，但若一味顺其性发展则必然会走向恶，而人之所以会表现出善良的一面，都是因为后天学习礼义的结果。荀子这里的“伪”并非“虚伪”的意思，而是作“人为”解。人即使有着优良的禀赋和理解力，也必须寻求贤师而侍奉之，选择良友而亲近之。正因为人性需要以礼义教化来引导，所以荀子特别注重环境的作用，强...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1523358521, '5acc2aaf17d00900619a2299', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637096, '淮南子 · 汜论训', NULL, 10, 27, 1, 2, '刘安', NULL, 18114, '5858ec6a8d6d810065c34715', '汉', 'wen', '文', '', '', '古者有鍪而绻领，以王天下者矣。其德生而不辱，予而不夺，天下不非其服，同怀其德。当此之时，阴阳和平，风雨时节，万物蕃息。乌鹊之巢可俯而探也，禽兽可羁而从也。岂必褒衣博带，句襟委章甫哉？
古者民泽处复穴，冬日则不胜霜雪雾露，夏日则不胜暑蛰蚊虻。圣人乃作，为之筑土构木，以为宫室，上栋下宇，以蔽风雨，以避寒暑，而百姓安之。伯余之初作衣也，緂麻索缕，手经指挂，其成犹网罗。后世为之机杼胜复，以便其用，而民得以掩形御寒。
古者剡耜而耕，摩蜃而耨，木钩而樵，抱甀而汲，民劳而利薄。后世为之耒耜櫌锄，斧柯而樵，桔槔而汲，民逸而利多焉。
古者大川名谷，冲绝道路，不通往来也；乃为窬木方版，以为舟航。故地势有无，得相委输。乃为靻蹻而超千里，肩荷负儋之勤也，而作为之楺轮建舆，驾马服牛，民以致远而不劳。为鸷禽猛兽之害伤人，而无以禁御也；而作为之铸金锻铁以为兵刃，猛兽不能为害。
故民迫其难，则求其便；困其患，则造其备。人各以其所知，去其所害，就其所利。常故不可循，器械不可因也，则先王之法度，有移易者矣。古之制，婚礼不称主人，舜不告而娶，非礼也。立子以长，文王舍伯邑考而用武王，非制也。礼三十而娶，文王十五而生武王，非法也。夏后氏殡于阼阶之上，殷人殡于两楹之间，周人殡于西阶之上，此礼之不同者也。有虞氏用瓦棺，夏后氏堲周，殷人用椁，周人墙置翣，此葬之不同者也。夏后氏祭于暗，殷人祭于阳，周人祭于日出以朝，此祭之不同者也。尧《大章》，舜《九韶》，禹《大夏》，汤《大濩》，周《武象》，此乐之不同者也。故五帝异道，而德覆天下；三王殊事，而名施后世。此皆因时变而制礼乐者。譬犹师旷之施瑟柱也，所推移上下者，无寸尺之度，而靡不中音，故通于礼乐之情者能作音，有本主于中，而以知榘彟之所周者也。鲁昭公有慈母而爱之，死，为之练冠，故有慈母之服。阳侯杀蓼侯而窃其夫人，故大飨废夫人之礼。先王之制，不宜则废之。末世之事，善则著之，是故礼乐未始有常也。
故圣人制礼乐，而不制于礼乐。治国有常，而利民为本；政教有经，而令行为上。苟利于民，不必法古；苟周于事，不必循旧。夫夏、商之衰也，不变法而亡；三代之起也，不相袭而王。故圣人法与时变，礼与俗化。衣服器械，各便其用；法度制令，各因其宜。故变古未可非，而循俗未足多也。百川异源，而皆归于海；百家殊业，而皆务于治。王道缺而《诗》作，周室废，礼义坏，而《春秋》作。《诗》、《春秋》，学之美者也，皆衰世之造也，儒者循之，以教导于世，岂若三代之盛哉！以《诗》、《春秋》为古之道而贵之，又有未作《诗》、《春秋》之时。夫道其缺也，不若道其全也。诵先王之《诗》、《书》，不若闻得其言，闻得其言，不若得其所以言，得其所以言者，言弗能言也。
故道可道者，非常道也。周公事文王也，行无专制，事无由己，身若不胜衣，言若不出口，有奉持于文王，洞洞属属，而将不能，恐失之，可谓能子矣。武王崩，成王幼少。周公继文王之业，履天子之籍，听天下之政，平夷狄之乱，诛管、蔡之罪，负扆而朝诸侯，诛赏制断，无所顾问，威动天地，声慑四海，可谓能武矣。成王既壮，周公属籍致政，北面委质而臣事之，请而后为，复而后行，无擅恣之志，无伐矜之色，可谓能臣矣。故一人之身而三变者，所以应时矣。何况乎君数易世，国数易君，人以其位达其好憎，以其威势供嗜欲，而欲以一行之礼，一定之法，应时偶变，其所不能中权亦明矣。
故圣人所由曰道，所为曰事。道犹金石，一调不更；事犹琴瑟，每弦改调。故法制礼义者，治人之具也，而非所以为治也。故仁以为经，义以为纪，此万世不更者也。若乃人考其才，而时省其用，虽日变可也。天下岂有常法哉！当于世事，行于人理，顺于天地，祥于鬼神，则可以正治矣。古者人醇工庞，商朴女重，是以政教易化，风俗易移也。今世德益衰，民俗益薄，欲以朴重之法，治既弊之民，是犹无镝衔■策錣而御馯马也。昔者，神农无制令而民从，唐、虞有制令而无刑罚，夏后氏不负言，殷人誓，周人盟。逮至当今之世，忍訽而轻辱，贪得而寡羞，欲以神农之道治之，则其乱必矣。伯成子高辞为诸侯而耕，天下高之。今之时人，辞官而隐处，为乡邑之下，岂可同哉！古之兵，弓剑而已矣，槽矛无击，修戟无刺；晚世之兵，隆冲以攻，渠詹以守，连弩以射，销车以斗。古之伐国，不杀黄口，不获二毛。于古为义，于今为笑。古之所以为荣者，今之所以为辱也；古之所以为治者，今之所以为乱也。夫神农、伏羲不施赏罚而民不为非，然而立政者不能废法而治民；舜执干戚而服有苗，然而征伐者不能释甲兵而制强暴。由此观之，法度者，所以论民俗而节缓急也；器械者，因时变而制宜适也。
夫圣人作法，而万物制焉；贤者立礼，而不肖者拘焉。制法之民，不可与远举；拘礼之人，不可使应变。耳不知清浊之分者，不可令调音；心不知治乱之源者，不可令制法。必有独闻之耳，独见之明，然后能擅道而行矣。夫殷变夏，周变殷，春秋变周，三代之礼不同，何古之从！大人作而弟子循。知法治所由生，则应时而变；不知法治之源，虽循古，终乱。今世之法籍与时变，礼义与俗易，为学者循先袭业，据籍守旧教，以为非此不治，是犹持方枘而周员凿也。欲得宜适致固焉，则难矣！
今儒、墨者称三代、文武而弗行，是言其所不行也；非今时之世而弗改，是行其所非也。称其所是，行其所非，是以尽日极虑而无益于治，劳形竭智而无补于主也。今夫图工而好画鬼魅，而憎图狗马者，何也？鬼魅不世出，而狗马可日见也。夫存危治乱，非智不能；道而先称古，虽愚有余。故不用之法，圣王弗行；不验之言，圣王弗听。天地之气莫大于和，和者，阴阳调，日夜分，而生物。春分而生，秋分而成，生之与成，必得和之精。故圣人之道，宽而栗，严而温，柔而直，猛而仁。太刚则折，太柔则卷，圣人正在刚柔之间，乃得道之本。积阴则沉，积阳则飞，阴阳相接，乃能成和。夫绳之为度也，可卷而伸也，引而伸之，可直而睎，故圣人以身体之。夫修而不横，短而不穷，直而不刚，久而不忘者，其唯绳乎？故恩推则懦，懦则不威；严推则猛，猛则不和；爱推则纵，纵则不令；刑推则虐，虐则无亲。昔者，齐简公释其国家之柄，而专任其大臣，将相摄威擅势，私门成党，而公道不行，故使陈成田常、鸱夷子皮得成其难。使吕氏绝祀而陈氏有国者，此柔懦所生也。郑子阳刚毅而好罚，其于罚也，执而无赦。舍人有折弓者，畏罪而恐诛，则因猘狗之惊，以杀子阳，此刚猛之所致也。
今不知道者，见柔懦者侵，则矜为刚毅；见刚毅者亡，则矜为柔懦。此本无主于中，而见闻舛驰于外者也，故终身而无所定趋。譬犹不知音者之歌也，浊之则郁而无转，清之则燋而不讴，及至韩娥、秦青、薛谈之讴，侯同、曼声之歌，愤于志，积于内，盈而发音，则莫不比于律而和于人心。何则？中有所本主，以定清浊，不受于外，而自为仪表也。今夫盲者行于道，人谓之左则左，谓之右则右，遇君子则易道，遇小人则陷沟壑。何则？目无以接物也。故魏两用楼翟、吴起，而亡西河，氵昏王专用淖齿，而死于东庙，无术以御之也；文王两用吕望、召公奭而王，楚庄王专任孙叔敖而霸，有术以御之也。
夫弦歌鼓舞以为乐，盘旋揖让以修礼，厚葬久丧以送死，孔子之所立也，而墨子非之。兼爱尚贤，右鬼非命，墨子之所立也，而杨子非之。全性保真，不以物累形，杨子之所立也，而孟子非之。趋舍人异，各有晓心。故是非有处，得其处则无非；失其处则无是。丹穴、太蒙、反踵、空同、大夏、北户、奇肱、修股之民，是非各异，习俗相反，君臣上下，夫妇父子，有以相使也。此之是，非彼之是也；此之非，非彼之非也。譬若斤斧椎凿之各有所施也。禹之时，以五音听治，悬钟鼓磬铎，置鞀，以待四方之士，为号曰：“教寡人以道者击鼓，谕寡人以义者击钟，告寡人以事者振铎，语寡人以忧者击磬，有狱讼者摇鞀。”当此之时，一馈而十起，一沐而三捉发，以劳天下之民。此而不能达善效忠者，则才不足也。秦之时，高为台榭，大为苑囿，远为驰道，铸金人，发适戍，入刍稿，头会箕赋，输于少府。丁壮丈夫，西至临洮、狄道，东至会稽、浮石；南至豫章、桂林，北至飞狐、阳原，道路死人以沟量。当此之时，忠谏者谓之不祥，而道仁义者谓之狂。逮至高皇帝存亡继绝，举天下之大义，身自奋袂执锐，以为百姓请命于皇天。当此之时，天下雄俊豪英，暴露于野泽，前蒙矢石，而后堕溪壑，出百死而绐一生，以争天下之权，奋武厉诚，以决一旦之命。当此之时，丰衣博带而道儒、墨者，以为不肖。逮至暴乱已胜，海内大定，继文之业，立武之功，履天子之图籍，造刘氏之貌冠，总邹、鲁之儒、墨，通先圣之遗教，戴天子之旗，乘大路，建九斿，撞大钟，击鸣鼓，奏《咸池》，扬干戚。当此之时，有立武者见疑，一世之间，而文武代为雌雄，有时而用也。
今世之为武者，则非文也；为文者，则非武也。文武更相非，而不知时世之用也。此见隅曲之一指，而不知八极之广大也。故东面而望，不见西墙；南面而视，不睹北方；唯无所向者，则无所不通。国之所以存者，道德也；家之所以亡者，理塞也。尧无百户之郭，舜无置锥之地，以有天下；禹无十人之众，汤无七里之分，以王诸侯。文王处岐周之间也，地方不过百里，而立为天子者，有王道也。夏桀、殷纣之盛也，人迹所至，舟车所通，莫不为郡县，然而身死人手，而为天下笑者，有亡形也。故圣人见化以观其徵，德有盛衰，风先萌焉。故得王道者，虽小必大；有亡形者，虽成必败。夫夏之将亡，太史令终古先奔于商，三年而桀乃亡。殷之将败也，太史令向艺先归文王，期年而纣乃亡。故圣人见存亡之迹，成败之际也，非待鸣条之野，甲子之日也。
今谓强者胜，则度地计众；富者利，则量粟称金。若此，则千乘之君无不霸王者，而万乘之国无不破亡者矣。存亡之迹，若此其易知也，愚夫蠢妇，皆能论之。赵襄子以晋阳之城霸，智伯以三晋之地擒，氵昏王以大齐亡，田单以即墨有功。故国之亡也，虽大不足恃；道之行也，虽小不可轻。由此观之，存在得道，而不在于大也；亡在失道，而不在于小也。《诗》云：“乃眷西顾，此惟与宅。”言去殷而迁于周也。故乱国之君，务广其地而不务仁义，务高其位而不务道德。是释其所以存，而造其所以亡也。故桀囚于焦门，而不能自非其所行，而悔不杀汤于夏台；纣居于宣室，而不反其过，而悔不诛文王于羑里。二君处强大势位，修仁义之道，汤、武救罪之不给，何谋之敢当！若上乱三光之明，下失万民之心，虽微汤、武，孰弗能夺也！今不审其在己者，而反备之于人，天下非一汤、武也，杀一人，则必有继之者也。且汤、武之所以处小弱而能以王者，以其有道也；桀、纣之所以处强大而见夺者，以其无道也。今不行人之所以王者，而反益己之所以夺，是趋亡之道也。
武王克殷，欲筑宫于五行之山，周公曰：“不可。夫五行之山，固塞险阻之地也。使我德能覆之，则天下纳其贡职者回也；使我有暴乱之行，则天下之伐我难矣。”此所以三十六世而不夺也。周公可谓能持满矣。昔者，《周书》有言曰：“上言者，下用也；下言者，上用也。上言者，常也；下言者，权也。”此存亡之术也，唯圣人为能知权。言而必信，期而必当，天下之高行也。直躬其父攘羊而子证之，尾生与妇人期而死之。直而证父，信而溺死，虽有直信，孰能贵之？夫三军矫命，过之大者也。秦穆公兴兵袭郑，过周而东，郑贾人弦高将西贩牛，道遇秦师于周、郑之间，乃矫郑伯之命，犒以十二牛，宾秦师而却之，以存郑国。故事有所至，信反为过，诞反为功。何谓失礼而有大功？昔楚恭王战于阴陵，潘尪、养由基、黄衰微、公孙丙相与篡之。恭王惧而失礼，黄衰微举足蹴其体，恭王乃觉。怒其失礼，奋体而起，四大夫载而行。昔苍吾绕娶妻而美，以让兄，此所谓忠爱而不可行者也。是故圣人论事之局曲直，与之屈伸偃仰，无常仪表，时屈时伸。卑弱柔如蒲苇，非摄夺也；刚强猛毅，志厉青云，非本矜也，以乘时应变也。夫君臣之接，屈膝卑拜，以相尊礼也；至其迫于患也，则举足蹴其体，天下莫能非也。是故忠之所在，礼不足以难之也。孝子之事亲，和颜卑体，奉带运履，至其溺也，则捽其发而拯；非敢骄侮，以救其死也。故溺则捽父，祝则名君，势不得不然也。此权之所设也。故孔子曰：“可以共学矣，而未可以适道也；可与适道，未可以立也；可以立，未可与权。”权者，圣人之所独见也。故忤而后合者，谓之知权；合而后舛者，谓之不知权；不知权者，善反丑矣。故礼者，实之华而伪之文也，方于卒迫穷遽之中也，则无所用矣。是故圣人以文交于世，而以实从事于宜，不结于一迹之途，凝滞而不化。是故败事少而成事多，号令行于天下，而莫之能非矣。
猩猩知往而不知来，乾鹄知来而不知往，此修短之分也。昔者苌弘，周室之执数者也。天地之气，日月之行，风雨之变，律历之数，无所不通。然而不能自知，车裂而死。苏秦，匹夫徒步之人也，靻蹻嬴盖，经营万乘之主，服诺诸侯，然不自免于车裂之患。徐偃王被服慈惠，身行仁义，陆地之朝者三十二国，然而身死国亡，子孙无类。大夫种辅翼越王勾践，而为之报怨雪耻，擒夫差之身，开地数千里，然而身伏属镂而死。此皆达治乱之机，而未知全性之具者。故苌宏知天道而不知人事，苏秦知权谋而不知祸福，徐偃王知仁义而不知时，大夫种知忠而不知谋。圣人则不然，论世而为之事，权事而为之谋，是以舒之天下而不窕，内之寻常而不塞。使天下荒乱，礼义绝，纲纪废，强弱相乘，力征相攘，臣主无差，贵贱无序，甲胄生虮虱，燕雀处帷幄，而兵不休息，而乃始服属臾之貌，恭俭之礼，则必灭抑而不能兴矣。天下安宁，政教和平，百姓肃睦，上下相亲，而乃始立气矜，奋勇力，则必不免于有司之法矣。是故圣人者，能阴能阳，能弱能强，随时而动静，因资而立功，物动而知其反，事萌而察其变，化则为之象，运则为之应，是以终身而无所困。
故事有可行而不可言者，有可言而不可行者，有易为而难成者，以难成而易败者。所谓可行而不可言者，趋舍也；可言而不可行者，伪诈也；易为而难成者，事也；难成而易败者，名也。此四策者，圣人之所独见而留意也。誳寸而伸尺，圣人为之；小枉而大直，君子行之。周公有杀弟之累，齐桓有争国之名；然而周公以义补缺，桓公以功灭丑，而皆为贤。今以人之小过，掩其大美，则天下无圣王贤相矣。故目中有疵，不害于视，不可灼也；喉中有病，无害于息，不可凿也。河上之丘冢，不可胜数，犹之为易也；水激兴波，高下相临，差以寻常，犹之为平。昔者，曹子为鲁将兵，三战不胜，亡地千里。使曹子计不顾后，足不旋踵，刎颈于陈中，则终身为破军擒将矣。然而曹子不羞其败，耻死而无功。柯之盟，揄三尺之刃，造桓公之胸，三战所亡，一朝而反之，勇闻于天下，功立于鲁国。管仲辅公子纠而不能遂，不可谓智；遁逃奔走，不使其难，不可谓勇；束缚桎梏，不讳其耻，不可谓贞。当此三行者，布衣弗友，人君弗臣。然而管仲免于累绁之中，立齐国之政，九合诸侯，一匡天下。使管仲出死捐躯，不顾后图，岂有此霸功哉！今人君之论其臣也，不计其大功，总其略行，而求其小善，则失贤之数也。
故人有厚德，无问其小节；而有大誉，无疵其小故。夫牛蹄之涔，不能生鳝鲔，而蜂房不容鹄卵；小形不足以包大体也。夫人之情，莫不有所短。诚其大略是也，虽有小过，不足以为累；若其大略非也，虽有闾里之行，未足大举。夫颜喙聚，梁父之大盗也；而为齐忠臣。段干木，晋国之大驵也；而为文侯师。孟卯妻其嫂，有五子焉；然而相魏，宁其危，解其患。景阳淫酒，被发而御于妇人；威服诸修。此四人者，皆有所短，然而功名不灭者，其略得也。季襄、陈仲子，立节抗行，不入洿君之朝，不食乱世之食，遂饿而死。不能存亡接绝者何？小节伸而大略屈。故小谨者无成功，訾行者不容于众，体大者节疏，庶距者举远。自古及今，五帝三王，未有能全其行者也。故《易》曰：“小过亨，利贞。”言人莫不有过，而不欲其大也。夫尧、舜、汤、武，世主之隆也；齐桓、晋文，五霸之豪英也。然尧有不慈之名，舜有卑父之谤，汤武有放弑之事，五伯有暴乱之谋。是故君子不责备于一人，方正而不以割，廉直而不以切，博通而不以訾，文武而不以责。求于一人则任以人力，自修则以道德。责人以人力，易偿也；自修以道德，难为也。难为则行高矣，自偿则求澹矣。夫夏后氏之璜不能无考，明月之珠不能无类。然而天下宝之者，何也？其小恶不足妨大美。今志人之所短，而忘人之所修，而求得其贤乎天下，则难矣。夫百里奚之饭牛，伊尹之负鼎，太公之鼓刀，甯戚之商歌，其美有存焉者矣。众人见其位之卑贱，事之洿辱，而不知其大略，以为不肖。及其为天子三公，而立为诸侯贤相，乃始信于异众也。夫发于鼎俎之间，出于屠酤之肆，解于累绁之中，兴于牛颔之下，洗之以汤沐，祓之以爟火，立之于本朝之上，倚之于三公之位，内不惭于国家，外不愧于诸侯，符势有以内合。
故未有功而知其贤者，尧之知舜；功成事立而知其贤者，市人之知舜也。为是释度数而求之于朝肆草莽之中，其失人也必多矣。何则？能效其求，而不知其所以取人也。夫物之相类者，世主之所乱惑也；嫌疑肖象者，众人之所眩耀。故狠者类知而非知，愚者类仁而非仁，戆者类勇而非勇。使人之相去也，若玉之与石，美之与恶，则论人易矣。夫乱人者，芎<艹穷>之与稿本也，蛇床之与麋芜也，此皆相似者。故剑工惑剑之似莫邪者，唯欧冶能名其种；玉工眩玉之似碧卢者，唯猗顿不失其情；暗主乱于奸臣、小人之疑君子者，唯圣人能见微以知明。故蛇举首尺，而修短可知也；象见其牙，而大小可论也。薛烛庸子，见若狐甲于剑，而利纯识矣；臾儿、易牙，淄、渑之水合者，尝一哈水而甘苦知矣。故圣人之论贤也，见其一行而贤不肖分矣。孔子辞廪丘，终不盗刀钩；许由让天子，终不利封侯。故未尝灼而不敢握火者，见其有所烧也；未尝伤而不敢握刃者，见其有所害也。由此观之，见者可以论未发也，而观小节可以知大体矣。故论人之道，贵则观其所举，富则观其所施，穷则观其所不受，贱则观其所不为，贫则观其所不取。视其更难，以知其勇；动以喜乐，以观其守；委以财货，以论其仁；振以恐惧，以知其节；则人情备矣。
古之善赏者，费少而劝众；善罚者，刑省而奸禁；善予者，用约而为德；善取者，入多而无怨。赵襄子围于晋阳，罢围而赏有功者五人，高赫为赏首，左右曰：“晋阳之难，赫无大功，今为赏首，何也？”襄子曰：“晋阳之围，寡人社稷危，国家殆，群臣无不有骄侮之心，唯赫不失君臣之礼。”故赏一人，而天下为忠之臣者莫不愿忠于其君。此赏少而劝善者众也。齐威王设大鼎于庭中，而数无盐令曰：“子之誉日闻吾耳，察子之事，田野芜，仓廪虚，囹圄实。子以奸事我者也。”乃烹之。齐以此三十二岁道路不拾遗。此刑省奸禁者也。秦穆公出游而车败，右服失马，野人得之。穆公追而及之岐山之阳，野人方屠而食之。穆公曰：“夫食骏马之肉，而不还饮酒者，伤人。吾恐其伤汝等。”遍饮而去之。处一年，与晋惠公为韩之战，晋师围穆公之车，梁由靡扣穆公之骖，获之。食马肉者三百余人，皆出死为穆公战于车下，遂克晋，虏惠公以归。此用约而为德者也。齐桓公将欲征伐，甲兵不足，令有重罪者出犀甲一戟，有轻罪者赎以金分，讼而不胜者出一束箭。百姓皆说，乃矫箭为矢，铸金而为刃，以伐不义而征无道，遂霸天下。此入多而无怨者也。故圣人因民之所喜而劝善，因民之所恶而禁奸。故赏一人而天下誉之，罚一人而天下畏之。故至赏不费，至刑不滥。孔子诛少正卯而鲁国之邪塞；子产诛邓析，而郑国之奸禁。以近喻远，以小知大也。故圣人守约而治广者，此之谓也。天下莫易于为善，而莫难于为不善也。所谓为善者，静而无为也；所谓为不善者，躁而多欲也。适情辞馀，无所诱惑，循性保真，无变于己，故曰为善易。越城郭，逾险塞，奸符节，盗管金，篡弑矫诬，非人之性也，故曰为不善难。今人所以犯囹圄之罪，而陷于刑戮之患者，由嗜欲无厌，不循度量之故也。何以知其然？天下县官法曰：“发墓者诛，窃盗者刑。”此执政之所司也。夫法令者，网其奸邪，勒率随其踪迹。无愚夫蠢妇，皆知为奸之无脱也，犯禁之不得免也。然而不材子不胜其欲，蒙死亡之罪，而被刑戮之羞。然而立秋之后，司寇之徒继踵于门，而死市之人血流于路。何则？惑于财利之得，而蔽于死亡之患也。夫今陈卒设兵，两军相当，将施令曰：“斩首拜爵，而屈挠者要斩。”然而队阶之卒皆不能前遂斩首之功，而后被要斩之罪，是去恐死而就必死也。故利害之反，祸福之接，不可不审也。
事或欲之，适足以失之；或避之，适足以就之。楚人有乘船而遇大风者，波至而自投于水。非不贪生而畏死也，惑于恐死而反忘生也。故人之嗜欲，亦犹此也。齐人有盗金者，当市繁之时，至掇而走。勒问其故，曰：“而盗金于市中，何也？”对曰：“吾不见人，徒见金耳。”志所欲，则忘其为矣。是故圣人审动静之变，而适受与之度，理好憎之情，和喜怒之节。夫动静得，则患弗过也；受与适，则罪弗累也；好憎理，则忧弗近也；喜怒节，则怨弗犯也。故达道之人，不苟得，不让福，其有弗弃，非其有弗索，常满而不溢，恒虚而易足。今夫霤水足以溢壶榼，而江河不能实漏卮。故人心犹是也。自当以道术度量，食充虚，衣御寒，则足以养七尺之形矣。若无道术度量而以自俭约，则万乘之势不足以为尊，天下之富不足以为乐矣。
叔孙敖三去令尹而无忧色，受罪禄不能累也；荆亻次非两蛟夹绕其船而志不动，怪物不能惊也。圣人心平志易，精神内守，物莫足以惑之。夫醉者俯入城门，以为七尺之闺也；超江、淮，以为寻常之沟也；酒浊其神也。怯者夜见立表，以为鬼也；见寝石，以为虎也；惧掩其气也。又况无天地之怪物乎？夫雌雄相接，阴阳相薄，羽者为雏，毛者为驹犊，柔者为皮肉，坚者为齿角，人弗怪也。水生蠬蜄，山生金玉，人弗怪也。老槐生火，久血为磷，人弗怪也。山出枭阳，水生罔象，木生毕方，井生坟羊，人怪之，闻见鲜而识物浅也。天下之怪物，圣人之所独见；利害之反覆，知者之所独明达也；同异嫌疑者，世俗之所眩惑也。夫见不可布于海内，闻不可明于百姓，是故鬼神禨祥，而为之立禁；总形推类，而为之变象。何以知其然也？世俗言曰：“飨大高者，而彘为上牲；葬死人者，裘不可以藏；相戏以刃者，太祖軵其肘；枕户橉而卧者，鬼神庶其首。”此皆不著于法令，而圣人之所不口传也。夫飨大高而彘为上牲者，非彘能贤于野兽麋鹿也，而神明独飨之，何也？以为彘者，家人所常畜，而易得之物也。故因其便以尊之。裘不可以藏者，非能具绨绵曼帛，温暖于身也。世以为裘者，难得贵贾之物也，而不可传于后世，无益于死者，而足以养生，故因其资以詟之。相戏以刃，太祖軵其肘者，夫以刃相戏，必为过失，过失相伤，其患必大，无涉血之仇争忿斗，而以小事自内于刑戮，愚者所不知忌也，故因太祖以累其心。枕户橉而卧，鬼神履其首者，使鬼神能玄化，则不待户牖之行，若循虚而出入，则亦无能履也。夫户牖者，风气之所从往来，而风气者，阴阳相捔者也。离者必病，故托鬼神以伸诫之也。凡此之属，皆不可胜著于书策竹帛，而藏于官府者也。故以禨祥明之。为愚者之不知其害，乃借鬼神之威以声其教，所由来者远矣。而愚者以为禨祥，而狠者以为非，唯有道者能通其志。
今世之祭井灶、门户、箕帚、臼杵者，非以其神为能飨之也，恃赖其德，烦苦之无已也。是故以时见其德，所以不忘其功也。触石而出，肤寸而合，不崇朝而雨天下者，唯太山。赤地三年而不绝流，泽及百里而润草木者，唯江、河也。是以天子秩而祭之。故马免人于难者，其死也，葬之。牛，其死也，葬以大车为荐。牛马有功，犹不可忘，又况人乎！此圣人所以重仁袭恩。故炎帝于火，而死为灶；禹劳天下，而死为社；后稷作稼穑，而死为稷；羿除天下之害，死而为宗布。此鬼神之所以立。北楚有任侠者，其子孙数谏而止之，不听也。县有贼，大搜其庐，事果发觉。夜惊而走，追，道及之。其所施德者皆为之战，得免而遂反。语其子曰：“汝数止吾为侠。今有难，果赖而免身，而谏我，不可用也。”知所以免于难，而不知所以无难。论事如此，岂不惑哉！宋人有嫁子者，告其子曰：“嫁未必成也。有如出，不可不私藏。私藏而富，其于以复嫁易。”其子听父之计，窃而藏之。若公知其盗也，逐而去之。其父不自非也，而反得其计。知为出藏财，而不知藏财所以出也。为论如此，岂不勃哉！今夫僦载者，救一车之任，极一牛之力，为轴之折也，有如辕轴其上以为造，不知轴辕之趣轴折也。楚王之佩玦而逐菟，为走而破其玦也，因佩两玦以为之豫。两玦相触，破乃逾疾。乱国之治，有似于此。夫鸱目大而视不若鼠，蚈足众而走不若蛇。物固有大不若小，众不若少者，及至夫强之弱，弱之强，危之安，存之亡也，非圣人，孰能观之！大小尊卑，未足以论也，唯道之在者为贵。何以明之？天子处于郊亭，则九卿趋，大夫走，坐者伏，倚者齐。当此之时，明堂太庙，悬冠解剑，缓带而寝。非郊亭大而庙堂狭小也，至尊居之也。天道之贵也，非特天子之为尊也，所在而众仰之。夫蛰虫鹊巢，皆向天一者，至和在焉尔。帝者诚能包禀道，合至和，则禽兽草木莫不被其泽矣，而况兆民乎！', '', '', '远古时代，君王尽管衣冠不整齐，但却能治理好天下，他的德政使百姓生活得好且有尊严，他给予百姓财富而不聚敛民财，所以天下也无人来讥笑非议他的服饰，而纷纷被他的思德所感化而归服。在那时候，阴阳二气平和，风调雨顺，万物繁衍生息，乌鸦喜鹊低处筑巢也不会有人去掏窝伤害它们，禽兽驯服得只须用绳系着就可牵走，那时候的人哪需要袍衣宽带，穿曲襟衣、戴章甫帽！
古时候人住在水乡泽国，于堤岸山崖上打洞栖身，冬天难以忍受霜雪雾露的侵袭，夏天难以忍受暑热和蚊虫的叮咬。于是圣人就为百姓筑土构木建成房舍，这样上有瓦梁，下有屋檐可以用来遮风挡雨、躲避寒暑，百姓从此得以安定。伯余开始制作衣服、搓麻绳、捻麻线，手缠指绕编结成像罗网那样粗糙的衣服；后来又发明了织布机，这样就方便人纺织布帛，使百姓得以遮体御寒。古时候人们磨利石头当犁来耕地，又磨快蛤蜊当锄头来除草，用木钩刀来砍柴，抱着瓦瓮来汲水，这时的人既劳累辛苦又获利微薄；后来发明了耒耜锄头来耕翻土地播种，又制造出斧头砍柴，利用桔皋来汲水，人既轻松又获利丰厚。古时候河流深谷阻绝交通道路，人们交往不方便，于是人们挖空树木，拼合木板做成舟船，使各地的人和物产得以运输，互通有无。又因为人们到千里之外全靠徒步行走，肩挑背驮非常劳累，于是发明了车子，用马牛拉拖，这样人坐车到远方也不显得劳累；还因为猛兽凶禽伤害人，无法防御抵抗，于是人就熔铸金铁，铸成兵器、刀具，这样凶猛的禽兽就不再危害百姓了。所以人是被迫逼艰难就会寻找合适的解决方法，被祸害困扰就会发明防备的器具，人们是各以自己的聪明才智，去避开有害的东西，趋于有益的东西。既然常规不可遵循，器械不能因袭，那么先王留下的法度也不是不能改变的。
按照古代的各种礼制，子女婚姻是由父母作主、媒人牵合，虞舜不禀报父母就娶了娥皇和女英，这是不符合古礼的；确立嗣子要立长子的制度，文王不立长子伯邑考而立伯邑考的弟弟武王为嗣子，这是不符合古制的；同样，古代规定男子三十岁才能娶妻，文王十五岁就生下了武王，这是不符合古法的。夏后氏时代的人死后将灵柩停放在堂屋的东阶上，而殷朝人死后将灵柩停放在厅堂的楹柱之间，周朝人死后则将灵柩停放在西阶上，这些都是殡礼不同的地方；有虞氏时人死后用瓦棺，夏后氏时代人死后用土棺，而殷朝人死后用椁，周朝人死后用的灵柩还需用布帐装饰成扇的形状，这些都是葬礼不同的地方；夏后氏时代人在黄昏祭祀，殷朝人在中午祭祀，而周朝人则在早晨祭祀，这些都是祭祀习俗的不同。尧帝时用《大章》，舜帝时用《九韶》，夏禹时用《大夏》，商汤时用《大瞉》，武王时用《武象》，这些都是音乐舞曲上的不同。所以五帝治理天下的方法、制度各异，但他们的德泽都能遍及天下，三王治理政事的方法、制度各异，但他们都能名扬四海流传百世，这些都是因为他们能够根据时势的变化而来制定礼乐，就好像师旷调整瑟柱、上下移动时没有尺度来衡量，却无不符合音律。所以能通达礼乐情理的人制作出恰当的礼乐，这是说他内心世界有一个谱作主宰，因而能对规矩法度掌握得非常恰当合适。
鲁昭公有位奶妈，昭公十分敬爱她，奶妈去世以后，昭公破例为她守孝，所以就有了为奶妈守孝的礼节。阳陵国侯杀死了蓼侯，并抢走了蓼侯的夫人，所以从此以后举行大飨祭典时废除了由夫人执豆的礼仪。由此看来，先王的制度，不适宜的就废除它；而近代的处事方法，如果是好的，就加以继承发扬。所以是礼乐从来就不是一成不变的。礼乐是圣人制定的，并不是圣人受礼乐限制的；治理国家虽有常规，但必须以便利民众为根本；政令教化虽有常法，但必须以切实有效为最好。如果对民众有利，就不必非要效法古制；如果适合实际情况，就不必一定要遵循旧法。夏朝、商朝到了末世，桀纣不改变陈法导致了灭亡；夏禹、商汤、周武王不因袭旧法却兴旺发达而称王。所以圣人的法度是随时势的变化而变化，礼节随着习俗的不同而改变；衣服、器械各自方便其使用，法令、制度各自适合时宜。所以改变古法无可非议，因循守旧不值得赞美。
百川源头各不相同，但最后都归于大海。百家学说事业各不一样，但都以治理好天下社会为目的。“王道”残缺才产生了《》；周王室衰微、礼义崩溃才有《春秋》产生。《诗》和《春秋》虽然是学问中的极品，但却都是衰世的产物，儒家用它们来教导世人，哪里比得上用三代盛世的事情来教育世人！如果认为《诗》《春秋》是讲古代的道理而推崇它们，那么还有没产生《诗》和《春秋》的远古时代呢！与其称颂王道破残时代产生的《诗》和《春秋》，不如称颂更早的王道完整的时代。与其诵读先王的诗书，不如听他们的言论；与其听他们的言论，不如了解他们说这些言论的根据理由；而这些言论的根据和理由，又是难以用言语表达的。所以是“道可道，非常道”。
周公侍奉文王的时候，行动不擅自决定，办事不自作主张；他在文王面前柔顺得好像禁不起衣服的重量，说话轻言细语好像没有发出声音，每当有东西要捧给文王时，总是相当柔顺小心、恭恭敬敬，好像捧着重物力不胜任，生怕有所闪失，这真可谓能尽孝之之道啊！武王去世后，成王尚年幼，周公为了继承文王的事业，履行天子的职责，以摄政王的身份处理天下政事，平息夷狄的叛乱，诛杀惩处了谋反的管叔、蔡叔，坐在天子的位子上接受诸侯的朝拜，诛杀赏赐、处置决断都由他亲自做出，不必请示成王和不必与他人商量，这样威风震动天地、声势慑服四海，这真可谓威武刚毅啊！成王长大以后，周公将政权归还给成王。以臣礼面北恭谦地侍奉成王，遇事必报告请示成王后才去执行，没有任何擅断专横的意思，也没有任何居功骄傲的神态，这真可谓能行臣之道啊！所以周公一人前后三次改变身份和为人作风，这都是为了顺应时势啊！何况同一君王多次变化治政方法，同一国家多次改换君王。凡人都凭借着他的地位来做他所喜欢的事和去除他所憎恶的事，以便借助他的威势来满足自己的嗜好欲望。然而却想用一定的礼法来应对千变万化的时势，这种不符合权变的原则，是明摆着的。
所以圣人所遵循的原则叫道，所做的叫事。这道就好比金钟石磬，一旦定了调就无法改换；而事就好比琴瑟，每根弦的音都可以随时调整。所以法制礼义这些东西，只是治理国家的工具、方法，而不是治理好国家的最终的东西。所以以“仁”为经，以“义”为纪，这倒是万世不变的。至于说考察人才，以省察他们的行为来决定对其使用与否，对于这类的事情，即使每天有变动也是可以的，天底下哪有一成不变的常规法度！只要符合世事，适合情理，顺应天地，协祥鬼神，就可以治理好天下了。
古时候，人们淳朴忠厚，工匠制作的器具坚固耐用精致美观，商贾诚实不欺诈，女子纯真稳重，因此教政容易感化，风俗容易改变。如今社会道德日益衰败，民风习俗日益浅薄，想用质朴纯厚的方法去治理日益腐败的民风，就像不用马嚼子和马鞭去驾御烈马那样困难。过去神农氏时代没有法令制度而民众却自觉服从，唐尧虞舜时代尽管制定了法令但无人触犯刑罚；夏朝人说话守信用，殷朝人通过发誓、周朝人通过歃血为盟来达到守信。而到今天这世道，人反而习惯忍受耻辱，为贪得财物而不顾廉耻，在这种情况下还想用神农时代的方法来治理，那就必定要乱套。过去伯成子高不愿做官，拒绝封为诸侯，情愿归乡隐居种田，天下人都称赞他；如今的人如果拒绝做官，就会被乡里人瞧不起，这哪能相提并论啊！古代兵器，只是弓和剑，木矛没有铁枪头，长戟没有锋尖。而近代的兵器，冲车做得高又大以备攻城，沟堑和幨帐用来防御，连发的机弩用来射杀，装有尖刀的战车用来战斗。古时候征讨别的国家，不杀小孩、不捉老人，这被认为是那时候的人道主义，而现在这样做就会被人嘲笑。古时候认为是一件光荣的事，在今天有可能被认为是一件耻辱的事；古时候用来治理天下的方法，今天用来治理天下就会乱套。
神农伏羲不实施赏罚，人民也不会去做坏事，而现在的执政者就不可能去废除法令来治理百姓；虞舜执干戚而舞使有苗族臣服。但现在带兵征伐的将领却哪能可以放弃武器去制止暴乱。由此看来，制定法度，是用来反映百姓的习俗，应当宽严缓急适度；器械用具同样要根据时代的变化而变化，使之适宜使用。
圣人制定法令制度，使普通人受到制约；贤人确立礼节，使无能的人拘泥于礼节。受法制约的人是不可能有远大行为的；拘泥于礼节的人是难以适应变化的。耳朵听觉不能分辨清浊的人，是不可以让他去调整音律的；内心不明白国家治乱根源的人，是不可以让他去制定法令的。具有能听别人难以听到的声音的听觉和能看别人难以看到的东西的视觉的人，才能随心所欲择道前进。
殷朝改变了夏朝的礼法，周朝改变了殷朝的礼法，春秋各国又改变了周朝的礼法，三代的礼法各不相同，哪还有什么古礼法可以遵从呢！如果遵从古礼法，就像长辈立法、晚辈遵从照搬。如果知道法治产生的缘由，那么就有可能应时而变法；如果不明白法治产生的根源，那么因循守旧，套用古礼古法，就有可能最终导致大乱。现在的法典已经根据时势变化而变化了，礼仪也已经随习俗变化而变化了。而那些学者还是因袭旧业，死守法典旧教，以为离开这些就无法治理天下，这实在是像拿着方榫头去装圆榫眼，还想套装牢固适宜，那就难了。现在的儒、墨、言必称三代、文武二王的一套，可自己又不实施，这无疑是在宣扬一套根本行不通的东西。现在的儒、墨，非议眼前的现实，但又不去改变它，这实际上是听任不合理的东西存在下去。这真是称赞是他们认为正确的事，做的却是他们认为错误的事，因此整天用尽心思伤透脑筋却对治国毫无益处，劳损形体竭尽智力，如此却无补于时。如今的那些画匠总爱画鬼怪而讨厌画狗马，这是什么道理呢？这是因为鬼怪不可能在世上出现，而狗与马倒是能天天见到，画鬼容易画狗（马）难啊！挽回危局、治理乱世，没有聪明才智是无法做到的；但只是复述古人、称道古代，即使让笨蛋来做也是绰绰有余。所以无用的方法和法规，圣王是不采用的；不符合实际的言论和事情，英明君主是不听取的。
天地之间的气，没有比中和之气更珍贵的了。所谓中和之气，就是阴阳协调，昼夜分明，这样万物才能生长。万物是在春分时节生长、秋分时节成熟，这生长和成熟都离不开这精纯的中和之气。所以圣人的处事原则是：宽松而又坚决，威严而又温和，柔软而又刚直，威猛而又仁慈。因为如果太刚硬则容易折断，如果太柔软则容易卷曲，所以圣人是处刚柔之间，为得道之根本。积阴过多则沉，积阳过多则飞，只有阴阳交融才能达到融和状态。', '[{"bookId": "645fbed05fc8182fe989db7d", "bookTitle": "淮南子鉴赏辞典", "articleId": "647c724dc98d685fd9dcb76b", "shortContent": "作者在本卷中泛论博说世间古今之得失，所以题为《氾论训》。这“氾论”并非泛泛而论，其中也有它的内涵宗旨，这就如高诱题解中说的那样：“以道为化，大归于一，故曰‘氾论’”。这“以道为化”，是说圣人明白“道可道者，非常道也”，“道”不是僵化不变的教条，而是无时无刻不在随时势而变化，是包涵一种理智的活动性在其中的；因而圣人不会机械地固守陈规，他“能阴能阳，能弱能强；随时而动静，因资而立功；物动而知其反，事萌...", "authors": ["刘康德", "张锋宾"], "pressName": "上海辞书出版社"}, {"bookId": "645fbed05fc8182fe989db7d", "bookTitle": "淮南子鉴赏辞典", "articleId": "647c913fb6a81d0c53921f3a", "shortContent": "在《淮南子》看来，虽然诸子百家有着各自不同的思想主张和义理体系，也有各自不同的现实实践活动，但是就像源头各异的江海湖泊最后都会流归于大海一样，这些迥然各异的诸子百家也有着相同的思想归旨，即它们都以治理好天下社会为其目的。这既是西汉初年黄老道学和其他思想流派的思想特征，又是道家“以道为化，大归于一”思想的具体体现，也是其“时变”思想的具体表现。\n\n以往我们过于严格突出诸子百家思想的差异性，却相对忽略...", "authors": ["张锦波"], "pressName": "上海辞书出版社"}, {"bookId": "645fbed05fc8182fe989db7d", "bookTitle": "淮南子鉴赏辞典", "articleId": "647c95e630675327e1298fb4", "shortContent": "我们现在一谈政治，便往往会援引西方的民主，以为古代中国万古如长夜，都是君主专制的时代，无足道者。其实，中国的政治文明要比西方起步早得多，如《淮南子》这则故事所讲的，早在夏禹时代，当时的为政者就明白了广泛听取民意的重要。夏禹不但悬鞀建铎以广开言路，而且细致地区分了五种民意：欲拿道来指导的可以击鼓，欲用义来教诲的可以敲钟，欲告之以事情的可以摇铎，欲诉之以忧愁的可以击磬，欲打官司的可以摇鞀鼓。从道、义，...", "authors": ["张榕坤"], "pressName": "上海辞书出版社"}, {"bookId": "645fbed05fc8182fe989db7d", "bookTitle": "淮南子鉴赏辞典", "articleId": "647c966ec98d685fd9dd6d25", "shortContent": "秦穆公是秦国历史上一位有作为的君主，他在位长达三十九年，内修国政，外图霸业，开始了秦国的崛起，在部分史料中被认定为春秋五霸之一。“秦穆公失马”这则故事主要反映的是秦穆公心胸宽广，能体恤百姓，因此也便自然能够得到百姓的拥戴和维护。\n\n当秦穆公看到山里人把自己的马杀了煮着吃的场面之后，他不但没有动怒，而且还怕山里人吃骏马的肉会伤身，又供给他们酒喝。能够如此胸怀宽广而不计个人利益得失，并且如此为百姓着想...", "authors": ["张榕坤"], "pressName": "上海辞书出版社"}, {"bookId": "645fbed05fc8182fe989db7d", "bookTitle": "淮南子鉴赏辞典", "articleId": "647c96ac7f27182da3f35d4a", "shortContent": "游侠是中国古代社会中的一个特殊群体，在先秦两汉时期尤其活跃，所以司马迁和班固分别在《史记》和《汉书》中专门为其立传。对于政府的行政治理来说，游侠作为一个特立独行、不拘礼法的群体，在很多时候自然是被政府所打压的，如韩非子曾把游侠作为危害社会统治的五种蛀虫之一，认为“侠以武犯禁”（《韩非子·五蠹》）；班固在《汉书·游侠传》中亦批评游侠“以匹夫之细窃生杀之权，其罪已不容于诛矣”。但在普通老百姓眼中，游侠...", "authors": ["刘康德"], "pressName": "上海辞书出版社"}]', '', 'indent', 1523359558, '5acc2e7417d00900619a3dc0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637097, '荀子 · 儒效', NULL, 40, 13, 1, 1, '荀子', NULL, 10279, '57b902bbdf0eea006334f0d0', '周', 'wen', '文', '', '', '大儒之效：武王崩，成王幼，周公屏成王而及武王，以属天下，恶天下之倍周也。履天子之籍，听天下之断，偃然如固有之，而天下不称贪焉。杀管叔，虚殷国，而天下不称戾焉。兼制天下，立七十一国，姬姓独居五十三人，而天下不称偏焉。教诲开导成王，使谕于道，而能揜迹于文武。周公归周，反籍于成王，而天下不辍事周；然而周公北面而朝之。天子也者，不可以少当也，不可以假摄为也；能则天下归之，不能则天下去之，是以周公屏成王而及武王；以属天下，恶天下之离周也。成王冠，成人，周公归周，反籍焉，明不灭主之义也。周公无天下矣；乡有天下，今无天下，非擅也；成王乡无天下，今有天下，非夺也；变埶次序节然也。故以枝代主而非越也；以弟诛兄而非暴也；君臣易位而非不顺也。因天下之和，遂文武之业，明主枝之义，抑亦变化矣，天下厌然犹一也。非圣人莫之能为。夫是之谓大儒之效。
秦昭王问孙卿子曰：“儒无益于人之国。”
孙卿子曰：“儒者法先王，隆礼义，谨乎臣子而致贵其上者也。人主用之，则埶在本朝而宜；不用，则退编百姓而悫；必为顺下矣。虽穷困冻餧，必不以邪道为贪。无置锥之地，而明于持社稷之大义。嘄呼而莫之能应，然而通乎财万物，养百姓之经纪。埶在人上，则王公之材也；在人下，则社稷之臣，国君之宝也；虽隐于穷阎漏屋，人莫不贵之，道诚存也。
“仲尼将为司寇，沈犹氏不敢朝饮其羊，公慎氏出其妻，慎溃氏逾境而徙，鲁之粥牛马者不豫贾，修正以待之也。居于阙党，阙党之子弟罔不分，有亲者取多，孝弟以化之也。儒者在本朝则美政，在下位则美俗。儒之为人下如是矣。”
王曰：“然则其为人上何如？”
孙卿曰：“其为人上也，广大矣！志意定乎内，礼节修乎朝，法则度量正乎官，忠信爱利形乎下。行一不义，杀一无罪，而得天下，不为也。此若义信乎人矣，通于四海，则天下应之如讙。是何也？则贵名白而天下治也。故近者歌讴而乐之，远者竭蹶而趋之，四海之内若一家，通达之属莫不从服。夫是之谓人师。诗曰：‘自西自东，自南自北，无思不服。’此之谓也。夫其为人下也如彼，其为人上也如此，何谓其无益于人之国也！”
昭王曰：“善！”
先王之道，人之隆也，比中而行之．曷谓中？曰：礼义是也．道者，非天之道，非地之道，人之所以道也，君子之所道也．君子之所谓贤者，非能遍能人之所能之谓也；君子之所谓知者，非能遍知人之所知之谓也；君子之所谓辩者，非能遍辩人之所辩之谓也；君子之所谓察者，非能遍察人之所察之谓也；有所止矣。相高下，视硗肥，序五种，君子不如农人；通货财，相美恶，辩贵贱，君子不如贾人；设规矩，陈绳墨，便备用，君子不如工人；不恤是非然不然之情，以相荐樽，以相耻怍，君子不若惠施、邓析。若夫谲德而定次，量能而授官，使贤不肖皆得其位，能不能皆得其官，万物得其宜，事变得其应，慎墨不得进其谈，惠施、邓析不敢窜其察，言必当理，事必当务，是然后君子之所长也。
凡事行，有益于理者，立之；无益于理者，废之。夫是之谓中事。凡知说，有益于理者，为之；无益于理者，舍之。夫是之谓中说。事行失中，谓之奸事；知说失中，谓之奸道。奸事、奸道，治世之所弃，而乱世之所从服也。若夫充虚之相施易也，“坚白”“同异”之分隔也，是聪耳之所不能听也，明目之所不能见也，辩士之所不能言也，虽有圣人之知，未能偻指也。不知无害为君子，知之无损为小人。工匠不知，无害为巧；君子不知，无害为治。王公好之则乱法，百姓好之则乱事。而狂惑戆陋之人，乃始率其群徒，辩其谈说，明其辟称，老身长子，不知恶也。夫是之谓上愚，曾不如相鸡狗之可以为名也。诗曰：“为鬼为蜮，则不可得，有腼面目，视人罔极。作此好歌，以极反侧。”此之谓也。
我欲贱而贵，愚而智，贫而富，可乎？
曰：其唯学乎。彼学者，行之，曰士也；敦慕焉，君子也；知之，圣人也。上为圣人，下为士、君子，孰禁我哉！乡也混然涂之人也，俄而并乎尧禹，岂不贱而贵矣哉！乡也效门室之辨，混然曾不能决也，俄而原仁义，分是非，圆回天下于掌上，而辩黑白，岂不愚而知矣哉！乡也胥靡之人，俄而治天下之大器举在此，岂不贫而富矣哉！今有人于此，屑然藏千溢之宝，虽行貣而食，人谓之富矣。彼宝也者，衣之不可衣也，食之不可食也，卖之不可偻售也，然而人谓之富，何也？岂不大富之器诚在此也？是杅杅亦富人已，岂不贫而富矣哉！故君子无爵而贵，无禄而富，不言而信，不怒而威，穷处而荣，独居而乐！岂不至尊、至富、至重、至严之情举积此哉！
故曰：贵名不可以比周争也，不可以夸诞有也，不可以埶重胁也，必将诚此然后就也。争之则失，让之则至；遵道则积，夸诞则虚。故君子务修其内，而让之于外；务积德于身，而处之以遵道。如是，则贵名起如日月，天下应之如雷霆。故曰：君子隐而显，微而明，辞让而胜。诗曰：“鹤鸣于九皋，声闻于天。”此之谓也。鄙夫反是：比周而誉俞少，鄙争而名俞辱，烦劳以求安利，其身俞危。诗曰：“民之无良，相怨一方，受爵不让，至于己斯亡。”此之谓也。
故能小而事大，辟之是犹力之少而任重也，舍粹折无适也。身不肖而诬贤，是犹伛伸而好升高也，指其顶者愈众。故明主谲德而序位，所以为不乱也；忠臣诚能然后敢受职，所以为不穷也。分不乱于上，能不穷于下，治辩之极也。诗曰：“平平左右，亦是率从。”是言上下之交不相乱也。
以从俗为善，以货财为宝，以养生为己至道，是民德也。行法至坚，不以私欲乱所闻：如是，则可谓劲士矣。行法至坚，好修正其所闻，以桥饰其情性；其言多当矣，而未谕也；其行多当矣，而未安也；其知虑多当矣，而未周密也；上则能大其所隆，下则能开道不己若者：如是，则可谓笃厚君子矣。修百王之法，若辨白黑；应当时之变，若数一二；行礼要节而安之，若生四枝；要时立功之巧，若诏四时；平正和民之善，亿万之众而搏若一人：如是，则可谓圣人矣。
井井兮其有理也，严严兮其能敬己也，分分兮其有终始也，猒猒兮其能长久也，乐乐兮其执道不殆也，照照兮其用知之明也，修修兮其用统类之行也，绥绥兮其有文章也，熙熙兮其乐人之臧也，隐隐兮其恐人之不当也：如是，则可谓圣人矣。此其道出乎一。曷谓一？曰：执神而固。曷谓神？曰：尽善挟治之谓神，万物莫足以倾之之谓固。神固之谓圣人。
圣人也者，道之管也：天下之道管是矣，百王之道一是矣。故诗书礼乐之道归是矣。诗言是其志也，书言是其事也，礼言是其行也，乐言是其和也，春秋言是其微也，故风之所以为不逐者，取是以节之也，小雅之所以为小雅者，取是而文之也，大雅之所以为大雅者，取是而光之也，颂之所以为至者，取是而通之也。天下之道毕是矣。乡是者臧，倍是者亡；乡是如不臧，倍是如不亡者，自古及今，未尝有也。
客有道曰：孔子曰：“周公其盛乎！身贵而愈恭，家富而愈俭，胜敌而愈戒。”
应之曰：是殆非周公之行，非孔子之言也。武王崩，成王幼，周公屏成王而及武王，履天子之籍，负扆而立，诸侯趋走堂下。当是时也，夫又谁为恭矣哉！兼制天下立七十一国，姬姓独居五十三人焉；周之子孙，苟不狂惑者，莫不为天下之显诸侯。孰谓周公俭哉！武王之诛纣也，行之日以兵忌，东面而迎太岁，至泛而泛，至怀而坏，至共头而山隧。霍叔惧曰：“出三日而五灾至，无乃不可乎？”周公曰：“刳比干而囚箕子，飞廉、恶来知政，夫又恶有不可焉！”遂选马而进，朝食于戚，暮宿于百泉，旦厌于牧之野。鼓之而纣卒易乡，遂乘殷人而诛纣。盖杀者非周人，因殷人也。故无首虏之获，无蹈难之赏。反而定三革，偃五兵，合天下，立声乐，于是武象起而韶护废矣。四海之内，莫不变心易虑以化顺之。故外阖不闭，跨天下而无蕲。当是时也，夫又谁为戒矣哉！
造父者，天下之善御者也，无舆马则无所见其能。羿者，天下之善射者也，无弓矢则无所见其巧。大儒者，善调一天下者也，无百里之地，则无所见其功。舆固马选矣，而不能以至远，一日而千里，则非造父也。弓调矢直矣，而不能射远中微，则非羿也。用百里之地，而不能以调一天下，制强暴，则非大儒也。
彼大儒者，虽隐于穷阎漏屋，无置锥之地，而王公不能与之争名；在一大夫之位，则一君不能独畜，一国不能独容，成名况乎诸侯，莫不愿得以为臣。用百里之地，而千里之国莫能与之争胜；笞棰暴国，齐一天下，而莫能倾也。是大儒之征也。其言有类，其行有礼，其举事无悔，其持险应变曲当。与时迁徙，与世偃仰，千举万变，其道一也。是大儒之稽也。其穷也俗儒笑之；其通也英杰化之，嵬琐逃之，邪说畏之，众人媿之。通则一天下，穷则独立贵名，天不能死，地不能埋，桀跖之世不能污，非大儒莫之能立，仲尼、子弓是也。
故有俗人者，有俗儒者，有雅儒者，有大儒者。不学问，无正义，以富利为隆，是俗人者也。逢衣浅带，解果其冠，略法先王而足乱世术，缪学杂举，不知法后王而一制度，不知隆礼义而杀诗书；其衣冠行伪已同于世俗矣，然而不知恶；其言议谈说已无异于墨子矣，然而明不能别；呼先王以欺愚者而求衣食焉；得委积足以揜其口，则扬扬如也；随其长子，事其便辟，举其上客，亿然若终身之虏而不敢有他志：是俗儒者也。法后王，一制度，隆礼义而杀诗书；其言行已有大法矣，然而明不能齐法教之所不及，闻见之所未至，则知不能类也；知之曰知之，不知曰不知，内不自以诬，外不自以欺，以是尊贤畏法而不敢怠傲：是雅儒者也。法先王，统礼义，一制度；以浅持博，以古持今，以一持万；苟仁义之类也，虽在鸟兽之中，若别白黑；倚物怪变，所未尝闻也，所未尝见也，卒然起一方，则举统类而应之，无所儗作；张法而度之，则晻然若合符节：是大儒者也。
故人主用俗人，则万乘之国亡；用俗儒，则万乘之国存；用雅儒，则千乘之国安；用大儒，则百里之地，久而后三年，天下为一，诸侯为臣；用万乘之国，则举错而定，一朝而伯。
不闻不若闻之，闻之不若见之，见之不若知之，知之不若行之。学至于行之而止矣。行之，明也；明之为圣人。圣人也者，本仁义，当是非，齐言行，不失豪厘，无他道焉，已乎行之矣。故闻之而不见，虽博必谬；见之而不知，虽识必妄；知之而不行，虽敦必困。不闻不见，则虽当，非仁也。其道百举而百陷也。
故人无师无法而知，则必为盗，勇则必为贼，云能则必为乱，察则必为怪，辩则必为诞；人有师有法，而知则速通，勇则速畏，云能则速成，察则速尽，辩则速论。故有师法者，人之大宝也；无师法者，人之大殃也。人无师法，则隆性矣；有师法，则隆积矣。而师法者，所得乎积，非所受乎性。性不足以独立而治。性也者，吾所不能为也，然而可化也。积也者，非吾所有也，然而可为也。注错习俗，所以化性也；并一而不二，所以成积也。习俗移志，安久移质。并一而不二，则通于神明，参于天地矣。
故积土而为山，积水而为海，旦暮积谓之岁，至高谓之天，至下谓之地，宇中六指谓之极，涂之人－－百姓，积善而全尽，谓之圣人。彼求之而后得，为之而后成，积之而后高，尽之而后圣，故圣人也者，人之所积也。人积耨耕而为农夫，积斫削而为工匠，积反货而为商贾，积礼义而为君子。工匠之子，莫不继事，而都国之民安习其服，居楚而楚，居越而越，居夏而夏，是非天性也，积靡使然也。故人知谨注错，慎习俗，大积靡，则为君子矣。纵情性而不足问学，则为小人矣；为君子则常安荣矣，为小人则常危辱矣。凡人莫不欲安荣而恶危辱，故唯君子为能得其所好，小人则日徼其所恶。诗曰：“维此良人，弗求弗迪；唯彼忍心，是顾是复。民之贪乱，宁为荼毒。”此之谓也。
人论：志不免于曲私，而冀人之以己为公也；行不免于污漫，而冀人之以己为修也；甚愚陋沟瞀，而冀人之以己为知也：是众人也。志忍私，然后能公；行忍情性，然后能修；知而好问，然后能才；公修而才，可谓小儒矣。志安公，行安修，知通统类：如是则可谓大儒矣。大儒者，天子三公也；小儒者，诸侯、大夫、士也；众人者，工农商贾也。礼者、人主之所以为群臣寸尺寻丈检式也。人伦尽矣。
君子言有坛宇，行有防表，道有一隆。言政治之求，不下于安存；言志意之求，不下于士；言道德之求，不二后王。道过三代谓之荡，法二后王谓之不雅。高之下之，小之巨之，不外是矣。是君子之所以骋志意于坛宇宫廷也。故诸侯问政，不及安存，则不告也。匹夫问学，不及为士，则不教也。百家之说，不及后王，则不听也。夫是之谓君子言有坛宇，行有防表也。', '', '', '', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3b0", "shortContent": "知行关系，一直是中国哲学史上的重要问题。从先秦开始，哲学家对于知与行之先后、轻重、难易，各有所论述。孔子认为有“生而知之者”、“学而知之者”和“困而学之者”（《论语·季氏》）。老子则“不行而知”，“不出户，知天下”（《老子》四十七章）。墨子把认识的来源归结为“闻之见之”（《墨子·明鬼下》），主张“口言之，身必行之”（《墨子·公孟》）。孟子主张人有“良知”、“良能”（《孟子·尽心上》）。荀子则明确提...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1523383737, '5acc8d314773f7005d8d05fc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637114, '地藏经 · 忉利天宫神通品第一', NULL, 24, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BF%89%E5%88%A9%E5%A4%A9%E5%AE%AB%E7%A5%9E%E9%80%9A%E5%93%81%E7%AC%AC%E4%B8%80/5783707', '', '如是我闻。一时佛在忉利天，为母说法。尔时十方无量世界，不可说不可说一切诸佛，及大菩萨摩诃萨，皆来集会。赞叹释迦牟尼佛，能于五浊恶世，现不可思议大智慧神通之力，调伏刚强众生，知苦乐法。各遣侍者，问讯世尊。
是时如来含笑，放百千万亿大光明云，所谓大圆满光明云、大慈悲光明云、大智慧光明云、大般若光明云、大三昧光明云、大吉祥光明云、大福德光明云、大功德光明云、大归依光明云、大赞叹光明云。
放如是等不可说光明云已，又出种种微妙之音，所谓檀波罗蜜音、尸波罗蜜音、羼提波罗蜜音、毗离耶波罗蜜音、禅波罗蜜音、般若波罗蜜音、慈悲音、喜舍音、解脱音、无漏音、智慧音、大智慧音、狮子吼音、大狮子吼音、云雷音、大云雷音。
出如是等不可说不可说音已，娑婆世界，及他方国土，有无量亿天龙鬼神，亦集到忉利天宫，所谓四天王天、忉利天、须焰摩天、兜率陀天、化乐天、他化自在天、梵众天、梵辅天、大梵天、少光天、无量光天、光音天、少净天、无量净天、遍净天、福生天、福爱天、广果天、无想天、无烦天、无热天、善见天、善现天、色究竟天、摩醯首罗天，乃至非想非非想处天，一切天众、龙众、鬼神等众，悉来集会。
复有他方国土，及娑婆世界，海神、江神、河神、树神、山神、地神、川泽神、苗稼神、昼神、夜神、空神、天神、饮食神、草木神，如是等神，皆来集会。复有他方国土，及娑婆世界，诸大鬼王，所谓恶目鬼王、啖血鬼王、啖精气鬼王、啖胎卵鬼王、行病鬼王、摄毒鬼王、慈心鬼王、福利鬼王、大爱敬鬼王，如是等鬼王，皆来集会。
尔时释迦牟尼佛，告文殊师利法王子菩萨摩诃萨：“汝观是一切诸佛菩萨，及天龙鬼神，此世界、他世界，此国土、他国土，如是今来集会，到忉利天者，汝知数否？”
文殊师利白佛言：“世尊，若以我神力，千劫测度，不能得知。”
佛告文殊师利：“吾以佛眼观故，犹不尽数。此皆是地藏菩萨久远劫来，已度、当度、未度，已成就、当成就、未成就。”
文殊师利白佛言：“世尊，我已过去久修善根，证无碍智，闻佛所言，即当信受。小果声闻、天龙八部，及未来世诸众生等，虽闻如来诚实之语，必怀疑惑。设使顶受，未免兴谤。唯愿世尊，广说地藏菩萨摩诃萨，因地作何行、立何愿，而能成就不思议事。”
佛告文殊师利：“譬如三千大千世界，所有草木丛林、稻麻竹苇、山石微尘，一物一数，作一恒河；一恒河沙，一沙一界；一界之内，一尘一劫；一劫之内，所积尘数，尽充为劫。地藏菩萨证十地果位以来，千倍多于上喻，何况地藏菩萨在声闻、辟支佛地。文殊师利，此菩萨威神誓愿，不可思议。若未来世，有善男子、善女人，闻是菩萨名字，或赞叹，或瞻礼，或称名，或供养，乃至彩画、刻镂、塑漆形像，是人当得百返生于三十三天，永不堕恶道。”
“文殊师利，是地藏菩萨摩诃萨，于过去久远不可说不可说劫前，身为大长者大子。时世有佛，号曰狮子奋迅具足万行如来。时长者子，见佛相好，千福庄严。因问彼佛，作何行愿，而得此相？时狮子奋迅具足万行如来告长者子：欲证此身，当须久远度脱一切受苦众生。文殊师利，时长者子因发愿言：我今尽未来际，不可计劫，为是罪苦六道众生，广设方便，尽令解脱，而我自身方成佛道。以是于彼佛前立斯大愿，于今百千万亿那由他不可说劫，尚为菩萨。”
“又于过去不可思议阿僧祇劫，时世有佛，号曰觉华定自在王如来，彼佛寿命四百千万亿阿僧祇劫。像法之中，有一婆罗门女，宿福深厚，众所钦敬，行住坐卧，诸天卫护。其母信邪，常轻三宝。是时圣女广设方便，劝诱其母，令生正见。而此女母，未全生信，不久命终，魂神堕在无间地狱。时婆罗门女，知母在世不信因果，计当随业，必生恶趣。遂卖家宅，广求香华，及诸供具，于先佛塔寺，大兴供养。见觉华定自在王如来，其形像在一寺中，塑画威容，端严毕备。时婆罗门女，瞻礼尊容，倍生敬仰。私自念言：佛名大觉，具一切智。若在世时，我母死后，倘来问佛，必知处所。时婆罗门女，垂泣良久，瞻恋如来。忽闻空中声曰：泣者圣女，勿至悲哀，我今示汝母之去处。”
“婆罗门女合掌向空，而白空曰：‘是何神德，宽我忧虑？我自失母已来，昼夜忆恋，无处可问，知母生界。’”
“时空中有声，再报女曰：‘我是汝所瞻礼者，过去觉华定自在王如来。见汝忆母，倍于常情众生之分，故来告示。’”
“婆罗门女闻此声已，举身自扑，肢节皆损。左右扶侍，良久方苏。而白空曰：‘愿佛慈愍，速说我母生界。我今身心，将死不久。’”
“时觉华定自在王如来，告圣女曰：‘汝供养毕，但早返舍，端坐思惟吾之名号，即当知母所生去处。’”
“时婆罗门女，寻礼佛已，即归其舍。以忆母故，端坐念觉华定自在王如来，经一日一夜。忽见自身到一海边，其水涌沸，多诸恶兽，尽复铁身，飞走海上，东西驰逐。见诸男子女人，百千万数，出没海中，被诸恶兽争取食啖。又见夜叉，其形各异，或多手多眼，多足多头，口牙外出，利刃如剑。驱诸罪人，使近恶兽。复自搏攫，头足相就。其形万类，不敢久视。时婆罗门女，以念佛力故，自然无惧。”
“有一鬼王，名曰无毒，稽首来迎，白圣女曰：‘善哉菩萨，何缘来此？’”
“时婆罗门女问鬼王曰：‘此是何处？’”
“无毒答曰：‘此是大铁围山西面第一重海。’”
“圣女问曰：‘我闻铁围之内，地狱在中，是事实否？’”
“无毒答曰：‘实有地狱。’”
“圣女问曰：‘我今云何得到狱所？’”
“无毒答曰：‘若非威神，即须业力。非此二事，终不能到。’”
“圣女又问：‘此水何缘，而乃涌沸，多诸罪人，及以恶兽？’”
“无毒答曰：‘此是阎浮提造恶众生，新死之者。经四十九日后，无人继嗣，为作功德，救拔苦难；生时又无善因。当据本业所感地狱，自然先渡此海。海东十万由旬，又有一海。其苦倍此。彼海之东，又有一海，其苦复倍。三业恶因之所招感，共号业海，其处是也。’”
“圣女又问鬼王无毒曰：‘地狱何在？’”
“无毒答曰：‘三海之内，是大地狱，其数百千，各各差别。所谓大者，具有十八。次有五百，苦毒无量。次有千百，亦无量苦。’”
“圣女又问大鬼王曰：‘我母死来未久，不知魂神当至何趣？’”“鬼王问圣女曰：‘菩萨之母，在生习何行业？’”
“圣女答曰：‘我母邪见，讥毁三宝。设或暂信，旋又不敬。死虽日浅，未知生处。’”
“无毒问曰：‘菩萨之母，姓氏何等？’”“圣女答曰：‘我父我母，俱婆罗门种。父号尸罗善现，母号悦帝利。’”
“无毒合掌启菩萨曰：‘愿圣者却返本处，无至忧忆悲恋。悦帝利罪女，生天以来，经今三日。云承孝顺之子，为母设供修福，布施觉华定自在王如来塔寺。非唯菩萨之母得脱地狱，应是无间罪人，此日悉得受乐，俱同生讫。’”
“鬼王言毕，合掌而退。”
“婆罗门女寻如梦归。悟此事已，便于觉华定自在王如来塔像之前，立弘誓愿：愿我尽未来劫，应有罪苦众生，广设方便，使令解脱。”
佛告文殊师利：“时鬼王无毒者，当今财首菩萨是。婆罗门女者，即地藏菩萨是。”', '《忉利天宫神通品第一》出自佛教经典《地藏经》。这一品记载了释迦牟尼佛在忉利天宫（佛教中帝释所居），为母亲摩耶夫人说法；并且，佛陀为文殊菩萨讲说了地藏菩萨发愿救度众生的宿世往因。', '如是我闻：为佛教经典固定的开篇用语，又作“我闻如是”、“闻如是”。
一时：指说法的时间，亦即法会开始至法会圆满结束的某时，系经典序文六种成就之一，可径直理解为往昔某一个时候。
十方：为四方、四维、上下之总称，即东、西、南、北、东南、西南、东北、西北、上、下。
菩萨摩诃萨：乃菩提萨埵与摩诃萨埵之简称。译作大心，大众生，大有情。摩诃名大，萨名众生，即有作佛大心之众生也。“大”有三种：即愿大（愿作佛），行大（六度万行），度众生大（度尽一切众生也）。
五浊：在恶世、末世中出现的五种污浊，即劫浊，见浊，烦恼浊，众生浊，命浊。见浊，以不明万法因缘所生无自性故，妄执为实，起自他、人我之见，不能见道，故名见浊；烦恼浊，以有人我之见，生是非、生爱憎而起种种烦恼；众生浊，烦恼内熏，发动身三、口四七支，造取舍、憎爱等业，随业受报，轮回不息，故名众生浊；命浊，轮回中一期寿命，寿夭穷通，各各不同，故名命浊；劫浊，前四浊炽盛，三灾竟起，众苦充满，故名劫浊。以五浊复障故，难见实相之理，故为障道因缘也。
神通：又作神通力，即依修禅定而得的无碍自在、超人间的、不可思议的能力和妙用。凝心修定所得变化莫测，通用无碍，变化自在之力。不测之谓神，无碍之谓通。有宿命通、天耳通、他心通、天眼通、神足通（现众生、现世界、诣世界、生万物、示化身）、漏尽通（一切世界示现正觉），通称六通。
世尊：梵文Bhagavat，音译为薄伽梵，佛的尊称，梵语路迦那他或婆迦婆，译为世尊，乃佛之尊号，以佛具万德，为世所尊重也。意思是为世间所尊敬的人。
如来：梵文Tathagata，佛的十种德号之一，意思是乘如实道，从因来果而成正觉，通俗地说，即已经觉悟的人。梵语多陀阿伽陀，译作如来，佛十号之一，乃乘真如之道，从因来果而成正觉者也，名真身如来。
慈悲：慈，梵语Maitrya悲，梵语Karuna。慈爱众生并给予快乐（与乐），称为慈；同感其苦，怜悯众生，并拔除其苦（拔苦），称为悲；二者合称为慈悲。
般若：梵文Prajna的音译，智慧之意。般若，译作净慧，妙慧。通达诸法之智及断惑证真之慧也。智乃心之性，心生一切法，智知一切法，知而无知，无知而知，离一切相，得一切智，故名般若。
三昧：梵文、巴利语Samadhi的音译，又音译作三昧定、三摩地，定的异名，汉译作等持，即将心定于一处（或一境）的一种安定状态。
檀：梵文、巴利语Dana，又译作檀那，布施、施舍之义，六度中的施度，即以慈悲心而施福利与人之义。
尸：指尸罗，梵文Sila的音译，即持戒。意思是制止恶行不为，遇到善事恭敬去做。尸罗波罗蜜为六波罗蜜即六度之一。
羼（chàn）提：梵文Ksanti的音译，即令心安稳，堪忍外在之侮辱、恼害等，亦即凡加诸身心之苦恼、苦痛，皆堪忍之，而不愤怒、不结怨、不怀恶意。
毗（pí）离耶：梵文Virya的音译，汉译为精进。精进有身精进、心精进。身精进是昼夜六时诵经拜忏礼佛；心精进即昼夜六时，念兹在兹，一心忆念佛法而不忘失。
禅：梵文Dhyana的音译，意译作静虑、止他想、系念专注一境、正审思虑、思维修等，寂静审虑之意，指将心专注于某一对象，极寂静以详密思维之定慧均等的状态。
喜舍：指四无量心（慈、悲、喜、舍）中之第三喜无量心、第四舍无量心。
无漏：漏，为漏泄、漏落之意，乃烦恼之异名。烦恼能令人堕入三恶道，故称有烦恼之法为有漏；称离烦恼垢染之清净法为无漏，如涅槃、菩提等。贪、嗔、痴诸烦恼日夜由眼耳等六根门头漏泄不止，能令众生漏落到三恶道中去，故名为漏。以此之故，名有烦恼之法为有漏，离烦恼之法名无漏。戒、定、慧及涅槃等皆为无漏之法也。以自性清净，远离烦恼，故能出此无漏之音也。
狮子吼：狮子乃众兽之王，譬喻佛说法，一切外道皆远避之。
大狮子吼：喻佛说大乘法门，令闻者振作无畏，勇猛精进发大菩提心。
云雷音、大云雷音：譬喻佛身像云，佛说法像雨，佛的音像雷一样能够远震，使众生听了雷音，猛然警悟，生欢喜心。
文殊师利法王子：文殊师利，梵文Manjusri，意译为妙吉祥，音译另有曼殊室利。是大乘佛教中以智慧为特德的菩萨，往昔曾为诸佛之师，为释迦牟尼的左胁侍，中国佛教四大菩萨之一。法王子：佛于法自在，故称法王。
劫：梵文Kalpa，音译作劫波。这是印度表示极其长久时间的一个单位，分为小劫、中劫、大劫。梵语称劫波，译成“分别时节”，指不能用年、月、日、时来计算的极长远的时节。或以世界成、住、坏、空一周所须时间为一劫，或以大、中、小时为一劫。小劫者，以人寿八万四千岁起算，每过百年减一岁，直减至人寿十岁，为一减劫，合一千六百七十九万八千年；反之，从人寿十岁起，每过百年加一岁，直加至人寿八万四千岁，为一增劫。增劫、减劫都称小劫。十次增减，合二十小劫，为一中劫。四个中劫为一大劫。通常称劫即指大劫，合一十三亿四千三百八十四万年。
佛眼：指诸佛照破诸法实相，而慈心观众生之眼。佛眼具足肉眼、天眼、慧眼、法眼四种眼之作用，此眼无事不见、无事不知、无事不闻，闻见互用，无所思维，一切皆见。
证：修习正法，如实体验而悟入真理，称为证。有契会真理而悟入之意，故有契证、证契、证会、证悟、证入等词语。又证之境地，乃唯有自己体验之意，故有已证、内证、自内证之称。
声闻：指听闻佛陀声教而证悟的出家弟子。声闻原指佛陀在世时的诸弟子，后与缘觉、菩萨相对，而为二乘或三乘之一。
天龙八部：守护佛法的八种神。天龙为别称，八部是总称。这就是天人、龙、夜叉、乾达婆（乐神）、阿修罗、迦楼罗（金翅鸟）、紧那罗（歌神）、摩喉罗伽（大蟒蛇、地龙）。
因地：为“果地”之对称。地者，位地，阶位之意，指修行佛道，由因行至证果间的阶位。相对佛果之果位而言，等觉以下者悉为因地；对于初地以上之菩萨而言，地前菩萨之阶位皆为因地，即对已证位者，称未证位者为因地。
三千大千世界：又称三千世界，这是古代印度人对全宇宙的称呼。以须弥山为中心，七山八海交互绕之，更以铁围山为外廓，是名一小世界（若包括中心的须弥山及外围铁围山，则为九山）。一小世界乃一个日月所照耀之世界，约相当于一个太阳系。合一千个小世界为一中千世界；合一千个中千世界为一大千世界，故称三千大千世界。
恒河：印度最大的河流，在今印度与孟加拉国境内。发源于雪山南部，其流域即恒河平原，四通八达，丰饶广阔，为数千年来印度文明之中心，佛陀说法亦多在恒河流域。
十地：指佛教修行过程中的十个阶位，有多种十地之说。一、三乘共十地，是《智度论》七十八所说，声闻、缘觉、菩萨三乘所共通者。二、四乘共十地，是《大乘同性经》所说，于三乘后加入佛乘十地。三、真言十地，乃指《大日经》与《金刚顶经》二经密宗所立之十地。此处唯述菩萨乘之十地：一、欢喜地：为菩萨既满初阿僧祗劫之行，初得圣性，破见惑，证二空性，生大欢喜，故名欢喜地。菩萨于此地成就檀（布施）波罗密。二、离垢地：菩萨成就尸（持戒）波罗密，断修惑（即思惑），除毁犯之垢，使身清净，故云离垢地。三、发光地：菩萨成就羼提（忍辱）波罗密，断修惑，得谛察法忍，智慧显发，故云发光地。四、焰慧地：菩萨成就毗离耶（精进）波罗密，断修惑，使慧性炽盛，故云焰慧地。五、极难胜地：菩萨成就禅定波罗密，断修惑，真俗二智之行相互违者，使之合而相应，故云极难胜地。六、现前地：菩萨成就般若（智慧）波罗密，断修惑，发最胜智，使现前无染净差别，故云现前地。七、远行地：菩萨成就方便波罗密，发大悲心，断修惑，远离二乘之自度，故云远行地。八、不动地：菩萨成就愿波罗密，断修惑，作无相观，任运无功用相续，故云不动地。九、善慧地：菩萨成就力波罗密，断修惑，具足十力，于一切处，知可度不可度，能说法，故云善慧地。十、法云地：菩萨成就智波罗密，亦断修惑，具足无边恒沙清净性功德，出生无边功德水，如大云复虚空，出清净众水，故云法云地。十地位满，便证佛菩提而成佛。
辟支佛：梵文Pratyeka—buddha，意译为缘觉或独觉。共有：一、出生于无佛之世，当时佛法已灭，但因其前世修行的因缘，自以智慧得道；二、自觉不从他闻，观悟十二因缘之理而得道。善男子、善女人：佛教经典中对在家的信男、信女，每用善男子、善女人称呼。所谓的“善”，系对信佛、闻法、行善业者之美称。长者：为家主、居士之意，一般则通称富豪或年高德劭者为长者。狮子奋迅：狮子奋起之时，诸根开张，身毛皆竖，其势迅速勇猛，以其威仪啸吼之相，令其余兽类尽失其威，以此喻佛之大威神力。具足万行，指一切具足，福慧圆满。相好：佛的身体所具足的微妙的特征。相是大的特征，好是小的特征。佛有三十二种相，八十种好。千福庄严：此种相须在百劫之中修福方可得。每修一百福可得一相，称为百福庄严；修成三十二相则需三千二百福，因称千福庄严。六道：指众生根据其生前的善恶行为，有六种轮回转生的趋向或境地，即地狱、饿鬼、畜生、阿修罗、人、天，也叫“六趣”。前三道为恶道，后三道为善道。
方便：或译善权、权宜。有三重意义：一指大乘菩萨不能像小乘一样自利，还必须运用各种手段利益他人；二是指为软化众生不得不因地因人制宜采取各种灵活方法，也即所谓权方便、权宜；三是指为证见真理而修的加行。
那由他：梵文Nayuta的音译，又译为那由多、那庾多，为数目的单位。意约为中国所说之“亿”，通常只是表示数目甚大之意。
阿僧祇：梵文Asamkhya的音译，意译为无数、无央数。佛教用于表示极为大量，无法以一般算数表示的计算单位。
觉华定自在王如来：觉悟时心境开朗，如莲华开放，故称觉华；摄心入定，抉破罗网，得大自在，所以称作定自在王。
像法：佛法有正法时代、像法时代、末法时代，这是就佛入灭后其教法的流行状态而分的三个时期。
婆罗门：梵文Brahmana的音译，意为清净。古印度四种姓之首，称最胜种姓，属祭司阶层，掌握社会的一切知识，包括宗教解脱的知识。专求解脱的婆罗门又称梵志。
宿福：过去世所做之善根功德。若以一生为限，从前迄今所做之善事亦称宿福，又称宿作福、宿善。
三宝：梵文Triratna，即佛、法、僧。佛是已开悟的人；法是指佛的教法；僧是信奉佛的、教法的僧众。以上三者，威德至高无上，永不变移，如世间之宝，故称三宝。
正见：指正确的知见，即能解知世间出世间因果，如实审虑诸法性相之有漏无漏的般若智慧。正见是八正道和十善之一，也就是对因果、事理、四圣谛及三法印等信受理解，并以之作为自己的见地。
无间地狱：无间，梵名Avici，音译作阿鼻、阿鼻旨，为八热地狱之第八。位于南赡部洲（即阎浮提）之地下二万由旬处，深广亦二万由旬，堕此地狱之有情，受苦无间。
因果：指原因与结果，亦即指因果律。因果，是佛教教义体系中用来说明一切事物相互关系的基本理论。盖一切诸法之形成，“因”为能生，“果”为所生。也就是说，能引生结果者为因，由因而生者为果。
恶趣：由恶业所感，而应趣往之处所，又称恶处、恶道。这是作为恶业结果的一种生存状态，是痛苦迷妄的生存环境。趣，为往到之义。一切智：梵文Sarvajna，音译为萨婆若、萨云然，为佛教所说的三智（一切智、道种智、一切种智）之一，指了知内外一切法相之智。
生界：现生结束后受生、托生的境地。夜叉：梵文yaksa，又音译为药叉、夜乞叉，汉译为捷疾鬼。佛教八部众之一，以昆沙门天眷属的身份，守护北方。通常指住于地上或空中，以威势恼害人，或守护正法之鬼类。
铁围山：以须弥山为中心，外有九山八海，第八海为咸海。南赡部洲等四大洲在此，围绕咸海者即是铁围山。围绕咸海而区划一小世界之铁山也。以须弥山为中心，外有七山八海，第八海即此咸海，瞻部等四大州均在此。围绕此咸海者，即大铁围山也，此为一小世界。详言之，中间是须弥山，以后各山团团围绕，第七重山外有四大部州，第八重山便是大铁围山，此铁围山乃一小世界之最外层也。铁围山又分两重，两重之间便是地狱所在。
业力：善恶之业有生起苦乐果之力用，称为业力。业，梵语Karman，音译作羯磨，为造作之义，意谓行为、所作、行动、作用、意志等身心活动，或单由意志所引生之身心生活。
阎浮提：南赡部洲的别称。新称瞻部州，位于须弥山的南方，也称南瞻部州，即是我们所居之处。阎浮是树名，为印度所产的乔木，虽为落叶植物，而其期极短，新叶相续而出。阎浮树下有河，称阎浮檀，河中出金，称阎浮檀金。阎浮提之“提”字，即“洲”之意也。按印度人的地理观，作为宇宙中心的须弥山四面有咸海，海中有四大部洲，分别为东胜神洲、南赡部洲、西牛贺洲、北俱卢洲。
由旬：梵文Yojana，系古印度计算距离的单位。以帝王一日行军的路程为一由旬，约四十里。分上中下三等。上由旬六十里，中由旬五十里，下由旬四十里。
三业：即身、口、意三业。', '这部经是我（阿难）亲闻佛陀这样宣说的：一时，释迦牟尼佛为报母生育之恩，知道母亲已生在忉利天，就上升到忉利天专门为母亲说法。当时，十方无数世界，有不可说、不可说一切诸佛及大菩萨摩诃萨，听说释迦牟尼佛到忉利天为母亲说法，都来随喜参加这个法会。法会中，无量诸佛及大菩萨摩诃萨同声赞叹释迦牟尼佛，能够在娑婆世界的五浊恶世里，现种种不可思议大智慧神通之力，调伏刚强众生，使他们明了离苦得乐的佛法。诸佛及大菩萨摩诃萨，都分别派遣侍者来向世尊致敬。
天人献草这时，释迦牟尼佛慈悲含笑，放出百千万亿大光明云，分别是大圆满光明云、大慈悲光明云、大智慧光明云、大般若光明云、大三昧光明云、大吉祥光明云、大福德光明云、大功德光明云、大归依光明云、大赞叹光明云。
呈现如此不可胜数的光明云以后，又发出种种微妙的声音，分别是布施波罗蜜音、持戒波罗蜜音、忍辱波罗蜜音、精进波罗蜜音、禅定波罗蜜音、般若波罗蜜音、慈悲音、喜舍音、解脱音、无漏音、智慧音、大智慧音、狮子吼音、大狮子吼音、云雷音、大云雷音。
发出如此不可胜数的声音之后，娑婆世界及他方世界种种国土，有无量亿的天龙鬼神，也集合到这忉利天宫，他们是四天王天、忉利天、须焰摩天、兜率陀天、化乐天、他化自在天、梵众天、梵辅天、大梵天、少光天、无量光天、光音天、少净天、无量净天、遍净天、福生天、福爱天、广果天、无想天、无烦天、无热天、善见天、善现天、色究竟天、摩醯首罗天，直到非想非非想处天，一切天众、龙众、鬼神等众，都来集会。
另外，还有其他世界及娑婆世界上的各种神祇亦来集会，包括海神、江神、河神、树神、山神、地神、川泽神、苗稼神、昼神、夜神、空神、天神、饮食神、草木神等。还有他方世界及娑婆世界中的各种鬼王，所谓恶目鬼王、啖血鬼王、啖精气鬼王、啖胎卵鬼王、行病鬼王、摄毒鬼王、慈心鬼王、福利鬼王、大爱敬鬼王等，这许多鬼王也来参加法会。
这时，释迦牟尼佛对文殊师利法王子菩萨摩诃萨说：“你看，这一切诸佛、菩萨及天龙鬼神，有来自此世界的，有来自其他世界的；有来自这方国土（即阎浮提）的，有来自他方国土的，如今都来到忉利天集会，你知道他们的数目一共有多少吗？”
文殊师利回答佛说：“世尊，以我所拥有的神通和力量，即使花上一千人劫这么长的时间来测算，也还是不能得知有多少数啊！”
佛告诉文殊师利菩萨说：“我以佛眼智慧来测算，也无法得知其确切数目，这些都是地藏菩萨从久远的、不可计量的劫数直到现在，已度脱使令成佛、正度脱使令成佛以及将度脱使令成佛的众生。”
文殊菩萨代一切众生向佛恭敬启问：“世尊啊！我于过去无量阿僧祇劫以前直到现在，勤修善根福德智慧，已彻底证悟了无碍智。因此，凡是听到佛所说的一切，都能够坚信受持。但对那些小果位的声闻、天龙八部以及未来世的一切众生，即使听到了如来真实不虚的话语，一定心里还是要生起疑惑的。即使出于恭敬，勉强接受，难免在外界的影响下说出诽谤的话来，反而使这些众生因此而造罪了。因此，我请求世尊，能否为这些众生，比较详细地介绍一下地藏菩萨摩诃萨，他从初发心时起直到现在，一直在做哪种修行，立哪种大愿，才能成就所说的那样不可思议的功德神力呢？”
佛告诉文殊菩萨说：“譬如说，将三千大千世界里所有的草木、丛林、稻麻、竹子、芦苇、山石、微尘等每一件东西记一个数，每一个数算做一条恒河；每一条恒河里有那么多的沙；将这么多的恒河里所有的沙，每一粒沙子算做一个世界；每一个世界都碎成微尘，每一粒微尘算做一个大劫；将一个大劫里所积的微尘数，再统统算为劫数。地藏菩萨自从证到十地果位以来所经过的劫数、度化的众生，远远超过上述比喻的数量之千倍。更何况地藏菩萨在声闻、辟支佛时所修行的时间与度化的众生，那更是多得无法想象了。文殊师利，这位菩萨的神通威力、宏誓大愿真是不可思议。倘若在未来世界里，有善男子或善女人，有缘能听到地藏菩萨的名号，或是赞叹，或是恭敬瞻礼，或是称念地藏菩萨的名号，或是拿灯烛、香花、饮食、衣服、燃香、果品等供于菩萨像前，或是绘画地藏菩萨形象、用玉石雕刻地藏菩萨形象、用土木胶漆彩帛等塑造地藏菩萨的形象，此人即能够以上述的功德，上升至忉利天，往返生于三十三天，永不会堕落到恶道中去。”
“文殊师利，这位地藏菩萨摩诃萨，在过去久远不可说不可说大劫之前，有一次投生为一位大长者家的儿子。在那个时代里，正好有一位佛住世，佛的名号称狮子奋迅具足万行如来。这位大长者子见到佛的相貌威仪非常的美好，兼备了千种的福慧与庄严。因此想要知道其原因，就来到佛前恭敬发问，立了什么样的誓愿，做了什么样的功德，才能感应到这种圆满的妙相。当时狮子奋迅具足万行如来就告诉长者子说：‘要想修证到这样圆满微妙的相貌和身形，应当在非常长久的遥远年代里，以佛法的清净智慧去度脱一切受苦的众生。大长者子听佛这样说了以后，就在佛前立下宏誓大愿说：‘我发愿，从今天起，以至尽未来际无数劫的岁月里，为一切六道中受苦的众生，以佛法的智慧，用种种方便使他们都能解脱生死，而后我自身再证得涅槃而成佛。’正是由于大长者子在狮子奋迅具足万行如来前发了如此誓愿。所以直到今天，虽然已经经过了百千万亿那由他不可说的大劫这么长的时间，仍然行菩萨道，度化众生。”
“再者，在过去不可思议无量数劫以前，当时世上有佛住世，号为觉华定自在王如来，寿命为四百千万亿无量数劫。在觉华定自在王佛教化的像法时代中，有一位出身婆罗门的女子，由于曾在过去无量世当中积累了无量的善根与福德，因此为大众所尊重钦佩，无论何时何地，行住坐卧之时总有天神在暗中保护着她。她的母亲不聿信了邪教邪说，非但不信佛，反而还常常轻视佛法僧三宝。为此，这位圣女想尽了种种方法，劝说、诱导她母亲，希望母亲能产生正知正见。但其母由于业障太重，善根太少，始终对佛法三心二意，不能完全信仰奉持。不久之后，她母亲寿终，魂神堕落到无间地狱中去了。婆罗门女知道其母亲在世时不相信因果报应，以其所做的恶业，命终之后，一定会堕入恶趣。为了救度母亲，她就变卖了自己的家园房舍及种种资产，筹办购买了上好名贵的香和花，以及其他各种供佛所用的器具物品，在各处佛像、宝塔、寺院当中一心供养。在一座寺院里，她见到一尊觉华定自在王如来的塑像，其形象威严慈祥、亲切端庄，惟妙惟肖，形神兼备，栩栩如生。当时，婆罗门女恭敬瞻礼佛的尊容时，心里升起加倍的敬仰，心想‘佛的名号既然称为大觉，具备一切智而无所不知。倘若佛在世时，母亲死后，倘若我来问佛我母死后所去的生地，佛肯定能知道并会告诉我的’。怀着遗憾与悲伤，婆罗门女在佛像前，一边伤心地哭泣，一边不停地礼拜念佛。不知过了多久，忽然空中有个声音在说：‘那位正在哭泣的圣女，不要太过悲伤了，我来告诉你母亲死后所生的地方。’”
“婆罗门女听到这声音之后，非常激动，合掌向空中问道：‘是哪一位有德之神，来安慰我的忧虑？我自从失去母亲以来，日日夜夜怀着悲伤的心情忆念我的母亲，不知道她生在什么世界了。’”
“这时空中的声音再次告诉婆罗门女说：‘我就是你现在正在瞻仰礼拜的过去佛觉华定自在王如来。见你思母心切，远远超过人之常情，所以来告诉你母亲的生处。’”
“婆罗门女听到这声音，激动万分，情不自禁扑倒在地，以至于手足关节折损了。旁人赶紧过来扶住她，安慰她，过了好一会儿才苏醒过来，泪流满面地对空中说：‘愿佛慈愍于我，快点告诉我母亲所生之处吧！我如今长久思念母亲，身心交瘁，都快要死了。’”
“这时，觉华定自在王如来再次告诉圣女说：‘你等供养仪式完毕以后，早点回家，在家中净室里，端身正坐，排除一切杂念，专心忆念我的名号，到一定的时候之后，即可知道你母亲所生的去处了。’”
“婆罗门女礼佛供养之后，立刻回到自己家中，端正坐好，因思念母亲心切，一刻不敢分心，全心全意称念觉华定自在王如来的名号。经一日一夜之久，忽然间觉得自己来到了一个大海边。这大海里的水，犹如滚汤一样，沸涌不止，海水中还有许许多多极其凶恶的怪兽，身子都是以铁化成，来来往往地在海面上飞行，东奔西跑。只见海里有成千上万的男男女女，一会儿漂上来，一会儿沉下去，被这些恶兽争来抢去地吞吃，又见到各种各样形状不同的夜叉：有的生了好多只眼，有的生了好多颗头，有的生了好多只脚，等等。这些夜叉露出白森森锋利的牙齿好像刀剑一样，它们追赶驱逐着这些罪人，使他们挨近恶兽，好让这些恶兽吞吃他们。不仅如此，这些夜叉也亲自动手争夺、攫取这些罪人，随意玩弄。有的把罪人的头和脚弯在一起，捆作一团；有的把他们的身体拉长压扁，如搓面团一般。这些夜叉的形状千奇百怪，种类多到数不清，令人毛骨悚然，不敢久视。婆罗门女因为有佛力加被，看到这些骇人的景象，当然不会产生恐惧的心理。”
“正在这时，有一位鬼王，名字叫无毒，恭敬作礼来迎接圣女，对他说：‘善哉，菩萨，您为什么到这里来呀？’”
“婆罗门女问鬼王说：‘这儿是什么地方？’”
“无毒鬼王回答说：‘这儿是大铁围山西面的第一重海。’”
“圣女问：‘我听说大铁围山内是地狱，这是真的吗？’”
“无毒回答说：‘大铁围山里边，确确实实是地狱的所在。’”
“圣女又问：‘我怎么会来到地狱呢？’”
“无毒回答说：‘倘若不是依靠佛菩萨的威神之力，那便是因为本身所造地狱之业而来。除了这两种力量，谁也无法到这个地方来。’”
“圣女又问：‘这里的海水为什么会像沸汤一样上下涌沸啊？为什么在海里有那么多的罪人和种种凶恶的怪兽呢？’”
“无毒回答说：‘这些都是阎浮提的造恶众生，新死不久，经过七七四十九天后，由于没有亲戚、子女、朋友为他们做超度功德，使他们能脱离这地狱的苦难；同时，他们生前又没有好好修善，没有求得佛法僧三宝力量的加持，所以按照他们生前所做的恶业，就感应到地狱来了。一般来说，在进入地狱之前，要先渡过这一重海，此海往东过去有十万由旬，又有一海，那里的痛苦比这一重海还要加重一倍。在那重海的东边，又有一海，其中的苦楚更是倍上加倍。这三个业海都是由于众生身、口、意三业所造的恶因，而感招的痛苦之果。通常所称的业海，指的就是这儿。’”
“圣女又问鬼王无毒说：‘那么，地狱又在什么地方呢？’”
“无毒回答说：‘在三重海之内就是大地狱，其数有好几千，大大小小都不一样。所谓最大的，就有十八个。其次大的，有五百个，那里边的苦难和刑罚真是一言难尽。再其次的，就是小地狱也有千百之数，每个里边也有无量的苦难，真是苦海无边啊。’”
“圣女又问大鬼王说：‘我母亲去世时间不长，不知道她的魂神在哪里？’”
“鬼王问圣女道：‘菩萨，您的母亲生前的所作所为是怎样的呢？’”
“圣女回答说：‘我母执著邪见，相信外道，以至于常常讥讽毁谤三宝。虽然有时经过劝说，暂时相信三宝，过不久就又不信不敬了。虽然去世时间不长，可我却不知道她投生到什么地方去了。’”
“无毒再问圣女说：‘菩萨的母亲姓什么，叫什么呀？’”
“圣女回答说：‘我父我母都属于婆罗门种姓，父亲叫尸罗善现，母亲叫悦帝利。’”
“无毒听了以后，恭敬合掌告诉圣女说：‘圣女，您不必再忧伤挂怀，可以放心地回家了。这位悦帝利罪女已脱离地狱，升到天上，如今已经有三天了。据说多亏有孝顺的子女为她设供修福，布施觉华定自在王如来塔寺，不但菩萨的母亲得以脱离了地狱之苦，就是在无间地狱里受苦的一切罪人，也都在这一天里做菩提座解脱了地狱之苦，升到善道受乐了。’”
“鬼王说完之后，恭敬地向圣女合掌，抽身而退。”
“此时婆罗门女仿佛大梦初醒，又回到了自己家中的佛堂。待明白了此事的前因后果，觉悟到生死业缘、因缘果报、佛力加持的不可思议，随即来到觉华定自在王如来的塔像之前，立下宏誓大愿说：愿自今日起直到遥远的未来之际，所有一切造罪受苦的众生，我都要用种种方法和智慧，使他们得到彻底解脱。”
佛告诉文殊师利菩萨说：“刚才所说的无毒鬼王，就是现在的财首菩萨，婆罗门女就是现在的地藏菩萨。”', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f825914587d02f66f22", "shortContent": "这个短篇借神鬼以讽刺世情，文笔绝妙，值得一读。\n曲阿的这位尊神，虽然颇有灵应，却是一个贪婪之徒，做事不论是非，不讲原则。许他一口猪，哪怕你是一个打家劫舍的强盗，他也照样庇佑；许他一头牛，他就来一个一百八十度的大转弯，公然出尔反尔。仗着他有些权力，有些神通，居然可以把是非公道当作商品一样公开拍卖！\n其实，读了这篇文章之后，谁都心里明白，这里写的哪里是什么神祇，分明是现实生活那些贪官污吏的真实写照。作...", "authors": ["范民声"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa70f8fda556506e4f3", "shortContent": "解脱的概念源自佛教“四谛说”之一的“灭谛”。谛，即真理。灭谛，讲佛教最高理想的无痛苦状态。灭，系指人生苦难的灭寂、解脱。一念解脱，即是讲在一念之间就获得了解脱人生痛苦、烦恼的途径与方法。本篇正是用一个故事，形象化地诠释了佛教的这一理论，图解倾向十分明显。故事叙述一个叫静弟的和尚在未出家时，因山行迷路，投宿于一破庙之中，遇到一个和尚来与之交谈并巧妙地引诱他投环上吊。正感痛苦不堪之际，那个和尚又将他解...", "authors": ["胡邦炜"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b9434bfda01e0eab209", "bookTitle": "唐宋小说鉴赏辞典", "articleId": "610f43e434a8757d5a0fb646", "shortContent": "降魔变神押座文\n君不见生来死去，似蚁脩环，为衣为食，如蚕作茧。假使有拔山举顶（鼎）之士，终埋在三尺土中。直饶玉提[3]金绣之徒，未免于一椷[4]灰烬。莫为久住，看则去时，虽论有顶之天，总到无常之地。少妻恩厚，难为与之替死之门；爱子情深，终不代君受苦。忙忙（茫茫）浊世，争恋久居；模模（漠漠）昏迷，如何拟去。不集开常意树，早折觉花，天宫快乐处，须生地狱下。波吒[5]莫去死，去了却生来。合叹伤，争[6]...", "authors": ["侯会"], "pressName": "上海辞书出版社"}]', '', 'indent', 1523464762, '5acdc92917d00900318c00aa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637115, '地藏经 · 分身集会品第二', NULL, 11, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%88%86%E8%BA%AB%E9%9B%86%E4%BC%9A%E5%93%81%E7%AC%AC%E4%BA%8C/5251472', '', '尔时百千万亿不可思、不可议、不可量、不可说无量阿僧祇世界，所有地狱处，分身地藏菩萨，俱来集在忉利天宫。以如来神力故，各以方面，与诸得解脱从业道出者，亦各有千万亿那由他数，共持香华，来供养佛。
彼诸同来等辈，皆因地藏菩萨教化，永不退转于阿耨多罗三藐三菩提。是诸众等，久远劫来，流浪生死，六道受苦，暂无休息。以地藏菩萨广大慈悲，深誓愿故，各获果证。既至忉利，心怀踊跃，瞻仰如来，目不暂舍。
尔时，世尊舒金色臂，摩百千万亿不可思、不可议、不可量、不可说、无量阿僧祇世界诸分身地藏菩萨摩诃萨顶，而作是言：吾于五浊恶世，教化如是刚强众生，令心调伏，舍邪归正，十有一二，尚恶习在。吾亦分身千百亿，广设方便。或有利根，闻即信受；或有善果，勤劝成就；或有暗钝，久化方归；或有业重，不生敬仰。如是等辈众生，各各差别，分身度脱。
或现男子身、或现女人身、或现天龙身、或现神鬼身、或现山林川原、河池泉井，利及于人，悉皆度脱。或现天帝身、或现梵王身、或现转轮王身、或现居士身、或现国王身、或现宰辅身、或现官属身、或现比丘、比丘尼、优婆塞、优婆夷身、乃至声闻、罗汉、辟支佛、菩萨等身、而以化度。非但佛身，独现其前。
汝观吾累劫勤苦，度脱如是等难化刚强罪苦众生。其有未调伏者，随业报应。若堕恶趣，受大苦时，汝当忆念吾在忉利天宫，殷勤付嘱。令娑婆世界，至弥勒出世已来众生，悉使解脱，永离诸苦，遇佛授记。
尔时，诸世界分身地藏菩萨，共复一形，涕泪哀恋，白其佛言：我从久远劫来，蒙佛接引，使获不可思议神力，具大智慧。我所分身，遍满百千万亿恒河沙世界，每一世界化百千万亿身，每一身度百千万亿人，令归敬三宝，永离生死，至涅槃乐。但于佛法中所为善事，一毛一渧，一沙一尘，或毫发许，我渐度脱，使获大利。唯愿世尊，不以后世恶业众生为虑。
如是三白佛言：唯愿世尊，不以后世恶业众生为虑。
尔时，佛赞地藏菩萨言：善哉！善哉！吾助汝喜。汝能成就久远劫来，发弘誓愿，广度将毕，即证菩提。', '《分身集会品第二》出自佛教经典《地藏经》。这一品讲述了在无量世界所有地狱处度生的分身地藏菩萨，以及地藏菩萨救度的解脱者，都来到忉利天宫，听释迦牟尼佛讲法。', '分身：即化身。佛菩萨为了化导众生，应众生的机缘而化作不同的身份，将一身化出无穷无尽的分身来，皆同一形，以地上菩萨能破一分无明，证一分法身者，即可分身。法身证得越多，分身越多。而与化身不同，化身为度有缘众生，应机赴现，形相种种皆不相同也。
业道：梵文Karma—marga，善恶业招感苦乐果报的场所或通路。一般分十善业道与十恶业道两类，这里主要指恶趣恶道。　业道：业者造作义；道者能通义。业道者，以烦恼为因，发动身三口四意三此十业，造诸种种有漏之业，而感天、人、恶趣之苦果，六道轮转，故名业道。
不退转：梵语阿跋致，不退转于成佛之道的意思。以菩萨所修之功德善根越增越进，不会退失转变也，是菩萨阶位名，经一大阿僧祗劫之修行方到此位，是人不为诸魔所动，更不退转。不退转有三方面：位不退，入十住位，无复退堕恶道及生死流转，发菩提心，破见思惑也。行不退，入于初地，成就真唯识观，利他之行不退，破尘沙惑也。念不退，八地以上，得无功用智，念念入于真如实相大海，破无明惑也。
阿耨（nòu）多罗三藐三菩提：梵文Anuttara—samyak—sam—bodhi的音译，意为无上正等正觉。
阿耨多罗三藐三菩提：佛智之名，即无上正等正觉也。阿，无也；耨多罗，上也；三，正也；藐，等也；菩提，觉也。其道无极称“无上”；其道至正至遍，为“正等”也；其道至正至慧，为“正觉”也，合之乃真正平等觉知一切真理之无上智慧也。“正觉”，区别于众生的不觉与外道的邪觉；“正等”区别于小乘的独觉；“无上”区别于菩萨觉行未能圆满也。故知“无上正等正觉”乃唯佛方可称得也。
果证：依因位之修行而得果地之证悟也。如修四谛道的，可得声闻四果的证悟；修十二因缘的，可得缘觉、独觉的果证；修六度万行的，可得菩萨四十二阶位的证悟。
金色臂：佛身紫磨真金色。紫磨真金乃黄金中最上品。用以表佛身无上也。紫者，紫色；磨者，无垢浊，表佛身清净。以佛身清净故，有忍辱柔软之相。金色臂乃佛紫磨真金色之手臂也。
摩顶：佛为嘱累大法，摩弟子之顶；或为授记摩顶。此处是佛为慰劳地藏菩萨度生，日日三时在地狱教化众生，赞其不辞劳苦而摩顶也。
五浊：又名五滓、五浑等，住劫中人寿二万岁以后，而有浑浊不净之法五种。一、劫浊：人寿二万岁以后，四浊叠起，此劫名劫浊，以四浊聚于此时而名之也；二、见浊：众生具种种邪见（见前“邪见”条所注），以此邪见引起余四浊也，乃五浊之主体；三、烦恼浊：以众生具邪见，复以无量生死来种种无明引起烦恼，如贪嗔痴慢疑等，为迷于世间事物而起之惑，为五钝使，亦为五浊之主体；四、众生浊：以众生之见浊、烦恼浊盛故，人间果报渐衰，心钝体弱，苦多福少，名众生浊；五、命浊：以众生之见浊、烦恼浊盛故，人命渐减乃至十岁，名命浊。此五浊中，以见浊，烦恼浊为浊之主体；众生浊、命浊、劫浊为前二浊之结果。
利根：利者，锐利也，闻法速疾即得妙解也；根者，常指根器、根性，亦指信、进、念、定、慧之五根或眼、耳、鼻、舌、身之五根，这里指具有深厚智慧及善根的众生，闻法即得妙解，能速证无生法忍者或至少能得声闻初果者。利根之人修出世间法易。就佛教来说，特别指易于觉悟得解脱的根器。
天帝：即释提桓因，帝释天原为摩揭陀国之婆罗门，由于修布施等福德，遂生忉利天，且成为三十三天之天主。
梵王：大梵天王的异称。大梵天为初禅天之王，所以叫大梵天王，总管色界诸天。
转轮王：转轮圣王的简称，指成就七宝，具足四德，统一须弥四洲，以正法治世的大帝王，是佛教政治理想中的统治者。　转轮王：又称转轮圣帝、转轮圣王、轮王。此王身具三十二相，即位时，由天感得轮宝，转其轮宝降伏四方，故称转轮圣王。又能飞行空中，故称飞行皇帝。其轮宝有金银铜铁四种，依次统领四、三、二、一大洲。在增小劫，人寿两万岁以上则生；在减小劫，人寿自无量岁到八万岁时才生。
居士：居家之佛教徒。梵文原语为Grhapati，意译为长者、家主、家长。在印度，是指从事工商业的富豪，或在家有道之士；在中国，则称学德高而未有出仕的人为居士，即处士之意。
宰辅：辅助皇帝、身居要位的官员。现代而言，指一个国家里执掌党、政、军等的高级干部或官员。
（15）官属：为政府所用的官僚。现代而言，指一般地方上的官员。
比丘：梵文Bhiksu，音译比丘、苾刍、备刍、比呼等，意译为乞士，言其上从如来乞求佛法而养育法身慧命，下从世俗乞求衣食以存活色身，指受过具足戒的男性出家人。
比丘尼：梵文Bhiksuni，指受过具足戒的女性出家人。
优婆塞：梵文、巴利语Upasaka的音译，汉译作清信士、近善男、近事男、善宿男。指皈依三宝，受持五戒、八戒等男性在家信徒。
优婆夷：梵文、巴利语Upasika的音译，又作优婆私，汉译作清信女、近善女、近事女、近宿女。指皈依三宝，受持五戒、八戒等女性在家信徒。
弥勒：梵文Maitreya，音译梅哩丽耶、末怛唎耶等，意译为慈氏。　弥勒：新称弥帝隶，每怛哩，菩萨之姓，译作慈氏；名阿逸多，译作无能胜，生于南天竺婆罗门家，绍释迦如来之佛位，为补处菩萨，今在兜率天内院，经人间五十六亿七千万岁下生人间，于华林园龙华树下成正觉。此菩萨过去值佛修慈心三昧，故称慈氏。
授记：又作授决、受别、记别等。本指分析教说，或以问答方式解说教理；转指弟子所证或死后之生处；后专指未来世证果及成佛名号之预言。　授记：梵云和伽罗，佛对发心之众生授予当来必当作佛之记别也。有多种授记，今举其二种：一为二种授记：无余记，佛现前授记某众生于某劫中成佛，立何名号，国土，眷属等等了了记明，名无余记；有余记，佛告某众生于未来某佛时当毕此罪，此佛将与汝授记，此名有余记。一为四种授记：一、未发心而与授记，此众生根性猛利，好乐大法，佛为此众生说成佛时间及国土，名号等等，与无余记授记内容同；二、适发心已得授记，此人久植德本，勤心精进，初发心即得不退转，入菩萨位，佛为之授记；三、秘密授记，若菩萨志求无上菩提当得授记，然恐其自满自足，不复精进，故佛以神力，密作授记，令他人得闻而已不闻也；四、现前授记，菩萨久集善根，悉皆具足，常修梵行，观无我空，得无生忍，佛知是人功德智慧已具足，于一切大众前，现前作无余记也。
涅槃：梵文Nirvana，又音译作泥洹、涅槃那等，汉译灭、灭度、寂灭、不生、圆寂。　23）涅槃：又作泥洹，旧译为灭度、寂灭、不生、无为、安乐、解脱，新译作圆寂。灭度者，灭生死之因果，度生死之瀑流也；寂灭者，寂乃无为空寂安稳之意，灭乃灭生死之大患也；不生者，以灭生死之因果，故不生也；无为者，无惑业因缘之造作也；安乐者，安稳快乐也；解脱者，解生死之系缚，脱三界之牢笼也。涅槃分有余及无余两种，有余涅槃者，生死因之惑业已尽，犹余有漏依身之苦果也；无余涅槃者，更灭依身苦果令无所余也。有余涅槃生时可证，无余涅槃死时方得。小乘以了分段生死谓得涅槃，大乘以了变易生死谓得涅槃。
三白佛言：指地藏菩萨用同样的话对佛连说三次，表明他下了很坚定的决心。
菩提：梵文Bodhi的音译，意译为智慧、知、觉，旧译为道，指佛的最高的智慧。菩提为佛教的根本理念与最高目标，佛教主要在说明菩提之内容，及证取菩提的实践方法。', '就在这时，百千万亿不可思议、不可称量、不可说的无量阿僧祇世界里，所有在地狱当中救度众生的分身地藏菩萨统统集合到忉利天宫。与此同时，由于依仗佛力的加持，那些曾经得到地藏菩萨教化与救度，从业道中解脱出来的千万亿那由他数的种种众生，也都有幸同到忉利天宫来，手捧种种名贵的香和花来供养佛。这些众生，从无量劫以来，一直在生死苦海里流浪，在六道轮回中受苦，片刻也得不到安宁。正因为受到地藏菩萨誓愿的召感与慈悲的教化，他们对于佛法具有了坚定的信念，每一位都证到了一定的果位，在走向无上正等正觉的路程当中永不退转。承蒙佛力的加持来到忉利天宫，心里十分地欢喜激动，以无比恭敬心瞻仰如来，目不暂舍。这时，释迦牟尼世尊伸出金色的手臂，以神通力摩百千万亿不可思、不可议、不可量、不可说无量阿僧祇世界中所有分身地藏菩萨顶，对他们说：“我在五浊恶世当中教化这些冥顽固执的众生，使他们的心性趋于调伏、柔和，抛弃邪恶的思想和行为，归到佛法的正道上来。大多数的众生经过我的教化，都有不同程度的改变，有的也证到一定的果位；但还有十分之一二的众生很难改得了他们无始生死以来所染的种种恶习。为此，我也曾分身千百亿，用尽种种的方法去教化。有的善根比较深厚，智慧比较开明的，听了我的教导后，当即就信服并接受我的教化；有的善根比较深厚，而智慧稍差些的，经过我多次的劝化，也有了种种的成就；有的善根比较肤浅，智慧也很低下，那就要经过长期耐心的教化方能使他们归向佛道；有的众生业障深重，根本对三宝不生敬仰心，极其难以教化。像这些众生，有各种各样不同的情况，我都分成无量化身去度脱他们：或是化现男子的形象；或是化现女人的形象；或是化现天龙的形象；或是化现神鬼的形象；或是化现山、河、树林、平原、湖泊、池塘、泉水、井水去利益众生，使他们感到佛力的不可思议而得到度脱；或是化现天帝的形象；或是化现梵王的形象；或是化现转轮王的形象；或是化现居士的形象；或是化现国王的形象；或是化现宰辅的形象；或是化现官属形象；或是化现比丘、比丘尼、优婆塞、优婆夷的形象；乃至化现为声闻罗汉、辟支佛、菩萨等种种形象，随众生的根基和机缘来度脱他们，而非仅仅以佛身的形象来化度众生。”“你看我从久远劫来辛勤劳苦地度脱这些难教难化、冥顽固执的罪苦众生，那些至今还没有教化、调伏过来的，免不了要受因果规律的支配，依照自己所造的种种恶业得到应有的报应。这些罪苦众生倘若堕落到恶道中受大苦时，你应当想到我在忉利天宫再三殷地嘱咐——让娑婆世界里那些直到弥勒佛出世以来的一切众生，你要以神通智慧使他们都得到解脱，永远脱离种种苦难，直到他们在将来能够遇佛授记，决定成佛。”这时，从一切世界出来的无量分身地藏菩萨，恢复合为一身，深为本师释迦牟尼佛为一切众生的解脱所做的种种难行苦行及佛陀对他的殷切期望与郑重嘱托所感动，泪流满面，伤感而仰慕地对佛表白自己的心意：“我从遥远的往昔无数大劫以来，承蒙佛的接引与教导，使我获得了不可思议的神通威力，具足无量的般若真智。我所有的分身，遍布百千万亿恒河沙数的世界；每一世界里，又化现百千万亿的化身；每一个化身又度脱百千万亿人，使他们都能皈依、尊敬三宝，永远脱离生死轮回，得到不生不灭的涅槃之乐。这些人中，为护持佛法久住所做的善事，哪怕轻如鸿毛，小如水滴，细如微尘，尖如毛端的点滴功德，我都会想方设法度化他，使他走上佛法的正道，获得脱生死、永离苦难的利益。请世尊放心，不必担心后来世造恶业的众生。”地藏菩萨就这样连说了三遍：“请世尊放心，不必担心后来世造恶业的众生。”魔王得梦这时，佛称赞地藏菩萨说：“善哉善哉，我也随喜赞叹你的功德和你救度一切众生的伟大心愿。你从久远的大劫以来一直诚恳地发度脱一切众生的宏誓大愿。我也向你保证，一旦你把这些众生度尽之后，马上就可以证得菩提而成佛。”', NULL, '', 'indent', 1523464839, '5acdca059f54540044e619f5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637116, '地藏经 · 观众生业缘品第三', NULL, 9, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E8%A7%82%E4%BC%97%E7%94%9F%E4%B8%9A%E7%BC%98%E5%93%81%E7%AC%AC%E4%B8%89/5251314', '', '尔时佛母摩耶夫人，恭敬合掌问地藏菩萨言：圣者，阎浮众生，造业差别，所受报应，其事云何？地藏答言：千万世界，乃及国土，或有地狱、或无地狱；或有女人、或无女人；或有佛法、或无佛法，乃至声闻辟支佛，亦复如是，非但地狱罪报一等。
摩耶夫人重白菩萨：且愿闻于阎浮罪报所感恶趣。
地藏答言：圣母，唯愿听受，我粗说之。
佛母白言：愿圣者说。
尔时地藏菩萨白圣母言：南阎浮提，罪报名号如是。若有众生不孝父母，或至杀害，当堕无间地狱，千万亿劫求出无期。若有众生出佛身血，毁谤三宝，不敬尊经，亦当堕于无间地狱，千万亿劫，求出无期。若有众生侵损常住，玷污僧尼，或伽蓝内恣行淫欲，或杀或害，如是等辈，当堕无间地狱，千万亿劫，求出无期。若有众生，伪作沙门，心非沙门，破用常住，欺诳白衣，违背戒律，种种造恶，如是等辈，当堕无间地狱，千万亿劫，求出无期。若有众生，偷窃常住财物谷米，饮食衣服，乃至一物不与取者，当堕无间地狱，千万亿劫，求出无期。
地藏白言：圣母，若有众生，作如是罪，当堕五无间地狱，求暂停苦一念不得。
摩耶夫人重白地藏菩萨言：云何名为无间地狱？
地藏白言：圣母，诸有地狱在大铁围山之内，其大地狱有一十八所，次有五百，名号各别，次有千百，名字亦别。无间狱者，其狱城周匝八万余里，其城纯铁，高一万里，城上火聚，少有空缺。其狱城中，诸狱相连，名号各别。独有一狱，名曰无间，其狱周匝万八千里，狱墙高一千里，悉是铁围，上火彻下，下火彻上。铁蛇铁狗，吐火驰逐狱墙之上，东西而走。
狱中有床，遍满万里。一人受罪，自见其身遍卧满床。千万人受罪，亦各自见身满床上。众业所感获报如是。
又诸罪人，备受众苦。千百夜叉及以恶鬼，口牙如剑，眼如电光，手复铜爪，拖拽罪人。复有夜叉执大铁戟，中罪人身，或中口鼻，或中腹背。抛空翻接或置床上，复有铁鹰啖罪人目。复有铁蛇绞罪人颈。百肢节内，悉下长钉，拔舌耕犁，抽肠剉斩，烊铜灌口，热铁缠身。万死千生，业感如是。动经亿劫，求出无期。
此界坏时，寄生他界，他界次坏，转寄他方；他方坏时，辗转相寄。此界成后，还复而来。无间罪报，其事如是。
又五事业感，故称无间。何等为五？
一者、日夜受罪，以至劫数，无时间绝，故称无间。
二者、一人亦满，多人亦满，故称无间。
三者、罪器叉棒，鹰蛇狼犬，碓磨锯凿，剉斫镬汤，铁网铁绳，铁驴铁马，生革络首，热铁浇身，饥吞铁丸，渴饮铁汁，从年竟劫，数那由他，苦楚相连，更无间断，故称无间。
四者、不问男子女人，羌胡夷狄，老幼贵贱，或龙或神，或天或鬼，罪行业感，悉同受之，故称无间。
五者、若堕此狱，从初入时，至百千劫，一日一夜，万死万生，求一念间暂住不得，除非业尽，方得受生，以此连绵，故称无间。
地藏菩萨白圣母言：无间地狱，粗说如是。若广说地狱罪器等名，及诸苦事，一劫之中，求说不尽。摩耶夫人闻已，愁忧合掌，顶礼而退。', '《观众生业缘品第三》出自佛教经典《地藏经》。在这一品中，佛母摩耶夫人向地藏菩萨询问阎浮提众生的造业差别及所感恶趣的情形，地藏菩萨为佛母讲述了无间地狱的造业因缘。', '摩耶夫人：释迦牟尼之母，为古印度迦毗罗卫城净饭王之妃。临产前依时俗返回娘家待产，途中于其父天臂城蓝毗尼园（今尼泊尔境内）休息时，生下释尊，七日后逝世，生于忉利天。
圣者：圣者，正也。发无漏真智而证真理之人曰圣者。乃见道位以上者。见道者，初发真无漏智而观谛理，以断一切见惑之位。声闻乃四加行后之预流向，菩萨为初地之入心。复有修道（断修惑，菩萨为初地至十地位）、无学道（证理究竟，声闻为罗汉果，菩萨为佛果）。
出佛身血：五逆罪之一。五逆者，杀父、杀母、杀阿罗汉、出佛身血、破和合僧，其罪次第而递增。以前二者背恩养故，后三者违福田故。以父母乃身之所出，命之所养，杀父母乃极背逆恩德，故重；以阿罗汉、佛乃福田也，杀之或出血之，乃违福田。而破坏和合僧众，使令斗争，则三宝断绝，乃五逆中罪业最大者。
常住：指往来僧众办道的地方。此外，亦指属于寺院全体的东西，如田园、杂具之类，为僧众所共用。常住：法无生灭变异谓之常住。常住有三种，指佛的法身、报身、化身常住也。此处指常住物，即四种僧物：一、常住常住：众僧之厨库寺舍众具、华果树林田园仆畜等也，乃永久之物；二、十方常住：日日供僧之常食，乃取常住常住而入当日之常食也。属十方僧人之物；三、现前现前：各比丘所属之私物，乃现前僧人之现前物也；四、十方现前：亡僧所遗之物，可分与十方僧人为现前物者。
伽蓝：梵文Samgharama，音译为僧伽蓝摩，或作僧伽蓝，汉译为僧园、僧院。原指可供建设众僧居住之房舍的用地，后指僧人聚合修行的清净闲静之所，也就是通常所说的寺院。　5）伽兰：梵语僧伽兰摩之略音，译作众园。为僧众所住之园庭，乃寺院之通称也。又伽兰神之简称。伽兰神乃护卫伽兰之神。《释氏要览》上云：“七佛经云，有十八神护伽兰，一、美音；二、梵音；三、天鼓；四、叹妙；五、叹美；六、摩妙；七、雷音；八、师子；九、妙叹；十、梵响；十一、人音；十二、佛奴；十三、颂德；十四、广目；十五、妙眼；十六、彻听；十七、彻视；十八、遍视”。亦有以汉将关羽为伽兰神者。
沙门：梵文Sramanaka，又音译为沙门那；汉译的名称很多，如息、息心、静志、净志、乏道、贫道、功劳、勤息等，指出家的僧人。
白衣：梵文Avadata—vasana，原意白色之衣，转称著白衣者，即指在家人。印度人一般皆以鲜白之衣为贵，故僧侣以外者皆著用白衣，佛典中亦多以“白衣”为在家人之代用语。
无间：八大地狱之第八地狱，谓之无间，以有五种无间也。一、趣果无间：感此狱之罪，为顺现业或顺生业，在造业与受果之间决无隔他生者。二、受苦无间；三、时无间；四、命无间：寿命相续死而复生；五、身形无间：地狱广八万由旬，身形亦八万由旬，无些少空处。经中五无间，受苦、身形、时无间与上述同，而有两种不同：一、罪器无间：种种罪器充满而无间；二、众类无间：种种众生同一受之而无间也。
一十八所：指十八地狱。一、光就居：人居此中相见即欲斗，自然而有兵器出现供相杀，无岁数，又不死，以人间三千七百五十岁为一日，三十日为一月，十二月为一年，经一万岁，即人间一百三十五亿岁。二、居虚略，此中一苦当前二十，其人入火中赤身出而相斗，以人间七千五百岁为一日，其寿两万岁（已下之狱中苦与日、年寿之倍增皆例此也）。三、桑居都：其人常被火烧。四、楼：其人常居大火铁城中。五、房卒：于大深谷之火中烂烧而不死。六、草乌卑次：于高二千里、广四千里之火城中烂烧而不死。七、都卢难旦：大火铁贯其人。八、不卢半呼：常在火中炮炙。九、乌竟都：寒冷冻身。十、泥卢都。十一、乌略。十二、乌满。十三、乌藉。十四、乌呼。十五、须健居。十六、末都乾直呼。十七、区逋途。十八、陈莫。见《十八泥犁经》中详述。
周匝：匝，音杂，就是周围、周长、四周之意。
（11）拖拽：拽，音‘知外’合，就是拖、拉、扔的意思。
（12）缴罪人颈：缴，音搅，同绞，有缠绕、勒吊之意。
（13）烊：音洋，熔化了的金属。用高温把金属熔化成液体。
（14）碓：音对，舂谷的设备。。掘地安放石臼，上架木杠，杠端装杵或缚石，用脚踏动木杠，使杵起落，脱去谷皮或舂成粉。用水力的称为水碓。
（15）斫：音卓，用刀或斧砍削也。
（16）生革络首：“革络”在此作动词用。依《实用汉语字典》（上海辞书出版社1985年8月第一版）的1346页注，“革”通“勒”。《诗·小雅·蓼萧》：“革忡忡”；684页注，“络”，缠绕，故知此句之义为“以生铁制成之索练缠在罪人的头或颈上，令其痛楚至死”也。此处之“革”，非指皮革（非作名词用），以本经中《地狱名号品第五》中云：“各各狱中，有百千种业道之器，无非是铜、是铁、是石、是火，此四种物，众业行感”。可知地狱刑具中，更无皮革之类充作刑具也。
（17）羌胡夷狄：羌，古族名，主要分布在今甘肃、青海、四川一带，最早见于甲骨文的卜辞中，殷周时杂居中原，秦汉时称西羌，居于四川省，成为现代的羌族。胡，中国古代对北方和西方各族的泛称。夷，中国古代对东方各族的泛称。有时也泛指外国人。狄，古族名，春秋前长期活动于齐、鲁、晋、卫、宋、邢等国间，主要居于北方，故称北狄。羌胡夷狄通常称为外族，这里指无论何方的众生，含有广义的意思。
（18）愁忧：愁罪人之受苦无有穷尽，忧已力之未充，无能相助也。
顶礼：又称头顶礼足、头面礼足、头面作礼、头面礼、五体投地等。这是古印度最高的敬礼。', '这时，佛的生母摩耶夫人向地藏菩萨恭敬合掌询问道：“圣者，阎浮提的众生造业有大有小，千差万别，他们所受的果报也有种种不同，具体来说又是怎样的呢？”地藏菩萨回答说：“千千万万的世界或国土中，有的有地狱，有的没地狱；有的有女人，有的没女人；有的有佛法流传教化，有的没有；或者如声闻、辟支佛一样的圣者及其教法，有的有，有的没有。不单单是地狱才算是罪报。”摩耶夫人重又请教菩萨说：“圣者，我只想听听阎浮提的众生，因造种种罪而遭受种种果报的情形是怎样的。”地藏菩萨回答说：“圣母，请您细听，我将阎浮提众生造罪受报的情形大略说一下。”佛母回答说：“请圣者讲一讲吧！”这时，地藏菩萨就对圣母讲：“南阎浮提众生造罪所得报应的情况是这样的：倘若有众生，不孝顺父母，甚至起恶心杀害父母的话，那就要堕入无间地狱，即使经过千万亿劫的久远时日也没有出头之日。倘若有众生出佛身血，毁谤三宝，不恭敬、不尊重佛教经典，也将要堕入无间地狱，就是经过千万亿劫的久远时日也还没有出头之日。倘若有众生侵占、损坏佛经、佛像、经典及寺院的财产物品，勾引僧人或奸污尼众，或是在寺庙里恣意搞邪淫的活动，或是杀害、打骂出家僧尼等，做了这些恶事，也要堕入无间地狱，即使经过千万亿劫的久远时日也还没有出头之日。倘若有的众生，穿了出家人的服装，假装虔诚向佛，但内心贪恋俗世，将寺庙及僧众公共财产据为己有，为了名闻和利养，欺骗居士信众，违背佛门戒律，造出种种恶业。像这样的人，也要堕入无间地狱，即使经过千万亿劫的久远时日都没有出头之日。倘若有众生偷窃寺院的用具、财物、粮食、衣物等，哪怕只是一件小东西，不经寺院或出家人同意而私自取用的话，也得要堕入无间地狱，即使经过千万亿劫的久远时间也还没有出头之日。”地藏菩萨总结说：“圣母，若有众生做了如上面所说的种种罪行的话，那就一定会堕入到五无间地狱里去受极大苦，在这期间，想要祈求哪怕刹那之间的停止都不可能啊！”摩耶夫人再次问地藏菩萨说：“为什么将这个地狱叫做无间呢？”地藏菩萨解释说：“圣母，所有的地狱都在大铁围山里边。要说大地狱，那就有十八所。其次有五百所，名称都不一样。再其次有千百所，名称也都不一样。所谓无间地狱，它的狱城周长有八万多里，城墙全都是用铁化成，城高一万里，在城墙顶上大火弥漫，连一点空隙都没有。在狱城之内，各个地狱互相连接，名称各不相同，特别有一个地狱，名字就叫‘无间’。这个无间地狱，周围有一万八千里，狱墙高一千里，也都是纯铁化成。狱墙上燃烧的火焰一直通到墙根，墙根的火焰烧到墙上，铁蛇、铁狗也都是烧得火红，喷出火来，在狱墙顶上来回奔跑，驱赶那些想爬出城去的罪人。狱中有大铁床，绵延布满一万里。若一个人受罪，可以亲眼看到自己的周身躺在铁床上遭受折磨；若千万人受罪，也都看见各自的周身躺在铁床上遭受折磨。这都是由于众生犯了众多严重的罪恶，所得到的苦报啊。另外，这些罪人还要承受许许多多各种各样其他的痛苦折磨。那里有千百个夜叉、恶鬼，张开了血盆大口，暴露出像剑一样锋利的牙齿，眼睛像闪电一样在黑暗的地狱里发光，手像铜爪一样结实，把罪人们拖来拽去。有的夜叉用大铁戟来戳罪人，有的刺中罪人的嘴巴、鼻子，有的刺中腹部或背部，把他们挑起来扔向空中，再用铁戟把罪人刺中接住，扔到大火烧红的铁床上。在空中还有许多铁鹰，专门啄食罪人的双眼；还有铁蛇缠住罪人的头颈使他们喘不过气来。罪人全身的关节骨骼里，都被钉上长长的铁钉。或者把罪人的舌头拔出来，用铁犁在上面耕犁；或者把罪人的肠子抽出来寸寸斩断；或者把烧熔的铜汁灌在罪人的口中；或者用烧红的铁水浇在罪人的身上……种种刑罚，万死千生，生了死，死了生。无间地狱里如此种种惨酷的折磨，都是由于众生过去所造的种种恶业所招感的恶报啊！罪人一旦堕入无间地狱，就要经过千万亿劫漫长的折磨，出离之日，遥遥无期。一旦这个世界毁灭之时，便会自动转生到其他世界的地狱中去；那个世界毁灭之时，再转寄到另一个世界的地狱当中，就这样循环转寄，无有休止。当这个世界重新生成之后，还会再转到这个世界的地狱中来。无间地狱里罪报的大致情况就是这样。”“此外，这个地狱之所以称为无间，是因为它是由五种特别严重的报应所组成的，所以叫五无间。第一，日日夜夜折磨不断，以至于累经劫数，也没有片刻时间的间断，故称为无间。第二，一个人身在狱中，其狱是满无间隙的，许多人身在狱中，其狱也是满无间隙的，从这个意义上来说，亦称为无间。第三，该狱中的种种刑具和刑罚的方式五花八门，种类俱全。如铁叉、铁棒、铁鹰、铁蛇、铁狼、铁狗、石碓、石磨、铁锯、铁凿、铁锉、铁斧、铁水、铁网、铁绳、铁驴、铁马等。或用铁链绞罪人的颈；或用铁水浇罪人的身体；饥饿时以铁丸子令罪人吞食；干渴时让罪人喝滚烫的铁水……就这样痛苦不堪地承受刑罚魔子谏父，一种接着一种，在无数大劫的时间里从不间断，所以称为无间。第四，无论是男是女，是汉族或是少数民族，是中国人或是外国人，无论是成人或是小孩，无论贵如君主还是贱如乞儿，无论是人类还是龙、神、天人、鬼道，不管是六道中哪一类的众生，只要生前犯有上述罪行的，都会感应到这地狱来，共同受苦，没有丝毫差别，所以称为无间。第五，一旦进入这个地狱当中，从一开始起直到百千大劫，期间的每日每夜每时每刻，都要经历万死万生的痛苦。在任何时候想要有一念间的暂停生死都不可能。除非业报已尽，方能离开地狱去别处受生，从这意义上讲，称为无间。（注：这与第一点不同。第一点说明累经劫数，强调时间的长久。这里说明一天一夜之间即经历万死万生，生死苦楚连绵不断，连一念的休息都没有，强调痛苦的程度。）”地藏菩萨最后对圣母说：“无间地狱的情形，粗略的来说就是这样，假如要详细叙说地狱里的刑具刑罚，众生受苦的惨状，那就是用上一个大劫的时间也说不完啊！”摩耶夫人听完地藏菩萨的讲述之后，深为那些在地狱当中受苦的众生而悲忧痛心，恭敬合掌，并向地藏菩萨顶礼，退回到原来的座位中去了。', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f812cee9a0c24ee78f9", "shortContent": "本篇作者是一个虔诚的佛教信徒，所著《冥祥记》为释氏辅教之书的代表作。至于本篇，则是释氏“业报轮回”这一宗教观念成功的形象表现，有令人信以为真和受其感染的力量。\n这种令人信以为真和受其感染的力量，来源于叙述赵泰的籍贯、出身、履历、品格，言之凿凿；写赵泰的猝死、苏活，为世间累见不鲜、可能出现之事；后来的“候视泰者”和“访问”泰者，姓名、籍贯、官爵尽具体确实。凡此，皆足以令人毫不生疑。\n这种令人信以为真...", "authors": ["何均地"], "pressName": "上海辞书出版社"}]', '', 'indent', 1523464988, '5acdca952f301e003fc5517f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637117, '地藏经 · 阎浮众生业感品第四', NULL, 9, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E9%98%8E%E6%B5%AE%E4%BC%97%E7%94%9F%E4%B8%9A%E6%84%9F%E5%93%81%E7%AC%AC%E5%9B%9B/5784006?fr=aladdin', '', '尔时地藏菩萨摩诃萨白佛言：世尊，我承佛如来威神力故，遍百千万亿世界，分是身形，救拔一切业报众生。若非如来大慈力故，即不能作如是变化。我今又蒙佛付嘱，至阿逸多成佛以来，六道众生，遣令度脱。唯然世尊，愿不有虑。
尔时佛告地藏菩萨：一切众生未解脱者，性识无定，恶习结业，善习结果。为善为恶，逐境而生。轮转五道，暂无休息，动经尘劫，迷惑障难。如鱼游网。将是长流，脱入暂出，又复遭网。以是等辈，吾当忧念。汝既毕是往愿，累劫重誓，广度罪辈，吾复何虑。
说是语时，会中有一菩萨摩诃萨，名定自在王，白佛言：世尊，地藏菩萨累劫以来，各发何愿，今蒙世尊殷勤赞叹。唯愿世尊，略而说之。
尔时世尊告定自在王菩萨：谛听谛听！善思念之！吾当为汝分别解说。乃往过去无量阿僧祇那由他不可说劫，尔时有佛，号一切智成就如来，应供、正遍知、明行足、善逝、世间解、无上士、调御丈夫、天人师、佛、世尊，其佛寿命六万劫。未出家时为小国王，与一邻国王为友，同行十善，饶益众生。其邻国内所有人民，多造众恶。二王议计，广设方便。一王发愿，早成佛道，当度是辈，令使无余。一王发愿，若不先度罪苦，令是安乐，得至菩提，我终未愿成佛。
佛告定自在王菩萨：一王发愿早成佛者，即一切智成就如来是。一王发愿永度罪苦众生，未愿成佛者，即地藏菩萨是。
复于过去无量阿僧祇劫，有佛出世，名清净莲华目如来，其佛寿命四十劫。像法之中，有一罗汉，福度众生。因次教化，遇一女人，字曰光目，设食供养。
罗汉问之：欲愿何等？
光目答曰：我以母亡之日，资福救拔，未知我母生处何趣？
罗汉愍之，为入定观，见光目女母堕在恶趣，受极大苦。罗汉问光目言：汝母在生，作何行业？今在恶趣，受极大苦。
光目答言：我母所习，唯好食啖鱼鳖之属。所食鱼鳖，多食其子，或炒或煮，恣情食啖，计其命数，千万复倍。尊者慈愍，如何哀救？
罗汉愍之，为作方便，劝光目言：汝可志诚念清净莲华目如来，兼塑画形像，存亡获报。
光目闻已，即舍所爱，寻画佛像而供养之，复恭敬心，悲泣瞻礼。忽于夜后，梦见佛身金色晃耀，如须弥山，放大光明。而告光目：汝母不久当生汝家，才觉饥寒，即当言说。
其后家内婢生一子，未满三日，而乃言说。稽首悲泣，告于光目：生死业缘，果报自受，吾是汝母，久处暗冥。自别汝来，累堕大地狱。蒙汝福力，方得受生。为下贱人，又复短命。寿年十三，更落恶道。汝有何计，令吾脱免？
光目闻说，知母无疑，哽咽悲啼而白婢子：既是我母，合知本罪，作何行业，堕于恶道。
婢子答言：以杀害毁骂二业受报。若非蒙福，救拔吾难，以是业故，未合解脱。
光目问言：地狱罪报，其事云何？
婢子答言：罪苦之事，不忍称说，百千岁中，卒白难竟。
光目闻已，啼泪号泣而白空界：愿我之母，永脱地狱，毕十三岁，更无重罪，及历恶道。十方诸佛慈哀愍我，听我为母所发广大誓愿。若得我母永离三途及斯下贱，乃至女人之身永劫不受者。愿我自今日后，对清净莲华目如来像前，却后百千万亿劫中，应有世界，所有地狱及三恶道诸罪苦众生，誓愿救拔，令离地狱恶趣，畜生饿鬼等，如是罪报等人，尽成佛竟，我然后方成正等正觉。
发誓愿已，具闻清净莲华目如来而告之曰：光目，汝大慈愍，善能为母发如是大愿。吾观汝母十三岁毕，舍此报已，生为梵志，寿年百岁。过是报后，当生无忧国土，寿命不可计劫。后成佛果，广度人天，数如恒河沙。
佛告定自在王：尔时罗汉福度光目者，即无尽意菩萨是。光目母者，即解脱菩萨是，光目女者即地藏菩萨是。过去久远劫中，如是慈愍，发恒河沙愿，广度众生。未来世中，若有男子女人，不行善者行恶者，乃至不信因果者，邪淫妄语者，两舌恶口者，毁谤大乘者，如是诸业众生，必堕恶趣。若遇善知识，劝令一弹指间，归依地藏菩萨，是诸众生，即得解脱三恶道报。若能志心归敬及瞻礼赞叹，香华衣服，种种珍宝，或复饮食，如是奉事者。未来百千万亿劫中，常在诸天受胜妙乐。若天福尽，下生人间，犹百千劫常为帝王，能忆宿命因果本末。
定自在王！如是地藏菩萨有如此不可思议大威神力，广利众生汝等诸菩萨当记是经广宣流布。
定自在王白佛言：世尊，愿不有虑。我等千万亿菩萨摩诃萨，必能承佛威神广演是经，于阎浮提利益众生。定自在王菩萨白世尊已，合掌恭敬作礼而退。
尔时四方天王俱从座起，合掌恭敬白佛言：世尊，地藏菩萨于久远劫来，发如是大愿，云何至今犹度未绝，更发广大誓言。唯愿世尊为我等说。
佛告四天王：善哉善哉！吾今为汝及未来现在天人众等，广利益故，说地藏菩萨于娑婆世界，阎浮提内生死道中，慈哀救拔，度脱一切罪苦众生方便之事。
四天王言：唯然世尊，愿乐欲闻。
佛告四天王：地藏菩萨久远劫来，迄至于今，度脱众生，犹未毕愿，慈愍此世罪苦众生。复观未来无量劫中，因蔓不断，以是之故，又发重愿。如是菩萨于娑婆世界，阎浮提中，百千万亿方便，而为教化。
四天王，地藏菩萨若遇杀生者，说宿殃短命报。若遇窃盗者，说贫穷苦楚报。若遇邪淫者，说雀鸽鸳鸯报。若遇恶口者，说眷属斗诤报。若遇毁谤者，说无舌疮口报。若遇嗔恚者，说丑陋癃残报。若遇悭吝者，说所求违愿报。若遇饮食无度者，说饥渴咽病报。若遇畋猎恣情者，说惊狂丧命报。若遇悖逆父母者，说天地灾杀报。若遇烧山林木者，说狂迷取死报。若遇前后父母恶毒者，说返生鞭挞现受报。若遇网捕生雏者，说骨肉分离报。若遇毁谤三宝者，说盲聋喑哑报。若遇轻法慢教者，说永处恶道报。若遇破用常住者，说亿劫轮回地狱报。若遇污梵诬僧者，说永在畜生报。若遇汤火斩斫伤生者，说轮回递偿报。若遇破戒犯斋者，说禽兽饥饿报。若遇非理毁用者，说所求阙绝报。若遇吾我贡高者，说卑使下贱报。若遇两舌斗乱者，说无舌百舌报。若遇邪见者，说边地受生报。
如是等阎浮提众生，身口意业，恶习结果，百千报应，今粗略说。如是等阎浮提众生业感差别，地藏菩萨百千方便而教化之。是诸众生，先受如是等报，后堕地狱，动经劫数，无有出期。是故汝等护人护国，无令是诸众业迷惑众生。
四天王闻已，涕泪悲叹合掌而退。', '《阎浮众生业感品第四》出自佛教经典《地藏经》。在这一品中，世尊为定自在王菩萨讲述了地藏菩萨因地发愿的两件事迹，并为四天王略述地藏菩萨度化众生所说报应之法。', '白佛言：白，表白；向佛陈说，恭敬发问，表白自心的意思。又，赞叹佛的话语，也称为白佛。
阿逸多：梵文Ajita的音译，为佛陀弟子之一。又作阿氏多、阿恃多、阿嗜多。意译无胜、无能胜或无三毒。此处当指弥勒菩萨。
唯然：应答之声，表示服从，表示同意，含有恭敬之意。
性：梵文Prakrti，与相、修相对，体之义，因之义，不变之义，即受外界影响亦不改变之本质，本来具足之性质、事物之实体（自性）、对相状而言之自体、众生之素质（种性）等。这里主要指众生长期以来为恶的习气，已经形成了一种天性。　性识：众生之根性与心识也。根有利钝，识有深浅，是为不定也。　
五道：又称五趣，指地狱、饿鬼、畜生、人间、天五种存在的境地。这五者都不能免于生死轮回。大乘经中则多说六道（趣），即于五道之外别立阿修罗一道。
迷惑障难：“迷”者，指无明，迷失真性，不见清净自性真如实相也；“惑”者，以迷故，惑于真理，有无明惑、尘沙惑、见思惑等，乃贪嗔痴一切烦恼之总名也。迷于所对之境而颠倒事理谓之惑；“障”者，以惑故，执于理而成所知障，执于事而成烦恼障。以惑起业，以业成障。障者，障碍圣道，令行人拘于三界故名。障有二、三、四、五、十等障，如二障：烦恼障（由我执起）、所知障（由法执起）；三障：烦恼障（惑）、业障（业）、报障（苦）等。“难”者，有二种：一指三恶道之苦难或六道之苦难也；一指闻法见佛之障难，指八难也。八难者，如地狱、饿鬼、畜生（无法见佛闻法）、北拘卢州、长寿天（福报胜而无法学佛）。聋盲喑哑（无法见佛闻法）、世智聪辩（自持聪明邪见，不闻法也）、佛前佛后（无法或难以见佛闻法也）。
定自在王：众生性识不定，所以出入罗网，不得解脱。这位菩萨摄心入定，所以能抉破网罗，得大自在，所以叫做定自在王。
谛听：谛者名了，了达声尘本来不生，不逐语言，详审而听。又若人听法，不起吾慢贡高，亦不起自卑轻小，以平常心认真听法，名为谛听。
善思念：闻法之时当先净虑，排除杂念，犹如量器，欲贮甘露，器不清净，必当染污。闻法亦如是，法如甘露，心如量器，杂念如污，当去杂念，净其心境，方可得清净之甘露法雨也。
一切智成就如来：能知一切之智，称一切智。佛教所说的智慧三种：一是一切智，能成就二乘小果；二是道种智，能成就菩萨道；三是一切种智，能成就佛道。
应供：梵文Arhat，音译阿罗诃，亦作应、应真。指断尽一切烦恼，智德圆满，应受人天供养、尊敬者。
正遍知：亦作正等觉，真正普遍平等的觉悟，乃三藐三菩提之意译。
明行足：亦作明行圆满，明善行、明行成。明，即阿耨多罗三藐三菩提；行足，即戒、定、慧等。佛陀以智慧为先导而修万行，故成就福慧圆满。
善逝：又作善去、善解、善说无患、好说、好去。善即好；逝即去；善逝者，即如实去彼岸不再退没生死之义。
世间解：指佛能了知世间与出世间的一切真理，既了知世间之因、世间之灭，亦了知出世间之道，于世间出世间一切事理性相，明解照了。
无上士：指如来之智德，于人中最胜，无有过之者，故称无上士。
调御丈夫：佛善能摧伏魔军，勇敢无畏，善能调御一切，故称调御丈夫。
天人师：佛陀为诸天与人类之导师，示导一切应作不应作、是善是不善，若能依教而行，不舍道法，能得解脱烦恼之报，故称天人师。
出家：梵语波吠你野，出离在家之生活，修沙门之净行也。《维摩诘经》云：“维摩诘言，然汝等便发阿耨多罗三藐三菩提心是即出家”。有三种及四种出家。三种出家者，第一、出世俗家：远离妻子儿女俗情故，又名出红尘家；第二、出三界家：能脱生死证阿罗汉；第三、出无明家：证佛法身，究竟出无明家，便成佛道。四种出家者，身心俱出家：于诸欲境心无顾恋；心出身不出：虽受用妻子而心不耽染；身出心不出：身参法侣，心犹顾恋；身心俱不出：乃俗人也。
十善：佛教对世间善行的总称，又称十善道、十善业道、十善根本业道或十白业道。清净莲华目如来：由于佛诸恶断净，德行圆满，因此他的面容，像净满的月亮一样光亮明洁；又由于佛常以慈悲的眼看待众生，因此他的眼睛像青色的莲花一样清澈无染。
清净莲华目如来：此佛以三十二相中之第二十九相，眼色如绀青相而起名。印度莲花色青，与佛眼相似，故云清净莲花目也。赞如来相好文中有：“面如净满月，眼若青莲华”，“目净修广若青莲，齿白齐密犹珂雪”。
罗汉：即阿罗汉，梵语Arhat，意译应供、杀贼、不生、无生、无学等。指断尽三界见、思之惑，证得尽智，而堪受世间大供养之圣者。
福度：罗汉已证无漏之断德，能断一切烦恼，应为人天所供养，而人天亦因之而得福，度于三恶道而得人天之上福，故称福度。
教化：又称劝化，教人化恶为善也。
光目：此光目女乃地藏王菩萨历劫修行中所应化之身，故以菩提心之功德，令目蕴慧光，睛藏神德，号曰光目。
资福；衣食住等物乃资助人之生命者，以生活所需之物资助他人以种福，是名资福。又，衣食住器等物亦为资佛道修行之外德，施之可助人增修佛道，此福德较前更大。何况以此资生之物供养贤圣，其福更不可限量矣。
志诚：志者，志愿；诚者，实德，性命之根，天得之以成天，地得之以成地，人得之而自成。志诚，有信向之意：信者，信三宝力；向者，向菩提道也。志诚有端心正意之意：直趣菩提名端心，不求余事名正意也。以志诚故，纯孝感天，故得佛现身而救度也。
稽首：梵文称和南，婆南，即敬礼、度我之意，礼拜也。西域有九等礼：一、发言慰问；二、俯首致敬；三、举手高揖；四、合掌平拱；五、屈膝；六、长跪；七、手膝踞地；八、五轮俱屈；九、五体投地。
业缘：善业为招乐果之因缘，恶业为招苦果之因缘，一切有情尽由业缘而生。《维摩诘经》云：“是身如影，从业缘生”。新译《仁王经》云：“诸界趣生，随业缘生，如影如响，一切皆空”。《法华经序品》云：“生死所趣，善恶业缘”。
暗冥：即幽冥，指三恶道（地狱、饿鬼、畜生）无真理之光之处所，通常指地狱道，亦称幻冥。地藏菩萨救苦誓愿深重，常在地狱、饿鬼、畜生道中救苦，济拔罪苦众生，故称幻冥世界教主。
卒白难竟：“卒”者，终也；“白”者，说也；“竟”者，完也。此语意为“很难说完”，“说也说不完”也。
慈哀愍我：慈者，慈悲。慈有如来慈及声闻慈之别：如来慈以无漏之功德，具足佛之十力，四无所畏，十八不共法，三十二相，八十种好之功德。而声闻无此功德，故声闻慈乃小慈也，至多施人以人天福报，无能救拔令离生死也。哀者，悲哀；愍者，怜悯。求佛菩萨以无缘大慈，同体大悲之心，哀我母之苦，愍我孝顺之心而救拔也。
梵志：梵文Brahmana，音译婆罗门、梵士，意译为净裔、净行，又称净行者、净行梵志。婆罗门志求无垢清净得生梵天，并自称由梵天之口而生，为四姓中最殊胜者，故独取梵为名。无忧国土：即西方极乐世界。
无尽意菩萨：又作无尽慧菩萨。此菩萨因观一切事相之因果报应皆为无尽，而发心上求无尽之诸功德，下度无尽之众生，故名无尽意菩萨。善知识：能够说法引导人们至于善处者，是善友，亦称善知识。
善知识：闻名为知，见形为识，更能益我菩提之道为善，故名善知识，乃相知相识导我于至善之地者，为善知识也。又，善能知真识妄，知病识药，能度众生者为善知识。《法句经》云：“善知识者，能说深法，于毕竟空中，炽然达一切法者为善知识。”《圆觉经》云：“末法众生，将发大心，求善知识，欲修行者，当求一切正知见人，心不住相，不著声闻、缘觉境界。虽现尘劳，心恒清净；示有诸过，赞叹梵行，不令众生入不律仪。求如是人，即得成就阿耨多罗三藐三菩提。”
弹指间：时名。《戒疏》云：“僧祇云：二十念为一瞬，二十瞬为弹指”，喻时间极短也。又，经中佛常有“弹指”之举，其义有三：一为许诺，如许讲法也；一为欢喜，如《法华经》中：“一时謦，俱共弹指”；一为警告，如《嘉祥法华义疏》云：“为令觉悟，是故弹指”。
归依：归者，归投；依者，依靠，于胜者归投、依靠、依伏也。《大乘义章》云：“归投依伏，故云归依。归投之相，如子归父，依伏之义，如民依王，如怯依勇”。《法界次第》云：“归以反还为义，依者凭也”。归亦作皈，含“白反”之义，即众生反黑业（恶业）归于白业（善业）之意。归有归命之意，即身命归趣于佛、归顺佛之教义、命根归于一心本元之意。
宿命：宿世之生命也。佛谓世人于过去世皆有生命。或为天，或为人，或为饿鬼畜生，展转轮回，谓之宿命。能知宿命者，谓之宿命通。
癃残：癃，音龙，手足不灵活也；又，小便不利。《素问·宣明五气篇》：“膀胱不利为癃”。残者，残疾也，如四肢、眼、耳、鼻、舌、嗓等有残缺者也。
悭吝：悭，音千，小气；吝，音林（入声），小气。《无量寿经》云：“爱保贪重”者是也，已得之物不肯舍，未得之物妄想取，正与“布施”、“舍”相反也。
畋猎：畋，音田，打猎也。
悖逆：悖，音被，违背；忤，音武，逆也，不顺从也。
鞭挞：挞，音蹋，打的意思。鞭挞，用鞭子打的意思。
哑：亦作喑哑，喑，音“音”，口不能发声；哑，口能发声而不成话语。
阙绝：阙，古时用作“缺”，缺少的意思；绝，断绝，一点也没有。
吾我贡高：亦称吾慢贡高，亦即自高自大之意。贡高：又作贡高我慢，自以为高人一等，倨傲自矜，侮慢他人。为五种根本烦恼（五盖：贪、嗔、痴、慢、疑）之一。
边地：阎浮提洲之边隅，谓之边地。又指不能见闻佛法之边隅下贱之种族。', '这时，地藏菩萨摩诃萨恭敬地对佛说：“世尊，我依仗诸佛如来威神之力的加持，能够在无量百千万亿世界里，示现种种不同的化身与形象，去救度教化一切罪业缠身的众生。倘若没有如来的慈悲威神的加持，我则不可能有这样的神通变化之力。我又承蒙佛陀的嘱托，将弥勒菩萨成佛之前在六道生死当中轮回的众生全部度脱，使他们脱离苦难。唯愿世尊安心释怀，无须挂虑，我一定不辜负您的嘱托。”这时，佛对地藏菩萨说：“一切还没能得到解脱的众生，于无量生死当中造业作恶形成了坚固的习气与强大的业力，形成善、恶无记的种子含藏于八识之中，随缘现行，没有定数，随着环境、条件的变化而变化，遇到善缘，会做点善事，得到好报，遇到恶缘，就会做坏事，得到恶报，不能自主。因此永远在天、人、畜生、饿鬼、地狱这五道中轮回不已，得不到片刻的休息。经过无量无边如同把三千大千世界化为微尘之多的劫数，受尽苦楚，却依然心存迷惑，自己制造了难以脱苦的无数障碍。就像鱼儿游入网中，在长长的生死大河里，刚出了这个网，不知不觉又游进了另一个网。这些众生，正是我忧虑挂念的。你能于无量劫以来，一次次发救度众生的宏誓大愿，一旦能圆满这些大愿，救度无量无边的罪苦六道众生，使他们最终能得到涅槃的安稳之处，那我还有什么可忧虑的呢？”佛赞叹地藏菩萨的宏誓大愿时，会中有一位菩萨摩诃萨，名叫定自在王，恭敬问佛道：“地藏菩萨从无量劫以来，都发了些什么愿，这么不可思议，令世尊在这大会中郑重其事地反复赞叹，请世尊给我们简要地说说吧！”世尊回答定自在王菩萨说：“仔细听好，善加思维，我现在就为你们分别解说地藏菩萨往昔所发大愿。在过去无量无数不可说大劫之前，有一尊佛在世宏法，佛号为一切智成就如来、应供、正遍知、明行足、善逝、世间解、无上士、调御丈夫、天人师、佛世尊，这尊佛住世的寿命为六万劫。在还没出家修行前，曾经是一个小国里的国王，同与他相邻的另一个小国的国王是朋友。他们相互约定，在国中共同推行十善法，作为治理国家的法律和道德规范，并以善政来利益国中的人民。但邻国中的人民常造种种恶业，难免要堕入三涂受苦。为此，这两个国王商议，如何才能妥善救度这些百姓，令其不遭恶道之苦。一国的国王发愿：愿自己早日成佛来度脱这些众生，使他们全部脱离苦海，得到最终的解脱；而邻国的国王发愿：若不能先使这些众生解脱三恶道苦，获得安乐，成就佛道，我将誓不成佛。”佛接着告诉定自在王菩萨说：“发愿早日成佛，度尽众生的国王，就是当时的一切智成就如来！发愿先度罪苦众生，如有一众生尚未得度，自己不愿成佛的，就是地藏菩萨！”“再举一个例子：在过去无量无数劫之前，有佛出世，名为清净莲华目如来。这尊佛的寿命长达四十劫。在佛涅槃后的像法时代里，有一位阿罗汉，游化世间，为众生作福田，施以教化，令得安乐。有一天，他遇见一个女人，名字叫做光目。这位光目女准备了许多美味的食物来供养阿罗汉。”“阿罗汉就问她：‘你知道供养阿罗汉是会得到大福报的。你想要求些什么呢？’”“光目回答说：‘我从母亲亡故那天起，就想为她做些功德，以救拔她的苦难。不知道我母亲死后，究竟投生到什么地方去了？’罗汉怜悯光目女一片纯孝之心，为她入定作观，只见光目女的母亲堕落到恶道中，正在受极大的苦。罗汉就问光目：‘你母亲活着的时候都造了些什么业啊？她现正在恶道里受极大的痛苦。’”“光目回答说：‘我母亲生前有个坏习气，专门喜欢吃鱼、鳖之类的东西，而且特别喜欢吃鱼籽、鳖蛋之类，或是炒、或是煮，放纵地大吃大嚼，所以这一辈子所吃掉的生命成千上万，不知道有多少！尊者！请您发发慈悲，告诉我用什么方法才可以救度我母亲呢？’”“阿罗汉对她十分同情，就为她想了个办法，说：‘你应当至诚恳切地称念清净莲华目如来的圣号，同时雕塑、彩画这尊佛的形象。这样，无论是死者或生者，都将获得好报。’”“光目女听了这话之后，马上把自己家中心爱之物变卖了，用这些钱财来塑画清净莲华目如来的形象，同时又以种种灯、香、花、烛、食品、幢幡等供养清净莲华目如来。在佛像前恭敬瞻礼，痛哭祈求清净莲华目如来。正在午夜之时，忽然梦见佛的金身，金光闪闪，如同须弥山那样高大，辉煌遍照。佛开口告诉光目说：‘你母亲不久就会托生在你家里，出生后，才觉出饥寒，马上就会开口说话。’”“后来没过多久，光目女家里的一个婢女生了一个孩子，还不到三天就会说话。低头作礼，悲切啼哭着对光目说：‘生死都受业力因缘所支配，各人所造的业，各人自己承受。我是你母亲，一直在黑暗的恶道里轮转，与你分别以来，几度堕入地狱里受苦。承蒙你供佛、念佛的福力，方才得以获得投生为人的机会，但也只能做一个下贱人，而且寿命很短，只有十三年，死了以后还得再次堕入恶道中去。你有什么办法可以使我脱离恶道之苦啊？’”“光目听了这话，知道这婴儿就是她母亲的转世，因此更加悲痛，哽哽咽咽地哭着说：‘你既然是我母亲转世，应当知道你自己是犯了什么罪，造了什么业，才会堕入到恶道中去的呀？’”“婢女的孩子说：‘因为犯了杀生害命以及毁谤恶口的罪才受这苦报。如果不是蒙你替我供佛修福，我是不可能暂时离开这恶道呢！’”“光目又问道：‘地狱里的罪报情形又是怎样的呢？’”“这婴儿说：‘地狱中所受的罪惨不忍说，要是详细说的话，就是几百年，几千年也说不完。’”“光目听了这话之后，悲痛得放声大哭，对着苍天发愿说：‘愿我的母亲能永远脱离地狱，在这十三年之后，消去一切重罪，永远不再经历三恶道。十方一切诸佛啊，请您们慈悲怜悯我，听我为母亲所发的广大誓愿。倘若能使得我母亲永远脱离三恶道、脱离下贱的人身，乃至脱离女人之身，所有这些永劫不再重受，我今天对清净莲华目如来像前发下大愿：愿我从今日起，直至将来百千万亿劫，所有世界、一切地狱以及三恶道中的罪苦众生，发誓要救济、超度他们，使他们永远脱离地狱、饿鬼、畜生这三恶道。不仅如此，还要使这所有的罪苦众生全都成佛以后，我才最后证得菩提而成佛。’”“光目女发下这个广大誓愿之后，就听到清净莲华目如来的声音对她说：‘光目，你能以大慈悲心，为你母亲发这么大的愿心。我以佛眼来观察，你母亲在这十三年的生命结束之后，就可以解脱往昔的罪报，转世为修行清净道的梵志，寿命为一百岁。再过了一期寿命之后，将往生无忧国土西方极乐世界，寿命不可限量，并在那里，勤修佛道，成就正果，决定成佛，将来度化的天众、人众亦如恒河沙一样无量无边难以计数。’”魔女炫媚接着，佛告诉定自在王菩萨说：“当时以福力来度光目女的阿罗汉，就是无尽意菩萨；光目女的母亲，就是解脱菩萨；光目女就是地藏菩萨！在过去无数久远的大劫之中，以慈悲心、怜悯心，发下如恒河沙之多的大愿，来普度一切众生。”“在未来的世界中，如果有那些不愿行善、专门作恶的男子女人，以及不信因果、邪淫妄语、挑拨离间、恶言伤人，甚至毁谤大乘的造恶众生，死了之后必定会堕落到恶道中去承受苦报。假如能有缘遇到通晓佛法的善知，劝他们在一念间皈依地藏菩萨，这些众生，就能够有机会从堕落三恶道的果报之中解脱出来。如果这些众生能进一步至诚恳切地皈依礼敬、瞻仰赞叹地藏菩萨，并用种种上好的香花、种种上好的衣服、种种稀有的珍宝和种种上妙的饮食来供养奉事地藏菩萨，那么这些众生在将来的百千万亿劫中，常常托生在各重天界之中享受种种适意美好快乐的生活。即使天福享尽了，下生到人间来，还能在百千劫的长久时间里，在人间做国王，具有宿命神通之力，能够回忆起自己过去世生生死死的因果业缘。定自在王，地藏菩萨有如此不可思议的大威神力，普遍地利益一切众生。在座的诸大菩萨们，应当牢记我所说的这部经，在各个世界当中广泛地宣扬、流通。”定自在王菩萨回答佛说：“世尊，请您不要心怀忧虑，我们千万亿的菩萨摩诃萨，必定能承蒙佛陀威神之力，在阎浮提世界中广泛地宣传、演说、讲解、流通这部经，以利益一切众生。”定自在王菩萨说完这番话之后，恭敬地向世尊合掌顶礼，退回到自己的座位中去。
这时，东西南北四大天王一起从座位上站起来，合掌作礼，向世尊白言：“世尊，地藏菩萨从久远的过去劫至今以来，一直发了这么多的宏誓大愿，为什么还没有把众生度完，而要发更为广大的宏誓大愿呢？但愿世尊能为我们说说这其中的道理。”佛告诉四天王说：“善哉善哉！我为你们、同时也是为未来的天界及人间的众生能得到广大的利益，来说说地藏菩萨在这娑婆世界阎浮提内的六道生死之中，是如何慈悲为怀，以他的智慧神通之力，运用种种方便法门，度脱一切罪苦众生的。”四天王说：“是的，世尊，我们非常乐意听到这些事。”佛告诉四天王说：“地藏菩萨从久远的大劫以来，一直在各个世界、各个生死道中辛勤地度脱众生，至今还没有了毕自己的宏誓大愿。因为悲悯这个世界的罪苦众生，同时也因为将来无量劫中，众生所做的恶因，就像藤蔓一样连绵不断，生生死死被业报所牵连，不能解脱，因此又再发宏誓重愿，要在娑婆世界阎浮提中，通过无量无数、百千万亿的方便法门，善巧地引导众生、教化众生。”“四天王，若遇到杀生的人，地藏菩萨就对他们说将会因杀生而短命的报应；若遇到偷盗的人，就对他们说受苦受穷的报应；若遇到犯不正当淫欲的人，就对他们说转生为雀、鸽、鸳鸯等鸟类的报应；若遇到恶口伤人的人，就对他们说家庭不和，亲属间相互争斗的报应；若遇到恶意毁谤他人的人，就对他们说缺舌、短舌、喑哑、生口疮等的报应；若遇到脾气暴躁的人，就对他们说生得丑陋残缺、四肢偏瘫的报应；若遇到小气吝惜的人，就对他们说常常不能如愿甚至事与愿违的报应；若遇到饮食没有节制、狂饮滥食的人，就对他们说饥饿、干渴或是咽喉得病的报应；若遇到经常打猎、杀生无度的人，就对他们说无端精神受刺激、突然害怕惊惶、突然如痴如狂想要自杀、终致丧命的报应；若遇到不孝敬父母，常常背逆父母的意愿，甚至打骂父母，加害父母的人，就对他们说因天地灾祸来夺取他生命的报应（如雷击、地震、掉崖、坠海等）；若遇到无故焚烧山林树木的人，就对他们说突然的精神错乱、癫狂痴乱最终导致死亡的报应；若遇到继父母，心不公平，残酷虐待非亲生子女，就对他们说，来生将要反过来投生为他们（非亲生子女）的儿女，也要受到这样的鞭打与虐待；若遇到用种种机关网罟捕捉幼禽雏鸟的人，就对他们说将要受到骨肉分离、亲人离散的报应；若遇到毁谤佛、法、僧三宝的人，就对他们说将要受到眼瞎、耳聋、哑巴的报应；若遇到轻视佛法、欺慢佛教的人，就对他们说将会永远流转在恶道的报应；若遇到毁损、私用三宝财物的人，就对他们说将会得到千百亿劫永远轮回在地狱的报应；若遇到破坏僧尼清净梵行或是冤枉魔军拒战陷害僧人的人，就对他们说将会得到永远轮回在畜生道的报应；若遇到用开水、大火、刀斧杀伤生命的人，就对他们说将会得到轮回流转、相互烧杀的报应，或是自己投生畜生道遭报应，或是成为战争中遇难者；若遇到犯戒破斋的人，就对他们说将会得到投生到禽兽道中受种种惊恐、鞭挞、劳苦、饥渴的报应；若遇到不知节约，随意浪费，挥霍无度的人，就对他们说将会得到在将来求什么都不会如愿的报应；若遇到自高自大、自以为了不起而轻视他人的人，就对他们说将会得到来生做下贱人，被人使唤、辱骂的报应；若遇到搬弄是非，挑拨他人争斗的人，就对他们说将会投生到没有舌头或是以舌为生的畜生道中去（如蚯蚓之类无舌，如黄莺、鹦鹉之类学舌）的报应。若遇到有邪见的众生，就会对他们说来世将会投生到边远荒蛮之地，无缘听受佛法的报应。”“像以上所说的阎浮提众生，由于身口意三业所造，结成种种恶果，形成百千万种各个不同的报应，今天只是粗略地说个大概。虽然阎浮提众生造业多端，而感应到千差万别的各种果报，地藏菩萨总是以他智慧神通，方便之力千方百计地化导他们。凡是犯了以上种种恶业的众生，先是受到上述提到的种种报应，然后还有可能堕入地狱，经过无数大劫的时间，罪业都还无法了结，一时半刻不要想有脱离地狱的指望。正因为如此，四天王，你们既然担当了护人、护国的职责，就应当协助地藏菩萨一起来教化众生，不要让这众多的恶习、罪业迷惑了众生。”四大天王听了佛陀的教示与嘱托，不禁泪流满面，悲叹不已，恭敬地向世尊合掌顶礼，退回到自己的座位中去了。', NULL, '', 'indent', 1523465123, '5acdcb1f4773f70069562169', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637118, '地藏经 · 地狱名号品第五', NULL, 8, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%9C%B0%E7%8B%B1%E5%90%8D%E5%8F%B7%E5%93%81%E7%AC%AC%E4%BA%94/5251174', '', '尔时普贤菩萨摩诃萨白地藏菩萨言：仁者，愿为天龙四众，及未来现在一切众生，说娑婆世界，及阎浮提罪苦众生，所受报处，地狱名号，及恶报等事，使未来世末法众生，知是果报。
地藏答言：仁者，我今承佛威神，及大士之力，略说地狱名号，及罪报恶报之事。
仁者，阎浮提东方有山，号曰铁围，其山黑邃，无日月光。
有大地狱，号极无间，又有地狱，名大阿鼻。复有地狱，名曰四角；复有地狱，名曰飞刀；复有地狱，名曰火箭；复有地狱，名曰夹山；复有地狱，名曰通枪；复有地狱，名曰铁车；复有地狱，名曰铁床；复有地狱，名曰铁牛；复有地狱，名曰铁衣；复有地狱，名曰千刃；复有地狱，名曰铁驴；复有地狱，名曰烊铜；复有地狱，名曰抱柱；复有地狱，名曰流火；复有地狱，名曰耕舌；复有地狱，名曰剉首；复有地狱，名曰烧脚；复有地狱，名曰啖眼；复有地狱，名曰铁丸；复有地狱，名曰诤论；复有地狱，名曰铁呋；复有地狱，名曰多嗔。
地藏白言：仁者，铁围之内，有如是等地狱，其数无限。
更有叫唤地狱，拔舌地狱，粪尿地狱，铜锁地狱，火象地狱，火狗地狱，火马地狱，火牛地狱，火山地狱，火石地狱，火床地狱，火梁地狱，火鹰地狱，锯牙地狱，剥皮地狱，饮血地狱，烧手地狱，烧脚地狱，倒刺地狱，火屋地狱，铁屋地狱，火狼地狱。如是等地狱。
其中各各复有诸小地狱，或一、或二、或三、或四、乃至百千，其中名号，各各不同。
地藏菩萨告普贤菩萨言：仁者，此者皆是南阎浮提行恶众生，业感如是。业力甚大，能敌须弥，能深巨海，能障圣道。是故众生莫轻小恶，以为无罪，死后有报，纤毫受之。父子至亲，歧路各别，纵然相逢，无肯代受。我今承佛威力，略说地狱罪报之事，唯愿仁者暂听是言。
普贤答言：吾已久知三恶道报，望仁者说，令后世末法一切恶行众生，闻仁者说，使令归佛。
地藏白言：仁者，地狱罪报，其事如是。
或有地狱，取罪人舌，使牛耕之。或有地狱取罪人心，夜叉食之。或有地狱，镬汤盛沸，煮罪人身。或有地狱，赤烧铜柱，使罪人抱。或有地狱，使诸火烧，趁及罪人。或有地狱，一向寒冰。或有地狱，无限粪尿。或有地狱，纯飞钑鑗。或有地狱，多攒火枪。或有地狱，唯撞胸背。或有地狱，但烧手足。或有地狱，盘缴铁蛇。或有地狱，驱逐铁狗。或有地狱，尽驾铁骡。
仁者，如是等报，各各狱中，有百千种业道之器，无非是铜是铁，是石是火，此四种物，众业行感。若广说地狱罪报等事，一一狱中，更有百千种苦楚，何况多狱。我今承佛威神及仁者问，略说如是。若广解说，穷劫不尽。', '《地狱名号品第五》出自佛教经典《地藏经》。这一品讲述了普贤菩萨请地藏菩萨讲一讲阎浮提世界的地狱名号及恶报的事情。', '普贤菩萨：梵文Samanthabhadra，音译为“三曼多跋陀罗”，即普遍贤善的意思，中国佛教四大菩萨之一。　普贤菩萨：梵名　输跋陀，又作三曼陀跋陀罗，译作普贤、遍吉。行弥法界曰普，位邻极圣曰贤。主一切诸佛之理德、定德及行德，与文殊之智德、证德相对，即理智一双、行证一双、三昧般若一双也，故为释迦如来之二胁士。《大日经疏》云：“普贤菩萨者，普是遍一切处，贤是最妙善义。谓菩提心所起愿行及身口意悉皆平等遍一切处，纯一妙善，备具众德，故以为名。”其道场在四川山。
仁者：系菩萨与菩萨之间的敬称。
末法：相对于正法、像法而言，指佛法衰颓之时代。
大士：菩萨的通称。士者凡夫之通称，区别于凡夫而称为大。又，士者事也，为自利利他之大事者，谓之大士。　有时亦称声闻及佛是大士者。《四教仪集解》云：“大士者，大非小也，士者事也。运心广大，能建佛事，故云大士，亦名上士。”
阿鼻：梵文Avici的音译，又作阿鼻旨，汉译为无间，这是最低的地狱，称阿鼻地狱、无间地狱，略称阿鼻狱，为八大地狱之一，是诸地狱中最苦者。　大阿鼻：又作阿鼻旨，阿为“无”，鼻为“遮”、“救”，译言无遮无救，言无人能遮止其入此狱，亦无人能救度其出此狱也，乃无间地狱中最苦者。
四角：将罪人身分成四块。依宣化上人之意，四角地狱即四围皆烧红之铁壁，顶上抛落铁火，罪人被驱于四角被铁壁所烧。
飞刀：空中有极大刀轮旋转落下，一著罪人身体，即头破血流，身无完躯。
火箭：无数亿烧得通红的铁箭密集射来，穿入罪人的身体，五脏六腑，刺割烧伤，惨痛不可言状。
夹山：罪人逃入山中，两山自动夹合，把罪人夹成糜烂，变成肉饼。
通枪：无数铁枪刺通罪人心胸腹背。
铁车：烧红的大铁车追逐罪人，把罪人碾得粉碎。
铁床：烧红的大铁床遍满地狱，皆见自身被卧床烧烂，或说罪人自见其身卧床上被鬼卒用种种刑具折磨受苦。
铁牛：能喷火的铁牛追逐罪人，令其被烧、被践踏、被角撞致死。
铁衣：烧红的铁衣从天而下，自然缠裹在罪人身上，把罪人烧烂。古德云：“现见袈裟离体，将来铁缠身”者，即此地狱也。
千刃：成千的烧红的匕首或利刃烧刺罪人。
铁驴：能喷火的铁驴追逐罪人，令其被烧、被践踏而死。
烊铜：把铜烧化了，或者把罪人抛下煮烂，或是用铜汁灌口。
抱柱：形如<封神演义>之“炮烙”，把铜柱烧红，凡是犯邪淫的男女，一见铜柱往往误以为是美男美女，往柱上一抱，即刻被火焚焦；业风一吹，死而复活，一见铜柱，又往上扑，又复烧焦，如是循环往复，直至业尽，方得出狱。
流火：此狱遍处火花四喷，平地铁水横流，这种流火遍及各处，令罪人无处可避，而被流火烧死。
耕舌：把罪人的舌头拉出，如耕牛一般地耕犁罪人，此乃犯口业的果报。
锉首：用刀把罪人的头颅片片锉碎。
烧脚：罪人踏上烧红的铁板，双脚被烫伤烧焦。
啖眼：啖，音淡，吃的意思，此狱有铁鹰，专好食啖罪人的眼睛。
铁丸：此地狱饥饿难当，但又无食可找。狱卒用烧红之铁丸令罪人吞食，入口即烧焦罪人的口、舌、喉、食道直至五脏六腑。
诤论：罪人一到此狱，自然嗔恨多端，其身上也生出铁爪锋刀，自相搏杀。
铁：，音夫，铡刀也，通称“斧”，如《列子·说符》云：“人有亡者，意其邻之子。”此狱用铡刀腰斫罪人之身。
多嗔：罪人腹内嗔火自焚其身，以嗔火故，复自相残杀。
叫唤：此狱中，狱卒将罪人掷入大锅汤中煮烂或大油锅中煎熬，令罪人痛苦而大声叫唤。
拔舌：此狱中，狱卒将罪人之口用铁杵打开，再用铁钩钩住罪人之舌，将其拔出。这是在生造口业所得的果报。
粪尿：此狱中，将罪人抛入极热的粪堆尿池之中，又臭又烫。
铜锁：用铜锁把罪人的颈项锁住，又用大铁练钩住，令罪人拖曳而行。
火象：有火象身上出火，追逐罪人，践踏罪人，令其烧死或被踏死。
火狗：《三法度论》云：“火铁燃烧，驱众罪人，煎熬令熟，熟已，复拖出，为恶狗所食。食尽，经风一吹又再活，还复如是，受报经百千劫。”
火马：火马身上着火，到处追逐罪人，践踏罪人。
火牛：火牛身上着火，到处追逐罪人，践踏罪人，用角抵触罪人。
火山：此狱由山而成，山上大火，无有空隙，罪人尽被火所焚烧。
火石：烧得极热之石，上压下铺，把罪人烧烂并磨成肉浆。
火床：与前大铁床地狱相似，此床大火熊熊，烧炙罪人。
火梁：把罪人悬挂在火梁上，周围皆是大火熊熊，将罪人烧焦。
火鹰：此狱铁树遍地，上有着火之铁鹰，专食罪人的双眼、耳鼻、脑髓、五脏六腑等。
锯牙：用锯锯罪人牙，或说用刀斧凿下罪人的牙齿。
剥皮：生剥罪人之皮，复用刀零割罪人身上之肉。
饮血：此狱中有恶虫，名朱诛虫，专门吸食罪人身上之血，令其乾枯而死。
烧手：用铁斗内盛炭火烧红，恒烙罪人双手。
烧脚：此狱遍地火炭烧红，无空隙处，令罪人奔走其上。
倒刺：此狱有山，山上有林，此林皆由刀剑带倒刺而成，逼令罪人上树，复被狱卒倒拖下树，倒刺尖刃便刺割罪人之身，令其体无完肤完肉。此皆由此罪人在生之时犯凶恶之邪淫，故遭此惨报。
火屋：将罪人关在铁屋之内纵火焚烧，令罪人无处可逃而被烧死。
铁屋：大铁城内，多诸铁屋，烈焰焚烧，无处可逃也。
火狼：着火之铁狼到处追逐罪人，烧、咬、踏诸罪人，令罪人心受惊恐，身受痛楚，口中狂呼，乃身口意三业所共感之苦果也。
圣道：圣者之道也。总称声闻、缘觉、菩萨之道也。《成实论》云：“圣道能破一切结使”。
蒺藜：音吉利，本指草本植物蒺藜，果皮有夹刺者。今作铁制带刺形如蒺藜之刑具，锋利如针，从空中飞来，刺罪人身，穿骨彻髓。', '这时，普贤菩萨摩诃萨见教化众生机缘成熟，起来向地藏菩萨说：“仁者，请您为天龙四众以及宇宙的一切众生，说一说娑婆世界及阎浮提罪苦众生，所受业报的地方、地狱的名称以及恶报的各种情况，使得未来世的末法众生能明了这些果报，心有所惧而免造种种恶业。”地藏菩萨回答说：“仁者，我承蒙佛的威神之力以及大士您的慈悲愿力，在这里简略地说一说地狱的名称以及罪报恶报等情形。仁者，在阎浮提的东方有一座山，名叫铁围山，这座山长年累月黑暗幽深，是日月的光明永远照不到的地方。其中有个大地狱，名字叫极无间；又有地狱，名叫大阿鼻；又有地狱，名叫四角；又有地狱，名叫飞刀；又有地狱，名叫火箭；又有地狱，名叫夹山；又有地狱，名叫通枪；又有地狱，名叫铁车；又有地狱，名叫铁床；又有地狱，名叫铁牛；又有地狱，名叫铁衣；又有地狱，名叫千刃；又有地狱，名叫铁驴；又有地狱，名叫烊铜；又有地狱，名叫抱柱；又有地狱，名叫流火；又有地狱，名叫耕舌；又有地狱，名叫锉首；又有地狱，名叫烧脚；又有地狱，名叫啖眼；又有地狱，名叫铁丸；又有地狱，名叫诤论；又有地狱，名叫铁铁；又有地狱，名叫多嗔。”地藏菩萨接着说：“仁者！铁围山内的地狱其数之多，是数都数不过来的。更有称为叫唤地狱、拔舌地狱、粪尿地狱、铜锁地狱、火象地狱、火狗地狱、火马地狱、火牛地狱、火山地狱、火石地狱、火床地狱、火梁地狱、火鹰地狱、锯牙地狱、剥皮地狱、饮血地狱、烧手地狱、烧脚地狱、倒刺地狱、火屋地狱、铁屋地狱、火狼地狱等许多地狱。在这些地狱中，有的还包括各种小地狱，有一个两个，三个四个不等，乃至包括成百上千个小地狱，这些小地狱的名称也都不相同。”地藏菩萨进一步告诉普贤菩萨说：“仁者！这许多的地狱，都是南阎浮提作恶众生的恶业所感应而形成的。业力之大不可思议，其高大要超过须弥山，其深广如大海水，它能障碍众生修习佛法圣道。业力的作用如此巨大，因此一切有情众生千万不要轻视那些小小的过恶，以为不算什么，要知道一切罪业在死后都有报应，哪怕是一丝一毫也不会空过。即使如父子一般的至亲骨肉，在黄泉路上，按照各人的业力，各走地神作证各的路，即使是偶然碰到了，也是相见不相识，更不用说代为受罪了。我如今承佛威神之力，在这里将地狱中罪恶报应的具体情形大略再说一下，请仁者耐心再听我讲述一番。”普贤菩萨回答说：“我早已知道三恶道由恶业所感的苦报有多么深重，希望仁者再讲述一遍，以使后世末法时期一切造恶的众生，有机会听到这些以后，明了因果报应真实不虚，从而发心皈依佛法，永离恶道！”地藏菩萨讲：“仁者！地狱里罪报的情形大致上是这样的：或有地狱，拔出罪人的舌头，让牛用犁来耕它；或有地狱，挖出罪人的心脏，让夜叉来吞食；或有地狱，在大铁锅里装满了沸腾的开水，把罪人放到里面去煮；或有地狱，把铜柱烧得通红，让罪人抱；或有地狱，遍地都是大火，追赶着焚烧那些罪人；或有地狱，终年寒冰不化，永远是寒天冻地；或有地狱，到处都是恶臭冲天的粪尿；或有地狱，空中到处飞撞着铁蒺藜；或有地狱，烧红铁枪横冲直撞；或有地狱，大铁锤不停地撞击罪人的胸背；或有地狱，地面全都是烧红的铁板，让罪人无法落脚；或有地狱，到处爬满了铁蛇，缠绕在罪人的颈项上；或有地狱，满地奔跑着铁狗，追逐撕咬着罪人；或有地狱，让罪人骑在铁骡背上上下颠簸。”“仁者！如此这般的报应，在各种各样的地狱中，有百千种。无论地狱中刑具有多少种，无非都是由以下这四种材料构成的：那就是铜、铁、石、火之类的东西。这四种东西正是同众生造恶的心一一对应，是由众生的罪业所感召的。如果要详细地说清地狱里种种罪报的情形，那么在每一个或大或小的地狱中，都有说不完的百千种痛苦之事，更何况有无量无数的地狱啊。我如今承蒙佛的威神之力和仁者的方便提问，借此因缘大略地讲述了地狱罪报的情形。如果要想把所有地狱以及每个地狱的种种苦处都说出来的话，那即使穷尽一劫的时间，也是说不完的。”', NULL, '', 'indent', 1523465330, '5acdcbef17d00900318c143a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637122, '地藏经 · 称佛名号品第九', NULL, 5, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E7%A7%B0%E4%BD%9B%E5%90%8D%E5%8F%B7%E5%93%81%E7%AC%AC%E4%B9%9D/10550955?fr=aladdin', '', '尔时地藏菩萨摩诃萨白佛言：世尊，我今为未来众生演利益事，于生死中，得大利益，唯愿世尊听我说之。
佛告地藏菩萨：汝今欲兴慈悲，救拔一切罪苦六道众生，演不思议事，今正是时，唯当速说。吾即涅槃，使汝早毕是愿，吾亦无忧现在未来一切众生。
地藏菩萨白佛言：世尊，过去无量阿僧祇劫，有佛出世，号无边身如来。若有男子女人闻是佛名，暂生恭敬，即得超越四十劫生死重罪。何况塑画形像，供养赞叹，其人获福无量无边。
又于过去恒河沙劫，有佛出世，号宝性如来。若有男子女人闻是佛名，一弹指顷，发心归依，是人于无上道永不退转。
又于过去有佛出世，号波头摩胜如来。若有男子、女人，闻是佛名，历于耳根，是人当得千返生于六欲天中，何况志心称念。
又于过去，不可说不可说阿僧祇劫，有佛出世，号师子吼如来。若有男子女人闻是佛名，一念归依，是人得遇无量诸佛摩顶授记。
又于过去有佛出世，号拘留孙佛。若有男子女人，闻是佛名，志心瞻礼或复赞叹，是人于贤劫千佛会中，为大梵王，得授上记。
又于过去有佛出世，号毗婆尸。若有男子女人闻是佛名，永不堕恶道，常生人天，受胜妙乐。
又于过去无量无数恒河沙劫，有佛出世，号宝胜如来。若有男子女人闻是佛名，毕竟不堕恶道，常在天上受胜妙乐。
又于过去有佛出世，号宝相如来。若有男子女人闻是佛名，生恭敬心，是人不久得阿罗汉果。
又于过去无量阿僧祇劫，有佛出世，号袈裟幢如来。若有男子女人闻是佛名者，超一百大劫生死之罪。
又于过去有佛出世，号大通山王如来。若有男子女人闻是佛名者，是人得遇恒河沙佛广为说法，必成菩提。
又于过去有净月佛、山王佛、智胜佛、净名王佛、智成就佛、无上佛、妙声佛、满月佛、月面佛有如是等不可说佛。世尊，现在未来一切众生，若天若人，若男若女，但念得一佛名号，功德无量，何况多名。
是众生等，生时死时，自得大利，终不堕恶道。若有临命终人，家中眷属，乃至一人，为是病人高声念一佛名，是命终人，除五无间罪，余业报等悉得销灭。是五无间罪，虽至极重，动经亿劫，了不得出，承斯临命终时，他人为其称念佛名，于是罪中，亦渐销灭。何况众生自称自念，获福无量，灭无量罪。', '《称佛名号品第九》出自佛教经典《地藏经》。这一品讲述地藏菩萨为利益未来众生，演说过去诸佛名号。', '名号：“名”是相对此人本体而起，具有特殊性；“号”是相对于这一类人共性而起，具有普遍性。如观世音菩萨：‘观世音’为名，特指此位大慈大悲的圣者；‘菩萨’为号，通指具有菩萨德行的圣者。如释迦牟尼佛：‘释迦牟尼’为名，特指本师；‘佛’为号，通指具佛德者。
慈悲：与乐曰慈，拔苦曰悲，乃慈悲喜舍四无量之前二也。有三种慈悲：一、众生缘慈悲，以慈悲心视十方六道众生犹如父母亲人，常思与乐拔苦，此乃未断烦恼之修学人所起也；二、法缘慈悲：断烦恼之圣人已达法空，破我空而未破法空，一心令众生随其意而起与乐拔苦之心也；三、无缘慈悲：诸佛不住有为、无为，不住三世，故心无所缘，于一切众生等视无别，皆令得乐拔苦也。故知此三类乃有学、无学、佛或凡贤、圣者、佛之区别也。
无边身：佛之身量无边际，指佛随机应化的应身。　无边身如来：即一切众生自性清净法身。《传心法要》云：“问无边身菩萨为什么不见如来顶相？师云，实无可见。何以故？无边身菩萨便是如来，不应更见。但无诸见，即是无边身。若有见处，即名外道”。“无边”者，广大而无边际也。
宝性：宝是珍宝，性是本性。珍宝在粪秽中本性不变，诸佛如来在众生烦恼中不失真如清净之性。　宝性如来：宝性者，佛性也，乃如来藏之异名也。真金在粪秽中，其性不变；如来藏性在众生烦恼中，不失真如清净之性，故云宝性。《宝性论》云：“尘劳诸境中，皆有如来藏，下至阿鼻狱，皆有如来身，真如清净法，名为如来体”。真如在烦恼中，名如来藏；真如出烦恼，谓之法身。依《佛性篇·如来藏品》云，藏有三义：一、所摄之义，真如立于众生之位，则含和合不和合二门。和合门者，生一切染法；不和合者，生一切净法。一切染净之法，皆摄于如来之性，即真如，故云如来藏。二、隐复之义：真如在烦恼中时，为烦恼隐复如来之性而不显，故名如来藏。三、能摄之义：真如在烦恼中，含摄如来一切果地之功德，故名如来藏。若能于刹那间见此佛性，则必能从性起修，直至成佛也。
不退转：梵文Avaivartika，音译阿鞞跋致、阿惟越致，意即不退转，指在修行佛道的过程中，不退失既得的功德。不退转是佛法修行中一个很高的阶位。
波头摩胜：梵文Padma，汉译为“红莲花”。莲花以红的颜色最好，所以叫胜。佛莲千瓣，喻作千返。佛法和莲花一样，出污泥而不染。众生听了这一佛名，便可以千返生天。　波头摩胜如来：波头摩，又作钵特摩、波昙摩、钵昙摩，译作赤莲华，其花茎有刺者。印度有四种莲：青黄赤白，以红莲为胜，故云波头摩胜，梵汉双举也。红莲华者，表一切众生之本心也。众生之本心能造万物而不为万物所污，犹如莲花出污泥而不染也。波头摩胜如来者，乃一切众生之本心也。
六欲天：指欲界之六天。即四天王天，忉利天，焰摩天，兜率天，化自在天，他化自在天。
师子吼如来：师子吼者，佛在大众中为决定之说而无所畏，如狮子吼而百兽伏也。<涅经>云：“师子吼者名决定说”。决定说者，是实非权，以名一乘大法也。一乘大法者，令一切众生悉皆成佛，非以声闻、缘觉、菩萨为究竟也，乃诸法实相也。
拘留孙佛：梵文Krakucchandha—buddha，汉译为“应断”。在人寿六万岁时，这佛就在世界上出现，救度众生。　拘留孙佛：又作俱留孙佛、鸠楼孙佛、羯罗迦村驮，译作：所应断已断、灭累、成就美妙等。当于过去七佛之第四佛，现在贤劫千佛之第一佛也。谓已断一切惑障也。《宝积经》云：“过去有佛，曰无量勋宝饰净王如来。其时有转轮圣王住清净大城，名勇群王，王有千子，第一名净意，第千子名意无量”。第一子净意，即拘留孙佛也，第千子意无量，即楼至佛也。此千子即贤劫千佛之前身也。
毗婆尸佛：梵文Vipasyin，汉译为胜观，种种观，种种见。过去七佛之第一佛。观一切皆空，皆幻空，皆幻，皆恒，亦是佛之境界。　毗婆尸佛：亦作毗钵尸、毗婆沙、维卫等，过去七佛之第一佛也，译作胜观，种种观，种种见等。释迦菩萨第三阿僧祗劫满时，遇此佛初修百大劫种相之福，又由赞其佛之精进力，超九劫而成佛，可知此佛出世在九十一大劫之前也。心为万法之主，观心者，即观察一切也。能观心者，究竟解脱，不能观心者，永处缠缚。
宝胜：宝有在世间的宝，也有出世间的宝。念佛可以了脱生死，故佛宝胜过世间的宝，也胜过各种出世间的宝。　宝胜如来：出世之宝，宝中极胜，故名宝胜。此宝乃涅槃四德常乐我净也。常者，涅槃之体，不变而无生灭也，随缘化用而常不绝也；乐者，涅槃之体，寂灭永安也，运用自在，所为道心也；我者，法性不变易也，作用自在也；净者，涅槃之体，离一切垢染，目之为净，随缘而处而不污名净。破烦恼名净，破有业名我，离有报名乐，离生死名常，如来已证涅槃，具四德，故名宝胜如来。
宝相：佛的无去无来的法性实相。　宝相如来：智者大师云，实相尊贵，故名宝相。宝相者，诸法实相也。《金刚经》云：“信心清净，则生实相”；“是实相者，即是非相”。《无量义经》云：“无相不相，是名实相”，无相者，无十相也，无色、声、香、味、触、生、住、坏、男、女之十相也；不相者，不取涅槃相也。离二边，不执中也。如来智证实相，尊贵无上，故名宝相如来也。又，宝相者，指佛相好无比也。
袈裟幢：就是如来宝幢的形象，表示佛的庄严。大通山王：就是以须弥山的妙高峰形容这位佛的高大。这山中之王，高达八万四千由旬，全是用金银铜铁四宝所合成。又因此佛能映照明彻，故名通。　袈裟幢如来：袈裟者，《释氏要览》云：“大集经云，袈裟名离染服，贤愚经云出世服；如幻三昧经云无垢衣，又名忍辱铠，又名莲华服，谓不为欲泥染故。又名幢相，谓不为邪所倾故。又名田相衣，谓不为见者生恶故。又名消瘦衣，谓著此衣烦恼消瘦故。又名离染服，去秽衣”。以此衣具人天宝幢相，生梵天之福，乃三世如来宝幢之相，闻此名者，能生实相也。
大通山王如来：依圣一法师解，大通是般若，山王是佛德，若人修般若之智能证法身时，则能通达一切法，故名大通。法身具常乐我净四德，犹如须弥山由四宝所成，故名山王，以须弥山乃一切山中之王也。
净月佛：一尘不染日净，随机应现，如水中月，故名净月佛。山王佛：是佛修成的报身，高大如山王。
山王佛：佛功德巍巍，犹如须弥山王，故名。
智胜佛：这位佛的智慧胜过一切。净名王佛：一切业障断尽，清净自然，以断惑立名。
净名王佛：净谓清净，乃真如理体；名，谓名字，乃召体之用。以名而召体，称名而令人想物也，故有钩召之义，钩召之用。能以称名功德，得证真体之果，故名净名王佛。
智成就佛：是功德的修成，皆因智力的成就。佛成就一切种智，故名智成就佛。
无上佛：无上是极尊的称谓。佛法是无上法，若人起信诚敬勤修，即可得无上果位，此佛的果位就是如此修来的。
妙声佛：是如来应机说法，圆妙声音，遍布十方。佛之梵音，清净柔软，深远微妙。三十二相之第二十八相为“梵音深远相”。《无量寿经》云：“或闻佛法僧声、波罗密声、止息寂静声、无生无灭声、十力无畏声，或闻无性无作无我声、大慈大悲喜舍声、甘露灌顶受位声，得闻如是种种声已，其心清净，无诸分别，正直平等，成熟善根”。阿弥陀佛佛国一切音声皆为阿弥陀佛愿力变化所作，阿弥陀佛为一切佛之王，故其音声即妙声佛也。
满月佛：像十五夜的明月，圆满具足。佛之功德一切圆满，无余无欠，故以十五夜之月比喻其圆满也。
月面佛：是说佛的脸清秀圆满，令人一瞻仰，就能生起无限欢喜恭敬。佛面犹如清净圆满之月，亦如千日所放之光明，此清净圆满之光明普照十方世界，慈悲喜舍悉皆具足。', '这时，地藏菩萨摩诃萨恭敬地对佛说：“世尊，我现在打算为了未来世的众生，说一下如何在生死轮回的苦海中得到解脱，获得大利益与大福德，唯愿望世尊您听我解说。”
佛对地藏菩萨说：“你今天起慈悲心，发大誓愿，以救拔济度一切遭罪受苦的六道众生，演说这不可思议的解脱法门。现在正是时候，就快说吧！我即将进入涅槃，让你能早点完成心愿，实现所立下的誓愿，同时我也可以不必再为现在和将来的一切众生担忧了。”
于是，地藏菩萨恭敬地对佛说：“世尊，在过去无量阿僧祇劫前，有一尊佛出现于世，名号称为‘无边身’如来。若有男子、女人听到了这尊佛名，哪怕暂时生起恭敬心，马上就可以免去四十劫的生死重罪，更何况还能恭敬地塑画佛的形象，供养赞叹呢？如果能这样，那所获得的福报真是无量无边了。”“还有，在过去恒河沙劫之前，有一尊佛出现于世，名号为‘宝性’如来。若有男子女人听到这尊佛名，哪怕只在一弹指的时间里发心皈依这尊佛，那么这个人在无上道中将获得不退转的果报，直至成佛。”“还有，在遥远的过去世里，有一尊佛出现于世，名号为‘波头摩胜’如来。若有男子、女人听到这尊佛名，哪怕只有一声经过耳根，那么这个人就可以千百次往返生于六重欲界天。更何况还能志诚恳切地称念佛的名号呢？那样获得的功德更是不可限量了。”“还有，在过去不可说、不可说阿僧祇劫前，有一尊佛出现于世，名号为‘狮子吼’如来。若有男子、女人听到这尊佛名，产生皈依这尊佛的念头，那么这个人就会得到无量无数诸佛的摩顶祝福，授记他将来必定成佛。”“还有，在遥远的过去世里，有一尊佛出现于世，名号为‘拘留孙’佛。若有男子、女人听到这尊佛名，能志诚恳切地瞻仰礼拜佛的形象，或赞叹颂扬佛的功德，那么这个人以此功德，可以在千佛出世的贤劫中成为大梵王，获得佛授予他将要成佛的记别。”“还有，在遥远的过去世里，有一尊佛出现于世，名号为‘毗婆尸’佛。若有男子、女人听到这尊佛的名号，永远不会堕入恶道，常常降生在天上或富贵人家，享受最美好、最微妙的快乐。”“还有，在遥远的过去世里，有一尊佛出现于世，名号为‘宝胜’如来。若有男子、女人听到这尊佛的华严大法名号，最终不会堕于恶道，常常能降生天上，享受最美好微妙的快乐。”“还有，在遥远的过去世里，有一尊佛出现于世，名号为‘宝相’如来。若有男子、女人听到这尊佛名，能产生恭敬心，那么这个人不久就可以修得阿罗汉的果位。”“还有，在遥远的过去世里，有一尊佛出现于世，名号为‘袈裟幢’如来。若有男子、女人听到这尊佛名，那么马上就可以脱离一百大劫的生死之罪。”“还有，在遥远的过去世里，有一尊佛出现于世，名号为‘大通山王’如来。若有男子、女人听到这尊佛名，那么，这个人就可遇到恒河沙数佛为他解说佛法的奥义，必定能证得菩提而觉悟成佛。”“还有，在遥远的过去世里，还有净月佛、山王佛、智胜佛、净名王佛、智成就佛、无上佛、妙声佛、满月佛、月面佛等不可说的无量诸佛。”“世尊，现在或是未来世界的众生，无论在天上还是在人间，无论是男是女，若能口称心念哪怕一尊佛的名号，那功德就多得无法称量了，更何况念这么多的佛名。这些众生，无论生时或死时，自然会得到极大的利益，永不会堕入恶道。倘若有临命终的人，家里的亲人中哪怕只有一个人，能够为这病人高声地念一尊佛的名号，那么这个命终人，除犯了极重的五无间罪之外，其余那些轻微的业报都会被消灭。即使说五无间罪这样的极恶重罪，在地狱中即使经过几亿大劫都没有出头的希望，但凭着临命终时，别人为他称名念佛的功德，这样的重罪，也能渐渐得以减轻以致消除。更何况众生能够自己称念佛的名号，自然可以获得无量的福报，消灭无量的重罪了。”', NULL, '', 'indent', 1523465772, '5acdcd7f4773f700695635f4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637123, '地藏经 · 校量布施功德缘品第十', NULL, 7, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E6%A0%A1%E9%87%8F%E5%B8%83%E6%96%BD%E5%8A%9F%E5%BE%B7%E7%BC%98%E5%93%81%E7%AC%AC%E5%8D%81/5221298', '', '尔时地藏菩萨摩诃萨，承佛威神，从座而起，胡跪合掌白佛言：世尊，我观业道众生，校量布施，有轻有重，有一生受福，有十生受福，有百生千生受大福利者。是事云何，唯愿世尊为我说之。
尔时佛告地藏菩萨：吾今于忉利天宫一切众会，说阎浮提布施较量功德轻重，汝当谛听，吾为汝说。
地藏白佛言：我疑是事，愿乐欲闻。
佛告地藏菩萨：南阎浮提，有诸国王、宰辅大臣、大长者、大刹利、大婆罗门等，若遇最下贫穷，乃至癃残喑哑，聋痴无目，如是种种不完具者。是大国王等欲布施时，若能具大慈悲下心含笑，亲手遍布施，或使人施，软言慰喻，是国王等所获福利，如布施百恒河沙佛功德之利。何以故。缘是国王等，于是最贫贱辈及不完具者，发大慈心，是故福利有如此报。百千生中，常得七宝具足，何况衣食受用。
复次地藏：若未来世，有诸国王，至婆罗门等，遇佛塔寺，或佛形像，乃至菩萨声闻辟支佛像，躬自营办供养布施。是国王等，当得三劫为帝释身，受胜妙乐。若能以此布施福利，回向法界，是大国王等，于十劫中，常为大梵天王。
复次地藏：若未来世，有诸国王，至婆罗门等，遇先佛塔庙，或至经像，毁坏破落，乃能发心修补。是国王等，或自营办，或劝他人，乃至百千人等布施结缘。是国王等，百千生中常为转轮王身。如是他人同布施者，百千生中常为小国王身。更能于塔庙前，发回向心。如是国王乃及诸人，尽成佛道，以此果报无量无边。
复次地藏：未来世中，有诸国王及婆罗门等，见诸老病及生产妇女，若一念间，具大慈心，布施医药饮食卧具，使令安乐。如是福利最不思议，一百劫中常为净居天主，二百劫中常为六欲天主，毕竟成佛，永不堕恶道，乃至百千生中，耳不闻苦声。
复次地藏：若未来世中，有诸国王及婆罗门等，能作如是布施，获福无量。更能回向，不问多少，毕竟成佛，何况帝释梵转轮之报。是故地藏，普劝众生当如是学。
复次地藏：未来世中，若善男子善女人，于佛法中，种少善根，毛发沙尘等许，所受福利，不可为喻。
复次地藏：未来世中，若有善男子善女人，遇佛形像、菩萨形像、辟支佛形像、转轮王形像，布施供养得无量福，常在人天受胜妙乐。若能回向法界，是人福利不可为喻。
复次地藏：未来世中，若有善男子善女人，遇大乘经典，或听闻一偈一句，发殷重心，赞叹恭敬，布施供养。是人获大果报，无量无边。若能回向法界，其福不可为喻。
复次地藏：若未来世中，有善男子善女人，遇佛塔寺，大乘经典。新者布施供养，瞻礼赞叹，恭敬合掌。若遇故者，或毁坏者，修补营理，或独发心，或劝多人同共发心。如是等辈，三十生中常为诸小国王，檀越之人，常为轮王，还以善法教化诸小国王。
复次地藏：未来世中，若有善男子善女人，于佛法中所种善根，或布施供养，或修补塔寺，或装理经典，乃至一毛一尘，一沙一渧。如是善事，但能回向法界，是人功德，百千生中受上妙乐。如但回向自家眷属，或自身利益，如是之果，即三生受乐，舍一得万报。是故地藏，布施因缘，其事如是。', '《校量布施功德缘品第十》出自佛教经典《地藏经》。在这一品中，地藏菩萨向世尊请问阎浮提众生布施功德的轻重，世尊针对这一问题作了回答。', '校量：校量又曰较量，较校虽通而以校为本。比量物之多少曰校量。又，校量叹，欲赞叹某种功德，先假举一大功德，使知其份量，而后以之况知其他功德之更大也。天台嘉祥谓之格量叹，慈恩谓之校量叹。《法华经·随喜功德品》所明者，其一例也。《金刚经》中多次以七宝、大千世界、微尘等以明诵经、讲经功德，此其又一例也。
七宝：七种珍宝，一般指金；银；琉璃，又作瑠璃、毗琉璃、吠琉璃等，属青玉类；玻璃，意译作水晶，指赤、白等之水晶；砗磲，指大蛤或白珊瑚之类；赤珠，又称赤真珠；玛瑙，深绿色之玉，但异于后世所称之玛瑙。
回向：梵文Parinama，又作转向、施向，即以自己所修之善根功德，回转给众生，并使自己趋入菩提涅槃。
转轮王：梵文Cakravarti—raja，亦称轮王，掌管四洲之王，感得轮宝，飞行空中，降伏四方。转轮王有金、银、铜、铁四王，金轮王统掌四洲，银轮王掌东、西、南三大洲，铜轮王掌东、南二洲，铁轮王掌南赡部洲，即阎浮提洲。
净居天：证得不还果的圣者所居的境地。此中又分五种：无烦天，无热天，善现天，善见天，色究竟天，合为五净居天。　净居天主：色界四禅天，证不还果之圣者所居之天。有五处：无烦天，无一切烦杂处；无热天，无一切热恼处；善现天，能现种种胜法处；善见天，能见种种胜法处；色究竟天，色界天最胜处也。《俱舍颂·疏世品》云：“此五名净居天，唯圣人居，无异生杂，故名净居天。”
檀越：梵文Danapati，施主之意，这里指发心布施的人。檀越：梵语陀那钵底，译作施主。“越”为施之功德，谓已越贫穷海之义也。《寄归传》云：“梵云陀那钵底，译为施主。陀那是施。钵底是主。而言檀越者，……意道由行檀舍，自可越度贫穷。”', '这时，地藏菩萨摩诃萨承蒙佛的威神之力，从座位起身，右膝着地，合掌恭敬，对佛说：“世尊，我观这六道里的众生，衡量比较他们布施的功德，有轻有重，大不相同。有的是一生受福报，有的是十生受福报，还有的百生、千生都受大福报的，这究竟是什么缘故？唯愿请世尊为我讲说。”佛告诉地藏菩萨说：“我今天在忉利天宫，法会中的一切大众之前，说一下阎浮提世界中衡量布施功德的轻重区别，你仔细用心倾听，我来为你分别解说。”地藏菩萨回答说：“我正对此事有所疑惑，很愿意听世尊解说。”佛告诉地藏菩萨说：“在南阎浮提世界中，若有国王、宰相大臣、大长者、大刹利、大婆罗门等，碰到那些最低贱、最贫穷的人，以及驼背肢残、耳聋眼瞎、哑巴痴呆等肢体残缺、六根不具的残疾人。倘若能抱着慈悲心，屈尊就卑，平易近人，亲自到各个地方布施救济穷人，或让手下人去布施的时候，也要叫他们含笑宽慰贫穷的人。那么这些国王、贵族等所获得的福利，就相当于供养百倍于恒河沙数那么多佛的功德。为什么呢？因为这些国王等，对于那些最贫贱、最可怜的人，能发起慈悲的关爱之心，所以能够得到如此之大的福报。在千百个转世过程中，常常可以得到充足的七宝，更何况普通的衣食住行等基本生活的享用了。”“另外，地藏，倘若在未来世，有国王、大臣、长者、刹利及修净行的婆罗门等，见到佛的塔寺、形象，乃至菩萨、声闻、辟支佛等圣者的形象，能亲自操持种种布施供养，那么，这些国王等人可以在三大劫的长时间里得生为帝释之身，享受种种微妙的快乐。如果能够进一步将此布施的功德福利回向给法界全体众生，那么这些国王等在十劫中可以得大梵天王之身，享受大梵天王的福报。”“还有，地藏，倘若在未来世，有国王、大臣、长者、刹利及婆罗门等，遇到已经涅槃的过去佛的塔庙，或遗留下来的经像，由于年代久远，毁坏破落，能够用心去修补。这些国王等人，或是亲自操办，或是劝人操办，劝一人、两人甚至成百上千等人大家共同布施结缘。那么这些国王等人，在今后的百千生中常可以得生为转轮王身，一同布施的其他人，在今后的百千生中常可以得生为小国王身。如果更能在塔庙前发回向心，那么这些国王及共同布施的人，终将成就佛道。因为这种布施供养的功德是无量无边的。”“还有，地藏，倘若在未来世，有国王、大臣、长者、刹利及婆罗门等，见到那些年老生病或是正在生产的妇女，若能在一念之间发大慈悲心，布施医药、饮食、床具等，使他们得到安乐。这种福德是最不可思议的。在一百大劫之中，常常成为净居天主；在二百大劫之中，常常成为六欲天的天主，最终必定成佛，永不堕入恶道。乃至在今后的百千生中，永远听不到受苦的声音，更不用说亲自受苦了。”“还有，地藏，倘若在未来世，有国王、大臣、长者、刹利及婆罗门等，能够做以上种种的布施，所获得的福德真是无量无边。若能进一步把这些功德回向给法界众生，不问功德多少，最终必定成佛，更不用说帝释天王、大梵天王、转轮圣王一类的福报了。因此，地藏，你应当广泛地向一切众生传达这其中的道理，广泛地劝说一切众生学者这么做。”“还有，地藏，在未来世中，倘若有善男子、善女人在佛法中种很少一点善根，即使如同汗毛、灰尘一样微不足道，他们所受的福报将大得无法形容。”观菩提树“另外，地藏，在未来世中，倘若有善男子、善女人见到佛的形象、菩萨的形象、辟支佛的形象，乃至转轮王的形象，能够布施供养，即可得无量的福德，常可在人间天上享受最美妙的安乐。若能够将此功德回向给法界众生，那这人的福德就多得无法言喻了。”“另外，地藏，在未来世中，倘若有善男子、善女人，见到大乘经典，或是听到一个偈、一句经，能发殷切尊重心，赞叹恭敬，布施供养，此人获得的果报，大到无量无边。如果能够将此功德回向给法界众生，那这人的福德也是多得无法言喻了。”“另外，地藏，在未来世中，倘若有善男子、善女人，遇到佛的塔寺、大乘经典。若是新的，便布施供养，瞻礼赞叹，恭敬合掌；若是旧的或是已经损坏的，便发心去修补打理，或是独自一个人发心，或是劝许多人共同发心，跟着一同布施的人，在三十生中，常常做小国王；而那位领头发心布施的人，在三十生中常常做转轮圣王，并以种种善法、善政去教导、教化这些小国王们。”“最后，地藏，在未来世中，倘若有善男子、善女人在佛法中所种的善根，或是布施供养，或是修补塔寺，或是装理经典，小到哪怕像一根汗毛、一粒灰尘那样微不足道的一点善事。只要能回向法界，那么这人的功德，在百千生中都会受到人天最美妙的快乐。倘若单是回向给自己的亲人或自身受用，那所得的福报只有三生受乐而已。若是能够回向给法界众生，那功德果报将千万倍于自身受用，真可以用‘舍一得万’来形容。地藏，布施因缘的来龙去脉和功德果报的轻重比较就是这样。”', NULL, '', 'indent', 1523465855, '5acdcdfc9f54540045e8fd37', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637124, '地藏经 · 地神护法品第十一', NULL, 5, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%9C%B0%E7%A5%9E%E6%8A%A4%E6%B3%95%E5%93%81%E7%AC%AC%E5%8D%81%E4%B8%80/5221249', '', '尔时坚牢地神白佛言：世尊，我从昔来瞻视顶礼无量菩萨摩诃萨，皆是大不可思议神通智慧，广度众生。是地藏菩萨摩诃萨，于诸菩萨誓愿深重，世尊，是地藏菩萨于阎浮提有大因缘。如文殊、普贤、观音、弥勒，亦化百千身形，度于六道，其愿尚有毕竟。是地藏菩萨教化六道一切众生，所发誓愿劫数，如千百亿恒河沙。
世尊，我观未来及现在众生，于所住处，于南方清洁之地，以土石竹木作其龛室，是中能塑画，乃至金银铜铁，作地藏形像，烧香供养，瞻礼赞叹。是人居处，即得十种利益。何等为十：
一者、土地丰壤；二者、家宅永安；三者、先亡生天；四者、现存益寿；五者、所求遂意；六者、无水火灾；七者、虚耗辟除；八者、杜绝恶梦；九者、出入神护；十者、多遇圣因。
世尊，未来世中，及现在众生，若能于所住处方面，作如是供养，得如是利益。
复白佛言：世尊，未来世中，若有善男子善女人，于所住处，有此经典及菩萨像，是人更能转读经典，供养菩萨。我常日夜以本神力，卫护是人，乃至水火盗贼，大横小横，一切恶事，悉皆消灭。
佛告坚牢地神：汝大神力，诸神少及。何以故？阎浮土地，悉蒙汝护，乃至草木沙石，稻麻竹苇，谷米宝贝，从地而有，皆因汝力。又常称扬地藏菩萨利益之事。汝之功德，及以神通，百千倍于常分地神。若未来世中，有善男子善女人，供养菩萨，及转读是经，但依地藏本愿经一事修行者。汝以本神力而拥护之，勿令一切灾害及不如意事，辄闻于耳，何况令受。非但汝独护是人故，亦有释梵眷属，诸天眷属，拥护是人。何故得如是圣贤拥护，皆由瞻礼地藏形像，及转读是本愿经故，自然毕竟出离苦海，证涅槃乐。以是之故，得大拥护。', '《地神护法品第十一》出自佛教经典《地藏经》。这一品通过坚牢地神与世尊之间的问答，说明了地藏菩萨大愿之殊胜及瞻礼供养地藏菩萨所获利益。', '坚牢地神：梵名Prthivi，音译为比里底毗，又作坚固地神、地神天、持地神、地天等。色界十二天之一，乃主掌大地之神。坚牢地神：亦称坚牢地祗，坚牢地天。大地神女之名，义为地之坚牢与神之不坏也。欲求资财珍宝伏藏、神通长寿妙药、疗治众病、降伏怨敌、制诸异论时，可结道场，如法求之。《金光明最胜王经》第八品为“坚牢地神品”；《金光明经》第九品为“坚牢地神品”，《观佛三昧经》及《大日经》中，皆言及坚牢地神。
观音菩萨：旧称观世音，略称观音；新称观世自在、观自在。观世音者，观世人称彼菩萨名之音而垂救；观自在者，观世界而自在拔苦与乐。观音有六观音、七观音、乃至三十三观音。但常称之观音为六观音中之圣观音，如《法华经·普门品》及《观无量寿经》中之观音乃观音之总体。与西方弥陀四菩萨之最初法菩萨同体。显教以为阿弥陀佛之弟子，密教以为阿弥陀佛之化身。与大势至菩萨同为弥陀之二胁士，而赞其教化。观音之本地乃正法明如来，为济度众生而现菩萨身也，见《千手千眼大悲心陀罗尼经》。《悲华经》云：于阿弥陀佛涅槃后，观音成佛，号遍出一切光明功德山如来。《观音授记经》云：“阿弥陀佛灭度后，补处号普光功德山王如来。其净土在印度南海岸补陀落迦山。观音顶戴阿弥陀佛，《般舟赞》曰：“天冠化佛高千里，念报慈恩常顶戴。”经云：观世音名宝意，作日天子；大势至名宝吉祥，作月天子；虚空藏名宝光，作星天子。
龛室：龛，音“看”，安置佛像之小柜或石室也。又称“塔下室”，用以贮存僧人遗体。
丰壤：此处“壤”即“穰”也，古时壤穰相通。五谷丰收曰穰。故知丰壤者，即丰穰、丰收也。
虚耗辟除：虚者空虚、空乏；耗者，消耗，指意外的损失。此句意为以诵《地藏经》之功德力，可免除种种意外之损失也。
水火盗贼：指种种祸事：“水”指水灾；“火”指火灾；“盗”指失窃被盗，丢失财物；“贼”指凶恶杀人放火抢掠之恶人也。
辄闻于耳：辄，音哲，“常常”之意，“总是”之意。此句为“常常听到”之意。
圣贤：圣人与贤人也。圣乃正之义，初地以上息妄契真会正，名圣。有圣法之人，得圣戒、圣定之人，指大小乘见道以上，断惑证理之人，常以指佛菩萨。贤乃和于善，虽离恶，而未发无漏智，不证理，不断惑，尚在凡夫之位。以十住、十行、十回向为三贤；以初地至十地为圣。
（9）拥护：拥者，亲而围之，拥戴也；护者，呵护，保护也。', '这时，坚牢地神起身恭敬地向佛说：“世尊，我从过去久远时间以来，已瞻礼无量无数的菩萨摩诃萨。这些菩萨摩诃萨都具有广大、不可思议的神通和智慧，普度一切众生，相比之下，这位地藏菩萨摩诃萨，在我所顶礼的所有大菩萨中，所发的誓愿最为深重。世尊，这位地藏菩萨与阎浮提的众生有极大的因缘。其他的大菩萨，如文殊菩萨、普贤菩萨、观音菩萨、弥勒菩萨等，也同样化现出成百上千的身形在六道中度化众生，但他们的誓愿尚有完结的一天，唯有地藏菩萨教化六道中的一切众生，所发誓愿的劫数，如同千百亿恒河沙一样，无穷无尽。”“世尊，我观察未来世和现在世的众生，如果能够在他们的居所中朝南的地方，找一块清净之地，用土石竹木等材料作一个龛室，在龛室中，或是雕塑，或是彩画，或是金、银、铜、铁铸刻地藏菩萨的形象，每天烧香供养，瞻礼赞叹地藏菩萨，那么这个人的住所就可以得到十种利益。哪十种呢？一者，土地丰壤（土地肥沃，物产丰富）；二者，家宅永安（家宅安稳，眷属平安）；三者，先亡生天（祖先获福，超升天上）；四者，现存益寿（在世家人，延年益寿）；五者，所求遂意（所有愿求，悉皆满足）；六者，无水火灾（远离水火等天灾厄难）；七者，虚耗辟除（避免亏损虚耗之事）；八者，杜绝恶梦（夜梦安乐，无诸横事）；九者，出入神护（往来出入，善神卫护）；十者，多遇圣因（常遇佛法，多结善缘）。世尊，未来世和现在世中的众生，若能在自己的住所做如上所说的供养，就可以得到上述的大利益。”接着，坚牢地神又说：“世尊，在未来世中，倘若有善男子、善女人在自己的住处里有这部不可思议的经典及地藏菩萨像，而且能常常读诵这部经，供养地藏菩萨，我将以神力，于日日夜夜之间保护这个人，诸如水灾火灾、强盗小偷、大小横祸等一切恶事，全都消除，不给他们带来任何困扰。”龙宫入定佛称赞坚牢地神说：“像你这样的神通大力，不是一般神祇所能够相比的。为什么呢？因为整个阎浮提世界的土地都是由你在保护，无论是草木沙石、稻麻竹苇，以至于地下埋藏的种种宝物，都是依赖于你神力的护持。你还能够常常称扬地藏菩萨利益众生的事迹，你的功德与神通比起一般的地神来，要超过何止千百倍。倘若在未来世，有善男子、善女人供养地藏菩萨以及读诵这部经典，或者专依《地藏菩萨本愿经》中所讲的法门修行的话，你应当以神力来保护他，不要让一切灾害及不如意的事使他听到，更何况使他受害了。非但只有你在保护这个人，帝释、梵天所的统领众多天人、天神也都在无形中拥护此人。为什么会得到这么多贤圣的保护呢？这都是由于瞻视礼拜地藏菩萨的形象以及念诵《地藏菩萨本愿经》的缘故，自然而然能最终跳出三界的生死苦海，证到涅槃的真实快乐。正因为如此，才会得到这么多贤圣的保护啊。”', NULL, '', 'indent', 1523465913, '5acdce3717d00900318c299c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637125, '地藏经 · 见闻利益品第十二', NULL, 4, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E8%A7%81%E9%97%BB%E5%88%A9%E7%9B%8A%E5%93%81%E7%AC%AC%E5%8D%81%E4%BA%8C/5784631?fr=aladdin', '', '尔时世尊，从顶门上，放百千万亿大毫相光，所谓：白毫相光、大白毫相光、瑞毫相光、大瑞毫相光、玉毫相光、大玉毫相光、紫毫相光、大紫毫相光、青毫相光、大青毫相光、碧毫相光、大碧毫相光、红毫相光、大红毫相光、绿毫相光、大绿毫相光、金毫相光、大金毫相光、庆云毫相光、大庆云毫相光、千轮毫光、大千轮毫光、宝轮毫光、大宝轮毫光、日轮毫光、大日轮毫光、月轮毫光、大月轮毫光、宫殿毫光、大宫殿毫光、海云毫光、大海云毫光。
于顶门上放如是等毫相光已，出微妙音，告诸大众，天龙八部、人非人等：听吾今日于忉利天宫，称扬赞叹地藏菩萨于人天中，利益等事、不思议事、超圣因事、证十地事、毕竟不退阿耨多罗三藐三菩提事。
说是语时，会中有一菩萨摩诃萨，名观世音，从座而起，胡跪合掌白佛言：世尊，是地藏菩萨摩诃萨具大慈悲，怜愍罪苦众生，于千万亿世界，化千万亿身。所有功德及不思议威神之力。我闻世尊，与十方无量诸佛，异口同音，赞叹地藏菩萨云：正使过去现在未来诸佛，说其功德，犹不能尽。向者，又蒙世尊，普告大众：欲称扬地藏利益等事。唯愿世尊，为现在未来一切众生，称扬地藏不思议事，令天龙八部，瞻礼获福。
佛告观世音菩萨：汝于娑婆世界有大因缘。若天若龙、若男若女、若神若鬼、乃至六道罪苦众生，闻汝名者、见汝形者、恋慕汝者、赞叹汝者。是诸众生，于无上道，必不退转。常生人天，具受妙乐。因果将熟，遇佛受记。汝今具大慈悲，怜愍众生，及天龙八部，听吾宣说地藏菩萨不思议利益之事。汝当谛听，吾今说之。
观世音言：唯然，世尊，愿乐欲闻！
佛告观世音菩萨：未来现在诸世界中，有天人受天福尽，有五衰相现，或有堕于恶道之者。如是天人，若男若女，当现相时，或见地藏菩萨形像、或闻地藏菩萨名，一瞻一礼。是诸天人，转增天福，受大快乐，永不堕三恶道报。何况见闻菩萨，以诸香华、衣服、饮食、宝贝、璎珞，布施供养，所获功德福利，无量无边。
复次观世音：若未来现在诸世界中，六道众生临命终时，得闻地藏菩萨名，一声历耳根者。是诸众生，永不历三恶道苦。何况临命终时，父母眷属，将是命终人舍宅、财物、宝贝、衣服，塑画地藏形像。或使病人未终之时，眼耳见闻，知道眷属将舍宅、宝贝等为其自身塑画地藏菩萨形像。是人若是业报合受重病者，承斯功德，寻即除愈，寿命增益。是人若是业报命尽，应有一切罪障业障，合堕恶趣者。承斯功德，命终之后，即生人天，受胜妙乐，一切罪障，皆悉消灭。
复次观世音菩萨：若未来世，有男子女人，或乳哺时、或三岁、五岁、十岁以下，亡失父母，乃及亡失兄弟姐妹，是人年既长大，思忆父母及诸眷属，不知落在何趣、生何世界、生何天中？是人若能塑画地藏菩萨形像，乃至闻名，一瞻一礼，一日至七日，莫退初心，闻名见形，瞻礼供养。是人眷属，假因业故，堕恶趣者，计当劫数，承斯男女，兄弟姊妹，塑画地藏形像，瞻礼功德，寻即解脱，生人天中，受胜妙乐。是人眷属，如有福力，已生人天，受胜妙乐者，即承斯功德，转增圣因，受无量乐。
是人更能三七日中，一心瞻礼地藏形像，念其名字，满于万遍。当得菩萨现无边身，具告是人，眷属生界。或于梦中，菩萨现大神力，亲领是人，于诸世界，见诸眷属。更能每日念菩萨名千遍，至于千日。是人当得菩萨遣所在土地鬼神，终身卫护，现世衣食丰溢，无诸疾苦。乃至横事不入其门，何况及身。是人毕竟得菩萨摩顶授记。
复次观世音菩萨：若未来世有善男子善女人，欲发广大慈心，救度一切众生者，欲修无上菩提者，欲出离三界者。是诸人等，见地藏形像，及闻名者，至心归依，或以香华、衣服、宝贝、饮食，供养瞻礼。是善男女等，所愿速成，永无障碍。
复次观世音：若未来世，有善男子善女人，欲求现在未来百千万亿等愿，百千万亿等事。但当归依瞻礼、供养赞叹，地藏菩萨形像。如是所愿所求，悉皆成就。复愿地藏菩萨具大慈悲，永拥护我。是人于睡梦中，即得菩萨摩顶授记。
复次观世音菩萨：若未来世，善男子善女人，于大乘经典，深生珍重，发不思议心，欲读欲诵。纵遇明师教视令熟，旋得旋忘，动经年月，不能读诵。是善男子等，有宿业障，未得消除，故于大乘经典，无读诵性。如是之人，闻地藏菩萨名、见地藏菩萨像，具以本心恭敬陈白，更以香华、衣服、饮食、一切玩具，供养菩萨。以净水一盏，经一日一夜安菩萨前，然后合掌请服，回首向南。临入口时，至心郑重，服水既毕，慎五辛酒肉，邪淫妄语，及诸杀害，一七日或三七日。是善男子善女人，于睡梦中，具见地藏菩萨现无边身，于是人处，授灌顶水。其人梦觉，即获聪明，应是经典，一历耳根，即当永记，更不忘失一句一偈。
复次观世音菩萨：若未来世，有诸人等，衣食不足，求者乖愿、或多病疾、或多凶衰、家宅不安、眷属分散、或诸横事，多来忤身，睡梦之间，多有惊怖。如是人等，闻地藏名、见地藏形，至心恭敬，念满万遍。是诸不如意事，渐渐消灭，即得安乐、衣食丰益，乃至于睡梦中，悉皆安乐。
复次观世音菩萨：若未来世，有善男子善女人，或因治生、或因公私、或因生死、或因急事，入山林中、过渡河海、乃及大水、或经险道。是人先当念地藏菩萨名万遍，所过土地，鬼神卫护，行住坐卧，永保安乐。乃至逢于虎狼狮子，一切毒害，不能损之。
佛告观世音菩萨：是地藏菩萨，于阎浮提有大因缘，若说于诸众生见闻利益等事，百千劫中，说不能尽。是故观世音，汝以神力流布是经，令娑婆世界众生，百千万劫永受安乐。
尔时世尊，而说偈言：
吾观地藏威神力，恒河沙劫说难尽，见闻瞻礼一念间，利益人天无量事。
若男若女若龙神，报尽应当堕恶道，至心归依大士身，寿命转增除罪障。
少失父母恩爱者，未知魂神在何趣，兄弟姊妹及诸亲，生长以来皆不识。
或塑或画大士身，悲恋瞻礼不暂舍，三七日中念其名，菩萨当现无边体，
示其眷属所生界，纵堕恶趣寻出离。若能不退是初心，即获摩顶受圣记。
欲修无上菩提者，乃至出离三界苦。是人既发大悲心，先当瞻礼大士像，
一切诸愿速成就，永无业障能遮止。有人发心念经典，欲度群迷超彼岸，
虽立是愿不思议，旋读旋忘多废失，斯人有业障惑故，于大乘经不能记。
供养地藏以香华，衣服饮食诸玩具，以净水安大士前，一日一夜求服之，
发殷重心慎五辛，酒肉邪淫及妄语，三七日内勿杀害，至心思念大士名，
即于梦中见无边，觉来便得利根耳，应是经教历耳闻，千万生中永不忘。
以是大士不思议，能使斯人获此慧。贫穷众生及疾病，家宅凶衰眷属离。
睡梦之中悉不安，求者乖违无称遂。至心瞻礼地藏像，一切恶事皆消灭。
至于梦中尽得安，衣食丰饶神鬼护。欲入山林及渡海，毒恶禽兽及恶人，
恶神恶鬼并恶风，一切诸难诸苦恼。但当瞻礼及供养，地藏菩萨大士像，
如是山林大海中，应是诸恶皆消灭。观音至心听吾说，地藏无尽不思议，
百千万劫说不周，广宣大士如是力。地藏名字人若闻，乃至见像瞻礼者，
香华衣服饮食奉，供养百千受妙乐。若能以此回法界，毕竟成佛超生死。
是故观音汝当知，普告恒沙诸国土。', '《见闻利益品第十二》出自佛教经典《地藏经》。在这一品中，世尊称扬赞叹地藏菩萨的功德，嘱咐观世音菩萨以神力流布地藏经。', '顶门：佛顶最上处，即中医所谓“百会”穴，此是最高处，以无有更上，非凡夫能见，亦号无见顶相。佛法和合，出生最上功德，故于顶门放光，光即功德也。诸佛以佛光度生，佛光出生一切无上功德，故佛光即无量清净恒沙性功德也。
毫相光：又作眉间白毫相、白毫庄严面相、白毫毛光相、眉间白毫光相、眉间毫相、额上毫相功德满足相、眉间白毛长好右旋相、眉间白毫软白兜罗绵相，为如来三十二相之一。
超圣因事：圣因者，能得见圣闻法之因缘也。见第七章注。超圣因事者，指地藏菩萨具不可思议智力，说法度生，令离生死苦，得涅槃乐之超凡入圣之事也。
证十地事：十地者，修大乘菩萨道，必先破尽见惑方可入圣位，称‘地上菩萨’。故知：十信为‘外凡位’，十住、十行、十回向为‘内凡位’或贤位（称三贤位），此皆在凡夫位之列，以其尚未破尽见惑也。十地者：初地、欢喜地：菩萨满初阿僧祗劫之行，成就“施”度，初得圣性，破见惑，证二空性，生大欢喜也。二、离垢地：成就“戒”度，断修（思）惑，除毁犯之垢，身心清净。三、发光地：成就“忍”度，断修惑，得谛察法忍，智慧显发而现光也。四、焰慧地：成就“勤”（精进）度，断修惑，慧性炽盛。五、极难胜地：成就“禅”度，断修惑，和合真俗二智使之相应。六、现前地：成就“慧”度，断修惑，发最胜智，使现前无染净差别。七、远行地：成就“方便”度，发大悲心，亦断修惑，远离二乘自度也。八、不动地：第三阿僧祗劫之始也。成就“愿”度，断修惑，作无相观，任运无功用相续。九、善慧地：成就“力”度，断修惑，具足十力，于一切处知可度不可度，能说法也。十、法云地：成就“智”度，亦断修惑，具足出生无边功德，如大云复空出清净水。“证十地”者，谓地藏菩萨早已自证十地之果，复能起大悲大智之心，化度一切众生，令皆得证十地也。
怜悯：见人受苦而起的慈悲之情。
五衰相：天人将死的时候，所现出来的五种衰相，有小和大两种。小的五衰相：一、口出恶声；二、身光微昧；三、浴水著身；四、著境不舍；五、身虚眼瞬。大的五衰相：一、头上花萎；二、衣裳秽污；三、体生臭气；四、腋下汗出；五、不乐本座。诸经所说不一。《涅槃经》云：“释提桓因，命欲将终，有五相现：一者衣裳垢腻，二者头上花萎，三者身体臭秽，四者腋下汗出，五者不乐本座。”<俱舍论>说大小之五种衰相：“然诸天子将命终时，先有五种相现：一者、衣服严具出非爱声；二者、自身光明忽然昧劣；三者、于沐浴位水着身；四者、本性嚣驰，令滞一境；五者、眼本凝寂，今数瞬动。此五衰相现，非定当死。复有五种大衰相现：一者、衣染埃尘；二者、花蔓萎悴；三者、两腋汗出；四者、臭气入身；五者、不乐本座。此五相现，必定当死。”
璎珞：梵语枳由罗，编玉悬于身以为装饰之具。印度男女贵族多用此。
三界：欲界、色界、无色界。一、欲界，是最低下的界域，具有淫欲与贪欲的众生都居于此。二、色界，在欲界之上，为离淫欲、食欲的众生所居地。三、无色界，是最上的领域，是超越于物质之上的世界。
陈白：陈者，陈述；白者，表白。向佛陈说，恭敬发问，表白自心之意。又赞叹佛的话语，也称“白佛”。
五辛：指五种有辛味之蔬菜，又作五荤，即韭、葱、蒜、薤、兴蕖。与酒、肉同为佛弟子所禁食之物。五辛：即五荤，凡物辛臭者皆曰荤。《梵网经》云：“若佛子不得食五辛：大蒜、（音谢）葱、慈葱、兰葱、兴渠。是五种一切食中不得食，若故食，犯轻垢罪。”《楞严经》云：“诸众生求三摩提，当断世间五种辛菜，此五种辛，熟食发淫，生啖增恚。如是世界食辛之人，纵能宣说十二部经，十方天仙嫌其臭秽，咸皆远离。”其中：“葱是薤（音谢）即韭菜，俗称“头”，可作酱菜及入药”。“慈葱”即普通之葱，包括大小葱。“兰葱”是小蒜。“兴渠”生于新疆于阗，色白，其臭如蒜，中原无此物也。
灌顶：以水灌于头顶，受灌者即获晋升一定地位之仪式。原为古代印度帝王即位及立太子的一种仪式，国师以四大海之水灌其头顶，表示祝福。此仪式后为佛教所采纳，其中密教最重灌顶。
忤身：忤，音“五”，违逆，抵触也。忤身者，指以种种违逆之言、行、事伤其身心，令不得安乐也。', '这时，释迦牟尼佛从其顶门白毫之中放出百千万亿大毫相光。所谓白毫相光、大白毫相光、瑞毫相光、大瑞毫相光、玉毫相光、大玉毫相光、紫毫相光、大紫毫相光、青毫相光、大青毫相光、碧毫相光、大碧毫相光、红毫相光、大红毫相光、绿毫相光、大绿毫相光、金毫相光、大金毫相光、庆云毫相光、大庆云毫相光、千轮毫光、大千轮毫光、宝轮毫光、大宝轮毫光、日轮毫光、大日轮毫光、月轮毫光、大月轮毫光、宫殿毫光、大宫殿毫光、海云毫光、大海云毫光。在顶门中放如此种种的毫相光之后，又以种种微妙的音声普告在场的天龙八部、人非人等大众说：“你们今天听我在忉利天宫的大会上，称扬赞叹地藏菩萨利益人天众生的事迹，种种不可思议的事迹，超凡入圣的事迹，证入十地果位的事迹，以及令一切众生永远不退转于无上正等正觉、究竟成佛的事迹。”佛说这些话的时候，法会中有一位菩萨摩诃萨，名号为观世音，从座位上起身，右膝着地，合掌恭敬地对佛说：“世尊，这位地藏菩萨摩诃萨，具有大慈大悲的心愿，怜悯一切因造罪而受苦的众生，在千万亿的世界中，化现出千万亿的身形度脱众生，他所做的功德和具有威神力量皆不可思议。我听到世尊以及十方无量无数的诸佛，异口同声地赞叹地藏菩萨。即使过去、现在、未来一切诸佛一起来论说地藏菩萨的功德，也是说不尽的。刚才承蒙世尊普告大众说，要称扬赞叹地藏菩萨利益一切众生的种种事迹。现在我虔诚地盼望世尊为现在及未来的一切众生，称扬地藏菩萨种种不可思议的、利益众生的事迹，使天龙八部等一切众生能够得知其详，瞻仰礼拜地藏菩萨，从而获得更大的福报。”佛告诉观世音菩萨说：“你与娑婆世界有着很深的因缘。在这娑婆世界中，无论是天人，还是龙众；无论是男人，还是女子；无论是神鬼，乃至六道中一切罪苦众生，若有缘听到你的名号，见到你的形象，恋慕敬仰你，称颂赞叹你，这些众生必定能最终成就无上道业，直至成佛。这些众生还可以常常生在天界或富贵的人间，享受种种微妙的安乐。一旦时机成熟，必定会遇到佛给他授记。你现在以大慈悲心，怜悯天龙八部及一切众生，来听我宣说地藏菩萨种种不可思议的事迹。你仔细倾听，我现在就为你们解说。”观世音菩萨回答说：“是的，世尊，我们都非常乐意想要听到这些事。”这时，本师释迦牟尼佛就告诉观世音菩萨及在会的一切大众说：“在未来世及现在世中，如果有天道的众生，天福快要享尽的时候，就会有五种衰败之相出现，甚至将来还有可能要堕入到恶道中去。像这样的天人，无论是男是女，正当出现五衰相时，若能有缘见到地藏菩萨的形象，或是听到地藏菩萨的名号，能以恭敬心，哪怕一瞻仰，一礼拜，这些天人马上就可以转而增加许多天福，继续在天界享受极大的快乐，永不会堕入三恶道遭受苦报。更何况在见到地藏菩萨形象、听到地藏菩萨名号时，能以恭敬心，用种种香花、衣服、饮食、宝贝、璎珞去供养地藏菩萨，那他所获得的福利，更是无量无边了。”“另外，观世音菩萨，在未来世及现在世中，如果有六道里的众生在临死前，能有缘听到地藏菩萨的名号，哪怕只有一声，能听到耳朵里去，那么这样的众生，将永不会到三恶道里去受苦了。更何况在他们临命终之时，家里的父母、眷属将房产、财物、珍宝以及衣服等都布施出去，用来雕塑或彩画地藏菩萨的形象，供养地藏菩萨的形象。假如在病人未死之际，让他亲眼看到，亲耳听到，明白家中亲人已经为他广修布施与供养。倘若这人命不该死，只是该得一场重病，由于上面所说的功德，马上可以恢复健康，同时还能增长寿命。倘若这个人阳寿已尽，由于生前所做种种罪业，死后应堕入到三恶道去，由于这超度的功德，在命终之后，即可生天享受美妙的福乐，而过去所造的一切罪业都已消灭了。”“另外，观世音菩萨，假如在未来世，有男子或女人，或是在哺乳的婴儿时期，或是在三岁、五岁、十岁以下的童年时期，死去了父母或兄弟姐妹，长大成人以后，时常思念已过世的父母或是其他亲人，不知道他们现在哪一道中生活，或者投生在什么世界里，或哪一重天上？此人如果能以恭敬心塑画地藏菩萨形象，听到地藏菩萨的名号后，不断地瞻仰、礼拜，在一天、两天直到七天之中，天天如此，不退初心，称念地藏菩萨名号，礼拜供养地藏菩萨，那么此人已经过世的亲属，假如他们因为罪报而堕落到恶道中去的，本应当在恶道中受满该有的劫数，凭借着亲人塑画、瞻礼、供养地藏菩萨的功德，不久便可以解脱恶道之苦，投生到天界或人间的富贵人家中去享受最美妙的快乐了。假如已过世的亲人本来就很有福报，已经生在天界或富贵人家享受种种快乐了，那么，承蒙现在亲人给他做的种种功德，不但其福报快乐无量无边，而且在佛法中结下了解脱之缘。假如这个人能够在二十一天里，一心一意地瞻仰礼拜地藏菩萨的形象，称念地藏菩萨的名号达一万遍，那就可以感应到地藏菩萨亲自显现无边身，明明白白地告诉这个人：你那位早已过世的亲人，现在生在某某世界里。或是在睡梦中，地藏菩萨以大神力，亲自带领此人在各个世界里，见到他所思念的亲人。倘若能再进一步，每天称念地藏菩萨名号一千遍，连续一千天始终不断，那么，此人将得到地藏菩萨指派他所居住地方的土地神灵终身保护他，现在世令他丰衣足食，没有病苦，大小横事、不吉利事均不入其门，更不用说伤害到他了。非但如此，此还可以得到地藏菩萨给他摩顶授记，最终必定觉悟解脱。”“另外，观世音菩萨，倘若在未来世，有善男子、善女人，想要发广大的慈悲心去救度一切众生，修习无上菩提，跳出三界生死轮回等。这些人若能在见到地藏菩萨形象、听到地藏菩萨名号后，以至诚心发林间宴坐愿皈依地藏菩萨，并以种种的香、花、衣服、宝贝、饮食去供养、瞻礼地藏菩萨，那么，这些善男子、善女人的愿望会很快地实现，永不会有什么障碍。”“还有，观世音菩萨，倘若在未来世，有善男子、善女人想要实现现在或将来百千万亿的种种心愿，想要办成现在的或将来的百千万亿的种种事情，只要一心皈依瞻礼、供养赞叹地藏菩萨的形象，那么，这些所愿所求都能达成。如果进一步发愿祈求地藏菩萨以大慈悲心永远保护‘我’（即发愿者），那么此人在睡梦中，就可以得到地藏菩萨的摩顶授记。”“还有，观世音菩萨，倘若在未来世，有善男子、善女人对大乘经典产生深切的敬仰心、尊重心、爱护心，发不可思议的愿心，要学习读诵经典，但即使得到明师的指点教诲，仍然前念后忘，经过数月乃至数年都无法读诵、背熟。这是因为这些善男子、善女人有过去所做的业障在障碍着他，所以对于大乘经典就没有熟读背诵的善根。像这样的人，若能在听到地藏菩萨名号、见到地藏菩萨形象后，发自内心、恭敬挚诚地向地藏菩萨表白自己的心愿，请求地藏菩萨的加被，更以香、花、衣服、饮食，以及一切美好的珍玩物品来供养地藏菩萨。以洁净的清水一盏，供在菩萨像前，经一天一夜，然后恭敬合掌，请求饮用此水（注意应将水换下，用别的杯子饮用，不能用供杯）。饮水之前，回过身来，面向南方，然后郑重其事，专心致志将水喝下。喝完净水之后，千万谨慎，戒五辛、戒酒肉、戒杀、戒盗、戒邪淫、戒妄语。这样，经过七天或二十一天，此人在睡梦中，会明明白白见到地藏菩萨现无边身，来到身旁，给他授灌顶水。醒来之后，这个人马上就变得很聪明，任何大乘经典只要听到一次后，就永不会再忘记了，乃至一句经，一句偈都能牢记如初。”“另外，观世音菩萨，倘若在未来世，或有人衣食不足，生计维艰；或有人事与愿违，所求不遂；或有人疾病缠身，凶耗不断；或有人合家不安，亲人离散；或有人横祸连绵，伤身害命；或有人睡梦不安，惊恐万状。这些业障深重的众生，如果有缘听到地藏菩萨名号或见到地藏菩萨形象，能够至心恳切地称念地藏菩萨名号满一万遍，那么，这许多不如意的事就会逐渐减轻直至消灭，而得到安稳、快乐的生活，日常衣食丰足，睡梦中也能得到安宁快乐。”“还有，观世音菩萨，倘若在未来世，有善男子、善女人，或是因为要外出谋生；或是为了公私事宜；或是去报生讣死；或是因事情急迫，不得已要穿山入林，渡河过海，经历惊涛骇浪或攀越悬崖峭壁等危险的地方。此人在出门之前，应当先虔诚念地藏菩萨的名号满一万遍，这样，他所要经过的地方，途中的一切鬼神、土地都来保护他。无论是行住坐卧，都能常保平安，哪怕在路上碰到豺狼虎豹、毒虫瘴气等，一切毒害都不能伤害到他。”
佛又继续告诉观世音菩萨说：“这位地藏菩萨同阎浮提众生有着极大的因缘。倘若要把地藏菩萨利益阎浮提众生的种种事迹统统说一遍，哪怕花上百千大劫的时间也是说不尽的。因此，观世音，你应当以神力来宣扬流布这部不可思议的经典，使未来、现在娑婆世界的众生在百千万劫中永享平安与福乐。”为了要进一步说明这件事，世尊又以偈言的形式重复了一遍：吾观地藏威神力，恒河沙劫说难尽，见闻瞻礼一念间，利益人天无量事。若男若女若龙神，报尽应当堕恶道，至心皈依大士身，寿命转增除罪障。少失父母恩爱者，未知魂神在何趣，兄弟姊妹及诸亲，生长以来皆不识，或塑或画大士身，悲恋瞻礼不暂舍，三七日中念其名，菩萨当现无边体，示其眷属所生界，纵堕恶趣寻出离，若能不退是初心，即获摩顶受圣记。欲修无上菩提者，乃至出离三界苦，是人既发大悲心，先当瞻礼大士像，一切诸愿速成就，永无业障能遮止。有人发心念经典，欲度群迷超彼岸，虽立是愿不思议，旋读旋忘多废失，斯人有业障惑故，于大乘经不能记，供养地藏以香华，衣服饮食诸玩具，以净水安大士前，一日一夜求服之，发殷重心慎五辛，酒肉邪淫及妄语，三七日内勿杀害，至心思念大士名，即于梦中见无边，觉来便得利根耳，应是经教历耳闻，千万生中永不忘，以是大士不思议，能使斯人获此慧。贫穷众生及疾病，家宅凶衰眷属离，睡梦之中悉不安，求者乖违无称遂，至心瞻礼地藏像，一切恶事皆消灭，至于梦中尽得安，衣食丰饶神鬼护。欲入山林及渡海，毒恶禽兽及恶人，恶神恶鬼并恶风，一切诸难诸苦恼，但当瞻礼及供养，地藏菩萨大士像，如是山林大海中，应是诸恶皆消灭。观音至心听吾说，地藏无尽不思议，百千万劫说不周，广宣大士如是力。地藏名字人若闻，乃至见像瞻礼者，香华衣服饮食奉，供养百千受妙乐，若能以此回法界，毕竟成佛超生死。是故观音汝当知，普告恒沙诸国土。', NULL, '', 'indent', 1523466022, '5acdcea29f54540044e6452a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637126, '地藏经 · 嘱累人天品第十三', NULL, 4, 153, 0, 1, '释迦牟尼', NULL, 10292, '57b902a9c4c97100558f333b', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%98%B1%E7%B4%AF%E4%BA%BA%E5%A4%A9%E5%93%81%E7%AC%AC%E5%8D%81%E4%B8%89/5221183', '', '尔时世尊举金色臂，又摩地藏菩萨摩诃萨顶，而作是言：地藏地藏，汝之神力不可思议、汝之慈悲不可思议、汝之智慧不可思议、汝之辩才不可思议，正使十方诸佛，赞叹宣说汝之不思议事，千万劫中，不能得尽。
地藏地藏，记吾今日在忉利天中，于百千万亿不可说，不可说，一切诸佛菩萨，天龙八部，大会之中，再以人天诸众生等，未出三界，在火宅中者，付嘱于汝。无令是诸众生，堕恶趣中，一日一夜，何况更落五无间，及阿鼻地狱，动经千万亿劫，无有出期。
地藏，是南阎浮提众生，志性无定，习恶者多。纵发善心，须臾即退。若遇恶缘，念念增长。以是之故，吾分是形，百千亿化度，随其根性而度脱之。
地藏，吾今殷勤，以天人众，付嘱于汝。未来之世，若有天人，及善男子善女人，于佛法中，种少善根，一毛一尘，一沙一渧，汝以道力，拥护是人，渐修无上，勿令退失。
复次地藏，未来世中，若天若人，随业报应，落在恶趣。临堕趣中，或至门首，是诸众生，若能念得一佛名，一菩萨名，一句一偈大乘经典。是诸众生，汝以神力，方便救拔，于是人所，现无边身，为碎地狱，遣令生天，受胜妙乐。
尔时世尊，而说偈言：
现在未来天人众，吾今殷勤付嘱汝，以大神通方便度，勿令堕在诸恶趣。
尔时地藏菩萨摩诃萨，胡跪合掌白佛言：世尊，唯愿世尊不以为虑。未来世中，若有善男子善女人，于佛法中，一念恭敬，我亦百千方便，度脱是人，于生死中速得解脱。何况闻诸善事，念念修行，自然于无上道永不退转。
说是语时，会中有一菩萨，名虚空藏，白佛言：世尊，我自至忉利，闻于如来赞叹地藏菩萨，威神势力，不可思议。未来世中，若有善男子善女人，乃及一切天龙，闻此经典及地藏名字，或瞻礼形像，得几种福利？唯愿世尊，为未来现在一切众等，略而说之。
佛告虚空藏菩萨：谛听谛听！吾当为汝分别说之。若未来世，有善男子善女人，见地藏形像，及闻此经，乃至读诵，香华饮食，衣服珍宝，布施供养，赞叹瞻礼，得二十八种利益：一者、天龙护念，二者、善果日增，三者、集圣上因，四者、菩提不退，五者、衣食丰足，六者、疾疫不临，七者、离水火灾，八者、无盗贼厄，九者、人见钦敬，十者、神鬼助持，十一者、女转男身，十二者、为王臣女，十三者、端正相好，十四者、多生天上。十五者、或为帝王，十六者、宿智命通，十七者、有求皆从，十八者、眷属欢乐，十九者、诸横消灭，二十者、业道永除，二十一者、去处尽通，二十二者、夜梦安乐，二十三者、先亡离苦，二十四者、宿福受生，二十五者、诸圣赞叹，二十六者、聪明利根，二十七者、饶慈愍心，二十八者、毕竟成佛。
复次虚空藏菩萨：若现在未来，天龙鬼神，闻地藏名，礼地藏形，或闻地藏本愿事行，赞叹瞻礼，得七种利益：
一者、速超圣地，二者、恶业消灭，三者、诸佛护临，四者、菩提不退，五者、增长本力，六者、宿命皆通，七者、毕竟成佛。
尔时，十方一切诸来，不可说不可说诸佛如来，及大菩萨天龙八部，闻释迦牟尼佛，称扬赞叹地藏菩萨，大威神力，不可思议，叹未曾有。
是时，忉利天，雨无量香华，天衣珠璎，供养释迦牟尼佛，及地藏菩萨已，一切众会，俱复瞻礼，合掌而退。', '《嘱累人天品第十三》出自佛教经典《地藏经》。这一品是《地藏经》的最后一品。世尊为虚空藏菩萨分别宣说了听闻《地藏经》及地藏名字、瞻礼地藏菩萨形象的功德利益。', '嘱累：以佛之圣旨而言，嘱为佛之嘱咐，累是烦汝宣传；以菩萨之修持而言，嘱是顶受所嘱；累是甘而弗劳；以授受之谊而言，佛为金口所嘱，菩萨以丹心顶戴也。
火宅：三界之生死譬如火宅也。《法华经·譬喻品》曰：“三界无安，犹如火宅，众苦充满，甚可怖畏。常有生老病死忧患，如是等火，炽然不息”。乃法华经七喻之一。
门首：指造恶众生命终之后，将欲堕入地狱而尚未入地狱之处，犹如处于地狱门首尚未进门也。
虚空藏：又名虚空孕，菩萨名，空慧之库藏，犹如虚空，故名虚空藏；包藏一切之功德，犹如虚空，故名虚空藏。胎藏界曼荼罗虚空藏院之中尊也。《大集经·虚空藏品》谓为从此东方大庄严世界一宝庄严佛所之菩萨。《虚空藏菩萨经》谓为从此西方一切香集依世界胜华敷藏如来所之菩萨。密宗以为金刚界之曼荼罗，在贤劫十六尊之中。若人欲求福智，当归依此菩萨，以明星为虚空藏菩萨之化身。虚空藏：梵名Akasa—garbha，音译为阿迦舍檗婆，又作虚空孕菩萨，即福、智二藏无量，等如虚空，广大无边之意。此菩萨流出无量之法宝，普施所欲者，利乐众生。
天衣：指天人所穿着之衣服，其重量极轻，且天愈高，衣则愈轻。据《长阿含经》卷二十载，四天王衣重半两，忉利天衣重六铢。', '这时，世尊举起清净无垢的金色手臂，又摩地藏菩萨摩诃萨的头顸，对他说：“地藏，地藏，你的神力不可思议，你的慈悲不可思议，你的智慧不可思议，你的辩才不可思议。即使十方一切诸佛同声赞叹、宣讲你的不可思议事迹，用上千万劫之久的时间也难以说尽。地藏，地藏，你应当牢记今天我在这忉利天中，百千万亿不可说、不可说一切诸佛菩萨、天龙八部所在的大会中，再次将天界人间的一切众生和尚在三界流转生死、在火宅中受苦受难的众生托付给你，不要让这些众生，再堕入到恶道里哪怕只有一天一夜，更何况落到那些五无间及阿鼻地狱中去，千万亿劫，没有出头之日。”“地藏，南阎浮提的众生，其心志与根性总是游移不定，作恶业的还在多数。即使偶尔发起一点善心，过不了多久就又退失了。相反如果遇到恶缘，恶念就会一天天膨胀起来。正因为这个缘故，我分身百千亿身形，根据众生不同的根性、习气、智慧、环境来有针对性地说法度化，使他们得到解脱。地藏二商奉食，我今天郑重殷切地将天上人间的众生托付给你。在未来世时，若有天上或人间的善男子、善女人，在佛法中哪怕只是种下如一毛一尘、一沙一滴这么渺小的一点善根，你都应当以你的神通之力，来保护这个人，使他走上佛法正道，千万不要使他产生退转之心或丧失前进的动力。”“还有，地藏，在未来世中，无论是天上或人间的众生，若是由于过去造下的种种恶业，应当堕入恶道。在他们将堕还未堕的时刻，倘若这些众生能亲口称念一尊佛的名号、一尊菩萨的名号，或是大乘经典里的一句话、一句偈。那么对于这些众生，你应当以你的神力想方设法救度他们，在他们所在的地方，化现无边身，为他粉碎地狱，使他得以超升，享受殊胜美妙的福乐。”为了进一步说明这个意思，佛又以偈言重复了一遍：“现在未来天人众，吾今殷勤付嘱汝，以大神通方便度，勿令堕在诸恶趣。”这时，地藏菩萨摩诃萨右膝着地，合掌恭敬地对佛说：“世尊，请不必为此事而有所忧虑，在未来世中，若有善男子、善女人于佛法中，哪怕只存有一念的恭敬心，我也会千方百计以种种方便去度脱他们，使他们跳出三界火宅，解脱生死轮回。更何况那些一听到种种善事便发心去做，念念之间勤恳修行的人，当然在佛法的解脱之道中，永不退转，必定成佛了。”说这话之时，大会中有一位菩萨，名号叫做虚空藏，恭敬地对佛说：“世尊，我今天自从来到忉利天宫，一直听到世尊赞叹地藏菩萨的威神之力不可思议。在将来世中，倘若有善男子、善女人，以及天龙八部一切众生等，有缘听到这部《地藏菩萨本愿经》及地藏菩萨的名号，或者瞻仰礼拜地藏菩萨形象，能够得到哪些福德利益，请求世尊为将来及现在的一切众生，大略地讲一讲。”佛告诉虚空藏菩萨说：“仔细倾听，我现在就为你分别解说一下。倘若在未来世，有善男子、善女人，见到地藏菩萨的形象，听到这部《地藏菩萨本愿经》，虔诚读诵这部经，并以种种香、花、饮食、衣服、珍宝去供养地藏菩萨，瞻礼赞叹地藏菩萨及《地藏菩萨本愿经》，可以得到二十八种利益：一者，天龙护念（得到天龙八部的卫护与保佑）；二者，善果日增（善果日日增益，福报日日积累）；三者，集圣上因（常常亲近佛法僧三宝，种下解脱的因缘）；四者，菩提不退（永不会退转于菩提觉悟之道）；五者，衣食丰足（家境充裕，物质生活丰富）；六者，疾疫不临（身心健康，没有种种疾病）；七者，离水火灾（远离水灾火灾等横祸）；八者，无盗贼厄（家宅安宁，不会遇到小偷、强盗）；九者，人见钦敬（受人尊敬，具有较高的社会地位）；十者，神鬼助持（得到各种鬼神暗中保护和帮助）；十一者，女转男身（不愿为女性者，来世转为男子之身）；十二者，为王臣女（生在国王大臣之家享受福贵）；十三者，端正相好（相貌端正美好）；十四者，多生天上（来世多转生天界，享受天福）；十五者，或为帝王（常为人间帝王，拥有权势）；十六者，宿智命通（知道前生后世的因果命运）；十七者，有求皆从（所求诸事，皆能遂其所愿）；十八者，眷属欢乐（家庭和睦，亲人欢乐）；十九者，诸横消灭（无飞来横祸，得享安宁）；二十者，业道永除（过去种种恶业都可以消除）；二十一者，去处尽通（无论到哪儿去，或谋求什么职业，都能通达顺利）；二十二者，夜梦安乐（夜间睡眠平和安乐）；二十三者，先亡离苦（故世的先人可以脱离恶道的苦难）；二十四者，宿福受生（本有宿福的，可以转生天上）；二十五者，诸圣赞叹（常常得到有德之人的赞美）；二十六者，聪明利根（六根聪明，智慧明达）；二十七者，饶慈愍心（心怀慈悲，怜悯众生）；二十八者，毕竟成佛（善根不断增长，最终必定成佛）。”“此外，虚空藏菩萨，倘若现在未来的天众、龙众、鬼神等众，能够听到地藏菩萨的名号，瞻礼地藏菩萨的形象，或者听到《地藏菩萨本愿经》，了解到地藏菩萨救度众生的本愿和事迹，这样可以得到七种利益：一者，速超圣地（能迅速地由凡夫地位上升到圣人的地位）；二者，恶业消灭（过去所做的种种恶业都能消灭）；三者，诸佛护临（得到诸佛菩萨的亲临加持）；四者，菩提不退（永不会退转于菩提道，直至成佛）；五者，增长本力（原有的神通力量得到增长）；六者，宿命皆通（得到宿命通，能知过去未来之事）；七者，毕竟成佛（善根不断增长，最终必定成佛）。”这时，十方世界一切到场的不可说、不可说数的诸佛如来，以及诸大菩萨摩诃萨、天龙八部等，听到释迦牟尼佛称扬赞叹地藏菩萨的种种大威神力及种种不可思议的功德之后，都发出由衷的感叹，这真是从来都不曾有过的稀有之事啊。这时，忉利天宫如同下雨一般，纷纷扬扬飘落着无量无数最美好的香花、天衣、珠宝、璎珞，来供养释迦牟尼佛及地藏菩萨。供养之后，一切集会的大众再次向释迦牟尼佛及地藏菩萨瞻视顶礼，恭敬合掌，心怀法喜，散会回去了。', NULL, '', 'indent', 1523466101, '5acdcef3d50eee0045cfedb5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637145, '野望', NULL, 58, 54, 2, 0, '杨广', NULL, 10532, '5858e5a061ff4b006cb8a3f1', '隋', 'shi', '诗', '', '', '寒鸦飞数点，流水绕孤村。
斜阳欲落处，一望黯消魂。', '这首触景抒情诗，通过山野秋景营造了一种寥落和孤寂的意境。全诗以白描手法，清新自然的语言，於萧瑟怡静的景色描写中流露出孤独抑郁的心情，抒发了惆怅、孤寂的情怀。全诗颇有诗境，流传于世，对唐宋词人产生了一定的影响。
「寒鸦飞数点，流水绕孤村。」这两句是说，千万点的寒鸦飞起落下；孤单的村庄被流水环绕。
诗人是在远眺，极目远眺，一副归心似箭的情态。视线无林树、群山的阻隔，正好远望。「长望当归」，欲归何时？「寒鸦」的「寒」，正映现心境之寒，「孤村」之「孤」，正见远离京国的孤单。
「斜阳欲落处，一望黯消魂。」这两句是说，斜阳欲落，暮霭渐逼，望之令人黯然销魂。
这首小诗很有意境，前三句皆景，首先映现的是「寒鸦」，再是「流水」、「孤村」，然后「斜阳」，形成了一个平远、萧疏、清冷、黯淡的境界。第四句「一望黯消魂」一下点醒，知道上面所写都是作者望中之景，为「有我之境」，而「黯销魂」又分明来自江淹《别赋》「黯然销魂者，唯别而已矣」，这就又将望中之情挑明了。一句出，全篇情活意动，最为警策。
这首诗营造了一种寥落和孤寂的意境，此时诗人心里会产生凉飕飕、空落落的感觉，村庄是很孤单，有流水环绕，有所凭依，似乎也不那么孤零了。流水看来还是那么有情，流水啊，何时送我回归？「一切景语皆情语」，这中间有玩索无尽的意味。
全诗意境浑成，语言又很自然、圆熟，因此博得了许多人的称赞。', '', '', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecce503048e64fbd9c768", "shortContent": "此诗一、二句为南北宋间几种诗话、笔记征引，阙题。明杨慎《升庵诗话》、莫是龙《笔麈》载录全篇，题作《野望》。第一句二书为“寒鸦飞数点”，而宋籍皆作“千万点”，从之。此诗当为炀帝登位前作，很可能作于南方。其为晋王时曾帅师伐陈，后又巡察江南，皆可为此诗写作背景。其《早渡淮》有“会待高秋晚，愁因逝水归”句，正可与此诗相发明（诸葛颖诸人有《奉和出颍至淮应令》诗，知《早渡淮》为登位前作）。\n这首小诗很有意境。...", "authors": ["汤华泉"], "pressName": "上海辞书出版社"}]', '', 'center', 1523568130, '5acf5d6a7f6fd30062f73aa6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637162, '采葵莫伤根', NULL, 24, 496, 1, 1, '无名氏', NULL, 10100, '57b959c18ac2470062e2a00f', '汉', 'shi', '诗', 'https://baike.baidu.com/item/%E9%87%87%E8%91%B5%E8%8E%AB%E4%BC%A4%E6%A0%B9/6597807?fr=aladdin', '', '采葵莫伤根，伤根葵不生。
结交莫羞贫，羞贫友不成。
甘瓜抱苦蒂，美枣生荆棘。
利旁有倚刀，贪人还自贼。', '语出《古诗源．古诗》:"采葵莫伤根，伤根葵不生；结交莫羞贫，羞贫交不成。"后因以"采葵"喻不耻与贫贱者为友。', '葵：冬葵，一种野菜名，又名冬寒菜。葵kuí〔向日葵〕一年生草本植物，茎很高，开大黄花，花常朝向太阳，子可食，亦可榨油。简称“葵
采：采cǎi摘取：采撷。采花。采摘。采制。选取，搜集，开发，利用：采访（搜集寻访）。采纳（接受意', '', NULL, '', 'center', 1523619756, '5ad0272bd50eee003cac569e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (638380, '杏花天（杏花）', NULL, 1, 109, 0, 1, '高观国', NULL, 30620, '5858f80e1b69e6006cb18441', '宋', 'ci', '词', '', '', '玉坛消息春寒浅。露红玉、娇生靓艳。小怜鬓湿燕脂染。只隔粉墙相见。
花阴外、故宫梦远。想未识、莺莺燕燕。飘零翠径红千点。桃李春风已晚。 ', '', '', '', NULL, '', 'indent', 1532519086, '5b57f237808ca40070ad65b0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637164, '苏武诗四首 · 其一', NULL, 2, 496, 1, 0, '无名氏', NULL, 10100, '57b959c18ac2470062e2a00f', '汉', 'shi', '诗', 'https://baike.baidu.com/item/%E8%8B%8F%E6%AD%A6%E8%AF%97%E5%9B%9B%E9%A6%96/10352446?fr=aladdin', '', '骨肉缘枝叶，结交亦相因。
四海皆兄弟，谁为行路人。
况我连枝树，与子同一身。
昔为鸳与鸯，今为参与辰。
昔者常相近，邈若胡与秦。
惟念当离别，恩情日以新。
鹿鸣思野草，可以喻嘉宾。
我有一樽酒，欲以赠远人。
愿子留斟酌，叙此平生亲。
', '《苏武诗四首》又名《苏武与李陵诗四首》。是东汉无名氏所作的四首五言古诗。这组诗和李陵的《与苏武诗三首》收入在南朝萧统《文选》卷二十九里，这七首诗是“苏李诗”的代表作。这些古诗都是送别诗，有的写友人之别、有的写夫妻之别、有的写骨肉兄弟之别，但情感都真挚动人。', '骨肉：指兄弟。首句以叶之缘枝而生比喻兄弟骨肉天然相亲。
因：亲。这句是说结识朋友也是相亲的。
四海皆兄弟：语出《论语》“四海之内皆为兄弟”的话。此二句是说天下的人谁都不是漠不相关的陌路人。
连枝树：即“连理树”，不同根的两树枝或干连生为一名为连理。通常用连理树喻夫妇，这里用来喻兄弟。
参与辰：二星名，参星居西方，辰星（又名商星）居东方，出没两不相见。
邈：远。
胡与秦：犹言外国和中国。当时西域人称中国为“秦”。以上四句是说往日形迹亲近，今后就疏远了。
恩情：此句言情谊比平时更觉不同，平时情谊固然深厚，临别更觉难舍。
鹿鸣：《诗经·小雅》有《鹿鸣》篇，是宴宾客的诗，以“呦呦鹿鸣，食野之苹（蒿类）”起兴，是以鹿得食物呼唤同类比喻燕乐嘉宾。
樽：酒器。
斟酌：用勺舀酒。结尾四句是说这一樽酒本为赠远人用的，现在希望你再留一会儿酌饮此酒。', '', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecc972cee9a0c24eda87f", "shortContent": "今人谈古诗，常常会有不同的角度。研究者注意较多的是作品的真伪及本事出处；而一般读者欣赏的则是诗的本身所能带来的审美情趣。例如这里选录的几首旧题为汉代苏武和李陵的五言诗，就存在这个问题。宋代文豪苏轼因不满《文选》的编选，首先在相传为苏、李的长安送别诗中读出了“江汉”二字，便据以怀疑是后人的伪作。而以博学著称的洪迈，也在《文选》所载李陵《与苏武三首》诗中发现了“盈觞”之“盈”犯了汉惠帝的讳，于是愈坚苏...", "authors": ["曹明纲"], "pressName": "上海辞书出版社"}]', '', 'center', 1523620034, '5ad028349f545400444014d7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637165, '留别妻', NULL, 113, 1, 1, 0, '苏武', NULL, 36782, '583ec5b261ff4b006ce696d4', '汉', 'shi', '诗', 'https://baike.baidu.com/item/%E8%8B%8F%E6%AD%A6%E8%AF%97%E5%9B%9B%E9%A6%96%E5%85%B6%E4%BA%8C/7721401', '', '结发为夫妻，恩爱两不疑。
欢娱在今夕，嬿婉及良时。
征夫怀往路，起视夜何其。
参辰皆已没，去去从此辞。
行役在战场，相见未有期。
握手一长叹，泪为生别滋。
努力爱春华，莫忘欢乐时。
生当复来归，死当长相思。', '《苏武诗四首其二》出自《苏武〈诗四首〉》。作者东汉无名氏。这首五言离别诗是“苏李诗”的代表作之一。描写了夫妻间的离别之情，情感真挚动人。', '结发：指男女初成年时。男子二十岁束发加冠，女子十五岁束发加笄表示成年，通称结发。。
嬿婉：欢好貌。以上二句是说良时的燕婉不能再得，欢娱只有今夜了。
怀往路：惦着走上旅途。
夜何其（音基）：《诗经·庭燎》云：“夜如何其？”这里用《诗经》成语。“其”，语尾助词，犹“哉”。
参辰皆已没：言天将明。
行役：应役远行。
滋：多。
春华：喻少壮时期。', '', NULL, '', 'center', 1523620100, '5ad02882a22b9d0045968b1f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637167, '苏武诗四首 · 其三', NULL, 0, 496, 1, 0, '无名氏', NULL, 10100, '57b959c18ac2470062e2a00f', '汉', 'shi', '诗', '', '', '黄鹄一远别，千里顾徘徊。
胡马失其群，思心常依依。
何况双飞龙，羽翼临当乖。
幸有弦歌曲，可以喻中怀。
请为游子吟，泠泠一何悲。
丝竹厉清声，慷慨有余哀。
长歌正激烈，中心怆以摧。
欲展清商曲，念子不能归。
俯仰内伤心，泪下不可挥。
愿为双黄鹄，送子俱远飞。', '', '依依：恋恋不舍。以上四句言鸟兽分别尚不免怀顾恋之情。
飞龙：龙是传说中的神物（蛇身，有四足，爪象狗的爪，有马的头鬃和尾，有鹿的角、鱼的鳞和须），能飞行。其中有一种有翼的，象飞鸟。这里是以飞龙喻作者送别的朋友和他自己。
喻中怀：晓示心怀。
游子吟：琴曲。《琴操》云：“楚引者，楚游子龙丘高出游三年，思归故乡，望楚而长叹。故曰楚引。”《游子吟》或许就是指此曲。因为是客中送客，《游子吟》正可以表示主客两方的情怀。
泠泠：形容音韵清。
丝竹：“丝”，指用丝弦的乐器，如琴瑟。“竹”，指竹制的乐器，如箫管。这里“丝竹”是偏义复词，上文只提到弦歌，有丝无竹。
厉：强烈。
长歌：乐府歌有《长歌行》，又有《短歌行》，据《乐府解题》，其分别在歌声的长短。长歌是慷慨激烈的，短歌是微吟低徊的。
展：重（平声）。
清商曲：是短歌而不是长歌。曹丕《燕歌行》：“援琴鸣弦发清商，短歌微吟不能长。”
念子不得归：是说我虽想念你而不能随你同归。以上四句是说长歌之后续以短歌，以写心中激烈的伤痛。', '', NULL, '', 'center', 1523620275, '5ad02930ee920a004530eb07', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637170, '蝶恋花 · 离小益作', NULL, 4, 9405, 1, 0, '陆游', NULL, 10019, '57b904a9d342d3005ac748fb', '宋', 'ci', '词', '', '', '桐叶晨飘蛩夜语。旅思秋光，黯黯长安路。忽记横戈盘马处，散关清渭应如故。
江海轻舟今已具。一卷兵书，叹息无人付。早信此生终不遇，当年悔草《长杨赋》。', '这首词是陆游离开南郑入蜀以后所写的。上阕写对南郑戎马生活的怀念，下阕抒发壮志难酬的感慨。开头一句「桐叶晨飘蛩夜语」，词人托物起兴，桐叶飘零，寒蛩夜鸣，都引发的是悲秋之景。「晨飘」与「夜语」对举，表明了同朝至夕，终日触目盈耳的，无往而非凄清萧瑟的景象，这就充分渲染了时代气氛和词人的心境两者形成鲜明的对比。第二句「旅思秋光」，承前启后，「秋光」点明了时间的先后顺序，叶落、虫语，勾起了作者的旅思：「黯黯长安路。」这一句有两重含意，一为写实，一为暗喻。从写实方面来说，当日西北军事重镇长安已为金人占领，词人在南郑王炎宣抚使幕中时，他们的主要进取目标就是收复长安，而一当朝廷下诏调走王炎，这一希望便化成了泡影长安收复，渺茫无期，道路黯黯，这一切使得词人不禁凄然神伤从暗喻方面来说，「长安」是周、秦、汉、唐的古都，这里是借指南宋京城临安。通向京城的道路黯淡无光，隐喻着词人对南宋小朝廷改变抗金决策的失望。「忽记横戈盘马处，散关清渭应如故。」词人北望长安，东望临安，都使他深为不安，而最使他关切的还是抗金前线的情况，那大散关头和清澈的渭水之旁，曾是他「横戈盘马」之处，也曾是他立志恢复中原与实现其理想的所在，而今的情况又怎样呢？「忽记」，乃油然想起，猛上心头，「应」字是悬想，但愿「如故」，更担心能否「如故」，也就是说，随着王炎内调以后形势的变化，金人会不会乘虚南下呢？表明词人对国事忧虑的深重。这两句不是旁斜横逸的转折，而是词人所感情事的变化，词人联想起自己那一段不平凡的战斗经历，说明他旅思的内涵，不是个人得失，不是旅途的风霜之苦，而是爱国忧时的情怀。
下边转到描写个人的前途方面。「江海轻舟今已具」，承上阕「旅思」而来，其意来源于苏轼《临江仙》「小舟从此逝，江海寄余生。」这句话含有想隐归江湖的意思。词人对个人的进退是无所萦怀的，难以忘情的是「一卷兵书，叹息无人付」。「一卷兵书」，既可实指他曾向王炎提出过的「经略中原，必自长安始」的一整套进军策略，也可虚指为抗敌兴国的重大报负，「无人」不是一般所说的没有人，而是春秋时期秦国随会对晋国使臣所说的「子无谓秦无人」中「无人」的意思，也就是慨叹朝廷抗金志士零落无存，国家前途令人担忧。歇拍两句从慨叹转为激愤：「早信此生终不遇，当年悔草《长杨赋》。」《长杨赋》是西汉辞赋家扬雄的名作，他是为了讽谏汉成帝游幸长杨宫，纵胡客大校猎才献上这篇赋的。词里活用了这个典故，表明自己如果早知不被知遇，就不会陈述什么恢复方略了。这「悔」的后面是「恨」，透露出词人的愤愤不平之气，不过只用「悔」字表现得婉转一些罢了。
全词共四个层次，第一层抚今，第二层思昔，第三层再回到现实，第四层又回顾以住，今昔交织，回环往复，写得神完气足。', '', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74dd34a8757d5a0d9eb2", "shortContent": "这首词是陆游离开南郑入蜀以后所作。上片写对南郑戎马生活的怀念，下片抒发壮志难酬的感慨。\n开头一句“桐叶晨飘蛩夜语”，词人托物起兴，桐叶飘零，寒蛩夜鸣，都是引发悲秋之景。“晨飘”与“夜语”对举，表明了由朝至夕，终日触目盈耳的，无往而非凄清萧瑟的景象，这就充分渲染了时代气氛和词人的心境。第二句“旅思秋光”，承前启后，“秋光”点明了时序，叶落、虫语，勾起了旅思：“黯黯长安路。”这一句有两重含意，一为写实...", "authors": ["李廷先", "刘立人"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5e25e272d4b2254e009", "shortContent": "这首词是陆游离开南郑入蜀以后所作。上片写对南郑戎马生活的怀念，下片抒发壮志难酬的感慨。\n开头一句“桐叶晨飘蛩夜语”，词人托物起兴，桐叶飘零，寒蛩夜鸣，都是引发悲秋之景。“晨飘”与“夜语”对举，表明了由朝至夕，终日触目盈耳的，无往而非凄清萧瑟的景象，这就充分渲染了时代气氛和词人的心境。第二句“旅思秋光”，承前启后，“秋光”点明了时序，叶落、虫语，勾起了旅思：“黯黯长安路。”这一句有两重含意，一为写实...", "authors": ["李廷先", "刘立人"], "pressName": "上海辞书出版社"}]', '', 'indent', 1523723964, '5ad1be2f7f6fd30062048786', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637246, '庆春宫 · 越调', NULL, 4, 239, 2, 0, '周邦彦', NULL, 10111, '57ba6fafa34131005b0e18bd', '宋', 'ci', '词', '', '', '云接平冈，山围寒野，路回渐转孤城。衰柳啼鸦，惊风驱雁，动人一片秋声。倦途休驾，淡烟里，微茫见星。尘埃憔悴，生怕黄昏，离思牵萦。
华堂旧日逢迎。花艳参差，香雾飘零。弦管当头，偏怜娇凤，夜深簧暖笙清。眼波传意，恨密约，匆匆未成。许多烦恼，只为当时，一饷留情。', '此词描写游子行旅别离之情，上阕就旅途即景生情，着意措摹；下阕就离思极力追忆，驰骋想象。
「云接平岗，山围寒野」，路回渐转孤城写游子在愁云笼罩的阴寒天，跨过山冈，越过原野，在崎岖的小路上跋涉，经过漫长的旅途，总算在偏僻的荒原上看到一座孤城。「渐」字有韵味，表示原野广阔、路途遥远曲折，又能透露行人旅客那焦灼期待的心情。「衰柳啼鸦，惊风驱雁」，两句通过乌鸦和鸿雁的啼声，极力描摹秋季原野上的肃杀气氛。「惊风驱雁」四字，最见精彩。用「惊」字形容秋风，除了说它猛烈之外，还能使人觉得节序变换之迅速，从而产生一种仓皇无措之感；说鸿雁是被秋风驱赶而南飞，还有比喻人生道路上的为世事所驱遣而不由自主的意思。「动人一片秋声」，「动人」二字并不突兀，因为它只不过是把上文写景之中所含的抒情成分点明罢了。「秋声」，当然是指鸦啼、雁唳和风吹的声音，但与「一片」相连接，则是为了与开头所描写的广漠原野相照应。由于环境寂静，声音便传得远；又由于有一些单调的声音，而周围的环境却会显得更加寂静。
以上几句，景中寓情，传达出深沉蕴藉的悲秋之意。
以下转入叙事，写作者精疲力竭时，在沉沉暮霭中抬头远望，透过薄薄的云雾，看到空中的点点星光。天地间行走，江湖上飘零，作者风尘仆仆，憔瘁不堪，一到黄昏，离愁别恨愈加浓重。这几句，写得波澜起伏，情深意切。
下阕写回忆中的往事，借助于对夕日一段恋情的描写，缠绵宛转地表达作者的离情别绪。首句点明作者曾在歌舞欢宴之地有过一段难忘的艳遇。「花艳参差，香雾飘零」八字，极写美女之姿，令人眼花心醉。「花艳」，喻指女郎的美貌。「香雾」是美人香气，「雾」言其浓若可见，又飘荡弥漫无所不至。
以下几句是说在众多乐伎中有词人独爱的一位吹笙美人。「娇凤」言其小，又言其美，同时又兼指她演奏出来的那悠扬动人的、如同凤鸣一般的笙乐。「夜深簧暖笙清」一句，写美人渲奏的乐声之清越。「眼波传意」，写美人与作者心有灵犀，眉目传情。恨密约、匆匆未成」，写一段美好恋情的迅速破灭。「许多烦恼，只为当时，一饷留情。」这一结尾，表达了作者离愁别绪之深重。
词中以追忆的方式，表现萌发于作者与歌女之间的爱情，读来柔肠百转，令人感慨。作者写歌女的姿容与乐声，形声兼备，丰满鲜活，具有极强的艺术表现力。', '', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74c603048e64fbd89393", "shortContent": "这是一首旅途怀人的词。上片着重描写旅途所见秋景，下片着重回忆与意中人的遇合，孤寂萧索与繁华热闹两极相互对应，也颇有它的特点。\n“云接平岗，山围寒野”，是一对偶句，从云和山着眼，极力描摹开阔广漠景象，“接”和“围”两个动词，也显得有气势。“路回渐转孤城”，道路经过几番回转以后，才逐渐地看到了远处的城郭。“渐”字有韵味，即表示原野广阔、路途遥远曲折，又能透露行人旅客那焦灼期待的心情。“衰柳啼鸦，惊风驱...", "authors": ["王双启"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5cb0f8fda55650604bb", "shortContent": "这是一首旅途怀人的词。上片着重描写旅途所见秋景，下片着重回忆与意中人的遇合，孤寂萧索与繁华热闹两极相互对应，也颇有它的特点。\n“云接平岗，山围寒野”，是一对偶句，从云和山着眼，极力描摹开阔广漠景象，“接”和“围”两个动词，也显得有气势。“路回渐转孤城”，道路经过几番回转以后，才逐渐地看到了远处的城郭。“渐”字有韵味，即表示原野广阔、路途遥远曲折，又能透露行人旅客那焦灼期待的心情。“衰柳啼鸦，惊风驱...", "authors": ["王双启"], "pressName": "上海辞书出版社"}, {"bookId": "645d152a7af6de1647101bdf", "bookTitle": "周邦彦词鉴赏辞典", "articleId": "6469c248e49f46528aba6aef", "shortContent": "这是一首旅途怀人的词。上片着重描写旅途所见秋景，下片着重回忆与意中人的遇合，孤寂萧索与繁华热闹两极相互对应，也颇有它的特点。\n“云接平冈，山围寒野”，是一对偶句，从云和山着眼，极力描摹开阔广漠景象，“接”和“围”两个动词，也显得有气势。“路回渐转孤城”，道路经过几番回转以后，才逐渐地看到了远处的城郭。“渐”字有韵味，即表示原野广阔、路途遥远曲折，又能透露行人旅客那焦灼期待的心情。“衰柳啼鸦，惊风驱...", "authors": ["王双启"], "pressName": "上海辞书出版社"}]', '', 'indent', 1524136723, '5ad80a87d50eee1db13a96ec', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637352, '笠翁对韵 · 上卷 · 二冬', NULL, 55, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '晨对午，夏对冬。下晌对高舂。青春对白昼，古柏对苍松。垂钓客，荷锄翁。仙鹤对神龙。凤冠珠闪烁，螭带玉玲珑。三元及第才千顷，一品当朝禄万钟。花萼楼间，仙李盘根调国脉；沉香亭畔，娇杨擅宠起边风。
清对淡，薄对浓。暮鼓对晨钟。山茶对石菊，烟锁对云封。金菡萏，玉芙蓉。绿绮对青锋。早汤先宿酒，晚食继朝饔。唐库金钱能化蝶，延津宝剑会成龙。巫峡浪传，云雨荒唐神女庙；岱宗遥望，儿孙罗列丈人峰。
繁对简，叠对重。意懒对心慵。仙翁对释伴，道范对儒宗。花灼烁，草蒙茸。浪蝶对狂蜂。数竿君子竹，五树大夫松。高皇灭项凭三杰，虞帝承尧殛四凶。内苑佳人，满地风光愁不尽；边关过客，连天烟草憾无穷。', '', '', '', NULL, '', 'indent', 1524654865, '5adff28fa22b9d00401e374a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637353, '笠翁对韵 · 上卷 · 三江', NULL, 36, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '奇对偶，只对双。大海对长江。金盘对玉盏，宝烛对银釭。朱漆槛，碧纱窗。舞调对歌腔。兴汉推马武，谏夏著龙逄。四收列国群王服，三筑高城众敌降。跨凤登台，潇洒仙姬秦月玉；斩蛇当道，英雄天子汉刘邦。
颜对貌，像对庞。步辇对徒杠。停针对搁笔，意懒对心降。灯闪闪，月幢幢。揽辔对飞艭。柳堤驰骏马，花院吠村尨。酒晕微酡琼杏颊，香尘浅印玉莲（双）。诗写丹枫，韩女幽怀流御水；泪弹斑竹，舜妃遗恨积湘江。', '', '', '', NULL, '', 'indent', 1524654886, '5adff2a3a22b9d0045326f84', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637354, '笠翁对韵 · 上卷 · 四支', NULL, 28, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '泉对石，干对枝。吹竹对弹丝。山亭对水榭，鹦鹉对鸬鹚。五色笔，十香词。泼墨对传卮。神奇韩干画，雄浑李陵诗。几处花街新夺锦，有人香径淡凝脂。万里烽烟，战士边头争保塞；一犁膏雨，农夫村外尽乘时。
菹对醢，赋对诗。点漆对描脂。瑶簪对珠履，剑客对琴师。沽酒价，买山赀。国色对仙姿。晚霞明似锦，春雨细如丝。柳畔长堤千万树，花横野寺两三枝。紫盖黄旗，天象预占江左地；青袍白马，童谣终应寿阳儿。
箴对赞，缶对卮。萤焰对蚕丝。轻裾对长袖，瑞草对灵芝。流涕策，断肠诗。喉舌对腰肢。云中熊虎将，天上凤麟儿。禹庙千年垂橘柚，尧阶三尺覆茅茨。湘竹含烟，腰下轻纱笼玳瑁；海棠经雨，脸边清泪湿胭脂。
争对让，望对思。野葛对山栀。仙风对道骨，天造对人为。专诸剑，博浪椎。经纬对干支。位尊民物主，德重帝王师。望切不妨人去远，心忙无奈马行迟。金屋闭来，赋乞茂陵题柱笔；玉楼成后，记须昌谷负囊词。', '', '流涕策：西汉贾谊《陈政事疏》：“臣窃惟事势，可为痛哭者一，可为流涕者二，可为长太息者六。”断肠诗：宋代女诗人朱淑贞，相传其对婚姻不满，故诗词多幽愤哀伤情调，后人辑有《断肠诗集》、《断肠词集》传世。云中：汉代北方有云中郡。垂橘柚：唐杜甫《禹庙》诗：“荒庭垂橘柚，古屋画龙蛇。”茅茨：以土为阶，以茅为屋。《韩非子.五蠹》：“尧之王天下也，茅茨不剪，采椽不斫。”湘竹：湘妃竹，又名斑竹。', '', NULL, '', 'indent', 1524654926, '5adff2cbee920a228ec6b5bf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637355, '笠翁对韵 · 上卷 · 五微', NULL, 15, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '贤对圣，是对非。觉奥对参微。鱼书对雁字，草舍对柴扉。鸡晓唱，雉朝飞。红瘦对绿肥。举杯邀月饮，骑马踏花归。黄盖能成赤壁捷，陈平善解白登危。太白书堂，瀑泉垂地三千丈；孔明祠庙，老柏参天四十围。
戈对甲，幄对帏。荡荡对巍巍。严滩对邵圃，靖菊对夷薇。占鸿渐，采凤飞。虎榜对龙旗。心中罗锦绣，口内吐珠玑。宽宏豁达高皇量，叱咤喑哑霸主威。灭项兴刘，狡兔尽时走狗死；连吴拒魏，貔貅屯处卧龙归。
衰对盛，密对稀。祭服对朝衣。鸡窗对雁塔，秋榜对春闱。乌衣巷，燕子矶。久别对初归。天姿真窈窕，圣德实光辉。蟠桃绛阙来金母，岭荔红尘进玉妃。灞上军营，亚父愤心撞玉斗；长安酒市，谪仙狂兴典银龟。', '', '严滩：浙江富春江的严陵濑，汉代隐士严子陵钓鱼处。
邵圃：秦代东陵侯邵平弃官種瓜，名东陵瓜。
靖菊：陶潜采菊东篱下，谥「靖节」。
夷薇：商代末伯夷叔齐，耻食周粟，隐于首阳山，采薇而食。
高皇：指汉高祖刘邦。
霸王：指西楚霸王项羽。
走狗死：《史记·淮阴侯列传》载，汉高祖擒韩信，信曰：「狡兔死，走狗烹。」
卧龙：三国时诸葛亮隐居南阳时，人称卧龙先生。', '', NULL, '', 'indent', 1524654963, '5adff2f1ac502e2713c99d4f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637356, '笠翁对韵 · 上卷 · 六鱼', NULL, 15, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '羹对饭，柳对榆。短袖对长裾。鸡冠对凤尾，芍药对芙蕖。周有若，汉相如。王屋对匡庐。月明山寺远，风细水亭虚。壮士腰间三尺剑，男儿腹内五车书。疏影暗香，和靖孤山梅蕊放；轻阴清昼，渊明旧宅柳条舒。
吾对汝，尔对余。选授对升除。书箱对药柜，耒耜对耰锄。参虽鲁，回不愚。阀阅对阎闾。诸侯千乘国，命妇七香车。穿云采药闻仙犬，踏雪寻梅策蹇驴。玉兔金乌，二气精灵为日月；洛龟河马，五行生克在图书。
欹对正，密对疏。囊橐对苞苴。罗浮对壶峤，水曲对山纡。骖鹤驾，侍鸾舆。桀溺对长沮。搏虎卞庄子，当熊冯婕妤。南阳高士吟梁妇，西蜀才人赋子虚。三径风光，白石黄花供杖履；五湖烟景，青山绿水在樵渔。', '', '芙蕖：荷花的别名。周有若：东周时人，孔子弟子，有若貌似孔子，曾一度奉以为师。见《史记.仲尼弟子传》。汉相如：西汉文学家司马相如。五车书：《庄子.天下》：“惠施多方，其书五车。”后以学富五车称人之博学。和靖：宋林逋（字和靖）种梅于杭州西湖之孤山，其咏梅名句有：“疏影横斜水清浅，暗香浮动月黄昏。”', '', NULL, '', 'indent', 1524654998, '5adff3149f545433342bada4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637357, '笠翁对韵 · 上卷 · 七虞', NULL, 10, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '红对白，有对无。布谷对提壶。毛锥对羽扇，天阙对皇都。谢蝴蝶，郑鹧鸪。蹈海对归湖。花肥春雨润，竹瘦晚风疏。麦饭豆糜终创汉，莼羹胪脍竟归吴。琴调轻弹，杨柳月中潜去听；酒旗斜挂，杏花村里共来沽。
罗对绮，茗对蔬。柏秀对松枯。中元对上巳，返璧对还珠。云梦泽，洞庭湖。玉烛对冰壶。苍头犀角带，绿鬓象牙梳。松阴白鹤声相应，镜里青鸾影不孤。竹户半开，对牖未知人在否？柴关深闭，停车还有客来无？
宾对主，婢对奴。宝鸭对金凫。升堂对入室，鼓瑟对投壶。觇合璧，颂联珠。提瓮对当垆。仰高红日近，望远白云孤。歆向秘书窥二酉，机云芳誉动三吴。祖饯三杯，老去常斟花下酒；荒田五亩，归来独荷月中锄。
君对父，魏对吴。北岳对西湖。菜蔬对茶荈，苣藤对菖蒲。梅花数，竹叶符。廷议对山呼。两都班固赋，八阵孔明图。田庆紫荆堂下茂，王裒青柏墓前枯。出塞中郎，羝有乳时归汉室；质秦太子，马生角日返燕都。', '', '投壶：古代宴会上一种饮酒游戏。合璧联珠：指日、月、五星合聚。《汉书.律历志上》：“日月如合璧，五星如连珠。”后用以表示会集精华之意。当垆：指卖酒。垆，酒店放酒坛的土台。歆向：西汉刘向、刘歆，父子读书于二酉山。机云：晋陆机、陆云，兄弟名重三吴。
梅花数：古占法。相传为宋代邵雍所作。附会人事，以断吉凶。竹叶符：即竹使符。汉代分与郡国守相的信符，右留京师，左留郡国。以竹箭五枚刻字制成。山呼：古代臣民对皇帝举行颂祝仪式，叩头高呼万岁三次，叫做山呼。两都：西汉班固作《两都赋》。八阵：三国诸葛亮作八阵图。八阵图乃行军阵法。紫荆：汉京兆田真、田庆、田广兄弟欲分家，堂下紫荆树忽然枯萎，田家受感动，决定不分家，荆树亦即复生。青柏：传说晋王裒父死攀墓柏号哭，柏树忽枯。羝乳：西汉苏武出使匈奴被扣，使牧羝羊（公羊），谓羝羊有乳方可放归。马角：《燕丹子》载，战国时燕太子丹为质于秦，秦王曰：马生角始可放归。太子悲啼，马果生角。', '', NULL, '', 'indent', 1524655035, '5adff3397f6fd30047ec57bb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637358, '笠翁对韵 · 上卷 · 八齐', NULL, 10, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '鸾对凤，犬对鸡。塞北对关西。长生对益智，老幼对旄倪。颁竹策，剪桐圭。剥枣对蒸梨。绵腰如弱柳，嫩手似柔荑。狡兔能穿三穴隐，鹪鹩权借一枝栖。甪里先生，策杖垂绅扶少主；於陵仲子，辟（纑）织履赖贤妻。
鸣对吠，泛对栖。燕语对莺啼。珊瑚对玛瑙，琥珀对玻璃。绛县老，伯州犁。测蠡对燃犀。榆槐堪作荫，桃李自成蹊。投巫救女西门豹，赁浣逢妻百里奚。阙里门墙，陋巷规模原不陋；隋堤基址，迷楼踪迹亦全迷。
越对赵，楚对齐。柳岸对桃蹊。纱窗对绣户，画阁对香闺。修月斧，上天梯。螮蝀对虹霓。行乐游春圃，工谀病夏畦。李广不封空射虎，魏明得立为存麑。按辔徐行，细柳功成劳主敬；闻声稍卧，临泾名震止儿啼。', '', '', '', NULL, '', 'indent', 1524655073, '5adff35f7f6fd30047ec58ce', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637359, '笠翁对韵 · 上卷 · 九佳', NULL, 12, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '门对户，陌对街。枝叶对根荄。斗鸡对挥麈，凤髻对鸾钗。登楚岫，渡秦淮。子犯对夫差。石鼎龙头缩，银筝雁翅排。百年诗礼延余庆，万里风云入壮怀。莫辨名伦，死矣野哉悲季路；不由径窦，生乎愚也有高柴。
冠对履，袜对鞋。海角对天涯。鸡人对虎旅，六市对三街。陈俎豆，戏堆埋。皎皎对皑皑。贤相聚东阁，良朋集小斋。梦里山川书越绝，枕边风月记齐谐。三径萧疏，彭泽高风怡五柳；六朝华贵，琅琊佳气种三槐。
勤对俭，巧对乖。水榭对山斋。冰桃对雪藕，漏箭对更牌。寒翠袖，贵金钗。慷慨对诙谐。竹径风声籁，花溪月影筛。携囊佳韵随时贮，荷锄沉酣到处埋。江海孤踪，云浪风涛惊旅梦；乡关万里，烟峦云树切归怀。
杞对梓，桧对楷。水泊对山崖。舞裙对歌袖，玉陛对瑶阶。风入袂，月盈怀。虎兕对狼豺。马融堂上帐，羊侃水中斋。北面黉宫宜拾芥，东巡岱畤定燔柴。锦缆春江，横笛洞箫通碧落；华灯夜月，遗簪堕翠遍香街。', '', '斗鸡：古时鸡与鸡相搏斗的一种游戏。唐王勃有《斗鸡檄》。挥麈：挥动拂尘。晋代人常挥麈清谈。子犯：春秋时晋臣。《左传.僖二十二年》载，晋重耳乞食于野人，野人与之块，公子怒，欲鞭之，子犯曰：“天赐也。”夫差：春秋时吴国国君。季路：孔子门人。《论语.子路》：子曰：“野哉由也。”高柴：孔子门人。遇卫难不径不窦（既不走小路，又不走孔道，不知变通）。《论语.先进》：子曰：“柴也愚。”
携囊：见前李贺系囊贮诗之注释。　荷锄：晋刘伶，好酒。尝荷锄自随曰：“醉死便可埋我。”
马融：西汉马融堂前教授生徒，后设绛纱帐，置女乐。羊侃：南朝梁羊侃，好奢侈，结舟为斋，亭馆皆备，日事游宴。黉宫：古代学校名。拾芥：捡取地上的草芥。比喻取之极易。《汉书.夏侯胜传》：“胜每讲授，常谓诸生曰：‘士病不明经术。经术苟明，其取青紫，如俯拾地芥耳。’”岱畤：岱，泰山。畤，古代祭天地五帝之处。燔柴：烧柴，祭天之礼。《礼.祭法》：“燔柴于泰坛，祭天地。”
', '', NULL, '', 'indent', 1524655122, '5adff3917f6fd30047ec59ff', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637360, '笠翁对韵 · 上卷 · 十灰', NULL, 9, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '春对夏，喜对哀。大手对长才。风清对月朗，地阔对天开。游阆苑，醉蓬莱。七政对三台。青龙壶老杖，白燕玉人钗。香风十里望仙阁，明月一天思子台。玉橘冰桃，王母几因求道降；莲舟藜杖，真人原为读书来。
朝对暮，去对来。庶矣对康哉。马肝对鸡肋，杏眼对桃腮。佳兴适，好怀开。朔雪对春雷。云移鳷鹊观，日晒凤凰台。河边淑气迎芳草，林下轻风待落梅。柳媚花明，燕语莺声浑是笑；松号柏舞，猿啼鹤唳总成哀。
忠对信，博对赅。忖度对疑猜。香消对烛暗，鹊喜对蛩哀。金花报，玉镜台。倒斝对衔杯。岩巅横老树，石磴覆苍苔。雪满山中高士卧，月明林下美人来。绿柳沿堤，皆因苏子来时种；碧桃满观，尽是刘郎去后栽。', '', '马肝：马肝味劣、喻烦粹之意。鸡肋：《三国志.魏书.魏武帝纪》载，曹操攻汉中欲还，出口令曰：鸡肋。杨修曰：“鸡肋弃之可惜，食之无味，示欲还也！”鳷鹊观：古代道观名。　凤凰台：在江苏南京市。落梅：汉应劭《风俗通》：“五月有落梅风，江淮以为信风。
金花报：古代状元寄家信报喜，称为金花报。玉镜台：晋温峤娶其姑之女，以玉镜台为聘礼。高士卧：《后汉书.袁安传》载，袁安遇雪天在家高卧不出，人以为贤，举为孝廉。美人来：隋赵师雄游罗浮山，日暮见一美人邀共饮，雄不觉醉卧。醒来在梅花树下，翠羽嘈唧其上，月落参横，惆怅不已。苏子：苏轼守杭州，令西湖沿堤种桃柳，人号苏公堤，简称苏堤。刘郎：唐刘禹锡《自朗州至京戏赠看花诸君子》诗：“玄都观里桃千树，尽是刘郎去后栽。”', '', NULL, '', 'indent', 1524655159, '5adff3b51b69e619db55e251', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637361, '笠翁对韵 · 上卷 · 十一真', NULL, 5, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '莲对菊，凤对麟。浊富对清贫。渔庄对佛舍，松盖对花茵。萝月叟，葛天民。国宝对家珍。草迎金埒马，花醉玉楼人。巢燕三春尝唤友，塞鸿八月始来宾。古往今来，谁见泰山曾作砺；天长地久，人传沧海几扬尘。
兄对弟，吏对民。父子对君臣。勾丁对甫甲，赴卯对同寅。折桂客，簪花人。四皓对三仁。王乔云外舄，郭泰雨中巾。人交好友来三益，士有贤妻备五伦。文教南宣，武帝平蛮开百越；义旗西指，韩侯扶汉卷三秦。
申对午，侃对訚。阿魏对茵陈。楚兰对湘芷，碧柳对青筠。花馥馥，草蓁蓁。粉颈对朱唇。曹公奸似鬼，尧帝智如神。南阮才郎羞北富，东邻丑女效西颦。色艳北堂，草号忘忧忧甚事；香浓南国，花名含笑笑何人。', '', '萝月：萝藤间的月色。南齐孔稚珪《北山移文》：“秋桂遗风，春萝罢月。”唐李白《赠王判官》诗：“何处我思君，天台绿萝月。”葛天民：晋陶潜《五柳先生传》：“无怀氏之民欤？葛天氏之民欤？”葛天氏，传说为远古帝号。古人认为是理想中的自然、淳朴之世。金埒：清王武有马癖，编钱为金埒。尝乘马不渡水，曰：“是必惜锦障泥。”去之，马乃渡水。作砺：《史记.高祖功臣侯者年表.序》：“封爵之誓曰：‘使河如带，泰山若砺。国以永宁，爰及苗裔。”砺，磨刀石。扬尘：犹言沧海桑田。
奸似鬼：三国时曹操奸伪，人称奸鬼。南阮：晋代洛阳阮氏，处北者富，处南者贫而多才。　效西颦：古越国美女西施因患心病而捧心皱眉，东村丑女东施以为美，亦捧心效其颦，而丑态益增。忘忧：萱草也名忘忧草。含笑：花名。', '', NULL, '', 'indent', 1524655204, '5adff3e317d0090062865581', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637362, '笠翁对韵 · 上卷 · 十二文', NULL, 4, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '忧对喜，戚对欣。二典对三坟。佛经对仙语，夏耨对春耘。烹早韭，剪春芹。暮雨对朝云。竹间斜白接，花下醉红裙。掌握灵符五岳箓，腰悬宝剑七星纹。金锁未开，上相趋听宫漏水；珠帘半卷，群僚仰对御炉熏。
词对赋，懒对勤。类聚对群分。鸾箫对凤笛，带草对香芸。燕许笔，韩柳文。旧话对新闻。赫赫周南仲，翩翩晋右军。六国说成苏子贵，两京收复郭公勋。汉阙陈书，侃侃忠言推贾谊；唐廷对策，岩岩直谏有刘羵。
言对笑，绩对勋。鹿豕对羊羵。星冠对月扇，把袂对书裙。汤事葛，说兴殷。萝月对松云。西池青鸟使，北塞黑鸦军。文武成康为一代，魏吴蜀汉定三分。桂苑秋宵，明月三杯邀曲客；松亭夏日，薰风一曲奏桐君。', '', '二典、三坟：相传为远古之书。白接：古代毡巾名。晋代山涛醉后巾帽欹斜。古诗云：“山公斜著白接罹。”五岳箓：道教符箓。', '', NULL, '', 'indent', 1524655233, '5adff4009f545433342bb447', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (638405, '画堂春', NULL, 1, 49, 0, 2, '毛幵', NULL, 18316, '5858eca0b123db00658daf81', '宋', 'ci', '词', '', '', '华灯收尽雪初残。踏青还尔游盘。落梅强半已飞翻。刬地春寒。
多病故人日远，几时双燕来还。可怜楼上一凭栏。不见长安。 ', '', '', '', NULL, '', 'indent', 1532709268, '5b5ad91dee920a003cd466c0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637363, '笠翁对韵 · 上卷 · 十三元', NULL, 4, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '卑对长，季对昆。永巷对长门。山亭对水阁，旅舍对军屯。扬子渡，谢公墩。德重对年尊。承乾对出震，叠坎对重坤。志士报君思犬马，仁王养老察鸡豚。远水平沙，有客泛舟桃叶渡；斜风细雨，何人携榼杏花村。
君对相，祖对孙。夕照对朝暾。兰台对桂殿，海岛对山村。碑堕泪，赋招魂。报怨对怀恩。陵埋金吐气，田种玉生根。相府珠帘垂白昼，边城画角对黄昏。枫叶半山，秋去烟霞堪倚杖；梨花满地，夜来风雨不开门。', '', '扬子渡：古津渡名。在江苏江都县南。谢公墩：山名，在江苏江宁县城北。晋谢安尝居半山，后来宋王安石也尝居此。承乾、出震、叠坎、重坤：指八卦中乾、震、坎、坤四卦符号的形象特点。桃叶渡：桃叶复桃叶，渡江不用楫。”杏花村：唐杜牧《清明》诗：“借问酒家何处有？牧童遥指杏花村。”后因以杏花村指卖酒之处。
碑堕泪：晋羊祜死后，襄阳人在岘山建碑纪念，见者莫不堕泪，故称堕泪碑。赋招魂：《楚辞》中有宋玉所作《招魂》篇，以招屈原之魂。金吐气：秦王埋金于金陵（今南京）钟山，以镇王气。故称金陵。玉生根：《搜神记》载，晋杨伯雍汲水于岭上供过客饮用，三年后有一人饮后赠石一斗，谓种之可生玉。不开门：唐刘方平《春怨》诗：“寂寞空庭春欲晓，梨花满地不开门。”', '', NULL, '', 'indent', 1524655268, '5adff4239f545433342bb568', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637364, '笠翁对韵 · 上卷 · 十四寒', NULL, 5, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '家对国，治对安。地主对天官。坎男对离女，周诰对殷盘。三三暖，九九寒。杜撰对包弹。古壁蛩声匝，闲亭鹤影单。燕出帘边春寂寂，莺闻枕上漏珊珊。池柳烟飘，日夕郎归青琐闼；砌花雨过，月明人倚玉栏杆。
肥对瘦，窄对宽。黄犬对青鸾。指环对腰带，洗钵对投竿。诛佞剑，进贤冠。画栋对雕栏。双垂白玉箸，九转紫金丹。陕右棠高怀召伯，河南花满忆潘安。陌上芳春，弱柳当风披彩线；池中清晓，碧荷承露捧珠盘。
行对卧，听对看。鹿洞对鱼滩。蛟腾对豹变，虎踞对龙蟠。风凛凛，雪漫漫。手辣对心酸。莺莺对燕燕，小小对端端。蓝水远从千涧落，玉山高并两峰寒。至圣不凡，嬉戏六龄陈俎豆；老莱大孝，承欢七秩舞斑襕。', '', '周诰、殷盘：《尚书·周书》有大诰、康诰、酒诰、召诰诸篇。《尚书·商书》中有盘庚上、中、下篇。杜撰：凭空捏造之事。唐代杜举好为不经之谈，人谓之为杜撰。包弹：宋代包拯为御史中丞，不避权贵，人谓之包弹。夕郎：黄门侍郎的别称。汉应劭《汉宫仪》：“黄门郎日暮入，对青琐门拜，名曰夕郎。”
诛佞剑：汉朱云求赐上方剑斩一佞臣，皇帝问为谁？答为张禹。帝怒令斩之。召公有德政，曾在棠树下理事，后人怀念召伯，不忍伐其树。潘安：晋潘安为河阳令，栽花满县，人称花县。', '', NULL, '', 'indent', 1524655308, '5adff44b1b69e619db55e5e9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637365, '笠翁对韵 · 上卷 · 十五删', NULL, 6, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '林对坞，岭对峦。昼永对春闲。谋深对望重，任大对投艰。裾袅袅，佩珊珊。守塞对当关。密云千里合，新月一钩弯。叔宝君臣皆纵逸，重华父母是嚚顽。名动帝畿，西蜀三苏来日下；壮游京洛，东吴二陆起云间。
骄对傲，吝对悭。讨逆对平蛮。忠肝对义胆，雾鬓对云鬟。埋笔冢，烂柯山。月貌对天颜。龙潜终得跃，鸟倦亦知还。陇树飞来鹦鹉绿，湘筠密处鹧鸪斑。秋露横江，苏子月明游赤壁；冻云迷岭，韩公雪拥过蓝关。', '', '叔宝：南朝陈后主，名叔宝。重华：虞舜名。《书·舜典》：“曰若稽古帝舜，曰重华，协于帝。”嚚顽：蠢而顽固。《书·尧典》：“父顽母嚚”。三苏：宋苏洵、苏轼、苏辙三父子，皆有文才，人号三苏。日下：京城。二陆：晋陆机、陆云兄弟，松江人并有才名，人称二陆。云间：江苏松江县之古称。
湘子，幼有仙迹，出外数年不返，韩公寿，湘忽至，书一联于壁上曰：“云横秦岭家何在，雪拥蓝关马不前。”未几，韩公谏迎佛骨上表，遭贬至潮州，果经蓝关。', '', NULL, '', 'indent', 1524655342, '5adff46c7f6fd30047ec5f0c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637372, ' 笠翁对韵 · 下卷 · 一先', NULL, 7, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '寒对暑，日对年。蹴踘对秋千。丹山对碧水，淡雨对轻烟。歌宛转，貌婵娟。雪赋对云笺。荒芦栖宿雁，疏柳噪秋蝉。洗耳尚逢高士笑，折腰肯受小儿怜。郭泰泛舟，折角半垂梅子雨；山涛骑马，接篱倒着杏花天。
轻对重，脆对坚。碧玉对青钱。郊寒对岛瘦，酒圣对诗仙。依玉树，步金莲。凿井对耕田。杜甫清宵立，边韶白昼眠。豪饮客吞杯底月，酣游人醉水中天。斗草青郊，几行宝马嘶金勒；看花紫陌，千里香车拥翠钿。
吟对咏，授对传。乐矣对凄然。风鹏对雪雁，董杏对周莲。春九十，岁三千。钟鼓对管弦。入山逢宰相，无事即神仙。霞染武陵桃淡淡，烟荒隋堤柳绵绵。七碗月团，啜罢清风生腋下；三杯云液，饮余红雨晕腮边。
中对外，后对先。树下对花前。玉树对金屋，叠嶂对平川。孙子策，祖生鞭。盛席对华筵。醉解知茶力，愁消识酒权。彩剪芰荷开冻沼，锦妆凫雁泛温泉。帝女衔石，海中遗魄为精卫；蜀王叫月，枝上游魂化杜鹃。', '', '洗耳：尧时有颍水箕山高人曰巢父、许由，尧欲以天下让许由，巢父以为污耳，就池水洗之。池主怒曰：“何污我水？”　折腰：晋陶潜为彭泽令，有督邮至，潜曰：“吾不能为五斗米折腰，拳拳事乡里小人耶！”遂辞官，作《归去来辞》。折角：折角巾。见上卷[十一真]“郭泰雨中巾”注释。　接篱：毡巾。见上卷[十二文]“白接”注释。
郊寒岛瘦：宋苏轼《祭柳子玉文》：“元轻白俗，郊寒岛瘦”。因孟郊、贾岛之诗，清峭瘦硬，好作苦语，故此称之。　玉树：《世说新语．容止》：魏明帝使后弟毛曾与夏侯玄共坐。时入谓之“兼葭倚玉树”。　金莲：《南史．齐东昏侯妃》载，南朝齐东昏侯以金为莲花贴地，令潘妃行其上，曰：“步步生莲花也。”后以金莲指女子纤足。 清宵立：唐杜甫诗：“思家步月清宵立。”　白昼眠：东汉边韶常昼眠，弟子嘲之曰：“边孝先，腹便便，懒读书，昼贪眠。”', '', NULL, '', 'indent', 1524738406, '5ae138e57f6fd30047f35b9d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637373, '笠翁对韵 · 下卷 · 二箫', NULL, 5, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '琴对管，釜对瓢。水怪对花妖。秋声对春色，白缣对红绡。臣五代，事三朝。斗柄对弓腰。醉客歌金缕，佳人品玉箫。风定落花闲不扫，霜余残叶湿难烧。千载兴周，尚父一竿投渭水；百年霸越，钱王万弩射江潮。
荣对悴，夕对朝。露地对云霄。商彝对周鼎，殷濩对虞韶。樊素口，小蛮腰。六诏对三苗。朝天车奕奕，出塞马萧萧。公子幽兰重泛舸，王孙芳草正联镳。潘岳高怀，曾向秋天吟蟋蟀；王维清兴，尝于雪夜画芭蕉。
耕对读，牧对樵。琥珀对琼瑶。兔毫对鸿爪，桂棹对兰桡。鱼潜藻，鹿藏蕉。水远对山遥。湘灵能鼓瑟，嬴女解吹箫。雪点寒梅横小院，风吹弱柳覆平桥。月牖通宵，绛蜡罢时光不减；风帘当昼，雕盘停后篆难消。', '', '臣五代：冯道历事后唐、后晋、后辽、后汉、后周五朝。　事三朝：沈约事南朝宋、齐、梁三朝。尚父：周初姜尚被周武王尊为尚父。　射江潮：吴越王钱镠，作御潮铁柱于江中，未成而潮至。王命万弩射之，潮果退。筑土一升者偿钱一升，故名之曰钱塘。
樊素、小蛮：唐白居易之二妾名。白有诗云：“樱桃樊素口，杨柳小蛮腰。”　六诏：唐时，我国西南部的少数民族称王为诏，当时有越析、蒙舍等六诏。其地在今云南及四川西南部。　吟蟋蟀：晋潘岳《秋兴赋》：“熠耀粲于阶闼兮，蟋蟀鸣乎轩屏。”　画芭蕉：唐王维作画不论四时，尝画雪中芭蕉。
鹿藏蕉：《列子．周穆王》：“郑人有薪者，遇鹿而毙之，藏诸泥中，覆之以蕉，俄而失其处，遂以为梦，顺途而道其事。傍闻者取之，归告室人曰：‘薪者梦得鹿，不知其处，我今得之，彼真在梦中矣。’”湘灵：湘水之神。《楚辞．远游》：“使湘灵鼓瑟兮，令海若舞冯夷。”嬴女：秦穆公女弄玉，吹箫引凤。秦穆公，姓嬴。绛蜡：红色的蜡烛。　篆：焚香而起的烟，弯曲如篆字。', '', NULL, '', 'indent', 1524738464, '5ae1391da22b9d0040252dca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637500, '宝石山下看塔灯', NULL, 3, 253, 0, 1, '高濂', NULL, 10013, '57ba82a88ac2470063045693', '明', 'wen', '文', '', '', '保叔为省中最高灯塔，七级燃灯，周遭百盏，星丸错落，辉煌烛天，极目高空，恍自九霄中下。灯影澄湖，水面又作一种色相，霞须滉荡，摇曳长虹，夜静水寒，焰射蛟窟。更喜风清湖白，光彩俨驾鹊桥，得生羽翰，便想飞步绳河彼岸。忽闻钟磬，半空梵音，声出天上，使我欲念色尘，一时幻破，清静无碍。', '', '', '', NULL, '', 'indent', 1525360893, '5aeab87c9f54544cd16f5113', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637374, '笠翁对韵 · 下卷 · 三肴', NULL, 3, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '诗对礼，卦对爻。燕引对莺调。晨钟对暮鼓，野蔌对山肴。雉方乳，鹊始巢。猛虎对神獒。疏星浮荇叶，皓月上松梢。为邦自古推瑚琏，从政于今愧斗筲。管鲍相知，能交忘形胶漆友；蔺廉有隙，终对刎颈死生交。
歌对舞，笑对嘲。耳语对神交。焉乌对亥豕，獭髓对鸾胶。宜久敬，莫轻抛。一气对同胞。祭遵甘布被，张禄念绨袍。花径风来逢客访，柴扉月到有僧敲。夜雨园中，一颗不雕王子柰；秋风江上，三重曾卷杜公茅。
衙对舍，廪对庖。玉磬对金铙。竹林对梅岭，起凤对腾蛟。鲛绡帐，兽锦袍。露果对风梢。扬州输橘柚，荆土贡菁茅。断蛇埋地称孙叔，渡蚁编桥识宋郊。好梦难成，蛩响阶前偏唧唧；良朋远至，鸡声窗外正嘐嘐。', '', '鲛绡：传说南海有鲛人，水居如人，不废绩织，其所织之绡，称为鲛绡。
兽锦：集鳞豹毳，织为文绮，称兽锦。
菁茅：草名。古代祭祀用以漉酒去滓。《谷梁传．僖四年》桓公曰：“昭王南征不反，菁茅之贡不至，故周室不祭。”孙叔：孙叔敖。战国时楚国人，幼时见两头蛇，杀而埋之，恐后有人见而致死。
宋郊：传说宋郊见蚂蚁为雨所溺，渡而活之，后为状元。
良朋：一说“良明”。', '', NULL, '', 'indent', 1524738489, '5ae139371b69e619db5cea7e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637375, '笠翁对韵 · 下卷 · 四豪', NULL, 4, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '茭对茨，荻对蒿。山麓对江皋。莺簧对蝶板，麦浪对松涛。骐骥足，凤凰毛。美誉对嘉褒。文人窥蠹简，学士书兔毫。马援南征载薏苡，张骞西使进葡萄。辩口悬河，万语千言常亹亹；词源倒峡，连篇累牍自滔滔。
梅对杏，李对桃。棫朴对旌旄。酒仙对诗史，德泽对恩膏。悬一榻，梦三刀。拙逸对贵劳。玉堂花烛绕，金殿月轮高。孤山看鹤盘云下，蜀道闻猿向月号。万事从人，有花有酒应自乐；百年皆客，一丘一壑尽吾豪。
台对省，署对曹。分袂对同胞。鸣琴对击剑，返辙对回艚。良借箸，操捉刀。香茗对醇醪。涓泉归海大，寸壤积山高。石室客来煎雀舌，画堂宾至饮羊羔。被谪贾生，湘水凄凉吟《鵩鸟》；遭谗屈子，江潭憔悴著离骚。', '', '借箸：汉初张良遇高祖进食时，即席借箸（筷子）画策。提刀：《三国志．魏武纪》：“北使见魏王，操捉刀立旁，使出曰：‘魏王亦复平常，捉刀人乃真英雄耳！’”　“篑土”句：《尚书．旅獒》：“为山九仞，功亏一篑。”篑，盛土的竹筐。　雀舌：茶名。羊羔：酒名。《事物绀珠》：“羊羔酒出汾州，色白莹，饶风味。”　吟鹏鸟：西汉贾谊作《鹏鸟赋》。　著离骚：战国楚国大夫屈原作《离骚》。《史记．屈原贾生列传》：“屈原至于江滨，披发行吟泽畔。颜色憔悴，形容枯槁。”', '', NULL, '', 'indent', 1524738515, '5ae13950ac502e2713d09959', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637376, '笠翁对韵 · 下卷 · 五歌', NULL, 3, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '微对巨，少对多。直干对平柯。蜂媒对蝶使，雨笠对烟蓑。眉淡扫，面微酡。妙舞对清歌。轻衫裁夏葛，薄袂剪春罗。将相兼行唐李靖，霸王杂用汉萧何。月本阴精，岂有羿妻曾窃药；星为夜宿，浪传织女漫投梭。
慈对善，虐对苛。缥缈对婆娑。长杨对细柳，嫩蕊对寒莎。追风马，挽日戈。玉液对金波。紫诏衔丹凤，黄庭换白鹅。画角江城梅作调，兰舟野渡竹为歌。门外雪飞，错认空中飘柳絮；岩边瀑响，误疑天半落银河。
松对竹，荇对荷。薜荔对藤萝。梯云对步月，樵唱对渔歌。升鼎雉，听经鹅。北海对东坡。吴郎哀废宅，邵子乐行窝。丽水良金皆入冶，昆山美玉总须磨。雨过皇州，琉璃色灿华清瓦；风来帝苑，荷芰香飘太液波。
笼对槛，巢对窝。及第对登科。冰清对玉润，地利对人和。韩擒虎，荣驾鹅。青女对素娥。破头朱泚笏，折齿谢鲲梭。留客酒杯应恨少，动人诗句不须多。绿野凝烟，但听村前双牧笛；沧江积雪，惟看滩上一渔蓑。', '', '李靖：唐初功臣，三定朔方，位兼将相。　霸王杂用：霸业与王业交替使用。儒家称以力假仁者为霸，以德行仁政者为王。萧何：汉高祖谋士，后为丞相。窃药：《太平御览》：传说羿有长生药，其妻窃之，因奔月宫，是为嫦娥。　星为夜宿：牛郎织女均为星宿名。投梭：传说织女能纺纱织布。
升鼎：商时有雉，升庙鼎而鸣。　听经：传说僧志违养鹅，能听经说法。　北海：汉孔融为北海令，人称孔北海。东坡：宋代苏轼，在黄冈东坡筑室，因号东坡。　哀废宅：唐吴融有《废宅》诗：“风飘碧瓦雨摧垣，却有邻人与锁门。”　乐行窝：宋邵雍名其居为安乐窝。　华清：唐代行宫临潼华清池。太液：汉、唐皇宫苑内均有太液池。
冰清玉润：《晋书．卫玠传》：“玠妻父乐广，有海内重名，议者以为：‘妇公冰清，女婿玉润。’”喻人品高洁。韩擒虎：隋代大将，屡立战功。荣驾鹅：春秋时鲁昭公之大臣。　青女：神话中的霜神。素娥：月中女神名嫦娥。月色白，故又称素娥。唐李商隐《霜月》诗：“青女素娥俱耐冷，月中霜里斗蝉娟。”朱泚：唐代大臣，欲窃皇位，被段秀实以笏击破其头。　谢鲲梭：《晋书．谢鲲传》：“邻家高氏女有美色，鲲尝挑之，女投梭，折其两齿。”　一渔蓑：唐柳宗元《江雪》诗：“孤舟蓑笠翁，独钓寒江雪。”', '', NULL, '', 'indent', 1524738579, '5ae13992d50eee1805d344e0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637377, '笠翁对韵 · 下卷 · 六麻', NULL, 3, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '清对浊，美对嘉。鄙吝对矜夸。花须对柳眼，屋角对檐牙。志和宅，博望槎。秋实对春华。乾炉烹白雪，坤鼎炼丹砂。深宵望冷沙场月，绝塞听残野戍笳。满院松风，钟声隐隐为僧舍；半窗花月，锡影依依是道家。
雷对电，雾对霞。蚁阙对蜂衙。寄梅对怀橘，酿酒对烹茶。宜男草，益母花。杨柳对蒹葭。班姬辞帝辇，蔡琰泣胡笳。舞榭歌楼千万户，竹篱茅舍两三家。珊枕半床，月明时梦飞塞外；银筝一曲，花落处人在天涯。
圆对缺，正对斜。笑语对咨嗟。沈腰对潘鬓，孟笋对卢茶。百舌鸟，两头蛇。帝里对仙家。尧仁敷率土，舜德被流沙。桥上授书曾纳履，壁间题句已笼纱。远塞迢迢，露碛风沙何可极；长沙渺渺，雪涛烟浪信无涯。
疏对密，朴对华。义鹘对慈鸦。鹅群对雁阵，白苎对黄麻。读三到，吟八叉。肃静对喧哗。围棋兼把钓，沉李并浮瓜。羽客片时能煮石，狐禅千劫似蒸沙。党尉粗豪，金帐笼香斟美酒；陶生清逸，银铛融雪啜团茶。', '', '志和宅：张志和，唐代诗人，肃宗时待诏翰林，授左金吾卫录事参军，因事遭贬，自此不仕，隐居江湖，“以太虚为庐，明月为伴”。博望槎：汉张骞封博望侯。《荆楚岁时记》：“汉武帝令张骞使大夏，寻河源。乘槎经月，而至一处，见城郭和州府，室内有一女织，又见一丈夫牵牛饮河。骞问曰：‘此星何处？’答曰：‘可问严君平。’织女取搘机石与骞而还。”始知已到牛郎、织女星。
寄梅：南朝宋范晔在长安，陆凯自江南寄梅花一枝。诗曰：“江南无所有，聊赠一枝春。”怀橘：陆绩怀橘，见前注。宜男草：即萱草。益母花：中药名。班姬：汉成帝游后苑，命班婕妤同辇，辞不敢。蔡琰：汉末蔡邕女，早寡。被虏入胡，作《胡笳十八拍》。
“党尉”四句：《事文类聚》载，宋陶谷得党太尉家姬，偶烹雪茶。陶曰：“党家有此味否？”姬曰：“彼但知坐销金帐里，共饮羊羔美洒，浅斟低唱而已。”', '', NULL, '', 'indent', 1524738626, '5ae139c1a22b9d00402532fa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637378, '笠翁对韵 · 下卷 · 七阳', NULL, 4, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '台对阁，沼对塘。朝雨对夕阳。游人对隐士，谢女对秋娘。三寸舌，九回肠。玉液对琼浆。秦皇照胆镜，徐肇返魂香。青萍夜啸芙蓉匣，黄卷时摊薜荔床。元亨利贞，天地一机成化育；仁义礼智，圣贤千古立纲常。
红对白，绿对黄。昼永对更长。龙飞对凤舞，锦缆对牙樯。云弁使，雪衣娘。故国对他乡。雄文能徙鳄，艳曲为求凰。九日高峰惊落帽，暮春曲水喜流觞。僧占名山，云绕双林藏古殿；客栖胜地，风飘落叶响空廊。
衰对壮，弱对强。艳饰对新妆。御龙对司马，破竹对穿杨。读班马，识求羊。水色对山光。仙棋藏绿橘，客枕梦黄梁。池草入诗因有梦，海棠带恨为无香。风起画堂，帘箔影翻青荇沼；月斜金井，辘轳声度碧梧墙。
臣对子，帝对王。日月对风霜。乌台对紫府，蔀屋对岩廊。香山社，昼锦堂。雪牖对云房。芬椒涂内壁，文杏饰高梁。贫女幸分东壁影，幽人高卧北窗凉。绣阁探春，丽日半笼青镜色；水亭醉夏，薰风常透碧筒香。', '', '云弁使：即蜻蜓。雪衣娘：即白鹦鹉。　徙鳄：唐代潮州有鳄鱼为害，韩愈为守，作《祭鳄鱼文》，鳄乃去。　求凰：汉代卓王孙，成都富户，有女文君新寡，司马相如奏《凤求凰》之曲以挑之。落帽：晋孟嘉为桓温之参军，重阳节宴集龙山，风吹落帽。　流觞：晋王羲之等一批名士，在农历三月初三，在山阴兰亭之水边嬉游采兰，曲水流觞，赋诗以娱，以消除不祥，称为修禊。', '', NULL, '', 'indent', 1524738655, '5ae139dd9f545405f20769bb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637379, '笠翁对韵 · 下卷 · 八庚', NULL, 3, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '形对貌，色对声。夏邑对周京。江云对渭树，玉磬对银筝。人老老，我卿卿。晓燕对春莺。玄霜舂玉杵，白露贮金茎。贾客君山秋弄笛，仙人缑岭夜吹笙。帝业独兴，尽道汉高能用将；父书空读，谁言赵括善知兵。
功对业，性对情。月上对云行。乘龙对附骥，阆苑对蓬瀛。春秋笔，月旦评。东作对西成。隋珠光照乘，和璧价连城。三箭三人唐将勇，一琴一鹤赵公清。汉帝求贤，诏访严滩逢故旧；宋廷优老，年尊洛社重耆英。
昏对旦，晦对明。久雨对新晴。蓼湾对花港，竹友对梅兄。黄石叟，丹丘生。犬吠对鸡鸣。暮山云外断，新水月中平。半榻清风宜午梦，一犁好雨趁春耕。王旦登庸，误我十年迟作相；刘羵下第，愧他多士早成名。', '', '黄石叟：即汉初张良所遇仙人黄石公。丹丘生：仙人。丹丘，神话中神仙之地，昼夜长明。王旦：《宋史．王旦传》载，宋王旦柄权十八年，死后，王钦若继为宰相。王钦若语人曰：“为王公迟我十年作宰相。”刘蕡不第：见前注。', '', NULL, '', 'indent', 1524738679, '5ae139f6d50eee1805d34798', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637380, '笠翁对韵 · 下卷 · 九青', NULL, 4, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '庚对甲，巳对丁。魏阙对彤庭。梅妻对鹤子，珠箔对银屏。鸳浴沼，鹭飞汀。鸿雁对鹡（鴒）。人间寿者相，天上老人星。八月好修攀桂斧，三春须系护花铃。江阁秋登，一水净连天际碧；石栏晓倚，群山秀向雨余青。
危对乱，泰对宁。纳陛对趋庭。金盘对玉箸，泛梗对浮萍。群玉圃，众芳亭。旧典对新型。骑牛闲读史，牧豕自横经。秋首田中禾颖重，春余园内菜花馨。旅次凄凉，塞月江风皆惨淡；筵前欢笑，燕歌赵舞独娉婷。', '', '梅妻鹤子：宋林逋，隐居杭州西湖孤山，终生不娶，以梅、鹤自娱，人称其“梅妻鹤子”。珠箔银屏：唐白居易《长恨歌》：“珠箔银屏迤逦开。”　“八月”句：旧时以科举登第为攀柱。考试时间一般定在八月，称“秋闱”。护花铃：明代宁王爱花，尝作护花铃，蜂、鸟至则牵铃惊之。
泛梗浮萍：浮动在水面的树梗和萍草。比喻飘荡无主。唐徐夤《别》诗：“酒尽欲终问后期，泛萍浮梗不胜悲。”　骑牛：隋末李密骑牛读《汉书》，常挂书卷于牛角之上。　牧豕：汉公孙弘少为人牧豕（猪），勤于学，常带经卷而读，年五十位至丞相。', '', NULL, '', 'indent', 1524738728, '5ae13a19a22b9d004539797f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637381, '笠翁对韵 · 下卷 · 十蒸', NULL, 3, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '蘋对蓼，芡对菱。雁弋对鱼罾。齐纨对鲁缟，蜀锦对吴绫。星渐没，日初升。九聘对三征。萧何曾作吏，贾岛昔为僧。贤人视履循规矩，大斧挥斤按准绳。野渡春风，人喜乘潮移酒舫；江天暮雨，客愁隔岸对渔灯。
谈对吐，谓对称。冉闵对颜曾。侯嬴对伯嚭，祖逖对孙登。抛白纻，宴红绫。胜友对良朋。争名如逐鹿，谋利似趋蝇。仁杰姨惭周不仕，王陵母识汉方兴。句写穷愁，浣花寄迹传工部；诗吟变乱，凝碧伤心叹右丞。', '', '九聘：多次聘请。出典未详。三征：朝廷三次征召。《后汉书．杨伦传》：“伦前后三征，皆以直谏不合。”贾岛：唐代诗人贾岛，原为僧人，法名无本。韩愈劝其读书，乃还俗，参加进士考试，但屡试不中。', '', NULL, '', 'indent', 1524738754, '5ae13a411b69e619db5cf611', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637382, '笠翁对韵 · 下卷 · 十一尤', NULL, 2, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '荣对辱，喜对忧。缱绻对绸缪。吴娃对越女，野马对沙鸥。茶解渴，酒消愁。白眼对苍头。马迁修史记，孔子作春秋。莘野耕夫闲举耜，磻溪渔父晚垂钩。龙马游河，羲圣因图而画卦；神龟出洛，禹王取法以明畴。
冠对履，舄对裘。院小对庭幽。面墙对膝地，错智对良筹。孤嶂耸，大江流。芳泽对园丘。花潭来越唱，柳屿起吴讴。莺懒燕忙三月雨，蛩摧蝉退一天秋。钟子听琴，荒径入林山寂寂；谪仙捉月，洪涛接岸水悠悠。
鱼对鸟，鸽对鸠。翠馆对红楼。七贤对三友，爱日对悲秋。虎类狗，蚁如牛。列辟对诸侯。陈唱临春乐，隋歌清夜游。空中事业麒麟阁，地下文章鹦鹉洲。旷野平原，猎士马蹄轻似箭；斜风细雨，牧童牛背稳如舟。', '', '白眼：三国魏末阮籍能作青、白眼。苍头：以青巾裹头的士卒。《战国策．魏策》：“今窃闻大王之卒，武力二十余万，苍头二十万。”　莘野耕夫：《孟子．万章上》：“伊尹耕于有莘之野，而乐尧舜之道焉。”　磻溪渔父：指商代末年的姜尚。
错智：汉晁错多智，人称智囊。良筹：汉初张良借箸筹画政事。钟子听琴：钟子，即钟子期。参见前“高山流水”注释。　谪仙捉月：传说唐李白在采石矶，醉后下江捉月而溺死。', '', NULL, '', 'indent', 1524738793, '5ae13a689f545463fe563fd4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637383, '笠翁对韵 · 下卷 · 十二侵', NULL, 2, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '歌对曲，啸对吟。往古对来今。山头对水面，远浦对遥岑。勤三上，惜寸阴。茂树对平林。卞和三献玉，杨震四知金。青皇风暖催芳草，白帝城高急暮砧。绣虎雕龙，才子窗前挥彩笔；描鸾刺凤，佳人帘下度金针。
登对眺，涉对临。瑞雪对甘霖。主欢对民乐，交浅对言深。耻三战，乐七擒。顾曲对知音。大车行槛槛，驷马聚骎骎。紫电青虹腾剑气，高山流水识琴心。屈子怀君，极浦吟风悲泽畔；王郎忆友，扁舟卧雪访山阴。', '', '三战：《史记．平原君虞卿列传》：“毛遂谓楚王曰：白起小竖子耳！一战而举鄢郢，再战而烧夷陵，三战而辱王之先人，而王不知耻焉！”七擒：三国时诸葛亮征孟获，七纵七擒。顾曲：《三国志．周瑜传》载，三国吴周瑜善审音律，曲有阙误，瑜必知之，知之必顾，故时人谣曰：“曲有误，周郎顾。”王郎：《世说新语．任诞》载，晋王子猷雪夜访山阴戴逵，经宿方至，造门不入而返，人问其故，王曰：“吾本乘兴而行，兴尽而返，何必见戴。”', '', NULL, '', 'indent', 1524738836, '5ae13a929f545463fe5640df', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637401, '庄子 · 外篇 · 天运', NULL, 8, 16, 0, 1, '庄子', NULL, 10064, '57b90297165abd0054bfdce7', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E5%A4%96%E7%AF%87%C2%B7%E5%A4%A9%E8%BF%90/10198446', '', '“天其运乎？地其处乎？日月其争于所乎？孰主张是？孰维纲是？孰居无事推而行是？意者其有机缄而不得已乎？意者其运转而不能自止邪？云者为雨乎？雨者为云乎？孰隆施是？孰居无事淫乐而劝是？风起北方，一西一东，有上仿徨。孰嘘吸是？孰居无事而披拂是？敢问何故？”巫咸袑曰：“来，吾语女。天有六极五常，帝王顺之则治，逆之则凶。九洛之事，治成德备，临照下土，天下戴之，此谓上皇。”
商大宰荡问仁于庄子。庄子曰：“虎狼，仁也。”曰：“何谓也？”庄子曰：“父子相亲，何为不仁！”曰：“请问至仁。”庄子曰：“至仁无亲。”大宰曰：“荡闻之，无亲则不爱，不爱则不孝。谓至仁不孝，可乎？”庄子曰：“不然，夫至仁尚矣，孝固不足以言之。此非过孝之言也，不及孝之言也。夫南行者至于郢，北面而不见冥山，是何也？则去之远也。故曰：以敬孝易，以爱孝难；以爱孝易，而忘亲难；忘亲易，使亲忘我难；使亲忘我易，兼忘天下难；兼忘天下易，使天下兼忘我难。夫德遗尧、舜而不为也，利泽施于万世，天下莫知也，岂直大息而言仁孝乎哉！夫孝悌仁义，忠信贞廉，此皆自勉以役其德者也，不足多也。故曰：至贵，国爵并焉；至富，国财并焉；至愿，名誉并焉。是以道不渝。”
北门成问于黄帝曰：“帝张咸池之乐于洞庭之野，吾始闻之惧，复闻之怠，卒闻之而惑，荡荡默默，乃不自得。”帝曰：“汝殆其然哉！吾奏之以人，徵之以天，行之以礼义，建之以大清。夫至乐者，先应之以人事，顺之以天理，行之以五德，应之以自然。然后调理四时，太和万物。四时迭起，万物循生。一盛一衰，文武伦经。一清一浊，阴阳调和，流光其声。蛰虫始作，吾惊之以雷霆。其卒无尾，其始无首。一死一生，一偾一起，所常无穷，而一不可待。汝故惧也。吾又奏之以阴阳之和，烛之以日月之明。其声能短能长，能柔能刚，变化齐一，不主故常。在谷满谷，在坑满坑。涂却守神，以物为量。其声挥绰，其名高明。是故鬼神守其幽，日月星辰行其纪。吾止之于有穷，流之于无止。子欲虑之而不能知也，望之而不能见也，逐之而不能及也。傥然立于四虚之道，倚于槁梧而吟：‘目知穷乎所欲见，力屈乎所欲逐，吾既不及，已夫！’形充空虚，乃至委蛇。汝委蛇，故怠。吾又奏之以无怠之声，调之以自然之命。故若混逐丛生，林乐而无形，布挥而不曳，幽昏而无声。动于无方，居于窈冥，或谓之死，或谓之生；或谓之实，或谓之荣。行流散徙，不主常声。世疑之，稽于圣人。圣也者，达于情而遂于命也。天机不张而五官皆备。此之谓天乐，无言而心说。故有焱氏为之颂曰：‘听之不闻其声，视之不见其形，充满天地，苞裹六极。’汝欲听之而无接焉，而故惑也。乐也者，始于惧，惧故祟；吾又次之以怠，怠故遁；卒之于惑，惑故愚；愚故道，道可载而与之俱也。”
孔子西游于卫，颜渊问师金曰：“以夫子之行为奚如？”师金曰：“惜乎！而夫子其穷哉！”颜渊曰：“何也？”师金曰：“夫刍狗之未陈也，盛以箧衍，巾以文绣，尸祝齐戒以将之。及其已陈也，行者践其首脊，苏者取而爨之而已。将复取而盛以箧衍，巾以文绣，游居寝卧其下，彼不得梦，必且数眯焉。今而夫子亦取先王已陈刍狗，聚弟子游居寝卧其下。故伐树于宋，削迹于卫，穷于商周，是非其梦邪？围于陈蔡之间，七日不火食，死生相与邻，是非其眯邪？夫水行莫如用舟，而陆行莫如用车。以舟之可行于水也，而求推之于陆，则没世不行寻常。古今非水陆与？周鲁非舟车与？今蕲行周于鲁，是犹推舟于陆也！劳而无功，身必有殃。彼未知夫无方之传，应物而不穷者也。且子独不见夫桔槔者乎？引之则俯，舍之则仰。彼，人之所引，非引人者也。故俯仰而不得罪于人。故夫三皇五帝之礼义法度，不矜于同而矜于治。故譬三皇五帝之礼义法度，其犹蒩梨橘柚邪！其味相反而皆可于口。故礼义法度者，应时而变者也。今取猨狙而衣以周公之服，彼必龄啮挽裂，尽去而后慊。观古今之异，犹猨狙之异乎周公也。故西施病心而颦其里，其里之丑人见之而美之，归亦捧心而颦其里。其里之富人见之，坚闭门而不出；贫人见之，挈妻子而去之走。彼知颦美而不知颦之所以美。惜乎，而夫子其穷哉！”
孔子行年五十有一而不闻道，乃南之沛见老聃。老聃曰：“子来乎？吾闻子，北方之贤者也！子亦得道乎？”孔子曰：“未得也。”老子曰：“子恶乎求之哉？”曰：“吾求之于度数，五年而未得也。”老子曰：“子又恶乎求之哉？”曰：“吾求之于阴阳，十有二年而未得也。”老子曰：“然，使道而可献，则人莫不献之于其君；使道而可进，则人莫不进之于其亲；使道而可以告人，则人莫不告其兄弟；使道而可以与人，则人莫不与其子孙。然而不可者，无它也，中无主而不止，外无正而不行。由中出者，不受于外，圣人不出；由外入者，无主于中，圣人不隐。名，公器也，不可多取。仁义，先王之蘧庐也，止可以一宿而不可久处。觏而多责。古之至人，假道于仁，托宿于义，以游逍遥之虚，食于苟简之田，立于不贷之圃。逍遥，无为也；苟简，易养也；不贷，无出也。古者谓是采真之游。以富为是者，不能让禄；以显为是者，不能让名。亲权者，不能与人柄，操之则栗，舍之则悲，而一无所鉴，以窥其所不休者，是天之戮民也。怨、恩、取、与、谏、教、生杀八者，正之器也，唯循大变无所湮者为能用之。故曰：正者，正也。其心以为不然者，天门弗开矣。”
孔子见老聃而语仁义。老聃曰：“夫播糠眯目，则天地四方易位矣；蚊虻囋肤，则通昔不寐矣。夫仁义憯然，乃愤吾心，乱莫大焉。吾子使天下无失其朴，吾子亦放风而动，总德而立矣！又奚杰然若负建鼓而求亡子者邪！夫鹄不日浴而白，乌不日黔而黑。黑白之朴，不足以为辩；名誉之观，不足以为广。泉涸，鱼相与处于陆，相呴以湿，相濡以沫，不若相忘于江湖。”
孔子见老聃归，三日不谈。弟子问曰：“夫子见老聃，亦将何规哉？”孔子曰：“吾乃今于是乎见龙。龙，合而成体，散而成章，乘乎云气而养乎阴阳。予口张而不能脋。予又何规老聃哉？”子贡曰：“然则人固有尸居而龙见，雷声而渊默，发动如天地者乎？赐亦可得而观乎？”遂以孔子声见老聃。老聃方将倨堂而应，微曰：“予年运而往矣，子将何以戒我乎？”子贡曰：“夫三皇五帝之治天下不同，其系声名一也。而先生独以为非圣人，如何哉？”老聃曰：“小子少进！子何以谓不同？”对曰：“尧授舜，舜授禹。禹用力而汤用兵，文王顺纣而不敢逆，武王逆纣而不肯顺，故曰不同。”老聃曰：“小子少进，余语汝三皇五帝之治天下：黄帝之治天下，使民心一。民有其亲死不哭而民不非也。尧之治天下，使民心亲。民有为其亲杀其杀而民不非也。舜之治天下，使民心竞。民孕妇十月生子，子生五月而能言，不至乎孩而始谁，则人始有夭矣。禹之治天下，使民心变，人有心而兵有顺，杀盗非杀人。自为种而‘天下’耳。是以天下大骇，儒墨皆起。其作始有伦，而今乎妇女，何言哉！余语汝：三皇五帝之治天下，名曰治之，而乱莫甚焉。三皇之知，上悖日月之明，下睽山川之精，中堕四时之施。其知惨于蛎虿之尾，鲜规之兽，莫得安其性命之情者，而犹自以为圣人，不可耻乎？其无耻也！”子贡蹴蹴然立不安。
孔子谓老聃曰：“丘治《诗》、《书》、《礼》、《乐》、《易》、《春秋》六经，自以为久矣，孰知其故矣，以奸者七十二君，论先王之道而明周、召之迹，一君无所钩用。甚矣！夫人之难说也？道之难明邪？”老子曰：“幸矣，子之不遇治世之君！夫六经，先王之陈迹也，岂其所以迹哉！今子之所言，犹迹也。夫迹，履之所出，而迹岂履哉！夫白鶂之相视，眸子不运而风化；虫，雄鸣于上风，雌应于下风而风化。类自为雌雄，故风化。性不可易，命不可变，时不可止，道不可壅。苟得于道，无自而不可；失焉者，无自而可。”孔子不出三月，复见，曰：“丘得之矣。乌鹊孺，
鱼傅沫，细要者化，有弟而兄啼。久矣，夫丘不与化为人！不与化为人，安能化人。”老子曰：“可，丘得之矣！”', '全文大体可以分为七个部分，第一部分至“此谓上皇”，就日、月、云、雨等自然现象提出疑问。第二部分至“是以道不渝”，写太宰荡向庄子请教，说明“至仁无亲”的道理。第三部分至“道可载而与之俱也”，写黄帝对音乐的谈论。第四部分至“而夫子其穷哉”，写师金对孔子周游列国推行礼制的评价。第五部分至“天门弗开矣”，借老聃对孔子的谈话来谈论道。第六部分至“子贡蹴蹴然立不安”，写老聃对仁义和三皇五帝之治的批判。余下为第七部分，写孔子得道，进一步批判先王之治，指出唯有顺应自然变化方才能够教化他人。', '', '天在自然运行吧？地在无心静处吧？日月交替出没是在争夺居所吧？谁在主宰张罗这些现象呢？谁在维系统带这些现象呢？是谁闲瑕无事推动运行而形成这些现象呢？揣测它们有什么主宰的机关而出于不得已呢？还是揣测它们运转而不能自己停下来呢？乌云是雨水蒸腾而成呢？还是雨水是乌云降落而成呢？是谁在行云布雨？是谁闲居无事贪求欢乐而促成了这种现象？风起于北方，一会儿西一会儿东，在天空中来回游动，是谁吐气或吸气造成了云彩的飘动？还是谁闲居无事煽动而造成这样的现象？我斗胆地请教是些什么缘故？”巫咸祒说：“来！我告诉你。大自然本身就存在六合和五行，帝王顺应它便能治理好国家，违背它就会招来灾祸。顺应九州聚居之人的各种事务，致使天下治理而道德完备，光辉照临人间，天下人拥戴，这就叫做‘上皇’。”
宋国的太宰荡向庄子请教仁爱的问题。庄子说：“虎和狼也具有仁爱。”太宰荡说：“这是说什么呢？”庄子说：“虎狼也能父子相互亲爱，为什么不能叫做仁呢？”太宰荡又问：“请教最高境界的仁。”庄子说：“最高境界的仁就是没有亲。”太宰荡说：“我听说，没有亲就不会有爱，没有爱就不会有孝，说最高境界的仁就是不孝，可以吗？”
庄子说：“不是这样。最高境界的仁实在值得推崇，孝本来就不足以说明它。这并不是要责备行孝的言论，而是不涉及行孝的言论。向南方走的人到了楚国都诚郢，面朝北方也看不见冥山，这是为什么呢？距离冥山越发地远了。所以说，用恭敬的态度来行孝容易，以爱的本心来行孝困难；用爱的本心来行孝容易，用虚静淡泊的态度对待双亲困难；虚静淡泊地对待双亲容易，使双亲也能虚静淡泊地对待自己困难；使双亲虚静淡泊地对待自己容易，能一并虚静淡泊地对待天下人困难；一并虚静淡泊地对待天下之人容易，使天下之人能一并忘却自我困难。盛德遗忘了尧舜因而尧舜方才能任物自得，利益和恩泽施给万世，天下人却没有谁知道，难道偏偏需要深深慨叹而大谈仁孝吗！孝、悌、仁、义、忠、信、贞、廉，这些都是用来劝勉自身而拘执真性的，不值得推崇。所以说，最为珍贵的，一国的爵位都可以随同忘却自我而弃除；最为富有的，一国的资财都可以随同知足的心态而弃置，最大的心愿，名声和荣誉都可以随同通适本性而泯灭。所以，大道是永恒不变的。”
北门成向黄帝问道：“你在广漠的原野上演奏咸池乐曲，我起初听起来感到惊惧，再听下去就逐步松缓下来，听到最后却又感到迷惑不解，神情恍惚无知无识，竟而不知所措。”
黄帝说：“你恐怕会有那样的感觉吧！我因循人情来演奏乐曲，取法自然的规律，用礼义加以推进，用天道来确立。最美妙最高贵的乐曲，总是用人情来顺应，用天理来因循，用五德来推演，用自然来应合，然后方才调理于四季的序列，跟天地万物同和。乐声犹如四季更迭而起，万物都遵循这一变化而栖息生长；忽而繁茂忽而衰败，春季的生机和秋季的肃杀都在有条不紊地更迭；忽而清新忽而浊重，阴阳相互调配交和，流布光辉和与之相应的声响；犹如解除冬眠的虫豸开始活动，我用雷霆使它们惊起。乐声的终结寻不到结尾，乐声的开始寻不到起头；一会儿消逝一会儿兴起，一会儿偃息一会儿亢进；变化的方式无穷无尽，全不可以有所期待。因此你会感到惊恐不安。
“我又用阴阳的交和来演奏，用日月的光辉来照临整个乐曲。于是乐声能短能长，能柔能刚，变化虽然遵循着一定的条理，却并不拘泥于故态和常规；流播于山谷山谷满盈，流播于坑凹坑凹充实；堵塞心灵的孔隙而使精神宁寂持守，一切用外物来度量。乐声悠扬广远，可以称作高如上天、明如日月。因此连鬼神也能持守幽暗，日月星辰也能运行在各自的轨道上。我时而把乐声停留在一定的境界里，而乐声的寓意却流播在无穷无尽的天地中。我想思考它却不能知晓，我观望它却不能看见，我追赶它却总不能赶上；只得无心地伫立在通达四方而无涯际的衢道上，依着几案吟咏。目光和智慧困窘于一心想要见到的事物，力气竭尽于一心想要追求的东西。我早已经赶不上了啊！形体充盈却又好像不复存在，方才能够随应变化。你随应变化，因此惊恐不安的情绪慢慢平息下来。
“我又演奏起忘情忘我的乐声，并且用自然的节奏来加以调协。因而乐声象是混同驰逐相辅相生，犹如风吹丛林自然成乐却又无有形迹；传播和振动均无外力引曳，幽幽暗暗又好象没有了一点儿声响。乐声启奏于不可探测的地方，滞留于深远幽暗的境界；有时候可以说它消逝，有时候又可以说它兴起；有时候可以说它实在，有时候又可说它虚华；演进流播飘散游徙，绝不固守一调。世人往往迷惑不解，向圣人问询查考。所谓圣，就是通达事理而顺应于自然。自然的枢机没有启张而五官俱全，这就可以称之为出自本然的乐声，犹如没有说话却心里喜悦。所以有焱氏为它颂扬说：‘用耳听听不到声音，用眼看看不见形迹，充满于大地，包容了六极。’你想听却无法衔接连贯，所以你到最后终于迷惑不解。
“这样的乐章，初听时从惶惶不安的境态开始，因为恐惧而认为是祸患；我接着又演奏了使人心境松缓的乐曲，因为松缓而渐渐消除恐惧；乐声最后在迷惑不解中终结，因为迷惑不解而无知无识似的；无知无识的浑厚心态就接近大道，接近大道就可以借此而与大道融合相通了。”
孔子向西边游历到卫国。颜渊问师金道：“你认为夫子此次卫国之行怎么样？”师金说：“可惜呀，你的先生一定会遭遇困厄啊！”颜渊说：“为什么呢？”
师金说：“用草扎成的狗还没有用于祭祀，一定会用竹制的箱笼来装着，用绣有图纹的饰物来披着，祭祀主持人斋戒后迎送着。等到它已用于祭祀，行路人踩踏它的头颅和脊背，拾草的人捡回去用于烧火煮饭罢了；想要再次取来用于祭祀而拿竹筐装着它，拿绣有图纹的饰物披着它，游乐居处于主人的身旁，即使它不做恶梦，也会一次又一次地感受到梦魇似的压抑。如今你的先生，也是在取法先王已经用于祭祀的草扎之狗，并聚集众多弟子游乐居处于他的身边。所以在宋国大树下讲习礼法而大树被砍伐，在卫国游说而被铲掉了所有的足迹，在殷地和东周游历遭到困厄，这不就是那样的恶梦吗？在陈国和蔡国之间遭到围困，整整七天没有能生火就食，让死和生成了近邻，这又不就是那压得喘不过气来的梦魇吗？
“在水上划行没有什么比得上用船，在陆地上行走没有什么比得上用车，因为船可以在水中划行而奢求在陆地上推着船走，那么终身也不能行走多远。古今的不同不就象是水面和陆地的差异吗？周和鲁的差异不就象是船和车的不同吗？如今一心想在鲁国推行周王室的治理办法，这就象是在陆地上推船而行，徒劳而无功，自身也难免遭受祸殃。他们全不懂得运动变化并无限定，只能顺应事物于无穷的道理。
“况且，你没有看见那吊杆汲水的情景吗？拉起它的一端而另一端便俯身临近水面，放下它的一端而另一端就高高仰起。那吊杆，是因为人的牵引，并非它牵引了人，所以或俯或仰均不得罪人。因此说，远古三皇五帝时代的礼义法度，不在于相同而为人顾惜，在于治理而为人看重。拿三皇五帝时代的礼义法度来打比方，恐怕就像柤、梨、橘、柚四种酸甜不一的果子吧，它们的味道彼此不同然而却都很可口。
“所以，礼义法度，都是顺应时代而有所变化的东西。如今捕捉到猿猴给它穿上周公的衣服，它必定会咬碎或撕裂，直到全部剥光身上的衣服方才心满意足。观察古今的差异，就象猿猴不同于周公。从前西施心口疼痛而皱着眉头在邻里间行走，邻里的一个丑女人看见了认为皱着眉头很美，回去后也在邻里间捂着胸口皱着眉头。邻里的有钱人看见了，紧闭家门而不出；贫穷的人看见了，带着妻儿子女远远地跑开了。那个丑女人只知道皱着眉头好看却不知道皱着眉头好看的原因。可惜呀，你的先生一定会遭遇厄运啊！
孔子活了五十一岁还没有领悟大道，于是往南去到沛地拜见老聃。老聃说：“你来了吗？我听说你是北方的贤者，你恐怕已经领悟了大道吧？”孔子说：“还未能得到。”老子说：“你是怎样寻求大道的呢？”孔子说：“我在规范、法度方面寻求大道，用了五年的功夫还未得到。”老子说：“你又怎样寻求大道呢？”孔子说：“我又从阴阳的变化来寻求，十二年了还是未能得到。”
老子说：“会是这样的。假使道可以用来进献，那么人们没有谁不会向国君进献大道；假使道可以用来奉送，那么人们没有谁不会向自己的双亲奉送大道；假使道可以传告他人，那么人们没有谁不会告诉给他的兄弟；假使道可以给与人，那么人们没有谁不会用来给与他的子孙。然而不可以这样做的原因，没有别的，内心不能自持因而大道不能停留，对外没有什么相对应因而大道不能推行。从内心发出的东西，倘若不能为外者所接受，圣人也就不会有所传教；从外部进入内心的东西，倘若心中无所领悟而不能自持，圣人也就不会有所怜惜。名声，乃是人人都可使用的器物，不可过多猎取。仁义，乃是前代帝王的馆舍，可以住上一宿而不可以久居，多次交往必然会生出许多责难。
“古代道德修养高的至人，对于仁来说只是借路，对于义来说只是暂住，而游乐于自由自在、无拘无束的境域，生活于马虎简单、无奢无华的境地，立身于从不施与的园圃。自由自在、无拘无束，便是无为；马虎简单、无奢无华，就易于生存；从不施与，就不会使自己受损也无裨益于他人。古代称这种情况叫做神采真实的遨游。
“把贪图财贿看作正确的人，不会让人利禄；把追求显赫看作正确的人，不会让人名声；迷恋权势的人，不会授人权柄。掌握了利禄、名声和权势便唯恐丧失而整日战栗不安，而放弃上述东西又会悲苦不堪，而且心中全无一点鉴识，眼睛只盯住自己所无休止追逐的东西，这样的人只能算是被大自然所刑戮的人。怨恨、恩惠、获取、施与、谏诤、教化、生存、杀戮、这八种作法全是用来端正他人的工具，只有遵循自然的变化而无所阻塞滞留的人才能够运用它。所以说，所谓正，就是使人端正。内心里认为不是这样，那么心灵的门户就永远不可能打开。”
孔子拜见老聃讨论仁义。老聃说：“播扬的糠屑进入眼睛，也会颠倒天地四方，蚊虻之类的小虫叮咬皮肤，也会通宵不能入睡。仁义给人的毒害就更为惨痛乃至令人昏愦糊涂，对人的祸乱没有什么比仁义更为厉害。你要想让天下不至于丧失淳厚质朴，你就该纵任风起风落似地自然而然地行动，一切顺于自然规律行事，又何必那么卖力地去宣扬仁义，好像是敲着鼓去追赶逃亡的人似的呢？白色的天鹅不需要天天沐浴而毛色自然洁白，黑色的乌鸦不需要每天用黑色渍染而毛色自然乌黑，乌鸦的黑和天鹅的白都是出于本然，不足以分辨谁优谁劣；名声和荣誉那样的外在东西，更不足以播散张扬。泉水干涸了，鱼儿相互依偎在陆地上，大口出气来取得一点儿湿气，靠唾沫来相互得到一点儿润湿，不如在江河湖海中畅游而彼此相互忘却。”
孔子拜见老聃回来，整整三天不讲话。弟子问道：“先生见到老聃，对他作了什么诲劝吗？”孔子说：“我直到如今才竟然在老聃那儿见到了真正的龙！龙，合在一起便成为一个整体，分散开来又成为华美的文采，乘驾云气而养息于阴阳之间。我大张着口久久不能合拢，我又哪能对老聃作出诲劝呢！”子贡说：“这样说，那么人难道有像尸体一样安稳不动而又像龙一样神情飞扬地显现，像疾雷一样震响而又像深渊那样沉寂，发生和运动犹如天地运动变化的情况吗？我也能见到他并亲自加以体察吗？”于是借助孔子的名义前去拜见老聃。
老聃正伸腿坐在堂上，轻声地应答说：“我年岁老迈，你将用什么来告诫我呢？”子贡说：“远古时代三皇五帝治理天下各不相同，然而却都有好的名声，唯独先生您不认为他们是圣人，这是为什么呢？”
老聃说：“年轻人，你稍稍近前些！你凭什么说他们各自有所不同？”子贡回答：“尧让位给舜，舜让位给禹，禹用力治水而汤用力征伐，文王顺从商纣不敢有所背逆，武王背逆商纣而不顺服，所以说各不相同。”
老聃说：“年轻人，你再稍微靠前些！我对你说说三皇五帝治理天下的事。黄帝治理天下，使人民心地淳厚保持本真，百姓有谁死了双亲并不哭泣，人们也不会加以非议。唐尧治理天下，使百姓敬重双亲，百姓有谁为了敬重双亲依照等差而做到亲疏有别，人们同样也不会非议。虞舜治理天下，使百姓心存竞争，怀孕的妇女十个月生下孩子，孩子生下五个月就张口学话，不等长到两、三岁就开始识人问事，于是开始出现夭折短命的现象。夏禹治理天下，使百姓心怀变诈，人人存有机变之心因而动刀动枪成了理所当然之事，杀死盗贼不算杀人，人们各自结成团伙而肆意于天下，所以天下大受惊扰，儒家、墨家都纷纷而起。他们初始时也还有伦有理，可是时至今日以女为妇，还有什么可言呢！我告诉你。三皇五帝治理天下，名义上叫做治理，而扰乱人性和真情没有什么比他们更严重的了。三皇的心智就只是，对上而言遮掩了日月的光明，对下而言违背了山川的精粹，就中而言毁坏了四时的推移。他们的心智比蛇蝎之尾还惨毒，就连小小的兽类，也不可能使本性和真情获得安宁，可是还自以为是圣人。是不认为可耻吗，还是不知道可耻呢？”子贡听了惊惶不定，心神不安地站着。
孔子对老聃说：“我研修《诗》《书》《礼》《乐》《易》《春秋》六部经书，自认为很久很久了，熟悉了旧时的各种典章制度；用违反先王之制的七十二个国君为例，论述先王（治世）的方略和彰明周公、召公的政绩，可是一个国君也没有取用我的主张。实在难啊！是人难以规劝，还是大道难以彰明呢？”
老子说：“幸运啊，你不曾遇到过治世的国君！六经，乃是先王留下的陈旧遗迹，哪里是先王遗迹的本原！如今你所谈论的东西，就好像是足迹；足迹是脚踩出来的，然而足迹难道就是脚吗！白？相互而视，眼珠子一动也不动便相诱而孕；虫，雄的在上方鸣叫，雌的在下方相应而诱发生子；同一种类而自身具备雌雄两性，不待交合而生子。本性不可改变，天命不可变更，时光不会停留，大道不会壅塞。假如真正得道，无论去到哪里都不会受到阻遏；失道的人，无论去到哪里都是此路不通。”
孔子三月闭门不出，再次见到老聃说：“我终于得道了。乌鸦喜鹊在巢里交尾孵化，鱼儿借助水里的泡沫生育，蜜蜂自化而生，生下弟弟哥哥就常常啼哭。很长时间了，我没有能跟万物的自然变化相识为友！不能跟自然的变化相识为友，又怎么能教化他人！”老子听了后说：“好。孔丘得道了！”', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf53911759740c9bd943", "shortContent": "此赋讲述了一个关于乌的故事：雌、雄二乌筑巢被盗鸟偷窃，雌乌为保护巢穴和盗鸟发生搏斗而受伤，又遭拘捕，雄乌欲与之同死，雌乌不允，嘱咐雄乌另觅贤妇，善待幼子，而后投地而亡。雄乌大恸，却无能为力，投冤无门，只能高翔离去。全赋以乌喻人，反映了当时政治腐败、社会黑暗的状况，赞美了夫妻之间生死与共的爱情。\n刘勰在《文心雕龙·诠赋》中说：“赋者，铺也，铺采摛文，体物写志也。”西汉大赋的特点在内容上以都邑、宫苑、...", "authors": ["杨玲"], "pressName": "上海辞书出版社"}, {"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf6a5914587d02f59d62", "shortContent": "此赋是陆游在宋孝宗淳熙七年（1180）路经丰城时所作。丰城剑，事详《晋书·张华传》。丰城，今江西丰城县。关于丰城剑的传说，在历史上广为流传，文人也将之写入诗歌，如南朝陈阴铿《经丰城剑池诗》、唐李白《古风》之十六，李群玉《雷焕丰城掘剑记》等等。本赋就是取材于这个传说的历史故事，议论生发，打破赋的常规写法，对丰城剑本身未着一笔描写，而只对西晋年间与丰城剑的传说及有关的历史事件与历史人物展开评论。\n赋分...", "authors": ["叶幼明"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1e334a8757d5a0edb5a", "shortContent": "本文是作者有感于南朝梁代任昉生前身后截然不同的境遇，慨叹世态炎凉和人情浇薄而撰写的。\n南北朝时期，任昉是名闻遐迩的文学家、政绩卓著的新安太守。《梁书·任昉传》云：“初昉立于士大夫间，多所汲引。有善己者，则厚其声名。”故士大夫纷纷慕名造访，正如文中所述：“见一善则盱衡扼腕，遇一才则扬眉抵掌。雌黄出其唇吻，朱紫由其月旦。冠盖辐凑，衣裳云合，辎軿击轊，坐客恒满。”他为政清廉，家无蓄资，一旦撒手西归，家业...", "authors": ["孙小力"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed20ad635634aee3eab91", "shortContent": "从标题看，这篇文章是人物传记，实际上是作者周容虚构的一篇讽喻性的故事。晋陶渊明的《五柳先生传》，唐韩愈的《圬者王承福传》、柳宗元的《种树郭橐驼传》、《捕蛇者说》，明宋濂的《樗散生传》、刘基的《卖柑者言》等，都属于此种类型。此类文章，有的有具体的人事为依据，有的纯属虚构，而共同的特点则是因事说理，表述作者的经验之谈或感愤之言，是介于史传和小说之间的一种文体。\n这篇文章叙述的是芋老人和一位相国发迹前后...", "authors": ["袁世硕"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8b911759740c9ca337", "shortContent": "月白风清之夜，一群容华绝代的少女在步月赏胜的兴头上推开一家宅门，想借院中的藤架赏月饮酒，并主动邀请男主人偕饮同乐。这位男子却闭门不应，疑心她们非妖即鬼，担心为其所惑。扔去一块石头，冲散了她们的宴席。就是这样一个小品式的故事，倏然而来，忽然而去。对故事中这群少女的真实身份不作任何交代，对那位男主人公张庾的行为也不作任何评论。仿佛是不经意地叙述了这样一个故事。但细加品味，却会感到这种客观描写另有一种雋...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9403572034f65b5dd0", "shortContent": "鬼为人祟，志怪小说中多有描叙，然而，假借鬼魅陷害他人，欲置人于死地，其用心险恶，真是人不如鬼了。本文中的老僧就是这样一个人不如鬼的家伙。\n大约是出于僧道两家的不同信仰，也可能出于僧家对道家的偏见，双塔寺老僧一出场便有一种咄咄逼人之势。叶道士作礼问讯，求宿寺下，却被怒骂一番。不留宿也就算了，老和尚却想出更恶毒的主意，想借助鬼魅杀死无辜的道士。老和尚虽然只出场一次，话语只有一句，可是其险恶的用心尽在幕...", "authors": ["陈建生"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3faa0ce818559d071296", "shortContent": "本篇通过一个荒诞的故事，揭露了封建社会中地主豪绅鱼肉乡民，欺凌残害老百姓的严酷现实，希冀有救世主出现，为人民制裁这些土豪劣绅。\n文中的庄姓武士，从外貌到言行，十足一副土豪劣绅的丑恶嘴脸。他外表“气象猛厉”，使人望而生畏；他态度傲慢，趾高气扬，“岸然”地来到以教书为生的屠秀才家；他说话盛气凌人，语言斩钉截铁，不容人有商量的余地；他倏地把干鹿肉扔在桌子上，一声“不要推却”，头也不回地出门扬长而去。在庄...", "authors": ["储有明"], "pressName": "上海辞书出版社"}]', '', 'indent', 1524825915, '5ae28e9f9f545400437d5931', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637384, '笠翁对韵 · 下卷 · 十三覃', NULL, 3, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '宫对阙，座对龛。水北对天南。蜃楼对蚁郡，伟论对高谈。遴杞梓，树楩楠。得一对函三。八宝珊瑚枕，双珠玳瑁簪。萧王待士心惟赤，卢相欺君面独蓝。贾岛诗狂，手拟敲门行处想；张颠草圣，头能濡墨写时酣。
闻对见，解对谙。三橘对双柑。黄童对白叟，静女对奇男。秋七七，径三三。海色对山岚。鸾声何哕哕，虎视正眈眈。仪封疆吏知尼父，函谷关人识老聃。江相归池，止水自盟真是止；吴公作宰，贪泉虽饮亦何贪。', '', '蜃楼：宋苏轼仕登州，作文祷海，而见海市蜃楼。　蚁郡：《南柯太守传》传奇，淳于棼梦入槐下蚁国，蚁王纳为婿，封南柯郡。　得一：《老子本义．下篇》：“天得一以清，地得一以宁，神得一以灵……”萧王：更始二年，刘玄遣侍御史持节立光武为萧王。　卢相：唐代奸相卢杞，貌蓝而心险，人称蓝面鬼。　敲门：《唐诗纪事》：贾岛赴举至京，骑驴赋诗，得“僧推月下门”之句，欲改“推”作“敲”，引手作推敲之势。濡墨：唐张旭善草书，醉后以头濡墨作狂草。人称其为张颠。', '', NULL, '', 'indent', 1524738871, '5ae13ab6ee920a67f6f5427c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637385, '笠翁对韵 · 下卷 · 十四盐', NULL, 2, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '宽对猛，冷对炎。清直对尊严。云头对雨脚，鹤发对龙髯。风台谏，肃堂廉。保泰对鸣谦。五湖归范蠡，三径隐陶潜。一剑成功堪佩印，百钱满卦便垂帘。浊酒停杯，容我半酣愁际饮；好花傍座，看他微笑悟时拈。
连对断，减对添。淡泊对安恬。回头对极目，水底对山尖。腰袅袅，手纤纤。凤卜对鸾占。开田多种粟，煮海尽成盐。居同九世张公艺，恩给千人范仲淹。箫弄凤来，秦女有缘能跨羽；鼎成龙去，轩臣无计得攀髯。
人对己，爱对嫌。举止对观瞻。四知对三语，义正对辞严。勤雪案，课风檐。漏箭对书笺。文繁归獭祭，体艳别香奁。昨夜题梅更一字，早春来燕卷重帘。诗以史名，愁里悲歌怀杜甫；笔经人索，梦中显晦老江淹。', '', '风台谏：风，厉也。台，台省。谏，谏臣。　肃堂廉：廉，阶陛之侧隅也。西汉贾谊《治安策》：“人主如堂，人臣如陛，众庶如地。”范蠡：字少伯，越国大夫。佐越王勾践破吴。成功后，载西施隐入五湖。　一剑：战国时苏秦尝佩一剑，说六国连横，终佩六国相印。　百钱：汉严遵，字君平，卖卜成都，每日得百钱，即闭户垂帘收市。　微笑：释迦佛拈花示众，独迦叶一人微笑，世尊乃付以正法。
张公：唐张公艺，九世同堂而居。高宗幸其第，问何以能如此？公书百“忍”字以进之。范仲淹：宋代大臣，谥文正，施义粜以养宗族。攀髯：传说轩辕皇帝铸鼎成，龙降，骑之上升。其臣攀龙髯欲随之升天，未得。
四知：即杨震四知，见前注。　三语：晋王戎问阮瞻，老子、孔子之道若何？曰：“将无同。”时人谓之三语掾。獭祭：唐李商隐作诗文，多拣阅书册，左右鳞次，号为獭祭鱼。香奁：唐韩偓好作艳诗，诗集名《香奁集》。人称香奁体。　更一字：唐僧齐己题梅花诗曰：“昨夜数枝开”。郑谷改为“一枝开”，时人称为一字师。诗史：唐杜甫，感痛时事，发之为诗，人称“诗史”。　笔索：《南史．江淹传》载，江淹尝宿于冶亭，梦一丈夫自称郭璞，谓淹曰：“吾有笔在卿处多年，可以见还。”淹乃探怀中得五色笔一以授之。此后文思枯竭，人谓江郎才尽。', '', NULL, '', 'indent', 1524738931, '5ae13af2ee920a25e88f932e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637386, '笠翁对韵 · 下卷 · 十五咸', NULL, 4, 63, 0, 1, '李渔', NULL, 10370, '57b9e802c4c9710061497a4b', '清', 'wen', '文', '', '', '栽对植，薙对芟。二伯对三监。朝臣对国老，职事对官衔。鹿麌麌，兔毚毚。启牍对开缄。绿杨莺睍睆，红杏燕呢喃。半篱白酒娱陶令，一枕黄粱度吕岩。九夏炎飙，长日风亭留客骑；三冬寒冽，漫天雪浪驻征帆。
梧对竹，柏对杉。夏濩对韶咸。涧瀍对溱洧，巩洛对崤函。藏书洞，避诏岩。脱俗对超凡。贤人羞献媚，正士嫉工谗。霸越谋臣推少伯，佐唐藩将重浑瑊。邺下狂生，羯鼓三挝羞锦袄；江州司马，琵琶一曲湿青衫。
袍对笏，履对衫。匹马对孤帆。琢磨对雕镂，刻划对镌镵。星北拱，日西衔。卮漏对鼎馋。江边生桂若，海外树都咸。但得恢恢存利刃，何须咄咄达空函。彩凤知音，乐典后夔须九奏；金人守口，圣如尼父亦三缄。', '', '麌麌：兽群聚集貌。《诗经．小雅．吉日》：“兽之所同，麀麀麌麌。”　兔毚毚：《诗经．小雅．巧言》：“跃跃毚兔，遇犬护之。”注：毚兔，狡兔也，喻谗人。
利刃：《庄子．养生主》：“庖丁为文惠君解牛。……恢恢乎其于游刃必有余地矣。”此即为“庖丁解牛”和“游刃有余”二成语之出典。　空函：《世说新语．黜免》载，晋代殷浩被废，在信安，终日恒书空作字，扬州吏民寻义逐之。窃视，惟作“咄咄怪事”四字而已。九奏：奏乐九曲。《书．益稷》：“箫韶九成，凤凰来仪。”注：“备乐九奏而致凤凰”。　三缄：三缄其口，见前注。', '', NULL, '', 'indent', 1524738969, '5ae13b17ac502e2713d0a708', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637396, '庄子 · 外篇 · 马蹄', NULL, 4, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E5%A4%96%E7%AF%87%C2%B7%E9%A9%AC%E8%B9%84/10180735?fr=aladdin', '', '马，蹄可以践霜雪，毛可以御风寒，龁草饮水，翘足而陆，此马之真性也。虽有义台路寝，无所用之。及至伯乐，曰：“我善治马。”烧之，剔之，刻之，雒之，连之以羁馽，编之以皂栈，马之死者十二三矣；饥之，渴之，驰之，骤之，整之，齐之，前有橛饰之患，而后有鞭策之威，而马之死者已过半矣。陶者曰：“我善治埴，圆者中规，方者中矩。”匠人曰：“我善治木，曲者中钩，直者应绳。”夫埴木之性，岂欲中规矩钩绳哉？然且世世称之曰“伯乐善治马”而“陶匠善治埴木”，此亦治天下者之过也。
吾意善治天下者不然。彼民有常性，织而衣，耕而食，是谓同德；一而不党，命曰天放。故至德之世，其行填填，其视颠颠。当是时也，山无蹊隧，泽无舟梁；万物群生，连属其乡；禽兽成群，草木遂长。是故禽兽可系羁而游，鸟鹊之巢可攀援而窥。
夫至德之世，同与禽兽居，族与万物并。恶乎知君子小人哉！同乎无知，其德不离；同乎无欲，是谓素朴。素朴而民性得矣。及至圣人，蹩躠为仁，踶跂为义，而天下始疑矣。澶漫为乐，摘辟为礼，而天下始分矣。故纯朴不残，孰为牺尊！白玉不毁，孰为珪璋！道德不废，安取仁义！性情不离，安用礼乐！五色不乱，孰为文采！五声不乱，孰应六律！夫残朴以为器，工匠之罪也；毁道德以为仁义，圣人之过也。
夫马，陆居则食草饮水，喜则交颈相靡，怒则分背相踶。马知已此矣！夫加之以衡扼，齐之以月题，而马知介倪、闉扼、鸷曼、诡衔、窃辔。故马之知而能至盗者，伯乐之罪也。
夫赫胥氏时，民居不知所为，行不知所之，含哺而熙，鼓腹而游。民能以此矣！及至圣人，屈折礼乐以匡天下之形，县跂仁义以慰天下之心，而民乃始踶跂好知，争归于利，不可止也。此亦圣人之过也。', '本篇表现了庄子反对束缚和羁绊，提倡一切返归自然的政治主张。在庄子的眼里，当世社会的纷争动乱都源于所谓圣人的“治”，因而他主张摒弃仁义和礼乐，取消一切束缚和羁绊，让社会和事物都回到它的自然和本性上去。文章对于仁义、礼乐的虚伪性、蒙蔽性揭露是深刻的。', '龁（hé）：咬嚼。
翘（qiáo）：扬起。陆：通作踛（lù），跳跃。
义（é）：通“峨”，“义台”即高台。路：大，正；寝：居室。
伯乐：姓孙名阳，伯乐为字，秦穆公时人，相传善于识马、驯马。
烧之：指烧红铁器灼炙马毛。
剔之：指剪剔马毛。
刻之：指凿削马蹄甲。
雒（luò）之：“雒”通作“烙”，指用烙铁留下标记。
连：系缀，连结。羁（jī）：马络头。？（zhì）：绊马脚的绳索。
皂（zào）：饲马的槽枥。栈：安放在马脚下的编木，用以防潮，俗称马床。
十二三：十分之二三。
驰：马快速奔跑；下句“骤”字同此义。“驰之”、“骤之”，意指打马狂奔，要求马儿速疾奔跑。
整：整齐划一；下句“齐”字同此义。“整之”、“齐之”，意指使马儿步伐、速度保持一致。
橛（jué）：马口所衔之木，今用铁制，谓马口铁。饰：指马络头上的装饰。
策：“策”字的异体。马鞭用皮制成叫鞭，用竹制成就叫“策”。
埴（zhí）：粘土。
称：称举，赞扬。
常性：一定的规律。天有常性，人有常顺。
党：成玄英疏：“党，偏也”。
天放：放任自然。成玄英疏：“直置放任，则物皆自足，故名曰天放也”。
填填：稳重貌。
颠颠：专注貌。成玄英疏：“填填，满足之心。颠颠，高直之貌……所以守真内足，填填而处无为；自不外求，颠颠而游於虚淡”。
同乎无知，其德不高；同乎无欲，是为素朴：人人都蠢笨而无智慧，人类的本能和天性也就不会丧失；人人都愚昧而无私欲，这就叫做“素”和“朴”。
蹩躠：《辞源》注为biésǎ，《古汉语常用字字典》注为biéxuè。尽心用力貌。
踶跂：读音dìqí，用尽心力，勉力行之的样子。
澶漫：chánmàn，宽长貌；广远貌。
牺尊：牺是古代宗庙祭祀用的纯色牲，牲就是牛，因而也可称为纯色牛；尊，同“樽”，是古代盛酒的礼器。
相靡：相继分散；递相消失。
相踶：互踢，成玄英疏：“踶，蹈也”。
衡扼：衡、轭是同义词，是驾在牲口脖子上、并与辕相连的部件。
月题：马额上的佩饰，其形似月。
介倪、闉扼、鸷曼、诡衔、窃辔：束缚马的器具。
赫胥氏：中国古代传说中的部落首领，后人追尊他为帝王。
含哺而熙，鼓腹而游：哺：口中所含的食物；熙：游戏；鼓腹：鼓起肚子，即饱食。口含食物，手拍肚子。形容太平时代无忧无虑的生活。
县跂：悬挂于高处而令人仰慕。', '马，蹄可以用来践踏霜雪，毛可以用来抵御风寒，饿了吃草，渴了喝水，性起时扬起蹄脚奋力跳跃，这就是马的天性。即使有高台正殿，对马来说没有什么用处。等到世上出了伯乐，说：“我善于管理马。”于是用烧红的铁器灼炙马毛，用剪刀修剔马鬃，凿削马蹄甲，烙制马印记，用络头和绊绳来拴连它们，用马槽和马床来编排它们，这样一来马便死掉十分之二三了。饿了不给吃，渴了不给喝，让它们快速驱驰，让它们急骤奔跑，让它们步伐整齐，让它们行动划一，前有马口横木和马络装饰的限制，后有皮鞭和竹条的威逼，这样一来马就死过半数了。制陶工匠说：“我最善于整治粘土，我用粘土制成的器皿，圆的合乎圆规，方的应于角尺。”木匠说：“我最善于整治木材，我用木材制成的器皿，能使弯曲的合于钩弧的要求，笔直的跟墨线吻合。”粘土和木材的本性难道就是希望去迎合圆规、角尺、钩弧、墨线吗？然而还世世代代地称赞他们说，“伯乐善于管理马”而“陶匠、木匠善于整治粘土和木材”，这也就是治理天下的人的过错啊！我认为善于治理天下的人就不是这样。黎民百姓有他们固有不变的本能和天性，织布而后穿衣，耕种而后吃饭，这就是人类共有的德行和本能。人们的思想和行为浑然一体没有一点儿偏私，这就叫做任其自然。所以上古人类天性保留最完善的时代，人们的行动总是那么持重自然，人们的目光又是那么专一而无所顾盼。正是在这个年代里，山野里没有路径和隧道，水面上没有船只和桥梁，各种物类共同生活，人类的居所相通相连而没有什么乡、县差别，禽兽成群结队，草木遂心地生长。因此禽兽可以用绳子牵引着游玩，鸟鹊的巢窠可以攀登上去探望。在那人类天性保留最完善的年代，人类跟禽兽同样居住，跟各种物类相互聚合并存，哪里知道什么君子、小人呢！人人都蠢笨而无智慧，人类的本能和天性也就不会丧失；人人都愚昧而无私欲，这就叫做“素”和“朴”。能够像生绢和原木那样保持其自然的本色，人类的本能和天性就会完整地留传下来。
等到世上出了圣人，勉为其难地去倡导所谓仁，竭心尽力地去追求所谓义，于是天下开始出现迷惑与猜疑。放纵无度地追求逸乐的曲章，繁杂琐碎地制定礼仪和法度，于是天下开始分离了。所以说，原木没被分割，谁还能用它雕刻为酒器！一块白玉没被破裂，谁还能用它雕刻出玉器！人类原始的自然本性不被废弃，哪里用得着仁义！人类固有的天性和真情不被背离，哪里用得着礼乐！五色不被错乱，谁能够调出文彩！五声不被搭配，谁能够应和六律！分解原木做成各种器皿，这是木工的罪过，毁弃人的自然本性以推行所谓仁义，这就是圣人的罪过！
再说马，生活在陆地上，吃草饮水，高兴时颈交颈相互摩擦，生气时背对背相互踢撞，马的智巧就只是这样了。等到后来把车衡和颈轭加在它身上，把配着月牙形佩饰的辔头戴在它头上，那么马就会侧目怒视，僵着脖子抗拒轭木，暴戾不驯，或诡谲地吐出嘴里的勒口，或偷偷地脱掉头上的马辔。所以，马的智巧竟能做出与人对抗的态度，这完全是伯乐的罪过。上古赫胥氏的时代，黎民百姓居处不知道做些什么，走动也知道去哪里，口里含着食物嬉戏，鼓着吃饱的肚子游玩，人们所能做的就只是这样了。等到圣人出现，矫造礼乐来匡正天下百姓的形象，标榜不可企及的仁义来慰藉天下百姓的心，于是人们便开始千方百计地去寻求智巧，争先恐后地去竞逐私利，而不能终止。这也是圣人的罪过啊！', NULL, '', 'indent', 1524825219, '5ae28c01fe88c2003819fd55', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637397, '庄子 · 外篇 · 胠箧', NULL, 4, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E5%A4%96%E7%AF%87%C2%B7%E8%83%A0%E7%AE%A7/10181076', '', '将为胠箧探囊发匮之盗而为守备，则必摄缄縢，固扃谲，此世俗之所谓知也。然而巨盗至，则负匮揭箧担囊而趋，唯恐缄縢扃谲之不固也。然则乡之所谓知者，不乃为大盗积者也？
故尝试论之：世俗之所谓知者，有不为大盗积者乎？所谓圣者，有不为大盗守者乎？何以知其然邪？昔者齐国邻邑相望，鸡狗之音相闻，罔罟之所布，耒耨之所刺，方二千余里。阖四竟之内，所以立宗庙社稷，治邑屋州闾乡曲者，曷尝不法圣人哉？然而田成子一旦杀齐君而盗其国，所盗者岂独其国邪？并与其圣知之法而盗之，故田成子有乎盗贼之名，而身处尧舜之安。小国不敢非，大国不敢诛，十二世有齐国，则是不乃窃齐国并与其圣知之法以守其盗贼之身乎？
尝试论之：世俗之所谓至知者，有不为大盗积者乎？所谓至圣者，有不为大盗守者乎？何以知其然邪？昔者龙逢斩，比干剖，苌弘胣，子胥靡。故四子之贤而身不免乎戮。故跖之徒问于跖曰：“盗亦有道乎？”跖曰：“何适而无有道邪？夫妄意室中之藏，圣也；入先，勇也；出后，义也；知可否，知也；分均，仁也。五者不备而能成大盗者，天下未之有也。”由是观之，善人不得圣人之道不立，跖不得圣人之道不行。天下之善人少而不善人多，则圣人之利天下也少而害天下也多。故曰：唇竭则齿寒，鲁酒薄而邯郸围，圣人生而大盗起。掊击圣人，纵舍盗贼，而天下始治矣。
夫川竭而谷虚，丘夷而渊实。圣人已死，则大盗不起，天下平而无故矣！圣人不死，大盗不止。虽重圣人而治天下，则是重利盗跖也。为之斗斛以量之，则并与斗斛而窃之；为之权衡以称之，则并与权衡而窃之；为之符玺以信之，则并与符玺而窃之；为之仁义以矫之，则并与仁义而窃之。何以知其然邪？彼窃钩者诛，窃国者为诸侯，诸侯之门而仁义存焉，则是非窃仁义圣知邪？故逐于大盗，揭诸侯，窃仁义并斗斛权衡符玺之利者，虽有轩冕之赏弗能劝，斧钺之威弗能禁。此重利盗跖而使不可禁者，是乃圣人之过也。
故曰：“鱼不可脱于渊，国之利器不可以示人。”彼圣人者，天下之利器也，非所以明天下也。故绝圣弃知，大盗乃止；掷玉毁珠，小盗不起；焚符破玺，而民朴鄙；掊斗折衡，而民不争；殚残天下之圣法，而民始可与论议；擢乱六律，铄绝竽瑟，塞瞽旷之耳，而天下始人含其聪矣；灭文章，散五采，胶离朱之目，而天下始人含其明矣。毁绝钩绳而弃规矩，攊攦工倕之指，而天下始人有其巧矣。故曰：大巧若拙。削曾、史之行，钳杨、墨之口，攘弃仁义，而天下之德始玄同矣。彼人含其明，则天下不铄矣；人含其聪，则天下不累矣；人含其知，则天下不惑矣；人含其德，则天下不僻矣。彼曾、史、杨、墨、师旷、工倕、离朱者，皆外立其德而爚乱天下者也，法之所无用也。
子独不知至德之世乎？昔者容成氏、大庭氏、伯皇氏、中央氏、栗陆氏、骊畜氏、轩辕氏、赫胥氏、尊卢氏、祝融氏、伏羲氏、神农氏，当是时也，民结绳而用之。甘其食，美其服，乐其俗，安其居，邻国相望，鸡狗之音相闻，民至老死而不相往来。若此之时，则至治已。今遂至使民延颈举踵，曰“某所有贤者”，赢粮而趣之，则内弃其亲而外去其主之事，足迹接乎诸侯之境，车轨结乎千里之外。则是上好知之过也！
上诚好知而无道，则天下大乱矣！何以知其然邪？夫弓弩毕弋机变之知多，则鸟乱于上矣；钩饵罔罟罾笱之知多，则鱼乱于水矣；削格罗落罘罝之知多，则兽乱于泽矣；知诈渐毒、颉滑坚白、解垢同异之变多，则俗惑于辩矣。故天下每每大乱，罪在于好知。故天下皆知求其所不知而莫知求其所已知者，皆知非其所不善而莫知非其所已善者，是以大乱。故上悖日月之明，下烁山川之精，中堕四时之施，惴耎之虫，肖翘之物，莫不失其性。甚矣，夫好知之乱天下也！自三代以下者是已！舍夫种种之机而悦夫役役之佞；释夫恬淡无为而悦夫啍啍之意，啍啍已乱天下矣！', '全篇大体分成三个部分。第一部分至“而天下始治矣”，从讨论各种防盗的手段最终都会被盗贼所利用入手，指出当时治天下的主张和办法，都是统治者、阴谋家的工具，着力批判了“仁义”和“礼法”。第二部分至“法之所无用也”，进一步提出摒弃一切社会文化的观点，使“绝圣”的主张和“弃知”的思想联系在一起。余下为第三部分，通过对比“至德之世”与“三代以下”的治乱，表达缅怀原始社会的政治主张。', '胠箧：（qūqiè）释义为撬开箱箧，后亦用为盗窃的代称。也指撬开箱子，打开箱子。', '为了对付撬箱子、掏口袋、开柜子的小偷而做防范准备，必定要收紧绳结、加固插闩和锁钥，这就是一般人所说的聪明作法。可是一旦大强盗来了，就背着柜子、扛着箱子、挑着口袋快步跑了，唯恐绳结、插闩与锁钥不够牢固哩。既然是这样，那么先前所谓的聪明作法，不就是给大盗作好了积聚和储备吗？所以我曾试图讨论这种情况，世俗所谓的聪明人，有不替大盗积聚财物的吗？所谓的圣人，有不替大盗守卫财物的吗？
怎么知道是这样的呢？当年的齐国，邻近的村邑遥遥相望，鸡狗之声相互听闻，鱼网所撒布的水面，犁锄所耕作的土地，方圆两千多里。整个国境之内，所有用来设立宗庙、社稷的地方，所有用来建置邑、屋、州、闾、乡、里各级行政机构的地方，何尝不是在效法古代圣人的作法！然而田成子一下子杀了齐国的国君也就窃据了整个齐国。他所盗窃夺取的难道又仅仅只是那样一个齐国吗？连同那里各种圣明的法规与制度也一块儿劫夺去了。而田成子虽然有盗贼的名声，却仍处于尧舜那样安稳的地位，小的国家不敢非议他，大的国家不敢讨伐他，世世代代窃据齐国。那么，这不就是盗窃了齐国并连同那里圣明的法规和制度，从而用来守卫他盗贼之身吗？所以我曾试图讨论这种情况，世俗的所谓聪明人，有不替大盗积聚财物的吗？所谓的圣人，有不替大盗防守财物的吗？
怎么知道是这样的呢？从前龙逢被斩首，比干被剖胸，苌弘被掏肚，子胥被抛尸江中任其腐烂。即使象上面四个人那样的贤能之士，仍不能免于遭到杀戮。因而盗跖的门徒向盗跖问道：“做强盗也有规矩和准绳吗？”盗跖回答说：“到什么地方会没有规矩和准绳呢？准确推测屋里储藏着什么财物，这就是圣明；率先进到屋里，这就是勇敢；最后退出屋子，这就是义气；能知道可否采取行动，这就是智慧；事后分配公平，这就是仁爱。以上五样不能具备，却能成为大盗的人，天下是没有的。”从这一点来看，善人不能通晓圣人之道便不能立业，盗跖不能通晓圣人之道便不能行窃；天下的善人少，而不善的人多，那么圣人给天下带来好处也就少，而给天下带来祸患也就多。所以说：嘴唇向外翻开牙齿就会外露受寒，鲁侯奉献的酒味道淡薄致使赵国都城邯郸遭到围困，圣人出现了因而大盗也就兴起了。抨击圣人，释放盗贼，天下方才能太平无事。
溪水干涸山谷显得格外空旷，山丘夷平深潭显得格外充实。圣人死了，那么大盗也就不会再兴起，天下就太平而没有变故了。圣人不死，大盗也就不会中止。即使让整个社会都重用圣人治理天下，那么这也是让盗跖获得最大的好处。给天下人制定斗、斛来计量物品的多少，那么就连同斗斛一道盗窃走了；给天下人制定秤锤、秤杆来计量物品的轻重，那么就连同秤锤、秤杆一道盗窃走了；给天下人制定符、玺来取信于人，那么就连同符、玺一道盗窃走了；给天下人制定仁义来规范人们的道德和行为，那么就连同仁义一道盗窃走了。怎么知道是这样的呢？那些偷窃腰带环钩之类小东西的人受到刑戮和杀害，而窃夺了整个国家的人却成为诸侯；诸侯之门方才存在仁义。这不就是盗窃了仁义和圣智吗？所以，那些追随大盗、高居诸侯之位、窃夺了仁义以及斗斛、秤具、符玺之利的人，即使有高官厚禄的赏赐不可能劝勉，即使有行刑杀戮的威严不可能禁止。这些大大有利于盗跖而不能使他们禁止的情况，都是圣人的过错。
因此说，鱼儿不能脱离深潭，治国的利器不能随便拿给人看。那些所谓的圣人，就是治理天下的利器，是不可以用来明示天下的。所以，断绝圣人摒弃智慧，大盗就能中止；弃掷玉器毁坏珠宝，小的盗贼就会消失；焚烧符记破毁玺印，百姓就会朴实浑厚；打破斗斛折断秤杆，百姓就会没有争斗；尽毁天下的圣人之法，百姓方才可以谈论是非和曲直。搅乱六律，毁折各种乐器，并且堵住师旷的耳朵，天下人方能保全他们原本的听觉；消除纹饰，离散五彩，粘住离朱的眼睛，天下人方才能保全他们原本的视觉；毁坏钩弧和墨线，抛弃圆规和角尺，弄断工倕的手指，天下人方才能保有他们原本的智巧。因此说：“最大的智巧就好像是笨拙一样。”削除曾参、史䲡的忠孝，钳住杨朱、墨翟善辩的嘴巴，摒弃仁义，天下人的德行方才能混同而齐一。人人都保有原本的视觉，那么天下就不会出现毁坏；人人都保有原本的听觉，那么天下就不会出现忧患；人人都保有原本的智巧，那么天下就不会出现迷惑；人人都保有原本的秉性，那么天下就不会出现邪恶。那曾参、史䲡、杨朱、墨翟、师旷、工倕和离朱，都外露并炫耀自己的德行，而且用来迷乱天下之人，这就是圣治之法没有用处的原因。
你唯独不知道那盛德的时代吗？从前容成氏、大庭氏、伯皇氏、中央氏、栗陆氏、骊畜氏、轩辕氏、赫胥氏、尊卢氏、祝融氏、伏羲氏、神农氏，在那个时代，人民靠结绳的办法记事，把粗疏的饭菜认作美味，把朴素的衣衫认作美服，把纯厚的风俗认作欢乐，把简陋的居所认作安适，邻近的国家相互观望，鸡狗之声相互听闻，百姓直至老死也互不往来。像这样的时代，就可说是真正的太平治世了。可是当今竟然达到使百姓伸长脖颈踮起脚跟说，“某个地方出了圣人”，于是带着干粮急趋而去，家里抛弃了双亲，外边离开了主上的事业，足迹交接于诸侯的国境，车轮印迹往来交错于千里之外，而这就是统治者追求圣智的过错。统治者一心追求圣智而不遵从大道，那么天下必定会大乱啊！
怎么知道是这样的呢？弓弩、鸟网、弋箭、机关之类的智巧多了，那么鸟儿就只会在空中扰飞；钩饵、鱼网、鱼笼之类的智巧多了，那么鱼儿就只会在水里乱游；木栅、兽栏、兽网之类的智巧多了，那么野兽就只会在草泽里乱窜；伪骗欺诈、奸黠狡猾、言词诡曲、坚白之辩、同异之谈等等权变多了，那么世俗的人就只会被诡辩所迷惑。所以天下昏昏大乱，罪过就在于喜好智巧。所以天下人都只知道追求他所不知道的，却不知道探索他所已经知道的；都知道非难他所认为不好的，却不知道否定他所已经赞同的，因此天下大乱。所以对上而言遮掩了日月的光辉，对下而言销解了山川的精华，居中而言损毁了四时的交替，就连附生地上蠕动的小虫，飞在空中的蛾蝶，没有不丧失原有真性的。追求智巧扰乱天下，竟然达到如此地步！自夏、商、周三代以来的情况就是这样啊，抛弃那众多淳朴的百姓，而喜好那钻营狡诈的谄佞小人；废置那恬淡无为的自然风尚，喜好那碟碟不休的说教。碟碟不休的说教已经搞乱了天下啊！', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d12e6a6b501f968545", "shortContent": "本文选自《庄子·外篇》。一般认为《外篇》中的文章多是庄子后学所作，但综观此篇的观点，仍出于庄子，其文风亦与庄子所作一致。《胠箧》是取首句中二字作为题目。这里节选其主要部分（最后部分未选）。\n庄子生活在战国中期。在各国纷争的局面中，封建阶级关系已大致形成，作为这种新兴势力在意识形态方面的代表，就是当时已成“显学”的儒家学派。儒家与杨朱、墨子、庄子学派相互攻讦，庄子学派尤其拿儒家作为对立面，非议他们所...", "authors": ["方智范"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed20f0f8fda5565061607", "shortContent": "家中蓄狗乃常事，崔述下笔则常中寻异。冉氏狗猛，遇行人则咬。伤人后，主人竟躬诣谢罪，出钱救疗，一而再，再而三，虽苦不堪言，却甘心受累，不忍杀之。这种患而忍之的矛盾心理表明狗因其猛而存，冉氏因狗猛而惜之。不仅主人既患之又爱之，还有个曾被此狗搏咬过的刘位东也如此。刘氏夜归，以柳枝横扫群狗，唯冉氏狗前扑相搏，弄得疲惫不堪，恼怒之极；刘氏自叙，自己且斗且走，离狗很远了，狗“犹望而吠”，即反映对狗的厌恶情绪。...", "authors": ["王政"], "pressName": "上海辞书出版社"}]', '', 'indent', 1524825265, '5ae28c2e9f545400437d47b1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637398, '庄子 · 外篇 · 在宥', NULL, 7, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E5%A4%96%E7%AF%87%C2%B7%E5%9C%A8%E5%AE%A5/10181525', '', '闻在宥天下，不闻治天下也。在之也者，恐天下之淫其性也；宥之也者，恐天下之迁其德也。天下不淫其性，不迁其德，有治天下者哉？昔尧之治天下也，使天下欣欣焉人乐其性，是不恬也；桀之治天下也，使天下瘁瘁焉人苦其性，是不愉也。夫不恬不愉。非德也；非德也而可长久者，天下无之。
人大喜邪，毗于阳；大怒邪，毗于阴。阴阳并毗，四时不至，寒暑之和不成，其反伤人之形乎！使人喜怒失位，居处无常，思虑不自得，中道不成章。于是乎天下始乔诘卓鸷，而后有盗跖、曾、史之行。故举天下以赏其善者不足，举天下以罚其恶者不给。故天下之大不足以赏罚。自三代以下者，匈匈焉终以赏罚为事，彼何暇安其性命之情哉！
而且说明邪，是淫于色也；说聪邪，是淫于声也；说仁邪，是乱于德也；说义邪，是悖于理也；说礼邪，是相于技也；说乐邪，是相于淫也；说圣邪，是相于艺也；说知邪，是相于疵也。天下将安其性命之情，之八者，存可也，亡可也。天下将不安其性命之情，之八者，乃始脔卷獊囊而乱天下也。而天下乃始尊之惜之。甚矣，天下之惑也！岂直过也而去之邪！乃齐戒以言之，跪坐以进之，鼓歌以舞之。吾若是何哉！
故君子不得已而临莅天下，莫若无为。无为也，而后安其性命之情。故贵以身于为天下，则可以托天下；爱以身于为天下，则可以寄天下。故君子苟能无解其五藏，无擢其聪明，尸居而龙见，渊默而雷声，神动而天随，从容无为而万物炊累焉。吾又何暇治天下哉！崔瞿问于老聃曰：“不治天下，安藏人心？”老聃曰：“女慎，无撄人心。人心排下而进上，上下囚杀，淖约柔乎刚强，廉刿雕琢，其热焦火，其寒凝冰，其疾俯仰之间而再抚四海之外。其居也，渊而静；其动也，县而天。偾骄而不可系者，其唯人心乎！昔者黄帝始以仁义撄人之心，尧、舜于是乎股无胈，胫无毛，以养天下之形。愁其五藏以为仁义，矜其血气以规法度。然犹有不胜也。尧于是放灌兜于崇山，投三苗于三峗，流共工于幽都，此不胜天下也。夫施及三王而天下大骇矣。下有桀、跖，上有曾、史，而儒墨毕起。于是乎喜怒相疑，愚知相欺，善否相非，诞信相讥，而天下衰矣；大德不同，而性命烂漫矣；天下好知，而百姓求竭矣。于是乎斤锯制焉，绳墨杀焉，椎凿决焉。天下脊脊大乱，罪在撄人心。故贤者伏处大山嵁岩之下，而万乘之君忧栗乎庙堂之上。今世殊死者相枕也，桁杨者相推也，形戮者相望也，而儒墨乃始离跂攘臂乎桎梏之间。意，甚矣哉！其无愧而不知耻也甚矣！吾未知圣知之不为桁杨椄槢也，仁义之不为桎梏凿枘也，焉知曾、史之不为桀、跖嚆矢也！故曰：绝圣弃知，而天下大治。
黄帝立为天子十九年，令行天下，闻广成子在于空同之上，故往见之，曰：“我闻吾子达于至道，敢问至道之精。吾欲取天地之精，以佐五谷，以养民人。吾又欲官阴阳以遂群生，为之奈何？”广成子曰：“而所欲问者，物之质也；而所欲官者，物之残也。自而治天下，云气不待族而雨，草木不待黄而落，日月之光益以荒矣，而佞人之心剪剪者，又奚足以语至道！”黄帝退，捐天下，筑特室，席白茅，闲居三月，复往邀之。广成子南首而卧，黄帝顺下风膝行而进，再拜稽首而问曰：“闻吾子达于至道，敢问：治身奈何而可以长久？”广成子蹶然而起，曰：“善哉问乎！来，吾语女至道：至道之精，窈窈冥冥；至道之极，昏昏默默。无视无听，抱神以静，形将自正。必静必清，无劳女形，无摇女精，乃可以长生。目无所见，耳无所闻，心无所知，女神将守形，形乃长生。慎女内，闭女外，多知为败。我为女遂于大明之上矣，至彼至阳之原也；为女入于窈冥之门矣，至彼至阴之原也。天地有官，阴阳有藏。慎守女身，物将自壮。我守其一以处其和。故我修身千二百岁矣，吾形未常衰。”黄帝再拜稽首曰：“广成子之谓天矣！”广成子曰：“来！余语女：彼其物无穷，而人皆以为有终；彼其物无测，而人皆以为有极。得吾道者，上为皇而下为王；失吾道者，上见光而下为土。今夫百昌皆生于土而反于土。故余将去女，入无穷之门，以游无极之野。吾与日月参光，吾与天地为常。当我缗乎，远我昏乎！人其尽死，而我独存乎！”
云将东游，过扶摇之枝而适遭鸿蒙。鸿蒙方将拊脾雀跃而游。云将见之，倘然止，贽然立，曰：“叟何人邪？叟何为此？”鸿蒙拊脾雀跃不辍，对云将曰：“游！”云将曰：“朕愿有问也。”鸿蒙仰而视云将曰：“吁！”云将曰：“天气不和，地气郁结，六气不调，四时不节。今我愿合六气之精以育群生，为之奈何？”鸿蒙拊脾雀跃掉头曰：“吾弗知！吾弗知！”云将不得问。又三年，东游，过有宋之野，而适遭鸿蒙。云将大喜，行趋而进曰：“天忘朕邪？天忘朕邪？”
再拜稽首，愿闻于鸿蒙。鸿蒙曰：“浮游不知所求，猖狂不知所往，游者鞅掌，以观无妄。朕又何知！”云将曰：“朕也自以为猖狂，而民随予所往；朕也不得已于民，今则民之放也！愿闻一言。”鸿蒙曰：“乱天之经，逆物之情，玄天弗成，解兽之群而鸟皆夜鸣，灾及草木，祸及止虫。意！治人之过也。”云将曰：“然则吾奈何？”鸿蒙曰：“意！毒哉！仙仙乎归矣！”云将曰：“吾遇天难，愿闻一言。”鸿蒙曰：“意！心养！汝徒处无为，而物自化。堕尔形体，吐尔聪明，伦与物忘，大同乎涬溟。解心释神，莫然无魂。万物云云，各复其根，各复其根而不知。浑浑沌沌，终身不离。若彼知之，乃是离之。无问其名，无窥其情，物固自生。”云将曰：“天降朕以德，示朕以默。躬身求之，乃今得也。”再拜稽首，起辞而行。
世俗之人，皆喜人之同乎己而恶人之异于己也。同于己而欲之，异于己而不欲者，以出乎众为心也。夫以出乎众为心者，曷常出乎众哉？因众以宁所闻，不如众技众矣。而欲为人之国者，此揽乎三王之利而不见其患者也。此以人之国侥幸也。几何侥幸而不丧人之国乎？其存人之国也，无万分之一；而丧人之国也，一不成而万有余丧矣！悲夫，有土者之不知也！夫有土者，有大物也。有大物者，不可以物。物而不物，故能物物。明乎物物者之非物也，岂独治天下百姓而已哉！出入六合，游乎九州，独往独来，是谓独有。独有之人，是之谓至贵。
大人之教，若形之于影，声之于响，有问而应之，尽其所怀，为天下配。处乎无响。行乎无方。挈汝适复之，挠挠以游无端，出入无旁，与日无始。颂论形躯，合乎大同。大同而无己。无己，恶乎得有有。睹有者，昔之君子；睹无者，天地之友。
贱而不可不任者，物也；卑而不可不因者，民也；匿而不可不为者，事也；粗而不可不陈者，法也；远而不可不居者，义也；亲而不可不广者，仁也；节而不可不积者，礼也；中而不可不高者，德也；一而不可不易者，道也；神而不可不为者，天也。故圣人观于天而不助，成于德而不累，出于道而不谋，会于仁而不恃，薄于义而不积，应于礼而不讳，接于事而不辞，齐于法而不乱，恃于民而不轻，因于物而不去。物者莫足为也，而不可不为。不明于天者，不纯于德；不通于道者，无自而可；不明于道者，悲夫！何谓道？有天道，有人道。无为而尊者，天道也；有为而累者，人道也。主者，天道也；臣者，人道也。天道之与人道也，相去远矣，不可不察也。', '《庄子·外篇·在宥》是庄子的作品之一。"在"是自在的意思，"宥"是宽容的意思。反对人为，提倡自然，阐述无为而治的主张就是本篇的主旨。全篇大体分为六个部分。', '在：自在。一说是存，存而不论的意思。宥：宽容。“在宥天下”意思是任天下自在地发展，人和事物均各得其所而相安无事，也就是无为而治。
淫：过，超出。
迁：改变。德：常态，指遵循于“道”的生活规律和处世的基本态度。
欣欣：高高兴兴的样子。乐其性：为其性而乐，意思是为保有真性而欣喜。一说“其”字指代“尧”，跟下句的“其”字指代“桀”一样，亦可通。姑备参考。
恬：静。
瘁瘁：忧愁的样子。苦其性：为其性而苦，为保有真性而苦恼。
毗（ｐí）：损伤。阳：与下句的“阴”本指日光的向背，引伸指气侯上的冷暖，中国古代哲学著作中又借此解释事物对立对应的正反两个侧面。
章：章法，法度。
乔诘：意不平。卓鸷：行不平。“乔诘”和“卓鸷”泛指世上出现的种种不平之事。一说“乔诘”是狡黠诈伪之意，“卓鸷”是卓尔不群之意，可备参考。
匈匈：即“讻讻”，喧嚣吵嚷的样子。
说（ｙｕè）：喜悦，这个意思后代写作“悦”。
淫：沉溺，为之所迷乱。
悖：违背。
相：助。技：技巧，这里指熟悉礼仪。
艺：才能。
疵：毛病，这里指辨别细小的是非。
脔（ｌｕáｎ）卷：拳曲而不舒展的样子。仓（ｃāｎｇ）囊：扰攘纷争的样子。
直：止，仅仅。过：经过。“过也而去之”意思是一代一代地流传下去。
齐（ｚｈāｉ）：通作“斋”。
舞（ｗǔ）：舞。
莅（ｌì）：到，临。“临莅天下”意思是来到从政的地位而治理天下。
“故贵以身于为天下，……爱以身于为天下，……”此两句亦见于《老子》。老庄认为轻身以赴利，弃我而殉物，那么，身且不能安，怎么能治理天下。因此，只有贵身贱利的人才可以托付天下。
五藏：五脏。“无解五藏”意思是，不敞开心中的灵气。
擢（ｚｈｕó）：拔，提升，引申为有意显露。
尸：表示一动不动的样子。“尸居”的意思就是，像受祭的活人那样一动不动地坐着。龙：表示精神腾飞的样子。见（ｘｉàｎ）：显现。“龙见”，意思就是精神里却是腾龙显现。
渊默：意思是像深渊那么默默深沉。雷声：意思是撼人之力就像雷声隆隆。
炊：炊烟。累：游动的尘埃。
崔瞿：虚拟的人名。
藏：乃，“臧”字之讹。“臧”是善的意思。
撄（ｙīｎｇ）：纠缠，扰乱。
排：排斥，压抑。进：推进，提升。“排”和“进”分别喻指不得志之时和得志之时；“下”和“上”则分别指两种心态，即颓丧、消沉和欢欣、气盛。
囚：拘禁。
淖约：柔弱美好的样子。彊（ｑｉáｎｇ）：“强”字之古体。
廉：方正，有棱角，比喻品行端正，不随合世事。刿（ｇｕì）：割伤。雕琢：犹言刻削。
“热”与下句的“寒”分别形容两种截然的心态：情感激动和情绪低落。
疾：快速；这里指心境变化迅速。俛：“俯”字的异体。“俛仰之间”比喻时间短暂。抚：临。
渊：这里是深沉的意思。
偾（ｆèｎ）骄：骄矜而不可禁。系：缀连，这里含有拘绊的意思。
股：大腿。胈（ｂá）：白肉。
胫：小腿。联系上一句，“股无胈”与“胫无毛”都是用来形容劳累奔波的。
五藏：即五脏，这里泛指心胸和思想。
矜：苦。“矜其血气”就是说耗费了无数心血。
三苗：帝尧时代的古国名，地处南方。三峗：又作“三危”，山名，地处西北。
共工：帝尧的水官。幽都：即幽州，地处北方。
施（ｙì）：延续。三王：即夏、商、周三代。骇：惊骇。
大德：指人的基本观念和生活态度。
竭：尽；“求竭”指永远不能满足。一说“求竭”即“纠葛”，与上句之“烂漫”对文。姑备参考。
釿（ｊīｎ）：“斤”字之异体，即横口之斧。
杀：疑为“设”字之误，处置的意思。“杀”，繁体写作“殺”。
椎凿：穿孔的工具。决：打穿，引伸指刑戮、处决。以上“釿锯”、“绳墨”、“椎凿”都是木匠的工具，借指伤害人和约束人的刑法和礼义。
脊脊：相互践踏的样子。一说是淆乱的意思。
伏处：隐居。嵁（ｋāｎ）岩：深谷。
乘（ｓｈèｎｇ）：古代一车四马为一乘。“万乘之君”指能统驭上万辆战车的国君，即大国的国君；这里泛指居于统治地位的诸侯。
殊：断。“殊死”也就是斩首。
桁（ｈáｎｇ）杨：加在被囚禁者颈上和脚上的刑具。相推：一个挨着一个。
离跂（ｑí）：奋力的样子。攘臂：举臂。桎（ｚｈì）梏（ｇù）：脚镣手铐，用于拘系罪犯刑具，这里喻指用来束缚人的真情本性的工具。
椄（jiē）槢（ｘí）：“槢”通作“楔”；“椄槢”就是连接脚镣或手铐左右两部分的插木。
凿：孔。枘（ｒｕì）：榫头，即插入孔中的木拴。
嚆（ｈāｏ）：吼。“嚆矢”即响箭，这里含有导向、先导的意思。
黄帝：轩辕氏，相传为中原部族的祖先。
广成子：传说即老子，实为虚构的人物。空同：亦作崆峒，神话中的山名。佐：辅助。“佐五谷”即帮助五谷生长。
官：用如动词，管、主宰的意思。
遂：顺应，顺着。
质：正，本质。
残：余剩，残损。
族：聚集。雨：用如动词，指下雨。
益：渐渐。荒：迷乱，晦暗。
佞人：谗谄的小人。剪剪：心地狭劣。
捐：弃置。
筑特室：指为了避喧嚣而另辟静室。
席：铺。白茅：古代祭祀时用于缩酒，这里取其洁白的特点，用以表示洁身自好。
间居：犹言独处；清心养性，因而杜绝与他人来往。
遨：请，求教。
南首：头朝南。
下风：下方。
膝行：意思是用膝盖着地而行。
稽首：叩头至地。
蹶（ｇｕì）然：急遽的样子。
窈窈（ｙǎｏ）冥冥：深远昏暗的样子。
昏昏默默：晦暗沉寂的样子。
抱神：持守精神。
内：内心，精神世界。“慎女内”即持守心思，摒弃思虑的意思。
外：人体外在的感受器官，如眼和耳。“闭女外”就是封闭住你的感受器官，即“无视无听”的意思。
遂：顺，引申为达到。
前一“至”字是动词，去到的意思；后一“至”字是形容词，极的意思。
藏：府，居所。
一：浑一，这里实指“道”。和：指阴、阳调谐。
未常：疑是“未尝”之误。
“百”，言其多；“百昌”就是说万物昌盛。
参：同。
当我：向着我而来。
缗（ｍíｎ）：泯合。一说不在意，不放在心上的意思。
远我：背着我而去。与上句之“当我”对文。
昬（ｍíｎ）：昏暗。一说同“缗”，也是不在意的意思。
云将：云的主帅。
扶摇：神木；一说为飓风。鸿蒙：自然的元气。“鸿蒙”跟“云将”一样，均已拟人化，成为寓言中的人物。
拊（ｆǔ）：拍击。脾：当作“髀”，大腿。雀跃：像小雀一样跳跃。
倘然：惊疑的样子。
贽（ｚｈì）然：站立不动的样子。
辍（ｚｈｕò）：停止。
朕（ｚｈèｎ）：我，一人称代词。
节：节令；“不节”即不合节令。
有：语助之辞，“有宋”也就是“宋”。
天：这里实指鸿蒙，敬如上天的意思。
猖狂：漫不经心地随意活动。
鞅掌：众多、纷纷攘攘的样子。
妄：虚，不实。“无妄”即真实，现实的存在。
放：依，仿效。
经：本指织物上的纵线，引申为常规，正常序列的意思。
玄天：即指天。
止：亦作“昆”，“止虫”即昆虫。一说“止”是“豸”的意思，“止虫”即豸虫。
毒：这里是受毒害太深的意思。
僊僊（ｘｉāｎ）：“僊”是“仙”字的异体。“僊僊”指轻扬的样子。
心养：养心，即摒弃思虑，清心寂神。
徒：只。
堕（ｈｕī）：通作“隳”，毁弃的意思。
吐：当是“咄”字之讹，“咄”与“黜”同，废弃的意思。“黜”与“隳”相对，“吐”字则不可通。一说“吐”当是“杜”字之误，杜塞的意思；亦可通。姑备参考。
伦：伦理。一说“伦”通作“沦”，沦没，意思是跟外物泯合而一块忘却。
涬（ｘìｎｇ）溟：混混茫茫的自然之气。
莫然：即漠然，像死灰一样没有感知的样子。
云云：众多的样子。
根：这里指固有的真性。
知：感知。
浑浑沌沌：各任自然，浑然无知，保持自然真性的状态。
降：这里是传授、教诲的意思。“降朕以德”即以德降朕，把对待外物和自我所应取的态度传授给我。
默：义同“养心”，即清心寂神的意思。“示朕以默”即以默示朕，把清心寂神的方法晓谕给我。
曷常：即何尝。
因：随顺，顺乎。宁：安。
传统断句把“所闻”列在上句之末，而“因众以宁所闻，不如众技众矣”语不可通，故未从之。
揽：把持，撮起。
有土者：拥有国土的人，指国君。
大物：旧注指至高无尚的人物，疑非是，联系下一句，当从字面讲，“有大物”即拥有万物。
九州：九州所指历来含义不定，这里可以理解为当时中原一带人们熟悉的地域。
独有：指不为外物所拘滞。
大人：即上句的“至贵”的人。
响：回声。
配：匹对，这里指应答；问话者为主，应答者则为匹对。
挈：提。适复：往返。挠挠：纷纷。
旁（ｂàｎｇ）：依。
颂：容。论：语。“颂论”犹言容颜、谈吐。
这句里有两个“有”字，其中前一“有”字是动词，据有、持有的意思；后一“有”字用如名词，指存在着的各种物象，包括自身的形躯。下一句之“有”字则同于本句后一“有”字的用法。
任：任凭，听任。
因：顺应，依随。
法：效法，这里指可以效法的言论。
广：扩大、推展的意思。亲近容易形成偏爱，扩大了亲近的范围也就成为“仁”。
节：礼仪。积：增多。
中：顺。一说获得的意思。
会：合符。恃：依靠。
薄：通作“迫”，接近、靠拢的意思。
讳：回避。
因：循，遵从。', '只听说听任天下安然自在地发展，没有听说要对天下进行治理。听任天下自在地发展，是因为担忧人们超越了原本的真性；宽容不迫各得其所，是因为担忧人们改变了自然的常态。天下人不超越原本的真性，不改变自然的常态，哪里用得着治理天下呢！从前唐尧治理天下，使天下人欣喜若狂人人都为有其真性而欢乐，这就不安宁了；当年夏桀治理天下，使天下人忧心不已人人都为有其真性而痛苦，这就不欢快了。不安宁与不欢快，都不是人们生活和处世的常态。不合于自然的常态而可以长久存在，天下是没有的。
人们过度欢欣，定会损伤阳气；人们过度愤怒，定会损伤阴气。阴与阳相互侵害，四时就不会顺应而至，寒暑也就不会调和形成，这恐怕反倒会伤害自身吧！使人喜怒失却常态，居处没有定规，考虑问题不得要领，办什么事都半途失去章法，于是天下就开始出现种种不平，而后便产生盗跖、曾参、史䲡等各各不同的行为和作法。所以，动员天下所有力量来奖励人们行善也嫌不够，动员天下所有力量来惩戒劣迹也嫌不足，因此天下虽很大仍不足以用来赏善罚恶。自夏、商、周三代以来，始终是喋喋不休地把赏善罚恶当作当政之急务，他们又哪里有心思去安定人的自然本性和真情呢！
而且，喜好目明吗，这是沉溺于五彩；喜好耳聪吗，这是沉溺于声乐；喜好仁爱吗，这是扰乱人的自然常态；喜好道义吗，这是违反事物的常理；喜好礼仪吗，这就助长了繁琐的技巧；喜好音乐吗，这就助长了淫乐；喜好圣智吗，这就助长了技艺；喜好智巧吗，这就助长了琐细之差的争辩。天下人想要安定自然赋予的真情和本性，这八种作法，存留可以，丢弃也可以；天下人不想安定自然赋予的真情和本性，这八种作法，就会成为拳曲不伸、扰攘纷争的因素而迷乱天下了。可是，天下人竟然会尊崇它，珍惜它，天下人为其所迷惑竟达到如此地步！这种种现象岂只是一代一代地流传下来呀！人们还虔诚地谈论它，恭敬地传颂它，欢欣地供奉它，对此我将能够怎么样呢！
所以，君子不得已而居于统治天下的地位，那就不如一切顺其自然。顺其自然方才能使天下人保有人类自然的本性与真情。正因为这样，看重自身甚于看重统驭天下的人，便可以把天下交给他；爱护自身甚于爱护统驭天下之事的人，便可以把天下托付给他。也正因为这样，君子倘能不敞露心中的灵气，不表明自己的才华和智巧，那就会安然不动而精神腾飞，默默深沉而撼人至深，精神活动合乎天理，从容自如顺应自然而万事万物都像炊烟游尘那样自由自在。我又何须分出心思去治理天下啊！
崔瞿子向老聃请教：“不治理天下，怎么能使人心向善？”老聃回答说：“你应谨慎而不要随意扰乱人心。人们的心情总是压抑便消沉颓丧而得志便趾高气扬，不过消沉颓丧或者趾高气扬都象是受到拘禁和伤害一样自累自苦，唯有柔弱顺应能软化刚强。端方而棱角外露容易受到挫折和伤害，情绪激烈时像熊熊大火，情绪低落时像凛凛寒冰。内心变化格外迅速转眼间再次巡游四海之外，静处时深幽宁寂，活动时腾跃高天。骄矜不禁而无所拘系的，恐怕就只是人的内心活动吧！“当年黄帝开始用仁义来扰乱人心，尧和舜于是疲于奔波而腿上无肉、胫上秃毛，用以养育天下众多的形体，满心焦虑地推行仁义，并耗费心血来制定法度。然而他还是未能治理好天下。此后尧将欢兜放逐到南方的崇山，将三苗放逐到西北的三峗，将共工放逐到北方的幽都，这些就是没能治理好天下的明证。延续到夏、商、周三代更是多方面地惊扰了天下的人民，下有夏桀、盗跖之流，上有曾参、史䲡之流，而儒家和墨家的争辩又全面展开。这样一来或喜或怒相互猜疑，或愚或智相互欺诈，或善或恶相互责难，或妄或信相互讥刺，因而天下也就逐渐衰败了；基本观念和生活态度如此不同，人类的自然本性散乱了，天下都追求智巧，百姓中便纷争迭起。于是用斧锯之类的刑具来制裁他们，用绳墨之类的法度来规范他们，用椎凿之类的肉刑来惩处他们。天下相互践踏而大乱，罪在扰乱了人心。因此贤能的人隐居于高山深谷之下，而帝王诸侯忧心如焚战栗在朝堂之上。
当今之世，遭受杀害的人尸体一个压着一个，带着脚镣手铐而坐大牢的人一个挨着一个，受到刑具伤害的人更是举目皆然，而儒家墨家竟然在枷锁和羁绊中挥手舞臂地奋力争辩。唉，真是太过份了！他们不知心愧、不识羞耻竟然达到这等地步！我不知道那所谓的圣智不是脚镣手铐上用作连接左右两部分的插木，我也不明白那所谓的仁义不是枷锁上用作加固的孔穴和木拴，又怎么知道曾参和史䲡之流不是夏桀和盗跖的先导！所以说，‘断绝圣人，抛弃智慧，天下就会得到治理而太平无事’。”
黄帝做了十九年天子，诏令通行天下，听说广成子居住在空同山上，特意前往拜见他，说：“我听说先生已经通晓至道，冒昧地请教至道的精华。我一心想获取天地的灵气，用来帮助五谷生长，用来养育百姓。我又希望能主宰阴阳，从而使众多生灵遂心地成长，对此我将怎么办？”广成子回答说：“你所想问的，是万事万物的根本；你所想主宰的，是万事万物的残留。自从你治理天下，天上的云气不等到聚集就下起雨来，地上的草木不等到枯黄就飘落凋零，太阳和月亮的光亮也渐渐地晦暗下来。然而谗谄的小人心地是那么偏狭和恶劣，又怎么能够谈论大道！”黄帝听了这一席话便退了回来，弃置朝政，筑起清心寂智的静室，铺着洁白的茅草，谢绝交往独居三月，再次前往求教。
广成子头朝南地躺着，黄帝则顺着下方，双膝着地匍匐向前，叩头着地行了大礼后问道：“听说先生已经通晓至道，冒昧地请教，修养自身怎么样才能活得长久？”广成子急速地挺身而起，说：“问得好啊！来，我告诉给你至道。至道的精髓，幽深渺远；至道的至极，晦暗沉寂。什么也不看什么也不听，持守精神保持宁静，形体自然顺应正道。一定要保持宁寂和清静，不要使身形疲累劳苦，不要使精神动荡恍惚，这样就可以长生。眼睛什么也没看见，耳朵什么也没听到，内心什么也不知晓，这样你的精神定能持守你的形体，形体也就长生。小心谨慎地摒除一切思虑，封闭起对外的一切感官，智巧太盛定然招致败亡。我帮助你达到最光明的境地，直达那阳气的本原。我帮助你进入到幽深渺远的大门，直达那阴气的本原。天和地都各有主宰，阴和阳都各有府藏，谨慎地守护你的身形，万物将会自然地成长。我持守着浑一的大道而又处于阴阳二气调谐的境界，所以我修身至今已经一千二百年，而我的身形还从不曾有过衰老。”黄帝再次行了大礼叩头至地说：“先生真可说是跟自然混而为一了！”
广成子又说：“来，我告诉你。宇宙间的事物是没有穷尽的，然而人们却认为有个尽头；宇宙间的事物是不可能探测的，然而人们却认为有个极限。掌握了我所说的道的人，在上可以成为皇帝，在下可以成为王侯；不能掌握我所说的道的人，在上只能见到日月的光亮，在下只能化为土块。如今万物昌盛可都生于土地又返归土地，所以我将离你而去，进入那没有穷尽的大门，从而遨游于没有极限的原野。我将与日月同光，我将与天地共存。向着我而来，我无所觉察！背着我而去，我无所在意！人们恐怕都要死去，而我还独自留下来吗？”
云将到东方巡游，经过神木扶摇的枝旁恰巧遇上了鸿蒙。鸿蒙正拍着大腿像雀儿一样跳跃游乐。云将见鸿蒙那般模样，惊疑地停下来，纹丝不动地站着，说：“老先生是什么人呀！你老先生为什么这般动作？”鸿蒙拍着大腿不停地跳跃，对云将说：“自在地游乐！”云将说：“我想向你请教。”鸿蒙抬起头来看了看云将道：“哎！”云将说：“天上之气不和谐，地上之气郁结了，阴、阳、风、雨、晦、明六气不调和，四时变化不合节令。如今我希望调谐六气之精华来养育众生灵，对此将怎么办？”鸿蒙拍着大腿掉过头去，说：“我不知道！我不知道！”云将得不到回答。
过了三年，云将再次到东方巡游，经过宋国的原野恰巧又遇到了鸿蒙。云将大喜，快步来到近前说：“你老先生忘记了我吗？你老先生忘记了我吗？”叩头至地行了大礼，希望得到鸿蒙的指教。鸿蒙说：“自由自在地遨游，不知道追求什么；漫不经心地随意活动，不知道往哪里去。游乐人纷纷攘攘，观赏那绝无虚假的情景；我又能知道什么！”云将说：“我自以为能够随心地活动，人民也都跟着我走；我不得已而对人民有所亲近，如今却为人民所效仿。我希望能聆听您的一言教诲。”鸿蒙说：“扰乱自然的常规，违背事物的真情，整个自然的变化不能顺应形成。离散群居的野兽，飞翔的鸟儿都夜鸣，灾害波及草木，祸患波及昆虫。唉，这都是治理天下的过错！”云将问：“这样，那么我将怎么办？”鸿蒙说：“唉，你受到的毒害实在太深啊！你还是就这么回去吧。”云将说：“我遇见你实在不容易，恳切希望能听到你的指教。”
鸿蒙说：“唉！修身养性。你只须处心于无为之境，万物会自然地有所变化。忘却你的形体，废弃你的智慧，让伦理和万物一块儿遗忘。混同于茫茫的自然之气，解除思虑释放精神，像死灰一样木然地没有魂灵。万物纷杂繁多，全都各自回归本性，各自回归本性却是出自无心，浑然无知保持本真，终身不得背违；假如有所感知，就是背离本真。不要询问它们的名称，不要窥测它们的实情，万物本是自然地生长。”云将说：“你把对待外物和对待自我的要领传授给我，你把清心寂神的方法晓谕给我；我亲身探求大道，如今方才有所领悟。”叩头至地再次行了大礼，起身告别而去。
世俗人都喜欢别人跟自己相同而讨厌别人跟自己不一样。希望别人跟自己相同，不希望别人跟自己不一样的人，总是把出人头地当作自己主要的内心追求。那些一心只想出人头地的人，何尝又能够真正超出众人呢！随顺众人之意当然能够得到安宁，可是个人的所闻总不如众人的技艺多才智高。希图治理邦国的人，必定是贪取夏、商、周三代帝王之利而又看不到这样做的后患的人。这样做是凭借统治国家的权力贪求个人的侥幸，而贪求个人的侥幸而不至于丧失国家统治权力的又有多少呢！他们中能够保存国家的，不到万分之一，而丧失国家的，自身一无所成而且还会留下许多祸患。可悲呀，拥有土地的统治者是何等的不聪明！
拥有土地的国君，必然拥有众多的物品。拥有众多的物品却不可以受外物所役使，使用外物而不为外物所役使，所以能够主宰天下万物。明白了拥有外物又能主宰外物的人本身就不是物，岂只是治理天下百姓而已啊！这样的人已经能往来于天地四方，游乐于整个世界，独自无拘无束地去，又自由自在地来，这样的人就叫做拥有万物而又超脱于万物。拥有万物而又超脱于万物的人，这就称得上是至高无上的贵人。
至贵之人的教诲，就好像形躯对于身影，传声对于回响。有提问就有应答，竭尽自己所能，为天下人的提问作出应答。处心于没有声响的境界，活动在变化不定的地方，引领着人们往返于纷扰的世界，从而遨游在无始无终的浩渺之境，或出或进都无须依傍，像跟随太阳那样周而复始地没有尽头；容颜、谈吐和身形躯体均和众人一样，大家都是一样也就无所谓自身。无所谓自身，哪里用得着据有各种物象！看到了自身和各种物象的存在，这是过去的君子；看不到自身的各种物象的存在，这就跟永恒的天地结成了朋友。
低贱然而不可不听任的，是万物；卑微然而不可不随顺的，是百姓；不显眼然而不可不去做的，是事情；不周全然而不可不陈述的，是可供效法的言论；距离遥远但又不可不恪守的，是道义；亲近然而不可不扩展的，是仁爱；细末的小节不可不累积的，是礼仪；顺依其性然而不可不尊崇的，是德；本于一气然而不可不变化的，是道；神妙莫测然而不可不顺应的，是自然。所以圣人观察自然的神妙却不去帮助，成就了无暇的修养却不受拘束，行动出于道却不是事先有所考虑，符合仁的要求却并不有所依赖，接近了道义却不积不留，应合礼仪却不回避，接触琐事却不推迟，同于法度而不肆行妄为，依靠百姓而不随意役使，遵循事物变化的规律而不轻率离弃。万事万物均不可强为，但又不可不为。不明白自然的演变和规律，也就不会具备纯正的修养；不通晓道的人，没有什么事情可以办成。不通晓道的人，可悲啊！
什么叫做道？有天道，有人道。无所事事无所作为却处于崇高地位的，这就是天道，事必躬亲有所作为而积劳累苦的，这就是人道。君王就是天道，臣下就是人道。天道跟人道比较，相差实在太远，不能不细加体察。', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf6403572034f65a9828", "shortContent": "中国的酒文化源远流长，影响巨大，恐为任何一种饮食文化所不及。咏酒之作，更是举不胜举，著名的如刘伶《酒德颂》、孟郊《酒德》诗，等等，多颂酒之特殊作用，夸其浇垒块、泄郁积之功效，追求“醉”之境界。如刘伶《酒德颂》说：“有大人先生，以天地为一朝，万期为须臾，日月为扃牖，八荒为庭衢。……止则操卮执觚，动则挈榼提壶，唯酒是务，焉知其余。有贵介公子、搢绅处士，闻吾风声，议其所以，乃奋袂攘襟，怒目切齿，陈说礼法...", "authors": ["尹占华"], "pressName": "上海辞书出版社"}, {"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf70911759740c9bd98c", "shortContent": "此赋的序言说得很明白，这是一篇应物兴感的作品。这种赋首先要求咏物必须生动具体形象，使读者如见其物，如闻其声；其次，必须切合作者的身份或彼时彼地的思想感情，使读者如见其人，感同身受。这篇赋都具备这些特点。\n此赋用序言简要交代了写作背景，写得极为简明扼要而又情韵悠长。孤雁与鹅鹜同侪，随而取食，被人驱逐，又不能振翅远逝。其悲惨使读者恻然伤之，一下子就把读者带入到了同情怜悯的境地。此赋的正文则首先点明作者...", "authors": ["叶", "农"], "pressName": "上海辞书出版社"}]', '', 'indent', 1524825672, '5ae28dc4a22b9d004400f3ca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637399, '庄子 · 外篇 · 天地', NULL, 8, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E5%A4%96%E7%AF%87%C2%B7%E5%A4%A9%E5%9C%B0/10182062', '', '天地虽大，其化均也；万物虽多，其治一也；人卒虽众，其主君也。君原于德而成于天。故曰：玄古之君天下，无为也，天德而已矣。以道观言而天下之君正；以道观分而君臣之义明；以道观能而天下之官治；以道泛观而万物之应备。故通于天地者，德也；行于万物者，道也；上治人者，事也；能有所艺者，技也。技兼于事，事兼于义，义兼于德，德兼于道，道兼于天。故曰：古之畜天下者，无欲而天下足，无为而万物化，渊静而百姓定。《记》曰：「通于一而万事毕，无心得而鬼神服。」
夫子曰：「夫道，覆载万物者也，洋洋乎大哉！君子不可以不刳心焉。无为为之之谓天，无为言之之谓德，爱人利物之谓仁，不同同之之谓大，行不崖异之谓宽，有万不同之谓富。故执德之谓纪，德成之谓立，循于道之谓备，不以物挫志之谓完。君子明于此十者，则韬乎其事心之大也，沛乎其为万物逝也。若然者，藏金于山，藏珠于渊；不利货财，不近贵富；不乐寿，不哀夭；不荣通，不丑穷。不拘一世之利以为己私分，不以王天下为己处显。显则明。万物一府，死生同状。」
夫子曰：「夫道，渊乎其居也，漻乎其清也。金石不得无以鸣。故金石有声，不考不鸣。万物孰能定之！夫王德之人，素逝而耻通于事，立之本原而知通于神，故其德广。其心之出，有物采之。故形非道不生，生非德不明。存形穷生，立德明道，非王德者邪！荡荡乎！忽然出，勃然动，而万物从之乎！此谓王德之人。视乎冥冥，听乎无声。冥冥之中，独见晓焉；无声之中，独闻和焉。故深之又深而能物焉；神之又神而能精焉。故其与万物接也，至无而供其求，时骋而要其宿，大小、长短、修远。」
黄帝游乎赤水之北，登乎昆仑之丘而南望。还归，遗其玄珠。使知索之而不得，使离朱索之而不得，使吃诟索之而不得也。乃使象罔，象罔得之。黄帝曰：「异哉，象罔乃可以得之乎？」
尧之师曰许由，许由之师曰啮缺，啮缺之师曰王倪，王倪之师曰被衣。尧问于许由曰：「啮缺可以配天乎？吾藉王倪以要之。」许由曰：「殆哉，圾乎天下！啮缺之为人也，聪明睿知，给数以敏，其性过人，而又乃以人受天。彼审乎禁过，而不知过之所由生。与之配天乎？彼且乘人而无天。方且本身而异形，方且尊知而火驰，方且为绪使，方且为物絯，方且四顾而物应，方且应众宜，方且与物化而未始有恒。夫何足以配天乎！虽然，有族有祖，可以为众父而不可以为众父父。治，乱之率也，北面之祸也，南面之贼也。」
尧观乎华，华封人曰：「嘻，圣人！请祝圣人，使圣人寿。」尧曰：「辞。」「使圣人富。」尧曰：「辞。」「使圣人多男子。」尧曰：「辞。」封人曰：「寿，富，多男子，人之所欲也。女独不欲，何邪？」尧曰：「多男子则多惧，富则多事，寿则多辱。是三者，非所以养德也，故辞。」封人曰：「始也我以女为圣人邪，今然君子也。天生万民，必授之职。多男子而授之职，则何惧之有？富而使人分之，则何事之有？夫圣人，鹑居而彀食，鸟行而无彰。天下有道，则与物皆昌；天下无道，则修德就闲。千岁厌世，去而上仙，乘彼白云，至于帝乡。三患莫至，身常无殃，则何辱之有？」封人去之，尧随之曰：「请问。」封人曰：「退已！」
尧治天下，伯成子高立为诸侯。尧授舜，舜授禹，伯成子高辞为诸侯而耕。禹往见之，则耕在野。禹趋就下风，立而问焉，曰：「昔尧治天下，吾子立为诸侯。尧授舜，舜授予，而吾子辞为诸侯而耕。敢问其故何也？」子高曰：「昔者尧治天下，不赏而民劝，不罚而民畏。今子赏罚而民且不仁，德自此衰，刑自此立，后世之乱自此始矣！夫子阖行邪？无落吾事！」俋乎耕而不顾。
泰初有无，无有无名。一之所起，有一而未形。物得以生谓之德；未形者有分，且然无间谓之命；留动而生物，物成生理谓之形；形体保神，各有仪则谓之性；性修反德，德至同于初。同乃虚，虚乃大。合喙鸣。喙鸣合，与天地为合。其合缗缗，若愚若昏，是谓玄德，同乎大顺。
夫子问于老聃曰：「有人治道若相放，可不可，然不然。辩者有言曰：‘离坚白，若县寓。’若是则可谓圣人乎？」老聃曰：「是胥易技系，劳形怵心者也。执留之狗成思，猿狙之便自山林来。丘，予告若，而所不能闻与而所不能言：凡有首有趾、无心无耳者众；有形者与无形无状而皆存者尽无。其动止也，其死生也，其废起也，此又非其所以也。有治在人。忘乎物，忘乎天，其名为忘己。忘己之人，是之谓入于天。」
将闾葂见季彻曰：「鲁君谓葂也曰：‘请受教。’辞不获命。既已告矣，未知中否。请尝荐之。吾谓鲁君曰：‘必服恭俭，拔出公忠之属而无阿私，民孰敢不辑！’」季彻局局然笑曰：「若夫子之言，于帝王之德，犹螳螂之怒臂以当车轶，则必不胜任矣！且若是，则其自为处危，其观台多物，将往投迹者众。」将闾葂覤覤然惊曰：「葂也汒若于夫子之所言矣！虽然，愿先生之言其风也。」季彻曰：「大圣之治天下也，摇荡民心，使之成教易俗，举灭其贼心而皆进其独志。若性之自为，而民不知其所由然。若然者，岂兄尧、舜之教民溟涬然弟之哉？欲同乎德而心居矣！」
子贡南游于楚，反于晋，过汉阴，见一丈人方将为圃畦，凿隧而入井，抱瓮而出灌，傦然用力甚多而见功寡。子贡曰：「有械于此，一日浸百畦，用力甚寡而见功多，夫子不欲乎？」为圃者仰而视之曰：「奈何？」曰：「凿木为机，后重前轻，挈水若抽，数如佚汤，其名为槔。」为圃者忿然作色而笑曰：「吾闻之吾师，有机械者必有机事，有机事者必有机心。机心存于胸中则纯白不备。纯白不备则神生不定，神生不定者，道之所不载也。吾非不知，羞而不为也。」子贡瞒然惭，俯而不对。有间，为圃者曰：「子奚为者邪？曰：「孔丘之徒也。」为圃者曰：「子非夫博学以拟圣，于于以盖众，独弦哀歌以卖名声于天下者乎？汝方将忘汝神气，堕汝形骸，而庶几乎！而身之不能治，而何暇治天下乎！子往矣，无乏吾事。」
子贡卑陬失色，顼顼然不自得，行三十里而后愈。其弟子曰：「向之人何为者邪？夫子何故见之变容失色，终日不自反邪？」曰：「始吾以为天下一人耳，不知复有夫人也。吾闻之夫子：事求可，功求成，用力少，见功多者，圣人之道。今徒不然。执道者德全，德全者形全，形全者神全。神全者，圣人之道也。托生与民并行而不知其所之，汒乎淳备哉！功利机巧必忘夫人之心。若夫人者，非其志不之，非其心不为。虽以天下誉之，得其所谓，謷然不顾；以天下非之，失其所谓，傥然不受。天下之非誉无益损焉，是谓全德之人哉！我之谓风波之民。」反于鲁，以告孔子。孔子曰：「彼假修浑沌氏之术者也。识其一，不识其二；治其内而不治其外。夫明白入素，无为复朴，体性抱神，以游世俗之间者，汝将固惊邪？且浑沌氏之术，予与汝何足以识之哉！」
谆芒将东之大壑，适遇苑风于东海之滨。苑风曰：「子将奚之？」曰：「将之大壑。」曰：「奚为焉？」曰：「夫大壑之为物也，注焉而不满，酌焉而不竭。吾将游焉！」苑风曰：「夫子无意于横目之民乎？愿闻圣治。」谆芒曰：「圣治乎？官施而不失其宜，拔举而不失其能，毕见其情事而行其所为，行言自为而天下化。手挠顾指，四方之民莫不俱至，此之谓圣治。」「愿闻德人。」曰：「德人者，居无思，行无虑，不藏是非美恶。四海之内共利之之谓悦，共给之之谓安。怊乎若婴儿之失其母也，傥乎若行而失其道也。财用有余而不知其所自来，饮食取足而不知其所从，此谓德人之容。」「愿闻神人。」曰：「上神乘光，与形灭亡，是谓照旷。致命尽情，天地乐而万事销亡，万物复情，此之谓混溟。」
门无鬼与赤张满稽观于武王之师，赤张满稽曰：「不及有虞氏乎！故离此患也。」门无鬼曰：「天下均治而有虞氏治之邪？其乱而后治之与？」赤张满稽曰：「天下均治之为愿，而何计以有虞氏为！有虞氏之药疡也，秃而施髢，病而求医。孝子操药以修慈父，其色燋然，圣人羞之。至德之世，不尚贤，不使能，上如标枝，民如野鹿。端正而不知以为义，相爱而不知以为仁，实而不知以为忠，当而不知以为信，蠢动而相使不以为赐。是故行而无迹，事而无传。」
孝子不谀其亲，忠臣不谄其君，臣、子之盛也。亲之所言而然，所行而善，则世俗谓之不肖子；君之所言而然，所行而善，则世俗谓之不肖臣。而未知此其必然邪？世俗之所谓然而然之，所谓善而善之，则不谓之道谀之人也！然则俗故严于亲而尊于君邪？谓己道人，则勃然作色；谓己谀人，则怫然作色。而终身道人也，终身谀人也，合譬饰辞聚众也，是终始本末不相坐。垂衣裳，设采色，动容貌，以媚一世，而不自谓道谀；与夫人之为徒，通是非，而不自谓众人也，愚之至也。知其愚者，非大愚也；知其惑者，非不惑也。大惑者，终身不解；大愚者，终身不灵。三人行而一人惑，所适者，犹可致也，惑者少也；二人惑则劳而不至，惑者胜也。而今也以天下惑，予虽有祈向，不可得也。不亦悲乎！
大声不入于里耳，折杨、皇侉，则嗑然而笑。是故高言不止于众人之心；至言不出，俗言胜也。以二缶钟惑，而所适不得矣。而今也以天下惑，予虽有祈向，其庸可得邪！知其不可得也而强之，又一惑也！故莫若释之而不推。不推，谁其比忧！厉之人，夜半生其子，遽取火而视之，汲汲然唯恐其似己也。
百年之木，破为牺尊，青黄而文之，其断在沟中。比牺尊于沟中之断，则美恶有间矣，其于失性一也。跖与曾、史，行义有间矣，然其失性均也。且夫失性有五：一曰五色乱目，使目不明；二曰五声乱耳，使耳不聪；三曰五臭熏鼻，困惾中颡；四曰五味浊口，使口厉爽；五曰趣舍滑心，使性飞扬。此五者，皆生之害也。而杨、墨乃始离跂自以为得，非吾所谓得也。夫得者困，可以为得乎？则鸠鸮之在于笼也，亦可以为得矣。且夫趣舍声色以柴其内，皮弁鹬冠搢笏绅修以约其外。内支盈于柴栅，外重纆缴睆然在纆缴之中，而自以为得，则是罪人交臂历指而虎豹在于囊槛，亦可以为得矣！', '位于《庄子·外篇》，以篇首二字命题「天地」。全篇由十四个部分组成，大抵以无为自然为宗旨，代表了庄子技术哲学的思想，并对海森堡产生影响。德国伟大物理学家兼思想家海森堡十分推崇庄子技术哲学的思想，并多次在讲演中提到庄子的观点。后来，海森堡又把庄子的这段论述写进了他的专著《当代物理学的自然图象》。', '', '天和地虽然很大，它们的运动和变化却是均衡的；事物虽然纷杂，处理它们的方法却是相同的；百姓虽然众多，决定他们言行的却是国君。国君就是有「德」而又受命于天的人，所以说：遥远的古代君主统治天下，好像什么都没做，一切都遵循着自然的法则。
用道的观点来对待处理事物，那么掌管天下的国君就是正确的；用道的观点来看待职位的不同，那么君和臣各自承担的道义就分明了；用道的观念来看待各人的才干，那么天下的官吏都可以得到很好地管理；从道的观念笼统地观察，万事万物全都齐备，应有尽有。所以，通晓天地变化规律的，我们称之为「德」；万物运行所依靠的，我们称之为「道」；国君用来治理天下的，我们称之为「事」；那些创造性的才能，我们称之为「技」。技巧与事务相辅相成，事务与义理相辅相成，义理与德相辅相成，德与道相辅相成，道与天地万物相辅相成。所以说，古时候养育天下百姓的统治者，无所追求而天下富足，无所作为而万物自行变化发展，深沉宁寂而人心安定。《记》这本书上说：「通晓大道因而万事自然完满成功，无心获取因而鬼神敬佩贴服。」
先生说：「道，是覆盖和托载万物的，多么广阔而盛大啊！君子不可以不敞开心胸排除一切有为的杂念。用无为的态度去做就叫做自然，用无为的态度去说就叫做顺应，给人以爱或给物以利就叫做仁爱，让各各不同的事物回归同一的本性就叫做伟大，行为不与众不同就叫做宽容，心里包容着万种差异就叫做富有。因此持守自然赋予的禀性就叫纲纪，德行形成就叫做建功济物，遵循于道就叫做修养完备，不因外物挫折节守就叫做完美无缺。君子明白了这十个方面，也就容藏了立功济物的伟大心志，而且像滔滔的流水汇聚一处似的成为万物的归往。像这样，就能藏黄金于大山，沉珍珠于深渊，不贪图财物，也不追求富贵；不把长寿看作快乐，不把夭折看作悲哀，不把通达看作荣耀，不把穷困看作羞耻；不把谋求举世之利作为自己的职分，不把统治天下看作是自己居处于显赫的地位。显赫就会彰明，然而万物最终却归结于同一，死与生也并不存在区别。」
先生还说：「道，它居处沉寂犹如幽深宁寂的渊海，它运动恒洁犹如明澈清澄的清流。金石制成钟、磬的器物，不获取外力，没有办法鸣响，所以钟磬之类的器物即使存在鸣响的本能，却也不敲不响。万物这种有感才能有应的情况谁能准确地加以认识！具有盛德而居于统治地位的人，应该是持守素朴的真情往来行事而以通晓琐细事务为羞耻，立足于固有的真性而智慧通达于神秘莫测的境界。因此他的德行圣明而又虚广，他的心志即使有所显露，也是因为外物的探求而作出自然的反应。所以说，形体如不凭借道就不能产生，生命产生了不能顺德就不会明达。保全形体维系生命，建树盛德彰明大道，这岂不就是具有盛德而又居于统治地位的人吗？浩渺伟大啊！他们无心地有所感，他们又无心地有所动，然而万物都紧紧地跟随着他们呢！这就是具有盛德而又居于统治地位的人。道，看上去是那么幽暗深渺，听起来又是那么寂然无声。然而幽暗深渺之中却能见到光明的真迹，寂然无声之中却能听到万窍唱和的共鸣。幽深而又幽深能够从中产生万物，玄妙而又玄妙能够从中产生精神。所以道与万物相接，虚寂却能满足万物的需求，时时驰骋纵放却能总合万物成其归宿，无论是大还是小，是长还是短，是高还是远。」
黄帝在赤水的北岸游玩，登上昆仑山巅向南观望，不久返回而失落玄珠。派才智超群的智去寻找未能找到，派善于明察的离朱去寻找未能找到，派善于闻声辩言的喫诟去寻找也未能找到。于是让无智、无视、无闻的象罔去寻找，而象罔找回了玄珠。黄帝说：「奇怪啊！象罔方才能够找到吗？」
尧的老师叫许由，许由的老师叫齧缺，齧缺的老师叫王倪，王倪的老师叫被衣。
尧问许由说：「齧缺可以做天子吗？我想借助于他的老师来请他做天子。」许由说：「恐怕天下也就危险了！齧缺这个人的为人，耳聪目明智慧超群，行动办事快捷机敏，他天赋过人，而且竟然用人为的心智去对应并调合自然的禀赋。他明了该怎样禁止过失，不过他并不知晓过失产生的原因。让他做天子吗？他将借助于人为而抛弃天然，将会把自身看作万物归向的中心而着意改变万物固有的形迹，将会尊崇才智而急急忙忙地为求知和驭物奔走驰逐，将会被细末的琐事所役使，将会被外物所拘束，将会环顾四方，目不暇接地跟外物应接，将会应接万物而又奢求处处合宜，将会参预万物的变化而从不曾有什么定准。那样的人怎么能够做天子呢？虽然这样，有了同族人的聚集，就会有一个全族的先祖；可以成为一方百姓的统领，却不能成为诸方统领的君主。治理天下，必将是天下大乱的先导，这就是臣子的灾害，国君的祸根。」
尧在华巡视。华地守护封疆的人说：「啊，圣人！请让我为圣人祝愿吧。」「祝愿圣人长寿。」尧说：「用不着。」「祝愿圣人富有。」尧说：「用不着。」「祝愿圣人多男儿。」尧说：「用不着。」守护封疆的人说：「寿延、富有和多男儿，这是人们都想得到的。你偏偏不希望得到，是为什么呢？」尧说：「多个男孩子就多了一层忧惧，多财物就多出了麻烦，寿命长就会多受些困辱。这三个方面都无助于培养无为的观念和德行，所以我谢绝你对我的祝愿。」
守护封疆的人说：「起初我把你看作圣人呢，如今竟然是个君子。苍天让万民降生人间，必定会授给他一定的差事。男孩子多而授给他们的差事也就一定很多，有什么可忧惧的！富有了就把财物分给众人，有什么麻烦的！圣人总是象鹌鹑一样随遇而安、居无常处，象待哺雏鸟一样觅食无心，就像鸟儿在空中飞行不留下一点踪迹；天下太平，就跟万物一同昌盛；天下纷乱，就修身养性趋就闲暇；寿延千年而厌恶活在世上，便离开人世而升天成仙；驾驭那朵朵白云，去到天与地交接的地方。寿延、富有、多男孩子所导致的多辱、多事、多惧都不会降临于我，身体也不会遭殃；那么还会有什么屈辱呢！」守护封疆的人离开了尧，尧却跟在他的后面，说：「希望能得到你的指教。」守护封疆的人说：「你还是回去吧！」
唐尧统治天下，伯成子高立作诸侯。尧把帝位让给了舜，舜又把帝位让给了禹，伯成子高便辞去诸侯的职位而去从事耕作。夏禹前去拜见他，伯成子高正在地里耕作。夏禹快步上前居于下方，恭敬地站着问伯成子高道：「当年尧统治天下，先生立为诸侯。尧把帝位让给了舜，舜又把帝位让给了我，可是先生却辞去了诸侯的职位而来从事耕作。我冒昧地请问，这是为什么呢？」伯成子高说：「当年帝尧统治天下，不须奖励而百姓自然勤勉，不须惩罚而人民自然敬畏。如今你施行赏罚的办法而百姓还是不仁不爱，德行从此衰败，刑罚从此建立，后世之乱也就从此开始了。先生你怎么不走开呢？不要耽误我的事情！」于是低下头去用力耕地而不再理睬。
元气萌动宇宙源起的太初，一切只存在于「无」，而没有存在也就没有称谓；混一的状态就是宇宙的初始，不过混一之时，还远未形成各别的形体。万物从混一的状态中产生，这就叫做自得；未形成形体时禀受的阴阳之气已经有了区别，不过阴阳的交合却是如此吻合而无缝隙，这就叫做天命；阴气滞留阳气运动而后生成万物，万物生成生命的机理，这就叫做形体；形体守护精神，各有轨迹与法则，这就叫做本性。善于修身养性就会返归自得，自得的程度达到完美的境界就同于太初之时。同于太初之时心胸就会无比虚豁，心胸无比虚豁就能包容广大。混同合一之时说起话来就跟鸟鸣一样无心于是非和爱憎，说话跟鸟一样无别，则与天地融合而共存。混同合一是那么不露踪迹，好像蒙昧又好像是昏暗，这就叫深奥玄妙的大道，也就如同返回本真而一切归于自然。
孔子向老聃请教：「有人研修和体验大道却好像跟大道相背逆，把不能认可的看作是可以认可的，把不正确的认为是正确的。善于辩论的人说：‘离析石的质坚和色白就好像高悬于天宇那样清楚醒目。’像这样的人可以称作圣人吗？」老聃说：「这只不过是聪明的小吏供职时为技艺所拘系、劳苦身躯担惊受怕的情况。善于捕猎的狗因为受到拘系而愁思，猿猴因为行动便捷而被人从山林里捕捉来。孔丘，我告诉你，告诉给你听不见而又说不出的道理。大凡人有了头和脚等具体的形体而无知无闻的很多，有形体的人跟没有形体、没有形状的道并存的却完全没有。或是运动或是静止，或是死亡或是生存，或是衰废或是兴盛，这六种情况全都出于自然而不可能探知其所以然。倘若果真存在着什么治理那也是人们遵循本性和真情的各自活动，忘掉外物，忘掉自然，它的名字就叫做忘掉自己。忘掉自己的人，这就可以说是与自然融为一体。」
将闾葂拜见季彻说：「鲁国国君对我说：‘请让我接受你的指教。’我一再推辞可是鲁君却不答应，我已经对他说了，不知道对还是不对，请让我试着说给你听。我对鲁国国君说：‘你必须躬身实行恭敬和节俭，选拔出公正、忠诚的臣子管理政务而没有偏护与私心，这样百姓谁敢不和睦！’」季彻听了后俯身大笑说：「像你说的这些话，对于帝王的准则，恐怕就像是螳螂奋起臂膀企图阻挡车轮一样，必定不能胜任。况且像这样，那一定会把自己置于危险的境地，就像那高高的观楼和亭台，众多事物必将归往，投向那里的人也必然很多。」
将闾葂吃惊地说：「我对于先生的谈话实在感到茫然。虽然这样，还是希望先生谈谈大概。」季彻说：「伟大的圣人治理天下，让民心纵放自由不受拘束，使他们在教化方面各有所成，在陋习方面各有所改，完全消除伤害他人的用心而增进自我教化的思想，就像本性在驱使他们活动，而人们并不知道为什么会是这样。像这样，难道还用得着尊崇尧舜对人民的教化，而看轻浑沌不分的状态吗？希望能同于天然自得而心境安定哩！」
子贡到南边的楚国游历，返回晋国，经过汉水的南沿，见一老丈正在菜园里整地开畦，打了一条地道直通到井边，抱着水瓮浇水灌地，吃力地来来往往用力甚多而功效甚少。子贡见了说：「如今有一种机械，每天可以浇灌上百个菜畦，用力很少而功效颇多，老先生你不想试试吗？」种菜的老人抬起头来看着子贡说：「应该怎么做呢？」子贡说：「用木料加工成机械，后面重而前面轻，提水就像从井中抽水似的，快速犹如沸腾的水向外溢出一样，它的名字就叫做桔槔。」种菜的老人变了脸色讥笑着说：「我从我的老师那里听到这样的话，有了机械之类的东西必定会出现机巧之类的事，有了机巧之类的事必定会出现机变之类的心思。机变的心思存留在胸中，那么不曾受到世俗沾染的纯洁空明的心境就不完整齐备；纯洁空明的心境不完备，那么精神就不会专一安定；精神不能专一安定的人，大道也就不会充实他的心田。我不是不知道你所说的办法，只不过感到羞辱而不愿那样做呀。」子贡满面羞愧，低下头去不能作答。
隔了一会儿，种菜的老人说：「你是干什么的呀？」子贡说：「我是孔丘的学生。」种菜的老人说：「你不就是那具有广博学识并处处仿效圣人，夸诞矜持盖过众人，自唱自和哀叹世事之歌以周游天下卖弄名声的人吗？你要抛弃你的精神和志气，废置你的身形体骸，恐怕就可以逐步接近于道了吧！你自身都不善于修养和调理，哪里还有闲暇去治理天下呢！你走吧，不要在这里耽误我的事情！」
子贡大感惭愧神色顿改，怅然若失而不能自持，走出三十里外方才逐步恢复常态。子贡的弟子问道：「先前碰到的那个人是干什么的呀？先生为什么见到他面容大变顿然失色，一整天都不能恢复常态呢？」子贡说：「起初我总以为天下圣人就只有我的老师孔丘一人罢了，不知道还会有刚才碰上的那样的人。我从我的老师那里听说到，办事要寻求可行，功业要寻求成就。用的力气要少，获得的功效要多，这就是圣人之道。如今却竟然不是这样。持守大道的人德行才完备，德行完备的人身形才完整，身形完整的人精神才健全。精神健全方才是圣人之道。这样的人他们寄托形骸于世间跟万民生活在一起却不知道自己应该去到哪里，内心世界深不可测德行淳厚而又完备啊！功利机巧必定不会放在他们那种人的心上。像那样的人，不同于自己的心志不会去追求，不符合自己的思想不会去做。即使让天下人都称誉他，称誉的言词合乎他的德行，他也孤高而不顾；即使让天下人都非议他，非议使其名声丧失，他也无动于衷不予理睬。天下人的非议和赞誉，对于他们既无增益又无损害，这就叫做德行完备的人啊！我只能称作心神不定为世俗尘垢所沾染的人。」
子贡回到鲁国，把路上遇到的情况告诉给孔子。孔子说：「那是研讨和实践浑沌氏主张的人，他们了解自古不移浑沌无别的道理，不懂得需要顺乎时势以适应社会的变化，他们善于自我修养调理精神，却不善于治理外部世界。那明澈白静到如此素洁，清虚无为回返原始的朴质，体悟真性持守精神，优游自得地生活在世俗之中的人，你怎么会不感到惊异呢？况且浑沌氏的主张和修养方法，我和你又怎么能够了解呢？」
谆芒向东到大海去，正巧在东海之滨遇到苑风。苑风问道：「你打算去哪儿呢？」谆芒说：「打算去大海。」苑风又问：「去做什么呢？」谆芒说：「大海作为一种物象，江河注入它不会满溢，不停地舀取它不会枯竭；因而我将到大海游乐。」
苑风说：「那么，先生无意关心庶民百姓吗？希望能听到圣人之治。」谆芒说：「圣人之治吗？设置官吏施布政令但处处合宜得体；举贤任才而不遗忘一个能人，让每个人都能看清事情的真情实况去做自己应该做的事，行为和谈吐人人都能自觉自动而自然顺化，挥挥手示示意，四方的百姓没有谁不汇聚而来，这就叫圣人之治。」苑风说：「希望再能听到关于顺应外物凝神自得的人。」谆芒说：「顺应外物凝神自得的人，居处时没有思索，行动时没有谋虑，心里不留存是非美丑。四海之内人人共得其利就是喜悦，人人共享财货便是安定；那悲伤的样子像婴儿失去了母亲，那怅然若失的样子又像行路时迷失了方向。财货使用有余却不知道自哪里来，饮食取用充足却不知道从哪儿出。这就是顺应外物凝神自得的人的仪态举止。」苑风说：「希望再能听到什么是神人。」谆芒说：「精神超脱物外的神人驾驭着光亮，跟所有事物的形迹一道消失，这就叫普照万物。穷尽天命和变化的真情，与天地同乐，因而万事都自然消亡，万物也就自然回复真情，这就叫混同玄合没有差异。」
门无鬼与赤张满稽观看武王伐纣的部队。赤张满稽说：「周武王还是比不上有虞氏啊！所以天下遭遇这种祸患。」门无鬼说：「天下太平无事而后有虞氏才去治理呢，还是天下动乱才去治理呢？」
赤张满稽说：「天下太平无事是人们的心愿，又为什么还要考虑有虞氏的盛德而推举他为国君呢！有虞氏替人治疗头疮，毛发脱落而成秃子方才敷设假发，正如有了疾病方才会去求医。孝子操办药物用来调治慈父的疾病，他的面容多么憔悴，而圣人却以这种情况为羞。盛德的时代，不崇尚贤才，不任使能人；国君居于上位如同树颠高枝无心在上而自然居于高位，百姓却像无知无识的野鹿无所拘束；行为端正却不知道把它看作道义，相互友爱却不知道把它看作仁爱，敦厚老实却不知道把它看作忠诚，办事得当却不知道把它看作信义；无心地活动而又相互支使却不把它看作恩赐。所以行动之后不会留下痕迹，事成之后不会留传后代。」
孝子不奉承他的父母，忠臣不谄媚他的国君，这是忠臣、孝子尽忠尽孝的极点。凡是父母所说的便都加以肯定，父母所做的便都加以称赞，那就是世俗人所说的不肖之子；凡是君王所说的就都加以应承，君王所做的就都加以奉迎，那就是世俗人所说的不良之臣。可是人们却不了解，世俗的看法就必定是正确的吗？而世俗人所谓正确的便把它当作是正确的，世俗人所谓好的便把它当作是好的，却不称他们是谄谀之人。这样，世俗的观念和看法岂不比父母更可崇敬、比君王更可尊崇了吗？说自己是个谗谄的人，定会勃然大怒颜容顿改；说自己是个阿谀的人，也定会忿恨填胸面色剧变。可是一辈子谗谄的人，一辈子阿谀的人，又只不过看作是用巧妙的譬喻和华丽的辞藻以博取众人的欢心，这样，终结和初始、根本和末节全都不能吻合。穿上华美的衣裳，绣制斑烂的纹彩，打扮艳丽的容貌，讨好献媚于举世之人，却不自认为那就是谗谄与阿谀。跟世俗人为伍，是非观念相通，却又不把自己看作是普通的人，这真是愚昧到了极点。知道自己愚昧的人，并不是最大的愚昧；知道自己迷惑的人，并不是最大的迷惑。最迷惑的人，一辈子也不会醒悟；最愚昧的人，一辈子也不会明白。三个人在一起行走其中一个人迷惑，所要去到的地方还是可以到达的，因为迷惑的人毕竟要少些；三个人中两人迷惑就徒劳而不能到达，因为迷惑的人占优势。如今天下人全都迷惑不解，我即使祈求导向，也不可能有所帮助。这不令人可悲吗？
高雅的音乐世俗人不可能欣赏，折杨、皇华之类的民间小曲，世俗人听了都会欣然而笑。所以高雅的谈吐不可能留在世俗人的心里，而至理名言也不能从世俗人的口中说出，因为流俗的言谈占了优势。让其中两个人迷惑而弄错方向，因而所要去的地方便不可能到达。如今天下人都大惑不解，我即使寻求导向，怎么可能到达呢！明知不可能到达却要勉强去做，这又是一大迷惑，所以不如弃置一旁不予推究。不去寻根究底，还会跟谁一道忧愁！丑陋的人半夜里生下孩子，立即拿过火来照看，心情急切地唯恐生下的孩子像自己一样丑陋。
百年的大树，伐倒剖开后雕刻成精美的酒器，再用青、黄二色彩绘出美丽的花纹，而余下的断木则弃置在山沟里。雕刻成精美酒器的一段木料比起弃置在山沟里的其余木料，美好的命运和悲惨的遭遇之间就有了差别，不过对于失去了原有的本性来说却是一样的。盗跖与曾参、史䲡，行为和道义上存在着差别，然而他们失却人所固有的真性却也是一样的。大凡丧失真性有五种情况：一是五种颜色扰乱视觉，使得眼睛看不明晰；二是五种乐音扰乱听力，使得耳朵听不真切；三是五种气味薰扰嗅觉，困扰壅塞鼻腔并且直达额顶；四是五种滋味秽浊味觉，使得口舌受到严重伤害；五是取舍的欲念迷乱心神，使得心性驰竞不息、轻浮躁动。这五种情况，都是生命的祸害。可是，杨朱、墨翟竟不停地奋力追求而自以为有所得，不过这却不是我所说的优游自得。得到什么反而为其所困，也可以说是有所得吗？那么，斑鸠鸮鸟关于笼中，也可以算是优游自得了。况且取舍于声色的欲念像柴草一样堆满内心，皮帽羽冠、朝板、宽带和长裙捆束于外，内心里充满柴草栅栏，外表上被绳索捆了一层又一层，却瞪着大眼在绳索束缚中自以为有所得，那么罪犯反绑着双手或者受到挤压五指的酷刑，以及虎豹被关在圈栅、牢笼中，也可以算是优游自得了。', NULL, '', 'indent', 1524825795, '5ae28e31a22b9d004400f628', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637400, '庄子 · 外篇 · 天道', NULL, 9, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E5%A4%96%E7%AF%87%C2%B7%E5%A4%A9%E9%81%93/10183092?fr=aladdin', '', '天道运而无所积，故万物成；帝道运而无所积，故天下归；圣道运而无所积，故海内服。明于天，通于圣，六通四辟于帝王之德者，其自为也，昧然无不静者矣。圣人之静也，非曰静也善，故静也；万物无足以铙心者，故静也。水静则明烛须眉，平中准，大匠取法焉。水静犹明，而况精神！圣人之心静乎！天地之鉴也；万物之镜也。夫虚静恬淡寂漠无为者，天地之平而道德之至，故帝王圣人休焉。休则虚，虚则实，实则伦矣。虚则静，静则动，动则得矣。静则无为，无为也则任事者责矣。无为则俞俞，俞俞者忧患不能处，年寿长矣。夫虚静恬淡寂漠无为者，万物之本也。明此以南乡，尧之为君也；明此以北面，舜之为臣也。以此处上，帝王天子之德也；以此处下，玄圣素王之道也。以此退居而闲游江海，山林之士服；以此进为而抚世，则功大名显而天下一也。静而圣，动而王，无为也而尊，朴素而天下莫能与之争美。夫明白于天地之德者，此之谓大本大宗，与天和者也；所以均调天下，与人和者也。与人和者，谓之人乐；与天和者，谓之天乐。
庄子曰：“吾师乎！吾师乎！赍万物而不为戾，泽及万世而不为仁，长于上古而不为寿，覆载天地刻雕众形而不为巧，此之谓天乐。故曰：‘知天乐者，其生也天行，其死也物化。静而与阴同德，动而与阳同波。’故知天乐者，无天怨，无人非，无物累，无鬼责。故曰：‘其动也天，其静也地，一心定而王天下；其鬼不祟，其魂不疲，一心定而万物服。’言以虚静推于天地，通于万物，此之谓天乐。天乐者，圣人之心，以畜天下也。”
夫帝王之德，以天地为宗，以道德为主，以无为为常。无为也，则用天下而有余；有为也，则为天下用而不足。故古之人贵夫无为也。上无为也，下亦无为也，是下与上同德，下与上同德则不臣；下有为也，上亦有为也，是上与下同道，上与下同道则不主。上必无为而用天下，下必有为为天下用，此不易之道也。故古之王天下者，知虽落天地，不自虑也；辩虽雕万物，不自说也；能虽穷海内，不自为也。天不产而万物化，地不长而万物育，帝王无为而天下功。故曰莫神于天，莫富于地，莫大于帝王。故曰帝王之德配天地。此乘天地驰万物，而用人群之道也。
本在于上，末在于下，要在于主，详在于臣。三军五兵之运，德之末也；赏罚利害，五刑之辟，教之末也；礼法度数，形名比详，治之末也；钟鼓之音，羽旄之容，乐之末也；哭泣衰绖，隆杀之服，哀之末也。此五末者，须精神之运，心术之动，然后从之者也。
末学者，古人有之，而非所以先也。君先而臣从，父先而子从，兄先而弟从，长先而少从，男先而女从，夫先而妇从。夫尊卑先后，天地之行也，故圣人取象焉。天尊地卑，神明之位也；春夏先，秋冬后，四时之序也。万物化作，萌区有状，盛衰之杀，变化之流也。夫天地至神，而有尊卑先后之序，而况人道乎！宗庙尚亲，朝廷尚尊，乡党尚齿，行事尚贤，大道之序也。语道而非其序者，非其道也；语道而非其道者，安取道！
是故古之明大道者，先明天而道德次之，道德已明而仁义次之，仁义已明而分守次之，分守已明而形名次之，形名已明而因任次之，因任已明而原省次之，原省已明而是非次之，是非已明而赏罚次之。赏罚已明而愚知处宜，贵贱履位，仁贤不肖袭情。必分其能，必由其名。以此事上，以此畜下，以此治物，以此修身；知谋不用，必归其天，此之谓太平，治之至也。
故书曰：“有形有名。”形名者，古人有之，而非所以先也。古之语大道者，五变而形名可举，九变而赏罚可言也。骤而语形名，不知其本也；骤而语赏罚，不知其始也。倒道而言，迕道而说者，人之所治也，安能治人！骤而语形名赏罚，此有知治之具，非知治之道；可用于天下，不足以用天下，此之谓辩士，一曲之人也。礼法数度，形名比详，古人有之，此下之所以事上，非上之所以畜下也。
昔者舜问于尧曰：“天王之用心何如？”尧曰：“吾不敖无告，不废穷民，苦死者，嘉孺子而哀妇人。此吾所以用心已。”舜曰：“美则美矣，而未大也。”尧曰：“然则何如？”舜曰：“天德而出宁，日月照而四时行，若昼夜之有经，云行而雨施矣。”尧曰：“胶胶扰扰乎！子，天之合也；我，人之合也。”夫天地者，古之所大也，而黄帝尧舜之所共美也。故古之王天下者，奚为哉？天地而已矣。
孔子西藏书于周室。子路谋曰：“由闻周之徵藏史有老聃者，免而归居，夫子欲藏书，则试往因焉。”孔子
往见老聃，而老聃不许，于是繙十二经以说。老聃中其说，曰：“大谩，愿闻其要。”孔子曰：“要在仁义。”老聃曰：“请问，仁义，人之性邪？”孔子曰：“然。君子不仁则不成，不义则不生。仁义，真人之性也，又将奚为矣？”老聃曰：“请问，何谓仁义？”孔子曰：“中心物恺，兼爱无私，此仁义之情也。”老聃曰：“意，几乎后言！夫兼爱，不亦迂乎！无私焉，乃私也。夫子若欲使天下无失其牧乎？则天地固有常矣，日月固有明矣，星辰固有列矣，禽兽固有群矣，树木固有立矣。夫子亦放德而行，循道而趋，已至矣；又何偈偈乎揭仁义意，夫子乱人之性也！”
士成绮见老子而问曰：“吾闻夫子圣人也，吾固不辞远道而来愿见，百舍重趼而不敢息。今吾观子，非圣人也。鼠壤而余蔬，而弃妹之者，不仁也，生熟不尽于前，而积敛无崖。”老子漠然不应。
士成绮明日复见，曰：“昔者吾有刺于子，今吾心正却矣，何故也？”老子曰：“夫巧知神圣之人，吾自以为脱焉。昔者子呼我牛也而谓之牛，呼我马也而谓之马。苟有其实，人与之名而弗受，再受其殃。吾服也恒服，吾非以服有服。”士成绮雁行避影，履行遂进而问，“修身若何？”老子曰：“而容崖然，而目冲然，而颡頯然，而口阚然，而状义然，似系马而止也。动而持，发也机，察而审，知巧而？于泰，凡以为不信。边竟有人焉，其名为窃。”
夫子曰：“夫道，于大不终，于小不遗，故万物备。广广乎其无不容也，渊乎其不可测也。形德仁义，神之末也，非至人孰能定之！夫至人有世，不亦大乎！而不足以为之累。天下奋棅而不与之偕，审乎无假而不与利迁，极物之真，能守其本，故外天地，遗万物，而神未尝有所困也。通乎道，合乎德，退仁义，宾礼乐，至人之心有所定矣。”
世之所贵道者书也，书不过语，语有贵也。语之所贵者意也，意有所随。意之所随者，不可言传也，而世因贵言传书。世虽贵之，我犹不足贵也，为其贵非其贵也。故视而可见者，形与色也；听而可闻者，名与声也。悲夫，世人以形色名声为足以得彼之情！夫形色名声果不足以得彼之情，则知者不言，言者不知，而世岂识之哉？
桓公读书于堂上。轮扁斫轮于堂下，释椎凿而上，问桓公曰：“敢问，公之所读者何言邪？”公曰：“圣人之言也。”曰：“圣人在乎？”公曰：“已死矣。”曰：“然则君之所读者，古人之糟魄已夫！”桓公曰：“寡人读书，轮人安得议乎！有说则可，无说则死。”轮扁曰：“臣也以臣之事观之。斫轮，徐则甘而不可，疾则苦而不入。不徐不疾，得之于手而应于心，口不能言，有数存焉于其间。臣不能以喻臣之子，臣之子亦不能受之于臣，是以行年七十而老斫轮。古之人与其不可传也死矣，然则君之所读者，古人之糟魄已夫！”', '跟《天地》篇一样，中心还是倡导“无为”；所谓“天道”，也就是自然的规律，不可抗拒，也不可改变。', '', '自然规律的运行从不曾有过停留和积滞，所以万物得以生成；帝王统治的规律也从不曾有过停留和积滞，所以天下百姓归顺；思想修养臻于圣明的人对宇宙万物的看法和主张也不曾中断和停留，所以四海之内人人倾心折服。明白于自然，通晓于圣哲，对于了解帝王之德的人来说，上下四方相通和四季的畅达，全都是自身的运动，晦迹韬光不露形迹从不损伤静寂的心境。圣明的人内心宁寂，不是说宁寂美好，所以才去追求宁寂；各种事物都不能动摇和扰乱他的内心，因而心神才虚空宁寂犹如死灰。水在静止时便能清晰地照见人的须眉，水的平面合乎水平测定的标准，高明的工匠也会取之作为水准。水平静下来尚且清澄明澈，又何况是人的精神！圣明的人心境是多么虚空宁静啊！可以作为天地的明镜，可以作为万物的明镜。虚静、恬淡、寂寞、无为，是天地的基准，是道德修养的最高境界，所以古代帝王和圣明的人都停留在这一境界上。停留在这一境界上便心境空明虚淡，空灵虚淡也就会显得充实，心境充实就能合于自然之理了。心境虚空才会平静宁寂，平静宁寂才能自我运动，没有干扰地自我运动也就能够无不有所得。虚静便能无为，无为使任事的人各尽其责。无为也就从容自得，从容自得的人便不会身藏忧愁与祸患，年寿也就长久了。虚静、恬淡、寂寞、无为，是万物的根本。明白这个道理而居于帝王之位，就象唐尧作为国君；明白这个道理而居于臣下之位，就象虞舜作为臣属。凭借这个道理而处于尊上的地位，就算是帝王治世的盛德；凭借这个道理而处于庶民百姓的地位，就算是通晓了玄圣素王的看法和主张。凭借这个道理退居闲游于江海，山林的隐士就推心折服；凭借这个道理进身仕林而安抚世间百姓，就能功业卓著名扬四海而使天下大同。清静而成为玄圣，行动而成为帝王，无为方才能取得尊尚的地位，保持淳厚素朴的天性天下就没有什么东西可以跟他媲美。明白天地以无为为本的规律，这就叫做把握了根本和宗原，而成为跟自然谐和的人；用此来均平万物、顺应民情，便是跟众人谐和的人。跟人谐和的，称作人乐；跟自然谐和的，就称作天乐。
庄子说：“我的宗师啊！我的宗师啊！拥有（具备、承载着、负担着）万物并不认为是那是罪行，恩泽施及万世而不以仁爱自居，生命长（读作长短的长）于远古而不自认为是长寿，覆天载地、雕刻众物之形而不觉得自己智巧，这就叫做天乐。所以说：‘通晓天乐的人，他活在世上顺应自然地运动，他离开人世混同万物而变化。平静时跟阴气同宁寂，运动时跟阳气同波动。’因此体察到天乐的人，不会受到天的抱怨，不会受到人的非难，不会受到外物的牵累，不会受到鬼神的责备。所以说：‘运动时合乎自然的运行，静止时犹如大地一样宁寂，内心安定专一统驭天下；鬼魔不会作祟，神魂不会疲惫，内心专一安定万物无不折服归附。’这些话就是说把虚空宁静推及到天地，通达于万物，这就叫做天乐。所谓天乐，就是圣人的爱心，用以养育天下人。”
帝王的德行，以天地为根本，以道德为中心，以顺应无为而治为常规。帝王无为，役使天下人而且闲暇有余；臣子有为，为天下事竭心尽力而且唯恐不足。因此，古时候的人都看重帝王无为的态度。处于上位的帝王无为，处于下位的臣子也无为，这样臣子跟帝王的态度相同，臣子跟帝王相同那就不象臣子了；处于下位的臣子有为，处于上位的帝王也有为，这样帝王跟臣子的作法就相同了，帝王跟臣子相同那就不象帝王了。帝王必须无为方才能役用天下，臣子必须有为而为天下所用，这是天经地义不能随意改变的规律。所以，古代统治天下的人，智慧即使能笼络天地，也从不亲自去思虑；口才即使能周遍万物，也从不亲自去言谈；才能即使能雄踞海内，也从不亲自去做。上天并不着意要产生什么而万物却自然变化产生，大地并不着意要长出什么而万物却自然繁衍生长，帝王能够无为天下就会自然得到治理。所以说没有什么比上天更为神妙，没有什么比大地更为富饶，没有什么比帝王更为伟大。因此说帝王的德行能跟天地相合。这就是驾驭天地、驱遣万物而任用天下人的办法。
道德存在于上古，仁义则推行于当今；治世的纲要掌握在帝王手里，繁杂的事务留在臣子的操劳中。军队和各种兵器的运用，这是德化衰败的表现；奖赏处罚利导惩戒，并且施行各种刑法，这是诲谕衰败的表现；礼仪法规度量计数，对事物实体和称谓的比较和审定，这是治理衰败的表现；钟鼓的声音，用鸟羽兽毛装饰的仪容，这是声乐衰败的表现；痛哭流涕披麻戴孝，不同规格的隆重或省简的丧服，这是哀伤情感不能自然流露的表现。这五种微末之举，等待精神的自然运行和心智的正常活动，方才能排除矫矜、率性而生。
追求末节的情况，古人中已经存在，但并不是用它来作为根本。国君为主而臣下从属，父亲为主而子女从属，兄长为主而弟弟从属，年长为主而年少从属，男子为主而妇女从属，丈夫为主而妻子从属。尊卑、先后，这都是天地运行的规律，所以古代圣人取而效法之。上天尊贵，大地卑下，这是神明的位次；春夏在先，秋冬在后，这是四季的序列。万物变化而生，萌生之初便存在差异而各有各的形状；盛与衰的次第，这是事物变化的流别。天与地是最为神圣而又玄妙的，尚且存在尊卑、先后的序列，何况是社会的治理呢！宗庙崇尚血缘，朝廷崇尚高贵，乡里崇尚年长，办事崇尚贤能，这是永恒的大道所安排下的秩序。谈论大道却非议大道安排下的秩序，这就不是真正在尊崇大道；谈论大道却非议体悟大道的人，怎么能真正获得大道！
因此，古代通晓大道的人，首先阐明自然的规律而后才是道德，道德已经阐明而后才是仁义，仁义已经阐明而后才是职守，职守已经明确而后才是事物的外形和称谓，外形和称谓已经明确了而后才是依其才而任其职，依才任职已经明确而后才是恕免或废除，恕免或废除已经明确而后才是是非，是非明确而后才是赏罚。赏罚明确因而愚钝与聪颖的人都能相处合宜，尊贵和卑贱的人也都能各安其位；仁慈贤能和不良的人也才能都袭用真情。必须区分各自不同的才能，必须遵从各自不同的名分。用这样的办法来侍奉帝王，用这样的办法来养育百姓，用这样的办法来管理万物，用这样的办法来修养自身；智谋不宜用，必定归依自然，这就叫做天下太平，也就是治理天下的最高境界。
因此古书上说：“有形体，有名称。”明了并区分事物的形体和称谓，古代就有人这样做，不过并不是把形、名的观念摆在首位。古时候谈论大道的人，从说明事物自然规律开始经过五个阶段方才可以称述事物的形体和名称，经过九个阶段方才可以谈论关于赏罚的问题。唐突地谈论事物的形体和称谓，不可能了解“形名”问题演绎的根本；唐突地讨论赏罚问题，不可能知晓赏罚问题的开始。把上述演绎顺序倒过来讨论，或者违背上述演绎顺序而辩说的人，只能是为别人所统治，怎么能去统治别人！离开上述顺序而唐突地谈论形名和赏罚，这样的人即使知晓治世的工具，也不会懂得治世的规律；可以用于天下，而不足以用来治理天下；这种人就称做辩士，即只能认识事物一隅的浅薄之人。礼仪法规计数度量，对事物的形体和名称比较和审定，古时候就有人这样做，这都是臣下侍奉帝王的作法，而不是帝王养育臣民的态度。
过去舜曾向尧问道：“你作为天子用心怎么样？”尧说：“我从不侮慢庶民百姓，也不抛弃生活无计走投无路的穷苦人民，为死者苦苦焦虑，很好地对待留下的幼子并悲悯那些妇人。这些就是我用心的方式。”舜说：“这样做好当然是很好了，不过还说不上伟大。”尧说：“如此那么将怎么办呢？”舜说：“自然而成形迹安宁，象日月照耀，四季运行，象昼夜交替，形成常规，象云彩随风飘动，雨点布施万物。”尧说：“整日里纷纷扰扰啊！你，跟自然相合；我，跟人事相合。”天和地，自古以来是最为伟大的，黄帝、尧、舜都共同赞美它。所以，古时候统治天下的人，做些什么呢？仿效天地罢了。
孔子想把书保藏到西边的周王室去。子路出主意说：“我听说周王室管理文典的史官老聃，已经引退回到家乡隐居，先生想要藏书，不妨暂且经过他家问问意见。”孔子说：“好。”
孔子前往拜见老聃，老聃对孔子的要求不予承诺，孔子于是翻检众多经书反复加以解释。老聃中途打断了孔子的解释，说：“你说得太冗繁，希望能够听到有关这些书的内容大要。”孔子说：“要旨就在于仁义。”老聃说：“请问，仁义是人的本性吗？”孔子说：“是的。君子如果不仁就不能成其名声，如果不义就不能立身社会。仁义的确是人的本性，离开了仁义又能干些什么呢？”老聃说：“再请问，什么叫做仁义？”孔子说：“中正而且和乐外物，兼爱而且没有偏私，这就是仁义的实情。”老聃说：“噫！你后面所说的这许多话几乎都是浮华虚伪的言辞！正是因为性情已经发生迁腐，才需要强调兼爱！正是因为已经存在自私的现象，才需要强调无私。先生你是想让天下的人都失去养育自身的条件吗？那么，天地原本就有自己的运动规律，日月原本就存在光亮，星辰原本就有各自的序列，禽兽原本就有各自的群体，树木原本就直立于地面。先生你还是仿依自然的状态行事，顺着规律去进取，这就是极好的了。又何必如此急切地标榜仁义，这岂不就象是打着鼓去寻找逃亡的人，鼓声越大跑得越远吗？噫！先生扰乱了人的本性啊！”
士成绮见到老子而问道：“听说先生是个圣人，我便不辞路途遥远而来，一心希望能见到你，走了上百天，脚掌上结上厚厚的老趼也不敢停下来休息休息。如今我观察先生，竟不象是个圣人。老鼠洞里掏出的泥土中有许多余剩的食物，看轻并随意抛弃这些物品，不能算合乎仁的要求；粟帛饮食享用不尽，而聚敛财物却没有限度。”老子好象没有听见似的不作回答。
第二天士成绮再次见到老子，说：“昨日我用言语刺伤了你，今天我已有所省悟而且改变了先前的嫌隙，这是什么原因呢？”老子说：“巧智神圣的人，我自以为早已脱离了这种人的行列。过去你叫我牛我就称作牛，叫我马我就称作马。假如存在那样的外形，人们给他相应的称呼却不愿接受，将会第二次受到祸殃。我顺应外物总是自然而然，我并不是因为要顺应而有所顺应。”士成绮象雁一样侧身而行不敢正视自己羞愧的身影，蹑手蹑脚地走向前来问道：“修身之道是怎样的呢？”老子说：“你容颜伟岸高傲，你目光突视，你头额矜傲，你口张舌利，你身形巍峨，好象奔马被拴住身虽休止而心犹奔腾。你行为暂时有所强制，一旦行动就象箭发弩机，你明察而又精审，自持智巧而外露骄恣之态，凡此种种都不能看作是人的真实本性。边远闭塞的地方有过这样的人，他们的名字就叫做窃贼。”
先生说：“道，从大的方面说它没有穷尽，从小的方面说它没有遗缺，所以说具备于万物之中。广大啊，道没有什么不包容，深遽啊，道不可以探测。推行刑罚德化与仁义，这是精神衰败的表现，不是道德修养高尚的“至人”谁能判定它！道德修养高尚的“至人”一旦居于统治天下的位置，不是很伟大吗？可是却不足以成为他的拖累。天下人争相夺取权威但他却不会随之趋赴，审慎地不凭借外物而又不为私利所动，深究事物的本原，持守事物的根本，所以忘忽天地，弃置万物，而精神世界不曾有过困扰。通晓于道，合乎常规，辞却仁义，摈弃礼乐，至人的内心也就恬淡而不乖违。
世上人们所看重的称道和就是书。书并没有超越言语，而言语确有可贵之处。言语所可看重的就在于它的意义，而意义又有它的出处。意义的出处，是不可以用言语来传告的，然而世人却因为看重言语而传之于书。世人虽然看重它，我还是认为它不值得看重，因为它所看重的并不是真正可以看重的。所以，用眼睛看而可以看见的，是形和色；用耳朵听而可以听到的，是名和声。可悲啊，世上的人们满以为形、色、名、声就足以获得事物的实情！形、色、名、声实在是不足以获得事物的实情，而知道的不说，说的不知道，世上的人们难道能懂得这个道理吗？
齐桓公在堂上读书，轮扁在堂下砍削车轮，他放下椎子和凿子走上朝堂，问齐桓公说：“冒昧地请问，您所读的书说的是些什么呢？”齐桓公说：“是圣人的话语。”轮扁说：“圣人还在世吗？”齐桓公说：“已经死了。”轮扁说：“这样，那么国君所读的书，全是古人的糟粕啊！”齐桓公说：“寡人读书，制作车轮的人怎么敢妄加评议呢！有什么道理说出来那还可以原谅，没有道理可说那就得处死。”轮扁说：“我用我所从事的工作观察到这个道理。砍削车轮，动作慢了松缓而不坚固，动作快了涩滞而不入木。不慢不快，手上顺利而且应合于心，口里虽然不能言说，却有技巧存在其间。我不能用来使我的儿子明白其中的奥妙，我的儿子也不能从我这儿接受这一奥妙的技巧，所以我活了七十岁如今老了还在砍削车轮。古时候的人跟他们不可言传的道理一块儿死亡了，那么国君所读的书，正是古人的糟粕啊！”', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf50d635634aee3ea86f", "shortContent": "在中国赋史上，荀子是第一位以赋命篇的作家。清人王芑孙《读赋卮言》说：“相如之徒，敷典摛文，乃从荀法。”荀子《赋篇》的原创意义，既在于为作为文类的“赋”创名，还在于创建了赋的文体范式，主客问答，咏物寓意，铺陈写物，因物以讽，开汉赋形成之先河。《赋篇》包括《礼》《智》《云》《蚕》《箴》五篇赋，后附《佹诗》。五赋的主要特点是以隐语为表现形式，隐语亦即后世所谓的谜语。刘勰《文心雕龙·谐隐》释谜语云：“谜也...", "authors": ["顾伟列"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa0dbb8b379ee0aecc9", "shortContent": "文中所叙花生奇人奇遇之事，虽是作者友人所述，看似道听途说，妄言妄听之类，但因所述“甚悉”，也就易于使读者信其实有，而非虚言。但作者于“甚悉”诸事之中，不言花生里居，等等一般情况，而是识其牝牡骊黄之外，仅只强调“嗜花如命”这一特点，重点非常突出。文中主人花生，虽然早中秀才，颇读圣贤之书，却与一般文人汲求功名有所不同，不是欲走科举入仕之途，而是绝意功名，唯与花儿相依为命。因花中之梅，高洁冰清，一向为人...", "authors": ["徐振贵", "张玉芹"], "pressName": "上海辞书出版社"}]', '', 'indent', 1524825855, '5ae28e7a9f5454005ea87fa0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637402, '庄子 · 外篇 · 刻意', NULL, 5, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E5%A4%96%E7%AF%87%C2%B7%E5%88%BB%E6%84%8F/10183474', '', '刻意尚行，离世异俗，高论怨诽，为亢而已矣；此山谷之士，非世之人，枯槁赴渊者之好也。语仁义忠信，恭俭推让，为修而已矣；此平世之士，教诲之人，游居学者之所好也。语大功，立大名，礼君臣，正上下，为治而已矣；此朝廷之士，尊主强国之人，致功并者之所好也。就薮泽，处闲旷，钓鱼闲处，无为而已矣；此江海之士，避世之人，闲暇者之所好也。吹呴呼吸，吐故纳新，熊经鸟申，为寿而已矣；此道引之士，养形之人，彭祖寿考者之所好也。若夫不刻意而高，无仁义而修，无功名而治，无江海而闲，不道引而寿，无不忘也，无不有也，淡然无极而众美从之；此天地之道，圣人之德也。故曰：夫恬淡寂漠，虚无无为，此天地之平而道德之质也。
故曰：圣人休休焉则平易矣。平易则恬淡矣。平易恬淡，则忧患不能入，邪气不能袭，故其德全而神不亏。故曰：圣人之生也天行，其死也物化。静而与阴同德，动而与阳同波。不为福先，不为祸始。感而后应，迫而后动，不得已而后起。去知与故，遁天之理。故无天灾，无物累，无人非，无鬼责。其生若浮，其死若休。不思虑，不豫谋。光矣而不耀，信矣而不期。其寝不梦，其觉无忧。其神纯粹，其魂不罢。虚无恬淡，乃合天德。故曰：悲乐者，德之邪也；喜怒者，道之过也；好恶者，德之失也。故心不忧乐，德之至也；一而不变，静之至也；无所于忤，虚之至也；不与物交，淡之至也；无所于逆，粹之至也。故曰：形劳而不休则弊，精用而不已则竭。水之性，不杂则清，莫动则平；郁闭而不流，亦不能清；天德之象也。故曰：纯粹而不杂，静一而不变，淡而无为，动而以天行，此养神之道也。
夫有干越之剑者，柙而藏之，不敢用也，宝之至也。精神四达并流，无所不极，上际于天，下蟠于地，化育万物，不可为象，其名为同帝。纯素之道，唯神是守。守而勿失，与神为一。一之精通，合于天伦。野语有之曰：“众人重利，廉士重名，贤士尚志，圣人贵精。”故素也者，谓其无所与杂也；纯也者，谓其不亏其神也。能体纯素，谓之真人。', '《刻意》以篇首两字作为篇名，“刻意”的意思就是磨砺自己的心志。本篇内容是讨论修养的，不同的人有不同的修养要求，只有“虚无恬淡”才合于“天德”，因而也才是修养的最高境域。全文较短，大体分成三个部分，第一部分至“圣人之德也”，分析了六种不同的修养态度，唯有第六种才值得称道，“澹然无极”才是“天地之道”、“圣人之德”。第二部分至“此养神之道也”，讨论修养的方法，中心就是“无为”。余下为第三部分，提出“贵精”的主张，所谓“贵精”即不丧“纯”、“素”，这样的人就可叫做“真人”。', '', '磨砺心志崇尚修养，超脱尘世不同流俗，谈吐不凡，抱怨怀才不遇而讥评世事无道，算是孤高卓群罢了；这样做乃是避居山谷的隐士，是愤世嫉俗的人，正是那些洁身自好、宁可以身殉志的人所一心追求的。宣扬仁爱、道义、忠贞、信实和恭敬、节俭、辞让、谦逊，算是注重修身罢了；这样做乃是意欲平定治理天下的人，是对人施以教化的人，正是那些游说各国而后退居讲学的人所一心追求的。宣扬大功，树立大名，用礼仪来划分君臣的秩序，并以此端正和维护上下各别的地位，算是投身治理天下罢了；这样做乃是身居朝廷的人，尊崇国君强大国家的人，正是那些醉心于建立功业开拓疆土的人所一心追求的。走向山林湖泽，处身闲暇旷达，垂钩钓鱼来消遣时光，算是无为自在罢了；这样做乃是闲游江湖的人，是逃避世事的人，正是那些闲暇无事的人所一心追求的。嘘唏呼吸，吐却胸中浊气吸纳清新空气，像黑熊攀缘引体、像鸟儿展翅飞翔，算是善于延年益寿罢了；这样做乃是舒活经络气血的人，善于养身的人，正是像彭祖那样寿延长久的人所一心追求的。
若不需磨砺心志而自然高洁，不需倡导仁义而自然修身，不需追求功名而天下自然得到治理，不需避居江湖而心境自然闲暇，不需舒活经络气血而自然寿延长久，没有什么不忘于身外，而又没有什么不据于自身。宁寂淡然而且心智从不滞留一方，而世上一切美好的东西都汇聚在他的周围。这才是像天地一样的永恒之道，这才是圣人无为的无尚之德。
所以说，恬淡、寂漠、虚空、无为，这是天地赖以均衡的基准，而且是道德修养的最高境界。
所以说，圣人总是停留在这一境域里，停留在这一境域也就平坦而无难了。安稳恬淡，那么忧患不能进入内心，邪气不能侵袭机体，因而他们的德行完整而内心世界不受亏损。
所以说，圣人生于世间顺应自然而运行，他们死离人世又像万物一样变化而去；平静时跟阴气一样宁寂，运动时又跟阳气一道波动。不做幸福的先导，也不为祸患的起始，外有所感而后内有所应，有所逼迫而后有所行动，不得已而后兴起。抛却智巧与事故，遵循自然的常规。因而没有自然的灾害，没有外物的牵累，没有旁人的非议，没有鬼神的责难。他们生于世间犹如在水面飘浮，他们死离人世就像疲劳后的休息。他们不思考，也不谋划。光亮但不刺眼，信实却不期求。他们睡觉不做梦，他们醒来无忧患，他们心神纯净精粹，他们魂灵从不疲惫。虚空而且恬淡，方才合乎自然的真性。
所以说，悲哀和欢乐乃是背离德行的邪妄，喜悦和愤怒乃是违反大道的罪过，喜好和憎恶乃是忘却真性的过失。因此内心不忧不乐，是德行的最高境界；持守专一而没有变化，是寂静的最高境界；不与任何外物相抵触，是虚豁的最高境界；不跟外物交往，是恬淡的最高境界；不与任何事物相违逆，是精粹的最高境界。
所以说，形体劳累而不休息那么就会疲乏不堪，精力使用过度而不止歇那么就会元气劳损，元气劳损就会精力枯竭。水的本性，不混杂就会清澈，不搅动就会平静，闭塞不流动也就不会纯清，这是自然本质的现象。
所以说，纯净精粹而不混杂，静寂持守而不改变，恬淡而又无为，运动则顺应自然而行，这就是养神的道理。', NULL, '', 'indent', 1524825965, '5ae28ee70b616000757de68d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637409, '庄子 · 外篇 · 缮性', NULL, 3, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E5%A4%96%E7%AF%87%C2%B7%E7%BC%AE%E6%80%A7/10183643?fr=aladdin', '', '缮性于俗学，以求复其初；滑欲于俗思，以求致其明：谓之蔽蒙之民。
古之治道者，以恬养知。生而无以知为也，谓之以知养恬。知与恬交相养，而和理出其性。夫德，和也；道，理也。德无不容，仁也；道无不理，义也；义明而物亲，忠也；中纯实而反乎情，乐也；信行容体而顺乎文，礼也。礼乐遍行，则天下乱矣。彼正而蒙己德，德则不冒。冒则物必失其性也。古之人，在混芒之中，与一世而得淡漠焉。当是时也，阴阳和静，鬼神不扰，四时得节，万物不伤，群生不夭，人虽有知，无所用之，此之谓至一。当是时也，莫之为而常自然。
逮德下衰，及燧人、伏羲始为天下，是故顺而不一。德又下衰，及神农、黄帝始为天下，是故安而不顺。德又下衰，及唐、虞始为天下，兴治化之流，枭淳散朴，离道以善，险德以行，然后去性而从于心。心与心识知，而不足以定天下，然后附之以文，益之以博。文灭质，博溺心，然后民始惑乱，无以反其性情而复其初。由是观之，世丧道矣，道丧世矣，世与道交相丧也。道之人何由兴乎世，世亦何由兴乎道哉！道无以兴乎世，世无以兴乎道，虽圣人不在山林之中，其德隐矣。隐故不自隐。古之所谓隐士者，非伏其身而弗见也，非闭其言而不出也，非藏其知而不发也，时命大谬也。当时命而大行乎天下，则反一无迹；不当时命而大穷乎天下，则深根宁极而待：此存身之道也。古之存身者，不以辩饰知，不以知穷天下，不以知穷德，危然处其所而反其性，己又何为哉！道固不小行，德固不小识。小识伤德，小行伤道。故曰：正己而已矣。乐全之谓得志。
古之所谓得志者，非轩冕之谓也，谓其无以益其乐而已矣。今之所谓得志者，轩冕之谓也。轩冕在身，非性命也，物之傥来，寄也。寄之，其来不可圉，其去不可止。故不为轩冕肆志，不为穷约趋俗，其乐彼与此同，故无忧而已矣！今寄去则不乐。由是观之，虽乐，未尝不荒也。故曰：丧己于物，失性于俗者，谓之倒置之民。', '《庄子·外篇·缮性》是战国时期著名思想家、文学家庄子的作品《庄子》中的一篇，文章中心仍是讨论如何养性。', '', '在世俗的流习范围内修治性情，靠仁义礼智的儒俗学说来期求复归原始的真性；内心欲念早已被习俗所扰乱，还一心希望能达到明彻与通达；这就叫做蔽塞愚昧的人。
古时候研究道术的人，总是以恬静来调养心智；心智生成却不用智巧行事，可称它为以心智调养恬静。心智和恬静交相调治，因而谐和顺应之情从本性中表露而出。德，就是谐和；道，就是顺应。德无所不容，就叫做仁；道无所不顺，就叫做义。义理彰明因而物类相亲，就叫做忠；心中纯厚朴实而且返归本真，就叫做乐；诚信著显、容仪得体而且合于一定礼仪的节度和表征，就叫做礼。礼乐偏执一方而又多方有失，那么天下定然大乱了。各人自我端正而且敛藏自己的德行，德行也就不会冒犯他人，德行冒犯他人那么万物必将失却自己的本性。
古时候的人，生活在混沌鸿蒙、淳风未散的境况中，跟整个外部世界混为一体而且人们彼此都恬淡无为、互不交往。正是这个时候，阴与阳谐和而又宁静，鬼神也不会干扰，四季的变化顺应时节，万物全不会受伤害，各种有生命的东西都能尽享天年，人们即使内存心智，也没处可用，这就叫做最为完满的浑一状态。正是这个时候，人们不知道需要去做什么而保持着天然。
等到后来道德衰退，到了燧人氏、伏羲氏统治天下，世事随顺却已不能浑然为一。道德再度衰退，到了神农氏和黄帝统治天下，世道安定却已不能随顺民心与物情。道德再度衰退，到了唐尧、虞舜统治天下，开启了治理和教化的风气，淳厚质朴之风受到干扰与破坏，背离大道而为，寡有德行而行，这之后也就舍弃了本性而顺从于各自的私心。人们彼此间都相互知道和了解，也就不足以使天下得到安定，然后又贴附上浮华的文饰，增加了众多的俗学。文饰浮华毁坏了质朴之风，广博的俗学掩没了纯真的心灵，然后人民才开始迷惑和纷乱，没有什么办法返归本真而回复原始的情状。
由此观之，世间丧失了自然之道，自然之道丧失了人世。社会和道交相丧失，有道之人怎么能立脚于人世间，人世间又怎么能从自然之道得到振兴呢？道没有办法在人世间兴起，人世间没有办法让道得以振兴，即使圣人不生活在少有人烟的山林之中，他的德行也必将隐没而不为人知。
谈到隐没于世，时逢昏暗不必韬光便已自隐。古时候的所谓隐士，并不是为了隐伏身形而不愿显现于世，并不是为了缄默不言而不愿吐露真情，也不是为了深藏才智而不愿有所发挥，是因为时遇和命运乖妄、背谬啊。当时遇和命运顺应自然而通行于天下，就会返归浑沌纯一之境而不显露踪迹。当时遇不顺、命运乖违而穷困于天下，就固守根本、保有宁寂至极之性而静心等待；这就是保存自身的方法。
古时候善于保存自身的人，不用辩说来巧饰智慧，不用智巧使天下人困窘，不用心智使德行受到困扰，巍然自持地生活在自己所处的环境而返归本性与真情，又何须一定得去做些什么呢！大道广荡本不是小有所成的人能够遵循，大德周遍万物本不是小有所知的人能够鉴识。小有所知会伤害德行，小有所成会伤害大道。所以说，端正自己也就可以了。快意地保持本真就可称作是心意自得而自适。
古时候所说的自得自适的人，不是指高官厚禄地位尊显，说的是出自本然的快意而没有必要再添加什么罢了。现在人们所说的快意自适，是指高官厚禄地位显赫。荣华富贵在身，并不出自本然，犹如外物偶然到来，是临时寄托的东西。外物寄托，它们到来不必加以阻挡，它们离去也不必加以劝止。所以不可为了富贵荣华而恣意放纵，不可因为穷困贫乏而趋附流俗，身处富贵荣华与穷困贫乏，其间的快意相同，因而没有忧愁罢了。如今寄托之物离去便觉不能快意，由此观之，即使真正有过快意也未尝不是迷乱了真性。所以说，由于外物而丧失自身，由于流俗而失却本性，就叫做颠倒了本末的人。', NULL, '', 'indent', 1524911225, '5ae3dbf80b6160007584f796', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637410, '庄子 · 外篇 · 秋水', NULL, 246, 16, 4, 5, '庄子', NULL, 10064, '57b90297165abd0054bfdce7', '周', 'wen', '文', 'https://baike.baidu.com/item/庄子·秋水/8218757', '', '秋水时至，百川灌河，泾流之大，两涘渚崖之间，不辨牛马。于是焉河伯欣然自喜，以天下之美为尽在己。顺流而东行，至于北海，东面而视，不见水端。于是焉河伯始旋其面目，望洋向若而叹曰：「野语有之曰：『闻道百以为莫己若者』，我之谓也。且夫我尝闻少仲尼之闻而轻伯夷之义者，始吾弗信；今我睹子之难穷也，吾非至于子之门则殆矣，吾长见笑于大方之家。」
北海若曰：「井蛙不可以语于海者，拘于虚也；夏虫不可以语于冰者，笃于时也；曲士不可以语于道者，束于教也。今尔出于崖涘，观于大海，乃知尔丑，尔将可与语大理矣。天下之水，莫大于海，万川归之，不知何时止而不盈；尾闾泄之，不知何时已而不虚；春秋不变，水旱不知。此其过江河之流，不可为量数。而吾未尝以此自多者，自以比形于天地，而受气于阴阳，吾在[于]天地之间，犹小石小木之在大山也，方存乎见少，又奚以自多！计四海之在天地之间也，不似礨空之在大泽乎？计中国之在海内，不似稊米之在大仓乎？号物之数谓之万，人处一焉；人卒九州，谷食之所生，舟车之所通，人处一焉；此其比万物也，不似豪末之在于马体乎？五帝之所连，三王之所争，仁人之所忧，任士之所劳，尽此矣。伯夷辞之以为名，仲尼语之以为博，此其自多也，不似尔向之自多于水乎？」
河伯曰：「然则吾大天地而小豪末，可乎？」
北海若曰：「否。夫物，量无穷，时无止，分无常，终始无故。是故大知观于远近，故小而不寡，大而不多：知量无穷。证向今故，故遥而不闷，掇而不跂，知时无止；察乎盈虚，故得而不喜，失而不忧，知分之无常也；明乎坦涂，故生而不说，死而不祸，知终始之不可故也。计人之所知，不若其所不知；其生之时，不若未生之时；以其至小求穷其至大之域，是故迷乱而不能自得也。由此观之，又何以知（毫）[豪]末之足以定至细之倪！又何以知天地之足以穷至大之域！」
河伯曰：「世之议者皆曰：『至精无形，至大不可围。』是信情乎？」
北海若曰：「夫自细视大者不尽，自大视细者不明。夫精，小之微也；垺，大之殷也，故异便。此势之有也。夫精粗者，期于有形者也；无形者，数之所不能分也；不可围者，数之所不能穷也。可以言论者，物之粗也；可以意致者，物之精也；言之所不能论，意之所不能察致者，不期精粗焉。
是故大人之行，不出乎害人，不多仁恩；动不为利，不贱门隶；货财之争，不多辞让；事焉不借人，不多食乎力，不贱贪污；行殊乎俗，不多辟异；为在从众，不贱佞谄；世之爵禄不足以为劝，戮耻不足以为辱；知是非之不可为分，细大之不可为倪。闻曰：『道人不闻，至德不得，大人无己。』约分之至也。」
河伯曰：「若物之外，若物之内，恶至而倪贵贱？恶至而倪小大？」
北海若曰：「以道观之，物无贵贱；以物观之，自贵而相贱；以俗观之，贵贱不在己。以差观之，因其所大而大之，则万物莫不大；因其所小而小之，则万物莫不小；知天地之为稊米也，知（毫）[豪]末之为丘山也，则差数睹矣。以功观之，因其所有而有之，则万物莫不有；因其所无而无之，则万物莫不无；知东西之相反而不可以相无，则功分定矣。以趣观之，因其所然而然之，则万物莫不然；因其所非而非之，则万物莫不非；知尧、桀之自然而相非，则趣操睹矣。
昔者尧舜让而帝，之哙让而绝；汤武争而王，白公争而灭。由此观之，争让之礼，尧桀之行，贵贱有时，未可以为常也。梁丽可以冲城，而不可以窒穴，言殊器也；骐骥骅骝，一日而驰千里，捕鼠不如狸狌，言殊技也；鸱鸺夜撮蚤，察毫末，昼出瞋目而不见丘山，言殊性也。故曰，盖师是而无非，师治而无乱乎？是未明天地之理，万物之情者也。是犹师天而无地，师阴而无阳，其不可行明矣。然且语而不舍，非愚则诬也。帝王殊禅，三代殊继。差其时，逆其俗者，谓之篡夫；当其时，顺其俗者，谓之义[之]徒。默默乎河伯！女恶知贵贱之门，小大之家！」
河伯曰：「然则我何为乎？何不为乎？吾辞受趣舍，吾终奈何？」
北海若曰：「以道观之，何贵何贱，是谓反衍；无拘而志，与道大蹇。何少何多，是谓谢施；无一而行，与道参差。严乎若国之有君，其无私德；繇繇乎若祭之有社，其无私福；泛泛乎其若四方之无穷，其无所畛域。兼怀万物，其孰承翼？是谓无方。万物一齐，孰短孰长？道无终始，物有死生，不恃其成；一虚一满，不位乎其形。年不可举，时不可止；消息盈虚，终则有始。是所以语大义之方，论万物之理也。物之生也，若骤若驰，无动而不变，无时而不移。何为乎，何不为乎？夫固将自化。」
河伯曰：「然则何贵于道邪？」
北海若曰：「知道者必达于理，达于理者必明于权，明于权者不以物害己。至德者，火弗能热，水弗能溺，寒暑弗能害，禽兽弗能贼。非谓其薄之也，言察乎安危，宁于祸福，谨于去就，莫之能害也。故曰，天在内，人在外，德在乎天。知天人之行，本乎天，位乎得，蹢䠱而屈伸，反要而语极。」
曰：「何谓天？何谓人？」
北海若曰：「牛马四足，是谓天；落马首，穿牛鼻，是谓人。故曰，无以人灭天，无以故灭命，无以得殉名。谨守而勿失，是谓反其真。」
夔怜蚿，蚿怜蛇，蛇怜风，风怜目，目怜心。
夔谓蚿曰：「吾以一足趻踔而行，予无如矣。今子之使万足，独柰何？」
蚿曰：「不然。子不见夫唾者乎？喷则大者如珠，小者如雾，杂而下者不可胜数也。今予动吾天机，而不知其所以然。」
蚿谓蛇曰：「吾以众足行，而不及子之无足，何也？」
蛇曰：「夫天机之所动，何可易邪？吾安用足哉！」
蛇谓风曰：「予动吾脊胁而行，则有似也。今子蓬蓬然起于北海，蓬蓬然入于南海，而似无有，何也？」
风曰：「然，予蓬蓬然起于北海而入于南海也，然而指我则胜我，鳅我亦胜我。虽然，夫折大木，蜚大屋者，唯我能也。故以众小不胜为大胜也。为大胜者，唯圣人能之。」
孔子游于匡，宋人围之数匝，而弦歌不惙。子路入见，曰：「何夫子之娱也？」
孔子曰：「来，吾语女。我讳穷久矣，而不免，命也；求通久矣，而不得，时也。当尧舜而天下无穷人，非知得也；当桀纣而天下无通人，非知失也，时势适然。夫水行不避蛟龙者，渔父之勇也；陆行不避兕虎者，猎夫之勇也；白刃交于前，视死若生者，烈士之勇也；知穷之有命，知通之有时，临大难而不惧者，圣人之勇也。由处矣！吾命有所制矣。」
无几何，将甲者进，辞曰：「以为阳虎也，故围之。今非也，请辞而退。」
公孙龙问于魏牟曰：「龙少学先王之道，长而明仁义之行；合同异，离坚白；然不然，可不可；困百家之知，穷众口之辩；吾自以为至达已。今吾闻庄子之言，茫焉异之。不知论之不及与，知之弗若与？今吾无所开吾喙，敢问其方。」
公子牟隐机大息，仰天而笑曰：「子独不闻夫埳井之蛙乎？谓东海之鳖曰：『吾乐与！出跳梁乎井干之上，入休乎缺甃之崖；赴水则接腋持颐，蹶泥则没足灭跗；还虷蟹与科斗，莫吾能若也。且夫擅一壑之水，而跨跱埳井之乐，此亦至矣，夫子奚不时来入观乎！』东海之鳖左足未入，而右膝已絷矣。于是逡巡而却，告之海曰：『夫千里之远，不足以举其大；千仞之高，不足以极其深。禹之时十年九潦，而水弗为加益；汤之时八年七旱，而崖不为加损。夫不为顷久推移，不以多少进退者，此亦东海之大乐也。』于是埳井之蛙闻之，适适然惊，规规然自失也。
且夫知不知是非之竟，而犹欲观于庄子之言，是犹使蚊负山，商蚷驰河也，必不胜任矣。且夫知不知论极妙之言，而自适一时之利者，是非埳井之蛙与？且彼方跐黄泉而登大皇，无南无北，奭然四解，沦于不测；无东无西，始于玄冥，反于大通。子乃规规然而求之以察，索之以辩，是直用管窥天，用锥指地也，不亦小乎！子往矣！且子独不闻夫寿陵馀子之学于邯郸与？未得国能，又失其故行矣，直匍匐而归耳。今子不去，将忘子之故，失子之业。」
公孙龙口呿而不合，舌举而不下，乃逸而走。
庄子钓于濮水，楚王使大夫二人往先焉，曰：「愿以境内累矣！」
庄子持竿不顾，曰：「吾闻楚有神龟，死已三千岁矣，王巾笥而藏之庙堂之上。此龟者，宁其死为留骨而贵乎？宁其生而曳尾于涂中乎？」
二大夫曰：「宁生而曳尾涂中。」
庄子曰：「往矣！吾将曳尾于涂中。」
惠子相梁，庄子往见之。或谓惠子曰：「庄子来，欲代子相。」于是惠子恐，搜于国中三日三夜。
庄子往见之，曰：「南方有鸟，其名为鹓雏，子知之乎？夫鹓雏，发于南海而飞于北海，非梧桐不止，非练实不食，非醴泉不饮。于是鸱得腐鼠，鹓雏过之，仰而视之曰：『吓！』今子欲以子之梁国而吓我邪？」
庄子与惠子游于濠梁之上。
庄子曰：「儵鱼出游从容，是鱼之乐也。」
惠子曰：「子非鱼，安知鱼之乐？」
庄子曰：「子非我，安知我不知鱼之乐？」
惠子曰「我非子，固不知子矣；子固非鱼也，子之不知鱼之乐，全矣！」
庄子曰：「请循其本。子曰『汝安知鱼乐』云者，既已知吾知之而问我，我知之濠上也。」', '', '时：按时令。
灌：奔注。河：黄河。
泾（jīng）：通「径」，直流的水波，此指水流。
不辨：分不清。
旋：转，改变。
望洋：仰视的样子。
伯夷：商孤竹君之子，与弟叔齐争让王位，被认为节义高尚之士。
子：原指海神若，此指海水。
长：永远。大方之家：有学问的人。
鼃：同蛙。
虚：同「墟」，居住的地方。
笃（dú）：固。引申为束缚、限制。
曲士：孤陋寡闻的人。
丑：鄙陋，缺乏知识。
大理：大道。
尾闾（lǘ）：海的底部，排泄海水的地方。
虚：流空。
过：超过。
自多：自夸。
大：同「太」。
方：正。
存：察，看到。
见（xiàn）：显得。
奚：何，怎么。
礨（lěi）空：蚁穴，小孔穴。礨，石块。
大泽：大湖泊。
稊米：泛指细小的米粒。
号：称。
连：继续。
仁人：指专门讲仁义的儒家者流。
任士：指身体力行的墨家者流。墨家以任劳以成人之所急为己任，故称。
分（fèn）：分性、秉赋。
无常：不固定。
故：同「固」。
大知（zhì）：大智大慧的人。
知量：知道物量。
曏：明。
故：古。
不闷：不昏暗，即「明白」。闷，昧，暗。
掇（dūo）：伸手可拾，表示近。
不跂：不可企求。跂，通「企」，求。
分（fèn愤）：界限，盈虚得失的界限。
坦涂：大道。涂，同「途」。
说：通「悦」。
至大之域：无穷大的境界。
倪（ní）：头绪，引申为标准、界限。
不可围：不可限制，没有范围。
信：真实。
垺（fú）：同「郛」，郭，城墙。
殷：盛大。
异便：不同的区别。便，通「辨」。
期：凭借。
数：数字。
不期：不可能。
大人：得道的大人先生。
多：赞美、歌颂。
辟异：傲慢怪辟。
倪：标准。
道人：得道的人。
不闻：不求名声。
至德：品德极高的人。
不得：不自显其德。
大人：伟大的人。
无己：忘我。
恶（wū）至：什么标准。
差：差别。
差数：差别的概念。
等：相同。
功分（fèn）：功利的性分。
趣：通「趋」，思想倾向。
操：主观标准。睹：可见。
之：燕国相名子之。
哙：燕王名哙。燕王哙于周慎靓王五年（公元前316年），用苏代之说，让王位给国相子之，燕人不服，大乱。齐乘机伐燕，杀哙与子之，燕国也几乎灭亡。
白公：白公胜，楚平王孙，他父亲太子建，因受陷害而流亡国外，生白公胜。后来白公胜回国，为了争夺政权发动武装政变，事败身亡。
常：不变的规律。
丽：通「欐」，屋栋。
性：才性。
师：推崇。
女：汝。
家、门：范围、界限。
趣：求取。
反衍（yǎn）：反方向发展。衍，通「延」，发展。
无：勿。而：你。
道：大道。
蹇（jiǎn）：阻塞，引申为抵触。
谢：代谢，衰落。
施：移，转。
严：通「俨」。
有：语助词。
繇（yóu）繇乎：坦然自得的样子。
社：土地神。
畛（zhěn）域：疆界。
翼：庇爱，偏护。
成：万物之成形。
位：守住、固定。
不位：不固定。
举：提取。
消：消亡。
息：生长。
大义：大道。
方：方向、原则。
权：权衡轻重而应变。
薄：迫近，引申为触犯。
蹢躅（zhízhú）：或作「踯躅」，进退的样子。
反：通「返」。
极：尽。
落：络，笼住。', '秋天里洪水按时到来，千百条江河注入黄河，直流的水畅通无阻，两岸和水中沙洲之间连牛马都不能分辨。在这个情况下河伯高兴地自得其乐，认为天下一切美景全都聚集在自己这里。河伯顺着水流向东而去，来到北海边，面朝东边一望，看不见大海的尽头。在这个时候河伯转变了原来欣然自得的表情，面对海神若仰首慨叹道：「有句俗话说，『听到了许多道理，就以为没有人比得上自己』，说的就是我这样的人了。况且我曾听说有人认为孔子的见闻浅陋，伯夷的道义微不足道，开始我还不相信；如今我看见您的广阔无边，我如果不是来到您的家门前，那就危险了，我将永远的被懂得大道理的人耻笑。」
北海神若说：「对井里的青蛙不能够与它谈论关于大海的事情，是因为井口局限了它的眼界；夏天的虫子不能够与它谈论关于冰雪的事情，是因为它被生存的时令所限制；对见识浅陋的人不可与他谈论道理的问题，是因为他的眼界受着教养的束缚。如今你从河岸流出来，看到大海后，才知道你的不足，这就可以与你谈论道理了。天下的水，没有比海更大的了。万千条江河归向大海，不知什么时候停止，可大海却不会满溢出来；海底的尾闾泄漏海水，不知什么时候才会停止，但海水却不曾减少；海水不因季节的变化而有所增减，也不因水灾旱灾而受影响。这说明了它的容量超过长江、黄河的容量，不可计数。但是我未曾藉此自我夸耀，因为自从天地之间生成形态，从那里汲取阴阳之气，我在天地里面，犹如小石小木在大山上一样，正感觉自己见到的太少，又哪里还能自傲呢？计算一下四海在天地间，不像小小的蚁穴在巨大的水泽里吗？计算一下中原在天下，不像细小的米粒在大粮仓中吗？人们用「万」这个数字来称呼物类，人不过占其中之一；人类遍布天下，谷物所生长的地方，车船所通达的地方都有人，每人只是占其中的一个；这表明人与万物相比，不像毫毛的末梢在马体上吗？五帝所连续统治的，三王所争夺的，仁人所担忧的，以天下为己任的贤人所劳碌的，全不过如此而已。伯夷以辞让君王位置而博得名声，孔子以谈论天下而显示渊博，他们这样自我夸耀，不正像你先前看到河水上涨而自满一样吗？」
河伯说：「那么我把天地看作是最大，把毫末之末看作是最小，可以吗？」
海神回答：「不可以。万物的量是无穷无尽的，时间是没有终点的，得与失的禀分没有不变的常规，事物的终结和起始也没有固定。所以具有大智的人观察事物从不局限于一隅，因而体积小却不看作就是少，体积大却不看作就是多，这是因为知道事物的量是不可穷尽的；证验并明察古往今来的各种情况，因而寿命久远却不感到厌倦，生命只在近前却不会企求寿延，这是因为知道时间的推移是没有止境的；洞悉事物有盈有虚的规律，因而有所得却不欢欣喜悦，有所失也不悔恨忧愁，这是因为知道得与失的禀分是没有定规的；明了生与死之间犹如一条没有阻隔的平坦大道，因而生于世间不会倍加欢喜，死离人世不觉祸患加身，这是因为知道终了和起始是不会一成不变的。算算人所懂得的知识，远远不如他所不知道的东西多，他生存的时间，也远远不如他不在人世的时间长；用极为有限的智慧去探究没有穷尽的境域，所以内心迷乱而必然不能有所得！由此看来，又怎么知道毫毛的末端就可以判定是最为细小的限度呢？又怎么知道天与地就可以看作是最大的境域呢？」
河神说：「世间议论的人们总是说：『最细小的东西没有形体可寻，最巨大的东西不可限定范围』。这样的话是真实可信的吗？」
海神回答：「从细小的角度看庞大的东西不可能全面，从巨大的角度看细小的东西不可能真切。精细，是小中之小；庞大，是大中之大；不过大小虽有不同却各有各的合宜之处。这就是事物固有的态势。所谓精细与粗大，仅限于有形的东西，至于没有形体的事物，是不能用计算数量的办法来加以剖解的；而不可限定范围的东西，更不是用数量能够精确计算的。可以用言语来谈论的东西，是事物粗浅的外在表象；可以用心意来传告的东西，则是事物精细的内在实质。言语所不能谈论的，心意所不能传告的，也就不限于精细和粗浅的范围了。所以修养高尚者的行动，不会出于对人的伤害，也不会赞赏给人以仁慈和恩惠；无论干什么都不是为了私利，也不会轻视从事守门差役之类的人。无论什么财物都不去争夺，也不推重谦和与辞让；凡事从不借助他人的力气，但也不提倡自食其力，同时也不鄙夷贪婪与污秽；行动与世俗不同，但不主张邪僻乖异；行为追随一般的人，也不以奉承和谄媚为卑贱；人世间的所谓高官厚禄不足以作为劝勉，刑戮和侮辱不足以看作是羞耻；知道是与非的界线不能清楚地划分，也懂得细小和巨大不可能确定清晰的界限。听人说：『能体察大道的人不求闻达于世，修养高尚的人不会计较得失，清虚宁寂的人能够忘却自己』。这就是约束自己而达到适得其分的境界。」
河神说：「如此事物的外表，如此事物的内在，从何处来区分它们的贵贱？又怎么来区别它们的大小？」
海神回答：「用自然的常理来看，万物本没有贵贱的区别。从万物自身来看，各自为贵而又以他物为贱。拿世俗的观点来看，贵贱不在于事物自身。按照物与物之间的差别来看，顺着各种物体大的一面去观察便会认为物体是大的，那么万物就没有什么不是大的；顺着各种物体小的一面去观察便会认为物体是小的，那么万物没有什么不是小的；知晓天地虽大比起更大的东西来也如小小的米粒，知晓毫毛之末虽小比起更小的东西来也如高大的山丘，而万物的差别和数量也就看得很清楚了。依照事物的功用来看，顺着物体所具有的一面去观察便会认为具有了这样的功能，那么万物就没有什么不具有这样的功能；顺着物体所不具有的一面去观察便会认为不具有这样的功能，那么万物就没有什么具有了这样的功能；可知东与西的方向对立相反却又不可以相互缺少，而事物的功用与本分便得以确定。从人们对事物的趋向来看，顺着各种事物肯定的一面去观察便会认为是对的，那么万物没有什么不是对的；顺着各种事物否定的一面去观察便会认为是不对的，那么万物没有什么不是错的；知晓唐尧和夏桀都自以为正确又相互否定对方，而人们的趋向与持守也就看得很清楚了。当年唐尧、虞舜禅让而称帝，宰相子之与燕王哙禅让而燕国几乎灭亡；商汤、周武王都争夺天下而成为帝王，白公胜争夺王位却遭致杀身。由此看来，争斗与禅让的礼制，唐尧与夏桀的作法，让可还是鄙夷都会因时而异，不可以把它们看作是不变的规律。栋梁之材可以用来冲击敌城，却不可以用来堵塞洞穴，说的是器物的用处不一样。骏马良驹一天奔驰上千里，捕捉老鼠却不如野猫与黄鼠狼，说的是技能不一样。猫头鹰夜里能抓取小小的跳蚤，细察毫毛之末，可是大白天睁大眼睛也看不见高大的山丘，说的是禀性不一样。所以说：怎么只看重对的一面而忽略不对的一面、看重治而忽略乱呢？这是因为不明了自然存在的道理和万物自身的实情。这就像是重视天而轻视地、重视阴而轻视阳，那不可行是十分明白的了。然而还是要谈论不休，不是愚昧便是欺骗！远古帝王的禅让各不相同，夏、商、周三代的继承也各不一样。不合时代、背逆世俗的人，称他叫篡逆之徒；合于时代、顺应世俗的人，称他叫高义之士。沉默下来吧，河神！你怎么会懂得万物间贵贱的门庭和大小的流别！」
河神说：「既然这样，那么我应该做些什么呢？又应该不做什么呢？我将怎样推辞或接纳、趋就或舍弃，我终究将怎么办？」
海神回答：「用道的观点来观察，什么是贵什么是贱，这可称之为循环往复；不必束缚你的心志，而跟大道相违碍。什么是少什么是多，这可称之为更替续延；不要偏执于事物的某一方面行事，而跟大道不相一致。端庄、威严的样子像是一国的国君，确实没有一点儿偏私的恩惠；优游自得的样子像是祭祀中的土地神，确实没有任何偏私的赐福；浩瀚周遍的样子像是通达四方而又旷远无穷，确实没有什么区分界限；兼蓄并且包藏万物，难道谁专门有所承受或者有所庇护？这就称作不偏执于事物的任何一个方面。宇宙万物本是浑同齐一的，谁优谁劣呢？大道没有终结和起始，万物却都有死有生，因而不可能依仗一时的成功。时而空虚时而充实，万物从不固守于某一不变的形态。岁月不可以挽留，时间从不会停息，消退、生长、充实、空虚，宇宙万物终结便又有了开始。这样也就可以谈论大道的准则，评说万物的道理了。万物的生长，像是马儿飞奔像是马车疾行，没有什么举动不在变化，没有什么时刻不在迁移。应该做些什么呢？又应该不做什么呢？一切必定都将自然地变化！」
河神说：「既然如此，那么为什么还要那么看重大道呢？
海神回答：「懂得大道的人必定通达事理，通达事理的人必定明白应变，明白应变的人定然不会因为外物而损伤自己。道德修养高尚的人烈焰不能烧灼他们，洪水不能沉溺他们，严寒酷暑不能侵扰他们，飞禽走兽不能伤害他们。不是说他们逼近水火、寒暑的侵扰和禽兽的伤害而能幸免，而是说他们明察安危，安于祸福，慎处离弃与追求，因而没有什么东西能够伤害他们。所以说：「天然蕴含于内里，人为显露于外在，高尚的修养则顺应自然。懂得人的行止，立足于自然的规律，居处于自得的环境，徘徊不定，屈伸无常，也就返归大道的要冲而可谈论至极的道理。」
河神说：「什么是天然？什么又是人为？」
海神回答：「牛马生就四只脚，这就叫天然；用马络套住马头，用牛鼻绾穿过牛鼻，这就叫人为。所以说，不要用人为去毁灭天然，不要用有意的作为去毁灭自然的禀性，不要为获取虚名而不遗余力。谨慎地持守自然的禀性而不丧失，这就叫返归本真。」
蛇与风
独脚的夔羡慕多脚的蚿，多脚的蚿羡慕无脚的蛇，无脚的蛇羡慕无形的风，无形的风羡慕明察外物的眼睛，明察外物的眼睛羡慕内在的心灵。
夔对蚿说：“我依靠一只脚跳跃而行，没有谁再比我简便的了。现在你使用上万只脚行走，竟是怎么样的呢？”蚿说：“不对哩。你没有看见那吐唾沫的情形吗？喷出唾沫大的像珠子，小的像雾滴，混杂着吐落而下的不可以数计。如今我启动我天生的机能而行走，不过我也并不知道自己为什么能够这样。”
蚿对蛇说：“我用众多的脚行走反倒不如你没有脚，这是为什么呢？”蛇说：“仰赖天生的机能而行动，怎么可以改变呢？我哪里用得着脚呢！”
蛇对风说：“我启动我的脊柱和腰胁而行走，还是像有足而行的样子。如今你呼呼地从北海掀起，又呼呼地驾临南海，却没有留下有足而行的形迹，这是为什么呢？”风说：“是的，我呼呼地从北海来到南海。可是人们用手来阻挡我而我并不能吹断手指，人们用腿脚来踢踏我而我也不能吹断腿脚。即使这样，折断大树、掀翻高大的房屋，却又只有我能够做到，而这就是细小的方面不求胜利而求获得大的胜利。获取大的胜利，只有圣人才能做到。”
孔子与子路
孔子周游到匡地，宋国人一层又一层地包围了他，可是孔子仍在不停地弹琴诵读。子路入内见孔子说：“先生如此欢心是为什么呢？”孔子说：“来，我告诉你！我违忌困窘蔽塞已经很久很久了，可是始终不能免除，这是命运啊。我寻求通达也已经很久很久了，可是始终未能达到，这是时运啊。当尧、舜的时代，天下没有一个困顿潦倒的人，并非因为他们都才智超人;当桀、纣的时代，天下没有一个通达的人，并非因为他们都才智低下。这都是时运所造成的。在水里活动而不躲避蛟龙的，乃是渔夫的勇敢;在陆上活动而不躲避犀牛老虎的，乃是猎人的勇敢;刀剑交错地横于眼前，看待死亡犹如生还的，乃是壮烈之士的勇敢。懂得困厄潦倒乃是命中注定，知道顺利通达乃是时运造成，面临大难而不畏惧的，这就是圣人的勇敢。仲由啊，你还是安然处之吧！我命中注定要受制啊！”
没有过多久，统带士卒的将官走了进来，深表歉意地说：“大家把你看作是阳虎，所以包围了你;现在知道了你不是阳虎，请让我向你表示歉意并且撤离部队。”
公孙龙与魏牟
公孙龙向魏牟问道：“我年少的时候学习古代圣王的主张，长大以后懂得了仁义的行为;能够把事物的不同与相同合而为一，把一个物体的质地坚硬与颜色洁白分离开来;能够把不对的说成是对的，把不应认可的看作是合宜的;能够使百家智士困惑不解，能够使众多善辩之口理屈辞穷：我自以为是最为通达的了。如今我听了庄子的言谈，感到十分茫然。不知是我的论辩比不上他呢，还是我的知识不如他呢？现在我已经没有办法再开口了，冒昧地向你请教其中的道理。”
魏牟靠着几案深深地叹了口气，然后又仰头朝天笑着说：“你不曾听说过那浅井里的青蛙吗？井蛙对东海里的鳖说：‘我实在快乐啊！我跳跃玩耍于井口栏杆之上，进到井里便在井壁砖块破损之处休息。跳入水中井水漫入腋下并且托起我的下巴，踏入泥里泥水就盖住了我的脚背，回过头来看看水中的那些赤虫、小蟹和蝌蚪，没有谁能像我这样的快乐！再说我独占一坑之水、盘踞一口浅井的快乐，这也是极其称心如意的了。你怎么不随时来井里看看呢？’东海之鳖左脚还未能跨入浅井，右膝就已经被绊住。于是迟疑了一阵子之后又把脚退了出来，把大海的情况告诉给浅井的青蛙，说：‘千里的遥远，不足以称述它的大;千仞的高旷，不足于探究它的深。夏禹时代十年里有九年水涝，而海水不会因此增多;商汤的时代八年里有七年大旱，而岸边的水位不会因此下降。不因为时间的短暂与长久而有所改变，不因为雨量的多少而有所增减，这就是东海最大的快乐。’浅井之蛙听了这一席话，惊惶不安，茫然不知所措。再说你公孙龙的才智还不足以知晓是与非的境界，却还想去察悉庄子的言谈，这就像驱使蚊虫去背负大山，驱使马蚿虫到河水里去奔跑，必定是不能胜任的。而你的才智不足以通晓极其玄妙的言论，竟自去迎合那些一时的胜利，这不就像是浅井里的青蛙吗？况且庄子的思想主张正俯极黄泉登临苍天，不论南北，释然四散通达无阻，深幽沉寂不可探测;不论东西，起于幽深玄妙之境，返归广阔通达之域。你竟拘泥浅陋地用察视的办法去探寻它的奥妙，用论辩的言辞去索求它的真谛，这只不过是用竹管去窥视高远的苍天，用锥子去测量浑厚的大地，不是太渺小了吗！你还是走吧！而且你就不曾听说过那燕国寿陵的小子到赵国的邯郸去学习走步之事吗？未能学会赵国的本事，又丢掉了他原来的本领，最后只得爬着回去了。现在你还不尽快离开我这里，必将忘掉你原有的本领，而且也必将失去你原有的学业。”
公孙龙听了这一番话张大著口而不能合拢，舌头高高抬起而不能放下，于是快速地逃走了。
庄子与楚臣
庄子在濮水边垂钓，楚王派遣两位大臣先行前往致意，说：“楚王愿将国内政事委托给你而劳累你了。”
庄子手把钓竿头也不回地说：“我听说楚国有一神龟，被杀死的时候已经活了三千年了，楚王用竹箱装着它，用巾饰覆盖着它，珍藏在宗庙里。这只神龟，是宁愿死去为了留下骨骸而显示尊贵呢，还是宁愿活着在泥水里拖着尾巴呢？”两位大臣说：“宁愿拖着尾巴活在泥水里。”庄子说：“你们走吧！我仍将拖着尾巴生活在泥水里。”
庄子与惠子
惠子在梁国做宰相，庄子前往看望他。有人对惠子说：“庄子来梁国，是想取代你做宰相。”于是惠子恐慌起来，在都城内搜寻庄子，整整三天三夜。
庄子前往看望惠子，说：“南方有一种鸟，它的名字叫鹓。你知道吗？从南海出发飞到北海，不是梧桐树它不会停息，不是竹子的果实它不会进食，不是甘美的泉水它不会饮用。正在这时一只鹞鹰寻觅到一只腐烂了的老鼠，鹓*刚巧从空中飞过，鹞鹰抬头看着鹓，发出一声怒气：‘吓’！如今你也想用你的梁国来怒叱我吗？”
庄子和惠子一道在濠水的桥上游玩。庄子说：“白儵鱼游得多么悠闲自在，这就是鱼儿的快乐。”惠子说：“你不是鱼，怎么知道鱼的快乐？”庄子说：“你不是我，怎么知道我不知道鱼儿的快乐？”惠子说：“我不是你，固然不知道你;你也不是鱼，你不知道鱼的快乐，也是完全可以肯定的。”庄子说：“还是让我们顺着先前的话来说。你刚才所说的‘你在哪里知道鱼的快乐’的话，就是已经知道了我知道鱼儿的快乐而问我，而我则是在濠水的桥上知道鱼儿快乐的。”', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf6c2cee9a0c24edabc1", "shortContent": "《观渔赋》是戴表元为数不多的赋作之一，笔调清新流畅，文辞简洁传神，深得其文之精髓。此赋是一篇对话体的哲理赋，写河滨童子捕鱼的情形与作者的观感，以类似寓言的方式比喻说理，向人们阐释了这样一个真理：只有经过一番艰辛的探索，在艰苦的环境中不断锻炼自我，才能最终取得伟大的成就。运用类比论证，摆脱了赋体惯有的堂皇的议论，而完全立足于人生的真实体验，发人深省。\n开篇即以工笔细细描绘出一幅童子捕鱼图：落潮之后，...", "authors": ["李占鹏", "金艳霞"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d10f8fda556506157b", "shortContent": "《秋水》在《庄子》外篇中是最重要的，它以河伯和海若对话的形式，讨论了“价值判断的无穷相对性”（陈鼓应《庄子今注今译》）。这里截选前一大半，也是本篇最主要的内容。十四个自然段一共七问七答，可以分成七大部分。\n第一番问答可以看成探讨问题的开端。庄子在这篇里谈论的是严肃而玄妙的哲学问题，在别人的笔下也许会写得苦涩无味，令人昏昏欲睡；庄子则不然，他以水为喻，引出河伯和海若的对话，两个虚构的主人公却写得活灵...", "authors": ["周本淳"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1e25914587d02f5a029", "shortContent": "宋文帝元嘉二十九年壬辰（452），鲍照三十九岁。这一年，他从南兖州（治广陵，即今江苏扬州）返回建业（今南京），途经瓜步山而作此文。瓜步山在今江苏南京市六合区境内，东临长江，六朝时是长江的重要渡口。“楬”（音杰）是用作标志的小木桩。《周礼·秋官·蜡氏》说：“若有死于道路者，则令埋而置楬焉。”而为一山作楬文，则是鲍照的独创，其写法也有创新，实际上是一篇寓言小品。\n全文可分两段。从首句至“才之多少，不如...", "authors": ["刘文忠"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed2110f8fda556506160b", "shortContent": "此文写于道光十六年（1836）。吴昌绶《定盦先生年谱》于此年云：“友人王元凤以陈州知府获谴，戍军台，托弱小于先生所。先生乞假五日，送之居庸关，逾八达岭而返。时方修《蒙古图志》，属元凤为图所阙部落山形，以门禁严，不果。先生居京师久，尝东游至永平境，此行又北至宣化境，因作纪游合一卷（原注：已佚），犹恨未至卢龙关、独石口，尽窥东北两边形势也。”这里把本文的写作背景交代颇详。文章本身充分说明它不仅是写居庸...", "authors": ["孙钦善"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f882e6a6b501f974b75", "shortContent": "魏晋以降，经六朝而至中唐，中国古典笔记小说的文体形式渐由志怪而朝传奇化方向演进，一个基本标志是，即使志怪，也“以传奇为风骨”。伴随着这种变化，小说的主人公也开始由鬼神而让位于异人。薛用弱的《集异记》正是这一历史性情感变化的美学记录，本篇《李子牟》作为它所展示的一条艺苑风景线，以一个独特的视角，准确地记述了精彩绝艳的盛唐之音在有唐一代社会结构和心理层次中的种种回响和延续。\n与中晚唐志怪传奇的柔婉清秀...", "authors": ["赵莱静"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9103048e64fbda97c3", "shortContent": "这是一篇东方的《渔夫和金鱼的故事》。和普希金的童话相比较，我们会发现许多东西方文化上的差异。这两个故事中，渔夫捕到的都是一种会说话的鱼，普希金童话中的鱼外形上只是一条普通的金鱼，而这篇志怪中的鱼却是“人面龟身，腹有数十足，颈下有两手如人手。其背似鳖，细视项有短发甚密，脑后又有一目，胸腹五色”，作者不惜笔墨地描写这种根本不存在的异鱼，正是志怪小说那种“记殊方异物”的特点决定的，也表现出东方的“成年人...", "authors": ["陈建生"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9a03048e64fbda97f8", "shortContent": "《聊斋志异》描写了许多美丽可爱的狐仙，歌颂了她们善良高尚的品格，表现了作者的生活理想。但这篇《刘海石》写的却是一个狡猾凶毒的狸精。她变成一个美丽的女子，被刘沧客纳为宠妾。她“吸人神气以为灵”，不久，便害死了刘的妻子、长子、长媳及若干婢仆，刘沧客本人和次子、次媳及其他婢仆也并受其毒，危在旦夕。如果不是刘海石识破真相，几遭灭门之祸。这个凶毒的狸精，在真相暴露之后仍然凶心不死，请求勿拔能使其变人作恶的脑...", "authors": ["许金榜"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa334a8757d5a0fa501", "shortContent": "封建社会，“选士而论族姓阀阅”，阶级成分很重要。本篇中柴四的职业是贩羊。他的“档案袋”里履历表只有这样填：家庭成分，贩羊；本人出身，贩羊。也算是贩羊世家了吧。按理成分是不能选择的，但前途可由自己挑选。可是也难，明清科举题名录，凡读书人应举，都要填明父祖履历，这种传统已形成社会共识。贩羊者自是小商，小商在农耕社会中更没有地位。因此即使是柴四为自己职业多作解释和辩护，也是徒劳的，用荀孺子话说，“两世贩...", "authors": ["盛巽昌"], "pressName": "上海辞书出版社"}]', '', 'indent', 1524911284, '5ae3dc2b7f6fd30038448264', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637411, '庄子 · 外篇 · 至乐', NULL, 12, 573, 1, 2, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E5%A4%96%E7%AF%87%C2%B7%E8%87%B3%E4%B9%90/10191849?fr=aladdin', '', '天下有至乐无有哉？有可以活身者无有哉？今奚为奚据？奚避奚处？奚就奚去？奚乐奚恶？
夫天下之所尊者，富贵寿善也；所乐者，身安厚味美服好色音声也；所下者，贫贱夭恶也；所苦者，身不得安逸，口不得厚味，形不得美服，目不得好色，耳不得音声；若不得者，则大忧以惧。其为形也亦愚哉。
夫富者，苦身疾作，多积财而不得尽用，其为形也亦外矣。夫贵者，夜以继日，思虑善否，其为形也亦疏矣。人之生也，与忧俱生，寿者惽惽，久忧不死，何苦也！其为形也亦远矣。烈士为天下见善矣，未足以活身。吾未知善之诚善邪，诚不善邪？若以为善矣，不足活身；以为不善矣，足以活人。故曰：“忠谏不听，蹲循勿争。”故夫子胥争之以残其形，不争，名亦不成。诚有善无有哉？
今俗之所为与其所乐，吾又未知乐之果乐邪，果不乐邪？吾观夫俗之所乐，举群趋者，誙誙然如将不得已，而皆曰乐者，吾未之乐也，亦未之不乐也。果有乐无有哉？吾以无为诚乐矣，又俗之所大苦也。故曰：“至乐无乐，至誉无誉。”
天下是非果未可定也。虽然，无为可以定是非。至乐活身，唯无为几存。请尝试言之。天无为以之清，地无为以之宁，故两无为相合，万物皆化。芒乎芴乎，而无从出乎！芴乎芒乎，而无有象乎！万物职职，皆从无为殖。故曰天地无为也而无不为也，人也孰能得无为哉！
庄子妻死，惠子吊之，庄子则方箕踞鼓盆而歌。惠子曰：“与人居，长子老身，死不哭亦足矣，又鼓盆而歌，不亦甚乎！”
庄子曰：“不然。是其始死也，我独何能无概然！察其始而本无生，非徒无生也而本无形，非徒无形也而本无气。杂乎芒芴之间，变而有气，气变而有形，形变而有生，今又变而之死，是相与为春秋冬夏四时行也。人且偃然寝于巨室，而我噭噭然随而哭之，自以为不通乎命，故止也。”
支离叔与滑介叔观于冥伯之丘、昆仑之虚，黄帝之所休。俄而柳生其左肘，其意蹶蹶然恶之。支离叔曰：“子恶之乎？”滑介叔曰：“亡，子何恶！生者，假借也；假之而生生者，尘垢也。死生为昼夜。且吾与子观化而化及我，我又何恶焉！”
庄子之楚，见空髑髅，髐然有形，撽以马捶因而问之，曰：“夫子贪生失理，而为此乎？将子有亡国之事，斧钺之诛，而为此乎？将子有不善之行，愧遗父母妻子之丑，而为此乎？将子有冻馁之患，而为此乎？将子之春秋故及此乎？”于是语卒，援髑髅，枕而卧。
夜半，髑髅见梦曰：“子之谈者似辩士。视子所言，皆生人之累也，死则无此矣。子欲闻死之说乎？”庄子曰：“然。”髑髅曰：“死，无君于上，无臣于下；亦无四时之事，从然以天地为春秋，虽南面王乐，不能过也。”庄子不信，曰：“吾使司命复生子形，为子骨肉肌肤，反子父母妻子闾里知识，子欲之乎？”髑髅深矉蹙额曰：“吾安能弃南面王乐而复为人间之劳乎！”
颜渊东之齐，孔子有忧色。子贡下席而问曰：“小子敢问：回东之齐，夫子有忧色，何邪？”孔子曰：“善哉汝问。昔者管子有言，丘甚善之，曰‘褚小者不可以怀大，绠短者不可以汲深。’夫若是者，以为命有所成而形有所适也，夫不可损益。吾恐回与齐侯言尧、舜、黄帝之道，而重以燧人、神农之言。彼将内求于己而不得，不得则惑，人惑则死。且女独不闻邪？昔者海鸟止于鲁郊，鲁侯御而觞之于庙，奏九韶以为乐，具太牢以为膳。鸟乃眩视忧悲，不敢食一脔，不敢饮一杯，三日而死。此以己养养鸟也，非以鸟养养鸟也。夫以鸟养养鸟者，宜栖之深林，游之坛陆，浮之江湖，食之鳅鲦，随行列而止，逶迤而处。彼唯人言之恶闻，奚以夫譊为乎！咸池九韶之乐，张之洞庭之野，鸟闻之而飞，兽闻之而走，鱼闻之而下入，人卒闻之，相与还而观之。鱼处水而生，人处水而死。彼必相与异，其好恶故异也。故先圣不一其能，不同其事。名止于实，义设于适，是之谓条达而福持。”
列子行，食于道从，见百岁髑髅，攓蓬而指之曰：“唯予与汝知而未尝死、未尝生也。若果养乎？予果欢乎？”
种有几，得水则为，得水土之际则为鼃蠙之衣，生於陵屯则为陵舄，陵舄得郁栖则为乌足。乌足之根为蛴螬，其叶为胡蝶。胡蝶胥也化而为虫，生于灶下，其状若脱，其名为鸲掇。鸲掇千日为鸟，其名为干余骨。干余骨之沫为斯弥，斯弥为食醯。颐辂生乎食醯，黄軦生乎九猷，瞀芮生乎腐蠸。羊奚比乎不箰，久竹生青宁；青宁生程，程生马，马生人，人又反入于机。万物皆出于机，皆入于机。', '', '', '天下有最大的快乐还是没有呢？有可以存活身形的东西还是没有呢？现在，应该做些什么又依据什么？回避什么又安心什么？靠近什么又舍弃什么？喜欢什么又讨厌什么？
世上的人们所尊崇看重的，是富有、高贵、长寿和善名；所爱好喜欢的，是身体的安适、丰盛的食品、漂亮的服饰、绚丽的色彩和动听的乐声；所认为低下的，是贫穷、卑微、短命和恶名；所痛苦烦恼的，是身体不能获得舒适安逸、口里不能获得美味佳肴、外形不能获得漂亮的服饰、眼睛不能看到绚丽的色彩、耳朵不能听到悦耳的乐声；假如得不到这些东西，就大为忧愁和担心，以上种种对待身形的作法实在是太愚蠢啊！
富有的人，劳累身形勤勉操作，积攒了许许多多财富却不能全部享用，那样对待身体也就太不看重了。高贵的人，夜以继日地苦苦思索怎样才会保全权位和厚禄与否，那样对待身体也就太忽略了。人们生活于世间，忧愁也就跟着一道产生，长寿的人整日里糊糊涂涂，长久地处于忧患之中而不死去，多么痛苦啊！那样对待身体也就太疏远了。刚烈之士为了天下而表现出忘身殉国的行为，可是却不足以存活自身。我不知道这样的行为是真正的好呢，还是实在不能算是好呢？如果认为是好行为，却不足以存活自身；如果认为不是好行为，却又足以使别人存活下来。所以说：“忠诚的劝谏不被接纳，那就退让一旁不再去争谏。”伍子胥忠心劝谏以致身受残戮，如果他不努力去争谏，忠臣的美名也就不会成就。那么果真又有所谓好还是没有呢？
如今世俗所从事与所欢欣的，我又不知道那快乐果真是快乐呢，果真不是快乐呢？我观察那世俗所欢欣的东西，大家都全力去追逐，拼死竞逐的样子真像是不达目的决不罢休。人人都说这就是最为快乐的事，而我并不看作就是快乐，当然也不认为不是快乐。那么，世上果真有快乐还是没有呢？我认为无为就是真正的快乐，但这又是世俗的人所感到最痛苦和烦恼的。所以说：“最大的快乐就是没有快乐，最大的荣誉就是没有荣誉。”
天下的是非果真是未可确定的。虽然如此，无为的观点和态度可以确定是非。最大的快乐是使自身存活，而唯有无为算是最接近于使自身存活的了。请让我说说这一点。苍天无为因而清虚明澈，大地无为因而浊重宁寂，天与地两个无为相互结合，万物就全都能变化生长。恍恍惚惚，不知道从什么地方产生出来！惚惚恍恍，没有一点儿痕迹！万物繁多，全从无为中繁衍生殖。所以说，天和地自清自宁无心去做什么却又无所不生无所不做，而人谁又能够做到无为呢！
庄子的妻子死了，惠子前往表示吊唁，庄子却正在分开双腿像簸箕一样坐着，一边敲打着瓦缶一边唱歌。惠子说：“你跟死去的妻子生活了一辈子，生儿育女直至衰老而死，人死了不伤心哭泣也就算了，又敲着瓦缶唱起歌来，不也太过分了吧！”
庄子说：“不对哩。这个人她初死之时，我怎么能不感慨伤心呢！然而仔细考察她开始原本就不曾出生，不只是不曾出生而且本来就不曾具有形体，不只是不曾具有形体而且原本就不曾形成元气。夹杂在恍恍惚惚的境域之中，变化而有了元气，元气变化而有了形体，形体变化而有了生命，如今变化又回到死亡，这就跟春夏秋冬四季运行一样。死去的那个人将安安稳稳地寝卧在天地之间，而我却呜呜地围着她啼哭，自认为这是不能通晓于天命，所以也就停止了哭泣。”
支离叔和滑介叔在冥伯的山丘上和昆仑的旷野里游乐观赏，那里曾是黄帝休息的地方。不一会儿，滑介叔的左肘上长出了一个瘤子，他感到十分吃惊并且厌恶这东西。支离叔说：“你讨厌这东西吗？”滑介叔说：“没有，我怎么会讨厌它！具有生命的形体，不过是借助外物凑合而成；一切假借他物而生成的东西，就像是灰土微粒一时间的聚合和积累。人的死与生也就犹如白天与黑夜交替运行一样。况且我跟你一道观察事物的变化，如今这变化来到了我身上，我又怎么会讨厌它呢！”
庄子到楚国去，途中见到一个髑髅（死人的头盖骨，不同于骷髅，下文“枕而卧”可以推知），枯骨突露呈现出原形。庄子用马鞭从侧旁敲了敲。于是问道：“先生是贪求生命、失却真理，因而成了这样呢？抑或你遇上了亡国的大事，遭受到刀斧的砍杀，因而成了这样呢？抑或有了不好的行为，担心给父母、妻儿子女留下耻辱，羞愧而死成了这样呢？抑或你遭受寒冷与饥饿的灾祸而成了这样呢？抑或你享尽天年而死去成了这样呢？”庄子说罢，拿过髑髅，用作枕头而睡去。
到了半夜，髑髅给庄子显梦说：“你先前谈话的情况真像一个善于辩论的人。看你所说的那些话，全属于活人的拘累，人死了就没有上述的忧患了。你愿意听听人死后的有关情况和道理吗？”庄子说：“好。”髑髅说：“人一旦死了，在上没有国君的统治，在下没有官吏的管辖；也没有四季的操劳，从容安逸地把天地的长久看作是时令的流逝，即使南面为王的快乐，也不可能超过。”庄子不相信，说：“我让主管生命的神来恢复你的形体，为你重新长出骨肉肌肤，返回到你的父母、妻子儿女、左右邻里和朋友故交中去，你希望这样做吗？”髑髅皱眉蹙额，深感忧虑地说：“我怎么能抛弃南面称王的快乐而再次经历人世的劳苦呢？”
颜渊向东到齐国去，孔子十分忧虑。子贡离开座席上前问道：“学生冒昧地请问，颜渊往东去齐国，先生面呈忧色，这是为什么呢？”
孔子说：“你的提问实在是好啊！当年管仲有句话，我认为说得很好：‘布袋小的不可能包容大东西，水桶上的绳索短了不可能汲取深井里的水。’如此说来，就应当看作是禀受天命而形成形体，形体虽异却各有适宜的用处，全都是不可以随意添减改变的。我担忧颜渊跟齐侯谈论尧、舜、黄帝治理国家的主张，而且还进一步地推重燧人氏、神农氏的言论。齐侯必将要求自己而苦苦思索，却仍不能理解，不理解必定就会产生疑惑，一旦产生疑惑便会迁怒对方而杀害他。
“况且你不曾听说过吗？从前，一只海鸟飞到鲁国都城郊外停息下来，鲁国国君让人把海鸟接到太庙里供养献酒，奏‘九韶’之乐使它高兴，用‘太牢’作为膳食。海鸟竟眼花缭乱忧心伤悲，不敢吃一块肉，不敢饮一杯酒，三天就死了。这是按自己的生活习性来养鸟，不是按鸟的习性来养鸟。按鸟的习性来养鸟，就应当让鸟栖息于深山老林，游戏于水中沙洲，浮游于江河湖泽、啄食泥鳅和小鱼，随着鸟群的队列而止息，从容自得、自由自在地生活。它们最讨厌听到人的声音，又为什么还要那么喧闹嘈杂呢？咸池、九韶之类的著名乐曲，演奏于广漠的原野，鸟儿听见了腾身高飞，野兽听见了惊惶逃遁，鱼儿听见了潜下水底，一般的人听见了，相互围着观看不休。鱼儿在水里才能生存，人处在水里就会死去，人和鱼彼此间必定有不同之处，他们的好恶因而也一定不一样。所以前代的圣王不强求他们具有划一的能力，也不等同他们所做的事情。名义的留存在于符合实际，合宜的措置在于适应自然，这就叫条理通达而福德长久地得到保持。”
列子外出游玩，在道旁吃东西，看见一个上百年的死人的头骨，拔掉周围的蓬草指着髑髅说：“只有我和你知道你是不曾死、也不曾生的。你果真忧愁吗？我又果真快乐吗？”
物类千变万化源起于微细状态的“几”，有了水的滋养便会逐步相继而生，处于陆地和水面的交接处就形成青苔，生长在山陵高地就成了车前草，车前草获得粪土的滋养长成乌足，乌足的根变化成土蚕，乌足的叶子变化成蝴蝶。蝴蝶很快又变化成为虫，生活在灶下，那样子就像是蜕皮，它的名字叫做灶马。灶马一千天以后变化成为鸟，它的名字叫做干余骨。干余骨的唾沫长出虫子斯弥，斯弥又生出蠛蠓。颐辂从蠛蠓中形成，黄軦从九猷中长出；蠓子则产生于萤火虫。羊奚草跟不长笋的老竹相结合，老竹又生出青宁虫；青宁虫生出程（一种赤虫），程生出马，马生出人（此句有待细究），而人又返归造化之初的浑沌中。万物都产生于自然的造化，又全都回返自然的造化。（“久竹生青宁，青宁生程，程生马，马生人，人又反入于机”一句，翻译上多有争论，个人以为抛却翻译，可以理解为：老竹生出了青宁虫，青宁虫使得程存货，程使马得以生长，马使人生存，而最终人又归于虚无。恰好与生物链所符合，微生物处出发滋养了生命，最终生命又归于微生物的养分。以此恰好印证文章的无生无死）', NULL, '', 'indent', 1524911846, '5ae3de617f6fd300384491a3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637412, '庄子 · 外篇 · 达生', NULL, 2, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E5%A4%96%E7%AF%87%C2%B7%E8%BE%BE%E7%94%9F/10191886', '', '达生之情者，不务生之所无以为；达命之情者，不务知之所无奈何。养形必先之以物，物有余而形不养者有之矣；有生必先无离形，形不离而生亡者有之矣。生之来不能却，其去不能止。悲夫！世之人以为养形足以存生；而养形果不足以存生，则世奚足为哉！虽不足为而不可不为者，其为不免矣。
夫欲免为形者，莫如弃世。弃世则无累，无累则正平，正平则与彼更生，更生则几矣。事奚足弃则生奚足遗？弃世则形不劳，遗生则精不亏。夫形全精复，与天为一。天地者，万物之父母也，合则成体，散则成始。形精不亏，是谓能移；精而又精，反以相天。
子列子问关尹曰：“至人潜行不窒，蹈火不热，行乎万物之上而不栗。请问何以至于此？”
关尹曰：“是纯气之守也，非知巧果敢之列。居，予语女。凡有貌象声色者，皆物也，物与物何以相远？夫奚足以至乎先？是色而已。则物之造乎不形而止乎无所化，夫得是而穷之者，物焉得而止焉！彼将处乎不淫之度，而藏乎无端之纪，游乎万物之所终始，一其性，养其气，合其德，以通乎物之所造。夫若是者，其天守全，其神无郤，物奚自入焉！
“夫醉者之坠车，虽疾不死。骨节与人同而犯害与人异，其神全也，乘亦不知也，坠亦不知也，死生惊惧不入乎其胸中，是故迕物而不慴。彼得全于酒而犹若是，而况得全于天乎？圣人藏于天，故莫之能伤也。复仇者不折镆干，虽有忮心者不怨飘瓦，是以天下平均。故无攻战之乱，无杀戮之刑者，由此道也。
“不开人之天，而开天之天，开天者德生，开人者贼生。不厌其天，不忽于人，民几乎以其真！”
仲尼适楚，出于林中，见痀偻者承蜩，犹掇之也。
仲尼曰：“子巧乎！有道邪？”曰：“我有道也。五六月累丸二而不坠，则失者锱铢；累三而不坠，则失者十一；累五而不坠，犹掇之也。吾处身也，若厥株拘；吾执臂也，若槁木之枝；虽天地之大，万物之多，而唯蜩翼之知。吾不反不侧，不以万物易蜩之翼，何为而不得！”
孔子顾谓弟子曰：“用志不分，乃凝于神，其痀偻丈人之谓乎！”
颜渊问仲尼曰：“吾尝济乎觞深之渊，津人操舟若神。吾问焉，曰：‘操舟可学邪？’曰：‘可。善游者数能。若乃夫没人，则未尝见舟而便操之也’。吾问焉而不吾告，敢问何谓也？”
仲尼曰：“善游者数能，忘水也。若乃夫没人之未尝见舟而便操之也，彼视渊若陵，视舟之覆犹其车却也。覆却万方陈乎前而不得入其舍，恶往而不暇！以瓦注者巧，以钩注者惮，以黄金注者湣。其巧一也，而有所矜，则重外也。凡外重者内拙。”
田开之见周威公。威公曰：“吾闻祝肾学生，吾子与祝肾游，亦何闻焉？”田开之曰：“开之操拔彗以侍门庭，亦何闻于夫子！”威公曰：“田子无让，寡人愿闻之。”开之曰：“闻之夫子曰：‘善养生者，若牧羊然，视其后者而鞭之。’”威公曰：“何谓也？”
田开之曰：“鲁有单豹者，岩居而水饮，不与民共利，行年七十而犹有婴儿之色；不幸遇饿虎，饿虎杀而食之。有张毅者，高门县薄，无不走也，行年四十而有内热之病以死。豹养其内而虎食其外，毅养其外而病攻其内，此二子者，皆不鞭其后者也。”
仲尼曰：“无入而藏，无出而阳，柴立其中央。三者若得，其名必极。夫畏涂者，十杀一人，则父子兄弟相戒也，必盛卒徒而后敢出焉，不亦知乎！人之所取畏者，袵席之上，饮食之间；而不知为之戒者，过也。”
祝宗人玄端以临牢？，说彘曰：“汝奚恶死？吾将三月豢汝，十曰戒，三日齐，藉白茅，加汝肩尻乎雕俎之上，则汝为之乎？”为彘谋，曰不如食以糠糟而错之牢？之中，自为谋，则苛生有轩冕之尊，死得于腞楯之上，聚偻之中则为之。为彘谋则去之，自为谋则取之，所异彘者何也。
桓公田于泽，管仲御，见鬼焉。公抚管仲之手曰：“仲父何见？”对曰：“臣无所见。”公反，诶诒为病，数日不出。
齐士有皇子告敖者曰：“公则自伤，鬼恶能伤公！夫忿滀之气，散而不反，则为不足；上而不下，则使人善怒；下而不上，则使人善忘；不上不下，中身当心，则为病。”桓公曰：“然则有鬼乎？”曰：“有。沈有履，灶有髻。户内之烦壤，雷霆处之，东北方之下者，倍阿鲑蠪跃之；西北方之下者，则泆阳处之。水有罔象，丘有峷，山有夔（，野有彷徨，泽有委蛇。”公曰：“请问委蛇之状何如？”皇子曰：“委蛇，其大如毂，其长如辕，紫衣而朱冠。其为物也，恶闻雷车之声，则捧其首而立。见之者殆乎霸。”
桓公辴然而笑曰；“此寡人之所见者也。”于是正衣冠与之坐，不终日而不知病之去也。
纪渻子为王养斗鸡。十日而问：“鸡已乎？”曰：“未也，方虚憍而恃气。”十日又问，曰：“未也，犹应向景。”十日又问，曰：“未也，犹疾视而盛气。”十日又问，曰：“几矣。鸡虽有鸣者，已无变矣，望之似木鸡矣，其德全矣，异鸡无敢应者，反走矣。”
孔子观于吕梁，县水三十仞，流沫四十里，鼋鼍鱼鳖之所不能游也。见一丈夫游之，以为有苦而欲死也，使弟子并流而拯之。数百步而出，被发行歌而游于塘下。孔子从而问焉，曰：“吾以子为鬼，察子则人也。请问，‘蹈水有道乎’”曰：“亡，吾无道。吾始乎故，长乎性，成乎命。与齐俱入，与汩偕出，从水之道而不为私焉。此吾所以蹈之也。”孔子曰：“何谓始乎故，长乎性，成乎命？”曰：“吾生於陵而安於陵，故也；长于水而安于水，性也；不知吾所以然而然，命也。”
梓庆削木为鐻，鐻成，见者惊犹鬼神。鲁侯见而问焉，曰：“子何术以为焉？”对曰：“臣工人，何术之有？虽然，有一焉。臣将为鐻，未尝敢以耗气也，必齐以静心。齐三曰，而不敢怀庆赏爵禄；齐五日，不敢怀非誉巧拙；齐七日，辄然忘吾有四枝形体也。当是时也，无公朝，其巧专而外骨消。然后入山林，观天性，形躯至矣，然后成见鐻，然后加手焉；不然则已，则以天合天，器之所以疑神者，其是与！”
东野稷以御见庄公，进退中绳，左右旋中规。庄子以为文弗过也，使之钩百而反。颜阖遇之，入见曰：“稷之马将败。”公密而不应。少焉，果败而反。公曰：“子何以知之？”曰“其马力竭矣，而犹求焉，故曰败。”
工倕旋而盖规矩，指与物化而不以心稽，故其灵台一而不桎。忘足，屦之适也；忘要，带之适也；知忘是非，心之适也；不内变，不外从，事会之适也。始乎适而未尝不适者，忘适之适也。
有孙休者，踵门而诧子扁庆子曰；“休居乡不见谓不修，临难不见谓不勇；然而田原不遇岁，事君不遇世，宾于乡里，逐于州部，则胡罪乎天哉？休恶遇此命也？”
扁子曰：“子独不闻夫至人之自行邪？忘其肝胆，遗其耳目，芒然彷徨乎尘垢之外，逍遥乎无事之业，是谓为而不恃，长而不宰。今汝饰知以惊愚，修身以明污，昭昭乎若揭日月而行也，汝得全而形躯，具而九窍，无中道夭于聋盲跛蹇而比于人数。亦幸矣，又何暇乎天之怨哉！子往矣！”
孙子出，扁子入，坐有间，仰天而叹。弟子问曰：“先生何为叹乎？”扁子曰：“向者休来，吾告之以至人之德，吾恐其惊而遂至于惑也。”弟子曰：“不然。孙子之所言是邪？先王之所言非邪？非固不能惑是。孙子所言非邪？先生所言是邪？彼固惑而来矣，又奚罪焉！”
扁子曰：“不然。昔者有鸟止于鲁郊，鲁君说之，为具太牢以飨之，奏九韶以乐之，鸟乃始忧悲眩视，不敢饮食。此之谓以己养养鸟也。若夫以鸟养养鸟者，宜栖之深林，浮之江湖，食之以委蛇，则平陆而已矣。今休，款启寡闻之民也，吾告以至人之德，譬之若载鼷以车马，乐鴳以钟鼓也。彼又恶能无惊乎哉！”', '“达”指通晓、通达，“生”指生存、生命，“达生”，就是通达生命的意思。怎样才能“达生”呢？篇文明确提出要摒除各种外欲，要心神宁寂事事释然，可知本篇的宗旨在于讨论如何养神。全篇自然分为十三个部分。', '', '通晓生命实情的人，不会去努力追求对于生命没有什么好处的东西；通晓命运实情的人，不会去努力追求命运无可奈何的事情。养育身形必定先得备足各种物品，可是物资充裕有余而身体却不能很好保养的情况是有的；保全生命必定先得使生命不脱离形体，可是形体没有死去而生命却已死亡的情况也是有的。生命的到来不能推却，生命的离去不能留止。可悲啊！世俗的人认为养育身形便足以保存生命；然而养育身形果真不足以保存生命，那么，世间还有什么事情值得去做呢！虽然不值得去做却不得不去做，内中的操劳或勤苦也就不可避免。
想要免除操劳形体的情况，不如忘却世事。忘却世事就没有劳苦和拘累，没有劳苦和拘累就算走上了正确的道路，走上了正确的道路就能跟随自然一道生存与变化，跟自然一道生存与变化也就接近于大道了。世俗之事为什么须得舍弃而生命途中的痕迹为什么须得遗忘？舍弃了世俗之事身形就不会劳累，遗忘了生命的涯际精神就不会亏损。身形得以保全而精神得以复本还原，就跟自然融合为一体。天和地，乃是万物（生长、繁育）的父体和母体，（阴阳二气）一旦结合便形成物体，物体一旦离散又成为新的物体产生的开始。形体保全精神不亏损，这就叫做能够随自然的变化而变化；精神汇集达到高度凝聚的程度，返回过来又将跟自然相辅相成。
列子问关尹说：“道德修养臻于完善的至人潜行水中却不会感到阻塞，跳入火中却不会感到灼热，行走于万物之上也不会感到恐惧。请问为什么会达到这样的境界？”
关尹回答说：“这是因为持守住纯和之气，并不是智巧、果敢所能做到的。坐下，我告诉给你。大凡具有面貌、形象、声音、颜色的东西，都是物体，那么物与物之间又为什么差异很大，区别甚多？又是什么东西最有能耐足以居于他物之先的地位？这都只不过是有形状和颜色罢了。大凡一个有形之物却不显露形色而留足于无所变化之中，懂得这个道理而且深明内中的奥秘，他物又怎么能控制或阻遏住他呢！那样的人处在本能所为的限度内，藏身于无端无绪的混沌中，游乐于万物或灭或生的变化环境里，本性专一不二，元气保全涵养，德行相融相合，从而使自身与自然相通。像这样，他的禀性持守保全，他的精神没有亏损，外物又从什么地方能够侵入呢！
“醉酒的人坠落车下，虽然满身是伤却没有死去。骨骼关节跟旁人一样而受到的伤害却跟别人不同，因为他的神思高度集中，乘坐在车子上也没有感觉，即使坠落地上也不知道，死、生、惊、惧全都不能进入到他的思想中，所以遭遇外物的伤害却全没有惧怕之感。那个人从醉酒中获得保全完整的心态尚且能够如此忘却外物，何况从自然之道中忘却外物而保全完整的心态呢？圣人藏身于自然，所以没有什么能够伤害他。复仇的人并不会去折断曾经伤害过他的宝剑，即使常存忌恨之心的人也不会怨恨那偶然飘来、无心地伤害到他的瓦片，这样一来天下也就太平安宁。没有攻城野战的祸乱，没有残杀戮割的刑罚，全因为遵循了这个道理。
“不要开启人为的思想与智巧，而要开发自然的真性。开发了自然的真性则随遇而安，获得生存；开启人为的思想与智巧，就会处处使生命受到残害。不要厌恶自然的禀赋，也不忽视人为的才智，人们也就几近纯真无伪了！”
孔子到楚国去，走出树林，看见一个驼背老人正用竿子粘蝉，就好像在地上拾取一样。
孔子说：“先生真是巧啊！有门道吗？”驼背老人说：“我有我的办法。经过五、六个月的练习，在竿头累迭起两个丸子而不会坠落，那么失手的情况已经很少了；迭起三个丸子而不坠落，那么失手的情况十次不会超过一次了；迭起五个丸子而不坠落，也就会像在地面上拾取一样容易。我立定身子，犹如临近地面的断木，我举竿的手臂，就像枯木的树枝；虽然天地很大，万物品类很多，我一心只注意蝉的翅膀，从不思前想后左顾右盼，绝不因纷繁的万物而改变对蝉翼的注意，为什么不能成功呢！”
孔子转身对弟子们说：“运用心志不分散，就是高度凝聚精神，恐怕说的就是这位驼背的老人吧！”
颜渊问孔子说：“我曾经在觞深过渡，摆渡人驾船的技巧实在神妙。我问他：‘驾船可以学习吗？’摆渡人说：‘可以的。善于游泳的人很快就能驾船。假如是善于潜水的人，那他不曾见到船也会熟练地驾驶船。’我进而问他怎样学习驾船而他却不再回答我。请问他的话说的是什么意思呢？”
孔子回答说：“善于游泳的人很快就能学会驾船，这是因为他们习以成性适应于水而处之自然。至于那善于潜水的人不曾见到过船就能熟练地驾驶船，是因为他们眼里的深渊就像是陆地上的小丘，看待船翻犹如车子倒退一样。船的覆没和车的倒退以及各种景象展现在他们眼前却都不能扰乱他们的内心，他们到哪里不从容自得！用瓦器作为赌注的人心地坦然而格外技高，用金属带钩作为赌注的人而心存疑惧，用黄金作为赌注的人则头脑发昏内心迷乱。各种赌注的赌博技巧本是一样的，而有所顾惜，那就是以身外之物为重了。大凡对外物看得过重的人其内心世界一定笨拙。”
田开之拜见周威公。周威公说：“我听说祝肾在学习养生，你跟祝肾交游，从他那儿听到过什么呢？”田开之说：“我只不过拿起扫帚来打扫门庭，又能从先生那里听到什么！”周威公说：“先生不必谦虚，我希望能听到这方面的道理。”田开之说：“听先生说：‘善于养生的人，就像是牧放羊群似的，瞅到落后的便用鞭子赶一赶。’”周威公问：这话说的是什么意思呢？”
田开之说：“鲁国有个叫单豹的，在岩穴里居住在山泉边饮水，不跟任何人争利，活了七十岁还有婴儿一样的面容；不幸遇上了饿虎，饿虎扑杀并吃掉了他。另有一个叫张毅的，高门甲第、朱户垂帘的富贵人家，无不趋走参谒，活到四十岁便患内热病而死去。单豹注重内心世界的修养可是老虎却吞食了他的身体，张毅注重身体的调养可是疾病侵扰了他的内心世界，这两个人，都不是能够鞭策落后而取其适宜的人。”
孔子说：“不要进入荒山野岭把自己深藏起来，也不要投进世俗而使自己处处显露，要像槁木一样站立在两者中间。倘若以上三种情况都能具备，他的名声必定最高。使人可畏的道路，十个行人有一个人被杀害，于是父子兄弟相互提醒和戒备，必定要使随行的徒众多起来方才敢于外出，这不是很聪明吗！人所最可怕的，还是枕席上的姿意，还有在饮食间的失度；却不知道为此提醒和戒备，这实在是过错。”
主持宗庙祭祀的官吏穿好礼服戴上礼帽来到猪圈边，对着栅栏里的猪说：“你为什么要讨厌死呢？我将喂养你三个月，用十天为你上戒，用三天为你作斋，铺垫上白茅，然后把你的肩胛和臀部放在雕有花纹的祭器上，你愿意这样吗？”为猪打算，说是仍不如吃糠咽糟而关在猪圈里，为自己打算，就希望活在世上有高贵荣华的地位，死后则能盛装在绘有文采的柩车上和棺椁中。为猪打算就会舍弃白茅、雕俎之类的东西，为自己打算却想求取这些东西，所不同于猪的原因究竟是什么呢？”
齐桓公在草泽中打猎，管仲替他驾车，突然桓公见到了鬼。桓公拉住管仲的手说：“仲父，你见到了什么？”管仲回答：“我没有见到什么。”桓公打猎回来，疲惫困怠而生了病，好几天不出门。
齐国有个士人叫皇子告敖的对齐桓公说：“你是自己伤害了自己，鬼怎么能伤害你呢？身体内部郁结着气，精魂就会离散而不返归于身，对于来自外界的骚扰也就缺乏足够的精神力量。郁结着的气上通而不能下达，就会使人易怒；下达而不能上通，就会使人健忘；不上通又不下达，郁结内心而不离散，那就会生病。”桓公说：“这样，那么还有鬼吗？”告敖回答：“有。水中污泥里有叫履的鬼，灶里有叫髻的鬼。门户内的各种烦攘，名叫雷霆的鬼在处置；东北的墙下，名叫倍阿鲑蠪的鬼在跳跃；西北方的墙下，名叫攻入阳的鬼住在那里。水里有水鬼罔象，丘陵里有山鬼峷，大山里有山鬼夔，郊野里有野鬼彷徨，草泽里还有一种名叫委蛇的鬼。”桓公接着问：“请问，委蛇的形状怎么样？”告敖回答：“委蛇，身躯大如车轮，长如车辕，穿着紫衣戴着红帽。他作为鬼神，最讨厌听到雷车的声音，一听见就两手捧着头站着。见到了他的人恐怕也就成了霸主了。”
桓公听了后开怀大笑，说：“这就是我所见到的鬼。”于是整理好衣帽跟皇子告敖坐着谈话，不到一天时间病也就不知不觉地消失了。
纪渻子为周宣王驯养斗鸡。过了十天周宣王问：“鸡驯好了吗？”纪渻子回答说：“不行，正虚浮骄矜自恃意气哩。”十天后周宣王又问，回答说：“不行，还是听见响声就叫，看见影子就跳。”十天后周宣王又问，回答说：“还是那么顾看迅疾，意气强盛。”又过了十天周宣王问，回答说：“差不多了。别的鸡即使打鸣，它已不会有什么变化，看上去像木鸡一样，它的德行真可说是完备了，别的鸡没有敢于应战的，掉头就逃跑了。”
孔子在吕梁观赏，瀑布高悬二三十丈，冲刷而起的激流和水花远达四十里，鼋、鼍、鱼、鳖都不敢在这一带游水。只见一个壮年男子游在水中，还以为是有痛苦而想寻死的，派弟子顺着水流去拯救他。忽见那壮年男子游出数百步远而后露出水面，还披着头发边唱边游在堤岸下。孔子紧跟在他身后而问他，说：“我还以为你是鬼，仔细观察你却是个人。请问，游水也有什么特别的门道吗？”那人回答：“没有，我并没有什么特别的方法。我起初是故常，长大是习性，有所成就在于自然。我跟水里的漩涡一块儿下到水底，又跟向上的涌流一道游出水面，顺着水势而不作任何违拗。这就是我游水的方法。”孔子说：“什么叫做‘起初是故常，长大是习性，有所成就在于自然’呢？”那人又回答：“我出生于山地就安于山地的生活，这就叫做故常；长大了又生活在水边就安于水边的生活，这就叫做习性；不知道为什么会这样而这样生活着，这就叫做自然。”
梓庆能削刻木头做鐻，鐻做成以后，看见的人无不惊叹好像是鬼神的工夫。鲁侯见到便问他，说：“你用什么办法做成的呢？”梓庆回答道：“我是个做工的人，会有什么特别高明的技术！虽说如此，我还是有一种本事。我准备做鐻时，从不敢随便耗费精神，必定斋戒来静养心思。斋戒三天，不再怀有庆贺、赏赐、获取爵位和俸禄的思想；斋戒五天，不再心存非议、夸誉、技巧或笨拙的杂念；斋戒七天，已不为外物所动仿佛忘掉了自己的四肢和形体。正当这个时候，我的眼里已不存在公室和朝廷，智巧专一而外界的扰乱全都消失。然后我便进入山林，观察各种木料的质地；选择好外形与体态最与鐻相合的，这时业已形成的鐻的形象便呈现于我的眼前，然后动手加工制作；不是这样我就停止不做。这就是用我木工的纯真本性融合木料的自然天性，制成的器物疑为神鬼工夫的原因，恐怕也就出于这一点吧！”
东野稷因为善于驾车而得见鲁庄公，他驾车时进退能够在一条直线上，左右转弯形成规整的弧形。庄公认为就是编织花纹图案也未必赶得上，于是要他转上一百圈后再回来。颜阖遇上了这件事，入内会见庄公，说：“东野稷的马一定会失败的。”庄公默不作声。不多久，东野稷果然失败而回。庄公问：“你为什么事先就知道定会失败呢？”颜阖回答说：“东野稷的马力气已经用尽，可是还要它转圈奔走，所以说必定会失败的。”
工倕随手画来就胜过用圆规与矩尺画出的，手指跟随事物一道变化而不须用心留意，所以他心灵深处专一凝聚而不曾受过拘束。忘掉了脚，便是鞋子的舒适；忘掉了腰，便是带子的舒适；知道忘掉是非，便是内心的安适；不改变内心的持守，不顺从外物的影响，便是遇事的安适。本性常适而从未有过不适，也就是忘掉了安适的安适。
有个名叫孙休的人，走到门前就惊叹不已地询问他的老师扁庆子，说：“我安居乡里不曾受人说过道德修养差，面临危难也没有人说过不勇敢；然而我的田地里却从未遇上过好年成，为国家出力也未遇上圣明的国君，被乡里所摈弃，受地方官放逐，而我对于上天有什么罪过呢？我怎么会遇上如此的命运？”
扁子说：“你不曾听说过那道德修养极高的人的身体力行吗？忘却自己的肝胆，也遗弃了自己的耳目，无心地纵放于世俗尘垢之外，自由自在地生活在不求建树的环境中，这就叫做有所作为而不自恃，有所建树而不自得。如今你把自己打扮得很有才干用以惊吓众人，用修养自己的办法来突出他人的污秽，毫不掩饰地炫耀自己就像在举着太阳和月亮走路。你得以保全形体和身躯，具备了九窍，没有中道上夭折于聋、瞎、跛、瘸而处于寻常人的行列，也真是万幸了，又有什么闲暇抱怨上天呢！你还是走吧！”
孙休走出屋子，扁子回到房里。不多一会儿，扁子仰天长叹，弟子问道：“先生为什么长叹呢？”扁子说：“刚才孙休进来，我把道德修养极高的人的德行告诉给他，我真担心他会吃惊以至迷惑更深。”弟子说：“不对哩。孙休所说的话是正确的吗？先生所说的话是错误的吗？错误的本来就不可能迷惑正确的。孙休所说的话是不对的吗？先生所说的话是正确的吗？他本来就因迷惑而来请教，又有什么过错呀！”
扁子说：“不是这样的。从前有只海鸟飞到鲁国都城郊外，鲁国国君很喜欢它，用‘太牢’来宴请它，奏‘九韶’乐来让它快乐，海鸟竟忧愁悲伤，眼花缭乱，不敢吃喝。这叫做按自己的生活习性来养鸟。假若是按鸟的习性来养鸟，就应当让它栖息于幽深的树林，浮游于大江大湖，让它吃泥鳅和小鱼，这本是极为普通的道理而已。如今的孙休，乃是管窥之见、孤陋寡闻的人，我告诉给他道德修养极高的人的德行，就好像用马车来托载小老鼠，用钟鼓的乐声来取悦小鴳雀一样。他又怎么会不感到吃惊啊！”', NULL, '', 'indent', 1524911910, '5ae3dea29f5454004006a9f2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637413, '庄子 · 外篇 · 山木', NULL, 5, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E5%B1%B1%E6%9C%A8/6644585', '', '庄子行于山
庄子行于山中，见大木枝叶盛茂，伐木者止其旁而不取也。问其故，曰：“无所可用。”
庄子曰：“此木以不材得终其天年。”夫子出于山，舍于故人之家。故人喜，命竖子杀雁而烹之。
竖子请曰：“其一能鸣，其一不能鸣，请奚杀？”
主人曰：“杀不能鸣者。”
明日，弟子问于庄子曰：“昨日山中之木，以不材得终其天年，今主人之雁，以不材死；先生将何处？”
庄子笑曰：“周将处乎材与不材之间。材与不材之间，似之而非也，故未免乎累。若夫乘道德而浮游则不然，无誉无訾，一龙一蛇，与时俱化，而无肯专为；一上一下，以和为量，浮游乎万物之祖，物物而不物于物，则胡可得而累邪！此神农、黄帝之法则也。若夫万物之情，人伦之传，则不然。合则离，成则毁；廉则挫，尊则议，有为则亏，贤则谋，不肖则欺，胡可得而必乎哉！悲夫！弟子志之，其唯道德之乡乎！”
市南宜僚见鲁侯
市南宜僚见鲁侯，鲁侯有忧色。市南子曰：“君有忧色，何也？”
鲁侯曰：“吾学先王之道，修先君之业；吾敬鬼尊贤，亲而行之，无须臾离居；然不免于患，吾是以忧。”
市南子曰：“君之除患之术浅矣！夫丰狐文豹，栖于山林，伏于岩穴，静也；夜行昼居，戒也；虽饥渴隐约，犹旦胥疏于江湖之上而求食焉，定也；然且不免于罔罗机辟之患。是何罪之有哉？其皮为之灾也。今鲁国独非君之皮邪？吾愿君刳形去皮，洒心去欲，而游于无人之野。南越有邑焉，名为建德之国。其民愚而朴，少私而寡欲；知作而不知藏，与而不求其报；不知义之所适，不知礼之所将；猖狂妄行，乃蹈乎大方；其生可乐，其死可葬。吾愿君去国捐俗，与道相辅而行。”
君曰：“彼其道远而险，又有江山，我无舟车，奈何？”市南子曰：“君无形倨，无留居，以为君车。”君曰：“彼其道幽远而无人，吾谁与为邻？吾无粮，我无食，安得而至焉？”
市南子曰：“少君之费，寡君之欲，虽无粮而乃足。君其涉于江而浮于海，望之而不见其崖，愈往而不知其所穷。送君者皆自崖而反，君自此远矣！故有人者累，见有于人者忧。故尧非有人，非见有于人也。吾愿去君之累，除君之忧，而独与道游于大莫之国。方舟而济于河，有虚船来触舟，虽有惼心之人不怒，有一人在其上，则呼张歙之，一呼而不闻，再呼而不闻，于是三呼邪，则必以恶声随之。向也不怒而今也怒，向也虚而今也实。人能虚己以游世，其孰能害之！”
北宫奢
北宫奢为卫灵公赋敛以为钟，为坛乎郭门之外，三月而成上下之县。
王子庆忌见而问焉，曰：“子何术之设？”
奢曰：“一之间，无敢设也。奢闻之，‘既雕既琢，复归于朴’，侗乎其无识，傥乎其怠疑；萃乎芒乎，其送往而迎来；来者勿禁，往者勿止；从其强梁。随其曲傅，因其自穷，故朝夕赋敛而毫毛不挫，而况有大涂者乎！
孔子围于陈蔡之间
孔子围于陈蔡之间，七日不火食。
大公任往吊之曰：“子几死乎？”
曰：“然”。“子恶死乎？”曰：“然。”
任曰：“子尝言不死之道。东海有鸟焉，其名曰意怠。其为鸟也，翂翂翐翐，而似无能；引援而飞，迫胁而栖，进不敢为前，退不敢为后；食不敢先尝，必取其绪。是故其行列不斥，而外人卒不得害，是以免于患。直木先伐，甘井先竭。子其意者饰知以惊愚，修身以明污，昭昭乎若揭日月而行，故不免也。昔吾闻之大成之人曰：‘自伐者无功；功成者堕，名成者亏。’孰能去功与名而还与众人！道流而不明居，得行而不名处；纯纯常常，乃比于狂；削迹捐势，不为功名。是故无责于人，人亦无责焉。至人不闻，子何喜哉？”
孔子曰：“善哉！”辞其交游，去其弟子，逃于大泽；衣裘褐，食杼栗；入兽不乱群，入鸟不乱行。鸟兽不恶，而况人乎！
孔子问子桑雽
孔子问子桑雽曰：“吾再逐于鲁，伐树于宋，削迹于卫，穷于商周，围于陈蔡之间。吾犯此数患，亲交益疏，徒友益散，何与？”
子桑雽曰：“子独不闻假人之亡与？林回弃千金之璧，负赤子而趋。或曰：‘为其布与？赤子之布寡矣；为其累与？赤子之累多矣。弃千金之璧，负赤子而趋，何也？’林回曰：‘彼以利合，此以天属也。’夫以利合者，迫穷祸患害相弃也。以天属者，迫穷祸患害相收也。夫相收之与相弃亦远矣。且君子之交淡若水，小人之交甘若醴；君子淡以亲，小人甘以绝。彼无故以合者，则无故以离。”
孔子曰：“敬闻命矣！”
徐行翔佯而归，绝学捐书，弟子无挹于前，其爱益加进。
异日，桑雽又曰：“舜之将死，真泠禹曰：‘汝戒之哉！形莫若缘，情莫若率。缘则不离，率则不劳；不离不劳，则不求文以待形，不求文以待形，固不待物。’”
庄子衣大布而补之
庄子衣大布而补之，正緳系履而过魏王。
魏王曰：“何先生之惫邪？”
庄子曰：“贫也，非惫也。士有道德不能行，惫也；衣弊履穿，贫也，非惫也；此所谓非遭时也。王独不见夫腾猿乎？其得枏梓豫章也，揽蔓其枝而王长其间，虽羿、蓬蒙不能眄睨也。及其得柘棘枳枸之间也，危行侧视，振动悼栗；此筋骨非有加急而不柔也，处势不便，未足以逞其能也。今处昏上乱相之间，而欲无惫，奚可得邪？此比干之见剖心征也夫！”
孔子穷于陈蔡之间
孔子穷于陈蔡之间，七日不火食，左据槁木，右击槁枝，而歌猋氏之风，有其具而无其数，有其声而无宫角，木声与人声，犁然有当于人之心。
颜回端拱还目而窥之。
仲尼恐其广己而造大也，爱己而造哀也，曰：“回，无受天损易，无受人益难。无始而非卒也，人与天一也。夫今之歌者其谁乎？”
回曰：“敢问无受天损易。”
仲尼曰：“饥渴寒暑，穷桎不行，天地之行也，运物之泄也，言与之偕逝之谓也。为人臣者，不敢去之。执臣之道犹若是，而况乎所以待天乎！”
“何谓无受人益难？”
仲尼曰：“始用四达，爵禄并至而不穷，物之所利，乃非己也，吾命其在外者也。君子不为盗，贤人不为窃。吾若取之，何哉！故曰，鸟莫知于鷾鸸，目之所不宜处，不给视，虽落其实，弃之而走。其畏人也，而袭诸人间，社稷存焉尔。”
“何谓无始而非卒？”
仲尼曰：“化其万物而不知其禅之者，焉知其所终？焉知其所始？正而待之而已耳。”
“何谓人与天一邪？”
仲尼曰：“有人，天也；有天，亦天也。人之不能有天，性也，圣人晏然体逝而终矣！”
庄周游于雕陵之樊
庄周游于雕陵之樊，一异鹊自南方来者，翼广七尺，目大运寸，感周之颡而集于栗林。
庄周曰：“此何鸟哉，翼殷不逝，目大不？”
蹇裳躩步，执弹而留之。
一蝉，方得美荫而忘其身，螳蜋执翳而搏之，见得而忘其形；异鹊从而利之，见利而忘其真。
庄周怵然曰：“噫！物固相累，二类相召也！”捐弹而反走，虞人逐而谇之。
庄周反入，三月不庭，蔺且从而问之：“夫子何为顷间甚不庭乎？”
庄周曰：“吾守形而忘身，观于浊水而迷于清渊。且吾闻诸夫子曰：‘入其俗，从其令’。今吾游于雕陵而忘吾身，异鹊感吾颡，游于栗林而忘真，栗林虞人以吾为戮，吾所以不庭也。”
阳子之宋
阳子之宋，宿于逆旅。逆旅人有妾二人，其一人美，其一人恶，恶者贵而美者贱。
阳子问其故，逆旅小子对曰：“其美者自美，吾不知其美也；其恶者自恶，吾不知其恶也。”
阳子曰：“弟子记之！行贤而去自贤之行，安往而不爱哉！”', '庄子·山木由各自独立的九则寓言故事组成，每则寓言故事的主旨不尽相同，但大体上反映了社会生活中的种种体验和感悟，不乏深邃的人生哲理和对社会问题的深刻认识。', '', '庄子行走于山中，看见一棵大树枝叶十分茂盛，伐木的人停留在树旁却不去动手砍伐。问他们是什么原因，说：“没有什么用处。”
庄子说：“这棵树就是因为不成材而能够终享天年啊！”
庄子走出山来，留宿在朋友家中。朋友高兴，叫童仆杀鹅款待他。
童仆问主人：“一只能叫，一只不能叫，请问杀哪一只呢？”
主人说：“杀那只不能叫的。”
第二天，弟子问庄子：“昨日遇见山中的大树，因为不成材而能终享天年，如今主人的鹅，因为不成材而被杀掉；先生你将怎样对待呢？”
庄子笑道：“我将处于成材与不成材之间。处于成材与不成材之间，庄子行于山
好像合于大道却并非真正与大道相合，所以这样不能免于拘束与劳累。假如能顺应自然而自由自在地游乐也就不是这样。没有赞誉没有诋毁，时而像龙一样腾飞时而像蛇一样蛰伏，跟随时间的推移而变化，而不愿偏滞于某一方面；时而进取时而退缩，一切以顺和作为度量，优游自得地生活在万物的初始状态，役使外物，却不被外物所役使，那么，怎么会受到外物的拘束和劳累呢？这就是神农、黄帝的处世原则。至于说到万物的真情，人类的传习，就不是这样的。有聚合也就有离析，有成功也就有毁败；棱角锐利就会受到挫折，尊显就会受到倾覆，有为就会受到亏损，贤能就会受到谋算，而无能也会受到欺侮，怎么可以一定要偏滞于某一方面呢！可悲啊！弟子们记住了，恐怕还只有归向于自然吧！”
市南宜僚见鲁侯
市南宜僚拜见鲁侯，鲁诸正面带忧色。市南宜僚说：“国君面呈忧色，为什么呢？”鲁侯说：“我学习先王治国的办法，承继先君的事业；我敬仰鬼神尊重贤能，身体力行，没有短暂的止息，可是仍不能免除祸患，我因为这个缘故而忧虑。”
市南宜僚说：“你消除忧患的办法太浅薄了！皮毛丰厚的大狐和斑斑花纹的豹子，栖息于深山老林，潜伏于岩穴山洞，这是静心；夜里行动，白天居息，这是警惕；即使饥渴也隐形潜踪，还要远离各种足迹到江湖上觅求食物，这又是稳定；然而还是不能免于罗网和机关的灾祸。这两种动物有什么罪过呢？是它们自身的皮毛给它们带来灾祸。如今的鲁国不就是为你鲁君带来灾祸的皮毛吗？我希望你能剖空身形舍弃皮毛，荡涤心智摈除欲念，进而逍遥于没有人迹的原野。遥远的南方有个城邑，名字叫做建德之国。那里的人民纯厚而又质朴，很少有私欲；知道耕作而不知道储备，给与别人什么从不希图酬报；不明白义的归宿，不懂得礼的去向；随心所欲任意而为，竟能各自行于大道；他们生时自得而乐，他们死时安然而葬。我希望国君你也能舍去国政捐弃世俗，从而跟大道相辅而行。”
鲁侯说：“那里道路遥远而又艰险，又有江河山岭阻隔，我没有可用的船和车，怎么办呢？”
市南宜僚说：“国君不要容颜高傲，不要墨守滞留，便可以此作为你的车子。”
鲁侯说：“那里道路幽暗遥远而又无人居住，我跟谁是邻居？我没有粮，我没有食物，怎么能够到达那里呢？”
市南宜僚说：“减少你的耗费，节制你的欲念，虽然没有粮食也是充足的。你渡过江河浮游大海，一眼望去看不到涯岸，越向前行便越发不知道它的穷尽。送行的人都从河岸边回去，你也就从此离得越来越远了！所以说统治他人的人必定受劳累，受制于别人的人必定会忧心。而唐尧从不役使他人，也从不受制于人。我希望能减除你的劳累，除去你的忧患，而独自跟大道一块儿遨游于太虚的王国。并合两条船来渡河，突然有条空船碰撞过来，即使心地最偏狭、性子最火急的人也不会发怒；倘若有一个人在那条船上，那就会人人大声呼喊喝斥来船后退；呼喊一次没有回应，呼喊第二次也没有回应，于是喊第三次，那就必定会骂声不绝。刚才不发脾气而现在发起怒来，那是因为刚才船是空的而今却有人在船上。一个人倘能听任外物、处世无心而自由自在地遨游于世，谁能够伤害他！”
北宫奢
北宫奢替卫灵公征集捐款铸造钟器，在外城门设下祭坛，三个月就造好了钟并编组在上下两层钟架上。王子庆忌见到这种情况便向他问道：“你用的是什么样的办法呀？”北宫奢说：“精诚专一而又顺其自然，不敢假设有其他什么好办法。我曾听说，‘既然已细细雕刻细细琢磨，而又要返归事物的本真。’纯朴无心是那样无知无识，忘却心智是那样从容不疑；财物汇聚而自己却茫然无知，或者分发而去或者收聚而来；送来的不去禁绝，分发的不去阻留；强横不讲理的就从其自便，隐委顺和的加以随应，依照各自的情况而竭尽力量，所以早晚征集捐款而丝毫不损伤他人，何况是遵循大道的人呢！”
孔子围于陈蔡之间
孔子被围困在陈国、蔡国之间，七天七夜不能生火煮饭。太公任前去看望他，说：“你快要饿死了吧？”孔子说：“是的。”太公任又问：“你讨厌死吗？”孔子回答：“是的。”
太公任说：“我来谈谈不死的方法。东海里生活着一种鸟，它的名字叫意怠。意怠作为一种鸟啊，飞得很慢，好像不能飞行似的；它们总是要有其他鸟引领而飞，栖息时又都跟别的鸟挤在一起；前进时不敢飞在最前面，后退时不敢落在最后面；吃食时不敢先动嘴，总是吃别的鸟所剩下的，所以它们在鸟群中从不受排斥，人们也终究不会去伤害它，因此能够免除祸患。长得很直的树木总是先被砍伐，甘甜的井水总是先遭枯竭。你的用心是装扮得很有才干以便惊吓普通的人，注重修养以便彰明别人的浊秽，毫不掩饰地炫耀自己就像是举着太
阳和月亮走路，所以总不能免除灾祸。从前我听圣德宏博的老子说过：‘自吹自擂的人不会成就功业；功业成就了而不知退隐的人必定会毁败，名声彰显而不知韬光隐晦的必定会遭到损伤。’谁能够摈弃功名而还原跟普通人一样！大道广为流传而个人则韬光隐居，道德盛行于世而个人则藏誉匿耀不处其名；纯朴而又平常，竟跟愚狂的人一样；削除形迹捐弃权势，不求取功名。因此不会去谴责他人，别人也不会责备自己。道德修养极高的人不求闻名于世，你为什么偏偏喜好名声呢？”
孔子说：“说得实在好啊！”于是辞别朋友故交，离开众多弟子，逃到山泽旷野；穿兽皮麻布做成的衣服，吃柞树和栗树的果实；进入兽群兽不乱群，进入鸟群鸟不乱行。鸟兽都不讨厌他，何况是人呢！
孔子问子桑雽
孔子问桑雽道：“我两次在鲁国被驱逐，在宋国受到伐树的惊辱，在卫国被人铲除足迹，在商、周之地穷愁潦倒，在陈国和蔡国间受到围困。我遭逢这么多的灾祸，亲朋故交越发疏远了，弟子友人更加离散了，这是为什么呢？”
桑雽回答说：“你没有听说过那假国人的逃亡吗？林回舍弃了价值千金的璧玉，背着婴儿就跑。有人议论：‘他是为了钱财吗？初生婴儿的价值太少太少了；他是为了怕拖累吗？初生婴儿的拖累太多太多了。舍弃价值千金的璧玉，背着婴儿就跑，为了什么呢？’林回说：‘价值千金的璧玉跟我是以利益相合，这个孩子跟我则是以天性相连。’以利益相合的，遇上困厄、灾祸、忧患与伤害就会相互抛弃；以天性相连的，遇上困厄、灾祸、忧患与伤害就会相互包容。相互收容与相互抛弃差别也就太远了。而且君子的交谊淡得像清水一样，小人的交情甜得像甜酒一样；君子淡泊却心地亲近，小人甘甜却利断义绝。大凡无缘无故而接近相合的，那么也会无缘无故地离散。”
孔子说：“我会由衷地听取你的指教！”于是慢慢地离去，闲放自得地走了回来，终止了学业丢弃了书简，弟子没有一个侍学于前，可是他们对老师的敬爱反而更加深厚了。
有一天，桑雽又说：“舜将死的时候，用真道晓谕夏禹说：‘你要警惕啊！身形不如顺应，情感不如率真。顺应就不会背离，率真就不会劳苦；不背离不劳神，那么也就不需要用纹饰来装扮身形；无须纹饰来矫造身形，当然也就不必有求于外物。’”
庄子衣大布而补之
庄子身穿粗布衣并打上补钉，工整地用麻丝系好鞋子走过魏王身边。
魏王见了说：“先生为什么如此困顿呢？”
庄子说：“是贫穷，不是困顿。士人身怀道德而不能够推行，这是困顿；衣服坏了鞋子破了，这是贫穷，而不是困顿。这种情况就是所谓生不逢时。大王没有看见过那跳跃的猿猴吗？它们生活在楠、梓、豫、章等高大乔木的树林里，抓住藤蔓似的小树枝自由自在地跳跃而称王称霸，即使是神箭手羿和逢蒙也不敢小看它们。等到生活在柘、棘、枳、枸等刺蓬灌木丛中，小心翼翼地行走而且不时地左顾右盼，内心震颤恐惧发抖；这并不是筋骨紧缩有了变化而不再灵活，而是所处的生活环境很不方便，不能充分施展才能。如今处于昏君乱臣的时代，要想不困顿，怎么可能呢？这种情况比干遭剖心刑戮就是最好的证明啊！”
孔子穷于陈蔡之间
孔子受困于陈国、蔡国之间，整整七天不能生火就食，左手靠着枯树，右手敲击枯枝，而且还唱起了神农时代的歌谣，不过敲击的东西并不能合符音乐的节奏，有了敲击的声响却没有符合五音的音阶，敲木声和咏歌声分得清清楚楚，而且恰如其分地表达了唱歌人的心意。
颜回恭敬地在一旁侍立，掉过脸去偷偷地看了看。
孔子真担心他把自己的道德看得过于高远而达到最了不起的境界，爱惜自己因而至于哀伤，便说：“颜回，不受自然的损害容易，不接受他人的利禄则较困难。世上的事没有什么开始不同时又是终了的，人与自然原本也是同一的。至于现在唱歌的人又将是谁呢？”
颜回说：“我冒昧地请教什么叫做不受自然的损害容易。”
孔子说：“饥饿、干渴、严寒、酷暑，穷困的束缚使人事事不能通达，这是天地的运行，万物的变迁，说的是要随着天地、万物一块儿变化流逝。做臣子的，不敢违拗国君的旨意。做臣子的道理尚且如此，何况是用这样的办法来对待自然呢！”
颜回又问：“什么叫做不接收他人的利禄则较困难呢？”
孔子说：“初被任用办什么事都觉得顺利，爵位和俸禄一齐到来没有穷尽，外物带来的好处，本不属于自己，只不过是我的机遇一时存在于外物。君子不会做劫盗，贤人也不会去偷窃。我若要获取外物的利益，为了什么呢？所以说，鸟没有比燕子更聪明的，看见不适宜停歇的地方，绝不投出第二次目光，即使掉落了食物，也舍弃不顾而飞走。燕子很害怕人，却进入到人的生活圈子，不过只是将它们的巢窠暂寄于人的房舍罢了。”
颜回又问：“什么叫做没有什么开始不同时又是终了的？”
孔子说：“变化无穷的万物不可能知道是谁替代了谁而谁又为谁所替代，这怎么能知道它们的终了？又怎么能知道它们的开始？只不过谨守正道随应变化而已。”
颜回又问：“什么叫做人与自然原本也是同一的？”
孔子说：“人类的出现，是由于自然；自然的出现，也是由于自然。人不可能具有自然的本性，也是人固有的天性所决定的，圣人安然体解，随着自然变化而告终！”
庄周游于雕陵之樊
庄子在雕陵栗树林里游玩，看见一只奇异的怪鹊从南方飞来，翅膀宽达七尺，眼睛大若一寸，碰着庄子的额头而停歇在果树林里。
庄子说：“这是什么鸟呀，翅膀大却不能远飞，眼睛大视力却不敏锐？”于是提起衣裳快步上前，拿着弹弓静静地等待着时机。
这时突然看见一只蝉，正在浓密的树荫里美美地休息而忘记了自身的安危；一只螳螂用树叶作隐蔽打算见机扑上去捕捉蝉，螳螂眼看即将得手而忘掉了自己形体的存在；那只怪鹊紧随其后认为那是极好的时机，眼看即将捕到螳螂而又丧失了自身的真性。
庄子惊恐而警惕地说：“啊，世上的物类原本就是这样相互牵累、相互争夺的，两种物类之间也总是以利相召引！”庄子于是扔掉弹弓转身快步而去，看守栗园的人大惑不解地在后面追着责问。
庄子返回家中，整整三天心情很不好。弟子蔺且跟随一旁问道：“先生为什么这几天来一直很不高兴呢？”
庄子说：“我留意外物的形体却忘记了自身的安危，观赏于混浊的流水却迷惑于清澈的水潭。而且我从老聃老师那里听说：‘每到一个地方，就要遵从那里的习惯与禁忌。’如今我来到雕陵栗园便忘却了自身的安危，奇异的怪鹊碰上了我的额头，游玩于果林时又丧失了自身的真性，管园的人不理解我又进而侮辱我，因此我感到很不愉快。”
阳子之宋
阳朱到宋国去，住在旅店里。旅店主人有两个妾，其中一个漂亮，一个丑陋，可是长得丑陋的受到宠爱而长得漂亮的却受到冷淡。
阳朱问这件事的缘故，年青的店主回答：“那个长得漂亮的自以为漂亮，但是我却不觉得她漂亮；那个长得丑陋的自以为丑陋，但是我却不觉得她丑陋。”
阳子转身对弟子说：“弟子们记住！品行贤良但却不自以为具有了贤良的品行，去到哪里不会受到敬重和爱戴啊！”', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3faa2cee9a0c24ee7af2", "shortContent": "在现代写作学中，有一种称之为“倒金字塔式”的新闻写作模式。要旨是在一篇新闻稿的开头，先用概括的语言，将事件的结果告诉读者，称之为“新闻导语”；然后再按事件的顺序，将其发生、发展的过程原原本本地写下来。\n在现代新闻写作教材中赫然载明：这种模式是从国外“引进”的，它的“始作俑者”是洋人（一般认为是美联社记者B．S．奥斯本）。\n然而李庆辰的这篇《火灾》，在写作手法上却完全符合此种“倒金字塔”的写作模式。...", "authors": ["储有明"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42c1c6e67846a9227c65", "shortContent": "本篇选自褚人获的杂俎小说集《坚瓠集》余集卷一。\n这篇作品最大的特点便是悬念的设置，可以说从题目到结局处处充满悬念。先看题目“异侠借银”，悬念由此开始，此篇中的侠客“异”在何处？作为一位侠客，何以要“借银”？随着故事的开始，作者进行了层层悬念的设置。首先，徽商密藏千金于布捆中，忽遇一人附舟，此人既“状貌雄伟”，又能与主人“甚款洽”。直觉告诉读者，这样的人绝非等闲之辈，但他究竟是什么人呢？作者留下了一...", "authors": ["石", "麟"], "pressName": "上海辞书出版社"}]', '', 'indent', 1524912217, '5ae3dfc49f5454005eafb803', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637414, '庄子 · 外篇 · 田子方', NULL, 3, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E5%A4%96%E7%AF%87%C2%B7%E7%94%B0%E5%AD%90%E6%96%B9/10192088?fr=aladdin', '', '田子方侍坐于魏文侯，数称溪工。文侯曰：“溪工，子之师邪？”子方曰：“非也，无择之里人也。称道数当故无择称之。”文侯曰：“然则子无师邪？”子方曰：“有。”曰：“子之师谁邪？”子方曰：“东郭顺子。”文侯曰：“然则夫子何故未尝称之？”子方曰：“其为人也真。人貌而天虚，缘而葆真，清而容物。物无道，正容以悟之，使人之意也消。无择何足以称之！”子方出，文侯傥然，终日不言。召前立臣而语之曰：“远矣，全德之君子！始吾以圣知之言、仁义之行为至矣。吾闻子方之师，吾形解而不欲动，口钳而不欲言。吾所学者，直土埂耳！夫魏真为我累耳！”
温伯雪子适齐，舍于鲁。鲁人有请见之者，温伯雪子曰：“不可。吾闻中国之君子，明乎礼义而陋于知人心。吾不欲见也。”至于齐，反舍于鲁，是人也又请见。温伯雪子曰：“往也蕲见我，今也又蕲见我，是必有以振我也。”出而见客，入而叹。明日见客，又入而叹。其仆曰：“每见之客也，必入而叹，何耶？”曰：“吾固告子矣：中国之民，明乎礼义而陋乎知人心。昔之见我者，进退一成规、一成矩，从容一若龙、一若虎。其谏我也似子，其道我也似父，是以叹也。”仲尼见之而不言。子路曰：“吾子欲见温伯雪子久矣。见之而不言，何邪？”仲尼曰：“若夫人者，目击而道存矣，亦不可以容声矣！”
颜渊问于仲尼曰：“夫子步亦步，夫子趋亦趋，夫子驰亦驰，夫子奔逸绝尘，而回瞠若乎后矣！”夫子曰：“回，何谓邪？”曰：“夫子步亦步也，夫子言亦言也；夫子趋亦趋也，夫子辩亦辩也；夫子驰亦驰也，夫子言道，回亦言道也；及奔逸绝尘而回瞠若乎后者，夫子不言而信，不比而周，无器而民滔乎前，而不知所以然而已矣。”仲尼曰：“恶！可不察与！夫哀莫大于心死，而人死亦次之。日出东方而入于西极，万物莫不比方，有目有趾者，待是而后成功。是出则存，是入则亡。万物亦然，有待也而死，有待也而生。吾一受其成形，而不化以待尽。效物而动，日夜无隙，而不知其所终。薰然其成形，知命不能规乎其前。丘以是日徂。吾终身与汝交一臂而失之，可不哀与？女殆著乎吾所以著也。彼已尽矣，而女求之以为有，是求马于唐肆也。吾服，女也甚忘；女服，吾也甚忘。虽然，女奚患焉！虽忘乎故吾，吾有不忘者存。”
孔子见老聃，老聃新沐，方将被发而干，蛰然似非人。孔子便而待之。少焉见，曰：“丘也眩与？其信然与？向者先生形体掘若槁木，似遗物离人而立于独也。”老聃曰：“吾游心于物之初。”孔子曰：“何谓邪？”曰：“心困焉而不能知，口辟焉而不能言。尝为汝议乎其将：至阴肃肃，至阳赫赫。肃肃出乎天，赫赫发乎地。两者交通成和而物生焉，或为之纪而莫见其形。消息满虚，一晦一明，日改月化，日有所为而莫见其功。生有所乎萌，死有所乎归，始终相反乎无端，而莫知乎其所穷。非是也，且孰为之宗！”孔子曰：“请问游是。”老聃曰：“夫得是至美至乐也。得至美而游乎至乐，谓之至人。”孔子曰：“愿闻其方。”曰：“草食之兽，不疾易薮；水生之虫，不疾易水。行小变而不失其大常也，喜怒哀乐不入于胸次。夫天下也者，万物之所一也。得其所一而同焉，则四支百体将为尘垢，而死生终始将为昼夜，而莫之能滑，而况得丧祸福之所介乎！弃隶者若弃泥涂，知身贵于隶也。贵在于我而不失于变。且万化而未始有极也，夫孰足以患心！已为道者解乎此。”孔子曰：“夫子德配天地，而犹假至言以修心。古之君子，孰能脱焉！”老聃曰：“不然。夫水之于汋也，无为而才自然矣；至人之于德也，不修而物不能离焉。若天之自高，地之自厚，日月之自明，夫何修焉！”孔子出，以告颜回曰：“丘之于道也，其犹醯鸡与！微夫子之发吾覆也，吾不知天地之大全也。”
庄子见鲁哀公，哀公曰：“鲁多儒士，少为先生方者。”庄子曰：“鲁少儒。”哀公曰：“举鲁国而儒服，何谓少乎？”庄子曰：“周闻之：儒者冠圜冠者知天时，履句履者知地形，缓佩玦者事至而断。君子有其道者，未必为其服也；为其服者，未必知其道也。公固以为不然，何不号于国中曰：‘无此道而为此服者，其罪死！’”于是哀公号之五日，而鲁国无敢儒服者。独有一丈夫，儒服而立乎公门。公即召而问以国事，千转万变而不穷。庄子曰：“以鲁国而儒者一人耳，可谓多乎？”
百里奚爵禄不入于心，故饭牛而牛肥，使秦穆公忘其贱，与之政也。有虞氏死生不入于心，故足以动人。
宋元君将画图，众史皆至，受揖而立，舐笔和墨，在外者半。有一史后至者，儃儃然不趋，受揖不立，因之舍。公使人视之，则解衣般礴臝。君曰：“可矣，是真画者也。”
文王观于臧，见一丈夫钓，而其钓莫钓。非持其钓有钓者也，常钓也。文王欲举而授之政，而恐大臣父兄之弗安也；欲终而释之，而不忍百姓之无天也。于是旦而属之大夫曰：“昔者寡人梦见良人，黑色而髯，乘驳马而偏朱蹄，号曰：‘寓而政于臧丈人，庶几乎民有瘳乎！’”诸大夫蹴然曰：“先君王也。”文王曰：“然则卜之。”诸大夫曰：“先君之命，王其无它，又何卜焉。”遂迎臧丈人而授之政。典法无更，偏令无出。三年，文王观于国，则列士坏植散群，长官者不成德，斔斛不敢入于四竟。列士坏植散群，则尚同也；长官者不成德，则同务也，斔斛不敢入于四竟，则诸侯无二心也。文王于是焉以为大师，北面而问曰：“政可以及天下乎？”臧丈人昧然而不应，泛然而辞，朝令而夜循，终身无闻。颜渊问于仲尼曰：“文王其犹未邪？又何以梦为乎？"仲尼曰："默，汝无言！夫文王尽之也，而又何论剌焉！彼直以循斯须也。”
列御寇为伯昏无人射，引之盈贯，措杯水其肘上，发之，适矢复沓，方矢复寓。当是时，犹象人也。伯昏无人曰：“是射之射，非不射之射也。尝与汝登高山，履危石，临百仞之渊，若能射乎？”于是无人遂登高山，履危石，临百仞之渊，背逡巡，足二分垂在外，揖御寇而进之。御寇伏地，汗流至踵。伯昏无人曰：“夫至人者，上窥青天，下潜黄泉，挥斥八极，神气不变。今汝怵然有恂目之志，尔于中也殆矣夫！”
肩吾问于孙叔敖曰：“子三为令尹而不荣华，三去之而无忧色。吾始也疑子，今视子之鼻间栩栩然，子之用心独奈何？”孙叔敖曰：“吾何以过人哉！吾以其来不可却也，其去不可止也。吾以为得失之非我也，而无忧色而已矣。我何以过人哉！且不知其在彼乎？其在我乎？其在彼邪亡乎我，在我邪亡乎彼。方将踌躇，方将四顾，何暇至乎人贵人贱哉！”仲尼闻之曰：“古之真人，知者不得说，美人不得滥，盗人不得劫，伏戏、黄帝不得友。死生亦大矣，而无变乎己，况爵禄乎！若然者，其神经乎大山而无介，入乎渊泉而不濡，处卑细而不惫，充满天地，既以与人己愈有。”
楚王与凡君坐，少焉，楚王左右曰“凡亡”者三。凡君曰：“凡之亡也，不足以丧吾存。夫凡之亡不足以丧吾存，则楚之存不足以存存。由是观之，则凡未始亡而楚未始存也。”', '田子方是篇首的人名。全篇内容比较杂，具有随笔、杂记的特点，不过从一些重要章节看，主要还是表现虚怀无为、随应自然、不受外物束缚的思想。', '', '田子方陪坐在魏文侯旁边，多次称赞溪工这个人。文侯说：“溪工是先生的老师吗？”子方说：“不是，只是我的同乡。讲说大道常常恰当在理，所以我称赞他。”文侯说：“那么先生没有老师吗？”子方说：“有”。又问：“先生的老师是谁呢？”子方说：“是东郭顺子。”文侯说：“可是，先生为什么没有称赞过呢？”子方说：“他为人真诚，具有人的体貌和天一样空虚之心，随顺物性而保持真性，心性高洁又能容人容物。人与事不合正道，他端正己之仪态使自悟其过而改之。我哪里配得上去称赞他呀！”子方出去后，文侯表现出若有所失的神态，整天不言语。召呼立在面前之臣对他说：“太深远玄妙了，真是一位德行完备的君子！起先我认为仁义的行为，圣智的言论是至高无上的。我听到子方讲述其老师的情况，我身体松散不愿动，口象被钳住一样不愿说话，对照我所学的东西，只是没有生命的土偶而已！魏国真成了我的累赘啊！”
温伯雪子往齐国去，途中寄宿于鲁国。鲁国有个人请求见他，温伯雪子说：“不可以。我听说中原的君子，明于礼义而浅于知人心，我不想见他。”到齐国后，返回时又住宿鲁国，那个人又请相见。温伯雪子说：“往日请求见我，今天又请求见我，此人必定有启示于我。”出去见客，回来就慨叹一番，明天又见客，回来又慨叹不已。他的仆人问，“每次见此客人，必定入而慨叹，为何呢？”回答说：“我本来已告诉过你：中原之人明于知礼义而浅于知人心，刚刚见我的这个人，出入进退一一合乎礼仪，动作举止蕴含龙虎般不可抵御之气势。他对我直言规劝象儿子对待父亲般恭顺，他对我指导又象父亲对儿子般严厉，所以我才慨叹。”孔子见到温伯雪子一句话也不说，子路问：“先生想见温伯雪子很久了，见了面却不说话，为何呀？”孔子说：“象这样人，用眼睛一看而知大道存之于身，也不容再用语言了。”
颜渊问孔子说：“先生缓步我也缓步，先生急走我也急走，先生跑我也跑，先生快速奔跑，脚掌好象离开地面一般，而我只能瞪大眼睛在后面看了。”孔子说：“颜回，你说的是什么意思？”颜回说：“先生缓步我也缓步，是说先生怎样讲我也跟着怎样说；先生急走我也急走，是说先生辨析事理我也跟着辨析事理；先生跑我也跑，是说先生讲说大道我也跟着讲说大道；及至先生好象脚掌离开地面般迅跑，而我瞪大眼睛在后面看，是说先生不用言说而为人信服，不私意亲近而周遍亲附，没有官爵利禄而人们聚集于前，却不知为什么要这样做，如此而已。”孔子说：“噢！不可不明察呀！悲哀没大过心死，而身死还在其次。太阳从东方出来而入于西天尽头，万物莫不顺从太阳的方向而动作，凡有眼有脚的，必待日出而后有所作为。日出则操作，日入无事可作则休息。万物亦是这样，待造化之往来而有生有死。我一秉受天赋之形体，就不会转化为他物而等待着穷尽天年。随着外物而运动，日夜不停息，而不知终极之处。和气自动聚合成形体，知命的人也不能测度将来的命运。我只是天天与变化俱往。我终身与你在一起，这极好机会却当面错过而不能使你了解这个道理，可不悲哀吗？你只是着眼于我显著的方面，而那些显著有形迹的东西已经过去了，你还着意追寻以为实有，这就如同在空虚市场上寻求马一样不可能。我之所习，你要把它全部遗忘；你之所习，我也把它全部遗忘。虽然如此，你又何必担忧！虽然忘记了过去的我，我还有永存的不被忘记的东西在。”
孔子去见老聃，老聃刚洗完发，正在披散头发晾干，木然而立不象一个活人。孔子蔽于隐处等待，过一会儿人见，说：“是我眼花呢？还是真的呢？刚才先生身体独立不动象槁木，象遗弃万物离开众人而独立自存的样子。”老聃说：“我在神游物初生之浑沌虚无之境。”孔子说：“这是何意呢？”老聃说：“心困惑于它而不能知，口对它开而不合不能言说。尝试为你议论一下它的大略：地之极致为阴冷之气，天之极致力炎热之气，阴冷之气恨于天，炎热之气本于地。两者相互交通和合而生成万物，谁为这一切的纲纪而又不见它的形体。消亡又生息，盈满又空虚，一暗一明，日日改变，月月转化，每日有所作为而不见其功效。生有所萌发之处，死有所归往之地，始终相反没有边际，而不知其穷尽。没有它，谁来作主宰啊！”孔子说：“请问神游大道之情形。”老聃说：“能得神游于此为至美至乐。能得至美而游于至乐，就叫作至人。”孔子说：“请问达于至美至乐之道。”老聃说：“食草的兽类，不担忧更换沼泽地；水生的虫类，不担忧改换水。实行小的变化而未失去基本的生活条件，喜怒哀乐之情就不会进入心里。至于天下，是万物共同生息之所。得到共同的生息之气而能混同为一，则四肢百体就将成为废物，而死生终始也将如昼夜之更迭，不能混乱，何况得失祸福之所分际啊！遗弃隶属于己之物如同抛弃泥土，这是知晓身贵于隶属之物。知自身之贵又不失与变化俱往。而且千变万化是未曾有终极的，又何必为此心忧！得道之人会理解此理的。？”孔子说：“先生之德与天地匹配，而还借助至道之言以修养心性。古之君子谁又能免于修养呢！”老聃说：“不是这样，水之于澄澈，是无为而才质自然如此的；至人之于德行，不须修养而成，万物不能离开它。就象天自然就高，地自然就厚，日月自然就明亮，何用修养啊！”孔子出来，把这些告诉颜回，说：“我对于道之认识，就如同醋瓮中的飞虫般渺小！没有先生揭开我之蒙蔽，我就不知道天地大全之理啊！”
庄子拜见鲁哀公，哀公说：“鲁国多懦学之上，很少有从事先生之道术的。”庄子说：“鲁国儒学之士很少。”哀公说：“全鲁国的人都穿儒者服装，怎么说少呢？”庄子说：“我听说，儒者中戴圆帽的通晓天时，穿方形鞋子的懂得地理，佩戴五彩丝带穿系玉块的，事至而能决断。君子怀有其道术的，未必穿戴那样的服饰；穿戴那样服饰的，未必真有道术。公一定以为不是这样，何不号令于国中说：“‘不懂此种道术而穿戴此种服饰的，要处以死罪！’”于是哀公发布这样命令，五天以后鲁国没有敢穿儒服的人。唯独有一位男子，身穿儒服立在哀公门外。哀公即刻召见他以国事相问，干转万变发问也不能难住他。庄子说：“以鲁国之大只有一个儒者，可以说多吗？”
百里奚不把官爵奉禄放在心上，所以养牛而牛肥，使秦穆公忘记了他出身低贱，而委之以国事。虞舜不把生死放在心上，所以能感动他人。
宋元君要画画，众位画师都来了，受君命拜揖而立，润笔调墨准备着，门外面还有一大半。有一位后到的画师，舒缓闲适不慌不忙地走着，受命拜揖后也不在那站着，而往馆舍走去。元公派人去看，见他脱掉上衣赤着上身盘腿而坐。元公说：“可以了，这位就是真正画师。”
周文王去臧地巡视，看见一位钓鱼的老者，身在钓鱼，心不在钓鱼上。他并非以持竿钓鱼为事，而是别有所钓，他经常就是这样钓法。文王想举用他，把国事交他治理，又担心大臣和父兄辈族人不肯相安；想最后舍弃此人，又不忍心让百姓们得不到善人的庇荫。于是就在清晨集合他的大夫们说：“昨天夜里我梦见一位好人，面黑两颊长满长须，骑的杂色马有一只蹄子是赤色，命令我说：‘托付你的国事给臧地老者，差不多民就可以解除病痛了！’”诸位大夫惊惧不安他说：“这是先君王季历啊！”文王说：“让我们占卜一下吧。”诸位大夫说：“先君之命令，王无可怀疑，又何必占卜。”于是就迎接臧地老者，授给国事。这个人掌政，以往典章法令没有更改，一篇新政令也未发出。三年之后，文王巡视国内，则见各种文士武士结成的私党都散掉了，官长们也不建立个人功德，标准不一的量器也不敢进入国境之内。文士武士们的私党散掉，则上同于君主；官长不建立个人功德，则能同以国事为务；标准不一的量器不入境，则诸侯们也就没有二心了。文王于是把臧丈人当作者师，北面而立请教说：“这佯的政事可以推行于天下吗？”臧丈人默然不回答，淡漠无心地告辞而去，早晨还接受文王指令，晚上就逃走了，终身没有消息。颜渊问孔子说：“文王还不足以取信于人吗？何必要假托于梦呢？”孔子说：“别作声，你不要说了！文王已经作得很完美了，你又何必议论讥刺呢！他只是在短暂时刻顺应众人罢了。”
列御寇为伯昏无人表演射箭，把弓拉得满满的，放一杯水在左肘上，发射出去，箭射出后又有一只扣在弦上，刚刚射出又一只寄在弦上，连续不停。在那个时候，他就象一个木偶一般纹丝不动。伯昏无人说：“这是有心于射的射法，不是无心之射的射法。尝试和你登上高山，踏着险石，对着百仞深渊，你能射吗？”于是伯昏无人就登上高山，脚踏险石，背对着百仞深渊向后却退，直到脚下有三分之二悬空在石外，在那里揖请列御寇退至相同位置表演射箭。列御寇惊惧得伏在地上，冷汗流到脚跟。伯昏无人说：“作为至人，上可探测青天，下可潜察黄泉，纵放自如于四面八方，而神情没有变化。现在你有惊恐目眩之意，你于精神已经疲困了！”
肩吾问孙叔敖说：“您三次作令尹而不昌盛显达，三次被免职也没有忧愁之色。我开始时对此怀疑，现在见您呼吸轻松欢畅，您的心里是怎样想的呢？”孙叔敖说：“我哪有什么过人之处啊！我认为它既然来了就无法推辞，它去了也无法阻止，我认为官职奉禄之得失非我所有，失去了而无忧愁之色而已。我哪有什么过人之处啊！况巨不知荣华显贵是在于令尹呢，还是在我自身？如果是在于令尹，则于我无涉；如果在我自身，则于令尹无涉。那时我正在驻足沉思，顾及四面八方之事，哪有工夫顾及到个人的富贵和贫贱哪！”孔子听后说：“古时候的真人，智者不能说服他，美色不能使之淫乱，强盗不能强制他，伏牺、黄帝这样的帝王也不能宠络亲近他。死生也算得上大事了，也不能使自己有所改变，何况是官爵奉禄之得失呢！象这样的人，他的精神历经大山而无障碍，入于深渊而不沾湿，处于贫贱而下疲困，充满大地之间，尽数给予别人而自己更富有。”
楚王和凡国之君共坐，过一会儿，楚王左右之臣多次来讲凡国已经灭亡了。凡国之君说：“凡国灭亡，不足以丧失我之存在。而凡国之灭亡既不足以丧失我之存，而楚国之存在也不足以存在为存。由此看来，则凡国未曾灭亡而楚国未曾存在。”', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f7703572034f65b5d4c", "shortContent": "作者笔下的郑交甫是一个柳下惠式的书生，他文质彬彬，受儒家的思想影响很深，不敢也不愿坦白地表露他的爱情。\n但是，爱情是人类的一种本能，要想完完全全包起来，那是不可能的。郑交甫遇到了江妃二女，“见而悦之”，这是他内心的思想活动。\n他控制不住自己，在这种情况之下，他又只得尽可能采取克制的态度，希望这两位美貌的少女能留下她们的玉佩，给他作为纪念。他自己觉得这个动作有些冒昧，就先向身边的奴仆试探一下，征求奴...", "authors": ["蒋星煜"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f825914587d02f66f20", "shortContent": "作为一个漫长历史时期的文学创作现象，志怪小说的情况十分复杂。从内容上来说，有的作品名为志怪，实际上反映了一定的社会生活，表现了作者一定的人生追求；有的作品则纯系志怪，无任何人生内容可言。这类作品，正如作者结集命名所指示的：“志怪”、“述异”、“异记”……其根本特征就在一个“怪”字——离奇古怪，荒诞不经。这篇小说就是这样。一个蝼蛄，竟能幻化成人，懂人间礼节，通人间语言，和真人毫无二致，甚至比一般人还...", "authors": ["孙秀荣"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8903048e64fbda9797", "shortContent": "本篇写商贾女叶氏经十余年苦心奔走，终得报父、夫被害之仇事。唐人小说以妇女为主人公者甚多，或大家闺秀如崔莺莺，或平康妓女如李娃，或风尘女侠如红线，《尼妙寂》主人公则是个商贾女。作品塑造了一个独特的妇女形象，填补了唐小说人物画廊的空白。\n叶氏女具备商贾女的特有气质与性格。开头，即提示了主人公出身于商家的身份，后面的情节也即在此基础上展开。父、夫经商，才发生湖中遇盗事；也只有商贾家出身之叶氏女，才有可能...", "authors": ["侯百朋"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8e7d0ac1145496bc64", "shortContent": "人与妖的搏斗，斗勇，斗智。试看韦自东与二夜叉的一番恶斗，何等惊心动魄！碗口粗的柏树，千斤重的石佛，都被他随手拔起和搬来作为武器。面对夜叉的狂怒、哮吼，他毫无畏惧，而是力举柏树以击其脑，继而又断其首，对其猎获的鹿则烹而食之。为了突出韦自东的勇力，作者用了几层铺垫：一是通过段将军转述樵者之言，渲染夜叉食僧、无人敢窥山寺的恐怖；二是韦自东决心诛灭夜叉，将军认为他虽有勇力而仍不可行，劝止道：“暴虎冯河，死...", "authors": ["赵山林"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8e2cee9a0c24ee7930", "shortContent": "裴铏《传奇》中《孙恪》一篇，与本篇相类，述下第秀才孙恪邂逅一名袁姓女子，貌美富财，孙恪与她结婚，成了巨富。但生下二子后，孙恪对妻子却发生了怀疑，甚至暗下请来了斩妖剑。后来孙恪到长安去干谒权贵，袁氏随行，途中见野猿数十，袁氏便留诗一首，化为老猿跃树而去。所谓“刚被恩情役此心，无端变化几湮沉。不如逐伴归山去，长啸一声烟雾深”。薛渔思《河东记》的《申屠澄》，又与《孙恪》相类，故事中的申屠澄妻在生下一男一...", "authors": ["穆", "俦"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8bdbb8b379ee0aec5f", "shortContent": "本篇写男女婚姻中的一件怪异之事。退职叶县县令卢造之女自幼由父母作主与郑楚之子郑元方订有婚约。后因郑楚去世，郑元方护丧迁往江陵，从此断了音信。卢女长大后，新县令韦计聘为子媳。在出阁那天的迎亲路上，卢女竟然被一只虎衔至县东十二里的一所佛舍，巧遇在那里临时过夜的郑元方。第二天，郑元方将卢女送回家，并将经过报告县令韦计。最后由韦计作主将卢女仍归郑元方。\n故事全篇突出了一个“巧”字，在艺术手法上颇有特色。在...", "authors": ["史美圣"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8d03048e64fbda97ab", "shortContent": "本篇写博陵崔瑴与一个笔怪小童的相遇过程。乍一看，这篇志怪小说不过是描述崔瑴怎样得到一管文笔，但细细读来，便会觉得作者的用意及手法颇有独到之处。\n其特点首先在于对崔瑴的描绘。文人本该是见笔如获至宝，可崔瑴对笔的态度却十分冷漠。当小童谓瑴曰“幸寄君砚席，可乎”时，崔瑴的态度是一声不应。当小童问“我尚壮，愿备指使，何见拒之深耶”时，崔瑴依然不理不睬，连看也不看。当小童来到崔瑴的床上，拱立良久，于袖中抽出...", "authors": ["王红箫"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8fd635634aee3f746e", "shortContent": "本篇文采绚烂，构思奇特，充满了道家气息。\n从全文对元、柳二公的描绘来看，元、柳二人大抵是当时功名无着的士人。他们二人所以不约而同地去探望被流放了的叔伯，可以推见二人平时与叔伯的关系是比较密切的。也许，元、柳二人曾对为官长辈寄托过什么希望，所以一旦这个希望破灭，二人当时的心境是可想而知的。既然探亲而来，却又在半途之中安排了一个奇遇，可见作者的本意并不在于二公探亲是否能够探成，而着意于二公涉足仙界的一...", "authors": ["罗怀臻"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f915e272d4b2255c225", "shortContent": "本篇原文在标题“狄方”之下又有一七言题目：“李主遣鬼取名画。”这是《青琐高议》特有的体例，鲁迅《中国小说史略》以为甚类元杂剧的“题目正名”，可能是为当时说书人准备的。\n李主即南唐后主李煜。他本是一个亡国之君，又是一个各种艺术兼工的才子，除了诗词创作之外，他还是一个著名的书画收藏家和鉴赏家。据说金陵城将陷时，李煜把所收藏的书画图籍交付给保仪黄氏。及城陷，李煜本人成了阶下囚，他一生聚集的书画及善本图书...", "authors": ["张仲谋"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f922e6a6b501f974bab", "shortContent": "容斋此篇，颇为奇特。它与一般志怪小说写花妖狐魅、鬼怪灵异旨趣不同，写的是器物成精。折足铛鼎之属，也能魅人作祟，化而为“半截美人”，文思之奇巧，出人意表。\n我们知道，洪迈的《夷坚志》，为宋代部头最大的私家小说，卷帙既多，势必庞杂，加之成书草率，不少篇目未曾很好润饰，故历来人们对它不无微词。如陈振孙《直斋书录解题》讥洪氏“谬用其心”，以为“多至于不胜载，则不得为异矣”。陈栎勤《有堂随录》则谓洪氏“欲修...", "authors": ["王星琦"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9c03572034f65b5dfa", "shortContent": "本篇写读书举子迷恋于科举功名遭狐奚落的故事。文分两部分，前为小说，后为议论。小说写王子安大醉失态，遭狐奚落，犹似做了一场功名醉梦。作者极尽其失常状态下的非失常的种种表现，生动而形象地刻画了科举制度对读书人的毒害。如果王子安真的及第得了进士，那么，小说中描写的情态，并不奇怪。小说妙在写放榜之前，将王子安一心及第的内心世界，趁其醉而尽情地暴露出来，得到的效果就比正常状态下的表现，来得深刻，在表现手法上...", "authors": ["李晓"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa10ce818559d071277", "shortContent": "欧美人信仰上帝，谓上帝无所不在，无所不知；中国人则认为冥冥之中，有鬼神在焉，于人之一举一动，甚至一念之善恶，亦无所不察。这些固然都是迷信，但在某种程度上皆出于导人向善的愿望。在志怪小说中，尤其是《阅微草堂笔记》中，则只须将它看作一种寓言手法，或说理的手段。这篇《郑苏仙梦至冥府》讲了两个故事，从情节上用郑苏仙梦至冥府的见闻相关联，在内容上则与上述观念相统一。而精华所在，则在两个故事中包含的两种人生处...", "authors": ["姚品文"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa50f8fda556506e4e8", "shortContent": "这个故事貌似荒诞，但细思之，它却反映了一个失意文人孤独落寞的悲剧遭遇。邓乙已到而立之年，但却既无功名富贵，又无良友妻妾，“每夜坐，一灯荧然，沉思郁结”。他甚至只能面对自己的影子叹息，希望影子能给自己一点快乐。而影子竟然真的从壁上下来，满足了他的一切愿望：或变为少年良友，长夜晤对；或变为官长贵人，衣冠俨然；或变为绝色少女，与其同寝。总之，功名富贵、良友美妻等封建文人希望得到的东西，都从影子那里得到了...", "authors": ["许金榜"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa65914587d02f66fcc", "shortContent": "本篇描写青年男女至诚的爱情。小说中的男主人公士人在前世乃为诸生，一日邻家的女子影娘坠钗帘下为士人拾得。影娘自此相思成疾，郁郁而亡。死后当念钗坠人间，为结前世孽缘，将钗赠予今世的士人，于是出现这一场人鬼相恋的趣剧。本文突出了男女青年爱情的至诚，特别是突出描写了影娘的一片痴情。\n小说的艺术构思颇具匠心。它在结构上可分三个层次：第一层次是士人春日登山，在泉边小憩，“拾得一玉钗，把弄冥想。忽水中，见丽女子...", "authors": ["纪乃咸"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa834a8757d5a0fa515", "shortContent": "本篇由三个各自独立的故事构成，三个故事中的鬼都没有粉墨登场，只是躲在幕后，从冥冥之中操纵着正在前台唱戏的那些人。故事中的三个主角其实都不曾想到过有鬼，更不会想到有厉鬼已经张开狰狞的利爪向他们的喉咙抓来。他们与人打交道，与同窗、新媳妇、道士开玩笑，最终落得的却是同样的下场：被无形中的鬼莫名其妙地吓死、缢死和击死。究其原因，似乎能这样解释：这三人太不知天高地厚，竟然胆大妄为到以死、以鬼为戏，这才招来恶...", "authors": ["欧阳云飞"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42b90f8fda556506f13a", "shortContent": "《春梦琐言》是一篇文言短篇小说。卷首有署名“沃焦山人”所撰的序言一篇，作于“崇祯丁丑”年间，估计这篇作品成于嘉靖、万历年间。\n\n这篇小说的情节很简单，写会稽富春人韩仲琏，才貌双全，惟心爱山水花草。一日春游，步入山洞，遇李姐芳华、棠娘锦云两女，侍寝交欢，尽鱼水之乐。后山鹃一声，大梦惊醒，乃凭石而坐，旁有两树：一是素李，花如积雪；二是海棠，英如升霞。才知其芳华者，李树之精；锦云者，海棠之精也。\n\n小说...", "authors": ["黄", "霖"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42c90ce818559d071fe7", "shortContent": "本篇选自清代陈其元所撰《庸闲斋笔记》卷十二。作者在是书《自序》中说：“隐恶扬善，事征诸实，不敢为荒唐谬悠之谈。”故本书以纪实为宗，文笔练达。《仕途中炎凉态》是其中记述游宦经历的一篇，它以相国勒保向方伯口述自己宦途所历，借主人公屈居下僚时临渊履薄、悲喜交错的心路历程，形象地揭示了当时官场的龌龊，人情的浇薄和仕途的炎凉。\n作品最突出的特点是对比手法的巧妙运用，即以主人公勒保拜谒总督前后的境遇作鲜明对比...", "authors": ["张进德康俊平"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42cad635634aee3f831e", "shortContent": "此文选自王韬笔记小说集《遯窟澜言》。\n《遯窟澜言》十二卷，系作者于同治年间避兵广东香海天南遯窟寓所时所作。作者“旨寓劝惩，意关风化；以善恶为褒贬，以贞淫为黜陟；俾愚顽易于观感，妇稚得以奋兴”。本篇即为其中富有思想意义的一篇。\n本文的主旨在于讽刺那些不学无术、浅薄鄙陋却又盲目骄傲的儒生。明清时期，赖以为社会统治集团输送新鲜血液的科举制度已经走向腐朽。当时知识分子只要熟读儒家经典，再将八股文的写作方法...", "authors": ["曹炳建"], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf303a", "shortContent": "随着西方文明在全世界的胜利，它对生命的看法也在整个世界文明中占据了统治地位。生命是什么？古希腊人的回答很简单，亚里士多德说：“绝大多数动物都有某种心理素质或倾向的迹象。这种心理素质在人身上显得更加分明，……人身上的上述某些素质，同动物身上相应的素质比较起来，也只有是差别而已。”认为人不过就是一种高级动物而已。\n\n既然人是动物，那么当然要将自己的动物性扩展到最大化。这样，野蛮、放纵、堕落，便成了合逻...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1524912259, '5ae3dffeac502e00625fe02d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637416, '庄子 · 外篇 · 知北游', NULL, 29, 16, 1, 1, '庄子', NULL, 10064, '57b90297165abd0054bfdce7', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E5%A4%96%E7%AF%87%C2%B7%E7%9F%A5%E5%8C%97%E6%B8%B8/10192398', '', '知北游于玄水之上，登隐弅之丘，而适遭无为谓焉。知谓无为谓曰：“予欲有问乎若：何思何虑则知道？何处何服则安道？何从何道则得道？”三问而无为谓不答也。非不答，不知答也。知不得问，反于白水之南，登狐阕之上，而睹狂屈焉。知以之言也问乎狂屈。狂屈曰：“唉！予知之，将语若。”中欲言而忘其所欲言。知不得问，反于帝宫，见黄帝而问焉。黄帝曰：“无思无虑始知道，无处无服始安道，无从无道始得道。”知问黄帝曰：“我与若知之，彼与彼不知也，其孰是邪？”黄帝曰：“彼无为谓真是也，狂屈似之，我与汝终不近也。夫知者不言，言者不知，故圣人行不言之教。道不可致，德不可至。仁可为也，义可亏也，礼相伪也。故曰：‘失道而后德，失德而后仁，失仁而后义，失义而后礼。’礼者，道之华而乱之首也。故曰：‘为道者日损，损之又损之，以至于无为。无为而无不为也。’今已为物也，欲复归根，不亦难乎！其易也其唯大人乎！生也死之徒，死也生之始，孰知其纪！人之生，气之聚也。聚则为生，散则为死。若死生为徒，吾又何患！故万物一也。是其所美者为神奇，其所恶者为臭腐。臭腐复化为神奇，神奇复化为臭腐。故曰：‘通天下一气耳。’圣人故贵一。”知谓黄帝曰：“吾问无为谓，无为谓不应我，非不我应，不知应我也；吾问狂屈，狂屈中欲告我而不我告，非不我告，中欲告而忘之也；今予问乎若，若知之，奚故不近？”黄帝曰：“彼其真是也，以其不知也；此其似之也，以其忘之也；予与若终不近也，以其知之也。”狂屈闻之，以黄帝为知言。
天地有大美而不言，四时有明法而不议，万物有成理而不说。圣人者，原天地之美而达万物之理。是故至人无为，大圣不作，观于天地之谓也。今彼神明至精，与彼百化。物已死生方圆，莫知其根也。扁然而万物，自古以固存。六合为巨，未离其内；秋豪为小，待之成体；天下莫不沉浮，终身不故；阴阳四时运行，各得其序；惽然若亡而存；油然不形而神；万物畜而不知：此之谓本根，可以观于天矣！
啮缺问道乎被衣，被衣曰：“若正汝形，一汝视，天和将至；摄汝知，一汝度，神将来舍。德将为汝美，道将为汝居。汝瞳焉如新生之犊而无求其故。”言未卒，啮缺睡寐。被衣大说，行歌而去之，曰：“形若槁骸，心若死灰，真其实知，不以故自持。媒媒晦晦，无心而不可与谋。彼何人哉！”
舜问乎丞：“道可得而有乎？”曰：“汝身非汝有也，汝何得有夫道！”舜曰：“吾身非吾有也，孰有之哉？”曰：“是天地之委形也；生非汝有，是天地之委和也；性命非汝有，是天地之委顺也；子孙非汝有，是天地之委蜕也。故行不知所往，处不知所持，食不知所味。天地之强阳气也，又胡可得而有邪！”
孔子问于老聃曰：“今日晏闲，敢问至道。”老聃曰：“汝齐戒，疏瀹而心，澡雪而精神，掊击而知。夫道，窅然难言哉！将为汝言其崖略：夫昭昭生于冥冥，有伦生于无形，精神生于道，形本生于精，而万物以形相生。故九窍者胎生，八窍者卵生。其来无迹，其往无崖，无门无房，四达之皇皇也。邀于此者，四肢强，思虑恂达，耳目聪明。其用心不劳，其应物无方，天不得不高，地不得不广，日月不得不行，万物不得不昌，此其道与！且夫博之不必知，辩之不必慧，圣人以断之矣！若夫益之而不加益，损之而不加损者，圣人之所保也。渊渊乎其若海，魏魏乎其终则复始也。运量万物而不匮。则君子之道，彼其外与！万物皆往资焉而不匮。此其道与！
“中国有人焉，非阴非阳，处于天地之间，直且为人，将反于宗。自本观之，生者，喑噫物也。虽有寿夭，相去几何？须臾之说也，奚足以为尧、桀之是非！果蓏有理，人伦虽难，所以相齿。圣人遭之而不违，过之而不守。调而应之，德也；偶而应之，道也。帝之所兴，王之所起也。
“人生天地之间，若白驹之过隙，忽然而已。注然勃然，莫不出焉；油然寥然，莫不入焉。已化而生，又化而死。生物哀之，人类悲之。解其天韬，堕其天帙。纷乎宛乎，魂魄将往，乃身从之。乃大归乎！不形之形，形之不形，是人之所同知也，非将至之所务也，此众人之所同论也。彼至则不论，论则不至；明见无值，辩不若默；道不可闻，闻不若塞：此之谓大得。”
东郭子问于庄子曰：“所谓道，恶乎在？”庄子曰：“无所不在。”东郭子曰：“期而后可。”庄子曰：“在蝼蚁。”曰：“何其下邪？”曰：“在稊稗。”曰：“何其愈下邪？”曰：“在瓦甓。”曰：“何其愈甚邪？”曰：“在屎溺。”东郭子不应。庄子曰：“夫子之问也，固不及质。正、获之问于监市履狶也，‘每下愈况’。汝唯莫必，无乎逃物。至道若是，大言亦然。周遍咸三者，异名同实，其指一也。尝相与游乎无有之宫，同合而论，无所终穷乎！尝相与无为乎！澹澹而静乎！漠而清乎！调而闲乎！寥已吾志，无往焉而不知其所至，去而来不知其所止。吾往来焉而不知其所终，彷徨乎冯闳，大知入焉而不知其所穷。物物者与物无际，而物有际者，所谓物际者也。不际之际，际之不际者也。谓盈虚衰杀，彼为盈虚非盈虚，彼为衰杀非衰杀，彼为本末非本末，彼为积散非积散也。”
婀荷甘与神农学于老龙吉。神农隐几，阖户昼瞑。婀荷甘日中奓户而入，曰：“老龙死矣！”神农隐几拥杖而起，嚗然放杖而笑，曰：“天知予僻陋谩诞，故弃予而死。已矣，夫子无所发予之狂言而死矣夫！”弇堈吊闻之，曰：“夫体道者，天下之君子所系焉。今于道，秋豪之端万分未得处一焉，而犹知藏其狂言而死，又况夫体道者乎！视之无形，听之无声，于人之论者，谓之冥冥，所以论道而非道也。”
于是泰清问乎无穷，曰：“子知道乎？”无穷曰：“吾不知。”又问乎无为，无为曰：“吾知道。”曰：“子之知道，亦有数乎？”曰：“有。”曰：“其数若何？”无为曰：“吾知道之可以贵、可以贱、可以约、可以散，此吾所以知道之数也。”泰清以之言也问乎无始，曰：“若是，则无穷之弗知与无为之知，孰是而孰非乎？”无始曰：“不知深矣，知之浅矣；弗知内矣，知之外矣。”于是泰清仰而叹曰：“弗知乃知乎，知乃不知乎！孰知不知之知？”无始曰：“道不可闻，闻而非也；道不可见，见而非也；道不可言，言而非也！知形形之不形乎！道不当名。”无始曰：“有问道而应之者，不知道也；虽问道者，亦未闻道。道无问，问无应。无问问之，是问穷也；无应应之，是无内也。以无内待问穷，若是者，外不观乎宇宙，内不知乎大初。是以不过乎昆仑，不游乎太虚。”
光曜问乎无有曰：“夫子有乎？其无有乎？”光曜不得问而孰视其状貌：窅然空然。终日视之而不见，听之而不闻，搏之而不得也。光曜曰：“至矣，其孰能至此乎！予能有无矣，而未能无无也。及为无有矣，何从至此哉！”
大马之捶钩者，年八十矣，而不失豪芒。大马曰：“子巧与！有道与？”曰：“臣有守也。臣之年二十而好捶钩，于物无视也，非钩无察也。”是用之者假不用者也，以长得其用，而况乎无不用者乎！物孰不资焉！
冉求问于仲尼曰：“未有天地可知邪？”仲尼曰：“可。古犹今也。”冉求失问而退。明日复见，曰：“昔者吾问‘未有天地可知乎？’夫子曰：‘可。古犹今也。’昔日吾昭然，今日吾昧然。敢问何谓也？”仲尼曰：“昔之昭然也，神者先受之；今之昧然也，且又为不神者求邪！无古无今，无始无终。未有子孙而有孙子可乎？”冉求未对。仲尼曰：“已矣，末应矣！不以生生死，不以死死生。死生有待邪？皆有所一体。有先天地生者物邪？物物者非物，物出不得先物也，犹其有物也。犹其有物也无已！圣人之爱人也终无已者，亦乃取于是者也。”
颜渊问乎仲尼曰：“回尝闻诸夫子曰：‘无有所将，无有所迎。’回敢问其游。”仲尼曰：“古之人外化而内不化，今之人内化而外不化。与物化者，一不化者也。安化安不化？安与之相靡？必与之莫多。狶韦氏之囿，黄帝之圃，有虞氏之宫，汤武之室。君子之人，若儒墨者师，故以是非相赍也，而况今之人乎！圣人处物不伤物。不伤物者，物亦不能伤也。唯无所伤者，为能与人相将迎。山林与，皋壤与，使我欣欣然而乐与！乐未毕也，哀又继之。哀乐之来，吾不能御，其去弗能止。悲夫，世人直为物逆旅耳！夫知遇而不知所不遇，知能能而不能所不能。无知无能者，固人之所不免也。夫务免乎人之所不免者，岂不亦悲哉！至言去言，至为去为。齐知之所知，则浅矣。”', '《庄子》是战国时期著名思想家庄周的毕生精华之作，《知北游》是《庄子·外篇》中的最后一篇，也是具有重要地位的一篇，对于了解《庄子》的哲学思想体系也较为重要。', '', '知向北游历来到玄水岸边，登上名叫隐弅的山丘，正巧在那里遇上了无为谓。知对无为谓说：“我想向你请教一些问题：怎样思索、怎样考虑才能懂得道？怎样居处、怎样行事才符合于道？依从什么、采用什么方法才能获得道？”问了好几次无为谓都不回答，不是不回答，而是不知道回答。知从无为谓那里得不到解答，便返回到白水的南岸，登上名叫狐阕的山丘，在那里见到了狂屈。知把先前的问话向狂屈提出请教，狂屈说：“唉，我知道怎样回答这些问题，我将告诉给你，可是心中正想说话却又忘记了那些想说的话”。知从狂屈那里也没有得到解答，便转回到黄帝的住所，见到黄帝向他再问。黄帝说：“没有思索、没有考虑方才能够懂得道，没有安处、没有行动方才能够符合于道，没有依从、没有方法方才能够获得道。”
知于是问黄帝：“我和你知道这些道理，无为谓和狂屈不知道这些道理，那么，谁是正确的呢？”黄帝说：“那无为谓是真正正确的，狂屈接近于正确；我和你则始终未能接近于道。知道的人不说，说的人不知道，所以圣人施行的是不用言传的教育。道不可能靠言传来获得，德不可能靠谈话来达到。没有偏爱是可以有所作为的，讲求道义是可以亏损残缺的，而礼仪的推行只是相互虚伪欺诈。所以说，‘失去了道而后能获得德，失去了德而后能获得仁，失去了仁而后能获得义，失去了义而后能获得礼。礼，乃是道的伪饰、乱的祸首’。所以说，‘体察道的人每天都得清除伪饰，清除而又再清除以至达到无为的境界，达到无所作为的境界也就没有什么可以作为的了。’如今你已对外物有所作为，想要再返回根本，不是很困难吗！假如容易改变而回归根本，恐怕只有是得道的人啊！
“生是死的同类，死是生的开始，谁能知道它们的端绪！人的诞生，是气的聚合，气的聚合形成生命，气的离散便是死亡。如果死与生是同类相属的，那么对于死亡我又忧患什么呢？所以，万物说到底是同一的。这样，把那些所谓美好的东西看作是神奇，把那些所谓讨厌的东西看作是臭腐，而臭腐的东西可以再转化为神奇，神奇的东西可以再转化为臭腐。所以说，‘整个天下只不过同是气罢了’。圣人也因此看重万物同一的特点。”
知又对黄帝说：“我问无为谓，无为谓不回答我，不是不回答我，是不知道回答我。我问狂屈，狂屈内心里正想告诉我却没有告诉我，不是不告诉我，是心里正想告诉我又忘掉了怎样告诉我。现在我想再次请教你，你懂得我所提出的问题，为什么又说回答了我便不是接近于道呢？”黄帝说：“无为谓他是真正了解大道的，因为他什么也不知道；狂屈他是接近于道的，因为他忘记了；我和你终究不能接近于道，因为我们什么都知道。”
狂屈听说了这件事，认为黄帝的话是最了解道的谈论。
天地具有伟大的美但却无法用言语表达，四时运行具有显明的规律但却无法加以评议，万物的变化具有现成的定规但却用不着加以谈论。圣哲的人，探究天地伟大的美而通晓万物生长的道理，所以“至人”顺应自然无所作为，“大圣”也不会妄加行动，这是说对于天地作了深入细致的观察。
大道神明精妙，参与宇宙万物的各种变化；万物业已或死、或生、或方、或圆，却没有谁知晓变化的根本，一切都是那么自然而然地自古以来就自行存在。“六合”算是十分巨大的，却始终不能超出道的范围；秋天的毫毛算是最小的，也得仰赖于道方才能成就其细小的形体。宇宙万物无时不在发生变化，始终保持着变化的新姿，阴阳与四季不停地运行，各有自身的序列。大道是那么浑沌昧暗仿佛并不存在却又无处不在，生机盛旺、神妙莫测却又不留下具体的形象，万物被它养育却一点也未觉察。这就称作本根，可以用它来观察自然之道了。
齧缺向被衣请教道，被衣说：“你得端正你的形体，集中你的视力，自然的和气便会到来；收敛你的心智，集中你的思忖，精神就会来你这里停留。玄德将为你而显得美好，大道将居处于你的心中，你那瞪着圆眼稚气无邪的样子就像初生的小牛犊而不会去探求外在的事物！”
被衣话还没说完，齧缺便已睡着。被衣见了十分高兴，唱着歌儿离去，说：“身形犹如枯骸，内心犹如死灰，朴实的心思返归本真，而且并不因为这个缘故而有所矜持，浑浑噩噩，昏昏暗暗，没有心计而不能与之共谋。那将是什么样的人啊！”
舜向丞请教说：“道可以获得而据有吗？”丞说：“你的身体都不是你所据有，你怎么能获得并占有大道呢？”舜说：“我的身体不是由我所有，那谁会拥有我的身体呢？”丞说：“这是天地把形体托给了你；降生人世并非你所据有，这是天地给予的和顺之气凝积而成，性命也不是你所据有，这也是天地把和顺之气凝聚于你；即使是你的子孙也不是你所据有，这是天地所给予你的蜕变之形。所以，行走不知去哪里，居处不知持守什么，饮食不知什么滋味；行走、居处和饮食都不过是天地之间气的运动，又怎么可以获得并据有呢？”
孔子对老聃说：“今天安居闲暇，我冒昧地向你请教至道。”老聃说：“你先得斋戒静心，再疏通你的心灵，清扫你的精神，破除你的才智！大道，真是深奥神妙难以言表啊！不过我将为你说个大概。
“明亮的东西产生于昏暗，具有形体的东西产生于无形，精神产生于道，形质产生于精微之气。万物全都凭借形体而诞生，所以，具有九个孔窍的动物是胎生的，具有八个孔窍的动物是卵生的。它的来临没有踪迹，它的离去没有边界，不知从哪儿进出、在哪儿停留，通向广阔无垠的四面八方。遵循这种情况的人，四肢强健，思虑通达，耳目灵敏，运用心思不会劳顿，顺应外物不拘定规。天不从它那儿获得什么便不会高远，地不从那儿获得什么便不会广大，太阳和月亮不能从那儿获得什么便不会运行，万物不能从那儿获得什么便不会昌盛，这恐怕就是道啊！
“再说博读经典的人不一定懂得真正的道理，善于辩论的人不一定就格外聪明，圣人因而断然割弃上述种种做法。至于增多了却不像是更加增加，减少了却不像是有所减少，那便是圣人所要持守的东西。深邃莫测呀它像大海一样，高大神奇呀它没有终结也没有开始，万物的运动全在它的范围之内，而且从不曾缺少什么。那么，世俗君子所谈论的大道，恐怕都是些皮毛啊！万物全都从它那里获取生命的资助，而且从不匮乏，这恐怕就是道啊！
“中原一带有人居住着，不偏于阴也不偏于阳，处在大地的中间，只不过姑且具备了人的形体罢了，而人终将返归他的本原。从道的观点来看，人的诞生，乃是气的聚合，虽然有长寿与短命，相差又有多少呢？说起来只不过是俄顷之间，又哪里用得着区分唐尧和夏桀的是非呢！果树和瓜类各不相同却有共同的生长规律，人们的次第关系即使难以划分，也还可以用年龄大小相互为序。圣人遇上这些事从不违拗，即使亲身过往也不会滞留。调和而顺应，这就是德；无心却适应，这就是道；而德与道便是帝业兴盛的凭藉，王侯兴起的规律。
“人生于天地之间，就像骏马穿过一个狭窄的通道，瞬间而过罢了。自然而然地，全都蓬勃而生；自然而然地，全都顺应变化而死。业已变化而生长于世间，又会变化而死离人世，活着的东西为之哀叹，人们为之悲悯。可是人的死亡，也只是解脱了自然的捆束，毁坏了自然的拘括，纷纷绕绕地，魂魄必将消逝，于是身形也将随之而去，这就是最终归向宗本啊！不具有形体变化而为有了形体，具有形体再变化而为消失形体，这是人们所共同了解的，绝不是体察大道的人所追求的道理，也是人们所共同谈论的话题。体悟大道的人就不会去议论，议论的人就没有真正体悟大道。显明昭露地寻找不会真正有所体察，宏辞巧辩不如闭口不言。道不可能通过传言而听到，希望传闻不如塞耳不听，这就称作是真正懂得了玄妙之道。”
东郭子向庄子请教说：“人们所说的道，究竟存在于什么地方呢？”庄子说：“大道无所不在。”东郭子曰：“必定得指出具体存在的地方才行。”庄子说：“在蝼蚁之中。”东郭子说：“怎么处在这样低下卑微的地方？”庄子说：“在稻田的稗草里。”东郭子说：“怎么越发低下了呢？”庄子说：“在瓦块砖头中。”东郭子说：“怎么越来越低下呢？”庄子说：“在大小便里。”东郭子听了后不再吭声。
庄子说：“先生的提问，本来就没有触及道的本质，一个名叫获的管理市场的官吏向屠夫询问猪的肥瘦，踩踏猪腿的部位越是往下就越能探知肥瘦的真实情况。你不要只是在某一事物里寻找道，万物没有什么东西可以逃离开它。‘至道’是这样，最伟大的言论也是这样。万物、言论和大道遍及各个角落，它们名称各异而实质却是相同，它们的意旨是归于同一的。让我们一道游历于什么也没有的地方，用混同合一的观点来加以讨论，宇宙万物的变化是没有穷尽的啊！我们再顺应变化无为而处吧！恬淡而又寂静啊！广漠而又清虚啊！调谐而又安闲啊！我的心思早已虚空宁寂，不会前往何处也不知道应该去到哪里，离去以后随即归来也从不知道停留的所在，我已在人世来来往往却并不了解哪里是最后的归宿；放纵我的思想遨游在虚旷的境域，大智的人跟大道交融相契而从不了解它的终极。造就万物的道跟万物本身并无界域之分，而事物之间的界线，就是所谓具体事物的差异；没有差异的区别，也就是表面存在差异而实质并非有什么区别。人们所说的盈满、空虚、衰退、减损，认为是盈满或空虚而并非真正是盈满或空虚，认为是衰退或减损而并非真正是衰退或减损，认为是宗本或末节而并非真正是宗本或末节，认为是积聚或离散而并非真正是积聚或离散。”
妸荷甘和神农一同在老龙吉处学习。神农大白天靠着几案、关着门睡觉，中午时分，妸荷甘推门而入说：“老龙吉死了！”神农抱着拐杖站起身来，“啪”的一声丢下拐杖而笑起来，说：“老龙吉知道我见识短浅心志不专，所以丢下了我而死去。完了，我的先生！没有用至道的言论来启发教导我就死去了啊！”
弇堈吊知道了这件事，说：“体悟大道的人，天下一切有道德修养的人都将归附于他。如今老龙吉对于道，连秋毫之末的万分之一也未能得到，尚且懂得深藏他的谈吐而死去，又何况真正体悟大道的人呢！大道看上去没有形体，听起来没有声音，对于人们所谈论的道，可以说是昏昧而又晦暗，可以加以谈论的所谓的“道”，实际上并不是真正的道。”
于是，泰清向无穷请教：“你知晓道吗？”无穷回答：“我不知晓。”又问无为。无为回答说：“我知晓道。”泰清又问：“你知晓道，道也有名目吗？”无为说：“有。”泰清说：“道的名目怎么样呢？”无为说：“我知道道可以处于尊贵，也可以处于卑贱，可以聚合，也可以离散，这就是我所了解的道的名数。”
泰清用上述谈话去请教无始，说：“像这样，那么无穷的不知晓和无为的知晓，谁对谁错呢？”无始说：“不知晓是深奥玄妙，知晓是浮泛浅薄；不知晓处于深奥玄妙之道的范围内，知晓却刚好与道相乖背。”于是泰清半中有所醒悟而叹息，说：“不知晓就是真正的知晓啊！知晓就是真正的不知晓啊！有谁懂得不知晓的知晓呢？”
无始说：“道不可能听到，听到的就不是道；道不可能看见，看见了就不是道；道不可以言传，言传的就不是道。要懂得有形之物之所以具有形体正是因为产生于无形的道啊！因此大道不可以称述。”
无始又说：“有人询问大道便随口回答的，乃是不知晓道。就是询问大道的人，也不曾了解过道。道无可询问，问了也无从回答。无可询问却一定要问，这是在询问空洞无形的东西；无从回答却勉强回答，这是说对大道并无了解。内心无所得却期望回答空洞无形的提问，像这样的人，对外不能观察广阔的宇宙，对内不能了解自身的本原，所以不能越过那高远的昆仑，也不能遨游于清虚宁寂的太虚之境。”
光曜问无有：“先生你是存在呢？还是不存在呢？”无有不吭声，光曜得不到回答，便仔细地观察它的形状和容貌，是那么深远那么空虚，整天看它看不见，整天听它听不到，整天捕捉它却摸不着。
光曜说：“最高的境界啊，谁能够达到这种境界呢！我能够做到‘无’，却未能达到‘无无’，等到做到了‘无’却仍然是在基于‘有’，从哪儿能够达到这种境界啊！”
大司马家锻制带钩的人，年纪虽然已经八十，却一点也不会出现差误。大司马说：“你是特别灵巧呢，还是有什么门道呀？”锻制带钩的老人说：“我遵循着道。我二十岁时就喜好锻制带钩，对于其他外在的事物我什么也看不见，不是带钩就不会引起我的专注。锻制带钩这是得用心专一的事，借助这一工作便不再分散自己的用心，而且锻制出的带钩得以长期使用，更何况对于那些无可用心之事啊！能够这样，外物有什么不会予以资助呢？”
冉求向孔子请教：“天地产生以前的情况可以知道吗？”孔子说：“可以，古时候就像今天一样。”冉求没有得到满意的回答便退出屋来，第二天再次见到孔子，说：“昨天我问‘天地产生以前的情况可以知道吗？’先生回答说：‘可以，古时候就象今天一样。’昨天我心里还很明白，今天就糊涂了，请问先生说的是什么意思呢？”孔子说：“昨天你心里明白，是因为心神先有所领悟；今天你糊涂了，是因为又拘滞于具体形象而有所疑问吧？没有古就没有今，没有开始就没有终结。不曾有子孙而存在子孙，可以吗？”冉求不能回答。
孔子说：“算了，不必再回答了！不会为了生而使死者复生，不会为了死而使生者死去。人的死和生相互有所依赖吗？其实全存在于一个整体。有先于天地而产生的物类吗？使万物成为具有各别形体事物的并不是具有形体的事物。万物的产生不可能先行出现具象性的物体，而是气的聚合而产生万物。由气的聚合形成万物之后，这才连续不断繁衍生息。圣人对于人的怜爱始终没有终结，也就是取法于万物的生生相续。”
颜渊问孔子说：“我曾听先生说过：‘不要有所送，也不要有所迎。’请问先生，一个人应该怎样居处与闲游。”
孔子说：“古时候的人，外表适应环境变化但内心世界却持守凝寂，现在的人，内心世界不能凝寂持守而外表又不能适应环境的变化。随应外物变化的人，必定内心纯一凝寂而不离散游移。对于变化与不变化都能安然听任，安闲自得地跟外在环境相顺应，必定会与外物一道变化而不有所偏移。狶韦氏的苑囿，黄帝的果林，虞舜的宫室，商汤、周武王的房舍，都是他们养心任物的好处所。那些称作君子的人，如像儒家、墨家之流，以是非好坏来相互诋毁，何况现时的人呢！圣人与外物相处却不损伤外物。不伤害外物的人，外物也不会伤害他。正因为无所伤害，因而能够与他人自然相送或相迎。山林呢，还是旷野呢？这都使我感到无限欢乐啊！可是欢乐还未消逝，悲哀又接着到来。悲哀与欢乐的到来，我无法阻挡，悲哀与欢乐的离去，我也不可能制止。可悲啊，世上的人们只不过是外物临时栖息的旅舍罢了。人们知道遇上了什么却不知道遇不上什么，能够做自身能力所及却不能做自身能力所不及的事。不知道与不能够，本来就是人们所不可回避的，一定要避开自己所不能避开的事，难道不可悲吗！最好的言论是什么也没说，最好的行动是什么也没做。要想把每个人所知道的各种认识全都等同起来，那就实在是浅陋了。”', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f985e272d4b2255c249", "shortContent": "蒲松龄《聊斋志异》一书以搜神状鬼见称于世，书中所刻画的狐仙神鬼不下数百千，大多荒诞而有情，富于人性，然亦不乏狰狞可怖者，其中给人印象最深的莫过于本篇画皮之鬼了。此鬼的本来面目是“面翠色，齿巉巉如锯”，当受到威胁时乃“卧嗥如猪”，看来这大概是一个凶猛的野兽修炼而成的精怪。物之凶猛丑怪者并不一定就可憎可怖，此物之可憎可怖处乃在于“画皮”。它不以本来面目示人，“铺人皮于榻，执彩笔而绘之”，“披于身，遂化...", "authors": ["刘明今"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9dc6e67846a9226e05", "shortContent": "《姬生》是一篇寓言小说，作者借姬生和狐仙的故事来表叙他对世上君子与小人之间关系的思考。文中之狐在鄂家惯窃金钱什物，显然属小人一类。鄂家之人痛恨它，思欲惩罚，然“迁之，祟益甚”。鄂家拿它毫无办法，于是君子姬生出现了。他采取和鄂家完全不同的态度来对待此狐，即把它当作良知未泯的人，所谓“彼能幻变，必有人心，我固将引之，俾入正果”。他屏除一切威胁的办法，焚香祝告，以兄称之。当二百钱失去后，他把更多的钱放在...", "authors": ["刘明今"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa2d635634aee3f74fa", "shortContent": "《阅微草堂笔记》是一部瑕瑜互见、众论不一的作品，涉及内容广泛而不稍嫌芜杂，因此能为旧时各类知识分子所择取。其所可贵者，是对讲学家每多问难与嘲讽，“造戏语以垢俗儒”（见《滦阳消夏录》），揭露道学先生的无知和伪诈，而对一般人不尽符合礼教之处，则往往以情原之，待以宽恕之道。同时，《阅微草堂笔记》的大部分篇章情节平淡，不讲究故事性。纪昀曾再三强调他所有的文字都是以期“不乖于风教”，“有益于劝惩”的。因此，...", "authors": ["邹自振"], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf3039", "shortContent": "今天呈现在我们面前的这个现代文明，其风貌并非从来如此。自14世纪以来，欧洲人从故纸堆里复兴了古希腊文明，跟他们固有的基督信仰一起被推广到了全世界。这个文明认为，世界只是表象的，人的主观意识运动与客观世界的运行毫不相关；人顶多只能通过对象性的实践活动才能改造自然。一句话，这个文明否定人与世界的天然联系。\n\n中国古文明却从来不这么看。中国古人认为，人的生命能量运动从来就与天地宇宙的能量运动是一个整体，...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1524912308, '5ae3e031ac502e00625fe1ae', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637417, '庄子 · 杂篇 · 庚桑楚', NULL, 14, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E6%9D%82%E7%AF%87%C2%B7%E5%BA%9A%E6%A1%91%E6%A5%9A/10192714?fr=aladdin', '', '老聃之役有庚桑楚者，偏得老聃之道，以北居畏垒之山，其臣之画然知者去之，其妾之挈然仁者远之；拥肿之与居，鞅掌之为使。居三年，畏垒大壤。畏垒之民相与言曰：“庚桑之子始来，吾洒然异之。今吾日计之而不足，岁计之而有馀。庶几其圣人乎！子胡不相与尸而祝之，社而稷之乎？”庚桑子闻之，南面而不释然。弟子异之。庚桑子曰：“弟子何异于予？夫春气发而百草生，正得秋而万宝成。夫春与秋，岂无得而然哉？天道已行矣。吾闻至人，尸居环堵之室，而百姓猖狂不知所如往。今以畏垒之细民而窃窃焉欲俎豆予于贤人之间，我其杓之人邪！吾是以不释于老聃之言。”弟子曰：“不然。夫寻常之沟，巨鱼无所还其体，而鲵鱿为之制；步仞之丘陵，巨兽无所隐其躯，而{薛女}狐为之祥。且夫尊贤授能，先善与利，自古尧、舜以然，而况畏垒之民乎！夫子亦听矣！”庚桑子曰：“小子来！夫函车之兽，介而离山，则不免于网罟之患；吞舟之鱼，砀而失水，则蚁能苦之。故鸟兽不厌高，鱼鳖不厌深。夫全其形生之人，藏其身也，不厌深眇而已矣。
且夫二子者，又何足以称扬哉！是其于辩也，将妄凿垣墙而殖蓬蒿也。简发而栉，数米而炊，窃窃乎又何足以济世哉！举贤则民相轧，任和则民相盗。之数物者，不足以厚民。民之于利甚勤，子有杀父，臣有杀君，正昼为盗，日中穴阫。吾语女，大乱之本，必生于尧、舜之间，其末存乎千世之后。千世之后，其必有人与人相食者也！”
南荣趎蹴然正坐曰：“若趎之年者已长矣，将恶乎托业以及此言邪？”庚桑子曰：“全汝形，抱汝生，无使汝思虑营营。若此三年，则可以及此言矣。”南荣趎曰：“目之与形，吾不知其异也，而盲者不能自见；耳之与形，吾不知其异也，而聋者不能自闻；心之与形，吾不知其异也，而狂者不能自得。
形之与形亦辟矣，而物或间之邪，欲相求而不能相得？今谓趎曰：‘全汝形，抱汝生，勿使汝思虑营营。’趎勉闻道达耳矣！”庚桑子曰：“辞尽矣。曰奔蜂不能化藿蠋，越鸡不能伏鹄卵，鲁鸡固能矣。
鸡之与鸡，其德非不同也，有能与不能者，其才固有巨小也。今吾才小，不足以化子。子胡不南见老子！”南荣趎赢粮，七日七夜至老子之所。
老子曰：“子自楚之所来乎？”南荣趎曰：“唯。”老子曰：“子何与人偕来之众也？”南荣趎惧然顾其后。
老子曰：“子不知吾所谓乎？”南荣趎俯而惭，仰而叹曰：“今者吾忘吾答，因失吾问。”老子曰：“何谓也？”南荣趎曰：“不知乎？人谓我朱愚。知乎？反愁我躯。不仁则害人，仁则反愁我身；不义则伤彼，义则反愁我己。我安逃此而可？此三言者，趎之所患也，愿因楚而问之。”老子曰：“向吾见若眉睫之间，吾因以得汝矣，今汝又言而信之。若规规然若丧父母，揭竿而求诸海也。女亡人哉，惘惘乎！汝欲反汝性情而无由入，可怜哉！”南荣趎请入就舍，召其所好，去其所恶，十日自愁，复见老子。
老子曰：“汝自洒濯，熟哉郁郁乎！然而其中津津乎犹有恶也。夫外韄者不可繁而捉，将内揵；内韄者不可缪而捉，将外揵。外内韄者，道德不能持，而况放道而行者乎！”南荣趎曰：“里人有病，里人问之，病者能言其病，然其病，病者犹未病也。若趎之闻大道，譬犹饮药以加病也。趎愿闻卫生之经而已矣。”老子曰：“卫生之经，能抱一乎？能勿失乎？能无卜筮而知吉凶乎？能止乎？能已乎？能舍诸人而求诸己乎？能翛然乎？能侗然乎？能儿子乎？儿子终日嗥而嗌不嗄，和之至也；终日握而手不掜，共其德也；终日视而目不瞚，偏不在外也。行不知所之，居不知所为，与物委蛇，而同其波。是卫生之经已。”南荣趎曰：“然则是至人之德已乎？”曰：“非也。是乃所谓冰解冻释者，能乎？夫至人者，相与交食乎地而交乐乎天，不以人物利害相撄，不相与为怪，不相与为谋，不相与为事，翛然而往，侗然而来。是谓卫生之经已。”曰：“然则是至乎？”曰：“未也。吾固告汝曰：‘能儿子乎？’儿子不知所为，行不知所之，身若槁木之枝而心若死灰。若是者，祸亦不至，福亦不来。祸福无有，恶有人灾也！”宇泰定者，发乎天光。发乎天光者，人见其人，物见其物。人有修者，乃今有恒；有恒者，人舍之，天助之。人之所舍，谓之天民；天之所助，谓之天子。
学者，学其所不能学也；行者，行其所不能行也；辩者，辩其所不能辩也。
知止乎其所不能知，至矣；若有不即是者，天钧败之。
备物以将形，藏不虞以生心，敬中以达彼，若是而万恶至者，皆天也，而非人也，不足以滑成，不可内于灵台。灵台者有持，而不知其所持，而不可持者也。
不见其诚己而发，每发而不当，业入而不舍，每更为失。为不善乎显明之中者，人得而诛之；为不善乎幽闲之中者，鬼得而诛之。明乎人，明乎鬼者，然后能独行。
券内者，行乎无名；券外者，志乎期费。行乎无名者，唯庸有光；志乎期费者，唯贾人也，人见其跂，犹之魁然。与物穷者，物入焉；与物且者，其身之不能容，焉能容人！不能容人者无亲，无亲者尽人。兵莫憯于志，镆铘为下；寇莫大于阴阳，无所逃于天地之间。非阴阳贼之，心则使之也。
道通，其分也，其成也毁也。所恶乎分者，其分也以备；所以恶乎备者，其有以备。故出而不反，见其鬼；出而得，是谓得死。灭而有实，鬼之一也。以有形者象无形者而定矣。
出无本，入无窍，有实而无乎处，有长而无乎本剽，有所出而无窃者有实。
有实而无乎处者，宇也。有长而无本剽者，宙也。有乎生，有乎死，有乎出，有乎入，入出而无见其形，是谓天门。天门者，无有也，万物出乎无有。有不能以有为有，必出乎无有，而无有一无有。圣人藏乎是。
古之人，其知有所至矣。恶乎至？有以为未始有物者，至矣，尽矣，费可以加矣。其次以为有物矣，将以生为丧也，以死为反也，是以分已。其次曰始无有，既而有生，生俄而死；以无有为首，以生为体，以死为尻；孰知有无死生之一守者，吾与之为友。是三者虽异，公族也。昭景也，著戴也；甲氏也，著封也，非一也。
有生，黬也，披然曰移是。尝言移是，非所言也。虽然，不可知者也。
腊者之有膍胲，可散而不可散也；观室者周于寝庙，又适其偃焉，为是举移是。
请常言移是。是以生为本，以知为师，因以乘是非；果有名实，因以己为质；使人以为己节，因以死偿节。若然者，以用为知，以不用为愚，以彻为名，以穷为辱。移是，今之人也，是蜩与学鸠同于同也。
蹍市人之足，则辞以放骜，兄则以妪，大亲则已矣。故曰，至礼有不人，至义不物，至知不谋，至仁无亲，至信辟金。
彻志之勃，解心之谬，去德之累，达道之塞。贵富显严名利六者，勃志也。
容动色理气意六者，谬心也。恶欲喜怒哀乐六者，累德也。去就取与知能六者，塞道也。此四六者不荡胸中则正，正则静，静则明，明则虚，虚则无为而无不为也。道者，德之钦也；生者，德之光也；性者，生之质也。性之动，谓之为；为之伪，谓之失。知者，接也；知者，谟也；知者之所不知，犹睨也。动以不得已之谓德，动无非我之谓治，名相反而实相顺也。
羿工乎中微而拙乎使人无己誉。圣人工乎天而拙乎人。夫工乎天而俍乎人者，唯全人能之。唯虫能虫，唯虫能天。全人恶天？恶人之天？而况吾天乎人乎！一雀适羿，羿必得之，威也；以天下为之笼，则雀无所逃。是故汤以胞人笼伊尹，秦穆公以五羊之皮笼百里奚。是故非以其所好笼之而可得者，无有也。
介者拸画，外非誉也；胥靡登高而不惧，遗死生也。夫复謵不馈而忘人，忘人，因以为天人矣。故敬之而不喜，侮之而不怒者，唯同乎天和者为然。出怒不怒，则怒出于不怒矣；出为无为，则为出于无为矣。欲静则平气，欲神则顺心，有为也。欲当则缘于不得已，不得已之类，圣人之道。', '《庄子·杂篇·庚桑楚》：庚桑楚是首句里的一个人名，这里以人名为篇名。全篇涉及许多方面的内容，有讨论顺应自然倡导无为的，有讨论认知的困难和是非难以认定的，但多数段落还是在讨论养生。全文大体分为五个部分。', '', '老聃的弟子中有个叫庚桑楚的，独得老聃真传，居住在北边的畏垒山，奴仆中着力炫耀才智的他就让他们纷纷离去，侍婢中着力标榜仁义的他就让他们远离自己；只有敦厚朴实的人跟他住在一起，只有任性自得的人作为他的役使。居住三年，畏垒山一带大丰收。畏垒山一带的人民相互传言：“庚桑楚刚来畏垒山，我们都微微吃惊感到诧异。如今我们一天天地计算收入虽然还嫌不足，但一年总的计算收益也还富足有余。庚桑楚恐怕就是圣人了吧！大家何不共同像供奉神灵一样供奉他，像对待国君一样地敬重他？”
庚桑楚听到了大家的谈论，坐朝南方心里很不愉快。弟子们感到奇怪。庚桑楚说：“你们对我有什么感到奇怪呢？春天阳气蒸腾勃发百草生长，正当秋天时节庄稼成熟果实累累。春天与秋天，难道无所遵循就能够这样吗？这是自然规律的运行与变化。我听说道德修养极高的人，像没有生命的人一样虚淡宁静地生活在斗室小屋内，而百姓纵任不羁全不知道应该做些什么。如今畏垒山一带的庶民百姓私下里谈论想把我列入贤人的行列而加以供奉，我难道乐意成为众人所注目的人吗？我正因为遵从老聃的教诲而对此大不愉快。”弟子说：“不是这样的。小水沟里，大鱼没有办法回转它的身体，可是小小的泥鳅却能转身自如；矮小的山丘，大的野兽没有办法隐匿它的躯体，可是妖狐却正好得以栖身。况且尊重贤才授权能人，以善为先给人利禄，从尧舜时代起就是这样，何况畏垒山一带的百姓呢！先生你还是顺从大家的心意吧！”庚桑楚说：“小子你过来！口能含车的巨兽，孤零零地离开山野，那就不能免于罗网的灾祸；口能吞舟的大鱼，一旦被水波荡出水流，小小的蚂蚁也会使它困苦不堪。所以鸟兽不厌山高，鱼鳖不厌水深。保全身形本性的人，隐匿自己的身形，不厌深幽高远罢了。至于尧与舜两个人，又哪里值得加以称赞和褒扬呢！尧与舜那样分辨世上的善恶贤愚，就像是在胡乱地毁坏好端端的垣墙而去种上没有什么用处的蓬蒿。选择头发来梳理，点数米粒来烹煮，计较于区区小事又怎么能够有益于世啊！举荐贤才人民就会相互出现伤害，任用智能百姓就会相互出现伪诈。这数种作法，不足以给人民带来好处。人们对于追求私利向来十分迫切，为了私利有的儿子杀了父亲，有的臣子杀了国君，大白天抢人，光天化日之下在别人墙上打洞。我告诉你，天下大乱的根源，必定是产生于尧舜的时代，而它的流毒和遗害又一定会留存于千年之后。千年之后，还将会出现人与人相食的情况哩！”
南荣趎虔敬地端正而坐，说：“像我这样的人已经年纪大了，将怎样学习才能达到你所说的那种境界呢？”庚桑楚说：“保全你的身形，护养你的生命，不要使你的思虑为求取私利而奔波劳苦。像这样三年时间，那就可以达到我所说的那种境界了。”南荣趎说：“盲人的眼睛和普通人的眼睛，彼此的外形我看不出有什么不同，而盲人的眼睛却看不见东西；聋子的耳朵和普通人的耳朵，彼此的外形我看不出有什么不同，而聋子的耳朵却听不见声音；疯狂人的样子与普遍人的样子，彼此之间我看不出有什么不同，而疯狂人却不能把持自己。形体与形体之间本是相通的，但出现不同的感知是外物有什么使之区别吗？还是希望获得却始终未能获得呢？如今先生对我说：‘保全你的身形，护养你的生命，不要使你的思虑为求取私利而奔波劳苦。’我只不过勉强听到耳里罢了！”
庚桑楚说：“我的话说尽了。小土蜂不能孵化出豆叶虫，越鸡不能孵化天鹅蛋，而鲁鸡却能够做到。鸡与鸡，它们的禀赋并没有什么不同，有的能做到有的不能做到，是因为它们的本领原本就有大有小。拿现在说我的才干就很小，不足以使你受到感化，你何不到南方去拜见老子？”
南荣趎带足干粮，走了七天七夜来到老子的住所。老子说：“你是从庚桑楚那儿来的吧？”南荣趎说：“是的。”老子说：“怎么跟你一块儿来的人如此多呢？”南荣趎恐惧地回过头来看看自己的身后。老子说：“你不知道我所说的意思吗？”南荣趎低下头来羞惭满面，而后仰面叹息：“现在我已忘记了我应该怎样回答，因为我忘掉了我的提问。”老子说：“什么意思呢？”南荣趎说：“不聪明吗？人们说我愚昧无知。聪明吗？反而给身体带来愁苦和危难。不具仁爱之心便会伤害他人，推广仁爱之心反而给自身带来愁苦和危难。不讲信义便会伤害他人，推广信义反而给自己带来愁苦和危难。这三句话所说的情况，正是我忧患的事，希望因为庚桑楚的引介而获得赐教。”老子说：“刚来时我察看你眉宇之间，也就借此了解了你的心思。如今你的谈话更证明了我的观察。你失神的样子真像是失去了父母，又好像在举着竹竿探测深深的大海。你确实是一个丧失了真性的人啊，是那么迷惘而又昏昧！你一心想返归你的真情与本性却不知道从哪里做起，实在是值得同情啊！”
南荣趎回到寓所，求取自己所喜好的东西，舍弃自己所讨厌的东西，整整十天愁思苦想，再去拜见老子。老子说：“你作了自我反省，郁郁不安的心情实在是沉重啊！然而你心中那充满外溢的情况说明还是存有邪念。受到外物的束缚便不可避免繁杂与急促，于是内心世界必将堵塞不通；内心世界受到束缚便不可避除杂乱无绪和急促，于是外部感官必定会闭塞不通。外部感官和内心世界都被束缚缠绕，即使道德高尚也不能持守，何况是初初学道仿行的人呢！”
南荣趎说：“邻里的人生了病，周围的乡邻询问他，生病的人能够说明自己的病情，而能够把自己的病情说个清楚的人，那就算不上是生了重病。像我这样的听闻大道，好比服用了药物反而加重了病情，因而我只希望能听到养护生命的常规罢了。”老子说：“养护生命的常规，能够使身形与精神浑一谐合吗？能够不失却真性吗？能够不求助于卜筮而知道吉凶吗？能够满足于自己的本分吗？能够对消逝了的东西不作追求吗？能够舍弃仿效他人的心思而寻求自身的完善吗？能够无拘无束、自由自在吗？能够心神宁寂无所执著吗？能够像初生的婴儿那样纯真、朴质吗？婴儿整天啼哭咽喉却不会嘶哑，这是因为声音谐和自然达到了顶点；婴儿整天握着小手而不松开，这是因为听任小手自然地握着乃是婴儿的天性与常态；婴儿整天瞪着小眼睛一点也不眨眼，这是因为内心世界不会滞留于外界事物。行走起来不知道去哪里，平日居处不知道做什么，接触外物随顺应合，如同随波逐流、听其自然：这就是养护生命的常规了。”
南荣趎：“那么这就是至人的最高思想境界吗？”老子回答：“不是的。这仅只是所谓冰冻消解那样自然消除心中积滞的本能吧？道德修养最高尚的人，跟人们一块儿向大地寻食而又跟人们一块儿向天寻乐，不因外在的人物或利害而扰乱自己，不参与怪异，不参与图谋，不参与尘俗的事务，无拘无束、自由自在地走了。又心神宁寂无所执著地到来。这就是所说的养护生命的常规。”南荣趎说：“那么这就达到了最高的境界吗？”老子说：“没有。我原本就告诉过你：‘能够像初生的婴儿那样纯真、朴质吗？’婴儿活动不知道干什么，行走不知道去哪里，身形像枯槁的树枝而心境像熄尽了死灰。像这样的人，灾祸不会到来，幸福也不会降临。祸福都不存在，哪里还会有人间的灾害呢！”
心境安泰镇定的人，就会发出自然的光芒。发出自然光芒的，人各自显其为人，物各自显其为物。注重修养的人，才能保持较高的道德修养境界；保持较高的道德修养境界，人们就会自然地向往他，上天也会帮助他。人们所向往的，称他叫做天民；上天辅佐的，称他叫做天子。
学习，是想要学习那些不能学到的东西；行走，是想要去到那些不能去到的地方；分辨，是想要分辨那些不易辨清的事物。知道停留于所不知道的境域，便达到了知道的极点。假如有人不是这样，那么自然的禀性一定会使他败亡。
备足造化的事物而顺应成形，深敛外在情感不作任何思虑而使心境快活并富有生气，谨慎地持守心中的一点灵气用以通达外在事物，像这样做而各种灾祸仍然纷至沓来，那就是自然安排的结果，而不是人为所造成，因而不足以扰乱成性，也不可以纳入灵府。灵府，就是有所持守却不知道持守什么，并且不可以着意去持守的地方。不能表现真诚的自我而任随情感外驰，虽然有所表露却总是不合适宜，外事一旦侵扰心中就不会轻易离去，即使有所改变也会留下创伤。在光天化日下做了坏事，人人都会谴责他、处罚他；在昏暗处隐蔽地做下坏事，鬼神也会谴责他、处罚他。对于人群清白光明，对于鬼神也清白光明，这之后便能独行于世。
各分合乎自身，行事就不显于名声；名分超出自身，就是心思也总在于穷尽财用。行事不显名声的人，即使平庸也有光辉；心思在于穷尽财用的人，只不过是商人而已，人人都能看清他们在奋力追求分外的东西，还自以为泰然无危。跟外物顺应相通的人，外物必将归依于他；跟外物相互阻遏的人，他们自身都不能相容，又怎么能容纳他人！不能容人的人没有亲近，没有亲近的人也就为人们所弃绝。兵器没有什么能对人的心神作出伤害，从这一意义说良剑莫邪也只能算是下等；寇敌没有什么比阴阳的变异更为巨大，因为任何人也没有办法逃脱出天地之间。其实并非阴阳的变异伤害他人，而是人们心神自扰不能顺应阴阳的变化而使自身受到伤害。
大道通达于万物。一种事物分离了新的事物就形成了，新的事物形成了原有的事物便毁灭了。对于分离厌恶的原因，就在于对分离求取完备；对于完备厌恶的原因，又在于对完备进一步求取完备。所以心神离散外逐欲情而不能返归，就会徒具形骸而显于鬼形；心神离散外逐欲情而能有所得，这就叫做接近于死亡。迷灭本性而徒有外形，也就跟鬼一个样。把有形的东西看作是无形，那么内心就会得到安宁。
产生没有根本，消逝没有踪迹。具有实在的形体却看不见确切的处所，有成长却见不到成长的始末，有所产生却没有产生的孔窍的情况又实际存在着。具有实在的形体而看不见确切的处所的，是因为处在四方上下没有边际的空间中。有成长却见不到成长的始末，是因为处在古往今来没有极限的时间里。存在着生，存在着死，存在着出，存在着入，入与出都没有具体的形迹，这就叫做自然之门。所谓自然之门，就是不存在一个人为的门，万事万物都出自这一自然之门。“有”不可能用“有”来产生“有”，必定要出自“无有”，而“无有”就是一切全都没有。圣人就藏身于这样的境域。
古时候的人，他们的才智达到很高的境界。什么样的境界呢？有认为宇宙初始是不曾有物的，这种观点是最高明的，最完美的了，不可以再添加什么了。次一等认为宇宙初始已经存在事物，他们把产生看作是另一种事物的失落，他们把消逝看作是返归自然，而这样的观点已经对事物有了区分。再次一等认为宇宙初始确实不曾有过什么，不久就产出了生物，有生命的东西又很快地死去；他们把虚空看作是头，把生命看作躯体，把死亡看作是尾脊。谁能懂得有、无、死、生归结为一体，我就跟他交上朋友。以上三种认识虽然各有不同，但从万物一体的观点看却并没有什么差异，犹如楚国王族中昭、景二姓，以世代为官而著显，屈姓，又以世代封赏而著显，只不过是姓氏不同罢了。
世上存在生命，乃是从昏暗中产生出来，生命一旦产生彼与此、是与非就在不停地转移而不易分辨。让我来谈谈转移和分辨，其实这本不足以谈论。虽然如此，即使谈论了也是不可以明瞭的。譬如说，年终时大祭备有牛牲的内脏和四肢，可以分别陈列却又不可以离散整体牛牲；又譬如说，游观王室的人周旋于整个宗庙，但同时又必须上厕所。像这些例子全都说明彼与此、是与非在不停地转移。请让我再进一步谈谈是非的转移和不定。这全是因为把生存看作根本，把才智看作老师。于是以这样的观点来驾驭是与非，便果真分辨出次要、主要的区别；于是把自我看作是主体，并且让人把这一点当作神圣的节操，于是又用死来殉偿这一节操。像这样的人，以举用为才智，以晦迹为愚昧，以通达为荣耀，以困厄为羞耻。是非、彼此的不定，是现今人们的认识，这就跟蜩与学鸠共同讥笑大鹏那样，乃是同样的无知。
踩了路上行人的脚，就要道歉说不小心，兄长踩了弟弟的脚就要怜惜抚慰，父母踩了子女的脚也就算了。因此说，最好的礼仪就是不分彼此视人如己，最好的道义就是不分物我各得其宜，最高的智慧就是无须谋虑，最大的仁爱就是对任何人也不表示亲近，最大的诚信就是无须用贵重的东西作为凭证。
毁除意志的干扰，解脱心灵的束缚，遗弃道德的牵累，打通大道的阻碍。高贵、富有、尊显、威严、声名、利禄六种情况，全是扰乱意志的因素。容貌、举止、美色、辞理、气调、情意六种情况，全是束缚心灵的因素。憎恶、欲念、欣喜、愤怒、悲哀、欢乐六种情况，全部牵累道德的因素。离去、靠拢、贪取、施与、智虑、技能六种情况，全是堵塞大道的因素。这四个方面各六种情况不至于震荡胸中，内心就会平正，内心平正就会宁静，宁静就会明澈，明澈就会虚空，虚空就能恬适顺应无所作为而又无所不为。大道，是自然的敬仰；生命，是盛德的光华；禀性，是生命的本根。合乎本性的行动，称之为率真的作为；受伪情驱使而行动，称之为失却本性。知识，出自与外物的应接；智慧，出自内心的谋划；具有智慧的人也会有不了解的知识，就像斜着眼睛看，所见必定有限。有所举动却出于不得已叫做德，有所举动却不是为了自我叫做治，追求名声必定适得其反，而讲求实际就会事事顺应。
羿精于射中微细之物而拙于人们不称誉自己。圣人精于顺应自然而拙于人为。精于顺应自然而又善于周旋人世，只有“全人”能够这样。唯独只有虫豸能够像虫豸一样地生活，唯独只有虫豸能够禀赋于自然。“全人”厌恶自然，是厌恶人为的自然，更何况用自我的尺度来看待自然和人为呢！
一只小雀迎着羿飞来，羿一定会射中它，这是羿的威力；把整个天下当作雀笼，那么鸟雀没有一只能够逃脱。因此商汤用庖厨来笼络伊尹，秦穆公用五张羊皮来笼络百里奚。所以说，不用其所好来笼络人心而可以成功的，从不曾有过。
砍断了脚的人不图修饰，因为已把毁誉置之度外；服役的囚徒登上高处不存恐惧，因为已经忘掉了死生。对于谦卑的言语不愿作出回报而忘掉了他人，能够忘掉他人的人，就可称作合于自然之理又忘却人道之情的“天人”。所以，敬重他却不感到欣喜，侮辱他却不会愤怒的人，只有混同于自然顺和之气的人才能够这样。发出了怒气但不是有心发怒，那么怒气也就出于不怒；有所作为但不是有心作为，那么作为也就出于无心作为。想要宁静就得平和气息，想要寂神就得顺应心志，即使有所作为也须处置适宜，事事顺应于不得已。事事不得已的作法，也就是圣人之道。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1de2cee9a0c24edae4d", "shortContent": "这篇《〈吊魏武帝文〉序》是陆机在西晋惠帝元康八年（298）由尚书郎升为著作郎，掌管国史时写的。因为看到档案材料中有曹操的《遗令》（《曹操集》原来未收，靠陆机这篇文章而保存下来），感慨万分，写了这篇悼念性的文章。这是文章的序。\n全序分四段。第一段简单叙述文章的缘起，怎么见到《遗令》的，见到后自己的感伤，这是为了引起下文。虽然短短几句，已为全文定了基调。\n第二段借客人的非议来引出后面自己的议论。客人三...", "authors": ["周本淳"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa2911759740c9ca3a5", "shortContent": "本篇写叔父溺爱其侄，知养而不知教，自知有过，自椎而死的故事。前后二件事，予以对照，一贬一褒，也是志怪小说类的“春秋笔法”。张三辰抚养亡兄之子如同亲生，帮助其侄理田产，谋婚娶，竭尽心力；其侄患痨病，又是请医求药，废寝食，关怀备至；其侄不治而死，又常精神恍惚如失亲子。左邻右舍无不称其兄弟友爱。可谓仁至义尽，谁能指责张三辰有过呢？然而，在封建的伦理道德观念中，认为长辈不仅知养更应重知教，张三辰未能教化其...", "authors": ["李晓"], "pressName": "上海辞书出版社"}]', '', 'indent', 1524912346, '5ae3e055ee920a00430a1c8b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637418, '庄子 · 杂篇 · 徐无鬼', NULL, 20, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E6%9D%82%E7%AF%87%C2%B7%E5%BE%90%E6%97%A0%E9%AC%BC/10172826?fr=aladdin', '', '徐无鬼因女商见魏武侯，武侯劳之曰：“先生病矣，苦于山林之劳，故乃肯见于寡人。”徐无鬼曰：“我则劳于君，君有何劳于我！君将盈耆欲，长好恶，则性命之情病矣；君将黜耆欲，牵好恶，则耳目病矣。我将劳君，君有何劳于我！”武侯超然不对。少焉，徐无鬼曰：“尝语君吾相狗也：下之质，执饱而止，是狸德也；中之质，若视日；上之质，若亡其一。吾相狗又不若吾相马也。吾相马：直者中绳，曲者中钩，方者中矩，圆者中规。是国马也，而未若天下马也。天下马有成材，若恤若失，若丧其一。若是者，超轶绝尘，不知其所。”武侯大悦而笑。徐无鬼出，女商曰：“先生独何以说吾君乎？吾所以说吾君者，横说之则以《诗》、《书》、《礼》、《乐》，从说则以《金板》、《六韬》，奉事而大有功者不可为数，而吾君未尝启齿。今先生何以说吾君？使吾君说若此乎？”徐无鬼曰：“吾直告之吾相狗马耳。”女商曰：“若是乎？”曰：“子不闻夫越之流人乎？去国数日，见其所知而喜；去国旬月，见所尝见于国中者喜；及期年也，见似人者而喜矣。不亦去人滋久，思人滋深乎？夫逃虚空者，藜藋柱乎鼪鼬之径，踉位其空，闻人足音跫然而喜矣，又况乎昆弟亲戚之謦欬其侧者乎！久矣夫，莫以真人之言謦欬吾君之侧乎！”
徐无鬼见武侯，武侯曰：“先生居山林，食芧栗，厌葱韭，以宾寡人，久矣夫！今老邪？其欲干酒肉之味邪？其寡人亦有社稷之福邪？”徐无鬼曰：“无鬼生于贫贱，未尝敢饮食君之酒肉，将来劳君也。”君曰：“何哉！奚劳寡人？”曰：“劳君之神与形。”武侯曰：“何谓邪？”徐无鬼曰：“天地之养也一，登高不可以为长，居下不可以为短。君独为万乘之主，以苦一国之民，以养耳目鼻口，夫神者不自许也。夫神者，好和而恶奸。夫奸，病也，故劳之。唯君所病之何也？”武侯曰：“欲见先生久矣！吾欲爱民而为义偃兵，其可乎？”徐无鬼曰：“不可。爱民，害民之始也；为义偃兵，造兵之本也。君自此为之，则殆不成。凡成美，恶器也。君虽为仁义，几且伪哉！形固造形，成固有伐，变固外战。君亦必无盛鹤列于丽谯之间，无徒骥于锱坛之宫，无藏逆于得，无以巧胜人，无以谋胜人，无以战胜人。夫杀人之士民，兼人之土地，以养吾私与吾神者，其战不知孰善？胜之恶乎在？君若勿已矣！修胸中之诚以应天地之情而勿撄。夫民死已脱矣，君将恶乎用夫偃兵哉！
黄帝将见大隗乎具茨之山，方明为御，昌寓骖乘，张若、囗（左“言”右“习”）朋前马，昆阍、滑稽后车。至于襄城之野，七圣皆迷，无所问涂。适遇牧马童子，问涂焉，曰：“若知具茨之山乎？”曰：“然。”“若知大隗之所存乎？”曰：“然。”黄帝曰：“异哉小童！非徒知具茨之山，又知大隗之所存。请问为天下。”小童曰：“夫为天下者，亦若此而已矣，又奚事焉！予少而自游于六合之内，予适有瞀病，有长者教予曰：‘若乘日之车而游于襄城之野。’今予病少痊，予又且复游于六合之外。夫为天下亦若此而已。予又奚事焉！”黄帝曰：“夫为天下者，则诚非吾子之事，虽然，请问为天下。”小童辞。黄帝又问。小童曰：“夫为天下者，亦奚以异乎牧马者哉！亦去其害马者而已矣！”黄帝再拜稽首，称天师而退。
知士无思虑之变则不乐；辩士无谈说之序则不乐；察士无凌谇之事则不乐：皆囿于物者也。招世之士兴朝；中民之士荣官；筋国之士矜雅；勇敢之士奋患；兵革之士乐战；枯槁之士宿名；法律之士广治；礼乐之士敬容；仁义之士贵际。农夫无草莱之事则不比；商贾无市井之事则不比；庶人有旦暮之业则劝；百工有器械之巧则壮。钱财不积则贪者忧，权势不尤则夸者悲，势物之徒乐变。遭时有所用，不能无为也，此皆顺比于岁，不物于易者也。驰其形性，潜之万物，终身不反，悲夫！
庄子曰：“射者非前期而中谓之善射，天下皆羿也，可乎？”惠子曰：“可。”庄子曰：“天下非有公是也，而各是其所是，天下皆尧也，可乎？”惠子曰：“可。”庄子曰：“然则儒墨杨秉四，与夫子为五，果孰是邪？或者若鲁遽者邪？其弟子曰：‘我得夫子之道矣！吾能冬爨鼎而夏造冰矣！’鲁遽曰：‘是直以阳召阳，以阴召阴，非吾所谓道也。吾示子乎吾道。’于是乎为之调瑟，废一于堂，废一于室，鼓宫宫动，鼓角角动，音律同矣！夫或改调一弦，于五音无当也，鼓之，二十五弦皆动，未始异于声而音之君已！且若是者邪！”惠子曰∶“今乎儒墨杨秉，且方与我以辩，相拂以辞，相镇以声，而未始吾非也，则奚若矣？”庄子曰：“齐人蹢子于宋者，其命阍也不以完；其求銒钟也以束缚；其求唐子也而未始出域：有遗类矣！夫楚人寄而銒阍者；夜半于无人之时而与舟人斗，未始离于岑而足以造于怨也。”
庄子送葬，过惠子之墓，顾谓从者曰：“郢人垩慢其鼻端若蝇翼，使匠人斫之。匠石运斤成风，听而斫之，尽垩而鼻不伤，郢人立不失容。宋元君闻之，召匠石曰：‘尝试为寡人为之。’匠石曰：‘臣则尝能斫之。虽然，臣之质死久矣！’自夫子之死也，吾无以为质矣，吾无与言之矣！”
管仲有病，桓公问之曰：“仲父之病病矣，可不讳云，至于大病，则寡人恶乎属国而可？”管仲曰：“公谁欲与？”公曰：“鲍叔牙。”曰：“不可。其为人洁廉，善士也；其于不己若者不比之；又一闻人之过，终身不忘。使之治国，上且钩乎君，下且逆乎民。其得罪于君也将弗久矣！”公曰：“然则孰可？”对曰：“勿已则隰朋可。其为人也，上忘而下畔，愧不若黄帝，而哀不己若者。以德分人谓之圣；以财分人谓之贤。以贤临人，未有得人者也；以贤下人，未有不得人者也。其于国有不闻也，其于家有不见也。勿已则隰朋可。”
吴王浮于江，登乎狙之山，众狙见之，恂然弃而走，逃于深蓁。有一狙焉，委蛇攫搔，见巧乎王。王射之，敏给搏捷矢。王命相者趋射之，狙执死。王顾谓其友颜不疑曰：“之狙也，伐其巧、恃其便以敖予，以至此殛也。戒之哉！嗟乎！无以汝色骄人哉？”颜不疑归而师董梧，以锄其色，去乐辞显，三年而国人称之。
南伯子綦隐几而坐，仰天而嘘。颜成子入见曰：“夫子，物之尤也。形固可使若槁骸，心固可使若死灰乎？”曰：“吾尝居山穴之中矣。当是时也，田禾一睹我而齐国之众三贺之。我必先之，彼故知之；我必卖之，彼故鬻之。若我而不有之，彼恶得而知之？若我而不卖之，彼恶得而鬻之？嗟乎！我悲人之自丧者；吾又悲夫悲人者；吾又悲夫悲人之悲者；其后而日远矣！“
仲尼之楚，楚王觞之。孙叔敖执爵而立。市南宜僚受酒而祭，曰：“古之人乎！于此言已。”曰：“丘也闻不言之言矣，未之尝言，于此乎言之：市南宜僚弄丸而两家之难解；孙叔敖甘寝秉羽而郢人投兵；丘愿有喙三尺。”彼之谓不道之道，此之谓不言之辩。故德总乎道之所一，而言休乎知之所不知，至矣。道之所一者，德不能同也。知之所不能知者，辩不能举也。名若儒墨而凶矣。故海不辞东流，大之至也。圣人并包天地，泽及天下，而不知其谁氏。是故生无爵，死无谥，实不聚，名不立，此之谓大人。狗不以善吠为良，人不以善言为贤，而况为大乎！夫为大不足以为大，而况为德乎！夫大备矣，莫若天地。然奚求焉，而大备矣！知大备者，无求，无失，无弃，不以物易己也。反己而不穷，循古而不摩，大人之诚！
子綦有八子，陈诸前，召九方甄曰：“为我相吾子，孰为祥。”九方曰：“梱也为祥。”子綦瞿然喜曰：“奚若？”曰：“梱也，将与国君同食以终其身。”子綦索然出涕曰：“吾子何为以至于是极也？”九方曰：“夫与国君同食，泽及三族，而况父母乎！今夫子闻之而泣，是御福也。子则祥矣，父则不祥。”子綦曰：“汝何足以识之。而梱祥邪？尽于酒肉，入于鼻口矣，而何足以知其所自来！吾未尝为牧而牂生于奥，未尝好田而鹑生于穾，若勿怪，何邪？吾所与吾子游者，游于天地，吾与之邀乐于天，吾与之邀食于地。吾不与之为事，不与之为谋，不与之为怪。吾与之乘天地之诚而不以物与之相撄，吾与之一委蛇而不与之为事所宜。今也然有世俗之偿焉？凡有怪征者必有怪行。殆乎！非我与吾子之罪，几天与之也！吾是以泣也。”无几何而使梱之于燕，盗得之于道，全而鬻之则难，不若刖之则易。于是乎刖而鬻之于齐，适当渠公之街，然身食肉而终。
啮缺遇许由曰：“子将奚之？”曰：“将逃尧。”曰：“奚谓邪？”曰：“夫尧畜畜然仁，吾恐其为天下笑。后世其人与人相食与！夫民不难聚也，爱之则亲，利之则至，誉之则劝，致其所恶则散。爱利出乎仁义，捐仁义者寡，利仁义者众。夫仁义之行，唯且无诚，且假乎禽贪者器。是以一人之断制天下，譬之犹一覕也。夫尧知贤人之利天下也，而不知其贼天下也。夫唯外乎贤者知之矣。”
有暖姝者，有濡需者，有卷娄者。所谓暖姝者，学一先生之言，则暖暖姝姝而私自说也，自以为足矣，而未知未始有物也。是以谓暖姝者也。濡需者，豕虱是也，择疏鬣长毛，自以为广宫大囿。奎蹄曲隈，乳间股脚，自以为安室利处。不知屠者之一旦鼓臂布草操烟火，而己与豕俱焦也。此以域进，此以域退，此其所谓濡需者也。卷娄者，舜也。羊肉不慕蚁，蚁慕羊肉，羊肉羶也。舜有羶行，百姓悦之，故三徙成都，至邓之虚而十有万家。尧闻舜之贤，举之童土之地，曰：“冀得其来之泽。”舜举乎童土之地，年齿长矣，聪明衰矣，而不得休归，所谓卷娄者也。是以神人恶众至，众至则不比，不比则不利也。故无所甚亲，无所甚疏，抱德炀和，以顺天下，此谓真人。于蚁弃知，于鱼得计，于羊弃意。以目视目，以耳听耳，以心复心。若然者，其平也绳，其变也循。古之真人！以天待之，不以人入天，古之真人！
得之也生，失之也死；得之也死，失之也生：药也。其实堇也，桔梗也，鸡癕也，豕零也，是时为帝者也，何可胜言！
句践也以甲楯三千栖于会稽，唯种也能知亡之所以存，唯种也不知其身之所以愁。故曰：鸱目有所适，鹤胫有所节，解之也悲。故曰：风之过，河也有损焉；日之过，河也有损焉；请只风与日相与守河，而河以为未始其撄也，恃源而往者也。故水之守土也审，影之守人也审，物之守物也审。故目之于明也殆，耳之于聪也殆，心之于殉也殆，凡能其于府也殆，殆之成也不给改。祸之长也兹萃，其反也缘功，其果也待久。而人以为己宝，不亦悲乎！故有亡国戮民无已，不知问是也。故足之于地也践，虽践，恃其所不蹍而后善博也；人之知也少，虽少，恃其所不知而后知天之所谓也。知大一，知大阴，知大目，知大均，知大方，知大信，知大定，至矣！大一通之，大阴解之，大目视之，大均缘之，大方体之，大信稽之，大定持之。尽有天，循有照，冥有枢，始有彼。则其解之也似不解之者，其知之也似不知之也，不知而后知之。其问之也，不可以有崖，而不可以无崖。颉滑有实，古今不代，而不可以亏，则可不谓有大扬搉乎！阖不亦问是已，奚惑然为！以不惑解惑，复于不惑，是尚大不惑。', '“徐无鬼”是开篇的人名，以人名作为篇名。全篇大体可分为十四个部分。', '', '徐无鬼靠女商的引荐得见魏武侯，武侯慰问他说：“先生一定是极度困惫了！为隐居山林的劳累所困苦，所以方才肯前来会见我。”徐无鬼说：“我是来慰问你的，你对于我有什么慰问！你想要满足嗜好和欲望，增多喜好和憎恶，那么性命攸关的心灵就会弄得疲惫不堪；你想要废弃嗜好和欲望，退却喜好和憎恶，那么耳目的享用就会困顿乏厄。我正打算来慰问你，你对于我有什么可慰问的！”武侯听了怅然若失，不能应答。
不一会儿，徐无鬼说：“请让我告诉你，我善于观察狗的体态以确定它们的优劣。下等品类的狗只求填饱肚子也就算了，这是跟野猫一样的禀性；中等品类的狗好像总是凝视上方，上等品类的狗便总像是忘掉了自身的存在。我观察狗，又不如我观察马。我观察马的体态，直的部分要合于墨线，弯的部分要合于钩弧，方的部分要合于角尺，圆的部分要合于圆规，这样的马就是国马，不过还比不上天下最好的马。天下最好的马具有天生的材质，或缓步似有忧虑或奔逸神采奕奕，总像是忘记了自身的存在，超越马群疾如狂风把尘土远远留在身后，却不知道这样高超的本领从哪里得来。”魏武侯听了高兴得笑了起来。
徐无鬼走出宫廷，女商说：“先生究竟是用什么办法使国君高兴的呢？我用来使国君高兴的办法是，从远处说向他介绍诗、书、礼、乐，从近处说向他谈论太公兵法。侍奉国君而大有功绩的人不可计数，而国君从不曾有过笑脸。如今你究竟用什么办法来取悦国君，竟使国君如此高兴呢？”徐无鬼说：“我只不过告诉他我怎么相狗、相马罢了。”女商说：“就是这样吗？”徐无鬼说：“你没有听说过越地流亡人的故事吗？离开都城几天，见到故交旧友便十分高兴；离开都城十天整月，见到在国都中所曾经见到过的人便大喜过望；等到过了一年，见到好像是同乡的人便欣喜若狂；不就是离开故人越久，思念故人的情意越深吗？逃向空旷原野的人，丛生的野草堵塞了黄鼠狼出入的路径，却能在杂草丛中的空隙里跌跌撞撞地生活，听到人的脚步声就高兴起来，更何况是兄弟亲戚在身边说笑呢？很久很久了，没有谁用真人纯朴的话语在国君身边说笑了啊！”
徐无鬼拜见魏武侯，武侯说：“先生居住在山林，吃的是橡子，满足于葱韭之类的菜蔬，而谢绝与我交往，已经很久很久了！如今是上了年岁吗？还是为了寻求酒肉之类的美味呢？抑或有什么治国的良策而造福于我的国家吗？”徐无鬼说：“我出身贫贱，不敢奢望能够享用国君的酒肉美食，只是打算来慰问你。”武侯说：“什么，怎么是慰问我呢？”徐无鬼说：“前来慰问你的精神和形体。”武侯说：“你说的是什么呀？”徐无鬼说：“天与地对于人们的养育是同样的，登上了高位不可以自以为高人一等，身处低下的地位不可以认为是矮人三分。你作为大国的国君，使全国的百姓劳累困苦，以人民的劳苦来满足眼耳口鼻的享用，而圣明的人却从不为自己求取分外的东西。圣明的人，喜欢跟外物和顺而厌恶为自己求取私利；为个人求取私利，这是一种严重的病态，所以我特地前来慰问。只有国君你患有这种病症，为什么呀？”
武侯说：“我希望见到先生已经很久了。我想爱护我的人民并为了道义而停止战争，这恐怕就可以了吧？”徐无鬼说：“不行。所谓爱护人民，实乃祸害人民的开始；为了道义而停止争战，也只是制造新的争端的祸根；你如果从这些方面来着手治理，恐怕什么也不会成功。大凡成就了美好的名声，也就有了作恶的工具；你虽然是在推行仁义，却更接近于虚伪和作假啊！有了仁义和形迹必定会出现仿造仁义的形迹，有了成功必定会自夸，有了变故也必定会再次挑起争战。你一定不要浩浩荡荡地像鹤群飞行那样布阵于丽谯楼前，不要陈列步卒骑士于锱坛的宫殿，不要包藏贪求之心于多种苟有所得的环境，不要用智巧去战胜别人，不要用谋划去打败别人，不要用战争去征服别人。杀死他人的士卒和百姓，兼并他人的土地，用来满足自己的私欲和精神的，他们之间的争战不知道究竟有谁是正确的？胜利又存在于哪里？你不如停止争战，修养心中的诚意，从而顺应自然的真情而不去扰乱其规律。百姓死亡的威胁得以摆脱，你将哪里用得着再止息争战呢！”
黄帝到具茨山去拜见大隗，方明驾驭马车，昌宇做陪乘，张若、謵朋在马前导引，昆阍、滑稽在车后跟随；来到襄城的旷野，七位圣人都迷失了方向，而且没有什么人可以问路。正巧遇上一位牧马的少年，便向牧马少年问路，说：“你知道具茨山吗？”少年回答：“是的。”又问：“你知道大隗居住在什么地方吗？”少年回答：“是的。”黄帝说：“真是奇怪啊，这位少年！不仅知道具茨山，而且知道大隗居住的地方。请问怎样治理天下。”少年说：“治理天下，也就像牧马一样罢了，又何须多事呢！我幼小时独自在天地四方内游玩，碰巧生了头眼眩晕的病，有位长者教导我说：‘你还是乘坐太阳车去襄城的旷野里游玩。’如今我的病已经有了好转，我又将到天地四方之外去游玩。至于治理天下恐怕也就像牧马一样罢了，我又何须去多事啊！”黄帝说：“治理天下，固然不是你操心的事。虽然如此，我还是要向你请教怎样治理天下。”少年听了拒绝回答。
黄帝又问。少年说：“治理天下，跟牧马哪里有什么不同呢！也就是去除过分、任其自然罢了！”黄帝听了叩头至地行了大礼，称他为天师而离去。
才智聪颖的人没有思虑上的变易与转换便不会感到快乐，善于辩论的人没有谈说的话题与机会就不会感到快乐，喜于明察的人没有对别人的冒犯与责问就不会感到快乐，这都是因为受到了外物的拘限与束缚。
招引贤才的人从朝堂上开始建功立业，善于治理百姓的人以做官为荣，身强体壮的人不把危难放在眼里，英勇无畏的人遇上祸患总是奋不顾身，手持武器身披甲胄的人乐于征战，隐居山林的人追求的是清白的名声，研修法制律令的人一心推行法治，崇尚礼教的人注重仪容，讲求仁义的人看重人际交往。农夫没有除草耕耘的事便觉内心不定无所事事，商人没有贸易买卖也会心神不安无所事事。百姓只要有短暂的工作就会勤勉，工匠只要有器械的技巧就会工效快、成效高。钱财积攒得不多贪婪的人总是忧愁不乐，权势不高不大而私欲很盛的人便会悲伤哀叹。依仗权势掠取财物的人热衷于变故，一遇时机就会有所动作，不能够做到清静无为。这样的人就像是顺应时令次第一样地取舍俯仰，不能够摆脱外物的拘累，使其身形与精神过分奔波驰骛，沉溺于外物的包围之中，一辈子也不会醒悟，实在是可悲啊！
庄子说：“射箭的人不是预先瞄准而误中靶的，称他是善于射箭，那么普天下都是羿那样善射的人，可以这样说吗？”惠子说：“可以。”庄子说：“天下本没有共同认可的正确标准，却各以自己认可的标准为正确，那么普天下都是唐尧那样圣明的人，可以这样说吗？”惠子说：“可以。”
庄子说：“那么郑缓、墨翟、杨朱、公孙龙四家，跟先生你一道便是五家，到底谁是正确的呢？或者都像是周初的鲁遽那样吗？鲁遽的弟子说：‘我学得了先生的学问，我能够在冬天生火烧饭在夏天制出冰块。’鲁遽说：‘这只不过是用具有阳气的东西来招引出具有阳气的东西，用具有阴气的东西来招引出具有阴气的东西，不是我所倡导的学问。我告诉给你我所主张的道理。’于是当着大家调整好瑟弦，放一张瑟在堂上，放一张瑟在内室，弹奏起这张瑟的宫音而那张瑟的宫音也随之应合，弹奏那张瑟的角音而这张瑟的角音也随之应合，调类相同的缘故啊。如果其中任何一根弦改了调，五个音不能合谐，弹奏起来，二十五根弦都发出震颤，然而却始终不会发出不同的声音，方才是乐音之王了。而你恐怕就是象鲁遽那样的人吧？”惠子说：“如今郑缓、墨翟、杨朱、公孙龙，他们正跟我一道辩论，相互间用言辞进行指责，相互间用声望压制对方，却从不曾认为自己是不正确的，那么将会怎么样呢？”
庄子说：“齐国有个人使自己的儿子滞留于宋国，命令守门人守住他而不让他有完整的身形返回来，他获得一只长颈的小钟唯恐破损而包了又包，捆了又捆，他寻找远离家门的儿子却不曾出过郊野，这就像辩论的各家忘掉了跟自己相类似的情况！楚国有个人寄居别人家而怒责守门人，半夜无人时走出门来又跟船家打了起来，还不曾离开岸边就又结下了怨恨。”
庄子送葬，经过惠子的墓地，回过头来对跟随的人说：“郢地有个人让白垩泥涂抹了他自己的鼻尖，像蚊蝇的翅膀那样大小，让匠石用斧子砍削掉这一小白点。匠石挥动斧子呼呼作响，漫不经心地砍削白点，鼻尖上的白泥完全除去而鼻子却一点也没有受伤，郢地的人站在那里也若无其事不失常态。宋元君知道了这件事，召见匠石说：‘你为我也这么试试’。匠石说：“我确实曾经能够砍削掉鼻尖上的小白点。虽然如此，我可以搭配的伙伴已经死去很久了。”自从惠子离开了人世，我没有可以匹敌的对手了！我没有可以与之论辩的人了！”
管仲生了病，齐桓公问他：“你老的病已经很重了，不避讳地说，一旦病危不起，我将把国事托付给谁才合适呢？”管仲说：“你想要交给谁呢？”齐桓公说：“鲍叔牙。”管仲说：“不可以。鲍叔牙为人，算得上是清白廉正的好人，他对于不如自己的人从不去亲近，而且一听到别人的过错，一辈子也忘不掉，让他治理国家，对上势必约束国君，对下势必忤逆百姓。一旦得罪于国君，也就不会长久执政了！”
齐桓公说：“那么谁可以呢？”管仲回答说：“要不，隰朋还可以。隰朋为人，对上不显示位尊而对下不分别卑微，自愧不如黄帝又能怜悯不如自己的人。能用道德去感化他人的称作圣人，能用财物去周济他人的称作贤人。以贤人自居而驾临于他人之上。不会获得人们的拥戴；以贤人之名而能谦恭待人，不会得不到人们的拥戴。他对于国事一定不会事事听闻，他对于家庭也一定不事事看顾。不得已，那么还是隰朋可以。”
吴王渡过长江。登上猕猴聚居的山岭。猴群看见吴王打猎的队伍，惊惶地四散奔逃，躲进了荆棘丛林的深处。有一个猴子留下了，它从容不迫地腾身而起抓住树枝跳来跳去，在吴王面前显示它的灵巧。吴王用箭射它，他敏捷地接过飞速射来的利箭。吴王下命令叫来左右随从打猎的人一起上前射箭，猴子躲避不及抱树而死。
吴王回身对他的朋友颜不疑说：“这只猴子夸耀它的灵巧，仗恃它的便捷而蔑视于我，以至受到这样的惩罚而死去！要以此为戒啊！唉，不要用傲气对待他人啊！”颜不疑回来后便拜贤士董梧为师用以铲除自己的傲气，弃绝淫乐辞别尊显，三年时间全国的人个个称赞他。
南伯子綦靠着几案静静地坐着，然后又仰着头缓缓地吐气。颜成子进屋来看见后说：“先生，你真是了不起的人物！人的形体固然可以使它像枯槁的骸骨，心灵难道也可以像死灰一样吗？”南伯子綦说：“我曾在山林洞穴里居住。正当这个时候，齐太公田禾曾来看望我，因而齐国的民众再三向他表示祝贺。我必定是名声在先，他所以能够知道我；我必定是名声张扬，他所以能利用我的名声。假如我不具有名声，他怎么能够知道我呢？假如我不是名声张扬于外，他又怎么能够利用我的名声呢？唉，我悲悯自我迷乱失却真性的人，我又悲悯那些悲悯别人的人，我还悲悯那些悲悯人们的悲悯者，从那以后我便一天天远离人世沉浮而达到心如死灰的境界”。
孔子去到楚国，楚王宴请孔子，孙叔敖拿着酒器站立一旁，市南宜僚把酒洒在地上祭祷，说：“古时候的人啊！在这种情况下总要说一说话。”孔子说：“我听说有不用言谈的言论，但从不曾说过，在这里说上一说。市南宜僚从容不迫地玩弄弹丸而使两家的危难得以解脱，孙叔敖运筹帷幄使敌国不敢对楚国用兵而楚国得以停止征战。我孔丘多么希望有只长长的嘴巴来说上几句呀！”
市南宜僚和孙叔敖可以称作不是办法的办法，孔子可以称作不用言辞的说辩，所以循道所得归结到一点就是道的原始浑一的状态。言语停留在才智所不知晓的境域，这就是最了不起的了。大道是混沌同一的，而体悟大道却个不相同；才智所不能通晓的知识，辩言也不能一一列举，名声像儒家、墨家那样的人也常因强不知以为知而招致凶祸。所以，大海不辞向东的流水，成就了博大之最，圣人包容天地，恩泽施及天下百姓，而百姓却不知道他们的姓名。因此生前没有爵禄，死后没有谥号，财物不曾汇聚，名声不曾树立，这才可以称作是伟大的人。狗不因为善于狂吠便是好狗，人不因为善于说话便是贤能，何况是成就于伟大的啊！成就伟大却不足以算是伟大，又何况是修养心性随顺自然啊！伟大而又完备，莫过于天地；然而天地哪里会求取什么，却是伟大而又完备的哩。伟大而又完备的人，没有追求，没有丧失，没有舍弃，不因外物而改变自己的本性。返归自己的本性就会没有穷尽，遵循恒古不变的规律就会没有矫饰，这就是伟大的人的真情。
子綦有八个儿子，排列在子綦身前，叫来九方歅说：“给我八个儿子看看相，谁最有福气。”九方歅说：“梱最有福气。”子綦惊喜地说：“怎么最有福气呢？”九方歅回答：“梱将会跟国君一道饮食而终了一生。”子綦泪流满面地说：“我的儿子为什么会达到这样的境遇！”九方歅说：“跟国君一道饮食，恩泽将施及三族，何况只是父母啊！如今先生听了这件事就泣不成声，这是拒绝要降临的福禄。你的儿子倒是有福气，你做父亲的却是没有福分了。”
子綦说：“歅，你怎么能够知道，梱确实是有福呢？享尽酒肉，只不过从口鼻进到肚腹里，又哪里知道这些东西从什么地方来？我不曾牧养而羊子却出现在我屋子的西南角，不曾喜好打猎而鹌鹑却出现在我屋子的东南角，假如不把这看作是怪事，又是为了什么呢？我和我的儿子所游乐的地方，只在于天地之间。我跟他一道在苍天里寻乐，我跟他一道在大地上求食；我不跟他建功立业，不跟他出谋划策，不跟他标新立异，我只和他一道随顺天地的实情而不因外物便相互背违，我只和他一应顺任自然而不为任何外事所左右。如今我却得到了世俗的回报啊！大凡有了怪异的征兆，必定会有怪异的行为，实在是危险啊，并不是我和我儿子的罪过，大概是上天降下的罪过！我因此泣不成声。”
没过多久派遣梱到燕国去，强盗在半道上劫持了他，想要保全其身形而卖掉实在担心他跑掉，不如截断他的脚容易卖掉些，于是截断他的脚卖到齐国，正好齐国的富人渠公买了去给自己看守街门，仍能够一辈子吃肉而终了一生。
齧缺遇见许由，说：“你准备去哪里呢？”许由回答：“打算逃避尧。”齧缺说：“你说些什么呢？”许由说：“尧，孜孜不倦地推行仁的主张，我担心他受到天下人的耻笑。后代一定会人与人相食啊！百姓，并不难以聚合，给他们爱护就会亲近，给他们好处就会靠拢，给他们奖励就会勤勉，送给他们所厌恶的东西就会离散。爱护和利益出自仁义，而弃置仁义的少，利用仁义的多。仁义的推行，只会没有诚信，而且还会被禽兽一般贪婪的人借用为工具。所以一个人的裁断与决定给天下人带来了好处，打个比方说就好像是短暂的一瞥。唐尧知道贤人能给天下人带来好处，却不知道他们对天下人的残害，而只有身处贤者之外的人才能知道这个道理。”
有沾沾自喜的人，不偷安矜持的人，有弯腰驼背、勤苦不堪的人。
所谓沾沾自喜的人，懂得了一家之言，就沾沾自喜地私下里暗自得意，自以为满足了，却不知道从未曾有过丝毫所得，所以称他为沾沾自喜的人。所谓偷安矜持的人，就像猪身上的虱子一个样，选择稀疏的鬃毛当中自以为就是广阔的宫廷与园林，后腿和蹄子间弯曲的部位，乳房和腿脚间的夹缝，就认为是安宁的居室和美好的处所，殊不知屠夫一旦挥动双臂布下柴草生起烟火，便跟随猪身一块儿烧焦。这就是依靠环境而安身，这又是因为环境而毁灭，而这也就是所说的偷安自得的人。所谓弯腰驼背、勤苦不堪的人，就是舜那样的人。羊肉不会爱慕蚂蚁，蚂蚁则喜爱羊肉，因为羊肉有羶腥味。舜有羶腥的行为，百姓都十分喜欢他，所以他多次搬迁居处都自成都邑，去到邓的废址就聚合了头十万家人。尧了解到舜的贤能，从荒芜的土地上举荐了他，说是希望他能把恩泽布施百姓。舜从荒芜的土地上被举荐出来，年岁逐渐老了，敏捷的听力和视力衰退了，还不能退回来休息，这就是所说的弯腰驼背、勤苦不堪的人。
所以超凡脱俗的神人讨厌众人跟随，众人跟随就不会亲密和睦，不亲密和睦也就不会带来好处。因此没有什么特别的亲密，没有什么格外的疏远，持守德行、温暖和气以顺应天下，这就叫做真人。就像是，蚂蚁不再追慕羶腥，鱼儿得水似的悠闲自在，羊肉也清除了羶腥的气味。
用眼睛来看视自己眼睛所应看视的东西，用耳朵来听取自己耳朵所应听取的声音，用心思来收回分外逐物的心思。像这样的人，他们内心的平静就像墨线一样正直，他们的变化总是处处顺应。古时候的真人，用顺任自然的态度来对待人事，不会用人事来干扰自然。古时候的真人，获得生存就听任生存，失掉生存就听任死亡；获得死亡就听任死亡，失掉死亡就听任生存。药物，乌头也好，桔梗也好，芡草也好，猪苓也好，这几种药更换着作为主药，怎么可以说得完呢！
勾践率领三千士兵困守于会稽，只有文种能够知道越国复国的办法，也只有文种不知道复国后将要遭受杀戮的祸害。所以说猫头鹰的眼睛只有在夜晚才适宜看视，仙鹤具有修长的双腿，截断就会感到悲哀。所以说，风儿吹过了河面河水就会有所减损，太阳照过河去河水也会有所减损。假如风与太阳总是盘桓在河的上空，而河水却认为不曾受到过干扰，那就是靠河水源头小溪的不断汇聚。所以，水保持住了泥土也就安定下来，影子留住了是因为人体安定下来，事物固守着事物因而相互安定下来。
所以，眼睛一味地追求超人的视力也就危险了，耳朵一味地追求超人的听力也就危险了，心思一味地追求外物也就危险了。才能从内心深处显露出来就会危险，危险一旦形成已经来不及悔改。灾祸滋生并逐渐地增多与聚集，返归本性却为功名所萦绕，要想获得成功便须持续很久很久。可是人们却把上述情况看作是自己最可宝贵的，不可悲吗？因此国家败亡、人民受戮从没有中断，却又不知道问一问造成这种情况的原因。
所以，脚对于地的践踏很小很小，虽然很小，仰赖所不曾践踏的地方而后才可以去到更为博大、旷远的地方；人对于各种事物的了解也很少很少，虽然很少，仰赖所不知道的知识而后才能够知道自然所称述的道理。知道“天”，知道“地”，知道“大目”，知道“大均”，知道“大方”，知道“大信”，知道“大定”，这就达到了认识的极限。“天”加以贯通，“地”加以化解，万物各视其所见，顺其本性令其自得，各得其宜自成轨迹，各守其实无使超逸，顺任安定持守不渝。
万物之中全都有其自然，顺应就会逐渐明朗清晰，深奥的道理之中都存在着枢要，而任何事物产生的同时又必然出现相应的对立面。那么，自然的理解好像是没有理解似的，自然的知晓好像是没有知晓，但这“不知”之后方才会有真知。深入一步问一问，本不可能有什么界限，然而又不可以没有什么界限。万物虽然纷扰杂乱却有它的根本，古今不能相互替换，但是无古无今、无今无古谁也不能缺少，这能不说是仅只显露其概略吗！何不再深入一步探问这博大玄妙的道理，为什么会迷惑成这个样呢？用不迷惑去解除迷惑，再回到不迷惑，这恐怕还是当初的不迷惑。', NULL, '', 'indent', 1524912518, '5ae3e0fea22b9d0044082886', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637419, '庄子 · 杂篇 · 则阳', NULL, 0, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E6%9D%82%E7%AF%87%C2%B7%E5%88%99%E9%98%B3/10157733?fr=aladdin', '', '则阳游于楚，夷节言之于王，王未之见。夷节归。彭阳见王果曰：“夫子何不谭我于王？”王果曰：“我不若公阅休。”彭阳曰：“公阅休奚为者邪？”曰：“冬则戳鳖于江，夏则休乎山樊。有过而问者，曰：‘此予宅也。’夫夷节已不能，而况我乎！吾又不若夷节。夫夷节之为人也，无德而有知，不自许，以之神其交，固颠冥乎富贵之地。非相助以德，相助消也。夫冻者假衣于春，者反冬乎冷风。夫楚王之为人也，形尊而严。其于罪也，无赦如虎。非夫佞人正德，其孰能桡焉。故圣人其穷也，使家人忘其贫；其达也，使王公忘爵禄而化卑；其于物也，与之为娱矣；其于人也，乐物之通而保己焉。故或不言而饮人以和，与人并立而使人化，父子之宜。彼其乎归居，而一闲其所施。其于人心者，若是其远也。故曰‘待公阅休’。”
圣人达绸缪，周尽一体矣，而不知其然，性也。复命摇作而以天为师，人则从而命之也。忧乎知，而所行恒无几时，其有止也，若之何！生而美者，人与之鉴，不告则不知其美于人也。若知之，若不知之，若闻之，若不闻之，其可喜也终无已，人之好之亦无已，性也。圣人之爱人也，人与之名，不告则不知其爱人也。若知之，若不知之，若闻之，若不闻之，其爱人也终无已，人之安之亦无已，性也。
旧国旧都，望之畅然。虽使丘陵草木之缗入之者十九，犹之畅然，况见见闻闻者也，以十仞之台县众间者也。
冉相氏得其环中以随成，与物无终无始，无几无时。日与物化者，一不化者也。阖尝舍之！夫师天而不得师天，与物皆殉。其以为事也，若之何！夫圣人未始有天，未始有人，未始有始，未始有物，与世偕行而不替，所行之备而不洫，其合之也，若之何！汤得其司御，门尹登恒为之傅之。从师而不囿，得其随成，为之司其名之名。嬴法得其两见。仲尼之尽虑，为之傅之。容成氏曰：“除日无岁，无内无外。”
魏莹与田侯牟约，田侯牟背之，魏莹怒，将使人刺之。犀首公孙衍闻而耻之，曰：“君为万乘之君也，而以匹夫从仇。衍请受甲二十万，为君攻之，虏其人民，系其牛马，使其君内热发于背，然后拨其国。忌也出走，然后抶其背，折其脊。”季子闻而耻之，曰：“筑十仞之城，城者既十仞矣，则又坏之，此胥靡之所苦也。今兵不起七年矣，此王之基也。衍，乱人也，不可听也。”华子闻而丑之，曰：“善言伐齐者，乱人也；善言勿伐者，亦乱人也；谓‘伐之与不伐乱人也’者，又乱人也。”君曰：“然则若何？”曰：“君求其道而已矣。”
惠之闻之，而见戴晋人。戴晋人曰：“有所谓蜗者，君知之乎？”曰：“然。”“有国于蜗之左角者，曰触氏；有国于蜗之右角者，曰蛮氏。时相与争地而战，伏尸数万，逐北旬有五日而后反。”君曰：“噫！其虚言与？”曰：“臣请为君实之。君以意在四方上下有穷乎？”君曰：“无穷。”曰：“知游心于无穷，而反在通达之国，若存若亡乎？”君曰：“然。”曰：“通达之中有魏，于魏中有梁，于梁中有王，王与蛮氏有辩乎？”君曰：“无辩。”客出而君惝然若有亡也。客出，惠子见。君曰：“客，大人也，圣人不足以当之。”惠子曰：“夫吹管也，犹有也；吹剑首者，而已矣。尧、舜，人之所誉也。道尧、舜于戴晋人之前，譬犹一也。”
孔子之楚，舍于蚁丘之浆。其邻有夫妻臣妾登极者，子路曰：“是何为者邪？”仲尼曰：“是圣人仆也。是自埋于民，自藏于畔。其声销，其志无穷，其口虽言，其心未尝言。方且与世违，而心不屑与之俱。是陆沉者也，是其市南宜僚邪？”子路请往召之。孔子曰：“已矣！彼知丘之着于己也，知丘之适楚也，以丘为必使楚王之召己也。彼且以丘为佞人也。夫若然者，其于佞人也，羞闻其言，而况亲见其身乎！而何以为存！”子路往视之，其室虚矣。
长梧封人问子牢曰：“君为政焉勿卤莽，治民焉勿灭裂。昔予为禾，耕而卤莽之，则其实亦卤莽而报予；芸而灭裂之，其实亦灭裂而报予。予来年变齐，深其耕而熟之，其禾蘩以滋，予终年厌飧。”庄子闻之曰：“今人之治其形，理其心，多有似封人之所谓：遁其天，离其性，灭其情，亡其神，以众为。故卤莽其性者，欲恶之孽为性，萑苇蒹始萌，以扶吾形，寻擢吾性。并溃漏发，不择所出，漂疽疥痈，内热溲膏是也。”
柏榘学于老聃，曰：“请之天下游。”老聃曰：“已矣！天下犹是也。”又请之，老聃曰：“汝将何始？”曰：“始于齐。”至齐，见辜人焉，推而强之，解朝服而幕之，号天而哭之，曰：“子乎！子乎！天下有大灾，子独先离之。曰‘莫为盗，莫为杀人’。荣辱立然后睹所病，货财聚然后睹所争。今立人之所病，聚人之所争，穷困人之身，使无休时。欲无至此得乎？古之君人者，以得为在民，以失为在己；以正为在民，以枉为在己。故一形有失其形者，退而自责。今则不然，匿为物而愚不识，大为难而罪不敢，重为任而罚不胜，远其涂而诛不至。民知力竭，则以伪继之。日出多伪，士民安取不伪。夫力不足则伪，知不足则欺，财不足则盗。盗窃之行，于谁责而可乎？”
蘧伯玉行年六十而六十化，未尝不始于是之，而卒诎之以非也。未知今之所谓是之非五十九非也。万物有乎生而莫见其根，有乎出而莫见其门。人皆尊其知之所知，而莫知恃其知之所不知而后知，可不谓大疑乎！已乎！已乎！且无所逃。此所谓然与然乎！
仲尼问于大史大、伯常骞、韦曰：“夫卫灵公饮酒湛乐，不听国家之政；田猎毕弋，不应诸侯之际：其所以为灵公者何邪？”大曰：“是因是也。”伯常骞曰：“夫灵公有妻三人，同滥而浴。史鳅奉御而进所，搏币而扶翼。其慢若彼之甚也，见贤人若此其肃也，是其所以为灵公也。”韦曰：“夫灵公也，死，卜葬于故墓，不吉；卜葬于沙丘而吉。掘之数仞，得石椁焉，洗而视之，有铭焉，曰：‘不冯其子，灵公夺而里之。’夫灵公之为灵也久矣！之二人何足以识之。”
少知问于大公调曰：“何谓丘里之言？”大公调曰：“丘里者，合十姓百名而为风俗也，合异以为同，散同以为异。今指马之百体而不得马，而马系于前者，立其百体而谓之马也。是故丘山积卑而为高，江河合水而为大，大人合并而为公。是以自外入者，有主而不执；由中出者，有正而不距。四时殊气，天不赐，故岁成；五官殊职，君不私，故国治；文武殊材，大人不赐，故德备；万物殊理，道不私，故无名。无名故无为，无为而无不为。时有终始，世有变化，祸福淳淳，至有所拂者而有所宜，自殉殊面；有所正者有所差，比于大泽，百材皆度；观于大山，木石同坛。此之谓丘里之言。”
少知曰：“然则谓之道足乎？”大公调曰：“不然，今计物之数，不止于万，而期曰万物者，以数之多者号而读之也。是故天地者，形之大者也；阴阳者，气之大者也；道者为之公。因其大以号而读之则可也，已有之矣，乃将得比哉！则若以斯辩，譬犹狗马，其不及远矣。”少知曰：“四方之内，六合之里，万物之所生恶起？”大公调曰：“阴阳相照相盖相治，四时相代相生相杀。欲恶去就，于是挢起。雌雄片合，于是庸有。安危相易，祸福相生，缓急相摩，聚散以成。此名实之可纪，精之可志也。随序之相理，挢运之相使，穷则反，终则始，此物之所有。言之所尽，知之所至，极物而已。睹道之人，不随其所废，不原其所起，此议之所止。”少知曰：“季真之莫为，接子之或使。二家之议，孰正于其情，孰偏于其理？”大公调曰：“鸡鸣狗吠，是人之所知。虽有大知，不能以言读其所自化，又不能以意其所将为。斯而析之，精至于无伦，大至于不可围。或之使，莫之为，未免于物而终以为过。或使则实，莫为则虚。有名有实，是物之居；无名无实，在物之虚。可言可意，言而愈疏。未生不可忌，已死不可阻。死生非远也，理不可睹。或之使，莫之为，疑之所假。吾观之本，其往无穷；吾求之末，其来无止。无穷无止，言之无也，与物同理。或使莫为，言之本也。与物终始。道不可有，有不可无。道之为名，所假而行。或使莫为，在物一曲，夫胡为于大方！言而足，则终日言而尽道；言而不足，则终日言而尽物。道，物之极，言默不足以载。非言非默，议有所极。”', '“则阳”是篇首的人名。本篇内容仍很庞杂，全篇大体可以分成两大部分，前一部分写了头十个小故事，用人物的对话来说明恬淡、清虚、顺任的旨趣和生活态度，同时也对滞留人事、迷恋权势的人给予抨击。后一部分则讨论宇宙万物的基本规律，讨论宇宙的起源，讨论对外在事物的主体认识。', '', '则阳周游到楚国，夷节向楚王谈到则阳，楚王没有接见他，夷节只得作罢归家。则阳见到王果，说：“先生怎么不在楚王面前谈谈我呢？”王果说：“我不如公阅休。”
则阳问：“公阅休是干什么的人呢？”王果说：“他冬天到江河里刺鳖，夏天到山脚下憩息。有人经过而问他，他就说：‘这就是我的住宅。’夷节尚且不能做到，何况是我呢？我又比不上夷节。夷节的为人，缺少德行却有世俗人的智巧，不能约束自己做到清虚恬淡，用他特有的办法巧妙地跟人交游与结识，在富有和尊显的圈子里弄得神情颠狂内心迷乱，不是用德行去相助他人，而是使德行有所毁损。受冻的人盼着温暖的春天，中暑的人刚好相反得求助冷风带来凉爽。楚王的为人，外表高贵而又威严；他对于有过错的人，像老虎一样不会给予一点宽恕；不是极有才辩的人而又端正德行，谁能够使他折服！
“所以圣人，他们潜身世外能使家人忘却生活的清苦，他们身世显赫能使王公贵族忘却爵禄而变得谦卑起来。他们对于外物，与之和谐欢娱；他们对于别人，乐于沟通、混迹人世而又能保持自己的真性；有时候一句话不说也能用中和之道给人以满足，跟人在一块儿就能使人受到感化。父亲和儿子都各得其宜，各自安于自己的地位，而圣人却完全是清虚无为地对待周围所有的人。圣人的想法跟一般人的心思，相比起来差距是那么远。所以说，要使楚王信服还得期待公阅休哩。”
圣人通达于人世间的各种纷扰和纠葛，周遍而又透彻地了解万物混同一体的状态，却并不知道为什么会是这样，这是出于自然的本性。为回返真性而又有所动作也总是把师法自然作为榜样，人们随后方才称呼他为圣人。忧心于智巧与谋虑因而行动常常不宜持久，时而有所中止又将能怎样样呢！
生来就漂亮的人，是因为别人给他作了一面镜子，如果不通过比较他也不会知道自己比别人漂亮。好像知道，又好像不知道，好像听见了，又好像没有听见，他内心的喜悦就不会有所终止，人们对他的好感也不会有所中止，这就是出于自然的本性。圣人抚爱众人，是因为人们给予了他相应的名字，如果人们不这样称誉他圣人也不知道自己怜爱他人。好像知道，又好像不知道，好像听见了，又好像没有听见，他给予人们的爱就不会有所终止，人们安于这样的抚爱也不会有所终止，这就是出于自然的本性。
祖国与家乡，一看到她就分外喜悦；即使是丘陵草木使她显得面目不清，甚至掩没了十之八九，心里还是十分欣喜。更何况亲身见闻到她的真面目、真情况，就像是数丈高台高悬于众人的面前让人崇敬、仰慕啊！
冉相氏体察了道的精髓因而能听任外物自然发展，跟外物接触相处没有终始，也显不出时日。天天随外物而变化，而其凝寂虚空的心境却一点也不会改变，何尝舍弃过大道的精髓！有心去效法自然却得不到效法自然的结果，跟外物一道相追逐，对于所修的事业又能够怎么样呢？圣人心目中从不曾有过天，从不曾有过人，从不曾有过开始，从不曾有过外物，跟随世道一块儿发展变化而没有废止，有所行动也是那么完备因而不会受到迷惑，他与外物的契合与融洽又将是怎么样的呢！商汤启用他的司御门尹登恒做他的师傅，而他随从师傅学习却从不拘泥于所学；能够随顺而成，为此而察其名迹；对待这样的名迹又无心寻其常法，因而君臣、师徒能各得其所、各安其分。仲尼最后弃绝了谋虑，因此对自然才有所辅助。容成氏说：“摒除了日就不会累积成年，忘掉了自己就能忘掉周围的事物。”
魏惠王与齐威王订立盟约，而齐威王违背了盟约。魏王大怒，打算派人刺杀齐威王，将军公孙衍知道后认为可耻，说：“您是大国的国君，却用普通百姓的手段去报仇！我愿统带二十万部队，替你攻打齐国，俘获齐国的百姓，牵走他们的牛马，使齐国的国君心急如焚热毒发于背心。然后我就攻占齐国的土地。齐国的大将田忌望风逃跑，于是我再鞭打他的背，折断他的脊骨。”
季子知道后又认为公孙衍的做法可耻，说：“建筑七八丈高的城墙，筑城已经七八丈高了，接着又把它毁掉，这是役使之人所苦的事。如今战争不起已经七年了，这是你王业的基础。公孙衍实在是挑起祸乱的人，不可听从他的主张。”
华子知道以后又鄙夷公孙衍和季子的做法，说：“极力主张讨伐齐国的人，是拨弄祸乱的人；极力劝说不要讨伐齐国的人，也是拨弄祸乱的人；评说讨伐齐国还是不讨伐齐国为拨弄祸乱之人的人，他本身就是拨弄祸乱的人。”魏王说：“既然如此，那将怎么办呢？”华子说：“你还是求助于清虚淡漠、物我兼忘的大道罢！”
惠子知道了，引见戴晋人。戴晋人对魏王说：“有叫蜗牛的小动物，国君知道吗？”魏王说：“知道。”戴晋人说：“有个国家在蜗牛的左角，名字叫触氏，有个国家在蜗牛的右角，名字叫蛮氏，正相互为争夺土地而打仗，倒下的尸体数也数不清，追赶打败的一方花去整整十五天方才撤兵而回。”魏王说：“咦，那都是虚妄的言论吧？”戴晋人说：“让我为你证实这些话。你认为四方与上下有尽头吗？”魏王说“没有止境。”戴晋人说：“知道使自己的思想在无穷的境域里遨游，却又返身于人迹所至的狭小的生活范围，这狭小的生活范围处在无穷的境域里恐怕就像是若存若失一样吧？”魏王说：“是的。”戴晋人又说：“在这人迹所至的狭小范围内有一个魏国，在魏国中有一个大梁城，在大梁城里有你魏王。大王与那蛮氏相比，有区别吗？”魏王回答说：“没有。”戴晋人辞别而去，魏王心中不畅怅然若有所失。
戴晋人离开后惠子见魏惠王，魏王说：“戴晋人，真是个了不起的人，圣人不足以和他相提并论。”惠子说：“吹起竹管，就会有嘟嘟的响声；吹着剑首的环孔，只会有丝丝的声音罢了。尧与舜，都是人们所赞誉的圣人；在戴晋人面前称赞尧与舜，就好比那微弱的丝丝之声罢了。”
孔子到楚国去，寄宿在蚁丘的卖浆人家。卖浆人家的邻居夫妻奴仆全都登上了屋顶观看孔子的车骑，子路说：“这么多人聚集在一起是干什么呢？”孔子说：“这些人都是圣人的仆从。这个圣哲之人把自己隐藏在百姓之中，藏身于田园生活里。他的声音从世上消失了，他的志向却是伟大的，他嘴里虽然在说着话，心理却好像不曾说过什么，处处与世俗相违背而且心理总不屑与世俗为伍。这是隐遁于世俗中的隐士，这个人恐怕就是楚国的市南宜僚吧？”
子路请求前去召见他。孔子说：“算了吧！他知道我对他十分了解，又知道我到了楚国，认为我必定会让楚王来召见他，他将把我看成是巧言献媚的人。如果真是这样，他对于巧言献媚的人一定会羞于听其言谈，更何况是亲自见到其人呢！你凭什么认为他还会留在那里呢？”子路前往探视，市南宜僚的居室已经空无一人了。
长梧地方守护封疆的人对子牢说：“你处理政事不要太粗疏，治理百姓不要太草率。从前我种庄稼，耕地粗疏马虎，而庄稼收获时也就用粗疏马虎的态度来报复我；锄草也轻率马虎，而庄稼收获时也用轻率马虎的态度来报复我。我来年改变了原有的方式，深深地耕地细细地平整，禾苗繁茂果实累累，我一年到头不愁食品不足。”
庄子听了后说：“如今人们治理自己的身形，调理自己的心思，许多都像这守护封疆的人所说的情况，逃避自然，背离天性，泯灭真情，丧失精神，这都因为粗疏卤莽所致。所以对待本性和真情粗疏卤莽的人，欲念与邪恶的祸根，就像萑苇、蒹葭蔽遮禾黍那样危害人的本性，开始时似乎还可以用来扶助人的形体，逐渐地就拔除了自己的本性，就像遍体毒疮一齐溃发，不知选择什么地方泄出，毒疮流浓，内热遗精就是这样。”
柏矩就学于老聃，说：“请求老师同意我到天下去游历。”老聃说：“算了，天下就像这里一样。”柏矩再次请求，老聃说：“你打算先去哪里？”柏矩说：“先从齐国开始。”柏矩到了齐国，见到一个处以死刑而抛尸示众的人，推推尸体把他摆正，再解下朝服覆盖在尸体上，仰天号陶大哭地诉说：“你呀你呀！天下出现如此大的灾祸，偏偏你先碰上了。人们常说不要做强盗，不要杀人！世间一旦有了荣辱的区别，然后各种弊端就显示出来；财货日渐聚积，然后各种争斗也就表露出来。如今树立人们所厌恶的弊端，聚积人们所争夺的财物，贫穷困厄的人疲于奔命便没有休止之时，想要不出现这样的遭遇，怎么可能呢？
“古时候统治百姓的人，把社会清平归于百姓，把管理不善归于自己；把正确的做法归于百姓，把各种过错归于自己；所以只要有一个人其身形受到损害，便私下总是责备自己。如今却不是这样。隐匿事物的真情却责备人们不能了解，扩大办事的困难却归罪于不敢克服困难，加重承受的负担却处罚别人不能胜任，把路途安排得十分遥远却谴责人们不能达到。人民耗尽了智慧和力量，就用虚假来继续应付，天天出现那么多虚假的事情，百姓怎么会不弄虚作假！力量不够便作假，智巧不足就欺诈，财力不济便行盗。盗窃的行径，对谁加以责备才合理呢？”
蘧伯玉活了六十岁而六十年来随年变化与日俱新，何尝不是年初时认为是对的而年终时又转过来认为是错的，不知道现今所认为是对的又不是五十九岁时认为是错的。万物有其产生却看不见它的本根，有其出现却寻不见它的门径。人人都尊崇自己的才智所了解的知识，却不懂得凭借自己才智所不知道而后知道的知识，这能不算是最大的疑惑吗？算了吧算了吧！没有什么办法可以逃避这样的情况。这就是所谓对吗，真正的对吗？
孔子向太史大弢、伯常骞、狶韦请教：“卫灵公饮酒作乐荒淫无度，不愿处理国家政务；经常出外张网打猎射杀飞鸟，又不参与诸侯间的交往与盟会；他死之后为什么还追谥为灵公呢？”大弢说：“这样的谥号就是因为他具有这样的德行。”伯常骞说：“那时候卫灵公有三个妻子，他们在一个盆池里洗澡。卫国的贤臣史䲡奉召进到卫灵公的寓所，只得急忙接过衣裳来相互帮助遮掩。他对待大臣是多么的傲慢，而他对贤人又是如此的肃敬，这就是他死后追谥为灵公的原因。”狶韦则说：“当年卫灵公死了，占卜问葬说是葬在原墓地不吉利，而葬在沙丘上就能吉利。于是挖掘沙丘数丈，发现有一石制外棺，洗去泥土一看，上面还刻有一段文字，说：‘不靠子孙，灵公将得此为冢。’灵公被叫做‘灵’看来已经很久很久了，大弢和伯常骞怎么能够知道！”
少知向大公调求教：“什么叫做‘丘里’之言？”大公调说：“所谓‘丘里’，就是聚合头十个姓，上百个人而形成共同的风气与习俗；组合各各不同的个体就形成混同的整体，离散混同的整体又成为各各不同的个体。如今指称马的上百个部位都不能获得马的整体，而马就拴缚在眼前，只有确立了马的每一个部位并组合成一整体才能称之为马。所以说山丘积聚卑小的土石才成就其高，江河汇聚细小的流水才成就其大，伟大的人物并合了众多的意见才成就其公。所以，从外界反映到内心里的东西，自己虽有定见却并不执着己见，由内心里向外表达的东西，即使是正确的也不愿跟他人相违逆。四季具有不同的气候，大自然并没有对某一节令给予特别的恩赐，因此年岁的序列得以形成；各种官吏具有不同的职能，国君没有偏私，因此国家得以治理；文臣武将具有各不相同的本事，国君不作偏爱，因此各自德行完备；万物具有各别的规律，大道对它们也都没有偏爱，因此不去授予名称以示区别。没有称谓因而也就没有作为，没有作为因而也就无所不为。时序有终始，世代有变化。祸福在不停地流转，出现违逆的一面同时也就存在相宜的一面；各自追逐其不同的侧面，有所端正的同时也就有所差误。就拿山泽来比方，生长的各种材质全都有自己的用处；再看看大山，树木与石块处在同一块地方。这就叫做‘丘里’的言论。”
少知问：“既然如此，那么称之为道，可以吗？”大公调说：“不可以。现在计算一下物的种数，不止于一万，而只限于称作万物，是用数目字最多的来称述它。所以，天和地，是形体中最大的；阴与阳，是元气中最大的；而大道却把天地、阴阳相贯通。因为它大就用‘道’来称述它是可以的，已经有了‘道’的名称，还能够用什么来与它相提并论呢？假如用这样的观点来寻求区别，就好像狗与马，其间的差别也就太大了！”
少知问：“四境之内，宇宙之间，万物的产生从哪里开始？”大公调说：“阴阳互相辉映、互相伤害又互相调治，四季互相更替、互相产生又互相衰减。欲念、憎恶、离弃、靠拢，于是像桥梁一样相互连接相互兴起，雌性、雄性的分开、交合，于是相互为常相互具有。安全与危难相互变易，灾祸与幸福相互生存，寿延与夭折相互交接，生还与死亡因此而形成。这些现象的名称与实际都能理出端绪，精细微妙之处都能记载下来。随物变化的次序相互更替总是遵循着一定的轨迹，又像桥梁连接彼此两方那样地运动而又彼此相互制约，到了尽头就会折回，有了终结就有开始；这都是万物所共有的规律。言语所能致意的，智巧所能达到的，只限于人们所熟悉的少数事物罢了。体察大道的人，不追逐事物的消亡，不探究事物的源起，这就是言语评说所限止的境界。”少知又问：“季真的‘莫为’观点，接子的‘或使’主张，两家的议论，谁最合乎事物的真情，谁又偏离了客观的规律？”大公调说：“鸡鸣狗叫，这是人人都能了解的现象；可是，即使是具有超人的才智，也不能用言语来称述其自我变化的原因，同样也不能臆断它们将会怎么样。用这样的道理来加以推论和分析，精妙达到了无以伦比，浩大达到了不可围量，事物的产生有所支持，还是事物的产生全出于虚无，两种看法各持一端均不能免于为物所拘滞，因而最终只能是过而不当。‘或使’的主张过于执滞，‘莫为’的观点过于虚空。有名有实，这就构成物的具体形象。无名无实，事物的存在也就显得十分虚无。可以言谈也可以测度，可是越是言谈距离事物的真情也就越疏远。没有产生的不能禁止其产生，已经死亡的不能阻挡其死亡。死与生并不相距很远，其中的规律却是不易察见。事物的产生有所支使，还是事物的产生全都出于虚无，两者都是因为疑惑而借此生出的偏执之见。我观察事物的原本，事物的过去没有穷尽；我寻找事物的末绪，事物的将来不可限止。没有穷尽又没有限止，言语的表达不能做到，这就跟事物具有同一的规律；而‘或使’、‘莫为’的主张，用言谈各持一端，又跟事物一样有了外在的终始。道不可以用“有”来表达，‘有’也不可以用无来描述。大道之所以称为‘道’，只不过是借用了‘道’的名称。‘或使’和‘莫为’的主张，各自偏执于事物的一隅，怎么能称述于大道呢？言语圆满周全，那么整天说话也能符合于道；言语不能圆满周全，那么整天说话也都滞碍于物。道是阐释万物的最高原理，言语和缄默都不足以称述；既不说话也不缄默，评议有极限而大道却是没有极限的。”', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf690f8fda5565061262", "shortContent": "本赋沿袭汉大赋传统体式，假洞庭乡三老与吴郡采石吏，设为问答，贯穿首尾，佯颂实讽，颇具新意。\n序中交代采石缘由。徽宗即位初，因宰相韩忠彦、曾布奏请，修建景灵西宫，奉安徽宗父神宗、母陈太后御像。所采之石为太湖石，出产太湖一带，多孔而玲珑剔透，供点缀庭院或堆叠假山之用。吴兴，在今浙江湖州市；吴郡，在今江苏苏州市，均处太湖地区。吴郡所采，出自包山，即洞庭西山，在今苏州市西南太湖中。作者亲眼实见，有感而发。...", "authors": ["张徐芳"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed207c6e67846a921a175", "shortContent": "一个作家的性情、风骨，必然会或多或少地体现在他的作品中。作家的艺术个性愈鲜明，审美理想愈执著，那么，他表现自我的愿望就愈强，而思想感情，倾注到他所着意描绘的外在景物上的内驱力也就愈大。明初文人宋濂曾经发挥陆机“诗缘情而绮靡”的名言，提出了“缘情托物”的说法。“缘情”指作家主体的物化，“托物”是客体的人化。这两种因素的水乳交融便是绝妙的审美创造的前提。晚明竟陵派领袖钟惺的《夏梅说》，便是艺术的人化和...", "authors": ["吴调公"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f7ddbb8b379ee0aec0a", "shortContent": "嵇康（223—262，或224—263），字叔夜，谯郡铚（今安徽濉溪西南）人。魏宗室之婿，曾任中散大夫，世称嵇中散。文学、哲学和音乐诸方面，皆有甚高的成就。崇尚老庄，恬静寡欲，而又刚肠疾恶，锋芒毕露，反对虚伪礼教，为“竹林七贤”之一。\n这两则故事的共同点是夜里弹琴而遇鬼。第一则简，只粗略地写了鬼的形体，精练地突出了嵇康的不怕鬼精神和高洁、傲岸态度。\n凡鬼皆令人蔑视、惹人厌恶吗？第二则详答之：首先写...", "authors": ["何均地"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa4c6e67846a9226f02", "shortContent": "不少志怪小说，常是搜奇记异，耸人听闻，荒谬乖诞，令人难以置信。如果硬要从中抉微探幽，寻其微言大义，则很容易穿凿附会，有失作者本意。本文所写群少夜遇山魈故事即属此类。即使果有此事，那么，当群少唱和吹歌时，那窃听者虽然异乎常人，但并无妨碍欢歌之意，只是“以手按拍，作知音态”而已。群少不应“以爆竹击之”，更不应以此称快。而倘若果是知音之人，也不应因群少恶作剧，便毁坏笙歌之所，致使丝管寂寂三十余年之久。倘...", "authors": ["徐振贵", "张玉芹"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42b35914587d02f67d62", "shortContent": "自古就有不少劝善惩恶的作品，明代人有感于世风日下，更有不少此类作品出现。《桂迁梦感录》即为其中的一篇。但多数作品总是通过赞美主人公来进行规劝，此篇却从以怨报德的角度出发，规劝世人知恩图报，切莫忘恩负义，并从中向世人展示了世态炎凉和社会风貌。\n这篇小说写的虽然是元朝的事，却生动形象地反映了明代的社会生活。当时，社会已经出现资本主义萌芽，特别是东南沿海地区，商业繁荣，商品贸易十分兴旺。一些有识之士便把...", "authors": ["宁稼雨", "芦", "茜"], "pressName": "上海辞书出版社"}]', '', 'indent', 1524912564, '5ae3e131ee920a00430a25c2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637420, '庄子 · 杂篇 · 外物', NULL, 5, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E6%9D%82%E7%AF%87%C2%B7%E5%A4%96%E7%89%A9/10157054?fr=aladdin', '', '外物不可必，故龙逢诛，比干戮，箕子狂，恶来死，桀纣亡。人主莫不欲其臣之忠，而忠未必信，故伍员流于江，苌弘死于蜀，藏其血三年而化为碧。人亲莫不欲其子之孝，而孝未必爱，故孝己忧而曾参悲。木与木相摩而然，金与火相守则流。阴阳错行，则天地大絯，于是乎有雷有霆，水中有火，乃焚大槐。有甚忧两陷而无所逃，螴蜳不得成，心若县于天地之间，慰昏沈屯，利害相摩，生火甚多；众人焚火，月固不胜火，于是乎有僓然而道尽。
庄周家贫，故往贷粟于监河侯。监河侯曰：“诺。我将得邑金，将贷子三百金，可乎？”庄周忿然作色曰：“周昨来，有中道而呼者。周顾视车辙中，有鲋鱼焉。周问之曰：‘鲋鱼来！子何为者邪？’对曰：‘我，东海之波臣也。君岂有斗升之水而活我哉？’周曰：‘诺。我且南游吴越之王，激西江之水而迎子，可乎？’鲋鱼忿然作色曰：‘吾失我常与，我无所处。吾得斗升之水然活耳，君乃言此，曾不如早索我枯鱼之肆！’”（转化为成语：涸辙之鲋）
任公子为大钩巨缁，五十犗以为饵，蹲乎会稽，投竿东海，旦旦而钓，期年不得鱼。已而大鱼食之，牵巨钩，錎没而下，鹜扬而奋鬐，白波如山，海水震荡，声侔鬼神，惮赫千里。任公得若鱼，离而腊之，自制河以东，苍梧已北，莫不厌若鱼者。已而后世辁才讽说之徒，皆惊而相告也。夫揭竿累，趣灌渎，守鲵鲋，其于得大鱼难矣。饰小说以干县令，其于大达亦远矣，是以未尝闻任氏之风俗，其不可与经于世亦远矣。
儒以诗礼发冢，大儒胪传曰：“东方作矣，事之何若？”小儒曰：“未解裙襦，口中有珠。诗固有之曰：‘青青之麦，生於陵陂。生不布施，死何含珠为！’”“接其鬓，压其顪，儒以金椎控其颐，徐别其颊，无伤口中珠！”
老莱子之弟子出薪，遇仲尼，反以告，曰：“有人于彼，修上而趋下，末偻而后耳，视若营四海，不知其谁氏之子。”老莱子曰：“是丘也。召而来。”仲尼至。曰：“丘！去汝躬矜与汝容知，斯为君子矣。”仲尼揖而退，蹙然改容而问曰：“业可得进乎？”老莱子曰：“夫不忍一世之伤而骜万世之患，抑固窭邪，亡其略弗及邪？惠以欢为骜，终身之丑，中民之行进焉耳，相引以名，相结以隐。与其誉尧而非桀，不如两忘而闭其所誉。反无非伤也，动无非邪也。圣人踌躇以兴事，以每成功，奈何哉其载焉终矜尔！”
宋元君夜半而梦人被发窥阿门，曰：“予自宰路之渊，予为清江使河伯之所，渔者余且得予。”元君觉，使人占之，曰：“此神龟也。”君曰：“渔者有余且乎？”左右曰：“有。”君曰：“令余且会朝。”明口，余且朝。君曰：“渔何得？”对曰：“且之网得白龟焉，其圆五尺，”君曰：“献若之龟。”龟至，君再欲杀之，再欲活之，心疑，卜之，曰：“杀龟以卜吉。”乃刳龟，七十二钻而无遗。仲尼曰：“神龟能见梦于元君，而不能避余且之网；知能七十二钻而无遗？，不能避刳肠之患。如是，则知有所困，神有所不及也。虽有至知，万人谋之。鱼不畏网而畏鹈鹕。去小知而大知明，去善而自善矣。婴儿生无石师而能言，与能言者处也。”
惠子谓庄子曰：“子言无用。”庄子曰：“知无用而始可与言用矣。天地非不广且大也，人之所用容足耳。然则厕足而垫之，致黄泉，人尚有用乎？”惠子曰：“无用。”庄子曰：“然则无用之为用也亦明矣。”
庄子曰：“人有能游，且得不游乎？人而不能游，且得游乎？夫流遁之志，决绝之行，噫，其非至知厚德之任与！覆坠而不反，火驰而不顾，虽相与为君臣，时也，易世而无以相践。故曰至人不留行焉。夫尊古而悲今，学者之流也。且以狶韦氏之流观今之世，夫孰能不波？唯至人乃能游于世而不僻，顺人而不失己。彼教不学，承意不彼。”
目彻为明，耳彻为聪，鼻彻为颤，口彻为甘，心彻为知，知彻为德。凡道不欲壅，壅则哽，哽而不止则跈，跈者众害生。物之有知者恃息，其不殷，非天之罪。天之穿之，日夜无降，人则顾塞其窦。胞有重阆，心有天游。室无空虚，则妇姑勃溪；心无天游，则六凿相攘。大林丘山之善于人也，亦神者不胜。
德溢乎名，名溢乎暴，谋稽乎誸，知出乎争，柴生乎守，官事果乎众宜。春雨日时，草木怒生，铫鎒于是乎始修，草木之到植者过半，而不知其然。
静然可以补病，眦搣可以休老，宁可以止遽。虽然，若是，劳者之务也，非佚者之所未尝过而问焉。圣人之所以駴天下，神人未尝过而问焉；贤人所以駴世，圣人未尝过而问焉；君子所以駴国，贤人未尝过而问焉；小人所以合时，君子未尝过而问焉。
演门有亲死者，以善毁爵为官师，其党人毁而死者半。尧与许由天下，许由逃之；汤与务光，务光怒之。纪他闻之，帅弟子而踆于窾水；诸侯吊之，三年，申徒狄因以踣河。荃者所以在鱼，得鱼而忘荃；蹄者所以在兔，得兔而忘蹄；言者所以在意，得意而忘言。吾安得夫忘言之人而与之言哉！', '《庄子·杂篇·外物》是庄子所作的一篇杂谈。“外物”是篇首的两个字，用来作为篇名。全文内容依旧很杂，但多数文字在于讨论养生处世，倡导顺应，反对矫饰，反对有所操持，从而做到虚己而忘言。', '', '外在事物不可能有个定准，所以忠良之士关龙逢被斩杀，比干遭杀害，箕子被迫装疯，而谀臣恶来同样不能免于一死，暴君夏桀和殷纣也同样身毁国亡。国君无不希望他的臣子效忠于己，可是竭尽忠心未必能够取得信任，所以伍子胥被赐死而且飘尸江中，苌弘被流放西蜀而死，西蜀人珍藏他的血液三年后竟化作碧玉。做父母的无不希望子女孝顺，可是竭尽孝心未必能够受到怜爱，所以孝己愁苦而死、曾参悲切一生。木与木相互摩擦就会燃烧，金属跟火相互厮守就会熔化。阴与阳错乱不顺，天与地都会大受惊骇，于是雷声隆隆，雷雨中夹着闪电，甚至烧毁高大的树木。心存忧喜而且在这两种心境中越陷越深就会没有办法逃避，小心翼翼、恐惧不安而又一无所成，内心像高悬在天地之间，忧郁沉闷，利害得失在心中碰撞，于是内心烦乱焦躁万分；世俗人内热如火烧毁了中和之气，清虚淡泊的心境抑制不住内心如火的焦虑，于是便精神颓然玄理荡然无存。
庄周家境贫寒，于是向监河侯借粮。监河侯说：“行，我即将收取封邑的税金，打算借给你三百金，好吗？”庄周听了脸色骤变忿忿地说：“我昨天来的时候，有谁在半道上呼唤我。我回头看看路上车轮辗过的小坑洼处，有条鲫鱼在那里挣扎。我问它：‘鲫鱼，你干什么呢？’鲫鱼回答：‘我是东海水族中的一员。你也许能用斗升之水使我活下来吧。’我对它说：‘行啊，我将到南方去游说吴王越王，引发西江之水来迎候你，可以吗？’鲫鱼变了脸色生气地说：‘我失去我经常生活的环境，没有安身之处。眼下我能得到斗升那样多的水就活下来了，而你竟说出这样的话，还不如早点到干鱼店里找我！’”
任国公子做了个大鱼钩系上粗大的黑绳，用五十头牛牲做钓饵，蹲在会稽山上，把钓竿投向东海，每天都这样钓鱼，整整一年一条鱼也没钓到。不久大鱼食吞鱼饵，牵着巨大的钓钩，急速沉没海底，又迅急地扬起脊背腾身而起，掀起如山的白浪，海水剧烈震荡，吼声犹如鬼神，震惊千里之外。任公子钓得这样一条大鱼，将它剖开制成鱼干，从浙江以东，到苍梧以北，没有谁不饱饱地吃上这条鱼的。这以后那些浅薄之人和喜好品评议论之士，都大为吃惊奔走相告。他们举着钓竿丝绳，奔跑在山沟小渠旁，守候小鱼上钩，至于想得到大鱼那就很难很难了。修饰浅薄的言辞以求得高高的美名，对于达到通晓大道的境界来说距离也就很远很远了，因此说不曾了解过任公子有所大成的志趣，恐怕也不可以说是善于治理天下，而且其间的差距也是很远很远了。
儒生表面运用诗、书而暗地里却在盗墓。大儒在上面向下传话：“太阳快升起来了，事情进行得怎么样？”小儒说：“下裙和内衣还未解开，口中还含着珠子。古诗上就有这样的诗句：‘青青的麦苗，长在山坡上。生前不愿周济别人，死了怎么还含着珠子！’”大儒说：“挤压他的两鬓，按着他的胡须，你再用锤子敲打他的下巴，慢慢地分开他的两颊，不要损坏了口中的珠子！”
老莱子的弟子出外打柴，遇上了孔丘，打柴归来告诉给老莱子，说：“有个人在那里，上身长下身短，伸颈曲背而且两耳后贴，眼光敏锐周遍四方，不知道他是姓什么的人。”老莱子说：“这个人一定是孔丘。快去叫他来见我。”孔丘来了，老莱子说：“孔丘，去掉你仪态上的矜持和容颜上的睿智之态，那就可以成为君子了。”孔丘听了后谦恭地作揖而退，面容顿改心悸不安地问道：“我所追求的仁义之学可以修进并为世人所用吗？”老莱子说：“不忍心一世的损伤却会留下使后世奔波不息的祸患，你是本来就孤陋蔽塞，还是才智赶不上呢？布施恩惠以博取欢心并因此自命不凡，这是终身的丑恶，是庸人的行为罢了，这样的人总是用名声来相互招引，用私利来相互勾结。与其称赞唐尧非议夏桀，不如两种情况都能遗忘而且堵住一切称誉。背逆事理与物性定会受到损伤，心性被搅乱就会邪念顿起。圣哲的人顺应事理稳妥行事，因而总是事成功就。你执意推行仁义而且以此自矜又将会怎么样呢？”
宋元君半夜里梦见有人披散着头发在侧门旁窥视，说：“我来自名叫宰路的深渊，我作为清江的使者出使河伯的居所，渔夫余且捕捉了我。”宋元君醒来，派人占卜，说：“这是一只神龟。”宋元君问：“渔夫有名叫余且的吗？”左右侍臣回答：“有。”宋元君说：“叫余且来朝见我。”第二天，余且来朝。宋元君问：“你捕捞到了什么？”余且回答：“我的网捕捉到一只白龟，周长五尺。”宋元君说：“献出你捕获的白龟”。白龟送到，宋元君一会儿想杀到，一会儿又想养起来，心理正犯疑惑，卜问吉凶，说：“杀掉白龟用来占卜，一定大吉。”于是把白龟剖开挖空，用龟板占卜数十次推断起来也没有一点失误。孔子知道后说：“神龟能显梦给宋元君，却不能避开余且的鱼网；才智能占卜数十次也没有一点失误，却不能逃脱剖腹挖肠祸患。如此说来，才智也有困窘的时候，神灵也有考虑不到的地方。即使存在最高超的智慧，也匹敌不了万人的谋算。鱼儿即使不畏惧鱼网却也会害怕鹈鹕。摒弃小聪明方才显示大智慧，除去矫饰的善行方才能使自己真正回到自然的善性。婴儿生下地来没有高明的老师指教也能学会说话，只因为跟会说话的人自然相处。”
惠子对庄子说：“你的言论没有用处。”庄子说：“懂得没有用处方才能够跟他谈论有用。大地不能不说是既广且大了，人所用的只是脚能踩踏的一小块罢了。既然如此，那么只留下脚踩踏的一小块其余全都挖掉，一直挖到黄泉，大地对人来说还有用吗？”惠子说：“当然没有用处。”庄子说：“如此说来，没有用处的用处也就很明白了。”
庄子说：“人若能随心而游，那么难道还会不自适自乐吗？人假如不能随心而游，那么难道还能够自适自乐吗？流荡忘返于外物的心思，矢志不渝弃世孤高的行为，唉，恐怕不是真知大德之人的所作所为吧！沉溺于世事而不知悔悟，心急如焚地追逐外物而不愿反顾，即使相互间有的为君有的为臣，也只是看作一时的机遇，时世变化后就没有谁会认为自己地位低下了。所以说道德修养极为高尚的人从不愿意在人生的旅途上有所滞留。崇尚古代鄙薄当今，这是未能通达事理之人的观点。用狶韦氏之流的角度来观察当今的世事，谁又能不在心中引起波动？道德修养极为高尚的人方才能够混迹于世而不出现邪僻，顺随于众人之中却不会失却自己的真性。尊古卑今的见教不应学取，禀受其意也不必相互对立争辩不已。”
眼光敏锐叫做明，耳朵灵敏叫做聪，鼻子灵敏叫做膻，口感灵敏叫做甘，心灵透彻叫做智，聪明贯达叫做德。大凡道德总不希望有所壅塞，壅塞就会出现梗阻，梗阻而不能排除就会出现相互践踏，相互残踏那么各种祸害就会随之而起。物类有知觉靠的是气息，假如气息不盛，那么绝不是自然禀赋的过失。自然的真性贯穿万物，日夜不停，可是人们却反而堵塞自身的孔窍。腹腔有许多空旷之处因而能容受五脏怀藏胎儿，内心虚空便会没有拘系地顺应自然而游乐。屋里没有虚空感，婆媳之间就会争吵不休；内心不能虚空而且游心于自然，那么六种官能就会出现纷扰。森林与山丘之所以适宜于人，也是因为人们的内心促狭、心神不爽。
德行的外溢是由于名声，名声的外溢是由于张扬，谋略的考究是由于危急，才智的运用是由于争斗，闭塞的出现是由于执滞，官府事务处理果决是由于顺应了民众。春雨应时而降，草木勃然而生，锄地的农具开始整修，田地里杂草锄后再生超过半数，而人们往往并不知道为什么会这样。
沉静可以调养病体，摩摩擦擦可以延缓衰老，宁寂安定可以止息内心的急促。虽然如此，像这样，仍是操劳的人所务必要做到的，闲逸的人却从不予以过问。圣人用来惊骇天下的办法，神人不曾过问；贤人用来惊骇时世的办法，圣人不曾过问；君子用来惊骇国人的办法，贤人不曾过问；小人用来苟合于一时的办法，君子也不曾过问。
东门口有个死了亲人的人，因为格外哀伤日渐消瘦而加官进爵封为官师，他的同乡仿效他也消瘦毁容却死者过半。尧要禅让天下给许由，许由因而逃到箕山；商汤想把天下禅让给务光，务光大发脾气；纪他知道了这件事，率领弟子隐居在窾水一带，诸侯纷纷前往慰问，过了三年，申徒狄仰慕其名而投河自溺。
竹笱是用来捕鱼的，捕到鱼后就忘掉了鱼笱；兔网是用来捕捉兔子的，捕到兔子后就忘掉了兔网；言语是用来传告思想的，领会了意思就忘掉了言语。我怎么才能寻找到忘掉言语的人而跟他谈一谈呢！', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf6003048e64fbd9c9d2", "shortContent": "本文写于卢照邻被诬入狱，得友人搭救出狱之后，曾列于卢照邻手编文集之首，表达了作者对伸以援手的友人的答谢感恩之意。全文以陷入困境的大鱼自比，而以大鹏比喻伸以援手的友人，想象贴切，以物喻人，抒发对个体生命的强烈感受。\n钱基博先生《中国文学史》第四编第二章《论唐》中指出：“《穷鱼赋》仗气爱奇，最为卓荦入古。”在卢照邻的文章中，钱先生对这篇《穷鱼赋》评价最高。而钱先生称其“仗气爱奇，最为卓荦入古”的原因，...", "authors": ["邓", "芳"], "pressName": "上海辞书出版社"}]', '', 'indent', 1524912598, '5ae3e1529f5454005eafc4eb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637423, '庄子 · 杂篇 · 盗跖', NULL, 7, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E6%9D%82%E7%AF%87%C2%B7%E7%9B%97%E8%B7%96/10195546?fr=aladdin', '', '孔子与柳下季为友，柳下季之弟，名曰盗跖。盗跖从卒九千人，横行天下，侵暴诸侯。穴室枢户，驱人牛马，取人妇女。贪得忘亲，不顾父母兄弟，不祭先祖。所过之邑，大国守城，小国入保，万民苦之。
孔子谓柳下季曰：「夫为人父者，必能诏其子；为人兄者，必能教其弟。若父不能诏其子，兄不能教其弟，则无贵父子兄弟之亲矣。今先生，世之才士也，弟为盗跖，为天下害，而弗能教也，丘窃为先生羞之。丘请为先生往说之。」
柳下季曰：「先生言为人父者必能诏其子，为人兄者必能教其弟，若子不听父之诏，弟不受兄之教，虽今先生之辩，将奈之何哉！且跖之为人也，心如涌泉，意如飘风，强足以距敌，辩足以饰非。顺其心则喜，逆其心则怒，易辱人以言。先生必无往。」
孔子不听，颜回为驭，子贡为右，往见盗跖。盗跖乃方休卒徒于太山之阳，脍人肝而哺之。孔子下车而前，见谒者曰：「鲁人孔丘，闻将军高义，敬再拜谒者。」
谒者入通。盗跖闻之大怒，目如明星，发上指冠，曰：「此夫鲁国之巧伪人孔丘非邪？为我告之：『尔作言造语，妄称文武，冠枝木之冠，带死牛之胁，多辞缪说，不耕而食，不织而衣，摇唇鼓舌，擅生是非，以迷天下之主，使天下学士不反其本，妄作孝弟而侥幸于封侯富贵者也。子之罪大极重，疾走归！不然，我将以子肝益昼哺之膳。』」
孔子复通曰：「丘得幸于季，愿望履幕下。」
谒者复通，盗跖曰：「使来前！」
孔子趋而进，避席反走，再拜盗跖。盗跖大怒，两展其足，案剑瞋目，声如乳虎，曰：「丘来前！若所言，顺吾意则生，逆吾心则死。」
孔子曰：「丘闻之，凡天下人有三德：生而长大，美好无双，少长贵贱见而皆说之，此上德也；知维天地，能辩诸物，此中德也；勇悍果敢，聚众率兵，此下德也。凡人有此一德者，足以南面称孤矣。今将军兼此三者，身长八尺二寸，面目有光，唇如激丹，齿如齐贝，音中黄钟，而名曰盗跖，丘窃为将军耻不取焉。将军有意听臣，臣请南使吴越，北使齐鲁，东使宋卫，西使晋楚，使为将军造大城数百里，立数十万户之邑，尊将军为诸侯，与天下更始，罢兵休卒，收养昆弟，共祭先祖。此圣人才士之行，而天下之愿也。」
盗跖大怒曰：「丘来前！夫可规以利而可谏以言者，皆愚陋恒民之谓耳。今长大美好，人见而悦之者，此吾父母之遗德也。丘虽不吾誉，吾独不自知邪？
且吾闻之，好面誉人者，亦好背而毁之。今丘告我以大城众民，是欲规我以利而恒民畜我也，安可久长也！城之大者，莫大乎天下矣。尧、舜有天下，子孙无置锥之地；汤、武立为天子，而后世绝灭；非以其利大故邪？
且吾闻之，古者禽兽多而人少，于是民皆巢居以避之。昼拾橡栗，暮栖木上，故命之曰『有巢氏之民』。古者民不知衣服，夏多积薪，冬则炀之，故命之曰『知生之民』。神农之世，卧则居居，起则于于。民知其母，不知其父，与麋鹿共处，耕而食，织而衣，无有相害之心，此至德之隆也。然而黄帝不能致德，与蚩尤战于涿鹿之野，流血百里。尧、舜作，立群臣；汤放其主，武王杀纣。自是之后，以强陵弱，以众暴寡。汤、武以来，皆乱人之徒也。
今子修文、武之道，掌天下之辩，以教后世。缝衣浅带，矫言伪行，以迷惑天下之主，而欲求富贵焉，盗莫大于子。天下何故不谓子为盗丘，而乃谓我为盗跖？子以甘辞说子路而使从之，使子路去其危冠，解其长剑，而受教于子，天下皆曰孔丘能止暴禁非。其卒之也，子路欲杀卫君而事不成，身菹于卫东门之上，子教子路菹此患，上无以为身，下无以为人，是子教之不至也。子自谓才士圣人邪？则再逐于鲁，削迹于卫，穷于齐，围于陈蔡，不容身于天下。子之道岂足贵邪？
世之所高，莫若黄帝，黄帝尚不能全德，而战涿鹿之野，流血百里。尧不慈，舜不孝，禹偏枯，汤放其主，武王伐纣，文王拘羑里。此六子者，世之所高也。孰论之，皆以利惑其真而强反其情性，其行乃什可羞也。
世之所谓贤士，莫若伯夷、叔齐。伯夷、叔齐辞孤竹之君，而饿死于首阳之山，骨肉不葬。鲍焦饰行非世，抱木而死。申徒狄谏而不听，负石自投于河，为鱼鳖所食。介子推至忠也，自割其股以食文公，文公后背之，子推怒而去，抱木而燔死。尾生与女子期于梁下，女子不来，水至不去，抱梁柱而死。此六子者，无异于磔犬流豕操瓢而乞者，皆离名轻死，不念本养寿命者也。
世之所谓忠臣者，莫若王子比干、伍子胥。子胥沉江，比干剖心，此二子者，世谓忠臣也，然卒为天下笑。自上观之，至于子胥、比干，皆不足贵也。
丘之所以说我者，若告我以鬼事，则我不能知也；若告我以人事者，不过此矣，皆吾所闻知也。
今吾告子以人之情，目欲视色，耳欲听声，口欲察味，志气欲盈。人上寿百岁，中寿八十，下寿六十，除病瘐死丧忧患，其中开口而笑者，一月之中不过四五日而已矣。天与地无穷，人死者有时，操有时之具而托于无穷之间，忽然无异骐骥之驰过隙也。不能说其志意，养其寿命者，皆非通道者也。
丘之所言，皆吾之所弃也，亟去走归，无复言之！子之道，狂狂汲汲，诈巧虚伪事也，非可以全真也，奚足论哉！」
孔子再拜趋走，出门上车，执辔三失，目芒然无见，色若死灰，据轼低头，不能出气。归到鲁东门外，适遇柳下季。柳下季曰：「今者阙然数日不见，车马有行色，得微往见跖邪？」
孔子仰天而叹曰：「然！」
柳下季曰：「跖得无逆汝意若前乎？」
孔子曰：「然。丘所谓无病而自灸也。疾走料虎头，编虎须，几不免虎口哉！」
子张问于满苟得曰：「盍不为行？无行则不信，不信则不任，不任则不利。故观之名，计之利，而义真是也。若弃名利，反之于心，则夫士之为行，不可一日不为乎！」
满苟得曰：「无耻者富，多信者显。夫名利之大者，几在无耻而信。故观之名，计之利，而信真是也。若弃名利，反之于心，则夫士之为行，抱其天乎！」
子张曰：「昔者桀、纣贵为天子，富有天下。今谓臧聚曰，汝行如桀、纣，则有怍色，有不服之心者，小人所贱也。仲尼、墨翟，穷为匹夫，今谓宰相曰，子行如仲尼、墨翟，则变容易色称不足者，士诚贵也。故势为天子，未必贵也；穷为匹夫，未必贱也；贵贱之分，在行之美恶。」
满苟得曰：「小盗者拘，大盗者为诸侯，诸侯之门，仁义存焉。昔者桓公小白杀兄入嫂，而管仲为臣；田成子常杀君窃国，而孔子受币。论则贱之，行则下之，则是言行之情悖战于胸中也，不亦拂乎！故《书》曰：『孰恶孰美？成者为首，不成者为尾。』」
子张曰：「子不为行，即将疏戚无伦，贵贱无义，长幼无序；五纪六位，将何以为别乎？」
满苟得曰：「尧杀长子，舜流母弟，疏戚有伦乎？汤放桀，武王杀纣，贵贱有义乎？王季为适，周公杀兄，长幼有序乎？儒者伪辞，墨子兼爱，五纪六位将有别乎？
且子正为名，我正为利。名利之实，不顺于理，不监于道。吾日与子讼于无约曰：『小人殉财，君子殉名，其所以变其精、易其性，则异矣；乃至于弃其所为而殉其所不为，则一也。』故曰：无为小人，反殉而天；无为君子，从天之理。若枉若直，相而天极；面观四方，与时消息。若是若非，执而圆机；独成而意，与道徘徊。无转而行，无成而义，将失而所为。无赴而富，无殉而成，将弃而天。
比干剖心，子胥抉眼，忠之祸也；直躬证父，尾生溺死，信之患也；鲍子立干，申子自埋，廉之害也；孔子不见母，匡子不见父，义之失也。此上世之所传、下世之所语，以为士者正其言，必其行，故服其殃，离其患也。」
无足问于知和曰：「人卒未有不兴名就利者。彼富则人归之，归则下之，下则贵之。夫见下贵者，所以长生安体乐意之道也。今子独无意焉，知不足邪，意知而力不能行邪！故推正不妄邪？」
知和曰：「今夫此人以为与己同时而生，同乡而处者，以为夫绝俗过世之士焉；是专无主正，所以览古今之时，是非之分也，与俗化。世去至重，弃至尊，以为其所为也。此其所以论长生安体乐意之道，不亦远乎！惨怛之疾，恬愉之安，不监于体；怵惕之恐，欣欢之喜，不监于心；知为为而不知所以为，是以贵为天子，富有天下，而不免于患也。」
无足曰：「夫富之于人，无所不利，穷美究势，至人之所不得逮，贤人之所不能及，侠人之勇力而以为威强，秉人之知谋以为明察，因人之德以为贤良，非享国而严若君父。且夫声色滋味权势之于人，心不待学而乐之，体不待象而安之。夫欲恶避就，固不待师，此人之性也。天下虽非我，孰能辞之！」
知和曰：「知者之为，故动以百姓，不违其度，是以足而不争，无以为故不求。不足故求之，争四处而不自以为贪；有馀故辞之，弃天下而不自以为廉。廉贪之实，非以迫外也，反监之度。势为天子而不以贵骄人，富有天下而不以财戏人。计其患，虑其反，以为害于性，故辞而不受也，非以要名誉也。尧、舜为帝而雍，非仁天下也，不以美害生也；善卷、许由得帝而不受，非虚辞让也，不以事害己也。此皆就其利、辞其害，而天下称贤焉，则可以有之，彼非以兴名誉也。」
无足曰：「必持其名，苦体绝甘，约养以持生，则亦犹久病长厄而不死者也。」
知和曰：「平为福，有余为害者，物莫不然，而财其甚者也。今富人，耳营于钟鼓管籥之声，口嗛于刍豢醪醴之味，以感其意，遗忘其业，可谓乱矣；侅溺于冯气，若负重行而上坂也，可谓苦矣；贪财而取慰，贪权而取竭，静居则溺，体泽则冯，可谓疾矣；为欲富就利，故满若堵耳而不知避，且冯而不舍，可谓辱矣；财积而无用，服膺而不舍，满心戚醮，求益而不止，可谓忧矣；内则疑劫请之贼，外则畏寇盗之害，内周楼疏，外不敢独行，可谓畏矣。此六者，天下之至害也，皆遗忘而不知察，及其患至，求尽性竭财，单以反一日之无故而不可得也。故观之名则不见，求之利则不得，缭意绝体而争此，不亦惑乎！」', '《史记》用精练的几行字介绍了庄子，说他著书十馀万言，大抵都是寓言，如其中的《渔父》、《盗跖》、《胠箧》等篇，都是用来攻击孔子的学说，从而辨明老子的主张的。共三十三篇，分“内篇”、“外篇”、“杂篇”三个部分。“杂篇”十一篇的情形应当是庄子学派或者后来的学者所写，有一些篇幅就认为肯定不是庄子学派所有的思想，如《盗跖》。', '', '孔子跟柳下季是朋友，柳下季的弟弟名叫盗跖。盗跖的部下有九千人，横行天下，侵扰各国诸侯；穿室破门，掠夺牛马，抢劫妇女；贪财妄亲，全不顾及父母兄弟，也不祭祀祖先。他所经过的地方，大国避守城池，小国退入城堡，百姓被他弄得很苦。孔子对柳下季说：“大凡做父母的，必定能告诫自己的子女，做兄长的，必定能教育自己的弟弟。假如做父亲的不能告诫自己的子女，做兄长的不能教育自己的兄弟，那么父子、兄弟之间的亲密关系也就没有什么可贵的了。如今先生你，是当世的贤士，然而兄弟却被叫作盗跖，成为天下的祸害，而且不能加以管教，我私下里替先生感到羞愧。我愿意替你前去说服他。”柳下季说：“先生谈到做父亲的必定能告诫自己的子女，做兄长的必定能教育自己的弟弟，假如子女不听从父亲的告诫，兄弟不接受兄长的教育，即使像先生今天这样能言善辩，又能拿他怎么样呢？而且盗跖的为人，思想活跃犹如喷涌的泉水，感情变化就像骤起的暴风，勇武强悍足以抗击敌人，巧言善辩足以掩盖过失，顺从他的心意他就高兴，违背他的意愿他就发脾气，容易用言语侮辱别人。先生千万不要去见他。”
孔子不听，让颜回驾车，子贡作骖乘，前去会见盗跖。盗跖正好在泰山的南麓休整队伍，将人肝切碎后吃掉。孔子下了车走上前去，见了禀报的人员说：“鲁国人孔丘，听说将军刚毅正直，多多拜托转达我前来拜见的心意。”
禀报的人入内通报，盗跖听说孔子求见勃然大怒，双目圆睁亮如明星，头发怒起直冲帽顶，说：“这不就是那鲁国的巧伪之人孔丘吗？替我告诉他：‘你矫造语言，托伪于文王、武王的主张；你头上带着树杈般的帽子，腰上围着宽宽的牛皮带，满口的胡言乱语；你不种地却吃得不错，不织布却穿得讲究；你整天摇唇鼓舌，专门制造是非，用以迷惑天下的诸侯，使天下的读书人全都不能返归自然的本性，而且虚妄地标榜尽孝尊长的主张以侥幸得到封侯的赏赐而成为富贵的人。你实在是罪大恶极，快些滚回去！要不然，我将把你的心肝挖出来增加午餐的膳食！’”
孔子再次请求通报接见，说：“我荣幸地跟柳下季相识，诚恳希望能够面见将军。”禀报人员再次通报，盗跖说：“叫他进来！”孔子小心翼翼地快步走进帐去，又远离坐席连退数步，向盗跖深深施礼。盗跖一见孔子大怒不已，伸开双腿，按着剑柄怒睁双眼，喊声犹如哺乳的母虎，说：“孔丘你上前来！你所说的话，合我的心意有你活的，不合你的心意你就等着一死。”
孔子说：“我听说，大凡天下人有三种美德：生就魁梧高大，长得漂亮无双，无论少小年长高贵卑贱见到他都十分喜欢，这是上等的德行；才智能够包罗天地，能力足以分辨各种事物，这是中等的德行；勇武、慓悍、果决、勇敢，能够聚合众人统率士兵，这是下一等的德行。大凡人们有此一种美德，足以南面称王了。如今将军同时具备了上述三种美德，你高大魁梧身长八尺二寸，面容和双眼熠熠有光，嘴唇鲜红犹如朱砂，牙齿整齐犹如编贝，声音洪亮合于黄钟，然而名字却叫盗跖，我暗暗为将军感到羞耻并且认为将军不应有此恶名。将军如果有意听从我的劝告，我将南边出使吴国越国，北边出使齐国鲁国，东边出使宋国卫国，西边出使晋国秦国，派人为将军建造数百里的大城，确立数十万户人家的封邑，尊将军为诸侯，跟天下各国更除旧怨开启新的一页，弃置武器休养士卒，收养兄弟，供祭祖先。这才是圣人贤士的作为，也是天下人的心愿。”
盗跖大怒说：“孔丘上前来！凡是可以用利禄来规劝、用言语来谏正的，都只能称作愚昧、浅陋的普通顺民。如今我身材高大魁梧面目英俊美好，人人见了都喜欢，这是我的父母给我留下的美德。你孔丘即使不当面吹捧我，我难道不知道吗？而且我听说，喜好当面夸奖别人的人，也好背地里诋毁别人。如今你把建造大城、汇聚众多百姓的意图告诉给我，这是用功利来诱惑我，而且是用对待普通顺民的态度来对待我，这怎么可以长久呢！城池最大的，莫过于整个天下。尧舜拥有天下，子孙却没有立锥之地；商汤与周武王立做天子，可是后代却遭灭绝，这不是因为他们贪求占有天下的缘故吗？”
“况且我还听说，古时候禽兽多而人少，于是人们都在树上筑巢而居躲避野兽，白天拾取橡子，晚上住在树上，所以称他们叫做有巢氏之民。古时候人们不知道穿衣，夏天多多存积柴草，冬天就烧火取暖，所以称他们叫做懂得生存的人。到了神农时代，居处是多么安静闲暇，行动是多么优游自得，人们只知道母亲，不知道父亲，跟麋鹿生活在一起，自己耕种自己吃，自己织布自己穿，没有伤害别人的心思，这就是道德鼎盛的时代。然而到了黄帝就不再具有这样的德行，跟蚩尤在涿鹿的郊野上争战，流血百里。尧舜称帝，设置百官，商汤放逐了他的君主，武王杀死了纣王。从此以后，世上总是依仗强权欺凌弱小，依仗势众侵害寡少。商汤、武王以来，就都是属于篡逆叛乱的人了。”
“如今你研修文王、武王的治国方略，控制天下的舆论，一心想用你的主张传教后世子孙，穿着宽衣博带的儒式服装，说话与行动矫揉造作，用以迷惑天下的诸侯，而且一心想用这样的办法追求高官厚禄，要说大盗再没有比你大的了。天下为什么不叫你作盗丘，反而竟称我是盗跖呢？你用甜言蜜语说服了子路让他死心塌地地跟随你，使子路去掉了勇武的高冠，解除了长长的佩剑，受教于你的门下，天下人都说你孔子能够制止暴力禁绝不轨。可是后来，子路想要杀掉篡逆的卫君却不能成功，而且自身还在卫国东门上被剁成了肉酱，这就是你那套说教的失败。你不是自称才智的学士、圣哲的人物吗？却两次被逐出鲁国，在卫国被人铲削掉所有足迹，在齐国被逼得走投无路，在陈国蔡国之间遭受围困，不能容身于天下。而你所教育的子路却又遭受如此的祸患，做师长的没有办法在社会上立足，做学生的也就没有办法在社会上为人，你的那套主张难道还有可贵之处吗？”
“世上所尊崇的，莫过于黄帝，黄帝尚且不能保全德行，而征战于涿鹿的郊野，流血百里。唐尧不慈爱，虞舜不孝顺，大禹半身不遂，商汤放逐了他的君主，武王出兵征讨商纣，文王曾经被囚禁在羑里。这以上的六个人，都是世人所尊崇的，但是仔细评论起来，都是因为追求功利迷惑了真性而强迫自己违反了自然的禀赋，他们的做法实在是极为可耻的。”
“世人所称道的贤士，就如伯夷、叔齐。伯夷、叔齐辞让了孤竹国的君位，却饿死在首阳山，尸体都未能埋葬。鲍焦着意清高非议世事，竟抱着树木而死去。申徒狄多次进谏不被采纳，背着石块投河而死，尸体被鱼鳖吃掉。介子推算是最忠诚的了，割下自己大腿上的肉给晋文公吃，文公返国后却背弃了他，介子推一怒之下逃出都城隐居山林，也抱着树木焚烧而死。尾生跟一女子在桥下约会，女子没有如期赴约，河水涌来尾生却不离去，竟抱着桥柱子而淹死。这以上的六个人，跟肢解了的狗、沉入河中的猪以及拿着瓢到处乞讨的乞丐相比没有什么不同，都是重视名节轻生赴死，不顾念身体和寿命的人。”
“世人所称道的忠臣，没有超过王子比干和伍子胥的了。伍子胥被抛尸江中，比干被剖心而死，这两个人，世人都称作忠臣，然而最终被天下人讥笑。从上述事实看来，直到伍子胥、王子比干之流，都是不值得推崇的。”
“你孔丘用来说服我的，假如告诉我怪诞离奇的事，那我是不可能知道的；假如告诉我人世间实实在在的事，不过如此而已，都是我所听闻的事。现在让我来告诉你人之常情，眼睛想要看到色彩，耳朵想要听到声音，嘴巴想要品尝滋味，志气想要满足、充沛。人生在世高寿为一百岁，中寿为八十岁，低寿为六十岁，除掉疾病、死丧、忧患的岁月，其中开口欢笑的时光，一月之中不过四、五天罢了。天与地是无穷尽的，人的死亡却是有时限的，拿有时限的生命托付给无穷尽的天地之间，迅速地消逝就像是千里良驹从缝隙中骤然驰去一样。凡是不能够使自己心境获得愉快而颐养寿命的人，都不能算是通晓常理的人。”
“你孔丘所说的，全都是我想要废弃的，你赶快离开这里滚回去，不要再说了！你的那套主张，颠狂失性钻营奔逐，全都是巧诈、虚伪的东西，不可能用来保全真性，有什么好谈论的呢！”
孔子一再拜谢快步离去，走出帐门登上车子，三次失落拿在手里的缰绳，眼光失神模糊不清，脸色犹如死灰，低垂着头靠在车前的横木上，颓丧地不能大口喘气。回到鲁国东门外，正巧遇上了柳下季。柳下季说：“近来多日不见心里很不踏实，看看你的车马好像外出过的样子，恐怕是前去见到盗跖了吧？”孔子仰天长叹道：“是的。”柳下季说：“盗跖莫不是像先前我所说的那样违背了你的心意吧？”孔子说：“正是这样。我这样做真叫做没有生病而自行扎针一样，自找苦吃，急急忙忙地跑去撩拨虎头、编理虎须，几乎不免被虎口吞掉啊！”
子张向满苟得问道：“怎么不推行合于仁义的德行呢？没有德行就不能取得别人的信赖，不能取得别人的信赖就不会得到任用，不能得到任用就不会得到利益。所以，从名誉的角度来观察，从利禄的角度来考虑，能够实行仁义就真是这样的。假如弃置名利，只在内心求得反思，那么士大夫的所作所为，也不可能一天不讲仁义啊！”满苟得说：“没有羞耻的人才会富有，善于吹捧的人才会显贵。大凡获得名利最大的，几乎全在于无耻而多言。所以，从名誉的角度来观察，从利禄的角度来考虑，能够吹捧就真是这样的。假如弃置名利，只在内心求得反思，那么士大夫的所作所为，也就只有保持他的天性了啊！”子张说：“当年桀与纣贵为天子，富有到占有天下，如今对地位卑贱的奴仆说，你的品行如同桀纣，那么他们定会惭愧不已，产生不服气的思想，这是因为桀纣的所作所为连地位卑贱的人也瞧不起。仲尼和墨翟穷困到跟普通百姓一样，如今对官居宰相地位的人说，你的品行如同仲尼和墨翟，那么他一定会除去傲气谦恭地说自己远远比不上，这是因为士大夫确实有可贵的品行。所以说，势大为天子，未比就尊贵；穷困为普通百姓，未必就卑贱；尊贵与卑贱的区别，决定了德行的美丑。”满苟得说：“小的盗贼被拘捕，大的强盗却成了诸侯，诸侯的门内，方才存有道义之士。当年齐桓公小白杀了兄长、娶了嫂嫂而管仲却做了他的臣子，田成子常杀了齐简公自立为国君而孔子却接受了他赠与的布帛。谈论起来总认为桓公、田常之流的行为卑下，做起来又总是使自己的行为更加卑下，这就是说言语和行动的实情在胸中相互矛盾和斗争，岂不是情理上极不相合吗！所以古书上说过：谁坏谁好？成功的居于尊上之位，失败的沦为卑下之人。”
子张说：“你不推行合于仁义的德行，就必将在疏远与亲近之间失去人伦关系，在尊贵与卑贱之间失去规范和准则，在长上与幼小之间失去先后序列；这样一来五伦和六位，又拿什么加以区别呢？”满苟得说：“尧杀了亲生的长子，舜流放了同母的兄弟，亲疏之间还有伦常可言吗？商汤逐放夏桀，武王杀死商纣，贵贱之间还有准则可言吗？王季被立为长子，周公杀了两个哥哥，长幼之间还有序列可言吗？儒家伪善的言辞，墨家兼爱的主张，‘五纪’和‘六位’的序列关系还能有区别吗？
“而且你心里所想的正在于名，我心里所想的正为了利。名与利的实情，不合于理，也不明于道。我往日跟你在无约面前争论不休：‘小人为财而死，君子为名献身。然而他们变换真情、更改本性的原因，却没有不同；而竟至舍弃该做的事而不惜生命地追逐不该寻求的东西，那是同一样的。’所以说，不要去做小人，反过来追寻你自己的天性；不要去做君子，而顺从自然的规律。或曲或直，顺其自然；观察四方，跟随四时变化而消长。或是或非，牢牢掌握循环变化的中枢；独自完成你的心意，跟随大道往返进退。不要执着于你的德行，不要成就于你所说的规范；那将会丧失你的禀性。不要为了富有而劳苦奔波，不要为了成功而不惜献身，那将会舍弃自然的真性。比干被剖心，子胥被挖眼，这是忠的祸害；直躬出证父亲偷羊，尾生被水淹死，这是信的祸患；鲍焦抱树而立、干枯而死，申生宁可自缢也不申辩委屈，这是廉的毒害；孔子不能为母送终，匡子发誓不见父亲，这是义的过失。这些现象都是上世的传闻，当代的话题，总认为士大夫必定会让自己的言论正直，让自己的行动跟着去做，所以深受灾殃，遭逢如此的祸患。”
无足向知和问道：“人们终究没有谁不想树立名声并获取利禄的。那个人富有了人们就归附他，归附他也就自以为卑下，以自己为卑下就更会尊崇富有者。受到卑下者的尊崇，就是人们用来延长寿命、安康体质、快乐心意的办法。如今唯独你在这方面没有欲念，是才智不够用呢？还是有了念头而力量不能达到呢？抑或推行正道而一心不忘呢？”
知和说：“如今有这么一个兴名就利的人，就认为跟自己是同时生、同乡处，而且认为是超越了世俗的人了；其实这样的人内心里全无主心，用这样的办法去看待古往今来和是非的不同，只能是混同流俗而融合于世事。舍弃了贵重的生命，离开了最崇高的大道，而追求他一心想要追求的东西；这就是他们所说的延长寿命、安康体质、快乐心意的办法，不是跟事理相去太远吗！悲伤所造成的痛苦，愉快所带来的安适，对身体的影响自己不能看清；惊慌所造成的恐惧，欢欣所留下的喜悦，对于心灵的影响自己也不可能看清。知道一心去做自己想要去做的事却不知道为什么要这样去做，所以尊贵如同天子，富裕到占有天下，却始终不能免于忧患。”
无足说：“富贵对于人们来说，没有什么不利的，享尽天下的美好并拥有天下最大的权势，这是道德极高尚的人所不能得到的，也是贤达的人所不能赶上的；挟持他人的勇力用以显示自己的威强，把握他人的智谋用以表露自己的明察，凭借他人的德行用以赢得贤良的声誉，虽然没有享受过国家权力所带来的好处却也像君父一样威严。至于说到乐声、美色、滋味、权势对于每一个人，心里不等到学会就自然喜欢，身体不需要模仿早已习惯。欲念、厌恶、回避、俯就，本来就不需要师传，这是人的禀性。天下人即使都认为我的看法不对，谁又能摆脱这一切呢？”
知和说：“睿智的人的做法，总是依从百姓的心思而行动，不去违反民众的意愿，所以，知足就不会争斗，无所作为因而也就无有所求。不能知足所以贪求不已，争夺四方财物却不自认为是贪婪；心知有馀所以处处辞让，舍弃天下却不自认为清廉。廉洁与贪婪的实情，并不是因为迫于外力，应该转回头来察看一下各自的禀赋。身处天子之位却不用显贵傲视他人，富裕到拥有天下却不用财富戏弄他人。想一想它的后患，再考虑考虑事情的反面，认为有害于自然的本性，所以拒绝而不接受，并不是要用它来求取名声与荣耀。尧与舜做帝王天下和睦团结，并非行仁政于天下，而是不想因为追求美好而损害生命；善卷与许由能够得到帝王之位却辞让不受，也不是虚情假意的谢绝禅让，而是不想因为治理天下危害自己的生命。这些人都能趋就其利，辞避其害，因而人们称誉他们是贤明的人，可见贤明的称誉也是可以获取的，不过他们的本心并非建树个人的名誉。”
无足说：“必定要保持自己的名声，即使劳苦身形、谢绝美食、俭省给养以维持生命，那么这一定是个长期疾病困乏而没有死去的人。”
知和说：“均平就是幸福，有馀便是祸害，物类莫不是这样，而财物更为突出。如今富有的人，耳朵谋求钟鼓、箫笛的乐声，嘴巴满足于肉食、佳酿的美味，因而触发了他的欲念，遗忘了他的事业，真可说是迷乱极了；深深地陷入了愤懑的盛气之中，像背着重荷爬行在山坡上，真可说是痛苦极了；贪求财物而招惹怨恨，贪求权势而耗尽心力，安静闲居就沉溺于嗜欲，体态丰腴光泽就盛气凌人，真可说是发病了；为了贪图富有追求私利，获取的财物堆得像齐耳的高墙也不知满足，而且越是贪婪就越发不知收敛，真可说是羞辱极了；财物囤积却没有用处，念念不忘却又不愿割舍，满腹的焦心与烦恼，企求增益永无休止，真可说是忧愁极了；在家内总担忧窃贼的伤害，在外面总害怕寇盗的残杀，在内遍设防盗的塔楼和射箭的孔道，在外不敢独自行走，真可说是畏惧极了。以上的六种情况，是天下最大的祸害，全都遗忘不求审察，等到祸患来临，想要倾家荡产保全性命，只求返归贫穷求得一日的安宁也不可能。所以，从名声的角度来观察却看不见，从利益的角度来探求却得不到，使心意和身体受到如此困扰地竭力争夺名利，岂不迷乱吗！”', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1dd0f8fda556506158f", "shortContent": "铭文通常刻于器物上，亦有在宫室、城关、山川名胜等场所勒石为铭。其用意大体有二：一以自戒或警人，一以祝颂德行，彪炳功业。本文的性质属于前一种。但它是假托之作，并未真的刻勒。相传周时有《金人铭》，劝人慎言远祸，为孔子所称道。此虽出于伪托，却很有名。孙楚遂亦以伪托形式，作《反金人铭》。二铭宣扬截然相反的处世态度，读来不仅有趣，且发人深思。\n因为《反金人铭》针对《金人铭》而发，所以首先需要对后者略加介绍。...", "authors": ["汪涌豪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1524912708, '5ae3e1bf9f5454003f108c5d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637424, '庄子 · 杂篇 · 列御寇', NULL, 13, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E6%9D%82%E7%AF%87%C2%B7%E5%88%97%E5%BE%A1%E5%AF%87/10156383?fr=aladdin', '', '列御寇之齐，中道而反，遇伯昏瞀人。伯昏瞀人曰：“奚方而反？”
曰：“吾惊焉。”
曰：“恶乎惊？”
曰：“吾尝食于十，而五先馈。”
伯昏瞀人曰：“若是，则汝何为惊已？”
曰：“夫内诚不解，形谍成光，以外镇人心，使人轻乎贵老，而其所患。夫浆人特为食羹之货，多余之赢，其为利也薄，其为权也轻，而犹若是，而况于万乘之主乎！身劳于国而知尽于事，彼将任我以事而效我以功。吾是以惊。”
伯昏瞀人曰：“善哉观乎！女处已，人将保女矣！”
无几何而往，则户外之屦满矣。伯昏瞀人北面而立，敦杖蹙之乎颐，立有间，不言而出。
宾者以告列子，列子提屦，跣而走，暨乎门，曰：“先生既来，曾不发药乎？”
曰：“已矣，吾固告汝曰人将保汝，果保汝矣。非汝能使人保汝，而汝不能使人无保汝也，而焉用之感豫出异也！必且有感，摇而本才，又无谓也。与汝游者，又莫汝告也。彼所小言，尽人毒也。莫觉莫悟，何相孰也！巧者劳而知者忧，无能者无所求，饱食而敖游，泛若不系之舟，虚而敖游者也。”
郑人缓也呻吟裘氏之地。祗三年而缓为儒，河润九里，泽及三族，使其弟墨。儒墨相与辩，其父助翟。十年而缓自杀。其父梦之曰：“使而子为墨者，予也，阖胡尝视其良，既为秋柏之实矣？”
夫造物者之报人也，不报其人而报其人之天，彼故使彼。夫人以己为有以异于人以贱其亲，齐人之井饮者相捽也。故曰今之世皆缓也。自是，有德者以不知也，而况有道者乎！古者谓之遁天之刑。
圣人安其所安，不安其所不安；众人安其所不安，不安其所安。
庄子曰：“知道易，勿言难。知而不言，所以之天也。知而言之，所以之人也。古之人，天而不人。”
朱泙漫学屠龙于支离益，单千金之家，三年技成而无所用其巧。
圣人以必不必，故无兵；众人以不必必之，故多兵。顺于兵，故行有求。兵，恃之则亡。
小夫之知，不离苞苴牍，敝精神乎蹇浅，而欲兼济道物，太一形虚。若是者，迷惑于宇宙，形累不知太初。彼至人者，归精神乎无始而甘冥乎无何有之乡。水流乎无形，发泄乎太清。悲哉乎！汝为知在毫毛而不知大宁。
宋人有曹商者，为宋王使秦。其往也，得车数乘。王说之，益车百乘。反于宋，见庄子，曰：“夫处穷闾厄巷，困窘织屦，槁项黄馘者，商之所短也；一悟万乘之主而从车百乘者，商之所长也。”
庄子曰：“秦王有病召医。破癕溃痤者得车一乘，舐痔者得车五乘，所治愈下，得车愈多。子岂治其痔邪？何得车之多也？子行矣！”
鲁哀公问乎颜阖曰：“吾以仲尼为贞干，国其有瘳乎？”
曰：“殆哉圾乎仲尼！方且饰羽而画，从事华辞。以支为旨，忍性以视民而不知不信。受乎心，宰乎神，夫何足以上民！彼宜女与？予颐与？误而可矣！今使民离实学伪，非所以视民也。为后世虑，不若休之。难治也！”
施于人而不忘，非天布也，商贾不齿。虽以事齿之，神者弗齿。
为外刑者，金与木也；为内刑者，动与过也。宵人之离外刑者，金木讯之；离内刑者，阴阳食之。夫免乎外内之刑者，唯真人能之。
孔子曰：“凡人心险于山川，难于知天。天犹有春秋冬夏旦暮之期，人者厚貌深情。故有貌愿而益，有长若不肖，有顺懁而达，有坚而缦，有缓而悍。故其就义若渴者，其去义若热。故君子远使之而观其忠，近使之而观其敬，烦使之而观其能，卒然问焉而观其知，急与之期而观其信，委之以财而观其仁，告之以危而观其节，醉之以酒而观其侧，杂之以处而观其色。九征至，不肖人得矣。”
正考父一命而伛，再命而偻，三命而俯，循墙而走，孰敢不轨！如而夫者，一命而吕巨，再命而于车上舞，三命而名诸父。孰协唐许！
贼莫大乎德有心而心有睫，及其有睫也而内视，内视而败矣。凶德有五，中德为首。何谓中德？中德也者，有以自好也而吡其所不为者也。
穷有八极，达有三必，形有六府。美髯长大壮丽勇敢，八者俱过人也，因以是穷。缘循，偃佒，困畏不若人，三者俱通达。知慧外通，勇动多怨，仁义多责，达生之情者傀，达于知者肖；达大命者随，达小命者遭。
人有见宋王者，锡车十乘。以其十乘骄稚庄子。
庄子曰：“河上有家贫恃纬萧而食者，其子没于渊，得千金之珠。其父谓其子曰：‘取石来锻之！夫千金之珠，必在九重之渊而骊龙颔下。子能得珠者，必遭其睡也。使骊龙而寤，子尚奚微之有哉！’今宋国之深，非直九重之渊也；宋王之猛，非直骊龙也；子能得车者，必遭其睡也。使宋王而寤，子为鐈粉夫。”
或聘于庄子，庄子应其使曰：“子见夫牺牛乎？衣以文绣，食以刍叔。及其牵而入于大庙，虽欲为孤犊，其可得乎！”
庄子将死，弟子欲厚葬之。庄子曰：“吾以天地为棺椁，以日月为连璧，星辰为珠玑，万物为赍送。吾葬具岂不备邪？何以加此！”
弟子曰：“吾恐乌鸢之食夫子也。”
庄子曰：“在上为乌鸢食，在下为蝼蚁食，夺彼与此，何其偏也。”
以不平平，其平也不平；以不征征，其征也不征。明者唯为之使，神者征之。夫明之不胜神也久矣，而愚者恃其所见入于人，其功外也，不亦悲乎！', '“列御寇”本是一人名，这里用作篇名。全篇由许多小故事夹着议论组合而成。内容很杂，其间也无内在联系，不过从主要段落看，主要是阐述忘我的思想，人生在世不应炫耀于外，不应求仕求禄，不应追求智巧，不应贪功图报。', '', '列御寇到齐国去，半路上又折了回来，遇上伯昏瞀人。伯昏瞀人问道：“什么事情使你又折了回来？”列御寇说：“我感到惊惶不安。”伯昏瞀人又问：“什么原因使你惊惶不安？”列御寇说：“我曾在十家卖饮料的店子里饮用，却有五家事先就给我送来。”伯昏瞀人说：“像这样的事，你怎么会惊惶不安呢？”列御寇说：“内心至诚却又未能从流俗中解脱出来，外部身形就会有所宣泄而呈现出神采；用外在的东西镇服人心，对自己的尊重胜过尊重年老的人，必然会招致祸患。那卖饮料的人只不过是为了卖掉饮用的羹汤，没有多少赢利，他们获利是很微薄的，他们预先送来饮料时的内心打算也是微不足道的，可是还如此地对待我，何况那大国的国君呢？国君亲身操劳于国家而才智耗尽于政事，他们定会把重任托付给我并检验我的功绩。我正因为这个缘故才惊惶不已。”伯昏瞀人说：“你的观察与分析实在是好啊！你安处自身吧，人们一定会归附于你了！”
没有多久伯昏瞀人前去看望列御寇，看见门外摆满了鞋子。伯昏瞀人面朝北方站着，竖着拐杖撑住下巴。站了一会儿，一句话也没说就走出去了。接待宾客的人员告诉了列御寇，列御寇提着鞋子，光着脚就跑了出来，赶到门口，说：“先生已经来了，竟不说一句批评指教的话吗？”伯昏瞀人说：“算了算了，我本来就告诉你说人们将会归附于你，果真都在归附你了。当初我曾责备过你让人们归附于你，而你却始终不能做到让人们不归附于你。你何必用显迹于外的做法让人感动而预先就表现得与众不同呢！必定是内心有所感动方才会动摇你的本性哩，而你又无可奈何。跟你交游的人又没有谁能提醒告诫你，他们的细巧迷惑的言辞，全是毒害人的；没有谁觉醒没有谁省悟，怎么能彼此相互审视详察！灵巧的人多劳累而聪慧的人多忧患，没有能耐的人也就没有什么追求，填饱肚子就自由自在地遨游，像没有缆索飘忽在水中的船只一样，这才是心境虚无而自由遨游的人。”
郑国有个名叫缓的人在裘氏地方吟咏诵读，只用了三年就成了儒生，像河水滋润沿岸的土地一样润泽着广远的地方，他的恩惠还施及三族，并且使他的弟弟成为墨家的学人。儒家、墨家不能相容而相互争辩，缓的父亲则站在墨家一边。过了十年缓愤而自杀，他的父亲梦见他说：“让你的儿子成为墨家，还是我的功劳。怎么不看看我的坟墓，我已变成秋天的柏树而结出了果实！”造物者所给予人们的，不会赋予人的才智和能力而是赋予人们的自然本性。缓的弟弟具备了墨家的禀赋因而能使他成为墨家学人。缓总认为自己有什么与众不同的地方才这样轻侮他的父亲，就跟齐人自以为挖井有功而与饮水的人抓扯扭打一样，看来如今社会上的人差不多都是像缓这样贪天之功以为己有的人。自以为生活中总是这样，有德行的人却并不知道这样的情况，更何况是有道的人啊！古时候人们称这种贪天之功的做法是违背自然规律而受到刑戮。
圣哲的人安于自然，却不适应人为的摆布；普通人习惯于人为的摆布，却不安于自然。
庄子说：“了解道容易，不去谈论却很困难。了解了道却不妄加谈论，这是通往自然的境界；了解了道却信口谈论，这是走向人为的尘世。古时候的人，体察自然而不追求人为。”
朱泙漫向支离益学习屠龙的技术，耗尽了千金的家产，三年后学成技术却没有什么机会可以施展这样的技巧。
圣哲的人对于必然的事物不与人持拗固执，所以总是没有争论；普通人却把非必然的东西看作必然，因而总是争论不休。曲从于纷争，总是因为一举一动都有所追求，纷争，依仗于它到头来只会自取灭亡。
世俗人的聪明作法，离不开赠与酬答，在浅薄的事情上耗费精神，一心想着兼济天下疏导万物，满以为这就可以达到混沌初开、物我相融的境界。像这样的人，早已被浩瀚的宇宙所迷惑，身形劳苦拘累却并不了解混沌初始的真谛。那些道德修养极高的人，让精神回归到鸿蒙初开的原始状态，甘愿休眠在没有任何有形事物的世界。像水流一样随顺无形，自然而然地流淌在清虚空寂的境域。可悲啊！世俗人把心思用在毫毛琐事上，却一点也不懂得宁静、自然和无为。
宋国有个叫做曹商的人，为宋王出使秦国。他前往秦国的时候，得到宋王赠与的数辆车子；秦王十分高兴，又加赐车辆一百乘。曹商回到宋国，见了庄子说：“身居偏僻狭窄的里巷，贫困到自己的编织麻鞋，脖颈干瘪面色饥黄，这是我不如别人的地方；一旦有机会使大国的国君省悟而随从的车辆达到百乘之多，这又是我超过他人之处。”庄子说：“听说秦王有病召请属下的医生，破出脓疮溃散疖子的人可获得车辆一乘，舔治痔疮的人可获得车辆五乘，凡是疗治的部位越是低下，所能获得的车辆就越多。你难道给秦王舔过痔疮吗，怎么获奖的车辆如此之多呢？你走开吧！”
鲁哀公向颜阖问道：“我想把仲尼任命为大臣，国家有希望了吧？”颜阖说：“危险了，实在是危险啊！仲尼正一心想着粉饰装扮，追求和讲习虚伪的言辞，把枝节看作是要旨，扭曲心性以夸示于民众却不知道全无一点诚信；让这样的做法承受于内心，并主宰着精神，怎么能够管理好人民！仲尼果真适合于你吗，还是他真的能够养育人民呢？你的考虑错误无疑了。现今让人民背离真情学习伪诈，这不是用来导引民众的办法，为后世子孙着想，不如早早放弃上述打算。孔丘是很难治理好国家的。”
施与别人恩惠却总忘不了让人回报，远不是自然对普天之下广泛而无私的赐予。施恩图报的行为商人都瞧不起，即使有什么事情必须与他交往，内心也是瞧不起的。
施加皮肉之刑的，不外乎是金属或木质的刑具；给内心世界带来惩罚的，则是自身的烦乱和行动的过失。小人受到皮肉之刑，是用刑具加以拷问；小人内心受到惩罚，则是阴气阳气郁积所造成的侵害。能够免于内外刑辱的，只有真人才可做到。
孔子说：“人心比山川还要险恶，比预测天象还要困难；自然界尚有春夏秋冬和早晚变化的一定周期，可是人却面容复杂多变情感深深潜藏。有的人貌似老实却内心骄溢，有的人貌似长者却心术不正，有的人外表拘谨内心急躁却通达事理，有的人外表坚韧却懈怠涣散，有的人表面舒缓而内心却很强悍。所以人们趋赴仁义犹如口干舌燥思饮泉水，而他们抛弃仁义也像是逃离炽热避开烈焰。因此君子总是让人远离自己任职而观察他们是否忠诚，让人就近办事而观察他们是否恭敬，让人处理纷乱事务观察他们是否有能力，对人突然提问观察他们是否有心智，交给期限紧迫的任务观察他们是否守信用，把财物托付给他们观察是否清廉，把危难告诉给他们观察是否持守节操，用醉酒的方式观察他们的仪态，用男女杂处的办法观察他们对待女色的态度。上述九种表现一一得到证验，不好的人也就自然挑捡出来。”
正考父首次被任命为士便逢人躬着背，再次任命为大夫便深深地弯着腰，第三次任命为卿更谦恭地俯下身子，总是让开大道顺着墙根快步急走，态度如此谦下谁还敢干出不轨之事！如果是凡夫俗子，首次任命为士就会傲慢矜持，再次任命为大夫就会在车上手舞足蹈，第三次任命为卿就要人呼叔称伯了，像这样谁还会成为唐尧、许由那样谦让的人呢？
最大的祸害莫过于有意培养德行而且有心眼，等到有了心眼就会以意度事主观臆断，而主观臆断必定导致失败。招惹凶祸的官能有心、耳、眼、舌、鼻五种，内心的谋虑则是祸害之首。什么叫做内心谋虑的祸害呢？所谓内心谋虑的祸害，是指自以为是而诋毁自己所不赞同的事情。
困厄窘迫源于以下八个方面的自恃与矜持，顺利通达基于以下三种情况的必然发展，就像身形必具六个脏腑一样。貌美、须长、高大、魁梧、健壮、艳丽、勇武、果敢，八项长处远远胜过他人，于是依恃傲人必然导致困厄窘迫。因循顺应、俯仰随人、困厄怯弱而又态度谦下，三种情况都能遇事通达。自恃聪明炫耀于外，勇猛躁动必多怨恨，倡导仁义必多责难。通晓生命实情的人心胸开阔，通晓真知的人内心虚空豁达，通晓长寿之道的人随顺自然，通晓寿命短暂之理的人也能随遇而安。
有个拜会过宋王的人，宋王赐给他车马十乘，依仗这些车马在庄子面前炫耀。庄子说：“河上有一个家庭贫穷靠编织苇席为生的人家，他的儿子潜入深渊，得到一枚价值千金的宝珠，父亲对儿子说：‘拿过石块来锤坏这颗宝珠！价值千金的宝珠，必定出自深深的潭底黑龙的下巴下面，你能轻易地获得这样的宝珠，一定是正赶上黑龙睡着了。倘若黑龙醒过来，你还想活着回来吗？’如今宋国的险恶，远不只是深深的潭底；而宋王的凶残，也远不只是黑龙那样。你能从宋王那里获得十乘车马，也一定是遇上宋王睡着了。倘若宋王一旦醒过来，你也就必将粉身碎骨了”。
有人向庄子行聘。庄子答复他的使者说：“你见过那准备用作祭祀的牛牲吗？用织有花纹的锦绣披着，给它吃草料和豆子，等到牵着进入太庙杀掉用于祭祀，就是想要做个没人看顾的小牛，难道还可能吗？”
庄子快要死了，弟子们打算用很多的东西作为陪葬。庄子说：“我把天地当作棺椁，把日月当作连璧，把星辰当作珠玑，万物都可以成为我的陪葬。我陪葬的东西难道还不完备吗？哪里用得着再加上这些东西！”弟子说：“我们担忧乌鸦和老鹰啄食先生的遗体。”庄子说：“弃尸地面将会被乌鸦和老鹰吃掉，深埋地下将会被蚂蚁吃掉，夺过乌鸦老鹰的吃食再交给蚂蚁，怎么如此偏心！”
用偏见去追求均平，这样的均平绝对不是自然的均平；用人为的感应去应验外物，这样的应验绝不是自然的感应。自以为明智的人只会被外物所驱使，精神世界完全超脱于物外的人才会自然地感应。自以为明智的人早就比不上精神世界完全超脱的人，可是愚昧的人还总是自恃偏见而沉溺于世俗和人事，他们的功利只在于追求身外之物，这不很可悲吗！', NULL, '', 'indent', 1524912909, '5ae3e210ac502e00625fee89', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637426, '庄子 · 杂篇 · 天下', NULL, 8, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%84%E5%AD%90%C2%B7%E6%9D%82%E7%AF%87%C2%B7%E5%A4%A9%E4%B8%8B/10194567?fr=aladdin', '', '天下之治方术者多矣，皆以其有为不可加矣！古之所谓道术者，果恶乎在？曰：“无乎不在。”曰：“神何由降？明何由出？”“圣有所生，王有所成，皆原于一。”不离于宗，谓之天人；不离于精，谓之神人；不离于真，谓之至人。以天为宗，以德为本，以道为门，兆于变化，谓之圣人；以仁为恩，以义为理，以礼为行，以乐为和，熏然慈仁，谓之君子；以法为分，以名为表，以参为验，以稽为决，其数一二三四是也，百官以此相齿；以事为常，以衣食为主，蕃息畜藏，老弱孤寡为意，皆有以养，民之理也。古之人其备乎！配神明，醇天地，育万物，和天下，泽及百姓，明于本数，系于末度，六通四辟，小大精粗，其运无乎不在。其明而在数度者，旧法、世传之史尚多有之；其在于《诗》、《书》、《礼》、《乐》者，邹鲁之士、缙绅先生多能明之。《诗》以道志，《书》以道事，《礼》以道行，《乐》以道和，《易》以道阴阳，《春秋》以道名分。其数散于天下而设于中国者，百家之学时或称而道之。
天下大乱，贤圣不明，道德不一。天下多得一察焉以自好。譬如耳目鼻口，皆有所明，不能相通。犹百家众技也，皆有所长，时有所用。虽然，不该不遍，一曲之士也。判天地之美，析万物之理，察古人之全。寡能备于天地之美，称神明之容。是故内圣外王之道，暗而不明，郁而不发，天下之人各为其所欲焉以自为方。悲夫！百家往而不反，必不合矣！后世之学者，不幸不见天地之纯，古人之大体。道术将为天下裂。
不侈于后世，不靡于万物，不晖于数度，以绳墨自矫，而备世之急。古之道术有在于是者，墨翟、禽滑厘闻其风而说之。为之大过，已之大顺。作为《非乐》，命之曰《节用》。生不歌，死无服。墨子泛爱兼利而非斗，其道不怒。又好学而博，不异，不与先王同，毁古之礼乐。黄帝有《咸池》，尧有《大章》，舜有《大韶》，禹有《大夏》，汤有《大濩》，文王有辟雍之乐，武王、周公作《武》。古之丧礼，贵贱有仪，上下有等。天子棺椁七重，诸侯五重，大夫三重，士再重。今墨子独生不歌，死不服，桐棺三寸而无椁，以为法式。以此教人，恐不爱人；以此自行，固不爱己。未败墨子道。虽然，歌而非歌，哭而非哭，乐而非乐，是果类乎？其生也勤，其死也薄，其道大觳。使人忧，使人悲，其行难为也。恐其不可以为圣人之道，反天下之心。天下不堪。墨子虽独能任，奈天下何！离于天下，其去王也远矣！墨子称道曰：“昔禹之湮洪水，决江河而通四夷九州也。名山三百，支川三千，小者无数。禹亲自操橐耜而九杂天下之川。腓无胈，胫无毛，沐甚雨，栉疾风，置万国。禹大圣也，而形劳天下也如此。”使后世之墨者，多以裘褐为衣，以屐蹻为服，日夜不休，以自苦为极，曰：“不能如此，非禹之道也，不足谓墨。”相里勤之弟子，五侯之徒，南方之墨者若获、已齿、邓陵子之属，俱诵《墨经》，而倍谲不同，相谓别墨。以坚白同异之辩相訾，以奇偶不仵之辞相应，以巨子为圣人。皆愿为之尸，冀得为其后世，至今不决。墨翟、禽滑厘之意则是，其行则非也。将使后世之墨者，必以自苦腓无胈、胫无毛相进而已矣。乱之上也，治之下也。虽然，墨子真天下之好也，将求之不得也，虽枯槁不舍也，才士也夫！
不累于俗，不饰于物，不苟于人，不忮于众，愿天下之安宁以活民命，人我之养，毕足而止，以此白心。古之道术有在于是者，宋钘、尹文闻其风而悦之。作为华山之冠以自表，接万物以别宥为始。语心之容，命之曰“心之行”。以聏合欢，以调海内。请欲置之以为主。见侮不辱，救民之斗，禁攻寝兵，救世之战。以此周行天下，上说下教。虽天下不取，强聒而不舍者也。故曰：上下见厌而强见也。虽然，其为人太多，其自为太少，曰：“请欲固置五升之饭足矣。”先生恐不得饱，弟子虽饥，不忘天下，日夜不休。曰：“我必得活哉！”图傲乎救世之士哉！曰：“君子不为苛察，不以身假物。”以为无益于天下者，明之不如己也。以禁攻寝兵为外，以情欲寡浅为内。其小大精粗，其行适至是而止。
公而不党，易而无私，决然无主，趣物而不两，不顾于虑，不谋于知，于物无择，与之俱往。古之道术有在于是者，彭蒙、田骈、慎到闻其风而悦之。齐万物以为首，曰：“天能覆之而不能载之，地能载之而不能覆之，大道能包之而不能辩之。”知万物皆有所可，有所不可。故曰：“选则不遍，教则不至，道则无遗者矣。”是故慎到弃知去己，而缘不得已。泠汰于物，以为道理。曰：“知不知，将薄知而后邻伤之者也。”謑髁无任，而笑天下之尚贤也；纵脱无行，而非天下之大圣；椎拍輐断，与物宛转；舍是与非，苟可以免。不师知虑，不知前后，魏然而已矣。推而后行，曳而后往。若飘风之还，若羽之旋，若磨石之隧，全而无非，动静无过，未尝有罪。是何故？夫无知之物，无建己之患，无用知之累，动静不离于理，是以终身无誉。故曰：“至于若无知之物而已，无用贤圣。夫块不失道。”豪桀相与笑之曰：“慎到之道，非生人之行，而至死人之理。”适得怪焉。田骈亦然，学于彭蒙，得不教焉。彭蒙之师曰：“古之道人，至于莫之是、莫之非而已矣。其风囗窢然，恶可而言。”常反人，不见观，而不免于魭断。其所谓道非道，而所言之韪不免于非。彭蒙、田骈、慎到不知道。虽然，概乎皆尝有闻者也。
以本为精，以物为粗，以有积为不足，澹然独与神明居。古之道术有在于是者，关尹、老聃闻其风而悦之。建之以常无有，主之以太一。以濡弱谦下为表，以空虚不毁万物为实。关尹曰：“在己无居，形物自著。”其动若水，其静若镜，其应若响。芴乎若亡，寂乎若清。同焉者和，得焉者失。未尝先人而常随人。老聃曰：“知其雄，守其雌，为天下溪；知其白，守其辱，为天下谷。”人皆取先，己独取后。曰：“受天下之垢”。人皆取实，己独取虚。“无藏也故有余”。岿然而有余。其行身也，徐而不费，无为也而笑巧。人皆求福，己独曲全。曰：“苟免于咎”。以深为根，以约为纪。曰：“坚则毁矣，锐则挫矣”。常宽容于物，不削于人。虽未至于极，关尹、老聃乎，古之博大真人哉！
寂漠无形，变化无常，死与？生与？天地并与？神明往与？芒乎何之？忽乎何适？万物毕罗，莫足以归。古之道术有在于是者，庄周闻其风而悦之。以谬悠之说，荒唐之言，无端崖之辞，时恣纵而不傥，不奇见之也。以天下为沈浊，不可与庄语。以卮言为曼衍，以重言为真，以寓言为广。独与天地精神往来，而不敖倪于万物。不谴是非，以与世俗处。其书虽瑰玮，而连犿无伤也。其辞虽参差，而諔诡可观。彼其充实，不可以已。上与造物者游，而下与外死生、无终始者为友。其于本也，弘大而辟，深闳而肆；其于宗也，可谓稠适而上遂矣。虽然，其应于化而解于物也，其理不竭，其来不蜕，芒乎昧乎，未之尽者。
惠施多方，其书五车，其道舛驳，其言也不中。历物之意，曰：“至大无外，谓之大一；至小无内，谓之小一。无厚，不可积也，其大千里。天与地卑，山与泽平。日方中方睨，物方生方死。大同而与小同异，此之谓‘小同异’；万物毕同毕异，此之谓‘大同异’。南方无穷而有穷。今日适越而昔来。连环可解也。我知天之中央，燕之北、越之南是也。泛爱万物，天地一体也。”惠施以此为大，观于天下而晓辩者，天下之辩者相与乐之。卵有毛。鸡三足。郢有天下。犬可以为羊。马有卵。丁子有尾。火不热。山出口。轮不蹍地。目不见。指不至，至不绝。龟长于蛇。矩不方，规不可以为圆。凿不围枘。飞鸟之景未尝动也。镞矢之疾，而有不行、不止之时。狗非犬。黄马骊牛三。白狗黑。孤驹未尝有母。一尺之棰，日取其半，万世不竭。辩者以此与惠施相应，终身无穷。桓团、公孙龙辩者之徒，饰人之心，易人之意，能胜人之口，不能服人之心，辩者之囿也。惠施日以其知与之辩，特与天下之辩者为怪，此其柢也。然惠施之口谈，自以为最贤，曰：“天地其壮乎，施存雄而无术。”南方有倚人焉，曰黄缭，问天地所以不坠不陷，风雨雷霆之故。惠施不辞而应，不虑而对，遍为万物说。说而不休，多而无已，犹以为寡，益之以怪，以反人为实，而欲以胜人为名，是以与众不适也。弱于德，强于物，其涂隩矣。由天地之道观惠施之能，其犹一蚊一虻之劳者也。其于物也何庸！夫充一尚可，曰愈贵，道几矣！惠施不能以此自宁，散于万物而不厌，卒以善辩为名。惜乎！惠施之才，骀荡而不得，逐万物而不反，是穷响以声，形与影竞走也，悲夫！', '位于《庄子·杂篇》，以“天下”为题。全篇分七段，是记录先秦诸子百家历史渊源，来龙去脉。评价主要思想，并且加以批评的总结性的论文。作者据民国学者考证，当为战国时期晚期的庄子后学。', '', '天下搞学术的人很多，都认为自己的学问达到了顶峰。古代所谓的道术，究竟在哪里？回答说：“无所不在。”问：“神由何而降？明从何而生？”回答说：“神圣自有其由来，王业自有其成因，都渊源于一。”
不离根本，称为天人。不离精纯，称为神人。不离本真，称为至人。以天为宰，以德为根本，以道为门径，能够预示变化，称为圣人。以仁布施恩惠，以义作为道理，以礼规范行为，以乐调和性情，温和慈爱，称为君子。以法律为尺度，以名号为标志，以比较为验证，以考核来判断，等级之数像一二三四那样明白，百官以此为序列，以职事为常务，以衣食为主旨，生产储藏，关心老弱孤寡，使其皆有所意养，这是养民的常理。
古代的圣人是很完备的啊！合于神明，效法自然，养育万物，泽及百姓，以天道为根本，以法度为末节，六合通达而四时顺畅，无论小大精粗，其作用无所不在。古时候的道术和法规制度，很多还保存在传世的史书中。保存《诗》《书》《礼》《乐》中的，邹鲁一带的学者和缙绅先生们大都知晓。《诗》用来表达志，《书》用来记载事情，《礼》用来规范行为。《乐》用来调和，《易》用来说明阴阳，《春秋》用来正名分。其散布于天下百设立于中国的，百家之学还常常引用它。
天下大乱，贤王不显，道德分岐，天下人多各得一孔之见而自我欣赏。譬如耳目鼻口，它们各有其功能，但却不能互相通用。犹如百家众技，各有所长，时有所用。虽然如此，但不完备和全面，都是孤陋寡闻的人。割裂天地的完美，离析万物之理，把古人完美的道德弄得支离破碎，很少能具备天地的完美，相称于神明之容。所以，内圣外王之道暗而不明，抑郁而不发挥，天下的人各尽所欲而自为方术。可悲啊！百家各行其道而不回头，必定不能相合。后世的学者，不幸不能见到天地的纯真和古人的全貌，道术将被天下所割裂！
不以奢侈影响后世，不糜费万物，不炫耀礼法，用规矩自我勉励，以应付社会的危难，这是古代道术的内涵之一。墨翟、禽滑厘对这种道术很喜欢，但他们实行得太过分，局限性太大。提倡非乐，主张节用，生不作乐，死不服丧。墨子倡导博爱兼利而反对战争，主张和睦相处；又好学而渊博，不立异，不与先王相同，毁弃古代的礼乐。
黄帝有《咸池》之乐，尧有《大章》之乐，舜有《大韶》之乐，禹有《大夏》之乐，汤有《大蓡》之乐，文王有《辟雍》之乐，武王、周公作《武》乐。古代的丧礼，贵贱有仪法，上下有等级，天子的棺椁七层，诸侯五层，大夫三层，士两层。现在墨子独自主张生不歌乐，死不服丧，只用3寸厚的桐木棺而没有椁，作为标准。以此来教导人，恐怕不是爱人之道；自己去实行，实在是不爱惜自己。墨子的学说尽管是成立的，然而应该歌唱而不歌唱，应该哭泣而不哭泣，应该作乐而不作乐，这合乎人情常理吗？生前辛勤劳苦，实行起来简单薄葬，这种主张太苛刻了。使人忧劳，使人悲苦，实行起来是很困难的，恐怕不能够成为圣人之道，违反了天下人的心愿，天下人是不堪忍受的。墨子虽然独自能够做到，但对天下的人却无可奈何！背离了天下的人，也就远离了王道。
墨子称道说：“从前禹治理洪水，疏异江河而沟通四夷九州，大川三百，支流三千，小河无数。禹亲自持筐操铲劳作，汇合天下的河川，辛苦得连腿上的汗毛都磨光了，风里来雨里去，终于安定了天下。禹是大圣人，为了天下还如此劳苦。”从而使后世的墨者，多用兽皮粗布为衣，穿着木屐草鞋，白天黑夜都不休息，以自苦为准则，并说：“不能这样，就不是禹之道，不足以称为墨者。”
后世墨家学人相里勤和他的弟子五侯之流，南方的墨家苦获与已齿，还有邓陵子一类的人，都口诵《墨经》，却违背了墨家的宗旨，相互指责对方不是正统的墨家。他们用“坚白”、“同异”等话题彼此争辩相互诋毁，用奇数偶数不会一致的言辞相互应答，把一时推举出来的首领看作是圣人，全都乐意敬重他为领袖，希望能成为墨家学派的后继人，而且至今各派之间仍争论不休。
墨翟、禽滑厘的用意是很好的，具体做法却太过分。这将使后世的墨者，以极端劳苦的方式互相竞进。这种做法乱国有余，治国不足。尽管如此，墨子还是真心爱天下的，这样的人实在是难以求得，即使辛苦得形容枯槁也不舍弃自己的主张，真是有才之士啊！
不为世俗牵累，不用外物矫饰，不苛求于人，不与众人发生矛盾，希望天下安宁使人民活命，生活上以饱暖为满足，以此来表白心愿，这是古代道术的内涵之一。宋鈃、尹文对这种道术很喜欢，制作了形状像华山一样的帽子以表示上下均平主张，应接万物以不带偏见为先；谈论内心的思维，称之为心理活动，以柔和的态度投合别人的喜欢，以调和天下，希望树立上述主张作为行动的主导思想。受到欺侮不以为耻辱，调解人民的争斗，禁止攻伐平息干戈，将天下从战火中拯救出来。用这种主张周行天下，但他们仍然不停地对劝说，所以说人们都讨厌而他们还是硬要宣扬自己的主张。
尽管如此，他们还是替别人考虑得太多，为自己打算得太少，说：“我们只想要5升米的饭就够了。”不仅先生们吃不饱，弟子们也常常处在饥饿之中，但他们仍然不忘天下，日夜不休，说：“君子不苛刻计较，不使自身被外物所利用。”认为对天下没有益处的，与其提示它不如禁止它。以禁攻息兵为外在活动，以清心寡欲为内在修养，无论从大的方面说还是从细微的方面说，他们的所为也就到些为止了。
公正而不阿党，平易而无偏私，排除主观的先入之见，随物变化而不三心二意，没有顾虑，不求智谋，对万物毫无选择地随顺，和它一起变化，这是古代道术的内涵之一。彭蒙、田骈、慎到对这种道术很喜欢，以齐同万物为首要，说：“天能覆盖万物却不能承载，地能承载万物却不能覆盖，大道能包容万物却不能分辨。”知道万物都有所能，有所不能，所以说：“选择则不普遍，教导则有所不及，大道则无所遗漏。”
所以慎到抛弃智慧去除己见而随任于不得已，听任于物作为道理，他说：“强求知其所不知，就会为知所迫而受到损伤。”随便任用人，而讥笑天下推崇贤人；放任不羁不拘形迹，而非议天下的大圣。刑罚之轻重，随着事态的发展而相应地变化，抛弃了是非，才可以免于刑罚。不依赖智巧谋虑，不瞻前顾后，巍然独立。推动而往前走，拖拉而向后退，像飘风的往返，像羽毛的飞旋，像磨石的转动，完美而无错，动静适度而无过失，未曾有罪。这是什么原因，没有知觉的东西，就不会有标榜自己的忧患，不会有运用智谋的牵累，动静合于自然之理，所以终生不会受到毁誉。所以说：“达到像没有知觉的东西就行了，不需要圣贤，土块不会失于道。”豪杰们相互嘲笑他说：“慎到的道对活人没有用而只适用于死人，实在怪异。”
田骈也是这样，受学于彭蒙，得到不言之教。彭蒙的老师说：“古时候得道的人，达到了无所谓是非的境界。他们的道术像风吹过一样迅速，怎么能够用语言表达出来呢？”常常违反人意，不受人们所尊敬，仍不免于随物变化。他们所说的道并不是直正的道。然而，他们都还大概地听闻过一点道。
以无形无为的道为精微，以有形有为的物为粗鄙，因为有所积蓄而易生不满足之心，恬谈地独自与神明共处，这是古代道术的内涵之一。关尹、老聃对这种道术很喜欢，主张建立在常无与常有的基础上，以太一为核心，以柔弱谦下为外表，以空虚不毁伤万物为实质。
关尹说：“自己不存私意，有形之物各自彰显。动如流水，静如平镜，反应如回响。恍恍惚惚如无有，寂静如清虚。相同则和谐，有得则有失。未曾争先而常常随顺别人。”
老聃说：“知道雄强，持守雌柔，愿成为天下的沟壑；知道明亮，持守暗昧，愿成为天下的山谷。”人人都争先，独自甘愿居后，说承受天下的垢辱；人人都务实，独自甘愿守虚，不使敛藏所以处处显得有余，多如高山堆积。他立身行事，从容不迫，无为而嘲笑机巧；人人都求福，独自甘愿委曲求全，说姑且免于受罪。以深藏为根本，以俭约为纲纪，说坚硬的易于毁坏，锐利的易于挫折。常常宽容待物，从不侵削别人，可以说达到了顶点。
关尹、老聃啊！真是古代的博大真人！
寂寞无形，变化无常，死死生生，与天地并存，与神明同往！茫然何往，忽然何去，包罗万物，不知归属，这是古代道术的内涵之一。庄子对这种道术很喜欢，以虚远不可捉模的理论，广大不可测度的言论，不着边际的言辞，放纵而不拘执，不持一端之见。认为天下人沉湎于物欲而不知觉醒，不能讲庄重的与之讲话，以自然随意的话来推衍，借重先哲时贤之言来使人相信，以寄寓之言拓展胸臆与思想。独自与天地精神往来而不傲视万物，不拘泥于是非，与世俗相处。他的书虽然奇伟却宛转连缀无伤宏旨，言辞虽然变化多端却奇异引人入胜。他内心充实而思想奔放，上与造物者同游，下与忘却死生不分终始的人为友。他论述道的根本，博大而通达，深广而畅达；他论述道的宗旨，和谐妥贴而上达天意。然而，他对于事物变化的反应和解释，没有止境，不离于道，茫然暗昧，未能穷尽。
惠施的学问广博，他的书多达五车，道术杂乱无章，言辞多有不当。他分析事物之一，说：“大到极点而没有边际的，称为‘大一’；小到极点而没有内核的，称为‘小一’。没有厚度，不可累积，但能扩大到千里。天和地一样低，山和泽一样平。太阳刚刚正中的时候就偏斜，万物刚刚生出就向死亡转化。大同和小同相差异，这叫‘小同异’；万物完全相同也完全相异，这叫‘大同异’。南方既没有穷尽也有穷尽，今天到越国去而昨天已来到。连环可以解开。我所知的天下的中央，在燕国之北越国之南。泛爱万物，天地合为一体。”
惠施认为这些是大道理，炫耀于天下而引导辩士，天下的辩士也乐于和他辩论。鸡蛋有毛；鸡有三只脚；郢都包有天下；犬可以变为羊；马有卵；青蛙有尾巴；火不热；山有口；车轮不着地；眼睛看不见东西；物指的概念不相称，相称也没有止境；龟比蛇长；矩不方，规划出的不圆；凿孔不能围住榫头；飞鸟的影子未曾移动；疾飞的箭头有不走也有不停的时候；狗不是犬；黄马、骊牛是三个；白狗是黑的；孤驹不曾有母；一尺长的木棍，每天截掉一半，永远也截不完。辩士们用这些辩题与惠施相辩论，终身无穷。
桓团、公孙龙这些好辩之徒，迷惑人心，改变人意，能够用口舌战胜人，却不能服人之心，这是辩者的局限。惠旆每天靠他的智慧与人辩论，专门和天下的辩士一起制造怪异之说，这就是他们的根本。
然而惠施口若悬河，自认为最能干，说天地果真就伟大吗！惠施有雄心而没有道术。南方有个名叫黄缭的怪异之人，问天地为什么不坠不陷，风雨雷霆是怎么回事。惠施毫不推辞地接受提问，不假思索地应对，广泛解说天地万物，滔滔不绝，没完没了，还嫌说得太少，又增加了一些怪异的说法。把违反人之常情的事说成是真实的，想通过辩赢别人而获取名声，所以与众不合。轻视道德修养，努力追逐外物，他走的是歪门邪道。从天地之道来看惠施的才能，他就像一只蚊虫那样徒劳。对于万物有什么用处！做为一家之说还可以，如果能进一步奠崇大道，那就差不多了！惠施不安于道，分散心思于万物而乐上不疲，终于以善辩出名。可惜啊！惠施的才能，放荡而不行于正道，追逐万物而不知回头，这就像用声音去追逐回响，用形体和影子况走一样。可悲啊！', NULL, '', 'indent', 1524912845, '5ae3e247ee920a00430a2d39', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637432, '史记 · 十二本纪 · 五帝本纪', NULL, 143, 139, 0, 1, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E4%BA%94%E5%B8%9D%E6%9C%AC%E7%BA%AA/2390002?fr=aladdin', '', '黄帝者，少典之子，姓公孙，名曰轩辕。生而神灵，弱而能言，幼而徇齐，长而敦敏，成而聪明。
轩辕之时，神农氏世衰。诸侯相侵伐，暴虐百姓，而神农氏弗能征。于是轩辕乃习用干戈，以征不享，诸侯咸来宾从。而蚩尤最为暴，莫能伐。炎帝欲侵陵诸侯，诸侯咸归轩辕。轩辕乃修德振兵，治五气，蓺五种，抚万民，度四方，教熊罴貔貅貙虎，以与炎帝战于阪泉之野。三战，然后得其志。蚩尤作乱，不用帝命。于是黄帝乃徵师诸侯，与蚩尤战于涿鹿之野，遂禽杀蚩尤。而诸侯咸尊轩辕为天子，代神农氏，是为黄帝。天下有不顺者，黄帝从而征之，平者去之，披山通道，未尝宁居。
东至于海，登丸山，及岱宗。西至于空桐，登鸡头。南至于江，登熊、湘。北逐荤粥，合符釜山，而邑于涿鹿之阿。迁徙往来无常处，以师兵为营卫。官名皆以云命，为云师。置左右大监，监于万国。万国和，而鬼神山川封禅与为多焉。获宝鼎，迎日推策。举风后、力牧、常先、大鸿以治民。顺天地之纪、幽明之占、死生之说、存亡之难。时播百谷草木，淳化鸟兽虫蛾，旁罗日月星辰水波土石金玉，劳勤心力耳目，节用水火材物。有土德之瑞，故号黄帝。
黄帝二十五子，其得姓者十四人。
黄帝居轩辕之丘，而娶于西陵之女，是为嫘祖。嫘祖为黄帝正妃，生二子，其后皆有天下：其一曰玄嚣，是为青阳，青阳降居江水；其二曰昌意，降居若水。昌意娶蜀山氏女，曰昌仆，生高阳，高阳有圣德焉。黄帝崩，葬桥山。其孙昌意之子高阳立，是为帝颛顼也。
帝颛顼高阳者，黄帝之孙而昌意之子也。静渊以有谋，疏通而知事；养材以任地，载时以象天，依鬼神以制义，治气以教化，絜诚以祭祀。北至于幽陵，南至于交阯，西至于流沙，东至于蟠木。动静之物，大小之神，日月所照，莫不砥属。
帝颛顼生子曰穷蝉。颛顼崩，而玄嚣之孙高辛立，是为帝喾。
帝喾高辛者，黄帝之曾孙也。高辛父曰蟜极，蟜极父曰玄嚣，玄嚣父曰黄帝。自玄嚣与蟜极皆不得在位，至高辛即帝位。高辛于颛顼为族子。
高辛生而神灵，自言其名。普施利物，不于其身。聪以知远，明以察微。顺天之义，知民之急。仁而威，惠而信，修身而天下服。取地之财而节用之，抚教万民而利诲之，历日月而迎送之，明鬼神而敬事之。其色郁郁，其德嶷嶷。其动也时，其服也士。帝喾溉执中而遍天下，日月所照，风雨所至，莫不从服。
帝喾娶陈锋氏女，生放勋。娶娵訾氏女，生挚。帝喾崩，而挚代立。帝挚立，不善。而弟放勋立，是为帝尧。
帝尧者，放勋。其仁如天，其知如神。就之如日，望之如云。富而不骄，贵而不舒。黄收纯衣，彤车乘白马。能明驯德，以亲九族。九族既睦，便章百姓。百姓昭明，合和万国。
乃命羲、和，敬顺昊天，数法日月星辰，敬授民时。分命羲仲，居郁夷，曰旸谷。敬道日出，便程东作。日中，星鸟，以殷中春。其民析，鸟兽字微。申命羲叔，居南交。便程南为，敬致。日永，星火，以正中夏。其民因，鸟兽希革。申命和仲，居西土，曰昧谷。敬道日入，便程西成。夜中，星虚，以正中秋。其民夷易，鸟兽毛毨。申命和叔，居北方，曰幽都。便在伏物。日短，星昴，以正中冬。其民燠，鸟兽氄毛。岁三百六十六日，以闰月正四时。信饬百官，众功皆兴。
尧曰：「谁可顺此事？」放齐曰：「嗣子丹朱开明。」尧曰：「吁！顽凶，不用。」尧又曰：「谁可者？」驩兜曰：「共工旁聚布功，可用。」尧曰：「共工善言，其用僻，似恭漫天，不可。」尧又曰：「嗟！四岳：汤汤洪水滔天，浩浩怀山襄陵，下民其忧，有能使治者？」皆曰鲧可。尧曰：「鲧负命毁族，不可。」岳曰：「异哉，试不可用而已。」尧于是听岳用鲧。九载，功用不成。
尧曰：「嗟！四岳：朕在位七十载，汝能庸命，践朕位？」岳应曰：「鄙德忝帝位。」尧曰：「悉举贵戚及疏远隐匿者。」众皆言于尧曰：「有矜在民闲，曰虞舜。」尧曰：「然，朕闻之。其何如？」岳曰：「盲者子。父顽，母嚚，弟傲，能和以孝，烝烝治，不至奸。」尧曰：「吾其试哉。」于是尧妻之二女，观其德于二女。舜饬下二女于妫汭，如妇礼。尧善之，乃使舜慎和五典，五典能从。乃遍入百官，百官时序。宾于四门，四门穆穆，诸侯远方宾客皆敬。尧使舜入山林川泽，暴风雷雨，舜行不迷。尧以为圣，召舜曰：「女谋事至而言可绩，三年矣。女登帝位。」舜让于德，不怿。正月上日，舜受终于文祖。文祖者，尧大祖也。
于是帝尧老，命舜摄行天子之政，以观天命。舜乃在璿玑玉衡，以齐七政。遂类于上帝，禋于六宗，望于山川，辩于群神。揖五瑞，择吉月日，见四岳诸牧，班瑞。岁二月，东巡狩，至于岱宗，祡，望秩于山川。遂见东方君长，合时月正日，同律度量衡，修五礼五玉三帛二生一死为挚，如五器，卒乃复。五月，南巡狩；八月，西巡狩；十一月，北巡狩：皆如初。归，至于祖祢庙，用特牛礼。五岁一巡狩，群后四朝。遍告以言，明试以功，车服以庸。肇十有二州，决川。象以典刑，流宥五刑，鞭作官刑，扑作教刑，金作赎刑。眚灾过，赦；怙终贼，刑。钦哉，钦哉，惟刑之静哉！
驩兜进言共工，尧曰不可，而试之工师，共工果淫辟。四岳举鲧治鸿水，尧以为不可，岳彊请试之，试之而无功，故百姓不便。三苗在江淮、荆州数为乱。于是舜归而言于帝，请流共工于幽陵，以变北狄；放驩兜于崇山，以变南蛮；迁三苗于三危，以变西戎；殛鲧于羽山，以变东夷：四罪而天下咸服。
尧立七十年得舜，二十年而老，令舜摄行天子之政，荐之于天。尧辟位凡二十八年而崩。百姓悲哀，如丧父母。三年，四方莫举乐，以思尧。尧知子丹朱之不肖，不足授天下，于是乃权授舜。授舜，则天下得其利而丹朱病；授丹朱，则天下病而丹朱得其利。尧曰「终不以天下之病而利一人」，而卒授舜以天下。尧崩，三年之丧毕，舜让辟丹朱于南河之南。诸侯朝觐者不之丹朱而之舜，狱讼者不之丹朱而之舜，讴歌者不讴歌丹朱而讴歌舜。舜曰：「天也夫！」而后之中国践天子位焉，是为帝舜。
虞舜者，名曰重华。重华父曰瞽叟，瞽叟父曰桥牛，桥牛父曰句望，句望父曰敬康，敬康父曰穷蝉，穷蝉父曰帝颛顼，颛顼父曰昌意：以至舜七世矣。自从穷蝉以至帝舜，皆微为庶人。
舜父瞽叟盲，而舜母死，瞽叟更娶妻而生象，象傲。瞽叟爱后妻子，常欲杀舜，舜避逃；及有小过，则受罪。顺事父及后母与弟，日以笃谨，匪有懈。
舜，冀州之人也。舜耕历山，渔雷泽，陶河滨，作什器于寿丘，就时于负夏。舜父瞽叟顽，母嚚，弟象傲，皆欲杀舜。舜顺适不失子道，兄弟孝慈。欲杀，不可得；即求，尝在侧。
舜年二十以孝闻。三十而帝尧问可用者，四岳咸荐虞舜，曰可。于是尧乃以二女妻舜以观其内，使九男与处以观其外。舜居妫汭，内行弥谨。尧二女不敢以贵骄事舜亲戚，甚有妇道。尧九男皆益笃。舜耕历山，历山之人皆让畔；渔雷泽，雷泽上人皆让居；陶河滨，河滨器皆不苦窳。一年而所居成聚，二年成邑，三年成都。尧乃赐舜絺衣与琴，为筑仓廪，予牛羊。瞽叟尚复欲杀之，使舜上涂廪，瞽叟从下纵火焚廪。舜乃以两笠自捍而下，去，得不死。后瞽叟又使舜穿井，舜穿井为匿空旁出。舜既入深，瞽叟与象共下土实井，舜从匿空出，去。瞽叟、象喜，以舜为已死。象曰：「本谋者象。」象与其父母分，于是曰：「舜妻尧二女与琴，象取之；牛羊仓廪，予父母。」象乃止舜宫居，鼓其琴。舜往见之。象鄂不怿，曰：「我思舜正郁陶！」舜曰：「然，尔其庶矣！」舜复事瞽叟，爱弟弥谨。于是尧乃试舜五典百官，皆治。
昔高阳氏有才子八人，世得其利，谓之「八恺」。高辛氏有才子八人，世谓之「八元」。此十六族者，世济其美，不陨其名。至于尧，尧未能举。舜举八恺，使主后土，以揆百事，莫不时序。举八元，使布五教于四方，父义，母慈，兄友，弟恭，子孝，内平外成。
昔帝鸿氏有不才子，掩义隐贼，好行凶慝，天下谓之浑沌。少暤氏有不才子，毁信恶忠，崇饰恶言，天下谓之穷奇。颛顼氏有不才子，不可教训，不知话言，天下谓之梼杌。此三族世忧之。至于尧，尧未能去。缙云氏有不才子，贪于饮食，冒于货贿，天下谓之饕餮。天下恶之，比之三凶。舜宾于四门，乃流四凶族，迁于四裔，以御螭魅，于是四门辟，言毋凶人也。
舜入于大麓，烈风雷雨不迷，尧乃知舜之足授天下。尧老，使舜摄行天子政，巡狩。舜得举，用事二十年，而尧使摄政。摄政八年而尧崩。三年丧毕，让丹朱，天下归舜。而禹、皋陶、契、后稷、伯夷、夔、龙、倕、益、彭祖自尧时而皆举用，未有分职。于是舜乃至于文祖，谋于四岳，辟四门，明通四方耳目，命十二牧论帝德，行厚德，远佞人，则蛮夷率服。舜谓四岳曰：「有能奋庸美尧之事者，使居官相事？」皆曰：「伯禹为司空，可美帝功。」舜曰：「嗟，然！禹，汝平水土，维是勉哉。」禹拜稽首，让于稷、契与皋陶。舜曰：「然，往矣。」舜曰：「弃，黎民始饥，汝后稷，播时百谷。」舜曰：「契，百姓不亲，五品不驯，汝为司徒，而敬敷五教，在宽。」舜曰：「皋陶，蛮夷猾夏，寇贼奸轨，汝作士，五刑有服，五服三就；五流有度，五度三居：维明能信。」舜曰：「谁能驯予工？」皆曰垂可。于是以垂为共工。舜曰：「谁能驯予上下草木鸟兽？」皆曰益可。于是以益为朕虞。益拜稽首，让于诸臣朱虎、熊罴。舜曰：「往矣，汝谐。」遂以朱虎、熊罴为佐。舜曰：「嗟！四岳，有能典朕三礼？」皆曰伯夷可。舜曰：「嗟！伯夷，以汝为秩宗，夙夜维敬，直哉维静絜。」伯夷让夔、龙。舜曰：「然。以夔为典乐，教稚子，直而温，宽而栗，刚而毋虐，简而毋傲；诗言意，歌长言，声依永，律和声，八音能谐，毋相夺伦，神人以和。」夔曰：「于！予击石拊石，百兽率舞。」舜曰：「龙，朕畏忌谗说殄伪，振惊朕众，命汝为纳言，夙夜出入朕命，惟信。」舜曰：「嗟！女二十有二人，敬哉，惟时相天事。」三岁一考功，三考绌陟，远近众功咸兴。分北三苗。
此二十二人咸成厥功：皋陶为大理，平，民各伏得其实；伯夷主礼，上下咸让；垂主工师，百工致功；益主虞，山泽辟；弃主稷，百谷时茂；契主司徒，百姓亲和；龙主宾客，远人至；十二牧行而九州莫敢辟违；唯禹之功为大，披九山，通九泽，决九河，定九州，各以其职来贡，不失厥宜。方五千里，至于荒服。南抚交阯、北发，西戎、析枝、渠廋、氐、羌，北山戎、发、息慎，东长、鸟夷，四海之内咸戴帝舜之功。于是禹乃兴九招之乐，致异物，凤皇来翔。天下明德皆自虞帝始。
舜年二十以孝闻，年三十尧举之，年五十摄行天子事，年五十八尧崩，年六十一代尧践帝位。践帝位三十九年，南巡狩，崩于苍梧之野。葬于江南九疑，是为零陵。舜之践帝位，载天子旗，往朝父瞽叟，夔夔唯谨，如子道。封弟象为诸侯。舜子商均亦不肖，舜乃豫荐禹于天。十七年而崩。三年丧毕，禹亦乃让舜子，如舜让尧子。诸侯归之，然后禹践天子位。尧子丹朱，舜子商均，皆有疆土，以奉先祀。服其服，礼乐如之。以客见天子，天子弗臣，示不敢专也。
自黄帝至舜、禹，皆同姓而异其国号，以章明德。故黄帝为有熊，帝颛顼为高阳，帝喾为高辛，帝尧为陶唐，帝舜为有虞。帝禹为夏后而别氏，姓姒氏。契为商，姓子氏。弃为周，姓姬氏。
太史公曰：学者多称五帝，尚矣。然尚书独载尧以来；而百家言黄帝，其文不雅驯，荐绅先生难言之。孔子所传宰予问五帝德及帝系姓，儒者或不传。余尝西至空桐，北过涿鹿，东渐于海，南浮江淮矣，至长老皆各往往称黄帝、尧、舜之处，风教固殊焉，总之不离古文者近是。予观春秋、国语，其发明五帝德、帝系姓章矣，顾弟弗深考，其所表见皆不虚。书缺有闲矣，其轶乃时时见于他说。非好学深思，心知其意，固难为浅见寡闻道也。余并论次，择其言尤雅者，故著为本纪书首。', '《五帝本纪》是西汉史学家司马迁创作的一篇文言文，收录于《史记》中。是《史记》的第一篇，记载的是远古传说中被后人尊为帝王的五个部落联盟首领——黄帝、颛顼（ZhuānXū）、帝喾（Kù）、尧、舜的事迹，同时也记录了当时部落之间频繁战争，部落联盟首领实行禅让制，远古初民战猛兽、治洪水、开良田、种嘉谷、观测天文、推算历法、谱制音乐舞蹈等多方面的情况。', '', '黄帝，是少典部族的子孙，姓公孙名叫轩辕。他一生下来，就很有灵性，出生不久就会说话，幼年时聪明机敏，长大后诚实勤奋，成年以后见闻广博，对事物看得清楚。
轩辕时代，神农氏的后代已经衰败，各诸侯互相攻战，残害百姓，而神农氏没有力量征讨他们。于是轩辕就习兵练武，去征讨那些不来朝贡的诸侯，各诸侯这才都来归从。而蚩尤在各诸侯中最为凶暴，没有人能去征讨他。炎帝想进攻欺压诸侯，诸侯都来归从轩辕。于是轩辕修行德业，整顿军旅，研究四时节气变化，种植五谷，安抚民众，丈量四方的土地，训练熊、罴、貔（pí）、貅（xiū）、貙（chū，）、虎等猛兽，跟炎帝在阪泉的郊野交战，先后打了几仗，才征服炎帝，如愿得胜。蚩尤发动叛乱，不听从黄帝之命。于是黄帝征调诸侯的军队，在涿鹿郊野与蚩尤作战，终于擒获并杀死了他。这样，诸侯都尊奉轩辕做天子，取代了神农氏，这就是黄帝。天下有不归顺的，黄帝就前去征讨，平定一个地方之后就离去，一路上劈山开道，从来没有在哪儿安宁地居住过。
黄帝往东到过东海，登上了丸山和泰山。往西到过空桐，登上了鸡头山。往南到过长江，登上了熊山、湘山。往北驱逐了荤粥（xūｎyù）部族，来到釜山与诸侯合验了符契，就在逐鹿山的山脚下建起了都邑。黄帝四处迁徙，没有固定的住处，带兵走到哪里，就在哪里设置军营以自卫。黄帝所封官职都用云来命名，军队号称云师。他设置了左右大监，由他们督察各诸侯国。这时，万国安定，因此，自古以来，祭祀鬼神山川的要数黄帝时最多。黄帝获得上天赐给的宝鼎，于是观测太阳的运行，用占卜用的蓍（shī）草推算历法，预知节气日辰。他任用风后、力牧、常先、大鸿等治理民众。黄帝顺应天地四时的规律，推测阴阳的变化，讲解生死的道理，论述存与亡的原因，按照季节播种百谷草木，驯养鸟兽蚕虫，测定日月星辰以定历法，收取土石金玉以供民用，身心耳目，饱受辛劳，有节度地使用水、火、木材及各种财物。他做天子有土这种属性的祥瑞征兆，土色黄，所以号称黄帝。
黄帝有二十五个儿子，其中建立自已姓氏的有十四人。
黄帝居住在轩辕山，娶西陵国的女儿为妻，这就是嫘祖。嫘祖是黄帝的正妃，生有两个儿子，他们的后代都领有天下：一个叫玄嚣，也就是青阳，青阳被封为诸侯，降居在江水；另一个叫昌意，也被封为诸侯，降居在若水。昌意娶了蜀山氏的女儿，名叫昌仆，生下高阳，高阳有圣人的品德。黄帝死后，埋葬在桥山，他的孙子，也就是昌意的儿子高阳即帝位，这就是颛顼帝。
颛顼帝高阳，是黄帝的孙子，昌意的儿子。他沉静稳练而有机谋，通达而知事理。他养殖各种庄稼牲畜以充分利用地力，推算四时节令以顺应自然，依顺鬼神以制定礼义，理顺四时五行之气以教化万民，洁净身心以祭祀鬼神。他往北到过幽陵，往南到过交阯，往西到过流沙，往东到过蟠木。各种动物植物，大神小神，凡是日月照临的地方，全都平定了，没有不归服的。
颛顼帝生的儿子叫穷蝉。颛顼死后，玄嚣的孙子高辛即位，这就是帝喾。
帝喾高辛，是黄帝的曾孙。高辛的父亲叫蟜极，蟜极的父亲叫玄嚣，玄嚣的父亲就是黄帝。玄嚣和蟜极都没有登上帝位，到高辛时才登上帝位。高辛是颛顼的侄子。
高辛生来就很有灵气，一出生就叫出了自己的名字。他普遍施予恩泽于众人而不及其自身。他耳聪目明，可以了解远处的情况，可以洞察细微的事理。他顺应上天的意旨，了解下民之所急。仁德而且威严，温和而且守信，修养自身，天下归服。他收取土地上的物产，俭节地使用；他抚爱教化万民，把各种有益的事教给他们；他推算日月的运行以定岁时节气，恭敬地迎送日月的出入；他明识鬼神，慎重地加以事奉。他仪表堂堂，道德高尚。他行动合乎时宜，服用如同士人。帝喾治民，像雨水浇灌农田一样不偏不倚，遍及天下，凡是日月照耀的地方，风雨所到的地方，没有人不顺从归服。
帝喾娶陈锋氏的女儿，生下放勋。娶娵訾（JūZī）氏的女儿，生下挚。帝喾死后，挚接替帝位。帝挚登位后，没有干出什么政绩，于是弟弟放勋登位。这就是帝尧。
帝尧，就是放勋。他仁德如天，智慧如神。接近他，就像太阳一样温暖人心；仰望他，就像云彩一般覆润大地。他富有却不骄傲，尊贵却不放纵。他戴的是黄色的帽子，穿的是黑色衣裳，朱红色的车子驾着白马。他能尊敬有善德的人，使同族九代相亲相爱。同族的人既已和睦，又去考察百官。百官政绩昭著，各方诸侯邦国都能和睦相处。
帝尧命令羲氏、和氏，遵循上天的意旨，根据日月的出没、星辰的位次，制定历法，谨慎地教给民众从事生产的节令。另外命令羲仲，住在郁夷，那个地方叫旸（yáng）谷，恭敬地迎接日出，分别步骤安排春季的耕作。春分日，白昼与黑夜一样长，朱雀七宿（xiù）中的星宿初昏时出现在正南方，据此来确定仲春之时。这时候，民众分散劳作，鸟兽生育交尾。又命令羲叔，住在南交，分别步骤安排夏季的农活儿，谨慎地干好。夏至日，白昼最长，苍龙七宿中的心宿（又称大火）初昏时出现在正南方，据此来确定仲夏之时。这时候，民众就居高处，鸟兽毛羽稀疏。又命令和仲，居住在西土，那地方叫做昧谷，恭敬地送太阳落下，有步骤地安排秋天的收获。秋分日，黑夜与白昼一样长，玄武七宿中的虚宿初昏时出现在正南方，据此来确定仲秋之时。这时候，民众移居平地，鸟兽再生新毛。又命令和叔，住在北方，那地方叫做幽都，认真安排好冬季的收藏。冬至日，白昼最短，白虎七宿中的昴（mǎo）宿初昏时出现在正南方，据此来确定仲冬之时。这时候，民众进屋取暖，鸟兽长满细毛。一年有三百六十六天，用置闰月的办法来校正春夏秋冬四季。帝尧真诚地告诫百官各守其职，各种事情都办起来了。
尧说：「谁可以继承我的这个事业？」放齐说：「你的儿子丹朱通达事理。」尧说：「哼！丹朱么，他这个人愚顽、凶恶，不能用。」尧又问道：「那么还有谁可以？」驩兜说：「共工广泛地聚集民众，做出了业绩，可以用。」尧说；「共工好讲漂亮话，用心不正，貌似恭敬，欺骗上天，不能用。」尧又问：「唉，四岳啊，如今洪水滔天，浩浩荡荡，包围了高山，漫上了丘陵，民众万分愁苦，谁可以派去治理呢？」大家都说鲧可以。尧说：「鲧违背天命，毁败同族，不能用。」四岳都说：「就任用他吧，试试不行，再把他撤掉。」尧因此听从了四岳的建议，任用了鲧。鲧治水九年，也没有取得成效。
尧说：「唉！四岳：我在位已经七十年了，你们谁能顺应天命，接替我的帝位？」四岳回答说；「我们的德行鄙陋得很，不敢玷污帝位。」尧说：「那就从所有同姓异姓远近大臣及隐居者当中推举吧。」大家都对尧说：「有一个单身汉流寓在民间，叫虞舜。」尧说：「对，我听说过，他这个人怎么样？」四岳回答说；「他是个盲人的儿子。他的父亲愚昧，母亲顽固，弟弟傲慢，而舜却能与他们和睦相处，尽孝悌之道，把家治理好，使他们不至于走向邪恶。」尧说：「那我就试试他吧。」于是尧把两个女儿嫁给他，从两个女儿身上观察他的德行。舜让她们降下尊贵之心住到妫（Guī）河边的家中去，遵守为妇之道。尧认为这样做很好，就让舜试任司徒之职，谨慎地理顺父义、母慈、兄友、弟恭、子孝这五种伦理道德，人民都遵从不违。尧又让他参与百官的事，百官的事因此变得有条不紊。让他在明堂四门接待宾客，四门处处和睦，从远方来的诸侯宾客都恭恭敬敬。尧又派舜进入山野丛林大川草泽，遇上暴风雷雨，舜也没有迷路误事。尧更认为他十分聪明，很有道德，把他叫来说道：「三年来，你做事周密，说了的话就能做到。现在你就登临天子位吧。」舜推让说自己的德行还不够，不愿接受帝位。正月初一，舜在文祖庙接受了尧的禅让。文祖也就是尧的太祖。
这时，尧年事已高，让舜代理天子之政事，借以观察他做天子是否合天意。舜于是通过观测北斗星，来考察日、月及金、木、水、火、土五星的运行是否有异常，接着举行临时仪式祭告上帝，用把祭品放在火上烧的仪式祭祀天地四时，用遥祭的仪式祭祀名山大川，又普遍地祭祀了各路神祗。他收集起公侯伯子男五等侯爵所持桓圭、信圭、躬圭、谷璧、蒲璧五种玉制符信，选择良月吉日，召见四岳和各州州牧，又颁发给他们。二月，舜去东方巡视，到泰山时，用烧柴的仪式祭祀东岳，用遥祭的仪式祭祀各地的名山大川。接着，他就召见东方各诸侯，协调校正四时节气、月之大小、日之甲乙，统一音律和长度、容量、重量的标准，修明吉、凶、宾、军、嘉五种礼仪，规定诸侯用五种圭壁、三种彩缯，卿大夫用羊羔、大雁二种动物，士用死雉作为朝见时的礼物，而五种圭璧，朝见典礼完毕以后仍还给诸侯。五月，到南方巡视；八月，到西方巡视；十一月，到北方巡视：都像起初到东方巡视时一样。回来后，告祭祖庙和父庙，用一头牛作祭品。以后每五年巡视一次，在其间的四年中，各诸侯国君按时来京师朝见。舜向诸侯们普遍地陈述治国之道，根据业绩明白地进行考察，根据功劳赐给车马衣服。舜开始把天下划分为十二个州，疏浚河川。规定根据正常的刑罚来执法，用流放的方法宽减刺字、割鼻、断足、阉割、杀头五种刑罚，官府里治事用鞭子施刑，学府教育用戒尺惩罚，罚以黄金可用作赎罪。因灾害而造成过失的，予以赦免；怙恶不悛、坚持为害的要施以刑罚。谨慎啊，谨慎啊，可要审慎使用刑罚啊！
驩兜曾举荐过共工，尧说「不行」，而驩兜还是试用他做工师，共工果然放纵邪僻。四岳曾推举鲧去治理洪水，尧说「不行」，而四岳硬说要试试看，试的结果是没有成效，所以百官都以为不适宜。三苗在江、淮流域及荆州一带多次作乱。这时舜巡视回来向尧帝报告，请求把共工流放到幽陵，以便改变北狄的风俗；把驩兜流放到崇山，以便改变南蛮的风俗；把三苗迁徙到三危山，以便改变西戎的风俗。把鲧流放到羽山，以便改变东夷的风俗：惩办了这四个罪人，天下人都悦服了。尧在位七十年得到舜，又过二十年因年老而告退，让舜代行天子政务，向上天推荐。尧让出帝位二十八年后逝世。百姓悲伤哀痛，如同死了生身父母一般。三年之内，四方各地没有人奏乐，为的是悼念帝尧。尧了解自己的儿子丹朱不贤，不配传给他天下，因此才姑且试着让给舜。让给舜，天下人就都得到利益而只对丹朱一人不利；传给丹朱，天下人就会遭殃而只有丹朱一人得到好处。尧说：「我毕竟不能使天下人受害而只让一人得利」，所以最终还是把天下传给了舜。尧逝世后，三年服丧完毕，舜把帝位让给丹朱，自己躲到了南河的南岸。诸侯前来朝觐的不到丹朱那里去却到舜这里来，打官司的也不去找丹朱却来找舜，歌颂功德的，不去歌颂丹朱却来歌颂舜。舜说「这是天意呀」，然后才到了京都，登上天子之位，这就是舜帝。
虞舜，名叫重华。重华的父亲叫瞽叟，瞽叟的父亲叫桥牛，桥牛的父亲叫句（Gōu）望，句望的父亲叫敬康，敬康的父亲叫穷蝉。穷蝉的父亲是颛顼帝，颛顼的父亲是昌意：从昌意至舜是七代了。自从穷蝉为帝之后一直到舜帝，中间几代地位低微，都是平民。
舜的父亲瞽叟是个瞎子，舜的生母死后，瞽叟又续娶了一个妻子生下了象，象桀骜不驯。瞽叟喜欢后妻的儿子，常常想把舜杀掉，舜都躲过了；赶上有点小错儿，就会遭到重罚。舜很恭顺地侍奉父亲、后母及后母弟，一天比一天地忠诚谨慎，没有一点懈怠。
舜，是冀州人。舜在历山耕过田，在雷泽打过鱼，在黄河岸边做过陶器，在寿丘做过各种家用器物，在负夏跑过买卖。舜的父亲瞽叟愚昧，母亲顽固，弟弟象桀骜不驯，他们都想杀掉舜。舜却恭顺地行事，从不违背为子之道，友爱兄弟，孝顺父母。他们想杀掉他的时候，就找不到他；而有事要找他的时候，他又总是在身旁侍候着。
舜二十岁时，就因为孝顺出了名。三十岁时，尧帝问谁可以治理天下，四岳全都推荐虞舜，说这个人可以。于是尧把两个女儿嫁给了舜来观察他在家的德行，让九个儿子和他共处来观察他在外的为人。舜居住在妫水岸边，他在家里做事更加谨慎。尧的两个女儿不敢因为自己出身高贵就傲慢地对待舜的亲属，很讲究为妇之道。尧的九个儿子也更加笃诚忠厚。舜在历山耕作，历山人都能互相推让地界；在雷泽捕鱼，雷泽的人都能推让便于捕鱼的位置；在黄河岸边制做陶器，那里就完全没有次品了。一年的功夫，他住的地方就成为一个村落，二年就成为一个小城镇，三年就变成大都市了。见了这些，尧就赐给舜一套细葛布衣服，给他一张琴，为他建造仓库，还赐给他牛和羊。瞽叟仍然想杀他，让舜登高去用泥土修补谷仓，瞽叟却从下面放火焚烧。舜用两个斗笠保护着自己，像长了翅膀一样跳下来，逃开了，才得以不死。后来瞽叟又让舜挖井，舜挖井的时候，在侧壁凿出一条暗道通向外边。舜挖到深处，瞽叟和象一起往下倒土填埋水井，舜从旁边的暗道出去，又逃开了。瞽叟和象很高兴，以为舜已经死了。象说：「最初出这个主意的是我。」象跟他的父母一起瓜分舜的财产，说：「舜娶过来尧的两个女儿，还有尧赐给他的琴，我都要了。牛羊和谷仓都归父母吧。」象于是住在舜的屋里，弹着舜的琴。舜回来后去看望他。象非常惊愕，继而又摆出闷闷不乐的样子，说：「我正在想念你呢，想得我好心闷啊！」舜说：「是啊，你可真够兄弟呀！」舜还像以前一样待奉父母，友爱兄弟，而且更加恭谨。这样，尧才试用舜去理顺五种伦理道德和参与百官的事，都干得很好。
从前高阳氏有富于才德的子孙八人，世人得到他们的好处，称之为八恺，意思就是八个和善的人。高辛氏有有才德的子孙八人，世人称之为「八元」，意思就是八个善良的人。这十六个家族的人，世世代代保持着他们先人的美德，没有败落他们先人的名声。到尧的时候，尧没有举用他们。舜举用了八恺的后代，让他们掌管土地的官职，以处理各种事务，都办得有条有理。舜又举用了八元的后代，让他们向四方传布五教，使得做父亲的有道义，做母亲的慈爱，做兄长的友善，做弟弟的恭谨，做儿子的孝顺，家庭和睦，邻里真诚。
从前帝鸿氏有个不成材的后代，掩蔽仁义，包庇残贼，好行凶作恶，天下人称他为浑沌。意思是说他野蛮不开化。少皞氏也有个不成材的后代，毁弃信义，厌恶忠直，喜欢邪恶的言语，天下人称他为穷奇，意思是说他怪异无比。颛顼氏有个不成材的后代，不可调教，不懂得好话坏话，天下人称他为梼杌，意思是说他凶顽绝伦。这三族，世人都害怕。到尧的时候，尧没有把他们除掉。缙云氏有个不成材的后代，贪于饮食，图于财货，天下人称之为饕餮，意思是说他贪得无厌。天下人憎恨他，反他与上面说的三凶并列在一起称为四凶。舜在四门接待四方宾客时，流放了这四个凶恶的家族，把他们赶到了边远地区，去抵御害人的妖魔，从此开放了四门，大家都说没有恶人了。
舜进入山林的时候，遇到暴风雷雨也不迷路误事，尧于是才知道了凭着舜的才能是可以把天下传授给他的。尧年纪大了，让舜代行天子之政，到四方去巡视。舜被举用掌管政事二十年，尧让他代行天子的政务。代行政务八年，尧逝世了。服丧三年完毕，舜让位给丹朱，可是天下人都来归服舜。禹、皋陶（Yáo）、契、后稷、伯夷、夔（Kuí）、龙、倕、益、彭祖，从尧的时候就都得到举用，却一直没有职务。于是舜就到文祖庙，与四岳商计，开放四门，了解勾通四方的情况，他让十二州牧讨论称帝应具备的功德，他们都说要办有大德的事，疏远巧言谄媚的小人，这样，远方的外族就都会归服。舜对四岳说：「有谁能奋发努力，建立功业，光大帝尧的事业，授给他官职辅佐我办事呢？」四岳都说：「伯禹为司空，可以光大帝尧的事业。」舜说：「嗯，好！禹，你去负责平治水土，一定要努力办好啊！」禹跪地叩头拜谢，谦让给稷、契和皋陶。舜说：「好了，去吧！」舜说：「弃，黎民正在挨饿受饥，你负责农业，去教他们播种百谷吧。」舜说：「契，百官不相亲爱，五伦不顺，你担任司徒，去谨慎地施行五伦教育，做好五伦教育，在于要宽厚。」舜又说：「皋陶，蛮夷侵扰中原，抢劫杀人，在我们的境内外作乱，你担任司法官，五刑要使用得当，根据罪行轻重，大罪在原野上执行，次罪在市、朝内执行，同族人犯罪送交甸师氏处理；五刑宽减为流放的，流放的远近要有个规定，按罪行轻重分别流放到四境之外、九州之外和国都之外。只有公正严明，才能使人信服。」舜问：「那么谁能管理我的各种工匠？」大家都说垂可以。于是任命垂为共工，统领各种工匠。舜又问：「谁能管理我山上泽中的草木鸟兽？」大家都说益行。于是任命益为朕虞，主管山泽。益下拜叩头，推让给朱虎、熊罴。舜说：「去吧，你行。」就让朱虎、熊罴做他的助手。舜说：「喂，四岳，有谁能替我主持天事、地事、人事三种祭祀？」大家都说伯夷可以。舜说：「喂，伯夷，我任命你担秩宗，主管祭祀，要早晚虔敬，要正直，要肃穆清洁。」伯夷推让给夔、龙，舜说：「那好，就任命夔为典乐，掌管音乐，教育贵族子弟，要正直而温和，宽厚而严厉，刚正却不暴虐，简捷却不傲慢；诗是表达内心情感的，歌是用延长音节来咏唱诗的，乐声的高低要与歌的内容相配合，还要用标准的音律来使乐声和谐。八种乐器的声音谐调一致，不要互相错乱侵扰，这样，就能通过音乐达到人与神相和的境界啦。」夔说：「呣，我轻重有节地敲起石罄，各种禽兽都会跟着跳起舞来的。」舜说：「龙，我非常憎恶那种诬陷他人的坏话和灭绝道义的行为，惊扰我的臣民，我任命你为纲言官，早晚传达我的旨命，报告下情，一定要诚实。」舜说：「喂，你们二十二个人，要谨守职责，时时辅佐我做好上天交付的治国大事。」此后，每三年考核一次功绩，经过三次考核，按照成绩升迁或贬黜，所以，不论远处近处，各种事情都振兴起来了。又根据是否归顺，分解了三苗部族。
这二十二人个个成就功业：皋陶担任大理，掌管刑法，断案平正，人们都佩服他能按情据实断理；伯夷主持礼仪，上上下下能都够礼让；垂担任工师，主管百工，百工都能做好自己的工作；益担任虞，主管山泽，山林湖泽都得到开发；弃担任稷，主管农业，百谷按季节茂盛成长；契担任司徒，主管教化，百官都亲善和睦；龙主管接待宾客，远方的诸侯都来朝贡；舜所置十二州牧做事，禹所定九州内的民众没有谁违抗。其中禹的功劳最大，开通了九座大山，治理了九处湖泽，疏浚了九条河流，辟定了九州方界，各地都按照应缴纳的贡物前来进贡，没有不恰当的。纵横五千里的领域，都受到安抚，直到离京师最远的边荒地区。那时，南方安抚到交阯、北发，西方安抚到戎、析枝、渠廋、氐、羌，北方安抚到山戎、发、息慎，东方安抚到长、鸟夷，四海之内，共同称颂帝舜的功德。于是禹创制《九招》乐曲歌颂舜的功德，招来了祥瑞之物，凤凰也飞来，随乐声盘旋起舞。天下清明的德政都从虞之物，凤凰也飞来，随乐声盘旋起舞。天下清明的德政都从虞舜帝开始。
舜二十岁时因为孝顺而闻名，三十岁时被尧举用，五十岁时代理天子政务，五十八岁时尧逝世，六十一岁时接替尧登临天子之位。登位三十九年，到南方巡视，在南方苍梧的郊野逝世。葬埋在长江南岸的九嶷山，这就是零陵。舜登临帝位之后，乘着有天子旗帜的车子去给父亲瞽叟请安，和悦恭敬，遵循为子之孝道。又把弟弟象封在有鼻为诸侯。舜的儿子商均不成材，舜就事先把禹推荐给上帝。十七年后舜逝世。服丧三年完毕，禹也把帝位让给舜的儿子，就跟舜让给尧的儿子时的情形一样。诸侯归服禹，这样，禹就登临了天子之位。尧的儿子丹朱，舜的儿子商均分别在唐和虞得到封地，来奉祀祖先。禹还让他们穿自己家族的服饰，用自己家族的礼乐仪式。他们以客人的身份拜见天子，天子也不把他们当臣下对待，以表示不敢专擅帝位。
从黄帝到舜、禹，都是同姓，但立了不同的国号，为的是彰明各自光明的德业。所以，黄帝号为有熊，帝颛顼号为高阳，帝喾号为高辛，帝尧号为陶唐，帝舜号为有虞。帝禹号为夏后，而另分出氏，姓姒氏。契为商始祖，姓子氏。弃为周始祖，姓姬氏。
太史公说：学者们很多人都称述五帝，五帝的年代已经很久远了。《尚书》只记载着尧以来的史实；而各家叙说黄帝，文字粗疏而不典范，士大夫们也很难说得清楚。孔子传下来的《宰予问五帝德》及《帝系姓》，读书人有的也不传习。我曾经往西到过空桐，往北路过涿鹿，往东到过大海，往南渡过长江、淮水，所到过的地方，那里的老前辈们都往往谈到他们各自所听说的黄帝、尧、舜的事迹，风俗教化都有不同，总起来说，我认为那些与古文经籍记载相符的说法，接近正确。我研读了《春秋》、《国语》，它们对《五帝德》、《帝系姓》的阐发都很明了，只是人们不曾深入考求，其实它们的记述都不是虚妄之说。《尚书》残缺已经有好长时间了，但散轶的记载却常常可以从其他书中找到。如果不是好学深思，真正在心里领会了它们的意思，想要向那些学识浅薄，见闻不广的人说明白，肯定是困难的。我把这些材料加以评议编次，选择了那些言辞特别雅正的，著录下来，写成这篇本纪，列于全书的开头。', '[{"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3d6f6542516c6dede52", "shortContent": "《史记》\n\n也称《太史公书》、《太史公记》。西汉司马迁编撰，部分篇目继承了其父司马谈的遗稿。是中国历史上第一部纪传体通史，与《汉书》、《后汉书》、《三国志》合称“前四史”。全书共一百三十卷，包括本纪十二卷、世家三十卷、列传七十卷、表十卷、书八卷。记载了从上古传说中的黄帝时代至汉武帝太初四年（前101年）的史事。因其文笔高雅，鲁迅赞之“固不失为史家之绝唱，无韵之《离骚》矣”（《汉文学史纲要》）。历代...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3d6f6542516c6dede57", "shortContent": "司马迁从五帝说起，难道意味着五帝之前就没有传说故事了么？事实并不如是，唐代的司马贞曾经为伏羲氏、女娲氏和神农氏补写过《三皇本纪》，司马贞所知道的故事，司马迁怎会不知道呢？“惟昔黄帝，法天择地，四圣遵序，各成法度”（《太史公自序》），原来按照司马迁的观点，黄帝是上古时代规划经纬、将人类带入文明社会的了不起的人物，故而追根溯源的初始理应便是黄帝了。同时，司马迁没有将历史继续向前推衍的另一个原因，则是由...", "authors": ["郭骥"], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3d9f6542516c6dede70", "shortContent": "本篇选自《史记·孝文本纪》。开创了“文景之治”的汉孝文帝，在历史上有着很高的评价，然而他登上历史舞台最初的道路却充满艰险。汉高祖死后，大权为吕太后控制，她大力扶植吕氏外戚的权势，削弱刘氏宗族的力量。以丞相陈平、太尉周勃为首的功臣们在眼见吕氏集团的权力扩张将威胁到自身利益时，便联合朱虚侯刘章等宗室成员发动政变剪除了诸吕。在消灭了最大敌人后，拥立谁为皇帝成为突出问题，当时有四大人选：少帝、齐王、代王、...", "authors": ["陆海旸"], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3d9f6542516c6dede78", "shortContent": "本篇选自《史记·孝武本纪》。《史记》之武帝纪，司马迁原作《今上本纪》。迁殁后散失。张晏谓褚少孙（宣帝时博士）补作《孝武本纪》。魏晋以后，少孙补篇亦佚。今通行本《孝武本纪》，钱大昕《廿二史考异》谓“乡里妄人取此以足其数耳”。《孝武本纪》真伪之论不可谓少。要之，纵然有所谓言意鄙陋浅近之指责，亦不能否认今本补篇为《史记》重要构成的文献价值与史学价值，《孝武本纪》亦然。\n“纪者，统理众事”（裴松之语）。史...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f144d24b2a4416e359", "shortContent": "在新莽政权倒台的战争中，何以刘秀能够在四刘中获得成功、完成了中兴汉室的帝业？这确实是一个值得深思的问题。《后汉书·光武帝纪》的历史叙述提供了刘秀由太学生到成为开国皇帝的风虎云龙博弈际会，也展现了帮助他在龙争虎斗中成功的主客观条件，他的人格特性和领导才具或领导资质恰恰是关键之所在。前述四刘的共同性可以支持我们将他们置入领袖学的研究与比较之中，而刘秀的不同之处，正可显出他的成功条件。这个异同比较亦将对...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f2ccce4d48ba49d1a8", "shortContent": "东汉皇后大多起自豪门富商。后宫妃后繁多，性格与事迹各不相同。有的贤明朴素，有治国才能，如明德马皇后、和熹邓皇后、前期的顺烈梁皇后等；有的刻忌残忍、宠溺外戚，如章德窦皇后、安思阎皇后、桓帝懿献梁皇后、桓思窦皇后等；有的本身无所作为，亦无大过，却沦为后宫或朝廷政治斗争的牺牲品，如梁贵人、王美人、献帝伏皇后等。本篇节选的三位就是这三种类型皇后的代表。\n范晔在《皇后纪》序中言：“东京皇统屡绝，权归女主，外...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f3f6542516c6dedef4", "shortContent": "《魏书·武帝纪》是《三国志》的第一篇。陈寿《三国志》以实录称，王鸣盛《十七史商榷》卷三十九即有“陈寿史皆实录”条以阐发之。《武帝纪》开首叙曹操出生来历，“帝王之兴，不容无本”是中国历史传统观念与正史凡例，故陈书不能不叙。陈书以“莫能审其本末”叙评“武帝出生本末”，王鸣盛书卷四十极称“此正陈寿立文之妙”。盖其文虽有曲而无饰，似可称“曲折的实录”。但王书卷三十八中已先揭出“曹腾，宦者中之最奸狡误国者”...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f3e8f18b220af4bff2", "shortContent": "司马懿是西晋王朝的实际奠基者，故晋代魏后即被追尊为“宣帝”。他出身官宦之家，三十岁始入曹操丞相府为文学掾。而此时，其同辈的周瑜和诸葛亮已名满天下，并在该年与曹操展开了震烁古今的赤壁大战。\n司马懿何以“出山”如此之晚？据《晋书》记载，他早年因不愿为曹操所用，长期装病在家，后来勉强就丞相府之职，还是曹操威逼的结果。但这种说法，明显有所夸饰。盖当时曹操手下谋臣如云，实在没有必要逼政治上尚无任何表现的司马...", "authors": ["胡逢祥"], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f4f6542516c6dedf10", "shortContent": "中国历史上的王位继承，曾经有过“兄终弟及”制度和“父死子继”制度。前者是严密的宗法制度没有确立的结果，后者是嫡长子继承制成熟的表现。在历史发展进程中，殷商是“兄终弟及”，姬周是“父死子继”，这个发展顺序，也说明两种王位继承制度的更替与宗法制度发展成熟的关系。\n然而，三国曹魏以后，司马氏家族的继承方式也存在两种。先是父死子继，司马懿去世后由长子司马师继承；接着是兄终弟及，司马师去世后由弟弟司马昭继承...", "authors": ["梁满仓"], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f830a1d3054c75650c", "shortContent": "北魏是由中国北方的少数民族鲜卑人创立的政权。拓跋部是鲜卑人的一部，原来生活在今内蒙古大兴安岭北部一带，后经不断内迁，逐渐来到了中原的山西地区。魏晋时期，天下大乱，拓跋部通过战争和掠夺逐渐强大起来，公元338年正式建立政权，称为“代”。淝水之战，前秦败亡，拓跋部趁机坐大，经过连续三代君主的努力，逐渐扫平了北方的各少数民族政权，到了太武帝拓跋焘时期，终于实现了北方的统一。拓跋焘颇具文韬武略，即位之后连...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f830a1d3054c75650e", "shortContent": "魏晋南北朝时期，天下大乱，南北对立。南朝的政局有两个鲜明的特点，即军权逐步加强与门阀政治的延续。由是之故，寒门军功阶层得以逐步掌握权力，政权变革主要通过宫廷政变的形式来加以完成，“禅让”又成为朝代更替的主要形式。刘宋的开创者刘裕能够从一介布衣终成开国之君，恰恰印证了这一时代特征。他出身寒微，从其早年出仕为军司马，应幕北府兵为参军来看，应当属于低级士族。他加入的刘牢之北府兵是江东最强的军队，为以后建...", "authors": ["郭敏"], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f830a1d3054c756514", "shortContent": "改革是中国历史上重要的话题，而气魄和政治智慧是杰出的改革者必备的素质。北魏孝文帝元宏就是中国历史上极具气魄和政治智慧的杰出改革家。\n太和十四年（490年），魏孝文帝的祖母太皇太后冯氏病逝。在此以前，北魏始终实行“既葬公除”这一制度。所谓“既葬公除”，即皇帝去世，埋葬完灵柩之后就除去丧服的制度，并没有遵循儒家所提倡的守孝三年这一规定。孝文帝以太皇太后冯氏治丧这一契机，一改拓跋族以往的传统，力主实行三...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f830a1d3054c756515", "shortContent": "齐高帝萧道成出身将门，其父萧承之担任过南朝刘宋政权的汉中太守、南泰山太守、龙骧将军、右军将军等职。将门出将，尽管史书上记载他“姿表英异，龙颡钟声”、“鳞文遍体”，以证明其有帝王之相，然而这只不过是后人赋予历史人物神化色彩的一种说辞，断然不能作为他最终登上皇帝宝座的根据。\n南朝梁萧子显指出，齐高帝萧道成和历史上的汉高祖刘邦、光武帝刘秀、魏武帝曹操、晋宣帝司马懿和宋武帝刘裕一样，都是“一世推雄，卒开鼎...", "authors": ["梁满仓"], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f830a1d3054c75651a", "shortContent": "南朝齐、梁两朝都由兰陵萧氏建立，刘宋末年的乱亡给祖籍兰陵（今江苏武进）的萧道成提供了建功立业的机会，他外抗北魏，内平战乱，最终建立了南齐政权。但是，南齐政权只存在了二十三年，就被同为兰陵萧氏的大司马萧衍夺取了政权。萧衍是南朝很有特点的皇帝，其在位时间之长在中国历史上也是屈指可数的。他作为一个王朝的开创者同时也是实际葬送者，即“自我得之，自我失之”，恐怕历史上也无人能出其右。他学问渊博、精通佛法，在...", "authors": ["郭敏"], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f830a1d3054c75651e", "shortContent": "陈高祖武皇帝陈霸先，字兴国，小字法生，吴兴郡长城县（今浙江长兴东）人。陈霸先初仕梁，曾辅佐王僧辩讨平侯景之乱。天成元年（555年）杀僧辩，立敬帝，自为相国，封陈王。他又打败北齐，排僧辩余党。后来受禅称帝，国号为陈，建都于建康，在位三年，谥武皇帝，庙号高祖。\n侯景之乱给南朝带来了史无前例的动荡与浩劫，萧梁内部权力厮杀更加剧了南朝的动乱。在乱局之中，陈霸先在巩固广州这个大后方后，毅然于岭南起兵勤王。面...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f4f6542516c6dedf0f", "shortContent": "公元254年，司马氏取代曹魏的政治进程进入了关键时期。这一年年初，魏帝曹芳与中书令李丰、光禄大夫张缉等人密谋，欲以夏侯玄代替司马师辅政。司马师闻讯，立即组织反击，杀死李丰、张缉、夏侯玄等人，九月，废掉魏帝曹芳，另立曹髦。不料按下葫芦起了瓢，次年正月，镇东大将军毌丘俭、扬州刺史文钦起兵反对司马师。司马师率师亲征，虽然平定了叛军，却因旧病复发，且日益加重，病死在许昌。\n处于绝望中的魏帝曹髦似乎又看到了...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3f830a1d3054c75651f", "shortContent": "宇文泰，一名黑獭，代郡武川（今内蒙古武川西东土城）人，是鲜卑化的匈奴族人，西魏王朝的拥立者和实际统治者。他最初与父兄镇压义军，后成为贺拔岳部将，贺拔岳死后，统领其部众，以关陇为根据地，迎北魏孝武帝，后弑孝武帝，立元宝炬为文帝，建立西魏后与高欢之东魏相抗衡。宇文泰推行府兵制，颁布六条诏书，以周礼治国，并与高欢互有征伐。西魏禅周后，被追尊为文王，庙号太祖，后又被追尊为文皇帝。\n宇文泰身处魏末丧乱之际，...", "authors": ["严昊"], "pressName": "上海辞书出版社"}]', '', 'indent', 1525123159, '5ae717bd9f5454004019a204', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637434, '史记 · 十二本纪 · 夏本纪', NULL, 19, 139, 0, 1, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E5%A4%8F%E6%9C%AC%E7%BA%AA/2390392?fr=aladdin', '', '夏禹，名曰文命。禹之父曰鲧，鲧之父曰帝颛顼，颛顼之父曰昌意，昌意之父曰黄帝。禹者，黄帝之玄孙而帝颛顼之孙也。禹之曾大父昌意及父鲧皆不得在帝位，为人臣。
当帝尧之时，鸿水滔天，浩浩怀山襄陵，下民其忧。尧求能治水者，群臣四岳皆曰鲧可。尧曰：“鲧为人负命毁族，不可。”四岳曰：“等之未有贤于鲧者，愿帝试之。”于是尧听四岳，用鲧治水。九年而水不息，功用不成。于是帝尧乃求人，更得舜。舜登用，摄行天子之政，巡狩。行视鲧之治水无状，乃殛鲧于羽山以死。天下皆以舜之诛为是。于是舜举鲧子禹，而使续鲧之业。
尧崩，帝舜问四岳曰：“有能成美尧之事者使居官？”皆曰：“伯禹为司空，可成美尧之功。”舜曰：“嗟，然！”命禹：“女平水土，维是勉之。”禹拜稽首，让于契、后稷、皋陶。舜曰：“女其往视尔事矣。”
禹为人敏给克勤；其德不违，其仁可亲，其言可信；声为律，身为度，称以出；亹亹穆穆，为纲为纪。
禹乃遂与益、后稷奉帝命，命诸侯百姓兴人徒以傅土，行山表木，定高山大川。禹伤先人父鲧功之不成受诛，乃劳身焦思，居外十三年，过家门不敢入。薄衣食，致孝于鬼神。卑宫室，致费于沟淢。陆行乘车，水行乘船，泥行乘橇，山行乘檋。左准绳，右规矩，载四时，以开九州，通九道，陂九泽，度九山。令益予众庶稻，可种卑溼。命后稷予众庶难得之食。食少，调有余相给，以均诸侯。禹乃行相地宜所有以贡，及山川之便利。
禹行自冀州始。冀州：既载壶口，治梁及岐。既修太原，至于岳阳。覃怀致功，至于衡漳。其土白壤。赋上上错，田中中，常、卫既从，大陆既为。鸟夷皮服。夹右碣石，入于海。
济、河维沇州：九河既道，雷夏既泽，雍、沮会同，桑土既蚕，于是民得下丘居土。其土黑坟，草繇木条。田中下，赋贞，作十有三年乃同。其贡漆丝，其篚织文。浮于济、漯，通于河。
海岱维青州：堣夷既略，潍、淄其道。其土白坟，海滨广潟，厥田斥卤。田上下，赋中上。厥贡盐絺，海物维错，岱畎丝、枲、铅、松、怪石，莱夷为牧，其篚酓丝。浮于汶，通于济。
海岱及淮维徐州：淮、沂其治，蒙、羽其艺。大野既都，东原底平。其土赤埴坟，草木渐包。其田上中，赋中中。贡维土五色，羽畎夏狄，峄阳孤桐，泗滨浮磬，淮夷蠙珠臮鱼，其篚玄纤缟。浮于淮、泗，通于河。
淮海维扬州：彭蠡既都，阳鸟所居。三江既入，震泽致定。竹箭既布。其草惟夭，其木惟乔，其土涂泥。田下下，赋下上上杂。贡金三品，瑶、琨、竹箭，齿、革、羽、旄，岛夷卉服，其篚织贝，其包橘、柚锡贡。均江海，通淮、泗。
荆及衡阳维荆州：江、汉朝宗于海。九江甚中，沱、涔已道，云土、梦为治。其土涂泥。田下中，赋上下。贡羽、旄、齿、革，金三品，杶、干、栝、柏，砺、砥、砮、丹，维箘簬、楛，三国致贡其名，包匦菁茅，其篚玄纁玑组，九江入赐大龟。浮于江、沱、涔、（于）汉，逾于雒，至于南河。
荆河惟豫州：伊、雒、瀍、涧既入于河，荥播既都，道菏泽，被明都。其土壤，下土坟垆。田中上，赋杂上中。贡漆、丝、絺、纻，其篚纤絮，锡贡磬错。浮于雒，达于河。
华阳黑水惟梁州：汶、嶓既艺，沱、涔既道，蔡、蒙旅平，和夷厎绩。其土青骊。田下上，赋下中三错。贡璆、铁、银、镂、砮、磬，熊、罴、狐、狸、织皮。西倾因桓是来，浮于潜，逾于沔，入于渭，乱于河。
黑水西河惟雍州：弱水既西，泾属渭汭。漆、沮既从，沣水所同。荆、岐已旅，终南、敦物至于鸟鼠。原隰厎绩，至于都野。三危既度，三苗大序。其土黄壤。田上上，赋中下。贡璆、琳、琅玕。浮于积石，至于龙门西河，会于渭汭。织皮昆仑、析支、渠搜，西戎即序。
道九山：汧及岐至于荆山，逾于河；壶口、雷首至于太岳；砥柱、析城至于王屋；太行、常山至于碣石，入于海；西倾、朱圉、鸟鼠至于太华；熊耳、外方、桐柏至于负尾；道嶓冢，至于荆山；内方至于大别；汶山之阳至衡山，过九江，至于敷浅原。
道九川：弱水至于合黎，馀波入于流沙。道黑水，至于三危，入于南海。道河积石，至于龙门，南至华阴，东至砥柱，又东至于盟津，东过雒汭，至于大邳，北过降水，至于大陆，北播为九河，同为逆河，入于海。嶓冢道瀁，东流为汉，又东为苍浪之水，过三澨，入于大别，南入于江，东汇泽为彭蠡，东为北江，入于海。汶山道江，东别为沱，又东至于醴，过九江，至于东陵，东迤北会于汇，东为中江，入于海。道沇水，东为济，入于河，泆为荥，东出陶丘北，又东至于荷，又东北会于汶，又东北入于海。道淮自桐柏，东会于泗、沂，东入于海。道渭自鸟鼠同穴，东会于沣，又东北至于泾，东过漆、沮，入于河。道雒自熊耳，东北会于涧、瀍，又东会于伊，东北入于河。
于是九州攸同，四奥既居，九山刊旅，九川涤原，九泽既陂，四海会同。六府甚修，众土交正，致慎财赋，咸则三壤成赋。中国赐土姓：“祗台德先，不距朕行。”
令天子之国以外五百里甸服：百里赋纳总，二百里纳緫，三百里纳秸服，四百里粟，五百里米。甸服外五百里侯服：百里采，二百里任国，三百里诸侯。侯服外五百里绥服：三百里揆文教，二百里奋武卫。绥服外五百里要服：三百里夷，二百里蔡。要服外五百里荒服：三百里蛮，二百里流。
东渐于海，西被于流沙，朔、南暨：声教讫于四海。于是帝锡禹玄圭，以告成功于天下。天下于是太平治。
皋陶作士以理民。帝舜朝，禹、伯夷、皋陶相与语帝前。皋陶述其谋曰：“信其道德，谋明辅和。”禹曰：“然，如何？”皋陶曰：“于！慎其身修，思长，敦序九族，众明高翼，近可远在已。”禹拜美言，曰：“然。”皋陶曰：“于！在知人，在安民。”禹曰：“吁！皆若是，惟帝其难之。知人则智，能官人；能安民则惠，黎民怀之。能知能惠，何忧乎驩兜，何迁乎有苗，何畏乎巧言善色佞人？”皋陶曰：“然，于！亦行有九德，亦言其有德。”乃言曰：“始事事，宽而栗，柔而立，愿而共，治而敬，扰而毅，直而温，简而廉，刚而实，强而义，章其有常，吉哉。日宣三德，蚤夜翊明有家。日严振敬六德，亮采有国。翕受普施，九德咸事，俊乂在官，百吏肃谨。毋教邪淫奇谋。非其人居其官，是谓乱天事。天讨有罪，五刑五用哉。吾言厎可行乎？”禹曰：“女言致可绩行。”皋陶曰：“余未有知，思赞道哉。”
帝舜谓禹曰：“女亦昌言。”禹拜曰：“于，予何言！予思日孳孳。”皋陶难禹曰：“何谓孳孳？”禹曰：“鸿水滔天，浩浩怀山襄陵，下民皆服于水。予陆行乘车，水行乘舟，泥行乘橇，山行乘檋，行山刊木。与益予众庶稻鲜食。以决九川致四海，浚畎浍致之川。与稷予众庶难得之食。食少，调有余补不足，徙居。众民乃定，万国为治。”皋陶曰：“然，此而美也。”
禹曰：“于，帝！慎乃在位，安尔止。辅德，天下大应。清意以昭待上帝命，天其重命用休。”帝曰：“吁，臣哉，臣哉！臣作朕股肱耳目。予欲左右有民，女辅之。余欲观古人之象。日月星辰，作文绣服色，女明之。予欲闻六律五声八音，来始滑，以出入五言，女听。予即辟，女匡拂予。女无面谀。退而谤予。敬四辅臣。诸众谗嬖臣，君德诚施皆清矣。”禹曰：“然。帝即不时，布同善恶则毋功。”
帝曰：“毋若丹朱傲，维慢游是好，毋水行舟，朋淫于家，用绝其世。予不能顺是。”禹曰：“予（辛壬）娶涂山，（辛壬）癸甲，生启予不子，以故能成水土功。辅成五服，至于五千里，州十二师，外薄四海，咸建五长，各道有功。苗顽不即功，帝其念哉。”帝曰：“道吾德，乃女功序之也。”
皋陶于是敬禹之德，令民皆则禹。不如言，刑从之。舜德大明。
于是夔行乐，祖考至，群后相让，鸟兽翔舞，箫韶九成，凤皇来仪，百兽率舞，百官信谐。帝用此作歌曰：“陟天之命，维时维几。”乃歌曰：“股肱喜哉，元首起哉，百工熙哉！”皋陶拜手稽首扬言曰：“念哉，率为兴事，慎乃宪，敬哉！”乃更为歌曰：“元首明哉，股肱良哉，庶事康哉！”（舜）又歌曰：“元首丛脞哉，股肱惰哉，万事堕哉！”帝拜曰：“然，往钦哉！”于是天下皆宗禹之明度数声乐，为山川神主。
帝舜荐禹于天，为嗣。十七年而帝舜崩。三年丧毕，禹辞辟舜之子商均于阳城。天下诸侯皆去商均而朝禹。禹于是遂即天子位，南面朝天下，国号曰夏后，姓姒氏。
帝禹立而举皋陶荐之，且授政焉，而皋陶卒。封皋陶之后于英、六，或在许。而后举益，任之政。
十年，帝禹东巡狩，至于会稽而崩。以天下授益。三年之丧毕，益让帝禹之子启，而辟居箕山之阳。禹子启贤，天下属意焉。及禹崩，虽授益，益之佐禹日浅，天下未洽。故诸侯皆去益而朝启，曰：“吾君帝禹之子也。”于是启遂即天子之位，是为夏后帝启。
夏后帝启，禹之子，其母涂山氏之女也。
有扈氏不服，启伐之，大战于甘。将战，作甘誓，乃召六卿申之。启曰：“嗟！六事之人，予誓告女：有扈氏威侮五行，怠弃三正，天用勦绝其命。今予维共行天之罚。左不攻于左，右不攻于右，女不共命。御非其马之政，女不共命。用命，赏于祖；不用命，僇于社，予则帑僇女。”遂灭有扈氏。天下咸朝。
夏后帝启崩，子帝太康立。帝太康失国，昆弟五人，须于洛汭，作五子之歌。
太康崩，弟中康立，是为帝中康。帝中康时，羲、和湎淫，废时乱日。胤往征之，作胤征。
中康崩，子帝相立。帝相崩，子帝少康立。帝少康崩，子帝予立。帝予崩，子帝槐立。帝槐崩，子帝芒立。帝芒崩，子帝泄立。帝泄崩，子帝不降立。帝不降崩，弟帝扃立。帝扃崩，子帝廑立。帝廑崩，立帝不降之子孔甲，是为帝孔甲。帝孔甲立，好方鬼神，事淫乱。夏后氏德衰，诸侯畔之。天降龙二，有雌雄，孔甲不能食，未得豢龙氏。陶唐既衰，其后有刘累，学扰龙于豢龙氏，以事孔甲。孔甲赐之姓曰御龙氏，受豕韦之后。龙一雌死，以食夏后。夏后使求，惧而迁去。
孔甲崩，子帝皋立。帝皋崩，子帝发立。帝发崩，子帝履癸立，是为桀。
帝桀之时，自孔甲以来而诸侯多畔夏，桀不务德而武伤百姓，百姓弗堪。乃召汤而囚之夏台，已而释之。汤修德，诸侯皆归汤，汤遂率兵以伐夏桀。桀走鸣条，遂放而死。桀谓人曰：“吾悔不遂杀汤于夏台，使至此。”汤乃践天子位，代夏朝天下。汤封夏之后后，至周封于杞也。
太史公曰：禹为姒姓，其后分封，用国为姓，故有夏后氏、有扈氏、有男氏、斟鄩氏、彤城氏、褒氏、费氏、杞氏、缯氏、辛氏、冥氏、斟（氏）戈氏。孔子正夏时，学者多传夏小正云。自虞、夏时，贡赋备矣。或言禹会诸侯江南，计功而崩，因葬焉，命曰会稽。会稽者，会计也。', '《夏本纪》是西汉史学家司马迁创作的一篇文言文，出自《史记卷二·夏本纪第二》。本片主要记述了夏朝的历史。夏代年代久远，《夏本纪》中记载的内容是现代人研究夏代历史的重要参考资料。夏本是一个古老的部落，相传是由包括夏在内的十多个部落联合发展而来的，与古代其他部落交错分布于中国境内。到唐尧、虞舜时期，夏族的首领禹因治水有功，取得了帝位，并传给其子启，从而建立了我国历史上第一个奴隶制王朝。夏王朝约存在于公元前二十一世纪至公元前十六世纪。', '敏给：敏捷。
克勤：能勤劳。
亹亹：勤勉不倦貌。
穆穆：端庄恭敬。
焦思：焦苦思虑。
白壤：白色的柔土。
织文：染丝织成花纹的丝织品。
维错：复杂众多。
羽畎：羽山之谷。
箘簬：美竹，箭竹。
磬错：磨磬用的石头。
敦物：丰富的物产。
嶓冢：山名。
逆河：指黄河入海处的一段河流。
三壤：古时按土质的肥瘠将耕地分为上、中、下三品，称为三壤。
文教：指礼乐法度，文章教化。
威侮：凌虐侮慢。
湎淫：沉溺于酒。
淫乱：荒淫无道，惑乱。
武伤：以武力伤害。
计功：计算功绩。', '夏禹，名叫文命。他的父亲叫鲧，鲧的父亲叫帝颛顼，颛顼的父亲叫昌意，昌意的父亲叫黄帝。禹就是黄帝的玄孙和颛顼的孙子。只有禹的曾祖父昌意和父亲鲧都不曾登过帝位，而是做臣子。
当帝尧的时候，滔滔的洪水，浩浩荡荡地包围了山岳，漫没了丘陵，老百姓陷在愁苦中。尧急着要找到能治水的人，群臣、四岳都说鲧可以。尧说：“鲧是个违背上命、败坏同族的人，不可用。”四岳说：“这一辈人员中没有比鲧更能干的了，希望陛下试试。”于是尧采纳了四岳的意见，用鲧治水。费了九年功夫，洪水之患没有平息，治水无功。于是帝尧就再设法寻求人才，另外得到了舜。舜被提拔重用，代理执行天子的职务，按时巡行视察各地诸侯所守的疆土。于巡行中发现鲧治水太不像话，就在羽山海边诛杀了鲧。天下的人都认为舜处理得当。这时舜选拔了鲧的儿子禹，任命他继续从事鲧的治水事业。
尧崩逝后，帝舜问四岳说：“有能够很好地完成尧的事业、可以担任官职的人吗？”都说：“如果让伯禹做司空，一定能很好地完成尧的勋业。”帝舜说：“啊！就这样吧！”因此就任命禹说：“你去平定水土，要好好地干啊！”禹下拜叩头，推让给契、后稷、皋陶等人。舜说：“还是你去担负起你这一任务吧！”
禹的为人，办事敏捷而又勤奋，他的品德不违正道，他仁爱之怀人人可亲，他讲的话诚实可信，发出来的声音自然地如同音律，动作举止自然地可为法度，乃至重要规范准则都可从他身上得出。他勤勉肃敬，可作为人所共遵的纲纪。
禹就和伯益、后稷一起奉帝舜之命，命令诸侯百官征集民夫，展开平治水土工作。随着山势树立标识，确定那些高山大川。禹伤痛父亲鲧治水无功被杀，因此劳身苦思，在外十三年，三次经过自己家门也不敢进。自己吃穿都很简朴，但对祖先神明的祭祀却很丰厚尽礼。自己居住的房屋很简陋，但不惜耗巨资于修渠挖沟等水利工程。他赶旱路坐车，走水路坐船，走泥泞的路坐橇，走山路用屐底有齿的檋。经常随身离不开的东西，就是测定平直的水准和绳墨，划定图式的圆规和方矩，四时都带着他们，用以从事于开划九州，辟通九州道路，修筑九州湖泽堤障，计度九州山岳脉络。同时叫伯益发放稻种，教群众在卑湿地方种植。叫后稷当群众在难于得到食物时发给食物。缺粮少食的地方，便调有余地方粮食来补其不足，务使各诸侯境内丰歉均一。禹又巡视各地所特有的物产以定其贡赋，还视察了各地山川的便利情况。
禹督导治水的行程从冀州开始。冀州：已治理了壶口，接着治理梁山和岐山。已修整了太原之后，接着修整到泰岳南面地区。覃怀地区也完工了，就到了衡漳水一带。常水（恒水）、卫水也都随河道流畅了，大陆泽周围土地都可耕作了（按这两句原错简在“田赋”下，今译文移正）。这一州的土壤是白壤，田地列在第五等（按此句原错在“赋”下，今译文移正），赋税第一等，不过随年的丰歉杂出第二等。东北的鸟夷族贡纳供贵族服用的珍奇异兽皮毛。他们遵海路入贡，在沿海岸（辽东湾西岸）向南航行的航道上，看到右拐角处的碣石便据以转而向西航驶，直驶入黄河航道。
济水和黄河之间是兖州。黄河下游的九条河道已畅通了，雷夏洼地已汇聚成湖泽了，雍水、沮水也都会同流到了雷夏泽中，能种桑的土地上已经在养蚕，于是人民得以从躲避洪水迁居的高地下到平地居住。这一州的土壤是黑坟，它上面披盖着茂盛的长林丰草。田地列在第六等，赋税则为第九等。这一州经过十三年的农作耕耘，才赶上其他各州。这一州的贡物是漆和丝，还有装在筐子里进贡的文彩美丽的丝织品。它的进贡道路是由船运经济水、漯水，直达黄河。
地跨东边的海，直至西边的泰山，这一地域是青州。已经给居住在东北的堣夷族划定疆界，使获安居；又疏通潍水、淄水，使这一地区也获得治理。这一州的土壤是白坟，海滨则是咸卤盐场。田地列在第三等，赋税则为第四等。这一州的贡物是盐、精细的葛布、海产品以及磨玉的砺石，并有泰山山谷里出的丝、麻、铅、松、似玉之石和莱夷族所献的畜产，还有装在筐子里进贡的山桑蚕丝。它的进贡道路是由汶水船运直达济水。（再由济入河。）
东边沿海，北边至泰山，南边至淮水之间的地域是徐州。淮水和沂水都已经治理，蒙山、羽山地方也都可耕种，大野泽也已汇积成湖，东原地区的水潦已去，地已平复。这一州的土壤是赤埴坟，它上面的草木繁茂丛生。田地列在第二等，赋税则为第五等。这一州的贡物是五色土，羽山谷中所出的五色雉羽，峄山之阳特产的制琴良材名桐，泗水滨的浮磐石，和淮夷族所献的珍珠贝及鱼产，还有装在筐子里进贡的赤黑色细缯和白色绸帛。它进贡道路由淮水船运入泗，再通于菏水。（再由菏入济以通河。）
北起淮河，东南到海之地是扬州。彭蠡之域已汇集众水成湖，作为每年雁阵南飞息冬之地。彭蠡以东诸江水已入于海，太湖水域也就安定了。于是遍地长满丛生的竹林，到处尽见美盛的芳草、葱翠的乔木。这一州的土壤是涂泥，田地列在第九等，赋税则为第七等，有时杂出为第六等。这一州的贡物是三种成色的铜，以及瑶琨美玉、竹材、象牙、异兽之革、珍禽之羽、旌牛之尾，和岛夷族所献的一种称为“卉服”的细葛布，还有装在筐子里进贡的绚丽的贝锦，和妥加包装进贡的橘子、柚子。这些贡品都经由大海、长江进入淮河、泗水。
荆山到衡山的南面是荆州：这个地区有长江、汉水注入大海。长江的众多支流大都有了固定的河道，沱水、涔水业已疏导，云泽、梦泽也治理好了。这里的土质湿润，田地属下中，即第八等，赋税居上下，即第三等。进贡的物品是羽毛、旄牛尾、象牙、皮革、三色铜，以及椿木、柘（zhè，蔗）木、桧木、柏木，还有粗细磨石，可做箭头的砮（nǔ，努）石、丹砂，特别是可做箭杆的竹子箘（jùn，郡）簬（lù，路）和楛（hù，户）木是汉水附近三个诸侯国进贡的最有名的特产，还有包裹着和装在匣子里的供祭祀时滤酒用的青茅，用竹筐盛着的彩色布帛，以及穿珠子用的丝带。有时根据命令进贡九江出产的大龟。进贡时，经由长江、沱水、涔水、汉水，转行一段陆路再进入洛水，然后转入南河。
荆州和黄河之间是豫州：伊水、洛水、瀍水、涧水都已疏通注入黄河，荥播也汇成了一个湖泊，还疏浚了荷泽，修筑了明都泽的堤防。这里的土质松软肥沃，低地则是肥沃坚实的黑土。田地属中上，即第四等，赋税居上中，即第二等，有时居第一等。进贡漆、丝、细葛布、麻，以及用竹筐盛着的细丝絮，有时按命令进贡治玉磬用的石头，进贡时走水路，经洛水进入黄河。
华山南麓到黑水之间是梁州：汶（岷）山、嶓冢山都可以耕种了，沱水、涔水也已经疏通，蔡山、蒙山的道路已经修好，在和夷地区治水也取得了成效。这里的土质是青黑色的，田地属下上，即第七等，赋税居下中，即第八等，有时也居第七等或第九等。贡品有美玉、铁、银、可以刻镂的硬铁、可以做箭头的砮石、可以制磬的磬石，以及熊、罴、狐狸。织皮族的贡品由西戎西倾山经桓水运出，再从潜水船运，进入沔（miǎn，免）水，然后走一段山路进入渭水，最后横渡黄河到达京城。
黑水与黄河西岸之间是雍州：弱水经治理已向西流去，泾水汇入了渭水。漆水、沮水跟着也汇入渭水，还有沣水同样汇入渭水。荆山、岐山的道路业已开通，终南山、敦物山一直到鸟鼠山的道路也已竣工。高原和低谷的治理工程都取得了成绩，一直治理到都野泽一带。三危山地区可以居住了，三苗族也大为顺服。这里的土质色黄而且松软肥沃，田地属上上，即第一等，赋税居中下，即第六等。贡品是美玉和美石。进贡时从积石山下走水路，顺流到达龙门山间的西河，会集到渭水湾里。织皮族居住在昆仑山、枝支山、渠搜山等地，那时西戎各国也归服了。
禹开通了九条山脉的道路：一条从汧山和岐山开始一直开到荆山，越过黄河；一条从壶口山、雷首山一直开到太岳山；一条从砥柱山、析城山一直开到王屋山；一条从太行山、常山一直开到碣石山，进入海中与水路接通；一条从西倾山、朱圉山，鸟鼠山一直开到太华山；一条从熊耳山、外方山、桐柏山一直开到负尾山；一条从嶓冢山一直开到荆山；一条从内方山一直开到大别山；一条从汶山的南面开到衡山，越过九江，最后到达敷浅原山。
禹疏导了九条大河：把弱水疏导至合黎，使弱水的下游注入流沙（沙漠）。疏导了黑水，经过三危山，流入南海（青海）。疏导黄河，从积石山开始，到龙门山，向南到华阴，然后东折经过砥柱山，继续向东到孟津，再向东经过洛水入河口，直到大邳；转而向北经过降水，到大陆泽，再向北分为九条河，这九条河到下游又汇合为一条，叫做逆河，最后流入大海。从嶓冢山开始疏导漾水，向东流就是汉水，再向东流就是苍浪水，经过三澨（shì，誓）水，到大别山，南折注入长江，再向东与彭蠡泽之水会合，继续向东就是北江，流入大海。从汶山开始疏导长江，向东分出支流就是沱水，再往东到达醴水，经过九江，到达东陵，向东斜行北流，与彭蠡泽之水会合，继续向东就是中江，最后流入大海。疏导沇水，向东流就是济水，注入黄河，两水相遇，溢为荥泽，向东经过陶丘北面，继续向东到达荷泽，向东北与汶水会合，再向北流入大海。从桐柏山开始疏导淮水，向东与泗水、沂水会合，再向东流入大海。疏导渭水，从鸟鼠同穴山开始，往东与沣水会合，又向东与泾水会合，再往东经过漆水、沮水，流入黄河。疏导洛水，从熊耳山开始，向东北与涧水、瀍水会合，又向东与伊水会合，再向东北流入黄河。
所有的山川河流都治理好了，从此九州统一，四境之内都可以居住了，九条山脉开出了道路，九条大河疏通了水源，九个大湖筑起了堤防，四海之内的诸侯都可以来京城会盟和朝觐了。金、木、水、火、土、谷六库的物资治理得很好，各方的土地美恶高下都评定出等级，能按照规定认真进贡纳税，赋税的等级都是根据三种不同的土壤等级来确定。还在华夏境内九州之中分封诸侯，赐给土地，赐给姓氏，并说：“要恭敬地把德行放在第一位，不要违背我天子的各种措施。”
禹下令规定天子国都以外五百里的地区为甸服，即为天子服田役纳谷税的地区：紧靠王城百里以内要交纳收割的整棵庄稼，一百里以外到二百里以内要交纳禾穗，二百里以外到三百里以内要交纳谷粒，三百里以外到四百里以内要交纳粗米，四百里以外到五百里以内要交纳精米。甸服以外五百里的地区为侯服，即为天子侦察顺逆和服侍王命的地区：靠近甸服一百里以内是卿大夫的采邑，往外二百里以内为小的封国，再往处二（原文作“三”）百里以内为诸侯的封地。侯服以外五百里的地区为绥服，即受天子安抚，推行教化的地区：靠近侯服三百里以内视情况来推行礼乐法度、文章教化，往外二百里以内要振兴武威，保卫天子。绥服以外五百里的地区为要（yāo，腰）服，即受天子约束服从天子的地区：靠近绥服三百里以内要遵守教化，和平相处；往外二百里以内要遵守王法。要服以外五百里的地区为荒服，即为天子守卫远边的荒远地区：靠近要服三百里以内荒凉落后，那里的人来去不受限制；再往外二百里以内可以随意居处，不受约束。
这样，东临大海，西至沙漠，从北方到南方，天子的声威教化达到了四方荒远的边陲。于是舜帝为表彰禹治水有功而赐给他一块代表水色的黑色圭玉，向天下宣告治水成功。天下从此太平安定。
皋陶担任执法的士这一官职，治理民众。舜帝上朝，禹、伯夷、皋陶一块儿在舜帝面前谈话。皋陶申述他的意见说：“遵循道德确定不移，就能做到谋略高明，臣下团结。”禹说：“很对，但应该怎样做呢？”皋陶说：“哦，要谨慎对待自身修养，要有长远打算，使上至高祖下至玄孙的同族人亲厚稳定，这样，众多有见识的人就都会努力辅佐你，由近处可以推及到远处，一定要从自身做起。”禹拜谢皋陶的善言，说：“对。”皋陶说：“哦，还有成就德业就在于能够了解人，能够安抚民众。”禹说：“呵！都象这样，即使是尧帝恐怕也会感到困难的。能了解人就是明智，就能恰当地给人安排官职；能安抚民众就是仁惠，黎民百姓都会爱戴你。如果既能了解人，又能仁惠，还忧虑什么欢（huān，欢）兜，何必流放有苗，何必害怕花言巧语伪善谄媚的小人呢？”皋陶说：“对，是这样。检查一个人的行为要根据九种品德，检查一个人的言论，也要看他是否有好的品德。”他接着说道：“开始先从办事来检验，宽厚而又威严，温和而又坚定，诚实而又恭敬，有才能而又小心谨慎，善良而又刚毅，正直而又和气，平易而又有棱角，果断而又讲求实效，强有力而又讲道理，要重用那些具有九德的善士呀！能每日宣明三种品德，早晚谨行努力，卿大夫就能保有他的采邑。每日严肃地恭敬实行六种品德，认真辅佐王事，诸侯就可以保有他的封国。能全部具备这九种品德并普遍施行，就可以使有才德的人都居官任职，使所有的官吏都严肃认真办理自己的政务。不要叫人们胡作非为，胡思乱想。如果让不适当的人居于官位，就叫做扰乱上天所命的大事。上天惩罚有罪的人，用五种刑罚处治犯有五种罪行的罪人。我讲的大抵可以行得通吧？”禹说：“如果按你的话行事，一定会做出成绩的。”皋陶说：“我才智浅薄，只是希望有助于推行治天下之道。”
舜帝对禹说：“你也说说你的好意见吧。”禹谦恭地行了拜礼，说：“哦，我说什么呢？我只想每天勤恳努力地办事。”皋陶追问道：“怎样才叫勤恳努力？”禹说：“洪水滔天，浩浩荡荡，包围了高山，漫上了丘陵，下民都遭受着洪水的威胁。我在陆地上行走乘车，在水中行走乘船，在泥沼中行走乘木橇，在山路上行走就穿上带铁齿的鞋，翻山越岭，树立木桩，在山上作了标志。我和益一块，给黎民百姓稻粮和新鲜的肉食。疏导九条河道引入大海，又疏浚田间沟渠引入河道。和稷一起赈济吃粮困难的民众。粮食匮乏时，从粮食较多的地区调济给粮食欠缺的地区，或者叫百姓迁到有粮食的地区居住。民众安定下来了，各诸侯国也都治理好了。”皋陶说：“是啊，这些是你的巨大业绩。”
禹说：“啊，帝！谨慎对待您的在位之臣，稳稳当当处理您的政务。辅佐的大臣有德行，天下人都会响应拥护您。您用清静之心奉行上帝的命令，上天会经常把美好的符瑞降临给您。”舜帝说：“啊，大臣呀，大臣呀！大臣是我的臂膀和耳目。我想帮助天下民众，你们要辅助我。我想要效法古人衣服上的图象，按照日月星辰的天象制作锦绣服装，你们要明确各种服装的等级。我想通过各地音乐的雅正与淫邪等来考察那里考察那里政教的情况，以便取舍各方的意见，你们要仔细地辨听。我的言行如有不正当的地方，你们要纠正我。你们不要当面奉承，回去之后却又指责我。我敬重前后左右辅佐大臣。至于那些搬弄是非的佞臣，只要君主的德政真正施行，他们就会被清除了。”禹说：“对。您如果不这样，好人坏人混而不分，那就不会成就大事。”
舜帝说：“你们不要学丹朱那样桀傲骄横，只喜欢怠惰放荡，在无水的陆地上行船，聚众在家里干淫乱之事，以致不能继承帝位。对这种人我决不听之任之。”禹说：“我娶涂山氏的女儿时，新婚四天就离家赴职，生下启我也未曾抚育过，因引才能使平治水土的工作取得成功。我帮助帝王设置了五服，范围达到五千里，每州用了三万劳力，一直开辟到四方荒远的边境，在每五个诸侯国中设立一个首领，他们各尽职守，都有功绩，只有三苗凶顽，没有功绩，希望帝王您记着这件事。”舜帝说：“用我的德教来开导，那么凭你的工作就会使他们归顺的！”
皋陶此时敬重禹的功德，命令天下都学习禹的榜样。对于不听从命令的，就施以刑法。因此，舜的德教得到了大发扬。
这时，夔担任乐师，谱定乐曲，祖先亡灵降临欣赏，各诸侯国君相互礼让，鸟兽在宫殿周围飞翔、起舞，《箫韶》奏完九通，凤凰被召来了。群兽都舞起来，百官忠诚合谐。舜帝于是歌唱道：“奉行天命，施行德政，顺应天时，谨微慎行。”又唱道：“股肱大臣喜尽忠啊，天子治国要有功啊，百官事业也兴盛啊！”皋陶跪拜，先低头至手，又叩头至地，然后高声说道：“您可记住啊，要带头努力尽职，谨慎对待您的法度，认真办好各种事务！”于是也接着唱道：“天子英明有方啊，股肱大臣都贤良啊，天下万事都兴旺啊！”又唱道：“天子胸中无大略啊，股肱大臣就懈怠啊，天下万事都败坏啊！”舜帝拜答说：“对！以后我们都要努力办好各自的事务！”这时候天下都推崇禹精于尺度和音乐，尊奉他为山川的神主，意思就是能代山川之神施行号令的帝王。
舜帝把禹推荐给上天，让他作为帝位的继承人。十七年之后，舜帝逝世。服丧三年完毕，禹为了把帝位让给舜的儿子商均，躲避到阳城。但天下诸侯都不去朝拜商均而来朝拜禹。禹这才继承了天子之位，南面接受天下诸侯的朝拜，国号为夏后，姓姒氏。
禹帝立为天子后，举用皋陶为帝位继承人，把他推荐给上天，并把国政授给他，但是皋陶没有继任就死了。禹把皋陶的后代封在英、六两地，有的封在许地。后来又举用了益，把国政授给他。
过了十年，禹帝到东方视察，到达会稽，在那里逝世。把天下传给益。服丧三年完毕，益又把帝位让禹的儿子启，自己到箕山之南去躲避。禹的儿子启贤德，天下人心都归向于他。等到禹逝世，虽然把天子位传给益，但由于益辅佐禹时间不长，天下并不顺服他。所以，诸侯还是都离开益而去朝拜启，说：“这是我们的君主禹帝的儿子啊。”于是启就继承了天子之位，这就是夏后帝启。
夏后帝启，是禹的儿子，他的母亲是涂山氏的女儿。
启登临帝位后，有扈氏不来归从，启前往征伐，在甘地大战一场。战斗开始之前，启作了一篇誓辞叫做《甘誓》，召集来六军将领进行训诫。启说：”喂！六军将领们，我向你们宣布誓言：有扈氏蔑视仁、义、礼、智、信五常的规范，背离天、地、人的正道，因此上天要断绝他的大命。如今我恭敬地执行上天对他的惩罚。战车左边的射手不从左边射击敌人，车右的剑手不从右边击杀敌人，就是不服从命令。驭手不能使车马阵列整齐，也是不服从命令。听从命令的，我将在祖先神灵面前奖赏他；谁不听从命令，就在社神面前杀掉他，而且要把他们的家属收为奴婢。”于是消灭了有扈氏，天下都来朝拜。
夏后帝启逝世后，他的儿子帝太康继位。帝太康整天游玩打猎，不顾民事，结果被羿放逐，丢了国家，他的五个弟在洛水北岸等待他没有等到，作了《五子之歌》。
太康逝世后，他的弟弟中康继位，这就是中康帝，中康帝在位的时候，掌管天地四时的大臣羲氏、和氏沉湎于酒，把每年的四季、日子的甲乙都搞乱了。胤奉命去征讨他，作了《胤征》。
中康逝世以后，他的儿子帝相继位。帝相逝世，儿子帝少康继位。帝少康逝世，儿子帝予继位。帝予逝世，儿子帝槐继位。帝槐逝世，儿子帝芒继位。帝芒逝世，儿子帝泄继位。帝泄逝世，儿子帝不降继位。帝不降逝世，弟弟帝扃（jiōng，平声炯）继位。帝扃逝世，儿子帝廑（jǐn，谨）继位。帝谨逝世，立帝不降的儿子孔甲为帝，这就是帝孔甲。帝孔甲继位后，迷信鬼神，干淫乱的事。夏后氏的威德日渐衰微，诸侯相继背叛了他。上天降下两条神龙，一雌一雄，孔甲喂养不了它们，也没有找到能够饲养的人。陶唐氏已经衰败，有个后代叫刘累，从会养龙的人那里学会了驯龙，就去侍奉孔甲。孔甲赐给他姓御龙氏，让他来接受豕韦氏后代的封地。后来那条雌龙死了，刘累偷偷做成肉酱拿来献给孔甲吃。夏后孔甲吃了以后，又派人去找刘累要肉酱，刘累害怕了，就迁到鲁县去。
孔甲逝世后，儿子帝皋继位。帝皋逝世后，儿子帝发继位。帝发逝世，儿子帝履癸继位，这就是桀。帝桀在位时，因为自从孔甲在位以来，诸侯就有很多相继叛离了夏，而桀又不修德行而用武力伤害百官之族，百官不堪忍受。桀召来汤，把他囚禁在夏台，后来又放了他。汤修行德业，诸侯都来归附，汤就率兵去征讨夏桀，夏桀逃到鸣条，最后被后放逐而死。桀对人说：“我后悔当初没有索性把汤杀死在夏台，以致使我落到这个下场。”这样，汤就登上了天子之位，取代了夏朝，领有天下。汤封了夏的后代，到周朝时，把他们封在杞地。
太史公说：禹是姒姓，他的后代被分封在各地，用国号为姓，所以有夏后氏、有扈氏、有男氏、斟鄩氏、彤城氏、褒氏、费氏、杞氏、缯氏、辛氏、冥氏、斟戈氏。据说孔子曾校正夏朝的历法，学者们有许多传习《夏小正》的。从虞舜、夏禹时代开始，进贡纳赋的规定已完备。有人说禹在长江南会聚诸侯，因为是在考核诸侯功绩时死的，就葬在那里了，所以，把埋葬禹的苗山改名为会稽山。会稽就是会计（会合考核）的意思。', NULL, '', 'indent', 1525123256, '5ae71831fe88c2003834426c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637435, '史记 · 十二本纪 · 殷本纪', NULL, 30, 139, 1, 2, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E6%AE%B7%E6%9C%AC%E7%BA%AA/2390465?fr=aladdin', '', '殷契，母曰简狄，有娀氏之女，为帝喾次妃。三人行浴，见玄鸟堕其卵，简狄取吞之，因孕生契。契长而佐禹治水有功。帝舜乃命契曰：“百姓不亲，五品不训，汝为司徒而敬敷五教，五教在宽。”封于商，赐姓子氏。契兴于唐、虞、大禹之际，功业著于百姓，百姓以平。
契卒，子昭明立。昭明卒，子相土立。相土卒，子昌若立。昌若卒，子曹圉立。曹圉卒，子冥立。冥卒，子振立。振卒，子微立。微卒，子报丁立。报丁卒，子报乙立。报乙卒，子报丙立。报丙卒，子主壬立。主壬卒，子主癸立。主癸卒，子天乙立，是为成汤。
成汤，自契至汤八迁。汤始居亳，从先王居，作帝诰。
汤征诸侯。葛伯不祀，汤始伐之。汤曰：“予有言：人视水见形，视民知治不。”伊尹曰：“明哉！言能听，道乃进。君国子民，为善者皆在王官。勉哉，勉哉！”汤曰：“汝不能敬命，予大罚殛之，无有攸赦。”作汤征。
伊尹名阿衡。阿衡欲奸汤而无由，乃为有莘氏媵臣，负鼎俎，以滋味说汤，致于王道。或曰，伊尹处士，汤使人聘迎之，五反然后肯往从汤，言素王及九主之事。汤举任以国政。伊尹去汤适夏。既丑有夏，复归于亳。入自北门，遇女鸠、女房，作女鸠女房。
汤出，见野张网四面，祝曰：“自天下四方皆入吾网。”汤曰：“嘻，尽之矣！”乃去其三面，祝曰：“欲左，左。欲右，右。不用命，乃入吾网。”诸侯闻之，曰：“汤德至矣，及禽兽。”
当是时，夏桀为虐政淫荒，而诸侯昆吾氏为乱。汤乃兴师率诸侯，伊尹从汤，汤自把钺以伐昆吾，遂伐桀。汤曰：“格女众庶，来，女悉听朕言。匪台小子敢行举乱，有夏多罪，予维闻女众言，夏氏有罪。予畏上帝，不敢不正。今夏多罪，天命殛之。今女有众，女曰：‘我君不恤我众，舍我啬事而割政。’女其曰：‘有罪，其柰何？’夏王率止众力，率夺夏国。众有率怠不和，曰：‘是日何时丧？予与女皆亡！’夏德若兹，今朕必往。尔尚及予一人致天之罚，予其大理女。女毋不信，朕不食言。女不从誓言，予则帑僇女，无有攸赦。”以告令师，作汤誓。于是汤曰：“吾甚武。”号曰武王。
桀败于有娀之虚，桀奔于鸣条，夏师败绩。汤遂伐三嵕，俘厥宝玉，义伯、仲伯作《典宝》。汤既胜夏，欲迁其社，不可，作夏社。伊尹报。于是诸侯毕服，汤乃践天子位，平定海内。
汤归至于泰卷陶，中垒作诰。既绌夏命，还亳，作汤诰：“维三月，王自至于东郊。告诸侯群后：‘毋不有功于民，勤力乃事。予乃大罚殛女，毋予怨。’曰：‘古禹、皋陶久劳于外，其有功乎民，民乃有安。东为江，北为济，西为河，南为淮，四渎已修，万民乃有居。后稷降播，农殖百谷。三公咸有功于民，故后有立。昔蚩尤与其大夫作乱百姓，帝乃弗予，有状。先王言不可不勉。’曰：‘不道，毋之在国，女毋我怨。’”以令诸侯。伊尹作咸有一德，咎单作明居。
汤乃改正朔，易服色，上白，朝会以昼。
汤崩，太子太丁未立而卒，于是乃立太丁之弟外丙，是为帝外丙。帝外丙即位三年，崩，立外丙之弟中壬，是为帝中壬。帝中壬即位四年，崩，伊尹乃立太丁之子太甲。太甲，成汤适长孙也，是为帝太甲。帝太甲元年，伊尹作伊训，作肆命，作徂后。
帝太甲既立三年，不明，暴虐，不遵汤法，乱德，于是伊尹放之于桐宫。三年，伊尹摄行政当国，以朝诸侯。
帝太甲居桐宫三年，悔过自责，反善，于是伊尹乃迎帝太甲而授之政。帝太甲修德，诸侯咸归殷，百姓以宁。伊尹嘉之，乃作太甲训三篇，褒帝太甲，称太宗。
太宗崩，子沃丁立。帝沃丁之时，伊尹卒。既葬伊尹于亳，咎单遂训伊尹事，作沃丁。
沃丁崩，弟太庚立，是为帝太庚。帝太庚崩，子帝小甲立。帝小甲崩，弟雍己立，是为帝雍己。殷道衰，诸侯或不至。
帝雍己崩，弟太戊立，是为帝太戊。帝太戊立伊陟为相。亳有祥桑谷共生于朝，一暮大拱。帝太戊惧，问伊陟。伊陟曰：“臣闻妖不胜德，帝之政其有阙与？帝其修德。”太戊从之，而祥桑枯死而去。伊陟赞言于巫咸。巫咸治王家有成，作咸艾，作太戊。帝太戊赞伊陟于庙，言弗臣，伊陟让，作原命。殷复兴，诸侯归之，故称中宗。
中宗崩，子帝中丁立。帝中丁迁于隞。河亶甲居相。祖乙迁于邢。帝中丁崩，弟外壬立，是为帝外壬。仲丁书阙不具。帝外壬崩，弟河亶甲立，是为帝河亶甲。河亶甲时，殷复衰。
河亶甲崩，子帝祖乙立。帝祖乙立，殷复兴。巫贤任职。
祖乙崩，子帝祖辛立。帝祖辛崩，弟沃甲立，是为帝沃甲。帝沃甲崩，立沃甲兄祖辛之子祖丁，是为帝祖丁。帝祖丁崩，立弟沃甲之子南庚，是为帝南庚。帝南庚崩，立帝祖丁之子阳甲，是为帝阳甲。帝阳甲之时，殷衰。
自中丁以来，废适而更立诸弟子，弟子或争相代立，比九世乱，于是诸侯莫朝。
帝阳甲崩，弟盘庚立，是为帝盘庚。帝盘庚之时，殷已都河北，盘庚渡河南，复居成汤之故居，乃五迁，无定处。殷民咨胥皆怨，不欲徙。盘庚乃告谕诸侯大臣曰：“昔高后成汤与尔之先祖俱定天下，法则可修。舍而弗勉，何以成德！”乃遂涉河南，治亳，行汤之政，然后百姓由宁，殷道复兴。诸侯来朝，以其遵成汤之德也。
帝盘庚崩，弟小辛立，是为帝小辛。帝小辛立，殷复衰。百姓思盘庚，乃作盘庚三篇。帝小辛崩，弟小乙立，是为帝小乙。
帝小乙崩，子帝武丁立。帝武丁即位，思复兴殷，而未得其佐。三年不言，政事决定于冢宰，以观国风。武丁夜梦得圣人，名曰说。以梦所见视群臣百吏，皆非也。于是乃使百工营求之野，得说于傅险中。是时说为胥靡，筑于傅险。见于武丁，武丁曰是也。得而与之语，果圣人，举以为相，殷国大治。故遂以傅险姓之，号曰傅说。
帝武丁祭成汤，明日，有飞雉登鼎耳而呴，武丁惧。祖己曰：“王勿忧，先修政事。”祖己乃训王曰：“唯天监下典厥义，降年有永有不永，非天夭民，中绝其命。民有不若德，不听罪，天既附命正厥德，乃曰其奈何。呜呼！王嗣敬民，罔非天继，常祀毋礼于弃道。”武丁修政行德，天下咸欢，殷道复兴。
帝武丁崩，子帝祖庚立。祖己嘉武丁之以祥雉为德，立其庙为高宗，遂作高宗肜日及训。
帝祖庚崩，弟祖甲立，是为帝甲。帝甲淫乱，殷复衰。
帝甲崩，子帝廪辛立。帝廪辛崩，弟庚丁立，是为帝庚丁。帝庚丁崩，子帝武乙立。殷复去亳，徙河北。
帝武乙无道，为偶人，谓之天神。与之博，令人为行。天神不胜，乃僇辱之。为革囊，盛血，昂而射之，命曰“射天”。武乙猎于河渭之闲，暴雷，武乙震死。子帝太丁立。帝太丁崩，子帝乙立。帝乙立，殷益衰。
帝乙长子曰微子启，启母贱，不得嗣。少子辛，辛母正后，辛为嗣。帝乙崩，子辛立，是为帝辛，天下谓之纣。
帝纣资辨捷疾，闻见甚敏；材力过人，手格猛兽；知足以距谏，言足以饰非；矜人臣以能，高天下以声，以为皆出己之下。好酒淫乐，嬖于妇人。爱妲己，妲己之言是从。于是使师涓作新淫声，北里之舞，靡靡之乐。厚赋税以实鹿台之钱，而盈钜桥之粟。益收狗马奇物，充仞宫室。益广沙丘苑台，多取野兽蜚鸟置其中。慢于鬼神。大聚乐戏于沙丘，以酒为池，县肉为林，使男女裸相逐其闲，为长夜之饮。
百姓怨望而诸侯有畔者，于是纣乃重刑辟，有炮格之法。以西伯昌、九侯、鄂侯为三公。九侯有好女，入之纣。九侯女不喜淫，纣怒，杀之，而醢九侯。鄂侯争之彊，辨之疾，并脯鄂侯。西伯昌闻之，窃叹。崇侯虎知之，以告纣，纣囚西伯羑里。西伯之臣闳夭之徒，求美女奇物善马以献纣，纣乃赦西伯。西伯出而献洛西之地，以请除炮格之刑。纣乃许之，赐弓矢斧钺，使得征伐，为西伯。而用费中为政。费中善谀，好利，殷人弗亲。纣又用恶来。恶来善毁谗，诸侯以此益疏。
西伯归，乃阴修德行善，诸侯多叛纣而往归西伯。西伯滋大，纣由是稍失权重。王子比干谏，弗听。商容贤者，百姓爱之，纣废之。及西伯伐饥国，灭之，纣之臣祖伊闻之而咎周，恐，奔告纣曰：“天既讫我殷命，假人元龟，无敢知吉，非先王不相我后人，维王淫虐用自绝，故天弃我，不有安食，不虞知天性，不迪率典。今我民罔不欲丧，曰‘天曷不降威，大命胡不至’？今王其柰何？”纣曰：“我生不有命在天乎！”祖伊反，曰：“纣不可谏矣。”西伯既卒，周武王之东伐，至盟津，诸侯叛殷会周者八百。诸侯皆曰：“纣可伐矣。”武王曰：“尔未知天命。”乃复归。
纣愈淫乱不止。微子数谏不听，乃与大师、少师谋，遂去。比干曰：“为人臣者，不得不以死争。”乃强谏纣。纣怒曰：“吾闻圣人心有七窍。”剖比干，观其心。箕子惧，乃详狂为奴，纣又囚之。殷之大师、少师乃持其祭乐器奔周。周武王于是遂率诸侯伐纣。纣亦发兵距之牧野。甲子日，纣兵败。纣走入，登鹿台，衣其宝玉衣，赴火而死。周武王遂斩纣头，县之（大）白旗。杀妲己。释箕子之囚，封比干之墓，表商容之闾。封纣子武庚、禄父，以续殷祀，令修行盘庚之政。殷民大说。于是周武王为天子。其后世贬帝号，号为王。而封殷后为诸侯，属周。
周武王崩，武庚与管叔、蔡叔作乱，成王命周公诛之，而立微子于宋，以续殷后焉。
太史公曰：余以颂次契之事，自成汤以来，采于书诗。契为子姓，其后分封，以国为姓，有殷氏、来氏、宋氏、空桐氏、稚氏、北殷氏、目夷氏。孔子曰，殷路车为善，而色尚白。
简狄吞乙，是为殷祖。玄王启商，伊尹负俎。上开三面，下献九主。旋师泰卷，继相臣扈。迁嚣圮耿，不常厥土。武乙无道，祸因射天。帝辛淫乱，拒谏贼贤。九侯见醢，炮格兴焉。黄钺斯杖，白旗是悬。哀哉琼室，殷祀用迁！', '《殷本纪》是西汉史学家司马迁创作的一篇文言文，出自《史记卷三·殷本纪第三》。商朝是中国历史上的第二个朝代，从公元前1600年——公元前1046年，前后相传17世31王，延续约600年时间。相传商的始祖契曾帮助禹治水有功而受封于商（今河南商丘），以后就以“商”来称其部落（或部族）。汤灭夏后，就以“商”作为国号。其后裔盘庚迁殷（今河南安阳西北）后，首都没有再变化过，故又以称“殷朝”或“殷商”。二十世纪初，王国维通过甲骨研究，佐证了《殷本纪》的可信性。', '', '殷的始祖是契（xiè谢），他的母亲叫简狄，是有娀（sōng松）氏的女儿，帝喾（kù酷）的次妃。简狄等三个人到河里去洗澡，看见燕子掉下一只蛋，简狄就拣来吞吃了，因而怀孕，生下了契。契长大成人后，帮助禹治水有功，舜帝于是命令契说：“现在老百姓们不相亲爱，父子、君臣、夫妇、长幼、朋友之间五伦关系不顺，你去担任司徒，认真地施行五伦教育。施行五伦教育，要本着宽厚的原则。”契被封在商地，赐姓子。契在唐尧、虞舜、夏禹的时代兴起，为百姓做了许多事，功业昭著，百姓们因而得以安定。
契死之后，他的儿子昭明继位。昭明死后，儿子相土继位。相土死后，儿子昌若继位。昌若死后，儿子曹圉（yǔ语）继位。曹圉死后，儿子冥继位。冥死后，儿子振继位。振死后，儿子微继位。微死后，儿子报丁继位。报丁死后，儿子报乙继位。报乙死后，儿子报丙继位。报丙死后，儿子主壬继位。主壬死后，儿子主癸继位。主癸死后，儿子天乙继位。这就是成汤。
从契到成汤，曾经八次迁都。到成汤时才又定居于亳，这是为了追随先王帝喾，重回故地。成汤为此写了《帝诰》，向帝喾报告迁都的情况。
成汤在夏朝为方伯（一方诸侯之长），有权征讨邻近的诸侯。葛伯不祭祀鬼神，成汤首先征讨他。成汤说：“我说过这样的话：人照一照水就能看出自己的形貌，看一看民众就可以知道国家治理得好与不好。”伊尹说：“英明啊！善言听得进去，道德才会进步。治理国家，抚育万民，凡是有德行做好事的人都要任用为朝廷之官。努力吧，努力吧！”成汤对葛伯说：“你们不能敬顺天命，我就要重重地惩罚你们，概不宽赦。”于是写下《汤征》，记载了征葛的情况。
伊尹名叫阿衡。阿衡想求见成汤而苦于没有门路，于是就去给有莘氏做陪嫁的男仆，背着饭锅砧板来见成汤，借着谈论烹调滋味的机会向成汤进言，劝说他实行王道。也有人说，伊尹本是个有才德而不肯做官的隐士，成汤曾派人去聘迎他，前后去了五趟，他才答应前来归从，向成汤讲述了远古帝王及九类君主的所做所为。成汤于是举用了他，委任他管理国政。伊尹曾经离开商汤到夏桀那里，因为看到夏桀无道，十分憎恶，所以又回到了商都亳。他从北门进城时，遇见了商汤的贤臣女（rǔ汝）鸠和女房，于是写下《女鸠》、《女房》，述说他离开夏桀重回商都时的心情。
一天成汤外出游猎，看见郊野四面张着罗网，张网的人祝祷说：“愿从天上来的，从地下来的，从四方来的，都进入我的罗网！”成汤听了说：“嗳，这样就把禽兽全部打光了！”于是把罗网撤去三面，让张网的人祝祷说：“想往左边走的就往左边走，想向右边逃的就向右边逃。不听从命令的，就进我的罗网吧。”诸侯听到这件事，都说：“汤真是仁德到极点了，就连禽兽都受到了他的恩惠。”
就在这个时候，夏桀却施行暴政，荒淫无道，还有诸侯昆吾氏也起来作乱，商汤于是举兵，率领诸侯，由伊尹跟随。商汤亲自握着大斧指挥，先去讨伐昆吾，转而又去讨伐夏桀。商汤说：“来，你们众人，到这儿来，都仔细听着我的话：不是我个人敢于兴兵作乱，是因为夏桀犯下了很多的罪行。我虽然也听到你们说了一些抱怨的话，可是夏桀有罪啊，我畏惧上天，不敢不去征伐。如今夏桀犯下了那么多的罪行，是上天命令我去惩罚他的。现在你们众人说：‘我们的国君不体恤我们，抛开我们的农事不管，却要去征伐打仗。’你们或许还会问：‘夏桀有罪，他的罪行究竟怎么样？’夏桀君臣大徭役，耗尽了夏国的民力；又重加盘剥，掠光了夏国的资财。夏国的民众都在怠工，不与他合作。他们说‘这个太阳什么时候消灭，我宁愿和你一起灭亡’！夏王的德行已经到这种地步，现在我一定要去讨伐他！希望你们和我一起来奉行上天降下的惩罚，我会重重地奖赏你们。你们不要怀疑，我绝不会说话不算数。如果你们违抗我的誓言，我就要惩罚你们，概不宽赦！”商汤把这些话告诉传令长官，写下了《汤誓》。当时商汤曾说“我很勇武”，因此号称武王。
夏桀在有娀氏旧地被打败，奔逃到鸣条，夏军就全军崩溃了。商汤乘胜追击，进攻忠于夏桀的三（zōng宗），缴获了他们的宝器珠玉，义伯、仲伯二臣写下了《典宝》，因为这是国家的固定财宝。商汤灭夏之后，想换掉夏的社神，可是社神是远古共公氏之子句龙，能平水土，还没有谁比得上他，所以没有换成，于是写下《夏社》，说明夏社不可换的道理。伊尹向诸侯公布了这次大战的战绩，自此，诸侯全都听命归服了，商汤登上天子之位，平定了天下。
成汤班师回朝，途经泰卷时，中垒（huǐ悔）作了朝廷的诰命。汤废除了夏的政令，回到国都亳，作《汤诰》号令诸侯。《汤诰》这样记载：“三月，殷王亲自到了东郊，向各诸侯国君宣布：‘各位可不能不为民众谋立功业，要努力办好你们的事情。否则，我就对你们严加惩办，那时可不要怪罪我。’又说：‘过去禹、皋陶长期奔劳在外，为民众建立了功业，民众才得以安居乐业。当时他们东面治理了长江，北而治理了济河，西面治理了黄河，南面治理了淮河，这四条重要的河道治理好了，万民才得以定居下来。后稷教导民众播种五谷，民众才知道种植各种庄稼。这三位古人都对民众有功，所以，他们的后代能够建国立业。也有另外的情况：从前蚩尤和他的大臣们在百姓中发动暴乱，上帝就不降福于他们，这样的事在历史上是有过的。先王的教诲，可不能不努力照办啊！’又说：‘你们当中如果有谁干出违背道义的事，那就不允许他回国再当诸侯，那时你们也不要怨恨我。’”汤用这些话告诫了诸侯。这时，伊尹又作了《咸有一德》，说明君臣都应该有纯一的品德；咎单作了《明居》，讲的是民众应该遵守的法则。
商汤临政之后，修改的历法，把夏历的寅月为岁首改为丑月为岁首，又改变了器物服饰的颜色，崇尚白色，在白天举行朝会。
商汤逝世之后，因为太子太丁未能即位而早亡，就立太丁弟外丙为帝，这就是外丙帝。外丙即位三年，逝世，立外丙的弟弟中壬为帝，这就是中壬帝。中壬即位四年，逝世，伊尹就拥立太丁之子太甲为帝。太甲，是成汤的嫡长孙，就是太甲帝。太甲元年，伊尹为谏训太甲，作了《伊训》、《肆命》、《徂后》。
太甲帝临政三年之后，昏乱暴虐，违背了汤王的法度，败坏了德业，因此，伊尹把他流放到汤的葬地桐宫。此后的三年，伊尹代行政务，主持国事，朝会诸侯。
太甲在桐宫住了三年，悔过自责，重新向善，于是伊尹又迎接他回到朝廷，把政权交还给他。从此以后，太甲帝修养道德，诸侯都来归服，百姓也因此得以安宁。伊尹对太甲帝很赞赏，就作了《太甲训》三篇，赞扬帝太甲，称他为太宗。
太宗逝世后，儿子沃丁即位。沃丁临政的时候，伊尹去逝了。在亳地安葬了伊尹之后，为了用伊尹的事迹垂训后人，咎单作了《沃丁》。
沃丁逝世，他的弟弟太庚即位，这就是太庚帝。太庚逝世，儿子小甲即位；小甲帝逝世，弟弟雍已即位，这就是雍已帝。到了这个时候，殷朝的国势已经衰弱，有的诸侯就不来朝见了。
雍已逝世，他的弟弟太戊即位。这就是太戊帝。太戊任用伊陟（zhì治）为相。当时国都亳出现了桑树和楮（chǔ储）树合生在朝堂上的怪异现象，一夜之间就长得有一搂粗。太戊帝很害怕，就去向伊陟询问。伊陟对太戊帝说：“我曾经听说，妖异不能战胜有德行的人，会不会是您的政治有什么失误啊？希望您进一步修养德行。”太戊听从了伊陟的规谏，那怪树就枯死而消失了。伊陟把这些话告诉了巫咸。巫咸治理朝政有成绩，写下《咸艾（yì义）》、《太戊》，记载了巫咸治理朝政的功绩，颂扬了太戊帝的从谏修德。太戊帝在太庙中称赞伊陟，说不能像对待其他臣下一样对待他。伊陟谦让不从，写下《原命》，为的是重新解释太戊之命。就这样，殷的国势再度兴盛，诸侯又来归服。因此，称太戊帝为中宗。
中宗逝世，儿子中丁继位。中丁帝迁都于隞（áo熬）。后来河亶（dàn旦）甲定都于相，祖乙又迁至邢。中丁帝逝世，他的弟弟外壬即位，这就是外壬帝。这些曾有《仲丁》加以记载，但现已残佚不存。外壬帝逝世后，他的弟弟河亶甲即位，这就是河亶甲帝。河亶甲时，殷朝国势再度衰弱。
河亶甲逝世，他的儿子祖乙即位。祖乙帝即位后，殷又兴盛起来，巫咸被任以重职。
祖乙逝世，他的儿子祖辛帝即位。祖辛帝逝世，他的弟弟沃甲即位，这就是沃甲帝。沃甲逝世，立沃甲之兄祖辛的儿子祖丁，这就是祖丁帝。祖丁逝世，立弟弟沃甲的儿子南庚，这就是南庚帝。南庚帝逝世，立祖丁帝的儿子阳甲，这就是阳甲帝。阳甲帝在位的时候，殷的国势衰弱了。
自中丁帝以来，废除嫡长子继位制而拥立诸弟兄及诸弟兄的儿子，这些人有时为取得王位而互相争斗，造成了连续九代的混乱，因此，诸侯没有人再来朝见。
阳甲帝逝世，他的弟弟盘庚继位。盘庚即位时，殷朝已在黄河以北的奄地定都，盘庚渡过黄河，在黄河以南的亳定都，又回到成汤的故居。因为自汤到盘庚，这已是第五次迁移了，一直没有固定国都，所以殷朝的民众一个个怨声载道，不愿再受迁移之苦。盘庚见此情况，就告谕诸侯大臣说：“从前先王成汤和你们的祖辈们一起平定天下，他们传下来的法度和准则应该遵循。如果我们舍弃这些而不努力推行，那怎么能成就德业呢？”这样，最后才渡过黄河，南迁到亳，修缮了成汤的故宫，遵行成汤的政令。此后百姓们渐渐安定，殷朝的国势又一次兴盛起来。因为盘庚遵循了成汤的德政，诸侯也纷纷前来朝见了。
盘庚帝逝世，他的弟弟小辛即位，这就是小辛帝。小辛在位时，殷又衰弱了。百姓们思念盘庚，于是写下了《盘庚》三篇。小辛帝逝世以后，他的弟弟小乙即位，这就是小乙帝。
小乙帝逝世，他的儿子武丁即位。武丁帝即位后，想复兴殷朝，但一直没有找到称职的辅佑大臣。于是武丁三年不发表政见，政事由冢宰决定，自己审慎地观察国家的风气。有一天夜里他梦见得到一位圣人，名叫说（yuè悦）。白天他按照梦中见到的形象观察群臣百官，没有一个像是那圣人。于是派百官到民间去四处寻找，终于在傅险找到了说。这时候，说正服刑役，在傅险修路，百官把说带来让武丁看，武丁说正是这个人。找到说之后，武丁和他交谈，发现果真是位贤圣之人，就举用他担任国相，殷国得到了很好的治理。因而用傅险这个地名来作说的姓，管他叫傅说。
有一次武丁祭祀成汤，第二天，有一只野鸡飞来登在鼎耳上鸣叫，武丁为此惊惧不安。祖己说：“大王不必担忧，先办好政事。”祖己进一步开导武丁说：“上天监察下民是着眼于他们的道义。上天赐给人的寿运有长有短，并不是上天有意使人的寿运夭折，中途断送性命。有的人不遵循道德，不承认罪恶，等到上天降下命令纠正他的德行了，他才想起来说‘怎么办’。唉，大王您继承王位，努力办好民众的事，没有什么不符合天意的，还要继续按常规祭祀，不要根据那些应该抛弃的邪道举行各种礼仪！”武丁听了祖己的劝谏，修行德政，全国上下都高兴，殷朝的国势又兴盛了。
武丁帝逝世，他的儿子祖庚帝即位。祖己赞赏武丁因为象征吉凶的野鸡出现而行德政，给他立庙，称为高宗，写下了《高宗肜（róng荣）日》和《高宗之训》。
祖庚帝逝世，他的弟弟祖甲即位，这就是甲帝。甲帝淫乱，殷朝再度衰落。
甲帝逝世，他的儿子廪辛即位。廪辛逝世，他的弟弟庚丁即位，这就是帝庚丁。庚丁逝世，他的儿子武乙即位，这时，殷都又从亳迁到了黄河以北。
武乙暴虐无道，曾经制作了一个木偶人，称它为天神，跟它下棋赌输赢，让旁人替它下子。如果天神输了，就侮辱它。又制作了一个皮革的囊袋，里面盛满血，仰天射它，说这是“射天”。有一次武乙到黄河和渭河之间去打猎，天空中突然打雷，武乙被雷击死。武乙死后，他的儿子太丁帝即位。太丁帝逝世，他的儿子乙帝即位，乙帝即位时，殷朝更加衰落了。
乙帝的长子叫微子启。启的母亲地位低贱，因而启不能继承帝位。乙帝的小儿子叫辛，辛的母亲是正王后，因而辛被立为继承人。乙帝逝世后，辛继位，这就是辛帝，天下都管他叫“纣”，因为谥法上“纣”表示残义损善。
纣天资聪颖，有口才，行动迅速，接受能力很强，而且气力过人，能徒手与猛兽格斗。他的智慧足可以拒绝臣下的谏劝，他的话语足可以掩饰自己的过错。他凭着才能在大臣面前夸耀，凭着声威到处抬高自己，认为天下所有的人都比不上他。他嗜好喝酒，放荡作乐，宠爱女人。他特别宠爱妲己，一切都听从妲己的。他让乐师涓为他制作了新的俗乐，北里舞曲，柔弱的歌。他加重赋税，把鹿台钱库的钱堆得满满的，把钜桥粮仓的粮食装得满满的。他多方搜集狗马和新奇的玩物，填满了宫室，又扩建沙丘的园林楼台，捕捉大量的野兽飞鸟，放置在里面。他对鬼神傲慢不敬。他招来大批戏乐，聚集在沙丘，用酒当做池水，把肉悬挂起来当做树林，让男女赤身裸体，在其间追逐戏闹，饮酒寻欢，通宵达旦。
纣如此荒淫无度，百姓们怨恨他，诸侯有的也背叛了他。于是他就加重刑罚，设置了叫做炮格的酷刑，让人在涂满油的铜柱上爬行，下面点燃炭火，爬不动了就掉在炭火里。纣任用西伯昌、九侯、鄂侯为三公。九侯有个美丽的女儿，献给了纣，她不喜淫荡，纣大怒，杀了她，同时把九侯也施以醢（hǎi海）刑，剁成肉酱。鄂侯极力强谏，争辩激烈，结果鄂侯也遭到脯（fǔ斧）刑，被制成肉干。西伯昌闻见此事，暗暗叹息。崇侯虎得知，向纣去告发，纣就把西伯囚禁在羑（yǒu有）里。西伯的僚臣闳（hóng宏）夭等人，找来了美女奇物和好马献给纣，纣才释放了西伯。西伯从狱里出来之后，向纣献出洛水以西的一片土地，请求废除炮格的酷刑。纣答允了他，并赐给他弓箭大斧，使他能够征伐其他诸侯，这样他就成了西部地区的诸侯之长，就是西伯。纣任用费仲管理国家政事。费仲善于阿谀，贪图财利，殷国人因此不来亲近了。纣又任用恶来，恶来善于毁谤，喜进谗言，诸侯因此越发疏远了。
西伯回国，暗地里修养德行，推行善政，诸侯很多背叛了纣而来归服西伯。西伯的势力更加强大，纣因此渐渐丧失了权势。王子比干劝说纣，纣不听。商容是一个有才德的人，百姓们敬爱他，纣却黜免了他。等到西伯攻打饥国并把它灭掉了，纣的大臣祖伊听说后既怨恨周国，又非常害怕，于是跑到纣那里去报告说：“上天已经断绝了我们殷国的寿运了。不管是能知天吉凶的人预测，还是用大龟占卜，都没有一点好征兆。我想并非是先王不帮助我们后人，而是大王您荒淫暴虐，以致自绝于天，所以上天才抛弃我们，使我们不得安食，而您既不揣度了解天意，又不遵循常法。如今我国的民众没有不希望殷国早早灭亡的，他们说：‘上天为什么还不显示你的威灵？灭纣的命令为什么还不到来？’大王您如今想怎么办呢？”纣说：“我生下来做国君，不就是奉受天命吗？”祖伊回国后说：“纣已经无法规劝了！”西伯昌死后，周武王率军东征，到达盟津时，诸侯背叛殷纣前来与武王会师的有八百国。诸侯们都说：“是讨伐纣的时候了！”周武王说：“你们不了解天命。”于是又班师回国了。
纣更加淫乱，毫无止息。微子曾多次劝谏，纣都不听，微子就和太师、少师商量，然后逃离了殷国。比干却说：“给人家做臣子，不能不拚死争谏。”就极力劝谏。纣大怒，说：“我听说圣人的心有七个孔。”于是剖开比干的胸膛，挖出心来观看。箕子见此情形很害怕，就假装疯癫去给人家当了奴隶。纣知道后又把箕子囚禁起来。殷国的太师、少师拿着祭器、乐器，急急逃到周国。周武王见时机已到，就率领诸侯讨伐殷纣。纣派出军队在牧野进行抵抗。周历二月初五甲子那一天，纣的军队被打败，纣仓皇逃进内城，登上鹿台，穿上他的宝玉衣，跑到火里自焚而死。周武王赶到，砍下他的头，挂在太白旗竿上示众。周武王又处死了妲己，释放了箕子，修缮了比干的坟墓，表彰了商容的里巷。封纣的儿子武庚禄父，让他承续殷的祭祀，并责令他施行盘庚的德政，殷的民众非常高兴。于是，周武王做了天子。因为后世人贬低帝这个称号，所以称为王。封殷的后代为诸侯，隶属于周。
周武王逝世后，武庚和管叔、蔡叔联合叛乱，周成王命周公旦诛杀他们，而把微子封在宋国，来延续殷的后代。
太史公说：我是根据《诗经》中的《商颂》来编定契的事迹的，自成汤以来，很多史实材料采自《尚书》和《诗经》。契为子姓，他的后代被分封到各国，就以国为姓了，有殷氏、来氏、宋氏、空桐氏、稚氏、北殷氏、目夷氏等。孔子曾经说过，殷人的车子很好，那个时代崇尚白色。', '[{"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3d6f6542516c6dede5a", "shortContent": "历史的演变，国家的兴衰，是社会内在合力的具体表征。但不可否认的是，处于权力中心的历史关键人物，其个人力量也不容轻易忽视，他们对历史发展之迟速，往往具有较大的影响力。旧时代的史家，通常将民心向背问题视为政治成败得失之关键，“得民心者得天下”，也就成了一句妇孺皆知的政治箴言。而民心依附与否，则要看当政者是否德才兼备，能否身体力行。所以，“家天下”体制下的君王，其道德言行便成了旧史家关注与热议的焦点。《...", "authors": ["陈絜"], "pressName": "上海辞书出版社"}]', '', 'indent', 1525123407, '5ae718c99f5454003f237157', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637436, '史记 · 十二本纪 · 周本纪', NULL, 5, 139, 0, 1, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E5%91%A8%E6%9C%AC%E7%BA%AA/2390597?fr=aladdin', '', '周后稷，名弃。其母有邰氏女，曰姜原。姜原为帝喾元妃。姜原出野，见巨人迹，心欣然说，欲践之，践之而身动如孕者。居期而生子，以为不祥，弃之隘巷，马牛过者皆辟不践；徙置之林中，适会山林多人，迁之；而弃渠中冰上，飞鸟以其翼覆荐之。姜原以为神，遂收养长之。初欲弃之，因名曰弃。
弃为儿时，屹如巨人之志。其游戏，好种树麻、菽，麻、菽美。及为成人，遂好耕农，相地之宜，宜穀者稼穑焉，民皆法则之。帝尧闻之，举弃为农师，天下得其利，有功。帝舜曰：“弃，黎民始饥，尔后稷播时百穀。”封弃于邰，号曰后稷，别姓姬氏。后稷之兴，在陶唐、虞、夏之际，皆有令德。
后稷卒，子不窋立。不窋末年，夏后氏政衰，去稷不务，不窋以失其官而饹戎狄之间。不窋卒，子鞠立。鞠卒，子公刘立。公刘虽在戎狄之间，复修后稷之业，务耕种，行地宜，自漆、沮度渭，取材用，行者有资，居者有畜积，民赖其庆。百姓怀之，多徙而保归焉。周道之兴自此始，故诗人歌乐思其德。公刘卒，子庆节立，国于豳。
庆节卒，子皇仆立。皇仆卒，子差弗立。差弗卒，子毁隃立。毁隃卒，子公非立。公非卒，子高圉立。高圉卒，子亚圉立。亚圉卒，子公叔祖类立。公叔祖类卒，子古公亶父立。古公亶父复修后稷、公刘之业，积德行义，国人皆戴之。薰育戎狄攻之，欲得财物，予之。已复攻，欲得地与民。民皆怒，欲战。古公曰：“有民立君，将以利之。今戎狄所为攻战，以吾地与民。民之在我，与其在彼，何异。民欲以我故战，杀人父子而君之，予不忍为。”乃与私属遂去豳，度漆、沮，逾梁山，止于岐下。豳人举国扶老携弱，尽复归古公于岐下。及他旁国闻古公仁，亦多归之。于是古公乃贬戎狄之俗，而营筑城郭室屋，而邑别居之。作五官有司。民皆歌乐之，颂其德。
古公有长子曰太伯，次曰虞仲。太姜生少子季历，季历娶太任，皆贤妇人，生昌，有圣瑞。古公曰：“我世当有兴者，其在昌乎？”长子太伯、虞仲知古公欲立季历以传昌，乃二人亡如荆蛮，文身断发，以让季历。
古公卒，季历立，是为公季。公季修古公遗道，笃于行义，诸侯顺之。
公季卒，子昌立，是为西伯。西伯曰文王，遵后稷、公刘之业，则古公、公季之法，笃仁，敬老，慈少。礼下贤者，日中不暇食以待士，士以此多归之。伯夷、叔齐在孤竹，闻西伯善养老，盍往归之。太颠、闳夭、散宜生、鬻子、辛甲大夫之徒皆往归之。
崇侯虎谮西伯于殷纣曰：“西伯积善累德，诸侯皆向之，将不利于帝。”帝纣乃囚西伯于羑里。闳夭之徒患之。乃求有莘氏美女，骊戎之文马，有熊九驷，他奇怪物，因殷嬖臣费仲而献之纣。纣大说，曰：“此一物足以释西伯，况其多乎！”乃赦西伯，赐之弓矢斧钺，使西伯得征伐。曰：“谮西伯者，崇侯虎也。”西伯乃献洛西之地，以请纣去炮格之刑。纣许之。
西伯阴行善，诸侯皆来决平。于是虞、芮之人有狱不能决，乃如周。入界，耕者皆让畔，民俗皆让长。虞、芮之人未见西伯，皆惭，相谓曰：“吾所争，周人所耻，何往为，祇取辱耳。”遂还，俱让而去。诸侯闻之，曰“西伯盖受命之君”。
明年，伐犬戎。明年，伐密须。明年，败耆国。殷之祖伊闻之，惧，以告帝纣。纣曰：“不有天命乎？是何能为！”明年，伐邘。明年，伐崇侯虎。而作丰邑，自岐下而徙都丰。明年，西伯崩，太子发立，是为武王。
西伯盖即位五十年。其囚羑里，盖益易之八卦为六十四卦。诗人道西伯，盖受命之年称王而断虞芮之讼。后十年而崩，谥为文王。改法度，制正朔矣。追尊古公为太王，公季为王季：盖王瑞自太王兴。
武王即位，太公望为师，周公旦为辅，召公、毕公之徒左右王，师修文王绪业。
九年，武王上祭于毕。东观兵，至于盟津。为文王木主，载以车，中军。武王自称太子发，言奉文王以伐，不敢自专。乃告司马、司徒、司空、诸节：“齐栗，信哉！予无知，以先祖有德臣，小子受先功，毕立赏罚，以定其功。”遂兴师。师尚父号曰：“总尔众庶，与尔舟楫，后至者斩。”武王渡河，中流，白鱼跃入王舟中，武王俯取以祭。既渡，有火自上复于下，至于王屋，流为乌，其色赤，其声魄云。是时，诸侯不期而会盟津者八百诸侯。诸侯皆曰：“纣可伐矣。”武王曰：“女未知天命，未可也。”乃还师归。
居二年，闻纣昏乱暴虐滋甚，杀王子比干，囚箕子。太师疵、少师彊抱其乐器而饹周。于是武王遍告诸侯曰：“殷有重罪，不可以不毕伐。”乃遵文王，遂率戎车三百乘，虎贲三千人，甲士四万五千人，以东伐纣。十一年十二月戊午，师毕渡盟津，诸侯咸会。曰：“孳孳无怠！”武王乃作太誓，告于众庶：“今殷王纣乃用其妇人之言，自绝于天，毁坏其三正，离逷其王父母弟，乃断弃其先祖之乐，乃为淫声，用变乱正声，怡说妇人。故今予发维共行天罚。勉哉夫子，不可再，不可三！”
二月甲子昧爽，武王朝至于商郊牧野，乃誓。武王左杖黄钺，右秉白旄，以麾。曰：“远矣西土之人！”武王曰：“嗟！我有国冢君，司徒、司马、司空，亚旅、师氏，千夫长、百夫长，及庸、蜀、羌、髳、微、纑、彭、濮人，称尔戈，比尔干，立尔矛，予其誓。”王曰：“古人有言‘牝鸡无晨。牝鸡之晨，惟家之索’。今殷王纣维妇人言是用，自弃其先祖肆祀不答，昏弃其家国，遗其王父母弟不用，乃维四方之多罪逋逃是崇是长，是信是使，俾暴虐于百姓，以奸轨于商国。今予发维共行天之罚。今日之事，不过六步七步，乃止齐焉，夫子勉哉！不过于四伐五伐六伐七伐，乃止齐焉，勉哉夫子！尚桓桓，如虎如罴，如豺如离，于商郊，不御克饹，以役西土，勉哉夫子！尔所不勉，其于尔身有戮。”誓已，诸侯兵会者车四千乘，陈师牧野。帝纣闻武王来，亦发兵七十万人距武王。武王使师尚父与百夫致师，以大卒驰帝纣师。纣师虽众，皆无战之心，心欲武王亟入。纣师皆倒兵以战，以开武王。武王驰之，纣兵皆崩畔纣。纣走，反入登于鹿台之上，蒙衣其殊玉，自燔于火而死。武王持大白旗以麾诸侯，诸侯毕拜武王，武王乃揖诸侯，诸侯毕从。武王至商国，商国百姓咸待于郊。于是武王使群臣告语商百姓曰：“上天降休！”商人皆再拜稽首，武王亦答拜。遂入，至纣死所。武王自射之，三发而后下车，以轻剑击之，以黄钺斩纣头，县大白之旗。已而至纣之嬖妾二女，二女皆经自杀。武王又射三发，击以剑，斩以玄钺，县其头小白之旗。武王已乃出复军。
其明日，除道，修社及商纣宫。及期，百夫荷罕旗以先驱。武王弟叔振铎奉陈常车，周公旦把大钺，毕公把小钺，以夹武王。散宜生、太颠、闳夭皆执剑以卫武王。既入，立于社南大卒之左，右毕从。毛叔郑奉明水，卫康叔封布兹，召公奭赞采，师尚父牵牲。尹佚策祝曰：“殷之末孙季纣，殄废先王明德，侮蔑神祇不祀，昏暴商邑百姓，其章显闻于天皇上帝。”于是武王再拜稽首，曰：“膺更大命，革殷，受天明命。”武王又再拜稽首，乃出。
封商纣子禄父殷之馀民。武王为殷初定未集，乃使其弟管叔鲜、蔡叔度相禄父治殷。已而命召公释箕子之囚。命毕公释百姓之囚，表商容之闾。命南宫括散鹿台之财，发钜桥之粟，以振贫弱萌隶。命南宫括、史佚展九鼎保玉。命闳夭封比干之墓。命宗祝享祠于军。乃罢兵西归。行狩，记政事，作武成。封诸侯，班赐宗彝，作分殷之器物。武王追思先圣王，乃襃封神农之后于焦，黄帝之后于祝，帝尧之后于蓟，帝舜之后于陈，大禹之后于杞。于是封功臣谋士，而师尚父为首封。封尚父于营丘，曰齐。封弟周公旦于曲阜，曰鲁。封召公奭于燕。封弟叔鲜于管，弟叔度于蔡。馀各以次受封。
武王徵九牧之君，登豳之阜，以望商邑。武王至于周，自夜不寐。周公旦即王所，曰：“曷为不寐？”王曰：“告女：维天不飨殷，自发未生于今六十年，麋鹿在牧，蜚鸿满野。天不享殷，乃今有成。维天建殷，其登名民三百六十夫，不显亦不宾灭，以至今。我未定天保，何暇寐！”王曰：“定天保，依天室，悉求夫恶，贬从殷王受。日夜劳来定我西土，我维显服，及德方明。自洛汭延于伊汭，居易毋固，其有夏之居。我南望三涂，北望岳鄙，顾詹有河，粤詹雒、伊，毋远天室。”营周居于雒邑而后去。纵马于华山之阳，放牛于桃林之虚；偃干戈，振兵释旅：示天下不复用也。
武王已克殷，后二年，问箕子殷所以亡。箕子不忍言殷恶，以存亡国宜告。武王亦丑，故问以天道。
武王病。天下未集，群公惧，穆卜，周公乃祓斋，自为质，欲代武王，武王有瘳。后而崩，太子诵代立，是为成王。
成王少，周初定天下，周公恐诸侯畔周，公乃摄行政当国。管叔、蔡叔群弟疑周公，与武庚作乱，畔周。周公奉成王命，伐诛武庚、管叔，放蔡叔。以微子开代殷后，国于宋。颇收殷馀民，以封武王少弟封为卫康叔。晋唐叔得嘉穀，献之成王，成王以归周公于兵所。周公受禾东土，鲁天子之命。初，管、蔡畔周，周公讨之，三年而毕定，故初作大诰，次作微子之命，次归禾，次嘉禾，次康诰、酒诰、梓材，其事在周公之篇。周公行政七年，成王长，周公反政成王，北面就群臣之位。
成王在丰，使召公复营洛邑，如武王之意。周公复卜申视，卒营筑，居九鼎焉。曰：“此天下之中，四方入贡道里均。”作召诰、洛诰。成王既迁殷遗民，周公以王命告，作多士、无佚。召公为保，周公为师，东伐淮夷，残奄，迁其君薄姑。成王自奄归，在宗周，作多方。既绌殷命，袭淮夷，归在丰，作周官。兴正礼乐，度制于是改，而民和睦，颂声兴。成王既伐东夷，息慎来贺，王赐荣伯作贿息慎之命。
成王将崩，惧太子钊之不任，乃命召公、毕公率诸侯以相太子而立之。成王既崩，二公率诸侯，以太子钊见于先王庙，申告以文王、武王之所以为王业之不易，务在节俭，毋多欲，以笃信临之，作顾命。太子钊遂立，是为康王。康王即位，遍告诸侯，宣告以文武之业以申之，作康诰。故成康之际，天下安宁，刑错四十馀年不用。康王命作策毕公分居里，成周郊，作毕命。
康王卒，子昭王瑕立。昭王之时，王道微缺。昭王南巡狩不返，卒于江上。其卒不赴告，讳之也。立昭王子满，是为穆王。穆王即位，春秋已五十矣。王道衰微，穆王闵文武之道缺，乃命伯臩申诫太仆国之政，作命。复宁。
穆王将征犬戎，祭公谋父谏曰：“不可。先王燿德不观兵。夫兵戢而时动，动则威，观则玩，玩则无震。是故周文公之颂曰：‘载戢干戈，载櫜弓矢，我求懿德，肆于时夏，允王保之。’先王之于民也，茂正其德而厚其性，阜其财求而利其器用，明利害之乡，以文修之，使之务利而辟害，怀德而畏威，故能保世以滋大。昔我先王世后稷以服事虞、夏。及夏之衰也，弃稷不务，我先王不窋用失其官，而自窜于戎狄之间。不敢怠业，时序其德，遵修其绪，修其训典，朝夕恪勤，守以敦笃，奉以忠信。奕世载德，不忝前人。至于文王、武王，昭前之光明而加之以慈和，事神保民，无不欣喜。商王帝辛大恶于民，庶民不忍，载武王，以致戎于商牧。是故先王非务武也，劝恤民隐而除其害也。夫先王之制，邦内甸服，邦外侯服，侯卫宾服，夷蛮要服，戎翟荒服。甸服者祭，侯服者祀，宾服者享，要服者贡，荒服者王。日祭，月祀，时享，岁贡，终王。先王之顺祀也，有不祭则修意，有不祀则修言，有不享则修文，有不贡则修名，有不王则修德，序成而有不至则修刑。于是有刑不祭，伐不祀，征不享，让不贡，告不王。于是有刑罚之辟，有攻伐之兵，有征讨之备，有威让之命，有文告之辞。布令陈辞而有不至，则增修于德，无勤民于远。是以近无不听，远无不服。今自大毕、伯士之终也，犬戎氏以其职来王，天子曰‘予必以不享征之，且观之兵’，无乃废先王之训，而王几顿乎？吾闻犬戎树敦，率旧德而守终纯固，其有以御我矣。”王遂征之，得四白狼四白鹿以归。自是荒服者不至。
诸侯有不睦者，甫侯言于王，作修刑辟。王曰：“吁，来！有国有土，告汝祥刑。在今尔安百姓，何择非其人，何敬非其刑，何居非其宜与？两造具备，师听五辞。五辞简信，正于五刑。五刑不简，正于五罚。五罚不服，正于五过。五过之疵，官狱内狱，阅实其罪，惟钧其过。五刑之疑有赦，五罚之疑有赦，其审克之。简信有众，惟讯有稽。无简不疑，共严天威。黥辟疑赦，其罚百率，阅实其罪。劓辟疑赦，其罚倍洒，阅实其罪。膑辟疑赦，其罚倍差，阅实其罪。宫辟疑赦，其罚五百率，阅实其罪。大辟疑赦，其罚千率，阅实其罪。墨罚之属千，劓罚之属千，膑罚之属五百，宫罚之属三百，大辟之罚其属二百：五刑之属三千。”命曰甫刑。
穆王立五十五年，崩，子共王繄扈立。共王游于泾上，密康公从，有三女饹之。其母曰：“必致之王。夫兽三为群，人三为众，女三为粲。王田不取群，公行不下众，王御不参一族。夫粲，美之物也。众以美物归女，而何德以堪之？王犹不堪，况尔之小丑乎！小丑备物，终必亡。”康公不献，一年，共王灭密。共王崩，子懿王畑立。懿王之时，王室遂衰，诗人作刺。
懿王崩，共王弟辟方立，是为孝王。孝王崩，诸侯复立懿王太子燮，是为夷王。
夷王崩，子厉王胡立。厉王即位三十年，好利，近荣夷公。大夫芮良夫谏厉王曰：“王室其将卑乎？夫荣公好专利而不知大难。夫利，百物之所生也，天地之所载也，而有专之，其害多矣。天地百物皆将取焉，何可专也？所怒甚多，不备大难。以是教王，王其能久乎？夫王人者，将导利而布之上下者也。使神人百物无不得极，犹日怵惕惧怨之来也。故颂曰‘思文后稷，克配彼天，立我蒸民，莫匪尔极’。大雅曰‘陈锡载周’。是不布利而惧难乎，故能载周以至于今。今王学专利，其可乎？匹夫专利，犹谓之盗，王而行之，其归鲜矣。荣公若用，周必败也。”厉王不听，卒以荣公为卿士，用事。
王行暴虐侈傲，国人谤王。召公谏曰：“民不堪命矣。”王怒，得卫巫，使监谤者，以告则杀之。其谤鲜矣，诸侯不朝。三十四年，王益严，国人莫敢言，道路以目。厉王喜，告召公曰：“吾能弭谤矣，乃不敢言。”召公曰：“是鄣之也。防民之口，甚于防水。水壅而溃，伤人必多，民亦如之。是故为水者决之使导，为民者宣之使言。故天子听政，使公卿至于列士献诗，瞽献曲，史献书，师箴，瞍赋，蒙诵，百工谏，庶人传语，近臣尽规，亲戚补察，瞽史教诲，耆艾修之，而后王斟酌焉，是以事行而不悖。民之有口也，犹土之有山川也，财用于是乎出：犹其有原隰衍沃也，衣食于是乎生。口之宣言也，善败于是乎兴。行善而备败，所以产财用衣食者也。夫民虑之于心而宣之于口，成而行之。若壅其口，其与能几何？”王不听。于是国莫敢出言，三年，乃相与畔，袭厉王。厉王出奔于彘。
厉王太子静匿召公之家，国人闻之，乃围之。召公曰：“昔吾骤谏王，王不从，以及此难也。今杀王太子，王其以我为雠而怼怒乎？夫事君者，险而不雠怼，怨而不怒，况事王乎！”乃以其子代王太子，太子竟得脱。
召公、周公二相行政，号曰“共和”。共和十四年，厉王死于彘。太子静长于召公家，二相乃共立之为王，是为宣王。宣王即位，二相辅之，修政，法文、武、成、康之遗风，诸侯复宗周。十二年，鲁武公来朝。
宣王不修籍于千亩，虢文公谏曰不可，王弗听。三十九年，战于千亩，王师败绩于姜氏之戎。
宣王既亡南国之师，乃料民于太原。仲山甫谏曰：“民不可料也。”宣王不听，卒料民。
四十六年，宣王崩，子幽王宫湦立。幽王二年，西周三川皆震。伯阳甫曰：“周将亡矣。夫天地之气，不失其序；若过其序，民乱之也。阳伏而不能出，阴迫而不能蒸，于是有地震。今三川实震，是阳失其所而填阴也。阳失而在阴，原必塞；原塞，国必亡。夫水土演而民用也。土无所演，民乏财用，不亡何待！昔伊、洛竭而夏亡，河竭而商亡。今周德若二代之季矣，其川原又塞，塞必竭。夫国必依山川，山崩川竭，亡国之徵也。川竭必山崩。若国亡不过十年，数之纪也。天之所弃，不过其纪。”是岁也，三川竭，岐山崩。
三年，幽王嬖爱襃姒。襃姒生子伯服，幽王欲废太子。太子母申侯女，而为后。后幽王得襃姒，爱之，欲废申后，并去太子宜臼，以襃姒为后，以伯服为太子。周太史伯阳读史记曰：“周亡矣。”昔自夏后氏之衰也，有二神龙止于夏帝庭而言曰：“余，襃之二君。”夏帝卜杀之与去之与止之，莫吉。卜请其漦而藏之，乃吉。于是布币而策告之，龙亡而漦在，椟而去之。夏亡，传此器殷。殷亡，又传此器周。比三代，莫敢发之，至厉王之末，发而观之。漦流于庭，不可除。厉王使妇人裸而譟之。漦化为玄鼋，以入王后宫。后宫之童妾既龀而遭之，既笄而孕，无夫而生子，惧而弃之。宣王之时童女谣曰：“檿弧箕服，实亡周国。”于是宣王闻之，有夫妇卖是器者，宣王使执而戮之。逃于道，而见乡者后宫童妾所弃妖子出于路者，闻其夜啼，哀而收之，夫妇遂亡，饹于襃。襃人有罪，请入童妾所弃女子者于王以赎罪。弃女子出于襃，是为襃姒。当幽王三年，王之后宫见而爱之，生子伯服，竟废申后及太子，以襃姒为后，伯服为太子。太史伯阳曰：“祸成矣，无可奈何！”
襃姒不好笑，幽王欲其笑万方，故不笑。幽王为烽燧大鼓，有寇至则举烽火。诸侯悉至，至而无寇，襃姒乃大笑。幽王说之，为数举烽火。其后不信，诸侯益亦不至。
幽王以虢石父为卿，用事，国人皆怨。石父为人佞巧善谀好利，王用之。又废申后，去太子也。申侯怒，与缯、西夷犬戎攻幽王。幽王举烽火徵兵，兵莫至。遂杀幽王骊山下，虏襃姒，尽取周赂而去。于是诸侯乃即申侯而共立故幽王太子宜臼，是为平王，以奉周祀。
平王立，东迁于雒邑，辟戎寇。平王之时，周室衰微，诸侯彊并弱，齐、楚、秦、晋始大，政由方伯。
四十九年，鲁隐公即位。
五十一年，平王崩，太子洩父蚤死，立其子林，是为桓王。桓王，平王孙也。
桓王三年，郑庄公朝，桓王不礼。五年，郑怨，与鲁易许田。许田，天子之用事太山田也。八年，鲁杀隐公，立桓公。十三年，伐郑，郑射伤桓王，桓王去归。
二十三年，桓王崩，子庄王佗立。庄王四年，周公黑肩欲杀庄王而立王子克。辛伯告王，王杀周公。王子克饹燕。
十五年，庄王崩，子釐王胡齐立。釐王三年，齐桓公始霸。
五年，釐王崩，子惠王阆立。惠王二年。初，庄王嬖姬姚，生子穨，穨有宠。及惠王即位，夺其大臣园以为囿，故大夫边伯等五人作乱，谋召燕、卫师，伐惠王。惠王饹温，已居郑之栎。立釐王弟穨为王。乐及遍舞，郑、虢君怒。四年，郑与虢君伐杀王穨，复入惠王。惠王十年，赐齐桓公为伯。
二十五年，惠王崩，子襄王郑立。襄王母蚤死，后母曰惠后。惠后生叔带，有宠于惠王，襄王畏之。三年，叔带与戎、翟谋伐襄王，襄王欲诛叔带，叔带饹齐。齐桓公使管仲平戎于周，使隰朋平戎于晋。王以上卿礼管仲。管仲辞曰：“臣贱有司也，有天子之二守国、高在。若节春秋来承王命，何以礼焉。陪臣敢辞。”王曰：“舅氏，余嘉乃勋，毋逆朕命。”管仲卒受下卿之礼而还。九年，齐桓公卒。十二年，叔带复归于周。
十三年，郑伐滑，王使游孙、伯服请滑，郑人囚之。郑文公怨惠王之入不与厉公爵，又怨襄王之与卫滑，故囚伯服。王怒，将以翟伐郑。富辰谏曰：“凡我周之东徙，晋、郑焉依。子穨之乱，又郑之由定，今以小怨弃之！”王不听。十五年，王降翟师以伐郑。王德翟人，将以其女为后。富辰谏曰：“平、桓、庄、惠皆受郑劳，王弃亲亲翟，不可从。”王不听。十六年，王绌翟后，翟人来诛，杀谭伯。富辰曰：“吾数谏不从。如是不出，王以我为怼乎？”乃以其属死之。
初，惠后欲立王子带，故以党开翟人，翟人遂入周。襄王出饹郑，郑居王于氾。子带立为王，取襄王所绌翟后与居温。十七年，襄王告急于晋，晋文公纳王而诛叔带。襄王乃赐晋文公珪鬯弓矢，为伯，以河内地与晋。二十年，晋文公召襄王，襄王会之河阳、践土，诸侯毕朝，书讳曰“天王狩于河阳”。
二十四年，晋文公卒。
三十一年，秦穆公卒。
三十二年，襄王崩，子顷王壬臣立。顷王六年，崩，子匡王班立。匡王六年，崩，弟瑜立，是为定王。定王元年，楚庄王伐陆浑之戎，次洛，使人问九鼎。王使王孙满应设以辞，楚兵乃去。十年，楚庄王围郑，郑伯降，已而复之。十六年，楚庄王卒。
二十一年，定王崩，子简王夷立。简王十三年，晋杀其君厉公，迎子周于周，立为悼公。
十四年，简王崩，子灵王泄心立。灵王二十四年，齐崔杼弑其君庄公。二十七年，灵王崩，子景王贵立。景王十八年，后太子圣而蚤卒。二十年，景王爱子朝，欲立之，会崩，子丐之党与争立，国人立长子猛为王，子朝攻杀猛。猛为悼王。晋人攻子朝而立丐，是为敬王。
敬王元年，晋人入敬王，子朝自立，敬王不得入，居泽。四年，晋率诸侯入敬王于周，子朝为臣，诸侯城周。十六年，子朝之徒复作乱，敬王饹于晋。十七年，晋定公遂入敬王于周。
三十九年，齐田常杀其君简公。
四十一年，楚灭陈。孔子卒。
四十二年，敬王崩，子元王仁立。元王八年，崩，子定王介立。
定王十六年，三晋灭智伯，分有其地。
二十八年，定王崩，长子去疾立，是为哀王。哀王立三月，弟叔袭杀哀王而自立，是为思王。思王立五月，少弟嵬攻杀思王而自立，是为考王。此三王皆定王之子。
考王十五年，崩，子威烈王午立。
考王封其弟于河南，是为桓公，以续周公之官职。桓公卒，子威公代立。威公卒，子惠公代立，乃封其少子于巩以奉王，号东周惠公。
威烈王二十三年，九鼎震。命韩、魏、赵为诸侯。
二十四年，崩，子安王骄立。是岁盗杀楚声王。
安王立二十六年，崩，子烈王喜立。烈王二年，周太史儋见秦献公曰：“始周与秦国合而别，别五百载复合，合十七岁而霸王者出焉。”
十年，烈王崩，弟扁立，是为显王。显王五年，贺秦献公，献公称伯。九年，致文武胙于秦孝公。二十五年，秦会诸侯于周。二十六年，周致伯于秦孝公。三十三年，贺秦惠王。三十五年，致文武胙于秦惠王。四十四年，秦惠王称王。其后诸侯皆为王。
四十八年，显王崩，子慎靓王定立。慎靓王立六年，崩，子赧王延立。王赧时东西周分治。王赧徙都西周。
西周武公之共太子死，有五庶子，毋适立。司马剪谓楚王曰：“不如以地资公子咎，为请太子。”左成曰：“不可。周不听，是公之知困而交疏于周也。不如请周君孰欲立，以微告剪，剪请令楚之以地。”果立公子咎为太子。
八年，秦攻宜阳，楚救之。而楚以周为秦故，将伐之。苏代为周说楚王曰：“何以周为秦之祸也？言周之为秦甚于楚者，欲令周入秦也，故谓‘周秦’也。周知其不可解，必入于秦，此为秦取周之精者也。为王计者，周于秦因善之，不于秦亦言善之，以疏之于秦。周绝于秦，必入于郢矣。”
秦借道两周之间，将以伐韩，周恐借之畏于韩，不借畏于秦。史厌谓周君曰：“何不令人谓韩公叔曰‘秦之敢绝周而伐韩者，信东周也。公何不与周地，发质使之楚’？秦必疑楚不信周，是韩不伐也。又谓秦曰‘韩彊与周地，将以疑周于秦也，周不敢不受’。秦必无辞而令周不受，是受地于韩而听于秦。”
秦召西周君，西周君恶往，故令人谓韩王曰：“秦召西周君，将以使攻王之南阳也，王何不出兵于南阳？周君将以为辞于秦。周君不入秦，秦必不敢逾河而攻南阳矣。”
东周与西周战，韩救西周。或为东周说韩王曰：“西周故天子之国，多名器重宝。王案兵毋出，可以德东周，而西周之宝必可以尽矣。”
王赧谓成君。楚围雍氏，韩徵甲与粟于东周，东周君恐，召苏代而告之。代曰：“君何患于是。臣能使韩毋徵甲与粟于周，又能为君得高都。”周君曰：“子苟能，请以国听子。”代见韩相国曰：“楚围雍氏，期三月也，今五月不能拔，是楚病也。今相国乃徵甲与粟于周，是告楚病也。”韩相国曰：“善。使者已行矣。”五代曰：“何不与周高都？”韩相国大怒曰：“吾毋徵甲与粟于周亦已多矣，何故与周高都也？”代曰：“与周高都，是周折而入于韩也，秦闻之必大怒忿周，即不通周使，是以弊高都得完周也。曷为不与？”相国曰：“善。”果与周高都。
三十四年，苏厉谓周君曰：“秦破韩、魏，扑师武，北取赵蔺、离石者，皆白起也。是善用兵，又有天命。今又将兵出塞攻梁，梁破则周危矣。君何不令人说白起乎？曰‘楚有养由基者，善射者也。去柳叶百步而射之，百发而百中之。左右观者数千人，皆曰善射。有一夫立其旁，曰“善，可教射矣”。养由基怒，释弓搤剑，曰“客安能教我射乎”？客曰“非吾能教子支左诎右也。夫去柳叶百步而射之，百发而百中之，不以善息，少焉气衰力倦，弓拨矢钩，一发不中者，百发尽息”。今破韩、魏，扑师武，北取赵蔺、离石者，公之功多矣。今又将兵出塞，过两周，倍韩，攻梁，一举不得，前功尽弃。公不如称病而无出’。”
四十二年，秦破华阳约。马犯谓周君曰：“请令梁城周。”乃谓梁王曰：“周王病若死，则犯必死矣。犯请以九鼎自入于王，王受九鼎而图犯。”梁王曰：“善。”遂与之卒，言戍周。因谓秦王曰：“梁非戍周也，将伐周也。王试出兵境以观之。”秦果出兵。又谓梁王曰：“周王病甚矣，犯请后可而复之。今王使卒之周，诸侯皆生心，后举事且不信。不若令卒为周城，以匿事端。”梁王曰：“善。”遂使城周。
四十五年，周君之秦客谓周曰：“公不若誉秦王之孝，因以应为太后养地，秦王必喜，是公有秦交。交善，周君必以为公功。交恶，劝周君入秦者必有罪矣。”秦攻周，而周勣谓秦王曰：“为王计者不攻周。攻周，实不足以利，声畏天下。天下以声畏秦，必东合于齐。兵弊于周。合天下于齐，则秦不王矣。天下欲弊秦，劝王攻周。秦与天下弊，则令不行矣。”
五十八年，三晋距秦。周令其相国之秦，以秦之轻也，还其行。客谓相国曰：“秦之轻重未可知也。秦欲知三国之情。公不如急见秦王曰‘请为王听东方之变’，秦王必重公。重公，是秦重周，周以取秦也；齐重，则固有周聚以收齐：是周常不失重国之交也。”秦信周，发兵攻三晋。
五十九年，秦取韩阳城负黍，西周恐，倍秦，与诸侯约从，将天下锐师出伊阙攻秦，令秦无得通阳城。秦昭王怒，使将军摎攻西周。西周君饹秦，顿首受罪，尽献其邑三十六，口三万。秦受其献，归其君于周。
周君、王赧卒，周民遂东亡。秦取九鼎宝器，而迁西周公于黿狐。后七岁，秦庄襄王灭东周。东西周皆入于秦，周既不祀。
太史公曰：学者皆称周伐纣，居洛邑，综其实不然。武王营之，成王使召公卜居，居九鼎焉，而周复都丰、镐。至犬戎败幽王，周乃东徙于洛邑。所谓“周公葬毕”，毕在镐东南杜中。秦灭周。汉兴九十有馀载，天子将封泰山，东巡狩至河南，求周苗裔，封其后嘉三十里地，号曰周子南君，比列侯，以奉其先祭祀。
后稷居邰，太王作周。丹开雀录，火降乌流。三分既有，八百不谋。苍兕誓众，白鱼入舟。太师抱乐，箕子拘囚。成康之日，政简刑措。南巡不还，西服莫附。共和之后，王室多故。檿弧兴谣，龙漦作蠹。穨带荏祸，实倾周祚。', '《周本纪》是西汉史学家司马迁创作的一篇文言文，出自司马迁《史记》卷四、本纪第四，概括地记述了周王朝兴衰的历史，勾画出一个天下朝宗、幅员辽阔的强大奴隶制王国的概貌，以及其间不同阶段不同君王厚民爱民或伤民虐民的不同政治作风，君臣之间协力相助共图大业或相互倾轧各执已见的不同政治气氛。', '元妃：帝王或诸侯的嫡妻。按：《索隐》曰：“谯周以为‘弃，帝喾之胄，其父亦不著’，与此纪异也。”
野：野外，郊野。
迹：脚印。
欣（xīn，欣）然：欣然。欣，同“欣”。说：同“悦”，喜悦，高兴。
践：踏，踩。
居期：到了日子。这里指怀孕满十月。
不祥：不吉利。
隘：狭窄。
辟：同“避”。
适会：正赶上。“适”“会”同义。
覆：盖。荐：藉，垫。
屹：耸立的样子。
种树：种植。“树”也是种的意思。菽：豆类。
相：仔细察看。
稼穑：种植和收获。种植叫稼，收获叫穑。
法则：效法、仿效。
举：举荐，提拔。
黎民：众民。黎，黑色。因众民发黑，故称黎民。
后稷：古代掌管农业事务的官。这里是做后稷以管理农务的意思。播时：播种，种植。时，通“莳（shì，示）”，栽种。
别：另外。姓姬氏：以姬为姓。
令德：美好的德性。令，美，善。
去稷，指废弃农师。
戎狄：泛指西北地区的部族。
行（旧读xìng，幸）：察看。
取材用：《正义》曰：“公刘从漆县漆水南渡渭水，至南山取材木为用也。”
赖：依靠，仰赖。庆：幸福。
怀：归向。
保归：归附。保，依，附。
“故诗人”句：《诗经·大雅》有《公刘》篇，歌颂了公刘的伟大业绩和高尚品德。诗人，指《诗经》的作者。
国：国都。这里是建都的意思。
戴：尊奉，拥护。
司马迁写作时的情形
司马迁写作时的情形
已：不久。
有民：民众。有，有人认为是上古汉语名词词头，无义。
所为：等于说“所以”，这里是表示攻战的原因或目的。
君之：意思是做他们的君主。
私属：家众。
逾：越过。
贬：减少，损减。这里有除去的意思。
邑别居之：意思是设邑落分别居住。
作五官有司：《集解》引《礼记》曰：“天子之五官曰司徒、司马、司空、司土、司寇，典司五众。”又引郑玄曰：“此殷时制。”作，设置。有司，官吏。古代设官分职，各有专司，所以称有司。
“民皆”二句：《诗经》中《周颂·天作》、《鲁颂·閟宫》都有歌颂古公亶父（fǔ，甫）的内容。古公有长子曰太伯，次曰虞仲。太姜生少子季历，季历娶太任，皆贤妇人，生昌，有圣瑞。古公曰：“我世当有兴者，其在昌乎？”长子太伯、虞仲知古公欲立季历以传昌，乃二人亡如荆蛮，文身断发，以让季历。
谮（zèn，怎去声）：进馋言，说人的坏话。
文马：有彩色花纹的马。《正义》：“按：骏马赤鬣缟身，目如黄金，文王以献纣也。”
九驷：三十六匹马。驷，古代一车驾四马，因称同驾一车的四马为驷。
他奇怪物：其他珍奇、稀有的宝物。
因：通过。嬖臣：亲信、宠幸之臣。
钺：大斧，古代兵器。
炮格：商纣时酷刑之一。《列女传》：“膏铜柱，下加之炭，令有罪者行焉，辄堕炭中，妲己笑，名曰格烙之法。”
滋甚：越来越厉害。
杀王子比干：比干为纣王的叔父，官少师，因屡次劝谏纣王，被剖心而死。见《殷本纪》。
囚箕子：箕子为当时贵族，纣王的诸父，官太师，封于箕（今山西太谷东北）。比干被剖心以后，箕子假装颠狂为奴，纣又囚之。见《殷本纪》。
“不可以句”：《会注考证》引梁玉绳曰：“《后书·袁术传》引史云‘殷有重罚，不可不伐’。”译文据此删“毕”字。
戎车：战车。乘（shèng，胜）：古代一车四马为一乘。这里可译为辆。
虎贲（bēn，奔）：勇士。《集解》引孔安国曰：“若虎之贲（奔）兽，言其猛也。”
甲士：披甲之士。
咸：皆，都。
孳孳：同“孜孜”，努力不懈的样子。
《太誓》：古文《尚书》篇名，作《泰誓》。
乃：竟，竟然。
三正：旧说指天、地、人或曰夏、商、周之正统。《集解》引马融曰：“动逆天地人也。”《正义》：“按：三正，三统也。周以建子为天统，殷以建丑为地统，夏以建寅为人统也。”建子、建丑、建寅，即以这三个月的朔日（初一）为岁首。“建”指斗建，即北斗所指的时辰，由子至亥，每月迁移一辰。又《尚书易解》于《甘誓》篇注云：“三正者，按正与政通，谓政事。《左传》文公七年晋却缺解《夏书》云：‘正德、利用、厚生谓之三事。’三事即三正也。”
离逷（tì，替）：疏远。逷，同“逖（tì，替），远。王父母弟、同祖亲族。《集解》引郑玄曰：“祖父母之族。必言‘母弟’，举亲者言之也。”
淫声：指淫荡的音乐。
用：以，以致，从而。正声：雅正的音乐。
怡说（yuè，悦）：使高兴。
维：句首语气词，可不译。共（gōng，恭）：通“恭”。天罚：指上天降下的惩罚。
勉：努力。夫子：对将士的尊称。《集解》引郑玄曰：“丈夫之称。”
再：两次，第二次。
二月：这是用周历，殷历为正月。昧爽：天将亮未亮之时。
杖：持，拿着。黄钺：黄铜制的大斧。
秉：持，把。旄：用旄牛尾放在旗杆上做装饰的旗。
麾（huī，挥）：挥动，指挥。
“远矣”句：这是慰劳的话。西土之人，指从西方来的将士。
有国冢君：称同来伐纣的诸侯。有国，《尚书·牧誓》作“友邦”。冢君：大君，等于说首领。
庸：在今湖北房县。蜀：在今四川成都一带。羌：西戎部落，在今甘肃境内。髳：西戎部落，在今四川东部。微：在今陕西郿县。郿：在今湖北西部。彭：在今四川彭宣县。濮：在今湖南沅陵县。按：以上八国都是当时属于武王的部落。
称：举。
比：并列，紧靠。这里是排列整齐的意思。
其：语气词，表示将要的意思。
牝鸡：雌鸡。晨：司晨，报晓。
惟家之索：等于说“惟索家”，意思是只能使家破败。惟，同“唯”，只。索，尽，这里有破败、毁败的意思。《集解》引孔安国曰：“喻妇人知外事，雌代雄鸣，则家尽也。”
惟妇人之言是用：等于说“维用妇人言”，只听妇人的话。维，同“唯”。《殷本纪》：“纣嬖于妇人，爱妲己，妲己之言是从。”
肆祀：指对祖先的祭祀。《集解》引郑玄曰：“肆，祭名。”答：答理，过问。
昏弃：弃去。昏，通“泯”，蔑。
多罪逋（bū，补平声）逃：指罪恶多端的逃犯。逋逃，逃亡。是崇是长：等于说：“崇是长是”，抬高这些人，重视这些人。崇，高，这里是使高、抬高的意思。长，以为长，即重视的意思。
是信是使，等于说“信是使是”，相信这些人，使用这些人。
俾：使。
奸轨：犯法作乱。奸，外乱。轨，通“宄（guǐ，轨），内乱。”
齐：指整顿队伍，使阵列整齐。
伐：击刺。
尚：表示命令或希望。桓桓：威武的样子。
离（chī，吃）：同“螭”，传说中一种似龙的动物。
御：抵挡，阻止。克奔：指能来奔投降者
役：助。西土：指周及伐纣各诸侯。
已：止，完毕。
陈师：摆开阵势。
七十万人：《新证》：“殷墟甲骨文记载商代用兵，至多一万余人，本文殷纣发兵七十万人，与实际不符合，只可以疑传疑。”距：同“拒”，抵抗。
致师：挑战。《集解》引郑玄曰：“致师者，致其必战之志也。古者将战，先使勇力之士犯敌焉。”
大卒：古代军队编制。《正义》：“大卒，谓戎车三百五十乘，士卒二万六千二百五十人，有虎贲三千人。”驰：驱赶车马向前冲。
亟：急，速。
倒兵：掉转兵器攻击自己一方，即倒戈。
开：引导。
畔：通“叛”，背叛。
反：同“返”。鹿台：又称南单之台。故址在今河南汤阴朝歌镇南，殷纣王所筑。
蒙：包，裹。衣（旧读yì，益）；穿（衣）。殊玉：大约是指极少见的美玉。《正义》引《周书》云：“甲子夕，纣取天智玉琰五，环身以自焚。”注：“天智，玉之善者，缝环其身自厚也。凡焚四千玉也，庶玉则销，天智玉不销，纣身不尽也。”
燔（fán，凡）：焚烧。
揖：拱手为礼。商国：商之国都。
百姓：百官。在战国以前，百姓是贵族的总称，因为当时只有贵族才有姓，一般平民没有姓。
咸：都。
告语（yù，玉）：告诉，对……宣告。
休：吉庆，美善。
稽（qǐ，启）首：叩头到地。古时九拜礼仪中最恭敬的一种。
所：处所，地方。
轻剑：据《正义》引《周书》作“轻吕之剑”。轻吕，剑名。
县（xuán，悬）：同“悬”，悬挂。
嬖（bì，辟）：宠爱。
经：缢死，上吊。
玄钺：黑色的大斧。《集解》引宋均：“玄钺用铁，不磨砺。”
复军：返回军中。
“除道”，清除道路。
“社”，祭祀土地神之所。
“百夫荷罕旗以先驱”，《克殷》作“百夫荷素质之旗于王前”，孔晁注：“素质白旗，前为王道也。”“荷”，扛。“罕旗”，旗名，有九旒。
“武王弟叔振铎奉陈常车”，《克殷》作“叔振铎奏拜假，又陈常车”，“奏拜假”，即“奏假”，字亦作“鬷假”、“艐格”、“奏嘏”。“奏”是进献之义；“假”通“格”，训至，指求神至；“拜”应指拜手。这里的“奉”字可能是“奏”字之误，并遗“拜假”二字。“叔振铎”，据说是文王第六子，后封于曹。详见本书《管蔡世家》。“陈”，列。“常车”，仪仗车，车上插有画着日月图像的太常旗。
“毕公”，据《逸周书·克殷》及本书《鲁世家》，是“召公”之误。
“夹”，左右夹侍。
“大卒”，见上文注，这里当指其兵众。
“左右毕从”，这段话《克殷》原文作“即位于社，大卒之左，群臣毕从”。这里“右”上应补一“左”字，“左右”，用以释“群臣”。
“毛叔郑”，文王庶子，武王弟，封于毛（在周王畿内）。“明水”，古人以阳燧（取火的铜镜）取火于日叫“明火”，以阴镜（取水的铜镜，又名“方诸”）取水于月叫“明水”。参看《周礼·秋官·司烜氏》。
“卫康叔封”，据说是文王第九子，初封于康（在周王畿内），后封于卫，详见本书《管蔡世家》、《卫康叔世家》。“兹”，草席。
“赞”，佐助。“采”，彩色币帛。
“牲”，祭牲。
“尹佚”，即史佚，食采于尹，以尹为氏，与太公、周公、召公被后人称为“四圣”（见《大戴礼·保傅》），是周初重臣之一。“策”，书于竹简。“祝”，祭告。
“末孙季纣”，《克殷》作“末孙受德”。
“殄”，音tiǎn，灭绝。“废”，废弃。
“侮蔑”，轻慢。“神祇”，天地之神。
“昏暴”，昏乱、残害。
“章”，读为“彰”，彰明。“天皇上帝”，古书及铜器铭文多作“皇天上帝”。”皇天”是至上的自然神，“上帝”是至上的人格神（族神）。
“膺更大命”，《逸周书·克殷》佚文（《文选·王元长曲水诗序》注引）作“膺受大命”。“膺受大命”亦见毛公鼎。这里的“更”字应是“受”字之误（战国文字中的“受”字与“更”字相似）。“大命”，指上天所授享有天下之命。
“革殷”，“革”，更革。代替殷享有天下。
“乃出”，以上是据《逸周书·克殷》。
集：和睦，安定。
相：辅佐。
表：称表，表彰。闾：闾里，闾巷。
发：散发。
振：同“赈”，赈济、救济。萌隶：指民众。萌，通“氓”，外来的百姓，也泛指老百姓。隶，奴隶。
展：展示，展览。九鼎：相传夏禹收天下之金铸成九鼎，象征九州。后来成了象征国家政权的传国之宝。成汤迁之于商邑，周武王迁之于洛邑。保玉：即宝玉。《集解》引徐广曰：“保，一作‘宝’。”
封：聚土筑坟。此处指在墓上添土。
享祠：祭祀鬼神。
行狩：到各诸侯国巡视。
《武成》：古文《尚书》篇名。《集解》引孔安国曰：“武功成也。”
班赐：分赐。班，同“颁”，颁发。宗彝：宗庙里用来盛酒的礼器。《集解》引郑玄曰：“宗彝，宗庙樽也。”
《分殷之器物》：《尚书》篇名，当作“分器”，已亡佚。《集解》引郑玄曰：“作《分器》，著王之命及受物。”分器事在《左传·定公四年》有记载。
首封：在分封的各诸侯王之中，位次第一。
观兵：炫耀武力。观，给人看。
戢：聚集，收藏。时动：适时出动。
玩：轻视，习惯而不经心。
震：惧怕。
周文公之颂：指《诗·周颂·时迈》。周文公，周公旦的谥号。
载：句首语气词，无义。
橐（gāo，高）：古代收藏弓箭的袋子。这里是用箭袋收藏的意思。
懿（yì，意）德：美德。
肆：传布。时：是，此。夏：华夏，指中国。
允：确实，一定。
茂：通“懋”，勉力，尽力。正：端正。厚：宽厚，富厚。这里是使宽厚的意思。
阜：物资多，丰富。这里是使多的意思。
乡：地方。
文：指礼法。修，告诫。
务：致力于，从事。
怀：心里藏着，心中装着。
滋：滋长，增长。
世后稷：世代做农官。
用：因此。
窜：流浪。
序：布舒、宣扬。
绪：事业。
训典：指教化法度。
恪勤：恭谨而努力。恪，恭敬，谨慎。
奕世：累世。奕，累，重。
忝：辱没，玷污。前人：指后稷等周代先王。
昭：使光大。
事：侍奉。
不忍：忍受不了。
䜣（xīn，欣）：同“欣”。载：拥戴，拥护。
戎：指戎事。商牧：商都郊野，即牧野。
恤：体恤，怜悯。隐：伤痛，痛苦。
邦内：国都郊外四周五百里以内。甸服：国都郊外四周五百里的地区。服，服待，服役，指为天子服役。按：古代把天子所居京都以外的地区按远近分为五等地区，每个地区五百里，叫“五服”，即甸服、侯服、绥服、要服、荒服。
侯服：甸服以外的五百里地区。
侯卫宾服：意思是侯服至卫服总称宾服。按：古代又有“九服”的区划法；王畿以外五百里为侯服，侯服以外五百里为甸服，甸服五百里以外为男服，男服以外五百里为采服，采服以外五百里为卫服，卫服以外五百里为蛮服，蛮服以外五百里为夷服，夷服以外五百里为镇服，镇服五百里以外为藩服。“宾服”是侯服、甸服、男服、采服、卫服的总称。这里五服、九服混说，诸服的远近次序纷错不同。
夷蛮：古代对东方、南方少数民族的总称：东部的叫夷，南部的叫蛮。带有蔑视的感情色彩。要（yāo，腰）服：这里指宾服以外的五百里地区。
戎翟（dí，狄）：古代对西方、北方少数民族的总称。戎，指西戎。翟，同“狄”，北狄。这也是蔑称。荒服：要服以外的五百里地区。
祭：指供给祭祀天子祖父和父亲的祭品。
祀：指供给祭祀天子高祖、曾祖的祭品。
享：献，指供给祭祀天子远祖的祭品。
贡：纳贡，指供给天子祭神的祭品。
王：朝见天子。《集解》引韦昭曰：“王，王事天子也。诗曰‘莫敢不来王’。”
日祭：每日祭祀。
月祀：每月祭祀。
时享：按季贡献祭品。
岁贡：每年纳贡。
终王：终身朝见天子一次。
先王之顺祀：《集解》引徐广云：“《外传》云‘先王之训’。”顺，通“训”，教诲，教导。祀，当是衍文。
修意：指检查自己的思想意念。
言：指言语号令。
文：指典法，法律制度。
名：名分，名号，指上下尊卑和贡赋的等级。
德：文德，指仁义礼乐等教化。
序成：指以上五种依次做完了。刑：施以刑罚，惩罚。
伐：攻打，征伐。
征：征讨，讨伐。按：古代有天子讨而不伐的说法。这两句“伐”与“征”对举，伐指命诸侯去征伐，征指天子派兵去征讨。
让：责备，谴责。
告：同“诰”，谕告，指上告下。
辟：法。
备：指武力装备。
命：命令。
辞：文书，公文。
布：发布。陈：陈述。
无：同“毋”，不，不要。勤：劳。使劳顿。
终：死。
职：职分，指“荒服者王”的职分。
天子：这里指周穆王。
无乃：不是，恐怕。
几：将。顿：疲困。
树敦：《集解》引韦昭曰：“树，立也。言犬戎立性敦笃也。”一说：树敦为犬戎君长名。
率：遵从。旧德：指祖先传下来的美好的品德、风尚。守终：指能守其“终王”的职分。纯固：专一。
遂：终于。
侈傲：放纵骄傲。
谤：指责别人的过失。
召公：这里是召公奭的后代，名虎，谥穆公。
鲜（xiǎn，显）：少。
不朝：不来朝觐。
国人：国都的人。
道路以目：是说人们在道路上相见，不敢说话，只以眼色示意。
弭（mǐ，米）：消除。
障：阻塞，阻止。
雍：水流堵塞。溃：水冲破堤防。
为水：治水。决：排除阻塞物，疏通水道。导：通，疏导。
宣：放开。
献诗：指采集民间讽谕朝政得失的诗歌献给国王。
瞽（gǔ，鼓）：盲者，指乐师。
史：太史，史官，掌记事。书：指历史文献，可供统治者借鉴。
师：太师，乐官之长。箴（zhēn，针）：箴言，规诫之言。这里是进箴言的意思。
瞍（sǒu，叟）：没有眼珠的盲人，为乐师。赋：指诵读公卿列士所献之诗。
蒙：有眼珠的盲人，为乐师。诵：指诵读箴诫之言。
百工：百官，众官。
传语：指由别人把意见传给王。
规：规劝，规谏。
亲戚：指王之同宗亲属。补察：补察王之过失。
耆艾：老年人，这里指师傅。古以六十为耆，五十为艾。修：告诫。
悖（bèi，背）：违背。
原：高而平之地。隰（xí，习）：低而湿之地。衍：低平之地。沃：有水流灌溉之地。
善败：好坏。
成：指虑成于心，即心里考虑好了。
与：语气词。几何：多久。
相与：一起，共同。
两周之间：东周与西周之间，为秦伐韩必经之路。
绝：横过，穿过。
发：派出。质：人质。
强（qiǎng，抢）：强行，竭力坚持。
疑周于秦：使周被秦怀疑。', '周的始祖后稷，名叫弃。他的母亲是有邰氏的女子，叫姜原。姜原是帝喾的第一个配偶。姜原到野外去，看见巨人的脚印，心里好喜欢，想去踩官，一踩上去便觉得腹中有什么在动，好像怀了孕一样。她怀胎满月生下个孩子，觉得不吉利，就把孩子丢在小巷子里，但经过的马牛却都躲开不去踩他；而把他移放在林子里，又碰上山林里人很多；再换个地方，把他丢在水渠的冰面上，又有飞鸟用它们的翅膀铺在上面垫在下面保护他。姜原认为是奇迹，便把他抱回抚养。由于最初想把这个孩子扔掉，所以给他取名叫弃。
弃还是个孩子时，就高大勇武，有巨人之志。他做游戏，喜欢的是栽麻种豆，种下去的麻、豆都长得茁壮茂盛。等他长大成人，也就爱上种庄稼，能根据土地的栽培特性，选择适宜的谷物加以种植培养，人民都仿效他。帝尧听说了，便举用弃为农师，天下的人都蒙受其惠，有功劳。帝舜说：“弃，百姓们当初忍饥挨饿，全靠你这个后稷播种各种谷物。”所以封弃干邰，号称后稷，另外得姓为姬氏。后稷的出名，全在陶唐、虞、夏几代之间，历任者都很有美德。
后稷死了，其子不窋即位。不窋末年，夏后氏政治衰败，废弃农官，不再劝民务农，不窋因而失去官职，逃奔戎狄中。不窋死了，其子鞠即位。鞠死了，其子公刘即位。公刘虽身在戎狄之中，却重新恢复后稷的旧业，致力于农作，按照土地的栽培特性加以耕种，从漆、沮二水渡渭水，伐取材木，行路人有盘缠，居家者有储备，人民仰赖他的恩德。百姓感戴他，多迁居而投靠他。周人治道的大兴是从这里开始的，所以诗人用诗歌赞美他，追怀他的恩德。公刘死了，其子庆节即位，建都于豳。
庆节死了，其子皇仆即位。皇仆死了，其子差弗即位。差弗死了，其子毁隃即位。毁隃死了，其子公非即位。公非死了，其子高圉即位。高圉死了，其子亚圉即位。亚圉死了，其子公叔祖类即位。公叔祖类死了，其子古公亶父即位。古公亶父重新恢复后稷、公刘的旧业，积德行义，国都中的人都拥戴他。黛盲等戎狄部族攻打他，想得到财物，他就把财物给他们。过了一阵又来攻打，还想得到土地和人民。人民都很愤怒，想迎战。古公说：“人民立君长，是求对他们有利。现在戎狄之所以来攻打，是为了得到土地和人民。人民在我的治下，与在他们的治下，有什么不同？人民是为了拥护我的缘故才去打仗，但靠牺牲别人的父亲和孩子来统治，我不忍心这样做。”因而同他的亲近左右离开了囱，涉漆、沮二水，翻过梁山，定居在歧山脚下。而豳地的人民举国扶老携幼，也全部重新回到古公身边来到岐山脚下。连周围国家听说古公仁慈，也多来投奔他。从此古公才贬斥戎狄的习俗，建造城郭和房屋，分成邑落居住，设立（司徒、司马、司空、司士、司寇）五种官职。人民都用诗歌赞美他，歌颂他的恩德。
古公有长子叫太伯，次子叫虞仲。太姜生小儿子季历，季历娶太任为妻，太姜、太任都是贤惠的妻子。太任生子昌，有圣明之兆。古公说：“我的后代当有成大事者，大概就是昌吧？”长子太伯和虞仲知道古公想立季历，以便将来能传位于昌，所以两人便逃亡到了荆蛮，（按当地风俗）身刺花纹，剪短头发，而让位给季历。
古公死了，季历即位，就是公季。公季遵循古公留下的原则，笃行仁义，诸侯都顺从他。
公季死了，其子昌即位，就是西伯。西伯即文王，他继承后稷、公刘的事业，遵照古公、公季的法则，笃行仁义，尊敬长者，慈爱幼小。由于他能屈节礼遇贤能，为了接待士人，每天到中午还顾不上吃早饭，士人纷纷投奔他。伯夷、叔齐在孤竹国，听说西伯善于敬养老人，一起投奔了他。太颠、闳夭、散宜生、鬻子、辛甲大夫等人也去投奔了他。
崇侯虎对殷纣讲西伯的坏话说：“西伯积德行善，诸侯归心，将不利于天子。”因而帝纣把西伯囚禁在羑里。闳夭等人很担心，就去搜求有莘氏的美女，骊戎的彩色骏马，有熊的九套驾车之马，以及其他种种珍奇之物，通过殷的宠臣费仲进献给纣。纣大喜，说：“有这里面的一件东西就足以令我释放西伯，何况还有其他许多呢！”故赦免了西伯，赐给他弓箭斧钺，使西伯得擅征伐。告诉他说：“说西伯坏话的人，是崇侯虎。”西伯因献洛水以西之地，而请纣废去炮格之刑。纣答应了他。
西伯暗自行善，诸侯都来请他裁决是非。当时虞、芮两国的人有讼事不能裁决，故前往周。他们进入周的境界，看到种田的人都互让田界，人民都以谦让长者为美德。虞、芮两国的人还没见到西伯，已觉惭愧，相互说：“我们所争的，正是周人所耻，还去干什么，去了只是自取羞辱罢了。”于是返回，互相谦让而去。诸侯听说，都说：“西伯当是受有上天之命的君主。”
次年，伐犬戎。又次年，伐密须。又次年，打败耆国。殷的祖伊听说后，害了怕，把情况报告给帝纣。纣说：“不是有天命助我吗？他能怎么样！”又次年，伐邘。又次年，伐崇侯虎，并开始营建丰邑，从岐山下迁都到丰邑。又次年，西伯死，太子发即位，就是武王。
西伯大概在位五十年。当他被囚羑里时，也许曾把《易》的八卦重为六十四卦。从《诗》的作者对西伯的称颂看，似乎西伯是在那一年受命称王，裁决虞、芮两国讼事。十年后去世，谥为文王。从此修改法度，制定正朔。追称古公为太王，公季为王季：这恐怕是因为称王的吉祥征兆是从太王开始。
武王即位，太公望做他的师，周公旦做他的傅，召公、毕公一班人辅佐武王，遵循文王的遗业。
九年，武王先在毕祭祀文王，然后前往东方举行阅兵，到达盟津。设文王的木主，用车子运载，置于军中。武王自称太子发，表示是以文王的名义征伐，不敢独断专行。然后向司马、司徒、司空、诸节告诫：“要小心谨慎，说到做到！我无知，全靠先祖留下的有德之臣，我这晚辈继承祖先的功业，当致力于赏罚，以巩固他们的功业。”终于起兵。师尚父下令说：“集合起你们的部下，带上你们的船只，迟到者斩首。”武王渡黄河，船到河心，有白鱼跳进王的船中，武王俯身拾起用来祭祀。渡过河之后，有一个火团从天而降，落在王的屋顶上，凝固成乌鸦状，它的颜色是红的，降落时声音轰隆隆。当时，诸侯不约而同前来盟津会盟的有八百诸侯。诸侯都说：“纣可以伐了。”武王说：“你们还未知天命，现在还不行。”所以班师回来。
过了两年，听说纣昏乱暴虐更甚于前，杀死王子比干，囚禁箕子。大师疵、少师彊抱着他们的乐器去投奔周。这时武王才向所有的诸侯宣告说：“殷犯下大罪，不可不合力讨伐。”因而遵循文王的遗志，率领战车三百辆，虎贲三千人，穿戴甲胄的战士四万五千人，东进伐纣。十一年十二月的戊午日，军队全部渡过盟津，诸侯都来参加，武王说：“要勤勤恳恳，不可懈怠呀！”武王因而作《太誓》，向众人宣告：“现在殷王纣竟然听信妻妾之言，自绝于上天，违背日、月、北斗的运行，疏远自己的同祖兄弟，竟然废弃其先祖的音乐，敢采用淫乱的音乐去窜改典雅的音乐，以取悦于他的妻妾。所以现在我发要恭敬地执行上天的惩罚。要努力呀，男子汉们，不会有第二次了，更不会有第三次了！”
二月甲子日的凌晨，武王一早就赶到商别都朝歌郊外的牧野，举行誓师。武王左手拄着黄色的钺，右手握着以白色旄牛尾为饰的旗，用来指挥。说：“一路辛苦了，来自西方的人们！”武王又说：“啊！我的友好邻邦的君主，司徒、司马、司空、亚旅、师氏、千夫长、百夫长，以及庸、蜀、羌、髳、微、、彭、濮各族的人民，举起你们的戈，排好你们的盾，竖起你们的矛，我要宣誓了。”王说：“古人有句话‘母鸡是不叫明的，如果母鸡叫明，必定倾家荡产’。现在殷王纣什么都听女人的，自弃其先祖的祭祀不予回报，抛下自己的家族和国家，放着自己的同祖兄弟不用，反而对四方各国犯罪逃亡的人那么推崇，那么看重，信任他们，使用他们，让他们对百姓横施暴虐，对商国大肆破坏。现在我发要恭敬地执行上天的惩罚。今天的作战，每次前进不超出六、七步，就要停顿整齐一下，要努力呀，男子汉们！（每次刺击）不超出四、五、六、七下，就要停顿整齐一下，要努力呀，男子汉们！希望大家勇武，有如虎、罴、豺、离，我们是在商郊作战，不可迎击前来投降的人，而要让他们为我西方之人所使，要努力呀，男子汉们！你们谁不努力，我将拿他问斩。”誓师完毕，诸侯派兵参加会盟者共有战车四千辆，列阵于牧野。
帝纣听说武王前来，也发兵七十万抵御武王。武王派师尚父和百夫长挑战，用大卒驰击纣的军队。纣的军队虽然人多，但都无心作战，只盼武王赶快攻入。纣的军队都掉转武器攻纣，为武王做内应。武王驰击纣的军队，纣的军队溃不成军，背叛纣。纣逃跑，退入城中，登上鹿台，把他的宝玉都穿戴在身上，自焚而死。武王手持大白旗指挥诸侯，诸侯都向武王拜手致敬，武王也向诸侯拱手回礼，诸侯都听从他。武王来到商的别都，城中的百姓都在城郊迎候。于是武王派群臣告诉商的百姓说：“上天将赐福给大家！”商人一齐拜手稽首共两次，武王也还礼拜谢。于是进城，到了纣死的地方。武王亲自用箭射他，射了三发才下车，用轻剑刺他，用黄色的钺砍下纣的头，挂在大白旗上。然后又到纣的两个宠妾那里，发现这两个宠妾都已上吊自杀。武王又射了三发，用剑刺她们，用黑色的钺砍下她们的头，把她们的头挂在小白旗上。武王做完这一切才出城，回到军中。
第二天，清除道路，整修社庙和商纣的宫室。到时候，一百名士兵扛着“罕旗”走在前面。武王的弟弟振铎布列“常车”，周公旦手持大钺，毕公手持小钺，夹立在武王的两边。散宜生、太颠、闳夭都持剑环卫武王。武王进了城，站在社庙南面大卒的左边，左右的人们都跟着他。毛叔郑端着“明水”，卫康权封铺草席，召公奭帮助拿彩帛，师尚父牵祭牲。尹佚朗读竹简上的祭文说：“殷的末代子孙季纣，废弃先王的美德，蔑视神明，不去祭祀，对商城中的百姓昏乱暴虐，这些皇天上帝都已知道得清清楚楚。”于是武王拜手稽首两次，说：“承受大命，革除殷所受之命，得到上无所降光明之命。”武王又拜手稽首两次，然后出城。
武王以殷的遗民封商纣之子禄父。武王因天下初定，尚未和睦，所以派他的弟弟管叔鲜、蔡叔度辅佐禄父治理殷国。然后又命召公放箕子出狱。命毕公放百姓出狱，在商容的闾门上设立标志以表彰他。命南宫括散发聚集在鹿台的钱财和巨桥的粮食，用来赈济贫苦的野人和贱民。命南宫括、史件搬走殷人的九鼎和宝玉。命闳夭为比干之墓培土为冢。命宗祝祭享于军中。然后撤兵回到西方。武王巡狩，记录其政事，作《武成》篇。封诸侯，分赐殷的宗庙祭器，作《分殷之器物》篇。武王追怀古代的圣王，因而嘉封神农的后代于焦，黄帝的后代于祝，帝尧的后代于蓟，帝舜的后代于陈，大禹的后代于杞。接着又封功臣谋士，而师尚父是被封的第一个。武王封尚父于营丘，为齐。封其弟同公旦于曲旱，为鲁。封召公奭于燕。封其弟叔鲜于管，其弟叔度于蔡。其他人也都依次受封。
武王召见九州之长，登上豳的高地，遥望商的都城。武王回到周，彻夜不眠。周公旦来到王的住处，问：“为什么不睡？”王说：“告诉你：只因天不受殷的享祭，从发没生下来到现在六十年，远郊和远郊以外到处是麋鹿和飞虫。天不受殷的享祭，所以才有今天的成功。上天建立了殷国，殷国进用的贤人有三百六十人，却既不重用也不废弃，所以会有今天。我还没有真正得到上天的保佑，哪有功夫睡觉！”王说：“要想真正得到上天的保佑，应依靠太室山，把作恶的人统统找出来，加以贬黜，与殷王受同罪。日夜慰劳人民，安定我西方，我要提倡克尽职守，直到我们的德教弘扬四方。从洛水拐弯处到伊水拐弯处，人们定居在平坦之处而非险隘之处，这是夏人的活动中心。我当南面可见三涂山，北面可见太行山，回首可见黄河，还有洛水、伊水，不要远高太室山。”在雒邑营建周城，然后离去。放马于华山之南，放牛于桃林之野，放下于戈不用，整顿军队，解除武装：向天下表示不再用兵。
武王已战胜殷，过了两年，问箕子殷灭亡的原因。箕子不忍讲殷的坏话，只以应当如何保存被亡之国相告。武王也感到惭愧，所以只向他问天道。
武王生病。天下尚未和睦，众公卿们都很害怕，进行“穆卜”（卜问武王的下一代，）周公因而祓除斋戒，自愿作替身，想代替武王去死，武王的病有好转。后来武王死了，太子诵代之即位，就是成王。
成王幼小，周刚刚平定天下，周公害怕诸侯背叛周，便摄政主持国家大事。管叔、蔡叔等兄弟怀疑周公，勾结武庚作乱，背叛周。周公奉成王之命，讨伐武庚、管叔，流放蔡叔。用微子启代替武庚为殷的后代，都于宋。收聚了不少殷遗民，用来封武王的小弟弟封为卫康叔。晋唐叔获得吉祥的谷穗，献给成王，成王把它送到周公的驻兵之地。周公在东方受此吉祥的谷穗，并宣布了天子的命令。当初，管、蔡背叛周，周公征讨他们，三年才完全平走，所以先作《大诰》，其次作《微子之命》，又其次作《归禾》，又其次作《嘉禾》，又其次作《康诰》、《酒诰》、《梓材》，其事见于《鲁周公世家》。周公摄政七年，成王长大了，周公还政给成王，重新北面称臣。
成王在丰邑，派召公再次营建洛邑，以完成武王的遗愿。周公再次卜问勘察，终于动工营建，将九鼎安放在城内。他说：“这里是天下的中央，四方进贡，路程远近相似。”因而作《召诰》、《洛诰》。成王已迁走殷遗民，周公以王的名义宣告，作《多士》、《无侠》。召公担任保，周公担任师，东伐淮夷，灭除奄，把他们的国君迁到薄姑。成王从奄回来，住在宗周，作《多方》。成王革除了殷的天命之后，又袭击淮夷，回到丰，作《周官》。创制和订定礼乐。制度从此改变，而人民和睦，颂歌四起。成王征伐东夷之后，息慎前来祝贺，王命荣伯作《贿息慎之命》。
成王将死，害怕太子钊不能胜任，便命召公、毕公率诸侯共同辅佐太子使之即位。成王死后，召公、毕公率诸侯，带太子钊谒见先王的宗庙，向他反复告诫文王、武王创立王业的来之不易，让他一定要注意节俭，不要欲望太多，以笃厚诚实来治理天下，因而作《顾命》。太子钊因此即位，就是康王。康王即位，遍告诸侯，反复宣传文王、武王的功业，因而作《康诰》。所以成、康两王时，天下安宁，刑罚弃置不用达四十多年。康王命作策毕公按等级划分居住范围，组成周的四郊，因而作《毕命》。
康王死，其子昭王瑕即位。昭王之时，王道略有缺损。昭王到南方巡狩未能回来，死在江上。死了也不告丧，是想掩饰。于是立昭王之子满即位，就是穆王。穆王即位，年龄已五十岁了。当时王道衰败，穆王痛心文、武二王之道已缺损，命伯臩为太仆，以国家政事反复告诫他，作《臩命》。天下又重新安宁。
穆王将征犬戎，祭公谋父劝谏说：“不可以。先王显示给人的是德行，而不是武力。平时积蓄兵力，只在一定时刻才动用，一旦动用就要有威力，如果一味显示武力，就会使人漫不经心，漫不经心就会没有威力。所以周文公所作的颂说：‘收起盾和戈，藏起弓和箭，我求美德之士，载入大夏之中，王必保守不失。’先王对待人民，勉励和端正其道德，使其性情敦厚，扩大其财物并改良其器物，懂得利害关系所在，用礼法培养他们，教他们趋利避害，心怀仁德而畏惧惩罚，所以能世代相传，子孙蕃昌。从前我们的先王世世代代为后稷之官，供职于虞、夏两代。待到夏朝衰亡时，废弃农官，不再劝民务农，我们的先王不窋因而失去官职，自己逃窜于戎狄之间。他不敢懈怠祖先的遗业，继承祖先的德行，遵循祖先的传统，整理祖先的教训和典法，早晚都敬慎勤勉，以敦厚笃实自持，忠诚老实自奉。世世代代感戴其恩德，不给祖先丢脸。到了文王和武王，进一步发扬光大前人的业绩，再加上仁慈和睦，敬事神明，保护人民，神民皆大欢喜。商王帝辛对其人民作恶大甚，庶民忍无可忍，乐意拥戴武王，因而才能干商的牧野列阵而战。所以先王并非有意要去使用武力，而只是因为时刻关怀人民的疾苦，想为民除害。按照先王的制度，邦畿之内是“甸服”，邦畿之外是“侯服”，设置侯、卫的地方叫“宾服”，蛮夷之地叫“要服”，戎翟之地叫“荒服”。属于甸服的要“祭”（祭祀），属于侯服的要“祀”（祭祀），属于宾服的要“享”（祭享），属于要服的要“贡”（进贡），属于荒服的要“王”（奉以为王）。“祭”是以日计，“祀”是以月计，“享”是以季节计，“贡”是以年计，“王”是以终身计。按照先王的遗训，如果不“祭”就要端正其意志，如果不“祀”就要端正其言辞，如果不“享”就要端正其礼法，如果不“贡”就要端正其名分，如果不“王”就要端正其道德，依次做了而仍不能尽其职守，就要施以刑罚。因而才有对不祭者的刑罚，对不祀者的攻伐，对不享者的征讨，对不贡者的谴责，对不王者的告谕天下。因而也才有刑罚的各种规定，才有攻伐的各种武器，才有征讨的各种准备，才有严厉谴责的命令，才有大告天下的文辞。用命令和文辞宣告而仍然不来述职者，则进一步端正其道德，不必劳民远征。这样才能使邻近的国家无不听从，远方的国家无不归顺。现在从犬戎氏二君大毕、伯士去世，犬戎氏能世守其职，前来奉事天子，而天子却说‘我非要按“不享”的罪名加以征讨，而且还要向他们炫耀武力’，这不是抛弃先王的教训，而使您处于危险境地吗？我听说犬戎氏提倡敦厚的风气，遵循前人的德行而能始终如一，他们是有足以抵御我们的东西呀。”但穆王还是出兵征讨，获取四只白狼和四只白鹿回来。从这以后，属于荒服的国家就不再来了。
诸侯各国中有些国家不太和睦，甫侯把情况告给王，王因而立下各种刑法。王说：“喂，到我这里来！凡是封有国邑和土地的诸侯们，我要告诉给你们如何慎重地使用刑法。如今你们要安顿百姓，应选择的难道不是执法人材吗？应尊重的难道不是刑法本身吗？应掌握的难道不是量刑尺度吗？原告和被告都到齐了，士师就要从（言辞、表情、呼吸、听觉反应和目光）等“五辞”来观察。通过这些观察摸清情况，即可用“五刑”来定罪。如果犯罪事实够不上“五刑”，就用“五罚”来定罪。如果犯罪事实够不上“五罚”，被判者不服，就用“五过”来定罪。属于“五过”方面的各种问题，如高官显贵不便诉诸刑庆的各种讼事，要查核其罪，使罪名与过失相当。凡遇该按“五刑”治罪而有疑问不得不赦免的讼事，凡遇该按“五罚”治罪而有疑问不得不赦免的讼事，要仔细查验。取证要从众，审讯要有据。如果没有充分证据便不能定罪，要知道老天在上。属于黥刑而不够定罪的，其罚金为一百率，要查核其罪。属于劓刑而不够定罪的，其罚金为前者的两倍，要查核其罪。属于膑刑而不够定罪的，其罚金为前者的两倍半，要查核其罪。属于宫刑而不够定罪的，其罚金为五百率，要查核其罪。属于大辟之刑而不够定罪的，其罚金为千率，要查核其罪。属于墨刑的罚金条文有上千条，属于劓刑的罚金条文有上千条，属于膑刑的罚金条文有五百条，属于宫刑的罚金条文有三百条，属于大辟之刑的罚金条文有二百条，五种刑罚的有关条文共有三千条。”被称之为《甫刑》。
穆王在位五十五年，去世，其子共王繄扈即位。共王在泾水上游玩，密康公服侍在旁，有三个女子来投奔密康公。密康公的母亲说：“你一定要把这三个女子献给王。兽，三只以上叫‘群’；人，三人以上叫‘众’，女子，三人以上叫‘粲’。王田猎从不猎取三只以上的兽，公行事必虚心听取三人以上的意见，王的妃嫔没有三人属于同族。粲字，是形容美好的事物。众人以美好的东西送给你，你有什么德行配去享用呢？王都不配享用，更何况你这样的小人物呢！小人物占有这类东西，终将灭亡。”密康公不肯献出，过了一年，共王灭密。共王死，其子懿王即位。懿王在位期间，王室终于衰败，诗人加以讥刺。
懿王死，共王的弟弟辟方即位，就是孝王。孝王死，诸侯又立懿王的太子燮即位，就是夷王。
夷王死，其子厉王胡即位。厉王即位三十年，贪图财利，亲近荣夷公。大夫芮良夫劝谏厉王说：“王室恐怕要衰落了吧？荣夷公喜欢垄断财利却不知道大难临头。财利，本是天地万物所生所长，要想垄断，害处太多了。天地万物是供大家所取，怎么可以垄断呢？他触怒的人很多，却不防备大难。还用这些来教王，王难道能够长治久安吗？做为人民的王，本应开发财源而遍施其惠。尽管使神、人万物得其所，仍然每天提心吊胆，害怕引起不满。所以《颂》说：‘追念祖先后稷，能够配享于天，安定我众多百姓，无不合乎其原则。’《大雅》说：‘布施赐予，成我周邦。’这不正是广施财利而又畏惧灾难吗？所以能成我周邦，绵延至今。现在王学的是垄断财利，这怎么可以呢？一个普通人垄断财利，尚且要称之为‘盗’，作为王也这样干，愿意归附的人就很少了。荣夷公若得重用，周朝必定衰败。”厉王不听，到底还是任用荣夷公为卿士，让他主持国家大事。
王行暴政，奢侈傲慢，住在国都中的人非议王。召公劝谏说：“人民受不了您的政令了。”王大怒，找到一个卫国的巫士，派他监视非议王的人。凡是报告上来有属于这种罪的都杀掉。这样非议是减少了，诸侯也不再来朝见。三十四年，王的控制更加严格，国都中的人都不敢说话，走在路上只能以目光示意。厉王很得意，告诉召公说：“我能平息人们的非议，使他们连话也不敢讲。”召公说：“这是因为您把他们的嘴堵起来了。堵人民的嘴可是比堵水还要危险。水被堵塞会决堤泛滥，伤人肯定很多，人民也是一样的。所以管理水的人要对水加以疏导，管理人民的人要让他们畅所欲言。因此天子为了了解下情，要让上至公卿下至列士的人都献诗，让盲乐师献曲，让史官献书，让师规诫，让无眼珠的盲人叙事，让有眼珠的盲人朗诵，让百工劝谏，让庶人街谈巷议，让近臣都来砚劝，让亲戚补察过失，让音乐师和史官来教诲，让老人们来整理，而后由帝王斟酌，所以政书得以施行而不违背情理。人民有嘴，就像土地上的山川是财货之源，平原沃野是衣食的来源。让人开口讲话，好事坏事都能反映出来。做好事而防备坏事，是财货和衣食的真正来源。人民心里怎么想嘴上就怎么讲，才能把事办好。如果把他们的嘴堵起来，又怎么能够长久呢？”王不听。因此国内没有人敢讲话，过了三年，竟一起叛乱，袭击厉王。厉王逃亡到彘。
厉王的太子静躲在召公的家里，国都中的人听说了，便把召公的家包围起来。召公说：“从前我屡次劝谏王，王不听，因而遭此大难。现在如果杀死王太子，王大概以为我是记仇而泄愤吧？奉事主人，虽处危难也不记仇，虽有怨气也不发泄，何况是奉事天子呢！”因而用自己的儿子代替王太子，太子竟然得免于难。
召公、周公两相共同执政，号称“共和”。共和十四年，厉王死于彘。太子静在召公家中长大，两相因共立之为王，就是宣王。宣王即位，两相辅佐他，修明政治，遵循文王、武王、成王、康王的遗风，诸侯又重新归附于周。十二年，鲁武公来朝见。
宣王废弃天子籍田上的籍礼，虢文公劝谏说这是不行的。王不听。三十九年，王的军队在千亩与姜氏之戎交战，大败。
宣王丧失了征伐南方的军队之后，竟在太原直接统计民户。仲山甫劝谏说：“民户是不可以由王直接加以统计的。”宣王不听，还是对民户进行了统计。
四十六年，宣王死，其子幽王宫湦即位。幽王二年，周西部丰、镐和泾、渭、洛一带都发生地震。伯阳甫说：“周将灭亡。天地二气，不可失去其秩序，如果越出其秩序，是人使之混乱。阳气伏藏而不能出，被阴气压迫不能上升，因而才有地震。现在泾、渭、洛一带发生地震，是因阳气不得其所而被阴气镇伏。阳气夫其所而被阴气镇伏，水源必然会堵塞；水源被堵塞，国家必然会灭亡。土壤中的水脉通畅，人民才能得到财利。土壤中的水脉不通畅，人民缺乏财利，国家不亡还等什么！从前伊水、洛水枯竭导致了夏亡，河水枯竭导致了商亡。现在周的德行己如同夏、商二代的末年，其水源又被堵塞，堵塞了就会枯竭。建立国都必须依山傍河，山陵崩颓，水源枯竭，是亡国的征兆。水源枯竭必定会引起山陵崩颓。若亡国的话当不出于十年，因为数是以十为进位。上天如果要抛弃我们，是不会超过这个数字的。”当年，泾、渭、洛枯竭，岐山崩颓。
三年，幽王宠爱褒似。褒似生下儿子伯服，幽王想废黜太子。太子的母亲是申侯之女，被立为王后。后来幽王得到褒姒，宠爱她，打算废黜申后，并除去太子宜臼，立褒姒为王后，伯服为太子。周太史伯阳读历史记录说：“周将要亡国了。”从前当夏后氏衰败，有两条神龙降落在夏帝的庭院而开口说：“我们，是褒国的两个君主。”夏帝卜问究竟是杀掉它还是赶走它或留下它，都不吉利。卜问是否可以把龙的涎沫收藏起来，才得到吉兆。于是陈设布帛，书于简策，向神龙祷告，龙走后留下涎沫，被盛在匣中收藏起来。夏灭亡，此器被传于商。商亡，此器又传于周。接连三个朝代，都没有人敢打开它。到厉王末年，才打开观看。涎沫流于庭院，除不去。厉王让女人赤身裸体而大声呼叫。涎沫化为黑色的蜥蜴，钻进王的后宫。后宫有个童女刚满七岁，碰上它，到十五岁行过笄礼后怀了孕，因为没有丈夫就生下孩子，感到害怕而把该子扔掉。宣王时有童女唱歌谣说：“见到山桑做成的弓和箕木做成的箭囊，周国将要灭亡。”当时宣王听到了，正好碰上有夫妇俩卖这两佯东西，宣王叫人把他们抓起来杀掉。他们逃跑走在路上，看见先前后宫童女扔在路边的孩子，听到孩子在夜里啼哭，出于怜悯而收养了她。夫妇俩终于逃亡，跑到褒国。褒国人犯了罪，请求献上童女扔掉的女儿给王以求赦免。这个被扔掉的女孩是来自褒国，就是褒姒。当幽王三年时，王到后宫，一见到她就爱上了她，和她生下儿子伯服，竟然废黜申后和太子，立褒姒为王后，伯服为太子。太史伯阳说：“灾祸己形成，没有任何办法了！”
褒姒不喜欢笑。幽王想尽一切办法逗她笑，她却偏偏不笑。幽王设有烽燧和大鼓，有来犯者则举烽火。有一次，幽王举烽火，诸侯都来了，来了却没有来犯者，褒姒才大笑。幽王喜欢这个办法，为褒姒多次举烽火。后来，失去信用，诸侯们渐渐也就不再来了。
幽王任用虢石父为卿士，主持国政，国都中的人都很有怨气。虢石父为人能说会道，喜欢阿谀奉承和贪图财利，王却重用他。再加上废黜申后和除去太子。申侯发了怒。联合缯和属于西夷的犬戎攻打幽王。幽王举烽火征发诸侯的军队，但诸侯的军队都不来。因此他们把幽王杀死在骊山下，掳走褒姒，将周人的财物抢掠一空而去。当时诸侯都到申侯这里来共立从前幽王的太子宜臼，就是平王，以保持周朝的祀统。
平王即位，把都城东迁到雒邑，以躲避戎寇。平王在位时，周王室衰败，诸侯强大之国吞并弱小之国，齐、楚、秦、晋开始强大，政令往往出于称霸的君主。
四十九年，鲁隐公即位。
五十一年，平王死，太子亶父早死，立其子林为王，就是桓王。桓王，是平王的孙桓王三年，郑庄公来朝见，桓王不予礼遇。五年，郑使宛与鲁国交换许田。许田，是天子用来祭祀泰山的土地。八年，鲁国杀隐公，立桓公。十三年，伐郑，郑射伤桓王，桓王逃跑回来。
二十三年，桓王死，其子庄王佗即位。庄王四年，周公黑肩打算杀死庄王而立王子克。辛伯报告王，王杀周公黑肩。王子克逃亡到燕国。
十五年，庄王死，其子釐王胡齐即位。釐王三年，齐桓公开始称霸。
五年，釐王死，其子惠王阆即位。惠王二年，当初庄王的宠妾姚氏生下子颓，颓有宠。等到惠王即位，惠王夺其大臣的园林作自己的猎场，因此大夫边伯等五人作乱，策划召燕、卫的军队，讨伐惠王。惠王逃奔到温，不久又住在郑国的栎。他们立了釐王的弟弟颓为王。（颓设礼招待五位大夫，）奏了全套的舞乐。郑、虢二国之君非常愤怒。四年，郑国和虢国的国君来讨伐，杀死王颓，重新迎立惠王。惠王十年，赐齐桓公为伯。
二十五年，惠王死，其子襄王郑即位。襄王的母亲早死，后母为惠后。惠后生叔带，叔带有宠于惠王，襄王害怕他。三年，叔带与戎、翟策划攻打襄玉，襄王想杀掉叔带，叔带逃奔到齐。齐桓公派管仲为戎与周说和，派隰朋为戎与晋说和。王用上卿之礼招待管仲。管仲辞谢说：“臣是身份低贱的官员，现有天子的两个上卿国氏和高氏在。如于春秋两季朝聘之节来受王命，将何以为礼呢？作为诸侯之臣的我请免去此礼。”王说：“作为舅舅家的人，我要奖励你的功勋，不要违反我的命令。”管仲到底还是只受下卿之礼而归。九年，齐桓公死。十二年，叔带又回到周。
十三年，郑伐滑，王派游孙、伯服为滑求情，郑人把他们囚禁起来。郑文公怨恨惠王复国没有送给郑厉公爵，又怨恨襄王帮助卫国替滑求情，所以把伯服囚禁起来。王发怒，准备用翟人伐郑。富辰劝谏说：“我们周人的东迁，全靠了晋、郑两国。子颓之乱，也是靠郑国才平定，今日竟然因为一点小小的不快就抛弃它们吗！”王不听。十五年，王派翟人的军队来伐郑。王感谢翟人，打算以他们的女子为王后。富辰劝谏说：“平、桓、庄、惠四王都受过郑国的帮助，王抛弃本族而亲近翟人，这个办法不行。”王不听。十六年，王废黜翟女之后，翟人来讨伐，杀死谭伯。富辰说：“我屡次劝谏都不听，如果碰上这种情况还不出战，王以为我是在怨恨吧？”竟率其族众殉难。
当初，惠后打算立王子带为王，因此派其党羽充当翟人的内应，翟人因而攻入周。襄王逃亡到郑，郑把王安顿在汜。子带即位为王，带上襄王所废黜的翟后一起住在温。十七年，襄王向晋告急，晋文公送王回国并杀死叔带。襄王因此赐给晋文公圭瓒、秬鬯、弓矢，封他为伯，把河内的土地赐给晋。二十年，晋文公召襄王，襄王与他在河阳、践土会见，诸侯都来朝见，史书加以掩饰，说是“天王巡狩至于河阳”。
二十四年，晋文公死。
三十一年，秦穆公死。
三十二年，襄王死，其子顷王壬臣即位。顷王六年，死，其子匡王班即位。匡王六年，死，其弟瑜即位，就是定王。
定王元年，楚庄王伐陆浑之戎，驻扎在洛，使人问九鼎（之大小轻重）。王派王孙满用言辞对答，楚兵才撤退。十年，楚庄王包围郑都，郑伯出降，不久又恢复郑国。十六年，楚庄王死。
二十一年，定王死，其子简王夷即位。简王十三年，晋杀死他们的国君厉公，从周接回子周，把他立为悼公。
十四年，简王死，其子灵王泄心即位。灵王二十四年，齐国的崔杼杀死其国君庄公。
二十七年，灵王死，其子景王贵即位。景王十八年，王后、太子圣明却早死。二十年，景王宠爱子朝，打算立他为太子，但景王却在这时死掉，子丐一伙人与子朝争立，国都中的人立长子猛为王，子朝攻打并杀死猛。猛即悼王。晋人攻打子朝而立丐为王，就是敬王。
敬王元年，晋人送敬王回国，子朝与之争立，敬王不能回国，住在泽。四年，晋率诸侯送敬王回到周都，子朝称臣，诸侯修筑周都的城墙。十六年，子朝一伙人再次作乱，敬王逃亡到晋。十七年，晋定公终于把周王送回周都。
三十九年，齐田常杀死其国君简公。
四十一年，楚灭陈国。孔子死。
四十二年，敬王死，其子元王仁即位。元王八年，其子定王介即位。
定王十六年，赵、魏、韩三国灭智伯，瓜分其土地。
二十八年，定王死，长子去疾即位，就是哀王。哀王即位三个月，其弟叔袭杀哀王自立，就是思王。思王即位五个月，其少弟嵬攻打并杀死思王而自立为王，就是考王。这三个王都是定王的儿子。
考王十五年，死，其子威烈王午即位。
考王把他的弟弟封在河南，就是西周桓公，让他接替周公的官职。桓公死，其子威公即位。威公死，其子惠公即位，而把惠公的幼子封在巩，让他奉侍周王，号称东周惠公。
威烈王二十三年，放置九鼎的王城地震。策命韩、魏、赵为诸侯。
二十四年，死，其子安王骄即位。当年有强盗杀死楚声王。
安王在位二十六年，死，其子烈王喜即位。烈王二年，周大史儋见秦献公，说：“当初周与秦国合在一起又分开，分开五百年又合在一起，合在一起十六年就会有霸王出现。”
十年，烈王死，其弟扁即位，就是显王。显王五年，祝贺秦献公，献公称伯。九年，赐送祭祀文、武二王的祭肉给秦孝公。二十五年，秦在周大会诸侯。二十六年，周赐伯的称号给秦孝公。三十三年，祝贺秦惠王。三十五年，赐送祭祀文、武二王的祭肉给秦惠王。四十四年，秦惠王称王。这以后诸侯都称王。
四十八年，显王死，其子慎靓王定即位。慎靓王在位六年，死，其子赧王延即位。王赦时东周和西周分裂，各自为政。王赧迁都于西周。
西周武公的共太子死了，他有五个庶子，没有嫡子即位。司马剪对楚王说：“不如拿土地给周，帮助公子咎，为之请立为太子。”左成说：“不行。周如果不答应，则您的计谋也就落空而且在外交上也会与周疏远。不如问问西周君想立谁为君，让他暗地告诉司马剪，司马剪再请楚予之土地作为资助。”最后果然立公子咎为太子。
八年，秦攻打宜阳，楚救宜阳。而楚因为周亲近秦的缘故，打算攻打周。苏代替周游说楚王说：“为什么要认为周亲近秦就是祸害呢？那些扬言周亲近秦超过楚的人，是想让周归并于秦，所以人称‘周秦’。周知道自己逃脱不了楚的进攻，必定会归并于秦，这是帮助秦取得周的最好办法。替王考虑，周亲近秦也对它好，不亲近秦也对它好，以使它和秦疏远。周与秦绝交，必定会旧并于楚。”
秦借道于东、西周之间，准备攻打韩，周害怕借道给秦会得罪韩，又怕不借会得罪秦。史厌对周君说：“为什么不派人对韩公叔说：‘秦之所以敢经过周去伐韩，是因为相信东周。您为何不送给周一些土地，派质子到楚？’这样做秦一定会怀疑楚而不相信周，如此也就不会去伐韩国。然后又对秦讲：‘韩硬把土地送给周，目的是为了使秦怀疑周，所以周不敢不接受。’秦必定没有理由让周不接受，这样就能既得地于韩又能使秦也相信。”
秦召西周君，西周君不愿前往，所以派人对韩王说：“秦召西周君，想让他派兵攻打王的南阳，王何不出兵南阳？西周君将以此为理由不去朝秦。如果西周君不到秦国去，秦也就必定不敢越过黄河而攻打南阳了。”
东周与西周交战，韩救两周。有人替东周劝说韩王说：“西周是从前天子的旧都，有许多名贵器物和珍宝，大王如果按兵不动，可以有恩德于东周，而西周的珍宝也一定可以尽归于韩。”
王赧对成君说（下有脱文）。楚围攻雍氏，韩向东周征发甲胄和粮食，东周君害了怕，召见苏代而把情况告诉他。苏代说：“您何必为此担心。臣下能让韩不向东周征发甲胄和粮食，又能为您得到高都。”东周君说：“您要真能如此，我要让整个国家都听从您。”苏代去见韩国的相邦说：“楚包围雍氏，曾保证三十月即可攻下，而现在已五个月了却仍然不能拔取，说明楚已损耗严重。现在相邦您竟向周征发甲胄和粮食，等于告诉楚（韩国）也损耗严重。”韩国相邦说：“讲得不错。但使者已经出发了。”苏代说：“何不把高都送给周？”韩国相邦大怒说：“我不向周征发甲胄和粮食就够可以的了，凭什么还得把高都也送给周？”苏代说：“把高都送给周，则周就会转而投靠韩国，秦听说必定会大怒，焚毁出使周的符节，不与周互派使节，这就等于用遭受破坏的高都换取完整的周地。又为什么不可以给呢？”相邦说：“不错。”真的把高都给了周。
三十四年，苏厉对周君说：“秦攻破韩、魏，杀师武。北取赵国的蔺、离石，都是白起所为。白起善用兵，又有天命为助。现在他又率兵出塞攻打大梁，大梁城破则周也就危险了。您何不派人游说白起呢？就说：‘楚国有个叫养由基的。是个擅长射箭的人。距离柳叶有百步之远而射之，百发百中。左右围观的人有几千人，都称赞他善射。唯独有个男子站在他身旁，却说：“不错，可以学射箭了。”养由基大怒，放下弓，握住剑，说：“外来人，你有什么资格教我射箭呢？”外来人说：“我并非真能教您左手执弓右手抠弦。像刚才那样距离柳叶百步远而射之，百发百中，不知道见好就收，用不了多久就会气力衰竭，弓歪矢曲，只要一发射不中，百发也就前功尽弃。”现在就凭攻破韩、魏，杀师武，北取赵国的蔺、离石这些事，您的功劳已太多。现在您又率兵出塞，经过东周、西周，背靠韩国，围攻大梁，一战不胜，就会前功尽弃。您不如告病，不出任将领。’”
四十二年，秦攻破华阳要塞。马犯对周君说：“请派我游说魏国为周筑城。”于是去对魏王说：“周王如果因担心秦伐周而忧患至死，那么犯也必死无疑了。犯请主动把九鼎进献给大王，大王得此九鼎要为犯所说的事情考虑。”魏王说：“好。”于是派兵给他，声称是去守卫周城。马犯借此又去对秦王说：“魏派兵并不是去守卫周城，是要攻打周。大王您不妨出兵境外看看情形如何。”秦果然出兵。马犯趁机又对魏王说：“周王的心头病已经好了，犯请等到条件许可时再来报答。现在大王派兵前往周，诸侯都会产生顾虑，以后再搞什么行动人家也不会相信了。不如让士兵帮助修筑周城，以掩盖最初的目的。”魏王说：“好。”于是派兵去修筑周城。
四十五年，西周君前往秦国，有游客对周冣说：“您不如赞誉秦王的孝顺，趁机把应送给秦太后做她的供养之地，秦王必定会高兴，这佯您与秦就有了交情。关系好，西周君必定认为是您的功劳。关系不好，劝周君入秦的人就必定会有罪。”秦攻打周，而周冣对秦王说：“为大王考虑，最好不要攻打周。攻周，其实并不足以获利，而却给天下留下坏的名声。天下因为秦的坏名声而讨厌秦，必定会联合东面的齐。因攻周而损耗兵力，使天下与齐联合，那么秦也就无法称王了。天下为了损害秦，所以劝大王攻打周。秦若接受这种损害，那么号令也就很难通行了。”
五十八年，三晋抵抗秦。周派其相邦到秦国去，因为秦国看不起周，所以推迟了行动。有游客对相邦说：“秦对周的态度尚未知道。秦很想了解三晋各国的情况。您不如赶紧去见秦王说‘请为王刺探东方各国的情况变化’，秦王必定看重您，看重您，秦也就会看重周，周就会与秦亲善；齐国看重周，则本有周冣与齐辛善：这样周就能一直保持与大国的交谊。”秦信任周，发兵攻打三晋。
五十九年，秦夺取韩国的阳城和负黍，西周害了怕，背叛秦，与诸侯合纵，率天下精兵出伊阙山攻打秦，使秦不能通往阳城。秦昭王发怒，派将军摎攻打西周。西周君逃奔到秦，叩首认罪，全部献上其城邑三十六座，人口三万人。秦接受其所献，释放西周君使归于周。
周君、王赧死，周的居民因而逃亡到东方。秦取得九鼎等贵重器物，而把西周君迁往狐。过了七年，秦庄襄王灭亡东周。东周、西周都被归并入秦，周从此祀统断绝。
太史公说：学者都说周伐商纣，定都洛邑，从总的事实看并不如此。虽然武王曾规划它，成王也派召公占卜其位置，把九鼎放在那里，但周仍然以丰、镐为都。直到犬戎打败幽王，周才东迁到洛邑。所谓“周公葬于毕”，毕便在镐东南的杜中。是秦灭亡了周。汉朝建立以来九十多年，天子要在泰山行封禅礼，东去巡狩到达河南县，访求周的后裔子孙，封给周的后人嘉三十里之地，号称周子南君，爵位同列侯，以保持对其祖先的祭祀。', NULL, '', 'indent', 1525124864, '5ae71d9aa22b9d00441b4780', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637444, '史记 · 十二本纪 · 秦本纪', NULL, 4, 139, 0, 2, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E7%A7%A6%E6%9C%AC%E7%BA%AA/2390760?fr=aladdin', '', '造父受封
秦之先，帝颛顼之苗裔孙曰女修。女修织，玄鸟陨卵，女修吞之，生子大业。大业取少典之子，曰女华。女华生大费，与禹平水土。已成，帝锡玄圭。禹受曰：“非予能成，亦大费为辅。”帝舜曰：“咨尔费，赞禹功，其赐尔皂游。尔后嗣将大出。”乃妻之姚姓之玉女。大费拜受，佐舜调驯鸟兽，鸟兽多驯服，是为柏翳。舜赐姓嬴氏。
大费生子二人：一曰大廉，实鸟俗氏；二曰若木，实费氏。其玄孙曰费昌，子孙或在中国，或在夷狄。费昌当夏桀之时，去夏归商，为汤御，以败桀于鸣条。大廉玄孙曰孟戏、中衍，鸟身人言。帝太戊闻而卜之使御，吉，遂致使御而妻之。自太戊以下，中衍之后，遂世有功，以佐殷国，故嬴姓多显，遂为诸侯。
其玄孙曰中潏（jue），在西戎，保西垂。生蜚廉。蜚廉生恶来。恶来有力，蜚廉善走，父子俱以材力事殷纣。周武王之伐纣，并杀恶来。是时蜚廉为纣石北方，还，无所报，为坛霍太山而报，得石棺，铭曰“帝令处父不与殷乱，赐尔石棺以华氏”。死，遂葬于霍太山。蜚廉复有子曰季胜。季胜生孟增。孟增幸于周成王，是为宅皋狼。皋狼生衡父，衡父生造父。造父以善御幸于周缪王，得骥、温骊、骅骝、騄耳之驷，西巡狩，乐而忘归。徐偃王作乱，造父为缪王御，长驱归周，一日千里以救乱。缪王以赵城封造父，造父族由此为赵氏。自蜚廉生季胜已下五世至造父，别居赵。赵衰其后也。恶来革者，蜚廉子也，蚤死。有子曰女防。女防生旁皋，旁皋生太几，太几生大骆，大骆生非子。以造父之宠，皆蒙赵城，姓赵氏。
位列诸侯
非子居犬丘，好马及畜，善养息之。犬丘人言之周孝王，孝王召使主马于汧渭之闲，马大蕃息。孝王欲以为大骆适嗣。申侯之女为大骆妻，生子成为适。申侯乃言孝王曰：“昔我先郦山之女，为戎胥轩妻，生中潏，以亲故归周，保西垂，西垂以其故和睦。今我复与大骆妻，生适子成。申骆重婚，西戎皆服，所以为王。王其图之。”于是孝王曰：“昔伯翳为舜主畜，畜多息，故有土，赐姓嬴。今其后世亦为朕息马，朕其分土为附庸。”邑之秦，使复续嬴氏祀，号曰秦嬴。亦不废申侯之女子为骆适者，以和西戎。
秦嬴生秦侯。秦侯立十年，卒。生公伯。公伯立三年，卒。生秦仲。
秦仲立三年，周厉王无道，诸侯或叛之。西戎反王室，灭犬丘大骆之族。周宣王即位，乃以秦仲为大夫，诛西戎。西戎杀秦仲。秦仲立二十三年，死于戎。有子五人，其长者曰庄公。周宣王乃召庄公昆弟五人，与兵七千人，使伐西戎，破之。于是复予秦仲后，及其先大骆地犬丘并有之，为西垂大夫。
庄公居其故西犬丘，生子三人，其长男世父。世父曰：“戎杀我大父仲，我非杀戎王则不敢入邑。”遂将击戎，让其弟襄公。襄公为太子。庄公立四十四年，卒，太子襄公代立。襄公元年，以女弟缪嬴为丰王妻。襄公二年，戎围犬丘，世父击之，为戎人所虏。岁余，复归世父。七年春，周幽王用褒姒废太子，立褒姒子为适，数欺诸侯，诸侯叛之。西戎犬戎与申侯伐周，杀幽王郦山下。而秦襄公将兵救周，战甚力，有功。周避犬戎难，东徙雒邑，襄公以兵送周平王。平王封襄公为诸侯，赐之岐以西之地。曰：“戎无道，侵夺我岐、丰之地，秦能攻逐戎，即有其地。”与誓，封爵之。襄公于是始国，与诸侯通使聘享之礼，乃用骝驹、黄牛、羝羊各三，祠上帝西畤。十二年，伐戎而至岐，卒。生文公。
秦晋之好
文公元年，居西垂宫。三年，文公以兵七百人东猎。四年，至汧渭之会。曰：“昔周邑我先秦嬴于此，后卒获为诸侯。”乃卜居之，占曰吉，即营邑之。十年，初为鄜畤，用三牢。十三年，初有史以纪事，民多化者。十六年，文公以兵伐戎，戎败走。于是文公遂收周余民有之，地至岐，岐以东献之周。十九年，得陈宝。二十年，法初有三族之罪。二十七年，伐南山大梓，丰大特。四十八年，文公太子卒，赐谥为竫公。竫公之长子为太子，是文公孙也。五十年，文公卒，葬西山。竫公子立，是为宁公。
宁公二年，公徙居平阳。遣兵伐荡社。三年，与亳战，亳王奔戎，遂灭荡社。四年，鲁公子翚弑其君隐公。十二年，伐荡氏，取之。宁公生十岁立，立十二年卒，葬西山。生子三人，长男武公为太子。武公弟德公，同母鲁姬子。生出子。宁公卒，大庶长弗忌、威垒、三父废太子而立出子为君。出子六年，三父等复共令人贼杀出子。出子生五岁立，立六年卒。三父等乃复立故太子武公。
武公元年，伐彭戏氏，至于华山下，居平阳封宫。三年，诛三父等而夷三族，以其杀出子也。郑高渠眯杀其君昭公。十年，伐邽、冀戎，初县之。十一年，初县杜、郑。灭小虢。
十三年，齐人管至父、连称等杀其君襄公而立公孙无知。晋灭霍、魏、耿。齐雍廪杀无知、管至父等而立齐桓公。齐、晋为强国。
十九年，晋曲沃始为晋侯。齐桓公伯于鄄。
二十年，武公卒，葬雍平阳。初以人从死，从死者六十六人。有子一人，名曰白，白不立，封平阳。立其弟德公。
德公元年，初居雍城大郑宫。以牺三百牢祠鄜畤。卜居雍。后子孙饮马于河。梁伯、芮伯来朝。二年，初伏，以狗御蛊。德公生三十三岁而立，立二年卒。生子三人：长子宣公，中子成公，少子穆公。长子宣公立。
宣公元年，卫、燕伐周，出惠王，立王子穨。三年，郑伯、虢叔杀子穨而入惠王。四年，作密畤。与晋战河阳，胜之。十二年，宣公卒。生子九人，莫立，立其弟成公。
成公元年，梁伯、芮伯来朝。齐桓公伐山戎，次于孤竹。
成公立四年卒。子七人，莫立，立其弟缪公。
称霸西戎
缪公（秦穆公）任好元年，自将伐茅津，胜之。四年，迎妇于晋，晋太子申生姊也。其岁，齐桓公伐楚，至邵陵。
五年，晋献公灭虞、虢，虏虞君与其大夫百里傒，以璧马赂于虞故也。既虏百里傒，以为秦缪公夫人媵于秦。百里傒亡秦走宛，楚鄙人执之。缪公闻百里傒贤，欲重赎之，恐楚人不与，乃使人谓楚曰：“吾媵臣百里傒在焉，请以五羖羊皮赎之。”。楚人遂许与之。当是时，百里傒年已七十余。缪公释其囚，与语国事。谢曰：“臣亡国之臣，何足问！”缪公曰：“虞君不用子，故亡，非子罪也。”固问，语三日，缪公大说，授之国政，号曰五羖大夫。百里傒让曰：“臣不及臣友蹇叔，蹇叔贤而世莫知。臣常游困于齐而乞食铚人，蹇叔收臣。臣因而欲事齐君无知，蹇叔止臣，臣得脱齐难，遂之周。周王子穨好牛，臣以养牛干之。及穨欲用臣，蹇叔止臣，臣去，得不诛。事虞君，蹇叔止臣。臣知虞君不用臣，臣诚私利禄爵，且留。再用其言，得脱，一不用，及虞君难：是以知其贤。”于是缪公使人厚币迎蹇叔，以为上大夫。
秋，缪公自将伐晋，战于河曲。晋骊姬作乱，太子申生死新城，重耳、夷吾出奔。
九年，齐桓公会诸侯于葵丘。
晋献公卒。立骊姬子奚齐，其臣里克杀奚齐。荀息立卓子，克又杀卓子及荀息。夷吾使人请秦，求入晋。于是缪公许之，使百里傒将兵送夷吾。夷吾谓曰：“诚得立，请割晋之河西八城与秦。”及至，已立，而使丕郑谢秦，背约不与河西城，而杀里克。丕郑闻之，恐，因与缪公谋曰：“晋人不欲夷吾，实欲重耳。今背秦约而杀里克，皆吕甥、郄芮之计也。愿君以利急召吕、郄，吕、郄至，则更入重耳便。”缪公许之，使人与丕郑归，召吕、郄。吕、郄等疑丕郑有间，乃言夷吾杀丕郑。丕郑子丕豹奔秦，说缪公曰：“晋君无道，百姓不亲，可伐也。”缪公曰：“百姓苟不便，何故能诛其大臣？能诛其大臣，此其调也。”不听，而阴用豹。
十二年，齐管仲、隰朋死。
晋旱，来请粟。丕豹说缪公勿与，因其饥而伐之。缪公问公孙支，支曰：“饥穰更事耳，不可不与。”问百里傒，傒曰：“夷吾得罪于君，其百姓何罪？”于是用百里傒、公孙支言，卒与之粟。以船漕车转，自雍相望至绛。
十四年，秦饥，请粟于晋。晋君谋之群臣。虢射曰：“因其饥伐之，可有大功。”晋君从之。十五年，兴兵将攻秦。缪公发兵，使丕豹将，自往击之。九月壬戌，与晋惠公夷吾合战于韩地。晋君弃其军，与秦争利，还而马騺。缪公与麾下驰追之，不能得晋君，反为晋军所围。晋击缪公，缪公伤。于是岐下食善马者三百人驰冒晋军，晋军解围，遂脱缪公而反生得晋君。初，缪公亡善马，岐下野人共得而食之者三百余人，吏逐得，欲法之。缪公曰：“君子不以畜产害人。吾闻食善马肉不饮酒，伤人。”乃皆赐酒而赦之。三百人者闻秦击晋，皆求从，从而见缪公窘，亦皆推锋争死，以报食马之德。于是缪公虏晋君以归，令于国，齐宿，吾将以晋君祠上帝。周天子闻之，曰“晋我同姓”，为请晋君。夷吾姊亦为缪公夫人，夫人闻之，乃衰绖跣，曰：“妾兄弟不能相救，以辱君命。”缪公曰：“我得晋君以为功，今天子为请，夫人是忧。”乃与晋君盟，许归之，更舍上舍，而馈之七牢。十一月，归晋君夷吾，夷吾献其河西地，使太子圉为质于秦。秦妻子圉以宗女。是时秦地东至河。
十八年，齐桓公卒。二十年，秦灭梁、芮。
二十二年，晋公子圉闻晋君病，曰：“梁，我母家也，而秦灭之。我兄弟多，即君百岁后，秦必留我，而晋轻，亦更立他子。”子圉乃亡归晋。二十三年，晋惠公卒，子圉立为君。秦怨圉亡去，乃迎晋公子重耳于楚，而妻以故子圉妻。重耳初谢，后乃受。缪公益礼厚遇之。二十四年春，秦使人告晋大臣，欲入重耳。晋许之，于是使人送重耳。二月，重耳立为晋君，是为文公。文公使人杀子圉。子圉是为怀公。
其秋，周襄王弟带以翟伐王，王出居郑。二十五年，周王使人告难于晋、秦。秦缪公将兵助晋文公入襄王，杀王弟带。二十八年，晋文公败楚于城濮。三十年，缪公助晋文公围郑。郑使人言缪公曰：“亡郑厚晋，于晋而得矣，而秦未有利。晋之强，秦之忧也。”缪公乃罢兵归。晋亦罢。三十二年冬，晋文公卒。
郑人有卖郑于秦曰：“我主其城门，郑可袭也。”缪公问蹇叔、百里傒，对曰：“径数国千里而袭人，希有得利者。且人卖郑，庸知我国人不有以我情告郑者乎？不可。”缪公曰：“子不知也，吾已决矣。”遂发兵，使百里傒子孟明视，蹇叔子西乞术及白乙丙将兵。行日，百里傒、蹇叔二人哭之。缪公闻，怒曰：“孤发兵而子沮哭吾军，何也？”二老曰：“臣非敢沮君军。军行，臣子与往；臣老，迟还恐不相见，故哭耳。”二老退，谓其子曰：“汝军即败，必于肴阨矣。”三十三年春，秦兵遂东，更晋地，过周北门。周王孙满曰：“秦师无礼，不败何待！”兵至滑，郑贩卖贾人弦高，持十二牛将卖之周，见秦兵，恐死虏，因献其牛，曰：“闻大国将诛郑，郑君谨修守御备，使臣以牛十二劳军士。”秦三将军相谓曰：“将袭郑，郑今已觉之，往无及已。”灭滑。滑，晋之边邑也。
当是时，晋文公丧尚未葬。太子襄公怒曰：“秦侮我孤，因丧破我滑。”遂墨衰绖，发兵遮秦兵于肴，击之，大破秦军，无一人得脱者。虏秦三将以归。文公夫人，秦女也，为秦三囚将请曰：“缪公之怨此三人入于骨髓，愿令此三人归，令我君得自快烹之。”晋君许之，归秦三将。三将至，缪公素服郊迎，向三人哭曰：“孤以不用百里傒、蹇叔言以辱三子，三子何罪乎？子其悉心雪耻，毋怠。”遂复三人官秩如故，愈益厚之。
三十四年，楚太子商臣弑其父成王代立。
缪公于是复使孟明视等将兵伐晋，战于彭衙。秦不利，引兵归。
戎王使由余于秦。由余，其先晋人也，亡入戎，能晋言。闻缪公贤，故使由余观秦。秦缪公示以宫室、积聚。由余曰：“使鬼为之，则劳神矣。使人为之，亦苦民矣。”缪公怪之，问曰：“中国以诗书礼乐法度为政，然尚时乱，今戎夷无此，何以为治，不亦难乎？”由余笑曰：“此乃中国所以乱也。夫自上圣黄帝作为礼乐法度，身以先之，仅以小治。及其后世，日以骄淫。阻法度之威，以责督于下，下罢极则以仁义怨望于上，上下交争怨而相篡弑，至于灭宗，皆以此类也。夫戎夷不然。上含淳德以遇其下，下怀忠信以事其上，一国之政犹一身之治，不知所以治，此真圣人之治也。”于是缪公退而问内史廖曰：“孤闻邻国有圣人，敌国之忧也。今由余贤，寡人之害，将奈之何？”内史廖曰：“戎王处辟匿，未闻中国之声。君试遗其女乐，以夺其志；为由余请，以疏其间；留而莫遣，以失其期。戎王怪之，必疑由余。君臣有间，乃可虏也。且戎王好乐，必怠于政。”缪公曰：“善。”因与由余曲席而坐，传器而食，问其地形与其兵势尽察，而后令内史廖以女乐二八遗戎王。戎王受而说之，终年不还。于是秦乃归由余。由余数谏不听，缪公又数使人间要由余，由余遂去降秦。缪公以客礼礼之，问伐戎之形。
三十六年，缪公复益厚孟明等，使将兵伐晋，渡河焚船，大败晋人，取王官及鄗，以报肴之役。晋人皆城守不敢出。于是缪公乃自茅津渡河，封肴中尸，为发丧，哭之三日。乃誓于军曰：“嗟士卒！听无哗，余誓告汝。古之人谋黄发番番，则无所过。”以申思不用蹇叔、百里傒之谋，故作此誓，令后世以记余过。君子闻之，皆为垂涕，曰：“嗟乎！秦缪公之与人周也，卒得孟明之庆。”
三十七年，秦用由余谋伐戎王，益国十二，开地千里，遂霸西戎。天子使召公过贺缪公以金鼓。三十九年，缪公卒，葬雍。从死者百七十七人，秦之良臣子舆氏三人名曰奄息、仲行、针虎，亦在从死之中。秦人哀之，为作歌黄鸟之诗。君子曰：“秦缪公广地益国，东服强晋，西霸戎夷，然不为诸侯盟主，亦宜哉。死而弃民，收其良臣而从死。且先王崩，尚犹遗德垂法，况夺之善人良臣百姓所哀者乎？是以知秦不能复东征也。”缪公子四十人，其太子嵤代立，是为康公。
东进受阻
康公元年。往岁缪公之卒，晋襄公亦卒；襄公之弟名雍，秦出也，在秦。晋赵盾欲立之，使随会来迎雍，秦以兵送至令狐。晋立襄公子而反击秦师，秦师败，随会来奔。二年，秦伐晋，取武城，报令狐之役。四年，晋伐秦，取少梁。六年，秦伐晋，取羁马。战于河曲，大败晋军。晋人患随会在秦为乱，乃使魏雠馀详反，合谋会，诈而得会，会遂归晋。康公立十二年卒，子共公立。
共公二年，晋赵穿弑其君灵公。三年，楚庄王强，北兵至雒，问周鼎。共公立五年卒，子桓公立。
桓公三年，晋败我一将。十年，楚庄王服郑，北败晋兵于河上。当是之时，楚霸，为会盟合诸侯。二十四年，晋厉公初立，与秦桓公夹河而盟。归而秦倍盟，与翟合谋击晋。二十六年，晋率诸侯伐秦，秦军败走，追至泾而还。桓公立二十七年卒，子景公立。
偏安一隅
景公四年，晋栾书弑其君厉公。十五年，救郑，败晋兵于栎。是时晋悼公为盟主。十八年，晋悼公强，数会诸侯，率以伐秦，败秦军。秦军走，晋兵追之，遂渡泾，至棫林而还。二十七年，景公如晋，与平公盟，已而背之。三十六年，楚公子围弑其君而自立，是为灵王。景公母弟后子针有宠，景公母弟富，或谮之，恐诛，乃奔晋，车重千乘。晋平公曰：“后子富如此，何以自亡？”对曰：“秦公无道，畏诛，欲待其后世乃归。”三十九年，楚灵王强，会诸侯于申，为盟主，杀齐庆封。景公立四十年卒，子哀公立。后子复来归秦。
哀公八年，楚公子弃疾弑灵王而自立，是为平王。十一年，楚平王来求秦女为太子建妻。至国，女好而自娶之。十五年，楚平王欲诛建，建亡；伍子胥奔吴。晋公室卑而六卿强，欲内相攻，是以久秦晋不相攻。三十一年，吴王阖闾与伍子胥伐楚，楚王亡奔随，吴遂入郢。楚大夫申包胥来告急，七日不食，日夜哭泣。于是秦乃发五百乘救楚，败吴师。吴师归，楚昭王乃得复入郢。哀公立三十六年卒。太子夷公，夷公蚤死，不得立，立夷公子，是为惠公。
惠公元年，孔子行鲁相事。五年，晋卿中行、范氏反晋，晋使智氏、赵简子攻之，范、中行氏亡奔齐。惠公立十年卒，子悼公立。
悼公二年，齐臣田乞弑其君孺子，立其兄阳生，是为悼公。六年，吴败齐师。齐人弑悼公，立其子简公。九年，晋定公与吴王夫差盟，争长于黄池，卒先吴。吴强，陵中国。十二年，齐田常弑简公，立其弟平公，常相之。十三年，楚灭陈。秦悼公立十四年卒，子厉共公立。孔子以悼公十二年卒。
厉共公二年，蜀人来赂。十六年，堑河旁。以兵二万伐大荔，取其王城。二十一年，初县频阳。晋取武成。二十四年，晋乱，杀智伯，分其国与赵、韩、魏。二十五年，智开与邑人来奔。三十三年，伐义渠，虏其王。三十四年，日食。厉共公卒，子躁公立。躁公二年，南郑反。十三年，义渠来伐，至渭南。十四年，躁公卒，立其弟怀公。
怀公四年，庶长晁与大臣围怀公，怀公自杀。怀公太子曰昭子，蚤死，大臣乃立太子昭子之子，是为灵公。灵公，怀公孙也。
灵公六年，晋城少梁，秦击之。十三年，城籍姑。灵公卒，子献公不得立，立灵公季父悼子，是为简公。简公，昭子之弟而怀公子也。
三晋伐秦
简公六年，令吏初带剑。堑洛。城重泉。十六年卒，子惠公立。
惠公十二年，子出子生。十三年，伐蜀，取南郑。惠公卒，出子立。
出子二年，庶长改迎灵公之子献公于河西而立之。杀出子及其母，沈之渊旁。秦以往者数易君，君臣乖乱，故晋复强，夺秦河西地。
献公元年，止从死。二年，城栎阳。四年正月庚寅，孝公生。十一年，周太史儋见献公曰：“周故与秦国合而别，别五百岁复合，合十七岁而霸王出。”十六年，桃冬花。十八年，雨金栎阳。二十一年，与晋战于石门，斩首六万，天子贺以黼黻。二十三年，与魏晋战少梁，虏其将公孙痤。二十四年，献公卒，子孝公立，年已二十一岁矣。
商鞅变法
孝公元年，河山以东强国六，与齐威、楚宣、魏惠、燕悼、韩哀、赵成侯并。淮泗之间小国十余。楚、魏与秦接界。魏筑长城，自郑滨洛以北，有上郡。楚自汉中，南有巴、黔中。周室微，诸侯力政，争相并。秦僻在雍州，不与中国诸侯之会盟，夷翟遇之。孝公于是布惠，振孤寡，招战士，明功赏。下令国中曰：“昔我缪公自岐雍之间，修德行武，东平晋乱，以河为界，西霸戎翟，广地千里，天子致伯，诸侯毕贺，为后世开业，甚光美。会往者厉、躁、简公、出子之不宁，国家内忧，未遑外事，三晋攻夺我先君河西地，诸侯卑秦、丑莫大焉。献公即位，镇抚边境，徙治栎阳，且欲东伐，复缪公之故地，修缪公之政令。寡人思念先君之意，常痛于心。宾客群臣有能出奇计强秦者，吾且尊官，与之分土。”于是乃出兵东围陕城，西斩戎之獂王。
卫鞅闻是令下，西入秦，因景监求见孝公。
二年，天子致胙。
三年，卫鞅说孝公变法修刑，内务耕稼，外劝战死之赏罚，孝公善之。甘龙、杜挚等弗然，相与争之。卒用鞅法，百姓苦之；居三年，百姓便之。乃拜鞅为左庶长。其事在商君语中。
七年，与魏惠王会杜平。八年，与魏战元里，有功。十年，卫鞅为大良造，将兵围魏安邑，降之。十二年，作为咸阳，筑冀阙，秦徙都之。并诸小乡聚，集为大县，县一令，四十一县。为田开阡陌。东地渡洛。十四年，初为赋。十九年，天子致伯。二十年，诸侯毕贺。秦使公子少官率师会诸侯逢泽，朝天子。
二十一年，齐败魏马陵。
二十二年，卫鞅击魏，虏魏公子昂。封鞅为列侯，号商君。
二十四年，与晋战雁门，虏其将魏错。
秦伯称王
孝公卒，子惠文君立。是岁，诛卫鞅。鞅之初为秦施法，法不行，太子犯禁。鞅曰：“法之不行，自于贵戚。君必欲行法，先于太子。太子不可黥，黥其傅师。”于是法大用，秦人治。及孝公卒，太子立，宗室多怨鞅，鞅亡，因以为反，而卒车裂以徇秦国。
惠文君元年，楚、韩、赵、蜀人来朝。二年，天子贺。三年，王冠。四年，天子致文武胙。齐、魏为王。
五年，阴晋人犀首为大良造。六年，魏纳阴晋，阴晋更名宁秦。七年，公子昂与魏战，虏其将龙贾，斩首八万。八年，魏纳河西地。九年，渡河，取汾阴、皮氏。与魏王会应。围焦，降之。十年，张仪相秦。魏纳上郡十五县。十一年，县义渠。归魏焦、曲沃。义渠君为臣。更名少梁曰夏阳。十二年，初腊。十三年四月戊午，魏君为王，韩亦为王。使张仪伐取陕，出其人与魏。
十四年，更为元年。二年，张仪与齐、楚大臣会啮桑。三年，韩、魏太子来朝。张仪相魏。五年，王游至北河。七年，乐池相秦。韩、赵、魏、燕、齐帅匈奴共攻秦。秦使庶长疾与战修鱼，虏其将申差，败赵公子渴、韩太子奂，斩首八万二千。八年，张仪复相秦。九年，司马错伐蜀，灭之。伐取赵中都、西阳。十年，韩太子苍来质。伐取韩石章。伐败赵将泥。伐取义渠二十五城。十一年，摢里疾攻魏焦，降之。败韩岸门，斩首万，其将犀首走。公子通封于蜀。燕君让其臣子之。十二年，王与梁王会临晋。庶长疾攻赵，虏赵将庄。张仪相楚。十三年，庶长章击楚于丹阳，虏其将屈丐，斩首八万；又攻楚汉中，取地六百里，置汉中郡。楚围雍氏，秦使庶长疾助韩而东攻齐，到满助魏攻燕。十四年，伐楚，取召陵。丹、犁臣，蜀相壮杀蜀侯来降。
惠王卒，子武王立。韩、魏、齐、楚、越皆宾从。
武王元年，与魏襄王会临晋。诛蜀相壮。张仪、魏章皆东出之魏。伐义渠、丹、犁。二年，初置丞相，摢里疾、甘茂为左右丞相。张仪死于魏。三年，与韩襄王会临晋外。南公揭卒，摢里疾相韩。武王谓甘茂曰：“寡人欲容车通三川，窥周室，死不恨矣。”其秋，使甘茂、庶长封伐宜阳。四年，拔宜阳，斩首六万。涉河，城武遂。魏太子来朝。武王有力好戏，力士任鄙、乌获、孟说皆至大官。王与孟说举鼎，绝膑。八月，武王死。族孟说。武王取魏女为后，无子。立异母弟，是为昭襄王。昭襄母楚人，姓芈氏，号宣太后。武王死时，昭襄王为质于燕，燕人送归，得立。
昭王称霸
昭襄王元年，严君疾为相。甘茂出之魏。二年，彗星见。庶长壮与大臣、诸侯、公子为逆，皆诛，及惠文后皆不得良死。悼武王后出归魏。三年，王冠。与楚王会黄棘，与楚上庸。四年，取蒲阪。彗星见。五年，魏王来朝应亭，复与魏蒲阪。六年，蜀侯辉反，司马错定蜀。庶长奂伐楚，斩首二万。泾阳君质于齐。日食，昼晦。七年，拔新城。摢里子卒。八年，使将军芊戎攻楚，取新市。齐使章子，魏使公孙喜，韩使暴鸢共攻楚方城，取唐眛。赵破中山，其君亡，竟死齐。魏公子劲、韩公子长为诸侯。九年，孟尝君薛文来相秦。奂攻楚，取八城，杀其将景快。十年，楚怀王入朝秦，秦留之。薛文以金受免。楼缓为丞相。十一年，齐、韩、魏、赵、宋、中山五国共攻秦，至盐氏而还。秦与韩、魏河北及封陵以和。彗星见。楚怀王走之赵，赵不受，还之秦，即死，归葬。十二年，楼缓免，穰侯魏冉为相。予楚粟五万石。
十三年，向寿伐韩，取武始。左更白起攻新城。五大夫礼出亡奔魏。任鄙为汉中守。十四年，左更白起攻韩、魏于伊阙，斩首二十四万，虏公孙喜，拔五城。十五年，大良造白起攻魏，取垣，复予之。攻楚，取宛。十六年，左更错取轵及邓。冉免，封公子市宛，公子悝邓，魏冉陶，为诸侯。十七年，城阳君入朝，及东周君来朝。秦以垣为蒲阪、皮氏。王之宜阳。十八年，错攻垣、河雍，决桥取之。十九年，王为西帝，齐为东帝，皆复去之。吕礼来自归。齐破宋，宋王在魏，死温。任鄙卒。二十年，王之汉中，又之上郡、北河。二十一年，错攻魏河内。魏献安邑，秦出其人，募徙河东赐爵，赦罪人迁之。泾阳君封宛。二十二年，蒙武伐齐。河东为九县。与楚王会宛。与赵王会中阳。二十三年，尉斯离与三晋、燕伐齐，破之济西。王与魏王会宜阳，与韩王会新城。二十四年，与楚王会鄢，又会穰。秦取魏安城，至大梁，燕、赵救之，秦军去。魏冉免相。二十五年，拔赵二城。与韩王会新城，与魏王会新明邑。二十六年，赦罪人迁之穰。侯冉复相。二十七年，错攻楚。赦罪人迁之南阳。白起攻赵，取代光狼城。又使司马错发陇西，因蜀攻楚黔中，拔之。二十八年，大良造白起攻楚，取鄢、邓，赦罪人迁之。二十九年，大良造白起攻楚，取郢为南郡，楚王走。周君来。王与楚王会襄陵。白起为武安君。三十年，蜀守若伐楚，取巫郡，及江南为黔中郡。三十一年，白起伐魏，取两城。楚人反我江南。三十二年，相穰侯攻魏，至大梁，破暴鸢，斩首四万，鸢走，魏入三县请和。三十三年，客卿胡阳攻魏卷、蔡阳、长社，取之。击芒卯华阳，破之，斩首十五万。魏入南阳以和。三十四年，秦与魏、韩上庸地为一郡，南阳免臣迁居之。三十五年，佐韩、魏、楚伐燕。初置南阳郡。三十六年，客卿灶攻齐，取刚、寿，予穰侯。三十八年，中更胡阳攻赵阏与，不能取。四十年，悼太子死魏，归葬芷阳。四十一年夏，攻魏，取邢丘、怀。四十二年，安国君为太子。十月，宣太后薨，葬芷阳郦山。九月，穰侯出之陶。四十三年，武安君白起攻韩，拔九城，斩首五万。四十四年，攻韩南阳，取之。四十五年，五大夫贲攻韩，取十城。叶阳君悝出之国，未至而死。四十七年，秦攻韩上党，上党降赵，秦因攻赵，赵发兵击秦，相距。秦使武安君白起击，大破赵于长平，四十余万尽杀之。四十八年十月，韩献垣雍。秦军分为三军。武安君归。王龁将伐赵武安、皮牢，拔之。司马梗北定太原，尽有韩上党。正月，兵罢，复守上党。其十月，五大夫陵攻赵邯郸。四十九年正月，益发卒佐陵。陵战不善，免，王龁代将。其十月，将军张唐攻魏，为蔡尉捐弗守，还斩之。五十年十月，武安君白起有罪，为士伍，迁阴密。张唐攻郑，拔之。十二月，益发卒军汾城旁。武安君白起有罪，死。龁攻邯郸，不拔，去，还奔汾军二月余。攻晋军，斩首六千，晋楚流死河二万人。攻汾城，即从唐拔宁新中，宁新中更名安阳。初作河桥。
五十一年，将军摎攻韩，取阳城、负黍，斩首四万。攻赵，取二十余县，首虏九万。西周君背秦，与诸侯约从，将天下锐兵出伊阙攻秦，令秦毋得通阳城。于是秦使将军摎攻西周。西周君走来自归，顿首受罪，尽献其邑三十六城，口三万。秦王受献，归其君于周。五十二年，周民东亡，其器九鼎入秦。周初亡。
五十三年，天下来宾。魏后，秦使摎伐魏，取吴城。韩王入朝，魏委国听令。五十四年，王郊见上帝于雍。五十六年秋，昭襄王卒，子孝文王立。尊唐八子为唐太后，而合其葬于先王。韩王衰绖入吊祠，诸侯皆使其将相来吊祠，视丧事。
孝文王元年，赦罪人，修先王功臣，褒厚亲戚，弛苑囿。孝文王除丧，十月己亥即位，三日辛丑卒，子庄襄王立。
庄襄王元年，大赦罪人，修先王功臣，施德厚骨肉而布惠于民。东周君与诸侯谋秦，秦使相国吕不韦诛之，尽入其国。秦不绝其祀，以阳人地赐周君，奉其祭祀。使蒙骜伐韩，韩献成皋、巩。秦界至大梁，初置三川郡。二年，使蒙骜攻赵，定太原。三年，蒙骜攻魏高都、汲，拔之。攻赵榆次、新城、狼孟，取三十七城。四月日食。王龁攻上党。初置太原郡。魏将无忌率五国兵击秦，秦却于河外。蒙骜败，解而去。五月丙午，庄襄王卒，子政立，是为秦始皇帝。
秦灭六国
秦王政立二十六年，初并天下为三十六郡，号为始皇帝。始皇帝五十一年而崩，子胡亥立，是为二世皇帝。三年，诸侯并起叛秦，赵高杀二世，立子婴。子婴立月余，诸侯诛之，遂灭秦。其语在始皇本纪中。
史家评论
太史公曰：秦之先为嬴姓。其后分封，以国为姓，有徐氏、郯氏、莒氏、终黎氏、运奄氏、菟裘氏、将梁氏、黄氏、江氏、修鱼氏、白冥氏、蜚廉氏、秦氏。然秦以其先造父封赵城，为赵氏。', '《秦本纪》是西汉史学家司马迁创作的一篇文言文，出自《史记卷五·秦本纪第五》。主要讲述了春秋和战国时期的诸侯国秦国从兴起、发展到称霸天下、秦王嬴政统一全国之前的历史。秦人是华夏族西迁的一支，其国君为嬴姓，秦最初的领地在今天陕西省西部，在当时属于中国的边缘部分。秦在战国初期也比较落后，从商鞅变法才开始改变。前325年秦惠王称王，前316年秦灭蜀，从此秦正式成为一个大国。前246年秦王嬴政登基，前238年掌权，开始了他对六国的征服。从前230年秦灭韩国起，到前221年秦灭齐国，统一中国。公元前207年，秦国灭亡于秦末农民战争。', '', '', '[{"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3d7ccce4d48ba49d10a", "shortContent": "公元前221年，秦王政统一天下。纷争扰攘了数百年，历史终于迎来了第一个真正的大一统局面。秦从边陲夷狄，一变而成为坐拥半壁江山的大国，到最终完成统一大业，是什么原因使起点较低的秦国来担当此大任呢？秦国又具备哪些独特的品质，经历了怎样的发展之路，从而能最终一统六国开创重大历史格局呢？\n秦是历史悠久的古老民族之一。秦人始祖为五帝颛顼之苗裔，其祖先大费曾助禹治水。周灭商，秦人因与商朝关系密切，被迁往遥远的...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1525196851, '5ae837a69f545400439d661d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637445, '史记 · 十二本纪 · 秦始皇本纪', NULL, 9, 139, 0, 1, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E5%8F%B2%E8%AE%B0%C2%B7%E7%A7%A6%E5%A7%8B%E7%9A%87%E6%9C%AC%E7%BA%AA/10323648?fr=aladdin&fromid=2390952&fromtitle=%E7%A7%A6%E5%A7%8B%E7%9A%87%E6%9C%AC%E7%BA%AA', '', '秦始皇帝者，秦庄襄王子也。庄襄王为秦质子于赵，见吕不韦姬，悦而取之，生始皇。以秦昭王四十八年正月生于邯郸。及生，名为政，姓赵氏。年十三岁，庄襄王死，政代立为秦王。当是之时，秦地已并巴、蜀、汉中，越宛有郢，置南郡矣；北收上郡以东，有河东、太原、上党郡；东至荥阳，灭二周，置三川郡。吕不韦为相，封十万户，号曰文信侯。招致宾客游士，欲以并天下。李斯为舍人。蒙骜、王齮、麃公等为将军。王年少，初即位，委国事大臣。
晋阳反，元年，将军蒙骜击定之。二年，麃公将卒攻卷，斩首三万。三年，蒙骜攻韩，取十三城。王齮死。十月，将军蒙骜攻魏氏畼、有诡。岁大饥。四年，拔畼、有诡。三月，军罢。秦质子归自赵，赵太子出归国。十月庚寅，蝗虫从东方来，蔽天。天下疫。百姓内粟千石，拜爵一级。五年，将军骜攻魏，定酸枣、燕、虚、长平、雍丘、山阳城，皆拔之，取二十城。初置东郡。冬雷。六年，韩、魏、赵、卫、楚共击秦，取寿陵。秦出兵，五国兵罢。拔卫，迫东郡，其君角率其支属徙居野王，阻其山以保魏之河内。七年，彗星先出东方，见北方，五月见西方。将军骜死。以攻龙、孤、庆都，还兵攻汲。彗星复见西方十六日。夏太后死。八年，王弟长安君成蟜将军击赵，反，死屯留，军吏皆斩死，迁其民于临洮。将军壁死，卒屯留、蒲鶮反，戮其尸。河鱼大上，轻车重马东就食。
嫪毐封为长信侯。予之山阳地，令毐居之。宫室车马衣服苑囿驰猎恣毐。事无小大皆决于毐。又以河西太原郡更为毐国。九年，彗星见，或竟天。攻魏垣、蒲阳。四月，上宿雍。己酉，王冠，带剑。长信侯毐作乱而觉，矫王御玺及太后玺以发县卒及卫卒、官骑、戎翟君公、舍人，将欲攻蕲年宫为乱。王知之，令相国昌平君、昌文君发卒攻毐。战咸阳，斩首数百，皆拜爵，及宦者皆在战中，亦拜爵一级。毐等败走。即令国中：有生得毐，赐钱百万；杀之，五十万。尽得毐等。卫尉竭、内史肆、佐弋竭、中大夫令齐等二十人皆枭首。车裂以徇，灭其宗。及其舍人，轻者为鬼薪。及夺爵迁蜀四千余家，家房陵。是月寒冻，有死者。杨端和攻衍氏。彗星见西方，又见北方，从斗以南八十日。十年，相国吕不韦坐嫪毐免。桓齮为将军。齐、赵来置酒。齐人茅焦说秦王曰：“秦方以天下为事，而大王有迁母太后之名，恐诸侯闻之，由此倍秦也。”秦王乃迎太后于雍而入咸阳，复居甘泉宫。
大索，逐客，李斯上书说，乃止逐客令。李斯因说秦王，请先取韩以恐他国，于是使斯下韩。韩王患之。与韩非谋弱秦。大梁人尉缭来，说秦王曰：“以秦之疆，诸侯譬如郡县之君，臣但恐诸侯合从，翕而出不意，此乃智伯、夫差、湣王之所以亡也。愿大王毋爱财物，赂其豪臣，以乱其谋，不过亡三十万金，则诸侯可尽。”秦王从其计，见尉缭亢礼，衣服食饮与缭同。缭曰：“秦王为人，蜂准，长目，挚鸟膺，豺声，少恩而虎狼心，居约易出人下，得志亦轻食人。我布衣，然见我常身自下我。诚使秦王得志于天下，天下皆为虏矣。不可与久游。”乃亡去。秦王觉，固止，以为秦国尉，卒用其计策。而李斯用事。
十一年，王翦、桓齮、杨端和攻邺，取九城。王翦攻阏与、橑杨，皆并为一军。剪将十八日，军归斗食以下，什推二人从军。取邺安阳，桓齮将。十二年，文信侯不韦死，窃葬。其舍人临者，晋人也逐出之；秦人六百石以上夺爵，迁；五百石以下不临，迁，勿夺爵。自今以来，操国事不道如嫪毐、不韦者籍其门，视此。秋，复嫪毐舍人迁蜀者。当是之时，天下大旱，六月至八月乃雨。
十三年，桓齮攻赵平阳，杀赵将扈辄，斩首十万。王之河南。正月，彗星见东方。十月，桓齮攻赵。十四年，攻赵军于平阳，取宜安，破之，杀其将军。桓齮定平阳、武城。韩非使秦，秦用李斯谋，留非，非死云阳。韩王请为臣。
十五年，大兴兵，一军至邺，一军至太原，取狼孟。地动。十六年九月，发卒受地韩南阳假守腾。初令男子书年。魏献地于秦。秦置丽邑。十七年，内史腾攻韩，得韩王安，尽纳其地，以其地为郡，命曰颍川。地动。华阳太后卒。民大饥。
十八年，大兴兵攻赵，王翦将上地，下井陉，端和将河内，羌瘣伐赵，端和围邯郸城。十九年，王翦、羌瘣尽定取赵地东阳，得赵王。引兵欲攻燕，屯中山。秦王之邯郸，诸尝与王生赵时母家有仇怨，皆坑之。秦王还，从太原、上郡归。始皇帝母太后崩。赵公子嘉率其宗数百人之代，自立为代王，东与燕合兵，军上谷。大饥。
二十年，燕太子丹患秦兵至国，恐，使荆轲刺秦王。秦王觉之，体解轲以徇，而使王翦、辛胜攻燕。燕、代发兵击秦军，秦军破燕易水之西。二十一年，王贲攻（蓟）。乃益发卒诣王翦军，遂破燕太子军，取燕蓟城，得太子丹之首。燕王东收辽东而王之。王翦谢病老归。新郑反。昌平君徙于郢。大雨雪，深二尺五寸。
二十二年，王贲攻魏，引河沟灌大梁，大梁城坏，其王请降，尽取其地。
二十三年，秦王复召王翦，强起之，使将击荆。取陈以南至平舆，虏荆王。秦王游至郢陈。荆将项燕立昌平君为荆王，反秦于淮南。二十四年，王翦、蒙武攻荆，破荆军，昌平君死，项燕遂自杀。
二十五年，大兴兵，使王贲将，攻燕辽东，得燕王喜。还攻代，虏代王嘉。王翦遂定荆江南地；降越君，置会稽郡。五月，天下大酺。
二十六年，齐王建与其相后胜发兵守其西界，不通秦。秦使将军王贲从燕南攻齐，得齐王建。
秦初并天下，令丞相、御史曰：“异曰韩王纳地效玺，请为藩臣，已而倍约，与赵、魏合从畔秦，故兴兵诛之，虏其王。寡人以为善，庶几息兵革。赵王使其相李牧来约盟，故归其质子。已而倍盟，反我太原，故兴兵诛之，得其王。赵公子嘉乃自立为代王，故举兵击灭之。魏王始约服入秦，已而与韩、赵谋袭秦，秦兵吏诛，遂破之。荆王献青阳以西，已而畔约，击我南郡，故发兵诛，得其王，遂定其荆地。燕王昏乱，其太子丹乃阴令荆轲为贼，兵吏诛，灭其国。齐王用后胜计，绝秦使，欲为乱，兵吏诛，虏其王，平齐地。寡人以眇眇之身，兴兵诛暴乱，赖宗庙之灵，六王咸伏其辜，天下大定。今名号不更，无以称成功，传后世。其议帝号。”丞相绾、御史大夫劫、廷尉斯等皆曰：“昔者五帝地方千里，其外侯服夷服诸侯或朝或否，天子不能制。今陛下兴义兵，诛残贼，平定天下，海内为郡县，法令由一统，自上古以来未尝有，五帝所不及。臣等谨与博士议曰：‘古有天皇，有地皇，有泰皇，泰皇最贵。’臣等昧死上尊号，王为‘泰皇’。命为‘制’，令为‘诏’，天子自称曰‘朕’。”王曰：“去‘泰’，著‘皇’，采上古‘帝’位号，号曰‘皇帝’。他如议。”制曰：“可。”追尊庄襄王为太上皇。制曰：“朕闻太古有号毋谥，中古有号，死而以行为谥。如此，则子议父，臣议君也，甚无谓，朕弗取焉。自今已来，除谥法。朕为始皇帝。后世以计数，二世三世至于万世，传之无穷。”始皇推终始五德之传，以为周得火德，秦代周德，从所不胜。方今水德之始，改年始，朝贺皆自十月朔。衣服旄旌节旗皆上黑。数以六为纪，符、法冠皆六寸，而舆六尺，六尺为步，乘六马。更名河曰德水，以为水德之始。刚毅戾深，事皆决于法，刻削毋仁恩和义，然后合五德之数。于是急法，久者不赦。
丞相绾等言：“诸侯初破，燕、齐、荆地远，不为置王，毋以填之。请立诸子，唯上幸许。”始皇下其议于群臣，群臣皆以为便。廷尉李斯议曰：“周文武所封子弟同姓甚众，然后属疏远，相攻击如仇雠，诸侯更相诛伐，周天子弗能禁止。今海内赖陛下神灵一统，皆为郡县，诸子功臣以公赋税重赏赐之，甚足易制。天下无异意，则安宁之术也。置诸侯不便。”始皇曰：“天下共苦战斗不休，以有侯王。赖宗庙，天下初定，又复立国，是树兵也，而求其宁息，岂不难哉！廷尉议是。”
分天下以为三十六郡，郡置守、尉、监。更名民曰“黔首”。大酺。收天下兵，聚之咸阳，销以为锺鐻，金人十二，重各千石，置廷宫中。一法度衡石丈尺。车同轨。书同文字。地东至海暨朝鲜，西至临洮、羌中，南至北乡户，北据河为塞，并阴山至辽东。徙天下豪富于咸阳十二万户。诸庙及章台、上林皆在渭南。秦每破诸侯，写放其宫室，作之咸阳北阪上，南临渭，自雍门以东至泾、渭，殿屋衤复道周阁相属。所得诸侯美人锺鼓，以充入之。
二十七年，始皇巡陇西、北地，出鸡头山，过回中。焉作信宫渭南，已更命信宫为极庙，象天极。自极庙道通郦山，作甘泉前殿。筑甬道，自咸阳属之。是岁，赐爵一级。治驰道。
二十八年，始皇东行郡县，上邹峄山。立石，与鲁诸儒生议，刻石颂秦德，议封禅望祭山川之事。乃遂上泰山，立石，封，祠祀。下，风雨暴至，休于树下，因封其树为五大夫。禅梁父。刻所立石，其辞曰：
皇帝临位，作制明法，臣下修饬。二十有六年，初并天下，罔不宾服。亲巡远方黎民，登兹泰山，周览东极。从臣思迹，本原事业，祗诵功德。治道运行，诸产得宜，皆有法式。大义休明，垂于后世，顺承勿革。皇帝躬圣，既平天下，不懈于治。夙兴夜寐，建设长利，专隆教诲。训经宣达，远近毕理，咸承圣志。贵贱分明，男女礼顺，慎遵职事。昭隔内外，靡不清净，施于后嗣。化及无穷，遵奉遗诏，永承重戒。
于是乃并勃海以东，过黄、腄，穷成山，登之罘，立石颂秦德焉而去。
南登琅邪，大乐之，留三月。乃徙黔首三万户琅邪台下，复十二岁。作琅邪台，立石刻，颂秦德，明得意。曰：维二十八年，皇帝作始。端平法度，万物之纪。以明人事，合同父子。圣智仁义，显白道理。东抚东土，以省卒士。事已大毕，乃临于海。皇帝之功，劝劳本事。上农除末，黔首是富。普天之下，抟心揖志。器械一量，同书文字。日月所照，舟舆所载。皆终其命，莫不得意。应时动事，是维皇帝。匡饬异俗，陵水经地。忧恤黔首，朝夕不懈。除疑定法，咸知所辟。方伯分职，诸治经易。举错必当，莫不如画。皇帝之明，临察四方。尊卑贵贱，不逾次行。奸邪不容，皆务贞良。细大尽力，莫敢怠荒。远迩辟隐，专务肃庄。端直敦忠，事业有常。皇帝之德，存定四极。诛乱除害，兴利致福。节事以时，诸产繁殖。黔首安宁，不用兵革。六亲相保，终无寇贼。欢欣奉教，尽知法式。六合之内，皇帝之土。西涉流沙，南尽北户。东有东海，北过大夏。人迹所至，无不臣者。功盖五帝，泽及牛马。莫不受德，各安其宇。
维秦王兼有天下，立名为皇帝，乃抚东土，至于琅邪。列侯武城侯王离、列侯通武侯王贲、伦侯建成侯赵亥、伦侯昌武侯成、伦侯武信侯冯毋择、丞相隗林、丞相王绾、卿李斯、卿王戊、五大夫赵婴、五大夫杨樛从，与议于海上。曰：“古之帝者，地不过千里，诸侯各守其封域，或朝或否，相侵暴乱，残伐不止，犹刻金石，以自为纪。古之五帝三王，知教不同，法度不明，假威鬼神，以欺远方，实不称名，故不久长。其身未殁，诸侯倍叛，法令不行。今皇帝并一海内，以为郡县，天下和平。昭明宗庙，体道行德，尊号大成。群臣相与诵皇帝功德，刻于金石，以为表经。”
既已，齐人徐市等上书，言海中有三神山，名曰蓬莱、方丈、瀛洲，仙人居之。请得斋戒，与童男女求之。于是遣徐市发童男女数千人，入海求仙人。
始皇还，过彭城，斋戒祷祠，欲出周鼎泗水。使千人没水求之，弗得。乃西南渡淮水，之衡山、南郡。浮江，至湘山祠。逢大风，几不得渡。上问博士曰：“湘君神？”博士对曰：“闻之，尧女，舜之妻，而葬此。”于是始皇大怒，使刑徒三千人皆伐湘山树，赭其山。上自南郡由武关归。
二十九年，始皇东游。至阳武博狼沙中，为盗所惊。求弗得，乃令天下大索十日。
登之罘，刻石。其辞曰：
维二十九年，时在中春，阳和方起。皇帝东游，巡登之罘，临照于海。从臣嘉观，原念休烈，追诵本始。大圣作治，建定法度，显箸纲纪。外教诸侯，光施文惠，明以义理。六国回辟，贪戾无厌，虐杀不已。皇帝哀众，遂发讨师，奋扬武德。义诛信行，威燀旁达，莫不宾服。烹灭彊暴，振救黔首，周定四极。普施明法，经纬天下，永为仪则。大矣哉！宇县之中，承顺圣意。群臣诵功，请刻于石，表垂于常式。其东观曰：
维二十九年，皇帝春游，览省远方。逮于海隅，遂登之罘，昭临朝阳。观望广丽，从臣咸念，原道至明。圣法初兴，清理疆内，外诛暴彊。武威旁畅，振动四极，禽灭六王。阐并天下，甾害绝息，永偃戎兵。皇帝明德，经理宇内，视听不怠。作立大义，昭设备器，咸有章旗。职臣遵分，各知所行，事无嫌疑。黔首改化，远迩同度，临古绝尤。常职既定，后嗣循业，长承圣治。群臣嘉德，祗诵圣烈，请刻之罘。旋，遂之琅邪，道上党入。
三十年，无事。
三十一年十二月，更名腊曰“嘉平”。赐黔首里六石米，二羊。始皇为微行咸阳，与武士四人俱，夜出逢盗兰池，见窘，武士击杀盗，关中大索二十日。米石千六百。
三十二年，始皇之碣石，使燕人卢生求羡门、高誓。刻碣石门。坏城郭，决通堤防。其辞曰：
遂兴师旅，诛戮无道，为逆灭息。武殄暴逆，文复无罪，庶心咸服。惠论功劳，赏及牛马，恩肥土域。皇帝奋威，德并诸侯，初一泰平。堕坏城郭，决通川防，夷去险阻。地势既定，黎庶无繇，天下咸抚。男乐其畴，女修其业，事各有序。惠被诸产，久并来田，莫不安所。群臣诵烈，请刻此石，垂著仪矩。
因使韩终、侯公、石生求仙人不死之药。始皇巡北边，从上郡入。燕人卢生使入海还，以鬼神事，因奏录图书，曰“亡秦者胡也”。始皇乃使将军蒙恬发兵三十万人北击胡，略取河南地。三十三年，发诸尝逋亡人、赘婿、贾人略取陆梁地，为桂林、象郡、南海，以适遣戍。西北斥逐匈奴。自榆中并河以东，属之阴山，以为十四县，城河上为塞。又使蒙恬渡河取高阙、山、北假中，筑亭障以逐戎人。徙谪，实之初县。禁不得祠。明星出西方。三十四年，适治狱吏不直者，筑长城及南越地。
始皇置酒咸阳宫，博士七十人前为寿。仆射周青臣进颂曰：“他时秦地不过千里，赖陛下神灵明圣，平定海内，放逐蛮夷，日月所照，莫不宾服。以诸侯为郡县，人人自安乐，无战争之患，传之万世。自上古不及陛下威德。”始皇悦。博士齐人淳于越进曰：“臣闻殷周之王千馀岁，封子弟功臣，自为枝辅。今陛下有海内，而子弟为匹夫，卒有田常、六卿之臣，无辅拂，何以相救哉？事不师古而能长久者，非所闻也。今青臣又面谀以重陛下之过，非忠臣。”始皇下其议。丞相李斯曰：“五帝不相复，三代不相袭，各以治，非其相反，时变异也。今陛下创大业，建万世之功，固非愚儒所知。且越言乃三代之事，何足法也？异时诸侯并争，厚招游学。今天下已定，法令出一，百姓当家则力农工，士则学习法令辟禁。今诸生不师今而学古，以非当世，惑乱黔首。丞相臣斯昧死言：古者天下散乱，莫之能一，是以诸侯并作，语皆道古以害今，饰虚言以乱实，人善其所私学，以非上之所建立。今皇帝并有天下，别黑白而定一尊。私学而相与非法教，人闻令下，则各以其学议之，入则心非，出则巷议，夸主以为名，异取以为高，率群下以造谤。如此弗禁，则主势降乎上，党与成乎下。禁之便。臣请史官非秦记皆烧之。非博士官所职，天下敢有藏诗、书、百家语者，悉诣守、尉杂烧之。有敢偶语诗书者弃市。以古非今者族。吏见知不举者与同罪。令下三十日不烧，黥为城旦。所不去者，医药卜筮种树之书。若欲有学法令，以吏为师。”制曰：“可。”
三十五年，除道，道九原抵云阳，堑山堙谷，直通之。于是始皇以为咸阳人多，先王之宫廷小，吾闻周文王都丰，武王都镐，丰镐之间，帝王之都也。乃营作朝宫渭南上林苑中。先作前殿阿房，东西五百步，南北五十丈，上可以坐万人，下可以建五丈旗。周驰为阁道，自殿下直抵南山。表南山之颠以为阙。为复道，自阿房渡渭，属之咸阳，以象天极阁道绝汉抵营室也。阿房宫未成；成，欲更择令名名之。作宫阿房，故天下谓之阿房宫。隐宫徒刑者七十馀万人，乃分作阿房宫，或作丽山。发北山石椁，乃写蜀、荆地材皆至。关中计宫三百，关外四百馀。于是立石东海上朐界中，以为秦东门。因徙三万家丽邑，五万家云阳，皆复不事十岁。卢生说始皇曰：“臣等求芝奇药仙者常弗遇，类物有害之者。方中，人主时为微行以辟恶鬼，恶鬼辟，真人至。人主所居而人臣知之，则害于神。真人者，入水不濡，入火不爇，陵云气，与天地久长。今上治天下，未能恬倓。原上所居宫毋令人知，然后不死之药殆可得也。”于是始皇曰：“吾慕真人，自谓‘真人’，不称‘朕’。”乃令咸阳之旁二百里内宫观二百七十复道甬道相连，帷帐锺鼓美人充之，各案署不移徙。行所幸，有言其处者，罪死。始皇帝幸梁山宫，从山上见丞相车骑众，弗善也。中人或告丞相，丞相后损车骑。始皇怒曰：“此中人泄吾语。”案问莫服。当是时，诏捕诸时在旁者，皆杀之。自是后莫知行之所在。听事，群臣受决事，悉于咸阳宫。
侯生卢生相与谋曰：“始皇为人，天性刚戾自用，起诸侯，并天下，意得欲从，以为自古莫及己。专任狱吏，狱吏得亲幸。博士虽七十人，特备员弗用。丞相诸大臣皆受成事，倚辨于上。上乐以刑杀为威，天下畏罪持禄，莫敢尽忠。上不闻过而日骄，下慑伏谩欺以取容。秦法，不得兼方不验，辄死。然候星气者至三百人，皆良士，畏忌讳谀，不敢端言其过。天下之事无小大皆决于上，上至以衡石量书，日夜有呈，不中呈不得休息。贪于权势至如此，未可为求仙药。”于是乃亡去。始皇闻亡，乃大怒曰：“吾前收天下书不中用者尽去之。悉召文学方术士甚众，欲以兴太平，方士欲练以求奇药。今闻韩众去不报，徐市等费以巨万计，终不得药，徒奸利相告日闻。卢生等吾尊赐之甚厚，今乃诽谤我，以重吾不德也。诸生在咸阳者，吾使人廉问，或为訞言以乱黔首。”于是使御史悉案问诸生，诸生传相告引，乃自除犯禁者四百六十馀人，皆阬之咸阳，使天下知之，以惩后。益发谪徙边。始皇长子扶苏谏曰：“天下初定，远方黔首未集，诸生皆诵法孔子，今上皆重法绳之，臣恐天下不安。唯上察之。”始皇怒，使扶苏北监蒙恬于上郡。
三十六年，荧惑守心。有坠星下东郡，至地为石，黔首或刻其石曰“始皇帝死而地分”。始皇闻之，遣御史逐问，莫服，尽取石旁居人诛之，因燔销其石。始皇不乐，使博士为《仙真人诗》，及行所游天下，传令乐人歌弦之。秋，使者从关东夜过华阴平舒道，有人持璧遮使者曰：“为吾遗滈池君。”因言曰：“今年祖龙死。”使者问其故，因忽不见，置其璧去。使者奉璧具以闻。始皇默然良久，曰：“山鬼固不过知一岁事也。”退言曰：“祖龙者，人之先也。”使御府视璧，乃二十八年行渡江所沈璧也。于是始皇卜之，卦得游徙吉。迁北河榆中三万家。拜爵一级。
三十七年十月癸丑，始皇出游。左丞相斯从，右丞相去疾守。少子胡亥爱慕请从，上许之。十一月，行至云梦，望祀虞舜于九疑山。浮江下，观籍柯，渡海渚。过丹阳，至钱唐。临浙水波恶，乃西百二十里从狭中渡。上会稽，祭大禹，望于南海，而立石刻颂秦德。其文曰：
皇帝休烈，平一宇内，德惠修长。三十有七年，亲巡天下，周览远方。遂登会稽，宣省习俗，黔首斋庄。群臣诵功，本原事迹，追首高明。秦圣临国，始定刑名，显陈旧章。初平法式，审别职任，以立恒常。六王专倍，贪戾泬猛，率众自强。暴虐恣行，负力而骄，数动甲兵。阴通间使，以事合从，行为辟方。内饰诈谋，外来侵边，遂起祸殃。义威诛之，殄熄暴悖，乱贼灭亡。圣德广密，六合之中，被泽无疆。皇帝并宇，兼听万事，远近毕清。运理群物，考验事实，各载其名。贵贱并通，善否陈前，靡有隐情。饰省宣义，有子而嫁，倍死不贞。防隔内外，禁止淫逸，男女絜诚。夫为寄豭，，杀之无罪，男秉义程。妻为逃嫁，子不得母，咸化廉清。大治濯俗，天下承风，蒙被休经。皆遵度轨，和安敦勉，莫不顺令。黔首修絜，人乐同则，嘉保太平。后敬奉法，常治无极，舆舟不倾。从臣诵烈，请刻此石，光垂休铭。
还过吴，从江乘渡。并海上，北至琅邪。方士徐市等入海求神药，数岁不得，费多，恐谴，乃诈曰：“蓬莱药可得，然常为大鲛鱼所苦，故不得至，原请善射与俱，见则以连弩射之。”始皇梦与海神战，如人状。问占梦，博士曰：“水神不可见，以大鱼蛟龙为候。今上祷祠备谨，而有此恶神，当除去，而善神可致。”乃令入海者赍捕巨鱼具，而自以连弩候大鱼出射之。自琅邪北至荣成山，弗见。至之罘，见巨鱼，射杀一鱼。遂并海西。
至平原津而病。始皇恶言死，群臣莫敢言死事。上病益甚，乃为玺书赐公子扶苏曰：“与丧会咸阳而葬。”书已封，在中车府令赵高行符玺事所，未授使者。七月丙寅，始皇崩于沙丘平台。丞相斯为上崩在外，恐诸公子及天下有变，乃秘之，不发丧。棺载辒凉车中，故幸宦者参乘，所至上食。百官奏事如故，宦者辄从辒凉车中可其奏事。独子胡亥、赵高及所幸宦者五六人知上死。赵高故尝教胡亥书及狱律令法事，胡亥私幸之。高乃与公子胡亥、丞相斯阴谋破去始皇所封书赐公子扶苏者，而更诈为丞相斯受始皇遗诏沙丘，立子胡亥为太子。更为书赐公子扶苏、蒙恬，数以罪，其赐死。语具在李斯传中。行，遂从井陉抵九原。会暑，上辒车臭，乃诏从官令车载一石鲍鱼，以乱其臭。
行从直道至咸阳，发丧。太子胡亥袭位，为二世皇帝。九月，葬始皇骊山。始皇初即位，穿治郦山，及并天下，天下徒送诣七十余万人，穿三泉，下铜而致椁，宫观百官奇器珍怪徙臧满之。令匠作机弩矢，有所穿近者辄射之。以水银为百川江河大海，机相灌输，上具天文，下具地理。以人鱼膏为烛，度不灭者久之。二世曰：“先帝后宫非有子者，出焉不宜。”皆令从死，死者甚众。葬既已下，或言工匠为机，臧皆知之，臧重即泄。大事毕，已臧，闭中羡，下外羡门，尽闭工匠臧者，无复出者。树草木以象山。
二世皇帝元年，年二十一。赵高为郎中令，任用事。二世下诏，增始皇寝庙牺牲及山川百祀之礼。令群臣议尊始皇庙。群臣皆顿首言曰：“古者天子七庙，诸侯五，大夫三，虽万世世不轶毁。今始皇为极庙，四海之内皆献贡职，增牺牲，礼成备，毋以加。先王庙或在西雍，或在咸阳。天子仪当独奉酌祠始皇庙。自襄公已下轶毁。所置凡七庙。群臣以礼进祠，以尊始皇庙为帝者祖庙。皇帝复自称‘朕’。”
二世与赵高谋曰：“朕年少，初即位，黔首未集附。先帝巡行郡县，以示强，威服海内。今晏然不巡行，即见弱，毋以臣畜天下。”春，二世东行郡县，李斯从。到碣石，并海，南至会稽，而尽刻始皇所立刻石，石旁着大臣从者名，以章先帝成功盛德焉。
皇帝曰：“金石刻尽始皇帝所为也。今袭号而金石刻辞不称始皇帝，其于久远也如后嗣为之者，不称成功盛德。”丞相臣斯、臣去疾、御史大夫臣德昧死言：“臣请具刻诏书刻石，因明白矣。臣昧死请。”制曰：“可。”遂至辽东而还。
于是二世乃遵用赵高，申法令。乃阴与赵高谋曰：“大臣不服，官吏尚强，及诸公子必与我争，为之柰何？”高曰：“臣固愿言而未敢也。先帝之大臣，皆天下累世名贵人也，积功劳世以相传久矣。今高素小贱，陛下幸称举，令在上位，管中事。大臣鞅鞅，特以貌从臣，其心实不服。今上出，不因此时案郡县守尉有罪者诛之，上以振威天下，下以除去上生平所不可者。今时不师文而决于武力，原陛下遂从时毋疑，即群臣不及谋。明主收举余民，贱者贵之，贫者富之，远者近之，则上下集而国安矣。”二世曰：“善。”乃行诛大臣及诸公子，以罪过连逮少近官三郎，无得立者，而六公子戮死于杜。公子将闾昆弟三人囚于内宫，议其罪独后。二世使使令将闾曰：“公子不臣，罪当死，吏致法焉。”将闾曰：“阙廷之礼，吾未尝敢不从宾赞也；廊庙之位，吾未尝敢失节也；受命应对，吾未尝敢失辞也。何谓不臣？原闻罪而死。”使者曰：“臣不得与谋，奉书从事。”将闾乃仰天大呼天者三，曰：“天乎！吾无罪！”昆弟三人皆流涕拔剑自杀。宗室振恐。群臣谏者以为诽谤，大吏持禄取容，黔首振恐。
四月，二世还至咸阳，曰：“先帝为咸阳朝廷小，故营阿房宫为室堂。未就，会上崩，罢其作者，复土郦山。郦山事大毕，今释阿房宫弗就，则是章先帝举事过也。”复作阿房宫。外抚四夷，如始皇计。尽征其材士五万人为屯卫咸阳，令教射狗马禽兽。当食者多，度不足，下调郡县转输菽粟刍稿，皆令自赍粮食，咸阳三百里内不得食其谷。用法益刻深。
七月，戍卒陈胜等反故荆地，为“张楚”。胜自立为楚王，居陈，遣诸将徇地。山东郡县少年苦秦吏，皆杀其守尉令丞反，以应陈涉，相立为侯王，合从西乡，名为伐秦，不可胜数也。谒者使东方来，以反者闻二世。二世怒，下吏。后使者至，上问，对曰：“群盗，郡守尉方逐捕，今尽得，不足忧。”上悦。武臣自立为赵王，魏咎为魏王，田儋为齐王。沛公起沛。项梁举兵会稽郡。
二年冬，陈涉所遣周章等将西至戏，兵数十万。二世大惊，与群臣谋曰：“柰何？”少府章邯曰：“盗已至，众强，今发近县不及矣。郦山徒多，请赦之，授兵以击之。”二世乃大赦天下，使章邯将，击破周章军而走，遂杀章曹阳。二世益遣长史司马欣、董翳佐章邯击盗，杀陈胜城父，破项梁定陶，灭魏咎临济。楚地盗名将已死，章邯乃北渡河，击赵王歇等于钜鹿。
赵高说二世曰：“先帝临制天下久，故群臣不敢为非，进邪说。今陛下富于春秋，初即位，柰何与公卿廷决事？事即有误，示群臣短也。天子称朕，固不闻声。”于是二世常居禁中，与高决诸事。其后公卿希得朝见，盗贼益多，而关中卒发东击盗者毋已。右丞相去疾、左丞相斯、将军冯劫进谏曰：“关东群盗并起，秦发兵诛击，所杀亡甚众，然犹不止。盗多，皆以戌漕转作事苦，赋税大也。请且止阿房宫作者，减省四边戌转。”二世曰：“吾闻之韩子曰：‘尧舜采椽不刮，茅茨不剪，饭土塯，啜土形，虽监门之养，不觳于此。禹凿龙门，通大夏，决河亭水，放之海，身自持筑臿，胫毋毛，臣虏之劳不烈于此矣。’凡所为贵有天下者，得肆意极欲，主重明法，下不敢为非，以制御海内矣。夫虞、夏之主，贵为天子，亲处穷苦之实，以徇百姓，尚何于法？朕尊万乘，毋其实，吾欲造千乘之驾，万乘之属，充吾号名。且先帝起诸侯，兼天下，天下已定，外攘四夷以安边竟，作宫室以章得意，而君观先帝功业有绪。今朕即位二年之间，群盗并起，君不能禁，又欲罢先帝之所为，是上毋以报先帝，次不为朕尽忠力，何以在位？”下去疾、斯、劫吏，案责他罪。去疾、劫曰：“将相不辱。”自杀。斯卒囚，就五刑。
三年，章邯等将其卒围钜鹿，楚上将军项羽将楚卒往救钜鹿。冬，赵高为丞相，竟案李斯杀之。夏，章邯等战数却，二世使人让邯，邯恐，使长史欣请事。赵高弗见，又弗信。欣恐，亡去，高使人捕追不及。欣见邯曰：“赵高用事于中，将军有功亦诛，无功亦诛。”项羽急击秦军，虏王离，邯等遂以兵降诸侯。八月己亥，赵高欲为乱，恐群臣不听，乃先设验，持鹿献于二世，曰：“马也。”二世笑曰：“丞相误邪？谓鹿为马。”问左右，左右或默，或言马以阿顺赵高。或言鹿，高因阴中诸言鹿者以法。后群臣皆畏高。
高前数言“关东盗毋能为也”，及项羽虏秦将王离等钜鹿下而前，章邯等军数却，上书请益助，燕、赵、齐、楚、韩、魏皆立为王，自关以东，大氐尽畔秦吏应诸侯，诸侯咸率其众西乡。沛公将数万人已屠武关，使人私于高，高恐二世怒，诛及其身，乃谢病不朝见。二世梦白虎啮其左骖马，杀之，心不乐，怪问占梦。卜曰：“泾水为祟。”二世乃斋于望夷宫，欲祠泾，沈四白马。使使责让高以盗贼事。高惧，乃阴与其婿咸阳令阎乐、其弟赵成谋曰：“上不听谏，今事急，欲归祸于吾宗。吾欲易置上，更立公子婴。子婴仁俭，百姓皆载其言。”使郎中令为内应，诈为有大贼，令乐召吏发卒，追劫乐母置高舍。遣乐将吏卒千余人至望夷宫殿门，缚卫令仆射，曰：“贼入此，何不止？”卫令曰：“周庐设卒甚谨，安得贼敢入宫？”乐遂斩卫令，直将吏入行射，郎宦者大惊，或走或格，格者辄死，死者数十人。郎中令与乐俱入，射上幄坐帏。二世怒，召左右，左右皆惶扰不斗。旁有宦者一人，侍不敢去。二世入内，谓曰：“公何不蚤告我？乃至于此！”宦者曰：“臣不敢言，故得全。使臣蚤言，皆已诛，安得至今？”阎乐前即二世数曰：“足下骄恣，诛杀无道，天下共畔足下，足下其自为计。”二世曰：“丞相可得见否？”乐曰：“不可。”二世曰：“吾愿得一郡为王。”弗许。又曰：“愿为万户侯。”弗许。曰：“愿与妻子为黔首，比诸公子。”阎乐曰：“臣受命于丞相，为天下诛足下，足下虽多言，臣不敢报。”麾其兵进。二世自杀。
阎乐归报赵高，赵高乃悉召诸大臣公子，告以诛二世之状。曰：“秦故王国，始皇君天下，故称帝。今六国复自立，秦地益小，乃以空名为帝，不可。宜为王如故，便。”立二世之兄子公子婴为秦王。以黔首葬二世杜南宜春苑中。令子婴斋，当庙见，受王玺。斋五日，子婴与其子二人谋曰：“丞相高杀二世望夷宫，恐群臣诛之，乃详以义立我。我闻赵高乃与楚约，灭秦宗室而王关中。今使我斋见庙，此欲因庙中杀我。我称病不行，丞相必自来，来则杀之。”高使人请子婴数辈，子婴不行，高果自往，曰：“宗庙重事，王柰何不行？”子婴遂刺杀高于斋宫，三族高家以徇咸阳。子婴为秦王四十六日，楚将沛公破秦军入武关，遂至霸上，使人约降子婴。子婴即系颈以组，白马素车，奉天子玺符，降轵道旁。沛公遂入咸阳，封宫室府库，还军霸上。居月余，诸侯兵至，项籍为从长，杀子婴及秦诸公子宗族。遂屠咸阳，烧其宫室，虏其子女，收其珍宝货财，诸侯共分之。灭秦之后，各分其地为三，名曰雍王、塞王、翟王，号曰三秦。项羽为西楚霸王，主命分天下王诸侯，秦竟灭矣。后五年，天下定于汉。
太史公曰：秦之先伯翳，尝有勋于唐虞之际，受土赐姓。及殷夏之间微散。至周之衰，秦兴，邑于西垂。自缪公以来，稍蚕食诸侯，竞成始皇。始皇自以为功过五帝，地广三王，而羞与之侔。善哉乎贾生推言之也！秦并兼诸侯山东三十余郡，缮津关，据险塞，修甲兵而守之。然陈涉以戍卒散乱之众数百，奋臂大呼，不用弓戟之兵，锄耰白梃，望屋而食，横行天下。秦人阻险不守，关梁不阖，长戟不刺，强弩不射。楚师深入，战于鸿门，曾无藩篱之艰。于是山东大扰，诸侯并起，豪俊相立。秦使章邯将而东征，章邯因其三军之众要市于外，以谋其上。群臣之不信，可见于此矣。子婴立，遂不寤。藉使子婴有庸主之材，仅得中佐，山东虽乱，三秦之地可全而有，宗庙之祀宜未绝也。秦地被山带河以为固，四塞之国也。自缪公以来，至于秦王，二十余君，常为诸侯雄。此岂世贤哉？其势居然也。且天下尝同心并力攻秦矣，当此之世，贤智并列，良将行其师，贤相通其谋，然困于阻险而不能进，秦乃延入战而为之开关，百万之徒逃北而遂坏。岂勇力智慧不足哉？形不利，势不便也。秦小邑并大城，守险塞而军，高垒毋战，闭关据厄，荷戟而守之。诸侯起于匹夫，以利合，非有素王之行也。其交未亲，其下未附，名曰亡秦，其实利之也。彼见秦阻之难犯也，必退师。案土息民，以待其敝，收弱扶罢，以令大国之君，不患不得意于海内。贵为天子，富有四海，而身为禽者，其救败非也。秦王足己而不问，遂过而不变。二世受之，因而不改，暴虐以重祸。子婴孤立无亲，危弱无辅。三主惑而终身不悟，亡，不亦宜乎？当此时也，世非无深虑知化之士也，然所以不敢尽忠拂过者，秦俗多忌讳之禁，忠言未卒于口而身为戮没矣。故使天下之士，倾耳而听，重足而立，拑口而不言。是以三主失道，而忠臣不谏，智士不谋也。天下已乱，奸不上闻，岂不哀哉！先王知雍蔽之伤国也，故置公卿、大夫、士，以饰法设刑，而天下治。其强也，禁暴诛乱而天下服；其弱也，五伯征而诸侯从；其削也，内守外附而社稷存。故秦之盛也，繁法严刑而天下振；及其衰也，百姓怨望而海内畔矣。故周五序得其道，而千余岁不绝；秦本末并失，故不能长。由是观之，安危之统相去远矣。野谚曰：“前事之不忘，后事之师也。”是以君子为国，观之上古，验之当世，参之人事，察盛衰之理，审权势之宜，去就有序，变化因时，故旷日长久而社稷安矣。
秦孝公据崤函之固，拥雍州之地，君臣固守以窥周室，有席卷天下，包举宇内，囊括四海之意，并吞八荒之心。当是时也，商君佐之，内立法度，务耕织，修守战之具；外连衡而斗诸侯。于是秦人拱手而取西河之外。孝公既没，惠文、武、昭襄蒙故业，因遗策，南取汉中，西举巴、蜀，东割膏腴之地，北收要害之郡。诸侯恐惧，会盟而谋弱秦，不爱珍器重宝肥饶之地，以致天下之士，合从缔交，相与为一。当此之时，齐有孟尝，赵有平原，楚有春申，魏有信陵。此四君者，皆明智而忠信，宽厚而爱人，尊贤而重士，约从离衡，兼韩、魏、燕、楚、齐、赵、宋、卫、中山之众。于是六国之士，有宁越、徐尚、苏秦、杜赫之属为之谋，齐明、周最、陈轸、召（shào）滑、楼缓、翟（zhái）景、苏厉、乐（yùe）毅之徒通其意，吴起、孙膑、带佗、倪良、王廖、田忌、廉颇、赵奢之伦制其兵。尝以十倍之地，百万之众，叩关而攻秦。秦人开关延敌，九国之师，逡（qūn）巡而不敢进。秦无亡矢遗镞（zú）之费，而天下诸侯已困矣。于是从散约败，争割地而赂秦。秦有余力而制其弊，追亡逐北，伏尸百万，流血漂橹。因利乘便，宰割天下，分裂山河。强国请服，弱国入朝。延及孝文王、庄襄王，享国之日浅，国家无事。及至始皇，奋六世之余烈，振长策而御宇内，吞二周而亡诸侯，履至尊而制六合，执敲扑而鞭笞天下，威振四海。南取百越之地，以为桂林、象郡；百越之君，俯首系颈，委命下吏。乃使蒙恬北筑长城而守藩篱，却匈奴七百余里。胡人不敢南下而牧马，士不敢弯弓而报怨。于是废先王之道，焚百家之言，以愚黔首；隳（huī）名城，杀豪杰，收天下之兵，聚之咸阳，销锋镝（dí），铸以为金人十二，以弱天下之民。然后践华为城，因河为池，据亿丈之城，临不测之渊，以为固。良将劲弩守要害之处，信臣精卒陈利兵而谁何。天下已定，始皇之心，自以为关中之固，金城千里，子孙帝王万世之业也。始皇既没，余威震于殊俗。然陈涉瓮牖（yǒu）绳枢之子，氓（méng）隶之人，而迁徙之徒也；才能不及中人，非有仲尼、墨翟〔dí〕之贤，陶朱、猗（yī）顿之富；蹑足行伍之间，而倔起阡陌之中，率疲弊之卒，将数百之众，转而攻秦，斩木为兵，揭竿为旗，天下云集响应，赢粮而景从。山东豪俊遂并起而亡秦族矣。且夫天下非小弱也，雍州之地，崤函之固，自若也。陈涉之位，非尊于齐、楚、燕、赵、韩、魏、宋、卫、中山之君也；锄耰（yōu）棘矜（qín），非铦（xiān）于钩戟长铩也；谪戍之众，非抗于九国之师也；深谋远虑，行军用兵之道，非及向时之士也。然而成败异变，功业相反，何也？试使山东之国与陈涉度（duó）长絜（xié）大，比权量力，则不可同年而语矣。然秦以区区之地，致万乘之势，序八州而朝同列，百有余年矣；然后以六合为家，崤函为宫；一夫作难（nàn）而七庙隳，身死人手，为天下笑者，何也？仁义不施而攻守之势异也。
秦灭周祀，并海内，兼诸侯，南面称帝，以养四海。天下之士，斐然向风。若是，何也？曰：近古之无王者久矣。周室卑微，五霸既灭，令不行于天下。是以诸侯力政，强凌弱，众暴寡，兵革不休，士民罢弊。今秦南面而王天下，是上有天子也。既元元之民冀得安其性命莫不虚心而仰上。当此之时，专威定功，安危之本，在于此矣。秦王怀贪鄙之心，行自奋之智，不信功臣，不亲士民，废王道而立私爱，焚文书而酷刑法，先诈力而后仁义，以暴虐为天下始。夫兼并者高诈力，安危者贵顺权，此言取与守不同术也。秦离战国而王天下，其道不易，其政不改，是其所以取之守之者无异也。孤独而有之，故其亡可立而待也。借使秦王论上世之事，并殷、周之迹，以制御其政，后虽有淫骄之主，犹未有倾危之患也。故三王之建天下，名号显美，功业长久。今秦二世立，天下莫不引领而观其政。夫寒者利裋褐，而饥者甘糟糠。天下嚣嚣，新主之资也。此言劳民之易为仁也。向使二世有庸主之行而任忠贤，臣主一心而忧海内之患，缟素而正先帝之过；裂地分民以封功臣之后，建国立君以礼天下；虚囹圄而免刑戮，去收孥污秽之罪，使各反其乡里；发仓廪，散财币，以振孤独穷困之士；轻赋少事，以佐百姓之急；约法省刑，以持其后，使天下之人皆得自新，更节修行，各慎其身；塞万民之望，而以盛德与天下，天下息矣。即四海之内皆欢然各自安乐其处，惟恐有变。虽有狡害之民，无离上之心，则不轨之臣无以饰其智，而暴乱之奸弭矣。二世不行此术，而重以无道：坏宗庙与民，更始作阿房之宫；繁刑严诛，吏治刻深；赏罚不当，赋敛无度。天下多事，吏不能纪；百姓困穷，而主不收恤。然后奸伪并起，而上下相遁；蒙罪者众，刑戮相望于道，而天下苦之。自群卿以下至于众庶，人怀自危之心，亲处穷苦之实，咸不安其位，故易动也。是以陈涉不用汤、武之贤，不借公侯之尊，奋臂于大泽，而天下响应者，其民危也。故先王者，见终始不变，知存亡之由。是以牧民之道，务在安之而已矣。下虽有逆行之臣，必无响应之助。故曰：“安民可与为义，而危民易与为非”，此之谓也。贵为天子，富有四海，身在于戮者，正之非也。是二世之过也。
襄公立，享国十二年。初为西畤。葬西垂。生文公。
文公立，居西垂宫。五十年死，葬西垂。生静公。
静公不享国而死。生宪公。
宪公享国十二年，居西新邑。死，葬衙。生武公、德公、出子。
出子享国六年，居西陵。庶长弗忌、威累、参父三人，率贼贼\\出子鄙衍，葬衙。武公立。
武公享国二十年。居平阳封宫。葬宣阳聚东南。三庶长伏其罪。德公立。
德公享国二年。居雍大郑宫。生宣公、成公、缪公。葬阳。初伏，以御蛊。
宣公享国十二年。居阳宫。葬阳。初志闰月。
成公享国四年，居雍之宫。葬阳。齐伐山戎、孤竹。
缪公享国三十九年。天子致霸。葬雍。缪公学着人。生康公。
康公享国十二年。居雍高寝。葬竘社。生共公。
共公享国五年，居雍高寝。葬康公南。生桓公。
桓公享国二十七年。居雍太寝。葬义里丘北。生景公。
景公享国四十年。居雍高寝，葬丘里南。生毕公。
毕公享国三十六年。葬车里北。生夷公。
夷公不享国。死，葬左宫。生惠公。
惠公享国十年。葬车里（康景）。生悼公。
悼公享国十五年。葬僖公西。城雍。生剌龚公。
剌龚公享国三十四年。葬入里。生躁公、怀公。其十年，彗星见。
躁公享国十四年。居受寝。葬悼公南。其元年，彗星见。
怀公从晋来。享国四年。葬栎圉氏。生灵公。诸臣围怀公，怀公自杀。
肃灵公，昭子子也。居泾阳。享国十年。葬悼公西。生简公。
简公从晋来。享国十五年。葬僖公西。生惠公。其七年。百姓初带剑。
惠公享国十三年。葬陵圉。生出公。
出公享国二年。出公自杀，葬雍。
献公享国二十三年。葬嚣圉。生孝公。
孝公享国二十四年。葬弟圉。生惠文王。其十三年，始都咸阳。
惠文王享国二十七年。葬公陵。生悼武王。
悼武王享国四年，葬永陵。
昭襄王享国五十六年。葬茝阳。生孝文王。
孝文王享国一年。葬寿陵。生庄襄王。
庄襄王享国三年。葬茝阳。生始皇帝。吕不韦相。
献公立七年，初行为市。十年，为户籍相伍。
孝公立十六年。时桃李冬华。
惠文王生十九年而立。立二年，初行钱。有新生婴儿曰「秦且王」。
悼武王生十九年而立。立三年，渭水赤三日。
昭襄王生十九年而立。立四年，初为田开阡陌。
孝文王生五十三年而立。
庄襄王生三十二年而立。立二年，取太原地。庄襄王元年，大赦，修先王功臣，施德厚骨肉，布惠于民。东周与诸侯谋秦，秦使相国不韦诛之，尽入其国。秦不绝其祀，以阳人地赐周君，奉其祭祀。
始皇享国三十七年。葬郦邑。生二世皇帝。始皇生十三年而立。
二世皇帝享国三年。葬宜春。赵高为丞相安武侯。二世生十二年而立。
右秦襄公至二世，六百一十岁。
孝明皇帝十七年十月十五日乙丑，曰：
周历已移，仁不代母。秦直其位，吕政残虐，然以诸侯十三，并兼天下，极情纵欲，养育宗亲。三十七年，兵无所不加，制作政令，施于后王。盖得圣人之威，河神授图，据狼、狐，蹈参、伐，佐攻驱除，距之称始皇。始皇既殁，胡亥极愚，郦山未毕，复作阿房，以遂前策。云「凡所为贵有天下者，肆意极欲，大臣至欲罢先君所为」。诛斯、去疾，任用赵高。痛哉言乎！人头畜鸣，不威不伐恶，不笃不虚亡，距之不得留，残虐以促期，虽居形便之国，犹不得存。
子婴度次得嗣，冠玉冠，佩华绂，车黄屋，从百司，谒七庙。小人乘非位，莫不恍忽失守，偷安日日，独能长念却虑，父子作权，近取于户牖之间，竟诛猾臣，为君讨贼。高死之后，宾婚未得尽相劳，餐未及下咽，酒未及濡唇，楚兵已屠关中，真人翔霸上，素车婴组，奉其符玺，以归帝者。郑伯茅旗鸾刀。严王退舍。河决不可复壅，鱼烂不可复全。贾谊、司马迁曰：「向使婴有庸主之才，仅得中佐，山东虽乱，秦之地可全而有，宗庙之祀未当绝也。」秦之积衰，天下土崩瓦解，虽有周旦之材，无所复陈其巧，而以责一日之孤，误哉！俗传秦始皇起罪恶，胡亥极，得其理矣。复责小子，云秦地可全，所谓不通时变者也。纪季以酅，《春秋》不名。吾读《秦纪》，至于子婴车裂赵高，未尝不健其决，怜其志。婴死生之义备矣。
六国陵替，二周沦亡。并一天下，号为始皇。阿房云构，金狄成行。南游勒石，东瞰浮梁。滈池见遗，沙丘告丧。二世矫制，赵高是与。诈因指鹿，灾生噬虎。子婴见推，恩报君父。下乏中佐，上乃庸主。欲振穨纲，云谁克补。', '《史记·秦始皇本纪》这篇本纪出自《史记卷六·秦始皇本纪第六》，作者司马迁。这篇本纪以编年记事的形式，记载了秦始皇及秦二世一生的主要活动和所发生的重大事件，条理清晰，内容丰富，真实地反映了秦朝建立前后四十年间风云变幻的历史场面。', '', '秦始皇帝，是秦国庄襄王的儿子。庄襄王曾以秦昭王的孙子的身份作为人质抵押在赵国，在那里看见吕不韦的妾，十分喜爱，就娶了她，生了始皇。秦始皇是秦昭王四十八年（前259）在邯郸出生的。出生后，起名叫政，姓赵。在他十三岁那年，庄襄王去世，政继承王位做了秦王。这时候，秦国的疆域已吞并了巴郡、蜀郡和汉中，跨过宛县占据了楚国的郢（ｙǐｎｇ，影）都，设置了南郡；往北收取了上郡以东，占据了河东、太原和上党郡；往东到荥阳，灭掉西周、东周两国，设置了三川郡。吕不韦为相国，封十万户，封号是文信侯。招揽宾客游士，想借此吞并天下。李斯为舍人。蒙骜、王齮、麃公等为将军。秦王年纪小，刚刚登上位，把国事委托给大臣们。
晋阳发生叛乱，始皇元年（前246），将军蒙骜前去讨伐，平定了叛乱。二年（前245），麃公率兵攻打卷（ｑｕāｎ，圈）邑，杀了三万人。三年（前244）蒙骜攻打韩国，夺取十三座城邑。王齮死了。将军蒙骜攻打魏国（ｃｈàｎｇ，畅）、有诡。这年发生严重饥荒。四年（前243），攻取了邑、有诡。三月，停止进军。秦国人质从赵国返国，赵国太子也从秦国回赵。十月庚寅日，蝗虫从东方飞来，遮天蔽日。全国瘟疫流行。老百姓献上一千石粮食，授给爵位一级。五年（前242），将军蒙骜攻打魏国，平定了酸枣、燕邑、虚邑、长平、雍丘、山阳城，全部攻下来，夺取了二十个城邑。开始设置东郡。这年冬天打雷了。六年（前241），韩国、魏国、赵国、卫国、楚国一起进攻秦国，攻占了寿陵邑。秦国派出军队，五国停止了进军。秦国攻下卫国，逼近东郡，卫君角率领他的宗族迁居到野王，凭借山势险阻，保住了魏国的河内。七年（前240），彗星先在东方出现，又在北方出现，五月，又在西方出现。将军蒙骜在攻打龙、孤、庆都时战死了，秦军回师进攻汲县。彗星又在西方连续出现了十六天。夏太后去世。
八年（前239），秦王弟长安君成（ｊｉāｏ，骄）率领军队攻打赵国，在屯留造反了，结果他手下的军官都被杀死，那里的百姓被迁往临洮（ｔáｏ，逃）。前来讨伐成的将军壁死了，屯留人士兵蒲鶮（ｈè，鹤）。又造反，结果战死，死后还遭到鞭戮尸体的酷刑。黄河的鱼大批涌上岸边，人们赶着马车到东方去找食物。
嫪毐（ｌàｏǎｉ，涝矮）被封为长信侯，赐给他山阳的土地，让他居住在那里。宫室、车马、衣服、园林、打猎都听凭嫪毐的意愿。事情无论大小全由嫪毐决定。又把河西太原郡改为嫪毐的封国。
九年（前238），彗星又出现了，有时划过整个天空。进攻魏国的垣邑和蒲阳邑。四月，秦王留宿在雍地。己酉日，秦王举行表示已经成年的加冠礼，佩带宝剑。长信侯嫪毐作乱的事被发觉，他盗用秦王的大印和太后的印玺，发动京城部队和侍卫、官骑、戎狄族首领、家臣，企图攻打蕲（ｑí，其）年宫，发动叛乱。始皇得知后，命令相国昌平君、昌文君发兵攻击嫪毐。在咸阳作战中，杀死数百人，秦王都授给他们以爵位，连同参战的宦官，也授给爵位一级。嫪毐等人战败逃走。当即通令全国：如谁活捉到嫪毐，赐给赏钱一百万；杀掉他，赐给赏钱五十万。嫪毐等人全部被抓获。卫尉竭、内史肆、佐戈竭、中大夫令齐等二十人都被判处枭（ｘｉāｏ，消）刑，即斩下头颅悬挂在木竿上。对嫪毐处以五马分尸的车裂之刑以示众，并灭了他的家族。至于他的家臣，罪轻的处以鬼薪之刑，即服为宗庙打柴三年的劳役。还有四千余家被剥夺了官爵，迁徙到蜀郡，住在房陵县。这个月虽属孟夏，但十分寒冷，有冻死的人。杨端和进攻衍氏邑。彗星出现在西方，不久又出现在北方，从北斗往南接连出现了八十天。
十年（前237），相国吕不韦因受嫪毐牵连而被罢官。桓齮为将军。齐国和赵国派来使臣摆酒祝贺。齐国人茅焦劝说秦王道：“秦国正以夺取天下为大事，而大王有流放太后的名声，恐怕诸侯听说了，因此而背弃秦国啊。”秦王于是把太后从雍地接回咸阳，仍让她住在甘泉宫。
秦国大规模地进行搜索，驱逐在秦国做官的别国人。李斯上书劝说，秦王才废止了逐客令。李斯借机劝说秦王，建议首先攻取韩国，以此来恐吓其它国家，于是秦王派李斯去降服韩国。韩王为此而担忧，就跟韩非谋划削弱秦国。大梁人尉缭来到秦国，劝说秦王道：“凭着秦国这样强大，诸侯就象郡县的首脑，我只担心山东各国合纵，联合起来进行出其不意的袭击，这就是从前智伯、夫差、湣（ｍǐｎ，敏）王所以灭亡的原因所在。希望大王不要吝惜财物，给各国权贵大臣送礼，利用他们打乱诸侯的计划，这样只不过损失三十万金，而诸侯就可以完全消灭了。”秦王听从了他的计谋，会见缭时以平等的礼节相待，衣服饮食也与尉缭一样。尉缭说：“秦王这个人，高鼻梁，大眼睛，老鹰的胸脯，豺狼的声音，缺乏仁德，而有虎狼之心，穷困的时候容易对人谦下，得志的时候也会轻易地吃人。我是个平民，然而他见到我总是那样谦下。如果秦王夺取天下的心愿得以实现，天下的人就都成为奴隶了。我不能跟他长久交往。”于是逃走，秦王发觉，坚决劝止，让他当秦国的最高军事长官，始终采用了他的计谋。李斯执掌国政。
十一年（前236），主将王翦、次将桓齮、末将杨端和三军并为一军去攻打邺邑，没有攻下，先夺取了九座城邑。王翦就另外去攻打阏（è，恶）与、橑（ｌｉáｏ，辽）杨，留下王橑继续攻打邺邑。
王翦统率军队十八天，让军中年俸禄不满百石的小官回家，十人中挑选二人留在军队。桓齮夺取了邺城，王翦又命令他率兵去攻打栎阳，自己攻打阏与，都攻了下来。十二年（前235），文信侯吕不韦死去，被其宾客偷偷安葬在洛阳北芒山。对于他的家臣参加哭吊的，如是晋国人，就赶出国境；如是秦国人，俸禄在六百石以上的官剥夺其爵位，迁到房陵；俸禄在五百石以下而未参与哭吊的，也迁到房陵，但不剥夺爵位。从此以后，掌管国事不遵循正道象嫪毐、吕不韦这样的，，就登记没收他的家人充作奴隶，不得做官，全部照此办理。秋天，免除迁居蜀郡的嫪毐家臣的赋税徭役。这时，全国大旱，从六月起，直到八月才下了雨。
十三年（前234），桓齮攻打赵国平阳邑，杀了赵将扈（ｈù，护）辄，斩首十万人。秦王到河南去。正月，彗星出现在东方。十月，桓齮攻打赵国。十四年（前233），在平阳攻击赵军，攻占了宜安，打败了赵国军队，杀死了赵国的将军。桓齮平定了平阳、武城。韩非出使到秦国，秦国采纳了李斯的计谋，扣留了韩非，韩非死在云阳。韩王请求向秦称臣。
十五年（前232），秦国大举出兵，一路到达邺县，一路到达太原，攻占了狼孟。这一年发生了地震。十六年（前231）九月，派军队去接收原韩国南阳一带土地，任命腾为代理南阳太守。开始命令男子登记年龄，以便征发兵卒、徭役。魏国向秦国献地。秦国设置丽邑。十七年（前230），内史腾去攻打韩国，擒获了韩王安，收缴了他的全部土地。把那个地方设置为郡。命名为颍川郡。又发生了地震。华阳太后去世。人民遭遇到大饥荒。
十八年（前229），秦大举兴兵攻赵，王翦统率上地的军队，攻占了井陉。杨端和率领河内的军队，羌瘣（ｈｕì，会）攻打赵国，杨端和包围了邯郸城。十九年（前228），王翦、羌瘣全部平定打下了赵国的东阳，俘获赵王。他们又想率兵攻打燕国，驻扎在中山。秦王到邯郸去，找到当初与秦王生在赵国时的母家有仇的那些人，把他们全部活埋了。秦王返回，经由太原、上郡回到都城。秦始皇的母太后去世。赵公子嘉率领他的宗族几百人到代地，自立为代王，向东与燕国的军队会合，驻扎在上谷郡。这年发生大饥荒。
二十年（前227），燕太子丹担心秦国军队打到燕国来，十分恐慌，派荆轲去刺杀秦王。秦王发现了，处荆轲以肢解之刑来示众，然后就派遣王翦、辛胜去攻打燕国。燕国、代国发兵迎击秦军，秦军在易水西边击溃了燕军。二十一年（前226），王贲（ｂēｎ，奔）去攻打楚国。秦王增派援兵到王翦军队中去，终于打败燕太子的军队，攻占了燕国的蓟城，拿到了燕太子丹的首级。燕王向东收取了辽东郡的地盘，在那里称王。王翦推说有病，告老还乡。新郑造反。昌平君被迁谪到郢城。这一年下了大雪，雪厚二尺五寸。
二十二年（前225），王贲去攻打魏国，引汴河的水灌大梁城，大梁城墙塌坏，魏王假请求投降，秦军取得了魏国的全部土地。
二十三年（前224），秦王再次诏令征召王翦，强行起用他，派他去攻打楚国。攻占了陈县往南直到平舆县的土地，俘虏了楚王。秦王巡游来到郢都和陈县。楚将项燕拥立昌平君做了楚王，在淮河以南反秦。二十四年（前223），王翦、蒙武去攻打楚国，打败楚军，昌平君死，项燕于是也就自杀了。
二十五年（前222），大规模举兵，派王贲为将领，攻打燕国的辽东郡，俘获燕王姬喜。回来时又进攻代国，俘虏了代王赵嘉。王翦于是平定了楚国的长江以南一带，降服了越族的首领，设置了会稽郡。五月，秦国为庆祝灭掉五国而下令特许天下聚饮。
二十六年（前221），齐王田建和他的相国后胜派军队防守齐国西部边境，断绝和秦国的来往。秦王派将军王贲经由燕国往南进攻齐国，俘获了齐王田建。
秦国刚统一天下，命令丞相、御史说：“从前韩王交出土地献上印玺，请求做守卫边境的臣子，不久又背弃誓约，与赵国、魏国联合反叛秦国，所以派兵去讨伐他们，俘虏了韩国的国王。我认为这很好，因为这样或许就可以停止战争了。赵王派他的相国李牧来订立盟约，所以归还了他们抵押在这里的质子。不久他们就违背了盟约，在太原反抗我们，所以派兵去讨伐他们，俘获了赵国的国王。赵公子嘉竟然自立为代王，所以就派兵去灭了赵国。魏王起初已约定归服于秦，不久却与韩国、赵国合谋袭击秦国，秦国官兵前去讨伐，终于打败了他们。楚王献出青阳以西的地盘，不久也背弃誓约，袭击我南郡，所以派兵去讨伐，俘获了楚国的国王，终于平定了楚地。燕王昏乱糊涂，他的太子丹竟然暗中派荆轲来做刺客，秦国官兵前去讨伐，灭掉了他的国家。齐王采用后胜的计策，继绝了与秦国的使臣来往，想要作乱，秦国官兵前去讨伐，俘虏了齐国国王，平定了齐地。我凭着这个渺小之身，兴兵诛讨暴乱，靠的是祖宗的神灵，六国国王都依他们的罪过受到了应有的惩罚，天下安定了。现在如果不更改名号，就无法显扬我的功业，传给后代。请商议帝号。”丞相王绾（ｗǎｎ，碗）、御史大夫冯劫、廷尉李斯等都说：“从前五帝的土地纵横各千里，外面还划分有侯服、夷服等地区，诸侯有的朝见，有的不朝见，天子不能控制，现在您兴正义之师，讨伐四方残贼之人，平定了天下，在全国设置郡县，法令归于一统，这是亘古不曾有，五帝也比不上的。我们恭谨地跟博士们商议说：‘古代有天皇、有地皇、有泰皇，泰皇最尊贵。’我们这些臣子冒死罪献上尊号，王称为‘泰皇’。发教令称为‘制书’，下命令称为‘诏书’，天子自称为‘朕’。秦王说：“去掉‘泰’字，留下‘皇’字，采用上古‘帝’的位号，称为‘皇帝’，其它就按你们议论的办。”于是下令说：“可以”。追尊庄襄王为太上皇。又下令说：“我听说上古有号而没有谥，中古有号，死后根据生前品行事迹给个谥号。这样做，就是儿子议论父亲，臣子议论君主了，非常没有意义，我不取这种做法。从今以后，废除谥法。我就叫做始皇帝，后代就从我这儿开始，称二世、三世直到万世，永远相传，没有穷尽。”
秦始皇按照水、火、木、金、土五行相生相克、终始循环的原理进行推求，认为周朝占有火德的属性，秦朝要取代周朝，就必须取周朝的火德所抵不过的水德。现在是水德开始之年，为顺天意，要更改一年的开始。群臣朝见拜贺都在十月初一这一天。衣服、符节和旗帜的装饰，都崇尚黑色。因为水德属阴，而《易》卦中表示阴的符号阴爻（ｙáｏ，遥）叫做“元”，就把数目以十为终极改成以六为终极，所以符节和御史所戴的法冠都规定为六寸，车宽为六尺，六尺为一步，一辆车驾六医马。把黄河改名为“德水”，以此来表示水德的开始。刚毅严厉，一切事情都依法律决定，刻薄而不讲仁爱、恩惠、和善、情义，这样才符合五德中水主阴的命数。于是把法令搞得极为严酷，犯了法久久不能得到宽赦。
丞相王绾等进言说：“诸侯刚刚被打败，燕国、齐国、楚国地处偏远，不给它们设王，就无法镇抚那里。请封立各位皇子为王，希望皇上恩准。”始皇把这个建议下交给群臣商议，群臣都认为这样做有利。廷尉李斯发表意见说：“周文王、周武王分封子弟和同姓亲属很多，可是他们的后代逐渐疏远了，互相攻击，就像仇人一样，诸侯之间彼此征战，周天子也无法阻止。现在天下靠您的神灵之威获得统一，都划分成了郡县，对于皇子功臣，用公家的赋税重重赏赐，这样就很容易控制了。要让天下人没有邪异之心，这才是使天下安宁的好办法啊。设置诸侯没有好处。”始皇说：“以前，天下人都苦于连年战争无止无休，就是因为有那些诸侯王。现在我依仗祖宗的神灵，天下刚刚安定如果又设立诸侯国，这等于是又挑起战争想要求得安宁太平，岂不困难吗？廷尉说得对。”
于是把天下分为三十六郡。每郡都设置守、尉、监。改称人民所做“黔首”。下令全国特许聚饮以表示欢庆。收集天下的兵器，聚集到咸阳，熔化之后铸成大钟，十二个铜人，每个重达十二万斤，放置在宫廷里。统一法令和度量衡标准。统一车辆两轮间的宽度。书写使用统一的隶书。领土东到大海和朝鲜，西到临洮、羌中，南到北向户，往北据守黄河作为要塞。沿着阴山往东一直到达辽东郡。迁徙天下富豪人家十二万户到咸阳居住。诸如祖庙及章台宫、上林苑都在渭水南岸。秦国每灭掉一个诸侯，都按照该国宫室的样子，在咸阳北面的山坡上进行仿造，南边濒临渭水，从雍门往东直到泾、渭二水交会处，殿屋之间有天桥和环行长廊互相连接起来。从诸侯那里虏得的美人和钟鼓乐器之类，都放到那里面。
二十七年（前220），秦始皇去巡视陇西、北地，穿过鸡头山，路经回中。于是在渭水南面建造信宫。不久，又把信宫改名叫极庙，以象征处于天极的北极星。从极庙开通道路直达郦山，又修建了甘泉前殿。修造两旁筑墙的甬道，从咸阳一直连接到骊山。这一年，普遍赐给爵位一级。修筑供皇帝巡行用的通向全国各地的驰道。
二十八年（前219），始皇到东方去巡视郡县，登上邹县峄（ｙì，译）山。在山上立了石碑，又跟鲁地儒生们商议，想刻石以颂扬秦之德业，商议在泰山祭天、在梁父山祭地和遥祭名山大川的事情。于是登上泰山，树立石碑，筑起土坛，举行祭天盛典。下山时，突然风雨大作，始皇歇息在一颗树下，因此赐封那颗树为“五大夫”，接着在梁父山举行祭地典礼，在石碑上镌刻碑文。碑文是：皇帝登基即位，创立昌明法度，臣下端正谨慎。就在二十六年（前222），天下归于一统，四方无不归顺。亲自巡视远方，登临这座泰山，东方一览极尽。随臣思念伟绩，推溯事业本源，敬赞功德无限。治世之道实施，诸种产业得宜，一切法则大振，大义清明美善，传于后代子孙，永世承继不变。皇帝圣明通达，既已平定天下，毫不懈怠国政。每日早起晚睡，建设长远利益，专心教化兴盛。训民皆以常道，远近通达平治，圣意人人尊奉。贵贱清楚分明，男女依礼有别，供职个个虔敬。光明通照内外，处处清净安泰，后世永续德政。教化所及无穷，定要遵从遗诏，重大告诫永世遵奉。于是就沿着渤海岸往东走，途经黄县、腄县，攀上成山的顶峰，又登上之罘（ｆú，浮）山，树立石碑歌颂秦之功德，然后离去。又往南走登上了琅邪山，十分高兴，在那里停留了三个月。
于是迁来百姓三万户到琅邪台下居住，免除他们十二年的赋税徭役。修筑琅邪台。立石刻字，歌颂秦之功德，表明自己因如愿以偿而感到满意的心情。碑文说：二十八年（前219），皇帝刚刚登基。端正一切法度，整治万物纲纪。彰明人事之宜，提倡子孝父慈。皇帝圣智仁义，宣明各种道理。亲临东土安抚，慰劳视察兵士。大事业已完毕，巡行滨海之地。皇帝伟大功绩，操劳根本大事。实行重农抑商，为使百姓富裕。普天之下同心，顺从皇帝意志。统一器物度量，统一书写文字。日月照耀之处，车船所到之地，无不遵奉王命，人人得志满意。顺应四时行事，自有大秦皇帝。整顿恶劣习俗，跋山涉水千里。怜惜黎民百姓，日夜不肯歇息。除疑惑定法律，无人不守法纪。地方长官分职，各级官署治理，举措必求得当，无不公平整齐。皇帝如此圣明，亲自视察四方。无论尊卑贵贱，不越等级规章。奸邪一律不容，务求忠贞贤良。事情不分大小，竭力不倦争强。无论远处近处，只求严肃端庄。正直敦厚忠诚，事业才能久长。皇帝大恩大德，四方均得安抚。诛除祸乱灾害。为国谋利造福。劳役不误农时，百业繁荣富足。黎民安居乐业，不再用兵动武。六亲终得相保，盗寇从此尽除。欢欣接受教化，法规都能记住。天地四方之内，尽是皇帝之土。西边越过沙漠，南边到达北户。东边到达东海，北边越过大夏。人迹所到之处，无不称臣归服。功高盖过五帝，恩泽遍及马牛。无人不受其德，家家安宁和睦。秦王兼有天下，建立名号称做皇帝，亲临东土安抚百姓，到达琅邪。列侯武成侯王离、列侯通武侯王贲、伦侯建成侯赵亥、伦侯昌武侯成、伦侯武信侯冯毋择、丞相隗（ｋｕí，逵）林、丞相王绾、卿李斯、卿王戊、五大夫赵婴、五大夫杨樛（ｊｉū，究）随从着在海上一起议论皇帝的功德。都说：“古代的帝王，土地不超过千里，诸侯各守受封之土，朝见与否各异。互相攻伐侵犯，暴乱残杀不止，还要刻金镂石，立碑夸耀自己。
古代五帝三王，知识教育不同，法令制度不明，借助鬼神之威，欺凌压迫远方，其实不称其名，所以不能久长。他们还未死，诸侯业已背叛，法令名存实亡。当今皇帝统一海内，全国设立郡县，天下安定太平。显明祖先宗庙，施行公道德政，皇帝尊号大成。群臣齐颂皇帝，功德刻于金石，树作典范永恒。”刻石事情完毕，齐地人徐市等上书，说大海之中有三座神山，名叫蓬莱、方丈、瀛洲，有仙人居住在那里。希望能斋戒沐浴，带领童男童女前往求仙。于是就派徐市挑选童男童女几千人，到海中去寻找仙人。始皇返回京城，路经彭城，斋戒祈祷，想要从泗水中打捞出那只落水的周鼎。派了一千人潜入水底寻找，没有找到。于是向西南渡过淮河，前往衡山、南郡。乘船顺江而下，来到湘山祠。遇上了大风，几乎不能渡河。皇上问博士说：“湘君是什么神？”博士回答说：“听说是尧的女儿，舜的妻子，埋葬在这里。”始皇非常生气，就派了三千服刑役的罪犯，把湘山上的树全部砍光，因为当地是红土，所以使山变成了赭红色。皇上从南郡经由武关回到京城。二十九年（前218），始皇到东方去巡游。到达阳武县博浪沙时，遭到张良和一名力士的行刺，刺客误中副车，始皇受了惊吓，捉拿刺客没有捉到，就命令全国大规模搜捕了十天。登上之罘山，刻石立碑，碑文是：二十九年（前218），正值仲春时节，春日阳气上升。皇帝东来游览，巡行登上之罘，观赏大海汪洋。诸臣赞赏景物，追颂伟业初创。圣君始建治道，确定制度法规，彰明准则纪纲。对外教化诸侯，广施礼乐恩德，大义公理显扬。六国之君邪僻，贪利永无满足，虐杀不止疯狂。皇帝哀怜民众，发师前往征讨，武德奋扬大振。仗义讨伐守信，声威光烈遍传，海内无不归顺。彻底消除强暴，努力拯救万民，遍安四方远近。明法普遍施行，天下治理安定，永为法则无伦。伟大啊！天地神州赤县，圣意共同遵循。群臣歌颂功德，请求刻于石碑，表率千古永不陨。在东观，又刻碑文说：二十九年（前218），皇帝春日出游，巡行来到远方。幸临东海之滨，登上之罘高山，观赏初升朝阳。遥望广阔绚丽，众臣推原思念，圣道灿烂辉煌。圣法刚刚实行，对内清理陋习，对外诛灭暴强。军威远扬四海，震撼四面八方，终于禽灭六王。开拓一统天下，灭绝种种灾害，兵器永远收藏。皇帝修明圣德，经营治理天下，明视兼听不倦。树立申明大义，设置种种器物，全有等级标志。大臣安守职分，都知各自事务，诸事毕无猜疑。百姓移风易俗，远近同一法度，终身守法不移。贯常职务已定，后代遵循先业，永远承袭圣治。群臣颂扬大德，敬赞圣明伟业，请刻之罘永志。不久，始皇前往琅邪，经由上党返回京城。三十年（前217），没有什么事情。
三十一年（前216）十二月，因为一首民谣说“帝若学之（仙）腊嘉平”，始皇有求仙之志，所以把腊月改名为“嘉平”。赐给每个里（一百户）六石米，二只羊。始皇在咸阳穿便装出行，和四个武士一起，晚上在兰池遇见了强盗，情势危急，武士们打死了强盗，于是在关中大规模搜查了二十天。米价每石一千六百钱。三十二年（前215），始皇前往碣石，派燕国人卢生访求方士羡门、高誓。在碣石山门刻石立碑。毁坏了城墙，挖通了堤防。所以碑文说：皇帝兴师用兵，诛灭无道之君，要把反叛平息。武力消灭暴徒，依法平反良民，民心全都归服。论功行赏众臣，惠泽施及牛马，皇恩遍布全国。皇帝振奋神威，以德兼并诸侯，天下统一太平。拆除关东旧城，挖通河川堤防，夷平各处险阻。地势既已平坦，众民不服徭役，天下都得安抚。男子欣喜耕作，女子修治女红，事事井然有序。皇恩覆盖百业，合力勤勉耕田，无不乐业安居。群臣敬颂伟业，敬请镌刻此石，永留典范规矩。于是派韩终、侯公、石生去寻找仙人不死之药。始皇巡视北部边界，经由上郡返回京城。燕国人卢生被派入海求仙回来了。为了鬼神的事，他奏上了宣扬符命占验的图录之书，上面写着“灭亡秦朝的是胡”。据说这个“胡”字是指胡亥，可是始皇没有理解，就派将军蒙恬率兵三十万去攻打北方的胡人，夺取了黄河以南的土地。三十三年（前214），征发那些曾经逃亡的犯人，典押给富人做奴隶、主家又给娶了妻子的人，以及商贩，去夺取陆梁地区，设置桂林、象郡、南海等郡，把受贬谪的人派去防守。又在西北驱逐匈奴。从榆中沿黄河往东一直连接到阴山，划分成四十四个县。沿河修筑城墙，设置要塞。又派蒙恬渡过黄河去夺取高阙、阳山、北假一带地方，筑起堡垒以驱逐戎狄。迁移被贬谪的人，让他们充实新设置的县。发布禁令不准祭祀主稼穑的灵星。彗星出现在西方。三十四年（前213），贬谪执法不正的法官去修筑长城及戌守南越地区。
秦始皇在咸阳宫摆设酒宴，七十位博士上前献酒颂祝寿辞。仆射（ｙè，夜）周青臣走上前去颂扬说：“从前秦国土地不过千里，仰仗陛下神灵明圣，平定天下，驱逐蛮夷，凡是日月所照耀到的地方，没有不臣服的。把诸侯国改置为郡县，人人安居乐业，不必再担心战争，功业可以传之万代。您的威德，自古及今无人能比。”始皇十分高兴。博士齐人淳于越上前说：“我听说殷朝、周朝统治天下达一千多年，分封子弟功臣，给自己当作辅佐。如今陛下拥有天下，而您的子弟却是平民百姓，一旦出现象齐国田常、晋国六卿之类谋杀君主的臣子，没有辅佐，靠谁来救援呢？凡事不师法古人而能长久的，还没有听说过。刚才周青臣又当面阿谀，以致加重陛下的过失，这不是忠臣。”始皇把他们的意见下交群臣议论。丞相李斯说：“五帝的制度不是一代重复一代，夏、商、周的制度也不是一代因袭一代，可是都凭着各自的制度治理好了，这并不是他们故意要彼此相反，而是由于时代变了，情况不同了。现在陛下开创了大业，建立起万世不朽之功，这本来就不是愚陋的儒生所能理解的。况且淳于越所说的是夏、商、周三代的事，哪里值得取法呢？从前诸侯并起纷争，才大量招揽游说之士。现在天下平定，法令出自陛下一人，百姓在家就应该致力于农工生产，读书人就应该学习法令刑禁。现在儒生们不学习今天的却要效法古代的，以此来诽谤当世，惑乱民心。丞相李斯冒死罪进言：古代天下散乱，没有人能够统一，所以诸侯并起，说话都是称引古人为害当今，矫饰虚言挠乱名实，人们只欣赏自己私下所学的知识，指责朝廷所建立的制度。当今皇帝已统一天下，分辨是非黑白，一切决定于至尊皇帝一人。可是私学却一起非议法令，教化人们一听说有命令下达，就各根据自己所学加以议论，入朝就在心里指责，出朝就去街巷谈议，在君主面前夸耀自己以求取名利，追求奇异说法以抬高自己，在民众当中带头制造谤言。象这样却不禁止，在上面君主威势就会下降，在下面朋党的势力就会形成。臣以为禁止这些是合适的。我请求让史官把不是秦国的典籍全部焚毁。除博士官署所掌管的之外，天下敢有收藏《诗》、《书》、诸子百家著作的，全都送到地方官那里去一起烧掉。有敢在一块儿谈议《诗》、《书》的处以死刑示众，借古非今的满门抄斩。官吏如果知道而不举报，以同罪论处。命令下达三十天仍不烧书的，处以脸上刺字的黥刑，处以城旦之刑四年，发配边疆，白天防寇，夜晚筑城。所不取缔的，是医药、占卜、种植之类的书。如果有人想要学习法令，就以官吏为师。”秦始皇下诏说：“可以。”三十五年（前212），开始修筑道路，经由九原一直修到云阳，挖掉山峰填平河谷，笔直贯通。这时始皇认为咸阳人口多，先王宫廷窄小，听说周文王建都在丰，武王建都在镐（ｈàｏ，号），丰、镐两城之间，才是帝王的都城所在。于是就在渭水南上林苑内修建朝宫。先在阿房（ēｐáｎｇ，阴平鹅、旁）建前殿，东西长五百步，南北宽五十丈，宫中可以容纳一万人，下面可以树立五丈高的大旗。四周架有天桥可供驰走，从宫殿之下一直通到南山。在南山的顶峰修建门阙作为标志。又修造天桥，从阿房跨过渭水，与咸阳连接起来，以象征天上的北极星、阁道星跨过银河抵达营室星。阿房宫没有建成；计划等竣工之后，再选择一个好名字给它命名。因为是在阿房修筑此宫，所以人们就称它为阿房宫，爱过宫刑、徒刑的七十多万人，分别被派去修建阿房宫，有的去营建骊山。从北山开采来山石，从蜀地、荆地运来木料。关中总共建造宫殿三百座，关外建四百座。于是在东海边的朐（ｑú，渠）山上竖立大石，作为秦朝国境的东门。为此迁徙三万家到骊邑，五万家到云阳，都免除十年的赋税和徭役。卢生劝说始皇道：“我们寻找灵芝、奇药和仙人，一直找不到，好像是有什么东西伤害了它们。
我们心想，皇帝要经常秘密出行以便驱逐恶鬼，恶鬼避开了，神仙真人才会来到。皇上住的地方如果让臣子们知道，就会妨害神仙。真人是入水不会沾湿，入火不会烧伤的，能够乘驾云气遨游，寿命和天地共久长。现在皇上治理天下，还没能做到清静恬淡。希望皇上所住的宫室不要让别人知道，这样，不死之药或许能够得到。”于是始皇说：“我羡慕神仙真人，我自己就叫‘真人’，不再称‘朕’了。”于是令咸阳四旁二百里内的二百七十座宫观都用天桥、甬道相互连接起来；把帷帐、钟鼓和美人都安置在里边，全部按照所登记的位置不得移动。皇帝所到的地方，如有人说出去，就判死罪。有一次皇帝幸临梁山宫，从山上望见丞相的随从车马众多，很不赞成。宦官近臣里有人把这件事告诉了丞相，丞相以后就减少了车马数目，始皇生气地说：“这是宫中有人泄露了我的话。”经过审问，没有人认罪，就下诏把当时跟随在旁的人抓起来，全部杀掉。从此以后再没有人知道皇帝的行踪。处理事务，群臣接受命令，全在咸阳宫进行。侯生、卢生一起商量说：“始皇为人，天性粗暴凶狠，自以为是，他出身诸侯，兼并天下，诸事称心，为所欲为，认为从古到今没有人比得上他。他专门任用治狱的官吏，狱吏们都受到亲近和宠幸。博士虽然也有七十人，但只不过是虚设充数的人员。丞相和各位大臣都只是接受已经决定的命令，依仗皇上办事。皇上喜欢用重刑、杀戮显示威严，官员们都怕获罪，都想保持住禄位，所以没有人敢真正竭诚尽忠。皇上听不到自己的过错，因而一天更比一天骄横。臣子们担心害怕，专事欺骗，屈从讨好。秦法规定，一个方士不能兼有两种方术，如果方术不能应验，就要处死。然而占侯星象云气以测吉凶的人多达三百，都是良土，然而由于害怕获罪，就得避讳奉承，不敢正直地说出皇帝的过错。天下的事无论大小都由皇上决定，皇上甚至用称来称量各种书写文件的竹简木简的重量，日夜都有定额，阅读达不到定额，就不能休息。他贪于权势到如此地步，咱们不能为他去找仙药。”于是就逃跑了。始皇听说二人逃跑，十分恼怒地说：“我先前查收了天下所有不适用的书都把它们烧掉。征召了大批文章博学之士和有各种技艺的方术之士，想用他们振兴太平，这些方士想要炼造仙丹寻找奇药。今天听说韩众逃跑了不再还报。徐市等人花费的钱以数万计算，最终也没找到奇药，只是他们非法谋利互相告发的消息传到我耳朵里。对卢生等人我尊重他们，赏赐十分优厚，如今竟然诽谤我，企图以此加重我的无德。这些人在咸阳的，我派人去查问过，有的人竟妖言惑众，扰乱民心。”于是派御吏去一一审查，这些人辗转告发，一个供出一个，始皇亲自把他们从名籍上除名，一共四百六十多人，全部活埋在咸阳，让天下的人知道，以惩戒以后的人。征发更多的流放人员去戌守边疆。始皇的大儿子扶苏进谏说：“天下刚刚平定，远方百姓还没有归附，儒生们都诵读诗书，效法孔子，现在皇上一律用重法制裁他们，我担心天下将会不安定，希望皇上明察。”始皇听了很生气，就派扶苏到北方上郡去监督蒙恬的军队。三十六年（前211），火星侵入心宿（ｘｉù，秀），这种天象象征着帝王有灾。有颗陨星坠落在东郡，落地后变为石块，老百姓有人在那块石头上刻了“始皇帝死而土地分。”始皇听说了，就派御史前去挨家查问，没有人认罪，于是把居住在那块石头周围的人全部抓来杀了，焚毁了那块陨石。始皇不高兴，让博士作了一首《仙真人诗》，等到巡行天下时，走到一处就传令乐师弹奏唱歌。秋天，使者从关东走夜路经过华阴平舒道，有人手持玉璧拦住使者说：“替我送给滈（ｈàｏ，皓）池君。”趁便说：“今年祖龙死。”使者问他缘由，那人忽然就不见了，放下那真玉璧离去。使者捧回玉璧向秦王陈述了所遇见的情况。始皇沉默了好一会，说：“山里鬼怪本来不过能预知一年的事。”当时已是秋季，始皇说今年的日子已不多，这话未必能应验。到退朝时他又说：“祖龙就是人的祖先。”故意把“祖”解释成祖先，祖先是已死去的人，因此“祖龙死”自然与他无关。始皇让御府察看那块玉璧，竟然是始皇二十八年出外巡视渡江时沉入水中的那块。于是始皇为此事进行占卜，占卜的结果是迁徙才吉利。迁移三万户人家到北河、榆中地区，每户授给爵位一级。
三十七年（前210）十月癸丑日，始皇外出巡游。左丞相李斯跟随着，右丞相冯去疾留守京城。少子胡亥想去巡游，要求跟随着，皇上答应了他。十一月，走到云梦，在九疑山遥祭虞舜。然后乘船沿长江而下，观览籍柯，渡过海渚（ｚｈǔ，煮），经过丹阳，到达钱塘。到浙江边上的时候，水波凶险，就向西走了一百二十里，从江面狭窄的地方渡过。登上会稽山，祭祀大禹，遥望南海。在那里刻石立碑，颂扬秦朝的功德。碑文是：皇帝功业伟大，统一平定天下，德惠深厚久长。三十七年，亲自巡行天下，遍游观览远方。登临会稽山峰，考察民间习俗，百姓恭敬景仰。群臣齐颂功德，推原皇帝事迹，追溯英明高强。秦朝圣王登位，创制刑法名称，阐述旧有规章。建立公平法则，审慎区分职责，确立永久纲纪。六国之王专横，贪利傲慢凶狠，凭借人多逞强。暴虐横行无忌，倚仗武力骄横，屡动干戈打仗。暗中安置坐探，联合六国合纵，行为卑鄙猖狂。对内说谎狡诈，向外侵我边境，由此引起祸殃。仗义扬威诛讨，消灭凶暴叛逆，乱贼终于灭亡。圣德广博深厚，天地四海之内，恩泽覆盖无疆。皇帝统一天下，一人兼理万机，远近到处清明。执掌管理万物，考察验证事实，分别记录其名。贵贱都能相通，好坏当前陈述，无人隐瞒实情。治有过扬道义，有夫弃子而嫁，背夫不贞无情。以礼分别内外，禁止纵欲放荡，男女都应洁诚。丈夫在外淫乱，杀了没有罪过，男子须守规程。妻子弃夫逃嫁，子不认她为母，都要感化清正。治理荡涤恶俗，全民承受教化，天下沐浴新风。人人遵守规矩，和好安定互勉，无不顺从命令。百姓美善清洁，全都自愿守法，乐保天下太平。后人敬奉圣法，大治大安无边，车船不翻不倾。众臣颂扬功业，请求刻石作铭，传千古放光明。始皇返回，途经吴地，从江乘县渡江。沿海岸北上，到达琅邪。方士徐市等人入海寻找仙药，好几年也没找到，花费钱财很多，害怕遭受责罚，就欺骗说：“蓬莱仙药可以找到，但常被大鲨鱼困扰，所以无法到达，希望皇上派善于射箭的人一起去，遇到大鲨鱼就用装有机关可以连续发射的弓弩射它。”
始皇作梦与海神交战，海神的形状好象人。请占梦的博士给圆梦，博士说：“水神本来是看不到的，它用大鱼蛟龙做侦探。现在皇上祭祀周到恭敬，却出现这种恶神，应当除掉它，然后真正的善神就可以找到了。”于是命令入海的人携带捕大鱼的工具，亲自带着有机关的弓弩去等侯大鱼出来以便射它。从琅邪向北直到荣成山，都不曾遇见。到达之罘的时候，遇见了大鱼，射死了一条。接着又沿海向西进发。秦始皇到达平原津时生了病。始皇讨厌说“死”这个字，群臣没有敢说死的事情。皇帝病得更厉害了，就写了一封盖上御印的信给公子扶苏说：“回咸阳来参加丧事，在咸阳安葬。”信已封好了，存放在中东府令赵高兼掌印玺事务的办公处，没有交给使者。七月丙寅日，始皇在沙丘平台逝世。丞相李斯认为皇帝在外地逝世，恐怕皇子们和各地乘机制造变故，就对此事严守秘密，不发布丧事消息。棺材放置在既密闭又能通风的辒（ｗēｎ，温）凉车中，让过去受始皇宠幸的宦官做陪乘，每走到适当的地方，就献上饭食，百官象平常一样向皇上奏事。宦官就在辒凉车中降诏批签。只有胡亥、赵高和五六个曾受宠幸的宦官知道皇上死了。赵高过去曾经教胡亥写字和狱律法令等事，胡亥私下里很喜欢他。赵高与公子胡亥、丞相李斯秘密商量拆开始皇赐给公子扶苏的那封已封好的信。谎称李斯在沙丘接受了始皇遗诏，立皇子胡亥为太子。又写了一封信给公子扶苏、蒙恬，列举他们的罪状，赐命他们自杀。这些事都记载在《李斯列传》中，继续往前走，从井陉到达九原。正赶上是暑天，皇上的尸体在辒凉车中发出了臭味，就下令随从官员让他们往车里装一石有腥臭气的腌鱼，让人们分不清尸臭和鱼臭。一路行进，从直道回到咸阳，发布治丧的公告。皇太子继承皇位，就是二世皇帝。九月，把始皇安葬在郦山。
始皇当初刚刚登位，就挖通治理了郦山，到统一天下后，从全国各地送来七十多万徒役，凿地三重泉水那么深，灌注铜水，填塞缝隙，把外棺放进去，又修造宫观，设置百官位次，把珍奇器物、珍宝怪石等搬了进去，放得满满的。命令工匠制造由机关操纵的弓箭，如有人挖墓一走近就能射死他。用水银做成百川江河大海，用机器递相灌注输送，顶壁装有天文图象，下面置有地理图形。用娃娃鱼的油脂做成火炬，估计很久不会熄灭。二世说：“先帝后宫妃嫔没有子女的，放她们出去不合适。”就命令这些人全部殉葬，殉葬的人很多。下葬完毕，有人说是工匠制造了机械，墓中所藏宝物他们都知道，宝物多而贵重，这就难免会泄露出去。隆重的丧礼完毕，宝物都已藏好，就封闭了墓道的中间一道门，又把墓地最外面的一道门放下来，工匠们全部被封闭在里边，没有一个再出来的。墓上栽种草木，从外边看上去好像一座山。二世皇帝元年（前209），二世二十一岁，赵高担任郎中令，执掌朝廷大权。二世下诏，增加始皇祠庙里用来祭祀的牲畜数量，增加山川各种祭祀的礼仪。命令大臣们讨论推尊始皇庙号的事。大臣们都叩头说：“古时候天子的祖庙为七庙，祭祀七代祖宗，诸侯五庙，大夫三庙，如今始皇庙是至高无上的，即使是万世以后也不能毁除，天下人都要贡献祭品赋税，增加祭祀用的牲畜，礼仪完全具备，不能有比这个再高的。先王庙有的在西雍，有的在咸阳。天子按礼仪应当单独捧着经多次酿制而且质醇的酎（ｚｈｏù，纣）酒祭祀始皇庙。从襄公以下的庙都毁除。所建共七庙。大臣们都依礼进献祭祀，推尊始皇庙为皇帝始祖庙。皇帝仍自称为‘朕’”。
二世跟赵高商议说：“我年纪轻，刚登位，百姓还不顺从。先帝巡视各郡县，以显示他的强有力，威势震服海内。现在我安然住在皇宫不出巡游，就让人看着我无能，没有办法统治天下。”春天，二世东行巡视郡县，李斯跟随着。到达碣石山，沿海南行到达会稽，在始皇所立的石碑上都刻上字，碑石旁都增刻上随从的大臣的名字，以使先帝的功业盛德更加明显。皇帝说：“金石碑刻全是始皇帝建造的。现在我承袭了皇帝名号，可是金石碑刻上不称始皇帝，以后年代久远了，就好像是后代子孙建造的，以致不能称扬始皇帝的功业和盛德。”丞相臣李斯、臣冯去疾、御史大夫臣德冒死罪进言说：“我们请求把诏书全刻在石碑上，这样就明白了。为臣冒死罪请求。”制书批复说：“可以。”接着到了辽东，然后返回。这时候秦二世就按照赵高的建议，申明法令。他暗中与赵高谋划说：“大臣们都不服从，官吏还很有力，还有各位皇子一定要跟我争权，对这些我该怎么办呢？”赵高说：“这些话我本来就想说却没敢说。先帝在位时的大臣，都是接连多少代有名望的贵人，建功立业，世代相传，已经很久了。如今为臣赵高生来卑贱，幸蒙陛下抬举，让我身居高位，管理宫廷事务。大臣们并不满意，只在表面上服从，实际上心里不服。现在皇上出巡，何不借此机会查办郡县守尉中的有罪者，把他们杀掉，这样，在上可以使皇上的威严震天下，在下可以除掉皇上一向所不满意的人。现时不能师法文治而应取决于武力，希望陛下能顺应时势，切勿犹豫，那么大臣们就来不及谋算了。英明的君主收集举用那些被弃不用的人。让卑贱的显贵起来，让贫穷的富裕起来，让疏远的变得亲近，这样就能上下团结国家安定了。”二世说：“好！”于是就诛杀大臣和皇子们，制造罪名连带拘捕近侍小臣中郎、外郎、散郎，没有一个得以免罪，六个皇子被杀死在杜县。皇子将闾兄弟三人被囚禁在内宫，议定他们的罪状。秦二世派使者命令将闾说：“你们不尽臣道，当外死罪，官吏依法行刑来了。”将闾说：“宫廷的礼节，我从来不敢不听从掌管司仪的宾赞；朝廷的位次，我从来不敢有失礼节；奉命对答，我从来不敢说错话。怎么能说不尽臣道呢？希望能知道罪名再死。”使者说：“我不能参与谋议，只是奉命行事。”将闾仰天大声呼喊，呼喊了几次说：“天啊！我没有罪！”兄弟三人都流着眼泪拔剑自杀了。皇族为之震惊恐慌。大臣们进谏的被认为是诽谤，大官们为保住禄位而屈从讨好，百姓震惊恐惧。
四月，二世返回到咸阳，说：“先帝因为咸阳朝廷小，所以营建阿房宫，室堂还没有建成，赶上始皇去世，只得让修建的人停下来，调到郦山去修墓。郦山修墓的工作已全部完毕，现在放下阿房宫而不把它建成，就是表明先帝办事有失误。”又开始修建阿房宫。对外安抚四方的外族，遵循始皇的策略，征召了五万身强力壮的兵丁守卫咸阳。下令教习射箭，还要饲养供宫廷玩赏的狗马禽兽，兵丁狗马禽兽所需粮食很多，估计咸阳仓里的粮食不够用，就从下面各郡县征调运来粮食和饲料，让转运人员都自带干粮，咸阳四百里之内不准吃这些粮食。施法更加严酷。七月，戌卒陈胜等在原生楚国之地造反，国号为“张楚”取张大楚国之意。陈胜自立为楚王，住在陈县，派遣将领们夺取土地。崤山函谷关以东的山东各郡县，年轻人因为受尽秦朝官吏之苦，都杀掉了他们的郡守、郡尉、县令、县丞，起来造反，以响应陈胜，并在各地相继拥立侯王，取合起来向西进攻，旗号都是讨伐秦朝，人数多得数也数不清。掌管传达通报的谒者出使山东回来，把山东造反的情况报告了二世。二世很生气，就把谒者下交给主管官吏去处理。后边的使者回来，皇上问他，他回答说：“那不过是一群盗匪，郡守、郡尉正在追捕，现在全部抓获了，不值得担心。”皇上高兴了。武臣自立为赵王，魏咎为魏王，田儋（ｄāｍ，担）为齐王，沛公在沛县起义。项梁在会稽郡起兵。二年（前208）冬天，陈胜派遣的周章等将领向西到达戏水，兵力有几十万。二世大为吃惊，跟群臣商议说：“怎么办？”少府章邯说：“盗匪已经来了，人数多势力强，现在征发附近各县的军队是来不及了。郦山徒役很多，请赦免他们，授予他们兵器去迎击起义军。”于是二世大赦天下，派章邯领兵为将，打败了周章的军队，周章败逃，被杀死在曹阳。
二世又增派长史司马欣、董翳（ｙì，义）去帮助章邯攻打起义军，在城父杀死了陈胜，在定陶打败了项梁，在临济杀死了魏咎。楚地起义军的名将已经被杀死，章邯就向北渡过黄河，到钜鹿攻打赵王赵歇等人。赵高劝说二世道：“先帝登位治理天下时间很久，所以群臣不敢做非分之事，不敢进言异端邪说。现在陛下正年轻，刚登皇位，怎么能跟公卿在朝廷上议决大事呢？事情如果有错误，就让群臣看出了自己的弱点。天子称“朕”，朕既然有征兆的意思，本来就是不让别人听到他的声音。”于是二世经常居住在深宫之内，只跟赵高一个人决定各种事情。从这以后公卿很少有机会朝见皇上，各地起义的人更多了，关中军队被征发到东边去攻打起义军的一直没有停止。右丞相冯去疾、左丞相李斯、将军冯劫进谏说：“关东各路盗贼纷纷而起，朝廷派兵前去诛讨，杀死的人很多，然而还不能平息。盗贼多都是因为戌边、运输、劳作的事情太劳苦，赋税太重。我们请求暂停阿房宫的修建，减少戌边兵役和运输徭役。”二世说：“我听韩子说：‘尧、舜用柞木做椽子，不进行砍削加工，用芦苇茅草盖屋顶不修剪，吃饭用瓦碗，喝水用瓦罐，即使是看门人的供养，也不会比这再俭薄了。禹平凿龙门，疏通大夏，疏导黄河淤积停滞之水，引水入海，亲自拿着杵和锹，小腿上的毛都被磨光了，即使是奴隶的劳苦，也不会比这再厉害了。’人们之所以看重享有天下，就是为了能纵欲而为，尽情享受，做君主重要的是修明法制，这样，臣下就不敢干坏事，就能统治天下了。虞、夏的君主，地位尊贵，做了天子，却身处穷苦境地，为百姓作出牺牲，这还有什么值得学习呢？天下被称为万乘（ｓｈèｎｇ，胜）之主，拥有万辆兵车，我身居万乘之高位，却没有万乘的实际，我要建造千乘之车驾，设立万乘之徒属，让实际跟我的名号相副。再说，先帝出身于诸侯，兼并了天下，天下已经平定，对外排除四方外族以安定边境，对内修建宫室来显示成功的得意，你们都看到了先帝功业已经就序。而现在我登位两年的时间，盗贼纷起，你们不能禁止，又想要终止先帝所要做的事情。这样做，对上不能报答先帝，其次也是不为我尽忠尽力，你们还凭什么身处高位呢？”于是把冯去疾、李斯、冯劫下交给狱吏，审讯追究三人的其他罪过。冯去疾、冯劫说：“将相不能受侮辱。”自杀了。李斯结果被囚受刑。二世三年（前207），章邯等率兵包围了巨鹿，楚国上将军项羽率领楚兵前去援救巨鹿。冬天，赵高担任丞相，终于判决杀了李斯。夏天，章邯等作战多次败退，二世派人去谴责章邯，章邯害怕了，就派长史司马欣回京汇报情况，请求指示。赵高既不接见，也不信任。司马欣害怕了，赶紧逃离，赵高派人去追，没有追到。司马欣见到章邯说：“
赵高在朝廷中掌权，将军您有功是被杀，无功也是被杀。”这时，项羽加紧进攻秦军，俘虏了王离，章邯等人就率兵投降了诸侯。八月己亥日，赵高想要谋反，恐怕群臣不听从他，就先设下计谋进行试验，带来一只鹿献给二世，说：“这是一匹马。”二世笑着说：“丞相错了，把鹿说成是马。”问左右大臣，左右大臣有的沉默，有的故意迎合赵高说是马，有的说是鹿，赵高就在暗中假借法律陷害那些说是鹿的人。以后，大臣们都畏惧赵高。赵高以前多次说：“关东的盗贼成不了什么气侯。”后来项羽在钜鹿城下俘虏了王离等人并继续前进，章邯等人的军队多次败退，上书请求增援，燕国、赵国、齐国、楚国、韩国、魏国都自立为王，从函谷关往东，大抵全部背叛了秦朝官吏而响应诸侯，诸侯都率兵西进。沛公率领几万人屠灭了武关，派人来跟赵高秘密接触。赵高害怕二世发怒，诛杀加害自身，就谎称有病不去朝见皇上。二世梦见一只白虎咬了他车驾的骖（ｃāｎ，参）马，他杀了那只白虎，但心中不乐，觉得奇怪，就去问解梦的人。解梦人卜得卦辞说：“泾水水神在作怪。”二世就在望夷宫斋戒，想要祭祀泾水水神，把四匹白马沉入泾水。二世派人以起义者日益逼近的事谴责赵高。赵高恐惧不安，就暗中跟他的女婿咸阳县令阎乐、他的弟弟赵成商量说：“皇上不听劝谏，如今事态危急，想要把罪祸推给咱们家族。我想另立天子，改立公子婴。子婴仁爱谦下，百姓都拥护他的话。”就让郎中令作内应，谎称有大盗，命令阎乐召集官吏发兵追捕，又劫持了阎乐的母亲，安置到赵高府中当人质。派阎乐带领官兵一千多人在望夷宫殿门前，捆绑上卫令仆射，喝问道：“盗贼从这里进去了，为什么不阻止？”卫令说：“皇宫周围警卫哨所都有卫兵防守，十分严密，盗贼怎么敢进入宫中？”阎乐就斩了卫令，带领官兵径直冲进去，一边走一边射箭，郎官宦官大为吃惊，有的逃跑，有的格斗，格斗的就被杀死，被杀死的有几十人。郎中令和阎乐一同冲进去，用箭射中了二世的帷帐。二世很生气，召唤左右的人，左右的人都慌乱了不敢动手。旁边有一个宦官服侍着二世不敢离开。二世进入内宫，对他说：“您为什么不早告诉我，竟到了现在这种地步！”宦官说：”为臣不敢说，才得以保住性命，如果早说，我们这班人早就都被您杀了，怎能活到今天？”阎乐走上前去历数二世的罪状说：“你骄横放纵、肆意诛杀，不讲道理，天下的人都背叛了你，怎么办你自己考虑吧！”二世说：“我可以见丞相吗？”阎乐说：“不行。”二世说：“我希望得到一个郡做个王。”阎乐不答应。又说：“我希望做个万户侯。”还是不答应。二世又说：“我愿意和妻子儿女去做普通百姓，跟诸公子一样。”阎乐说：“我是奉丞相之命，为天下人来诛杀你，你即使说了再多的话，我也不敢替你回报。”于是指挥士兵上前。二世自杀。阎乐回去禀报赵高，赵高就召来了所有的大臣和公子，把杀死二世的情况告诉了他们。赵高说：“秦国本来是个诸侯国，始皇统治了天下，所以称帝。现在六国又各自立了王，秦国地盘越来越小，竟然还凭着个空名称皇帝，这不合适。应象过去一样称王，才合适。”于是立二世兄长的儿子婴为秦王。按照平民的葬仪把二世埋葬在杜南宜春苑中。让子婴斋戒，到宗庙去拜祖先，接受国王印玺。
斋戒五天后，子婴跟他的两个儿子商议说：“丞相赵高在望夷宫杀了二世，害怕大臣们杀他，就假装按照道义立我为王。我听说赵高竟与楚国约定，灭掉秦宗室后他在关中称王。现在让我斋戒，朝见宗庙，这是想趁着我在庙里把我杀掉。我推说生病不能前往，丞相一定会亲自来，他来了就杀掉他。”赵高派人去请子婴，前后去了好几趟，子婴却不走，赵高果然亲自去请。说：“国家大事，王为什么不去呢？”子婴于是在斋宫杀了赵高，杀死赵高家三族，在咸阳示众。子婴做秦王四十六天，楚将沛公打败秦军进入武关，接着就到了霸上，派人去招降子婴。子婴用丝带系上脖子，驾着白车白马，捧着天子的印玺符节，在轵道亭旁投降。沛公于是进入咸阳，封了宫室府库，回师驻扎在霸上。过了一个多月，各路诸侯的军队也到了，项羽是各路诸侯的盟主，杀了子婴和秦公子宗室所有的人。随后屠戮咸阳，焚烧宫室，俘虏宫女，没收秦宫的珍宝财物，跟各路诸侯一起分了。灭掉秦王朝之后，把原来秦国的地盘划成三份各自为王，就是雍王、塞王、翟王，号称三秦。项羽为西楚霸王，主持分割天下，赐封诸侯王，秦朝终于灭亡了。此后五年，天下统一于汉。太史公说：秦朝的祖先伯益，在唐尧、虞舜的时候，曾经建立功勋，被封给土地，受赐姓嬴。到夏朝、商朝时衰落了。到周朝衰落的时候，秦国兴起，在西部边境建起城邑。从穆公即位以来，逐渐蚕食诸侯，最终成就了始皇。始皇自以为功业比五帝伟大，地盘比三王宽广，就认为跟五帝、三王相比是羞耻。贾生评论的话说得多好啊！他说：秦朝兼并了诸侯，山东有三十多个郡，修筑渡口关隘，占据着险要地势，修治武器，守护着这些地方。然而陈涉凭着几百名散乱的戌卒，振臂大呼，不用弓箭矛戟等武器，光靠锄把和木棍，虽然没有给养，但只要看到有人家住的房屋就能吃上饭，纵横驰骋天下，所向无敌。秦朝险阻之地防守不住了，关卡桥梁封销不封了，长戟刺不了，强弩射不了。楚军很快深入境内，鸿门一战，竟然连篱笆一样的阻拦都没有遇到。于是山东大乱，诸侯纷纷起事，豪杰相继立王。秦王派章邯率兵东征，章邯得此机会，就凭着三军的众多兵力，在外面跟诸侯相约，做交易，图谋他的主上。大臣们不可信用，从这件事就可以看出来了。子婴登位，最终也不曾觉悟，假使子婴有一般君主的才能，仅仅得到中等的辅佐之臣，山东地区虽然混乱，秦国的地盘还是可以保全的，宗庙的祭祀也不会断绝。秦国地势有高山阻隔，有大河环绕，形成坚固防御，是个四面都有险要关塞的国家。从穆公以来，一直到秦始皇，二十多个国君，经常在诸侯中称雄。难道代代贤明吗？这是地位形势造成的呀！再说天下各国曾经同心合力进攻秦国。在这种时候，贤人智士会聚，有良将指挥各国的军队，有贤相沟通彼此的计谋，然而被险阻困住不能前进，秦国就引诱诸侯进入秦国境内作战，为他们打开关塞，结果山东百万军队败逃崩溃。难道是因为勇气、力量和智慧不够吗？是地形不利，地势不便啊。秦国把小邑并为大城，在险要关塞驻军防守，把营垒筑得高高的而不轻易跟敌方作战，紧闭关门据守险塞，肩扛矛戟守卫在那里。诸侯们出身平民，是为了利益联合起来，并没德高望众而未居王位者的德行。
他们的交往不亲密，他们的下属不亲附。名义上是说灭亡秦朝，实际上是为自己谋求私利。他们看见秦地险阻难以进犯，就必定退兵。如果他们能安定本土，让人民休养生息，等待秦的衰败，收纳弱小，扶助疲困，那么凭着能对大国发号施令的君主，就不用担心在天下实现不了自己的愿望了。可是他们尊贵身为天子，富足拥有天下，自己却遭擒获，这是因为他们挽救败亡的策略错误啊。秦王满足一己之功，不求教于人，一错到底而不改变。二世承袭父过，因循不改，残暴苛虐以致加重了祸患。子婴孤立无亲，自处危境，却又柔弱而没有辅佐，三位君主一生昏惑而不觉悟，秦朝灭亡，不也是应该的吗？在这个时候，世上并非没有深谋远虑懂得形势变化的人士，然而他们所以不敢竭诚尽忠，纠正主上之过，就是由于秦朝的风气多有忌讳的禁规，忠言还没说完而自己就被杀戮了。所以使得天下之士只能侧着耳朵听，重叠双脚站立，闭上嘴巴不敢说话。因此，三位君主迷失了路途，而忠臣不敢进谏言，智士不敢出主意，天下已经大乱，皇上还不知道，难道不可悲吗？先王知道壅塞不通就会伤害国家，所以设置公卿、大夫和士，来整治法律设立刑罚，天下因而得到治理。强盛的时候，禁止残暴诛讨叛乱，天下服从；衰弱的时候，五霸为天子征讨，诸侯也顺从；土地被割削的时候，在内能自守备，在外还有亲附，社稷得以保存。所以秦朝强盛的时候，繁法严刑，天下震惊；等到它衰弱的时候，百姓怨恨，天下背叛。周朝的公、侯、伯、子、男五等爵位合乎根本大道，因而传国一千多年不断绝。而秦朝则是本末皆失，所以不能长久。由此看来，安定和危亡的纲纪相距太远了！俗话说‘前事不忘，后事之师’（过去的经验教训不忘记，就是以后做事的借鉴）。因此君子治理国家，考察于上古的历史，验证以当代的情况，还要通过人事加以检验，从而了解兴盛衰亡的规律，详知谋略和形势是否合宜，做到取舍有序，变化适时，所以历时长久，国家安定。秦孝公占据了殽山和函谷关的险固地势，拥有雍州的土地，君臣牢固防守，窥伺着周朝王室以图夺取政权，心怀席卷天下、包举宇内的意图，有着囊括四海、并吞八方的雄心。那时候，商君辅佐他，对内建立法令制度，致力于农耕和纺织，修治防守和攻战的器械设备，对外实行连衡，挑起诸侯之间的争斗，于是秦国人仅以举手之劳就取得了西河以外的土地。孝公死后，惠王、武王继承原有的基业，遵循孝公留下来的策略，向南兼并了汉中，向西夺得了巴、蜀，向东割取了肥沃的土地，占据了险要的郡县。诸侯害怕了，举行盟会来商议削弱秦国，不吝惜珍奇的器物、贵重的财宝和肥美的土地，用来招请天下贤士，实行合纵，缔约结交，互相联合，结成一体。在这个时候，齐国有孟尝君，赵国有平原君，楚国有春申君，魏国有信陵君。这四君子，个个明智忠信，宽仁爱人，尊重贤士，重用能人，他们结约合纵，拆散连横，聚合起韩、魏、燕、楚、齐、赵、宋、卫、中山等国的众多军队。这时候六国的谋士有宁越、徐尚、苏秦、杜赫这些人给他们谋划，有齐明、周最、陈轸、昭滑、楼缓、翟景、苏厉、乐毅这些人为他们沟通各国的意见，有吴起、孙膑、带佗、倪良、王廖、田忌、廉颇、赵奢这些人为他们统率军队。他们曾经凭着十倍于秦国的土地，用上百万的军队，去攻打函谷关进攻秦国。秦国敞开关门把敌人放进来打，九国的军队却退缩奔逃，不敢前进。秦国没有损失一枝箭、丢一个箭头的耗费，各国诸侯就已经疲困不堪了。因此合纵离散了，盟约解除了，争着割让地盘以侍奉秦国。这就使得秦国有充足的力量利用各国疲困的机会去制服他们，追逐败逃之敌，杀人上百万，尸体遍地；鲜血流成河，可以漂起盾牌。秦国乘着有利的形势，控制了天下，切割诸侯土地，使得强国请求归服，弱国入秦朝拜。王位传到孝文王、庄襄王，他们在位的时间很短，国家没有什么大事。
等到秦王，继承六代先王遗留下来的功业，挥舞长鞭，驾御天下，兼并了西周、东周，消灭了各国诸侯，登上帝位，控制了天地四方，手执鞭杖来抽打天下，威震四海。向南取得了百越地区，设置了桂林、象郡，百越的君主低着头，用绳子系着脖子，把生命交给秦国的下级官吏。又派蒙恬到北方修筑长城，守卫边界，使匈奴退却七百多里，胡人不敢南下牧马，武士不敢挽弓复仇。于是废除古代帝王的原则，烧毁诸子百家的典籍，以此来愚弄百姓。毁坏坚固的名城，杀死豪杰俊士，没收全国的兵器，集中在咸阳，把这些兵器销毁，熔铸成钟鐻，又做了十二个铜人，以此来削弱百姓的反抗力量。然后劈开华山作为城垣，利用黄河作为渡口，据守高达亿丈的城他，下临深不可测的溪流，作为固守的凭借。优秀的将领、强劲的弓弩手把守要害的地方，忠实的大臣、精锐的士卒摆开锋利的武器，谁也无可奈何，天下得到安定。秦王的心里，自以为关中地方坚固，就像有千里铜墙铁壁，子孙可以世代做帝王，功业流传千秋万代。
秦王已经死了，余威还远震四夷。陈涉是用破瓮做窗户、用绳捆门轴的穷人家子弟，为人庸耕的农民，而又是流徙之徒，才能赶不上一个中等人，并不具有仲尼、墨翟那样的贤智，陶朱、猗顿那样的财富，插足士卒行列之间，崛起田野之中，率领疲惫散乱的士卒，带着几百个徒众，转身攻秦。砍断树木作为兵器，高举竹竿当作旗帜，天下百姓响应陈涉，云集在一起，携带着粮食，如影相随，山东豪杰俊士同时并起，消灭了秦国。
再说秦国并不弱小，雍州的领土，殽山、函谷夫的险固，还是和从前一样。陈涉的地位，并不比齐、楚、燕、赵、韩、魏、宋、卫、中山的君主尊贵；锄櫌戟柄，并不比钩戟长矛锋利；被遣送远方戍守的一群人，并不能与九国的军队相抗衡；深谋远虑，行军用兵的方法，比不上过去的谋士。然而成败情况大不相同，所建立的功业大小截然相反。如果拿山东各诸侯国与陈涉比较长短大小，衡量权势和力量，则是不能相提并论的。秦凭借小小的一块领土，一千辆兵车的力量，招致八州诸侯国，使与自己地位同等的诸侯来秦朝见，（这种情况）已有一百多年。然后把天地四方当成自己的家私，用殽山、函谷关作为宫垣，（但是）一人发难，宗庙全部毁灭，生命死在别人手中，被天下人笑话，这是为什么呢？是因为不施行仁义，进退攻守的形势发生了变化的缘故。
秦国统一了四海之内，兼并了各国诸侯，南面称帝，来抚养海内百姓，天下之士闻风倾服，如此局面是什么', '[{"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3d8e8f18b220af4bf4c", "shortContent": "秦始皇的历史功绩最重要的是统一六国与其统一全国后所建立的一系列制度。秦灭六国是一个逐步的过程，应该是从商鞅帮着秦孝公变法强国的时候开始，中间经过惠文王、秦武王、秦昭王、孝文王、庄襄王，不断向东方蚕食、扩张，到秦始皇的时候，就已经是水到渠成了。用一个形容词说，就是“摧枯拉朽”、“风卷残云”。秦始皇（当时还称“秦王”）十七年（前230年），灭韩；十九年灭赵；二十二年灭魏；二十三年灭楚；二十五年灭燕；二...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1525197249, '5ae8391e9f545400401f8d60', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637446, '史记 · 十二本纪 · 项羽本纪', NULL, 51, 139, 0, 2, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E9%A1%B9%E7%BE%BD%E6%9C%AC%E7%BA%AA/2115064?fr=aladdin', '', '项籍者，下相人也，字羽。初起时，年二十四。其季父项梁，梁父即楚将项燕，为秦将王翦所戮者也。项氏世世为楚将，封于项，故姓项氏。
项籍少时，学书不成，去，学剑，又不成。项梁怒之。籍曰：「书足以记名姓而已。剑一人敌，不足学，学万人敌！」于是项梁乃教籍兵法，籍大喜，略知其意，又不肯竟学。项梁尝有栎阳逮，乃请蕲狱掾曹咎书抵栎阳狱掾司马欣，以故事得已。项梁杀人，与籍避仇于吴中。吴中贤士大夫皆出项梁下。每吴中有大繇役及丧，项梁常为主办，阴以兵法部勒宾客及子弟，以是知其能。秦始皇帝游会稽，渡浙江，梁与籍俱观。籍曰：「彼可取而代也。」梁掩其口，曰：「毋妄言，族矣！」梁以此奇籍。籍长八尺馀，力能扛鼎，才气过人，虽吴中子弟皆已惮籍矣。
秦二世元年七月，陈涉等起大泽中。其九月，会稽守通谓梁曰：「江西皆反，此亦天亡秦之时也。吾闻先即制人，后则为人所制。吾欲发兵，使公及桓楚将。」是时桓楚亡在泽中。梁曰：「桓楚亡，人莫知其处，独籍知之耳。」梁乃出，诫籍持剑居外待。梁复入，与守坐，曰：「请召籍，使受命召桓楚。」守曰：「诺。」梁召籍入。须臾，梁眴籍曰：「可行矣！」于是籍遂拔剑斩守头。项梁持守头，佩其印绶。门下大惊，扰乱，籍所击杀数十百人。一府中皆慑伏，莫敢起。梁乃召故所知豪吏，谕以所为起大事，遂举吴中兵。使人收下县，得精兵八千人。梁部署吴中豪杰为校尉、候、司马。有一人不得用，自言于梁。梁曰：「前时某丧使公主某事，不能办，以此不任用公。」众乃皆伏。于是梁为会稽守，籍为裨将，徇下县。
广陵人召平于是为陈王徇广陵，未能下。闻陈王败走，秦兵又且至，乃渡江矫陈王命，拜梁为楚王上柱国。曰：「江东已定，急引兵西击秦。」项梁乃以八千人渡江而西。闻陈婴已下东阳，使使欲与连和俱西。陈婴者，故东阳令史，居县中，素信谨，称为长者。东阳少年杀其令，相聚数千人，欲置长，无适用，乃请陈婴。婴谢不能，遂彊立婴为长，县中从者得二万人。少年欲立婴便为王，异军苍头特起。陈婴母谓婴曰：「自我为汝家妇，未尝闻汝先古之有贵者。今暴得大名，不祥。不如有所属，事成犹得封侯，事败易以亡，非世所指名也。」婴乃不敢为王。谓其军吏曰：「项氏世世将家，有名于楚。今欲举大事，将非其人，不可。我倚名族，亡秦必矣。」于是众从其言，以兵属项梁。项梁渡淮，黥布、蒲将军亦以兵属焉。凡六七万人，军下邳。
当是时，秦嘉已立景驹为楚王，军彭城东，欲距项梁。项梁谓军吏曰：「陈王先首事，战不利，未闻所在。今秦嘉倍陈王而立景驹，逆无道。」乃进兵击秦嘉。秦嘉军败走，追之至胡陵。嘉还战一日，嘉死，军降。景驹走死梁地。项梁已并秦嘉军，军胡陵，将引军而西。章邯军至栗，项梁使别将朱鸡石、馀樊君与战。馀樊君死。朱鸡石军败，亡走胡陵。项梁乃引兵入薛，诛鸡石。项梁前使项羽别攻襄城，襄城坚守不下。已拔，皆坑之。还报项梁。项梁闻陈王定死，召诸别将会薛计事。此时沛公亦起沛，往焉。
居鄛人范增，年七十，素居家，好奇计，往说项梁曰：「陈胜败固当。夫秦灭六国，楚最无罪。自怀王入秦不反，楚人怜之至今，故楚南公曰『楚虽三户，亡秦必楚』也。今陈胜首事，不立楚后而自立，其势不长。今君起江东，楚蜂午之将皆争附君者，以君世世楚将，为能复立楚之后也。」于是项梁然其言，乃求楚怀王孙心民间，为人牧羊，立以为楚怀王，从民所望也。陈婴为楚上柱国，封五县，与怀王都盱台。项梁自号为武信君。
居数月，引兵攻亢父，与齐田荣、司马龙且军救东阿，大破秦军于东阿。田荣即引兵归，逐其王假。假亡走楚。假相田角亡走赵。角弟田闲故齐将，居赵不敢归。田荣立田儋子市为齐王。项梁已破东阿下军，遂追秦军。数使使趣齐兵，欲与俱西。田荣曰：「楚杀田假，赵杀田角、田闲，乃发兵。」项梁曰：「田假为与国之王，穷来从我，不忍杀之。」赵亦不杀田角、田闲以市于齐。齐遂不肯发兵助楚。项梁使沛公及项羽别攻城阳，屠之。西破秦军濮阳东，秦兵收入濮阳。沛公、项羽乃攻定陶。定陶未下，去，西略地至雍丘，大破秦军，斩李由。还攻外黄，外黄未下。
项梁起东阿，西，（北）［比］至定陶，再破秦军，项羽等又斩李由，益轻秦，有骄色。宋义乃谏项梁曰：「战胜而将骄卒惰者败。今卒少惰矣，秦兵日益，臣为君畏之。」项梁弗听。乃使宋义使于齐。道遇齐使者高陵君显，曰：「公将见武信君乎？」曰：「然。」曰：「臣论武信君军必败。公徐行即免死，疾行则及祸。」秦果悉起兵益章邯，击楚军，大破之定陶，项梁死。沛公、项羽去外黄攻陈留，陈留坚守不能下。沛公、项羽相与谋曰：「今项梁军破，士卒恐。」乃与吕臣军俱引兵而东。吕臣军彭城东，项羽军彭城西，沛公军砀。
章邯已破项梁军，则以为楚地兵不足忧，乃渡河击赵，大破之。当此时，赵歇为王，陈馀为将，张耳为相，皆走入钜鹿城。章邯令王离、涉闲围钜鹿，章邯军其南，筑甬道而输之粟。陈馀为将，将卒数万人而军钜鹿之北，此所谓河北之军也。
楚兵已破于定陶，怀王恐，从盱台之彭城，并项羽、吕臣军自将之。以吕臣为司徒，以其父吕青为令尹。以沛公为砀郡长，封为武安侯，将砀郡兵。
初，宋义所遇齐使者高陵君显在楚军，见楚王曰：「宋义论武信君之军必败，居数日，军果败。兵未战而先见败徵，此可谓知兵矣。」王召宋义与计事而大说之，因置以为上将军，项羽为鲁公，为次将，范增为末将，救赵。诸别将皆属宋义，号为卿子冠军。行至安阳，留四十六日不进。项羽曰：「吾闻秦军围赵王钜鹿，疾引兵渡河，楚击其外，赵应其内，破秦军必矣。」宋义曰：「不然。夫搏牛之虻不可以破虮虱。今秦攻赵，战胜则兵罢，我承其敝；不胜，则我引兵鼓行而西，必举秦矣。故不如先斗秦赵。夫被坚执锐，义不如公；坐而运策，公不如义。」因下令军中曰：「猛如虎，很如羊，贪如狼，彊不可使者，皆斩之。」乃遣其子宋襄相齐，身送之至无盐，饮酒高会。天寒大雨，士卒冻饥。项羽曰：「将戮力而攻秦，久留不行。今岁饥民贫，士卒食芋菽，军无见粮，乃饮酒高会，不引兵渡河因赵食，与赵并力攻秦，乃曰『承其敝』。夫以秦之彊，攻新造之赵，其势必举赵。赵举而秦彊，何敝之承！且国兵新破，王坐不安席，扫境内而专属于将军，国家安危，在此一举。今不恤士卒而徇其私，非社稷之臣。」项羽晨朝上将军宋义，即其帐中斩宋义头，出令军中曰：「宋义与齐谋反楚，楚王阴令羽诛之。」当是时，诸将皆慑服，莫敢枝梧。皆曰：「首立楚者，将军家也。今将军诛乱。」乃相与共立羽为假上将军。使人追宋义子，及之齐，杀之。使桓楚报命于怀王。怀王因使项羽为上将军，当阳君、蒲将军皆属项羽。
项羽已杀卿子冠军，威震楚国，名闻诸侯。乃遣当阳君、蒲将军将卒二万渡河，救钜鹿。战少利，陈馀复请兵。项羽乃悉引兵渡河，皆沈船，破釜甑，烧庐舍，持三日粮，以示士卒必死，无一还心。于是至则围王离，与秦军遇，九战，绝其甬道，大破之，杀苏角，虏王离。涉闲不降楚，自烧杀。当是时，楚兵冠诸侯。诸侯军救钜鹿下者十馀壁，莫敢纵兵。及楚击秦，诸将皆从壁上观。楚战士无不一以当十，楚兵呼声动天，诸侯军无不人人惴恐。于是已破秦军，项羽召见诸侯将，入辕门，无不膝行而前，莫敢仰视。项羽由是始为诸侯上将军，诸侯皆属焉。
章邯军棘原，项羽军漳南，相持未战。秦军数却，二世使人让章邯。章邯恐，使长史欣请事。至咸阳，留司马门三日，赵高不见，有不信之心。长史欣恐，还走其军，不敢出故道，赵高果使人追之，不及。欣至军，报曰：「赵高用事于中，下无可为者。今战能胜，高必疾妒吾功；战不能胜，不免于死。愿将军孰计之。」陈馀亦遗章邯书曰：「白起为秦将，南征鄢郢，北坑马服，攻城略地，不可胜计，而竟赐死。蒙恬为秦将，北逐戎人，开榆中地数千里，竟斩阳周。何者？功多，秦不能尽封，因以法诛之。今将军为秦将三岁矣，所亡失以十万数，而诸侯并起滋益多。彼赵高素谀日久，今事急，亦恐二世诛之，故欲以法诛将军以塞责，使人更代将军以脱其祸。夫将军居外久，多内却，有功亦诛，无功亦诛。且天之亡秦，无愚智皆知之。今将军内不能直谏，外为亡国将，孤特独立而欲常存，岂不哀哉！将军何不还兵与诸侯为从，约共攻秦，分王其地，南面称孤；此孰与身伏鈇质，妻子为僇乎？」章邯狐疑，阴使候始成使项羽，欲约。约未成，项羽使蒲将军日夜引兵度三户，军漳南，与秦战，再破之。项羽悉引兵击秦军污水上，大破之。
章邯使人见项羽，欲约。项羽召军吏谋曰：「粮少，欲听其约。」军吏皆曰：「善。」项羽乃与期洹水南殷虚上。已盟，章邯见项羽而流涕，为言赵高。项羽乃立章邯为雍王，置楚军中。使长史欣为上将军，将秦军为前行。
到新安。诸侯吏卒异时故繇使屯戍过秦中，秦中吏卒遇之多无状，及秦军降诸侯，诸侯吏卒乘胜多奴虏使之，轻折辱秦吏卒。秦吏卒多窃言曰：「章将军等诈吾属降诸侯，今能入关破秦，大善；即不能，诸侯虏吾属而东，秦必尽诛吾父母妻子。」诸侯微闻其计，以告项羽。项羽乃召黥布、蒲将军计曰：「秦吏卒尚众，其心不服，至关中不听，事必危，不如击杀之，而独与章邯、长史欣、都尉翳入秦。」于是楚军夜击坑秦卒二十馀万人新安城南。
行略定秦地。函谷关有兵守关，不得入。又闻沛公已破咸阳，项羽大怒，使当阳君等击关。项羽遂入，至于戏西。沛公军霸上，未得与项羽相见。沛公左司马曹无伤使人言于项羽曰：「沛公欲王关中，使子婴为相，珍宝尽有之。」项羽大怒，曰：「旦日飨士卒，为击破沛公军！」当是时，项羽兵四十万，在新丰鸿门，沛公兵十万，在霸上。范增说项羽曰：「沛公居山东时，贪于财货，好美姬。今入关，财物无所取，妇女无所幸，此其志不在小。吾令人望其气，皆为龙虎，成五采，此天子气也。急击勿失。」
楚左尹项伯者，项羽季父也，素善留侯张良。张良是时从沛公，项伯乃夜驰之沛公军，私见张良，具告以事，欲呼张良与俱去。曰：「毋从俱死也。」张良曰：「臣为韩王送沛公，沛公今事有急，亡去不义，不可不语。」良乃入，具告沛公。沛公大惊，曰：「为之奈何？」张良曰：「谁为大王为此计者？」曰：「鲰生说我曰『距关，毋内诸侯，秦地可尽王也』。故听之。」良曰：「料大王士卒足以当项王乎？」沛公默然，曰：「固不如也，且为之奈何？」张良曰：「请往谓项伯，言沛公不敢背项王也。」沛公曰：「君安与项伯有故？」张良曰：「秦时与臣游，项伯杀人，臣活之。今事有急，故幸来告良。」沛公曰「孰与君少长？」良曰：「长于臣。」沛公曰「君为我呼入，吾得兄事之。」张良出，要项伯。项伯即入见沛公。沛公奉巵酒为寿，约为婚姻，曰：「吾入关，秋豪不敢有所近，籍吏民，封府库，而待将军。所以遣将守关者，备他盗之出入与非常也。日夜望将军至，岂敢反乎！愿伯具言臣之不敢倍德也。」项伯许诺。谓沛公曰：「旦日不可不蚤自来谢项王。」沛公曰：「诺。」于是项伯复夜去，至军中，具以沛公言报项王。因言曰：「沛公不先破关中，公岂敢入乎？今人有大功而击之，不义也，不如因善遇之。」项王许诺。
沛公旦日从百馀骑来见项王，至鸿门，谢曰：「臣与将军戮力而攻秦，将军战河北，臣战河南，然不自意能先入关破秦，得复见将军于此。今者有小人之言，令将军与臣有郤。」项王曰：「此沛公左司马曹无伤言之；不然，籍何以至此。」项王即日因留沛公与饮。项王、项伯东向坐。亚父南向坐。亚父者，范增也。沛公北向坐，张良西向侍。范增数目项王，举所佩玉玦以示之者三，项王默然不应。范增起，出召项庄，谓曰：「君王为人不忍，若入前为寿，寿毕，请以剑舞，因击沛公于坐，杀之。不者，若属皆且为所虏。」庄则入为寿，寿毕，曰：「君王与沛公饮，军中无以为乐，请以剑舞。」项王曰：「诺。」项庄拔剑起舞，项伯亦拔剑起舞，常以身翼蔽沛公，庄不得击。于是张良至军门，见樊哙。樊哙曰：「今日之事何如？」良曰：「甚急。今者项庄拔剑舞，其意常在沛公也。」哙曰：「此迫矣，臣请入，与之同命。」哙即带剑拥盾入军门。交戟之卫士欲止不内，樊哙侧其盾以撞，卫士仆地，哙遂入，披帷西向立，瞋目视项王，头发上指，目眦尽裂。项王按剑而跽曰：「客何为者？」张良曰：「沛公之参乘樊哙者也。」项王曰：「壮士，赐之巵酒。」则与斗巵酒。哙拜谢，起，立而饮之。项王曰：「赐之彘肩。」则与一生彘肩。樊哙覆其盾于地，加彘肩上，拔剑切而啖之。项王曰：「壮士，能复饮乎？」樊哙曰：「臣死且不避，巵酒安足辞！夫秦王有虎狼之心，杀人如不能举，刑人如恐不胜，天下皆叛之。怀王与诸将约曰『先破秦入咸阳者王之』。今沛公先破秦入咸阳，豪毛不敢有所近，封闭宫室，还军霸上，以待大王来。故遣将守关者，备他盗出入与非常也。劳苦而功高如此，未有封侯之赏，而听细说，欲诛有功之人。此亡秦之续耳，窃为大王不取也。」项王未有以应，曰：「坐。」樊哙从良坐。坐须臾，沛公起如厕，因招樊哙出。
沛公已出，项王使都尉陈平召沛公。沛公曰：「今者出，未辞也，为之奈何？」樊哙曰：「大行不顾细谨，大礼不辞小让。如今人方为刀俎，我为鱼肉，何辞为。」于是遂去。乃令张良留谢。良问曰：「大王来何操？」曰：「我持白璧一双，欲献项王，玉斗一双，欲与亚父，会其怒，不敢献。公为我献之」张良曰：「谨诺。」当是时，项王军在鸿门下，沛公军在霸上，相去四十里。沛公则置车骑，脱身独骑，与樊哙、夏侯婴、靳彊、纪信等四人持剑盾步走，从郦山下，道芷阳间行。沛公谓张良曰：「从此道至吾军，不过二十里耳。度我至军中，公乃入。」沛公已去，闲至军中，张良入谢，曰：「沛公不胜杯杓，不能辞。谨使臣良奉白璧一双，再拜献大王足下；玉斗一双，再拜奉大将军足下。」项王曰：「沛公安在？」良曰：「闻大王有意督过之，脱身独去，已至军矣。」项王则受璧，置之坐上。亚父受玉斗，置之地，拔剑撞而破之，曰：「唉！竖子不足与谋。夺项王天下者，必沛公也，吾属今为之虏矣。」沛公至军，立诛杀曹无伤。
居数日，项羽引兵西屠咸阳，杀秦降王子婴，烧秦宫室，火三月不灭；收其货宝妇女而东。人或说项王曰：「关中阻山河四塞，地肥饶，可都以霸。」项王见秦宫皆以烧残破，又心怀思欲东归，曰：「富贵不归故乡，如衣绣夜行，谁知之者！」说者曰：「人言楚人沐猴而冠耳，果然。」项王闻之，烹说者。
项王使人致命怀王。怀王曰：「如约。」乃尊怀王为义帝。项王欲自王，先王诸将相。谓曰：「天下初发难时，假立诸侯后以伐秦。然身被坚执锐首事，暴露于野三年，灭秦定天下者，皆将相诸君与籍之力也。义帝虽无功，故当分其地而王之。」诸将皆曰：「善。」乃分天下，立诸将为侯王。项王、范增疑沛公之有天下，业已讲解，又恶负约，恐诸侯叛之，乃阴谋曰：「巴、蜀道险，秦之迁人皆居蜀。」乃曰：「巴、蜀亦关中地也。」故立沛公为汉王，王巴、蜀、汉中，都南郑。而三分关中，王秦降将以距塞汉王。项王乃立章邯为雍王，王咸阳以西，都废丘。长史欣者，故为栎阳狱掾，尝有德于项梁；都尉董翳者，本劝章邯降楚。故立司马欣为塞王，王咸阳以东至河，都栎阳；立董翳为翟王，王上郡，都高奴。徙魏王豹为西魏王，王河东，都平阳。瑕丘申阳者，张耳嬖臣也，先下河南（郡），迎楚河上，故立申阳为河南王，都雒阳。韩王成因故都，都阳翟。赵将司马卬定河内，数有功，故立卬为殷王，王河内，都朝歌。徙赵王歇为代王。赵相张耳素贤，又从入关，故立耳为常山王，王赵地，都襄国。当阳君黥布为楚将，常冠军，故立布为九江王，都六。鄱君吴芮率百越佐诸侯，又从入关，故立芮为衡山王，都邾。义帝柱国共敖将兵击南郡，功多，因立敖为临江王，都江陵。徙燕王韩广为辽东王。燕将臧荼从楚救赵，因从入关，故立荼为燕王，都蓟。徙齐王田市为胶东王。齐将田都从共救赵，因从入关，故立都为齐王，都临菑。故秦所灭齐王建孙田安，项羽方渡河救赵，田安下济北数城，引其兵降项羽，故立安为济北王，都博阳。田荣者，数负项梁，又不肯将兵从楚击秦，以故不封。成安君陈馀弃将印去，不从入关，然素闻其贤，有功于赵，闻其在南皮，故因环封三县。番君将梅鋗功多，故封十万户侯。项王自立为西楚霸王，王九郡，都彭城。
汉之元年四月，诸侯罢戏下，各就国。项王出之国，使人徙义帝，曰：「古之帝者地方千里，必居上游。」乃使使徙义帝长沙郴县。趣义帝行，其群臣稍稍背叛之，乃阴令衡山、临江王击杀之江中。韩王成无军功，项王不使之国，与俱至彭城，废以为侯，已又杀之。臧荼之国，因逐韩广之辽东，广弗听，荼击杀广无终，并王其地。
田荣闻项羽徙齐王市胶东，而立齐将田都为齐王，乃大怒，不肯遣齐王之胶东，因以齐反，迎击田都。田都走楚。齐王市畏项王，乃亡之胶东就国。田荣怒，追击杀之即墨。荣因自立为齐王，而西杀击济北王田安，并王三齐。荣与彭越将军印，令反梁地。陈馀阴使张同、夏说说齐王田荣曰：「项羽为天下宰，不平。今尽王故王于丑地，而王其群臣诸将善地，逐其故主赵王，乃北居代，馀以为不可。闻大王起兵，且不听不义，愿大王资馀兵，请以击常山，以复赵王，请以国为捍蔽。」齐王许之，因遣兵之赵。陈馀悉发三县兵，与齐并力击常山，大破之。张耳走归汉。陈馀迎故赵王歇于代，反之赵。赵王因立陈馀为代王。
是时，汉还定三秦。项羽闻汉王皆已并关中，且东，齐、赵叛之：大怒。乃以故吴令郑昌为韩王，以距汉。令萧公角等击彭越。彭越败萧公角等。汉使张良徇韩，乃遗项王书曰：「汉王失职，欲得关中，如约即止，不敢东。」又以齐、梁反书遗项王曰：「齐欲与赵并灭楚。」楚以此故无西意，而北击齐。徵兵九江王布。布称疾不往，使将将数千人行。项王由此怨布也。汉之二年冬，项羽遂北至城阳，田荣亦将兵会战。田荣不胜，走至平原，平原民杀之。遂北烧夷齐城郭室屋，皆坑田荣降卒，系虏其老弱妇女。徇齐至北海，多所残灭。齐人相聚而叛之。于是田荣弟田横收齐亡卒得数万人，反城阳。项王因留，连战未能下。
春，汉王部五诸侯兵，凡五十六万人，东伐楚。项王闻之，即令诸将击齐，而自以精兵三万人南从鲁出胡陵。四月，汉皆已入彭城，收其货宝美人，日置酒高会。项王乃西从萧，晨击汉军而东，至彭城，日中，大破汉军。汉军皆走，相随入谷、泗水，杀汉卒十馀万人。汉卒皆南走山，楚又追击至灵壁东睢水上。汉军却，为楚所挤，多杀，汉卒十馀万人皆入睢水，睢水为之不流。围汉王三匝。于是大风从西北而起，折木发屋，扬沙石，窈冥昼晦，逢迎楚军。楚军大乱，坏散，而汉王乃得与数十骑遁去，欲过沛，收家室而西；楚亦使人追之沛，取汉王家：家皆亡，不与汉王相见。汉王道逢得孝惠、鲁元，乃载行。楚骑追汉王，汉王急，推堕孝惠、鲁元车下，滕公常下收载之。如是者三。曰：「虽急不可以驱，奈何弃之？」于是遂得脱。求太公、吕后不相遇。审食其从太公、吕后闲行，求汉王，反遇楚军。楚军遂与归，报项王，项王常置军中。
是时吕后兄周吕侯为汉将兵居下邑，汉王闲往从之，稍稍收其士卒。至荥阳，诸败军皆会，萧何亦发关中老弱未傅悉诣荥阳，复大振。楚起于彭城，常乘胜逐北，与汉战荥阳南京、索闲，汉败楚，楚以故不能过荥阳而西。
项王之救彭城，追汉王至荥阳，田横亦得收齐，立田荣子广为齐王。汉王之败彭城，诸侯皆复与楚而背汉。汉军荥阳，筑甬道属之河，以取敖仓粟。汉之三年，项王数侵夺汉甬道，汉王食乏，恐，请和，割荥阳以西为汉。
项王欲听之。历阳侯范增曰：「汉易与耳，今释弗取，后必悔之。」项王乃与范增急围荥阳。汉王患之，乃用陈平计闲项王。项王使者来，为太牢具，举欲进之。见使者，详惊愕曰：「吾以为亚父使者，乃反项王使者。」更持去，以恶食食项王使者。使者归报项王，项王乃疑范增与汉有私，稍夺之权。范增大怒，曰：「天下事大定矣，君王自为之。愿赐骸骨归卒伍。」项王许之。行未至彭城，疽发背而死。
汉将纪信说汉王曰：「事已急矣，请为王诳楚为王，王可以闲出。」于是汉王夜出女子荥阳东门被甲二千人，楚兵四面击之。纪信乘黄屋车，傅左纛，曰：「城中食尽，汉王降。」楚军皆呼万岁。汉王亦与数十骑从城西门出，走成皋。项王见纪信，问：「汉王安在？」曰：「汉王已出矣。」项王烧杀纪信。
汉王使御史大夫周苛、枞公、魏豹守荥阳。周苛、枞公谋曰：「反国之王，难与守城。」乃共杀魏豹。楚下荥阳城，生得周苛。项王谓周苛曰：「为我将，我以公为上将军，封三万户。」周苛骂曰：「若不趣降汉，汉今虏若，若非汉敌也。」项王怒，烹周苛，井杀枞公。
汉王之出荥阳，南走宛、叶，得九江王布，行收兵，复入保成皋。汉之四年，项王进兵围成皋。汉王逃，独与滕公出成皋北门，渡河走修武，从张耳、韩信军。诸将稍稍得出成皋，从汉王。楚遂拔成皋，欲西。汉使兵距之巩，令其不得西。
是时，彭越渡河击楚东阿，杀楚将军薛公。项王乃自东击彭越。汉王得淮阴侯兵，欲渡河南。郑忠说汉王，乃止壁河内。使刘贾将兵佐彭越，烧楚积聚。项王东击破之，走彭越。汉王则引兵渡河，复取成皋，军广武，就敖仓食。项王已定东海来，西，与汉俱临广武而军，相守数月。
当此时，彭越数反梁地，绝楚粮食，项王患之。为高俎，置太公其上，告汉王曰：「今不急下，吾烹太公。」汉王曰：「吾与项羽俱北面受命怀王，曰『约为兄弟』，吾翁即若翁，必欲烹而翁，则幸分我一杯羹。」项王怒，欲杀之。项伯曰：「天下事未可知，且为天下者不顾家，虽杀之无益，只益祸耳。」项王从之。
楚汉久相持未决，丁壮苦军旅，老弱罢转漕。项王谓汉王曰：「天下匈匈数岁者，徒以吾两人耳，愿与汉王挑战决雌雄，毋徒苦天下之民父子为也。」汉王笑谢曰：「吾宁斗智，不能斗力。」项王令壮士出挑战。汉有善骑射者楼烦，楚挑战三合，楼烦辄射杀之。项王大怒，乃自被甲持戟挑战。楼烦欲射之，项王瞋目叱之，楼烦目不敢视，手不敢发，遂走还入壁，不敢复出。汉王使人闲问之，乃项王也。汉王大惊。于是项王乃即汉王相与临广武闲而语。汉王数之，项王怒，欲一战。汉王不听，项王伏弩射中汉王。汉王伤，走入成皋。
项王闻淮阴侯已举河北，破齐、赵，且欲击楚，乃使龙且往击之。淮阴侯与战，骑将灌婴击之，大破楚军，杀龙且。韩信因自立为齐王。项王闻龙且军破，则恐，使盱台人武涉往说淮阴侯。淮阴侯弗听。是时，彭越复反，下梁地，绝楚粮。项王乃谓海春侯大司马曹咎等曰：「谨守成皋，则汉欲挑战，慎勿与战，毋令得东而已。我十五日必诛彭越，定梁地，复从将军。」乃东，行击陈留、外黄。
外黄不下。数日，已降，项王怒，悉令男子年十五已上诣城东，欲坑之。外黄令舍人儿年十三，往说项王曰：「彭越彊劫外黄，外黄恐，故且降，待大王。大王至，又皆坑之，百姓岂有归心？从此以东，梁地十馀城皆恐，莫肯下矣。」项王然其言，乃赦外黄当坑者。东至睢阳，闻之皆争下项王。
汉果数挑楚军战，楚军不出。使人辱之，五六日，大司马怒，渡兵汜水。士卒半渡，汉击之，大破楚军，尽得楚国货赂。大司马咎、长史翳、塞王欣皆自刭汜水上。大司马咎者，故蕲狱掾，长史欣亦故栎阳狱吏，两人尝有德于项梁，是以项王信任之。当是时，项王在睢阳，闻海春侯军败，则引兵还。汉军方围钟离眛于荥阳东，项王至，汉军畏楚，尽走险阻。
是时，汉兵盛食多，项王兵罢食绝。汉遣陆贾说项王，请太公，项王弗听。汉王复使侯公往说项王，项王乃与汉约，中分天下，割鸿沟以西者为汉，鸿沟而东者为楚。项王许之，即归汉王父母妻子。军皆呼万岁。汉王乃封侯公为平国君。匿弗肯复见。曰：「此天下辩士，所居倾国，故号为平国君。」项王已约，乃引兵解而东归。
汉欲西归，张良、陈平说曰：「汉有天下太半，而诸侯皆附之。楚兵罢食尽，此天亡楚之时也，不如因其机而遂取之。今释弗击，此所谓『养虎自遗患』也。」汉王听之。汉五年，汉王乃追项王至阳夏南，止军，与淮阴侯韩信、建成侯彭越期会而击楚军。至固陵，而信、越之兵不会。楚击汉军，大破之。汉王复入壁，深堑而自守。谓张子房曰：「诸侯不从约，为之奈何？」对曰：「楚兵且破，信、越未有分地，其不至固宜。君王能与共分天下，今可立致也。即不能，事未可知也。君王能自陈以东傅海，尽与韩信；睢阳以北至谷城，以与彭越：使各自为战，则楚易败也。」汉王曰：「善。」于是乃发使者告韩信、彭越曰：「并力击楚。楚破，自陈以东傅海与齐王，睢阳以北至谷城与彭相国。」使者至，韩信、彭越皆报曰：「请今进兵。」韩信乃从齐往，刘贾军从寿春并行，屠城父，至垓下。大司马周殷叛楚，以舒屠六，举九江兵，随刘贾、彭越皆会垓下，诣项王。
项王军壁垓下，兵少食尽，汉军及诸侯兵围之数重。夜闻汉军四面皆楚歌，项王乃大惊曰：「汉皆已得楚乎？是何楚人之多也！」项王则夜起，饮帐中。有美人名虞，常幸从；骏马名骓，常骑之。于是项王乃悲歌慨，自为诗曰：「力拔山兮气盖世，时不利兮骓不逝。骓不逝兮可奈何，虞兮虞兮柰若何！」歌数阕，美人和之。项王泣数行下，左右皆泣，莫能仰视。
于是项王乃上马骑，麾下壮士骑从者八百馀人，直夜溃围南出，驰走。平明，汉军乃觉之，令骑将灌婴以五千骑追之。项王渡淮，骑能属者百馀人耳。项王至阴陵，迷失道，问一田父，田父绐曰「左」。左，乃陷大泽中。以故汉追及之。项王乃复引兵而东，至东城，乃有二十八骑。汉骑追者数千人。项王自度不得脱。谓其骑曰：「吾起兵至今八岁矣，身七十馀战，所当者破，所击者服，未尝败北，遂霸有天下。然今卒困于此，此天之亡我，非战之罪也。今日固决死，愿为诸君快战，必三胜之，为诸君溃围，斩将，刈旗，令诸君知天亡我，非战之罪也。」乃分其骑以为四队，四向。汉军围之数重。项王谓其骑曰：「吾为公取彼一将。」令四面骑驰下，期山东为三处。于是项王大呼驰下，汉军皆披靡，遂斩汉一将。是时，赤泉侯为骑将，追项王，项王瞋目而叱之，赤泉侯人马俱惊，辟易数里与其骑会为三处。汉军不知项王所在，乃分军为三，复围之。项王乃驰，复斩汉一都尉，杀数十百人，复聚其骑，亡其两骑耳。乃谓其骑曰：「何如？」骑皆伏曰：「如大王言。」
于是项王乃欲东渡乌江。乌江亭长舣船待，谓项王曰：「江东虽小，地方千里，众数十万人，亦足王也。愿大王急渡。今独臣有船，汉军至，无以渡。」项王笑曰：「天之亡我，我何渡为！且籍与江东子弟八千人渡江而西，今无一人还，纵江东父兄怜而王我，我何面目见之？纵彼不言，籍独不愧于心乎？」乃谓亭长曰：「吾知公长者。吾骑此马五岁，所当无敌，尝一日行千里，不忍杀之，以赐公。」乃令骑皆下马步行，持短兵接战。独籍所杀汉军数百人。项王身亦被十馀创。顾见汉骑司马吕马童，曰：「若非吾故人乎？」马童面之，指王翳曰：「此项王也。」项王乃曰：「吾闻汉购我头千金，邑万户，吾为若德。」乃自刎而死。王翳取其头，馀骑相蹂践争项王，相杀者数十人。最其后，郎中骑杨喜，骑司马吕马童，郎中吕胜、杨武各得其一体。五人共会其体，皆是。故分其地为五：封吕马童为中水侯，封王翳为杜衍侯，封杨喜为赤泉侯，封杨武为吴防侯，封吕胜为涅阳侯。
项王已死，楚地皆降汉，独鲁不下。汉乃引天下兵欲屠之，为其守礼义，为主死节，乃持项王头视鲁，鲁父兄乃降。始，楚怀王初封项籍为鲁公，及其死，鲁最后下，故以鲁公礼葬项王谷城。汉王为发哀，泣之而去。
诸项氏枝属，汉王皆不诛。乃封项伯为射阳侯。桃侯、平皋侯、玄武侯皆项氏，赐姓刘。
太史公曰：吾闻之周生曰：「舜目盖重瞳子」，又闻项羽亦重瞳子。羽岂其苗裔邪？何兴之暴也？夫秦失其政，陈涉首难，豪杰蜂起，相与并争，不可胜数。然羽非有尺寸，乘势起陇亩之中，三年，遂将五诸侯灭秦，分裂天下而封王侯，政由羽出，号为霸王，位虽不终，近古以来未尝有也。及羽背关怀楚，放逐义帝而自立，怨王侯叛己，难矣。自矜功伐，奋其私智而不师古，谓霸王之业，欲以力征经营天下，五年，卒亡其国，身死东城，尚不觉寤，而不自责，过矣。乃引「天亡我，非用兵之罪也」，岂不谬哉！
【索隐述赞】亡秦鹿走，伪楚狐鸣。云郁沛谷，剑挺吴城。勋开鲁甸，势合砀兵。卿子无罪，亚父推诚。始救赵歇，终诛子婴。违约王汉，背关怀楚。常迁上游，臣迫故主。灵壁大振，成皋久拒。战非无功，天实不与。嗟彼盖代，卒为凶竖。', '《项羽本纪》是西汉史学家司马迁创作的一篇文言文，出于《史记》中第七卷，是关于楚霸王项羽的本纪，它记录了秦末项羽光辉壮烈的一生。', '', '项籍是下相人，字羽。开始起兵时二十四岁。他的叔父是项梁，项梁的父亲就是楚将项燕，被秦将王翦所杀的那个人。项氏世代为楚将，封于项，所以姓项氏。
项籍小时候，学习认字写字，没有学成。放弃了学字，改学击剑，又没有学成。项梁很生他的气。项籍说：“字只不过用来记记姓名而已。剑也只能抵敌一人，不值得学，要学能抵抗万人的。”于是项梁就教项籍兵法，项籍非常高兴，粗略地知道了兵法大意，但又不肯认真学完。项梁曾因栎阳罪案受到牵连，就请蕲县狱掾曹咎写信给栎阳狱掾司马欣，因此事情得到了结。项梁杀了人，和项籍到吴中躲避仇家。吴中有才能的士大夫都比不上项梁。每当吴中有大规模的繇役和丧葬，项梁常常主持办理，暗中用兵法部署调度宾客和子弟，因此了解了每个人的能力。秦始皇帝巡游会稽，渡过浙江，项梁和项籍一同去观看。项籍说：“那个皇帝，我可以取而代之。”项梁捂住他的嘴，说：“不许胡说八道，当心全族要杀头啊！”项梁因此觉得项籍不同于一般人。项籍身高八尺有余，力能举鼎，才气过人，吴中子弟都已经敬畏他了。
秦二世元年七月，陈涉等人在大泽乡起义。这一年九月，会稽郡守殷通对项梁说“江西都造反了，这也是上天灭亡秦朝的时候。我听说先发则能制人，后发则为人所制。我想发兵，派你和桓楚带领。”当时桓楚逃亡在湖泽之中。项梁说：“桓楚亡匿在外，人们不知道他的下落，只有项籍知道。”项梁走出来，吩咐项籍持剑在外面等候。项梁又走进去，与郡守一块儿坐着。项梁说：“请允许我叫项籍进来，让他接受命令召回桓楚。”郡守说：“好吧。”项梁招呼项籍进来。不一会儿，项梁使眼色给项籍说：“可以行动了！”于是项籍拔出剑来砍掉了郡守的脑袋。项梁拿着郡守的脑袋，身上系着郡守的官印。郡守的侍从护卫大为惊慌，一片混乱，项籍杀死了百十来人。全府中的人都慌惧畏服，没有人敢动手反抗。项梁就召集昔日所熟悉的有胆识的府吏，把所要做的起兵反秦这件事情向大家讲清楚，于是征集吴中士卒起义。派人搜罗下属各县丁壮，得到精兵八千人。项梁安排吴中豪杰为校尉、候、司马。有一人没有得到任用，自己去向项梁申述。项梁说：“前些时候有一丧事，让你主办一件事，你不能办，因此不任用你。”于是大家都很佩服项梁。项梁为会稽郡守，项籍为裨将。镇抚下属县邑。
广陵人召平这时为陈王略地广陵，没有降服。听说陈王战败逃走，秦兵又将要到达，就渡江假托陈王的命令，拜项梁为楚王的上柱国。召平说：“江东已经平定，赶快引兵西进攻打秦军。”项梁就以八千人渡江向西进发。他听说陈婴已经攻下东阳，便派遣使者，想要与陈婴联合西进。陈婴这个人，原来是东阳令史，在县里一向诚实谨慎，人们称之为忠厚长者。东阳的青年杀死了他们的县令，聚合了几千人，想要选置一个首领，没有找到可用的人，就请陈婴来担任。陈婴推辞说不能胜任，大家就强行推立他做首领，县中随从的有二万人。青年们打算推举陈婴就便称王，士兵为了同其他各路军队相区别，头上裹以青巾，表示异军突起。陈婴的母亲对陈婴说：“自从我做了你家的媳妇，未曾听说你的前辈有过高官贵爵。现在突然得到很大的名声，不是好兆头。不如有所归属，事情成功了，犹能得到封侯，事情失败了，也容易逃脱，因为不是社会上指名道姓的人。”因此陈婴不敢为王。对他的军吏说：“项家世代为将，有名于楚。现在想要干成大事，将帅不得其人不行。我们依附名门大族，一定能使秦朝灭亡。”于是大家听从他的话，把军队归属项梁。项梁渡过淮水，黥布、蒲将军也率军归附。项梁共有六七万人，驻扎在下邳。
这时，秦嘉已立景驹为楚王，驻扎彭城东面，想要抵挡项梁。项梁对军吏说：“陈王首先起事，作战不利，不知道下落。现在秦嘉背叛陈王而立景驹，大逆不道。”项梁就进兵攻打秦嘉。秦嘉的军队败逃，项梁追到胡陵。秦嘉回军打了一天，秦嘉阵亡，士卒投降。景驹逃走，死在梁地。项梁已经合并了秦嘉的军队，驻扎在胡陵，将要引军西进。章邯的军队到达栗县，项梁派别将朱鸡石、余樊君和他交战。余樊君战死，朱鸡石军败，逃跑到钥陵。项梁便带兵进入薛县，杀了朱鸡石。项梁在这之前派项羽另率一军攻打襄城，襄城坚守不降。攻克以后，全部坑杀了守城军民，回来报告项梁。项梁听说陈王确实死了，召集各路将领会合到薛县商讨大事。这时沛公也起兵于沛，前往薛县。
居鄛人范增，七十岁了，一向住在家里，喜欢奇策妙计。他去游说项梁说：“陈胜失败本来是应该的。秦灭六国，楚国最没有过错。自从楚怀王入秦不返，楚人至今还想念他。所以楚南公说‘楚虽三户，亡秦必楚’。如今陈胜首先起事，没有立楚国的后裔而自立为王，他的局面不会长久。现在你起兵江东，楚地将领有如群蜂纵横，都争先恐后地归附你的缘故，是因为项家世代为楚将，能够再立楚国的后裔。”项梁认为他说的对，就在民间寻访到了楚怀王的孙子心，他在给人放羊，项梁立他为楚怀王，顺从人民的愿望。陈婴为楚上柱国，封地有五个县，和楚怀王一起，建都盱台。项梁自称为武信君。
过了几个月，项梁带兵攻打亢父，与齐田荣、司马龙且的军队一起援救东阿，在东阿大败秦军。田荣率军回到旧地，赶跑了齐王田假。田假逃到楚国。田假的相国田角逃到赵国。田角的弟弟田间原来是齐国的将领，留在赵国不敢回去。田荣立了田儋的儿子田市为齐王。项梁已经打垮了东阿方面的秦军，就（乘胜）追击。屡次派遣使者催促齐国军队，打算与它联兵西进。田荣说：“楚国杀了田假，赵国杀了田角、田间，我就出兵。”项梁说：“田假是楚国友好国家的国王，走投无路才来依附我，不忍心杀他。”赵国也不杀田角、田间作为与齐交换的条件。于是齐国不肯发兵帮助楚国。项梁派沛公和项羽另率一支军队攻打城阳，屠毁了县城。向西在濮阳东面击破了秦军，秦军收兵进入濮阳。沛公、项羽就攻打定陶。没有攻下定陶，率军离去，西进略地，到达雍丘，大破秦军，杀了李由。回军攻打外黄，没有攻下来。
项梁自东阿出发，向西进军，等到到达定陶，又一次打败秦军，项羽等又杀了李由，因此，项梁越来越轻视秦军，面有骄色。宋义就劝告项梁说：“打了胜仗而将领骄傲、士卒懈怠的就要失败。现在士卒稍有懈怠，秦兵日益增多，我替你担心。”项梁不听劝告。就派宋义出使齐国。路上遇到齐国使者高陵君显，问他：“你将要去见武信君吗？”回答说：“是的。”宋义说：“我断定武信君的军队一定失败。你慢走就可以免死，快走就要遭殃。”秦果然发动全部兵力增援章邯，攻打楚军，大破楚军于定陶，项梁战死。沛公、项羽离开外黄攻打陈留，陈留坚兵固守，不能攻下。沛公、项羽互相商量说：“如今项梁的军队垮了，士卒恐惧。”于是就领兵同吕臣的军队一起向东进发。吕臣驻扎在彭城东面，项羽驻扎在彭城西面，沛公驻扎在砀。
章邯已经打垮了项梁的军队，以为楚地的敌人不用担心了，就渡过黄河攻打赵地，大破赵军。这个时候，赵歇为赵王，陈余为将，张耳为相，都跑进了巨鹿城。章邯命令王离、涉间围攻巨鹿，章邯驻扎在巨鹿南面，修筑甬道输送粮食。陈余作为将领，统率士卒数万人驻扎在巨鹿的北面，这就是所说的河北之军。
楚军在定陶打了败仗，楚怀王很恐惧，从盱台前往彭城，合并了项羽、吕臣的军队亲自统率。以吕臣为司徒，用他的父亲叶青为令尹。以沛公为砀郡长，封为武安侯，统率砀郡的军队。
以前宋义所遇到的齐国使者高陵君显还在楚国的军队里，他见到楚怀王说：“宋义断定武信君的军队一定失败，过了几天，他的军队果然失败了。军队没有开战而先看到了失败的征兆，这可说是懂得军事了。”楚怀王召见宋义，和他商量事情，大为高兴，因此委任为上将军，项羽为鲁公，担任次将，范增为末将，去援救赵国。各路别将都统属于宋义，宋义号为卿子冠军。
走到安阳，停留四十六天不前进。项羽说：“我听说秦军把赵王围在巨鹿，赶快带兵渡河，楚军从外面攻打，赵军在内响应，一定能打垮秦军。”宋义说：“不是的。咬牛的牛虻不能伤害虱子，现在秦军攻打赵军，打胜了则兵疲力尽，我们乘秦军疲惫（发动进攻）；打不胜，我们就率领军队鸣鼓西进，一定打垮秦军。所以不如先让秦、赵相斗。身披甲胄，手执利器，冲锋陷阵，宋义不如你；坐下来运筹划策，你不如宋义。”因此向军中下令说：“凶猛如虎，狠戾如羊，贪婪如狼，倔强不听指挥的人，一律斩首。”宋义又派遣他的儿子宋襄去辅助齐国，亲自送他到无盐，摆酒设筵，大会宾客。（当时，）天寒大雨，士卒冻饿交加。项羽说：“本来打算并力攻秦，却长期停留不进。现在年荒岁饥，人民贫困，士卒只吃半升豆子，（食不果腹，）军中没有存粮，宋义却还设酒宴，会宾客，不率领军队渡河就地取用赵国的粮食，而说什么‘等待秦军疲惫’。以秦那样强大的兵力，进攻新建立的赵国，形势发展的结果必定是秦军打垮赵国的军队。赵国的军队被打垮了，而秦军更加强大，还有什么疲惫的机会可乘！而且楚军最近被打败，国王坐不安席，把国内的所有兵力都集中起来统属于上将军，国家安危，在此一举。如今不体恤士卒，而徇情营私，不是与国家同休共戚之臣。”项羽早晨参见上将军宋义，就在他的帐幕中割下了宋义的脑袋，出来发令军中说：“宋义和齐国阴谋反楚，楚王秘密命令我杀死他。”这时，将领们都恐惧屈服，没有敢抗拒的。都说：“创建楚国的，是将军一家。现在又是将军处死了叛乱的人。”将领们就共同推立项羽为假上将军。派人去追宋义的儿子，在齐国赶上了，杀死了他。项羽派桓楚向楚怀王报告。楚怀王就让项羽做上将军，当阳君、蒲将军都归项羽节制。
项羽已经杀了卿子冠军，威震楚国，名闻诸侯，他便派遣当阳君、蒲将军带领两万士卒渡河，援救巨鹿。战事稍有胜利，陈余又向项羽请求救兵。项羽就率领全军渡河，凿沉船只，砸破炊具，烧毁营舍，携带三天口粮，用以表示士卒拼死决战，没有一个有活着回来的打算。军队一到就围困了王离，与秦军遭遇，打了九仗，截断了秦军的甬道，大破秦军。杀了苏角，俘虏了王离。涉间不向楚军投降，自焚而死。诸侯将领都在营垒上观战。楚军战士无不以一当十，楚兵喊声震天，诸侯军人人胆战心惊。已经打垮了秦军，项羽召见各诸侯将领，他们进入辕门，无不膝行而前，不敢抬头仰视。项羽从此成为诸侯军的上将军，各路诸侯隶属于他。
章邯驻扎在棘原，项羽驻扎在漳水南岸，两军相持，没有交战。秦军多次退却，二世派人责让章邯。章邯恐惧，派长史司马欣去请示。到了咸阳，留在司马门三天，赵高不接见，有不信任之意。长史司马欣心里害怕，急忙逃回军中。（他怕有人来追杀，）没有敢走原路，赵高果然派人追赶他，没有追上。司马欣到了军中，向章邯报告说：“赵高居中用事，下面的人不可能有所作为。如今仗能打赢，赵高必定嫉妒我们的功劳；仗打不赢，免不了被处死。希望将军深恩熟虑。”陈余也送给章邯一封信说：“白起为秦将，向南攻拔鄢、郢，向北坑杀马服，攻城咯地，不可胜数，而最后竟然赐死。蒙恬为秦将，北逐匈奴，开辟榆中几千里的地域，最终竟然斩于阳周。为什么呢？功劳太多，秦不能按功行封，因此（罗织罪名，）用法来杀死他们。现在将军为秦将三年了，所损失的士卒以十万计，而诸侯军同时并起，越来越多。那个赵高一向谄谀，为时已久，眼下形势危急，也怕二世杀他，所以打算用法杀死将军，借以推卸责任，别外派人替代将军，以此来摆脱祸患。将军在外时日已久，朝廷中很多人与你有隔阂，有功也是被杀，无功也是被杀。况且天要亡秦，无论是愚笨的人还是聪明的人全都知道。如今将军在内不能直言规谏，在外为即将灭亡的国家的将领，子身孤立而想长期存在，岂不可哀！将军何不倒戈与各路诸侯联合，签订和约，共同攻秦，割地为王，南向而坐，称孤道寡；这同自己伏砧受戮，妻子被杀，哪个比较好一些呢？”章邯犹豫不决，暗中派军候始成到项羽营中，想要签署和约。和约没有商妥，项羽让蒲将军昼夜领兵渡过三户津，扎营漳水南岸，与秦军交战，又一次打败了秦军。项羽率领全军士卒在汗水上攻击秦军，把秦军打得大败。
章邯派人去见项羽，打算订立和约。项羽召集军吏商量说：“军中粮少，想允许他签订和约。”军吏都说：“好。”项羽就与章邯订期在洹水南岸殷墟相见。已经缔结了盟约，章邯见到项羽，涕泪交下，向项羽诉说赵高的种种行径。项羽就立章邯为雍王，安置在楚军营中。使长史司马欣为上将军，率领秦军为先行部队。
到达了新安。诸侯军的官兵以前曾因服徭役、屯戍边地路过秦中，秦中官兵对他们多有凌辱。等到秦军投降了诸侯军，诸侯军的官兵乘战争胜利的机会，像对待奴隶和俘虏一样地驱使他们，随便折磨侮辱秦军官兵。秦军官兵多在私下议论说：“章将军等欺骗我们投降诸侯军。如今能够入关破秦，（当然）很好；如果不能，诸侯军俘虏我们东去；秦势必把我们的父母妻子全部处死。”诸侯军的将领们暗中听到了他们的打算，报告了项羽。项羽就找来黥布、蒲将军商量说：“秦军官兵还很多，他们心里不服，到了关中不听从命令，事情必然岌岌可危，不如杀掉他们，而只与章邯、长史司马欣、都尉董翳一起入秦。”于是楚军夜间把秦军士卒二十多万人处死掩埋在新安城南。
项羽将要攻取秦关中地带。函谷关有兵把守，不能进去。又听说沛公已经攻破咸阳，项羽大怒，派当阳君等扣关。项羽便进入了函谷关，到达戏水西岸。沛公驻军霸上，没有能够和项羽相见。沛公左司马曹无伤派人对项羽说：“沛公想称王关中，使子婴为相，占有了全部珍宝。”项羽怒气冲天他说：“明天早晨饱餐士卒，将击溃沛公的军队！”这时，项羽有兵四十万，驻扎在新丰鸿门，沛公有兵十万，驻扎在霸上。范增劝告项羽说：“沛公在山东时，贪财好货，喜爱美女。现在进了关，不收财物，不亲近妇女，由此看来，他的志向不小。我叫人观望他上空的云气，都呈龙虎形状，五颜六色，这是天子之气。赶快进击，不要失掉机会。”
楚国左尹项伯这个人，是项羽的叔父，一向和留侯张良相友好。张良这时跟随着沛公，项伯就夜间骑马跑到沛公军营，私下见到张良，讲述了事情的经过，打算叫张良和他一起离去。他说：“不要跟他们一起死掉。”张良说：“我为韩王护送沛公，现在沛公的事情发生了危急，逃走是不道义的，不能不说一声。”张良就走了进去，把情况全部告诉了沛公。沛公大吃一惊，说：“怎么办呢？”张良说：“谁给大王出的这个主意？”沛公说：“一个小子劝我说‘守住函谷关，不要让诸侯军进来，秦地可以全部占为己有，在这里称王’。我听信了他的话。”张良说：“估计大王的军力足以抵挡项王吗？”沛公默然不语，（过了一会）说：“军力当然不如项羽，又该怎么办呢？”张良说：“请让我去告诉项伯，说沛公不敢背叛项王。”沛公说：“你怎么与项伯有交情？”张良说：“秦未灭六国时，项伯和我交游，他杀了人，我救了他。现在事有危急，幸亏他来告诉我。”沛公说：“项伯与你相比，谁年纪大？谁年纪小？”张良说：“他比我大。”沛公说：“你替我叫他进来，我要对他兄长相待。”张良走出来，邀请项伯。项伯就进去见沛公。沛公向项伯举杯敬酒，约为儿女亲家。沛公说：“我入了关，丝毫利益不敢有所接近，造册登记吏民，封存府库，等待将军。所以遣将守关，是为了防备别的盗贼出入和意外事件。我日日夜夜盼望将军到来，哪里敢反叛！请伯兄向将军详细说明我是不敢忘恩负义的。”项伯答应了。对沛公说：“明天早晨不可不早来向项王道歉。”沛公说：“是的。”于是项伯又当夜离去，回到军中，把沛公的话原原本本报告了项王。随即向项羽说：“沛公不先攻破关中，你难道敢进来吗？如今人家立有大功而去攻打他，是不道义的，不如借他来请罪的机会好好对待他。”项王答应了。
次日早晨，沛公带着一百多名骑兵来见项王，到了鸿门，向项羽谢罪说：“我和将军并力攻秦，将军在河北作战，我在河南作战，然而我自己也没有想到先入关攻破秦地，能在这里又见到将军。现在有小人之言，使将军和我有了隔阂。”项王说：“这是你沛公左司马曹无伤说的，不然，我何至于如此。”项王当天就留沛公一同饮酒。项王、项伯面朝东坐，亚父面朝南坐。亚父就是范增。沛公面朝北坐，张良面朝西陪坐。范增向项王多次使眼色，再三举起佩带的玉玦向项王示意，项王默然不应。范增起身出去找来项庄，对他说：“君王为人不狠，你进去上前祝酒，祝酒完了，请求舞剑，乘机在座上袭击沛公，杀死他。不然的话，你们这些人都将被他俘虏。”项庄便进去祝酒。祝酒完了说：“君王和沛公饮酒，军中没有什么可供娱乐的，请允许我舞剑助乐。”项王说：“好吧。”项庄拔剑起舞。项伯也拔剑起舞。常常用身体掩蔽沛公，项庄得不到刺杀机会。这时张良来到军门，看见了樊哙。樊哙说：“今天的事情怎么样了？”张良说：“极为危急。此刻项庄正在舞剑，他的用意时时在沛公身上。”樊哙说：“这可紧急了，请让我进去，与沛公同生共死。”樊哙立即带着剑，手拥盾牌，进入军门。交乾守门的卫士打算阻拦，不让他进去，樊哙侧过他的盾牌撞击，卫士倒在地上，樊哙就进入了大帐，揭开帷帐，向西而立，圆睁怒目，看着项王，头发上指，眼眶破裂。项王按剑长跪说；“来客是干什么的？”张良说：“这是沛公的参乘樊哙。”项王说：“壮士！赏赐他一杯酒。”左右就给他一大杯酒。樊哙拜谢后起来，站着一饮而尽。项王说：“赏给他猪腿。”左右就给一只生猪腿。樊哙覆盾于地，把猪腿放在盾上，拔出剑来切肉吃。项王说：“壮士！能再喝酒吗？”樊哙说：“我死都不怕，一杯酒哪里值得推辞！秦王有虎狼之心，杀人唯恐杀不尽，用刑唯恐刑不重，天下人都反叛他。楚怀王和将领们约定说‘先攻破秦地进入咸阳的做关中王’。现在沛公先攻破了秦地进入咸阳，丝毫利益不敢有所接近，封闭宫室，回军霸上，等待大王到来。所以遣将守关，是为了防备别的盗贼和意外事件。如此劳苦功高，没有得到封侯的赏赐，而听信闲言细语，要杀有功的人。这是继承了已经灭亡的秦朝的道路，以我私见，大王这样做是不可取的。”项王无辞以对，只说：“坐。”樊啥在张良旁边坐下来。坐了不一会儿，沛公起来上厕所，乘机招呼樊哙出来。
沛公出去后，项王派都尉陈平去叫沛公回来。沛公（对樊哙）说：“我们现在出去，没有辞行，怎么办呢？”樊哙说：“做大事不顾忌细枝节，行大礼不讲究小谦让。如今人家为刀俎，我们为鱼肉，还辞别什么！”于是就不辞而去。（临走时，）叫张良留下道谢。张良问：“大王来时带了什么？”沛公说：“我带来一只白壁，想献给项王，一只玉斗，想送给亚父，正碰上他们生气，不敢进献。你替我献给他们。”张良说：“遵命。”当时，项王的军队在鸿门，沛公的军队在霸上，相去四十里。沛公丢下车骑，一人骑马脱身而去，樊哙、夏侯婴、靳疆、纪信等四人握剑持盾步行，从郦山下取道芷阳，抄行小路。沛公对张良说：“从这条路到我们军营，不过二十里而已。估计我到了军中，你再进去。”沛公走后，张良估计抄小路已经到达军中，就进去道谢说：“沛公经受不了杯盏，不能亲自来辞行。谨使张良奉上白壁一只，拜献大王；玉斗一只，拜送大将军。”项玉说：“沛公在哪里？”张良说：“听说大王有意责备他，独自脱身而去，已经回到军中了。”项王接过王壁，放在坐席上。亚父接过玉斗，放在地上，拔剑一击而碎，说：“唉！这小子不足以共谋大事。夺取项王天下的，一定是沛公，我们这些人就要被他俘虏了。”沛公回到军中，立刻杀了曹无伤。
过了几天，项羽带兵西进，屠毁咸阳，杀死了秦朝已经投降的国王子婴，焚烧秦朝宫室，大火三个月不灭；搜罗了秦朝的财宝和妇女，率军东去。有人劝项王说：“关中阻山带河，四面关塞，土地肥饶，可在这里建都，以定霸业。”项王看见秦朝宫室都已烧毁，残破不堪，又怀念故乡，心欲东归，就说：“富贵了不回故乡，如同衣绣夜行，有谁能知道！”劝项王的人说，“人们说楚国人是猕猴戴帽子，果然如此。”项王听到了这话，烹杀了劝说他的那个人。
项王派人向楚怀王报告请示。楚怀王说：“按照约定办。”项羽就尊楚怀王为义帝。项王想自己称王，就先封诸侯将相为王。对他们说：“天下最初发难的时候，暂时拥立诸侯后裔为王，以便讨伐秦朝。然而亲自身穿铠甲，手执兵器，率先起义，三年来风餐露宿，消灭秦朝，平定天下的，都是各位将相和我项籍的力量。只有义帝没有功劳，本来应该瓜分他的土地，封大家为王。”将领们都说：“好。”项王就分割天下，封将领们为侯王。
项王、范增疑心沛公将来占有天下。（不想让他称王关中，）但既已和解，又怕违背原约，诸侯反叛，他们就暗中商量说：“巴、蜀道路险恶，秦朝被迁徙的罪人都居住蜀地。”于是就（扬言）说：“巴、蜀也是关中地区。”所以封沛公为汉王，称王于巴、蜀、汉中，建都南郑。而把关中分为三部分，封给秦朝降将为王，阻挡汉王，（防止他将来向东方出兵。）
项王封章邯为雍王，称王于咸阳以西，建都废丘。长史司马欣，从前做栎阳狱掾，曾对项梁有过恩德；都尉董翳，最初劝说章邯降楚，所以封司马欣为塞王，称王于咸阳以东到黄河一带，建都栎阳；封董翳为翟王，称王于上郡，建都高奴。徙封魏王豹为西魏王，称王于河东，建都平阳。瑕丘申阳是张耳的宠臣，先攻下河南，在黄河岸边迎接楚军，所以立申阳为河南王，建都雒阳。韩王成仍以旧都城为都，建都阳翟。赵将司马印平定河内，屡立战功，所以封司马印为殷王，称王于河内，建都朝歌。徒封赵王歇为代王。赵相张耳一向贤能，又随从项王入关，所以封张耳为常山王，称王于赵地，建都襄国。当阳君黥布为楚军将领，常常勇冠全军，所以封黥布为九江王，建都于六。鄱君吴芮率领百越兵协助诸侯军，又随从入关，所以封吴芮为衡山王，建都于邾。义帝的柱国共敖率兵攻打南郡，功劳很多，于是封共敖为临江王，建都江陵。徙封燕王韩广为辽东王。燕将臧茶曾随楚军救赵，遂又跟从入关，所以封臧荼为燕王，建都于蓟。徒封齐王田市为胶东王。齐将田都曾随从项王共同救赵，遂又跟着入关，所以立田都为齐王，建都临淄。原来被秦朝灭亡的齐王建的孙子田安，正在项羽渡河救赵时，攻下济水北边几座城邑，率领他的军队投降了项羽，所以封田安为济北王，建都博阳。田荣多次有负项梁，又不愿率军随楚击秦，因此没有封王。成安君陈余丢弃将印离去，没有随从入关，然而一向听说他贤能，有功于赵，知道他在南皮，所以把环绕南皮的三个县封给他。番君的将领梅捐战功很多，所以封为十万户侯。项王自立为西楚霸王，封有九郡，建都彭城。
汉元年四月，在项王硅麾之下诸侯罢兵散归，各自回到封国。项王也出关回到封国，派人迁徙义帝，说：“古代做帝王的拥有千里见方的土地，必须住在上游。”于是就派遣使者把义帝迁往长沙郴县。项王催促义帝快些动身，义帝群臣渐渐背叛了他，项王就暗中命令衡山王、临江王把义帝击杀在江中。韩王成没有军功，项王不让他就国，一起到了彭城，废去王号，改封为侯，不久又杀死了。臧荼到了封国，就驱逐韩广去辽东，韩广不服从，臧茶在无终击杀了韩广，兼并了他的封地。
田荣听说项羽把齐王市徒封胶东，而立齐将田都为齐王，十分气愤，不愿让齐王去胶东，就据齐反叛，迎击田都。田都逃往楚国。齐工市害怕项王，就潜往胶东就国。田荣大为生气，派兵追击，在即墨杀死了他。田荣便自立为齐王，向西进兵，击杀了济北王田安，兼并了三齐。田荣把将军印授予彭越，让他在梁地反楚。陈余秘密派遣张同、夏说劝告齐王田荣说：“项羽为天下的主宰，（分封侯王）不公平。如今把原来的诸侯王都封在坏地方称王，而他的群臣诸将都封在好地方称王。（因为要）赶走原来的诸侯王，赵王就（只好）到北方居住代地，我以为这样是不能答应的。听说大王已经起兵，而且不接受不道义的命令，希望大王援助我一些兵马，允许我用以攻打常山，恢复赵王的地位，愿把赵国作为齐国的屏障。”齐王答应了，就遣兵赴赵。陈余调动了三县的全部士卒，与齐军并力攻打常山，打垮了常山的军队。张耳逃走归服了汉王。陈余去代地迎接原来的赵王歇返归赵地。赵王就立陈余为代王。
这时，汉王回军平定了三秦。项羽听说汉王已经兼并了关中，将要东进，齐、赵又反叛了他，非常愤怒。就以从前的吴令郑昌为韩王，来阻挡汉军。命令萧公角等人攻击彭越。彭越打败了萧公角等人。汉王派张良巡行招抚韩地，张良就给项王写信说：“汉王（没有如约称王关中），有失职守，打算取得关中，实现了原来的约定就停止进军，不敢继续东进。”张良又把齐、梁的反叛文告送给项王，说：“齐想和赵并力灭楚。”楚军因此无意西进，而向北攻打齐国。项王向九江王黥布征调兵力。黥布称病不往，派将领率兵几千人前去。项王从此怨恨黥布。
汉二年冬，项羽北上到达城阳，田荣也率军到此与项羽会战。田荣兵败，逃到平原，平原百姓杀死了他。楚军北进，烧毁齐国房屋，夷平齐国城郭，坑杀田荣降卒，掳掠老弱妇女。在齐攻城略地，直至北海，到处烧杀掠夺。齐国人联合起来反抗项羽。田荣的弟弟田横收集齐国逃散的士卒，得到几万人，反于城阳。项王因此留下来，连续攻打几次都没有攻下城阳。
春天，汉王统率五路诸侯的军队，共五十六万人，东进伐楚。项王听到这个消息，即令诸将攻打齐国，而自己带领精兵三万人南下，由鲁越过胡陵。四月，汉军都已进入彭城，搜掠财物珍宝和美女，天天设筵会饮，项王向西进发，到达萧县，早晨攻击汉军，向东进发，到达彭城，中午，把汉军打得大败。汉军溃退，相继逃入谷水、泗水，楚军杀死了十多万汉军士卒。汉军向南往山里逃跑，楚军又追击到灵壁东面的睢水上。汉军退却，为楚军所逼，拥挤在一起，多被杀伤，汉军十多万人落入睢水，睢水为之不流。楚军把汉王包围了三层。这时大风从西北刮起，吹断了树木，掀毁了房屋，飞沙走石，天色昏昏沉沉，（狂风夹杂着沙石）向楚军迎面扑来。楚军大乱，阵形溃散，汉王才得以和几十个骑兵逃走。打算经过沛县，接取家眷西行；楚军也派人追往沛县，掠取汉王家眷。家眷都已逃亡，没有和汉王相见。汉王在路上遇到了孝惠、鲁元，就用车拉着一块儿走。楚军骑兵追赶汉王，汉王着急了，把孝惠、鲁元推下车去，膝公便下车把他们抱上来，这样推下抱上了好几次。滕公说：“事虽危急，不是可以把车赶得快一些！怎么能丢弃他们！”汉王终于脱身而出。他寻找太公、吕后，没有找到。审食其跟随太公、吕后从小路潜行，寻找汉王，反而碰上了楚军。楚军就带他们回到军营，报告了项王，项王把他们拘留在军营里。
这时吕后的哥哥周吕侯为汉率兵驻扎在下邑，汉王抄小路来到周吕侯那里，稍稍收集了一些逃散的士卒。到了荥阳，各路败军都会合在一起，萧何也征发关中没有著籍的老弱全部来到荥阳，声势又振作起来。楚军从彭城出发，常常乘胜追击败兵，与汉军在荥阳南面的京、索之间交战，汉军打败了楚军，楚军因此不能越过荥阳西进。
项王解救彭城，追赶汉王到达荥阳，田横乘机收复了齐国，立田荣子田广为齐王。汉王在彭城战败，诸侯又都向楚背汉。汉军驻扎在荥阳，修筑了一条甬道，与黄河相连，以便运取敖仓的粮食。
汉三年，项王屡次侵夺汉军的甬道，汉王粮食缺乏，恐慌起来，请求讲和，划分荥阳以西归汉。项王想要答应他。历阳侯范增说：“汉军容易对付，现在放掉他们，不予以消灭，以后一定要懊悔。”项王就和范增加紧围攻荥阳。汉王深为忧虑，就采用陈平的计策离间项王和范增。项王的使者来了，给他准备了牛、羊、了齐全的丰盛筵席，打算端上去。端饭菜的人一看使者，假装惊愕他说：“我以为是亚父的使者，没想到反而是项王的使者。”把饭菜又端了下去，拿粗菜恶饭给项王的使者吃。使者回来报告了项王，项王就怀疑范增私通汉军，渐渐剥夺他的权力。范增大怒，说：“天下的形势，大局已定，君王好自为之。请赐还我的躯体，让我成为一个普通的士卒。”项王答应了他。范增走了，还没有到彭城，因背上长毒疮死去了。
汉军将领纪信劝汉王说：“形势已经很危急了，请让我假装成大王替你去蒙骗楚军，大王可以乘机逃出城去。”于是汉王夜间从荥阳东门放出两千名身穿铠甲的妇女，楚军四面围击。纪信乘坐黄屋车，左边的车衡上竖立着大纛旗，（卫士大声地）说：“城中粮食吃光了，汉王投降。”楚军都高呼万岁。汉王和几十名骑兵从西门出城，奔向成皋。项王见到纪信，问他：“汉王在哪里？”纪信说：“汉王已经出城了。”项王烧死了纪信。
汉王派御史大夫周苛、枞公、魏豹守卫荥阳。周苛、机公商量说：“魏豹这个叛国之王，很难和他共守城池。”就一起杀死了魏豹。楚军攻下荥阳城，活捉了周苛。项王对周苛说：“做我的将领，我以你为上将军，封三万户。”周苛骂着说：“你不赶快投降汉军，汉军就要俘虏你，你不是汉军的对手。”项王大怒，烹死了周苛，并杀了枞公。
汉王逃出荥阳，南走宛、叶，收服了九江王黥布，一边走一边收集士卒，又进入成皋固守。汉四年，项王围攻成皋。汉王逃走了，单身一人与滕公出了成皋北门，渡河奔向修武，到了张耳、韩信军营。诸将陆续逃出成皋，追随汉王。楚军攻下成皋，想要向西进军。汉王派兵在巩县阻击，使楚军不能西进。
这时，彭越渡河在东阿攻击楚军，杀死了楚将军薛公。项王就亲自东去攻打彭越。汉王得到淮阻侯的军队，打算渡河南下，郑忠劝阻汉王，汉王就停留在河内筑起营垒。派刘贾领兵协同彭越，烧掉楚军的粮食。项王东进打败了刘贾和彭越，彭越逃走了。汉王率军渡河，又夺取了成皋，驻扎在广武，取食敖仓。项王已经平定了东海，率军回来，向西进发，与汉军都在广武驻扎，相持了好几个月。
当时，彭越在梁地多次反击楚军，断绝楚军的粮食，项王很忧虑。他设置了一个高大的砧板，把太公放在上面，告诉汉王说：“现在不快快投降，我就烹杀太公。”汉王说：“我和你项羽都是北面称臣，受命于怀王，说是‘结为兄弟’，我的老子就是你的老子，一定要烹杀你的老子，那么希望你分给我一杯肉羹。”项王十分气愤，打算杀死太公。项伯说：“天下大事还不能预料，而且打天下的人不顾念家眷，虽然杀了大公也没有好处，只能增加祸患。”项王听从了项伯的话。
楚、汉长期相持，未决胜负，年青力壮的苦干行军作战，年老体弱的疲于水陆运输。项王对汉王说：“几年来天下扰攘不安。只是由于我们两个人的缘故，愿意与你挑战，一决雌雄，不要使天下百姓空受痛苦。”汉王笑着拒绝说：“我宁愿斗智，不愿斗力。”项王叫壮士出去挑战。汉军有个善长骑马射箭的人叫楼烦，楚军派壮士挑战三次，楼烦都把壮士射死了。项王大怒，就亲自披甲持戟出来挑战。楼烦想要射他，项王怒目呵叱，楼烦（被吓得）眼不敢正视，手不敢发箭，跑回营垒，不敢再出来。汉王派人暗中打听，才知道挑战的人原来是项王。汉王大为震惊。于是项王靠近汉王军营，和他隔着广武涧对话，汉王历数项王的罪状，项王非常气愤，要求决战。汉王没有答应，项王埋伏的弓弩射中了汉王，汉王受伤跑回成皋。
项王听说淮阴侯已经攻下河北，打垮了齐、赵军队，而且将要进攻楚军，就派龙且前往迎击。淮阴侯与龙旦交战，骑兵将领灌婴也出击龙且，大破楚军，杀死了龙且。韩信就自立为齐王。项王听说龙且的军队垮了，大为恐慌，派遣盱台人武涉去游说淮阴侯。淮阴侯不肯听从。这时，彭越又起来反楚，攻下梁地，断绝楚军的粮道。项王就对海春侯大司马曹咎等人说：“小心守卫成皋，即使汉军挑战，千万不要和它交战，不要让它东进就行了。我十五天一定杀掉彭越，平定梁地，再与将军会合。”于是项王率军东去，进军过程中攻打陈留、外黄。
外黄没有攻下。过了几天，外黄投降了，项王很生气，命令十五岁以上的男子全部到城东，准备坑杀他们，外黄令门客的儿子才十三岁，前去劝告项王说：“彭越用武力逼迫外黄百姓，外黄百姓很害怕，所以暂时投降，等待大王到来。大王到了，又都坑杀他们，难道百姓还有归顺之心吗？从这儿往东，梁地十多个城邑都心怀恐惧，没有肯投降的了。”项王赞成他的话，就赦免了外黄应当坑杀的那些人。从外黄往东直至睢阳，听到这个消息，都争先恐后地向项王投降。
汉军果然屡次向楚军挑战，楚军不出来应战。汉军派人在阵前辱骂楚军，骂了五六天，大司马十分气愤，让士卒渡过汜水，（迎击汉军。）士卒刚渡过一半，汉军出击，大败楚军，缴获了楚国全部物资。大司马曹咎、长史欣都自刎在汜水上。大司马曹咎原来是蕲县的狱掾，长史司马欣原来是栎阳的狱吏，两人曾对项梁有过恩德，因此项王信任他们。当时，项王在睢阳，听说海春侯的军队失败了，就率军返回。汉军正在荥阳东面围攻钟离眛，项王一到，汉军害怕楚军，全部撤走到险阻地带。
这时，汉军兵多粮足，项王兵疲粮绝。汉王派遣陆贾劝说项王，请求释放太公，项王没有答应。汉王又派遣侯公前去劝说项王，项王就和汉约定，平分天下，划鸿沟以西归汉，鸿沟以东归楚。项王答应了侯公的要求，就把汉王的父母妻子送了回来。汉军都高呼万岁。汉王封侯公为平国君。侯公隐匿起来，不肯再见汉王。汉王说：“这个人是天下善辩之士，所到之处，可以使人国家覆灭，所以封号为平国君。”项王已经订立和约，就解除了军事对峙，率军东归。
汉王准备西归，张良、陈平劝汉王说：“汉占领了大半个天下，而诸侯都归服了我们。楚军兵疲粮尽，这是上天让楚灭亡的时候，不如乘这个机会消灭它。现在放走项王不去攻打他，这就是所谓‘养虎自遗患’。”汉王同意了他们的建议。
汉五年，汉王追击项王到了阳夏南面，军队驻扎下来，与淮阴侯韩信、建成侯彭越约期会合进攻楚军。到达固陵，而韩信、彭越的军队不来会合。楚军攻击汉军，把汉军打得大败。汉王又进入营垒，挖深沟堑，自为固守。汉王对张子房说：“诸侯不遵守约定，怎么办呢？”张子房回答说：“楚军即将崩溃，韩信、彭越没有分到一块封地，他们不来会合是很自然的。君王能和他们共分天下，眼下可以使他们立刻前来。如果不能这样，局势的发展很难预料。君王能从陈县以东到海边的地区，全部划给韩信，睢阳以北到谷城，分给彭越，使他们各自为战，那么楚军是容易打败的。”汉王说：“好。”于是就派遣使者告诉韩信、彭越说：“合力攻打楚军。楚军崩溃后，从陈县以东到海边给予齐王，睢阳以北到谷城给予彭相国。”使者一到，韩信、彭越都回话说：“请让我们立刻进兵。”韩信就从齐地出发，刘贾的军队从寿春出发并行，屠毁了城父，到达垓下。大司马周殷背叛了楚国，利用舒地的兵力屠毁了六县，调动全部九江士卒，随同刘贾、彭越都会集在垓下，来到项王阵前。
项王的军队筑垒垓下，兵少粮尽，汉军和各路诸侯军队把它重重包围起来。夜晚听到四面的汉军都是唱的楚地歌曲，项王大为震惊他说：“汉军已经全部占领了楚国吗？为什么楚国人如此众多啊？”项王就夜间起来，在帐幕里饮酒。有一个名字叫虞的美人，得到项王的宠爱，常常带在身边。有一匹叫骓的骏马，项王经常骑着它。于是项王慷慨悲歌，自己作诗唱道：“力拔山兮气盖世，时不利兮骓不逝。骓不逝兮可奈何，虞兮虞兮奈若何！”唱了好几遍，美人跟着他一起唱。项王悲泣，泪下数行，左右侍从也都俯首哭泣，（悲痛得）不能抬头仰视。
于是项王上马（突围），部下壮士骑马随从的有八百多人，当夜冲破包围，向南飞驰而去。天亮，汉军才发觉，派骑兵将领灌婴率五千骑兵追赶项王。项王渡过淮水，能够跟从的骑兵只有一百多人，项王到阴陵，迷失了道路，询问一个种田的人，种田的人欺骗他说“往左”。项王往左去，结果陷入了一大片沼泽中。因此，汉军追上了项王。项王就又带兵向东，到了东城，只有二十八个骑兵了。追赶的汉军骑兵有几千人。项王自己估计不能脱身了，对他的骑兵说：“我起兵到现在八年了，亲身打过七十多次仗，谁抵挡我，我就打垮谁，我攻击谁，准就降服，未曾打过败仗，因而霸有天下。然而现在终于被围困在这里，这是上天要灭亡我，不是我打仗的过错。今天固然要决心战死，愿意力各位痛痛快快地打一仗，一定要三次取胜，力各位突破重围，斩杀敌将，砍倒敌人军旗，让各位知道是上天灭亡我，不是我打仗的过错。”项王就把他的骑兵分为四队，面向四方。汉军把项王包围了好几层。项王对他的骑兵说：“我为你们斩他一个将领。”项王命令骑兵四面疾驰而下，约定在山的东面会合为三处。于是项王大声呼喊着，飞奔直下，汉军惊惶溃乱，项王就斩了一个汉军将领。当时，赤泉侯做骑兵将领，追赶项王，项王怒目大吼，赤泉侯人马俱惊，倒退了好几里。项王和他的骑兵会合为三处。汉军不知道项王在哪里，就把军队分为三部分，又把项王包围起来，项王骑马冲驰，又斩了汉军的一个都尉，杀死了百十来人，再把他的骑兵集合起来，只丧失了两个骑兵。项王就对他的骑兵说：“怎么样？”骑兵都佩服他说：“正像大王所说的那样。”
项王想要向东渡过乌江。乌江亭长把船靠在岸边等待着项王。他对项王说：“江东虽小，地方也纵横上千里，民众数十万，也足以称王。希望大王赶快渡江。现在只有我有船只，汉军来到这，没有船只渡江。”项王笑着说：“上天要灭亡我，我渡江干什么呢！况且我和江东子弟八千人渡江西进，现在没有一个人回来，即使江东父兄怜悯我，让我称王，我有什么脸面去见他们？即使他们不说什么，我项籍难道不于心有愧吗？”（最后）项王对亭长说：“我知道你是个忠厚长者。我骑这匹马五年了，所向无敌，曾经一天奔驰一千里，不忍心杀了它，把它送给你吧。”就叫骑兵都下马步行，甲短兵接战。单单项籍一人就杀死汉军几百人。项王身上也受了十多处伤。他回头看见汉军的骑司马吕马童，说：“你不是我的老朋友吗？”吕马童背对项王，指给王翳说：“这就是项王。”项王说：“我听说汉军用一千斤黄金、一万户封邑来悬赏我的头，我给你做件好事吧。”就自刎而死。王翳割了项王的头，其他骑兵自相蹂躏践踏，争夺项王的尸体，互相残杀了几十人。最后，郎中骑杨喜，骑司马吕马童，郎中吕胜、杨武各自得到了项王的一段肢体。五个人把肢体合拢起来，都确实是项王的。所以把准备封赏的土地分为五部分：封吕马童为中水侯，封王翳为杜衍侯，封杨喜为赤泉侯，封杨武为吴防侯，封吕胜为涅阳侯。
项王死后，楚国各地都投降了汉军，只有鲁城不肯投降。汉王就带领天下士卒打算屠毁鲁城，因为他们坚守礼义，为主人以死守节，就拿项王的头给鲁城人看，鲁城父兄才投降了。最初，楚怀王曾封项籍为鲁公，等到项籍死了，鲁城又最后投降，所以用鲁公的礼仪把项王理葬在谷城。汉王为项王举哀，哭了一场，然后离开了鲁城。
各支项氏宗族，汉王都不诛杀。封项伯为射阳侯。桃侯、平景侯、玄武侯都是项氏宗族，赐姓刘。
太史公说：我听周生说“舜的眼睛大概是两个瞳孔”，又听说项羽也是两个瞳孔。项羽难道是舜的后裔吗？为什么兴起得这么迅速啊！秦朝政治腐败，陈涉首先发难，豪杰蜂起，相互争夺，不可胜数。然而项羽毫无凭借，乘势起于民间，三年时间，就率领五路诸侯军消灭了秦朝，分割天下，封王建侯，政自己出，号为“霸王”，虽然没有始终保持他的地位，但近古以来，还未曾有过这样的事情。等到项羽放弃关中，怀恋楚地，放逐义帝而自立为王，抱怨王侯背叛自己，这时已经难以控制局势了。自我夸耀功勋，逞一己私智，不效法古人，以为创立霸王的事业，需要用武力来经营天下，终于五年时间覆灭了他自己的国家，身死东城，还没有觉悟，不自我谴责，这就不对了。竟然用“上天灭亡我，不是我用兵打仗的过错”为借口，难道不是太荒谬了吗！', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d6c6e67846a921a0fa", "shortContent": "本篇节选自《史记·项羽本纪》，题目为后人所拟。\n有人把《史记》誉之为悲剧英雄画廊，西楚霸王项羽则是悲剧群像中的绝代典型，“项羽之死”这个片断便是这部旷世悲剧的最后一幕。“喑噁叱咤，千人皆废”的英雄死了，留在人间的是历史长河中曾经“卷起千堆雪”的浪花，群山万壑中殷殷不绝的回响，两千年来无数读者掩卷而思、拍案而起的长叹息。\n这最后一幕，由垓下之围、东城快战、乌江自刎三场组成，其中包含了楚歌夜警、虞兮悲...", "authors": ["赖汉屏"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa103572034f65b5e0a", "shortContent": "这是一桩“恶人自有恶鬼磨”的惩戒故事。\n张某为人深险诡谲，巧言善骗，这在尔虞我诈、逢人只说三分话的封建社会，本有其社会根源。出于自我保护的需要，一向忠厚朴讷的“老实头”，也可能在特定场合耍一点小狡黠；为了捍卫正义，对付敌人，坦荡刚直的人也须搞些谋略。但张某则不然：他在任何场合，对任何人，从来不说一句实话，把对待敌手、应付弊害的手法，无限推广，到处行骗，四面树敌，终于引起周围的人反感，落得个四面楚歌...", "authors": ["鄢化志"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b9434bfda01e0eab209", "bookTitle": "唐宋小说鉴赏辞典", "articleId": "610f43e4dbb8b379ee0aff1d", "shortContent": "这是一篇历史故事变文，出自敦煌写本。作品以王陵斫楚营、项羽捉陵母、卢绾送战书、项羽辱陵母及陵母伏剑死几个富于戏剧性的场面，形象地表现了特定历史时期的历史风貌，同时，突出刻画了王陵母亲威武不屈、深明大义、成子助汉的不凡品质。\n\n在艺术构思上，《汉将王陵变》把《史记》中不到二百字的记载变为长达八千字的篇幅，这不单是字数的增加，而是以极丰富的想象，将梗概的记载化为血肉丰满、娓娓动听的说唱故事。《史记·陈...", "authors": ["陈惠琴"], "pressName": "上海辞书出版社"}, {"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3d8e8f18b220af4bf55", "shortContent": "项羽是楚国世代将门之后，项燕之孙。楚国灭亡之后，项氏家族惨遭屠杀，他随叔父项梁流亡到吴县（今江苏苏州）。秦二世元年（前209年），陈胜、吴广在大泽乡揭竿而起。大泽乡起义不久，项羽在会稽郡斩杀郡守后崛起，举兵反秦。并于公元前207年的决定性战役巨鹿之战中大破秦军主力。巨鹿之战后，率军入关中，将五诸侯灭暴秦，威震海内。是时，分裂天下，册封十八路诸侯，并自立为西楚霸王，统治黄河及长江下游的梁、楚九郡。后...", "authors": ["周示莹"], "pressName": "上海辞书出版社"}]', '', 'indent', 1525197440, '5ae839e9ac502e006278b6db', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637448, '史记 · 十二本纪 · 吕太后本纪 ', NULL, 4, 139, 0, 1, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E5%90%95%E5%A4%AA%E5%90%8E%E6%9C%AC%E7%BA%AA/2391198?fr=aladdin', '', '吕太后者，高祖微时妃也，生孝惠帝、女鲁元太后。及高祖为汉王，得定陶戚姬，爱幸，生赵隐王如意。孝惠为人仁弱，高祖以为不类我，常欲废太子，立戚姬子如意，如意类我。戚姬幸，常从上之关东，日夜啼泣，欲立其子代太子。吕后年长，常留守，希见上，益疏。如意立为赵王后，几代太子者数矣，赖大臣争之，及留侯策，太子得毋废。
吕后为人刚毅，佐高祖定天下，所诛大臣多吕后力。吕后兄二人，皆为将。长兄周吕侯死事，封其子吕台为郦侯，子产为交侯；次兄吕释之为建成侯。
高祖十二年四月甲辰，崩长乐宫，太子袭号为帝。是时高祖八子：长男肥，孝惠兄也，异母，肥为齐王；余皆孝惠弟，戚姬子如意为赵王，薄夫人子恒为代王，诸姬子子恢为梁王，子友为淮阳王，子长为淮南王，子建为燕王。高祖弟交为楚王，兄子濞为吴王。非刘氏功臣番君吴芮子臣为长沙王。
吕后最怨戚夫人及其子赵王，乃令永巷囚戚夫人，而召赵王。使者三反，赵相建平侯周昌谓使者曰：“高帝属臣赵王，赵王年少。窃闻太后怨戚夫人，欲召赵王并诛之，臣不敢遣王。王且亦病，不能奉诏。”吕后大怒，乃使人召赵相。赵相征至长安，乃使人复召赵王。王来，未到。孝惠帝慈仁，知太后怒，自迎赵王霸上，与入宫，自挟与赵王起居饮食。太后欲杀之，不得闲。孝惠元年十二月，帝晨出射。赵王少，不能蚤起。太后闻其独居，使人持鸩饮之。犁明，孝惠还，赵王已死。于是乃徙淮阳王友为赵王。夏，诏赐郦侯父追谥为令武侯。太后遂断戚夫人手足，去眼，辉耳，饮喑药，使居厕中，命曰“人彘”。居数日，乃召孝惠帝观人彘。孝惠见，问，乃知其戚夫人，乃大哭，因病，岁余不能起。使人请太后曰：“此非人所为。臣为太后子，终不能治天下。”孝惠以此日饮为淫乐，不听政，故有病也。
二年，楚元王、齐悼惠王皆来朝。十月，孝惠与齐王燕饮太后前，孝惠以为齐王兄，置上坐，如家人之礼。太后怒，乃令酌两卮酖，置前，令齐王起为寿。齐王起，孝惠亦起，取卮欲俱为寿。太后乃恐，自起泛孝惠卮。齐王怪之，因不敢饮，详醉去。问，知其酖，齐王恐，自以为不得脱长安，忧。齐内史士说王曰：“太后独有孝惠与鲁元公主。今王有七十余城，而公主乃食数城。王诚以一郡上太后，为公主汤沐邑，太后必喜，王必无忧。”于是齐王乃上城阳之郡，尊公主为王太后。吕后喜，许之。乃置酒齐邸，乐饮，罢，归齐王。三年，方筑长安城，四年就半，五年六年城就。诸侯来会。十月朝贺。
七年秋八月戊寅，孝惠帝崩。发丧，太后哭，泣不下。留侯子张辟彊为侍中，年十五，谓丞相曰：“太后独有孝惠，今崩，哭不悲，君知其解乎？”丞相曰：“何解？”辟彊曰：“帝毋壮子，太后畏君等。君今请拜吕台、吕产、吕禄为将，将兵居南北军，及诸吕皆入宫，居中用事，如此则太后心安，君等幸得脱祸矣。”丞相乃如辟彊计。太后说，其哭乃哀。吕氏权由此起。乃大赦天下。九月辛丑，葬。太子即位为帝，谒高庙。元年，号令一出太后。
太后称制，议欲立诸吕为王，问右丞相王陵。王陵曰：“高帝刑白马盟曰’非刘氏而王，天下共击之‘。今王吕氏，非约也。”太后不说。问左丞相陈平、绛侯周勃。勃等对曰：“高帝定天下，王子弟，今太后称制，王昆弟诸吕，无所不可。”太后喜，罢朝。王陵让陈平、绛侯曰：“始与高帝啑血盟，诸君不在邪？今高帝崩，太后女主，欲王吕氏，诸君从欲阿意背约，何面目见高帝地下？”陈平、绛侯曰：“于今面折廷争，臣不如君；夫全社稷，定刘氏之后，君亦不如臣。”王陵无以应之。十一月，太后欲废王陵，乃拜为帝太傅，夺之相权。王陵遂病免归。乃以左丞相平为右丞相，以辟阳侯审食其为左丞相。左丞相不治事，令监宫中，如郎中令。食其故得幸太后，常用事，公卿皆因而决事。乃追尊郦侯父为悼武王，欲以王诸吕为渐。
四月，太后欲侯诸吕，乃先封高祖之功臣郎中令无择为博城侯。鲁元公主薨，赐谥为鲁元太后。子偃为鲁王。鲁王父，宣平侯张敖也。封齐悼惠王子章为朱虚侯，
以吕禄女妻之。齐丞相寿为平定侯。少府延为梧侯。乃封吕种为沛侯，吕平为扶柳侯，张买为南宫侯。
太后欲王吕氏，先立孝惠后宫子彊为淮阳王，子不疑为常山王，子山为襄城侯，子朝为轵侯，子武为壶关侯。太后风大臣，大臣请立郦侯吕台为吕王，太后许之。建成康侯释之卒，嗣子有罪，废，立其弟吕禄为胡陵侯，续康侯后。二年，常山王薨，以其弟襄城侯山为常山王，更名义。十一月，吕王台薨，谥为肃王，太子嘉代立为王。三年，无事。四年，封吕嬃为临光侯，吕他为俞侯，吕更始为赘其侯，吕忿为吕城侯，及诸侯丞相五人。
宣平侯女为孝惠皇后时，无子，详为有身，取美人子名之，杀其母，立所名子为太子。孝惠崩，太子立为帝。帝壮，或闻其母死，非真皇后子，乃出言曰：“后安能杀吾母而名我？我未壮，壮即为变。”太后闻而患之，恐其为乱，乃幽之永卷中，言帝病甚，左右莫得见。太后曰：“凡有天下治为万民命者，盖之如天，容之如地，上有欢心以安百姓，百姓欣然以事其上，欢欣交通而天下治。今皇帝病久不已，乃失惑惛乱，不能继嗣奉宗庙祭祀，不可属天下，其代之。”群臣皆顿首言：“皇太后为天下齐民计所以安宗庙社稷甚深，群臣顿首奉诏。”帝废位，太后幽杀之。五月丙辰，立常山王义为帝，更名曰弘。不称元年者，以太后制天下事也。以轵侯朝为常山王。置太尉官，绛侯勃为太尉。五年八月，淮阳王薨，以弟壶关侯武为淮阳王。六年十月，太后曰吕王嘉居处骄恣，废之，以肃王台弟吕产为吕王。夏，赦天下。封齐悼惠王子兴居为东牟侯。
七年正月，太后召赵王友。友以诸吕女为受后，弗爱，爱他姬，诸吕女妒，怒去，谗之于太后，诬以罪过，曰：“吕氏安得王！太后百岁后，吾必击之”。太后怒，以故召赵王。赵王至，置邸不见，令卫围守之，弗与食。其群臣或窃馈，辄捕论之，赵王饿，乃歌曰：“诸吕用事兮刘氏危，迫胁王侯兮彊授我妃。我妃既妒兮诬我以恶，谗女乱国兮上曾不寤。我无忠臣兮何故弃国？自决中野兮苍天举直！于嗟不可悔兮宁蚤自财。为王而饿死兮谁者怜之！吕氏绝理兮托天报仇。”丁丑，赵王幽死，以民礼葬之长安民冢次。
己丑，日食，昼晦。太后恶之，心不乐，乃谓左右曰：“此为我也。”
二月，徙梁王恢为赵王。吕王产徙为梁王，梁王不之国，为帝太傅。立皇子平昌侯太为吕王。更名梁曰吕，吕曰济川。太后女弟吕嬃有女为营陵侯刘泽妻，泽为大将军。太后王诸吕，恐即崩后刘将军为害，乃以刘泽为琅邪王，以慰其心。
梁王恢之徙王赵，心怀不乐。太后以吕产女为赵王后。王后从官皆诸吕，擅权，微伺赵王，赵王不得自恣。王有所爱姬，王后使人酖杀之。王乃为歌诗四章，令乐人歌之。王悲，六月即自杀。太后闻之，以为王用妇人弃宗庙礼，废其嗣。
宣平侯张敖卒，以子偃为鲁王，敖赐谥为鲁元王。
秋，太后使使告代王，欲徙王赵。代王谢，愿守代边。
太傅产、丞相平等言，武信侯吕禄上侯，位次第一，请立为赵王。太后许之，追尊禄父康侯为赵昭王。九月，燕灵王建薨，有美人子，太后使人杀之，无后，国除。八年十月，立吕肃王子东平侯吕通为燕王，封通弟吕庄为东平侯。
三月中，吕后祓，还过轵道，见物如苍犬，据高后掖，忽弗复见。卜之，云赵王如意为祟。高后遂病掖伤。
高后为外孙鲁元王偃年少，蚤失父母，孤弱，乃封张敖前姬两子，侈为新都侯，寿为乐昌侯，以辅鲁元王偃。及封中大谒者张释为建陵侯，吕荣为祝兹侯。诸中宦者令丞皆为关内侯，食邑五百户。
七月中，高后病甚，乃令赵王吕禄为上将军，军北军；吕王产居南军。吕太后诫产、禄曰：“高帝已定天下，与大臣约，曰’非刘氏王者，天下共击之‘。今吕氏王，大臣弗平。我即崩，帝年少，大臣恐为变。必据兵卫宫，慎毋送丧，毋为人所制。”辛巳，高后崩，遗诏赐诸侯王各千金，将相列侯郎吏皆以秩赐金。大赦天下。以吕王产为相国，以吕禄女为帝后。
高后已葬，以左丞相审食其为帝太傅。
朱虚侯刘章有气力，东牟侯兴居其弟也。皆齐哀王弟，居长安。当是时，诸吕用事擅权，欲为乱，畏高帝故大臣绛、灌等，未敢发。朱虚侯妇，吕禄女，阴知其谋。恐见诛，乃阴令人告其兄齐王，欲令发兵西，诛诸吕而立。朱虚侯欲从中与大臣为应。齐王欲发兵，其相弗听。八月丙午，齐王欲使人诛相，相召平乃反，举兵欲围王，王因杀其相，遂发兵东，诈夺琅邪王兵，并将之而西。语在齐王语中。
齐王乃遗诸侯王书曰：“高帝平定天下，王诸子弟，悼惠王王齐。悼惠王薨，孝惠帝使留侯良立臣为齐王。孝惠崩，高后用事，春秋高，听诸吕，擅废帝更立，又比杀三赵王，灭梁、赵、燕以王诸吕，分齐为四。忠臣进谏，上惑乱弗听。今高后崩，而帝春秋富，未能治天下，固恃大臣诸侯。而诸吕又擅自尊官，聚兵严威，劫列侯忠臣，矫制以令天下，宗庙所以危。寡人率兵入诛不当为王者。”汉闻之，相国吕产等乃遣颍阴侯灌婴将兵击之。灌婴至荥阳，乃谋曰：“诸吕权兵关中，欲危刘氏而自立。今我破齐还报，此益吕氏之资也。”乃留屯荥阳，使使谕齐王及诸侯，与连和，以待吕氏变，共诛之。齐王闻之，乃还兵西界待约。
吕禄、吕产欲发乱关中，内惮绛侯、朱虚等，外畏齐、楚兵，又恐灌婴畔之，欲待灌婴兵与齐合而发，犹豫未决。当是时，济川王太、淮阳王武、常山王朝名为少帝弟，及鲁元王吕后外孙，皆年少未之国，居长安。赵王禄、梁王产各将兵居南北军，皆吕氏之人。列侯群臣莫自坚其命。
太尉绛侯勃不得入军中主兵。曲周侯郦商老病，其子寄与吕禄善。绛侯乃与丞相陈平谋，使人劫郦商。令其子寄往绐说吕禄曰：“高帝与吕后共定天下，刘氏所立九王，吕氏所立三王，皆大臣之议，事已布告诸侯，诸侯皆以为宜。今太后崩，帝少，而足下佩赵王印，不急之国守藩，乃为上将，将兵留此，为大臣诸侯所疑。足下何不归印，以兵属太尉？请梁王归相国印，与大臣盟而之国，齐兵必罢，大臣得安，足下高枕而王千里，此万世之利也。”吕禄信然其计，欲归将印，以兵属太尉。使人报吕产及诸吕老人，或以为便，或曰不便，计犹豫未有所决。吕禄信郦寄，时与出游猎。过其姑吕嬃，嬃大怒，曰：“若为将而弃军，吕氏今无处矣。”乃悉出珠玉宝器散堂下，曰：“毋为他人守也”
左丞相食其免。
八月庚申旦，平阳侯窋行御史大夫事，见相国产计事。郎中令贾寿使从齐来，因子产曰：“王不蚤之国，今虽欲行，尚可得邪？”具以灌婴与齐楚合从，欲诛诸吕告产，乃趣产急入宫。平阳侯颇闻其语，乃驰告丞相、太尉。太尉欲入北军，不得入。襄平侯通尚符节。乃令持节矫内太尉北军。太尉复令郦寄与典客刘揭先说吕禄曰：“帝使太尉守北军，欲足下之国，急归将印辞去，不然，祸且起。”吕禄以为郦兄不欺己，遂解印属典客，而以兵授太尉。太尉将之入军门，行令军中曰：“为吕氏右襢，为刘氏左襢。”军中皆左襢为刘氏。太尉行至，将军吕禄亦已解上将印去，太尉遂将北军。
然尚有南军。平阳侯闻之，以吕产谋告丞相平，丞相平乃召朱虚侯佐太尉。太尉令朱虚侯监军门。令平阳侯告卫尉：“毋入相国产殿门。”吕产不知吕禄已去北军，乃入未央宫，欲为乱，殿门弗得入，裴回往来。平阳侯恐弗胜，驰语太尉。太尉尚恐不胜诸吕，未敢讼言诛之，乃遣朱虚侯谓曰：“急入宫卫帝。”朱虚侯请卒，太尉予卒千余人。入未央宫门，遂见产廷中。日哺时，遂击产。产走，天风大起，以故其从官乱，莫敢斗。逐产，杀之郎中府吏厕中。
朱虚侯已杀产，帝命谒者持节劳朱虚侯。朱虚侯欲夺节信，谒者不肯，朱虚侯则从与载，因节信驰走，斩长乐卫尉吕更始。还，驰入北军，报太尉。太尉起，拜贺朱虚侯曰：“所患独吕产，今已诛，天下定矣。”遂遣人分部悉捕诸吕男女，无少长皆斩之。辛酉，捕斩吕禄，而笞杀吕嬃。使人诛燕王吕通，而废鲁王偃。壬戌，以帝太傅食其复为左丞相。戊辰，徙济川王王梁，立赵幽王子遂为赵王。遣朱虚侯章以诛诸吕氏事告齐王，令罢兵。灌婴兵亦罢荥阳而归。
诸大臣相与阴谋曰：“少帝及梁、淮阳、常山王，皆非真孝惠子也。吕后以计诈名他人子，杀其母，养后宫，令孝惠子之，立以为后，及诸王，以彊吕氏。今皆已夷灭诸吕，而置所立，即长用事，吾属无类矣。不如视诸王最贤者立之。”或言“齐悼惠王高帝长子，今其适子为齐王，推本言之，高帝适长孙，可立也”。大臣皆曰：“吕氏以外家恶而几危宗庙，乱功臣今齐王母家驷（钧），驷钧，恶人也。即立齐王，则复为吕氏。”欲立淮南王，以为少，母家又恶。乃曰：“代王方今高帝见子，最长，仁孝宽厚。太后家薄氏谨良。且立长故顺，以仁孝闻于天下，便。”乃相与共阴使人召代王。代王使人辞谢。再反，然后乘六乘传。后九月晦日己酉，至长安，舍代邸。大臣皆往谒，奉天子玺上代王，共尊立为天子。代王数让，群臣固请，然后听。
东牟侯兴居曰：“诛吕氏吾无功，请得除宫。”乃与太仆汝阴侯滕公入宫，前谓少帝曰：“足下非刘氏，不当立。”乃顾麾左右执戟者掊兵罢去。有数人不肯去兵，宦者令张泽谕告，亦去兵。滕公乃召乘舆车载少帝出。少帝曰：“欲将我安之乎？”滕公曰“出就舍。”舍少府。乃奉天子法驾，迎代王于邸。报曰：“宫谨除。”代王即夕入未央宫。有谒者十人持戟卫端门，曰：“天子在也，足下何为者而入？”代王乃谓太尉。太尉往谕，谒者十人皆掊兵而去。代王遂入而听政。夜，有司分部诛灭梁、淮阳、常山王及少帝于邸。
代王立为天子。二十三年崩，谥为孝文皇帝。
太史公曰：孝惠皇帝、高后之时，黎民得离战国之苦，君臣俱欲休息乎无为，故惠帝垂拱，高后女主称制，政不出房户，天下晏然。刑罚罕用，罪人是希。民务稼穑，衣食滋殖。', '《史记·吕太后本纪》是西汉史学家司马迁创作的一篇文言文，收录于《史记》中，是史记本纪的第九篇，是史记中唯一一篇单独为女性作的传记。该篇本纪成功地塑造了吕后这样一个残忍刻毒、权欲薰心的乱政后妃的形象，详细地记述了吕后篡权及其覆灭的过程。这篇本纪记事真实，刻画人物性格鲜明深刻，通过描写吕后残害戚姬、连杀三赵王等事件表现了其残忍狠毒的性格，作者还用貌似悠闲的文字不动声色地加重表达自己对吕后的憎恶之情，全文艺术感染力强。', '集解徐广曰：“吕后父吕公，汉元年为临泗侯，四年卒，高后元年追谥曰吕宣王。”
集解汉书音义曰：“讳雉。”索隐讳雉，字娥姁也。
集解汉书音义曰：“讳盈。”
集解如淳曰：“姬音怡，众妾之总称也。汉官仪曰’姬妾数百‘。”苏林曰：“清河国有妃里，而题门作’姬‘。”瓒曰：“汉秩禄令及茂陵书姬，内官也，秩比二千石，位次婕妤下，在七子、八子之上。”索隐如淳音怡，非也。茂陵书曰“姬是内官”，是矣，然官号及妇人通称姬者，姬，周之姓，所以左传称伯姬、叔姬，以言天子之宗女，贵于他姓，故遂以姬为妇人美号。故诗曰“虽有姬姜，不弃憔悴”是也。
索隐上其纪反，又音祈也。
索隐张良、叔孙通等。
索隐令太子卑词安车，以迎四皓也。
集解徐广曰：“名泽，高祖八年卒，谥令武侯，追谥曰悼武王。”
索隐郑氏、邹诞并音怡，苏林音胎。
集解徐广曰：“郦，一作’鄜‘。”
集解徐广曰：“台弟也。”
集解徐广曰：“惠帝二年卒，谥康王。”
索隐母曰曹姬也。
集解如淳曰：“列女传云周宣王姜后脱簪珥待罪永巷，后改为掖庭。”索隐永巷，别宫名，有长巷，故名之也。后改为掖庭。按：韦昭云以为在掖门内，故谓之掖庭也。
集解应劭曰：“酖鸟食蝮，以其羽画酒中，饮之立死。”
集解徐广曰：“犁犹比也。诸言犁明者，将明之时。”
索隐令音龄。
索隐音捧泛也。
集解徐广曰：“一作’出‘。”
集解如淳曰：“公羊传曰’天子嫁女于诸侯，必使诸侯同姓者主之‘，故谓之公主。百官表列侯所食曰国，皇后、公主所食曰邑，诸侯王女曰公主。”苏林曰：“公，五等尊爵也。春秋听臣子以称君父，妇人称主，有’主孟啗我‘之比，故云公主。”瓒曰：“天子女虽食汤沐之邑，不君其民。”索隐啗音徒滥反。按：主是谓里克妻，即优施之语，事见国语。孟者，且也，言且啗我物，我教汝妇事夫之道。此即妇人称主之意耳。比音必二反。
集解如淳曰：“张敖子偃为鲁王，故公主得为太后。”
正义汉法，诸侯各起邸第于京师。
索隐按：汉宫阙疏“四年筑东面，五年筑北面”。汉旧仪“城方六十三里，经纬各十二里”。三辅旧事云“城形似北斗”也。
集解皇甫谧曰：“帝以秦始皇三十七年生，崩时年二十三。”
集解应劭曰：“入侍天子，故曰侍中。”
正义解，纪卖反。言哭解惰，有所思也。又音户卖反。解，节解也。又纪买反，谓解说也。
正义毋音无。
集解汉书云：“葬安陵。”皇览曰：“山高三十二丈，广袤百二十步，居地六十亩。”皇甫谧曰：“去长陵十里，在长安北三十五里。”
索隐啑，邹音使接反。又云或作“喢”，音丁牒反。
集解应劭曰：“古官。傅者，覆也。”瓒曰：“大戴礼云’傅之德义‘。”
索隐按：韦昭云信都之县名。
集解徐广曰：“姓冯。”
正义括地志云：“兖州博城，本汉博城县城。”
索隐虚音墟，琅邪县也。正义括地志云：“朱虚故城在青州临朐县东六十里，汉朱虚也。十三州志云丹朱游故虚，故云朱虚也。”虚犹丘也。朱犹丹也。
集解徐广曰：“姓齐。”
集解徐广曰：“姓阳成也。延以军匠起，作宫筑城也。”
集解徐广曰：“释之之子也。”正义括地志云：“徐州沛县古城也。”
集解徐广曰：“吕后姊子也。母字长姁。”正义括地志云：“扶柳故城在冀州信都县西三十里，汉扶柳县也。有泽，泽中多柳，故曰扶柳。”
集解徐广曰：“其父越人，为高祖骑将。”
集解韦昭曰：“今陈留郡。”
正义括地志云：“常山故城在恒州真定县南八里，本汉东垣邑也。”
索隐按：下文更名义，又改名弘农。汉书襄城侯唯云名弘，盖史省文耳。按志，襄城属颍川也。
索隐按：韦昭云河内有轵县，音纸也。正义括地志云：“故轵城在怀州济源县东南十三里，七国时魏邑。”
正义初吕台为吕王，后吕产王梁，更名梁曰吕。
集解徐广曰：“释之少子。”
正义胡陵，县名，属山阳，章帝改曰胡陆。
集解汉书云：“秋，星昼见。”
索隐他音陀。俞音输。正义括地志云：“故鄃城在德州平原县西南三十里，本汉鄃县，吕他邑也。”
集解徐广曰：“表云吕后昆弟子淮阳丞相吕胜为赘其侯。”索隐按表作“临淮”也。
正义括地志云：“故吕城在邓州南阳县西三十里，吕尚先祖封。”
集解徐广曰：“中邑侯朱通、山都侯王恬开、松兹侯徐厉、滕侯吕更始、醴陵侯越。”
正义刘伯庄云：“诸美人元幸吕氏，怀身而入宫生子。”
集解徐广曰：“一无此字。”
索隐韦昭云：“东莱县。”
集解徐广曰：“举，一作’与‘。”
索隐韦昭云：“樊哙妻，封林光侯。”
集解徐广曰：“吕后兄子也。前封胡陵侯，盖号曰武信。”
集解如淳曰：“功大者位在上，功臣侯表有第一第二之次也。”
正义祓，芳弗反，又音废。后同。
集解徐广曰：“音戟。”
集解徐广曰：“食细阳之池阳乡。”
集解徐广曰：“一云张释卿。”駰案：如淳曰“百官表’谒者掌宾赞受事‘，灌婴为中谒者。后常以奄人为之，诸官加’中‘者多奄人也”。
集解徐广曰：“吕后昆弟子。”
集解如淳曰：“列侯出关就国，关内侯但爵其身，有加异者，与关内之邑，食其租税也。风俗通义曰’秦时六国未平，将帅皆家关中，故称关内侯‘。”
集解蔡邕曰：“皇子封为王者，其实古诸侯也。加号称王，故谓之诸侯王。王子弟封为侯者，谓之诸侯。”
集解皇甫谧曰：“合葬长陵。”皇览曰：“高帝、吕后，山各一所也。”
索隐比音如字。比犹频也。赵隐王如意，赵幽王友，赵王恢，是三赵王也。
索隐犹，邹音以兽反。与音预，又作“豫”。崔浩云“犹，蝯类也。卬鼻，长尾，性多疑”。又说文云“犹，兽名，多疑”，故比之也。按：狐性亦多疑，度冰而听水声，故云“狐疑”也。今解者又引老子“与兮若冬涉川，犹兮若畏四邻”，故以为“犹与”是常语。且按狐听冰，而此云“若冬涉川”，则与是狐类不疑。“犹兮若畏四邻”，则犹定是兽，自不保同类，故云“畏四邻”也。
索隐吴，楚，齐，淮南，琅邪，代，常山王朝，淮阳王武，济川王太，是九也。
索隐梁王产、赵王禄、燕王通也。
索隐颜师古以为言见诛灭，无处所也。
集解徐广曰：“姓纪。”张晏曰：“纪信字也。尚，主也。今符节令。”索隐张晏云：“纪信子。”又晋灼云：“信被楚烧死，不见有后。按功臣表襄平侯纪通，父成以将军定三秦，死事，子侯。”则通非信子，张说误矣。
集解汉书百官表曰：“典客，秦官也，掌诸侯、归义蛮夷也。”
集解徐广曰：“音况，字也。名寄。”
集解徐广曰：“讼，一作’公‘。”駰按：韦昭曰“讼犹公也”。索隐按：韦昭以讼为公，徐广又云一作“公”，盖公为得。然公言犹明言也。又解者云讼，诵说也。
集解如淳曰：“百官表郎中令掌宫殿门户，故其府在宫中，后转为光禄勋也。”
集解张晏曰：“备汉朝有变，欲驰还也。或曰传车六乘。”
集解文颖曰：“即闰九月也。时律历废，不知闰，谓之’后九月‘也。以十月为岁首，至九月则岁终，后九月则闰月。”
集解徐广曰：“掊音仆。”
集解蔡邕曰：“律曰’敢盗乘舆服御物‘。天子至尊，不敢渫渎言之，故托于乘舆也。乘犹载也，舆犹车也。天子以天下为家，不以京师宫室为常处，则当乘车舆以行天下，故群臣托舆以言之也，故或谓之’车驾‘。”
集解蔡邕曰：“天子有大驾、小驾、法驾。法驾上所乘，曰金根车，驾六马，有五时副车，皆驾四马，侍中参乘，属车三十六乘。”
【索隐述赞】高祖犹微，吕氏作妃。及正轩掖，潜用福威。志怀安忍，性挟猜疑。置鸩齐悼，残彘戚姬。孝惠崩殒，其哭不悲。诸吕用事，天下示私。大臣葅醢，支櫱芟夷。祸盈斯验，苍狗为菑', '吕太后是高祖贫贱时的妻子，生了孝惠帝和鲁元太后。到高祖做汉王时，又娶了定陶人戚姬，非常宠爱她，生了赵隐王刘如意。孝惠帝为人仁惠柔弱，高祖认为不象自己，常想废掉他，改立戚姬的儿子如意为太子，因为如意象自己。戚姬得到宠爱，常跟随高祖到关东，她日夜啼哭，想要让自己的儿子取代孝惠帝做太子。吕后年纪大，经常留在家中，很少见到高祖，和高祖越来越疏远。如意被立为赵王之后，好几次险些取代了太子的地位，靠着大臣们的极力诤谏，以及留侯张良的计策，太子才没有被废掉。　　吕后为人刚强坚毅，辅佐高祖平定天下，诛杀韩信、黥（qíng）布、彭越等大臣也多有吕后之力。吕后有两个哥哥，都是高祖的部将。大哥周吕侯吕泽死于战争，他的儿子吕台被封为郦（lì）侯，吕产被封为交侯；二哥吕释之被封为建成侯。　　高祖十二年（前195）四月甲辰日，高祖逝于长乐宫，太子承袭帝号做了皇帝。当时高祖有八个儿子：长子刘肥是惠帝的异母兄，被封为齐王，其余都是惠帝的弟弟，戚夫人的儿子刘如意被封为赵王，薄夫人的儿子刘恒被封为代王，其他妃嫔的儿子，刘恢被封为梁王，刘友被封为淮阳王，刘长被封为淮南王，刘建被封为燕王。高祖的弟弟刘交被封为楚王，高祖兄的儿子刘濞（bì）被封为吴王。非刘氏的功臣鄱（pó）君吴芮（ruì）的儿子吴臣被封为长沙王。　　吕后最怨恨戚夫人和她的儿子赵王，就命令永巷令把戚夫人囚禁起来，同时派人召赵王进京。使者往返多次，赵国丞相建平侯周昌对使者说：“高皇帝把赵王托付给我，赵王年纪还小。我听说太后怨恨戚夫人，想把赵王召去一起杀掉，我不能让赵王前去。况且赵王又有病，不能接受诏命。”吕后非常恼怒，就派人去召周昌。周昌被召到长安，吕后又派人去召赵王。赵王动身赴京，还在半路上。惠帝仁慈，知道太后恼恨赵王，就亲自到霸上去迎接，跟他一起回到宫中，亲自保护，跟他同吃同睡。太后想要杀赵王，却得不到机会。孝惠元年（前194）十二月一天清晨，惠帝出去射箭。赵王年幼，不能早起。太后得知赵王独自在家，派人拿去毒酒让他喝下。等到惠帝回到宫中，赵王已经死了。于是就调淮阳王刘友去做赵王。这年夏天，下诏追封郦侯吕台的父亲吕泽为令武侯。太后随即派人砍断戚夫人的手脚，挖去眼睛，熏聋耳朵，灌了哑药，扔到猪圈里，叫她“人彘”。过了几天，太后叫惠帝去看人猪。惠帝看了，一问，才知道这就是戚夫人，于是大哭起来，从此就病倒了，一年多不能起来。惠帝派人请见太后说：“这不是人干的事情，我作为太后的儿子，再也不能治理天下了。”惠帝从此每天饮酒作乐，放纵无度，不问朝政，所以一直患病。　　二年（前193），楚元王刘交、齐悼惠王刘肥都前来朝见。十月，有一天惠帝与齐王在太后面前宴饮，惠帝因为齐王是兄长，就按家人的礼节，请他坐上座。太后见此大怒，就叫人倒了两杯毒酒放在齐王面前，让齐王起来向他献酒祝寿。齐王站了起来，惠帝也站起来，端起酒杯要一起向太后祝酒。太后害怕了，急忙站起来倒掉了惠帝手里的酒。齐王觉得奇怪，因而没敢喝这杯酒，就装醉离开了席座。事后打听，才知道那是毒酒，齐王心里很害怕，认为不能从长安脱身了，非常焦虑。齐国的内史向齐王献策说：“太后只有惠帝和鲁元公主两个孩子。如今大王您拥有七十多座城，而公主只享食几座城的贡赋。大王如果能把一个郡的封地献给太后，来作公主的汤沐邑，供公主收取赋税，太后一定高兴，您也就不必再担心了。”于是齐王就献上城阳郡，为了讨好太后，并违背常礼尊自己的异母妹鲁元公主为王太后。吕后很高兴，就接受了。于是在齐王在京的官邸摆设酒宴，欢饮一番，酒宴结束，就让齐王返回封地了。三年（前192），开始修筑长安城，四年（前191），完成了一半，五年（前190）、六年（前189）全部竣工。诸侯都来京聚会，十月入朝祝贺。　　七年（前188）秋季八月戊寅日，惠帝逝世。发丧时，太后只是干哭，没有眼泪。留侯张良的儿子张辟强任侍中，只有十五岁，对丞相陈平说：“太后只有惠帝这一个儿子，如今去世了，太后只干哭而不悲通，您知道这里的原因吗？”陈平问：“是什么原因？”辟强说：“皇帝没有成年的儿子，太后顾忌的是你们这班老臣。如果您请求太后拜吕台、吕产、吕禄为将军，统领两宫卫队南北二军，并请吕家的人都进入宫中，在朝廷里掌握重权，这样太后就会安心，你们这些老臣也就能够幸免于祸了。”丞相照张辟强的办法做了。太后很满意，才哭得哀痛起来。吕氏家族掌握朝廷大权就是从这时开始的。于是大赦天下。九月辛丑日，安葬惠帝。太子即位做了皇帝，到高祖庙举行典礼，向高祖禀告。少帝元年（前187），朝廷号令完全出自太后。　　太后行使皇帝的职权之后，召集大臣商议，打算立诸吕为王。先问右丞相王陵。王陵说：“高帝曾杀白马，和大臣们立下誓约，‘不是刘氏子弟却称王的，天下共同诛讨他’。现在如果封吕氏为王，是违背誓约的。”太后很不高兴。又问右丞相陈平和绛侯周勃。周勃等人回答：“高帝平定天下，封刘氏子弟为王；如今太后代行天子之职，封吕氏诸兄弟为王，没有什么不可以的。”太后大喜，于是退朝。王陵责备陈平、周勃：“当初跟高帝歃（shà，厦）血盟誓时，你们难道不在吗？如今高帝去世，太后是临朝执政的女主，却要封吕氏子弟为王。你们竟然纵容她的私欲，迎合她的心愿，违背与高帝立下的誓约，将来还有什么脸面见高帝于黄泉之下呢？”陈平、周勃说：“如今在朝廷上当面反驳，据理诤谏，我们比不上您；而要保全大汉天下，安定刘氏后代，您又比不上我们。”王陵无话可答。十一月，太后想要罢免王陵，就拜他为皇帝的太傅，夺了他右丞相的实权。王陵于是就称病免职回乡了。吕后任命左丞相陈平做了右丞相，任命辟阳侯审食其（yìjī，异基）做了左丞相。但左丞相审食其不管应该做的事情，而只是监督宫中事务，就象郎中令一样。审食其原先做过太后的舍人，曾随太后落入项羽军中，所以很得宠信。常常决断大事，朝廷大臣处理政务都要通过他来决定。吕后又追尊郦侯吕台的父亲吕泽为悼武王，想由此开头来封诸吕为王。　　四月，太后准备封诸吕为侯，就先封高祖的功臣郎中令冯无择为博城侯。鲁元公主去世，赐给她谥号为鲁元太后，封她的儿子张偃为鲁王。鲁王的父亲就是宣平侯张敖。封齐悼惠王刘肥的儿子刘章为朱虚侯。把吕禄的女儿嫁给他做妻子。封齐国的丞相齐寿为平定侯。封少府阳成延为梧侯。接着就封吕种为沛侯，吕平为扶柳侯，张买为南宫侯。　　太后又想封诸吕为王，先封惠帝后宫妃子所生的儿子刘强为淮阳王，刘不疑为常山王，刘山为襄阳侯，刘朝为轵（zhǐ）侯，刘武为壶关侯。太后暗示大臣们，大臣们就请求封郦侯吕台为吕王，太后同意了。建成侯吕释之去世，继承侯位的儿子因为有罪而被废除，就封他的弟弟吕禄为胡陵侯，做为继承建成侯的后代。二年（前186），常山王刘不疑去世，封他的弟弟襄阳侯刘山为常山王，改名刘义。十一月，吕王吕台去世，谥为肃王，他的儿子吕嘉接替为王。三年（前185），无可记之事。四年（前184），吕后封她的妹妹吕嬃（Xū）为临光侯，封吕他为俞侯，吕更始为赘其侯，吕忿为吕城侯，又封了诸侯王的丞相五人为侯。　　宣平侯张敖的女儿做孝惠皇后时，没有儿子，假装怀孕，抱来后宫妃子生的孩子说成是自己所生，杀掉他的母亲，立他为太子。惠帝去世，太子立为皇帝。后来皇帝略微懂事时，偶然听说自己的母亲已经死了，自己并不是皇后的亲生儿子，就口出怨言，说：“皇后怎么能杀死我的母亲却把我说成是自己的儿子呢？我现在还小，等长大成人后我就造反。”太后听说这件事以后很担心，害怕他将来作乱，就把他囚禁在永巷宫中，声称皇帝得了重病，左右大臣谁也见不到他。太后说：“凡是拥有天下掌握万民命运的人，应该象上天覆盖大地、象大地容载万物一样抚育百姓，皇帝有欢悦爱护之心安抚百姓，百姓就会欢欣喜悦地侍奉皇帝，这样上下欢悦欣喜的感情相通，天下就能太平。如今皇帝病重，经久不愈，以致神志昏乱失常，不能继承帝位供奉宗庙祭祀了，因此不能把天下托付给他，应该找人代替他。”群臣都叩头说：“皇太后为天下百姓谋划，对安定宗庙社稷的思虑极为深远，我们恭敬地叩头听命。”于是废了皇帝的帝位，太后又在暗中杀了他。五月丙辰日，立常山王刘义为皇帝，改名叫刘弘。没有改称元年，是因为太后在行使着皇帝的职权。改封轵侯刘朝为常山王。设置太尉的官职，绛侯周勃当了太尉。五年（前183）八月，淮阳王刘强去世，封他的弟弟壶关侯刘武为淮阳王。六年（前182）十月，太后说吕王吕嘉行为骄横跋扈，废掉了他，封肃王吕台的弟弟吕产为吕王。夏天，大赦天下。封齐悼王的儿子刘兴居为东牟侯。　　七年（前181）正月，太后召赵王刘友进京。刘友的王后是吕氏的女儿，刘友不喜欢她，而喜欢其他的姬妾，这个吕氏的女儿很嫉妒，恼怒之下离开了家，到吕后面前诽谤刘友，诬告刘友曾经说：“吕氏怎么能封王！太后百年之后，我一定收拾他们。”太后大怒，因此召赵王来京。赵王到京后，太后把他安置在官邸里却不接见，并派护卫队围守着，不给他饭吃。赵王的臣下有偷着给送饭的，就被抓起来问罪。赵王饿极了，就作了一首歌，唱道：　　“诸吕朝中掌大权啊，刘氏江山实已危；以势胁迫诸王侯啊，强行嫁女为我妃。　　我妃嫉妒其无比啊，竟然谗言诬我罪；谗女害人又乱国啊，不料皇上也蒙昧。　　并非是我无忠臣啊，如今失国为哪般？途中自尽弃荒野啊，曲直是非天能辨。　　可惜悔之时已晚啊，宁愿及早入黄泉。为王却将饥饿死啊，无声无息有谁怜！　　吕氏天理已灭绝啊，祈望苍天报仇冤。”　　丁丑日，赵王被囚禁饿死，按照平民的葬礼，把他埋在长安百姓坟墓的旁边。　　己丑日，发生日食，白昼变得跟黑夜一样。太后非常嫌恶，心中闷闷不乐，对左右的人说：“这是因为我啊。”　　二月，改封梁王刘恢为赵王。吕王吕产被改封为梁王，但梁王没有去封国，留在朝廷担任皇帝的太傅。封皇帝之子平昌侯刘太为吕王。把梁国改为吕国。原来的吕国改名为济川国。太后的妹妹吕嬃有个女儿嫁给营陵侯刘泽为妻，刘泽当时担任大将军。太后封诸吕为王，怕自己死后刘泽作乱，于是就封刘泽为琅邪王，想借此来稳住他的心。　　梁王刘恢改封为赵王后，心里不高兴。太后就把吕产的女儿嫁给赵王做王后。王后的随从官员都是吕家的人，专揽大权，暗中监视赵王，赵王不能随意行动。赵王有个宠爱的姬妾，王后派人用毒酒毒死了她。赵王于是作诗四章，让乐工们歌唱。赵王内心悲痛，六月就自杀了。太后知道这件事后，认为赵王为了女人就连祭祀宗庙的礼仪都不要了，于是废除了他后代的王位继承权。　　宣平侯张敖去世，封他的儿子张偃为鲁王，赐给张敖鲁元王的谥号。　　秋天，太后派使者去告诉代王刘恒，想要改封他为赵王。代王辞谢了，表示愿意守卫边远的代国。　　太傅吕产，丞相陈平等人向太后进言说，武信侯吕禄是上侯，在列侯中排在第一位，请求立他为赵王，太后同意，并追尊吕禄的父亲康侯为赵昭王。九月，燕灵王刘建去世，他有一个姬妾生的儿子，太后派人把他杀了，燕灵王绝了后代，封国被废除。八年（前180）十月，立吕肃王的儿子东平侯吕通为燕王，封吕通的弟弟吕庄为东平侯。　　三月中旬，吕后举行了除灾求福的祓（fú）祭，回来路过轵道亭时，看到一个东西象是一条黑狗，一下子撞到她的腋下，忽然又不见了。让人占卜，说是赵王刘如意在作祟，从此太后得了腋下疼痛的病。　　吕后因为外孙鲁元王张偃年幼，又老早就死了父母，孤单势弱，就封了张敖前妾所生的两个儿子，封张侈为新都侯，张寿为乐昌侯，来辅佐鲁元王张偃。又封中大谒者张释为建陵侯，封吕荣为祝兹侯。宫中宦官担任令和丞的都封为关内侯，食邑五百户。　　七月中旬，吕后病重，就任命赵王吕禄为上将军，统领北军；吕王吕产统领南军。吕后告诫吕禄、吕产说：“高帝平定天下后，曾和大臣们立下誓约，说：‘不是刘氏子弟却称王的，天下共同诛讨他。’现在吕家的人被封为王，大臣们心中不平。我如果死了，皇帝年轻，大臣们恐怕要作乱。你们一定要握住兵仅，保卫皇宫，千万不要为我送丧，不要被人所制服。”辛巳日，吕后去世，留下诏书，赐给每个诸侯王黄金千斤。将、相、列侯、郎、吏等都按位次赐给黄金。大赦天下。以吕王吕产为相国，以吕禄的女儿为皇后。　　吕后安葬以后，用左丞相审食其做皇帝的太傅。　　朱虚侯刘章有气概有勇力，东牟侯刘兴居是他的弟弟，二人都是齐哀王刘襄的弟弟，住在长安。当时，诸吕独揽大权，打算作乱，但他们畏惧高帝的老臣周勃、灌婴等人。未敢妄动。朱虚侯的妻子是吕禄的女儿，因此他私下里了解到诸吕的阴谋。他怕自己被杀，就暗中派人告诉他的哥哥齐王刘襄，想要让他发兵西进，诛杀诸吕自立为帝。朱虚侯自己准备在朝廷里联合大臣们作内应。齐王准备发兵，他的丞相不服从。八月丙午日，齐王准备派人诛杀丞相，丞相召（shào）平于是造反，发动军队想要围攻齐王，齐王因此杀了丞相，接着发兵东进，诈夺了琅邪王刘泽的军队，然后把两支军队一并率领起来向西进发。此事在《齐悼惠王世家》中有记载。　　齐王写信给各诸侯王说：“高帝平定天下后，分封子弟为王，悼惠王被封在齐国。悼惠王去世，孝惠帝派留侯张良立我为齐王。孝惠帝逝世，吕后执掌朝权，年事已高，听信诸吕，擅自废掉和改立皇帝，又接连杀了刘如意、刘友、刘恢三个赵王，废除了梁、赵、燕三个刘氏封国，用来封诸吕为王，还把齐国一分为四。虽有忠臣进言劝谏，可是吕后昏乱糊涂听不进去。如今吕后逝世，而皇帝还很年轻，不能治理天下，本应依靠大臣、诸侯。可是诸吕却随意自己提高官职，聚兵率卒，增加威势，胁迫列侯、忠臣，假传皇帝之命，向天下发号施令，刘氏宗庙因此濒临危境。我率兵入京就是去杀不该为王的人。”朝廷知道后，相国吕产等人就派颍阴侯灌婴率军迎击齐王。灌婴到了荥阳，和将士们商议说：“诸吕在关中握有兵权，图谋颠覆刘氏，自立为帝。如果我打败齐国回去报告，就是给吕氏增了实力。”于是把军队留驻在荥阳，派使者告知齐王及各国诸侯，要和他们联合起来，等待吕氏发动变乱，再共同诛灭他们。齐王得知灌婴的打算以后，就带兵返回齐国的西部边界，等待按照约定行事。　　吕禄、吕产想要在关中发动叛乱，但在朝廷他们害怕绛侯、朱虚侯等人，在外面他们害怕齐、楚二国的军队，又担心灌婴背叛他们，所以想等到灌婴的军队与齐王交战后再起事，所以犹豫不决。当时，名义上是少帝弟弟的济川王刘太、淮阳王刘武、常山王刘朝，以及吕后的外孙鲁元王张偃，都因年纪太小未去封国，住在长安。赵王吕禄、梁王吕产各自带兵分居南北二军，他们都是吕家的人，列侯群臣都感到不能自保性命。　　太尉绛侯周勃不能进入军营主持军务。曲周侯郦商年老有病，他儿子郦寄和吕禄要好。绛侯就跟丞相陈平商议，派人挟持郦商，让他儿子郦寄前去骗吕禄，说：“高帝和吕后共同平定天下，刘氏被立为王的九人，吕氏被立为王的三人，都是大臣们商议过的，此事已通告诸侯，诸侯都认为这样合适。现在太后逝世，皇帝年轻，而您佩带着赵王的印，不赶快回去守卫封国，却担任上将军，率军留驻此地，让大臣诸侯们产生怀疑。您为什么不把将印归还给朝廷，把兵权交还给太尉呢？也请梁王归还相国印，和大臣们订立盟约，返回封国，这样齐国必然罢兵，大臣也能心里踏实，您也可以在千里封国高忱无忧地做您的王了，这是有利于子孙万代的好事呀。”吕禄果然相信了他的建议，准备交出将军印，把军队归还给太尉。派人把这事告知吕产和吕家的老人们，这些人有的认为可行，有的认为不行，意见不一，迟疑未决。吕禄信任郦寄，常和他一起出外游玩射猎。一次经过他姑姑吕嬃的府第，吕嬃大发雷霆，说：“你做为将军却放弃军队，我们吕家如今就要没有容身之地了。”接着把所有的珠玉宝器都抛撒到庭堂下面，说：“再也不替别人保存这些玩艺儿了。”　　左丞相审食其被免职。　　八月庚申日早晨，代理御史大夫职务的平阳侯曹窋（zhú），会见相国吕产商议事情。郎中令贾寿从齐国出使回来，趁机责备吕产说：“大王早不到封国去，现在即使想走，还走得成吗？”接着就把灌婴与齐楚联合，准备诛灭诸吕的事情全部告诉了吕产，催促吕产赶快进宫。平阳侯曹窋大体听到了这些话，立即跑去告诉丞相陈平和太尉周勃。太尉想进入守卫吕后所居长乐宫的北军，因为长乐宫原为吕后所居，是诸吕的活动中心，而且北军力量较强，所以没能进去。襄平侯纪通主管符节，太尉就让纪通拿着符节，假传皇帝诏令，要让太尉进入北军。太尉又派郦寄和典客刘揭先去劝说吕禄：“皇帝命太尉主管北军，让您回封国去，还是赶快交出将军印，及早离开，不然，大祸将要临头了。”吕禄认为郦寄不会欺骗他，就解下将军印交给典客，把兵权交给太尉。太尉拿着将印进入军门，向军中发令：“拥护吕氏的袒露右臂，拥护刘氏的袒露左臂。”军中将士都袒露左臂拥护刘氏。太尉还没到北军时，吕禄已经交出将军印离开了军营，太尉于是统率了北军。　　然而南军还在吕氏手里。平阳侯曹窋听到吕产的阴谋，告诉了丞相陈平以后，陈平就召来朱虚侯刘章，让他协助太尉。太尉派朱虚侯监守军门，命令曹窋通知未央宫卫尉：“不准放相国吕产进入殿门。”吕产不知道吕禄已离开北军，就进入未央宫，准备作乱，但进不了殿门，在那里走来走去，徘徊不定。平阳侯担心不能取胜，就驱马跑去告诉太尉。太尉也担心不能战胜诸吕，没敢明言杀掉吕产，就派朱虚侯进宫，对他说：“赶快进宫保卫皇帝。”朱虚侯要求派兵，太尉给他一千多人。朱虚侯进入未央宫，就看见吕产已在宫中。到吃晚饭的时分，朱虚侯向吕产发起攻击，吕产逃走。这时狂风大作，吕产的随从官员一片混乱，无人再敢抵抗。朱虚侯率兵追赶吕产，追到郎中令官府的厕所中把他杀掉了。　　朱虚侯刘章杀掉吕产后，皇帝派谒者手持符节前来慰劳。朱虚侯想夺过符节，谒者不肯。刘章就跟谒者同乘一辆车，凭借谒者手中的符节在宫中驱马奔跑，斩了长乐宫的卫尉吕更始。然后跑回北军向太尉报告。太尉起身向朱虚侯拜贺说：“我们所担心的就是这个吕产，因为他身为相国，又掌握着南军，现在已经把他杀了，刘氏天下就安定了。”随即派人分头把吕氏的男男女女全部抓来，不分老少，一律斩杀。辛酉日，将吕禄抓获斩首，用鞭杖竹板打死吕嬃。又派人杀了燕王吕通，并废掉了鲁王张偃。壬戌日，恢复了皇帝太傅审食其左丞相的职务。戊辰日，改封济川王刘太为梁王，立赵幽王的儿子刘遂为赵王。派朱虚侯把诛杀诸吕的事情通知齐王，让他收兵。灌婴也从荥阳收兵回京。　　朝廷的大臣们聚在一起秘密商量，说：“少帝以及吕（梁）王刘太、淮阳王刘武、常山王刘朝，都不是孝惠皇帝真正的儿子。吕后用欺诈的手段，把别人的儿子抱来谎称是惠帝的儿子，杀掉他们的生母，养在后宫，让孝惠皇帝把他们认做自己的儿子，立为继承人，或者封为诸侯王，来加强吕氏的势力。如今已经把诸吕全部消灭了，却还留着吕氏所立的人，那么等到他们长大后掌了权，我们这班人就要被灭族了。不如现在挑选一位最贤明的诸侯王，立他为皇帝。”有人说：“齐悼惠王刘肥是高帝的长子，现在他的嫡子为齐王，从根儿上说，是高帝的嫡长孙，可以立为皇帝。”但大臣们都说：“吕氏就凭着他们是外戚而专权作恶，几乎毁了刘氏天下，害了功臣贤良。现在齐王外祖母家姓驷，驷钧是个恶人，如果立齐王为皇帝，那就又成了吕氏的天下。”大家考虑立淮南王刘长，又觉得他太年轻，外祖母家也很凶恶。最后大家说：“代王刘恒是现今高帝儿子中最大的了，为人仁孝宽厚。太后薄夫人娘家谨慎善良。再说，拥立最大的儿子本来就名正言顺，而且代王又以仁爱孝顺闻名天下，立他为帝合适。”于是就一起暗中派使者去召代王进京。代王派人推辞。使者再次前来，代王才带着随从人员乘坐六辆驿车进京。闰九月月末己酉日到达长安，住在代王的官邸。大臣们都前去拜见，把天子的玉玺奉上，一起尊立代王为天子。代王一再推辞，群臣坚决请求，最后才答应了。　　车牟侯刘兴居说：“诛灭吕氏我没有功劳，请让我去清理皇宫。”就和太仆汝阴侯滕公夏侯婴一起入宫，到少帝面前说：“你不是刘氏的后代，不应立为皇帝。”接着回过头来挥手让少帝左右的卫士放下兵器离去。有几个人不肯，宦者令张泽说明情况，他们也把兵器放下了。滕公于是叫来车子，载着少帝出了皇宫。少帝问：“你们要带我到哪儿去？”滕公说：“出去找个地方住。”就让他住在少府。然后侍侯着天子乘坐的法驾，到代王官邸迎接代王，向他报告：“宫室已经仔细清理完毕。”代王当天晚上进入未央宫。有十名谒者持戟守卫端门，喝问：“天子还在，你是什么人要进去？”代王叫过太尉，让太尉去向他们说明，这十个谒者就都放下兵器离去了。代王于是进入内廷执掌朝政。当天夜里，主管部门的官员分头到梁王、淮阳王、常山王和少帝的住处把他们杀死。　　代王被立为天子，在位二十三年去世，谥号是孝文皇帝。　　太史公说：孝惠皇帝和吕后在位的时候，百姓得以脱离战国时期的苦难，君臣都想通过无为而治来休养生息，所以惠帝垂衣拱手，安闲无为，吕后以女主身份代行皇帝职权，施政不出门户，天下却也安然无事。刑罪很少使用，犯罪的人也很少。百姓专心从事农耕，衣食富足起来了。', '[{"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3d8f534825deea03166", "shortContent": "吕后，名雉，字娥姁。汉高祖的开国皇后，史称高后。《史记》于《高祖本纪》后置《吕太后本纪》，而以惠帝朝事附入（《汉书》高后、惠帝分《纪》）。《史记》、《汉书》为吕后立《纪》，后世议论纷纭不已（如刘勰、黄东发即反对为“女帝”立《纪》）。盖惠帝君道不行，政出吕后；二少帝年幼，吕后临朝称制，立《纪》只是记实，“本纪者记其政之自出”乃《史记》之义例。故郑樵《通志》说：“若吕后之《纪》不立，正朔所系何朝？”“...", "authors": [], "pressName": "上海辞书出版社"}]', '太史公自序：“惠之早殒，诸吕不台。崇强禄产，诸侯谋之。杀隐幽友，大臣洞疑，遂及宗祸，作《吕太后本纪》第九。”
司马贞曰：“吕太后以女主临朝，自孝惠崩后少帝立而始称制，正合附‘惠纪’而论之；不然或别为吕后本纪，岂得全没孝惠，而独称‘吕后本纪’？合依班氏分为二纪焉。”——《史记索隐》
郭嵩焘曰：“本纪中有言‘孝惠日饮，为淫乐，不听政，’是惠帝初立后，吕后专政自恣，政由己出，固已久矣，史公不为惠帝立纪，以纪实也。”——《史记札记》
凌约言曰：“一篇关键，总在王诸吕、诛诸吕上著力，以汉室兴替所关也，故史公乃见其大者。”——《史记评林》
徐时栋曰：“天下号令在某人，则某人为‘本纪’，此史公例也。故《高祖本纪》之前，有《项羽本纪》；高祖以后，不立《孝惠皇帝本纪》，而独立《吕后本纪》故以本纪为纪实，而非争名分之地也。此后无人能具此识力，亦无人敢循此史例矣。”——《烟屿楼读书志》
泷川资言曰：“史公舍惠帝而纪吕后，犹舍楚怀而纪项羽，盖以政令之后出也。”——《史记全注考证》
宋濂曰：“高祖知吕后与戚夫人有隙，然终不杀者，以孝惠第而不能制诸大臣，故委戚氏不顾，为天下计也。”——《史记评注》引
吕祖谦曰：“存高后为有功臣，有功臣为有吕后，此高祖深虑也。”——《大事记》
吴见思曰：“一篇匆忙文字，借文帝雍容揖逊以为曲终雅奏，令人神怡。”——《史记论文》
牛运震曰：“叙诛诸吕，头绪最繁多，而点逗极为明晰；事最匆遽，而叙次最安闲；总于转键安顿见笔法妙处。”——《史记评注》
黄震曰：“吕后欲王诸吕，王陵力争，可谓社稷臣矣。平，勃阿意王之，勃岁卒诛诸吕、安刘氏，然矣功不赎罪；若平又何以赎之，而反受赏邑三千户，金二十斤耶？平平生教帝诈，无益成败之数；天下既定，误帝伪游，叛者九走，卒死于兵；今复负帝身后如此，平真汉之罪人也。”——《黄氏日钞》
赵翼曰：“吕后当高祖临危时问萧相国后孰可代者，是故以安国家为急也。　　‘孝惠既立，政由母氏，其所用曹参，王陵，陈平，周勃等，无一非高帝注意安刘之人，是惟恐孝惠之不能守业也。　　‘所生惟孝惠及鲁元公主，其他皆诸姬子，使孝惠而在，则方与孝惠，图治计长久，观于高祖欲废太子时，后迫留侯画策，至跪谢周昌之廷诤，则其母子之间可知也。　　‘迨孝惠崩，而所取后宫子立为帝者，又以怨怼而废，于是己之于孙无在者，则与其使诸姬子据权势以凌吕氏，不如先张吕氏以久其权。　　‘故孝惠时未尝王诸吕，王诸吕乃在孝惠崩后，此则后之私心短见。　　‘盖嫉妒者妇人之常情也，然其所最妒亦只戚夫人母子，以其先宠幸时几至于夺嫡，故高帝崩后击杀之。　　‘此外诸姬子如文帝封于代，则听其母薄太后随之；淮南王长无母，依吕氏以成立，则始终无恙；齐悼惠王以孝惠庶兄失后意，后怒欲鸩之，已而悼惠献城阳郡为鲁元汤沐邑，即复待之如初；其子朱虚侯章入侍宴，请以军法行酒，斩诸吕逃酒者一人，后亦未尝加罪也。　　‘赵王友之幽死，梁王恢之自杀，则皆以妃吕氏不谐之故。　　‘然赵王友妃吕产女，梁王妃亦诸吕女，又少帝后及朱虚侯皆吕禄女，吕氏有女不以他适，而必以配诸刘，正见后之欲使刘吕常相亲也。”——《廿二史札记》
又引黄震曰：“按吕后杀其子孙，而王母家，使母家无少长皆斩，而身亦死于祟祸。史迁备著之，为万世女后戒。”', 'indent', 1525198186, '5ae83ce22f301e003df86ebc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637449, '史记 · 十二本纪 · 孝文本纪', NULL, 1, 139, 0, 1, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%9D%E6%96%87%E6%9C%AC%E7%BA%AA/2391270?fr=aladdin', '', '孝文皇帝，高祖中子也。高祖十一年春，已破陈豨军，定代地，立为代王，都中都。太后薄氏子。即位十七年，高后八年七月，高后崩。九月，诸吕吕产等欲为乱，以危刘氏，大臣共诛之，谋召立代王，事在吕后语中。
丞相陈平、太尉周勃等使人迎代王。代王问左右郎中令张武等。张武等议曰：“汉大臣皆故高帝时大将，习兵，多谋诈，此其属意非止此也，特畏高帝、吕太后威耳。今已诛诸吕，新啑血京师，此以迎大王为名，实不可信。愿大王称疾毋往，以观其变。”中尉宋昌进曰：“群臣之议皆非也。夫秦失其政，诸侯豪桀并起，人人自以为得之者以万数，然卒践天子之位者，刘氏也，天下绝望，一矣。高帝封王子弟，地犬牙相制，此所谓盘石之宗也，天下服其彊，二矣。汉兴，除秦苛政，约法令，施德惠，人人自安，难动摇，三矣。夫以吕太后之严，立诸吕为三王，擅权专制，然而太尉以一节入北军，一呼士皆左袒，为刘氏，叛诸吕，卒以灭之。此乃天授，非人力也。今大臣虽欲为变，百姓弗为使，其党宁能专一邪？方今内有朱虚、东牟之亲，外畏吴、楚、淮南、琅邪、齐、代之彊。方今高帝子独淮南王与大王，大王又长，贤圣仁孝，闻于天下，故大臣因天下之心而欲迎立大王，大王勿疑也。”代王报太后计之，犹与未定。卜之龟，卦兆得大横。占曰：“大横庚庚，余为天王，夏启以光。”代王曰：“寡人固已为王矣，又何王？”卜人曰：“所谓天王者乃天子。”于是代王乃遣太后弟薄昭往见绛侯，绛侯等具为昭言所以迎立王意。薄昭还报曰：“信矣，毋可疑者。”代王乃笑谓宋昌曰：“果如公言。”乃命宋昌参乘，张武等六人乘传诣长安。至高陵休止，而使宋昌先驰之长安观变。
昌至渭桥，丞相以下皆迎。宋昌还报。代王驰至渭桥，群臣拜谒称臣。代王下车拜。太尉勃进曰：“愿请闲言。”宋昌曰：“所言公，公言之。所言私，王者不受私。”太尉乃跪上天子玺符。代王谢曰：“至代邸而议之。”遂驰入代邸。群臣从至。丞相陈平、太尉周勃、大将军陈武、御史大夫张苍、宗正刘郢、朱虚侯刘章、东牟侯刘兴居、典客刘揭皆再拜言曰：“子弘等皆非孝惠帝子，不当奉宗庙。臣谨请（与）阴安侯列侯顷王后与琅邪王、宗室、大臣、列侯、吏二千石议曰：‘大王高帝长子，宜为高帝嗣。’愿大王即天子位。”代王曰：“奉高帝宗庙，重事也。寡人不佞，不足以称宗庙。愿请楚王计宜者，寡人不敢当。”群臣皆伏固请。代王西乡让者三，南乡让者再。丞相平等皆曰：“臣伏计之，大王奉高帝宗庙最宜称，虽天下诸侯万民以为宜。臣等为宗庙社稷计，不敢忽。愿大王幸听臣等。臣谨奉天子玺符再拜上。”代王曰：“宗室将相王列侯以为莫宜寡人，寡人不敢辞。”遂即天子位。
群臣以礼次侍。乃使太仆婴与东牟侯兴居清宫，奉天子法驾，迎于代邸。皇帝即日夕入未央宫。乃夜拜宋昌为卫将军，镇抚南北军。以张武为郎中令，行殿中。还坐前殿。于是夜下诏书曰：“闲者诸吕用事擅权，谋为大逆，欲以危刘氏宗庙，赖将相列侯宗室大臣诛之，皆伏其辜。朕初即位，其赦天下，赐民爵一级，女子百户牛酒，酺五日。”
孝文皇帝元年十月庚戌，徙立故琅邪王为燕王。
辛亥，皇帝即阼，谒高庙。右丞相平徙为左丞相，太尉勃为右丞相，大将军灌婴为太尉。诸吕所夺齐楚故地，皆复与之。
壬子，遣车骑将军薄昭迎皇太后于代。皇帝曰：“吕产自置为相国，吕禄为上将军，擅矫遣灌将军婴将兵击齐，欲代刘氏，婴留荥阳弗击，与诸侯合谋以诛吕氏。吕产欲为不善，丞相陈平与太尉周勃谋夺吕产等军。朱虚侯刘章首先捕吕产等。太尉身率襄平侯通持节承诏入北军。典客刘揭身夺赵王吕禄印。益封太尉勃万户，赐金五千斤。丞相陈平、灌将军婴邑各三千户，金二千斤。朱虚侯刘章、襄平侯通、东牟侯刘兴居邑各二千户，金千斤。封典客揭为阳信侯，赐金千斤。”
十二月，上曰：“法者，治之正也，所以禁暴而率善人也。今犯法已论，而使毋罪之父母妻子同产坐之，及为收帑，朕甚不取。其议之。”有司皆曰：“民不能自治，故为法以禁之。相坐坐收，所以累其心，使重犯法，所从来远矣。如故便。”上曰：“朕闻法正则民悫，罪当则民从。且夫牧民而导之善者，吏也。其既不能导，又以不正之法罪之，是反害于民为暴者也。何以禁之？朕未见其便，其孰计之。”有司皆曰：“陛下加大惠，德甚盛，非臣等所及也。请奉诏书，除收帑诸相坐律令。”
正月，有司言曰：“蚤建太子，所以尊宗庙。请立太子。”上曰：“朕既不德，上帝神明未歆享，天下人民未有嗛志。今纵不能博求天下贤圣有德之人而禅天下焉，而曰豫建太子，是重吾不德也。谓天下何？其安之。”有司曰：“豫建太子，所以重宗庙社稷，不忘天下也。”上曰：“楚王，季父也，春秋高，阅天下之义理多矣，明于国家之大体。吴王于朕，兄也，惠仁以好德。淮南王，弟也，秉德以陪朕。岂为不豫哉！诸侯王宗室昆弟有功臣，多贤及有德义者，若举有德以陪朕之不能终，是社稷之灵，天下之福也。今不选举焉，而曰必子，人其以朕为忘贤有德者而专于子，非所以忧天下也。朕甚不取也。”有司皆固请曰：“古者殷周有国，治安皆千馀岁，古之有天下者莫长焉，用此道也。立嗣必子，所从来远矣。高帝亲率士大夫，始平天下，建诸侯，为帝者太祖。诸侯王及列侯始受国者皆亦为其国祖。子孙继嗣，世世弗绝，天下之大义也，故高帝设之以抚海内。今释宜建而更选于诸侯及宗室，非高帝之志也。更议不宜。子某最长，纯厚慈仁，请建以为太子。”上乃许之。因赐天下民当代父后者爵各一级。封将军薄昭为轵侯。
三月，有司请立皇后。薄太后曰：“诸侯皆同姓，立太子母为皇后。”皇后姓窦氏。上为立后故，赐天下鳏寡孤独穷困及年八十已上孤儿九岁已下布帛米肉各有数。上从代来，初即位，施德惠天下，填抚诸侯四夷皆洽欢，乃循从代来功臣。上曰：“方大臣之诛诸吕迎朕，朕狐疑，皆止朕，唯中尉宋昌劝朕，朕以得保奉宗庙。已尊昌为卫将军，其封昌为壮武侯。诸从朕六人，官皆至九卿。”
上曰：“列侯从高帝入蜀、汉中者六十八人皆益封各三百户，故吏二千石以上从高帝颍川守尊等十人食邑六百户，淮阳守申徒嘉等十人五百户，卫尉定等十人四百户。封淮南王舅父赵兼为周阳侯，齐王舅父驷钧为清郭侯。”秋，封故常山丞相蔡兼为樊侯。
人或说右丞相曰：“君本诛诸吕，迎代王，今又矜其功，受上赏，处尊位，祸且及身。”右丞相勃乃谢病免罢，左丞相平专为丞相。
二年十月，丞相平卒，复以绛侯勃为丞相。上曰：“朕闻古者诸侯建国千余（岁），各守其地，以时入贡，民不劳苦，上下欢欣，靡有遗德。今列侯多居长安，邑远，吏卒给输费苦，而列侯亦无由教驯其民。其令列侯之国，为吏及诏所止者，遣太子。”
十一月晦，日有食之。十二月望，日又食。上曰：“朕闻之，天生蒸民，为之置君以养治之。人主不德，布政不均，则天示之以菑，以诫不治。乃十一月晦，日有食之，适见于天，菑孰大焉！朕获保宗庙，以微眇之身托于兆民君王之上，天下治乱，在朕一人，唯二三执政犹吾股肱也。朕下不能理育群生，上以累三光之明，其不德大矣。令至，其悉思朕之过失，及知见思之所不及，丐以告朕。及举贤良方正能直言极谏者，以匡朕之不逮。因各饬其任职，务省繇费以便民。朕既不能远德，故憪然念外人之有非，是以设备未息。今纵不能罢边屯戍，而又饬兵厚卫，其罢卫将军军。太仆见马遗财足，馀皆以给传置。”
正月，上曰：“农，天下之本，其开籍田，朕亲率耕，以给宗庙粢盛。”
三月，有司请立皇子为诸侯王。上曰：“赵幽王幽死，朕甚怜之，已立其长子遂为赵王。遂弟辟彊及齐悼惠王子朱虚侯章、东牟侯兴居有功，可王。”乃立赵幽王少子辟彊为河间王，以齐剧郡立朱虚侯为城阳王，立东牟侯为济北王，皇子武为代王，子参为太原王，子揖为梁王。
上曰：“古之治天下，朝有进善之旌，诽谤之木，所以通治道而来谏者。今法有诽谤妖言之罪，是使众臣不敢尽情，而上无由闻过失也。将何以来远方之贤良？其除之。民或祝诅上以相约结而后相谩，吏以为大逆，其有他言，而吏又以为诽谤。此细民之愚无知抵死，朕甚不取。自今以来，有犯此者勿听治。”
九月，初与郡国守相为铜虎符、竹使符。
三年十月丁酉晦，日有食之。十一月，上曰：“前日（计）[诏]遣列侯之国，或辞未行。丞相朕之所重，其为朕率列侯之国。”绛侯勃免丞相就国，以太尉颍阴侯婴为丞相。罢太尉官，属丞相。四月，城阳王章薨。淮南王长与从者魏敬杀辟阳侯审食其。
五月，匈奴入北地，居河南为寇。帝初幸甘泉。六月，帝曰：“汉与匈奴约为昆弟，毋使害边境，所以输遗匈奴甚厚。今右贤王离其国，将众居河南降地，非常故，往来近塞，捕杀吏卒，驱保塞蛮夷，令不得居其故，陵轹边吏，入盗，甚敖无道，非约也。其发边吏骑八万五千诣高奴，遣丞相颍阴侯灌婴击匈奴。”匈奴去，发中尉材官属卫将军军长安。
辛卯，帝自甘泉之高奴，因幸太原，见故群臣，皆赐之。举功行赏，诸民里赐牛酒。复晋阳中都民三岁。留游太原十馀日。
济北王兴居闻帝之代，欲往击胡，乃反，发兵欲袭荥阳。于是诏罢丞相兵，遣棘蒲侯陈武为大将军，将十万往击之。祁侯贺为将军，军荥阳。七月辛亥，帝自太原至长安。乃诏有司曰：「济北王背德反上，诖误吏民，为大逆。济北吏民兵未至先自定，及以军地邑降者，皆赦之，复官爵。与王兴居去来，亦赦之。」八月，破济北军，虏其王。赦济北诸吏民与王反者。[1]
六年，有司言淮南王长废先帝法，不听天子诏，居处毋度，出入拟于天子，擅为法令，与棘蒲侯太子奇谋反，遣人使闽越及匈奴，发其兵，欲以危宗庙社稷。群臣议，皆曰「长当弃市」帝不忍致法于王，赦其罪，废勿王。群臣请处王蜀严道、邛都，帝许之。长未到处所，行病死，上怜之。后十六年，追尊淮南王长谥为厉王，立其子三人为淮南王、衡山王、庐江王。
十三年夏，上曰：“盖闻天道祸自怨起而福繇德兴。百官之非，宜由朕躬。今秘祝之官移过于下，以彰吾之不德，朕甚不取。其除之。”
五月，齐太仓令淳于公有罪当刑，诏狱逮徙系长安。太仓公无男，有女五人。太仓公将行会逮，骂其女曰：“生子不生男，有缓急非有益也！”其少女缇萦自伤泣，乃随其父至长安，上书曰：“妾父为吏，齐中皆称其廉平，今坐法当刑。妾伤夫死者不可复生，刑者不可复属，虽复欲改过自新，其道无由也。妾愿没入为官婢，赎父刑罪，使得自新。”书奏天子，天子怜悲其意，乃下诏曰：“盖闻有虞氏之时，画衣冠异章服以为僇，而民不犯。何则？至治也。今法有肉刑三，而奸不止，其咎安在？非乃朕德薄而教不明欤？吾甚自愧。故夫驯道不纯而愚民陷焉。诗曰‘恺悌君子，民之父母’。今人有过，教未施而刑加焉？或欲改行为善而道毋由也。朕甚怜之。夫刑至断支体，刻肌肤，终身不息，何其楚痛而不德也，岂称为民父母之意哉！其除肉刑。”
上曰：“农，天下之本，务莫大焉。今勤身从事而有租税之赋，是为本末者毋以异，其于劝农之道未备。其除田之租税。”
十四年冬，匈奴谋入边为寇，攻朝那塞，杀北地都尉昂。上乃遣三将军军陇西、北地、上郡，中尉周舍为卫将军，郎中令张武为车骑将军，军渭北，车千乘，骑卒十万。帝亲自劳军，勒兵申教令，赐军吏卒。帝欲自将击匈奴，群臣谏，皆不听。皇太后固要帝，帝乃止。于是以东阳侯张相如为大将军，成侯赤为内史，栾布为将军，击匈奴。匈奴遁走。
春，上曰：“朕获执牺牲珪币以事上帝宗庙，十四年于今，历日（县）[绵]长，以不敏不明而久抚临天下，朕甚自愧。其广增诸祀墠场珪币。昔先王远施不求其报，望祀不祈其福，右贤左戚，先民后己，至明之极也。今吾闻祠官祝釐，皆归福朕躬，不为百姓，朕甚愧之。夫以朕不德，而躬享独美其福，百姓不与焉，是重吾不德。其令祠官致敬，毋有所祈。”
是时北平侯张苍为丞相，方明律历。鲁人公孙臣上书陈终始传五德事，言方今土德时，土德应黄龙见，当改正朔服色制度。天子下其事与丞相议。丞相推以为今水德，始明正十月上黑事，以为其言非是，请罢之。
十五年，黄龙见成纪，天子乃复召鲁公孙臣，以为博士，申明土德事。于是上乃下诏曰：“有异物之神见于成纪，无害于民，岁以有年。朕亲郊祀上帝诸神。礼官议，毋讳以劳朕。”有司礼官皆曰：“古者天子夏躬亲礼祀上帝于郊，故曰郊。”于是天子始幸雍，郊见五帝，以孟夏四月答礼焉。赵人新垣平以望气见，因说上设立渭阳五庙。欲出周鼎，当有玉英见。
十六年，上亲郊见渭阳五帝庙，亦以夏答礼而尚赤。
十七年，得玉杯，刻曰“人主延寿”。于是天子始更为元年，令天下大酺。其岁，新垣平事觉，夷三族。
后二年，上曰：“朕既不明，不能远德，是以使方外之国或不宁息。夫四荒之外不安其生，封畿之内勤劳不处，二者之咎，皆自于朕之德薄而不能远达也。闲者累年，匈奴并暴边境，多杀吏民，边臣兵吏又不能谕吾内志，以重吾不德也。夫久结难连兵，中外之国将何以自宁？今朕夙兴夜寐，勤劳天下，忧苦万民，为之怛惕不安，未尝一日忘于心，故遣使者冠盖相望，结轶于道，以谕朕意于单于。今单于反古之道，计社稷之安，便万民之利，亲与朕俱弃细过，偕之大道，结兄弟之义，以全天下元元之民。和亲已定，始于今年。”
后六年冬，匈奴三万人入上郡，三万人入云中。以中大夫令勉为车骑将军，军飞狐；故楚相苏意为将军，军句注；将军张武屯北地；河内守周亚夫为将军，居细柳；宗正刘礼为将军，居霸上；祝兹侯军棘门：以备胡。数月，胡人去，亦罢。[1]
天下旱，蝗。帝加惠：令诸侯毋入贡，弛山泽，减诸服御狗马，损郎吏员，发仓庾以振贫民，民得卖爵。
孝文帝从代来，即位二十三年，宫室苑囿狗马服御无所增益，有不便，辄弛以利民。尝欲作露台，召匠计之，直百金。上曰：“百金中民十家之产，吾奉先帝宫室，常恐羞之，何以台为！”上常衣绨衣，所幸慎夫人，令衣不得曳地，帏帐不得文绣，以示敦朴，为天下先。治霸陵皆以瓦器，不得以金银铜锡为饰，不治坟，欲为省，毋烦民。南越王尉佗自立为武帝，然上召贵尉佗兄弟，以德报之，佗遂去帝称臣。与匈奴和亲，匈奴背约入盗，然令边备守，不发兵深入，恶烦苦百姓。吴王诈病不朝，就赐几杖。群臣如袁盎等称说虽切，常假借用之。群臣如张武等受赂遗金钱，觉，上乃发御府金钱赐之，以愧其心，弗下吏。专务以德化民，是以海内殷富，兴于礼义。
后七年六月己亥，帝崩于未央宫。遗诏曰：“朕闻盖天下万物之萌生，靡不有死。死者天地之理，物之自然者，奚可甚哀。当今之时，世咸嘉生而恶死，厚葬以破业，重服以伤生，吾甚不取。且朕既不德，无以佐百姓；今崩，又使重服久临，以离寒暑之数，哀人之父子，伤长幼之志，损其饮食，绝鬼神之祭祀，以重吾不德也，谓天下何！朕获保宗庙，以眇眇之身托于天下君王之上，二十有馀年矣。赖天地之灵，社稷之福，方内安宁，靡有兵革。朕既不敏，常畏过行，以羞先帝之遗德；维年之久长，惧于不终。今乃幸以天年，得复供养于高庙。朕之不明与嘉之，其奚哀悲之有！其令天下吏民，令到出临三日，皆释服。毋禁取妇嫁女祠祀饮酒食肉者。自当给丧事服临者，皆无践。绖带无过三寸，毋布车及兵器，毋发民男女哭临宫殿。宫殿中当临者，皆以旦夕各十五举声，礼毕罢。非旦夕临时，禁毋得擅哭。已下，服大红十五日，小红十四日，纤七日，释服。佗不在令中者，皆以此令比率从事。布告天下，使明知朕意。霸陵山川因其故，毋有所改。归夫人以下至少使。”令中尉亚夫为车骑将军，属国悍为将屯将军，郎中令武为复土将军，发近县见卒万六千人，发内史卒万五千人，藏郭穿复土属将军武。
乙巳，群臣皆顿首上尊号曰孝文皇帝。
太子即位于高庙。丁未，袭号曰皇帝。
孝景皇帝元年十月，制诏御史：“盖闻古者祖有功而宗有德，制礼乐各有由。闻歌者，所以发德也；舞者，所以明功也。高庙酎，奏武德、文始、五行之舞。孝惠庙酎，奏文始、五行之舞。孝文皇帝临天下，通关梁，不异远方。除诽谤，去肉刑，赏赐长老，收恤孤独，以育群生。减嗜欲，不受献，不私其利也。罪人不帑，不诛无罪。除（肉）[宫]刑，出美人，重绝人之世。朕既不敏，不能识。此皆上古之所不及，而孝文皇帝亲行之。德厚侔天地，利泽施四海，靡不获福焉。明象乎日月，而庙乐不称。朕甚惧焉。其为孝文皇帝庙为昭德之舞，以明休德。然后祖宗之功德著于竹帛，施于万世，永永无穷，朕甚嘉之。其与丞相、列侯、中二千石、礼官具为礼仪奏。”丞相臣嘉等言：“陛下永思孝道，立昭德之舞以明孝文皇帝之盛德。皆臣嘉等愚所不及。臣谨议：世功莫大于高皇帝，德莫盛于孝文皇帝，高皇庙宜为帝者太祖之庙，孝文皇帝庙宜为帝者太宗之庙。天子宜世世献祖宗之庙。郡国诸侯宜各为孝文皇帝立太宗之庙。诸侯王列侯使者侍祠天子，岁献祖宗之庙。请著之竹帛，宣布天下。”制曰：“可。”
太史公曰：孔子言“必世然后仁。善人之治国百年，亦可以胜残去杀”。诚哉是言！汉兴，至孝文四十有馀载，德至盛也。廪廪乡改正服封禅矣，谦让未成于今。呜呼，岂不仁哉！', '《孝文本纪》是西汉史学家司马迁创作的一篇文言文，出自《史记卷十·孝文本纪第十》。本篇主要讲述了西汉第五位皇帝汉文帝刘恒一生的文治武功。汉文帝刘恒（公元前203年—公元前157年），庙号汉太宗，汉高祖刘邦第四子，惠帝刘盈弟，母薄姬。在位期间，继续执行与民休息和轻徭薄赋的政策，使汉朝从国家初定走向繁荣昌盛的过渡时期，开创了历史上著名的“文景之治”。此书现存最古版本目前保存于日本东北大学图书馆。', '', '孝文皇帝刘恒，是高祖排行居中的儿子，即八个儿子中的第四个。高祖十一年（前196）春天，打败了陈豨（xī，希）叛军，平定了代地，刘恒被立为代王，建都中都。他是薄太后所生。在他做代王的第十七年，即吕后八年（前180）七月，吕后去世。九月，吕氏家族的吕产等企图作乱，危害刘氏天下，大臣们共同诛灭了诸吕，商议迎立代王为皇帝，详细情况记载在《吕太后本纪》中。
丞相陈平、太尉周勃等派人去迎接代王。代王就此事征求左右大臣和郎中令张武等人的意见。张武等人议论说：“朝廷大臣都是当初高帝时的大将，熟习兵事，多谋善诈，他们的用意恐怕不止于此，这样做只是畏惧高帝、吕太后的威势罢了。如今他们刚刚诛灭诸吕，血染京城，此时来人名义上说是迎接大王，其实不可轻信。希望大王假托有病，不要前往，以便观察他们会有什么变化。”中尉宋昌进言说：“众位大臣的议论都是错误的。当初秦朝政治混乱，诸侯豪杰纷纷起事，自以为能得天下的人数以万计，然而最终登上天子之位的是刘氏，天下豪杰已经不再存有做皇帝的希望，这是第一点。高帝封刘氏子弟为王，封地象犬牙一样彼此交错，互相制约，这就是古人所说的宗族坚固，有如磐石，天下人都为刘氏的强大而折服，这是第二点。汉朝建立以后，废除了秦朝的苛虐政令，与民商定新的法令，对百姓施以恩德，人心安定，难以动摇，这是第三点。再者凭着吕后的威严，吕氏已有三人被立为王，把持朝政，独断专行，然而太尉凭朝廷一支符节进入吕氏把持的北军，只是一声呼唤，将士们就都袒露左臂，表示要辅佐刘氏而抛弃吕氏，最终消灭了诸吕。这是天意所授，而不是人力所能做到的。现在即使大臣们想要作乱，百姓也不会听他们驱使，他们的党羽难道能够同心一致吗？如今京城内有朱虚侯、东牟侯这样的亲族，京城外有吴、楚、淮南、琅邪、齐、代这样强大的诸侯，谁都惧怕他们。现在高帝的儿子就只有淮南王和大王您了，而大王您又年长，贤圣仁孝闻名天下，所以大臣们是根据天下人的心愿要迎立大王做皇帝，大王您不必怀疑。”代王又禀报太后商议这件事，还是犹豫，没拿定主意。于是就烧灼龟甲进行占卜，龟甲上显现出一条大的横向裂纹，卜辞是：“大横预示着更替，我将做天王，象夏启那样，使父业光大发扬。”代王说：“我本来就是王了，还做什么王？”占卜的人说：“所谓天王就是天子。”于是代王就派太后的弟弟薄昭前往京城会见绛侯周勃。周勃等人原原本本地向薄昭说明了为什么要迎立代王。薄昭回来报告说：“全是真的，没什么可怀疑的。”代王于是笑着对宋昌说：“果然象你说的那样。”随即命宋昌担任随车的参乘，张武等六人也乘驿车随代王一同前往长安。走到高陵停了下来，派宋昌先驱车前去长安观察情况有无变化。
宋昌刚到渭桥，丞相以下的官员都来迎接。宋昌返回报告。代王驱车到了渭桥，群臣都来拜见称臣。代王也下车答拜群臣。太尉周勃上前说：“我希望单独向大王禀报。”宋昌说：“你要说的如果是公事，就请公开说；如果是私事，在王位的人不受理私事。”太尉于是跪下献上皇帝的玉玺和符节。代王辞谢说：“等到代邸再商议吧。”然后驱车进入代王官邸。群臣也跟着来了。丞相陈平、太尉周勃、大将军陈武、御史大夫张苍、宗正刘郢、朱虚侯刘章、东牟侯刘兴居、典客刘揭都上前行礼，拜了两拜，然后说：“皇子刘弘等人都不是孝惠皇帝的儿子，不应当继位事奉宗庙。我们恭敬地与阴安侯、顷王后、琅邪王以及宗室、大臣、列侯、二千石以上的官员商议，大家都说：‘大王如今是高帝的长子，最应该做高帝的继承人。’希望大王即天子之位。”代王说：“事奉高帝宗庙，这是大事。我没有才能，胜任不了事奉宗庙的大事。希望请叔父楚王考虑最合适的人，我是不敢当此重任的。”群臣都伏在地上，坚决请求。代王先是面向西坐在主人的位置谦让了几次，群臣扶他向南坐在君主的位置，他又谦让了两次。丞相陈平等人都说：“我们再三考虑，认为大王事奉高帝宗庙是最适宜的。即使让天下诸侯和百姓来考虑，也会认为适宜的。我们臣子是为宗庙社稷着想，绝不敢轻率疏忽。希望大王听从我们的意见，我们将感到荣幸。现在，我们恭敬地奉上天子的玉玺和符节。”代王说：“既然宗室、将相、诸王、列侯都认为没有人比我更适宜，那我就不敢推辞了。”于是，代王即位做了天子。
群臣按照礼仪依次陪侍皇帝。于是派太仆夏侯婴与东牟侯刘兴居去清理皇宫。然后用天子乘坐的法驾，来代邸迎接皇帝。皇帝当天晚上就进入未央宫。连夜任命宋昌为卫将军，统领两宫卫队南北军；任命张武为郎中令，负责巡视殿中。皇帝回到前殿坐朝，当夜下诏说：“近来诸吕把持朝政，独断专行，阴谋叛逆，企图危害刘氏天下，全靠众位将相、列侯、宗室和大臣诛灭了他们，使他们的罪恶全都受到了应有的惩罚。现在我刚刚即位，下令大赦天下，赐给民家户主每人一级爵位，赐给无夫无子的女子每百户一头牛，十石酒，允许百姓聚会饮酒五天。
孝文皇帝元年（前179）十月庚戌日，改封原琅邪王刘泽为燕王。
辛亥日，文帝正式即位，在高祖庙举行典礼向高祖禀报。右丞相陈平改任左丞相，太尉周勃任右丞相，大将军灌婴任太尉。诸吕所剥夺的原齐、楚两国的封地，全部归给齐王和楚王。
壬子日，文帝派车骑将军薄昭去代国迎接皇太后。文帝说：“吕产自任为相国，吕禄为上将军，擅自假托皇帝诏令，派遣将军灌婴带领军队攻打齐国，企图取代刘氏，而灌婴留驻在荥阳不发兵攻齐，并与诸侯共谋诛灭了吕氏。吕产图谋不轨，丞相陈平与太尉周勃谋划夺了吕产等人的兵权，朱虚侯刘章首先捕杀了吕产等人。太尉周勃亲自率领襄平侯纪通持节奉诏进入北军。典客刘揭亲自夺了赵王吕禄的将军印。为此，加封太尉周勃食邑一万户，赐黄金五千斤；加封丞相陈平、将军灌婴食邑各三千户，赐黄金二千斤；加封朱虚侯刘章、襄平侯纪通、东牟侯刘兴居食邑各二千户，赐黄金一千斤；封典客刘揭为阳信侯，赐黄金一千斤。”
十二月，文帝说：“法令是治理国家的准绳，是用来制止暴行，引导人们向善的工具。如今犯罪的人已经治罪，却还要使他们无罪的父母、妻子、儿女和兄弟因为他们而被定罪，甚至被收为奴婢。我认为这种做法很不可取，希望你们再议论议论吧。”主管官员都说：“百姓不能自治，所以制定法令来禁止他们做坏事。无罪的亲属连坐，和犯人一起收捕判罪，就是要使人们心有牵挂，感到犯法干系重大。这种做法由来已久，还是依原来的做法不加改变为宜。”文帝说：“我听说法令公正百姓就忠厚，判罪得当百姓就心服。再说治理百姓引导他们向善，要靠官吏。如果既不能引导百姓向善，又使用不公正的法令处罚他们，这样反倒是加害于民而使他们去干凶暴的事。又怎么能禁止犯罪呢？这样的法令，我看不出它有哪些适宜之处，请你们再仔细考虑考虑。”官员们都说：“陛下给百姓以大恩大惠，功德无量，这不是我们这些臣下所能想得到的。我们遵从诏书，废除拘执罪犯家属，收为奴婢等各种连坐的法令。”
正月，主管大臣进言说：“及早确立太子，是尊奉宗庙的一种保障。请皇帝确立太子。”皇帝说：“我的德薄，上帝神明还没有欣然享受我的祭品，天下的人民心里还没有满意。如今我既不能广泛求访贤圣有德的人把天下禅让给他，却说预先确立太子，这是加重我的无德。我将拿什么向天下人交待呢？还是缓一缓吧。”主管大臣又说：“预先确立太子，正是为了尊奉宗庙社稷，不忘天下。”皇帝说：“楚王是我的叔父，年岁大，经历见识过的道理多了，懂得国家的大体。吴王是我的兄长，贤惠仁慈，甚爱美德。淮南王是我的弟弟，能守其才德以辅佐我。有他们，难道还不是预先做了安排吗？诸侯王、宗室、兄弟和有功的大臣，很多都是有才能有德义的人，如果推举有德之人辅佐我这不能做到底的皇帝，这也将是国家的幸运，天下人的福分。现在不推举他们，却说一定要立太子，人们就会认为我忘掉了贤能有德的人，而只想着自己的儿子，不是为天下人着想。我觉得这样做很不可取。”大臣们都坚决请求说：“古代殷、周立国，太平安定都达一千多年，古来享有天下的王朝没有比它们更长久的了，就是因为采取了立太子这个办法。确立继承人必须是自己的儿子，这是由来已久的。高帝亲自率领众将士最早平定天下，封建诸侯，成为本朝皇帝的太祖。诸侯王和列侯第一个接受封国的，也都是成为他们各自侯国的始祖。子孙继承，世世代代不断绝，这是普天之下的大原则，所以高帝设立了这种制度来安定天下人心。现在如果抛开应当立为太子的人，却从诸侯或宗室中另选他人，那就违背高帝的本意了。另议他人是不合适的。陛下的儿子启最大，纯厚仁爱，请立他为太子。”文帝这才同意了。于是赐给全国民众中应当继承父业的人每人一级爵位。封将军薄昭为轵（zhī，至）侯。
三月，主管大臣请求皇帝封立皇后。薄太后说：“皇帝的儿子都是同母所生，就立太子的母亲为皇后吧。”皇后姓窦。文帝因为立了皇后的缘故，赐给天下无妻、无夫、无父、无子的穷困人，以及年过八十的老人，不满九岁的孤儿每人若干布、帛、米、肉。文帝由代国来到京城，即位不久，就对天下施以德惠，安抚诸侯和四方边远的部族，使各方面的上上下下都融洽欢乐，于是慰问从代国随同来京的功臣。文帝说：“当朝廷大臣诛灭了诸吕迎接我入朝的时候，我犹疑不定，代国的大臣们也都劝阻我，只有中尉宋昌劝我入京，我才得以事奉宗庙。前已提拔宋昌为卫将军，现在再封他为壮武侯。另外随我进京的六个人，都任命为九卿。”
文帝说：“当年跟随高帝进入蜀郡和汉中的列侯六十八人，都加封食邑三百户；原先官禄在二千石以上曾跟随高帝的颖川郡守刘尊等十人，各赐封食邑六百户；淮阳郡郡守申徒嘉等十人，各赐封食邑五百户；卫尉定等十人，各赐封食邑四百户。封淮南王的舅父赵兼为周阳侯，齐王的舅父驷钧为清郭侯。”秋天，封原常山国的丞相蔡兼为樊侯。
有人劝说右丞相道：“您原先诛杀诸吕，迎立代王；如今又自夸功劳，受到最高的赏赐，居于尊贵的地位，灾祸就要落到您头上了。”于是右丞相周勃就推说有病而免职，由左丞相陈平一个人专任丞相。
文帝二年（前178）十月，丞相陈平去世，又用绛侯周勃为丞相。文帝说：“我听说古代诸侯建立国家的有一千多个，他们各守封地，按时入朝进贡，百姓不觉劳苦，上下欢欣，没有发生不遵守道德的事情。如今列侯大都住在长安，封邑离得又远，要靠官吏士卒供应运输给养，既浪费又辛苦，而这些列侯也无法教导和管理封地的百姓。命令列侯回到各自的封国去，在朝廷任职和诏令所准许留下的诸侯，要派太子回去。
十一月最后一天发生了日食。十二月十五日又发生了日食。文帝说：“我听说天生万民，为他们设置君主，来抚育治理他们。如果君主不贤德，施政不公平，那么上天就显示出灾异现象，告诫他治理得不好。十一月最后一天发生日食，上天的谴责在天象上表现出了灾异现象，有什么比这更大的呢！我能够事奉宗庙，以这微小之躯依托于万民和诸侯之上，天下的治与乱，责任在我一个人，你们众位执掌国政的大臣好比是我的左膀右臂。我对下不能很好地治理抚育众生，对上又牵累了日、月、星辰的光辉，以致发生日蚀，我的无德实在太严重了。接到诏令后，你们都要认真想想我的过失，以及你们知道的、见到的、想到的我做得不够的地方，恳请你们告诉我。还要推举贤良方正，能直言极谏的人，来补正我的疏漏。趁此机会，官吏们要整顿好各自所担任的职事，务必减少徭役和费用，以便利民众。我不能使惠德及于远方，所以忧虑不安，怕外族侵扰边境为非作歹，因此边疆的防务一直没停止。现在既然不能撤除边塞的军队，却还要命令军队增加兵力来保卫我吗？应该撤销卫将军统辖的军队。太仆掌管的现有马匹，只需留下一些够用就可以了，其余的都交给驿站使用。”
正月，文帝说：“农业是国家的根本，应当开辟皇帝亲自耕种的籍田，我要亲自带头耕作，来供给宗庙祭祀用的谷物。”
三月，主管大臣建议封皇子们为诸侯王。文帝说：“赵幽王刘友被囚禁而死，我非常怜惜他，他的长子刘遂已经被立为赵王。刘遂的弟弟辟强，以及齐悼惠王的儿子朱虚侯刘章、东矣侯刘兴居有功，也可以封王。”于是封赵幽王的小儿子刘辟强为河间王，用齐国的重要大郡封朱虚侯为城阳王，封东牟侯为济北王，封皇子刘武为代王，刘参为太原王，刘揖为梁王。
文帝说：“古代治理天下，朝廷设置进善言的旌旗和批评朝政的木牌，用以打通治国的途径，招来进谏的人。现在法令中有诽谤朝廷妖言惑众的罪状，这就使大臣们不敢完全说真话，做皇帝的也无从了解自己的过失。这还怎么能招来远方的贤良之士呢？应当废除这样的条文。百姓中有人一起诅咒皇帝，约定互相隐瞒，后来又负约相互告发，官吏认为这是大逆不道；如果再有其他不满的话，官吏又认为是诽谤朝廷。这些实际上只是小民愚昧无知而犯了死罪。上述做法我认为很不可取。从今以后，再有犯这类罪的，一律不加审理不予治罪。”
九月，首先把授兵权或调军队的铜虎符和使臣出使所持的竹使符发给各封国丞相和各郡郡守。
三年（前177）十月底丁酉日，发生日食。十一月，文帝说：“日前曾诏令列侯回各自的封国，有的找借口还没有走，丞相是我所敬重的，希望丞相为我率领列侯回封国。”于是绛侯周勃免去丞相职务，回自己的封国了。文帝任命太尉颍阴侯灌婴为丞相。取消了太尉这个官职，太尉所掌的兵权归属于丞相。四月，城阳王刘章去世。淮南王刘长和他的随从魏敬杀了辟阳侯审食其（yìjī，异基）。
五月，匈奴侵入北地郡，在河南地区进行抢掠。文帝初次幸临甘泉宫。六月，文帝说：“汉朝曾与匈奴结为兄弟，目的是不使它侵扰边境，为此给他们运去了大量的物资，馈赠十分丰厚。现在匈奴的右贤王离开他们本土，率众进驻早已归属汉朝的河南地区，没有任何正当理由，就在边塞地区出入往来，捕杀汉官吏士卒，驱逐守卫边塞的蛮夷，使他们不能在原居住地居住，欺凌边防官吏，侵入内地抢劫，十分傲慢，不讲道理，破坏了先前的协约。为此可调发边防官吏骑兵八万五千人前往高奴，派丞相颍阴侯灌婴率兵反击匈奴。”匈奴退离边境。又征调中尉属下勇武的士卒归属于卫将军统领，驻守长安。
辛卯日，文帝从甘泉前往高奴，顺便来到太原，接见原代国的群臣，全都给以赏赐。根据功劳大小给以不同的奖赏，赐给百姓牛、酒，免除晋阳、中都两地百姓三年的赋税。文帝在太原逗留游玩了十多天。
济北王刘兴居得知文帝到了代地，想要前去反击匈奴，趁势起兵造反，打算袭击荥阳。于是文帝下令丞相灌婴撤回部队，派遣棘蒲侯陈武为大将军，率领十万部队前去讨伐叛军。任命祁侯缯贺为将军，驻扎在荥阳。七月辛亥日，文帝从太原回到长安。诏令有关大臣说：“济北王背德反上，连累了济北的官吏百姓，这是大逆不道。济北的官吏和民众，凡是在朝廷大军到来之前就自己停止反叛活动的，以及率部投降或献出城邑出降的，一律赦免，官爵复原。那些开始曾与刘兴居一起造反但后来投降了的人，也予以赦免。”八月，打垮了济北叛军，浮虏了济北王。文帝宣布郝免济北国中随济北王造反的官吏百姓。
六年（前174），主管大臣报告淮南王刘长废弃先帝的法律，不听从皇帝的诏令，宫室居所超过规定的限度，出入车马仪仗比拟天子，擅自制定法令，与棘蒲侯的太子陈奇图谋造反，派人出使闽越和匈奴，调用它们的军队，企图危害宗庙社稷。群臣议论此事，都说“刘长应当在街市上斩首示众。”文帝不忍心法办淮南王，免了他的死罪，废了他的王位，不准再做诸侯王。群臣请求把淮南王流放到蜀郡的严道和邛（qióng，琼）都一带，文帝同意了。刘长还没到达流放地，就病死在路上。文帝怜惜他，后来到十六年（前164）时，追尊淮南王刘长，谥号为厉王，并封他的三个儿子：刘安为淮南王，刘勃为衡山王，刘赐为庐江王。
十三年（前167）夏天，文帝说：“我听说，天道是祸从怨起、福由德兴。百官的过错，应当由我一人承担责任。如今秘祝官把过错都推到下面的大臣，其结果是显扬了我的无德，我很不赞成。应当取消这种做法。”
五月，齐国的太仓令淳于公犯了罪，应该受刑，朝廷下诏让狱官逮捕他，把他押解到长安拘禁起来。太仓令没有儿子，只有五个女儿。他被捕临行时，骂女儿们说：“生孩子不生儿子，遇到紧急情况，就没有用处了！”他的小女儿缇（tí，提）萦（yíng，营）伤心地哭了，就跟随父亲来到长安，向朝廷上书说：“我的父亲做官，齐国的人们都称赞他廉洁公平，现在因触犯法律而犯罪，应当受刑。我哀伤的是，受了死刑的人不能再活过来，受了肉刑的人肢体断了不能再接起来，虽想走改过自新之路，也没有办法了。我愿意被收入官府做奴婢，来抵父亲的应该受刑之罪，使他能够改过自新。”上书送到文帝那里，文帝怜悯缇萦的孝心，就下诏说：“听说在有虞氏的时候，只是在罪犯的衣帽上画上特别的图形或颜色，给罪犯穿上有特定标志的衣服，以此来羞辱他们，这样，民众就不犯法了。为什么能这样呢？因为当时政治清明到了极点。如今法令中有刺面、割鼻、断足三种肉刑，可是犯法的事仍然不能禁止，过失出在哪儿呢？不就是因为我道德不厚教化不明吗？我自己感到很渐愧，所以训导的方法不完善，愚昧的百姓就会走上犯罪。《诗经》上说，‘平易近人的官员，才是百姓的父母’。现在人犯了过错，还没施以教育就加给刑罚，那么有人想改过从善也没有机会了。我很怜悯他们。施用刑罚以致割断犯人的肢体，刻伤犯人的肌肤，终身不能长好，多么令人痛苦而又不合道德呀，作为百姓的父母，这样做，难道合乎天下父母心吗？应该废除肉刑。”
文帝说：“农业是天下的根本，没有什么比这事情更重要。现在农民辛勤地从事农业生产却还要交纳租税，使得务农和从事商业手工业没有区别，本末不分，这恐怕是由于鼓励农耕的方法还不完备。应当免除农田的租税。”
十四年（前166）冬天，匈奴谋划侵入边境进行劫掠，攻打朝那塞，杀死北地郡都尉孙昂。文帝于是派出三位将军率兵分别驻扎在陇西、北地、上郡，任命中尉周舍为卫将军，郎中令张武为车骑将军，驻扎在渭河以北地区，计有战车千辆，骑兵十万。文帝亲自慰劳军队，部署军队，申明训令，奖赏全军将士。文帝想要亲自率兵反击匈奴，群臣劝阻，一概不听。皇太后坚决阻拦文帝，文帝这才作罢。于是任命东阳侯张相如为大将军，成侯董赤为内史，栾布为将军，率军攻打匈奴。匈奴逃跑了。
这年春天，文帝说：“我有幸得以执掌祭祀的牺牲、玉帛来祭祀上帝、宗庙，登上帝位，至今十四年了，历时已经很久，以我这样一个既不聪敏又不明智的人长久地治理天下，深为自愧。应当广泛增设祭祀的？（shàn，扇）场和玉帛。从前先王远施恩惠而不求回报，遥祭山川却不为自己祈福，尊贤抑亲，先民后己，圣明到了极点。如今我听说掌管祭祀的祠官祈祷时，全都是为我一个人，而不为百姓祝福，我为此而感到非常渐愧。凭着我这样无德之人，却独自享受神灵的降福，而百姓却享受不到，这就加重了我的无德。现在命令祠官祭祀要向神献上敬意，不要为我一个人祈求什么。”
这时，北平侯张苍任丞相，刚刚明确了新的乐律和历法。鲁国人公孙臣上书陈说金木水火土五行相生相克，终而复始以象征王朝兴替的五德终始学说，说现在正当土德，土德的验证是将有黄龙出现，应当更改历法、服色等制度。文帝把此事下交给丞相去研究。丞相张苍经过推算认为现今是水德，才明确把冬十月作为岁首，应该崇尚黑色，认为公孙臣的说法不对，请求文帝不要采纳。
十五年（前165），有黄龙出现在成纪县，文帝又召来鲁国的公孙臣，任命他为博士，让他重新说明当今应为土德的道理。于是文帝下诏说：“有奇物神龙出现在成纪，没有伤害到百姓，今年又是个好年成。我要亲自到郊外祭祀上帝和诸神。礼官们商议这件事，不要因为怕我劳累而有什么隐讳。”主管大臣和礼官们都说：“古代天子每年夏天亲自到郊外祭祀上帝，所以叫做‘郊’（郊祀，郊祭）。”于是文帝第一次来到雍，郊祭五帝，在夏初四月向天帝致礼。赵国人新垣平凭着善于望云气而知凶吉来进见文帝，劝说文帝在渭城建五帝庙，并预言这将使周朝的传国宝鼎出现，还会有奇异的美玉出现。
十六年（前164），文帝亲自到渭阳五帝庙郊祭，仍在夏季向天帝致敬，并崇尚红色。十七年（前163），文帝得到一个玉杯，这个玉杯实际是新垣平为欺骗文帝而派人献上的，玉杯上刻有“人主延寿”四个字。于是文帝下诏把这一年改为元年，下令天下民众尽情聚会饮酒。当年，新垣平欺诈的事情被发觉，夷灭了三族。
后元二年（前162），文帝说：“我不英明，不能施恩德于远方，因而使境外有些国家时常侵扰生事。边远地区的人民不能安定地生活，内地的百姓辛勤劳动也不得歇息，这两方面的过失，都是由于我的德不厚，不能惠及远方。最近连续几年，匈奴都来为害边境，杀我许多官吏和百姓，边境的官员和将领又不明白我的心意，以致加重我的无德。这样长久结下怨仇，兵祸不断，中外各国将怎么能各自安宁呢？现在我起早睡晚，操劳国事，为万民忧虑，惶惶不安，未曾有一天心里不想着这些事情，所以我派出一批又一批的使者，在路上礼帽车盖前后相望，车子的辙迹道道相连，为的就是让他们向单于说明我的意愿。现在单于已经回到从前友好相处的道路上来了，考虑国家的安定，为了万民的利益，亲自跟我相约完全抛弃细小的过失，一起走和平的大道，结为兄弟之好，以保全天下善良的百姓。和亲的协议已经确定，从今年就开始。”
后元六年（前159）冬天，匈奴三万人入侵上郡，三万人入侵云中郡。文帝任命中大夫令勉为车骑将军，驻扎在飞狐口；任命原楚国丞相苏意为将军，驻扎在勾注山；命将军张武驻守北地郡；任命河内郡郡守周亚夫为将军，驻军细柳；任命宗正刘礼为将军，驻军霸上；命祝兹侯徐悍驻扎在棘门：以防备匈奴。过了几个月，匈奴人退去，这些军队也撤回了。
这一年天下干旱，发生蝗灾。文帝施恩于民：诏令诸侯不要向朝廷进贡，解除民众开发山林湖泊的禁令，减少宫中各种服饰、车驾和狗马，裁减朝廷官吏的人数，打开粮仓救济贫苦百性，允许民间买卖爵位。
孝文帝从代国来到京城，即位二十三年，宫室、园林、狗马、服饰、车驾等等，什么都没有增加。但凡有对百姓不便的事情，就予以废止，以便利民众。文帝曾打算建造一座高台，召来工匠一计算，造价要值上百斤黄金。文帝说：“百斤黄金相当于十户中等人家的产业，我承受了先帝留下来的宫室，时常担心有辱于先帝，还建造高台干什么呢？”文帝平时穿的是质地粗厚的丝织衣服，对所宠爱的慎夫人，也不准她穿长得拖地的衣服，所用的帏帐不准绣彩色花纹，以此来表示俭朴，为天下人做出榜样。文帝规定，建造他的陵墓霸陵，一律用瓦器，不准用金银铜锡等金属做装饰，不修高大的坟；要节省，不要烦扰百性。南越王尉佗自立为武帝，文帝却把尉佗的兄弟召来，使他们显贵，报之以德。尉佗于是取消了帝号，向汉朝称臣。汉与匈奴相约和亲，匈奴却背约入侵劫掠，而文帝只命令边塞戒备防守，不发兵深入匈奴境内，不乐意给百姓带来烦扰和劳苦。吴王刘濞谎称有病不来朝见，文帝就趁此机会赐给他木几和手杖，以表示关怀他年纪大，可以免去进京朝觐之礼。群臣中如袁盎（àng，去声昂）等人进言说事，虽然直率尖锐，而文帝总是宽容采纳。大臣中如张武等人接受别人贿赂的金钱，事情被发觉，文帝就从皇宫仓库中取出金钱赐给他们，用这种办法使他们内心羞愧，而不下交给执法官吏处理。文帝一心致力于用恩德感化臣民，因此天下富足，礼义兴盛。
后元七年六月己亥日，文帝在未央宫逝世。留下遗诏说：“我听说天下万物萌芽生长，最终没有不死的。死是世间的常理，事物的自然归宿，有什么值得过份悲哀呢！当今世人都喜欢活着而不乐意死，死了人还要厚葬，以致破尽家产；加重服丧以致损害身体。我认为很不可取。况且我生前没什么德行，没有给百姓什么帮助；现在死了，又让人们加重服丧长期哭吊，遭受严寒酷暑的折磨，使天下的父子为我悲哀，使天下的老幼心灵受到损害，减少饮食，中断对鬼神的祭祀，其结果是加重了我的无德，我怎么向天下人交待呢！我有幸得以保护宗庙，凭着我这渺小之身依托在天下诸侯之上，至今已二十多年。靠的是天地的神灵，社稷的福气，才使得国内安宁，没有战乱。我不聪敏，时常担心行为有过错，使先帝遗留下来的美德蒙受羞辱；岁月长久了，总是担心不能维持始终。如今没想到能侥幸享尽天年，将被供奉在高庙里享受祭祀，我如此不贤明，却能有这样的结果，我认为就很好，还有什么可悲哀的呢！现在诏令全国官吏和百姓，诏令到达后，哭吊三日就除去丧服。不要禁止娶妻、嫁女、祭祀、饮酒、吃肉。应当参加丧事、服丧哭祭的人，都不要赤脚。服丧的麻带宽度不要超过三寸，不要陈列车驾和兵器，不要动员民间男女到宫殿来哭祭。宫中应当哭祭的人，都在早上和晚上各哭十五声，行礼完毕就停止。不是早上和晚上哭祭的时间，不准擅自哭泣。下葬以后，按丧服制度应服丧九个月的大功只服十五日，应服丧五个月的小功只服十四日，应服丧三个月的缌麻只服七日，期满就脱去丧服。其他不在此令中的事宜，都参照此令办理。要把这道诏令通告天下，使天下人都明白地知道我的心意。葬我的霸陵周围山水要保留其原来的样子，不要有所改变。后宫夫人以下直至少使，全都让他们回娘家。”朝廷任命中尉周亚夫为车骑将军，典属国徐悍为将屯将军，郎中令张武为复土将军。征调京城附近各县现役士卒一万六千人，又征调内史所统辖的京城士卒一万五千人，去做安葬棺椁的挖土、填土等工作，归将军张武统领。
乙巳日，文帝葬在霸陵，群臣叩首至地，奉上谥号，尊称为孝文皇帝。
太子刘启在高庙即位。丁未日，承袭帝号为皇帝。
孝景皇帝元年（前156）十月，下诏给御史：“我听说古代帝王，有取天下之功的称为‘祖’，有治天下之德的称为‘宗’，制定礼仪音乐各有其根据。还听说歌是用来颂扬德行的，舞是用来显扬功绩的。在高庙献酒祭祀，演奏《武德》、《文始》、《五行》等歌舞。在孝惠庙献酒祭祀，演奏《文始》、《五行》等歌舞。孝文皇帝治理天下，开放了关卡桥梁，处处畅通无阻，边远地区也是一样；废除了诽谤有罪的法令，取消肉刑，赏赐老人，收养抚恤少无父母和老而无子的贫苦人，以此来养育天下众生；他杜绝各种嗜好，不受臣下进献的贡品，不求一己之私利；处治罪犯不株连家属，不诛罚无罪之人。废除宫刑，放出后宫美人，对使人断绝后代的事看得很重。我不聪敏，不能认识孝文皇帝的一切。这些都是古代帝王做不到的，而孝文皇帝亲自实行了。他的功德显赫，比得上天地；恩惠广施，遍及四海，没有哪个人不曾得到他的好处。他的光辉如同日月，而祭祀时所用的歌舞却不相称，对此我心中非常不安。应当为孝文皇帝庙制作《昭德》舞，以显扬他的美德。然后将祖宗的功德载入史册，流传万代，永远永远没有尽头，我认为这样做很好。此事交给丞相、列侯、中二千石级的官员和礼官共同制定出礼仪，然后上报给我。”丞相申徒嘉等人说：“陛下始终想着孝亲之道，制作《昭德》之舞来显扬孝文皇帝的赫赫功德，这都是我们这些臣子由于愚钝而想不到的。我们恭敬地建议：世间取天下之功没有大过高皇帝的，治天下之德没有超过孝文皇帝的，高皇帝庙应当作为本朝帝王的太祖庙，孝文皇帝庙应当作为本朝帝王的太宗庙。后代天子应当世世祭祀太祖和太宗之庙。各郡各国诸侯也应当分别为孝文皇帝建立太宗之庙。每年朝廷祭祀时，诸侯王和列侯都要按时派使者来京陪侍天子祭祀，每年都要祭祀太祖、太宗。请把这些写入文献，向天下公布。”景帝下制说：“可以。”
太史公说：孔子曾说：“治理国家必须经过三十年才能实现仁政。善人治理国家经过一百年，也就可以克服残暴免除刑杀了。”这话千真万确。汉朝建立，到孝文皇帝经过四十多年，德政达到了极盛的地步。孝文帝已逐渐走向更改历法、服色和进行封禅了，可是由于他的谦让，至今尚未完成。啊，这难道不就是仁吗？', NULL, '', 'indent', 1525198319, '5ae83d6ca22b9d0044213e31', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (637450, '史记 · 十二本纪 · 孝景本纪', NULL, 0, 139, 0, 1, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%9D%E6%99%AF%E6%9C%AC%E7%BA%AA/2391370?fr=aladdin', '', '孝景皇帝者，孝文之中子也。母窦太后。孝文在代时，前后有三男，及窦太后得幸，前后死，及三子更死，故孝景得立。
元年四月乙卯，赦天下。乙巳，赐民爵一级。五月，除田半租，为孝文立太宗庙。令群臣无朝贺。匈奴入代，与约和亲。
二年春，封故相国萧何孙系为武陵侯。男子二十而得傅。四月壬午，孝文太后崩。广川、长沙王皆之国。丞相申屠嘉卒。八月，以御史大夫开封陶青为丞相。彗星出东北。秋，衡山雨雹，大者五寸，深者二尺。荧惑逆行，守北辰。月出北辰间。岁星逆行天廷中。置南陵及内史、祋祤为县。
三年正月乙巳，赦天下。长星出西方。天火燔雒阳东宫大殿城室。吴王濞、楚王戊、赵王遂、胶西王昂、济南王辟光、菑川王贤、胶东王雄渠反，发兵西乡。天子为诛晁错，遣袁盎谕告，不止，遂西围梁。上乃遣大将军窦婴、太尉周亚夫将兵诛之。六月乙亥。赦亡军及楚元王子蓺等与谋反者。封大将军窦婴为魏其侯。立楚元王子平陆侯礼为楚王。立皇子端为胶西王，子胜为中山王。徙济北王志为菑川王，淮阳王馀为鲁王，汝南王非为江都王。齐王将庐、燕王嘉皆薨。
四年夏，立太子。立皇子彻为胶东王。六月甲戌，赦天下。后九月，更以阳为阳陵。复置津关，用传出入。冬，以赵国为邯郸郡。
五年三月，作阳陵、渭桥。五月，募徙阳陵，予钱二十万。江都大暴风从西方来，坏城十二丈。丁卯，封长公主子蟜为隆虑侯。徙广川王为赵王。
六年春，封中尉绾为建陵侯，江都丞相嘉为建平侯，陇西太守浑邪为平曲侯，赵丞相嘉为江陵侯，故将军布为鄃侯。梁楚二王皆薨。后九月，伐驰道树，殖兰池。
七年冬，废栗太子为临江王。十月晦，日有食之。春，免徒隶作阳陵者。丞相青免。二月乙巳，以太尉条侯周亚夫为丞相。四月乙巳，立胶东王太后为皇后。丁巳，立胶东王为太子。名彻。
中元年，封故御史大夫周苛孙平为绳侯，故御史大夫周昌左车为安阳侯，四月乙巳，赦天下，赐爵一级。除禁锢。地动。衡山、原都雨雹，大者尺八寸。
中二年二月，匈奴入燕，遂不和亲。三月，召临江王来。即死中尉府中。夏，立皇子越为广川王，子寄为胶东王。封四侯。九月甲戌，日食。
中三年冬，罢诸侯御史中丞。春，匈奴王二人率其徒来降，皆封为列侯。立皇子方乘为清河王。三月，彗星出西北。丞相周亚夫，以御史大夫桃侯刘舍为丞相。四月，地动。九月戊戌晦，日食。军东都门外。
中四年三月，置德阳宫。大蝗。秋，赦徒作阳陵者。
中五年夏，立皇子舜为常山王。封十侯。六月丁巳，赦天下，赐爵一级。天下大潦。更命诸侯丞相曰相。秋，地动。
中六年二月己卯，行幸雍，郊见五帝。三月，雨雹。四月，梁孝王、城阳共王、汝南王皆薨。立梁孝王子明为济川王，子彭离为济东王，子定为山阳王，子不识为济阴王。梁分为五。封四侯。更命廷尉为大理，将作少府为将作大匠，主爵中尉为都尉，长信詹事为长信少府，将行为大长秋，大行为行人，奉常为太常，典客为大行，治粟内史为大农。以大内为二千石，置左右内官，属大内。七月辛亥，日食。八月，匈奴入上郡。
后元年冬，更命中大夫令为卫尉。三月丁酉，赦天下，赐爵一级，中二千石、诸侯相爵右庶长。四月，大酺。五月丙戌，地动，其蚤食时复动。上庸地动二十二日，坏城垣。七月乙巳，日食。丞相刘舍免。八月壬辰，以御史大夫绾为丞相，封建陵侯。
后二年正月，地一日三动。郅将军击匈奴。酺五日。令内史郡不得食马粟，没入县官。令徒隶衣七緵布。止马舂。为岁不登，禁天下食不造岁。省列侯遣之国。三月，匈奴入雁门。十月，租长陵田。大旱。衡山国、河东、云中郡民疫。
后三年十月，日月皆赤五日。十二月晦，袴。日如紫。五星逆行守太微。月贯天廷中。正月甲寅，皇太子冠。甲子，孝景皇帝崩。遗诏赐诸侯王以下至民为父后爵一级，天下户百钱。出宫人归其家，复无所与。太子即位，是为孝武皇帝。三月，封皇太后弟蚡为武安侯，弟胜为周阳侯。置阳陵。
太史公曰：汉兴，孝文施大德，天下怀安，至孝景，不复忧异姓，而晁错刻削诸侯，遂使七国俱起，合从而西乡，以诸侯太盛，而错为之不以渐也。及主父偃言之，而诸侯以弱，卒以安。安危之机，岂不以谋哉？', '《孝景本纪》是西汉史学家司马迁创作的一篇文言文，出自《史记卷十一·孝景本纪第十一》。本篇主要讲述了西汉第6位皇帝汉景帝刘启在位16年间的文治武功。他在位期间，平定了“七国之乱”，且继续执行与民休息和轻徭薄赋的政策，使汉朝从国家初定走向繁荣昌盛的过渡时期，开创了历史上著名的“文景之治”。', '集解汉书音义曰：“讳启。”□正义谥法曰：“繇义而济曰景。”
集解（徐广曰：汉书亦作“系”。邹诞生本作“傒”，音奚。又按：汉书功臣表及萧何传皆云孙嘉，疑其人有二名。）○索隐汉书亦作“系”，邹诞生本作“傒”。又按：汉书功臣表及萧何传皆云封何孙嘉，疑其人有二名也。
索隐音附。荀悦云：“傅，正卒也。”小颜云旧法二十三而傅，今改也。
索隐薄太后也。亦葬芷阳西，曰少陵也。
索隐广川王彭祖、长沙王发皆景帝子，遣就国也。
正义雨，于付反。
集解徐广曰：“地理志云文帝七年置。”骃按：地理志、百官表南陵县文帝置也。分内史为左右，及祋祤为县，皆景帝二年，不得皆如徐所云。○索隐邹诞生祋音都会反，又音丁活反。祤音羽，又音诩。
