INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639170, '三国演义 · 第三十五回 · 玄德南漳逢隐沧 单福新野遇英主', NULL, 5, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说蔡瑁方欲回城，赵云引军赶出城来。原来赵云正饮酒间，忽见人马动，急入内观之，席上不见了玄德。云大惊，出投馆舍，听得人说：“蔡瑁引军望西赶去了。”云火急绰枪上马，引着原带来三百军，奔出西门，正迎着蔡瑁，急问曰：“吾主何在？”瑁曰：“使君逃席而去，不知何往。”赵云是谨细之人，不肯造次，即策马前行。遥望大溪，别无去路，乃复回马，喝问蔡瑁曰：“汝请吾主赴宴，何故引着军马追来？”瑁曰：“九郡四十二州县官僚俱在此，吾为上将，岂可不防护？”云曰：“汝逼吾主何处去了？”瑁曰：“闻使君匹马出西门，到此却又不见。”云惊疑不定，直来溪边看时，只见隔岸一带水迹。云暗忖曰：“难道连马跳过了溪去……？”令三百军四散观望，并不见踪迹。云再回马时，蔡瑁已入城去了。云乃拿守门军士追问，皆说：“刘使君飞马出西门而去。”云再欲入城，又恐有埋伏，遂急引军归新野。
却说玄德跃马过溪，似醉如痴，想：“此阔涧一跃而过，岂非天意！”迤逦望南漳策马而行，日将沉西。正行之间，见一牧童跨于牛背上，口吹短笛而来。玄德叹曰：“吾不如也！”遂立马观之。牧童亦停牛罢笛，熟视玄德，曰：“将军莫非破黄巾刘玄德否？”玄德惊问曰：“汝乃村僻小童，何以知吾姓字！”牧童曰：“我本不知，因常侍师父，有客到日，多曾说有一刘玄德，身长七尺五寸，垂手过膝，目能自顾其耳，乃当世之英雄，今观将军如此模样，想必是也。”玄德曰：“汝师何人也？”牧童曰：“吾师覆姓司马，名徽，字德操，颍川人也。道号‘水镜先生’。”玄德曰：“汝师与谁为友？”小童曰：“与襄阳庞德公、庞统为友。”玄德曰：“庞德公乃庞统何人？”童子曰：“叔侄也。庞德公字山民，长俺师父十岁；庞统字士元，少俺师父五岁。一日，我师父在树上采桑，适庞统来相访，坐于树下，共相议论，终日不倦。吾师甚爱庞统，呼之为弟。”玄德曰：“汝师今居何处？”牧童遥指曰：“前面林中，便是庄院。”玄德曰：“吾正是刘玄德。汝可引我去拜见你师父。”童子便引玄德，行二里余，到庄前下马，入至中门，忽闻琴声甚美。玄德教童子且休通报，侧耳听之。琴声忽住而不弹。一人笑而出曰：“琴韵清幽，音中忽起高抗之调。必有英雄窃听。”童子指谓玄德曰：“此即吾师水镜先生也。”玄德视其人，松形鹤骨，器宇不凡。慌忙进前施礼，衣襟尚湿。水镜曰：“公今日幸免大难！”玄德惊讶不已。小童曰：“此刘玄德也。”水镜请入草堂，分宾主坐定。玄德见架上满堆书卷，窗外盛栽松竹，横琴于石床之上，清气飘然。水镜问曰：“明公何来？”玄德曰：“偶尔经由此地，因小童相指，得拜尊颜，不胜万幸！”水镜笑曰：“公不必隐讳。公今必逃难至此。”玄德遂以襄阳一事告之。水镜曰：“吾观公气色，已知之矣。”因问玄德曰：“吾久闻明公大名，何故至今犹落魄不偶耶？”玄德曰：“命途多蹇，所以至此。”水镜曰：“不然。盖因将军左右不得其人耳。”玄德曰：“备虽不才，文有孙乾、糜竺、简雍之辈，武有关、张、赵云之流，竭忠辅相，颇赖其力。”水镜曰：“关、张、赵云，皆万人敌，惜无善用之之人。若孙乾、糜竺辈，乃白面书生，非经纶济世之才也。”玄德曰：“备亦尝侧身以求山谷之遗贤，奈未遇其人何！”水镜曰：“岂不闻孔子云：‘十室之邑’必有忠信，何谓无人？”玄德曰：“备愚昧不识，愿赐指教。”水镜曰：“公闻荆襄诸郡小儿谣言乎？其谣曰：八九年间始欲衰，至十三年无孑遗。到头天命有所归，泥中蟠龙向天飞。此谣始于建安初：建安八年，刘景升丧却前妻，便生家乱，此所谓‘始欲衰’也；‘无孑遗’者，不久则景升将逝，文武零落无孑遗矣；‘天命有归’，‘龙向天飞’，盖应在将军也。”玄德闻言惊谢曰：“备安敢当此！”水镜曰：“今天下之奇才，尽在于此，公当往求之。”玄德急问曰：“奇才安在？果系何人？”水镜曰：“伏龙、凤雏，两人得一，可安天下。”玄德曰：“伏龙、凤雏何人也？”水镜抚掌大笑曰：“好！好！”玄德再问时，水镜曰：“天色已晚，将军可于此暂宿一宵，明日当言之。”即命小童具饮馔相待，马牵入后院喂养。玄德饮膳毕，即宿于草堂之侧。玄德因思水镜之言，寝不成寐。约至更深，忽听一人叩门而入，水镜曰：“元直何来？”玄德起床密听之，闻其人答曰：“久闻刘景升善善恶恶，特往谒之。及至相见，徒有虚名，盖善善而不能用，恶恶而不能去者也。故遗书别之，而来至此。”水镜曰：“公怀王佐之才，宜择人而事，奈何轻身往见景升乎？且英雄豪杰，只在眼前，公自不识耳。”其人曰：“先生之言是也。”玄德闻之大喜，暗忖此人必是伏龙、凤雏，即欲出见，又恐造次。候至天晓，玄德求见水镜，问曰：“昨夜来者是谁？”水镜曰：“此吾友也。”玄德求与相见。水镜曰：“此人欲往投明主，已到他处去了。”玄德请问其姓名。水镜笑曰：“好！好！”玄德再问：“伏龙、凤雏，果系何人？”水镜亦只笑曰：“好！好！”玄德拜请水镜出山相助，同扶汉室。水镜曰：“山野闲散之人，不堪世用。自有胜吾十倍者来助公，公宜访之。”正谈论间，忽闻庄外人喊马嘶，小童来报：“有一将军，引数百人到庄来也。”玄德大惊，急出视之，乃赵云也。玄德大喜。云下马入见曰：“某夜来回县，寻不见主公，连夜跟问到此。主公可作速回县。只恐有人来县中厮杀。”玄德辞了水镜，与赵云上马，投新野来。行不数里，一彪人马来到，视之，乃云长、翼德也。相见大喜。玄德诉说跃马檀溪之事，共相嗟讶。到县中，与孙乾等商议。乾曰：“可先致书于景升，诉告此事。”玄德从其言，即令孙乾赍书至荆州。刘表唤入问曰：“吾请玄德襄阳赴会，缘何逃席而去？”孙乾呈上书札，具言蔡瑁设谋相害，赖跃马檀溪得脱。表大怒，急唤蔡瑁责骂曰：“汝焉敢害吾弟！”命推出斩之。蔡夫人出，哭求免死，表怒犹未息。孙乾告曰：“若杀蔡瑁，恐皇叔不能安居于此矣。”表乃责而释之，使长子刘琦同孙乾至玄德处请罪。
琦奉命赴新野，玄德接着，设宴相待。酒酣，琦忽然堕泪。玄德问其故。琦曰：“继母蔡氏，常怀谋害之心；侄无计免祸，幸叔父指教。”玄德劝以小心尽孝，自然无祸。次日，琦泣别。玄德乘马送琦出郭，因指马谓琦曰：“若非此马，吾已为泉下之人矣。”琦曰：“此非马之力，乃叔父之洪福也。”说罢。相别。刘琦涕泣而去。
玄德回马入城，忽见市上一人，葛巾布袍，皂绦乌履，长歌而来。歌曰：“天地反覆兮，火欲殂；大厦将崩兮，一木难扶。山谷有贤兮，欲投明主；明主求贤兮，却不知吾。”玄德闻歌，暗思：“此人莫非水镜所言伏龙、凤雏乎？”遂下马相见，邀入县衙。问其姓名，答曰：“某乃颍上人也，姓单，名福。久闻使君纳士招贤，欲来投托，未敢辄造；故行歌于市，以动尊听耳。”玄德大喜，待为上宾。单福曰：“适使君所乘之马，再乞一观。”玄德命去鞍牵于堂下。单福曰：“此非的卢马乎？虽是千里马，却只妨主，不可乘也。”玄德曰：“已应之矣。”遂具言跃檀溪之事。福曰：“此乃救主，非妨主也；终必妨一主。某有一法可禳。玄德曰：“愿闻禳法。”福曰：“公意中有仇怨之人，可将此马赐之；待妨过了此人，然后乘之，自然无事。”玄德闻言变色曰：“公初至此，不教吾以正道，便教作利己妨人之事，备不敢闻教。”福笑谢曰：“向闻使君仁德，未敢便信，故以此言相试耳。”玄德亦改容起谢曰：“备安能有仁德及人，惟先生教之。”福曰：“吾自颍上来此，闻新野之人歌曰‘新野牧，刘皇叔；自到此，民丰足。’可见使君之仁德及人也。”玄德乃拜单福为军师，调练本部人马。
却说曹操自冀州回许都，常有取荆州之意，特差曹仁、李典并降将吕旷、吕翔等领兵三万，屯樊城，虎视荆襄，就探看虚实。时吕旷、吕翔禀曹仁曰：“今刘备屯兵新野，招军买马，积草储粮，其志不小，不可不早图之。吾二人自降丞相之后，未有寸功，愿请精兵五千，取刘备之头，以献丞相。”曹仁大喜，与二吕兵五千，前往新野厮杀。
探马飞报玄德。玄德请单福商议。福曰：“既有敌兵，不可令其入境。可使关公引一军从左而出，以敌来军中路；张飞引一军从右而出，以敌来军后路；公自引赵云出兵前路相迎：敌可破矣。”玄德从其言，即差关、张二人去讫；然后与单福、赵云等，共引二千人马出关相迎。
行不数里，只见山后尘头大起，吕旷、吕翔引军来到。两边各射住阵角。玄德出马于旗门下，大呼曰：“来者何人，敢犯吾境？”吕旷出马曰：“吾乃大将吕旷也。奉丞相命，特来擒汝！”玄德大怒，使赵云出马。二将交战，不数合，赵云一枪刺吕旷于马下。玄德麾军掩杀，吕翔抵敌不住，引军便走。正行间，路傍一军突出，为首大将，乃关云长也；冲杀一阵，吕翔折兵大半，夺路走脱。行不到十里，又一军拦住去路，为首大将，挺矛大叫：“张翼德在此！”直取吕翔。翔措手不及，被张飞一矛刺中，翻身落马而死。余众四散奔走。玄德合军追赶，大半多被擒获。玄德班师回县，重待单富，稿赏三军。
却说败军回见曹仁，报说：“二吕被杀，军士多被活捉。”曹仁大惊，与李典商议。典曰：“二将欺敌而亡，今只宜按兵不动，申报丞相，起大兵来征剿，乃为上策。”仁曰：“不然。今二将阵亡，死折许多军马，此仇不可不急报。量新野弹丸之地，何劳丞相大军？”典曰：“刘备人杰也，不可轻视。”仁曰：“公何怯也！”典曰：“兵法云：‘知彼知己，百战百胜。’某非怯战，但恐不能必胜耳。”仁怒曰：“公怀二心耶？吾必欲生擒刘备！”典曰：“将军若去，某守樊城。”仁曰：“汝若不同去，真怀二心矣！”典不得已，只得与曹仁点起二万五千军马，渡河投新野而来。正是：偏裨既有舆尸辱，主将重兴雪耻兵。
未知胜负何如，且听下文分解。', '', '', '', NULL, '', 'indent', 1536852031, '5b9a0fcf1579a3003a415e47', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639171, '三国演义 · 第三十六回 · 玄德用计袭樊城 元直走马荐诸葛', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说曹仁忿怒，遂大起本部之兵，星夜渡河，意欲踏平新野。且说单福得胜回县，谓玄德曰：“曹仁屯兵樊城，今知二将被诛，必起大军来战。”玄德曰：“当何以迎之？”福曰：“彼若尽提兵而来，樊城空虚，可乘间夺之。”玄德问计。福附耳低言如此如此。玄德大喜，预先准备已定。忽报马报说：“曹仁引大军渡河来了。”单福曰：“果不出吾之料。”遂请玄德出军迎敌。两阵对圆，赵云出马唤彼将答话。曹仁命李典出阵，与赵云交锋。约战十数合，李典料敌不过，拨马回阵。云纵马追赶，两翼军射住，遂各罢兵归寨。李典回见曹仁，言：“彼军精锐，不可轻敌，不如回樊城。”曹仁大怒曰：“汝未出军时，已慢吾军心；今又卖阵，罪当斩首！”便喝刀斧手推出李典要斩；众将苦告方免。乃调李典领后军，仁自引兵为前部。次日鸣鼓进军，布成一个阵势，使人问玄德曰：“识吾阵势？”单福便上高处观看毕，谓玄德曰：“此八门金锁阵也。八门者：休、生、伤、杜、景、死、惊、开。如从生门、景门、开门而入则吉；从伤门、惊门、休门而入则伤；从杜门、死们而人则亡。今八门虽布得整齐，只是中间通欠主持。如从东南角上生门击人，往正西景门而出，其阵必乱。”玄德传令，教军士把住阵角，命赵云引五百军从东南而入，径往西出。云得令，挺枪跃马，引兵径投东南角上，呐喊杀入中军。曹仁便投北走。云不追赶，却突出西门，又从西杀转东南角上来。曹仁军大乱。玄德麾军冲击，曹兵大败而退。单福命休追赶，收军自回。却说曹仁输了一阵，方信李典之言；因复请典商议，言：“刘备军中必有能者，吾阵竟为所破。”李典曰：“吾虽在此，甚忧樊城。”曹仁曰：“今晚去劫寨。如得胜，再作计议；如不胜，便退军回樊城。”李典曰：“不可。刘备必有准备。”仁曰：“若如此多疑，何以用兵！”遂不听李典之言。自引军为前队，使李典为后应，当夜二更劫寨。
却说单福正与玄德在寨中议事，忽信风骤起。福曰：“今夜曹仁必来劫寨。”玄德曰：“何以敌之？”福笑曰：“吾已预算定了。”遂密密分拨已毕。至二更，曹仁兵将近寨，只见寨中四围火起，烧着寨栅。曹仁知有准备，急令退军。赵云掩杀将来。仁不及收兵回寨，急望北河而走。将到河边，才欲寻船渡河，岸上一彪军杀到：为首大将，乃张飞也。曹仁死战，李典保护曹仁下船渡河。曹军大半淹死水中。曹仁渡过河面，上岸奔至樊城，令人叫门。只见城上一声鼓响，一将引军而出，大喝曰：“吾已取樊城多时矣！”众惊视之，乃关云长也。仁大惊，拨马便走。云长追杀过来。曹仁又折了好些军马，星夜投许昌。于路打听，方知有单福为军师，设谋定计。不说曹仁败回许昌。且说玄德大获全胜，引军入樊城，县令刘泌出迎。玄德安民已定。那刘泌乃长沙人，亦汉室宗亲，遂请玄德到家，设宴相待。只见一人侍立于侧。玄德视其人器宇轩昂，因问泌曰：“此何人？”泌曰：“此吾之甥寇封，本罗侯寇氏之子也；因父母双亡，故依于此。”玄德爱之，欲嗣为义子。刘泌欣然从之，遂使寇封拜玄德为父，改名刘封。玄德带回，令拜云长、翼德为叔。云长曰：“兄长既有子，何必用螟蛉？后必生乱。”玄德曰：“吾待之如子，彼必事吾如父，何乱之有！”云长不悦。玄德与单福计议，令赵云引一千军守樊城。玄德领众自回新野。
却说曹仁与李典回许都，见曹操，泣拜于地请罪，具言损将折兵之事。操曰：“胜负乃军家之常。但不知谁为刘备画策？”曹仁言是单福之计。操曰：“单福何人也？”程昱笑曰：“此非单福也。此人幼好学击剑；中平末年，尝为人报仇杀人，披发涂面而走，为吏所获；问其姓名不答，吏乃缚于车上，击鼓行于市，今市人识之，虽有识者不敢言，而同伴窃解救之。乃更姓名而逃，折节向学，遍访名师，尝与司马徽谈论。此人乃颍川徐庶，字元直。单福乃其托名耳。”操曰：“徐庶之才，比君何如？”昱曰：“十倍于昱。”操曰：“惜乎贤士归于刘备！羽翼成矣？奈何？”昱曰：“徐庶虽在彼，丞相要用，召来不难。”操曰：“安得彼来归？”昱曰：“徐庶为人至孝。幼丧其父，止有老母在堂。现今其弟徐康已亡，老母无人侍养。丞相可使人赚其母至许昌，令作书召其子，则徐庶必至矣。”
操大喜，使人星夜前去取徐庶母。不一日，取至，操厚待之。因谓之曰：“闻令嗣徐元直，乃天下奇才也。今在新野，助逆臣刘备，背叛朝廷，正犹美玉落于污泥之中，诚为可惜。今烦老母作书，唤回许都，吾于天子之前保奏，必有重赏。”遂命左右捧过文房四宝，令徐母作书。徐母曰：“刘备何如人也？”操曰：“沛郡小辈，妄称‘皇叔’，全无信义，所谓外君子而内小人者也。徐母厉声曰：“汝何虚诳之甚也！吾久闻玄德乃中山靖王之后，孝景皇帝阁下玄孙，屈身下士，恭己待人，仁声素著，世之黄童、白叟、牧子、樵夫皆知其名：真当世之英雄也。吾儿辅之，得其主矣。汝虽托名汉相，实为汉贼。乃反以玄德为逆臣，欲使吾几背明投暗，岂不自耻乎！”言讫，取石砚便打曹操。操大怒，叱武士执徐母出，将斩之。程昱急止之，入谏操曰：“徐母触忤丞相者，欲求死也。丞相若杀之，则招不义之名，而成徐母之德。徐母既死，徐庶必死心助刘备以报仇矣；不如留之，使徐庶身心两处，纵使助刘备，亦不尽力也。且留得徐母在，昱自有计赚徐庶至此，以辅丞相。”操然其言，遂不杀徐母，送于别室养之。程昱日往问候，诈言曾与徐庶结为兄弟，待徐母如亲母；时常馈送物件，必具手启。徐母因亦作手启答之。程昱赚得徐母笔迹，乃仿其字体，诈修家书一封，差一心腹人，持书径奔新野县，寻问“单福”行幕。军士引见徐庶。庶知母有家书至，急唤入问之。来人曰：“某乃馆下走卒，奉老夫人言语，有书附达。”庶拆封视之。书曰：“近汝弟康丧，举目无亲。正悲凄间，不期曹丞相使人赚至许昌，言汝背反，下我于缧绁，赖程昱等救免。若得汝降，能免我死。如书到日，可念劬劳之恩，星夜前来，以全孝道；然后徐图归耕故园，免遭大祸。吾今命若悬丝，专望救援！更不多嘱。”徐庶览毕，泪如泉涌。持书来见玄德曰：“某本颍川徐庶，字元直；为因逃难，更名单福。前闻刘景升招贤纳士，特往见之；及与论事，方知是无用之人，故作书别之。夤夜至司马水镜庄上，诉说其事。水镜深责庶不识主，因说刘豫州在此，何不事之？庶故作狂歌于市，以动使君；幸蒙不弃，即赐重用。争奈老母今被曹操奸计，赚至许昌囚禁，将欲加害。老母手书来唤，庶不容不去。非不欲效犬马之劳，以报使君；奈慈亲被执，不得尽力。今当告归，容图后会。”玄德闻言大哭曰：“子母乃天性之亲，元直无以备为念。待与老夫人相见之后，或者再得奉教。”徐庶便拜谢欲行。玄德曰：“乞再聚一宵，来日饯行。”孙乾密谓玄德曰：“元直天下奇才，久在新野，尽知我军中虚实。今若使归曹操，必然重用，我其危矣。主公宜苦留之，切勿放去。操见元直不去，必斩其母。元直知母死，必为母报仇。力攻曹操也。”玄德曰：“不可。使人杀其母，而吾用其子，不仁也；留之不使去，以绝其子母之道，不义也。吾宁死，不为不仁不义之事。”众皆感叹。
玄德请徐庶饮酒，庶曰：“今闻老母被囚，虽金波玉液不能下咽矣。”玄德曰：“备闻公将去，如失左右手，虽龙肝凤髓，亦不甘味。”二人相对而泣，坐以待旦。诸将已于郭外安排筵席饯行。玄德与徐庶并马出城，至长亭，下马相辞。玄德举杯谓徐庶曰：“备分浅缘薄，不能与先生相聚。望先生善事新主，以成功名。”庶泣曰：“某才微智浅，深荷使君重用。今不幸半途而别，实为老母故也。纵使曹操相逼，庶亦终身不设一谋。”玄德曰：“先生既去，刘备亦将远遁山林矣。”庶曰：“某所以与使君共图王霸之业者，恃此方寸耳；今以老母之故，方寸乱矣，纵使在此，无益于事。使君宜别求高贤辅佐，共图大业，何便灰心如此？”玄德曰：“天下高贤，无有出先生右者。”庶曰：“某樗栎庸材，何敢当此重誉。”临别，又顾谓诸将曰：“愿诸公善事使君，以图名垂竹帛，功标青史，切勿效庶之无始终也。”诸将无不伤感。玄德不忍相离，送了一程，又送一程。庶辞曰：“不劳使君远送，庶就此告别。”玄德就马上执庶之手曰：“先生此去，天各一方，未知相会却在何日！”说罢，泪如雨下。庶亦涕泣而别。玄德立马于林畔，看徐庶乘马与从者匆匆而去。玄德哭曰：“元直去矣！吾将奈何？”凝泪而望，却被一树林隔断。玄德以鞭指曰：“吾欲尽伐此处树木。”众问何故。玄德曰：“因阻吾望徐元直之目也。”
正望间，忽见徐庶拍马而回。玄德曰：“元直复回，莫非无去意乎？”遂欣然拍马向前迎问曰：“先生此回，必有主意。”庶勒马谓玄德曰：“某因心绪如麻，忘却一语：此间有一奇士，只在襄阳城外二十里隆中。使君何不求之？”玄德曰：“敢烦元直为备请来相见。”庶曰：“此人不可屈致，使君可亲往求之。若得此人，无异周得吕望、汉得张良也。”玄德曰：“此人比先生才德何如？”庶曰：“以某比之，譬犹驽马并麒麟、寒鸦配鸾凤耳。此人每尝自比管仲，乐毅；以吾观之，管、乐殆不及此人。此人有经天纬地之才，盖天下一人也！”玄德喜曰：“愿闻此人姓名。”庶曰：“此人乃琅琊阳都人，覆姓诸葛，名亮，字孔明，乃汉司隶校尉诸葛丰之后。其父名珪，字子贡，为泰山郡丞，早卒；亮从其叔玄。玄与荆州刘景升有旧，因往依之，遂家于襄阳。后玄卒，亮与弟诸葛均躬耕于南阳。尝好为《梁父吟》。所居之地有一冈，名卧龙冈，因自号为‘卧龙先生’。此人乃绝代奇才，使君急宜枉驾见之。若此人肯相辅佐，何愁天下不定乎！”玄德曰：“昔水镜先生曾为备言：‘伏龙、凤雏，两人得一，可安天下。’今所云莫非即‘伏龙、凤雏’乎？”庶曰：“凤雏乃襄阳庞统也。伏龙正是诸葛孔明。”玄德踊跃曰：“今日方知伏龙、凤雏之语。何期大贤只在目前！非先生言，备有眼如盲也！”后人有赞徐庶走马荐诸葛诗曰：“痛恨高贤不再逢，临岐泣别两情浓。片言却似春雷震，能使南阳起卧龙。”徐庶荐了孔明，再别玄德，策马而去。玄德闻徐庶之语，方悟司马德操之言，似醉方醒，如梦初觉。引众将回至新野，便具厚币，同关、张前去南阳请孔明。
且说徐庶既别玄德，感其留恋之情，恐孔明不肯出山辅之，遂乘马直至卧龙冈下，入草庐见孔明。孔明问其来意。庶曰：“庶本欲事刘豫州，奈老母为曹操所囚，驰书来召，只得舍之而往。临行时，将公荐与玄德。玄德即日将来奉谒，望公勿推阻，即展平生之大才以辅之，幸甚！”孔明闻言作色曰：“君以我为享祭之牺牲乎！”说罢，拂袖而入。庶羞惭而退，上马趱程，赴许昌见母。正是：嘱友一言因爱主，赴家千里为思亲。
未知后事若何，下文便见。', '', '', '', NULL, '', 'indent', 1536852060, '5b9a0fe91b69e6005b946de9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639172, '三国演义 · 第三十七回 · 司马徽再荐名士 刘玄德三顾草庐', NULL, 5, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说徐庶趱程赴许昌。曹操知徐庶已到，遂命荀彧、程昱等一班谋士往迎之。庶入相府拜见曹操。操曰：“公乃高明之士，何故屈身而事刘备乎？”庶曰：“某幼逃难，流落江湖，偶至新野，遂与玄德交厚，老母在此，幸蒙慈念，不胜愧感。”操曰：“公今至此，正可晨昏侍奉令堂，吾亦得听清诲矣。”庶拜谢而出。急往见其母，泣拜于堂下。母大惊曰：“汝何故至此？”庶曰：“近于新野事刘豫州；因得母书，故星夜至此。”徐母勃然大怒，拍案骂曰：“辱子飘荡江湖数年，吾以为汝学业有进，何其反不如初也！汝既读书，须知忠孝不能两全。岂不识曹操欺君罔上之贼？刘玄德仁义布于四海，况又汉室之胄，汝既事之，得其主矣，今凭一纸伪书，更不详察，遂弃明投暗，自取恶名，真愚夫也！吾有何面目与汝相见！汝玷辱祖宗，空生于天地间耳！”骂得徐庶拜伏于地，不敢仰视，母自转入屏风后去了。少顷，家人出报曰：“老夫人自缢于梁间。”徐庶慌入救时，母气已绝。后人有《徐母赞》曰：“贤哉徐母，流芳千古：守节无亏，于家有补；教子多方，处身自苦；气若丘山，义出肺腑；赞美“豫州”，毁触魏武；不畏鼎镬，不惧刀斧；唯恐后嗣，玷辱先祖。伏剑同流，断机堪伍；生得其名，死得其所：贤哉徐母，流芳千古！”徐虑见母已死，哭绝于地，良久方苏。曹操使人赍礼吊问，又亲往祭奠。徐庶葬母柩于许昌之南原，居丧守墓。凡曹操所赐，庶俱不受。
时操欲商议南征。荀□谏曰：“天寒未可用兵；姑待春暖，方可长驱大进。”操从之，乃引漳河之水作一池，名玄武池，于内教练水军，准备南征。
却说玄德正安排礼物，欲往隆中谒诸葛亮，忽人报：“门外有一先生，峨冠博带，道貌非常，特来相探。”玄德曰：“此莫非即孔明否？”遂整衣出迎。视之，乃司马徽也。玄德大喜，请入后堂高坐，拜问曰：“备自别仙颜，因军务倥偬，有失拜访。今得光降，大慰仰慕之私。”徽曰：“闻徐元直在此，特来一会。”玄德曰：“近因曹操囚其母，似母遣人驰书，唤回许昌去矣。”徽曰：“此中曹操之计矣！吾素闻徐母最贤，虽为操所囚，必不肯驰书召其子；此书必诈也。元直不去，其母尚存；今若去，母必死矣！”玄德惊问其故，徽曰：“徐母高义，必羞见其子也。”玄德曰：“元直临行，荐南阳诸葛亮，其人若何？”徽笑曰：“元直欲去，自去便了，何又惹他出来呕心血也？”玄德曰：“先生何出此言？”徽曰：“孔明与博陵崔州平、颍川石广元、汝南孟公威与徐元直四人为密友。此四人务于精纯，惟孔明独观其大略。尝抱膝长吟，而指四人曰：“公等仕进可至刺史、郡守。众问孔明之志若何，孔明但笑而不答。每常自比管仲、乐毅，其才不可量也。”玄德曰：“何颍川之多贤乎！”徽曰：“昔有殷馗善观天文，尝谓‘群星聚于颍分，其地必多贤士。’”时云长在侧曰：“某闻管仲、乐毅乃春秋、战国名人，功盖寰宇；孔明自比此二人，毋乃太过？”徽笑曰：“以吾观之，不当比此二人；我欲另以二人比之。”云长问：“那二人？”徽曰：“可比兴周八百年之姜子牙、旺汉四百年之张子房也。”众皆愕然。徽下阶相辞欲行，玄德留之不住。徽出门仰天大笑曰：“卧龙虽得其主，不得其时，惜哉！”言罢，飘然而去。玄德叹曰：“真隐居贤士也！”
次日，玄德同关、张并从人等来隆中。遥望山畔数人，荷锄耕于田间，而作歌曰：“苍天如圆盖，陆地似棋局；世人黑白分，往来争荣辱：荣者自安安，辱者定碌碌。南阳有隐居，高眠卧不足！”玄德闻歌，勒马唤农夫问曰：“此歌何人所作？”答曰：“乃卧龙先生所作也。”玄德曰：“卧龙先生住何处？”农夫曰：“自此山之南，一带高冈，乃卧龙冈也。冈前疏林内茅庐中，即诸葛先生高卧之地。”玄德谢之，策马前行。不数里，遥望卧龙冈，果然清景异常。后人有古风一篇，单道卧龙居处。诗曰：“襄阳城西二十里，一带高冈枕流水：高冈屈曲压云根，流水潺湲飞石髓；势若困龙石上蟠，形如单凤松阴里；柴门半掩闭茅庐，中有高人卧不起。修竹交加列翠屏，四时篱落野花馨；床头堆积皆黄卷，座上往来无白丁；叩户苍猿时献果，守门老鹤夜听经；囊里名琴藏古锦，壁间宝剑挂七星。庐中先生独幽雅，闲来亲自勤耕稼：专待春雷惊梦回，一声长啸安天下。”玄德来到庄前，下马亲叩柴门，一童出问。玄德曰：“汉左将军、宜城亭、侯领豫州牧、皇叔刘备，特来拜见先生。”童子曰：“我记不得许多名字。”玄德曰：“你只说刘备来访。”童子曰：“先生今早少出。”玄德曰：“何处去了？”童子曰：“踪迹不定，不知何处去了。”玄德曰：“几时归？”童子曰：“归期亦不定，或三五日，或十数日。”玄德惆怅不已。张飞曰：”既不见，自归去罢了。”玄德曰：“且待片时。”云长曰：“不如且归，再使人来探听。”玄德从其言，嘱付童子：“如先生回，可言刘备拜访。”遂上马，行数里，勒马回观隆中景物，果然山不高而秀雅，水不深而澄清；地不广而平坦，林不大而茂盛；猿鹤相亲，松篁交翠。观之不已，忽见一人，容貌轩昂，丰姿俊爽，头戴逍遥巾，身穿皂布袍，杖藜从山僻小路而来。玄德曰：“此必卧龙先生也！”急下马向前施礼，问曰：“先生非卧龙否？”其人曰：“将军是谁？”玄德曰：“刘备也。”其人曰：“吾非孔明，乃孔明之友，博陵崔州平也。”玄德曰：“久闻大名，幸得相遇。乞即席地权坐，请教一言。”二人对坐于林间石上，关、张侍立于侧。州平曰：“将军何故欲见孔明？”玄德曰：“方今天下大乱，四方云扰，欲见孔明，求安邦定国之策耳。”州平笑曰：“公以定乱为主，虽是仁心，但自古以来，治乱无常。自高祖斩蛇起义，诛无道秦，是由乱而入治也；至哀、平之世二百年，太平日久，王莽篡逆，又由治而入乱；光武中兴，重整基业，复由乱而入治；至今二百年，民安已久，故干戈又复四起：此正由治入乱之时，未可猝定也。将军欲使孔明斡旋天地，补缀乾坤，恐不易为，徒费心力耳。岂不‘闻顺天者逸，逆天者劳’；‘数之所在，理不得而夺之；命之所在，人不得而强之’乎？”玄德曰：“先生所言，诚为高见。但备身为汉胄，合当匡扶汉室，何敢委之数与命？”州平曰：“山野之夫，不足与论天下事，适承明问，故妄言之。”玄德曰：“蒙先生见教。但不知孔明往何处去了？”州平曰：“吾亦欲访之，正不知其何往。”玄德曰：“请先生同至敝县，若何？”州平曰：“愚性颇乐闲散，无意功名久矣；容他日再见。”言讫，长揖而去。玄德与关、张上马而行。张飞曰：“孔明又访不着，却遇此腐儒，闲谈许久！”玄德曰：“此亦隐者之言也。”
三人回至新野，过了数日，玄德使人探听孔明。回报曰：“卧龙先生已回矣。”玄德便教备马。张飞曰：“量一村夫，何必哥哥自去，可使人唤来便了。”玄德叱曰：“汝岂不闻孟子云：欲见贤而不以其道，犹欲其入而闭之门也。孔明当世大贤，岂可召乎！”遂上马再往访孔明。关、张亦乘马相随。时值隆冬，天气严寒，彤云密布。行无数里，忽然朔风凛凛，瑞雪霏霏：山如玉簇，林似银妆。张飞曰：“天寒地冻，尚不用兵，岂宜远见无益之人乎！不如回新野以避风雪。”玄德曰：“吾正欲使孔明知我殷勤之意。如弟辈怕冷，可先回去。”飞曰：“死且不怕，岂怕冷乎！但恐哥哥空劳神思。”玄德曰：“勿多言，只相随同去。”将近茅庐，忽闻路傍酒店中有人作歌。玄德立马听之。其歌曰：“壮士功名尚未成，呜呼久不遇阳春！君不见：东海者叟辞荆榛，后车遂与文王亲；八百诸侯不期会，白鱼入舟涉孟津；牧野一战血流杵，鹰扬伟烈冠武臣。又不见：高阳酒徒起草中，长楫芒砀隆准公；高谈王霸惊人耳，辍洗延坐钦英风；东下齐城七十二，天下无人能继踪。二人功迹尚如此，至今谁肯论英雄？”歌罢，又有一人击桌而歌。其歌曰：“吾皇提剑清寰海，创业垂基四百载；桓灵季业火德衰，奸臣贼子调鼎鼐。青蛇飞下御座傍，又见妖虹降玉堂；群盗四方如蚁聚，奸雄百辈皆鹰扬，吾侪长啸空拍手，闷来村店饮村酒；独善其身尽日安，何须千古名不朽！”
二人歌罢，抚掌大笑。玄德曰：“卧龙其在此间乎！”遂下马入店。见二人凭桌对饮：上首者白面长须，下首者清奇古貌。玄德揖而问曰：“二公谁是卧龙先生？”长须者曰：“公何人？欲寻卧龙何干？”玄德曰：“某乃刘备也。欲访先生，求济世安民之术。”长须者曰：“我等非卧龙，皆卧龙之友也：吾乃颍川石广元，此位是汝南孟公威。”玄德喜曰：“备久闻二公大名，幸得邂逅。今有随行马匹在此，敢请二公同往卧龙庄上一谈。”广元曰：“吾等皆山野慵懒之徒，不省治国安民之事，不劳下问。明公请自上马，寻访卧龙。”
玄德乃辞二人，上马投卧龙冈来。到庄前下马，扣门问童子曰：“先生今日在庄否？”童子曰：“现在堂上读书。”玄德大喜，遂跟童子而入。至中门，只见门上大书一联云：“淡泊以明志。宁静而致远。”玄德正看间，忽闻吟咏之声，乃立于门侧窥之，见草堂之上，一少年拥炉抱膝，歌曰：“凤翱翔于千仞兮，非梧不栖；士伏处于一方兮，非主不依。乐躬耕于陇亩兮，吾爱吾庐；聊寄傲于琴书兮，以待天时。”
玄德待其歌罢，上草堂施礼曰：“备久慕先生，无缘拜会。昨因徐元直称荐，敬至仙庄，不遇空回。今特冒风雪而来。得瞻道貌，实为万幸，”那少年慌忙答礼曰：“将军莫非刘豫州，欲见家兄否？”玄德惊讶曰：“先生又非卧龙耶？”少年曰：“某乃卧龙之弟诸葛均也。愚兄弟三人：长兄诸葛瑾，现在江东孙仲谋处为幕宾；孔明乃二家兄。”玄德曰：“卧龙今在家否？”均曰：“昨为崔州平相约，出外闲游去矣。”玄德曰：“何处闲游？”均曰：“或驾小舟游于江湖之中，或访僧道于山岭之上，或寻朋友于村落之间，或乐琴棋于洞府之内：往来莫测，不知去所。”玄德曰：“刘备直如此缘分浅薄，两番不遇大贤！”均曰：“少坐献茶。”张飞曰：“那先生既不在，请哥哥上马。”玄德曰：“我既到此间，如何无一语而回？”因问诸葛均曰：“闻令兄卧龙先生熟谙韬略，日看兵书，可得闻乎？”均曰：“不知。”张飞曰：“问他则甚！风雪甚紧，不如早归。”玄德叱止之。均曰：“家兄不在，不敢久留车骑；容日却来回礼。”玄德曰：“岂敢望先生枉驾。数日之后，备当再至。愿借纸笔作一书，留达令兄，以表刘备殷勤之意。”均遂进文房四宝。玄德呵开冻笔，拂展云笺，写书曰：“备久慕高名，两次晋谒，不遇空回，惆怅何似！窃念备汉朝苗裔，滥叨名爵，伏睹朝廷陵替，纲纪崩摧，群雄乱国，恶党欺君，备心胆俱裂。虽有匡济之诚，实乏经纶之策。仰望先生仁慈忠义，慨然展吕望之大才，施子房之鸿略，天下幸甚！社稷幸甚！先此布达，再容斋戒薰沐，特拜尊颜，面倾鄙悃。统希鉴原。”玄德写罢，递与诸葛均收了，拜辞出门。均送出，玄德再三殷勤致意而别。方上马欲行，忽见童子招手篱外，叫曰：“老先生来也。”玄德视之，见小桥之西，一人暖帽遮头，狐裘蔽体，骑着一驴，后随一青衣小童，携一葫芦酒，踏雪而来；转过小桥，口吟诗一首。诗曰：“一夜北风寒，万里彤云厚。长空雪乱飘，改尽江山旧。仰面观太虚，疑是玉龙斗。纷纷鳞甲飞，顷刻遍宇宙。骑驴过小桥，独叹梅花瘦！”玄德闻歌曰：“此真卧龙矣！”滚鞍下马，向前施礼曰：“先生冒寒不易！刘备等候久矣！”那人慌忙下驴答礼。
诸葛均在后曰：“此非卧龙家兄，乃家兄岳父黄承彦也。”玄德曰：“适间所吟之句，极其高妙。”承彦曰：“老夫在小婿家观《梁父吟》，记得这一篇；适过小桥，偶见篱落间梅花，故感而诵之。不期为尊客所闻。”玄德曰：“曾见令婿否？”承彦曰：“便是老夫也来看他。”玄德闻言，辞别承彦，上马而归。正值风雪又大，回望卧龙冈，悒怏不已。后人有诗单道玄德风雪访孔明。诗曰：“一天风雪访贤良，不遇空回意感伤。冻合溪桥山石滑，寒侵鞍马路途长。当头片片梨花落，扑面纷纷柳絮狂。回首停鞭遥望处，烂银堆满卧龙冈。”
玄德回新野之后，光阴荏苒，又早新春。乃令卜者揲蓍，选择吉期，斋戒三日，薰沐更衣，再往卧龙冈谒孔明。关、张闻之不悦，遂一齐入谏玄德。正是：高贤未服英雄志，屈节偏生杰士疑。
未知其言若何，下文便晓。', '', '', '', NULL, '', 'indent', 1536852579, '5b9a10071b69e6005b946f50', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639173, '三国演义 · 第三十八回 · 定三分隆中决策 战长江孙氏报仇', NULL, 19, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说玄德访孔明两次不遇，欲再往访之。关公曰：“兄长两次亲往拜谒，其礼太过矣。想诸葛亮有虚名而无实学，故避而不敢见。兄何惑于斯人之甚也！”玄德曰：“不然，昔齐桓公欲见东郭野人，五反而方得一面。况吾欲见大贤耶？”张飞曰：“哥哥差矣。量此村夫，何足为大贤；今番不须哥哥去；他如不来，我只用一条麻绳缚将来！”玄德叱曰：“汝岂不闻周文王谒姜子牙之事乎？文王且如此敬贤，汝何太无礼！今番汝休去，我自与云长去。”飞曰：“既两位哥哥都去，小弟如何落后！”玄德曰：“汝若同往，不可失礼。”飞应诺。
于是三人乘马引从者往隆中。离草庐半里之外，玄德便下马步行，正遇诸葛均。玄德忙施礼，问曰：“令兄在庄否？”均曰：“昨暮方归。将军今日可与相见。”言罢，飘然自去。玄德曰：“今番侥幸得见先生矣！”张飞曰：“此人无礼！便引我等到庄也不妨，何故竟自去了！”玄德曰：“彼各有事，岂可相强。”三人来到庄前叩门，童子开门出问。玄德曰：“有劳仙童转报：刘备专来拜见先生。”童子曰：“今日先生虽在家，但今在草堂上昼寝未醒。”玄德曰：“既如此，且休通报。”分付关、张二人，只在门首等着。玄德徐步而入，见先生仰卧于草堂几席之上。玄德拱立阶下。半晌，先生未醒。关、张在外立久，不见动静，入见玄德犹然侍立。张飞大怒，谓云长曰：“这先生如何傲慢！见我哥哥侍立阶下，他竟高卧，推睡不起！等我去屋后放一把火，看他起不起！”云长再三劝住。玄德仍命二人出门外等候。望堂上时，见先生翻身将起，忽又朝里壁睡着。童子欲报。玄德曰：“且勿惊动。”又立了一个时辰，孔明才醒，口吟诗曰：“大梦谁先觉？平生我自知，草堂春睡足，窗外日迟迟。”孔明吟罢，翻身问童子曰：“有俗客来否？”童子曰：“刘皇叔在此，立候多时。”孔明乃起身曰：“何不早报！尚容更衣。”遂转入后堂。又半晌，方整衣冠出迎。
玄德见孔明身长八尺，面如冠玉，头戴纶巾，身披鹤氅，飘飘然有神仙之概。玄德下拜曰：“汉室末胄、涿郡愚夫，久闻先生大名，如雷贯耳。昨两次晋谒，不得一见，已书贱名于文几，未审得入览否？”孔明曰：“南阳野人，疏懒性成，屡蒙将军枉临，不胜愧赧。”二人叙礼毕，分宾主而坐，童子献茶。茶罢，孔明曰：“昨观书意，足见将军忧民忧国之心；但恨亮年幼才疏，有误下问。”玄德曰：“司马德操之言，徐元直之语，岂虚谈哉？望先生不弃鄙贱，曲赐教诲。”孔明曰：“德操、元直，世之高士。亮乃一耕夫耳，安敢谈天下事？二公谬举矣。将军奈何舍美玉而求顽石乎？”玄德曰：“大丈夫抱经世奇才，岂可空老于林泉之下？愿先生以天下苍生为念，开备愚鲁而赐教。”孔明笑曰：“愿闻将军之志。”玄德屏人促席而告曰：“汉室倾颓，奸臣窃命，备不量力，欲伸大义于天下，而智术浅短，迄无所就。惟先生开其愚而拯其厄，实为万幸！”孔明曰：“自董卓造逆以来，天下豪杰并起。曹操势不及袁绍，而竟能克绍者，非惟天时，抑亦人谋也。今操已拥百万之众，挟天子以令诸侯，此诚不可与争锋。孙权据有江东，已历三世，国险而民附，此可用为援而不可图也。荆州北据汉、沔，利尽南海，东连吴会，西通巴、蜀，此用武之地，非其主不能守；是殆天所以资将军，将军岂有意乎？益州险塞，沃野千里，天府之国，高祖因之以成帝业；今刘璋暗弱，民殷国富，而不知存恤，智能之士，思得明君。将军既帝室之胄，信义著于四海，总揽英雄，思贤如渴，若跨有荆、益，保其岩阻，西和诸戎，南抚彝、越，外结孙权，内修政理；待天下有变，则命一上将将荆州之兵以向宛、洛，将军身率益州之众以出秦川，百姓有不箪食壶浆以迎将军者乎？诚如是，则大业可成，汉室可兴矣。此亮所以为将军谋者也。惟将军图之。”言罢，命童子取出画一轴，挂于中堂，指谓玄德曰：“此西川五十四州之图也。将军欲成霸业，北让曹操占天时，南让孙权占地利，将军可占人和。先取荆州为家，后即取西川建基业，以成鼎足之势，然后可图中原也。”玄德闻言，避席拱手谢曰：“先生之言，顿开茅塞，使备如拨云雾而睹青天。但荆州刘表、益州刘璋，皆汉室宗亲，备安忍夺之？”孔明曰：“亮夜观天象，刘表不久人世；刘璋非立业之主：久后必归将军。”玄德闻言，顿首拜谢。只这一席话，乃孔明未出茅庐，已知三分天下，真万古之人不及也！后人有诗赞曰：“豫州当日叹孤穷，何幸南阳有卧龙！欲识他年分鼎处，先生笑指画图中。”玄德拜请孔明曰：“备虽名微德薄，愿先生不弃鄙贱，出山相助。备当拱听明诲。”孔明曰：“亮久乐耕锄，懒于应世，不能奉命。”玄德泣曰：“先生不出，如苍生何！”言毕，泪沾袍袖，衣襟尽湿。孔明见其意甚诚，乃曰：“将军既不相弃，愿效犬马之劳。”玄德大喜，遂命关、张入，拜献金帛礼物。孔明固辞不受。玄德曰：“此非聘大贤之礼，但表刘备寸心耳。”孔明方受。于是玄德等在庄中共宿一宵。
次日，诸葛均回，孔明嘱付曰：“吾受刘皇叔三顾之恩，不容不出。汝可躬耕于此，勿得荒芜田亩。待我功成之日，即当归隐。”后人有诗叹曰：“身未升腾思退步，功成应忆去时言。只因先主丁宁后，星落秋风五丈原。”又有古风一篇曰：“高皇手提三尺雪，芒砀白蛇夜流血；平秦灭楚入咸阳，二百年前几断绝。
大哉光武兴洛阳，传至桓灵又崩裂；献帝迁都幸许昌，纷纷四海生豪杰：
曹操专权得天时，江东孙氏开鸿业；孤穷玄德走天下，独居新野愁民厄。
南阳卧龙有大志，腹内雄兵分正奇；只因徐庶临行语，茅庐三顾心相知。
先生尔时年三九，收拾琴书离陇亩；先取荆州后取川，大展经纶补天手；
纵横舌上鼓风雷，谈笑胸中换星斗；龙骧虎视安乾坤，万古千秋名不朽！”
玄德等三人别了诸葛均，与孔明同归新野。
玄德待孔明如师，食则同桌，寝则同榻，终日共论天下之事，孔明曰：“曹操于冀州作玄武池以练水军，必有侵江南之意。可密令人过江探听虚实。”玄德从之，使人往江东探听。
却说孙权自孙策死后，据住江东，承父兄基业，广纳贤士，开宾馆于吴会，命顾雍、张纮延接四方宾客。连年以来，你我相荐。时有会稽阚泽，字德润；彭城严畯，字曼才；沛县薛综，字敬文；汝阳程秉，字德枢；吴郡朱桓，字休穆；陆绩，字公纪；吴人张温，字惠恕；乌伤骆统，字公绪；乌程吾粲，字孔休：此数人皆至江东，孙权敬礼甚厚。又得良将数人：乃汝南吕蒙，字子明；吴郡陆逊，宇伯言；琅琊徐盛，字文向；东郡潘璋，字文珪；庐江丁奉，字承渊。文武诸人，共相辅佐，由此江东称得人之盛。
建安七年，曹操破袁绍，遣使往江东，命孙权遣子入朝随驾。权犹豫未决。吴太夫人命周瑜、张昭等面议。张昭曰：“操欲令我遣子入朝，是牵制诸侯之法也。然若不令去，恐其兴兵下江东，势必危矣。”周瑜曰：“将军承父兄遗业，兼六郡之众，兵精粮足，将士用命，有何逼迫而欲送质于人？质一入，不得不与曹氏连和；彼有命召，不得不往：如此，则见制于人也。不如勿遣，徐观其变，别以良策御之。”吴太夫人曰：“公瑾之言是也。”权遂从其言，谢使者，不遣子。自此曹操有下江南之意。但正值北方未宁，无暇南征。
建安八年十一月，孙权引兵伐黄祖，战于大江之中。祖军败绩。权部将凌操，轻舟当先，杀入夏口，被黄祖部将甘宁一箭射死。凌操子凌统，时年方十五岁，奋力往夺父尸而归。权见风色不利，收军还东吴。
却说孙权弟孙翊为丹阳太守，翊性刚好酒，醉后尝鞭挞士卒。丹阳督将妫览、郡丞戴员二人，常有杀翊之心；乃与翊从人边洪结为心腹，共谋杀翊。时诸将县令，皆集丹阳，翊设宴相待。翊妻徐氏美而慧，极善卜《易》，是日卜一卦，其象大凶，劝翊勿出会客。翊不从，遂与众大会。至晚席散，边洪带刀跟出门外，即抽刀砍死孙翊。妫览、戴员乃归罪边洪，斩之于市。二人乘势掳翊家资侍妾。妫览见徐氏美貌，乃谓之曰：“吾为汝夫报仇，汝当从我；不从则死。”徐氏曰：“夫死未几，不忍便相从；可待至晦日，设祭除服，然后成亲未迟。”览从之。徐氏乃密召孙翊心腹旧将孙高、傅婴二人入府，泣告曰：“先夫在日，常言二公忠义。今妫、戴二贼，谋杀我夫，只归罪边洪，将我家资童婢尽皆分去。妫览又欲强占妾身，妾已诈许之，以安其心。二将军可差人星夜报知吴侯，一面设密计以图二贼，雪此仇辱，生死衔恩！”言毕再拜。孙高、傅婴皆泣曰：“我等平日感府君恩遇，今日所以不即死难者，正欲为复仇计耳。夫人所命，敢不效力！”于是密遣心腹使者往报孙权。
至晦日，徐氏先召孙、傅二人，伏于密室韩幕之中，然后设祭于堂上。祭毕，即除去孝服，沐浴薰香，浓妆艳裹，言笑自若。妫览闻之甚喜。至夜，徐氏遗婢妾请览入府，设席堂中饮酒。饮既醉，徐氏乃邀览入密室。览喜，乘醉而入。徐氏大呼曰：“孙、傅二将军何在！”二人即从帏幕中持刀跃出。妫览措手不及，被傅婴一刀砍倒在地，孙高再复一刀，登时杀死。徐氏复传请戴员赴宴。员入府来，至堂中，亦被孙、傅二将所杀。一面使人诛戮二贼家小，及其余党。徐氏遂重穿孝服，将妫览、戴员首级，祭于孙翊灵前。不一日，孙权自领军马至丹阳，见徐氏已杀妫、戴二贼，乃封孙高、傅婴为牙门将，令守丹阳，取徐氏归家养老。江东人无不称徐氏之德。后人有诗赞曰：“才节双全世所无，奸回一旦受摧锄。庸臣从贼忠臣死，不及东吴女丈夫。”
且说东吴各处山贼，尽皆平复。大江之中，有战船七千余只。孙权拜周瑜为大都督，总统江东水陆军马。建安十二年，冬十月，权母吴太夫人病危，召周瑜、张昭二人至，谓曰：“我本吴人，幼亡父母，与弟吴景徒居越中。后嫁与孙氏，生四子。长子策生时，吾梦月入怀；后生次子权，又梦日入怀。卜者云：梦日月入怀者，其子大贵。不幸策早丧，今将江东基业付权。望公等同心助之，吾死不朽矣！”又嘱权曰：“汝事子布、公瑾以师傅之礼，不可怠慢。吾妹与我共嫁汝父，则亦汝之母也；吾死之后，事吾妹如事我。汝妹亦当恩养，择佳婿以嫁之。”言讫遂终。孙权哀哭，具丧葬之礼，自不必说。
至来年春，孙权商议欲伐黄祖。张昭曰：“居丧未及期年，不可动兵。”周瑜曰：“报仇雪恨，何待期年？”权犹豫未决。适平北都尉吕蒙入见，告权曰：“某把龙湫水口，忽有黄祖部将甘宁来降。某细询之：宁字兴霸，巴郡临江人也；颇通书史，有气力，好游侠；尝招合亡命，纵横于江湖之中；腰悬铜铃，人听铃声，尽皆避之。又尝以西川锦作帆幔，时人皆称为‘锦帆贼’。后悔前非，改行从善，引众投刘表。见表不能成事，即欲来投东吴，却被黄祖留住在夏口。前东吴破祖时，祖得甘宁之力，救回夏口；乃待宁甚薄。都督苏飞屡荐宁于祖。祖曰：宁乃劫江之贼，岂可重用！宁因此怀恨。苏飞知其意，乃置酒邀宁到家，谓之曰：吾荐公数次，奈主公不能用。日月逾迈，人生几何，宜自远图。吾当保公为邾县长，自作去就之计。宁因此得过夏口，欲投江东，恐江东恨其救黄祖杀凌操之事。某具言主公求贤若渴，不记旧恨；况各为其主，又何恨焉？宁欣然引众渡江，来见主公。乞钧旨定夺。”孙权大喜曰：“吾得兴霸，破黄祖必矣。”遂命吕蒙引甘宁入见。参拜已毕，权曰：“兴霸来此，大获我心，岂有记恨之理？请无怀疑。愿教我以破黄祖之策。”宁曰：“今汉祚日危，曹操终必篡窃。南荆之地，操所必争也。刘表无远虑，其子又愚劣，不能承业传基，明公宜早图之；若迟，则操先图之矣。今宜先取黄祖。祖今年老昏迈，务于货利；侵求吏民，人心皆怨；战具不修，军无法律。明公若往攻之，其势必破。既破祖军，鼓行而西，据楚关而图巴、蜀，霸业可定也。”孙权曰：“此金玉之论也！”遂命周瑜为大都督，总水陆军兵；吕蒙为前部先锋；董袭与甘宁为副将；权自领大军十万，征讨黄祖。
细作探知，报至江夏。黄祖急聚众商议，令苏飞为大将，陈就、邓龙为先锋，尽起江夏之兵迎敌。陈就、邓龙各引一队艨艟截住沔口，艨艟上各设强弓硬弩千余张，将大索系定艨艟于水面上。东吴兵至，艨艟上鼓响，弓弩齐发，兵不敢进，约退数里水面。甘宁谓董袭曰：“事已至此，不得不进。”乃选小船百余只，每船用精兵五十人：二十人撑船，三十人各披衣甲，手执铜刀，不避矢石，直至艨艟傍边，砍断大索，艨艟遂横。甘宁飞上艨艟，将邓龙砍死。陈就弃船而走。吕蒙见了，跳下小船，自举橹棹，直入船队，放火烧船。陈就急待上岸，吕蒙舍命赶到跟前，当胸一刀砍翻。比及苏飞引军于岸上接应时，东吴诸将一齐上岸，势不可当。祖军大败。苏飞落荒而走，正遇东吴大将潘璋，两马相交，战不数合，被璋生擒过去，径至船中来见孙权。权命左右以槛车囚之，待活捉黄祖，一并诛戮。催动三军，不分昼夜，攻打夏口。正是：只因不用锦帆贼，至令冲开大索船。
未知黄祖胜负如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536852580, '5b9a101e1579a3003a416159', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639174, '三国演义 · 第三十九回 · 荆州城公子三求计 博望坡军师初用兵', NULL, 2, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说孙权督众攻打夏口，黄祖兵败将亡，情知守把不住，遂弃江夏，望荆州而走。甘宁料得黄祖必走荆州，乃于东门外伏兵等候。祖带数十骑突出东门，正走之间，一声喊起，甘宁拦住。祖于马上谓宁曰：“我向日不曾轻待汝，今何相逼耶？”宁叱曰：“吾昔在江夏，多立功绩，汝乃以‘劫江贼’待我，今日尚有何说！”自知难免，拨马而走。甘宁冲开士卒，直赶将来，只听得后面喊声起处，又有数骑赶来。宁视之，乃程普也。宁恐普来争功，慌忙拈弓搭箭，背射黄祖，祖中箭翻身落马；宁枭其首级，回马与程普合兵一处，回见孙权，献黄祖首级。权命以木匣盛贮，待回江东祭献于亡父灵前。重赏三军，升甘宁为都尉。商议欲分兵守江夏。张昭曰：“孤城不可守，不如且回江东。刘表知我破黄祖，必来报仇；我以逸待劳，必败刘表；表败而后乘势攻之，荆襄可得也。”权从其言，遂弃江夏，班师回江东。
苏飞在槛车内，密使人告甘宁求救。宁曰：“飞即不言，吾岂忘之？”大军既至吴会，权命将苏飞袅首，与黄祖首级一同祭献。甘宁乃入见权，顿首哭告曰：“某向日若不得苏飞，则骨填沟壑矣，安能效命将军麾下哉？今飞罪当诛，某念其昔日之恩情，愿纳还官爵，以赎飞罪。”权曰：“彼既有恩于君，吾为君赦之。但彼若逃去奈何？宁曰：“飞得免诛戮，感恩无地，岂肯走乎！若飞去，宁愿将首级献于阶下。”权乃赦苏飞，止将黄祖首级祭献。祭毕设宴，大会文武庆功。
正饮酒间，忽见座上一人大哭而起，拔剑在手，直取甘宁。宁忙举坐椅以迎之。权惊视其人，乃凌统也，因甘宁在江夏时，射死他父亲凌操，今日相见，故欲报仇。权连忙劝住，谓统曰：“兴霸射死卿父，彼时各为其主，不容不尽力。今既为一家人，岂可复理旧仇？万事皆看吾面。”凌统即头大哭曰：“不共戴天之仇，岂容不报！”权与众官再三劝之，凌统只是怒目而视甘宁。权即日命甘宁领兵五千、战船一百只，往夏口镇守，以避凌统。宁拜谢，领兵自往夏口去了。权又加封凌统为承烈都尉。统只得含恨而止。东吴自此广造战船，分兵守把江岸；又命孙静引一枝军守吴会；孙权自领大军，屯柴桑；周瑜日于鄱阳湖教练水军，以备攻战。
话分两头。却说玄德差人打探江东消息，回报：“东吴已攻杀黄祖，现今屯兵柴桑。”玄德便请孔明计议。正话间，忽刘表差人来请玄德赴荆州议事。孔明曰：“此必因江东破了黄祖，故请主公商议报仇之策也。某当与主公同往，相机而行，自有良策。”玄德从之，留云长守新野，令张飞引五百人马跟随往荆州来。玄德在马上谓孔明曰：“今见景升，当若何对答？”孔明曰：“当先谢襄阳之事。他若令主公去征讨江东，切不可应允，但说容归新野，整顿军马。”玄德依言。
来到荆州，馆驿安下，留张飞屯兵城外，玄德与孔明入城见刘表。礼毕，玄德请罪于阶下。表曰：“吾已悉知贤弟被害之事。当时即欲斩蔡瑁之首，以献贤弟；因众人告危，故姑恕之。贤弟幸勿见罪。”玄德曰：“非干蔡将军之事，想皆下人所为耳。”表曰：“今江夏失守，黄祖遇害，故请贤弟共议报复之策。”玄德曰：“黄祖性暴，不能用人，故致此祸。今若兴兵南征，倘曹操北来，又当奈何？”表曰：“吾今年老多病，不能理事，贤弟可来助我。我死之后，弟便为荆州之主也。”玄德曰：“兄何出此言！量备安敢当此重任。”孔明以目视玄德。玄德曰：“容徐思良策。”遂辞出。
回至馆驿，孔明曰：“景升欲以荆州付主公，奈何却之？”玄德曰：“景升待我，恩礼交至，安忍乘其危而夺之？”孔明叹曰：“真仁慈之主也！”正商论间，忽报公子刘琦来见。玄德接入。琦泣拜曰：“继母不能相容，性命只在旦夕，望叔父怜而救之。”玄德曰：“此贤侄家事耳，奈何问我？”孔明微笑。玄德求计于孔明，孔明曰：“此家事，亮不敢与闻。”少时，玄德送琦出，附耳低言曰：“来日我使孔明回拜贤侄，可如此如此，彼定有妙计相告。”琦谢而去。
次日，玄德只推腹痛，乃浼孔明代往回拜刘琦。孔明允诺，来至公子宅前下马，入见公子。公子邀入后堂。茶罢，琦曰：“琦不见容于继母，幸先生一言相救。”孔明曰：“亮客寄于此，岂敢与人骨肉之事？倘有漏泄，为害不浅。”说罢，起身告辞。琦曰：“既承光顾，安敢慢别。”乃挽留孔明入密室共饮。饮酒之间，琦又曰：“继母不见容，乞先生一言救我。”孔明曰：“此非亮所敢谋也。”言讫，又欲辞去。琦曰：“先生不言则已，何便欲去？”孔明乃复坐。琦曰：“琦有一古书，请先生一观。”乃引孔明登一小楼，孔明曰：“书在何处？”琦泣拜曰：“继母不见容，琦命在旦夕，先生忍无一言相救乎？”孔明作色而起，便欲下楼，只见楼梯已撤去。琦告曰：“琦欲求教良策，先生恐有泄漏，不肯出言；今日上不至天，下不至地，出君之口，入琦之耳：可以赐教矣。”孔明曰：“疏不间亲，亮何能为公子谋？琦曰：“先生终不幸教琦乎！琦命固不保矣，请即死于先生之前。”乃掣剑欲自刎。孔明止之曰：“已有良策。”琦拜曰：“愿即赐教。”孔明曰：“公子岂不闻申生、重耳之事乎？申生在内而亡，重耳在外而安。今黄祖新亡，江夏乏人守御，公子何不上言，乞屯兵守江夏，则可以避祸矣。”琦再拜谢教，乃命人取梯迭孔明下楼。孔明辞别，回见玄德，具言其事。玄德大喜。
次日，刘琦上言，欲守江夏。刘表犹豫未决，请玄德共议。玄德曰：“江夏重地，固非他人可守，正须公子自往。东南之事，兄父子当之；西北之事，备愿当之。”表曰：“近闻曹操于邺郡作玄武池以练水军，必有南征之意，不可不防。”玄德曰“备已知之，兄勿忧虑。”遂拜辞回新野。刘表令刘琦引兵三千往江夏镇守。却说曹操罢三公之职，自以丞相兼之。以毛玠为东曹掾，崔琰为西曹掾，司马懿为文学掾。懿字仲达，河内温人也。颍川太守司马隽之孙，京兆尹司马防之子，主簿司马朗之弟也。自是文官大备，乃聚武将商议南征。夏侯惇进曰：“近闻刘备在新野，每日教演士卒，必为后患，可早图之。”操即命夏侯惇为都督，于禁、李典、夏侯兰、韩浩为副将，领兵十万，直抵博望城，以窥新野。荀彧谏曰：“刘备英雄，今更兼诸葛亮为军师，不可轻敌。”惇曰：“刘备鼠辈耳，吾必擒之。”徐庶曰：“将军勿轻视刘玄德。今玄德得诸葛亮为辅，如虎生翼矣。”操曰：“诸葛亮何人也？”庶曰：亮字孔明，道号卧龙先生。有经天纬地之才，出鬼入神之计，真当世之奇才，非可小觑。”操曰：“比公若何？”庶曰：“庶安敢比亮？庶如萤火之光，亮乃皓月之明也。”夏侯惇曰：“元直之言谬矣。吾看诸葛亮如草芥耳，何足惧哉！吾若不一阵生擒刘备，活捉诸葛，愿将首级献与丞相。”操曰：“汝早报捷书，以慰吾心。”惇奋然辞曹操，引军登程。
却说玄德自得孔明，以师礼待之。关、张二人不悦，曰：“孔明年幼，有甚才学？兄长待之太过！又未见他真实效验！”玄德曰：“吾得孔明，犹鱼之得水也。两弟勿复多言。”关、张见说，不言而退，一日，有人送氂牛尾至。玄德取尾亲自结帽。孔明入见，正色曰：“明公无复有远志，但事此而已耶？”玄德投帽于地而谢曰：“吾聊假此以忘忧耳。”孔明曰：“明公自度比曹操若何？”玄德曰：“不如也。”孔明曰：“明公之众，不过数千人，万一曹兵至，何以迎之？”玄德曰：“吾正愁此事，未得良策。”孔明曰：“可速招募民兵，亮自教之，可以待敌。”玄德遂招新野之民，得三千人。孔明朝夕教演阵法。
忽报曹操差夏侯惇引兵十万，杀奔新野来了。张飞闻知，谓云长曰：“可着孔明前去迎敌便了。”正说之间，玄德召二人入，谓曰：”夏侯惇引兵到来，如何迎敌？”张飞曰：“哥哥何不使‘水’去？”玄德曰：“智赖孔明，勇须二弟，何可推调？”关、张出，玄德请孔明商议。孔明曰：“但恐关、张二人不肯听吾号令；主公若欲亮行兵，乞假剑印。”玄德便以剑印付孔明，孔明遂聚集众将听令。张飞谓云长曰：“且听令去，看他如何调度。”孔明令曰：“博望之左有山，名曰豫山；右有林，名曰安林：可以埋伏军马。云长可引一千军往豫山埋伏，等彼军至，放过休敌；其辎重粮草，必在后面，但看南面火起，可纵兵出击，就焚其粮草。翼德可引一千军去安林背后山谷中埋伏，只看南面火起，便可出，向博望城旧屯粮草处纵火烧之。关平、刘封可引五百军，预备引火之物，于博望坡后两边等候，至初更兵到，便可放火矣。”又命：“于樊城取回赵云，令为前部，不要赢，只要输，主公自引一军为后援。各须依计而行，勿使有失。”云长曰：“我等皆出迎敌，未审军师却作何事？”孔明曰：“我只坐守县城。”张飞大笑曰：“我们都去厮杀，你却在家里坐地，好自在！”孔明曰：“剑印在此，违令者斩！”玄德曰：“岂不闻‘运筹帷幄之中，决胜千里之外’？二弟不可违令。”张飞冷笑而去。云长曰：“我们且看他的计应也不应，那时却来问他未迟。”二人去了。众将皆未知孔明韬略，今虽听令，却都疑惑不定。孔明谓玄德曰：“主公今日可便引兵就博望山下屯住。来日黄昏，敌军必到，主公便弃营而走；但见火起，即回军掩杀。亮与糜竺、糜芳引五百军守县。”命孙乾、简雍准备庆喜筵席，安排“功劳簿”伺候。派拨已毕，玄德亦疑惑不定。
却说夏侯惇与于禁等引兵至博望，分一半精兵作前队，其余尽护粮车而行。时当秋月，商飙徐起。人马趱行之间，望见前面尘头忽起。惇便将人马摆开，问向导官曰：“此间是何处？”答曰：“前面便是博望城，后面是罗川口。”惇令于禁、李典押住阵脚，亲自出马阵前。遥望军马来到，惇忽然大笑。众问：“将军为何而笑？”惇曰：“吾笑徐元直在丞相面前，夸诸葛亮为天人；今观其用兵，乃以此等军马为前部，与吾对敌，正如驱犬羊与虎豹斗耳！吾于丞相前夸口。要活捉刘备、诸葛亮，今必应吾言矣。”遂自纵马向前。赵云出马。惇骂曰：“汝等随刘备，如孤魂随鬼耳！”云大怒，纵马来战。两马相交，不数合，云诈败而走。夏侯惇从后追赶。云约走十余里，回马又战。不数合又走。韩浩拍马向前谏曰：“赵云诱敌，恐有埋伏。”惇曰：“敌军如此，虽十面埋伏，吾何惧哉！”遂不听浩言，直赶至博望坡。一声炮响，玄德自引军冲将过来，接应交战。夏侯惇笑谓韩浩曰：“此即埋伏之兵也！吾今晚不到新野，誓不罢兵！”乃催军前进。玄德、赵云退后便走。
时天色已晚，浓云密布，又无月色；昼风既起，夜风愈大。夏侯惇只顾催军赶杀。于禁、李典赶到窄狭处，两边都是芦苇。典谓禁曰：“欺敌者必败。南道路狭，山川相逼。树木丛杂，倘彼用火攻，奈何？”禁曰：“君言是也。吾当往前为都督言之；君可止住后军。”李典便勒回马，大叫：“后军慢行！”人马走发，那里拦当得住？于禁骤马大叫：“前军都督且住！”夏侯惇正走之间，见于禁从后军奔来，便问何故。禁曰：“南道路狭，山川相逼，树木丛杂，可防火攻。”夏侯惇猛省，即回马令军马勿进。言未已，只听背后喊声震起，早望见一派火光烧着，随后两边芦苇亦着。一霎时，四面八方，尽皆是火；又值风大，火势愈猛。曹家人马，自相践踏，死者不计其数。赵云回军赶杀，夏侯惇冒烟突火而走。且说李典见势头不好，急奔回博望城时，火光中一军拦住。当先大将，乃关云长也。李典纵马混战，夺路而走。于禁见粮草车辆，都被火烧，便投小路奔逃去了。夏侯兰、韩浩来救粮草，正遇张飞。战不数合，张飞一枪刺夏侯兰于马下。韩浩夺路走脱。直杀到天明，却才收军。杀得尸横遍野，血流成河。后人有诗曰：“博望相持用火攻，指挥如意笑谈中。直须惊破曹公胆，初出茅庐第一功！”夏侯惇收拾残军，自回许昌。却说孔明收军。关、张二人相谓曰：“孔明真英杰也！”行不数里，见糜竺、糜芳引军簇拥着一辆小车。车中端坐一人，乃孔明也。关、张下马拜伏于车前。须臾，玄德、赵云、刘封、关平等皆至，收聚众军，把所获粮草辎重，分赏将士，班师回新野，新野百姓望尘遮道而拜，曰：“吾属生全，皆使君得贤人之力也！”孔明回至县中，谓玄德曰：“夏侯惇虽败去，曹操必自引大军来。”玄德曰：“似此如之奈何？”孔明曰：“亮有一计，可敌曹军。”正是：破敌未堪息战马，避兵又必赖良谋。
未知其计若何，且看下回分解。', '', '', '', NULL, '', 'indent', 1536852580, '5b9a103717d00900340929d2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639175, '三国演义 · 第四十回 · 蔡夫人议献荆州 诸葛亮火烧新野', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说玄德问孔明求拒曹兵之计。孔明曰：“新野小县，不可久居，近闻刘景升病在危笃，可乘此机会，取彼荆州为安身之地，庶可拒曹操也。”玄德曰：“公言甚善；但备受景升之恩，安忍图之！”孔明曰：“今若不取，后悔何及！”玄德曰：“吾宁死，不忍作负义之事。”孔明曰：“且再作商议。”
却说夏侯惇败回许昌，自缚见曹操，伏地请死。操释之。惇曰：“惇遭诸葛亮诡计，用火攻破我军。”操曰：“汝自幼用兵，岂不知狭处须防火攻？”惇曰：“李典、于禁曾言及此，悔之不及！”操乃赏二人。惇曰：“刘备如此猖狂，真腹心之患也，不可不急除。”操曰：“吾所虑者，刘备、孙权耳；余皆不足介意，今当乘此时扫平江南。”便传令起大兵五十万，令曹仁、曹洪为第一队，张辽、张郃为第二队。夏侯渊、夏侯惇为第三队，于禁、李典为第四队，操自领诸将为第五队：每队各引兵十万。又令许褚为折冲将军，引兵三千为先锋。选定建安十三年秋七月丙午日出师。
太中大夫孔融谏曰：“刘备，刘表皆汉室宗亲，不可轻伐；孙权虎踞六郡，且有大江之险，亦不易取，今丞相兴此无义之师，恐失天下之望。”操怒曰：“刘备、刘表、孙权皆逆命之臣，岂容不讨！”遂叱退孔融，下令：“如有再谏者，必斩。”孔融出府，仰天叹曰：“以至不仁伐至仁，安得不败乎！”时御史大夫郗虑家客闻此言，报知郗虑，虑常被孔融侮慢，心正恨之，乃以此言入告曹操，且曰：“融平日每每狎侮丞相，又与祢衡相善，衡赞融曰‘仲尼不死，融赞衡曰颜回复生’。向者祢衡之辱丞相，乃融使之也。”操大怒，遂命廷尉捕捉孔融。融有二子，年尚少，时方在家，对坐弈棋。左右急报曰：“尊君被廷尉执去，将斩矣！二公子何不急避？”二子曰：“破巢之下，安有完卵乎？”言未已，廷尉又至，尽收融家小并二子，皆斩之，号令融尸于市。京兆脂习伏尸而哭。操闻之，大怒，欲杀之。荀彧曰：“彧闻脂习常谏融曰：公刚直太过，乃取祸之道，今融死而来哭，乃义人也，不可杀。”操乃止，习收融父子尸首，皆葬之。后人有诗赞孔融曰：孔融居北海，豪气贯长虹：坐上客长满，樽中酒不空；文章惊世俗，谈笑侮王公。史笔褒忠直，存官纪“太中”。曹操既杀孔融，传令五队军马次第起行，只留荀彧等守许昌。
却说荆州刘表病重，使人请玄德来托孤。玄德引关、张至荆州见刘表。表曰：“我病已入膏肓，不久便死矣，特托孤于贤弟。我子无才，恐不能承父业，我死之后，贤弟可自领荆州。”玄德泣拜曰：“备当竭力以辅贤侄，安敢有他意乎！”正说间，人报曹操自统大兵至。玄德急辞刘表，星夜回新野。刘表病中闻此信，吃惊不小，商议写遗嘱，令玄德辅佐长子刘琦为荆州之主。蔡夫人闻之大怒，关上内门；使蔡瑁、张允二人把住外门。时刘琦在江夏，知父病危，来至荆州探病，方到外门，蔡瑁当住曰：“公子奉父命镇守江夏，其任至重；今擅离职守，倘东吴兵至，如之奈何？若入见主公，主公必生嗔怒，病将转增，非孝也。宜速回。”刘琦立于门外，大哭一场，上马仍回江夏。刘表病势危笃，望刘琦不来；至八月戊申日，大叫数声而死。后人有诗叹刘表曰：“昔闻袁氏居河朔，又见刘君霸汉阳。总为牝晨致家累，可怜不久尽销亡！”
刘表既死，蔡夫人与蔡瑁、张允商议，假写遗嘱，令次子刘琮为荆州之主，然后举哀报丧。时刘琮年方十四岁，颇聪明，乃聚众言曰：“吾父弃世，吾兄现在江夏，更有叔父玄德在新野。汝等立我为主。倘兄与叔兴兵问罪，如何解释？”众官未及对，幕官李珪答曰：“公子之言甚善。今可急发哀书至江夏，请大公子为荆州之主，就命玄德一同理事：北可以敌曹操，南可以拒孙权。此万全之策也。”蔡瑁叱曰：“汝何人，敢乱言以逆主公遗命！”李珪大骂曰：“汝内外朋谋，假称遗命，废长立幼，眼见荆襄九郡，送于蔡氏之手！故主有灵，必当殛汝！”蔡瑁大怒，喝令左右推出斩之。李珪“至死大骂不绝。于是蔡瑁遂立刘琮为主。蔡氏宗族，分领荆州之兵；命治中邓义、别驾刘先守荆州；蔡夫人自与刘琮前赴襄阳驻扎，以防刘琦、刘备。就葬刘表之柩于襄阳城东汉阳之原，竟不讣告刘琦与玄德。
刘琮至襄阳，方才歇马，忽报曹操引大军径望襄阳而来。琮大惊，遂请蒯越、蔡瑁等商议。东曹掾傅巽进言曰：“不特曹操兵来为可忧；今大公子在江夏，玄德在新野，我皆未往报丧，若彼兴兵问罪，荆襄危矣。巽有一计，可使荆襄之民，安如泰山，又可保全主公名爵。”琮曰：“计将安出？”巽曰：“不如将荆襄九郡，献与曹操，操必重待主公也。”琮叱曰：“是何言也！孤受先君之基业，坐尚未稳，岂可便弃之他人？”蒯越曰：“傅公悌之言是也。夫逆顺有大体，强弱有定势。今曹操南征北讨，以朝廷为名，主公拒之，其名不顺。且主公新立，外患未宁，内忧将作。荆襄之民，闻曹兵至，未战而胆先寒，安能与之敌哉？”琮曰：“诸公善言，非我不从；但以先君之业，一旦弃与他人，恐贻笑于天下耳。”
言未已，一人昂然而进曰：“傅公悌、蒯异度之言甚善，何不从之？”众视之，乃山阳高平人，姓王，名粲，字仲宣。粲容貌瘦弱，身材短小；幼时往见中郎蔡邕，时邕高朋满座，闻粲至，倒履迎之。宾客皆惊曰：“蔡中郎何独敬此小子耶？”邕曰：“此子有异才，吾不如也。”粲博闻强记，人皆不及：尝观道旁碑文一过，便能记诵；观人弈棋，棋局乱，粲复为摆出，不差一子。又善算术。其文词妙绝一时。年十七，辟为黄门侍郎，不就。后因避乱至荆襄，刘表以为上宾。当日谓刘琮曰：“将军自料比曹公何如？”琮曰：“不如也。”粲曰：“曹公兵强将勇，足智多谋；擒吕布于下邳，摧袁绍于官渡，逐刘备于陇右，破乌桓于白狼：枭除荡定者，不可胜计。今以大军南下荆襄，势难抵敌。傅、蒯二君之谋，乃长策也。将军不可迟疑，致生后悔。”琮曰：“先生见教极是。但须禀告母亲知道。”只见蔡夫人从屏后转出，谓琮曰：“既是仲宣、公悌、异度三人所见相同，何必告我。”于是刘琮意决，便写降书，令宋忠潜地往曹操军前投献。宋忠领命，直至宛城，接着曹操，献上降书。操大喜，重赏宋忠，分付教刘琮出城迎接，便着他永为荆州之主。
宋忠拜辞曹操，取路回荆襄。将欲渡江，忽见一枝人马到来，视之，乃关云长也。宋忠回避不迭，被云长唤住，细问荆州之事。忠初时隐讳；后被云长盘问不过，只得将前后事情，——实告。云长大惊，随捉宋忠至新野见玄德，备言其事。玄德闻之大哭。张飞曰：“事已如此，可先斩宋忠，随起兵渡江，夺了襄阳，杀了蔡氏、刘琮，然后与曹操交战。”玄德曰：“你且缄口。我自有斟酌。”乃叱宋忠曰：“你知众人作事，何不早来报我？今虽斩汝，无益于事。可速去。”忠拜谢，抱头鼠窜而去。玄德正忧闷间，忽报公子刘琦差伊籍到来。玄德感伊籍昔日相救之恩，降阶迎之，再三称谢。籍曰：“大公子在江夏，闻荆州已故，蔡夫人与蔡瑁等商议，不来报丧，竟立刘琮为主。公子差人往襄阳探听，回说是实；恐使君不知，特差某赍哀书呈报，并求使君尽起麾下精兵，同往襄阳问罪。”玄德看书毕，谓伊籍曰：“机伯只知刘琮僭立，更不知刘琮已将荆襄九郡献与曹操矣！”籍大惊曰：“使君从何知之？”玄德具言拿获宋忠之事。籍曰：“若如此，使君不如以吊丧为名，前赴襄阳，诱刘琮出迎，就便擒下，诛其党类，则荆州属使君矣。”孔明曰：“机伯之言是也。主公可从之。”玄德垂泪曰：“吾兄临危托孤于我，今若执其子而夺其地，异日死于九泉之下，何面目复见吾兄乎？”孔明曰：“如不行此事，今曹兵已至宛城，何以拒敌？”玄德曰：“不如走樊城以避之。”
正商议间，探马飞报曹兵已到博望了。玄德慌忙发付伊籍回江夏整顿军马，一面与孔明商议拒敌之计。孔明曰：“主公且宽心。前番一把火，烧了夏侯惇大半人马；今番曹军又来，必教他中这条计。我等在新野住不得了，不如早到樊城去。”便差人四门张榜，晓谕居民：“无问老幼男女，愿从者，即于今日皆跟我往樊城暂避，不可自误。”差孙乾往河边调拨船只，救济百姓；差糜竺护送各官家眷到樊城。一面聚诸将听令，先教云长：“引一千军去白河上流头埋伏。各带布袋，多装沙土，遏住白河之水，至来日三更后，只听下流头人喊马嘶，急取起布袋，放水淹之，却顺水杀将下来接应。”又唤张飞：“引一千军去博陵渡口埋伏。此处水势最慢，曹军被淹，必从此逃难，可便乘势杀来接应。”又唤赵云：“引军三千，分为四队，自领一队伏于东门外，其三队分伏西、南、北三门，却先于城内人家屋上，多藏硫黄焰硝引火之物。曹军入城，必安歇民房。来日黄昏后，必有大风；但看风起，便令西、南、北三门伏军尽将火箭射入城去；待城中火势大作，却于城外呐喊助威，只留东门放他出走。汝却于东门外从后击之。天明会合关、张二将，收军回樊城。”再令糜芳、刘封：“二人带二千军。一半红旗，一半青旗，去新野城外三十里鹊尾坡前屯住。一见曹军到，红旗军走在左，青旗军走在右。他心疑必不敢追。汝二人却去分头埋伏。只望城中火起，便可追杀败兵，然后却来白河上流头接应。”孔明分拨已定，乃与玄德登高了望，只候捷音。却说曹仁、曹洪引军十万为前队，前面已有许褚引三千铁甲军开路，浩浩荡荡，杀奔新野来。是日午牌时分，来到鹊尾坡，望见坡前一簇人马，尽打青、红旗号，许褚催军向前。刘封、糜芳分为四队，青、红旗各归左右。许褚勒马，教且休进：“前面必有伏兵。我兵只在此处住下。”许褚一骑马飞报前队曹仁。曹仁曰：“此是疑兵，必无埋伏。可速进兵。我当催军继至。”许褚复回坡前，提兵杀入。至林下追寻时，不见一人。时日已坠西。许褚方欲前进，只听得山上大吹大擂。抬头看时，只见山顶上一簇旗，旗丛中两把伞盖：左玄德，右孔明，二人对坐饮酒。许褚大怒，引军寻路上山。山上擂木炮石打将下来，不能前进。又闻山后喊声大震。欲寻路厮杀，天色已晚。曹仁领兵到，教且夺新野城歇马。军士至城下时，只见四门大开。曹兵突人，并无阻当，城中亦不见一人，竟是一座空城了。曹洪曰：“此是势孤计穷，故尽带百姓逃窜去了。我军权且在城安歇，来日平明进兵。”此时各军走乏，都已饥饿，皆去夺房造饭。曹仁、曹洪就在衙内安歇。初更已后，狂风大作。守门军士飞报火起。曹仁曰：“此必军士造饭不小心，遗漏之火，不可自惊。”说犹未了，接连几次飞报，西、南、北三门皆火起。曹仁急令众将上马时，满县火起，上下通红。是夜之火，更胜前日博望烧屯之火。后人有诗叹曰：“奸雄曹操守中原，九月南征到汉川。风伯怒临新野县，祝融飞下焰摩天。”曹仁引众将突烟冒火，寻路奔走，闻说东门无火，急急奔出东门。军士自相践踏，死者无数。曹仁等方才脱得火厄，背后一声喊起，赵云引军赶来混战，败军各逃性命，谁肯回身厮杀。正奔走间，糜芳引一军至，又冲杀一阵。曹仁大败，夺路而走，刘封又引一军截杀一阵。到四更时分，人困马乏，军士大半焦头烂额；奔至白河边，喜得河水不甚深，人马都下河吃水：人相喧嚷，马尽嘶鸣。
却说云长在上流用布袋遏住河水，黄昏时分，望见新野火起；至四更，忽听得下流头人喊马嘶，急令军士一齐掣起布袋，水势滔天，望下流冲去，曹军人马俱溺于水中，死者极多。曹仁引众将望水势慢处夺路而走。行到博陵渡口，只听喊声大起，一军拦路，当先大将，乃张飞也，大叫：“曹贼快来纳命！”曹军大惊。正是：城内才看红焰吐，水边又遇黑风来。
未知曹仁性命如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536852604, '5b9a104f17d0090034092acb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639176, '三国演义 · 第四十一回 · 刘玄德携民渡江 赵子龙单骑救主', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说张飞因关公放了上流水，遂引军从下流杀将来，截住曹仁混杀。忽遇许褚，便与交锋；许褚不敢恋战，夺路走脱。张飞赶来，接着玄德、孔明，一同沿河到上流。刘封、糜芳已安排船只等候，遂一齐渡河，尽望樊城而去，孔明教将船筏放火烧毁。却说曹仁收拾残军，就新野屯住，使曹洪去见曹操，具言失利之事。操大怒曰：“诸葛村夫，安敢如此；”催动三军，漫山塞野，尽至新野下寨。传令军士一面搜山，一面填塞白河。令大军分作八路，一齐去取樊城。刘晔曰：“丞相初至襄阳，必须先买民心，今刘备尽迁新野百姓入樊城，若我兵径进，二县为齑粉矣；不如先使人招降刘备。备即不降，亦可见我爱民之心；若其来降，则荆州之地，可不战而定也。”操从其言，便问：“谁可为使？”刘晔曰：“徐庶与刘备至厚，今现在军中，何不命他一往？”操曰：“他去恐不复来。”晔曰：“他若不来，贻笑于人矣。丞相勿疑。”操乃召徐庶至，谓曰：“我本欲踏平樊城，奈怜众百姓之命。公可往说刘备：如肯来降，免罪赐爵；若更执迷，军民共戮，玉石俱焚。吾知公忠义，故特使公往。愿勿相负。”
徐庶受命而行。至樊城，玄德、孔明接见，共诉旧日之情。庶曰：“曹操使庶来招降使君，乃假买民心也，今彼分兵八路，填白河而进。樊城恐不可守，宜速作行计。”玄德欲留徐庶。庶谢曰：“某若不还，恐惹人笑。今老母已丧，抱恨终天。身虽在彼，誓不为设一谋，公有卧龙辅佐，何愁大业不成。庶请辞。”玄德不敢强留。
徐庶辞回，见了曹操，言玄德并无降意。操大怒，即日进兵。玄德问计于孔明。孔明曰：“可速弃樊城，取襄阳暂歇。”玄德曰：“奈百姓相随许久，安忍弃之？”孔明曰：“可令人遍告百姓：有愿随者同去，不愿者留下。”先使云长往江岸整顿船只，令孙乾、简雍在城中声扬曰：“今曹兵将至，孤城不可久守，百姓愿随者，便同过江。”两县之民，齐声大呼曰：“我等虽死，亦愿随使君！”即日号泣而行。扶老携幼，将男带女，滚滚渡河，两岸哭声不绝。玄德于船上望见，大恸曰：“为吾一人而使百姓遭此大难，吾何生哉！”欲投江而死，左右急救止。闻者莫不痛哭。船到南岸，回顾百姓，有未渡者，望南而哭。玄德急令云长催船渡之，方才上马。
行至襄阳东门，只见城上遍插旌旗，壕边密布鹿角，玄德勒马大叫曰：“刘琮贤侄，吾但欲救百姓，并无他念。可快开门。”刘琮闻玄德至，惧而不出。蔡瑁、张允径来敌楼上，叱军士乱箭射下。城外百姓，皆望敌楼而哭。城中忽有一将，引数百人径上城楼，大喝：“蔡瑁、张允卖国之贼！刘使君乃仁德之人，今为救民而来投，何得相拒！”众视其人，身长八尺，面如重枣；乃义阳人也，姓魏，名延，字文长。当下魏延轮刀砍死守门将士，开了城门，放下吊桥，大叫：“刘皇叔快领兵入城，共杀卖国之贼！”张飞便跃马欲入，玄德急止之曰：“休惊百姓！”魏延只管招呼玄德军马入城。只见城内一将飞马引军而出，大喝：“魏延无名小卒，安敢造乱！认得我大将文聘么！”魏延大怒，挺枪跃马，便来交战。两下军兵在城边混杀，喊声大震。玄德曰：“本欲保民，反害民也！吾不愿入襄阳！”孔明曰：“江陵乃荆州要地，不如先取江陵为家。”玄德曰：“正合吾心。”于是引着百姓，尽离襄阳大路，望江陵而走。襄阳城中百姓，多有乘乱逃出城来，跟玄德而去。魏延与文聘交战，从已至未，手下兵卒皆已折尽。延乃拨马而逃，却寻不见玄德，自投长沙太守韩玄去了。
却说玄德同行军民十余万，大小车数千辆，挑担背包者不计其数，路过刘表之墓，玄德率众将拜于墓前，哭告曰：“辱弟备无德无才，负兄寄托之重，罪在备一身，与百姓无干。望兄英灵，垂救荆襄之民！”言甚悲切，军民无不下泪。忽哨马报说：“曹操大军已屯樊城，使人收拾船筏，即日渡江赶来也。”众将皆曰：“江陵要地，足可拒守。今拥民众数万，日行十余里，似此几时得至江陵？倘曹兵到，如何迎敌？不如暂弃百姓，先行为上。”玄德泣曰：“举大事者必以人为本。今人归我，奈何弃之？”百姓闻玄德此言，莫不伤感。后人有诗赞之曰：“临难仁心存百姓，登舟挥泪动三军。至今凭吊襄江口，父老犹然忆使君。”却说玄德拥着百姓，缓缓而行。孔明曰：“追兵不久即至。可遣云长往江夏求救于公子刘琦。教他速起兵乘船会于江陵。”玄德从之，即修书令云长同孙乾领五百军往江夏求救；令张飞断后；赵云保护老小；其余俱管顾百姓而行。每日只走十余里便歇。却说曹操在樊城，使人渡江至襄阳，召刘琮相见。琮惧怕不敢往见。蔡瑁、张允请行。王威密告琮曰：“将军既降，玄德又走，曹操必懈弛无备。愿将军奋整奇兵，设于险处击之，操可获矣。获操则威震天下，中原虽广，可传檄而定。此难遇之机，不可失也。”琮以其言告蔡瑁。瑁叱王威曰：“汝不知天命，安敢妄言！”威怒骂曰：“卖国之徒，吾恨不生啖汝肉！”瑁欲杀之，蒯越劝止。
瑁遂与张允同至樊城，拜见曹操。瑁等辞色甚是谄佞。操问：“荆州军马钱粮，今有多少？”瑁曰：“马军五万，步军十五万，水军八万：共二十八万。钱粮大半在江陵；其余各处，亦足供给一载。”操曰：“战船多少？原是何人管领？”瑁曰：“大小战船，共七千余只，原是瑁等二人掌管。”操遂加瑁为镇南侯、水军大都督，张允为助顺侯、水军副都督。二人大喜拜谢。操又曰：“刘景升既死，其子降顺，吾当表奏天子，使永为荆州之主。”二人大喜而退。荀攸曰：“蔡瑁，张允乃谄佞之徒，主公何遂加以如此显爵，更教都督水军乎？”操笑曰：“吾岂不识人！止因吾所领北地之众，不习水战，故且权用此二人；待成事之后，别有理会。”
却说蔡瑁、张允归见刘琮，具言：“曹操许保奏将军永镇荆襄。”琮大喜！次日，与母蔡夫人赍捧印缓兵符，亲自渡江拜迎曹操。操抚慰毕，即引随征军将，进屯襄阳城外。蔡瑁、张允令襄阳百姓焚香拜接。曹操俱用好言抚谕。入城至府中坐定，即召蒯越近前，抚慰曰：“吾不喜得荆州，喜得异度也。”遂封蒯越为江陵太守、樊城侯；傅巽、王粲等皆为关内侯；而以刘琮为青州刺史，便教起程。琮闻命大惊，辞曰：“琮不愿为官，愿守父母乡土。”操曰：“青州近帝都，教你随朝为官，免在荆襄被人图害。”琮再三推辞，曹操不准。琮只得与母蔡夫人同赴青州。只有故将王威相随，其余官员俱送至江口而回。操唤于禁嘱咐曰：“你可引轻骑追刘琮母子杀子，以绝后患。”于禁得令，领众赶上，大喝曰：“我奉丞相令，教来杀汝母子！可早纳下首级！”蔡夫人抱刘琮而大哭。于禁喝令军士下手。王威忿怒，奋力相斗，竟被众军所杀。军士杀死刘琮及蔡夫人，于禁回报曹操，操重赏于禁。便使人往隆中搜寻孔明妻小，却不知去向。原来孔明先已令人搬送至三江内隐避矣。操深恨之。襄阳既定，荀攸进言曰：“江陵乃荆襄重地，钱粮极广。刘备若据此地，急难动摇。”操曰：“孤岂忘之！”随命于襄阳诸将中，选一员引军开道。诸将中却独不见文聘。操使人寻问，方才来见。操曰：“汝来何迟？”对曰：“为人臣而不能使其主保全境土，心实悲惭，无颜早见耳。”言讫，欷歔流涕。操曰：“真忠臣也！”除江夏太守，赐爵关内侯，便教引军开道。探马报说：“刘备带领百姓，日行止十数里，计程只有三百余里。”操教各部下精选五千铁骑，星夜前进，限一日一夜，赶上刘备。大军陆续随后而进。
却说玄德引十数万百姓、三千余军马，一程程挨着往江陵进发。赵云保护老小，张飞断后。孔明曰：“云长往江夏去了，绝无回音，不知若何。”玄德曰：“敢烦军师亲自走一遭。刘琦感公昔日之教，今若见公亲至，事必谐矣。”孔明允诺，便同刘封引五百军先往江夏求救去了。
当日玄德自与简雍、糜竺、糜芳同行。正行间，忽然一阵狂风就马前刮起，尘土冲天，平遮红日。玄德惊曰：“此何兆也？”简雍颇明阴阳，袖占一课，失惊曰：“此大凶之兆也。应在今夜。主公可速弃百姓而走。”玄德曰：“百姓从新野相随至此，吾安忍弃之？”雍曰：“主公若恋而不弃，祸不远矣。”玄德问：“前面是何处？”左右答曰：“前面是当阳县。有座山名为景山。”玄德便教就此山扎住。
时秋末冬初，凉风透骨；黄昏将近，哭声遍野。至四更时分，只听得西北喊声震地而来。玄德大惊，急上马引本部精兵二千余人迎敌。曹兵掩至，势不可当。玄德死战。正在危迫之际，幸得张飞引军至，杀开一条血路，救玄德望东而走。文聘当先拦住，玄德骂曰：“背主之贼，尚有何面目见人！”文聘羞惭满面，引兵自投东北去了。张飞保着玄德，且战且走。奔至天明，闻喊声渐渐远去，玄德方才歇马。看手下随行人，止有百余骑；百姓、老小并糜竺、糜芳、简雍、赵云等一干人，皆不知下落。玄德大哭曰：“十数万生灵，皆因恋我，遭此大难；诸将及老小，皆不知存亡：虽土木之人，宁不悲乎！”正凄惶时，忽见糜芳面带数箭，踉跄而来，口言：“赵子龙反投曹操去了也！”玄德叱曰：“子龙是我故交，安肯反乎？”张飞曰：“他今见我等势穷力尽，或者反投曹操，以图富贵耳！”玄德曰：“子龙从我于患难，心如铁石，非富贵所能动摇也。”糜芳曰：“我亲见他投西北去了。”张飞曰：“待我亲自寻他去。若撞见时，一枪刺死！”玄德曰：“休错疑了。岂不见你二兄诛颜良、文丑之事乎？子龙此去，必有事故。吾料子龙必不弃我也。”张飞那里肯听，引二十余骑，至长坂桥。见桥东有一带树木，飞生一计：教所从二十余骑，都砍下树枝，拴在马尾上，在树林内往来驰骋，冲起尘土，以为疑兵。飞却亲自横矛立马于桥上，向西而望。
却说赵云自四更时分，与曹军厮杀，往来冲突，杀至天明，寻不见玄德，又失了玄德老小，云自思曰：“主公将甘、糜二夫人与小主人阿斗，托付在我身上；今日军中失散，有何面目去见主人？不如去决一死战，好歹要寻主母与小主人下落！”回顾左右，只有三四十骑相随。云拍马在乱军中寻觅，二县百姓号哭之声震天动地；中箭着枪、抛男弃女而走者，不计其数。赵云正走之间，见一人卧在草中，视之，乃简雍也。云急问曰：“曾见两位主母否？”雍曰：“二主母弃了车仗，抱阿斗而走。我飞马赶去，转过山坡，被一将刺了一枪，跌下马来，马被夺了去。我争斗不得，故卧在此。”云乃将从骑所骑之马，借一匹与简雍骑坐；又着二卒扶护简雍先去报与主人：“我上天入地，好歹寻主母与小主人来。如寻不见，死在沙场上也！”
说罢，拍马望长坂坡而去。忽一人大叫：“赵将军那里去？”云勒马问曰：“你是何人？”答曰：“我乃刘使君帐下护送车仗的军士，被箭射倒在此。”赵云便问二夫人消息。军士曰：“恰才见甘夫人披头跣足，相随一伙百姓妇女，投南而走。”云见说，也不顾军士，急纵马望南赶去。只见一伙百姓，男女数百人，相携而走。”云大叫曰：“内中有甘夫人否？”夫人在后面望见赵云，放声大哭。云下马插枪而泣曰：“使主母失散，云之罪也！糜夫人与小主人安在？”甘夫人曰：“我与糜夫人被逐，弃了车仗，杂于百姓内步行，又撞见一枝军马冲散。糜夫人与阿斗不知何往。我独自逃生至此。”
正言间，百姓发喊，又撞出一枝军来。赵云拔枪上马看时，面前马上绑着一人，乃糜竺也。背后一将，手提大刀，引着千余军。乃曹仁部将淳于导，拿住糜竺，正要解去献功。赵云大喝一声，挺枪纵马，直取淳于导。导抵敌不住，被云一枪刺落马下，向前救了糜竺，夺得马二匹。云请甘夫人上马，杀开条大路，直送至长坂城。只见张飞横矛立马于桥上，大叫：“子龙！你如何反我哥哥？”云曰：“我寻不见主母与小主人，因此落后，何言反耶？”飞曰：“若非简雍先来报信，我今见你，怎肯干休也！”云曰：“主公在何处？”飞曰：“只在前面不远。”云谓糜竺曰：“糜子仲保甘夫人先行，待我仍往寻糜夫人与小主人去。”言罢，引数骑再回旧路。
正走之间，见一将手提铁枪，背着一口剑，引十数骑跃马而来。赵云更不打话，直取那将。交马只一合，把那将一枪刺倒，从骑皆走。原来那将乃曹操随身背剑之将夏侯恩也。曹操有宝剑二口：一名“倚天”，一名“青釭"；倚天剑自佩之，青釭剑令夏侯恩佩之。那青釭剑砍铁如泥，锋利无比。当时夏侯恩自恃勇力，背着曹操，只顾引人抢夺掳掠。不想撞着赵云，被他一枪刺死，夺了那口剑，看靶上有金嵌“青釭”二字，方知是宝剑也。云插剑提枪，复杀入重围，回顾手下从骑，已没一人，只剩得孤身。云并无半点退心，只顾往来寻觅；但逢百姓，便问糜夫人消息。忽一人指曰：“夫人抱着孩儿，左腿上着了枪，行走不得，只在前面墙缺内坐地。”
赵云听了，连忙追寻。只见一个人家，被火烧坏土墙，糜夫人抱着阿斗，坐于墙下枯井之傍啼哭。云急下马伏地而拜。夫人曰：“妾得见将军，阿斗有命矣。望将军可怜他父亲飘荡半世，只有这点骨血。将军可护持此子，教他得见父面，妾死无恨！”云曰：“夫人受难，云之罪也。不必多言，请夫人上马。云自步行死战，保夫人透出重围。”糜夫人曰：“不可！将军岂可无马！此子全赖将军保护。妾已重伤，死何足惜！望将军速抱此子前去，勿以妾为累也。”云曰：“喊声将近，追兵已至，请夫人速速上马。”糜夫人曰：“妾身委实难去。休得两误。”乃将阿斗递与赵云曰：“此子性命全在将军身上！”赵云三回五次请夫人上马，夫人只不肯上马。四边喊声又起。云厉声曰：“夫人不听吾言，追军若至，为之奈何？”糜夫人乃弃阿斗于地，翻身投入枯井中而死。后人有诗赞之曰：“战将全凭马力多，步行怎把幼君扶？拚将一死存刘嗣，勇决还亏女丈夫。”赵云见夫人已死，恐曹军盗尸，便将土墙推倒，掩盖枯井。掩讫，解开勒甲绦，放下掩心镜，将阿斗抱护在怀，绰枪上马。早有一将，引一队步军至，乃曹洪部将晏明也，持三尖两刃刀来战赵云。不三合，被赵云一枪刺倒，杀散众军，冲开一条路。正走间，前面又一枝军马拦路。当先一员大将，旗号分明，大书“河间张郃”。云更不答话，挺枪便战。约十余合，云不敢恋战，夺路而走。背后张郃赶来，云加鞭而行，不想趷跶一声，连马和人，颠入土坑之内。张郃挺枪来刺，忽然一道红光，从土坑中滚起，那匹马平空一跃，跳出坑外。后人有诗曰：“红光罩体困龙飞，征马冲开长坂围。四十二年真命主，将军因得显神威。”张郃见了，大惊而退。赵云纵马正走，背后忽有二将大叫：“赵云休走！”前面又有二将，使两般军器，截住去路：后面赶的是马延、张顗，前面阻的是焦触、张南，都是袁绍手下降将。赵云力战四将，曹军一齐拥至。云乃拔青釭剑乱砍，手起处，衣甲平过，血如涌泉。杀退众军将，直透重围。却说曹操在景山顶上，望见一将，所到之处，威不可当，急问左右是谁。曹洪飞马下山大叫曰：“军中战将可留姓名！”云应声曰：“吾乃常山赵子龙也！”曹洪回报曹操。操曰：“真虎将也！吾当生致之。”遂令飞马传报各处：“如赵云到，不许放冷箭，只要捉活的。”因此赵云得脱此难；此亦阿斗之福所致也。这一场杀：赵云怀抱后主，直透重围，砍倒大旗两面，夺槊三条；前后枪刺剑砍，杀死曹营名将五十余员。后人有诗曰：“血染征袍透甲红，当阳谁敢与争锋！古来冲阵扶危主，只有常山赵子龙。”
赵云当下杀透重围，已离大阵，血满征袍。正行间，山坡下又撞出两枝军，乃夏侯惇部将钟缙、钟绅兄弟二人，一个使大斧，一个使画戟，大喝：“赵云快下马受缚！”正是：“才离虎窟逃生去，又遇龙潭鼓浪来。
毕竟子龙怎地脱身，且听下回分解。', '', '', '', NULL, '', 'indent', 1536852581, '5b9a106a17d0090034092c1f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639177, '三国演义 · 第四十二回 · 张翼德大闹长坂桥 刘豫州败走汉津口', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', ' 却说钟缙、钟绅二人拦住赵云厮杀。赵云挺枪便刺，钟缙当先挥大斧来迎。两马相交，战不三合。被云一枪刺落马下，夺路便走。背后钟绅持戟赶来，马尾相衔，那枝戟只在赵云后心内弄影。云急拨转马头，恰好两胸相拍。云左手持枪隔过画戟，右手拔出青釭宝剑砍去，带盔连脑，砍去一半，绅落马而死，余众奔散。赵云得脱，望长坂桥而走，只闻后面喊声大震，原来文聘引军赶来。赵云到得桥边，人困马乏。见张飞挺矛立马于桥上，云大呼曰：“翼德援我！”飞曰：“子龙速行，追兵我自当之。”
云纵马过桥，行二十余里，见玄德与众人憩于树下。云下马伏地而泣。玄德亦泣。云喘息而言曰：“赵云之罪，万死犹轻！糜夫人身带重伤，不肯上马，投井而死，云只得推土墙掩之。怀抱公子，身突重围；赖主公洪福，幸而得脱。适来公子尚在怀中啼哭，此一会不见动静，多是不能保也。”遂解视之，原来阿斗正睡着未醒。云喜曰：“幸得公子无恙！”双手递与玄德。玄德接过，掷之于地曰：“为汝这孺子，几损我一员大将！”赵云忙向地下抱起阿斗，泣拜曰：“云虽肝脑涂地，不能报也！”后人有诗曰：“曹操军中飞虎出，赵云怀内小龙眠。无由抚慰忠臣意，故把亲儿掷马前。”
却说文聘引军追赵云至长坂桥，只见张飞倒竖虎须，圆睁环眼，手绰蛇矛，立马桥上，又见桥东树林之后，尘头大起，疑有伏兵，便勒住马，不敢近前。俄而，曹仁、李典、夏侯惇、夏侯渊、乐进、张辽、张郃、许褚等都至。见飞怒目横矛，立马于桥上，又恐是诸葛孔明之计，都不敢近前。扎住阵脚，一字儿摆在桥西，使人飞报曹操。操闻知，急上马，从阵后来。张飞睁圆环眼，隐隐见后军青罗伞盖、旄钺旌旗来到，料得是曹操心疑，亲自来看。飞乃厉声大喝曰：“我乃燕人张翼德也！谁敢与我决一死战？”声如巨雷。曹军闻之，尽皆股栗。曹操急令去其伞盖，回顾左右曰：“我向曾闻云长言：翼德于百万军中，取上将之首，如探囊取物。今日相逢，不可轻敌。”言未已，张飞睁目又喝曰：“燕人张翼德在此！谁敢来决死战？”曹操见张飞如此气概，颇有退心。飞望见曹操后军阵脚移动，乃挺矛又喝曰：“战又不战，退又不退，却是何故！”喊声未绝，曹操身边夏侯杰惊得肝胆碎裂，倒撞于马下。操便回马而走。于是诸军众将一齐望西奔走。正是：黄口孺子，怎闻霹雳之声；病体樵夫，难听虎豹之吼。一时弃枪落盔者，不计其数，人如潮涌，马似山崩，自相践踏。后人有诗赞曰：“长坂桥头杀气生，横枪立马眼圆睁。一声好似轰雷震，独退曹家百万兵。”
却说曹操惧张飞之威，骤马望西而走，冠簪尽落，披发奔逃。张辽、许褚赶上，扯住辔环。曹操仓皇失措。张辽曰：“丞相休惊。料张飞一人，何足深惧！今急回军杀去，刘备可擒也。”曹操神色方才稍定，乃令张辽、许褚再至长坂桥探听消息。且说张飞见曹军一拥而退，不敢追赶；速唤回原随二十余骑，解去马尾树枝，令将桥梁拆断，然后回马来见玄德，具言断桥一事。玄德曰：“吾弟勇则勇矣，惜失于计较。”飞问其故。玄德曰：“曹操多谋。汝不合拆断桥梁，彼必追至矣。”飞曰：“他被我一喝，倒退数里，何敢再追？”玄德曰：“若不断桥，彼恐有埋伏，不敢进兵，今拆断了桥，彼料我无军而怯，必来追赶。彼有百万之众，虽涉江汉，可填而过，岂惧一桥之断耶？”于是即刻起身，从小路斜投汉津，望沔阳路而走。却说曹操使张辽、许褚探长坂桥消息，回报曰：“张飞已拆断桥梁而去矣。”操曰：“彼断桥而去，乃心怯也。”遂传令差一万军，速搭三座浮桥，只今夜就要过。李典曰：“此恐是诸葛亮之诈谋，不可轻进。”操曰：“张飞一勇之夫，岂有诈谋！”遂传下号令，火速进兵。
却说玄德行近汉津，忽见后面尘头大起，鼓声连天，喊声震地。玄德曰：“前有大江，后有追兵，如之奈何？”急命赵云准备抵敌。曹操下令军中曰：“今刘备釜中之鱼，阱中之虎；若不就此时擒捉，如放鱼入海，纵虎归山矣。众将可努力向前。”众将领命，一个个奋威追赶。忽山坡后鼓声响处，一队军马飞出，大叫曰：“我在此等候多时了！”当头那员大将，手执青龙刀，坐下赤兔马，原来是关云长，去江夏借得军马一万，探知当阳长坂大战，特地从此路截出。曹操一见云长，即勒住马回顾众将曰：“又中诸葛亮之计也！”传令大军速退。
云长追赶十数里，即回军保护玄德等到汉津，已有船只伺候，云长请玄德并甘夫人、阿斗至船中坐定。云长问曰：“二嫂嫂如何不见？”玄德诉说当阳之事。云长叹曰：“曩日猎于许田时，若从吾意，可无今日之患。”玄德曰：“我于此时亦‘投鼠忌器’耳。”正说之间，忽见江南岸战鼓大鸣，舟船如蚁，顺风扬帆而来。玄德大惊。船来至近，只见一人白袍银铠，立于船头上大呼曰：“叔父别来无恙！”小侄得罪。”玄德视之，乃刘琦也。琦过船哭拜曰：“闻叔父困于曹操，小侄特来接应。”玄德大喜，遂合兵一处，放舟而行。在船中正诉情由，江西南上战船一字儿摆开，乘风唿哨而至，刘琦惊曰：“江夏之兵，小侄已尽起至此矣。今有战船拦路，非曹操之军，即江东之军也，如之奈何？”玄德出船头视之，见一人纶巾道服，坐在船头上，乃孔明也，背后立着孙乾。玄德慌请过船，问其何故却在此。孔明曰：“亮自至江夏，先令云长于汉津登陆地而接。我料曹操必来追赶，主公必不从江陵来，必斜取汉津矣；故特请公子先来接应，我竟往夏口，尽起军前来相助。”玄德大悦，合为一处，商议破曹之策。孔明曰：“夏口城险，颇有钱粮，可以久守。请主公且到夏口屯住。公子自回江夏，整顿战船，收拾军器，为掎角之势，可以抵当曹操。若共归江夏，则势反孤矣。”刘琦曰：“军师之言甚善。但愚意欲请叔父暂至江夏；整顿军马停当，再回夏口不迟。”玄德曰：“贤侄之言亦是。”遂留下云长，引五千军守夏口。玄德、孔明、刘琦共投江夏。
却说曹操见云长在旱路引军截出，疑有伏兵，不敢来追；又恐水路先被玄德夺了江陵，便星夜提兵赴江陵来。荆州治中邓义、别驾刘先，已备知襄阳之事，料不能抵敌曹操，遂引荆州军民出郭投降。曹操入城、安民已定，释韩嵩之囚，加为大鸿胪。其余众官，各有封赏。曹操与众将议曰：“今刘备已投江夏，恐结连东吴，是滋蔓也，当用何计破之？”荀攸曰：“我今大振兵威，遣使驰檄江东，请孙权会猎于江夏，共擒刘备，分荆州之地，永结盟好。孙权必惊疑而来降，则吾事济矣。”操从其计，一面发檄遣使赴东吴；一面计点马步水军共八十三万，诈称一百万，水陆并进，船骑双行，沿江而来，西连荆、峡、东接蕲、黄、赛栅联络三百余里。
话分两头。却说江东孙权，屯兵柴桑郡，闻曹操大军至襄阳，刘琮已降，今又星夜兼道取江陵，乃集众谋士商议御守之策。鲁肃曰：“荆州与国邻接，江山险固，士民殷富。吾若据而有之，此帝王之资也。今刘表新亡，刘备新败，肃请奉命往江夏吊丧，因说刘备使抚刘表众将，同心一意，共破曹操；备若喜而从命，则大事可定矣。”权喜从其言，即遣鲁肃赍礼往江夏吊丧。却说玄德至江夏，与孔明、刘琦共议良策。孔明曰：“曹操势大，急难抵敌，不如往投东吴孙权，以为应援。使南北相持，吾等于中取利，有何不可？”玄德曰：“江东人物极多，必有远谋，安肯相容耶？”孔明笑曰：“今操引百万之众，虎踞江汉，江东安得不使人来探听虚实？若有人到此，亮借一帆风，直至江东，凭三寸不烂之舌，说南北两军互相吞并。若南军胜，共诛曹操以取荆州之地；若北军胜，则我乘势以取江南可也。”玄德曰：“此论甚高。但如何得江东人到？”
正说间，人报江东孙权差鲁肃来吊丧，船已傍岸。孔明笑曰：：大事济矣！”遂问刘琦曰：“往日孙策亡时，襄阳曾遣人去吊丧否？”琦曰：“江东与我家有杀父之仇，安得通庆吊之礼！”孔明曰：“然则鲁肃之来，非为吊丧，乃来探听军情也。”遂谓玄德曰：“鲁肃至，若问曹操动静，主公只推不知，再三问时，主公只说可问诸葛亮。”计会已定，使人迎接鲁肃。肃入城吊丧；收过礼物，刘琦请肃与玄德相见。礼毕，邀入后堂饮酒，肃曰：“久闻皇叔大名，无缘拜会；今幸得见。实为欣慰。近闻皇叔与曹操会战，必知彼虚实：敢问操军约有几何？”玄德曰：“备兵微将寡，一闻操至即走，竟不知彼虚实。”鲁肃曰：“闻皇叔用诸葛孔明之谋，两场火烧得曹操魂亡胆落，何言不知耶？”玄德曰：“除非问孔明，便知其详。”肃曰：“孔明安在？愿求一见。”玄德教请孔明出来相见。
肃见孔明礼毕，问曰：“向慕先生才德，未得拜晤；今幸相遇，愿闻目今安危之事。”孔明曰：“曹操奸计，亮已尽知；但恨力未及，故且避之。”肃曰：“皇叔今将止于此乎？”孔明曰：“使君与苍梧太守吴臣有旧，将往投之。”肃曰：“吴臣粮少兵微，自不能保，焉能容人？”孔明曰：“吴臣处虽不足久居，今且暂依之，别有良图。”肃曰：“孙将军虎踞六郡，兵精粮足，又极敬贤礼士，江表英雄，多归附之。今为君计。莫若遣心腹往结东吴，以共图大事。”孔明曰：“刘使君与孙将军自来无旧，恐虚费词说。且别无心腹之人可使。”肃曰：“先生之兄，现为江东参谋，日望与先生相见。肃不才，愿与公同见孙将军，共议大事。”玄德曰：“孔明是吾之师，顷刻不可相离，安可去也？”肃坚请孔明同去。玄德佯不许。孔明曰：“事急矣，请奉命一行。玄德方才许诺。鲁肃遂别了玄德、刘琦，与孔明登舟，望柴桑郡来。正是：只因诸葛扁舟去，致使曹兵一旦休。
不知孔明此去毕竟如何，且看下文分解。
', '', '', '', NULL, '', 'indent', 1536852581, '5b9a109267f356005c7fb3c7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639178, '三国演义 · 第四十三回 · 诸葛亮舌战群儒 鲁子敬力排众议', NULL, 4, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说鲁肃、孔明辞了玄德、刘琦，登舟望柴桑郡来。二人在舟中共议、鲁肃谓孔明曰：“先生见孙将军，切不可实言曹操兵多将广。”孔明曰：“不须子敬叮咛，亮自有对答之语。”及船到岸，肃请孔明于馆驿中暂歇，先自往见孙权。权正聚文武于堂上议事，闻鲁肃回，急召入问曰：“子敬往江夏，体探虚实若何？”肃曰：“已知其略，尚容徐禀。”权将曹操檄文示肃曰：“操昨遣使赍文至此，孤先发遣来使，现今会众商议未定。”肃接檄文观看。其略曰：“孤近承帝命，奉词伐罪。旄麾南指，刘琮束手；荆襄之民，望风归顺。今统雄兵百万，上将千员，欲与将军会猎于江夏，共伐刘备，同分土地，永结盟好。幸勿观望，速赐回音。”鲁肃看毕曰：“主公尊意若何？”权曰：“未有定论。”张昭曰：“曹操拥百万之众，借天子之名，以征四方，拒之不顺。且主公大势可以拒操者，长江也。今操既得荆州，长江之险，已与我共之矣，势不可敌。以愚之计，不如纳降，为万安之策。众谋士皆曰：“子布之言，正合天意。”孙权沉吟不语。张昭又曰：“主公不必多疑。如降操，则东吴民安，江南六郡可保矣。”孙权低头不语。
须臾，权起更衣，鲁肃随于权后。权知肃意，乃执肃手而言曰：“卿欲如何？”肃曰：“恰才众人所言，深误将军。众人皆可降曹操，惟将军不可降曹操。”权曰：“何以言之？”肃曰：“如肃等降操，当以肃还乡党，累官故不失州郡也；将军降操，欲安所归乎？位不过封侯，车不过一乘，骑不过一匹，从不过数人，岂得南面称孤哉！众人之意，各自为己，不可听也。将军宜早定大计。”权叹曰：“诸人议论，大失孤望。子敬开说大计，正与吾见相同。此天以子敬赐我也！但操新得袁绍之众，近又得荆州之兵，恐势大难以抵敌。”肃曰：“肃至江夏，引诸葛瑾之弟诸葛亮在此，主公可问之，便知虚实。”权曰：“卧龙先生在此乎？”肃曰：“现在馆驿中安歇。”权曰：“今日天晚，且未相见。来日聚文武于帐下，先教见我江东英俊，然后升堂议事。”肃领命而去。次日至馆驿中见孔明，又嘱曰：“今见我主，切不可言曹操兵多。”孔明笑曰：“亮自见机而变，决不有误。”肃乃引孔明至幕下。早见张昭、顾雍等一班文武二十余人，峨冠博带，整衣端坐。孔明逐一相见，各问姓名。施礼已毕，坐于客位。张昭等见孔明丰神飘洒，器宇轩昂，料道此人必来游说。张昭先以言挑之曰：“昭乃江东微末之士，久闻先生高卧隆中，自比管；乐。此语果有之乎？”孔明曰：“此亮平生小可之比也。”昭曰：“近闻刘豫州三顾先生于草庐之中，幸得先生，以为如鱼得水，思欲席卷荆襄。今一旦以属曹操，未审是何主见？”孔明自思张昭乃孙权手下第一个谋士，若不先难倒他，如何说得孙权，遂答曰：“吾观取汉上之地，易如反掌。我主刘豫州躬行仁义，不忍夺同宗之基业，故力辞之。刘琮孺子，听信佞言，暗自投降，致使曹操得以猖獗。今我主屯兵江夏，别有良图，非等闲可知也。”昭曰：“若此，是先生言行相违也。先生自比管、乐，管仲相桓公，霸诸侯，一匡天下；乐毅扶持微弱之燕，下齐七十余城：此二人者，真济世之才也。先生在草庐之中，但笑傲风月，抱膝危坐。今既从事刘豫州，当为生灵兴利除害，剿灭乱贼。且刘豫州未得先生之前，尚且纵横寰宇，割据城池；今得先生，人皆仰望。虽三尺童蒙，亦谓彪虎生翼，将见汉室复兴，曹氏即灭矣。朝廷旧臣，山林隐士，无不拭目而待：以为拂高天之云翳，仰日月之光辉，拯民于水火之中，措天下于衽席之上，在此时也。何先生自归豫州，曹兵一出，弃甲抛戈，望风而窜；上不能报刘表以安庶民，下不能辅孤子而据疆土；乃弃新野，走樊城，败当阳，奔夏口，无容身之地：是豫州既得先生之后，反不如其初也。管仲、乐毅，果如是乎？愚直之言，幸勿见怪！”孔明听罢，哑然而笑曰：“鹏飞万里，其志岂群鸟能识哉？譬如人染沉疴，当先用糜粥以饮之，和药以服之；待其腑脏调和，形体渐安，然后用肉食以补之，猛药以治之：则病根尽去，人得全生也。若不待气脉和缓，便投以猛药厚味，欲求安保，诚为难矣。吾主刘豫州，向日军败于汝南，寄迹刘表，兵不满千，将止关、张、赵云而已：此正如病势尫羸已极之时也，新野山僻小县，人民稀少，粮食鲜薄，豫州不过暂借以容身，岂真将坐守于此耶？夫以甲兵不完，城郭不固，军不经练，粮不继日，然而博望烧屯，白河用水，使夏侯惇，曹仁辈心惊胆裂：窃谓管仲、乐毅之用兵，未必过此。至于刘琮降操，豫州实出不知；且又不忍乘乱夺同宗之基业，此真大仁大义也。当阳之败，豫州见有数十万赴义之民，扶老携幼相随，不忍弃之，日行十里，不思进取江陵，甘与同败，此亦大仁大义也。寡不敌众，胜负乃其常事。昔高皇数败于项羽，而垓下一战成功，此非韩信之良谋乎？夫信久事高皇，未尝累胜。盖国家大计，社稷安危，是有主谋。非比夸辩之徒，虚誉欺人：坐议立谈，无人可及；临机应变，百无一能。诚为天下笑耳！”这一篇言语，说得张昭并无一言回答。
座上忽一人抗声问曰：“今曹公兵屯百万，将列千员，龙骧虎视，平吞江夏，公以为何如？”孔明视之，乃虞翻也。孔明曰：“曹操收袁绍蚁聚之兵，劫刘表乌合之众，虽数百万不足惧也。”虞翻冷笑曰：“军败于当阳，计穷于夏口，区区求教于人，而犹言‘不惧’，此真大言欺人也！”孔明曰：“刘豫州以数千仁义之师，安能敌百万残暴之众？退守夏口，所以待时也。今江东兵精粮足，且有长江之险，犹欲使其主屈膝降贼，不顾天下耻笑。由此论之，刘豫州真不惧操贼者矣！”虞翻不能对。
座间又一人问曰：“孔明欲效仪、秦之舌，游说东吴耶？”孔明视之，乃步骘也。孔明曰：“步子山以苏秦张仪为辩士，不知苏秦、张仪亦豪杰也。苏秦佩六国相印，张仪两次相秦，皆有匡扶人国之谋，非比畏强凌弱，惧刀避剑之人也。君等闻曹操虚发诈伪之词，便畏惧请降，敢笑苏秦、张仪乎？”步骘默然无语。忽一人问曰：“孔明以曹操何如人也？”孔明视其人，乃薛综也。孔明答曰：“曹操乃汉贼也，又何必问？”综曰：“公言差矣。汉传世至今，天数将终。今曹公已有天下三分之二，人皆归心。刘豫州不识天时，强欲与争，正如以卵击石，安得不败乎？”孔明厉声曰：“薛敬文安得出此无父无君之言乎！夫人生天地间，以忠孝为立身之本。公既为汉臣，则见有不臣之人，当誓共戮之：臣之道也。今曹操祖宗叨食汉禄，不思报效，反怀篡逆之心，天下之所共愤；公乃以天数归之，真无父无君之人也！不足与语！请勿复言！”薛综满面羞惭，不能对答。座上又一人应声问曰：“曹操虽挟天子以令诸侯，犹是相国曹参之后。刘豫州虽云中山靖王苗裔，却无可稽考，眼见只是织席贩屦之夫耳，何足与曹操抗衡哉！”孔明视之，乃陆绩也。孔明笑曰：“公非袁术座间怀桔之陆郎乎？请安坐，听吾一言：曹操既为曹相国之后，则世为汉臣矣；今乃专权肆横，欺凌君父，是不惟无君，亦且蔑祖，不惟汉室之乱臣，亦曹氏之贼子也。刘豫州堂堂帝胄，当今皇帝，按谱赐爵，何云无可稽考？且高祖起身亭长，而终有天下；织席贩屦，又何足为辱乎？公小儿之见，不足与高士共语！”陆绩语塞。
座上一人忽曰：“孔明所言，皆强词夺理，均非正论，不必再言。且请问孔明治何经典？”孔明视之，乃严酸也。孔明曰：“寻章摘句，世之腐儒也，何能兴邦立事？且古耕莘伊尹，钓渭子牙，张良、陈平之流。邓禹、耿弇之辈，皆有匡扶宇宙之才，未审其生平治何经典。岂亦效书生，区区于笔砚之间，数黑论黄，舞文弄墨而已乎？”严峻低头丧气而不能对。
忽又一人大声曰：“公好为大言，未必真有实学，恐适为儒者所笑耳。”孔明视其人，乃汝阳程德枢也。孔明答曰：“儒有君子小人之别。君子之儒，忠君爱国，守正恶邪，务使泽及当时，名留后世。若夫小人之儒，惟务雕虫，专工翰墨，青春作赋，皓首穷经；笔下虽有千言，胸中实无一策。且如杨雄以文章名世，而屈身事莽，不免投阁而死，此所谓小人之儒也；虽日赋万言，亦何取哉！”程德枢不能对。众人见孔明对答如流，尽皆失色。时座上张温、骆统二人，又欲问难。忽一人自外而入，厉声言曰：“孔明乃当世奇才，君等以唇舌相难，非敬客之礼也。曹操大军临境，不思退敌之策，乃徒斗口耶！”众视其人，乃零陵人，姓黄，名盖，字公覆，现为东吴粮官。当时黄盖谓孔明曰：“愚闻多言获利，不如默而无言。何不将金石之论为我主言之，乃与众人辩论也？”孔明曰：“诸君不知世务，互相问难，不容不答耳。”于是黄盖与鲁肃引孔明入。至中门，正遇诸葛瑾，孔明施礼。瑾曰：“贤弟既到江东，如何不来见我？”孔明曰：“弟既事刘豫州，理宜先公后私。公事未毕，不敢及私。望兄见谅。”瑾曰：“贤弟见过吴侯，却来叙话。”说罢自去。鲁肃曰：“适间所嘱，不可有误。”孔明点头应诺。引至堂上，孙权降阶而迎，优礼相待。施礼毕，赐孔明坐。众文武分两行而立。鲁肃立于孔明之侧，只看他讲话。孔明致玄德之意毕，偷眼看孙权：碧眼紫髯，堂堂一表。孔明暗思：“此人相貌非常，只可激，不可说。等他问时，用言激之便了。”献茶已毕，孙权曰：“多闻鲁子敬谈足下之才，今幸得相见，敢求教益。”孔明曰：“不才无学，有辱明问。”权曰：“足下近在新野，佐刘豫州与曹操决战，必深知彼军虚实。”孔明曰：“刘豫州兵微将寡，更兼新野城小无粮，安能与曹操相持。”权曰：“曹兵共有多少？”孔明曰：“马步水军，约有一百余万。”权曰：“莫非诈乎？”孔明曰：“非诈也。曹操就兖州已有青州军二十万；平了袁绍，又得五六十万；中原新招之兵三四十万；今又得荆州之军二三十万：以此计之，不下一百五十万。亮以百万言之，恐惊江东之士也。”鲁肃在旁，闻言失色，以目视孔明；孔明只做不见。权曰：“曹操部下战将，还有多少？”孔明曰：“足智多谋之士，能征惯战之将，何止一二千人。”权曰：“今曹操平了荆、楚，复有远图乎？”孔明曰：“即今沿江下寨，准备战船，不欲图江东，待取何地？”权曰：“若彼有吞并之意，战与不战，请足下为我一决。”孔明曰：“亮有一言，但恐将军不肯听从。”权曰：“愿闻高论。”孔明曰：“向者宇内大乱，故将军起江东，刘豫州收众汉南，与曹操并争天下。今操芟除大难，略已平矣；近又新破荆州，威震海内；纵有英雄，无用武之地：故豫州遁逃至此。愿将军量力而处之：若能以吴、越之众，与中国抗衡，不如早与之绝；若其不能，何不从众谋士之论，按兵束甲，北面而事之？”权未及答。孔明又曰：“将军外托服从之名，内怀疑贰之见，事急而不断，祸至无日矣！”权曰：“诚如君言，刘豫州何不降操？”孔明曰：“昔田横，齐之壮士耳，犹守义不辱。况刘豫州王室之胄，英才盖世，众士仰慕。事之不济，此乃天也。又安能屈处人下乎！”孙权听了孔明此言，不觉勃然变色，拂衣而起，退入后堂。众皆哂笑而散，鲁肃责孔明曰：“先生何故出此言？幸是吾主宽洪大度，不即面责。先生之言，藐视吾主甚矣。”孔明仰面笑曰：“何如此不能容物耶！我自有破曹之计，彼不问我，我故不言。”肃曰：“果有良策，肃当请主公求教。”孔明曰：“吾视曹操百万之众，如群蚁耳！但我一举手，则皆为齑粉矣！”肃闻言，便入后堂见孙权。权怒气未息，顾谓肃曰：“孔明欺吾太甚！”肃曰：“臣亦以此责孔明，孔明反笑主公不能容物。破曹之策，孔明不肯轻言，主公何不求之？”权回嗔作喜曰：“原来孔明有良谋，故以言词激我。我一时浅见，几误大事。”便同鲁肃重复出堂，再请孔明叙话。权见孔明，谢曰：“适来冒渎威严，幸勿见罪。”孔明亦谢曰：“亮言语冒犯，望乞恕罪。”权邀孔明入后堂，置酒相待。
数巡之后，权曰：“曹操平生所恶者：吕布、刘表、袁绍、袁术、豫州与孤耳。今数雄已灭，独豫州与孤尚存。孤不能以全吴之地，受制于人。吾计决矣。非刘豫州莫与当曹操者；然豫州新败之后，安能抗此难乎？”孔明曰：“豫州虽新败，然关云长犹率精兵万人；刘琦领江夏战士，亦不下万人。曹操之众，远来疲惫；近追豫州，轻骑一日夜行三百里，此所谓强弩之末，势不能穿鲁缟者也。且北方之人，不习水战。荆州士民附操者，迫于势耳，非本心也。今将军诚能与豫州协力同心，破曹军必矣。操军破，必北还，则荆、吴之势强，而鼎足之形成矣。成败之机，在于今日。惟将军裁之。”权大悦曰：“先生之言，顿开茅塞。吾意已决，更无他疑。即日商议起兵，共灭曹操！”遂令鲁肃将此意传谕文武官员，就送孔明于馆驿安歇。张昭知孙权欲兴兵，遂与众议曰：“中了孔明之计也！”急入见权曰：“昭等闻主公将兴兵与曹操争锋。主公自思比袁绍若何？曹操向日兵微将寡，尚能一鼓克袁绍；何况今日拥百万之众南征，岂可轻敌？若听诸葛亮之言，妄动甲兵，此所谓负薪救火也。”孙权只低头不语。顾雍曰：“刘备因为曹操所败，故欲借我江东之兵以拒之，主公奈何为其所用乎；愿听子布之言。”孙权沉吟未决。张昭等出，鲁肃入见曰：“适张子布等，又劝主公休动兵，力主降议，此皆全躯保妻子之臣，为自谋之计耳。原主公勿听也。”孙权尚在沉吟。肃曰：“主公若迟疑，必为众人误矣。”权曰：“卿且暂退，容我三思。”肃乃退出。时武将或有要战的，文官都是要降的，议论纷纷不一。且说孙权退入内宅，寝食不安，犹豫不决。吴国太见权如此，问曰：“何事在心，寝食俱废？”权曰：“今曹操屯兵于江汉，有下江南之意。问诸文武，或欲降者，或欲战者。欲待战来，恐寡不敌众；欲待降来，又恐曹操不容：因此犹豫不决。”吴国太曰：“汝何不记吾姐临终之语乎？”孙权如醉方醒，似梦初觉，想出这句话来。正是：追思国母临终语，引得周郎立战功。
毕竟说着甚的，且看下文分解。', '', '', '', NULL, '', 'indent', 1536852584, '5b9a10ad1579a3003a41679f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639179, '三国演义 · 第四十四回 · 孔明用智激周瑜 孙权决计破曹操', NULL, 2, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说吴国太见孙权疑惑不决，乃谓之曰：“先姊遗言云：‘伯符临终有言：内事不决问张昭，外事不决问周瑜。’今何不请公瑾问之？”权大喜，即遣使往鄱阳请周瑜议事。原来周瑜在鄱阳湖训练水师，闻曹操大军至汉上，便星夜回柴桑郡议军机事。使者未发，周瑜已先到。鲁肃与瑜最厚，先来接着，将前项事细述一番。周瑜曰：“子敬休忧，瑜自有主张。今可速请孔明来相见。”鲁肃上马去了。
周瑜方才歇息，忽报张昭、顾雍、张纮、步骘四人来相探。瑜接入堂中坐定，叙寒温毕。张昭曰：“都督知江东之利害否？”瑜曰：“未知也。”昭曰：“曹操拥众百万，屯于汉上，昨传檄文至此，欲请主公会猎于江夏。虽有相吞之意，尚未露其形。昭等劝主公且降之，庶免江东之祸。不想鲁子敬从江夏带刘备军师诸葛亮至此，彼因自欲雪愤，特下说词以激主公。子敬却执迷不悟。正欲待都督一决。”瑜曰：“公等之见皆同否？”顾雍等曰：“所议皆同。”瑜曰：“吾亦欲降久矣。公等请回，明早见主公，自有定议。”昭等辞去。
少顷，又报程普、黄盖、韩当等一班战将来见。瑜迎入，各问慰讫。程普曰：“都督知江东早晚属他人否？”瑜曰：“未知也。”普曰：“吾等自随孙将军开基创业，大小数百战，方才战得六郡城池。今主公听谋士之言，欲降曹操，此真可耻可惜之事！吾等宁死不辱。望都督劝主公决计兴兵，吾等愿效死战。”瑜曰：“将军等所见皆同否？”黄盖忿然而起，以手拍额曰：“吾头可断，誓不降曹！”众人皆曰：“吾等都不愿降！”瑜曰：“吾正欲与曹操决战，安肯投降！将军等请回。瑜见主公，自有定议。”程普等别去。
又未几，诸葛瑾、吕范等一班儿文官相候。瑜迎入，讲礼方毕，诸葛瑾曰：“舍弟诸葛亮自汉上来，言刘豫州欲结东吴，共伐曹操，文武商议未定。因舍弟为使，瑾不敢多言，专候都督来决此事。”瑜曰：“以公论之若何？”瑾曰：“降者易安，战者难保。”周瑜笑曰：“瑜自有主张。来日同至府下定议。”瑾等辞退。忽又报吕蒙、甘宁等一班儿来见。瑜请入，亦叙谈此事。有要战者，有要降者，互相争论。瑜曰：“不必多言，来日都到府下公议。”众乃辞去。周瑜冷笑不止。
至晚，人报鲁子敬引孔明来拜。瑜出中门迎入。叙礼毕，分宾主而坐。肃先问瑜曰：“今曹操驱众南侵，和与战二策，主公不能决，一听于将军。将军之意若何？”瑜曰：“曹操以天子为名，其师不可拒。且其势大，未可轻敌。战则必败，降则易安。吾意已决。来日见主公，便当遣使纳降。”鲁肃愕然曰：“君言差矣！江东基业，已历三世，岂可一旦弃于他人？伯符遗言，外事付托将军。今正欲仗将军保全国家，为泰山之靠，奈何从懦夫之议耶？”瑜曰：“江东六郡，生灵无限；若罹兵革之祸，必有归怨于我，故决计请降耳。”肃曰：“不然。以将军之英雄，东吴之险固，操未必便能得志也。”
二人互相争辩，孔明只袖手冷笑。瑜曰：“先生何故哂笑？”孔明曰：“亮不笑别人，笑子敬不识时务耳。”肃曰：“先生如何反笑我不识时务？”孔明曰：“公瑾主意欲降操，甚为合理。”瑜曰：“孔明乃识时务之士，必与吾有同心。”肃曰：“孔明，你也如何说此？”孔明曰：“操极善用兵，天下莫敢当。向只有吕布、袁绍、袁术、刘表敢与对敌。今数人皆被操灭，天下无人矣。独有刘豫州不识时务，强与争衡；今孤身江夏，存亡未保。将军决计降曹，可以保妻子，可以全富贵。国祚迁移，付之天命，何足惜哉！”鲁肃大怒曰：“汝教吾主屈膝受辱于国贼乎！”孔明曰：“愚有一计：并不劳牵羊担酒，纳土献印；亦不须亲自渡江；只须遣一介之使，扁舟送两个人到江上。操一得此两人，百万之众，皆卸甲卷旗而退矣。”瑜曰：“用何二人，可退操兵？”孔明曰：“江东去此两人，如大木飘一叶，太仓减一粟耳；而操得之，必大喜而去。”瑜又问：“果用何二人？”孔明曰：“亮居隆中时，即闻操于漳河新造一台，名曰铜雀，极其壮丽；广选天下美女以实其中。操本好色之徒，久闻江东乔公有二女，长曰大乔，次曰小乔，有沉鱼落雁之容，闭月羞花之貌。操曾发誓曰：吾一愿扫平四海，以成帝业；一愿得江东二乔，置之铜雀台，以乐晚年，虽死无恨矣。今虽引百万之众，虎视江南，其实为此二女也。将军何不去寻乔公，以千金买此二女，差人送与曹操，操得二女，称心满意，必班师矣。此范蠡献西施之计，何不速为之？”瑜曰：“操欲得二乔，有何证验？”孔明曰：“曹操幼子曹植，字子建，下笔成文。操尝命作一赋，名曰《铜雀台赋》。赋中之意，单道他家合为天子，誓取二乔。”瑜曰：“此赋公能记否？”孔明曰：“吾爱其文华美，尝窃记之。”瑜曰：“试请一诵。”孔明即时诵《铜雀台赋》云：“从明后以嬉游兮，登层台以娱情。见太府之广开兮。观圣德之所营。建高门之嵯峨兮，浮双阙乎太清。立中天之华观兮，连飞阁乎西城。临漳水之长流兮，望园果之滋荣。立双台于左右兮，有玉龙与金凤。揽二乔于东南兮，乐朝夕之与共。俯皇都之宏丽兮，瞰云霞之浮动。欣群才之来萃兮，协飞熊之吉梦。仰春风之和穆兮，听百鸟之悲鸣。天云垣其既立兮，家愿得乎双逞，扬仁化于宇宙兮，尽肃恭于上京。惟桓文之为盛兮，岂足方乎圣明？休矣！美矣！惠泽远扬。翼佐我皇家兮，宁彼四方。同天地之规量兮，齐日月之辉光。永贵尊而无极兮，等年寿于东皇。御龙兮以遨游兮，回鸾驾而周章。恩化及乎四海兮，嘉物阜而民康。愿斯台之永固兮，乐终古而未央！”
周瑜听罢，勃然大怒，离座指北而骂曰：“老贼欺吾太甚！”孔明急起止之曰：“昔单于屡侵疆界，汉天子许以公主和亲，今何惜民间二女乎？”瑜曰：“公有所不知：大乔是孙伯符将军主妇，小乔乃瑜之妻也。”孔明佯作惶恐之状，曰：“亮实不知。失口乱言，死罪！死罪！”瑜曰：“吾与老贼誓不两立！”孔明曰：“事须三思，免致后悔。”瑜曰：“吾承伯符寄托，安有屈身降操之理？适来所言，故相试耳。吾自离鄱阳湖，便有北伐之心，虽刀斧加头，不易其志也！望孔明助一臂之力，同破曹贼。”孔明曰：“若蒙不弃，愿效犬马之劳，早晚拱听驱策。”瑜曰：“来日入见主公，便议起兵。”孔明与鲁肃辞出，相别而去。次日清晨，孙权升堂。左边文官张昭、顾雍等三十余人；右边武官程普、黄盖等三十余人：衣冠济济，剑佩锵锵，分班侍立。少顷，周瑜入见。礼毕，孙权问慰罢，瑜曰：“近闻曹操引兵屯汉上，驰书至此，主公尊意若何？”权即取檄文与周瑜看。瑜看毕，笑曰：“老贼以我江东无人，敢如此相侮耶！”权曰：“君之意若何？”瑜曰：“主公曾与众文武商议否？”权曰：“连日议此事：有劝我降者，有劝我战者。吾意未定，故请公瑾一决。”瑜曰：“谁劝主公降？”权曰：“张子布等皆主其意。”瑜即问张昭曰：“愿闻先生所以主降之意。”昭曰：“曹操挟天子而征四方，动以朝廷为名；近又得荆州，威势愈大。吾江东可以拒操者，长江耳。今操艨艟战舰，何止千百？水陆并进，何可当之？不如且降，更图后计。”瑜曰：“此迂儒之论也！江东自开国以来，今历三世，安忍一旦废弃？”权曰：“若此，计将安出？”瑜曰：“操虽托名汉相，实为汉贼。将军以神武雄才，仗父兄余业，据有江东，兵精粮足，正当横行天下，为国家除残去暴，奈何降贼耶？且操今此来，多犯兵家之忌：北土未平，马腾、韩遂为其后患，而操久于南征，一忌也；北军不熟水战，操舍鞍马，仗舟楫，与东吴争衡，二忌也；又时值隆冬盛寒，马无稿草，三忌也；驱中国士卒，远涉江湖，不服水土，多生疾病，四忌也。操兵犯此数忌，虽多必败。将军擒操，正在今日。瑜请得精兵数万人，进屯夏口，为将军破之！”权矍然起曰：“老贼欲废汉自立久矣，所惧二袁、吕布、刘表与孤耳。今数雄已灭，惟孤尚存。孤与老贼，誓不两立！卿言当伐，甚合孤意。此天以卿授我也。”瑜曰：“臣为将军决一血战，万死不辞。只恐将军狐疑不定。”权拔佩剑砍面前奏案一角曰：“诸官将有再言降操者，与此案同！”言罢，便将此剑赐周瑜，即封瑜为大都督，程普为副都督，鲁肃为赞军校尉。如文武官将有不听号令者，即以此剑诛之。瑜受了剑，对众言曰：“吾奉主公之命，率众破曹。诸将官吏来日俱于江畔行营听令。如迟误者，依七禁令五十四斩施行。”言罢，辞了孙权，起身出府。众文武各无言而散。周瑜回到下处，便请孔明议事。孔明至。瑜曰：“今日府下公议已定，愿求破曹良策。”孔明曰：“孙将军心尚未稳，不可以决策也。”瑜曰：“何谓心不稳？”孔明曰：“心怯曹兵之多，怀寡不敌众之意。将军能以军数开解，使其了然无疑，然后大事可成。”瑜曰：“先生之论甚善。”乃复入见孙权。权曰：“公瑾夜至，必有事故。”瑜曰：“来日调拨军马，主公心有疑否？”权曰“但忧曹操兵多，寡不敌众耳。他无所疑。”瑜笑曰：“瑜特为此来开解主公。主公因见操檄文，言水陆大军百万，故怀疑惧，不复料其虚实。今以实较之：彼将中国之兵，不过十五六万，且已久疲；所得袁氏之众，亦止七八万耳，尚多怀疑未服。夫以久疲之卒，御狐疑之众，其数虽多，不足畏也。瑜得五万兵，自足破之。愿主公勿以为虑。”权抚瑜背曰：“公瑾此言，足释吾疑。子布无谋，深失孤望；独卿及子敬，与孤同心耳。卿可与子敬、程普即日选军前进。孤当续发人马，多载资粮，为卿后应。卿前军倘不如意，便还就孤。孤当亲与操贼决战，更无他疑。”周瑜谢出，暗忖曰：“孔明早已料着吴侯之心。其计画又高我一头。久必为江东之患，不如杀之。乃令人连夜请鲁肃入帐，言欲杀孔明之事。肃曰：“不可。今操贼未破，先杀贤士，是自去其助也。”瑜曰：“此人助刘备，必为江东之患。”肃曰：“诸葛瑾乃其亲兄，可令招此人同事东吴，岂不妙哉？”瑜善其言。
次日平明，瑜赴行营，升中军帐高坐。左右立刀斧手，聚集文官武将听令。原来程普年长于瑜，今瑜爵居其上，心中不乐：是日乃托病不出，令长子程咨自代。瑜令众将曰：“王法无亲，诸君各守乃职。方今曹操弄权，甚于董卓：囚天子于许昌。屯暴兵于境上。吾今奉命讨之，诸君幸皆努力向前。大军到处，不得扰民。赏劳罚罪，并不徇纵。”令毕，即差韩当、黄盖为前部先锋，领本部战船，即日起行，前至三江口下寨，别听将令；蒋钦、周泰为第二队；凌统、潘璋为第三队；太史慈、吕蒙为第四队；陆逊、董袭为第五队；吕范、朱治为四方巡警使，催督六郡官军，水陆并进，克期取齐。调拨已毕，诸将各自收拾船只军器起行。程咨回见父程普，说周瑜调兵，动止有法。普大惊曰：“吾素欺周郎懦弱，不足为将；今能如此，真将才也！我如何不服！”遂亲诣行营谢罪。瑜亦逊谢。次日，瑜请诸葛瑾，谓曰：“令弟孔明有王佐之才，如何屈身事刘备？今幸至江东，欲烦先生不惜齿牙余论，使令弟弃刘备而事东吴，则主公既得良辅，而先生兄弟又得相见，岂不美哉？先生幸即一行。”瑾曰：“瑾自至江东，愧无寸功。今都督有命，敢不效力。”即时上马，径投驿亭来见孔明。孔明接入，哭拜，各诉阔情。瑾泣曰：“弟知伯夷、叔齐乎？”孔明暗思：“此必周郎教来说我也。”遂答曰：“夷、齐古之圣贤也。”瑾曰：“夷、齐虽至饿死首阳山下，兄弟二人亦在一处。我今与你同胞共乳，乃各事其主，不能旦暮相聚。视夷、齐之为人，能无愧乎？”孔明曰：“兄所言者，情也；弟所守者，义也。弟与兄皆汉人。今刘皇叔乃汉室之胄，兄若能去东吴，而与弟同事刘皇叔，则上不愧为汉臣，而骨肉又得相聚，此情义两全之策也。不识兄意以为何如？”瑾思曰：“我来说他，反被他说了我也。”遂无言回答，起身辞去。回见周瑜，细述孔明之言。瑜曰：“公意若何？”瑾曰：“吾受孙将军厚恩，安肯相背！”瑜曰：“公既忠心事主，不必多言。吾自有伏孔明之计。”正是：智与智逢宜必合，才和才角又难容。
毕竟周瑜定何计伏孔明，且看下回分解。', '', '', '', NULL, '', 'indent', 1536852584, '5b9a10c5808ca43cd2145430', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639180, '三国演义 · 第四十五回 · 三江口曹操折兵 群英会蒋干中计', NULL, 2, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说周瑜闻诸葛瑾之言，转恨孔明，存心欲谋杀之。次日，点齐军将，入辞孙权。权曰：“卿先行，孤即起兵继后。”瑜辞出，与程普、鲁肃领兵起行，便邀孔明同住。孔明欣然从之。一同登舟，驾起帆樯，迤逦望夏口而进。离三江口五六十里，船依次第歇定。周瑜在中央下寨，岸上依西山结营，周围屯住。孔明只在一叶小舟内安身。
周瑜分拨已定，使人请孔明议事。孔明至中军帐，叙礼毕，瑜曰：“昔曹操兵少，袁绍兵多，而操反胜绍者，因用许攸之谋，先断乌巢之粮也。今操兵八十三万，我兵只五六万，安能拒之？亦必须先断操之粮，然后可破。我已探知操军粮草，俱屯于聚铁山。先生久居汉上，熟知地理。敢烦先生与关、张、子龙辈——吾亦助兵千人——星夜往聚铁山断操粮道。彼此各为主人之事，幸勿推调。”孔明暗思：“此因说我不动，设计害我。我若推调，必为所笑。不如应之，别有计议。”乃欣然领诺。瑜大喜。孔明辞出。鲁肃密谓瑜曰：“公使孔明劫粮，是何意见？”瑜曰：“吾欲杀孔明，恐惹人笑，故借曹操之手杀之，以绝后患耳。”肃闻言，乃往见孔明，看他知也不知。只见孔明略无难色，整点军马要行。肃不忍，以言挑之曰：“先生此去可成功否？”孔明笑曰：“吾水战、步战、马战、车战，各尽其妙，何愁功绩不成，非比江东公与周郎辈止一能也。”肃曰：“吾与公瑾何谓一能？”孔明曰：“吾闻江南小儿谣言云：‘伏路把关饶子敬，临江水战有周郎。’公等于陆地但能伏路把关；周公瑾但堪水战，不能陆战耳。”
肃乃以此言告知周瑜。瑜怒曰：“何欺我不能陆战耶！不用他去！我自引一万马军，往聚铁山断操粮道：”肃又将此言告孔明。孔明笑曰：“公瑾令吾断粮者，实欲使曹操杀吾耳。吾故以片言戏之，公瑾便容纳不下。目今用人之际，只愿吴侯与刘使君同心，则功可成；如各相谋害，大事休矣。操贼多谋，他平生惯断人粮道，今如何不以重兵提备？公瑾若去，必为所擒。今只当先决水战，挫动北军锐气，别寻妙计破之。望子敬善言以告公瑾为幸。”鲁肃遂连夜回见周瑜，备述孔明之言。瑜摇首顿足曰：“此人见识胜吾十倍，今不除之，后必为我国之祸！”肃曰：“今用人之际，望以国家为重。且待破曹之后，图之未晚。”瑜然其说。
却说玄德分付刘琦守江夏，自领众将引兵往夏口。遥望江南岸旗幡隐隐，戈戟重重，料是东吴已动兵矣，乃尽移江夏之兵，至樊口屯扎。玄德聚众曰：“孔明一去东吴，杳无音信，不知事体如何。谁人可去探听虚实回报？”糜竺曰：“竺愿往。”玄德乃备羊酒礼物，令糜竺至东吴，以犒军为名，探听虚实。竺领命，驾小舟顺流而下，径至周瑜大寨前。军士入报周瑜，瑜召入。竺再拜，致玄德相敬之意，献上酒礼。瑜受讫，设宴款待糜竺。竺曰：“孔明在此已久，今愿与同回。”瑜曰：“孔明方与我同谋破曹，岂可便去？吾亦欲见刘豫州，共议良策；奈身统大军，不可暂离。若豫州肯枉驾来临，深慰所望。”竺应诺，拜辞而回。肃问瑜曰：“公欲见玄德，有何计议？”瑜曰：“玄德世之枭雄，不可不除。吾今乘机诱至杀之，实为国家除一后患。”鲁肃再三劝谏，瑜只不听，遂传密令：“如玄德至，先埋伏刀斧手五十人于壁衣中，看吾掷杯为号，便出下手。”却说糜竺回见玄德，具言周瑜欲请主公到彼面会，别有商议。玄德便教收拾快船一只，只今便行。云长谏曰：“周瑜多谋之士，又无孔明书信，恐其中有诈，不可轻去。”玄德曰：“我今结东吴以共破曹操，周郎欲见我，我若不往，非同盟之意。两相猜忌，事不谐矣。”云长曰：“兄长若坚意要去，弟愿同往。”张飞曰：“我也跟去。”玄德曰：“只云长随我去。翼德与子龙守寨。简雍固守鄂县。我去便回。”分付毕，即与云长乘小舟，并从者二十余人，飞棹赴江东。玄德观看江东艨艟战舰、旌旗甲兵，左右分布整齐，心中甚喜。军士飞报周瑜：“刘豫州来了。”瑜问：“带多少船只来？”军士答曰：“只有一只船，二十余从人。”瑜笑曰：“此人命合体矣！”乃命刀斧手先埋伏定，然后出寨迎接。玄德引云长等二十余人，直到中军帐，叙礼毕，瑜请玄德上坐。玄德曰：“将军名传天下，备不才，何烦将军重礼？”乃分宾主而坐。周瑜设宴相待。
且说孔明偶来江边，闻说玄德来此与都督相会，吃了一惊，急入中军帐窃看动静。只见周瑜面有杀气，两边壁衣中密排刀斧手。孔明大惊曰：“似此如之奈何？”回视玄德，谈笑自若；却见玄德背后一人，按剑而立，乃云长也。孔明喜曰：“吾主无危矣。”遂不复入，仍回身至江边等候。
周瑜与玄德饮宴，酒行数巡，瑜起身把盏，猛见云长按剑立于玄德背后，忙问何人。玄德曰：“吾弟关云长也。”瑜惊曰：“非向日斩颜良、文丑者乎？”玄德曰：“然也。”瑜大惊，汗流满背，便斟酒与云长把盏。少顷，鲁肃入。玄德曰：“孔明何在？烦子敬请来一会。”瑜曰：“且待破了曹操，与孔明相会未迟。”玄德不敢再言。云长以目视玄德。玄德会意，即起身辞瑜曰：“备暂告别。即日破敌收功之后，专当叩贺。”瑜亦不留，送出辕门。玄德别了周瑜，与云长等来至江边，只见孔明已在舟中。玄德大喜。孔明曰：“主公知今日之危乎？”玄德愕然曰：“不知也。”孔明曰：“若无云长，主公几为周郎所害矣。”玄德方才省悟，便请孔明同回樊口。孔明曰：“亮虽居虎口，安如泰山。今主公但收拾船只军马候用。以十一月二十甲子日后为期，可令子龙驾小舟来南岸边等候。切勿有误。”玄德问其意。孔明曰：“但看东南风起，亮必还矣。”玄德再欲问时，孔明催促玄德作速开船。言讫自回。玄德与云长及从人开船，行不数里，忽见上流头放下五六十只船来。船头上一员大将，横矛而立，乃张飞也。因恐玄德有失，云长独力难支，特来接应。于是三人一同回寨，不在话下。
却说周瑜送了玄德，回至寨中，鲁肃入问曰：“公既诱玄德至此，为何又不下手？”瑜曰：“关云长，世之虎将也，与玄德行坐相随，吾若下手，他必来害我。”肃愕然。忽报曹操遣使送书至。瑜唤入。使者呈上书看时，封面上判云：“汉大丞相付周都督开拆。”瑜大怒，更不开看，将书扯碎，掷于地下，喝斩来使。肃曰：“两国相争，不斩来使。瑜曰：“斩使以示威！”遂斩使者，将首级付从人持回。随令甘宁为先锋，韩当为左翼，蒋钦为右翼。瑜自部领诸将接应。来日四更造饭，五更开船，鸣鼓呐喊而进。
却说曹操知周瑜毁书斩使，大怒，便唤蔡瑁、张允等一班荆州降将为前部，操自为后军，催督战船，到三江口。早见东吴船只，蔽江而来。为首一员大将，坐在船头上大呼曰：“吾乃甘宁也！谁敢来与我决战？”蔡瑁令弟蔡□前进。两船将近，甘宁拈弓搭箭，望蔡？熏射来，应弦而倒。宁驱船大进，万弩齐发。曹军不能抵当。右边蒋钦，左边韩当，直冲入曹军队中。曹军大半是青、徐之兵，素不习水战，大江面上，战船一摆，早立脚不住。甘宁等三路战船，纵横水面。周瑜又催船助战。曹军中箭着炮者，不计其数，从巳时直杀到未时。周瑜虽得利，只恐寡不敌众，遂下令鸣金，收住船只。
曹军败回。操登旱寨，再整军士，唤蔡瑁、张允责之曰：“东吴兵少，反为所败，是汝等不用心耳！”蔡瑁曰：“荆州水军，久不操练；青、徐之军，又素不习水战。故尔致败。今当先立水寨，令青、徐军在中，荆州军在外，每日教习精熟，方可用之。”操曰：“汝既为水军都督，可以便宜从事，何必禀我！”于是张、蔡二人，自去训练水军。沿江一带分二十四座水门，以大船居于外为城郭，小船居于内，可通往来，至晚点上灯火，照得天心水面通红。旱寨三百余里，烟火不绝。
却说周瑜得胜回寨，犒赏三军，一面差人到吴侯处报捷。当夜瑜登高观望，只见西边火光接天。左右告曰：“此皆北军灯火之光也。”瑜亦心惊。次日，瑜欲亲往探看曹军水寨，乃命收拾楼船一只，带着鼓东，随行健将数员，各带强弓硬弩，一齐上船迤逦前进。至操寨边，瑜命下了矴石，楼船上鼓乐齐奏。瑜暗窥他水寨，大惊曰：“此深得水军之妙也！”问：“水军都督是谁？”左右曰：“蔡瑁、张允。”瑜思曰：“二人久居江东，谙习水战，吾必设计先除此二人，然后可以破曹。”正窥看间，早有曹军飞报曹操，说：“周瑜偷看吾寨。”操命纵船擒捉。瑜见水寨中旗号动，急教收起矴石，两边四下一齐轮转橹棹，望江面上如飞而去。比及曹寨中船出时，周瑜的楼船已离了十数里远，追之不及，回报曹操。
操问众将曰：“昨日输了一阵，挫动锐气；今又被他深窥吾寨。吾当作何计破之？”言未毕，忽帐下一人出曰：“某自幼与周郎同窗交契，愿凭三寸不烂之舌，往江东说此人来降。”曹操大喜，视之，乃九江人，姓蒋，名干，字子翼，现为帐下幕宾。操问曰：“子翼与周公瑾相厚乎？”干曰：“丞相放心。干到江左，必要成功。”操问：“要将何物去？”干曰：“只消一童随往，二仆驾舟，其余不用。”操甚喜，置酒与蒋干送行。
干葛巾布袍，驾一只小舟，径到周瑜寨中，命传报：“故人蒋干相访。”周瑜正在帐中议事，闻将干至，笑谓诸将曰：“说客至矣！”遂与众将附耳低言，如此如此。众皆应命而去。瑜整衣冠，引从者数百，皆锦衣花帽，前后簇拥而出。蒋干引一青衣小童，昂然而来。瑜拜迎之。干曰：“公瑾别来无恙！”瑜曰：“子翼良苦：远涉江湖，为曹氏作说客耶？”干愕然曰：“吾久别足下，特来叙旧，奈何疑我作说客也？”瑜笑曰：“吾虽不及师旷之聪，闻弦歌而知雅意。”干曰：“足下待故人如此，便请告退。”瑜笑而挽其臂曰：“吾但恐兄为曹氏作说客耳。既无此心，何速去也？”遂同入帐。
叙礼毕，坐定，即传令悉召江左英杰与子翼相见。须臾，文官武将，各穿锦衣；帐下偏裨将校，都披银铠：分两行而入。瑜都教相见毕，就列于两傍而坐。大张筵席，奏军中得胜之乐，轮换行酒。瑜告众官曰：“此吾同窗契友也。虽从江北到此，却不是曹家说客。公等勿疑。”遂解佩剑付太史慈曰：“公可佩我剑作监酒：今日宴饮，但叙朋友交情；如有提起曹操与东吴军旅之事者，即斩之！”太史慈应诺，按剑坐于席上。蒋干惊愕，不敢多言。周瑜曰：“吾自领军以来，滴酒不饮；今日见了故人，又无疑忌，当饮一醉。”说罢，大笑畅饮。座上觥筹交错。饮至半醋，瑜携干手，同步出帐外。左右军士，皆全装惯带，持戈执戟而立。瑜曰：“吾之军士，颇雄壮否？”干曰：“真熊虎之士也，”瑜又引干到帐后一望，粮草堆如山积。瑜曰：“吾之粮草，颇足备否？”干曰：“兵精粮足，名不虚传。”瑜佯醉大笑曰：“想周瑜与子翼同学业时，不曾望有今日。”干曰：“以吾兄高才，实不为过。”瑜执干手曰：“大丈夫处世，遇知己之主，外托君臣之义，内结骨肉之恩，言必行，计必从，祸福共之。假使苏秦、张仪、陆贾、郦生复出，口似悬河，舌如利刃，安能动我心哉！”言罢大笑。蒋干面如土色。
瑜复携干入帐，会诸将再饮；因指诸将曰：“此皆江东之英杰。今日此会，可名‘群英会’。”饮至天晚，点上灯烛，瑜自起舞剑作歌。歌曰：“丈夫处世兮立功名；立功名兮慰平生。慰平生兮吾将醉；吾将醉兮发狂吟！”歌罢，满座欢笑。
至夜深，干辞曰：“不胜酒力矣。”瑜命撤席，诸将辞出。瑜曰：“久不与子翼同榻，今宵抵足而眠。”于是佯作大醉之状，携干入帐共寝。瑜和衣卧倒，呕吐狼藉。蒋干如何睡得着？伏枕听时，军中鼓打二更，起视残灯尚明。看周瑜时，鼻息如雷。干见帐内桌上，堆着一卷文书，乃起床偷视之，却都是往来书信。内有一封，上写“蔡瑁张允谨封。”干大惊，暗读之。书略曰：“某等降曹，非图仕禄，迫于势耳。今已赚北军困于寨中，但得其便，即将操贼之首，献于麾下。早晚人到，便有关报。幸勿见疑。先此敬覆。”干思曰：“原来蔡瑁、张允结连东吴！”遂将书暗藏于衣内。再欲检看他书时，床上周瑜翻身，干急灭灯就寝。瑜口内含糊曰：“子翼，我数日之内，教你看操贼之首！”干勉强应之。瑜又曰：“子翼，且住！……教你看操贼之首！……”及干问之，瑜又睡着。干伏于床上，将近四更，只听得有人入帐唤曰：“都督醒否？”周瑜梦中做忽觉之状，故问那人曰：“床上睡着何人？”答曰：“都督请子翼同寝，何故忘却？”瑜懊悔曰：“吾平日未尝饮醉；昨日醉后失事，不知可曾说甚言语？”那人曰：“江北有人到此。”瑜喝：“低声！”便唤：“子翼。”蒋干只妆睡着。瑜潜出帐。干窃听之，只闻有人在外曰：“张、蔡二都督道：急切不得下手，……”后面言语颇低，听不真实。少顷，瑜入帐，又唤：“子翼。”蒋干只是不应，蒙头假睡。瑜亦解衣就寝。
干寻思：“周瑜是个精细人，天明寻书不见，必然害我。”睡至五更，干起唤周瑜；瑜却睡着。干戴上巾帻，潜步出帐，唤了小童，径出辕门。军士问：“先生那里去？”干曰：“吾在此恐误都督事，权且告别。”军士亦不阻当。干下船，飞棹回见曹操。操问：“子翼干事若何？”干曰：“周瑜雅量高致，非言词所能动也。”操怒曰：“事又不济，反为所笑！”干曰：“虽不能说周瑜，却与丞相打听得一件事。乞退左右。”
干取出书信，将上项事逐一说与曹操。操大怒曰：“二贼如此无礼耶！”即便唤蔡瑁、张允到帐下。操曰：“我欲使汝二人进兵。”瑁曰：“军尚未曾练熟，不可轻进。”操怒曰：“军若练熟，吾首级献于周郎矣！”蔡、张二人不知其意，惊慌不能回答。操喝武士推出斩之。须臾，献头帐下，操方省悟曰：“吾中计矣！”后人有诗叹曰：“曹操奸雄不可当，一时诡计中周郎。蔡张卖主求生计，谁料今朝剑下亡！”众将见杀了张、蔡二人，入问其故。操虽心知中计，却不肯认错，乃谓众将曰：“二人怠慢军法，吾故斩之。”众皆嗟呀不已。
操于众将内选毛玠、于禁为水军都督，以代蔡、张二人之职。细作探知，报过江东。周瑜大喜曰：“吾所患者，此二人耳。今既剿除，吾无忧矣。”肃曰：“都督用兵如此，何愁曹贼不破乎！”瑜曰：“吾料诸将不知此计，独有诸葛亮识见胜我，想此谋亦不能瞒也。子敬试以言挑之，看他知也不知，便当回报。”正是：还将反间成功事，去试从旁冷眼人。
未知肃去问孔明还是如何，且看下文分解。', '', '', '', '[{"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42afc6e67846a9227bfc", "shortContent": "春愁艳色中，夏景繁华里，秋悲霜降后，冬恨雪零时。触目攒眉，许多情意，心事有谁知？三年里几字不通，一日间百忧并集。\n〔小梁州〕碧碧天，茫茫不尽；念青鸾[2]，杳杳无期。可怜辜负深盟誓。玉人何处？招之不至。乐昌镜破[3]，凤钏双离。萧郎[4]箫断，蔡琰笳悲。怪累朝鸟雀频啼，喜今宵玉手同携。《小梁州》，漫把曲歌歌，大都来细把离情诉，声声短叹长吁。钟情到此，悲欢离合都经历。怅杀我无双翼。安得双双花并蒂、对...", "authors": ["宁稼雨", "牛景丽"], "pressName": "上海辞书出版社"}]', '', 'indent', 1536852587, '5b9a10de1579a3003a416aae', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639181, '三国演义 · 第四十六回 · 用奇谋孔明借箭 献密计黄盖受刑', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说鲁肃领了周瑜言语，径来舟中相探孔明。孔明接入小舟对坐。肃曰：“连日措办军务，有失听教。”孔明曰：“便是亮亦未与都督贺喜。”肃曰：“何喜？”孔明曰：“公瑾使先生来探亮知也不知，便是这件事可贺喜耳。”諕得鲁肃失色问曰：“先生何由知之？”孔明曰：“这条计只好弄蒋干。曹操、虽被一时瞒过，必然便省悟，只是不肯认错耳。今蔡、张两人既死，江东无患矣，如何不贺喜！吾闻曹操换毛玠、于禁为水军都督，则这两个手里，好歹送了水军性命。”鲁肃听了，开口不得，把些言语支吾了半晌，别孔明而回。孔明嘱曰：“望子敬在公瑾面前勿言亮先知此事。恐公瑾心怀妒忌，又要寻事害亮。”鲁肃应诺而去，回见周瑜，把上项事只得实说了。瑜大惊曰：“此人决不可留！吾决意斩之！”肃劝曰：“若杀孔明，却被曹操笑也。”瑜曰：“吾自有公道斩之，教他死而无怨。”肃曰：“何以公道斩之？”瑜曰：“子敬休问，来日便见。”次日，聚众将于帐下，教请孔明议事。孔明欣然而至。坐定，瑜问孔明曰：“即日将与曹军交战，水路交兵，当以何兵器为先？”孔明曰：“大江之上，以弓箭为先。”瑜曰：“先生之言，甚合愚意。但今军中正缺箭用，敢烦先生监造十万枝箭，以为应敌之具。此系公事，先生幸勿推却。”孔明曰：“都督见委，自当效劳。敢问十万枝箭，何时要用？”瑜曰：“十日之内，可完办否？”孔明曰：“操军即日将至，若候十日，必误大事。”瑜曰：“先生料几日可完办？”孔明曰：“只消三日，便可拜纳十万枝箭。”瑜曰：“军中无戏言。”孔明曰：“怎敢戏都督！愿纳军令状：三日不办，甘当重罚。”瑜大喜，唤军政司当面取了文书，置酒相待曰：“待军事毕后，自有酬劳。”孔明曰：“今日已不及，来日造起。至第三日，可差五百小军到江边搬箭。”饮了数杯，辞去。鲁肃曰：“此人莫非诈乎？”瑜曰：“他自送死，非我逼他。今明白对众要了文书，他便两胁生翅，也飞不去。我只分付军匠人等，教他故意迟延，凡应用物件，都不与齐备。如此，必然误了日期。那时定罪，有何理说？公今可去探他虚实，却来回报。
肃领命来见孔明。孔明曰：“吾曾告子敬，休对公瑾说，他必要害我。不想子敬不肯为我隐讳，今日果然又弄出事来。三日内如何造得十万箭？子敬只得救我！”肃曰：“公自取其祸，我如何救得你？”孔明曰：“望子敬借我二十只船，每船要军士三十人，船上皆用青布为幔，各束草千余个，分布两边。吾别有妙用。第三日包管有十万枝箭。只不可又教公瑾得知，若彼知之，吾计败矣。”肃允诺，却不解其意，回报周瑜，果然不提起借船之事，只言：“孔明并不用箭竹、翎毛、胶漆等物，自有道理。”瑜大疑曰：“且看他三日后如何回覆我！”却说鲁肃私自拨轻快船二十只，各船三十余人，并布幔束草等物，尽皆齐备，候孔明调用。第一日却不见孔明动静；第二日亦只不动。至第三日四更时分，孔明密请鲁肃到船中。肃问曰：“公召我来何意？”孔明曰：“特请子敬同往取箭。”肃曰：“何处去取？”孔明曰：“子敬休问，前去便见。”遂命将二十只船，用长索相连，径望北岸进发。是夜大雾漫天，长江之中，雾气更甚，对面不相见。孔明促舟前进，果然是好大雾！前人有篇《大雾垂江赋》曰：“大哉长江！西接岷、峨，南控三吴，北带九河。汇百川而入海，历万古以扬波。至若龙伯、海若，江妃、水母，长鲸千丈，天蜈九首，鬼怪异类，咸集而有。盖夫鬼神之所凭依，英雄之所战守也。时也阴阳既乱，昧爽不分。讶长空之一色，忽大雾之四屯。虽舆薪而莫睹，惟金鼓之可闻。初若溟蒙，才隐南山之豹；渐而充塞，欲迷北海之鲲。然后上接高天，下垂厚地；渺乎苍茫，浩乎无际。鲸鲵出水而腾波，蛟龙潜渊而吐气。又如梅霖收溽，春阴酿寒；溟溟漠漠，洁浩漫漫。东失柴桑之岸，南无夏口之山。战船千艘，俱沉沦于岩壑；渔舟一叶，惊出没于波澜。甚则穹吴无光，朝阳失色；返白昼为昏黄，变丹山为水碧。虽大禹之智，不能测其浅深；离娄之明，焉能辨乎咫尺？于是冯夷息浪，屏翳收功；鱼鳖遁迹，鸟兽潜踪。隔断蓬莱之岛，暗围阊阖之宫。恍惚奔腾，如骤雨之将至；纷纭杂沓，若寒云之欲同。乃能中隐毒蛇，因之而为瘴疠；内藏妖魅，凭之而为祸害。降疾厄于人间，起风尘于塞外。小民遇之夭伤，大人观之感慨。盖将返元气于洪荒，混天地为大块。”
当夜五更时候，船已近曹操水寨。孔明教把船只头西尾东，一带摆开，就船上擂鼓呐喊。鲁肃惊曰：“倘曹兵齐出，如之奈何？”孔明笑曰：“吾料曹操于重雾中必不敢出。吾等只顾酌酒取乐，待雾散便回。
却说曹寨中，听得擂鼓呐喊，毛玠、于禁二人慌忙飞报曹操。操传令曰：“重雾迷江，彼军忽至，必有埋伏，切不可轻动。可拨水军弓弩手乱箭射之。”又差人往旱寨内唤张辽、徐晃各带弓弩军三千，火速到江边助射。比及号令到来，毛玠、于禁怕南军抢入水寨，已差弓弩手在寨前放箭；少顷，旱寨内弓弩手亦到，约一万余人，尽皆向江中放箭：箭如雨发。孔明教把船吊回，头东尾西，逼近水寨受箭，一面擂鼓呐喊。待至日高雾散，孔明令收船急回。二十只船两边束草上，排满箭枝。孔明令各船上军士齐声叫曰：“谢丞相箭！”比及曹军寨内报知曹操时，这里船轻水急，已放回二十余里，追之不及。曹操懊悔不已。却说孔明回船谓鲁肃曰：“每船上箭约五六千矣。不费江东半分之力，已得十万余箭。明日即将来射曹军，却不甚便！”肃曰：“先生真神人也！何以知今日如此大雾？”孔明曰：“为将而不通天文，不识地利，不知奇门，不晓阴阳，不看阵图，不明兵势，是庸才也。亮于三日前已算定今日有大雾，因此敢任三日之限。公瑾教我十日完办，工匠料物，都不应手，将这一件风流罪过，明白要杀我。我命系于天，公瑾焉能害我哉！”鲁肃拜服。船到岸时，周瑜已差五百军在江边等候搬箭。孔明教于船上取之，可得十余万枝，都搬入中军帐交纳。鲁肃人见周瑜，备说孔明取箭之事。瑜大惊，慨然叹曰：“孔明神机妙算，吾不如也！”后人有诗赞曰：“一天浓雾满长江，远近难分水渺茫。骤雨飞蝗来战舰，孔明今日伏周郎。”少顷，孔明入寨见周瑜。瑜下帐迎之，称羡曰：“先生神算，使人敬服。”孔明曰：“诡谲小计，何足为奇。”
瑜邀孔明入帐共饮。瑜曰：“昨吾主遣使来催督进军，瑜未有奇计，愿先生教我。”孔明曰：“亮乃碌碌庸才，安有妙计？”瑜曰：“某昨观曹操水寨，极是严整有法，非等闲可攻。思得一计，不知可否。先生幸为我一决之。”孔明曰：“都督且休言。各自写于手内，看同也不同。”瑜大喜，教取笔砚来，先自暗写了，却送与孔明；孔明亦暗写了。两个移近坐榻，各出掌中之字，互相观看，皆大笑。原来周瑜掌中字，乃一“火”字；孔明掌中，亦一“火”字。瑜曰：“既我两人所见相同，更无疑矣。幸勿漏泄。”孔明曰：“两家公事，岂有漏泄之理。吾料曹操虽两番经我这条计，然必不为备。今都督尽行之可也。”饮罢分散，诸将皆不知其事。
却说曹操平白折了十五六万箭，心中气闷。荀攸进计曰：“江东有周瑜、诸葛亮二人用计，急切难破。可差人去东吴诈降，为奸细内应，以通消息，方可图也。”操曰：“此言正合吾意。汝料军中谁可行此计？”攸曰：“蔡瑁被诛，蔡氏宗族，皆在军中。瑁之族弟蔡中、蔡和现为副将。丞相可以恩结之，差往诈降东吴，必不见疑。”操从之，当夜密唤二人入帐嘱付曰：“汝二人可引些少军士，去东吴诈降。但有动静，使人密报，事成之后，重加封赏。休怀二心！”二人曰：“吾等妻子俱在荆州，安敢怀二心，丞相勿疑。某二人必取周瑜、诸葛亮之首，献于麾下。”操厚赏之。次日，二人带五百军士，驾船数只，顺风望着南岸来。
且说周瑜正理会进兵之事，忽报江北有船来到江口，称是蔡瑁之弟蔡和、蔡中，特来投降。瑜唤入。二人哭拜曰：“吾兄无罪，被操贼所杀。吾二人欲报兄仇，特来投降。望赐收录，愿为前部。”瑜大喜，重赏二人，即命与甘宁引军为前部。二人拜谢，以为中计。瑜密唤甘宁分付曰：“此二人不带家小，非真投降，乃曹操使来为奸细者。吾今欲将计就计，教他通报消息。汝可殷勤相待，就里提防。至出兵之日，先要杀他两个祭旗。汝切须小心，不可有误。”甘宁领命而去。
鲁肃入见周瑜曰：“蔡中、蔡和之降，多应是诈，不可收用。”瑜叱曰：“彼因曹操杀其兄，欲报仇而来降，何诈之有！你若如此多疑，安能容天下之士乎！”肃默然而退，乃往告孔明。孔明笑而不言。肃曰：“孔明何故哂笑？”孔明曰：“吾笑子敬不识公瑾用计耳。大江隔远，细作极难往来。操使蔡中、蔡和诈降，刺探我军中事，公瑾将计就计，正要他通报消息。兵不厌诈，公瑾之谋是也。”肃方才省悟。
却说周瑜夜坐帐中，忽见黄盖潜入中军来见周瑜。瑜问曰：“公覆夜至，必有良谋见教？”盖曰：“彼众我寡，不宜久持，何不用火攻之？”瑜曰：“谁教公献此计？”盖曰：“某出自己意，非他人之所教也。”瑜曰：“吾正欲如此，故留蔡中、蔡和诈降之人，以通消息；但恨无一人为我行诈降计耳。”盖曰：“某愿行此计。”瑜曰：“不受些苦，彼如何肯信？”盖曰：“某受孙氏厚恩，虽肝脑涂地，亦无怨悔。”瑜拜而谢之曰：“君若肯行此苦肉计，则江东之万幸也。”盖曰：“某死亦无怨。”遂谢而出。次日，周瑜鸣鼓大会诸将于帐下。孔明亦在座。周瑜曰：“操引百万之众，连络三百余里，非一日可破。今令诸将各领三个月粮草，准备御敌。”言未讫，黄盖进曰：“莫说三个月，便支三十个月粮草，也不济事！若是这个月破的，便破；若是这个月破不的，只可依张子布之言，弃甲倒戈，北面而降之耳！”周瑜勃然变色，大怒曰：“吾奉主公之命，督兵破曹，敢有再言降者必斩。今两军相敌之际，汝敢出此言，慢我军心，不斩汝首，难以服众！”喝左右将黄盖斩讫报来。黄盖亦怒曰：“吾自随破虏将军，纵横东南，已历三世，那有你来？”瑜大怒，喝令速斩。甘宁进前告曰：“公覆乃东吴旧臣，望宽恕之。”瑜喝曰：“汝何敢多言，乱吾法度！”先叱左右将甘宁乱棒打出。众官皆跪告曰：“黄盖罪固当诛，但于军不利。望都督宽恕，权且记罪。破曹之后，斩亦未迟。”瑜怒未息。众官苦苦告求。瑜曰：“若不看众官面皮，决须斩首！今且免死！”命左右：“拖翻打一百脊杖，以正其罪！”众官又告免。瑜推翻案桌，叱退众官，喝教行杖。将黄盖剥了衣服，拖翻在地，打了五十脊杖。众官又复苦苦求免。瑜跃起指盖曰：“汝敢小觑我耶！且寄下五十棍！再有怠慢，二罪俱罚！”恨声不绝而入帐中。众官扶起黄盖，打得皮开肉绽，鲜血进流，扶归本寨，昏绝几次。动问之人，无不下泪。鲁肃也往看问了，来至孔明船中，谓孔明曰：“今日公瑾怒责公覆，我等皆是他部下，不敢犯颜苦谏；先生是客，何故袖手旁观，不发一语？”孔明笑曰：“子敬欺我。”肃曰：“肃与先生渡江以来，未尝一事相欺。今何出此言？”孔明曰：“子敬岂不知公瑾今日毒打黄公覆，乃其计耶？如何要我劝他？”肃方悟。孔明曰：“不用苦肉计，何能瞒过曹操？今必令黄公覆去诈降，却教蔡中、蔡和报知其事矣。子敬见公瑾时，切勿言亮先知其事，只说亮也埋怨都督便了。”肃辞去，入帐见周瑜。瑜邀入帐后。肃曰：“今日何故痛责黄公覆？”瑜曰：“诸将怨否？”肃曰：“多有心中不安者。”瑜曰：“孔明之意若何？”肃曰：“他也埋怨都督忒情薄。”瑜笑曰：“今番须瞒过他也。”肃曰：“何谓也？”瑜曰：“今日痛打黄盖，乃计也。吾欲令他诈降，先须用苦肉计瞒过曹操，就中用火攻之，可以取胜。”肃乃暗思孔明之高见，却不敢明言。
且说黄盖卧于帐中，诸将皆来动问。盖不言语，但长吁而已。忽报参谋阚泽来问。盖令请入卧内，叱退左右。阚泽曰：“将军莫非与都督有仇？”盖曰：“非也。”泽曰：“然则公之受责，莫非苦肉计乎？”盖曰：“何以知之？”泽曰：“某观公瑾举动，已料着八九分。”盖曰：“某受吴侯三世厚恩，无以为报，故献此计，以破曹操。吾虽受苦，亦无所恨。吾遍观军中，无一人可为心腹者。惟公素有忠义之心，敢以心腹相告。”泽曰：“公之告我，无非要我献诈降书耳。”盖曰：“实有此意。未知肯否？”阚泽欣然领诺。正是：勇将轻身思报主，谋臣为国有同心。
未知阚泽所言若何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536852333, '5b9a10fb9f54540039aa39b2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639182, '三国演义 · 第四十七回 · 阚泽密献诈降书 庞统巧授连环计', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说阚泽字德润，会稽山阴人也；家贫好学，与人佣工，尝借人书来看，看过一遍，更不遗忘；口才辨给，少有胆气。孙权召为参谋，与黄盖最相善。盖知其能言有胆，故欲使献诈降书。泽欣然应诺曰：“大丈夫处世，不能立功建业，不几与草木同腐乎！公既捐躯报主，泽又何惜微生！”黄盖滚下床来，拜而谢之。泽曰：“事不可缓，即可便行。”盖曰：“书已修下了。”泽领了书，只就当夜扮作渔翁，驾小舟，望北岸而行。
是夜寒星满天。三更时候，早到曹军水寨。巡江军士拿住，连夜报知曹操。操曰：“莫非是奸细么？”军士曰：“只一渔翁，自称是东吴参谋阚泽，有机密事来见。”操便教引将入来。军士引阚泽至，只见帐上灯烛辉煌，曹操凭几危坐，问曰：“汝既是东吴参谋，来此何干？”泽曰：“人言曹丞相求贤若渴，今观此问，甚不相合。黄公覆，汝又错寻思了也！”操曰：“吾与东吴旦夕交兵，汝私行到此，如何不问？”泽曰：“黄公覆乃东吴三世旧臣，今被周瑜于众将之前，无端毒打，不胜忿恨。因欲投降丞相，为报仇之计，特谋之于我。我与公覆，情同骨肉，径来为献密书。未知丞相肯容纳否？”操曰：“书在何处？”阚泽取书呈上。
操拆书，就灯下观看。书略曰：“盖受孙氏厚恩，本不当怀二心。然以今日事势论之：用江东六郡之卒，当中国百万之师，众寡不敌，海内所共见也。东吴将吏，无有智愚，皆知其不可。周瑜小子，偏怀浅戆，自负其能，辄欲以卵敌石；兼之擅作威福，无罪受刑，有功不赏。盖系旧臣，无端为所摧辱，心实恨之！伏闻丞相诚心待物，虚怀纳士，盖愿率众归降，以图建功雪耻。粮草军仗，随船献纳。泣血拜白，万勿见疑。”曹操于几案上翻覆将书看了十余次，忽然拍案张目大怒曰：“黄盖用苦肉计，令汝下诈降书，就中取事，却敢来戏侮我耶！”便教左右推出斩之。左右将阚泽簇下。泽面不改容，仰天大笑。操教牵回，叱曰：“吾已识破奸计，汝何故哂笑？”泽曰：“吾不笑你。吾笑黄公覆不识人耳。”操曰：“何不识人？”泽曰：“杀便杀，何必多问！”操曰：“吾自幼熟读兵书，深知奸伪之道。汝这条计，只好瞒别人，如何瞒得我！”泽曰：“你且说书中那件事是奸计？”操曰：“我说出你那破绽，教你死而无怨：你既是真心献书投降，如何不明约几时？你今有何理说？”阚泽听罢，大笑曰：“亏汝不惶恐，敢自夸熟读兵书！还不及早收兵回去！倘若交战，必被周瑜擒矣！无学之辈！可惜吾屈死汝手！”操曰：“何谓我无学？”泽曰：“汝不识机谋，不明道理，岂非无学？”操曰：“你且说我那几般不是处？”泽曰：“汝无待贤之礼，吾何必言！但有死而已。”操曰：“汝若说得有理，我自然敬服。”泽曰：“岂不闻‘背主作窃’，不可定期？倘今约定日期，急切下不得手，这里反来接应，事必泄漏。但可觑便而行，岂可预期相订乎？汝不明此理，欲屈杀好人，真无学之辈也！”操闻言，改容下席而谢曰：“某见事不明，误犯尊威，幸勿挂怀。”泽曰：“吾与黄公覆，倾心投降，如婴儿之望父母，岂有诈乎！”操大喜曰：“若二人能建大功，他日受爵，必在诸人之上。”泽曰：“某等非为爵禄而来，实应天顺人耳。”操取酒待之。
少顷，有人入帐，于操耳边私语。操曰：“将书来看。”其人以密书呈上。操观之，颜色颇喜。阚泽暗思：“此必蔡中、蔡和来报黄盖受刑消息，操故喜我投降之事为真实也。”操曰：“烦先生再回江东，与黄公覆约定，先通消息过江，吾以兵接应。”泽曰：“某已离江东，不可复还。望丞相别遣机密人去。”操曰：“若他人去，事恐泄漏。”泽再三推辞；良久，乃曰：“若去则不敢久停，便当行矣。”操赐以金帛，泽不受。辞别出营，再驾扁舟，重回江东，来见黄盖，细说前事。盖曰：“非公能辩，则盖徒受苦矣。”泽曰；“吾今去甘宁寨中，探蔡中、蔡和消息。”盖曰：“甚善。”泽至宁寨，宁接入，泽曰：“将军昨为救黄公覆，被周公瑾所辱，吾甚不平。”宁笑而不答。正话间，蔡和、蔡中至。泽以目送甘宁，宁会意，乃曰：“周公瑾只自恃其能，全不以我等为念。我今被辱，羞见江左诸人！”说罢，咬牙切齿，拍案大叫。泽乃虚与宁耳边低语。宁低头不言，长叹数声。蔡和、蔡中见宁、泽皆有反意，以言挑之曰：“将军何故烦恼？先生有何不平？”泽曰：“吾等腹中之苦，汝岂知耶！”蔡和曰：“莫非欲背吴投曹耶？”阚泽失色，甘宁拔剑而起曰：“吾事已为窥破，不可不杀之以灭口！”蔡和、蔡中慌曰：“二公勿忧。吾亦当以心腹之事相告。”宁曰：“可速言之！”蔡和曰：“吾二人乃曹公使来诈降者。二公若有归顺之心，吾当引进。”宁曰：“汝言果真？”二人齐声曰；“安敢相欺！”宁佯喜曰；“若如此，是天赐其便也！”二蔡曰：“黄公覆与将军被辱之事，吾已报知丞相矣。”泽曰：“吾已为黄公覆献书丞相，今特来见兴霸，相约同降耳。”宁曰：“大丈夫既遇明主，自当倾心相投。”于是四人共饮，同论心事。二蔡即时写书，密报曹操，说“甘宁与某同为内应。”阚泽另自修书，遣人密报曹操，书中具言：黄盖欲来，未得其便；但看船头插青牙旗而来者，即是也。
却说曹操连得二书，心中疑惑不定，聚众谋士商议曰：“江左甘宁，被周瑜所辱，愿为内应；黄盖受责，令阚泽来纳降：俱未可深信。谁敢直入周瑜寨中，探听实信？”蒋干进曰：“某前日空往东吴，未得成功，深怀惭愧。今愿舍身再往，务得实信，回报丞相。”操大喜，即时令蒋干上船。干驾小舟，径到江南水寨边，便使人传报。周瑜听得干又到，大喜曰：“吾之成功，只在此人身上！”遂嘱付鲁肃：“请庞士元来，为我如此如此。”原来襄阳庞统，字士元，因避乱寓居江东，鲁肃曾荐之于周瑜。统未及往见，瑜先使肃问计于统曰：“破曹当用何策？”统密谓肃曰：“欲破曹兵，须用火攻；但大江面上，一船着火，余船四散；除非献‘连环计’，教他钉作一处，然后功可成也。”肃以告瑜，瑜深服其论，因谓肃曰：“为我行此计者，非庞士元不可。”肃曰：“只怕曹操奸猾，如何去得？”周瑜沉吟未决。正寻思没个机会，忽报蒋干又来。瑜大喜，一面分付庞统用计；一面坐于帐上，使人请干。
干见不来接，心中疑虑，教把船于僻静岸口缆系，乃入寨见周瑜。瑜作色曰：“子翼何故欺吾太甚？”蒋干笑曰：“吾想与你乃旧日弟兄，特来吐心腹事，何言相欺也？”瑜曰：“汝要说我降，除非海枯石烂！前番吾念旧日交情，请你痛饮一醉，留你共榻；你却盗吾私书，不辞而去，归报曹操，杀了蔡瑁、张允，致使吾事不成。今日无故又来，必不怀好意！吾不看旧日之情，一刀两段！本待送你过去，争奈吾一二日间，便要破曹贼；待留你在军中，又必有泄漏。”便教左右：“送子翼往西山庵中歇息。待吾破了曹操，那时渡你过江未迟。”蒋干再欲开言，周瑜已入帐后去了。
左右取马与蒋干乘坐，送到西山背后小庵歇息，拨两个军人伏侍。干在庵内，心中忧闷，寝食不安。是夜星露满天，独步出庵后，只听得读书之声。信步寻去，见山岩畔有草屋数椽，内射灯光。干往窥之，只见一人挂剑灯前，诵孙、吴兵书。干思：“此必异人也。”叩户请见。其人开门出迎，仪表非俗。干问姓名，答曰：“姓庞，名统，字士元。”干曰：“莫非凤雏先生否？”统曰：“然也。”干喜曰：“久闻大名，今何僻居此地？”答曰：“周瑜自恃才高，不能容物，吾故隐居于此。公乃何人？”干曰：“吾蒋干也。”统乃邀入草庵，共坐谈心。干曰：“以公之才，何往不利？如肯归曹，干当引进。”统曰：“吾亦欲离江东久矣。公既有引进之心，即今便当一行。如迟则周瑜闻之，必将见害。”于是与干连夜下山，至江边寻着原来船只，飞棹投江北。
既至操寨，干先入见，备述前事。操闻凤雏先生来，亲自出帐迎入，分宾主坐定，问曰：“周瑜年幼，恃才欺众，不用良谋。操久闻先生大名，今得惠顾，乞不吝教诲。”统曰：“某素闻丞相用兵有法，今愿一睹军容。”操教备马，先邀统同观旱寨。统与操并马登高而望。统曰：“傍山依林，前后顾盼，出入有门，进退曲折，虽孙、吴再生，穰苴复出，亦不过此矣。”操曰：“先生勿得过誉，尚望指教。”于是又与同观水寨。见向南分二十四座门，皆有艨艟战舰，列为城郭，中藏小船，往来有巷，起伏有序，统笑曰：“丞相用兵如此，名不虚传！”因指江南而言曰：“周郎，周郎！克期必亡！”操大喜。回寨，请入帐中，置酒共饮，同说兵机。统高谈雄辩，应答如流。操深敬服，殷勤相待。统佯醉曰：“敢问军中有良医否？”操问何用。统曰：“水军多疾，须用良医治之。”时操军因不服水土，俱生呕吐之疾，多有死者，操正虑此事；忽闻统言，如何不问？统曰：“丞相教练水军之法甚妙，但可惜不全。”操再三请问。统曰：“某有一策，使大小水军，并无疾病，安稳成功。”操大喜，请问妙策。统曰：“大江之中，潮生潮落，风浪不息；北兵不惯乘舟，受此颠播，便生疾病。若以大船小船各皆配搭，或三十为一排，或五十为一排，首尾用铁环连锁，上铺阔板，休言人可渡，马亦可走矣，乘此而行，任他风浪潮水上下，复何惧哉？”曹操下席而谢曰：“非先生良谋，安能破东吴耶！”统曰：“愚浅之见，丞相自裁之。”操即时传令，唤军中铁匠，连夜打造连环大钉，锁住船只。诸军闻之，俱各喜悦。后人有诗曰：“赤壁鏖兵用火攻，运筹决策尽皆同。若非庞统连环计，公瑾安能立大功？”
庞统又谓操曰：“某观江左豪杰，多有怨周瑜者；某凭三寸舌，为丞相说之，使皆来降。周瑜孤立无援，必为丞相所擒。瑜既破，则刘备无所用矣。”操曰：“先生果能成大功，操请奏闻天子，封为三公之列。”统曰：“某非为富贵，但欲救万民耳。丞相渡江，慎勿杀害。”操曰：“吾替天行道，安忍杀戮人民！”统拜求榜文，以安宗族。操曰：“先生家属，现居何处？”统曰：“只在江边。若得此榜，可保全矣。”操命写榜佥押付统。统拜谢曰：“别后可速进兵，休待周郎知觉。”操然之。统拜别，至江边，正欲下船，忽见岸上一人，道袍竹冠，一把扯住统曰：“你好大胆！黄盖用苦肉计，阚泽下诈降书，你又来献连环计：只恐烧不尽绝！你们把出这等毒手来，只好瞒曹操，也须瞒我不得！”諕得庞统魂飞魄散。正是：莫道东南能制胜，谁云西北独无人？
毕竟此人是谁，且看下文分解。', '', '', '', NULL, '', 'indent', 1536852357, '5b9a1116808ca43cd2145a08', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639183, '三国演义 · 第四十八回 · 宴长江曹操赋诗 锁战船北军用武', NULL, 3, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说庞统闻言，吃了一惊，急回视其人，原来却是徐庶。统见是故人，心下方定。回顾左右无人，乃曰：“你若说破我计，可惜江南八十一州百姓，皆是你送了也！”庶笑曰：“此间八十三万人马，性命如何？”统曰：“元直真欲破我计耶？”庶曰：“吾感刘皇叔厚恩，未尝忘报。曹操送死吾母，吾已说过终身不设一谋，今安肯破兄良策？只是我亦随军在此，兵败之后，玉石不分，岂能免难？君当教我脱身之术，我即缄口远避矣。”统笑曰：“元直如此高见远识，谅此有何难哉！”庶曰：“愿先生赐教。”统去徐庶耳边略说数句。庶大喜，拜谢。庞统别却徐庶，下船自回江东。
且说徐庶当晚密使近人去各寨中暗布谣言。次日，寨中三三五五，交头接耳而说。早有探事人报知曹操，说：“军中传言西凉州韩遂、马腾谋反，杀奔许都来。”操大惊，急聚众谋士商议曰：“吾引兵南征，心中所忧者，韩遂、马腾耳。军中谣言，虽未辨虚实，然不可不防。”言未毕，徐庶进曰：“庶蒙丞相收录，恨无寸功报效。请得三千人马，星夜往散关把住隘口；如有紧急，再行告报。”操喜曰：“若得元直去，吾无忧矣！散关之上，亦有军兵，公统领之。目下拨三千马步军，命臧霸为先锋，星夜前去，不可稽迟。”徐庶辞了曹操，与臧霸便行。此便是庞统救徐庶之计。后人有诗曰：“曹操征南日日忧，马腾韩遂起戈矛。凤雏一语教徐庶，正似游鱼脱钓钩。”曹操自遣徐庶去后，心中稍安，遂上马先看沿江旱寨，次看水寨。乘大船一只于中央，上建“帅”字旗号，两傍皆列水寨，船上埋伏弓弩千张。操居于上。时建安十三年冬十一月十五日，天气晴明，平风静浪。操令：“置酒设乐于大船之上，吾今夕欲会诸将。”天色向晚，东山月上，皎皎如同白日。长江一带，如横素练。操坐大船之上，左右侍御者数百人，皆锦衣绣袄，荷戈执戟。文武众官，各依次而坐。操见南屏山色如画，东视柴桑之境，西观夏口之江，南望樊山，北觑乌林，四顾空阔，心中欢喜，谓众官曰：“吾自起义兵以来，与国家除凶去害，誓愿扫清四海，削平天下；所未得者江南也。今吾有百万雄师，更赖诸公用命，何患不成功耶！收服江南之后，天下无事，与诸公共享富贵，以乐太平。”文武皆起谢曰：“愿得早奏凯歌！我等终身皆赖丞相福荫。”操大喜，命左右行酒。饮至半夜，操酒酣，遥指南岸曰：“周瑜、鲁肃，不识天时！今幸有投降之人，为彼心腹之患，此天助吾也。”荀攸曰：“丞相勿言，恐有泄漏。”操大笑曰：“座上诸公，与近侍左右，皆吾心腹之人也，言之何碍！”又指夏口曰：“刘备、诸葛亮，汝不料蝼蚁之力，欲撼泰山，何其愚耶！”顾谓诸将曰：“吾今年五十四岁矣，如得江南，窃有所喜。昔日乔公与吾至契，吾知其二女皆有国色。后不料为孙策、周瑜所娶。吾今新构铜雀台于漳水之上，如得江南，当娶二乔，置之台上，以娱暮年，吾愿足矣！”言罢大笑。唐人杜牧之有诗曰：“折戟沉沙铁未消，自将磨洗认前朝。东风不与周郎便，铜雀春深锁二乔。”曹操正笑谈间，忽闻鸦声望南飞鸣而去。操问曰；“此鸦缘何夜鸣？”左右答曰：“鸦见月明，疑是天晓，故离树而鸣也。”操又大笑。时操已醉，乃取槊立于船头上，以酒奠于江中，满饮三爵，横槊谓诸将曰：“我持此槊，破黄巾、擒吕布、灭袁术、收袁绍，深入塞北，直抵辽东，纵横天下：颇不负大丈夫之志也。今对此景，甚有慷慨。吾当作歌，汝等和之。”歌曰：“对酒当歌，人生几何：譬如朝露，去日苦多。慨当以慷，忧思难忘；何以解忧，惟有杜康。青青子衿，悠悠我心；但为君故，沉吟至今。呦呦鹿鸣，食野之苹；我有嘉宾，鼓瑟吹笙。皎皎如月，何时可辍？忧从中来，不可断绝！越陌度阡，枉用相存；契阔谈宴，心念旧恩。月明星稀，乌鹊南飞；绕树三匝，无枝可依。山不厌高，水不厌深：周公吐哺，天下归心。”歌罢，众和之，共皆欢笑。忽座间一人进曰：“大军相当之际，将士用命之时，丞相何故出此不吉之言？”操视之，乃扬州刺史，沛国相人，姓刘，名馥，字元颖。馥起自合淝，创立州治，聚逃散之民，立学校，广屯田，兴治教，久事曹操，多立功绩。当下操横槊问曰：“吾言有何不吉？”馥曰：“月明星稀，乌鹊南飞；绕树三匝，无枝可依。此不吉之言也。”操大怒曰：“汝安敢败吾兴！”手起一槊，刺死刘馥。众皆惊骇。遂罢宴。次日，操酒醒，懊恨不已。馥子刘熙，告请父尸归葬。操泣曰：“吾昨因醉误伤汝父，悔之无及。可以三公厚礼葬之。”又拨军士护送灵柩，即日回葬。
次日，水军都督毛玠、于禁诣帐下，请曰：“大小船只，俱已配搭连锁停当。旌旗战具，一一齐备。请丞相调遣，克日进兵。”操至水军中央大战船上坐定，唤集诸将，各各听令。水旱二军，俱分五色旗号：水军中央黄旗毛玠、于禁，前军红旗张郃，后军皂旗吕虔，左军青旗文聘，右军白旗吕通；马步前军红旗徐晃，后军皂旗李典，左军青旗乐进，右军白旗夏侯渊。水陆路都接应使：夏侯惇、曹洪；护卫往来监战使：许褚、张辽。其余骁将，各依队伍。令毕，水军寨中发擂三通，各队伍战船，分门而出。是日西北风骤起，各船拽起风帆，冲波激浪，稳如平地。北军在船上，踊跃施勇，刺枪使刀。前后左右各军，旗幡不杂。又有小船五十余只，往来巡警催督。操立于将台之上，观看调练，心中大喜，以为必胜之法；教且收住帆幔，各依次序回寨。
操升帐谓众谋士曰：“若非天命助吾，安得凤雏妙计？铁索连舟，果然渡江如履平地。”程昱曰：“船皆连锁，固是平稳；但彼若用火攻，难以回避。不可不防。”操大笑曰：“程仲德虽有远虑，却还有见不到处。”荀攸曰：“仲德之言甚是。丞相何故笑之？”操曰：“凡用火攻，必藉风力。方今隆冬之际，但有西风北风，安有东风南风耶？吾居于西北之上，彼兵皆在南岸，彼若用火，是烧自己之兵也，吾何惧哉？若是十月小春之时，吾早已提备矣。”诸将皆拜伏曰：“丞相高见，众人不及。”操顾诸将曰：“青、徐、燕、代之众，不惯乘舟。今非此计，安能涉大江之险！”只见班部中二将挺身出曰：“小将虽幽、燕之人，也能乘舟。今愿借巡船二十只，直至江口，夺旗鼓而还，以显北军亦能乘舟也。”操视之，乃袁绍手下旧将焦触、张南也。操曰：“汝等皆生长北方，恐乘舟不便。江南之兵，往来水上，习练精熟，汝勿轻以性命为儿戏也。”焦触、张南大叫曰：“如其不胜，甘受军法！”操曰：“战船尽已连锁，惟有小舟。每舟可容二十人，只恐未便接战。”触曰：“若用大船，何足为奇？乞付小舟二十余只，某与张南各引一半，只今日直抵江南水寨，须要夺旗斩将而还。”操曰：“吾与汝二十只船，差拨精锐军五百人，皆长枪硬弩。到来日天明，将大寨船出到江面上，远为之势。更差文聘亦领三十只巡船接应汝回。”焦触、张南欣喜而退。
次日，四更造饭，五更结束已定，早听得水寨中擂鼓鸣金。船皆出寨，分布水面，长江一带，青红旗号交杂。焦触、张南领哨船二十只，穿寨而出，望江南进发。却说南岸隔夜听得鼓声喧震，遥望曹操调练水军，探事人报知周瑜。瑜往山顶观之，操军已收回。次日，忽又闻鼓声震天，军士急登高观望，见有小船冲波而来，飞报中军。周瑜问帐下：“谁敢先出？”韩当、周泰二人齐出曰：“某当权为先锋破敌。”瑜喜，传令各寨严加守御，不可轻动。韩当、周泰各引哨船五只，分左右而出。却说焦触、张南凭一勇之气，飞棹小船而来。韩当独披掩心，手执长枪，立于船头。焦触船先到，便命军士乱箭望韩当船上射来。当用牌遮隔。焦触捻长枪与韩当交锋。当手起一枪，刺死焦触。张南随后大叫赶来。隔斜里周泰船出。张南挺枪立于船头，两边弓矢乱射。周泰一臂挽牌，一手提刀，两船相离七八尺，泰即飞身一跃，直跃过张南船上，手起刀落，砍张南于水中，乱杀驾舟军士。众船飞棹急回。韩当、周泰催船追赶，到半江中，恰与文聘船相迎。两边便摆定船厮杀。却说周瑜引众将立于山顶，遥望江北水面艨艟战船，排合江上，旗帜号带，皆有次序。回看文聘与韩当、周泰相持，韩当、周泰奋力攻击，文聘抵敌不住，回船而走，韩、周二人，急催船追赶。周瑜恐二人深入重地，便将白旗招飐，令众鸣金。二人乃挥棹而回。周瑜于山顶看隔江战船，尽入水寨。瑜顾谓众将曰：“江北战船如芦苇之密，操又多谋，当用何计以破之？”众未及对，忽见曹军寨中，被风吹折中央黄旗，飘入江中。瑜大笑曰：“此不祥之兆也！”正观之际，忽狂风大作，江中波涛拍岸。一阵风过，刮起旗角于周瑜脸上拂过。瑜猛然想起一事在心，大叫一声，往后便倒，口吐鲜血。诸将急救起时，却早不省人事。正是：一时忽笑又忽叫，难使南军破北军。
毕竟周瑜性命如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536852588, '5b9a112e9f54540039aa3bb8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639184, '三国演义 · 第四十九回 · 七星坛诸葛祭风 三江口周瑜纵火', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说周瑜立于山顶，观望良久，忽然望后而倒，口吐鲜血，不省人事。左右救回帐中。诸将皆来动问，尽皆愕然相顾曰：“江北百万之众，虎踞鲸吞。不争都督如此，倘曹兵一至，如之奈何？”慌忙差人申报吴侯，一面求医调治。
却说鲁肃见周瑜卧病，心中忧闷，来见孔明，言周瑜卒病之事。孔明曰：“公以为何如？”肃曰：“此乃曹操之福，江东之祸也。”孔明笑曰：“公瑾之病，亮亦能医。”肃曰：“诚如此，则国家万幸！”即请孔明同去看病。肃先入见周瑜。瑜以被蒙头而卧。肃曰：“都督病势若何？”周瑜曰：“心腹搅痛，时复昏迷。”肃曰：“曾服何药饵？”瑜曰：“心中呕逆，药不能下。”肃曰：“适来去望孔明，言能医都督之病。现在帐外，烦来医治，何如？”瑜命请入，教左右扶起，坐于床上。孔明曰：“连日不晤君颜，何期贵体不安！”瑜曰：“人有旦夕祸福，岂能自保？”孔明笑曰：“天有不测风云，人又岂能料乎？”瑜闻失色，乃作呻吟之声。孔明曰：“都督心中似觉烦积否？”瑜曰：“然，”孔明曰：“必须用凉药以解之。”瑜曰：“已服凉药，全然无效。”孔明曰：“须先理其气；气若顺，则呼吸之间，自然痊可。”瑜料孔明必知其意，乃以言挑之曰：“欲得顺气，当服何药？”孔明笑曰：“亮有一方，便教都督气顺。”瑜曰：“愿先生赐教。”孔明索纸笔，屏退左右，密书十六字曰：“欲破曹公，宜用火攻；万事俱备，只欠东风。”写毕，递与周瑜曰：“此都督病源也。”瑜见了大惊，暗思：“孔明真神人也！早已知我心事！只索以实情告之。”乃笑曰：“先生已知我病源，将用何药治之？事在危急，望即赐教。”孔明曰：“亮虽不才，曾遇异人，传授奇门遁甲天书，可以呼风唤雨。都督若要东南风时，可于南屏山建一台，名曰七星坛：高九尺，作三层，用一百二十人，手执旗幡围绕。亮于台上作法，借三日三夜东南大风，助都督用兵，何如？”瑜曰：“休道三日三夜，只一夜大风，大事可成矣。只是事在目前，不可迟缓。”孔明曰：“十一月二十日甲子祭风，至二十二日丙寅风息，如何？”瑜闻言大喜，矍然而起。便传令差五百精壮军士，往南屏山筑坛；拨一百二十人，执旗守坛，听候使令。
孔明辞别出帐，与鲁肃上马，来南屏山相度地势，令军士取东南方赤土筑坛。方圆二十四丈，每一层高三尺，共是九尺。下一层插二十八宿旗：东方七面青旗，按角、亢、氏、房、心、尾、箕，布苍龙之形；北方七面皂旗，按斗、牛、女、虚、危、室、壁，作玄武之势；西方七面白旗，按奎、娄、胃、昴、毕、觜、参，踞白虎之威；南方七面红旗，按井、鬼、柳、星、张、翼、轸，成朱雀之状。第二层周围黄旗六十四面，按六十四卦，分八位而立。上一层用四人，各人戴束发冠，穿皂罗袍，凤衣博带，朱履方裾。前左立一人，手执长竿，竿尖上用鸡羽为葆。以招风信；前右立一人，手执长竿，竿上系七星号带，以表风色；后左立一人，捧宝剑；后右立一人，捧香炉。坛下二十四人，各持旌旗、宝盖、大戟、长戈、黄钺、白旄、朱幡、皂纛，环绕四面。
孔明于十一月二十日甲子吉辰，沐浴斋戒，身披道衣，跣足散发，来到坛前。分付鲁肃曰：“子敬自往军中相助公瑾调兵。倘亮所祈无应，不可有怪。”鲁肃别去。孔明嘱付守坛将士：“不许擅离方位。不许交头接耳。不许失口乱言。不许失惊打怪。如违令者斩！”众皆领命。孔明缓步登坛，观瞻方位已定，焚香于炉，注水于盂，仰天暗祝。下坛入帐中少歇，令军士更替吃饭。孔明一日上坛三次，下坛三次。却并不见有东南风。且说周瑜请程普、鲁肃一班军官，在帐中伺候，只等东南风起，便调兵出；一面关报孙权接应。黄盖已自准备火船二十只，船头密布大钉；船内装载芦苇干柴，灌以鱼油，上铺硫黄、焰硝引火之物，各用青布油单遮盖；船头上插青龙牙旗，船尾各系走舸：在帐下听候，只等周瑜号令。甘宁、阚泽窝盘蔡和、蔡中在水寨中，每日饮酒，不放一卒登岸；周围尽是东吴军马，把得水泄不通：只等帐上号令下来。周瑜正在帐中坐议，探子来报：“吴侯船只离寨八十五里停泊，只等都督好音。”瑜即差鲁肃遍告各部下官兵将士：“俱各收拾船只、军器、帆橹等物。号令一出，时刻休违。倘有违误，即按军法。”众兵将得令，一个个磨拳擦掌，准备厮杀。
是日，看看近夜，天色清明，微风不动。瑜谓鲁肃曰：“孔明之言谬矣。隆冬之时，怎得东南风乎？”肃曰：“吾料孔明必不谬谈。”将近三更时分，忽听风声响，旗幡转动。瑜出帐看时，旗脚竟飘西北。霎时间东南风大起，瑜骇然曰：“此人有夺天地造化之法、鬼神不测之术！若留此人，乃东吴祸根也。及早杀却，免生他日之忧。”急唤帐前护军校尉丁奉、徐盛二将：“各带一百人。徐盛从江内去，丁奉从旱路去，都到南屏山七星坛前，休问长短，拿住诸葛亮便行斩首，将首级来请功。”二将领命。徐盛下船，一百刀斧手荡开棹桨；丁奉上马，一百弓弩手各跨征驹：往南屏山来。于路正迎着东南风起。后人有诗曰：“七星坛上卧龙登，一夜东风江水腾。不是孔明施妙计，周郎安得逞才能？”
丁奉马军先到，见坛上执旗将士，当风而立。丁奉下马提剑上坛，不见孔明，慌问守坛将士。答曰：“恰才下坛去了。”丁奉忙下坛寻时，徐盛船已到。二人聚于江边。小卒报曰：“昨晚一只快船停在前面滩口。适间却见孔明披发下船，那船望上水去了。”丁奉、徐盛便分水陆两路追袭。徐盛教拽起满帆，抢风而使。遥望前船不远，徐盛在船头上高声大叫：“军师休去！都督有请！”只见孔明立于船尾大笑曰：“上覆都督：好好用兵；诸葛亮暂回夏口，异日再容相见。”徐盛曰：“请暂少住，有紧话说。”孔明曰：“吾已料定都督不能容我，必来加害，预先教赵子龙来相接。将军不必追赶。”徐盛见前船无篷，只顾赶来。看看至近，赵云拈弓搭箭，立于船尾大叫曰：“吾乃常山赵子龙也！奉令特来接军师。你如何来追赶？本待一箭射死你来，显得两家失了和气。——教你知我手段！”言讫，箭到处，射断徐盛船上篷索。那篷堕落下水，其船便横。赵云却教自己船上拽起满帆，乘顺风而去。其船如飞，追之不及。岸上丁奉唤徐盛船近岸，言曰：“诸葛亮神机妙算，人不可及。更兼赵云有万夫不当之勇，汝知他当阳长坂时否？吾等只索回报便了。”于是二人回见周瑜，言孔明预先约赵云迎接去了。周瑜大惊曰：“此人如此多谋，使我晓夜不安矣！”鲁肃曰：“且待破曹之后，却再图之。”
瑜从其言，唤集诸将听令。先教甘宁：“带了蔡中并降卒沿南岸而走，只打北军旗号，直取乌林地面，正当曹操屯粮之所，深入军中，举火为号。只留下蔡和一人在帐下，我有用处。”第二唤太史慈分付：“你可领三千兵，直奔黄州地界，断曹操合淝接应之兵，就逼曹兵，放火为号；只看红旗，便是吴侯接应兵到。”这两队兵最远，先发。第三唤吕蒙领三千兵去乌林接应甘宁，焚烧曹操寨栅，第四唤凌统领三千兵，直截彝陵界首，只看乌林火起，以兵应之。第五唤董袭领三千兵，直取汉阳，从汉川杀奔曹操案中。看白旗接应。第六唤潘璋领三千兵，尽打白旗，往汉阳接应董袭。六队船只各自分路去了。却令黄盖安排火船，使小卒驰书约曹操，今夜来降。一面拨战船四只，随于黄盖船后接应。第一队领兵军官韩当，第二队领兵军官周泰，第三队领兵军官蒋钦，第四队领兵军官陈武：四队各引战船三百只，前面各摆列火船二十只。周瑜自与程普在大艨艟上督战，徐盛、丁奉为左右护卫，只留鲁肃共阚泽及众谋士守寨。程普见周瑜调军有法，甚相敬服。却说孙权差使命持兵符至，说已差陆逊为先锋，直抵蕲、黄地面进兵，吴侯自为后应。瑜又差人西山放火炮，南屏山举号旗。各各准备停当，只等黄昏举动。
话分两头。且说刘玄德在夏口专候孔明回来，忽见一队船到，乃是公子刘琦自来探听消息。玄德请上敌楼坐定，说：“东南风起多时，子龙去接孔明，至今不见到，吾心甚忧。”小校遥指樊口港上：“一帆风送扁舟来到，必军师也。”玄德与刘琦下楼迎接。须臾船到，孔明、子龙登岸。玄德大喜。问候毕，孔明曰：“且无暇告诉别事。前者所约军马战船，皆已办否？”玄德曰：“收拾久矣，只候军师调用。”
孔明便与玄德、刘琦升帐坐定，谓赵云曰：“子龙可带三千军马，渡江径取乌林小路，拣树木芦苇密处埋伏。今夜四更已后，曹操必然从那条路奔走。等他军马过，就半中间放起火来。虽然不杀他尽绝，也杀一半。”云曰：“乌林有两条路：一条通南郡，一条取荆州。不知向那条路来？”孔明曰：“南郡势迫，曹操不敢往；必来荆州，然后大军投许昌而去。”云领计去了。又唤张飞曰：“翼德可领三千兵渡江，截断彝陵这条路，去葫芦谷口埋伏。曹操不敢走南彝陵，必望北彝陵去。来日雨过，必然来埋锅造饭。只看烟起，便就山边放起火来。虽然不捉得曹操，翼德这场功料也不小。”飞领计去了。又唤糜竺、糜芳、刘封三人各驾船只，绕江剿擒败军，夺取器械。三人领计去了。孔明起身，谓公子刘琦曰：“武昌一望之地。最为紧要。公子便请回，率领所部之兵，陈于岸口。操一败必有逃来者，就而擒之，却不可轻离城郭。”刘琦便辞玄德、孔明去了。孔明谓玄德曰：“主公可于樊口屯兵，凭高而望，坐看今夜周郎成大功也。”
时云长在侧，孔明全然不睬。云长忍耐不住，乃高声曰：“关某自随兄长征战，许多年来，未尝落后。今日逢大敌，军师却不委用，此是何意？”孔明笑曰：“云长勿怪！某本欲烦足下把一个最紧要的隘口，怎奈有些违碍，不敢教去。”云长曰：“有何违碍？愿即见谕。”孔明曰：“昔日曹操待足下甚厚，足下当有以报之。今日操兵败，必走华容道；若令足下去时，必然放他过去。因此不敢教去。”云长曰：“军师好心多！当日曹操果是重待某，某已斩颜良，诛文丑，解白马之围，报过他了。今日撞见，岂肯放过！”孔明曰：“倘若放了时，却如何？”云长曰：“愿依军法！”孔明曰：“如此，立下文书。”云长便与了军令状。”云长曰：“若曹操不从那条路上来，如何？”孔明曰：“我亦与你军令状。云长大喜。孔明曰：“云长可于华容小路高山之处，堆积柴草，放起一把火烟，引曹操来。”云长曰：“曹操望见烟，知有埋伏，如何肯来？”孔明笑曰：“岂不闻兵法‘虚虚实实’之论？操虽能用兵，只此可以瞒过他也。他见烟起，将谓虚张声势，必然投这条路来。将军休得容情。”云长领了将令，引关平、周仓并五百校刀手，投华容道埋伏去了。玄德曰：“吾弟义气深重，若曹操果然投华容道去时，只恐端的放了。”孔明曰：“亮夜观乾象，操贼未合身亡。留这人情，教云长做了，亦是美事。”玄德曰：“先生神算，世所罕及！”孔明遂与玄德往樊口，看周瑜用兵，留孙乾、简雍守城。却说曹操在大寨中，与众将商议，只等黄盖消息。当日东南风起甚紧。程昱入告曹操曰：“今日东南风起，宜预提防。”操笑曰：“冬至一阳生，来复之时，安得无东南风？何足为怪！”军士忽报江东一只小船来到，说有黄盖密书。操急唤入。其人呈上书。书中诉说：“周瑜关防得紧，因此无计脱身。今有鄱阳湖新运到粮，周瑜差盖巡哨，已有方便。好歹杀江东名将，献首来降。只在今晚二更，船上插青龙牙旗者，即粮船也。”操大喜，遂与众将来水寨中大船上，观望黄盖船到。
且说江东，天色向晚，周瑜唤出蔡和，令军士缚倒。和叫：“无罪！”瑜曰：“汝是何等人，敢来诈降！吾今缺少福物祭旗，愿借你首级。”和抵赖不过，大叫曰：“汝家阚泽、甘宁亦曾与谋！”瑜曰：“此乃吾之所使也。”蔡和悔之无及。瑜令捉至江边皂纛旗下，奠酒烧纸，一刀斩了蔡和，用血祭旗毕，便令开船。黄盖在第三只火船上，独披掩心，手提利刃，旗上大书“先锋黄盖”。盖乘一天顺风，望赤壁进发。是时东风大作，波浪汹涌。操在中军遥望隔江，看看月上，照耀江水，如万道金蛇，翻波戏浪。操迎风大笑，自以为得志。忽一军指说：“江南隐隐一簇帆幔，使风而来。”操凭高望之。报称：“皆插青龙牙旗。内中有大旗，上书先锋黄盖名字。”操笑曰：“公覆来降，此天助我也！”来船渐近。程昱观望良久，谓操曰：“来船必诈。且休教近寨。”操曰：“何以知之！”程昱曰：“粮在船中，船必稳重；今观来船，轻而且浮。更兼今夜东南风甚紧，倘有诈谋，何以当之？”操省悟，便问：“谁去止之？”文聘曰：“某在水上颇熟，愿请一往。”言毕，跳下小船，用手一指，十数只巡船，随文聘船出。聘立于船头，大叫：“丞相钧旨：南船且休近寨，就江心抛住。”众军齐喝：“快下了篷！”言未绝，弓弦响处，文聘被箭射中左臂，倒在船中。船上大乱，各自奔回。南船距操寨止隔二里水面。黄盖用刀一招，前船一齐发火。火趁风威，风助火势，船如箭发，烟焰涨天。二十只火船，撞入水寨，曹寨中船只一时尽着；又被铁环锁住，无处逃避。隔江炮响，四下火船齐到，但见三江面上，火逐风飞，一派通红，漫天彻地。
曹操回观岸上营寨，几处烟火。黄盖跳在小船上，背后数人驾舟，冒烟突火，来寻曹操。操见势急，方欲跳上岸，忽张辽驾一小脚船，扶操下得船时，那只大船，已自着了。张辽与十数人保护曹操，飞奔岸口。黄盖望见穿绛红袍者下船，料是曹操，乃催船速进，手提利刃，高声大叫：“曹贼休走！黄盖在此！”操叫苦连声。张辽拈弓搭箭，觑着黄盖较近，一箭射去。此时风声正大，黄盖在火光中，那里听得弓弦响？”正中肩窝，翻身落水。正是：火厄盛时遭水厄，棒疮愈后患金疮。
未知黄盖性命如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536852588, '5b9a114c17d0090034093736', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639185, '三国演义 · 第五十回 · 诸葛亮智算华容 关云长义释曹操', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说当夜张辽一箭射黄盖下水，救得曹操登岸，寻着马匹走时，军已大乱。韩当冒烟突火来攻水寨，忽听得士卒报道：“后梢舵上一人，高叫将军表字。”韩当细听，但闻高叫“义公救我？”当曰：“此黄公覆也！”急教救起。见黄盖负箭着伤，咬出箭杆，箭头陷在肉内。韩当急为脱去湿衣，用刀剜出箭头，扯旗束之，脱自己战袍与黄盖穿了，先令别船送回大寨医治。原来黄盖深知水性，故大寒之时，和甲堕江，也逃得性命。却说当日满江火滚，喊声震地。左边是韩当、蒋钦两军从赤壁西边杀来；右边是周泰、陈武两军从赤壁东边杀来；正中是周瑜、程普、徐盛、丁奉大队船只都到。火须兵应，兵仗火威。此正是：三江水战，赤壁鏖兵。曹军着枪中箭、火焚水溺者，不计其数。后人有诗曰：“魏吴争斗决雌雄，赤壁楼船一扫空。烈火初张照云海，周郎曾此破曹公。”又有一绝云：“山高月小水茫茫，追叹前朝割据忙。南士无心迎魏武，东风有意便周郎。”不说江中鏖兵。且说甘宁令蔡中引入曹寨深处，宁将蔡中一刀砍于马下，就草上放起火来。吕蒙遥望中军火起，也放十数处火，接应甘宁。潘璋、董袭分头放火呐喊，四下里鼓声大震。曹操与张辽引百余骑，在火林内走，看前面无一处不着。正走之间，毛玠救得文聘，引十数骑到。操令军寻路。张辽指道：“只有乌林地面，空阔可走。”操径奔乌林。正走间，背后一军赶到，大叫：“曹贼休走！”火光中现出吕蒙旗号。操催军马向前，留张辽断后，抵敌吕蒙。却见前面火把又起，从山谷中拥出一军，大叫：“凌统在此！”曹操肝胆皆裂。忽刺斜里一彪军到，大叫：“丞相休慌！徐晃在此！”彼此混战一场，夺路望北而走。忽见一队军马，屯在山坡前。徐晃出问，乃是袁绍手下降将马延、张凯，有三千北地军马，列寨在彼；当夜见满天火起，未敢转动，恰好接着曹操。操教二将引一千军马开路，其余留着护身。操得这枝生力军马，心中稍安。马延、张凯二将飞骑前行。不到十里，喊声起处，一彪军出。为首一将，大呼曰：“吾乃东吴甘兴霸也！”马延正欲交锋，早被甘宁一刀斩于马下；张凯挺枪来迎，宁大喝一声，凯措手不及，被宁手起一刀，翻身落马。后军飞报曹操。操此时指望合淝有兵救应；不想孙权在合淝路口，望见江中火光，知是我军得胜，便教陆逊举火为号，太史慈见了，与陆逊合兵一处，冲杀将来。操只得望彝陵而走。路上撞见张郃，操令断后。纵马加鞭，走至五更，回望火光渐远，操心方定，问曰：“此是何处？”左右曰：“此是乌林之西，宜都之北。”操见树木丛杂，山川险峻，乃于马上仰面大笑不止。诸将问曰：“丞相何故大笑？”操曰：“吾不笑别人，单笑周瑜无谋，诸葛亮少智。若是吾用兵之时，预先在这里伏下一军，如之奈何？”说犹未了，两边鼓声震响，火光竟天而起，惊得曹操几乎坠马。刺斜里一彪军杀出，大叫：“我赵子龙奉军师将令，在此等候多时了！”操教徐晃、张郃双敌赵云，自己冒烟突火而去。子龙不来追赶，只顾抢夺旗帜。曹操得脱。
天色微明，黑云罩地，东南风尚不息。忽然大雨倾盆，湿透衣甲。操与军士冒雨而行，诸军皆有饥色。操令军士往村落中劫掠粮食，寻觅火种。方欲造饭，后面一军赶到。操心甚慌。原来却是李典、许褚保护着众谋士来到，操大喜，令军马且行，问：“前面是那里地面？”人报：“一边是南彝陵大路，一边是北彝陵山路。”操问：“那里投南郡江陵去近？”军士禀曰：“取北彝陵过葫芦口去最便。”操教走北彝陵。行至葫芦口，军皆饥馁，行走不上，马亦困乏，多有倒于路者。操教前面暂歇。马上有带得锣锅的，也有村中掠得粮米的，便就山边拣干处埋锅造饭，割马肉烧吃。尽皆脱去湿衣，于风头吹晒；马皆摘鞍野放，咽咬草根。操坐于疏林之下，仰面大笑。众官问曰：“适来丞相笑周瑜、诸葛亮，引惹出赵子龙来，又折了许多人马。如今为何又笑？”操曰：“吾笑诸葛亮、周瑜毕竟智谋不足。若是我用兵时，就这个去处，也埋伏一彪军马，以逸待劳；我等纵然脱得性命，也不免重伤矣。彼见不到此，我是以笑之。”正说间，前军后军一齐发喊、操大惊，弃甲上马。众军多有不及收马者。早见四下火烟布合，山口一军摆开，为首乃燕人张翼德，横矛立马，大叫：“操贼走那里去！”诸军众将见了张飞，尽皆胆寒。许褚骑无鞍马来战张飞。张辽、徐晃二将，纵马也来夹攻。两边军马混战做一团。操先拨马走脱，诸将各自脱身。张飞从后赶来。操迤逦奔逃，追兵渐远，回顾众将多已带伤。
正行时，军士禀曰：“前面有两条路，请问丞相从那条路去？”操问：“那条路近？”军士曰：“大路稍平，却远五十余里。小路投华容道，却近五十余里；只是地窄路险，坑坎难行。”操令人上山观望，回报：“小路山边有数处烟起；大路并无动静。”操教前军便走华容道小路。诸将曰：“烽烟起处，必有军马，何故反走这条路？”操曰：“岂不闻兵书有云：虚则实之，实则虚之。诸葛亮多谋，故使人于山僻烧烟，使我军不敢从这条山路走，他却伏兵于大路等着。吾料已定，偏不教中他计！”诸将皆曰：“丞相妙算，人不可及。”遂勒兵走华容道。此时人皆饥倒，马尽困乏。焦头烂额者扶策而行，中箭着枪者勉强而走。衣甲湿透，个个不全；军器旗幡，纷纷不整：大半皆是彝陵道上被赶得慌，只骑得秃马，鞍辔衣服，尽皆抛弃。正值隆冬严寒之时，其苦何可胜言。
操见前军停马不进，问是何故。回报曰：“前面山僻路小，因早晨下雨，坑堑内积水不流，泥陷马蹄，不能前进。”操大怒，叱曰：“军旅逢山开路，遇水叠桥，岂有泥泞不堪行之理！”传下号令，教老弱中伤军士在后慢行，强壮者担土束柴，搬草运芦，填塞道路。务要即时行动，如违令者斩。众军只得都下马，就路旁砍伐竹木，填塞山路。操恐后军来赶，令张辽、许褚、徐晃引百骑执刀在手，但迟慢者便斩之。此时军已饿乏，众皆倒地，操喝令人马践踏而行，死者不可胜数。号哭之声，于路不绝。操怒曰：“生死有命，何哭之有！如再哭者立斩！”三停人马：一停落后，一停填了沟壑，一停跟随曹操。过了险峻，路稍平坦。操回顾止有三百余骑随后，并无衣甲袍铠整齐者。操催速行。众将曰：“马尽乏矣，只好少歇。”操曰：“赶到荆州将息未迟。”又行不到数里，操在马上扬鞭大笑。众将问：“丞相何又大笑？”操曰：“人皆言周瑜、诸葛亮足智多谋，以吾观之，到底是无能之辈。若使此处伏一旅之师，吾等皆束手受缚矣。”
言未毕，一声炮响，两边五百校刀手摆开，为首大将关云长，提青龙刀，跨赤兔马，截住去路。操军见了，亡魂丧胆，面面相觑。操曰：“既到此处，只得决一死战！”众将曰：“人纵然不怯，马力已乏，安能复战？”程昱曰：“某素知云长傲上而不忍下，欺强而不凌弱；恩怨分明，信义素著。丞相旧日有恩于彼，今只亲自告之，可脱此难。”操从其说，即纵马向前，欠身谓云长曰：“将军别来无恙！”云长亦欠身答曰：“关某奉军师将令，等候丞相多时。”操曰：“曹操兵败势危，到此无路，望将军以昔日之情为重。”云长曰：“昔日关某虽蒙丞相厚恩，然已斩颜良，诛文丑，解白马之围，以奉报矣。今日之事，岂敢以私废公？”操曰：“五关斩将之时，还能记否？大丈夫以信义为重。将军深明《春秋》，岂不知庾公之斯追子濯孺子之事乎？”云长是个义重如山之人，想起当日曹操许多恩义，与后来五关斩将之事，如何不动心？又见曹军惶惶，皆欲垂泪，一发心中不忍。于是把马头勒回，谓众军曰：“四散摆开。”这个分明是放曹操的意思。操见云长回马，便和众将一齐冲将过去。云长回身时，曹操已与众将过去了。云长大喝一声，众军皆下马，哭拜于地。云长愈加不忍。正犹豫间，张辽纵马而至。云长见了，又动故旧之情，长叹一声，并皆放去。后人有诗曰：“曹瞒兵败走华容，正与关公狭路逢。只为当初恩义重，放开金锁走蛟龙。”
曹操既脱华容之难。行至谷口，回顾所随军兵，止有二十七骑。比及天晚，已近南郡，火把齐明，一簇人马拦路。操大惊曰：“吾命休矣！”只见一群哨马冲到，方认得是曹仁军马。操才心安。曹仁接着，言：“虽知兵败，不敢远离，只得在附近迎接。”操曰：“几与汝不相见也！”于是引众入南郡安歇。随后张辽也到，说云长之德。操点将校，中伤者极多，操皆令将息。曹仁置酒与操解闷。众谋士俱在座。操忽仰天大恸。众谋士曰：“丞相于虎窟中逃难之时，全无惧怯；今到城中，人已得食，马已得料，正须整顿军马复仇，何反痛哭？”操曰：“吾哭郭奉孝耳！若奉孝在，决不使吾有此大失也！”遂捶胸大哭曰：“哀哉，奉孝！痛哉，奉孝！惜哉！奉孝！”众谋士皆默然自惭。次日，操唤曹仁曰：“吾今暂回许都，收拾军马，必来报仇。汝可保全南郡。吾有一计，密留在此，非急休开，急则开之。依计而行，使东吴不敢正视南郡。”仁曰：“合淝、襄阳，谁可保守？”操曰：“荆州托汝管领；襄阳吾已拨夏侯惇守把；合淝最为紧要之地，吾令张辽为主将，乐进、李典为副将，保守此地。但有缓急，飞报将来。”操分拨已定，遂上马引众奔回许昌。荆州原降文武各官，依旧带回许昌调用。曹仁自遣曹洪据守彝陵、南郡，以防周瑜。
却说关云长放了曹操，引军自回。此时诸路军马，皆得马匹、器械、钱粮，已回夏口；独云长不获一人一骑，空身回见玄德。孔明正与玄德作贺，忽报云长至。孔明忙离坐席，执杯相迎曰：“且喜将军立此盖世之功，与普天下除大害。合宜远接庆贺！”云长默然。孔明曰：“将军莫非因吾等不曾远接，故尔不乐？”回顾左右曰：“汝等缘何不先报？”云长曰：“关某特来请死。”孔明曰：“莫非曹操不曾投华容道上来？”云长曰：“是从那里来。关某无能，因此被他走脱。”孔明曰：“拿得甚将士来？”云长曰：“皆不曾拿。”孔明曰：“此是云长想曹操昔日之恩，故意放了。但既有军令状在此，不得不按军法。”遂叱武士推出斩之。正是：拼将一死酬知己，致令千秋仰义名。
未知云长性命如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536852588, '5b9a116417d009003409380e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639186, '三国演义 · 第五十一回 · 曹仁大战东吴兵 孔明一气周公瑾', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说孔明欲斩云长，玄德曰：“昔吾三人结义时，誓同生死。今云长虽犯法，不忍违却前盟。望权记过，容将功赎罪。”孔明方才饶了。且说周瑜收军点将，各各叙功，申报吴侯。所得降卒，尽行发付渡江，大犒三军，遂进兵攻取南郡。前队临江下寨，前后分五营。周瑜居中。瑜正与众商议征进之策，忽报：“刘玄德使孙乾来与都督作贺。”瑜命请入。乾施礼毕，言：“主公特命乾拜谢都督大德，有薄礼上献。”瑜问曰：“玄德在何处？”乾答曰：“现移兵屯油江口。”瑜惊曰：“孔明亦在油江否？”乾曰；“孔明与主公同在油江。”瑜曰：“足下先回，某亲来相谢也。”瑜收了礼物，发付孙乾先回。肃曰：“却才都督为何失惊？”瑜曰：“刘备屯兵油江，必有取南郡之意。我等费了许多军马，用了许多钱粮，目下南郡反手可得；彼等心怀不仁，要就现成，须放着周瑜不死！”肃曰：“当用何策退之？”瑜曰：“吾自去和他说话。好便好；不好时，不等他取南郡，先结果了刘备！”肃曰：“某愿同往。”于是瑜与鲁肃引三千轻骑，径投油江口来。先说孙乾回见玄德，言周瑜将亲来相谢。玄德乃问孔明曰：“来意若何？”孔明笑曰：“那里为这些薄礼肯来相谢。止为南郡而来。”玄德曰：“他若提兵来，何以待之？”孔明曰：“他来便可如此如此应答。”遂于油江口摆开战船，岸上列着军马。人报：“周瑜、鲁肃引兵到来。”孔明使赵云领数骑来接。瑜见军势雄壮，心甚不安。行至营门外，玄德、孔明迎入帐中。各叙礼毕，设宴相待。玄德举酒致谢鏖兵之事。酒至数巡，瑜曰：“豫州移兵在此，莫非有取南郡之意否？”玄德曰：“闻都督欲取南郡，故来相助。若都督不取，备必取之”。瑜笑曰：“吾东吴久欲吞并汉江，今南郡已在掌中，如何不取？”玄德曰：“胜负不可预定。曹操临归，令曹仁守南郡等处，必有奇计；更兼曹仁勇不可当：但恐都督不能取耳。”瑜曰：“吾若取不得，那时任从公取。”玄德曰：“子敬、孔明在此为证，都督休悔。”鲁肃踌躇未对。瑜曰：“大丈夫一言既出，何悔之有！”孔明曰：“都督此言，甚是公论。先让东吴去取；若不下，主公取之，有何不可！”瑜与肃辞别玄德、孔明，上马而去。玄德问孔明曰：“却才先生教备如此回答，虽一时说了，展转寻思，于理未然。我今孤穷一身，无置足之地，欲得南郡，权且容身；若先教周瑜取了，城池已属东吴矣，却如何得住？”孔明大笑曰：“当初亮劝主公取荆州，主公不听，今日却想耶？”玄德曰：“前为景升之地，故不忍取；今为曹操之地，理合取之。”孔明曰：“不须主公忧虑。尽着周瑜去厮杀，早晚教主公在南郡城中高坐。”玄德曰：“计将安出？”孔明曰：“只须如此如此。”玄德大喜，只在江口屯扎，按兵不动。却说周瑜、鲁肃回寨。肃曰：“都督如何亦许玄德取南郡？”瑜曰：“吾弹指可得南郡，落得虚做人情。”随问帐下将士：“谁敢先取南郡？”一人应声而出，乃蒋钦也。瑜曰：“汝为先锋，徐盛、丁奉为副将，拨五千精锐军马，先渡江。吾随后引兵接应。”且说曹仁在南郡，分付曹洪守彝陵，以为掎角之势。人报：“吴兵已渡汉江。”仁曰：“坚守勿战为上。”骁将牛金奋然进曰：“兵临城下而不出战，是怯也。况吾兵新败，正当重振锐气。某愿借精兵五百，决一死战。”仁从之，令牛金引五百军出战。丁奉纵马来迎。约战四五合，奉诈败，牛金引军追赶入阵。奉指挥众军一裹围牛金于阵中。金左右冲突，不能得出。曹仁在城上望见牛金困在垓心，遂披甲上马，引麾下壮士数百骑出城，奋力挥刀，杀入吴阵。徐盛迎战，不能抵挡。曹仁杀到垓心，救出牛金。回顾尚有数十骑在阵，不能得出，遂复翻身杀入，救出重围。正遇蒋钦拦路，曹仁与牛金奋力冲散。仁弟曹纯，亦引兵接应，混杀一阵。吴军败走，曹仁得胜而回。蒋钦兵败，回见周瑜，瑜怒欲斩之，众将告免。瑜即点兵，要亲与曹仁决战。甘宁曰：“都督未可造次。今曹仁令曹洪据守彝陵，为掎角之势；某愿以精兵三千，径取彝陵，都督然后可取南郡。”瑜服其论，先教甘宁领三千兵攻打彝陵，早有细作报知曹仁，仁与陈矫商议。矫曰：“彝陵有失，南郡亦不可守矣。宜速救之。”仁遂令曹纯与牛金暗地引兵救曹洪。曹纯先使人报知曹洪，令洪出城诱敌。甘宁引兵至彝陵，洪出与甘宁交锋。战有二十余合，洪败走。宁夺了彝陵。至黄昏时，曹纯、牛金兵到，两下相合，围了彝陵。探马飞报周瑜，说甘宁困于彝陵城中，瑜大惊。程普曰：“可急分兵救之。”瑜曰：“此地正当冲要之处，若分兵去救，倘曹仁引兵来袭，奈何？”吕蒙曰：“甘兴霸乃江东大将，岂可不救？”瑜曰：“吾欲自往救之；但留何人在此，代当吾任？”蒙曰：“留凌公绩当之。蒙为前驱，都督断后；不须十日，必奏凯歌。”瑜曰：“未知凌公绩肯暂代吾任否？”凌统曰：“若十日为期，可当之；十日之外，不胜其任矣。”瑜大喜，遂留兵万余，付与凌统；即日起大兵投彝陵来。蒙谓瑜曰：“彝陵南僻小路，取南郡极便。可差五百军去砍倒树木，以断其路。彼军若败，必走此路；马不能行，必弃马而走，吾可得其马也。”瑜从之，差军去讫。
大兵将至彝陵，瑜问：“谁可突围而入，以救甘宁？”周泰愿往，即时绰刀纵马，直杀入曹军之中，径到城下。甘宁望见周泰至，自出城迎之。泰言：“都督自提兵至。”宁传令教军士严装饱食，准备内应。却说曹洪、曹纯、牛金闻周瑜兵将至，先使人往南郡报知曹仁，一面分兵拒敌。及吴兵至，曹兵迎之。比及交锋，甘宁、周泰分两路杀出，曹兵大乱，吴兵四下掩杀。曹洪、曹纯、牛金果然投小路而走；却被乱柴塞道，马不能行，尽皆弃马而走。吴兵得马五百余匹。周瑜驱兵星夜赶到南郡，正遇曹仁军来救彝陵。两军接着，混战一场。天色已晚，各自收兵。
曹仁回城中，与众商议。曹洪曰：“目今失了彝陵，势已危急，何不拆丞相遗计观之，以解此危？”曹仁曰：“汝言正合吾意。”遂拆书观之，大喜，便传令教五更造饭；平明，大小军马，尽皆弃城；城上遍插旌旗，虚张声势。军分三门而出。却说周瑜救出甘宁，陈兵于南郡城处。见曹兵分三门而出，瑜上将台观看。只见女墙边虚搠旌旗，无人守护；又见军士腰下各束缚包裹。瑜暗忖曹仁必先准备走路，遂下将台号令，分布两军为左右翼；如前军得胜，只顾向前追赶，直待鸣金，方许退步。命程普督后军，瑜亲自引军取城。对阵鼓声响处，曹洪出马搦战，瑜自至门旗下，使韩当出马，与曹洪交锋；战到三十余合，洪败走。曹仁自出接战，周泰纵马相迎；斗十余合，仁败走。阵势错乱。周瑜麾两翼军杀出，曹军大败。瑜自引军马追至南郡城下，曹军皆不入城，望西北面走。韩当、周泰引前部尽力追赶。瑜见城门大开，城上又无人，遂令众军抢城。数十骑当先而入。瑜在背后纵马加鞭，直入瓮城。陈矫在敌楼上，望见周瑜亲自入城来，暗暗喝采道：“丞相妙策如神！”一声梆子响，两边弓弩齐发，势如骤雨。争先入城的，都颠入陷坑内。周瑜急勒马回时，被一弩箭，正射中左助，翻身落马。牛金从城中杀出，来捉周瑜；徐盛、丁奉二人舍命救去。城中曹兵突出，吴兵自相践踏，落堑坑者无数。程普急收军时，曹仁、曹洪分兵两路杀回。吴兵大败。幸得凌统引一军从刺斜里杀来，敌住曹兵。曹仁引得胜兵进城，程普收败军回寨。丁、徐二将救得周瑜到帐中，唤行军医者用铁钳子拔出箭头，将金疮药敷掩疮口，疼不可当，饮食俱废。医者曰：“此箭头上有毒，急切不能痊可。若怒气冲激，其疮复发。”程普令三军紧守各寨，不许轻出，三日后，牛金引军来搦战，程普按兵不动。牛金骂至日暮方回，次日又来骂战。程普恐瑜生气，不敢报知。第三日，牛金直至寨门外叫骂，声声只道要捉周瑜。程普与众商议，欲暂且退兵，回见吴侯，却再理会。却说周瑜虽患疮痛，心中自有主张；已知曹兵常来寨前叫骂，却不见众将来禀。一日，曹仁自引大军，擂鼓呐喊，前来搦战。程普拒住不出。周瑜唤众将入帐问曰：“何处鼓噪呐喊？”众将曰：“军中教演士卒。”瑜怒曰：“何欺我也！吾已知曹兵常来寨前辱骂。程德谋既同掌兵权，何故坐视？”遂命人请程普入帐问之。普曰：“吾见公瑾病疮，医者言勿触怒，故曹兵搦战，不敢报知。”瑜曰：“公等不战，主意若何？”普曰：“众将皆欲收兵暂回江东。待公箭疮平复，再作区处。”瑜听罢，于床上奋然跃起曰：“大丈夫既食君禄，当死于战场，以马革裹尸还，幸也！岂可为我一人，而废国家大事乎？”言讫，即披甲上马。诸军众将，无不骇然。遂引数百骑出营前。望见曹兵已布成阵势，曹仁自立马于门旗下，扬鞭大骂曰：“周瑜孺子，料必横夭，再不敢正觑我兵！”骂犹未绝，瑜从群骑内突然出曰：“曹仁匹夫！见周郎否！”曹军看见，尽皆惊骇。曹仁回顾众将曰：“可大骂之！”众军厉声大骂。周瑜大怒，使潘璋出战。未及交锋，周瑜忽大叫一声，口中喷血。坠于马下。曹兵冲来，众将向前抵住，混战一场，救起周瑜，回到帐中。程普问曰：“都督贵体若何？”瑜密谓普曰：“此吾之计也。”普曰：“计将安出？”瑜曰：“吾身本无甚痛楚；吾所以为此者，欲令曹兵知我病危，必然欺敌。可使心腹军士去城中诈降，说吾已死。今夜曹仁必来劫寨。吾却于四下埋伏以应之，则曹仁可一鼓而擒也。”程普曰：“此计大妙！”随就帐下举起哀声。众军大惊，尽传言都督箭疮大发而死，各寨尽皆挂孝。却说曹仁在城中与众商议，言周瑜怒气冲发，金疮崩裂，以致口中喷血，坠于马下，不久必亡。正论间，忽报：“吴寨内有十数个军士来降。中间亦有二人，原是曹兵被掳过去的。”曹仁忙唤入问之。军士曰：“今日周瑜阵前金疮碎裂，归寨即死。今众将皆已挂孝举哀。我等皆受程普之辱，故特归降，便报此事。”曹仁大喜，随即商议今晚便去劫寨，夺周瑜之尸，斩其首级，送赴许都。陈矫曰：“此计速行，不可迟误。”
曹仁遂令牛金为先锋，自为中军，曹洪、曹纯为合后，只留陈矫领些少军士守城，其余军兵尽起。初更后出城，径投周瑜大寨。来到寨门，不见一人，但见虚插旗枪而已。情知中计，急忙退军。四下炮声齐发：东边韩当、蒋钦杀来，西边周泰、潘璋杀来，南边徐盛、丁奉杀来，北边陈武、吕蒙杀来。曹兵大败，三路军皆被冲散，首尾不能相救。曹仁引十数骑杀出重围，正遇曹洪，遂引败残军马一同奔走。杀到五更，离南郡不远，一声鼓响，凌统又引一军拦住去路，截杀一阵。曹仁引军刺斜而走，又遇甘宁大杀一阵。曹仁不敢回南郡，径投襄阳大路而行，吴军赶了一程，自回。
周瑜、程普收住众军，径到南郡城下，见旌旗布满，敌楼上一将叫曰：“都督少罪！吾奉军师将令，已取城了。吾乃常山赵子龙也。”周瑜大怒，便命攻城。城上乱箭射下。瑜命且回军商议，使甘宁引数千军马，径取荆州；凌统引数千军马，径取襄阳；然后却再取南郡未迟。正分拨间，忽然探马急来报说：“诸葛亮自得了南郡，遂用兵符，星夜诈调荆州守城军马来救，却教张飞袭了荆州。”又一探马飞来报说：“夏侯惇在襄阳，被诸葛亮差人赍兵符，诈称曹仁求救，诱惇引兵出，却教云长袭取了襄阳。二处城池，全不费力，皆属刘玄德矣。”周瑜曰：“诸葛亮怎得兵符？”程普曰：“他拿住陈矫，兵符自然尽属之矣。”周瑜大叫一声，金疮迸裂。正是：几郡城池无我分，一场辛苦为谁忙！
未知性命如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536852592, '5b9a117bfb4ffe005ca1b0db', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639187, '三国演义 · 第五十二回 · 诸葛亮智辞鲁肃 赵子龙计取桂阳', NULL, 5, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说周瑜见孔明袭了南郡，又闻他袭了荆襄，如何不气？气伤箭疮，半晌方苏，众将再三劝解。瑜曰：“若不杀诸葛村夫，怎息我心中怨气！程德谋可助我攻打南郡，定要夺还东吴。”正议间，鲁肃至。瑜谓之曰：“吾欲起兵与刘备、诸葛亮共决雌雄，复夺城池。子敬幸助我。”鲁肃曰：“不可。方今与曹操相持，尚未分成败；主公现攻合淝不下。不争自家互相吞并，倘曹兵乘虚而来，其势危矣。况刘玄德旧曾与曹操相厚，若逼得紧急，献了城池，一同攻打东吴，如之奈何？”瑜曰：“吾等用计策，损兵马，费钱粮，他去图现成，岂不可恨！”肃曰：“公瑾且耐。容某亲见玄德，将理来说他。若说不通，那时动兵未迟。”诸将曰：“子敬之言甚善。”
于是鲁肃引从者径投南郡来，到城下叫门。赵云出问，肃曰：“我要见刘玄德有话说。”云答曰：“吾主与军师在荆州城中。”肃遂不入南郡，径奔荆州。见旌旗整列，军容甚盛，肃暗羡曰：“孔明真非常人也！”军士报入城中，说鲁子敬要见。孔明令大开城门，接肃入衙。讲礼毕，分宾主而坐。茶罢，肃曰：“吾主吴侯，与都督公瑾，教某再三申意皇叔，前者，操引百万之众，名下江南，实欲来图皇叔；幸得东吴杀退曹兵，救了皇叔。所有荆州九郡，合当归于东吴。今皇叔用诡计，夺占荆襄，使江东空费钱粮军马，而皇叔安受其利，恐于理未顺。”孔明曰：“子敬乃高明之士，何故亦出此言？常言道：物必归主。荆襄九郡，非东吴之地，乃刘景升之基业。吾主固景升之弟也。景升虽亡，其子尚在；以叔辅侄，而取荆州，有何不可？”肃曰：“若果系公子刘琦占据，尚有可解；今公子在江夏，须不在这里！”孔明曰：“子敬欲见公子乎？”便命左右：“请公子出来。”只见两从者从屏风后扶出刘琦。琦谓肃曰：“病躯不能施礼，子敬勿罪。”鲁肃吃了一惊，默然无语，良久，言曰：“公子若不在，便如何？”孔明曰：“公子在一日，守一日；若不在，别有商议。”肃曰：“若公子不在，须将城池还我东吴。”孔明曰：“子敬之言是也。”遂设宴相待。
宴罢，肃辞出城，连夜归寨，具言前事。瑜曰：“刘琦正青春年少，如何便得他死？这荆州何日得还？”肃曰：“都督放心。只在鲁肃身上，务要讨荆襄还东吴。”瑜曰：“子敬有何高见？”肃曰：“吾观刘琦过于酒色，病入膏肓，现今面色羸瘦，气喘呕血，不过半年，其人必死。那时往取荆州，刘备须无得推故。”周瑜犹自忿气未消，忽孙权遣使至。瑜令请入。使曰：“主公围合淝，累战不捷。特令都督收回大军，且拨兵赴合淝相助。”周瑜只得班师回柴桑养病，令程普部领战船士卒，来合淝听孙权调用。
却说刘玄德自得荆州、南郡、襄阳，心中大喜，商议久远之计。忽见一人上厅献策，视之，乃伊籍也。玄德感其旧日之恩，十分相敬，坐而问之。籍曰：“要知荆州久远之计，何不求贤士以问之？”玄德曰：“贤士安在？”籍曰：“荆襄马氏，兄弟五人并有才名：幼者名谡，字幼常；其最贤者，眉间有白毛，名良，字季常。乡里为之谚曰：‘马氏五常，白眉最良。’公何不求此人而与之谋？”玄德遂命请之。马良至，玄德优礼相待，请问保守荆襄之策。良曰：“荆襄四面受敌之地，恐不可久守；可令公子刘琦于此养病，招谕旧人以守之，就表奏公子为荆州刺史，以安民心。然后南征武陵、长沙、桂阳、零陵四郡，积收钱粮，以为根本。此久远之计也。”玄德大喜，遂问：“四郡当先取何郡？”良曰：“湘江之西，零陵最近，可先取之；次取武陵。然后湘江之东取桂阳；长沙为后。”玄德遂用马良为从事，伊籍副之。请孔明商议送刘琦回襄阳，替云长回荆州。便调兵取零陵，差张飞为先锋，赵云合后，孔明；玄德为中军，人马一万五千；留云长守荆州；糜竺、刘封守江陵。却说零陵太守刘度，闻玄德军马到来，乃与其子刘贤商议。贤曰：“父亲放心。他虽有张飞、赵云之勇，我本州上将邢道荣，力敌万人，可以抵对。”刘度遂命刘贤与邢道荣引兵万余，离城三十里，依山靠水下寨。探马报说：“孔明自引一军到来。”道荣便引军出战。两阵对圆，道荣出马，手使开山大斧，厉声高叫：“反贼安敢侵我境界！”只见对阵中，一簇黄旗出。旗开处，推出一辆四轮车，车中端坐一人，头戴纶巾，身披鹤氅，手执羽扇，用扇招邢道荣曰：“吾乃南阳诸葛孔明也。曹操引百万之众，被吾聊施小计，杀得片甲不回。汝等岂堪与我对敌？我今来招安汝等，何不早降？”道荣大笑曰：“赤壁鏖兵，乃周郎之谋也，干汝何事，敢来诳语！”轮大斧竟奔孔明。孔明便回车，望阵中走，阵门复闭。道荣直冲杀过来，阵势急分两下而走。道荣遥望中央一簇黄旗，料是孔明，乃只望黄旗而赶。抹过山脚，黄旗扎住，忽地中央分开，不见四轮车，只见一将挺矛跃马，大喝一声，直取道荣，乃张翼德也。道荣轮大斧来迎，战不数合，气力不加，拨马便走。翼德随后赶来，喊声大震，两下伏兵齐出。道荣舍死冲过，前面一员大将，拦住去路，大叫：“认得常山赵子龙否！”道荣料敌不过，又无处奔走，只得下马请降。子龙缚来寨中见玄德、孔明。玄德喝教斩首。孔明急止之，问道荣曰：“汝若与我捉了刘贤，便准你投降。”道荣连声愿往。孔明曰：“你用何法捉他？”道荣曰：“军师若肯放某回去，某自有巧说。今晚军师调兵劫寨，某为内应，活捉刘贤，献与军师。刘贤既擒，刘度自降矣。”玄德不信其言。孔明曰：“邢将军非谬言也。”遂放道荣归。道荣得放回寨，将前事实诉刘贤。贤曰：“如之奈何？”道荣曰：“可将计就计。今夜将兵伏于寨外，寨中虚立旗幡，待孔明来劫寨，就而擒之。”刘贤依计。
当夜二更，果然有一彪军到寨口，每人各带草把，一齐放火。刘贤、道荣两下杀来，放火军便退。刘贤、道荣两军乘势追赶，赶了十余里，军皆不见。刘贤、道荣大惊，急回本寨，只见火光未灭，寨中突出一将，乃张翼德也。刘贤叫道荣：“不可入寨，却去劫孔明寨便了。”于是复回军。走不十里，赵云引一军刺斜里杀出，一枪刺道荣于马下。刘贤急拨马奔走，背后张飞赶来，活捉过马，绑缚见孔明。贤告曰：“邢道荣教某如此，实非本心也。”孔明令释其缚，与衣穿了，赐酒压惊，教人送入城说父投降；如其不降，打破城池，满门尽诛。刘贤回零陵见父刘度，备述孔明之德，劝父投降。度从之，遂于城上竖起降旗，大开城门，赍捧印绶出城，竟投玄德大寨纳降。孔明教刘度仍为郡守，其子刘贤赴荆州随军办事。零陵一郡居民，尽皆喜悦。
玄德入城安抚已毕，赏劳三军。乃问众将曰：“零陵已取了，桂阳郡何人敢取？”赵云应曰：“某愿往。”张飞奋然出曰：“飞亦愿往！”二人相争。孔明曰：“终是子龙先应，只教子龙去。”张飞不服，定要去取。孔明教拈阉，拈着的便去。又是子龙拈着。张飞怒曰：“我并不要人相帮，只独领三千军去，稳取城池。”赵云曰：“某也只领三千军去。如不得城，愿受军令。”孔明大喜，责了军令状，选三千精兵付赵云去。张飞不服，玄德喝退。赵云领了三千人马，径往桂阳进发。早有探马报知桂阳太守赵范。范急聚众商议。管军校尉陈应、鲍隆愿领兵出战。原来二人都是桂阳岭山乡猎户出身，陈应会使飞叉，鲍隆曾射杀双虎。二人自恃勇力，乃对赵范曰：“刘备若来，某二人愿为前部。”赵范曰：“我闻刘玄德乃大汉皇叔；更兼孔明多谋，关、张极勇；今领兵来的赵子龙，在当阳长坂百万军中，如入无人之境。我桂阳能有多少人马？不可迎敌，只可投降。”应曰：“某请出战。若擒不得赵云，那时任太守投降不迟。”赵范拗不过，只得应允。陈应领三千人马出城迎敌，早望见赵云领军来到。陈应列成阵势，飞马绰叉而出。赵云挺枪出马，责骂陈应曰：“吾主刘玄德，乃刘景升之弟，今辅公子刘琦同领荆州，特来抚民。汝何敢迎敌！”陈应骂曰：“我等只服曹丞相，岂顺刘备！”赵云大怒，挺枪骤马，直取陈应。应捻叉来迎，两马相交，战到四五合，陈应料敌不过，拨马便走。赵云追赶。陈应回顾赵云马来相近，用飞叉掷去，被赵云接住。回掷陈应。应急躲过，云马早到，将陈应活捉过马，掷于地下，喝军士绑缚回寨。败军四散奔走。云入寨叱陈应曰：“量汝安敢敌我！我今不杀汝，放汝回去；说与赵范，早来投降。”陈应谢罪，抱头鼠窜，回到城中，对赵范尽言其事。范曰：“我本欲降，汝强要战，以致如此。”遂叱退陈应，赍捧印绶，引十数骑出城投大寨纳降。云出寨迎接，待以宾礼，置酒共饮，纳了印绶，酒至数巡，范曰：“将军姓赵，某亦姓赵，五百年前，合是一家。将军乃真定人，某亦真定人，又是同乡。倘得不弃，结为兄弟，实为万幸。”云大喜，各叙年庚。云与范同年。云长范四个月，范遂拜云为兄。二人同乡，同年，又同姓，十分相得。至晚席散，范辞回城。次日，范请云入城安民。云教军士休动，只带五十骑随入城中。居民执香伏道而接。云安民已毕，赵范邀请入衙饮宴。酒至半酣，范复邀云入后堂深处，洗盏更酌。云饮微醉。范忽请出一妇人，与云把酒。子龙见妇人身穿缟素，有倾国倾城之色，乃问范曰：“此何人也？”范曰：“家嫂樊氏也。”子龙改容敬之。樊氏把盏毕，范令就坐。云辞谢。樊氏辞归后堂。云曰：“贤弟何必烦令嫂举杯耶？”范笑曰：“中间有个缘故，乞兄勿阻：先兄弃世已三载，家嫂寡居，终非了局，弟常劝其改嫁。嫂曰：‘若得三件事兼全之人，我方嫁之：第一要文武双全，名闻天下；第二要相貌堂堂，威仪出众；第三要与家兄同姓。’你道天下那得有这般凑巧的？今尊兄堂堂仪表，名震四海，又与家兄同姓，正合家嫂所言。若不嫌家嫂貌陋，愿陪嫁资，与将军为妻，结累世之亲，如何？”云闻言大怒而起，厉声曰：“吾既与汝结为兄弟，汝嫂即吾嫂也，岂可作此乱人伦之事乎！”赵范羞惭满面，答曰：“我好意相待，如何这般无礼！”遂目视左右，有相害之意。云已觉，一拳打倒赵范，径出府门，上马出城去了。
范急唤陈应、鲍隆商议。应曰：“这人发怒去了，只索与他厮杀。”范曰：“但恐赢他不得。”鲍隆曰：“我两个诈降在他军中，太守却引兵来搦战，我二人就阵上擒之。”陈应曰：“必须带些人马。”隆曰：“五百骑足矣。”当夜二人引五百军径奔赵云寨来投降。云已心知其诈，遂教唤入。二将到帐下，说：“赵范欲用美人计赚将军，只等将军醉了，扶入后堂谋杀，将头去曹丞相处献功：如此不仁。某二人见将军怒出，必连累于某，因此投降。”赵云佯喜，置酒与二人痛饮。二人大醉，云乃缚于帐中，擒其手下人问之，果是诈降。云唤五百军入，各赐酒食，传令曰：“要害我者，陈应、鲍隆也；不干众人之事。汝等听吾行计，皆有重赏。”众军拜谢。将降将陈、鲍二人当时斩了；却教五百军引路，云引一千军在后，连夜到桂阳城下叫门。城上听时，说陈、鲍二将军杀了赵云回军，请太守商议事务。城上将火照看，果是自家军马。赵范急忙出城。云喝左右捉下，遂入城，安抚百姓已定，飞报玄德。
玄德与孔明亲赴桂阳。云迎接入城，推赵范于阶下。孔明问之，范备言以嫂许嫁之事。孔明谓云曰：“此亦美事，公何如此？”云曰：“赵范既与某结为兄弟，今若娶其嫂，惹人唾骂，一也；其妇再嫁，使失大节，二也；赵范初降，其心难测，三也。主公新定江汉，枕席未安，云安敢以一妇人而废主公之大事？”玄德曰：“今日大事已定，与汝娶之，若何？”云曰：“天下女子不少，但恐名誉不立，何患无妻子乎？”玄德曰：“子龙真丈夫也！”遂释赵范，仍令为桂阳太守，重赏赵云。张飞大叫曰：“偏子龙干得功！偏我是无用之人！只拨三千军与我去取武陵郡，活捉太守金旋来献！”孔明大喜曰：“翼德要去不妨，但要依一件事。”正是：军师决胜多奇策，将士争先立战功。
未知孔明说出那一件事来，且看下文分解。', '', '', '', NULL, '', 'indent', 1536852593, '5b9a1192fb4ffe005ca1b37f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639195, '三国演义 · 第五十七回 · 柴桑口卧龙吊丧 耒阳县凤雏理事', NULL, 3, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说周瑜怒气填胸，坠于马下，左右急救归船。军士传说：“玄德、孔明在前山顶上饮酒取乐。”瑜大怒，咬牙切齿曰：“你道我取不得西川，吾誓取之！”正恨间，人报吴侯遣弟孙瑜到。周瑜接入。具言其事。孙瑜曰：“吾奉兄命来助都督。”遂令催军前行。行至巴丘，人报上流有刘封、关平二人领军截住水路。周瑜愈怒。忽又报孔明遣人送书至。周瑜拆封视之。书曰：“汉军师中郎将诸葛亮，致书于东吴大都督公瑾先生麾下：亮自柴桑一别，至今恋恋不忘。闻足下欲取西川，亮窃以为不可。益州民强地险，刘璋虽闇弱，足以自守。今劳师远征，转运万里，欲收全功，虽吴起不能定其规，孙武不能善其后也。曹操失利于赤壁，志岂须臾忘报仇哉？今足下兴兵远征，倘操乘虚而至，江南齑粉矣！亮不忍坐视，特此告知。幸垂照鉴。”周瑜览毕，长叹一声，唤左右取纸笔作书上吴侯。乃聚众将曰：“吾非不欲尽忠报国，奈天命已绝矣。汝等善事吴侯，共成大业。”言讫，昏绝。徐徐又醒，仰天长叹曰：“既生瑜，何生亮！”连叫数声而亡。寿三十六岁。后人有诗叹曰：“赤壁遗雄烈，青年有俊声。弦歌知雅意，杯酒谢良朋，曾谒三千斛，常驱十万兵。巴丘终命处，凭吊欲伤情。”周瑜停丧于巴丘。众将将所遗书缄，遣人飞报孙权。权闻瑜死，放声大哭。拆视其书，乃荐鲁肃以自代也。书略曰：“瑜以凡才，荷蒙殊遇，委任腹心，统御兵马，敢不竭股肱之力，以图报效。奈死生不测，修短有命；愚志未展，微躯已殒，遗恨何极！方今曹操在北，疆场未静；刘备寄寓，有似养虎；天下之事，尚未可知。此正朝士旰食之秋，至尊垂虑之日也。鲁肃忠烈，临事不苟，可以代瑜之任。人之将死，其言也善。倘蒙垂鉴，瑜死不朽矣。”孙权览毕，哭曰：“公瑾有王佐之才，今忽短命而死，孤何赖哉？既遗书特荐子敬，孤敢不从之。”即日便命鲁肃为都督，总统兵马；一面教发周瑜灵柩回葬。却说孔明在荆州，夜观天文，见将星坠地，乃笑曰：“周瑜死矣。”至晓，告于玄德。玄德使人探之，果然死了。玄德问孔明曰：“周瑜既死，还当如何？”孔明曰：“代瑜领兵者，必鲁肃也。亮观天象，将星聚于东方。亮当以吊丧为由。往江东走一遭，就寻贤士佐助主公。”玄德曰：“只恐吴中将士加害于先生。”孔明曰：“瑜在之日，亮犹不惧；今瑜已死，又何患乎？”乃与赵云引五百军，具祭礼，下船赴巴丘吊丧。于路探听得孙权已令鲁肃为都督，周瑜灵柩已回柴桑。
孔明径至柴桑，鲁肃以礼迎接。周瑜部将皆欲杀孔明，因见赵云带剑相随，不敢下手。孔明教设祭物于灵前，亲自奠酒，跪于地下，读祭文曰：“呜呼公瑾，不幸夭亡！修短故天，人岂不伤？我心实痛，酹酒一觞；君其有灵，享我烝尝！吊君幼学，以交伯符；仗义疏财，让舍以居。吊君弱冠，万里鹏抟；定建霸业，割据江南。吊君壮力，远镇巴丘；景升怀虑，讨逆无忧。吊君丰度，佳配小乔；汉臣之婿，不愧当朝，吊君气概，谏阻纳质；始不垂翅，终能奋翼。吊君鄱阳，蒋干来说；挥洒自如，雅量高志。吊君弘才，文武筹略；火攻破敌，挽强为弱。想君当年，雄姿英发；哭君早逝，俯地流血。忠义之心，英灵之气；命终三纪，名垂百世，哀君情切，愁肠千结；惟我肝胆，悲无断绝。昊天昏暗，三军怆然；主为哀泣；友为泪涟。亮也不才，丐计求谋；助吴拒曹，辅汉安刘；掎角之援，首尾相俦，若存若亡，何虑何忧？呜呼公瑾！生死永别！朴守其贞，冥冥灭灭，魂如有灵，以鉴我心：从此天下，更无知音！呜呼痛哉！伏惟尚飨。”孔明祭毕，伏地大哭，泪如涌泉，哀恸不已。众将相谓曰：“人尽道公瑾与孔明不睦，今观其祭奠之情，人皆虚言也。”鲁肃见孔明如此悲切，亦为感伤，自思曰：“孔明自是多情，乃公瑾量窄，自取死耳。”后人有诗叹曰：“卧龙南阳睡未醒，又添列曜下舒城。苍天既已生公瑾，尘世何须出孔明！”
鲁肃设宴款待孔明。宴罢，孔明辞回。方欲下船，只见江边一人道袍竹冠，皂绦素履，一手揪住孔明大笑曰：“汝气死周郎，却又来吊孝，明欺东吴无人耶！”孔明急视其人，乃凤雏先生庞统也。孔明亦大笑。两人携手登舟，各诉心事。孔明乃留书一封与统，嘱曰：“吾料孙仲谋必不能重用足下。稍有不如意，可来荆州共扶玄德。此人宽仁厚德，必不负公平生之所学。”统允诺而别，孔明自回荆州。
却说鲁肃送周瑜灵柩至芜湖，孙权接着，哭祭于前，命厚葬于本乡。瑜有两男一女，长男循，次男胤，权皆厚恤之。鲁肃曰：“肃碌碌庸才，误蒙公瑾重荐，其实不称所职，愿举一人以助主公。此人上通天文，下晓地理；谋略不减于管、乐，枢机可并于孙、吴。往日周公瑾多用其言，孔明亦深服其智，现在江南，何不重用！”权闻言大喜，便问此人姓名。肃曰：“此人乃襄阳人，姓庞，名统，字士元：道号凤雏先生。”权曰：“孤亦闻其名久矣。今既在此，可即请来相见。”
于是鲁肃邀请庞统入见孙权。施礼毕。权见其人浓眉掀鼻，黑面短髯，形容古怪，心中不喜。乃问曰：“公平生所学，以何为主？”统曰：“不必拘执，随机应变。”权曰：“公之才学，比公瑾如何？”统笑曰：“某之所学，与公瑾大不相同。”权平生最喜周瑜，见统轻之，心中愈不乐，乃谓统曰：“公且退。待有用公之时，却来相请。”统长叹一声而出。鲁肃曰：“主公何不用庞士元？”权曰：“狂士也，用之何益！”肃曰：“赤壁鏖兵之时，此人曾献连环策，成第一功。主公想必知之。”权曰：“此时乃曹操自欲钉船，未必此人之功也，吾誓不用之。”
鲁肃出谓庞统曰：“非肃不荐足下，奈吴侯不肯用公。公且耐心。”统低头长叹不语。肃曰：“公莫非无意于吴中乎？”统不答。肃曰：“公抱匡济之才，何往不利？可实对肃言，将欲何往？”统曰：“吾欲投曹操去也。”肃曰：“此明珠暗投矣，可往荆州投刘皇叔，必然重用。”统曰：“统意实欲如此，前言戏耳。”肃曰：“某当作书奉荐，公辅玄德，必令孙、刘两家，无相攻击，同力破曹。”统曰：“此某平生之素志也。”乃求肃书。径往荆州来见玄德。
此时孔明按察四郡未回，门吏传报：“江南名士庞统，特来相投。”玄德久闻统名，便教请入相见。统见玄德，长揖不拜。玄德见统貌陋，心中亦不悦，乃问统曰：“足下远来不易？”统不拿出鲁肃、孔明书投呈，但答曰：“闻皇叔招贤纳士，特来相投。”玄德曰：“荆楚稍定，苦无闲职。此去东北一百三十里，有一县名耒阳县，缺一县宰，屈公任之，如后有缺，却当重用。”统思：“玄德待我何薄！”欲以才学动之，见孔明不在，只得勉强相辞而去。统到耒阳县，不理政事，终日饮酒为乐；一应钱粮词讼，并不理会。有人报知玄德，言庞统将耒阳县事尽废。玄德怒曰：“竖儒焉敢乱吾法度！”遂唤张飞分付，引从人去荆南诸县巡视：“如有不公不法者，就便究问。恐于事有不明处，可与孙乾同去。”张飞领了言语，与孙乾前至耒阳县。军民官吏，皆出郭迎接，独不见县令。飞问曰：“县令何在？”同僚覆曰：“庞县令自到任及今，将百余日，县中之事，并不理问，每日饮酒，自旦及夜，只在醉乡。今日宿酒未醒，犹卧不起。”张飞大怒，欲擒之。孙乾曰：“庞士元乃高明之人，未可轻忽。且到县问之。如果于理不当，治罪未晚。”飞乃入县，正厅上坐定，教县令来见。统衣冠不整，扶醉而出。飞怒曰：“吾兄以汝为人，令作县宰，汝焉敢尽废县事！”统笑曰：“将军以吾废了县中何事？”飞曰：“汝到任百余日，终日在醉乡，安得不废政事？”统曰：“量百里小县，些小公事，何难决断！将军少坐，待我发落。”随即唤公吏，将百余日所积公务，都取来剖断。吏皆纷然赍抱案卷上厅，诉词被告人等，环跪阶下。统手中批判，口中发落，耳内听词，曲直分明，并无分毫差错。民皆叩首拜伏。
不到半日，将百余日之事，尽断毕了，投笔于地而对张飞曰：“所废之事何在！曹操、孙权，吾视之若掌上观文，量此小县，何足介意！”飞大惊，下席谢曰：“先生大才，小子失敬。吾当于兄长处极力举荐。”统乃将出鲁肃荐书。飞曰：“先生初见吾兄，何不将出？”统曰：“若便将出，似乎专藉荐书来干谒矣。”飞顾谓孙乾曰：“非公则失一大贤也。”遂辞统回荆州见玄德，具说庞统之才。玄德大惊曰：“屈待大贤，吾之过也！”飞将鲁肃荐书呈上。玄德拆视之。书略曰：“庞士元非百里之才，使处治中、别驾之任，始当展其骥足。如以貌取之，恐负所学，终为他人所用，实可惜也！”玄德看毕，正在嗟叹，忽报孔明回。玄德接入，礼毕，孔明先明曰：“庞军师近日无恙否？”玄德曰：“近治耒阳县，好酒废事。”孔明笑曰：“士元非百里之才，胸中之学，胜亮十倍。亮曾有荐书在士元处，曾达主公否？”玄德曰：“今日方得子敬书，却未见先生之书。”孔明曰：“大贤若处小任，往往以酒糊涂，倦于视事。”玄德曰：“若非吾弟所言，险失大贤。”随即令张飞往耒阳县敬请庞统到荆州。玄德下阶请罪。统方将出孔明所荐之书。玄德看书中之意，言凤雏到日，宜即重用。玄德喜曰：“昔司马德操言：‘伏龙、凤雏，两人得一，可安天下。’今吾二人皆得，汉室可兴矣。”遂拜庞统为副军师中郎将，与孔明共赞方略，教练军士，听候征伐。
早有人报到许昌，言刘备有诸葛亮、庞统为谋士，招军买马，积草屯粮，连结东吴，早晚必兴兵北伐。曹操闻之，遂聚众谋士商议南征。荀攸进曰：“周瑜新死，可先取孙权，次攻刘备。”操曰：“我若远征，恐马腾来袭许都。前在赤壁之时，军中有讹言，亦传西凉入寇之事，今不可不防也。”荀攸曰：“以愚所见，不若降诏加马腾为征南将军，使讨孙权，诱入京师，先除此人，则南征无患矣。”操大喜，即日遣人赍诏至西凉召马腾。却说腾字寿成，汉伏波将军马援之后，父名肃，字子硕，桓帝时为天水兰干县尉；后失官流落陇西，与羌人杂处，遂娶羌女生腾。腾身长八尺。体貌雄异，禀性温良，人多敬之。灵帝末年，羌人多叛，腾招募民兵破之。初平中年，因讨贼有功，拜征西将军，与镇西将军韩遂为弟兄。当日奉诏，乃与长子马超商议曰：“吾自与董承受衣带诏以来，与刘玄德约共讨贼，不幸董承已死，玄德屡败。我又僻处西凉，未能协助玄德。今闻玄德已得荆州，我正欲展昔日之志，而曹操反来召我，当是如何？”马超曰：“操奉天子之命以召父亲。今若不往，彼必以逆命责我矣。当乘其来召，竟往京师，于中取事，则昔日之志可展也。”马腾兄子马岱谏曰：“曹操心怀叵测，叔父若往，恐遭其害。”超曰：“儿愿尽起西凉之兵，随父亲杀入许昌，为天下除害，有何不可？”腾曰：“汝自统羌兵保守西凉，只教次子马休、马铁并侄马岱随我同往。曹操见有汝在西凉，又有韩遂相助，谅不敢加害于我也。”超曰：“父亲欲往，切不可轻入京师。当随机应变，观其动静。”腾曰：“吾自有处，不必多虑。”
于是马腾乃引西凉兵五千，先教马休、马铁为前部，留马岱在后接应，迤逦望许昌而来。离许昌二十里屯住军马。曹操听知马腾已到，唤门下侍郎黄奎分付曰：“目今马腾南征，吾命汝为行军参谋，先至马腾寨中劳军，可对马腾说：西凉路远，运粮甚难，不能多带人马。我当更遣大兵，协同前进。来日教他入城面君，吾就应付粮草与之。”奎领命，来见马腾。腾置酒相待。奎酒半酣而言曰：“吾父黄琬死于李傕、郭汜之难，尝怀痛恨。不想今日又遇欺君之贼！”腾曰：“谁为欺君之贼？”奎曰：“欺君者操贼也。公岂不知之，而问我耶？”腾恐是操使来相探，急止之曰：“耳目较近，休得乱言。”奎叱曰：“公竟忘却衣带诏乎！”腾见他说出心事，乃密以实情告之。奎曰：“操欲公入城面君，必非好意。公不可轻入。来日当勒兵城下。待曹操出城点军，就点军处杀之，大事济矣。”二人商议已定。黄奎回家，恨气未息。其妻再三问之，奎不肯言。不料其妾李春香、与奎妻弟苗泽私通。泽欲得春香，正无计可施。妾见黄奎愤恨，遂对泽曰：“黄侍郎今日商议军情回，意甚愤恨，不知为谁？”泽曰：“汝可以言挑之曰：“人皆说刘皇叔仁德，曹操奸雄，何也？看他说甚言语。”是夜黄奎果到春香房中。妾以言挑之。奎乘醉言曰：“汝乃妇人，尚知邪正，何况我乎？吾所恨者，欲杀曹操也！”妾曰：“若欲杀之，如何下手？”奎曰：“吾已约定马将军，明日在城外点兵时杀之。”妾告于苗泽，泽报知曹操。操便密唤曹洪、许褚分付如此如此；又唤夏侯渊、徐晃分付如此如此。各人领命去了，一面先将黄奎一家老小拿下。次日，马腾领着西凉兵马，将次近城，只见前面一簇红旗，打着丞相旗号。马腾只道曹操自来点军，拍马向前。忽听得一声炮响，红旗开处，弓弩齐发。一将当先，乃曹洪也。马腾急拨马回时，两下喊声又起：左边许褚杀来，右边夏侯渊杀来，后面又是徐晃领兵杀至，截断西凉军马，将马腾父子三人困在垓心。马腾见不是头，奋力冲杀。马铁早被乱箭射死。马休随着马腾，左冲右突，不能得出。二人身带重伤，坐下马又被箭射倒。父子二人俱被执。曹操教将黄奎与马腾父子，一齐绑至。黄奎大叫：“无罪！”操教苗泽对证。马腾大骂曰：“竖儒误我大事！我不能为国杀贼，是乃天也！”操命牵出。马腾骂不绝口，与其子马休，及黄奎，一同遇害。后人有诗叹马腾曰：“父子齐芳烈，忠贞著一门，捐生图国难，誓死答君恩。嚼血盟言在，诛奸义状存。西凉推世胄，不愧伏波孙！”苗泽告操曰：“不愿加赏，只求李春香为妻。”操笑曰：“你为了一妇人，害了你姐夫一家，留此不义之人何用！”便教将苗泽、李春香与黄奎一家老小并斩于市。观者无不叹息。后人有诗叹曰：“苗泽因私害荩臣，春香未得反伤身。奸雄亦不相容恕，枉自图谋作小人。”
曹操教招安西凉兵马，谕之曰：“马腾父子谋反，不干众人之事。”一面使人分付把住关隘，休教走了马岱。且说马岱自引一千兵在后。早有许昌城外逃回军士，报知马岱。岱大惊，只得弃了兵马，扮作客商，连夜逃遁去了。曹操杀了马腾等，便决意南征。忽人报曰：“刘备调练军马，收拾器械，将欲取川。”操惊曰：“若刘备收川，则羽翼成矣。将何以图之？”言未毕，阶下一人进言曰：“某有一计，使刘备、孙权不能相顾，江南、西川皆归丞相。”正是：西州豪杰方遭戮，南国英雄又受殃。
未知献计者是谁，且看下文分解。', '', '', '', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "60fc5bfa3cbe6008c19b1a02", "shortContent": "这是周瑜病危之际给孙权的遗书，录自《三国志·吴书·鲁肃传》裴松之注所引《江表传》。《周瑜传》载：周瑜诣京见孙权后，“还江陵，为行装，而道于巴丘病卒，时年三十六”。因此，这封信当写于建安十五年（210）。\n周瑜是东吴政权的重臣。他与孙策是同庚挚友，共同奠定了东吴政权的基础，又分娶江东美人乔氏姐妹，成为连襟。孙策曾说：“周公瑾英隽异才，与孤有总角之好、骨肉之分。”（《三国志·周瑜传》裴注引《江表传》）...", "authors": ["戎晓若"], "pressName": "上海辞书出版社"}]', '', 'indent', 1536943837, '5b9b6c9f1579a3003a4f7e20', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639196, '三国演义 · 第五十八回 · 马孟起兴兵雪恨 曹阿瞒割须弃袍', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说献策之人，乃治书侍御史陈群，字长文。操问曰：“陈长文有何良策？”群曰：“今刘备、孙权结为唇齿，若刘备欲取西川，丞相可命上将提兵，会合淝之众，径取江南，则孙权必求救于刘备；备意在西川，必无心救权；权无救则力乏兵衰，江东之地，必为丞相所得。若得江东，则荆州一鼓可平也；荆州既平，然后徐图西川：天下定矣。”操曰：“长文之言，正合吾意。”即时起大兵三十万，径下江南；令合淝张辽，准备粮草，以为供给。
早有细作报知孙权。权聚众将商议。张昭曰：“可差人往鲁子敬处，教急发书到荆州，使玄德同力拒曹。子敬有恩于玄德，其言必从；且玄德既为东吴之婿，亦义不容辞。若玄德来相助。江南可无患矣。”权从其言，即遣人谕鲁肃，使求救于玄德。肃领命，随即修书使人送玄德，玄德看了书中之意，留使者于馆舍，差人往南郡请孔明。孔明到荆州，玄德将鲁肃书与孔明看毕，孔明曰：“也不消动江南之兵，也不必动荆州之兵，自使曹操不敢正觑东南。”便回书与鲁肃，教高枕无忧，若但有北兵侵犯，皇叔自有退兵之策。使者去了。玄德问曰：“今操起三十万大军，会合淝之众，一拥而来，先生有何妙计，可以退之？”孔明曰：“操平生所虑者，乃西凉之兵也。今操杀马腾，其子马超，现统西凉之众，必切齿操贼。主公可作一书，往结马超，使超兴兵入关，则操又何暇下江南乎？”玄德大喜，即时作书，遣一心腹人，径往西凉州投下。
却说马超在西凉州，夜感一梦：梦见身卧雪地，群虎来咬。惊惧而觉，心中疑惑，聚帐下将佐，告说梦中之事。帐下一人应声曰：“此梦乃不祥之兆也。”众视其人，乃帐前心腹校尉，姓庞，名德，字令明。超问：“令明所见若何？”德曰：“雪地遇虎，梦兆殊恶。莫非老将军在许昌有事否？”言未毕，一人踉跄而入，哭拜于地曰：“叔父与弟皆死矣！”超视之，乃马岱也。超惊问何为。岱曰：“叔父与侍郎黄奎同谋杀操，不幸事泄，皆被斩于市，二弟亦遇害。惟岱扮作客商，星夜走脱。超闻言，哭倒于地。众将救起。超咬牙切齿，痛恨操贼。忽报荆州刘皇叔遣人赍书至。超拆视之。书略曰：“伏念汉室不幸，操贼专权，欺君罔上，黎民凋残。备昔与令先君同受密诏，誓诛此贼。今令先君被操所害，此将军不共天地、不同日月之仇也。若能率西凉之兵，以攻操之右，备当举荆襄之众，以遏操之前：则逆操可擒，奸党可灭，仇辱可报，汉室可兴矣。书不尽言，立待回音。”
马超看毕，即时挥涕回书，发使者先回，随后便起西凉军马，正欲进发，忽西凉太守韩遂使人请马超往见。超至遂府，遂将出曹操书示之。内云：“若将马超擒赴许都，即封汝为西凉侯。”超拜伏于地曰：“请叔父就缚俺兄弟二人，解赴许昌，免叔父戈戟之劳。”韩遂扶起曰：“吾与汝父结为兄弟，安忍害汝？汝若兴兵，吾当相助。”马超拜谢。
韩遂便将操使者推出斩之，乃点手下八部军马，一同进发。那八部？乃侯选、程银、李堪、张横、梁兴、成宜、马玩、杨秋也。八将随着韩遂，合马超手下庞德、马岱，共起二十万大兵，杀奔长安来。
长安郡守钟繇，飞报曹操；一面引军拒敌，布阵于野。西凉州前部先锋马岱，引军一万五千，浩浩荡荡，漫山遍野而来。钟繇出马答话。岱使宝刀一口，与繇交战。不一合，繇大败奔走。岱提刀赶来。马超、韩遂引大军都到，围住长安。钟繇上城守护。长安乃西汉建都之处，城郭坚固。壕堑险深，急切攻打不下。一连围了十日，不能攻破。庞德进计曰：“长安城中土硬水碱，甚不堪食，更兼无柴。今围十日，军民饥荒。不如暂且收军，只须如此如此，长安唾手可得。”马超曰：“此计大妙！”即时差“令”字旗传与各部，尽教退军，马超亲自断后。各部军马渐渐退去。钟繇次日登城看时，军皆退了，只恐有计；令人哨探，果然远去，方才放心。纵令军民出城打柴取水，大开城门，放人出入。至第五日，人报马超兵又到，军民竞奔入城，钟繇仍复闭城坚守。
却说钟繇弟钟进，守把西门，约近三更，城门里一把火起。钟进急来救时，城边转过一人，举刀纵马大喝曰：“庞德在此！”钟进措手不及，被庞德一刀斩于马下，杀散军校，斩关断锁，放马超、韩遂军马入城。钟繇从东门弃城而走。马超、韩遂得了城池，赏劳三军。
钟繇退守潼关，飞报曹操。操知失了长安，不敢复议南征，遂唤曹洪、徐晃分付：“先带一万人马，替钟繇紧守潼关。如十日内失了关隘，皆斩；十日外，不干汝二人之事。我统大军随后便至。”二人领了将令，星夜便行。曹仁谏曰：“洪性躁，诚恐误事。”操曰：“你与我押送粮草，便随后接应。”
却说曹洪、徐晃到潼关，替钟繇坚守关隘，并不出战。马超领军来关下，把曹操三代毁骂。曹洪大怒，要提兵下关厮杀。徐晃谏曰：“此是马超要激将军厮杀，切不可与战。待丞相大军来，必有主画。”马超军日夜轮流来骂。曹洪只要厮杀，徐晃苦苦挡住。至第九日，在关上看时，西凉军都弃马在于关前草地上坐；多半困乏，就于地上睡卧。曹洪便教备马，点起三千兵杀下关来。西凉兵弃马抛戈而走。洪迤逦追赶。时徐晃正在关上点视粮车，闻曹洪下关厮杀，大惊，急引兵随后赶来，大叫曹洪回马。忽然背后喊声大震，马岱引军杀至。曹洪、徐晃急回走时，一棒鼓响，山背后两军截出：左是马超、右是庞德，混杀一阵。曹洪抵挡不住，折军大半，撞出重围，奔到关上。西凉兵随后赶来，洪等弃关而走。庞德直追过潼关，撞见曹仁军马，救了曹洪等一军。马超接应庞德上关。
曹洪失了潼关。奔见曹操。操曰：“与你十日限，如何九日失了潼关？”洪曰：“西凉军兵，百般辱骂，因见彼军懈怠，乘势赶去，不想中贼奸计。”操曰：“洪年幼躁暴，徐晃你须晓事！”晃曰：“累谏不从。当日晃在关上点粮车，比及知道，小将军已下关了。晃恐有失，连忙赶去，已中贼奸计矣。”操大怒，喝斩曹洪。众官告免。曹洪服罪而退。
操进兵直叩潼关。曹仁曰：“可先下定寨栅，然后打关未迟。”操令砍伐树木，起立排栅，分作三寨：左寨曹仁，右寨夏侯渊，操自居中寨。次日，操引三寨大小将校，杀奔关隘前去，正遇西凉军马。两边各布阵势。操出马于门旗下，看西凉之兵，人人勇健，个个英雄。又见马超生得面如傅粉，唇若抹朱，腰细膀宽，声雄力猛，白袍银铠，手执长枪，立马阵前；上首庞德，下首马岱。操暗暗称奇，自纵马谓超曰：“汝乃汉朝名将子孙，何故背反耶？”超咬牙切齿，大骂：“操贼！歉君罔上，罪不容诛！害我父弟，不共戴天之仇！吾当活捉生啖汝肉！”说罢，挺枪直杀过来。曹操背后于禁出迎。两马交战，斗得八九合，于禁败走。张郃出迎，战二十合亦败走。李通出迎，超奋威交战，数合之中，一枪刺李通于马下。超把枪望后一招，西凉兵一齐冲杀过来。操兵大败。西凉兵来得势猛，左右将佐，皆抵当不住。马超、庞德、马岱引百余骑，直入中军来捉曹操。操在乱军中，只听得西凉军大叫：“穿红袍的是曹操！”操就马上急脱下红袍。又听得大叫：“长髯者是曹操！”操惊慌，掣所佩刀断其髯。军中有人将曹操割髯之事，告知马超，超遂令人叫拿：“短髯者是曹操！”操闻知，即扯旗角包颈而逃。后人有诗曰：“潼关战败望风逃，孟德怆惶脱锦袍。剑割髭髯应丧胆，马超声价盖天高。”
曹操正走之间，背后一骑赶来，回头视之，正是马超。操大惊。左右将校见超赶来，各自逃命，只撤下曹操。超厉声大叫曰：“曹操休走！”操惊得马鞭坠地。看看赶上，马超从后使枪搠来。操绕树而走，超一枪搠在树上；急拔下时，操已走远。超纵马赶来，山坡边转过一将，大叫：“勿伤吾主！曹洪在此！”轮刀纵马，拦住马超。操得命走脱。洪与马超战到四五十合，渐渐刀法散乱，气力不加。夏侯渊引数十骑随到。马超独自一人，恐被所算，乃拨马而回，夏侯渊也不来赶。
曹操回寨，却得曹仁死据定了寨栅，因此不曾多折军马。操入帐叹曰：“吾若杀了曹洪，今日必死于马超之手也！”遂唤曹洪，重加赏赐。收拾败军，坚守寨栅，深沟高垒，不许出战。超每日引兵来寨前辱骂搦战。操传令教军士坚守，如乱动者斩。诸将曰：“西凉之兵，尽使长枪，当选弓弩迎之。”操曰：“战与不战，皆在于我，非在贼也。贼虽有长枪，安能便刺？诸公但坚壁观之，贼自退矣。”诸将皆私相议曰：“丞相自来征战，一身当先；今败于马超，何如此之弱也？”
过了几日，细作报来：“马超又添二万生力兵来助战，乃是羌人部落。”操闻知大喜。诸将曰：“马超添兵，丞相反喜。何也？”操曰：“待吾胜了，却对汝等说。”三日后又报关上又添军马。操又大喜，就于帐中设宴作贺。诸将皆暗笑。操曰：“诸公笑我无破马超之谋，公等有何良策？”徐晃进曰：“今丞相盛兵在此，贼亦全部现屯关上，此去河西，必无准备；若得一军暗渡蒲阪津，先截贼归路，丞相径发河北击之，贼两不相应，势必危矣。”操曰：“公明之言，正合吾意。”便教徐晃引精兵四千，和朱灵同去径袭河西，伏于山谷之中，“待我渡河北同时击之。”徐晃、朱灵领命、先引四千军暗暗去了。操下令，先教曹洪于蒲阪津，安排船筏。留曹仁守寨，操自领兵渡渭河。早有细作报知马超。超曰：“今操不攻潼关，而使人准备船筏，欲渡河北，必将遏吾之后。吾当引一军循河拒住岸北。操兵不得渡，不消二十日，河东粮尽，操兵必乱，却循河南而击之，操可擒矣。”韩遂曰：“不必如此。岂不闻兵法有云：‘兵半渡可击，’待操兵渡至一半，汝却于南岸击之，操兵皆死于河内矣。超曰：“叔父之言甚善。”即使人探听曹操几时渡河。却说曹操整兵已毕，分三停军，前渡渭河，比及人马到河口时，日光初起。操先发精兵渡过北岸，开创营寨。操自引亲随护卫军将百人，按剑坐于南岸，看军渡河。忽然人报：“后边白袍将军到了！”众皆认得是马超。一拥下船。河边军争上船者，声喧不止。操犹坐而不动，按剑指约休闹。只听得人喊马嘶，蜂拥而来，船上一将跃身上岸，呼曰：“贼至矣！请丞相下船！”操视之，乃许褚也。操口内犹言：“贼至何妨？”回头视之，马超已离不得百余步，许褚拖操下船时，船已离岸一丈有余，褚负操一跃上船。随行将士尽皆下水，扳住船边，争欲上船逃命。船小将翻，褚掣刀乱砍，傍船手尽折，倒于水中。急将船望下水棹去。许褚立于梢上。忙用木篙撑之。操伏在许褚脚边。马超赶到河岸，见船已流在半河，遂拈弓搭箭，喝令骁将绕河射之。矢如雨急。褚恐伤曹操，以左手举马鞍遮之。马超箭不虚发，船上驾舟之人，应弦落水；船中数十人皆被射倒。其船反撑不定，于急水中旋转。许褚独奋神威，将两腿夹舵摇撼，一手使篙撑船，一手举鞍遮护曹操。时有渭南县令丁斐，在南山之上，见马超追操甚急，恐伤操命，遂将寨内牛只马匹，尽驱于外，漫山遍野，皆是牛马。西凉兵见之。都回身争取牛马，无心追赶，曹操因此得脱。方到北岸，便把船筏凿沉。诸将听得曹操在河中逃难，急来救时，操已登岸。许褚身被重铠，箭皆嵌在甲上。众将保操至野寨中，皆拜于地而问安。操大笑曰：“我今日几为小贼所困！”褚曰；“若非有人纵马放牛以诱贼，贼必努力渡河矣。”操问曰：“诱贼者谁也？”有知者答曰：“渭南县令丁斐也。”少顷，斐入见。操谢曰：“若非公之良谋，则吾被贼所擒矣。”遂命为典军校尉，斐曰：“贼虽暂去，明日必复来。须以良策拒之。”操曰：“吾已准备了也。”遂唤诸将各分头循河筑起甬道，暂为寨脚，贼若来时，陈兵于甬道外。内虚立旌旗，以为疑兵；更沿河掘下壕堑，虚土棚盖，河内以兵诱之：“贼急来必陷，贼陷便可击矣。”却说马超回见韩遂，说：“几乎捉住曹操！有一将奋勇负操下船去了，不知何人。”遂曰：“吾闻曹操选极精壮之人，为帐前侍卫，名曰虎卫军，以骁将典韦、许褚领之。典韦已死，今救曹操者，必许褚也。此人勇力过人，人皆称为虎痴；如遇之。不可轻敌。”超曰：“吾亦闻其名久矣。”遂曰：“今操渡河，将袭我后。可速攻之。不可令他创立营寨。若立营寨，急难剿除。”超曰：“以侄愚意。还只拒住北岸。使彼不得渡河，乃为上策。”遂曰：“贤侄守寨，吾引军循河战操，若何？”超曰：“令庞德为先锋，跟叔父前去。”
于是韩遂与庞德将兵五万，直抵渭南。操令众将于甬道两旁诱之。庞德先引铁骑千余，冲突而来。喊声起处，人马俱落于陷马坑内。庞德踊身一跳。跃出土坑，立于平地，立杀数人，步行砍出重围。韩遂已被困在垓心，庞德步行救之。正遇着曹仁部将曹永，被庞德一刀砍于马下，夺其马，杀开一条血路，救出韩遂，投东南而走。背后曹兵赶来，马超引军接应，杀败曹兵，复救出大半军马。战至日暮方回。计点人马，折了将佐程银、张横，陷坑中死者二百余人。超与韩遂商议：“若迁延日久，操于河北立了营寨，难以退敌；不若乘今夜引轻骑去劫野营。”遂曰：“须分兵前后相救。”于是超自为前部，令庞德、马岱为后应，当夜便行。
却说曹操收兵屯渭北，唤诸将曰：“贼欺我未立寨栅，必来劫野营。可四散伏兵，虚其中军。号炮响时，伏兵尽起，一鼓可擒也。”众将依令，伏兵已毕。当夜，马超却先使成宜引三十骑往前哨探，成宜见无人马，径入中军。操军见西凉兵到，遂放号炮。四面伏兵皆出，只围得三十骑。成宜被夏侯渊所杀。马超却自从背后与庞德、马岱兵分三路蜂拥杀来。正是：纵有伏兵能候敌，怎当健将共争先？
未知胜负若何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943837, '5b9b6cb99f54540039b84edd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639197, '三国演义 · 第五十九回 · 许诸裸衣斗马超 曹操抹书问韩遂', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说当夜两兵混战，直到天明，各自收兵。马超屯兵渭口，日夜分兵，前后攻击。曹操在渭河内将船筏锁链作浮桥三条，接连南岸。曹仁引军夹河立寨，将粮草车辆穿连，以为屏障。马超闻之，教军士各挟草一束，带着火种，与韩遂引军并力杀到寨前，堆积草把，放起烈火。操兵抵敌不住，弃寨而走。车乘、浮桥，尽被烧毁。西凉兵大胜，截住渭河。曹操立不起营寨，心中忧惧。荀攸曰：“可取渭河沙土筑起土城，可以坚守。”操拨三万军担土筑城。马超又差庞德、马岱各引五百马军，往来冲突；更兼沙土不实，筑起便倒，操无计可施。时当九月尽，天气暴冷，彤云密布，连日不开。曹操在寨中纳闷。忽人报曰：“有一老人来见丞相，欲陈说方略。”操请入。见其人鹤骨松姿，形貌苍古。问之，乃京兆人也，隐居终南山，姓娄，名子伯，道号“梦梅居士”。操以客礼待之。子伯曰：“丞相欲跨渭安营久矣，今何不乘时筑之？”操曰：“沙土之地，筑垒不成。隐士有何良策赐教？”子伯曰：“丞相用兵如神，岂不知天时乎？连日阴云布合，朔风一起，必大冻矣。风起之后，驱兵士运土泼水，比及天明，土城已就。”操大悟，厚赏子伯。子伯不受而去。
是夜北风大作。操尽驱兵士担土泼水；为无盛水之具，作缣囊盛水浇之，随筑随冻。比及天明，沙水冻紧，土城已筑完。细作报知马超。超领兵观之，大惊，疑有神助。次日，集大军鸣鼓而进。操自乘马出营，止有许褚一人随后。操扬鞭大呼曰：“孟德单骑至此，请马超出来答话。”超乘马挺枪而出。操曰：“汝欺我营寨不成，今一夜天已筑就，汝何不早降！”马超大怒，意欲突前擒之，见操背后一人，睁圆怪眼，手提钢刀，勒马而立。超疑是许褚，乃扬鞭问曰：“闻汝军中有虎侯，安在哉？”许褚提刀大叫曰：“吾即谯郡许褚也！”目射神光，威风抖擞。超不敢动，乃勒马回。操亦引许褚回寨。两军观之，无不骇然。操谓诸将曰：“贼亦知仲康乃虎侯也！”自此军中皆称褚为虎侯，许褚曰：“某来日必擒马超。”操曰：“马超英勇，不可轻敌。”褚曰：“某誓与死战！”即使人下战书，说虎侯单搦马超来日决战。超接书大怒曰：“何敢如此相欺耶！”即批次日誓杀“虎痴”。
次日，两军出营布成阵势。超分庞德为左翼，马岱为右翼，韩遂押中军。超挺枪纵马，立于阵前，高叫：“虎痴快出！”曹操在门旗下回顾众将曰：“马超不减吕布之勇！”言未绝，许褚拍马舞刀而出。马超挺枪接战。斗了一百余合，胜负不分。马匹困乏，各回军中，换了马匹，又出阵前。又斗一百余合，不分胜负。许褚性起，飞回阵中，卸了盔甲，浑身筋突，赤体提刀，翻身上马，来与马超决战。两军大骇。两个又斗到三十余合，褚奋威举刀便砍马超。超闪过，一枪望褚心窝刺来。褚弃刀将枪挟住。两个在马上夺枪。许诸力大，一声响，拗断枪杆，各拿半节在马上乱打。操恐褚有失，遂令夏侯渊、曹洪两将齐出夹攻。庞德、马岱见操将齐出，麾两翼铁骑，横冲直撞，混杀将来。操兵大乱。许褚臂中两箭。诸将慌退入寨。马超直杀到壕边，操兵折伤大半。操令坚闭休出。马超回至渭口，谓韩遂曰：“吾见恶战者莫如许褚，真‘虎痴’也。”
却说曹操料马超可以计破，乃密令徐晃、朱灵尽渡河西结营，前后夹攻。一日，操于城上见马超引数百骑，直临寨前，往来如飞。操观良久，掷兜鍪于地曰：“马儿不死，吾无葬地矣！”夏侯渊听了，心中气忿，厉声曰：“吾宁死于此地，誓灭马贼！”遂引本部千余人，大开寨门，直赶去。操急止不住，恐其有失，慌自上马前来接应。马超见曹兵至，乃将前军作后队，后队作先锋，一字儿摆开。夏侯渊到，马超接往厮杀。超于乱军中遥见曹操，就撇了夏侯渊，直取曹操。操大惊，拨马而走。曹兵大乱。
正追之际，忽报操有一军，已在河西下了营寨，超大惊，无心追赶，急收军回寨，与韩遂商议，言：“操兵乘虚已渡河西，吾军前后受敌，如之奈何？”部将李堪曰：“不如割地请和，两家且各罢兵，捱过冬天，到春暖别作计议。”韩遂曰：“李堪之言最善，可从之。”
超犹豫未决。杨秋、侯选皆劝求和，于是韩遂遣杨秋为使，直往操寨下书，言割地请和之事。操曰：“汝且回寨，吾来日使人回报。”杨秋辞去。贾诩入见操曰：“丞相主意若何？”操曰：“公所见若何？”诩曰：“兵不厌诈，可伪许之；然后用反间计，令韩、马相疑，则一鼓可破也。”操抚掌大喜曰：“天下高见，多有相合。文和之谋，正吾心中之事也。”于是遣人回书，言：“待我徐徐退兵，还汝河西之地。”一面教搭起浮桥，作退军之意。马超得书，谓韩遂曰：“曹操虽然许和，奸雄难测。倘不准备，反受其制。超与叔父轮流调兵，今日叔向操，超向徐晃；明日超向操，叔向徐晃：分头提备，以防其诈。”韩遂依计而行。
早有人报知曹操。操顾贾诩曰：“吾事济矣！”问：“来日是谁合向我这边？”人报曰：“韩遂。”次日，操引众将出营，左右围绕，操独显一骑于中央。韩遂部卒多有不识操者，出阵观看。操高叫曰：“汝诸军欲观曹公耶？吾亦犹人也，非有四目两口，但多智谋耳。”诸军皆有惧色。操使人过阵谓韩遂曰：“丞相谨请韩将军会话。”韩遂即出阵；见操并无甲仗，亦弃衣甲，轻服匹马而出。二人马头相交，各按辔对语。操曰：“吾与将军之父，同举孝廉，吾尝以叔事之。吾亦与公同登仕路，不觉有年矣。将军今年妙龄几何？”韩遂答曰：“四十岁矣。”操曰：“往日在京师，皆青春年少，何期又中旬矣！安得天下清平共乐耶！”只把旧事细说，并不提起军情。说罢大笑，相谈有一个时辰，方回马而别，各自归寨。早有人将此事报知马超。超忙来问韩遂曰：“今日曹操阵前所言何事？”遂曰：“只诉京师旧事耳。”超曰：“安得不言军务乎？”遂曰：“曹操不言，吾何独言之？”超心甚疑，不言而退。
却说曹操回寨，谓贾诩曰：“公知吾阵前对语之意否？”诩曰：“此意虽妙，尚未足间二人。某有一策，令韩、马自相仇杀。”操问其计。贾诩曰：“马超乃一勇之夫，不识机密。丞相亲笔作一书，单与韩遂，中间朦胧字样，于要害处，自行涂抹改易，然后封送与韩遂，故意使马超知之。超必索书来看。若看见上面要紧去处，尽皆改抹，只猜是韩遂恐超知甚机密事，自行改抹，正合着单骑会语之疑；疑则必生乱。我更暗结韩遂部下诸将，使互相离间，超可图矣。”操曰：“此计甚妙。”随写书一封，将紧要处尽皆改抹，然后实封，故意多遣从人送过寨去，下了书自回。果然有人报知马超。超心愈疑，径来韩遂处索书看。韩遂将书与超。超见上面有改抹字样，问遂曰：“书上如何都改抹糊涂？”遂曰：“原书如此，不知何故。”超曰：“岂有以草稿送与人耶？必是叔父怕我知了详细，先改抹了。”遂曰：“莫非曹操错将草稿误封来了。”超曰：“吾又不信。曹操是精细之人，岂有差错？吾与叔父并力杀贼，奈何忽生异心？”遂曰：“汝若不信吾心，来日吾在阵前赚操说话，汝从阵内突出，一枪刺杀便了。”超曰：“若如此，方见叔父真心。”两人约定。次日，韩遂引侯选、李堪、梁兴、马玩、杨秋五将出阵。马超藏在门影里。韩遂使人到操寨前，高叫：“韩将军请丞相攀话。”操乃令曹洪引数十骑径出阵前与韩遂相见。马离数步，洪马上欠身言曰：“夜来丞相拜意将军之言，切莫有误。”言讫便回马。超听得大怒，挺枪骤马，便刺韩遂。五将拦住，劝解回寨。遂曰：“贤侄休疑，我无歹心。”马超那里肯信，恨怨而去。韩遂与五将商议曰：“这事如何解释？”杨秋曰：“马超倚仗武勇，常有欺凌主公之心，便胜得曹操，怎肯相让？以某愚见，不如暗投曹公，他日不失封侯之位。”遂曰：“吾与马腾结为兄弟，安忍背之？”杨秋曰：“事已至此，不得不然。”遂曰：“谁可以通消息？”杨秋曰：“某愿往。”遂乃写密书，遣杨秋径来操寨，说投降之事。操大喜，许封韩遂为西凉侯、杨秋为西凉太守。其余皆有官爵。约定放火为号，共谋马超。杨秋拜辞，回见韩遂，备言其事：“约定今夜放火，里应外合。”遂大喜，就令军士于中军帐后堆积干柴，五将各悬刀剑听候，韩遂商议，欲设宴赚请马超，就席图之，犹豫未去。不想马超早已探知备细，便带亲随数人，仗剑先行，令庞德、马岱为后应。超潜步入韩遂帐中，只见五将与韩遂密语，只听得杨秋口中说道：“事不宜迟，可速行之！”超大怒，挥剑直入，大喝曰：“群贼焉敢谋害我！”众皆大惊。超一剑望韩遂面门剁去，遂慌以手迎之，左手早被砍落。五将挥刀齐出。超纵步出帐外，五将围绕混杀。超独挥宝剑，力敌五将。剑光明处，鲜血溅飞：砍翻马玩，剁倒梁兴，三将各自逃生。超复入帐中来杀韩遂时，已被左右救去。帐后一把火起，各寨兵皆动。超连忙上马，庞德、马岱亦至，互相混战。超领军杀出时，操兵四至：前有许褚，后有徐晃，左有夏侯渊，右有曹洪。西凉之兵，自相并杀。超不见了庞德、马岱，乃引百余骑，截于渭桥之上。天色微明，只见李堪领一军从桥下过，超挺枪纵马逐之。李堪拖枪而走。恰好于禁从马超背后赶来。禁开弓射马超。超听得背后弦响，急闪过，却射中前面李堪，落马而死。超回马来杀于禁，禁拍马走了。超回桥上住扎。操兵前后大至，虎卫军当先，乱箭夹射马超。超以枪拨之，矢皆纷纷落地。超令从骑往来突杀。争奈曹兵围裹坚厚，不能冲出。超于桥上大喝一声，杀入河北，从骑皆被截断。超独在阵中冲突，却被暗弩射倒坐下马，马超堕于地上，操军逼合。正在危急，忽西北角上一彪军杀来，乃庞德、马岱也。二人救了马超，将军中战马与马超骑了，翻身杀条血路，望西北而走。曹操闻马超走脱，传令诸将：“无分晓夜，务要赶到马儿。如得首级者，千金赏，万户侯；生获者封大将军。”众将得令，各要争功，迤逦追袭。马超顾不得人马困乏，只顾奔走。从骑渐渐皆散。步兵走不上者，多被擒去。止剩得三十余骑，与庞德、马岱望陇西临洮而去。
曹操亲自追至安定，知马超去远，方收兵回长安。众将毕集。韩遂已无左手，做了残疾之人，操教就于长安歇马，授西凉侯之职。杨秋、侯选皆封列侯，令守渭口。下令班师回许都。凉州参军杨阜，字义山，径来长安见操。操问之，杨阜曰：“马超有吕布之勇，深得羌人之心。今丞相若不乘势剿绝，他日养成气力，陇上诸郡，非复国家之有也。望丞相且休回兵。”操曰：“吾本欲留兵征之，奈中原多事，南方未定，不可久留。君当为孤保之。”阜领诺，又保荐韦康为凉州刺史，同领兵屯冀城，以防马超。阜临行，请于操曰：“长安必留重兵以为后援。”操曰：“吾已定下，汝但放心。”阜辞而去。
众将皆问曰：“初贼据潼关，渭北道缺，丞相不从河东击冯翊，而反守潼关，迁延日久，而后北渡，立营固守，何也？”操曰：“初贼守潼关，若吾初到，便取河东，贼必以各寨分守诸渡口，则河西不可渡矣。吾故盛兵皆聚于潼关前，使贼尽南守，而河西不准备，故徐晃、朱灵得渡也。吾然后引兵北渡，连车树栅为甬道，筑冰城，欲贼知吾弱，以骄其心，使不准备。吾乃巧用反间，畜士卒之力，一旦击破之。正所谓疾雷不及掩耳。兵之变化，固非一道也。”众将又请问曰：“丞相每闻贼加兵添众，则有喜色，何也？”操曰：“关中边远，若群贼各依险阻，征之非一二年不可平复；今皆来聚一处，其众虽多，人心不一，易于离间，一举可灭：吾故喜也。”众将拜曰：“丞相神谋，众不及也；”操曰：“亦赖汝众文武之力。”遂重赏诸军。留夏侯渊屯兵长安，所得降兵，分拨各部。夏侯渊保举冯翊高陵人，姓张，名既，字德容，为京兆尹，与渊同守长安。操班师回都。献帝排銮驾出郭迎接。诏操“赞拜不名，入朝不趋，剑履上殿”：如汉相萧何故事。自此威震中外。这消息播入汉中，早惊动了汉宁太守张鲁。原来张鲁乃沛国丰人。其祖张陵在西川鹄鸣山中造作道书以惑人，人皆敬之。陵死之后，其子张衡行之。百姓但有学道者，助米五斗。世号“米贼”。张衡死，张鲁行之。鲁在汉中自号为“师君”；其来学道者皆号为“鬼卒”；为首者号为“祭酒”；领众多者号为“治头大祭酒”。务以诚信为主，不许欺诈。如有病者，即设坛使病人居于静室之中，自思己过，当面陈首，然后为之祈祷；主祈祷之事者，号为“奸令祭酒”。祈祷之法，书病人姓名，说服罪之意，作文三通，名为“三官手书”：一通放于山顶以奏天，一通埋于地以奏地，一通沉于水以申水官。如此之后，但病痊可，将米五斗为谢。又盖义舍：舍内饭米、柴火、肉食齐备，许过往人量食多少，自取而食；多取者受天诛。境内有犯法者，必恕三次；不改者，然后施刑。所在并无官长，尽属祭酒所管。如此雄据汉中之地已三十年。国家以为地远不能征伐，就命鲁为镇南中郎将，领汉宁太守，通进贡而已。当年闻操破西凉之众，威震天下，乃聚众商议曰：“西凉马腾遭戮，马超新败，曹操必将侵我汉中。我欲自称汉宁王，督兵拒曹操，诸君以为何如？”阎圃曰：“汉川之民，户出十万余众，财富粮足，四面险固；今马超新败，西凉之民，从子午谷奔入汉中者，不下数万。愚意益州刘璋昏弱，不如先取西川四十一州为本，然后称王未迟。”张鲁大喜，遂与弟张卫商议起兵。早有细作报入川中。
却说益州刘璋，字季玉，即刘焉之子，汉鲁恭王之后。章帝元和中，徙封竟陵，支庶因居于此。后焉官至益州牧，兴平元年患病疽而死，州大吏赵韪等，共保璋为益州牧。璋曾杀张鲁母及弟，因此有仇。璋使庞羲为巴西太守，以拒张鲁。时庞羲探知张鲁欲兴兵取川，急报知刘璋。璋平生懦弱，闻得此信，心中大忧，急聚众官商议。忽一人昂然而出曰：“主公放心。某虽不才，凭三寸不烂之舌，使张鲁不敢正眼来觑西川。”正是：只因蜀地谋臣进，致引荆州豪杰来。
未知此人是谁，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943838, '5b9b6cd2fb4ffe005cafd0b2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639198, '三国演义 · 第六十回 · 张永年反难杨修 庞士元议取西蜀', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说那进计于刘璋者，乃益州别驾，姓张，名松，字永年。其人生得额？头尖，鼻偃齿露，身短不满五尺，言语有若铜钟。刘璋问曰：“别驾有何高见，可解张鲁之危？”松曰：“某闻许都曹操，扫荡中原，吕布、二袁皆为所灭，近又破马超，天下无敌矣。主公可备进献之物，松亲往许都，说曹操兴兵取汉中，以图张鲁。则鲁拒敌不暇，何敢复窥蜀中耶？”刘璋大喜，收拾金珠锦绮，为进献之物，遣张松为使。松乃暗画西川地理图本藏之，带从人数骑，取路赴许都。早有人报入荆州。孔明便使人入许都打探消息。
却说张松到了许都馆驿中住定，每日去相府伺候，求见曹操。原来曹操自破马超回，傲睨得志，每日饮宴，无事少出，国政皆在相府商议。张松候了三日，方得通姓名。左右近侍先要贿赂，却才引入。操坐于堂上，松拜毕，操问曰：“汝主刘璋连年不进贡，何也？”松曰：“为路途艰难，贼寇窃发，不能通进。”操叱曰：“吾扫清中原，有何盗贼？”松曰：“南有孙权，北有张鲁，西有刘备，至少者亦带甲十余万，岂得为太平耶？”操先见张松人物猥琐，五分不喜；又闻语言冲撞，遂拂袖而起，转入后堂。左右责松曰：“汝为使命，何不知礼，一味冲撞？幸得丞相看汝远来之面，不见罪责。汝可急急回去！”松笑曰：“吾川中无诌佞之人也。”忽然阶下一人大喝曰：“汝川中不会谄佞，吾中原岂有谄佞者乎？”
松观其人，单眉细眼，貌白神清。问其姓名，乃太尉杨彪之子杨修，字德祖，现为丞相门下掌库主簿。此人博学能言，智识过人。松知修是个舌辩之士，有心难之。修亦自恃其才，小觑天下之士。当时见张松言语讥讽，遂邀出外面书院中，分宾主而坐，谓松曰：“蜀道崎岖，远来劳苦。”松曰：“奉主之命，虽赴汤蹈火，弗敢辞也。”修问：“蜀中风土何如？”松曰：“蜀为西郡，古号益州。路有锦江之险，地连剑阁之雄。回还二百八程，纵横三万余里。鸡鸣犬吠相闻，市井闾阎不断。田肥地茂，岁无水旱之忧；国富民丰，时有管弦之乐。所产之物，阜如山积。天下莫可及也！”修又问曰：“蜀中人物如何？”松曰：“文有相如之赋，武有伏波之才；医有仲景之能，卜有君平之隐。九流三教，出乎其类，拔乎其萃者，不可胜记，岂能尽数！”修又问曰：“方今刘季玉手下，如公者还有几人？”松曰：“文武全才，智勇足备，忠义慷慨之士，动以百数。如松不才之辈，车载斗量，不可胜记。”修曰：“公近居何职？”松曰：“滥充别驾之任，甚不称职。敢问公为朝廷何官？”修曰：“现为丞相府主簿。”松曰：“久闻公世代簪缨，何不立于庙堂，辅佐天子，乃区区作相府门下一吏乎？”杨修闻言，满面羞惭，强颜而答曰：“某虽居下寮，丞相委以军政钱粮之重，早晚多蒙丞相教诲，极有开发，故就此职耳。”松笑曰：“松闻曹丞相文不明孔、孟之道，武不达孙、吴之机，专务强霸而居大位，安能有所教诲，以开发明公耶？”修曰：“公居边隅，安知丞相大才乎？吾试令公观之。”呼左右于箧中取书一卷，以示张松。松观其题曰“孟德新书”。从头至尾，看了一遍，共一十三篇，皆用兵之要法。松看毕，问曰：“公以此为何书耶？”修曰：“此是丞相酌古准今，仿《孙子十三篇》而作。公欺丞相无才，此堪以传后世否？”松大笑曰：“此书吾蜀中三尺小童，亦能暗诵，何为‘新书’？此是战国时无名氏所作，曹丞相盗窃以为己能，止好瞒足下耳！”修曰：“丞相秘藏之书，虽已成帙，未传于世。公言蜀中小儿暗诵如流，何相欺乎？”松曰：“公如不信，吾试诵之。”遂将《孟德新书》，从头至尾，朗诵一遍，并无一字差错。修大惊曰：“公过目不忘，真天下奇才也！”后人有诗赞曰：“古怪形容异，清高体貌疏。语倾三峡水，目视十行书。胆量魁西蜀，文章贯太虚。百家并诸子，一览更无余。”
当下张松欲辞回。修曰：“公且暂居馆舍，容某再禀丞相，令公面君。”松谢而退。修入见操曰：“适来丞相何慢张松乎？”操曰：“言语不逊，吾故慢之。”修曰：“丞相尚容一祢衡，何不纳张松？”操曰：“祢衡文章，播于当今，吾故不忍杀之。松有何能？”修曰：“且无论其口似悬河，辩才无碍。适修以丞相所撰《孟德新书》示之，彼观一遍，即能暗诵，如此博闻强记，世所罕有。松言此书乃战国时无名氏所作，蜀中小儿，皆能熟记。”操曰：“莫非古人与我暗合否？”令扯碎其书烧之。修曰：“此人可使面君，教见天朝气象。”操曰：“来日我于西教场点军，汝可先引他来，使见我军容之盛，教他回去传说：吾即日下了江南，便来收川。”修领命。
至次日，与张松同至西教场。操点虎卫雄兵五万，布于教场中。果然盔甲鲜明，衣袍灿烂；金鼓震天，戈矛耀日；四方八面，各分队伍；旌旗扬彩，人马腾空。松斜目视之。良久，操唤松指而示曰：“汝川中曾见此英雄人物否？”松曰：“吾蜀中不曾见此兵革，但以仁义治人。”操变色视之。松全无惧意。杨修频以目视松。操谓松曰：“吾视天下鼠辈犹草芥耳。大军到处，战无不胜，攻无不取，顺吾者生，逆吾者死。汝知之乎？”松曰：“丞相驱兵到处，战必胜，攻必取，松亦素知。昔日濮阳攻吕布之时，宛城战张绣之日；赤壁遇周郎，华容逢关羽；割须弃袍于潼关，夺船避箭于渭水：此皆无敌于天下也！”操大怒曰：“竖儒怎敢揭吾短处！”喝令左右推出斩之。杨修谏曰：“松虽可斩，奈从蜀道而来入贡，若斩之，恐失远人之意。”操怒气未息。荀彧亦谏。操方免其死，令乱棒打出。松归馆舍，连夜出城，收拾回川。松自思曰：“吾本欲献西川州郡与曹操，谁想如此慢人！我来时于刘璋之前，开了大口；今日怏怏空回。须被蜀中人所笑。吾闻荆州刘玄德仁义远播久矣，不如径由那条路回。试看此人如何，我自有主见。”于是乘马引仆从望荆州界上而来，前至郢州界口，忽见一队军马，约有五百余骑，为首一员大将，轻妆软扮，勒马前问曰：“来者莫非张别驾乎？”松曰：“然也。”那将慌忙下马，声喏曰：“赵云等候多时。”松下马答礼曰：“莫非常山赵子龙乎？”云曰：“然也，某奉主公刘玄德之命，为大夫远涉路途，鞍马驱驰，特命赵云聊奉酒食。”言罢，军士跪奉酒食，云敬进之。松自思曰：“人言刘玄德宽仁爱客，今果如此。”遂与赵云饮了数杯，上马同行。来到荆州界首，是日天晚，前到馆驿，见驿门外百余人侍立，击鼓相接。一将于马前施礼曰：“奉兄长将令，为大夫远涉风尘，令关某洒扫驿庭，以待歇宿。”松下马，与云长、赵云同入馆舍。讲礼叙坐。须臾，排上酒筵，二人殷勤相劝。饮至更阑，方始罢席，宿了一宵。
次日早膳毕，上马行不到三五里，只见一簇人马到。乃是玄德引着伏龙、凤雏，亲自来接。遥见张松，早先下马等候。松亦慌忙下马相见。玄德曰：“久闻大夫高名，如雷灌耳。恨云山遥远，不得听教。今闻回都，专此相接。倘蒙不弃，到荒州暂歇片时，以叙渴仰之思，实为万幸！”松大喜，遂上马并辔入城。至府堂上各各叙礼，分宾主依次而坐，设宴款待。饮酒间，玄德只说闲话，并不提起西川之事。松以言挑之曰：“今皇叔守荆州，还有几郡？”孔明答曰：“荆州乃暂借东吴的，每每使人取讨。今我主因是东吴女婿，故权且在此安身。”松曰：“东吴据六郡八十一州，民强国富，犹且不知足耶？”庞统曰：“吾主汉朝皇叔，反不能占据州郡；其他皆汉之蟊贼，却都恃强侵占地土；惟智者不平焉。”玄德曰：“二公休言。吾有何德，敢多望乎？”松曰：“不然。明公乃汉室宗亲，仁义充塞乎四海。休道占据州郡，便代正统而居帝位，亦非分外。”玄德拱手谢曰：“公言太过，备何敢当！”
自此一连留张松饮宴三日，并不提起川中之事。松辞去，玄德于十里长亭设宴送行。玄德举酒酌松曰：“甚荷大夫不外，留叙三日；今日相别，不知何时再得听教。”言罢，潸然泪下。张松自思：“玄德如此宽仁爱士，安可舍之？不如说之，令取西川。”乃言曰：“松亦思朝暮趋侍，恨未有便耳。松观荆州：东有孙权，常怀虎踞；北有曹操，每欲鲸吞。亦非可久恋之地也。”玄德曰：“故知如此，但未有安迹之所。”松曰：“益州险塞，沃野千里，民殷国富；智能之士，久慕皇叔之德。若起荆襄之众，长驱西指，霸业可成，汉室可兴矣。”玄德曰：“备安敢当此？刘益州亦帝室宗亲，恩泽布蜀中久矣。他人岂可得而动摇乎？”松曰：“某非卖主求荣；今遇明公，不敢不披沥肝胆：刘季玉虽有益州之地，禀性暗弱，不能任贤用能；加之张鲁在北，时思侵犯；人心离散，思得明主。松此一行，专欲纳款于操；何期逆贼恣逞奸雄，傲贤慢士，故特来见明公。明公先取西川为基，然后北图汉中，收取中原，匡正天朝，名垂青史，功莫大焉。明公果有取西川之意，松愿施犬马之劳，以为内应。未知钧意若何？”玄德曰：“深感君之厚意。奈刘季玉与备同宗，若攻之，恐天下人唾骂。”松曰：“大丈夫处世，当努力建功立业，着鞭在先。今若不取，为他人所取，悔之晚矣。”玄德曰：“备闻蜀道崎岖，千山万水，车不能方轨，马不能联辔；虽欲取之，用何良策？”松于袖中取出一图，递与玄德曰：“松感明公盛德，敢献此图。但看此图，便知蜀中道路矣。”玄德略展视之，上面尽写着地理行程，远近阔狭，山川险要，府库钱粮，一一俱载明白。松曰：“明公可速图之。松有心腹契友二人：法正、孟达。此二人必能相助。如二人到荆州时，可以心事共议。”玄德拱手谢曰：“青山不老，绿水长存。他日事成，必当厚报。”松曰：“松遇明主，不得不尽情相告，岂敢望报乎？”说罢作别。孔明命云长等护送数十里方回。张松回益州，先见友人法正。正字孝直，右扶风郿人也，贤士法真之子。松见正，备说曹操轻贤傲士，只可同忧，不可同乐。吾已将益州许刘皇叔矣。专欲与兄共议。法正曰：“吾料刘璋无能，已有心见刘皇叔久矣。此心相同，又何疑焉？”少顷，孟达至。达字子庆，与法正同乡。达入，见正与松密语。达曰：“吾已知二公之意。将欲献益州耶？”松曰：“是欲如此。兄试猜之，合献与谁？”达曰：“非刘玄德不可。”三人抚掌大笑。法正谓松曰：“兄明日见刘璋，当若何？”松曰：“吾荐二公为使，可往荆州。”二人应允。
次日，张松见刘璋。璋问：“干事若何？”松曰：“操乃汉贼，欲篡天下，不可为言。彼已有取川之心。”璋曰：“似此如之奈何？”松曰；“松有一谋，使张鲁、曹操必不敢轻犯西川。”璋曰：“何计？”松曰：“荆州刘皇叔，与主公同宗，仁慈宽厚，有长者风。赤壁鏖兵之后，操闻之而胆裂，何况张鲁乎？”主公何不遣使结好，使为外援，可以拒曹操、张鲁矣。”璋曰：“吾亦有此心久矣。谁可为使？”松曰：“非法正、孟达，不可往也。”璋即召二人入，修书一封，令法正为使，先通情好；次遣孟达领精兵五千，迎玄德入川为援。正商议间，一人自外突入，汗流满面，大叫曰：“主公若听张松之言，则四十一州郡，已属他人矣！”松大惊；视其人，乃西阆中巴人，姓黄，名权，字公衡，现为刘璋府下主簿。璋问曰：“玄德与我同宗，吾故结之为援；汝何出此言？”权曰：“某素知刘备宽以待人，柔能克刚，英雄莫敌；远得人心，近得民望；兼有诸葛亮、庞统之智谋，关、张、赵云、黄忠、魏延为羽翼。若召到蜀中，以部曲待之，刘备安肯伏低做小？若以客礼待之，又一国不容二主。今听臣言，则西蜀有泰山之安；不听臣言，则主公有累卵之危矣。张松昨从荆州过，必与刘备同谋。可先斩张松，后绝刘备，则西川万幸也。”璋曰：“曹操、张鲁到来，何以拒之？”权曰：“不如闭境绝塞，深沟高垒，以待时清。”璋曰：“贼兵犯界，有烧眉之急；若待时清，则是慢计也。”遂不从其言，遣法正行。又一人阻曰：“不可！不可！”璋视之，乃帐前从事官王累也。累顿首言曰：“主公今听张松之说，自取其祸。”璋曰：“不然。吾结好刘玄德，实欲拒张鲁也。”累曰：“张鲁犯界，乃癣疥之疾；刘备入川，乃心腹之大患。况刘备世之枭雄，先事曹操，便思谋害；后从孙权，便夺荆州。心术如此，安可同处乎？”今若召来，西川休矣！”璋叱曰：“再休乱道！玄德是我同宗，他安肯夺我基业？”便教扶二人出。遂命法正便行。
法正离益州，径取荆州，来见玄德。参拜已毕，呈上书信。玄德拆封视之。书曰：“族弟刘璋，再拜致书于玄德宗兄将军麾下：久伏电天，蜀道崎岖，未及赍贡，甚切惶愧。璋闻吉凶相救，患难相扶，朋友尚然，况宗族乎？今张鲁在北，旦夕兴兵，侵犯璋界，甚不自安。专人谨奉尺书，上乞钧听。倘念同宗之情，全手足之义，即日兴师剿灭狂寇，永为唇齿，自有重酬。书不尽言，耑候车骑。”
玄德看毕大喜，设宴相待法正。酒过数巡，玄德屏退左右，密谓正曰：“久仰孝直英名，张别驾多谈盛德。今获听教，甚慰平生。”法正谢曰：“蜀中小吏，何足道哉！盖闻马逢伯乐而嘶，人遇知己而死。张别驾昔日之言，将军复有意乎？”玄德曰：“备一身寄客，未尝不伤感而叹息。尝思鹪鹩尚存一枝，狡兔犹藏三窟，何况人乎？蜀中丰余之地，非不欲取；奈刘季玉系备同宗，不忍相图。”法正曰：“益州天府之国，非治乱之主，不可居也，今刘季玉不能用贤，此业不久必属他人。今日自付与将军，不可错失。岂不闻逐兔先得之语乎？将军欲取，某当效死。”玄德拱手谢曰：“尚容商议。”
当日席散，孔明亲送法正归馆舍。玄德独坐沉吟。庞统进曰：“事当决而不决者，愚人也。主公高明，何多疑耶？”玄德问曰：“以公之意，当复何如？”统曰：“荆州东有孙权，北有曹操，难以得志。益州户口百万，土广财富，可资大业。今幸张松、法正为内助，此天赐也。何必疑哉？”玄德曰：“今与吾水火相敌者，曹操也。操以急，吾以宽；操以暴，吾以仁；操以谲，吾以忠：每与操相反，事乃可成。若以小利而失信义于天下，吾不忍也。”庞统笑曰：“主公之言，虽合天理，奈离乱之时，用兵争强，固非一道；若拘执常理，寸步不可行矣，宜从权变。且兼弱攻昧、逆取顺守，汤、武之道也。若事定之后，报之以义，封为大国，何负于信？今日不取，终被他人取耳。主公幸熟思焉。”玄德乃恍然曰：“金石之言，当铭肺腑。”于是遂请孔明，同议起兵西行。孔明曰：“荆州重地，必须分兵守之。”玄德曰：“吾与庞士元、黄忠、魏延前往西川；军师可与关云长、张翼德、赵子龙守荆州。”孔明应允。于是孔明总守荆州；关公拒襄阳要路，当青泥隘口；张飞领四郡巡江，赵云屯江陵，镇公安。玄德令黄忠为前部，魏延为后军，玄德自与刘封、关平在中军。庞统为军师，马步兵五万，起程西行。临行时，忽廖化引一军来降。玄德便教廖化辅佐云长以拒曹操。
是年冬月，引兵望西川进发。行不数程，孟达接着，拜见玄德，说刘益州令某领兵五千远来迎接。玄德使人入益州，先报刘璋。璋便发书告报沿途州郡，供给钱粮。璋欲自出涪城亲接玄德，即下令准备车乘帐幔，旌旗铠甲，务要鲜明。主簿黄权入谏曰：“主公此去，必被刘备之害，某食禄多年，不忍主公中他人奸计。望三思之！”张松曰：“黄权此言，疏间宗族之义，滋长寇盗之威，实无益于主公。”璋乃叱权曰：“吾意已决，汝何逆吾！”权叩首流血，近前口衔璋衣而谏。璋大怒，扯衣而起。权不放，顿落门牙两个。璋喝左右，推出黄权。权大哭而归。璋欲行，一人叫曰：“主公不纳黄公衡忠言，乃欲自就死地耶！”伏于阶前而谏。璋视之，乃建宁俞元人也，姓李，名恢。叩首谏曰：“窃闻君有诤臣，父有诤子。黄公衡忠义之言，必当听从。若容刘备入川，是犹迎虎于门也。”璋曰：“玄德是吾宗兄，安肯害吾？再言者必斩！”叱左右推出李恢。张松曰：“今蜀中文官各顾妻子，不复为主公效力；诸将恃功骄傲，各有外意。不得刘皇叔，则敌攻于外，民攻于内，必败之道也。”璋曰：“公所谋，深于吾有益。”次日，上马出榆桥门。人报从事王累，自用绳索倒吊于城门之上，一手执谏章，一手仗剑，口称如谏不从，自割断其绳索，撞死于此地。刘璋教取所执谏章观之。其略曰：“益州从事臣王累，泣血恳告：窃闻良药苦口利于病，忠言逆耳利于行。昔楚怀王不听屈原之言，会盟于武关，为秦所困。今主公轻离大郡，欲迎刘备于涪城，恐有去路而无回路矣。倘能斩张松于市，绝刘备之约，则蜀中老幼幸甚，主公之基业亦幸甚！”刘璋观毕，大怒曰：“吾与仁人相会，如亲芝兰，汝何数侮于吾耶！”王累大叫一声，自割断其索，撞死于地，后人有诗叹曰：“倒挂城门捧谏章，拚将一死报刘璋。黄权折齿终降备，矢节何如王累刚！”刘璋将三万人马往涪城来。后军装载资粮饯帛一千余辆，来接玄德。却说玄德前军已到垫江。所到之处，一者是西川供给；二者是玄德号令严明，如有妄取百姓一物者斩：于是所到之处，秋毫无犯。百姓扶老携幼，满路瞻观，焚香礼拜。玄德皆用好言抚慰。却说法正密谓庞统曰：“近张松有密书到此，言于涪城相会刘璋，便可图之。机会切不可失。”统曰：“此意且勿言。待二刘相见，乘便图之。若预走泄，于中有变。”法正乃秘而不言。涪城离成都三百六十里。璋已到，使人迎接玄德。两军皆屯于涪江之上。玄德入城，与刘璋相见，各叙兄弟之情。礼毕，挥泪诉告衷情。饮宴毕，各回寨中安歇。
璋谓众官曰：“可笑黄权、王累等辈，不知宗兄之心，妄相猜疑。吾今日见之，真仁义之人也。吾得他为外援，又何虑曹操、张鲁耶？非张松则失之矣。”乃脱所穿绿袍，并黄金五百两，令人往成都赐与张松。时部下将佐刘璝、泠苞、张任、邓贤等一班文武官曰：“主公且休欢喜。刘备柔中有刚，其心未可测，还宜防之。”璋笑曰：“汝等皆多虑。吾兄岂有二心哉！”众皆嗟叹而退。
却说玄德归到寨中。庞统入见曰：“主公今日席上见刘季玉动静乎？”玄德曰：“季玉真诚实人也。”统曰：“季玉虽善，其臣刘璝、张任等皆有不平之色，其间吉凶未可保也。以统之计，莫若来日设宴，请季玉赴席；于壁衣中埋伏刀斧手一百人，主公掷杯为号，就筵上杀之；一拥入成都，刀不出鞘，弓不上弦，可坐而定也。”玄德曰：“季玉是吾同宗，诚心待吾；更兼吾初到蜀中，恩信未立；若行此事，上天不容，下民亦怨。公此谋，虽霸者亦不为也。”统曰：“此非统之谋，是法孝直得张松密书，言事不宜迟，只在早晚当图之。”言未已，法正入见，曰：“某等非为自己，乃顺天命也。”玄德曰：“刘季玉与吾同宗，不忍取之。”正曰：“明公差矣。若不如此，张鲁与蜀有杀母之仇，必来攻取。明公远涉山川，驱驰士马，既到此地，进则有功，退则无益。若执狐疑之心，迁延日久，大为失计。且恐机谋一泄，反为他人所算。不若乘此天与人归之时，出其不意，早立基业，实为上策。”庞统亦再三相劝。正是：人主几番存厚道，才臣一意进权谋。
未知玄德心下如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943838, '5b9b6ce99f54540039b8514f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639199, '三国演义 · 第六十一回 · 赵云截江夺阿斗 孙权遗书退老瞒', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说庞统、法正二人，劝玄德就席间杀刘璋，西川唾手可得。玄德曰：“吾初入蜀中，恩信未立，此事决不可行。”二人再三说之，玄德只是不从。次日，复与刘璋宴于城中，彼此细叙衷曲，情好甚密。酒至半酣，庞统与法正商议曰：“事已至此，由不得主公了。”便教魏延登堂舞剑，乘势杀刘璋。延遂拔剑进曰：“筵间无以为乐，愿舞剑为戏。”庞统便唤众武士入，列于堂下，只待魏延下手。刘璋手下诸将，见魏延舞剑筵前，又见阶下武士手按刀靶，直视堂上，从事张任亦掣剑舞曰：“舞剑必须有对，某愿与魏将军同舞。”二人对舞于筵前。魏延目视刘封，封亦拔剑助舞。于是刘璝、泠苞、邓贤各掣剑出曰：“我等当群舞，以助一笑。”玄德大惊，急掣左右所佩之剑，立于席上曰：“吾兄弟相逢痛饮，并无疑忌。又非鸿门会上，何用舞剑？不弃剑者立斩！”刘璋亦叱曰：“兄弟相聚，何必带刀？”命侍卫者尽去佩剑。众皆纷然下堂。玄德唤诸将士上堂，以酒赐之，曰：“吾弟兄同宗骨血，共议大事，并无二心。汝等勿疑。”诸将皆拜谢。刘璋执玄德之手而泣曰：“吾兄之恩，誓不敢忘！”二人欢饮至晚而散。玄德归寨，责庞统曰：“公等奈何欲陷备于不义耶？今后断勿为此。”统嗟叹而退。却说刘璋归寨，刘璝等曰：“主公见今日席上光景乎？不如早回，免生后患。刘璋曰：“吾兄刘玄德，非比他人。”众将曰：“虽玄德无此心，他手下人皆欲吞并西川，以图富贵。”璋曰：“汝等无间吾兄弟之情。”遂不听，日与玄德欢叙。忽报张鲁整顿兵马，将犯葭萌关。刘璋便请玄德往拒之。玄德慨然领诺，即日引本部兵望葭萌关去了。众将劝刘璋令大将紧守各处关隘，以防玄德兵变。璋初时不从，后因众人苦劝，乃令白水都督杨怀、高沛二人，守把涪水关。刘璋自回成都。玄德到葭萌关，严禁军士，广施恩惠，以收民心。
早有细作报入东吴。吴侯孙权会文武商议。顾雍进曰：“刘备分兵远涉山险而去，未易往还。何不差一军先截川口，断其归路，后尽起东吴之兵，一鼓而下荆襄？此不可失之机会也。”权曰：“此计大妙！”正商议间，忽屏风后一人大喝而出曰：“进此计者可斩之！欲害吾女之命耶！”众惊视之，乃吴国太也。国太怒曰：“吾一生惟有一女，嫁与刘备。今若动兵，吾女性命如何！”因叱孙权曰：“汝掌父兄之业，坐领八十一州，尚自不足，乃顾小利而不念骨肉！”孙权喏喏连声，答曰：“老母之训，岂敢有违！”遂叱退众官。国太恨恨而入。孙权立于轩下，自思：“此机会一失，荆襄何日可得？”正沉吟间，只见张昭入问曰：“主公有何忧疑？”孙权曰：“正思适间之事。”张昭曰：“此极易也：今差心腹将一人，只带五百军。潜入荆州，下一封密书与郡主，只说国太病危，欲见亲女，取郡主星夜回东吴。玄德平生只有一子，就教带来。那时玄德定把荆州来换阿斗。如其不然，一任动兵，更有何碍？”权曰：“此计大妙！吾有一人，姓周，名善，最有胆量。自幼穿房入户，多随吾兄。今可差他去。”昭曰：“切勿漏泄。只此便令起行。”于是密遣周善，将五百人，扮为商人，分作五船；更诈修国书，以备盘诘；船内暗藏兵器。周善领命，取荆州水路而来。船泊江边，善自入荆州，令门吏报孙夫人。夫人命周善入。善呈上密书。夫人见说国太病危，洒泪动问。周善拜诉曰：“国太好生病重，旦夕只是思念夫人。倘去得迟，恐不能相见。就教夫人带阿斗去见一面。”夫人曰：“皇叔引兵远出，我今欲回，须使人知会军师，方可以行。”周善曰：“若军师回言道：须报知皇叔，候了回命，方可下船，如之奈何？”夫人曰：“若不辞而去，恐有阻当。”周善曰：“大江之中，已准备下船只。只今便请夫人上车出城。”孙夫人听知母病危急，如何不慌？便将七岁孩子阿斗，载在车中；随行带三十余人，各跨刀剑，上马离荆州城，便来江边上船。府中人欲报时，孙夫人已到沙头镇，下在船中了。
周善方欲开船，只听得岸上有人大叫：“且休开船，容与夫人饯行！”视之，乃赵云也。原来赵云巡哨方回，听得这个消息，吃了一惊，只带四五骑，旋风般沿江赶来。周善手执长戈，大喝曰：“汝何人，敢当主母！”叱令军士一齐开船，各将军器出来，摆列在船上。风顺水急，船皆随流而去。赵云沿江赶叫：“任从夫人去。只有一句话拜禀。”周善不睬，只催船速进。赵云沿江赶到十余里，忽见江滩斜缆一只渔船在那里。赵云弃马执枪，跳上渔船。只两人驾船前来，望着夫人所坐大船追赶。周善教军士放箭。赵云以枪拨之，箭皆纷纷落水。离大船悬隔丈余，吴兵用枪乱刺。赵云弃枪在小船上，掣所佩青釭剑在手，分开枪搠，望吴船涌身一跳，早登大船。吴兵尽皆惊倒。赵云入舱中，见夫人抱阿斗于怀中，喝赵云曰：“何故无礼！”云插剑声喏曰：“主母欲何往？何故不令军师知会？”夫人曰：“我母亲病在危笃，无暇报知。”云曰：“主母探病，何故带小主人去？”夫人曰：“阿斗是吾子，留在荆州，无人看觑。”云曰：“主母差矣。主人一生，只有这点骨血，小将在当阳长坂坡百万军中救出，今日夫人却欲抱将去，是何道理？”夫人怒曰：“量汝只是帐下一武夫，安敢管我家事！”云曰：“夫人要去便去，只留下小主人。”夫人喝曰：“汝半路辄入船中，必有反意！”云曰：“若不留下小主人，纵然万死，亦不敢放夫人去。”夫人喝侍婢向前揪捽，被赵云推倒，就怀中夺了阿斗，抱出船头上。欲要傍岸，又无帮手；欲要行凶，又恐碍于道理：进退不得。夫人喝侍婢夺阿斗，赵云一手抱定阿斗，一手仗剑，人不敢近。周善在后梢挟住舵，只顾放船下水。风顺水急，望中流而去。赵云孤掌难鸣，只护得阿斗，安能移舟傍岸。
正在危急，忽见下流头港内一字儿使出十余只船来，船上磨旗擂鼓。赵云自思：“今番中了东吴之计！”只见当头船上一员大将，手执长矛，高声大叫：“嫂嫂留下侄儿去！”原来张飞巡哨，听得这个消息，急来油江夹口，正撞着吴船，急忙截住。当下张飞提剑跳上吴船。周善见张飞上船，提刀来迎，被张飞手起一剑砍倒，提头掷于孙夫人前。夫人大惊曰：“叔叔何故无礼？”张飞曰：“嫂嫂不以俺哥哥为重，私自归家，这便无礼！”夫人曰：“吾母病重，甚是危急，若等你哥哥回报，须误了我事。若你不放我回去，我情愿投江而死！”
张飞与赵云商议：“若逼死夫人，非为臣下之道。只护着阿斗过船去罢。”乃谓夫人曰：“俺哥哥大汉皇叔，也不辱没嫂嫂。今日相别，若思哥哥恩义，早早回来。”说罢，抱了阿斗，自与赵云回船，放孙夫人五只船去了。后人有诗赞子龙曰：“昔年救主在当阳，今日飞身向大江。船上吴兵皆胆裂，子龙英勇世无双！”又有诗赞翼德曰：“长坂桥边怒气腾，一声虎啸退曹兵。今朝江上扶危主，青史应传万载名。”
二人欢喜回船。行不数里，孔明引大队船只接来，见阿斗已夺回，大喜。三人并马而归。孔明自申文书往葭萌关，报知玄德。却说孙夫人回吴，具说张飞、赵云杀了周善，截江夺了阿斗。孙权大怒曰：“今吾妹已归，与彼不亲，杀周善之仇，如何不报！”唤集文武，商议起军攻取荆州。正商议调兵，忽报曹操起军四十万来报赤壁之仇。孙权大惊，且按下荆州，商议拒敌曹操。人报长史张纮辞疾回家，今已病故，有哀书上呈。权拆视之，书中劝孙权迁居秣陵，言秣陵山川有帝王之气，可速迁于此，以为万世之业。孙权览书大哭，谓众官曰：“张子纲劝吾迁居秣陵，吾如何不从！”即命迁治建业，筑石头城。吕蒙进曰：“曹操兵来，可于濡须水口筑坞以拒之。”诸将皆曰：“上岸击贼，跣足入船，何用筑城？”蒙曰：“兵有利钝，战无必胜。如猝然遇敌，步骑相促，人尚不暇及水，何能入船乎？”权曰：“人无远虑，必有近忧。子明之见甚远。”便差军数万筑濡须坞。晓夜并工，刻期告竣。
却说曹操在许都，威福日甚。长史董昭进曰：“自古以来，人臣未有如丞相之功者，虽周公、吕望，莫可及也。栉风沐雨，三十余年，扫荡群凶，与百姓除害，使汉室复存。岂可与诸臣宰同列乎？合受魏公之位，加‘九锡’以彰功德。”你道那九锡？一，车马（大辂、戎辂各一。大辂，金车也。戎辂，兵车也。玄牡二驷，黄马八匹）；二，衣服（衮冕之服，赤舄副焉。衮冕，王者之服。赤舄，朱履也）；三，乐悬（乐悬，王者之乐也）；四，朱户（居以朱户，红门也）；五，纳陛（纳陛以登。陛，阶也）；六，虎贲（虎贲三百人，守门之军也）；七，鈇钺（鈇钺各一。鈇，即斧也。钺，斧属）；八、弓矢（彤弓一，彤矢百。彤，赤色也。玈矢千。玈，黑色也）；九，秬鬯圭瓚（秬鬯一卣，圭瓚副焉。秬，黑黍也。鬯，香酒，灌地以求神于阴。卣，中樽也。圭瓚，宗庙祭器，以祀先王也）。
侍中荀彧曰：“不可。丞相本兴义兵，匡扶汉室，当秉忠贞之志，守谦退之节。君子爱人以德，不宜如此。”曹操闻言，勃然变色。董昭曰：“岂可以一人而阻众望？”遂上表请尊操为魏公，加九锡。荀彧叹曰：“吾不想今日见此事！”操闻，深恨之，以为不助己也。建安十七年冬十月，曹操兴兵下江南，就命荀彧同行。彧已知操有杀己之心，托病止于寿春。忽曹操使人送饮食一盒至。盒上有操亲笔封记。开盒视之，并无一物。彧会其意，遂服毒而亡。年五十岁。后人有诗叹曰：“文若才华天下闻，可怜失足在权门。后人休把留侯比，临没无颜见汉君。”其子荀惲，发哀书报曹操。操甚懊悔，命厚葬之，谥曰敬侯。
且说曹操大军至濡须，先差曹洪领三万铁甲马军，哨至江边。回报云：“遥望沿江一带，旗幡无数，不知兵聚何处。”操放心不下，自领兵前进，就濡须口排开军阵。操领百余人上山坡，遥望战船，各分队伍，依次摆列。旗分五色，兵器鲜明。当中大船上青罗伞下，坐着孙权。左右文武，侍立两边。操以鞭指曰：“生子当如孙仲谋！若刘景升儿子，豚犬耳！”忽一声响动，南船一齐飞奔过来。濡须坞内又一军出，冲动曹兵。曹操军马退后便走，止喝不住。忽有千百骑赶到山边，为首马上一人，碧眼紫髯，众人认得正是孙权。权自引一队马军来击曹操。操大惊，急回马时，东吴大将韩当、周泰，两骑马直冲将上来。操背后许褚纵马舞刀，敌住二将，曹操得脱归寨。许褚与二将战三十合方回。操回寨，重赏许褚，责骂众将：“临敌先退，挫吾锐气！后若如此，尽皆斩首。”是夜二更时分，忽寨外喊声大震。操急上马，见四下里火起，却被吴兵劫入大寨。杀至天明，曹兵退五十余里下寨。操心中郁闷，闲看兵书。程昱曰：“丞相既知兵法，岂不知‘兵贵神速’乎？丞相起兵，迁延日久，故孙权得以准备，夹濡须水口为坞，难于攻击。不若且退兵还许都，别作良图。”操不应。
程昱出。操伏几而卧，忽闻潮声汹涌，如万马争奔之状。操急视之，见大江中推出一轮红日，光华射目；仰望天上，又有两轮太阳对照。忽见江心那轮红日，直飞起来，坠于寨前山中，其声如雷。猛然惊觉，原来在帐中做了一梦。帐前军报道午时。曹操教备马，引五十余骑，径奔出寨，至梦中所见落日山边。正看之间，忽见一簇人马，当先一人，金盔金甲。操视之，乃孙权也。权见操至，也不慌忙，在山上勒住马，以鞭指操曰：“丞相坐镇中原，富贵已极，何故贪心不足，又来侵我江南？”操答曰：“汝为臣下，不尊王室。吾奉天子诏，特来讨汝！”孙权笑曰：“此言岂不羞乎？天下岂不知你挟天子令诸侯？吾非不尊汉朝，正欲讨汝以正国家耳。”操大怒，叱诸将上山捉孙权。忽一声鼓响，山背后两彪军出，右边韩当、周泰，左边陈武、潘璋。四员将带三千弓弩手乱射，矢如雨发。操急引众将回走。背后四将赶来甚急。赶到半路，许褚引众虎卫军敌住，救回曹操。吴兵齐奏凯歌，回濡须去了。操还营自思：“孙权非等闲人物。红日之应，久后必为帝王。”于是心中有退兵之意，又恐东吴耻笑，进退未决。两边又相拒了月余，战了数场，互相胜负。直至来年正月，春雨连绵，水港皆满，军士多在泥水之中，困苦异常。操心甚忧。当日正在寨中，与众谋士商议。或劝操收兵，或云目今春暖，正好相持，不可退归。操犹豫未定。
忽报东吴有使赍书到。操启视之。书略曰：“孤与丞相，彼此皆汉朝臣宰。丞相不思报国安民，乃妄动干戈，残虐生灵，岂仁人之所为哉？即日春水方生，公当速去。如其不然，复有赤壁之祸矣。公宜自思焉。”书背后又批两行云：“足下不死，孤不得安。”曹操看毕，大笑曰：“孙仲谋不欺我也。”重赏来使，遂下令班师，命庐江太守朱光镇守皖城，自引大军回许昌。孙权亦收军回秣陵。权与众将商议：“曹操虽然北去，刘备尚在葭萌关未还。何不引拒曹操之兵，以取荆州？”张昭献计曰：“且未可动兵。某有一计，使刘备不能再还荆州。”正是：孟德雄兵方退北，仲谋壮志又图南。
不知张昭说出甚计来，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943840, '5b9b6d1b1579a3003a4f8535', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639200, '三国演义 · 第六十二回 · 取涪关杨高授首 攻雒城黄魏争功', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说张昭献计曰：“且休要动兵。若一兴师，曹操必复至。不如修书二封：一封与刘璋，言刘备结连东吴，共取西川，使刘璋心疑而攻刘备；一封与张鲁，教进兵向荆州来。着刘备首尾不能救应。我然后起兵取之，事可谐矣。”权从之，即发使二处去讫。且说玄德在葭萌关日久，甚得民心。忽接得孔明文书。知孙夫人已回东吴。又闻曹操兴兵犯濡须，乃与庞统议曰：“曹操击孙权，操胜必将取荆州，权胜亦必取荆州矣。为之奈何？”庞统曰：“主公勿忧。有孔明在彼，料想东吴不敢犯荆州。主公可驰书去刘璋处，只推：‘曹操攻击孙权，权求救于荆州。吾与孙权唇齿之邦，不容不相援。张鲁自守之贼，决不敢来犯界。吾今欲勒兵回荆州，与孙权会同破曹操，奈兵少粮缺。望推同宗之谊，速发精兵三、四万，行粮十万斛相助。请勿有误。’若得军马钱粮，却另作商议。”
玄德从之，遣人往成都。来到关前，杨怀、高沛闻知此事，遂教高沛守关，杨怀同使者入成都，见刘璋呈上书信。刘璋看毕，问杨怀为何亦同来。杨怀曰：“专为此书而来。刘备自从入川，广布恩德，以收民心，其意甚是不善。今求军马钱粮，切不可与。如若相助，是把薪助火也。”刘璋曰：“吾与玄德有兄弟之情，岂可不助？”一人出曰：“刘备枭雄，久留于蜀而不遣，是纵虎入室矣。今更助之以军马钱粮，何异与虎添翼乎？”众视其人，乃零陵烝阳人，姓刘，名巴，字子初。刘璋闻刘巴之言，犹豫未决。黄权又复苦谏。璋乃量拨老弱军四千，米一万斛，发书遣使报玄德。仍令杨怀、高沛紧守关隘。刘璋使者到葭萌关见玄德，呈上回书。玄德大怒曰：“吾为汝御敌，费力劳心。汝今积财吝赏，何以使士卒效命乎？”遂扯毁回书，大骂而起。使者逃回成都。庞统曰：“主公只以仁义为重，今日毁书发怒，前情尽弃矣。”玄德曰：“如此，当若何？”庞统曰：“某有三条计策，请主公自择而行。”
玄德问：“那三条计？”统曰：“只今便选精兵，昼夜兼道径袭成都：此为上计。杨怀、高沛乃蜀中名将，各仗强兵拒守关隘；今主公佯以回荆州为名，二将闻知，必来相送；就送行处，擒而杀之，夺了关隘，先取涪城，然后却向成都：此中计也。退还白帝，连夜回荆州，徐图进取：此为下计。若沉吟不去，将至大困，不可救矣。”玄德曰：“军师上计太促，下计太缓；中计不迟不疾，可以行之。”
于是发书致刘璋，只说曹操令部将乐进引兵至青泥镇，众将抵敌不住，吾当亲往拒之，不及面会，特书相辞。书至成都，张松听得说刘玄德欲回荆州，只道是真心，乃修书一封，欲令人送与玄德，却值亲兄广汉太守张肃到，松急藏书于袖中，与肃相陪说话。肃见松神情恍惚，心中疑惑。松取酒与肃共饮。献酬之间，忽落此书于地，被肃从人拾得。席散后，从人以书呈肃。肃开视之。书略曰：“松昨进言于皇叔，并无虚谬，何乃迟迟不发？逆取顺守，古人所贵。今大事已在掌握之中，何故欲弃此而回荆州乎？使松闻之，如有所失。书呈到日，疾速进兵。松当为内应，万勿自误！”张肃见了，大惊曰：“吾弟作灭门之事，不可不首。”连夜将书见刘璋，具言弟张松与刘备同谋，欲献西川。刘璋大怒曰：“吾平日未尝薄待他，何故欲谋反！”遂下令捉张松全家，尽斩于市。后人有诗叹曰：“一览无遗世所稀，谁知书信泄天机。未观玄德兴王业，先向成都血染衣。”
刘璋既斩张松，聚集文武商议曰：“刘备欲夺吾基业，当如之何？”黄权曰：“事不宜迟。即便差人告报各处关隘，添兵把守，不许放荆州一人一骑入关。”璋从其言，星夜驰檄各关去讫。却说玄德提兵回涪城，先令人报上涪水关，请杨怀，高沛出关相别。杨、高二将闻报，商议曰：“玄德此回若何？”高沛曰：“玄德合死。我等各藏利刃在身，就送行处刺之，以绝吾主之患。”杨怀曰：“此计大妙。”二人只带随行二百人，出关送行，其余并留在关上。
玄德大军尽发。前至涪水之上，庞统在马上谓玄德曰：“杨怀、高沛若欣然而来，可提防之；若彼不来，便起兵径取其关，不可迟缓。”正说间，忽起一阵旋风，把马前“帅”字旗吹倒。玄德问庞统曰：“此何兆也？”统曰：“此警报也，杨怀、高沛二人必有行刺之意，宜善防之。”玄德乃身披重铠，自佩宝剑防备。人报杨、高二将前来送行。玄德令军马歇定。庞统分付魏延、黄忠：“但关上来的军士，不问多少，马步军兵，一个也休放回。”二将得令而去。
却说杨怀、高沛二人身边各藏利刃，带二百军兵，牵羊送酒，直至军前。见并无准备，心中暗喜，以为中计。入至帐下、见玄德正与庞统坐于帐中。二将声喏曰：“闻皇叔远回，特具薄礼相送。”遂进酒劝玄德。玄德曰：“二将军守关不易，当先饮此杯。”二将饮酒毕，玄德曰：“吾有密事与二将军商议，闲人退避。”遂将带来二百人尽赶出中军。玄德叱曰：“左右与吾捉下二贼！”帐后刘封、关平应声而出。杨、高二人急待争斗，刘封、关平各捉住一人。玄德喝曰：“吾与汝主是同宗兄弟，汝二人何故同谋，离间亲情？”庞统叱左右搜其身畔，果然各搜出利刃一口。统便喝斩二人；玄德还犹未决，统曰：“二人本意欲杀吾主，罪不容诛。”遂叱刀斧手斩杨怀、高沛于帐前。黄忠、魏延早将二百从人，先自捉下，不曾走了一个。玄德唤入，各赐酒压惊。玄德曰：“杨怀、高沛离间吾兄弟，又藏利刃行刺，故行诛戮。尔等无罪，不必惊疑。”众各拜谢。庞统曰：“吾今即用汝等引路，带吾军取关。各有重赏。”众皆应允。是夜二百人先行，大军随后。前军至关下叫曰：“二将军有急事回，可速开关。”城上听得是自家军，即时开关。大军一拥而入，兵不血刃，得了涪关。蜀兵皆降。玄德各加重赏，遂即分兵前后守把。次日劳军，设宴于公厅。玄德酒酣，顾庞统曰：“今日之会，可为乐乎？”庞统曰：“伐人之国而以为乐，非仁者之兵也。”玄德曰：“吾闻昔日武王伐纣，作乐象功，此亦非仁者之兵欤？汝言何不合道理？可速退！”庞统大笑而起。左右亦扶玄德入后堂。睡至半夜，酒醒。左右以逐庞统之言，告知玄德。玄德大悔；次早穿衣升堂，请庞统谢罪曰：“昨日酒醉，言语触犯，幸勿挂怀。”庞统谈笑自若。玄德曰：“昨日之言，惟吾有失。”庞统曰：“君臣俱失，何独主公？”玄德亦大笑，其乐如初。
却说刘璋闻玄德杀了杨、高二将，袭了涪水关，大惊曰：“不料今日果有此事！”遂聚文武，问退兵之策。黄权曰：“可连夜遣兵屯雒县，塞住咽喉之路。刘备虽有精兵猛将，不能过也。”璋遂令刘璝、泠苞、张任、邓贤点五万大军，星夜往守雒县，以拒刘备。四将行兵之次，刘璝曰：“吾闻锦屏山中有一异人，道号‘紫虚上人’，知人生死贵贱。吾辈今日行军，正从锦屏山过。何不试往问之？”张任曰：“大丈夫行兵拒敌，岂可问于山野之人乎？”璝曰：“不然。圣人云：‘至诚之道，可以前知。’吾等问于高明之人，当趋吉避凶。”于是四人引五六十骑至山下，问径樵夫。樵夫指高山绝顶上，便是上人所居。四人上山至庵前，见一道童出迎。问了姓名，引入庵中。只见紫虚上人，坐于蒲墩之上。四人下拜，求问前程之事。紫虚上人曰：“贫道乃山野废人，岂知休咎？”刘璝再三拜问，紫虚遂命道童取纸笔，写下八句言语，付与刘璝。其文曰：“左龙右凤，飞入西川。雏凤坠地，卧龙升天。一得一失，天数当然。见机而作，勿丧九泉。”刘璝又问曰：“我四人气数如何？”紫虚上人曰：“定数难逃，何必再问！”璝又请问时，上人眉垂目合，恰似睡着的一般，并不答应。四人下山。刘璝曰：“仙人之言，不可不信。”张任曰：“此狂叟也，听之何益。”遂上马前行。
既至雒县，分调人马，守把各处隘口。刘璝曰：“雒城乃成都之保障，失此则成都难保。吾四人公议，着二人守城，二人去雒县前面，依山傍险，扎下两个寨子，勿使敌兵临城。”泠苞、邓贤曰：“某愿往结寨。”刘璝大喜，分兵二万，与泠、邓二人，离城六十里下寨。刘璝、张任守护雒城。
却说玄德既得涪水关，与庞统商议进取雒城。人报刘璋拨四将前来，即日泠苞、邓贤领二万军离城六十里，扎下两个大寨。玄德聚众将问曰：“谁敢建头功，去取二将寨栅？”老将黄忠应声出曰：“老夫愿往。”玄德曰：“老将军率本部人马，前至雒城，如取得泠苞、邓贤营寨，必当重赏。”
黄忠大喜，即领本部兵马，谢了要行。忽帐下一人出曰：“老将军年纪高大，如何去得？小将不才愿往。”玄德视之，乃是魏延。黄忠曰：“我已领下将令，你如何敢搀越？”魏延曰：“老者不以筋骨为能。吾闻泠苞、邓贤乃蜀中名将，血气方刚。恐老将军近他不得，岂不误了主公大事？因此愿相替，本是好意。”黄忠大怒曰：“汝说吾老，敢与我比试武艺么？”魏延曰：“就主公之前，当面比试。赢得的便去，何如？”黄忠遂趋步下阶，便叫小校“将刀来”！玄德急止之曰：“不可！吾今提兵取川，全仗汝二人之力。今两虎相斗，必有一伤。须误了我大事。吾与你二人劝解，休得争论。”庞统曰：“汝二人不必相争。即今泠苞、邓贤下了两个营寨。今汝二人自领本部军马，各打一寨。如先夺得者，便为头功。”于是分定黄忠打泠苞寨，魏延打邓贤寨。二人各领命去了。庞统曰：“此二人去，恐于路上相争，主公可自引军为后应。”玄德留庞统守城，自与刘封、关平引五千军随后进发。
却说黄忠归寨，传令来日四更造饭，五更结束，平明进兵，取左边山谷而进。魏延却暗使人探听黄忠甚时起兵。探事人回报：“来日四更造饭，五更起兵。”魏延暗喜，分付众军士二更造饭，三更起兵，平明要到邓贤寨边。军士得令，都饱餐一顿，马摘铃，人衔枚，卷旗束甲，暗地去劫寨。三更前后，离寨前进。到半路，魏延马上寻思：“只去打邓贤寨，不显能处，不如先去打泠苞寨，却将得胜兵打邓贤寨。两处功劳，都是我的。”就马上传令，教军士都投左边山路里去。天色微明，离泠苞寨不远，教军士少歇，排搠金鼓旗幡、枪刀器械。早有伏路小军飞报入寨，泠苞已有准备了。一声炮响，三军上马，杀将出来。魏延纵马提刀，与泠苞接战。二将交马，战到三十合，川兵分两路来袭汉军。汉军走了半夜，人马力乏，抵当不住，退后便走。魏延听得背后阵脚乱，撇了泠苞，拨马回走。川兵随后赶来，汉军大败。走不到五里，山背后鼓声震地，邓贤引一彪军从山谷里截出来，大叫：“魏延快下马受降！”魏延策马飞奔，那马忽失前蹄，双足跪地，将魏延掀将下来。邓贤马奔到，挺枪来刺魏延。枪未到处，弓弦响，邓贤倒撞下马。后面泠苞方欲来救，一员大将，从山坡上跃马而来，厉声大叫：“老将黄忠在此！”舞刀直取泠苞。泠苞抵敌不住，望后便走。黄忠乘势追赶，川兵大乱。
黄忠一枝军救了魏延，杀了邓贤，直赶到寨前。泠苞回马与黄忠再战。不到十余合，后面军马拥将上来，泠苞只得弃了左寨，引败军来投右寨。只见寨中旗帜全别，泠苞大惊。兜住马看时，当头一员大将，金甲锦袍，乃是刘玄德，左边刘封，右边关平，大喝道：“寨子吾已夺下，汝欲何往？”原来玄德引兵从后接应，便乘势夺了邓贤寨子。泠苞两头无路，取山僻小径，要回雒城。行不到十里，狭路伏兵忽起，搭钩齐举，把泠苞活捉了。原来却是魏延自知罪犯，无可解释，收拾后军，令蜀兵引路，伏在这里，等个正着。用索缚了泠苞，解投玄德寨来。却说玄德立起免死旗，但川兵倒戈卸甲者，并不许杀害，如伤者偿命；又谕众降兵曰：“汝川人皆有父母妻子，愿降者充军，不愿降者放回。”于是欢声动地。黄忠安下寨脚，径来见玄德，说魏延违了军令，可斩之。玄德急召魏延，魏延解泠苞至。玄德曰：“延虽有罪，此功可赎。”令魏延谢黄忠救命之恩，今后毋得相争。魏延顿首伏罪。玄德重赏黄忠，使人押泠苞到帐下，玄德去其缚，赐酒压惊，问曰：“汝肯降否？”泠苞曰：“既蒙免死，如何不降？刘璝、张任与某为生死之交；若肯放某回去，当即招二人来降，就献雒城。”玄德大喜，便赐衣服鞍马，令回雒城。魏延曰：“此人不可放回。若脱身一去，不复来矣。”玄德曰：“吾以仁义待人，人不负我。”
却说泠苞得回雒城，见刘璝、张任，不说捉去放回，只说：“被我杀了十余人，夺得马匹逃回。”刘璝忙遣人往成都求救。刘璋听知折了邓贤，大惊，慌忙聚众商议。长子刘循进曰：“儿愿领兵前去守雒城。”璋曰：“既吾儿肯去，当遣谁人为辅？”一人出曰：“某愿往”璋视之，乃舅氏吴懿也。璋曰：“得尊舅去最好。谁可为副将？”吴懿保吴兰、雷铜二人为副将，点二万军马来到雒城。刘璝、张任接着，具言前事。吴懿曰：“兵临城下，难以拒敌，汝等有何高见？”泠苞曰：“此间一带，正靠涪江，江水大急；前面寨占山脚，其形最低。某乞五千军，各带锹锄前去，决涪江之水，可尽淹死刘备之兵也。”吴懿从其计，即令泠苞前往决水，吴兰、雷铜引兵接应。泠苞领命，自去准备决水器械。
却说玄德令黄忠、魏延各守一寨，自回涪城，与军师庞统商议。细作报说：“东吴孙权遣人结好东川张鲁，将欲来攻葭萌关。”玄德惊曰：“若葭萌关有失，截断后路，吾进退不得，当如之何？”庞统谓孟达曰：“公乃蜀中人，多知地理，去守葭萌关如何？”达曰：“某保一人与某同去守关，万无一失。”玄德问何人。达曰：“此人曾在荆州刘表部下为中郎将，乃南郡枝江人，姓霍，名峻，字仲邈。”玄德大喜，即时遣孟达、霍峻守葭萌关去了。庞统退归馆舍，门吏忽报：“有客特来相访。”统出迎接，见其人身长八尺，形貌甚伟；头发截短，披于颈上；衣服不甚齐整。统问曰：“先生何人也？”其人不答，径登堂仰卧床上。统甚疑之。再三请问。其人曰：“且消停，吾当与汝说知天下大事。”统闻之愈疑，命左右进酒食。其人起而便食，并无谦逊；饮食甚多，食罢又睡。统疑惑不定，使人请法正视之，恐是细作。法正慌忙到来。统出迎接，谓正曰：“有一人如此如此。”法正曰：“莫非彭永言乎？”升阶视之。其人跃起曰：“孝直别来无恙！”正是：只为川人逢旧识，遂令涪水息洪流。
毕竟此人是谁，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943843, '5b9b6d41808ca43cd22279d8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639201, '三国演义 · 第六十三回 · 诸葛亮痛哭庞统 张翼德义释严颜', NULL, 3, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说法正与那人相见，各抚掌而笑。庞统问之。正曰：“此公乃广汉人，姓彭，名羕，字永言，蜀中豪杰也。因直言触忤刘璋，被璋髡钳为徒隶，因此短发。”统乃以宾礼待之，问羕从何而来。羕曰：“吾特来救汝数万人性命，见刘将军方可说。”法正忙报玄德。玄德亲自谒见，请问其故。羕曰：“将军有多少军马在前寨？”玄德实告：“有魏延、黄忠在彼。”羕曰：“为将之道，岂可不知地理乎？前寨紧靠涪江，若决动江水，前后以兵塞之，一人无可逃也。”玄德大悟。彭羕曰：“罡星在西方，太白临于此地，当有不吉之事，切宜慎之。”玄德即拜彭羕为幕宾，使人密报魏延、黄忠，教朝暮用心巡警，以防决水。黄忠、魏延商议：二人各轮一日，如遇敌军到来，互相通报。却说泠苞见当夜风雨大作，引了五千军，径循江边而进，安排决江。只听得后面喊声乱起，泠苞知有准备，急急回军。前面魏延引军赶来，川兵自相践踏。泠苞正奔走间，撞着魏延。交马不数合，被魏延活捉去了。比及吴兰、雷铜来接应时，又被黄忠一军杀退。魏延解泠苞到涪关。玄德责之曰：“吾以仁义相待，放汝回去，何敢背我！今次难饶！”将泠苞推出斩之，重赏魏延。玄德设宴管待彭羕，忽报：荆州诸葛亮军师特遣马良奉书至此。玄德召入问之。马良礼毕曰：“荆州平安，不劳主公忧念。”遂呈上军师书信。玄德拆书观之，略云：“亮夜算太乙数，今年岁次癸巳，罡星在西方；又观乾象，太白临于雒城之分：主将帅身上多凶少吉。切宜谨慎。”玄德看了书，便教马良先回。玄德曰：“吾将回荆州，去论此事。”庞统暗思：“孔明怕我取了西川，成了功，故意将此书相阻耳。”乃对玄德曰：“统亦算太乙数，已知罡星在西，应主公合得西川，别不主凶事。统亦占天文，见太白临于雒城，先斩蜀将泠苞，已应凶兆矣。主公不可疑心，可急进兵。”
玄德见庞统再三催促，乃引军前进。黄忠同魏延接入寨去。庞统问法正曰：“前至雒城，有多少路？”法正画地作图。玄德取张松所遗图本对之，并无差错。法正言：“山北有条大路，正取雒城东门；山南有条小路，却取雒城西门：两条路皆可进兵。”庞统谓玄德曰：“统令魏延为先锋，取南小路而进；主公令黄忠作先锋，从山北大路而进：并到雒城取齐。”玄德曰：“吾自幼熟于弓马，多行小路。军师可从大路去取东门，吾取西门。”庞统曰：“大路必有军邀拦，主公引兵当之。统取小路。”玄德曰：“军师不可。吾夜梦一神人，手执铁棒击吾右臂，觉来犹自臂疼。此行莫非不佳。”庞统曰：“壮士临阵，不死带伤，理之自然也。何故以梦寐之事疑心乎？”玄德曰：“吾所疑者，孔明之书也。军师还守涪关，如何？”庞统大笑曰：“主公被孔明所惑矣：彼不欲令统独成大功，故作此言以疑主公之心。心疑则致梦，何凶之有？统肝脑涂地，方称本心。主公再勿多言，来早准行。”
当日传下号令，军士五更造饭，平明上马。黄忠、魏延领军先行。玄德再与庞统约会，忽坐下马眼生前失，把庞统掀将下来。玄德跳下马，自来笼住那马。玄德曰：“军师何故乘此劣马？”庞统曰：“此马乘久，不曾如此。”玄德曰：“临阵眼生，误人性命。吾所骑白马，性极驯熟，军师可骑，万无一失。劣马吾自乘之。”遂与庞统更换所骑之马。庞统谢曰：“深感主公厚恩，虽万死亦不能报也。”遂各上马取路而进。玄德见庞统去了，心中甚觉不快，怏怏而行。
却说雒城中吴懿、刘璝听知折了泠苞，遂与众商议。张任曰：“城东南山僻有一条小路，最为要紧，某自引一军守之。诸公紧守雒城，勿得有失。”忽报汉兵分两路前来攻城。张任急引三千军，先来抄小路埋伏。见魏延兵过，张任教尽放过去，休得惊动。后见庞统军来，张任军士遥指军中大将：“骑白马者必是刘备。”张任大喜，传令教如此如此。
却说庞统迤逦前进，抬头见两山逼窄，树木丛杂；又值夏末秋初，枝叶茂盛。庞统心下甚疑，勒住马问：“此处是何地？”数内有新降军士，指道：“此处地名落凤坡。”庞统惊曰：“吾道号凤雏，此处名落凤坡，不利于吾。”令后军疾退。只听山坡前一声炮响，箭如飞蝗，只望骑白马者射来。可怜庞统竟死于乱箭之下。时年止三十六岁。后人有诗叹曰：“古岘相连紫翠堆，士元有宅傍山隈。儿童惯识呼鸠曲，闾巷曾闻展骥才。预计三分平刻削，长驱万里独徘徊。谁知天狗流星坠，不使将军衣锦回。”先是东南有童谣云：“一凤并一龙，相将到蜀中。才到半路里，凤死落坡东。风送雨，雨随风，隆汉兴时蜀道通，蜀道通时只有龙。”
当日张任射死庞统，汉军拥塞，进退不得，死者大半。前军飞报魏延。魏延忙勒兵欲回，奈山路逼窄，厮杀不得。又被张任截断归路，在高阜处用强弓硬弩射来。魏延心慌。有新降蜀兵曰：“不如杀奔雒城下，取大路而进。”延从其言，当先开路，杀奔雒城来。尘埃起处，前面一军杀至，乃雒城守将吴兰、雷铜也；后面张任引兵追来：前后夹攻，把魏延围在垓心。魏延死战不能得脱。但见吴兰、雷铜后军自乱，二将急回马去救。魏延乘势赶去，当先一将，舞刀拍马，大叫：“文长，吾特来救汝！”视之，乃老将黄忠也。两下夹攻，杀败吴、雷二将，直冲至雒城之下。刘璝引兵杀出，却得玄德在后当住接应。黄忠、魏延翻身便回。玄德军马比及奔到寨中，张任军马又从小路里截出。刘璝、吴兰、雷铜当先赶来。玄德守不住二寨，且战且走，奔回涪关。蜀兵得胜，迤逦追赶。玄德人困马乏，那里有心厮杀，且只顾奔走。将近涪关，张任一军追赶至紧。幸得左边刘封，右边关平，二将领三万生力军截出，杀退张任；还赶二十里，夺回战马极多。
玄德一行军马，再入涪关，问庞统消息。有落凤坡逃得性命的军士，报说：“军师连人带马，被乱箭射死于坡前。”玄德闻言，望西痛哭不已，遥为招魂设祭。诸将皆哭。黄忠曰：“今番折了庞统军师，张任必然来攻打涪关，如之奈何？不若差人往荆州，请诸葛军师来商议收川之计。”正说之间，人报张任引军直临城下搦战。黄忠、魏延皆要出战。玄德曰：“锐气新挫，宜坚守以待军师来到。”黄忠、魏延领命，只谨守城池。玄德写一封书，教关平分付：“你与我往荆州请军师去。”关平领了书，星夜往荆州来。玄德自守涪关，并不出战。
却说孔明在荆州，时当七夕佳节，大会众官夜宴，共说收川之事。只见正西上一星，其大如斗，从天坠下，流光四散。孔明失惊，掷杯于地，掩面哭曰：“哀哉！痛哉”众官慌问其故。孔明曰：“吾前者算今年罡星在西方，不利于军师；天狗犯于吾军，太白临于雒城，已拜书主公，教谨防之。谁想今夕西方星坠，庞士元命必休矣！”言罢，大哭曰：“今吾主丧一臂矣！”众官皆惊，未信其言。孔明曰：“数日之内，必有消息。”是夕酒不尽欢而散。
数日之后，孔明与云长等正坐间，人报关平到，众官皆惊。关平入，呈上玄德书信。孔明视之，内言：“本年七月初七日，庞军师被张任在落凤坡前箭射身故。”孔明大哭，众官无不垂泪。孔明曰：“既主公在涪关进退两难之际，亮不得不去。”云长曰：“军师去，谁人保守荆州？荆州乃重地，干系非轻。”孔明曰：“主公书中虽不明言其人，吾已知其意了。”乃将玄德书与众官看曰：“主公书中，把荆州托在吾身上，教我自量才委用。虽然如此，今教关平赍书前来，其意欲云长公当此重任。云长想桃园结义之情，可竭力保守此地，责任非轻，公宜勉之。”云长更不推辞，慨然领诺。孔明设宴，交割印绶。云长双手来接。孔明擎着印曰：“这干系都在将军身上。”云长曰：“大丈夫既领重任，除死方休。”孔明见云长说个“死”字，心中不悦；欲待不与，其言已出。孔明曰：“倘曹操引兵来到，当如之何？”云长曰：“以力拒之。”孔明又曰：“倘曹操、孙权，齐起兵来，如之奈何？”云长曰：“分兵拒之。”孔明曰：“若如此，荆州危矣。吾有八个字，将军牢记，可保守荆州。”云长问：“那八个字？”孔明曰：“北拒曹操，东和孙权。”云长曰：“军师之言，当铭肺腑。”
孔明遂与了印绶，令文官马良、伊籍、向朗、糜竺，武将糜芳、廖化、关平、周仓，一班儿辅佐云长，同守荆州。一面亲自统兵入川。先拨精兵一万，教张飞部领，取大路杀奔巴州、雒城之西，先到者为头功。又拨一枝兵，教赵云为先锋，溯江而上，会于雒城。孔明随后引简雍、蒋琬等起行。那蒋琬字公琰，零陵湘乡人也，乃荆襄名士，现为书记。
当日孔明引兵一万五千，与张飞同日起行。张飞临行时，孔明嘱付曰：“西川豪杰甚多，不可轻敌。于路戒约三军，勿得掳掠百姓，以失民心。所到之处，并宜存恤，勿得恣逞鞭挞士卒。望将军早会雒城，不可有误。”
张飞欣然领诺，上马而去。迤逦前行，所到之处，但降者秋毫无犯。径取汉川路，前至巴郡。细作回报：“巴郡太守严颜，乃蜀中名将，年纪虽高，精力未衰，善开硬弓，使大刀，有万夫不当之勇：据住城郭，不竖降旗。”张飞教离城十里下寨，差人入城去：“说与老匹夫，早早来降，饶你满城百姓性命；若不归顺，即踏平城郭，老幼不留！”
却说严颜在巴郡，闻刘璋差法正请玄德入川，拊心而叹曰：“此所谓独坐穷山，引虎自卫者也！”后闻玄德据住涪关，大怒，屡欲提兵往战，又恐这条路上有兵来。当日闻知张飞兵到，便点起本部五六千人马，准备迎敌。或献计曰：“张飞在当阳长坂，一声喝退曹兵百万之众。曹操亦闻风而避之，不可轻敌。今只宜深沟高垒，坚守不出。彼军无粮，不过一月，自然退去。更兼张飞性如烈火，专要鞭挞士卒；如不与战，必怒；怒则必以暴厉之气，待其军士：军心一变，乘势击之，张飞可擒也。”严颜从其言，教军士尽数上城守护。忽见一个军士，大叫：“开门！”严颜教放入问之。那军士告说是张将军差来的，把张飞言语依直便说。严颜大怒，骂：“匹夫怎敢无礼！吾严将军岂降贼者乎！借你口说与张飞！”唤武士把军人割下耳鼻，却放回寨。军人回见张飞，哭告严颜如此毁骂。张飞大怒，咬牙睁目，披挂上马，引数百骑来巴郡城下搦战。城上众军百般痛骂。张飞性急，几番杀到吊桥，要过护城河，又被乱箭射回。到晚全无一个人出，张飞忍一肚气还寨。次日早晨，又引军去搦战。那严颜在城敌楼上，一箭射中张飞头盔。飞指而恨曰：“若拿住你这老匹夫，我亲自食你肉！”到晚又空回。第三日，张飞引了军，沿城去骂。原来那座城子是个山城，周围都是乱山，张飞自乘马登山，下视城中。见军士尽皆披挂，分列队伍，伏在城中，只是不出；又见民夫来来往往，搬砖运石，相助守城。张飞教马军下马，步军皆坐，引他出敌，并无动静。又骂了一日，依旧空回。张飞在寨中，自思：“终日叫骂，彼只不出，如之奈何？”猛然思得一计，教众军不要前去搦战，都结束了在寨中等候；却只教三五十个军士，直去城下叫骂。引严颜军出来，便与厮杀。张飞磨拳擦掌，只等敌军来。小军连骂了三日，全然不出。张飞眉头一纵，又生一计，传令教军士四散砍打柴草，寻觅路径，不来搦战。严颜在城中，连日不见张飞动静，心中疑惑，着十数个小军，扮作张飞砍柴的军，潜地出城，杂在军内，入山中探听。
当日诸军回寨。张飞坐在寨中，顿足大骂：“严颜老匹夫！枉气杀我！”只见帐前三四个人说道：“将军不须心焦：这几日打探得一条小路，可以偷过巴郡。”张飞故意大叫曰：“既有这个去处，何不早来说？”众应曰：“这几日却才哨探得出。”张飞曰：“事不宜迟，只今二更造饭，趁三更明月，拔寨都起，人衔枚，马去铃，悄悄而行。我自前面开路，汝等依次而行。”传了令便满寨告报。探细的军听得这个消息，尽回城中来，报与严颜。颜大喜曰：“我算定这匹夫忍耐不得。你偷小路过去，须是粮草辎重在后；我截住后路，你如何得过？好无谋匹夫，中我之计！”即时传令，教军士准备赴敌：“今夜二更也造饭，三更出城，伏于树木丛杂去处。只等张飞过咽喉小路去了，车仗来时，只听鼓响，一齐杀出。”传了号令，看看近夜，严颜全军尽皆饱食，披挂停当，悄悄出城，四散伏住，只听鼓响：严颜自引十数裨将，下马伏于林中。约三更后，遥望见张飞亲自在前，横矛纵马，悄悄引军前进。去不得三四里，背后车仗人马、陆续进发。严颜看得分晓，一齐擂鼓，四下伏兵尽起。正来抢夺车仗、背后一声锣响，一彪军掩到，大喝：“老贼休走！我等的你恰好！”严颜猛回头看时，为首一员大将，豹头环眼，燕颌虎须，使丈八矛，骑深乌马：乃是张飞。四下里锣声大震，众军杀来。严颜见了张飞，举手无措，交马战不十合，张飞卖个破绽，严颜一刀砍来，张飞闪过，撞将入去，扯住严颜勒甲绦，生擒过来，掷于地下；众军向前，用索绑缚住了。原来先过去的是假张飞。料道严颜击鼓为号，张飞却教鸣金为号：金响诸军齐到。川兵大半弃甲倒戈而降。
张飞杀到巴郡城下，后军已自入城。张飞叫休杀百姓，出榜安民。群刀手把严颜推至。飞坐于厅上，严颜不肯下跪。飞怒目咬牙大叱曰：“大将到此，何为不降，而敢拒敌？”严颜全无惧色，回叱飞曰：“汝等无义，侵我州郡！但有断头将军，无降将军！”飞大怒，喝左右斩来。严颜喝曰：“贼匹夫！砍头便砍，何怒也？”张飞见严颜声音雄壮，面不改色，乃回嗔作喜，下阶喝退左右，亲解其缚，取衣衣之，扶在正中高坐，低头便拜曰：“适来言语冒渎，幸勿见责。吾素知老将军乃豪杰之士也。”严颜感其恩义，乃降。后人有诗赞严颜曰：“白发居西蜀，清名震大邦。忠心如皎月，浩气卷长江。宁可断头死，安能屈膝降？巴州年老将，天下更无双。”又有赞张飞诗曰：“生获严颜勇绝伦，惟凭义气服军民。至今庙貌留巴蜀，社酒鸡豚日日春。”张飞请问入川之计。严颜曰：“败军之将，荷蒙厚恩，无可以报，愿施犬马之劳，不须张弓只箭，径取成都。”正是：只因一将倾心后，致使连城唾手降。
未知其计如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943845, '5b9b6d6167f356005c8dd7df', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639202, '三国演义 · 第六十四回 · 孔明定计捉张任 杨阜借兵破马超', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说张飞问计于严颜，颜曰：“从此取雒城，凡守御关隘，都是老夫所管，官军皆出于掌握之中。今感将军之恩，无可以报，老夫当为前部，所到之处，尽皆唤出拜降。”张飞称谢不已。于是严颜为前部，张飞领军随后。凡到之处，尽是严颜所管，都唤出投降。有迟疑未决者，颜曰：“我尚且投降，何况汝乎？”自是望风归顺，并不曾厮杀一场。
却说孔明已将起程日期申报玄德，教都会聚雒城。玄德与众官商议：“今孔明、翼德分两路取川，会于雒城，同入成都。水陆舟车，已于七月二十日起程，此时将及待到。今我等便可进兵。”黄忠曰：“张任每日来搦战，见城中不出，彼军懈怠，不做准备，今日夜间分兵劫寨，胜如白昼厮杀。”玄德从之，教黄忠引兵取左，魏延引兵取右，玄德取中路。当夜二更，三路军马齐发。张任果然不做准备。汉军拥入大寨，放起火来，烈焰腾空。蜀兵奔走，连夜直赶到雒城，城中兵接应入去。玄德还中路下寨；次日，引兵直到雒城，围住攻打。张任按兵不出。攻到第四日，玄德自提一军攻打西门，令黄忠、魏延在东门攻打，留南门北门放军行走。原来南门一带都是山路，北门有涪水：因此不围。张任望见玄德在西门，骑马往来，指挥打城，从辰至未，人马渐渐力乏。张任教吴兰、雷铜二将引兵出北门，转东门，敌黄忠、魏延；自己却引军出南门，转西门，单迎玄德。城内尽拨民兵上城，擂鼓助喊。却说玄德见红日平西，教后军先退。军士方回身，城上一片声喊起，南门内军马突出。张任径来军中捉玄德，玄德军中大乱。黄忠、魏延又被吴兰、雷铜敌住。两下不能相顾。玄德敌不住张任，拨马往山僻小路而走。张任从背后追来，看看赶上。玄德独自一人一马。张任引数骑赶来。玄德正望前尽力加鞭而行，忽山路一军冲来。玄德马上叫苦曰：“前有伏兵，后有追兵，天亡我也！”只见来军当头一员大将，乃是张飞。原来张飞与严颜正从那条路上来，望见尘埃起，知与川兵交战。张飞当先而来，正撞着张任，便就交马。战到十余合，背后严颜引兵大进。张任火速回身。张飞直赶到城下。张任退入城，拽起吊桥。张飞回见玄德曰：“军师溯江而来，尚且未到，反被我夺了头功。”玄德曰：“山路险阻，如何无军阻当，长驱大进，先到于此？”张飞曰：“于路关隘四十五处，皆出老将严颜之功，因此于路并不曾费分毫之力。”遂把义释严颜之事，从头说了一遍，引严颜见玄德。玄德谢曰：“若非老将军，吾弟安能到此？”即脱身上黄金锁子甲以赐之。严颜拜谢。正待安排宴饮，忽闻哨马回报：“黄忠、魏延和川将吴兰、雷铜交锋，城中吴懿、刘璝又引兵助战，两下夹攻，我军抵敌不住，魏、黄二将败阵投东去了。”张飞听得，便请玄德分兵两路，杀去救援。于是张飞在左，玄德在右，杀奔前来。吴懿、刘璝见后面喊声起，慌退入城中。吴兰、雷铜只顾引兵追赶黄忠、魏延，却被玄德、张飞截住归路。黄忠、魏延又回马转攻。吴兰、雷铜料敌不住，只得将本部军马前来投降。玄德准其降，收兵近城下寨。却设张任失了二将，心中忧虑。吴懿、刘璝曰：“兵势甚危，不决一死战，如何得兵退？一面差人去成都见主公告急，一面用计敌之。”张任曰：“吾来日领一军搦战，诈败，引转城北；城内再以一军冲出，截断其中：可获胜也。”吴懿曰：“刘将军相辅公子守城，我引兵冲出助战。”约会已定。次日，张任引数千人马，摇旗呐喊，出城搦战。张飞上马出迎，更不打话，与张任交锋。战不十余合，张任诈败，绕城而走。张飞尽力追之。吴懿一军截住，张任引军复回，把张飞围在垓心，进退不得。正没奈何，只见一队军从江边杀出。当先一员大将，挺枪跃马，与吴懿交锋；只一合，生擒吴懿，战退敌军，救出张飞。视之，乃赵云也。飞问：“军师何在？”云曰：“军师已至，想此时已与主公相见了也。”二人擒吴懿回寨。张任自退入东门去了。
张飞、赵云回寨中，见孔明、简雍、蒋琬已在帐中。飞下马来参军师。孔明惊问曰：“如何得先到？”玄德具述义释严颜之事。孔明贺曰：“张将军能用谋，皆主公之洪福也。”赵云解吴懿见玄德。玄德曰：“汝降否？”吴懿曰：“我既被捉，如何不降？”玄德大喜，亲解其缚。孔明问：“城中有几人守城？”吴懿曰：“有刘季玉之子刘循，辅将刘璝、张任。刘璝不打紧；张任乃蜀郡人，极有胆略，不可轻敌。”孔明曰：“先捉张任，然后取雒城。”问：“城东这座桥名为何桥？”吴懿曰：“金雁桥。”孔明遂乘马至桥边，绕河看了一遍，回到寨中，唤黄忠、魏延听令曰：“离金雁桥南五六里，两岸都是芦苇蒹葭，可以埋伏。魏延引一千枪手伏于左，单戳马上将；黄忠引一千刀手伏于右，单砍坐下马。杀散彼军，张任必投山东小路而来。张翼德引一千军伏在那里，就彼处擒之。”又唤赵云伏于金雁桥北：“待我引张任过桥，你便将桥拆断，却勒兵于桥北，遥为之势，使张任不敢望北走，退投南去，却好中计。”调遣已定，军师自去诱敌。
却说刘璋差卓鹰、张翼二将，前至雒城助战。张任教张翼与刘璝守城，自与卓膺为前后二队，任为前队，膺为后队，出城退敌。孔明引一队不整不齐军，过金雁桥来，与张任对阵。孔明乘四轮车，纶巾羽扇而出，两边百余骑簇捧，遥指张任曰：“曹操以百万之众，闻吾之名，望风而走；今汝何人，敢不投降？”张任看见孔明军伍不齐，在马上冷笑曰：“人说诸葛亮用兵如神，原来有名无实！”把枪一招，大小军校齐杀过来。孔明弃了四轮车，上马退走过桥。张任从背后赶来。过了金雁桥，见玄德军在左，严颜军在右，冲杀将来。张任知是计，急回军时，桥已拆断了；欲投北去，只见赵云一军隔岸摆开，遂不敢投北，径往南绕河而走。走不到五七里，早到芦苇丛杂处。魏延一军从芦中忽起，都用长枪乱戳。黄忠一军伏在芦苇里，用长刀只剁马蹄。马军尽倒，皆被执缚，步军那里敢来？张任引数十骑望山路而走，正撞着张飞。张任方欲退走，张飞大喝一声，众军齐上，将张任活捉了。原来卓膺见张任中计，已投赵云军前降了，一发都到大寨。玄德赏了卓膺。张飞解张任至。孔明亦坐于帐中。玄德谓张任曰：“蜀中诸将，望风而降，汝何不早投降？”张任睁目怒叫曰：“忠臣岂肯事二主乎？”玄德曰：“汝不识天时耳。降即免死。”任曰：“今日便降，久后也不降！可速杀我！”玄德不忍杀之。张任厉声高骂。孔明命斩之以全其名。后人有诗赞曰：“烈士岂甘从二主，张君忠勇死犹生。高明正似天边月，夜夜流光照雒城。”玄德感叹不已，令收其尸首，葬于金雁桥侧，以表其忠。次日，令严颜、吴懿等一班蜀中降将为前部。直至雒城，大叫：“早开门受降，免一城生灵受苦！”刘璝在城上大骂。严颜方待取箭射之，忽见城上一将，拔剑砍翻刘璝，开门投降。玄德军马入雒城，刘循开西门走脱，投成都去了。玄德出榜安民。杀刘璝者，乃武阳人张翼也。
玄德得了雒城，重赏诸将。孔明曰：“雒城已破，成都只在目前；惟恐外州郡不宁，可令张翼、吴懿引赵云抚外水江阳、犍为等处所属州郡，令严颜、卓膺引张飞抚巴西德阳所属州郡，就委官按治平靖，即勒兵回成都取齐。”张飞、赵云领命，各自引兵去了。孔明问：“前去有何处关隘？”蜀中降将曰：“止绵竹有重兵守御；若得绵竹，成都唾手可得。”孔明便商议进兵。法正曰：“雒城既破，蜀中危矣。主公欲以仁义服众，且勿进兵。某作一书上刘璋，陈说利害，璋自然降矣。”孔明曰：“孝直之言最善。”便令写书遣人径往成都。
却说刘循逃回见父，说雒城已陷，刘璋慌聚众官商议。从事郑度献策曰：“今刘备虽攻城夺地，然兵不甚多，士众未附，野谷是资，军无辎重。不如尽驱巴西梓潼民，过涪水以西。其仓廪野谷，尽皆烧除，深沟高垒，静以待之。彼至请战，勿许。久无所资，不过百日，彼兵自走。我乘虚击之，备可擒也。”刘璋曰：“不然。吾闻拒敌以安民，未闻动民以备敌也。此言非保全之计。”正议间，人报法正有书至。刘璋唤入。呈上书。璋拆开视之。其略曰：“昨蒙遣差结好荆州，不意主公左右不得其人，以致如此。今荆州眷念旧情，不忘族谊。主公若得幡然归顺，量不薄待。望三思裁示。”刘璋大怒，扯毁其书，大骂：“法正卖主求荣，忘恩背义之贼！”逐其使者出城。即时遣妻弟费观，提兵前去守把绵竹。费观举保南阳人姓李，名严，字正方，一同领兵。
当下费观、李严点三万军来守绵竹。益州太守董和，字幼宰，南郡枝江人也，上书与刘璋，请往汉中借兵。璋曰：“张鲁与吾世仇，安肯相救？”和曰：“虽然与我有仇，刘备军在雒城，势在危急，唇亡则齿寒，若以利害说之，必然肯从。”璋乃修书遣使前赴汉中。却说马超自兵败入羌，二载有余，结好羌兵，攻拔陇西州郡。所到之处，尽皆归降；惟冀城攻打不下。刺史韦康，累遣人求救于夏侯渊。渊不得曹操言语，未敢动兵。韦康见救兵不来，与众商议：“不如投降马超。”参军杨阜哭谏曰：“超等叛君之徒，岂可降之？”康曰：“事势至此，不降何待？”阜苦谏不从。韦康大开城门，投拜马超。超大怒曰：“汝今事急请降，非真心也！”将韦康四十余口尽斩之，不留一人。有人言：“杨阜劝韦康休降，可斩之。”超曰：“此人守义，不可斩也。”复用杨阜为参军。阜荐梁宽、赵衢二人，超尽用为军官。
杨阜告马超曰：阜妻死于临洮，乞告两个月假，归葬其妻便回。马超从之。杨阜过历城，来见抚彝将军姜叙。叙与阜是姑表兄弟：叙之母是阜之姑，时年已八十二。当日，杨阜入姜叙内宅，拜见其姑，哭告曰：“阜守城不能保，主亡不能死，愧无面目见姑。马超叛君，妄杀郡守，一州士民，无不恨之。今吾兄坐据历城，竟无讨贼之心，此岂人臣之理乎？”言罢，泪流出血。叙母闻言，唤姜叙入，责之曰：“韦使君遇害，亦尔之罪也。”又谓阜曰：“汝既降人，且食其禄，何故又兴心讨之？”阜曰：“吾从贼者，欲留残生，与主报冤也。”叙曰：“马超英勇，急难图之。”阜曰：“有勇无谋，易图也。吾已暗约下梁宽、赵衢。兄若肯兴兵，二人必为内应。”叙母曰：“汝不早图，更待何时，谁不有死，死于忠义，死得其所也。勿以我为念。汝若不听义山之言，吾当先死，以绝汝念。”
叙乃与统兵校尉尹奉、赵昂商议。原来赵昂之子赵月，现随马超为裨将。赵昂当日应允，归见其妻王氏曰：“吾今日与姜叙、杨阜、尹奉一处商议，欲报韦康之仇。吾想子赵月现随马超，今若兴兵，超必先杀吾子，奈何？”其妻厉声曰：“雪君父之大耻，虽丧身亦不惜，何况一子乎！君若顾子而不行，吾当先死矣！”赵昂乃决。次日一同起兵。姜叙、杨阜屯历城，尹奉、赵昂屯祁山。王氏乃尽将首饰资帛，亲自往祁山军中，赏劳军士，以励其众。
马超闻姜叙、杨阜会合尹奉、赵昂举事，大怒，即将赵月斩之；令庞德、马岱尽起军马，杀奔历城来。姜叙、杨阜引兵出。两阵圆处，杨阜、姜叙衣白袍而出，大骂曰：“叛君无义之贼！”马超大怒，冲将过来，两军混战。姜叙、杨卓如何抵得马超，大败而走。马超驱兵赶来。背后喊声起处，尹奉、赵昂杀来。超急回时，两下夹攻，首尾不能相顾。正斗间，刺斜里大队军马杀来。原来是夏侯渊得了曹操军令，正领军来破马超。超如何当得三路军马，大败奔回。
走了一夜，比及平明，到得翼城叫门时，城上乱箭射下。梁宽、赵衢立在城上，大骂马超；将马超妻杨氏从城上一刀砍了，撇下尸首来；又将马超幼子三人，并至亲十余口，都从城上一刀一个，剁将下来。超气噎塞胸，几乎坠下马来。背后夏侯渊引兵追赶。超见势大，不取恋战，与庞德、马岱杀开一条路走。前面又撞见姜叙、杨阜，杀了一阵；冲得过去，又撞着尹奉、赵昂，杀了一阵；零零落落，剩得五六十骑，连夜奔走，四更前后，走到历城下，守门者只道姜叙兵回，大开门接入。超从城南门边杀起，尽洗城中百姓。至姜叙宅，拿出老母。母全无惧色，指马超而大骂。超大怒，自取剑杀之。尹奉、赵昂全家老幼，亦尽被马超所杀。昂妻王氏因在军中，得免于难。次日，夏侯渊大军至，马超弃城杀出，望西而逃。行不得二十里，前面一军摆开，为首的是杨阜。超切齿而恨，拍马挺枪刺之。阜宗弟七人，一齐来助战。马岱、庞德敌住后军。宗弟七人，皆被马超杀死。阜身中五枪，犹然死战。后面夏侯渊大军赶来，马超遂走。只有庞德、马岱五七骑后随而去。夏侯渊自行安抚陇西诸州人民，令姜叙等各各分守，用车载杨阜赴许都，见曹操。操封阜为关内侯。阜辞曰：“阜无捍难之功，又无死难之节，于法当诛，何颜受职？”操嘉之，卒与之爵。却说马超与庞德、马岱商议，径往汉中投张鲁。张鲁大喜，以为得马超，则西可以吞益州，东可以拒曹操，乃商议欲以女招超为婿。大将杨柏谏曰：“马超妻子遭惨祸，皆超之贻害也。主公岂可以女与之？”鲁从其言，遂罢招婿之议。或以杨柏之言，告知马超。超大怒，有杀杨柏之意。杨柏知之，与兄杨松商议，亦有图马超之心。正值刘璋遣使求救于张鲁，鲁不从。忽报刘璋又遣黄权到。权先来见杨松，说：“东西两川，实为唇齿；西川若破，东川亦难保矣。今若肯相救，当以二十州相酬。”松大喜，即引黄权来见张鲁，说唇齿利害，更以二十州相谢。鲁喜其利，从之。巴西阎圃谏曰：“刘璋与主公世仇，今事急求救，诈许割地，不可从也。”忽阶下一人进曰：“某虽不才，愿乞一旅之师，生擒刘备。务要割地以还。”正是：方看真主来西蜀，又见精兵出汉中。
未知其人是谁，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943854, '5b9b6d8767f356005c8dd9a0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639203, '三国演义 · 第六十五回 · 马超大战葭萌关 刘备自领益州牧', NULL, 2, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说阎圃正劝张鲁勿助刘璋，只见马超挺身出曰：“超感主公之恩，无可上报，愿领一军攻取葭萌关，生擒刘备，务要刘璋割二十州奉还主公。”张鲁大喜，先遣黄权从小路而回，随即点兵二万与马超。此时庞德卧病不能行，留于汉中。张鲁令杨柏监军，超与弟马岱选日起程。
却说玄德军马在雒城，法正所差下书人回报说：“郑度劝刘璋尽烧野谷，并各处仓廪，率巴西之民，避于涪水西，深沟高垒而不战。”玄德、孔明闻之，皆大惊曰：“若用此言，吾势危矣！”法正笑曰：“主公勿忧。此计虽毒，刘璋必不能用也。”不一日，人传刘璋不肯迁动百姓，不从郑度之言。玄德闻之，方始宽心。孔明曰：“可速进兵取绵竹。如得此处，成都易取矣。”遂遣黄忠、魏延领兵前进。费观听知玄德兵来，差李严出迎。严领三千兵也，各布阵完。黄忠出马，与李严战四五十合，不分胜败。孔明在阵中教鸣金收军。黄忠回阵，问曰：“正待要擒李严，军师何故收兵？”孔明曰：“吾已见李严武艺，不可力取。来日再战，汝可诈败，引入山峪，出奇兵以胜之。”黄忠领计。次日，李严再引兵来，黄忠又出战，不十合诈败，引兵便走。李严赶来，迤逦赶入出峪，猛然省悟。急待回来，前面魏延引兵摆开。孔明自在山头，唤曰：“公如不降，两下已伏强弩，欲与吾庞士元报仇矣。”李严慌下马卸甲投降。军士不曾伤害一人。孔明引李严见玄德。玄德待之甚厚。严曰：“费观虽是刘盖州亲戚，与某甚密，当往说之。”玄德即命李严回城招降费观。严入绵竹城，对费观赞玄德如此仁德；今若不降，必有大祸。观从其言，开门投降。玄德遂入绵竹，商议分兵取成都。
忽流星马急报，言：“孟达、霍峻守葭萌关，今被东川张鲁遣马超与杨柏、马岱领兵攻打甚急，救迟则关隘休矣。玄德大惊。”孔明曰：“须是张、赵二将，方可与敌。”玄德曰：“子龙引兵在外未回。翼德已在此，可急遣之。”孔明曰：“主公且勿言，容亮激之。”却说张飞闻马超攻关，大叫而入曰：“辞了哥哥，便去战马超也！”孔明佯作不闻，对玄德曰：“今马超侵犯关隘，无人可敌；除非往荆州取关云长来，方可与敌。”张飞曰：“军师何故小觑吾！吾曾独拒曹操百万之兵，岂愁马超一匹夫乎！”孔明曰：“翼德拒水断桥，此因曹操不知虚实耳；若知虚实，将军岂得无事？今马超之勇，天下皆知，渭桥六战，杀得曹操割须弃袍，几乎丧命，非等闲之比。云长且未必可胜。”飞曰：“我只今便去；如胜不得马超，甘当军令！”孔明曰：“既尔肯写文书，便为先锋。请主公亲自去一遭，留亮守绵竹。待子龙来，却作商议。”魏延曰：“某亦愿往。”
孔明令魏延带五百哨马先行，张飞第二，玄德后队，望葭萌关进发。魏延哨马先到关下，正遇杨柏。魏延与杨柏交战，不十合，杨柏败走。魏延要夺张飞头功，乘势赶去。前面一军摆开，为首乃是马岱。魏延只道是马超，舞刀跃马迎之。与岱战不十合，岱败走。延赶去，被岱回身一箭，中了魏延左臂。延急回马走。马岱赶到关前，只见一将喊声如雷，从关上飞奔至面前。原来是张飞初到关上，听得关前厮杀，便来看时，正见魏延中箭，因骤马下关，救了魏延。飞喝马岱曰：“汝是何人？先通姓名，然后厮杀？”马岱曰：“吾乃西凉马岱是也。”张飞曰：“你原来不是马超，快回去！非吾对手！只令马超那厮自来，说道燕人张飞在此！”马岱大怒曰：“汝焉敢小觑我！”挺枪跃马，直取张飞。战不十合，马岱败走。张飞欲待追赶，关上一骑马到来，叫：“兄弟且休去！”飞回视之，原来是玄德到来。飞遂不赶，一同上关。玄德曰：“恐怕你性躁，故我随后赶来到此。既然胜了马岱，且歇一宵，来日战马超。”次日天明，关下鼓声大震，马超兵到。玄德在关上看时，门旗影里，马超纵骑持枪而出；狮盔兽带，银甲白袍：一来结束非凡，二者人才出众。玄德叹曰：“人言‘锦马超’，名不虚传！”张飞便要下关。玄德急止之曰：“且休出战。先当避其锐气。”关下马超单搦张飞出马，关上张飞恨不得平吞马超，三五番皆被玄德当住。看看午后，玄德望见马超阵上人马皆倦，遂选五百骑，跟着张飞，冲下关来。马超见张飞军到，把枪望后一招，约退军有一箭之地。张飞军马一齐扎住；关上军马，陆续下来。张飞挺枪出马，大呼：“认得燕人张翼德么！”马超曰：“吾家屡世公侯，岂识村野匹夫！”张飞大怒。两马齐出，二枪并举。约战百余合，不分胜负。玄德观之，叹曰：“真虎将也！”恐张飞有失，急鸣金收军。两将各回。张飞回到阵中，略歇马片时，不用头盔，只裹包巾上马，又出阵前搦马超厮杀。超又出，两个再战。玄德恐张飞有失，自披挂下关，直至阵前；看张飞与马超又斗百余合，两个精神倍加。玄德教鸣金收军。二将分开，各回本阵。
是日天色已晚，玄德谓张飞曰：“马超英勇，不可轻敌，且退上关。来日再战。”张飞杀得性起，那里肯休？大叫曰：“誓死不回！”玄德曰：“今日天晚，不可战矣。”飞曰：“多点火把，安排夜战！”马超亦换了马，再出阵前，大叫曰：“张飞！敢夜战么？张飞性起，问玄德换了坐下马，抢出阵来，叫曰：“我捉你不得，誓不上关！”超曰：“我胜你不得，誓不回寨！”两军呐喊，点起千百火把，照耀如同白日。两将又向阵前鏖战。到二十余合，马超拨回马便走。张飞大叫曰：“走那里去！”原来马超见赢不得张飞，心生一计：诈败佯输，赚张飞赶来，暗掣铜锤在手，扭回身觑着张飞便打将来。张飞见马超走，心中也提防；比及铜锤打来时，张飞一闪，从耳朵边过去。张飞便勒回马走时，马超却又赶来。张飞带住马，拈弓搭箭，回射马超；超却闪过。二将各自回阵。玄德自于阵前叫曰：“吾以仁义待人。不施谲诈。马孟起，你收兵歇息，我不乘势赶你。”马超闻言，亲自断后，诸军渐退。玄德亦收军上关。次日，张飞又欲下关战马超。人报军师来到。玄德接着孔明。孔明曰：“亮闻孟起世之虎将，若与翼德死战，必有一伤；故令子龙、汉升守住绵竹，我星夜来此。可用条小计，令马超归降主公。”玄德曰：“吾见马超英勇，甚爱之。如何可得？”孔明曰：“亮闻东川张鲁，欲自立为‘汉宁王’。手下谋士杨松，极贪贿赂。主公可差人从小路径投汉中，先用金银结好杨松，后进书与张鲁云：‘吾与刘璋争西川，是与汝报仇。不可听信离间之语。事定之后，保汝为汉宁王。’令其撤回马超兵。待其来撤时，便可用计招降马超矣。”玄德大喜，即时修书，差孙乾赍金珠从小路径至汉中，先来见杨松，说知此事，送了金珠。松大喜，先引孙乾见张鲁，陈言方便。鲁曰：“玄德只是左将军，如何保得我为汉宁王？”杨松曰：“他是大汉皇叔，正合保奏。”张鲁大喜，便差人教马超罢兵。孙乾只在杨松家听回信。不一日，使者回报：“马超言：未成功，不可退兵。”张鲁又遣人去唤，又不肯回。一连三次不至。杨松曰：“此人素无信行，不肯罢兵，其意必反。”遂使人流言云：“马超意欲夺西川，自为蜀主，与父报仇，不肯臣于汉中。”张鲁闻之，问计于杨松。松曰：“一面差人去说与马超：‘汝既欲成功，与汝一月限，要依我三件事。若依得，便有赏；否则必诛：一要取西川，二要刘璋首级，三要退荆州兵。三件事不成，可献头来。’一面教张卫点军守把关隘，防马超兵变。”鲁从之，差人到马超寨中，说这三件事。超大惊曰：“如何变得恁的！”乃与马岱商议：“不如罢兵。”杨松又流言曰：“马超回兵，必怀异心。”于是张卫分七路军，坚守隘口，不放马超兵入。超进退不得，无计可施。孔明谓玄德曰：“今马超正在进退两难之际，亮凭三寸不烂之舌，亲往超寨，说马超来降。”玄德曰：“先生乃吾之股肱心腹，倘有疏虞，如之奈何？”孔明坚意要去，玄德再三不肯放去。正踌躇间，忽报赵云有书荐西川一人来降。玄德召入问之。其人乃建宁俞元人也，姓李，名恢，字德昂。玄德曰：“向日闻公苦谏刘璋，今何故归我？”恢曰：“吾闻：‘良禽相木而栖，贤臣择主而事，’前谏刘益州者，以尽人臣之心；既不能用，知必败矣。今将军仁德布于蜀中，知事必成，故来归耳。”玄德曰：“先生此来，必有益于刘备。”恢曰：“今闻马超在进退两难之际。恢昔在陇西，与彼有一面之交，愿往说马超归降，若何？”孔明曰：“正欲得一人替吾一往。愿闻公之说词。”李恢于孔明耳畔陈说如此如此。孔明大喜，即时遣行。
恢行至超寨，先使人通姓后。马超曰：“吾知李恢乃辩士，今必来说我。”先唤二十刀斧手伏于帐下，嘱曰：“令汝砍，即砍为肉酱！”须臾，李恢昂然而入。马超端坐帐中不动，叱李恢曰：“汝来为何？”恢曰：“特来作说客。”超曰：“吾匣中宝剑新磨。汝试言之，其言不通，便请试剑！”恢笑曰：“将军之祸不远矣！但恐新磨之剑，不能试吾之头，将欲自试也！”超曰：“吾有何祸？”恢曰：“吾闻越之西子，善毁者不能闭其美；齐之无盐，善美者不能掩其丑；日中则昃，月满则亏：此天下之常理也。今将军与曹操有杀父之仇，而陇西又有切齿之恨；前不能救刘璋而退荆州之兵，后不能制杨松而见张鲁之面；目下四海难容，一身无主；若复有渭桥之败，冀城之失，何面目见天下之人乎？”超顿首谢曰：“公言极善，但超无路可行。”恢曰：“公既听吾言，帐下何故伏刀斧手？”超大惭，尽叱退。恢曰：“刘皇叔礼贤下士，吾知其必成，故舍刘璋而归之。公之尊人，昔年曾与皇叔约共讨贼，公何不背暗投明，以图上报父仇，下立功名乎？”马超大喜，即唤杨柏入，一剑斩之，将首极共恢一同上关来降玄德。
玄德亲自接入，待以上宾之礼。超顿首谢曰：“今遇明主，如拨云雾而见青天！”时孙乾已回。玄德复命霍峻、孟达守关，便撤兵来取成都。赵云、黄忠接入绵竹。人报蜀将刘晙、马汉引军到。赵云曰：“某愿往擒此二人！”言讫，上马引军出。玄德在城上管待马超吃酒。未曾安席，子龙已斩二人之头，献于筵前。马超亦惊，倍加敬重。超曰：“不须主公军马厮杀，超自唤出刘璋来降。如不肯降，超自与弟马岱取成都，双手奉献。”玄德大喜。是日尽欢。
却说败兵回到益州，报刘璋。璋大惊，闭门不出。人报城北马超救兵到，刘璋方敢登城望之。见马超、马岱立于城下，大叫：“请刘季玉答话。”刘璋在城上问之。超在马上以鞭指曰：“吾本领张鲁兵来救益州，谁想张鲁听信杨松谗言，反欲害我。今已归降刘皇叔。公可纳士拜降，免致生灵受苦。如或执迷，吾先攻城矣！”刘璋惊得面如土色，气倒于城上。众官救醒。璋曰：“吾之不明，悔之何及！不若开门投降，以救满城百姓。”董和曰：“城中尚有兵三万余人；钱帛粮草，可支一年：奈何便降？”刘璋曰：“吾父子在蜀二十余年，无恩德以加百姓；攻战三年，血肉捐于草野，皆我罪也。我心何安？不如投降以安百姓。”众人闻之，皆堕泪。忽一人进曰：“主公之言，正合天意。”视之，乃巴西西充国人也，姓谯，名周，字允南。此人素晓天文。璋问之，周曰：“某夜观乾象，见群星聚于蜀郡；其大星光如皓月，乃帝王之象也。况一载之前，小儿谣云：若要吃新饭，须待先主来。此乃预兆。不可逆天道。”黄权、刘巴闻言皆大怒，欲斩之。刘璋挡住。忽报：“蜀郡太守许靖，逾城出降矣。”刘璋大哭归府。
次日，人报刘皇叔遣幕宾简雍在城下唤门。璋令开门接入。雍坐车中，傲睨自若。忽一人掣剑大喝曰：“小辈得志，傍若无人！汝敢藐视吾蜀中人物耶！”雍慌下车迎之。此人乃广汉绵竹人也，姓秦，名宓，字子敕。雍笑曰：“不识贤兄，幸勿见责。”遂同入见刘璋，具说玄德宽洪大度，并无相害之意。于是刘璋决计投降，厚待简雍。次日，亲赍印绶文籍，与简雍同车出城投降。玄德出寨迎接，握手流涕曰：“非吾不行仁义，奈势不得已也！”共入寨，交割印绶文籍，并马入城。
宏德入成都，百姓香花灯烛，迎门而接。玄德到公厅，升堂坐定。郡内诸官，皆拜于堂下！惟黄权、刘巴，闭门不出。众将忿怒，欲往杀之。玄德慌忙传令曰：“如有害此二人者，灭其三族！”玄德亲自登门，请二人出仕。二人感玄德恩礼，乃出。孔明请曰：“今西川平定，难容二主，可将刘璋送去荆州。”玄德曰：“吾方得蜀郡，未可令季玉远去。”孔明曰：“刘璋失基业者，皆因太弱耳。主公若以妇人之仁，临事不决，恐此土难以长久。”玄德从之，设一大宴，请刘璋收拾财物，佩领振威将军印绶，令将妻子良贱，尽赴南郡公安住歇，即日起行。玄德自领益州牧。其所降文武，尽皆重赏，定拟名爵：严颜为前将军，法正为蜀郡太守，董和为掌军中郎将，许靖为左将军长史，庞义为营中司马，刘巴为左将军，黄权为右将军。其余吴懿、费观、彭□、卓膺、李严、吴兰、雷铜、李恢、张翼、秦宓、谯周、吕义，霍峻、邓芝、杨洪、周群、费祎、费诗、孟达，文武投降官员，共六十余人，并皆擢用。诸葛亮为军师，关云长为荡寇将军、汉寿亭侯，张飞为征虏将军、新亭侯，赵云为镇远将军，黄忠为征西将军，魏延为扬武将军，马超为平西将军。孙乾、简雍、糜竺、糜芳、刘封、吴班、关平、周仓、廖化、马良、马谡、蒋琬、伊籍，及旧日荆襄一班文武官员，尽皆升赏。遣使赍黄金五百斤、白银一千斤、钱五千万、蜀锦一千匹，赐与云长。其余官将，给赏有差。杀牛宰马，大饷士卒。开仓赈济百姓，军民大悦。
益州既定，玄德欲将成都有名田宅，分赐诸官。赵云谏曰：“益州人民，屡遭兵火，田宅皆空；今当归还百姓，令安居复业，民心方服；不宜夺之为私赏也。”玄德大喜，从其言。使诸葛军师定拟治国条例，刑法颇重。法正曰：“昔高祖约法三章，黎民皆感其德。愿军师宽刑省法。以慰民望。”孔明曰：“君知其一、未知其二：秦用法暴虐，万民皆怨，故高祖以宽仁得之。今刘璋暗弱，德政不举，威刑不肃；君臣之道，渐以陵替。宠之以位，位极则残；顺之以恩，恩竭则慢。所以致弊，实由于此。吾今威之以法，法行则知恩；限之以爵，爵加则知荣。恩荣并济，上下有节。为治之道，于斯著矣。”法正拜服。自此军民安堵。四十一州地面，分兵镇抚，并皆平定。法正为蜀郡太守，凡平日一餐之德，睚毗之怨，无不报复。或告孔明曰：“孝直太横，宜稍斥之。”孔明曰：“昔主公困守荆州，北畏曹操，东惮孙权，赖孝直为之辅翼，遂翻然翱翔，不可复制。今奈何禁止孝直，使不得少行其意耶？”因竟不问。法正闻之，亦自敛戢。
一日，玄德正与孔明闲叙，忽报云长遣关平来谢所赐金帛。玄德召入。平拜罢，呈上书信曰：“父亲知马超武艺过人，要入川来与之比试高低。教就禀伯父此事。”玄德大惊曰：“若云长入蜀，与孟起比试，势不两立。”孔明曰：“无妨。亮自作书回之。”玄德只恐云长性急，便教孔明写了书，发付关平星夜回荆州。平回至荆州，云长问曰：“我欲与马孟起比试，汝曾说否？”平答曰：“军师有书在此。”云长拆开视之。其书曰：“亮闻将军欲与孟起分别高下。以亮度之：孟起虽雄烈过人，亦乃黥布、彭越之徒耳；当与翼德并驱争先，犹未及美髯公之绝伦超群也。今公受任守荆州，不为不重；倘一入川，若荆州有失。罪莫大焉。惟冀明照。”云长看毕，自绰其髯笑曰：“孔明知我心也。”将书遍示宾客，遂无入川之意。
却说东吴孙权，知玄德并吞西川，将刘璋逐于公安，遂召张昭、顾雍商议曰：“当初刘备借我荆州时，说取了西川，便还荆州。今已得巴蜀四十一州，须用取索汉上诸郡。如其不还，即动干戈。”张昭曰：“吴中方宁，不可动兵。昭有一计，使刘备将荆州双手奉还主公。”正是：西蜀方开新日月，东吴又索旧山川。
未知其计如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943845, '5b9b6da017d00900341747f9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639204, '三国演义 · 第六十六回 · 关云长单刀赴会 伏皇后为国捐生', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说孙权要索荆州。张昭献计曰：“刘备所倚仗者，诸葛亮耳。其兄诸葛瑾今仕于吴，何不将瑾老小执下，使瑾入川告其弟，令劝刘备交割荆州：‘如其不还，必累及我老小。’亮念同胞之情，必然应允。”权曰：“诸葛瑾乃诚实君子，安忍拘其老小？”昭曰：“明教知是计策，自然放心。”权从之，召诸葛瑾老小，虚监在府；一面修书，打发诸葛瑾往西川去。
不数日，早到成都，先使人报知玄德。玄德问孔明曰：“令兄此来为何？”孔明曰：“来索荆州耳。”玄德曰：“何以答之？”孔明曰：“只须如此如此。”计会已定，孔明出郭接瑾。不到私宅，径入宾馆。参拜毕，瑾放声大哭。亮曰：“兄长有事但说。何故发哀？”瑾曰：“吾一家老小休矣！”亮曰：“莫非为不还荆州乎？因弟之故，执下兄长老小，弟心何安？兄休忧虑，弟自有计还荆州便了。”
瑾大喜，即同孔明入见玄德，呈上孙权书。玄德看了，怒曰：“孙权既以妹嫁我，却乘我不在荆州，竟将妹子潜地取去，情理难容！我正要大起川兵，杀下江南，报我之恨，却还想来索荆州乎！”孔明哭拜于地，曰：“吴侯执下亮兄长老小，倘若不还，吾兄将全家被戮。兄死，亮岂能独生？望主公看亮之面，将荆州还了东吴，全亮兄弟之情！”玄德再三不肯，孔明只是哭求。玄德徐徐曰：“既如此，看军师面，分荆州一半还之：将长沙、零陵、桂阳三郡与他。”亮曰：“既蒙见允，便可写书与云长令交割三郡。”玄德曰：“子瑜到彼，须用善言求吾弟。吾弟性如烈火，吾尚惧之。切宜仔细。”
瑾求了书，辞了玄德，别了孔明，登途径到荆州。云长请入中堂，宾主相叙。瑾出玄德书曰：“皇叔许先以三郡还东吴，望将军即日交割，令瑾好回见吾主。”云长变色曰：“吾与吾兄桃园结义，誓共匡扶汉室。荆州本大汉疆土，岂得妄以尺寸与人？‘将在外，君命有所不受’。虽吾兄有书来，我却只不还。”瑾曰：“今吴侯执下瑾老小，若不得荆州，必将被诛。望将军怜之！”云长曰：“此是吴侯谲计，如何瞒得我过！”瑾曰：“将军何太无面目？”云长执剑在手曰：“休再言！此剑上并无面目！”关平告曰：“军师面上不好看，望父亲息怒。”云长曰：“不看军师面上，教你回不得东吴！”
瑾满面羞惭，急辞下船，再往西川见孔明。孔明已自出巡去了。瑾只得再见玄德，哭告云长欲杀之事。玄德曰：“吾弟性急，极难与言。子瑜可暂回，容吾取了东川、汉中诸郡，调云长往守之，那时方得交付荆州。”
瑾不得已，只得回东吴见孙权，具言前事。孙权大怒曰：“子瑜此去，反覆奔走，莫非皆是诸葛亮之计？”瑾曰：“非也。吾弟亦哭告玄德，方许将三郡先还，又无奈云长恃顽不肯，”孙权曰：“既刘备有先还三郡之言，便可差官前去长沙、零陵、桂阳三郡赴任，且看如何。”瑾曰：“主公所言极善。”权乃令瑾取回老小，一面差官往三郡赴任。不一日，三郡差去官吏，尽被逐回，告孙权曰：“关云长不肯相容，连夜被逐回吴。迟后者便要杀。”
孙权大怒，差人召鲁肃责之曰：“子敬昔为刘备作保，借吾荆州；今刘备已得西川，不肯归还，子敬岂得坐视？”肃曰：“肃已思得一计，正欲告主公。”权问：“何计？”肃曰：“今屯兵于陆口，使人请关云长赴会。若云长肯来，以善言说之；如其不从，伏下刀斧手杀之。如彼不肯来，随即进兵，与决胜负，夺取荆州便了。”孙权曰：“正合吾意。可即行之。”阐泽进曰：“不可，关云长乃世之虎将，非等闲可及。恐事不谐，反遭其害。”孙权怒曰：“若如此，荆州何日可得！”便命鲁肃速行此计。肃乃辞孙权，至陆口，召吕蒙、甘宁商议，设宴于陆口寨外临江亭上，修下请书，选帐下能言快语一人为使，登舟渡江。江口关平问了，遂引使人入荆州，叩见云长，具道鲁肃相邀赴会之意，呈上请书。云长看书毕，谓来人曰：“既子敬相请，我明日便来赴宴。汝可先回。”
使者辞去。关平曰：“鲁肃相邀，必无好意；父亲何故许之？”云长笑曰：“吾岂不知耶？此是诸葛瑾回报孙权，说吾不肯还三郡，故令鲁肃屯兵陆口，邀我赴会，便索荆州。吾若不往，道吾怯矣。吾来日独驾小舟，只用亲随十余人，单刀赴会，看鲁肃如何近我！”平谏曰：“父亲奈何以万金之躯，亲蹈虎狼之穴？恐非所以重伯父之寄托也。”云长曰：“吾于千枪万刃之中，矢石交攻之际，匹马纵横，如入无人之境；岂忧江东群鼠乎！”马良亦谏曰：“鲁肃虽有长者之风，但今事急，不容不生异心。将军不可轻往。”云长曰：“昔战国时赵人蔺相如，无缚鸡之力，于渑池会上，觑秦国君臣如无物；况吾曾学万人敌者乎！既已许诺，不可失信。”良曰：“纵将军去，亦当有准备。”云长曰：“只教吾儿选快船十只，藏善水军五百，于江上等候。看吾认旗起处，便过江来。”平领命自去准备。却说使者回报鲁肃，说云长慨然应允，来日准到。肃与吕蒙商议：“此来若何？”蒙曰：“彼带军马来，某与甘宁各人领一军伏于岸侧，放炮为号，准备厮杀；如无军来，只于庭后伏刀斧手五十人，就筵间杀之。”计会已定。次日，肃令人于岸口遥望。辰时后，见江面上一只船来，梢公水手只数人，一面红旗，风中招飐，显出一个大“关”字来。船渐近岸，见云长青巾绿袍，坐于船上；傍边周仓捧着大刀；八九个关西大汉，各跨腰刀一口。鲁肃惊疑，接入庭内。叙礼毕，入席饮酒，举杯相劝，不敢仰视。云长谈笑自若。
酒至半酣，肃曰：“有一言诉与君侯，幸垂听焉：昔日令兄皇叔，使肃于吾主之前，保借荆州暂住，约于取川之后归还。今西川已得，而荆州未还，得毋失信乎？”云长曰：“此国家之事，筵间不必论之。”肃曰：“吾主只区区江东之地，而肯以荆州相借者，为念君侯等兵败远来，无以为资故也。今已得益州，则荆州自应见还；乃皇叔但肯先割三郡，而君侯又不从，恐于理上说不去。”云长曰：“乌林之役，左将军亲冒矢石，戮力破敌，岂得徒劳而无尺土相资？今足下复来索地耶？”肃曰：“不然。君侯始与皇叔同败于长坂，计穷力竭，将欲远窜，吾主矜念皇叔身无处所，不爱土地，使有所托足，以图后功；而皇叔愆德隳好，已得西川，又占荆州，贪而背义，恐为天下所耻笑。惟君侯察之。”云长曰：“此皆吾兄之事，非某所宜与也。”肃曰：“某闻君侯与皇叔桃园结义，誓同生死。皇叔即君侯也，何得推托乎？”云长未及回答，周仓在阶下厉声言曰：“天下土地，惟有德者居之。岂独是汝东吴当有耶！”云长变色而起，夺周仓所捧大刀，立于庭中，目视周仓而叱曰：“此国家之事，汝何敢多言！可速去！”仓会意，先到岸口，把红旗一招。关平船如箭发，奔过江东来。云长右手提刀，左手挽住鲁肃手，佯推醉曰：“公今请吾赴宴，莫提起荆州之事。吾今已醉，恐伤故旧之情。他日令人请公到荆州赴会，另作商议。”鲁肃魂不附体，被云长扯至江边。吕蒙、甘宁各引本部军欲出，见云长手提大刀，亲握鲁肃，恐肃被伤，遂不敢动。云长到船边，却才放手，早立于船首，与鲁肃作别。肃如痴似呆，看关公船已乘风而去。后人有诗赞关公曰：“藐视吴臣若小儿，单刀赴会敢平欺。当年一段英雄气，尤胜相如在渑池。”云长自回荆州。鲁肃与吕蒙共议：“此计又不成，如之奈何？”蒙曰：“可即申报主公，起兵与云长决战。”肃即时使人申报孙权。权闻之大怒，商议起倾国之兵，来取荆州。忽报：“曹操又起三十万大军来也！”权大惊，且教鲁肃休惹荆州之兵，移兵向合淝、濡须，以拒曹操。
却说操将欲起程南征，参军傅干，字彦材，上书谏操。书略曰：“干闻用武则先威，用文则先德；威德相济，而后王业成。往者天下大乱，明公用武攘之，十平其九；今未承王命者，吴与蜀耳。吴有长江之险，蜀有崇山之阻，难以威胜。愚以为：且宜增修文德，按甲寝兵，息军养士，待时而动。今若举数十万之众，顿长江之滨，倘贼凭险深藏，使我士马不得逞其能，奇变无所用其权，则天威屈矣。惟明公详察焉。”曹操览之，遂罢南征，兴设学校，延礼文士。于是侍中王粲、杜袭、卫凯、和洽四人，议欲尊曹操为“魏王”。中书令荀攸曰：“不可。丞相官至魏公，荣加九锡，位已极矣。今又进升王位，于理不可。”曹操闻之，怒曰：“此人欲效荀彧耶！”荀攸知之，忧愤成疾，卧病十数日而卒，亡年五十八岁。操厚葬之，遂罢“魏王”事。一日，曹操带剑入宫，献帝正与伏后共坐。伏后见操来，慌忙起身。帝见曹操，战栗不已。操曰：“孙权、刘备各霸一方，不尊朝廷，当如之何？”帝曰：“尽在魏公裁处，”操怒曰：“陛下出此言，外人闻之，只道吾欺君也。”帝曰：“君若肯相辅则幸甚；不尔，愿垂恩相舍。”操闻言，怒目视帝，恨恨而出。左右或奏帝曰：“近闻魏公欲自立为王，不久必将篡位。”帝与伏后大哭。后曰：“妾父伏完常有杀操之心，妾今当修书一封，密与父图之”。帝曰：“昔董承为事不密，反遭大祸；今恐又泄漏，朕与汝皆休矣！”后曰：“旦夕如坐针毡，似此为人，不如早亡！妾看宦官中之忠义可托者，莫如穆顺，当令寄此书。”乃即召穆顺入屏后，退去左右近侍。帝后大哭告顺曰：“操贼欲为魏王，早晚必行篡夺之事。朕欲令后父伏完密图此贼，而左右之人，俱贼心腹，无可托者。欲汝将皇后密书，寄与伏完。量汝忠义，必不负朕。”顺泣曰：“臣感陛下大恩，敢不以死报！臣即请行。”后乃修书付顺。顺藏书于发中，潜出禁宫，径至伏完宅，将书呈上。完见是伏后亲笔，乃谓穆顺曰：“操贼心腹甚众，不可遽图。除非江东孙权、西川刘备，二处起兵于外，操必自往。此时却求在朝忠义之臣，一同谋之。内外夹攻，庶可有济。”顺曰：“皇丈可作书覆帝后，求密诏，暗遣人往吴、蜀二处，令约会起兵，讨贼救主。”伏完即取纸写书付顺。顺乃藏于头髻内，辞完回宫。
原来早有人报知曹操。操先于宫门等候。穆顺回遇曹操，操问：“那里去来？”顺答曰：“皇后有病，命求医去。”操曰：“召得医人何在？”顺曰：“还未召至。”操喝左右，遍搜身上，并无夹带，放行。忽然风吹落其帽。操又唤回，取帽视之，遍观无物，还帽令戴。穆顺双手倒戴其帽。操心疑，令左右搜其头发中，搜出伏完书来。操看时，书中言欲结连孙、刘为外应。操大怒，执下穆顺于密室问之，顺不肯招。操连夜点起甲兵三千，围住伏完私宅，老幼并皆拿下；搜出伏后亲笔之书，随将伏氏三族尽皆下狱。平明，使御林将军郗虑持节入宫，先收皇后玺绶。是日，帝在外殿，见郗虑引三百甲兵直入。帝问曰：“有何事？”虑曰：“奉魏公命收皇后玺。”帝知事泄，心胆皆碎。虑至后宫，伏后方起。虑便唤管玺绶人索取玉玺而出。伏后情知事发，便于殿后椒房内夹壁中藏躲。少顷，尚书令华歆引五百甲兵入到后殿，问宫人：伏后何在？”宫人皆推不知。歆教甲兵打开朱户，寻觅不见；料在壁中，便喝甲士破壁搜寻。歆亲自动手揪后头髻拖出。后曰：“望免我一命！”歆叱曰：“汝自见魏公诉去！”后披发跣足，二甲士推拥而出。原来华歆素有才名，向与邴原、管宁相友善。时人称三人为一龙：华歆为龙头，邴原为龙腹，管宁为龙尾。一日，宁与歆共种园蔬，锄地见金。宁挥锄不顾；歆拾而视之，然后掷下。又一日，宁与歆同坐观书，闻户外传呼之声，有贵人乘轩而过。宁端坐不动，歆弃书往观。宁自此鄙歆之为人，遂割席分坐，不复与之为友。后来管宁避居辽东，常戴白帽，坐卧一楼，足不履地，终身不肯仕魏；而歆乃先事孙权，后归曹操，至此乃有收捕伏皇后一事。后人有诗叹华歆曰：华歆当日逞凶谋，破壁生将母后收。助虐一朝添虎翼，骂名千载笑“龙头”！又有诗赞管宁曰：“辽东传有管宁楼，人去楼空名独留。笑杀子鱼贪富贵，岂如白帽自风流。”
且说华歆将伏后拥至外殿。帝望见后，乃下殿抱后而哭。歆曰：“魏公有命，可速行！”后哭谓帝曰：“不能复相活耶？”帝曰：“我命亦不知在何时也！”甲士拥后而去，帝捶胸大恸。见郗虑在侧，帝曰：“郗公！天下宁有是事乎！”哭倒在地。郗虑令左右扶帝入宫。华歆拿伏后见操。操骂曰：“吾以诚心待汝等，汝等反欲害我耶！吾不杀汝，汝必杀我！”喝左右乱棒打死。随即入宫，将伏后所生二子，皆酖杀之。当晚将伏完、穆顺等宗族二百余口，皆斩于市。朝野之人，无不惊骇。时建安十九年十一月也。后人有诗叹曰：“曹瞒凶残世所无，伏完忠义欲何如。可怜帝后分离处，不及民间妇与夫！”
献帝自从坏了伏后，连日不食。操入曰：“陛下无忧，臣无异心。臣女已与陛下为贵人，大贤大孝，宜居正宫。”献帝安敢不从。于建安二十年正月朔，就庆贺正旦之节，册立曹操女曹贵人为正宫皇后。群下莫敢有言。
此时曹操威势日甚。会大臣商议收吴灭蜀之事。贾诩曰：“须召夏侯惇、曹仁二人回，商议此事。”操即时发使，星夜唤回。夏侯惇未至，曹仁先到，连夜便入府中见操。操方被酒而卧，许褚仗剑立于堂门之内，曹仁欲入，被许褚当住。曹仁大怒曰：“吾乃曹氏宗族，汝何敢阻当耶？”许褚曰：“将军虽亲，乃外藩镇守之官；许褚虽疏，现充内侍。主公醉卧堂上，不敢放入。”仁乃不敢入。曹操闻之，叹曰：“许褚真忠臣也！”不数日，夏侯惇亦至，共议征伐。惇曰：“吴、蜀急未可攻，宜先取汉中张鲁，以得胜之兵取蜀，可一鼓而下也。”曹操曰：“正合吾意。”遂起兵西征。正是：方逞凶谋欺弱主，又驱劲卒扫偏邦。
未知后事如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536944217, '5b9b6df11b69e6005ba2aeda', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639205, '三国演义 · 第六十七回 · 曹操平定汉中地 张辽威震逍遥津', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说曹操兴师西征，分兵三队：前部先锋夏侯渊；张郃；操自领诸将居中；后部曹仁、夏侯惇，押运粮草。早有细作报入汉中来。张鲁与弟张卫，商议退敌之策。卫曰：“汉中最险无如阳平关；可于关之左右，依山傍林，下十余个寨栅，迎敌曹兵。兄在汉宁，多拨粮草应付。”张鲁依言，遣大将杨昂、杨任，与其弟即日起程。军马到阳平关，下寨已定。夏侯渊、张郃前军随到，闻阳平关已有准备，离关一十五里下寨。是夜，军士疲困，各自歇息。忽寨后一把火起，杨昂、杨任两路兵杀来劫寨。夏侯渊、张郃急上得马，四下里大兵拥入，曹兵大败，退见曹操。操怒曰：“汝二人行军许多年，岂不知‘兵若远行疲困，可防劫寨’？如何不作准备？”欲斩二人，以明军法。众官告免。操次日自引兵为前队，见山势险恶，林木丛杂，不知路径，恐有伏兵，即引军回寨，谓许褚、徐晃二将曰：“吾若知此处如此险恶，必不起兵来。”许褚曰：“兵已至此，主公不可惮劳。”次日，操上马，只带许褚、徐晃二人，来看张卫寨栅。三匹马转过山坡，早望见张卫寨栅。操扬鞭遥指，谓二将曰：“如此坚固，急切难下！”言未已，背后一声喊起，箭如雨发。杨昂、杨任分两路杀来。操大惊。许褚大呼曰：“吾当敌贼！徐公明善保主公。”说罢，提刀纵马向前，力敌二将。杨昂、杨任不能当许褚之勇，回马退去，其余不敢向前。徐晃保着曹操奔过山坡，前面又一军到；看时，却是夏侯渊；张郃二将，听得喊声，故引军杀来接应。于是杀退杨昂、杨任，救得曹操回寨。操重赏四将。
自此两边相拒五十余日，只不交战。曹操传令退军。贾诩曰：“贼势未见强弱，主公何故自退耶？”操曰：“吾料贼兵每日提备，急难取胜。吾以退军为名，使贼懈而无备，然后分轻骑抄袭其后，必胜贼矣。”贾诩曰：“丞相神机，不可测也。”于是令夏侯渊；张郃分兵两路，各引轻骑三千，取小路抄阳平关后。曹操一面引大军拔寨尽起。杨昂听得曹兵退，请杨任商议，欲乘势击之。杨任曰：“操诡计极多，未知真实，不可追赶。”杨昂曰：“公不往，吾当自去。”杨任苦谏不从。杨昂尽提五寨军马前进，只留些少军士守寨。
是日，大雾迷漫，对面不相见。杨昂军至半路，不能行，且权扎住。却说夏侯渊一军抄过山后，见重雾垂空，又闻人语马嘶，恐有伏兵，急催人马行动，大雾中误走到杨昂寨前。守寨军士，听得马蹄响，只道是杨昂兵回，开门纳之。曹军一拥而入，见是空寨，便就寨中放起火来。五寨军士，尽皆弃寨而走。比及雾散，杨任领兵来救，与夏侯渊战不数合，背后张郃兵到。杨任杀条大路，奔回南郑。杨昂待要回时，已被夏侯渊、张郃两个占了寨栅。背后曹操大队军马赶来。两下夹攻，四边无路。杨昂欲突阵而出，正撞着张郃。两个交手，被张郃杀死。败兵回投阳平关，来见张卫。原来卫知二将败走，诸营已失，半夜弃关，奔回去了。曹操遂得阳平关并诸寨。张卫、杨任回见张鲁。卫言二将失了隘口，因此守关不住。张鲁大怒，欲斩杨任。任曰：“某曾谏杨昂，休追操兵。他不肯听信，故有此败。任再乞一军前去挑战，必斩曹操。如不胜，甘当军令。”张鲁取了军令状。杨任上马，引二万军离南郑下寨。却说曹操提军将进，先令夏侯渊领五千军，往南郑路上哨探，正迎着杨任军马，两军摆开。任遣部将昌奇出马，与渊交锋；战不三合，被渊一刀斩于马下。杨任自挺枪出马，与渊战三十余合，不分胜负。渊佯败而走，任从后追来；被渊用拖刀计，斩于马下。军士大败而回。曹操知夏侯渊斩了杨任，即时进兵，直抵南郑下寨。张鲁慌聚文武商议。阎圃曰：“某保一人，可敌曹操手下诸将。”鲁问是谁。圃曰：“南安庞德，前随马超投主公；后马超往西川，庞德卧病不曾行。现今蒙主公恩养，何不令此人去？”
张鲁大喜，即召庞德至，厚加赏劳；点一万军马，令庞德出。离城十余里，与曹兵相对，庞德出马搦战。曹操在渭桥时，深知庞德之勇，乃嘱诸将曰：“庞德乃西凉勇将，原属马超；今虽依张鲁，未称其心。吾欲得此人。汝等须皆与缓斗，使其力乏，然后擒之。”张郃先出，战了数合便退。夏侯渊也战数合退了。徐晃又战三五合也退了。临后许褚战五十余合亦退。庞德力战四将，并无惧怯。各将皆于操前夸庞德好武艺。曹操心中大喜，与众将商议：“如何得此人投降？”贾诩曰：“某知张鲁手下，有一谋士杨松。其人极贪贿赂。今可暗以金帛送之，使谮庞德于张鲁，便可图矣。”操曰：“何由得人入南郑？”诩曰：“来日交锋，诈败佯输，弃寨而走，使庞德据我寨。我却于夤夜引兵劫寨，庞德必退入城。却选一能言军士，扮作彼军，杂在阵中，便得入城。”操听其计，选一精细军校，重加赏赐，付与金掩心甲一副，今披在贴肉，外穿汉中军士号衣，先于半路上等候。
次日，先拨夏侯渊；张郃两枝军，远去埋伏；却教徐晃挑战，不数合败走。庞德招军掩杀，曹兵尽退。庞德却夺了曹操寨栅。见寨中粮草极多，大喜，即时申报张鲁；一面在寨中设宴庆贺。当夜二更之后，忽然三路火起：正中是徐晃、许褚，左张郃，右夏侯渊。三路军马，齐来劫寨。庞德不及提备，只得上马冲杀出来，望城而走。背后三路兵追来。庞德急唤开城门，领兵一拥而入。
此时细作已杂到城中，径投杨松府下谒见，具说：“魏公曹丞相久闻盛德，特使某送金甲为信。更有密书呈上。”松大喜，看了密书中言语，谓细作曰：“上覆魏公，但请放心。某自有良策奉报。”打发来人先回，便连夜入见张鲁，说庞德受了曹操贿赂，卖此一阵。张鲁大怒，唤庞德责骂，欲斩之。阎圃苦谏。张鲁曰：“你来日出战，不胜必斩！”庞德抱恨而退。次日，曹兵攻城，庞德引兵冲出。操令许褚交战。褚诈败，庞德赶来。操自乘马于山坡上唤曰：“庞令明何不早降？”庞德寻思：“拿住曹操，抵一千员上将！”遂飞马上坡。一声喊起，天崩地塌，连人和马，跌入陷坑内去；四壁钩索一齐上前，活捉了庞德，押上坡来。曹操下马，叱退军士，亲释其缚，问庞德肯降否。庞德寻思张鲁不仁，情愿拜降。曹操亲扶上马，共回大寨，故意教城上望见。人报张鲁，德与操并马而行。鲁益信杨松之言为实。次日，曹操三面竖立云梯，飞炮攻打。张鲁见其势已极，与弟张卫商议。卫曰：“放火尽烧仓廪府库，出奔南山，去守巴中可也。”杨松曰：“不如开门投降。”张鲁犹豫不定。卫曰：“只是烧了便行。”张鲁曰：“我向本欲归命国家，而意未得达；今不得已而出奔，仓廪府库，国家之有，不可废也。”遂尽封锁。是夜二更，张鲁引全家老小，开南门杀出。曹操教休追赶；提兵入南郑，见鲁封闭库藏，心甚怜之。遂差人往巴中，劝使投降。张鲁欲降，张卫不肯。杨松以密书报操，便教进兵，松为内应。操得书，亲自引兵往巴中。张鲁使弟卫领兵出敌，与许褚交锋；被褚斩于马下。败军回报张鲁，鲁欲坚守。杨松曰：“今若不出，坐而待毙矣。某守城，主公当亲与决一死战。”鲁从之。阎圃谏鲁休出。鲁不听，遂引军出迎。未及交锋，后军已走。张鲁急退，背后曹兵赶来。鲁到城下，杨松闭门不开。张鲁无路可走，操从后追至，大叫：“何不早降！”鲁乃下马投拜。操大喜；念其封仓库之心，优礼相待，封鲁为镇南将军。阎圃等皆封列侯。于是汉中皆平。曹操传令各郡分设太守，置都尉，大赏士卒。惟有杨松卖主求荣，即命斩之于市曹示众。后人有诗叹曰：“妨贤卖主逞奇功，积得金银总是空。家未荣华身受戮，令人千载笑杨松！”
曹操已得东川，主簿司马懿进曰：“刘备以诈力取刘璋，蜀人尚未归心。今主公已得汉中，益州震动。可速进兵攻之，势必瓦解。智者贵于乘时，时不可失也。”曹操叹曰：“‘人苦不知足，既得陇，复望蜀’耶？”刘晔曰：“司马仲达之言是也。若少迟缓，诸葛亮明于治国而为相，关、张等勇冠三军而为将，蜀民既定，据守关隘，不可犯矣。”操曰：“士卒远涉劳苦，且宜存恤。”遂按兵不动。却说西川百姓，听知曹操已取东川，料必来取西川，一日之间，数遍惊恐。玄德请军师商议。孔明曰：“亮有一计。曹操自退。”玄德问何计。孔明曰：“曹操分军屯合淝，惧孙权也。今我若分江夏、长沙、桂阳三郡还吴，遣舌辩之士，陈说利害，令吴起兵袭合淝，牵动其势，操必勒兵南向矣。”玄德问：“谁可为使？”伊籍曰：“某愿往。”玄德大喜，遂作书具礼，令伊籍先到荆州，知会云长，然后入吴。
到秣陵，来见孙权，先通了姓名。权召籍入。籍见权礼毕，权问曰：“汝到此何为？”籍曰：“昨承诸葛子瑜取长沙等三郡，为军师不在，有失交割，今传书送还。所有荆州南郡、零陵，本欲送还；被曹操袭取东川，使关将军无容身之地。今合淝空虚，望君侯起兵攻之，使曹操撤兵回南。吾主若取了东川，即还荆州全土。”权曰：“汝且归馆舍，容吾商议。”伊籍退出，权问计于众谋士。张昭曰：“此是刘备恐曹操取西川，故为此谋。虽然如此，可因操在汉中。乘势取合淝，亦是上计。”权从之，发付伊籍回蜀去讫，便议起兵攻操：令鲁肃收取长沙、江夏、桂阳三郡，屯兵于陆口，取吕蒙、甘宁回；又去余杭取凌统回。不一日，吕蒙、甘宁先到。蒙献策曰：“现今曹操令庐江太守朱光，屯兵于皖城，大开稻田，纳谷于合淝，以充军实。今可先取皖城，然后攻合淝。”权曰：“此计甚合吾意。”遂教吕蒙、甘宁为先锋，蒋钦、潘璋为合后，权自引周泰、陈武、董袭、徐盛为中军。时程普、黄盖、韩当在各处镇守，都未随征。却说军马渡江，取和州，径到皖城。皖城太守朱光，使人往合淝求救；一面固守城池，坚壁不出。权自到城下看时，城上箭如雨发，射中孙权麾盖。权回寨，问众将曰：“如何取得皖城？”董袭曰：“可差军士筑起土山攻之。”徐盛曰：“可竖云梯，造虹桥，下观城中而攻之。”吕蒙曰：“此法皆费日月而成，合淝救军一至，不可图矣。今我军初到，士气方锐，正可乘此锐气，奋力攻击。来日平明进兵，午未时便当破城。”权从之。次日五更饭毕，三军大进。城上矢石齐下。甘宁手执铁链，冒矢石而上。朱光令弓弩手齐射，甘宁拨开箭林，一链打倒朱光。吕蒙亲自擂鼓。士卒皆一拥而上，乱刀砍死朱光。余众多降，得了皖城，方才辰时。张辽引军至半路，哨马回报皖城已失。辽即回兵归合淝。
孙权入皖城，凌统亦引军到。权慰劳毕，大犒三军，重赏吕蒙，甘宁诸将，设宴庆功。吕蒙逊甘宁上坐，盛称其功劳。酒至半酣，凌统想起甘宁杀父之仇，又见吕蒙夸美之，心中大怒，瞪目直视良久，忽拔左右所佩之剑，立于筵上曰：“筵前无乐，看吾舞剑。”甘宁知其意，推开果桌起身，两手取两枝戟挟定，纵步出曰：“看我筵前使戟。”吕蒙见二人各无好意，便一手挽牌，一手提刀，立于其中曰：“二公虽能，皆不如我巧也。”说罢，舞起刀牌，将二人分于两下。早有人报知孙权。权慌跨马，直至筵前。众见权至，方各放下军器。权曰：“吾常言二人休念旧仇，今日又何如此？”凌统哭拜于地。孙权再三劝止。至次日，起兵进取合淝，三军尽发。
张辽为失了皖城，回到合淝，心中愁闷。忽曹操差薛悌送木匣一个，上有操封，傍书云：“贼来乃发。”是日报说孙权自引十万大军，来攻合淝。张辽便开匣观之。内书云：“若孙权至，张、李二将军出战，乐将军守城。”张辽将教帖与李典、乐进观之。乐进曰：“将军之意若何？”张辽曰：“主公远征在外，吴兵以为破我必矣。今可发兵出迎，奋力与战，折其锋锐，以安众心，然后可守也。”李典素与张辽不睦，闻辽此言，默然不答。乐进见李典不语，便道：“贼众我寡，难以迎敌，不如坚守。”张辽曰：“公等皆是私意，不顾公事。吾今自出迎敌，决一死战。”便教左右备马。李典慨然而起曰：“将军如此，典岂敢以私憾而忘公事乎？愿听指挥。”张辽大喜曰：“既曼成肯相助，来日引一军于逍遥津北埋伏：待吴兵杀过来，可先断小师桥，吾与乐文谦击之。”李典领命，自去点军埋伏。却说孙权令吕蒙、甘宁为前队，自与凌统居中，其余诸将陆续进发，望合淝杀来。吕蒙、甘宁前队兵进，正与乐进相迎。甘宁出马与乐进交锋，战不数合，乐进诈败而走。甘宁招呼吕蒙一齐引军赶去。孙权在第二队，听得前军得胜，催兵行至逍遥津北，忽闻连珠炮响，左边张辽一军杀来，右边李典一军杀来。孙权大惊，急令人唤吕蒙、甘宁回救时，张辽兵已到。凌统手下，止有三百余骑，当不得曹军势如山倒。凌统大呼曰：“主公何不速渡小师桥！”言未毕，张辽引二千余骑，当先杀至。凌统翻身死战。孙权纵马上桥，桥南已折丈余，并无一片板。孙权惊得手足无措。牙将谷利大呼曰：“主公可约马退后，再放马向前，跳过桥去。”孙权收回马来有三丈余远，然后纵辔加鞭，那马一跳飞过桥南。后人有诗曰：“的卢当日跳檀溪，又见吴侯败合淝。退后着鞭驰骏骑，逍遥津上玉龙飞。”孙权跳过桥南，徐盛、董袭驾舟相迎。凌统、谷利抵住张辽。甘宁、吕蒙引军回救，却被乐进从后追来，李典又截住厮杀，吴兵折了大半。凌统所领三百余人，尽被杀死。统身中数枪，杀到桥边，桥已折断，绕河而逃。孙权在舟中望见，急令董袭棹舟接之，乃得渡回。吕蒙、甘宁皆死命逃过河南。这一阵杀得江南人人害怕；闻张辽大名，小儿也不敢夜啼。众将保护孙权回营。权乃重赏凌统、谷利，收军回濡须，整顿船只，商议水陆并进；一面差人回江南，再起人马来助战。却说张辽闻孙权在濡须将欲兴兵进取，恐合淝兵少难以抵敌，急令薛悌星夜往汉中，报知曹操，求请救兵。操同众官议曰：“此时可收西川否？”刘晔曰：“今蜀中稍定，已有提备，不可击也。不如撤兵去救合淝之急，就下江南。”操乃留夏侯渊守汉中定军山隘口，留张郃守蒙头岩等隘口。其余军兵拔寨都起，杀奔濡须坞来。正是：铁骑甫能平陇右，旌旄又复指江南。
未知胜负如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943855, '5b9b6e1f9f54540039b85f3b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639206, '三国演义 · 第六十八回 · 甘宁百骑劫魏营 左慈掷杯戏曹操', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说孙权在濡须口收拾军马，忽报曹操自汉中领兵四十万前来救合淝。孙权与谋士计议，先拨董袭、徐盛二人领五十只大船，在濡须口埋伏；令陈武带领人马，往来江岸巡哨。张昭曰：“今曹操远来，必须先挫其锐气。”权乃问帐下曰：“曹操远来，谁敢当先破敌，以挫其锐气？”凌统出曰：“某愿往。”权曰：“带多少军去？”统曰：“三千人足矣。”甘宁曰：“只须百骑，便可破敌，何必三千！”凌统大怒。两个就在孙权面前争竞起来。权曰：“曹军势大，不可轻敌。”乃命凌统带三千军出濡须口去哨探，遇曹兵，便与交战。凌统领命，引着三千人马，离濡须坞。尘头起处，曹兵早到。先锋张辽与凌统交锋，斗五十合，不分胜败。孙权恐凌统有失，令吕蒙接应回营。甘宁见凌统回，即告权曰：“宁今夜只带一百人马去劫曹营；若折了一人一骑，也不算功。”孙权壮之，乃调拨帐下一百精锐马兵付宁；又以酒五十瓶，羊肉五十斤，赏赐军士。甘宁回到营中，教一百人皆列坐，先将银碗斟酒，自吃两碗，乃语百人曰：“今夜奉命劫寨，请诸公各满饮一觞，努力向前。”众人闻言，面面相觑。甘宁见众人有难色，乃拔剑在手，怒叱曰：“我为上将，且不惜命；汝等何得迟疑！”众人见甘宁作色，皆起拜曰：“愿效死力。”甘宁将酒肉与百人共饮食尽，约至二更时候，取白鹅翎一百根，插于盔上为号；都披甲上马，飞奔曹操寨边，拔开鹿角，大喊一声，杀入寨中，径奔中军来杀曹操。原来中军人马，以车仗伏路穿连，围得铁桶相似，不能得进。甘宁只将百骑，左冲右突。曹兵惊慌，正不知敌兵多少，自相扰乱。那甘宁百骑，在营内纵横驰骤，逢着便杀。各营鼓噪，举火如星，喊声大震。甘宁从寨之南门杀出，无人敢当。孙权令周泰引一枝兵来接应。甘宁将百骑回到濡须。操兵恐有埋伏，不敢追袭。后人有诗赞曰：“鼙鼓声喧震地来，吴师到处鬼神哀！百翎直贯曹家寨，尽说甘宁虎将才。”甘宁引百骑到寨，不折一人一骑；至营门，令百人皆击鼓吹笛，口称“万岁”，欢声大震。孙权自来迎接。甘宁下马拜伏。权扶起，携宁手曰：“将军此去，足使老贼惊骇。非孤相舍，正欲观卿胆耳！”即赐绢千匹，利刀百口。宁拜受讫，遂分赏百人。权语诸将曰：“孟德有张辽，孤有甘兴霸，足以相敌也。”
次日，张辽引兵搦战。凌统见甘宁有功，奋然曰：“统愿敌张辽。”权许之。统遂领兵五千，离濡须。权自引甘宁临阵观战。对阵圆处，张辽出马，左有李典，右有乐进。凌统纵马提刀，出至阵前。张辽使乐进出迎。两个斗到五十合，未分胜败。曹操闻知，亲自策马到门旗下来看，见二将酣斗，乃令曹休暗放冷箭。曹休便闪在张辽背后，开弓一箭，正中凌统坐下马，那马直立起来，把凌统掀翻在地。乐进连忙持枪来刺。枪还未到，只听得弓弦响处，一箭射中乐进面门，翻身落马。两军齐出，各救一将回营，鸣金罢战。凌统回寨中拜谢孙权。权曰：“放箭救你者，甘宁也。”凌统乃顿首拜宁曰：“不想公能如此垂恩！”自此与甘宁结为生死之交，再不为恶。且说曹操见乐进中箭，令自到帐中调治。次日，分兵五路来袭濡须：操自领中路；左一路张辽，二路李典；右一路徐晃，二路庞德。每路各带一万人马，杀奔江边来。时董袭、徐盛二将，在楼船上见五路军马来到，诸军各有惧色。徐盛曰：“食君之禄，忠君之事，何惧哉！”遂引猛士数百人，用小船渡过江边，杀入李典军中去了。董袭在船上，令众军擂鼓呐喊助威。忽然江上猛风大作，白浪掀天，波涛汹涌。军士见大船将覆，争下脚舰逃命。董袭仗剑大喝曰：“将受君命，在此防贼，怎敢弃船而去！”立斩下船军士十余人。须臾，风急船覆，董袭竟死于江口水中。徐盛在李典军中，往来冲突。
却说陈武听得江边厮杀，引一军来，正与庞德相遇，两军混战。孙权在濡须坞中，听得曹兵杀到江边，亲自与周泰引军前来助战。正见徐盛在李典军中搅做一团厮杀，便麾军杀入接应。却被张辽、徐晃两枝军，把孙权困在垓心。曹操上高阜处看见孙权被围，急令许褚纵马持刀杀入军中，把孙权军冲作两段，彼此不能相救。
却说周泰从军中杀出，到江边，不见了孙权，勒回马，从外又杀入阵中，问本部军：“主公何在？”军人以手指兵马厚处，曰：“主公被围甚急！”周泰挺身杀入，寻见孙权。泰曰：“主公可随泰杀出。”于是泰在前，权在后，奋力冲突。泰到江边，回头又不见孙权，乃复翻身杀入围中，又寻见孙权。权曰：“弓弩齐发，不能得出，如何？”泰曰：“主公在前，某在后，可以出围。”孙权乃纵马前行。周泰左右遮护，身被数枪，箭透重铠，救得孙权。到江边，吕蒙引一枝水军前来接应下船。权曰：“吾亏周泰三番冲杀，得脱重围。但徐盛在垓心，如何得脱？”周泰曰：“吾再救去。”遂轮枪复翻身杀入重围之中，救出徐盛。二将各带重伤。吕蒙教军士乱箭射住岸上兵，救二将下船。却说陈武与庞德大战，后面又无应兵，被庞德赶到峪口，树林丛密；陈武再欲回身交战，被树株抓往袍袖，不能迎敌，为庞德所杀。曹操见孙权走脱了，自策马驱兵，赶到江边对射。吕蒙箭尽，正慌间，忽对江一宗船到，为首一员大将，乃是孙策女婿陆逊，自引十万兵到；一阵射退曹兵，乘势登岸追杀曹兵，复夺战马数千匹，曹兵伤者，不计其数，大败而回。于乱军中寻见陈武尸首，孙权知陈武已亡，董袭又沉江而死，哀痛至切，令人入水中寻见董袭尸首，与陈武尸一齐厚葬之。又感周泰救护之功，设宴款之。权亲自把盏，抚其背，泪流满面，曰：“卿两番相救，不惜性命，被枪数十，肤如刻画，孤亦何心不待卿以骨肉之恩、委卿以兵马之重乎！卿乃孤之功臣，孤当与卿共荣辱、同休戚也。”言罢，令周泰解衣与众将观之：皮肉肌肤，如同刀剜，盘根遍体。孙权手指其痕，一一问之。周泰具言战斗被伤之状。一处伤令吃一觥酒。是日，周泰大醉。权以青罗伞赐之，令出入张盖，以为显耀。权在濡须，与操相拒月余，不能取胜。张昭，顾雍上言：“曹操势大，不可力取；若与久战，大损士卒：不若求和安民为上。”孙权从其言，令步骘往曹营求和，许年纳岁贡。操见江南急未可下，乃从之，令：“孙权先撤人马，吾然后班师。”步骘回覆，权只留蒋钦、周泰守濡须口，尽发大兵上船回秣陵。操留曹仁、张辽屯合淝，班师回许昌。文武众官皆议立曹操为魏王。尚书崔琰力言不可。众官曰：“汝独不见荀文若乎？”琰大怒曰：“时乎，时乎！会当有变，任自为之！”有与琰不和者，告知操。操大怒，收琰下狱问之。琰虎目虬髯，只是大骂曹操欺君奸贼。廷尉白操，操令杖杀崔琰在狱中。后人有赞曰：“清河崔琰，天性坚刚；虬髯虎目，铁石心肠；奸邪辟易，声节显昂；忠于汉主，千古名扬！”
建安二十一年夏五月，群臣表奏献帝，颂魏公曹操功德，极天际地，伊、周莫及，宜进爵为王。献帝即令钟繇草诏，册立曹操为魏王。曹操假意上书三辞。诏三报不许，操乃拜命受魏王之爵，冕十二旒，乘金根车，驾六马，用天子车服銮仪，出警入跸，于邺郡盖魏王宫，议立世子。操大妻丁夫人无出。妾刘氏生子曹昂，因征张绣时死于宛城。卞氏所生四子：长曰丕，次曰彰，三曰植，四曰熊。于是黜丁夫人，而立卞氏为魏王后。第三子曹植，字子建，极聪明，举笔成章，操欲立之为后嗣。长子曹丕，恐不得立，乃问计于中大夫贾诩。诩教如此如此。自是但凡操出征，诸子送行，曹植乃称述功德，发言成章；惟曹丕辞父，只是流涕而拜，左右皆感伤。于是操疑植乖巧，诚心不及丕也。丕又使人买嘱近侍，皆言丕之德。操欲立后嗣，踌躇不定，乃问贾诩曰：“孤欲立后嗣，当立谁？”贾诩不答，操问其故，诩曰：“正有所思，故不能即答耳。”操曰：“何所思？”诩对曰：“思袁本初、刘景升父子也。”操大笑，遂立长子曹丕为王世子。
冬十月，魏王宫成，差人往各处收取奇花异果，栽植后苑。有使者到吴地，见了孙权，传魏王令旨，再往温州取柑子。时孙权正尊让魏王，便令人于本城选了大柑子四十余担，星夜送往邺郡。至中途，挑担役夫疲困，歇于山脚下，见一先生，眇一目，跛一足，头戴白藤冠，身穿青懒衣，来与脚夫作礼，言曰：“你等挑担劳苦，贫道都替你挑一肩何如？”众人大喜。于是先生每担各挑五里。但是先生挑过的担儿都轻了。众皆惊疑。先生临去，与领柑子官说：“贫道乃魏王乡中故人，姓左，名慈，字元放，道号乌角先生。如你到邺郡，可说左慈申意。”遂拂袖而去。
取柑人至邺郡见操，呈上柑子。操亲剖之，但只空壳，内并无肉。操大惊，问取柑人。取柑人以左慈之事对。操未肯信，门吏忽报：“有一先生，自称左慈，求见大王。”操召入。取柑人曰：“此正途中所见之人。”操叱之曰：“汝以何妖术，摄吾佳果？”慈笑曰：“岂有此事！”取柑剖之，内皆有肉，其味甚甜。但操自剖者，皆空壳。操愈惊，乃赐左慈坐而问之。慈索酒肉，操令与之，饮酒五斗不醉，肉食全羊不饱。操问曰：“汝有何术，以至于此？”慈曰：“贫道于西川嘉陵峨嵋山中，学道三十年，忽闻石壁中有声呼我之名；及视，不见。如此者数日。忽有天雷震碎石壁，得天书三卷，名曰《遁甲天书》。上卷名‘天遁’，中卷名‘地遁’，下卷名‘人遁’。天遁能腾云跨风，飞升太虚；地遁能穿山透石；人遁能云游四海，藏形变身，飞剑掷刀，取人首级。大王位极人臣，何不退步，跟贫道往峨嵋山中修行？当以三卷天书相授。”操曰：“我亦久思急流勇退，奈朝廷未得其人耳。”慈笑曰：“益州刘玄德乃帝室之胄，何不让此位与之？不然，贫道当飞剑取汝之头也。”操大怒曰：“此正是刘备细作！”喝左右拿下。慈大笑不止。操令十数狱卒，捉下拷之。狱卒着力痛打，看左慈时，却齁齁熟睡，全无痛楚。操怒，命取大枷，铁钉钉了，铁锁锁了，送入牢中监收，令人看守。只见枷锁尽落，左慈卧于地上，并无伤损。连监禁七日，不与饮食。及看时，慈端坐于地上，面皮转红。狱卒报知曹操，操取出问之。慈曰：“我数十年不食，亦不妨；日食千羊，亦能尽。”操无可奈何。
是日，诸官皆至王宫大宴。正行酒间，左慈足穿木履，立于筵前。众官惊怪。左慈曰：“大王今日水陆俱备，大宴群臣，四方异物极多，内中欠少何物，贫道愿取之。”操曰：“我要龙肝作羹，汝能取否？”慈曰：“有何难哉！”取墨笔于粉墙上画一条龙，以袍袖一拂，龙腹自开。左慈于龙腹中提出龙肝一副，鲜血尚流。操不信，叱之曰：“汝先藏于袖中耳！”慈曰：“即今天寒，草木枯死；大王要甚好花，随意所欲。”操曰：“吾只要牡丹花。”慈曰：“易耳。”令取大花盆放筵前。以水噀之。顷刻发出牡丹一株，开放双花。众官大惊，邀慈同坐而食。少刻，庖人进鱼脍。慈曰：“脍必松江鲈鱼者方美，”操曰：“千里之隔，安能取之？”慈曰：“此亦何难取！”教把钓竿来，于堂下鱼池中钓之。顷刻钓出数十尾大鲈鱼，放在殿上。操曰：“吾池中原有此鱼。”慈曰：“大王何相欺耶？天下鲈鱼只两腮，惟松江鲈鱼有四腮：此可辨也。”众官视之，果是四腮。慈曰：“烹松江鲈鱼，须紫芽姜方可。”操曰：“汝亦能取之否？”慈曰：“易耳。”令取金盆一个，慈以衣覆之。须臾，得紫芽姜满盆，进上操前。操以手取之，忽盆内有书一本，题曰《孟德新书》。操取视之，一字不差。操大疑，慈取桌上玉杯，满斟佳酿进操曰：“大王可饮此酒，寿有千年。”操曰：“汝可先饮。”慈遂拔冠上玉簪，于杯中一画，将酒分为两半；自饮一半，将一半奉操。操叱之。慈掷杯于空中，化成一白鸠，绕殿而飞。众官仰面视之，左慈不知所往。左右忽报：“左慈出宫门去了。”操曰：“如此妖人，必当除之！否则必将为害。”遂命许褚引三百铁甲军追擒之。
褚上马引军赶至城门，望见左慈穿木履在前，慢步而行。褚飞马追之，却只追不上。直赶到一山中，有牧羊小童，赶着一群羊而来，慈走入羊群内。褚取箭射之，慈即不见。褚尽杀群羊而回。牧羊小童守羊而哭，忽见羊头在地上作人言，唤小童曰：“汝可将羊头都凑在死羊腔子上。”小童大惊，掩面而走。忽闻有人在后呼曰：“不须惊走，还汝活羊。”小童回顾，见左慈已将地上死羊凑活，赶将来了。小童急欲问时，左慈已拂袖而去。其行如飞，倏忽不见。
小童归告主人，主人不敢隐讳，报知曹操。操画影图形，各处捉拿左慈。三日之内，城里城外，所捉眇一目、跛一足、白藤冠、青懒衣、穿木履先生，都一般模样者，有三四百个。哄动街市。操令众将，将猪羊血泼之，押送城南教场。曹操亲自引甲兵五百人围住，尽皆斩之。人人颈腔内各起一道青气，到上天聚成一处，化成一个左慈，向空招白鹤一只骑坐，拍手大笑曰：“土鼠随金虎，奸雄一旦休！”操令众将以弓箭射之。忽然狂风大作，走石扬沙；所斩之尸，皆跳起来，手提其头，奔上演武厅来打曹操。文官武将，掩面惊倒，各不相顾。正是：奸雄权势能倾国，道士仙机更异人。
未知曹操性命如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943855, '5b9b6e3f1b69e6005ba2b2a5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639207, '三国演义 · 第六十九回 · 卜周易管辂知机 讨汉贼五臣死节', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说当日曹操见黑风中群尸皆起，惊倒于地。须臾风定，群尸皆不见。左右扶操回宫，惊而成疾。后人有诗赞左慈曰：“飞步凌云遍九州，独凭遁甲自遨游。等闲施设神仙术，点悟曹瞒不转头。”曹操染病，服药无愈。适太史丞许芝，自许昌来见操。操令芝卜易。芝曰：“大王曾闻神卜管辂否？”操曰：“颇闻其名，未知其术。汝可详言之。”芝曰：“管辂字公明，平原人也。容貌粗丑，好酒疏狂。其父曾为琅琊即丘长。辂自幼便喜仰视星辰，夜不肯寐，父母不能禁止。常云家鸡野鹄，尚自知时，何况为人在世乎？与邻儿共戏，辄画地为天文，分布日月星辰。及稍长，即深明《周易》，仰观风角，数学通神，兼善相术。琅琊太守单子春闻其名，召辂相见。时有坐客百余人，皆能言之士。辂谓子春曰：辂年少胆气未坚，先请美酒三升，饮而后言。子春奇之，遂与酒三升。饮毕，辂问子春：今欲与辂为对者，若府君四座之士耶？子春曰：吾自与卿旗鼓相当。于是与辂讲论《易》理。辂亹亹而谈，言言精奥。子春反覆辩难，辂对答如流。从晓至暮，酒食不行。子春及众宾客，无不叹服。于是天下号为‘神童’。后有居民郭恩者，兄弟三人，皆得躄疾，请辂卜之。辂曰：卦中有君家本墓中女鬼，非君伯母即叔母也。昔饥荒之年，谋数升米之利，推之落井，以大石压破其头，孤魂痛苦，自诉于天，故君兄弟有此报。不可禳也。郭恩等涕泣伏罪。安平太守王基，知辂神卜，延辂至家。适信都令妻常患头风，其子又患心痛，因请辂卜之。辂曰：此堂之西角有二死尸：一男持矛，一男持弓箭。头在壁内，脚在壁外。持矛者主刺头，故头痛；持弓箭者主刺胸腹，故心痛。乃掘之。入地八尺，果有二棺。一棺中有矛，一棺中有角弓及箭，木俱已朽烂。辂令徙骸骨去城外十里埋之，妻与子遂无恙。馆陶令诸葛原，迁新兴太守，辂往送行。客言辂能覆射。诸葛原不信，暗取燕卵、蜂窠、蜘蛛三物，分置三盒之中，令辂卜之。卦成，各写四句于盒上。其一曰：含气须变，依乎宇堂；雌雄以形，羽翼舒张：此燕卵也。其二曰：家室倒悬，门户众多；藏精育毒，得秋乃化：此蜂窠也。其三曰：觳觫长足，吐丝成罗；寻网求食，利在昏夜：此蜘蛛也。满座惊骇。乡中有老妇失牛，求卜之。辂判曰：北溪之滨，七人宰烹；急往追寻，皮肉尚存。老妇果往寻之：七人于茅舍后煮食，皮肉犹存。妇告本郡太守刘邠，捕七人罪之。因问老妇曰：汝何以知之？妇告以管辂之神卜。刘邠不信，请辂至府，取印囊及山鸡毛藏于盒中，令卜之。辂卜其一曰：内方外圆，五色成文；含宝守信，出则有章：此印囊也。其二曰：岩岩有鸟，锦体朱衣；羽翼玄黄，鸣不失晨：此山鸡毛也。刘邠大惊，遂待为上宾。一日，出郊闲行，见一少年耕于田中，辂立道傍，观之良久，问曰：“少年高姓、贵庚？答曰：姓赵，名颜，年十九岁矣。敢问先生为谁？辂曰：吾管辂也。吾见汝眉间有死气，三日内必死。汝貌美，可惜无寿。赵颜回家，急告其父。父闻之，赶上管辂，哭拜于地曰：请归救吾子！辂曰：“此乃天命也，安可禳乎？父告曰：老夫止有此子，望乞垂救！赵颜亦哭求。辂见其父子情切，乃谓赵颜曰：汝可备净酒一瓶，鹿脯一块，来日赍往南山之中，大树之下，看盘石上有二人弈棋：一人向南坐，穿白袍，其貌甚恶；一人向北坐，穿红袍，其貌甚美。汝可乘其弈兴浓时，将酒及鹿脯跑进之。待其饮食毕，汝乃哭拜求寿，必得益算矣。但切勿言是吾所教。老人留辂在家。次日，赵颜携酒脯杯盘入南山之中。约行五六里，果有二人于大松树下盘石上着棋，全然不顾。赵颜跪进酒脯。二人贪着棋，不觉饮酒已尽。赵颜哭拜于地而求寿，二人大惊。穿红袍者曰：此必管子之言也。吾二人既受其私，必须怜之。穿白袍者，乃于身边取出簿籍检看，谓赵颜曰：汝今年十九岁，当死。吾今于十字上添一九字，汝寿可至九十九。回见管辂，教再休泄漏天机；不然，必致天谴。穿红者出笔添讫，一阵香风过处，二人化作二白鹤，冲天而去。赵颜归问管辂。辂曰：穿红者，南斗也；穿白者，北斗也。颜曰：吾闻北斗九星，何止一人？辂曰：散而为九，合而为一也。北斗注死，南斗注生。今已添注寿算，子复何忧？父子拜谢。自此管辂恐泄天机，更不轻为人卜。此人现在平原，大王欲知休咎，何不召之？”
操大喜，即差人往平原召辂。辂至，参拜讫，操令卜之。辂答曰：“此幻术耳，何必为忧？”操心安，病乃渐可。操令卜天下之事。辂卜曰；“三八纵横，黄猪遇虎；定军之南，伤折一股。”又令卜传祚修短之数。辂卜曰：“狮子宫中，以安神位；王道鼎新，子孙极贵。”操问其详。辂曰：“茫茫天数，不可预知。待后自验。”操欲封辂为太史。辂曰：“命薄相穷，不称此职，不敢受也。”操问其故，答曰：“辂额无主骨，眼无守睛；鼻无梁柱，脚无天根；背无三甲，腹无三壬：只可泰山治鬼，不能治生人也。”操曰：“汝相吾若何？”辂曰：“位极人臣，又何必相？”再三问之，辂但笑而不答。操令辂遍相文武官僚。辂曰：“皆治世之臣也。”操问休咎，皆不肯尽言。后人有诗赞曰：平原神卜管公明，能算南辰北斗星。八封幽微通鬼窍，六爻玄奥究天庭。预知相法应无寿，自觉心源极有灵。可惜当年奇异术，后人无复授遗经。
操令卜东吴、西蜀二处。辂设卦云：“东吴主亡一大将，西蜀有兵犯界。”操不信。忽合淝报来：“东吴陆口守将鲁肃身故。”操大惊，便差人往汉中探听消息。不数日，飞报刘玄德遣张飞、马超兵屯下辨取关。操大怒，便欲自领大兵再入汉中，令管辂卜之。辂曰：“大王未可妄动，来春许都必有火灾。”操见辂言累验，故不敢轻动，留居邺郡。使曹洪领兵五万，往助夏侯渊、张郃同守东川；又差夏侯惇兵三万，于许都来往巡警，以备不虞；又教长史王必总督御林军马。主簿司马懿曰：“王必嗜酒性宽，恐不堪任此职。”操曰：“王必是孤披荆棘历艰难时相随之人，忠而且勤，心如铁石，最足相当。”遂委王必领御林军马屯于许都东华门外。
时有一人，姓耿，名纪，字季行，洛阳人也；旧为丞相府掾，后迁侍中少府，与司直韦晃甚厚；见曹操进封王爵，出入用天子车服，心甚不平。时建安二十三年春正月。耿纪与韦晃密议曰：“操贼奸恶日甚，将来必为篡逆之事。吾等为汉臣，岂可同恶相济？”韦晃曰：“吾有心腹人，姓金，名祎，乃汉相金日磾之后，素有讨操之心；更兼与王必甚厚。若得同谋，大事济矣。”耿纪曰：“他既与王必交厚，岂肯与我等同谋乎？”韦晃曰：“且往说之，看是如何。”于是二人同至金祎宅中。祎接入后堂，坐定。晃曰：“德伟与王长史甚厚，吾二人特来告求。”祎曰：“所求何事？”晃曰：“吾闻魏王早晚受禅，将登大宝，公与王长史必高迁。望不相弃，曲赐提携，感德非浅！”祎拂袖而起。适从者奉茶至，便将茶泼于地上。晃佯惊曰：“德伟故人，何薄情也？”祎曰：“吾与汝交厚，为汝等是汉朝臣宰之后；今不思报本，欲辅造反之人，吾有何面目与汝为友！”耿纪曰：“奈天数如此，不得不为耳！”祎大怒。
耿纪、韦晃见祎果有忠义之心，乃以实情相告曰：“吾等本欲讨贼，来求足下。前言特相试耳。”祎曰：“吾累世汉臣，安能从贼！公等欲扶汉室，有何高见？”晃曰：“虽有报国之心，未有讨贼之计。”祎曰：“吾欲里应外合，杀了王必，夺其兵权，扶助銮舆。更结刘皇叔为外援，操贼可灭矣。”二人闻之，抚掌称善。祎曰：“我有心腹二人，与操贼有杀父之仇，现居城外，可用为羽翼。”耿纪问是何人。祎曰：“太医吉平之子：长名吉邈，字文然；次名吉穆，字思然。操昔日为董承衣带诏事，曾杀其父；二子逃窜远乡，得免于难。今已潜归许都，若使相助讨贼，无有不从。”耿纪、韦晃大喜。金祎即使人密唤二吉。须臾，二人至。祎具言其事。二人感愤流泪，怨气冲天，誓杀国贼。金祎曰：“正月十五日夜间，城中大张灯火，庆赏元宵。耿少府、韦司直，你二人各领家僮，杀到王必营前；只看营中火起，分两路杀入；杀了王必，径跟我入内，请天子登五凤楼，召百官面谕讨贼。吉文然兄弟于城外杀入，放火为号，各要扬声，叫百姓诛杀国贼，截住城内救军；待天子降诏，招安已定，便进兵杀投邺郡擒曹操，即发使赍诏召刘皇叔。今日约定，至期二更举事。勿似董承自取其祸。”五人对天说誓，歃血为盟，各自归家，整顿军马器械，临期而行。且说耿纪、韦晃二人，各有家僮三四百，预备器械。吉邈兄弟，亦聚三百人口，只推围猎，安排已定。金祎先期来见王必，言：“方今海宇稍安，魏王威震天下；今值元宵令节，不可不放灯火以示太平气象。”王必然其言，告谕城内居民，尽张灯结彩，庆赏佳节。至正月十五夜，天色晴霁，星月交辉，六街三市，竞放花灯。真个金吾不禁，玉漏无催！王必与御林诸将，在营中饮宴。二更以后，忽闻营中呐喊，人报营后火起。王必慌忙出帐看时，只见火光乱滚；又闻喊杀连天，知是营中有变，急上马出南门，正遇耿纪，一箭射中肩膊，几乎坠马，遂望西门而走。背后有军赶来。王必着忙，弃马步行。至金祎门首，慌叩其门。原来金祎一面使人于营中放火，一面亲领家僮随后助战，只留妇女在家。时家中闻王必叩门之声，只道金祎归来。祎妻从隔门便问曰：“王必那厮杀了么？”王必大惊，方悟金祎同谋，径投曹休家，报知金祎、耿纪等同谋反。休急披挂上马，引千余人在城中拒敌。城内四下火起，烧着五凤楼，帝避于深宫。曹氏心腹爪牙，死据宫门。城中但闻人叫：“杀尽曹贼，以扶汉室！”
原来夏侯惇奉曹操命，巡警许昌，领三万军，离城五里屯扎；是夜，遥望见城中火起，便领大军前来，围住许都，使一枝军入城接应曹休。直混杀至天明。耿纪、韦晃等无人相助。人报金祎、二吉皆被杀死。耿纪、韦晃夺路杀出城门，正遇夏侯惇大军围住，活捉去了。手下百余人皆被杀。夏侯惇入城，救灭遗火，尽收五人老小宗族，使人飞报曹操。操传令教将耿、韦二人，及五家宗族老小，皆斩于市，并将在朝大小百官，尽行拿解邺郡，听候发落。夏侯惇押耿、韦二人至市曹。耿纪厉声大叫曰：“曹阿瞒！吾生不能杀汝，死当作厉鬼以击贼！”刽子以刀搠其口，流血满地，大骂不绝而死。韦晃以面颊顿地曰：“可恨！可恨！”咬牙皆碎而死。后人有诗赞曰：“耿纪精忠韦晃贤，各持空手欲扶天。谁知汉祚相将尽，恨满心胸丧九泉。”夏侯惇尽杀五家老小宗族，将百官解赴邺郡。曹操于教场立红旗于左、白旗于右，下令曰：“耿纪、韦晃等造反，放火焚许都，汝等亦有出救火者，亦有闭门不出者。如曾救火者，可立于红旗下；如不曾救火者，可立于白旗下。”众官自思救火者必无罪，于是多奔红旗之下。三停内只有一停立于白旗下。操教尽拿立于红旗下者。众官各言无罪。操曰：“汝当时之心，非是救火，实欲助贼耳。”尽命牵出漳河边斩之，死者三百余员。其立于白旗下者，尽皆赏赐，仍令还许都。时王必已被箭疮发而死，操命厚葬之。令曹休总督御林军马，钟繇为相国，华歆为御史大夫。遂定侯爵六等十八级，关中侯爵十七级，皆金印紫绶；又置关内外侯十六级，银印龟纽墨绶；五大夫十五级，铜印环纽墨绶。定爵封官，朝廷又换一班人物。曹操方悟管辂火灾之说，遂重赏辂。辂不受。
却说曹洪领兵到汉中，令张郃、夏侯渊各据险要。曹洪亲自进兵拒敌。时张飞自与雷铜守把巴西。马超兵至下辨，令吴兰为先锋，领军哨出，正与曹洪军相遇。吴兰欲退，牙将任夔曰：“贼兵初至，若不先挫其锐气，何颜见孟起乎？”于是骤马挺枪搦曹洪战。洪自提刀跃马而出。交锋三合，斩夔于马下，乘势掩杀。吴兰大败，回见马超。超责之曰：“汝不得吾令，何故轻敌致败？”吴兰曰：“任夔不听吾言，故有此败？”马超曰：“可紧守隘口，勿与交锋。”一面申报成都，听候行止。曹洪见马超连日不出，恐有诈谋，引军退回南郑。张郃来见曹洪，问曰：“将军既已斩将，如何退兵？”洪曰：“吾见马超不出，恐有别谋。且我在邺都，闻神卜管辂有言：当于此地折一员大将。吾疑此言，故不敢轻进。”张郃大笑曰：“将军行兵半生，今奈何信卜者之言而惑其心哉！郃虽不才，愿以本部兵取巴西。若得巴西，蜀郡易耳。”洪曰：“巴西守将张飞，非比等闲，不可轻敌。”张郃曰：“人皆怕张飞，吾视之如小儿耳！此去必擒之！”洪曰：“倘有疏失，若何？”郃曰：“甘当军令。”洪勒了文状，张郃进兵。正是：自古骄兵多致败，从来轻敌少成功。
未知胜负如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943855, '5b9b6e5bfb4ffe005cafe30c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639208, '三国演义 · 第七十回 · 猛张飞智取瓦口隘 老黄忠计夺天荡山', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说张郃部兵三万，分为三寨，各傍山险：一名宕渠寨，一名蒙头寨。一名荡石寨。当日张郃于三寨中，各分军一半，去取巴西，留一半守寨。早有探马报到巴西，说张郃引兵来了。张飞急唤雷铜商议。铜曰：“阆中地恶山险，可以埋伏。将军引兵出战，我出奇兵相助，郃可擒矣。”张飞拨精兵五千与雷铜去讫。飞自引兵一万，离阆中三十里，与张郃兵相遇。两军摆开，张飞出马，单搦张郃。郃挺枪纵马而出。战到二十余合，郃后军忽然喊起：原来望见山背后有蜀兵旗幡，故此扰乱。张郃不敢恋战，拨马回走。张飞从后掩杀。前面雷铜又引兵杀出。两下夹攻，郃兵大败。张飞、雷铜连夜追袭，直赶到宕渠山。张郃仍旧分兵守住三寨，多置擂木炮石，坚守不战。张飞离宕渠十里下寨，次日引兵搦战。郃在山上大吹大擂饮酒，并不下山。张飞令军士大骂，郃只不出。飞只得还营。次日，雷铜又去山下搦战，郃又不出。雷铜驱军士上山，山上擂木炮石打将下来。雷铜急退。荡石、蒙头两寨兵出，杀败雷铜。次日，张飞又去搦战，张郃又不出。飞使军人百般秽骂，郃在山上亦骂。张飞寻思，无计可施。相拒五十余日，飞就在山前扎住大寨，每日饮酒；饮至大醉，坐于山前辱骂。
玄德差人犒军，见张飞终日饮酒，使者回报玄德。玄德大惊，忙来问孔明。孔明笑曰：“原来如此！军前恐无好酒；成都佳酿极多，可将五十瓮作三车装，送到军前与张将军饮。”玄德曰：“吾弟自来饮酒失事，军师何故反送酒与他？”孔明笑曰：“主公与翼德做了许多年兄弟，还不知其为人耶？翼德自来刚强，然前于收川之时，义释严颜，此非勇夫所为也。今与张郃相拒五十余日，酒醉之后，便坐山前辱骂，傍若无人：此非贪杯，乃败张郃之计耳。”玄德曰：“虽然如此，未可托大。可使魏延助之。”孔明令魏延解酒赴军前，车上各插黄旗，大书“军前公用美酒”。魏延领命，解酒到寨中，见张飞，传说主公赐酒。飞拜受讫，分付魏延、雷铜各引一枝人马，为左右翼；只看军中红旗起，便各进兵；教将酒摆列帐下，令军士大开旗鼓而饮。有细作报上山来，张郃自来山顶观望，见张飞坐于帐下饮酒，令二小卒于面前相扑为戏。郃曰：“张飞欺我太甚！”传令今夜下山劫飞寨，令蒙头、荡石二寨，皆出为左右援。当夜张郃乘着月色微明，引军从山侧而下，径到寨前。遥望张飞大明灯烛，正在帐中饮酒。张郃当先大喊一声，山头擂鼓为助，直杀入中军。但见张飞端坐不动。张郃骤马到面前，一枪刺倒，却是一个草人。急勒马回时，帐后连珠炮起。一将当先，拦住去路，睁圆环眼，声如巨雷：乃张飞也。挺矛跃马，直取张郃。两将在火光中，战到三五十合。张郃只盼两寨来救，谁知两寨救兵，已被魏延，雷铜两将杀退，就势夺了二寨。张郃不见救兵至，正没奈何，又见山上火起，已被张飞后军夺了寨栅。张郃三寨俱失，只得奔瓦口关去了。张飞大获胜捷，报入成都。玄德大喜，方知翼德饮酒是计，只要诱张郃下山。却说张郃退守瓦口关，三万军已折了二万，遣人问曹洪求救。洪大怒曰：“汝不听吾言，强要进兵，失了紧要隘口，却又来求救！”遂不肯发兵，使人催督张郃出战。郃心慌，只得定计，分两军去关口前山僻埋伏，分付曰：“我诈败，张飞必然赶来，汝等就截其归路。”当日张郃引军前进，正遇雷铜。战不数合，张郃败走，雷铜赶来。两军齐出，截断回路。张郃复回，刺雷铜于马下。败军回报张飞，飞自来与张郃挑战。郃又诈败，张飞不赶。郃又回战，不数合，又败走。张飞知是计，收军回寨，与魏延商议曰：“张郃用埋伏计，杀了雷铜，又要赚吾，何不将计就计？”延问曰：“如何？”飞曰：“我明日先引一军前往，汝却引精兵于后，待伏兵出，汝可分兵击之。用车十余乘，各藏柴草，塞住小路，放火烧之。吾乘势擒张郃，与雷铜报仇。”魏延领计。次日，张飞引兵前进。张郃兵又至，与张飞交锋。战到十合，郃又诈败。张飞引马步军赶来，郃且战且走。引张飞过山峪口，郃将后军为前，复扎住营，与飞又战，指望两彪伏兵出，要围困张飞。不想伏兵却被魏延精兵到，赶入峪口，将车辆截住山路，放火烧车，山谷草木皆着，烟迷其径，兵不得出。张飞只顾引军冲突，张郃大败，死命杀开条路，走上瓦口关，收聚败兵，坚守不出。
张飞和魏延连日攻打关隘不下。飞见不济事，把军退二十里，却和魏延引数十骑，自来两边哨探小路。忽见男女数人，各背小包，于山僻路攀藤附葛而走。飞于马上用鞭指与魏延曰：“夺瓦口关，只在这几个百姓身上。”便唤军士分付：“休要惊恐他，好生唤那几个百姓来。”军士连忙唤到马前。飞用好言以安其心，问其何来。百姓告曰：“某等皆汉中居民，今欲还乡。听知大军厮杀，塞闭阆中官道；今过苍溪，从梓潼山桧釿川入汉中，还家去。”飞曰：“这条路取瓦口关远近若何？”百姓曰：“从梓潼山小路，却是瓦口关背后。”飞大喜，带百姓入寨中，与了酒食；分付魏延：“引兵扣关攻打，我亲自引轻骑出梓潼山攻关后。”便令百姓引路，选轻骑五百，从小路而进。却说张郃为救军不到，心中正闷。人报魏延在关下攻打。张郃披挂上马，却待下山，忽报：“关后四五路火起，不知何处兵来。”郃自领兵来迎。旗开处，早见张飞。郃大惊，急往小路而走。马不堪行。后面张飞追赶甚急，郃弃马上山，寻径而逃，方得走脱，随行只有十余人。
步行入南郑，见曹洪。洪见张郃只剩下十余人，大怒曰：“吾教汝休去，汝取下文状要去；今日折尽大兵，尚不自死，还来做甚！”喝令左右推出斩之。行军司马郭淮谏曰：“三军易得，一将难求。张郃虽然有罪，乃魏王所深爱者也，不可便诛。可再与五千兵径取葭萌关，牵动其各处之兵，汉中自安矣。如不成功，二罪俱罚。”曹洪从之，又与兵五千，教张郃取葭萌关。郃领命而去。
却说葭萌关守将孟达、霍峻，知张郃兵来。霍峻只要坚守；孟达定要迎敌，引军下关与张郃交锋，大败而回。霍峻急申文书到成都。玄德闻知，请军师商议。孔明聚众将于堂上，问曰：“今葭萌关紧急，必须阆中取翼德，方可退张郃也。”法正曰：“今翼德兵屯瓦口，镇守阆中，亦是紧要之地，不可取回。帐中诸将内选一人去破张郃。”孔明笑曰：“张郃乃魏之名将，非等闲可及。除非翼德，无人可当。”忽一人厉声而出曰：“军师何轻视众人耶！吾虽不才，愿斩张郃首级，献于麾下。”众视之，乃老将黄忠也。孔明曰：“汉升虽勇，争奈年老，恐非张郃对手。”忠听了，白发倒竖而言曰：“某虽老，两臂尚开三石之弓，浑身还有千斤之力：岂不足敌张郃匹夫耶！”孔明曰：“将军年近七十，如何不老？”忠趋步下堂，取架上大刀，轮动如飞；壁上硬弓，连拽折两张。孔明曰：“将军要去，谁为副将？”忠曰：“老将严颜，可同我去。但有疏虞，先纳下这白头。”玄德大喜，即时令严颜、黄忠去与张郃交战。赵云谏曰：“今张郃亲犯葭萌关，军师休为儿戏。若葭萌一失，益州危矣。何故以二老将当此大敌乎？”孔明曰：“汝以二人老迈，不能成事，吾料汉中必于此二人手内可得。”赵云等各各哂笑而退。却说黄忠、严颜到关上，孟达、霍峻见了，心中亦笑孔明欠调度：“是这般紧要去处，如何只教两个老的来！”黄忠谓严颜曰：“你可见诸人动静么？他笑我二人年老，今可建奇功，以服众心。”严颜曰：“愿听将军之令。”两个商议定了。黄忠引军下关，与张郃对阵。张郃出马，见了黄忠，笑曰：“你许大年纪，犹不识羞，尚欲出战耶！”忠怒曰：“竖子欺吾年老！吾手中宝刀却不老！”遂拍马向前与郃决战。二马相交，约战二十余合，忽然背后喊声起：原来是严颜从小路抄在张郃军后。两军夹攻，张郃大败。连夜赶去，张郃兵退八九十里。黄忠、严颜收兵入寨，俱各按兵不动。
曹洪听知张郃输了一阵，又欲见罪。郭淮曰：“张郃被迫，必投西蜀；今可遣将助之，就如监临，使不生外心。”曹洪从之，即遣夏侯惇之侄夏侯尚并降将韩玄之弟韩浩，二人引五千兵，前来助战。二将即时起行。到张郃寨中，问及军情，郃言：“老将黄忠，甚是英雄，更有严颜相助，不可轻敌。”韩浩曰：“我在长沙知此老贼利害。他和魏延献了城池，害吾亲兄，今既相遇，必当报仇！”遂与夏侯尚引新军离寨前进。原来黄忠连日哨探，已知路径。严颜曰：“此去有山，名天荡山，山中乃是曹操屯粮积草之地。若取得那个去处，断其粮草，汉中可得也。”忠曰：“将军之言，正合吾意。可与吾如此如此。”严颜依计，自领一枝军去了。
却说黄忠听知夏侯尚、韩浩来，遂引军马出营。韩浩在阵前，大骂黄忠：“无义老贼！”拍马挺枪，来取黄忠。夏侯尚便出夹攻。黄忠力战二将，各斗十余合，黄忠败走。二将赶二十余里，夺了黄忠寨。忠又草创一营。次日，夏侯尚、韩浩赶来，忠又出阵，战数合，又败走。二将又赶二十余里，夺了黄忠营寨，唤张郃守后寨。郃来前寨谏曰：“黄忠连退二日，于中必有诡计。”夏侯尚叱张郃曰：“你如此胆怯，可知屡次战败！今再休多言，看吾二人建功！”张郃羞赧而退。次日，二将又战，黄忠又败退二十里；二将迤逦赶上。次日，二将兵出，黄忠望风而走，连败数阵，直退在关上。二将扣关下寨，黄忠坚守不出。孟达暗暗发书，申报玄德，说：“黄忠连输数阵，现今退在关上。”玄德慌问孔明。孔明曰：“此乃老将骄兵之计也。”赵云等不信。
玄德差刘封来关上接应黄忠。忠与封相见，问刘封曰：“小将军来助战何意？”封曰：“父亲得知将军数败，故差某来。”忠笑曰：“此老夫骄兵之计也。看今夜一阵，可尽复诸营，夺其粮食马匹。此是借寨与彼屯辎重耳。今夜留霍峻守关，孟将军可与我搬粮草夺马匹，小将军看我破敌！”
是夜二更，忠引五千军开关直下。原来夏侯尚、韩浩二将连日见关上不出，尽皆懈怠；被黄忠破寨直入，人不及甲，马不及鞍，二将各自逃命而走，军马自相践踏，死者无数。比及天明，连夺三寨。寨中丢下军器鞍马无数，尽教孟达搬运入关。黄忠催军马随后而进，刘封曰：“军士力困，可以暂歇。”忠曰：“‘不入虎穴，焉得虎子’？”策马先进。士卒皆努力向前。张郃军兵，反被自家败兵冲动，都屯扎不住，望后而走；尽弃了许多寨栅，直奔至汉水傍。
张郃寻见夏侯尚、韩浩议曰：“此天荡山，乃粮草之所；更接米仓山，亦屯粮之地：是汉中军士养命之源。倘若疏失，是无汉中也。当思所以保之。”夏侯尚曰：“米仓山有吾叔夏侯渊分兵守护，那里正接定军山，不必忧虑。天荡山有吾兄夏侯德镇守，我等宜往投之，就保此山。”
于是张郃与二将连夜投天荡山来，见夏侯德，具言前事。夏侯德曰：“吾此处屯十万兵，你可引去，复取原寨。”郃曰：“只宜坚守、不可妄动。”忽听山前金鼓大震，人报黄忠兵到。夏侯德大笑曰：“老贼不谙兵法，只恃勇耳！”郃曰：“黄忠有谋，非止勇也。”德曰：“川兵远涉而来，连日疲困，更兼深入战境，此无谋也！”郃曰：“亦不可轻敌，且宜坚守。”韩浩曰：“愿借精兵三千击之，当无不克。”德遂分兵与浩下山。
黄忠整兵来迎。刘封谏曰：“日已西沉矣，军皆远来劳困，且宜暂息。”忠笑曰：“不然。此天赐奇功，不取是逆天也。”言毕，鼓噪大进。韩浩引兵来战。黄忠挥刀直取浩，只一合，斩浩于马下。蜀兵大喊，杀上山来。张郃、夏侯尚急引军来迎。忽听山后大喊，火光冲天而起，上下通红。夏侯德提兵来救火时，正遇老将严颜，手起刀落，斩夏侯德于马下。原来黄忠预先使严颜引军埋伏于山僻去处，只等黄忠军到，却来放火，柴草堆上，一齐点着，烈焰飞腾，照耀山峪。严颜既斩夏侯德，从山后杀来。张郃、夏侯尚前后不能相顾，只得弃天荡山，望定军山投奔夏侯渊去了。
黄忠、严颜守住天荡山，捷音飞报成都。玄德闻之，聚众将庆喜。法正曰：“昔曹操降张鲁，定汉中，不因此势以图巴、蜀，乃留夏侯渊、张郃二将屯守，而自引大军北还：此失计也。今张郃新败，天荡失守，主公若乘此时，举大兵亲往征之，汉中可定也。既定汉中，然后练兵积粟，观衅伺隙，进可讨贼，退可自守。此天与之时，不可失也。”玄德、孔明皆深然之。遂传令赵云、张飞为先锋，玄德与孔明亲自引兵十万，择日图汉中；传檄各处，严加提备。时建安二十三年秋七月吉日。玄德大军出葭萌关下营，召黄忠、严颜到寨，厚赏之。玄德曰：“人皆言将军老矣，惟军师独知将军之能。今果立奇功。但今汉中定军山，乃南郑保障，粮草积聚之所；若得定军山，阳平一路，无足忧矣。将军还敢取定军山否？”黄忠慨然应诺，便要领兵前去。孔明急止之曰：“老将军虽然英勇，然夏侯渊非张郃之比也。渊深通韬略，善晓兵机，曹操倚之为西凉藩蔽：先曾屯兵长安，拒马孟起；今又屯兵汉中。操不托他人，而独托渊者，以渊有将才也。今将军虽胜张郃，未卜能胜夏侯渊。吾欲酌量着一人去荆州，替回关将军来，方可敌之。”忠奋然答曰：“昔廉颇年八十，尚食斗米、肉十斤，诸侯畏其勇，不敢侵犯赵界，何况黄忠未及七十乎？军师言吾老，吾今并不用副将，只将本部兵三千人去，立斩夏侯渊首级，纳于麾下。”孔明再三不容。黄忠只是要去。孔明曰：“既将军要去，吾使一人为监军同去，若何？”正是：请将须行激将法，少年不若老年人。
未知其人是谁，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943856, '5b9b6e7617d0090034175342', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639209, '三国演义 · 第七十一回 · 占对山黄忠逸待劳 据汉水赵云寡胜众', NULL, 4, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说孔明分付黄忠：“你既要去，吾教法正助你。凡事计议而行。吾随后拨人马来接应。”黄忠应允，和法正领本部兵去了。孔明告玄德曰：“此老将不着言语激他，虽去不能成功。他今既去，须拨人马前去接应。”乃唤赵云：“将一枝人马，从小路出奇兵接应黄忠：若忠胜，不必出战；倘忠有失，即去救应。”又遣刘封、孟达：“领三千兵于山中险要去处，多立旌旗，以壮我兵之声势，令敌人惊疑。”三人各自领兵去了。又差人往下辨，授计与马超，令他如此而行。又差严颜往巴西阆中守隘，替张飞、魏延来同取汉中。
却说张郃与夏侯尚来见夏侯渊，说：“天荡山已失，折了夏侯德、韩浩。今闻刘备亲自领兵来取汉中，可速奏魏王，早发精兵猛将，前来策应。”夏侯渊便差人报知曹洪。洪星夜前到许昌，禀知曹操。操大惊，急聚文武，商议发兵救汉中。长史刘晔进曰：“汉中若失，中原震动。大王休辞劳苦，必须亲自征讨。”操自悔曰：“恨当时不用卿言，以致如此！”忙传令旨，起兵四十万亲征。时建安二十三年秋七月也。
曹操兵分三路而进：前部先锋夏侯惇，操自领中军，使曹休押后，三军陆续起行。操骑白马金鞍，玉带锦衣；武士手执大红罗销金伞盖，左右金瓜银钺，镫棒戈矛，打日月龙凤旌旗；护驾龙虎官军二万五千，分为五队，每队五千，按青、黄、赤、白、黑五色，旗幡甲马，并依本色：光辉灿烂，极其雄壮。兵出潼关，操在马上望见一簇林木，极其茂盛，问近侍曰：“此何处也？”答曰：“此名蓝田。林木之间，乃蔡邕庄也。今邕女蔡琰，与其夫董祀居此。”原来操素与蔡邕相善。先时其女蔡琰，乃卫仲道之妻；后被北方掳去，于北地生二子，作《胡笳十八拍》，流入中原。操深怜之，使人持千金入北方赎之。左贤王惧操之势，送蔡琰还汉。操乃以琰配与董祀为妻。当日到庄前，因想起蔡邕之事，令军马先行，操引近侍百余骑，到庄门下马。时董祀出仕于外，止有蔡琰在家，琰闻操至，忙出迎接。操至堂，琰起居毕，侍立于侧。操偶见壁间悬一碑文图轴，起身观之。问于蔡琰，琰答曰：“此乃曹娥之碑也。昔和帝时，上虞有一巫者，名曹旴，能婆娑乐神；五月五日，醉舞舟中，堕江而死。其女年十四岁，绕江啼哭七昼夜，跳入波中；后五日，负父之尸浮于江面；里人葬之江边。上虞令度尚奏闻朝廷，表为孝女。度尚令邯郸淳作文镌碑以记其事。时邯郸淳年方十三岁，文不加点，一挥而就，立石墓侧，时人奇之。妾父蔡邕闻而往观，时日已暮，乃于暗中以手摸碑文而读之，索笔大书八字于其背。后人镌石，并镌此八字。”操读八字云：“黄绢幼妇，外孙齑臼。”操问琰曰：“汝解此意否？”琰曰：“虽先人遗笔，妾实不解其意。”操回顾众谋士曰：“汝等解否？”众皆不能答。于内一人出曰：“某已解其意。”操视之，乃主簿杨修也。操曰：“卿且勿言，容吾思之。”遂辞了蔡琰，引众出庄。上马行三里，忽省悟，笑谓修曰：“卿试言之。”修曰：“此隐语耳。‘黄绢’乃颜色之丝也：色傍加丝，是‘绝’字。‘幼妇’者，少女也：女傍少字，是‘妙’字。外孙乃女之子也：女傍子字，是‘好’字。‘齑臼’乃受五辛之器也：受傍辛字，是‘辤’字。总而言之，是‘绝妙好辤’四字。”操大惊曰：“正合孤意！”众皆叹羡杨修才识之敏。不一日，军至南郑。曹洪接着，备言张郃之事。操曰：“非郃之罪，胜负乃兵家常事耳。”洪曰：“目今刘备使黄忠攻打定军山，夏侯渊知大王兵至，固守未曾出战。”操曰：“若不出战，是示懦也。”便差人持节到定军山，教夏侯渊进兵。刘晔谏曰：“渊性太刚，恐中奸计。”操乃作手书与之。使命持节到渊营，渊接入。使者出书，渊拆视之。略曰：凡为将者，当以刚柔相济，不可徒恃其勇。若但任勇，则是一夫之敌耳。吾今屯大军于南郑，欲观卿之“妙才”，勿辱二字可也。夏侯渊览毕大喜。打发使命回讫，乃与张郃商议曰：“今魏王率大兵屯于南郑，以讨刘备。吾与汝久守此地，岂能建立功业？来日吾出战，务要生擒黄忠。”张郃曰：“黄忠谋勇兼备，况有法正相助，不可轻敌。此间山路险峻，只宜坚守。”渊曰：“若他人建了功劳，吾与汝有何面目见魏王耶？汝只守山，吾去出战。”遂下令曰：“谁敢出哨诱敌？”夏侯尚曰：“吾愿往。”渊曰：“汝去出哨，与黄忠交战，只宜输，不宜赢。吾有妙计，如此如此。”尚受令，引三千军离定军山大寨前行。
却说黄忠与法正引兵屯于定军山口，累次挑战，夏侯渊坚守不出；欲要进攻，又恐山路危险，难以料敌，只得据守。是日，忽报山上曹兵下来搦战。黄忠恰待引军出迎，牙将陈式曰：“将军休动，某愿当之。”忠大喜，遂令陈式引军一千，出山口列阵。夏侯尚兵至，遂与交锋。不数合，尚诈败而走。式赶去，行到半路，被两山上擂木炮石，打将下来，不能前进。正欲回时，背后夏侯渊引兵突出，陈式不能抵当，被夏侯渊生擒回寨。部卒多降。有败军逃得性命，回报黄忠，说陈式被擒。忠慌与法正商议，正曰：“渊为人轻躁，恃勇少谋。可激劝士卒，拔寨前进，步步为营，诱渊来战而擒之：此乃‘反客为主’之法。”忠用其谋，将应有之物，尽赏三军，欢声满谷，愿效死战。黄忠即日拔寨而进，步步为营；每营住数日，又进。渊闻之，欲出战。张郃曰：“此乃‘反客为主’之计，不可出战，战则有失。”渊不从，令夏侯尚引数千兵出战，直到黄忠寨前。忠上马提刀出迎，与夏侯尚交马，只一合，生擒夏侯尚归寨。余皆败走，回报夏侯渊。
渊急使人到黄忠寨，言愿将陈式来换夏侯尚。忠约定来日阵前相换。次日，两军皆到山谷阔处，布成阵势。黄忠、夏侯渊各立马于本阵门旗之下。黄忠带着夏侯尚，夏侯渊带着陈式，各不与袍铠，只穿蔽体薄衣。一声鼓响，陈式、夏侯尚各望本阵奔回。夏侯尚比及到阵门时，被黄忠一箭，射中后心。尚带箭而回。渊大怒，骤马径取黄忠。忠正要激渊厮杀。两将交马，战到二十余合，曹营内忽然鸣金收兵。渊慌拨马而回，被忠乘势杀了一阵。渊回阵问押阵官：“为何鸣金？”答曰：“某见山凹中有蜀兵旗幡数处，恐是伏兵，故急招将军回。”渊信其说，遂坚守不出。
黄忠逼到定军山下，与法正商议。正以手指曰：“定军山西，巍然有一座高山，四下皆是险道。此山上足可下视定军山之虚实。将军若取得此山，定军山只在掌中也。”忠仰见山头稍平，山上有些少人马。是夜二更，忠引军士鸣金击鼓，直杀上山顶。此山有夏侯渊部将杜袭守把，止有数百余人。当时见黄忠大队拥上，只得弃山而走。忠得了山顶，正与定军山相对。法正曰：“将军可守在半山，某居山顶。待夏侯渊兵至，吾举白旗为号，将军却按兵勿动；待他倦怠无备，吾却举起红旗，将军便下山击之：以逸待劳，必当取胜。”忠大喜，从其计。却说杜袭引军逃回，见夏侯渊，说黄忠夺了对山。渊大怒曰：“黄忠占了对山，不容我不出战。”张郃谏曰：“此乃法正之谋也。将军不可出战，只宜坚守。”渊曰：“占了吾对山，观吾虚实，如何不出战？”郃苦谏不听。渊分军围住对山，大骂挑战。法正在山上举起白旗；任从夏侯渊百般辱骂，黄忠只不出战。午时以后，法正见曹兵倦怠，锐气已堕，多下马坐息，乃将红旗招展，鼓角齐鸣，喊声大震，黄忠一马当先，驰下山来，犹如天崩地塌之势。夏侯渊措手不及，被黄忠赶到麾盖之下，大喝一声，犹如雷吼。渊未及相迎，黄忠宝刀已落，连头带肩，砍为两段。后人有诗赞黄忠曰：“苍头临大敌，皓首逞神威。力趁雕弓发，风迎雪刃挥。雄声如虎吼，骏马似龙飞。献馘功勋重，开疆展帝畿。”黄忠斩了夏侯渊，曹兵大溃，各自逃生。黄忠乘势去夺定军山，张郃领兵来迎。忠与陈式两下夹攻，混杀一阵，张郃败走。忽然山傍闪出一彪人马，当住去路；为首一员大将，大叫：“常山赵子龙在此！”张郃大惊，引败军夺路望定军山而走。只见前面一枝兵来迎，乃杜袭也。袭曰：“今定军山已被刘封、孟达夺了。”郃大惊，遂与杜袭引败兵到汉水扎营；一面令人飞报曹操。
操闻渊死，放声大哭，方悟管辂所言：“三八纵横”，乃建安二十四年也，“黄猪遇虎”，乃岁在己亥正月也；“定军之南”，乃定军山之南也；“伤折一股”，乃渊与操有兄弟之亲情也。操令人寻管辂时，不知何处去了。操深恨黄忠，遂亲统大军，来定军山与夏侯渊报仇，令徐晃作先锋。行到汉水，张郃、杜袭接着曹操。二将曰：“今定军山已失，可将米仓山粮草移于北山寨中屯积，然后进兵。”曹操依允。
却说黄忠斩了夏侯渊首级，来葭萌关上见玄德献功。玄德大喜，加忠为征西大将军，设宴庆贺。忽牙将张著来报说：“曹操自领大军二十万，来与夏侯渊报仇。目今张郃在米仓山搬运粮草，移于汉水北山脚下。”孔明曰：“今操引大兵至此，恐粮草不敷，故勒兵不进；若得一人深入其境，烧其粮草，夺其辎重，则操之锐气挫矣。”黄忠曰：“老夫愿当此任。”孔明曰：“操非夏侯渊之比，不可轻敌。”玄德曰：“夏侯渊虽是总帅，乃一勇夫耳，安及张郃？若斩得张郃，胜斩夏侯渊十倍也。”忠奋然曰：“吾愿往斩之。”孔明曰：“你可与赵子龙同领一枝兵去；凡事计议而行，看谁立功。”忠应允便行。孔明就令张著为副将同去。云谓忠曰：“今操引二十万众，分屯十营，将军在主公前要去夺粮，非小可之事。将军当用何策？”忠曰：“看我先去，如何？”云曰：“等我先去。”忠曰：“我是主将，你是副将，如何先争？”云曰：“我与你都一般为主公出力，何必计较？我二人拈阄，拈着的先去。”忠依允。当时黄忠拈着先去。云曰：“既将军先去，某当相助。可约定时刻。如将军依时而还，某按兵不动；若将军过时而不还，某即引军来接应。”忠曰：“公言是也。”于是二人约定午时为期。云回本寨，谓部将张翼曰：“黄汉升约定明日去夺粮草，若午时不回，我当往助。吾营前临汉水，地势危险；我若去时，汝可谨守寨栅，不可轻动。”张翼应诺。
却说黄忠回到寨中，谓副将张著曰；“我斩了夏侯渊，张郃丧胆；吾明日领命去劫粮草，只留五百军守营。你可助吾。今夜三更，尽皆饱食；四更离营，杀到北山脚下，先捉张郃，后劫粮草。”张著依令。当夜黄忠领人马在前，张著在后，偷过汉水，直到北山之下。东方日出，见粮积如山。有些少军士看守，见蜀兵到，尽弃而走。黄忠教马军一齐下马，取柴堆于米粮之上。正欲放火，张郃兵到，与忠混战一处。曹操闻知，急令除晃接应。晃领兵前进，将黄忠困于垓心。张著引三百军走脱，正要回寨，忽一枝兵撞出，拦住去路；为首大将，乃是文聘；后面曹兵又至，把张著围住。
却说赵云在营中，看看等到午时，不见忠回，急忙披挂上马，引三千军向前接应；临行，谓张翼曰：“汝可坚守营寨。两壁厢多设弓弩，以为准备。”翼连声应诺。云挺枪骤马直杀往前去。迎头一将拦路，乃文聘部将慕容烈也，拍马舞刀来迎赵云；被云手起一枪刺死。曹兵败走。云直杀入重围，又一枝兵截住；为首乃魏将焦炳。云喝问曰：“蜀兵何在？”炳曰：“已杀尽矣！”云大怒，骤马一枪，又刺死焦炳。杀散余兵，直至北山之下，见张郃、徐晃两人围住黄忠，军士被困多时。云大喝一声，挺枪骤马，杀入重围，左冲右突，如入无人之境。那枪浑身上下，若舞梨花；遍体纷纷，如飘瑞雪。张郃、徐晃心惊胆战，不敢迎敌。云救出黄忠，且战且走；所到之处，无人敢阻。操于高处望见，惊问众将曰：“此将何人也？”有识者告曰：“此乃常山赵子龙也。”操曰：“昔日当阳长坂英雄尚在！”急传令曰：“所到之处，不许轻敌。”赵云救了黄忠，杀透重围，有军士指曰：“东南上围的，必是副将张著。”云不回本寨，遂望东南杀来。所到之处，但见“常山赵云”四字旗号，曾在当阳长坂知其勇者，互相传说，尽皆逃窜。云又救了张著。
曹操见云东冲西突，所向无前，莫敢迎敌，救了黄忠，又救了张著，奋然大怒，自领左右将士来赶赵云。云已杀回本寨。部将张翼接着，望见后面尘起，知是曹兵追来，即谓云曰：“追兵渐近，可令军士闭上寨门，上敌楼防护。”云喝曰：“休闭寨门！汝岂不知吾昔在当阳长坂时，单枪匹马，觑曹兵八十三万如草芥！今有军有将，又何惧哉！”遂拨弓弩手于寨外壕中埋伏；将营内旗枪，尽皆倒偃，金鼓不鸣。云匹马单枪，立于营门之外。
却说张郃、徐晃领兵追至蜀寨，天色已暮；见寨中偃旗息鼓，又见赵云匹马单枪，立于营外，寨门大开，二将不敢前进。正疑之间，曹操亲到，急催督众军向前。众军听令，大喊一声，杀奔营前；见赵云全然不动，曹兵翻身就回。赵云把枪一招，壕中弓弩齐发。时天色昏黑，正不知蜀兵多少。操先拨回马走。只听得后面喊声大震，鼓角齐鸣，蜀兵赶来。曹兵自相践踏，拥到汉水河边，落水死者，不知其数。赵云、黄忠、张著各引兵一枝，追杀甚急。操正奔走间，忽刘封、孟达率二枝兵，从米仓山路杀来，放火烧粮草。操弃了北山粮草，忙回南郑。徐晃、张郃扎脚不住，亦弃本寨而走。赵云占了曹寨，黄忠夺了粮草，汉水所得军器无数，大获胜捷，差人去报玄德。玄德遂同孔明前至汉水，问赵云的部卒曰：“子龙如何厮杀？”军士将子龙救黄忠、拒汉水之事，细述一遍。玄德大喜，看了山前山后险峻之路，欣然谓孔明曰：“子龙一身都是胆也！”后人有诗赞曰：“昔日战长坂，威风犹未减。突阵显英雄，被围施勇敢。鬼哭与神号，天惊并地惨。常山赵子龙，一身都是胆！”
于是玄德号子龙为“虎威将军”，大劳将士，欢宴至晚。
忽报曹操复遣大军从斜谷小路而进，来取汉水。玄德笑曰：“操此来无能为也。我料必得汉水矣。”乃率兵于汉水之西以迎之。曹操命徐晃为先锋，前来决战。帐前一人出曰：“某深知地理，愿助徐将军同去破蜀。”操视之，乃巴西宕渠人也，姓王，名平，字子均；现充牙门将军。操大喜，遂命王平为副先锋，相助徐晃。操屯兵于定军山北。徐晃、王平引军至汉水，晃令前军渡水列阵。平曰：“军若渡水，倘要急退，如之奈何？”晃曰：“昔韩信背水为阵，所谓‘致之死地而后生’也。”平曰：“不然。昔者韩信料敌人无谋而用此计；今将军能料赵云、黄忠之意否？”晃曰：“汝可引步军拒敌，看我引马军破之。”遂令搭起浮桥，随即过河来战蜀兵。正是：魏人妄意宗韩信，蜀相那知是子房。
未知胜负如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943858, '5b9b6ea41b69e6005ba2b728', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639210, '三国演义 · 第七十二回 · 诸葛亮智取汉中 曹阿瞒兵退斜谷', NULL, 0, 120, 0, 5, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说徐晃引军渡汉水，王平苦谏不听，渡过汉水扎营。黄忠、赵云告玄德曰：“某等各引本部兵去迎曹兵。”玄德应允。二人引兵而行。忠谓云曰：“今徐晃恃勇而来，且休与敌；待日暮兵疲，你我分兵两路击之可也。”云然之，各引一军据住寨栅。徐晃引兵从辰时搦战，直至申时，蜀兵不动。晃尽教弓弩手向前，望蜀营射去。黄忠谓赵云曰：“徐晃令弓弩射者，其军必将退也：可乘时击之。”言未已，忽报曹兵后队果然退动。于是蜀营鼓声大震：黄忠领兵左出，赵云领兵右出。两下夹攻，徐晃大败，军士逼入汉水，死者无数。晃死战得脱，回营责王平曰：“汝见吾军势将危，如何不救？”平曰：“我若来救，此寨亦不能保。我曾谏公休去，公不肯听，以致此败。”晃大怒，欲杀王平。平当夜引本部军就营中放起火来，曹兵大乱，徐晃弃营而走。王平渡汉水来投赵云，云引见玄德。王平尽言汉水地理。玄德大喜曰：“孤得王子均，取汉中无疑矣。”遂命王平为偏将军，领向导使。却说徐晃逃回见操，说：“王平反去降刘备矣！”操大怒，亲统大军来夺汉水寨栅。赵云恐孤军难立，遂退于汉水之西。两军隔水相拒，玄德与孔明来观形势。孔明见汉水上流头，有一带土山，可伏千余人；乃回到营中，唤赵云分付：“汝可引五百人，皆带鼓角，伏于土山之下；或半夜，或黄昏，只听我营中炮响：炮响一番，擂鼓一番。只不要出战。”子龙受计去了。孔明却在高山上暗窥。次日，曹兵到来搦战，蜀营中一人不出，弓弩亦都不发。曹兵自回。当夜更深，孔明见曹营灯火方息，军士歇定，遂放号炮。子龙听得，令鼓角齐鸣。曹兵惊慌，只疑劫寨。及至出营，不见一军。方才回营欲歇，号炮又响，鼓角又鸣，呐喊震地，山谷应声。曹兵彻夜不安。一连三夜，如此惊疑，操心怯，拔寨退三十里，就空阔处扎营。孔明笑曰：“曹操虽知兵法，不知诡计。”遂请玄德亲渡汉水，背水结营。玄德问计，孔明曰：“可如此如此。”
曹操见玄德背水下寨，心中疑惑，使人来下战书。孔明批来日决战。次日，两军会于中路五界山前，列成阵势。操出马立于门旗下，两行布列龙凤旌旗，擂鼓三通，唤玄德答话。玄德引刘封、孟达并川中诸将而出。操扬鞭大骂曰：“刘备忘恩失义，反叛朝廷之贼！”玄德曰：“吾乃大汉宗亲，奉诏讨贼。汝上弑母后，自立为王，僭用天子銮舆，非反而何？”操怒，命徐晃出马来战，刘封出迎。交战之时，玄德先走入阵。封敌晃不住，拨马便走。操下令：“捉得刘备，便为西川之主。”大军齐呐喊杀过阵来。蜀兵望汉水而逃，尽弃营寨；马匹军器，丢满道上。曹军皆争取。操急鸣金收军。众将曰：“某等正待捉刘备，大王何故收军？”操曰：“吾见蜀兵背汉水安营，其可疑一也；多弃马匹军器，其可疑二也。可急退军，休取衣物。”遂下令曰：“妄取一物者立斩。火速退兵。”曹兵方回头时，孔明号旗举起：玄德中军领兵便出，黄忠左边杀来，赵云右边杀来。曹兵大溃而逃，孔明连夜追赶。
操传令军回南郑，只见五路火起，原来魏延、张飞得严颜代守阆中，分兵杀来，先得了南郑。操心惊，望阳平关而走。玄德大兵追至南郑褒州。安民已毕，玄德问孔明曰：“曹操此来，何败之速也？”孔明曰：“操平生为人多疑，虽能用兵，疑则多败。吾以疑兵胜之。”玄德曰：“今操退守阳平关，其势已孤，先生将何策以退之？”孔明曰：“亮已算定了。”便差张飞、魏延分兵两路去截曹操粮道，令黄忠、赵云分兵两路去放火烧山。四路军将，各引向导官军去了。
却说曹操退守阳平关，令军哨探。回报曰：“今蜀兵将远近小路，尽皆塞断；砍柴去处，尽放火烧绝。不知兵在何处。”操正疑惑间，又报张飞、魏延分兵劫粮。操问曰：“谁敢敌张飞？”许褚曰：“某愿往！”操令许褚引一千精兵，去阳平关路上护接粮草。解粮官接着，喜曰：“若非将军到此，粮不得到阳平矣。”遂将车上的酒肉，献与许褚。褚痛饮，不觉大醉，便乘酒兴，催粮车行。解粮官曰：“日已暮矣，前褒州之地，山势险恶，未可过去。”褚曰：“吾有万夫之勇，岂惧他人哉！今夜乘着月色，正好使粮车行走。”许褚当先，横刀纵马，引军前进。二更已后，往褒州路上而来。行至半路，忽山凹里鼓角震天，一枝军当住。为首大将，乃张飞也，挺矛纵马，直取许褚。褚舞刀来迎，却因酒醉，敌不住张飞；战不数合，被飞一矛刺中肩膀，翻身落马；军士急忙救起，退后便走。张飞尽夺粮草车辆而回。却说众将保着许褚，回见曹操。操令医士疗治金疮，一面亲自提兵来与蜀兵决战。玄德引军出迎。两阵对圆，玄德令刘封出马。操骂曰：“卖履小儿，常使假子拒敌！吾若唤黄须儿来，汝假子为肉泥矣！”刘封大怒，挺枪骤马，径取曹操。操令徐晃来迎，封诈败而走。操引兵追赶。蜀兵营中，四下炮响，鼓角齐鸣。操恐有伏兵，急教退军。曹兵自相践踏，死者极多，奔回阳平关，方才歇定。蜀兵赶到城下：东门放火，西门呐喊；南门放火，北门擂鼓。操大惧，弃关而走。蜀兵从后追袭。操正走之间，前面张飞引一枝兵截住，赵云引一枝兵从背后杀来，黄忠又引兵从褒州杀来。操大败。诸将保护曹操，夺路而走。方逃至斜谷界口，前面尘头忽起，一枝兵到。操曰：“此军若是伏兵，吾休矣！”及兵将近，乃操次子曹彰也。彰字子文，少善骑射；膂力过人，能手格猛兽。操尝戒之曰：“汝不读书而好弓马，此匹夫之勇，何足贵乎？”彰曰：“大丈夫当学卫青、霍去病，立功沙漠，长驱数十万众，纵横天下；何能作博士耶？”操尝问诸子之志。彰曰：“好为将。”操问：“为将何如？”彰曰：“披坚执锐，临难不顾，身先士卒；赏必行，罚必信。”操大笑。建安二十三年，代郡乌桓反，操令彰引兵五万讨之；临行戒之曰：“居家为父子，受事为君臣。法不徇情，尔宜深戒。”彰到代北，身先战阵，直杀至桑干，北方皆平；因闻操在阳平败阵，故来助战。操见彰至，大喜曰：“我黄须儿来，破刘备必矣！”遂勒兵复回，于斜谷界口安营。有人报玄德，言曹彰到。玄德问曰：“谁敢去战曹彰？”刘封曰：“某愿往。”孟达又说要去。玄德曰：“汝二人同去，看谁成功。”各引兵五千来迎：“刘封在先，孟达在后，曹彰出马与封交战，只三合，封大败而回。孟达引兵前进，方欲交锋，只见曹兵大乱。原来马超、吴兰两军杀来，曹兵惊动。孟达引兵夹攻。马超士卒，蓄锐日久，到此耀武扬威，势不可当。曹兵败走。曹彰正遇吴兰，两个交锋，不数合，曹彰一戟刺吴兰于马下。三军混战。操收兵于斜谷界口扎住。操屯兵日久，欲要进兵，又被马超拒守；欲收兵回，又恐被蜀兵耻笑，心中犹豫不决。适庖官进鸡汤。操见碗中有鸡肋，因而有感于怀。正沉吟间，夏侯惇入帐，禀请夜间口号。操随口曰：“鸡肋！鸡肋！”惇传令众官，都称“鸡肋”。行军主簿杨修，见传“鸡肋”二字，便教随行军士，各收拾行装，准备归程。有人报知夏侯惇。惇大惊，遂请杨修至帐中问曰：“公何收拾行装？”修曰：“以今夜号令，便知魏王不日将退兵归也：鸡肋者，食之无肉，弃之有味。今进不能胜，退恐人笑，在此无益，不如早归：来日魏王必班师矣。故先收拾行装，免得临行慌乱。”夏侯惇曰：“公真知魏王肺腑也！”遂亦收拾行装。于是寨中诸将，无不准备归计。当夜曹操心乱，不能稳睡，遂手提钢斧，绕寨私行。只见夏侯惇寨内军士，各准备行装。操大惊，急回帐召惇问其故。惇曰：“主簿杨德祖先知大王欲归之意。”操唤杨修问之，修以鸡肋之意对。操大怒曰：“汝怎敢造言，乱我军心！”喝刀斧手推出斩之，将首级号令于辕门外。原来杨修为人恃才放旷，数犯曹操之忌：操尝造花园一所；造成，操往观之，不置褒贬，只取笔于门上书一“活”字而去。人皆不晓其意。修曰：“‘门’内添‘活’字，乃阔字也。丞相嫌园门阔耳。”于是再筑墙围，改造停当，又请操观之。操大喜，问曰：“谁知吾意？”左右曰：“杨修也。”操虽称美，心甚忌之。又一日，塞北送酥一盒至。操自写“一合酥”三字于盒上，置之案头。修入见之，竟取匙与众分食讫。操问其故，修答曰：“盒上明书‘一人一口酥’，岂敢违丞相之命乎？”操虽喜笑，而心恶之。操恐人暗中谋害己身，常分付左右：“吾梦中好杀人；凡吾睡着，汝等切勿近前。”一日，昼寝帐中，落被于地，一近侍慌取覆盖。操跃起拔剑斩之，复上床睡；半晌而起，佯惊问：“何人杀吾近侍？”众以实对。操痛哭，命厚葬之。人皆以为操果梦中杀人；惟修知其意，临葬时指而叹曰：“丞相非在梦中，君乃在梦中耳！”操闻而愈恶之。操第三子曹植，爱修之才，常邀修谈论，终夜不息。操与众商议，欲立植为世子，曹丕知之，密请朝歌长吴质入内府商议；因恐有人知觉，乃用大簏藏吴质于中，只说是绢匹在内，载入府中。修知其事，径来告操。操令人于丕府门伺察之。丕慌告吴质，质曰：“无忧也：明日用大簏装绢再入以惑之。”丕如其言，以大簏载绢入。使者搜看簏中，果绢也，回报曹操。操因疑修谮害曹丕，愈恶之。操欲试曹丕、曹植之才干。一日，令各出邺城门；却密使人分付门吏，令勿放出。曹丕先至，门吏阻之，丕只得退回。植闻之，问于修。修曰：“君奉王命而出，如有阻当者，竟斩之可也。”植然其言。及至门，门吏阻住。植叱曰：“吾奉王命，谁敢阻当！”立斩之。于是曹操以植为能。后有人告操曰：“此乃杨修之所教也。”操大怒，因此亦不喜植。修又尝为曹植作答教十余条，但操有问，植即依条答之。操每以军国之事问植，植对答如流。操心中甚疑。后曹丕暗买植左右，偷答教来告操。操见了大怒曰：“匹夫安敢欺我耶！”此时已有杀修之心；今乃借惑乱军心之罪杀之。修死年三十四岁。后人有诗曰：“聪明杨德祖，世代继簪缨。笔下龙蛇走，胸中锦绣成。开谈惊四座，捷对冠群英。身死因才误，非关欲退兵。”
曹操既杀杨修，佯怒夏侯惇，亦欲斩之。众官告免。操乃叱退夏侯惇，下令来日进兵。次日，兵出斜谷界口，前面一军相迎，为首大将乃魏延也。操招魏延归降，延大骂。操令庞德出战。二将正斗间，曹寨内火起。人报马超劫了中后二寨。操拔剑在手曰：“诸将退后者斩！”众将努力向前，魏延诈败而走。操方麾军回战马超，自立马于高阜处，看两军争战。忽一彪军撞至面前，大叫：“魏延在此！”拈弓搭箭，射中曹操。操翻身落马。延弃弓绰刀，骤马上山坡来杀曹操。刺斜里闪出一将，大叫：“休伤吾主！”视之，乃庞德也。德奋力向前，战退魏延，保操前行。马超已退。操带伤归寨：原来被魏延射中人中，折却门牙两个，急令医士调治。方忆杨修之言，随将修尸收回厚葬，就令班师；却教庞德断后。操卧于毡车之中，左右虎贲军护卫而行。忽报斜谷山上两边火起，伏兵赶来。曹兵人人惊恐。正是：依稀昔日潼关厄，仿佛当年赤壁危。
未知曹操性命如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943860, '5b9b6eccfb4ffe005cafe7bc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639211, '三国演义 · 第七十三回 · 玄德进位汉中王 云长攻拔襄阳郡', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说曹操退兵至斜谷，孔明料他必弃汉中而走，故差马超等诸将，分兵十数路，不时攻劫。因此操不能久住；又被魏延射了一箭，急急班师。三军锐气堕尽。前队才行，两下火起，乃是马超伏兵追赶。曹兵人人丧胆。操令军士急行，晓夜奔走无停；直至京兆，方始安心。
且说玄德命刘封、孟达、王平等，攻取上庸诸郡，申耽等闻操已弃汉中而走，遂皆投降，玄德安民已定，大赏三军，人心大悦。于是众将皆有推尊玄德为帝之心；未敢径启，却来禀告诸葛军师，孔明曰：“吾意已有定夺了。”随引法正等入见玄德，曰：“今曹操专权，百姓无主；主公仁义著于天下，今已抚有两川之地，可以应天顺人，即皇帝位，名正言顺，以讨国贼。事不宜迟，便请择吉。”玄德大惊曰：“军师之言差矣。刘备虽然汉之宗室，乃臣子也；若为此事，是反汉矣。”孔明曰：“非也。方今天下分崩，英雄并起，各霸一方，四海才德之士，舍死亡生而事其上者，皆欲攀龙附凤，建立功名也。今主公避嫌守义，恐失众人之望。愿主公熟思之。”玄德曰：“要吾僭居尊位，吾必不敢。可再商议长策。”诸将齐言曰：“主公若只推却，众心解矣。”孔明曰：“主公平生以义为本，未肯便称尊号。今有荆襄、两川之地，可暂为汉中王。”玄德曰：“汝等虽欲尊吾为王，不得天子明诏，是僭也。”孔明曰：“今宜从权，不可拘执常理。”张飞大叫曰：“异姓之人，皆欲为君何，况哥哥乃汉朝宗派！莫说汉中王，就称皇帝，有何不可！”玄德叱曰：“汝勿多言！”孔明曰：“主公宜从权变，先进位汉中王，然后表奏天子，未为迟也。”
玄德再三推辞不过，只得依允。建安二十四年秋七月，筑坛于沔阳，方圆九里，分布五方，各设旌旗仪仗。群臣皆依次序排列。许靖、法正请玄德登坛，进冠冕玺绶讫，面南而坐，受文武官员拜贺为汉中王。子刘禅，立为王世子。封许靖为太傅，法正为尚书令；诸葛亮为军师，总理军国重事。封关羽、张飞、赵云、马超、黄忠为五虎大将，魏延为汉中太守。其余各拟功勋定爵。玄德既为汉中王，遂修表一道，差人赍赴许都。表曰：“备以具臣之才，荷上将之任，总督三军，奉辞于外；不能扫除寇难，靖匡王室，久使陛下圣教陵迟，六合之内，否而未泰：惟忧反侧，疢如疾首。曩者董卓，伪为乱阶。自是之后，群凶纵横，残剥海内。赖陛下圣德威临，人臣同应，或忠义奋讨，或上天降罚，暴逆并殪，以渐冰消。惟独曹操，久未枭除，侵擅国权，恣心极乱。臣昔与车骑将军董承，图谋讨操，机事不密，承见陷害。臣播越失据，忠义不果，遂得使操穷凶极逆：主后戮杀，皇子鸩害。虽纠合同盟，念在奋力；懦弱不武，历年未效。常恐殒没，辜负国恩；寤寐永叹，夕惕若厉。今臣群僚以为：在昔《虞书》，敦叙九族，庶明励翼；帝王相传，此道不废；周监二代，并建诸姬，实赖晋、郑夹辅之力；高祖龙兴，尊王子弟，大启九国，卒斩诸吕，以安大宗。今操恶直丑正，实繁有徒，包藏祸心，篡盗已显；既宗室微弱，帝族无位，斟酌古式，依假权宜：上臣为大司马、汉中王。臣伏自三省：受国厚恩，荷任一方，陈力未效，所获已过，不宜复忝高位，以重罪谤。群僚见逼，迫臣以义。臣退惟寇贼不枭，国难未已；宗庙倾危，社稷将坠：诚臣忧心碎首之日。若应权通变，以宁静圣朝，虽赴水火，所不得辞。辄顺众议，拜受印玺，以崇国威。仰惟爵号，位高宠厚；俯思报效，忧深责重。惊怖惕息，如临于谷。敢不尽力输诚，奖励六师，率齐群义，应天顺时，以宁社稷。谨拜表以闻。”
表到许都，曹操在邺郡闻知玄德自立汉中王，大怒曰：“织席小儿，安敢如此！吾誓灭之！”即时传令，尽起倾国之兵，赴两川与汉中王决雌雄。一人出班谏曰：“大王不可因一时之怒，亲劳车驾远征。臣有一计，不须张弓只箭，令刘备在蜀自受其祸；待其兵衰力尽，只须一将往征之，便可成功。”操视其人，乃司马懿也。操喜问曰：“仲达有何高见？”懿曰：“江东孙权，以妹嫁刘备，而又乘间窃取回去；刘备又据占荆州不还：彼此俱有切齿之恨。今可差一舌辩之士，赍书往说孙权，使兴兵取荆州；刘备必发两川之兵以救荆州。那时大王兴兵去取汉川，令刘备首尾不能相救，势必危矣。”操大喜，即修书令满宠为使，星夜投江东来见孙权。
权知满宠到，遂与谋士商议。张昭进曰：“魏与吴本无仇；前因听诸葛之说词，致两家连年征战不息，生灵遭其涂炭。今满伯宁来，必有讲和之意，可以礼接之。”权依其言，令众谋士接满宠入城相见。礼毕，权以宾礼待宠。宠呈上操书，曰：“吴、魏自来无仇，皆因刘备之故，致生衅隙。魏王差某到此，约将军攻取荆州，魏王以兵临汉川，首尾夹击。破刘之后，共分疆土，誓不相侵。”孙权览书毕，设筵相待满宠，送归馆舍安歇。权与众谋士商议。顾雍曰：“虽是说词，其中有理。今可一面送满宠回，约会曹操，首尾相击；一面使人过江探云长动静，方可行事。”诸葛瑾曰：“某闻云长自到荆州，刘备娶与妻室，先生一子，次生一女。其女尚幼，未许字人。某愿往与主公世子求婚。若云长肯许，即与云长计议共破曹操；若云长不肯，然后助曹取荆州。”孙权用其谋，先送满宠回许都；却遣诸葛瑾为使，投荆州来。入城见云长，礼毕。云长曰：“子瑜此来何意？”瑾曰：“特来求结两家之好：吾主吴侯有一子，甚聪明；闻将军有一女，特来求亲。两家结好，并力破曹。此诚美事，请君侯思之。”云长勃然大怒曰：“吾虎女安肯嫁犬子乎！不看汝弟之面，立斩汝首！再休多言！”遂唤左右逐出。瑾抱头鼠窜，回见吴侯；不敢隐匿，遂以实告。权大怒曰：“何太无礼耶！”便唤张昭等文武官员，商议取荆州之策。步骘曰：“曹操久欲篡汉，所惧者刘备也；今遣使来令吴兴兵吞蜀，此嫁祸于吴也。”权曰：“孤亦欲取荆州久矣。”骘曰：“今曹仁现屯兵于襄阳、樊城，又无长江之险，旱路可取荆州；如何不取，却令主公动兵？只此便见其心。主公可遣使去许都见操，令曹仁旱路先起兵取荆州，云长必掣荆州之兵而取樊城。若云长一动，主公可遣一将，暗取荆州，一举可得矣。”权从其议，即时遣使过江，上书曹操，陈说此事。操大喜，发付使者先回，随遣满宠往樊城助曹仁，为参谋官，商议动兵；一面驰檄东吴，令领兵水路接应，以取荆州。
却说汉中王令魏延总督军马，守御东川。遂引百官回成都。差官起造宫庭，又置馆舍，自成都至白水，共建四百余处馆舍亭邮。广积粮草。多造军器，以图进取中原。细作人探听得曹操结连东吴，欲取荆州，即飞报入蜀。汉中王忙请孔明商议。孔明曰：“某已料曹操必有此谋；然吴中谋士极多，必教操令曹仁先兴兵矣。”汉中王曰：“似此如之奈何？”孔明曰：“可差使命就送官诰与云长，令先起兵取樊城，使敌军胆寒，自然瓦解矣。”汉中王大喜，即差前部司马费诗为使，赍捧诰命投荆州来。云长出郭，迎接入城。至公廨礼毕，云长问曰：“汉中王封我何爵？”诗曰：“五虎大将之首。”云长问：“那五虎将？”诗曰：“关、张、赵、马、黄是也。”云长怒曰：“翼德吾弟也；孟起世代名家；子龙久随吾兄，即吾弟也：位与吾相并，可也。黄忠何等人，敢与吾同列？大丈夫终不与老卒为伍？”遂不肯受印。诗笑曰：“将军差矣。昔萧何、曹参与高祖同举大事，最为亲近，而韩信乃楚之亡将也；然信位为王，居萧、曹之上，未闻萧、曹以此为怨。今汉中王虽有五虎将之封，而与将军有兄弟之义，视同一体。将军即汉中王，汉中王即将军也。岂与诸人等哉？将军受汉中王厚恩，当与同休戚、共祸福，不宜计较官号之高下。愿将军熟思之。”云长大悟，乃再拜曰：“某之不明，非足下见教，几误大事。”即拜受印绶。
费诗方出王旨，令云长领兵取樊城。云长领命，即时便差傅士仁、糜芳二人为先锋，先引一军于荆州城外屯扎；一面设宴城中，款待费诗。饮至二更，忽报城外寨中火起。云长急披挂上马，出城看时，乃是傅士仁、糜芳饮酒，帐后遗火，烧着火炮，满营撼动，把军器粮草，尽皆烧毁。云长引兵救扑，至四更方才火灭。云长入城，召傅士仁、糜芳责之曰：“吾令汝二人作先锋，不曾出师，先将许多军器粮草烧毁，火炮打死本部军人。如此误事，要你二人何用？”叱令斩之。费诗告曰：“未曾出师，先斩大将，于军不利。可暂免其罪。”云长怒气不息，叱二人曰：“吾不看费司马之面，必斩汝二人之首！”乃唤武士各杖四十，摘去先锋印绶，罚糜芳守南郡，傅士仁守公安；且曰：“若吾得胜回来之日，稍有差池，二罪俱罚！”二人满面羞惭，喏喏而去。
云长便令廖化为先锋，关平为副将，自总中军，马良、伊籍为参谋，一同征进。先是，有胡华之子胡班，到荆州来投降关公；公念其旧日相救之情，甚爱之；令随费诗入川，见汉中王受爵。费诗辞别关公，带了胡班，自回蜀中去了。
且说关公是日祭了“帅”字大旗，假寐于帐中。忽见一猪，其大如牛，浑身黑色，奔入帐中，径咬云长之足。云长大怒，急拔剑斩之，声如裂帛。霎然惊觉，乃是一梦。便觉左足阴阴疼痛，心中大疑。唤关平至，以梦告之。平对曰：“猪亦有龙象。龙附足，乃升腾之意，不必疑忌。”云长聚多官于帐下，告以梦兆。或言吉祥者，或言不祥者，众论不一。云长曰：“吾大丈夫，年近六旬，即死何憾！”正言间，蜀使至，传汉中王旨，拜云长为前将军，假节钺，都督荆襄九郡事。云长受命讫，众官拜贺曰：“此足见猪龙之瑞也。”于是云长坦然不疑，遂起兵奔襄阳大路而来。
曹仁正在城中，忽报云长自领兵来。仁大惊，欲坚守不出，副将翟元曰：“今魏王令将军约会东吴取荆州；今彼自来，是送死也，何故避之！”参谋满宠谏曰：“吾素知云长勇而有谋，未可轻敌。不如坚守，乃为上策。”骁将夏侯存曰：“此书生之言耳。岂不闻‘水来土掩，将至兵迎’？我军以逸待劳，自可取胜。”曹仁从其言，令满宠守樊城，自领兵来迎云长。
云长知曹兵来，唤关平、廖化二将，受计而往。与曹兵两阵对圆，廖化出马搦战。翟元出迎。二将战不多时，化诈败，拨马便走，翟元从后追杀，荆州兵退二十里。次日，又来搦战。夏侯存、翟元一齐出迎，荆州兵又败，又追杀二十余里。忽听得背后喊声大震，鼓角齐鸣。曹仁急命前军速回，背后关平、廖化杀来，曹兵大乱。曹仁知是中计，先掣一军飞奔襄阳；离城数里，前面绣旗招飐，云长勒马横刀，拦住去路。曹仁胆战心惊，不敢交锋，望襄阳斜路而走。云长不赶。须臾，夏侯存军至，见了云长，大怒，便与云长交锋，只一合，被云长砍死。翟元便走，被关平赶上，一刀斩之。乘势追杀，曹兵大半死于襄江之中。曹仁退守樊城。
云长得了襄阳，赏军抚民。随军司马王甫曰：“将军一鼓而下襄阳，曹兵虽然丧胆，然以愚意论之：今东吴吕蒙屯兵陆口，常有吞并荆州之意；倘率兵径取荆州，如之奈何？”云长曰：“吾亦念及此。汝便可提调此事：去沿江上下，或二十里，或三十里，选高阜处置一烽火台，每台用五十军守之；倘吴兵渡江，夜则明火，昼则举烟为号。吾当亲往击之。”王甫曰：“糜芳、傅士仁守二隘口，恐不竭力；必须再得一人以总督荆州。”云长曰：“吾已差治中潘濬守之，有何虑焉？”甫曰：“潘濬平生多忌而好利，不可任用。可差军前都督粮料官赵累代之。赵累为人忠城廉直。若用此人，万无一失。”云长曰：“吾素知潘浚为人。今既差定，不必更改。赵累现掌粮料，亦是重事。汝勿多疑，只与我筑烽火台去。”王甫怏怏拜辞而行。云长令关平准备船只渡襄江，攻打樊城。
却说曹仁折了二将，退守樊城，谓满宠曰：“不听公言，兵败将亡，失却襄阳，如之奈何？”宠曰：“云长虎将，足智多谋，不可轻敌，只宜坚守。”正言间，人报云长渡江而来，攻打樊城。仁大惊，宠曰：“只宜坚守。”部将吕常奋然曰：“某乞兵数千，愿当来军于襄江之内。”宠谏曰：“不可。”吕常怒曰：“据汝等文官之言，只宜坚守，何能退敌？岂不闻兵法云：军半渡可击。今云长军半渡襄江，何不击之？若兵临城下，将至壕边，急难抵当矣。”仁即与兵二千，令吕常出樊城迎战。吕常来至江口，只见前面绣旗开处，云长横刀出马。吕常却欲来迎，后面众军见云长神威凛凛，不战先走，吕常喝止不住。云长混杀过来，曹兵大败，马步军折其大半，残败军奔入樊城。曹仁急差人求救，使命星夜至长安，将书呈上曹操，言：“云长破了襄阳，现围樊城甚急。望拨大将前来救援。”曹操指班部内一人而言曰：“汝可去解樊城之围。”其人应声而出。众视之，乃于禁也。禁曰：“某求一将作先锋，领兵同去。”操又问众人曰：“谁敢作先锋？”一人奋然出曰：“某愿施犬马之劳，生擒关某，献于麾下。”操观之大喜。正是：未见东吴来伺隙，先看北魏又添兵。
未知此人是谁，且看下文分解。', '', '', '', NULL, '', 'indent', 1536944218, '5b9b6eddfb4ffe005cafe880', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639212, '三国演义 · 第七十四回 · 庞令明抬榇决死战 关云长放水淹七军', NULL, 3, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说曹操欲使于禁赴樊城救援，问众将谁敢作先锋。一人应声愿往。操视之，乃庞德也。操大喜曰：“关某威震华夏，未逢对手；今遇令明，真劲敌也。”遂加于禁为征南将军，加宠德为征西都先锋，大起七军，前往樊城。这七军，皆北方强壮之士。两员领军将校：一名董衡，一名董超；当日引各头目参拜于禁。董衡曰：“今将军提七枝重兵，去解樊城之厄，期在必胜，乃用庞德为先锋，岂不误事？”禁惊问其故。衡曰：“庞德原系马超手下副将，不得已而降魏；今其故主在蜀，职居‘五虎上将’；况其亲兄庞柔亦在西川为官，今使他为先锋，是泼油救火也。将军何不启知魏王，别换一人去？”
禁闻此语，遂连夜入府启知曹操。操省悟，即唤庞德至阶下，令纳下先锋印。德大惊曰：“某正欲与大王出力，何故不肯见用？”操曰：“孤本无猜疑；但今马超现在西川，汝兄庞柔亦在西川，俱佐刘备。孤纵不疑，奈众口何？”庞德闻之，免冠顿首，流血满面而告曰：“某自汉中投降大王，每感厚恩，虽肝脑涂地，不能补报；大王何疑于德也？德昔在故乡时，与兄同居，嫂甚不贤，德乘醉杀之；兄恨德入骨髓，誓不相见，恩已断矣。故主马超，有勇无谋，兵败地亡，孤身入川，今与德各事其主，旧义已绝。德感大王恩遇，安敢萌异志？惟大王察之。”操乃扶起庞德，抚慰曰：“孤素知卿忠义，前言特以安众人之心耳。卿可努力建功。卿不负孤，孤亦必不负卿也。”德拜谢回家，令匠人造一木榇。次日，请诸友赴席，列榇于堂。众亲友见之，皆惊问曰：“将军出师，何用此不祥之物？”德举杯谓亲友曰：“吾受魏王厚恩，誓以死报。今去樊城与关某决战，我若不能杀彼，必为彼所杀；即不为彼所杀，我亦当自杀。故先备此榇，以示无空回之理。”众皆嗟叹。德唤其妻李氏与其子庞会出，谓其妻曰：“吾今为先锋，义当效死疆场。我若死，汝好生看养吾儿；吾儿有异相，长大必当与吾报仇也。”妻子痛哭送别，德令扶榇而行。临行，谓部将曰：“吾今去与关某死战，我若被关某所杀，汝等即取吾尸置此榇中；我若杀了关某，吾亦即取其首，置此榇内，回献魏王。”部将五百人皆曰：“将军如此忠勇，某等敢不竭力相助！”于是引军前进。有人将此言报知曹操。操喜曰：“庞德忠勇如此，孤何忧焉！”贾诩曰：“庞德恃血气之勇，欲与关某决死战，臣窃虑之。”操然其言，急令人传旨戒庞德曰：“关某智勇双全，切不可轻敌。可取则取，不可取则宜谨守。”庞德闻命，谓众将曰：“大王何重视关某也？吾料此去，当挫关某三十年之声价。”禁曰：“魏王之言，不可不从。”德奋然趱军前至樊城，耀武扬威，鸣锣击鼓。
却说关公正坐帐中，忽探马飞报：“曹操差于禁为将，领七枝精壮兵到来。前部先锋庞德，军前抬一木榇，口出不逊之言，誓欲与将军决一死战。兵离城止三十里矣。”关公闻言，勃然变色，美髯飘动，大怒曰：“天下英雄，闻吾之名，无不畏服；庞德竖子，何敢藐视吾耶！关平一面攻打樊城，吾自去斩此匹夫，以雪吾恨！”平曰：“父亲不可以泰山之重，与顽石争高下。辱子愿代父去战庞德。”关公曰：“汝试一往，吾随后便来接应。”关平出帐，提刀上马，领兵来迎庞德。两阵对圆，魏营一面皂旗上大书“南安庞德”四个白字。庞德青袍银铠，钢刀白马，立于阵前；背后五百军兵紧随，步卒数人肩抬木榇而出。关平大骂庞德：“背主之贼！”庞德问部卒曰：“此何人也？”或答曰：“此关公义子关平也。”德叫曰：“吾奉魏王旨，来取汝父之首！汝乃疥癞小儿，吾不杀汝！快唤汝父来！”平大怒，纵马舞刀，来取庞德。德横刀来迎。战三十合，不分胜负，两家各歇。早有人报知关公。公大怒，令廖化去攻樊城，自己亲来迎敌庞德。关平接着，言与庞德交战，不分胜负。关公随即横刀出马，大叫曰：“关云长在此，庞德何不早来受死！”鼓声响处，庞德出马曰：“吾奉魏王旨，特来取汝首！恐汝不信，备榇在此。汝若怕死，早下马受降！”关公大骂曰：“量汝一匹夫，亦何能为！可惜我青龙刀斩汝鼠贼！”纵马舞刀，来取庞德。德轮刀来迎。二将战有百余合，精神倍长。两军各看得痴呆了。魏军恐庞德有失，急令鸣金收军。关平恐父年老，亦急鸣金。二将各退。庞德归寨，对众曰：“人言关公英雄，今日方信也。”正言间，于禁至。相见毕，禁曰：“闻将军战关公，百合之上，未得便宜，何不且退军避之？”德奋然曰：“魏王命将军为大将，何太弱也？吾来日与关某共决一死，誓不退避！”禁不敢阻而回。
却说关公回寨，谓关平曰：“庞德刀法惯熟，真吾敌手。”平曰：“俗云：‘初生之犊不惧虎，’父亲纵然斩了此人，只是西羌一小卒耳；倘有疏虞，非所以重伯父之托也。”关公曰：“吾不杀此人，何以雪恨？吾意已决，再勿多言！”次日，上马引兵前进。庞德亦引兵来迎。两阵对圆，二将齐出，更不打话，出马交锋。斗至五十余合，庞德拨回马，拖刀而走。关公随后追赶。关平恐有疏失，亦随后赶去。关公口中大骂：“庞贼！欲使拖刀计，吾岂惧汝？”原来庞德虚作拖刀势，却把刀就鞍鞒挂住，偷拽雕弓，搭上箭，射将来。关平眼快，见庞德拽弓，大叫：“贼将休放冷箭！”关公急睁眼看时，弓弦响处，箭早到来；躲闪不及，正中左臂。关平马到，救父回营。庞德勒回马轮刀赶来，忽听得本营锣声大震。德恐后军有失，急勒马回。原来于禁见庞德射中关公，恐他成了大功，灭禁威风，故鸣金收军。庞德回马，问：“何故鸣金？”于禁曰：“魏王有戒：关公智勇双全。他虽中箭，只恐有诈，故鸣金收军。”德曰：“若不收军，吾已斩了此人也。”禁曰：“紧行无好步，当缓图之。”庞德不知于禁之意，只懊悔不已。
却说关公回营，拔了箭头。幸得箭射不深，用金疮药敷之。关公痛恨庞德，谓众将曰：“吾誓报此一箭之仇！”众将对曰：“将军且暂安息几日，然后与战未迟。”次日，人报庞德引军搦战。关公就要出战。众将劝住。庞德令小军毁骂。关平把住隘口，分付众将休报知关公。庞德搦战十余日，无人出迎，乃与于禁商议曰：“眼见关公箭疮举发，不能动止；不若乘此机会，统七军一拥杀入寨中，可救樊城之围。”于禁恐庞德成功，只把魏王戒旨相推，不肯动兵。庞德累欲动兵，于禁只不允，乃移七军转过山口，离樊城北十里，依山下寨，禁自领兵截断大路，令庞德屯兵于谷后，使德不能进兵成功。
却说关平见关公箭疮已合，甚是喜悦。忽听得于禁移七军于樊城之北下寨，未知其谋，即报知关公。公遂上马，引数骑上高阜处望之，见樊城城上旗号不整，军士慌乱；城北十里山谷之内，屯着军马；又见襄江水势甚急，看了半响，唤向导官问曰：“樊城北十里山谷，是何地名？”对曰：“罾口川也。”关公喜曰：“于禁必为我擒矣。”将士问曰：“将军何以知之？”关公曰：“‘鱼’入‘罾口’，岂能久乎？”诸将未信。公回本寨。时值八月秋天，骤雨数日。公令人预备船筏，收拾水具。关平问曰：“陆地相持，何用水具？”公曰：“非汝所知也。于禁七军不屯于广易之地，而聚于罾口川险隘之处；方今秋雨连绵，襄江之水必然泛涨；吾已差人堰住各处水口，待水发时，乘高就船，放水一淹，樊城，罾口川之兵皆为鱼鳖矣。”关平拜服。却说魏军屯于罾口川，连日大雨不止，督将成何来见于禁曰：“大军屯于川口，地势甚低；虽有土山，离营稍远。即今秋雨连绵，军士艰辛。近有人报说荆州兵移于高阜处，又于汉水口预备战筏；倘江水泛涨，我军危矣，宜早为计。”于禁叱曰：“匹夫惑吾军心耶！再有多言者斩之！”成何羞惭而退，却来见庞德，说此事。德曰：“汝所见甚当。于将军不肯移兵，吾明日自移军屯于他处。”
计议方定，是夜风雨大作。庞德坐于帐中，只听得万马争奔，征鼙震地。德大惊，急出帐上马看时，四面八方，大水骤至；七军乱窜，随波逐浪者，不计其数。平地水深丈余，于禁、庞德与诸将各登小山避水。比及平明，关公及众将皆摇旗鼓噪，乘大船而来。于禁见四下无路，左右止有五六十人，料不能逃，口称“愿降”。关公令尽去衣甲，拘收入船，然后来擒庞德。时庞德并二董及成何，与步卒五百人，皆无衣甲，立在堤上。见关公来，庞德全无惧怯，奋然前来接战。关公将船四面围定，军士一齐放箭，射死魏兵大半。董衡、董超见势已危，乃告庞德曰：“军士折伤大半，四下无路，不如投降。”庞德大怒曰：“吾受魏王厚恩，岂肯屈节于人！”遂亲斩董衡、董超于前，厉声曰：“再说降者，以此二人为例！”于是众皆奋力御敌。自平明战至日中，勇力倍增。关公催四面急攻，矢石如雨。德令军士用短兵接战。德回顾成何曰：“吾闻‘勇将不怯死以苟免，壮士不毁节而求生’。今日乃我死日也。汝可努力死战。”成何依令向前，被关公一箭射落水中。众军皆降，止有庞德一人力战。正遇荆州数十人，驾小船近堤来，德提刀飞身一跃，早上小船，立杀十余人，余皆弃船赴水逃命。庞德一手提刀，一手使短棹，欲向樊城而走。只见上流头，一将撑大筏而至，将小船撞翻，庞德落于水中。船上那将跳下水去，生擒庞德上船。众视之，擒庞德者，乃周仓也。仓素知水性，又在荆州住了数年，愈加惯熟；更兼力大，因此擒了庞德。于禁所领七军，皆死于水中。其会水者料无去路，亦皆投降。后人有诗曰：“夜半征鼙响震天，襄樊平地作深渊。关公神算谁能及，华夏威名万古传。”
关公回到高阜去处，升帐而坐。群刀手押过于禁来。禁拜伏于地，乞哀请命。关公曰：“汝怎敢抗吾？”禁曰：“上命差遣，身不由己。望君侯怜悯，誓以死报。”公绰髯笑曰：“吾杀汝，犹杀狗彘耳，空污刀斧！”令人缚送荆州大牢内监候：“待吾回，别作区处。”发落去讫。关公又令押过庞德。德睁眉怒目，立而不跪，关公曰：“汝兄现在汉中；汝故主马超，亦在蜀中为大将。汝如何不早降？”德大怒曰：“吾宁死于刀下，岂降汝耶！”骂不绝口。公大怒，喝令刀斧手推出斩之。德引颈受刑。关公怜而葬之。于是乘水势未退，复上战船，引大小将校来攻樊城。却说樊城周围，白浪滔天，水势益甚，城垣渐渐浸塌，男女担土搬砖，填塞不住。曹军众将，无不丧胆，慌忙来告曹仁曰：“今日之危，非力可救；可趁敌军未至，乘舟夜走，虽然失城，尚可全身。”仁从其言。方欲备船出走，满宠谏曰：“不可。山水骤至，岂能长存？不旬日即当自退。关公虽未攻城，已遣别将在郏下。其所以不敢轻进者，虑吾军袭其后也。今若弃城而去，黄河以南，非国家之有矣。”愿将军固守此城，以为保障。”仁拱手称谢曰：“非伯宁之教，几误大事。”乃骑白马上城，聚众将发誓曰：“吾受魏王命，保守此城；但有言弃城而去者斩！”诸将皆曰：“某等愿以死据守！”仁大喜，就城上设弓弩数百，军士昼夜防护，不敢懈怠。老幼居民，担土石填塞城垣。旬日之内，水势渐退。
关公自擒魏将于禁等，威震天下，无不惊骇。忽次子关兴来寨内省亲。公就令兴赍诸官立功文书去成都见汉中王，各求升迁。兴拜辞父亲，径投成都去讫。
却说关公分兵一半，直抵郏下。公自领兵四面攻打樊城。当日关公自到北门，立马扬鞭，指而问曰：“汝等鼠辈，不早来降，更待何时？”正言间，曹仁在敌楼上，见关公身上止披掩心甲，斜袒着绿袍，乃急招五百弓弩手，一齐放箭。公急勒马回时，右臂上中一弩箭，翻身落马。正是：水里七军方丧胆，城中一箭忽伤身。
未知关公性命如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943860, '5b9b6f011579a3003a4f9c44', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639213, '三国演义 · 第七十五回 · 关云长刮骨疗毒 吕子明白衣渡江', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说曹仁见关公落马，即引兵冲出城来；被关平一阵杀回，救关公归寨，拔出臂箭。原来箭头有药，毒已入骨，右臂青肿，不能运动。关平慌与众将商议曰：“父亲若损此臂，安能出敌？不如暂回荆州调理。”于是与众将入帐见关公。公问曰：“汝等来有何事？”众对曰：“某等因见君侯右臂损伤，恐临敌致怒，冲突不便。众议可暂班师回荆州调理。”公怒曰：“吾取樊城，只在目前；取了樊城，即当长驱大进，径到许都，剿灭操贼，以安汉室。岂可因小疮而误大事？汝等敢慢吾军心耶！”平等默然而退。众将见公不肯退兵，疮又不痊，只得四方访问名医。忽一日，有人从江东驾小舟而来，直至寨前。小校引见关平。平视其人：方巾阔服，臂挽青囊；自言姓名，乃沛国谯郡人，姓华，名伦，字元化。因闻关将军乃天下英雄，今中毒箭，特来医治。平曰：“莫非昔日医东吴周泰者乎？”佗曰：“然。”平大喜，即与众将同引华佗入帐见关公。时关公本是臂疼，恐慢军心，无可消遣，正与马良弈棋；闻有医者至，即召入。礼毕，赐坐。茶罢，佗请臂视之。公袒下衣袍，伸臂令佗看视。佗曰：“此乃弩箭所伤，其中有乌头之药，直透入骨；若不早治，此臂无用矣。”公曰：“用何物治之？”佗曰：“某自有治法，但恐君侯惧耳。”公笑曰：“吾视死如归，有何惧哉？”佗曰：“当于静处立一标柱，上钉大环，请君侯将臂穿于环中，以绳系之，然后以被蒙其首。吾用尖刀割开皮肉，直至于骨，刮去骨上箭毒，用药敷之，以线缝其口，方可无事。但恐君侯惧耳。”公笑曰：“如此，容易！何用柱环？”令设酒席相待。
公饮数杯酒毕，一面仍与马良弈棋，伸臂令佗割之。佗取尖刀在手，令一小校捧一大盆于臂下接血。佗曰：“某便下手，君侯勿惊。”公曰：“任汝医治，吾岂比世间俗子，惧痛者耶！”佗乃下刀，割开皮肉，直至于骨，骨上已青；佗用刀刮骨，悉悉有声。帐上帐下见者，皆掩面失色。公饮酒食肉，谈笑弈棋，全无痛苦之色。须臾，血流盈盆。佗刮尽其毒，敷上药，以线缝之。公大笑而起，谓众将曰：“此臂伸舒如故，并无痛矣。先生真神医也！”佗曰：“某为医一生，未尝见此。君侯真天神也！”后人有诗曰：“治病须分内外科，世间妙艺苦无多。神威罕及惟关将，圣手能医说华佗。”
关公箭疮既愈，设席款谢华佗。佗曰：“君侯箭疮虽治，然须爱护。切勿怒气伤触。过百日后，平复如旧矣。”关公以金百两酬之。佗曰：“某闻君侯高义，特来医治，岂望报乎！”坚辞不受，留药一帖，以敷疮口，辞别而去。
却说关公擒了于禁，斩了庞德，威名大震，华夏皆惊。探马报到许都，曹操大惊，聚文武商议曰：“某素知云长智勇盖世，今据荆襄，如虎生翼。于禁被擒，庞德被斩，魏兵挫锐；倘彼率兵直至许都，如之奈何？孤欲迁都以避之。”司马懿谏曰：“不可。于禁等被水所淹，非战之故；于国家大计，本无所损。今孙、刘失好，云长得志，孙权必不喜；大王可遣使去东吴陈说利害，令孙权暗暗起兵蹑云长之后，许事平之日，割江南之地以封孙权，则樊城之危自解矣。”主簿蒋济曰：“仲达之言是也。今可即发使往东吴，不必迁都动众。”操依允，遂不迁都；因叹谓诸将曰：“于禁从孤三十年，何期临危反不如庞德也！今一面遣使致书东吴，一面必得一大将以当云长之锐。”言未毕，阶下一将应声而出曰：“某愿往。”操视之，乃徐晃也。操大喜，遂拨精兵五万，令徐晃为将，吕建副之，克日起兵，前到阳陵坡驻扎；看东南有应，然后征进。
却说孙权接得曹操书信，览毕，欣然应允，即修书发付使者先回，乃聚文武商议。张昭曰：“近闻云长擒于禁，斩庞德，威震华夏，操欲迁都以避其锋。今樊城危急，遣使求救，事定之后，恐有反覆。”权未及发言，忽报吕蒙：“乘小舟自陆口来，有事面禀。”权召入问之，蒙曰：“今云长提兵围樊城，可乘其远出，袭取荆州。”权曰：“孤欲北取徐州，如何？”蒙曰：“今操远在河北，未暇东顾，徐州守兵无多，往自可克；然其地势利于陆战，不利水战，纵然得之，亦难保守。不如先取荆州，全据长江，别作良图。”权曰：“孤本欲取荆州，前言特以试卿耳。卿可速为孤图之。孤当随后便起兵也。”
吕蒙辞了孙权，回至陆口，早有哨马报说：“沿江上下，或二十里，或三十里，高阜处各有烽火台。”又闻荆州军马整肃，预有准备，蒙大惊曰：“若如此，急难图也。我一时在吴侯面前劝取荆州，今却如何处置？”寻思无计，乃托病不出，使人回报孙权。权闻吕蒙患病，心甚怏怏。陆逊进言曰：“吕子明之病，乃诈耳，非真病也。”权曰：“伯言既知其诈，可往视之。”陆逊领命，星夜至陆口寨中，来见吕蒙，果然面无病色。逊曰：“某奉吴侯命，敬探子明贵恙。”蒙曰：“贱躯偶病，何劳探问。”逊曰：“吴侯以重任付公，公不乘时而动，空怀郁结，何也？”蒙目视陆逊，良久不语。逊又曰：“愚有小方，能治将军之疾，未审可用否？”蒙乃屏退左右而问曰：“伯言良方，乞早赐教。”逊笑曰：“子明之疾，不过因荆州兵马整肃，沿江有烽火台之备耳。予有一计，令沿江守吏，不能举火；荆州之兵，束手归降，可乎？”蒙惊谢曰：“伯言之语，如见我肺腑。愿闻良策。”陆逊曰：“云长倚恃英雄，自料无敌，所虑者惟将军耳。将军乘此机会，托疾辞职，以陆口之任让之他人，使他人卑辞赞美关公，以骄其心，彼必尽撤荆州之兵，以向樊城。若荆州无备，用一旅之师，别出奇计以袭之，则荆州在掌握之中矣。”蒙大喜曰：“真良策也！”
由是吕蒙托病不起，上书辞职。陆逊回见孙权，具言前计。孙权乃召吕蒙还建业养病。蒙至，入见权，权问曰：“陆口之任，昔周公谨荐鲁子敬以自代，后子敬又荐卿自代，今卿亦须荐一才望兼隆者，代卿为妙。”蒙曰：“若用望重之人，云长必然提备。陆逊意思深长，而未有远名，非云长所忌；若即用以代臣之任，必有所济。”权大喜，即日拜陆逊为偏将军、右都督，代蒙守陆口。逊谢曰：“某年幼无学，恐不堪重任。”权曰：“子明保卿，必不差错。卿毋得推辞。”逊乃拜受印绶，连夜往陆口；交割马步水三军已毕，即修书一封，具名马、异锦、酒礼等物，遣使赍赴樊城见关公。
时公正将息箭疮，按兵不动。忽报：“江东陆口守将吕蒙病危，孙权取回调理，近拜陆逊为将，代吕蒙守陆口。今逊差人赍书具礼，特来拜见。”关公召入，指来使而言曰：“仲谋见识短浅，用此孺子为将！”来使伏地告曰：“陆将军呈书备礼：一来与君侯作贺，二来求两家和好。幸乞笑留。”公拆书视之，书词极其卑谨。关公览毕，仰面大笑，令左右收了礼物，发付使者回去。使者回见陆逊曰：“关公欣喜，无复有忧江东之意。”
逊大喜，密遣人探得关公果然撤荆州大半兵赴樊城听调，只待箭疮痊可，便欲进兵。逊察知备细，即差人星夜报知孙权，孙权召吕蒙商议曰：“今云长果撤荆州之兵，攻取樊城，便可设计袭取荆州。卿与吾弟孙皎同引大军前去，何如？”孙皎字叔明，乃孙权叔父孙静之次子也。蒙曰：“主公若以蒙可用则独用蒙；若以叔明可用则独用叔明。岂不闻昔日周瑜、程普为左右都督，事虽决于瑜，然普自以旧臣而居瑜下，颇不相睦；后因见瑜之才，方始敬服？今蒙之才不及瑜，而叔明之亲胜于普，恐未必能相济也。”
权大悟，遂拜吕蒙为大都督，总制江东诸路军马；令孙皎在后接应粮草。蒙拜谢，点兵三万，快船八十余只，选会水者扮作商人，皆穿白衣，在船上摇橹，却将精兵伏于？冓？鹿船中。次调韩当、蒋钦、朱然、潘璋、周泰、徐盛、丁奉等七员大将，相继而进。其余皆随吴侯为合后救应。一面遣使致书曹操，令进兵以袭云长之后；一面先传报陆逊，然后发白衣人，驾快船往浔阳江去。昼夜趱行，直抵北岸。江边烽火台上守台军盘问时，吴人答曰：“我等皆是客商，因江中阻风，到此一避。”随将财物送与守台军士。军士信之，遂任其停泊江边。约至二更，？冓？鹿中精兵齐出，将烽火台上官军缚倒，暗号一声，八十余船精兵俱起，将紧要去处墩台之军，尽行捉入船中，不曾走了一个。于是长驱大进，径取荆州，无人知觉。将至荆州，吕蒙将沿江墩台所获官军，用好言抚慰，各各重赏，令赚开城门，纵火为号。众军领命，吕蒙便教前导。比及半夜，到城下叫门。门吏认得是荆州之兵，开了城门。众军一声喊起，就城门里放起号火。吴兵齐入，袭了荆州。吕蒙便传令军中：“如有妄杀一人，妄取民间一物者，定按军法。”原任官吏，并依旧职。将关公家属另养别宅，不许闲人搅扰。一面遣人申报孙权。
一日大雨，蒙上马引数骑点看四门。忽见一人取民间箬笠以盖铠甲，蒙喝左右执下问之，乃蒙之乡人也。蒙曰：“汝虽系我同乡，但吾号令已出，汝故犯之，当按军法。”其人泣告曰：“其恐雨湿官铠，故取遮盖，非为私用。乞将军念同乡之情！”蒙曰：“吾固知汝为覆官铠，然终是不应取民间之物。”叱左右推下斩之。枭首传示毕，然后收其尸首，泣而葬之。自是三军震肃。不一日，孙权领众至。吕蒙出郭迎接入衙。权慰劳毕，仍命潘濬为治中，掌荆州事；监内放出于禁，遣归曹操；安民赏军，设宴庆贺。权谓吕蒙曰：“今荆州已得，但公安傅士仁、南郡糜芳，此二处如何收复？”言未毕，忽一人出曰：“不须张弓只箭，某凭三寸不烂之舌，说公安傅士仁来降，可乎？”众视之，乃虞翻也。权曰：“仲翔有何良策，可使傅士仁归降？”翻曰：“某自幼与士仁交厚；今若以利害说之，彼必归矣。”权大喜，遂令虞翻领五百军，径奔公安来。
却说傅士仁听知荆州有失，急令闭城坚守。虞翻至，见城门紧闭，遂写书拴于箭上，射入城中。军士拾得，献与傅士仁。士仁拆书视之，乃招降之意。览毕，想起“关公去日恨吾之意，不如早降。”即令大开城门，请虞翻入城。二人礼毕，各诉旧情。翻说吴侯宽洪大度，礼贤下土；士仁大喜，即同虞翻赍印绶来荆州投降。孙权大悦，仍令去守公安。吕蒙密谓权曰：“今云长未获，留士仁于公安，久必有变；不若使往南郡招糜芳归降。”权乃召傅士仁谓曰：“糜芳与卿交厚，卿可招来归降，孤自当有重赏。”傅士仁慨然领诺，遂引十余骑，径投南郡招安糜芳。正是：今日公安无守志，从前王甫是良言。
未知此去如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943862, '5b9b6f1cfb4ffe005cafeb43', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639214, '三国演义 · 第七十六回 · 徐公明大战沔水 关云长败走麦城', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说糜芳闻荆州有失，正无计可施。忽报公安守将傅士仁至，芳忙接入城，问其事故。士仁曰：“吾非不忠。势危力困，不能支持，我今已降东吴。将军亦不如早降。”芳曰：“吾等受汉中王厚恩，安忍背之？“士仁曰：“关公去日，痛恨吾二人；倘一日得胜而回，必无轻恕。公细察之。”芳曰：“吾兄弟久事汉中王，岂可一朝相背？”正犹豫间，忽报关公遣使至，接入厅上。使者曰：“关公军中缺粮，特来南郡、公安二处取白米十万石，令二将军星夜解去军前交割。如迟立斩。”芳大惊，顾谓傅士仁曰：“今荆州已被东吴所取，此粮怎得过去？”士仁厉声曰：“不必多疑！”遂拔剑斩来使于堂上。芳惊曰：“公如何斩之？”士仁曰：“关公此意，正要斩我二人。我等安可束手受死？公今不早降东吴，必被关公所杀。”正说间，忽报吕蒙引兵杀至城下。芳大惊，乃同傅士仁出城投降。蒙大喜，引见孙权。权重赏二人。安民已毕，大犒三军。
时曹操在许都，正与众谋士议荆州之事，忽报东吴遣使奉书至。操召人，使者呈上书信。操拆视之，书中具言吴兵将袭荆州，求操夹攻云长；且嘱：“勿泄漏，使云长有备也。”操与众谋士商议，主簿董昭曰：“今樊城被困，引颈望救，不如令人将书射入樊城，以宽军心；且使关公知东吴将袭荆州。彼恐荆州有失，必速退兵，却令徐晃乘势掩杀，可获全功。”操从其谋，一面差人催徐晃急战；一面亲统大兵，径往洛阳之南阳陵坡驻扎，以救曹仁。
却说徐晃正坐帐中，忽报魏王使至。晃接入问之，使曰：“今魏王引兵，已过洛阳；令将军急战关公，以解樊城之困。”正说间，探马报说：“关平屯兵在偃城，廖化屯兵在四冢：前后一十二个寨栅，连络不绝。”晃即差副将徐商、吕建假着徐晃旗号，前赴偃城与关平交战。晃却自引精兵五百，循沔水去袭偃城之后。且说关平闻徐晃自引兵至，遂提本部兵迎敌。两阵对圆，关平出马，与徐商交锋，只三合，商大败而走；吕建出战，五六合亦败走。平乘胜追杀二十余里，忽报城中火起。平知中计，急勒兵回救偃城。正遇一彪军摆开，徐晃立马在门旗下，高叫曰：“关平贤侄，好不知死！汝荆州已被东吴夺了，犹然在此狂为！”平大怒，纵马轮刀，直取徐晃；不三四合，三军喊叫，偃城中火光大起。平不敢恋战，杀条大路，径奔四冢寨来。廖化接着。化曰：“人言荆州已被吕蒙袭了，军心惊慌，如之奈何？”平曰：“此必讹言也。军士再言者斩之。”
忽流星马到，报说正北第一屯被徐晃领兵攻打。平曰：“若第一屯有失，诸营岂得安宁？此间皆靠沔水，贼兵不敢到此。吾与汝同去救第一屯。”廖化唤部将分付曰：“汝等坚守营寨，如有贼到，即便举火。”部将曰：“四冢寨鹿角十重，虽飞鸟亦不能入，何虑贼兵！”于是关平、廖化尽起四冢寨精兵，奔至第一屯住扎。关平看见魏兵屯于浅山之上，谓廖化曰：“徐晃屯兵，不得地利，今夜可引兵劫寨。”化曰：“将军可分兵一半前去，某当谨守本寨。”
是夜，关平引一枝兵杀入魏寨，不见一人。平知是计，火速退时，左边徐商，右边吕建，两下夹攻。平大败回营，魏兵乘势追杀前来，四面围住。关平、廖化支持不住，弃了第一屯，径投四冢寨来。早望见寨中火起。急到寨前，只见皆是魏兵旗号。关平等退兵，忙奔樊城大路而走。前面一军拦住，为首大将，乃是徐晃也。平、化二人奋力死战，夺路而走，回到大寨，来见关公曰：“今徐晃夺了偃城等处；又兼曹操自引大军，分三路来救樊城；多有人言荆州已被吕蒙袭了。”关公喝曰：“此敌人讹言，以乱我军心耳！东吴吕蒙病危，孺子陆逊代之，不足为虑！”
言未毕，忽报徐晃兵至。公令备马。平谏曰：“父体未痊，不可与敌。”公曰：“徐晃与吾有旧，深知其能；若彼不退，吾先斩之，以警魏将。”遂披挂提刀上马，奋然而出。魏军见之，无不惊惧。公勒马问曰：“徐公明安在？”魏营门旗开处，徐晃出马，欠身而言曰：“自别君侯，倏忽数载，不想君侯须发已苍白矣！忆昔壮年相从，多蒙教诲，感谢不忘。今君侯英风震于华夏，使故人闻之，不胜叹羡！兹幸得一见，深慰渴怀。”公曰：“吾与公明交契深厚，非比他人；今何故数穷吾儿耶？”晃回顾众将，厉声大叫曰：“若取得云长首级者，重赏千金！”公惊曰：“公明何出此言？”晃曰：“今日乃国家之事，某不敢以私废公。”言讫，挥大斧直取关公。公大怒，亦挥刀迎之。战八十余合，公虽武艺绝伦，终是右臂少力。关平恐公有失，火急鸣金，公拨马回寨。忽闻四下里喊声大震。原来是樊城曹仁闻曹操救兵至，引军杀出城来，与徐晃会合，两下夹攻，荆州兵大乱。关公上马，引众将急奔襄江上流头。背后魏兵追至。关公急渡过襄江，望襄阳而奔。忽流星马到，报说：“荆州已被吕蒙所夺，家眷被陷。”关公大惊。不敢奔襄阳，提兵投公安来。探马又报：“公安傅士仁已降东吴了。”关公大怒。忽催粮人到，报说：“公安傅士仁往南郡，杀了使命，招糜芳都降东吴去了。”
关公闻言，怒气冲塞，疮口迸裂，昏绝于地。众将救醒，公顾谓司马王甫曰：“悔不听足下之言，今日果有此事！”因问：“沿江上下，何不举火？”探马答曰：“吕蒙使水手尽穿白衣，扮作客商渡江，将精兵伏于？冓？鹿之中，先擒了守台士卒，因此不得举火。”公跌足叹曰：“吾中奸贼之谋矣！有何面目见兄长耶！”管粮都督赵累曰：“今事急矣，可一面差人往成都求救，一面从旱路去取荆州。”关公依言，差马良、伊籍赍文三道，星夜赴成都求救；一面引兵来取荆州，自领前队先行，留廖化、关平断后。却说樊城围解，曹仁引众将来见曹操，泣拜请罪。操曰：“此乃天数，非汝等之罪也。”操重赏三军，亲至四冢寨周围阅视，顾谓众将曰：“荆州兵围堑鹿角数重，徐公明深入其中，竟获全功。孤用兵三十余年，未敢长驱径入敌围。公明真胆识兼优者也！”众皆叹服。操班师还于摩陂驻扎。徐晃兵至，操亲出寨迎之，见晃军皆按队伍而行，并无差乱。操大喜曰：“徐将军真有周亚夫之风矣！”遂封徐晃为平南将军，同夏侯尚守襄阳，以遏关公之师。操因荆州未定，就屯兵于摩陂，以候消息。却说关公在荆州路上，进退无路，谓赵累曰：“目今前有吴兵，后有魏兵，吾在其中，救兵不至，如之奈何？”累曰：“昔吕蒙在陆口时，尝致书君侯，两家约好，共诛操贼，今却助操而袭我，是背盟也。君侯暂驻军于此，可差人遗书吕蒙责之，看彼如何对答。”关公从其言，遂修书遣使赴荆州来。
却说吕蒙在荆州，传下号令：凡荆州诸郡，有随关公出征将士之家，不许吴兵搅扰，按月给与粮米；有患病者，遣医治疗。将士之家，感其恩惠，安堵不动。忽报关公使至，吕蒙出郭迎接入城，以宾礼相待。使者呈书与蒙。蒙看毕，谓来使曰：“蒙昔日与关将军结好，乃一己之私见；今日之事，乃上命差遣，不得自主。烦使者回报将军，善言致意。”遂设宴款待，送归馆驿安歇。于是随征将士之家，皆来问信；有附家书者，有口传音信者，皆言家门无恙，衣食不缺。
使者辞别吕蒙，蒙亲送出城。使者回见关公，具道吕蒙之语，并说：“荆州城中，君侯宝眷并诸将家属，俱各无恙，供给不缺。”公大怒曰：“此奸贼之计也！我生不能杀此贼，死必杀之，以雪吾恨！”喝退使者。使者出寨，众将皆来探问家中之事；使者具言各家安好，吕蒙极其恩恤，并将书信传送各将。各将欣喜，皆无战心。
关公率兵取荆州，军行之次，将士多有逃回荆州者。关公愈加恨怒，遂催军前进。忽然喊声大震，一彪军拦住，为首大将，乃蒋钦也，勒马挺枪大叫曰：“云长何不早降！”关公骂曰：“吾乃汉将，岂降贼乎！”拍马舞刀，直取蒋钦。不三合，钦败走。关公提刀追杀二十余里，喊声忽起，左边山谷中韩当领军冲出，右边山谷中周泰引军冲出，蒋钦回马复战，三路夹攻。关公急撤军回走。行无数里，只见南山冈上人烟聚集，一面白旗招飐，上写“荆州土人”四字，众人都叫本处人速速投降。关公大怒，欲上冈杀之。山崦内又有两军撞出：左边丁奉，右边徐盛；并合蒋钦等三路军马，喊声震地，鼓角喧天，将关公困在垓心。手下将士，渐渐消疏。比及杀到黄昏，关公遥望四山之上，皆是荆州土兵，呼兄唤弟，觅子寻爷，喊声不住。军心尽变，皆应声而去。关公止喝不住，部从止有三百余人。杀至三更，正东上喊声连天，乃是关平、廖化分两路兵杀入重围，救出关公。关平告曰：“军心乱矣，必得城池暂屯，以待援兵。麦城虽小，足可屯扎。”关公从之，催促残军前至麦城，分兵紧守四门，聚将士商议。赵累曰：“此处相近上庸，现有刘封、孟达在彼把守，可速差人往求救兵。若得这枝军马接济，以待川兵大至，军心自安矣。”
正议间，忽报吴兵已至，将城四面围定。公问曰：“谁敢突围而出，往上庸求救？”廖化曰：“某愿往。”关平曰：“我护送汝出重围。”关公即修书付廖化藏于身畔。饱食上马，开门出城。正遇吴将丁奉截往。被关平奋力冲杀，奉败走，廖化乘势杀出重围。投上庸去了。关平入城，坚守不出。
且说刘封、孟达自取上庸，太守申耽率众归降，因此汉中王加刘封为副将军，与孟达同守上庸。当日探知关公兵败，二人正议间，忽报廖化至。
封令请人问之。化曰：“关公兵败，现困于麦城，被围至急。蜀中援兵，不能旦夕即至。特命某突围而出，来此求救。望二将军速起上庸之兵，以救此危。倘稍迟延，公必陷矣。”封曰：“将军且歇，容某计议。”
化乃至馆驿安歇，耑候发兵。刘封谓孟达曰：“叔父被困，如之奈何？”达曰：“东吴兵精将勇；且荆州九郡，俱已属彼，止有麦城，乃弹丸之地；又闻曹操亲督大军四五十万，屯于摩陂：量我等山城之众，安能敌得两家之强兵？不可轻敌。”封曰：“吾亦知之。奈关公是吾叔父，安忍坐视而不救乎？”达笑曰：“将军以关公为叔，恐关公未必以将军为侄也。某闻汉中王初嗣将军之时，关公即不悦。后汉中王登位之后，欲立后嗣，问于孔明，孔明曰：‘此家事也，问关、张可矣，’汉中王遂遣人至荆州问关公，关公以将军乃螟蛉之子，不可僭立，劝汉中王远置将军于上庸山城之地，以杜后患。此事人人知之，将军岂反不知耶？何今日犹沾沾以叔侄之义，而欲冒险轻动乎？”封曰：“君言虽是，但以何词却之？”达曰：“但言山城初附，民心未定，不敢造次兴兵，恐失所守。”封从其言。次日，请廖化至，言：“此山城初附之所，未能分兵相救。”化大惊，以头叩地曰：“若如此，则关公休矣！”达曰：“我今即往，一杯之水，安能救一车薪之火乎？将军速回，静候蜀兵至可也。”化大恸告求，刘封、孟达皆拂袖而入。廖化知事不谐，寻思须告汉中王求救，遂上马大骂出城，望成都而去。
却说关公在麦城盼望上庸兵到，却不见动静；手下止有五六百人，多半带伤；城中无粮，甚是苦楚。忽报城下一人教休放箭，有话来见君侯。公令放入，问之，乃诸葛瑾也。礼毕茶罢，瑾曰：“今奉吴侯命，特来劝谕将军。自古道：“识时务者为俊杰，今将军所统汉上九郡，皆已属他人类；止有孤城一区，内无粮草，外无救兵，危在旦夕。将军何不从瑾之言，归顺吴侯，复镇荆襄，可以保全家眷。幸君侯熟思之。”关公正色而言曰：“吾乃解良一武夫，蒙吾主以手足相待，安肯背义投敌国乎？城若破，有死而已。玉可碎而不可改其白，竹可焚而不可毁其节，身虽殒，名可垂于竹帛也。汝勿多言，速请出城，吾欲与孙权决一死战！”瑾曰：“吴侯欲与君侯结秦、晋之好，同力破曹，共扶汉室，别无他意。君侯何执迷如是？”言未毕，关平拔剑而前，欲斩诸葛瑾。公止之曰：“彼弟孔明在蜀，佐汝伯父，今若杀彼，伤其兄弟之情也。”遂令左右逐出诸葛瑾。瑾满面羞惭，上马出城，回见吴侯曰：“关公心如铁石，不可说也。”孙权曰：“真忠臣也！似此如之奈何？’吕范曰：“某请卜其休咎。”权即令卜之。范揲蓍成象，乃“地水师卦”，更有玄武临应，主敌人远奔。权问吕蒙曰：“卦主敌人远奔，卿以何策擒之？”蒙笑曰：“卦象正合某之机也。关公虽有冲天之翼，飞不出吾罗网矣！”正是：龙游沟壑遭虾戏，凤入牢笼被鸟欺。
毕竟吕蒙之计若何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943863, '5b9b6fa39f54540039b873f8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639215, '三国演义 · 第七十七回 · 玉泉山关公显圣 洛阳城曹操感神', NULL, 2, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说孙权求计于吕蒙。蒙曰：“吾料关某兵少，必不从大路而逃，麦城正北有险峻小路，必从此路而去。可令朱然引精兵五千，伏于麦城之北二十里；彼军至，不可与敌，只可随后掩杀。彼军定无战心，必奔临沮。却令潘璋引精兵五百，伏于临沮山僻小路，关某可擒矣。今遣将士各门攻打，只空北门，待其出走。”权闻计，令吕范再卜之。卦成，范告曰：“此卦主敌人投西北而走，今夜亥时必然就擒。”权大喜，遂令朱然、潘璋领两枝精兵，各依军令埋伏去讫。
且说关公在麦城，计点马步军兵，止剩三百余人；粮草又尽。是夜，城外吴兵招唤各军姓名，越城而去者甚多。救兵又不见到。心中无计，谓王甫曰：“吾悔昔日不用公言！今日危急，将复何如？”甫哭告曰：“今日之事，虽子牙复生，亦无计可施也。”赵累曰：“上庸救兵不至，乃刘封、孟达按兵不动之故。何不弃此孤城，奔入西川，再整兵来，以图恢复？”公曰：“吾亦欲如此。”遂上城观之。见北门外敌军不多，因问本城居民：“此去往北，地势若何？”答曰：“此去皆是山僻小路，可通西川。”公曰：“今夜可走此路。。王甫谏曰：“小路有埋伏，可走大路。”公曰：“虽有埋伏，吾何惧哉！”即下令马步官军：严整装束，准备出城。甫哭曰：“君侯于路，小心保重！某与部卒百余人，死据此城；城虽破，身不降也！专望君侯速来救援！”公亦与泣别。遂留周仓与王甫同守麦城，关公自与关平、赵累引残卒二百余人，突出北门。关公横刀前进，行至初更以后，约走二十余里，只见山凹处，金鼓齐鸣，喊声大震，一彪军到，为首大将朱然，骤马挺枪叫曰：“云长休走！趁早投降，免得一死！”公大怒，拍马轮刀来战。朱然便走，公乘势追杀。一棒鼓响，四下伏兵皆起。公不敢战，望临沮小路而走，朱然率兵掩杀。关公所随之兵，渐渐稀少。走不得四五里，前面喊声又震，火光大起，潘璋骤马舞刀杀来。公大怒，轮刀相迎，只三合，潘璋败走。公不敢恋战，急望山路而走。背后关平赶来，报说赵累已死于乱军中。关公不胜悲惶，遂令关平断后，公自在前开路，随行止剩得十余人。行至决石，两下是山，山边皆芦苇败草，树木丛杂。时已五更将尽。正走之间，一声喊起，两下伏兵尽出，长钩套索，一齐并举，先把关公坐下马绊倒。关公翻身落马，被潘璋部将马忠所获。关平知父被擒，火速来救；背后潘璋、朱然率兵齐至，把关平四下围住。平孤身独战，力尽亦被执。至天明，孙权闻关公父子已被擒获，大喜，聚众将于帐中。
少时，马忠簇拥关公至前。权曰：“孤久慕将军盛德，欲结秦、晋之好，何相弃耶？公平昔自以为天下无敌，今日何由被吾所擒？将军今日还服孙权否？”关公厉声骂曰：“碧眼小儿，紫髯鼠辈！吾与刘皇叔桃园结义，誓扶汉室，岂与汝叛汉之贼为伍耶！我今误中奸计，有死而已，何必多言！”权回顾众官曰：“云长世之豪杰，孤深爱之。今欲以礼相待，劝使归降，何如？”主簿左咸曰：“不可。昔曹操得此人时，封侯赐爵，三日一小宴，五日一大宴，上马一提金，下马一提银：如此恩礼，毕竟留之不住，听其斩关杀将而去，致使今日反为所逼，几欲迁都以避其锋。今主公既已擒之，若不即除，恐贻后患。”孙权沉吟半晌，曰：“斯言是也。”遂命推出。于是关公父子皆遇害。时建安二十四年冬十二月也。关公亡年五十八岁。后人有诗叹曰：“汉末才无敌，云长独出群：神威能奋武，儒雅更知文。天日心如镜，《春秋》义薄云。昭然垂万古，不止冠三分。”又有诗曰：“人杰惟追古解良，士民争拜汉云长。桃园一日兄和弟，俎豆千秋帝与王。气挟风雷无匹敌，志垂日月有光芒。至今庙貌盈天下，古木寒鸦几夕阳。”
关公既殁，坐下赤兔马被马忠所获，献与孙权。权即赐马忠骑坐。其马数日不食草料而死。
却说王甫在麦城中，骨颤肉惊，乃问周仓曰：“昨夜梦见主公浑身血污，立于前；急问之，忽然惊觉。不知主何吉凶？”正说间，忽报吴兵在城下，将关公父子首级招安。王甫、周仓大惊，急登城视之，果关公父子首级也。王甫大叫一声，堕城而死。周仓自刎而亡。于是麦城亦属东吴。
却说关公一魂不散，荡荡悠悠，直至一处，乃荆门州当阳县一座山，名为玉泉山。山上有一老僧，法名普净，原是汜水关镇国寺中长老；后因云游天下，来到此处，见山明水秀，就此结草为庵，每日坐禅参道，身边只有一小行者，化饭度日。是夜月白风清，三更已后，普净正在庵中默坐，忽闻空中有人大呼曰：“还我头来！”普净仰面谛视，只见空中一人，骑赤兔马，提青龙刀，左有一白面将军、右有一黑脸虬髯之人相随，一齐按落云头，至玉泉山顶。普净认得是关公，遂以手中麈尾击其户曰：“云长安在？”关公英魂顿悟，即下马乘风落于庵前，叉手问曰：“吾师何人？愿求法号。”普净曰：“老僧普净，昔日汜水关前镇国寺中，曾与君侯相会，今日岂遂忘之耶？”公曰：“向蒙相救，铭感不忘。今某已遇祸而死，愿求清诲，指点迷途。”普净曰：“昔非今是，一切休论；后果前因，彼此不爽。今将军为吕蒙所害，大呼‘还我头来’，然则颜良、文丑，五关六将等众人之头，又将向谁索耶？“于是关公恍然大悟，稽首皈依而去。后往往于玉泉山显圣护民，乡人感其德，就于山顶上建庙，四时致祭。后人题一联于其庙云：“赤面秉赤心、骑赤兔追风，驰驱时、无忘赤帝，青灯观青史、仗青龙偃月，隐微处不愧青天。”
却说孙权既害了关公，遂尽收荆襄之地，赏犒三军，设宴大会诸将庆功；置吕蒙于上位，顾谓众将曰：“孤久不得荆州，今唾手而得，皆子明之功也。”蒙再三逊谢。权曰：“昔周郎雄略过人，破曹操于赤壁，不幸早夭，鲁子敬代之。子敬初见孤时，便及帝王大略，此一快也；曹操东下，诸人皆劝孤降，子敬独劝孤召公瑾逆而击之，此二快也；惟劝吾借荆州与刘备，是其一短。今子明设计定谋，立取荆州，胜子敬、周郎多矣！”于是亲酌酒赐吕蒙。吕蒙接酒欲饮，忽然掷杯于地，一手揪住孙权，厉声大骂曰：“碧眼小儿！紫髯鼠辈！还识我否？”众将大惊，急救时，蒙推倒孙权，大步前进，坐于孙权位上，两眉倒竖，双眼圆睁，大喝曰：“我自破黄巾以来，纵横天下三十余年，今被汝一旦以奸计图我，我生不能啖汝之肉，死当追吕贼之魂！我乃汉寿亭侯关云长也。”权大惊，慌忙率大小将士，皆下拜。只见吕蒙倒于地上，七窍流血而死。众将见之，无不恐惧。权将吕蒙尸首，具棺安葬，赠南郡太守、孱陵侯；命其子吕霸袭爵。孙权自此感关公之事，惊讶不已。
忽报张昭自建业而来。权召入问之。昭曰：“今主公损了关公父子，江东祸不远矣！此人与刘备桃园结义之时，誓同生死。今刘备已有两川之兵；更兼诸葛亮之谋，张、黄、马、赵之勇。备若知云长父子遇害，必起倾国之兵，奋力报仇，恐东吴难与敌也。”权闻之大惊，跌足曰：“孤失计较也！似此如之奈何？”昭曰：“主公勿忧。某有一计，令西蜀之兵不犯东吴，荆州如磐石之安。”权问何计。昭曰：“今曹操拥百万之众，虎视华夏，刘备急欲报仇，必与操约和。若二处连兵而来，东吴危矣。不如先遣人将关公首级，转送与曹操，明教刘备知是操之所使，必痛恨于操，西蜀之兵，不向吴而向魏矣。吾乃观其胜负，于中取事。此为上策。”
权从其言，随遣使者以木匣盛关公首级，星夜送与曹操。时操从摩陂班师回洛阳，闻东吴送关公首级至，喜曰：“云长已死，吾夜眠贴席矣。”阶下一人出曰：“此乃东吴移祸之计也。”操视之，乃主簿司马懿也。操问其故，懿曰：“昔刘、关、张三人桃园结义之时，誓同生死。今东吴害了关公，惧其复仇，故将首级献与大王，使刘备迁怒大王，不攻吴而攻魏，他却于中乘便而图事耳。”操曰：“仲达之言是也。孤以何策解之？”懿曰：“此事极易。大王可将关公首级，刻一香木之躯以配之，葬以大臣之礼；刘备知之，必深恨孙权，尽力南征。我却观其胜负！蜀胜则击吴，吴胜则击蜀。二处若得一处，那一处亦不久也。”操大喜，从其计，遂召吴使入。呈上木匣，操开匣视之，见关公面如平日。操笑曰：“云长公别来无恙！”言未讫，只见关公口开目动，须发皆张，操惊倒。众官急救，良久方醒，顾谓众官曰：“关将军真天神也！”吴使又将关公显圣附体、骂孙权追吕蒙之事告操。操愈加恐惧，遂设牲醴祭祀，刻沉香木为躯，以王侯之礼，葬于洛阳南门外，令大小官员送殡，操自拜祭，赠为荆王，差官守墓；即遣吴使回江东去讫。却说汉中王自东川回成都，法正奏曰：“王上先夫人去世；孙夫人又南归。未必再来。人伦之道，不可废也，必纳王妃，以襄内政。”汉中王从之，法正复奏曰：“吴懿有一妹，美而且贤。尝闻有相者，相此女后必大贵。先曾许刘焉之子刘瑁，瑁早夭。其女至今寡居，大王可纳之为妃。”汉中王曰：“刘瑁与我同宗，于理不可。”法正曰：“论其亲疏，何异晋文之与怀嬴乎？”汉中王乃依允，遂纳吴氏为王妃。后生二子：长刘永，字公寿；次刘理，字奉孝。
且说东西两川，民安国富，田禾大成。忽有人自荆州来，言东吴求婚于关公，关公力拒之。孔明曰：“荆州危矣！可使人替关公回。”正商议间，荆州捷报使命，络绎而至。不一日，关兴到，具言水淹七军之事。忽又报马到来，报说关公于江边多设墩台，提防甚密，万无一失。因此玄德放心。
忽一日，玄德自觉浑身肉颤，行坐不安；至夜，不能宁睡，起坐内室，秉烛看书，觉神思昏迷，伏几而卧；就室中起一阵冷风，灯灭复明，抬头见一人立于灯下。玄德问曰：“汝何人，夤夜至吾内室？”其人不答。玄德疑怪，自起视之，乃是关公，于灯影下往来躲避。玄德曰：“贤弟别来无恙！夜深至此，必有大故。吾与汝情同骨肉，因何回避？”关公泣告曰：“愿兄起兵，以雪弟恨！”言讫，冷风骤起，关公不见。玄德忽然惊觉，乃是一梦。时正三鼓。玄德大疑，急出前殿，使人请孔明来。孔明入见，玄德细言梦警。孔明曰：“此乃王上心思关公，故有此梦。何必多疑？”玄德再三疑虑，孔明以善言解之。孔明辞出，至中门外，迎见许靖。靖曰：“某才赴军师府下报一机密，听知军师入宫，特来至此。”孔明曰：“有何机密？”靖曰：“某适闻外人传说，东吴吕蒙已袭荆州，关公已遇害！故特来密报军师。”孔明曰：“吾夜观天象，见将星落于荆楚之地，已知云长必然被祸，但恐王上忧虑，故未敢言。”
二人正说之间，忽然殿内转出一人，扯住孔明衣袖而言曰：“如此凶信，公何瞒我！”孔明视之，乃玄德也。孔明、许靖奏曰：“适来所言，皆传闻之事，未足深信。愿王上宽怀，勿生忧虑。”玄德曰：“孤与云长，誓同生死；彼若有失，孤岂能独生耶！”孔明、许靖正劝解之间，忽近侍奏曰：“马良、伊籍至。”玄德急召入问之。二人具说荆州已失，关公兵败求救，呈上表章。未及拆观，侍臣又奏荆州廖化至。玄德急召入。化哭拜于地，细奏刘封、孟达不发救兵之事。玄德大惊曰：“若如此，吾弟休矣！”孔明曰：“刘封、孟达如此无礼，罪不容诛！王上宽心，亮亲提一旅之师，去救荆襄之急。”玄德泣曰：“云长有失，孤断不独生！孤来日自提一军去救云长！”遂一面差人赴阆中报知翼德，一面差人会集人马。
未及天明，一连数次，报说关公夜走临沮，为吴将所获，义不屈节，父子归神。玄德听罢，大叫一声，昏绝于地。正是：为念当年同誓死，忍教今日独捐生！
未知玄德性命如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943865, '5b9b6fbc9f54540039b87531', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639216, '三国演义 · 第七十八回 · 治风疾神医身死 传遗命奸雄数终', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说汉中王闻关公父子遇害，哭倒于地；众文武急救，半晌方醒，扶入内殿。孔明劝曰：“王上少忧。自古道‘死生有命’；关公平日刚而自矜，故今日有此祸。王上且宜保养尊体，徐图报仇。”玄德曰：“孤与关、张二弟桃园结义时，誓同生死。今云长已亡，孤岂能独享富贵乎！”言未已，只见关兴号恸而来。玄德见了，大叫一声，又哭绝于地。众官救醒。一日哭绝三五次，三日水浆不进，只是痛哭；泪湿衣襟，斑斑成血。孔明与众官再三劝解。玄德曰：“孤与东吴，誓不同日月也！”孔明曰：“闻东吴将关公首级献与曹操，操以王侯礼祭葬之。”玄德曰：“此何意也？”孔明曰：“此是东吴欲移祸于曹操，操知其谋，故以厚礼葬关公，令王上归怨于吴也。”玄德曰：“吾今即提兵问罪于吴，以雪吾恨！”孔明谏曰：“不可。方今吴欲令我伐魏，魏亦欲令我伐吴，各怀谲计，伺隙而乘。王上只宜按兵不动，且与关公发丧。待吴、魏不和，乘时而伐之，可也。”众官又再三劝谏，玄德方才进膳，传旨川中大小将士，尽皆挂孝。汉中王亲出南门招魂祭奠，号哭终日。
却说曹操在洛阳，自葬关公后，每夜合眼便见关公。操甚惊惧，问于众官。众官曰：“洛阳行宫旧殿多妖，可造新殿居之。”操曰：“吾欲起一殿，名建始殿。恨无良工。”贾诩曰：“洛阳良工有苏越者，最有巧思。”操召入，令画图像。苏越画成九间大殿，前后廊庑楼阁，呈与操。操视之曰：“汝画甚合孤意，但恐无栋梁之材。”苏越曰：“此去离城三十里，有一潭，名跃龙潭；前有一祠，名跃龙祠。祠傍有一株大梨树，高十余丈，堪作建始殿之梁。”
操大喜，即令人工到彼砍伐。次日，回报此树锯解不开，斧砍不入，不能斩伐。操不信，自领数百骑，直至跃龙祠前下马，仰观那树，亭亭如华盖，直侵云汉，并无曲节。操命砍之，乡老数人前来谏曰：“此树已数百年矣，常有神人居其上，恐未可伐。”操大怒曰：“吾平生游历，普天之下，四十余年，上至天子，下及庶人，无不惧孤；是何妖神，敢违孤意！”言讫，拔所佩剑亲自砍之，铮然有声，血溅满身。操愕然大惊，掷剑上马，回至宫内。是夜二更，操睡卧不安，坐于殿中，隐几而寐。忽见一人披发仗剑，身穿皂衣，直至面前，指操喝曰：“吾乃梨树之神也。汝盖建始殿，意欲篡逆，却来伐吾神木！吾知汝数尽，特来杀汝！”操大惊，急呼：“武士安在？”皂衣人仗剑砍操。操大叫一声，忽然惊觉，头脑疼痛不可忍。急传旨遍求良医治疗，不能痊可。众官皆忧。
华歆入奏曰：“大王知有神医华佗否？”操曰：“即江东医周泰者乎？”歆曰：“是也。”操曰：“虽闻其名，未知其术。”歆曰：“华佗字元化，沛国谯郡人也。其医术之妙，世所罕有。但有患者，或用药，或用针，或用灸，随手而愈。若患五脏六腑之疾，药不能效者，以麻肺汤饮之，令病者如醉死，却用尖刀剖开其腹，以药汤洗其脏腑，病人略无疼痛。洗毕，然后以药线缝口，用药敷之；或一月，或二十日，即平复矣：其神妙如此！一日，佗行于道上，闻一人呻吟之声。佗曰：此饮食不下之病。问之果然。佗令取蒜齑汁三升饮之，吐蛇一条，长二三尺，饮食即下。广陵太守陈登，心中烦懑，面赤，不能饮食，求佗医治。佗以药饮之，吐虫三升，皆赤头，首尾动摇。登问其故，佗曰：此因多食鱼腥，故有此毒。今日虽可，三年之后，必将复发，不可救也。后陈登果三年而死。又有一人眉间生一瘤，痒不可当，令佗视之。佗曰：内有飞物。人皆笑之。佗以刀割开，一黄雀飞去，病者即愈。有一人被犬咬足指，随长肉二块，一痛一痒，俱不可忍。佗曰：痛者内有针十个，痒者内有黑白棋子二枚。人皆不信。佗以刀割开，果应其言。此人真扁鹊，仓公之流也！现居金城，离此不远，大王何不召之？”
操即差人星夜请华佗入内，令诊脉视疾。佗曰：“大王头脑疼痛，因患风而起。病根在脑袋中，风涎不能出，枉服汤药，不可治疗。某有一法：先饮麻肺汤，然后用利斧砍开脑袋，取出风涎，方可除根。”操大怒曰：“汝要杀孤耶！”佗曰：“大王曾闻关公中毒箭，伤其右臂，某刮骨疗毒，关公略无惧色；今大王小可之疾，何多疑焉？”操曰：“臂痛可刮，脑袋安可砍开？汝必与关公情熟，乘此机会，欲报仇耳！”呼左右拿下狱中，拷问其情。贾诩谏曰：“似此良医，世罕其匹，未可废也。”操叱曰：“此人欲乘机害我，正与吉平无异！”急令追拷。华佗在狱，有一狱卒，姓吴，人皆称为“吴押狱”。此人每日以酒食供奉华佗。佗感其恩，乃告曰：“我今将死，恨有《青囊书》未传于世。感公厚意，无可为报；我修一书，公可遣人送与我家，取《青囊书》来赠公，以继吾术。”吴押狱大喜曰：“我若得此书，弃了此役，医治天下病人，以传先生之德。”佗即修书付吴押狱。吴押狱直至金城，问佗之妻取了《青囊书》；回至狱中，付与华佗检看毕，佗即将书赠与吴押狱。吴押狱持回家中藏之。旬日之后，华佗竟死于狱中。吴押狱买棺殡殓讫，脱了差役回家，欲取《青囊书》看习，只见其妻正将书在那里焚烧。吴押狱大惊，连忙抢夺，全卷已被烧毁，只剩得一两叶。吴押狱怒骂其妻。妻曰：“纵然学得与华佗一般神妙，只落得死于牢中，要他何用！”吴押狱嗟叹而止。因此《青囊书》不曾传于世，所传者止阉鸡猪等小法，乃烧剩一两叶中所载也。后人有诗叹曰：“华佗仙术比长桑，神识如窥垣一方。惆怅人亡书亦绝，后人无复见《青囊》！”
却说曹操自杀华佗之后，病势愈重，又忧吴、蜀之事。正虑间，近臣忽奏东吴遣使上书。操取书拆视之，略曰：“臣孙权久知天命已归王上，伏望早正大位，遣将剿灭刘备，扫平两川，臣即率群下纳土归降矣。”操观毕大笑，出示群臣曰：“是儿欲使吾居炉火上耶！”侍中陈群等奏曰：“汉室久已衰微，殿下功德巍巍，生灵仰望。今孙权称臣归命，此天人之应，异气齐声。殿下宜应天顺人，早正大位。”操笑曰：“吾事汉多年，虽有功德及民，然位至于王，名爵已极，何敢更有他望？苟天命在孤，孤为周文王矣。”司马懿曰：“今孙权既称臣归附，王上可封官赐爵，令拒刘备。”操从之，表封孙权为骠骑将军、南昌侯，领荆州牧。即日遣使赍诰敕赴东吴去讫。
操病势转加。忽一夜梦三马同槽而食，及晓，问贾诩曰：“孤向日曾梦三马同槽，疑是马腾父子为祸；今腾已死，昨宵复梦三马同槽。主何吉凶？”诩曰：“禄马，吉兆也。禄马归于曹，王上何必疑乎？”操因此不疑。后人有诗曰：“三马同槽事可疑，不知已植晋根基。曹瞒空有奸雄略，岂识朝中司马师？”是夜，操卧寝室，至三更，觉头目昏眩，乃起，伏几而卧。忽闻殿中声如裂帛，操惊视之，忽见伏皇后、董贵人、二皇子，并伏完、董承等二十余人，浑身血污，立于愁云之内，隐隐闻索命之声。操急拔剑望空砍去，忽然一声响亮，震塌殿宇西南一角。操惊倒于地，近侍救出，迁于别宫养病。次夜，又闻殿外男女哭声不绝。至晓，操召群臣入曰：“孤在戎马之中，三十余年，未尝信怪异之事。今日为何如此？”群臣奏曰：“大王当命道士设醮修禳。”操叹曰：“圣人云：获罪于天，无所祷也。孤天命已尽，安可救乎？”遂不允设醮。
次日，觉气冲上焦，目不见物，急召夏侯惇商议。惇至殿门前，忽见伏皇后、董贵人、二皇子、伏完、董承等，立在阴云之中。惇大惊昏倒，左右扶出，自此得病。操召曹洪、陈群、贾诩、司马懿等，同至卧榻前，嘱以后事。曹洪等顿首曰：“大王善保玉体，不日定当霍然。”操曰：“孤纵横天下三十余年，群雄皆灭，止有江东孙权，西蜀刘备，未曾剿除。孤今病危，不能再与卿等相叙，特以家事相托。孤长子曹昂，刘氏所生，不幸早年殁于宛城；今卞氏生四子：丕、彰、植、熊。孤平生所爱第三子植，为人虚华少诚实，嗜酒放纵，因此不立。次子曹彰，勇而无谋；四子曹熊，多病难保。惟长子曹丕，笃厚恭谨，可继我业。卿等宜辅佐之。”曹洪等涕泣领命而出。操令近侍取平日所藏名香，分赐诸侍妾，且嘱曰：“吾死之后，汝等须勤习女工，多造丝履，卖之可以得钱自给。”又命诸妾多居于铜雀台中，每日设祭，必令女伎奏乐上食。又遗命于彰德府讲武城外，设立疑冢七十二：“勿令后人知吾葬处，恐为人所发掘故也。”嘱毕，长叹一声，泪如雨下。须臾，气绝而死。寿六十六岁。时建安二十五年春正月也。后人有《邺中歌》一篇，叹曹操云：“邺则邺城水漳水，定有异人从此起：雄谋韵事与文心，君臣兄弟而父子；英雄未有俗胸中，出没岂随人眼底？功首罪魁非两人，遗臭流芳本一身；文章有神霸有气，岂能苟尔化为群？横流筑台距太行，气与理势相低昂；安有斯人不作逆，小不为霸大不王？霸王降作儿女鸣，无可奈何中不平；向帐明知非有益，分香未可谓无情。呜呼！古人作事无巨细，寂寞豪华皆有意；书生轻议冢中人，冢中笑尔书生气！”却说曹操身亡，文武百官尽皆举哀；一面遣人赴世子曹丕、鄢陵侯曹彰、临淄侯曹植、萧怀侯曹熊处报丧。众官用金棺银椁将操入殓，星夜举灵榇赴邺郡来。曹丕闻知父丧，放声痛哭，率大小官员出城十里，伏道迎榇入城，停于偏殿。官僚挂孝，聚哭于殿上。忽一人挺身而出曰：“请世子息哀，且议大事。”众视之，乃中庶子司马孚也。孚曰：“魏王既薨，天下震动；当早立嗣王，以安众心。何但哭泣耶？”群臣曰：“世子宜嗣位，但未得天子诏命，岂可造次而行？”兵部尚书陈矫曰：“王薨于外，爱子私立，彼此生变，则社稷危矣。”遂拔剑割下袍袖，厉声曰：“即今日便请世子嗣位。众官有异议者，以此袍为例！”百官悚惧。
忽报华歆自许昌飞马而至，众皆大惊。须臾华歆入，众问其来意，歆曰：“今魏王薨逝，天下震动，何不早请世子嗣位？”众官曰：“正因不及候诏命，方议欲以王后卞氏慈旨立世子为王。”歆曰：“吾已于汉帝处索得诏命在此。”众皆踊跃称贺。歆于怀中取出诏命开读。原来华歆谄事魏，故草此诏，威逼献帝降之；帝只得听从，故下诏即封曹丕为魏王、丞相、冀州牧。丕即日登位，受大小官僚拜舞起居。
正宴会庆贺间，忽报鄢陵侯曹彰，自长安领十万大军来到。丕大惊，遂问群臣曰：“黄须小弟；平日性刚，深通武艺。今提兵远来，必与孤争王位也。如之奈何？”忽阶下一人应声出曰：“臣请往见鄢陵侯，以片言折之。”众皆曰：“非大夫莫能解此祸也。”正是：试看曹氏丕彰事，几作袁家谭尚争。
未知此人是谁，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943865, '5b9b6fd49f54540039b8762a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639217, '三国演义 · 第七十九回 · 兄逼弟曹植赋诗 侄陷叔刘封伏法', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说曹丕闻曹彰提兵而来，惊问众官；一人挺身而出，愿往折服之。众视其人，乃谏议大夫贾逵也。曹丕大喜，即命贾逵前往。逵领命出城，迎见曹彰。彰问曰：“先王玺绶安在？”逵正色而言曰：“家有长子，国有储君。先王玺绶，非君侯之所宜问也。”彰默然无语，乃与贾逵同入城。至宫门前，逵问曰：“君侯此来，欲奔丧耶？欲争位耶？”彰曰：“吾来奔丧，别无异心。”逵曰：“既无异心，何故带兵入城？”彰即时叱退左右将士，只身入内，拜见曹丕。兄弟二人，相抱大哭。曹彰将本部军马尽交与曹丕。丕令彰回鄢陵自守，彰拜辞而去。
于是曹丕安居王位，改建安二十五年为延康元年；封贾诩为太尉，华歆为相国，王朗为御史大夫；大小官僚，尽皆升赏。谥曹操曰武王，葬于邺郡高陵，令于禁董治陵事。禁奉命到彼，只见陵屋中白粉壁上，图画关云长水淹七军擒获于禁之事：画云长俨然上坐，庞德愤怒不屈，于禁拜伏于地，哀求乞命之状。原来曹丕以于禁兵败被擒，不能死节，既降敌而复归，心鄙其为人，故先令人图画陵屋粉壁，故意使之往见以愧之。当下于禁见此画像，又羞又恼，气愤成病，不久而死。后人有诗叹曰：“三十年来说旧交，可怜临难不忠曹。知人未向心中识，画虎今从骨里描。”
却说华歆奏曹丕曰：“鄢陵侯已交割军马，赴本国去了；临淄侯植、萧怀侯熊，二人竟不来奔丧，理当问罪，丕从之，即分遣二使往二处问罪。不一日，萧怀使者回报：“萧怀侯曹熊惧罪，自缢身死。”丕令厚葬之，追赠萧怀王。又过了一日，临淄使者回报，说：“临淄侯日与丁仪、丁廙兄弟二人酣饮，悖慢无礼，闻使命至，临淄侯端坐不动；丁仪骂曰：昔者先王本欲立吾主为世子，被谗臣所阻；今王丧未远，便问罪于骨肉，何也？丁廙又曰：据吾主聪明冠世，自当承嗣大位，今反不得立。汝那庙堂之臣，何不识人才若此！临淄侯因怒，叱武士将臣乱棒打出。”
丕闻之，大怒，即令许褚领虎卫军三千，火速至临淄擒曹植等一千人来。褚奉命，引军至临淄城。守将拦阻，褚立斩之，直入城中，无一人敢当锋锐，径到府堂。只见曹植与丁仪、丁廙等尽皆醉倒。褚皆缚之，载于车上，并将府下大小属官，尽行拿解邺郡，听候曹丕发落。丕下令，先将丁仪、丁廙等尽行诛戳。丁仪字正礼，丁廙字敬礼，沛郡人，乃一时文士；及其被杀，人多惜之。
却说曹丕之母卞氏，听得曹熊缢死，心甚悲伤；忽又闻曹植被擒，其党丁仪等已杀，大惊。急出殿，召曹丕相见。丕见母出殿，慌来拜谒。卞氏哭谓丕曰：“汝弟植平生嗜酒疏狂，盖因自恃胸中之才，故尔放纵。汝可念同胞之情，存其性命。吾至九泉亦瞑目也。”丕曰：“儿亦深爱其才，安肯害他？今正欲戒其性耳。母亲勿忧。”
卞氏洒泪而入，丕出偏殿，召曹植入见。华歆问曰：“适来莫非太后劝殿下勿杀子建乎？”丕曰：“然。”歆曰：“子建怀才抱智，终非池中物；若不早除，必为后患。”丕曰：“母命不可违。”歆曰：“人皆言子建出口成章，臣未深信。主上可召入，以才试之。若不能，即杀之；若果能，则贬之，以绝天下文人之口。”丕从之。须臾，曹植入见，惶恐伏拜请罪。丕曰：“吾与汝情虽兄弟，义属君臣，汝安敢恃才蔑礼？昔先君在日，汝常以文章夸示于人，吾深疑汝必用他人代笔。吾今限汝行七步吟诗一首。若果能，则免一死；若不能，则从重治罪，决不姑恕！”植曰：“愿乞题目。”时殿上悬一水墨画，画着两只牛，斗于土墙之下，一牛坠井而亡。丕指画曰：“即以此画为题。诗中不许犯着‘二牛斗墙下，一牛坠井死’字样。”植行七步，其诗已成。诗曰：“两肉齐道行，头上带凹骨。相遇块山下，郯起相搪突。二敌不俱刚，一肉卧土窟。非是力不如，盛气不泄毕。”曹丕及群臣皆惊。丕又曰：“七步成章，吾犹以为迟。汝能应声而作诗一首否？”植曰：“愿即命题。”丕曰：“吾与汝乃兄弟也。以此为题。亦不许犯着‘兄弟’字样。”植略不思索，即口占一首曰：“煮豆燃豆萁，豆在釜中泣，本是同根生，相煎何太急！”曹丕闻之，潸然泪下。其母卞氏，从殿后出曰：“兄何逼弟之甚耶？”丕慌忙离坐告曰：“国法不可废耳。”于是贬曹植为安乡侯。植拜辞上马而去。
曹丕自继位之后，法令一新，威逼汉帝，甚于其父。早有细作报入成都。汉中王闻之，大惊，即与文武商议曰：“曹操已死，曹丕继位，威逼天子，更甚于操。东吴孙权，拱手称臣。孤欲先伐东吴，以报云长之仇；次讨中原，以除乱贼。”言未毕，廖化出班，哭拜于地曰：“关公父子遇害，实刘封、孟达之罪。乞诛此二贼。”玄德便欲遣人擒之。孔明谏曰：“不可。且宜缓图之，急则生变矣。可升此二人为郡守，分调开去，然后可擒。”玄德从之，遂遣使升刘封去守绵竹。
原来彭羕与孟达甚厚，听知此事，急回家作书，遣心腹人驰报孟达。使者方出南门外，被马超巡视军捉获，解见马超。超审知此事，即往见彭羕。羕接入，置酒相待。酒至数巡，超以言挑之曰：“昔汉中王待公甚厚，今何渐薄也？”羕因酒醉，恨骂曰：“老革荒悖，吾必有以报之！”超又探曰：“某亦怀怨心久矣。”羕曰：“公起本部军，结连孟达为外合，某领川兵为内应，大事可图也。”超曰：“先生之言甚当。来日再议。”
超辞了彭羕，即将人与书解见汉中王，细言其事。玄德大怒，即令擒彭羕下狱，拷问其情。羕在狱中，悔之无及。玄德问孔明曰：“彭羕有谋反之意，当何以治之？”孔明曰：“羕虽狂士，然留之久必生祸。”于是玄德赐彭羕死于狱。
羕既死，有人报知孟达。达大惊，举止失措。忽使命至，调刘封回守绵竹去讫。孟达慌请上庸、房陵都尉申耽、申仪弟兄二人商议曰：“我与法孝直同有功于汉中王；今孝直已死，而汉中王忘我前功，乃欲见害，为之奈何？“耽曰：“某有一计，使汉中王不能加害于公。”达大喜，急问何计。耽曰：“吾弟兄欲投魏久矣，公可作一表，辞了汉中王，投魏王曹丕，丕必重用。吾二人亦随后来降也。”达猛然省悟，即写表一通，付与来使；当晚引五十余骑投魏去了。
使命持表回成都，奏汉中王，言孟达投魏之事。先主大怒。览其表曰：“臣达伏惟殿下：将建伊、吕之业，追桓、文之功，大事草创，假势吴、楚，是以有为之士，望风归顺。臣委质以来，愆戾山积；臣犹自知，况于君乎？今王朝英俊鳞集，臣内无辅佐之器，外无将领之才，列次功臣，诚足自愧！臣闻范蠡识微，浮于五湖；舅犯谢罪，逡巡河上。夫际会之间，请命乞身，何哉？欲洁去就之分也。况臣卑鄙，无元功巨勋，自系于时，窃慕前贤，早思远耻。昔申生至孝，见疑于亲；子胥至忠，见诛于君；蒙恬拓境而被大刑，乐毅破齐而遭谗佞。臣每读其书，未尝不感慨流涕；而亲当其事，益用伤悼！迩者，荆州覆败，大臣失节，百无一还；惟臣寻事，自致房陵、上庸，而复乞身，自放于外。伏想殿下圣恩感悟，愍臣之心，悼臣之举。臣诚小人，不能始终。知而为之，敢谓非罪？臣每闻“交绝无恶声，去臣无怨辞”。臣过奉教于君子，愿君王勉之，臣不胜惶恐之至！”玄德看毕，大怒曰：“匹夫叛吾，安敢以文辞相戏耶！”即欲起兵擒之。孔明曰：“可就遣刘封进兵，令二虎相并；刘封或有功，或败绩，必归成都，就而除之，可绝两害。玄德从之，遂遣使到绵竹，传谕刘封。封受命，率兵来擒孟达。却说曹丕正聚文武议事，忽近臣奏曰：“蜀将孟达来降。”丕召入问曰：“汝此来，莫非诈降乎？”达曰：“臣为不救关公之危，汉中王欲杀臣，因此惧罪来降，别无他意。”曹丕尚未准信，忽报刘封引五万兵来取襄阳，单搦孟达厮杀。丕曰：“汝既是真心，便可去襄阳取刘封首级来，孤方准信。”达曰：“臣以利害说之，不必动兵，令刘封亦来降也。”丕大喜，遂加孟达为散骑常侍、建武将军、平阳亭侯，领新城太守，去守襄阳、樊城。原来夏侯尚、徐晃已先在襄阳，正将收取上庸诸部。孟达到了襄阳，与二将礼毕，探得刘封离城五十里下寨。达即修书一封，使人赍赴蜀寨招降刘封。刘封览书大怒曰：“此贼误吾叔侄之义，又间吾父子之亲，使吾为不忠不孝之人也！”遂扯碎来书，斩其使，次日，引军前来搦战。
孟达知刘封扯书斩使，勃然大怒，亦领兵出迎。两阵对圆，封立马于门旗下。以刀指骂曰：“背国反贼，安敢乱言！”孟达曰：“汝死已临头上，还自执迷不省！”封大怒，拍马轮刀，直奔孟达。战不三合，达败走，封乘虚追杀二十余里，一声喊起，伏兵尽出，左边夏侯尚杀来，右边徐晃杀来，孟达回身复战。三军夹攻，刘封大败而走，连夜奔回上庸，背后魏兵赶来。刘封到城下叫门，城上乱箭射下。申耽在敌楼上叫曰：“吾已降了魏也！”封大怒，欲要攻城，背后追军将至，封立脚不住，只得望房陵而奔，见城上已尽插魏旗。申仪在敌楼上将旗一飐，城后一彪军出，旗上大书“右将军徐晃”。封抵敌不住，急望西川而走。晃乘势追杀。刘封部下只剩得百余骑。到了成都，入见汉中王，哭拜于地，细奏前事。玄德怒曰：“辱子有何面目复来见吾！”封曰：“叔父之难，非儿不救，因孟达谏阻故耳。”玄德转怒曰：“汝须食人食、穿人衣，非土木偶人！安可听谗贼所阻！”命左右推出斩之。汉中王既斩刘封，后闻孟达招之，毁书斩使之事，心中颇悔；又哀痛关公，以致染病。因此按兵不动。
且说魏王曹丕，自即王位，将文武官僚，尽皆升赏；遂统甲兵三十万，南巡沛国谯县，大飨先茔。乡中父老，扬尘遮道，奉觞进酒，效汉高祖还沛之事。人报大将军夏侯惇病危，丕即还邺郡。时惇已卒，丕为挂孝，以厚礼殡葬。
是岁八月间，报称石邑县凤凰来仪，临淄城麒麟出现，黄龙现于邺郡。于是中郎将李伏、太史丞许芝商议：种种瑞征，乃魏当代汉之兆，可安排受禅之礼，令汉帝将天下让于魏王。遂同华歆、王朗、辛毗、贾诩、刘廙、刘晔、陈矫、陈群、桓阶等一班文武官僚，四十余人，直入内殿，来奏汉献帝，请禅位于魏王曹丕。正是：魏家社稷今将建，汉代江山忽已移。
未知献帝如何回答，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943868, '5b9b6feb67f356005c8df739', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639218, '三国演义 · 第八十回 · 曹丕废帝篡炎刘 汉王正位续大统', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说华歆等一班文武，入见献帝。歆奏曰：“伏睹魏王，自登位以来，德布四方，仁及万物，越古超今，虽唐、虞无以过此。群臣会议，言汉祚已终，望陛下效尧、舜之道，以山川社稷，禅与魏王，上合天心，下合民意，则陛下安享清闲之福，祖宗幸甚！生灵幸甚！臣等议定，特来奏请。”帝闻奏大惊，半晌无言，觑百官而哭曰：“朕想高祖提三尺剑，斩蛇起义，平秦灭楚，创造基业，世统相传，四百年矣。朕虽不才，初无过恶，安忍将祖宗大业，等闲弃了？汝百官再从公计议。”华歆引李伏、许芝近前奏曰：“陛下若不信，可问此二人。”李伏奏曰：“自魏王即位以来，麒麟降生，凤凰来仪，黄龙出现，嘉禾蔚生，甘露下降。此是上天示瑞，魏当代汉之象也。”许芝又奏曰：“臣等职掌司天，夜观乾象，见炎汉气数已终，陛下帝星隐匿不明；魏国乾象，极天际地，言之难尽。更兼上应图谶，其谶曰：鬼在边，委相连；当代汉，无可言。言在东，午在西；两日并光上下移。以此论之，陛下可早禅位。‘鬼在边，委相连’，是‘魏’字也；‘言在东，午在西’，乃‘许’字也；两日并光上下移，乃‘昌’字也：此是魏在许昌应受汉禅也。愿陛下察之。”帝曰：“祥瑞图谶，皆虚妄之事；奈何以虚妄之事，而遽欲朕舍祖宗之基业乎？”王朗奏曰：“自古以来，有兴必有废，有盛必有衰，岂有不亡之国、不败之家乎？汉室相传四百余年，延至陛下，气数已尽，宜早退避，不可迟疑；迟则生变矣。”帝大哭，入后殿去了。百官哂笑而退。
次日，官僚又集于大殿，令宦官入请献帝。帝忧惧不敢出。曹后曰：“百官请陛下设朝，陛下何故推阻？”帝泣曰：“汝兄欲篡位，令百官相逼，朕故不出。”曹后大怒曰：“吾兄奈何为此乱逆之事耶！”言未已，只见曹洪、曹休带剑而入，请帝出殿。曹后大骂曰：“俱是汝等乱贼，希图富贵，共造逆谋！吾父功盖寰区，威震天下，然且不敢篡窃神器。今吾兄嗣位未几，辄思篡汉，皇天必不祚尔！”言罢，痛哭入宫。左右侍者皆歔欷流涕。曹洪、曹休力请献帝出殿。帝被逼不过，只得更衣出前殿。华歆奏曰：“陛下可依臣等昨日之议，免遭大祸。”帝痛哭曰：“卿等皆食汉禄久矣；中间多有汉朝功臣子孙，何忍作此不臣之事？”歆曰：“陛下若不从众议，恐旦夕萧墙祸起。非臣等不忠于陛下也。”帝曰：“谁敢弑朕耶？”歆厉声曰：“天下之人，皆知陛下无人君之福，以致四方大乱！若非魏王在朝，弑陛下者，何止一人？陛下尚不知恩报德，直欲令天下人共伐陛下耶？”帝大惊，拂袖而起，王朗以目视华歆。歆纵步向前，扯住龙袍，变色而言曰：“许与不许，早发一言！”帝战栗不能答，曹洪、曹休拔剑大呼曰：“符宝郎何在？”祖弼应声出曰：“符宝郎在此！”曹洪索要玉玺。祖弼叱曰：“玉玺乃天子之宝，安得擅索！”洪喝令武士推出斩之。祖弼大骂不绝口而死。后人有诗赞曰：“奸宄专权汉室亡，诈称禅位效虞唐。满朝百辟皆尊魏，仅见忠臣符宝郎。”
帝颤栗不已。只见阶下披甲持戈数百余人，皆是魏兵。帝泣谓群臣曰：“朕愿将天下禅于魏王，幸留残喘，以终天年。”贾诩曰：“魏王必不负陛下。陛下可急降诏，以安众心。”帝只得令陈群草禅国之诏，令华歆赍捧诏玺，引百官直至魏王宫献纳。曹丕大喜。开读诏曰：“朕在位三十二年，遭天下荡覆，幸赖祖宗之灵，危而复存。然今仰瞻天象，俯察民心，炎精之数既终，行运在乎曹氏。是以前王既树神武之迹，今王又光耀明德，以应其期。历数昭明，信可知矣。夫大道之行，天下为公；唐尧不私于厥子，而名播于无穷，朕窃慕焉，今其追踵尧典，禅位于丞相魏王。王其毋辞！”
曹丕听毕，便欲受诏。司马懿谏曰：“不可。虽然诏玺已至，殿下宜且上表谦辞，以绝天下之谤。”丕从之，令王朗作表，自称德薄，请别求大贤以嗣天位。帝览表，心甚惊疑，谓群臣曰：“魏王谦逊，如之奈何？”华歆曰：“昔魏武王受王爵之时，三辞而诏不许，然后受之，今陛下可再降诏，魏王自当允从。”帝不得已，又令桓阶草诏，遣高庙使张音，持节奉玺至魏王宫。曹丕开读诏曰：“咨尔魏王，上书谦让。朕窃为汉道陵迟，为日已久；幸赖武王操，德膺符运，奋扬神武，芟除凶暴，清定区夏。今王丕缵承前绪，至德光昭，声教被四海，仁风扇八区；天之历数，实在尔躬。昔虞舜有大功二十，而放勋禅以天下；大禹有疏导之绩，而重华禅以帝位。汉承尧运，有传圣之义，加顺灵祇，绍天明命，使行御史大夫张音，持节奉皇帝玺绶。王其受之！”
曹丕接诏欣喜，谓贾诩曰：“虽二次有诏，然终恐天下后世，不免篡窃之名也。”诩曰：“此事极易，可再命张音赍回玺绶，却教华歆令汉帝筑一坛，名‘受禅坛’；择吉日良辰，集大小公卿，尽到坛下，令天子亲奉玺绶，禅天下与王，便可以释群疑而绝众议矣。”丕大喜，即令张音赍回玺绶，仍作表谦辞。音回奏献帝。帝问群臣曰：“魏王又让，其意若何？”华歆奏曰：“陛下可筑一坛，名曰‘受禅坛’，集公卿庶民，明白禅位；则陛下子子孙孙，必蒙魏恩矣。”帝从遣太常院官，卜地于繁阳，筑起三层高坛，择于十月庚午日寅时禅让。
至期，献帝请魏王曹丕登坛受禅，坛下集大小官僚四百余员，御林虎贲禁军三十余万，帝亲捧玉玺奉曹丕。丕受之。坛下群臣跪听册曰：“咨尔魏王！昔者唐尧禅位于虞舜，舜亦以命禹：天命不于常，惟归有德。汉道陵迟，世失其序；降及朕躬，大乱滋昏，群凶恣逆，宇内颠覆。赖武王神武，拯兹难于四方，惟清区夏，以保绥我宗庙；岂予一人获乂，俾九服实受其赐。今王钦承前绪，光于乃德；恢文武之大业，昭尔考之弘烈。皇灵降瑞，人神告徵；诞惟亮采，师锡朕命。佥曰：尔度克协于虞舜，用率我唐典，敬逊尔位。于戏！天之历数在尔躬，君其祗顺大礼，飨万国以肃承天命！”
读册已毕，魏王曹丕即受八般大礼，登了帝位。贾诩引大小官僚朝于坛下。改延康元年为黄初元年。国号大魏。丕即传旨，大赦天下。谥父曹操为太祖武皇帝，华歆奏曰：“‘天无二日，民无二主’。汉帝既禅天下，理宜退就藩服。乞降明旨，安置刘氏于何地？”言讫，扶献帝跪于坛下听旨。丕降旨封帝为山阳公，即日便行。华歆按剑指帝，厉声而言曰：“立一帝，废一帝，古之常道！今上仁慈，不忍加害，封汝为山阳公。今日便行，非宣召不许入朝！”献帝含泪拜谢，上马而去。坛下军民人等见之，伤感不已。丕谓群臣曰：“舜、禹之事，朕知之矣！”群臣皆呼“万岁”。后人观此受禅坛，有诗叹曰：“两汉经营事颇难，一朝失却旧江山。黄初欲学唐虞事，司马将来作样看。”百官请曹丕答谢天地。丕方下拜，忽然坛前卷起一阵怪风，飞砂走石，急如骤雨，对面不见；坛上火烛，尽皆吹灭。丕惊倒于坛上，百官急救下坛，半晌方醒。侍臣扶入宫中，数日不能设朝。后病稍可，方出殿受群臣朝贺。封华歆为司徒，王朗为司空；大小官僚，一一升赏。丕疾未痊，疑许昌宫室多妖，乃自许昌幸洛阳，大建宫室。
早有人到成都，报说曹丕自立为大魏皇帝，于洛阳盖造宫殿；且传言汉帝已遇害。汉中王闻知，痛哭终日，下令百官挂孝，遥望设祭，上尊谥曰“孝愍皇帝”。玄德因此忧虑，致染成疾，不能理事，政务皆托与孔明。
孔明与太傅许靖、光禄大夫谯周商议，言天下不可一日无君，欲尊汉中王为帝。谯周曰：“近有祥风庆云之瑞；成都西北角有黄气数十丈，冲霄而起；帝星见于毕、胃、昴之分，煌煌如月。此正应汉中王当即帝位，以继汉统，更复何疑？”于是孔明与许靖，引大小官僚上表，请汉中王即皇帝位。汉中王览表，大惊曰：“卿等欲陷孤为不忠不义之人耶？”孔明奏曰：“非也。曹丕篡汉自立，王上乃汉室苗裔，理合继统以延汉祀。”汉中王勃然变色曰：“孤岂效逆贼所为！”拂袖而起，入于后宫。众官皆散。
三日后，孔明又引众官入朝，请汉中王出。众皆拜伏于前。许靖奏曰：“今汉天子已被曹丕所弑，王上不即帝位，兴师讨逆，不得为忠义也。今天下无不欲王上为君，为孝愍皇帝雪恨。若不从臣等所议，是失民望矣。”汉中王曰：“孤虽是景帝之孙，并未有德泽以布于民；今一旦自立为帝，与篡窃何异！”孔明苦劝数次，汉中王坚执不从。
孔明乃设一计，谓众官曰：如此如此。于是孔明托病不出。汉中王闻孔明病笃，亲到府中，直入卧榻边，问曰：“军师所感何疾？”孔明答曰：“忧心如焚，命不久矣！”汉中王曰：“军师所忧何事？”连问数次，孔明只推病重，瞑目不答。汉中王再三请问。孔明喟然叹曰：“臣自出茅庐，得遇大王，相随至今，言听计从；今幸大王有两川之地，不负臣夙昔之言。目今曹丕篡位，汉祀将斩，文武官僚，咸欲奉大王为帝，灭魏兴刘，共图功名；不想大王坚执不肯，众官皆有怨心，不久必尽散矣。若文武皆散，吴、魏来攻，两川难保。臣安得不忧乎？”汉中王曰：“吾非推阻，恐天下人议论耳。”孔明曰：“圣人云：名不正则，言不顺，今大王名正言顺，有何可议？岂不闻天与弗取，反受其咎？”汉中王曰：“待军师病可，行之未迟。”孔明听罢，从榻上跃然而起，将屏风一击，外面文武众官皆入，拜伏于地曰：“王上既允，便请择日以行大礼。”汉中王视之，乃是太傅许靖、安汉将军糜竺、青衣侯向举、阳泉侯刘豹、别驾赵祚、治中杨洪、议曹杜琼、从事张爽、太常卿赖恭、光禄卿黄权、祭酒何宗、学士尹默、司业谯周、大司马殷纯、偏将军张裔、少府王谋、昭文博士伊籍、从事郎秦宓等众也。
汉中王惊曰：“陷孤于不义，皆卿等也！”孔明曰：“王上既允所请，便可筑坛择吉，恭行大礼。”即时送汉中王还宫，一面令博士许慈、谏议郎孟光掌礼，筑坛于成都武担之南。诸事齐备，多官整设銮驾，迎请汉中王登坛致祭。谯周在坛上，高声朗读祭文曰：“惟建安二十六年四月丙午朔，越十二日丁巳，皇帝备，敢昭告于皇天后土：汉有天下，历数无疆。曩者，王莽篡盗，光武皇帝震怒致诛，社稷复存。今曹操阻兵残忍，戮杀主后，罪恶滔天；操子丕，载肆凶逆，窃据神器。群下将士，以为汉祀堕废，备宜延之，嗣武二祖，躬行天罚。备惧无德忝帝位，询于庶民，外及遐荒君长，佥曰：天命不可以不答，祖业不可以久替，四海不可以无主。率土式望，在备一人。备畏天明命，又惧高、光之业，将坠于地，谨择吉日，登坛告祭，受皇帝玺绶，抚临四方。惟神飨祚汉家，永绥历服！”读罢祭文，孔明率众官恭上玉玺。汉中王受了，捧于坛上，再三推辞曰：“备无才德，请择有才德者受之。”孔明奏曰：“王上平定四海，功德昭于天下，况是大汉宗派，宜即正位。已祭告天神，复何让焉！”文武各官，皆呼“万岁”。拜舞礼毕，改元章武元年。立妃吴氏为皇后，长子刘禅为太子；封次子刘永为鲁王，三子刘理为梁王；封诸葛亮为丞相，许靖为司徒；大小官僚，一一升赏。大赦天下。两川军民，无不欣跃。次日设朝，文武官僚拜毕，列为两班。先主降诏曰：“朕自桃园与关、张结义，誓同生死。不幸二弟云长，被东吴孙权所害；若不报仇，是负盟也。朕欲起倾国之兵，剪伐东吴，生擒逆贼，以雪此恨！”言未毕，班内一人，拜伏于阶下，谏曰：“不可。”先主视之，乃虎威将军赵云也。正是：君王未及行天讨，臣下曾闻进直言。
未知子龙所谏若何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536944087, '5b9b70071579a3003a4fa85f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639219, '三国演义 · 第八十一回 · 急兄仇张飞遇害 雪弟恨先主兴兵', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说先主欲起兵东征，赵云谏曰：“国贼乃曹操，非孙权也。今曹丕篡汉，神人共怒。陛下可早图关中，屯兵渭河上流，以讨凶逆，则关东义士，必裹粮策马以迎王师；若舍魏以伐吴，兵势一交，岂能骤解。愿陛下察之。”先主曰：“孙权害了朕弟；又兼傅士仁、糜芳、潘璋、马忠皆有切齿之仇：啖其肉而灭其族，方雪朕恨！卿何阻耶？”云曰：“汉贼之仇，公也；兄弟之仇，私也。愿以天下为重。”先主答曰：“朕不为弟报仇，虽有万里江山，何足为贵？”遂不听赵云之谏，下令起兵伐吴；且发使往五溪，借番兵五万，共相策应；一面差使往阆中，迁张飞为车骑将军，领司隶校尉，封西乡侯，兼阆中牧。使命赍诏而去。却说张飞在阆中，闻知关公被东吴所害，旦夕号泣，血湿衣襟。诸将以酒解劝，酒醉，怒气愈加。帐上帐下，但有犯者即鞭挞之；多有鞭死者。每日望南切齿睁目怒恨，放声痛哭不已。忽报使至，慌忙接入，开读诏旨。飞受爵望北拜毕，设酒款待来使。飞曰：“吾兄被害，仇深似海；庙堂之臣，何不早奏兴兵？”使者曰：“多有劝先灭魏而后伐吴者。”飞怒曰：“是何言也！昔我三人桃园结义，誓同生死；今不幸二兄半途而逝，吾安得独享富贵耶！吾当面见天子，愿为前部先锋，挂孝伐吴，生擒逆贼，祭告二兄，以践前盟！”言讫，就同使命望成都而来。却说先主每日自下教场操演军马，克日兴师，御驾亲征。于是公卿都至丞相府中见孔明，曰：“今天子初临大位，亲统军伍，非所以重社稷也。丞相秉钧衡之职，何不规谏？”孔明曰：“吾苦谏数次，只是不听。今日公等随我入教场谏去。”当下孔明引百官来奏先主曰：“陛下初登宝位，若欲北讨汉贼，以伸大义于天下，方可亲统六师；若只欲伐吴，命一上将统军伐之可也，何必亲劳圣驾？”先主见孔明苦谏，心中稍回。忽报张飞到来，先主急召入。飞至演武厅拜伏于地，抱先主足而哭。先主亦哭。飞曰：“陛下今日为君，早忘了桃园之誓！二兄之仇，如何不报？”先主曰：“多官谏阻，未敢轻举。”飞曰：“他人岂知昔日之盟？若陛下不去，臣舍此躯与二兄报仇！若不能报时，臣宁死不见陛下也！”先主曰：“朕与卿同往：卿提本部兵自阆州而出，朕统精兵会于江州，共伐东吴，以雪此恨！”飞临行，先主嘱曰：“朕素知卿酒后暴怒，鞭挞健儿，而复令在左右：此取祸之道也。今后务宜宽容，不可如前。”飞拜辞而去。次日，先主整兵要行。学士秦宓奏曰：“陛下舍万乘之躯，而徇小义，古人所不取也。愿陛下思之。”先主曰：“云长与朕，犹一体也。大义尚在，岂可忘耶？”宓伏地不起曰：“陛下不从臣言，诚恐有失。”先主大怒曰：“朕欲兴兵，尔何出此不利之言！”叱武士推出斩之，宓面不改色，回顾先主而笑曰：“臣死无恨，但可惜新创之业，又将颠覆耳！”众官皆为秦宓告免。先主曰：“暂且囚下，待朕报仇回时发落。”孔明闻知，即上表救秦宓。其略曰：“臣亮等切以吴贼逞奸诡之计，致荆州有覆亡之祸；陨将星于斗牛，折天柱于楚地：此情哀痛，诚不可忘。但念迁汉鼎者，罪由曹操；移刘祚者，过非孙权。窃谓魏贼若除，则吴自宾服。愿陛下纳秦宓金石之言，以养士卒之力，别作良图，则社稷幸甚！天下幸甚！”先主看毕，掷表于地曰：“朕意已决，无得再谏！”遂命丞相诸葛亮保太子守两川；骠骑将军马超并弟马岱，助镇北将军魏延守汉中，以当魏兵；虎威将军赵云为后应，兼督粮草；黄权、程畿为参谋；马良、陈震掌理文书；黄忠为前部先锋；冯习、张南为副将；傅彤、张翼为中军护尉；赵融、廖淳为合后。川将数百员，并五溪番将等，共兵七十五万，择定章武元年七月丙寅日出师。却说张飞回到阆中，下令军中；限三日内制办白旗白甲，三军挂孝伐吴。次日，帐下两员末将范疆、张达，入帐告曰：“白旗白甲，一时无措，须宽限方可。飞大怒曰：“吾急欲报仇，恨不明日便到逆贼之境，汝安敢违我将令！”叱武士缚于树上，各鞭背五十。鞭毕，以手指之曰：“来日俱要完备！若违了限，即杀汝二人示众！”打得二人满口出血。回到营中商议，范疆曰：“今日受了刑责，着我等如何办得？其人性暴如火，倘来日不完，你我皆被杀矣！”张达曰：“比如他杀我，不如我杀他。”疆曰：“怎奈不得近前。”达曰：“我两个若不当死，则他醉于床上；若是当死，则他不醉。”二人商议停当。
却说张飞在帐中，神思昏乱，动止恍惚，乃问部将曰：“吾今心惊肉颠，坐卧不安，此何意也？”部将答曰：“此是君侯思念关公，以致如此。”飞令人将酒来，与部将同饮，不觉大醉，卧于帐中。范、张二贼，探知消息，初更时分，各藏短刀，密入帐中，诈言欲禀机密重事，直至床前。原来张飞每睡不合眼；当夜寝于帐中，二贼见他须竖目张，本不敢动手。因闻鼻息如雷，方敢近前，以短刀刺入飞腹。飞大叫一声而亡。时年五十五岁。后人有诗叹曰：“安喜曾闻鞭督邮，黄巾扫尽佐炎刘。虎牢关上声先震，长坂桥边水逆流。义释严颜安蜀境，智欺张郃定中州。伐吴未克身先死，秋草长遗阆地愁。”却说二贼当夜割了张飞首级，便引数十人连夜投东吴去了。次日，军中闻知，起兵追之不及。时有张飞部将吴班，向自荆州来见先主，先主用为牙门将，使佐张飞守阆中。当下吴班先发表章，奏知天子；然后令长子张苞具棺椁盛贮，令弟张绍守阆中，苞自来报先主。时先主已择期出师。大小官僚，皆随孔明送十里方回。孔明回至成都，怏怏不乐，顾谓众官曰：“法孝直若在，必能制主上东行也。”
却说先主是夜心惊肉颤，寝卧不安。出帐仰观天文，见西北一星，其大如斗，忽然坠地。先主大疑，连夜令人求问孔明。孔明回奏曰：“合损一上将。三日之内，必有惊报。”先主因此按兵不动。忽侍臣奏曰：“阆中张车骑部将吴班，差人赍表至。”先主顿足曰：“噫！三弟休矣！”及至览表，果报张飞凶信。先主放声大哭，昏绝于地。众官救醒。
次日，人报一队军马骤风而至。先主出营观之。良久，见一员小将，白袍银铠，滚鞍下马，伏地而哭，乃张苞也。苞曰：“范疆、张达杀了臣父，将首级投吴去了！”先主哀痛至甚，饮食不进。群臣苦谏曰：“陛下方欲为二弟报仇，何可先自摧残龙体？”先主方才进膳，遂谓张苞曰：“卿与吴班，敢引本部军作先锋，为卿父报仇否？”苞曰：“为国为父，万死不辞！”先主正欲遣苞起兵，又报一彪军风拥而至。先主令侍臣探之。须臾，侍臣引一小将军，白袍银铠，入营伏地而哭。先主视之，乃关兴也。先主见了关兴，想起关公，又放声大哭。众官苦劝。先主曰：“朕想布衣时，与关、张结义，誓同生死；今朕为天子，正欲与两弟同享富贵，不幸俱死于非命！见此二侄，能不断肠！”言讫又哭。众官曰：“二小将军且退。容圣上将息龙体。”侍臣奏曰：“陛下年过六旬，不宜过于哀痛。”先主曰：“二弟俱亡，朕安忍独生！”言讫，以头顿地而哭。
多官商议曰：“今天子如此烦恼，将何解劝？”马良曰：“主上亲统大兵伐吴，终日号泣，于军不利。”陈震曰：“吾闻成都青城山之西，有一隐者，姓李，名意。世人传说此老已三百余岁，能知人之生死吉凶，乃当世之神仙也。何不奏知天子，召此老来，问他吉凶，胜如吾等之言。”遂入奏先主。先主从之，即遣陈震赍诏，往青城山宣召。震星夜到了青城，令乡人引入山谷深处，遥望仙庄，清云隐隐，瑞气非凡。忽见一小童来迎曰：“来者莫非陈孝起乎？”震大惊曰：“仙童如何知我姓字！”童子曰：“吾师昨者有言：今日必有皇帝诏命至；使者必是陈孝起。”震曰：“真神仙也！人言信不诬矣！”遂与小童同入仙庄，拜见李意，宣天子诏命。李意推老不行。震曰：“天子急欲见仙翁一面，幸勿吝鹤驾。”再三敦请，李意方行。即至御营，入见先主。先主见李意鹤发童颜，碧眼方瞳，灼灼有光，身如古柏之状，知是异人，优礼相待。李意曰：“老夫乃荒山村叟，无学无识。辱陛下宣召，不知有何见谕？”先主曰：“朕与关、张二弟结生死之交，三十余年矣。今二弟被害，亲统大军报仇，未知休咎如何。久闻仙翁通晓玄机，望乞赐教。”李意曰：“此乃天数，非老夫所知也。”先主再三求问，意乃索纸笔画兵马器械四十余张，画毕便一一扯碎。又画一大人仰卧于地上，傍边一人掘土埋之，上写一大“白”字，遂稽首而去。先主不悦，谓群臣曰：“此狂叟也！不足为信。”即以火焚之，便催军前进。
张苞入奏曰：“吴班军马已至。小臣乞为先锋。”先主壮其志，即取先锋印赐张苞。苞方欲挂印，又一少年将奋然出曰：“留下印与我！”视之，乃关兴也。苞曰：“我已奉诏矣。”兴曰：“汝有何能，敢当此任？”苞曰：“我自幼习学武艺，箭无虚发。”先主曰：“朕正要观贤侄武艺，以定优劣。”苞令军士于百步之外，立一面旗，旗上画一红心。苞拈弓取箭，连射三箭，皆中红心。众皆称善。关兴挽弓在手曰：“射中红心何足为奇？”正言间，忽值头上一行雁过。兴指曰：“吾射这飞雁第三只。”一箭射去，那只雁应弦而落。文武官僚，齐声喝采。苞大怒，飞身上马，手挺父所使丈八点钢矛，大叫曰：“你敢与我比试武艺否？”兴亦上马，绰家传大砍刀纵马而出曰：“偏你能使矛！吾岂不能使刀！”
二将方欲交锋，先主喝曰：“二子休得无礼！”兴、苞二人慌忙下马，各弃兵器，拜伏请罪。先主曰：“朕自涿郡与卿等之父结异姓之交，亲如骨肉；今汝二人亦是昆仲之分，正当同心协力，共报父仇；奈何自相争竞，失其大义！父丧未远而犹如此，况日后乎？”二人再拜伏罪。先主问曰：“卿二人谁年长？”苞曰：“臣长关兴一岁。”先主即命兴拜苞为兄。二人就帐前折箭为誓，永相救护。先主下诏使吴班为先锋，令张苞、关兴护驾。水陆并进，船骑双行，浩浩荡荡，杀奔吴国来。却说范疆、张达将张飞首级，投献吴侯，细告前事。孙权听罢，收了二人，乃谓百官曰：“今刘玄德即了帝位，统精兵七十余万，御驾亲征，其势甚大，如之奈何？”百官尽皆失色，面面相觑。诸葛瑾出曰：“某食君侯之禄久矣，无可报效，愿舍残生，去见蜀主，以利害说之，使两国相和，共讨曹丕之罪。”权大喜，即遣诸葛瑾为使，来说先主罢兵。正是：两国相争通使命，一言解难赖行人。
未知诸葛瑾此去如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536944219, '5b9b701f1579a3003a4fa99a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639220, '三国演义 · 第八十二回 · 孙权降魏受九锡 先主征吴赏六军', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说章武元年秋八月，先主起大军至夔关，驾屯白帝城。前队军马已出川口。近臣奏曰：“吴使诸葛瑾至。”先主传旨教休放入。黄权奏曰：“瑾弟在蜀为相，必有事而来。陛下何故绝之？当召入，看他言语。可从则从；如不可，则就借彼口说与孙权，令知问罪有名也。”先主从之，召瑾入城。瑾拜伏于地。先主问曰：“子瑜远来，有何事故？”瑾曰：“臣弟久事陛下，臣故不避斧钺，特来奏荆州之事。前者，关公在荆州时，吴侯数次求亲，关公不允。后关公取襄阳，曹操屡次致书吴侯，使袭荆州；吴侯本不肯许，因吕蒙与关公不睦，故擅自兴兵，误成大事，今吴侯悔之不及。此乃吕蒙之罪，非吴侯之过也。今吕蒙已死，冤仇已息。孙夫人一向思归。今吴侯令臣为使，愿送归夫人，缚还降将，并将荆州仍旧交还，永结盟好，共灭曹丕，以正篡逆之罪。”先主怒曰：“汝东吴害了朕弟，今日敢以巧言来说乎！”瑾曰：“臣请以轻重大小之事，与陛下论之：陛下乃汉朝皇叔，今汉帝已被曹丕篡夺，不思剿除；却为异姓之亲，而屈万乘之尊：是舍大义而就小义也。中原乃海内之地，两都皆大汉创业之方，陛下不取，而但争荆州：是弃重而取轻也。天下皆知陛下即位，必兴汉室，恢复山河；今陛下置魏不问，反欲伐吴：窃为陛下不取。”先主大怒曰：“杀吾弟之仇，不共戴天！欲朕罢兵，除死方休！不看丞相之面，先斩汝首！今且放汝回去，说与孙权：洗颈就戮！”诸葛瑾见先主不听，只得自回江南。
却说张昭见孙权曰：“诸葛子瑜知蜀兵势大，故假以请和为辞，欲背吴入蜀。此去必不回矣。”权曰：“孤与子瑜，有生死不易之盟；孤不负子瑜，子瑜亦不负孤。昔子瑜在柴桑时，孔明来吴，孤欲使子瑜留之。子瑜曰：‘弟已事玄德，义无二心；弟之不留，犹瑾之不往。’其言足贯神明。今日岂肯降蜀乎？孤与子瑜可谓神交，非外言所得间也。”正言间，忽报诸葛瑾回。权曰：“孤言若何？”张昭满面羞惭而退。瑾见孙权，言先主不肯通和之意。权大惊曰：“若如此，则江南危矣！”阶下一人进曰：“某有一计，可解此危。”视之，乃中大夫赵咨也。权曰：“德度有何良策？”咨曰：“主公可作一表，某愿为使，往见魏帝曹丕，陈说利害，使袭汉中，则蜀兵自危矣。”权曰：“此计最善。但卿此去，休失了东吴气象。”咨曰：“若有些小差失，即投江而死，安有面目见江南人物乎！”
权大喜，即写表称臣，令赵咨为使。星夜到了许都，先见太尉贾诩等，并大小官僚。次日早朝，贾诩出班奏曰：“东吴遣中大夫赵咨上表。”曹丕笑曰：“此欲退蜀兵故也。”即令召入。咨拜伏于丹墀。丕览表毕，遂问咨曰：“吴侯乃何如主也：”咨曰：“聪明、仁智、雄略之主也。”丕笑曰：“卿褒奖毋乃太甚？”咨曰：“臣非过誉也。吴侯纳鲁肃于凡品，是其聪也；拔吕蒙于行阵，是其明也；获于禁而不害，是其仁也；取荆州兵不血刃，是其智也；据三江虎视天下，是其雄也；屈身于陛下，是其略也：以此论之，岂不为聪明、仁智、雄略之主乎？”丕又问曰：“吴主颇知学乎？”咨曰：“吴主浮江万艘，带甲百万，任贤使能，志存经略；少有余闲，博览书传，历观史籍，采其大旨，不效书生寻章摘句而已。”丕曰：“朕欲伐吴，可乎？”咨曰：“大国有征伐之兵，小国有御备之策。”丕曰：“吴畏魏乎？”咨曰：“带甲百万，江汉为池，何畏之有？”丕曰：“东吴如大夫者几人？”咨曰：“聪明特达者八九十人；如臣之辈，车载斗量，不可胜数。”丕叹曰：“使于四方，不辱君命，卿可以当之矣。”于是即降诏，命太常卿邢贞赍册封孙权为吴王，加九锡。赵咨谢恩出城。
大夫刘晔谏曰：“今孙权惧蜀兵之势，故来请降。以臣愚见：蜀、吴交兵，乃天亡之也；今若遣上将提数万之兵，渡江袭之，蜀攻其外，魏攻其内，吴国之亡，不出旬日。吴亡则蜀孤矣。陛下何不早图之？”丕曰：“孙权既以礼服朕，朕若攻之，是沮天下欲降者之心；不若纳之为是。”刘晔又曰：“孙权虽有雄才，乃残汉骠骑将军、南昌侯之职。官轻则势微，尚有畏中原之心；若加以王位，则去陛下一阶耳。今陛下信其诈降，崇其位号以封殖之，是与虎添翼也。”丕曰：“不然。朕不助吴，亦不助蜀。待看吴、蜀交兵，若灭一国，止存一国，那时除之，有何难哉？朕意已决，卿勿复言。”遂命太常卿邢贞同赵咨捧执册锡，径至东吴。
却说孙权聚集百官，商议御蜀兵之策。忽报魏帝封主公为王，礼当远接，顾雍谏曰：“主公宜自称上将军、九州伯之位，不当受魏帝封爵。”权曰：“当日沛公受项羽之封，盖因时也；何故却之？”遂率百官出城迎接。邢贞自恃上国天使，入门不下车。张昭大怒，厉声曰：“礼无不敬，法无不肃，而君敢自尊大，岂以江南无方寸之刃耶？”邢贞慌忙下车，与孙权相见，并车入城。忽车后一人放声哭曰：“吾等不能奋身舍命，为主并魏吞蜀，乃令主公受人封爵，不亦辱乎！”众视之，乃徐盛也。邢贞闻之，叹曰：“江东将相如此，终非久在人下者也！”却说孙权受了封爵，众文武官僚拜贺已毕，命收拾美玉明珠等物，遣人赍进谢恩。早有细作报说蜀主引本国大兵，及蛮王沙摩柯番兵数万，又有洞溪汉将杜路、刘宁二枝兵，水陆并进，声势震天。水路军已出巫口，旱路军已到秭归。时孙权虽登王位，奈魏主不肯接应，乃问文武曰：“蜀兵势大，当复如何？”众皆默然。权叹曰：“周郎之后有鲁肃，鲁肃之后有吕蒙，今吕蒙已亡，无人与孤分忧也！”言未毕，忽班部中一少年将，奋然而出，伏地奏曰：“臣虽年幼，颇习兵书。愿乞数万之兵，以破蜀兵。”权视之，乃孙桓也。桓字叔武，其父名河，本姓俞氏，孙策爱之，赐姓孙，因此亦系吴王宗族。河生四子，桓居其长，弓马熟娴，常从吴王征讨，累立奇功，官授武卫都尉；时年二十五岁。权曰：“汝有何策胜之？”桓曰：“臣有大将二员：一名李异，一名谢旌，俱有万夫不当之勇。乞数万之众，往擒刘备。”权曰：“侄虽英勇，争奈年幼；必得一人相助，方可。”虎威将军朱然出曰：“臣愿与小将军同擒刘备。”权许之，遂点水陆军五万，封孙桓为左都督，朱然为右都督，即日起兵。哨马探得蜀兵已至宜都下寨，孙桓引二万五千军马，屯于宜都界口，前后分作三营，以拒蜀兵。却说蜀将吴班领先锋之印，自出川以来，所到之处，望风而降，兵不血刃，直到宜都；探知孙桓在彼下寨，飞奏先主。时先主已到秭归，闻奏怒曰：“量此小儿，安敢与朕抗耶！”关兴奏曰：“既孙权令此子为将，不劳陛下遣大将，臣愿往擒之。”先主曰：“朕正欲观汝壮气。”即命关兴前往。兴拜辞欲行，张苞出曰：“既关兴前去讨贼，臣愿同行。”先主曰：“二侄同行甚妙，但须谨慎，不可造次。”
二人拜辞先主，会合先锋，一同进兵，列成阵势。孙桓听知蜀兵大至，合寨多起。两阵对圆，桓领李异、谢旌立马于门旗之下，见蜀营中，拥出二员大将，皆银盔银铠，白马白旗：上首张苞挺丈八点钢矛，下首关兴横着大砍刀。苞大骂曰：“孙桓竖子！死在临时，尚敢抗拒天兵乎！”桓亦骂曰：“汝父已作无头之鬼；今汝又来讨死，好生不智！”张苞大怒，挺枪直取孙桓。桓背后谢旌，骤马来迎。两将战有三十余合，旌败走，苞乘胜赶来。李异见谢旌败了，慌忙拍马轮蘸金斧接战。张苞与战二十余合，不分胜负。吴军中裨将谭雄，见张苞英勇，李异不能胜，却放一冷箭，正射中张苞所骑之马。那马负痛奔回本阵，未到门旗边，扑地便倒，将张苞掀在地上。李异急向前轮起大斧，望张苞脑袋便砍。忽一道红光闪处，李异头早落地，原来关兴见张苞马回，正待接应，忽见张苞马倒，李异赶来，兴大喝一声，劈李异于马下，救了张苞。乘势掩杀，孙桓大败。各自鸣金收军。
次日，孙桓又引军来。张苞、关兴齐出。关兴立马于阵前，单搦孙桓交锋。桓大怒，拍马轮刀，与关兴战三十余合，气力不加，大败回阵。二小将追杀入营，吴班引着张南、冯习驱兵掩杀。张苞奋勇当先，杀入吴军，正遇谢旌，被苞一矛刺死。吴军四散奔走。蜀将得胜收兵，只不见了关兴。张苞大惊曰：“安国有失，吾不独生！”言讫，绰枪上马。寻不数里，只见关兴左手提刀，右手活挟一将。苞问曰：“此是何人？”兴笑答曰：“吾在乱军中，正遇仇人，故生擒来。”苞视之，乃昨日放冷箭的谭雄也。苞大喜，同回本营，斩首沥血，祭了死马。遂写表差人赴先主处报捷。
孙桓折了李异、谢旌、谭雄等许多将士，力穷势孤，不能抵敌，即差人回吴求救。蜀将张南、冯习谓吴班曰：“目今吴兵势败，正好乘虚劫寨。”班曰：“孙桓虽然折了许多将士，朱然水军现今结营江上，未曾损折。今日若去劫寨，倘水军上岸，断我归路，如之奈何？”南曰：“此事至易：可教关、张二将军，各引五千军伏于山谷中；如朱然来救，左右两军齐出夹攻，必然取胜。”班曰：“不如先使小卒诈作降兵，却将劫寨事告与朱然；然见火起，必来救应，却令伏兵击之，则大事济矣。”冯习等大喜，遂依计而行。
却说朱然听知孙桓损兵折将，正欲来救，忽伏路军引几个小卒上船投降。然问之，小卒曰：“我等是冯习帐下士卒，因赏罚不明，待来投降，就报机密。”然曰：“所报何事？”小卒曰：“今晚冯习乘虚要劫孙将军营寨，约定举火为号。”朱然听毕，即使人报知孙桓。报事人行至半途，被关兴杀了。朱然一面商议，欲引兵去救应孙桓。部将崔禹曰：“小卒之言，未可深信。倘有疏虞，水陆二军尽皆休矣。将军只宜稳守水寨，某愿替将军一行。”然从之，遂令崔禹引一万军前去。是夜，冯习、张南、吴班分兵三路，直杀入孙桓寨中，四面火起，吴兵大乱，寻路奔走。
且说崔禹正行之间，忽见火起，急催兵前进。刚才转过山来，忽山谷中鼓声大震：左边关兴，右边张苞，两路夹攻。崔禹大惊，方欲奔走，正遇张苞；交马只一合，被苞生擒而回。朱然听知危急，将船往下水退五六十里去了。孙桓引败军逃走，问部将曰：“前去何处城坚粮广？”部将曰：“此去正北彝陵城，可以屯兵。”桓引败军急望彝陵而走。方进得城，吴班等追至，将城四面围定。关兴、张苞等解崔禹到秭归来。先主大喜，传旨将崔禹斩却，大赏三军。自此威风震动，江南诸将无不胆寒。
却说孙桓令人求救于吴王，吴王大惊，即召文武商议曰：“今孙桓受困于彝陵，朱然大败于江中，蜀兵势大，如之奈何？”张昭奏曰：“今诸将虽多物故，然尚有十余人，何虑于刘备？可命韩当为正将，周泰为副将，潘璋为先锋，凌统为合后，甘宁为救应，起兵十万拒之。”权依所奏，即命诸将速行。此时甘宁已患痢疾，带病从征。
却说先主从巫峡建平起，直接彝陵界分，七百余里，连结四十余寨；见关兴、张苞屡立大功，叹曰：“昔日从朕诸将，皆老迈无用矣；复有二侄如此英雄，朕何虑孙权乎！”正言间，忽报韩当、周泰领兵来到。先主方欲遣将迎敌，近臣奏曰：“老将黄忠，引五六人投东吴去了。”先主笑曰：“黄汉升非反叛之人也；因朕失口误言老者无用，彼必不服老，故奋力去相持矣。”即召关兴、张苞曰：“黄汉升此去必然有失。贤侄休辞劳苦，可去相助。略有微功，便可令回，勿使有失。”二小将拜辞先主，引本部军来助黄忠。正是：老臣素矢忠君志，年少能成报国功。
未知黄忠此去如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536944219, '5b9b7038808ca43cd222a0ee', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639221, '三国演义 · 第八十三回 · 战猇亭先主得仇人 守江口书生拜大将', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说章武二年春正月，武威后将军黄忠随先主伐吴；忽闻先主言老将无用，即提刀上马，引亲随五六人，径到彝陵营中。吴班与张南、冯习接入，问曰：“老将军此来，有何事故？”忠曰：“吾自长沙跟天子到今，多负勤劳。今虽七旬有余，尚食肉十斤，臂开二石之弓，能乘千里之马，未足为老。昨日主上言吾等老迈无用，故来此与东吴交锋，看吾斩将，老也不老！”正言间，忽报吴兵前部已到，哨马临营。忠奋然而起，出帐上马。冯习等劝曰：“老将军且休轻进。”忠不听，纵马而去。吴班令冯习引兵助战。忠在吴军阵前，勒马横刀，单搦先锋潘璋交战。璋引部将史迹出马。迹欺忠年老，挺枪出战；斗不三合，被忠一刀斩于马下。潘璋大怒，挥关公使的青龙刀，来战黄忠。交马数合，不分胜负。忠奋力恶战，璋料敌不过，拨马便走。忠乘势追杀，全胜而回。路逢关兴、张苞。兴曰：“我等奉圣旨来助老将军；既已立了功，速请回营。”忠不听。次日，潘璋又来搦战。黄忠奋然上马。兴、苞二人要助战，忠不从；吴班要助战，忠亦不从；只自引五千军出迎。战不数合，璋拖刀便走。忠纵马追之，厉声大叫曰：“贼将休走！吾今为关公报仇！”追至三十余里，四面喊声大震，伏兵齐出：右边周泰，左边韩当，前有潘璋，后有凌统，把黄忠困在垓心。忽然狂风大起，忠急退时，山坡上马忠引一军出，一箭射中黄忠肩窝，险些儿落马。吴兵见忠中箭，一齐来攻，忽后面喊声大起，两路军杀来，吴兵溃散，救出黄忠，乃关兴、张苞也。二小将保送黄忠径到御前营中。忠年老血衰，箭疮痛裂，病甚沉重。先主御驾自来看视，抚其背曰：“令老将军中伤，朕之过也！”忠曰：“臣乃一武夫耳，幸遇陛下。臣今年七十有五，寿亦足矣。望陛下善保龙体，以图中原！”言讫，不省人事。是夜殒于御营。后人有诗叹曰：“老将说黄忠，收川立大功。重披金锁甲，双挽铁胎弓。胆气惊河北，威名镇蜀中。临亡头似雪，犹自显英雄。”
先主见黄忠气绝，哀伤不已，敕具棺椁，葬于成都。先主叹曰：“五虎大将，已亡三人。朕尚不能复仇，深可痛哉！”乃引御林军直至猇亭，大会诸将，分军八路，水陆俱进。水路令黄权领兵，先主自率大军于旱路进发。时章武二年二月中旬也。韩当、周泰听知先主御驾来征，引兵出迎。两阵对圆，韩当、周泰出马，只见蜀营门旗开处，先主自出，黄罗销金伞盖，左右白旌黄钺，金银旌节，前后围绕。当大叫曰：“陛下今为蜀主，何自轻出？倘有疏虞，悔之何及！”先主遥指骂曰：“汝等吴狗，伤朕手足，誓不与立于天地之间！”当回顾众将曰：“谁敢冲突蜀兵？”部将夏恂，挺枪出马。先主背后张苞挺丈八矛，纵马而出，大喝一声，直取夏恂。恂见苞声若巨雷，心中惊惧；恰待要走，周泰弟周平见恂抵敌不住，挥刀纵马而来。关兴见了，跃马提刀来迎。张苞大喝一声，一矛刺中夏恂，倒撞下马。周平大惊，措手不及，被关兴一刀斩了。二小将便取韩当、周泰。韩、周二人，慌退入阵。先主视之，叹曰：“虎父无犬子也！”用御鞭一指，蜀兵一齐掩杀过去，吴兵大败。那八路兵，势如泉涌，杀的那吴军尸横遍野，血流成河。
却说甘宁正在船中养病，听知蜀兵大至，火急上马，正遇一彪蛮兵，人皆披发跣足，皆使弓弩长枪，搪牌刀斧；为首乃是番王沙摩柯，生得面如噀血，碧眼突出，使一个铁蒺藜骨朵，腰带两张弓，威风抖擞。甘宁见其势大，不敢交锋，拨马而走；被沙摩柯一箭射中头颅。宁带箭而走，到于富池口，坐于大树之下而死。树上群鸦数百，围绕其尸。吴王闻之，哀痛不已，具礼厚葬，立庙祭祀。后人有诗叹曰：“吴郡甘兴霸，长江锦幔舟。酬君重知己，报友化仇雠。劫寨将轻骑，驱兵饮巨瓯。神鸦能显圣，香火永千秋。”
却说先主乘势追杀，遂得猇亭。吴兵四散逃走。先主收兵，只不见关兴。先主慌令张苞等四面跟寻。原来关兴杀入吴阵，正遇仇人潘璋，骤马追之。璋大惊，奔入山谷内，不知所往。兴寻思只在山里，往来寻觅不见。看看天晚，迷踪失路。幸得星月有光，追至山僻之间，时已二更，到一庄上，下马叩门。一老者出问何人。兴曰：“吾是战将，迷路到此，求一饭充饥。”老人引入，兴见堂内点着明烛，中堂绘画关公神像。兴大哭而拜。老人问曰：“将军何故哭拜？”兴曰：“此吾父也。”老人闻言，即便下拜。兴曰：“何故供养吾父？”老人答曰：“此间皆是尊神地方。在生之日，家家侍奉，何况今日为神乎？老夫只望蜀兵早早报仇。今将军到此，百姓有福矣。”遂置酒食待之，卸鞍喂马。
三更已后，忽门外又一人击户。老人出而问之，乃吴将潘璋亦来投宿。恰入草堂，关兴见了，按剑大喝曰：“歹贼休走！”璋回身便出。忽门外一人，面如重枣，丹凤眼，卧蚕眉，飘三缕美髯，绿袍金铠，按剑而入。璋见是关公显圣，大叫一声，神魂惊散；欲待转身，早被关兴手起剑落，斩于地上，取心沥血，就关公神像前祭祀。兴得了父亲的青龙偃月刀，却将潘璋首级，擐于马项之下，辞了老人，就骑了潘璋的马，望本营而来。老人自将潘璋之尸拖出烧化。
且说关兴行无数里，忽听得人言马嘶，一彪军来到；为首一将，乃潘璋部将马忠也。忠见兴杀了主将潘璋，将首级擐于马项之下，青龙刀又被兴得了，勃然大怒，纵马来取关兴。兴见马忠是害父仇人，气冲牛斗，举青龙刀望忠便砍。忠部下三百军并力上前，一声喊起，将关兴围在垓心。兴力孤势危。忽见西北上一彪军杀来，乃是张苞。马忠见救兵到来，慌忙引军自退。关兴、张苞一处赶来。赶不数里，前面糜芳、傅士仁引兵来寻马忠。两军相合，混战一处。苞、兴二人兵少，慌忙撤退，回至猇亭，来见先主，献上首级，具言此事。先主惊异，赏犒三军。却说马忠回见韩当、周泰，收聚败军，各分头守把。军士中伤者不计其数。马忠引傅士仁、糜芳于江渚屯扎。当夜三更，军士皆哭声不止。糜芳暗听之，有一夥军言曰：“我等皆是荆州之兵，被吕蒙诡计送了主公性命，今刘皇叔御驾亲征，东吴早晚休矣。所恨者，糜芳、傅士仁也。我等何不杀此二贼，去蜀营投降？功劳不小。”又一伙军言曰：“不要性急，等个空儿，便就下手。”
糜芳听毕，大惊，遂与傅士仁商议曰：“军心变动，我二人性命难保。今蜀主所恨者马忠耳；何不杀了他，将首级去献蜀主，告称：‘我等不得已而降吴，今知御驾前来，特地诣营请罪。’”仁曰：“不可。去必有祸。”芳曰：“蜀主宽仁厚德：目今阿斗太子是我外甥，彼但念我国戚之情，必不肯加害。”二人计较已定，先备了马。三更时分，入帐刺杀马忠，将首级割了，二人带数十骑，径投猇亭而来。伏路军人先引见张南、冯习，具说其事。次日，到御营中来见先主，献上马忠首级，哭告于前曰：“臣等实无反心；被吕蒙诡计，称言关公已亡，赚开城门，臣等不得已而降。今闻圣驾前来，特杀此贼。以雪陛下之恨。伏乞陛下恕臣等之罪。”先主大怒曰：“朕自离成都许多时，你两个如何不来请罪？今日势危，故来巧言，欲全性命！朕若饶你，至九泉之下，有何面目见关公乎！”言讫，令关兴在御营中，设关公灵位。先主亲捧马忠首级，诣前祭祀。又令关兴将糜芳、傅士仁剥去衣服，跪于灵前，亲自用刀剐之，以祭关公。忽张苞上帐哭拜于前曰：“二伯父仇人皆已诛戮；臣父冤仇，何日可报？”先主曰：“贤侄勿忧。朕当削平江南，杀尽吴狗，务擒二贼，与汝亲自醢之，以祭汝父。“苞泣谢而退。
此时先主威声大震，江南之人尽皆胆裂，日夜号哭。韩当、周泰大惊，急奏吴王，具言糜芳、傅士仁杀了马忠，去归蜀帝，亦被蜀帝杀了。孙权心怯，遂聚文武商议。步骘奏曰：“蜀主所恨者，乃吕蒙、潘璋、马忠、糜芳、傅士仁也。今此数人皆亡，独有范疆、张达二人，现在东吴。何不擒此二人，并张飞首级，遣使送还，交与荆州，送归夫人，上表求和，再会前情，共图灭魏，则蜀兵自退矣。”权从其言，遂具沉香木匣，盛贮飞首，绑缚范疆、张达，囚于槛车之内，令程秉为使，赍国书，望猇亭而来。
却说先主欲发兵前进。忽近臣奏曰：“东吴遣使送张车骑之首，并囚范疆、张达二贼至。”先主两手加额曰：“此天之所赐，亦由三弟之灵也！“即令张苞设飞灵位。先主见张飞首级在匣中面不改色，放声大哭。张苞自仗利刀，将范疆、张达万剐凌迟，祭父之灵。祭毕，先主怒气不息，定要灭吴。马良奏曰：“仇人尽戳，其恨可雪矣。吴大夫程秉到此，欲还荆州，送回夫人，永结盟好，共图灭魏，伏候圣旨。”先主怒曰：“朕切齿仇人，乃孙权也。今若与之连和，是负二弟当日之盟矣。今先灭吴，次灭魏。”便欲斩来使，以绝吴情。多官苦告方免。程秉抱头鼠窜，回奏吴主曰：“蜀不从讲和，誓欲先灭东吴，然后伐魏。众臣苦谏不听，如之奈何？“
权大惊，举止失措。阚泽出班奏曰：“现有擎天之柱，如何不用耶？”权急问何人。泽曰：“昔日东吴大事，全任周郎；后鲁子敬代之；子敬亡后，决于吕子明；今子明虽丧，现有陆伯言在荆州。此人名虽儒生，实有雄才大略，以臣论之，不在周郎之下；前破关公，其谋皆出于伯言。主上若能用之，破蜀必矣。如或有失，臣愿与同罪。”权曰：“非德润之言，孤几误大事。”张昭曰：“陆逊乃一书生耳，非刘备敌手；恐不可用。”顾雍亦曰：“陆逊年幼望轻，恐诸公不服；若不服则生祸乱，必误大事。”步骘亦曰：“逊才堪治郡耳；若托以大事，非其宜也。”阚泽大呼曰：“若不用陆伯言，则东吴休矣！臣愿以全家保之！”权曰：“孤亦素知陆伯言乃奇才也！孤意已决，卿等勿言。”于是命召陆逊。逊本名陆议，后改名逊，字伯言，乃吴郡吴人也；汉城门校尉陆纡之孙，九江都尉陆骏之子；身长八尺，面如美玉；官领镇西将军。当下奉召而至，参拜毕，权曰：“今蜀兵临境，孤特命卿总督军马，以破刘备。”逊曰：“江东文武，皆大王故旧之臣；臣年幼无才，安能制之？”权曰：“阚德润以全家保卿，孤亦素知卿才。今拜卿为大都督，卿勿推辞。”逊曰：“倘文武不服，何如？”权取所佩剑与之曰：“如有不听号令者，先斩后奏。”逊曰：“荷蒙重托，敢不拜命；但乞大王于来日会聚众官，然后赐臣。”阚泽曰：“古之命将，必筑坛会众，赐白旄黄钺、印绶兵符，然后威行令肃。今大王宜遵此礼，择日筑坛，拜伯言为大都督，假节钺，则众人自无不服矣。”权从之，命人连夜筑坛完备，大会百官，请陆逊登坛，拜为大都督、右护军镇西将军，进封娄候，赐以宝剑印绶，令掌六郡八十一州兼荆楚诸路军马。吴王嘱之曰：“阃以内，孤主之；阃以外，将军制之。”
逊领命下坛，令徐盛、丁奉为护卫，即日出师；一面调诸路军马，水陆并进。文书到猇亭，韩当、周泰大惊曰：“主上如何以一书生总兵耶？”比及逊至，众皆不服。逊升帐议事，众人勉强参贺。逊曰：“主上命吾为大将，督军破蜀。军有常法，公等各宜遵守。违者王法无亲，勿致后悔。”众皆默然。周泰曰：“目今安东将军孙桓，乃主上之侄，现困于彝陵城中，内无粮草，外无救兵；请都督早施良策，救出孙桓，以安主上之心。”逊曰：“吾素知孙安东深得军心，必能坚守，不必救之。待吾破蜀后，彼自出矣。”众皆暗笑而退。韩当谓周泰曰：“命此孺子为将，东吴休矣！公见彼所行乎？”泰曰：“吾聊以言试之，早无一计，安能破蜀也！”
次日，陆逊传下号令，教诸将各处关防，牢守隘口，不许轻敌。众皆笑其懦，不肯坚守。次日，陆逊升帐唤诸将曰：“吾钦承王命，总督诸军，昨已三令五申，令汝等各处坚守；俱不遵吾令，何也？”韩当曰：“吾自从孙将军平定江南，经数百战；其余诸将，或从讨逆将军，或从当今大王，皆披坚执锐，出生入死之士。今主上命公为大都督，令退蜀兵，宜早定计，调拨军马，分头征进，以图大事；乃只令坚守勿战，岂欲待天自杀贼耶？吾非贪生怕死之人，奈何使吾等堕其锐气？”于是帐下诸将，皆应声而言曰：“韩将军之言是也。吾等情愿决一死战！”陆逊听毕，掣剑在手，厉声曰：“仆虽一介书生，今蒙主上托以重任者，以吾有尺寸可取，能忍辱负重故也。汝等只各守隘口，牢把险要，不许妄动，如违令者皆斩！”众皆愤愤而退。
却说先主自猇亭布列军马，直至川口，接连七百里，前后四十营寨，昼则旌旗蔽日，夜则火光耀天。忽细作报说：“东吴用陆逊为大都督，总制军马。逊令诸将各守险要不出。”先主问曰：“陆逊何如人也？’马良奏曰：“逊虽东吴一书生，然年幼多才，深有谋略；前袭荆州，皆系此人之诡计。”先主大怒曰：“竖子诡计，损朕二弟，今当擒之！”便传令进兵。马良谏曰：“陆逊之才，不亚周郎，未可轻敌。”先主曰：“朕用兵老矣，岂反不如一黄口孺子耶！”遂亲领前军，攻打诸处关津隘口。韩当见先主兵来，差人投知陆逊。逊恐韩当妄动，急飞马自来观看，正见韩当立马于山上；远望蜀兵，漫山遍野而来，军中隐隐有黄罗盖伞。韩当接着陆逊，并马而观。当指曰：“军中必有刘备，吾欲击之。”逊曰：“刘备举兵东下，连胜十余阵，锐气正盛；今只乘高守险，不可轻出，出则不利。但宜奖励将士，广布守御之策，以观其变。今彼驰骋于平原广野之间，正自得志；我坚守不出，彼求战不得，必移屯于山林树木间。吾当以奇计胜之。”
韩当口虽应诺，心中只是不服，先主使前队搦战，辱骂百端。逊令塞耳休听，不许出迎，亲自遍历诸关隘口，抚慰将士，皆令坚守。先主见吴军不出，心中焦躁。马良曰：“陆逊深有谋略。今陛下远来攻战，自春历夏；彼之不出，欲待我军之变也。愿陛下察之。”先主曰：“彼有何谋？但怯敌耳。向者数败，今安敢再出！”先锋冯习奏曰：“即今天气炎热，军屯于赤火之中，取水深为不便。”先主遂命各营，皆移于山林茂盛之地，近溪傍涧；待过夏到秋，并力进兵。冯习遂奉旨，将诸寨皆移于林木阴密之处。马良奏曰：“我军若动，倘吴兵骤至，如之奈何？”先主曰：“朕令吴班引万余弱兵，近吴寨平地屯住；朕亲选八千精兵，伏于山谷之中。若陆逊知朕移营，必乘势来击，却令吴班诈败；逊若追来，朕引兵突出，断其归路，小子可擒矣。”文武皆贺曰：“陛下神机妙算，诸臣不及也！”马良曰：“近闻诸葛丞相在东川点看各处隘口，恐魏兵入寇。陛下何不将各营移居之地，画成图本，问于丞相？”先主曰：“朕亦颇知兵法，何必又问丞相？”良曰：“古云：‘兼听则明，偏听则蔽。’望陛下察之。”先主曰：“卿可自去各营，画成四至八道图本，亲到东川去向丞相。如有不便，可急来报知。”马良领命而去。于是先主移兵于林木阴密处避暑。早有细作报知韩当、周泰。二人听得此事，大喜，来见陆逊曰：“目今蜀兵四十余营，皆移于山林密处，依溪傍涧，就水歇凉。都督可乘虚击之。”正是：蜀主有谋能设伏，吴兵好勇定遭擒。
未知陆逊可听其言否，且看下文分解。', '', '', '', NULL, '', 'indent', 1536944087, '5b9b704f9f54540039b87bf0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639222, '三国演义 · 第八十四回 · 陆逊营烧七百里 孔明巧布八阵图', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说韩当、周泰探知先主移营就凉，急来报知陆逊。逊大喜，遂引兵自来观看动静；只见平地一屯，不满万余人，大半皆是老弱之众，大书“先锋吴班”旗号。周泰曰：“吾视此等兵如儿戏耳。愿同韩将军分两路击之。如其不胜，甘当军令。”陆逊看了良久，以鞭指曰：“前面山谷中。隐隐有杀气起；其下必有伏兵，故于平地设此弱兵，以诱我耳。诸公切不可出。”众将听了，皆以为懦。
次日，吴班引兵到关前搦战，耀武扬威，辱骂不绝；多有解衣卸甲，赤身裸体，或睡或坐。徐盛、丁奉入帐禀陆逊曰：“蜀兵欺我太甚！某等愿出击之！”逊笑曰：“公等但恃血气之勇，未知孙、吴妙法，此彼诱敌之计也：三日后必见其诈矣。”徐盛曰：“三日后，彼移营已定，安能击之乎？”逊曰：“吾正欲令彼移营也。”诸将哂笑而退。过三日后，会诸将于关上观望，见吴班兵已退去。逊指曰：“杀气起矣。刘备必从山谷中出也。”言未毕，只见蜀兵皆全装惯束，拥先主而过。吴兵见了，尽皆胆裂。逊曰：“吾之不听诸公击班者，正为此也。今伏兵已出，旬日之内，必破蜀矣。”诸将皆曰：“破蜀当在初时，今连营五六百里，相守经七八月，其诸要害，皆已固守，安能破乎？”逊曰：“诸公不知兵法。备乃世之枭雄，更多智谋，其兵始集，法度精专；今守之久矣，不得我便，兵疲意阻，取之正在今日。”诸将方才叹服。后人有诗赞曰：“虎帐谈兵按《六韬》，安排香饵钓鲸鳌。三分自是多英俊，又显江南陆逊高。”却说陆逊已定了破蜀之策，遂修笺遣使奏闻孙权，言指日可以破蜀之意。权览毕，大喜曰：“江东复有此异人，孤何忧哉！诸将皆上书言其懦，孤独不信，今观其言，果非懦也。”于是大起吴兵来接应。却说先主于猇亭尽驱水军，顺流而下，沿江屯扎水寨，深入吴境。黄权谏曰：“水军沿江而下，进则易，退则难。臣愿为前驱。陛下宜在后阵，庶万无一失。”先主曰：“吴贼胆落，朕长驱大进，有何碍乎？”众官苦谏，先主不从。遂分兵两路：命黄权督江北之兵，以防魏寇；先主自督江南诸军，夹江分立营寨，以图进取。细作探知，连夜报知魏主，言“蜀兵伐吴，树栅连营，纵横七百余里，分四十余屯，皆傍山林下寨；今黄权督兵在江北岸，每日出哨百余里，不知何意。”魏主闻之，仰面笑曰：“刘备将败矣！”群臣请问其故。魏主曰：“刘玄德不晓兵法；岂有连营七百里，而可以拒敌者乎？包原隰险阻屯兵者，此兵法之大忌也。玄德必败于东吴陆逊之手，旬日之内，消息必至矣。”群臣犹未信，皆请拨兵备之。魏主曰：“陆逊若胜，必尽举吴兵去取西川；吴兵远去，国中空虚，朕虚托以兵助战，令三路一齐进兵，东吴唾手可取也。”众皆拜服。魏主下令，使曹仁督一军出濡须，曹休督一军出洞口，曹真督一军出南郡：“三路军马会合日期，暗袭东吴。朕随后自来接应。”调遣已定。不说魏兵袭吴。且说马良至川，入见孔明，呈上图本而言曰：“今移营夹江，横占七百里，下四十余屯，皆依溪傍涧，林木茂盛之处。皇上令良将图本来与丞相观之。”孔明看讫，拍案叫苦曰：“是何人教主上如此下寨？可斩此人！”马良曰：“皆主上自为，非他人之谋。”孔明叹曰：“汉朝气数休矣！”良问其故。孔明曰：“包原隰险阻而结营，此兵家之大忌。倘彼用火攻，何以解救？又，岂有连营七百里而可拒敌乎？祸不远矣！陆逊拒守不出，正为此也。汝当速去见天子，改屯诸营，不可如此。”良曰：“倘今吴兵已胜，如之奈何？”孔明曰：“陆逊不敢来追，成都可保无虞。”良曰：“逊何故不追？”孔明曰：“恐魏兵袭其后也。主上若有失，当投白帝城避之。吾入川时，已伏下十万兵在鱼腹浦矣。”良大惊曰：“某于鱼腹浦往来数次，未尝见一卒，丞相何作此诈语？”孔明曰：“后来必见，不劳多问。”马良求了表章，火速投御营来。孔明自回成都，调拨军马救应。却说陆逊见蜀兵懈怠，不复提防，升帐聚大小将士听令曰：“吾自受命以来，未尝出战。今观蜀兵，足知动静，故欲先取江南岸一营。谁敢去取？”言未毕，韩当、周泰、凌统等应声而出曰：“某等愿往。”逊教皆退不用，独唤阶下末将淳于丹曰：“吾与汝五千军，去取江南第四营：蜀将傅彤所守。今晚就要成功。吾自提兵接应。”淳于丹引兵去了，又唤徐盛、丁奉曰：“汝等各领兵三千，屯于寨外五里，如淳于丹败回，有兵赶来，当出救之，却不可追去。”二将自引军去了。
却说淳于丹于黄昏时分，领兵前进，到蜀寨时，已三更之后。丹令众军鼓噪而入。蜀营内傅彤引军杀出，挺枪直取淳于丹；丹敌不住，拨马便回。忽然喊声大震，一彪军拦住去路：为首大将赵融。丹夺路而走，折兵大半，正走之间，山后一彪蛮兵拦住：为首番将沙摩柯。丹死战得脱，背后三路军赶来。比及离营五里，吴军徐盛、丁奉二人两下杀来，蜀兵退去，救了淳于丹回营。丹带箭入见陆逊请罪。逊曰：“非汝之过也。吾欲试敌人之虚实耳。破蜀之计，吾已定矣。”徐盛、丁奉曰：“蜀兵势大，难以破之，空自损兵折将耳。”逊笑曰：“吾这条计，但瞒不过诸葛亮耳。天幸此人不在，使我成大功也。”遂集大小将士听令：使朱然于水路进兵，来日午后东南风大作，用船装载茅草，依计而行；韩当引一军攻江北岸，周泰引一军攻江南岸，每人手执茅草一把，内藏硫黄焰硝，各带火种，各执枪刀，一齐而上，但到蜀营，顺风举火；蜀兵四十屯，只烧二十屯，每间一屯烧一屯。各军预带干粮，不许暂退，昼夜追袭，只擒了刘备方止。众将听了军令，各受计而去。却说先主正在御营寻思破吴之计，忽见帐前中军旗幡，无风自倒。乃问程畿曰：“此为何兆？”畿曰：“今夜莫非吴兵来劫营？”先主曰：“昨夜杀尽，安敢再来？”畿曰：“倘是陆逊试敌，奈何？”正言间，人报山上远远望见吴兵尽沿山望东去了。先主曰：“此是疑兵。”令众休动，命关兴、张苞各引五百骑出巡。黄昏时分，关兴回奏曰：“江北营中火起。”先主急令关兴往江北，张苞往江南，探看虚实：“倘吴兵到时，可急回报。”二将领命去了。
初更时分，东南风骤起。只见御营左屯火发。方欲救时，御营右屯又火起。风紧火急，树木皆着，喊声大震。两屯军马齐出，奔离御营中，御营军自相践踏，死者不知其数。后面吴兵杀到，又不知多少军马。先主急上马，奔冯习营时，习营中火光连天而起。江南、江北，照耀如同白日。冯习慌上马引数十骑而走，正逢吴将徐盛军到，敌住厮杀。先主见了，拨马投西便走。徐盛舍了冯习，引兵追来。先主正慌，前面又一军拦住，乃是吴将丁奉，两下夹攻。先主大惊，四面无路。忽然喊声大震，一彪军杀入重围，乃是张苞，救了先主，引御林军奔走。正行之间，前面一军又到，乃蜀将傅彤也，合兵一处而行。背后吴兵追至。先主前到一山，名马鞍山。张苞、傅彤请先主上的山时，山下喊声又起：陆逊大队人马，将马鞍山围住。张苞、傅彤死据山口。先主遥望遍野火光不绝，死尸重叠，塞江而下。次日，吴兵又四下放火烧山，军士乱窜，先主惊慌。忽然火光中一将引数骑杀上山来，视之，乃关兴也。兴伏地请曰：“四下火光逼近，不可久停。陛下速奔白帝城，再收军马可也。”先主曰：“谁敢断后？”傅彤奏曰：“臣愿以死当之！”当日黄昏，关兴在前，张苞在中，留傅彤断后，保着先主，杀下山来。吴兵见先主奔走，皆要争功，各引大军，遮天盖地，往西追赶，先主令军士尽脱袍铠，塞道而焚，以断后军。正奔走间，喊声大震，吴将朱然引一军从江岸边杀来，截住去路。先主叫曰：“朕死于此矣！”关兴、张苞纵马冲突，被乱箭射回，各带重伤，不能杀出。背后喊声又起，陆逊引大军从山谷中杀来。
先主正慌急之间，此时天色已微明，只见前面喊声震天，朱然军纷纷落涧，滚滚投岩：一彪军杀人，前来救驾。先主大喜，视之，乃常山赵子龙也。时赵云在川中江州，闻吴、蜀交兵，遂引军出；忽见东南一带火光冲天，云心惊，远远探视，不想先主被困，云奋勇冲杀而来。陆逊闻是赵云，急令军退。云正杀之间，忽遇朱然，便与交锋；不一合，一枪刺朱然于马下，杀散吴兵，救出先主，望白帝城而走。先主曰：“朕虽得脱，诸将士将奈何？”云曰：“敌军在后，不可久迟。陛下且入白帝城歇息，臣再引兵去救应诸将。”此时先主仅存百余人入白帝城。后人有诗赞陆逊曰：“持矛举火破连营，玄德穷奔白帝城。一旦威名惊蜀魏，吴王宁不敬书生。”
却说傅彤断后，被吴军八面围住。丁奉大叫曰：“川兵死者无数，降者极多，汝主刘备已被擒获，今汝力穷势孤，何不早降！”傅彤叱曰：“吾乃汉将，安肯降吴狗乎！”挺枪纵马，率蜀军奋力死战，不下百余合，往来冲突，不能得脱。彤长叹曰：“吾今休矣！”言讫，口中吐血，死于吴军之中。后人赞傅彤诗曰：“彝陵吴蜀大交兵，陆逊施谋用火焚。至死犹然骂“吴狗”，傅彤不愧汉将军。”
蜀祭酒程畿，匹马奔至江边，招呼水军赴敌，吴兵随后追来，水军四散奔逃。畿部将叫曰：“吴兵至矣！程祭酒快走罢！”畿怒曰：“吾自从主上出军，未尝赴敌而逃！”言未毕，吴兵骤至，四下无路，畿拔剑自刎。后人有诗赞曰：“慷慨蜀中程祭酒，身留一剑答君王。临危不改平生志，博得声名万古香。”时吴班、张南久围彝陵城，忽冯习到，言蜀兵败，遂引军来救先主，孙桓方才得脱。张、冯二将正行之间，前面吴兵杀来，背后孙桓从彝陵城杀出，两下夹攻。张南、冯习奋力冲突，不能得脱，死于乱军之中。后人有诗赞曰：“冯习忠无二，张南义少双。沙场甘战死，史册共流芳。”
吴班杀出重围，又遇吴兵追赶；幸得赵云接着，救回白帝城去了。时有蛮王沙摩柯，匹马奔走，正逢周泰，战二十余合，被泰所杀。蜀将杜路，刘宁尽皆降吴。蜀营一应粮草器仗，尺寸不存。蜀将川兵，降者无数。时孙夫人在吴，闻猇亭兵败，讹传先主死于军中，遂驱车至江边，望西遥哭，投江而死。后人立庙江滨，号曰枭姬祠。尚论者作诗叹之曰：“先主兵归白帝城，夫人闻难独捐生。至今江畔遗碑在，犹著千秋烈女名。”却说陆逊大获全功，引得胜之兵，往西追袭。前离夔关不远，逊在马上看见前面临山傍江，一阵杀气，冲天而起；遂勒马回顾众将曰：“前面必有埋伏，三军不可轻进。”即倒退十余里，于地势空阔处，排成阵势，以御敌军；即差哨马前去探视。回报并无军屯在此，逊不信，下马登高望之，杀气复起。逊再令人仔细探视，哨马回报，前面并无一人一骑。逊见日将西沉，杀气越加，心中犹豫，令心腹人再往探看。回报江边止有乱石八九十堆，并无人马。逊大疑，令寻土人问之。须臾，有数人到。逊问曰：“何人将乱石作堆？如何乱石堆中有杀气冲起？”土人曰：“此处地名鱼腹浦。诸葛亮入川之时，驱兵到此，取石排成阵势于沙滩之上。自此常常有气如云，从内而起。”陆逊听罢，上马引数十骑来看石阵，立马于山坡之上，但见四面八方，皆有门有户。逊笑曰：“此乃惑人之术耳，有何益焉！”遂引数骑下山坡来，直入石阵观看。部将曰：“日暮矣，请都督早回。”逊方欲出阵，忽然狂风大作，一霎时，飞沙走石，遮天盖地。但见怪石嵯峨，槎枒似剑；横沙立土，重叠如山；江声浪涌，有如剑鼓之声。逊大惊曰：“吾中诸葛之计也！”急欲回时，无路可出。正惊疑间，忽见一老人立于马前，笑曰：“将军欲出此阵乎？”逊曰：“愿长者引出。”老人策杖徐徐而行，径出石阵，并无所碍，送至山坡之上。逊问曰：“长者何人？”老人答曰：“老夫乃诸葛孔明之岳父黄承彦也。昔小婿入川之时，于此布下石阵，名‘八阵图’。反复八门，按遁甲休、生、伤、杜、景、死、惊、开。每日每时，化无端，可比十万精兵。临去之时，曾分付老夫道：后有东吴大将迷于阵中，莫要引他出来。老夫适于山岩之上，见将军从‘死门’而入，料想不识此阵，必为所迷。老夫平生好善，不忍将军陷没于此，故特自‘生门’引出也。”逊曰：“公曾学此阵法否？”黄承彦曰：“变化无穷，不能学也。”逊慌忙下马拜谢而回。后杜工部有诗曰：“功盖三分国，名成八阵图。江流石不转，遗恨失吞吴。”陆逊回寨，叹曰：“孔明真‘卧龙’也！吾不能及！”于是下令班师。左右曰：“刘备兵败势穷，困守一城，正好乘势击之；今见石阵而退，何也？”逊曰：“吾非惧石阵而退；吾料魏主曹丕，其奸诈与父无异，今知吾追赶蜀兵，必乘虚来袭。吾若深入西川，急难退矣。”遂令一将断后，逊率大军而回。退兵未及二日，三处人来飞报：“魏兵曹仁出濡须，曹休出洞口，曹真出南郡：三路兵马数十万，星夜至境，未知何意。”逊笑曰：“不出吾之所料。吾已令兵拒之矣。”正是：雄心方欲吞西蜀，胜算还须御北朝。
未知如何退兵，且看下文分解。', '', '', '', NULL, '', 'indent', 1536944510, '5b9b706f1b69e6005ba2cd26', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639226, '三国演义 · 第八十七回 · 征南寇丞相大兴师 抗天兵蛮王初受执', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说诸葛丞相在于成都，事无大小，皆亲自从公决断。两川之民，欣乐太平，夜不闭户，路不拾遗。又幸连年大熟，老幼鼓腹讴歌，凡遇差徭，争先早办。因此军需器械应用之物，无不完备；米满仓廒，财盈府库。
建兴三年，益州飞报：蛮王孟获，大起蛮兵十万，犯境侵掠。建宁太守雍闿，乃汉朝什方侯雍齿之后，今结连孟获造反。牂牁郡太守朱褒、越巂郡太守高定，二人献了城。止有永昌太守王伉不肯反。现今雍闿、朱褒、高定三人部下人马，皆与孟获为向导官，攻打永昌郡。今王伉与功曹吕凯，会集百姓，死守此城，其势甚急。孔明乃入朝奏后主曰：“臣观南蛮不服，实国家之大患也。臣当自领大军，前去征讨。”后主曰“东有孙权，北有曹丕，今相父弃朕而去，倘吴、魏来攻，如之奈何？”孔明曰：“东吴方与我国讲和，料无异心；若有异心，李严在白帝城，此人可当陆逊也。曹丕新败，锐气已丧，未能远图；且有马超守把汉中诸处关口，不必忧也。臣又留关兴、张苞等分两军为救应，保陛下万无一失。今臣先去扫荡蛮方，然后北伐，以图中原，报先帝三顾之恩，托孤之重。”后主曰：“朕年幼无知，惟相父斟酌行之。”言未毕，班部内一人出曰：“不可！不可！”众视之，乃南阳人也，姓王，名连，字文仪，现为谏议大夫。连谏曰：“南方不毛之地，瘴疫之乡；丞相秉钧衡之重任，而自远征，非所宜也。且雍闿等乃疥癣之疾，丞相只须遣一大将讨之，必然成功。”孔明曰：“南蛮之地，离国甚远，人多不习王化，收伏甚难，吾当亲去征之。可刚可柔，别有斟酌，非可容易托人。”
王连再三苦劝，孔明不从。是日，孔明辞了后主，令蒋琬为参军，费祎为长史，董厥、樊建二人为掾史；赵云、魏延为大将，总督军马；王平、张翼为副将；并川将数十员：共起川兵五十万，前望益州进发。忽有关公第三子关索，入军来见孔明曰：“自荆州失陷，逃难在鲍家庄养病。每要赴川见先帝报仇，疮痕未合，不能起行。近已安痊，打探得系吴仇人已皆诛戮，径来西川见帝，恰在途中遇见征南之兵，特来投见。”孔明闻之，嗟讶不已；一面遣人申报朝廷，就令关索为前部先锋，一同征南。大队人马，各依队伍而行。饥餐渴饮，夜住晓行；所经之处，秋毫无犯。
却说雍闿听知孔明自统大军而来，即与高定、朱褒商议，分兵三路：高定取中路，雍闿在左，朱褒在右；三路各引兵五六万迎敌。于是高定令鄂焕为前部先锋。焕身长九尺，面貌丑恶，使一枝方天戟，有万夫不当之勇：领本部兵，离了大寨，来迎蜀兵。却说孔明统大军已到益州界分。前部先锋魏延，副将张翼、王平，才入界口，正遇鄂焕军马。两阵对圆，魏延出马大骂曰：“反贼早早受降！”鄂焕拍马与魏延交锋。战不数合，延诈败走，焕随后赶来。走不数里，喊声大震。张翼、王平两路军杀来，绝其后路。延复回，三员将并力拒战，生擒鄂焕。解到大寨，入见孔明。孔明令去其缚，以酒食待之。问曰：“汝是何人部将？”焕曰：“某是高定部将。”孔明曰：“吾知高定乃忠义之士，今为雍闿所惑，以致如此。吾今放汝回去，令高太守早早归降，免遭大祸。”鄂焕拜谢而去，回见高定，说孔明之德。定亦感激不已。次日，雍闿至寨。礼毕，闿曰：“如何得鄂焕回也？”定曰：“诸葛亮以义放之。”闿曰：“此乃诸葛亮反间之计：欲令我两人不和，故施此谋也。”定半信不信，心中犹豫。忽报蜀将搦战，闿自引三万兵出迎。战不数合，闿拨马便走。延率兵大进，追杀二十余里。次日，雍闿又起兵来迎。孔明一连三日不出。至第四日，雍闿、高定分兵两路，来取蜀寨。却说孔明令魏延两路伺候；果然雍闿、高定两路兵来，被伏兵杀伤大半，生擒者无数，都解到大寨来。雍闿的人，囚在一边；高定的人，囚在一边。却令军士谣说：“但是高定的人免死，雍闿的人尽杀。”众军皆闻此言。少时，孔明令取雍闿的人到帐前，问曰：“汝等皆是何人部从？”众伪曰：“高定部下人也。”孔明教皆免其死，与酒食赏劳，令人送出界首，纵放回寨。孔明又唤高定的人问之。众皆告曰：“吾等实是高定部下军士。”孔明亦皆免其死，赐以酒食；却扬言曰：“雍闿今日使人投降，要献汝主并朱褒首级以为功劳，吾甚不忍。汝等既是高定部下军，吾放汝等回去，再不可背反。若再擒来，决不轻恕。”
众皆拜谢而去；回到本寨，入见高定，说知此事。定乃密遣人去雍闿寨中探听，却有一般放回的人，言说孔明之德；因此雍闿部军，多有归顺高定之心。虽然如此，高定心中不稳，又令一人来孔明寨中探听虚实。被伏路军捉来见孔明。孔明故意认做雍闿的人，唤入帐中问曰：“汝元帅既约下献高定、朱褒二人首级，因何误了日期？汝这厮不精细，如何做得细作！”军士含糊答应。孔明以酒食赐之，修密书一封，付军士曰：“汝持此书付雍闿，教他早早下手，休得误事。”细作拜谢而去，回见高定，呈上孔明之书，说雍闿如此如此。定看书毕，大怒曰：“吾以真心待之，彼反欲害吾，情理难容！”便唤鄂焕商议。焕曰：“孔明乃仁人，背之不祥。我等谋反作恶，皆雍闿之故；不如杀闿以投孔明。”定曰：“如何下手？”焕曰：“可设一席，令人去请雍闿。彼若无异心，必坦然而来；若其不来，必有异心。我主可攻其前，某伏于寨后小路候之；闿可擒矣。”高定从其言，设席请雍闿。闿果疑前日放回军士之言，惧而不来。是夜高定引兵杀投雍闿寨中。原来有孔明放回免死的人，皆想高定之德，乘时助战。雍闿军不战自乱。闿上马望山路而走。行不二里，鼓声响处，一彪军出，乃鄂焕也：挺方天戟，骤马当先。雍闿措手不及，被焕一戟刺于马下，就枭其首级。闿部下军士皆降高定。定引两部军来降孔明，献雍闿首级于帐下。孔明高坐于帐上，喝令左右推转高定，斩首报来。定曰：“某感丞相大恩，今将雍闿首级来降，何故斩也？”孔明大笑曰：“汝来诈降。敢瞒吾耶！”定曰：“丞相何以知吾诈降？”孔明于匣中取出一缄，与高定曰：“朱褒已使人密献降书，说你与雍闿结生死之交，岂肯一旦便杀此人？吾故知汝诈也。”定叫屈曰：“朱褒乃反间之计也。丞相切不可信！”孔明曰：“吾亦难凭一面之词。汝若捉得朱褒，方表真心。”定曰：“丞相休疑。某去擒朱褒来见丞相，若何？”孔明曰：“若如此，吾疑心方息也。”
高定即引部将鄂焕并本部兵，杀奔朱褒营来。比及离寨约有十里，山后一彪军到，乃朱褒也。褒见高定军来，慌忙与高定答话。定大骂曰：“汝如何写书与诸葛丞相处，使反间之计害吾耶？”褒目瞪口呆，不能回答。忽然鄂焕于马后转过，一戟刺朱褒于马下。定厉声而言曰：“如不顺者皆戮之！”于是众军一齐拜降。定引两部军来见孔明，献朱褒首级于帐下。孔明大笑曰：“吾故使汝杀此二贼，以表忠心。”遂命高定为益州太守，总摄三郡；令鄂焕为牙将。三路军马已平。
于是永昌太守王伉出城迎接孔明。孔明入城已毕，问曰：“谁与公守此城，以保无虞？”伉曰：“某今日得此郡无危者，皆赖永昌不韦人，姓吕，名凯，字季平。皆此人之力。”孔明遂请吕凯至。凯入见，礼毕。孔明曰：“久闻公乃永昌高士，多亏公保守此城。今欲平蛮方，公有何高见？”吕凯遂取一图，呈与孔明曰：“某自历仕以来，知南人欲反久矣，故密遣人入其境，察看可屯兵交战之处，画成一图，名曰《平蛮指掌图》。今敢献与明公。明公试观之，可为征蛮之一助也。”孔明大喜，就用吕凯为行军教授，兼向导官。于是孔明提兵大进，深入南蛮之境。正行军之次，忽报天子差使命至。孔明请入中军，但见一人素袍白衣而进，乃马谡也——为兄马良新亡，因此挂孝。——谡曰：“奉主上敕命，赐众军酒帛。”孔明接诏已毕，依命一一给散，遂留马谡在帐叙话。孔明问曰：“吾奉天子诏，削平蛮方；久闻幼常高见，望乞赐教。”谡曰：“愚有片言，望丞相察之；南蛮恃其地远山险，不服久矣；虽今日破之，明日复叛。丞相大军到彼，必然平服；但班师之日，必用北伐曹丕；蛮兵若知内虚，其反必速。夫用兵之道：攻心为上，攻城为下；心战为上，兵战为下。愿丞相但服其心足矣。”孔明叹曰：“幼常足知吾肺腑也！”于是孔明遂令马谡为参军，即统大兵前进。却说蛮王孟获，听知孔明智破雍闿等，遂聚三洞元帅商议。第一洞乃金环三结元帅，第二洞乃董荼那元帅，第三洞乃阿会喃元帅。三洞元帅入见孟获。获曰：“今诸葛丞相领大军来侵我境界，不得不并力敌之。汝三人可分兵三路而进。如得胜者，便为洞主。”于是分金环三结取中路，董荼那取左路，阿会喃取右路：各引五万蛮兵，依令而行。
却说孔明正在寨中议事，忽哨马飞报，说三洞元帅分兵三路到来。孔明听毕，即唤赵云、魏延至，却都不分付；更唤王平、马忠至，嘱之曰：“今蛮兵三路而来，吾欲令子龙、文长去；此二人不识地理，未敢用之。王平可往左路迎敌，马忠可往右路迎敌。吾却使子龙、文长随后接应。今日整顿军马，来日平明进发。”二人听令而去。又唤张嶷、张翼分付曰：“汝二人同领一军，往中路迎敌。今日整点军马，来日与王平、马忠约会而进。吾欲令子龙、文长去取，奈二人不识地理，故未敢用之。”张嶷、张翼听令去了。
赵云、魏延见孔明不用，各有愠色。孔明曰：“吾非不用汝二人，但恐以中年涉险，为蛮人所算，失其锐气耳。”赵云曰：“倘我等识地理，若何？”孔明曰：“汝二人只宜小心，休得妄动。”二人怏怏而退。赵云请魏延到自己寨内商议曰：“吾二人为先锋，却说不识地理而不肯用。今用此后辈，吾等岂不羞乎？”延曰：“吾二人只今就上马，亲去探之；捉住土人，便教引进，以敌蛮兵，大事可成。”云从之，遂上马径取中路而来。方行不数里，远远望见尘头大起。二人上山坡看时，果见数十骑蛮兵，纵马而来。二人两路冲出。蛮兵见了，大惊而走。赵云、魏延各生擒几人，回到本寨，以酒食待之，却细问其故。蛮兵告曰：“前面是金环三结元帅大寨，正在山口。寨边东西两路，却通五溪洞并董荼那、阿会喃各寨之后。”
赵云、魏延听知此话，遂点精兵五千，教擒来蛮兵引路。比及起军时，已是二更天气；月明星朗，趁着月色而行。刚到金环三结大寨之时，约有四更，蛮兵方起造饭，准备天明厮杀。忽然赵云、魏延两路杀入，蛮兵大乱。赵云直杀入中军，正逢金环三结元帅；交马只一合，被云一枪刺落马下，就枭其首级。余军溃散。魏延便分兵一半，望东路抄董荼那寨来。赵云分兵一半，望西路抄阿会喃寨来。比及杀到蛮兵大寨之时，天已平明。先说魏延杀奔董荼那寨来。董荼那听知寨后有军杀至，便引兵出寨拒敌。忽然寨前门一声喊起，蛮兵大乱。原来王平军马早已到了。两下夹攻，蛮兵大败。董荼那夺路走脱，魏延追赶不上。却说赵云引兵杀到阿会喃寨后之时，马忠已杀至寨前。两下夹攻，蛮兵大败，阿会喃乘乱走脱。各自收军，回见孔明。孔明问曰：“三洞蛮兵，走了两洞之主；金环三结元帅首级安在？”赵云将首级献功。众皆言曰：“董荼那、阿会喃皆弃马越岭而去，因此赶他不上。”孔明大笑曰：“二人吾已擒下了。”赵、魏二人并诸将皆不信。少顷，张嶷解董荼那到，张翼解阿会喃到。众皆惊讶。孔明曰：“吾观吕凯图本，已知他各人下的寨子，故以言激子龙、文长之锐气，故教深入重地，先破金环三结，随即分兵左右寨后抄出，以王平、马忠应之。非子龙、文长不可当此任也。吾料董荼那、阿会喃必从便径往山路而走，故遣张嶷、张翼以伏兵待之，令关索以兵接应，擒此二人。”诸将皆拜伏曰：“丞相机算，神鬼莫测！”
孔明令押过董荼那、阿会喃至帐下，尽去其缚，以酒食衣服赐之，令各自归洞，勿得助恶。二人泣拜，各投小路而去。孔明谓诸将曰：“来日孟获必然亲自引兵厮杀，便可就此擒之。”乃唤赵云、魏延至，付与计策，各引五千兵去了。又唤王平、关索同引一军，授计而去。孔明分拨已毕，坐于帐上待之。却说蛮王孟获在帐中正坐，忽哨马报来，说三洞元帅，俱被孔明捉将去了；部下之兵，各自溃散。获大怒，遂起蛮兵迤逦进发，正遇王平军马。两阵对圆，王平出马横刀望之：只见门旗开处，数百南蛮骑将两势摆开。中间孟获出马：头顶嵌宝紫金冠，身披缨络红锦袍，腰系碾玉狮子带，脚穿鹰嘴抹绿靴，骑一匹卷毛赤兔马，悬两口松纹镶宝剑，昂然观望，回顾左右蛮将曰：“人每说诸葛亮善能用兵；今观此阵，旌旗杂乱，队伍交错；刀枪器械，无一可能胜吾者：始知前日之言谬也。早知如此，吾反多时矣。谁敢去擒蜀将：以振军威？”言未尽，一将应声而出，名唤忙牙长；使一口截头大刀，骑一匹黄骠马，来取王平。二将交锋，战不数合，王平便走。孟获驱兵大进，迤逦追赶。关索略战又走，约退二十余里。孟获正追杀之间，忽然喊声大起，左有张嶷，右有张翼，两路兵杀出，截断归路。王平、关索复兵杀回。前后夹攻，蛮兵大败。孟获引部将死战得脱，望锦带山而逃。背后三路兵追杀将来。获正奔走之间，前面喊声大起，一彪军拦住：为首大将乃常山赵子龙也。获见了大惊，慌忙奔锦带山小路而走。子龙冲杀一阵，蛮兵大败，生擒者无数。孟获止与数十骑奔入山谷之中，背后追兵至近，前面路狭，马不能行，乃弃了马匹，爬山越岭而逃。忽然山谷中一声鼓响，乃是魏延受了孔明计策，引五百步军，伏于此处，孟获抵敌不住，被魏延生擒活捉了。从骑皆降。魏延解孟获到大寨来见孔明。孔明早已杀牛宰羊，设宴在寨；却教帐中排开七重围子手，刀枪剑戟，灿若霜雪；又执御赐黄金钺斧，曲柄伞盖，前后羽葆鼓吹，左右排开御林军，布列得十分严整。孔明端坐于帐上，只见蛮兵纷纷穰穰，解到无数。孔明唤到帐中，尽去其缚，抚谕曰：“汝等皆是好百姓，不幸被孟获所拘，今受惊唬。吾想汝等父母、兄弟、妻子必倚门而望；若听知阵败，定然割肚牵肠，眼中流血。吾今尽放汝等回去，以安各人父母、兄弟、妻子之心。”言讫，各赐酒食米粮而遣之。蛮兵深感其恩，泣拜而去。孔明教唤武士押过孟获来。不移时，前推后拥，缚至帐前。获跪与帐下。孔明曰：“先帝待汝不薄，汝何敢背反？”获曰：“两川之地，皆是他人所占土地，汝主倚强夺之，自称为帝。吾世居此处，汝等无礼，侵我土地：何为反耶？”孔明曰：“吾今擒汝，汝心服否？”获曰：“山僻路狭，误遭汝手，如何肯服！”孔明曰：“汝既不服，吾放汝去，若何？”获曰：“汝放我回去，再整军马，共决雌雄；若能再擒吾，吾方服也。”孔明即令去其缚。与衣服穿了，赐以酒食，给与鞍马，差人送出路，径望本寨而去。正是：寇入掌中还放去，人居化外未能降。
未知再来交战若何，且看下文分解。', '', '', '', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f7d5914587d02f66f03", "shortContent": "这篇故事写张闿因做了好事，故而得到鬼役的相助，不但免于一死，而且后来还做了大官，集富贵寿考于一身。不用说，写这一故事的目的无非是宣扬因果报应思想，这种思想在古代志怪小说中是大量存在的。\n但是，也许作者自己没有意识到，这一故事在宣扬“善有善报”的同时，实际上也在宣扬“做了坏事得善报”。张闿因做过好事而得到鬼役的敬重，特“亏法以相济”，而“亏法”的结果则是“嫁祸于人”。虽说主意为鬼役所出，但替死的对象...", "authors": ["范民声"], "pressName": "上海辞书出版社"}]', '', 'indent', 1536944221, '5b9b72f8fb4ffe005cb029d7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639227, '三国演义 · 第八十八回 · 渡泸水再缚番王 识诈降三擒孟获', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说孔明放了孟获，众将上帐问曰：“孟获乃南蛮渠魁，今幸被擒，南方便定；丞相何故放之？”孔明笑曰：“吾擒此人，如囊中取物耳。直须降伏其心，自然平矣。”诸将闻言，皆未肯信。当日孟获行至泸水，正遇手下败残的蛮兵，皆来寻探。众兵见了孟获，且惊且喜，拜问曰：“大王如何能勾回来？”获曰：“蜀人监我在帐中，被我杀死十余人，乘夜黑而走；正行间，逢着一哨马军，亦被我杀之，夺了此马：因此得脱。”众皆大喜，拥孟获渡了泸水，下住寨栅，会集各洞酋长，陆续招聚原放回的蛮兵，约有十余万骑。此时董荼那、阿会喃已在洞中。孟获使人去请，二人惧怕，只得也引洞兵来。获传令曰：“吾已知诸葛亮之计矣，不可与战，战则中他诡计。彼川兵远来劳苦，况即日天炎，彼兵岂能久住？吾等有此泸水之险，将船筏尽拘在南岸，一带皆筑土城，深沟高垒，看诸葛亮如何施谋！”众酋长从其计，尽拘船筏于南岸，一带筑起土城：有依山傍崖之地，高竖敌楼；楼上多设弓弩炮石，准备久处之计。粮草皆是各洞供运。孟获以为万全之策，坦然不忧。却说孔明提兵大进，前军已至泸水，哨马飞报说：“泸水之内，并无船筏；又兼水势甚急，隔岸一带筑起土城，皆有蛮兵守把。”时值五月，天气炎热，南方之地，分外炎酷，军马衣甲，皆穿不得。孔明自至泸水边观毕，回到本寨，聚诸将至帐中，传令曰：“今孟获兵屯泸水之南，深沟高垒，以拒我兵；吾既提兵至此，如何空回？汝等各各引兵，依山傍树，拣林木茂盛之处，与我将息人马。”乃遣吕凯离泸水百里，拣阴凉之地，分作四个寨子；使王平、张嶷、张翼、关索各守一寨，内外皆搭草棚，遮盖马匹，将士乘凉，以避暑气。参军蒋琬看了，入问孔明曰：“某看吕凯所造之寨甚不好，正犯昔日先帝败于东吴时之地势矣，倘蛮兵偷渡泸水，前来劫寨，若用火攻，如何解救？”孔明笑曰：“公勿多疑，吾自有妙算。”蒋琬等皆不晓其意。忽报蜀中差马岱解暑药并粮米到。孔明令入。岱参拜毕，一面将米药分派四寨。孔明问曰：“汝将带多少军来？”马岱曰：“有三千军。”孔明曰：“吾军累战疲困，欲用汝军，未知肯向前否？”岱曰：“皆是朝廷军马，何分彼我？丞相要用，虽死不辞。”孔明曰：“今孟获拒住泸水，无路可渡。吾欲先断其粮道，令彼军自乱。”岱曰：“如何断得？”孔明曰：“离此一百五十里，泸水下流沙口，此处水慢，可以扎筏而渡。汝提本部三千军渡水，直入蛮洞，先断其粮，然后会合董荼那、阿会喃两个洞主，便为内应。不可有误。”
马岱欣然去了，领兵前到沙口，驱兵渡水；因见水浅，大半不下筏，只裸衣而过，半渡皆倒；急救傍岸，口鼻出血而死。马岱大惊，连夜回告孔明。孔明随唤向导土人问之。土人曰：“目今炎天，毒聚泸水，日间甚热，毒气正发，有人渡水，必中其毒；或饮此水，其人必死。若要渡时。须待夜静水冷，毒气不起，饱食渡之，方可无事。”孔明遂令土人引路，又选精壮军五六百，随着马岱，来到泸水沙口，扎起木筏，半夜渡水，果然无事，岱领着二千壮军，令土人引路，径取蛮洞运粮总路口夹山峪而来。那夹山峪，两下是山，中间一条路，止容一人一马而过。马岱占了夹山峪，分拨军士，立起寨栅。洞蛮不知，正解粮到，被岱前后截住，夺粮百余车，蛮人报入孟获大寨中。此时孟获在寨中，终日饮酒取乐，不理军务，谓众酋长曰：“吾若与诸葛亮对敌，必中奸计。今靠此泸水之险，深沟高垒以待之；蜀人受不过酷热，必然退走。那时吾与汝等随后击之，便可擒诸葛亮也。”言讫，呵呵大笑。忽然班内一酋长曰：“沙口水浅，倘蜀兵透漏过来，深为利害；当分军守把。”获笑曰：“汝是本处土人，如何不知？吾正要蜀兵来渡此水，渡则必死于水中矣。”酋长又曰：“倘有土人说与夜渡之法，当复何如？”获曰：“不必多疑。吾境内之人，安肯助敌人耶？”正言之间，忽报蜀兵不知多少，暗渡泸水，绝断了夹山粮道，打着“平北将军马岱”旗号。获笑曰：“量此小辈，何足道哉！”即遣副将忙牙长，引三千兵投夹山峪来。
却说马岱望见蛮兵已到，遂将二千军摆在山前。两阵对圆，忙牙长出马，与马岱交锋，只一合，被岱一刀，斩于马下。蛮兵大败走回，来见孟获，细言其事。获唤诸将问曰：“谁敢去敌马岱？”言未毕，董荼那出曰：“某愿往。”孟获大喜，遂与三千兵而去。获又恐有人再渡泸水，即遣阿会喃，引三千兵，去守把沙口。却说董荼那引蛮兵到了夹山峪下寨，马岱引兵来迎。部内军有认得是董荼那，说与马岱如此如此。岱纵马向前大骂曰：“无义背恩之徒！吾丞相饶汝性命，今又背反，岂不自羞！”董荼那满面惭愧，无言可答，不战而退。马岱掩杀一阵而回。董荼那回见孟获曰：“马岱英雄，抵敌不住。”获大怒曰：“吾知汝原受诸葛亮之恩，今故不战而退，正是卖阵之计！”喝教推出斩了。众酋长再三哀告，方才免死，叱武士将董荼那打了一百大棍，放归本寨。诸多酋长皆来告董荼那曰：“我等虽居蛮方，未尝敢犯中国；中国亦不曾侵我。今因孟获势力相逼，不得已而造反。想孔明神机莫测，曹操、孙权尚自惧之，何况我等蛮方乎？况我等皆受其活命之恩，无可为报。今欲舍一死命，杀孟获去投孔明，以免洞中百姓涂炭之苦。”董荼那曰：“未知汝等心下若何？”内有原蒙孔明放回的人，一齐同声应曰：“愿往！”于是董荼那手执钢刀，引百余人，直奔大寨而来，时孟获大醉于帐中。董荼那引众人持刀而入，帐下有两将侍立。董荼那以刀指曰：“汝等亦受诸葛丞相活命之恩，宜当报效。”二将曰：“不须将军下手，某当生擒孟获，去献丞相。”于是一齐入帐，将孟获执缚已定，押到泸水边，驾船直过北岸，先使人报知孔明。
却说孔明已有细作探知此事，于是密传号令，教各寨将士，整顿军器，方教为首酋长解孟获入来，其余皆回本寨听候。董荼那先入中军见孔明，细说其事。孔明重加赏劳，用好言抚慰，遣董荼那引众酋长去了，然后令刀斧手推孟获入。孔明笑曰：“汝前者有言：但再擒得，便肯降服。今日如何？”获曰：“此非汝之能也；乃吾手下之人自相残害，以致如此。如何肯服！”孔明曰：“吾今再放汝去，若何？”孟获曰：“吾虽蛮人，颇知兵法；若丞相端的肯放吾回洞中，吾当率兵再决胜负。若丞相这番再擒得我，那时倾心吐胆归降，并不敢改移也。”孔明曰：“这番生擒，如又不服，必无轻恕。”令左右去其绳索，仍前赐以酒食，列坐于帐上。孔明曰：“吾自出茅庐，战无不胜，攻无不取。汝蛮邦之人，何为不服？”获默然不答。孔明酒后，唤孟获同上马出寨，观看诸营寨栅所屯粮草，所积军器。孔明指谓孟获曰：“汝不降吾，真愚人也。吾有如此之精兵猛将，粮草兵器，汝安能胜吾哉？汝若早降，吾当奏闻天子，令汝不失王位，子子孙孙，永镇蛮邦。意下若何？”获曰：“某虽肯降，怎奈洞中之人未肯心服。若丞相肯放回去，就当招安本部人马，同心合胆，方可归顺。”孔明欣然，又与孟获回到大寨。饮酒至晚，获辞去；孔明亲自送至泸水边，以船送获归寨。孟获来到本寨，先伏刀斧手于帐下，差心腹人到董荼那、阿会喃寨中，只推孔明有使命至，将二人赚到大寨帐下，尽皆杀之，弃尸于涧。孟获随即遣亲信之人，守把隘口，自引军出了夹山峪，要与马岱交战，却并不见一人；及问土人，皆言昨夜尽搬粮草，复渡泸水，归大寨去了。获再回洞中，与亲弟孟优商议曰：“如今诸葛亮之虚实，吾已尽知，汝可去如此如此。”孟优领了兄计，引百余蛮兵，搬载金珠、宝贝、象牙、犀角之类，渡了泸水，径投孔明大寨而来；方才过了河时，前面鼓角齐鸣，一彪军摆开：为首大将乃马岱也。孟优大惊。岱问了来情，令在外厢，差人来报孔明。孔明正在帐中与马谡、吕凯、蒋琬、费祎等共议平蛮之事，忽帐下一人，报称孟获差弟孟优来进宝贝。孔明回顾马谡曰：“汝知其来意否？”谡曰：“不敢明言。容某暗写于纸上，呈与丞相，看合钧意否？”孔明从之。马谡写讫，呈与孔明。孔明看毕，抚掌大笑曰：“擒孟获之计，吾已差派下也。汝之所见，正与吾同。”遂唤赵云入，向耳畔分付如此如此；又唤魏延入，亦低言分付；又唤王平、马忠、关索入，亦密密地分付。
各人受了计策，皆依令而去，方召孟优入帐，优再拜于帐下曰：“家兄孟获，感丞相活命之恩，无可奉献，辄具金珠宝贝若干，权为赏军之资。续后别有进贡天子礼物。”孔明曰：“汝兄今在何处？”优曰：“为感丞相天恩，径往银坑山中收拾宝物去了，少时便回来也。”孔明曰：“汝带多少人来？”优曰：“不敢多带。只是随行百余人，皆运货物者。”孔明尽教入帐看时，皆是青眼黑面，黄发紫须，耳带金环，蓬头跣足，身长力大之士。孔明就令随席而坐，教诸将劝酒，殷勤相待。
却说孟获在帐中专望回音，忽报有二人回了；唤入问之，具说：“诸葛亮受了礼物大喜，将随行之人，皆唤入帐中，杀牛宰羊，设宴相待。二大王令某密报大王：今夜二更，里应外合，以成大事。”孟获听知甚喜，即点起三万蛮兵，分为三队。获唤各洞酋长分付曰：“各军尽带火具。今晚到了蜀寨时，放火为号。吾当自取中军，以擒诸葛亮。”诸多蛮将，受了计策，黄昏左侧，各渡泸水而来。孟获带领心腹蛮将百余人，径投孔明大寨，于路并无一军阻当。前至寨门，获率众将骤马而入，乃是空寨，并不见一人。获撞入中军，只见帐中灯烛荧煌，孟优并番兵尽皆醉倒。原来孟优被孔明教马谡、吕凯二人管待，令乐人搬做杂剧，殷勤劝酒，酒内下药，尽皆昏倒，浑如醉死之人。孟获入帐问之，内有醒者，但指口而已。获知中计，急救了孟优等一干人；却待奔回中队，前面喊声大震，火光骤起，蛮兵各自逃窜。一彪军杀到，乃是蜀将王平。获大惊，急奔左队时，火光冲天，一彪军杀到，为首蜀将乃是魏延。获慌忙望右队而来，只见火光又起，又一彪军杀到，为首蜀将乃是赵云。三路军夹攻将来，四下无路。孟获弃了军士，匹马望泸水而逃。正见泸水上数十个蛮兵，驾一小舟，获慌令近岸。人马方才下船，一声号起，将孟获缚住。原来马岱受了计策，引本部兵扮作蛮兵，撑船在此，诱擒孟获。
于是孔明招安蛮兵，降者无数。孔明一一抚慰，并不加害。就教救灭了余火。须臾，马岱擒孟获至；赵云擒孟优至；魏延、马忠、王平、关索擒诸洞酋长至。孔明指孟获而笑曰：“汝先令汝弟以礼诈降，如何瞒得过吾！今番又被我擒，汝可服否？”获曰：“此乃吾弟贪口腹之故，误中汝毒，因此失了大事。吾若自来，弟以兵应之，必然成功。此乃天败，非吾之不能也，如何肯服！”孔明曰：“今已三次，如何不服？”孟获低头无语。孔明笑曰：“吾再放汝回去。”孟获曰：“丞相若肯放吾兄弟回去，收拾家下亲丁，和丞相大战一场。那时擒得，方才死心塌地而降。”孔明曰：“再若擒住，必不轻恕。汝可小心在意，勤攻韬略之书，再整亲信之士，早用良策，勿生后悔。”遂令武士去其绳索，放起孟获，并孟优及各洞酋长，一齐都放。孟获等拜谢去了。此时蜀兵已渡泸水。孟获等过了泸水，只见岸口陈兵列将，旗帜纷纷。获到营前，马岱高坐，以剑指之曰：“这番拿住，必无轻放！”孟获到了自己寨时，赵云早已袭了此寨，布列兵马。云坐于大旗下，按剑而言曰：“丞相如此相待，休忘大恩！”获喏喏连声而去。将出界口山坡，魏延引一千精兵，摆在坡上，勒马厉声而言曰：“吾今已深入巢穴，夺汝险要；汝尚自愚迷，抗拒大军！这回拿住，碎尸万段，决不轻饶！”孟获等抱头鼠窜，望本洞而去。后人有诗赞曰：“五月驱兵入不毛，月明泸水瘴烟高。誓将雄略酬三顾，岂惮征蛮七纵劳。”
却说孔明渡了泸水，下寨已毕，大赏三军，聚众将于帐下曰：“孟获第二番擒来，吾令遍观各营虚实，正欲令其来劫营也。吾知孟获颇晓兵法，吾以兵马粮草炫耀，实令孟获看吾破绽，必用火攻。彼令其弟诈降，欲为内应耳。吾三番擒之而不杀，诚欲服其心，不欲灭其类也。吾今明告汝等，勿得辞劳，可用心报国。”众将拜伏曰：“丞相智、仁、勇三者足备，虽子牙、张良不能及也。”孔明曰：“吾今安敢望古人耶？皆赖汝等之力，共成功业耳。”帐下诸将听得孔明之言，尽皆喜悦。却说孟获受了三擒之气，忿忿归到银坑洞中，即差心腹人赍金珠宝贝，往八番九十三甸等处，并蛮方部落，借使牌刀獠丁军健数十万，克日齐备，各队人马，云推雾拥，俱听孟获调用。伏路军探知其事，来报孔明，孔明笑曰：“吾正欲令蛮兵皆至，见吾之能也。”遂上小车而行。正是：若非洞主威风猛，怎显军师手段高！
未知胜负如何，且看下文分解。', '', '', '', '[{"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42b4d635634aee3f827c", "shortContent": "这是明代讲史小说《杨家府演义》第五卷的第一回。《杨家府演义》全名《杨家府忠勇通俗演义》，叙北宋杨业一家五代为保卫大宋江山，抗击辽及西夏的入侵，前仆后继，英勇牺牲的故事。杨业是历史人物，北宋名将，《宋史》中有传，所以一般以这本《演义》为历史小说；但它的虚构成分比《三国演义》更多了许多，所以有的文学史家以之入英雄传奇类，也有一定道理。\n《杨家府演义》虽然有一些史传作依据，但主要是在宋元民间传说、话本、...", "authors": ["姚品文"], "pressName": "上海辞书出版社"}]', '', 'indent', 1536944089, '5b9b7313fb4ffe005cb02af0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639228, '三国演义 · 第八十九回 · 武乡侯四番用计 南蛮王五次遭擒', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说孔明自驾小车，引数百骑前来探路。前有一河，名曰西洱河，水势虽慢，并无一只船筏。孔明令伐木为筏而渡，其木到水皆沉。孔明遂问吕凯，凯曰：“闻西洱河上流有一山，其山多竹，大者数围。可令人伐之，于河上搭起竹桥，以渡军马。”孔明即调三万人入山，伐竹数十万根，顺水放下，于河面狭处，搭起竹桥，阔十余丈。乃调大军于河北岸一字儿下寨，便以河为壕堑，以浮桥为门，垒土为城；过桥南岸，一字下三个大营，以待蛮兵。
却说孟获引数十万蛮兵，恨怒而来。将近西洱河，孟获引前部一万刀牌獠丁，直扣前寨搦战。孔明头戴纶巾，身披鹤氅，手执羽扇，乘驷马车，左右众将簇拥而出。孔明见孟获身穿犀皮甲，头顶朱红盔，左手挽牌，右手执刀，骑赤毛牛，口中辱骂；手下万余洞丁，各舞刀牌，往来冲突。孔明急令退回本寨，四面紧闭，不许出战。蛮兵皆裸衣赤身，直到寨门前叫骂。诸将大怒，皆来禀孔明曰：“某等情愿出寨决一死战！”孔明不许。诸将再三欲战，孔明止曰：“蛮方之人，不遵王化，今此一来，狂恶正盛，不可迎也；且宜坚守数日，待其猖獗少懈，吾自有妙计破之。”
于是蜀兵坚守数日。孔明在高阜处探之，窥见蛮兵已多懈怠，乃聚诸将曰：“汝等敢出战否？”众将欣然要出。孔明先唤赵云、魏延入帐，向耳畔低言，分付如此如此。二人受了计策先进。却唤王平、马忠入帐，受计去了。又唤马岱分付曰：“吾今弃此三寨，退过河北；吾军一退，汝可便拆浮桥，移于下流，却渡赵云、魏延军马过河来接应。”岱受计而去。又唤张翼曰：“吾军退去，寨中多设灯火。孟获知之，必来追赶，汝却断其后。”张翼受计而退。孔明只教关索护车。众军退去，寨中多设灯火。蛮兵望见，不敢冲突。
次日平明，孟获引大队蛮兵径到蜀寨之时，只见三个大寨，皆无人马，于内弃下粮草车仗数百余辆。孟优曰：“诸葛弃寨而走，莫非有计否？”孟获曰：“吾料诸葛亮弃辎重而去，必因国中有紧急之事：若非吴侵，定是魏伐。故虚张灯火以为疑兵，弃车仗而去也。可速追之，不可错过。”于是孟获自驱前部，直到西洱河边。望见河北岸上，寨中旗帜整齐如故，灿若云锦；沿河一带，又设锦城。蛮兵哨见，皆不敢进。获谓优曰：“此是诸葛亮惧吾追赶，故就河北岸少住，不二日必走矣。”遂将蛮兵屯于河岸；又使人去山上砍竹为筏，以备渡河；却将敢战之兵，皆移于寨前面。却不知蜀兵早已入自己之境。是日，狂风大起。四壁厢火明鼓响，蜀兵杀到。蛮兵獠丁，自相冲突，孟获大惊，急引宗族洞丁杀开条路，径奔旧寨。忽一彪军从寨中杀出，乃是赵云。获慌忙回西洱河，望山僻处而走。又一彪军杀出，乃是马岱。孟获只剩得数十个败残兵，望山谷中而逃。见南、北、西三处尘头火光，因此不敢前进，只得望东奔走，方才转过山口，见一大林之前，数十从人，引一辆小车；车上端坐孔明，呵呵大笑曰：“蛮王孟获！天败至此，吾已等候多时也！”获大怒，回顾左右曰：“吾遭此人诡计！受辱三次；今幸得这里相遇。汝等奋力前去，连人带车砍为粉碎！”数骑蛮兵，猛力向前。孟获当先呐喊，抢到大林之前，趷踏一声，踏了陷坑，一齐塌倒。大林之内，转出魏延，引数百军来，一个个拖出，用索缚定。孔明先到寨中，招安蛮兵，并诸甸酋长洞丁——此时大半皆归本乡去了——除死伤外，其余尽皆归降。孔明以酒肉相待，以好言抚慰，尽令放回。蛮兵皆感叹而去。少顷，张翼解孟优至。孔明诲之曰：“汝兄愚迷，汝当谏之。今被吾擒了四番，有何面目再见人耶！”孟优羞惭满面。伏地告求免死。孔明曰：“吾杀汝不在今日。吾且饶汝性命，劝谕汝兄。”令武士解其绳索，放起孟优。优泣拜而去。不一时，魏延解孟获至。孔明大怒曰：“你今番又被吾擒了，有何理说！”获曰：“吾今误中诡计，死不瞑目！”孔明叱武士推出斩之。获全无惧色，回顾孔明曰：“若敢再放吾回去，必然报四番之恨！”孔明大笑，令左右去其缚，赐酒压惊，就坐于帐中。孔明问曰：“吾今四次以礼相待，汝尚然不服，何也？”获曰：“吾虽是化外之人，不似丞相专施诡计，吾如何肯服？”孔明曰：“吾再放汝回去，复能战乎？”获曰：“丞相若再拿住吾，吾那时倾心降服，尽献本洞之物犒军，誓不反乱。”孔明即笑而遣之。获欣然拜谢而去。于是聚得诸洞壮丁数千人，望南迤逦而行。早望见尘头起处，一队兵到；乃是兄弟孟优，重整残兵，来与兄报仇。兄弟二人，抱头相哭，诉说前事。优曰：“我兵屡败，蜀兵屡胜，难以抵当。只可就山阴洞中，退避不出。蜀兵受不过暑气，自然退矣。”获问曰：“何处可避？”优曰：“此去西南有一洞，名曰秃龙洞。洞主朵思大王，与弟甚厚，可投之。”于是孟获先教孟优到秃龙洞，见了朵思大王。朵思慌引洞兵出迎，孟获入洞，礼毕，诉说前事。朵思曰：“大王宽心。若蜀兵到来，令他一人一骑不得还乡，与诸葛亮皆死于此处！”获大喜，问计于朵思。朵思曰：“此洞中止有两条路：东北上一路，就是大王所来之路，地势平坦，土厚水甜，人马可行；若以木石垒断洞口，虽有百万之众，不能进也。西北上有一条路，山险岭恶，道路窄狭；其中虽有小路，多藏毒蛇恶蝎；黄昏时分，烟瘴大起，直至巳，午时方收，惟未、申、酉三时，可以往来；水不可饮，人马难行。此处更有四个毒泉：一名哑泉，其水颇甜，人若饮之，则不能言，不过旬日必死；二曰灭泉，此水与汤无异，人若沐浴，则皮肉皆烂，见骨必死；三曰黑泉，其水微清，人若溅之在身，则手足皆黑而死；四曰柔泉，其水如冰，人若饮之，咽喉无暖气，身躯软弱如绵而死。此处虫鸟皆无，惟有汉伏波将军曾到；自此以后，更无一人到此。今垒断东北大路，令大王稳居敝洞，若蜀兵见东路截断，必从西路而入；于路无水，若见此四泉，定然饮水，虽百万之众，皆无归矣。何用刀兵耶！”孟获大喜，以手加额曰：“今日方有容身之地！”又望北指曰：“任诸葛神机妙算，难以施设！四泉之水，足以报败兵之恨也！”自此，孟获、孟优终日与朵思大王筵宴。
却说孔明连日不见孟获兵出，遂传号令教大军离西洱河，望南进发。此时正当六月炎天，其热如火。有后人咏南方苦热诗曰：“山泽欲焦枯，火光覆太虚。不知天地外，暑气更何如！”又有诗曰：“赤帝施权柄，阴云不敢生。云蒸孤鹤喘，海热巨鳌惊。忍舍溪边坐？慵抛竹里行。如何沙塞客，擐甲复长征！”孔明统领大军，正行之际，忽哨马飞报：“孟获退往秃龙洞中不出，将洞口要路垒断，内有兵把守；山恶岭峻，不能前进。”孔明请吕凯问之，凯曰：“某曾闻此洞有条路，实不知详细。”蒋琬曰：“孟获四次遭擒，既已丧胆，安敢再出？况今天气炎热，军马疲乏，征之无益；不如班师回国。”孔明曰：“若如此，正中孟获之计也。吾军一退，彼必乘势追之。今已到此，安有复回之理！”遂令王平领数百军为前部；却教新降蛮兵引路，寻西北小径而入。前到一泉，人马皆渴，争饮此水。王平探有此路，回报孔明。比及到大寨之时，皆不能言，但指口而已。孔明大惊，知是中毒，遂自驾小车，引数十人前来看时，见一潭清水，深不见底，水气凛凛，军不敢试。孔明下车，登高望之，四壁峰岭，鸟雀不闻，心中大疑。忽望见远远山冈之上，有一古庙。孔明攀藤附葛而到，见一石屋之中，塑一将军端坐，旁有石碑，乃汉伏波将军马援之庙：因平蛮到此，土人立庙祀之。孔明再拜曰：“亮受先帝托孤之重，今承圣旨，到此平蛮；欲待蛮方既平，然后伐魏吞吴，重安汉室。今军士不识地理，误饮毒水，不能出声。万望尊神，念本朝恩义，通灵显圣，护佑三军！”祈祷已毕，出庙寻土人问之。隐隐望见对山一老叟扶杖而来，形容甚异。孔明请老叟入庙，礼毕，对坐于石上。孔明问曰：“丈者高姓？”老叟曰：“老夫久闻大国丞相隆名，幸得拜见。蛮方之人，多蒙丞相活命，皆感恩不浅。”孔明问泉水之故，老叟答曰：“军所饮水，乃哑泉之水也，饮之难言，数日而死。此泉之外，又有三泉：东南有一泉，其水至冷，人若饮之，咽喉无暖气，身躯软弱而死，名曰柔泉；正南有一泉，人若溅之在身，手足皆黑而死，名曰黑泉；西南有一泉，沸如热汤，人若浴之，皮肉尽脱而死，名曰灭泉。敝处有此四泉，毒气所聚，无药可治，又烟瘴甚起，惟未、申、酉三个时辰可往来；余者时辰，皆瘴气密布，触之即死。”
孔明曰：“如此则蛮方不可平矣。蛮方不平，安能并吞吴、魏，再兴汉室？有负先帝托孤之重，生不如死也！”老叟曰：“丞相勿忧。老夫指引一处，可以解之。”孔明曰：“老丈有何高见，望乞指教。”老叟曰：“此去正西数里，有一山谷，入内行二十里，有一溪名曰万安溪。上有一高士，号为万安隐者；此人不出溪有数十余年矣。其草庵后有一泉，名安乐泉。人若中毒，汲其水饮之即愈。有人或生疥癞，或感瘴气，于万安溪内浴之，自然无事，更兼庵前有一等草，名曰薤叶芸香。人若口含一叶，则瘴气不染。丞相可速往求之。”孔明拜谢，问曰：“承丈者如此活命之德，感刻不胜。愿闻高姓。”老叟入庙曰：“吾乃本处山神，奉伏波将军之命，特来指引。”言讫、喝开庙后石壁而入。孔明惊讶不已，再拜庙神，寻旧路上车，回到大寨。次日，孔明备信香、礼物，引王平及众哑军，连夜望山神所言去处，迤逦而进。入山谷小径，约行二十余里，但见长松大柏，茂竹奇花，环绕一庄；篱落之中，有数间茅屋，闻得馨香喷鼻。孔明大喜，到庄前扣户，有一小童出。孔明方欲通姓名，早有一人，竹冠草履，白袍皂绦，碧眼黄发，欣然出曰：“来者莫非汉丞相否？”孔明笑曰：“高士何以知之？”隐者曰：“久闻丞相大纛南征，安得不知！”遂邀孔明入草堂。礼毕，分宾主坐定。孔明告曰：“亮受昭烈皇帝托孤之重，今承嗣君圣旨，领大军至此，欲服蛮邦，使归王化。不期孟获潜入洞中，军士误饮哑泉之水。夜来蒙伏波将军显圣，言高士有药泉，可以治之。望乞矜念，赐神水以救众兵残生。”隐者曰：“量老夫山野废人，何劳丞相枉驾。此泉就在庵后。”教取来饮。于是童子引王平等一起哑军，来到溪边，汲水饮之；随即吐出恶涎，便能言语。童子又引众军到万安溪中沐浴。
隐者于庵中进柏子茶、松花菜，以待孔明。隐者告曰：“此间蛮洞多毒蛇恶蝎，柳花飘入溪泉之间，水不可饮；但掘地为泉，汲水饮之方可。”孔明求“薤叶芸香”，隐者令众军尽意采取：“各人口含一叶，自然瘴气不侵。”孔明拜求隐者姓名，隐者笑曰：“某乃孟获之兄孟节是也。”孔明愕然。隐者又曰：“丞相休疑，容伸片言：某一父母所生三人：长即老夫孟节，次孟获，又次孟优。父母皆亡。二弟强恶，不归王化。某屡谏不从，故更名改姓，隐居于此。今辱弟造反，又劳丞相深入不毛之地，如此生受，孟节合该万死，故先于丞相之前请罪。”孔明叹曰：“方信盗跖、下惠之事，今亦有之。”遂与孟节曰：“吾申奏天子，立公为王，可乎？”节曰：“为嫌功名而逃于此，岂复有贪富贵之意！”孔明乃具金帛赠之。孟节坚辞不受。孔明嗟叹不已，拜别而回。后人有诗曰：“高士幽栖独闭关，武侯曾此破诸蛮。至今古木无人境，犹有寒烟锁旧山。”
孔明回到大寨之中，令军士掘地取水。掘下二十余丈，并无滴水；凡掘十余处，皆是如此。军心惊慌。孔明夜半焚香告天曰：“臣亮不才，仰承大汉之福，受命平蛮。今途中乏水，军马枯渴。倘上天不绝大汉，即赐甘泉！若气运已终，臣亮等愿死于此处！”是夜祝罢，平明视之，皆得满井甘泉。后人有诗曰：“为国平蛮统大兵，心存正道合神明。耿恭拜井甘泉出，诸葛虔诚水夜生。”孔明军马既得甘泉，遂安然由小径直入秃龙洞前下寨。蛮兵探知，来报孟获曰：“蜀兵不染瘴疫之气，又无枯渴之患，诸泉皆不应。”朵思大王闻知不信，自与孟获来高山望之。只见蜀兵安然无事，大桶小担，搬运水浆，饮马造饭。朵思见之，毛发耸然，回顾孟获曰：“此乃神兵也！”获曰：“吾兄弟二人与蜀兵决一死战，就殒于军前，安肯束手受缚！”朵思曰：“若大王兵败，吾妻子亦休矣。当杀牛宰马，大赏洞丁，不避水火，直冲蜀寨，方可得胜。”于是大赏蛮兵。
正欲起程，忽报洞后迤西银冶洞二十一洞主杨锋引三万兵来助战。孟获大喜曰：“邻兵助我，我必胜矣！”即与朵思大王出洞迎接。杨锋引兵入曰：“吾有精兵三万，皆披铁甲，能飞山越岭，足以敌蜀兵百万；我有五子，皆武艺足备。愿助大王。”锋令五子入拜，皆彪躯虎体，威风抖擞。孟获大喜，遂设席相待杨锋父子。酒至半酣，锋曰：“军中少乐，吾随军有蛮姑，善舞刀牌，以助一笑。”获欣然从之。须臾，数十蛮姑，皆披发跣足，从帐外舞跳而入，群蛮拍手以歌和之。杨锋令二子把盏。二子举杯诣孟获、孟优前。二人接杯，方欲饮酒，锋大喝一声，二子早将孟获、孟优执下座来。朵思大王却待要走，已被杨锋擒了。蛮姑横截于帐上，谁敢近前。获曰：“‘兔死狐悲，物伤其类’。吾与汝皆是各洞之主，往日无冤，何故害我？”锋曰：“吾兄弟子侄皆感诸葛丞相活命之恩，无可以报。今汝反叛，何不擒献！”
于是各洞蛮兵，皆走回本乡。杨锋将孟获、孟优、朵思等解赴孔明寨来。孔明令入，杨锋等拜于帐下曰：“某等子侄皆感丞相恩德，故擒孟获、孟优等呈献。”孔明重赏之，令驱孟获入。孔明笑曰：“汝今番心服乎？”获曰：“非汝之能，乃吾洞中之人，自相残害，以致如此。要杀便杀，只是不服！”孔明曰：“汝赚吾入无水之地，更以哑泉、灭泉、黑泉、柔泉如此之毒，吾军无恙，岂非天意乎？汝何如此执迷？”获又曰：“吾祖居银坑山中，有三江之险，重关之固。汝若就彼擒之，吾当子子孙孙，倾心服事。”孔明曰：“吾再放汝回去，重整兵马，与吾共决胜负；如那时擒住，汝再不服，当灭九族。”叱左右去其缚，放起孟获。获再拜而去。孔明又将孟优并朵思大王皆释其缚，赐酒食压惊。二人悚惧，不敢正视。孔明令鞍马送回。正是：深临险地非容易，更展奇谋岂偶然！
未知孟获整兵再来，胜负如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943876, '5b9b7329808ca43cd222ca17', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639229, '三国演义 · 第九十回 · 驱巨善六破蛮兵 烧藤甲七擒孟获', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说孔明放了孟获等一干人，杨锋父子皆封官爵，重赏洞兵。杨锋等拜谢而去。孟获等连夜奔回银坑洞。那洞外有三江：乃是泸水、甘南水、西城水。三路水会合，故为三江。其洞北近平坦三百余里，多产万物。洞西二百里，有盐井。西南二百里，直抵泸、甘。正南三百里，乃是梁都洞，洞中有山，环抱其洞；山上出银矿，故名为银坑山。山中置宫殿楼台，以为蛮王巢穴。其中建一祖庙，名曰“家鬼”。四时杀牛宰马享祭，名为“卜鬼”。每年常以蜀人并外乡之人祭之。若人患病，不肯服药，只祷师巫，名为“药鬼”。其处无刑法，但犯罪即斩。有女长成，却于溪中沐浴，男女自相混淆，任其自配，父母不禁，名为“学艺”。年岁雨水均调，则种稻谷；倘若不熟，杀蛇为羹，煮象为饭。每方隅之中，上户号曰“洞主”，次曰“酋长”。每月初一、十五两日，皆在三江城中买卖，转易货物。其风俗如此。
却说孟获在洞中，聚集宗党千余人，谓之曰：“吾屡受辱于蜀兵，立誓欲报之。汝等有何高见？”言未毕，一人应曰：“吾举一人，可破诸葛亮。”众视之，乃孟获妻弟，现为八番部长，名曰‘带来洞主’。获大喜，急问何人。带来洞主曰：“此去西南八纳洞，洞主木鹿大王，深通法术：出则骑象，能呼风唤雨，常有虎豹豺狼、毒蛇恶蝎跟随。手下更有三万神兵，甚是英勇。大王可修书具礼，某亲往求之。此人若允，何惧蜀兵哉！”获欣然，令国舅赍书而去。却令朵思大王守把三江城，以为前面屏障。却说孔明提兵直至三江城，遥望见此城三面傍江，一面通旱；即遣魏延、赵云同领一军，于旱路打城。军到城下时，城上弓弩齐发：原来洞中之人，多习弓弩，一弩齐发十矢，箭头上皆用毒药；但有中箭者，皮肉皆烂，见五脏而死。赵云、魏延不能取胜，回见孔明，言药箭之事。孔明自乘小车，到军前看了虚实，回到寨中，令军退数里下寨。蛮兵望见蜀兵远退，皆大笑作贺，只疑蜀兵惧怯而退，因此夜间安心稳睡，不去哨探。却说孔明约军退后，即闭寨不出。一连五日，并无号令。黄昏左侧，忽起微风。孔明传令曰：“每军要衣襟一幅，限一更时分应点。无者立斩。”诸将皆不知其意，众军依令预备。初更时分，又传令曰：“每军衣襟一幅，包土一包。无者立斩。”众军亦不知其意，只得依令预备。孔明又传令曰：“诸军包土，俱在三江城下交割。先到者有赏。”众军闻令，皆包净土，飞奔城下。孔明令积土为蹬道，先上城者为头功。于是蜀兵十余万，并降兵万余，将所包之土，一齐弃于城下。一霎时，积土成山，接连城上。一声暗号，蜀兵皆上城。蛮兵急放弩时，大半早被执下，余者弃城而走。朵思大王死于乱军之中。蜀将督军分路剿杀。孔明取了三江城，所得珍宝，皆赏三军。败残蛮兵逃回见孟获说：“朵思大王身死。失了三江城。”获大惊。正虑之间，人报蜀兵已渡江，现在本洞前下寨。孟获甚是慌张。忽然屏风后一人大笑而出曰：“既为男子，何无智也？我虽是一妇人，愿与你出战。”获视之，乃妻祝融夫人也。夫人世居南蛮，乃祝融氏之后；善使飞刀，百发百中。孟获起身称谢。夫人欣然上马，引宗党猛将数百员、生力洞兵五万，出银坑宫阙，来与蜀兵对敌。方才转过洞口，一彪军拦住：为首蜀将，乃是张嶷。蛮兵见之，却早两路摆开。祝融夫人背插五口飞刀，手挺丈八长标，坐下卷毛赤兔马。张嶷见之，暗暗称奇。二人骤马交锋。战不数合，夫人拨马便走。张嶷赶去，空中一把飞刀落下。嶷急用手隔，正中左臂，翻身落马。蛮兵发一声喊，将张嶷执缚去了。马忠听得张嶷被执，急出救时，早被蛮兵捆住。望见祝融夫人挺标勒马而立，忠忿怒向前去战，坐下马绊倒，亦被擒了。都解入洞中来见孟获。获设席庆贺。夫人叱刀斧手推出张嶷、马忠要斩。获止曰：“诸葛亮放吾五次，今番若杀彼将，是不义也。且囚在洞中，待擒住诸葛亮，杀之未迟。”夫人从其言，笑饮作乐。
却说败残兵来见孔明，告知其事。孔明即唤马岱、赵云、魏延三人受计，各自领军前去。次日，蛮兵报入洞中，说赵云搦战。祝融夫人即上马出迎。二人战不数合，云拨马便走。夫人恐有埋伏，勒兵而回。魏延又引军来搦战，夫人纵马相迎。正交锋紧急，延诈败而逃，夫人只不赶。次日，赵云又引军来搦战，夫人领洞兵出迎。二人战不数合，云诈败而走，夫人按标不赶。欲收兵回洞时，魏延引军齐声辱骂，夫人急挺标来取魏延。延拨马便走。夫人忿怒赶来，延骤马奔入山僻小路。忽然背后一声响亮，延回头视之，夫人仰鞍落马：原来马岱埋伏在此，用绊马索绊倒。就里擒缚，解投大寨而来。蛮将洞兵皆来救时，赵云一阵杀散。孔明端坐于帐上，马岱解祝融夫人到，孔明急令武士去其缚，请在别帐赐酒压惊，遣使往告孟获，欲送夫人换张嶷、马忠二将。
孟获允诺，即放出张嶷、马忠，还了孔明。孔明遂送夫人入洞。孟获接入，又喜又恼。忽报八纳洞主到。孟获出洞迎接，见其人骑着白象，身穿金珠缨络，腰悬两口大刀，领着一班喂养虎豹豺狼之士，簇拥而入。获再拜哀告，诉说前事。木鹿大王许以报仇。获大喜，设宴相待。次日，木鹿大王引本洞兵带猛兽而出。赵云、魏延听知蛮兵出，遂将军马布成阵势。二将并辔立于阵前视之，只见蛮兵旗帜器械皆别：人多不穿衣甲，尽裸身赤体，面目丑陋；身带四把尖刀；军中不鸣鼓角，但筛金为号；木鹿大王腰挂两把宝刀，手执蒂钟，身骑白象，从大旗中而出。赵云见了，谓魏延曰：“我等上阵一生，未尝见如此人物。”二人正沉吟之际，只见木鹿大王口中不知念甚咒语，手摇蒂钟。忽然狂风大作，飞砂走石，如同骤雨；一声画角响，虎豹豺狼，毒蛇猛兽，乘风而出，张牙舞爪，冲将过来。蜀兵如何抵当，往后便退。蛮兵随后追杀，直赶到三江界路方回。赵云、魏延收聚败兵，来孔明帐前请罪，细说此事。孔明笑曰：“非汝二人之罪。吾未出茅庐之时，先知南蛮有驱虎豹之法。吾在蜀中已办下破此阵之物也：随军有二十辆车，俱封记在此。今日且用一半；留下一半，后有别用。”遂令左右取了十辆红油柜车到帐下，留十辆黑油柜车在后。众皆不知其意。孔明将柜打开，皆是木刻彩画巨兽，俱用五色绒线为毛衣，钢铁为牙爪，一个可骑坐十人。孔明选了精壮军士一千余人，领了一百，口内装烟火之物，藏在军中。次日，孔明驱兵大进，布于洞口。蛮兵探知，入洞报与蛮王。木鹿大王自谓无敌，即与孟获引洞兵而出。孔明纶巾羽扇，身衣道袍，端坐于车上。孟获指曰：“车上坐的便是诸葛亮！若擒住此人，大事定矣！”木鹿大王口中念咒，手摇蒂钟。顷刻之间，狂风大作，猛兽突出。孔明将羽扇一摇，其风便回吹彼阵中去了，蜀阵中假兽拥出。蛮洞真兽见蜀阵巨兽口吐火焰，鼻出黑烟，身摇铜铃，张牙舞爪而来，诸恶兽不敢前进，皆奔回蛮洞，反将蛮兵冲倒无数。孔明驱兵大进，鼓角齐鸣，望前追杀。木鹿大王死于乱军之中。洞内孟获宗党，皆弃宫阙，扒山越岭而走。孔明大军占了银坑洞。
次日，孔明正要分兵缉擒孟获，忽报：“蛮王孟获妻弟带来洞主，因劝孟获归降，获不从，今将孟获并祝融夫人及宗党数百余人尽皆擒来，献与丞相。”孔明听知，即唤张嶷、马忠，分付如此如此。二将受了计，引二千精壮兵，伏于两廊。孔明即令守门将，俱放进来。带来洞主引刀斧手解孟获等数百人，拜于殿下。孔明大喝曰：“与吾擒下！”两廊壮兵齐出，二人捉一人，尽被执缚。孔明大笑曰：“量汝些小诡计，如何瞒得过我！汝见二次俱是本洞人擒汝来降，吾不加害；汝只道吾深信，故来诈降，欲就洞中杀吾！”喝令武士搜其身畔，果然各带利刀。孔明问孟获曰：“汝原说在汝家擒住，方始心服；今日如何？”获曰：“此是我等自来送死，非汝之能也。吾心未服。”孔明曰：“吾擒住六番，尚然不服，欲待何时耶？”获曰：“汝第七次擒住，吾方倾心归服，誓不反矣。”孔明曰：“巢穴已破，吾何虑哉！”令武士尽去其缚，叱之曰：“这番擒住，再若支吾，必不轻恕！”孟获等抱头鼠窜而去。
却说败残蛮兵有千余人，大半中伤而逃，正遇蛮王孟获。获收了败兵，心中稍喜，却与带来洞主商议曰：“吾今洞府已被蜀兵所占，今投何地安身？”带来洞主曰：“止有一国可以破蜀。”获喜曰：“何处可去？”带来洞主曰：“此去东南七百里，有一国，名乌戈国。国主兀突骨，身长丈二，不食五谷，以生蛇恶兽为饭；身有鳞甲，刀箭不能侵。其手下军士，俱穿藤甲；其藤生于山涧之中，盘于石壁之上；国人采取，浸于油中，半年方取出晒之；晒干复浸，凡十余遍，却才造成铠甲；穿在身上，渡江不沉，经水不湿，刀箭皆不能入：因此号为‘藤甲军’。今大王可往求之。若得彼相助，擒诸葛亮如利刀破竹也。”孟获大喜，遂投乌戈国，来见兀突骨。其洞无宇舍，皆居土穴之内。孟获入洞，再拜哀告前事。兀突骨曰：“吾起本洞之兵，与汝报仇。”获欣然拜谢。于是兀突骨唤两个领兵俘长：一名土安，一名奚泥，起三万兵，皆穿藤甲，离乌戈国望东北而来。行至一江，名桃花水，两岸有桃树，历年落叶于水中，若别国人饮之尽死，惟乌戈国人饮之，倍添精神。兀突骨兵至桃花渡口下寨，以待蜀兵。
却说孔明令蛮人哨探孟获消息，回报曰：“孟获请乌戈国主，引三万藤甲军，现屯于桃花渡口。孟获又在各番聚集蛮兵，并力拒战。”孔明听说，提兵大进，直至桃花渡口。隔岸望见蛮兵，不类人形，甚是丑恶；又问土人，言说即日桃叶正落，水不可饮。孔明退五里下寨，留魏延守寨。
次日，乌戈国主引一彪藤甲军过河来，金鼓大震。魏延引兵出迎。蛮兵卷地而至。蜀兵以弩箭射到藤甲之上，皆不能透，俱落于地；刀砍枪刺，亦不能入。蛮兵皆使利刀钢叉，蜀兵如何抵当，尽皆败走。蛮兵不赶而回。魏延复回，赶到桃花渡口，只见蛮兵带甲渡水而去；内有困乏者，将甲脱下，放在水面，以身坐其上而渡。魏延急回大寨，来禀孔明，细言其事。孔明请吕凯并土人问之。凯曰：“某素闻南蛮中有一乌戈国，无人伦者也。更有藤甲护身，急切难伤。又有桃叶恶水，本国人饮之，反添精神；别国人饮之即死：如此蛮方，纵使全胜，有何益焉？不如班师早回。”孔明笑曰：“吾非容易到此，岂可便去！吾明日自有平蛮之策。”于是令赵云助魏延守寨，且休轻出。次日，孔明令土人引路，自乘小车到桃花渡口北岸山僻去处，遍观地理。山险岭峻之处，车不能行，孔明弃车步行。忽到一山，望见一谷，形如长蛇，皆光峭石壁，并无树木，中间一条大路。孔明问土人曰：“此谷何名？”土人答曰：“此处名为盘蛇谷。出谷则三江城大路，谷前名塔郎甸。”孔明大喜曰：“此乃天赐吾成功于此也！”遂回旧路，上车归寨，唤马岱分付曰：“与汝黑油柜车十辆，须用竹竿千条，柜内之物，如此如此。可将本部兵去把住盘蛇谷两头，依法而行。与汝半月限，一切完备。至期如此施设。倘有走漏，定按军法。”马岱受计而去。又唤赵云分付曰：“汝去盘蛇谷后，三江大路口如此守把。所用之物，克日完备。”赵云受计而去。又唤魏延分付曰：“汝可引本部兵去桃花渡口下寨。如蛮兵渡水来敌，汝便弃了寨，望白旗处而走。限半个月内，须要连输十五阵，弃七个寨栅。若输十四阵，也休来见我。”魏延领命，心中不乐，怏怏而去。孔明又唤张翼另引一军，依所指之处，筑立寨栅去了；却令张嶷、马忠引本洞所降千人，如此行之。各人都依计而行。却说孟获与乌戈国主兀突骨曰：“诸葛亮多有巧计，只是埋伏。今后交战，分付三军：但见山谷之中，林木多处，不可轻进。”兀突骨曰：“大王说的有理。吾已知道中国人多行诡计。今后依此言行之。吾在前面厮杀；汝在背后教道。”两人商议已定。忽报蜀兵在桃花渡口北岸立起营寨。兀突骨即差二俘长引藤甲军渡了河，来与蜀兵交战。不数合，魏延败走。蛮兵恐有埋伏，不赶自回。次日，魏延又去立了营寨。蛮兵哨得，又引众军渡过河来战。延出迎之。不数合，延败走。蛮兵追杀十余里，见四下并无动静，便在蜀寨中屯住。次日，二俘长请兀突骨到寨，说知此事。兀突骨即引兵大进，将魏延追一阵。蜀兵皆弃甲抛戈而走，只见前有白旗。延引败兵，急奔到白旗处，早有一寨，就寨中屯住。兀突骨驱兵追至，魏延引兵弃寨而走。蛮兵得了蜀寨。次日，又望前追杀。魏延回兵交战，不三合又败，只看白旗处而走，又有一寨，延就寨屯住。次日，蛮兵又至。延略战又走。蛮兵占了蜀寨。
话休絮烦，魏延且战且走，已败十五阵，连弃七个营寨。蛮兵大进追杀。兀突骨自在军前破敌，于路但见林木茂盛之处，便不敢进；却使人远望，果见树阴之中，旌旗招飐。兀突骨谓孟获曰：“果不出大王所料。”孟获大笑曰：“诸葛亮今番被吾识破！大王连日胜了他十五阵，夺了七个营寨，蜀兵望风而走。诸葛亮已是计穷；只此一进，大事定矣！”兀突骨大喜，遂不以蜀兵为念。至第十六日，魏延引败残兵，来与藤甲军对敌，兀突骨骑象当先，头戴日月狼须帽，身披金珠缨络，两肋下露出生鳞甲，眼目中微有光芒，手指魏延大骂。延拨马便走。后面蛮兵大进。魏延引兵转过了盘蛇谷，望白旗而走。兀突骨统引兵众，随后追杀。兀突骨望见山上并无草木，料无埋伏，放心追杀。赶到谷中，见数十辆黑油柜车在当路。蛮兵报曰：“此是蜀兵运粮道路，因大王兵至，撇下粮车而走。”兀突骨大喜，催兵追赶。将出谷口，不见蜀兵，只见横木乱石滚下，垒断谷口。兀突骨令兵开路而进，忽见前面大小车辆，装载干柴，尽皆火起。兀突骨忙教退兵，只闻后军发喊，报说谷中已被干柴垒断，车中原来皆是火药，一齐烧着。兀突骨见无草木，心尚不慌，令寻路而走。只见山上两边乱丢火把，火把到处，地中药线皆着，就地飞起铁炮。满谷中火光乱舞，但逢藤甲，无有不着。将兀突骨并三万藤甲军，烧得互相拥抱，死于盘蛇谷中。孔明在山上往下看时，只见蛮兵被火烧的伸拳舒腿，大半被铁炮打的头脸粉碎，皆死于谷中，臭不可闻。孔明垂泪而叹曰：“吾虽有功于社稷，必损寿矣！”左右将士，无不感叹。
却说孟获在寨中，正望蛮兵回报。忽然千余人笑拜于寨前，言说：“乌戈国兵与蜀兵大战，将诸葛亮围在盘蛇谷中了。特请大王前去接应。我等皆是本洞之人，不得已而降蜀；今知大王前到，特来助战。”孟获大喜，即引宗党并所聚番人，连夜上马；就令蛮兵引路。方到盘蛇谷时，只见火光甚起，臭气难闻。获知中计，急退兵时，左边张嶷，右边马忠，两路军杀出。获方欲抵敌，一声喊起，蛮兵中大半皆是蜀兵，将蛮王宗党并聚集的番人，尽皆擒了。孟获匹马杀出重围，望山径而走。
正走之间，见山凹里一簇人马，拥出一辆小车；车中端坐一人，纶巾羽扇，身衣道袍，乃孔明也。孔明大喝曰：“反贼孟获！今番如何？”获急回马走。旁边闪过一将，拦住去路，乃是马岱。孟获措手不及，被马岱生擒活捉了。此时王平、张翼已引一军赶到蛮寨中，将祝融夫人并一应老小皆活捉而来。
孔明归到寨中，升帐而坐，谓众将曰：“吾今此计，不得已而用之，大损阴德。我料敌人必算吾于林木多处埋伏，吾却空设旌旗，实无兵马，疑其心也。吾令魏文长连输十五阵者，坚其心也。吾见盘蛇谷止一条路，两壁厢皆是光石，并无树木，下面都是沙土，因令马岱将黑油柜安排于谷中，车中油柜内，皆是预先造下的火炮，名曰‘地雷’，一炮中藏九炮，三十步埋之，中用竹竿通节，以引药线；才一发动，山损石裂。吾又令赵子龙预备草车，安排于谷中。又于山上准备大木乱石。却令魏延赚兀突骨并藤甲军入谷，放出魏延，即断其路，随后焚之。吾闻：‘利于水者必不利于火。’藤甲虽刀箭不能入，乃油浸之物，见火必着。蛮兵如此顽皮，非火攻安能取胜？使乌戈国之人不留种类者，是吾之大罪也！”众将拜伏曰：“丞相天机，鬼神莫测也！”孔明令押过孟获来。孟获跪于帐下。孔明令去其缚，教且在别帐与酒食压惊。孔明唤管酒食官至坐榻前，如此如此，分付而去。却说孟获与祝融夫人并孟优、带来洞主、一切宗党在别帐饮酒。忽一人入帐谓孟获曰：“丞相面羞，不欲与公相见。特令我来放公回去，再招人马来决胜负。公今可速去。”孟获垂泪言曰：“七擒七纵，自古未尝有也。吾虽化外之人，颇知礼义，直如此无羞耻乎？”遂同兄弟妻子宗党人等，皆匍匐跪于帐下，肉袒谢罪曰：“丞相天威，南人不复反矣！”孔明曰：“公今服乎？”获泣谢曰：“某子子孙孙皆感覆载生成之恩，安得不服！”孔明乃请孟获上帐，设宴庆贺，就令永为洞主。所夺之地，尽皆退还。孟获宗党及诸蛮兵，无不感戴，皆欣然跳跃而去。后人有诗赞孔明曰：“羽扇纶巾拥碧幢，七擒妙策制蛮王。至今溪洞传威德，为选高原立庙堂。”
长史费祎入谏曰：“今丞相亲提士卒，深入不毛，收服蛮方；目今蛮王既已归服，何不置官吏，与孟获一同守之？”孔明曰：“如此有三不易：留外人则当留兵，兵无所食，一不易也；蛮人伤破，父兄死亡，留外人而不留兵，必成祸患，二不易也；蛮人累有废杀之罪，自有嫌疑，留外人终不相信，三不易也。今吾不留人，不运粮，与相安于无事而已。”众人尽服。于是蛮方皆感孔明恩德，乃为孔明立生祠，四时享祭，皆呼之为“慈父”；各送珍珠金宝、丹漆药材、耕牛战马，以资军用，誓不再反。南方已定。
却说孔明犒军已毕，班师回蜀，令魏延引本部兵为前锋。延引兵方至泸水，忽然阴云四合，水面上一阵狂风骤起，飞沙走石，军不能进。延退兵回报孔明。孔明遂请孟获问之。正是：塞外蛮人方帖服，水边鬼卒又猖狂。
未知孟获所言若何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943875, '5b9b7344570c350063547c3f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639230, '三国演义 · 第九十一回 · 祭泸水汉相班师 伐中原武侯上表', NULL, 2, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说孔明班师回国，孟获率引大小洞主酋长，及诸部落，罗拜相送。前军至泸水，时值九月秋天，忽然阴云布合，狂风骤起；兵不能渡，回报孔明。孔明遂问孟获，获曰：“此水原有猖神作祸，往来者必须祭之。”孔明曰：“用何物祭享？”获曰：“旧时国中因猖神作祸，用七七四十九颗人头并黑牛白羊祭之，自然风恬浪静，更兼连年丰稔。”孔明曰：“吾今事已平定，安可妄杀一人？”遂自到泸水岸边观看。果见阴风大起，波涛汹涌，人马皆惊。孔明甚疑，即寻土人问之。土人告说：“自丞相经过之后，夜夜只闻得水边鬼哭神号。自黄昏直至天晓，哭声不绝。瘴烟之内，阴鬼无数。因此作祸，无人敢渡。”孔明曰：“此乃我之罪愆也。前者马岱引蜀兵千余，皆死于水中；更兼杀死南人，尽弃此处。狂魂怨鬼，不能解释，以致如此。吾今晚当亲自往祭。”土人曰：“须依旧例，杀四十九颗人头为祭，则怨鬼自散也。”孔明曰：“本为人死而成怨鬼，岂可又杀生人耶？吾自有主意。”唤行厨宰杀牛马；和面为剂，塑成人头，内以牛羊等肉代之，名曰“馒头”。当夜于泸水岸上，设香案，铺祭物，列灯四十九盏，扬幡招魂；将馒头等物，陈设于地。三更时分，孔明金冠鹤氅，亲自临祭，令董厥读祭文。其文曰：“维大汉建兴三年秋九月一日，武乡侯、领益州牧、丞相诸葛亮，谨陈祭仪，享于故殁王事蜀中将校及南人亡者阴魂曰：我大汉皇帝，威胜五霸，明继三王。昨自远方侵境，异俗起兵；纵虿尾以兴妖，盗狼心而逞乱。我奉王命，问罪遐荒；大举貔貅，悉除蝼蚁；雄军云集，狂寇冰消；才闻破竹之声，便是失猿之势。但士卒儿郎，尽是九州豪杰；官僚将校，皆为四海英雄：习武从戎，投明事主，莫不同申三令，共展七擒；齐坚奉国之诚，并效忠君之志。何期汝等偶失兵机，缘落奸计：或为流矢所中，魂掩泉台；或为刀剑所伤，魄归长夜：生则有勇，死则成名，今凯歌欲还，献俘将及。汝等英灵尚在，祈祷必闻：随我旌旗，逐我部曲，同回上国，各认本乡，受骨肉之蒸尝，领家人之祭祀；莫作他乡之鬼，徒为异域之魂。我当奏之天子，使汝等各家尽沾恩露，年给衣粮，月赐廪禄。用兹酬答，以慰汝心。至于本境土神，南方亡鬼，血食有常，凭依不远；生者既凛天威，死者亦归王化，想宜宁帖，毋致号啕。聊表丹诚，敬陈祭祀。呜呼，哀哉！伏惟尚飨！”读毕祭文，孔明放声大哭，极其痛切，情动三军，无不下泪。孟获等众，尽皆哭泣。只见愁云怨雾之中，隐隐有数千鬼魂，皆随风而散。于是孔明令左右将祭物尽弃于泸水之中。次日，孔明引大军俱到泸水南岸，但见云收雾散，风静浪平。蜀兵安然尽渡泸水，果然“鞭敲金镫响，人唱凯歌还”。行到永昌，孔明留王伉、吕凯守四郡；发付孟获领众自回，嘱其勤政驭下，善抚居民，勿失农务。孟获涕泣拜别而去。
孔明自引大军回成都。后主排銮驾出郭三十里迎接，下辇立于道傍，以候孔明。孔明慌下车伏道而言曰：“臣不能速平南方，使主上怀忧，臣之罪也。”后主扶起孔明，并车而回，设太平筵会，重赏三军。自此远邦进贡来朝者二百余处。孔明奏准后主，将殁于王事者之家，一一优恤。人心欢悦，朝野清平。却说魏主曹丕，在位七年，即蜀汉建兴四年也。丕先纳夫人甄氏，即袁绍次子袁熙之妇，前破邺城时所得。后生一子，名睿，字元仲，自幼聪明，丕甚爱之。后丕又纳安平广宗人郭永之女为贵妃，甚有颜色；其父尝曰：“吾女乃女中之王也。”故号为“女王”。自丕纳为贵妃，因甄夫人失宠，郭贵妃欲谋为后，却与幸臣张韬商议。时丕有疾，韬乃诈称于甄夫人宫中掘得桐木偶人，上书天子年月日时，为魇镇之事。丕大怒，遂将甄夫人赐死，立郭贵妃为后。因无出，养曹睿为己子。虽甚爱之，不立为嗣。
睿年至十五岁，弓马熟娴。当年春二月，丕带睿出猎。行于山坞之间，赶出子母二鹿，丕一箭射倒母鹿，回观小鹿驰于曹睿马前。丕大呼曰：“吾儿何不射之？”睿在马上泣告曰：“陛下已杀其母，臣安忍复杀其子也。”丕闻之，掷弓于地曰：“吾儿真仁德之主也！”于是遂封睿为平原王。
夏五月，丕感寒疾，医治不痊，乃召中军大将军曹真、镇军大将军陈群、抚军大将军司马懿三人入寝宫。丕唤曹睿至，指谓曹真等曰：“今朕病已沉重，不能复生。此子年幼，卿等三人可善辅之，勿负朕心。”三人皆告曰：“陛下何出此言？臣等愿竭力以事陛下，至千秋万岁。”丕曰：“今年许昌城门无故自崩，乃不祥之兆，朕故自知必死也。”正言间，内侍奏征东大将军曹休入宫问安。丕召入谓曰：“卿等皆国家柱石之臣也，若能同心辅朕之子，朕死亦瞑目矣！”言讫，堕泪而薨。时年四十岁，在位七年。于是曹真、陈群、司马懿、曹休等，一面举哀，一面拥立曹睿为大魏皇帝。谥父丕为文皇帝，谥母甄氏为文昭皇后。封钟繇为太傅，曹真为大将军，曹休为大司马，华歆为太尉，王朗为司徒，陈群为司空，司马懿为骠骑大将军。其余文武官僚，各各封赠。大赦天下。时雍、凉二州缺人守把，司马懿上表乞守西凉等处。曹睿从之，遂封懿提督雍、凉等处兵马。领诏去讫。
早有细作飞报入川。孔明大惊曰：“曹丕已死，孺子曹睿即位，余皆不足虑：司马懿深有谋略，今督雍、凉兵马，倘训练成时，必为蜀中之大患。不如先起兵伐之。”参军马谡曰：“今丞相平南方回，军马疲敝，只宜存恤，岂可复远征？某有一计，使司马懿自死于曹睿之手，未知丞相钧意允否？”孔明问是何计，马谡曰：“司马懿虽是魏国大臣，曹睿素怀疑忌。何不密遣人往洛阳、邺郡等处，布散流言，道此人欲反；更作司马懿告示天下榜文，遍贴诸处。使曹睿心疑，必然杀此人也。”孔明从之，即遣人密行此计去了。
却说邺城门上。忽一日见贴下告示一道。守门者揭了，来奏曹睿。睿观之，其文曰：“骠骑大将军总领雍、凉等处兵马事司马懿，谨以信义布告天下：昔太祖武皇帝，创立基业，本欲立陈思王子建为社稷主；不幸奸谗交集，岁久潜龙。皇孙曹睿，素无德行，妄自居尊，有负太祖之遗意。今吾应天顺人，克日兴师，以慰万民之望。告示到日，各宜归命新君。如不顺者，当灭九族！先此告闻，想宜知悉。”
曹睿览毕，大惊失色，急问群臣。太尉华歆奏曰：“司马懿上表乞守雍、凉，正为此也。先时太祖武皇帝尝谓臣曰：司马懿鹰视狼顾，不可付以兵权；久必为国家大祸。今日反情已萌，可速诛之。”王朗奏曰：“司马懿深明韬略，善晓兵机，素有大志；若不早除，久必为祸。”睿乃降旨，欲兴兵御驾亲征。忽班部中闪出大将军曹真奏曰：“不可。文皇帝托孤于臣等数人，是知司马仲达无异志也。今事未知真假，遽尔加兵，乃逼之反耳。或者蜀、吴奸细行反间之计，使我君臣自乱，彼却乘虚而击，未可知也。陛下幸察之。”睿曰：“司马懿若果谋反，将奈何？”真曰：“如陛下心疑，可仿汉高伪游云梦之计。御驾幸安邑，司马懿必然来迎；观其动静，就车前擒之，可也。”睿从之，遂命曹真监国，亲自领御林军十万，径到安邑。司马懿不知其故，欲令天子知其威严，乃整兵马，率甲士数万来迎。近臣奏曰：“司马懿果率兵十余万，前来抗拒，实有反心矣。”睿慌命曹休先领兵迎之。司马懿见兵马前来，只疑车驾亲至，伏道而迎。曹休出曰：“仲达受先帝托孤之重，何故反耶？”懿大惊失色，汗流遍体，乃问其故。休备言前事。懿曰：“此吴、蜀奸细反间之计，欲使我君臣自相残害，彼却乘虚而袭。某当自见天子辨之。”遂急退了军马，至睿车前俯伏泣奏曰：“臣受先帝托孤之重，安敢有异心？必是吴、蜀之奸计。臣请提一旅之师，先破蜀，后伐吴，报先帝与陛下，以明臣心。”睿疑虑未决。华歆奏曰：“不可付之兵权。可即罢归田里。”睿依言，将司马懿削职回乡，命曹休总督雍；凉军马。曹睿驾回洛阳。却说细作探知此事，报入川中。孔明闻之大喜曰：“吾欲伐魏久矣，奈有司马懿总雍、凉之兵。今既中计遭贬，吾有何忧！”次日，后主早朝，大会官僚，孔明出班，上《出师表》一道。表曰：“臣亮言：先帝创业未半，而中道崩殂；今天下三分，益州罢敝，此诚危急存亡之秋也。然侍卫之臣，不懈于内；忠志之士，忘身于外者：盖追先帝之殊遇，欲报之于陛下也。诚宜开张圣听，以光先帝遗德，恢弘志士之气；不宜妄自菲薄，引喻失义，以塞忠谏之路也。宫中府中，俱为一体；陟罚臧否，不宜异同。若有作奸犯科，及为忠善者，宜付有司，论其刑赏，以昭陛下平明之治；不宜偏私，使内外异法也。侍中、侍郎郭攸之、费祎、董允等，此皆良实，志虑忠纯，是以先帝简拔以遗陛下。愚以为宫中之事，事无大小，悉以咨之，然后施行，必得裨补阙漏，有所广益。将军向宠，性行淑均，晓畅军事，试用之于昔日，先帝称之曰“能”，是以众议举宠以为督。愚以为营中之事，事无大小，悉以咨之，必能使行阵和穆，优劣得所也。亲贤臣，远小人，此先汉所以兴隆也；亲小人，远贤臣，此后汉所以倾颓也。先帝在时，每与臣论此事，未尝不叹息痛恨于桓、灵也！侍中、尚书、长史、参军，此悉贞亮死节之臣也，愿陛下亲之、信之，则汉室之隆，可计日而待也。臣本布衣，躬耕南阳，苟全性命于乱世，不求闻达于诸侯。先帝不以臣卑鄙，猥自枉屈，三顾臣于草庐之中，谘臣以当世之事，由是感激，遂许先帝以驱驰。后值倾覆，受任于败军之际，奉命于危难之间：尔来二十有一年矣。先帝知臣谨慎，故临崩寄臣以大事也。受命以来，夙夜忧虑，恐付托不效，以伤先帝之明；故五月渡泸，深入不毛。今南方已定，甲兵已足，当奖帅三军，北定中原，庶竭弩钝，攘除奸凶，兴复汉室，还于旧都：此臣所以报先帝而忠陛下之职分也。至于斟酌损益，进尽忠言，则攸之、祎、允之任也。愿陛下托臣以讨贼兴复之效，不效则治臣之罪，以告先帝之灵；若无兴复之言，则责攸之、祎、允等之咨，以彰其慢。陛下亦宜自谋，以谘诹善道，察纳雅言，深追先帝遗诏。臣不胜受恩感激！今当远离，临表涕泣，不知所云。”
后主览表曰：“相父南征，远涉艰难；方始回都，坐未安席；今又欲北征，恐劳神思。”孔明曰：“臣受先帝托孤之重，夙夜未尝有怠。今南方已平，可无内顾之忧；不就此时讨贼，恢复中原，更待何日？”忽班部中太史谯周出奏曰：“臣夜观天象，北方旺气正盛，星曜倍明，未可图也。”乃顾孔明曰：“丞相深明天文，何故强为？”孔明曰：“天道变易不常，岂可拘执？吾今且驻军马于汉中，观其动静而后行。”谯周苦谏不从。于是孔明乃留郭攸之、董允、费祎等为侍中，总摄宫中之事。又留向宠为大将，总督御林军马；蒋琬为参军；张裔为长史，掌丞相府事；杜琼为谏议大夫；杜微、杨洪为尚书；孟光、来敏为祭酒；尹默、李譔为博士；郤正、费诗为秘书；谯周为太史。内外文武官僚一百余员，同理蜀中之事。
孔明受诏归府，唤诸将听令：
前督部——镇北将军、领丞相司马、凉州刺史、都亭侯魏延；
前军都督——领扶风太守张翼；
牙门将——裨将军王平；
后军领兵使——安汉将军、领建宁太守李恢，
副将——定远将军、领汉中太守吕义；
兼管运粮左军领兵使——平北将军、陈仓侯马岱，
副将——飞卫将军廖化；
右军领兵使——奋威将军、博阳亭侯马忠，抚戎将军、关内侯张嶷；
行中军师——车骑大将军、都乡侯刘琰；
中监军——扬武将军邓芝；
中参军——安远将军马谡；
前将军——都亭侯袁綝；
左将军——高阳侯吴懿；
右将军——玄都侯高翔；
后将军——安乐侯吴班；
领长史——绥军将军杨仪；
前将军——征南将军刘巴；
前护军——偏将军、汉城亭侯许允；
左护军——笃信中郎将丁咸；
右护军——偏将军刘敏；
后护军——典军中郎将官雝；
行参军——昭武中郎将胡济；
行参军——谏议将军阎晏；
行参军——偏将军爨习；
行参军——裨将军杜义，武略中郎将杜祺，绥戎都尉盛孛攵；
从事——武略中郎将樊岐；
典军书记——樊建；
丞相令史——董厥；
帐前左护卫使——龙骧将军关兴；
右护卫使——虎翼将军张苞。
以上一应官员，都随着平北大都督、丞相、武乡侯、领益州牧、知内外事诸葛亮。分拨已定，又檄李严等守川口以拒东吴。选定建兴五年春三月丙寅日，出师伐魏。
忽帐下一老将，厉声而进曰：“我虽年迈，尚有廉颇之勇，马援之雄。此二古人皆不服老，何故不用我耶？”众视之，乃赵云也。孔明曰：“吾自平南回都，马孟起病故，吾甚惜之，以为折一臂也。今将军年纪已高，倘稍有参差，动摇一世英名，减却蜀中锐气。”云厉声曰：“吾自随先帝以来，临阵不退，遇敌则先。大丈夫得死于疆场者，幸也，吾何恨焉？愿为前部先锋！”孔明再三苦劝不住。云曰：“如不教我为先锋，就撞死于阶下！”孔明曰：“将军既要为先锋，须得一人同去。”言未尽，一人应曰：“某虽不才，愿助老将军先引一军前去破敌。”孔明视之，乃邓芝也。孔明大喜，即拨精兵五千。副将十员，随赵云、邓芝去讫。
孔明出师，后主引百官送于北门外十里。孔明辞了后主，旌旗蔽野，戈戟如林，率军望汉中迤逦进发。却说边庭探知此事，报入洛阳。是日曹睿设朝，近臣奏曰：“边官报称：诸葛亮率领大兵三十余万，出屯汉中，令赵云、邓芝为前部先锋，引兵入境。”睿大惊，问群臣曰：“谁可为将，以退蜀兵？”忽一人应声而出曰：“臣父死于汉中，切齿之恨，未尝得报。今蜀兵犯境，臣愿引本部猛将，更乞陛下赐关西之兵，前往破蜀，上为国家效力，下报父仇，臣万死不恨！”众视之，乃夏侯渊之子夏侯楙也。楙字子休，其性最急，又最吝，自幼嗣与夏侯惇为子。后夏侯渊为黄忠所斩，曹操怜之，以女清河公主招为驸马，因此朝中钦敬。虽掌兵权，未尝临阵。当时自请出征，曹睿即命为大都督，调关西诸路军马前去迎敌。司徒王朗谏曰：“不可。夏侯驸马素不曾经战，今付以大任，非其所宜。更兼诸葛亮足智多谋，深通韧略，不可轻敌。”夏侯楙叱曰：“司徒莫非结连诸葛亮，欲为内应耶？吾自幼从父学习韬略，深通兵法。汝何欺我年幼？吾若不生擒诸葛亮，誓不回见天子！”王朗等皆不敢言。夏侯楙辞了魏主，星夜到长安，调关西诸路军马二十余万，来敌孔明。正是：欲秉白旄摩将士，却教黄吻掌兵权。
未知胜负如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943873, '5b9b735b1579a3003a4fd71b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639231, '三国演义 · 第九十二回 · 赵子龙力斩五将 诸葛亮智取三城', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说孔明率兵前至沔阳，经过马超坟墓，乃令其弟马岱挂孝，孔明亲自祭之。祭毕，回到寨中，商议进兵。忽哨马报道：“魏主曹睿遣驸马夏侯楙，调关中诸路军马，前来拒敌。”魏延上帐献策曰：“夏侯楙乃膏粱子弟，懦弱无谋。延愿得精兵五千，取路出褒中，循秦岭以东，当子午谷而投北，不过十日，可到长安。夏侯楙若闻某骤至，必然弃城望横门邸阁而走。某却从东方而来，丞相可大驱士马，自斜谷而进。如此行之，则咸阳以西，一举可定也。”孔明笑曰：“此非万全之计也。汝欺中原无好人物，倘有人进言，于山僻中以兵截杀，非惟五千人受害，亦大伤锐气。决不可用。”魏延又曰：“丞相兵从大路进发，彼必尽起关中之兵，于路迎敌，则旷日持久，何时而得中原？”孔明曰：“吾从陇右取平坦大路，依法进兵，何忧不胜！”遂不用魏延之计。魏延怏怏不悦。孔明差人令赵云进兵。
却说夏侯楙在长安聚集诸路军马。时有西凉大将韩德，善使开山大斧，有万夫不当之勇，引西羌诸路兵八万到来；见了夏侯楙，楙重赏之，就遣为先锋。德有四子，皆精通武艺，弓马过人：长子韩瑛，次子韩瑶，三子韩琼，四子韩琪。韩德带四子并西羌兵八万，取路至凤鸣山，正遇蜀兵。两阵对圆。韩德出马，四子列于两边。德厉声大骂曰：“反国之贼，安敢犯吾境界！”赵云大怒，挺枪纵马，单搦韩德交战。长子韩瑛，跃马来迎；战不三合，被赵云一枪刺死于马下。次子韩瑶见之，纵马挥刀来战。赵云施逞旧日虎威，抖擞精神迎战。瑶抵敌不住。三子韩琼，急挺方天戟骤马前来夹攻。云全然不惧，枪法不乱。四子韩琪，见二兄战云不下，也纵马抡两口日月刀而来，围住赵云。云在中央独战三将。少时，韩琪中枪落马，韩阵中偏将急出救去。云拖枪便走。韩琼按戟，急取弓箭射之，连放三箭，皆被云用枪拨落。琼大怒，仍绰方天戟纵马赶来；却被云一箭射中面门，落马而死，韩瑶纵马举宝刀便砍赵云。云弃枪于地，闪过宝刀，生擒韩瑶归阵，复纵马取枪杀过阵来。韩德见四子皆丧于赵云之手，肝胆皆裂，先走入阵去。西凉兵素知赵云之名，今见其英勇如昔，谁敢交锋？赵云马到处，阵阵倒退。赵云匹马单枪，往来冲突，如入无人之境。后人有诗赞曰：“忆昔常山赵子龙，年登七十建奇功。独诛四将来冲阵，犹似当阳救主雄。”
邓芝见赵云大胜，率蜀兵掩杀，西凉兵大败而走。韩德险被赵云擒住，弃甲步行而逃。云与邓芝收军回寨。芝贺曰：“将军寿已七旬，英勇如昨。今日阵前力斩四将，世所罕有！”云曰：“丞相以吾年迈，不肯见用，吾故聊以自表耳。”遂差人解韩瑶，申报捷书，以达孔明。
却说韩德引败军回见夏侯楙，哭告其事。楙自统兵来迎赵云。探马报入蜀寨，说夏侯楙引兵到。云上马绰枪，引千余军，就凤鸣山前摆成阵势。当日，夏侯楙戴金盔，坐白马，手提大砍刀，立在门旗之下。见赵云跃马挺枪，往来驰骋，楙欲自战。韩德曰：“杀吾四子之仇，如何不报！”纵马轮开山大斧，直取赵云。云奋怒挺枪来迎；战不三合，枪起处，刺死韩德于马下，急拨马直取夏侯楙。楙慌忙闪入本阵。邓芝驱兵掩杀，魏兵又折一阵，退十余里下寨。楙连夜与众将商议曰：“吾久闻赵云之名，未尝见面；今日年老，英雄尚在，方信当阳长坂之事。似此无人可敌，如之奈何？”参军程武，乃程昱之子也，进言曰：“某料赵云有勇无谋，不足为虑。来日都督再引兵出，先伏两军于左右；都督临阵先退，诱赵云到伏兵处；都督却登山指挥四面军马，重叠围住，云可擒矣。”楙从其言，遂遣董禧引三万军伏于左，薛则引三万军伏于右。二人埋伏已定。
次日，夏侯楙复整金鼓旗幡，率兵而进。赵云、邓芝出迎。芝在马上谓赵云曰：“昨夜魏兵大败而走，今日复来，必有诈也。老将军防之。”子龙曰：“量此乳臭小儿，何足道哉！吾今日必当擒之！”便跃马而出。魏将潘遂出迎，战不三合，拨马便走。赵云赶去，魏阵中八员将一齐来迎。放过夏侯楙先走，八将陆续奔走。赵云乘势追杀，邓芝引兵继进。赵云深入重地，只听得四面喊声大震。邓芝急收军退回，左有董禧，右有薛则，两路兵杀到。邓芝兵少，不能解救。赵云被困在垓心，东冲西突，魏兵越厚。时云手下止有千余人，杀到山坡之下，只见夏侯楙在山上指挥三军。赵云投东则望东指，投西则望西指，因此赵云不能突围，乃引兵杀上山来。半山中擂木炮石打将下来，不能上山。赵云从辰时杀至酉时，不得脱走，只得下马少歇，且待月明再战。却才卸甲而坐，月光方出，忽四下火光冲天，鼓声大震，矢石如雨，魏兵杀到，皆叫曰：“赵云早降！”云急上马迎敌。四面军马渐渐逼近，八方弩箭交射甚急，人马皆不能向前。云仰天叹曰：“吾不服老，死于此地矣！”忽东北角上喊声大起，魏兵纷纷乱窜，一彪军杀到，为首大将持丈八点钢矛，马项下挂一颗人头。云视之，乃张苞也。苞见了赵云，言曰：“丞相恐老将军有失，特遣某引五千兵接应。闻老将军被困，故杀透重围。正遇魏将薛则拦路，被某杀之。”云大喜，即与张苞杀出西北角来。只见魏兵弃戈奔走：一彪军从外呐喊杀人，为首大将提偃月青龙刀，手挽人头。云视之，乃关兴也。兴曰：“奉丞相之命，恐老将军有失，特引五千兵前来接应。却才阵上逢着魏将董禧，被吾一刀斩之，枭首在此。丞相随后便到也。”云曰：“二将军已建奇功，何不趁今日擒住夏侯楙，以定大事？”张苞闻言，遂引兵去了。兴曰：“我也干功去。”遂亦引兵去了。云回顾左右曰：“他两个是吾子侄辈，尚且争先干功；吾乃国家上将，朝廷旧臣，反不如此小儿耶？吾当舍老命以报先帝之恩！”于是引兵来捉夏侯楙。当夜三路兵夹攻，大破魏军一阵。邓芝引兵接应，杀得尸横遍野，血流成河。夏侯楙乃无谋之人，更兼年幼，不曾经战，见军大乱，遂引帐下骁将百余人，望南安郡而走。众军因见无主，尽皆逃窜。兴、苞二将闻夏侯楙望南安郡去了，连夜赶来。楙走入城中，令紧闭城门，驱兵守御。兴、苞二人赶到，将城围住；赵云随后也到：三面攻打。少时，邓芝亦引兵到。一连围了十日，攻打不下。
忽报丞相留后军住沔阳，左军屯阳平，右军屯石城，自引中军来到。赵云、邓芝、关兴、张苞皆来拜问孔明，说连日攻城不下。孔明遂乘小车亲到城边周围看了一遍，回寨升帐而坐。众将环立听令。孔明曰：“此郡壕深城峻，不易攻也。吾正事不在此城，汝等如只久攻，倘魏兵分道而出，以取汉中，吾军危矣。”邓芝曰：“夏侯楙乃魏之驸马，若擒此人，胜斩百将。今困于此，岂可弃之而去？”孔明曰：“吾自有计。此处西连天水郡，北抵安定郡，二处太守，不知何人？”探卒答曰：“天水太守马遵，安定太守崔谅。”孔明大喜，乃唤魏延受计，如此如此；又唤关兴、张苞受计，如此如此；又唤心腹军士二人受计，如此行之。各将领命，引兵而去。孔明却在南安城外，令军运柴草堆于城下，口称烧城。魏兵闻知，皆大笑不惧。却说安定太守崔谅，在城中闻蜀兵围了南安，困住夏侯楙，十分慌惧，即点军马约共四千，守住城池。忽见一人自正南而来，口称有机密事。崔谅唤入问之，答曰：“某是夏侯都督帐下心腹将裴绪。今奉都督将令，特来求救于天水、安定二郡。南安甚急，每日城上纵火为号，专望二郡救兵，并不见到；因复差某杀出重围，来此告急。可星夜起兵为外应。都督若见二郡兵到，却开城门接应也。”谅曰：“有都督文书否？”绪贴肉取出，汗已湿透；略教一视，急令手下换了乏马，便出城望天水而去。不二日，又有报马到，告天水太守已起兵救援南安去了，教安定早早接应。崔谅与府官商议。多官曰：“若不去救，失了南安，送了夏侯驸马，皆我两郡之罪也：只得救之。”谅即点起人马，离城而去，只留文官守城。
崔谅提兵向南安大路进发，遥望见火光冲天，催兵星夜前进，离南安尚有五十余里，忽闻前后喊声大震，哨马报道：“前面关兴截住去路，背后张苞杀来！”安定之兵，四下逃窜。谅大惊，乃领手下百余人，往小路死战得脱，奔回安定。方到城壕边，城上乱箭射下来。蜀将魏延在城上叫曰：“吾已取了城也！何不早降？”原来魏延扮作安定军，夤夜赚开城门，蜀兵尽入，因此得了安定。
崔谅慌投天水郡来。行不到一程，前面一彪军摆开。大旗之下，一人纶巾羽扇，道袍鹤氅，端坐于车上。谅视之，乃孔明也，急拨回马走。关兴、张苞两路兵追到，只叫：“早降！”崔谅见四面皆是蜀兵，不得已遂降，同归大寨。孔明以上宾相待。孔明曰：“南安太守与足下交厚否？”谅曰：“此人乃杨阜之族弟杨陵也；与某邻郡，交契甚厚。”孔明曰：“今欲烦足下入城，说杨陵擒夏侯楙，可乎？”谅曰：“丞相若令某去，可暂退军马，容某入城说之。”孔明从其言，即时传令，教四面军马各退二十里下寨。崔谅匹马到城边叫开城门，入到府中，与杨陵礼毕，细言其事。陵曰：“我等受魏主大恩，安忍背之？可将计就计而行。”遂引崔谅到夏侯楙处，备细说知。楙曰：“当用何计？”杨陵曰：“只推某献城门，赚蜀兵入，却就城中杀之。”崔谅依计而行，出城见孔明，说：“杨陵献城门，放大军入城，以擒夏侯楙。杨陵本欲自捉，因手下勇士不多，未敢轻动。”孔明曰：“此事至易：今有足下原降兵百余人，于内暗藏蜀将扮作安定军马，带入城去、先伏于夏侯楙府下；却暗约杨陵，待半夜之时，献开城门，里应外合。”崔谅暗思：“若不带蜀将去，恐孔明生疑。且带入去，就内先斩之，举火为号，赚孔明入来，杀之可也。”因此应允。孔明嘱曰：“吾遣亲信将关兴、张苞随足下先去，只推救军杀入城中，以安夏侯楙之心；但举火，吾当亲入城去擒之。”时值黄昏，关兴、张苞受了孔明密计，披挂上马，各执兵器，杂在安定军中，随崔谅来到南安城下。杨陵在城上撑起悬空板，倚定护心栏，问曰：“何处军马？”崔谅曰：“安定救军来到。”谅先射一号箭上城，箭上带着密书曰：“今诸葛亮先遣二将，伏于城中，要里应外合；且不可惊动，恐泄漏计策。待入府中图之。”杨陵将书见了夏侯楙，细言其事。楙曰：“既然诸葛亮中计，可教刀斧手百余人，伏于府中。如二将随崔太守到府下马，闭门斩之；却于城上举火，赚诸葛亮入城。伏兵齐出，亮可擒矣。”
安排已毕，杨陵回到城上言曰：“既是安定军马，可放入城。”关兴跟崔谅先行，张苞在后。杨陵下城，在门边迎接。兴手起刀落，斩杨陵于马下。崔谅大惊，急拨马奔到吊桥边，张苞大喝曰：“贼子休走！汝等诡计，如何瞒得丞相耶！”手起一枪，刺崔谅于马下。关兴早到城上，放起火来。四面蜀兵齐入。夏侯楙措手不及，开南门并力杀出。一彪军拦住，为首大将，乃是王平；交马只一合，生擒夏侯楙于马上，余皆杀死。孔明入南安，招谕军民，秋毫无犯。众将各各献功。孔明将夏侯楙囚于车中。邓芝问曰：“丞相何故知崔谅诈也？”孔明曰：“吾已知此人无降心，故意使入城。彼必尽情告与夏侯楙，欲将计就计而行。吾见来情，足知其诈，复使二将同去，以稳其心。此人若有真心，必然阻当；彼欣然同去者，恐吾疑也。他意中度二将同去，赚入城内杀之未迟；又令吾军有托，放心而进。吾已暗嘱二将，就城门下图之。城内必无准备，吾军随后便到。此出其不意也。”众将拜服。孔明曰：“赚崔谅者，吾使心腹人诈作魏将裴绪也。吾又去赚天水郡，至今未到，不知何故。今可乘势取之。”乃留吴懿守南安，刘琰守安定，替出魏延军马去取天水郡。
却说天水郡太守马遵，听知夏侯楙困在南安城中，乃聚文武官商议。功曹梁绪、主簿尹赏、主记梁虔等曰：“夏侯驸马乃金枝玉叶，倘有疏虞，难逃坐视之罪。太守何不尽起本部兵以救之？”马遵正疑虑间，忽报夏侯驸马差心腹将裴绪到。绪入府，取公文付马遵，说：“都督求安定、天水两郡之兵，星夜救应。”言讫，匆匆而去。次日又有报马到，称说：“安定兵已先去了，教太守火急前来会合。”
马遵正欲起兵，忽一人自外而入曰：“太守中诸葛亮之计矣！”众视之，乃天水冀人也，姓姜名维，字伯约。父名冏，昔日曾为天水郡功曹，因羌人乱，没于王事。维自幼博览群书，兵法武艺，无所不通；奉母至孝，郡人敬之；后为中郎将，就参本郡军事。当日姜维谓马遵曰：“近闻诸葛亮杀败夏侯楙，困于南安，水泄不通，安得有人自重围之中而出？又且裴绪乃无名下将，从不曾见；况安定报马，又无公文，以此察之，此人乃蜀将诈称魏将。赚得太守出城，料城中无备，必然暗伏一军于左近，乘虚而取天水也，”马遵大悟曰：“非伯约之言，则误中奸计矣！”维笑曰：“太守放心。某有一计，可擒诸葛亮，解南安之危。”正是：运筹又遇强中手，斗智还逢意外人。
未知其计如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943870, '5b9b7387808ca43cd222cef8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639232, '三国演义 · 第九十三回 · 姜伯约归降孔明 武乡侯骂死王朗', NULL, 1, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说姜维献计于马遵曰：“诸葛亮必伏兵于郡后，赚我兵出城，乘虚袭我。某愿请精兵三千，伏于要路。太守随后发兵出城，不可远去，止行三十里便回；但看火起为号，前后夹攻，可获大胜。如诸葛亮自来，必为某所擒矣。”遵用其计，付精兵与姜维去讫，然后自与梁虔引兵出城等候；只留梁绪、尹赏守城。原来孔明果遣赵云引一军埋伏于山僻之中，只待天水人马离城，便乘虚袭之。当日细作回报赵云，说天水太守马遵，起兵出城，只留文官守城。赵云大喜，又令人报与张翼、高翔，教于要路截杀马遵。此二处兵亦是孔明预先埋伏。却说赵云引五千兵，径投天水郡城下，高叫曰：“吾乃常山赵子龙也！汝知中计，早献城池，免遭诛戮！”城上梁绪大笑曰：“汝中吾姜伯约之计，尚然不知耶？”云恰待攻城，忽然喊声大震，四面火光冲天。当先一员少年将军，挺枪跃马而言曰：“汝见天水姜伯约乎！”云挺枪直取姜维。战不数合，维精神倍长。云大惊，暗忖曰：“谁想此处有这般人物！”正战时，两路军夹攻来，乃是马遵、梁虔引军杀回。赵云首尾不能相顾，冲开条路，引败兵奔走，姜维赶来。亏得张翼、高翔两路军杀出，接应回去。
赵云归见孔明，说中了敌人之计。孔明惊问曰：“此是何人，识吾玄机？”有南安人告曰：“此人姓姜，名维，字伯约，天水冀人也；事母至孝，文武双全，智勇足备，真当世之英杰也。”赵云又夸奖姜维枪法，与他人大不同。孔明曰：“吾今欲取天水，不想有此人。”遂起大军前来。
却说姜维回见马遵曰：“赵云败去，孔明必然自来。彼料我军必在城中。今可将本部军马，分为四枝：某引一军伏于城东，如彼兵到则截之。太守与梁虔、尹赏各引一军城外埋伏。梁绪率百姓在城上守御。”分拨已定。
却说孔明因虑姜维，自为前部，望天水郡进发。将到城边，孔明传令曰：“凡攻城池，以初到之日，激励三军，鼓噪直上。若迟延日久，锐气尽隳，急难破矣。”于是大军径到城下。因见城上旗帜整齐，未敢轻攻。候至半夜，忽然四下火光冲天，喊声震地，正不知何处兵来。只见城上亦鼓噪呐喊相应，蜀兵乱窜。孔明急上马，有关兴；张苞二将保护，杀出重围。回头看时，正东上军马，一带火光，势若长蛇。孔明令关兴探视，回报曰：“此姜维兵也。”孔明叹曰：“兵不在多，在人之调遣耳。此人真将才也！”收兵归寨，思之良久，乃唤安定人问曰：“姜维之母，现在何处？”答曰：“维母今居冀县。”孔明唤魏延分付曰：“汝可引一军，虚张声势，诈取冀县。若姜维到，可放入城。”又问：“此地何处紧要？”安定人曰：“天水钱粮，皆在上圭阝；若打破上圭阝，则粮道自绝矣。”孔明大喜，教赵云引一军去攻上圭阝。孔明离城三十里下寨。早有人报入天水郡，说蜀兵分为三路：一军守此郡，一军取上圭阝，一军取冀城。姜维闻之，哀告马遵曰：“维母现在冀城，恐母有失。维乞一军往救此城，兼保老母。”马遵从之，遂令姜维引三千军去保冀城；梁虔引三千军去保上圭阝。
却说姜维引兵至冀城，前面一彪军摆开，为首蜀将，乃是魏延。二将交锋数合，延诈败奔走。维入城闭门，率兵守护，拜见老母，并不出战。赵云亦放过梁虔入上邽城去了。孔明乃令人去南安郡，取夏侯楙至帐下。孔明曰：“汝惧死乎？”楙慌拜伏乞命。孔明曰：“目今天水姜维现守冀城，使人持书来说：‘但得驸马在，我愿归降。’吾今饶汝性命，汝肯招安姜维否？”楙曰：“情愿招安。”孔明乃与衣服鞍马，不令人跟随，放之自去。楙得脱出寨，欲寻路而走，奈不知路径。正行之间，逢数人奔走。楙问之，答曰：“我等是冀县百姓；今被姜维献了城池，归降诸葛亮，蜀将魏延纵火劫财，我等因此弃家奔走，投上圭阝去也。”楙又问曰：“今守天水城是谁？”土人曰：“天水城中乃马太守也。”楙闻之，纵马望天水而行。又见百姓携男抱女远来，所说皆同。
楙至天水城下叫门，城上人认得是夏侯楙，慌忙开门迎接。马遵惊拜问之。楙细言姜维之事；又将百姓所言说了。遵叹曰：“不想姜维反投蜀矣！”梁绪曰：“彼意欲救都督，故以此言虚降。”楙曰：“今维已降，何为虚也？”正踌躇间，时已初更，蜀兵又来攻城。火光中见姜维在城下挺枪勒马，大叫曰：“请夏侯都督答话！”夏侯楙与马遵等皆到城上，见姜维耀武扬威大叫曰：“我为都督而降，都督何背前言？”楙曰：“汝受魏恩，何故降蜀？有何前言耶？”维应曰：“汝写书教我降蜀，何出此言？汝要脱身，却将我陷了？我今降蜀，加为上将，安有还魏之理？”言讫，驱兵打城，至晓方退。原来夜间妆姜维者，乃孔明之计，令部卒形貌相似者，假扮姜维攻城，因火光之中，不辨真伪。
孔明却引兵来攻冀城。城中粮少，军食不敷。姜维在城上，见蜀军大车小辆，搬运粮草，入魏延寨中去了。维引三千兵出城，径来劫粮。蜀兵尽弃了粮车，寻路而走。姜维夺得粮车，欲要入城，忽然一彪军拦住，为首蜀将张翼也。二将交锋，战不数合，王平引一军又到，两下夹攻。维力穷抵敌不住，夺路归城；城上早插蜀兵旗号：原来已被魏延袭了。维杀条路奔天水城，手下尚有十余骑；又遇张苞杀了一阵，维止剩得匹马单枪，来到天水城下叫门。城上军见是姜维，慌报马遵。遵曰：“此是姜维来赚我城门也。”令城上乱箭射下。姜维回顾蜀兵至近，遂飞奔上邽城来。城上梁虔见了姜维，大骂曰：“反国之贼，安敢来赚我城池！吾已知汝降蜀矣！”遂乱箭射下。姜维不能分说，仰天长叹，两眼泪流，拨马望长安而走。行不数里，前至一派大树茂林之处，一声喊起，数千兵拥出：为首蜀将关兴，截住去路。
维人困马乏，不能抵当，勒回马便走。忽然一辆小车从山坡中转出。其人头戴纶巾，身披鹤氅，手摇羽扇，乃孔明也。孔明唤姜维曰：“伯约此时何尚不降？”维寻思良久，前有孔明，后有关兴，又无去路，只得下马投降。孔明慌忙下车而迎，执维手曰：“吾自出茅庐以来，遍求贤者，欲传授平生之学，恨未得其人。今遇伯约，吾愿足矣。”维大喜拜谢。
孔明遂同姜维回寨，升帐商议取天水、上圭阝之计。维曰：“天水城中尹赏、梁绪，与某至厚；当写密书二封，射入城中，使其内乱，城可得矣。”孔明从之。姜维写了二封密书，拴在箭上，纵马直至城下，射入城中。小校拾得，呈与马遵。遵大疑，与夏侯楙商议曰：“梁绪、尹赏与姜维结连，欲为内应，都督宜早决之。”楙曰：“可杀二人。”尹赏知此消息，乃谓梁绪曰：“不如纳城降蜀，以图进用。”是夜，夏侯楙数次使人请梁、尹二人说话。二人料知事急，遂披挂上马，各执兵器，引本部军大开城门，放蜀兵入。夏侯楙、马遵惊慌，引数百人出西门，弃城投羌胡城而去。梁绪、尹赏迎接孔明入城。安民已毕，孔明问取上圭阝之计。梁绪曰：“此城乃某亲弟梁虔守之，愿招来降。”孔明大喜。绪当日到上圭阝唤梁虔出城来降孔明。孔明重加赏劳，就令梁绪为天水太守，尹赏为冀城令，梁虔为上圭阝令。孔明分拨已毕，整兵进发。诸将问曰：“丞相何不去擒夏侯楙？”孔明曰：“吾放夏侯楙，如放一鸭耳。今得伯约，得一凤也！”孔明自得三城之后，威声大震，远近州郡，望风归降。孔明整顿军马，尽提汉中之兵，前出祁山，兵临渭水之西。细作报入洛阳。时魏主曹睿太和元年，升殿设朝。近臣奏曰：“夏侯驸马已失三郡，逃窜羌中去了。今蜀兵已到祁山，前军临渭水之西，乞早发兵破敌。”睿大惊，乃问群臣曰：“谁可为朕退蜀兵耶？”司徒王朗出班奏曰：“臣观先帝每用大将军曹真，所到必克；今陛下何不拜为大都督，以退蜀兵？”睿准奏，乃宣曹真曰：“先帝托孤与卿，今蜀兵入寇中原，卿安忍坐视乎？”真奏曰：“臣才疏智浅，不称其职。”王朗曰：“将军乃社稷之臣，不可固辞。老臣虽驽钝，愿随将军一往。”真又奏曰：“臣受大恩，安敢推辞？但乞一人为副将。”睿曰：“卿自举之。”真乃保太原阳曲人，姓郭，名淮，字伯济，官封射亭侯，领雍州刺史。睿从之，遂拜曹真为大都督，赐节钺；命郭淮为副都督，王朗为军师。朗时年已七十六岁矣。选拨东西二京军马二十万与曹真。真命宗弟曹遵为先锋，又命荡寇将军朱赞为副先锋。当年十一月出师，魏主曹睿亲自送出西门之外方回。曹真领大军来到长安，过渭河之西下寨。真与王朗、郭淮共议退兵之策。朗曰：“来日可严整队伍，大展旌旗。老夫自出，只用一席话，管教诸葛亮拱手而降，蜀兵不战自退。”真大喜，是夜传令：来日四更造饭，平明务要队伍整齐，人马威仪，旌旗鼓角，各按次序。当时使人先下战书。次日，两军相迎，列成阵势于祁山之前。蜀军见魏兵甚是雄壮，与夏侯楙大不相同。三军鼓角已罢，司徒王朗乘马而出。上首乃都督曹真，下首乃副都督郭淮；两个先锋压住阵角。探子马出军前，大叫曰：“请对阵主将答话！”只见蜀兵门旗开处，关兴、张苞分左右而出，立马于两边；次后一队队骁将分列；门旗影下，中央一辆四轮车，孔明端坐车中，纶巾羽扇，素衣皂绦，飘然而出。孔明举目见魏阵前三个麾盖，旗上大书姓名：中央白髯老者，乃军师、司徒王朗。孔明暗忖曰：“王朗必下说词，吾当随机应之。”遂教推车出阵外，令护军小校传曰：“汉丞相与司徒会话。”王朗纵马而出。孔明于车上拱手，朗在马上欠身答礼。朗曰：“久闻公之大名，今幸一会。公既知天命、识时务，何故兴无名之兵？”孔明曰：“吾奉诏讨贼，何谓无名？”朗曰：“天数有变，神器更易，而归有德之人，此自然之理也。曩自桓、灵以来，黄巾倡乱，天下争横。降至初平、建安之岁，董卓造逆，傕、汜继虐；袁术僭号于寿春，袁绍称雄于邺土；刘表占据荆州，吕布虎吞徐郡：盗贼蜂起，奸雄鹰扬，社稷有累卵之危，生灵有倒悬之急。我太祖武皇帝，扫清六合席卷八荒；万姓倾心，四方仰德。非以权势取之，实天命所归也。世祖文帝，神文圣武，以膺大统，应天合人，法尧禅舜，处中国以临万邦，岂非天心人意乎？今公蕴大才、抱大器，自欲比于管、乐，何乃强欲逆天理、背人情而行事耶？岂不闻古人曰：‘顺天者昌，逆天者亡。’今我大魏带甲百万，良将千员。谅腐草之萤光，怎及天心之皓月？公可倒戈卸甲，以礼来降，不失封侯之位。国安民乐，岂不美哉！”
孔明在车上大笑曰：“吾以为汉朝大老元臣，必有高论，岂期出此鄙言！吾有一言，诸军静听：昔日桓、灵之世，汉统陵替，宦官酿祸；国乱岁凶，四方扰攘。黄巾之后，董卓、傕、汜等接踵而起，迁劫汉帝，残暴生灵。因庙堂之上，朽木为官，殿陛之间，禽兽食禄；狼心狗行之辈，滚滚当道，奴颜婢膝之徒，纷纷秉政。以致社稷丘墟，苍生涂炭。吾素知汝所行：世居东海之滨，初举孝廉入仕；理合匡君辅国，安汉兴刘；何期反助逆贼，同谋篡位！罪恶深重，天地不容！天下之人，愿食汝肉！今幸天意不绝炎汉，昭烈皇帝继统西川。吾今奉嗣君之旨，兴师讨贼。汝既为谄谀之臣，只可潜身缩首，苟图衣食；安敢在行伍之前，妄称天数耶！皓首匹夫！苍髯老贼！汝即日将归于九泉之下，何面目见二十四帝乎！老贼速退！可教反臣与吾共决胜负！”
王朗听罢，气满胸膛，大叫一声，撞死于马下。后人有诗赞孔明曰：“兵马出西秦，雄才敌万人。轻摇三寸舌，骂死老奸臣。”孔明以扇指曹真曰：“吾不逼汝。汝可整顿军马，来日决战。”言讫回车。于是两军皆退。曹真将王朗尸首，用棺木盛贮，送回长安去了。副都督郭淮曰：“诸葛亮料吾军中治丧，今夜必来劫寨。可分兵四路：两路兵从山僻小路，乘虚去劫蜀寨；两路兵伏于本寨外，左右击之。”曹真大喜曰：“此计与吾相合。”遂传令唤曹遵、朱赞两个先锋分付曰：“汝二人各引一万军，抄出祁山之后。但见蜀兵望吾寨而来，汝可进兵去劫蜀寨。如蜀兵不动，便撤兵回，不可轻进。”二人受计，引兵而去。真谓淮曰：“我两个各引一枝军，伏于寨外，寨中虚堆柴草，只留数人。如蜀兵到，放火为号。”诸将皆分左右，各自准备去了。却说孔明归帐，先唤赵云、魏延听令。孔明曰：“汝二人各引本部军去劫魏寨。”魏延进曰：“曹真深明兵法，必料我乘丧劫寨。他岂不提防？”孔明笑曰：“吾正欲曹真知吾去劫寨也。彼必伏兵在祁山之后，待我兵过去，却来袭我寨；吾故令汝二人，引兵前去，过山脚后路，远下营寨，任魏兵来劫吾寨。汝看火起为号，分兵两路：文长拒住山口；子龙引兵杀回，必遇魏兵，却放彼走回，汝乘势攻之，彼必自相掩杀。可获全胜。”二将引兵受计而去。又唤关兴、张苞分付曰：“汝二人各引一军，伏于祁山要路；放过魏兵，却从魏兵来路，杀奔魏寨而去。”二人引兵受计去了。又令马岱、王平、张翼、张嶷四将，伏于寨外，四面迎击魏兵。孔明乃虚立寨栅，居中堆起柴草，以备火号；自引诸将退于寨后，以观动静。
却说魏先锋曹遵、朱赞黄昏离寨，迤逦前进。二更左侧，遥望山前隐隐有军行动。曹遵自思曰：“郭都督真神机妙算！”遂催兵急进。到蜀寨时，将及三更。曹遵先杀入寨，却是空寨，并无一人。料知中计，急撤军回。寨中火起。朱赞兵到，自相掩杀，人马大乱。曹遵与朱赞交马，方知自相践踏。急合兵时，忽四面喊声大震，王平、马岱、张嶷、张翼杀到。曹、朱二人引心腹军百余骑，望大路奔走。忽然鼓角齐鸣，一彪军截住去路，为首大将乃常山赵子龙也，大叫曰：“贼将那里去？早早受死！”曹、朱二人夺路而走。忽喊声又起，魏延又引一彪军杀到。曹、朱二人大败，夺路奔回本寨。守寨军士，只道蜀兵来劫寨，慌忙放起号火。左边曹真杀至，右边郭淮杀至，自相掩杀。背后三路蜀兵杀到：中央魏延，左边关兴，右边张苞，大杀一阵。魏兵败走十余里，魏将死者极多。孔明全获大胜，方始收兵。曹真、郭淮收拾败军回寨，商议曰：“今魏兵势孤，蜀兵势大，将何策以退之？”淮曰：“胜负乃兵家常事，不足为忧。某有一计，使蜀兵首尾不能相顾，定然自走矣。”正是：可怜魏将难成事，欲向西方索救兵。
未知其计如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943869, '5b9b73b2570c3500635481cf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639233, '三国演义 · 第九十四回 · 诸葛亮乘雪破羌兵 司马懿克日擒孟达', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说郭淮谓曹真曰：“西羌之人，自太祖时连年入贡，文皇帝亦有恩惠加之；我等今可据住险阻，遣人从小路直入羌中求救，许以和亲，羌人必起兵袭蜀兵之后。吾却以大兵击之，首尾夹攻，岂不大胜？”真从之，即遣人星夜驰书赴羌。
却说西羌国王彻里吉，自曹操时年年入贡；手下有一文一武：文乃雅丹丞相，武乃越吉元帅。时魏使赍金珠并书到国，先来见雅丹丞相，送了礼物，具言求救之意。雅丹引见国王，呈上书礼。彻里吉览了书，与众商议。雅丹曰：“我与魏国素相往来，今曹都督求救，且许和亲，理合依允。”彻里吉从其言，即命雅丹与越吉元帅起羌兵一十五万，皆惯使弓弩、枪刀、蒺藜、飞锤等器；又有战车，用铁叶裹钉，装载粮食军器什物：或用骆驼驾车，或用骡马驾车，号为“铁车兵”。二人辞了国王，领兵直扣西平关。守关蜀将韩祯，急差人赍文报知孔明。孔明闻报，问众将曰：“谁敢去退羌兵？”张苞、关兴应曰：“某等愿往。”孔明曰：“汝二人要去，奈路途不熟。”遂唤马岱曰：“汝素知羌人之性，久居彼处，可作向导。”便起精兵五万，与兴、苞二人同往。兴、苞等引兵而去。行有数日，早遇羌兵。关兴先引百余骑登山坡看时，只见羌兵把铁车首尾相连，随处结寨；车上遍排兵器，就似城池一般。兴睹之良久，无破敌之策，回寨与张苞、马岱商议。岱曰：“且待来日见阵，观看虚实，另作计议。”次早，分兵三路：关兴在中，张苞在左，马岱在右，三路兵齐进。羌兵阵里，越吉元帅手挽铁锤，腰悬宝雕弓，跃马奋勇而出。关兴招三路兵径进。忽见羌兵分在两边，中央放出铁车，如潮涌一般，弓弩一齐骤发。蜀兵大败，马岱、张苞两军先退；关兴一军，被羌兵一裹，直围入西北角上去了。
兴在垓心，左冲右突，不能得脱；铁车密围，就如城池。蜀兵你我不能相顾。兴望山谷中寻路而走。看看天晚，但见一簇皂旗，蜂拥而来，一员羌将，手提铁锤大叫曰：“小将休走！吾乃越吉元帅也！”关兴急走到前面，尽力纵马加鞭，正遇断涧，只得回马来战越吉。兴终是胆寒，抵敌不住，望涧中而逃；被越吉赶到，一铁锤打来，兴急闪过，正中马胯。那马望涧中便倒，兴落于水中。忽听得一声响处，背后越吉连人带马，平白地倒下水来。兴就水中挣起看时，只见岸上一员大将，杀退羌兵。兴提刀待砍越吉，吉跃水而走。关兴得了越吉马，牵到岸上，整顿鞍辔，绰刀上马。只见那员将，尚在前面追杀羌兵。兴自思此人救我性命，当与相见，遂拍马赶来。看看至近，只见云雾之中，隐隐有一大将，面如重枣，眉若卧蚕，绿袍金铠，提青龙刀，骑赤兔马，手绰美髯，分明认得是父亲关公。兴大惊。忽见关公以手望东南指曰：“吾儿可速望此路去。吾当护汝归寨。”言讫不见。关兴望东南急走。至半夜，忽一彪军到，乃张苞也，问兴曰：“你曾见二伯父否？”兴曰：“你何由知之？”苞曰：“我被铁车军追急，忽见伯父自空而下，惊退羌兵，指曰：‘汝从这条路去救吾儿。’因此引军径来寻你。’关兴亦说前事，共相嗟异。二人同归寨内。马岱接着，对二人说：“此军无计可退。我守住寨栅，你二人去禀丞相，用计破之。”于是兴、苞二人，星夜来见孔明，备说此事。孔明随命赵云、魏延各引一军埋伏去讫；然后点三万军，带了姜维、张冀、关兴、张苞，亲自来到马岱寨中歇定。次日上高阜处观看，见铁车连络不绝，人马纵横，往来驰骤。孔明曰：“此不难破也。”唤马岱、张冀分付如此如此。二人去了，乃唤姜维曰：“伯约知破车之法否？”维曰：“羌人惟恃一勇力，岂知妙计乎？”孔明笑曰：“汝知吾心也。今彤云密布，朔风紧急，天将降雪，吾计可施矣。”便令关兴、张苞二人引兵埋伏去讫；令姜维领兵出战：但有铁车兵来，退后便走；寨口虚立旌旗，不设军马。准备已定。
是时十二月终，果然天降大雪。姜维引军出，越吉引铁车兵来。姜维即退走。羌兵赶到寨前，姜维从寨后而去。羌兵直到寨外观看，听得寨内鼓琴之声，四壁皆空竖旌旗，急回报越吉。越吉心疑，未敢轻进。雅丹丞相曰：“此诸葛亮诡计，虚设疑兵耳。可以攻之。”越吉引兵至寨前，但见孔明携琴上车，引数骑入寨，望后而走。羌兵抢入寨栅，直赶过山口，见小车隐隐转入林中去了。雅丹谓越吉曰：“这等兵虽有埋伏，不足为惧。”遂引大兵追赶。又见姜维兵俱在雪地之中奔走。越吉大怒，催兵急追。山路被雪漫盖，一望平坦。正赶之间，忽报蜀兵自山后而出。雅丹曰：“纵有些小伏兵，何足惧哉！”只顾催趱兵马，往前进发。忽然一声响，如山崩地陷，羌兵俱落于坑堑之中；背后铁车正行得紧溜，急难收止，并拥而来，自相践踏。后兵急要回时，左边关兴、右边张苞，两军冲出，万弩齐发；背后姜维、马岱、张冀三路兵又杀到。铁车兵大乱。越吉元帅望后面山谷中而逃，正逢关兴；交马只一合，被兴举刀大喝一声，砍死于马下。雅丹丞相早被马岱活捉，解投大寨来。羌兵四散逃窜。孔明升帐，马岱押过雅丹来。孔明叱武士去其缚，赐酒压惊，用好言抚慰。雅丹深感其德。孔明曰：“吾主乃大汉皇帝，今命吾讨贼，尔如何反助逆？吾今放汝回去，说与汝主：吾国与尔乃邻邦，永结盟好，勿听反贼之言。”遂将所获羌兵及车马器械，尽给还雅丹，俱放回国。众皆拜谢而去。孔明引三军连夜投祁山大寨而来，命关兴、张苞引军先行；一面差人赍表奏报捷音。
却说曹真连日望羌人消息，忽有伏路军来报说：“蜀兵拔寨收拾起程。”郭淮大喜曰：“此因羌兵攻击，故尔退去。”遂分两路追赶。前面蜀兵乱走，魏兵随后追袭。先锋曹遵正赶之间，忽然鼓声大震，一彪军闪出，为首大将乃魏延也，大叫曰：“反贼休走！”曹遵大惊，拍马交锋；不三合，被魏延一刀斩于马下。副先锋朱赞引兵追赶，忽然一彪军闪出，为首大将乃赵云也。朱赞措手不及，被云一枪刺死。曹真、郭淮见西路先锋有失，欲收兵回；背后喊声大震，鼓角齐鸣：关兴、张苞两路兵杀出，围了曹真、郭淮，痛杀一阵。曹、郭二人，引败兵冲路走脱。蜀兵全胜，直追到渭水，夺了魏寨。曹真折了两个先锋，哀伤不已；只得写本申朝，乞拨援兵。
却说魏主曹睿设朝，近臣奏曰：“大都督曹真，数败于蜀，折了两个先锋，羌兵又折了无数，其势甚急，今上表求救，请陛下裁处。”睿大惊，急问退军之策。华歆奏曰：“须是陛下御驾亲征，大会诸侯，人皆用命，方可退也。不然，长安有失，关中危矣！”太傅钟繇奏曰：“凡为将者，智过于人，则能制人。孙子云：‘知彼知己，百战百胜。’臣量曹真虽久用兵，非诸葛亮对手。臣以全家良贱，保举一人，可退蜀兵。未知圣意准否？”睿曰：“卿乃大老元臣，有何贤士，可退蜀兵，早召来与朕分忧。”钟繇奏曰：“向者，诸葛亮欲兴师犯境，但惧此人，故散流言，使陛下疑而去之，方敢长驱大进。今若复用之，则亮自退矣。”睿问何人。繇曰：“骠骑大将军司马懿也。”睿叹曰：“此事朕亦悔之。今仲达现在何地？”繇曰：“近闻仲达在宛城闲住。”睿即降诏，遣使持节，复司马懿官职，加为平西都督，就起南阳诸路军马，前赴长安。睿御驾亲征，令司马懿克日到彼聚会。使命星夜望宛城去了。
却说孔明自出师以来，累获全胜，心中甚喜；正在祁山寨中，会聚议事，忽报镇守永安宫李严令子李丰来见。孔明只道东吴犯境，心甚惊疑，唤入帐中问之。丰曰：“特来报喜。”孔明曰：“有何喜？”丰曰：“昔日孟达降魏，乃不得已也。彼时曹丕爱其才，时以骏马金珠赐之，曾同辇出入，封为散骑常侍，领新城太守，镇守上庸、金城等处，委以西南之任。自丕死后，曹睿即位，朝中多人嫉妒，孟达日夜不安，常谓诸将曰：‘我本蜀将，势逼于此。’今累差心腹人，持书来见家父，教早晚代禀丞相：前者五路下川之时，曾有此意；今在新城，听知丞相伐魏，欲起金城、新城、上庸三处军马，就彼举事，径取洛阳：丞相取长安，两京大定矣。今某引来人并累次书信呈上。”孔明大喜，厚赏李丰等。
忽细作人报说：“魏主曹睿，一面驾幸长安；一面诏司马懿复职，加为平西都督，起本处之兵，于长安聚会。”孔明大惊。参军马谡曰：“量曹睿何足道！若来长安，可就而擒之。丞相何故惊讶？”孔明曰：“吾岂惧曹睿耶？所患者惟司马懿一人而已。今孟达欲举大事，若遇司马懿，事必败矣。达非司马懿对手，必被所擒。孟达若死，中原不易得也。”马谡曰：“何不急修书，令孟达提防？’孔明从之，即修书令来人星夜回报孟达。却说孟达在新城，专望心腹人回报。一日，心腹人到来，将孔明回书呈上。孟达拆封视之。书略曰：“近得书，足知公忠义之心，不忘故旧，吾甚喜慰。若成大事，则公汉朝中兴第一功臣也。然极宜谨密，不可轻易托人。慎之！戒之！近闻曹睿复诏司马懿起宛、洛之兵，若闻公举事，必先至矣。须万全提备，勿视为等闲也。”孟达览毕，笑曰：“人言孔明心多，今观此事可知矣。”乃具回书，令心腹人来答孔明。孔明唤入帐中。其人呈上回书。孔明拆封视之。书曰：“适承钧教，安敢少怠。窃谓司马懿之事，不必惧也：宛城离洛阳约八百里，至新城一千二百里。若司马懿闻达举事，须表奏魏主。往复一月间事，达城池已固，诸将与三军皆在深险之地。司马懿即来，达何惧哉？丞相宽怀，惟听捷报！”
孔明看毕，掷书于地而顿足曰：“孟达必死于司马懿之手矣！”马谡问曰：“丞相何谓也？”孔明曰：“兵法云，攻其不备，出其不意。岂容料在一月之期？曹睿既委任司马懿，逢寇即除，何待奏闻？若知孟达反，不须十日，兵必到矣，安能措手耶？”众将皆服。孔明急令来人回报曰：“若未举事，切莫教同事者知之；知则必败。”其人拜辞，归新城去了。
却说司马懿在宛城闲住，闻知魏兵累败于蜀，乃仰天长叹。懿长子司马师，字子元；次子司马昭，字子尚：二人素有大志，通晓兵书。当日侍立于侧，见懿长叹，乃问曰：“父亲何为长叹？”懿曰：“汝辈岂知大事耶？”司马师曰：“莫非叹魏主不用乎？”司马昭笑曰：“早晚必来宣召父亲也。”言未已，忽报天使持节至。懿听诏毕，遂调宛城诸路军马。忽又报金城太守申仪家人，有机密事求见。懿唤入密室问之，其人细说孟达欲反之事。更有孟达心腹人李辅并达外甥邓贤，随状出首。司马懿听毕，以手加额曰：“此乃皇上齐天之洪福也！诸葛亮兵在祁山，杀得内外人皆胆落；今天子不得已而幸长安，若旦夕不用吾时，孟达一举，两京休矣！此贼必通谋诸葛亮。吾先擒之，诸葛亮定然心寒，自退兵也。”长子司马师曰：“父亲可急写表申奏天子。”懿曰：“若等圣旨，往复一月之间，事无及矣。”即传令教人马起程，一日要行二日之路，如迟立斩；一面令参军梁畿赍檄星夜去新城，教孟达等准备征进，使其不疑。梁畿先行，懿随后发兵。行了二日，山坡下转出一军，乃是右将军徐晃。晃下马见懿，说：“天子驾到长安，亲拒蜀兵，今都督何往？”懿低言曰：“今孟达造反，吾去擒之耳。”晃曰：“某愿为先锋。”懿大喜，合兵一处。徐晃为前部，懿在中军，二子押后。又行了二日，前军哨马捉住孟达心腹人，搜出孔明回书，来见司马懿。懿曰：“吾不杀汝，汝从头细说。”其人只得将孔明、孟达往复之事，一一告说。懿看了孔明回书，大惊曰：“世间能者所见皆同。吾机先被孔明识破。幸得天子有福，获此消息：孟达今无能为矣。”遂星夜催军前行。
却说孟达在新城，约下金城太守申仪、上庸太守申耽，克日举事。耽、仪二人佯许之，每日调练军马，只待魏兵到，便为内应；却报孟达言：军器粮草，俱未完备，不敢约期起事。达信之不疑。忽报参军梁畿来到，孟达迎入城中。畿传司马懿将令曰：“司马都督今奉天子诏，起诸路军以退蜀兵。太守可集本部军马听候调遣。”达问曰：“都督何日起程？”畿曰：“此时约离宛城，望长安去了。”达暗喜曰：“吾大事成矣！”遂设宴待了梁畿，送出城外，即报申耽、申仪知道，明日举事，换上大汉旗号，发诸路军马，径取洛阳。忽报：“城外尘土冲天，不知何处兵来。”孟达登城视之，只见一彪军，打着“右将军徐晃”旗号，飞奔城下。达大惊，急扯起吊桥。徐晃坐下马收拾不住，直来到壕边，高叫曰：“反贼孟达，早早受降！”达大怒，急开弓射之，正中徐晃头额，魏将救去。城上乱箭射下，魏兵方退。孟达恰待开门追赶，四面旌旗蔽日，司马懿兵到。达仰天长叹曰：“果不出孔明所料也！”于是闭门坚守。却说徐晃被孟达射中头额，众军救到寨中，取了箭头，令医调治；当晚身死，时年五十九岁。司马懿令人扶柩还洛阳安葬。次日，孟达登城遍视，只见魏兵四面围得铁桶相似。达行坐不安，惊疑未定，忽见两路兵自外杀来，旗上大书“申耽”、“申仪”。孟达只道是救军到，忙引本部兵大开城门杀出。耽、仪大叫曰：“反贼休走！早早受死！”达见事变，拨马望城中便走，城上乱箭射下。李辅、邓贤二人在城上大骂曰：“吾等已献了城也！”达夺路而走，申耽赶来。达人困马乏，措手不及，被申耽一枪刺于马下，枭其首级。余军皆降。李辅、邓贤大开城门，迎接司马懿入城。抚民劳军已毕，遂遣人奏知魏主曹睿。睿大喜，教将孟达首级去洛阳城市示众；加申耽、申仪官职，就随司马懿征进；命李辅、邓贤守新城、上庸。却说司马懿引兵到长安城外下寨。懿入城来见魏主。睿大喜曰：“朕一时不明，误中反间之计，悔之无及。今达造反，非卿等制之，两京休矣！”懿奏曰：“臣闻申仪密告反情，意欲表奏陛下，恐往复迟滞，故不待圣旨，星夜而去。若待奏闻，则中诸葛亮之计也。”言罢，将孔明回孟达密书奉上。睿看毕，大喜曰：“卿之学识，过于孙、吴矣！”赐金钺斧一对，后遇机密重事，不必奏闻，便宜行事。就令司马懿出关破蜀。懿奏曰：“臣举一大将，可为先锋。”睿曰：“卿举何人？”懿曰：“右将军张郃，可当此任。”睿笑曰：“朕正欲用之。”遂命张郃为前部先锋，随司马懿离长安来破蜀兵。正是：既有谋臣能用智，又求猛将助施威。
未知胜负如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943869, '5b9b73cd17d009003417abb2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639234, '三国演义· 第九十五回 · 马谡拒谏失街亭 武侯弹琴退仲达', NULL, 2, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', ' 却说魏主曹睿令张郃为先锋，与司马懿一同征进；一面令辛毗、孙礼二人领兵五万，往助曹真。二人奉诏而去。且说司马懿引二十万军，出关下寨，请先锋张郃至帐下曰：“诸葛亮平生谨慎，未敢造次行事。若是吾用兵，先从子午谷径取长安，早得多时矣。他非无谋，但怕有失，不肯弄险。今必出军斜谷，来取郿城。若取郿城，必分兵两路，一军取箕谷矣。吾已发檄文，令子丹拒守郿城，若兵来不可出战；令孙礼、辛毗截住箕谷道口，若兵来则出奇兵击之。”郃曰：“今将军当于何处进兵？”懿曰：“吾素知秦岭之西，有一条路，地名街亭；傍有一城，名列柳城：此二处皆是汉中咽喉。诸葛亮欺子丹无备，定从此进。吾与汝径取街亭，望阳平关不远矣。亮若知吾断其街亭要路，绝其粮道，则陇西一境，不能安守，必然连夜奔回汉中去也。彼若回动，吾提兵于小路击之，可得全胜；若不归时，吾却将诸处小路，尽皆垒断，俱以兵守之。一月无粮，蜀兵皆饿死，亮必被吾擒矣。”张郃大悟，拜伏于地曰：“都督神算也！”懿曰：“虽然如此，诸葛亮不比孟达。将军为先锋，不可轻进。当传与诸将：循山西路，远远哨探。如无伏兵，方可前进。若是怠忽，必中诸葛亮之计。”张郃受计引军而行。
却说孔明在祁山寨中，忽报新城探细人来到。孔明急唤入问之，细作告曰：“司马懿倍道而行，八日已到新城，孟达措手不及；又被申耽、申仪、李辅、邓贤为内应：孟达被乱军所杀。今司马懿撤兵到长安，见了魏主，同张郃引兵出关，来拒我师也。”孔明大惊曰：“孟达做事不密，死固当然。今司马懿出关，必取街亭，断吾咽喉之路。”便问：“谁敢引兵去守街亭？”言未毕，参军马谡曰：“某愿往。”孔明曰：“街亭虽小，干系甚重：倘街亭有失，吾大军皆休矣。汝虽深通谋略，此地奈无城郭，又无险阻，守之极难。”谡曰：“某自幼熟读兵书，颇知兵法。岂一街亭不能守耶？”孔明曰：“司马懿非等闲之辈；更有先锋张郃，乃魏之名将：恐汝不能敌之。”谡曰：“休道司马懿、张郃，便是曹睿亲来，有何惧哉！若有差失，乞斩全家。”孔明曰：“军中无戏言。”谡曰：“愿立军令状。”孔明从之，谡遂写了军令状呈上。孔明曰：“吾与汝二万五千精兵，再拨一员上将，相助你去。”即唤王平分付曰：“吾素知汝平生谨慎，故特以此重任相托。汝可小心谨守此地：下寨必当要道之处，使贼兵急切不能偷过。安营既毕，便画四至八道地理形状图本来我看。凡事商议停当而行，不可轻易。如所守无危，则是取长安第一功也。戒之！戒之！”二人拜辞引兵而去。孔明寻思，恐二人有失，又唤高翔曰：“街亭东北上有一城，名列柳城，乃山僻小路，此可以屯兵扎寨。与汝一万兵，去此城屯扎。但街亭危，可引兵救之。”高翔引兵而去。孔明又思：高翔非张郃对手，必得一员大将，屯兵于街亭之右，方可防之，遂唤魏延引本部兵去街亭之后屯扎。延曰：“某为前部，理合当先破敌，何故置某于安闲之地？’孔明曰：“前锋破敌，乃偏裨之事耳。今令汝接应街亭，当阳平关冲要道路，总守汉中咽喉：此乃大任也，何为安闲乎？汝勿以等闲视之，失吾大事。切宜小心在意！”魏延大喜，引兵而去。孔明恰才心安，乃唤赵云、邓芝分付曰：“今司马懿出兵，与旧日不同。汝二人各引一军出箕谷，以为疑兵。如逢魏兵，或战、或不战，以惊其心。吾自统大军，由斜谷径取郿城；若得郿城，长安可破矣。”二人受命而去。孔明令姜维作先锋，兵出斜谷。
却说马谡、王平二人兵到街亭，看了地势。马谡笑曰：“丞相何故多心也？量此山僻之处，魏兵如何敢来！”王平曰：“虽然魏兵不敢来，可就此五路总口下寨；却令军士伐木为栅，以图久计。”谡曰：“当道岂是下寨之地？此处侧边一山，四面皆不相连，且树木极广，此乃天赐之险也：可就山上屯军。”平曰：“参军差矣。若屯兵当道，筑起城垣，贼兵总有十万，不能偷过；今若弃此要路，屯兵于山上，倘魏兵骤至，四面围定，将何策保之？”谡大笑曰：“汝真女子之见！兵法云：‘凭高视下，势如劈竹。’若魏兵到来，吾教他片甲不回！”平曰：“吾累随丞相经阵，每到之处，丞相尽意指教。今观此山，乃绝地也：若魏兵断我汲水之道，军士不战自乱矣。”谡曰：“汝莫乱道！孙子云：‘置之死地而后生。’若魏兵绝我汲水之道，蜀兵岂不死战？以一可当百也。吾素读兵书，丞相诸事尚问于我，汝奈何相阻耶！”平曰：“若参军欲在山上下寨，可分兵与我，自于山西下一小寨，为掎角之势。倘魏兵至，可以相应。”马谡不从。忽然山中居民，成群结队，飞奔而来，报说魏兵已到。王平欲辞去。马谡曰：“汝既不听吾令，与汝五千兵自去下寨。待吾破了魏兵，到丞相面前须分不得功！”王平引兵离山十里下寨，画成图本，星夜差人去禀孔明，具说马谡自于山上下寨。却说司马懿在城中，令次子司马昭去探前路：若街亭有兵守御，即当按兵不行。司马昭奉令探了一遍，回见父曰：“街亭有兵守把。”懿叹曰：“诸葛亮真乃神人，吾不如也！”昭笑曰：“父亲何故自堕志气耶？男料街亭易取。”懿问曰：“汝安敢出此大言？”昭曰：“男亲自哨见，当道并无寨栅，军皆屯于山上，故知可破也。”懿大喜曰：“若兵果在山上，乃天使吾成功矣！”遂更换衣服，引百余骑亲自来看。是夜天晴月朗，直至山下，周围巡哨了一遍，方回。马谡在山上见之，大笑曰：“彼若有命，不来围山！”传令与诸将：“倘兵来，只见山顶上红旗招动，即四面皆下。”
却说司马懿回到寨中，使人打听是何将引兵守街亭。回报曰：“乃马良之弟马谡也。”懿笑曰：“徒有虚名，乃庸才耳！孔明用如此人物，如何不误事！”又问：“街亭左右别有军否？”探马报曰：“离山十里有王平安营。”懿乃命张郃引一军，当住王平来路。又令申耽、申仪引两路兵围山，先断了汲水道路；待蜀兵自乱，然后乘势击之。当夜调度已定。次日天明，张郃引兵先往背后去了。司马懿大驱军马，一拥而进，把山四面围定。马谡在山上看时，只见魏兵漫山遍野，旌旗队伍，甚是严整。蜀兵见之，尽皆丧胆，不敢下山。马谡将红旗招动，军将你我相推，无一人敢动。谡大怒，自杀二将。众军惊惧，只得努力下山来冲魏兵。魏兵端然不动。蜀兵又退上山去。马谡见事不谐，教军紧守寨门，只等外应。
却说王平见魏兵到，引军杀来，正遇张郃；战有数十余合，平力穷势孤，只得退去。魏兵自辰时困至戌时，山上无水，军不得食，寨中大乱。嚷到半夜时分，山南蜀兵大开寨门，下山降魏。马谡禁止不住。司马懿又令人于沿山放火，山上蜀兵愈乱。马谡料守不住，只得驱残兵杀下山西逃奔。司马懿放条大路，让过马谡。背后张郃引兵追来。赶到三十余里，前面鼓角齐鸣，一彪军出，放过马谡，拦住张郃；视之，乃魏延也。延挥刀纵马，直取张郃。郃回军便走。延驱兵赶来，复夺街亭。赶到五十余里，一声喊起，两边伏兵齐出：左边司马懿，右边司马昭，却抄在魏延背后，把延困在垓心。张郃复来，三路兵合在一处。魏延左冲右突，不得脱身，折兵大半。正危急间，忽一彪军杀入，乃王平也。延大喜曰：“吾得生矣！”二将合兵一处，大杀一阵，魏兵方退。二将慌忙奔回寨时，营中皆是魏兵旌旗。申耽、申仪从营中杀出。王平、魏延径奔列柳城，来投高翔。此时高翔闻知街亭有失，尽起列柳城之兵，前来救应，正遇延、平二人，诉说前事。高翔曰：“不如今晚去劫魏寨，再复街亭。”当时三人在山坡下商议已定。待天色将晚，兵分三路。魏延引兵先进，径到街亭，不见一人，心中大疑，未敢轻进，且伏在路口等候，忽见高翔兵到，二人共说魏兵不知在何处。正没理会，又不见王平兵到。忽然一声炮响，火光冲天，鼓声震地：魏兵齐出，把魏延、高翔围在垓心。二人往来冲突，不得脱身。忽听得山坡后喊声若雷，一彪军杀入，乃是王平，救了高、魏二人，径奔列柳城来。比及奔到城下时，城边早有一军杀到，旗上大书“魏都督郭淮”字样。原来郭淮与曹真商议，恐司马懿得了全功，乃分淮来取街亭；闻知司马懿、张郃成了此功，遂引兵径袭列柳城。正遇三将，大杀一阵。蜀兵伤者极多。魏延恐阳平关有失，慌与王平、高翔望阳平关来。
却说郭淮收了军马，乃谓左右曰：“吾虽不得街亭，却取了列柳城，亦是大功。”引兵径到城下叫门，只见城上一声炮响，旗帜皆竖，当头一面大旗，上书“平西都督司马懿”。懿撑起悬空板，倚定护心木栏干，大笑曰：“郭伯济来何迟也？”淮大惊曰：“仲达神机，吾不及也！”遂入城。相见已毕，懿曰：“今街亭已失，诸葛亮必走。公可速与子丹星夜追之。”郭淮从其言，出城而去。懿唤张郃曰：“子丹、伯济，恐吾全获大功，故来取此城池。吾非独欲成功，乃侥幸而已。吾料魏延、王平、马谡、高翔等辈，必先去据阳平关。吾若去取此关，诸葛亮必随后掩杀，中其计矣。兵法云：‘归师勿掩，穷寇莫追。’汝可从小路抄箕谷退兵。吾自引兵当斜谷之兵。若彼败走，不可相拒，只宜中途截住：蜀兵辎重，可尽得也。”张郃受计，引兵一半去了。懿下令：“竟取斜谷，由西城而进。西城虽山僻小县，乃蜀兵屯粮之所，又南安、天水、安定三郡总路。若得此城，三郡可复矣。”于是司马懿留申耽、申仪守列柳城，自领大军望斜谷进发。
却说孔明自令马谡等守街亭去后，犹豫不定。忽报王平使人送图本至。孔明唤入，左右呈上图本。孔明就文几上拆开视之，拍案大惊曰：“马谡无知，坑陷吾军矣！”左右问曰：“丞相何故失惊？”孔明曰：“吾观此图本，失却要路，占山为寨。倘魏兵大至，四面围合，断汲水道路，不须二日，军自乱矣。若街亭有失，吾等安归？”长史杨仪进曰：“某虽不才，愿替马幼常回。”孔明将安营之法，一一分付与杨仪。正待要行，忽报马到来，说：“街亭、列柳城，尽皆失了！”孔明跌足长叹曰：“大事去矣！此吾之过也！”急唤关兴、张苞分付曰：“汝二人各引三千精兵，投武功山小路而行。如遇魏兵，不可大击，只鼓噪呐喊，为疑兵惊之。彼当自走，亦不可追。待军退尽，便投阳平关去。”又令张冀先引军去修理剑阁，以备归路。又密传号令，教大军暗暗收拾行装，以备起程。又令马岱、姜维断后，先伏于山谷中，待诸军退尽，方始收兵。又差心腹人，分路报与天水、南安、安定三郡官吏军民，皆入汉中。又遣心腹人到冀县搬取姜维老母，送入汉中。
孔明分拨已定，先引五千兵退去西城县搬运粮草。忽然十余次飞马报到，说：“司马懿引大军十五万，望西城蜂拥而来！”时孔明身边别无大将，只有一班文官，所引五千军，已分一半先运粮草去了，只剩二千五百军在城中。众官听得这个消息，尽皆失色。孔明登城望之，果然尘土冲天，魏兵分两路望西城县杀来。孔明传令，教“将旌旗尽皆隐匿；诸军各守城铺，如有妄行出入，及高言大语者，斩之！大开四门，每一门用二十军士，扮作百姓，洒扫街道。如魏兵到时，不可擅动，吾自有计。”孔明乃披鹤氅，戴纶巾，引二小童携琴一张，于城上敌楼前，凭栏而坐，焚香操琴。
却说司马懿前军哨到城下，见了如此模样，皆不敢进，急报与司马懿。懿笑而不信，遂止住三军，自飞马远远望之。果见孔明坐于城楼之上，笑容可掬，焚香操琴。左有一童子，手捧宝剑；右有一童子，手执麈尾。城门内外，有二十余百姓，低头洒扫，傍若无人，懿看毕大疑，便到中军，教后军作前军，前军作后军，望北山路而退。次子司马昭曰：“莫非诸葛亮无军，故作此态？父亲何故便退兵？”懿曰：“亮平生谨慎，不曾弄险。今大开城门，必有埋伏。我兵若进，中其计也。汝辈岂知？宜速退。”于是两路兵尽皆退去。孔明见魏军远去，抚掌而笑。众官无不骇然，乃问孔明曰：“司马懿乃魏之名将，今统十五万精兵到此，见了丞相，便速退去，何也？”孔明曰：“此人料吾生平谨慎，必不弄险；见如此模样，疑有伏兵，所以退去。吾非行险，盖因不得已而用之。此人必引军投山北小路去也。吾已令兴、苞二人在彼等候。”众皆惊服曰：“丞相之机，神鬼莫测。若某等之见，必弃城而走矣。”孔明曰：“吾兵止有二千五百，若弃城而走，必不能远遁。得不为司马懿所擒乎？”后人有诗赞曰：“瑶琴三尺胜雄师，诸葛西城退敌时。十五万人回马处，土人指点到今疑。”言讫，拍手大笑，曰：“吾若为司马懿，必不便退也。”遂下令，教西城百姓，随军入汉中；司马懿必将复来。于是孔明离西城望汉中而走。天水、安定、南安三郡官吏军民，陆续而来。
却说司马懿望武功山小路而走。忽然山坡后喊杀连天，鼓声震地。懿回顾二子曰：“吾若不走，必中诸葛亮之计矣。”只见大路上一军杀来，旗上大书“右护卫使虎冀将军张苞”。魏兵皆弃甲抛戈而走。行不到一程，山谷中喊声震地，鼓角喧天，前面一杆大旗，上书“左护卫使龙骧将军关兴”。山谷应声，不知蜀兵多少；更兼魏军心疑，不敢久停，只得尽弃辎重而去。兴、苞二人皆遵将令，不敢追袭，多得军器粮草而归。司马懿见山谷中皆有蜀兵，不敢出大路，遂回街亭。
此时曹真听知孔明退兵，急引兵追赶。山背后一声炮响，蜀兵漫山遍野而来：为首大将，乃是姜维、马岱。真大惊，急退军时，先锋陈造已被马岱所斩。真引兵鼠窜而还。蜀兵连夜皆奔回汉中。却说赵云、邓芝伏兵于箕谷道中。闻孔明传令回军，云谓芝曰：“魏军知吾兵退，必然来追。吾先引一军伏于其后，公却引兵打吾旗号，徐徐而退。吾一步步自有护送也。
却说郭淮提兵再回箕谷道中，唤先锋苏颙分付曰：“蜀将赵云，英勇无敌。汝可小心提防，彼军若退，必有计也。”苏颙欣然曰：“都督若肯接应，某当生擒赵云。”遂引前部三千兵，奔入箕谷。看看赶上蜀兵，只见山坡后闪出红旗白字，上书“赵云”。苏颙急收兵退走。行不到数里，喊声大震，一彪军撞出：为首大将，挺枪跃马，大喝曰：“汝识赵子龙否！”苏颙大惊曰：“如何这里又有赵云？”措手不及，被云一枪刺死于马下。余军溃散。云迤逦前进，背后又一军到，乃郭淮部将万政也。云见魏兵追急，乃勒马挺枪，立于路口，待来将交锋。蜀兵已去三十余里。万政认得是赵云，不敢前进，云等得天色黄昏，方才拨回马缓缓而进。郭淮兵到，万政言赵云英勇如旧，因此不敢近前。淮传令教军急赶，政令数百骑壮士赶来。行至一大林，忽听得背后大喝一声曰：“赵子龙在此！”惊得魏兵落马者百余人，余者皆越岭而去。万政勉强来敌，被云一箭射中盔缨，惊跌于涧中。云以枪指之曰：“吾饶汝性命回去！快教郭淮赶来！”万政脱命而回。云护送车仗人马，望汉中而去，沿途并无遗失。曹真、郭淮复夺三郡，以为己功。却说司马懿分兵而进。此时蜀兵尽回汉中去了，懿引一军复到西城，因问遗下居民及山僻隐者，皆言孔明止有二千五百军在城中，又无武将，只有几个文官，别无埋伏。武功山小民告曰：“关兴、张苞，只各有三千军，转山呐喊，鼓噪惊追，又无别军，并不敢厮杀。”懿悔之不及，仰天叹曰：“吾不如孔明也！”遂安抚了诸处官民，引兵径还长安，朝见魏主。睿曰：“今日复得陇西诸郡，皆卿之功也。”懿奏曰：“今蜀兵皆在汉中，未尽剿灭。臣乞大兵并力收川，以报陛下。”睿大喜，令懿即便兴兵。忽班内一人出奏曰：“臣有一计，足可定蜀降吴。”正是：蜀中将相方归国，魏地君臣又逞谋。
未知献计者是谁，且看下文分解。
', '', '', '', NULL, '', 'indent', 1536944091, '5b9b73e6fb4ffe005cb035f7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639235, '三国演义 · 第九十六回 · 孔明挥泪斩马谡 周鲂断发赚曹休', NULL, 4, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说献计者，乃尚书孙资也。曹睿问曰：“卿有何妙计？”资奏曰：“昔太祖武皇帝收张鲁时，危而后济；常对群臣曰：‘南郑之地，真为天狱。’中斜谷道为五百里石穴，非用武之地。今若尽起天下之兵伐蜀，则东吴又将入寇。不如以现在之兵，分命大将据守险要，养精蓄锐。不过数年，中国日盛，吴、蜀二国必自相残害：那时图之，岂非胜算？乞陛下裁之。”睿乃问司马懿曰：“此论若何？懿奏曰：“孙尚书所言极当。”睿从之，命懿分拨诸将守把险要，留郭淮、张郃守长安。大赏三军，驾回洛阳。却说孔明回到汉中，计点军士，只少赵云、邓芝，心中甚忧；乃令关兴、张苞，各引一军接应。二人正欲起身，忽报赵云、邓芝到来，并不曾折一人一骑；辎重等器，亦无遗失。孔明大喜，亲引诸将出迎。赵云慌忙下马伏地曰：“败军之将，何劳丞相远接？”孔明急扶起，执手而言曰：“是吾不识贤愚，以致如此！各处兵将败损，惟子龙不折一人一骑，何也？”邓芝告曰：“某引兵先行，子龙独自断后，斩将立功，敌人惊怕，因此军资什物，不曾遗弃。”孔明曰：“真将军也！”遂取金五十斤以赠赵云，又取绢一万匹赏云部卒。云辞曰：“三军无尺寸之功，某等俱各有罪；若反受赏，乃丞相赏罚不明也。且请寄库，候今冬赐与诸军未迟。”孔明叹曰：“先帝在日，常称子龙之德，今果如此！”乃倍加钦敬。
忽报马谡、王平、魏延、高翔至。孔明先唤王平入帐，责之曰：“吾令汝同马谡守街亭，汝何不谏之，致使失事？”平曰：“某再三相劝，要在当道筑土城，安营守把。参军大怒不从，某因此自引五千军离山十里下寨。魏兵骤至，把山四面围合，某引兵冲杀十余次，皆不能入。次日土崩瓦解，降者无数。某孤军难立，故投魏文长求救。半途又被魏兵困在山谷之中，某奋死杀出。比及归寨，早被魏兵占了。及投列柳城时，路逢高翔，遂分兵三路去劫魏寨，指望克复街亭。因见街亭并无伏路军，以此心疑。登高望之，只见魏延、高翔被魏兵围住，某即杀入重围，救出二将，就同参军并在一处。某恐失却阳平关，因此急来回守。非某之不谏也。丞相不信，可问各部将校。”孔明喝退，又唤马谡入帐。
谡自缚跪于帐前。孔明变色曰：“汝自幼饱读兵书，熟谙战法。吾累次丁宁告戒：街亭是吾根本。汝以全家之命，领此重任。汝若早听王平之言，岂有此祸？今败军折将，失地陷城，皆汝之过也！若不明正军律，何以服众？汝今犯法，休得怨吾。汝死之后，汝之家小，吾按月给与禄粮，汝不必挂心。”叱左右推出斩之。谡泣曰：“丞相视某如子，某以丞相为父。某之死罪，实已难逃；愿丞相思舜帝殛鲧用禹之义，某虽死亦无恨于九泉！”言讫大哭。孔明挥泪曰：“吾与汝义同兄弟，汝之子即吾之子也，不必多嘱。”左右推出马谡于辕门之外，将斩。参军蒋琬自成都至，见武士欲斩马谡，大惊，高叫：“留人！”入见孔明曰：“昔楚杀得臣而文公喜。今天下未定，而戮智谋之臣，岂不可惜乎？”孔明流涕而答曰：“昔孙武所以能制胜于天下者，用法明也。今四方分争，兵戈方始，若复废法，何以讨贼耶？合当斩之。”须臾，武士献马谡首级于阶下。孔明大哭不已。蒋琬问曰：“今幼常得罪，既正军法，丞相何故哭耶？”孔明曰：“吾非为马谡而哭。吾想先帝在白帝城临危之时，曾嘱吾曰：‘马谡言过其实，不可大用。’今果应此言。乃深恨己之不明，追思先帝之言，因此痛哭耳！”大小将士，无不流涕。马谡亡年三十九岁，时建兴六年夏五月也。后人有诗曰：“失守街亭罪不轻，堪嗟马谡枉谈兵。辕门斩首严军法，拭泪犹思先帝明。”
却说孔明斩了马谡，将首级遍示各营已毕，用线缝在尸上，具棺葬之，自修祭文享祀；将谡家小加意抚恤，按月给与禄米。于是孔明自作表文，令蒋琬申奏后主，请自贬丞相之职。琬回成都，入见后主，进上孔明表章。后主拆视之。表曰：“臣本庸才，叨窃非据，亲秉旄钺，以励三军。不能训章明法，临事而惧，至有街亭违命之阙，箕谷不戒之失。咎皆在臣，授任无方。臣明不知人，恤事多暗。《春秋》责帅，臣职是当。请自贬三等，以督厥咎。臣不胜惭愧，俯伏待命！”后主览毕曰：“胜负兵家常事，丞相何出此言？”侍中费祎奏曰：“臣闻治国者，必以奉法为重。法若不行，何以服人？丞相败绩，自行贬降，正其宜也。”后主从之，乃诏贬孔明为右将军，行丞相事，照旧总督军马，就命费祎赍诏到汉中。
孔明受诏贬降讫，祎恐孔明羞赧，乃贺曰：“蜀中之民，知丞相初拔四县，深以为喜。”孔明变色曰：“是何言也！得而复失，与不得同。公以此贺我，实足使我愧赧耳。”祎又曰：“近闻丞相得姜维，天子甚喜。”孔明怒曰：“兵败师还，不曾夺得寸土，此吾之大罪也。量得一姜维，于魏何损？”祎又曰：“丞相现统雄师数十万，可再伐魏乎？”孔明曰：“昔大军屯于祁山、箕谷之时，我兵多于贼兵，而不能破贼，反为贼所破：此病不在兵之多寡，在主将耳。今欲减兵省将，明罚思过，较变通之道于将来；如其不然，虽兵多何用？自今以后，诸人有远虑于国者，但勤攻吾之阙，责吾之短，则事可定，贼可灭，功可翘足而待矣。”费祎诸将皆服其论。费祎自回成都。
孔明在汉中，惜军爱民，励兵讲武，置造攻城渡水之器，聚积粮草，预备战筏，以为后图。细作探知，报入洛阳，魏主曹睿闻知，即召司马懿商议收川之策。懿曰：“蜀未可攻也。方今天道亢炎，蜀兵必不出；若我军深入其地，彼守其险要，急切难下。”睿曰：“倘蜀兵再来入寇，如之奈何？”懿曰：“臣已算定今番诸葛亮必效韩信暗度陈仓之计。臣举一人往陈仓道口，筑城守御，万无一失：此人身长九尺，猿臂善射，深有谋略。若诸葛亮入寇，此人足可当之。”睿大喜，问曰：“此何人也？”懿奏曰：“乃太原人，姓郝，名昭，字伯道，现为杂号将军，镇守河西。”睿从之，加郝昭为镇西将军，命守把陈仓道口，遣使持诏去讫。
忽报扬州司马大都督曹休上表，说东吴鄱阳太守周鲂，愿以郡来降，密遣人陈言七事，说东吴可破，乞早发兵取之。睿就御床上展开，与司马懿同观。懿奏曰：“此言极有理，吴当灭矣！臣愿引一军往助曹休。”忽班中一人进曰：“吴人之言，反覆不一，未可深信。周鲂智谋之士，必不肯降，此特诱兵之诡计也。”众视之，乃建威将军贾逵也。懿曰：“此言亦不可不听，机会亦不可错失。”魏主曰：“仲达可与贾逵同助曹休。”二人领命去讫。于是曹休引大军径取皖城；贾逵引前将军满宠、东莞太守胡质，径取阳城，直向东关；司马懿引本部军径取江陵。却说吴主孙权，在武昌东关，会多官商议曰：“今有鄱阳太守周鲂密表，奏称魏扬州都督曹休，有人寇之意。今鲂诈施诡计，暗陈七事，引诱魏兵深入重地，可设伏兵擒之。今魏兵分三路而来，诸卿有何高见？”顾雍进曰：“此大任非陆伯言不敢当也。”权大喜，乃召陆逊，封为辅国大将军、平北都元帅，统御林大兵，摄行王事：授以白旄黄钺，文武百官，皆听约束。权亲自与逊执鞭。逊领命谢恩毕，乃保二人为左右都督，分兵以迎三道。权问何人。逊曰：“奋威将军朱桓，绥南将军全琮，二人可为辅佐。”权从之，即命朱桓为左都督，全琮为右都督，于是陆逊总率江南八十一州并荆湖之众七十余万，令朱桓在左，全琮在右。逊自居中，三路进兵。朱桓献策曰：“曹休以亲见任，非智勇之将也。今听周鲂诱言，深入重地，元帅以兵击之，曹休必败。败后必走两条路：左乃夹石，右乃挂车。此二条路，皆山僻小径，最为险峻。某愿与全子璜各引一军，伏于山险，先以柴木大石塞断其路，曹休可擒矣。若擒了曹休，便长驱直进，唾手而得寿春，以窥许、洛，此万世一时也。”逊曰：“此非善策，吾自有妙用。”于是朱桓怀不平而退。逊令诸葛瑾等拒守江陵，以敌司马懿。诸路俱各调拨停当。却说曹休兵临皖城，周鲂来迎，径到曹休帐下。休问曰：“近得足下之书，所陈七事，深为有理，奏闻天子，故起大军三路进发。若得江东之地，足下之功不小。有人言足下多谋，诚恐所言不实。吾料足下必不欺我。”周鲂大哭，急掣从人所佩剑欲自刎。休急止之。鲂仗剑而言曰：“吾所陈七事，恨不能吐出心肝。今反生疑，必有吴人使反间之计也。若听其言，吾必死矣。吾之忠心，惟天可表！”言讫，又欲自刎。曹休大惊，慌忙抱住曰：“吾戏言耳，足下何故如此！”鲂乃用剑割发掷于地曰：“吾以忠心待公，公以吾为戏，吾割父母所遗之发，以表此心！”曹休乃深信之，设宴相待。席罢，周鲂辞去。忽报建威将军贾逵来见，休令入，问曰：“汝此来何为？”逵曰：“某料东吴之兵，必尽屯于皖城。都督不可轻进，待某两下夹攻，贼兵可破矣。”休怒曰：“汝欲夺吾功耶？”逵曰：“又闻周鲂截发为誓，此乃诈也，昔要离断臂，刺杀庆忌。未可深信。”休大怒曰：“吾正欲进兵，汝何出此言以慢军心！”叱左右推出斩之。众将告曰：“未及进兵，先斩大将，于军不利。且乞暂免。”休从之，将贾逵兵留在寨中调用，自引一军来取东关。时周鲂听知贾逵削去兵权，暗喜曰：“曹休若用贾逵之言，则东吴败矣！今天使我成功也！”即遣人密到皖城，报知陆逊。逊唤诸将听令曰：“前面石亭，虽是山路，足可埋伏。早先去占石亭阔处，布成阵势，以待魏军。”遂令徐盛为先锋，引兵前进。却说曹休命周鲂引兵而进，正行间，休问曰：“前至何处？”鲂曰：“前面石亭也，堪以屯兵。”休从之，遂率大军并车仗等器，尽赴石亭驻扎。次日，哨马报道：“前面吴兵不知多少，据住山口。”休大惊曰：“周鲂言无兵，为何有准备？”急寻鲂问之。人报周鲂引数十人，不知何处去了。休大悔曰：“吾中贼之计矣！虽然如此，亦不足惧！”遂令大将张普为先锋，引数千兵来与吴兵交战。两阵对圆，张普出马骂曰：“贼将早降！”徐盛出马相迎。战无数合，普抵敌不住，勒马收兵，回见曹休，言徐盛勇不可当。休曰：“吾当以奇兵胜之。”就令张普引二万军伏于石亭之南，又令薛乔引二万军伏于石亭之北。“明日吾自引一千兵搦战，却佯输诈败，诱到北山之前，放炮为号，三面夹攻，必获大胜。”二将受计，各引二万军到晚埋伏去了。却说陆逊唤朱桓、全琮分付曰：“汝二人各引三万军，从石亭山路抄到曹休寨后，放火为号；吾亲率大军从中路而进：可擒曹休也。”当日黄昏，二将受计引兵而进。二更时分，朱桓引一军正抄到魏寨后，迎着张普伏兵。普不知是吴兵，径来问时，被朱桓一刀斩于马下。魏兵便走。桓令后军放火。全琮引一军抄到魏寨后，正撞在薛乔阵里，就那里大杀一阵。薛乔败走，魏兵大损，奔回本寨。后面朱桓、全琮两路杀来。曹休寨中大乱，自相冲击。休慌上马，望夹石道奔走。徐盛引大队军马，从正路杀来。魏兵死者不可胜数，逃命者尽弃衣甲。曹休大惊，在夹石道中，奋力奔走。忽见一彪军从小路冲出，为首大将，乃贾逵也。休惊慌少息，自愧曰：“吾不用公言，果遭此败！”逵曰：“都督可速出此道：若被吴兵以木石塞断，吾等皆危矣！”于是曹休骤马而行，贾逵断后。逵于林木盛茂处，及险峻小径，多设旌旗以为疑兵。及至徐盛赶到，见山坡下闪出旗角，疑有埋伏，不敢追赶，收兵而回。因此救了曹休。司马懿听知休败，亦引兵退去。
却说陆逊正望捷音，须臾，徐盛、朱桓、全琮皆到。所得车仗、牛马、驴骡、军资、器械，不计其数，降兵数万余人。逊大喜，即同太守周鲂并诸将班师还吴。吴主孙权，领文武官僚出武昌城迎接，以御盖覆逊而入。诸将尽皆升赏。权见周鲂无发，慰劳曰：“卿断发成此大事，功名当书于竹帛也。”即封周鲂为关内侯；大设筵会，劳军庆贺。陆逊奏曰：“今曹休大败，魏已丧胆；可修国书，遣使入川，教诸葛亮进兵攻之。”权从其言，遂遣使赍书入川去。正是：只因东国能施计，致令西川又动兵。
未知孔明再来伐魏，胜负如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943876, '5b9b73ff17d009003417ae1c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639236, '三国演义 · 第九十七回 · 讨魏国武侯再上表 破曹兵姜维诈献书', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说蜀汉建兴六年秋九月，魏都督曹休被东吴陆逊大破于石亭，车仗马匹，军资器械，并皆罄尽，休惶恐之甚，气忧成病，到洛阳，疽发背而死。魏主曹睿敕令厚葬。司马懿引兵还、众将接入问曰：“曹都督兵败，即元帅之干系，何故急回耶？”懿曰：“吾料诸葛亮知吾兵败，必乘虚来取长安。倘陇西紧急，何人救之？吾故回耳。”众皆以为惧怯，哂笑而退。
却说东吴遣使致书蜀中，请兵伐魏，并言大破曹休之事：一者显自己威风，二者通和会之好。后主大喜，令人持书至汉中，报知孔明。时孔明兵强马壮，粮草丰足，所用之物，一切完备，正要出师。听知此信，即设宴大会诸将，计议出师。忽一阵大风，自东北角上而起，把庭前松树吹折。众皆大惊。孔明就占一课，曰：“此风主损一大将！”诸将未信。正饮酒间，忽报镇南将军赵云长子赵统、次子赵广，来见丞相。孔明大惊，掷杯于地曰：“子龙休矣！”二子入见，拜哭曰：“某父昨夜三更病重而死。”孔明跌足而哭曰：“子龙身故，国家损一栋梁，吾去一臂也！”众将无不挥涕。孔明令二子入成都面君报丧。后主闻云死，放声大哭曰“朕昔年幼，非子龙则死于乱军之中矣！”即下诏追赠大将军，谥封顺平侯，敕葬于成都锦屏山之东；建立庙堂，四时享祭。后人有诗曰：“常山有虎将，智勇匹关张。汉水功勋在，当阳姓字彰。两番扶幼主，一念答先皇。青史书忠烈，应流百世芳。”
却说后主思念赵云昔日之功，祭葬甚厚；封赵统为虎贲中郎，赵广为牙门将，就令守坟。二人辞谢而去。忽近臣奏曰：“诸葛丞相将军马分拨已定，即日将出师伐魏。”后主问在朝诸臣，诸臣多言未可轻动。后主疑虑未决。忽奏丞相令杨仪赍出师表至。后主宜入，仪呈上表章。后主就御案上拆视，其表曰：
“先帝虑汉贼不两立，王业不偏安，故托臣以讨贼也。以先帝之明，量臣之才，故知臣伐贼，才弱敌强也。然不伐贼，王业亦亡。惟坐而待亡，孰与伐之？是故托臣而弗疑也。臣受命之日，寝不安席，食不甘味；思惟北征，宜先入南：故五月渡沪，深入不毛，并日而食。——臣非不自惜也，顾王业不可偏安于蜀都，故冒危难以奉先帝之遗意。而议者谓为非计。今贼适疲于西，又务于东，兵法“乘劳”：此进趋之时也。谨陈其事如左：
高帝明并日月，谋臣渊深，然涉险被创，危然后安；今陛下未及高帝，谋臣不如良、平，而欲以长策取胜，坐定天下，此臣之未解一也。刘繇、王朗，各据州郡，论安言计，动引圣人，群疑满腹，众难塞胸；今岁不战，明年不征，使孙权坐大，遂并江东，此臣之未解二也。曹操智计，殊绝于人，其用兵也，仿佛孙、吴，然困于南阳，险于乌巢，危于祁连，逼于黎阳，几败北山，殆死潼关，然后伪定一时耳；况臣才弱，而欲以不危而定之，此臣之未解三也。曹操五攻昌霸不下，四越巢湖不成，任用李服而李服图之，委任夏侯而夏侯败亡，先帝每称操为能，犹有此失；况臣驽下，何能必胜，此臣之未解四也。自臣到汉中，中间期年耳，然丧赵云、阳群、马玉、阎芝、丁立、白寿、刘郃、邓铜等，及曲长屯将七十余人，突将无前，賨、叟、青羌，散骑武骑一千余人，此皆数十年之内，所纠合四方之精锐，非一州之所有；若复数年，则损三分之二也。——当何以图敌，此臣之未解五也。今民穷兵疲，而事不可息；事不可息，则住与行，劳费正等；而不及今图之，欲以一州之地，与贼持久，此臣之未解六也。
夫难平者，事也。昔先帝败军于楚，当此之时，曹操拊手，谓天下已定。——然后先帝东连吴、越，西取巴、蜀，举兵北征，夏侯授首，此操之失计，而汉事将成也。——然后吴更违盟，关羽毁败，秭归蹉跌，曹丕称帝，凡事如是，难可逆见。臣鞠躬尽瘁，死而后已；至于成败利钝，非臣之明所能逆睹也。”
后主览表甚喜，即敕令孔明出师。孔明受命，起三十万精兵，令魏延总督前部先锋，径奔陈仓道口而来。早有细作报入洛阳。司马懿奏知魏主，大会文武商议。大将军曹真出班奏曰：“臣昨守陇西，功微罪大，不胜惶恐。今乞引大军往擒诸葛亮。臣近得一员大将，使六十斤大刀，骑千里征？宛马，开两石铁胎弓，暗藏三个流星锤，百发百中，有万夫不当之勇，乃陇西狄道人，姓王，名双，字子全。臣保此人为先锋。”睿大喜，便召王双上殿。视之，身长九尺，面黑睛黄，熊腰虎背。睿笑曰：“朕得此大将，有何虑哉！”遂赐锦袍金甲，封为虎威将军、前部大先锋。曹真为大都督。真谢恩出朝，遂引十五万精兵，会合郭淮、张郃，分道守把隘口。却说蜀兵前队哨至陈仓，回报孔明，说：“陈仓口已筑起一城，内有大将郝昭守把，深沟高垒，遍排鹿角，十分谨严；不如弃了此城，从太白岭鸟道出祁山甚便。”孔明曰：“陈仓正北是街亭；必得此城，方可进兵。”命魏延引兵到城下，四面攻之。连日不能破。魏延复来告孔明，说城难打。孔明大怒，欲斩魏延。忽帐下一人告曰：“某虽无才，随丞相多年，未尝报效。愿去陈仓城中，说郝昭来降，不用张弓只箭。”众视之，乃部曲靳祥也。孔明曰：“汝用何言以说之？”祥曰：“郝昭与某，同是陇西人氏，自幼交契。某今到彼，以利害说之，必来降矣。”孔明即令前去。
靳祥骤马径到城下，叫曰：“郝伯道故人靳祥来见。”城上人报知郝昭。昭令开门放入，登城相见。昭问曰：“故人因何到此？”祥曰：“吾在西蜀孔明帐下，参赞军机，待以上宾之礼。特令某来见公，有言相告。”昭勃然变色曰：“诸葛亮乃我国仇敌也！吾事魏，汝事蜀，各事其主，昔时为昆仲，今时为仇敌！汝再不必多言，便请出城！”靳祥又欲开言，郝昭已出敌楼上了。魏军急催上马，赶出城外。祥回头视之，见昭倚定护心木栏杆。祥勒马以鞭指之曰：“伯道贤弟，何太情薄耶？”昭曰：“魏国法度，兄所知也。吾受国恩，但有死而已，兄不必下说词。早回见诸葛亮，教快来攻城，吾不惧也！”
祥回告孔明曰：“郝昭未等某开言，便先阻却。”孔明曰：“汝可再去见他，以利害说之。”祥又到城下，请郝昭相见。昭出到敌楼上。祥勒马高叫曰：“伯道贤弟，听吾忠言：汝据守一孤城，怎拒数十万之众？今不早降，后悔无及！且不顺大汉而事奸魏，抑何不知天命、不辨清浊乎？愿伯道思之。”郝昭大怒，拈弓搭箭，指靳祥而喝曰：“吾前言已定，汝不必再言！可速退！吾不射汝！”
靳祥回见孔明，具言郝昭如此光景。孔明大怒曰：“匹夫无礼太甚！岂欺吾无攻城之具耶？”随叫土人问曰：“陈仓城中，有多少人马？”土人告曰：“虽不知的数，约有三千人。”孔明笑曰：“量此小城，安能御我！休等他救兵到，火速攻之！”于是军中起百乘云梯，一乘上可立十数人，周围用木板遮护。军士各把短梯软索，听军中擂鼓，一齐上城。郝昭在敌楼上，望见蜀兵装起云梯，四面而来，即令三千军各执火箭，分布四面；待云梯近城，一齐射之。孔明只道城中无备，故大造云梯，令三军鼓噪呐喊而进；不期城上火箭齐发，云梯尽着，梯上军士多被烧死，城上矢石如雨，蜀兵皆退。孔明大怒曰：“汝烧吾云梯，吾却用‘冲车’之法！”于是连夜安排下冲车。次日，又四面鼓嗓呐喊而进。郝昭急命运石凿眼，用葛绳穿定飞打，冲车皆被打折。孔明又令人运土填城壕，教廖化引三千锹？军，从夜间掘地道，暗入城去。郝昭又于城中掘重壕横截之。如此昼夜相攻，二十余日，无计可破。
孔明正在营中忧闷，忽报：“东边救兵到了，旗上书：‘魏先锋大将王双’。”孔明问曰：“谁可迎之？”魏延出曰：“某愿往。”孔明曰：“汝乃先锋大将，未可轻出。”又问：“谁敢迎之？”裨将谢雄应声而出。孔明与三千军去了。孔明又问曰：“谁敢再去？”裨将龚起应声要去。孔明亦与三千兵去了。孔明恐城内郝昭引兵冲出，乃把人马退二十里下寨。
却说谢雄引军前行，正遇王双；战不三合，被双一刀劈死。蜀兵败走，双随后赶来。龚起接着，交马只三合，亦被双所斩。败兵回报孔明。孔明大惊，忙令廖化、王平、张嶷三人出迎。两阵对圆，张嶷出马，王平、廖化压住阵角。王双纵马来与张嶷交马，数合不分胜负。双诈败便走，嶷随后赶去。王平见张嶷中计，忙叫曰：“休赶！”嶷急回马时，王双流星锤早到，正中其背。巍伏鞍而走，双回马赶来。王平、廖化截住，救得张嶷回阵。王双驱兵大杀一阵，蜀兵折伤甚多。巍吐血数口，回见孔明，说：“王双英雄无敌；如今将二万兵就陈仓城外下寨，四围立起排栅，筑起重城，深挖壕堑，守御甚严。”孔明见折二将，张嶷又被打伤，即唤姜维曰：“陈仓道口这条路不可行。别求何策？”维曰：“陈仓城池坚固，郝昭守御甚密，又得王双相助，实不可取。不若令一大将，依山傍水，下寨固守；再令良将守把要道，以防街亭之攻；却统大军去袭祁山，某却如此如此用计，可捉曹真也。”孔明从其言，即令王平，李恢，引二枝兵守街亭小路；魏延引一军守陈仓口。马岱为先锋，关兴、张苞为前后救应使，从小径出斜谷望祁山进发。却说曹真因思前番被司马懿夺了功劳，因此到洛阳分调郭淮、孙礼东西守把；又听的陈仓告急，已令王双去救。闻知王双斩将立功，大喜，乃令中护军大将费耀，权摄前部总督，诸将各自守把隘口。忽报山谷中捉得细作来见。曹真令押入，跪于帐前。其人告曰：“小人不是奸细，有机密来见都督，误被伏路军捉来，乞退左右。”真乃教去其缚，左右暂退。其人曰：“小人乃姜伯约心腹人也。蒙本官遣送密书。”真曰：“书安在？”其人于贴肉衣内取出呈上。真拆视曰：“罪将姜维百拜，书呈大都督曹麾下：维念世食魏禄，忝守边城；叨窃厚恩，无门补报。昨日误遭诸葛亮之计，陷身于巅崖之中。思念旧国，何日忘之！今幸蜀兵西出，诸葛亮甚不相疑。赖都督亲提大兵而来：如遇敌人，可以诈败；维当在后，以举火为号，先烧蜀人粮草，却以大兵翻身掩之，则诸葛亮可擒也。非敢立功报国，实欲自赎前罪。倘蒙照察，速赐来命。”曹真看毕，大喜曰：“天使吾成功也！”遂重赏来人，便令回报，依期会合。真唤费耀商议曰：“今姜维暗献密书，令吾如此如此。”耀曰：“诸葛亮多谋，姜维智广，或者是诸葛亮所使，恐其中有诈。”真曰：“他原是魏人，不得已而降蜀，又何疑乎？”耀曰：“都督不可轻去，只守定本寨。某愿引一军接应姜维。如成功，尽归都督；倘有奸计，某自支当。”真大喜，遂令费耀引五万兵，望斜谷而进。行了两三程，屯下军马，令人哨探。当日申时分，回报：“斜谷道中，有蜀兵来也。”耀忙催兵进。蜀兵未及交战先退。耀引兵追之，蜀兵又来。方欲对阵，蜀兵又退：如此者三次，俄延至次日申时分。魏军一日一夜，不曾敢歇，只恐蜀兵攻击。方欲屯军造饭，忽然四面喊声大震，鼓角齐鸣，蜀兵漫山遍野而来。门旗开处，闪出一辆四轮车，孔明端坐其中，令人请魏军主将答话。耀纵马而出，遥见孔明，心中暗喜，回顾左右曰：“如蜀兵掩至，便退后走。若见山后火起，却回身杀去，自有兵来相应。”分付毕，跃马出呼曰：“前者败将，今何敢又来！”孔明曰：“唤汝曹真来答话！”耀骂曰：“曹都督乃金枝玉叶，安肯与反贼相见耶！”孔明大怒，把羽扇一招，左有马岱，右有张嶷，两路兵冲出。魏兵便退。行不到三十里，望见蜀兵背后火起，喊声不绝。费耀只道号火，便回身杀来。蜀兵齐退。耀提刀在前，只望喊处追赶。将次近火，山路中鼓角喧天、喊声震地，两军杀出：左有关兴，右有张苞。山上矢石如雨，往下射来。魏兵大败。费耀知是中计，急退军望山谷中而走，人马困乏。背后关兴引生力军赶来，魏兵自相践踏及落涧身死者，不知其数。
耀逃命而走，正遇山坡口一彪军，乃是姜维。耀大骂曰：“反贼无信！吾不幸误中汝奸计也！”维笑曰：“吾欲擒曹真，误赚汝矣！速下马受降！”耀骤马夺路，望山谷中而走。忽见谷口火光冲天，背后追兵又至。耀自刎身死，余众尽降。孔明连夜驱兵，直出祁山前下寨，收住军马，重赏姜维。维曰：“某恨不得杀曹真也！”孔明亦曰：“可惜大计小用矣。”
却说曹真听知折了费耀，悔之不及，遂与郭淮商议退兵之策。于是孙礼、辛毗星夜具表申奏魏主，言蜀兵又出祁山，曹真损兵折将，势甚危急。睿大惊，即召司马懿入内曰：“曹真损兵折将，蜀兵又出祁山。卿有何策，可以退之？”懿曰：“臣已有退诸葛亮之计。不用魏军扬武耀威，蜀兵自然走矣。”正是：已见子丹无胜术，全凭仲达有良谋。
未知其计如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943877, '5b9b741317d009003417af08', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639237, '三国演义 · 第九十八回 · 追汉军王双受诛 袭陈仓武侯取胜', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '却说司马懿奏曰：“臣尝奏陛下，言孔明必出陈仓，故以郝昭守之，今果然矣。彼若从陈仓入寇，运粮甚便。今幸有郝昭、王双守把，不敢从此路运粮。其余小道，搬运艰难。臣算蜀兵行粮止有一月，利在急战。我军只宜久守。陛下可降诏，令曹真坚守诸路关隘，不要出战。不须一月，蜀兵自走。那时乘虚而击之，诸葛亮可擒也。”睿欣然曰：“卿既有先见之明，何不自引一军以袭之？”懿曰：“臣非惜身重命，实欲存下此兵，以防东吴陆逊耳。孙权不久必将僭号称尊；如称尊号，恐陛下伐之，定先入寇也：臣故欲以兵待之。”正言间，忽近臣奏曰：“曹都督奏报军情。”懿曰：“陛下可即令人告戒曹真：凡追赶蜀兵，必须观其虚实，不可深入重地，以中诸葛亮之计。”睿即时下诏，遣太常卿韩暨持节告戒曹真：“切不可战，务在谨守；只待蜀兵退去，方才击之。”司马懿送韩暨于城外，嘱之曰：“吾以此功让与子丹；公见子丹，休言是吾所陈之意，只道天子降诏，教保守为上。追赶之人，大要仔细，勿遣性急气躁者追之。”暨辞去。
却说曹真正升帐议事，忽报天子遣太常卿韩暨持节至。真出寨接入，受诏已毕，退与郭淮、孙礼计议。淮笑曰：“此乃司马仲达之见也。”真曰：“此见若何？”淮曰：“此言深识诸葛亮用兵之法。久后能御蜀兵者，必仲达也。”真曰：“倘蜀兵不退，又将如何？”淮曰：“可密令人去教王双，引兵于小路巡哨，彼自不敢运粮。待其粮尽兵退，乘势追击，可获全胜。”孙礼曰：“某去祁山虚妆做运粮兵，车上尽装干柴茅草，以硫黄焰硝灌之，却教人虚报陇西运粮到。若蜀人无粮，必然来抢。待人其中，放火烧车，外以伏兵应之，可胜矣。”真喜曰：“此计大妙！”即令孙礼引兵依计而行。又遣人教王双引兵于小路上巡哨，郭淮引兵提调箕谷、街亭，令诸路军马守把险要。真又令张辽子张虎为先锋，乐进子乐綝为副先锋，同守头营，不许出战。却说孔明在祁山寨中，每日今人挑战，魏兵坚守不出。孔明唤姜维等商议曰：“魏兵坚守不出，是料吾军中无粮也。今陈仓转运不通，其余小路盘涉艰难，吾算随军粮草，不敷一月用度，如之奈何？”正踌躇间，忽报：“陇西魏军运粮数千车于祁山之西，运粮官乃孙礼也。”孔明曰：“其人如何？”有魏人告曰：“此人曾随魏主出猎于大石山，忽惊起一猛虎，直奔御前，孙礼下马拔剑斩之。从此封为上将军。乃曹真心腹人也。”孔明笑曰：“此是魏将料吾乏粮，故用此计：车上装载者，必是茅草引火之物。吾平生专用火攻，彼乃欲以此计诱我耶？彼若知吾军去劫粮车，必来劫吾寨矣。可将计就计而行。”遂唤马岱分付曰：“汝引三千军径到魏兵屯粮之所，不可入营，但于上风头放火。若烧着车仗，魏兵必来围吾寨。”又差马忠、张嶷各引五千兵在外围住，内外夹攻。三人受计去了。又唤关兴、张苞分付曰：“魏兵头营接连四通之路。今晚若西山火起，魏兵必来劫吾营。汝二人却伏于魏寨左右，只等他兵出寨，汝二人便可劫之。”又唤吴班、吴懿分付曰：“汝二人各引一军伏于营外。如魏兵到，可截其归路。”孔明分拨已毕，自在祁山上凭高而坐。
魏兵探知蜀兵要来劫粮，慌忙报与孙礼。礼令人飞报曹真。真遣人去头营分付张虎、乐綝：“看今夜山西火起，蜀兵必来救应。可以出军，如此如此。”二将受计，令人登楼专看号火。却说孙礼把军伏于山西，只待蜀兵到。是夜二更，马岱引三千兵来，人皆衔枚，马尽勒口，径到山西。见许多车仗，重重叠叠，攒绕成营，车仗虚插旌旗。正值西南风起，岱令军士径去营南放火，车仗尽着，火光冲天。孙礼只道蜀兵到魏寨内放号火，急引兵一齐掩至。背后鼓角喧天，两路兵杀来：乃是马忠、张嶷，把魏军围在垓心。孙礼大惊。又听的魏军中喊声起，一彪军从火光边杀来，乃是马岱。内外夹攻，魏兵大败。火紧风急，人马乱窜，死者无数。孙礼引中伤军，突烟冒火而走。却说张虎在营中，望见火光，大开寨门，与乐綝尽引人马，杀奔蜀寨来，寨中却不见一人。急收军回时，吴班、吴懿两路兵杀出，断其归路。张、乐二将急冲出重围，奔回本寨，只见土城之上，箭如飞蝗，原来却被关兴、张苞袭了营寨。魏兵大败，皆投曹真寨来。方欲入寨，只见一彪败军飞奔而来，乃是孙礼；遂同入寨见真，各言中计之事。真听知，谨守大寨，更不出战。蜀兵得胜，回见孔明。孔明令人密授计与魏延，一面教拔寨齐起。杨仪曰：“今已大胜，挫尽魏兵锐气，何故反欲收军？”孔明曰：“吾兵无粮，利在急战。今彼坚守不出，吾受其病矣。彼今虽暂时兵败，中原必有添益；若以轻骑袭吾粮道，那时要归不能。今乘魏兵新败，不敢正视蜀兵，便可出其不意，乘机退去。所忧者但魏延一军，在陈仓道口拒住王双，急不能脱身；吾已令人授以密计，教斩王双，使魏人不敢来追。只今后队先行。”当夜，孔明只留金鼓守在寨中打更。一夜兵已尽退，只落空营。却说曹真正在寨中忧闷，忽报左将军张郃领军到。郃下马入帐，谓真曰：“某奉圣旨，特来听调。”真曰：“曾别仲达否？”郃曰：“仲达分付云：‘吾军胜，蜀兵必不便去；若吾军败，蜀兵必即去矣。’今吾军失利之后，都督曾往哨探蜀兵消息否？”真曰：“未也。”于是即令人往探之，果是虚营，只插着数十面旌旗，兵已去了二日也。曹真懊悔无及。
且说魏延受了密计，当夜二更拔寨，急回汉中。早有细作报知王双。双大驱军马，并力追赶。追到二十余里，看看赶上，见魏延旗号在前，双大叫曰：“魏延休走！”蜀兵更不回头。双拍马赶来。背后魏兵叫曰：“城外寨中火起，恐中敌人奸计。”双急勒马回时，只见一片火光冲天，慌令退军。行到山坡左侧，忽一骑马从林中骤出，大喝曰：“魏延在此！”王双大惊，措手不及，被延一刀砍于马下。魏兵疑有埋伏，四散逃走。延手下止有三十骑人马，望汉中缓缓而行。后人有诗赞曰：“孔明妙算胜孙庞，耿若长星照一方。进退行兵神莫测，陈仓道口斩王双。”原来魏延受了孔明密计：先教存下三十骑，伏于王双营边；只待王双起兵赶时，却去他营中放火；待他回寨，出其不意，突出斩之。魏延斩了王双，引兵回到汉中见孔明，交割了人马。孔明设宴大会，不在话下。
且说张郃追蜀兵不上，回到寨中。忽有陈仓城郝昭差人申报，言王双被斩，曹真闻知，伤感不已，因此忧成疾病，遂回洛阳；命郭淮、孙礼、张郃守长安诸道。
却说吴王孙权设朝，有细作人报说：“蜀诸葛丞相出兵两次，魏都督曹真兵损将亡。”于是群臣皆劝吴王兴师伐魏，以图中原。权犹疑未决。张昭奏曰：“近闻武昌东山，凤凰来仪；大江之中，黄龙屡现。主公德配唐、虞，明并文、武，可即皇帝位，然后兴兵。”多官皆应曰：“子布之言是也。”遂选定夏四月丙寅日，筑坛于武昌南郊。是日，群臣请权登坛即皇帝位，改黄武八年为黄龙元年。谥父孙坚为武烈皇帝，母吴氏为武烈皇后，兄孙策为长沙桓王。立子孙登为皇太子。命诸葛瑾长子诸葛恪为太子左辅，张昭次子张休为太子右弼。
恪字元逊，身长七尺，极聪明，善应对。权甚爱之。年六岁时，值东吴筵会，恪随父在座。权见诸葛瑾面长，乃令人牵一驴来，用粉笔书其面曰：“诸葛子瑜”。众皆大笑。恪趋至前，取粉笔添二字于其下曰：“诸葛子瑜之驴”。满座之人，无不惊讶。权大喜，遂将驴赐之。又一日，大宴官僚，权命恪把盏。巡至张昭面前，昭不饮，曰：“此非养老之礼也。”权谓恪曰：“汝能强子布饮乎？”恪领命，乃谓昭曰：“昔姜尚父年九十，秉旄仗钺，未尝言老。今临阵之日，先生在后；饮酒之日，先生在前：何谓不养老也？”昭无言可答，只得强饮。权因此爱之，故命辅太子。张昭佐吴王，位列三公之上，故以其子张休为太子右弼。又以顾雍为丞相，陆逊为上将军，辅太子守武昌。权复还建业。群臣共议伐魏之策。张昭奏曰：“陛下初登宝位，未可动兵。只宜修文偃武，增设学校，以安民心；遣使入川，与蜀同盟，共分天下，缓缓图之。”权从其言，即令使命星夜入川，来见后主。礼毕，细奏其事。后主闻知，遂与群臣商议。众议皆谓孙权僭逆，宜绝其盟好。蒋琬曰：“可令人问于丞相。”后主即遣使到汉中问孔明。孔明曰：“可令人赍礼物入吴作贺，乞遣陆逊兴师伐魏。魏必命司马懿拒之。懿若南拒东吴，我再出祁山，长安可图也。”后主依言，遂令太尉陈震，将名马、玉带、金珠、宝贝，入吴作贺。
震至东吴，见了孙权，呈上国书。权大喜，设宴相待，打发回蜀。权召陆逊入，告以西蜀约会兴兵伐魏之事。逊曰：“此乃孔明惧司马懿之谋也。既与同盟，不得不从。今却虚作起兵之势，遥与西蜀为应。待孔明攻魏急，吾可乘虚取中原也。”即时下令，教荆襄各处都要训练人马，择日兴师。
却说陈震回到汉中，报知孔明。孔明尚忧陈仓不可轻进，先令人去哨探。回报说：“陈仓城中郝昭病重。”孔明曰：“大事成矣。”遂唤魏延、姜维分付曰：“汝二人领五千兵，星夜直奔陈仓城下；如见火起，并力攻城。”二人俱未深信，又来告曰：“何日可行？”孔明曰：“三日都要完备；不须辞我，即便起行。”二人受计去了。又唤关兴、张苞至，附耳低言，如此如此。二人各受密计而去。且说郭淮闻郝昭病重，乃与张郃商议曰：“郝昭病重，你可速去替他。我自写表申奏朝廷，别行定夺。”张郃引着三千兵，急来替郝昭。时郝昭病危，当夜正呻吟之间，忽报蜀军到城下了。昭急令人上城守把。时各门上火起，城中大乱。昭听知惊死。蜀兵一拥入城。
却说魏延、姜维领兵到陈仓城下看时，并不见一面旗号，又无打更之人。二人惊疑，不敢攻城。忽听得城上一声炮响，四面旗帜齐竖。只见一人纶巾羽扇，鹤氅道袍，大叫曰：“汝二人来的迟了！”二人视之，乃孔明也。二人慌忙下马，拜伏于地曰：“丞相真神计也！”孔明令放入城，谓二人曰：“吾打探得郝昭病重，吾令汝三日内领兵取城，此乃稳众人之心也。吾却令关兴、张苞，只推点军，暗出汉中。吾即藏于军中，星夜倍道径到城下，使彼不能调兵。吾早有细作在城内放火、发喊相助，令魏兵惊疑不定。兵无主将，必自乱矣。吾因而取之，易如反掌。兵法云：出其不意，攻其无备。正谓此也。”魏延、姜维拜伏。孔明怜郝昭之死，令彼妻小扶灵柩回魏，以表其忠。孔明谓魏延、姜维曰：“汝二人且莫卸甲，可引兵去袭散关。把关之人，若知兵到，必然惊走。若稍迟便有魏兵至关，即难攻矣。”魏延、姜维受命，引兵径到散关。把关之人，果然尽走。二人上关才要卸甲，遥见关外尘头大起，魏兵到来。二人相谓曰：“丞相神算，不可测度！”急登楼视之，乃魏将张郃也。二人乃分兵守住险道。张郃见蜀兵把住要路，遂令退军。魏延随后追杀一阵，魏兵死者无数，张郃大败而去。延回到关上，令人报知孔明。
孔明先自领兵，出陈仓斜谷，取了建威。后面蜀兵陆续进发。后主又命大将陈式来助。孔明驱大兵复出祁出。安下营寨，孔明聚众言曰：“吾二次出祁山，不得其利，今又到此，吾料魏人必依旧战之地，与吾相敌。彼意疑我取雍、郿二处，必以兵拒守；吾观阴平、武都二郡，与汉连接，若得此城，亦可分魏兵之势。何人敢取之？”姜维曰：“某愿往。”王平应曰：“某亦愿往。”孔明大喜，遂令姜维引兵一万取武都，王平引兵一万取阴平。二人领兵去了。
再说张郃回到长安，见郭淮、孙礼，说：“陈仓已失，郝昭已亡，散关亦被蜀兵夺了。今孔明复出祁山，分道进兵。”淮大惊曰：“若如此，必取雍、郿矣！”乃留张郃守长安，令孙礼保雍城。淮自引兵星夜来郿城守御，一面上表入洛阳告急。
却说魏主曹睿设朝，近臣奏曰：“陈仓城已失，郝昭已亡，诸葛亮又出祁山，散关亦被蜀兵夺了。”睿大惊。忽又奏满宠等有表，说：“东吴孙权僭称帝号，与蜀同盟。今遣陆逊在武昌训练人马，听候调用。只在旦夕，必入寇矣。”睿闻知两处危急，举止失措，甚是惊慌。此时曹真病未痊，即召司马懿商议。懿奏曰：“以臣愚意所料，东吴必不举兵。”睿曰：“卿何以知之？”懿曰：“孔明尝思报猇亭之仇，非不欲吞吴也，只恐中原乘虚击彼，故暂与东吴结盟。陆逊亦知其意，故假作兴兵之势以应之，实是坐观成败耳。陛下不必防吴，只须防蜀。”睿曰：“卿真高见！”遂封懿为大都督，总摄陇西诸路军马，令近臣取曹真总兵将印来。懿曰：“臣自去取之。”
遂辞帝出朝，径到曹真府下，先令人入府报知，懿方进见。问病毕，懿曰：“东吴、西蜀会合，兴兵入寇，今孔明又出祁山下寨，明公知之乎？”真惊讶曰：“吾家人知我病重，不令我知。似此国家危急，何不拜仲达为都督，以退蜀兵耶？”懿曰：“某才薄智浅，不称其职。”真曰：“取印与仲达。”懿曰：“都督少虑。某愿助一臂之力，只不敢受此印也。”真跃起曰：“如仲达不领此任，中国必危矣！吾当抱病见帝以保之！懿曰：“天子已有恩命，但懿不敢受耳。”真大喜曰：“仲达今领此任，可退蜀兵。”懿见真再三让印，遂受之，入内辞了魏主，引兵往长安来与孔明决战。正是：旧帅印为新帅取，两路兵惟一路来。
未知胜负如何，且看下文分解。', '', '', '', NULL, '', 'indent', 1536943881, '5b9b742a808ca43cd222d741', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639238, '三国演义 · 第九十九回 · 诸葛亮大破魏兵 司马懿入寇西蜀', NULL, 0, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', '蜀汉建兴七年夏四月，孔明兵在祁山，分作三寨，专候魏兵。却说司马懿引兵到长安，张郃接见，备言前事。懿令郃为先锋，戴陵为副将，引十万兵到祁山，于渭水之南下寨。郭淮、孙礼入寨参见。懿问曰：“汝等曾与蜀兵对阵否？”二人答曰：“未也。”懿曰：“蜀兵千里而来，利在速战；今来此不战，必有谋也。陇西诸路，曾有信息否？”淮曰：“已有细作探得各郡十分用心，日夜提防，并无他事。只有武都、阴平二处，未曾回报。”懿曰：“吾自差人与孔明交战。汝二人急从小路去救二郡，却掩在蜀兵之后，彼必自乱矣。”
二人受计，引兵五千，从陇西小路来救武都、阴平，就袭蜀兵之后。郭淮于路谓孙礼曰：“仲达比孔明如何？”礼曰：“孔明胜仲达多矣。”淮曰：“孔明虽胜，此一计足显仲达有过人之智。蜀兵如正攻两郡，我等从后抄到，彼岂不自乱乎？”正言间，忽哨马来报：“阴平已被王平打破了，武都已被姜维打破了。前离蜀兵不远。”礼曰：“蜀兵既已打破了城池，如何陈兵于外？必有诈也。不如速退。”郭淮从之。方传令教军退时，忽然一声炮响，山背后闪出一枝军马来，旗上大书：“汉丞相诸葛亮”，中央一辆四轮车，孔明端坐于上；左有关兴，右有张苞。孙、郭二人见之，大惊。孔明大笑曰：“郭淮、孙礼休走！司马懿之计，安能瞒得过吾？他每日令人在前交战，却教汝等袭吾军后。武都、阴平吾已取了。汝二人不早来降，欲驱兵与吾决战耶？”郭淮、孙礼听毕，大慌。忽然背后喊杀连天，王平、姜维引兵从后杀来。兴、苞二将又引军从前面杀来。两下夹攻，魏兵大败。郭、孙二人弃马爬山而走。张苞望见，骤马赶来；不期连人带马，跌入涧内，后军急忙救起，头已跌破。孔明令人送回成都养病。
却说郭、孙二人走脱，回见司马懿曰：“武都、阴平二郡已失。孔明伏于要路，前后攻杀，因此大败，弃马步行，方得逃回。”懿曰：“非汝等之罪，孔明智在吾先。可再引兵守把雍、郿二城，切勿出战。吾自有破敌之策。”二人拜辞而去。懿又唤张郃、戴陵分付曰：“今孔明得了武都、阴平，必然抚百姓以安民心，不在营中矣。汝二人各引一万精兵，今夜起身，抄在蜀兵营后，一齐奋勇杀将过来；吾却引军在前布阵，只待蜀兵势乱，吾大驱士马，攻杀进去：两军并力，可夺蜀寨也。若得此地山势，破敌何难？”二人受计引兵而去。
戴陵在左，张郃在右，各取小路进发，深入蜀兵之后。三更时分，来到大路，两军相遇，合兵一处，却从蜀兵背后杀来。行不到三十里，前军不行。张、戴二人自纵马视之，只见数百辆草车横截去路。郃曰：“此必有准备。可急取路而回。”才传令退军，只见满山火光齐明，鼓角大震，伏兵四下皆出，把二人围住。孔明在祁山上大叫曰：“戴陵、张郃可听吾言：司马懿料吾往武都、阴平抚民，不在营中，故令汝二人来劫吾寨，却中吾之计也。汝二人乃无名下将，吾不杀害，下马早降！”郃大怒，指孔明而骂曰：“汝乃山野村夫，侵吾大国境界，如何敢发此言！吾若捉住汝时，碎尸万段！”言讫，纵马挺枪，杀上山来。山上矢石如雨，郃不能上山，乃拍马舞枪，冲出重围，无人敢当。蜀兵困戴陵在垓心。郃杀出旧路，不见戴陵，即奋勇翻身又杀入重围，救出戴陵而回。孔明在山上，见郃在万军之中，往来冲突，英勇倍加，乃谓左右曰：“尝闻张翼德大战张郃，人皆惊惧。吾今日见之，方知其勇也。若留下此人，必为蜀中之害。吾当除之。”遂收军还营。
却说司马懿引兵布成阵势，只待蜀兵乱动，一齐攻之。忽见张郃、戴陵狼狈而来，告曰：“孔明先如此提防，因此大败而归。”懿大惊曰：“孔明真神人也！不如且退。”即传令教大军尽回本寨，坚守不出。且说孔明大胜，所得器械、马匹，不计其数，乃引大军回寨。每日令魏延挑战，魏兵不出。一连半月，不曾交兵。孔明正在帐中思虑，忽报天子遣侍中费祎赍诏至。孔明接入营中，焚香礼毕，开诏读曰：“街亭之役，咎由马谡；而君引愆，深自贬抑。重违君意，听顺所守。前年耀师，馘斩王双；今岁爱征，郭淮遁走；降集氏、羌，复兴二郡：威震凶暴，功勋显然。方今天下骚扰，元恶未枭，君受大任，干国之重，而久自抑损，非所以光扬洪烈矣。今复君丞相，君其勿辞！”孔明听诏毕，谓费祎曰：“吾国事未成，安可复丞相之职？”坚辞不受。祎曰：“丞相若不受职，拂了天子之意，又冷淡了将士之心。宜且权受。”孔明方才拜受。祎辞去。
孔明见司马懿不出，思得一计，传令教各处皆拔寨而起。当有细作报知司马懿，说孔明退兵了。懿曰：“孔明必有大谋，不可轻动。”张郃曰：“此必因粮尽而回，如何不追？”懿曰：“吾料孔明上年大收，今又麦熟，粮草丰足；虽然转运艰难，亦可支吾半载，安肯便走？彼见吾连日不战，故作此计引诱。可令人远远哨之。”军士探知，回报说：“孔明离此三十里下寨。”懿曰：“吾料孔明果不走。且坚守寨栅，不可轻进。”住了旬日，绝无音信，并不见蜀将来战。懿再令人哨探，回报说：“蜀兵已起营去了。”懿未信，乃更换衣服，杂在军中，亲自来看，果见蜀兵又退三十里下寨。懿回营谓张郃曰：“此乃孔明之计也，不可追赶。”又住了旬日，再令人哨探。回报说：“蜀兵又退三十里下寨。”郃曰：“孔明用缓兵之计，渐退汉中，都督何故怀疑，不早追之？郃愿往决一战！”懿曰：“孔明诡计极多，倘有差失，丧我军之锐气。不可轻进。”郃曰：“某去若败，甘当军令。”懿曰：“既汝要去，可分兵两枝：汝引一枝先行，须要奋力死战；吾随后接应，以防伏兵。汝次日先进，到半途驻扎，后日交战，使兵力不乏。”遂分兵已毕。
次日，张郃、戴陵引副将数十员、精兵三万，奋勇先进，到半路下寨。司马懿留下许多军马守寨，只引五千精兵，随后进发。原来孔明密令人哨探，见魏兵半路而歇。是夜，孔明唤众将商议曰：“今魏兵来追，必然死战，汝等须以一当十，吾以伏兵截其后：非智勇之将，不可当此任。”言毕，以目视魏延。延低头不语。王平出曰：“某愿当之。”孔明曰：“若有失，如何？”平曰：“愿当军令。”孔明叹曰：“王平肯舍身亲冒矢石，真忠臣也！虽然如此，奈魏兵分两枝前后而来，断吾伏兵在中；平纵然智勇，只可当一头，岂可分身两处？须再得一将同去为妙。怎奈军中再无舍死当先之人！”言未毕，一将出曰：“某愿往！”孔明视之，乃张翼也。孔明曰：“张郃乃魏之名将，有万夫不当之勇，汝非敌手。”翼曰：“若有失事，愿献首于帐下。”孔明曰：“汝既敢去，可与王平各引一万精兵伏于山谷中；只待魏兵赶上，任他过尽，汝等却引伏兵从后掩杀。若司马懿随后赶来，却分兵两头：张翼引一军当住后队，王平引一军截其前队。两军须要死战。吾自有别计相助。”二人受计引兵而去。
孔明又唤姜维、廖化分付曰：“与汝二人一个锦囊，引三千精兵，偃旗息鼓，伏于前山之上。如见魏兵围住王平、张翼，十分危急，不必去救，只开锦囊看视，自有解危之策。”二人受计引兵而去。又令吴班、吴懿、马忠、张嶷四将，附耳分付曰：“如来日魏兵到，锐气正盛，不可便迎，且战且走。只看关兴引兵来掠阵之时，汝等便回军赶杀，吾自有兵接应。”四将受计引兵而去。又唤关兴分付曰：“汝引五千精兵，伏于山谷；只看山上红旗飐动，却引兵杀出。”兴受计引兵而去。
却说张郃、戴陵领兵前来，骤如风雨。马忠、张嶷、吴懿、吴班四将接着，出马交锋。张郃大怒，驱兵追杀。蜀兵且战且走，魏兵追赶约有二十余里，时值六月天气，十分炎热，人马汗如泼水。走到五十里外，魏兵尽皆气喘。孔明在山上把红旗一招，关兴引兵杀出。马忠等四将，一齐引兵掩杀回来。张郃、戴陵死战不退。忽然喊声大震，两路军杀出，乃王平、张翼也。各奋勇追杀，截其后路。郃大叫众将曰：“汝等到此，不决一死战，更待何时！”魏兵奋力冲突，不得脱身。忽然背后鼓角喧天，司马懿自领精兵杀到。懿指挥众将，把王平、张翼围在垓心。翼大呼曰：“丞相真神人也！计已算定，必有良谋。吾等当决一死战！”即分兵两路：平引一军截住张郃、戴陵，翼引一军力当司马懿。两头死战，叫杀连天。姜维、廖化在山上探望，见魏兵势大，蜀兵力危，渐渐抵当不住。维谓化曰：“如此危急，可开锦囊看计。”二人拆开视之，内书云：“若司马懿兵来围王平、张翼至急，汝二人可分兵两枝，竟袭司马懿之营；懿必急退，汝可乘乱攻之。营虽不得，可获全胜。”二人大喜，即分兵两路，径袭司马懿营中而去。原来司马懿亦恐中孔明之计，沿途不住的令人传报。懿正催战间，忽流星马飞报，言蜀兵两路竟取大寨去了，懿大惊失色，乃谓众将曰：“吾料孔明有计，汝等不信，勉强追来，却误了大事！”即提兵急回。军心惶惶乱走。张翼随后掩杀，魏兵大败。张郃、戴陵见势孤，亦望山僻小路而走，蜀兵大胜。背后关兴引兵接应诸路。司马懿大败一阵，奔入寨时，蜀兵已自回去。懿收聚败军，责骂诸将曰：“汝等不知兵法，只凭血气之勇，强欲出战，致有此败。今后切不许妄动，再有不遵，决正军法！”众皆羞惭而退。这一阵，魏军死者极多，遗弃马匹器械无数。却说孔明收得胜军马入寨，又欲起兵进取。忽报有人自成都来，说张苞身死。孔明闻知，放声大哭，口中吐血，昏绝于地。众人救醒。孔明自此得病卧床不起。诸将无不感激。后人有诗叹曰：“悍勇张苞欲建功，可怜天不助英雄！武侯泪向西风洒，为念无人佐鞠躬。”
旬日之后，孔明唤董厥、樊建等入帐分付曰：“吾自觉昏沉，不能理事；不如且回汉中养病，再作良图。汝等切勿走泄：司马懿若知，必来攻击。”遂传号令，教当夜暗暗拔寨，皆回汉中。孔明去了五日，懿方得知，乃长叹曰：“孔明真有神出鬼没之计，吾不能及也！”于是司马懿留诸将在寨中，分兵守把各处隘口；懿自班师回。
却说孔明将大军屯于汉中，自回成都养病；文武官僚出城迎接，送入丞相府中，后主御驾自来问病，命御医调治，日渐痊可。建兴八年秋七月，魏都督曹真病可，乃上表说：“蜀兵数次侵界，屡犯中原，若不剿除，必为后患。今时值秋凉，人马安闲，正当征伐。臣愿与司马懿同领大军，径入汉中，殄灭奸党，以清边境。”魏主大喜，问侍中刘晔曰：“子丹劝朕伐蜀，若何？”晔奏曰：“大将军之言是也。今若不剿除，后必为大患。陛下便可行之。睿点头。晔出内回家，有众大臣相探，问曰：“闻天子与公计议兴兵伐蜀，此事如何？”晔应曰：“无此事也。蜀有山川之险，非可易图；空费军马之劳，于国无益。”众官皆默然而出。杨暨入内奏曰：“昨闻刘晔劝陛下伐蜀；今日与众臣议，又言不可伐：是欺陛下也。陛下何不召而问之？”睿即召刘晔入内问曰：“卿劝朕伐蜀；今又言不可，何也？”晔曰：“臣细详之，蜀不可伐。”睿大笑。少时，杨暨出内。晔奏曰：“臣昨日劝陛下伐蜀，乃国之大事，岂可妄泄于人？夫兵者，诡道也：事未发切宜秘之。”睿大悟曰：“卿言是也。”自此愈加敬重。
旬日内，司马懿入朝，魏主将曹真表奏之事，逐一言之。懿奏曰：“臣料东吴未敢动兵，今日正可乘此去伐蜀。”睿即拜曹真为大司马、征西大都督，司马懿为大将军、征西副都督，刘晔为军师。三人拜辞魏主，引四十万大兵，前行至长安，径奔剑阁，来取汉中。其余郭淮、孙礼等，各取路而行。汉中人报入成都。此时孔明病好多时，每日操练人马，习学八阵之法，尽皆精熟，欲取中原；听得这个消息，遂唤张嶷、王平分付曰：“汝二人先引一千兵去守陈仓古道，以当魏兵；吾却提大兵便来接应。”二人告曰：“人报魏军四十万，诈称八十万，声势甚大，如何只与一千兵去守隘口？倘魏兵大至，何以拒之？”孔明曰：“吾欲多与，恐士卒辛苦耳。”嶷与平面面相觑，皆不敢去。孔明曰：“若有疏失，非汝等之罪。不必多言，可疾去。”二人又哀告曰：“丞相欲杀某二人，就此清杀，只不敢去。”孔明笑曰：“何其愚也！吾令汝等去，自有主见：吾昨夜仰观天文，见毕星躔于太阴之分，此月内必有大雨淋漓；魏兵虽有四十万，安敢深入山险之地？因此不用多军，决不受害。吾将大军皆在汉中安居一月，待魏兵退，那时以大兵掩之：以逸待劳，吾十万之众可胜魏兵四十万也。”二人听毕，方大喜，拜辞而去。孔明随统大军出汉中，传令教各处隘口，预备干柴草料细粮，俱够一月人马支用，以防秋雨；将大军宽限一月，先给衣食，伺候出征。却说曹真、司马懿同领大军，径到陈仓城内，不见一间房屋；寻土人问之，皆言孔明回时放火烧毁。曹真便要从陈仓道进发。懿曰：“不可轻进。我夜观天文，见毕星躔于太阴之分，此月内必有大雨；若深入重地，常胜则可。倘有疏虞，人马受苦，要退则难。且宜在城中搭起窝铺住扎，以防阴雨。”真从其言。未及半月，天雨大降，淋漓不止。陈仓城外，平地水深三尺，军器尽湿，人不得睡，昼夜不安。大雨连降三十日，马无草料，死者无数，军士怨声不绝。传入洛阳，魏主设坛，求晴不得。黄门侍郎王肃上疏曰：“前志有之；“千里馈粮，士有饥色；樵苏后爨，师不宿饱。”此谓平途之行军者也。又况于深入险阻，凿路而前，则其为劳，必相百也。今又加之以霖雨，山坂峻滑，众逼而不展，粮远而难继：实行军之大忌也。闻曹真发已逾月，而行方半谷，治道功大，战士悉作：是彼偏得以逸待劳，乃兵家之所惮也。言之前代，则武王伐纣，出关而复还；论之近事，则武、文征权，临江而不济：岂非顺天知时，通于权变者哉？愿陛下念水雨艰剧之故，休息士卒；后日有衅，乘时用之。所谓“悦以犯难，民忘其死”者也。”魏主览表，正在犹豫，杨阜、华歆亦上疏谏。魏主即下诏，遣使诏曹真、司马懿还朝。
却说曹真与司马懿商议曰：“今连阴三十日，军无战心，各有思归之意，如何禁止？”懿曰：“不如且回。”真曰：“倘孔明追来，怎生退之？”懿曰：“先伏两军断后，方可回兵。”正议间，忽使命来召。二人遂将大军前队作后队，后队作前队，徐徐而退。却说孔明计算一月秋雨将尽，天尚未晴，自提一军屯于城固，又传令教大军会于赤坡驻扎。孔明升帐唤众将言曰：“吾料魏兵必走，魏主必下诏来取曹真、司马懿兵回。吾若追之，必有准备；不如任他且去，再作良图。”忽王平令人报来，说魏兵已回。孔明分付来人，传与王平：“不可追袭。吾自有破魏兵之策。”正是：魏兵纵使能埋伏，汉相原来不肯追。
未知孔明怎生破魏，且看下文分解。', '', '', '', '[{"bookId": "60d939cea06dc908f045ad24", "bookTitle": "元明清诗鉴赏辞典（新一版）", "articleId": "610e8d247d0ac11454951f95", "shortContent": "作者金和，曾被梁启超誉为“中国文学革命的先驱”（《晚清两大家诗钞题辞》）。的确，在近代诗人中，金和是一位非常有特色的作家。他的许多古体和乐府都写得极其通俗，不少作品较多使用俚词俗语。长篇叙事诗如《兰陵女儿行》、《烈女行纪黄婉梨事》等还吸取了小说的某些表现手法，对中国叙事诗的发展做出了贡献。然而，最能显示作者艺术风貌和艺术个性的，还是他的讽刺诗。\n本诗是他讽刺佳作中的一首。题目中的一个“战”字，就是...", "authors": ["马亚中"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42b55e272d4b2255ce5b", "shortContent": "本篇系《西汉通俗演义》第八十二回。作者甄伟编著本书的目的是“因略以致详，考史以广义”，从而“使刘项之强弱，楚汉之兴亡，一展卷而悉在目中”（《西汉通俗演义序》）。即通过对史实的考订和丰富详赡的描写，揭示楚汉兴亡的“大义”，使读者受到教益。\n项羽的出身、名望与实力都胜过刘邦，但为什么最终竟是汉胜而楚灭？韩信曾分析项羽的性格特征：“项王喑喑叱咤，千人皆废，然不能任属贤将，此恃匹夫之勇耳！……项王虽霸天下...", "authors": ["曾", "良"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42cec6e67846a9227c97", "shortContent": "本篇选自《洪秀全演义》中第十回。作者黄小配。此书仅写了五十四回，对太平天国起义和太平天国人物表示了无限的崇敬，给予了高度的评价。书未完，黄小配被军阀陈炯明杀害。\n本篇主要写了两个战事：计赚乌兰泰；误走张嘉祥。作者成功地吸取传统的写作技法，使人物形象跃然纸上，在行文上也极有章法。\n小说写道：乌兰泰领大队清军扎营江口，与洪秀全义军对垒，却迟迟不见洪军动静。参谋张奋扬预感其中有诈，建议不要轻动。乌兰泰自...", "authors": ["张成全"], "pressName": "上海辞书出版社"}]', '', 'indent', 1536943882, '5b9b743f808ca43cd222d819', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (639239, '三国演义 · 第一百回 · 汉兵劫寨破曹真 武侯斗阵辱仲达', NULL, 2, 120, 0, 1, '罗贯中', NULL, 36958, '5b98c834808ca43cd206d5c7', '明', 'wen', '文', '', '', ' 却说众将闻孔明不追魏兵，俱入帐告曰：“魏兵苦雨，不能屯扎，因此回去，正好乘势追之。丞相如何不追？”孔明曰：“司马懿善能用兵，今军退必有埋伏。吾若追之，正中其计。不如纵他远去，吾却分兵径出斜谷而取祁山，使魏人不提防也。”众将曰：“取长安之地，别有路途；丞相只取祁山，何也？”孔明曰：“祁山乃长安之首也：陇西诸郡，倘有兵来，必经由此地；更兼前临渭滨，后靠斜谷，左出右入。可以伏兵，乃用武之地。吾故欲先取此，得地利也。”众将皆拜服。孔明令魏延、张嶷、杜琼、陈式出箕谷；马岱、王平、张翼、马忠出斜谷：俱会于祁山。调拨已定，孔明自提大军，令关兴、廖化为先锋，随后进发。却说曹真、司马懿二人，在后监督人马，令一军入陈仓古道探视，回报说蜀兵不来。又行旬日，后面埋伏众将皆回，说蜀兵全无音耗。真曰：“连绵秋雨，栈道断绝，蜀人岂知吾等退军耶？”懿曰：“蜀兵随后出矣。”真曰：“何以知之？”懿曰：“连日晴明，蜀兵不赶，料吾有伏兵也，故纵我兵远去；待我兵过尽，他却夺祁山矣。”曹真不信。懿曰：“子丹如何不信？吾料孔明必从两谷而来。吾与子丹各守一谷口，十日为期。若无蜀兵来，我面涂红粉，身穿女衣，来营中伏罪。”真曰：“若有蜀兵来，我愿将天子所赐玉带一条、御马一匹与你。”即分兵两路：真引兵屯于祁山之西，斜谷口；懿引军屯于祁山之东，箕谷口。各下寨已毕。懿先引一枝兵伏于山谷中；其余军马，各于要路安营。懿更换衣装，杂在全军之内，遍观各营。忽到一营，有一偏将仰天而怨曰：“大雨淋了许多时，不肯回去；今又在这里顿住，强要赌赛，却不苦了官军！”懿闻言，归寨升帐，聚众将皆到帐下，挨出那将来。懿叱之曰：“朝廷养军千日，用在一时。汝安敢出怨言，以慢军心！”其人不招。懿叫出同伴之人对证，那将不能抵赖。懿曰：“吾非赌赛；欲胜蜀兵，令汝各人有功回朝，汝乃妄出怨言，自取罪戾！”喝令武士推出斩之。须臾，献首帐下。众将悚然。懿曰：“汝等诸将皆要尽心以防蜀兵。听吾中军炮响，四面皆进。”众将受令而退。
却说魏延、张嶷、陈式、杜琼四将，引二万兵，取箕谷而进。正行之间，忽报参谋邓芝到来。四将问其故，芝曰：“丞相有令：如出箕谷，提防魏兵埋伏，不可轻进。”陈式曰：“丞相用兵何多疑耶？吾料魏兵连遭大雨，衣甲皆毁，必然急归；安得又有埋伏？今吾兵倍道而进，可获大胜，如何又教休进？”芝曰：“丞相计无不中，谋无不成，汝安敢违令？”式笑曰：“丞相若果多谋，不致街亭之失！”魏延想起孔明向日不听其计，亦笑曰：“丞相若听吾言，径出子午谷，此时休说长安，连洛阳皆得矣！今执定要出祁山。有何益耶？既令进兵，今又教休进。何其号令不明！”式曰：“吾自有五千兵，径出箕谷，先到祁山下寨，看丞相羞也不羞！”芝再三阻当，式只不听，径自引五千兵出箕谷去了。邓芝只得飞报孔明。
却说陈式引兵行不数里，忽听的一声炮响，四面伏兵皆出。式急退时，魏兵塞满谷口，围得铁桶相似。式左冲右突，不能得脱。忽闻喊声大震，一彪军杀入，乃是魏延。救了陈式，回到谷中，五千兵只剩得四五百带伤人马。背后魏兵赶来，却得杜琼、张嶷引兵接应，魏兵方退。陈、魏二人方信孔明先见如神，懊悔不及。
且说邓芝回见孔明，言魏延、陈式如此无礼。孔明笑曰：“魏延素有反相，吾知彼常有不平之意；因怜其勇而用之。久后必生患害。”正言间，忽流星马报到，说陈式折了四千余人，止有四五百带伤人马，屯在谷中。孔明令邓芝再来箕谷抚慰陈式，防其生变；一面唤马岱、王平分付曰：“斜谷若有魏兵守把，汝二人引本部军越山岭，夜行昼伏，速出祁山之左，举火为号。”又唤马忠、张翼分付曰：“汝等亦从山僻小路，昼伏夜行，径出祁山之右，举火为号，与马岱、王平会合，共劫曹真营寨。吾自从谷中三面攻之，魏兵可破也。”四人领命分头引兵去了。孔明又唤关兴、廖化分付曰：如此如此。二人受了密计，引兵而去。孔明自领精兵倍道而行。正行间，又唤吴班、吴懿授与密计，亦引兵先行。
却说曹真心中不信蜀兵来，以此怠慢，纵令军士歇息；只等十日无事，要羞司马懿，不觉守了七日，忽有人报谷中有些小蜀兵出来。真令副将秦良引五千兵哨探，不许纵令蜀兵近界。秦良领命，引兵刚到谷口，哨见蜀兵退去。良急引兵赶来，行到五六十里，不见蜀兵，心下疑惑，教军士下马歇息。忽哨马报说：“前面有蜀兵埋伏。”良上马看时，只见山中尘土大起，急令军士提防。不一时，四壁厢喊声大震：前面吴班、吴懿引兵杀出，背后关兴、廖化引兵杀来。左右是山，皆无走路。山上蜀兵大叫：“下马投降者免死！”魏兵大半多降。秦良死战，被廖化一刀斩于马下。
孔明把降兵拘于后军，却将魏兵衣甲与蜀兵五千人穿了，扮作魏兵，令关兴、廖化、吴班、吴懿四将引着，径奔曹真寨来；先令报马入寨说：“只有些小蜀兵，尽赶去了。”真大喜。忽报司马都督差心腹人至。真唤入问之。其人告曰：“今都督用埋伏计，杀蜀兵四千余人。司马都督致意将军，教休将赌赛为念，务要用心提备。”真曰：“吾这里并无一个蜀兵。”遂打发来人回去。忽又报秦良引兵回来了。真自出帐迎之。比及到寨，人报前后两把火起。真急回寨后看时，关兴、廖化、吴班、吴懿四将，指麾蜀军，就营前杀将进来；马岱、王平从后面杀来；马忠、张翼亦引兵杀到。魏军措手不及，各自逃生。众将保曹真望东而走，背后蜀兵赶来。
曹真正奔走，忽然喊声大震，一彪军杀到。真胆战心惊，视之，乃司马懿也。懿大战一场，蜀兵方退。真得脱，羞惭无地。懿曰：“诸葛亮夺了祁山地势，吾等不可久居此处；宜去渭滨安营，再作良图。”真曰：“仲达何以知吾遭此大败也？”懿曰：“见来人报称子丹说并无一个蜀兵，吾料孔明暗来劫寨，因此知之，故相接应。今果中计。切莫言赌赛之事，只同心报国。”曹真甚是惶恐，气成疾病，卧床不起。兵屯渭滨，懿恐军心有乱，不敢教真引兵。
却说孔明大驱士马，复出祁山。劳军已毕，魏延、陈式、杜琼、张嶷入帐拜伏请罪。孔明曰：“是谁失陷了军来？”延曰：“陈式不听号令，潜入谷口，以此大败。”式曰：“此事魏延教我行来。”孔明曰：“他倒救你，你反攀他！将令已违，不必巧说！”即叱武士推出陈式斩之。须臾，悬首于帐前，以示诸将。此时孔明不杀魏延，欲留之以为后用也。
孔明既斩了陈式，正议进兵，忽有细作报说曹真卧病不起，现在营中治疗。孔明大喜，谓诸将曰：“若曹真病轻，必便回长安。今魏兵不退，必为病重，故留于军中，以安众人之心。吾写下一书，教秦良的降兵持与曹真，真若见之，必然死矣！”遂唤降兵至帐下，问曰：“汝等皆是魏军，父母妻子多在中原，不宜久居蜀中。今放汝等回家，若何？”众军泣泪拜谢。孔明曰：“曹子丹与吾有约；吾有一书，汝等带回，送与子丹，必有重赏。”魏军领了书，奔回本寨，将孔明书呈与曹真。真扶病而起，拆封视之。其书曰：“汉丞相、武乡侯诸葛亮，致书于大司马曹子丹之前：窃谓夫为将者，能去能就，能柔能刚；能进能退，能弱能强。不动如山岳，难测如阴阳；无穷如天地，充实如太仓；浩渺如四海，眩曜如三光。预知天文之旱涝，先识地理之平康；察阵势之期会，揣敌人之短长。嗟尔无学后辈，上逆穹苍；助篡国之反贼，称帝号于洛阳；走残兵于斜谷，遭霖雨于陈仓；水陆困乏，人马猖狂；抛盈郊之戈甲，弃满地之刀枪；都督心崩而胆裂，将军鼠窜而狼忙！无面见关中之父老，何颜入相府之厅堂！史官秉笔而记录，百姓众口而传扬：仲达闻阵而惕惕，子丹望风而遑遑！吾军兵强而马壮，大将虎奋以龙骧；扫秦川为平壤，荡魏国作丘荒！”曹真看毕，恨气填胸；至晚，死于军中。司马懿用兵车装载，差人送赴洛阳安葬。
魏主闻知曹真已死，即下诏催司马懿出战。懿提大军来与孔明交锋，隔日先下战书。孔明谓诸将曰：“曹真必死矣。”遂批回“来日交锋”，使者去了。孔明当夜教姜维受了密计：如此而行；又唤关兴分付：如此如此。
次日，孔明尽起祁山之兵前到谓滨：一边是河，一边是山，中央平川旷野，好片战场！两军相迎，以弓箭射住阵角。三通鼓罢，魏阵中门旗开处，司马懿出马，众将随后而出。只见孔明端坐于四轮车上，手摇羽扇。懿曰：“吾主上法尧禅舜，相传二帝，坐镇中原，容汝蜀、吴二国者，乃吾主宽慈仁厚，恐伤百姓也。汝乃南阳一耕夫，不识天数，强要相侵，理宜殄灭！如省心改过，宜即早回，各守疆界，以成鼎足之势，免致生灵涂炭，汝等皆得全生！”孔明笑曰：“吾受先帝托孤之重，安肯不倾心竭力以讨贼乎！汝曹氏不久为汉所灭。汝祖父皆为汉臣，世食汉禄，不思报效，反助篡逆，岂不自耻？”懿羞惭满面曰：“吾与汝决一雌雄！汝若能胜，吾誓不为大将！汝若败时，早归故里，吾并不加害。”
孔明曰：“汝欲斗将？斗兵？斗阵法？”懿曰：“先斗阵法？”孔明曰：“先布阵我看。懿入中军帐下，手执黄旗招飐，左右军动，排成一阵。复上马出阵，问曰：“汝识吾阵否？”孔明笑曰：“吾军中末将，亦能布之。此乃‘混元一气阵’也。”懿曰：“汝布阵我看。”孔明入阵，把羽扇一摇，复出阵前，问曰：“汝识我阵否？”懿曰：“量此‘八卦阵’，如何不识！”孔明曰：“识便识了，敢打我阵否？”懿曰：“既识之，如何不敢打！”孔明曰：“汝只管打来。”司马懿回到本阵中，唤戴陵、张虎、乐綝三将，分付曰：“今孔明所布之阵，按休、生、伤、杜、景、死、惊、开八门。汝三人可从正东‘生门’打入，往西南休门杀出，复从正北‘开门’杀入：此阵可破。汝等小心在意！”
于是戴陵在中，张虎在前，乐綝在后，各引三十骑，从生门打入。两军呐喊相助。三人杀入蜀阵，只见阵如连城，冲突不出。三人慌引骑转过阵脚，往西南冲去，却被蜀兵射住，冲突不出。阵中重重叠叠，都有门户，那里分东西南北？三将不能相顾，只管乱撞，但见愁云漠漠，惨雾蒙蒙。喊声起处，魏军一个个皆被缚了，送到中军。
孔明坐于帐中，左右将张虎、戴陵、乐綝并九十个军，皆缚在帐下。孔明笑曰：“吾纵然捉得汝等，何足为奇！吾放汝等回见司马懿，教他再读兵书，重观战策，那时来决雌雄，未为迟也。汝等性命既饶，当留下军器战马。”遂将众人衣服脱了，以墨涂面，步行出阵。司马懿见之大怒，回顾诸将曰：“如此挫败锐气，有何面目回见中原大臣耶！”即指挥三军，奋死掠阵，懿自拔剑在手，引百余骁将，催督冲杀。
两军恰才相会，忽然阵后鼓角齐鸣，喊声大震，一彪军从西南上杀来，乃关兴也。懿分后军当之，复催军向前厮杀。忽然魏兵大乱：原来姜维引一彪军悄地杀来，蜀兵三路夹攻。懿大惊，急忙退军。蜀兵周围杀到，懿引三军望南死命冲击。魏兵十伤六七。司马懿退在渭滨南岸下寨，坚守不出。
孔明收得胜之兵，回到祁山时，永安城李严遣都尉苟安解送粮米，至军中交割。苟安好酒，于路怠慢，违限十日。孔明大怒曰：“吾军中专以粮为大事，误了三日，便该处斩！汝今误了十日，有何理说？”喝令推出斩之。长史杨仪曰：“苟安乃李严用人，又兼钱粮多出于西川，若杀此人，后无人敢送粮也。”孔明乃叱武士去其缚，杖八十放之。苟安被责，心中怀恨，连夜引亲随五六骑，径奔魏寨投降。懿唤入，苟安拜告前事。懿曰：“虽然如此，孔明多谋，汝言难信。汝能为我干一件大功，吾那时奏准天子，保汝为上将。”安曰：“但有甚事，即当效力。”懿曰：“汝可回成都布散流言，说孔明有怨上之意，早晚欲称为帝，使汝主召回孔明：即是汝之功矣。”苟安允诺，径回成都，见了宦官，布散流言，说孔明自倚大功，早晚必将篡国。宦官闻知大惊，即入内奏帝，细言前事。后主惊讶曰：“似此如之奈何？宦官曰：“可诏还成都，削其兵权，免生叛逆。”后主下诏，宣孔明班师回朝。蒋琬出班奏曰：“丞相自出师以来，累建大功，何故宣回？”后主曰：“朕有机密事，必须与丞相面议。”即遣使赍诏星夜宣孔明回。
使命径到祁山大寨，孔明接入，受诏已毕，仰天叹曰：“主上年幼，必有佞臣在侧！吾正欲建功，何故取回？我如不回，是欺主矣。若奉命而退，日后再难得此机会也。”姜维问曰：“若大军退，司马懿乘势掩杀，当复如何？”孔明曰：“吾今退军，可分五路而退。今日先退此营，假如营内一千兵，却掘二千灶，明日掘三千灶，后日掘四千灶：每日退军，添灶而行。”杨仪曰：“昔孙膑擒庞涓，用添兵减灶之法而取胜；今丞相退兵，何故增灶？”孔明曰：“司马懿善能用兵，知吾兵退，必然追赶；心中疑吾有伏兵，定于旧营内数灶；见每日增灶，兵又不知退与不退，则疑而不敢追。吾徐徐而退，自无损兵之患。”遂传令退军。
却说司马懿料苟安行计停当，只待蜀兵退时，一齐掩杀。正踌躇间，忽报蜀寨空虚，人马皆去。懿因孔明多谋，不敢轻追，自引百余骑前来蜀营内踏看，教军士数灶，仍回本寨；次日，又教军士赶到那个营内，查点灶数。回报说：“这营内之灶，比前又增一分。”司马懿谓诸将曰：“吾料孔明多谋，今果添兵增灶，吾若追之，必中其计；不如且退，再作良图。”于是回军不追。孔明不折一人，望成都而去。次后，川口土人来报司马懿，说孔明退兵之时，未见添兵，只见增灶。懿仰天长叹曰：“孔明效虞诩之法，瞒过吾也！其谋略吾不如之！”遂引大军还洛阳。正是：棋逢敌手难相胜，将遇良才不敢骄。
未知孔明退回成都，竟是如何，且看下文分解。
