INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640175, '三国志 · 魏书 · 诸夏侯曹传', NULL, 5, 66, 1, 1, '陈寿', NULL, 10399, '57ec58715bbb50005bd458f9', '晋', 'wen', '文', '', '', '夏侯惇字元让，沛国谯人，夏侯婴之后也。年十四，就师学。人有辱其师者，惇杀之，由是以烈气闻。太祖初起，惇常为裨将，从征伐。太祖行奋武将军，以惇为司马，别屯白马，迁折冲校尉，领东郡太守。太祖征陶谦，留惇守濮阳。张邈叛迎吕布，太祖家在鄄城，惇轻军往赴，适与布会，交战。布退还，遂入濮阳，袭得惇军辎重。遣将伪降，共执持惇，责以宝货，惇军中震恐。惇将韩浩乃勒兵屯惇营门，召军吏诸将，皆案甲当部不得动，诸营乃定。遂诣惇所，叱持质者曰：“妆等凶逆，乃敢执劫大将军，复欲望生邪！且吾受命讨贼，宁能以一将军之故，而纵汝乎？”因涕泣谓惇曰：“当奈国法何！”促召兵击持质者。持质者惶遽叩头，言：“我但欲乞资用去耳！”浩数责，皆斩之。
惇既免，太祖闻之，谓浩曰：“卿此可为万世法。”乃着令：“自今已后有持质者，皆当并击，勿颐质。由是劫质者遂绝。
太祖自徐州还，惇从征吕布。为流矢所中，伤左目。复领陈留、济阴太守，加建武将军，封高安乡侯。时大旱，蝗虫起，惇乃断太寿水作陂，身自负土，率将士劝种稻，民赖其利。转领河南尹。太祖平河北，为大将军后拒。邺破，迁伏波将军，领尹如故，使得以便宜从事，不拘科制。建安十二年，录惇前后功，增封邑千八百户，并前二千五百户。二十一年，从征孙权还，使惇都督二十六军，留居巢。赐伎乐名倡。令曰：“魏绛以和戎之功，犹受金石之乐，况将军乎！”二十四年，太祖军（击破吕布军）于摩陂，召惇常与同载，特见亲重，出入卧内，诸将莫得比也。拜前将军，督诸军还寿春，徙屯召陵。文帝即王位，拜惇大将军，数月薨。
惇虽在军旅，亲迎师受业。性清俭，有余财辄以分施。不足资之于官，不治产业。
谥曰忠侯，子充嗣。帝追思惇功，欲使子孙毕侯，分惇邑千户，赐惇七子二孙爵皆关内侯。惇弟廉及子楙素自封列侯。初，太祖以女妻楙，即清河公主也。楙历位侍中、尚书、安西、镇东将军，假节。充薨，子廙嗣。廙薨，子劭嗣。
韩浩者，河内人。（及）沛国史涣与浩俱以忠勇显。浩至中护军，涣至中领军，皆掌禁兵，封列侯。
夏侯渊字妙才，惇族弟也。太祖居家，曾有县官事，渊代引重罪，太祖营救之，得免。太祖起兵，以别部司马、骑都尉从，迁陈留、颖川太守。及与袁绍战于官渡，行督军校尉。绍破，使督兖、豫、徐州军粮。时军食少，渊传馈相继，军以复振。昌狶反，遣于禁击之，未拔。复遣渊与禁并力，遂击狶，降其十余屯，狶诣禁降。渊还，拜典军校尉。济南、乐安黄巾徐和、司马俱等攻城，杀长吏，渊将泰山、齐、平原郡兵击，大破之，斩和，平诸县，收其粮谷以给军士。十四年，以渊为行领军。太祖征孙权还，使渊督诸将击庐江叛者雷绪，绪破，又行征西护军，督徐晃击太原贼，攻下二十余屯，斩贼帅商曜，屠其城。从征韩遂等，战于渭南。又督朱灵平隃糜、（氵干干）氐。与太祖会安定，降杨秋。
十七年，太祖乃还邺，以渊行护军将军，督朱灵、路招等屯长安，击破南山贼刘雄，降其众。围遂、超余党梁兴于鄠，拔之，斩兴，封博昌亭侯。马超围凉州刺史韦康于冀。
渊救康，未到，康败。去冀二百余里，超来逆战，军不利。（氵干干）氐反，渊引军还。
十九年，赵衢、尹奉等谋讨超，姜叙起兵卤城以应之。衢等谲说超，使出击叙，于后尽杀超妻子。超奔汉中，还围祁山。叙等急求救，诸将议者欲须太祖节度。渊曰：“公在邺，反复四千里，比报，叙等必败，非救急也。”遂行，使张合督步骑五千在前，从陈仓狭道入，渊自督粮在后。合至渭水上，超将氐、羌数千逆合.未战，超走，合进军收超军器械。渊到，诸县皆己降。韩遂在显亲，渊欲袭取之，遂走。渊收遂军粮，追至略阳城，去遂二十余里，诸将欲攻之，或言当攻兴国氐。渊以为遂兵精，兴国城固，攻不可卒拔，不如击长离诸羌。长离诸羌多在遂军，必归救其家。若[舍]羌独守则孤，救长离官兵得与野战，可必虏也。渊乃留督将守辎重，轻兵步骑到长离，攻烧羌屯，斩获其众。诸羌在遂军者，各还种落。遂果救长离，与渊军对陈。诸将见遂众，恶之，欲结营作堑乃与战。渊曰：“我转斗千里，今复作营堑，则士众罢弊，不可久。贼虽众，易与耳。”乃鼓之，大破遂军，得其旌麾，还略阳，进军围兴国。氐王千万逃奔马超，余众降。转击高平屠各，皆散走，收其粮谷牛马。乃假渊节。
初，枹罕宋建因凉州乱，自号河首平汉王。太祖使渊帅诸将讨建。渊至，围枹罕。
月余拔之，斩建及所置丞相已下。渊别遣张合等平河关，渡河入小湟中，河西诸羌尽降，陇右平。太祖下令曰：“宋建造为乱逆三十余年，渊一举灭之，虎步关右，所向无前。
仲尼有言：“吾于尔不如也。‘二十一年，增封三百户，并前八百户。还击武都氐羌下辩，收氐谷十余万斛。太祖西征张鲁，渊等将凉州诸将侯王已下，与太祖会休亭。太祖每引见羌、胡，以渊畏之。会鲁降，汉中平，以渊行都护将军，督张合、徐晃等平巴郡。
太祖还邺。留渊守汉中，即拜渊征西将军。二十三年，刘备军阳平关，渊率诸将拒之。
相守连年。二十四年正月，备夜烧围鹿角。渊使张合护东围，自将轻兵护南围。备跳合战，合军不利。渊分所将兵半助合，为备所袭，渊遂战死。谥曰愍侯。
初，渊虽数战胜，太祖常戒曰：“为将当有怯弱时，不可但恃勇也。将当以勇为本，行之以智计；但知任勇，一匹夫敌耳。”
渊妻，太祖内妹。长子衡，尚太祖弟海阳哀侯女，恩宠特隆。衡袭爵，转封安宁亭侯。黄初中，赐中子霸，太和中，赐霸四弟，爵皆关内侯。霸，正始中为讨蜀护军、右将军，进封博昌亭侯，素为曹爽所厚。闻爽诛，自疑，亡入蜀。以渊旧勋赦霸子，徙乐浪郡。霸弟威，官至兖州刺史。威弟惠，乐安太守。惠弟和，河南尹。衡薨，子绩嗣，为虎贲中郎将。绩薨。子褒嗣。
曹仁字子孝，太祖从弟也。少好弓马弋猎。后豪杰并起，仁亦阴结少年，得千余人，周旅淮、泗之间，遂从太祖为别部司马，行厉锋校尉。太祖之破袁术，仁所斩获颇多。
从征徐州，仁常督骑，为军前锋。别攻陶谦将吕由，破之。还与大军合彭城，大破谦军。
后攻费、华、即墨、开阳，谦遣别将救诸县，仁以骑击破之。太祖征吕布，仁别攻句阳，拔之，生获布将刘何。太祖平黄巾，迎天子都许。仁数有功，拜广阳太守。太祖器其勇略，不使之郡，以议郎督骑。太祖征张绣，仁别徇旁县，虏其男女三千余人。太祖军还，为绣所追，军不利，士卒丧气，仁率厉将士甚奋，太祖壮之，遂破绣。
太祖与袁绍久相持于官渡，绍遣刘备徇（氵隐）强诸县，多举众应之。自许以南，吏民不安，太祖以为忧。仁曰：“南方以大军方有目前急，其势不能相救，刘备以强兵临之，其背叛固宜也。备新将绍兵，未能得其用，击之可破也。”太祖善其言，遂使将骑击备，破走之。仁尽复收诸叛县而还。绍遣别将韩荀抄断西道，仁击荀于鸡洛山，大破之。由是绍不敢复分兵出。复与史涣等抄绍运车，烧其粮谷。
河北既定，从围壶关。太祖令曰：“城拔，皆坑之。”连月不下。仁言于太祖曰：“围城必示之活门，所以开其生路也。今公告之必死，将人自为守。且城固而粮多，攻之则士卒伤，守之则引日久。今顿兵坚城之下，以攻必死之虏，非良计也。”太祖从之，城降。于是录仁前后功，封都亭侯。
从平荆州，以仁行征南将军，留屯江陵，拒吴将周瑜。瑜将数万众来攻，前锋数千人始至，仁登城望之，乃募得三百人，遣部曲将牛金逆与挑战。贼多，金众少，遂为所围。长史陈矫俱在城上，望见金等垂没，左右皆失色。仁意气奋怒甚，谓左右：“取马来！”矫等共援持之。谓仁曰：“贼众盛，不可当也。假使弃数百人何苦，而将军以身赴之！”仁不应，遂被甲上马，将其麾下壮士数十骑出城。去贼百余步，迫沟。矫等以为仁当住沟上，为金形势也，仁径渡沟直前，冲入贼围，金等乃得解。余众未尽出，仁复直还突之，拔出金兵，亡其数人，贼众乃退。矫等初见仁出，皆惧。及见仁还，乃叹曰：“将军真天人也！”三军服其勇。太祖益壮之，转封安平亭侯。
太祖讨马超，以仁行安西将军，督诸将拒潼关，破超渭南。苏伯、田银反，以仁行骁骑将军，都督七军讨银等，破之。复以仁行征南将军，假节，屯樊，镇荆州。侯音以宛叛，略傍县众数千人，仁率诸军攻破音，斩其首，还屯樊，即拜征南将军。关羽攻樊。
时汉水暴溢，于禁等七军皆没，禁降羽。仁人马数千人守城，城不没者数板。羽乘船临城，围数重，外内断绝，粮食欲尽，救兵不至。仁激厉将士，示以必死，将士感之皆无二。徐晃救至，水亦稍减，晃从外击羽，仁得溃围出，羽退走。
仁少时不修行检，及长为将，严整奉法令，常置科于左右，案以从事。鄢陵侯彰北征乌丸，文帝在东宫，为书戒彰曰：“为将奉法，不当如征南邪！”及即王位，拜仁车骑将军，都督荆、扬、益州诸军事，进封陈侯，增邑二千，并前三千五百户。追赐仁父炽谥曰陈穆侯，置守家十家。后召还屯宛。孙权遣将陈邵据襄阳，诏仁讨之。仁与徐晃攻破邵，遂人襄阳，使将军高迁等徙汉南附化民于汉北，文帝遣使即拜仁大将军。又诏仁移屯临颖，迁大司马，复督诸军据乌江，还屯合肥。黄初四年薨，谥曰忠侯。子泰嗣，官至镇东将军，假节，转封宁陵侯。泰薨，子初嗣。又分封泰弟楷、范，皆为列侯，而牛金官至后将军。
仁弟纯，初以仪郎参司空军事，督虎豹骑从围南皮。袁谭出战，土卒多死。太祖欲缓之，纯曰：“今千里蹈敌，进不能克，退必丧威。且县师深入，难以持久，彼胜而骄，我败而惧，以惧敌骄，必可克也。”太祖善其言，遂急攻之，谭败。纯麾下骑斩谭首。
及北征三郡，纯部骑获单于蹹顿。以前后功封高陵亭侯，邑三百户。从征荆州，追刘备于长坂，获其二女、辎重，收其散率。进降江陵，从还谯。建安十五年薨。文帝即位，追谥曰威侯，子演嗣。官至领军将军，正元中进封平乐乡侯。演薨，子亮嗣。
曹洪字子廉，太祖从弟也。太祖起义兵讨董卓，至荧阳，为卓将徐荣所败。太祖失马，贼追甚急。洪下，以马授太祖，太祖辞让，洪曰：“天下可无洪，不可无君。”遂步从到汴水，水深不得渡，洪循水不得船，与太祖俱济，还奔谯。扬州刺史陈温素与洪善，洪将家兵千余人，就温募兵，得庐江上甲二千人，东到丹杨复得数干人，与太祖会龙亢。太祖征徐州，张邈举兖州叛迎吕布。时大饥荒，洪将兵在前，先据东平、范，聚粮谷以继军。太祖讨邈、布于濮阳，布破走，遂据东阿，转击济阴、山阳、中牟、阳武、京、密十余县，皆拔之。以前后功拜鹰扬校尉，迁扬武中郎将。天子都许，拜洪谏议大夫。别征刘表。破表别将于舞阳、阴叶、堵阳、博望，有功，迁厉锋将军，封国明事侯。
累从征伐，拜都护将军。文帝即位，为卫将军，迁骠骑将军，进封野王侯，益邑千户，并前二千一百户，位特进，后徙封都阳侯。
始，洪家富而性吝啬，文帝少时假求不称，常恨之，遂以舍客犯法，下狱当死。群臣并救莫能得。卞太后谓郭后曰：“令曹洪今日死，吾明日敕帝废后矣。”于是泣涕屡请，乃得免官削爵士。洪先帝功臣，时人多为觖望。明帝即位，拜后将军，更封乐城侯，邑千户，位特进，复拜骠骑将军。太和六年薨，谥曰恭侯。子馥，嗣侯。初，太祖分洪户封子震列侯。洪族父瑜，修慎笃敬，官至卫将军，封列侯。
曹休字文烈，太祖族子也。天下乱，宗族各散去乡里。休年十余岁丧父，独与一客担丧假葬，携将老母，渡江至吴。以太祖举义兵，易姓名转至荆州，间行北归，见太祖。
太祖谓左右曰：“此吾家千里驹也。”使与文帝同止，见待如子。常从征伐，使领虎豹骑宿卫。刘备遣将吴兰屯下辩。太祖遣曹洪征之，以休为骑都尉，参洪军事。太祖谓休曰：“欲虽参军，其实帅也。”洪闻此令，亦委事于休。备遣张飞屯固山，欲断军后。
众议狐疑，休曰：“贼实断道者，当伏兵潜行。今乃先张声势，此其不能也。宜及其未集，促击兰，兰破则飞自走矣。”洪从之，进兵击兰，大破之，飞果走。太祖拔汉中诸军还长安，拜休中领军。文帝即王位，为领军将军，录前后功，封东阳亭侯。夏侯惇薨，以休为镇南将军，假节，都督诸军事，车驾临送，上乃下舆执手而别。孙权遣将屯历阳。
休列，击破之，又别遣兵渡江，烧贼芜湖营数千家。迁征东将军，领扬州刺史，进封安阳乡侯。帝征孙权，以休为征东大将军，假黄钺，督张辽等及诸州郡二十余军，击权大将吕范等于洞浦，破之。拜扬州牧。明帝即位，进封长平侯。吴将审德屯皖，休击破之，斩德首，吴将韩综、翟丹等前后率众诣休降。增邑四百，并前二千五百户，迁大司马，都督扬州如故。太和二年，帝为二道征吴，遣司马宣王从汉水下，督休诸军向寻阳。贼将伪降，休深入，战不利，退还宿石亭。军夜惊，士卒乱，弃甲兵辎重甚多。休上书谢罪，帝遣屯骑校尉杨暨慰谕，礼赐益隆。休因此痈发背薨，谥曰壮侯，子肇嗣。
肇有当世才度，为散骑常侍、屯骑校尉。明帝寝疾，方与燕王宇等属以后事。帝意寻变，诏肇以侯归第。正始中薨，追赠卫将军，子兴嗣。初，文帝分休户三百封肇弟纂为列侯，后为殄吴将军，薨，追赠前将军。
曹真字子丹，太祖族子也。太祖起兵，真父邵募徒众，为州郡所杀。太祖哀真少孤，收养与诸子同，使与文帝共止。常猎，为虎所逐。顾射虎，应声而倒。太祖壮其鸷勇，使将虎豹骑。讨灵丘贼，拔之，封灵寿亭侯。以偏将军将兵击刘备别将于辩，破之，拜中坚将军。从至长安，领中领军。是时，夏侯渊没于阳平，太祖忧之。以真为征蜀护军，督徐晃等破刘备别将高详于阳平。太祖自至汉中，拔出诸军，使真至武都迎曹洪等还屯陈仓。文帝即王位，以真为镇西将军，假节，都督雍、凉州诸军事。录前后功，进封东乡侯。张进等反于酒泉，真遣费曜讨破之。斩进等。黄初三年还京都，以真为上军大将军，都督中外诸军事，假节钺。与夏侯尚等征孙权，击牛渚屯，破之。转拜中军大将军，加给事中。七年，文帝寝疾，真与陈群、司马宣王等受遗诏辅政。明帝即位，进封邵陵侯，迁大将军。
诸葛亮围祁山，南安、天水、安定三郡反应亮。帝遣真督诸军军郿，遣张合击亮将马谡，大破之。安定民杨条等略吏民保月支城，真进军围之条谓其众曰：“大将军自来，吾愿早降耳。”遂自缚出，三郡皆平。真以亮惩于祁山，后出必从陈仓。乃使将军郝昭、王生守陈仓，治其城。明年春，亮果围陈仓，已有备而不能克。增邑，并前二千九百户。
四年，朝洛阳，迁大司马，赐剑履上殿，入朝不趋。真以“蜀连出侵边境，宜遂伐之，数道并入，可大克也。”帝从其计。真当发西讨，帝亲临送。真以八月发长安，从子午道南入。司马宣王溯汉水，当会南郑。诸军或从斜谷道，或从武威入。会大霖雨三十余日，或栈道断绝，诏真还军。
真少与宗人曹遵、乡人朱赞并事太祖。遵，赞早亡。真愍之，乞分所食邑封遵、赞子。诏曰：“大司马有叔向抚孤之仁。笃晏平久要之分。君子成人之美，听分真邑赐遵、赞子爵关内侯，各百户。”真每征行，与将士同劳苦，军赏不足，辄以家财班赐，士卒皆愿为用。真病还洛阳，帝自幸其第省疾。真薨，谥曰元侯，于爽嗣。帝追思真功，诏曰：“大司马蹈履忠节，佐命二祖，内不恃亲戚之宠，外不骄白屋之士，可谓能封盈守位，劳谦其德者也。其悉封真五子羲、训、则、彦、皑皆为列侯。”初，文帝分真邑二百户，封真弟彬为列侯。
爽字昭伯，少以宗至谨重，明帝在东宫，甚亲爱之。及即位，为散骑侍郎，累迁城门校尉，加散骑常侍，转武卫将军，宠待有殊。帝寝疾，乃引爽入卧内，拜大将军，假节钺，都督中外诸军事，录尚书事，与太尉司马宣王井受遗诏辅少主。明帝崩，齐王即位，加爽侍中，改封武安侯，邑万二千户。赐剑履上殿，入朝不趋，赞拜不名。丁谧画策，使爽白天子，发诏转宣王为太傅，外以名号尊之，内欲令尚书奏事。先来由己，得制其轻重也。爽帝羲为中领军，训武卫将军，彦散骑常侍侍讲，其余诸弟，皆以列侯侍从，出入禁闼，贵宠莫盛焉。南阳何晏、邓扬、李胜，沛园丁谧、东平毕轨咸有声名，进趣于时，明帝以其浮华，皆抑黜之。及爽秉政，乃复进叙，任为腹心。扬等欲令爽立威名于天下，劝使伐蜀，爽从其言。宣王止之不能禁。正始五年，爽乃西至长安，大发率六七万人，从骆谷入。是时，关中及氐、羌转输不能供，牛马骡驴多死，民夷号泣道路。入谷行数百里，贼因山为固，兵不得进。爽参军杨伟为爽陈形势，宜急还，不然将败。扬与伟争于爽前，伟曰：“扬、胜将败国家事，可斩也。”爽不悦，乃引军还。
初，爽以宣王年德并高，恒父事之，不敢专行。及晏等进用，咸共推戴，说爽以权重不宜委之于人。乃以晏、扬、谧为尚书，晏典选举，轨司隶校尉，胜河南尹，诸事希复由宣王。宣王遂称疾避爽。晏等专政，共分割洛阳、野王典农部桑田数百顷，及坏汤沐地以为产业，承势窃取官物，因缘求欲州郡。有司望风，莫敢忤旨。晏等与廷尉卢毓素有不平。因毓吏微过，深文致毓法，使主者先收毓印绶，然后奏闻。其作威如此。爽饮食车服，拟于乘舆。尚方珍玩，充牣其家。妻妾盈后庭，又私取先帝才人七八人，及将吏、师工、鼓吹、良家子女三十三人，皆以为伎乐。诈作诏书，发才人五十七人送邺台，使先帝倢伃教习为伎。擅取太乐乐器、武库禁兵。作窟室，绮疏四周，数与晏等会其中，纵酒作乐。羲深以为大忧，数谏止之。又着书三篇，陈骄淫盈溢之致祸败，辞旨甚切，不敢斥爽，托戒诸弟以示爽。爽知其为己发也，甚不悦，羲或时以谏喻不纳，涕泣而起。宣王密为之备。九年冬，李胜出为荆州刺史，往诣宣王。宣王称疾困笃，示以羸形。胜不能觉，谓之信然。
十年正月，车驾朝高平陵，爽兄弟皆从。宣王部勒兵马，先据武库，遂出屯洛水浮桥。奏爽曰：“臣昔从辽东还，先帝诏陛下、秦王及臣升御床，把臣臂，深以后事为念。
臣言‘二祖亦属臣以后事，（为念）此自陛下所见，无所忧苦。万一有不如意，臣当以死奉明诏’。黄门令董箕等，才人侍疾者，皆所闻知。今大将军爽背弃顾命，败乱国典，内则僭拟，外专威权；破坏诸营，尽据禁兵，群官要职，皆置所亲；殿中宿卫，历世旧人皆复斥出，欲置新人以树私计；根据盘互，纵恣日甚。外既如此，又以黄门张当为都监，专共交关，看察至尊，候伺神器，离间二宫，伤害骨肉。天下汹汹，人怀危惧，陛下但为寄坐，岂得久安！此非先帝诏陛下及臣升御床之本意也。臣虽朽迈，敢忘往言？昔赵高极意，奏氏以灭；吕、霍早断，汉祚永世。此乃陛下之大鉴，臣受命之时也。太尉臣济、尚书令臣孚等，皆以爽为有无君之心，兄弟不宜典兵宿卫，奏永宁宫。皇太后令敕臣如奏施行。臣辄敕主者及黄门令罢爽、羲、训吏兵，以侯就第，不得逗留以稽车驾；敢有稽留，便以军法从事。臣辄力疾将兵屯洛水浮桥，伺察非常。“
爽得宣王奏事，不通，迫窘不知所为。大司农沛国桓范闻兵起，不应太后召，矫诏开平昌门，拔取剑戟，略将门候，南奔爽。宣王知，曰：“范画策，爽必不能用范计。”
范说爽使车驾幸许昌，招外兵。爽兄弟犹豫未决，范重谓羲曰：“当今白，卿门户求贫贱复可得乎？且匹夫持质一人，尚欲望活。今卿与天子相随，令于天下，谁敢不应者？”
羲犹不能纳。侍中许允、尚书陈泰说爽，使早自归罪。爽于是遣允、泰诣宣王，归罪请死，乃通宣王奏事。遂免爽兄弟，以侯还第。
初，张当私以所择才人张、何等与爽。疑其有奸，收当治罪。当陈爽与晏等阴谋反逆，并先习兵，须三月中欲发，于是收晏等下狱。会公卿朝臣廷议，以为“《春秋》之义，‘君亲无将，将而必诛’。爽以支属，世蒙殊宠，亲受先帝握手遗诏，托以天下，而包藏祸心，蔑弃顾命。乃与晏、扬及当等谋图神器，范党同罪人，皆为大逆不道。”
于是收爽、羲、训、晏、扬、谧、轨、胜、范、当等，皆伏诛，夷三族。嘉平中，绍功臣世，封真族孙熙为新昌亭侯，邑三百户，以奉真后。
晏，何进孙也。母尹氏，为太祖夫人。晏长于宫省，又尚公主，少以才秀知名。好《老》、《庄》言，作《道德论》及诸文赋着述凡数十篇。
夏侯尚字伯仁，渊从子也。文帝与之亲友。太祖定冀州，尚为军司马，将骑从征伐，后为五官将文学。魏国初建，迁黄门侍郎。代郡胡叛，遣鄢陵侯彰征讨之，以尚参彰军事，定代地，还。太祖崩于洛阳。尚持节，奉梓宫还邺。并录前功，封平陵亭侯，拜散骑常侍，迁中领军。文帝践阼，更封平陵乡侯，迁征南将军，领荆州刺史，假节，都督南方诸军事。尚奏：“刘备别军在上庸，山道险难，彼不我虞，若以奇兵潜行，出其不意，则独克之势也。”遂勒诸军击破上庸，平三郡九县，迁征南大将军。孙权虽称藩，尚益修攻讨之备，权后果有贰心。黄初三年，车驾幸宛，使尚率诸军与曹真共围江陵。
权将诸葛瑾与尚军对江，瑾渡入江中渚，而分水军于江中。尚夜多持油船，将步骑万余人，于下流潜渡，攻瑾诸军，夹江烧其舟船，水陆并攻，破之。城末拔，会大疫，诏敕尚引诸军还。益封六百户，并前干九百户，假钺，进为牧。荆州残荒，外接蛮夷。而与吴阻汉水为境，旧民多居江南。尚自上庸通道，西行七百余里，山民蛮夷多服从者。五六年间，降附数千家。五年，徙封昌陵乡侯。尚有爱妾嬖幸，宠夺适室。适室，曹氏女也，故文帝遣人绞杀之。尚悲感，发病恍惚，既葬埋妾，不胜思见，复出视之。文帝闻而恚之曰：“杜袭之轻薄尚，良有以也。”然以旧臣，恩宠不衰。六年，尚疾笃，还京都，帝数临幸，执手涕泣。尚薨，谥曰悼侯，子玄嗣。又分尚户三百，赐尚弟子奉爵关内侯。
玄字太初。少知名，弱冠为散骑、黄门侍郎。尝进见，与皇后弟毛曾并坐。玄耻之。
不悦形之于色。明帝恨之，左迁为羽林监。正始初，曹爽辅政。玄，爽之姑子也。累迁散骑常侍、中护军。
太傅司马宣王问以时事，玄议以为：“夫官才用人，国之柄也；故铨衡专于台阁，上之分也；孝行存乎闾巷，优劣任之乡人，下之叙也。夫欲清教审选，在明其分叙，不使相涉而已。何者？上过其分，则恐所由之不本，而干势驰鹜之路开；下逾其叙，则恐天爵之外通，而机权之门多矣。夫天爵下通，是庶人议柄也；机权多门，是纷乱之原也。
自州郡中正品度官才之来，有年载矣，缅缅纷纷，未闻整齐，岂非分叙参错，各失其要之所由哉！若令中正但考行伦辈，伦辈当行均，斯可官矣。何者？夫孝行着于家门，岂不忠恪于在官乎？仁怨称于九族，岂不达于为政乎？义断行于乡党，岂不堪于事任乎？三者之类，取于中正，虽不处其官名，斯任官可知矣。行有大小，比有高下，则所任之流，亦涣然明别矣。奚必使中正干铨衡之机于下，而执机柄者有所委仗于上，上下交侵，以生纷错哉？且台阁临下，考功校否，众职之属，各有官长，旦夕相考，莫究于此；闾阎之议，以意裁处，而使匠宰失位，众人驱骇，欲风俗清静，其可得乎？天台县远，众所绝意。所得至者，更在侧近，孰不修饰以要所求？所求有路，则修已家门者，已不如自达于乡党矣。自达乡党者，已不如自求之于州邦矣。苟开之有路，而患其饰真离本，虽复严责中正，督以刑罚，犹无益也。岂若使备帅其分，官长则各以其属能否献之台阁，台阁则据官长能否之第，参以乡闾德行之次，拟其伦比，勿使偏颇。中正则唯考其行迹，别其高下，审定辈类，勿使升降。台阁总之，如其所简或有参错，则其责负自在有司。
官长所第，中正辈拟，比随次率而用之，如其不称，责负在外。然则内外相参，得失有所，互相形检，孰能相饰？斯则人心定而事理得，庶可以静风俗而审官才矣。“又以为：”古之建官，所以济育群生，统理民物也，故为之君长以司牧之。司牧之主，欲一而专，一则宫任定而上下安，专则职业修而事不烦。夫事简业修，上下相安而不治者，末之有也。先王建万国，虽其详未可得而究，然分疆画界，各守土境，则非重累羁绊之体也。
下考殷、周五等之叙，徒有小大贵贱之差，亦无君官臣民而有二统互相牵制者也。夫官统不一，则职业不修；职业不修，则事何得而简？事之不简，则民何得而静？民之不静，则邪恶并兴，而奸伪滋长矣。先王达其如此，故专其职司而一其统业。始自秦世，不师圣道，私以御职，奸以待下；惧宰官之不修，立监牧以董之，畏督监之容曲，设司察以纠之；宰牧相累，监察相司，人怀异心，上下殊务。汉承其绪，莫能匡改。魏室之隆，日不暇及，五等之典，虽难卒复，可粗立仪准以一治制。今之长吏，皆君吏民，横重以郡守，累以刺史。若郡所摄，唯在大较，则与州同，无为再重。宜省郡守，但任刺史；刺史职存则监察不废，郡吏万数，还亲农业，以省烦费，丰财殖谷，一也。大县之才，皆堪郡守，是非之讼，每生意异，顺从则安，直己则争。夫和羹之美，在于合异，上下之益，在能相济，顺从乃安，此琴瑟一声也，荡而除之，则官省事简，二也。又干郡之吏，职监诸县，营护党亲，乡邑旧故，如有不副，而因公掣顿，民之困弊，咎生于此，若皆并合，则乱原自塞，三也。今承衰弊，民人雕落，贤才鲜少，任事者寡，郡县良吏，往往非一，郡受县成，其剧在下，而吏之上选，郡当先足，此为亲民之吏，专得底下，吏者民命，而常顽鄙，今如并之，吏多选清良者造职，大化宣流，民物获宁，四也。制使万户之县，名之郡守，五千以上，名之都尉，千户以下，令长如故，自长以上，考课迁用，转以能升，所牧亦增，此进才效功之叙也，若经制一定，则官才有次，治功齐名，五也。若省郡守，县皆径达，事不拥隔，官无留滞，三代之风，虽未可必，简一之化，庶几可致，便民省费，在于此矣。“又以为：”文质之更用，犹四时之迭兴也，王者体天理物，必因弊而济通之，时弥质则文之以礼，时泰侈则救之以质。今承百王之末，秦汉余流，世俗弥文，宜大改之易民望。今科制自公、列侯以下，位从大将军以上，皆得服绫锦、罗绮、纨素、金银饰镂之物，自是以下，杂采之服，通于贱人，虽上下等级，各示有差，然朝臣之制，已得侔至尊矣，玄黄之采，已得通于下矣。欲使市不鬻华丽之色，商不通难得之货，工不作雕刻之物，不可得也。是故宜大理其本，准度古法，文质之宜，取其中则，以为礼度。车舆服章，皆从质朴，禁除末俗华丽之事，使干朝之家，有位之室，不复有锦绮之饰，无兼采之服，纤巧之物，自上以下，至于朴素之差，示有等级而已，勿使过一二之觉。若夫功德之赐，上恩所特加，皆表之有司，然后服用之。
夫上之化下，犹风之靡草。朴素之教兴于本朝，则弥侈之心自消于下矣。“
宣王报书曰：“审官择人，除重官，改服制，皆大善。礼乡闾本行，朝廷考事，大指如所示。而中间一相承习，卒不能改。秦时无刺史，但有郡守长吏。汉家虽有刺史，奉六条而已，故刺史称传车，其吏言从事，居无常治，吏不成臣，其后转更为官司耳。
昔贾谊亦患服制，汉文虽身服弋绨，犹不能使上下如意。恐此三事，当待贤能然后了耳。“玄又书曰：”汉文虽身衣弋绨，而不革正法度，内外有僭拟之服，宠臣受无限之赐，由是观之，似指立在身之名，非笃齐治制之意也。今公侯命世作宰，追踪上古，将隆至治，抑末正本，若制定于上，则化行于众矣。夫当宜改之时，留殷勤之心，令发之日，下之应也犹响寻声耳，犹垂谦谦，曰‘待贤能’，此伊周不正殷姬之典也。窃末喻焉。“
顷之，为征西将军，假节都督雍、凉州诸军事。与曹爽共兴骆谷之役，时人讥之。
爽诛，征玄为大鸿胪，数年徙太常。玄以爽抑绌，内不得意。中书令李丰虽宿为大将军司马景王所亲待，然私心在玄，遂结皇后父光禄大夫张缉，谋欲以玄辅政。丰既内握权柄，子尚公主，又与缉俱冯翊人，故缉信之。丰阴令弟兖州刺史翼求入朝，欲使将兵入，并力起。会翼求朝，不听。嘉平六年二月，当拜贵人，丰等欲因御临轩，诸门有陛兵，诛大将军，以玄代之，以缉为骠骑将军。丰密语黄门监苏铄、永宁署令乐敦、冗从仆射刘贤等曰：“卿诸人居内，多有不法，大将军严毅，累以为言，张当可以为诫。”铄等皆许以从命。大将军微闻其谋，请丰相见，丰不知而往，即杀之。事下有司，收玄、缉、铄、敦、贤等送廷尉。廷尉钟毓奏：“丰等谋迫胁至尊，擅诛冢宰，大逆无道，请论如法。”于是会公卿朝臣廷尉仪，咸以为“丰等各受殊宠，典综机密，缉承外戚椒房之尊。
玄备世臣，并居列位，而包藏祸心，构图凶逆，交关阉竖，授以奸计，畏惮天威，不敢显谋，乃欲要君胁上，肆其诈虐，谋诛良辅，擅相建立，将以倾覆京室，颠危社稷。毓所正皆如科律，报毓施行。“诏书：”齐长公主，先帝遗爱，原其三子死命。“于是丰、玄、缉、敦、贤等皆夷三族，其余亲属徙乐浪郡。玄格量弘济，临斩东市，颜色不变，举动自若。时年四十六。正元中，绍功臣世，封尚从孙本为昌陵亭侯，邑三百户，以奉尚后。
初，中领军高阳许允与丰、玄亲善。先是有诈作尺一诏书，以玄为大将军，允为太尉，共录尚书事。有何人天未明乘马以诏版付允门吏，曰“有诏”因便驰走。允即投书烧之。不以呈司马景王。后丰等事觉，徒允为镇北将军，假节，督河北诸军事。未发，以放散官物，收付廷尉，徙乐浪，道死。
渭河王经亦与允俱称冀州名士。甘露中为尚书，坐高贵乡公事诛。始经为郡守。经母谓经曰：“汝田家子。今仕至二千石，物太过不祥，可以止矣。”经不能从，历二州刺史，司隶校尉，终以致败。允友人同郡崔赞，亦尝以处世太盛戒允云。
评曰：夏侯、曹氏，世为婚姻。故惇、渊、仁、洪、休、尚、真等并以亲旧肺腑，贵重于时，左右勋业，咸有效劳。爽德薄位尊，沈溺盈溢，此固《伏易》所着，道家所忌也。玄以规格局度，世称其名，然与曹爽中外缱绻；荣位如斯，曾未闻匡弼其非，援致良才。举兹以论，焉能免之。', '', '', '', NULL, '', 'indent', 1540488717, '5bd189df44d904005e8efaf0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640197, '将赴成都草堂途中有作先寄严郑公五首（其四）', NULL, 1, 1416, 0, 1, '杜甫', NULL, 10035, '57b91627165abd0054c07fc6', '唐', 'shi', '诗', '', '', '常苦沙崩损药栏，也从江槛落风湍。
新松恨不高千尺，恶竹应须斩万竿。
生理只凭黄阁老，衰颜欲付紫金丹。
三年奔走空皮骨，信有人间行路难。', '', '', '我恨不得让新松长到千尺高，而对于恶竹，则必须全部加以芟除。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92ae03048e64fbd91407", "shortContent": "因徐知道据成都叛乱，杜甫曾一度离开成都草堂，避难于梓州（治今四川三台）、阆州（治今四川阆中）等地。广德二年（764）正月，杜甫携家由梓州赴阆州，准备出陕谋生。二月，闻严武再为成都尹兼剑南节度使，同时，严武也来信相邀，诗人于是决定重返成都。于阆州还成都途中作诗五首，此为其中第四首。诗题中的“严郑公”，即严武，广德元年严武被封为郑国公。\n首四句是设想回成都后整理草堂之事，但却给人以启迪世事的联想：“常...", "authors": ["傅经顺"], "pressName": "上海辞书出版社"}, {"bookId": "645fb3be30675327e174affd", "bookTitle": "杜甫诗歌鉴赏辞典", "articleId": "6466061445e4710056ca07a7", "shortContent": "因徐知道据成都叛乱，杜甫曾一度离开成都草堂，避难于梓州（治今四川三台）、阆州（治今四川阆中）等地。广德二年（764）正月，杜甫携家由梓州赴阆州，准备出陕谋生。二月，闻严武再为成都尹兼剑南节度使，同时，严武也来信相邀，诗人于是决定重返成都。于阆州还成都途中作诗五首，此为其中第四首。诗题中的“严郑公”，即严武，广德元年严武被封为郑国公。\n\n首四句是设想回成都后整理草堂之事，但却给人以启迪世事的联想：“...", "authors": ["傅经顺"], "pressName": "上海辞书出版社"}]', '', 'center', 1540496171, '5bd1aac7ee920a0068db1c3f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640199, '初去郡', NULL, 0, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E5%88%9D%E5%8E%BB%E9%83%A1/1003728?fr=aladdin', '', '彭薛裁知耻，贡公未遗荣。
或可优贪竞，岂足称达生。
伊余秉微尚，拙讷谢浮名。
庐园当栖岩，卑位代躬耕。
顾己虽自许，心迹犹未并。
无庸妨周任，有疾像长卿。
毕娶类尚子，薄游似邴生。
恭承古人意，促装返柴荆。
牵丝及元兴，解龟在景平。
负心二十载，于今废将迎。
理棹遄还期，遵渚骛修坰。
溯溪终水涉，登岭始山行。
野旷沙岸净，天高秋月明。
憩石挹飞泉，攀林搴落英。
战胜臞者肥，止监流归停。
即是羲唐化，获我击壤情。', '《初去郡》是南朝宋诗人谢灵运所作的一首五言诗。诗作前部分叙写古人事迹，以之为衬托表明自己坚决辞职隐居的意志与行为。诗作后部分写自己返家行程中的景象及感想。诗中抒发了去官还家、获得解脱的愉悦心情。诗中写景不多，却极为清丽动人。', '彭：彭宣。汉代研究《周易》学者，官至大司空。王莽时上书求归乡里。薛：薛广德，汉代“鲁诗”专家，字长卿，官至御史大夫，后辞官归里，不再出仕。朝廷赐以安车驷马，广德悬挂其事以示荣。班固评价此二人“近于知耻”。裁：通“才”，仅只。知耻：谓有羞耻之心。
贡公：贡禹，汉人，字少翁，为光禄大夫，后辞官不许，又为御史大夫。与王阳友善，见其被用而喜。未遗荣：没有忘记荣华富贵。
贪竞：贪恋官位。
达生：通达人生，为道家对生命的认识理论。
伊：语助。秉：执持。微尚：隐遁的志趣。尚：志向。
拙讷（zhuōnè）：笨拙又口不善言；自谦之词，指自己不善作官。谢：弃绝。浮名：指功名。
栖岩：指古代巢居穴处，这里指隐居。
卑位：谦指所袭康乐侯。
顾己：回顾自己。自许：自赞。
心：心愿，指隐居。迹：行迹，指做官。并：合一，具备。
无庸：无所作为。周任：春秋时周大夫，言行为孔子所称。
长卿：汉代司马相如，字长卿，常托病不朝。
毕娶，办完婚娶之事。尚子：尚长，东汉隐士，为儿女办完婚嫁，即隐迹山林。
薄游：指做小官。邴生：西汉邴曼容，养志自修，不愿作六百石以上的官，如超过，便自免退居。
促装：收拾行装。柴荆：柴草竹木编织的门或屋舍，代指故居。
牵丝：指初仕。《礼记·缁衣》有“王言如丝”。元兴：东晋安帝年号（402-404年）。灵运初仕为晋琅玡王大司马参军，时在晋安帝义熙元年（405年）。是年正月戊戌（十六日）方才改元，而上一年的年号为元兴，故云“及元兴”。
解龟：即去官。龟：龟纽。宫印印鼻刻有龟形，下有穿丝条的孔眼。景平：宋少帝年号（423-424年）。
负心：违背心愿，指作官。
废将迎：指省去官场送往迎来的繁琐礼节。将迎：官场上的应酬。
理棹（zhào）：准备船只。遄（chuán）：急忙。
遵渚：沿着江中小洲。骛（wù）：疾驰而过。修垌（jiōng）：绵长的原野。
溯溪：沿溪逆流而上。终水涉：结束水上旅行。
挹（yì）：双手合捧取水。
搴（qiān）：拉动、拾取。落英：落花。
臞（qú）：瘦。清瘦。
鉴：镜子，此作动词，犹临照。止：止水。流归停：指流水终归静止。
羲（xī）：伏羲氏。唐：唐尧。
击壤：上古时的一种游戏。击壤情：即风俗淳朴时代人们的思想感情。', '彭薛告老仅仅算知耻，贡公贺友确是好虚荣。
此辈稍胜贪求名利徒，岂够保身全生受称扬。
唯我怀抱出尘隐逸志，才疏口讷鄙弃虚浮名。
田园当作巢栖穴居处，爵位可代亲自去耕种。
久想退隐虽说自赞许，愿望行迹尚未成一统。
仿效周任无功不求升，取法长卿闲居说多病。
儿女完婚离家像尚子，谢绝高位知足似邴生。
恭谨承继古人清高意，快备行装尽速返故乡。
回想初仕正是元兴问，此次辞官适逢在景平。
违背心愿居官二十载，从今清静不为俗事忙。
归期将近登船心如箭，沿岸船飞大地退后方。
由江入溪水路至尽头，离船登岭跨步山路行。
原野空旷沙岸一片静，天空高远秋月分外明。
石上休息尽情饮流泉，攀附林木随意餐落英。
归隐心静体瘦已变肥，临水照容终得清流静。
就此超世作个羲唐人，我学击壤重获真朴情。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb2911759740c9bd662", "shortContent": "此诗作于宋景平元年（423）秋。上一年七月，谢灵运出为永嘉太守，至此称病离职，刚满一年。诗中抒发了去官还家、获得解脱的愉悦心情。\n开头十句自述隐居丘园之志。先对几位古人加以评价：西汉的彭宣、薛广德、贡禹虽有高名，但只能说是优于贪婪奔竞之徒，还说不上是懂得养生缮性。彭宣，哀帝时官至御史大夫、大司空，封长平侯。哀帝卒，外戚王莽专权，他便告老回乡。薛广德，元帝时为御史大夫，因遭遇荒年，人民流亡，自己觉得...", "authors": ["杨", "明"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "6470a55c7f27182da386e59a", "shortContent": "此诗作于宋景平元年(423)秋。上一年七月，谢灵运出为永嘉太守， 至此称病离职，刚满一年。诗中抒发了去官还家、获得解脱的愉悦心情。\n\n开头十句自述隐居丘园之志。先对几位古人加以评价:西汉的彭 宣、薛广德、贡禹虽有高名，但只能说是优于贪婪奔竞之徒，还说不上是懂 得养生缮性。彭宣，哀帝时官至御史大夫、大司空，封长平侯。哀帝卒，外 戚王莽专权，他便告老回乡。薛广德，元帝时为御史大夫，因遭遇荒年，人 民流...", "authors": ["杨明"], "pressName": "上海辞书出版社"}]', '上海古籍出版社编辑室主任曹明纲：前人评谢诗，有“把定一题、一人、一事、一物，于其上求形模，求比拟，求词采，求故实，如钝斧子劈栎柞，皮屑纷霏，何尝动得一丝纹理？以意为主，势次之，势者，意中之神理也，唯谢康乐为能。取势宛转屈伸，以求尽其意，意已尽则止，殆无剩语”之说，此诗即是显例。', 'center', 1553655377, '5bd281a4ac502e0061bf1af8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640200, '七里濑', NULL, 2, 135, 2, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', '', '', '羁心积秋晨，晨积展游眺。
孤客伤逝湍，徒旅苦奔峭。
石浅水潺湲，日落山照曜。
荒林纷沃若，哀禽相叫啸。
遭物悼迁斥，存期得要妙。
既秉上皇心，岂屑末代诮。
目睹严子濑，想属任公钓。
谁谓古今殊，异代可同调。', '', '', '', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb02cee9a0c24eda8b5", "shortContent": "宋永初三年（442），谢灵运自京都建康赴永嘉太守任，途经富春江畔的七里濑（水流沙上为“濑”），乃作此诗。七里濑亦名七里滩，在今浙江桐庐县严陵山迤西。两岸高山耸立，水急驶如箭。旧时有谚云：“有风七里，无风七十里。”指舟行急湍中进度极难掌握，唯视风之大小来决定迟速。\n此诗一韵到底，凡十六句，每四句为一节。诗意借观赏沿江景物以寄托作者落落寡合的“羁心”，诗中虽作旷达语，却充满了不合时宜的牢骚。这是谢灵运...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}]', '', 'center', 1553681423, '5bd281cdee920a0068e38a72', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640201, '晚出西射堂', NULL, 0, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E6%99%9A%E5%87%BA%E8%A5%BF%E5%B0%84%E5%A0%82%E8%AF%97/4451156?fr=aladdin', '', '步出西城门，遥望城西岑。
连鄣叠巘崿，青翠杳深沉。
晓霜枫叶丹，夕曛岚气阴。
节往戚不浅，感来念已深。
羁雌恋旧侣，迷鸟怀故林。
含情尚劳爱，如何离赏心。
抚镜华缁鬓，揽带缓促衿。
安排徒空言，幽独赖鸣琴。', '', '西射堂：在永嘉郡（今浙江温州市）城内。所谓射堂，是试士习射的所在。
西城门：《艺文类聚》卷二八、宋本《三谢诗》、五臣本、《太平寰宇记》卷九九、“百三家集”作“西掖门”。
西岑（cén）：即西山。又名瓯浦山，金丹山。连峰叠蜮，青葱秀丽，为温州登览胜处。
连障（zhàng）：连绵不断的山。
巘崿（yǎnè）：谓山崖重重叠叠。巘，山形似甑者。崿，山崖。
青翠：指青山。
杳（yǎo）深沉：形容山色幽暗朦胧。
夕曛（xūn）：黄昏时的余晖。
岚（lán）气：山中的雾气。
阴：昏暗。
节往：谓时序推迁。
戚（qī）不浅：谓忧愁深。
感：寿考堂藏板、信述堂重刊本“百兰家集”作“恨”，不从。
羁雌（jīcí）：指失群的雌禽。
含情：指鸟含感情。
劳爱：忧愁、热爱。
赏心：以心相赏，此指知心朋友。
华缁（zī）鬓（bìn）：谓发髻由黑变花白。华，头发变白。缁，黑色。
缓促衿（jīn）：衣服宽松，喻身体消瘦。缓，宽缓。促，紧。
安排：安于自然的推移，指听任大自然的变化。语出《庄子》。《庄子·大宗师》：“安排而去化，乃入于廖天一。”
空言：空话。', '苍茫暮色中，独自步出西门，远眺连峰叠巘，青葱秀丽的山景色。
往日里青翠的崇山都被广漠无边的暮色笼罩着，变得深不可测。
曾经慰目的染霜红枫，已不复见，唯有斜阳无言，在厚重阴沉的岚气中，恹恹降沉。
随着时间的推迁引起了无限的愁绪，感到思念越来越深。
被拘系的鸟儿依恋昔日的伴侣，迷途的鸟儿思念住惯了的树林。
鸟的感情尚且如此忧愁热爱，我又怎么离得开知心朋友。
从镜子中看到发髻由黑变花白，人瘦则衣带显得宽松。
听从大自然的安排是空话，唯有靠抚弄琴弦来安慰自己的一颗孤寂苦闷之心。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb05914587d02f599da", "shortContent": "西射堂，在永嘉西南二里，所谓射堂，是试士习射的所在，由诗题及诗中所状景色推之，本诗当作于永初三年（422）灵远外放永嘉当年的深秋。\n傍晚，诗人漫步出西城门，大抵谪宦羁旅之人最怕黄昏长夜，因为白日的公务，多少还能分散心事，而公余闲暇，天色如磐，这愁绪又何以消遣？这种感觉，在常人都如此，更何况诗客敏感的心灵？所以当灵运举目远望郊坰的西山时，永嘉的青山绿水，已都无秀色可言，触目尽是惹愁兴叹的资料。崇山如...", "authors": ["赵昌平"], "pressName": "上海辞书出版社"}]', '', 'center', 1553684290, '5bd2820aee920a0068e38eef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640202, '登江中孤屿', NULL, 4, 135, 2, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E7%99%BB%E6%B1%9F%E4%B8%AD%E5%AD%A4%E5%B1%BF/1108193?fr=aladdin', '', '江南倦历览，江北旷周旋。
怀新道转迥，寻异景不延。
乱流趋正绝，孤屿媚中川。
云日相辉映，空水共澄鲜。
表灵物莫赏，蕴真谁为传。
想像昆山姿，缅邈区中缘。
始信安期术，得尽养生年。', '《登江中孤屿》是南朝宋山水诗人谢灵运所作的一首五言诗。这是一首写景诗，诗人先写因倦游而觅新奇之境，然后写登江中孤屿时所看到的风景，以及因此而产生的对于神仙养生之境的幻想，抒发了作者对朝中的厌倦与渴望遁世处幽的心境。此诗叙事、写景、说理，层次分明，过渡自然。', '江中：指永嘉江，在浙江东南境，又称瓯江、温江、蜃江、永宁江。孤屿，即孤屿山，在今温州市附近永嘉江中。
历览：遍览，游遍了。
旷周旋：久不游览。旷，荒废，耽搁。周旋，应酬，打交道，这里指前去游赏。
迥：迂回。
景：日光，指时间。延：长。
乱流：从江中截流横渡。趋：疾行。
媚：优美悦人。中川：江水中间。
空水：天空和江水。
表灵：指孤屿山极其神奇的景象。表，明显。灵，灵秀、神奇。物：指世人。
蕴真：蕴藏的仙人。真，真人、神仙。
昆山姿：指神仙的姿容。昆山，昆仑山的简称，是古代传说中西王母的住处。
缅（miǎn）邈（miǎo）：悠远。区中缘：人世间的相互关系。
安期术：安期生的长生之术。安期，即安期生，古代传说中的神仙，传说他是琅琊阜乡人，因得长生不老之术而活过了一千岁。', '倦于遍览江南美景，江北风光久未观看。
寻求新景道路遥远，探访奇观时光不延。
穿越激流横渡前行，孤岛秀美大河中间。
白云红日相互辉映，水天一色澄碧鲜妍。
呈现灵气无人欣赏，藏有真趣谁为传言？
遥想昆山仙人英姿，顿觉世间尘缘邈远。
始信安期养生之术，得以享尽养生天年。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb1d635634aee3ea591", "shortContent": "此诗当作于景平元年（423），灵运时在永嘉（治所在今浙江温州）太守任上。题中的“江”指永嘉江。“孤屿”在温州南四十里，为永嘉江中渚，长三百丈，阔七十步，岛屿上有二峰。（见张云璈《选学胶言》引《寰宇记》）\n全诗分三层。首四句是第一层：写诗人欲游江北探寻新异胜境的急切心情。谢灵运于头年因受排挤而出任永嘉太守，“既不得志，遂肆意游遨，遍历诸县，动逾旬朔。”（《宋书》本传）区区永嘉诸景，不到一年便已“历览...", "authors": ["熊", "笃"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "647325c482772d45942c4c86", "shortContent": "此诗作于景平元年（４２３），作者当时在永嘉（治所在今浙江温州）太守任上。题中的“江”指永嘉江。“孤屿”在温州南四十里，为永嘉江中渚，长三百丈，阔七十步，岛屿上有二峰（见张云璈《选学胶言》引《寰宇记》）。\n全诗分三层。首四句是第一层：写诗人欲游江北探寻新异胜境的急切心情。谢灵运于头年因受排挤而出任永嘉太守，“既不得志，遂肆意游遨，遍历诸县，动逾旬朔”（《宋书》本传）。区区永嘉诸景，不到一年便已“历览...", "authors": ["熊笃"], "pressName": "上海辞书出版社"}]', '明代钟惺：“怀新道转回”：只是舟行诣妙。“寻异景不延”：此景亦真，惜说得不畅。（《古诗归》）
明代谭元春：灵运是古今第一游山人，所以游具游情丝毫可通之今日……（《古诗归》）
明代陆时雍：“乱流趋正绝（一作孤屿）”，此景人所不道，然言之自佳。“孤屿媚中川”，此山水赏心语，得趣既饶，故赋景自别。（《古诗镜》）
明代胡应麟：风神华畅，似得天授，而骈丽已极。又云：康乐清而丽。（《诗薮》）
明代孙矿：意不甚深，惟以生涩工。得在此，失亦在此。（《文选集评》）
清代王夫之：入想出句，一如皎月之脱于重云。（《船山古诗评选》）
清代陈祚明：谢康乐诗如湛湛江流，源出万山之中，穿岩激石，瀑挂湍回，千转百折，喷为洪涛。及其浩漾澄湖，树影山光，云容草色，涵彻洞深，盖缘源远流长，时或潴为小涧，亦复摇曳澄萦，波荡不定。又日：于未登孤屿前，先写一层，搜奇选胜，意见笃好山水若此，情倍深，旨倍曲，发端构想，高人几许。作诗能用意者，难在得发端一语，既得起句，则循绪而下，滔滔不穷，自然章法迢递，通体灵警，无论古体、近体皆然。又云：“乱流”二句佳，绝流而渡，正尔时，不意复有好景，忽得孤屿悦目赏心，出于望外，觉此境倍佳耳。“云日”二句，十字足尽孤屿妙景，亦写景写虚法。（《采菽堂古诗选》）
清代何焯：放眼江天，脱屣遗世，兴象殆欲参灵。“乱流趋正绝”二句，妙在上句一顿。舟行兀兀，忽推蓬远眺，心目俱旷，叙写生动。“表灵物莫赏”二句，景物灵旷，尚莫能赏，况埋照而蕴真者乎。（《义门读书记》）
清代沈德潜：“怀新道转回”，谓贪寻新境，忘其道之远也。“寻异景不延”，谓往前探奇，当前妙景，不能少迁延也，深于寻幽者知之。十字字字耐人咀味。又云：“乱流”二句，谓截流而渡，忽得孤屿。余尝游金、焦，诵此二句，愈觉其妙。（《古诗源》）
清代邵长蘅：孤屿便妙，“新”、“异”二字，为孤屿写境灵，真便写性情矣。又云：大谢诗无论才高，其所历之处皆是妙境，焉得不触发？（《文选集评》）', 'center', 1553684394, '5bd2824317d0090062e49e76', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640203, '入彭蠡湖口', NULL, 0, 135, 3, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E5%85%A5%E5%BD%AD%E8%A0%A1%E6%B9%96%E5%8F%A3/8650067?fr=aladdin', '', '客游倦水宿，风潮难具论。
洲岛骤回合，圻岸屡崩奔。
乘月听哀狖，浥露馥芳荪。
春晚绿野秀，岩高白云屯。
千念集日夜，万感盈朝昏。
攀崖照石镜，牵叶入松门。
三江事多往，九派理空存。
灵物吝珍怪，异人秘精魂。
金膏灭明光，水碧缀流温。
徒作千里曲，弦绝念弥敦。', '《入彭蠡湖口》是晋宋之际诗人谢灵运创作的一首山水诗。此诗作于前往临川途中由长江入彭蠡湖口时。诗中细致地描写了入彭蠡湖口的经过与所见的景物。面对彭蠡湖，诗人看到灵异不显，异人隐迹，暗喻贤人隐世之理，故最后发出“弦绝念弥敦”之叹。全诗意境疏朗高远，笔致趋于跳荡，用典不露痕迹，情景理融为一体，显示出山水诗进一步脱略玄言诗影响的历史进程。', '彭蠡湖：即今江西鄱阳湖。彭蠡湖口：即今鄱阳湖口，长江与鄱阳湖在九江附近与相接。
倦：厌倦。水宿：栖住于水中的船上。此句意谓厌倦了水上长途旅行。
具论：详细述说。
骤：急疾。回合：聚合；汇合。此言风浪拍打在洲岛上。圻（qí）岸：曲岸。崩奔：水流冲激堤岸而奔涌。
狖（yòu）：长尾猿。
浥（yì）：湿。馥（fù）：香气浓郁。芳荪：香草名。此句说露水沾在芳荪的叶子上，散发出浓郁的香气。
屯：聚集。
千念二句：各种感慨日夜缠绕在心头。
石镜、松门：山名，二山都近鄱阳湖口。李善《文选注》引张僧鉴《浔阳记》曰：“石镜山，东有一圆石，悬崖明净，照人见形。”又引顾野王《舆地志》曰：“自入湖三百三十里，穷于松门。东西四十里，青松徧于两岸。”
三江：《尚书·禹贡》：“三江既入。”郑玄注：“三江分于彭蠡，为三孔，东入海。”
九派：浔阳的别称。即今江西九江。上二句说古代关于三江、九派说法已成往事，其中的玄理也无从知晓。
灵物：珍奇神异之物。吝珍怪：惜其珍奇怪异之状。
秘精魂：隐藏其精神魂魄。二句说江湖中本来有很多神异之物，但都不显现出来。
金膏：道教传说中的仙药。灭明光：韬光而不显现。
水碧：玉的一种，又称碧玉。《山海经》：“耿山多水碧。”辍：停止。流温：指水玉温润。二句说此江中有金膏、水碧，然都灭其明光，止其温润而不见。
千里曲：曲名，即《千里别鹤》曲。蔡邕《琴操》：“商陵牧子娶妻五年，无子，父兄欲为改娶，牧子援琴鼓之，叹别鹤以舒其愤懑。故曰《别鹤操》。鹤一举千里，故名《千里别鹤》也。”
弦绝：曲终。李善《文选注》说：“言奏曲冀以消忧，弦绝而念逾甚。故曰‘徒作’也。”', '我对日复一日的水行客宿已经厌倦，因为风潮变幻不定，莫可理究，凶险难测。彭蠡水波涛奔流，时而遇到洲岛，立刻遽分两股，急转猛合，又冲撞到岸崖之上，崩起重重雪浪，更凝聚起来，奔流而下。沿途，有时乘月夜游，聆听哀怨的猿啼，湿露而行，赏玩芳草的浓香；有时晨起远眺，近处晚春秀野，碧绿无际，远处苍岩高峙，白云如聚。我想凭借与寥夜清晨静景的对晤，来参透这冥冥之理。但是日日夜夜，朝朝昏昏，百思千索，依然不解。因不耐静思默想，于是攀登悬崖，登上了石镜山；牵萝扳叶，进入了松门顶。访异探秘，登高远望，然而三江九派，先哲的记载，已成难以追寻的故事；沧海桑田，这千变万化的自然之理，更难以考究。如今灵物异人已惜其珍藏，秘其精魂；金膏仙药，温润水玉，早已灭其明光，辍其流温。对于这颠颠倒倒，是非莫明的一切，我奏起了《千里别鹤》曲。突然断弦一声，万籁俱寂，唯有那无尽愁思在江天回荡。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb32cee9a0c24eda8bc", "shortContent": "彭蠡湖，即今江西鄱阳湖。湖口即江州（今江西九江）口，为彭蠡与长江交接处。自《尚书·禹贡》后，古书对湖口水势的记载有“三江既入”、“九江孔殷”等说，由于地貌变迁，加以传说悠谬，是三为九，本费猜思，而具体何指，更莫衷一是。于是种种的传说也应运而生。这本是人们发思古之幽情的好处所，加以水流吞吐，水道复杂，更有一派奇景壮观，于是催发了诗人们千百次吟咏，谢客此诗是其中最早的也是最优秀的篇章之一。\n诗作于元嘉...", "authors": ["赵昌平"], "pressName": "上海辞书出版社"}, {"bookId": "645fc1be30675327e174e067", "bookTitle": "历代山水诗鉴赏：江山留胜迹", "articleId": "647325f030675327e1c54c5f", "shortContent": "彭蠡湖，即今江西鄱阳湖。湖口即江州（今江西九江）口，为彭蠡与长江交接处。自《尚书•禹贡》后，古书对湖口水势的记载有“三江既入”、“九江孔殷”等说，由于地貌变迁，加以传说悠谬，是三为九，本费猜思，而具体何指，更莫衷一是。于是种种的传说也应运而生。这本是人们发思古之幽情的好处所，加以水流吞吐，水道复杂，更有一派奇景壮观，于是催发了诗人们千百次吟咏，谢灵运此诗是其中最早的也是最优秀的篇章之一。\n诗作于元...", "authors": ["赵昌平"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "6470a569b5420e27678a6b4b", "shortContent": "彭蠡湖，即今江西鄱阳湖。湖口即江州(今江西九江)口，为彭蠡与长 江交接处。自《尚书·禹贡》后，古书对湖口水势的记载有“三江既入”、 “九江孔殷”等说，由于地貌变迁，加以传说悠谬，是三为九，本费猜思，而具体何指，更莫衷一是。于是种种的传说也应运而生。这本是人们发思 古之幽情的好处所，加以水流吞吐，水道复杂，更有一派奇景壮观，于是催 发了诗人们千百次吟咏，谢客此诗是其中最早的也是最优秀的篇章之一。\n\n...", "authors": ["赵昌平"], "pressName": "上海辞书出版社"}]', '方回：“灵物”“异人”以下，又归宿于仙道。“千里曲”，想当时有此琴操，徒作此曲，而仙灵不接，所以弦虽绝而心徒悲也。大抵以恍惚为宗，要为不近人情，胸中亦别无十分道理也。（《文选颜鲍谢诗评》卷三）
王夫之：抉微挹秀，无非至者，华净之光，遂掩千秋。（《古诗评选》）
吴淇：舍舟而崖，远入松门而望，三江九派历历矣。“事”者，古人之事迹，如大禹九江既入之绩之类。然事既往矣，熟为继之？“理”者，即康乐后诗所蕴之“真”，（指《登江中孤屿》中的“蕴真谁为传”句），如古圣观河而作图，临洛而作书，皆因其理。其理空存，谁是作者？故灵物吝珍怪而不出，异人秘精魄而不见，金膏之明光已灭，水碧之流久缀。所谓天地闭、贤人隐之时也。所以徒作思归之曲，转令忧念益甚耳。（《六朝选诗定论》）', 'center', 1553685802, '5bd2827d44d904005e998775', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640204, '过白岸亭', NULL, 0, 135, 2, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', '', '', '拂衣遵沙垣，缓步入蓬屋。
近涧涓密石，远山映疏木。
空翠难强名，渔钓易为曲。
援萝临青崖，春心自相属。
交交止栩黄，呦呦食萍鹿。
伤彼人百哀，嘉尔承筐乐。
荣悴迭去来，穷通成休慽。
未若长疏散，万事恒抱朴。', '', '', '', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb203572034f65a9519", "shortContent": "这首诗作于景平元年（423），即谢灵运出为永嘉太守的第二年初春。“白岸亭”，在柟溪西南，离永嘉八十七里，以溪岸有白沙而得名。\n诗的开头两句点题，说诗人拂了拂衣袖，站起动身，沿着一条沙岸前进，缓步进入一座草屋，这就是白岸亭。“遵”，循，沿。“垣”，矮墙，此指岸沙堆积如垣。“拂衣”、“缓步”，动作舒缓，透露出诗人起行时的闲适心情。次四句，写沿途风物。近处是一条溪涧，细细的溪水潺湲地流过密石；透过稀疏的...", "authors": ["陶文鹏"], "pressName": "上海辞书出版社"}]', '', 'center', 1553655310, '5bd282cfee920a0068e399d8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640205, '于南山往北山经湖中瞻眺', NULL, 0, 135, 3, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E4%BA%8E%E5%8D%97%E5%B1%B1%E5%BE%80%E5%8C%97%E5%B1%B1%E7%BB%8F%E6%B9%96%E4%B8%AD%E7%9E%BB%E7%9C%BA/1001547?fr=aladdin', '', '朝旦发阳崖，景落憩阴峰。
舍舟眺迥渚，停策倚茂松。
侧径既窈窕，环洲亦玲珑。
俯视乔木杪，仰聆大壑灇。
石横水分流，林密蹊绝踪。
解作竟何感，升长皆丰容。
初篁苞绿箨，新蒲含紫茸。
海鸥戏春岸，天鸡弄和风。
抚化心无厌，览物眷弥重。
不惜去人远，但恨莫与同。
孤游非情叹，赏废理谁通。', '《于南山往北山经湖中瞻眺》是南北朝文学家谢灵运所作的一首五言古诗，诗中描写的是作者由南山往北山经过巫湖时所见的自然美景。', '南山：指今浙江省嵊州市西北的突山、石门山一带。
北山：相对南山而言，指今浙江省上虞市南的东山一带。
瞻（zhān）：往前或往上看。
眺（tiào）：远望。
阳崖：指南山。古时以山南为阳，山北为阴，所以称南山为阳崖。
景：日光，这里指太阳。
憩（qì）：休息。
阴峰：北山。
迥（jiǒng）：远。
渚（zhǔ）：水中的小块陆地，也称洲。
停策：止步的意思。策，手杖。
窈（yǎo）窕（tiǎo）：细长曲折的样子。
玲珑：澄明闪光的样子，形容小洲在天光水色辉映中的状态。
杪（miǎo）：树梢。
淙（cóng）：流水声。
蹊（xī）：小路。
解作：雷雨大作。
丰容：草木茂盛的样子。
篁（huáng）：竹子。
苞：包裹。
箨（tuò）：竹笋一层层的外皮。
新蒲：新生的蒲草。蒲，即菖蒲，生于水边，有香气，根可入药。
紫茸（róng）：初生的蒲叶呈紫色，所以称紫茸。茸，初生的草。
海鸥：一名江鸥，水鸟名，随潮水上下翻飞。
天鸡：鸟名，丹鸡。
抚化：把自己的思想感情渗透到自然万物之中，并与之融为一体；万物有盛衰荣枯的变化，自己也就随之而产生喜怒哀乐。
心无厌：面对美好的自然万物，总是看不够。厌，满足。
览物：观赏景物。
眷（juàn）：留恋。
弥（mí）：更。
去人：隐逸之人。
赏废：赏心之事废止，也就是说，再也不能与好友欢会言笑了。', '清晨出发于南山岩崖，傍晚歇息在北山顶峰。
离船眺望远处的沙洲，拄杖倚靠丰茂的青松。
盘山的小径蜿蜒幽深，圆圆的小洲晶莹空明。
俯视可见高树的梢头，举首聆听深谷的水声。
巨石横谷使涧水分流，密林遮断路径的去向。
春雨普降催万物萌动，草木滋长正葱葱茏茏。
初生的丛竹包裹绿皮，新绿的蒲草紫花待放。
海鸥嬉戏于春日水岸，天鸡弃羽于和煦暖风。
与万物同化心无厌倦，观照物象而悄然移情。
不惜古人隐逸去久远，只恨今人情志不与同。
独游违我真情而慨叹，赏乐废止玄理谁能通。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb30ce818559d0646b0", "shortContent": "这首诗集中体现了谢灵运山水诗的风格特色。\n首先，让我们看看此诗的题目。灵运的诗题往往扼要概括他登山临水的路线和行程，具有很强的真实性。诗题“于南山往北山经湖中瞻眺”，“于”、“往”、“经”将游览过程叙说得十分具体。谢灵运《山居赋》注曰：“大小巫湖，中隔一山。然往北山，经巫湖中过。”明乎此，就可以说：“康乐题便佳，有一种纪游笔致。”（《孙评文选》卷二）题本身简直就是诗。\n其次，谢灵运山水诗有一个大体...", "authors": ["宋绪连"], "pressName": "上海辞书出版社"}]', '明·王夫之《古诗评选》卷五：一命笔即作数往回，古无创人，后亦无继者。人非不欲继，无其随往不穷之才致故也。
清·何焯《义门读书记》卷四十六：“俯视乔木”四语，可悟画理。', 'center', 1553681490, '5bd283199f54540066879b87', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640256, '中庸 · 第一章', NULL, 89, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '天命之谓性，率性之谓道，修道之谓教。道也者，不可须臾离也，可离，非道也。是故君子戒慎乎其所不睹，恐惧乎其所不闻。莫见乎隐，莫显乎微，故君子慎其独也。
喜怒哀乐之未发谓之中，发而皆中节谓之和。中也者，天下之大本也；和也者，天下之达道也。致中和，天地位焉，万物育焉。', '', '', '人的自然禀赋叫做“性”，顺着本性行事叫做“道”，按照“道”的原则修养叫做“教”。
“道”是不可以片刻离开的，如果可以离开，那就不是“道”了。所以，品德高尚的人在没有人看见的地方也是谨慎的，在没有人听见的地方也是有所戒惧的。越是隐蔽的地方越是明显，越是细微的地方越是显著。所以，品德高尚的人在一人独处的时候也是谨慎的。
喜怒哀乐没有表现出来的时候，叫做“中”；表现出来以后符合节度，叫做“和”。“中”，是人人都有的本性；“和”，是大家遵循的原则，达到“中和”的境界，天地便各在其位了，万物便生长繁衍了。', NULL, '', 'indent', 1540829771, '5bd6c1d80b61600066086053', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640257, '中庸 · 第二章', NULL, 42, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '仲尼曰：“君子中庸，小人反中庸。君子之中庸也，君子而时中。小人之反中庸也，小人而无忌惮也。”', '', '', '仲尼说：“君子中庸，小人违背中庸。君子之所以中庸，是因为君子随时做到适中，无过无不及；小人之所以违背中庸，是因为小人肆无忌惮，专走极端。”', NULL, '', 'indent', 1540829814, '5bd6c215ee920a0068390b33', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640258, '中庸 · 第三章 ', NULL, 29, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '子曰：“中庸其至矣乎！民鲜能久矣。”', '', '', '孔子说：“中庸大概是最高的德行了吧！大家缺乏它已经很久了！”', NULL, '', 'indent', 1540832928, '5bd6c22c44d904005ed1adf0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640264, '中庸 · 第十章', NULL, 22, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '子路问强。子曰：“南方之强与？北方之强与？抑而强与？宽柔以教，不报无道，南方之强也，君子居之。衽金革，死而不厌，北方之强也，而强者居之。故君子和而不流，强哉矫！中立而不倚，强哉矫！国有道，不变塞焉，强哉矫！国无道，至死不变，强哉矫！”', '', '', '子路问什么是强。孔子说：“南方的强呢？北方的强呢？还是你认为的强呢？用宽容柔和的精神去教育人，人家对我蛮横无礼也不报复，这是南方的强，品德高尚的人具有这种强。用兵器甲盾当枕席，死而后已，这是北方的强，勇武好斗的人就具有这种强。所以，品德高尚的人和顺而不随波逐流，这才是真强啊！保持中立而不偏不倚，这才是真强啊！国家政治清平时不改变志向，这才是真强啊！国家政治黑暗时坚持操守，宁死不变，这才是真强啊！”', NULL, '', 'indent', 1540829983, '5bd6c2bf17d00900621cb9fb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640265, '中庸 · 第十一章 ', NULL, 16, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '子曰：“素隐行怪，后世有述焉，吾弗为之矣。君子遵道而行，半途而废，吾弗能已矣。君子依乎中庸，遁世不见知而不悔，唯圣者能之。”', '', '', '孔子说：“专找歪理，做些怪诞的事情来欺世盗名，后世也许会有人来记述他，为他立传，但我是绝不会这样做的。有些品德不错的人按照中庸之道去做，但是半途而废，不能坚持下去，而我是绝不会停止的。真正的君子遵循中庸之道，即使隐遁山林、一生默默无闻，不被人知道也不后悔，这只有圣人才能做得到。”', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b1e13b6a81d0c538c2650", "shortContent": " 《中庸》这几章首先指明了妨碍实行中庸之道的思想观念，提出了实行中庸之道应当具有的人格品质。\n\n刚强、勇敢是人们赞扬的美德，人们往往把那些临危不惧、奋不顾身的举动视为英雄行为，但有的人却逞一时之勇，在受到轻视、侮辱、挑衅或挑动就恶言相加，拔拳动刀，做出激烈的反应。《中庸》认为这种极端行为是对中庸之道的最常见的危害。所以第十章在分析、阐述“强”（刚强、勇敢）的概念时指出“衽金革，死而不厌”是“北方之...", "authors": ["魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1540830246, '5bd6c2d2ee920a00681bc645', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640266, '中庸 · 第十二章', NULL, 15, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '君子之道费而隐。夫妇之愚，可以与知焉，及其至也，虽圣人亦有所不知焉。夫妇之不肖，可以能行焉，及其至也，虽圣人亦有所不能焉。天地之大也，人犹有所憾。故君子语大，天下莫能载焉；语小，天下莫能破焉。《诗》云：“鸢飞戾天，鱼跃于渊。”言其上下察也。君子之道，造端乎夫妇，及其至也，察乎天地。', '', '', '君子的道广大而又精微。普通男女虽然愚昧，也可以知道君子的道，但它的最高深境界，即便是圣人也有弄不清楚的地方。普通男女虽然不贤明，也可以实行君子的道，但它的最高深境界，即便是圣人也有做不到的地方。天地如此之大，但人们仍有不满足的地方。所以，君子说到“大”，就大得连整个天下都装不下；君子说到“小”，就小得连一点儿也分不开。《诗经》说：“鸢鸟飞向天空，鱼儿跳跃深水。”这是说上下分明。君子的道，开始于普通男女，但它的最高深境界却昭著于整个天地。', NULL, '', 'indent', 1540830024, '5bd6c2e844d904005ed1b8ca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640267, '中庸 · 第十三章', NULL, 22, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '子曰：“道不远人。人之为道而远人，不可以为道。”“《诗》云：''伐柯伐柯，其则不远。’执柯以伐柯，睨而视之，犹以为远。故君子以人治人。改而止。”“忠恕违道不远，施诸己而不愿，亦勿施于人。”“君子之道四，丘未能一焉。所求乎子以事父，未能也；所求乎臣以事君，未能也；所求乎弟以事兄，未能也；所求乎朋友先施之，未能也。庸德之行，庸言之谨；有所不足，不敢不勉；有余，不敢尽。言顾行，行顾言，君子胡不慥慥尔？”', '', '', '孔子说：“道离人不远的。如果有人实行道却故作高深，使道远离人们，那就不可以实行道了。”“《诗经》说：''砍削斧柄，砍削斧柄，斧柄的式样就在眼前。’握着斧柄砍削木材制的斧柄，应该说不会有什么差异，但如果你斜眼一看，还是会发现差异很大。所以，君子总是根据不同人的情况采取不同的办法治理，只要他能改正错误实行道就行。”“一个人做到忠恕，离道也就不远了。什么叫忠恕呢？自己不愿意做的事，也不要施加给别人。”“君子的道有四项，我孔丘连其中的一项也没有能够做到：作为一个儿子应该对父亲做到的，我没有能够做到；作为一个臣民应该对君王做到的，我没能做到；作为一个弟弟应该对哥哥做到的，我没能做到；作为一个朋友应该做到的，我没能做到。平常的德行努力实践，平常的言谈尽量谨慎。德行的实践有不足的地方，不敢不勉励自己努力；言谈却不敢放肆而无所顾忌。说话顾到能否做到，行为也要顾到所说的话，这样的君子怎么会不忠厚诚实呢？”', NULL, '', 'indent', 1540830045, '5bd6c2fd17d00900621cbd43', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640268, '中庸 · 第十四章', NULL, 25, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '君子素其位而行，不愿乎其外。素富贵，行乎富贵；素贫贱，行乎贫贱：素夷狄，行乎夷狄；素患难，行乎患难。君子无入而不自得焉！在上位，不陵下；在下位，不援上。正己而不求于人，则无怨。上不怨天，下不尤人。故君子居易以俟命，小人行险以徼幸。子曰：“射有似乎君子，失诸正鹄，反求诸其身。”', '', '', '君子安于现在所处的地位去做应做的事，不生非分之想。处于富贵的地位，就做富贵人应做的事；处于贫贱的状况，就做贫xx应做的事；处于边远地区，就做在边远地区应做的事；处于患难之中，就做在患难之中应做的事。君子无论处于什么情况下都是安然自得的。处于上位，不欺侮在下位的人；处于下位，不攀援在上位的人。端正自己而不苛求别人，这样就不会有什么抱怨了。上不抱怨天，下不抱怨人。所以，君子安居现状来等待天命，小人却铤而走险妄图获得非分的东西。孔子说：“君子立身处世就像射箭一样，射不中，不怪靶子不正，只怪自己箭术不行。”', NULL, '', 'indent', 1540830064, '5bd6c3100b61600066087238', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640269, '中庸 · 第十五章', NULL, 23, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '君子之道，辟如行远必自迩；辟如登高必自卑。《诗》曰：“妻子好合，如鼓瑟琴。兄弟既翕，和乐且耽。宜尔室家，乐尔妻帑。”子曰：“父母其顺矣乎！”', '', '', '君子实行中庸之道，就像走远路一样，必定要从近处开始；就像登高山一样，必定要从低处起步。《诗经》说：“妻子儿女感情和睦，就像弹琴鼓瑟一样。兄弟关系融洽，和顺又快乐。使你的家庭美满，妻儿幸福。”孔子赞叹说：“这样，父母也就称心如意了啊！”', NULL, '', 'indent', 1540830084, '5bd6c324ac502e0061f7ba50', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640270, '中庸 · 第十六章', NULL, 16, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '子曰：“鬼神之为德，其盛矣乎！视之而弗见，听之而弗闻，体物而不可遗。使天下之人，齐明盛服，以承祭祀。洋洋乎，如在其上，如在其左右。《诗》曰：''神之格思，不可度思，矧可射思。’夫微之显，诚之不可掩如此夫！”', '', '', '孔子说：“鬼神的德行可真是大得很啊！看它也看不见，听它也听不到，但它却体现在万物之中使人无法离开它。天下的人都斋戒净心，穿着庄重整齐的服装去祭祀它，无所不在啊！好像就在你的头上，又像在你左右。《诗经》说：''神的降临，不可揣测，怎么能够怠慢不敬呢？’从隐微到显著，真实的东西就是这样不可掩盖！”', NULL, '', 'indent', 1540830104, '5bd6c3370b61600066087457', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640271, '中庸 · 第十七章', NULL, 18, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '子曰，「舜其大孝也与！德为圣人，尊为天子，富有四海之内。宗庙飨之，子孙保之。」
「故大德，必得其位，必得其禄，必得其名，必得其寿。」
「故天之生物必因其材而笃焉。故栽者培之，倾者覆之。」
「诗曰，『嘉乐君子，宪宪令德，宜民宜人。受禄于天。保佑命之，自天申之。』」
「故大德者必受命。」', '', '宗庙：古代天子、诸侯祭祀先王的地方。飨（xiang）：一种祭祀形式，祭先王。之，代词，指舜。
材，资质，本性。
笃：厚，这里指厚待。
培：培育。
覆：倾覆，摧败。
“嘉乐君子……”：引自《诗经·大雅·假乐》。嘉乐，即《诗经》之“假乐”，“假”通”嘉”，意为美善。宪宪，《诗经》作“显显”，显明兴盛的样子。令，美好。申，重申。', '孔子说：“舜该是个最孝顺的人了吧？德行方面是圣人，地位上是尊贵的天子，财富拥有整个天下，宗庙里祭祀他，子子孙孙都保持他的功业。”
“所以，有大德的人必定得到他应得的地位，必定得到他应得的财富，必定得到他应得的名声，必定得到他应得的长寿。”
“所以，上天生养万物，必定根据它们的资质而厚待它们。能成材的得到培育，不能成材的就遭到淘汰。”
“《诗经》说：‘高尚优雅的君子，有光明美好的德行，让人民安居乐业，享受上天赐予的福禄。上天保佑他，任用他，给他以重大的使命。’”
“所以，有大德的人必定会承受天命。”', NULL, '', 'indent', 1540830125, '5bd6c34d9f5454006e298ef3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640272, '中庸 · 第十八章', NULL, 15, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '子曰：「无忧者其惟文王乎！以王季为父，以武王为子，父作之，子述之。武王缵大王、王季、文王之绪。壹戎衣而有天下，身不失天下之显名。尊为天子，富有四海之内。宗庙飨之，子孙保之。武王末受命，周公成文武之德，追王大王、王季，上祀先公以天子之礼。斯礼也，达乎诸侯大夫，及士庶人。父为大夫，子为士；葬以大夫，祭以士。父为士，子为大夫；葬以士，祭以大夫。期之丧达乎大夫，三年之丧达乎天子，父母之丧无贵贱一也。」', '', '', '孔子说：古代帝王中无忧无虑的，大概衹有周文王吧！因为他有贤明的王季做父亲，有英勇的武王做儿子，父亲王季为他开创了基业，儿子周武王继承了他的遗志，完成了他所没有完成的事业。武王继续着太王、王季、文王未完成的功业，灭掉了大殷，取得了天下。周武王这种以下伐上的正义行动，不仅没有使他自身失掉显赫天下的美名，反而被天下人尊为天子，掌握普天下的财富，世代在宗庙中享受祭祀，子孙永保祭祀不断。周武王晚年才接受天命而成为天子，由周公成就了文王和武王的道德礼仪理想，追封太王、王季、文王为王，提升了祭祀祖父以上的历代先祖的级别，用天子的礼仪形式进行祭祀了。这种礼制形式，通用于诸侯、大夫、士、庶人等各个级别。父亲生前的职位是大夫，儿子的职位是士，父亲去世后的丧礼就按照大夫的级别举办，祭祀的时候用士这个级别的礼仪形式。父亲生前的职位是士，儿子的职位是大夫，父亲去世后的丧礼就按照士的级别，祭祀的时候按照大夫的级别。守丧一年的丧期穿什么样的丧服，通行到大夫这个级别；守丧三年的丧期穿什么样的丧服，通行到天子；为父亲和母亲守丧时的所穿的丧服，不分贵贱级别，完全一样。', NULL, '', 'indent', 1540830149, '5bd6c3649f5454006e29900b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640273, '中庸 · 第九章', NULL, 17, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '子曰：「天下国家可均也，爵禄可辞也，白刃可蹈也，中庸不可能也。」', '', '', '孔子说：「天下国家可以治理，官爵俸禄可以放弃，雪白的刀刃可以践踏而过，中庸却不容易做到。」', NULL, '', 'indent', 1540830535, '5bd6c4e60b61600066088dbb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640274, '中庸 · 第十九章 ', NULL, 11, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '子曰：“武王、周公，其达孝矣乎！夫孝者，善继人之志，善述人之事者也。春秋修其祖庙，陈其宗器，设其裳衣，荐其时食。宗庙之礼，所以序昭穆也；序爵，所以辨贵贱也；序事，所以辨贤也；旅酬下为上，所以逮贱也；燕毛，所以序齿也。”
“践其位，行其礼，奏其乐，敬其所尊，爱其所亲，事死如事生，事亡如事存，孝之至也。”“郊社之礼，所以事上帝也；宗庙之礼，所以祀乎其先也。明乎郊社之礼，禘尝之义，治国其如示诸掌乎！”', '', '', '孔子说：“周武王和周公真是最守孝道的人吧！所说的孝道，就是善于继承先人的遗志，善于继续先人未完成的功业。在春秋两季祭祀的时节，整修祖宗庙宇，陈列祭祀器具，摆设先王遗留下来的衣裳，进献祭祀应时的鲜美食品。
按照宗庙祭祀的礼制，是要把父子、长幼、亲疏的次序排列出来；把官职爵位的次序排列出来，就能将贵贱分辨清楚；在众人劝酒时把执事职位的次序排列出来，就能将才能的高低分辨清楚，晚辈必须先向长辈举杯，这样祖先的恩惠就会延及到晚辈，宴饮时按年龄大小来决定宴席座次，这样就能使老小长幼秩序井然。”
“站在合适的位置上，行先王传下的祭礼，演奏先王时代的音乐，尊敬先王所尊敬的，亲爱先王所亲爱的。侍奉死去的人就像侍奉活着的人一样；侍奉亡故的人就像侍奉活着的人一样，这才是孝的最高境界。
制定了祀天祭地的礼节，是用来侍奉皇天后土的；制定了宗庙的礼节，是用来祭祀祖先的。明白了郊社的礼节，大祭小祭的意义，那么治理天下国家的道理，也就像看着自己手掌上的东西那样容易明白啊！”', NULL, '', 'indent', 1540830715, '5bd6c59bac502e0061f7dce0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640275, '中庸 · 第二十章', NULL, 38, 33, 1, 2, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '哀公问政。
子曰，「文武之政，布在方策。其人存，则其政举；其人亡，则其政息。」
「人道敏政，地道敏树。夫政也者，蒲卢也。」
「故为政在人。取人以身。修身以道。修道以仁。」
「仁者，人也，亲亲为大。义者，宜也，尊贤为大。亲亲之杀，尊贤之等，礼所生也。」
「在下位，不获乎上，民不可得而治矣。」
「故君子，不可以不修身。思修身，不可以不事亲。思事亲，不可以不知人。思知人，不可以不知天。」
「天下之达道五，所以行之者三，曰：君臣也、父子也、夫妇也、昆弟也、朋友之交也。五者，天下之达道也。知、仁、勇三者，天下之达德也。所以行之者一也。」
「或生而知之；或学而知之；或困而知之：及其知之，一也。或安而行之；或利而行之；或勉强而行之：及其成功，一也。」
子曰，「好学近乎知。力行近乎仁。知耻近乎勇。」
「知斯三者，则知所以修身。知所以修身，则知所以治人。知所以治人，则知所以治天下国家矣。」
「凡为天下国家有九经，曰：修身也、尊贤也、亲亲也、敬大臣也、体群臣也、子庶民也、来百工也、柔远人也、怀诸侯也。」
「修身，则道立。尊贤，则不惑。亲亲，则诸父昆弟不怨。敬大臣，则不眩。体群臣，则士之报礼重。子庶民，则百姓劝。来百工，则财用足。柔远人，则四方归之。怀诸侯，则天下畏之。」
「齐明盛服，非礼不动：所以修身也。去谗远色，贱货而贵德，所以劝贤也。尊其位，重其禄，同其好恶，所以劝亲亲也。官盛任使，所以劝大臣也。忠信重禄，所以劝士也。时使薄敛，所以劝百姓也。日省月试，既禀称事，所以劝百工也。送往迎来，嘉善而矜不能所以柔远人也。继绝世，举废国，治乱持危，朝聘以时，厚往而薄来，所以怀诸侯也。」
「凡为天下国家有九经，所以行之者一也。」
「凡事，豫则立，不豫则废。言前定，则不跲。事前定，则不困。行前定，则不疚。道前定，则不穷。」
「在下位不获乎上，民不可得而治矣。获乎上有道：不信乎朋友，不获乎上矣。信乎朋友有道：不顺乎亲，不信乎朋友矣。顺乎亲有道：反者身不诚，不顺乎亲矣。诚身有道：不明乎善，不诚乎身矣。」
「诚者，天之道也。诚之者，人之道也。诚者，不勉而中不思而得：从容中道，圣人也。诚之者，择善而固执之者也。」
「博学之，审问之，慎思之，明辨之，笃行之。」
「有弗学，学之弗能，弗措也。有弗问，问之弗知，弗措也。有弗思，思之弗得，弗措也。有弗辨，辨之弗明，弗措也。有弗行，行之弗笃，弗措也。人一能之，己百之。人十能之，己千之。」
「果能此道矣，虽愚必明，虽柔必强。」', '', '', '鲁哀公询问政事。孔子说：“周文王、周武王的政事都记载在典籍上。他们在世，这些政事就实施;他们去世，这些政事也就废弛了。治理人的途径是勤于政事;治理地的途径是多种树木。说起来，政事就像芦苇一样，完全取决于用什么人。要得到适用的人在于修养自己，修养自己在于遵循大道，遵循大道要从仁义做起。仁就是爱人，亲爱亲族是最大的仁。义就是事事做得适宜，尊重贤人是最大的义。至于说亲爱亲族要分亲疏，尊重贤人要有等级，这都是礼的要求。处在下位的人不能得到上面的信任和支持，那就不可能治理好人民。所以，君子不能不修养自己。要修养自己，不能不侍奉亲族;要侍奉亲族，不能不了解他人;要了解他人，不能不知道天理。”
天下人共有的伦常关系有五项，用来处理这五项伦常关系的德行有三种。君臣、父子、夫妇、兄弟、朋友之间的交往，这五项是天下人共有的伦常关系;智、仁、勇，这三种是用来处理这五项伦常关系的德行。至于这三种德行的实施，道理都是一样的。比如说，有的人生来就知道它们，有的人通过学习才知道它们，有的人要遇到困难后才知道它们，但只要他们最终都知道了，也就是一样的了。又比如说，有的人自觉自愿地去实行它们，有的人为了某种好处才去实行它们，有的人勉勉强强地去实行，但只要他们最终都实行起来了，也就是一样的了。孔子说：“喜欢学习就接近了智，努力实行就接近了仁，知道羞耻就接近了勇。知道这三点，就知道怎样修养自己，知道怎样修养自己，就知道怎样管理他人，知道怎样管理他人，就知道怎样治理天下和国家了。”
治理天下和国家有九条原则。那就是：修养自身，尊崇贤人，亲爱亲族，敬重大臣，体恤群臣，爱民如子，招纳工匠，优待远客，安抚诸侯。修养自身就能确立正道;尊崇贤人就不会思想困惑;亲爱亲族就不会惹得叔伯兄弟怨恨;敬重大臣就不会遇事无措;体恤群臣，士人们就会竭力报效;爱民如子，老百姓就会忠心耿耿;招纳工匠，财物就会充足;优待远客，四方百姓就会归顺;安抚诸侯，天下的人都会敬畏了。像斋戒那样净心虔诚，穿着庄重整齐的服装，不符合礼仪的事坚决不做，这是为了修养自身;驱除小人，疏远女色，看轻财物而重视德行，这是为了尊崇贤人;提高亲族的地位，给他们以丰厚的俸禄，与他们爱憎相一致，这是为了亲爱亲族;让众多的官员供他们使用，这是为了敬重大臣;真心诚意地任用他们，并给他们以较多的俸禄，这是为了体恤群臣;使用民役不误农时，少收赋税，这是为了爱民如子;经常视察考核，按劳付酬，这是为了招纳工匠;来时欢迎，去时欢送，嘉奖有才能的人，救济有困难的人，这是为了优待远客;延续绝后的家族，复兴灭亡的国家，治理祸乱，扶持危难，按时接受朝见，赠送丰厚，纳贡菲薄，这是为了安抚诸侯。总而言之，治理天下和国家有九条原则，但实行这些原则的道理都是一样的。
任何事情，事先有预备就会成功，没有预备就会失败。说话先有预备，就不会中断;做事先有预备，就不会受挫;行为先有预备，就不会后悔;道路预先选定，就不会走投无路。
在下位的人，如果得不到在上位的人信任，就不可能治理好平民百姓。得到在上位的人信任有办法：得不到朋友的信任就得不到在上位的人信任;得到朋友的信任有办法：不孝顺父母就得不到朋友的信任;孝顺父母有办法：自己不真诚就不能孝顺父母;使自己真诚有办法：不明白什么是善就不能够使自己真诚。
真诚是上天的原则，追求真诚是做人的原则。天生真诚的人，不用勉强就能做到，不用思考就能拥有，自然而然地符合上天的原则，这样的人是圣人。努力做到真诚，就要选择美好的目标执著追求：广泛学习，详细询问，周密思考，明确辨别，切实实行。要么不学，学了没有学会绝不罢休;要么不问，问了没有懂得绝不罢休;要么不想，想了没有想通绝不罢休;要么不分辨，分辨了没有明确绝不罢休;要么不实行，实行了没有成效绝不罢休。别人用一分努力就能做到的，我用一百分的努力去做;别人用十分的努力做到的，我用一千分的努力去做。如果真能够做到这样，虽然愚笨也一定可以聪明起来，虽然柔弱也一定可以刚强起来。
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b1e92b1076d586377b3dc", "shortContent": "第二十章论述儒家的政治哲学，最终从中提炼出整本《中庸》的核心观念：诚。\n\n作者按照儒家的思维方式，提出人是国家政治中的决定性因素。《中庸》在将人的因素同政治制度、政治学说的重要性加以比较时说：“文武之政，布在方策。其人存，则其政举；其人亡，则其政息。”人的因素在儒家的政治理论中包括了全体人民的道德水平，但在这里是指治理国家的人的思想品质。根据《中庸》的观点，如果执政者思想品质不好，那么任何一种优良...", "authors": ["魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1540832931, '5bd6cbbf9f5454006e2a067c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640276, '中庸 · 第二十一章 ', NULL, 12, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '自诚明，谓之性；自明诚，谓之教。诚则明矣，明则诚矣。', '', '', '由真诚而自然明白道理，这叫做天性；由明白道理后做到真诚，这叫做人为的教育。真诚也就会自然明白道理，明白道理后也就会做到真诚。', NULL, '', 'indent', 1540832336, '5bd6cbeb9f5454006e2a0952', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640451, '真珠帘 · 题宋牧仲枫香词次曹实庵韵', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '当时红杏尚书句。宋玉今朝风赋。萤火柳绵词，斗阳阿激楚。
五色蛮笺螺子墨，渲染彀、微云疏雨。凄苦。满歌坊粉壁，舞巾纨素。
一曲减字偷声，听小屏风后，玉箫潜度。低啭隔林莺，碎一庭花露。
鹍鸡又砉关山调，似万马、凭秋而怒。相诉。我中年以后，冰弦怕鼓。
', '', '', '', NULL, '', 'indent', 1541693820, '5be3f11b8d6d81005eda98ea', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640277, '中庸 · 第二十二章 ', NULL, 13, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '唯天下至诚，为能尽其性；能尽其性，则能尽人之性；能尽人之性，则能尽物之性；能尽物之性，则可以赞天地之化育；可以赞天地之化育，则可以与天地参矣。', '', '', '只有天下极端真诚的人能充分发挥他的天赋本性；能充分发挥他的本性，就能充分发挥众人的本性；能充分发挥众人的本性，就能充分发挥万物的本性；能充分发挥万物的本性，就可以赞助天地养育万物；能赞助天地养育万物，就可以与天地并列为三了。', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b1ef966a763596afdeb3d", "shortContent": " 这几章可以视为能够独立成篇的哲学论文，包含了极其丰富而又深刻的哲学思想，是中国哲学史上经典性的文本。它们论述了至诚与尽性、成己、成物的关系，描绘了至诚所产生的神奇效应和不可思议的结果。\n\n所谓至诚就是最高的真实。从天人合一的理念出发，《中庸》将性规定为天之道——诚——的自觉，说“自诚明谓之性”，这样它就合乎逻辑地提出天下之至诚就是个体无限地发挥自己的本性，即所谓“能尽其性”，可以说“尽其性”是对...", "authors": ["魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1540832405, '5bd6cc3444d904005ed23729', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640278, '中庸 · 第二十三章', NULL, 13, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '其次致曲，曲能有诚。诚则形，形则著，著则明，明则动，动则变，变则化；唯天下至诚为能化。', '', '', '比圣人次一等的贤人从细微处入手推究道理，也能达到真诚的境界。做到了真诚就会表现出来，表现出来就会逐渐显著，显著了就会发扬光大，发扬光大就会感动他人，感动他人就会引起转变，引起转变就能化育万物。只有天下最真诚的人能化育万物。', NULL, '', 'indent', 1540832431, '5bd6cc4a44d904005ed23971', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640279, '中庸 · 第二十四章 ', NULL, 12, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '至诚之道，可以前知。国家将兴，必有祯祥；国家将亡，必有妖孽。见乎蓍龟，动乎四体。祸福将至：善，必先知之；不善，必先知之，故至诚如神。', '', '', '真诚到极点，可以预知未来。国家将要兴旺，必然有吉祥的征兆；国家将要衰亡，必然有不祥的反常现象。或者呈现在占卜的蓍草龟甲上，或者表现在人的动作状态上。祸福将要来临时，是福可以预先知道，是祸也可以预先知道。所以极端真诚就像神灵一样微妙。', NULL, '', 'indent', 1540832453, '5bd6cc649f54540066c04123', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640280, '中庸 · 第二十五章 ', NULL, 16, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '诚者自成也；而道自道也。诚者物之终始，不诚无物。是故君子诚之为贵。诚者，非自成己而已也，所以成物也。成己，仁也；成物，知也。性之德也，合外内之道也，故时措之宜也。', '', '', '真诚是自我的完善，道是自我的引导。真诚是事物的发端和归宿，没有真诚就没有了事物。因此君子以真诚为贵。不过，真诚并不是自我完善就够了，而是还要完善事物。自我完善是仁，完善事物是智。仁和智是出于本性的德行，是融合自身与外物的准则，所以任何时候施行都是适宜的。', NULL, '', 'indent', 1540832475, '5bd6cc799f5454006e2a1388', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640281, '中庸 · 第二十六章 ', NULL, 11, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '故至诚无息，不息则久，久则征，征则悠远，悠远则博厚，博厚则高明。博厚，所以载物也；高明，所以覆物也；悠久，所以成物也。博厚配地，高明配天，悠久无疆。如此者，不见而章，不动而变，无为而成。
天地之道，可一言而尽也：其为物不贰，则其生物不测。天地之道，博也，厚也，高也，明也，悠也，久也。今夫天，斯昭昭之多，及其无穷也，日月星辰系焉，万物覆焉。今夫地，一撮土之多，及其广厚，载华岳而不重，振河海而不泄，万物载焉。今夫山，一卷石之多，及其广大，草木生之，禽兽居之，宝藏兴焉。
今夫水，一勺之多，及其不测，鼋鼍鲛龙鱼鳖生焉，货财殖焉。《诗》云：“惟天之命，于穆不已！”盖曰天之所以为天也。“于乎不显，文王之德之纯！”盖曰文王之所以为文也，纯亦不已。', '', '', '所以，极端真诚是永不停止的。永不停止就会保持长久，保持长久就会有效验，有效验就会悠远，悠远就会广博深厚，广博深厚就会高大光明。广博深厚才能承载万物；高大光明才能覆盖万物；悠远长久的作用是生成万物。广博深厚可以与地相比，高大光明可以与天相比，悠远长久则是永无止境。达到这样的境界，不自我显示也会自然彰明显著，不活动也会感人化物，无所作为也会自然有所成就。
天地的法则，简直可以用一个“诚”字来囊括：诚本身专一不二，所以生育万物有难测之妙。大地的法则，就是广博、深厚、高大、光明、悠远、长久。今天我们所说的天，原本不过是由一点一点的光明聚积起来的，可等到它无边无际时，日月星辰都靠它维系，世界万物都靠它覆盖。今天我们所说的地，原本不过是由一撮土一撮土聚积起来的，可等到它广博深厚时，承载像华山那样的崇山峻岭也不觉得重，容纳那众多的江河湖海也不会泄漏，世间万物都由它承载了。今天我们所说的山，原本不过是由拳头大的石块聚积起来的，可等到它高大无比时，草木在上面生长，禽兽在上面居住，宝藏也是从里面开发出来。今天我们所说的水，原本不过是一勺一勺聚积起来的，可等到它浩瀚无涯时，蛟龙鱼鳖等都在里面生长，各种货物财富都在里面繁殖生长出来。
《诗经》说，“天命多么深远啊，永远无穷无尽！”这大概就是说的天之所以为天的原因吧。“多么显赫光明啊，文王的品德纯正无二！”这大概就是说的文王之所以被称为“文”王的原因吧。纯正也是没有止息的。', NULL, '', 'indent', 1540832652, '5bd6cd2b9f54540066c04f59', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640282, '中庸 · 第二十七章 ', NULL, 16, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '大哉圣人之道！洋洋乎，发育万物，峻极于天。优优大哉！礼仪三百，威仪三千。待其人而后行。故曰：“苟不至德，至道不凝焉。”故君子尊德性而道问学，致广大而尽精微，极高明而道中庸。温故而知新，敦厚以崇礼。是故居上不骄，为下不倍。国有道，其言足以兴；国无道，其默足以容。《诗》曰：“既明且哲，以保其身。”其此之谓与！', '', '', '伟大啊，圣人的道！浩瀚无边，生养万物，与天一样崇高；充足有余，礼仪三百条，威仪三千条。这些都有待圣人来实行。所以说，如果没有极高的德行，就不能成就极高的道。因此，君子尊崇道德修养而追求知识学问；达到广博境界而又钻研精微之处；极端高明而又奉行中庸之道；温习已有的知识从而获得新知识；朴实厚道，崇奉礼节。所以身居高位不骄傲，身居低位不会犯上作乱，国家政治清明时，他的言论足以振兴国家；国家政治黑暗时，他的沉默足以保全自己。《诗经》说：“既明智又通达事理，可以保全自身。”大概就是说的这个意思吧！', NULL, '', 'indent', 1540832675, '5bd6cd4144d904005ed24a17', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640283, '中庸 · 第二十八章 ', NULL, 12, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '子曰：“愚而好自用，贱而好自专；生乎今之世，反古之道。如此者，灾及其身者也。”
非天子不议礼，不制度，不考文。今天下车同轨，书同文，行同伦。虽有其位，苟无其德，不敢做礼乐焉；虽有其德，苟无其位，亦不敢作礼乐焉。子曰：“吾说夏礼，杞不足征也。吾学殷礼，有宋存焉。吾学周礼，今用之，吾从周。”', '', '', '孔子说：“愚昧却喜欢自以为是，卑贱却喜欢独断专行。生于现在的时代却一心想回复到古代去。这样做，灾祸一定会降临到自己的身上。”不是天子就不要议订礼仪，不要制订法度，不要考订文字规范。现在天下车子的轮距一致，文字的规范统一，伦理道德相同。虽有天子的地位，如果没有圣人的德行，是不敢制作礼乐制度的；虽然有圣人的德行，如果没有天子的地位，也是不敢制作礼乐制度的。
孔子说：“我谈论夏朝的礼制，夏的后裔杞国以不足以验证它；我学习殷朝的礼制，殷的后裔宋国还残存着它；我学习周朝的礼制，现在还实行着它，所以我遵从周礼。”', NULL, '', 'indent', 1540832705, '5bd6cd5f17d00900621d511c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640452, '真珠帘', NULL, 0, 326, 0, 1, '李慈铭', NULL, 20875, '5858eeda128fe1006dcc6711', '清', 'ci', '词', '', '', '是谁琢就珍珠蕊。露苞含、多少温存深意。恰到半开时，又素馨如醉。
见说琳宫新采得，便暗取、荷囊深系。偷寄。恁背人低数，相思何事。
偏称小扇轻纨，配绰约簪花，琼瑶匀缀。卅喜算团圞，看细排心字。
比似丁香犹款密，好结取、从头盟誓。休弃。便箧缄香，见时长记。
', '', '', '', NULL, '', 'indent', 1541693919, '5be3f1818d6d81005eda9f3f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640284, '中庸 · 第二十九章', NULL, 13, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '王天下有三重焉，其寡过矣乎！上焉者，虽善无征，无征不信，不信，民弗从；下焉者，虽善不尊，不尊不信，不信，民弗从。
故君子之道，本诸身，征诸庶民，考诸三王而不缪，建诸天地而不悖，质诸鬼神而无疑，百世以俟圣人而不惑。质诸鬼神而无疑，知天也；百世以俟圣人而不惑，知人也。是故君子动而世为天下道，行而世为天下法，言而世为天下则。远之则有望，近之则不厌。
《诗》曰：“在彼无恶，在此无射。庶几夙夜，以永终誉。”君子未有不如此，而蚤有誉于天下者也。', '', '', '治理天下能够做好议订礼仪，制订法度，考订文字规范这三件重要的事，也就没有什么大的过失了吧！在上位的人，虽然行为很好，但如果没有验证的活，就不能使人信服，不能使人信服，老百姓就不会听从。在下位的人，虽然行为很好，但由于没有尊贵的地位，也不能使人信服，不能使人信服，老百姓就不会听从。
所以君子治理天下应该以自身的德行为根本，并从老百姓那里得到验证。考查夏、商、周三代先王的做法而没有背谬，立于天地之间而没有悖乱，质询于鬼神而没有疑问，百世以后待到圣人出现也没有什么不理解的地方。质询于鬼神而没有疑问，这是知道天理；百世以后待到圣人出现也没有什么不理解的地方，这是知道人意。所以君子的举止能世世代代成为天下的先导，行为能世世代代成为天下的法度，语言能世世代代成为天下准则。在远处有威望，在近处也不使人厌恶。
《诗经》说，“在那里没有人憎恶，在这里没有人厌烦，日日夜夜操劳啊，为了保持美好的名望。”君子没有不这样做而能够早早在天下获得名望的。', NULL, '', 'indent', 1540832735, '5bd6cd7e9f54540066c05549', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640285, '中庸 · 第三十章', NULL, 19, 33, 1, 2, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '仲尼祖述尧舜，宪章文武；上律天时，下袭水土。辟如天地之无不持载，无不覆帱，辟如四时之错行，如日月之代明。万物并育而不相害，道并行而不相悖。小德川流，大德敦化。此天地之所以为大也。', '', '', '孔子继承尧舜的传统，以文王、武王为典范，上遵循天时，下符合地理。就像天地那样没有什么不承载，没有什么不覆盖。又好像四季的交错运行，日月的交替光明。万物一起生长而互不妨害，道路同时并行而互不衝突。小的德行如河水一样川流不息，大的德行敦厚纯朴、化育万物。这就是天地的伟大之处啊！', NULL, '', 'indent', 1540832759, '5bd6cd96ee920a00681c610b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640286, '中庸 · 第三十一章 ', NULL, 23, 33, 0, 2, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '唯天下至圣，为能聪明睿知，足以有临也；宽裕温柔，足以有容也；发强刚毅，足以有执也；齐庄中正，足以有敬也；文理密察，足以有别也。溥博渊泉，而时出之。溥博如天，渊泉如渊。见而民莫不敬，言而民莫不信，行而民莫不说。是以声名洋溢乎中国，施及蛮貊，舟车所至，人力所通，天之所覆，地之所载，日月所照，霜露所队，凡有血气者，莫不尊亲。故曰配天。', '', '', '只有天下崇高的圣人，才能做到聪明智慧，能够居上位而临下民；宽宏大量，温和柔顺，能够包容天下；奋发勇健，刚强坚毅，能够决断天下大事；威严庄重，忠诚正直，能够博得人们的尊敬；条理清晰，详辨明察，能够辨别是非邪正。
崇高的圣人，美德广博而又深厚，并且时常会展现出来。德性广博如天，德性深厚如渊。美德表现在仪容上，百姓没有谁不敬佩，表现在言谈中，百姓没有谁不信服。表现在行动上，百姓没有谁不喜悦。
这样，美好的名声广泛流传在中国，并且传播到边远的少数民族地区。凡是车船行驶的地方，人力通行的地方，苍天覆盖的地方，大地承载的地方，日月照耀的地方，霜露降落的地方；凡有血气的生物，没有不尊重和不亲近他们的，所以说圣人的美德能与天相匹配。', NULL, '', 'indent', 1540832792, '5bd6cdb644d904005ed251f2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640287, '中庸 · 第三十二章 ', NULL, 8, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '唯天下至诚，为能经纶天下之大经，立天下之大本，知天地之化育。夫焉有所倚？肫肫其仁！渊渊其渊！浩浩其天！苟不固聪明圣知达天德者，其孰能知之？', '', '', '衹有天下地道的真诚，纔能成为治理天下的崇高典范，纔能树立天下的根本法则，掌握天地化育万物的深刻道理，这需要什么依靠呢！他的仁心那样诚挚，他的思虑像潭水那样幽深，他的美德像苍天那样广阔。如果不真是聪明智慧，通达天赋美德的人，还有谁能知道天下地地道道的真诚呢？', NULL, '', 'indent', 1540832875, '5bd6ce09ee920a00681c68b2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640288, '中庸 · 第三十三章 ', NULL, 16, 33, 0, 1, '子思', NULL, 36963, '5bd6bbc444d904005ed15a51', '周', 'wen', '文', '', '', '《诗》曰「衣锦尚絅」，恶其文之著也。故君子之道，闇然而日章；小人之道，的然而日亡。君子之道：淡而不厌，简而文，温而理，知远之近，知风之自，知微之显，可与入德矣。《诗》云：「潜虽伏矣，亦孔之昭！」故君子内省不疚，无恶于志。君子之所不可及者，其唯人之所不见乎。《诗》云：「相在尔室，尚不愧于屋漏。」故君子不动而敬，不言而信。《诗》曰：「奏假无言，时靡有争。」是故君子不赏而民劝，不怒而民威于鈇钺。《诗》曰：「不显惟德！百辟其刑之。」是故君子笃恭而天下平。《诗》云：「予怀明德，不大声以色。」子曰：「声色之于以化民，末也。」《诗》曰：「德輶如毛」，毛犹有伦。「上天之载，无声无臭」，至矣！', '', '', '《诗经》说：「身穿锦绣衣服，外面罩件套衫。」这是为了避免锦衣花纹太显露，所以，君子的道深藏不露而日益彰明；小人的道显露无遗而日益消亡。君子的道，平淡而有意味，简略而有文采，温和而有条理，由近因知远事，由风知源，由微知显，这样，就可以进入道德的境界了。
《诗经》说：「潜藏虽然很深，但也会很明显的。」所以君子自我反省没有愧疚，没有恶念存于心志之中。君子的德行之所以高于一般人，大概就是在这些不被人看见的地方吧？《诗经》说：「看你独自在室内的时候，是不是能无愧于神明。」所以，君子就是在没做什么事的时候也是恭敬的，就是在没有对人说什么的时候也是能表现出他的诚信。《诗经》说：「进奉诚心，感通神灵。肃穆无言，没有争执。」所以，君子不用赏赐，老百姓也会互相劝勉；不用发怒，老百姓也会很畏惧。《诗经》说：「弘扬那德行啊，诸侯们都来效法。」所以，君子笃实恭敬就能使天下太平。《诗经》说：「我怀有光明的品德，不用厉声厉色。」孔子说：「用厉声厉色去教育老百姓，是最拙劣的行为。」《诗经》说：「德行轻如毫毛。」轻如毫毛还是有物可比拟。「上天所承载的，既没有声音也没有气味」，这纔是最高的境界啊！', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b412cb6a81d0c538cdcbb", "shortContent": "《中庸》最后一部分论述至诚所造成的理想人格，其思想品质所达到的崇高境界以及对于国家、人民和现实社会所起的伟大作用。\n\n第二十九章所说的“君子之道”就是指圣人之道，是说圣人的思想与学说。在《中庸》中圣人就是称精神的完善、发展达到至诚地步的理想人格，因此第三十一章开头讲“天下至圣”，第三十二章的开端是写“天下至诚”，都是描述同一个对象。在《中庸》作者看来，孔子是理想人格的典范，是最具代表性、最能清楚地...", "authors": ["魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1540832919, '5bd6ce36ac502e0061f85c42', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640306, '西湖梦寻 · 总记', NULL, 9, 227, 1, 1, '张岱', NULL, 10007, '57ba82be165abd0066234de7', '明', 'wen', '文', '', '', '自马臻开鉴湖，而由汉及唐，得名最早。后至北宋，西湖起而夺之，人皆奔走西湖，而鉴湖之淡远，自不及西湖之冶艳矣。至于湘湖则僻处萧然，舟车罕至，故韵士高人无有齿及之者。余弟毅孺常比西湖为美人，湘湖为隐士，鉴湖为神仙。余不谓然。余以湘湖为处子，目氐婷羞涩，犹及见其未嫁之时；而鉴湖为名门闺淑，可钦而不可狎；若西湖则为曲中名妓，声色俱丽，然倚门献笑，人人得而媟亵之矣。人人得而媟亵，故人人得而艳羡；人人得而艳羡，故人人得而轻慢。
在春夏则热闹之至，秋冬则冷落矣；在花朝则喧哄之至，月夕则星散矣；在晴明则萍聚之至，雨雪则寂寥矣。故余尝谓：「善读书，无过董遇三馀，而善游湖者，亦无过董遇三馀。董遇曰：『冬者，岁之馀也；夜者，日之馀也；雨者，月之馀也。』雪巘古梅，何逊烟堤高柳；夜月空明，何逊朝花绰约；雨色涳蒙，何逊晴光滟潋。深情领略，是在解人。」即湖上四贤，余亦谓：「乐天之旷达，固不若和靖之静深；邺侯之荒诞，自不若东坡之灵敏也。」其馀如贾似道之豪奢，孙东瀛之华赡，虽在西湖数十年，用钱数十万，其于西湖之性情、西湖之风味，实有未曾梦见者在​​也。世间措大，何得易言游湖。
苏轼《夜泛西湖》诗：
　　菰蒲无边水茫茫，荷花夜开风露香。
　　渐见灯明出远寺，更待月黑看湖光。
又《湖上夜归》诗：
　　我饮不尽器，半酣尤味长。
　　篮舆湖上归，春风吹面凉。
　　行到孤山西，夜色已苍苍。
　　清吟杂梦寐，得句旋已忘。
　　尚记梨花村，依依闻暗香。
又《怀西湖寄晁美叔》诗：
　　西湖天下景，游者无愚贤。深浅随所得，谁能识其全。
　　嗟我本狂直，早为世所捐。独专山水乐，付与宁非天。
　　三百六十寺，幽寻遂穷年。所至得其妙，心知口难传。
　　至今清夜梦，耳目余芳鲜。君持使者节，风采烁云烟。
　　清流与碧巘，安肯为君妍。胡不屏骑从，暂借僧榻眠。
　　读我壁间诗，清凉洗烦煎。策杖无道路，直造意所使。
　　应逢古渔父，苇间自夤缘。问道若有得，买鱼弗论钱。
李奎《西湖》诗：
　　锦帐开桃岸，兰桡系柳津。
　　鸟歌如劝酒，花笑欲留人。
　　钟磬千山夕，楼台十里春。
　　回看香雾里，罗绮六桥新。
苏轼《开西湖》诗：
　　伟人谋议不求多，事定纷纭自唯阿。
　　尽放龟鱼还绿净，肯容萧苇障前坡。
　　一朝美事谁能继，百尺苍崖尚可磨。
　　天上列星当亦喜，月明时下浴金波。
周立勋《西湖》诗：
　　平湖初涨绿如天，荒草无情不记年。
　　犹有当时歌舞地，西泠烟雨丽人船。
夏炜《西湖竹枝词》：
　　四面空波卷笑声，湖光今日最分明。
　　舟人莫定游何外，但望鸳鸯睡处行。
　　平湖竟日只溟蒙，不信韶光只此中。
　　笑拾杨花装半臂，恐郎到晚怯春风。
　　行觞次第到湖湾，不许莺花半刻闲。
　　眼看谁家金络马，日驼春色向孤山。
　　春波四合没晴沙，昼在湖船夜在家。
　　怪杀春风归不断，担头原自插梅花。
欧阳修《西湖》诗：
　　菡萏香消画舸浮，使君宁复忆扬州。
　　都将二十四桥月，换得西湖十顷秋。
赵子昂《西湖》诗：
　　春阴柳絮不能飞，两足蒲芽绿更肥。
　　只恐前呵惊白鹭，独骑款段绕湖归。
袁宏道《西湖总评》诗：
　　龙井饶甘泉，飞来富石骨。
　　苏桥十里风，胜果一天月。
　　钱祠无佳处，一片好石码。
　　孤山旧亭子，凉荫满林樾。
　　一年一桃花，一岁一白发。
　　南高看云生，北高见月没。
　　楚人无羽毛，能得凡游越。
范景文《西湖》诗：
　　湖边多少游观者，半在断桥烟雨间。
　　尽逐春风看歌舞，凡人着眼看青山。
张岱《西湖》诗：
　　追想西湖始，何缘得此名。恍逢西子面，大服古人评。
　　冶艳山川合，风姿烟雨生。奈何呼不已，一往有深情。
　　一望烟光里，苍茫不可寻。吾乡争道上，此地说湖心。
　　泼墨米颠画，移情伯子琴。南华秋水意，千古有人钦。
　　到岸人心去，月来不看湖。渔灯隔水见，堤树带烟熇。
　　真意言词尽，淡妆脂粉无。问谁能领略，此际有髯苏。
又《西湖十景》诗：
　　一峰一高人，两人相与语。
　　此地有西湖，勾留不肯去。
　　（两峰插云）
　　湖气冷如冰，月光淡于雪。
　　肯弃与三潭，杭人不看月。
　　（三潭印月）
　　高柳荫长堤，疏疏漏残月。
　　蹩躠步松沙，恍疑是踏雪。
　　（断桥残雪）
　　夜气滃南屏，轻岚薄如纸。
　　钟声出上方，夜渡空江水。
　　（南屏晚钟）
　　烟柳幕桃花，红玉沉秋水。
　　文弱不胜夜，西施刚睡起。
　　（苏堤春晓）
　　颊上带微酡，解颐开笑口。
　　何物醉荷花，暖风原似酒。
　　（曲院风荷）
　　深柳叫黄鹂，清音入空翠。
　　若果有诗肠，不应比鼓吹。
　　（柳浪闻莺）
　　残塔临湖岸，颓然一醉翁。
　　奇情在瓦砾，何必藉人工。
　　（雷峰夕照）
　　秋空见皓月，冷气入林皋。
　　静听孤飞雁，声轻天正高。
　　（平湖秋月）
　　深恨放生池，无端造鱼狱。
　　今来花港中，肯受人拘束？
　　（花港观鱼）
柳耆卿《望海潮》词：
　　东南形胜，三吴都会，钱塘自古繁华。烟柳画桥，风帘翠幕，参差十万人家。云树绕堤沙。怒涛卷霜雪，天堑无涯。市列珠玑，户盈罗绮，竞豪奢。
　　重湖叠巘清佳，有三秋桂子，十里荷花。羌管弄晴，菱歌泛夜，嬉嬉钓叟莲娃。千骑拥高牙。乘醉听箫鼓，吟赏烟霞。异日图将好景，归去凤池夸。
（金主阅此词，慕西湖胜景，遂起投鞭渡江之思。）
于国宝《风入松》词：
　　一春常费买花钱，日日醉湖边。玉骢惯识西湖路，骄嘶过、沽酒楼前。红杏香中箫鼓，绿杨影里秋千。
　　暖风十里丽人天，花压鬓云偏。画船载得春归去，馀情付、湖水湖烟。明日重扶残醉，来寻陌上花钿。', '', '', '', '[{"bookId": "60fd4b9434bfda01e0eab209", "bookTitle": "唐宋小说鉴赏辞典", "articleId": "610f43ee5914587d02f6836a", "shortContent": "入话：\n此诗乃苏子瞻所作，单题西湖好处。言不尽意，又作一词，词名《眼儿媚》：\n说不尽西湖好处，吟有一词云：\n这西湖是真山真水，一年四景，皆可游玩。\n真山真水，天下更有数处：\n这几处虽然是真山真水，怎比西湖好处？假如：风起时，有千尺翻头浪；雨下时，有百丈滔天水。大雨一个月，不曾见满溢；大旱三个月，不曾见干涸。但见：\n那游人行到乱云深处，听得鸡鸣犬吠，缲丝织布之声，宛然人间洞府，世上蓬瀛：\n这西湖，晨...", "authors": ["王", "燕"], "pressName": "上海辞书出版社"}]', '', 'indent', 1540912350, '5bd7ffe2ee920a0068549e91', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642097, '幽梦影 · 卷一 · 六十六', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '文人讲武事，大都纸上谈兵；武将论文章，半属道听途说。', '', '', '', NULL, '吴街南曰：今日武将讲武事，亦属纸上谈兵；今之文人论文章，大都道听途说。', 'indent', 1556017097, '5cbe7f48a3180b7832e6e1d6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640331, '西湖梦寻 · 卷三 · 西湖中路 · 片石居 ', NULL, 0, 227, 1, 1, '张岱', NULL, 10007, '57ba82be165abd0066234de7', '明', 'wen', '文', '', '', '由昭庆缘湖而西，为餐香阁，今名片石居。？阁精庐，皆韵人别墅。其临湖一带，则酒楼茶馆，轩爽面湖，非惟心胸开涤，亦觉日月清朗。张谓“昼行不厌湖上山，夜坐不厌湖上月”，则尽之矣。再去则桃花港，其上为石函桥，唐刺史李邺侯所建，有水闸泄湖水以入古荡。沿东西马塍、羊角埂，至归锦桥，凡四派焉。白乐天记云：“北有石函，南有笕，决湖水一寸，可溉田五十余顷。”闸下皆石骨磷磷，出水甚急。
徐渭《八月十六片石居夜泛》词：
月倍此宵多，杨柳芙蓉夜色蹉。鸥鹫不眠如昼里，舟过，向前惊换几汀莎。筒酒觅稀荷，唱尽塘栖《白苎歌》。天为红妆重展镜，如磨，渐照胭脂奈褪何。', '', '', '', '[{"bookId": "60fc157134bfda01e0e91549", "bookTitle": "元明清词鉴赏辞典（新一版）", "articleId": "610e863e03572034f659ae5c", "shortContent": "苏轼《阳关曲》咏中秋月云：“暮云收尽溢清寒，银汉无声转玉盘。此生此夜不长好，明月明年何处看？”确实，中秋朗月，此夜不长，望月寄情，普天同心。然而，心裁别具而风骨独立的徐文长，却淡于“十五”而偏好“十六”。其诗，尝有《十六夜踏灯与璩仲玉王新甫饮于大中桥之西楼》之作，且被王夫之视为“得供奉（李白）、嘉州（岑参）之神”；其词，则有此阕《南乡子·八月十六片石居夜泛》，也被评家视为咏西湖明月的佳作。\n为什么...", "authors": ["陈文忠"], "pressName": "上海辞书出版社"}]', '', 'indent', 1540911945, '5bd802e8ac502e00610748a8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640333, '西湖梦寻 · 卷三 · 西湖中路 · 孤山', NULL, 4, 227, 1, 1, '张岱', NULL, 10007, '57ba82be165abd0066234de7', '明', 'wen', '文', '', '', '《水经注》曰：水黑曰卢，不流曰奴；山不连陵曰孤。梅花屿介于两湖之间，四面岩峦，一无所丽，故曰孤也。是地水望澄明，？焉冲照，亭观绣峙，两湖反景，若三山之倒水下。山麓多梅，为林和靖放鹤之地。林逋隐居孤山，宋真宗征之不就，赐号和靖处士。常畜双鹤，豢之樊中。逋每泛小艇，游湖中诸寺，有客来，童子开樊放鹤，纵入云霄，盘旋良久，逋必棹艇遄归，盖以鹤起为客至之验也。临终留绝句曰：“湖外青山对结庐，坟前修竹亦萧疏。茂陵他日求遗稿，犹喜曾无封禅书。”绍兴十六年建四圣延祥观，尽徙诸院刹及士民之墓，独逋墓诏留之，弗徙。至元，杨连真伽发其墓，唯端砚一、玉簪一。明成化十年，郡守李瑞修复之。天启间，有王道士欲于此地种梅千树。云间张侗初太史补《孤山种梅序》。
袁宏道《孤山小记》：
孤山处士，妻梅子鹤，是世间第一种便宜人。我辈只为有了妻子，便惹许多闲事，撇之不得，傍之可厌，如衣败絮行荆棘中，步步牵挂。近日雷峰下有虞僧儒，亦无妻室，殆是孤山后身。所著《溪上落花诗》，虽不知于和靖如何，然一夜得百五十首，可谓迅捷之极。至于食淡参禅，则又加孤山一等矣，何代无奇人哉！
张京元《孤山小记》：
孤山东麓，有亭翼然。和靖故址，今悉编篱插棘。诸巨家规种桑养鱼之利，然亦赖其稍葺亭榭，点缀山容。楚人之弓，何问官与民也。
又《萧照画壁》：
西湖凉堂，绍兴间所构。高宗将临观之。有素壁四堵，高二丈，中贵人促萧照往绘山水。照受命，即乞尚方酒四斗，夜出孤山，每一鼓即饮一斗，尽一斗则一堵已成，而照亦沉醉。
上至，览之叹赏，宣赐金帛。
沈守正《孤山种梅疏》：
西湖之上，葱？亲人，亦爽朗易尽。独孤山盘郁重湖之间，水石草木皆有幽色。唐时楼阁参差，诗歌点缀，冠于两湖。读“不雨山常润，无云水自阴”之句，犹可想见当时。道孤山者，不径西泠，必沿湖水，不似今从望湖折？？而入也。
此地尚有古梅偃蹇，云是和靖故居。
李流芳《题孤山夜月图》：
曾与印持诸兄弟醉后泛小艇，从孤山而归。时月初上新堤，柳枝皆倒影湖中，空明摩荡，如镜中，复如画中。久怀此胸臆，壬子在小筑，忽为孟？写出，真画中矣。
苏轼《书林逋诗后》：
吴侬生长湖山曲，呼吸湖光饮山渌。
不论世外隐君子，佣儿贩妇皆冰玉。
先生可是绝俗人，神清骨冷无由俗。
我不识见曾梦见，瞳子了然光可烛。
遗篇妙字处处有，步绕西湖看不足。
诗如东野不言寒，书似西台差少肉。
平生高节已难继，将死微言犹可录。
自言不作封禅书，更肯悲吟白头曲。
我笑吴人不好事，好作祠堂傍修竹。
不然配食水仙王，一盏寒泉荐秋菊。
张祜《孤山》诗：
楼台耸碧岑，一径入湖心。不雨山常润，无云水自阴。
断桥荒藓合，空院落花深。犹忆西窗月，钟声出北林。
徐渭《孤山玩月》诗：
湖水淡秋空，练色澄初静。倚棹激中流，幽然适吾性。
举酒忽见月，光与波相映。西子拂淡妆，遥岚挂孤镜。
座客本玉姿，照耀几筵莹。暇时吐高怀，四座尽倾听。
却言处士疏，徒抱梅花咏。如以径寸鱼，蹄涔即成泳。
论久兴弥洽，返棹堤逾迥。自顾纵清谈，何嫌麾尘柄。
卓敬《孤山种梅》诗：
风流东阁题诗客，潇洒西湖处士家。
雪冷江深无梦到，自锄明月种梅花。
王稚登《赠林纯卿卜居孤山》诗：
藏书湖上屋三间，松映轩窗竹映关。
引鹤过桥看雪去，送僧归寺带云还。
轻红荔子家千里，疏影梅花水一湾。
和靖高风今已远，后人犹得住孤山。
陈鹤《题孤山林隐君祠》诗：
孤山春欲半，犹及见梅花。笑踏王孙草，闲寻处士家。
尘心莹水镜，野服映山霞。岩壑长如此，荣名岂足夸。
王思任《孤山》诗：
淡水浓山画里开，无船不署好楼台。
春当花月人如戏，烟入湖灯声乱催。
万事贤愚同一醉，百年修短未须哀。
只怜逋老栖孤鹤，寂寞寒篱几树梅。
张岱《补孤山种梅叙》：
盖闻地有高人，品格与山川并重；亭遗古迹，梅花与姓氏俱香。名流虽以代迁，胜事自须人补。在昔西泠逸老，高洁韵同秋水，孤清操比寒梅。疏影横斜，远映西湖清浅；暗香浮动，长陪夜月黄昏。今乃人去山空，依然水流花放。瑶葩洒雪，乱飘冢上苔痕；玉树迷烟，恍堕林间鹤羽。兹来韵友，欲步前贤，补种千梅，重修孤屿。凌寒三友，早连九里松篁；破腊一枝，远谢六桥桃柳。伫想水边半树，点缀冰花；
待将雪后横枝，低昂铁干。美人来自林下，高士卧于山中。白石苍崖，拟筑草亭招放鹤；浓山淡水，闲锄明月种梅花。有志竟成，无约不践。将与罗浮争艳，还期庾岭分香。实为林处士之功臣，亦是苏长公之胜友。吾辈常劳梦想，应有宿缘。
哦曲江诗（曲江张九龄有《庭梅吟》），便见孤芳风韵；读广平赋，尚思铁石心肠。共策灞水之驴，且向断桥踏雪；遥瞻漆园之蝶，群来林墓寻梅。莫负佳期，用追芳躅。
张岱《林和靖墓柱铭》：
云出无心，谁放林间双鹤。
月明有意，即思冢上孤梅。 ', '', '', '', NULL, '', 'indent', 1540912359, '5bd8036bac502e0061074ffc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640397, '书河上亭壁', NULL, 7, 299, 0, 1, '寇准', NULL, 10376, '57be759d5bbb500063188cff', '宋', 'shi', '诗', 'https://baike.baidu.com/item/%E4%B9%A6%E6%B2%B3%E4%B8%8A%E4%BA%AD%E5%A3%81/3936299?fr=aladdin', '', '岸阔樯稀波渺茫，独凭危槛思何长。
萧萧远树疏林外，一半秋山带夕阳。', '《书河上亭壁》北宋诗人寇准创作的一首七言绝句，题写在黄河边一座亭子的壁上，以描写秋天的景色为主。诗前两句写黄河，及因黄河勾起的无边的愁思。诗人用的线条很粗，着眼于大景。三、四句写远处，说萧瑟秋风中，依稀可见一片凋落的树林，林后的山脉，一半浸沉在夕阳照射中。诗构出一个令人愁怨的气氛，描写出令人愁怨的场景，隐括诗人的心情，显得含蓄深致。自然之景与人的感慨紧紧结合，诗境诗意都得到了全面地发挥。', '这是四首（春、夏、秋、冬）组诗中的第三首。诗前有序，说明此诗是作者被贬谪时写的。
河，黄河。
凭，靠。危，高。
萧萧，风声。
危槛：高高的栏杆', '宽阔的黄河，只有不多几条船在航行，眼前是波浪滚滚，一派渺茫。我独自登上河边的亭子，斜靠着栏杆，愁绪像河水，源源不断。那河边、远处，萧瑟秋风中，有片稀疏的树林，林后是耸立的高山，一半沐浴着西斜的阳光。', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea6f12cee9a0c24ed46f8", "shortContent": "原诗题很长，因此一般选本都截其末句为题，这里也沿用。不过，从原诗题中，可以窥见诗人作诗的经过，因照录如下：“予顷从穰下移莅河阳，洎出中书，复领分陕。惟兹二镇，俯接洛都，皆山河襟带之地也。每凭高极望，思以诗句状其物景，久而方成四绝句，书于河上亭壁。”“穰下移莅河阳”，是指诗人由参知政事之职，于至道二年（996）罢知邓州（即“穰”，治所在今河南邓州市），咸平初徙河阳（治所在今河南孟州市西）。“分陕”是...", "authors": ["周慧珍"], "pressName": "上海辞书出版社"}]', '', 'center', 1541087617, '5bdab1209f54540066cb97fe', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640398, '黄河夜泊', NULL, 0, 378, 0, 1, '李流芳', NULL, 15240, '5858e9e1ac502e0067085d8e', '明', 'shi', '诗', 'https://baike.baidu.com/item/%E9%BB%84%E6%B2%B3%E5%A4%9C%E6%B3%8A/2969923?fr=aladdin', '', '明月黄河夜，寒沙似战场。
奔流聒地响，平野到天荒。
吴会书难达，燕台路正长。
男儿少为客，不辨是他乡。', '《黄河夜泊》是明代文学家李流芳所作的一首五言律诗，这首诗写作者漂泊他乡，夜宿时所看到黄河边凄凉的景象，发出一生漂泊已久的伤感。全诗质朴简练、浅近率直，耐人咀嚼。这首诗抒发了作者久客异乡、仕途艰难的惆怅与感伤。', '寒沙：寒冷的沙滩。
聒：声音嘈杂，使人厌烦。
平野：平坦的旷野。
天荒：极言空间无尽或历时久远。
吴会：吴地的会稽，即作者故乡。
燕台：指燕京，今北京。明朝的京城。', '月光下黄河横躺，月光下战场似的黄沙漫漫。
轰隆隆的奔流翻腾不息，荒野伸向无尽的远方。
书信难寄遥远的会稽，去燕台的路啊还很漫长。
我这样长年的四处漂泊，竟再也不觉得是客居他乡。', NULL, '中国作家协会会员吕晴飞《中国历代名诗今译》：“这首诗是作者会试途中所作，虽写游子旅夜的感受，却不作悲声，颇为难得。”', 'center', 1541087722, '5bdab18a808ca400665a1984', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640399, '黄河泛舟', NULL, 0, 3, 0, 1, '罗元琦', NULL, 26419, '5858f428ac502e006708b1ec', '清', 'shi', '诗', '', '', '洪波舣楫泛中流，凫淑鸥汀揽胜游。
数点渔舟歌欸乃，诗情恍在白苹洲。 ', '', '这首诗选自《乾隆中卫县志》。黄河泛舟，中卫知县黄恩锡设置的中卫十二景之一。
舣：停在岸边的船。楫：划船。
凫淑：野鸭在清澈的水边。淑，美好。鸥汀：水鸟在水边的平地上。
欸乃：象声词，形容摇橹声。这里指渔歌。
白苹洲：长满了白色苹草花的水中滩地。白苹，俗名田字草，夏秋开小白花。 ', '', NULL, '', 'center', 1541087802, '5bdab1d8808ca400665a20ff', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640400, '渡黄河', NULL, 0, 7, 0, 1, '范雲', NULL, 35910, '5858fce4570c350069185f20', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E6%B8%A1%E9%BB%84%E6%B2%B3/8689?fr=aladdin', '', '河流迅且浊，汤汤不可陵。
桧楫难为榜，松舟才自胜。
空庭偃旧木，荒畴余故塍。
不睹行人迹，但见狐兔兴。
寄言河上老，此水何当澄？', '《渡黄河》是南朝诗人范云创作的一首五言古诗。这首诗首四句先写出了黄河的气势和特征，再写河水汹猛，渡河十分艰险；中间四句写岸畔所见，先写乡村庭户空旷，田地荒芜，再写人走屋空，只见狐兔横行一片荒凉；末两句写内心的感慨、痛苦和愿望。这首诗笔力劲健，描写真实，又运用典故，寄寓了诗人澄清天下之志。', '迅：疾速，急疾。
汤汤（shāng）：水势浩大貌。陵：超越，越过。
桧（guì）楫：桧木做的桨。桧为坚硬木材，桧楫谓船桨极坚固。榜（bǎng）：船桨。
胜：胜任，担当。《诗经·卫风·竹竿》：“淇水溜漶，桧楫松舟。”
空庭：犹空院，谓荒芜冷寂的庭院。偃：倒伏。
故塍（chéng）：过去的田埂。
兴：作，这里指狐兔奔跑。
河上老：河上老：古时高士，即河上公，能预测未来。葛洪《神仙传》：“河上公者，莫知其姓字。汉文帝时，公结草为庵于河之滨。帝读《老子经》颇好之……有所不解数事，时人莫能道之，闻时皆称河上公解《老子经》义旨，乃使赍所不决之事以问。”
何：何时。澄：清。传说黄河千年一清，河清则天下太平。', '黄河流水湍急而且浑浊，其盛大的水势不可阻挡。
用桧木做成的桨，船夫也难以使用，松木造成的坚船方可胜任。
空院落倒放着旧木头，荒地里留着旧土埂。
这里不见行人的踪迹，所见的只有狐狸兔子的出没。
我要对黄河边上的老人说，这浊水相当澄清了。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccc55914587d02f59a19", "shortContent": "此诗当为作者永明十年（492）出使北魏途中作。黄河在北魏境内，时魏都在平城（今山西大同），故须渡河北上。\n前四句写渡河情况。“河流迅且浊，汤汤不可陵。”起笔写出了黄河的气势和特征：水流迅猛而浑浊。“汤汤”，水势浩大。“不可陵”，不可超越，极言渡河之难。“桧楫难为榜，松舟才自胜。”“桧楫”，桧树做的桨。桧和松都是坚硬的木材，常用来制造船桨，《诗经·卫风·竹竿》有“淇水滺滺，桧楫松舟”的句子。这里说，...", "authors": ["汤华泉"], "pressName": "上海辞书出版社"}]', '广西师范大学中文系教授周满江，胡光舟《中国历代名诗分类大典》：这首诗描绘了黄河的冲决千里。河水泛滥，毁坏了田地庐舍，给人民带来了深重灾难。真实地反映了黄河的面貌，表现了诗人对受灾人民的同情，以及盼望黄河澄清的美好理想。', 'center', 1541087854, '5bdab20c808ca400665a273f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640453, '真珠帘', NULL, 0, 3, 0, 1, '徐某', NULL, 29866, '5858f760570c350069182e87', '宋', 'ci', '词', '', '', '落红几阵清明雨。忆花期、半被睛慳寒阻。新柳着春浓，早翠池波妒。粉雨香去消息远，温旧日、秋千庭宇。凝伫。正春醒帘外，一声莺语。
尘锁宝筝弦柱。自眉峰惹恨。六么慵舞。深院不成妆，有泪弹谁与。记得踏青归去后，细共说、花阴深处。心愫。怕当时飞燕，知人分付。 ', '', '', '', NULL, '', 'indent', 1541694710, '5be3f497fb4ffe0069c0bf0f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640401, '黄河行', NULL, 1, 1, 0, 1, '贡泰父', NULL, 36964, '5bdab2547565710067201c59', '元', 'shi', '诗', '', '', '黄河水，水阔无边深无底，其来不知几千里。
或云昆仑之山出西纪，元气融结自兹始。
地维崩兮天柱折，于是横奔逆激日夜流不已。
九功歌成四载止，黄熊化作苍龙尾。
双谼凿断海门开，两鄂崭崭尚中峙。
盘涡荡激，回湍冲射，悬崖飞沙，断岸决石，瞬息而争靡。
洪涛巨浪相豗，怒声不住从天来。
初如两军战方合，飞炮忽下坚壁摧。
又如丰隆起行雨，鞭笞铁骑驱奔雷。
半空澎湃落银屋，势连渤澥吞淮渎。
天吴九首兮，魌魋独足。
潜潭雨过老蛟吟，明月夜照鲛人哭。
扁舟侧挂帆一幅，满耳萧萧鸟飞速。
徐邳千里半日程，转盼青山小如粟。
吁嗟雄哉！其水一石，其泥数斗。
滔滔汩汩兮，同宇宙之悠久。
泛中流以击楫兮，招群仙而挥手。
好风兮东来，酬河伯兮杯酒。 ', '', '这首诗选自《乾隆宁夏府志》。
纪：基也，基址。
元气：指天地未分前混一之气。
地维：古时以为大地四方，四角有大縆（粗绳）维系，故称地维。天柱：古人相传，天有八柱承之，故称天柱（《山海经·神异经》）。
九功：九职之功。《周礼·天官·太宰》：“以九职任万民。”包括三农、园圃、虞衡、薮牧、百工、商贾、嫔妇、臣妾、闲氏。四载：古时的四种交通工具。《书·益稷》：“予乘四载。”谓禹治水时，水行乘舟，陆行乘车、泥行承輴，山行乘樏。
“黄熊”句：指鲧、禹治水事。相传鲧被天帝所诛后，化为黄熊，入于羽渊。其子禹治洪水时，有神龙以尾画地导水所注。
谼：大谷。海门：通向海的大门。
鄂：边际。崭崭：突出貌。
争靡：形容两岸碎石土块被河水冲刷，争相坍塌。靡，倒下。
豗：撞击。
丰隆：古代神话中的云神。一说雷神。
渤澥：古代称东海的一部分，即渤海。淮渎：淮河。
天吴：古代传水中的水神。九首：《道光中卫县志》（标点注释本）作：“八首”。
魌魋：大禹化作熊，凿山开路，驱逐鬼神。魌，即魌头，古时打鬼驱疫时用的面具。魋，兽名，似小熊，喻大禹。
鲛人：传说中的人鱼。
徐邳：黄河下游经徐州、邳州。
汩汩：水流声；急流貌。
酬：报谢。河伯：古代神话中的黄河水神，名冯夷。 ', '', NULL, '', 'center', 1541087963, '5bdab2797565710067201e52', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640402, '春别曲', NULL, 4, 444, 0, 1, '张籍', NULL, 10134, '57b9c2fd7db2a20068bebb37', '唐', 'shi', '诗', 'https://baike.baidu.com/item/%E6%98%A5%E5%88%AB%E6%9B%B2/4123585?fr=aladdin', '', '长江春水绿堪染，莲叶出水大如钱。
江头橘树君自种，那不长系木兰船。', '《春别曲》是唐代诗人张籍的作品，这首诗完全仿民歌写成，十分生动有趣、轻松自然。平实通俗的语言风格，看不到什么生涩难通的词句，也看不到什么深奥难解的典故，平平道来，语意贯通。', '堪：能，可
钱：指铜钱。初生的小荷叶，状如铜钱，又被称为“荷钱”。
木兰船：常用为船的美称，并非实指木兰树所制。', '长江中春水碧绿，颜色浓得简直可以作为染料，荷叶刚刚长出水面，一个个才有铜钱那么大。亲爱的朋友啊，你看江头的那棵橘树，还是你当年亲手种下的，能不能用它拴住你这就要远去的小船，和你永不分别？', NULL, '', 'center', 1541089535, '5bdab89f9f545400663e0c8b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640403, '六么令 · 次韵和贺方回金陵怀古鄱阳席上作', NULL, 4, 1659, 1, 2, '李纲', NULL, 28019, '5858f5ad128fe1006b884764', '宋', 'ci', '词', '', '', '长江千里，烟淡水云阔。歌沉玉树，古寺空有疏钟发。六代兴亡如梦，苒苒惊时月。兵戈凌灭。豪华销尽，几见银蟾自圆缺。
潮落潮生波渺，江树森如发。谁念迁客归来，老大伤名节。纵使岁寒途远，此志应难夺。高楼谁设。倚阑凝望，独立渔翁满江雪。 ', '', '', '', '[{"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5d403572034f65a8bb0", "shortContent": "作为一个政治家和军事家，李纲的抗金立场从未动摇过，是最坚定的主战派代表之一。唯其如此，他随着朝中战与和两种气氛、两种势力的消与长，而在宦海中升沉起落，变化无常。曾位至宰相，更屡为迁客，历尽荣辱，饱经忧患。发之为诗文，自然多感慨身世、怀古伤今和即物明志之作，磊落光明，雄深雅健，非一般文士可及。此词大约作于南渡初期的被贬途中，借金陵怀古之题，抒抗战报国之志。和贺铸韵。贺词今不存。\n上片集中笔墨写金陵怀...", "authors": ["谢楚发"], "pressName": "上海辞书出版社"}]', '', 'indent', 1541089643, '5bdab90afb4ffe005d20f3bf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640406, '秋霁（西湖十咏 · 平湖秋月）', NULL, 0, 351, 0, 1, '陈允平', NULL, 10437, '582c71d1570c35006ce955c9', '宋', 'ci', '词', '', '', '千顷玻璃，远送目斜阳，渐下林阗。题叶人归，采菱舟散，望中水天一色。碾空桂魄。玉绳低转云无迹。有素鸥，闲伴夜深，呼棹过环碧。
相思万里，顿隔婵媛，几回琼台，同驻鸾翼。对西风、凭谁问取，人间那得有今夕。应笑广寒宫殿窄。露冷烟淡，还看数点残星，两行新雁，倚楼横笛。 ', '', '', '', NULL, '', 'indent', 1541175567, '5bdc08a6ac502e00622475f0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640409, '太常引 · 乐府小云', NULL, 0, 155, 0, 1, '张可久', NULL, 10298, '57b9aeef79bc4400639bd1fc', '元', 'ci', '词', 'https://baike.baidu.com/item/%E5%A4%AA%E5%B8%B8%E5%BC%95%E4%B9%90%E5%BA%9C%E5%B0%8F%E4%BA%91/16989785?fr=aladdin', '', '溶溶一叶不成衣。恰待弄春晖。幽懒意迟迟。只可向、山中自怡。清歌遏玉，娇鬟*翠，纤月映蛾眉。来往且孤飞。问行雨、巫咸未知。', '', '', '', NULL, '', 'indent', 1541177013, '5bdc0e549f545400665209af', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640410, '太常引 · 黄山西楼', NULL, 0, 155, 0, 1, '张可久', NULL, 10298, '57b9aeef79bc4400639bd1fc', '元', 'ci', '词', '', '', '黄岩秋色雨频频。楼上着闲身。凉意逼羊裙。更添得、砧声耳根。寒香吹桂，暗苞绽橘，红日晓窗温。客至莫论文。只坐守、方山看云。 ', '', '', '', NULL, '', 'indent', 1541177056, '5bdc0e81fb4ffe005d34d37f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640411, '太常引 · 永嘉林熙翁城南旧院', NULL, 0, 155, 0, 1, '张可久', NULL, 10298, '57b9aeef79bc4400639bd1fc', '元', 'ci', '词', 'https://baike.baidu.com/item/%E5%A4%AA%E5%B8%B8%E5%BC%95%E6%B0%B8%E5%98%89%E6%9E%97%E7%86%99%E7%BF%81%E5%9F%8E%E5%8D%97%E6%97%A7%E9%99%A2/17024318', '', '霖铃秋雨打空阶。人坐益清齐。门掩小蓬莱。怕有客、寻真到来。楼头碧远，山眉青小，口树挂苍苔。且莫写离怀。看隔水、芙蓉正开。', '', '', '', NULL, '', 'indent', 1541177103, '5bdc0ea9fb4ffe005d34d828', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640416, '摊破浣溪沙 · 五里滩头风欲平', NULL, 2, 377, 0, 1, '无名氏', NULL, 10156, '57b9dc73a633bd005d303896', '唐', 'ci', '词', '', '', '五里滩头风欲平，张帆举棹觉船轻。柔橹不施停却棹，是船行。
满眼风波多闪灼，看山却似走来迎。仔细看山山不动，是船行。', '这首词它是较为特别的。它喜欢用口语，思想新颖，调子轻快，读起来满有船夫曲的味道。因为，它是一首唐代的民间词。它的作者是谁？现在已经无法知道了。甚至这篇作品也差不多失传了近九百年，直到驰名中外的甘肃敦煌莫高窟藏经洞在1899年或1900年被打开，人们才有机会读到它。', '五里滩头：原作“五两竿头”，“五里”应为“五量”，即“五两”。
闪烁：原作“陕汋”，音近而误。', '这是一首反映船夫水上生活的抒情小词，它写的是狂风过后船夫们驾驶帆船前进的情景和心情。
词一开头就说”五里滩头风欲平，张帆举棹觉船轻”。五里滩，是这条河上的一个地名，“头”是方位词，它说明船已开到五里滩上了。帆船是需要借助风力的，乘风破浪，船走得更快。但这种风必须是顺风。如果吹来的风是旋风，或逆风，那就不但不能帮助帆船前进，而且还会带来危险，所以是不能张帆的。在五里滩以前，船夫们遇到的显然不是顺风。他们经过一场和狂风恶浪的搏斗以后，观察到风势将要平息，也就是“风欲平”了，就马上扯起帆来。在这个当儿，大家虽然还在继续举棹摇般，却产生了“觉船轻”的感觉。“棹”，桨板，举棹就是打桨板。既然风力可以代替人力，何必还要打桨摇橹呢，于是，便“柔橹不施停却棹”吧。在文学作品中常把橹称为柔橹，以形容橹的得心应手。橹的外形有点儿象桨，安在船梢或船旁，用人摇动，它会象鱼的尾和鳍一样，通过拨水，产主推动力。“施”，使用。写到这里，船夫们的轻松愉快的感情，一下就传达出来了。
在紧张的劳动过程中，是没有空闲时间来欣赏船外的美景的，但在劳动之余，船夫们不仅轻松，而且欢快，词的下片就是通过看山看水反映了他们的心情。“满眼风波多闪灼，看山却似走来迎。”“闪灼”，形容水光闪动的样子。狂风过后，乌云也散开了，上文说“风欲平”，是还有些风，所以河里的波浪涌起，波光粼粼。这时两岸的山呐，看上去挺有趣过的，它们似乎很好客，正在急急忙忙地迎面走过来欢迎大家。但是，山是不会走动的。子细（仔细）看看，山确实没有动啊。那么，这是怎么一回事呢？哦，那不过是因为船走得快，使得坐在船上的人产生一种“走来迎”的感觉罢了。
词的上片和下片的末尾都用“是船行”作结束，它不仅起一个叙述作用，而且还象船夫的劳动号子的和声一样，余音袅袅[niǎo]，久久回荡在青山绿水之间。', NULL, '', 'indent', 1541434897, '5bdffdb167f356006219d325', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640459, '贺圣朝 · 送春', NULL, 0, 193, 0, 2, '陈家庆', NULL, 22765, '5858f09a128fe1006dcc7486', '清', 'ci', '词', '', '', '二分春色都辞树。剩一分风雨。征衫检点最消魂，看泪花红处。
幽情难问，归期细数。祗满怀离绪。天涯谁解惜芳菲，任东皇来去。
', '', '', '', NULL, '', 'indent', 1541781338, '5be546effb4ffe0069d2725c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640460, '贺圣朝', NULL, 0, 193, 0, 1, '陈家庆', NULL, 22765, '5858f09a128fe1006dcc7486', '清', 'ci', '词', '', '', '画屏几点江南树。织丝丝微雨。西楼聊共燕徘徊，望晚云深处。
楚兰描出，乱愁无数。系悠悠情绪。子规犹自两三声，道不如归去。', '', '', '', NULL, '', 'indent', 1541781373, '5be5471f9f54540070f1efb2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640461, '贺圣朝 · 留春', NULL, 0, 199, 0, 1, '俞彦', NULL, 10392, '57e63aaf128fe1005702b6d8', '明', 'ci', '词', '', '', '东皇听我多珍重。莫便思飞轻。得得难来，频频要去，匆匆如梦。
梨花欲吐香魂动。待一杯相共。可能张主，免教佳节，雨摧风送。
', '', '', '', NULL, '', 'indent', 1541781673, '5be547f867f3560062ea00ca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640462, '贺圣朝', NULL, 0, 80, 0, 1, '杜安世', NULL, 10341, '57c3a535c4c9710061929134', '宋', 'ci', '词', '', '', '东君造物无凝滞。芳容相替。杏花桃萼一时开，就中明媚。
绿丛金朵，枝长叶细。称花王相待。万般堪爱，暂时见了，断肠无计。 ', '', '', '', NULL, '', 'indent', 1541781732, '5be548869f54540070d85322', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640417, '摊破浣溪沙', NULL, 0, 149, 0, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '相恨相思一个人。柳眉桃脸自然春。别离情思，寂寞向谁论。映地残霞红照水，断魂芳草碧连云。水边楼上，回首倚黄昏。 ', '', '', '', '[{"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典", "articleId": "60d8a6743bacb94d0b73307e", "shortContent": "这首词是一位未留名姓的作者用篦刀刻在蔡州（今河南汝南）瓜陂铺的青泥壁上的。大约是词中流露的真情实感引起了许多过往墨客骚人的共鸣吧，宋人吴曾据友人所述收录在他的《能改斋漫录》之中，使它流传了下来。\n词的上片是追忆与爱人别离时的情景。香罗帕，一般是男女定情时馈赠的信物，现在将它剪碎来揩拭离人的眼泪，真是悲痛之极。从“剪碎香罗”这种决绝的举动看来，这番别离不是暂时的分手，而是带有诀别的性质，所以非用如此...", "authors": ["程中原"], "pressName": "上海辞书出版社"}, {"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典", "articleId": "60fc06671941966574a355e9", "shortContent": "这首词由一位未留名姓的作者用篦刀刻在蔡州（今河南汝南）瓜陂铺的青泥壁上。大约是词中流露的真情实感引起了许多过往墨客骚人的共鸣吧，宋人吴曾据友人所述收录在他的《能改斋漫录》之中，使它流传了下来。\n词的上片是追忆与爱人别离时的情景。香罗帕，一般是男女定情时馈赠的信物，现在将它剪碎来揩拭离人的眼泪，真是悲痛之极。从“剪碎香罗”这种决绝的举动看来，这番别离不是暂时的分手，而是带有诀别的性质，所以非用如此强...", "authors": ["程中原"], "pressName": "上海辞书出版社"}]', '', 'indent', 1541435237, '5bdfff0667f35600621a077c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640418, '婆罗门引 · 春情', NULL, 0, 34, 0, 1, '严仁', NULL, 10210, '57d02f438ac2470062e1779b', '宋', 'ci', '词', '', '', '花明柳暗，一天春色绕朱楼。断鸿声唤人愁。欲问归鸿何处，身世自悠悠。正东风留滞，楚尾吴头。追思旧游。叹双鬓、飒惊秋。可惜等间孤了，酒令花筹。断弦难续，谩题诗、分付水东流。流不到、蓬岛瀛洲。 ', '', '', '', NULL, '', 'indent', 1541436962, '5be005c3ee920a0066107722', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640419, '婆罗门引 · 寄袁箨庵用稼轩韵', NULL, 1, 324, 0, 1, '王士禛', NULL, 19251, '5858ed641b69e60056f64c4d', '清', 'ci', '词', '', '', '问平安否，金陵南去楚云西。望中烟草迷离。回首红桥分赋，笔掣翠虹蜺。
叹青门一别，白社人稀。
诗狂酒悲。老大去、几人知。往日荆州作牧，吊古题诗。
周郎已矣，忆风流、顾曲似当时。归来也、两鬓千丝。
', '', '', '', NULL, '', 'indent', 1541437079, '5be0062f7565710068b53f69', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640420, '婆罗门引 · 髻鬟对耸', NULL, 0, 351, 0, 1, '陈允平', NULL, 10437, '582c71d1570c35006ce955c9', '宋', 'ci', '词', '', '', '髻鬟对耸，万松扶玉上青冥。西风共倚，烟南水北，石荒苔老，三十六梯平。爱翠尖如削，天外亭亭。高寒梦惊。是何夕堕双星。无限苍崖紫岫，谁拊棱层。薜萝深处，算少年、游屐几番登。河汉近、疑在蓬瀛。 ', '', '', '', NULL, '', 'indent', 1541437246, '5be006c89f54540070aef955', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640421, '婆罗门引 · 江上晚泊望月', NULL, 0, 697, 0, 1, '宋褧', NULL, 10761, '5858e5d1128fe1006dcc1d8b', '元', 'ci', '词', '', '', '短衣乌帽，京尘眯目强钻头。梦中八表神游。今日江山佳处，便欲贾胡留。
爱峰岚滴翠，天水涵秋。
断霞渐收。见隐隐、两蛾愁。好在九华烟树，秋浦沙鸥。
相看依旧，但憔悴、潘郎俗状羞。孤负却、笑傲林丘。
', '', '', '', NULL, '', 'indent', 1541437762, '5be008e24773f70066f65ebc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640422, '婆罗门引 · 题露筋祠', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '露筋祠下，寒篷淼淼去何之。停桡一问灵旗。怊怅千年古庙，陈迹几人悲。
只风前燕子，雨后棠梨。
俯仰歔欷，凭吊处，更怜谁。惟有淮阴漂母，一样蛾眉。
估船争泊，问何人、拂藓一题诗。依稀见、玉佩珠衣。
', '', '', '', NULL, '', 'indent', 1541437804, '5be0090d9f54540070af1fad', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640423, '婆罗门引 · 香橼', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '晚风千颗，累累才与画檐平。绽来刚趁秋晴。怪底匀圆如许，青女手搓成。
乍回廊小摘，冷韵旋生。
冰瓷翠罂，压叠在、小红檠。弄影夕阳黄处，檀晕偏明。
空香如雨，最宜人、昨夜恰微酲。何须数、西崦霜橙。
', '', '', '', NULL, '', 'indent', 1541438108, '5be009e04773f70066f670e7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640424, '婆罗门引', NULL, 0, 82, 0, 1, '苏穆', NULL, 26423, '5858f4291b69e60056f682c2', '清', 'ci', '词', '', '', '西风过后，更无落叶作秋声。锦机偏动幽情。万里天涯路窄，何处月长盈。
叹沧波一片，轻换阴晴。
凝眸短檠。浑未辨、旧时明。况又潇潇细雨，遥夜争鸣。
繁华梦久，怕相将、都付与云屏。愁玉女、立尽残更。
', '', '', '', NULL, '', 'indent', 1541438055, '5be00a079f5454007095900e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640425, '婆罗门引 · 重阳与元帅窦子温暨众友东城赏菊即席赋', NULL, 0, 891, 0, 1, '李俊民', NULL, 10838, '5858e5e38e450a006c7f7cd2', '元', 'ci', '词', '', '', '浮空霁色，江涵秋影雁初飞。相逢共绕东篱。点检樽前见在，人似晓星稀。
对满山红树，叶叶堪题。
大家露顶。任短发、被风吹。只恐黄花人貌，不似年时。
杯添野水，更何用、频频望白衣。沉醉后、携手方归。
', '', '', '', NULL, '', 'indent', 1541438227, '5be00ab3ee920a006610cc0f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640426, '人月圆 · 雪中游虎丘', NULL, 1, 155, 1, 1, '张可久', NULL, 10298, '57b9aeef79bc4400639bd1fc', '元', 'qu', '曲', 'https://baike.baidu.com/item/%E4%BA%BA%E6%9C%88%E5%9C%86%C2%B7%E9%9B%AA%E4%B8%AD%E6%B8%B8%E8%99%8E%E4%B8%98/8477034?fr=aladdin', '', '梅花浑似真真面，留我倚阑杆。雪晴天气，松腰玉瘦，泉眼冰寒。兴亡遗恨，一丘黄土，千古青山。老僧同醉，残碑休打，宝剑羞看。', '《人月圆·雪中游虎丘》是元代张可久所写的一首散曲。这是一首记游的欺曲。在记实中抒发了自己的感慨。表达了自己对国事和人生的看法。作者由美丽的如同传说中的真真一样的梅花起兴，将眼前的景物与过去的史实联系起来，表达了自己对历代先贤的追思，对兴亡遗恨的痛楚，对壮志难酬的悲愤。', '雪中游虎丘：虎丘，山名，在今苏州市郊。
浑似：简直象。
真真面：谓美女之面容。
一丘黄土，千古青山：黄土，虎丘传为吴王圈闯葬处，故云。青山，这里指虎丘。
残碑休打：残碑，残留之碑，打，拓碑文。旧时有人以拓碑文为生，所拓碑纸售于市。
宝剑羞看：羞于去看宝剑，对不能奋发的内疚。按《吴越春秋·阖闾内传》，吴王阖闾有干将、莫耶、湛卢等宝剑。这句暗用此典。', '雪后的梅花红润娇艳仿佛仙女真真姣好的脸面，吸引我凭依着栏杆久久流连，雪后初晴的天气，松树的腰显得细瘦而泉眼的冰面特别清寒。历史兴盛衰亡留下了深深的遗憾，闺闾当年曾经是纵横天下的荚雄，如今只留下一个大大的黄土坟丘。而千古不变的是苍翠的青山，为我导游的老和尚也被美景所陶醉，就不要再去观赏拍打残破的古碑，去欣赏那一湾绿水的剑池的景观。', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2990f8fda556505fff2", "shortContent": "虎丘山在今苏州西北郊，是江南名胜之一。相传春秋吴王阖闾葬此，三日而虎踞其上，因称之为虎丘。此曲通过写雪中虎丘胜景而发兴亡遗恨和文人失意、壮志难酬的羞愧悲怨之情。\n全曲可分三层。开头五句写冬季虎丘的动人景色，是第一层。首二句用拟人写梅花，说梅花真像美女真真的容貌一样迷人，多情地顾盼、挽留着我倚靠阑杆观赏。真真，典出《太平广记·画工》，云唐代进士赵颜得一美女图，甚喜。画工告诉他：此女叫真真，若昼夜呼其...", "authors": ["熊笃"], "pressName": "上海辞书出版社"}, {"bookId": "6277bbb9f716b7243c7bdff3", "bookTitle": "元曲鉴赏辞典", "articleId": "63126ed877683d1933015141", "shortContent": "虎丘，在今江苏苏州的西北，有剑池、梅树等景观。相传春秋吴王阖闾死后就葬在此地，经三日，白虎踞其上，故称之为虎丘。作者游虎丘，自然免不了怀古伤今，此曲就是通过写雪中游虎丘所见之景，抒发了兴亡无常、壮志难酬的悲怨。\n作者首先向我们介绍了雪中虎丘的美景。雪中的虎丘，梅花开得正艳，这里作者别具一格以人拟物，将梅花比作美女真真。《太平广记·画工》中记载了这么一个故事：唐代进士赵颜得到一幅美女图，非常喜爱。画...", "authors": ["李霓虹"], "pressName": "崇文书局"}]', '中国古代韵文专家熊笃：此曲章法谨严，写雪中游虎丘所见、所感、所叹，分别对应触景、怀古、伤今。用典较多而恰到好处，遣词考究而清丽自然。写景中比拟尤妙，以美人拟梅，以腰、眼人体器官部位拟松、泉，皆各臻其妙，生动传神。其炼字炼意，诚如李开先《张小山乐府序》所说，达到“瘦至骨立，血肉销化俱尽，乃炼成万转金铁躯。”', 'indent', 1541517501, '5be1405d9f54540070bf766a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640463, '贺圣朝', NULL, 0, 80, 0, 1, '杜安世', NULL, 10341, '57c3a535c4c9710061929134', '宋', 'ci', '词', '', '', '牡丹盛拆春将暮。群芳羞妒。几时流落在人间，半间仙露。
馨香艳冶，吟看醉赏，叹谁能留住。莫辞持烛夜深深，怨等闲风雨。', '', '', '', NULL, '', 'indent', 1541781762, '5be548a4fb4ffe0069d28f99', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640427, '人月圆 · 为细君寿', NULL, 0, 263, 0, 1, '魏初', NULL, 11641, '5858e6a9b123db00658d7fc8', '元', 'qu', '曲', 'https://baike.baidu.com/item/%E4%BA%BA%E6%9C%88%E5%9C%86%C2%B7%E4%B8%BA%E7%BB%86%E5%90%9B%E5%AF%BF/7133992?fr=aladdin', '', '冷云冻雪褒斜路，泥滑似登天。年来又到，吴头楚尾，风雨江船。但教康健，心头过得，莫论无钱。从今只望，儿婚女嫁，鸡犬山田。', '《人月圆·为细君寿》是元代散曲家魏初所写的一首散曲。此曲是作者为妻子的生日所写的一首祝寿之作。前几句向夫人诉说奔波在外的艰辛，暗喻仕途的险恶。后几句则是对夫人生日的良好祝愿，表达了自己的人生态度。全曲直抒胸臆，语言质朴，充满亲切感，表达了作者对功名利禄的厌倦情绪。', '人月圆：曲牌名。此词调始于王诜，因其词中“人月圆时”句，取以为名。
细君：特指妾。
褒斜路：古道路名。因取道褒水、斜水二河谷得名。
吴头楚尾：指古豫章一带。因位于吴地长江的上游，楚地长江的下游而得名。', '你在褒斜古道上冒着冰冷的大雪行走，地上泥泞湿滑走起来如同登天一样艰难。过了一年才到了吴头楚尾的江西豫章，一路上乘坐江船历经风雨。只希望你身体健康，对不平之事心里能过得去，不抱怨自己没有足够的钱。从今往后，只希望自己的儿女能过上温饱的山村林园生活就可以了。', NULL, '岭南大学中文系助理教授司徒秀英：此曲纯用浅显语，展示的是真实的生活，真实的心态，真挚的感情，其知足常乐的人生态度得到鲜明的表现。（《元曲鉴赏辞典》）', 'indent', 1541517565, '5be1409e8d6d81005eba5a71', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640428, '人月圆 · 吴门怀古', NULL, 0, 155, 0, 1, '张可久', NULL, 10298, '57b9aeef79bc4400639bd1fc', '元', 'qu', '曲', 'https://baike.baidu.com/item/%E4%BA%BA%E6%9C%88%E5%9C%86%C2%B7%E5%90%B4%E9%97%A8%E6%80%80%E5%8F%A4/1335985?fr=aladdin', '', '版本一
山藏白虎云藏寺，池上老梅枝。洞庭归兴，香柑红树，鲈鲙银丝。白家池馆，吴宫花草，可似当时。最怜人处，啼乌夜月，犹怨西施。
版本二
山藏白虎云藏寺，池上老梅枝。洞庭归兴，香柑红树，鲈脍银丝。白家池馆，吴王花草，长似坡诗。可人怜处，啼乌夜月，犹怨西施。
版本三
山藏白虎云藏寺，池上老梅枝。洞庭归兴，香柑红树，鲈鲙银丝。白家池馆，吴王花草，长似坡诗。可人怜处，啼乌夜月，犹怨西施。', '《人月圆·吴门怀古》是元朝散曲家张可久所创作的一曲小令。', '吴门：指苏州。
山：指虎丘山，苏州城西北七里。
池：指剑池。
洞庭归兴：借用范蠡功成隐退之典，后人常用此事称道鄙薄名利的品格。洞庭：指苏州西南太湖中的洞庭山。
香柑红树：作者由四时果鲜的太湖洞庭而想到尤为出名的洞庭红橘，又由红橘追忆了三国时陆绩怀橘归遗其母的典故。香柑：橘子，洞庭山的名产。
鲈（lú）鲙（kuài）银丝：用晋人张翰之典。《晋书·张翰传》载：“翰因见秋风起，乃思吴中菰菜、莼羹、鲈鱼脍，曰：‘人生贵得适志，何能羁宦数千里，以要名爵乎？’遂命驾而归。”鲈鲙：苏州名菜，把鲈鱼切成片生吃。
白家：指白居易。他在唐敬宗宝历元年曾任苏州刺史，历时一年多。
吴宫：指吴王夫差为西施扩建的宫殿，叫馆娃宫。
怜人：令人可怜。', '相传这座高山因隐藏一只白虎而得名，虎丘寺淹没在这高山密林之中。池水旁和山崖上长满了桠权苍老的梅树。望着眼前虎丘山的美景，不禁想起了当年范蠡功成归隐泛舟太湖之行；仿佛看到了陆续怀揣红桔从枫林归来赠母的情景；似乎听到了张翰不图名爵而起驾回乡欲吃鲈鱼细丝的命令。
伴着思绪观赏着美景，又仿佛出现在白居易的池馆前、吴王的姑苏台边，似乎听到东坡仍在长吟虎丘美景。就在这美妙的遐思中，耳畔又仿佛传来了乌鸦在月夜中的哀鸣，这声声凄惨的啼叫，莫不是西施发出的亡吴之恨的哀声。', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2990ce818559d06362f", "shortContent": "这是一首在吴门写的怀古曲。吴门就是苏州，春秋时代吴国曾在这里建都，故名。但曲的内容并不全是怀古，也夹杂着作者向往归隐的思想。\n开头两句，描写虎丘景物。“山藏白虎”，包含着一个关于虎丘来历的故事。相传：吴王阖闾死后葬在山下，经三日，“白虎蹲踞其上，故名虎丘”（见《越绝书》）。“云藏寺”，说的是虎丘山寺的风光。虎丘山上有一座禅寺，唐时改名报恩，宋时改名云岩（后来康熙又改名虎阜），但一般人都叫它作虎丘寺...", "authors": ["洪柏昭"], "pressName": "上海辞书出版社"}, {"bookId": "62de2d8a3bba5677642ac2d1", "bookTitle": "元曲三百首", "articleId": "630593d3eebf5e0fdea511f2", "shortContent": "这是一首在吴门写的怀古曲。吴门就是苏州，春秋时代吴国曾在这里建都，故名。但曲的内容并不全是怀古，也夹杂着作者向往归隐的思想。\n\n开头两句，描写虎丘景物。“山藏白虎”，包含着一个关于虎丘来历的故事。相传吴王阖闾死后葬在山下，经三日，“白虎蹲踞其上，故名虎丘”（见《越绝书》）。“云藏寺”，说的是虎丘山寺的风光。虎丘山上有一座禅寺，唐时改名报恩，宋时改名云岩（后来康熙又改名虎阜），但一般人都叫它做虎丘寺...", "authors": ["洪柏昭"], "pressName": "上海辞书出版社"}]', '全国中学语文研究会教学改革研究中心研究员国庆波《古典诗词曲阅读与鉴赏》：“曲中所写人物虽多，但主次分明，感情丰富，又寓情于景，是一首情景俱佳的曲作。”', 'indent', 1541517655, '5be140f14773f7006606c8cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640429, '人月圆 · 春晚次韵', NULL, 3, 155, 0, 1, '张可久', NULL, 10298, '57b9aeef79bc4400639bd1fc', '元', 'qu', '曲', 'https://baike.baidu.com/item/%E4%BA%BA%E6%9C%88%E5%9C%86%C2%B7%E6%98%A5%E6%99%9A%E6%AC%A1%E9%9F%B5/725211?fr=aladdin', '', '萋萋芳草春云乱，愁在夕阳中。短亭别酒，平湖画舫，垂柳骄骢。一声啼鸟，一番夜雨，一阵东风。桃花吹尽，佳人何在，门掩残红。', '《人月圆·春晚次韵》是元代曲作家张可久所作的一首词。这首曲上片写作者春日傍晚惜别，下片写春雨鸟啼花落之时，思念伊人缠绵悱恻。全曲委婉含蓄，弥漫悲伤情怀，真挚感人。表达了作者因昔日送别佳人，而今孑然孤寂的惆怅之情。', '人月圆：曲牌名，属黄钟调，双调四十八字，前片五句两平韵，后片六句两平韵；次韵：古体诗词写作的一种方式。
萋萋：形容草叶的繁茂。
短亭：旧时离城五里处设短亭，十里处设长亭，为行人休憩或送行饯别之所。
画舫：装饰华美的游船。
骄骢（cōng）：健壮的骢马，泛指骏马。', '萋萋芳草、浓云惨淡，笼罩在血色残阳里。我想起以前在亭子里与你饮酒惜别，那时和现在一样，碧绿的湖水上飘着画舫，垂柳之下还有一匹骏马。鸟雀声声啼，一番春雨下，携起一片东风。东风把桃花都吹落了，佳人还是不在。', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec299c6e67846a9218b57", "shortContent": "“次韵”，和人歌诗并依原诗用韵次序之谓。此曲系和何人之作，已不可知。它写诗人在暮春傍晚中来到昔日送别之地，而伊人不在，于是触景生情，睹物感旧，表达了一腔绵绵离恨和惆怅。\n“萋萋”二句写眼前景物引起的离愁。“萋萋”是视觉，状草之茂盛；“芳草”是嗅觉兼视觉，散发芳香的春草。“萋萋芳草”，年年复生蔓延，人力除不断，野火烧不尽，恰似离人心中的愁恨难以排除，触而复发，不断滋长。故古诗词中芳草与离恨早已结下不...", "authors": ["熊", "笃"], "pressName": "上海辞书出版社"}, {"bookId": "62de2d8a3bba5677642ac2d1", "bookTitle": "元曲三百首", "articleId": "630593d3eebf5e0fdea511f1", "shortContent": "“次韵”，和人歌诗并依原诗用韵次序之谓。此曲系和何人之作，已不可知。它写诗人在暮春傍晚中来到昔日送别之地，而伊人不在，于是触景生情，睹物感旧，表达了一腔绵绵离恨和惆怅。\n\n“萋萋”两句写眼前景物引起的离愁。“萋萋”是视觉，状草之茂盛；“芳草”是嗅觉兼视觉，散发芳香的春草。“萋萋芳草”，年年复生蔓延，人力除不断，野火烧不尽，恰似离人心中的愁恨难以排除，触而复发，不断滋长。故古诗词中芳草与离恨早已结下...", "authors": ["熊", "笃"], "pressName": "上海辞书出版社"}, {"bookId": "6277bbb9f716b7243c7bdff3", "bookTitle": "元曲鉴赏辞典", "articleId": "63126ed7f2af4e09d55b65a9", "shortContent": "自古以来，离别总是让人伤感，离别这一刻，总是让人刻骨铭心。故地重游，驻足追忆，触景生情，更有一番愁怨，此曲便表达了这样的一腔离情。\n在暮春的傍晚，作者来到昔日与佳人分别的地方，驻足凝望，夕阳中萋萋的芳草一望无际，与天相接，天边乱云飞渡，“芳草”、“春云”、“夕阳”这些景物构成的凄迷境界，更勾起了诗人的离愁别绪。此时，与佳人分别的幅幅画面又浮现在眼前：短亭内举杯饮别，佳人别情依依；平湖画舫之中，佳人...", "authors": ["李霓虹"], "pressName": "崇文书局"}, {"bookId": "645fc22c5e6bb82b8caff682", "bookTitle": "历代咏春诗鉴赏：春江花月夜", "articleId": "64731b1da5f1e74f958bd9c1", "shortContent": "“次韵”，和人歌诗并依原诗用韵次序之谓。此曲系和何人之作，已不可知。它写诗人在暮春傍晚中来到昔日送别之地，而伊人不在，于是触景生情，睹物感旧，表达了一腔绵绵离恨和惆怅。\n\n“萋萋”二句写眼前景物引起的离愁。“萋萋”是视觉，状草之茂盛；“芳草”是嗅觉兼视觉，散发芳香的春草。“萋萋芳草”，年年复生蔓延，人力除不断，野火烧不尽，恰似离人心中的愁恨难以排除，触而复发，不断滋长。故古诗词中芳草与离恨早已结下...", "authors": ["熊笃"], "pressName": "上海辞书出版社"}]', '近代张德瀛《词征》：“丰约中度，旋复回环。”', 'indent', 1541517697, '5be1411767f3560062b7c0dd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640430, '人月圆 · 其一', NULL, 0, 326, 0, 1, '李慈铭', NULL, 20875, '5858eeda128fe1006dcc6711', '清', 'ci', '词', '', '', '恹恹小病垂帘地，倚枕怯春寒。月明灯灺，花阴无赖，还上栏干。
麝巾暗解，螺杯偷递，一晌追欢。雾浓香细，银屏划袜，何日同看。
', '', '', '', NULL, '', 'indent', 1541518028, '5be1426dfb4ffe0069a07e51', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640431, '人月圆 · 其二', NULL, 0, 326, 0, 1, '李慈铭', NULL, 20875, '5858eeda128fe1006dcc6711', '清', 'ci', '词', '', '', '湘江终古伤心泪，长自发红兰。莺声啼老，鹃声化去，零落谁看。
钿车催至，冰瓯银烛，半日追欢。冯唐霜鬓，何戡病骨，同此长安。
', '', '', '', NULL, '', 'indent', 1541518069, '5be142948d6d81005eba7839', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640432, '人月圆 · 壬午生日，时初遇会庆节，至翌日小集', NULL, 0, 9, 0, 1, '张纲', NULL, 16449, '5858eaf11b69e60056f639ae', '明', 'ci', '词', '', '', '封人祝望尧云了，归路蔼欢声。何妨明日，开筵笑语，聊庆初生。
官闲岁晚身犹健，兰玉更盈庭。持杯为寿，从教夜醉，谁怕参横。
', '', '', '', NULL, '', 'indent', 1541518127, '5be142cf4773f7006606e6bf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640433, '减兰 · 鹓雏以所著红豆书屋近词见示，赏以小词', NULL, 0, 205, 0, 1, '高燮', NULL, 23336, '5858f12d1b69e60056f6695a', '清', 'ci', '词', '', '', '深情如是。愿种漫天红豆子。两字相思。葬向心头一点痴。
春风微逗。何事干卿池水皱。幽梦迢迢。酒浅愁深骨也销。', '', '', '', NULL, '', 'indent', 1541519081, '5be1468afb4ffe0069a0b994', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640441, '谒金门 · 留不得', NULL, 0, 84, 4, 0, '孙光宪', NULL, 13017, '5858e7e31b69e60056f61eaf', '五代十国', 'ci', '词', '', '', '留不得，留得也应无益。白苎春衫如雪色，扬州初去日。
轻别离，甘抛掷，江上满帆风疾。却羡彩鸳三十六，孤鸾还一只。', '', '', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e748e03048e64fbd892a4", "shortContent": "这首词通首作独白语气，有说是写游子漂泊之感的，有说是代闺人抒写怨情的。细玩词意，当以后说为是。这类表现相思别恨的闺怨题材，在词里已属习见，而这首词在艺术手法上却颇有特色。\n词一开头就是突如其来的两句话：“留不得！留得也应无益。”令人摸不着头脑。然而这话中却分明暗示着一个富于情节性的离别场景：一方挽留无效，恋恋不舍；一方去意已定，没有多少回旋余地。恰如南朝乐府《那呵滩》所写的，这一个虽“愿得篙橹折，...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "63038930d402f14f161459f9", "shortContent": "这首词通首作独白语气，有说是写游子漂泊之感的，有说是代闺人抒写怨情的。细玩词意，当以后说为是。这类表现相思别恨的闺怨题材，在词里已属习见，而这首词在艺术手法上却颇有特色。\n\n词一开头就是突如其来的两句话：“留不得！留得也应无益。”令人摸不着头脑。然而这话中却分明暗示着一个富于情节性的离别场景：一方挽留无效，恋恋不舍；一方去意已定，没有多少回旋余地。恰如南朝乐府《那呵滩》所写的，这一个虽“愿得篙橹折...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '清代徐釚《词苑丛谈》：词虽以险丽为宗，实不及本色语之妙。如李易安“眼波才动被人猜”。萧淑兰“去也不教知，怕人留恋伊。”魏夫人“为报归期须及早，休误妾，一身闲”。孙光宪“留不得，留得也应无益”。', 'indent', 1553349271, '5be28fb167f3560062c74405', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640442, '台城路 · 白狼河北秋偏早', NULL, 3, 395, 2, 1, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', '', '', '白狼河北秋偏早，星桥又迎河鼓。清漏频移，微云欲湿，正是金风玉露。两眉愁聚。待归踏榆花，那时才诉。只恐重逢，明明相视更无语。
人间别离无数，向瓜果筵前，碧天凝伫，连理千花，相思一叶，毕竟随风何处。羁栖良苦，算未抵空房，冷香啼曙。今夜天孙，笑人愁似许。', '', '白狼河：即大凌河。
星桥：指鹊桥。河鼓：即牵牛星。
清漏：漏，古计时器。清漏，是将时漏中水之清移来形容时漏本身。
金风玉露：化用李商稳的《辛未七夕》诗和秦观的《鹊桥仙》词。
待归踏榆花：用唐诗人曾虎《织女牵牛》诗典故：“欲将心就仙郎说，借问榆花早晚秋。”
瓜果筵：古代妇女在七夕时，常在庭中供上瓜果以庆祝牛郎织女相会。
连理：连理树，比喻夫妇恩爱深重。
相思一叶：用红叶题诗的典故。
曙：天亮。
天孙：织女星别名。', '白狼河以北的边地，秋季偏早。架于银河之上的鹊桥又将迎来牵牛星。清晰的漏壶滴水声随着时间推移，淡淡的云似乎更湿润了，这正是金风玉露相逢之时。鹊桥那端，织女的双眉忧愁地攒聚着，是要等牵牛踏着榆花归来，才好将心事说与郎听。却又只恐，重逢之时，分明相望却没有了言语。
人间的别离无数，有多少人，在瓜果的筵席前，向着碧空凝望。连理花，相思叶，随风飘散到了何处？羁旅之中的我怀思良苦，却也不及家中妻子，在冷冷清清的空房里，流泪到天明。今夜喜相逢的织女星，笑人忧愁如许。', '[{"bookId": "60fc157134bfda01e0e91549", "bookTitle": "元明清词鉴赏辞典（新一版）", "articleId": "610e865f911759740c9ae79d", "shortContent": "“七夕”———农历七月初七之夜，作为我国的一个传统节日，起源于有关牛郎、织女的神话故事。南北朝时宗懔的《荆楚岁时记》载：“天河之东，有织女，天帝之子也。年年织杼劳役，织成云锦天衣。天帝怜其独处，许嫁河西牵牛郎。嫁后，遂废织纴。天帝怒，遂令归河东。唯每年七月七日夜渡河一会。”可知七夕是牛郎织女这对整年分离的夫妻在一年中唯一可以聚会一次的喜庆日子。纳兰性德写这首《齐天乐》时，也正当七夕，却身在远离亲人...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}, {"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3f7ccdb86c49f28f48", "shortContent": "纳兰词中“七夕”之日所作，大约有三首，以此篇最晚，或当作于康熙二十二年（1683）。词中说“只恐重逢，明明相视更无语”，令人想到苏轼《江城子》“十年生死两茫茫”一阕之“夜来幽梦忽还乡，小轩窗，正梳妆。相顾无言，惟有泪千行”，那么是词当为悼亡。而归踏榆花之日，再来倾诉别离之苦，则近乎强作安慰。", "authors": [], "pressName": "崇文书局"}]', '', 'indent', 1541607480, '5be29fd9fb4ffe0069b0996a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640443, '台城路 · 寄姚江太白山人陈文卿别本文卿作又新 ', NULL, 0, 304, 2, 1, '张炎', NULL, 10223, '57bc5941a633bd005d42458f', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E5%8F%B0%E5%9F%8E%E8%B7%AF%C2%B7%E5%AF%84%E5%A7%9A%E6%B1%9F%E5%A4%AA%E7%99%BD%E5%B1%B1%E4%BA%BA%E9%99%88%E6%96%87%E5%8D%BF/5287274?fr=aladdin', '', '薛涛笺上相思字，重开又还重摺。载酒船空，眠波柳老，一缕离痕难折。虚沙动月。叹千里悲歌，唾壶敲缺。却说巴山，此时怀抱那时节。
寒香深处话别。病来浑瘦损，懒赋情切。太白闲云，新丰旧雨，多少英游消歇。回潮似咽。送一点秋心，故人天末。江影沉沉，露凉鸥梦阔。', '《台城路·寄姚江太白山人陈文卿》是南宋词人张炎所写的一首赠友词。词人此刻心情亦如玉溪生。在宽己的心态中，对友人也是一个慰藉。用词贴切自然。同时词人描绘了一幅沙鸥夜宿图，在空旷、寂寥中，体会其充实、幽邃。诸般滋味孕满其中，不着痕迹，令人感到词人的功力非同凡响。', '', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e75137d0ac1145494bd81", "shortContent": "张炎大半生流落江湖，潦倒苦闷的境遇，使他更为珍重友情。他曾在《水龙吟·寄袁竹初》一词中说：“几番问竹平安，雁书不尽相思字。……待相逢、说与相思，想亦在、相思里。”你看，他对朋友有着说不尽的相思，同时，他觉得自己也是生活在朋友的思念之中，友情使他凄凉落寞的心灵寻得了抚慰和寄托。这大概就是张炎寄赠友人的词为什么写得较多的一个原因吧。这首《台城路》是这一类词中不大为人注意的一首，但也写得情思浓郁，至为感...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec6145914587d02f5910c", "shortContent": "张炎大半生流落江湖，潦倒苦闷的境遇，使他更为珍重友情。他曾在《水龙吟·寄袁竹初》一词中说：“几番问竹平安，雁书不尽相思字。……待相逢、说与相思，想亦在、相思里。”你看，他对朋友有着说不尽的相思，同时，他觉得自己也是生活在朋友的思念之中，友情使他凄凉落寞的心灵寻得了抚慰和寄托。这大概就是张炎寄赠友人的词为什么写得较多的一个原因吧。这首《台城路》便是这一类词中不大为人注意的一首，但也写得情思浓郁，至为...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}]', '', 'indent', 1541607595, '5be2a04c9f54540070b64e21', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640444, '渔歌子 · 草芊芊', NULL, 0, 84, 0, 1, '孙光宪', NULL, 13017, '5858e7e31b69e60056f61eaf', '五代十国', 'ci', '词', 'https://baike.baidu.com/item/%E6%B8%94%E6%AD%8C%E5%AD%90%C2%B7%E8%8D%89%E8%8A%8A%E8%8A%8A/2294609?fr=aladdin', '', '草芊芊，波漾漾。湖边草色连波涨。沿蓼岸，泊枫汀，天际玉轮初上。
扣舷歌，联极望。桨声伊轧知何向？黄鹄叫，白鸥眠，谁似侬家疏旷？', '', '芊芊：芳草茂盛的样子。
漾漾：水波动荡的样子。
连波涨：意思是草色与波浪相映连成一片。
泊枫汀：船停泊于有枫树的水汀边。
玉轮：明月。骆宾王《在江南赠宋五之问》诗：“玉轮涵地开，剑匣连星起。”
联极望：向四边远望。
伊轧：象声词，摇桨之声，同“咿呀”。
黄鹄（hú胡）：天鹅，游禽类，体长三尺多，形似鹅，颈长，上嘴有黄色之瘤，多为白色，栖于水滨。
侬家：我，自称。疏旷：自由自在，旷达放纵。', '', NULL, '', 'indent', 1541608901, '5be2a5659f54540070d045d6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640445, '渔歌子 · 二首 · 其一', NULL, 1, 6729, 0, 1, '屈大均', NULL, 15479, '5858ea131b69e6006cb11146', '清', 'ci', '词', '', '', '开到棠梨不是花。莺啼莫忆旧繁华。朝雨急，暮风斜。春光催去去谁家。', '', '', '', NULL, '', 'indent', 1541609498, '5be2a7bb4773f70066179191', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640446, '渔歌子 · 二首 · 其二', NULL, 1, 6729, 0, 1, '屈大均', NULL, 15479, '5858ea131b69e6006cb11146', '清', 'ci', '词', '', '', '夹浦夭桃树树斜。一湾不见一湾花。云带岸，水侵沙。
白鸥多处有人家。
', '', '', '', NULL, '', 'indent', 1541609528, '5be2a7d99f54540070b6b7cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640447, '渔歌子', NULL, 1, 6729, 0, 1, '屈大均', NULL, 15479, '5858ea131b69e6006cb11146', '清', 'ci', '词', '', '', '素馨红，素馨绿。素馨红绿看难足。穿茉莉，贯芙蓉，持作玲珑花屋。
旖旄香，宜新浴，荔枝膏滑惭非玉。捐麝片，屏笺沉，怕乱冰肌真馥。
', '', '', '', NULL, '', 'indent', 1541609576, '5be2a80967f3560062c89159', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640448, '渡江云', NULL, 0, 169, 0, 1, '邵亨贞', NULL, 10917, '5858e5f461ff4b006875be34', '元', 'ci', '词', '', '', '朔风吹破帽，江空岁晚，客路正冰霜。暮鸦归未了，指点旗亭，弭棹宿河梁。
荒烟乱草，试小立、目送斜阳。寻旧游、恍然如梦，展转意难忘。
堪伤。山阳夜笛，水面琵琶，记当年曾赏。嗟老来、风埃憔悴，身世微茫。
今宵到此知何处，对冷月、清兴犹狂。愁未了，一声渔笛沧浪。
', '', '', '', NULL, '', 'indent', 1541691742, '5be3e8fdfb4ffe0069c00f95', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640449, '真珠帘', NULL, 4, 9405, 0, 1, '陆游', NULL, 10019, '57b904a9d342d3005ac748fb', '宋', 'ci', '词', '', '', '山村水馆参差路。感羁游、正似残春风絮。掠地穿帘，知是竟归何处。镜里新霜空自悯，问几时、鸾台鳌署。迟暮。谩凭高怀远，书空独语。
自古。儒冠多误。悔当年、早不扁舟归去。醉下白苹洲，看夕阳鸥鹭。菰菜鲈鱼都弃了，只换得、青衫尘土。休顾。早收身江上，一蓑烟雨。', '', '', '', NULL, '', 'indent', 1541693321, '5be3eeea7565710068e5dc13', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640450, '真珠帘 · 栽竹', NULL, 0, 497, 0, 1, '王质', NULL, 36794, '588c9e6361ff4b006bd4783c', '宋', 'ci', '词', '', '', '翠虬夭矫拿苍玉。飞来到、吾庐溪湾山麓。一笑忽相逢，更解包投宿。
北池之畔西墙曲，与主人、呼青吸绿。恨我，无天寒翠袖，共倚修竹。
每遇飞雪萧萧，更惊风摵摵，清标可掬。更与月同来，无半点尘俗。
冬有寒梅闲相伴，春亦有、幽兰相逐。香足。才露下霜飞，又有秋菊。
', '', '', '', NULL, '', 'indent', 1541693435, '5be3ef959f54540070c6366a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640464, '贺圣朝 · 两辰岁生日作', NULL, 1, 342, 0, 1, '赵鼎', NULL, 10272, '57c2f599d342d3006b26fb56', '宋', 'ci', '词', '', '', '花光烛影春容媚。香生和气。纷纷儿女拜翁前，劝犀尊金醴。家酿名，出《真诰》。
凌烟图画，王侯富贵，非翁雅意，愿翁早早乞身归，对青山沉醉。 ', '', '', '', NULL, '', 'indent', 1541781799, '5be548c9ee920a00665385f2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640479, '宝鼎现 · 晚风微动', NULL, 0, 513, 0, 1, '吴潜', NULL, 10788, '5858e5d8570c350069179bc0', '宋', 'ci', '词', '', '', '晚风微动，净扫天际，云裾霞绮。
将海外、银蟾推上，相映华灯辉万砌。
看舞队、向梅梢然昼，丹焰玲珑玉蕊。
渐陆地、金莲吐遍，恰似楼台临水。
老子欢意随人意。
引红裙、钗宝钿翠。
穿夜市、珠筵玳席，多少吴讴联越吹。
绣幕卷、散缤纷香雾。
笼定团圆锦里。
认一点、星球挂也，士女桃源洞里。
闻说旧日京华，般百戏、灯棚如履。
待端门排宴，三五传宣禁侍。
愿乐事、这回重见，喜庆新开起。
瞻圣主、齐寿南山，势拱东南百二。', '', '', '', NULL, '', 'indent', 1542041109, '5be93db6ee920a00668b6690', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640480, '宝鼎现 · 秋怀', NULL, 0, 219, 0, 1, '俞士彪', NULL, 21679, '5858efa31b69e60056f65d4c', '清', 'ci', '词', '', '', '东园极目，暮霭秋色，望中缥缈。江城下、寒涛寂寞，一抹吴峰青未了。
睹败柳、挂残阳欲落，沙岸倒垂红蓼。渐野寺、疏钟时动，惊起隔林栖鸟。
何事今岁秋偏早。向登临、无限愁抱。还追忆、他乡行乐，炬烛双燃花底照。
敞绮席、拥红妆调笑，翻怪笙歌烦恼。残月堕、霞觞更举，客里光阴偏好。
惆怅归来，空赢得、青衫破帽。对长宵魂断，渐渐哀笳唤晓。
帘外露冷、残星小。愁听寒螀叫。待新雁、寄与同游，不是旧时年少。', '', '', '', NULL, '', 'indent', 1542041201, '5be93e1375657100682fff87', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640481, '宝鼎现 · 筠翁李似之作此词见招因赋其事，使歌之者想像风味如到山中也', NULL, 0, 423, 0, 1, '张元幹', NULL, 10184, '57b9b9bc1532bc00656c9c64', '宋', 'ci', '词', '', '', '山庄图画，锦囊吟咏，胸中丘壑。年少日、如虹豪气，吐凤词华浑忘却。便袖手、向岩前溪畔，种满烟梢雾箨。想别墅平泉，当时草木，风流如昨。
瘦藤闲倚看锄药。双芒鞋、雨后常著。目送处、飞鸿灭没，谁问蓬蒿争燕雀。乍霁月、望松云南渡，短艇欹沙夜泊。正万里青冥，千林虚籁，从渠缯缴。
携幼尚有筠丁，谁会得、人生行乐。岸帻纶巾归去，深户香迷翠幕。恐未免、上凌烟阁。好在秋天鹗。念小山丛桂，今宵狂客，不胜杯勺。 ', '', '', '', NULL, '', 'indent', 1542042006, '5be941399f5454007010696d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640482, '宝鼎现 · 过云居山房，访叶林屋、岂僧昆仲', NULL, 0, 64, 0, 1, '佟世南', NULL, 20409, '5858ee67128fe1006dcc62be', '清', 'ci', '词', '', '', '长林雨过，山翠如沐，鸟啼相应。绕城堞、攀云独上，点点嫩苔生小径。
高岭外、听清风乍起，吹落半天钟磬。却最爱、名蓝幽寂，佛火岚光相映。
尽日门掩无人到，任闲庭、云卧花冷。回首望、湖光咫尺，一片澄波如拭镜。
喜二妙、幽栖相并。占尽晨光暮景。叹今日、诗才画手，谁向艺林驰骋。
尔我相携，共游赏、岂辞新咏。更清泉莹玉，花碗香浮绿茗，促坐语笑、浑忘永。
归路寒烟暝。振衣袂、长啸高冈，却把千山唤醒。', '', '', '', NULL, '', 'indent', 1542042066, '5be9417267f356006222246b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640483, '春光好 · 迎春', NULL, 0, 2214, 0, 1, '吴绮', NULL, 20461, '5858ee81128fe1006b880bbf', '清', 'ci', '词', 'https://baike.baidu.com/item/%E6%98%A5%E5%85%89%E5%A5%BD%C2%B7%E8%BF%8E%E6%98%A5/9711775?fr=aladdin', '', '春来也，是何时？没人知。先到玉儿头上，袅花枝。
十二画楼帘卷，红妆笑语参差。争向彩幡成队去，看朱衣。', '《春光好·迎春》是明代词人吴绮烦人作品，这首迎春词章法别致，构思新颖。春已悄悄来到人间。来是何时？却无人知。词中不言陌头杨柳，枝上杏花，却说年轻女子头上先已花枝袅袅。她们一边打扮，一边说笑，成群结队地争着去看那些新考中的青年才士。此词以欢快而又含蓄、热闹而又风雅的情趣，烘衬出春已降临人间。', '玉儿：南齐东昏侯潘妃小字玉儿。古因称女子小字玉奴。
红妆：指女子。
彩幡：古代春节剪彩成幡，做庭户装饰或妇女头饰。
朱衣：相传宋代欧阳修知贡举，阅卷时，觉座后有一朱衣人，逢其点头者文章便入格。此借指春闱中式者。', '', NULL, '', 'indent', 1542042821, '5be944674773f70066713eda', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640484, '春光好', NULL, 0, 110, 0, 1, '张抡', NULL, 10190, '57c408bd5bbb50006343ab7e', '宋', 'ci', '词', '', '', '烟淡淡，雨蒙蒙。水溶溶。帖水落花飞不起，小桥东。
翩翩怨蝶愁蜂。绕芳丛。恋馀红。不恨无情桥下水，恨东风。 ', '', '', '', NULL, '', 'indent', 1542042888, '5be944aa8d6d81005e24f2d4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640485, '春光好', NULL, 1, 82, 0, 1, '吴绡', NULL, 20343, '5858ee58b123db00658dbd12', '清', 'ci', '词', '', '', '风力软，弄晴天。柳如烟。水满平湖看画船。簇神仙。
百舌黄鹂交语，一声一啭堪怜。好花多在鬓云边。
晓妆鲜。', '', '', '', NULL, '', 'indent', 1542043367, '5be9468b9f5454007010b668', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640486, '春光好 · 其一 · 苕川偶题', NULL, 0, 82, 0, 1, '吴绡', NULL, 20343, '5858ee58b123db00658dbd12', '清', 'ci', '词', '', '', '随柳絮，拂榆钱。冶游天。欲问水嬉何处，五湖边。
醉里题将罗扇，归来恰得金钿。走马碧鸡人莫笑，海棠颠。
', '', '', '', NULL, '', 'indent', 1542043402, '5be946adfb4ffe00690aeeb5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640487, '春光好 · 其三 · 立春', NULL, 0, 82, 0, 1, '吴绡', NULL, 20343, '5858ee58b123db00658dbd12', '清', 'ci', '词', '', '', '朱阁丽，彩幡轻。好风生。万树梅花一夜明，晓来晴。
锦爆抛残寒色，瑶笙吹出新声。画屧印将琼屑碎，满江城。', '', '', '', NULL, '', 'indent', 1542043446, '5be946d8ee920a00668becdc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640488, '春光好 · 过沉香亭址', NULL, 0, 470, 0, 1, '董元恺', NULL, 24572, '5858f27761ff4b0063d759c8', '清', 'ci', '词', '', '', '荒亭北，夕阳空。晚烟笼。倾国名花何处，只春风。
自是羽衣尘土，采蘋休怨楼东。一样梨花寒食夜，翠微中。
', '', '', '', NULL, '', 'indent', 1542043526, '5be94729fb4ffe00690afe9c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640489, '破阵子 · 柳下笙歌庭院', NULL, 1, 267, 0, 1, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E7%A0%B4%E9%98%B5%E5%AD%90%C2%B7%E6%9F%B3%E4%B8%8B%E7%AC%99%E6%AD%8C%E5%BA%AD%E9%99%A2/4685245?fr=aladdin', '', '柳下笙歌庭院，花间姊妹秋千。记得春楼当日事，写向红窗夜月前。凭谁寄小莲。
绛蜡等闲陪泪，吴蚕到了缠绵。绿鬓能供多少恨，未肯无情比断弦。今年老去年。', '《破阵子·柳下笙歌庭院》是北宋词人晏几道所写的一首词。词人通过对周围景象的描写，抒发了词人对年华易逝的感慨。并且词人通过对旧日景色的重游与追忆，表达了词人对歌女小莲的怀念之情。', '破阵子：唐教坊曲，一名《十拍子》。陈旸《乐书》：“唐《破阵乐》属龟兹部，秦王（唐太宗李世民）所制，舞用二千人，皆画衣甲，执旗旆。外藩镇春衣犒军设乐，亦舞此曲，兼马军引入场，尤壮观也。”按《秦王破阵乐》为唐开国时之大型武舞曲，震惊一世。玄奘往印度取经时，一国王曾询及之，见所著《大唐西域记》。此双调小令，当是截取舞曲中之一段为之，犹可想见激壮声容。六十二字，上下片皆三平韵。
小莲。人名。
绛（jiàng）蜡：红蜡烛。
等闲：无端。
吴蚕：吴地的蚕，江苏一带盛产蚕丝，故称“吴蚕”。
到了：到底。
绿鬓（bìn）：指乌黑的头发。
无情比断弦：像断弦一样无情。', '庭院下的柳树还有人弹奏歌曲，花丛间也有姐妹在嬉戏。还记得当年在青楼时的那些事，在月光下红窗前写封书信，谁又能替我寄给小莲呢？
烛陪人落泪，春蚕吐丝，诉说着无尽的凄楚缠绵。乌黑的头发又能经得起多少次生离死别，未必能像断弦一样无情。今年依旧比去年还要衰老。', '[{"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "6467927d5e6bb82b8cd0c5c7", "shortContent": "晏幾道年轻时曾有过一段友朋长聚、诗酒欢娱的快乐时光，这段时光成为他小令创作的重要背景。他在《小山词》自序中说：“始时，沈十二廉叔、陈十君宠家，有莲、鸿、[插图]、云，品清讴娱客。每得一解，即以草授诸儿。吾三人持酒听之，为一笑乐。已而，君宠疾废卧家，廉叔下世，昔之狂篇醉句遂与两家歌儿酒使俱流传于人间。”晏幾道对“莲、鸿、[插图]、云”等人的情感既有男女之情，亦有对往昔欢情的追忆，“感光阴之易迁，叹境...", "authors": ["孔燕妮"], "pressName": "上海辞书出版社"}]', '南开大学中华古典文化研究所所长叶嘉莹《历代名家词新释辑评》：“此词抒写对歌妓小莲的怀念之情，也追忆了昔日旧游，并抒发了年华易逝的感慨。”', 'indent', 1542127014, '5bea8d4975657100683e0cdb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640491, '绛都春 · 清明', NULL, 0, 39, 0, 1, '刘镇（叔安）', NULL, 33341, '5858fa87128fe10069b2eb08', '宋', 'ci', '词', '', '', '和风乍扇，又还是去年，清明重到。喜见燕子，巧说千般如人道。墙头陌上青梅小。是处有、闲花芳草。偶然思想，前欢醉赏，牡丹时候。
当此三春媚景，好连宵恣乐，情怀歌酒。纵有珠珍，难买红颜长年少。从他乌兔茫茫走。更莫待、花残莺老。恁时欢笑，休把万金换了。 ', '', '', '', NULL, '', 'indent', 1542128187, '5bea91de75657100683e563e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640492, '绛都春 · 春愁怎画', NULL, 3, 96, 0, 1, '蒋捷', NULL, 10071, '57ac9514c4c9710054655e3c', '宋', 'ci', '词', '', '', '春愁怎画。正莺背带雪，酴醿花谢。细雨院深，淡月廊斜重帘挂。归时记约烧灯夜。早拆尽、秋千红架。纵然归近，风光又是，翠阴初夏。娅姹。颦青泫白，恨玉佩罢舞，芳尘凝榭。几拟情人，付与兰香秋罗帕。知他堕策斜拢马。在底处、垂杨楼下。无言暗拥娇鬟，凤钗溜也。 ', '', '', '', NULL, '', 'indent', 1542128265, '5bea922bfb4ffe006918dd09', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640493, '绛都春 · 东君运巧', NULL, 0, 149, 0, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '东君运巧。向枝头点缀，琼英虽小。全是一般，风味花中最轻妙。横斜疏影当池沼。似弄粉、初临鸾照。众芳皆有，深红浅白，岂能争早。莫厌金樽频倒。把芳酒赏花，追陪欢笑。有愿告天，愿天多情休教老。奇花也愿休残了。免乐事、离多欢少。易老难叙衷肠，算天怎表。 ', '', '', '', '[{"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典", "articleId": "60d8a676d604b86f6c04252c", "shortContent": "此词见《草堂诗馀》，撰人不详。\n金明池，是北宋汴京著名的苑囿。据孟元老《东京梦华录》卷七记载，其地在城西顺天门外街北，东西两岸，皆垂杨蘸水，烟草铺堤。琼林苑与金明池相对，两旁有石榴园、樱桃园，古松怪柏，风景佳丽。这首词的特点是采用赋体，充分利用长调篇幅大、容量多的优势，尽量铺叙，尽情抒写，结合风景的描绘寄寓身世之慨，笔触细腻，委婉动人。整个上阕好像展开一幅画卷，从汴京的顺天门一直铺向金明池，上有轻...", "authors": ["徐桦"], "pressName": "上海辞书出版社"}, {"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典", "articleId": "60fc06683cbe6008c199809d", "shortContent": "此词见《草堂诗余》，撰人不详。\n金明池，是北宋汴京著名的苑囿。据孟元老《东京梦华录》卷七记载，其地在城西顺天门外街北，东西两岸，皆垂杨蘸水，烟草铺堤。琼林苑与金明池相对，两旁有石榴园、樱桃园，古松怪柏，风景佳丽。这首词的特点是采用赋体，充分利用长调篇幅大、容量多的优势，尽量铺叙，尽情抒写，结合风景的描绘寄寓身世之慨，笔触细腻，委婉动人。整个上阕好像展开一幅画卷，从汴京的顺天门一直铺向金明池，上有轻...", "authors": ["徐", "桦"], "pressName": "上海辞书出版社"}]', '', 'indent', 1542128319, '5bea926275657100683e5e82', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640494, '绛都春 · 同赵次闲周澹岩叶小谱登江声帆影阁', NULL, 0, 3925, 0, 1, '姚燮', NULL, 21980, '5858efed128fe10069b28fb0', '清', 'ci', '词', '', '', '雨晴碧窈。恁凄楚客里、闲愁难扫。翠断画栏，不似年时珠帘绕。
横江一带伤心草。漫春意、徐徐催到。两三帆影，回烟转水，特迎斜照。
缥缈。家山一点，越州远望眼、西陵遮了。奈忍听伊，林影疏疏啼新鸟。
韶华容易天涯老。问俊侣、飘零多少。休题琼琯金卮，那回怀抱。', '', '', '', NULL, '', 'indent', 1542128379, '5bea929dee920a006699c86b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640495, '绛都春 · 寒阴渐晓', NULL, 0, 149, 0, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '寒阴渐晓。报驿使探春，南枝开早。粉蕊弄香，芳脸凝酥琼枝小。雪天分外精神好。向白玉堂前应到。化工不管，朱门闭也，暗传音耗。轻渺。盈盈笑靥，称娇面、爱学宫妆新巧。几度醉吟，独倚栏干黄昏后。月笼疏影横斜照。更莫待、单于吹老。便须折取归来，胆瓶顿了。 ', '', '', '', NULL, '', 'indent', 1542128744, '5bea940b8d6d81005e3305db', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640496, '绛都春', NULL, 0, 6729, 0, 1, '屈大均', NULL, 15479, '5858ea131b69e6006cb11146', '清', 'ci', '词', '', '', '庞妻赵女，本酒泉丽质，小字娥亲。阴市好刀，磨砻犀利，鹿车中、嬉春日日施红粉。
卷帏人道佳人。挟长持短，诛雠报父。不顾娇身。遂杀凶豪李寿，任娥眉溅血，玉骨成尘。
孝媛帝怜，香名人播，已千春。曹娥与尔争英烈，更同缑玉芳芬。
子胥渐汝，吹箫一片苦辛。', '', '', '', NULL, '', 'indent', 1542128910, '5bea94b14773f700667f78e7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640497, '哨遍 · 咏弹筝', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '何处放娇，砑罗裙上，一寸销魂地。倚桃笙、恰恰罢梳头，正是恹恹天气。
上青楼、轻拢鬓枣，乍挨纤笋，万种情如水。正搭定鲛绡，妆完羲甲，十二钿蝉栉比。
对玉荷、清影颤琼枝。又小语、流莺上柳丝。慢撚斜搊，鬟亸衫偏，那人情味。
似秋夜楚天，急雨弹入空舲里。鼓神弦、含商嚼徵尽伶俐。
拍碎棠梨，唱残红豆，一双玉剪低还起。印粉痕圆，凝愁声重，碧到眉峰无际。
怪窗前、簌簌落红轻坠。见十五、檀奴绿窗西。要窃听、曲中私意。
不觉阁住银筝，婉转筹身世。种玉前缘，簸钱旧事，脉脉萦牵不已。
家乡秦陇几时归。此曲可怜犹在耳。', '', '', '', NULL, '', 'indent', 1542212736, '5bebdc239f5454007005107e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640498, '哨遍 · 酒后柬丁飞涛即次其赠施愚山韵', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '大叫高歌，脱帽欢呼，头没酒杯里。记昨年、马角未曾生，几唤公为无是。
君不见，庄生漆园傲吏，洸洋玩弄人间世。又不见信陵，暮年失路，醇酒妇人而已。
为汝拔剑上崦嵫。令虎豹、君门勿然疑。古人有云，虽不得肉，亦且快意。
君言在辽西，大鱼如阜海无际。饥咽冬青子，雪窖人、聊复尔。
土炕夜偏长，烛花坌涌，琵琶帐外连天起。更万里乡心，三更雁叫，那不愁肠如醉。
我劝君、莫负赏花时。幸归矣，长嘘复奚为。算人生、亦欲豪耳。
今宵饮博达旦，酒三行以后，汝为我舞，我为若语，手作拍张言志。
黄须笑捋凭红肌。论英雄、如此足矣。', '', '', '', NULL, '', 'indent', 1542212772, '5bebdc478d6d810068a634c9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640499, '哨遍 · 读彭禹峰先生诗文全集竟跋词卷尾兼示令子中郎直上两君', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '自古穰城，从来宛叶，崭绝夸形势。有千年、诸葛卧龙冈，萧萧英魂霸气。
其西引武关，商于六百，昔人以战为儿戏。其南控襄樊，析郦房竹，常产畸人烈士。
公也生值乱离时。好说剑、谈兵射且骑。须作猬张，箭如鸱叫，言天下事。
噫此世何为。岩疆好以公充饵。僰爨牂牁地，鬼磷生、鼓声死。
犹记靖州城，连营贼火，楚歌帐外凄然起。公左挈人头，右提酒瓮，大嚼辕门残胔。
奈缚他、乌获矐渐离。则女子、佣奴尽胜之。论通侯、羊头羊胃。
吾读公也全集，有刀声戛触，人声嘈囋，舞声綷䌨，更杂筑声凄异。
忽然牛饮酒池声，又鬼声、啾然林际。', '', '', '', NULL, '', 'indent', 1542212818, '5bebdc76303f390062c73904', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640500, '哨遍 · 曾庭闻至', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '有客苍然，万里而来，精悍眉端做。诉蹉跎、少壮迅流波，算狂奴、半生磊砢。
炙毂踝高谈，直惊帝座，周旋与我宁为我。嗟廿载河湟，全家关陇，虞兮其若之何。
况赫连城下虎腥多。更无定河头毒龙窝。夜少毡房，马腹中间，鼾哈竟卧。
邀羌女秦娥，豪猪皮染茜红靴。脱帽侮群帅，醉来遑恤其他。
奈少妇穷边，三年浅土，坏罗裙被枫根裹。遂不觉神伤，悄焉泪湿，浮生渐识因果。
乃豪气、狂踪尽摧挫。向法鼓、斋鱼修梵课。更谁知、劫风吹堕。
今年作事大谬，又捩芦沟柁。道上路鬼，掫揄近日，前辈何其计左。
东风下第渡滹沱，笑洛阳、黑貂裘破。
', '', '', '', NULL, '', 'indent', 1542212856, '5bebdc9b9f54540070051762', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640514, '二郎神 · 七夕', NULL, 0, 643, 0, 1, '张孝祥', NULL, 10054, '57bbbd045bbb500063036208', '宋', 'ci', '词', '', '', '坐中客。共千里、潇湘秋色。渐万宝西成农事了，罢稏看、黄云阡陌。乔□橘洲风浪稳，岳镇耸、倚天青壁。追前事、与亡相续，空与山川陈迹。
南国。都会繁盛，依然似昔。聚翠羽明珠三市满，楼观涌、参差金碧。乞巧处、家家追乐事，争要做、丰年七夕。愿明年强健，百姓欢娱，还如今日。 ', '', '', '', NULL, '', 'indent', 1542281839, '5bece9608d6d810068b2356e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640501, '哨遍', NULL, 0, 149, 1, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '太皞司春，春工着意，和气生旸谷。十里芳菲，尽东风、丝丝柳搓金缕。
渐次第、桃红杏浅，水绿山青，春涨生烟渚。九十光阴能几，早鸣鸠呼妇，乳燕携雏。
乱红满地任风吹，飞絮蒙空有谁主。春色三分，半入池塘，半随尘土。
满地榆钱，算来难买春光住。初夏永、薰风池馆，有藤床冰簟纱橱。
日转午。脱巾散发，沉李浮瓜，宝扇摇纨素。著甚消磨永日，有扫愁竹叶，侍寝青奴。
霎时微雨送新凉，些少金风退残暑。韶华早、暗中归去。
', '', '', '', NULL, '', 'indent', 1542212907, '5bebdcc7303f390062c73d9c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640502, '哨遍 · 题坐忘斋', NULL, 3, 212, 0, 1, '朱晞颜', NULL, 10735, '5858e5cc128fe10069b23b23', '元', 'ci', '词', '', '', '一室退藏，隐几坐观，默会人间世。惟集虚，抱一自斋心。
黜聪明形骸之外。回益矣。冥然如丧吾志，乌知礼乐非仁义。彼造物何知，息黥补劓，徒劳巧任私智。但忘年、忘义乐天倪。好恶情、都忘物皆齐。鳅与鱼游，鹿与麋交，将无同异。
噫。请试言之。彼知忘此此忘而。海上多矰?，翁鸥乃、两忘机。想蝶梦庄周，周迷蝶梦，蘧蘧自适无非己。便是是非非，非非是是，由来非马非指。我而今、鱼兔都忘已。又岂知、筌蹄为得计。问臧穀、亡羊何累。塞翁得马奚喜，得失成何济，顿忘世味，箪瓢陋巷，乐以忘其忧耳。
便教有酒也忘归。任忘形、相汝相尔。', '', '', '', NULL, '', 'indent', 1542213203, '5bebdde79f54540066a3548e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640503, '哨遍 · 括兰亭记', NULL, 0, 513, 0, 1, '吴潜', NULL, 10788, '5858e5d8570c350069179bc0', '宋', 'ci', '词', '', '', '在晋永和，癸丑暮春，初作兰亭会。集众贤，临峻岭崇山，有茂林修竹流水。畅幽情，纵无管弦丝竹，一觞一咏佳天气。于宇宙之中，游心骋目，此娱信可乐只。念人生相与放形骸。或一室晤言襟抱开。静躁虽殊，当其可欣，不知老至。
然倦复何之。情随事改悲相系。俯仰间遗迹，往往俱成陈矣。况约境变迁，终期于尽，修龄短景都能几。谩古换今移，时消物化，痛哉莫大生死。每临文吊往一兴嗟。亦自悼不能喻于怀。算彭殇、妄虚均尔。今之视昔如契，后视今犹昔。故聊叙录时人所述，慨想世殊事异。后之来者览斯文，将悠然、有感于此。 ', '', '', '', NULL, '', 'indent', 1542213353, '5bebde8dfb4ffe006a43c49f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640504, '倾杯乐 · 善权寺火', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '玉宝琼扉，琳宫绀宇，层崖染茜。嵌峭壁、三生堂后，梳妆台左，李唐遗殿。
黑摧秃柏苍皮偃。雨淋浪，藓崩剥，坏梁雷篆。昨春野寺，记着青鞋踏遍。
陆浑火、烧残赤县。焚玉石馀灰延鹿苑。叹一夜、猿狖悲号，千年龙鬼糜烂。
化断井、颓垣一片。剩落落、长松谁伴。想月夜，古洞里、仙灵浩叹。', '', '', '', NULL, '', 'indent', 1542214389, '5bebe2988d6d81005e11566e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640505, '倾杯乐 · 正月十三夜预卜元宵月', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '丝雨如酥，小窗似梦，睡猧难稳。试灯夜、凤胫慵点，香闺潜向，姮娥预恳。
元宵可有冰轮分。奈琼瑶，舞萦幌，拂帘逾紧。安黄剔翠，都到眉峰砌恨。
邻院女、盈盈来问。说青鸟广寒原有信。要春城、一色铺银，夜市万家堆粉。
正雪后、玲珑灯映。又陌上、软松鸳润。当此际，才涌上、团圞玉镜。', '', '', '', NULL, '', 'indent', 1542214419, '5bebe2b644d9040061b0442c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640506, '倾杯乐 · 品茶', NULL, 1, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '雨后新晴，林端小阁，疏帘窣地。正注罢、南华下卷，几般绿雪，岳僧新寄。
涧边杓取鸣泉试。借幽廊，支瓦铫，细商茶事。松风入听，瑟瑟珠跳雪沸。
绿鬓女、娇拖燕尾。捧玉湿钧州磁盏翠。羡幽韵、未泻先传，馀芬罢啜还殢。
渐证入、茗柯至理。终不负、酪奴风致。七碗后，玉川子、颓然竟醉。', '', '', '', NULL, '', 'indent', 1542214444, '5bebe2d0303f390062c799ec', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640508, '二郎神', NULL, 1, 513, 0, 1, '吴潜', NULL, 10788, '5858e5d8570c350069179bc0', '宋', 'ci', '词', '', '', '小楼向晚，正柳锁、一城烟雨。记十里吴山，绣帘朱户，曾学宫词内舞。浪逐东风无人管，但脉脉、岁移年度。嗟往事未尘，新愁还织，怎堪重诉。
凝伫。问春何事，飞红飘絮。纵杜曲秦川，旧家都在，谁寄音书说与。野草凄迷，暮云深黯，浑自替人无绪。珠泪滴，应把寸肠万结，夜帷深处。 ', '', '', '', NULL, '', 'indent', 1542281255, '5bece7cb9f545400701109fa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640509, '二郎神 · 小亭徙倚', NULL, 0, 513, 0, 1, '吴潜', NULL, 10788, '5858e5d8570c350069179bc0', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E4%BA%8C%E9%83%8E%E7%A5%9E%C2%B7%E5%B0%8F%E4%BA%AD%E5%BE%99%E5%80%9A/18856904?fr=aladdin', '', '小亭徙倚，慢一步、立秋千影。渐夕照林梢，晚风池上，缉缉轻寒嫩冷。又是将他春__，酿一种、花愁花病。空客鬓岁迁，征衫人老，倚楼看镜。还省。故园多少，紫殷红凝。窗外晓莺啼，拂墙金缕，烟柳慵眠乍醒。桃菜踏青，趁蜂随蝶，长负清明时景。凝伫久，蓦听棋边落子，一声声静。', '', '', '', NULL, '', 'indent', 1542281331, '5bece8148d6d81005e1cf451', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640510, '二郎神 · 近时厌雨', NULL, 0, 513, 0, 1, '吴潜', NULL, 10788, '5858e5d8570c350069179bc0', '宋', 'ci', '词', '', '', '近时厌雨，喜午日、放开天日。不用辟兵符，从今去也，管定千祥万吉。已报甘泉新捷到，况更是、年丰堪必。任景物换来，蛙鸣蝉噪，耳边口煎唧。
洋溢。尽教愿乞，兵厨闲秩。看恰好园池，随宜亭榭，人道瀛洲压一。且恁浮沉，奈何衰悴，惟怕牧之名毕。安得去，占却三神绝顶，瑞芝同拾。 ', '', '', '', NULL, '', 'indent', 1542281352, '5bece82b8d6d810068b223d2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640511, '二郎神 · 己未自寿', NULL, 0, 513, 0, 1, '吴潜', NULL, 10788, '5858e5d8570c350069179bc0', '宋', 'ci', '词', '', '', '古希近也，是六十五翁生日。恰就得端阳，艾人当户，朱笔书符大吉。卦气周来从新起，怕白发、苍颜难必。随见定性缘，餐饥眠困，喜无啾唧。
盈溢，书生做到，能高官秩。况碌碌儿曹，望郎名郡，叨冒差除不一。积世主恩，满家天禄，婚嫁近来将毕。还自祝，愿早悬车里社，始为收拾。', '', '', '', NULL, '', 'indent', 1542281529, '5bece8dcfb4ffe006a4fc097', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640512, '二郎神 · 二首 · 其一', NULL, 0, 300, 0, 1, '奕绘', NULL, 21722, '5858efaf128fe10069b28d4b', '清', 'ci', '词', '', '', '洞启楼窗，书案对、莲花峰影。任海燕窥梁，山峰入户，高处不胜春冷。
万树蟠桃齐开遍，食之者、延年却病。记金灶浮烟，石床含水，宝奁开镜。
来省。笙歌别院，露华初凝。又早是、万年枝头日出，三十六官人醒。
合殿香幽，崇阶莎细，武帝甘泉旧景。剩今日古柏，吟风仙掌，月明轩静。', '', '', '', NULL, '', 'indent', 1542281595, '5bece91f303f390062d3500b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640513, '二郎神 · 二首 · 其二', NULL, 0, 300, 0, 1, '奕绘', NULL, 21722, '5858efaf128fe10069b28d4b', '清', 'ci', '词', '', '', '愁云痴霭，隐一道、无情疆界。乍凉月、上弦秋上浣，偏今夜、女牛光太。
守住情关参不破，直贯透、九重天外。最可恨、虚空加点，便要相思偿债。
难奈。遥知此际，有人偷拜"。乞心事、无人闻细语，清露下、风吹裙带。
就得一年能一见，也强似、相逢不再。越凄景难堪，萤冷琴书，蛩吟萧艾。', '', '', '', NULL, '', 'indent', 1542281620, '5bece9379f54540066af5a7d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640515, '一萼红 · 盆梅', NULL, 1, 212, 0, 1, '朱晞颜', NULL, 10735, '5858e5cc128fe10069b23b23', '元', 'ci', '词', '', '', '玉堂深。正重帘护暝，窗色试新晴。苔暖鳞生，泥融脉起，春意初破琼英。夜深后、寒消绛蜡，误碎月、和露落空庭。暖吹调香，冷芳侵梦，一晌消凝。
长恨年华婉晚，被柔情数曲，抵死牵萦。何事东君，解将芳思，巧缀一斛春冰。那得似、空山静夜，傍疏篱、清浅小溪横。莫问调羹心事，且论笛里平生。', '', '暝：黄昏。
苔暖鳞生：是说梅枝向阳有苔痕如鱼鳞。
泥融脉起：是说盆内新泥融化涌起脉纹。
琼英：琼：一种美玉。英：花。这里指梅花。
寒消绛蜡：红色的蜡烛燃起时，驱走了寒意。绛：深红色。
暖吹：暖风。
晚：暮晚。
芳思：赏花的意绪。
一斛春冰：形容盆梅洁白如冰。
调羹：古时以梅子作为烹饪的调料。 ', '', NULL, '', 'indent', 1542282654, '5beced3e9f54540066af9912', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640516, '眉妩 · 戏张仲远', NULL, 1, 288, 0, 1, '姜夔', NULL, 10049, '57b97702a633bd006661948c', '宋', 'ci', '词', '', '', '看垂杨连苑，杜若侵沙，愁损未归眼。信马青楼去，重帘下，娉婷人妙飞燕。翠尊共款。听艳歌、郎意先感。便携手、月地云阶里，爱良夜微暖。
无限。风流疏散。有暗藏弓履，偷寄香翰。明日闻津鼓，湘江上，催人还解春缆。乱红万点。怅断魂、烟水遥远。又争似相携，乘一舸、镇长见。', '', '眉妩：一名《百宜娇》。', '', NULL, '', 'indent', 1542282693, '5beced699f54540070116030', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640517, '一萼红 · 读小谱花影词卷感题', NULL, 0, 3925, 0, 1, '姚燮', NULL, 21980, '5858efed128fe10069b28fb0', '清', 'ci', '词', '', '', '恁凄清。把初红晚绿，低诉一声声。檐角天高，帘心梦短，谁伴秃管疏檠。
便绝到、黄河远上，恐绛树、不复在旗亭。若问愁侬，艳辰娇夕，也值惺惺。
今愿与君申约，约鸾台鹤峤，月白吹笙。春水横塘，梨花细雨，涉甚闲怨闲情。
笑多事、痴蚕弄茧，更缠绵、啼得似秋莺。试看秦黄，半生误赚狂名。', '', '', '', NULL, '', 'indent', 1542282761, '5becedad8d6d810068b277b0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640518, '一萼红 · 得阮梅叔书，倚此代答。', NULL, 0, 3925, 0, 1, '姚燮', NULL, 21980, '5858efed128fe10069b28fb0', '清', 'ci', '词', '', '', '最难堪，战风梧雨竹，萧瑟似茆庵。病榻秋深，吟灯夜寂，故人书递江南。
便那时、芜城春好，吊烟花、隋苑共停骖。携燕寻诗，贴莺买醉，但把愁谙。
一自囊琴还海，几云遥望浦，天阔看岚。鬓换苍痕，曲翻红怨，已如老去何戡。
问一段、玉钩斜路，敢霜华、催瘦柳毵毵。漫忆城西禊序，佳日重三。', '', '', '', NULL, '', 'indent', 1542282788, '5becedc78d6d810068b2798f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640519, '一萼红 · 录别', NULL, 0, 3925, 0, 1, '姚燮', NULL, 21980, '5858efed128fe10069b28fb0', '清', 'ci', '词', '', '', '夜迢迢。趁香初酒半，添烛倚红箫。冷黛镌颦，明波画睐，嫣韵堪比陵苕。
更携扇、邀凉藓径，正柳外、斜月转西寮。珠露横阶，玉河案户，人影单绡。
曾记看荷时节，泛红窗蠡艇，茶榼诗瓢。散絮经年，团沙此夜，分袂须缓明朝。
便来岁、瓜期未远，怕再见、多半鬓丝凋。听否西风过梧，落叶萧萧。', '', '', '', NULL, '', 'indent', 1542282823, '5becede7fb4ffe006a500f58', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640520, '一萼红 · 秋海棠', NULL, 0, 3925, 0, 2, '姚燮', NULL, 21980, '5858efed128fe10069b28fb0', '清', 'ci', '词', '', '', '太凄然。是谁家紫玉，埋梦古墙边。剪蓼分根，揉绒作叶，消受荒月凉烟。
枉丹染、蜀鹃恨泪，问旧井、谁觅丽华钿。薄质桃花，小魂豆蔻，楚楚娟娟。
一样天生丽质，妒华清春醉，绮烛么弦。露夜零蛩，风晨冷蝶，还肯来与相怜。
苦难乞、东皇赐宠，有怨女、抱病负髫年。试看灵芸玉壶，剩唾红嫣。', '', '', '', NULL, '', 'indent', 1542282846, '5becee0275657100674624fe', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640521, '一萼红 · 二首 · 其一', NULL, 0, 101, 0, 1, '端木埰', NULL, 36968, '5becee44fb4ffe006a50153e', '清', 'ci', '词', '', '', '忆年时，对金盘簇燕，良久隔天涯。燕树凄迷，蒿云迢遰。
缄札空写相思。那曾料、今年春好，把吟袂，刚及看梅期。
佛火青边，夕阳红际，携手同归。归去更劳投辖，又吟朋远迓，芳酒同持。
新月当阶，华灯欲试，堪悲昨岁伤离。便堪傲，幽吟杜老，望西蜀、空寄草诗。
举哀对尊前剧谈，却忘归迟。', '', '', '', NULL, '', 'indent', 1542282935, '5becee578d6d810068b2819e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640522, '一萼红 · 风菱', NULL, 0, 427, 0, 1, '俞樾', NULL, 21749, '5858efb661ff4b0063d7432e', '清', 'ci', '词', '', '', '指江乡。有一绳斜界，采采水中央。鞋角同尖，弓腰比曲，青翠堆满筠筐。
趁秋老、风檐高挂，任儿童、谗口不教尝。几日西风，销磨玉质，干透琼浆。
看取晶盘盛到，似瘦来家令，老去秋娘。面目虽皴，腰肢尽细，多少余味包藏。
还自笑、形骸槁木，论风调、与尔最相当。但博饶甜作相，休惜年光。', '', '', '', NULL, '', 'indent', 1542283135, '5becef239f54540070117c50', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640523, '点绛唇 · 楼下清歌', NULL, 0, 1, 1, 0, '李祁', NULL, 36969, '5bed14648d6d810068b4bc52', '元', 'ci', '词', 'https://baike.baidu.com/item/%E7%82%B9%E7%BB%9B%E5%94%87%C2%B7%E6%A5%BC%E4%B8%8B%E6%B8%85%E6%AD%8C/10948478?fr=aladdin', '', '楼下清歌，水流歌断春风暮。
梦云烟树，依约江南路。
碧水黄沙，梦到寻梅处。
花无数。问花无语。明月随人去。', '《点绛唇·楼下清歌》，北宋李祁词作，词曰：“楼下清歌，水流歌断春风暮。梦云烟树。依约江南路。碧水黄沙，梦到寻梅处。花无数。问花无语。明月随人去。”此词明写春景，暗抒离情。', '断：终了
水流：即流水，暗寓知音。
依约：隐约、朦胧的，极是迷离惝恍的梦境。', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74d0dbb8b379ee08df0e", "shortContent": "此词写怀人念远之情。由闻歌而至入梦，由梦中寻觅而转入对月怀人。词体虽小，却能于辗转往复之中，佳境迭现，曲尽其意。\n起句从闻歌入手。“清歌”，为全词在感情上定下了幽清的基调，细读全词，便知曲终无违于一个“清”字。“水流歌断春风暮”，断，终了，这句是说那流水般的一曲清歌，在春风吹拂的暮霭中结束了。“春风暮”，景语，一字一景，词中以下诸景，皆缘此三字而来；这里也同时点出了这首词的特定节候，这正是一个怀人...", "authors": ["邱鸣皋"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5d5911759740c9bcb90", "shortContent": "此词写怀人念远之情。由闻歌而至入梦，由梦中寻觅而转入对月怀人。词体虽小，却能于辗转往复之中，佳境迭现，曲尽其意。\n起句从闻歌入手。“清歌”，为全词在感情上定下了幽清的基调，细读全词，便知曲终无违于一个“清”字。“水流歌断春风暮”，断，终了，这句是说那流水般的一曲清歌，在春风吹拂的暮霭中结束了。“春风暮”，景语，一字一景，词中以下诸景，皆缘此三字而来；这里也同时点出了这首词的特定节候，这正是一个怀人...", "authors": ["邱鸣皋"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "630592544b56e213e6848048", "shortContent": "此词写怀人念远之情。由闻歌而至入梦，由梦中寻觅而转入对月怀人。词体虽小，却能于辗转往复之中，佳境迭现，曲尽其意。\n\n起句从闻歌入手。“清歌”，为全词在感情上定下了幽清的基调，细读全词，便知曲终无违于一个“清”字。“水流歌断春风暮”，断，终了，这句是说那流水般的一曲清歌，在春风吹拂的暮霭中结束了。“春风暮”，景语，一字一景，词中以下诸景，皆缘此三字而来；这里也同时点出了这首词的特定节候，这正是一个怀...", "authors": ["邱鸣皋"], "pressName": "上海辞书出版社"}]', '', 'indent', 1542292707, '5bed147d44d9040061be8784', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640527, '南浦', NULL, 0, 156, 0, 1, '程垓', NULL, 10191, '57c6f782efa631005ad93a9b', '宋', 'ci', '词', '', '', '金鸭懒熏香，向晚来春酲，一枕无绪。浓绿涨瑶窗，东风外、吹尽乱红飞絮。无言伫立，断肠惟有流莺语。碧云欲暮，空惆怅，韶华一时虚度。
追思旧日心情，记题叶西楼，吹花南浦。老去觉欢疏，伤春恨，都付断云残雨。黄昏院落，问谁犹在凭阑处。可堪杜宇，空只解声声，催他春去。 ', '', '', '', NULL, '', 'indent', 1542379755, '5bee68838d6d81005e300fcd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640528, '南浦', NULL, 0, 106, 0, 1, '高士奇', NULL, 23253, '5858f11861ff4b006cb90145', '清', 'ci', '词', '', '', '双燕又重来，认低梁，曲栋是伊曾住。剪剪掠花梢，春寒甚、恨颠风绵雨。
穿檐绕窗，知他心事应无据。恐被湘帘朝隔断，难把向时巢补。
怜余三径荒芜，刚湖乡卜筑，葭墙葵圃。多少隔年情，相留处，先禁草堂儿女。
书囊画谱，莫教衔坠香泥污。待到纱窗蕉影绿，坐听嫩雏争乳。', '', '', '', NULL, '', 'indent', 1542380017, '5bee698e9f5454007024512d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640529, '南浦 · 浓阴催暝细雨送寒愁绪无端长歌自遣', NULL, 0, 26, 0, 1, '刘炳照', NULL, 36970, '5bee69e49f54540070245583', '清', 'ci', '词', '', '', '疏雨湿苔茵，怨天公，不放斜阳微罅。莺燕话离情，重来日、非复春游闲冶。
红愁绿惨，群芳旧侣都凋谢。一点青灯寒焰短，怎度者般长夜。
当年联袂骚坛，更评花醉月，争飞玉斝。豪气尽消磨，添惆怅、偏又寄人篱下。
琴弦已断，茫茫谁是知音者。千种凄凉无处诉，空剩泪珠盈把。', '', '', '', NULL, '', 'indent', 1542380122, '5bee69fe8d6d810068c54d18', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640530, '南浦 · 题吴枚庵《慢香词》', NULL, 0, 33, 0, 1, '刘嗣绾', NULL, 36971, '5bee6a387565710067590699', '清', 'ci', '词', '', '', '金荃旧谱，有新声、一卷叠珑玲。界出乌丝小字，随意写云屏。
拟把红牙低唱，向筵前、拍了又重停。借名香炷就，碧窗影里，消受客灯青。
回首吟坛销歇，剩年时、春恨记星星。直待千帆过尽，细数旧旗亭。
残月晓风何处，甚天涯、词客各飘零。怕高楼一带，潇湘归雁，有人听。
', '', '', '', NULL, '', 'indent', 1542380202, '5bee6a4e8d6d81005e3027c9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640531, '南浦 · 题秦端崖先生《寒梅着花未画幅》', NULL, 0, 33, 0, 1, '刘嗣绾', NULL, 36971, '5bee6a387565710067590699', '清', 'ci', '词', '', '', '远天如梦，恁荒寒、点出碧芜村。依约江南归路，昨夜逗春痕。
报与枝头消息，问窗前、小立几黄昏。料空山孤鹤，月明无主，独自守柴门。
数遍旗亭长短，向天涯、我亦怅离樽。直待东风人日，清怨与同论。
纸帐朝来依旧，怪石肠、不似旧温存。莫图中回首，关山容易笛销魂。', '', '', '', NULL, '', 'indent', 1542380229, '5bee6a698d6d81005e3028e8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640532, '南浦 · 次韵答南金见寄', NULL, 0, 169, 0, 1, '邵亨贞', NULL, 10917, '5858e5f461ff4b006875be34', '元', 'ci', '词', '', '', '烟水隔殊乡，又匆匆误了，踏青时候。一别几多时，河桥外、官柳青条犹瘦。君来为问，渡江桃叶曾来否。生怕木阑双艇子，只道故人依旧。孤村寒食＊寻，料归期渐近，花开休骤。油壁耐东风，先拌取、同醉乱红千亩。凭阑望久。几番魂断烟中岫。从此相逢休草草，莫对夕阳搔首。 ', '', '', '', NULL, '', 'indent', 1542380463, '5bee6b538d6d810068c560db', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640533, '南浦 · 会波村，在松江城北三十里。其西九山', NULL, 0, 472, 0, 1, '陶宗仪', NULL, 11135, '5858e62c128fe1006b87c8b5', '元', 'ci', '词', '', '', '水兼九山南过村外，以入于海。而沟塍畎浍，隐翳竹树间。春时桃花盛开，难犬之声相闻，殊有武陵风概，隐者停云子居焉。一舟曰水光山色，时放乎中流，或投竿，或弹琴，或呼酒独酌，或哦咏陶谢韦柳诗，殆将与功名相忘，尝坐余舟中茗供，襟抱清旷，不觉度成此曲。主人即谱入中吕调，命洞箫吹之，与童子权歌相答，极鸥波缥缈之思云如此好溪山，羡云屏九叠，波影涵素。暖翠隔红尘，空明里，着我扁舟容与。高歌鼓＊，鸥边长是寻盟去。头白江南，看不了，何况几番风雨。画图依约天开，荡清晖，别有越中真趣。孤啸拓蓬窗、幽情远，都在酒瓢茶具。水＊摇，晚月明，一笛潮生浦。欲问渔郎无恙否？四首武陵何许。', '', '', '', NULL, '', 'indent', 1542380740, '5bee6bad9f545400702470ef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640535, '多丽 · 近中秋', NULL, 0, 149, 0, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '近中秋，迥然玉宇澄鲜。更尧蓂、十有一叶，向人特敷妍。喜名家、世行阴德，有馀庆、门拥祥烟。梦协熊罴，间生鸑鷟，妙年攀桂振青毡。横飞上，金闺粉署，小试佐临川。翩然返，一身似叶，琳馆清闲。记榜下、曩尝附骥，浪萍还有夤缘。曳长裾、不辞还道，接漫刺、复面同年。邂逅佳辰，铺排雅席，金炉香袅欲何言。愿趣诏、入扶宗社，浩气愈纯全。长年少，龟龄共永，鹤算同坚。 ', '', '', '', NULL, '', 'indent', 1542381290, '5bee6e8e303f390062e6b914', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640536, '多丽 · 为友生书所见', NULL, 0, 830, 0, 1, '张翥', NULL, 11200, '5858e63a1b69e60056f6100c', '元', 'ci', '词', '', '', '小庭阶。帘栊婀娜蓬莱。恨匆匆、归鸿度影，东风摇荡情怀。不多时、见他行过，霎儿后、依旧回来。银铤双鬟，玉丝头导，一尖生色合欢鞋。麝香粉、绣茸衫子，窄窄可身裁。偶回头、笑涡透脸，蝉影笼钗。忆疏狂、随车信马，那知沦落天涯。豆蔻初、可怜春早，菖蒲晚、难见花开。红叶波深，彩楼天远，浪凭青鸟信音乖。等闲是、这番迷眼，无处可安排。行云断、梦魂不到，空赋阳台。 ', '', '', '', NULL, '', 'indent', 1542381323, '5bee6eaf44d9040061cf6066', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640537, '多丽', NULL, 0, 34, 0, 1, '严仁', NULL, 10210, '57d02f438ac2470062e1779b', '宋', 'ci', '词', '', '', '最无端，官楼画角轻软。一声来、深闺深处，把人好梦惊回。许多愁、尽教奴受，些个事、未必君知。泪滴兰衾，寒生珠幌，翠云撩乱枕频欹。窗儿上、几条残月，斜玉界罗帷。更堪听，霜摧败叶，静扣朱扉。
念别离、千里万里，问何日是归期。关情处、鱼来雁往，断肠是、兔走鸟飞。美景良辰，赏心乐事，风流孤负缕金衣。谩赢得、花颜玉骨，瘦损为相思。归须早，刘郎双鬓，莫遣成丝。', '', '', '', NULL, '', 'indent', 1542381484, '5bee6f507565710067594e97', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640538, '多丽 · 为袁敬甫补悼亡', NULL, 0, 644, 0, 1, '易顺鼎', NULL, 21499, '5858ef778e450a006cba8491', '清', 'ci', '词', '', '', '玉卮娘，人间金屋难藏。是生成、雪肤花貌，海山别有家乡。
九螭钗、两头敲重，千蝶帐、四角拖长。稽首情天，扫眉才地，镜台双笑伴檀郎。
谁说道、书生无命，曾染杜兰香。还牢记、帕装端正，钏响荒唐。
问因何、西东沟水，茂陵留句凄凉。抱愁眠、暗销龙骨，收影去、空费鸾肠。
白燕秋飞，红鹃春哭，伤心不见殓时妆。料碧海、娥情定悔，夜夜照潇湘。
虚博得、月归环佩，云想衣裳。', '', '', '', NULL, '', 'indent', 1542381535, '5bee6f817565710067595170', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640539, '多丽 · 刘公㦷吏部每为余言苏门百泉之胜，冬日行汲县道中，遥望峰峦幽异，未及登眺，感赋一阕，并以寄刘', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '记刘子，语我苏门山好。更百泉、澄泓萧瑟，雷辊千尺银瀑。
乱松崖、经声夜落，古溪、樵风晨噭。寿柏瘿藤，危梯恶栈，山无不树，树无不鸟。
径谽谺、数间虎落，时响幽人铫。翛然也、指间弦歇，山前月晓。
一自渡、桑干河水，马头恒向西笑。拟十月、寒衣手绽，来作山村荷蓧。
太息尘踪，难攀仙境，重来猿鹤应相诮。祇望见、蒙茸幂䍥，一派青难了。
回头听、似有人兮，山半长啸。', '', '', '', NULL, '', 'indent', 1542381588, '5bee6fb89f5454007024a79a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640540, '多丽 · 冰', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '玉壶中，井花彻底都凝。讶涟漪、风吹难皱，潺湲一夜无声。
太玲珑、鳞堂贝阙，偏确荦、玉甃银屏。烈士心边，佳人肌上，一种晶莹仿佛曾。
还应似、飞仙剑侠，灰冷万缘僧。都只被、奇寒苦冻，锻炼才成。
记前冬、芦沟南下，归舟却阻河淩。四弦弹、颇黎劈裂，万梃击、琴筑琮琤。
玉骇蛟愁，珠飞兕吼，篷窗千里梦魂清。回头笑、京华炙手，岁岁火云蒸。
还亏煞、沿街六月，唤买凉冰。', '', '', '', NULL, '', 'indent', 1542381616, '5bee6fd59f5454007024a8e3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642098, '幽梦影 · 卷一 · 六十七', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '斗方止三种可取：佳诗文，一也；新题目，二也；精款式，三也。', '', '斗方：一或二尺见方的书画或诗幅页。', '', NULL, '', 'indent', 1556017113, '5cbe7f57c8959c00752d7928', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640541, '多丽 · 清明兼上巳作', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '算风光，依稀才过传柑。又取次、韶光媚眼，今朝三月逢三。
映一行、水边粉屧，立几簇、桥上红衫。皂荚园中，丁香树下，春人影落百花潭。
又何处、东风作阵，吹绽碧桃缄。从古是、清明上巳，两好难兼。
恰经过、幽坊小市，衣痕鬓缕廉纤。翠蛾招、流觞巷北，黄莺唤、泼火城南。
艳粉墙头，红香帽底，花枝婉娩碍晴檐。争留住、饧箫戏鼓，准拟待新蟾。
归来晚、梨花院宇，情绪恹恹。', '', '', '', NULL, '', 'indent', 1542381646, '5bee6ff2303f390062e6cc4b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640553, '六么令', NULL, 4, 321, 0, 1, '吕岩', NULL, 12581, '5835b348128fe10062cb8166', '唐', 'ci', '词', '', '', '东与西，眼与眉。偃月炉中运坎离，灵砂且上飞。
最幽微，是天机，你休痴，你不知。 ', '', '', '', NULL, '', 'indent', 1542627504, '5bf230549f545400704e91dc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640554, '六么令 · 京中清明', NULL, 0, 3, 0, 1, '李琳', NULL, 28367, '5858f5f661ff4b0063d775d5', '宋', 'ci', '词', '', '', '淡烟疏雨，香径渺啼鴂。新晴画帘闲卷，燕外寒犹力。依约天涯芳草，染得春风碧。人间陈迹？斜阳今古，几缕游丝趁飞蝶。
柳向尊前起舞，又觉春如客。翠袖折取嫣红，笑与簪华发。回首青山一点，檐外寒云叠。梨花淡白，柳花飞絮，梦绕阑干一株雪。', '', '', '', NULL, '', 'indent', 1542627567, '5bf23090756571006783354d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640555, '六么令 · 壬寅四月，扶病外邑催租，寄内', NULL, 0, 90, 0, 1, '杨泽民', NULL, 31954, '5858f93e61ff4b0063d79412', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E5%85%AD%E4%B9%88%E4%BB%A4%C2%B7%E5%A3%AC%E5%AF%85%E5%9B%9B%E6%9C%88%EF%BC%8C%E6%89%B6%E7%97%85%E5%A4%96%E9%82%91%E5%82%AC%E7%A7%9F%EF%BC%8C%E5%AF%84%E5%86%85/18853995?fr', '', '道骨仙风，本自无寒燠。谁教勉从人事，风雨充梳沐。酒病从来屡作，汤药宜谙熟。五穷难逐。折腰升斗，辜负当年旧松菊。
今岁重更甲子，已是难题目。那更频陪俎宴，几度山颓玉。扶病奔驰外邑，宛转溪山曲。蛛丝应卜。音书频寄，止酒加餐不须嘱。', '', '', '', NULL, '', 'indent', 1542627834, '5bf2319f756571006783422b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640556, '凤凰台上忆吹箫', NULL, 0, 304, 0, 1, '张炎', NULL, 10223, '57bc5941a633bd005d42458f', '宋', 'ci', '词', '', '味凄然。以其号孤篷，嘱余赋之。 ', '水国浮家，渔村古隐，浪游惯占花深。犹记得、琵琶半面，曾湿衫青。不道江空岁晚，桃叶渡、还叹飘零。因乘兴，醉梦醒时，却是山阴。
投闲倦呼俦侣，竟棹入芦花，俗客难寻。风渺渺、云拖暮雪，独钓寒清。远溯流光万里，浑错认、叶竹寰瀛。元来是、天上太乙真人。 ', '', '', '', NULL, '', 'indent', 1542628453, '5bf23409fb4ffe006a8d39cf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640557, '凤凰台上忆吹箫 · 步月', NULL, 0, 201, 0, 1, '沈宜修', NULL, 15234, '5858e9e01b69e6006cb1100e', '明', 'ci', '词', '', '', '帘影横阶，翠？垂榥，花阑芳径苔肥。看小庭烟醉，白月澄漪。
帘外将舒玉药，寻萼梦、雪汗凝蕤。金壶送，回廊静悄，墨洒花筛。
微微。罗衣耐冷，双繶向轻阴，夜渐阑时。想夕阳初下，云树参差。
又是婵娟千里，长相见、淡景霏霏。还待去，浓香软叠，绣幕重帏。', '', '', '', NULL, '', 'indent', 1542628534, '5bf2345b7565710067836776', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640558, '凤凰台上忆吹箫 · 代人恨别', NULL, 0, 201, 0, 1, '沈宜修', NULL, 15234, '5858e9e01b69e6006cb1100e', '明', 'ci', '词', '', '', '好事多磨，重云掩月，晓风惊梦难留。又一番春色，恼乱枝头。
湘浦佩沉波冷，花影里、枉自凝眸。添怊怅，燕来鸿去，锁尽闲愁。
休休。楚台已远，生惹得情深，何处忘忧。叹幽怀几许，总付东流。
那更栏前芳草，萦人思、恨满银钩。空回首，从今风雨，两地悠悠。', '', '', '', NULL, '', 'indent', 1542628575, '5bf234838d6d810068ef9f39', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640559, '凤凰台上忆吹箫', NULL, 0, 326, 0, 1, '李慈铭', NULL, 20875, '5858eeda128fe1006dcc6711', '清', 'ci', '词', '', '', '叶随初鸿，花留宿蝶，巫云低拥屏山。恁银河化泪，洒遍人天。
偏是流萤有意，入疏帘、犹觅花钿。更宵静，玉窗风触，时响筝弦。
当年，倩黄姑作证，辨一炷心香，兰夜同燃。奈星桥乌鹊，不会传笺。
独自针楼扶病，更无人、相倚恹恹。但长守、断丝蛛合，谁与缠绵。', '', '', '', NULL, '', 'indent', 1542628861, '5bf235a2303f39006210cad7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640560, '凤凰台上忆吹箫', NULL, 0, 75, 0, 1, '李岳瑞', NULL, 20617, '5858ee9e1b69e6006cb13436', '清', 'ci', '词', '', '', '皓月仍圆，西风昨夜，一年容易惊秋。泻沈沈银汉，无语东流。
正是羁心撩乱，何堪更、砧杵声遒。销魂处、红鹣绮梦，白雁边愁。
悠悠。夜凉如水，恰小扇轻衫，渐昵香篝。也知非吾土，强俯登楼。
一发中原隐隐，凭谁挽、落日神州。空惆怅、公无渡河，试奏箜篌。', '', '', '', NULL, '', 'indent', 1542628921, '5bf235de44d9040061f9813b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640563, '满路花 · 夜抵江城，闻蜡梅香，同刘易台柬黄艾罨', NULL, 0, 2, 0, 1, '张夏', NULL, 31106, '5858f870128fe1006b885f20', '宋', 'ci', '词', '', '', '芦遮曲岸天，竹碎沙滩月。榜人乘夜渡、呼声捷。严寒堕指，百丈迎风折。
星芒动金阙。送下栴檀，却随鼓角清越。
常年于役，半刺怀磨减。何如茅屋卧、耑修业。暗麝飘来，此亦晨钟发。
素交吾所浃，问山谷、木樨香，参个同别。', '', '', '', NULL, '', 'indent', 1542714416, '5bf383d4756571006790e524', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640564, '满路花 · 与听公', NULL, 0, 112, 0, 1, '严绳孙', NULL, 26496, '5858f43b1b69e6006cb16423', '清', 'ci', '词', '', '', '吴宫落日荒，燕市悲歌暮。天山三丈雪、迷行路。蓦然相遇，宝筏横津渡。
支公都未许。会待安心，早教觅向何处。
玄关频叩，默语俱成误。白头浑未定、风前絮。一灯深照，领略元无句。
从今应记取。玉河霜月，满身多少花雨。', '', '', '', NULL, '', 'indent', 1542714554, '5bf384038d6d81121a310011', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640566, '满路花 · 荷珠', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '红绡水面妆，碧玉波间柄。低迷扶翠盖，西风劲。玉人摇橹，隔浦莲歌竞。花面交相映。戏取春纤，掬他潭水芳冷。
洒来错落，尽向钱钱迸。鲛珠圆又碎，难持赠。低鬟凝想，总似檀郎性。荡漾何时定。惆怅回船，碧天早挂明镜。', '', '', '', NULL, '', 'indent', 1542715084, '5bf3867144d9040061070d81', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640567, '满路花 · 赠梵公 师住云门，工书画。时以选诗来荆溪', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '荷钱贴野塘，竹粉黏晴砌。师从何处到，云门寺。零笺烂本，点笔聊轩轾。
试将小语戏。高岑王孟，关卿定复何事。
平山堂下，鸿爪依稀记。北邙王与宋，曾同醉。重逢瓶拂，顿下山阳泪。
更欲游何地。他时念我，巨然小幅须寄。', '', '', '', NULL, '', 'indent', 1542715143, '5bf386ab9f54540066fa7438', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640568, '满路花 · 咏禹门寺前一带颓崖峭石', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '嵌空撑户牖，凿翠支堂奥。淙淙岩溜响，喧银瀑。硗确谽谺，铁色黏青峤。
石笋攒丹灶。积雪层冰，玲珑原隰俱缟。
或为怪鹘，或作千年豹。或似秋江岸，晴龟曝。林青日黑，山畔归樵少。
野火连天烧。虎腥如雨，瘦石此时更峭。', '', '', '', NULL, '', 'indent', 1542715191, '5bf386dd8d6d81121a312222', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642099, '幽梦影 · 卷一 · 六十八', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '情必近于痴而始真；才必兼乎趣而始化。', '', '', '', NULL, '', 'indent', 1556017134, '5cbe7f6cf884af0065c06eaa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640575, '雨中花令', NULL, 0, 176, 0, 1, '扬无咎', NULL, 32269, '5858f98461ff4b006cb947e0', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E9%9B%A8%E4%B8%AD%E8%8A%B1%E4%BB%A4%C2%B7%E5%8E%9F%E6%9D%A5%E6%98%AF%E4%BA%91%E6%B8%A9%E9%9B%A8%E6%B6%A6/18855619?fr=aladdin', '', '原来是云温雨润。诮不解、佯嗔偷闷。倾坐精神，堪人情性，眉际生春晕。
语带京华清更韵。听娅姹、莺喉娇稳。别后相思，心头欲见，觅个灯花信。 ', '', '', '', NULL, '', 'indent', 1542726191, '5bf3b1d4303f39006220477c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640576, '开元乐', NULL, 84, 87, 0, 1, '李煜', NULL, 10017, '57b8af7c5bbb50005b770fdd', '五代十国', 'ci', '词', 'https://baike.baidu.com/item/%E5%BC%80%E5%85%83%E4%B9%90%C2%B7%E5%BF%83%E4%BA%8B%E6%95%B0%E8%8C%8E%E7%99%BD%E5%8F%91/4060548?fr=aladdin', '', '心事数茎白发，生涯一片青山。
空林有雪相待，野路无人自还。', '《开元乐·心事数茎白发》是五代词人李煜创作的一首词。', '这首词作者题署不一，《全唐五代词》依邵长光辑录《南唐二主词》稿本列入李煜词，唐圭璋《南唐二主词汇笺》依此说。
数：清刻本《诗人玉屑》中作“千”。茎（jīng）：量词。用于长条形的东西。这里是根的意思。唐代薛逢《长安夜雨》中有：“当年志气俱消尽，白发新添四五茎”诗句。
生涯：人的一生所经历的种种状况。语出《庄子·养生主》中：“吾生也有涯，而知也无涯。”后引申为生命、人生。青：《万首唐人绝句》中作“春”。青山，郁郁葱葱的山岭，也指归隐之处。
空林：詹安泰《李璟李煜词》、《南唐二主词汇笺》等本中均作“空山”。空林，指人烟罕至，幽深的山林。相待：等待，相等。
野路：《万首唐人绝句》、《东坡题跋》、《诗话总龟》前六卷中均作“古路”。野路，村野间的田间小路。自还：《万首唐人绝句》、《东坡题跋》、《诗话总龟》前六卷中均作“独还”。自还，独自行走。', '', '[{"bookId": "6277f75b92ce672e2db07b2f", "bookTitle": "李煜全集", "articleId": "63126e147f0b9738b369af61", "shortContent": "此词诸本《南唐二主词》及总集皆未收录，惟邵长光辑录《南唐二主词》稿本，据东坡题跋（《东坡全集·跋李后主〈开元乐〉词》）录之，兹依邵辑本收入。此词又传为顾况作，见《万首唐人绝句》卷二十六。", "authors": [], "pressName": "崇文书局"}]', '', 'indent', 1542797954, '5bf4c9fa8d6d8100680a31c8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640577, '芳草渡 · 依清真四声和伯越还乡之作', NULL, 0, 369, 0, 1, '杨玉衔', NULL, 24980, '5858f2d71b69e60056f67782', '清', 'ci', '词', '', '', '息故里。怅倦鹤归来，暮天无侣。乍觅巢痕梦，飘摇又委风雨。
为旅情味苦。思园莺能诉。谢送我、夜半潮生，一棹归去。
回顾。岭云望远，草绿清明墦祭路。漫虚拟、支茅傍冢，墟烟凝窗户。
松楸抚遍，乱撩起、絮泥闲绪。但注目，似蝶钱灰倦舞。', '', '', '', NULL, '', 'indent', 1542798926, '5bf4cdf1303f3900622b60e3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640578, '芳草渡 · 登吴江城楼', NULL, 0, 3925, 0, 1, '姚燮', NULL, 21980, '5858efed128fe10069b28fb0', '清', 'ci', '词', '', '', '春潮落，晚山低。高楼外，几船归。迢迢渔唱出斜晖。
沙岸白，烟草绿，暝禽飞。
杨花乱。愁鬓短。天际乡云目断。芳事尽，客心非。今宵梦，明日路，大江西。', '', '', '', NULL, '', 'indent', 1542798976, '5bf4ce2575657100679e278f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640580, '调笑令', NULL, 1, 196, 0, 1, '甯调元', NULL, 25124, '5858f2fb61ff4b0068762aa4', '清', 'ci', '词', '', '', '人影。人影。一个清清冷冷。夜阑难觅知音。相与商量古今。今古。
今古。独自商量正苦。
', '', '', '', NULL, '', 'indent', 1542800435, '5bf4d3d98d6d8100680ab703', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640581, '浣溪沙 · 重九旧韵', NULL, 28, 3406, 1, 0, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'ci', '词', '', '', '《白雪》清词出坐间，爱君才器两俱全。异乡风景却依然。
可恨相逢能几日，不知重会是何年。茱萸子细更重看。', '', '浣溪沙：词牌名。原为唐代教坊曲，《金奁集》入「黄鐘宫」，《张子野词》入「中吕宫」。最早采用此调的是唐人韩致尧，通常以其词《浣溪沙·宿醉离愁慢髻鬟》为正体，另有四种变体。正体双调，四十二字，上阕三句，三平韵；下阕三句，两平韵；过阕二句多用对偶。此调音节明快，为婉约、豪放两派词人所常用。别有《摊破浣溪沙》，又名《山花子》，上下阕各增三字，韵全同。
「重九旧韵」：傅注本存目阙文。今据元延祐本补正文，并据吴讷钞本等略作校订。傅注本阙如待考补。元延祐本无题，《二妙集》本、茅维《苏集》本题作「重九」。兹从吴讷钞本题。
《白雪》：龙榆生笺引战国楚·宋玉《对楚王问》：「客有歌于郢中者，其始曰《下里》《巴人》，国中属而和者数千人；其为《阳阿》，《薤露》，国中属而和者数百人；其为《阳春》《白雪》，国中属而和者不过数十人；引商刻羽，杂以流徵，国中属而和者不过数人而已。是其曲弥高，其和弥寡。」
茱萸：龙榆生笺引唐·杜少陵《九日蓝田崔氏庄》诗：「明年此会知谁健，醉把茱萸子细看。」
却依然：《二妙集》本作「各依然」。
子细：《二妙集》本、毛本作「仔细」。刘尚荣按：「『仔细』是後起义。」', '', '[{"bookId": "6277f29b862cf9784bfd1c98", "bookTitle": "苏轼词全集", "articleId": "63126e79f2af4e09d55b650d", "shortContent": "朱本卷一：“案韵同前首，疑同时答元素作也。”孔《谱》、薛本、邹王本从之，编熙宁七年甲寅（1074）。", "authors": [], "pressName": "崇文书局"}]', '', 'indent', 1542834808, '5bf55a0a9f54540070710f13', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640582, '绮罗香三首 · 其一 · 秦邮道中', NULL, 0, 223, 0, 1, '史承谦', NULL, 36972, '5bf616d4808ca40072027674', '清', 'shi', '诗', '', '', '风柳夸腰，露桃呈脸，倦客顿舒怀抱。摇漾晴云，不定浴波沙鸟。
映水郭、酒旆斜挑，倚高楼、眉痕初扫。记春帆，前度曾过，惊心又是隔年了。
佳辰何处祓禊，怊怅采兰人远，空磋长道。官烛分烟，一半韶光还好。
沾暮雨、只有杨花，系归心，不关芳草。奈今宵，尚滞江皋，楚天双岫杳。', '', '', '', NULL, '', 'center', 1542883150, '5bf616f1303f39005e9ec1af', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640583, '绮罗香三首 · 其二', NULL, 0, 223, 0, 1, '史承谦', NULL, 36972, '5bf616d4808ca40072027674', '清', 'ci', '词', '', '', '乍脱轻绵，旋飘弱絮，转眼流光如毂。频岁淮南客里，消他寒燠。
最难忘、前度欢游，不堪听、后庭遗曲。寻春芊芊，肠断是生绿。
天边无赖明月，又几回流照，玉钩斜足。酒荡襟怀，不禁乱红频扑。
牵昨梦、画舫冰丝，绕香心、玉妃脂盝。判携来，十样蛮笺，赋闲情几幅。', '', '', '', NULL, '', 'indent', 1542883178, '5bf61710303f39005e9ec346', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640584, '绮罗香三首 · 其三', NULL, 0, 223, 0, 1, '史承谦', NULL, 36972, '5bf616d4808ca40072027674', '清', 'ci', '词', '', '', '秋景平分，银蟾乍涌，帘幕重重低卷。碧杜红阑，何处玉箫声缓。
况寄与、班女新愁，只合付、谢郎雕管。恁迢遥、千里相随，萧萧落木赋情远。
天末净扫纤翳，丛桂飘来别院。晚香零乱。稽首姮娥，谁叩广寒宫殿？
想此际、一片清光，照人间、万般恩怨。只天涯，倦侣孤吟，画屏离思满。', '', '', '', NULL, '', 'indent', 1542883204, '5bf6172967f356005f68e92f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640585, '绮罗香 · 四首 · 其二', NULL, 0, 300, 0, 1, '奕绘', NULL, 21722, '5858efaf128fe10069b28d4b', '清', 'ci', '词', '', '', '绿颤钗虫，红移绣凤，犹记那人娇小。瘦削身量，容下春愁多少。
凭寄取、两线三针，便见透、千灵百巧。直回伊、几句相思，今番拼得被花恼。
新诗温李格调。写在衍波笺上，签儿封好。蜜意蜂情，埋怨不来青鸟。
消宿业、七卷莲华，践旧盟、一年芳草。算从头、雨梦风怀，有情天亦老。', '', '', '', NULL, '', 'indent', 1542883377, '5bf617d6303f39005e9ecc9d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640586, '绮罗香 · 四首 · 其三', NULL, 0, 300, 0, 1, '奕绘', NULL, 21722, '5858efaf128fe10069b28d4b', '清', 'ci', '词', '', '', '蝶梦香轻，花魂影媚，锦瑟悲凉弦柱。隋苑齐宫，消受凄清佳句。
飘碧瓦、何处秋声，挂红索、谁家芳树。百尺韩碑，诗人气概自神武。
昵昵儿女怨态，落落英雄壮志，断肠今古。獭祭空嘲，施注郑笺难补。
隔阆苑、一片飞烟，咽蝉声、五更疏露。洒琼瑰、万里桐花，丹山寻凤路。', '', '', '', NULL, '', 'indent', 1542883405, '5bf617f2303f39005e9ece19', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640587, '绮罗香 · 四首 · 其四', NULL, 0, 300, 0, 1, '奕绘', NULL, 21722, '5858efaf128fe10069b28d4b', '清', 'ci', '词', '', '', '隋苑芜荒，阿房火冷，时拂画檐轻坠。一点清辉，惯搅玉人无睡。
冲暗露、团扇亲兜，上鱼钥、小门深闭。恨此时、荒冢青磷，幽光孤另鲍家鬼。
凉风初撼木叶，纤月初沈树杪，早秋天气。些小微茫，隔院飞来三四。
照不见、醉梦生涯，只饱谙、夜深滋味。待收拾、晶盒芸囊，盟星书细字。
', '', '', '', NULL, '', 'indent', 1542883430, '5bf6180cfb4ffe005f558804', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640588, '绮罗香', NULL, 0, 106, 0, 1, '高士奇', NULL, 23253, '5858f11861ff4b006cb90145', '清', 'ci', '词', '', '', '圆颊涂脂，赪毬绉縠，碧叶亸枝深缀。一树霜红，频颤露床凉吹。
擘素指、不数橙黄，对珍盘、未输萸紫。爱携来、书几安排，越穸夺得晚峰翠。
垂虹桥外古水，占取山芡苔径，白花香细。风冷江天，独自冶容沉醉。
谁压倒、长庆诗人，漫留说、好秋吟纸。待年年、满摘筠篮，片帆湖上舣。', '', '', '', NULL, '', 'indent', 1542883477, '5bf6183a756571006af63b05', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640589, '绮罗香', NULL, 0, 90, 0, 1, '陈衍', NULL, 23136, '5858f0fb128fe1006b881f3e', '清', 'ci', '词', '', '', '簇蝶裙腰，钿蝉鬓影，前度嬉游春时节。绮陌香泥，昨夜初飘春雪。
妆点出、夹岸琼楼，映灯火、繁星明灭。那知他、瓦冷圆月，栏干偎罢被池热。
匆匆骊唱又发。谁向青青客舍，垂条攀折。淡粉轻烟，珍重泰娘留别。
邀顾曲、檀板梨园，约载花、玉骢金埒。总今日、回首音尘，个侬先愁绝。
', '', '', '', NULL, '', 'indent', 1542883600, '5bf618b5756571006af640d1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640590, '绮罗香 · 咏枕', NULL, 0, 46, 0, 1, '钱斐仲', NULL, 25996, '5858f3bfb123db00658deaba', '清', 'ci', '词', '', '', '蕙帐笼香，文裀藉玉，依约水晶帘里。好梦能圆，何必通中连理。
带三分、腻鬓花香，渍几点、相思情泪。最愁它、莲漏迢迢，背灯无语抱鸳被。
相依孤旅更苦。谁见尘床自拂，素衾漫启。待托归魂，还被晓鸡催起。
惯偷窥、双靥偎桃，也曾上、半肩行李。甚新来、愁病恹恹，日高犹倦倚。', '', '', '', NULL, '', 'indent', 1542883641, '5bf618defb4ffe005f559230', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640591, '南楼令', NULL, 1, 106, 0, 1, '高士奇', NULL, 23253, '5858f11861ff4b006cb90145', '清', 'ci', '词', '', '', '浅草乱山稠。惊沙黑水流。好春光，只似穷秋。刚得一枝花到眼，经雨打，又还休。
遥忆小红楼。玉人楼上头。月溶溶，催和香篝。肯信东风欺绝塞，都不许，把春留。', '', '', '', NULL, '', 'indent', 1542884263, '5bf61b4aee920a0068e4e9de', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640592, '齐桓下拜受胙', NULL, 9, 300, 0, 2, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '夏，会于葵丘，寻盟，且修好，礼也。
王使宰孔赐齐侯胙，曰：“天子有事于文武，使孔赐伯舅胙。”齐侯将下拜。孔曰：“且有后命。天子使孔曰：‘以伯舅耋老，加劳，赐一级，无下拜！”’对曰：“天威不违颜咫尺，小白余敢贪天子之命‘无下拜’！恐陨越于下，以遗天子羞，敢不下拜？”下，拜，登，受。', '本文出自《左传·僖公九年》。', '葵丘：宋国地名，在今河南兰考。一说在民权县东北。当时齐桓公与宋襄公、鲁僖公、卫文公、郑文公、许僖公、曹共公在葵丘相会。
寻盟：重温旧盟。齐桓公曾在曹国的洮会合过鲁、宋等诸侯，故称“寻盟”。寻，通“爝（jué）”，把冷了的东西重新温一温，引申为重续或重温。盟，在神前立誓缔约。
王：周襄王。宰孔：周襄王的使臣。宰，官名。孔，人名。胙（zuò）：古代祭祀时供的肉。
文、武：周文王与周武王。
伯舅：周天子尊称同姓诸侯为伯父或叔父，尊称异姓诸侯为伯舅。周，姬姓；齐，姜姓。
耋（dié）老：老迈，年高。耋，七十岁。
加劳：加上有功劳。一说重加慰劳。
违：离。颜：面。咫（zhǐ）尺：距离很近，八寸为咫。
小白：齐桓公名。余：我。敢：怎敢。贪：贪妄，意为恃宠而违礼法。陨越：坠落。指违背礼法。', '夏天，齐桓公在葵丘与各国诸侯聚会，为的是重申原来的盟誓，使大家更加和好。这是合乎礼的。
周襄王派宰孔赏赐齐侯一块祭肉。宰孔说：“天子正忙于祭祀文王、武王，特派我来，赏赐伯舅一块祭肉。”　齐侯刚要下阶拜谢。宰孔说：“且慢，后面还有命令哩。天子命我告诉您：‘伯舅年纪大了，加之对王室有功，特赐爵一级，不必下阶拜谢。’”齐桓公答谢：“天子的威严，离我不过咫尺，小白我岂敢贪受天子之命‘不下拜’？果真那样，只怕就会垮台，使天子也蒙受羞耻。怎敢不下阶拜谢！”　下阶，拜谢；登堂，领赏。', NULL, '', 'indent', 1542884946, '5bf61df8fb4ffe005f55cf8c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640593, '南楼令 · 六首 · 其一', NULL, 0, 223, 0, 1, '史承谦', NULL, 36972, '5bf616d4808ca40072027674', '清', 'ci', '词', '', '', '妆罢敛愁娥。单衣试薄罗。最怜他、道字娇讹。暗忆陈王曾解赋，肠断处，是凌波。
毕竟奈情何。年华小劫过。拨香灰、空对银荷。只隔珠帘同听雨，辜负杀、晚凉多。', '', '', '', NULL, '', 'indent', 1542885003, '5bf61e2d44d904005fcb5b14', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640594, '南楼令 · 六首 · 其二', NULL, 0, 223, 0, 1, '史承谦', NULL, 36972, '5bf616d4808ca40072027674', '清', 'ci', '词', '', '', '帘影卷湘纹。花前荡画裙。乍伤情、钗燕轻分。毕竟风尘堪得否，频说向、远行人。
惜别掩重门。凭谁验粉痕。展芳衾、独自黄昏。好是恹恹风月底，知两处、暗消魂。', '', '', '', NULL, '', 'indent', 1542885028, '5bf61e49756571006af6868f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640595, '南楼令 · 六首 · 其三', NULL, 0, 223, 0, 1, '史承谦', NULL, 36972, '5bf616d4808ca40072027674', '清', 'ci', '词', '', '', '深院下帘旌。薰炉小篆清。听疏疏、鸳瓦声轻。缀玉飘琼寒乍紧，问何处，春草生？
曾否破新正。连宵拥病醒。数芳辰、草晕花醒。独对东风应自笑，消不尽、绮罗情。', '', '', '', NULL, '', 'indent', 1542885054, '5bf61e64756571006af68893', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640596, '南楼令 · 六首 · 其四', NULL, 0, 223, 0, 1, '史承谦', NULL, 36972, '5bf616d4808ca40072027674', '清', 'ci', '词', '', '', '花底识罗敷。雕拢映碧梧。细腰身、应怯将雏。锦字银笺都不寄，多半是、少双鱼。
往事总模糊。钗盟半已虚。最难忘、一点香酥。今夜夜凉知有梦，还梦到、碧纱无。
', '', '', '', NULL, '', 'indent', 1542885084, '5bf61e81808ca4007202d348', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640597, '百字令 · 月夜过七里滩', NULL, 0, 1723, 2, 1, '厉鹗', NULL, 25122, '5858f2fa570c35006918079e', '清', 'ci', '词', 'https://baike.baidu.com/item/%E7%99%BE%E5%AD%97%E4%BB%A4%C2%B7%E7%A7%8B%E5%85%89%E4%BB%8A%E5%A4%9C/9752939?fr=aladdin&fromtitle=%E7%99%BE%E5%AD%97%E4%BB%A4%C2%B7%E6%9C%88%E5%A4%9C%E8%BF%87%E4%B8%83%E9', '月夜过七里滩，光景奇绝。歌此调，几令众山皆响。', '秋光今夜，向桐江，为写当年高躅。风露皆非人世有，自坐船头吹竹。万籁生山，一星在水，鹤梦疑重续。挐音遥去，西岩渔父初宿。
心忆汐社沉埋，清狂不见，使我形容独。寂寂冷萤三四点，穿破前湾茅屋。林净藏烟，峰危限月，帆影摇空绿。随风飘荡，白云还卧深谷。', '《百字令·秋光今夜》是清代文学家厉鹗创作的一首词。此词上片从听觉方面写乘船夜过七里滩时的景色，重点在刚出发时的思绪、行动和见闻；下片从视觉方面写月夜下七里滩的美景，由近而远，展现了一幅“桐江夜月图”。全词清俊秀逸，气象不俗，宛如画境，以写景为主，又融入对古代高士的崇敬之情和超然物外、情景神会的独特感受。', '百字令：词牌名，又名“念奴娇”等，双调，一百字，上下片各四仄韵，一韵到底。
七里滩：又称“七里濑”、“七里泷”，在浙江省桐庐县严陵山西边，两岸群峰峭立，绵延七里而水流湍急。
桐江：也称“桐庐江”，即钱塘江流经浙江省桐庐县的一段。
当年高躅（zhú）：当年高人严光隐居的遗踪。严光，字子陵，东汉会稽余姚人。与刘秀同学，刘秀称帝，他改名隐居。后刘秀召他入京，授谏议大夫，不受，归隐富春山。后世把他居游、垂钓之地名为严陵滩、严陵山、严陵钓台（亦称西台），均在桐江岸边。躅，足迹。
吹竹：吹竹笛。
万籁（lài）：各种秋声。
一星在水：星月倒映在水里。严光曾被指为客星夜侵帝座。
鹤梦：驾鹤成仙的梦。陆游《秋夜》：“露浓惊鹤梦，月冷伴蛩愁。”
挐（ráo）音：船桨拨水的声音。挐，通‘‘挠”，船桨。《庄子·渔父》：“方将杖挐而引其船。”
西岩渔父初宿：化用柳宗元《渔翁》中“渔翁夜傍西岩宿"句。
汐（xī）社沉埋：文天祥被杀后八年（1290年），谢翱与吴思齐、冯柱芳等登西台大哭遥祭，并把他们诗酒聚会之所称为“汐社”，取期晚而信之意。谢翱死后，被吴思齐等人葬在钓台。
清狂：放荡不羁的意思。
萤：即萤火虫。
峰危限月：峰高遮月。
帆影摇空绿：化用南朝乐府民歌《西洲曲》中“卷帘天自高，海水摇空绿"句。
白云远卧深谷：南齐时，陶弘景答齐高帝诏说：“山中何所有？岭上多白云。只可自怡悦，不堪持赠君。”后以白云象征隐士的高风。', '在一个月夜渡过七里滩，见到的风光景色奇异无比。我吟诵此词，声音差不多传遍各山。
今夜秋月的光，正洒向桐江。像专为照耀严光高隐的足迹。风景夜露都不是人世所有，我独坐船头吹奏竹笛。无数秋声产生于群山，星月倒映在水中，我怀疑又在驾鹤成仙的梦里。远处传来了船桨划水声，那是渔翁傍着西岩刚刚歇宿。
心中回忆谢翱被葬在这里，从那以后再不见狂放不羁的人，使我感到孤独。流萤静静地闪着三四点冷光，穿过了前湾的茅屋。清净的林中藏着烟雾，山峰高得遮住了月，帆影摇晃在倒映翠峰的绿水里。我乘船随着流水飘荡，远处的白云静卧深谷。', '[{"bookId": "60fc157134bfda01e0e91549", "bookTitle": "元明清词鉴赏辞典（新一版）", "articleId": "610e86610f8fda5565052315", "shortContent": "富春江流经桐庐段称桐江。上游七里滩又名七里泷、七里濑，连亘七里，两岸众山夹峙，水驰如箭，有“富春江小三峡”之称。江边严子陵钓台，双峰相对，称东、西台。东台为东汉严光隐居垂钓处；西台为南宋遗民诗人谢翱恸哭文天祥处，其与友朋聚会之所名汐社。作者于清康熙六十年（1721）舟过此地时，适逢秋夜，江上之星月、风露、桨声、帆影，岸上之烟林、危峰、萤火、茅屋，东、西钓台上令人千古仰止之严、谢的故址遗踪，融会成疑...", "authors": ["陈邦炎"], "pressName": "上海辞书出版社"}]', '清代陈廷焯：无一字不清俊。炼字炼句，归于纯雅，此境亦未易到也。（《白雨斋词话》）
清代谭献：与洞庭词壮浪幽情，各极其用。（《箧中词》）', 'indent', 1542968524, '5bf7646167f356005f7788a9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640598, '百字令 · 宿汉儿村', NULL, 2, 395, 0, 1, '纳兰性德', NULL, 10020, '57b8eab42e958a005fa4c3f8', '清', 'ci', '词', 'https://baike.baidu.com/item/%E7%99%BE%E5%AD%97%E4%BB%A4%C2%B7%E5%AE%BF%E6%B1%89%E5%84%BF%E6%9D%91/22208808?fr=aladdin', '', '无情野火，趁西风烧遍、天涯芳草。榆塞重来冰雪里，冷入鬓丝吹老。牧马长嘶，征笳乱动，并入愁怀抱。定知今夕，庾郎瘦损多少。便是脑满肠肥，尚难消受，此荒烟落照。何况文园憔悴后，非复酒垆风调。回乐峰寒，受降城远，梦向家山绕。茫茫百感，凭高唯有清啸。', '《百字令·宿汉儿村》是清代词人纳兰性得所写的一首词。上片写塞上荒凉萧索，凄冷苦寒之景，再借庾郎之典映己，毒达了凄然伤感的情怀。下片以“便是”“何况”的迭进句法，并用文园憔悴等典实，突出此刻的乡愁客思，愁怀难遣。结尾处以“惟有清啸”宕起远神，情韵更为深挚感人。全词将词人内心的凄然之情表达地淋漓尽致。', '百字令：词牌名，即念奴娇。双调一百字，上下片各十句四仄韵。
汉儿村：在今辽宁省朝阳县境内。
榆塞：榆关，即山海关。
“牧马”两句：汉李陵《答苏武书》：“胡笳互动，牧马悲鸣。”
庾郎：北周诗人庾信。他身经丧乱，作品饱含愁思，曾作《愁赋》。
脑满肠肥：不操心的人，吃得饱，养得胖。
文园：指司马相如。
酒垆风调：据《史记·司马相如列传》，司马相如曾和妻子卓文君在酒店当垆卖酒。回乐峰：在今宁夏灵武西南。
受降城：有三处，这里泛指边塞。', '无情的野火，趁着阵阵西风，烧光了天涯芳草。冰天雪地里再次来到边塞，鬓发染霜，我已被寒风吹老。牧马长嘶，胡笳乱鸣，一并闯进我忧愁的怀抱。定然知道今天晚上，我这个庾信般多愁善感的诗人，会瘦掉多少。
即便是脑满肠肥的过去，尚且难以消受，这里的荒烟落照。更何况司马相如早已憔悴，不再有当垆卖酒的风流格调。回乐峰彻骨寒冷，受降城如此僻远，思念家乡的梦儿夜夜萦绕。登高凭栏，四野茫茫，不由百感交织，只能向着远方，发出一声清啸。', '[{"bookId": "6277f64234359466e83ac99f", "bookTitle": "纳兰词全集", "articleId": "63126e3fc26cbf3417f091b1", "shortContent": "词写容若再度赴边时的感触。重来山海关，已是寒风呼晡，冰天雪地，加之朔风吹叶，万里尘昏，胡笳四起，牧马长鸣，真可谓“笳声未断肠先断”，不由深深体会到了当年庾信羁留北地的心情。这种荒芜凄凉的场景，即使脑满肠肥者也难以消受，更何况这些年来自己也日益憔悴，不复往日青春年少，风流不羁。词之作期，较难确定，或当为康熙二十一年（1682）秋冬。", "authors": [], "pressName": "崇文书局"}]', '现代作家何雅苓：此篇步步写来托，感情所至，自有其沉重的扣人心弦的力量。（《纳兰的词》）', 'indent', 1542968577, '5bf764a5ee920a0068fde5e9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640599, '百字令 · 刘邦彦招饮竹东馆赏桂花', NULL, 0, 594, 0, 1, '史鉴', NULL, 14715, '5858e9738d6d810065c32ff7', '明', 'ci', '词', '', '', '竹东庄上，记当年春尽，归舟曾歇。莫雨和风催客去，猛地作时还辍。
小馆茶香，行厨酒尽，执手难为别。归家南望，寸肠几度千结。
谁道买棹重游，主人情重，樽俎依前设。桂树团香纤月露，渐近中秋时节。
试问姮娥，今年才子，谁把高枝折。夜深无语，霏霏满地金屑。
', '', '', '', NULL, '', 'indent', 1542968654, '5bf764f467f356005f778f95', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640600, '百字令 · 赠妓', NULL, 1, 594, 0, 1, '史鉴', NULL, 14715, '5858e9738d6d810065c32ff7', '明', 'ci', '词', '', '', '紫薇楼下，记持觞，醉把名花相酹。爱尔玉兰名字好，况乃色香幽媚。
娟净无瑕，清芬离俗，临去犹凝睇。时移事换，梦中频见佳丽。
谁道买笑吴门，美人携手，俨与花相似。气味风标无两样，疑是花神游戏。
娇啭歌喉，明珠一串，散落金盘脆。曲终凝望，碧云犹在天际。', '', '', '', NULL, '', 'indent', 1542968687, '5bf76515303f39005ead90d3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640601, '百字令 · 二月下浣客成都，游花市，漫拈', NULL, 0, 116, 0, 2, '潘榕', NULL, 25803, '5858f3928e450a006c7fed19', '清', 'ci', '词', '', '', '锦官城外，览群芳、紫陌红尘游遍。百卉争妍延胜赏，铃索彩幡风飐。
芍药娇姿，海棠媚影，到眼春撩乱。香云粉雾，花光相映人面。
惊艳。引蝶成痴，惹蜂作闹，喧鸟声都颤。故态犹存狂未减，我也魂销无算。
老尚情多，愁将酒扫，买醉归来倦。灯残梦醒，客衾依旧寒恋。', '', '', '', NULL, '', 'indent', 1542968967, '5bf7662cee920a0068fe0661', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640602, '百字令 · 送春，叠游花市韵', NULL, 0, 116, 0, 2, '潘榕', NULL, 25803, '5858f3928e450a006c7fed19', '清', 'ci', '词', '', '', '阑珊花事，惜余春、看到荼蘼开遍。诗记才迎词又送，袅袅吟魂柔飐。
笑也含愁，醒还似梦，离绪萦心乱。恨随流水，残红飞落波面。
清玩。竹筱风摇，柳梢月挂，弄影巍巍颤。触感相思添几许，别后应难猜算。
凤子情慵，莺儿语懒，我客天涯倦。曰归未得，故园烟景空恋。', '', '', '', NULL, '', 'indent', 1542969011, '5bf766570b616000672074ba', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640603, '百字令 · 观灯归后醉饮，度此', NULL, 0, 116, 0, 1, '潘榕', NULL, 25803, '5858f3928e450a006c7fed19', '清', 'ci', '词', '', '', '六街灯火，踏欢场、游倦归来行缓。爆竹声声声不断，听彻元宵弦管。
楼望邻家，筵开别院，烧烛帘高卷。盈盈笑语，耳轮风过吹满。
凄惋。老恨年催，境随梦幻，少日狂都减。心字香销灰已冷，访翠偎红情懒。
圆月窥愁，寒檠瘦影，坐数更长短。沉思旧事，无言姑醉瑶盏。', '', '', '', NULL, '', 'indent', 1542969052, '5bf76681303f39005eada49b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640604, '九江闻雁', NULL, 3, 3, 2, 0, '陈均', NULL, 36973, '5bf78d95ee920a006801c35c', '宋', 'shi', '诗', '', '', '烟波渺渺梦悠悠，家在江南海尽头。
音信稀疏兄弟隔，一声新雁九江秋。', '《九江闻雁》是南宋陈公齐时任江西提刑的七言绝句，以「思乡」为题材。
这首绝句妙在头尾两句。
首句似乎是将崔颢「日暮乡关何处是，烟波江上使人愁」和岑嘉州「枕上片时春梦中，行尽江南数千里」加以熔化提炼而成，七个字里景中含情，情中含景，语言简练，感情浓郁。而「渺渺」和「悠悠」两个重叠词，把「故园渺何处，归思方悠哉」（韦苏州《闻雁》）这一意境渲染、烘托出来，使感情色彩显得更浓重，收到情景相生的艺术效果。
末句又像是把吴子华「独羡一声南去雁，满天风雨到汀洲」，钱考功「俱是南来客，怜君缀一行」，姜白石「年年数尽秋风字，想见江南摇落时」熔化提炼而成。诗人独立浔阳江头，眼望「枫叶荻花秋瑟瑟」，耳闻「雁阵惊寒，声断衡阳之浦」，忍不住「却道天凉好个秋」。纯乎写景，尽是抒情，「一切景语皆情语」，确实是绝唱。王船山曰：「不能作景语，又何能作情语耶？」这种「以写景之心理言情，则身心中独喻之微，轻安拈出」的手法最妙。
诗中之「雁」：秋去春来的候鸟鸿雁，和月亮一样，也是触动诗人们乡思的重要媒介，因而在乡思类诗词中出现的频率也非常髙。如：「烟渡渺渺梦悠悠，家在江南海尽头。音信稀疏兄弟隔，一声新雁九江秋。」《九江闻雁》「一声新雁」和「九江秋」构成因果关系，看似很不合情，却是顺理成章，因为大雁南飞代表了秋天的到来，而这新雁一声最能触动人的乡思。', '九江：今属江西省。
江南海尽头：陈公齐家乡位于浙江最南端，今浙江苍南蒲城城西。', '', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea7402e6a6b501f961b46", "shortContent": "此诗抒写乡情。诗人的家乡在福建莆田，兄弟们都在故乡，而自己“独在异乡为异客”（王维《九月九日忆山东兄弟》），只身在九江，难得收到来自家乡的口信或书信。离家日久，不免怀念日深。初秋的一天傍晚，诗人独自来到长江边上。但见暮霭沉沉，江水浩浩，一种“日暮乡关何处是，烟波江上使人愁”（崔颢《黄鹤楼》）的感觉，不觉涌上心头。\n首句的“烟波渺渺”，当是即目所见。“烟波”透露出，地点是在江边，时间是暮色苍茫的傍晚...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}]', '', 'center', 1542980087, '5bf7909d303f39005eb047e4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640613, '塞翁吟 · 短绿抽堤草', NULL, 0, 780, 0, 1, '仇远', NULL, 10355, '57b9221c165abd0054c0e90e', '元', 'ci', '词', '', '   ', '短绿抽堤草，芳信未许花知。尚留冻梗冰枝。藓石雪消迟。方塘水浅鸳鸯冷，沙际水翼相依。拾翠约，踏青期。终是乐游稀。相思。江南远，渔汀渺渺，还又是、梅花谢时。有多少、旧愁新恨，纵罗虬、妙曲风流，怎比红儿。何时再得，画鷁摇春，丰乐楼西。 ', '', '', '', NULL, '', 'indent', 1543229582, '5bfb602d756571006a372b4e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640614, '塞翁吟', NULL, 0, 351, 0, 1, '陈允平', NULL, 10437, '582c71d1570c35006ce955c9', '宋', 'ci', '词', '', '', '睡起鸾钗亸，金约鬓影胧。檐佩冷，玉丁东。镜里对芙蓉。秦筝倦理梁尘暗，惆怅燕子楼空。山万垒，水千重。一叶漫题红。
匆匆。从别后，残云断雨，余香在、鲛绡帐中。更懊恨、灯花无准，写幽愫、锦织回文，小字斜封。无人为托，欲倩宾鸿。立尽西风。 ', '', '', '', NULL, '', 'indent', 1543229664, '5bfb6086fb4ffe2c75c01e9c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640615, '塞翁吟 · 苇湾泛秋，晚莲向尽，以美成涩体写之', NULL, 0, 628, 0, 1, '朱祖谋', NULL, 19930, '5858edfc1b69e60056f650e8', '清', 'ci', '词', '', '', '乱笛回塘路，催换野色珑璁。故情断，坠衣红。涴急雨阑东。
客怀未耐秋摇兀，慵对艳锦屏空。暗里忆，旧珍丛。
负一舸匆匆。
花宫。星期近，南飞倦翼，憔悴与、津梁梦中。料今夜、西池露下，盼不到、太乙仙槎，怨入高鸿。
鸳鸯最苦，睡稳荒波，犹梦薰风。', '', '', '', NULL, '', 'indent', 1543230001, '5bfb61d744d904005f0c0110', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640616, '塞翁吟 · 秋日过竹枝庵访灵机上人不遇与寒松上人茗谈', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '出郭秋光好，黄叶飒沓霜空。筱径织，石泉通。漱碎玉淙淙。
三生堂后名僧至，乘兴杖笠过从。拟问取，寺门松。
可仍旧如龙。
桥东。谁延伫，虎溪三笑，逢相识、庐山远公。说晓起、秋山有信，趣昨夜、出岫闲云，仍返山中。
姑留软语，饱看禅窗，瘦槲枯枫。', '', '', '', NULL, '', 'indent', 1543230052, '5bfb620a303f39005edff341', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640617, '塞翁吟 · 暮色催更鼓', NULL, 0, 94, 0, 1, '方千里', NULL, 18235, '5858ec898d6d810065c347ec', '宋', 'ci', '词', '', '', '暮色催更鼓，庭户月影胧。记旧迹、玉楼东。看枕上芙蓉。云屏几轴江南画，香篆烬暖烟空。睡起处，绣衾重。尚残酒潮红。
忡忡。从分散，歌稀宴小，怀丽质，浑如梦中。苦寂寞、离情万绪，似秋后、怯雨芭蕉，不展愁封。何时细语，此夕相思，曾对西风。 ', '', '', '', NULL, '', 'indent', 1543230222, '5bfb62b5ee920a00684eb036', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640618, '玲珑四犯 · 除夕游花市', NULL, 0, 254, 0, 1, '陈洵', NULL, 23117, '5858f0f71b69e6006cb147a5', '清', 'ci', '词', '', '', '如锦年华，趁闹极珠灯，一夜流转。故国天涯，谁念岁穷家远。
闻道绣屋春多，怎教道、灌园人健。料四时、乐事轻换。
偏是堕梅先怨。
去年风雨悭游便。意匆匆、恨春迟见。钗云梦底都寻得，闲记供消遣。
多少镜约袖盟，又暗里欢悰隔断。向市桥立过，还放下，情千万。 ', '', '', '', NULL, '', 'indent', 1543232934, '5bfb6d4b44d904005f0cb391', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640619, '玲珑四犯 · 题叶霓仙遗词，兼寄其弟琴西', NULL, 0, 40, 0, 1, '冯幵', NULL, 24776, '5858f2a6b123db00658de1f4', '清', 'ci', '词', '', '', '篁孔引悽，桐丝流恨，秋声绵渺无际。吹花弹泪歰，滴粉搓愁细。
沉吟酒边心事。甚华年、只成憔悴。玉笥云薶，金奁月冷，寂寞旧风味。
天涯杜陵兄弟。念京华冠盖，飘泊非计。微官归不得，息影车尘底。
俊游转眼余萧瑟，怕低唱、浅斟都废。空雪涕。斜阳外、暮鸦啼起。', '', '', '', NULL, '', 'indent', 1543233031, '5bfb6dad44d904005f0cba8a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640620, '玲珑四犯', NULL, 0, 167, 0, 1, '冯煦', NULL, 24786, '5858f2a98d6d810065c37af8', '清', 'ci', '词', '', '', '隔浦暗镫，孤城清角，天涯能几相见。断桥西去月，照影惊萧散。
而今俊游渐懒。算烟波、再来都换。一别浮尘，十年漂梗，芳序黯将晚。
无人地凭阑遍。望淮南落木，离绪何限。夜阑潮信稳，梦与轻鸿远。
曾携手处销凝甚，又千里、霜空云乱。谁更遣。愁来怕、尊中酒浅。', '', '', '', NULL, '', 'indent', 1543233095, '5bfb6debee920a00684fad20', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640621, '玲珑四犯 · 寂市', NULL, 0, 3925, 0, 1, '姚燮', NULL, 21980, '5858efed128fe10069b28fb0', '清', 'ci', '词', '', '', '结堡陋村，攒闾偏郭，居民聊事生产。望旗三五叶，乱柳相飘绾。
盘飧苦难猝辨，剩堆笼、宿雨零苋。饼灶妪闲，酒垆佣睡，饥雀渐飞散。
铜街递、圜平衍。有锦衣侠贾，筹亿持万。晓烟金气结，夜火珠虹烂。
寻常博得妻孥饱，恰隐仗、肩筐传贩。天又晚。听灯栅、盲词消懒。', '', '', '', NULL, '', 'indent', 1543233295, '5bfb6eb5303f39005ee0b1b6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640622, '玲珑四犯 · 登德清玉尘峰浮远楼', NULL, 0, 10, 0, 1, '杨夔生', NULL, 36974, '5bfb6f03ee920a00684fc52d', '清', 'ci', '词', '', '', '叠巇砌蓝，峭岑镵碧，飞楼缥缈云路。浩歌携谢屐，远蹑卢敖步。
危楯玲珑漫抚。倚高寒、鬓丝千缕。半壁晴湍，数峰苍石，霞杪画秋树。
空翠冷，沾衣屦，乍泠泠松籁，如听风雨。雁边秋去远，天澹长烟暮。
乾坤静里堪舒啸，又打起、清时钟鼓。悄延伫。眺绿野，几家桑苎。', '', '', '', NULL, '', 'indent', 1543233391, '5bfb6f13756571006a3811ef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640623, '玲珑四犯 · 恽正叔西湖泛月图为陈玉几赋', NULL, 0, 1723, 0, 1, '厉鹗', NULL, 25122, '5858f2fa570c35006918079e', '清', 'ci', '词', '', '', '寒玉砌澜，修蛾横绿，青天明月初涌。人间今夕好，柳外凉阴重，沈沈两堤跨蝀。
问何人、曲声吹送。酒面邀秋，船头照影，吟思欲飞动。
烟空远眸堪纵。想菱飔乱起，荷气深拥。清欢惊易晓，光景随尘鞚。
南田词客今仙去，剩沙鸟、来成幽梦。谁与共。裴回写、闲情数种。', '', '', '', NULL, '', 'indent', 1543233445, '5bfb6f4a756571006a38164b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640624, '玲珑四犯', NULL, 0, 101, 0, 1, '端木埰', NULL, 36968, '5becee44fb4ffe006a50153e', '清', 'ci', '词', '', '', '漆灯晕绿，悲声起，幽居一味凄寂。夜台睡稳，何缘更露，尘中声迹。
泉扃悄阒，想也念人间故戚。镇伶俜、惊风怯影霜叶共萧槭。
凄绝荒坟畔，月淡梨、雨昏松枥。翠楼画阁剩如今、土华凝碧。
待访天亲，又朝市，沧桑几历。悄呜咽，泣绕断梗伴夜蟀。', '', '', '', NULL, '', 'indent', 1543233489, '5bfb6f7744d904005f0cd846', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640625, '玲珑四犯 · 咏墨纱灯', NULL, 0, 191, 0, 1, '李符', NULL, 20901, '5858eee18e450a006c7fc439', '清', 'ci', '词', '', '', '谁擘珊瑚，嵌几幅蝉纱，向玳梁挂。淡墨轻匀，笼住烛花红射。
黯黯片镜无光，偏照出、粉妆姚冶。似朦胧、蟾彩凝烟，真有药娥飞下。
更看面面花枝好，讶双蕖、乱开春夜。依稀四角悬针字，猜谜消琼斝。
蛾绿忽倚玉屏，荑苗指、眼波微泻。露月华裙子，一般颜色，斗他图画。', '', '', '', NULL, '', 'indent', 1543233525, '5bfb6f9b0b616000675382c2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640628, '生查子 · 陌上郎', NULL, 1, 877, 3, 0, '贺铸', NULL, 10098, '57b9bbb28ac2470063feff0a', '宋', 'ci', '词', '', '', '西津海鹘舟，径度沧江雨。双艣本无情，鸦轧如人语。
挥金陌上郎，化石山头妇。何物系君心，三岁扶床女。', '此词运用将物拟人、以物语言己情的手法，以「艣语」谴责、批判了玩弄女性的负心之徒，对于被侮辱、被损害的不幸女子予以深切同情。
起首两句，浓墨重彩地描绘出一幅沧江烟雨送别图。在一派烟雨之中，那艘轻捷的船儿离开渡口，径直地渡过沧江，消失在迷茫的远方。这里，词人没有直接去写送者和行者，更没有直接去写送者的悲恸和行者的决绝，而衹以津、舟、江、雨所组成的浑茫开阔的图画把二者都包容在其中。词人在「度」之前加一「径」字，大有深意，尤言即使是妻悲女啼，情意绵婉；即使是气候恶劣，雨急浪险，船还是一点也不犹豫，一点也不留恋地径直而去。
以下两句，词人采用「移情于物」的手法，出人意料地把双艣摇动时连续而又低沉的鸦轧声当作触媒，产生「荒诞」而又入情的设想。连这本无生命，本无感情的「双艣」。
过片为「艣」「人语」之内容，实际上也就是词人的内心独白 。前两句用典 ，以对偶句出之。刘向《列女传》：鲁人秋胡外出作官，五年乃归。未至家，见路旁妇人采桑，悦之，以金引诱，遭妇坚拒，回家後始知为其妻。这里借秋胡以指那些用情不专、二三其德的男了。又《太平寰宇记·卷一百〇五·〈太平州·当涂县〉》载：「望夫山，在县西四十七里。昔人往楚，累岁不还 ，其妻登此山望失，乃化为石。」这里指纯朴坚贞、忠于爱情的妻子。这两个各自独立完整的故事 ，现在被词人借双橹之「口」把二者并列在一起，顿时就产生极为强烈的效果 ：一方无行，一方痴情；一方薄幸，一方坚贞。最后两句，以反诘的形式诚挚委婉地劝慰负心汉，给人以强烈的心灵震撼。词人在「何物系君心」这一问之中，已经包含了对负心丈夫的谴责。接着，又以家中还有刚刚能够扶着床沿走路的三岁女儿来进行再一次的劝喻，感情色彩更加强烈。', '', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74bf911759740c9aa377", "shortContent": "在长期的中国封建社会里，由于妇女一直作为男子的附庸，因而就产生了许多“痴心女子负心汉”的爱情和家庭生活悲剧。古代进步作家在涉及这一主题时，往往毫不犹豫地把同情给予那些不幸的女子，而把谴责批判的矛头直指负心之徒。方回哲宗元祐四年（1089）八月在历阳曾赋《望夫石》一诗，借当涂“望夫山”的传说歌咏了这一主题，“交游间无不爱者”（《王直方诗话》）。很可能在同时，他又写了这首词，再一次表达了自己鲜明的爱憎...", "authors": ["李维新"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5c5d635634aee3e9aa8", "shortContent": "在长期的中国封建社会里，由于妇女一直作为男子的附庸，因而就产生了许多“痴心女子负心汉”的爱情和家庭生活悲剧。古代进步作家在涉及这一主题时，往往毫不犹豫地把同情给予那些不幸的女子，而把谴责批判的矛头直指负心之徒。方回哲宗元祐四年（1089）八月在历阳曾赋《望夫石》一诗，借当涂“望夫山”的传说歌咏了这一主题，“交游间无不爱者”（《王直方诗话》）。很可能在同时，他又写了这首词，再一次表达了自己鲜明的爱憎...", "authors": ["李维新"], "pressName": "上海辞书出版社"}]', '', 'indent', 1543265902, '5bfbee1344d904005f14e03f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640629, '巫山一段云 · 阆苑年华永', NULL, 0, 225, 0, 1, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', '', '', '阆苑年华永，嬉游别是情。人间三度见河清。一番碧桃成。
金母忍将轻摘。留宴鳌峰真客。红狵闲卧吠斜阳。方朔敢偷尝。 ', '', '阆苑：传说中神仙的居所。
年华：时光。
嬉游：游玩。
碧桃：即神话中的蟠桃，三千年一结果，为西王母所有。
真客：仙客。
狵：多毛的狗。相传为仙家之犬。
方朔：即东方朔。', '阆苑的西王母长生不老。在这里游玩却别有一番情趣。人间三千年见到黄河三次清澈，西王母的仙桃才成熟一次。
西王母忍心将仙桃轻易地摘下，留着宴请龟山之峰的神仙食用。红色多毛狗安闲趴伏着，面对斜阳高叫不停。岁星东方朔敢把仙桃偷尝。', NULL, '', 'indent', 1543316077, '5bfcb214ee920a00686a2a84', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640630, '巫山一段云 · 萧氏贤夫妇', NULL, 0, 225, 0, 1, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', '', '', '萧氏贤夫妇，茅家好弟兄。羽轮飙驾赴层城。高会尽仙卿。
一曲云谣为寿。倒尽金壶碧酒。醺酣争撼白榆花。踏碎九光霞。 ', '“萧氏贤夫妇”，咏仙家嬉游宴饮之乐。结尾两句想象奇特，色彩斑斓，摇曳多姿，生动有趣。', '萧氏贤夫妇：指萧史弄玉夫妇。
茅家好弟兄：指茅盈、茅固、茅衷三兄弟。相传一齐成仙。
飙（biāo）驾：御风而行的车。层城：古神话中的地名。
高会：大宴会。
云谣：即《白云谣》。为寿：祝福。
白榆：树名，传说仙境中有白榆树。
九光霞：五彩缤纷的云霞。', '修道成仙的萧史与弄玉，是一对好夫妇；得道为仙的茅盈、茅固、茅衷，是茅家好兄弟。驾起羽轮和飙车，赶赴西王母所居的层城。这里举行盛大宴会，与会者全是仙界的贵官。
一曲云和之笛所奏的仙歌，为西王母祝寿。喝完了金壶里的美酒，酣醉的众仙争摇白榆花，踏碎了五光十色的云霞。', NULL, '', 'indent', 1543316172, '5bfcb272756571006a47677e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640680, '暗香', NULL, 1, 513, 0, 1, '吴潜', NULL, 10788, '5858e5d8570c350069179bc0', '宋', 'ci', '词', '', '闻尧章死西湖，尝助诸丈为殡之，今又不知几年矣。自昭忽录示尧章暗香、疏影二词，因信手酬酢，并赓潘德久之诗云。', '晓霜一色。正恁时陇上，征人横笛。驿使不来，借问孤芳为谁折。休说和羹未晚，都付与、逋仙吟笔。算只是，野店疏篱，樵子共争席。
寒圃，众籁寂。想暗里度香，万斛堆积。恼他鼻观，巡索还无最堪忆。萼绿堂前一笑，封老干、苔青莓碧。春漏也，应念我、要归未得。 ', '', '', '', NULL, '', 'indent', 1543835848, '5c04a06e9f545400677c4b41', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642100, '幽梦影 · 卷一 · 六十九', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '凡花色之娇媚者，多不甚香；瓣之千层者，多不结实；甚矣全才之难也。兼之者，其惟莲乎？', '', '', '', NULL, '尤谨庸曰：全才必为人所忌，莲花故名君子。', 'indent', 1556017149, '5cbe7f7ba91c9377aab36897', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640631, '巫山一段云 · 六六真游洞', NULL, 0, 225, 0, 1, '柳永', NULL, 10060, '57b94edc2e958a005fa80261', '宋', 'ci', '词', '', '', '六六真游洞，三三物外天。九班麟稳破非烟。何处按云轩。
昨夜麻姑陪宴。又话蓬莱清浅。几回山脚弄云涛。仿佛见金鳌。 ', '“六六真游洞”，咏游仙，仙境、仙人、仙游、仙踪，境界无限，想象奇诡，写来颇有气势。', '巫山一段云：词牌名。
六六真游洞：即三十六洞天，道家称神仙居住的地方。
三三物外天：即九天。
九班麟稳：即九仙。
云轩：神仙所乘之车。
麻姑：女仙名。
蓬莱：仙山名。
金鳌：是中国神话中的一种神龟。通常是权利和财富的象征。头尾似龙，身似陆龟，全身金色，生活在海里的神龟。', '三十六洞天，世外九天，仙女舞班，麒步稳称，舞步轻妙，破彩云。何处可摸到云台之轩。
昨夜仙女麻姑陪同参加宴会，又说仙山蓬莱东海的清澈不深。仙女麻姑曾数次到蓬莱、方丈、瀛洲三仙山，弄其云涛而见其负山之金龟。', NULL, '', 'indent', 1543316236, '5bfcb2b3303f39005ef010c7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640632, '巫山一段云', NULL, 1, 6729, 0, 1, '屈大均', NULL, 15479, '5858ea131b69e6006cb11146', '清', 'ci', '词', '', '', '片片瑶姬影，飞来最有情。朝朝暮暮不分明，愁与梦魂凝。
云湿碍行雨，峰开似列屏。髻鬟染得一天青。一朵一仙灵。', '', '', '', NULL, '', 'indent', 1543316466, '5bfcb399fb4ffe2c75d05f10', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640634, '鹊踏枝 · 六曲阑干偎碧树', NULL, 173, 105, 2, 3, '冯延巳', NULL, 10045, '57b90551128fe10054c9ae3e', '五代十国', 'ci', '词', 'https://baike.baidu.com/item/%E9%B9%8A%E8%B8%8F%E6%9E%9D%C2%B7%E5%85%AD%E6%9B%B2%E9%98%91%E5%B9%B2%E5%81%8E%E7%A2%A7%E6%A0%91/3067549?fr=aladdin', '', '六曲阑干偎碧树，杨柳风轻，展尽黄金缕。谁把钿筝移玉柱，穿帘海燕双飞去。
满眼游丝兼落絮，红杏开时，一霎清明雨。浓睡觉来莺乱语，惊残好梦无寻处。', '《鹊踏枝·六曲阑干偎碧树》为南唐词人冯延巳所作，通过对闺情的描写，感叹春光易逝，寓含词人对南唐小朝廷国运颓危的无奈感叹之情。', '偎：紧靠着。
黄金缕：形容嫩黄的柳条，如同丝丝金线一般。
钿筝：用金翠宝石装饰的筝，玉柱：筝上定弦用的玉制码子。
海燕：传说燕子来自海上，故称“海燕”。双飞，一作“惊飞”。以上两句是写有人弹起筝来，双燕由帘内惊起飞走。
游丝：指在空中飞扬的虫丝。落絮：指飘落的柳絮。
一霎（shà）：一阵子。唐孟郊《春后雨》诗：“昨夜一霎雨，天意苏群物。”
觉来：醒来。莺乱语，一作“慵不语”。', '在绿阴丛中，一座别致、幽静的小楼悄然独立，曲曲折折的栏杆紧紧依偎着碧树，两者相映成趣。春风和煦轻柔，鹅黄嫩绿、如丝如缕的杨柳在风中款款摆动腰肢，摇曳多姿。在这寂静的环境中突然响起了琮琮的筝声，闺中安栖的燕子，被筝声惊起，双双穿帘飞去了。
春光明媚，晴空万里，游丝袅袅，柳絮翻飞，这已是暮春景象了，正当杏花盛开，娇艳无比之际，却下起了一阵小雨。在如此深重的幽情之中，她不由沉沉睡去，正在睡酣梦甜之际，却被窗外清脆的莺啼声惊起，而美梦也再也无寻处了。', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e748fdbb8b379ee08dda4", "shortContent": "春日，某家闺阁中传出了哀怨的弹筝声，引起了词人的想象。冯延巳的这首词，大概就是这样写出来的，是拟写闺情之作。\n上片从春光写起。“六曲阑干偎碧树。杨柳风轻，展尽黄金缕。”春天来到了这幽静的小庭深院。曲曲红阑，绿荫环绕；院中的杨柳，鹅黄嫩绿，如丝如缕，一齐在春风中轻盈地飞舞。写风轻，其实是写柳条的轻柔，借以表现其摇曳多姿。再进一层，写这杨柳在春风的抚弄下，怡然地摆动腰肢，又何尝不是反衬闺中人无所慰藉的...", "authors": ["孙映逵"], "pressName": "上海辞书出版社"}, {"bookId": "62de388c7706b0251984eec4", "bookTitle": "唐五代词三百首鉴赏辞典", "articleId": "6303892dbb31680ae4c4b4dc", "shortContent": "春日，某家闺阁中传出了哀怨的弹筝声，引起了词人的想象。冯延巳的这首词，大概就是这样写出来的，是拟写闺情之作。\n\n上片从春光写起。“六曲阑干偎碧树。杨柳风轻，展尽黄金缕。”春天来到了这幽静的小庭深院。曲曲红阑，绿荫环绕；院中的杨柳，鹅黄嫩绿，如丝如缕，一齐在春风中轻盈地飞舞。写风轻，其实是写柳条的轻柔，借以表现其摇曳多姿。再进一层，写这杨柳在春风的抚弄下，怡然地摆动腰肢，又何尝不是反衬闺中人无所慰藉...", "authors": ["孙映逵"], "pressName": "上海辞书出版社"}, {"bookId": "6277583f5b7e9043f1123826", "bookTitle": "宋词三百首鉴赏辞典", "articleId": "63126f3c7f0b9738b369b0ec", "shortContent": "关于此词作者，历来争议纷纷。《宋词三百首》记载为晏殊作，见晏殊《珠玉词》，亦见于冯延巳《阳春集》，《花庵词选》作欧阳修词。作者的争议也体现出花间词派的固定性以及流派风格的相似性，无论是风格、意象、意境、还是表达的情感，都十分相似，才让人难辨作者身份。这里依据《宋词三百首》，将其归于晏殊笔下。\n庭院中回廊曲折，阑干在回环处似乎与垂柳轻轻依偎着。春风骀荡，柳枝轻拂，嫩黄的枝叶尽显柔和妩媚。在这一幅春光...", "authors": ["邓安琪"], "pressName": "崇文书局"}]', '谭献《复堂词话》评此词云：“金碧山水，一片空漾，此正周氏（周济）所谓‘有寄托入，无寄托出’也。”
又，评“满眼游丝兼落絮”句：感；评“一霎清明雨”句：境；评“浓睡觉来莺乱语”句：人；评“惊残好梦无寻处”句：情。
陈廷焯《词则·天稚集》卷一亦云此词：“忧谗畏讥，思深意苦，信其言不必论其人也。”
又《云韶集》卷一：“雅秀工丽，是欧公之祖。字字和雅，字字秀丽，词中正格也。”（南京图书馆藏清钞本）
又《白雨斋词话（稿本）》卷六：“《蝶恋花》一调，最为古雅，‘六曲阑干’唱后，几成绝句。”
蔡嵩云《柯亭词论》：“正中《鹊踏枝》十四章，郁伊惝倪究莫测其意惽。刘融斋谓其词流连光景，惆怅自怜。冯梦华则以为有家国之感寓乎其中，然欤否欤。”
唐圭璋《唐宋词简释》：此首，情绪亦寓景中。“六曲”三句，阑外景；“谁把”两句，帘内景。阑外杨柳如丝，帘内海燕双栖，是一极富丽极幽静之金屋。而钿筝一声，骤惊双燕，又是极微妙之兴象。下片，“满眼”三句，因雨而引起惜花情绪，“浓睡”两句，因梦而引起恼莺情绪。镇日凄清，原无欢意，方期睡浓梦好，一晌贪欢，偏是莺语又惊残梦，其惆怅为何如耶。谭复堂评此词如“金碧山水，一片空蒙”，可谓善会消息矣。', 'indent', 1543404884, '5bfe0cfa808ca4007264ffec', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640636, '鹊踏枝 · 斜日平山寒已薄', NULL, 2, 89, 0, 1, '仲殊', NULL, 27101, '5858f4d1128fe10069b2b7af', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E9%B9%8A%E8%B8%8F%E6%9E%9D%C2%B7%E6%96%9C%E6%97%A5%E5%B9%B3%E5%B1%B1%E5%AF%92%E5%B7%B2%E8%96%84/939781?fr=aladdin', '', '斜日平山寒已薄。雪过松梢，犹有残英落。晚色际天天似幕。一尊先与东风约。
邀得红梅同宴乐。酒面融春，春满纤纤萼。客意为伊浑忘却。归船且傍花阴泊。', '《鹊踏枝·斜日平山寒已薄》是北宋诗人仲殊作的词。本诗上阕写日暮雪飘，渴望春天。下阕紧承上阕结句，写以酒迎春，以酒消愁，盼望在繁花似锦的春天，乘船归去。通过写暮冬花落残雪衬托自己的落寞孤寂。', '', '', NULL, '', 'indent', 1543405085, '5bfe0d8744d904005f2d5f44', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640637, '鹊踏枝', NULL, 0, 89, 0, 1, '仲殊', NULL, 27101, '5858f4d1128fe10069b2b7af', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E9%B9%8A%E8%B8%8F%E6%9E%9D%C2%B7%E5%87%A0%E6%97%A5%E4%B8%AD%E5%85%83%E5%88%9D%E8%BF%87%E5%A4%8D/18855898?fr=aladdin', '', '几日中元初过复。七叶蓂疏，佳气生晴书。称庆源深流福厚。天精储粹干星斗。
喜人高堂罗燕豆。风弄微凉，帘幕披香绣。暂倩灵龟言永寿。蟠桃花送长生酒。 ', '', '', '', NULL, '', 'indent', 1543405126, '5bfe0ddfee920a0068883604', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640639, '潇湘神', NULL, 0, 33, 0, 1, '黄公绍', NULL, 10078, '57b9eb3bc4c9710061498d6e', '宋', 'ci', '词', '', '', '贺灵灶。贺灵灶。几年翠舞与珠歌。看到日斜犹未足，涌金门外涌金波。 ', '', '', '', NULL, '', 'indent', 1543406106, '5bfe11c0808ca40072655635', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640640, '潇湘神 · 盱眙舟中作', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '淮水流，淮水流，蛮弦铜鼓不胜愁。骊山金碗无消息，六月园陵冷胜秋。', '', '', '', NULL, '', 'indent', 1543406133, '5bfe11dc0b6160006774462c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640641, '潇湘神 · 望湖天', NULL, 0, 33, 0, 1, '黄公绍', NULL, 10078, '57b9eb3bc4c9710061498d6e', '宋', 'ci', '词', '', '', '望湖天。望湖天。绿杨深处鼓鼘鼘。好是年年三二月，湖边日日看划船。', '', '', '', NULL, '', 'indent', 1543414204, '5bfe3163808ca40072671d2c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640646, '庆清朝 · 禁幄低张', NULL, 6, 101, 0, 1, '李清照', NULL, 10043, '57b90879df0eea0063351b94', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E5%BA%86%E6%B8%85%E6%9C%9D%C2%B7%E7%A6%81%E5%B9%84%E4%BD%8E%E5%BC%A0/920815?fr=aladdin', '', '禁幄低张，彤阑巧护，就中独占残春。容华淡伫，绰约俱见天真。待得群花过后，一番风露晓妆新。妖娆艳态，妒风笑月，长殢东君。　东城边，南陌上，正日烘池馆，竞走香轮。绮筵散日，谁人可继芳尘。更好明光宫殿，几枝先近日边匀。金尊倒，拚了尽烛，不管黄昏。', '《庆清朝·禁幄低张》是宋代女词人李清照的作品。这是一首长调赏花词，描述春花盛开之时，明光宫苑之处，词人与同游者对花倾觞，自朝至暮直到秉烛而兴致未减的情景。全词状物抒怀，笔致工雅，蕴藉含蓄，层层铺陈，宕而有序，表现了暮春三月一派繁荣升平之景象，抒写了女主人公一腔赏花惜春之心境。', '庆清朝（zhāo）：此词调名他本多作《庆清朝慢》，疑误。《词谱》以王观《庆清朝慢·踏青》为正格，李清照此词为变体。王、李二词字数、句读均有所不同，调名亦不同。又说《庆清朝》即《庆清朝慢》。
禁幄（wò）低张：指护花的帷幕低垂。幄，帐幕。
彤阑（lán）：红色的栏杆。阑，同“栏”。
“容华”二句：意谓素淡的花儿就像一个不加雕饰的美女一样。伫（zhù），久立。这里以之形容花色淡雅。绰（chuò）约，姿态柔美。
“妖娆”三句：意谓娇媚的花儿惹得春风嫉妒，明月却为之绽开笑脸，她还能把春天久久留住。殢（tì），滞留。
绮筵（yán）：豪华而丰盛的酒席。
芳尘：含有双关之义：一则是对“香轮”车尘的美称，其意与“戟流波于桂水兮，起芳尘于沉泥”（陆云《喜霁赋》）差同；二则指词人所欣赏的这种入禁赏花的高雅活动，其意与“振芳尘于后”（《宋书·谢灵运传》）相近，指某种名声、风气。
明光宫殿：汉代宫殿名，包括明光宫和明光殿。据《三辅黄图》载，明光宫建于汉武帝太初四年（公元前101年）秋，在长乐宫中。明光殿位于未央宫渐台西之桂宫中。这里借指北宋汴京的宫殿。
日边：太阳的旁边。这里比喻在皇帝身边。
“金尊倒”三句：意谓日夜宴饮，喝得杯盘狼藉，灯烛燃尽。尊，同“樽”，盛酒的器具。', '宫禁中的护花帷幕低低地张蔽遮阳，红色的栏杆工巧地缭绕围护。那里被精心保护的是一种独占暮春风光的名花。这种花淡雅挺立，姿态柔美，朵朵都呈现出天公造化的精巧绝伦。等到数不清的春花纷纷开过之后，经历了春风吹拂、春雨浴洗、清露浇洒的名花，仿佛晓妆初成的美人，带给人无限清新。它以无比妩媚的姿态，戏弄春风、嘲笑春月，尽情地引逗着司管春天的神君。　　在东城、南陌这些日光易照之处，那里的亭台池馆整天都被暖烘烘的太阳熏抚；从早到晚，赏花买花的人们车水马龙川流不息。在这般牡丹盛开如锦如簇的兴会结束之后，又有什么花可以继它之后，散发出诱人的芳香呢？最迷人的是在这明光宫苑内，有几枝向阳的牡丹正在竞芳吐艳。对着花儿飞觥举觞，快些把金杯内的美酒喝下，别管它金乌已西坠，黄昏将袭来，筵上还有未燃尽的残蜡！', '[{"bookId": "6277f84f8efdff05d7d6839b", "bookTitle": "李清照全集", "articleId": "6312258ac9ebcc6fbea12052", "shortContent": "该词咏什么，原无人论及。近代有人说是咏芍药，有人认为是咏牡丹，见仁见智。以咏牡丹为佳。据宋人钱易《南部新书》记载，宋时汴梁有“三月十五日两街看牡丹，奔走车马”风俗。这首词题咏此事。\n\n词的上片写花事，下片写赏况，极写人们通宵达旦饮酒赏花兴致，抒发了词人欣喜之情。咏牡丹，不露牡丹，正所谓不着一字尽得风流。", "authors": [], "pressName": "崇文书局"}]', '现代词人黄墨谷：此词各本无题，细玩词意，有“就中独占残春”，乃咏芍药之作。苏东坡诗：“一声啼鴂画楼东，魏紫姚黄扫地空。多谢化工怜寂寞，尚留芍药殿春风。”（《重辑李清照集》）
现代学者靳极苍：前三句“禁幄低张，彤阑巧护，就中独占残春”，该确定为牡丹。因“禁幄低张”可见不是高大的花木。“彤阑巧护”，可见是很宝贵的花木。尤其“就中独占残春”，只有牡丹是残春时独占的。白居易《卖花诗》：“上张幄幕庇，旁织巴离护”，正是说牡丹和这儿“禁幄低张，彤栏巧护”同。李建勋诗“携殇邀客绕朱栏，肠断残春送牡丹”正和这儿“彤栏巧护，就中独占残春”相同，所以这首诗咏牡丹，该是没有问题的。（《百家唐宋词新话》）
现代学者孙崇恩：上阕描写宫内禁苑牡丹的容姿。起笔“禁幄”三句，写牡丹所处的环境，表现其高贵，突出咏花本题，运笔工巧，如烘云托月。紧接着刻画牡丹形象，“容华”二句，写牡丹的神姿；“待得”二句，写牡丹的品格；“妖烧”三句，写牡丹的魅力，“妒”、“笑”、“殢”三字把风、月、日拟人化，写来生动传神，形神毕现。下阕描写宫廷内外赏花的情景。换头笔势转折，“东城边”四句，写赏花盛况；紧接着再度跌宕，“绮筵”二句，抒赏花之情，含伤春之感；“更加”二句，又见跌宕，突出禁苑赏花；结尾笔锋挺拔，洒脱不羁，“金尊倒”三句，抒惜春赏花情怀。全词状物抒怀，笔致工雅，层层铺陈，宕而有序，蕴藉含蓄，表现了一派繁荣升平景象，抒发了女词人一腔赏花惜春之情。（《李清照诗词选》）', 'indent', 1543489027, '5bff55a9303f39005fe1f6e1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640681, '暗香 · 定王台夜集', NULL, 0, 121, 0, 1, '王闿运', NULL, 19508, '5858ed9d8d6d810065c35085', '清', 'ci', '词', '', '', '汉时月色。向古城一角，长窥词客。试傍玉梅，岁岁春来探消息。
环佩归时夜冷，料瘦损、胡沙天北。又十载、蜡屐重经，长啸楚天碧。
南国。远岑寂。比雪苑兔园，未近锋镝。故垣约略。
时有幽禽觑苔石。休道长沙地小，长乐外、钟声堪忆。
这冷淡、踪迹处，几人觅得。', '', '', '', NULL, '', 'indent', 1543836014, '5c04a115303f39005f1f2fb0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640647, '庆清朝 · 榴花', NULL, 0, 69, 0, 1, '王沂孙', NULL, 10224, '57ce3e8a7db2a200680bfee3', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E5%BA%86%E6%B8%85%E6%9C%9D%C2%B7%E6%A6%B4%E8%8A%B1/5244424?fr=aladdin', '', '玉局歌残，金陵句绝，年年负却熏风。西邻窈窕，独怜入户飞红。前度绿阴载酒，枝头色比舞裙同。何须拟，蜡珠作蒂，缃彩成丛。
谁在旧家殿阁？自太真仙去，扫地春空。朱幡护取，如今应误花工。颠倒绛英满径，想无车马到山中。西风后，尚余数点，犹胜春浓。', '《庆清朝·榴花》是王沂孙所作的一首词。整首词通过前人咏榴花的诗词和种榴花的故事，烘托榴花的美，把哀伤也融入新鲜的审美感里面。', '', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e750f03048e64fbd894f5", "shortContent": "王沂孙这一首咏榴花的词，突出了自己对榴花的鉴赏。南宋咏物词总是本着“不着一字，尽得风流”的意旨。此词即不做正面描绘，也不点明榴花，而是充分利用了前人咏榴花的诗词和种榴故事来烘托出榴花的美。但他把前人诗词融入自己词笔的时候，有抑有扬，一反前人描绘石榴花的繁盛艳丽，却强调了榴花的自然美，并以一种与时代盛衰有关系的深沉感慨寄托于词中。\n词一开始写“玉局歌残，金陵句绝，年年负却熏风”，就点出了榴花，并说从...", "authors": ["王达津"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec6105914587d02f590fe", "shortContent": "王沂孙这一首咏榴花的词，突出了自己对榴花的鉴赏。南宋咏物词总是本着“不著一字，尽得风流”的意旨。此词即不做正面描绘，也不点明榴花，而是充分利用了前人咏榴花的诗词和种榴故事来烘托出榴花的美的。但他把前人诗词融入自己词笔的时候，有抑有扬，一反前人描绘石榴花的繁盛艳丽，却强调了榴花的自然美，并以一种与时代盛衰有关系的深沉感慨寄托于词中。\n词一开始写“玉局歌残，金陵句绝，年年负却熏风”，就点出了榴花，并说...", "authors": ["王达津"], "pressName": "上海辞书出版社"}]', '', 'indent', 1543489175, '5bff563e9f545400673f097f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640648, '庆清朝', NULL, 0, 114, 0, 1, '史达祖', NULL, 10213, '57ba7284a34131005b0e3271', '宋', 'ci', '词', '', '', '坠絮孳萍，狂鞭孕竹，偷移红紫池亭。余花未落，似供残蝶经营。赋得送春诗了，夏帷撺断绿阴成。桑麻外，乳鸠稚燕，别样芳情。
荀令旧香易冷，叹俊游疏懒，枉自销凝。尘侵谢屐，幽径斑驳苔生。便觉寸心尚老，故人前度谩丁宁。空相误，祓兰曲水，挑菜东城。 ', '', '', '', NULL, '', 'indent', 1543489239, '5bff567e303f39005fe201a4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640649, '庆清朝', NULL, 0, 304, 0, 1, '张炎', NULL, 10223, '57bc5941a633bd005d42458f', '宋', 'ci', '词', '', '竹，散怀吟眺，一任所适。太白去后三百年，无此乐也。', '浅草犹霜。融泥未燕，晴梢润叶初干。闲扶短策，邻家小聚清欢。错认篱根是雪，梅花过了一番寒。风还峭，较迟芳信，恰是春残。
此境此时此意，待移琴独去，石冷慵弹。飘飘爽气，飞鸟相与俱还。醉里不知何处，好诗尽在夕阳山。山深杳，更无人到，流水花间。 ', '', '', '', NULL, '', 'indent', 1543489288, '5bff56affb4ffe0069aa58ef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640650, '庆清朝 · 北陆严凝', NULL, 0, 149, 0, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '北陆严凝，东郊料峭，化工争付归期。前村夜来雪里，先见纤枝。想像靓妆淡伫，钗头翡翠茧蛾儿。冰壶莹，坐间静对，姑射仙姿。潇洒处，非艳冶最奇。是名赋、处士新诗。尊前坐曲，忍听羌管频吹。试问占先众卉，微笑不奈苦寒欺。何须问，定应未羡，桃李芳菲。 ', '', '', '', NULL, '', 'indent', 1543489372, '5bff570244d904005f862c84', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640651, '庆清朝 · 银漏花残', NULL, 0, 149, 0, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '银漏花残，红消烛泪。九重鱼钥欢声沸。奏万乘、祥曦门外。盖圣君、恭谢灵休，谨访景明嘉礼。天意好，祥风瑞月，时正当、小春天气。禁街十里香中，御辇万红影里。千官花底，控绣勒、宝鞭摇曳。看万年，永庆吾皇，拈指又瞻三载。 ', '', '', '', NULL, '', 'indent', 1543489398, '5bff571c303f39005fe20812', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640652, '庆清朝 · 点检尧阶', NULL, 0, 149, 0, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '点检尧阶，阶蓂生六叶，春深桃杏花开。长庚入梦，重新产谪仙才。事业十年灯火，文章笔下若掀雷。果然是，两字功名，唾手拿来。又况当年强仕，得志青云路，足慰高怀。紫泥凤诏，行须非次招徕。金马玉堂风月，从容九棘面三槐。从今看，会唐九老，它日云台。 ', '', '', '', NULL, '', 'indent', 1543489508, '5bff578b1579a3005f22d9d6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640653, '庆清朝 · 节过重三', NULL, 0, 149, 0, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '节过重三，日逢四六，真贤应昴初生。元来鼻祖，降瑞应长庚。今喜重逢旧事，固宜依旧复青毡。果然是、双雕一箭，雁塔书名。大器也须小试，鸾凤暂栖，荆棘若为荣。从容钜竹双松，足畅吟情。行种河阳桃李，即飞诏、入厕朝绅。从兹看、箕星上应，南极长明。 ', '', '', '', NULL, '', 'indent', 1543489540, '5bff57ab44d904005f8634c0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640654, '庆清朝 · 朏月生西', NULL, 0, 149, 0, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '朏月生西，杓星建未，画堂昼景偏长。天生英杰，独向此炎光。超卓凡尘表物，精神秋水自清凉。真奇特，清沟挺秀，敌国传芳。好是少年折桂，唾手功名就，腾踏飞黄。君王眷厚，皇华绣斧还乡。士贵姜谟盛事，未容专美独夸唐。称觞处，颂闽境、斑戏公堂。', '', '', '', NULL, '', 'indent', 1543489573, '5bff57c5808ca400728da6db', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640655, '庆清朝慢 · 憺园即景', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '正复淡沲，居然萧远，此中位置殊难。主人略旋烟墨，已就林恋。
几尺红泥墙子，被风吹乱月同弯。花深处，玲珑金粉，一半才干。
碧一队，黄一队，皴染得亭榭，在水云间。朱栏绿莎厅好，映带潺湲。
尽日唼波花鸭，参差睡破簟纹闲。登楼望，斜阳士女，又满春山。', '', '', '', NULL, '', 'indent', 1543489622, '5bff57fd1579a3005f22e1c5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640656, '庆清朝', NULL, 0, 101, 0, 1, '端木埰', NULL, 36968, '5becee44fb4ffe006a50153e', '清', 'ci', '词', '', '', '草浅铺茵，波平漾曲，翠痕新上帘衣。虚窗静俯，娱人多少清晖。
恰正侯过百六，雅游须莫负芳菲。披襟封，嫩红稚绿，一片生机。
休道永和禊事，便舞雩风浴，人对清沂。高情未让，素心如此应希。
餐尽野香秀色，吟魂拌与蝶俱飞。斜阳去，更须留待，明月同归。', '', '', '', NULL, '', 'indent', 1543489831, '5bff58ce9f545400673f2d86', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640657, '庆清朝 · 上楼大参 · 十一月十五', NULL, 0, 17, 0, 1, '李廷忠', NULL, 28347, '5858f5f21b69e60056f692af', '宋', 'ci', '词', '', '', '天启重光，地钟上瑞，有人起自东山。当年谢传，几曾鹤发貂冠。不似文章隽老，重来鸣步斗枢间。洪钧转，五原草绿，太白兵闲。
运庆今朝初度，正日添纹线，月挂冰盘。恩重御壶宣劝，喜溢天颜。听取沙堤好语，金科红篆押千官。春长在，调元鼎里，不假还丹。 ', '', '', '', NULL, '', 'indent', 1543489872, '5bff58f767f3560066d0e176', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640658, '庆清朝 · 寿章丞二月初六', NULL, 0, 149, 0, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '点检尧阶，蓂生六叶，春深桃杏花开。长庚入梦，重新产谪仙才。
事业十年灯火，文章笔下若掀雷。果然是，两字功名，唾手拿来。
又况当年强仕，得志青云路，足慰高怀。紫泥凤诏，行须非次招徕。
金马玉堂风月，从容九棘面三槐。从今看，会唐九老，它日云台。', '', '', '', NULL, '', 'indent', 1543489927, '5bff592efb4ffe0069aa78e4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640757, '晏子春秋 · 外篇 · 第八', NULL, 0, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', '', '', '仲尼见景公景公欲封之晏子以为不可第一
仲尼之齐，见景公，景公说之，欲封之以尔稽，以告晏子。晏子对曰：“不可。彼浩裾自顺，不可以教下；好乐缓于民，不可使亲治；立命而建事，不可守职；厚葬破民贫国，久丧道哀费日，不可使子民；行之难者在内，而传者无其外，故异于服，勉于容，不可以道众而驯百姓。自大贤之灭，周室之卑也，威仪加多，而民行滋薄；声乐繁充，而世德滋衰。今孔丘盛声乐以侈世，饰弦歌鼓舞以聚徒，繁登降之礼，趋翔之节以观众，博学不可以仪世，劳思不可以补民，兼寿不能殚其教，当年不能究其礼，积财不能赡其乐，繁饰邪术以营世君，盛为声乐以淫愚其民。其道也，不可以示世；其教也，不可以导民。今欲封之，以移齐国之俗，非所以导众存民也？。”公曰：“善。”于是厚其礼而留其封，敬见不问其道，仲尼乃行。
景公上路寝闻哭声问梁丘据晏子对第二
景公上路寝，闻哭声。曰：“吾若闻哭声，何为者也？”梁丘据对曰：“鲁孔丘之徒鞠语者也。明于礼乐，审于服丧，其母死，葬埋甚厚，服丧三年，哭泣甚疾。”公曰：“岂不可哉！”而色说之。晏子曰：“古者圣人，非不知能繁登降之礼，制规矩之节，行表缀之数以教民，以为烦人留日，故制礼不羡于便事；非不知能扬干戚钟鼓竽瑟以劝众也，以为费财留工，故制乐不羡于和民；非不知能累世殚国以奉死，哭泣处哀以持久也，而不为者，知其无补死者而深害生者，故不以导民。今品人饰礼烦事，羡乐淫民，崇死以害生，三者，圣王之所禁也。贤人不用，德毁俗流，故三邪得行于世。是非贤不肖杂，上妄说邪，故好恶不足以导众。此三者，路世之政，道事之教也。公曷为不察，声受而色说之？”
仲尼见景公景公曰先生奚不见寡人宰乎第三
仲尼游齐，见景公。景公曰：“先生奚不见寡人宰乎？”
仲尼对曰：“臣闻晏子事三君而得顺焉，是有三心，所以不见也。”
仲尼出，景公以其言告晏子，晏子对曰：“不然！婴为三心，三君为一心故，三君皆欲其国之安，是以婴得顺也。婴闻之，是而非之，非而是之，犹非也。孔丘必据处此一心矣。”
仲尼之齐见景公而不见晏子子贡致问第四
仲尼之齐，见景公而不见晏子。子贡曰：“见君不见其从政者，可乎？”仲尼曰：“吾闻晏子事三君而顺焉，吾疑其为人。”
晏子闻之，曰：“婴则齐之世民也，不维其行，不识其过，不能自立也。婴闻之，有幸见爱，无幸见恶，诽谤为类，声响相应，见行而从之者也。婴闻之，以一心事三君者，所以顺焉；以三心事一君者，不顺焉。今未见婴之行，而非其顺也。婴闻之，君子独立不惭于影，独寝不惭于魂。孔子拔树削迹，不自以为辱；穷陈蔡，不自以为约；非人不得其故，是犹泽人之非斤斧，山人之非网罟也。出之其口，不知其困也，始吾望儒而贵之，今吾望儒而疑之。”
仲尼闻之，曰：“语有之：言发于尔，不可止于远也；行存于身，不可掩于众也。吾窃议晏子而不中夫人之过，吾罪几矣！丘闻君子过人以为友，不及人以为师。今丘失言于夫子，讥之，是吾师也。”因宰我而谢焉，然仲尼见之。
景公出田顾问晏子若人之众有孔子乎第五
景公出田，寒，故以为浑，犹顾而问晏子曰：“若人之众，则有孔子焉乎？”
晏子对曰：“有孔子焉则无有，若舜焉则婴不识。”
公曰：“孔子之不逮舜为闲矣，曷为‘有孔子焉则无有，若舜焉则婴不识’？”
晏子对曰：“是乃孔子之所以不逮舜。孔子行一节者也，处民之中，其过之识，况乎处君之中乎！舜者处民之中，则自齐乎士；处君子之中，则齐乎君子；上与圣人，则固圣人之林也。此乃孔子之所以不逮舜也。”
仲尼相鲁景公患之晏子对以勿忧第六
仲尼相鲁，景公患之，谓晏子曰：“邻国有圣人，敌国之忧也。今孔子相鲁若何？”
晏子对曰：“君其勿忧。彼鲁君，弱主也；孔子，圣相也。君不如阴重孔子，设以相齐，孔子彊谏而不听，必骄鲁而有齐，君勿纳也。夫绝于鲁，无主于齐，孔子困矣。”
居期年，孔子去鲁之齐，景公不纳，故困于陈蔡之闲。
景公问有臣有兄弟而彊足恃乎晏子对不足恃第七
晏公问晏子曰：“有臣而彊，足恃乎？”晏子对曰：“不足恃。”
“有兄弟而彊，足恃乎？”晏子对曰：“不足恃。”公忿然作色曰：“吾今有恃乎？”晏子对曰：“有臣而彊，无甚如汤；有兄弟而彊，无甚如桀。汤有弑其君，桀有亡其兄，岂以人为足恃哉，可以无亡也！”
景公游牛山少乐请晏子一愿第八
景公游于牛山，少乐，公曰：“请晏子一愿。”晏子对曰：“不，婴何愿？”公曰：“晏子一愿。”对曰：“臣愿有君而见畏，有妻而见归，有子而可遗。”公曰：“善乎！晏子之愿；载一愿。”
晏子对曰：“臣愿有君而明，有妻而材，家不贫，有良邻。有君而明，日顺婴之行；有妻而材，则使婴不忘；家不贫，则不愠朋友所识；有良邻，则日见君子：婴之愿也。”公曰：“善乎！晏子之愿也。”
晏子对曰：“臣愿有君而可辅，有妻而可去，有子而可怒。”公曰：“善乎！晏子之愿也。”
景公为大钟晏子与仲尼柏常骞知将毁第九
景公为大钟，将悬之。晏子、仲尼、柏常骞三人朝，俱曰：“钟将毁。”冲之，果毁。公召三子而者问之。晏子对曰：“钟大，不祀先君而以燕，非礼，是以曰钟将毁。”仲尼曰：“钟大而悬下，冲之其气下回而上薄，是以曰钟将毁。”柏常骞曰：“今庚申，雷日也，音莫胜于雷，是以曰钟将毁也。”
田无宇非晏子有老妻晏子对以去老谓之乱第十
田无宇见晏子独立于闺内，有妇人出于室者，发班白，衣缁布之衣而无里裘。
田无宇讥之曰：“出于室为何者也？”
晏子曰：“婴之家也。”无宇曰：“位为中卿，田七十万，何以老为妻？”
对曰：“婴闻之，去老者，谓之乱；纳少者，谓之淫。且夫见色而忘义，处富贵而失伦，谓之逆道。婴可以有淫乱之行，不顾于伦，逆古之道乎？”
工女欲入身于晏子晏子辞不受第十一
有工女托于晏子之家焉者，曰：“婢妾，东廓之野之也。愿得入身，比数于下陈焉。”
晏子曰：“乃今日而后自知吾不肖也！古之为政者，士农工商异居，男女有别而不通，故士无邪行，女无淫事。今仆托国主民，而女欲奔仆，仆必色见而行无廉也。”遂不见。
景公欲诛羽人晏子以为法不宜杀第十二
景公盖姣，有羽人视景公僭者。公谓左右曰：“问之，何视寡人之僭也？”羽人对曰：“言亦死，而不言亦死，窃姣公也。”公曰：“合色寡人也？杀之！”晏子不时而入，见曰：“盖闻君有所怒羽人。”公曰：“然。色寡人，故将杀之。”晏子对曰：“婴闻拒欲不道，恶爱不祥，虽使色君，于法不宜杀也。”公曰：“恶然乎！若使沐浴，寡人将使抱背。”
景公谓晏子东海之中有水而赤晏子详对第十三
景公谓晏子曰：“东海之中，有水而赤，其中有枣，华而不实，何也？”
晏子对曰：“昔者秦缪公乘龙舟而理天下，以黄布裹烝枣，至东海而捐其布，破黄布，故水赤；烝枣，故华而不实。”
公曰：“吾详问子何为？”对曰：“婴闻之，详问者，亦详对之也。”
景公问天下有极大极细晏子对第十四
景公问晏子曰：“天下有极大乎？”
晏子对曰：“有。足游浮云，背凌苍天，尾偃天闲，跃啄北海，颈尾咳于天地乎！然而漻漻不知六翮之所在。”
公曰：“天下有极细乎？”
晏子对曰：“有。东海有虫，巢于虱睫，再乳再飞，而虱不为惊。臣婴不知其名，而东海渔者命曰焦冥。”
庄公图莒国人扰绐以晏子在乃止第十五
庄公阖门而图莒，国人以为有乱也，皆操长兵而立于闾。公召睢休相而问曰：“寡人阖门而图莒，国人以为有乱，皆摽长兵而立于衢闾，柰何？”休相对曰：“诚无乱而国以为有，则仁人不存。请令于国，言晏子之在也。”公曰：“诺。”以令于国：“孰谓国有乱者，晏子在焉。”然后皆散兵而归。君子曰：“夫行不可不务也。晏子存而民心安，此非一日之所为也，所以见于前信于后者。是以晏子立人臣之位，而安万民之心。”
晏子死景公驰往哭哀毕而去第十六
晏公游于灾，闻晏子死，公乘侈舆服繁驵驱之。而因为迟，下车而趋；知不若车之遫，则又乘。比至于国者，四下而趋，行哭而往，伏尸而号，曰：“子大夫日夜责寡人，不遗尺寸，寡人犹且淫逸而不收，怨罪重积于百姓。今天降祸于齐，不加于寡人，而加于夫子，齐国之社稷危矣，百姓将谁告夫！”
晏子死景公哭之称莫复陈告吾过第十七
晏子死，景公操玉加于晏子而哭之，涕沾襟。章子谏曰：“非礼也。”公曰：“安用礼乎？昔者吾与夫子游于公邑之上，一日而三不听寡人，今其孰能然乎！吾失夫子则亡，何礼之有？”免而哭，哀尽而去。
晏子没左右谀弦章谏景公赐之鱼第十八
晏子没，十有七年，景公饮诸大夫酒。公射，出质，堂上唱善，若出一口。公作色太息，播弓矢。
弦章入，公曰：“章！自晏子没后，不复闻不善之事。”弦章对曰：“君好之，则臣服之；君嗜之，则臣食之。尺蠖食黄则黄，食苍则苍是也。”
公曰：“善。吾不食谄人以言也。”以鱼五十乘赐弦章，章归，鱼车塞涂，抚其御之手，曰：“昔者晏子辞党以正君，故过失不掩之。今诸臣谀以干利，吾若受鱼，是反晏子之义，而顺谄谀之欲。”固辞鱼不受。
君子曰：“弦章之廉，晏子之遗行也。”', '', '', '', NULL, '', 'indent', 1545260709, '5c1a5e4d9f54540474a32f9e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640758, '上神宗皇帝书', NULL, 7, 3406, 2, 2, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'wen', '文', '', '', '熙宁四年二月某日，殿中丞直史馆判官告院权开封府推官苏轼，谨昧万死再拜上书皇帝陛下：
臣近者不度愚贱，辄上封章言灯事。自知渎犯天威，罪在不赦，席稿私室，以待斧钺之诛；而侧听逾旬，威命不至，问之府司，则买灯之事寻已停罢，乃知陛下不惟赦之，又能听之。惊喜过望，以至感泣。何者？改过不吝，从善如流，此尧舜禹汤之所勉强而力行，秦汉以来之所绝无而仅有。顾此买灯毫发之失，岂能上累日月之明，而陛下幡然改命，曾不移刻，则所谓智出天下而听于至愚，威加四海而屈于匹夫。臣今知陛下可与为尧舜，可与为汤武，可与富民而措刑，可与强兵而伏戎狄矣。有君如此，其忍负之！惟当披露腹心，捐弃肝脑，尽力所至，不知其它。乃者臣亦知天下之事，有大于买灯者矣，而独区区以此为先者，盖未信而谏，圣人不与；交浅言深，君子所戒。是以试论其小者，而其大者固将有待而后言。今陛下果赦而不诛，则是既已许之矣；许而不言，臣则有罪；是以愿终言之。
臣之所欲言者三，愿陛下结人心，厚风俗，存纪纲而已。
人莫不有所恃，人臣恃陛下之命，故能役使小民；恃陛下之法，故能胜服强暴。至于人主所恃者谁与？书曰：“予临兆民，凛乎若朽索之驭六马。”言天下莫危于人主也。聚则为君民，散则为仇雠。聚散之间，不容毫厘。故天下归往谓之王，人各有心谓之独夫。由此观之，人主之所恃者，人心而已。人心之于人主也，如木之有根，如灯之有膏，如鱼之有水，如农夫之有田，如商贾之有财。木无根则稿，灯无膏则灭，鱼无水则死，农无田则饥，商贾无财则贫，人主失人心则亡。此理之必然，不可逭之灾也。其为可畏，从古以然。苟非乐祸好亡，狂易丧志，则孰敢肆其胸臆，轻犯人心。昔子产焚载书以弭众言，赂伯石以安巨室，以为众怒难犯，专欲难成，而孔子亦曰：“信而后劳其民，未信则以为厉已也。”惟商鞅变法，不顾人心，虽能骤至富彊，亦以召怨天下。使其民知利而不知义，见刑而不见德，虽得天下，旋踵而失也；至于其身，亦卒不免负罪出走，而诸侯不纳，车裂以狥，而秦人莫哀。君臣之间，岂愿如此。宋襄公虽行仁义。失众而亡；田常虽不义，得众而强。是以君子未论行事之是非，先观众心之向背。谢安之用诸桓，未必是，而众之所乐，则国以乂安。庾亮之召苏峻，未必非，而势有不可，则反为危辱。自古及今，未有和易同众而不安，刚果自用而不危者也。
今陛下亦知人心之不悦矣。中外之人，无贤不肖，皆言祖宗以来，治财用者不过三司使副判官，经今百年，未尝阙事。今者无故又创一司，号曰制置三司条例使。六七少年，日夜讲求于内；使者四十馀辈，分行营干于外。造端宏大，民实惊疑；创法新奇，吏皆惶惑。贤者则求其说而不可得，未免于忧；小人则以其意度朝廷，遂以为谤，谓陛下以万乘之主而言利，谓执政以天子之宰而治财。商贾不行，物价腾踊，近自淮甸，远及川蜀，喧传万口，论说百端。或言京师正店，议置监官；夔路深山，当行酒禁；拘收僧尼常住；减刻兵吏廪禄；如此等类，不可胜言。而甚者至以为欲复肉刑。斯言一出，民且狼顾。陛下与二三大臣亦闻其语矣，然而莫之顾者，徒曰“我无其事，又无其意，何恤于人言。”夫人言虽未必皆然，而疑似则有以致谤。人必贪财也，而后人疑其盗；人必好色也，而后人疑其淫。何者？未置此司，则无其谤，岂去岁之人皆忠厚，今岁之人皆虚浮？孔子曰：“工欲善其事，必先利其器。”又曰：“必也正名乎。”今陛下操其器而讳其事，有其名而辞其意，虽家置一喙以自解，市列千金以购人，人必不信，谤亦不止。夫制置三司条例司，求利之名也；六七少年与使者四十馀辈，求利之器也。驱鹰犬而赴林薮，语人曰：“我非猎也”，不如放鹰犬而兽自驯；操网罟而入江湖，语人曰：“我非渔也”，不如捐网罟而人自信。故臣以为，消谗慝以召和气，复人心而安国本，则莫若罢制置三司条例司。夫陛下之所以创此司者，不过以兴利除害也。使罢之而利不兴，害不除，则勿罢；罢之而天下悦，人心安，兴利除害，无所不可，则何苦而不罢？
陛下欲去积弊，而立法必使宰相熟议而后行事。若不由中书，则是乱世之法，圣君贤相，夫岂其然？必若立法，不免由中书熟议，不免使宰相，此司之设，无乃冗长而无名。智者所国，贵于无迹，汉之文景，纪无可书之事；唐之房杜，传无可载之功；而天下之言治者与文景，言贤者与房杜，盖事已立而迹不见，功已成而人不知。故曰：“善用兵者，无赫赫之功。”岂惟用兵，事莫不然。今所图者，万分未获其一也，而迹之布于天下者，若泥中之斗兽。亦可谓拙谋矣。
陛下诚欲富国，择三司官属与漕运使副，而陛下与二三大臣孜孜讲求，磨以岁月，则积弊自去而人不知。但恐立志不坚，中道而废，孟轲有言：“其进锐者其退速。”若有始有卒，自可徐徐，十年之后，何事不立？孔子曰：“欲速则不达，见小利则大事不成。”使孔子而非圣人，则此言亦不可用。书曰：“谋及卿士，至于庶人。翕然大同，乃底元吉。”若违多而从少，则静吉而作凶。
今上自宰相大臣，既已辞免不为，则外之议论，断亦可知。宰相人臣也，且不欲以此自污，而陛下独安受其名而不辞，非臣愚之所识也。君臣宵旰几一年矣，而富国之效，茫如捕风，徒闻内帑出数百万缗，祠部度五千馀人耳。以此为术，其谁不能？
且遣使纵横，本非令典。汉武遣绣衣直指，桓帝遣八使，皆以守宰狼籍，盗贼公行，出于无术，行此下策。宋文帝元嘉之政，比于文景。当时责成郡县，未尝遣使。至孝武，以为郡县迟缓，始命台使督之。以至萧齐，此弊不革。故景陵王子良上疏极言其事，以为此等，朝辞禁门，情态即异；暮宿村县，威福便行；驱迫邮传；折辱守宰；公私劳扰，民不聊生。唐开元中，宇文融奏置劝农判官使裴宽等二十九人，并摄御史，分行天下，招携户口，检责漏田。时张说、杨瑒、皇甫璟、杨相如皆以为不便。而相继罢黜。虽得户八十馀万，皆州县希旨，以主为客，以少为多。及使百官集议都省，而公卿以下，惧融威势，不敢异辞。陛下读之，观其所行，为是为否？近者均税宽恤，冠盖相望，朝廷亦旋觉其非，而天下至今以为谤，曾未数岁，是非较然。臣恐后之视今，亦犹今之视昔。
且其所遣尤不适宜。事少而员多，人轻而权重。夫人轻而权重，则人多不服，或致侮慢以兴争；事少而员多，则无以为功，必须生事以塞责。陛下虽严赐约束，不许邀功，然人臣事君之常情，不从其令而从其意。今朝廷之意，好动而恶静，好同而恶异，指趣所在，谁敢不从？臣恐陛下赤子，自此无宁岁矣。
至于所行之事，行路皆知其难。何者？汴水浊流，自生民以来不以种稻。秦人之歌曰：“泾水一石，其泥数斗。且溉且粪，长我禾黍，”何尝言“长我粳稻”耶？今欲陂而清之，万顷之稻，必用千顷之陂。一岁一淤，三岁而满矣。陛下遽信其说，即使相视地形，万一官吏苟且顺从，真谓陛下有意兴作，上縻帑廪，下夺农时，堤防一开，水失故道，虽食议者之肉，何补于民？天下久平，民物滋息，四方遗利，盖略尽矣。今欲凿空访寻水利，所谓“即鹿无虞”，岂惟徒劳，必大烦扰。
凡有擘画，不问何人，小则随事酬劳，大则量才录用。若官私格沮，并行黜降，不以赦原；若才力不办兴修，便许申奏替换。赏可谓重，罚可谓轻，然并终不言诸色人妄有申陈，或官私误兴功役，当得何罪。如此，则妄庸轻剽浮浪奸人，自此争言水利矣。成功则有赏，败事则无诛，官司虽知其疏，岂可便行。抑退所在，追集老少，相视可否，吏卒所过，鸡犬一空。若非灼然难行，必须且为兴役。何则？格沮之罪重，而误兴之过轻。人多爱身，势必如此。且古陂废堰，多为侧近冒耕，岁月既深，已同永业。苟欲兴复，必尽追收，人心或摇，甚非善政。又有好讼之党，多怨之人，妄言某处可作陂渠，规坏所怨田产；或指人旧业，以为官陂。冒田之讼，必倍今日。臣不知朝廷本无一事，何苦而行此哉？
自古役人必用乡户，犹食之必用五谷，衣之必用丝麻，济川之必用舟楫，行地之必用牛马。虽其间或有以他物充代，然终非天下所可常行。今者，徒闻江浙之间数郡雇役，而欲措之天下，是犹见燕晋之枣栗，岷蜀之蹲鸱，而欲以废五谷，岂不难哉？
又欲官卖所在房场，以充衙前雇直。虽有长役，更无酬劳。长役所得既微，自此必渐衰散，则州郡事体，憔悴可知。士大夫捐亲戚，弃坟墓，以从官于四方者，用力之馀，亦欲取乐，此人之至情也。若雕弊太甚，厨传萧然，则似危邦之陋风，恐非太平之盛观。陛下诚虑及此，必不肯为。且今法令莫严于御军，军法莫严于逃窜。禁军三犯，厢军五犯，大率处死，然逃军常半天下。不知雇人为役，与厢军何异？若有逃者，何以罪之？其势必轻于逃军，则其逃必甚于今日。为其官长，不亦难乎？
近者虽使乡户，颇得雇人。然至于所雇逃亡，乡户犹任其责。今遂欲于两税之外，别立一科，谓之庸钱，以备官雇。则雇人之责，官所自任矣。自唐杨炎废租庸调以为两税，取大历十四年应干赋敛之数以定两税之额，则是租调与庸，两税既兼之矣。今两税如故，奈何复欲取庸？圣人之立法，必虑后世，岂可于两税之外，生出科名。万一后世不幸，有多欲之君，辅之以聚敛之臣，庸钱不除，差役仍旧，使天下怨毒，推所从来，则必有任其咎者矣。又欲使坊郭等第之民与乡户均役，品官形势之家与齐民并事。其说曰：“周礼田不耕者出屋粟，宅不毛者有里布，而汉世宰相之子不免戍边。”此其所以藉口也。古者官养民，今者民养官。给之以田而不耕，劝之以农而不力，于是有里布、屋粟、夫家之征，而民无所为生，去为商贾，事势当尔，何名役之？且一岁之戍，不过三日，三日之雇，其直三百。今世三大户之役，自公卿以降，毋得免者，其费岂特三百而已。大抵事若可行，不必皆有故事，若民所不悦，俗所不安，纵有经典明文，无补于怨。若行此二者，必怨无疑。女户、单丁，盖天民之穷者也。古之王者，首务恤此，而今陛下首欲役之，此等苟非户将绝而未亡，则是家有丁而尚幼，若假之数岁，则必成丁而就役，老死而没。官富有四海，忍不加恤？孟子曰：“始作俑者，其无后乎！”春秋书“作丘甲”、“用田赋”，皆重其始为民患也。
青苗放钱，自昔有禁，今陛下始立成法，每岁常行，虽云不许抑配，而数世之后，暴君污吏，陛下能保之与？异日天下恨之，国史记之，曰青苗钱自陛下始，岂不惜哉？东南买绢，本用见钱，陕西粮草，不许折兊。朝廷既有著令，职司又每举行，然而买绢未尝不折盐，粮草未尝不折钞，乃知青苗不许抑配之说，亦是空文。只如治平之初，拣刺义勇，当时诏旨慰谕，明言永不戍边，著在简书，有如盟约。于今几日，议论已摇，或以代还东军，或欲抵换弓手，约束难恃，岂不明哉？
纵使此令决行，果不抑配，计其间愿请之户，必皆孤贫不济之人家，若自有嬴馀，何至与官交易。此等鞭挞巳急，则继之逃亡，逃亡之馀，则均之邻保，势有必至，理有固然。且夫常平之为法也，可谓至矣。所守者约，而所及者广。借使万家之邑，已有千斛，而谷贵之际，千斛在市，物价自平。一市之价既平，一邦之民自足，无专斗乞丐之弊，无里正催驱之劳，今若变为青苗，家贷一斛，则千户之外，孰救其饥？且常平官钱常患其少，若尽数收籴，则无借贷；若留充借贷，则所籴几何？乃知常平青苗，其势不能两立。坏彼成此，所丧愈多；亏官害民，虽悔何逮。
臣窃计陛下欲考其实，必然问人，人知陛下方欲力行，必谓此法有利无害。以臣愚见，恐未可凭。何以明之？臣在陜西，见刺义勇，提举诸县，臣常亲行。愁怨之民，哭声振野，当时奉使还者，皆言民尽乐为。希合取容，自古如此。不然，则山东之盗，二世何缘不觉？南诏之败，明皇何缘不知？今虽未至于此，亦望陛下审听而已。
昔汉武之世，财力匮竭，用贾人桑羊之说，买贱卖贵，谓之均输。于时商贾不行，盗贼滋炽，几至于乱。孝昭既立，学者争排其说，霍光顺民所欲从而予，之天下归心，遂以无事。不意今者此论复兴，立法之初，其说尚浅，徒言徙贵就贱，用近易远。然而广置官属，多出缗钱，豪商大贾，皆疑而不敢动，以为虽不明言贩卖，然既已许之变易，变易既行，而不与商贾争利，未之闻也。夫商贾之事，曲折难行，其买也先期而与钱，其卖也后期而取直，多方相济，委曲相通，倍称之息，由此而得。今官买是物，必先设官置吏。簿书廪禄，为费已厚；非良不售，非贿不行，是以官买之价，比民必贵；及其卖也，弊复如前，商贾之利，何缘而得？朝廷不知虑此，乃捐五百万缗以予之，此钱一出，恐不可复。纵使其间薄有所获，而征商之额，所损必多。今有人为其主牧牛羊，不告其主而以一牛易五羊，一牛之失则隐而不言，五羊之获则指为劳绩。陛下以为坏常平而言青苗之功，亏商税而取均输之利，何以异此？
陛下天机洞照，圣略如神，此事至明，岂有不晓。必谓已行之事不欲中变，恐天下以为执德不一，用人不终，是以迟留岁月，庶几万一。臣窃以为过矣。古之英主，无出汉高。郦生谋挠楚权，欲复六国，高祖曰：“善，趣刻印。”及闻留侯之言，吐哺而骂曰：“趣销印。”夫称善未几，继之以骂，刻印销印，有同儿嬉，何尝累高祖之知人，适足明圣人之无我。陛下以为可而行之，知其不可而罢之，至圣至明，无以加此。议者必谓民可与乐成，难与虑始，故陛下坚执不顾，期于必行，此乃战国贪功之人行险侥幸之说，陛下若信而用之，则是狥高论而逆至情，持空名而邀实祸，未及乐成，而怨已起矣。
臣之所愿结人心者，此之谓也。
士之进言者，为不少矣，亦尝有以国家之所以存亡，历数之所以长短告陛下者乎？国家之所以存亡者，在道德之浅深，不在乎强与弱；历数之所以长短者，在风俗之厚薄，不在乎富与贫。道德诚深，风俗诚厚，虽贫且弱，不害于长而存；道的诚浅，风俗诚薄，虽强且富，不救于短而亡。人主知此，则知所轻重矣。
是以古之贤君，不以弱而忘道德，不以贫而伤风俗，而智者观人之国，亦以此而察之。齐，至强也，周公知其后有篡弑之臣；卫，至弱也，季子知其后亡；吴破楚入郢，而陈大夫逢滑知楚之必复；晋武既平吴，何曾知其将乱；隋文既平，陈房乔知其不久；元帝斩郅支，朝呼韩，功多于武宣矣，偷安而王氏之衅生；宣宗収燕赵；复河湟；力强于宪武矣；销兵而庞勋之乱起。故臣愿陛下务崇道德而厚风俗，不愿陛下急于有功而贪富强，使陛下富如隋，强如秦，西取灵武，北取燕蓟，谓之有功可也，而国之长短，则不在此。
夫国之长短，如人之寿夭。人之寿夭在元气，国之长短在风俗，世有尫羸而寿考，亦有盛壮而暴亡。若元气犹存，则尫羸而无害，及其巳耗，则盛壮而愈危。是以善养生者，慎起居，节饮食，道引关节，吐故纳新，不得已而用药，则择其品之上，性之良，可以久服而无害，则五脏和平而寿命长。不善养生者，薄节慎之功，迟吐纳之效，厌上药而用下品，伐真气而助强阳，根本已空，僵仆无日，天下之势与此无殊。故臣愿陛下爱惜风俗，如护元气。
古之圣人，非不知深刻之法可以齐众，勇悍之夫可以集事，忠厚近于迂阔，老成初若迟钝，然终不肯以彼易此者，知其所得小而所丧大也。曹参，贤相也，曰：“慎无扰狱市。”黄霸，循吏也，曰：“治道去太甚。”或讥谢安以清谈废事，安笑曰：“秦用法吏，二世而亡。”刘晏为度支，专用果锐少年，务在急速，集事好利之党，相师成风。德宗初即位，擢崔佑甫为相，以道德宽大，推广上意，故建中之政其声蔼然，天下相望。庶几贞观。及卢杞为相，讽上以刑名，整齐天下，驯致浇薄，以及播迁。
我仁祖之驭天下也，持法至宽，用人有叙，专务掩覆过失，未尝轻改旧章，然考其成功，则曰：“未至以言乎？”用兵则十出而九败，以言乎府库则仅足，而无馀徒，以德泽在人，风俗知义，是以升遐之日，天下如丧考妣。社稷长远，终必赖之，则仁祖可谓知本矣。今议者不察，徒见其末年吏多因循，事不振举，乃欲矫之以苛察，齐之以智能，招来新进勇锐之人，以图一切速成之效。未享其利，浇风已成。
且天时不齐，人谁无过，国君含垢，至察无徒。若陛下多方包容，则人材取次可用，必欲广置耳目，务求瑕疵，则人不自安，各图苟免，恐非朝廷之福，亦岂陛下所愿哉？汉文欲拜虎圈，啬夫释之，以为利口伤俗，今若以口舌捷给而取士，以应对迟钝而退人，以虚诞无实为能文，以矫激不仕为有德，则先王之泽，遂将散微。
自古用人，必须历试诸难，有卓异之器，必有已成之功。一则使其更变而知难，事不轻作；一则待其功高而望重，人自无辞。昔先主以黄忠为后将军，而诸葛亮忧其不可，以为忠之名望，素非关张之伦，若班爵遽同，则必不悦。其后关侯果以为言。以黄忠豪勇之资，以先主君臣之契，尚须虑此，况其他乎？世尝谓汉文不用贾生，以为深恨。臣尝推究其旨，窃谓不然。贾生固天下之奇才，所言亦一时之良策，然请为属国，欲以系单于，则是处士之大言，少年之锐气。昔高祖以三十万众，困于平城，当时将相群臣，岂无贾生之比，三表五饵，人知其疏，而欲以困中行，说尤不可信矣。兵，凶器也，而易言之，正如赵括之轻秦，李信之易楚，若文帝亟用其说，则天下殆将不安。使贾生尝历艰难，亦必自悔其说，用之晚成，其术必精。不幸丧亡，非意所及。不然，文帝岂弃材之主，绛灌岂蔽贤之士，至于晁错，尤号刻薄，文帝之世，止于太子家令，而景帝既立，以为御史大夫。申屠贤相，发愤而死，纷更政令，天下骚然，及至七国发难，而错之术亦穷矣。文景优劣，于斯可见。
大抵名器爵禄，人所奔趋，必使积劳而后迁，以明持久而难得，则人各安其分，不敢躁求。今若多开骤进之门，使有意外之得，公卿侍从，跬步可图其得者，既不肯以侥幸自名，则其不得者必皆以沉沦为叹，使天下常调举，生妄心，耻不若人，何所不至，欲望风俗之厚，岂可得哉？选人之改，京官常须十年以上，荐更险阻，计析毫厘，其间一事声牙，常至终身沦弃，今乃以一人之荐举而与之，犹恐未称，章服随至，使积劳久次而得者何以厌服哉？夫常调之人，非守则令，员多阙少，久已患之，不可复开多门，以待巧者。若巧者侵夺已甚，则拙者迫隘无聊，利害相形，不得不察。故近岁朴拙之人愈少，巧进之士益多，惟陛下重之，惜之，哀之，救之。如近日三司献言，使天下郡选一人，催驱三司文字许之，先次指射以酧其劳，则数年之后，审官吏部，又有三百馀人得先占阙，常调待次不其愈难。此外勾当发运均输，按行农田水利，巳振监司之体，各坏进用之心，转对者望以称旨而骤迁，奏课者求为优等而速化，相胜以力，相高以言，而名实乱矣。
惟陛下以简易为法，以清浄为心，使奸无所缘，而民德归厚，臣之所愿厚风俗者，此之谓也。
古者建国，使内外相制，轻重相权，如周，如唐，则外重而内轻。如秦，如魏，则外轻而内重，内重之末，必有奸臣指鹿之患。外重之弊，必有大国问鼎之忧。圣人方盛而虑衰，常先立法以救弊，我国家租赋籍于计省，重兵聚于京师，以古揆今，则似内重。恭惟祖宗所以深计而预虑，固非小臣所能臆度而周知，然其委任台谏之一端，则是圣人过防之至计。
历观秦汉以及五代，谏争而死，盖数百人，而自建隆以来，未尝罪一言者，纵有薄责，旋即超升，许以风闻，而无官长。风采所系，不问尊卑，言及乘舆则天子改容，事关廊庙则宰相待罪。故仁宗之世，议者讥宰相，但奉行台谏风旨而已，圣人深意流俗，岂知台谏固未必皆贤，所言亦未必皆是，然须养其锐气，而借之重权者，岂徒然哉？将以折奸臣之萌，而救内重之弊也。
夫奸臣之始，以台谏折之而有馀，及其既成，以干戈取之而不足。今法令严密，朝廷清明，所谓奸臣，万无此理。然而养猫以去鼠，不可以无鼠而养不捕之猫；畜狗以防奸，不可以无奸而畜不吠之狗。陛下得不上念祖宗设此官之意，下为子孙立万世之防，朝廷纪纲，孰大于此？臣自幼小所记，及闻长老之谈，皆谓台谏所言，常随天下公议，公议所与，台谏亦与之，公议所击，台谏亦击之。及至英庙之初，始建称亲之议，本非人主大过，亦无礼典明文，徒以众心未安，公议不允，当时台谏以死争之。
今者物论沸腾，怨讟交至，公议所在，亦可知矣。而相顾不发，中外失望。夫弹劾积威之后，虽庸人亦可奋扬风采，消委之馀，虽豪杰有所不能振起。臣恐自兹以往，习惯成风，尽为执政私人，以致人主孤立。纪纲一废，何事不生？
孔子曰：“鄙夫可与事，君也与哉？其未得之也，患得之，既得之，患失之，苟患失之，无所不至矣。”臣始读此书，疑其太过，以为鄙夫之患失，不过备位而苟容，及观李斯忧蒙恬之夺其权，则立二世以亡秦，卢杞忧怀光之数其恶，则误德宗以再乱，其心本生于患失，而其患乃至于丧邦。孔子之言，良不为过。是以知为国者，平居必有亡躯犯颜之士，则临难庶几有徇义守死之臣。若平居尚不能一言，则临难何以责其死节？人臣苟皆如此，天下亦曰殆哉。
君子和而不同，小人同而不和，和如和羮，同如济水。孙宝有言：“周公大圣，召公大贤，犹不相悦，著于经典。晋之王导，可谓元臣，每与客言，举坐称善，而述不悦，以为人非尧舜，安得每事尽善，导亦敛袵谢之。若使言无不同，意无不合，更唱迭和，何者非贤？万一有小人居其间，则人主何缘得以知觉？”
臣之所愿存纪纲者，此之谓也。
臣非敢历诋新政，苟无异论，如近日裁减皇族恩例，刋定任子条式，修完器械，阅习鼓旗，皆陛下神筭之至明，乾刚之必，断物议既允，臣敢有词。至于所献之三言，则非臣之私见，中外所病，其谁不知。昔禹戒舜曰：“无若丹朱傲，惟慢游是好。”舜岂有是哉？周公戒成王曰：“毋若商王，受之迷乱，酗于酒德。”成王岂有是哉？周昌以汉高为桀纣，刘毅以晋武为桓灵，当时人君，曾莫之罪，书之史册，以为美谈。使臣所献三言，皆朝廷未尝有此，则天下之幸，臣与有焉。若有万一似之，则陛下安可不察？然而臣之为计，可谓愚矣，以蝼蚁之命，试雷霆之威，积其狂愚，岂可数赦，大则身首异处，破坏家门，小则削籍投荒，流离道路。虽然，陛下必不为此。何哉？臣天赐至愚，笃于自信，向者与议学校贡举，首违大臣，本意巳期窜逐，敢意自全，而陛下独然其言，曲赐召对，从容久之，至谓臣曰：“方今政令得失安在？朕过失，指陈可也。”臣即对曰：“陛下生知之性，天纵文武，不患不明，不患不勤，不患不断，但患求治太速，进人太锐，听言太广。”又俾具述所以然之状，陛下颔之，曰：“卿所献三言，朕当熟思之。”臣之狂愚，非独今日，陛下容之久矣，岂其容之于始，而不赦之于终？恃此而言，所以不惧。臣之所惧者，讥刺既众，怨仇实多，必将诋臣以深文，中臣以危法，使陛下虽欲赦臣而不得，岂不殆哉。死亡不辞，但恐天下以臣为戒，无复言者，是以思之经月，夜以继昼，表成复毁，至于再三，感陛下听其一言，坏不能巳，卒进其说，惟陛下怜其愚忠，而卒赦之，不胜俯伏待罪忧恐之至。', '', '', '', NULL, '', 'indent', 1550131757, '5c1a6a6967f35600660f416a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640660, '竹枝词四首', NULL, 1, 2952, 0, 1, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'ci', '词', 'https://baike.baidu.com/item/%E7%AB%B9%E6%9E%9D%E8%AF%8D%E5%9B%9B%E9%A6%96/8940686?fr=aladdin', '', '【其一】
瞿塘峡口水烟低，白帝城头月向西。
唱到竹枝声咽处，寒猿闇鸟一时啼。
【其二】
竹枝苦怨怨何人？夜静山空歇又闻。
蛮儿巴女齐声唱，愁杀江楼病使君。
【其三】
巴东船舫上巴西，波面风生雨脚齐。
水蓼冷花红簇簇，江篱湿叶碧凄凄。
【其四】
江畔谁人唱竹枝？前声断咽后声迟。
怪来调苦缘词苦，多是通州司马诗。', '《竹枝词四首》是唐代诗人白居易创作的七言绝句组诗作品。第一首写深夜听唱《竹枝》；第二首写静夜听唱《竹枝》；第三首描绘诗人于江楼上所见的“竹枝”歌乡之雨景；第四首写听江畔唱《竹枝》。这组《竹枝词》内容充实健康，语言通俗晓畅。', '竹枝词：本巴、渝一带的民歌，唐代诗人多有拟作，刘禹锡、顾况、白居易等人成绩比较显著。
瞿（qú）塘峡：为长江三峡之首，也称夔峡。西起四川省奉节县白帝城，东至巫山大溪。两岸悬崖壁立，江流湍急，山势险峻，号称西蜀门户。水烟：水上的烟霭。
白帝：在今四川省奉节县东瞿塘峡口。
闇（ān）鸟：指归宿之鸟。
歇：停止，消止。
蛮儿巴女：指湖北、四川之间的青年男女。蛮，古时称楚因为荆蛮，称四川为巴蜀。巴，今四川省东部地区。
杀：形容程度很深。使君：古时对州郡长官的尊称，这里是作者自指，当时作者任忠州刺史。
巴东、巴西：均为郡名，前者在今四川奉节一带，后者在今四川阆中一带。船舫（fǎng）：泛指船。
雨脚：随云飘行、长垂及地的雨丝。
蓼（liǎo）：一年生或多年生草本植物，花小，白色或浅红色，生长在水边或水中。簇簇（cù）：丛列成行貌。
蓠（lí）：水中生长的一种藻类植物。
断咽（yè）：止断。
怪来：怪不得的意思。缘：因为。
通州司马：指元稹，当时元稹任通州司马。', '【其一】
瞿塘峡口，水雾蒙蒙，像轻烟一样低低地笼罩着江水。白帝城上的月亮已经向西偏斜。深夜有人唱起了令人伤心的竹枝民歌，当唱歌的声音哽咽着时，山上的猿猴和山鸟都一起悲伤地啼叫起来。
【其二】
《竹技》曲调苦怨究竟是把谁怨？夜静山空里歌声时续又时断。巴楚的青年男女齐声来歌唱，愁杯了江楼里的忠州病长官。
【其三】
坐着小船，从巴东到巴西去。一路上，江风吹动波浪，大雨下个不停。那江边的水蓼草开着白里带红的小花，似乎感到了寒冷，相互紧紧挤在一起；被雨打湿的江蓠草叶，更显得幽绿幽绿的。
【其四】
大江边是谁在唱那《竹枝词》？前声曲幽咽之后声调迟迟。难怪曲调苦只因为词语苦，所唱的多是通州司马的诗。', '[{"bookId": "645d09bbec56251f2eeb5b78", "bookTitle": "白居易诗文鉴赏辞典", "articleId": "6462d656cd12b001c6ddc830", "shortContent": "《白氏长庆集》卷十八有《竹枝词四首》，此为其中一首。白居易于元和十四年（819）春由江州赴任忠州刺史，这一组作品就是创作于此时。忠州，今属重庆。\n\n《竹枝》之曲，本出于民间。《乐府歌辞》卷八十一《近代曲辞》：“《竹枝》本出于巴渝。唐贞元中，刘禹锡在沅、湘，以里歌鄙陋，乃依骚人《九歌》，作《竹枝》新调九章，教里中儿歌之。由是盛于贞元元和之间。禹锡曰：‘《竹枝》，巴歈也。巴儿联歌，吹短笛击鼓以赴节，歌...", "authors": ["刘竞飞"], "pressName": "上海辞书出版社"}]', '爱新觉罗·弘历《唐宋诗醇》：“声韵悠扬，最合竹枝之体。”
唐汝询：“冷烟斜月之景，竹枝悲咽之声，即寒猿暗鸟尚不胜情，况可使愁人听之邪。”', 'indent', 1543572966, '5c009d8d9f54540066e2a75f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640661, '竹枝 · 一名巴渝辞', NULL, 0, 30, 0, 1, '皇甫松', NULL, 12831, '5858e7bd128fe1006b87d57a', '唐', 'ci', '词', '', '', '槟榔花发鹧鸪啼，雄飞烟瘴雌亦飞。
木棉花尽荔支垂，千花万花待郎归。
芙蓉并蒂一心连，花侵槅子眼应穿。
筵中蜡烛泪珠红，合欢桃核两人同。
斜江风起动横波，劈开莲子苦心多。
山头桃花谷底杏，两花窈窕遥相映。 ', '', '', '', NULL, '', 'indent', 1543573182, '5c009e659f545400674c2d89', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640663, '相思引二首 · 其一', NULL, 0, 300, 0, 1, '奕绘', NULL, 21722, '5858efaf128fe10069b28d4b', '清', 'ci', '词', '', '', '双乳山临易水涯，衔花小寺镇山洼。仙人去后，仙犬守桃花。
细草交承无漏果，绛跗深抱未开葩。松阴满地，幢影卧余霞。', '', '相思引：双调四十六字，前段四句三平韵，后段四句两平韵。房舜卿词用别称《玉交枝》，周紫芝词用别称《定风波令》，赵彦端词用别称《琴调相思引》，《古今词话》无名氏词用别称《镜中人》。', '', NULL, '', 'indent', 1543575055, '5c00a5b69f54540066e31011', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640664, '相思引二首 · 其二', NULL, 0, 300, 0, 1, '奕绘', NULL, 21722, '5858efaf128fe10069b28d4b', '清', 'ci', '词', '', '', '冲澹精神富贵花，墨香酣扫半开葩。笔尖到处，清露长仙芽。
云想衣裳嫌太艳，风吹魂梦恨难拿。新春初月，眉样一痕斜。', '', '相思引：双调四十六字，前段四句三平韵，后段四句两平韵。房舜卿词用别称《玉交枝》，周紫芝词用别称《定风波令》，赵彦端词用别称《琴调相思引》，《古今词话》无名氏词用别称《镜中人》。', '', NULL, '', 'indent', 1543575081, '5c00a5d0303f39005fef5913', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640665, '相思引 · 藕翘小榭听宛宛歌湘春夜月', NULL, 0, 369, 0, 1, '郑文焯', NULL, 25452, '5858f3458e450a006c7fea6d', '清', 'ci', '词', '', '', '记曲香名月里传。珠吭风约绕花圆。暗抛歌豆，红破第三弦。
艳拍重商秋玉谱，新题细品瘦金笺。井华清处，不数柳屯田。', '', '相思引：双调四十六字，前段四句三平韵，后段四句两平韵。房舜卿词用别称《玉交枝》，周紫芝词用别称《定风波令》，赵彦端词用别称《琴调相思引》，《古今词话》无名氏词用别称《镜中人》。', '', NULL, '', 'indent', 1543575130, '5c00a60144d904005f938c8f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640666, '相思引 · 元夕后二日夜雨即事', NULL, 0, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '绮陌将收五夜灯，后堂锁到第三层。画檐残烛，细雨恐难胜。
歌板敲愁飞火凤，枕函贮梦结红冰。觉来还记，踏月六街曾。', '', '相思引：双调四十六字，前段四句三平韵，后段四句两平韵。房舜卿词用别称《玉交枝》，周紫芝词用别称《定风波令》，赵彦端词用别称《琴调相思引》，《古今词话》无名氏词用别称《镜中人》。', '', NULL, '', 'indent', 1543575492, '5c00a767808ca400729affd2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640667, '相思引', NULL, 0, 326, 0, 1, '李慈铭', NULL, 20875, '5858eeda128fe1006dcc6711', '清', 'ci', '词', '', '', '侧侧轻寒到被池，玉凫烟重卷帘迟。有谁怜惜，挨病过花时。
燕子泥香消永日，绿杨风软见游丝。小栏红煞，无地著相思。', '', '相思引：双调四十六字，前段四句三平韵，后段四句两平韵。房舜卿词用别称《玉交枝》，周紫芝词用别称《定风波令》，赵彦端词用别称《琴调相思引》，《古今词话》无名氏词用别称《镜中人》。', '', NULL, '', 'indent', 1543575597, '5c00a7d0fb4ffe0069b7d46b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640668, '相思引', NULL, 0, 223, 0, 1, '史承谦', NULL, 36972, '5bf616d4808ca40072027674', '清', 'ci', '词', '', '', '不为横陈忆小怜，夜窗风细月如弦。拟添银叶、安稳耐孤眠。
百尺游丝牵别绪，一痕蛾绿淡秋烟。近来心事、都在药栏边。', '', '相思引：双调四十六字，前段四句三平韵，后段四句两平韵。房舜卿词用别称《玉交枝》，周紫芝词用别称《定风波令》，赵彦端词用别称《琴调相思引》，《古今词话》无名氏词用别称《镜中人》。', '', NULL, '', 'indent', 1543575645, '5c00a8041579a3005f305ff0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640677, '暗香', NULL, 0, 3, 0, 1, '危西麓', NULL, 27151, '5858f4df128fe1006dcc9703', '宋', 'ci', '词', '', '梢，开花繁艳，兵後流落人间。对花泫然承脸而赋', '馆娃艳骨。见数枝雪里，争开时节。底事化工，着意阳和暗偷泄。偏把红膏染质，都点缀、枝头如血。最好是、院落黄昏，压栏照水清绝。
风韵自迥别。谩记省故家，玉手曾折。翠条袅娜，犹学宫妆舞残月。肠断江南倦客，歌未了、琼壶敲缺。更忍见，吹万点、满庭绛雪。 ', '', '', '', NULL, '', 'indent', 1543835608, '5c049f7e9f545400677c3e0e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640678, '暗香 · 再和', NULL, 2, 513, 0, 1, '吴潜', NULL, 10788, '5858e5d8570c350069179bc0', '宋', 'ci', '词', '', '', '雪来比色。对澹然一笑，休喧笙笛。莫怪广平，铁石心肠为伊折。偏是三花两蕊，消万古、才人骚笔。尚记得，醉卧东园，天幕地为席。
回首，往事寂。正雨暗雾昏，万种愁积。锦江路悄，媒聘音沉两空忆。终是茅檐竹户，难指望、凌烟金碧。憔悴了、羌管里，怨谁始得。 ', '', '', '', NULL, '', 'indent', 1543835685, '5c049faf44d904005fc341cf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640679, '暗香', NULL, 0, 513, 0, 1, '吴潜', NULL, 10788, '5858e5d8570c350069179bc0', '宋', 'ci', '词', '', '及歌酒其下，今荒矣。园乃欧公记、君谟书，古今称二绝。犹忆其词云：高甍巨桷，水光日影，动摇而下上，其宽间深靓，可以答远响而生清风，此前日之颓垣断堑而荒墟也。嘉时令节，州人士女，啸歌而管弦，此前日之晦冥风雨、＿鼯鸟兽之嗥音也。令人慨然。', '澹然绝色。记故园月下，吹残龙笛。怅望楚云，日日归心大刀折。犹怕冰条冷蕊，轻点污、丹青凡笔。可怪底，屈子离骚，兰蕙独前席。
院宇，深更寂。正目断古邗，暮霭凝积。何郎旧梦，四十余年尚能忆。须索梅兄一笑，但矫首、层霄空碧。春在手、人在远，倩谁寄得。 ', '', '', '', NULL, '', 'indent', 1543835743, '5c04a0069f5454006612b31a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640781, '随园诗话补遗', NULL, 18, 173, 1, 1, '袁枚', NULL, 10099, '57b921bed342d3005ac840e9', '清', 'wen', '文', '', '', '凡菱笋、鱼虾，从水中采得，过半个时辰，则色味俱变；其为菱笋、鱼虾之形质，依然尚在，而其天则已失矣。谚云：“死蛟龙，不若活老鼠。”', '', '', '', NULL, '', 'indent', 1545321308, '5c1b4aa64773f7005f06b6f2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640682, '暗香 · 落梅', NULL, 1, 205, 0, 1, '高燮', NULL, 23336, '5858f12d1b69e60056f6695a', '清', 'ci', '词', '', '', '空劳怅望。向水边篱落，闲寻闲访。偏是东风，桃李枝枝各争放。
今日与君言别，眼看这、波翻雪浪。但撩来、花片零星，一例深深葬。
海样情无量。更取烹茶，涤将肺脏。痴怀谁谅。细嚼残英空半晌。
我自替伊凄怆。非欲避、百花头上，不忍见奈何天，繁华万状。', '', '', '', NULL, '', 'indent', 1543836222, '5c04a1e644d904005fc361ec', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640683, '暗香 · 白梅花', NULL, 2, 48, 0, 1, '陆蓉佩', NULL, 23099, '5858f0f31b69e60056f667ba', '清', 'ci', '词', '', '', '一分月色。照绮窗斗影，娟娟清绝。缟袂初逢，绿萼仙人似相识。
回首乡关旧梦，浑难问、南枝消息。看一树、瘦影横斜，寒素谢雕饰。
残雪。伴孤洁。正卷幔忽惊，竹外琼积。几回暗惜。玉质冰姿漫轻摘。
多少嫣红姹紫，更莫妒、天然风骨。应好护、开遍也，休教狼藉。', '', '', '', NULL, '', 'indent', 1543836284, '5c04a22544d904005fc36524', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640684, '卖花声 · 闺思', NULL, 0, 52, 0, 1, '康与之', NULL, 30748, '582fa4df128fe100696618e5', '宋', 'ci', '词', '', '', '蹙损远山眉。幽怨谁知。罗衾滴尽泪胭脂。夜过春寒愁未起，门外鸦啼。
惆怅阻佳期。人在天涯。东风频动小桃枝。正是销魂时候也，撩乱花飞。
', '', '', '', NULL, '', 'indent', 1543836681, '5c04a3b1fb4ffe0069e7b92a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640685, '卖花声 · 闺思', NULL, 0, 52, 0, 1, '康与之', NULL, 30748, '582fa4df128fe100696618e5', '宋', 'ci', '词', '', '', '愁捻断钗金。远信沈沈。秦筝调怨不成音。郎马不知何处也，楼外春深。
好梦已难寻。夜夜余衾。目穷千里正伤心。记得当初郎去路，绿树阴阴。', '', '', '', NULL, '', 'indent', 1543836737, '5c04a3e967f35600660dfc2f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640687, '卖花声 · 帘下美人影', NULL, 1, 253, 0, 1, '曹贞吉', NULL, 10302, '57ba7fdeefa631005a7b9f4a', '清', 'ci', '词', '', '', '对面尚参差。难慰相思。东风无力画帘垂。薄雾冥冥春未晓，掩映花枝。
蝉影乱罘罳。似隔天涯。金钩双控是何时。独立窥人人不见，卷上些儿。', '', '', '', NULL, '', 'indent', 1543837192, '5c04a5b0fb4ffe0069e7d5ab', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640688, '卖花声 · 秋夜', NULL, 1, 253, 0, 1, '曹贞吉', NULL, 10302, '57ba7fdeefa631005a7b9f4a', '清', 'ci', '词', '', '', '风紧纸窗鸣。秋气凄清。淡云笼月未分明。雨点疏如残夜漏，滴到三更。
无计破愁城。梦断魂惊。一天黄叶雁纵横。不待成霜霜满鬓，短发星星。
', '', '', '', NULL, '', 'indent', 1543837221, '5c04a5cc9f545400661306c6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640689, '卖花声 · 不寐口占', NULL, 0, 253, 0, 1, '曹贞吉', NULL, 10302, '57ba7fdeefa631005a7b9f4a', '清', 'ci', '词', '', '', '雨气没高林。庭院深深。流萤如豆草如针。又是嫩凉时候也，只欠疏砧。
旧梦杳难寻。云水沉沉。海南花发土墙阴。斜月窥人人未起，冷浸孤衾。', '', '', '', NULL, '', 'indent', 1543837253, '5c04a5ed1579a3005f604d52', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640690, '卖花声 · 丁巳清明', NULL, 26, 253, 0, 3, '曹贞吉', NULL, 10302, '57ba7fdeefa631005a7b9f4a', '清', 'ci', '词', '', '', '烟草似愁生。绿满长汀。隔墙一一卖花声。十日雨丝天作剧，渲染清明。
林外乍啼莺。楼外峰青。东风拂面酒微醒。攲帽垂鞭何处去，淰淰寒轻。', '', '', '', NULL, '', 'indent', 1543837303, '5c04a61c44d904005fc3a643', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640691, '卖花声 · 咏鼓子花腰', NULL, 0, 253, 0, 1, '曹贞吉', NULL, 10302, '57ba7fdeefa631005a7b9f4a', '清', 'ci', '词', '', '', '虚负此花名。听去无声。断云残雨过荒汀。摵摵凄凄闻响答，也欠分明。
宜傍战场生。画角连营。青山不动气纵横。广乐钧天谁间作，溪畔芦笙。', '', '', '', NULL, '', 'indent', 1543837326, '5c04a63644d904005fc3a799', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640694, '怀古', NULL, 5, 12, 1, 0, '萧观音', NULL, 35713, '5858fcbf8e450a006c803da4', '辽', 'shi', '诗', '', '', '宫中只数赵家妆，败雨残云误汉王。
惟有知情一片月，曾窥飞燕入昭阳。', '', '', '', '[{"bookId": "60d939cea06dc908f045ad24", "bookTitle": "元明清诗鉴赏辞典（新一版）", "articleId": "610e8cb85914587d02f4cb1b", "shortContent": "如诗题所示，这是一首怀古诗，从其字面上看，怀的是汉成帝的皇后赵飞燕。赵飞燕善歌舞，以体轻，号曰“飞燕”，被召入宫，先为婕妤，不久立为皇后。其妹赵合德亦为昭仪，姊妹专宠十余年。后因成帝倾心合德，飞燕渐被疏远。\n全诗四句，字面意思分两层。一、二句为一层，写汉家宫中对赵飞燕的指责。“数”，指责，责备。这个“数”字，为两句的关键性动词，“赵家妆”和“败雨残云误汉王”都是“数”的“宾语”，即赵氏被指责的瑕疵...", "authors": ["邱鸣皋"], "pressName": "上海辞书出版社"}]', '', 'center', 1587757418, '5c05e48d1579a3005f6edc0c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640695, '河满子', NULL, 0, 139, 0, 1, '晁端礼', NULL, 10180, '57bbddb5165abd00662c7aca', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E6%B2%B3%E6%BB%A1%E5%AD%90%C2%B7%E6%BB%A1%E6%B5%A6%E4%BA%AD%E5%89%8D%E6%9D%A8%E6%9F%B3/18855705?fr=aladdin', '', '满浦亭前杨柳，一年三度攀条。瞬息光阴都几许，离情常是迢迢。须信沈腰易瘦，争教潘鬓相饶。
不忍重寻香径，还来独立溪桥。唯有无情东去水，来时曾傍兰桡。今夜欲求好梦，望中莫遣魂消。', '', '', '', NULL, '', 'indent', 1543933215, '5c061c999f5454006624b8ed', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640696, '河满子', NULL, 10, 267, 0, 1, '晏几道', NULL, 10079, '57b931a6df0eea00633679de', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E6%B2%B3%E6%BB%A1%E5%AD%90%C2%B7%E7%BB%BF%E7%BB%AE%E7%90%B4%E4%B8%AD%E5%BF%83%E4%BA%8B/9873585?fr=aladdin', '', '绿绮琴中心事，齐纨扇上时光。五陵年少浑薄幸，轻如曲水飘香。夜夜魂消梦峡，年年泪尽啼湘。
归雁行边远字，惊鸾舞处离肠。蕙楼多少铅华在，从来错倚红妆。可羡邻姬十五，金钗早嫁王昌。', '《河满子·绿绮琴中心事》是北宋词人晏几道所写的一首词。此词塑造了歌妓沦落风尘的憔悴、悲苦形象，叙写了她们强颜欢笑中耗尽青春、耗尽生命的不幸身世，流露出作者对她们悲惨命运的深深关切和同情。', '', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74ad0ce818559d050791", "shortContent": "本词反映歌伎的不幸身世。首两句通过绿绮琴、齐纨扇传达出女子的幽怨，她的心情是借琴声曲曲传出的，一如小晏《菩萨蛮》所写的“哀筝一弄湘江曲，声声写尽江波绿。纤指十三弦，细将幽恨传。”齐纨扇，指歌舞时所持的团扇，“舞低杨柳楼心月，歌尽桃花扇底风”。公子王孙，征歌选色，纵情狂欢，真是所谓“肯爱千金轻一笑！”惜乎时光易逝，红颜难驻，一旦憔悴，就被遗弃，犹如秋扇见捐。古诗《怨歌行》云：“新裂齐纨素，鲜洁如霜雪...", "authors": ["潘君昭"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b40f8fda556506047e", "shortContent": "本词反映歌伎的不幸身世。首两句通过绿绮琴、齐纨扇传达出女子的幽怨，她的心情是借琴声曲曲传出的，一如小晏《菩萨蛮》所写的“哀筝一弄湘江曲，声声写尽江波绿。纤指十三弦，细将幽恨传。”齐纨扇，指歌舞时所持的团扇，“舞低杨柳楼心月，歌尽桃花扇底风。”公子王孙，征歌选色，纵情狂欢，真是所谓“肯爱千金轻一笑！”惜乎时光易逝，红颜难驻，一旦憔悴，就被遗弃，犹如秋扇见捐。古诗《怨歌行》云：“新裂齐纨素，鲜洁如霜雪...", "authors": ["潘君昭"], "pressName": "上海辞书出版社"}, {"bookId": "645d0c3f6de2f61f4bb3d104", "bookTitle": "二晏词鉴赏辞典", "articleId": "6467924d45e4710056d0d13b", "shortContent": "本词反映歌伎的不幸身世。首两句通过绿绮琴、齐纨扇传达出女子的幽怨，她的心情是借琴声曲曲传出的，一如小晏《菩萨蛮》所写的“哀筝一弄湘江曲，声声写尽江波绿。纤指十三弦，细将幽恨传。”齐纨扇，指歌舞时所持的团扇，“舞低杨柳楼心月，歌尽桃花扇底风。”公子王孙，征歌选色，纵情狂欢，真是所谓“肯爱千金轻一笑！”惜乎时光易逝，红颜难驻，一旦憔悴，就被遗弃，犹如秋扇见捐。古诗《怨歌行》云：“新裂齐纨素，鲜洁如霜雪...", "authors": ["潘君昭"], "pressName": "上海辞书出版社"}]', '', 'indent', 1543933282, '5c061d06303f39005f31365c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640697, '琐窗寒', NULL, 0, 300, 0, 1, '奕绘', NULL, 21722, '5858efaf128fe10069b28d4b', '清', 'ci', '词', '', '', '水际魂清，吟边句冷，暗馨幽俊。盘中舞罢，冻合铢衣生莹。
俏璁珑、身轻梦轻，尘埃不点湘娥鬓。有莲花清净，梅花高洁，梨花丰韵。
芳润。向谁问。问延伫冬春，几番风信。晓来寒重，金盏玉台冰晕。
袅亭亭、天仙水仙，茶杯酒斗和香沁。更今朝、雪意萧条，料有催诗分。', '', '', '', NULL, '', 'indent', 1544004959, '5c0735071579a3005f7e5be5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642101, '幽梦影 · 卷一 · 七十', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '著得一部新书，便是千秋大业；注得一部古书，允为万世宏功。', '', '', '', NULL, '', 'indent', 1556017174, '5cbe7f93a673f51cbdf354bb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640698, '琐窗寒 · 重游东湖', NULL, 0, 3, 0, 1, '苏茂一', NULL, 34505, '5858fba6b123db00658e2ef0', '宋', 'ci', '词', '', '', '云浦苍寒，烟堤幕翠，旧痕新涨。春愁十里，冉冉碧丝摇荡。记登临、少年思豪，唾壶击玉歌清壮。到如今梦里，秋风鸿阵，晚波渔唱。
惆怅。重来处，望画舫天边，辔丝原上。山阴秀句，付与一声云响。正东湖、谁家柳下，午阴漠漠人荡桨。最堪怜、白发周郎，为江山自赏。 ', '', '云浦：烟雾迷濛的水滨。幕：罩，覆盖。
唾壶：承唾之器。《世说新语·豪爽》有载：“王处仲每酒后辄咏‘老骥伏枥，志在千里；烈士暮年，壮心不已。’以铁如意击打唾壶，壶口尽缺。”后人因以“击碎唾壶”作为激赏诗文之词。
画舫：装饰华丽的游船。
辔丝：马缰绳。
山阴：浙江省绍兴市的古称。
秀句：优美的词句。
云响：响遏行云的意思。
周郎：指宋末词人周密。
', '烟雾迷濛的水滨苍茫凄寒，轻烟弥漫的岸堤被一片翠绿柳荫覆盖，碧水新涨漫过了往日的旧痕。湖边冉冉摇荡的十里柳丝播撒出浓浓的春愁。记得昔日登临游赏东湖之时，正值年少气盛，豪情满怀，曾以玉如意击打唾壶慷慨而歌，歌声清越雄壮。到如今，在梦中也只能梦到那秋风萧瑟，鸿雁列阵南飞；晚波荡漾，渔歌声声的凄凉景象了。真让人惆怅啊。重来之地，只看见华丽的游船在天边游弋，骏马在荒原上奔驰。往昔曾经在这儿写过多少优美的词句，（古诗百#科）如今所有的这一切付与那一声响遏行云的长叹。东湖岸边，不知是谁家的柳树下，在午日遮蔽起的漠漠浓阴中，我正划荡着船桨。最让人感到痛惜的是，已经满头白发的周郎还在独自醉心于游赏江山风景。', NULL, '', 'indent', 1544005215, '5c0735b9fb4ffe006905d786', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640699, '琐窗寒 · 十六夜雪用樊榭韵', NULL, 0, 41, 0, 1, '叶大庄', NULL, 19659, '5858edbd61ff4b0063d733df', '清', 'ci', '词', '', '', '昨雨刚停，晚寒峭甚，烟禽跳瓦。细听折竹，兽炭铜盆新冶。
□□□□□□□，水边蓦记丁家树。正鮰鱼欲上，青裘贳酒，冷吟闲话。
浅浅。分水汊。却在孤村，夜舂声罢。好事南中，堪卜丰年团社。
似明朝千峰草堂，琉璃屏风和粉写。诏山僮迟迟开门，满径香云惹。', '', '', '', NULL, '', 'indent', 1544005275, '5c0736449f545400679acb55', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640700, '琐窗寒', NULL, 0, 106, 0, 1, '高士奇', NULL, 23253, '5858f11861ff4b006cb90145', '清', 'ci', '词', '', '', '翠笼轻驼，红绵密裹，水山千叠。封题乍解，却称江村蛮榼。
堪爱是、清芬熨齿，赪腮素体圆仍洁。想西山野寺，树头垂颗，嫩凉初结。
吴越，灯宵节。也探钓传斝，夜阑歌阕。争夸远道，未忍浅尝深啮。
叹多年、流浪春华，因他感触浮生辙。忆从前、酒市旗亭，买来闲醉月。', '', '', '', NULL, '', 'indent', 1544005413, '5c0736cd303f39005f3dae22', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640701, '琐窗寒 · 初夏同葑田松泉过深柳草堂', NULL, 0, 1723, 0, 1, '厉鹗', NULL, 25122, '5858f2fa570c35006918079e', '清', 'ci', '词', '', '', '户小关云，城高缒碧，嫩阴摇瓦。何年种柳，正忆汉南游冶。
想依依、香绵褪时，绣鸳不到闲庭榭。付馀花倦蝶，桥痕帘影，伴人情话。
疏野。连渔汊，听笛弄沧浪，悄然歌罢。离踪似寄，顿冷故溪吟社。
笑输他、桃根渡头，载来翠峰偏淡写。看篱根、艇子萦回，任取浮萍惹。', '', '', '', NULL, '', 'indent', 1544005650, '5c0737ba67f35600662c4acc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640702, '琐窗寒 · 和豁轩韵', NULL, 0, 882, 0, 1, '林朝崧', NULL, 21556, '5858ef831b69e6006cb13b63', '清', 'ci', '词', '', '', '荏弱孱躯，温柔细语，劫风吹远。中宵酒渴，梦里时时错唤。
算穷途相依半生，怕人刚叩情深浅。唱一篇哀些，人间天上，可能听遍？
春短，知难恋。更苦是难逢，夜台鱼雁。百年有几？我亦无多时返。
问天天山檗涧松，死生流转何处见？最凄凉女哭儿啼，乍彻灵床饭。', '', '', '', NULL, '', 'indent', 1544005739, '5c0738139f54540066312059', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640703, '琐窗寒 · 再和豁轩', NULL, 0, 882, 0, 1, '林朝崧', NULL, 21556, '5858ef831b69e6006cb13b63', '清', 'ci', '词', '', '', '未惯生离，那堪死别？隔重泉远。欲寻去处，妙子稠桑难唤。
乍新巢双栖未安，叹伊福薄侬缘浅。忆廿年流落，牛衣鸿案，苦俱尝遍。
长短，前因恋。纵早替量珠，未成孤雁。知音会意，争似倩魂难返。
对灯前春风画图，绿窗鬓影长梦见。忏情痴便欲灰心，去乞伊蒲饭。', '', '', '', NULL, '', 'indent', 1544005767, '5c07382f67f35600662c507c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640704, '琐窗寒 · 三叠豁轩韵', NULL, 0, 882, 0, 1, '林朝崧', NULL, 21556, '5858ef831b69e6006cb13b63', '清', 'ci', '词', '', '', '梦醒春回，房栊寂寂，彩云飞远。罗窗镇掩，懊恼流莺空唤。
记三生钗钿誓盟，此情海水量深浅。到如今赢得檀奴哀什，素屏题遍。
发短，遗簪恋。况等是惊弦，劫馀哀雁。尘缘撒手，恁便玉京先返。
断肠人春心渐灰，旧时月色应照见。纵桃花赚入天台，肯吃胡麻饭？', '', '', '', NULL, '', 'indent', 1544005897, '5c073851303f39005f3dc228', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640705, '琐窗寒 · 初春和云臣韵', NULL, 0, 882, 0, 1, '林朝崧', NULL, 21556, '5858ef831b69e6006cb13b63', '清', 'ci', '词', '', '', '雪洒红窗，雨敲碧瓦，晓寒偏紧。莺簧生涩，不似旧时淹润。
记前春、城南水边，内家车子绡成阵。只新年节候，连阴做暝，误他花信。
点尽。安仁鬓。拚满幅春词，秦灰同烬。纵然墨淡，还有啼红堪认。
况如今、苔花小笺，誓成乌鲗犹隐隐。最难忘、梅月朦胧，不耐施脂粉。', '', '', '', NULL, '', 'indent', 1544005975, '5c0738ff9f54540066312c55', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640706, '倦寻芳 · 香泥垒燕', NULL, 1, 111, 0, 1, '卢祖皋', NULL, 10215, '57c5b6567db2a200681c47b8', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E5%80%A6%E5%AF%BB%E8%8A%B3%C2%B7%E9%A6%99%E6%B3%A5%E5%9E%92%E7%87%95/4727101?fr=aladdin', '', '香泥垒燕，密叶巢莺，春晦寒浅。花径风柔，着地舞茵红软。斗草烟欺罗袂薄，秋千影落春游倦。醉归来，记宝帐歌慵，锦屏香暖。　　别来怅、光阴容易，还又酴醿，牡丹开遍。妒恨疏狂，那更柳花迎面。鸿羽难凭芳信短，长安犹近归期远。倚危楼，但镇日、绣帘高卷。', '《倦寻芳·香泥垒燕》是南宋词人卢祖皋的一首词。上片开头五句，以工细的画笔描绘春景。“斗草”二句，由写景转入写人，反映闺中人的倦游情绪。“醉归来”三句，回忆当初男女双方春日相聚的欢乐与温馨。下片写分别之后女方对男方的愁怨相望之情。前半六句，写春末几种花的开放让女主人公痛感光阴之易逝，更加怀念意中人。后半五句，写双方天各一方，音信难通，越发使人整日惆怅，难以为怀。末二句以景结情，更显出女主人公愁怀浩茫。全词对春日景色和春闺女子形象都进行工笔细描，风格艳丽，含蓄蕴藉，一派清新词风。', '香泥垒（lěi）燕，密叶巢莺：燕子正用香泥垒窝，黄莺在浓密的树叶间筑巢。
着地舞茵（yīn）红软：指落花散落一地。
斗草：斗草是古代流行在女孩子中的一种游戏。斗草，又称“斗百草”，其最初的源起已无处可寻，最早见于文献是在魏晋南北朝时期，梁代宗懔的《荆楚岁时记》载：“五月五日，谓之浴兰节。荆楚人并踏百草．又有斗百草之戏。”
光阴容易：指时光容易流逝。
酴醿（túmí）：亦作"酴釄"、"酴醾"，酒名。亦有因颜色似之，而取以为花名，产于陕西秦岭南坡以及湖北、四川、贵州、云南等省。
疏狂：狂放不羁。
鸿羽（hóngyǔ）：鸿雁的羽毛。比喻轻微之物。晋葛洪《抱朴子·嘉遯》：“抑轻则鸿羽沉于弱水，抗重则玉石漂于飞波。”明沈鲸《双珠记·并拜荣升》：“可怜视死轻鸿羽，衔寃九地难追。”参见“鸿毛”。
长安犹近归期远：与遥远的长安相比，情人的归期更是渺茫难及。
危楼：高楼。
镇日（zhènrì）：整天，从早到晚。', '燕子衔来香泥建窝，黄莺筑巢在茂密的树叶间，春天阳光和煦寒意轻轻。清风柔和，吹着花丛间的路面，落花满地，像为小路铺上一条柔软的红色地毯。玩斗草游戏时，水雾浸透了我单薄的罗衫，荡过秋千我已经游玩得有些疲倦。醉酒归来，我在罗帐内懒洋洋地哼着歌曲，此刻在锦屏的护遮下我能感到暖暖的春意。自我们分别后我一直惆怅忧郁，单单在时间中苦熬着我还忍受得过去，却难以忍受春景给我带来的刺激。看那酴醿刚绽放出黄色的花朵，牡丹花又红遍在园圃里。最气愤的是那张狂的柳絮，到处飞舞粘贴上人的脸面，像在提示你，这是春天，因此让我更加妒恨生气。纵然我把表达芳心的信写得再短，也无鸿雁可拜托传递；纵然长安距离这儿再近，你的归返还是那么遥遥无期。我在高楼上把绣帘高高地卷起，整日站在那里远望，盼望你能早日归还和我永不分离。', NULL, '', 'indent', 1544006428, '5c073ac3808ca40072e94def', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640707, '倦寻芳 · 试墨', NULL, 0, 497, 0, 1, '王质', NULL, 36794, '588c9e6361ff4b006bd4783c', '宋', 'ci', '词', '', '', '冰壶秋月，去了潘郎，传到梁老。骑马乘船，麾斥五湖三岛。任捎云，兼拂日，拽蛟龙、鳞鬣都推倒。向尘中，分付高人胜士，把云烟扫。
乾坤巧。自苍筠无汗，乌锥无刃，此为至宝。第一君门通表。书囊谏草。第二文章扬事业，第三编简摅怀抱。千百般，终久被他磨了。 ', '', '', '', NULL, '', 'indent', 1544006490, '5c073b0244d904005fe21b68', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640708, '倦寻芳 · 春雨', NULL, 0, 128, 0, 1, '周贻繁', NULL, 21414, '5858ef618e450a006c7fc7eb', '清', 'ci', '词', '', '', '翠滋藓石，青润蕉窗，庭院风劲。酿冷妆寒，虚却画堂佳景。
紫燕嫞来梁上语，晓莺并坐枝头听。问啼鸠、把痴云唤出，几时才醒。
早又是、清明节候，柳弱花嫞，都没些兴。负了芳辰，恁地得成新咏。
别泪如珠添满掬，细丝千缕穿难定。只亏它、助湘波，载将帆影。', '', '', '', NULL, '', 'indent', 1544006729, '5c073bf19f5454006631591b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640709, '倦寻芳', NULL, 0, 106, 0, 1, '高士奇', NULL, 23253, '5858f11861ff4b006cb90145', '清', 'ci', '词', '', '', '才晴便雨，试暖翻寒，禁烟时候。一抹泥金，烘染夕阳林岫。
叹韶光，随逝水，莺花转眼成辜负。数邮签，恁茫茫过尽，羊肠人首。
西湖曲、钓矶无恙，买片春帆，欲归难聚。何处封侯，几度陌头杨柳。
忆得今宵灯烬暗，小窗曾梦辽西否。乍听残，五更风、乳鸦啼又。', '', '', '', NULL, '', 'indent', 1544006782, '5c073c269f545400679b2677', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640710, '倦寻芳 · 三月二十日饯春', NULL, 0, 10, 0, 1, '冒殷书', NULL, 21741, '5858efb41b69e60056f65e02', '清', 'ci', '词', '', '', '咄嗟过容，离别年年，舍我原惯。我定难留，留下乱红成片。
忆花朝，思寒食，更怀上巳情难遣。问春光，自古归何处，空随云散。
送行人、缠绵不了，那个临歧，能免三叹。却怪芳时，不把故人依恋。
也似伤心无一语，奈何频倩啼莺唤。更无端，变晴天、雨悲风怨。', '', '', '', NULL, '', 'indent', 1544007011, '5c073d0b303f39005f3e0a94', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640711, '倦寻芳', NULL, 1, 1702, 0, 1, '陈维崧', NULL, 10393, '57dfe65cd203090069efe796', '清', 'ci', '词', '', '', '画堂左侧，绣槛东偏，朵朵轻俊。欧碧姚黄，总是让他风韵。
紫府家乡原不远，红楼伴侣休相混。记当时，恰一枝初颤，便曾厮认。
讵料是、六年一别，今日人归，倍添春晕。满院浓香，砌就闲愁成阵。
雨后喜看娇态足，朝来怕见残妆褪。这情怀，沉醉醒时，细将花问。', '', '', '', NULL, '', 'indent', 1544007065, '5c073d41fb4ffe00690641cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640747, '管子 · 牧民', NULL, 29, 4, 2, 2, '管仲', NULL, 36975, '5c1a2f8f1579a3005f6d1d25', '周', 'wen', '文', '', '', '国颂
凡有地牧民者，务在四时，守在仓廪。国多财，则远者来，地辟举，则民留处；仓廪实，则知礼节；衣食足，则知荣辱；上服度，则六亲固。四维张，则君令行。故省刑之要，在禁文巧，守国之度，在饰四维，顺民之经，在明鬼神，只山川，敬宗庙，恭祖旧。不务天时，则财不生；不务地利，则仓廪不盈；野芜旷，则民乃菅，上无量，则民乃妄。文巧不禁，则民乃淫，不璋两原，则刑乃繁。不明鬼神，则陋民不悟；不只山川，则威令不闻；不敬宗庙，则民乃上校；不恭祖旧，则孝悌不备；四维不张，国乃灭亡。
四维
国有四维，一维绝则倾，二维绝则危，三维绝则覆，四维绝则灭。倾可正也，危可安也，覆可起也，灭不可复错也。何谓四维？一曰礼、二曰义、三曰廉、四曰耻。礼不逾节，义不自进。廉不蔽恶，耻不从枉。故不逾节，则上位安；不自进，则民无巧诈；不蔽恶，则行自全；不从枉，则邪事不生。
四顺
政之所兴，在顺民心。政之所废，在逆民心。民恶忧劳，我佚乐之。民恶贫贱，我富贵之，民恶危坠，我存安之。民恶灭绝，我生育之。能佚乐之，则民为之忧劳。能富贵之，则民为之贫贱。能存安之，则民为之危坠。能生育之，则民为之灭绝。故刑罚不足以畏其意，杀戮不足以服其心。故刑罚繁而意不恐，则令不行矣。杀戮众而心不服，则上位危矣。故从其四欲，则远者自亲；行其四恶，则近者叛之，故知“予之为取者，政之宝也”。
十一经
错国于不倾之地，积于不涸之仓，藏于不竭之府，下令于流水之原，使民于不争之官，明必死之路，开必得之门。不为不可成，不求不可得，不处不可久，不行不可复。错国于不倾之地者，授有德也；积于不涸之仓者，务五谷也；藏于不竭之府者，养桑麻育六畜也；下令于流水之原者，令顺民心也；使民于不争之官者，使各为其所长也；明必死之路者，严刑罚也；开必得之门者，信庆赏也；不为不可成者，量民力也；不求不可得者，不彊民以其所恶也；不处不可久者，不偷取一世也；不行不可复者，不欺其民也；故授有德，则国安；务五谷，则食足；养桑麻，育六畜，则民富；令顺民心，则威令行；使民各为其所长，则用备；严刑罚，则民远邪；信庆赏，则民轻难；量民力，则事无不成；不彊民以其所恶，则轴伪不生；不偷取一世，则民无怨心；不欺其民，则下亲其上。
六亲五法
以家为乡，乡不可为也。以乡为国，国不可为也。以国为天下，天下不可为也。以家为家，以乡为乡，以国为国，以天下为天下。毋曰不同生，远者不听。毋曰不同乡，远者不行。毋曰不同国，远者不从。如地如天，何私何亲？如月如日，唯君之节。御民之辔，在上之所贵。道民之门，在上之所先。召民之路，在上之所好恶。故君求之，则臣得之。君嗜之，则臣食之。君好之，则臣服之。君恶之，则臣匿之。毋蔽汝恶，毋异汝度，贤者将不汝助。言室满室，言堂满堂，是谓圣王。城郭沟渠，不足以固守；兵甲彊力，不足以应敌；博地多财，不足以有众。惟有道者，能备患于未形也，故祸不萌。天下不患无臣，患无君以使之。天下不患无财，患无人以分之。故知时者，可立以为长。无私者，可置以为政。审于时而察于用，而能备官者，可奉以为君也。缓者后于事。吝于财者失所亲，信小人者失士。', '《管子·牧民》是春秋时期军事家管仲创作的一篇散文。管子一书是稷下道家推尊管仲之作的集结，即以此为稷下之学的管子学派。《汉书·艺文志》将其列入子部道家类，《隋书·经籍志》列入法家类。《四库全书》将其列入子部法家类。书篇幅宏伟，内容复杂，思想丰富，是研究中国古代特别是先秦学术文化思想的重要典籍。', '', '国颂
凡是一个国家的君主，必须致力于四时农事，确保粮食贮备。国家财力充足，远方的人们就能自动迁来，荒地开发得好，本国的人民就能安心留住。粮食富裕，人们就知道礼节；衣食丰足，人们就懂得荣辱。君主的服用合乎法度，六亲就可以相安无事；四维发扬，君令就可以贯彻推行。因此，减少刑罚的关键，在于禁止奢侈；巩固国家的准则，在于整饰四维；教训人民的根本办法，则在于：尊敬鬼神、祭祀山川、敬重祖宗和宗亲故旧。不注意天时，财富就不能增长；不注意地利，粮食就不会充足。田野荒芜废弃，人民也将由此而惰怠；君主挥霍无度，则人民胡作妄为；不注意禁止奢侈，则人民放纵淫荡；不堵塞这两个根源；犯罪者就会大量增多。不尊鬼神，小民就不能感悟；不祭山川，威令就不能远播；不敬祖宗，老百姓就会犯上；不尊重宗亲故旧，孝悌就不完备。四维不发扬，国家就会灭亡。
四维
国有四维，缺了一维，国家就倾斜；缺了两维，国家就危险；缺了三维，国家就颠覆；缺了四维，国家就会灭亡。倾斜可以扶正，危险可以挽救，倾覆可以再起，只有灭亡了，那就不可收拾了。什么是四维呢？一是礼，二是义，三是廉，四是耻。有礼，人们就不会超越应守的规范；有义，就不会妄自求进；有廉，就不会掩饰过错；有耻，就不会趋从坏人。人们不越出应守的规范，为君者的地位就安定；不妄自求进，人们就不巧谋欺诈；不掩饰过错，行为就自然端正；不趋从坏人，邪乱的事情也就不会发生了。
四顺
政令所以能推行，在于顺应民心；政令所以废弛，在于违背民心。人民怕忧劳，我便使他安乐；人民怕贫贱，我便使他富贵；人民怕危难，我便使他安定；人民怕灭绝，我便使他生育繁息。因为我能使人民安乐，他们就可以为我承受忧劳；我能使人民富贵，他们就可以为我忍受贫贱；我能使人民安定，他们就可以为我承担危难；我能使人民生育繁息，他们也就不惜为我而牺牲了。单靠刑罚不足以使人民真正害伯，仅凭杀戮不足以使人民心悦诚服。刑罚繁重而人心不惧，法令就无法推行了；杀戮多行而人心不服，为君者的地位就危险了。因此，满足上述四种人民的愿望，疏远的自会亲近；强行上述四种人民厌恶的事情，亲近的也会叛离。由此可知，“予之于民就是取之于民”这个原则，是治国的法宝。
十一经
把国家建立在稳固的基础上。把粮食积存在取之不尽的粮仓里。把财货贮藏在用之不竭的府库里。把政令下达在流水源头上。把人民使用在无所争议的岗位上。向人们指出犯罪必死的道路。向人们敞开立功必赏的大门。不强干办不到的事。不追求得不到的利。不可立足于难得持久的地位。不去做不可再行的事情。所谓把国家建立在稳固的基础上，就是把政权交给有道德的人。所谓把粮食积存在取之不尽的粮仓里，就是要努力从事粮食生产。所谓把财富贮藏在用之不竭的府库里，就是要种植桑麻、饲养六畜。所谓把政令下达在流水源头上，就是要令顺民心。所谓把人民使用在无所争议的岗位上，就是要尽其所长。所谓向人民指出犯罪必死的道路，就是刑罚严厉。所谓向人民敞开立功必赏的大门，就是奖赏信实。所谓不强干办不到的事，就是要度量民力。所谓不追求得不到的利，就是不强迫人民去做他们厌恶的事情。所谓不可立足于难得持久的地位，就是不贪图一时侥幸。所谓不去做不可再行的事情，就是不欺骗人民。这样，把政权交给有道德的人，国家就能安定。努力从事粮食生产，民食就会充足。种植桑麻、饲养六畜，人民就可以富裕。能作到令顺民心，威令就可以贯彻。使人民各尽所长，用品就能齐备。刑罚严厉，人民就不去干坏事。奖赏信实，人民就不怕死难。量民力而行事，就可以事无不成。不强使人民干他们厌恶的事情，欺诈作假的行为就不会发生。不贪图一时侥幸，人民就不会抱怨。不欺骗人民，人民就拥戴君上。
六亲五法
按照治家的要求治理乡，乡不能治好；按照治乡的要求治理国，国不能治好；按照治国的要求治理天下，天下不可能治好。应该按照治家的要求治家，按照治乡的要求治乡，按照治国的要求治国，按照治天下的要求治理天下。不要因为不同姓，不听取外姓人的意见；不要因为不同乡，不采纳外乡入的办法；诸候国不要因为不同国，而不听从别国人的主张。象天地对待万物，没有什么偏私偏爱；像日月普照一切，才算得上君主的气度。
驾驭人民奔什么方向，看君主重视什么；引导人民走什么门路，看君主提倡什么；号召人民走什么途径，看君主的好恶是什么。君主追求的东西，臣下就想得到；君主爱吃的东西，臣下就想尝试；君主喜欢的事情，臣下就想实行；君主厌恶的事情，臣下就想规避。因此，不要掩蔽你的过错，不要擅改你的法度；否则，贤者将无法对你帮助。在室内讲话，要使全室的人知道；在堂上讲话，要使满堂的人知道。这样开诚布公，才称得上圣明的君主。单靠城郭沟渠，不一定能固守；仅有强大的武力和装备，不一定能御敌；地大物博，群众不一定就拥护。只有有道的君主，能做到防患于未然，才可避免灾祸的发生。
天下不怕没有能臣，怕的是没有君主去使用他们；天下不怕没有财货，怕的是无人去管理它们。所以，通晓天时的，可以任用为官长；没有私心的，可以安排作官吏；通晓天时，善于用财，而又能任用官吏的，就可以奉为君主了。处事迟钝的人，总是落后于形势；吝啬财物的人，总是无人亲近；偏信小人的人，总是失掉贤能的人才。', NULL, '', 'indent', 1545259480, '5c1a30229f545400665a5550', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640748, '请蠲积逋以安民生疏', NULL, 9, 23, 1, 1, '张居正', NULL, 16508, '5858eaff128fe10069b2675c', '明', 'wen', '文', '', '', '窃闻致理之要，惟在于安民，安民之道，在察其疾苦而已。……然尚有一事为民病者，带征钱粮是也。所谓带征者，将累年拖欠，搭配分数，与同见年钱粮，一并催征也。……况今考成法行，公私积贮，颇有赢余，即蠲此积逋，于国赋初无所损，而令膏泽洽乎黎庶，颂声溢于寰宇，民心固结，邦本辑宁，久安长治之道，计无便于此者，伏乞圣裁施行。', '“治政之要在于安民，安民之道在于察其疾苦”，是对明朝张居正“致理之要，惟在于安民，安民之道，在察其疾苦”一语的化用。致：达到，实现。要：关键。其意为：实现国家安定的关键，就在于使百姓安居乐业；而要让百姓安居乐业，就必须体察他们的疾苦。张居正的这一观点继承并发展了儒家民本主义思想。

万历十年（1582年），张居正向明神宗上《请蠲积逋以安民生疏》，奏请在全国范围内停止带征钱粮，对于百姓积欠的部分不再追究。蠲（juān）：除去，免除。积逋（bū）：累欠的钱粮。带征钱粮“将累年拖欠，搭配分数，与同见年钱粮，一并催征”，而百姓即使遇上丰年，收获的粮食也仅够交纳当年的钱粮；如遇上灾年，当年必然无法足额交纳。而征收钱粮的人为了向朝廷交差，“往往将见年所征那（nuó）作带征之数，名为完旧欠，实则减新收也”。如此年复一年，百姓所欠的钱粮就越来越多，终将无法承受。张居正提出了具体的解决办法：只需交足当年应交之数，不再补交过往年份的积欠。这样既减轻了百姓的负担，亦减轻了连带而来的吏治弊病。并称“久安长治之道，计无便于此者”。', '', '', NULL, '', 'indent', 1545259491, '5c1a424a303f39005f217c8a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640750, '晏子春秋 · 内篇 · 谏上第一', NULL, 5, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', '', '', '庄公矜勇力不顾行义晏子谏第一
庄公奋乎勇力，不顾于行义。勇力之士，无忌于国，贵戚不荐善，逼迩不引过，故晏子见公。公曰：“古者亦有徒以勇力立于世者乎？”
晏子对曰：“婴闻之，轻死以行礼谓之勇，诛暴不避彊谓之力。故勇力之立也，以行其礼义也。汤武用兵而不为逆。并国而不为贪，仁义之理也。诛暴不避彊，替罪不避众，勇力之行也。古之为勇力者，行礼义也；今上无仁义之理，下无替罪诛暴之行，而徒以勇力立于世，则诸侯行之以国危，匹夫行之以家残。昔夏之衰也，有推侈、大戏，殷之衰也，有费仲、恶来，足走千里，手裂兕虎，任之以力，凌轹天下，威戮无罪，崇尚勇力，不顾义理，是以桀纣以灭，殷夏以衰。今公目夺乎勇力，不顾乎行义，勇力之士，无忌于国，身立威强，行本淫暴，贵戚不荐善，逼迩不引过，反圣王之德，而循灭君之行，用此存者，婴未闻有也。”
景公饮酒酣愿诸大夫无为礼晏子谏第二
景公饮酒酣，曰：“今日愿与诸大夫为乐饮，请无为礼。”晏子蹴然改容曰：“君之言过矣！群臣固欲君之无礼也。力多足以胜其长，勇多足以弑君，而礼不使也。禽兽以力为政，彊者犯弱，故日易主，今君去礼，则是禽兽也。群臣以力为政，彊者犯弱，而日易主，君将安立矣！凡人之所以贵于禽兽者，以有礼也；故诗曰：‘人而无礼，胡不遄死。’礼不可无也。”
公湎而不听。少间，公出，晏子不起，公入，不起；交举则先饮。公怒，色变，抑手疾视曰：“向者夫子之教寡人无礼之不可也，寡人出入不起，交举则先饮，礼也？”
晏子避席再拜稽首而请曰：“婴敢与君言而忘之乎？臣以致无礼之实也。君若欲无礼，此是已！”
公曰：“若是，孤之罪也。夫子就席，寡人闻命矣。”觞三行，遂罢酒。盖是后也，饬法修礼以治国政，而百姓肃也。
景公饮酒酲三日而后发晏子谏第三
景公饮酒，酲，三日而后发。
晏子见曰：“君病酒乎？”公曰：“然。”
晏子曰：“古之饮酒也，足以通气合好而已矣。故男不群乐以妨事，女不群乐以妨功。男女群乐者，周觞五献，过之者诛。君身服之，故外无怨治，内无乱行。今一日饮酒，而三日寝之，国治怨乎外，左右乱乎内。以刑罚自防者，劝乎为非；以赏誉自劝者，惰乎为善；上离德行，民轻赏罚，失所以为国矣。愿君节之也！”
景公饮酒七日不纳弦章之言晏子谏第四
景公饮酒，七日七夜不止。弦章谏曰：“君欲饮酒七日七夜，章愿君废酒也！不然，章赐死。”
晏子入见，公曰：“章谏吾曰：‘愿君之废酒也！不然，章赐死。’如是而听之，则臣为制也；不听，又爱其死。”
晏子曰：“幸矣章遇君也！令章遇桀纣者，章死久矣。”于是公遂废酒。
景公饮酒不恤天灾致能歌者晏子谏第五
景公之时，霖雨十有七日。公饮酒，日夜相继。晏子请发粟于民，三请，不见许。公命柏遽巡国，致能歌者。晏子闻之，不说，遂分家粟于氓，致任器于陌，徒行见公曰：“十有七日矣！怀宝乡有数十，饥氓里有数家，百姓老弱，冻寒不得短褐，饥饿不得糟糠，敝撤无走，四顾无告。而君不恤，日夜饮酒，令国致乐不已，马食府粟，狗餍刍豢，三保之妾，俱足粱肉。狗马保妾，不已厚乎？民氓百姓，不亦薄乎？故里穷而无告，无乐有上矣；饥饿而无告，无乐有君矣。婴奉数之策，以随百官之吏，民饥饿穷约而无告，使上淫湎失本而不恤，婴之罪大矣。”再拜稽首，请身而去，遂走而出。公从之，兼于涂而不能逮，令趣驾追晏子，其家，不及。粟米尽于氓，任器存于陌，公驱及之康内。
公下车从晏子曰：“寡人有罪，夫子倍弃不援，寡人不足以有约也，夫子不顾社稷百姓乎？愿夫子之幸存寡人，寡人请奉齐国之粟米财货，委之百姓，多寡轻重，惟夫子之令。”遂拜于途。晏子乃返，命禀巡氓，家有布缕之本而绝食者，使有终月之委；绝本之家，使有期年之食，无委积之氓，与之薪橑，使足以毕霖雨。令柏巡氓，家室不能御者，予之金；巡求氓寡用财乏者，死三日而毕，后者若不用令之罪。公出舍，损肉撤酒，马不食府粟，狗不食饘肉，辟拂嗛齐，酒徒减赐。三日，吏告毕上：贫氓万七千家，用粟九十七万钟，薪橑万三千乘；怀宝二千七百家，用金三千。公然后就内退食，琴瑟不张，钟鼓不陈。晏子请左右与可令歌舞足以留思虞者退之，辟拂三千，谢于下陈，人待三，士待四，出之关外也。
景公夜听新乐而不朝晏子谏第六
晏子朝，杜扃望羊待于朝。晏子曰：“君奚故不朝？”
对曰：“君夜发不可以朝。”晏子曰：“何故？”对曰：“梁丘据扃入歌人虞，变齐音。”
晏子退朝，命宗祝修礼而拘虞，公闻之而怒曰：“何故而拘虞？”晏子曰：“以新乐淫君。”
公曰：“诸侯之事，百官之政，寡人愿以请子。酒醴之味，金石之声，愿夫子无与焉。夫乐，何必夫故哉？”
对曰：“夫乐亡而礼从之，礼亡而政从之，政亡而国从之。国衰，臣惧君之逆政之行。有歌，纣作北里，幽厉之声，顾夫淫以鄙而偕亡。君奚轻变夫故哉？”
公曰：“不幸有社稷之业，不择言而出之，请受命矣。”
景公燕赏无功而罪有司晏子谏第七
景公燕赏于国内，万钟者三，千钟者五，令三出，而职计莫之从。公怒，令免职计，令三出，而士师莫之从。公不说。晏子见，公谓晏子曰：“寡人闻君国者，爱人则能利之，恶人则能疏之。今寡人爱人不能利，恶人不能疏，失君道矣。”
晏子曰：“婴闻之，君正臣从谓之顺，君僻臣从谓之逆。今君赏谗谀之民，而令吏必从，则是使君失其道，臣失其守也。先王之立爱，以劝善也，其立恶，以禁暴也。昔者三代之兴也，利于国者爱之，害于国者恶之，故明所爱而贤良众，明所恶而邪僻灭，是以天下治平，百姓和集。及其衰也，行安简易，身安逸乐，顺于己者爱之，逆于己者恶之，故明所爱而邪僻繁，明所恶而贤良灭，离散百姓，危覆社稷。君上不度圣王之兴，而下不观惰君之衰，臣惧君之逆政之行，有司不敢争，以覆社稷，危宗庙。”
公曰：“寡人不知也，请从士师之策。”国内之禄，所收者三也。
景公信用谗佞赏罚失中晏子谏第八
景公信用谗佞，赏无功，罚不辜。晏子谏曰：“臣闻明君望圣人而信其教，不闻听谗佞以诛赏。今与左右相说颂也，曰：‘比死者勉为乐乎！吾安能为仁而愈黥民耳矣！’故内宠之妾，迫夺于国，外宠之臣，矫夺于鄙，执法之吏，并荷百姓。民愁苦约病，而奸驱尤佚，隐情奄恶，蔽谄其上，故虽有至圣大贤，岂能胜若谗哉！是以忠臣之常有灾伤也。臣闻古者之士，可与得之，不可与失之；可与进之，不可与退之。臣请逃之矣。”遂鞭马而出。
公使韩子休追之，曰：“孤不仁，不能顺教，以至此极，夫子休国焉而往，寡人将从而后。”晏子遂鞭马而返。其仆曰：“向之去何速？今之返又何速？”晏子曰：“非子之所知也，公之言至矣。”
景公爱嬖妾随其所欲晏子谏第九
翟王子羡臣于景公，以重驾，公观之而不说也。嬖人婴子欲观之，公曰：“及晏子寝病也。”居囿中台上以观之，婴子说之，因为之请曰：“厚禄之！”公许诺。
晏子起病而见公，公曰：“翟王子羡之驾，寡人甚说之，请使之示乎？”晏子曰：“驾御之事，臣无职焉。”公曰：“寡人一乐之，是欲禄之以万钟，其足乎？”对曰：“昔卫士东野之驾也，公说之，婴子不说，公曰不说，遂不观。今翟王子羡之驾也，公不说，婴子说，公因说之；为请，公许之，则是妇人为制也。且不乐治人，而乐治马，不厚禄贤人，而厚禄御夫。昔者先君桓公之地狭于今，修法治，广政教，以霸诸侯。今君，一诸侯无能亲也，岁凶年饥，道途死者相望也。君不此忧耻，而惟图耳目之乐，不修先君之功烈，而惟饰驾御之伎，则公不顾民而忘国甚矣。且诗曰：‘载骖载驷，君子所诫。’夫驾八，固非制也，今又重此，其为非制也，不滋甚乎！且君苟美乐之，国必众为之，田猎则不便，道行致远则不可，然而用马数倍，此非御下之道也。淫于耳目，不当民务，此圣王之所禁也。君苟美乐之，诸侯必或效我，君无厚德善政以被诸侯，而易之以僻，此非所以子民、彰名、致远、亲邻国之道也。且贤良废灭，孤寡不振，而听嬖妾以禄御夫以蓄怨，与民为雠之道也。诗曰：‘哲夫成城，哲妇倾城。’今君不免成城之求，而惟倾城之务，国之亡日至矣。君其图之！”
公曰：“善。”遂不复观，乃罢归翟王子羡，而疏嬖人婴子。
景公敕五子之傅而失言晏子谏第十
景公有男子五人，所使傅之者，皆有车百乘者也，晏子为一焉。公召其傅曰：“勉之！将以而所傅为子。”及晏子，晏子辞曰：“君命其臣，据其肩以尽其力，臣敢不勉乎！今有之家，此一国之权臣也，人人以君命命之曰：‘将以而所傅为子，’此离树别党，倾国之道也，婴不敢受命，愿君图之！”
景公欲废适子阳生而立荼晏子谏第十一
淳于人纳女于景公，生孺子荼，景公爱之。诸臣谋欲废公子阳生而立荼，公以告晏子。
晏子曰：“不可。夫以贱匹贵，国之害也；置大立少，乱之本也。夫阳生，生而长，国人戴之，君其勿易！夫服位有等，故贱不陵贵；立子有礼，故孽不乱宗。愿君教荼以礼而勿陷于邪，导之以义而勿湛于利。长少行其道，宗孽得其伦。夫阳生敢毋使荼餍粱肉之味，玩金石之声，而有患乎？废长立少，不可以教下；尊孽卑宗，不可以利所爱。长少无等，宗孽无别，是设贼树奸之本也。君其图之！古之明君，非不知繁乐也，以为乐淫则哀，非不知立爱也，以为义失则忧。是故制乐以节，立子以道。若夫恃谗谀以事君者，不足以责信。今君用谗人之谋，听乱夫之言也，废长立少；臣恐后人之有因君之过以资其邪，废少而立长以成其利者。君其图之！”公不听。
景公没，田氏杀君荼，立阳生；杀阳生，立简公；杀简公而取齐国。
景公病久不愈欲诛祝史以谢晏子谏第十二
景公疥且疟，期年不已。召会谴、梁丘据、晏子而问焉，曰：“寡人之病病矣，使史固与祝佗巡山川宗庙，牺牲珪璧，莫不备具，数其常多先君桓公，桓公一则寡人再。病不已，滋甚，予欲杀二子者以说于上帝，其可乎？”会谴、梁丘据曰：“可。”晏子不对。公曰：“晏子何如？”
晏子曰：“君以祝为有益乎？”公曰：“然。”“若以为有益，则诅亦有损也。君疏辅而远拂，忠臣拥塞，谏言不出。臣闻之，近臣嘿，远臣喑，众口铄金。今自聊摄以东，姑尤以西者，此其人民众矣，百姓之咎怨诽谤，诅君于上帝者多矣。一国诅，两人祝，虽善祝者不能胜也。且夫祝直言情，则谤吾君也；隐匿过，则欺上帝也。上帝神，则不可欺；上帝不神，祝亦无益。愿君察之也。不然，刑无罪，夏商所以灭也。”
公曰：“善解余惑，加冠！”命会谴毋治齐国之政，梁丘据毋治宾客之事，兼属之乎晏子。晏子辞，不得命，受相退，把政，改月而君病悛。公曰：“昔吾先君桓公，以管子为有力，邑狐与谷，以共宗庙之鲜，赐其忠臣，则是多忠臣者。子今忠臣也，寡人请赐子州款。”辞曰：“管子有一美，婴不如也；有一恶，婴不忍为也，其宗庙之养鲜也。”终辞而不受。
景公怒封人之祝不逊晏子谏第十三
景公游于麦丘，问其封人曰：“年几何矣？”对曰：“鄙人之年八十五矣。”公曰：“寿哉！子其祝我。”封人曰：“使君之年长于胡，宜国家。”公曰：“善哉！子其复之。”曰：“使君之嗣，寿皆若鄙臣之年。”公曰：“善哉！子其复之。”封人曰：“使君无得罪于民。”公曰：“诚有鄙民得罪于君则可，安有君得罪于民者乎？”
晏子谏曰：“君过矣！彼疏者有罪，戚者治之，贱者有罪，贵者治之；君得罪于民，谁将治之？敢问：桀纣，君诛乎，民诛乎？”
公曰：“寡人固也。”于是赐封人麦丘以为邑。
景公欲使楚巫致五帝以明德晏子谏第十四
楚巫微导裔款以见景公，侍坐三日，景公说之。楚巫曰：“公，明神之主，帝王之君也。公即位有七年矣，事未大济者，明神未至也。请致五帝，以明君德。”景公再拜稽首。楚巫曰：“请巡国郊以观帝位。”至于牛山而不敢登，曰：“五帝之位，在于国南，请斋而后登之。”公命百官供斋具于楚巫之所，裔款视事。晏子闻之而见于公曰：“公令楚巫斋牛山乎？”公曰：“然。致五帝以明寡人之德，神将降福于寡人，其有所济乎？”晏子曰：“君之言过矣！古之王者，德厚足以安世，行广足以容众，诸侯戴之，以为君长，百姓归之，以为父母。是故天地四时和而不失，星辰日月顺而不乱，德厚行广，配天象时，然后为帝王之君，明神之主。古者不慢行而繁祭，不轻身而恃巫。今政乱而行僻，而求五帝之明德也？弃贤而用巫，而求帝王之在身也？夫民不苟德，福不苟降，君之帝王，不亦难乎！惜乎！君位之高，所论之卑也。”公曰：“裔款以楚巫命寡人曰：‘试尝见而观焉。’寡人见而说之，信其道，行其言。今夫子讥之，请逐楚巫而拘裔款。”晏子曰：“楚巫不可出。”公曰：“何故？”对曰：“楚巫出，诸侯必或受之。公信之，以过于内，不知；出以易诸侯于外，不仁。请东楚巫而拘裔款。”公曰：“诺。”故曰：送楚巫于东，而拘裔款于国也。
景公欲祠灵山河伯以祷雨晏子谏第十五
齐大旱逾时，景公召群臣问曰：“天不雨久矣，民且有饥色。吾使人卜，云，祟在高山广水。寡人欲少赋敛以祠灵山，可乎？”群臣莫对。晏子进曰：“不可！祠此无益也。夫灵山固以石为身，以草木为发，天久不雨，发将焦，身将热，彼独不欲雨乎？祠之无益。”
公曰：“不然，吾欲祠河伯，可乎？”
晏子曰：“不可！河伯以水为国，以鱼鳖为民，天久不雨，泉将下，百川竭，国将亡，民将灭矣，彼独不欲雨乎？祠之何益！”
景公曰：“今为之柰何？”
晏子曰：“君诚避宫殿暴露，与灵山河伯共忧，其幸而雨乎！”于是景公出野居暴露，三日，天果大雨，民尽得种时。
景公曰：“善哉！晏子之言，可无用乎！其维有德。”
景公贪长有国之乐晏子谏第十六
景公将观于淄上，与晏子闲立。公喟然叹曰：“呜呼！使国可长保而传于子孙，岂不乐哉？”
晏子对曰：“婴闻明王不徒立，百姓不虚至。今君以政乱国，以行弃民久矣，而声欲保之，不亦难乎！婴闻之，能长保国者，能终善者也。诸侯并立，能终善者为长；列士并学，能终善者为师。昔先君桓公，其方任贤而赞德之时，亡国恃以存，危国仰以安，是以民乐其政而世高其德，行远征暴，劳者不疾，驱海内使朝天子，而诸侯不怨。当是时，盛君之行不能进焉。及其卒而衰，怠于德而并于乐，身溺于妇侍而谋因竖刁，是以民苦其政，而世非其行，故身死乎胡宫而不举，虫出而不收。当是时也，桀纣之卒不能恶焉。诗曰：‘靡不有初，鲜克有终。’不能终善者，不遂其君。今君临民若寇雠，见善若避热，乱政而危贤，必逆于众，肆欲于民，而诛虐于下，恐及于身。婴之年老，不能待于君使矣，行不能革，则持节以没世耳。”
景公登牛山悲去国而死晏子谏第十七
景公游于牛山，北临其国城而流涕曰：“若何滂滂去此而死乎！”艾孔、梁丘据皆从而泣。晏子独笑于旁，公刷涕而顾晏子曰：“寡人今日游悲，孔与据皆从寡人而涕泣，子之独笑，何也？”
晏子对曰：“使贤者常守之，则太公、桓公将常守之矣；使勇者常守之，则庄公、灵公将常守之矣。数君者将守之，则吾君安得此位而立焉？以其迭处之，迭去之，至于君也，而独为之流涕，是不仁也。不仁之君见一，谄谀之臣见二，此臣之所以独窃笑也。”
景公游公阜一日有三过言晏子谏第十八
景公出游于公阜，北面望睹齐国曰：“呜呼！使古而无死，何如？”晏子曰：“昔者上帝以人之殁为善，仁者息焉，不仁者伏焉。若使古而无死，丁公、太公将有齐国，桓、襄、文、武将皆相之，君将戴笠衣褐，执铫耨以蹲行畎亩之中，孰暇患死！”公忿然作色，不说。无几何而梁丘据御六马而来，公曰：“是谁也？”晏子曰：“据也。”公曰：“何如？”曰：“大暑而疾驰，甚者马死，薄者马伤，非据孰敢为之！”公曰：“据与我和者夫！”晏子曰：“此所谓同也，所谓和者，君甘则臣酸，君淡则臣咸。今据也甘君亦甘，所谓同也，安得为和！”公忿然作色，不说。无几何，日暮，公西面望睹彗星，召伯常骞，使禳去之。晏子曰：“不可！此天教也。日月之气，风雨不时，彗星之出，天为民之乱见之，故诏之妖祥，以戒不敬。今君若设文而受谏，谒圣贤人，虽不去彗，星将自亡。今君嗜酒而并于乐，政不饰而宽于小人，近谗好优，恶文而疏圣贤人，何暇在彗！茀又将见矣。”公忿然作色，不说。及晏子卒，公出，背而泣曰：“呜呼！昔者从夫子而游公阜，夫子一日而三责我，今谁责寡人哉！”
景公游寒涂不恤死胔晏子谏第十九
景公出游于寒涂，睹死胔，默然不问。晏子谏曰：“昔吾先君桓公出游，睹饥者与之食，睹疾者与之财，使令不劳力，籍敛不费民。先君将游，百姓皆说曰：‘君当幸游吾乡乎！’今君游于寒涂，据四十里之氓，殚财不足以奉敛，尽力不能周役民氓，饥寒冻馁，死胔相望，而君不问，失君道矣。财屈力竭，下无以亲上；骄泰奢侈，上无以亲下。上下交离，君臣无亲，此三代之所以衰也。今君行之，婴惧公族之危，以为异姓之福也。”公曰：“然！为上而忘下，厚藉敛而忘民，吾罪大矣。”于是敛死胔，发粟于民，据四十里之氓不服政其年，公三月不出游。
景公衣狐白裘不知天寒晏子谏第二十
景公之时，雨雪三日而不霁。公被狐白之裘，坐堂侧陛。晏子入见，立有间，公曰：“怪哉！雨雪日而天不寒。”
晏子对曰：“天不寒乎？”公笑。晏子曰：“婴闻古之贤君饱而知人之饥，温而知人之寒，逸而知人之劳。今君不知也。”
公曰：“善！寡人闻命矣。”乃令出裘发粟，与饥寒。令所睹于涂者，无问其乡；所睹于里者，无问其家；循国计数，无言其名。士既事者兼月，疾者兼岁。
孔子闻之曰：“晏子能明其所欲，景公能行其所善也。”
景公异荧惑守虚而不去晏子谏第二十一
景公之时，荧惑守于虚，期年不去。公异之，召晏子而问曰：“吾闻之，人行善者天赏之，行不善者天殃之。荧惑，天罚也，今留虚，其孰当之？”
晏子曰：“齐当之。”公不说，曰：“天下大国十二，皆曰诸侯，齐独何以当？”
晏子曰：“虚，齐野也。且天之下殃，固干富彊，为善不用，出政不行，贤人使远，谗人反昌，百姓疾怨，自为祈祥，录录彊食，进死何伤！是以列舍无次，变星有芒，荧惑回逆，孽星在旁，有贤不用，安得不亡！”公曰：“可去乎？”
对曰：“可致者可去，不可致者不可去。”公曰：“寡人为之若何？”
对曰：“盍去冤聚之狱，使反田矣；散百官之财，施之民矣；振孤寡而敬老人矣。夫若是者，百恶可去，何独是孽乎！”公曰：“善。”行之三月，而荧惑迁。
景公将伐宋瞢二丈夫立而怒晏子谏第二十二
景公举兵将伐宋，师过泰山，公瞢见二丈夫立而怒，其怒甚盛。公恐，觉，辟门召占瞢者，至。公曰：“今夕吾瞢二丈夫立而怒，不知其所言，其怒甚盛，吾犹识其状，识其声。”占瞢者曰：“师过泰山而不用事，故泰山之神怒也。请趣召祝史祠乎泰山则可。”公曰：“诺。”
明日，晏子朝见，公告之如占瞢之言也。公曰：“占瞢者之言曰：‘师过泰山而不用事，故泰山之神怒也。’今使人召祝史祠之。”晏子俯有间，对曰：“占瞢者不识也，此非泰山之神，是宋之先汤与伊尹也。”公疑，以为泰山神。
晏子曰：“公疑之，则婴请言汤伊尹之状也。汤质皙而长，颜以髯，兑上丰下，倨身而扬声。”公曰：“然，是已。”“伊尹黑而短，蓬而髯，丰上兑下，偻身而下声。”公曰：“然，是已。今若何？”
晏子曰：“夫汤、太甲、武丁、祖乙，天下之盛君也，不宜无后。今惟宋耳，而公伐之，故汤伊尹怒，请散师以平宋。”景公不用，终伐宋。晏子曰：“伐无罪之国，以怒明神，不易行以续蓄，进师以近过，非婴所知也。师若果进，军必有殃。”
军进再舍，鼓毁将殪。公乃辞乎晏子，散师，不果伐宋。
景公从畋十八日不返国晏子谏第二十三
景公畋于署梁，十有八日而不返。晏子自国往见公。比至，衣冠不正，不革衣冠，望游而驰。
公望见晏子，下而急带曰：“夫子何为遽？国家无有故乎？”晏子对曰：“不亦急也！虽然，婴愿有复也。国人皆以君为安野而不安国，好兽而恶民，毋乃不可乎？”
公曰：“何哉？吾为夫妇狱讼之不正乎？则泰士子牛存矣；为社稷宗庙之不享乎？则泰祝子游存矣；为诸侯宾客莫之应乎？则行人子羽存矣；为田野之不僻，仓库之不实？则申田存焉；为国家之有余不足聘乎？则吾子存矣。寡人之有五子，犹心之有四支，心有四支，故心得佚焉。今寡人有五子，故寡人得佚焉，岂不可哉！”
晏子对曰：“婴闻之，与君言异。若乃心之有四支，而心得佚焉，可；得令四支无心，十有八日；不亦久乎！”公于是罢畋而归。
景公欲诛骇鸟野人晏子谏第二十四
景公射鸟，野人骇之。公怒，令吏诛之。
晏子曰：“野人不知也。臣闻赏无功谓之乱，罪不知谓之虐。两者，先王之禁也；以飞鸟犯先王之禁，不可！今君不明先王之制，而无仁义之心，是以从欲而轻诛。夫鸟兽，固人之养也，野人骇之，不亦宜乎！
公曰：“善！自今已后，弛鸟兽之禁，无以苛民也。”
景公所爱马死欲诛圉人晏子谏第二十五
景公使圉人养所爱马，暴死，公怒，令人操刀解养马者。是时晏子侍前，左右执刀而进，晏子止而问于公曰：“尧舜支解人，从何躯始？”公矍然曰：“从寡人始。”遂不支解。
公曰：“以属狱。”
晏子曰：“此不知其罪而死，臣为君数之，使知其罪，然后致之狱。”公曰：“可。”
晏子数之曰：“尔罪有三：公使汝养马而杀之，当死罪一也；又杀公之所最善马，当死罪二也；使公以一马之故而杀人，百姓闻之必怨吾君，诸侯闻之必轻吾国，汝杀公马，使怨积于百姓，兵弱于邻国，汝当死罪三也。今以属狱。”
公喟然叹曰：“夫子释之！夫子释之！勿伤吾仁也。”', '', '', '', NULL, '', 'indent', 1545260232, '5c1a5ba59f54540474a31379', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640751, '晏子春秋 · 内篇 · 谏下第二', NULL, 2, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', '', '', '景公藉重而狱多欲托晏子晏子谏第一
景公藉重而狱多，拘者满圄，怨者满朝。晏子谏，公不听。公谓晏子曰：“夫狱，国之重官也，愿托之夫子。”
晏子对曰：“君将使婴饬其功乎？则婴有壹妄能书，足以治之矣。君将使婴饬其意乎？夫民无欲残其家室之生，以奉暴上之僻者，则君使吏比而焚之而已矣。”景公不说，曰：“饬其功则使壹妄，饬其意则比焚，如是，夫子无所谓能治国乎？”
晏子曰：“婴闻与君异。今夫胡貉戎狄之蓄狗也，多者十有余，寡者五六，然不相害伤。今束鸡豚妄投之，其折骨决皮，可立得也。且夫上正其治，下审其论，则贵贱不相逾越。今君举千钟爵禄，而妄投之于左右，左右争之，甚于胡狗，而公不知也。寸之管无当，天下不能足之以粟。今齐国丈夫耕，女子织，夜以接日，不足以奉上，而君侧皆雕文刻镂之观。此无当之管也，而君终不知。五尺童子，操寸之烟，天下不能足以薪。今君之左右，皆操烟之徒，而君终不知。钟鼓成肆，干戚成舞，虽禹不能禁民之观。且夫饰民之欲，而严其听，禁其心，圣人所难也，而况夺其财而饥之，劳其力而疲之，常致其苦而严听其狱，痛诛其罪，非婴所知也。”
景公欲杀犯所爱之槐者晏子谏第二
景公有所爱槐，令吏谨守之，植木县之，下令曰：“犯槐者刑，伤之者死。”有不闻令，醉而犯之者，公闻之曰：“是先犯我令。”使吏拘之，且加罪焉。其女子往辞晏子之家，托曰：“负廓之民贱妾，请有道于相国，不胜其欲，愿得充数乎下陈。”晏子闻之，笑曰：“婴其淫于色乎？何为老而见奔？虽然，是必有故。”令内之。女子入门，晏子望见之，曰：“怪哉！有深忧。”进而问焉，曰：“所忧何也？”对曰：“君树槐县令，犯之者刑，伤之者死。妾父不仁，不闻令，醉而犯之，吏将加罪焉。妾闻之，明君莅国立政，不损禄，不益刑，又不以私恚害公法，不为禽兽伤人民，不为草木伤禽兽，不为野草伤禾苗。吾君欲以树木之故，杀妾父，孤妾身，此令行于民而法于国矣。虽然，妾闻之，勇士不以众彊凌孤独，明惠之君不拂是以行其所欲，此譬之犹自治鱼鳖者也，去其腥臊者而已。昧墨与人比居庾肆，而教人危坐。今君出令于民，苟可法于国，而善益于后世，则父死亦当矣，妾为之收亦宜矣。甚乎！今之令不然，以树木之故，罪法妾父，妾恐其伤察吏之法，而害明君之义也。邻国闻之，皆谓吾君爱树而贱人，其可乎？愿相国察妾言以裁犯禁者。”
晏子曰：“甚矣！吾将为子言之于君。”使人送之归。明日，早朝，而复于公曰：“婴闻之，穷民财力以供嗜欲谓之暴，崇玩好，威严拟乎君谓之逆，刑杀不辜谓之贼。此三者，守国之大殃。今君穷民财力，以羡馁食之具，繁钟鼓之乐，极宫室之观，行暴之大者；崇玩好，县爱槐之令，载过者驰，步过者趋，威严拟乎君，逆之明者也；犯槐者刑，伤槐者死，刑杀不称，贼民之深者。君享国，德行未见于众，而三辟着于国，婴恐其不可以莅国子民也。”
公曰：“微大夫教寡人，几有大罪以累社稷，今子大夫教之，社稷之福，寡人受命矣。”
晏子出，公令趣罢守槐之役，拔置县之木，废伤槐之法，出犯槐之囚。
景公逐得斩竹者囚之晏子谏第三
景公树竹，令吏谨守之。公出，过之，有斩竹者焉，公以车逐，得而拘之，将加罪焉。晏子入见，曰：“君亦闻吾先君丁公乎？”公曰：“何如？”晏子曰：“丁公伐曲沃，胜之，止其财，出其民。公日自莅之，有舆死人以出者，公怪之，令吏视之，则其中金与玉焉。吏请杀其人，收其金玉。公曰：‘以兵降城，以众图财，不仁。且吾闻之，人君者，宽惠慈众，不身传诛。’令舍之。”公曰：“善！”晏子退，公令出斩竹之囚。
景公以抟治之兵未成功将杀之晏子谏第四
景公令兵抟治，当腊冰月之间而寒，民多冻馁，而功不成。公怒曰：“为我杀兵二人。”晏子曰：“诺。”少间，晏子曰：“昔者先君庄公之伐于晋也，其役杀兵四人，今令而杀兵二人，是师杀之半也。”公曰：“诺！是寡人之过也。”令止之。
景公冬起大台之役晏子谏第五
晏子使于鲁，比其返也，景公使国人起大台之役，岁寒不已，冻馁之者乡有焉，国人望晏子。
晏子至，已复事，公延坐，饮酒乐，晏子曰：“君若赐臣，臣请歌之。”歌曰：“庶民之言曰：‘冻水洗我，若之何！太上靡散我，若之何！’”歌终，喟然叹而流涕。公就止之曰：“夫子曷为至此？殆为大台之役夫！寡人将速罢之。”晏子再拜。出而不言，遂如大台，执朴鞭其不务者，曰：“吾细人也，皆有盖庐，以避燥湿，君为壹台而不速成，何为？”国人皆曰：“晏子助天为虐。”
晏子归，未至，而君出令趣罢役，车驰而人趋。仲尼闻之，喟然叹曰：“古之善为人臣者，声名归之君，祸灾归之身，入则切磋其君之不善，出则高誉其君之德义，是以虽事惰君，能使垂衣裳，朝诸侯，不敢伐其功。当此道者，其晏子是耶！”
景公为长庲欲美之晏子谏第六
景公为长庲，将欲美之，有风雨作，公与晏子入坐饮酒，致堂上之乐。酒酣，晏子作歌曰：“穗乎不得获，秋风至兮殚零落，风雨之拂杀也，太上之靡弊也。”歌终，顾而流涕，张躬而舞。公就晏子而止之曰：“今日夫子为赐而诫于寡人，是寡人之罪。”遂废酒，罢役，不果成长庲。
景公为邹之长涂晏子谏第七
景公筑路寝之台，三年未息；又为长庲之役，二年未息；又为邹之长涂。晏子谏曰：“百姓之力勤矣！公不息乎？”公曰：“涂将成矣，请成而息之。”对曰：“明君不屈民财者，不得其利；不穷民力者，不得其乐。昔者楚灵王作顷宫，三年未息也；又为章华之台，五年又不息也；干溪之役，八年，百姓之力不足而自息也。灵王死于干溪，而民不与君归。今君不遵明君之义，而循灵王之迹，婴惧君有暴民之行，而不睹长庲之乐也，不若息之。”公曰：“善！非夫子者，寡人不知得罪于百姓深也。”于是令勿委坏，余财勿收，斩板而去之。
景公春夏游猎兴役晏子谏第八
景公春夏游猎，又起大台之役。晏子谏曰：“春夏起役，且游猎，夺民农时，国家空虚，不可。”景公曰：“吾闻相贤者国治，臣忠者主逸。吾年无几矣，欲遂吾所乐，卒吾所好，子其息矣。”晏子曰：“昔文王不敢盘于游田，故国昌而民安。楚灵王不废干溪之役，起章华之台，而民叛之。今君不革，将危社稷，而为诸侯笑。臣闻忠臣不避死，谏不违罪。君不听臣，臣将逝矣。”景公曰：“唯唯，将弛罢之。”未几，朝韦囧解役而归。
景公猎休坐地晏子席而谏第九
景公猎休，坐地而食，晏子后至，左右灭葭而席。公不说，曰：“寡人不席而坐地，二三子莫席，而子独搴草而坐之，何也？”晏子对曰：“臣闻介胄坐陈不席，狱讼不席，尸坐堂上不席，三者皆忧也。故不敢以忧侍坐。”公曰：“诺。”令人下席曰：“大夫皆席，寡人亦席矣。”
景公猎逢蛇虎以为不祥晏子谏第十
景公出猎，上山见虎，下泽见蛇。归，召晏子而问之曰：“今日寡人出猎，上山则见虎，下泽则见蛇，殆所谓不祥也？”
晏子对曰：“国有三不祥，是不与焉。夫有贤而不知，一不祥；知而不用，二不祥；用而不任，三不祥也。所谓不祥，乃若此者。今上山见虎，虎之室也；下泽见蛇，蛇之穴也。如虎之室，如蛇之穴，而见之，曷为不祥也！”
景公为台成又欲为钟晏子谏第十一
景公为台，台成，又欲为钟。晏子谏曰：“君国者不乐民之哀。君不胜欲，既筑台矣，今复为钟，是重敛于民，民必哀矣。夫敛民之哀，而以为乐，不祥，非所以君国者。”公乃止。
景公为泰吕成将以燕飨晏子谏第十二
景公为泰吕成，谓晏子曰：“吾欲与夫子燕。”对曰：“未祀先君而以燕，非礼也。”公曰：“何以礼为？”对曰：“夫礼者，民之纪，纪乱则民失，乱纪失民，危道也。”公曰：“善。”乃以祀焉。
景公为履而饰以金玉晏子谏第十三
景公为履，黄金之綦，饰以银，连以珠，良玉之絇，其长尺，冰月服之，以听朝。
晏子朝，公迎之，履重，仅能举足，问曰：“天寒乎？”
晏子曰：“君奚问天之寒也？古圣人制衣服也，冬轻而暖，夏轻而凊，今君之履，冰月服之，是重寒也，履重不节，是过任也，失生之情矣。故鲁工不知寒温之节，轻重之量，以害正生，其罪一也；作服不常，以笑诸侯，其罪二也；用财无功，以怨百姓，其罪三也。请拘而使吏度之。”公苦，请释之。
晏子曰：“不可。婴闻之，苦身为善者，其赏厚；苦身为非者，其罪重。”公不对。晏子出，令吏拘鲁工，令人送之境，使不得入。公撤履，不复服也。
景公欲以圣王之居服而致诸侯晏子谏第十四
景公问晏子曰：“吾欲服圣王之服，居圣王之室，如此，则诸侯其至乎？”
晏子对曰：“法其节俭则可，法其服，居其室，无益也。三王不同服而王，非以服致诸侯也，诚于爱民，果于行善，天下怀其德而归其义，若其衣服节俭而众说也。夫冠足以修敬，不务其饰；衣足以掩形御寒，不务其美。衣不务于隅眦之削，冠无觚羸之理，身服不杂彩，首服不镂刻。且古者尝有紩衣挛领而王天下者其义好生而恶杀，节上而羡下，天下不朝其服，而共归其义。古者尝有处橧巢窟穴而不恶，予而不取，天下不朝其室，而共归其仁。及三代作服，为益敬也，首服足以修敬，而不重也，身服足以行洁，而不害于动作。服之轻重便于身，用财之费顺于民。其不为橧巢者，以避风也；其不为窟穴者，以避湿也。是故明堂之制，下之润湿，不能及也；上之寒暑，不能入也。土事不文，木事不镂，示民知节也。及其衰也，衣服之侈过足以敬，宫室之美过避润湿，用力甚多，用财甚费，与民为雠。今君欲法圣王之服，不法其制，法其节俭也，则虽未成治，庶其有益也。今君穷台榭之高，极污池之深而不止，务于刻镂之巧，文章之观而不厌，则亦与民而雠矣。若臣之虑，恐国之危，而公不平也。公乃愿致诸侯，不亦难乎！公之言过矣。”
景公自矜冠裳游处之贵晏子谏第十五
景公为西曲潢，其深灭轨，高三仞，横木龙蛇，立木鸟兽。公衣黼黻之衣，素绣之裳，一衣而五彩具焉；带球玉而冠且，被发乱首，南面而立，傲然。晏子见，公曰：“昔仲父之霸何如？”晏子抑首而不对。公又曰：“昔管文仲之霸何如？”晏子对曰：“臣闻之，维翟人与龙蛇比，今君横木龙蛇，立木鸟兽，亦室一就矣，何暇在霸哉！且公伐宫室之美，矜衣服之丽，一衣而五彩具焉，带球玉而乱首被发，亦室一容矣，万乘之君，而壹心于邪，君之魂魄亡矣，以谁与图霸哉？”公下堂就晏子曰：“梁丘据、裔款以室之成告寡人，是以窃袭此服，与据为笑，又使夫子及，寡人请改室易服而敬听命，其可乎？”晏子曰：“夫二子营君以邪，公安得知道哉！且伐木不自其根，则蘗又生也，公何不去二子者，毋使耳目淫焉。”
景公为巨冠长衣以听朝晏子谏第十六
景公为巨冠长衣以听朝，疾视矜立，日晏不罢。晏子进曰：“圣人之服中，侻而不驵，可以导众，其动作，侻顺而不逆，可以奉生，是以下皆法其服，而民争学其容。今君之服，驵华不可以导众民，疾视矜立，不可以奉生，日晏矣，君不若脱服就燕。”公曰：“寡人受命。”退朝，遂去衣冠、不复服。
景公朝居严下不言晏子谏第十七
晏子朝，复于景公曰：“朝居严乎？”
公曰：“严居朝，则曷害于治国家哉？”
晏子对曰：“朝居严则下无言，下无言则上无闻矣。下无言则吾谓之喑，上无闻则吾谓之聋。聋喑，非害国家而如何也！且合升斗之微以满仓廪，合疏缕之绨以成帏幕，大山之高，非一石也，累卑然后高，天下者，非用一士之言也，固有受而不用，恶有拒而不受者哉！”
景公登路寝台不终不悦晏子谏第十八
景公登路寝之台，不能终，而息乎陛，忿然而作色，不说，曰：“孰为高台，病人之甚也？”
晏子曰：“君欲节于身而勿高，使人高之而勿罪也。今高，从之以罪，卑亦从以罪，敢问使人如此可乎？古者之为宫室也，足以便生，不以为奢侈也，故节于身，谓于民。及夏之衰也，其王桀背弃德行，为璇室玉门。殷之衰也，其王纣作为顷宫灵台，卑狭者有罪，高大者有赏，是以身及焉。今君高亦有罪，卑亦有罪，甚于夏殷之王；民力殚乏矣，而不免于罪，婴恐国之流失，而公不得享也！”
公曰：“善！寡人自知诚费财劳民，以为无功，又从而怨之，是寡人之罪也！非夫子之教，岂得守社稷哉！”遂下，再拜，不果登台。
景公登路寝台望国而叹晏子谏第十九
景公与晏子登寝而望国，公愀然而叹曰：“使后嗣世世有此，岂不可哉！”晏子曰：“臣闻明君必务正其治，以事利民，然后子孙享之。诗云：‘武王岂不事，贻厥孙谋，以燕翼子。’今君处佚怠，逆政害民有日矣，而犹出若言，不亦甚乎！”公曰：“然则后世孰将把齐国？”对曰：“服牛死，夫妇哭，非骨肉之亲也，为其利之大也。欲知把齐国者，则其利之者邪？”公曰：“然，何以易？”对曰：“移之以善政。今公之牛马老于栏牢，不胜服也；车蠹于巨户，不胜乘也；衣裘襦裤，朽弊于藏，不胜衣也；醯醢腐，不胜，沽也；酒醴酸不胜饮也；府粟郁而不胜食；又厚藉敛于百姓，而不以分馁民。夫藏财而不用，凶也，财苟失守，下其报环至。其次昧财之失守，委而不以分人者，百姓必进自分也。故君人者与其请于人，不如请于己也。”
景公路寝台成逢于何愿合葬晏子谏而许第二十
景公成路寝之台，逢于何遭丧，遇晏子于途，再拜乎马前。晏子下车挹之，曰：“子何以命婴也？”对曰：“于何之母死，兆在路寝之台牖下，愿请命合骨。”
晏子曰：“嘻！难哉！虽然，婴将为子复之，适为不得，子将若何？”对曰：“夫君子则有以，如我者侪小人，吾将左手拥格，右手梱心，立饿枯槁而死，以告四方之士曰：‘于何不能葬其母者也。’”
晏子曰：“诺。”遂入见公，曰：“有逢于何者，母死，兆在路寝，当如之何？愿请合骨。”公作色不说，曰：“古之及今，子亦尝闻请葬人主之宫者乎？”
晏子对曰：“古之人君，其宫室节，不侵生民之居，台榭俭，不残死人之墓，故未尝闻诸请葬人主之宫者也。今君侈为宫室，夺人之居，广为台榭，残人之墓，是生者愁忧，不得安处，死者离易，不得合骨。丰乐侈游，兼傲生死，非人君之行也。遂欲满求，不顾细民，非存之道。且婴闻之，生者不得安，命之曰蓄忧；死者不得葬，命之曰蓄哀。蓄忧者怨，蓄哀者危，君不如许之。”公曰：“诺。”
晏子出，梁丘据曰：“自昔及今，未尝闻求葬公宫者也，若何许之？”公曰：“削人之居，残人之墓，凌人之丧，而禁其葬，是于生者无施，于死者无礼。诗云：‘谷则异室，死则同穴。’吾敢不许乎？”逢于何遂葬其母路寝之牖下，解衰去绖，布衣縢履，元冠茈武，踊而不哭。躄而不拜，已乃涕洟而去。
景公嬖妾死守之三日不敛晏子谏第二十一
景公之嬖妾婴子死，公守之，三日不食，肤着于席不去。左右以复，而君无听焉。
晏子入，复曰：“有术客与医俱言曰：‘闻婴子病死，愿请治之。’”公喜，遽起，曰：“病犹可为乎？”
晏子曰：“客之道也，以为良医也，请尝试之。君请屏，洁沐浴饮食，间病者之宫，彼亦将有鬼神之事焉。”公曰：“诺。”屏而沐浴。晏子令棺人入敛，已敛，而复曰：“医不能治病，已敛矣，不敢不以闻。”公作色不说，曰：“夫子以医命寡人，而不使视，将敛而不以闻，吾之为君，名而已矣。”
晏子曰：“君独不知死者之不可以生邪？婴闻之，君正臣从谓之顺，君僻臣从谓之逆。今君不道顺而行僻，从邪者迩，导害者远，谗谀萌通，而贤良废灭，是以谄谀繁于间，邪行交于国也。昔吾先君桓公用管仲而霸，嬖乎竖刁而灭，今君薄于贤人之礼，而厚嬖妾之哀。且古圣王畜私不伤行，敛死不失爱，送死不失哀。行伤则溺己，爱失则伤生，哀失则害性。是故圣王节之也。即毕敛，不留生事，棺椁衣衾，不以害生养，哭泣处哀，不以害生道。今朽尸以留生，广爱以伤行，修哀以害性，君之失矣。故诸侯之宾客惭入吾国，本朝之臣惭守其职，崇君之行，不可以导民，从君之欲，不可以持国。且婴闻之，朽而不敛，谓之僇尸，臭而不收，谓之陈胔。反明王之性，行百姓之诽，而内嬖妾于僇胔，此之为不可。”
公曰：“寡人不识，请因夫子而为之。”
晏子复曰：“国之士大夫，诸侯四邻宾客，皆在外，君其哭而节之。”
仲尼闻之曰：“星之昭昭，不若月之曀曀，小事之成，不若大事之废，君子之非，贤于小人之是也。其晏子之谓欤！”
景公欲厚葬梁丘据晏子谏第二十二
梁丘据死，景公召晏子而告之，曰：“据忠且爱我，我欲丰厚其葬，高大其垄。”晏子曰：“敢问据之忠与爱于君者，可得闻乎？”公曰：“吾有喜于玩好，有司未能我具也，则据以其所有共我，是以知其忠也；每有风雨，暮夜求必存，吾是以知其爱也。”
晏子曰：“婴对，则为罪，不对，则无以事君，敢不对乎！婴闻之，臣专其君，谓之不忠；子专其父，谓之不孝；妻专其夫，谓之嫉。事君之道，导亲于父兄，有礼于群臣，有惠于百姓，有信于诸侯，谓之忠；为子之道，以钟爱其兄弟，施行于诸父，慈惠于众子，诚信于朋友，谓之孝；为妻之道，使其众妾皆得欢欣于其夫，谓之不嫉。今四封之民，皆君之臣也，而维据尽力以爱君，何爱者之少邪？四封之货，皆君之有也，而维据也以其私财忠于君，何忠者之寡邪？据之防塞群臣，拥蔽君，无乃甚乎？”公曰：“善哉！微子，寡人不知据之至于是也。”遂罢为垄之役，废厚葬之命，令有司据法而责，群臣陈过而谏。故官无废法，臣无隐忠，而百姓大说。
景公欲以人礼葬走狗晏子谏第二十三
景公走狗死，公令外共之棺，内给之祭。晏子闻之，谏。
公曰：“亦细物也，特以与左右为笑耳。”
晏子曰：“君过矣！夫厚藉敛不以反民，弃货财而笑左右，傲细民之忧，而崇左右之笑，则国亦无望已。且夫孤老冻馁，而死狗有祭，鳏寡不恤，死狗有棺，行辟若此，百姓闻之，必怨吾君，诸侯闻之，必轻吾国。怨聚于百姓，而权轻于诸侯，而乃以为细物，君其图之。”公曰：“善。”趣庖治狗，以会朝属。
景公养勇士三人无君之义晏子谏第二十四
公孙接、田开疆、古冶子事景公，以勇力搏虎闻。晏子过而趋，三子者不起。
晏子入见公曰：“臣闻明君之蓄勇力之士也，上有君臣之义，下有长率之伦，内可以禁暴，外可以威敌，上利其功，下服其勇，故尊其位，重其禄。今君之蓄勇力之士也，上无君臣之义，下无长率之伦，内不以禁暴，外不可威敌，此危国之器也，不若去之。”
公曰：“三子者，搏之恐不得，刺之恐不中也。”
晏子曰：“此皆力攻勍敌之人也，无长幼之礼。”因请公使人少馈之二桃，曰：“三子何不计功而食桃？”
公孙接仰天而叹曰：“晏子，智人也！夫使公之计吾功者，不受桃，是无勇也，士众而桃寡，何不计功而食桃矣。接一搏猏而再搏乳虎，若接之功，可以食桃而无与人同矣。”援桃而起。
田开疆曰：“吾仗兵而却三军者再，若开疆之功，亦可以食桃，而无与人同矣。”援桃而起。
古冶子曰：“吾尝从君济于河，鼋衔左骖以入砥柱之流。当是时也，冶少不能游，潜行逆流百步，顺流九里，得鼋而杀之，左操骖尾，右挈鼋头，鹤跃而出。津人皆曰：‘河伯也！’若冶视之，则大鼋之首。若冶之功，亦可以食桃而无与人同矣。二子何不反桃！”抽剑而起。
公孙接、田开疆曰：“吾勇不子若，功不子逮，取桃不让，是贪也；然而不死，无勇也。”皆反其桃，挈领而死。
古冶子曰：“二子死之，冶独生之，不仁；耻人以言，而夸其声，不义；恨乎所行，不死，无勇。虽然，二子同桃而节，冶专其桃而宜。”亦反其桃，挈领而死。
使者复曰：“已死矣。”公殓之以服，葬之以士礼焉。
景公登射思得勇力士与之图国晏子谏第二十五
景公登射，晏子修礼而侍。公曰：“选射之礼，寡人厌之矣！吾欲得天下勇士，与之图国。”
晏子对曰：“君子无礼，是庶人也；庶人无礼，是禽兽也。夫勇多则弑其君，力多则杀其长，然而不敢者，维礼之谓也。礼者，所以御民也，辔者，所以御马也，无礼而能治国家者，晏未之闻也。”
景公曰：“善。”乃饰射更席，以为上客，终日问礼。', '', '', '', NULL, '', 'indent', 1545260218, '5c1a5c59fb4ffe0069e88feb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640752, '晏子春秋 · 内篇 · 问上第三', NULL, 0, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', '', '', '庄公问威当世服天下时耶晏子对以行也第一
庄公问晏子曰：“威当世而服天下，时耶？”
晏子对曰：“行也。”
公曰：“何行？”对曰：“能爱邦内之民者，能服境外之不善；重士民之死力者，能禁暴国之邪逆；听赁贤者，能威诸侯；安仁义而乐利世者，能服天下。不能爱邦内之民者，不能服境外之不善；轻士民之死力者，不能禁暴国之邪逆；愎谏傲贤者之言，不能威诸侯；倍仁义而贪名实者，不能威当世。而服天下者，此其道也已。”
而公不用，晏子退而穷处。公任勇力之士，而轻臣仆之死，用兵无休，国罢民害，期年，百姓大乱，而身及崔氏祸。君子曰：“尽忠不豫交，不用不怀禄，其晏子可谓廉矣！”
庄公问伐晋晏子对以不可若不济国之福第二
庄公将伐晋，问于晏子，晏子对曰：“不可。君得合而欲多，养欲而意骄。得合而欲多者危，养欲而意骄者困。今君任勇力之士，以伐明主，若不济，国之福也，不德而有功，忧必及君。”公作色不说。晏子辞不为臣，退而穷处，堂下生蓼藿，门外生荆棘。庄公终任勇力之士，西伐晋，取朝歌，及太行、孟门，兹于兑，期而民散，身灭于崔氏。崔氏之期，逐群公子，及庆氏亡。
景公问伐鲁晏子对以不若修政待其乱第三
公举兵欲伐鲁，问于晏子，晏子对曰：“不可。鲁好义而民戴之，好义者安，见戴者和，伯禽之治存焉，故不可攻。攻义者不祥，危安者必困。且婴闻之，伐人者德足以安其国，政足以和其民，国安民和，然后可以举兵而征暴。今君好酒而辟，德无以安国，厚藉敛，意使令，无以和民。德无以安之则危，政无以和之则乱。未免乎危乱之理，而欲伐安和之国，不可，不若修政而待其君之乱也。其君离，上怨其下，然后伐之，则义厚而利多，义厚则敌寡，利多则民欢。”
公曰：“善。”遂不果伐鲁。
景公伐斄胜之问所当赏晏子对以谋胜禄臣第四
公伐斄，胜之，问晏子曰：“吾欲赏于斄何如？”对曰：“臣闻之，以谋胜国者，益臣之禄；以民力胜国者，益民之利。故上有羡获，下有加利，君上享其名，臣下利其实。故用智者不偷业，用力者不伤苦，此古之善伐者也。”公曰：“善。”于是破斄之臣，东邑之卒，皆有加利。是上独擅名，利下流也。
景公问圣王其行若何晏子对以衰世而讽第五
公外傲诸侯，内轻百姓，好勇力，崇乐以从嗜欲，诸侯不说，百姓不亲。公患之，问于晏子曰：“古之圣王，其行若何？”
晏子对曰：“其行公正而无邪，故谗人不得入；不阿党，不私色，故群徒之卒不得容；薄身厚民，故聚敛之人不得行；不侵大国之地，不秏小国之民，故诸侯皆欲其尊；不劫人以甲兵，不威人以众彊，故天下皆欲其彊；德行教训加于诸侯，慈爱利泽加于百姓，故海内归之若流水。今衰世君人者，辟邪阿党，故谗谄群徒之卒繁；厚身养，薄视民，故聚敛之人行；侵大国之地，秏小国之民，故诸侯不欲其尊；劫人以兵甲，威人以众彊，故天下不欲其彊；灾害加于诸侯，劳苦施于百姓，故雠敌进伐，天下不救，贵戚离散，百姓不兴。”
公曰：“然则何若？”
对曰：“请卑辞重币，以说于诸侯，轻罪省功，以谢于百姓，其可乎？”
公曰：“诺。”
于是卑辞重币，而诸侯附，轻罪省功，而百姓亲，故小国入朝，燕鲁共贡。墨子闻之曰：“晏子知道，道在人为，而失为己。为人者重，自为者轻。景公自为，而小国不与，为人，而诸侯为役，则道在为人，而行在反己矣，故晏子知道矣。”
景公问欲善齐国之政以干霸王晏子对以官未具第六
公问晏子曰：“吾欲善治齐国之政，以干霸王之诸侯。”
晏子作色对曰：“官未具也。臣数以闻，而君不肯听也。故臣闻仲尼居处惰倦，廉隅不正，则季次、原宪侍；气郁而疾，志意不通，则仲由、卜商侍；德不盛，行不厚，则颜回、骞雍侍。今君之朝臣万人，兵车千乘，不善政之所失于下，霣坠下民者众矣，未有能士敢以闻者。臣故曰：官未具也。”
公曰：“寡人今欲从夫子而善齐国之政，可乎？”
对曰：“婴闻国有具官，然后其政可善。”
公作色不说，曰：“齐国虽小，则何谓官不具？”
对曰：“此非臣之所复也。昔吾先君桓公身体惰懈，辞令不给，则隰朋昵侍；左右多过，狱谳不中，则弦宁昵侍；田野不修，民氓不安，则宁戚昵侍；军吏怠，戎士偷，则王子成甫昵侍；居处佚怠，左右慑畏，繁乎乐，省乎治，则东郭牙昵侍；德义不中，信行衰微，则管子昵侍。先君能以人之长续其短，以人之厚补其薄，是以辞令穷远而不逆，兵加于有罪而不顿，是以诸侯朝其德，而天子致其胙。今君之过失多矣，未有一士以闻也。
故曰：“官不具。”公曰：“善。”
景公问欲如桓公用管仲以成霸业晏子对以不能第七
公问晏子曰：“昔吾先君桓公，有管仲夷吾保乂齐国，能遂武功而立文德，纠合兄弟，抚存翌州，吴越受令，荆楚惛忧，莫不宾服，勤于周室，天子加德。先君昭功，管子之力也。今寡人亦欲存齐国之政于夫子，夫子以佐佑寡人，彰先君之功烈，而继管子之业。”
晏子对曰：“昔吾先君桓公，能任用贤，国有什伍，治遍细民，贵不凌贱，富不傲贫，功不遗罢，佞不吐愚，举事不私，听狱不阿，内妾无羡食，外臣无羡禄，鳏寡无饥色；不以饮食之辟害民之财，不以宫室之侈劳人之力；节取于民，而普施之，府无藏，仓无粟，上无骄行，下无谄德。是以管子能以齐国免于难，而以吾先君参乎天子。今君欲彰先君之功烈，而继管子之业，则无以多辟伤百姓，无以嗜欲玩好怨诸侯，臣孰敢不承善尽力，以顺君意？今君疏远贤人，而任谗谀；使民若不胜，藉敛若不得；厚取于民，而薄其施，多求于诸侯，而轻其礼；府藏朽蠹，而礼悖于诸侯，菽粟藏深，而怨积于百姓；君臣交恶，而政刑无常；臣恐国之危失，而公不得享也。又恶能彰先君之功烈而继管子之业乎！”
景公问莒鲁孰先亡晏子对以鲁后莒先第八
公问晏子：“莒与鲁孰先亡？”
对曰：“以臣观之也，莒之细人，变而不化，贪而好假，高勇而贱仁，士武以疾，忿急以速竭，是以上不能养其下，下不能事其上，上下不能相收，则政之大体失矣。故以臣观之也，莒其先亡。”
公曰：“鲁何如？”
对曰：“鲁之君臣，犹好为义，下之妥妥也，奄然寡闻，是以上能养其下，下能事其上，上下相收，政之大体存矣。故鲁犹可长守，然其亦有一焉。彼邹滕雉奔而出其地，犹称公侯，大之事小，弱之事彊久矣，彼周者，殷之树国也，鲁近齐而亲殷，以变小国，而不服于邻，以远望鲁，灭国之道也。齐其有鲁与莒乎？”
公曰：“鲁与莒之事，寡人既得而闻之矣，寡人之德亦薄，然后世孰践有齐国者？”
对曰：“田无宇之后为几。”
公曰：“何故也？”
对曰：“公量小，私量大，以施于民，其与士交也，用财无筐箧之藏，国人负携其子而归之，若水之流下也。夫先与人利，而后辞其难，不亦寡乎！若苟勿辞也，从而抚之，不亦几乎！”
景公问治国何患晏子对以社鼠猛狗第九
公问于晏子曰：“治国何患？”
晏子对曰：“患夫社鼠。”
公曰：“何谓也？”
对曰：“夫社，束木而涂之，鼠因往托焉，熏之则恐烧其木，灌之则恐败其涂，此鼠所以不可得杀者，以社故也。夫国亦有焉，人主左右是也。内则蔽善恶于君上，外则卖权重于百姓，不诛之则乱，诛之则为人主所案据，腹而有之，此亦国之社鼠也。
人有酤酒者，为器甚洁清，置表甚长，而酒酸不售，问之里人其故，里人云：‘公狗之猛，人挈器而入，且酤公酒，狗迎而噬之，此酒所以酸而不售也。’夫国亦有猛狗，用事者是也。有道术之士，欲干万乘之主，而用事者迎而龁之，此亦国之猛狗也。左右为社鼠，用事者为猛狗，主安得无壅，国安得无患乎？”
景公问欲令祝史求福晏子对以当辞罪而无求第十
公问于晏子曰：“寡人意气衰，身病甚。今吾欲具珪璋牺牲，令祝宗荐之乎上帝宗庙，意者礼可以干福乎？”
晏子对曰：“婴闻之，古者先君之干福也，政必合乎民，行必顺乎神；节宫室，不敢大斩伐，以无逼山林；节饮食，无多畋渔，以无逼川泽；祝宗用事，辞罪而不敢有所求也。是以神民俱顺，而山川纳禄。今君政反乎民，而行悖乎神；大宫室，多斩伐，以逼山林；羡饮食，多畋渔，以逼川泽。是以民神俱怨，而山川收禄，司过荐罪，而祝宗祈福，意者逆乎！”
公曰：“寡人非夫子无所闻此，请革心易行。”于是废公阜之游，止海食之献，斩伐者以时，畋渔者有数，居处饮食，节之勿羡，祝宗用事，辞罪而不敢有所求也。故邻国忌之，百姓亲之，晏子没而后衰。
景公问古之盛君其行如何晏子对以问道者更正第十一
公问晏子曰：“古之盛君，其行何如？”
晏子对曰：“薄于身而厚于民，约于身而广于世：其处上也，足以明政行教，不以威天下；其取财也，权有无，均贫富，不以养嗜欲；诛不避贵，赏不遗贱；不淫于乐，不遁于哀；尽智导民，而不伐焉，劳力岁事，而不责焉；为政尚相利，故下不以相害，行教尚相爱，故民不以相恶为名；刑罚中于法，废罪顺于民。是以贤者处上而不华，不肖者处下而不怨，四海之内，社稷之中，粒食之民，一意同欲。若夫私家之政，生有遗教，此盛君之行也。”公不图。
晏子曰：“臣闻问道者更正，闻道者更容。今君税敛重，故民心离；市买悖，故商旅绝；玩好充，故家货殚。积邪在于上，蓄怨藏于民，嗜欲备于侧，毁非满于国，而公不图。”
公曰：“善。”于是令玩好不御，公市不豫，宫室不饰，业土不成，止役轻税，上下行之，而百姓相亲。
景公问谋必得事必成何术晏子对以度义因民第十二
公问晏子曰：“谋必得，事必成，有术乎？”
晏子对曰：“有。”
公曰：“其术如何？”
晏子曰：“谋度于义者必得，事因于民者必成。”公曰：“奚谓也？”
对曰：“其谋也，左右无所系，上下无所縻，其声不悖，其实不逆，谋于上，不违天，谋于下，不违民，以此谋者必得矣；事大则利厚，事小则利薄，称事之大小，权利之轻重，国有义劳，民有如利，以此举事者必成矣。夫逃人而谟，虽成不安；傲民举事，虽成不荣。故臣闻义谋之法以民事之本也，故及义而谋，信民而动，未闻不存者也。昔三代之兴也，谋必度其义，事必因于民。及其衰也，建谋不及义，兴事伤民。故度义因民，谋事之术也。”
公曰：“寡人不敏，闻善不行，其危如何？”
对曰：“上君全善，其次出入焉，其次结邪而羞问。全善之君能制；出入之君时问，虽日危，尚可以没身；羞问之君，不能保其身。今君虽危，尚可没身也。”
景公问善为国家者何如晏子对以举贤官能第十三
公问晏子曰：“莅国治民，善为国家者何如？”
晏子对曰：“举贤以临国，官能以敕民，则其道也。举贤官能，则民与若矣。”
公曰：“虽有贤能，吾庸知乎？”
晏子对曰：“贤而隐，庸为贤乎，吾君亦不务乎是，故不知也。”
公曰：“请问求贤。”
对曰：“观之以其游，说之以其行，君无以靡曼辩辞定其行，无以毁誉非议定其身，如此，则不为行以扬声，不掩欲以荣君。故通则视其所举，穷则视其所不为，富则视其所不取。夫上士，难进而易退也；其次，易进易退也；其下，易进难退也。以此数物者取人，其可乎！”
景公问君臣身尊而荣难乎晏子对以易第十四
公问晏子曰：“为君，身尊民安，为臣，事治身荣，难乎，易乎？”
晏子对曰：“易。”
公曰：“何若？”
对曰：“为君节养其余以顾民，则君尊而民安；为臣忠信而无逾职业，则事治而身荣。”
公又问：“为君何行则危？为臣何行则废？”
晏子对曰：“为君，厚藉敛而托之为民，进谗谀而托之用贤，远公正而托之不顺，君行此三者则危；为臣，比周以求进，逾职业，防下隐利而求多，从君，不陈过而求亲，人臣行此三者则废。故明君不以邪观民，守则而不亏，立法仪而不犯，苟有所求于民，而不以身害之，是故刑政安于下，民心固于上。故察士不比周而进，不为苟而求，言无阴阳，行无内外，顺则进，否则退，不与上行邪，是以进不失廉，退不失行也。”
景公问天下之所以存亡晏子对以六说第十五
公问晏子曰：“寡人持不仁，其无义耳也。不然，北面与夫子而义。”
晏子对曰：“婴，人臣也，公曷为出若言？”
公曰：“请终问天下之所以存亡。”
晏子曰：“缦密不能，蔍苴学者诎，身无以用人，而又不为人用者卑。善人不能戚，恶人不能疏者危。交游朋友从，无以说于人，又不能说人者穷。事君要利，大者不得，小者不为者喂。修道立义，大不能专，小不能附者灭。此足以观存亡矣。”
景公问君子常行曷若晏子对以三者第十六
公问晏子曰：“君子常行曷若？”
晏子对曰：“衣冠不中，不敢以入朝；所言不义，不敢以要君；行己不顺，治事不公，不敢以莅众。衣冠无不中，故朝无奇僻之服；所言无不义，故下无伪上之报；身行顺，治事公，故国无阿党之义。三者，君子之常行者也。”
景公问贤君治国若何晏子对以任贤爱民第十七
公问晏子曰：“贤君之治国若何？”
晏子对曰：“其政任贤，其行爱民，其取下节，其自养俭；在上不犯下，在治不傲穷；从邪害民者有罪，进善举过者有赏。其政，刻上而饶下，赦过而救穷；不因喜以加赏，不因怒以加罚；不从欲以劳民，不修怒而危国；上无骄行，下无谄德；上无私义，下无窃权；上无朽蠹之藏，下无冻馁之民；不事骄行而尚司，其民安乐而尚亲。贤君之治国若此。”
景公问明王之教民何若晏子对以先行义第十八
公问晏子曰：“明王之教民何若？”
晏子对曰：“明其教令，而先之以行义；养民不苛，而防之以刑辟；所求于下者，不务于上；所禁于民者，不行于身。守于民财，无亏之以利，立于仪法，不犯之以邪，苟所求于民，不以身害之，故下之劝从其教也。称事以任民，中听以禁邪，不穷之以劳，不害之以实，苟所禁于民，不以事逆之，故下不敢犯其上也。古者百里而异习，千里而殊俗，故明王修道，一民同俗，上爱民为法，下相亲为义，是以天下不相遗，此明王教民之理也。”
景公问忠臣之事君何若晏子对以不与君陷于难第十九
公问于晏子曰：“忠臣之事君也，何若？”
晏子对曰：“有难不死，出亡不送。”
公不说，曰：“君裂地而封之，疏爵而贵之，君有难不死，出亡不送，可谓忠乎？”
对曰：“言而见用，终身无难，臣奚死焉；谋而见从，终身不出，臣奚送焉。若言不用，有难而死之，是妄死也；谋而不从，出亡而送之，是诈伪也。故忠臣也者，能纳善于君，不能与君陷于难。”
景公问忠臣之行何如晏子对以不与君行邪第二十
公问晏子曰：“忠臣之行何如？”
对曰：“不掩君过，谏乎前，不华乎外；选贤进能，不私乎内；称身就位，计能定禄；睹贤不居其上，受禄不过其量；不权居以为行，不称位以为忠；不掩贤以隐长，不刻下以谀上；君在不事太子，国危不交诸侯；顺则进，否则退，不与君行邪也。”
景公问佞人之事君何如晏子对以愚君所信也第二十一
公问：“佞人之事君如何？”
晏子对曰：“意难，难不至也。明言行之以饰身，伪言无欲以说人，严其交以见其爱；观上之所欲，而微为之偶，求君逼迩，而阴为之与；内重爵禄，而外轻之以诬行，下事左右，而面示正公以伪廉；求上采听，而幸以求进；傲禄以求多，辞任以求重；工乎取，鄙乎予；欢乎新，慢乎故；吝乎财，薄乎施；睹贫穷若不识，趋利若不及；外交以自扬，背亲以自厚；积丰义之养，而声矜恤之义；非誉乎情，而言不行身，涉时所议，而好论贤不肖；有之己，不难非之人，无之己，不难求之人；其言彊梁而信，其进敏逊而顺；此佞人之行也。明君之所诛，愚君之所信也。”
景公问圣人之不得意何如晏子对以不与世陷乎邪第二十二
公问晏子曰：“圣人之不得意何如？”
晏子对曰：“上作事反天时，从政逆鬼神，藉敛殚百姓；四时易序，神祇并怨；道忠者不听，荐善者不行，谀过者有赉，救失者有罪。故圣人伏匿隐处，不干长上，洁身守道，不与世陷乎邪，是以卑而不失义，瘁而不失廉。此圣人之不得意也。”“圣人之得意何如？”
对曰：“世治政平，举事调乎天，藉敛和乎百姓；乐及其政，远者怀其德；四时不失序，风雨不降虐；天明象而赞，地长育而具物；神降福而不靡，民服教而不伪；治无怨业，居无废民；此圣人之得意也。”
景公问古者君民用国不危弱晏子对以文王第二十三
公问晏子曰：“古者君民而不危，用国而不弱，恶乎失之？”
晏子对曰：“婴闻之，以邪莅国，以暴和民者危；修道以要利，得求而返邪者弱。古者文王修德，不以要利，灭暴不以顺纣，干崇侯之暴，而礼梅伯之醢，是以诸侯明乎其行，百姓通乎其德，故君民而不危，用国而不弱也。”
景公问古之莅国者任人如何晏子对以人不同能第二十四
公问晏子曰：“古之莅国治民者，其任人何如？”
晏子对曰：“地不同生，而任之以一种，责其俱生不可得；人不同能，而任之以一事，不可责遍成。责焉无已，智者有不能给，求焉无餍，天地有不能赡也。故明王之任人，谄谀不迩乎左右，阿党不治乎本朝；任人之长，不彊其短，任人之工，不彊其拙。此任人之大略也。”
景公问古者离散其民如何晏子对以今闻公令如寇雠第二十五
公问晏子曰：“古者离散其民，而陨失其国者，其常行何如？”
晏子对曰：“国贫而好大，智薄而好专；贵贱无亲焉，大臣无礼焉；尚谗谀而贱贤人，乐简慢而玩百姓；国无常法，民无经纪；好辩以为忠，流湎而忘国，好兵而忘民；肃于罪诛，而慢于庆赏；乐人之哀，利人之难；德不足以怀人，政不足以惠民；赏不足以劝善，刑不足以防非：亡国之行也。今民闻公令如寇雠，此古离散其民，陨失其国所常行者也。”
景公问欲和臣亲下晏子对以信顺俭节第二十六
公问晏子曰：“吾欲和民亲下奈何？”
晏子对曰：“君得臣而任使之，与言信，必顺其令，赦其过，任大无多责焉，使迩臣无求嬖焉，无以嗜欲贫其家，无亲谗人伤其心，家不外求而足，事君不因人而进，则臣和矣。俭于藉敛，节于货财，作工不历时，使民不尽力，百官节适，关市省征，山林陂泽，不专其利，领民治民，勿使烦乱，知其贫富，勿使冻馁，则民亲矣。”
公曰：“善！寡人闻命矣。”故令诸子无外亲谒，辟梁丘据无使受报，百官节适，关市省征，陂泽不禁，冤报者过，留狱者请焉。
景公问得贤之道晏子对以举之以语考之以事第二十七
公问晏子曰：“取人得贤之道何如？”
晏子对曰：“举之以语，考之以事，能谕，则尚而亲之，近而勿辱以取人，则得贤之道也。是以明君居上，寡其官而多其行，拙于文而工于事，言不中不言，行不法不为也。”
景公问臣之报君何以晏子对报以德第二十八
公问晏子曰：“臣之报君何以？”
晏子对曰：“臣虽不知，必务报君以德。士逢有道之君，则顺其令；逢无道之君，则争其不义。故君者择臣而使之，臣虽贱，亦得择君而事之。”
景公问临国莅民所患何也晏子对以患者三第二十九
公问晏子曰：“临国莅民，所患何也？”
晏子对曰：“所患者三：忠臣不信，一患也；信臣不忠，二患也；君臣异心，三患也。是以明君居上，无忠而不信，无信而不忠者。是故君臣同欲，而百姓无怨也。”
公问为政何患晏子对以善恶不分第三十
公问于晏子曰：“为政何患？”
晏子对曰：“患善恶之不分。”
公曰：“何以察之？”
对曰：“审择左右。左右善，则百僚各得其所宜，而善恶分。”
孔子闻之曰：“此言也信矣！善进，则不善无由入矣；不善进，则善无由入矣。”', '', '', '', NULL, '', 'indent', 1545260292, '5c1a5cac67f35600660eb992', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640753, '晏子春秋 · 内篇 · 问下第四', NULL, 1, 573, 1, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', '', '', '景公问何修则夫先王之游晏子对以省耕实第一
景公出游，问于晏子曰：“吾欲观于转附、朝舞，遵海而南，至于琅玡，寡人何修，则夫先王之游？”
晏子再拜曰：“善哉！君之问也。闻天子之诸侯为巡狩，诸侯之天子为述职。故春省耕而补不足者谓之游，秋省实而助不给者谓之豫。夏谚曰：‘吾君不游，我曷以休？吾君不豫，我曷以助？一游一豫，为诸侯度。’今君之游不然，师行而粮食，贫苦不补，劳者不息。夫从南历时而不反谓之流，从下而不反谓之连，从兽而不归谓之荒，从乐而不归谓之亡。古者圣王无流连之游，荒亡之行。”
公曰：“善。”命吏计公掌之粟，藉长幼贫氓之数。吏所委发廪出粟，以予贫民者三千钟，公所身见癃老者七十人，振赡之，然后归也。
景公问桓公何以致霸晏子对以下贤以身第二
景公问于晏子曰：“昔吾先君桓公，善饮酒穷乐，食味方丈，好色无别，辟若此，何以能率诸侯以朝天子乎？”
晏子对曰：“昔吾先君桓公，变俗以政，下贤以身。管仲，君之贼者也，知其能足以安国济功，故迎之于鲁郊，自御，礼之于庙。异日，君过于康庄，闻宁戚歌，止车而听之，则贤人之风也，举以为大田。先君见贤不留，使能不怠，是以内政则民怀之，征伐则诸侯畏之。今君闻先君之过，而不能明其大节，桓公之霸也，君奚疑焉？”
景公问欲逮桓公之后晏子对以任非其人第三
景公问晏子曰：“昔吾先君桓公，从车三百乘，九合诸侯，一匡天下。今吾从车千乘，可以逮先君桓公之后乎？”
晏子对曰：“桓公从车三百乘，九合诸侯，一匡天下者，左有鲍叔，右有仲父。今君左为倡，右为优，谗人在前，谀人在后，又焉可逮桓公之后者乎？”
景公问廉政而长久晏子对以其行水也第四
景公问晏子曰：“廉政而长久，其行何也？”
晏子对曰：“其行水也。美哉水乎清清，其浊无不雩途，其清无不洒除，是以长久也。”
公曰：“廉政而遫亡，其行何也？”
对曰：“其行石也。坚哉石乎落落，视之则坚，循之则坚，内外皆坚，无以为久，是以遫亡也。”
景公问为臣之道晏子对以九节第五
景公问晏子曰：“请问为臣之道。”
晏子对曰：“见善必通，不私其利，庆善而不有其名；称身居位，不为苟进；称事授禄，不为苟得；体贵侧贱不逆其伦，君贤不肖，不乱其序；肥利之地，不为私邑，贤质之士，不为私臣；君用其所言，民得其所利，而不伐其功。此臣之道也。”
景公问贤不肖可学乎晏子对以勉彊为上第六
景公问晏子曰：“人性有贤不肖，可学乎？”
晏子对曰：“诗云：‘高山仰止，景行行止。’之者其人也。故诸侯并立，善而不怠者为长；列士并学，终善者为师。”
景公问富民安众晏子对以节欲中听第七
景公问晏子曰：“富民安众难乎？”
晏子对曰：“易。节欲则民富，中听则民安，行此两者而已矣。”
景公问国如何则谓安晏子对以内安政外归义第八
景公问晏子曰：“国如何则可谓安矣？”
晏子对曰：“下无讳言，官无怨治；通人不华，穷民不怨；喜乐无羡赏，忿怒无羡刑；上有礼于士，下有恩于民；地博不兼小，兵彊不劫弱；百姓内安其政，外归其义：可谓安矣。”
景公问诸侯孰危晏子对以莒其先亡第九
景公问晏子曰：“当今之时，诸侯孰危？”
晏子对曰：“莒其先亡乎！”公曰：“何故？”对曰：“地侵于齐，货竭于晋，是以亡也。”
晏子使吴吴王问可处可去晏子对以视国治乱第十
晏子聘于吴，吴王曰：“子大夫以君命辱在敝邑之地，施贶寡人，寡人受贶矣，愿有私问焉。”
晏子巡遁而对曰：“婴，北方之贱臣也，得奉君命，以趋于末朝，恐辞令不审，讥于下吏，惧不知所以对者。”
吴王曰：“寡人闻夫子久矣，今乃得见，愿终其问。”
晏子避席对曰：“敬受命矣。”
吴王曰：“国如何则可处，如何则可去也？”
晏子对曰：“婴闻之，亲疏得处其伦，大臣得尽其忠，民无怨治，国无虐刑，则可处矣。是以君子怀不逆之君，居治国之位。亲疏不得居其伦，大臣不得尽其忠，民多怨治，国有虐刑，则可去矣。是以君子不怀暴君之禄，不处乱国之位。”
吴王问保威彊不失之道晏子对以先民后身第十一
晏子聘于吴，吴王曰：“敢问长保威彊勿失之道若何？”
晏子对曰：“先民而后身，先施而后诛；彊不暴弱，贵不凌贱，富不傲贫；百姓并进，有司不侵，民和政平；不以威彊退人之君，不以众彊兼人之地；其用法，为时禁暴，故世不逆其志；其用兵，为众屏患，故民不疾其劳：此长保威彊勿失之道也。失此者危矣！”吴王忿然作色，不说。
晏子曰：“寡君之事毕矣，婴无斧锧之罪，请辞而行。”遂不复见。
晏子使鲁鲁君问何事回曲之君晏子对以庇族第十二
晏子使鲁，见昭公，昭公说曰：“天下以子大夫语寡人者众矣，今得见而羡乎所闻，请私而无为罪。寡人闻大国之君，盖回曲之君也，曷为以子大夫之行，事回曲之君乎？”
晏子逡循对曰：“婴不肖，婴之族又不若婴，待婴而祀先者五百家，故婴不敢择君。”
晏子出，昭公语人曰：“晏子，仁人也。反亡君，安危国，而不私利焉；僇崔杼之尸，灭贼乱之徒，不获名焉；使齐外无诸侯之忧，内无国家之患，不伐功焉；鍖然不满，退托于族，晏子可谓仁人矣。”
鲁昭公问鲁一国迷何也晏子对以化为一心第十三
晏子聘于鲁，鲁昭公问焉：“吾闻之，莫三人而迷，今吾以鲁一国迷虑之，不免于乱，何也？”
晏子对曰：“君之所尊举而富贵，入所以与图身，出所与图国，及左右逼迩，皆同于君之心者也。犒鲁国化而为一心，曾无与二，其何暇有三？夫逼迩于君之侧者，距本朝之势，国之所以治也；左右谗谀，相与塞善，行之所以衰也；士者持禄，游者养交，身之所以危也。诗曰：‘芃芃棫朴，薪之槱之，济济辟王，左右趋之。’此言古者圣王明君之使以善也。故外知事之情，而内得心之诚，是以不迷也。”
鲁昭公问安国众民晏子对以事大养小谨听节俭第十四
晏子聘于鲁，鲁昭公问曰：“夫俨然辱临敝邑，窃甚嘉之，寡人受贶，请问安国众民如何？”
晏子对曰：“婴闻傲大贱小则国危，慢听厚敛则民散。事大养小，安国之器也；谨听节俭，众民之术也。”
晏子使晋晋平公问先君得众若何晏子对以如美渊泽第十五
晏子使晋，晋平公飨之文室，既静矣，晏以，平公问焉，曰：“昔吾先君得众若何？”
晏子对曰：“君飨寡君，施及使臣，御在君侧，恐惧不知所以对。”
平公曰：“闻子大夫数矣，今乃得见，愿终闻之。”
晏子对曰：“臣闻君子如美，渊泽容之，众人归之，如鱼有依，极其游泳之乐；若渊泽决竭，其鱼动流，夫往者维雨乎，不可复已。”
公又问曰：“请问庄公与今孰贤？”
晏子曰：“两君之行不同，臣不敢不知也。
公曰：“王室之正也，诸侯之专制也，是以欲闻子大夫之言也。”
对曰：“先君庄公不安静处，乐节饮食，不好钟鼓，好兵作武，士与同饥渴寒暑，君之彊，过人之量，有一过不能已焉，是以不免于难。今君大宫室，美台榭，以辟饥渴寒暑，畏祸敬鬼神，君之善，足以没身，不足以及子孙矣。”
晋平公问齐君德行高下晏子对以小善第十六
晏子使于晋，晋平公问曰：“吾子之君，德行高下如何？”
晏子对以“小善”。
公曰：“否，吾非问小善，问子之君德行高下也。”
晏子蹙然曰：“诸侯之交，绍而相见，辞之有所隐也。君之命质，臣无所隐，婴之君无称焉。”
平公蹙然而辞送，再拜而反曰：“殆哉吾过！谁曰齐君不肖！直称之士，正在本朝也。”
晋叔向问齐国若何晏子对以齐德衰民归田氏第十七
晏子聘于晋，叔向从之宴，相与语。叔向曰：“齐其何如？”晏子对曰：“此季世也，吾弗知，齐其为田氏乎！”叔向曰：“何谓也？”
晏子曰：“公弃其民，而归于田氏。齐旧四量：豆、区、釜、钟，四升为豆，各自其四，以登于釜，釜十则钟。田氏三量，皆登一焉，钟乃巨矣。以家量贷，以公量收之。山木如市，弗加于山，鱼盐蜃蛤，弗加于海。民参其力，二入于公，而衣食其一；公积朽蠹，而老少冻馁；国都之市，屦贱而踊贵；民人痛疾，或燠休之。昔者殷人诛杀不当，僇民无时，文王慈惠殷众，收恤无主，是故天下归之，无私与，维德之授。今公室骄暴，而田氏慈惠，其爱之如父母，而归之如流水，无获民，将焉避？箕伯、直柄、虞遂、伯戏，其相胡公大姬，已在齐矣。”
叔向曰：“虽吾公室，亦季世也。戎马不驾，卿无军行，公乘无人，卒列无长；庶民罢獘，宫室滋侈，道殣相望，而女富溢尤；民闻公命，如逃寇雠；栾却、胥原、孤续、庆伯，降在皂隶；政在家门，民无所依，而君日不悛，以乐慆忧；公室之卑，其何日之有！谗鼎之铭曰：‘昧旦丕显，后世犹怠’，况日不悛，其能久乎！”
晏子曰：“然则子将若何？”
叔向曰：“人事毕矣，待天而已矣！晋之公族尽矣。肸闻之，公室将卑，其宗族枝叶先落，则公从之。肸之宗十一族，维羊舌氏在而已，肸又无子，公室无度，幸而得死，岂其获祀焉。”
叔向问齐德衰子若何晏子对以进不失忠退不失行第十八
叔向问晏子曰：“齐国之德衰矣，今子何若？”
晏子对曰：“婴闻事明君者，竭心力以没其身，行不逮则退，不以诬持禄；事惰君者，优游其身以没其世，力不能则去，不以谀持危。且婴闻君子之事君也，进不失忠，退不失行。不苟合以隐忠，可谓不失忠；不持利以伤廉，可谓不失行。”
叔向曰：“善哉！诗有之曰：‘进退维谷。’其此之谓欤！”
叔向问正士邪人之行如何晏子对以使下顺逆第十九
叔向问晏子曰：“正士之义，邪人之行，何如？”
晏子对曰：“正士处势临众不阿私，行于国足养而不忘故；通则事上，使恤其下，穷则教下，使顺其上；事君尽礼行忠，不正爵禄，不用则去而不议。其交友也，论身义行，不为苟戚，不同则疏而不悱；不毁进于君，不以刻民尊于国。故用于上则民安，行于下则君尊；故得众上不疑其身，用于君不悖于行。是以进不丧亡，退不危身，此正士之行也。
邪人则不然，用于上则虐民，行于下则逆上；事君苟进不道忠，交友苟合不道行；持谀巧以正禄，比奸邪以厚养；矜爵禄以临人，夸礼貌以华世；不任上则轻议，不笃于友则好诽。故用于上则民忧，行于下则君危，是以其事君近于罪，其交友近于患，其得上辟于辱，其为生偾于刑，故用于上则诛，行于下则弑。是故交通则辱，生患则危，此邪人之行也。”
叔向问事君徒处之义奚如晏子对以大贤无择第二十
叔向问晏子曰：“事君之伦，徒处之义奚如？”
晏子对曰：“事君之伦，知虑足以安国，誉厚足以导民，和柔足以怀众，不廉上以为名，不倍民以为行，上也；洁于治己，不饰过以求先，不谗谀以求进，不阿以私，不诬所能，次也；尽力守职不怠，奉官从上不敢隋，畏上故不苟，忌罪故不辟，下也。三者，事君之伦也。及夫大贤，则徒处与有事无择也，随时宜者也。有所谓君子者，能不足以补上，退处不顺上，治唐园，考菲履，共恤上令，弟长乡里，不夸言，不愧行，君子也。不以上为本，不以民为忧，内不恤其家，外不顾其身游，夸言愧行，自勤于饥寒，不及丑侪，命之曰狂僻之民，明上之所禁也。进也不能及上，退也不能徒处，作穷于富利之门，毕志于畎亩之业，穷通行无常处之虑，佚于心，利通不能，穷业不成，命之曰处封之民，明上之所诛也。有智不足以补君，有能不足以劳民，俞身徒处，谓之傲上，苟进不择所道，苟得不知所恶，谓之乱贼。身无以与君，能无以劳民，饰徒处之义，扬轻上之名，谓之乱国。明君在上，三者不免罪。”
叔向曰：“贤不肖，性夫！吾每有问，而未尝自得也。”
叔向问处乱世其行正曲晏子对以民为本第二十一
叔向问晏子曰：“世乱不遵道，上辟不用义；正行则民遗，曲行则道废。正行而遗民乎？与持民而遗道乎？此二者之于行，何如？”
晏子对曰：“婴闻之，卑而不失尊，曲而不失正者，以民为本也。苟持民矣，安有遗道！苟遗民矣，安有正行焉！”
叔向问意孰为高行孰为厚晏子对以爱民乐民第二十二
叔向问晏子曰：“意孰为高？行孰为厚？”
对曰：“意莫高于爱民，行莫厚于乐民。”
又问曰：“意孰为下？行孰为贱？”
对曰：“意莫下于刻民，行莫贱于害身也。”
叔向问啬吝爱之于行何如晏子对以啬者君子之道第二十三
叔向问晏子曰：“啬吝爱之于行何如？”
晏子对曰：“啬者，君子之道；吝爱者，小人之行也。”
叔向曰：“何谓也？”
晏子曰：“称财多寡而节用之，富无金藏，贫不假贷，谓之啬；积多不能分人，而厚自养，谓之吝；不能分人，又不能自养，谓之爱。故夫啬者，君子之道；吝爱者，小人之行也。”
叔向问君子之大义何若晏子对以尊贤退不肖第二十四
叔向问晏子曰：“君子之大义何若？”
晏子对曰：“君子之大义，和调而不缘，溪盎而不苛，庄敬而不狡，和柔而不铨，刻廉而不刿，行精而不以明污，齐尚而不以遗罢，富贵不傲物，贫穷不易行，尊贤而不退不肖。此君子之大义也。”
叔向问傲世乐业能行道乎晏子对以狂惑也第二十五
叔向问晏子曰：“进不能事上，退不能为家，傲世乐业，枯槁为名，不疑其所守者，可谓能行其道乎？”
晏子对曰：“婴闻古之能行道者，世可以正则正，不可以正则曲。其正也，不失上下之伦；其曲也，不失仁义之理。道用，与世乐业；不用，有所依归。不以傲上华世，不以枯槁为名。故道者，世之所以治，而身之所以安也。今以不事上为道，以不顾家为行，以枯槁为名，世行之则乱，身行之则危。且天之与地，而上下有衰矣；明王始立，而居国为制矣；政教错，而民行有伦矣。今以不事上为道，反天地之衰矣；以不顾家为行，倍先圣之道矣；以枯槁为名，则世塞政教之途矣。有明上，可以为下；遭乱世，不可以治乱。说若道，谓之惑，行若道，谓之狂。惑者狂者，木石之朴也，而道义未戴焉。”
叔向问人何若则荣晏子对以事君亲忠孝第二十六
叔向问晏子曰：“何若则可谓荣矣？”
晏子对曰：“事亲孝，无悔往行，事君忠，无悔往辞；和于兄弟，信于朋友，不谄过，不责得；言不相坐，行不相反；在上治民，足以尊君，在下莅修，足以变人，身无所咎，行无所创，可谓荣矣。”
叔向问人何以则可保身晏子对以不要幸第二十七
叔向问晏子曰：“人何以则可谓保其身？”
晏子对曰：“诗曰：‘既明且哲，以保其身，夙夜匪懈，以事一人。’不庶几，不要幸，先其难乎而后幸，得之时其所也，失之非其罪也，可谓保其身矣。”
曾子问不谏上不顾民以成行义者晏子对以何以成也第二十八
曾子问晏子曰：“古者尝有上不谏上，下不顾民，退处山谷，以成行义者也？”晏子对曰：“察其身无能也，而托乎不欲谏上，谓之诞意也。上惛乱，德义不行，而邪辟朋党，贤人不用，士亦不易其行，而从邪以求进，故有隐有不隐。其行法，士也，乃夫议上，则不取也。夫上不谏上，下不顾民，退处山谷，婴不识其何以为成行义者也。”
梁丘据问子事三君不同心晏子对以一心可以事百君第二十九
梁丘据问晏子曰：“子事三君，君不同心，而子俱顺焉，仁人固多心乎？”
晏子对曰：“晏闻之，顺爱不懈，可以使百姓，彊暴不忠，不可以使一人。”心可以事百君，三心不可以事一君。”
仲尼闻之曰：“小子识之！晏子以一心事百君者也。”
柏常骞问道无灭身无废晏子对以养世君子第三十
柏常骞去周之齐，见晏子曰：“骞，周室之贱史也，不量其不肖，愿事君子。敢问正道直行则不容于世，隐道危行则不忍，道亦无灭，身亦无废者何若？”
晏子对曰：“善哉！问事君乎。婴闻之，执二法裾，则不取也；轻进苟合，则不信也；直易无讳，则速伤也；新始好利，则无敝也。且婴闻养世之君子，从重不为进，从轻不为退，省行而不伐，让利而不夸，陈物而勿专，见象而勿彊，道不灭，身不废矣。”', '', '', '', NULL, '', 'indent', 1545260345, '5c1a5ce144d904005fc47fd2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640754, '晏子春秋 · 内篇 · 杂上第五', NULL, 4, 573, 0, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', '', '', '庄公不说晏子晏子坐地讼公而归第一
晏子臣于庄公，公不说，饮酒，令召晏子。晏子至，入门，公令乐人奏歌曰：“已哉已哉！寡人不能说也，尔何来为？”
晏子入坐，乐人三奏，然后知其谓己也。遂起，北面坐地。公曰：“夫子从席，曷为坐地？”
晏子对曰：“婴闻讼夫坐地，今婴将与君讼，敢毋坐地乎？婴闻之，众而无义，彊而无礼，好勇而恶贤者，祸必及其身，若公者之谓矣。且婴言不用，愿请身去。”遂趋而归，管籥其家者纳之公，财在外者斥之市。曰：“君子有力于民，则进爵禄，不辞富贵；无力于民而旅食，不恶贫贱。”
遂徒行而东，耕于海滨。居数年，果有崔杼之难。
庄公不用晏子晏子致邑而退后有崔氏之祸第二
晏子为庄公臣，言大用，每朝，赐爵益邑；俄而不用，每朝，致邑与爵。爵邑尽，退朝而乘，嘳然而叹，终而笑。其仆曰：“何叹笑相从数也？”
晏子曰：“吾叹也，哀吾君不免于难；吾笑也，喜吾自得也，吾亦无死矣。”崔杼果弑庄公，晏子立崔杼之门，从者曰：“死乎？”晏子曰：“独吾君也乎哉！吾死也！”曰：“行乎？”曰：“独吾罪也乎哉！吾亡也！”曰：“归乎？”曰：“吾君死，安归！君民者，岂以陵民，社稷是主；臣君者，岂为其口实，社稷是养。故君为社稷死，则死之，为社稷亡，则亡之；若君为己死而为己亡，非其私昵，孰能任之。且人有君而弑之，吾焉得死之？而焉得亡之？将庸何归！”门启而入，崔子曰：“子何不死？子何不死？”
晏子曰：“祸始，吾不在也；祸终，吾不知也，吾何为死？且吾闻之，以亡为行者，不足以存君；以死为义者，不足以立功。婴岂其婢子也哉！其缢而从之也！”遂袒免，坐，枕君尸而哭，兴，三踊而出。人谓崔子必杀之，崔子曰：“民之望也，舍之，得民。”
崔庆劫齐将军大夫盟晏子不与第三
崔杼既弑庄公而立景公，杼与庆封相之，劫诸将军大夫及显士庶人于太宫之坎上，令无得不盟者。为坛三仞，陷其下，以甲千列环其内外，盟者皆脱剑而入。维晏子不肯，崔杼许之。有敢不盟者，戟拘其颈，剑承其心，令自盟曰：“不与崔庆而与公室者，受其不祥。言不疾，指不至血者死。”所杀七人。次及晏子，晏子奉杯血，仰天叹曰：“呜呼！崔子为无道，而弑其君，不与公室而与崔庆者，受此不祥。”俯而饮血。
崔子谓晏子曰：“子变子言，则齐国吾与子共之；子不变子言，戟既在脰，剑既在心，维子图之也。”
晏子曰：“劫吾以刃，而失其志，非勇也；回吾以利，而倍其君，非义也。崔子！子独不为夫诗乎！诗云：‘莫莫葛藟，施于条枚，恺恺君子，求福不回。’今婴且可以回而求福乎？曲刃钩之，直兵推之，婴不革矣。”
崔杼将杀之，或曰：“不可！子以子之君无道而杀之，今其臣有道之士也，又从而杀之，不可以为教矣。”崔子遂舍之。晏子曰：“若大夫为大不仁，而为小仁，焉有中乎！”趋出，授绥而乘。其仆将驰，晏子抚其手曰：“徐之！疾不必生，徐不必死，鹿生于野，命县于厨，婴命有系矣。”按之成节而后去。诗云：“彼己之子，舍命不渝。”晏子之谓也。
晏子再治阿而见信景公任以国政第四
景公使晏子为东阿宰，三年，毁闻于国。景公不说，召而免之。
晏子谢曰：“婴知婴之过矣，请复治阿，三年而誉必闻于国。”景公不忍，复使治阿，三年而誉闻于国。景公说，召而赏之。景公问其故。
对曰：“昔者婴之治阿也，筑蹊径，急门闾之政，而淫民恶之；举俭力孝弟，罚偷窳，而惰民恶之；决狱不避，贵彊恶之；左右所求，法则予，非法则否，而左右恶之；事贵人体不过礼，而贵人恶之。是以三邪毁乎外，二谗毁于内，三年而毁闻乎君也。今臣谨更之，不筑蹊径，而缓门闾之政，而淫民说；不举俭力孝弟，不罚偷窳，而惰民说；决狱阿贵彊，而贵彊说；左右所求言诺，而左右说；事贵人体过礼，而贵人说。是以三邪誉乎外，二谗誉乎内，三年而誉闻于君也。昔者婴之所以当诛者宜赏，今所以当赏者宜诛，是故不敢受。”
景公知晏子贤，乃任以国政，三年，而齐大兴。
景公恶故人晏子退国乱复召晏子第五
景公与晏子立于曲潢之上，晏子称曰：“衣莫若新，人莫若故。”
公曰：“衣之新也，信善矣，人之故，相知情。”
晏子归，负载使人辞于公曰：“婴故老耄无能也，请毋服壮者之事。”公自治国，身弱于高国，百姓大乱。公恐，复召晏子。诸侯忌其威，而高国服其政，田畴垦辟，蚕桑豢收之处不足，丝蚕于燕，牧马于鲁，共贡入朝。墨子闻之曰：“晏子知道，景公知穷矣。”
齐饥晏子因路寝之役以振民第六
景公之时饥，晏子请为民发粟，公不许，当为路寝之台，晏子令吏重其赁，远其兆，徐其日，而不趋。三年台成而民振，故上说乎游，民足乎食。君子曰：“政则晏子欲发粟与民而已，若使不可得，则依物而偶于政。”
景公欲堕东门之堤晏子谓不可变古第七
景公登东门防，民单服然后上，公曰：“此大伤牛马蹄矣，夫何不下六尺哉？”
晏子对曰：“昔者吾先君桓公，明君也，而管仲贤相也。夫以贤相佐明君，而东门防全也，古者不为，殆有为也。蚤岁溜水至，入广门，即下六尺耳，乡者防下六尺，则无齐矣。夫古之重变古常，此之谓也。”
景公怜饥者晏子称治国之本以长其意第八
景公游于寿宫，睹长年负薪者，而有饥色。公悲之，喟然叹曰：“令吏养之！”
晏子曰：“臣闻之，乐贤而哀不肖，守国之本也。今君爱老，而恩无所不逮，治国之本也。”
公笑，有喜色。晏子曰：“圣王见贤以乐贤，见不肖以哀不肖。今请求老弱之不养，鳏寡之无室者，论而共秩焉。”
公曰：“诺。”于是老弱有养，鳏寡有室。
景公探雀鷇鷇弱反之晏子称长幼以贺第九
景公探雀鷇，鷇弱，反之。晏子闻之，不待时而入见景公。公汗出惕然，晏子曰：“君何为者也？”
公曰：“吾探雀鷇，鷇弱，故反之。”
晏子逡巡北面再拜而贺曰：“吾君有圣王之道矣！”
公曰：“寡人探雀鷇，鷇弱，故反之，其当圣王之道者何也？”
晏子对曰：“君探雀鷇，鷇弱，反之，是长幼也。吾君仁爱，曾禽兽之加焉，而况于人乎！此圣王之道也。”
景公睹乞儿于涂晏子讽公使养第十
景公睹婴儿有乞于涂者，公曰：“是无归矣！”
晏子对曰：“君存，何为无归？使吏养之，可立而以闻。”
景公惭刖跪之辱不朝晏子称直请赏之第十一
景公正昼，被发，乘六马，御妇人以出正闺，刖跪击其马而反之，曰：“尔非吾君也。”公惭而不朝。
晏子睹裔款而问曰：“君何故不朝？”
对曰：“昔者君正昼，被发，乘六马，御妇人以出正闺，刖跪击其马而反之，曰：‘尔非吾君也。’公惭而反，不果出，是以不朝。”
晏子入见。景公曰：“昔者寡人有罪，被发，乘六马，以出正闺，刖跪击马而反之，曰：‘尔非吾君也。’寡人以天子大夫之赐，得率百姓以守宗庙，今见戮于刖跪，以辱社稷，吾犹可以齐于诸侯乎？”
晏子对曰：“君勿恶焉！臣闻下无直辞，上有隐君；民多讳言，君有骄行。古者明君在上，下多直辞；君上好善，民无讳言。今君有失行，刖跪直辞禁之，是君之福也。故臣来庆。请赏之，以明君之好善；礼之，以明君之受谏。”
公笑曰：“可乎？”
晏子曰：“可。”于是令刖跪倍资无征，时朝无事也。
景公夜从晏子饮晏子称不敢与第十二
景公饮酒，夜移于晏子，前驱款门曰：“君至！”
晏子被元端，立于门曰：“诸侯得微有故乎？国家得微有事乎？君何为非时而夜辱？”
公曰：“酒醴之味，金石之声，愿与夫子乐之。”
晏子对曰：“夫布荐席，陈簠簋者，有人，臣不敢与焉。”
公曰：“移于司马穣苴之家。”前驱款门，曰：“君至！”
穣苴介胄操戟立于门曰：“诸侯得微有兵乎？大臣得微有叛者乎？君何为非时而夜辱？”
公曰：“酒醴之味，金石之声，愿与将军乐之。”
穣苴对曰：“夫布荐席，陈簠簋者，有人，臣不敢与焉。”
公曰：“移于梁丘据之家。”前驱款门，曰：“君至！”
梁丘据左操瑟，右挈竽，行歌而出。公曰：“乐哉！今夕吾饮也。微此二子者，何以治吾国；微此一臣者，何以乐吾身。”
君子曰：“圣贤之君，皆有益友，无偷乐之臣，景公弗能及，故两用之，仅得不亡。”
景公使进食与裘晏子对以社稷臣第十三
晏子侍于景公，朝寒，公曰：“请进暖食。”
晏子对曰：“婴非君奉馈之臣也，敢辞。”公曰：“请进服裘。”
对曰：“婴非君茵席之臣也，敢辞。”公曰：“然夫子之于寡人何为者也？”
对曰：“婴，社稷之臣也。”公曰：“何谓社稷之臣？”
对曰：“夫社稷之臣，能立社稷，别上下之义，使当其理；制百官之序，使得其宜；作为辞令，可分布于四方。”自是之后，君不以礼，不见晏子。
晏子饮景公止家老敛欲与民共乐第十四
晏子饮景公酒，令器必新，家老曰：“财不足，请敛于氓。”
晏子曰：“止！夫乐者，上下同之。故天子与天下，诸侯与境内，大夫以下各与其僚，无有独乐。今上乐其乐，下伤其费，是独乐者也，不可！”
晏子饮景公酒公呼具火晏子称诗以辞第十五
晏子饮景公酒，日暮，公呼具火，晏子辞曰：“诗云：‘侧弁之俄’，言失德也。‘屡舞傞傞’，言失容也。‘既醉以酒，既饱以德，既醉而出，并受其福’，宾主之礼也。‘醉而不出，是谓伐德’，宾之罪也。婴已卜其日，未卜其夜。”
公曰：“善。”举酒祭之，再拜而出。曰：“岂过我哉，吾托国于晏子也。以其家货养寡人，不欲其淫侈也，而况与寡人谋国乎！”
晋欲攻齐使人往观晏子以礼侍而折其谋第十六
晋平公欲伐齐，使范昭往观焉。景公觞之，饮酒酣，范昭曰：“请君之弃樽。”公曰：“酌寡人之樽，进之于客。”范昭已饮，晏子曰：“彻樽，更之。”樽觯具矣，范昭佯醉，不说而起舞，谓太师曰：“能为我调成周之乐乎？吾为子舞之。”太师曰：“冥臣不习。”范昭趋而出。
景公谓晏子曰：“晋，大国也，使人来将观吾政，今子怒大国之使者，将奈何？”
晏子曰：“夫范昭之为人也，非陋而不知礼也，且欲试吾君臣，故绝之也。”
景公谓太师曰：“子何以不为客调成周之乐乎？”
太师对曰：“夫成周之乐，天子之乐也，调之，必人主舞之。今范昭人臣，欲舞天子之乐，臣故不为也。”
范昭归以报平公曰：“齐未可伐也。臣欲试其君，而晏子识之；臣欲犯其礼，而太师知之。”
仲尼闻之曰：“夫不出于尊俎之间，而知千里之外，其晏子之谓也。可谓折冲矣！而太师其与焉。”
景公问东门无泽年谷而对以冰晏子请罢伐鲁第十七
景公伐鲁，傅许，得东门无泽，公问焉：“鲁之年谷何如？”对曰：“阴水厥，阳冰厚五寸。”不知，以告晏子。
晏子对曰：“君子也。问年谷而对以冰，礼也。阴水厥，阳冰厚五寸者，寒温节，节则刑政平，平则上下和，和则年谷熟。年充众和而伐之，臣恐罢民弊兵，不成君之意。请礼鲁以息吾怨，遣其执，以明吾德。”公曰：“善。”乃不伐鲁。
景公使晏子予鲁地而鲁使不尽受第十八
景公予鲁君地，山阴数百社，使晏子致之，鲁使子叔昭伯受地，不尽受也。晏子曰：“寡君献地，忠廉也，曷为不尽受？”
子叔昭伯曰：“臣受命于君曰：‘诸侯相见，交让，争处其卑，礼之文也；交委多，争受少，行之实也。礼成文于前，行成章于后，交之所以长久也。’且吾闻君子不尽人之欢，不竭人之忠，吾是以不尽受也。”晏子归报公，公喜笑曰：“鲁君犹若是乎。”
晏子曰：“臣闻大国贪于名，小国贪于实，此诸侯之通患也。今鲁处卑而不贪乎尊，辞实而不贪乎多，行廉不为苟得，道义不为苟合，不尽人之欢，不竭人之忠，以全其交，君之道义，殊于世俗，国免于公患。”
公曰：“寡人说鲁君，故予之地，今行果若此，吾将使人贺之。”
晏子曰：“不！君以欢予之地，而贺其辞，则交不亲，而地不为德矣。”公曰：“善。”于是重鲁之币，毋比诸侯，厚其礼，毋比宾客。君子于鲁，而后明行廉辞地之可为重名也。
景公游纪得金壶中书晏子因以讽之第十九
景公游于纪，得金壶，乃发视之，中有丹书，曰：“食鱼无反，勿乘驽马。”
公曰：“善哉！知苦言，食鱼无反，则恶其鱢也；勿乘驽马，恶其取道不远也。”
晏子对曰：“不然。食鱼无反，毋尽民力乎！勿乘驽马，则无置不肖于侧乎！”
公曰：“纪有书，何以亡也？”
晏子对曰：“有以亡也。婴闻之，君子有道，悬之闾。纪有此言，注之壶，不亡何待乎！”
景公贤鲁昭公去国而自悔晏子谓无及已第二十
鲁昭公弃国走齐，齐公问焉，曰：“君何年之少，而弃国之蚤？奚道至于此乎？”
昭公对曰：“吾少之时，人多爱我者，吾体不能亲；人多谏我者，吾志不能用；好则内无拂而外无辅，辅拂无一人，谄谀我者甚众。譬之犹秋蓬也，孤其根而美枝叶，秋风一至，根且拔矣。”
景公辩其言，以语晏子，曰：“使是人反其国，岂不为古之贤君乎？”
晏子对曰：“不然。夫愚者多悔，不肖者自贤，溺者不问坠，迷者不问路。溺而后问坠，迷而后问路，譬之犹临难而遽铸兵，噎而遽掘井，虽速亦无及已。”
景公使鲁有事已仲尼以为知礼第二十一
晏子使鲁，仲尼命门弟子往观。子贡反，报曰：“孰谓晏子习于礼乎？夫礼曰：‘登阶不历，堂上不趋，授玉不跪。’今晏子皆反此，孰谓晏子习于礼者？”晏子既已有事于鲁君，退见仲尼，仲尼曰：“夫礼，登阶不历，堂上不趋，授玉不跪。夫子反此乎？”
晏子曰：“婴闻两槛之闲，君臣有位焉，君行其一，臣行其二。君之来速，是以登阶历堂上趋以及位也。君授玉卑，故跪以下之。且吾闻之，大者不逾闲，小者出入可也。”晏子出，仲尼送之以宾客之礼，不计之义，维晏子为能行之。
晏子之鲁进食有豚亡二肩不求其人第二十二
晏子之鲁，朝食进馈膳，有豚焉。晏子曰：“去其二肩。”昼者进膳，则豚肩不具。侍者曰：“膳豚肩亡。”
晏子曰：“释之矣。”侍者曰：“我能得其人。”
晏子曰：“止。吾闻之，量功而不量力，则民尽；藏余不分，则民盗。子教我所以改之，无教我求其人也。”
曾子将行晏子送之而赠以善言第二十三
曾子将行，晏子送之曰：“君子赠人以轩，不若以言。吾请以言之，以轩乎？”曾子曰：“请以言。”
晏子曰：“今夫车轮，山之直木也，良匠揉之，其圆中规，虽有槁暴，不复嬴矣，故君子慎隐揉。和氏之璧，井里之困也，良工修之，则为存国之宝，故君子慎所修。今夫兰本，三年而成，湛之苦酒，则君子不近，庶人不佩；湛之縻醢，而贾匹马矣。非兰本美也，所湛然也。愿子之必求所湛。婴闻之，君子居必择邻，游必就士，择居所以求士，求士所以辟患也。婴闻汩常移质，习俗移性，不可不慎也。”
晏子之晋睹齐累越石父解左骖赎之与归第二十四
晏子之晋，至中牟，睹敝冠反裘负刍，息于涂侧者，以为君子也，使人问焉。曰：“子何为者也？”对曰：“我越石父者也。”
晏子曰：“何为至此？”曰：“吾为人臣，仆于中牟，见使将归。”
晏子曰：“何为为至仆？”对曰：“不免冻饿之切吾身，是以为仆也。”
晏子曰：“为仆几何？”对曰：“三年矣。”
晏子曰：“可得赎乎？”对曰：“可。”
遂解左骖以赠之，因载而与之俱归。至舍，不辞而入，越石父怒而请绝，晏子使人应之曰：“吾未尝得交夫子也，子为仆三年，吾乃今日睹而赎之，吾于子尚未可乎？子何绝我之暴也。”
越石父对之曰：“臣闻之，士者诎乎不知己，而申乎知己，故君子不以功轻人之身，不为彼功诎身之理。吾三年为人臣仆，而莫吾知也。今子赎我，吾以子为知我矣；向者子乘，不我辞也，吾以子为忘；今又不辞而入，是与臣我者同矣。我犹且为臣，请鬻于世。”
晏子出，见之曰：“向者见客之容，而今也见客之意。婴闻之，省行者不引其过，察实者不讥其辞，婴可以辞而无弃乎！婴诚革之。”
乃令粪洒改席，尊醮而礼之。越石父曰：“吾闻之，至恭不修途，尊礼不受摈。夫子礼之，仆不敢当也。”晏子遂以为上客。
君子曰：“俗人之有功则德，德则骄，晏子有功，免人于厄，而反诎下之，其去俗亦远矣。此全功之道也。”
晏子之御感妻言而自抑损晏子荐以为大夫第二十五
晏子为齐相，出，其御之妻从门闲而窥，其夫为相御，拥大盖，策驷马，意气扬扬，甚自得也。既而归，其妻请去。夫问其故，妻曰：“晏子长不满六尺，相齐国，名显诸侯。今者妾观其出，志念深矣，常有以自下者。今子长八尺，乃为人仆御；然子之意，自以为足，妾是以求去也。”
其后，夫自抑损。晏子怪而问之，御以实对，晏子荐以为大夫。
泯子午见晏子晏子恨不尽其意第二十六
燕之游士，有泯子午者，南见晏子于齐，言有文章，术有条理，巨可以补国，细可以益晏子者，三百篇。睹晏子，恐慎而不能言。晏子假之以悲色，开之以礼颜，然后能尽其复也。客退。晏子直席而坐，废朝移时。在侧者曰：“向者燕客侍，夫子胡为忧也？”
晏子曰：“燕，万乘之国也；齐，千里之涂也。泯子午以万乘之国为不足说，以千里之涂为不足远，则是千万人之上也。且犹不能殚其言于我，况乎齐人之怀善而死者乎！吾所以不得睹者，岂不多矣！然吾失此，何之有也。”
晏子乞北郭骚米以养母骚杀身以明晏子之贤第二十七
齐有北郭骚者，结罘罔，捆蒲苇，织履，以养其母，犹不足，踵门见晏子曰：“窃说先生之义，愿乞所以养母者。”
晏子使人分仓粟府金而遗之，辞金受粟。有闲，晏子见疑于景公，出奔，过北郭骚之门而辞。北郭骚沐浴而见晏子曰：“夫子将焉适？”
晏子曰：“见疑于齐君，将出奔。”
北郭骚曰：“夫子勉之矣！”
晏子上车太息而叹曰：“婴之亡岂不宜哉！亦不知士甚矣。”
晏子行，北郭子召其友而告之曰：“吾说晏子之义，而尝乞所以养母者焉。吾闻之，养其亲者身伉其难。今晏子见疑，吾将以身死白之。”
着衣冠，令其友操剑，奉笥而从，造于君庭，求复者曰：“晏子，天下之贤者也；今去齐国，齐必侵矣。方见国之必侵，不若死，请以头托白晏子也。”因谓其友曰：“盛吾头于笥中，奉以托。”退而自刎。
其友因奉托而谓复者曰：“此北郭子为国故死，吾将为北郭子死。”又退而自刎。景公闻之，大骇，乘驲而自追晏子，及之国郊，请而反之。晏子不得已而反，闻北郭子之以死白己也，太息而叹曰：“婴之亡，岂不宜哉！亦愈不知士甚矣。”
景公欲见高纠晏子辞以禄仕之臣第二十八
景公谓晏子曰：“吾闻高纠与夫子游，寡人请见之。”
晏子对曰：“臣闻之，为地战者，不能成其王；为禄仕者，不能正其君。高纠与婴为兄弟久矣，未尝干婴之行，特禄之臣也，何足以补君乎！”
高纠治晏子家不得其俗乃逐之第二十九
高纠事晏子而见逐，高纠曰：“臣事夫子三年，无得，而卒见逐，其说何也？”
晏子曰：“婴之家俗有三，而子无一焉。”纠曰：“可得闻乎？”
晏子曰：“婴之家俗，闲处从容不谈议，则疏；出不相扬美，入不相削行，则不与；通国事无论，骄士慢知者，则不朝也。此三者，婴之家俗，今子是无一焉。故婴非特食馈之长也，是以辞。”
晏子居丧逊畣家老仲尼善之第三十
晏子居晏桓子之丧，粗衰，斩，苴绖带，杖，菅屦，食粥，居倚庐，寝苫，枕草。其家老曰：“非大夫丧父之礼也。”
晏子曰：“唯卿为大夫。”曾子以闻孔子，孔子曰：“晏子可谓能远害矣。不以己之是驳人之非，逊辞以避咎，义也夫！”', '', '', '', NULL, '', 'indent', 1545260456, '5c1a5d461579a3005f6fb0be', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640755, '晏子春秋 · 内篇 · 杂下第六', NULL, 20, 573, 2, 3, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', '', '', '　灵公禁妇人为丈夫饰不止晏子请先内勿服第一
灵公好妇人而丈夫饰者，国人尽服之，公使吏禁之，曰：“女子而男子饰者，裂其衣，断其带。”裂衣断带相望，而不止。
晏子见，公问曰：“寡人使吏禁女子而男子饰，裂断其衣带，相望而不止者何也？”
晏子对曰：“君使服之于内，而禁之于外，犹悬牛首于门，而卖马肉于内也。公何以不使内勿服，则外莫敢为也。”
公曰：“善。”使内勿服，逾月，而国莫之服。
齐人好毂击晏子绐以不祥而禁之第二
齐人甚好毂击，相犯以为乐。禁之不止。晏子患之，乃为新车良马，出与人相犯也，曰：“毂击者不祥，臣其祭祀不顺，居处不敬乎？”下车而弃去之，然后国人乃不为。
故曰：“禁之以制，而身不先行，民不能止。故化其心，莫若教也。”
景公瞢五丈夫称无辜晏子知其冤第三
景公畋于梧丘，夜犹早，公姑坐睡，而瞢有五丈夫北面韦庐，称无罪焉。公觉，召晏子而告其所瞢。公曰：“我其尝杀不辜，诛无罪邪？”
晏子对曰：“昔者先君灵公畋，五丈夫罟而骇兽，故杀之，断其头而葬之。命曰‘五丈夫之丘’，此其地邪？”公令人掘而求之，则五头同穴而存焉。公曰：“嘻！”令吏葬之。国人不知其瞢也，曰：“君悯白骨，而况于生者乎，不遗余力矣，不释余知矣。”故曰：君子之为善易矣。
柏常骞禳枭死将为景公请寿晏子识其妄第四
景公为路寝之台，成，而不踊焉。柏常骞曰：“君为台甚急，台成，君何为而不踊焉？”公曰：“然！有枭昔者鸣，声无不为也，吾恶之甚，是以不踊焉。”
柏常骞曰：“臣请禳而去。”公曰：“何具？”对曰：“筑新室，为置白茅。”公使为室，成，置白茅焉。柏常骞夜用事。明日，问公曰：“今昔闻鸮声乎？”公曰：“一鸣而不复闻。”使人往视之，鸮当陛，布翌，伏地而死。公曰：“子之道若此其明，亦能益寡人之寿乎？”对曰：“能。”公曰：“能益几何？”对曰：“天子九，诸侯七，大夫五。”公曰：“子亦有征兆之见乎？”对曰：“得寿，地且动。”公喜，令百官趣具骞之所求。柏常骞出，遭晏子于涂，拜马前，骞辞曰：“为禳君鸮而杀之，君谓骞曰：‘子之道若此其明也，亦能益寡人寿乎？’骞曰：‘能。’今且大祭，为君请寿，故将往，以闻。”晏子曰：“嘻！亦善能为君请寿也。虽然，吾闻之，维以政与德而顺乎神，为可以益寿，今徒祭，可以益寿乎？然则福兆有见乎？”对曰：“得寿，地将动。”
晏子曰：“骞！昔吾见维星绝，枢星散，地其动，汝以是乎？”柏常骞俯有闲，仰而对曰：“然。”晏子曰：“为之无益，不为无损也。汝薄敛，毋费民，且无令君知之。”
景公成柏寝而师开言室夕晏子辨其所以然第五
景公新成柏寝之台，使师开鼓琴，师开左抚宫，右弹商，曰：“室夕。”公曰：“何以知之？”
师开对曰：“东方之声薄，西方之声扬。”公召大匠曰：“室何为夕？”
大匠曰：“立室以宫矩为之。”于是召司空曰：“立宫何为夕？”
司空曰：“立宫以城矩为之。”明日，晏子朝公，公曰：“先君太公以营丘之封立城，曷为夕？”
晏子对曰：“古之立国者，南望南斗，北戴枢星，彼安有朝夕哉！然而以今之夕者，周之建国，国之西方，以尊周也。”公蹙然曰：“古之臣乎！”
景公病水瞢与日斗晏子教占瞢者以对第六
景公病水，卧十数日，夜瞢与二日斗，不胜。晏子朝，公曰：“夕者瞢与二日斗，而寡人不胜，我其死乎？”
晏子对曰：“请召占瞢者。”出于闺，使人以车迎占瞢者。至，曰：“曷为见召？”
晏子曰：“夜者，公瞢二日与公斗，不胜。公曰：‘寡人死乎？’故请君占瞢，是所为也。”占瞢者曰：“请反具书。”
晏子曰：“毋反书。公所病者，阴也，日者，阳也。一阴不胜二阳，故病将已。以是对。”占瞢者入，公曰：“寡人瞢与二日斗而不胜，寡人死乎？”占瞢者对曰：“公之所病，阴也，日者，阳也。一阴不胜二阳，公病将已。”
居三日，公病大愈，公且赐占瞢者。占瞢者曰：“此非臣之力，晏子教臣也。”公召晏子，且赐之。晏子曰：“占瞢者以占之言对，故有益也。使臣言之，则不信矣。此占瞢之力也，臣无功焉。”
公两赐之，曰：“以晏子不夺人之功，以占瞢者不蔽人之能。”
景公病疡晏子抚而对之乃知群臣之野第七
景公病疽，在背，高子国子请。公曰：“职当抚疡。”高子进而抚疡，公曰：“热乎？”曰：“热。”“热何如？”曰：“如火。”“其色何如？”曰：“如未热李。”“大小何如？”曰：“如豆。”“堕者何如？”曰：“如屦辨。”二子者出，晏子请见。公曰：“寡人有病，不能胜衣冠以出见夫子，夫子其辱视寡人乎？”
晏子入，呼宰人具盥，御者具巾，刷手温之，发席傅荐，跪请抚疡。公曰：“其热何如？”曰：“如日。”“其色何如？”曰：“如苍玉。”“大小何如？”曰：“如璧。”“其堕者何如？”曰：“如珪。”晏子出，公曰：“吾不见君子，不知野人之拙也。”
晏子使吴吴王命傧者称天子晏子详惑第八
晏子使吴，吴王谓行人曰：“吾闻晏婴，盖北方辩于辞，习于礼者也。命摈者‘客见则称天子请见。’”
明日，晏子有事，行人曰：“天子请见。”晏子蹙。行人又曰：“天子请见。”晏子蹙然。又曰：“天子请见。”晏子蹙然者，曰：“臣受命敝邑之君，将使于吴王之所，以不敏而迷惑，入于天子之朝，问吴王恶乎存？”然后吴王曰：“夫差请见。”见之以诸侯之礼。
晏子使楚楚为小门晏子称使狗国者入狗门第九
晏子使楚，以晏子短，楚人为小门于大门之侧而延晏子。晏子不入，曰：“使狗国者，从狗门入；今臣使楚，不当从此门入。”傧者更道从大门入，见楚王。王曰：“齐无人耶？”
晏子对曰：“临淄三百闾，张袂成阴，挥汗成雨，比肩继踵而在，何为无人？”
王曰：“然则子何为使乎？”
晏子对曰：“齐命使，各有所主，其贤者使使贤王，不肖者使使不肖王。婴最不肖，故直使楚矣。”
楚王欲辱晏子指盗者为齐人晏子对以橘第十
晏子将至楚，楚闻之，谓左右曰：“晏婴，齐之习辞者也，今方来，吾欲辱之，何以也？”
左右对曰：“为其来也，臣请缚一人，过王而行，王曰：‘何为者也？’对曰：‘齐人也。’王曰：‘何坐？’曰：‘坐盗。’”
晏子至，楚王赐晏子酒，酒酣，吏二缚一人诣王，王曰：“缚者曷为者也？”对曰：“齐人也，坐盗。”
王视晏子曰：“齐人固善盗乎？”
晏子避席对曰：“婴闻之，橘生淮南则为橘，生于淮北则为枳，叶徒相似，其实味不同。所以然者何？水土异也。今民生长于齐不盗，入楚则盗，得无楚之水土使民善盗耶？”
王笑曰：“圣人非所与熙也，寡人反取病焉。”
楚王飨晏子进橘置削晏子不剖而食第十一
景公使晏子于楚，楚王进橘，置削，晏子不剖而并食之。
楚王曰：“当去剖。”晏子对曰：“臣闻之，赐人主之前者，瓜桃不削，橘柚不剖。今者万乘无教令，臣故不敢剖；不然，臣非不知也。”
晏子布衣栈车而朝陈桓子侍景公饮酒请浮之第十二
景公饮酒，田桓子侍，望见晏子，而复于公曰：“请浮晏子。”公曰：“何故也？”无宇对曰：“晏子衣缁布之衣，麋鹿之裘，栈轸之车，而驾驽马以朝，是隐君之赐也。”公曰：“诺。”
晏子坐，酌者奉觞进之，曰：“君命浮子。”
晏子曰：“何故也？”田桓子曰：“君赐之卿位以尊其身，宠之百万以富其家，群臣其爵莫尊于子，禄莫重于子。今子衣缁布之衣，麋鹿之裘，栈轸之车，而驾驽马以朝，是则隐君之赐也。故浮子。”
晏子避席曰：“请饮而后辞乎，其辞而后饮乎？”公曰：“辞然后饮。”
晏子曰：“君之赐卿位以尊其身，婴非敢为显受也，为行君令也；宠以百万以富其家，婴非敢为富受也，为通君赐也。臣闻古之贤臣，有受厚赐而不顾其国族，则过之；临事守职，不胜其任，则过之。君之内隶，臣之父兄，若有离散，在于野鄙，此臣之罪也。君之外隶，臣之所职，若有播亡，在于四方，此臣之罪也。兵革之不完，战车之不修，此臣之罪也。若夫弊车驽马以朝，意者非臣之罪乎？且臣以君之赐，父之党无不乘车者，母之党无不足于衣食者，妻之党无冻馁者，国之闲士待臣而后举火者数百家。如此者，为彰君赐乎，为隐君赐乎？”
公曰：“善！为我浮无宇也。”
田无宇请求四方之学士晏子谓君子难得第十三
田桓子见晏子独立于墙阴，曰：“子何为独立而不忧？何不求四乡之学士可者而与坐？”
晏子曰：“共立似君子，出言而非也。婴恶得学士之可者而与之坐？且君子之难得也，若美山然，名山既多矣，松柏既茂矣，望之相相然，尽目力不知厌。而世有所美焉，固欲登彼相相之上，仡仡然不知厌。小人者与此异，若部娄之未登，善，登之无蹊，维有楚棘而已；远望无见也，俯就则伤婴，恶能无独立焉？且人何忧，静处远虑，见岁若月，学问不厌，不知老之将至，安用从酒！”
田桓子曰：“何谓从酒？”晏子曰：“无客而饮，谓之从酒。今若子者，昼夜守尊，谓之从酒也。”
田无宇胜栾氏高氏欲分其家晏子使致之公第十四
栾氏、高氏欲逐田氏、鲍氏，田氏、鲍氏先知而遂攻之。高彊曰：“先得君，田、鲍安往？”遂攻虎门。二家召晏子，晏子无所从也。从者曰：“何为不助田、鲍？”
晏子曰：“何善焉，其助之也。”“何为不助栾、高？”曰：“庸愈于彼乎？”门开，公召而入。栾、高不胜而出，田桓子欲分其家，以告晏子。
晏子曰：“不可！君不能饬法，而群臣专制，乱之本也。今又欲分其家，利其货，是非制也。子必致之公。且婴闻之，廉者，政之本也；让者，德之主也。栾、高不让，以至此祸，可毋慎乎！廉之谓公正，让之谓保德，凡有血气者，皆有争心，怨利生孽，维义可以为长存。且分争者不胜其祸，辞让者不失其福，子必勿取。”
桓子曰：“善。”尽致之公，而请老于剧。
子尾疑晏子不受庆氏之邑晏子谓足欲则亡第十五
庆氏亡，分其邑，与晏子邶殿，其鄙六十，晏子勿受。子尾曰：“富者，人之所欲也，何独弗欲？”
晏子对曰：“庆氏之邑足欲，故亡。吾邑不足欲也，益之以邶殿，乃足欲；足欲，亡无日矣。在外不得宰吾一邑，不受邶殿，非恶富也，恐失富也。且夫富，如布帛之有幅焉，为之制度，使无迁也。夫生厚而用利，于是乎正德以幅之，使无黜慢，谓之幅利，利过则为败，吾不敢贪多，所谓幅也。”
景公禄晏子平阴与棠邑晏子愿行三言以辞第十六
景公禄晏子以平阴与棠邑，反市者十一社。晏子辞曰：“吾君好治宫室，民之力弊矣；又好盘游玩好，以饬女子，民之财竭矣；又好兴师，民之死近矣。弊其力，竭其财，近其死，下之疾其上甚矣！此婴之所为不敢受也。”
公曰：“是则可矣。虽然，君子独不欲富与贵乎？”晏子曰：“婴闻为人臣者，（先国后家，）先君后身；安国而度家，宗君而处身，曷为独不欲富与贵也！”
公曰：“然则曷以禄夫子？”晏子对曰：“君商渔盐，关市讥而不征；耕者十取一焉；弛刑罚──若死者刑，若刑者罚，若罚者免。若此三言者，婴之禄，君之利也。”公曰：“此三言者，寡人无事焉，请以从夫子。”公既行若三言，使人问大国，大国之君曰：“齐安矣。”使人问小国，小国之君曰：“齐不加我矣。”
梁丘据言晏子食肉不足景公割地将封晏子辞第十七
晏子相齐，三年，政平民说。梁丘据见晏子中食，而肉不足，以告景公，旦日，割地将封晏子，晏子辞不受。曰：“富而不骄者，未尝闻之。贫而不恨者，婴是也。所以贫而不恨者，以善为师也。今封，易婴之师，师已轻，封已重矣，请辞。”
景公以晏子食不足致千金而晏子固不受第十八
晏子方食，景公使使者至。分食食之，使者不饱，晏子亦不饱。使者反，言之公。
公曰：“嘻！晏子之家，若是其贫也。寡人不知，是寡人之过也。”使吏致千金与市租，请以奉宾客。晏子辞，三致之，终再拜而辞曰：“婴之家不贫。以君之赐，泽覆三族，延及交游，以振百姓，君之赐也厚矣！婴之家不贫也。婴闻之，夫厚取之君，而施之民，是臣代君君民也，忠臣不为也。厚取之君，而不施于民，是为筐箧之藏也，仁人不为也。进取于君，退得罪于士，身死而财迁于它人，是为宰藏也，智者不为也。夫十总之布，一豆之食，足于中免矣。”
景公谓晏子曰：“昔吾先君桓公，以书社五百封管仲，不辞而受，子辞之何也？”
晏子曰：“婴闻之，圣人千虑，必有一失；愚人千虑，必有一得。意者管仲之失，而婴之得者耶？故再拜而不敢受命。”
景公以晏子衣食弊薄使田无宇致封邑晏子辞第十九
晏子相齐，衣十升之布，脱粟之食，五卯、苔菜而已。左右以告公，公为之封邑，使田无宇致台与无盐。晏子对曰：“昔吾先君太公受之营丘，为地五百里，为世国长，自太公至于公之身，有数十公矣。苟能说其君以取邑，不至公之身，趣齐搏以求升土，不得容足而寓焉。婴闻之，臣有德益禄，无德退禄，恶有不肖父为不肖子为封邑以败其君之政者乎？”遂不受。
田桓子疑晏子何以辞邑晏子答以君子之事也第二十
景公赐晏子邑，晏子辞。田桓子谓晏子曰：“君欢然与子邑，必不受以恨君，何也？”晏子对曰：“婴闻之，节受于上者，宠长于君；俭居处者，名广于外。夫长宠广名，君子之事也。婴独庸能已乎？”
景公欲更晏子宅晏子辞以近市得求讽公省刑第二十一
景公欲更晏子之宅，曰：“子之宅近市湫隘，嚣尘不可以居，请更诸爽垲者。”
晏子辞曰：“君之先臣容焉，臣不足以嗣之，于臣侈矣。且小人近市，朝夕得所求，小人之利也。敢烦里旅！”
公笑曰：“子近市，识贵贱乎？”
对曰：“既窃利之，敢不识乎！”
公曰：“何贵何贱？”是时也，公繁于刑，有鬻踊者。故对曰：“踊贵而屦贱。”公愀然改容。公为是省于刑。君子曰：“仁人之言，其利博哉！晏子一言，而齐侯省刑。诗曰：‘君子如祉，乱庶遄已。’其是之谓乎。”
景公毁晏子邻以益其宅晏子因陈桓子以辞第二十二
晏子使晋，景公更其宅，反则成矣。既拜，乃毁之，而为里室，皆如其旧，则使宅人反之。且“谚曰：‘非宅是卜，维邻是卜。’二三子先卜邻矣。违卜不祥。君子不犯非礼，小人不犯不祥，古之制也。吾敢违诸乎？”卒复其旧宅。公弗许。因陈桓子以请，乃许之。
景公欲为晏子筑室于宫内晏子称是以远之而辞第二十三
景公谓晏子曰：“寡人欲朝夕见，为夫子筑室于闺内可乎？”晏子对曰：“臣闻之，隐而显，近而结，维至贤耳。如臣者，饰其容止，以待承令，犹恐罪戾也，今君近之，是远之也，请辞。”
景公以晏子妻老且恶欲内爱女晏子再拜以辞第二十四
景公有爱女，请嫁于晏子，公乃往燕晏子之家，饮酒，酣，公见其妻曰：“此子之内子耶？”
晏子对曰：“然，是也。”
公曰：“嘻！亦老且恶矣。寡人有女少且姣，请以满夫子之宫。”
晏子违席而对曰：“乃此则老且恶，婴与之居故矣，故及其少且姣也。且人固以壮托乎老，姣托乎恶，彼尝托，而婴受之矣。君虽有赐，可以使婴倍其托乎？”再拜而辞。
景公以晏子乘弊车驽马使梁丘据遗之三返不受第二十五
晏子朝，乘弊车，驾驽马。景公见之曰：“嘻！夫子之禄寡耶？何乘不任之甚也？”
晏子对曰：“赖君之赐，得以寿三族，及国游士，皆得生焉。臣得暖衣饱食，弊车驽马，以奉其身，于臣足矣。”
晏子出，公使梁丘据遗之辂车乘马，三返不受。公不说，趣召晏子。晏子至，公曰：“夫子不受，寡人亦不乘。”
晏子对曰：“君使臣临百官之吏，臣节其衣服饮食之养，以先国之民；然犹恐其侈靡而不顾其行也。今辂车乘马，君乘之上，而臣亦乘之下，民之无义，侈其衣服饮食而不顾其行者，臣无以禁之。”遂让不受。
景公睹晏子之食菲薄而嗟其贫晏子称其参士之食第二十六
晏子相景公，食脱粟之食，炙三弋、五卯、苔菜耳矣。公闻之，往燕焉，睹晏子之食也。公曰：“嘻！夫子之家如此其贫乎！而寡人不知，寡人之罪也。”
晏子对曰：“以世之不足也，免粟之食饱，士之一乞也；炙三弋，士之二乞也；五卯，士之三乞也。婴无倍人之行，而有参士之食，君之赐厚矣！婴之家不贫。”再拜而谢。
梁丘据自患不及晏子晏子勉据以常为常行第二十七
梁丘据谓晏子曰：“吾至死不及夫子矣！”
晏子曰：“婴闻之，为者常成，行者常至。婴非有异于人也，常为而不置，常行而不休者，故难及也。”
晏子老辞邑景公不许致车一乘而后止第二十八
晏子相景公，老，辞邑。公曰：“自吾先君定公至今，用世多矣，齐大夫未有老辞邑者矣。今夫子独辞之，是毁国之故，弃寡人也。不可！”
晏子对曰：“婴闻古之事君者，称身而食；德厚而受禄，德薄则辞禄。德厚受禄，所以明上也；德薄辞禄，可以洁下也。婴老薄无能，而厚受禄，是掩上之明，污下之行，不可。”
公不许，曰：“昔吾先君桓公，有管仲恤劳齐国，身老，赏之以三归，泽及子孙。今夫子亦相寡人，欲为夫子三归，泽至子孙，岂不可哉？”
对曰：“昔者管子事桓公，桓公义高诸侯，德备百姓。今婴事君也，国仅齐于诸侯，怨积乎百姓，婴之罪多矣，而君欲赏之，岂以其不肖父为不肖子厚受赏以伤国民义哉？且夫德薄而禄厚，智惛而家富，是彰污而逆教也，不可。”公不许。晏子出。异日朝，得闲而入邑，致车一乘而后止。
晏子病将死妻问所欲言云毋变尔俗第二十九
晏子病，将死，其妻曰：“夫子无欲言乎？”子曰：“吾恐死而俗变，谨视尔家，毋变尔俗也。”
晏子病将死凿楹纳书命子壮示之第三十
晏子病，将死，凿楹纳书焉，谓其妻曰：“楹语也，子壮而示之。”及壮，发书之言曰：“布帛不可穷，穷不可饰；牛马不可穷，穷不可服；士不可穷，穷不可任；国不可穷，穷不可窃也。”', '', '', '', NULL, '', 'indent', 1545260503, '5c1a5d7f9f545400665cd23d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640756, '晏子春秋 · 外篇 · 第七', NULL, 23, 573, 1, 3, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', '', '', '景公饮酒命晏子去礼晏子谏第一
公饮酒数日而乐，释衣冠，自鼓缶，谓左右曰：“仁人亦 乐是夫？ ”梁丘据对曰：“仁人之耳目，亦犹人也，夫奚为独不乐此也？”
公曰：“趣驾迎晏子。”晏子朝服以至，受觞再拜。公曰：“寡人甚乐此乐，欲与夫子共之，请去礼。”
晏子对曰：“君之言过矣！群臣皆欲去礼以事君，婴恐君子之不欲也。今齐国五尺之童子，力皆过婴，又能胜君，然而不敢 乱者，畏礼也。上若无礼，无以使其下；下若无礼，无 以事其上。夫麋鹿维无礼，故父子同麀，人之所以贵于禽兽 者，以有礼也。婴闻之，人君无礼，无以临其邦；大夫无礼 ，官吏不恭；父子无礼，其家必凶；兄弟无礼，不能久同。诗 曰：‘人而无礼，胡不遄死。’故礼不可去也。”
公曰：“寡人不敏无良，左右淫蛊寡人，以至于此，请杀之。”
晏子曰：“左 右何罪？君若无礼，则好礼者去，无礼者至；君若好礼，则有礼 者至，无礼者去。”
公曰：“善。请易衣革冠，更受命。 ”晏子避走，立乎门外。公令人粪洒改席，召衣冠以迎晏子。 晏子入门，三让，升阶，用三献焉；嗛酒尝膳，再拜，告餍 而出。公下拜，送之门，反，命撤酒去乐，曰：“吾以彰晏 子之教也。”
景公置酒泰山四望而泣晏子谏第二
公置酒于泰山之阳，酒酣，公四望其地，喟然叹，泣数行而下，曰：“寡人将去此堂堂国者而死乎！”左右佐哀而泣者三人，曰：“吾细人也，犹将难死，而况公乎！弃是国也而死，其孰可为乎！”
晏子独搏其髀，仰天而大笑曰：“乐哉！今日之饮也。”公怫然怒曰：“寡人有哀，子独大笑，何也？”晏子对曰：“今日见怯君一，谀臣三人，是以大笑。”公曰：“何谓谀怯也？”晏子曰：“夫古之有死也，令后世贤者得之以息，不肖者得之以伏。若使古之王者毋知有死，自昔先君太公至今尚在，而君亦安得此国而哀之？夫盛之有衰，生之有死，天之分也。物有必至，事有常然，古之道也。曷为可悲？至老尚哀死者，怯也；左右助哀者，谀也。怯谀聚居，是故笑之。 ”公惭而更辞曰：“我非为去国而死哀也。寡人闻之，彗星出，其所向之国君当之，今彗星出而向吾国，我是以悲也。”晏子曰：“君之行义回邪，无德于国，穿池沼，则欲其深以广也；为台榭，则欲其高且大也；赋敛如撝夺，诛僇如仇雠。自是观之，茀又将出。天之变，彗星之出，庸可悲乎！”于是公惧，乃归，窴池沼，废台榭，薄赋敛，缓刑罚，三十七日而彗星亡。
景公瞢见彗星使人占之晏子谏第三
公瞢见彗星。明日，召晏子而问焉：“寡人闻之，有彗星者必有亡国。夜者，寡人瞢见彗星，吾欲召占瞢者使占之。”晏子对曰：“君居处无节，衣服无度，不听正谏，兴事无已，赋敛无厌，使民如将不胜，万民怼怨。茀星又将见瞢，奚独彗星乎！”
景公问古而无死其乐若何晏子谏第四
公饮酒，乐，公曰：“古而无死，其乐若何？”
晏子对曰：“古而无死，则古之乐也，君何得焉？昔爽鸠氏始居此地，季荝因之，有逢伯陵因之，蒲姑氏因之，而后太公因之。古若无 死，爽鸠氏之乐，非君所愿也。”
景公谓梁丘据与己和晏子谏第五
公至自畋，晏子侍于遄台，梁丘据造焉。公曰：“ 维据与我和夫！”晏子对曰：“据亦同也，焉得为和。 ”公曰：“和与同异乎？”
对曰：“异。和如羹焉，水火醯醢盐梅，以烹鱼肉，燀之以薪，宰夫和之，齐之以味，济其不及；以泄其过，君子食之，以平其心。君臣亦然。君所谓可，而有否焉，臣献其否，以成其可；君所谓否，而有可焉，臣献其可，以去其否。是以政平而不干，民无争心。故诗曰：‘亦有和羹，既戒且平；奏鬷无言，时靡有争。’先王之济五味，和五声也，以平其心，成其政也。声亦如味：一气，二体，三类，四物，五声，六律，七音，八风，九歌，以相成也；清浊，大小，短长，疾徐，哀乐，刚柔，迟速，高下，出入，周流，以相济也。君子听之，以平其心，心平德和。故诗曰：‘德音不瑕。’今据不然，君所谓可，据亦曰可；君所谓否，据亦曰否。若以水济水，谁能食之？若琴瑟之专一，谁能听之？同之不可也如是。”公曰：“善。”
景公使祝史禳彗星晏子谏第六
齐有彗星，景公使祝禳之。晏子谏曰：“无益也，祇取诬焉。天道不疑，不贰其命，若之何禳之也！且天之有彗，以除秽也。君无秽德，又何禳焉？若德之秽，禳之何损？诗云：‘维此文王，小心翼翼，昭事上帝，聿怀多福，厥德不回，以受方国。’君无违德，方国将至，何患于彗？诗曰：‘我无所监，夏后及商，用乱之故，民卒流亡。’若德之回乱，民将流亡，祝史之为，无能补也。”公说，乃止。
景公有疾梁丘据裔款请诛祝史晏子谏第七
公疥遂痁，期而不瘳。诸侯之宾，问疾者多在。梁丘据、裔款言于公曰：“吾事鬼神，丰于先君有加矣。今君疾病，为诸侯忧，是祝史之罪也。诸侯不知，其谓我不敬，君盍诛于祝固史嚚以辞宾。”公说，告晏子。晏子对曰：“日宋之盟，屈建问范会之德于赵武，赵武曰：‘夫子家事治，言于晋国，竭情无私，其祝史祭祀，陈言不愧；其家事无猜，其祝史不祈。’建以语康王，康王曰：‘神人无怨，宜天子之光辅五君，以为诸侯主也。’”
公曰：“据与款谓寡人能事鬼神，故欲诛于祝史，子称是语何故？”对曰：“若有德之君，外内不废，上下无怨，动无违事，其祝史荐信，无愧心矣。是以鬼神用飨，国受其福，祝史与焉。其所以蕃祉老寿者，为信君使也，其言忠信于鬼神。其适遇淫君，外内颇邪，上下怨疾，动作辟违，从欲厌私，高台深池，撞钟舞女，斩刈民力，输掠其聚，以成其违，不恤后人，暴虐淫纵，肆行非度，无所还忌，不思谤讟，不惮鬼神，神怒民痛，无悛于心。其祝史荐信，是言罪也；其盖失数美，是矫诬也；进退无辞，则虚以成媚，是以鬼神不飨，其国以祸之，祝史与焉。所以夭昏孤疾者，为暴君使也，其言僭嫚于鬼神。”
公曰：“然则若之何？”对曰：“不可为也。山林之木，衡鹿守之；泽之雈蒲，舟鲛守之；薮之薪蒸，虞候守之；海之盐蜃，祈望守之。县鄙之人，入从其政；逼介之关，暴征其私；承嗣大夫，彊易其贿；布常无艺，征敛无度；宫室日更，淫乐不违；内宠之妾肆夺于市，外宠之臣僭令于鄙；私欲养求，不给则应。民人苦病，夫妇皆诅。祝有益也，诅亦有损，聊摄以东，姑尤以西，其为人也多矣！虽其善祝，岂能胜亿兆人之诅！君若欲诛于祝史，修德而后可。”公说，使有司宽政，毁关去禁，薄敛已责，公疾愈。
景公见道殣自惭无德晏子谏第八
公赏赐及后宫，文绣被台榭，菽粟食凫雁；出而见殣，谓晏子曰：“此何为而死？”
晏子对曰：“此喂而死。”公曰：“嘻！寡人之无德也甚矣。”
对曰：“君之德着而彰，何为无德也？”景公曰：“ 何谓也？”
对曰：“君之德及后宫与台榭，君之玩物，衣以文绣；君之凫雁，食以菽粟；君之营内自乐，延及后宫之族，何为其无德！顾臣愿有请于君：由君之意，自乐之心，推而与百姓同之，则何殣之有！君不推此，而苟营内好私，使财货偏有所聚，菽粟币帛腐于囷府，惠不遍加于百姓，公心不周乎万国，则桀纣之所以亡也。夫士民之所以叛，由偏之也，君如察臣婴之言，推君之盛德，公布之于天下，则汤武可为也。一殣何足恤哉！”
景公欲诛断所爱橚者晏子谏第九
公登箐室而望，见人有断雍门之橚者，公令吏拘之，顾谓 晏子趣诛之。晏子默然不对。公曰：“雍门之橚，寡人所甚爱也，此 见断之，故使夫子诛之，默然而不应，何也？”
晏子对曰：“婴闻之，古者人君出，则辟道十里，非畏也；冕前 有旒，恶多所见也；纩纮珫耳，恶多所闻也；大带重半钧， 舄履倍重，不欲轻也。刑死之罪，日中之朝，君过之，则赦之， 婴未尝闻为人君而自坐其民者也。”公曰：“赦之，无使夫 子复言。”
景公坐路寝曰谁将有此晏子谏第十
公坐于路寝，曰：“美哉其室，将谁有此乎？”晏子对曰：“其田氏乎，田无宇为圻矣。”
公曰：“然则柰何？”晏子对曰：“为善者，君上之所劝也，岂可禁哉！夫田氏国门击柝之家，父以托其子，兄以托其弟，于今三世矣。山木如市，不加于山；鱼盐蚌蜃，不加于海；民财为之归。今岁凶饥，蒿种芼敛不半，道路有死人。齐旧四量而豆，豆四而区，区四而釜，釜十而钟。田氏四量，各加一焉。以家量贷，以公量收，则所以籴百姓之死命者泽矣。今公家骄汰，而田氏慈惠，国泽是将焉归？田氏虽无德而施于民。公厚敛而田氏厚施焉。诗曰：‘虽无德与汝，式歌且舞。’田氏之施，民歌舞之也，国之归焉，不亦宜乎！”
景公台成盆成适愿合葬其母晏子谏而许第十一
公宿于路寝之宫，夜分，闻西方有男子哭者，公悲之。明日朝，问于晏子曰：“寡人夜者闻西方有男子哭者，声甚哀，气甚悲，是奚为者也？寡人哀之。”
晏子对曰：“西郭徒居布衣之士盆成适也。父之孝子，兄之顺弟也。又尝为孔子门人。今其母不幸而死，祔柩未葬，家贫，身老，子孺，恐力不能合祔，是以悲也。”
公曰：“子为寡人吊之，因问其偏柎何所在？”晏子奉命往吊，而问偏之所在。盆成适再拜，稽首而不起，曰：“偏柎寄于路寝，得为地下之臣，拥扎掺笔，给事宫殿中右陛之下，愿以某日送，未得君之意也。穷困无以图之，布唇枯舌，焦心热中，今君不辱而临之，愿君图之。”
晏子曰：“然。此人之甚重者也，而恐君不许也。” 盆成适蹶然曰：“凡在君耳！且臣闻之，越王好勇，其民轻死；楚灵王好细腰，其朝多饿死人；子胥忠其君，故天下皆愿得以为子。今为人子臣，而离散其亲戚，孝乎哉？足以为臣乎？若此而得祔，是生臣而安死母也；若此而不得，则臣请挽尸车而寄之于国门外宇霤之下，身不敢饮食，拥辕执辂，木干鸟栖，袒肉暴骸，以望君愍之。贱臣虽愚，窃意明君哀而不忍也。”
晏子入，复乎公，公忿然作色而怒曰：“子何必患若言而教寡人乎？”晏子对曰：“婴闻之，忠不避危，爱无恶言。且婴固以难之矣。今君营处为游观，既夺人有，又禁其葬，非仁也；肆心傲听，不恤民忧，非义也。若何勿听？”因道盆成适之辞。
公喟然太息曰：“悲乎哉！子勿复言。”乃使男子袒免，女子发笄者以百数，为开凶门，以迎盆成适。适脱衰绖，冠条缨，墨缘，以见乎公。
公曰：“吾闻之，五子不满隅，一子可满朝，非乃子耶！”盆成适于是临事不敢哭，奉事以礼，毕，出门，然后举声焉。
景公筑长庲台晏子舞而谏第十二
景公筑长庲之台，晏子侍坐。觞三行，晏子起舞曰： “岁已暮矣，而禾不获，忽忽矣若之何！岁已寒矣，而役不罢，惙惙矣如之何！”舞三，而涕下沾襟。景公惭焉，为之罢长庲之役。
景公使烛邹主鸟而亡之公怒将加诛晏子谏第十三
公好弋，使烛邹主鸟而亡之，公怒，诏吏杀之。
晏子曰：“烛邹有罪三，请数之以其罪而杀之。”公曰：“可。”于是召而数之公前，曰：“烛邹！汝为吾君主鸟而亡之，是罪一也；使吾君以鸟之故杀人，是罪二也；使诸侯闻之，以吾君重鸟以轻士，是罪三也。” 数烛邹罪已毕，请杀之。
公曰：“勿杀！寡人闻命矣。”
景公问治国之患晏子对以佞人谗夫在君侧第十四
公问晏子曰：“治国之患亦有常乎？”对曰：“佞人谗夫之 在君侧者，好恶良臣，而行与小人，此国之长患也。”
公曰：“ 谗佞之人，则诚不善矣；虽然，则奚曾为国常患乎？”
晏子曰：“君以为耳目而好缪事，则是君之耳目缪也。夫上乱君之耳目，下使群臣皆失其职，岂不诚足患哉！”
公曰：“如是乎！寡人将去之。”
晏子曰：“公不能去也。”公忿然作色不说，曰：“夫子何小寡人甚也！”
对曰：“臣何敢槁也！夫能自周 于君者，才能皆非常也。夫藏大不诚于中者，必谨小诚于外 ，以成其大不诚，入则求君之嗜欲能顺之，公怨良臣，则具其往 失而益之，出则行威以取富。夫何密近，不为大利变，而务 与君至义者也？此难得其知也。”
公曰：“然则先圣柰何？ ”
对曰：“先圣之治也，审见宾客，听治不留，群臣皆得毕其诚 ，谗谀安得容其私！”
公曰：“然则夫子助寡人止之，寡人亦事 勿用。”
对曰：“谗夫佞人之在君侧者，若社之有鼠也，谚 言有之曰：‘社鼠不可熏去。’谗佞之人，隐君之威以自守也，是难去焉。”
景公问后世孰将践有齐者晏子对以田氏第十五
公与晏子立曲潢之上，望见齐国，问晏子曰：“后世孰将践有齐国者乎？”
晏子对曰：“非贱臣之所敢议也。”公曰：“胡必然也？得者无失，则虞、夏常存矣。”
晏子对曰：“臣闻见不足以知之者，智也；先言而后当者，惠也。夫智与惠，君子之事，臣奚足以知之乎！虽然，臣请陈其为政：君强臣弱，政之本也；君唱臣和，教之隆也；刑罚在君，民之纪也。今夫田无宇二世有功于国，而利取分寡，公室兼之，国权专之，君臣易施，能无衰乎！婴闻之，臣富主亡。由是观之，其无宇之后无几，齐国，田氏之国也？婴老不能待公之事，公若即世，政不在公室。”公曰：“然则柰何？”
晏子对曰：“维礼可以已之。其在礼也，家施不及国，民不懈，货不移，工贾不变，士不滥，官不谄，大夫不收公利。”公曰：“善。今知礼之可以为国也 。”
对曰：“礼之可以为国也久矣，与天地并立。君令臣忠，父慈子孝，兄爱弟敬，夫和妻柔，姑慈妇听，礼之经也。君令而不违，臣忠而不二，父慈而教，子孝而箴，兄爱而友，弟敬而顺，夫和而义，妻柔而贞，姑慈而从，妇听而婉，礼之质也。”公曰：“善哉！寡人乃今知礼之尚也。”
晏子曰：“夫礼，先王之所以临天下也，以为其民，是故尚之。”
晏子使吴吴王问君子之行晏子对以不与乱国俱灭第十六
晏子聘于吴，吴王问：“君子之行何如？”
晏子对曰：“君顺怀之，政治归之，不怀暴君之禄，不居乱国之位，君子见兆则退，不与乱国俱灭，不与暴君偕亡。”
吴王问齐君僈暴吾子何容焉晏子对以岂能以道食人第十七
晏子使吴，吴王曰：“寡人得寄僻陋蛮夷之乡，希见教君子之行，请私而无为罪。”晏子憱然辟位。
吴王曰：“吾闻齐君盖贼以僈，野以暴，吾子容焉，何甚也？”
晏子遵而对曰：“臣闻之，微事不通，粗事不能者，必劳；大事不得，小事不为者，必贫；大者不能致人，小者不能至人之门者，必困。此臣之所以仕也。如臣者，岂能以道食人者哉！”
晏子出，王笑曰：“嗟乎！今日吾讥晏子，訾犹裸而咎撅者也。”
司马子期问有不干君不恤民取名者乎晏子对以不仁也第十八
司马子期问晏子曰：“士亦有不干君，不恤民，徒居无为而取名者乎？”
晏子对曰：“婴闻之，能足以赡上益民而不为者，谓之不仁。不仁而取名者，婴未得闻之也。”
高子问子事灵公庄公景公皆敬子晏子对以一心第十九
高子问晏子曰：“子事灵公、庄公、景公，皆敬子，三君之心一耶？夫子之心三也？”
晏子对曰：“善哉！问事君，婴闻一心可以事百君，三心不可以事一君。故三君之心非一也，而婴之心非三心也。且婴之于灵公也，尽复而不能立之政，所谓仅全其四支以从其君者也。及庄公陈武夫，尚勇力，欲辟胜于邪，而婴不能禁，故退而野处。婴闻之，言不用者，不受其禄，不治其事者，不与其难，吾于庄公行之矣。今之君，轻国而重乐，薄于民而厚于养，藉敛过量，使令过任，而婴不能禁，庸知其能全身以事君乎！”
晏子再治东阿上计景公迎贺晏子辞第二十
晏子治东阿，三年，景公召而数之曰：“吾以子为可，而使子治东阿，今子治而乱，子退而自察也，寡人将加大诛于子。”
晏子对曰：“臣请改道易行而治东阿，三年不治，臣请死之。”景公许。于是明年上计，景公迎而贺之曰： “甚善矣！子之治东阿也。”
晏子对曰：“前臣之治东阿也，属托不行，货赂不至，陂池之鱼，以利贫民。当此之时，民无饥，君反以罪臣。今臣后之东阿也，属托行，货赂至，并重赋敛，仓库少内，便事左右，陂池之鱼，入于权宗。当此之时，饥者过半矣，君乃反迎而贺。臣愚不能复治东阿，愿乞骸骨，避贤者之路。”再拜，便僻。景公乃下席而谢之曰：“子彊复治东阿，东阿者，子之东阿也，寡人无复与焉。”
太卜绐景公能动地晏子知其妄使卜自晓公第二十一
公问太卜曰：“汝之道何能？”对曰：“臣能动地。”公召晏子而告之，曰：“寡人问太卜曰：‘汝之道何能？’对曰：‘能动地。’地可动乎？”晏子默然不对，出，见太卜曰：“昔吾见钩星在四心之闲，地其动乎？”太卜曰：“然。”晏子曰：“吾言之，恐子死之也；默然不对，恐君之惶也。子言，君臣俱得焉。忠于君者，岂必伤人哉！”晏子出，太卜走入见公，曰：“ 臣非能动地，地固将动也。”陈子阳闻之，曰：“晏子默而不对者，不欲太卜之死也；往见太卜者，恐君之惶也。晏子，仁人也，可谓忠上而惠下也。”
有献书谮晏子退耕而国不治复召晏子第二十二
晏子相景公，其论人也，见贤而进之，不同君所欲；见不善则废之，不辟君所爱；行己而无私，直言而无讳。
有纳书者曰：“废置不周于君前，谓之专；出言不讳于君前，谓之易。专易之行存，则君臣之道废矣，吾不知晏子之为忠臣也。”公以为然。
晏子入朝，公色不说，故晏子归，备载，使人辞曰： “婴故老悖无能，毋敢服壮者事。”辞而不为臣，退而穷处，东耕海滨，堂下生藜藿，门外生荆棘。七年，燕、鲁分争，百姓惛乱，而家无积。公自治国，权轻诸侯，身弱高、国。
公恐，复召晏子。晏子至，公一归七年之禄，而家无藏。晏子立，诸侯忌其威，高、国服其政，燕、鲁贡职，小国时朝。晏子没而后衰。
晏子使高纠治家三年而未尝弼过逐之第二十三
晏子使高纠治家，三年而辞焉。傧者谏曰：“高纠之事夫子三年，曾无以爵位而逐之，敢请其罪。”
晏子曰：“若夫方立之人，维圣人而已。如婴者，仄陋之人也。若夫左婴右婴之人不举，四维将不正。今此子事吾三年，未尝弼吾过也。吾是以辞之。”
景公称桓公之封管仲益晏子邑辞不受第二十四
公谓晏子曰：“昔吾先君桓公，予管仲狐与谷，其县十七，着之于帛，申之以策，通之诸侯，以为其子孙赏邑。寡人不足以辱而先君，今为夫子赏邑，通之子孙。”晏子辞曰：“昔圣王论功而赏贤，贤者得之，不肖者失之，御德修礼，无有荒怠。今事君而免于罪者，其子孙奚宜与焉？若为齐国大夫者必有赏邑，则齐君何以共其社稷与诸侯币帛？婴请辞。”遂不受。
景公使梁丘据致千金之裘晏子固辞不受第二十五
公赐晏子狐之白裘，元豹之茈，其赀千金，使梁丘据致之。晏子辞而不受，三反。公曰：“寡人有此二，将欲服之，今夫子不受，寡人不敢服。与其闭藏之，岂如弊之身乎？”
晏子曰：“君就赐，使婴修百官之政，君服之上，而使婴服之于下，不可以为教。”固辞而不受。
晏子衣鹿裘以朝景公嗟其贫晏子称有饰第二十六
晏子相景公，布衣鹿裘以朝。公曰：“夫子之家，若此其贫也，是奚衣之恶也！寡人不知，是寡人之罪也。 ”
晏子对曰：“婴闻之，盖顾人而后衣食者，不以贪昧为非；盖顾人而后行者，不以邪僻为累。婴不肖，婴之族又不如婴也，待婴以祀其先人者五百家，婴又得布衣鹿裘而朝，于婴不有饰乎！”再拜而辞。
仲尼称晏子行补三君而不有果君子也第二十七
仲尼曰：“灵公污，晏子事之以整齐；庄公壮，晏子事之以宣武；景公奢，晏子事之以恭俭：君子也！相三君而善不通下，晏子细人也。”
晏子闻之，见仲尼曰：“婴闻君子有讥于婴，是以来见。如婴者，岂能以道食人者哉！婴之宗族待婴而祀其先人者数百家，与齐国之闲士待婴而举火者数百家，臣为此仕者也。如臣者，岂能以道食人者哉！”晏子出，仲尼送之以宾客之礼，再拜其辱。反，命门弟子曰：“ 救民之姓而不夸，行补三君而不有，晏子果君子也。”', '', '', '', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9103048e64fbda97c1", "shortContent": "儿时常听老人们讲“灶王爷”的故事。据说他是每个家庭中常住的两个“神”之一（另一个是门神），家中的大事小事、好事歹事，灶王爷都一清二楚。每年阴历的腊月二十四，他就要上天去玉皇大帝那儿汇报，因此，每当“辞灶”的那一天，除了给灶王爷准备供品之外，还要特地准备下甜糕或麦芽糖，让他上天之后只拣好的说，或粘住了牙说不出什么来。那时对灶王爷充满了敬仰。稍大，便知道灶间那满面胡须、脸色漆黑的灶王爷的画像不过是出自...", "authors": ["陈建生"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f992e6a6b501f974bdb", "shortContent": "蒲松龄生于明崇祯十三年（1640），少年时代亲身经历过清朝初年的兵燹之祸。明清之际的王朝变革和清军的暴行在作者的思想中留下了深刻的烙印，他的《聊斋志异》有些篇章隐约而曲折地反映了清兵入关之后的掳掠屠杀和人民的深重灾难。《林四娘》即为其中之一。\n表面看来，《林四娘》写的是人鬼艳合而又惨然相别的故事。但由林四娘所言：“妾，衡府宫人也。遭难而死，十七年矣”；“谈及式微之际，则哽咽不能成语”。可知她并非一...", "authors": ["许金榜"], "pressName": "上海辞书出版社"}]', '', 'indent', 1545260568, '5c1a5dc1808ca40072cc48d8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640759, '周官辨非•天官', NULL, 6, 2, 1, 1, '万斯大', NULL, 24507, '5858f26a1b69e60056f67484', '清', 'wen', '文', '', '', '圣人之治天下，利民之事，丝发必兴；厉民之事，毫末必去。关市之赋，厉民之甚者也。周公制礼，其肯笔之于书以为常法哉？昔文王治岐，关市讥而不征。武王有天下，奉行不变。故周公作《无逸》以训成王曰：“文王不敢盘于游田，以庶邦惟正之供。”言无横敛也。复曰：“继自今嗣王，则其无淫于观、于逸、于游、于田，以万民惟正之供。”期其法祖而无横敛也。使赋及关市，宁非横敛乎？吾以是知《周官》非周公所作，决也！', '', '', '', NULL, '', 'indent', 1545264165, '5c1a6baf1579a3005f703e13', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640761, '伪古文尚书 · 周书 · 泰誓（中）', NULL, 3, 14, 1, 2, '王肃', NULL, 37087, '5e9aab01671c4f00082fea3d', '三国', 'wen', '文', '', '', '惟戊午，王次于河朔，群后以师毕会。王乃徇师而誓曰：“呜呼！西土有众，咸听朕言。我闻吉人为善，惟日不足。凶人为不善，亦惟日不足。今商王受，力行无度，播弃犁老，昵比罪人。淫酗肆虐，臣下化之，朋家作仇，胁权相灭。无辜吁天，秽德彰闻。惟天惠民，惟辟奉天。有夏桀弗克若天，流毒下国。天乃佑命成汤，降黜夏命。惟受罪浮于桀。剥丧元良，贼虐谏辅。谓己有天命，谓敬不足行，谓祭无益，谓暴无伤。厥监惟不远，在彼夏王。天其以予乂民，朕梦协朕卜，袭于休祥，戎商必克。受有亿兆夷人，离心离德。予有乱臣十人，同心同德。虽有周亲，不如仁人。天视自我民视，天听自我民听。百姓有过，在予一人，今朕必往。我武维扬，侵于之疆，取彼凶残。我伐用张，于汤有光。勖哉夫子！罔或无畏，宁执非敌。百姓懔懔，若崩厥角。呜呼！乃一德一心，立定厥功，惟克永世。”', '', '', '', NULL, '', 'indent', 1545265494, '5c1a71009f54540474a3ee25', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640763, '说苑·政理', NULL, 386, 49, 2, 1, '刘向', NULL, 18105, '58540cde8e450a006c5803d4', '汉', 'wen', '文', '', '', '政有三品：王者之政化之，霸者之政威之，强者之政胁之，夫此三者各有所施，而化之为贵矣。夫化之不变而后威之，威之不变而后胁之，胁之不变而后刑之；夫至于刑者，则非王者之所得已也。是以圣王先德教而后刑罚，立荣耻而明防禁；崇礼义之节以示之，贱货利之弊以变之；修近理内政橛机之礼，壹妃匹之际；则莫不慕义礼之荣，而恶贪乱之耻。其所由致之者，化使然也。
季孙问于孔子曰：「如杀无道，以就有道，何如？」孔子曰：「
子为政，焉用杀，子欲善而民善矣。君子之德，风也；小人之德，草也；草上之风必偃。」言明其化而已矣，治国有二机，刑德是也；王者尚其德而布其刑，霸者刑德并凑，强国先其刑而后德。夫刑德者，化之所由兴也。德者，养善而进阙者也；刑者，惩恶而禁后者也；故德化之崇者至于赏，刑罚之甚者至于诛；夫诛赏者，所以别贤不肖，而列有功与无功也。故诛赏不可以缪，诛赏缪则善恶乱矣。夫有功而不赏，则善不劝，有过而不诛，则恶不惧，善不劝而能以行化乎天下者，未尝闻也。书曰：『毕协赏罚』，此之谓也。
水浊则鱼困，令苛则民乱，城峭则必崩，岸竦则必陁。故夫治国，譬若张琴，大弦急则小弦绝矣，故曰急辔御者非千里御也。有声之声，不过百里，无声之声，延及四海；故禄过其功者损，名过其实者削，情行合而民副之，祸福不虚至矣。诗云：「何其处也，必有与也；何其久也，必有以也。」此之谓也。
公叔文子为楚令尹三年，民无敢入朝，公叔子见曰：「严矣。」文子曰：「朝廷之严也，宁云妨国家之治哉？」公叔子曰：「严则下喑，下喑则上聋，聋喑不能相通，何国之治也？顺针缕者成帷幕，合升斗者实仓廪，并小流而成江海；明主者有所受命而不行，未尝有所不受也。」
卫灵公谓孔子曰：「有语寡人为国家者，谨之于庙堂之上而国家治矣，其可乎？」孔子曰：「可。爱人者，则人爱之；恶人者，则人恶之；知得之己者，亦知得之人；所谓不出于环堵之室而知天下者，知反之己者也。」
子贡问治民于孔子，孔子曰：「懔懔焉如以腐索御奔马。」子贡曰：「何其畏也！」孔子曰：「夫通达之国皆人也，以道导之，则吾畜也；不以道导之，则吾雠也，若何而毋畏？」
齐桓公谓管仲曰：「吾欲举事于国，昭然如日月，无愚夫愚妇皆曰善，可乎？」仲曰：「可。然非圣人之道。」桓公曰：「何也？」对曰：「夫短绠不可以汲深井，知鲜不可以与圣人言，慧士可与辨物，智士可与辨无方，圣人可与辨神明；夫圣人之所为，非众人之所及也。民知十己，则尚与之争，曰不如吾也，百己则疵其过，千己则谁而不信。是故民不可稍而掌也，可并而牧也；不可暴而杀也，可麾而致也；众不可户说也，可举而示也。」
卫灵公问于史曰：「政孰为务？」对曰：「大理为务，听狱不中，死者不可生也，断者不可属也，故曰：大理为务。」少焉，子路见公，公以史言告之，子路曰：「司马为务，两国有难，两军相当，司马执枹以行之，一斗不当，死者数万，以杀人为非也，此其为杀人亦众矣，故曰：司马为务。」少焉，子贡入见，公以二子言告之，子贡曰：「不识哉！昔禹与有扈氏战，三陈而不服，禹于是修教一年而有扈氏请服，故曰：去民之所事，奚狱之所听？兵革之不陈，奚鼓之所鸣？故曰：教为务也。」
齐桓公出猎，逐鹿而走入山谷之中，见一老公而问之曰：「是为何谷？」对曰：「为愚公之谷。」桓公曰：「何故？」对曰：「以臣名之。」桓公曰：「今视公之仪状，非愚人也，何为以公名？」对曰：「臣请陈之，臣故畜牛生子而大，卖之而买驹，少年曰：『牛不能生马。』遂持驹去。傍邻闻之，以臣为愚，故名此谷为愚公之谷。」桓公曰：「公诚愚矣，夫何为而与之？」桓公遂归。明日朝，以告管仲，管仲正衿再拜曰：「此夷吾之愚也，使尧在上，咎繇为理，安有取人之驹者乎？若有见暴如是叟者，又必不与也，公知狱讼之不正，故与之耳，请退而修政。」孔子曰：「弟子记之，桓公，霸君也；管仲，贤佐也；犹有以智为愚者也，况不及桓公管仲者也。」
鲁有父子讼者，康子曰：「杀之！」孔子曰：「未可杀也。夫民不知子父讼之不善者久矣，是则上过也；上有道，是人亡矣。」康子曰：「夫治民以孝为本，今杀一人以戮不孝，不亦可乎？」孔子曰：「不孝而诛之，是虐杀不辜也。三军大败，不可诛也；狱讼不治，不可刑也；上陈之教而先服之，则百姓从风矣，躬行不从而后俟之以刑，则民知罪矣；夫一仞之墙，民不能逾，百仞之山，童子升而游焉，陵迟故也！今是仁义之陵迟久矣，能谓民弗逾乎？诗曰：『俾民不迷！』昔者君子导其百姓不使迷，是以威厉而不至，刑错而不用。」于是讼者闻之，乃请无讼。
鲁哀公问政于孔子，对曰：「政有使民富且寿。」哀公曰：「何谓也？」孔子曰：「薄赋敛则民富，无事则远罪，远罪则民寿。」公曰：「若是则寡人贫矣。」孔子曰：「诗云：『凯悌君子，民之父母』，未见其子富而父母贫者也。」
文王问于吕望曰：「为天下若何？」对曰：「王国富民，霸国富士；仅存之国，富大夫；亡道之国，富仓府；是谓上溢而下漏。」文王曰：「善！」对曰：「宿善不祥。是日也，发其仓府，以赈鳏、寡、孤、独。」
武王问于太公曰：「治国之道若何？」太公对曰：「治国之道，爱民而已。」曰：「爱民若何？」曰：「利之而勿害，成之勿败，生之勿杀，与之勿夺，乐之勿苦，喜之勿怒，此治国之道，使民之谊也，爱之而已矣。民失其所务，则害之也；农失其时，则败之也；有罪者重其罚，则杀之也；重赋敛者，则夺之也；多徭役以罢民力，则苦之也；劳而扰之，则怒之也。故善为国者遇民，如父母之爱子，兄之爱弟，闻其饥寒为之哀，见其劳苦为之悲。」
武王问于太公曰：「贤君治国何如？」对曰：「贤君之治国，其政平，其吏不苛，其赋敛节，其自奉薄，不以私善害公法，赏赐不加于无功，刑罚不施于无罪，不因喜以赏，不因怒以诛，害民者有罪，进贤举过者有赏，后宫不荒，女谒不听，上无淫慝，下不阴害，不幸宫室以费财，不多观游台池以罢民，不雕文刻镂以逞耳目，宫无腐蠹之藏，国无流饿之民，此贤君之治国也。」武王曰：「善哉！」
武王问于太公曰：「为国而数更法令者何也？」太公曰：「为国而数更法令者，不法法，以其所善为法者也；故令出而乱，乱则更为法，是以其法令数更也。」
成王问政于尹逸曰：「吾何德之行而民亲其上？」对曰：「使之以时而敬顺之，忠而爱之，布令信而不食言。」王曰：「其度安至？」对曰：「如临深渊，如履薄冰。」王曰：「惧哉！」对曰：「天地之间，四海之内，善之则畜之，不善则雠也；夏、殷之臣，反雠桀、纣而臣汤、武，夙沙之民，自攻其主而归神农氏。此君之所明知也，若何其无惧也？」
仲尼见梁君，梁君问仲尼曰：「吾欲长有国，吾欲列都之得，吾欲使民安不惑，吾欲使士竭其力，吾欲使日月当时，吾欲使圣人自来，吾欲使官府治，为之奈何？」仲尼对曰：「千乘之君，万乘之主，问于丘者多矣，未尝有如主君问丘之术也，然而尽可得也。丘闻之，两君相亲，则长有国；君惠臣忠，则列都之得；毋杀不辜，毋释罪人，则民不惑；益士禄赏，则竭其力；尊天敬鬼，则日月当时；善为刑罚，则圣人自来；尚贤使能，则官治。」梁君曰：「岂有不然哉！」
子贡曰：「叶公问政于夫子，夫子曰：『政在附近来远』，鲁哀公问政于夫子，夫子曰：『政在于谕臣』。齐景公问政于夫子，夫子曰：『政在于节用』。三君问政于夫子，夫子应之不同，然则政有异乎？」孔子曰：「夫荆之地广而都狭，民有离志焉，故曰在于附近而来远。哀公有臣三人，内比周公以惑其君，外障诸侯宾客以蔽其明，故曰政在谕臣。齐景公奢于台榭，淫于苑囿，五官之乐不解，一旦而赐人百乘之家者三，故曰政在于节用，此三者政也，诗不云乎：『乱离斯瘼，爰其适归』，此伤离散以为乱者也，『匪其止共，惟王之邛』，此伤奸臣蔽主以为乱者也，『相乱蔑资，鲁莫惠我师』，此伤奢侈不节以为乱者也，察此三者之所欲，政其同乎哉！」
公仪休相鲁，鲁君死，左右请闭门，公仪休曰：「止！池渊吾不税，蒙山吾不赋，苛令吾不布，吾已闭心矣！何闭于门哉？」
子产相郑，简公谓子产曰：「内政毋出，外政毋入。夫衣裘之不美，车马之不饰，子女之不洁，寡人之丑也；国家之不治，封疆之不正，夫子之丑也。」子产相郑，终简公之身，内无国中之乱，外无诸侯之患也；子产之从政也，择能而使之：冯简子善断事，子太叔善决而文，公孙挥知四国之为而辨于其大夫之族姓，变而立至，又善为辞令，裨谌善谋，于野则获，于邑则否，有事乃载裨谌与之适野，使谋可否，而告冯简子断之，使公孙挥为之辞令，成乃受子太叔行之，以应对宾客，是以鲜有败事也。
董安于治晋阳，问政于蹇老，蹇老曰：「曰忠、曰信、曰敢。」董安于曰：「安忠乎？」曰：「忠于主。」曰：「安信乎？」曰：「信于令。」曰：「安敢乎？」曰：「敢于不善人。」董安于曰：「此三者足矣。」
魏文侯使西门豹往治于邺，告之曰：「必全功成名布义。」豹曰：「敢问全功成名布义为之奈何？」文侯曰：「子往矣！是无邑不有贤豪辨博者也，无邑不有好扬人之恶，蔽人之善者也。往必问豪贤者，因而亲之；其辨博者，因而师之；问其好扬人之恶，蔽人之善者，因而察之，不可以特闻从事。夫耳闻之不如目见之，目见之不如足践之，足践之不如手辨之；人始入官，如入晦室，久而愈明，明乃治，治乃行。」
宓子贱治单父，弹鸣琴，身不下堂而单父治。巫马期亦治单父，以星出，以星入，日夜不出，以身亲之，而单父亦治。巫马期问其故于宓子贱，宓子贱曰：「我之谓任人，子之谓任力；任力者固劳，任人者固佚。」人曰宓子贱，则君子矣，佚四肢，全耳目，平心气而百官治，任其数而已矣。巫马期则不然，弊性事情，劳烦教诏，虽治犹未至也。
孔子谓宓子贱曰：「子治单父而众说，语丘所以为之者。」曰：「不齐父其父，子其子，恤诸孤而哀丧纪。」孔子曰：「善小节也小民附矣，犹未足也。」曰：「不齐也，所父事者三人，所兄事者五人，所友者十一人，」孔子曰：「父事三人，可以教孝矣；兄事五人，可以教弟矣；友十一人，可以教学矣。中节也，中民附矣，犹未足也。」曰：「此地民有贤于不齐者五人，不齐事之，皆教不齐所以治之术。」孔子曰：「欲其大者，乃于此在矣。昔者尧、舜清微其身，以听观天下，务来贤人，夫举贤者，百福之宗也，而神明之主也，不齐之所治者小也，不齐所治者大，其与尧、舜继矣。」
宓子贱为单父宰，辞于夫子，夫子曰：「毋迎而距也，毋望而许也；许之则失守，距之则闭塞。譬如高山深渊，仰之不可极，度之不可测也。」子贱曰：「善，敢不承命乎！」宓子贱为单父宰，过于阳昼曰：「子亦有以送仆乎？」阳昼曰：「吾少也贱，不知治民之术，有钓道二焉，请以送子。」子贱曰：「钓道奈何？」阳昼曰：「夫扱纶错饵，迎而吸之者也，阳桥也，其为鱼薄而不美；若存若亡，若食若不食者，鲂也，其为鱼也博而厚味。」宓子贱曰：「善。」于是未至单父，冠盖迎之者交接于道，子贱曰：「车驱之，车驱之。」夫阳昼之所谓阳桥者至矣，于是至单父请其耆老尊贤者而与之共治单父。
孔子弟子有孔蔑者，与宓子贱皆仕，孔子往过孔蔑，问之曰：「自子之仕者，何得、何亡？」孔蔑曰：「自吾仕者未有所得，而有所亡者三，曰：王事若袭，学焉得习，以是学不得明也，所亡者一也。奉禄少鬻，鬻不足及亲戚，亲戚益疏矣，所亡者二也。公事多急，不得吊死视病，是以朋友益疏矣，所亡者三也。」孔子不说，而复往见子贱曰：「自子之仕，何得、何亡也？」子贱曰：「自吾之仕，未有所亡而所得者三：始诵之文，今履而行之，是学日益明也，所得者一也。奉禄虽少鬻，鬻得及亲戚，是以亲戚益亲也，所得者二也。公事虽急，夜勤，吊死视病，是以朋友益亲也，所得者三也。」孔子谓子贱曰：「君子哉若人！君子哉若人！鲁无君子也，斯焉取斯？」
晏子治东阿三年，景公召而数之曰：「吾以子为可，而使子治东阿，今子治而乱，子退而自察也，寡人将加大诛于子。」晏子对曰：「臣请改道易行而治东阿，三年不治，臣请死之。」景公许之。于是明年上计，景公迎而贺之曰：「甚善矣！子之治东阿也。」晏子对曰：「前臣之治东阿也，属托行，货赂至，并会赋敛，仓库少内，便事左右，陂池之鱼，入于权家。当此之时，饥者过半矣，君乃反迎而贺臣，愚不能复治东阿，愿乞骸骨，避贤者之路，再拜便辟。」景公乃下席而谢之曰：「子强复治东阿；东阿者，子之东阿也，寡人无复与焉。」
子路治蒲，见于孔子曰：「由愿受教。」孔子曰：「蒲多壮士，又难治也。然吾语汝，恭以敬，可以摄勇；宽以正，可以容众；恭以洁，可以亲上。」
子贡为信阳令，辞孔子而行，孔子曰：「力之顺之，因子之时，无夺无伐，无暴无盗。」子贡曰：「赐少日事君子，君子固有盗者邪！」孔子曰：「夫以不肖伐贤，是谓夺也；以贤伐不肖，是谓伐也；缓其令，急其诛，是谓暴也；取人善以自为己，是谓盗也。君子之盗，岂必当财币乎？吾闻之曰：知为吏者奉法利民，不知为吏者，枉法以侵民，此皆怨之所由生也。临官莫如平，临财莫如廉，廉平之守，不可攻也。匿人之善者，是谓蔽贤也；扬人之恶者，是谓小人也；不内相教而外相谤者，是谓不足亲也。言人之善者，有所得而无所伤也；言人之恶者，无所得而有所伤也。故君子慎言语矣，毋先己而后人，择言出之，令口如耳。」
杨朱见梁王，言治天下如运诸掌然，梁王曰：「先生有一妻一妾不能治，三亩之园不能芸，言治天下如运诸手掌何以？」杨朱曰：「臣有之，君不见夫羊乎，百羊而群，使五尺童子荷杖而随之，欲东而东，欲西而西；君且使尧牵一羊，舜荷杖而随之，则乱之始也。臣闻之，夫吞舟之鱼不游渊，鸿鹄高飞不就污池，何则？其志极远也。黄钟大吕，不可从繁奏之舞，何则？其音疏也。将治大者不治小，成大功者不小苛，此之谓也。」
景差相郑，郑人有冬涉水者，出而胫寒，后景差过之，下陪乘而载之，覆以上衽，晋叔向闻之曰：「景子为人国相，岂不固哉！吾闻良吏居之三月而沟渠修，十月而津梁成，六畜且不濡足，而况人乎？」
魏文侯问李克曰：「为国如何？」对曰：「臣闻为国之道，食有劳而禄有功，使有能而赏必行，罚必当。」文侯曰：「吾尝罚皆当，而民不与，何也？」对曰：「国其有淫民乎？臣闻之曰：夺淫民之禄以来四方之士；其父有功而禄，其子无功而食之，出则乘车马衣美裘以为荣华，入则修竽琴、钟石之声而安其子女之乐，以乱乡曲之教，如此者夺其禄以来四方之士，此之谓夺淫民也。」
齐桓公问管仲曰：「国何患？」管仲对曰：「患失社鼠。」桓公曰：「何谓也？」管仲对曰：「夫社束木而涂之，鼠因往托焉，熏之则恐烧其木，灌之则恐败其涂，此鼠所以不可得杀者，以社故也。夫国亦有社鼠，人主左右是也；内则蔽善恶于君上，外则卖权重于百姓，不诛之则为乱，诛之则为人主所察，据腹而有之，此亦国之社鼠也。人有酤酒者，为器甚洁清，置表甚长而酒酸不售，问之里人其故，里人云：『公之狗猛，人挈器而入，且酤公酒，狗迎而噬之，此酒所以酸不售之故也。』夫国亦有猛狗，用事者也；有道术之士，欲明万乘之主，而用事者迎而龁之，此亦国之猛狗也。左右为社鼠，用事者为猛狗，则道术之士不得用矣，此治国之所患也。」
齐侯问于晏子曰：「为政何患？」对曰：「患善恶之不分。」公曰：「何以察之？」对曰：「审择左右，左右善，则百僚各得其所宜而善恶分。」孔子闻之曰：「此言也信矣，善言进，则不善无由入矣；不进善言，则善无由入矣。」
复槁之君朝齐，桓公问治民焉，复槁之君不对，而循口操衿抑心，桓公曰：「与民共甘苦饥寒乎？」「夫以我为圣人也，故不用言而谕。」因礼之千金。晋文公时，翟人有封狐、文豹之皮者，文公喟然叹曰：「封狐文豹何罪哉？以其皮为罪也。」大夫栾枝曰：「地广而不平，财聚而不散，独非狐豹之罪乎？」文公曰：「善哉！说之。」栾枝曰：「地广而不平，人将平之；财聚而不散，人将争之。」于是列地以分民，散财以赈贫。
晋文侯问政于舅犯，舅犯对曰：「分熟不如分腥，分腥不如分地；割以分民而益其爵禄，是以上得地而民知富，上失地而民知贫，古之所谓致师而战者，其此之谓也。」
晋侯问于士文伯曰：「三月朔，日有蚀之，寡人学惛焉，诗所谓：『彼日而蚀，于何不臧』者，何也？」对曰：「不善政之谓也；国无政不用善，则自取谪于日月之灾，故不可不慎也。政有三而已：一曰因民，二曰择人，三曰从时。」
延陵季子游于晋，入其境曰：「嘻，暴哉国乎！」入其都曰：「嘻，力屈哉，国乎！」立其朝曰：「嘻，乱哉国乎！」从者曰：「夫子之入境未久也，何其名之不疑也？」延陵季子曰：「然，吾入其境田亩荒秽而不休，杂增崇高，吾是以知其国之暴也。吾入其都，新室恶而故室美，新墙卑而故墙高，吾是以知其民力之屈也。吾立其朝，君能视而不下问，其臣善伐而不上谏，吾是以知其国之乱也。齐之所以不如鲁者，太公之贤不如伯禽，伯禽与太公俱受封，而各之国三年，太公来朝，周公问曰：「何治之疾也？」对曰：「尊贤，先疏后亲，先义后仁也。」此霸者之迹也。周公曰：「太公之泽及五世。」五年伯禽来朝，周公问曰：「何治之难？」对曰：「亲亲者，先内后外，先仁后义也。」此王者之迹也。周公曰：「鲁之泽及十世。」故鲁有王迹者，仁厚也；齐有霸迹者，武政也；齐之所以不如鲁也，太公之贤不如伯禽也。
景公好妇人而丈夫饰者，国人尽服之，公使吏禁之曰：「女子而男子饰者，裂其衣，断其带。」裂衣断带相望而不止，晏子见，公曰：「寡人使吏禁女子而男子饰者，裂其衣，断其带，相望而不止者，何也？」对曰：「君使服之于内而禁之于外，犹悬牛首于门而求买马肉也；公胡不使内勿服，则外莫敢为也。」公曰：「善！」使内勿服，不旋月而国莫之服也。
齐人甚好毂击相犯以为乐，禁之不止，晏子患之，乃为新车良马出与人相犯也，曰：「毂击者不祥，臣其察祀不顺，居处不敬乎？」下车弃而去之，然后国人乃不为。故曰：「禁之以制，而身不先行也，民不肯止，故化其心莫若教也。」
鲁国之法，鲁人有赎臣妾于诸侯者，取金于府；子贡赎人于诸侯而还其金，孔子闻之曰：「赐失之矣，圣人之举事也，可以移风易俗，而教导可施于百姓，非独适其身之行也。今鲁国富者寡而贫者众，赎而受金则为不廉；不受则后莫复赎，自今以来，鲁人不复赎矣。」孔子可谓通于化矣。故老子曰：「见小曰明。」
孔子见季康子，康子未说，孔子又见之，宰予曰：「吾闻之夫子曰：『王公不聘不动。』今吾子之见司寇也少数矣。」孔子曰：「鲁国以众相陵，以兵相暴之日久矣，而有司不治，聘我者孰大乎？」于是鲁人闻之曰：「圣人将治，何以不先自为刑罚乎？」自是之后，国无争者。孔子谓弟子曰：「违山十里，蟪蛄之声犹尚存耳，政事无如膺之矣。」古之鲁俗，涂里之间，罗门之罗，收门之鱼，独得于礼，是以孔子善之夫涂里之间，富家为贫者出；罗门之罗，有亲者取多，无亲者取少；收门之渔，有亲者取巨，无亲者取小。
春秋曰：四民均则王道兴而百姓宁；所谓四民者，士、农、工、商也。婚姻之道废，则男女之道悖，而淫逸之路兴矣。', '西汉经学家刘向在《说苑·政理》中讲述了这样一个故事：周武王向姜太公询问治国方法，太公答道：「治国之道，爱民而已。」接着，二人就爱民方式方法问题进行了深入探讨。最后太公总结道：「善为国者，遇民如父母之爱子，兄之爱弟，闻其饥寒为之哀，见其劳苦为之悲。」为国：治理国家；遇：对待。意思是说，善于治理国家的人，对待百姓就像父母爱护子女、兄长爱护弟弟一样，听到他们挨冻受饿就感到哀伤，看到他们劳苦不堪就感到悲痛。
其实，《说苑》这段话应来自《太公六韬·文韬·国务》，不过却是姜太公对周文王说的。太公原话为:「善为国者，驭民如父母之爱子，如兄之爱弟，见其饥寒则为之忧，见其劳苦则为之悲。」刘向将「驭」字易为「遇」，一字之改见深意。
治国理政，本是件大事，也是件难事。但治国者若能抓住根本，便可垂拱而治。这个根本就是「爱民」二字，因为治国就是治人。提倡爱民是刘向民本思想的主要内容，对此，他在《新序·杂事一》中还有进一步阐述：「良君将赏善而除民患，爱民如子，盖之如天，容之若地。」主张治国者应像天地一样庇护包容他的子民。这就是成语「爱民如子」的由来。', '', '', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d3dbb8b379ee0a148d", "shortContent": "本文是《吕氏春秋·孟春纪》中的第五篇，第四篇是《贵公》，两篇可视为姊妹篇。\n私是与公相对来说的。私的本字作“厶”，《韩非子·五蠹》说：“古者苍颉之作书也，自环者谓之私，背私谓之公。”《说文》引作“自营为厶”。可知私就是为自己打算，包括私利、私欲、私心、私念。去私就是要去掉一切私心私念，摒弃一切谋取私利、满足私欲的行为，而要求事事“出以公心”。题目“去私”就是全文的中心论点。\n与《吕氏春秋》其他篇相...", "authors": ["张葆全"], "pressName": "上海辞书出版社"}]', '', 'indent', 1545265986, '5c1a7273fb4ffe0069e96ddc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640764, '治国第四十八', NULL, 6, 49, 1, 1, '刘向', NULL, 18105, '58540cde8e450a006c5803d4', '汉', 'wen', '文', '', '', '凡治国之道，必先富民。民富则易治也，民贫则难治也。奚以知其然也？民富则安乡重家，安乡重家则敬上畏罪，敬上畏罪则易治也。民贫则危乡轻家，危乡轻家则敢凌上犯禁，凌上犯禁则难治也。故治国常富，而乱国常贫。是以善为国者，必先富民，然后治之。
昔者，七十九代之君，法制不一，号令不同，然俱王天下者，何也？必国富而粟多也。夫富国多粟生于农，故先王贵之。凡为国之急者，必先禁末作文巧，末作文巧禁则民无所游食，民无所游食则必农。民事农则田垦，田垦则粟多，粟多则国富。国富者兵强，兵强者战胜，战胜者地广。是以先王知众民、强兵、广地、富国之必生于粟也，故禁末作，止奇巧，而利农事。今为末作奇巧者，一日作而五日食。农夫终岁之作，不足以自食也。然则民舍本事而事末作。舍本事而事末作，则田荒而国贫矣。

凡农者月不足而岁有余者也，而上征暴急无时，则民倍贷以给上之征矣。耕耨者有时，而泽不必足，则民倍贷以取庸矣。秋籴以五，春粜以束，是又倍贷也。故以上之证而倍取于民者四，关市之租，府库之征粟十一，厮舆之事，此四时亦当一倍贷矣。夫以一民养四主，故逃徙者刑而上不能止者，粟少而民无积也。

嵩山之东，河汝之间，蚤生而晚杀，五谷之所蕃孰也，四种而五获。中年亩二石，一夫为粟二百石。今也仓廪虚而民无积，农夫以粥子者，上无术以均之也。故先王使农、士、商、工四民交能易作，终岁之利无道相过也。是以民作一而得均。民作一则田垦，奸巧不生。田垦则粟多，粟多则国富。奸巧不生则民治。富而治，此王之道也。

不生粟之国亡，粟生而死者霸，粟生而不死者王。粟也者，民之所归也；粟也者，财之所归也；粟也者，地之所归也。粟多则天下之物尽至矣。故舜一徙成邑，二徙成都，参徙成国。舜非严刑罚重禁令，而民归之矣，去者必害，从者必利也。先王者善为民除害兴利，故天下之民归之。所谓兴利者，利农事也；所谓除害者，禁害农事也。农事胜则入粟多，入粟多则国富，国富则安乡重家，安乡重家则虽变俗易习、驱众移民，至于杀之，而民不恶也。此务粟之功也。上不利农则粟少，粟少则人贫，人贫则轻家，轻家则易去、易去则上令不能必行，上令不能必行则禁不能必止，禁不能必止则战不必胜、守不必固矣。夫令不必行，禁不必止，战不必胜，守不必固，命之曰寄生之君。此由不利农少粟之害也。粟者，王之本事也，人主之大务，有人之涂，治国之道也。', '', '', '大凡治国的道理，一定要先使人民富裕，人民富裕就容易治理，人民贫穷就难以治理。何以知其然？人民富裕就安于乡居而爱惜家园，安乡爱家就恭敬君上而畏惧刑罪，敬上畏罪就容易治理了。人民贫穷就不安于乡居而轻视家园，不安于乡居而轻家就敢于对抗君上而违犯禁令，抗上犯禁就难以治理了。所以，治理得好的国家往往是富的，乱国必然是穷的。因此，善于主持国家的君主，一定要先使人民富裕起来，然后再加以治理。

从前，历代的君主，法度不一，号令不同，然而都能统一天下，这是什么原因呢？必定是国富而粮多的缘故。国富粮多来源于农业，所以先代圣王都是重视农业的。凡属于治国之急务，一定要先禁止奢侈性的工商业和奢侈品的制造，禁止了这些，人民便无法游荡求食，人民无法游荡求食，就只好从事农业。人民从事农业则土地得到开垦，土地开垦则粮食增加，粮食增加则国家富裕，国富则兵力可以强大，兵强则战争可以取胜，战胜则土地也就广阔了。因此，先代圣王懂得人口多、兵力强、国土广和国家富都一定来源于粮食，因而都禁止奢侈性的工商业和奢侈品的制作，以利于发展农业。现今从事奢侈性的工商业和奢侈品制作的人们，干一天可以吃用五天。农民终年劳动，却不能维持自家生活。这样，人民就放弃农业而从事奢侈性的工商业。弃农而从事奢侈性的工商业，那土地也就荒芜而国家贫穷了。

凡是农业，其收入的特点是按月算往往不足，按年算才可能有余。然而，官府征税却急如星火，没有定时，农民只好借“一还二”的高利贷来应付上面征课。耕田锄草都有季节限制，但雨水不一定及时够用，农民又只好借“一还二”的高利贷来雇人浇地。商人秋天买粮的粮价是“五”，春天卖粮的粮价是“十”，这又是一项“一还二”的高利贷。所以，把上面的征索算进来，成倍索取农民的地方就达到四项，因为关市的租税、府库的征收、十分之一的征粮和各种劳役放在一起。—年四季加起来，也等于一项“一还二”的高利贷了。—个农民要养四个债主，所以对于外逃者处刑，国君也能制止农民外流，这乃是粮少而农民没有积蓄的缘故。  

从高山东麓到黄河、汝水之间。作物生长期早，凋落期迟，是粮食增产的好地方。四季皆种而五谷皆收。中等年成亩产两石粮食。一个劳力可以耕百亩收二百石。如今国家粮仓空虚而百姓没有积存。农民卖儿卖女，其原因就在于君主没有办法均衡人们的收入。所以先代圣王总是注意让农、士、商、工四民即使互换其行业，他们每年的收入也无法互相超过。这样，农民专—务农而收入可以与其他各业均衡。农民专一务农田野就得到开垦，奸巧之事也不会发生。田野开垦则粮食增多，粮食多则国家富裕。没有奸巧之事人民又会安定。富裕而安定，这正是成王业的道路。

不生产粮食的国家要灭亡，生产粮食而吃光用尽的国家仅能称霸，生产粮食而又能食用不尽的国家才可以成其王业。粮食，能吸引人民；粮食，能招引财富；粮食，也能使领土开拓。粮食一多，则天下的物产都来了。所以，舜第一次率民迁安发展农耕建成“邑”，第二次迁徒建成“都”，第三次迁徒建成“国”。舜没有采用严重的刑罚和禁令，而人民都跟定他了。因为离开他必然受害，跟着他必然有利。先代圣王，正是善于为人民除害兴利，所以天下人民都归附他。所谓兴利，就是有利于农业。所谓除害，就是禁害于农业。农业发展则粮食收入增多，粮食收入增多则国富，国富则人民安于乡居而爱惜家园，安乡爱家则虽改变他们的风俗和习惯，对他们驱使和调遣，以至于有所杀戮，人民都是不憎恶的。这都是致力于粮食生产的功效。人君不发展农业则粮食必少，粮少则人民贫困，贫困则轻视家园，轻家则容易外逃，人民轻易外逃则君令不能做到“必行”，君令不能行则禁律也不能做到“必止”，禁律不能必止则战争不能做到必胜，防守也不能做到必固了。法令不能必行。禁律不能必止，出战不能必胜，防守不能必固，这叫作寄生的君主。这都是不发展农业缺少粮食的危害。所以增产粮食乃是成王业的根本大事，是人君的重大任务，是招引民众的途径和治国的道路。', NULL, '', 'indent', 1545266677, '5c1a758c44d904005fc571da', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640765, '申鉴·政体第一', NULL, 18, 3, 1, 2, '荀悦', NULL, 36978, '5c1a7693303f39005f23dcde', '汉', 'wen', '文', '', '', '自天子达于庶人，好恶哀乐，其修一也，丰约劳佚，各有其制。上足以备礼，下足以备乐，夫是谓大道。天下国家一体也，君为元首，臣为股肱，民为手足。下有忧民，则上不尽乐；下有饥民，则上不备膳；下有寒民，则上不具服。徒跣而垂旒，非礼也。故足寒伤心，民寒伤国。', '', '', '', NULL, '', 'indent', 1545266993, '5c1a76d167f35600660fb42a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640766, '晋宣帝总论', NULL, 18, 119, 1, 1, '李世民', NULL, 10478, '5858e5968e450a006c7f7a6b', '唐', 'wen', '文', '', '', '制曰：夫天地之大，黎元为本；邦国之贵，元首为先。治乱无常，兴亡有运。', '', '', '', NULL, '', 'indent', 1545267161, '5c1a77651579a3005f70a2ab', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640767, '二程语录（节选）', NULL, 46, 4, 1, 1, '张伯行', NULL, 23414, '5858f143570c35006917f917', '清', 'wen', '文', '', '', '君子之学必日新，日新者日进也。不日新者必日退，未有不进而不退者。', '', '', '', NULL, '', 'indent', 1545309254, '5c1b1bd5808ca40073276f50', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640768, '藏书·世纪列传总目前论（节选）', NULL, 20, 155, 1, 1, '李贽', NULL, 15269, '583eb11ea22b9d006ddd71de', '明', 'wen', '文', '', '', '夫是非之争也，如岁时然，昼夜更迭，不相一也。昨日是而今日非矣，今日非而后日又是矣。虽使孔夫子复生于今，又不知作如何非是也，而可遽以定本行罚赏哉！', '', '', '', NULL, '', 'indent', 1545309563, '5c1b1d2567f356005fc80850', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640769, '官箴', NULL, 12, 1366, 1, 1, '吕本中', NULL, 10269, '57bd3b77d342d3006bf88ba8', '宋', 'wen', '文', '', '', '当官之法唯有三事：曰清、曰慎、曰勤。知此三者，可以保禄位，可以远耻辱，可以得上之知，可以得下之援。然世之仕者，临财当事不能自克，常自以为不必败，持不必败之意，则无所不为矣。然事常至于败而不能自已，故设心处事，戒之在初，不可不察。借使役，用权智，百端补治，幸而得免，所损已多，不若初不为之为愈也。司马微《坐忘论》云：“与其巧持于末，孰若拙戒于初。”此天下之要言，当官处事之大法，用力简而见功多，无如此言者。人能思之，岂复有悔吝耶？
事君如事亲，事官长如兄长，与同僚如家人，待群吏如奴仆，爱百姓如妻子，处官事如家事，然后为能尽吾之心。如有毫末不至，皆吾心有所未至也。故事亲孝，故忠可移于君；事兄悌，故顺可移于长；居家理，故治可移于官。岂有二理哉！
当官处事，常思有以及人。如科率之行，既不能免，便就其间，求其所以使民省力，不使重为民害，其益我矣。不与人争者，常得利多；退一步者，常进百步；取之廉者，得之常过其初；约于今者，必有垂报于后，不可不思也。惟不能少自忍必败，此实未知利害之分、贤愚之别也。予尝为泰州狱掾，颜岐夷仲以书劝予治狱次第，每一事写一幅相戒。如夏月处罪人，早间在东廓，以辟日色之类。又如狱中遣人勾追之类，必使之毕此事，不可更别遣人，恐其受赂已足，不肯毕事也。又如监司郡守严刻过当者，须平心定气，与之委屈详尽，使之相从而后已。如未肯从，再当如此详尽，其不听者少矣。
当官之法，直道为先。其有未可一直向前，或直前反败大事者，须用冯宣徽惠穆秤停之说。此非特小官然也，为天下国家当知之。
黄兑刚中尝为予言：顷为县尉，每遇检尸，虽盛暑亦先饮少酒，捉鼻亲视，人命至重，不可避少臭秽，使人横死无所申诉也。
范侍良育作库务官，随人箱笼，只置厅上，以防疑谤。凡若此类，皆守臣所宜详知也。
当官既自廉洁，又须关防小人，如文字历引之类，皆须明白，以防中伤，不可不至慎，不可不详知也。
当官者，难事勿辞，而深避嫌疑，以至请诚遇人，而深避文法，如此则可以免。
前辈尝云小人之性，专务苛且。明日有事，今日得休且休。当官者，不可徇其私意，忽而不治。谚有之曰：“劳心不如劳力。”此实要言也。
徐丞相择之尝言：“前辈尽心职事。”仁庙朝有为京西转运使者，一日见监窑官，问：“日所烧柴凡几灶？”曰：“十八九灶。”曰：“吾所见者十一灶，何也？”窑官愕然。盖转运使者，晨起望窑中所出烟几道知之。其尽心如此。
前辈尝言吏人不怕严只怕读。盖当官者详读公案，则情伪自见，不待严明也。
当官者，凡异色人皆不宜与之相接，巫祝尼媪之类尤宜疏绝，要以清心省事为本。
后生少年乍到官守，多为猾吏所饵，不自省察，所得毫末。而一任之间，不复敢举动，大作官嗜利，所得甚少，而吏人所盗不赀矣。以此被重谴，良可惜也。
当官者，先以暴怒为戒。事有不可当，详处之，必无不中。若先暴怒，只能自害，岂能害人，前辈尝言：“凡事只怕待。”待者，详处之谓也。盖详处之，则思虑自出，人不能中伤也。
尝见前辈作州县或狱官，每一公事难决者，必沉思静虑累日，忽然若有得者，则是非判矣。是道也，惟不苟者能之。
处事者，不以聪明为先，而以尽习为急；不以集事为急，而以方便为上。
孙思邈尝言：“忧于身者，不拘于人；畏于已者，不制于彼；慎于小者，不惧于大；戒于近者，不侈于远。”如此，则人事毕矣，实当官之要也。
同僚之契，交承之分，有兄弟之义，至其子孙，亦世讲之。前辈专以此为务，今人知之者盖少矣。又如旧举将及，旧尝为旧任察官者，后已官虽在上，前辈皆避，坐下坐。风俗如此，安得不厚乎？
叔曾祖尚书，当官至为廉洁。盖尝市缣帛，欲制造衣服，召当行者取缣帛，使缝匠还之。荥阳公为单州，几每月所用杂物，悉书之库门，买民间，未尝过此数，民皆悦服。
关沼止叔获盗，有情轻法重者，止叔不忍以此被赏也。
当官取佣钱、般家钱之类，多为之程，而过受其直，所得至微，所丧多矣。亦殊不知此数亦吾分外物也。
当官者，前辈多不敢就上位求荐章，但尽心职事，所以求知也。习诚尽职，求之虽不中，不远矣。未有学养子而后嫁者也。当官遇事，以此为心，鲜不济矣。
畏避文法，固有常情，然也人自然者，常以文法难任，委之于人。殊不知人之自私，亦犹已之自私也。以此处事，其能有济乎？其能有后福乎？其能使子孙昌盛乎？
当官处事，务合人情，忠恕违道不远，观于已而得之，未有舍此二字，而通用济者也。尝有人作郡守，延一术士，同处书室。后术士以公事干之，大怒叱下，竟致之杖背编置。招延此人已是犯义，既与之稔熟，而干以公事，亦人常情也。不从之足矣，而治之如此之峻，殆似绝灭人理。
尝谓仁人所处，能变虎狼如人类。如虎不入境，不害物，蝗不伤稼之类是也。如其不然，则变人类如虎狼。凡若此类，及告讦中伤谤人，欲置于死地是也。
唐充之广仁，贤者也，深为陈、邹二公所知。大观、政和间，守官苏州，朱氏方盛，充之数刺讥之。朱氏深以为怨，傅致之罪，刘器之以为充之为善，欲人之见知，故不免自异，以致祸患，非明哲保身之谓。
当官大要，直不犯祸，和不害义，在人精详酌之尔，然求合于道理，本非私心专为己也。
当官处事，但务着实。如涂擦文书，追改日月，重易押字，万一败露，得罪反重，亦非所以养诚心事君不欺之道也。百种奸伪，不如一实；反覆变诈，不如慎始；防人疑众，不如自慎；智数周密，不如省事。不易之道，事有当死不死，其诟有甚于死者，后亦未免得安。世人至此，多惑乱失常，皆不知轻重义之分也。此理非平居熟讲，临事必不能自立，不可不预思。古之欲委质事人，其父兄日夜先以此教之矣。中材以下，岂临事一朝一夕所能至哉！教之有素，其心安焉，所谓有所养也。
忍之一事，众妙之门。当官处事，尤是先务。若能清、慎、勤之外，更忍一忍，何事不办！《书》：“曰必有忍，其乃有济。”此处事之本也。谚曰：“忍事故灾星。”少陵诗云：“忍过事堪喜。”此皆切于事理，为世大法，非空言也，王沂公尝说：“吃得三斗酽醋方做得宰相。”盖言忍受得事。
刘器之建中崇宁初知潞州，部使者观望治郡中，事无巨细，皆详考然，竟不得毫发过。虽过往驿券，亦无违法予者。部使者亦叹伏之。后居南京，有府尹取兵，官白直点磨他：寓居无有不借禁军者，独器之未尝借一人。其廉慎如此。
故人龚节亨彦承，尝为予言：“后生当官，其使令人无乞丐钱物处，即此职事可为；有乞丐钱物处，则此职事不可为。”盖言有乞丐钱物处，人多陷主人以利，或致嫌疑也。
前辈尝言：“公罪不可无，私罪不可有。”此亦要言。私罪固不可有，若无公罪，则自保太过，无任事之意。
范忠宣公镇西京，日尝戒属官：“受纳租税，不要令两头探戒。”问：“何谓？”公曰：“贤问是也。不要令人户探官员等候受纳，官员不要探纳者多少，然后入场。此谓两头探。但自绝早入场待人口，则自无人户稽留之弊。”', '《官箴》，是古代中国居官格言之类的著作。共一卷，宋代吕本中撰。吕本中，字居仁，号东莱先生。吕公著之曾孙。曾任济阴主簿、起居舍人，官至直学士院。一生著述甚丰。', '', '当官的法则不过如下三点：清廉、谨慎、勤勉。知道了这三要素，就知道怎样持身立世。但世上当官之人，面对钱财，处理事务时，不能自我克制，常常自以为不一定败露出来。存这种侥幸念头，就会什么事也敢去做。然而虽常常做事失败，却无法控制自己不去做。因此明正心志，处理事务，从一开始就要自励自警，这是不能不注意的。如不是这样，而是耍弄权术智谋，千方百计补漏救拙，虽侥幸免于灾难，损失却很大。不如自始即不为之，也就无须补救了。唐人司马承祯先生在《坐忘论》中说：“与其在最后弄巧补救，不如当初老实守规。”这是当官者处理事务的基本法则。费力少而见功多，没有比说这句话更精彩的人了。人能临事而深思熟虑，就不会事后后悔不迭了。
侍奉君王如服侍父亲，侍奉长官如听命兄长；对待同事要像对待亲人一样和善，对待下级要像对待官仆一般友好；对待平民百姓要像对待妻子一般相爱；处理官场事务要如料理家事一样；这样，才能尽我的心力。只要有丝毫不足，就是我没有全力以赴，一心一意。所以，侍奉父母孝顺，就能对君王尽忠；对待兄长恭敬，就能对长官服从；治理家庭有方，就能胜任官职。家事、政事、不是同一道理么？
当官做事，要推已及人，常替别人着想。如征收税赋之类事项，既然必须照章办事，不能避免，在具体执行时，就要尽力减轻人民负担，不要让其成为人民的灾难。这样所得益处是很多的。', '[{"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42b87d0ac1145496c91a", "shortContent": "本篇选自《禅真后史》第二十五回。书题“清溪道人编次”，一般认为即明方汝浩编撰。是书与《禅真逸史》相接，叙禅真高徒薛举转世，托身贤士瞿天民家为子，因降生时有五色彩云笼覆不散，故取名为琰；时值唐太宗末年至武则天以周代唐前后，天下始由治入乱，国运衰落，百姓饥馑流离，瞿琰少年英杰，以普济天下之志，挟天生之神技异术，拯弱扶危，利民济物，定国安邦，一生功绩丰硕，最后功德圆满，白日升天，成了正果。\n作品旨在强调...", "authors": ["竺洪波"], "pressName": "上海辞书出版社"}]', '', 'indent', 1545310431, '5c1b1fe01579a3005fc241ac', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640770, '帝范', NULL, 15, 119, 1, 1, '李世民', NULL, 10478, '5858e5968e450a006c7f7a6b', '唐', 'wen', '文', 'https://baike.baidu.com/item/%E5%B8%9D%E8%8C%83/4215695?fr=aladdin', '', '君体第一
夫人者国之先，国者君之本。人主之体，如山岳焉，高峻而不动；如日月焉，贞明而普照。兆庶之所瞻仰，天下之所归往。宽大其志，足以兼包；平正其心足以制断。非威德无以致远，非慈厚无以怀人。抚九族以仁，接大臣以礼。奉先思孝，处位思恭。倾己勤劳，以行德义，此乃君之体也。
建亲第二
夫六合旷道，大宝重任。旷道不可偏制，故与人共理之；重任不可独居，故与人共守之。是以封建亲戚，以为藩卫，安危同力，盛衰一心。远近相持，亲疏两用。并兼路塞，逆节不生。昔周之兴也，割裂山河，分王宗族。内有晋郑之辅，外有鲁卫之虞。故卜祚灵长，历年数百。秦之季也，弃淳于之策，纳李斯之谋。不亲其亲，独智其智，颠覆莫恃，二世而亡。斯岂非枝叶扶疏，则根柢难拔；股肱既殒，则心腹无依者哉！汉祖初定关中，戒亡秦之失策，广封懿亲，过于古制。大则专都偶国，小则跨郡连州。末大则危，尾大难掉。六王怀叛逆之志，七国受鈇钺之诛。此皆地广兵强积势之所致也。魏武创业，暗于远图。子弟无封户之人，宗室无立锥之地。外无维城以自固，内无盘石以为基。遂乃大器保于他人，社稷亡于异姓。语曰：“流尽其源竭，条落则根枯。”此之谓也。
夫封之太强，则为噬脐之患；致之太弱则无固本之基。由此而言，莫若众建宗亲而少力。使轻重相镇，忧乐是同。则上无猜忌之心，下无侵冤之虑。此封建之鉴也。斯二者，安国之基。
君德之弘，唯资博达。设令县教，以术化人。应务适时，以道制物。
术以神隐为妙，道以光大为功。括苍旻以体心，则人仰之而不测；包厚地以为量，则人循之而无端。荡荡难名，宜其不远。且敦穆九族，放勋流美于前；克谐烝乂，重华垂誉于后。无以奸破义，无以疏间亲。察之以明，抚之以德，则邦家俱泰，骨肉无虞，良为美矣。
求贤第三
夫国之匡辅，必待忠良。任使得人，天下自治。故尧命四岳，舜举八元，以成恭己之隆，用赞钦明之道。士之居世，贤之立身，莫不戢翼隐鳞，待风云之会；怀奇蕴异，思会遇之秋。是明君旁求俊乂，博访英贤，搜扬侧陋。不以卑而不用，不以辱而不尊。昔伊尹，有莘之媵臣；吕望，渭滨之贱老。夷吾困于缧绁；韩信弊于逃亡。商汤不以鼎俎为羞，姬文不以屠钓为耻，终能献规景亳，光启殷朝；执旌牧野，会昌周室。
齐成一匡之业，实资仲父之谋；汉以六合为家，寔赖淮阴之策。
故舟航之绝海也，必假桡楫之功；鸿鹄之凌云也，必因羽翮之用；帝王之为国也，必藉匡辅之资。故求之斯劳，任之斯逸。照车十二，黄金累千，岂如多士之隆，一贤之重。此乃求贤之贵也。
审官第四
夫设官分职，所以阐化宣风。故明主之任人，如巧匠之制木，直者以为辕，曲者以为轮；长者以为栋梁，短者以为栱角。无曲直长短，各有所施。明主之任人，亦由是也。智者取其谋，愚者取其力；勇者取其威，怯者取其慎，无智、愚、勇、怯，兼而用之。故良匠无弃材，明主无弃士。不以一恶忘其善；勿以小瑕掩其功。割政分机，尽其所有。然则函牛之鼎，不可处以烹鸡；捕鼠之狸，不可使以搏兽；一钧之器，不能容以江汉之流；百石之车，不可满以斗筲之粟。何则大非小之量，轻非重之宜。
今人智有短长，能有巨细。或蕴百而尚少，或统一而为多。有轻才者，不可委以重任；有小力者，不可赖以成职。委任责成，不劳而化，此设官之当也。斯二者治乱之源。
立国制人，资股肱以合德；宣风导俗，俟明贤而寄心。列宿腾天，助阴光之夕照；百川决地，添溟渤之深源。海月之深朗，犹假物而为大。君人御下，统极理时，独运方寸之心，以括九区之内，不资众力何以成功？必须明职审贤，择材分禄。得其人则风行化洽，失其用则亏教伤人。故云则哲惟难，良可慎也！
纳谏第五
夫王者，高居深视，亏聪阻明。恐有过而不闻，惧有阙而莫补。所以设鞀树木，思献替之谋；倾耳虚心，伫忠正之说。言之而是，虽在仆隶刍荛，犹不可弃也；言之而非，虽在王侯卿相，未必可容。其义可观，不责其辩；其理可用，不责其文。至若折槛坏疏，标之以作戒；引裾却坐，显之以自非。故忠者沥其心，智者尽其策。臣无隔情于上，君能遍照于下。
昏主则不然，说者拒之以威；劝者穷之以罪。大臣惜禄而莫谏，小臣畏诛而不言。恣暴虐之心，极荒淫之志。其为雍塞，无由自知。以为德超三皇，材过五帝。至于身亡国灭，岂不悲哉！此拒谏之恶也。
去谗第六
夫谗佞之徒，国之蟊贼也。争荣华于旦夕，竞势利于市朝。以其谄谀之姿，恶忠贤之在己上；奸邪之志，怨富贵之不我先。朋党相持，无深而不入；比周相习，无高而不升。令色巧言，以亲于上；先意承旨，以悦于君。朝有千臣，昭公去国而方悟；弓无九石，宣王终身而不知。
以疏间亲，宋有伊戾之祸；以邪败正，楚有郤宛之诛。斯乃暗主庸君之所迷惑，忠臣孝子之可泣冤。故丛兰欲茂，秋风败之；王者欲明，谗人蔽之。此奸佞之危也。斯二者，危国之本。
砥躬砺行，莫尚于忠言；败德败心，莫逾于谗佞。今人颜貌同于目际，犹不自瞻，况是非在于无形，奚能自睹？何则饰其容者，皆解窥于明镜，修其德者，不知访于哲人。讵自庸愚，何迷之甚！良由逆耳之辞难受，顺心之说易从。彼难受者，药石之苦喉也；此易从者，鸩毒之甘口也！明王纳谏，病就苦而能消；暗主从谀，命因甘而致殒。可不诫哉！可不诫哉！
诫盈第七
夫君者，俭以养性，静以修身。俭则人不劳，静则下不扰。人劳则怨起，下扰则政乖。人主好奇技淫声、鸷鸟猛兽，游幸无度，田猎不时。如此则徭役烦，徭役烦则人力竭，人力竭则农桑废焉。人主好高台深池，雕琢刻镂，珠玉珍玩，黼黻絺绤。如此则赋敛重，赋敛重则人财匮，人财匮则饥寒之患生焉。乱世之君，极其骄奢，恣其嗜欲。土木衣缇绣，而人裋褐不全；犬马厌刍豢，而人糟糠不足。故人神怨愤，上下乖离，佚乐未终，倾危已至。此骄奢之忌也。
崇俭第八
夫圣世之君，存乎节俭。富贵广大，守之以约；睿智聪明，守之以愚。不以身尊而骄人，不以德厚而矜物。茅茨不剪，采椽不斫，舟车不饰，衣服无文，土阶不崇，大羹不和。非憎荣而恶味，乃处薄而行俭。故风淳俗朴，比屋可封。此节俭之德也。斯二者，荣辱之端。
奢俭由人，安危在己。五关近闭，则嘉命远盈；千欲内攻，则凶源外发。是以丹桂抱蠹，终摧曜月之芳；朱火含烟，遂郁凌云之焰。以是知骄出于志，不节则志倾；欲生于身，不遏则身丧。故桀纣肆情而祸结，尧舜约己而福延，可不务乎？
赏罚第九
夫天之育物，犹君之御众。天以寒暑为德，君以仁爱为心。寒暑既调，则时无疾疫；风雨不节，则岁有饥寒。仁爱下施，则人不凋弊；教令失度，则政有乖违。防其害源者，使民不犯其法；开其利本者，使民各务其业。显罚以威之，明赏以化之。威立则恶者惧，化行则善者劝。适己而妨于道，不加禄焉；逆己而便于国，不施刑焉。故赏者不德君，功之所致也；罚者不怨上，罪之所当也。故《书》曰：无偏无党，王道荡荡。此赏罚之权也。
务农第十
夫食为人天，农为政本。仓廪实则知礼节，衣食足则志廉耻。故躬耕东郊，敬授人时。国无九岁之储，不足备水旱；家无一年之服，不足御寒暑。然而莫不带犊佩牛，弃坚就伪。求伎巧之利，废农桑之基。以一人耕而百人食，其为害也，甚于秋螟。莫若禁绝浮华，劝课耕织，使人还其本，俗反其真，则竞怀仁义之心，永绝贪残之路，此务农之本也。斯二者，制俗之机。
子育黎黔，惟资威惠。惠而怀也，则殊俗归风，若披霜而照春日；威可惧也，则中华慑軏，如履刃而戴雷霆。必须威惠并施，刚柔两用，画刑不犯，移木无欺。赏罚既明，则善恶斯别；仁信并著，则遐迩宅心。勤穑务农，则饥寒之患塞；遏奢禁丽，则丰厚之利兴。且君之化下，如风偃草。上不节心，则下多逸志；君不约己，而禁人为非，是犹恶火之燃，添薪望止其焰；忿池之浊，挠浪欲澄其流，不可得也。莫若先正其身，则人不言而化矣。
阅武第十一
夫兵甲者，国之凶器也。土地虽广，好战则人雕；邦国虽安，忘战则人殆。雕非保全之术，殆非拟寇之方。不可以全除，不可以常用，故农隙讲武，习威仪也。是以勾践轼蛙，卒成霸业；徐偃弃武，终以丧邦。何则？越习其威，徐忘其备也。孔子曰：不教人战，是谓弃之。故知弧矢之威，以利天下。此用兵之机也。
崇文第十二
夫功成设乐，治定制礼。礼乐之兴，以儒为本。弘风导俗，莫尚于文；敷教训人，莫善于学。因文而隆道，假学以光身。不临深溪，不知地之厚；不游文翰，不识智之源。然则质蕴吴竿，非筈羽不美；性怀辨慧，非积学不成。是以建明堂，立辟雍。博览百家，精研六艺，端拱而知天下，无为而鉴古今。飞英声，腾茂实，光于天下不朽者，其唯学乎？此崇文术也。斯二者，递为国用。
至若长气亘地，成败定乎锋端；巨浪滔天，兴亡决乎一阵。当此之际，则贵干戈而贱庠序。及乎海岳既晏，波尘已清，偃七德之余威，敷九功之大化。当此之际，则轻甲胄而重诗书。是知文武二途，舍一不可，与时优劣，各有其宜。武士儒人，焉可废也。此十二条者，帝王之大纲也。安危兴废，咸在兹焉。
古人有云，非知之难，惟行不易；行之可勉，惟终实难。是以暴乱之君，非独明于恶路；圣哲之主，非独见于善途。良由大道远而难遵，邪径近而易践。小人俯从其易，不得力行其难，故祸败及之；君子劳处其难，不能力居其易，故福庆流之。故知祸福无门，惟人所召。欲悔非于既往，惟慎祸于将来。当择圣主为师。毋以吾为前鉴。取法于上，仅得为中；取法于中，故为其下。自非上德，不可效焉。吾在位以来，所制多矣。奇丽服，锦绣珠玉，不绝于前，此非防欲也；雕楹刻桷，高台深池，每兴其役，此非俭志也；犬马鹰鹘，无远必致，此非节心也；数有行幸，以亟劳人，此非屈己也。斯事者，吾之深过，勿以兹为是而后法焉。但我济育苍生其益多，平定寰宇其功大，益多损少，人不怨；功大过微，德未以之亏。然犹之尽美之踪，于焉多愧；尽善之道，顾此怀惭。况汝无纤毫之功，直缘基而履庆？若崇善以广德，则业泰身安；若肆情以纵非，则业倾身丧。且成迟败速者，国之基也；失易得难者，天之位也。可不惜哉？可不慎哉？', '《帝范》，古代论政著作。唐朝李世民撰。此书系唐太宗李世民自撰的论述人君之道的一部政治文献，他在赐予子女时云，再三叮嘱，作为遗训：“饬躬阐政之道，皆在其中，朕一旦不讳，更无所言。”书成于贞观二十二年（648年）。', '', '', NULL, '《帝范：中国最伟大帝王的沉思录》：中国历史上最好的管理和统御之道；毛泽东曾说，“李世民的工作方法有四”，即李世民平定四方，用怀柔政策，不急功近利，劳民损兵；不贪图游乐，每早视朝，用心听取各种建议，出言周密；罢朝后和大臣们推心置腹讨论是非；晚上同人高谈经典文事。对这位古代领袖俊杰的为政能力做出了极高的评价。
《帝范》一书是李世民一生执政经验的高度浓缩。他曾经这样告诉太子：“饬躬阐政之道，皆在其中，朕一旦不讳，更无所言。”可见，他对《帝范：中国最伟大帝王的沉思录》的高度自信。事实也的确如此。在《帝范：中国最伟大帝王的沉思录》中，他对为政者的个人修养，选任和统御下属的学问，乃至经济民生、教育军事等家国事务都做出了非常有见地的解答。
', 'indent', 1545311094, '5c1b22cbfb4ffe005f0dd1ee', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640771, '二程集-河南程氏遗书-卷十一', NULL, 16, 73, 1, 1, '程颢', NULL, 10253, '57bb15847db2a20068c90a25', '宋', 'wen', '文', '', '', '仲弓曰：“焉知贤才而举之？”子曰：“举尔所知。尔所不知，人其舍诸？”便见仲弓与圣人用心之大小。推此义，则一心可以丧邦，一心可以兴邦，只在公私之间尔。', '《二程语录》是北宋思想家程颢、程颐兄弟一生传道讲学言论的结集。二人同为宋明理学的奠基者，故世称二程。', '这段话是二程对《论语》子路篇第十三的解释。原文为：“仲弓为季氏宰，问政。子曰：‘先有司，赦小过，举贤才。’曰：‘焉知贤才而举之？’曰：‘举尔所知。尔所不知，人其舍诸？’”说的是鲁国的仲弓做了季氏的家臣，向孔子请教怎样管理政事。孔子告诉他：“先责成手下负责具体事务的官吏，让他们各负其责，赦免他们的小过错，选拔贤才来任职。”仲弓又问：“怎样发现并选拔贤才呢？”孔子说：“选拔你所知道的。至于你不知道的贤才，别人难道还会埋没他们吗？”', '', NULL, '', 'indent', 1545311860, '5c1b260afb4ffe005f0df609', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640772, '管子形势', NULL, 24, 573, 1, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E7%AE%A1%E5%AD%90%C2%B7%E5%BD%A2%E5%8A%BF/19831178?fr=aladdin', '', '山高而不崩，则祈羊至矣；渊深而不涸，则沈玉极矣，天不变其常，地不易其则，春秋冬夏，不更其节，古今一也。蛟龙得水，而神可立也；虎豹得幽，而威可载也。风雨无乡，而怨怒不及也。贵有以行令，贱有以忘卑，寿夭贫富，无徒归也。
衔命者，君之尊也。受辞者，名之铉也。上无事，则民自试。抱蜀不言，而庙堂既修。槛鹄锵锵，唯民歌之。济济多士，殷民化之，纣之失也。飞蓬之问，不在所宾；燕雀之集，道行不顾。牺牷圭璧，不足以飨鬼神。主功有素，宝币奚为？羿之道，非射也；造父之术，非驭也；奚仲之巧，非斫削也。召远者使无为焉，亲近者言无事焉，唯夜行者独有也。
平原之隰，奚有于高？大山之隈，奚有于深？訾讆之人，勿与任大。譕臣者可以远举。顾忧者可与致道。其计也速而忧在近者，往而勿召也举长者可远见也；裁大者众之所比也。美人之怀，定服而勿厌也。必得之事，不足赖也；必诺之言，不足信也。小谨者不大立，訾食者不肥体；有无弃之言者，必参于天地也。坠岸三仞，人之所大难也，而猿猱饮焉，故曰伐矜好专，举事之祸也。不行其野，不违其马；能予而无取者，天地之配也。
怠倦者不及，无广者疑神，神者在内，不及者在门，在内者将假，在门者将待。曙戒勿怠，后稚逢殃。朝忘其事，夕失其功。邪气入内，正色乃衰。君不君，则臣不臣。父不父，则子不子。上失其位，则下逾其节。上下不和，令乃不行。衣冠不正，则宾者不肃；进退无仪，则政令不行。且怀且威，则君道备矣。莫乐之，则莫哀之。莫生之，则莫死之。往者不至，来者不极。
道之所言者一也，而用之者异。有闻道而好为家者，一家之人也；有闻道而好为乡者，一乡之人也；有闻道而好为国者，一国之人也；有闻道而好为天下者，天下之人也；有闻道而好定万物者，天下之配也。道往者，其人莫来；道来者，其人莫往；道之所设，身之化也。持满者与天，安危者与人。失天之度，虽满必涸。上下不和，虽安必危。欲王天下，而失天之道，天下不可得而王也。得天之道。其事若自然。失天之道，虽立不安。其道既得，莫知其为之。其功既成，莫知其释之。藏之无刑，天之道也。疑今者，察之古；不知来者，视之往，万事之生也，异趣而同归，古今一也。
生栋覆屋。怨怒不及；弱子下瓦，慈母操棰。天道之极，远者自亲。人事之起，近亲造怨。万物之于人也，无私近也，无私远也；巧者有余，而拙者不足；其功顺天者天助之，其功逆天者天违之；天之所助，虽小必大；天之所违，虽成必败；顺天者有其功，逆天者怀其凶，不可复振也。
乌鸟之狡，虽善不亲。不重之结，虽固必解；道之用也，贵其重也。毋与不可，毋彊不能，毋告不知；与不可，彊不能，告不知，谓之劳而无功。见与之交，几于不亲；见哀之役，几于不结；见施之德，几于不报；四方所归，心行者也。独王之国，劳而多祸；独国之君，卑而不威；自媒之女，丑而不信，未之见而亲焉，可以往矣；久而不忘焉，可以来矣。日月不明，天不易也；山高而不见，地不易也。言而不可复者，君不言也；行而不可再者，君不行也。凡言而不可复，行而不可再者，有国者之大禁也。', '管子一书是稷下道家推尊管仲之作的集结，即以此为稷下之学的管子学派。《汉书·艺文志》将其列入子部道家类，《隋书·经籍志》列入法家类。《四库全书》将其列入子部法家类。书篇幅宏伟，内容复杂，思想丰富，是研究中国古代特别是先秦学术文化思想的重要典籍。', '', '山高而不崩颓，就有人烹羊设祭；渊深而不枯竭，就有人投玉求神。天不改变它的常规，地不改变它的法则，春秋冬夏不改变它的节令，从古到今都是一样的。蛟龙得水，才可以树立神灵；虎豹凭借深山幽谷，才可以保持威力。风雨没有既定的方向，谁也不会埋怨它。位高的人发号施令，位低的人忘掉卑贱，长寿、短命、贫穷、富有等等，都不是无因而至的。
臣下能奉行命令，是由于君主地位的尊严；臣下能接受指示，是由于君臣名分的作用。君主不亲自过问，人民就会自己去做事；手执祭器不说话，朝政也会普遍地修明。天鹅发出动听的声音，人们会齐声赞美；西周人材济济，殷遗民也会被感化。对于没有根据的言论，不必听从；对于燕雀聚集的小事，行道者不屑一顾。用牛羊玉器来供奉鬼神，不一定得到鬼神的保佑，只要君主的功业有根基，何必使用珍贵的祭品！后羿射箭的功夫，不在射箭的表面动作；造父驾车的技术，不在驾车的表面动作；奚仲的技巧，也不在木材的砍削上。召徕远方的人，单靠使者是没有用的；亲近国内的人，光说空话也无济于事。只有内心里认真行德的君主，才能够独得治国的功效。
平原上的小坡，怎么能够算作高？大山上的小沟，怎么能够算作深？专挑好人毛病专说坏人好话的人，是不能委之以重任的。谋虑远大的人，可以同他共图大事；见识高超的人，可以同他共行治国之道。但是，对于那种贪图速效而只顾眼前利害的人，走开了就不要召他回来；注重长远利益的人，影响也就深远；材器伟大的人，会得到众人的依赖；要人们感怀自己，一定要行德而不可厌倦。不应得而求必得的事情，是靠不住的；不应承诺而完全承诺的语言，是信不得的。谨小慎微也不能成大事，就好比挑拣食物不能使身体胖起来一样。能够不放弃以上这些格言的，就能与天地媲美了。从三人高的崖岸上跳下来，人是很难做到的，但猴子却毫不在乎地跳下来喝水。所以说，骄傲自大，独断专行，乃是行事的祸患。虽不到野外跑路，也不要把马丢掉。能够做到只给人们好处而不向人们索取报酬的，那就同天地一样伟大了。
懒惰的人总是落后，勤奋的人总是办事神速有效。如果说，办事神速的已经进入室内，那么，落后的还在门外。进入室内的可以从容不迫，在门外的必将疲惫不堪。所以，黎明时玩忽怠惰，日暮时就要遭殃。早上忘掉了应作的事情，晚上就什么成果也没有。一个人邪气侵袭到体内，正色就要衰退。君主不像君主的样子，臣子当然就不像臣子；父亲不像父亲的样子，儿子当然就不像儿子。君主不按照他的身份办事，臣子就会超越应守的规范。上下不和，政令就无法推行。君主的衣冠不端正，礼宾的官吏就不会严肃。君主的举动不合乎仪式，政策法令就不容易贯彻。一方面关怀臣民，另方面再有威严，为君之道，才算完备。君主不能使臣民安乐，臣民也就不会为君主分忧；君主不能使臣民生长繁息，臣民也就不会为君主牺牲生命。君主给予臣民的，不确实兑现；臣民对待君主，也是不会全力以赴的。
关于“道”，它的理论是一致的，但运用起来则各有不同。有的人懂得道而能治家，他便是治家的人材；有的人懂得道而能治乡，他便是一乡的人材；有的人懂得道而能治国，他便是一国的人材；有的人懂得道而能治天下，他便是天下的人材；有的人懂得道而能使万物各得其所，那便和天地一样伟大了。失道者，人民不肯来投；得道者，人民不肯离去。道之所在，自身就应该与之同化。’凡是始终保持强盛的，就因为顺从天道；凡是能安危存亡的，就因为顺从人心。违背天的法则，虽然暂时丰满，最终必然枯竭；上下不和，虽然暂时安定，最终也必然危亡。想要统一天下而违背天道，天下就不可能被他统一起来。掌握了天道，成事就很自然；违背了天道，虽然成功也不能保持。已经得道的，往往不觉察自己是怎样做的；已经成功了，往往又不觉察道是怎样离开的。就好像隐藏起来而没有形体，这就是“天道”。但是，对当今有怀疑则可以考察古代，对未来不了解，则可以查阅历史。万事的本性，内容虽有不同，但总是同归一理，从古到今都是一样的。
用新伐的木材做屋柱而房子倒坍，谁也不怨恨木材；小孩子把屋瓦拆下来，慈母也会打棍子。顺天道去做，远者都会来亲近；事起于人为，近亲也要怨恨。万物之于人，是没有远近亲疏之分的。高明的人用起来就有余，愚笨的人用起来就不足。顺乎天道去做，天就帮助他；反乎天道去做，天就违背他。天之所助，弱小可以变得强大；天之所弃，成功可以变为失败。顺应天道的可以得其成效，违背天道的就要招致灾祸，且无可挽救。
乌鸦般的交谊，看着友善，其实并不亲密；不重合的绳结，即使坚固，也一定松脱开解。所以，道在实际运用的时候，贵在慎重。不要交与不可靠的人，不要强给做不到的人，不要告知不明事理的人。交与不可靠的、强予做不到的、告知不明事理的人，就叫作劳而无功。表面上显示友好的朋友，也就接近于不亲密了；表面上显示亲爱的交谊，也就接近于不结好了；表面上显示慷慨的恩赐，也就接近于不得所报了。只有内心里认真行德，四面八方才会归附。独断专横的国家，必然疲于奔命而祸事多端；独断专横国家的君主，必然卑鄙而没有威望。这就好比独自议定婚姻的妇女，一定名声不好而没有信誉。但对于尚未见面就令人仰慕的君主，应该去投奔；对于久别而令人难忘的君主，应该来辅佐。日月有不明的时候，但天不会变；山高有看不见的时候，但地不会变。说起话来，那种只说一次而不可再说的错话，人君就不应该说；做起事来，那种只做一次而不可再做的错事，人君就不应该做。凡是重复那些不可再说的言论和那些不可再做的事情，都是一国之君的最大禁忌。', NULL, '', 'indent', 1565352049, '5c1b3ad91579a3005fc378b0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640775, '周易·益卦·彖传', NULL, 8, 67, 1, 1, '姬昌 ', NULL, 36810, '58a65cd8ac502e006cc070e1', '周', 'wen', '文', '', '', '益，损上益下，民说无疆，自上下下，其道大光。利有攸往，中正有庆。利涉大川，木道乃行。益动而巽，日进无疆。天施地生，其益无方。凡益之道，与时偕行。', '', '', '', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b4e0fb5420e2767eec323", "shortContent": " 《彖传》是战国中期的哲学家解释和发挥《易经》思想的最重要的成果，所以得以一代代地传承下来。《周易》原来是古代占卜留下的文字的选编和集锦，它的哲学化过程就是从《彖传》开始的。《周易》正是由于《彖》、《象》、《文言》、《系辞》等著作的辅助，才成为中国古代哲学观念和理论的来源和宝库，并且成为两千年中使用最广泛的哲学教科书，对培养中国人的抽象思维能力发挥了极其巨大的作用。\n\n《彖传》的作者在理论上具有大...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b4e7ab5420e2767eec57b", "shortContent": "坤卦的《彖传》赞美大地的品格，但是《彖传》并不奉行二元论，将天道与地道规定为世界的两个互不统辖的本源，而是从另外一个角度，即通过讲述地德来说明天道的作用。同乾卦一样，坤卦卦辞中也有“元亨”两字，《彖传》颂扬“坤元”，因为万物一定要依靠大地才能生存，但是其赞词肯定大地最根本的品格是“顺承天”，就是说只有天道才是惟一的原动力，而地道只是遵循天道，以实现天道。\n\n这里所谓的“顺承天”意思是遵循天道，即宇...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1545318870, '5c1b41694773f7005f062e72', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640776, '大道上', NULL, 4, 2, 1, 1, '尹文', NULL, 36979, '5c1b429a808ca400732949a8', '周', 'wen', '文', '', '', '大道无形，称器有名。名也者，正形者也。形正由名，则名不可差。故仲尼云“必也正名乎！名不正，则言不顺”也。大道不称，众有必名。生于不称，则群形自得其方圆。名生于方圆，则众名得其所称也。大道治者，则名、法、儒、墨自废。以名、法、儒、墨治者，则不得离道。老子曰：“道者万物之奥，善人之宝，不善人之所宝。”是道治者，谓之善人；藉名、法、儒、墨者，谓之不善人。善人之与不善人，名分日离，不待审察而得也。道不足以治则用法，法不足以治则用术，术不足以治则用权，权不足以治则用势。势用则反权，权用则反术，术用则反法，法用则反道，道用则无为而自治。故穷则徼终，徼终则反始。始终相袭，无穷极也。

有形者必有名，有名者未必有形。形而不名，未必失其方圆白黑之实。名而不可不寻名以检其差。故亦有名以检形，形以定名，名以定事，事以检名。察其所以然，则形名之与事物，无所隐其理矣。

名有三科，法有四呈。一曰命物之名，方圆白黑是也；二曰毁誉之名，善恶贵贱是也；三曰况谓之名，贤愚爱憎是也。一曰不变之法，君臣上下是也；二曰齐俗之法，能鄙同异是也；三曰治众之法，庆赏刑罚是也；四曰平准之法，律度权量是也。

术者，人君之所密用，群下不可妄窥；势者，制法之利器，群下不可妄为。人君有术而使群下得窥，非术之奥者；有势而使群下得为，非势之重者。大要在乎先正名分，使不相侵杂。然后术可秘，势可专。名者，名形者也；形者，应名者也。然形非正名也，名非正形也。则形之与名居然别矣。不可相乱，亦不可相无。无名，故大道无称；有名，故名以正形。今万物具存，不以名正之，则乱；万名具列，不以形应之，则乖。故形名者，不可不正也。善名命善，恶名命恶。故善有善名，恶有恶名。圣贤仁智，命善者也；顽嚚凶愚，命恶者也。今即圣贤仁智之名，以求圣贤仁智之实，未之或尽也。即顽嚚凶愚之名，以求顽嚚凶愚之实，亦未或尽也。使善恶尽然有分，虽未能尽物之实，犹不患其差也。故曰：名不可不辨也。

名称者，别彼此而检虚实者也。自古至今，莫不用此而得，用彼而失。失者，由名分混；得者，由名分察。今亲贤而疏不肖，赏善而罚恶。贤不肖善恶之名宜在彼，亲疏赏罚之称宜属我。我之与彼，又复一名，名之察者也。名贤不肖为亲疏，名善恶为赏罚，合彼我之一称而不别之，名之混者也。故曰：名称者，不可不察也。语曰“好牛”，又曰，不可不察也。好则物之通称，牛则物之定形，以通称随定形，不可穷极者也。设复言“好马”，则复连于马矣，则好所通无方也。设复言“好人”，则彼属于人矣。则“好”非“人”，“人”非“好”也。则“好牛”、“好马”、“好人”之名自离矣。故曰：名分不可相乱也。

五色、五声、五臭、五味，凡四类，自然存焉天地之间，而不期为人用。人必用之，终身各有好恶，而不能辨其名分。名宜属彼，分宜属我。我爱白而憎黑，韵商而舍徵，好膻而恶焦，嗜甘而逆苦。白黑、商徵、膻焦、甘苦，彼之名也；爱憎、韵舍、好恶、嗜逆，我之分也。定此名分，则万事不乱也。故人以“度”审长短，以“量”受少多，以“衡”平轻重，以“律”均清浊，以“名”稽虚实，以“法”定治乱，以简治烦惑，以易御险难。万事皆归于一，百度皆准于法。归一者，简之至；准法者，易之极。如此则顽嚚聋瞽，可与察慧聪明同其治也。

天下万事，不可备能，责其备能于一人，则贤圣其犹病诸。设一人能备天下之事，则左右前后之宜、远近迟疾之间，必有不兼者焉。苟有不兼，于治阙矣。全治而无阙者，大小、多少，各当其分；农商工仕，不易其业。老农、长商、习工、旧仕，莫不存焉，则处上者何事哉？故有理而无益于治者，君子弗言；有能而无益于事者，君子弗为。君子非乐有言，有益于治，不得不言。君子非乐有为，有益于事，不得不为。故所言者不出于名法权术，所为者不出于农稼军阵，周务而已，故明主任之。治外之理，小人之所必言；事外之能，小人之所必为。小人亦知言有损于治，而不能不言；小人亦知能有损于事，而不能不为。故所言者极于儒墨是非之辨，所为者极于坚伪偏抗之行，求名而已，故明主诛之。故古语曰：“不知无害为君子，知之无损为小人。工匠不能，无害于巧；君子不知，无害于治。”此言信矣。

为善使人不能得从，此独善也；为巧使人不能得从，此独巧也；未尽善巧之理。为善与众行之，为巧与众能之，此善之善者，巧之巧者也。故所贵圣人之治，不贵其独治，贵其能与众共治也；所贵工倕之巧，不贵其独巧，贵其能与众共巧也。

今世之人，行欲独贤，事欲独能，辩欲出群，勇欲绝众。独行之贤，不足以成化；独能之事，不足以周务；出群之辩，不可为户说；绝众之勇，不可与征阵。凡此四者，乱之所由生。是以圣人任道以夷其险，立法以理其差。使贤愚不相弃，能鄙不相遗。能鄙不相遗，则能鄙齐功；贤愚不相弃，则贤愚等虑。此至治之术也。

名定则物不竞，分明则私不行。物不竞，非无心；由名定，故无所措其心。私不行，非无欲；由分明，故无所措其欲。然则心欲人人有之，而得同于无心无欲者，制之有道也。田骈曰：天下之士，莫肯处其门庭、臣其妻子，必游宦诸侯之朝者，利引之也。游于诸侯之朝，皆志为卿大夫而不拟于诸侯者，名限之也。彭蒙曰：“雉兔在野，众人逐之，分未定也；鸡豕满市，莫有志者，分定故也。物奢则仁智相屈，分定则贪鄙不争。”圆者之转，非能转而转，不得不转也；方者之止，非能止而止，不得不止也。因圆之自转，使不得止；因方之自止，使不得转。何苦物之失分？故因贤者之有用，使不得不用；因愚者之无用，使不得用。用与不用，皆非我也。因彼可用与不可用而自得其用也。自得其用，奚患物之乱乎？物皆不能自能，不知自知。智非能智而智，愚非能愚而愚，好非能好而好，丑非能丑而丑。夫不能自能，不知自知，则智好何所贵？愚丑何所贱？则智不能得夸愚，好不能得嗤丑，此为得之道也。道行于世，则贫贱者不怨，富贵者不骄，愚弱者不慑，智勇者不陵，定于分也；法行于世，则贫贱者不敢怨富贵，富贵者不敢陵贫贱，愚弱者不敢冀智勇，智勇者不敢鄙愚弱。此法之不及道也。

世之所贵，同而贵之，谓之俗；世之所用，同而用之，谓之物。苟违于人，俗所不与；苟忮于众，俗所共去。故人心皆殊，而为行若一；所好各异，而资用必同。此俗之所齐，物之所饰。故所齐不可不慎，所饰不可不择。昔齐桓好衣紫，阖境不鬻异采；楚庄爱细腰，一国皆有饥色。上之所以率下，乃治乱之所由也。故俗苟沴，必为法以矫之；物苟溢，必立制以检之。累于俗、饰于物者，不可与为治矣。昔晋国苦奢，文公以俭矫之，乃衣不重帛，食不兼肉。无几时，国人皆大布之衣，脱粟之饭。越王句践谋报吴，欲人之勇，路逢怒蛙而轼之。比及数年，民无长幼，临敌虽汤火不避。居上者之难，如此之验。圣王知民情之易动，故作乐以和之，制礼以节之。在下者不得用其私，故礼乐独行。礼乐独行，则私欲寝废；私欲寝废，则遭贤之与遭愚均矣。若使遭贤则治，遭愚则乱，是治乱属于贤愚，不系于礼乐。

是圣人之术与圣主而俱没，治世之法逮易世而莫用，则乱多而治寡。乱多而治寡，则贤无所贵，愚无所贱矣。处名位，虽不肖，不患物不亲己；在贫贱，虽仁贤，不患物不疏己。亲疏系乎势利，不系于不肖与仁贤也。吾亦不敢据以为天理，以为地势之自然者尔。今天地之间，不肖实众，仁贤实寡。趋利之情，不肖特厚。廉耻之情，仁贤偏多。今以礼义招仁贤，所得仁贤者，万不一焉；以名利招不肖，所得不肖者，触地是焉。故曰：“礼义成君子，君子未必须礼义；名利治小人，小人不可无名利。”

庆赏刑罚，君事也；守职效能，臣业也。君料功黜陟，故有庆赏刑罚；臣各慎所任，故有守职效能。君不可与臣业，臣不可侵君事。上下不相侵与，谓之名正。名正而法顺也。接万物使分，别海内使不杂。见侮不辱，见推不矜，禁暴息兵，救世之斗。此仁君之德，可以为主矣。守职分使不乱，慎所任而无私。饥饱一心，毁誉同虑，赏亦不忘，罚亦不怨。此居下之节，可为人臣矣。

世有因名以得实，亦有因名以失实。宣王好射，说人之谓己能用强也，其实所用不过三石。以示左右，左右皆引试之，中关而止。皆曰：“不下九石，非大王孰能用是？”宣王说之。然则宣王用不过三石，而终身自以为九石。三石，实也，九石，名也，宣王悦其名而丧其实。齐有黄公者，好谦卑。有二女，皆国色。以其美也，常谦辞毁之，以为丑恶，丑恶之名远布，年过而一国无聘者。卫有鳏夫，失时冒娶之，果国色。然后曰：“黄公好谦，故毁其子不姝美。”于是争礼之，亦国色也。国色，实也；丑恶，名也。此违名而得实矣。楚人担山雉者，路人问：“何鸟也？”担雉者欺之曰：“凤皇也。”路人曰：“我闻有凤皇，今直见之，汝贩之乎？”曰：“然。”则十金，弗与。请加倍，乃与之。将欲献楚王，经宿而鸟死。路人不遑惜金，惟恨不得以献楚王。国人传之，咸以为真凰皇，贵，欲以献之。遂闻楚王，王感其欲献于己，召而厚赐之，过于买鸟之金十倍。魏田父有耕于野者，得宝玉径尺，弗知其玉也，以告邻人。邻人阴欲图之，谓之曰：“怪石也，畜之弗利其家，弗如复之。”田父虽疑，犹录以归，置于庑下。其夜玉明光照一室，田父称家大怖，复以告邻人。曰：“此怪之征，遄弃，殃可销。”于是遽而弃于远野。邻人无何盗之以献魏王。魏王召玉工相之，玉工望之再拜而立：“敢贺王，王得此天下之宝，臣未尝见。”王问价，玉工曰：“此无价以当之，五城之都，仅可一观。”魏王立赐献玉者千金，长食上大夫禄。

凡天下万里皆有是非，吾所不敢诬。是者常是，非者常非，亦吾所信。然是虽常是，有时而不用；非虽常非，有时而必行。故用是而失，有矣；行非而得，有矣。是非之理不同，而更兴废，翻为我用，则是非焉在哉？观尧、舜、汤、武之成，或顺或逆，得时则昌；桀、纣、幽、厉之败，或是或非，失时则亡。五伯之主亦然。宋公以楚人战于泓，公子目夷曰：“楚众我寡，请其未悉济而击之。”宋公曰：“不可，吾闻不鼓不成列。寡人虽亡之余，不敢行也。”战败，楚人执宋公。齐人弑襄公，立公孙无知。召忽、夷吾奉公子纠奔鲁，鲍叔牙奉公子小白奔莒。既而无知被杀，二公子争国。纠，宜立者也。小白先入，故齐人立之。既而使鲁人杀纠，召忽死之，征夷吾以为相。晋文公为骊姬之谮，出亡十九年，惠公卒，赂秦以求反国，杀怀公子而自立。彼一君正而不免于执，二君不正，霸业遂焉。己是而举世非之，则不知己之是；己非而举世是之，亦不知己之非。然则是非随众贾而为正，非己所独了。则犯众者为非，顺众者为是。故人君处权乘势，处所是之地，则人所不得非也。居则物尊之，动则物从之，言则物诚之，行则物则之，所以居物上、御群下也。国乱有三事：年饥民散，无食以聚之则乱；治国无法，则乱；有法而不能用，则乱。有食以聚民，有法而能行，国不治，未之有也。', '', '', '', NULL, '', 'indent', 1545319246, '5c1b42e4808ca400672ed23e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640778, '周易·系辞下传·其二', NULL, 15, 327, 1, 1, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '古者包羲氏之王天下也，仰则观象于天，俯则观法于地，观鸟兽之文，与地之宜，近取诸身，远取诸物，于是始作八卦，以通神明之德，以类万物之情。
作结绳而为网罟，以佃以渔，盖取诸离。
包羲氏没，神农氏作，斫木为耜，揉木为耒，耒耨之利，以教天下，盖取诸益。
日中为市，致天下之民，聚天下之货，交易而退，各得其所，盖取诸噬嗑。
神农氏没，黄帝、尧、舜氏作，通其变，使民不倦，神而化之，使民宜之。易穷则变，变则通，通则久。是以自天佑之，吉无不利，黄帝、尧、舜，垂衣裳而天下治，盖取诸乾坤。
刳木为舟，剡木为楫，舟楫之利，以济不通，致远以利天下，盖取诸涣。
服牛乘马，引重致远，以利天下，盖取诸随。
重门击柝，以待暴客，盖取诸豫。
断木为杵，掘地为臼，臼杵之利，万民以济，盖取诸小过。
弦木为弧，剡木为矢，弧矢之利，以威天下，盖取诸睽。
上古穴居而野处，后世圣人易之以宫室，上栋下宇，以待风雨，盖取诸大壮。
古之葬者，厚衣之以薪，葬之中野，不封不树，丧期无数，后世圣人易之以棺椁，盖取诸大过。
上古结绳而治，后世圣人易之以书契，百官以治，万民以察，盖取诸口。', '', '', '', NULL, '', 'indent', 1545319811, '5c1b4509808ca400672ef15a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640779, '韩诗外传', NULL, 40, 2, 1, 1, '韩婴', NULL, 36802, '589c4d372f301e0069abfb3f', '汉', 'wen', '文', '', '', '夫明镜所以照形，往古所以知今。夫知恶往古之所以危亡，而不袭蹈其所以安存者，则无异乎却行而求逮于前人也。', '对照明镜是为了看清自己的面容，研究古事是为了知道今天的时势。说明研究并借鉴古代的经验教训，才能更好地作出决策，求得好的形势。', '', '', NULL, '', 'indent', 1545320254, '5c1b462b808ca400672f01fd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640780, '荀子 · 议兵', NULL, 9, 13, 1, 1, '荀子', NULL, 10279, '57b902bbdf0eea006334f0d0', '周', 'wen', '文', '', '', '临武君与孙卿子议兵于赵孝成王前，王曰：“请问兵要。”临武君对曰：“上得天时，下得地利，观敌之变动，后之发，先之至，此用兵之要求也。”
孙卿子曰：“不然。臣所闻古之道，凡用兵攻战之本在乎壹民。弓矢不调，则羿不能以中微；六马不和，则造父不能以致远；士民不亲附，则汤、武不能以必胜也。故善附民者，是乃善用兵者也。故兵要在乎善附民而已。”
临武君曰：“不然。兵之所贵者势利也，所行者变诈也。善用兵者，感忽悠暗，莫知其所从出，孙、吴用之，无敌于天下，岂必待附民哉！”
孙卿子曰：“不然。臣之所道，仁人之兵，王者之志也。君之所贵，权谋势利也；所行，攻夺变诈也，诸侯之事也。仁人之兵，不可诈也。彼可诈者，怠慢者也，路亶者也，君臣上下之间滑然有离德者也。故以桀诈桀，犹巧拙有幸焉。以桀诈尧，譬之若以卵投石，以指挠沸；若赴水火，入焉焦没耳。故仁人上下，百将一心，三军同力；臣之于君也，下之于上也，若子之事父，弟之事兄，若手臂之扞头目而覆胸腹也，诈而袭之，与先惊而后击之，一也。且仁人之用十里之国，则将有百里之听；用百里之国，则将有千里之听。用千里之国，则将有四海之听，必将聪明警戒，和传而一。故仁人之兵，聚则成卒，散则成列；延则若莫邪之长刃，婴之者断；兑则若莫邪之利锋，当之者溃；圜居而方止，则若磐石然，触之者角摧，案角鹿埵、陇种、东笼而退耳。且夫暴国之君，将谁与至哉？彼其所与至者，必其民也，而其民之亲我，欢若父母，其好我，芬若椒兰；彼反顾其上，则若灼黥，若仇雠。人之情，虽桀、跖，岂又肯为其所恶贼其所好者哉？是犹使人之子孙自贼其父母也，彼必将来告之，夫又何可诈也？故仁人用，国日明，诸侯先顺者安，后顺者危，虑敌之者削，反之者亡。《诗》曰：‘武王载发，有虔秉钺；如火烈烈，则莫我敢遏。’此之谓也。”
孝成王、临武君曰：“善！请问王者之兵设何道、何行而可？”
孙卿子曰：“凡在大王，将率未事也。臣请遂道王者诸侯强弱存亡之效、安危之势。君贤者其国治，君不能者其国乱；隆礼、贵义者其国治，简礼、贱义者其国乱。治者强，乱者弱，是强弱之本也。上足卬则下可用也，上不卬则下不可用也。下可用则强，下不可用则弱，是强弱之常也。隆礼效功，上也；重禄贵节，次也；上功贱节，下也：是强弱之凡也。好士者强，不好士者弱；爱民者强，不爱民者弱；政令信者强，政令不信者弱；民齐者强，民不齐者弱；赏重者强，赏轻者弱；刑威者强，刑侮者弱；械用兵革攻完便利者强，械用兵革窳楛不便利者弱；重用兵者强，轻用兵者弱；权出一者强，权出二者弱；是强弱之常也。齐人隆技击，其技也，得一首者，则赐赎锱金，无本赏矣。是事小敌毳则偷可用也，事大敌坚则焉涣离耳，若飞鸟然，倾侧反覆无日，是亡国之兵也。兵莫弱是矣，是其去赁市佣而战之几矣。魏氏之武卒，以度取之，衣三属之甲，操十二石之弩，负服矢五十个，置戈其上，冠带剑，赢三日之粮，日中而趋百里。中试则复其户，利其田宅，是数年而衰而未可夺也，改造则不易周也，是故地虽大其税必寡，是危国之兵也。秦人其生民也陿阸，其使民也酷烈，劫之以势，隐之以阸，忸之以庆赏，䲡之以刑罚，使天下之民所以要利于上者，非斗无由也。阸而用之，得而后功之，功赏相长也。五甲首而隶五家，是最为众强长久，多地以正。故四世有胜，非幸也，数也。故齐之技击不可以遇魏氏之武卒，魏氏之武卒不可以遇秦之锐士，秦之锐士不可以当桓、文之节制，桓、文之节制不可以敌汤、武之仁义，有遇之者，若以焦熬投石焉。兼是数国者，皆干赏蹈利之兵也，佣徒鬻卖之道也，未有贵上、安制、綦节之理也，诸侯有能微妙之以节，则作而兼殆之耳！故招近募选，隆势诈，尚功利，是渐之也；礼义教化，是齐之也。故以诈遇诈，犹有巧拙焉；以诈遇齐，辟之犹以锥刀堕太山也，非天下之愚人莫敢试。故王者之兵不试，汤、武之诛桀、纣也，拱挹指麾，而强暴之国莫不趋使，诛桀、纣若诛独夫。故《泰誓》曰：‘独夫纣’，此之谓也。故兵大齐则制天下，小齐则治邻敌，若夫招近募选，隆势诈，尚功利之兵，则胜不胜无常，代翕代张，代存代亡，相为雌雄耳矣。夫是之谓盗兵，君子不由也。故齐之田单，楚之庄？，秦之卫鞅，燕之缪虮，是皆世俗之所谓善用兵者也，是其巧拙强弱则未有以相君也，若其道一也，未及和齐也，掎契司诈，权谋倾覆，未免盗兵也。齐桓、晋文、楚庄、吴阖闾、越勾践，是皆和齐之兵也，可谓入其域矣，然而未有本统也；故可以霸而不可以王，是强弱之效也。”
孝成王、临武君曰：“善！请问为将。”
孙卿子曰：“知莫大乎弃疑，行莫大乎无过，事莫大乎无悔。事至无悔而止矣，成不可必也。故制号政令，欲严以威；庆赏刑罚，欲必以信；处舍收臧，欲周以固；徙举进退，欲安以重，欲疾以速；窥敌观变，欲潜以深，欲伍以参；遇敌决战，必道吾所明，无道吾所疑：夫是之谓六术。无欲将而恶废，无急胜而忘败，无威内而轻外，无见其利而不顾其害，凡虑事欲孰而用财欲泰：夫是之谓五权。所以不受命于主有三：可杀而不可使处不完，可杀而不可使击不胜，可杀而不可使欺百姓，夫是之谓三至。凡受命于主而行三军，三军既定，百官得序，群物皆正，则主不能喜，敌不能怒，夫是之谓至臣。虑必先事而申之以敬，慎终如始，终始如一，夫是之谓大吉。凡百事之成也必在敬之，其败也必在慢之，故敬胜怠则吉，怠胜敬则灭，计胜欲则从，欲胜计则凶。战如守，行如战，有功如幸，敬谋无圹，敬事无圹，敬吏无圹，敬众无圹，敬敌无圹，夫是之谓五无圹。慎行此六术、五权、三至，而处之以恭敬无圹，夫是之谓天下之将，则通于神明矣。”
临武君曰：“善！请问王者之军制。”
孙卿子曰：“将死鼓，御死辔，百吏死职，士大夫死行列，闻鼓声而进，闻金声而退，顺命为上，有功次之；令不进而进，犹令不退而退也，其罪惟均。不杀老弱，不躐禾稼，服者不禽，格者不舍，犇命者不获。凡诛，非诛其百姓也，诛其乱百姓者也；百姓有扞其贼，则是亦贼也。以故顺刃者生，苏刃者死，犇命者贡。微子开封于宋；曹触龙断于军；殷之服民，所以养生之者也，无异周人。故近者歌讴而乐之，远者竭蹶而趋之，无幽闲辟陋之国，莫不趋使而安乐之，四海之内若一家，通达之属莫不从服，夫是之谓人师。《诗》曰：“自西自东，自南自北，无思不服。”此之谓也。王者有诛而无战，城守不攻，兵格不击。上下相喜则庆之。不屠城，不潜军，不留众，师不越时，故乱者乐其政，不安其上，欲其至也。”
临武君曰：“善！”
陈嚣问孙卿子曰：“先生议兵，常以仁义为本。仁者爱人，义者循理，然则又何以兵为？凡所为有兵者，为争夺也。”
孙卿子曰：“非女所知也。彼仁者爱人，爱人，故恶人之害之也；义者循理，循理故恶人之乱之也。彼兵者，所以禁暴除害也，非争夺也。故仁人之兵，所存者神，所过者化，若时雨之降，莫不说喜。是以尧伐驩兜，舜伐有苗，禹伐共工，汤伐有夏，文王伐崇，武王伐纣，此四帝、两王皆以仁义之兵行于天下也。故近者亲其善，远方慕其德；兵不血刃，远迩来服，德盛于此，施及四极。《诗》曰：‘淑人君子，其仪不忒，’此之谓也。”
李斯问孙卿子曰：“秦四世有胜，兵强海内，威行诸侯，非以仁义为之也，以便从事而已。”
孙卿子曰：“非女所知也。女所谓便者，不便之便也；吾所谓仁义者，大便之便也。彼仁义者，所以修政者也，政修则民亲其上，乐其君，而轻为之死。故曰：凡在于君，将率，末事也。秦四世有胜，諰諰然常恐天下之一合而轧己也，此所谓末世之兵，未有本统也。故汤之放桀也，非其逐之鸣条之时也；武王之诛纣也，非以甲子之朝而后胜之也。皆前行素修也，此所谓仁义之兵也。今女不求之于本而索之于末，此世之所以乱也。
礼者，治辨之极也，强固之本也，威行之道也，功名之总也。王公由之，所以得天下也，不由，所以陨社稷也。故坚甲利兵不足以为胜，高城深池不足以为固，严令繁刑不足以为威，由其道则行，不由其道则废。楚人鲛革、犀兕以为甲，鞈如金石；宛钜铁釶，惨如蜂虿；轻利僄遬，卒如飘风，然而兵殆于垂沙，唐蔑死，庄□起，楚分而为三四。是岂无坚甲利兵也哉？其所以统之者非其道故也。汝、颍以为险，江、汉以为池，限之以邓林，缘之以方城，然而秦师至而鄢、郢举，若振槁然。是岂无固塞隘阻也哉？其所以统之者非其道故也。纣刳比干，囚箕子，为炮烙刑；杀戮无时，臣下懔然莫必其命，然而周师至而令不行乎下，不能用其民。是岂令不严、刑不繁也哉？其所以统之者非其道故也。古之兵，戈、矛、弓、矢而已矣，然而敌国不待试而诎；城郭不辨，沟池不拑，固塞不树，机变不张，然而国晏然不畏外而明内者，无它故焉，明道而钧分之，时使而诚爱之，下之和上也如影响，有不由令者然后诛之以刑。故刑一人而天下服，罪人不邮其上，知罪之在己也；是故刑罚省而威流，无它故焉，由其道故也。古者帝尧之治天下也。盖杀一人、刑二人而天下治。传曰：‘威厉而不试，刑错而不用。’此之谓也。
凡人之动也，为赏庆为之则见害伤焉止矣。故赏庆刑罚势诈不足以尽人之力，致人之死。为人主上者也，其所以接下之百姓者，无礼忠信，焉虑率用赏庆刑罚势诈险阸其下，获其功用而已矣。大寇则至，使之持危城则必畔，遇敌处战则必北，劳苦烦辱则必奔，霍焉离耳，下反制其上。故赏庆刑罚势诈之为道者，佣徒粥卖之道也，不足以合大众，美国家，故古之人羞而不道也。故厚德音以先之，明礼义以道之，致忠信以爱之，尚贤使能以次之，爵服庆赏以申之，时其事，轻其任以调齐之，长养之，如保赤子，政令以定，风俗以一。有离俗不顺其上，则百姓莫不敦恶，莫不毒孽，若祓不祥，然后刑于是起矣。是大刑之所加也，辱孰大焉？将以为利邪？则大刑加焉。身苟不狂惑戆陋，谁睹是而不改也哉！然后百姓晓然皆知修上之法，像上之志而安乐之，于是有能化善、修身、正行、积礼义、尊道德，百姓莫不贵敬，莫不亲誉，然后赏于是起矣。是高爵丰禄之所加也，荣孰大焉？将以为害邪？则高爵丰禄以持养之，生民之属，孰不愿也。雕雕焉县贵爵重赏于其前，县明刑大辱于其后，虽欲无化，能乎哉？故民归之如流水，所存者神，所为者化。而顺，暴悍勇力之属为之化而愿，旁辟曲私之属为之化而公，矜纠收缭之属为之化而调，夫是之谓大化至一。《诗》曰：‘王犹允塞，徐方既来。’此之谓也。
凡兼人者有三术：有以德兼人者，有以力兼人者，有以富兼人者。彼贵我名声，美我德行，欲为我民，故辟门除涂以迎吾入，因其民，袭其处，而百姓皆安，立法施令莫不顺比。是故得地而权弥重，兼人而兵俞强，是以德兼人者也。非贵我名声也，非美我德行也，彼畏我威，劫我势，故民虽有离心，不敢有畔虑，若是，则戎甲俞众，奉养必费。是故得地而权弥轻，兼人而兵俞弱，是以力兼人者也。非贵我名声也，非美我德行也，用贫求富，用饥求饱，虚腹张口来归我食；若是，则必发夫掌窌之粟以食之，委之财货以富之，立良有司以接之，已朞三年，然后民可信也。是故得地而权弥轻，兼人而国俞贫，是以富兼人者也。故曰：以德兼人者王，以力兼人者弱，以富兼人者贫。古今一也。
兼并易能也，唯坚凝之难焉。齐能并宋而不能凝也，故魏夺之；燕能并齐而不能凝也，故田单夺之；韩之上地，方数百里，完全富足而趋赵，赵不能凝也，故秦夺之。故能并之而不能凝，则必夺；不能并之又不能凝其有，则必亡。能凝之，则必能并之矣。得之则凝，兼并无强。古者汤以薄，武王以滈，皆百里之地也，天下为一，诸侯为臣，无它故焉，能凝之也。故凝士以礼，凝民以政；礼修而士服，政平而民安，士服民安，夫是之谓大凝。以守则固，以征则强，令行禁止，王者之事毕矣。”', '本篇阐述的是荀子的军事思想。在文中荀子指出，攻战之本在于得到人民的支持，最强大的军队是“仁人之兵”。军队的强弱取决于国家政治状况。将领要做到智能决疑，行能无过，临事果断。具体而言，就是要做到六术、五权、三至、五无圹。此外，军队还必须有严格的纪律，即“顺命为上，有功次之”。', '', '临武君和荀卿在赵孝成王面前议论用兵之道。
赵孝成王说：“请问用兵的要领是什么？”
临武君回答说：“上取得有利于攻战的自然气候条件，下取得地理上的有利形势，观察好敌人的变动情况，比敌人后行动但比敌人先到达，这就是用兵的要领。”
荀卿说：“不对。我所听说的古代的方法，大凡用兵打仗的根本在于使民众和自己团结一致。如果弓箭不协调，那么后羿也不能用它来射中微小的目标；如果六匹马不协调，那么造父也不能靠它们到达远方；如果民众不亲近归附君主，那么商汤、周武王也不能一定打胜仗。所以善于使民众归附的人，这才是善于用兵的人。所以用兵的要领就在善于使民众归附自己罢了。”
临武君说：“不对。用兵所看重的，是形势和条件有利；所施行的，是变化无常而诡诈的计谋和行动。善于用兵的人，神出鬼没，没有人知道他们是从什么地方出来的。孙武、吴起用了这种办法，因而无敌于天下。哪里一定要依靠使民众归附的办法呢？”
荀卿说：“不对。我所说的，是仁德之人的军队、是称王天下者的意志。您所看重的，是权变谋略、形势有利；所施行的，是攻取掠夺、机变诡诈的计谋和行动，这些都是诸侯干的事。仁德之人的军队，是不可能被欺诈的。那可以被欺诈的，只是一些懈怠大意的军队，羸弱疲惫的军队，君臣上下之间涣散而离心离德的军队。所以，用桀之类的人欺骗桀之类的人，还由于巧拙不同而有侥幸获胜的；用桀之类的人欺骗尧之类的人，拿它打个比方，就好像用鸡蛋掷石头、用手指搅开水，就好像投身水火、一进去就会被烧焦淹没的啊。
“所以，仁德之人上下之间，各位将领齐心一致，三军共同努力，臣子对君主，下级对上级，就像儿子侍奉父亲、弟弟侍奉兄长一样，就像手臂捍卫脑袋眼睛、庇护胸部腹部一样；所以用欺诈的办法袭击他与先惊动他之后再攻击他，那结果是一样的。况且仁德之人治理方圆十里的国家，就会了解到方圆百里的情况；治理方圆百里的国家，就会了解到方圆千里的情况；治理方圆千里的国家，就会了解到天下的情况；他的军队一定是耳聪目明、警惕戒备、协调团结而齐心一致的。所以，仁德之人的军队，集合起来就成为有组织的队伍；分散开来便成为整齐的行列；伸展开来就像莫邪宝剑那长长的刃口，碰到它的就会被截断；向前冲刺就像莫邪宝剑那锐利的锋芒，阻挡它的就会被击溃；摆成圆形的阵势停留或排成方形的队列站住，就像磐石一样岿然不动，触犯它的就会头破血流，就会稀里哗啦地败下阵来。
“再说那些强暴之国的君主，将和谁一起来攻打我们呢？从他那边来看，和他一起来的，一定是他统治下的民众；而他的民众亲爱我们就像喜欢自己的父母一样，他们热爱我们就像酷爱芳香的椒、兰一样，而他们回头看到他们的国君，却像看到了烧烤皮肤、刺脸涂墨一样害怕，就像看到了仇人一样愤怒；他们这些人的情性即使像夏桀、盗跖那样残暴贪婪，但哪有肯为他所憎恶的君主去残害他所喜爱的君主的人呢？这就好像让别人的子孙亲自去杀害他们的父母一样，他们一定会来告诉我们，那么我们又怎么可以被欺诈呢？
“所以，仁德之人当政，国家日益昌盛，诸侯各国先去归顺的就会安宁，迟去归顺的就会危险，想和他作对的就会削弱，背叛他的就会灭亡。《诗》云：‘商汤扬旗出征去，威严恭敬握大斧；就像熊熊列火烧，没有人敢阻挡我。’说的就是这种情况啊。”
赵孝成王、临武君说：“说得好。请问称王天下者的军队采用什么办法、采取什么行动才行？”
荀卿说：“一切都在于君主，将帅是次要的事。请让我来逐一述说帝王诸侯强盛、衰弱、存在、灭亡的效验和安定、危险的形势吧。君主贤能的，他的国家就安定；君主无能的，他的国家就混乱；君主崇尚礼法、看重道义的，他的国家就安定；君主怠慢礼法、鄙视道义的，他的国家就混乱。安定的国家强盛，混乱的国家衰弱，这是强盛与衰弱的根本原因。君主值得仰赖，那么臣民就能为他所用；君主不值得仰赖，那么臣民就不能为他所用。臣民能被他使用的就强盛，臣民不能被他使用的就衰弱，这是强盛与衰弱的常规。推崇礼法、考核战功，是上等的办法；看重利禄、推崇气节，是次一等的办法；崇尚战功、鄙视气节，是下等的办法，这些是导致强盛与衰弱的一般情况。君主喜欢贤士的就强盛，不喜欢贤士的就衰弱；君主爱护人民的就强盛，不爱护人民的就衰弱；政策法令有信用的就强盛，政策法令没有信用的就衰弱；民众齐心合力的就强盛，民众不齐心的就衰弱；奖赏慎重给人的就强盛，奖赏轻易给人的就衰弱；刑罚威严的就强盛，刑罚轻慢的就衰弱；器械、用具、兵器、盔甲精善坚固便于使用的就强盛，器械、用具、兵器、盔甲粗劣而不便于使用的就衰弱；谨慎用兵的就强盛，轻率用兵的就衰弱；指挥权出自一个人的就强盛，指挥权出自两个人的就衰弱，这些是强盛与衰弱的常规。
“齐国人推崇已勇力来斩杀敌人。具体的做法是：取得一个敌人首级的，就赐给他八两黄金来赎买，却没有战胜后所应颁发的奖赏。这种办法，如果战役小、敌人弱，那还勉强可以使用；如果战役大、敌人强，那么士兵就会涣散而逃离，像那乱飞的鸟一样，导致覆灭也就没有多久了。这是使国家灭亡的军队，没有比这更弱的军队了，这和那劳务市场上雇取佣工去让他们作战也就差不多了。
“魏国的武卒，根据一定的考试、考核标准来录取他们。具体的做法是：让他们穿上三种依次相连的铠甲，拿着拉力为十二石的弩弓，背着装有五十支箭的箭袋，把戈放在那上面，戴着头盔，佩带宝剑，带上三天的粮食，半天要奔走一百里。考试合格就免除他家的徭役，使他的田地住宅都处于便利的地方。这些待遇，即使几年以后他体力衰弱了也不可以剥夺，这边免除老兵的各种赋税，那边重新选取了武士又难以完全符合条件而投入战争。所以，国土虽然广大，但它的税收必定很少，这是使国家陷于危困的军队啊。
“秦国的君主，他使民众谋生的道路很狭窄、生活很穷窘，他使用民众残酷严厉，用权势威逼他们作战，用穷困使他们生计艰难而只能去作战，用奖赏使他们习惯于作战，用刑罚强迫他们去作战，使国内的民众向君主求取利禄的办法，除了作战就没有别的途径了；使民众穷困后再使用他们，得胜后再给他们记功，对功劳的奖赏随着功劳而增长，得到五个敌人士兵的首级就可以役使本乡的五户人家。这秦国要算是兵员最多、战斗力最强而又最为长久的了，又有很多土地可以征税。所以秦国四代都保持了强盛的局面，这并不是因为侥幸，而是有其必然性的。
“齐国的‘技击’不可以用来对付魏国的‘武卒’，魏国的‘武卒’不可以用来对付秦国的‘锐士’，秦国的‘锐士’不可以用来对付齐桓公、晋文公那有纪律约束的军队，齐桓公、晋文公那有纪律约束的军队不可以用来抵抗商汤、周武王的仁义之师；如果有抵抗他们的，就会像用枯焦烤干的东西扔在石头上一样。综合齐、魏、秦这几个国家来看，都是些追求奖赏、贪图利益的军队，这是受雇佣的人出卖气力、生命的办法，并不讲尊重君主、遵守礼义制度、极尽大义气节的道理。诸侯如果有谁能用仁义节操精细巧妙地来训导士兵的话，一举兵便可歼灭这些国家的军队。
“所以，招引、募求、挑选士兵的时候，注重权谋诡诈，崇尚功利，这是在欺骗士兵；讲求礼制道义教育感化，这才能使士兵齐心合力。用受骗的军队去对付受骗的军队，他们之间还有巧妙与拙劣之别，用受骗的军队去对付齐心合力的军队，拿它打个比方，就好像用小刀去毁坏泰山一样，如果不是天底下的傻子，是没有人敢尝试的。所以称王天下者的军队是没有人敢试与为敌的。商汤、周武王讨伐夏桀、商纣的时候，从容地指挥，而那些强横暴虐的诸侯国也没有不奔走前来供驱使的，除掉夏桀、商纣就好像除掉孤独的一个人一样。所以《泰誓》说：‘独夫纣。’说的就是这种情况啊。
“所以，军队能大规模地齐心合力，就能制服天下；小规模地齐心合力，就能打败邻近的敌国。至于那种招引募求挑选来的、注重权谋诡诈、崇尚功利的军队，那胜负就没有个定准了，有时衰，有时盛，有时保存，有时灭亡，互为高下、互有胜负罢了。这叫做盗贼式的军队，君子是不用这种军队的。
“齐国的田单，楚国的庄蹻，秦国的卫鞅，燕国的缪虮，这些都是一般人所说的善于用兵的人。这些人的巧妙、拙劣、强大、弱小尚不相上下，至于他们遵行的原则，却是一样的，他们都还没有达到使士兵和衷共济、齐心合力的地步，而只是抓住对方弱点伺机进行欺诈，玩弄权术阴谋进行颠覆，所以仍免不了是些盗贼式的军队。齐桓公、晋文公、楚庄王、吴王阖闾、越王勾践，这些人的军队就都是和衷共济、齐心合力的军队，可说是进入礼义教化的境地了，但还没有抓住那根本的纲领，所以可以称霸诸侯而不可以称王天下。这就是或强或弱的效验。”
孝成王、临武君说：“说得好。请问做将领的原则。”
荀卿说：“智慧没有比抛弃犹豫不决更高的了，行动没有比不犯错误更好的了，事情没有比毫无悔恨更美的了。做事到了没有后悔的地步就到顶了，不能要求它一定成功。所以制度、号召、政策、命令，要严肃而有威势；奖赏刑罚，要坚决实行而有信用；军队驻扎的营垒和收藏物资的军库，要周密而坚固；转移、发动、进攻、撤退，既要安全而稳重，又要紧张而迅速；侦探敌情、观察其变动，既要隐蔽而深入，又要多方比较而反复检验；遇到敌人进行决战，一定要根据自己已了解清楚的情况去行动，不要根据自己怀疑的情况去行动。以上这些叫做六种策略。不要热衷于当将军而怕罢免，不要急于求胜而忘记了有可能失败，不要只以为自己有威力而轻视外敌，不要看见了那有利的一面而不顾那有害的一面，凡是考虑事情要仔细周详而使用财物进行奖赏时要慷慨大方。这些叫做五种要权衡的事。所以，将领不从君主那里接受命令的原因有三种：宁可被杀而不可使自己的军队驻扎在守备不完善的地方，宁可被杀而不可使自己的军队打注定无法取胜的仗，宁可被杀而不可使自己的军队去欺负老百姓。这叫做三条最高的原则。大凡从君主那里接受了命令就巡视三军，三军已经稳定，各级军官得到了合适的安排，各方面的事务都步入了正规，那么君主的奖赏就不能使他沾沾自喜，敌人的奸计就不能使他愤怒，这叫做最合格的将领。一定在战事之前深思熟虑，并且反复告诫自己要慎重，慎重地对待结束就像开始时一样，始终如一，这叫做最大的吉利。大凡各种事情成功一定在于慎重，失败一定在于怠慢，所以慎重胜过怠慢就吉利，怠慢胜过慎重就灭亡，冷静的谋划胜过冲动的欲望就顺利，冲动的欲望胜过冷静的谋划就凶险。攻战要像防守一样不轻率追击，行军要像作战一样毫不松懈，有了战功要像侥幸取得的一样不骄傲自满。慎重对待谋划而不要大意，慎重对待战事而不要大意，慎重对待军吏而不要大意，慎重对待士兵而不要大意，慎重对待敌人而不要大意。这叫做五种不大意。谨慎地根据这六种策略、五种权衡、三条最高原则办事，并且用恭敬而不大意的态度来处理一切，这叫做举世无双的将领，他就能与神明相通了。”
临武君说：“说得好。请问称王天下者的军队制度。”
荀卿说：“将军击鼓指挥军队前进时，致死不能后退，驾驭战车的人至死不能丢掉缰绳，各级官吏致死不能离开自己的职守，士大夫至死不能离开队列。听见战鼓的声音就前进，听见钲、铙的声音就后退；服从命令是最重要的，取得战功在其次；命令不准前进却前进，就像命令不准后退却后退一样，它们的罪过是相同的。不杀害年老体弱的，不践踏庄稼，对不战而退的敌人不追擒，对顽固抵抗的敌人不放过，对前来投顺的不抓起来当俘虏。凡是讨伐杀戮，不是去讨伐杀戮那百姓，而是去讨伐杀戮那扰乱百姓的人。百姓如果有保护那乱贼的，那么他也就是乱贼了。因为这个缘故，所以顺着我们的刀锋转身逃跑的就让他活命，对着我们的刀锋进行抵抗的就把他杀死，前来投顺的就赦免其罪。微子启归顺周朝而被封在宋国，曹触龙负隅顽抗而被斩首于军中，商王朝那些降服周朝的民众用来养身的生活资料，和周朝的人没有什么两样。所以，近处的人歌颂周朝而且热爱周朝，远处的人竭尽全力地来投奔周朝，即使是幽隐闭塞偏僻边远的国家，也无不前来归附而听从役使，并且喜欢周朝，四海之内就像一个家庭似的，凡是交通能到达的地方，没有谁不服从，这可以称作是人民的君长了。《诗经》上说：‘从那西边又从东，从那南边又从北，没有哪个不服从。’说的就是这种情况。称王天下的君主有讨伐而没有攻战，敌城坚守时不攻打，敌军抵抗时不攻击，敌人官兵上下相亲相爱就为他们庆贺，不摧毁城郭而屠杀居民，不秘密出兵搞偷袭，不留兵防守占领的地方，军队出征不超过预先约定的时限。所以政治混乱的国家中的人民都喜欢他的这些政策，而不爱自己的君主，都希望他的到来。”
临武君说：“说得好！”
陈嚣问荀卿说：“先生议论用兵，经常把仁义作为根本。仁者爱人，义者遵循道理，既然这样，那么又为什么要用兵呢？大凡用兵的原因，是为了争夺啊。”
荀卿说：“这道理不是你所知道的。那仁者爱人，正因为爱人，所以就憎恶别人危害他们；义者遵循道理，正因为遵循道理，所以就憎恶别人搞乱它。那用兵，是为了禁止横暴、消除危害，并不是争夺啊。所以仁人的军队，他们停留的地方会得到全面治理，他们经过的地方会受到教育感化，就像及时雨的降落，没有人不欢喜的。因此尧讨伐驩兜，舜讨伐三苗，禹讨伐共工，汤讨伐夏桀，周文王讨伐崇国，周武王讨伐商纣，这两帝、四王都是使用仁义的军队驰骋于天下的。所以，近处喜爱他们的善良，远方仰慕他们的道义；兵器的刀口上还没有沾上鲜血，远近的人就来归附了；德行伟大到这种地步，就会影响到四方极远的地方。《诗经》上说：‘善人君子忠于仁，坚持道义不变更。他的道义不变更，四方国家他坐镇。’说的就是这种情况啊。”
李斯问荀卿说：“秦国四代都保持了强盛的局面，在四海之内兵力最强，威力扩展到诸侯各国，但他们并不是依靠仁义去从事战争，而只是根据便利的原则去做罢了。”
荀卿说：“这道理不是你所知道的。你所说的便利，是一种并不便利的便利。我所说的仁义，才是极其便利的便利。那仁义，是用来搞好政治的工具；政治搞好了，那么民众就会亲近他们的君主，喜爱他们的君主，而不在乎为君主去牺牲。所以说：‘一切都在于君主，将帅是次要的事。’秦国四代都保持了强盛的局面，却还是提心吊胆地经常怕天下各国团结一致来蹂躏自己，这就是人们所说的混乱时代的军队，还没有抓住根本的纲领。从前商汤流放夏桀，并不只是在鸣条大战的时候；武王诛杀商纣，并不是甲子日早晨之后才战胜他的；而都是靠一贯地坚持施行了仁义，实行了教化的结果，这就是我所说的仁义的军队。现在你不从根本上去寻找原因而只是从枝节上去探索缘由，这就是社会混乱的原因。”
礼，是治理社会的最高准则，是使国家强大的根本措施，是威力得以扩展的有效办法，是功业名声得以成就的要领。天子诸侯遵行了它，所以能取得天下；不遵行它，所以会丢掉国家政权。所以，坚固的铠甲、锋利的兵器不足以用来取胜，高耸的城墙、深深的护城河不足以用来固守，严格的命令、繁多的刑罚不足以用来造成威势，遵行礼义之道才能成功，不遵行礼义之道就会失败。
楚国人用鲨鱼皮、犀兕皮做成铠甲，坚硬得就像金属、石头一样；宛地出产的钢铁长矛，狠毒得就像蜂、蝎的毒刺一样；士兵行动轻快敏捷，迅速得就像旋风一样；但是兵败垂沙，唐蔑阵亡；庄蹻起兵造反，楚国被分裂成了三四块。这难道是因为没有坚固的铠甲、锋利的兵器吗？这是因为他们用来统治国家的办法并不是礼义之道的缘故啊。楚国以汝水、颍水作为天险，以长江、汉水作为护城河，把邓地一带的山林作为它的边界屏障，拿方城来围绕保护自己，但是秦军一到而鄢、郢就被攻取了，像摧枯拉朽一样。这难道是因为没有要塞险阻吗？这是因为他们用来统治国家的办法，并不是礼义之道的缘故啊。商纣王将比干剖腹挖心，囚禁了箕子，设置了炮烙的酷刑，随时杀人，臣下心惊胆战地没有谁能肯定自己会寿终正寝，但是周军一到，他的命令就不能在下面贯彻执行了，他就不能使用他的民众了。这难道是因为命令不严厉、刑罚不繁多吗？不是的，这是因为他用来统治国家的办法并不是礼义之道的缘故啊。
古代圣王的兵器，不过是戈、矛、弓、箭罢了，但是敌国不等他使用就屈服了；他城墙不整修，护城河不挖掘，要塞不建立，机智变诈不施展，但是他的国家却平安无事地不怕外敌而又能昌盛，这没有其他的缘故，是由于彰明了礼义之道而用名分来协调臣民，适时使用人民而真诚地爱护他们，因而臣民附和君主就像影子和回响声音一样。有不遵从命令的，然后再用刑罚来惩处他，所以惩罚了一个人而天下都服了，罪犯也不怨恨自己的君主，知道罪责在自己身上。所以刑罚用得少而威力却行于四方，这没有其他的缘故，是因为遵行了礼义之道的缘故。古代帝尧治理天下，只杀了一个人、惩罚了两个人而天下就治理好了。古书说：“威势高举而不使用，刑罚设置而不施行。”说的就是这种情况啊。
大凡人们的行动，如果是为了赏赐和表扬才去做的，那么看见对自己有损害就罢手不干了。所以赏赐表扬、刑罚处置、权谋诡诈不足以竭尽人们的力量、使人们为君主献出生命。现在做君主的，他们用来对待下面老百姓的，不是礼义忠信，而仅仅试图使用赏赐表扬、刑罚处置、权谋诡诈控制臣民，使他们贫困而走投无路，因而不得不靠战争拼命立功以求获得君主的赏赐而已。强大的敌寇到来，让他们去把守危险的城邑，就一定会叛变；让他们去抵抗敌人进行战斗，就一定会败北；让他们干费力艰苦繁杂的事，就一定会逃跑；他们涣散地背离了，臣民反过来制裁了他们的君主。
所以，赏赐表扬、刑罚处置、权谋诡诈这些办法，实是一种受雇佣的人出卖气力的办法，它不足以团结广大民众、使国家的风俗淳美，所以古代的圣王认为可耻而不遵行它。古代的圣王提高道德声誉来引导人民，彰明礼制道义来指导他们，尽力做到忠诚守信来爱护他们，根据尊崇贤人、任用能人的原则来安排他们职位，用爵位、服饰、表扬、赏赐去一再激励他们，根据时节安排他们的劳动、减轻他们的负担来调剂他们，抚养他们，就像保护初生的婴儿一样。
政策法令已经确定，风气习俗已经一致，如果还有人违背习俗而不顺从自己的君主，那么百姓就没有谁不怨恨厌恶他，就没有谁不把他当作祸害妖孽，就像要驱除祸害妖孽一样要除掉他，这种情况发生以后，刑罚就从此产生了。这种人便是重刑所施加的对象，耻辱还有哪一种比这个更大的呢？要把它看作为有利的事吗？但是重刑加到了他身上啊。本身如果不是发疯、糊涂、愚蠢、浅陋的人，谁能看到了这种处罚而不改过自新呢？这样做了以后，百姓就明明白白地都知道要遵从君主的法令、依顺君主的意志而爱戴君主。在这种情况下，如果有人能被善道所感化、修养身心、端正品行、不断奉行礼义、崇尚道德，百姓就没有谁不器重尊敬他，就没有谁不亲近赞誉他，这种情况发生以后，奖赏就从此产生了。这种人便是高官厚禄的授予对象，光荣还有哪一种比这个更大的呢？要把它看作为有害的事吗？可是用高官厚禄来扶养他们的啊。凡是人，哪一个不愿意这样呢？明明白白地把高贵的官爵和优厚的奖赏摆在他们的前面，把彰明罪行的刑罚与最大的耻辱放在他们的后面，即使要他们不变好，可能么？所以民众归顺投奔君主就像流水奔向大海一样，君主所在的地方就得到全面的治理，君主采取措施的地方人们都受到教育感化而顺服。残暴、凶狠、胆大、强壮的一类人都会被他感化而变得忠厚老实，偏颇、邪僻、搞歪门邪道、偏私的一类人都会被他感化而变得大公无私，骄傲自大、尖刻伤人、竞抢不让、纠缠不休的一类人都会被他感化而变得和气温顺，这叫做深广的教化、极大的一致。《诗经》上说：“王道真大满四海，徐国已经来朝拜。”说的就是这种情形啊。
大凡兼并别国的君主有三种方法：有依靠德行去兼并别国的，有依靠强力去兼并别国的，有依赖财富去兼并别国的。
那个国家的人民景仰我的名声，赞赏我的德行，想做我的臣民，所以打开国门清除道路来迎接我进城。我依靠这国家的民众，沿用它的住处，而百姓都安宁，对我制订的法律与颁布的命令没有人不顺从。所以得到了土地而权势更大，兼并了别国而兵力越来越强。这是依靠德行去兼并别国的君主。
那个国家的人民并不是景仰我的名声，也不是赞赏我的德行，他们只是害怕我的威武，被我的势力所胁迫，所以他们虽然有离开我的心思，也不敢有背叛我的打算。像这样，那么战士就要越来越多，给养一定化费很大。所以得到了土地而权势更轻，兼并了别国而兵力越来越弱。这是依靠强力去兼并别国的君主。
那个国家的人民并不是景仰我的名声，也不是赞赏我的德行，而是因为贫穷而追求富裕，因为饥饿而想吃饱，所以空着肚子张着嘴来投奔我求食。像这样，就必须发放那米仓地窖中的粮食来供养他们，给他们财物来使他们富足，委任善良的官吏来接待他们，已经满了三年，然后这些归附的老百姓才可以信任。所以得到了土地而权势更轻，兼并了别国而国家越来越贫穷。这是依靠财富去兼并别国的君主。
所以说：依靠德行兼并别国的君主称王，依靠强力兼并别国的君主衰弱，依靠财富兼并别国的君主贫穷。这种情况古今是一样的。
兼并别国容易做到，只是巩固保持它很难。齐国能够兼并宋国，但不能保持巩固它，所以魏国夺走了宋国；燕国能兼并齐国，但不能保持巩固它，所以田单夺回了它；韩国的上党地区，方圆几百里，城池完备、府库充足而投奔赵国，赵国不能保持巩固它，所以秦国夺取了它。所以，能兼并别国的土地而不能保持巩固团结他们，就一定会被夺走；不能兼并别国又不能保持巩固自己本来拥有的国家，就一定会灭亡。能保持巩固自己的国家，就一定能兼并别国了。得到别国的土地就能保持巩固，那么再去兼并就不会有强大而不能兼并的对手了。古代商汤凭借亳，周武王凭借鄗，都不过是方圆百里的领土，而天下被他们统一了，诸侯做了他们的臣属，这没有其他的缘故，是因为他们能保持巩固取得的土地啊。凝聚士人要依靠礼义，凝聚民众要依靠政策。礼义搞好了，士人就会归服；政治清明，民众就安定。士人归服、民众安定，这叫做最大的凝聚。靠这种政治局面来守卫就牢不可破，靠它来出征就强大无比，有令必行，有禁必止，称王天下者的事业就完成了。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d8dbb8b379ee0a1494", "shortContent": "刘向是我国第一位校雠学家。他将当时所有的各种书籍，逐一校对，成为定本。每一部书校完之后，都要写一篇文章介绍情况或加评论，奏上皇帝。后来把这些文章集成《别录》，可以说是我国古书的第一部“书目提要”。向死之后，儿子歆，继承父业，写成《七略》，后来班固修《汉书·艺文志》就是根据《七略》，成为今存目录学最早的一部著作。当时外戚专权，刘向是汉的宗室，他总是利用一切机会上书匡谏皇帝，又把古代一些值得借鉴的小故...", "authors": ["周本淳"], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3b2", "shortContent": "这里是说治国与享乐的关系。荀子认为，君主应该先治国，后享乐，而不应先享乐，后治国。先治国，为国家的一切事业打好物质基础，享乐亦自然随之。如果一开始就纵情享乐，将国事拋在一边，那最终就会导致亡国。\n\n人究竟应不应该享乐？这向来是一个争论不休的问题。对待“乐”的态度一般有三种：纵之，禁之，节之。“节”的态度看起来是最明智的。但是，这个“节”的“度”该怎么把握呢？\n\n中国古人处理这个问题的方法与这三种态...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3b3", "shortContent": "这句话出自《荀子·议兵》。荀子和临武君在赵孝成王面前讨论用兵之道，临武君认为天时、地利或是权谋变诈才是用兵要道，荀子反驳说这都不如用仁心使人民归附自己，君臣一心，军民同力，“故仁人之兵聚则成卒，散则成列，延则若莫邪之长刃，婴之者断，兑则若莫邪之利锋，当之者溃，圜居而方止，则若盘石然，触之者角摧”（《议兵》），这样的军队自然战无不胜，所向披靡。\n\n荀子认为国家的强弱取决于很多因素，其中最重要的莫过于...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1545320527, '5c1b47da808ca400672f1be0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640782, '洪范传', NULL, 4, 1836, 1, 1, '王安石', NULL, 10067, '57b93713c4c971005590f52a', '宋', 'wen', '文', '', '', '五行，天所以命万物者也，故“初一曰五行”。五事，人所以继天道而成性者也，故“次二曰敬用五事”。五事，人君所以修其心、治其身者也，修其心，治其身，而后可以为政于天下，故“次三曰农用八政”。为政必协之岁、月、日、星辰、曆数之纪，故“次四曰协用五纪”。既协之岁、月、日、星辰、曆数之纪，当立之以天下之中，故“次五曰建用皇极”。中者，所以立本，而未足以趣时，趣时则中不中无常也，唯所施之宜而已矣，故“次六曰用三德”。有皇极以立本，有三德以趣时，而人君之能事具矣。虽然，天下之故犹不能无疑也。疑则如之何？谋之人以尽其智，谋之鬼神以尽其神，而不专用己也，故“次七曰明用稽疑”。虽不专用己而参之于人物、鬼神，然而反身不诚不善，则明不足以尽人物，幽不足以尽鬼神，则其在我者不可以不思。在我者，其得失微而难知，莫若质诸天物之显而易见，且可以为戒也，故“次八曰念用庶证”。自五事至于庶证各得其序，则五福之所集，自五事至于庶证各失其序，则六极之所集，故“次九曰向用五福，威用六极”。敬者何？君子所以直内也，言五事之本在人心而已。农者何？厚也，言君子之道施于有政，取诸此以厚彼而已。有本以保常而后可立也，故皇极曰建。有变以趣时，而后可治也，故三德曰，向者，慕而欲其至也；威者，畏而欲其亡也。
“五行，一曰水，二曰火，三曰木，四曰金，五曰土”，何也？五行也者，成变化而行鬼神，往来乎天地之间而不穷者也，是故谓之行。天一生水，其于物为精，精者，一之所生也。地二生火，其于物为神，神者，有精而后从之者也。天三生木，其于物为魂，魂从神者也。地四生金，其于物为魄，魄者，有魂而后从之者也。天五生土，其于物为意，精神魂魄具而后有意。自天一至于天五，五行之生数也。以奇生者成而耦，以耦生者成而奇，其成之者皆五。五者，天数之中也，盖中者所以成物也。道立于两，成于三，变于五，而天地之数具。其为十也，耦之而已。盖五行之为物，其时，其位，其材，其气，其性，其形，其事，其情，其色，其声，其臭，其味，皆各有耦，推而散之，无所不通。一柔一刚，一晦一明，故有正有邪，有美有恶，有丑有好，有凶有吉，性命之理、道德之意皆在是矣。耦之中又有耦焉，而万物之变遂至于无穷。其相生也，所以相继也；其相克也，所以相治也。语器也以相治，故序六府以相克；语时也以相继，故序盛德所在以相生。《洪范》语道与命，故其序与语器与时者异也。道者，万物莫不由之者也。命者，万物莫不听之者也。器者，道之散，时者，命之运。由于道，听于命而不知者，百姓也；由于道，听于命而知之者，君子也。道万物而无所由，命万物而无所听，唯天下之至神为能与于此。夫火之于水，妻道也；其于土，母道也。故神从志，无志则从意。志致一之谓精，唯天下之至精，为能合天下之至神。精与神一而不离，则变化之所为在我而已。是故能道万物而无所由，命万物而无所听也。
“水曰润下，火曰炎上，木曰曲直，金曰从革，土爰稼穑”，何也？北方阴极而生寒，寒生水，南方阳极而生热，热生火，故水润而火炎，水下而火上。东方阳动以散而生风，风生木。木者，阳中也，故能变，能变，故曲直。西方阴止以收而生燥，燥生金。金者，阴中也，故能化，能化，故从革。中央阴阳交而生湿，湿生土。土者，阴阳冲气之所生也，故发之而为稼，敛之而为穑。曰者，所以命其物。爰者，言于之稼穑而已。润者，性也。炎者，气也。上下者，位也。曲直者，形也。从革者，材也。稼穑者，人事也。冬，物之性复，复者，性之所，故于水言其性。夏，物之气交，交者，气之时，故于火言其气。阳极上，阴极下，而后各得其位，故于水火言其位。春，物之形着，故于木言其形。秋，物之材成，故于金言其材。中央，人之位也，故于土言人事。水言润，则火，土溽，木敷，金敛，皆可知也。火言炎，则水洌，土，木温，金凊，皆可知也。水言下，火言上，则木左，金右，土中央，皆可知也。推类而反之，则曰后，曰前，曰西，曰东，曰北，曰南，皆可知也。木言曲直，则土圜，金方，火锐，水准，皆可知也。金言从革，则木变，土化，水因，火革，皆可知也。土言稼穑，则水之井洫，火之爨冶，木、金之为械器，皆可知也。所谓木变者何？灼之而为火，烂之而为土，此之谓变。所谓土化者何？能能润，能敷能敛，此之谓化。所谓水因者何？因甘而甘，因苦而苦，因苍而苍，因白而白，此之谓因。所谓火革者何？革生以为熟，革柔以为刚，革刚以为柔，此之谓革。金亦能化，而命之曰从革者何？可以圜，可以平，可以锐，可以曲直，然非火革之，则不能自化也，是故命之曰从革也。夫金，阴精之纯也，是其所以不能自化也。盖天地之用五行也，水施之，火化之，木生之，金成之，土和之。施生以柔，化成以刚，故木挠而水弱，金坚而火悍，悍坚而济以和，万物之所成也，奈何终于挠弱而欲以收成物之功哉？
“润下作咸，炎上作苦，曲直作酸，从革作辛，稼穑作甘”，何也？寒生水，水生咸，故润下作咸。热生火，火生苦，故炎上作苦。风生木，木生酸，故曲直作酸。燥生金，金生辛，故从革作辛。湿生土，土生甘，故稼穑作甘。生物者，气也；成之者，味也。以奇生则成而耦，以耦生则成而奇。寒之气坚，故其味可用以绥；热之气，故其味可用以坚。风之气散，故其味可用以收；燥之气收，故其味可用以散。土者，冲气之所生也，冲气则无所不和，故其味可用以绥而已。气坚则壮，故苦可以养气，脉则和，故咸可以养脉；骨收则强，故酸可以养骨；筋散则不挛，故辛可以养筋；肉缓则不壅，故甘可以养肉。坚之而后可以，收之而后可以散；欲缓则用甘，不欲则弗用也。古之养生治疾者，必先通乎此，不通乎此而能已人之疾者，盖寡矣。
“五事，一曰貌，二曰言，三曰视，四曰听，五曰思。貌曰恭，言曰从，视曰明，听曰聪，思曰睿。恭作肃，从作，明作哲，聪作谋，睿作圣”，何也？恭则貌钦，故作肃；从则言顺，故作；明则善视，故作哲；聪则善听，故作谋；睿则思无所不通，故作圣。五事以思为主，而貌最其所后也，而其次之如此，何也？此言修身之序也。恭其貌，顺其言，然后可以学而至于哲。既哲矣，然后能听而成其谋。能谋矣，然后可以思而至于圣。思者，事之所成终而所成始也，思所以作圣也。既圣矣，则虽无思也，无为也，寂然不动，感而遂通天下之故可也。
“八政，一曰食，二曰货，三曰祀，四曰司空，五曰司徒，六曰司寇，七曰宾，八曰师”，何也？食货，人之所以相生养也，故一曰食，二曰货。有相生养之道，则不可不致孝于鬼神，而着不忘其所自，故三曰祀。有所以相生养之道，而知不忘其所自，然后能保其居，故四曰司空。司空所以居民，民保其居，然后可教，故五曰司徒。司徒以教民，教之不率，然后俟之以刑戮，故六曰司寇。自食货至于司寇，而治内者具矣，故七曰宾，八曰师。宾所以接外治，师所以接外乱也。自食货至于宾师，莫不有官以治之，而独曰司空、司徒、司寇者，言官则以知物之有官，言物则以知官之有物也。
“五纪，一曰岁，二曰月，三曰日，四曰星辰，五曰曆数”，何也？王省惟岁，卿士惟月，师尹惟日，上考之星辰，下考之曆数，然后岁月日时不失其政，故一曰岁，二曰月，三曰日，四曰星辰，五曰曆数。曆者，数也；数者，一二三四是也，五纪之所成终而所成始也，非特曆而已。先王之举事也，莫不有时；其制物也，莫不有数。有时，故莫敢废；有数，故莫敢逾。盖尧舜所以同律度量衡，协时月正日，而天下治者，取诸此而已。
“皇极，皇建其有极，敛时五福，用敷锡厥庶民”，何也？皇，君也；极，中也。言君建其有中，则万物得其所，故能集五福以敷锡其庶民也。
“惟时厥庶民，于汝极，锡汝保极”，何也？言庶民以君为中，君保中，则民与之也。
“凡厥庶民，无有淫朋，人无有比德，惟皇作极”，何也？言君中则民人中也。庶民无淫朋，人无比德者，惟君为中而已。盖君有过行偏政，则庶民有淫朋，人有比德矣。“凡厥庶民，有猷，有为，有守，汝则念之，不协于极，不罹于咎，皇则受之，而康而色，曰予攸好德，汝则锡之福，时人斯其惟皇之极”，何也？言民之有猷、有为、有守，汝则念其所猷、所为、所守之当否。所猷、所为、所守不协于极，亦不罹于咎，君则容受之，而康汝颜色而诱之。不协于极，不罹于咎，虽未可以锡之福，然亦可教者也，故当受之而不当谴怒也。《诗》曰“载色载笑，匪怒伊教”，康而色之谓也。其曰我所好者德，则是协于极，则非但康汝颜色以受之，又当锡之福以劝焉。如此，则人惟君之中矣。不言“攸好德，则锡之福”，而言“曰予攸好德，则锡之福”，何也？谓之皇极，则不为已甚也。攸好德，然后锡之福，则获福者寡矣，是为已甚，而非所以劝也。曰予攸好德，则锡之福，则是苟革面以从吾之攸好者，吾不深探其心，而皆锡之福也。此之谓皇极之道也。
“无虐茕独，而畏高明”，何也？言苟曰好德，则虽茕独，必进宠之而不虐；苟曰不好德，则虽高明，必罪废之而不畏也。盖茕独也者，众之所违而虐之者也；高明也者，众之所比而畏之者也。人君蔽于众，而不知自用其福威，则不期虐茕独，而茕独实见虐矣，不期畏高明，而高明实见畏矣。茕独见虐而莫劝其作德，则为善者不长；高明见畏而莫惩其作伪，则为恶者不消。善不长，恶不消，人人离德作伪，则大乱之道也。然则虐茕独而宽朋党之多，畏高明而忽卑晦之贱，最人君之大戒也。
“人之有能、有为，使羞其行，而邦其昌”，何也？言有能者，使在职而羞其材，有为者，使在位而羞其德，则邦昌也。人君孰不欲有能者羞其材，有为者羞其德，然旷千数百年而未有一人致此，盖聪不明而无以通天下之志，诚不至而无以通天下之德，则智以难知，而为愚者所诎，贤以寡助，而为不肖者所困，虽欲羞其行，不可得也。通天下之志在穷理，同天下之德在尽性。穷理矣，故知所谓咎而弗受，知所谓德而锡之福；尽性矣，故能不虐茕独以为仁，不畏高明以为义。如是，则愚者可诱而为智也，虽不可诱而为智，必不使之诎智者矣；不肖者可革而为贤也，虽不可革而为贤，必不使之困贤者矣。夫然后有能、有为者得羞其行，而邦赖之以昌也。
“凡厥正人，既富方谷，汝弗能使有好于而家，时人斯其辜”，何也？言凡正人之道，既富之然后善。虽然，徒富之亦不能善也，必先治其家，使人有好于汝家，然后人从汝而善也。汝弗能使有好于汝家，则人无所视效，而放僻邪侈亦无不为也。盖人君能自治，然后可以治人；能治人，然后人为之用；人为之用，然后可以为政于天下。为政于天下者，在乎富之、善之，而善之，必自吾家人始。所谓自治者，“惟皇作极”是也；所谓治人者，“弗协于极，弗罹于咎，皇则受之，而康而色，曰予攸好德，汝则锡之福，无虐茕独，而畏高明”是也；所谓人为之用者，“有能、有为，使羞其行，而邦其昌”是也；所谓为政于天下者，“凡厥正人”是也。既曰能治人，则人固已善矣，又曰富之然后善，何也？所谓治人者，教化以善之也；所谓富之然后善者，政以善之也。徒教化不能使人善，故继之曰“凡厥正人，既富方谷”；徒政亦不能使人善，故卒之曰“汝弗能使有好于而家，时人斯其辜”也。“于其无好德，汝虽锡之福，其作汝用咎”，何也？既言治家不善不足以正人也，又言用人不善不足以正身，言崇长不好德之人而锡之福，亦用咎作汝而已矣。
“无偏无陂，遵王之义；无有作好，遵王之道；无有作恶，遵王之路；无偏无党，王道荡荡；无党无偏，王道平平；无反无侧，王道正直；会其有极，归其有极。曰皇极之敷言，是彝是训，于帝其训”，何也？言君所以虚其心，平其意，唯义所在，以会归其有中者。其说以为人君以中道布言，是以为彝、是以为训者，于天其训而已。夫天之为物也，可谓无作好，无作恶，无偏无党，无反无侧，会其有极，归其有极矣。荡荡者，言乎其大；平平者，言乎其治。大而治，终于正直，而王道成矣。无偏者，言乎其所居；无党者，言乎其所与。以所居者无偏，故能所与者无党，故曰“无偏无党”；以所与者无党，故能所居者无偏，故曰“无党无偏”。偏不已，乃至于侧；陂不已，乃至于反。始曰“无偏无陂”者，率义以治心，不可以有偏陂也；卒曰“无反无侧”者，及其成德也，以中庸应物，则要之使无反侧而已。路，大道也；正直，中德也。始曰“义”，中曰“道”、曰“路”，卒曰“正直”，尊德性而道问学，致广大而尽精微，极高明而道中庸之谓也。孔子以为“示之以好恶，而民知禁”，今曰“无有作好，无有作恶”者，何也？好恶者，性也，天命之谓性。作者，人为也，人为则与性反矣。《书》曰：“天命有德，五服五章哉；天讨有罪，五刑五用哉。”命有德，讨有罪，皆天也，则好恶者岂可以人为哉？所谓示之以好恶者性而已矣。
“凡厥庶民，极之敷言，是训是行，以近天子之光。曰天子作民父母，以为天下王”，何也？言凡厥庶民，以中道布言，“是训是行，以近天子之光”者，其说以为天子作民父母以为天下王，当顺而比之，以效其所为，而不可逆。盖君能顺天而效之，则民亦顺君而效之也。二帝、三王之诰命，未尝不称天者，所谓“于帝其训”也，此人之所以化其上也。及至后世，矫诬上天以布命于下，而欲人之弗叛也，不亦难乎？
“三德，一曰正直，二曰刚克，三曰柔克”，何也？直而不正者有矣，以正正直，乃所谓正也；曲而不直者有矣，以直正曲，乃所谓直也。正直也者，变通以趣时，而未离刚柔之中者也。刚克也者，刚胜柔者也；柔克也者，柔胜刚者也。
“平康正直，强弗友刚克，燮友柔克”，何也？燮者，和孰上之所为者也；友者，右助上之所为者也；强者，弗柔从上之所为者也；弗友者，弗右助上之所为者也。君君臣臣，适各当分，所谓正直也。若承之者，所谓柔克也；若威之者，所谓刚克也。盖先王用此三德，于一颦一笑，未尝或失，况以大施于庆赏刑威之际哉！故能为之其未有也，治之其未乱也。
“沉潜刚克，高明柔克”，何也？言人君之用刚克也，沉潜之于内；其用柔克也，发见之于外。其用柔克也，抗之以高明；其用刚克也，养之以卑晦。沉潜之于内，所以制奸慝；发见之于外，所以昭忠善。抗之以高明，则虽柔过而不废；养之以卑晦，则虽刚过而不折。《易》曰：“道有变动，故曰爻；爻有等，故曰物；物相杂，故曰文；文不当，故吉凶生焉。”吉凶之生，岂在夫大哉？盖或一颦一笑之间而已。《洪范》之言三德，与《舜典》、《皋陶谟》所序不同，何也？《舜典》所序以教胄子，而《皋陶谟》所序以知人臣，故皆先柔而后刚；《洪范》所序，则人君也，故独先刚而后柔。至于正直，则《舜典》、《洪范》皆在刚柔之先，而《皋陶谟》乃独在刚柔之中者，教人、治人，宜皆以正直为先，至于序德之品，则正直者中德也，固宜在柔刚之中也。
“惟辟作福、惟辟作威、惟辟玉食。臣无有作福、作威、玉食。臣之有作福、作威、玉食，其害于而家，凶于而国，人用侧颇僻，民用僭忒”，何也？执常以事君者，臣道也；执权以御臣者，君道也。三德者，君道也。作福，柔克之事也；作威，刚克之事也。以其侔于神天也，是故谓之福。作福以怀之，作祸以威之，言作福则知威之为祸，言作威则知福之为怀也。皇极者，君与臣民共由之者也。三德者，君之所独任而臣民不得僭焉者也。有其权，必有礼以章其别，故惟辟玉食也。礼所以定其位，权所以固其政，下僭礼则上失位，下侵权则上失政，上失位则亦失政矣。上失位失政，人所以乱也。故臣之有作福、作威、玉食，其害于而家，凶于而国，人用侧颇僻，民用僭忒也。侧颇僻者，臣有作福、作威之效也；僭忒者，臣有玉食之效也。民侧颇僻也易，而其僭忒也难。民僭忒，则人可知也；人侧颇僻，则民可知也。其曰“庶民有淫朋，人有比德”，亦若此而已矣。于淫朋曰庶民，于僭忒曰民而已，何也？僭忒者，民或有焉，而非众之所能也。天子、皇、王、辟，皆君也，或曰天子，或曰皇，或曰王，或曰辟，何也？皇极于帝其训者，所以继天而顺之，故称天子；建有极者道，故称皇；好恶者德，故称王；福威者政，故称辟。道所以成德，德所以立政，故言政于三德而称辟也。建有极者道，故称皇，则其曰“天子作民父母，以为天下王”，何也？吾所建者道，而民所知者德而已矣。
“七稽疑，择建立卜筮人，乃命卜筮，曰雨，曰霁，曰蒙，曰驿，曰克，曰贞，曰悔。凡七，卜五，占用二，衍忒”，何也？言有所择，有所建，则立卜筮人，卜筮凡七，而其为卜者五，则其为筮者二可知也。先卜而后筮，则筮之为正悔亦可知也。衍者，吉之谓也；忒者，凶之谓也。吉言衍，则凶之为耗可知也；凶言忒，则吉之为当亦可知也。此言之法也，盖自始造书，则固如此矣。福之所以为福者，于文从，则衍之谓也；祸所以为祸者，于文从呙，呙则忒之谓也。盖忒也、当也，言乎其位；衍也、耗也，言乎其数。夫物有吉凶，以其位与数而已。六五得位矣，其为九四所难者，数不足故也；九四得数矣，其为六五所制者，位不当故也。数衍而位当者吉，数耗而位忒者凶，此天地之道、阴阳之义，君子小人之所以相为消长，中国夷狄之所以相为强弱。《易》曰：“人谋鬼谋，百姓与能。”盖圣人君子以察存亡，以御治乱，必先通乎此，不通乎此而为百姓之所与者，盖寡矣。
“立时人作卜筮，三人占，则从二人之言”，何也？卜筮者，质诸鬼神，其从与违为难知，故其占也，从众而已也。
“汝则有大疑，谋及乃心，谋及卿士，谋及庶民，谋及卜筮”，何也？言人君有大疑，则当谋之于己，己不足以决，然后谋之于卿士，又不足以决，然后谋之于庶民，又不足以决，然后谋之于鬼神。鬼神，尤人君之所钦也，然而谋之反在乎卿士、庶民之后者，吾之所疑而谋者，人事也，必先尽之人，然后及鬼神焉，固其理也。圣人以鬼神为难知，而卜筮如此其可信者，《易》曰：“成天下之者，莫大乎蓍龟。”唯其诚之不至而已矣，用其至诚，则鬼神其有不应而龟筮其有不告乎？
“汝则从，龟从，筮从，卿士从，庶民从，是之谓大同，身其康强，子孙其逢吉”，何也？将有作也，心从之，而人神之所弗异，则有余庆矣，故谓之大同，而子孙其逢吉也。
“汝则从，龟从，筮从，卿士逆，庶民逆，吉。卿士从，龟从，筮从，汝则逆，庶民逆，吉。庶民从，龟从，筮从，汝则逆，卿士逆，吉”，何也？吾之所谋者疑也，可以作，可以无作，然后谓之疑。疑而从者众，则作而吉也。“汝则从，龟从，筮逆，卿士逆，庶民逆，作内吉，作外凶”，何也？尊者从，卑者逆，故逆者虽众，以作内，犹吉也。
“龟筮共违于人，用静吉，用作凶”，何也？所以谋之心谋之人者尽矣，然犹不免于疑，则谋及于龟筮，故龟筮之所共违，不可以有作也。
“庶征，曰雨，曰，曰燠，曰寒，曰风，曰时”者，何也？曰雨，曰，曰燠，曰寒，曰风者，自“肃时雨若”以下是也；曰时者，自“王省惟岁”以下是也。“五者来备，各以其叙，庶草蕃庑”，何也？阴阳和，则万物尽其性、极其材。言庶草者，以为物之尤微而莫养，又不知自养也，而犹蕃庑，则万物得其性，皆可知也。“一极备凶，一极无凶”，何也？雨极备则为常雨，极备则为常，风极备则为常风，燠极无则为常寒，寒极无则为常燠，此饥馑疾疠之所由作也，故曰凶。“曰休征：曰肃时雨若，曰时若，曰哲时燠若，曰谋时寒若，曰圣时风若。曰咎征：曰狂恒雨若，曰僭恒若，曰豫恒燠若，曰急恒寒若，曰蒙恒风若”，何也？言人君之有五事，犹天之有五物也。天之有五物，一极备凶，一极无亦凶，其施之小大缓急无常，其所以成物者，要之适而已。人之有五事，一极备凶，一极无亦凶，施之小大缓急亦无常，其所以成民者，亦要之适而已。故雨、、燠、寒、风者，五事之证也。降而万物悦者，肃也，故若时雨然；升而万物理者，也，故若时然；哲者，阳也，故若时燠然；谋者，阴也，故若时寒然；睿其思，心无所不通，以济四事之善者，圣也，故若时风然。狂则荡，故常雨若；僭则亢，故常若；豫则解缓，故常燠若；急则缩栗，故常寒若；冥其思，心无所不入，以济四事之恶者，蒙，故常风若也。
孔子曰：“见贤思齐，见不贤而内自省也。”君子之于人也，固常思齐其贤，而以其不肖为戒，况天者固人君之所当法象也，则质诸彼以验此，固其宜也。然则世之言灾异者，非乎？曰：人君固辅相天地以理万物者也，天地万物不得其常，则恐惧修省，固亦其宜也。今或以为天有是变，必由我有是罪以致之；或以为灾异自天事耳，何豫于我，我知修人事而已。盖由前之说，则蔽而葸；由后之说，则固而怠。不蔽不葸，不固不怠者，亦以天变为已惧，不曰天之有某变，必以我为某事而至也，亦以天下之正理考吾之失而已矣，此亦“念用庶证”之意也。
“王省惟岁，卿士惟月，师尹惟日”，何也？言自王至于师尹，犹岁、月、日三者相系属也。岁、月、日有常而不可变，所总大者亦不可以侵小，所治少者亦不可以僭多。自王至于师尹，三者亦相系属，有常而不可变，所总大者亦不可以侵小，所治少者亦不可以僭多。故岁、月、日者，王及卿士、师尹之证也。“岁、月、日时无易，百谷用成，用明，俊民用章，家用平康。日月岁时既易，百谷用不成，用昏不明，俊民用微，家用不宁”，何也？既以岁、月、日三者之时为王及卿士、师尹之证也，而王及卿士、师尹之职，亦皆协之岁、月、日时之纪焉，故岁有会，月有要，日有成。大者省其大而略，小者治其小而详，其小大、详略得其序，则功用兴，而分职治矣，故百谷用成，用明，俊民用章，家用平康。小大、详略失其序，则功用无所程，分职无所考，故百谷用不成，用昏不明，俊民用微，家用不宁也。“庶民惟星，星有好风，星有好雨”，何也？言星之好不一，犹庶民之欲不同。星之好不一，待月而后得其所好，而月不能违也，庶民之欲不同，待卿士而后得其所欲，而卿士亦不能违也，故星者，庶民之证也。“日月之行，则有冬有夏”，何也？言岁之所以为岁，以日月之有行，而岁无为也，犹王之所以为王，亦以卿士、师尹之有行，而王无为也。春秋者，阴阳之中；冬夏者，阴阳之正。阴阳各致其正，而后岁成。有冬、有夏者，言岁之成也。“月之从星，则以风雨”，何也？言月之好恶不自用而从星，则风雨作而岁功成，犹卿士之好恶不自用而从民，则治教政令行而王事立矣。《书》曰：“天听自我民听，天视自我民视。”夫民也，天之所不能违也，而况于王乎，况于卿士乎？
“五福，一曰寿，二曰富，三曰康宁，四曰攸好德，五曰考终命”，何也？人之始生也，莫不有寿之道焉，得其常性则寿矣，故一曰寿。少长而有为也，莫不有富之道焉，得其常产则富矣，故二曰富。得其常性，又得其常产，而继之以毋扰，则康宁矣，故三曰康宁也。夫人君使人得其常性，又得其常产，而继之以毋扰，则人好德矣，故四曰攸好德。好德则能以令终，故五曰考终命。“六极，一曰凶短折，二曰疾，三曰忧，四曰贫，五曰恶，六曰弱”，何也？不考终命谓之凶，早死谓之短，中绝谓之折。祸莫大于凶、短、折，疾次之，忧次之，贫又次之，故一曰凶短折，二曰疾，三曰忧，四曰贫。凶者，考终命之反也；短折者，寿之反也；疾忧者，康宁之反也；贫者，富之反也。此四极者，使人畏而欲其亡，故先言人之所尤畏者，而以犹愈者次之。夫君人者，使人失其常性，又失其常产，而继之以扰，则人不好德矣，故五曰恶，六曰弱。恶者，小人之刚也；弱者，小人之柔也。九畴曰初，曰次，而五行、五事、八政、五纪、三德、五福、六极，特以一二数之，何也？九畴以五行为初，而水之于五行，貌之于五事，食之于八政，岁之于五纪，正直之于三德，寿、凶短折之于五福、六极，不可以为初故也。或曰：“箕子之所次，自五行至于庶证，而今独曰自五事至于庶证，各得其序，则五福之所集，自五事至于庶证，各爽其序，则六极之所集，何也？”曰：人君之于五行也，以五事修其性，以八政用其材，以五纪协其数，以皇极建其常，以三德治其变，以稽疑考其难知，以庶证证其失得，自五事至于庶证，各得其序，则五行固已得其序矣。或曰：“世之不好德而能以令终，与好德而不得其死者众矣。今曰好德则能以令终，何也？”曰：孔子以为“人之生也直，罔之生也幸而免”。君子之于吉凶、祸福，道其常而已，幸而免与不幸而及焉，盖不道也。或曰：“孔子以为富与贵人之所欲，贫与贱人之所恶，而福极不言贵贱，何也？”曰：五福者，自天子至于庶人，皆可使慕而欲其至；六极者，自天子至于庶人，皆可使畏而欲其亡；若夫贵贱，则有常分矣。使自公侯至于庶人，皆慕贵，欲其至，而不欲贱之在己，则陵犯篡夺之行日起，而上下莫安其命矣。《诗》曰：“肃肃宵征，抱衾与，实命不犹。”盖王者之世，使贱者安其贱如此。夫岂使知贵之为可慕而欲其至，贱之为可畏而欲其亡乎？', '', '', '', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f82c6e67846a9226d8a", "shortContent": "中华民族是个重伦理、讲道德的民族，特别重视忠奸之分、曲直之别。对于那些忠于祖国、热爱人民、对民族作出贡献的人，特别是那些因此而受诬枉、被陷害而含冤至死者，人们总是寄予无限的崇敬和怀念。或者为他们立丰碑，或者为他们建祠庙，而更多的还是根据他们的事迹创作出一个个动人的传说，为他们编织成一束束美丽的花环，使他们世世代代永远活在人们的心中。屈原就是这样一位几千年来一直为人们尊崇的忠臣与诗人。这篇志怪小说就...", "authors": ["孙秀荣"], "pressName": "上海辞书出版社"}]', '', 'indent', 1545336586, '5c1b553d4773f7005f074b59', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640783, '四哀诗李钦叔', NULL, 15, 819, 1, 1, '元好问', NULL, 10074, '57b9127ca633bd00665de11d', '金', 'shi', '诗', '', '', '赤县神州坐陆沈，金汤非粟祸侵寻。
当官避事平生耻，视死如归社稷心。
文采是人知子重，交朋无我与君深。
悲来不待山阳笛，一忆同衾泪满襟。', '', '', '', NULL, '', 'center', 1545324257, '5c1b568b1579a3005fc4f8fb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640784, '兵要', NULL, 38, 60, 1, 1, '诸葛亮', NULL, 10026, '57b8f8452e958a005fa50d86', '三国', 'wen', '文', '', '', '人之忠也，犹鱼之有渊。鱼失水则死，人失忠则凶。故良将守之，志立而扬名。', '', '《兵要》是诸葛亮从军事实践中，总结出的“以法治军”所必须遵循的要领，共十则。这十则《兵要》，从军事纪律、良将品德、用人选贤、将领作风、捕捉战机、打击歪风、杜绝朋党、战术教练、驻防移防、军规军容等方面进行了论述，是研究诸葛亮军事思想的重要资料。

本则见于《太平御览》卷二百七十三。意思是，人有忠诚的品德，就好比鱼儿有了水。鱼离开水就会死，人失去忠诚的品德就很危险。所以好的将领都注意保守它，使部卒志向得以实现，名声广为传扬。基于此，诸葛亮认为对士兵要“教之以礼义，诲之以忠信”。', '', NULL, '', 'indent', 1545324513, '5c1b577b9f5454007062cc16', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640785, '应间', NULL, 4, 17, 1, 1, '张衡', NULL, 18092, '5830da81d203090067130f53', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E5%BA%94%E9%97%B4/13880715', '', '观者观余去史官五载而复还，非进取之势也。唯衡内识利钝，操心不改。或不我知者，以为失志矣，用为间余。余应之以时有遇否，性命难求，因兹以露余诚焉，名之《应间》云。
有间余者曰：“盖闻前哲首务，务于下学上达，佐国理民，有云为也。朝有所闻，则夕行之。立功立事，式昭德音。是故伊尹思使君为尧、舜，而民处唐、虞，彼岂虚言而已哉？必旌厥素尔。咎单、巫咸，实守王家，申伯、樊仲，实干周邦，服衮而朝，介圭作瑞。厥迹不朽，垂烈后昆，不亦丕欤！且学非以要利，而富贵萃之。贵以行令，富以施惠，惠施令行，故《易》称以“大业”。质以文美，实由华兴，器赖雕饰为好，人以舆服为荣。吾子性德体道，笃信安仁，约己博艺，无贤不钻，以思世路，斯何远矣！曩滞日官，今又原之。虽老氏曲全，进道若退，然行亦以需。必也学非所用，术有所仰，故临川将济，而舟楫不存焉。徒经思天衢，内昭独智，固合理民之式也？故尝见谤于鄙儒。深厉浅揭，随时为义，可贪于支离，而习其孤技邪？参轮可使自转，木雕犹能独飞，已垂翅而还故栖，盍亦调其机而铦诸？昔有文王，自求多福。人生在勤，不索何获。曷若卑体屈己，美言以相克？鸣于乔木，乃金声而玉振之。用后勋，雪前吝，婞佷不柔，以意谁靳也。”应之曰：“是何观同而见异也？君子不患位之不尊，而患德之不崇；不耻禄之不伙，而耻智之不博。是故艺可学而行可力也。天爵高悬，得之在命或不速而自怀，或羡旃而不臻，求之无益，故智者偭而不思。阽身以徼幸，固贪夫之所为，未得而豫丧也。枉尺直寻，议者讥之，盈欲亏志，孰云非羞？于心有猜，则簋飧馔餔犹不屑餐，旌瞀以之。意之无疑，则兼金盈百而不嫌辞，孟轲以之。士或解裋褐而袭黼黻，或臿筑而据文轩者，度德拜爵，量绩受禄也。输力致庸，受必有阶。浑元初基，灵轨未纪，吉凶分错，人用膧朦。黄帝为斯深惨。有风后者，是焉亮之，察三辰于上，迹祸福乎下，经纬历数，然后天步有常，则风后之为也。当少昊清阳之末，实或乱德，人神杂扰，不可方物，重、黎又相颛顼而申理之，日月即次，则重、黎之为也。人各有能，因艺受任，鸟师别名，四叔三正，官无二业，事不并济。昼长则宵短，日南则景北。天且不堪兼，况以人该之。夫玄龙，迎夏则陵云而奋鳞，乐时也；涉冬则淈泥而潜蟠，避害也。公旦道行，故制典礼，以尹天下，惧教诲之不从，有人之不理。仲尼不遇，故论《六经》，以俟来辟，耻一物之不知，有事之无范。所考不齐，如何可一？夫战国交争，戎车竞驱，君若缀旒，人无所丽烛武县缒而秦伯退师，鲁连系箭而聊城弛柝。从往则合，横来则离，安危无常，要在说夫。咸以得人为枭，失士为尤。故樊哙披帷，入见高祖；高祖踞洗，以对郦生。当此之会，乃鼋鸣而鳖应也。故能同心戮力，勤恤人隐，奄受区夏，遂定帝位，皆谋臣之由也。故一介之策，各有攸建，子长谍之，烂然有第。夫女魃北而应龙翔，洪鼎声而军容息；溽暑至而鹑火栖，寒冰沍而鼋鼍蛰。今也皇泽宣洽，海外混同，万方亿丑，并质共剂，若修成之不暇，尚何功之可立！立事有三，言为下列。下列且不可庶矣，奚冀其二哉！于兹缙绅如云，儒士成林，及津者风摅，失涂者幽僻，遭遇难要，趋偶为幸世易俗异，事势桀殊，不能通其变，而一度以揆之，斯契船而求剑，守株而伺兔也。冒愧逞愿，必无仁以继之，有道者所不履也。越王勾践事此，故厥绪不永，捷径邪至，我不忍以投步；干进苟容，我不忍以歙肩。虽有犀舟劲楫，犹人涉卬否，有须者也。姑亦奉顺敦笃，守以忠信，得之不休，不获不吝。不见是而不惛，居下位而不忧，允上德之常服焉。方将师天老而友地典，与之乎高睨而大谈，孔甲且不足慕，焉称殷彭及周聃！与世殊技，固孤是求。子忧朱泙曼之无所用，吾恨轮扁之无所教也。子睹木雕独飞，愍我垂翅故栖，吾感去蛙附鸱，悲尔先笑而后号也。斐豹以弊督燔书，礼至以掖国作铭；弦高以牛饩退敌，墨翟以萦带全城；贯高以端辞显义，苏武以秃节效贞；蒲且以飞矰逞巧，詹何以沈钧致精；弈秋以棋局取誉，王豹以清讴流声。仆进不能参名于二立，退又不能群彼数子。愍《三坟》之既颓，惜《八索》之不理。庶前训之可钻，聊朝隐乎柱史。且韫椟以待价，踵颜氏以行止。曾不慊夫晋、楚，敢告诚于知己。”', '', '', '', NULL, '', 'indent', 1545335562, '5c1b829c67f356005fcd5c52', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640786, '内乡县衙楹联', NULL, 22, 103, 1, 1, '无名氏', NULL, 10396, '57e63abf0bd1d0005bfbba07', '明', 'shi', '诗', '', '', '廉不言贫，勤不言苦；尊其所闻，行其所知。', '这副楹联悬挂内乡县衙东账房正厅。', '', '真正廉洁的人，不会讲自己如何清贫；真正勤政的人，不会抱怨自己如何辛苦；重视倾听民间传闻，努力实践自己认识到的理论，实现自己的抱负。', NULL, '', 'center', 1545335922, '5c1b840b1579a3005fc78b07', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640788, '周官', NULL, 9, 1, 1, 1, '梅赜', NULL, 37037, '5cb1a44bc8959c007570ea9c', '晋', 'wen', '文', 'https://baike.baidu.com/item/%E5%91%A8%E5%AE%98/16262660', '', '惟周王抚万邦，巡侯、甸，四征弗庭，绥厥兆民。六服群辟，罔不承德。归于宗周，董正治官。　　王曰：「若昔大猷，制治于未乱，保邦于未危。」　　曰：「唐虞稽古，建官惟百。内有百揆四岳，外有州、牧、侯伯。庶政惟和，万国咸宁。夏商官倍，亦克用乂。明王立政，不惟其官，惟其人。　　今予小子，祗勤于德，夙夜不逮。仰惟前代时若，训迪厥官。立太师、太傅、太保，兹惟三公。论道经邦，燮理阴阳。官不必备，惟其人。少师、少傅、少保，曰三孤。贰公弘化，寅亮天地，弼予一人。冢宰掌邦治，统百官，均四海。司徒掌邦教，敷五典，扰兆民。宗伯掌邦礼，治神人，和上下。司马掌邦政，统六师，平邦国。司冠掌邦禁，诘奸慝，刑暴乱。司空掌邦土，居四民，时地利。六卿分职，各率其属，以倡九牧，阜成兆民。六年，五服一朝。又六年，王乃时巡，考制度于四岳。诸侯各朝于方岳，大明黜陟。」　　王曰：「呜呼！凡我有官君子，钦乃攸司，慎乃出令，令出惟行，弗惟反。以公灭私，民其允怀。学古入官。议事以制，政乃不迷。其尔典常作之师，无以利口乱厥官。蓄疑败谋，怠忽荒政，不学墙面，莅事惟烦。戒尔卿士，功崇惟志，业广惟勤，惟克果断，乃罔后艰。位不期骄，禄不期侈。恭俭惟德，无载尔伪。作德，心逸日休；作伪，心劳日拙。居宠思危，罔不惟畏，弗畏入畏。推贤让能，庶官乃和，不和政庞。举能其官，惟尔之能。称匪其人，惟尔不任。」　　王曰：「呜呼！三事暨大无，敬尔有官，乱尔有政，以佑乃辟。永康兆民，万邦惟无斁。', '周室东迁之后，人臣之事君，远不如往古，乱臣杀君之事屡见不鲜。史官作《周书》，记古贤臣事君之道，以使后世取法。周官即为《尚书·周书》中的一篇。（“成王既黜殷命，灭淮夷，还归在丰，作《周官》。”）', '', '周成王安抚万国，巡视侯服、甸服等诸侯，四方征讨不来朝见的诸侯，以安定天下的老百姓。六服的诸侯，无人不奉承他的德教。成王回到王都丰邑，又督导整顿治事的官员。　　成王说：“顺从往日的大法，要在未出现动乱的时候制定治理的办法，在未出现危机的时候安定国家。尧舜稽考古代制度，建立官职一百。内有百揆和四岳，外有州牧和侯伯。各种政策适合，天下万国都安宁。夏代和商代，官数增加一倍，也能用来治理。明王设立官员，不考虑他的官员之多，而考虑要得到贤人。现在我小子恭敬勤奋施行德政，起早睡晚都不敢懈怠。仰思顺从前代，说明建立我们的官制。　　“设立太师、太傅、大保，这是三公。他们讲明治道，治理国家，调和阴阳。三公的官不必齐备，要考虑适当的人。　　“设立少师、少傅、少保，叫做三孤。他们协助三公弘扬教化，敬明天地的事，辅助我一人。　　“冢宰主管国家的治理，统帅百官，调剂四海。司徒主管国家的教育，传布五常的教训，使万民和顺。宗伯主管国家的典礼，治理神和人的感通，调和上下尊卑的关系。司马主管国家的军政，统率六师，平服邦国。司寇主管国家的法禁，治理好恶的人，刑杀暴乱之徒。司空主管国家的土地，安置士农工商，依时发展地利。六卿分管职事，各自统率他的属官，以倡导九州之牧，大力安定兆民。　　“六年，五服诸侯来朝见一次。又隔六年，王便依时巡视，到四岳校正制度。诸侯各在所属的方岳来朝见，王对诸侯普遍讲明升降赏罚。”　　成王说：“啊！凡我的各级官长，要认真对待你们所管理的工作，慎重对待你们发布的命令。命令发出了就要进行，不要违抗。用公正消除私情，人民将会信任归服。先学古代治法再入仕途，议论政事依据法制，政事就不会错误。你们要用周家常法作为法则，不要以巧言干扰你的官员。蓄疑不决，必定败坏计谋，怠情忽略，必定废弃政事。不学习好象向墙站着，临事就会烦乱。　　“告诉你们各位卿士：功高由于有志，业大由于勤劳。能够果敢决断，就没有后来的艰难。居官不当骄傲，享禄不当奢侈，恭和俭是美德啊！不要行使诈伪，行德就心逸而日美，作伪就心劳而日拙。处于尊宠要想到危辱，无事不当敬畏，不知敬畏，就会进入可畏的境地。推举贤明而让能者，众官就会和谐；众官不和，政事就复杂了。推举能者在其官位，是你们的贤能；所举不是那种人，是你们不能胜任。”　　成王说：“啊！任人、准夫、牧三位首长和大夫们：认真对待你们的官职，治理你们的政事，来辅助你们的君主，使广大百姓长远安宁；天下万国就不会厌弃我们了。”', NULL, '', 'indent', 1545337287, '5c1b89441579a3005fc7dcbb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640789, '勤懒歌', NULL, 41, 1, 1, 1, '钱德苍', NULL, 36980, '5c1b8d417f6fd3005dfb1aa7', '清', 'wen', '文', '', '', '为人在世莫嗜懒，嗜懒之人才智短。百事由懒做不成，临老噬脐悲已晚。士而懒，终身布衣不能换；农而懒，食不充肠衣不暖；工而懒，积聚万贯成星散。又不见，人生天地惟在勤，原勤之本在乎心。若能自强而不息，先须抖擞己精神。士而勤，万里青云可致身；农而勤，盈盈仓廪成红陈；工而勤，巧手超群能动人；商而勤，腰中常缠千万金。噫嘻噫嘻复噫嘻，只在勤兮与懒兮。丈夫志气掀天地，拟上百尺竿头立。百尺竿头立不难，一勤天下无难事。', '《解人颐》二十四集，清钱德苍重辑。根据书前作者写于乾隆二十六年（1761年）的序可知，他是根据坊间流传的《解人颐》初集、二集及《新订解人颐》三部书，“复为去陈集新，又从而广益之”，重新付梓的。

      《解人颐》收录的这首《勤懒歌》，是对古代的“四民”——士、农、工、商进行劝勤戒懒。结语为：“百尺竿头立不难，一勤天下无难事。”意思是，只要勤奋，天下就没有难做的事情，即使百尺竿头也能昂然挺立。百尺竿头：百尺高的竿子，佛教比喻道行修养的极高境界，也作“百丈竿头”。
       关于勤奋，古人论之多矣。东汉张衡说：“人生在勤，不索何获。”唐代韩愈有言：“书山有路勤为径，学海无涯苦作舟。”勤能补拙是良训，一分辛劳一分才。伟人毛泽东在《水调歌头·重上井冈山》词中写道：“世上无难事，只要肯登攀。”可说是“一勤天下无难事”的另类表达。', '', '', NULL, '', 'indent', 1545338293, '5c1b8d5167f356005fce0467', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640790, '东周列国志第十六回', NULL, 27, 7, 1, 1, '冯梦龙', NULL, 17086, '5858eb7aac502e0067086998', '明', 'wen', '文', '', '', '桓公与管夷吾连语三日三夜，字字投机，全不知倦。桓公大悦，乃复斋戒三日，告于太庙，欲拜管夷吾为相。夷吾辞而不受。桓公曰:“吾纳子之伯策。欲成吾志，故拜子为相。何为不受？”对曰:“臣闻大厦之成，非一木之材也;大海之润，非一流之归也。君必欲成其大志，则用五杰。”', '', '＂大厦之成，非一木之材也；大海之润，非一流之归也＂，是《东周列国志》中齐相管仲建议齐桓公广纳人才以成霸业时打的比方。意思是说，大厦的建成，不能只靠一棵树的木材；大海的润泽，也不是仅凭一条河流的归聚。', '', NULL, '', 'indent', 1545339386, '5c1b9198808ca4565c7d8a13', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640791, '韩非子·喻老', NULL, 18, 20, 2, 2, '韩非', NULL, 36801, '589c4ae38d6d81006c808cbe', '秦', 'wen', '文', 'https://baike.baidu.com/item/%E9%9F%A9%E9%9D%9E%E5%AD%90%C2%B7%E5%96%BB%E8%80%81/3609916?fr=aladdin', '《韩非子》中《解老》、《喻老》二篇为道家经典《老子》的重要注解与阐释著作。先秦法家本为极其凌厉之学问，多有真切喜人之处，而道家老子之深邃精奥则远过其他诸子。凌厉之法家与深邃之道家本一脉相承，故学者有“道生法”一说。而韩非“喜刑名法术之学，而其归本于黄老”。
', '天下有道，无急患，则曰静，遽传不用，故曰：“却走马以粪。”天下无道，攻击不休，相守数年不已，甲胄生虮虱，燕雀处帷幄，而兵不归，故曰：“戎马生于郊。”
翟人有献丰狐、玄豹之皮于晋文公，文公受客皮而叹曰：“此以皮之美自为罪。”夫治国者以名号为罪，徐偃王是也；以城与地为罪，虞、虢是也。故曰：“罪莫大于可欲。”
智伯兼范、中行而攻赵不已，韩、魏反之，军败晋阳，身死高梁之东，遂卒被分，漆其首以为溲器。故曰：“祸莫大于不知足。”
虞君欲屈产之乘与垂棘之璧，不听宫之奇，故邦亡身死。故曰：“咎莫憯于欲得。”
邦以存为常，霸王其可也；身以生为常，富贵其可也。不欲自害，则邦不亡，身不死。故曰：“知足之为足矣。”
楚庄王既胜狩于河雍，归而赏孙叔敖。孙叔敖请汉间之地，沙石之处。楚邦之法，禄臣再世而收地，唯孙叔敖独在。此不以其邦为收者，瘠也，故九世而祀不绝。故曰：“善建不拔，善抱不脱，子孙以其祭祀，世世不辍。”孙叔敖之谓也。
制在己曰重，不离位曰静。重则能使轻，静则能使躁。故曰：“重为轻根，静为躁君。”故曰：“君子终日行不离辎重也。”邦者，人君之辎重也。主父生传其邦，此离其辎重者也，故虽有代、云中之乐，超然已无赵矣。主父，万乘之主，而以身轻于天下。无势之谓轻，离位之谓躁，是以生幽而死。故曰：“轻则失臣，躁则失君。”主父之谓也。
势重者，人君之渊也。君人者，势重于人臣之间，失则不可复得矣。简公失之于田成，晋公失之于六卿，而邦亡身死。故曰：“鱼不可脱于深渊。”赏罚者，邦之利器也，在君则制臣，在臣则胜君。君见赏，臣则损之以为德；君见罚，臣则益之以为威。人君见赏，则人臣用其势；人君见罚，而人臣乘其威。故曰：“邦之利器，不可以示人。”
越王入宦于吴，而观之伐齐以弊吴。吴兵既胜齐人于艾陵，张之于江、济，强之于黄池，故可制于五湖。故曰：“将欲翕之，必固张之；将欲弱之，必固强之。”晋献公将欲袭虞，遗之以璧、马。知伯将袭仇由，遗之以广车。故曰：“将欲取之，必固与之。”起事于无形，而要大功于天下，“是谓微明”。处小弱而重自卑，谓“损弱胜强”也。
有形之类，大必起于小；行久之物，族必起于少。故曰：“天下之难事必作于易，天下之大事必作于细。”是以欲制物者于其细也。故曰：“图难于其易也，为大于其细也。”千丈之堤，以蝼蚁之穴溃；百尺之室，以突隙之烟焚。故曰：白圭之行堤也塞其穴，丈人之慎火也涂其隙，是以白圭无水难，丈人无火患。此皆慎易以避难，敬细以远大者也。扁鹊见蔡桓公，立有间。扁鹊曰：“君有疾在腠理，不治将恐深。”桓侯曰：“寡人无疾。”扁鹊出。桓侯曰：“医之好治不病以为功。”居十日，扁鹊复见曰：“君之病在肌肤，不治将益深。”桓侯不应。扁鹊出，桓侯又不悦。居十日，扁鹊复见曰：“君之病在肠胃，不治将益深。”桓侯又不应。扁鹊出，桓侯又不悦。居十日，扁鹊望桓侯而还走，桓侯故使人问之。扁鹊曰：“病在腠理，汤熨之所及也；在肌肤，针石之所及也；在肠胃，火齐之所及也；在骨髓，司命之所属，无奈何也。今在骨髓，臣是以无请也。”居五日，桓侯体痛，使人索扁鹊，已逃秦矣。桓侯遂死。故良医之治病也，攻之于腠理。此皆争之于小者也。夫事之祸福亦有腠理之地，故曰：“圣人蚤从事焉。”
昔晋公子重耳出亡，过郑，郑君不礼。叔瞻谏曰：“此贤公子也，君厚待之，可以积德。”郑君不听。叔瞻又谏曰：“不厚待之，不若杀之，无令有后患。”郑君又不听。及公子返晋邦，举兵伐郑，大破之，取八城焉。晋献公以垂棘之璧假道于虞而伐虢，大夫宫之奇谏曰：“不可。唇亡而齿寒，虞、虢相救，非相德也。今日晋灭虢，明日虞必随之亡。”虞君不听，受其璧而假之道。晋已取虢，还，反灭虞。此二臣者，皆争于腠理者也，而二君不用也。然则叔瞻、宫之奇亦虞、虢之扁鹊也，而二君不听，故郑以破，虞以亡。故曰：“其安易持也，其未兆易谋也。”
昔者纣为象箸而箕子怖，以为象箸必不加于土铏，必将犀玉之杯；象箸、玉杯必不羹菽藿，则必旄、象、豹胎；旄、象、豹胎必不衣短褐而食于茅屋之下，则锦衣九重，广室高台。吾畏其卒，故怖其始。居五年，纣为肉圃，设炮烙，登糟丘，临酒池，纣遂以亡。故箕子见象箸以知天下之祸，故曰：“见小曰明。”
勾践入宦于吴，身执干戈为吴王洗马，故能杀夫差于姑苏。文王见詈于王门，颜色不变，而武王擒纣于牧野。故曰：“守柔曰强。”越王之霸也不病宦，武王之王也不病詈，故曰：“圣人之不病也，以其不病，是以无病也。”
宋之鄙人得璞玉而献之子罕，子罕不受。鄙人曰：“此宝也，宜为君子器，不宜为细人用。”子罕曰：“尔以玉为宝，我以不受子玉为宝。”是鄙人欲玉，而子罕不欲玉。故曰：“欲不欲，而不贵难得之货。”
王寿负书而行，见徐冯于周涂。冯曰：“事者为也，为生于时，知者无常事；书者言也，言生于知，知者不藏书。今子何独负之而行？”于是王寿因焚其书而舞之。故知者不以言谈教，而慧者不以藏书箧。此世之所过也，而王寿复之，是学不学也。故曰：“学不学，复归众人之所过也。”
夫物有常容，因乘以导之。因随物之容，故静则建乎德，动则顺乎道。宋人有为其君以象为楮叶者，三年而成。丰杀茎柯，毫芒繁泽，乱之楮叶之中而不可别也。此人遂以功食禄于宋邦。列子闻之曰：“使天地三年而成一叶，则物之有叶者寡矣。”故不乘天地之资而载一人之身，不随道理之数而学一人之智，此皆一叶之行也。故冬耕之稼，后稷不能羡也；丰年大禾，臧获不能恶也。以一人之力，则后稷不足；随自然，则臧获有余。故曰：“恃万物之自然而不敢为也。”
空窍者，神明之户牖也。耳目竭于声色，精神竭于外貌，故中无主。中无主则祸福虽如丘山，无从识之。故曰：“不出于户，可以知天下；不窥于牖，可以知天道。”此言神明之不离其实也。
赵襄主学御于王子期，俄而与于期逐，三易马而三后。襄主曰：“子之教我御，术未尽也？”对曰：“术已尽，用之则过也。凡御之所贵，马体安于车，人心调于马，而后可以进速致远。今君后则欲逮臣，先则恐逮于臣。夫诱道争远，非先则后也，而先后心在于臣，上何以调于马？此君之所以后也。”
白公胜虑乱，罢朝，倒杖而策锐贯颐，血流至于地而不知。郑人闻之曰：“颐之忘，将何为忘哉！”故曰：“其出弥远者，其智弥少。”此言智周乎远，则所遗在近也。是以圣人无常行也。能并智，故曰：“不行而知。”能并视，故曰：“不见而明。”随时以举事，因资而立功，用万物之能而获利其上，故曰：“不为而成。”
楚庄王莅政三年，无令发，无政为也。右司马御座而与王隐曰：“有鸟止南方之阜，三年不翅，不飞不鸣，嘿然无声，此为何名？”王曰：“三年不翅，将以长羽翼；不飞不鸣，将以观民则。虽无飞，飞必冲天；虽无鸣，鸣必惊人。子释之，不谷知之矣。”处半年，乃自听政。所废者十，所起者九，诛大臣五，举处士六，而邦大治。举兵诛齐，败之徐州，胜晋于河雍，合诸侯于宋，遂霸天下。庄王不为小害善，故有大名；不蚤见示，故有大功。故曰：“大器晚成，大音希声。”
楚庄王欲伐越，庄子谏曰：“王之伐越，何也？”曰：“政乱兵弱。”庄子曰：“臣患智之如目也，能见百步之外而不能自见其睫。王之兵自败于秦、晋，丧地数百里，此兵之弱也。庄蹻为盗于境内而吏不能禁，此政之乱也。王之弱乱，非越之下也，而欲伐越，此智之如目也。”王乃止。故知之难不在见人，在自见，故曰：“自见之谓明。”
子夏见曾子。曾子曰：“何肥也？”对曰：“战胜，故肥也。”曾子曰：“何谓也？”子夏曰：“吾入见先王之义则荣之，出见富贵之乐又荣之，两者战于胸中，未知胜负，故臞。今先王之义胜，故肥。”是以志之难也不在胜人，在自胜也，故曰：“自胜之谓强。”
周有玉版，纣令胶鬲索之，文王不予；费仲来求，因予之。是胶鬲贤而费仲无道也。周恶贤者之得志也，故予费仲。文王举太公于渭滨者，贵之也；而资费仲玉版者，是爱之也。故曰：“不贵其师，不爱其资，虽知大迷，是谓要妙。”', '《韩非子·喻老》出自《韩非子》。在短篇幅中，用二十五则历史故事和民间传说分别解释了《老子》十二章，其中《德经》八章、《道经》四章，使《老子》抽象的哲学思想有了具体可感的呈现，在中国哲学史和训诂学史上起着发凡起例的作用，同时也使他的刑名法术之学有了比较精深的理论凭藉。', '', '', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3be", "shortContent": "礼是内心情感的描绘，文采是内在本质的修饰。君子采纳情感而舍弃描绘，喜欢本质而厌恶修饰。依靠描绘来阐明的情感，这种情感是不好的；依靠修饰来阐明的本质，这种本质是糟糕的。就比如和氏璧，不用五彩修饰，但它依然价值连城，这是因为它的本质极美，别的东西是不足以修饰它的。情感是本质，而礼只是体现内心情感的表现形式，是各种义的有条理的表现，是用来规定君臣、父子之间关系的；情感才是内质的，是真正宝贵的东西，过分重...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3c0", "shortContent": "“徧”同“遍”，普遍，全部；“必”通“毕”，尽，完全。太山对土石没有好恶之心，所以能够形成它的高大；江海不舍弃细流，所以能够形成它的浩瀚。\n\n无论是在奴隶制社会、封建社会、资本主义社会还是社会主义社会，治国都是一个永恒的经典主题。怎样才能国泰民安是统治阶级必须思考的问题，韩非在此提出了他的建议。韩非认为，有了辽阔的天空，世界才能被全部覆盖，有了宽厚的土地，万物才能被全部负载，所以，统治者要像天地那...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1545339847, '5c1b9343808ca4565c7da4f6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642102, '幽梦影 · 卷一 · 七十一', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '延名师，训子弟；入名山，习举业；丐名士，代捉刀。三者都无是处。', '', '', '', NULL, '陈康畴曰：大抵名而已矣，好歹原未必著意。', 'indent', 1556017191, '5cbe7fa5a3180b7832e6e737', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640792, '拟连珠', NULL, 32, 1624, 1, 1, '刘基', NULL, 10076, '57ba8247c4c97100614d49ee', '明', 'wen', '文', '', '', '盖闻物有甘苦，尝之者识；道有夷险，履之者知。是以宴安日久诘戎兵，而听者忽忽；老成人丧语典形，而闻者嗤嗤。', '', '《拟连珠》是明朝开国元勋刘基仿连珠文体而作，共六十八首。刘基的思想主要来源于孔、孟、荀、墨以及易学、名家、法家、兵家、老庄道家等，充分体现了“一代文宗”刘基“会通百家、兼容儒道”的为学风格与理论旨趣。明末竟陵文派创始人钟惺评曰：“居身涉世之理，用贤治人之道，与夫阴阳祸福、盛衰治乱无不具备于六十八首，寝食其中，有无穷受用处，公真教敷一时，泽被千古者也。”

《拟连珠》的“无穷受用处”就是注重实学、实效、实功，强调实践工夫。在“名实之辨”问题上，刘基主张以“形”、“实”证“声”、“名”，其实学思想的主要观点为：“观形于声，未必见形；求实于名，未必得实”，反对“声”、“名”等一般性的描述语言和理论，主张从“形”、“实”中获取关于事物本质性的认识。为此，他提出：“物有甘苦，尝之者识；道有夷险，履之者知。”意思是说，任何事物都有甘苦之分，只有尝试过才会知道；天下道路都有平坦坎坷之分，只有自己走过才会明白。这与毛泽东同志所说的“要想知道梨子的味道，就要亲口尝一尝”一样，都阐述了“实践出真知”的道理。', '', NULL, '', 'indent', 1545340140, '5c1b945367f356005fce7d3a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640793, '申鉴·俗嫌', NULL, 14, 3, 1, 1, '荀悦', NULL, 36978, '5c1a7693303f39005f23dcde', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E7%94%B3%E9%89%B4/2857129?fr=aladdin', '', '或问卜筮。曰：“德斯益，否斯损。”曰：“何谓也？”“吉而济，凶而救之谓益；吉而恃，凶而怠之谓损。”
或问曰时群忌。曰：“此天地之数也，非吉凶所生也，东方主生，死者不鲜；西方主杀，生者不寡，南方火也，居之不燋；北方水也，蹈之不沈。故甲子昧爽，殷灭周兴；咸阳之地，秦亡汉隆。
或问五三之位周应也，茏虎之会晋祥也。曰：“官府设陈，富贵者值之；布衣寓焉，不符其爵也，狱犴若居，有罪者触之；贞良入焉，不受其罚也。”或曰：“然则日月可废欤？”曰：“否。曰元辰，先王所用也，人承天地，故动静焉顺焉。顺其阴阳，顺其日辰，顺其度数。内有顺实，外有顺文，文实顺，理也，休〕徵之符，自然应也。故盗泉、朝歌，孔、墨不由，恶其名者，顺其心也。苟无其实，徼福于忌，斯成难也。”
或曰：“祈请者诚以接神，自然应也。故精以底之，牺牲玉帛，以昭祈请，吉朔以通之。礼云礼云，玉帛云乎哉？请云祈云，酒膳云乎哉？非其礼则或愆，非其请则不应。”
或问祈请可否。曰：“气物应感则可，性命自然则否。”或问：“避疾厄，有诸？”曰，“夫疾厄，何为者也？非身则神身。不可避，神不可逃；可避非身，可逃非神也。持身随天，万里不逸，譬诸孺子掩目巨夫之掖，而曰逃可乎？”
或问人形有相。曰：“盖有之焉。夫神气形容之相包也，自然矣。贰之于行，参之于时，相成也，亦参相败也。其数众矣，其变多矣，亦有上中下品云尔。”
或问神仙之术。曰：“诞哉！末之也已矣。圣人弗学，非恶生也。终始，运也，短长，数也。运数非人力之为也。”曰：“亦有仙人乎？”曰：“僬侥桂莽，产乎异俗，就有仙人，亦殊类矣。”
或问：”有数百岁人乎？”曰：“力称乌获，捷言羌、亥，勇期贲、育，圣云仲尼，寿称彭祖，物有俊杰，不可诬也。”	
或问：“凡寿者必有道，非习之功。”曰：“夫惟寿，则惟能用道，惟能用道，则性寿矣。苟非其性也，修不至也。学必至圣，可以尽性，寿必用道，所以尽命。”
或曰：“人有自变化而仙者，信乎？”曰：“未之前闻也。然则异也，非仙也。男化为女者有矣，死人复生者有矣，夫岂人之性哉？气数不存焉。”
或问曰：“有养性乎？”曰：“养性秉中和，守之以生而已。爱亲、爱德、爱力、爱神，之谓啬，否则不宣，过则不澹。故君子节宣其气，勿使有所壅闭滞底。昏乱百度则生疾，故喜怒哀乐思虑必得其中，所以养神也；寒暄虚盈消息必得其中，所以养体也。善治气者，由禹之治水也。若夫导引蓄气，历藏内视，过则失中，可以治疾，皆非养性之圣术也。夫屈者以乎申也，蓄者以乎虚也，内者以乎外也。气宜宣而遏之，体宜调而矫之，神宜平而抑之，必有失和者矣。夫善养性者无常术，得其和而已矣。邻脐二寸谓之关，关者所以关藏呼吸之气，以禀授四体也。故气长者以关息，气短者其息稍升，其脉稍促，其神稍越，至于以肩息而气舒，其神稍专，至于以关息而气衍矣。故道者，常致气于关，是谓要术。凡阳气生养，阴气消杀，和喜之徒，其气阳也，故养性者，崇其阳而绌其阴。阳极则元，阴极则凝，元则有悔，凝则有凶。夫物不能为春，故候天春而生，人则不然，存吾春而已矣。药者疗也，所以治疾也，无疾则勿药可也。肉不胜食气，况于药乎？寒斯热，热则致滞，阴药之用也，唯适其宜，则不为害，若己气平也，则必有伤。唯针火亦如之。故养性者，不多服也，唯在乎节之而已矣。”
或问：“仁者寿，何谓也？”曰：“仁者内不伤性，外不伤物，上不违天，下不违人，处正居中，形神以和，故咎徵不至，而休嘉集之，寿之术也。”曰：“颜、冉何？”曰：“命也，麦不终夏，花不济春，如和气何？虽云其短，长亦在其中矣。”
或问黄白之俦。曰，“傅毅论之当也。燔埴为瓦则可，烁瓦为铜则不可，以自然验于不然，诡哉！歒犬羊之肉以造马牛，不几矣，不其然欤？”
世称纬书，仲尼之作也，臣悦叔父故司空爽辨之，盖发其伪也。有起于中兴之前，终张之徒之作乎？或曰：“杂。”曰：“以己杂仲尼乎？以仲尼杂己乎？若彼者，以仲尼杂己而已。然则可谓八十一首，非仲尼之作矣。”或曰：“燔诸？”曰：“仲尼之作则否，有取焉则可，曷其燔？在上者不受虚言，不听浮术，不采华名，不兴伪事；言必有用，术必有典，名必有实，事必有功。”', '《申鉴》是中国东汉末思想家荀悦的政治、哲学论著。《后汉书》本传说，荀悦志在匡辅献帝，因曹操揽政，“谋无所用，乃作《申鉴》”。意为重申历史经验，供皇帝借鉴。全书5卷，包括《政体》、《时事》、《俗嫌》、《杂言》5篇。明代黄省曾做了注释，有明嘉靖四年黄氏文始堂刊本，涵芬楼《四部丛刊》影印明文始堂本等。《申鉴》有明黄省曾所作注，《四库全书总目》称其“引据博洽，多得悦旨”。有《龙溪精舍丛书》本、《小万卷楼丛书》本以及《四部丛刊》影印明文始堂刊本。', '', '', NULL, '', 'indent', 1545340431, '5c1b958f67f356005fce918b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640794, '大略', NULL, 36, 13, 3, 3, '荀子', NULL, 10279, '57b902bbdf0eea006334f0d0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%A4%A7%E7%95%A5#2', '', '君人者，隆礼尊贤而王，重法爱民而霸，好利多诈而危。欲近四旁，莫如中央，故王者必居天下之中，礼也。
天子外屏，诸侯内屏，礼也。外屏、不欲见外也；内屏、不欲见内也。
诸侯召其臣，臣不俟驾，颠倒衣裳而走，礼也。诗曰：“颠之倒之，自公召之。”天子召诸侯，诸侯辇舆就马，礼也。诗曰：“我出我舆，于彼牧矣。自天子所，谓我来矣。”
天子山冕，诸侯玄冠，大夫裨冕，士韦弁，礼也。
天子御珽，诸侯御荼，大夫服笏，礼也。
天子雕弓，诸侯彤弓，大夫黑弓，礼也。
诸侯相见，卿为介，以其教士毕行，使仁居守。
聘人以圭，问士以璧，召人以瑗，绝人以玦，反绝以环。
人主仁心设焉，知其役也，礼其尽也，故王者先仁而后礼，天施然也。
聘礼志曰：“币厚则伤德，财侈则殄礼。”礼云礼云，玉帛云乎哉！诗曰：“物其指矣，唯其偕矣。”不时宜，不敬文，不欢欣，虽指非礼也。
水行者表深，使人无陷；治民者表乱，使人无失，礼者，其表也。先王以礼义表天下之乱；今废礼者，是弃表也，故民迷惑而陷祸患，此刑罚之所以繁也。
舜曰：“维予从欲而治。”故礼之生，为贤人以下至庶民也，非为成圣也；然而亦所以成圣也，不学不成；尧学于君畴，舜学于务成昭，禹学于西王国。
五十不成丧，七十唯衰存。
亲迎之礼，父南向而立，子北面而跪，醮而命之：“往迎尔相，成我宗事，隆率以敬先妣之嗣，若则有常。”子曰：“诺！唯恐不能，敢忘命矣！”
夫行也者，行礼之谓也。礼也者，贵者敬焉，老者孝焉，长者弟焉，幼者慈焉，贱者惠焉。
赐予其宫室，犹用庆赏于国家也；忿怒其臣妾，犹用刑罚于万民也。
君子之于子，爱之而勿面，使之而勿视，道之以道而勿强。
礼以顺人心为本，故亡于礼经而顺于人心者，皆礼也。
礼之大凡：－－事生、饰欢也，送死、饰哀也，军旅、施威也。
亲亲、故故、庸庸、劳劳，仁之杀也；贵贵、尊尊、贤贤、老老、长长、义之伦也。行之得其节，礼之序也。仁、爱也，故亲；义、理也，故行；礼、节也，故成。仁有里，义有门；仁、非其里而处之，非仁也；义，非其门而由之，非义也。推恩而不理，不成仁；遂理而不敢，不成义；审节而不和，不成礼；和而不发，不成乐。故曰：仁义礼乐，其致一也。君子处仁以义，然后仁也；行义以礼，然后义也；制礼反本成末，然后礼也。三者皆通，然后道也。
货财曰赙，舆马曰赗，衣服曰襚，玩好曰赠，玉贝曰唅。赙赗、所以佐生也，赠襚、所以送死也。送死不及柩尸，吊生不及悲哀，非礼也。故吉行五十，奔丧百里，赗赠及事，礼之大也。
礼者、政之挽也；为政不以礼，政不行矣。
天子即位，上卿进曰：“如之何忧之长也？能除患则为福，不能除患则为贼。”授天子一策。中卿进曰：“配天而有下土者，先事虑事，先患虑患。先事虑事谓之接，接则事优成。先患虑患谓之豫，豫则祸不生。事至而后虑者谓之后，后则事不举。患至而后虑者谓之困，困则祸不可御。”授天子二策。下卿进曰：“敬戒无怠，庆者在堂，吊者在闾。祸与福邻，莫知其门。豫哉！豫哉！万民望之。”授天子三策。
禹见耕者耦、立而式，过十室之邑、必下。
杀大蚤，朝大晚，非礼也。治民不以礼，动斯陷矣。
平衡曰拜，下衡曰稽首，至地曰稽颡。
大夫之臣，拜不稽首，非尊家臣也，所以辟君也。
一命齿于乡，再命齿于族，三命，族人虽七十不敢先。上大夫，中大夫，下大夫。
吉事尚尊，丧事尚亲。
聘、问也。享、献也。私觌、私见也。
言语之美，穆穆皇皇。朝廷之美，济济鎗鎗。
为人臣下者，有谏而无讪，有亡而无疾，有怨而无怒。
君于大夫，三问其疾，三临其丧；于士，一问，一临。诸侯非问疾吊丧不之臣之家。
既葬，君若父之友食之则食矣，不辟梁肉，有醴酒则辞。
寝不逾庙，燕衣不逾祭服，礼也。
汤之咸，见夫妇。夫妇之道，不可不正也，君臣父子之本也。咸、感也，以高下下，以男下女，柔上而刚下。
聘士之义，亲迎之道，重始也。
礼者，人之所履也，失所履，必颠蹶陷溺。所失微而其为乱大者，礼也。
礼之于正国家也，如权衡之于轻重也，如绳墨之于曲直也。故人无礼不生，事无礼不成，国家无礼不宁。君臣不得不尊，父子不得不亲，兄弟不得不顺，夫妇不得不欢，少者以长，老者以养。故天地生之，圣人成之。
和鸾之声，步中武象，趋中韶护。君子听律习容而后出。
霜降逆女，冰泮杀止，十日一御。
坐视膝，立视足，应对言语视面。立视前六尺而大之－－六六三十六，三丈六尺。
文貌情用，相为内外表里。礼之中焉，能思索谓之能虑。
礼者，本末相顺，终始相应。
礼者，以财物为用，以贵贱为文，以多少为异。
下臣事君以货，中臣事君以身，上臣事君以人。
易曰：“复自道，何其咎？”春秋贤穆公，以为能变也。
士有妒友，则贤交不亲；君有妒臣，则贤人不至。蔽公者谓之昧，隐贤者谓之妒，奉妒昧者谓之交谲。交谲之人，妒昧之臣，国之薉孽也。
口能言之，身能行之，国宝也。口不能言，身能行之，国器也。口能言之，身不能行，国用也。口言善，身行恶，国妖也。治国者敬其宝，爱其器，任其用，除其妖。
不富无以养民情，不教无以理民性。故家五亩宅，百亩田，务其业，而勿夺其时，所以富之也。立大学，设庠序，修六礼，明七教，所以道之也。诗曰：“饮之食之，教之诲之。”王事具矣。
武王始入殷，表商容之闾，释箕子之囚，哭比干之墓，天下乡善矣。
天下国有俊士，世有贤人。迷者不问路，溺者不问遂，亡人好独。诗曰：“我言维服，勿用为笑。先民有言，询于刍荛。”言博问也。
有法者以法行，无法者以类举。以其本知其末，以其左知其右，凡百事异理而相守也。庆赏刑罚，通类而后应；政教习俗，相顺而后行。
八十者一子不事，九十者举家不事，废疾非人不养者，一人不事，父母之丧，三年不事，齐衰大功，三月不事，从诸侯来，与新有昏，期不事。
子谓子家驹续然大夫，不如晏子；晏子功用之臣也，不如子产；子产惠人也，不如管仲；管仲之为人，力功不力义，力知不力仁，野人也，不可为天子大夫。
孟子三见宣王，不言事。门人曰：“曷为三遇齐王而不言事？”孟子曰：“吾先攻其邪心。”
公行子之之燕，遇曾元于涂，曰：“燕君何如？”曾元曰：“志卑。志卑者轻物，轻物者不求助；苟不求助，何能举？氐羌之虏也，不忧其系垒也，而忧其不焚也。利夫秋毫，害靡国家，然且为之，几为知计哉！”
今夫亡箴者，终日求之而不得；其得之也，非目益明也，眸而见之也。心之于虑亦然。
“义”与“利”者，人之所两有也。虽尧舜不能去民之欲利；然而能使其欲利不克其好义也。虽桀纣不能去民之好义；然而能使其好义不胜其欲利也。故义胜利者为治世，利克义者为乱世。上重义则义克利，上重利则利克义。故天子不言多少，诸侯不言利害，大夫不言得丧，士不通货财。有国之君不息牛羊，错质之臣不息鸡豚，冢卿不修币，大夫不为场园，从士以上皆羞利而不与民争业，乐分施而耻积藏；然故民不困财，贫窭者有所窜其手。
文王诛四，武王诛二，周公卒业，至成康则案无诛已。
多积财而羞无有，重民任而诛不能，此邪行之所以起，刑罚之所以多也。
上好义，则民闇饰矣！上好富，则民死利矣！二者治乱之衢也。民语曰：“欲富乎？忍耻矣！倾绝矣！绝故旧矣！与义分背矣！”上好富，则人民之行如此，安得不乱！
汤旱而祷曰：“政不节与？使民疾与？何以不雨至斯极也！宫室荣与？妇谒盛与？何以不雨至斯之极也！苞苴行与？谗夫兴与？何以不雨至斯极也！”
天之生民，非为君也；天之立君，以为民也。故古者，列地建国，非以贵诸侯而已；列官职，差爵禄，非以尊大夫而已。
主道知人，臣道知事。故舜之治天下，不以事诏而万物成。农精于田，而不可以为田师，工贾亦然。
以贤易不肖，不待卜而后知吉。以治伐乱，不待战而后知克。
齐人欲伐鲁，忌卞庄子，不敢过卞。晋人欲伐卫，畏子路，不敢过蒲。
不知而问尧舜，无有而求天府。－－曰：先王之道，则尧舜已；六贰之博，则天府已。
君子之学如蜕，翻然迁之。故其行效，其立效，其置颜色、出辞气效。无留善，无宿问。
善学者尽其理，善行者究其难。
君子立志如穷，虽天子三公问正，以是非对。
君子隘穷而不失，劳倦而不苟，临患难而不忘细席之言。岁不寒无以知松柏，事不难无以知君子无日不在是。
雨小，汉故潜。夫尽小者大，积微者箸，德至者色泽洽，行尽而声问远，小人不诚于内而求之于外。
言而不称师谓之畔，教而不称师谓之倍。倍畔之人，明君不内，朝士大夫遇诸涂不与言。
不足于行者，说过；不足于信者，诚言。故春秋善胥命，而诗非屡盟，其心一也。善为诗者不说，善为易者不占，善为礼者不相，其心同也。
曾子曰：“孝子言为可闻，行为可见。言为可闻，所以说远也；行为可见，所以说近也；近者说则亲，远者悦则附；亲近而附远，孝子之道也。”
曾子行，晏子从于郊，曰：“婴闻之：君子赠人以言，庶人赠人以财。婴贫无财，请假于君子，赠吾子以言：乘舆之轮，太山之木也，示诸檃栝，三月五月，为帱采，敝而不反其常。君子之檃栝，不可不谨也。慎之！兰茞槁本，渐于蜜醴，一佩易之。正君渐于香酒，可谗而得也。君子之所渐，不可不慎也。”
人之于文学也，犹玉之于琢磨也。诗曰：“如切如磋，如琢如磨。”谓学问也。和之璧，井里之厥也，玉人琢之，为天子宝。子赣季路故鄙人也，被文学，服礼义，为天下列士。
学问不厌，好士不倦，是天府也。
君子疑则不言，未问则不言，道远日益矣。
多知而无亲，博学而无方，好多而无定者，君子不与。
少不讽诵，壮不论议，虽可，未成也。
君子壹教，弟子壹学，亟成。
君子进则益上之誉，而损下之忧。不能而居之，诬也；无益而厚受之，窃也。学者非必为仕，而仕者必如学。
子贡问于孔子曰：“赐倦于学矣，愿息事君。”孔子曰：“诗云：‘温恭朝夕，执事有恪。’事君难，事君焉可息哉！”“然则，赐愿息事亲。”孔子曰：“诗云：‘孝子不匮，永锡尔类。’事亲难，事亲焉可息哉！”“然则赐愿息于妻子。”孔子曰：“诗云：‘刑于寡妻，至于兄弟，以御于家邦。’妻子难，妻子焉可息哉！”“然则赐愿息于朋友。”孔子曰：“诗云：‘朋友攸摄，摄以威仪。’朋友难，朋友焉可息哉！”“然则赐愿息耕。”孔子曰：“诗云：‘昼尔于茅，宵尔索绹，亟其乘屋，其始播百谷。’耕难，耕焉可息哉！”“然则赐无息者乎？”孔子曰：“望其圹，皋如也，颠如也，鬲如也，此则知所息矣。”子贡曰：“大哉！死乎！君子息焉，小人休焉。”
国风之好色也，传曰：“盈其欲而不愆其止。其诚可比于金石，其声可内于宗庙。”小雅不以于污上，自引而居下，疾今之政以思往者，其言有文焉，其声有哀焉。
国将兴，必贵师而重傅，贵师而重傅，则法度存。国将衰，必贱师而轻傅；贱师而轻傅，则人有快；人有快则法度坏。
古者匹夫五十而士。天子诸侯子十九而冠，冠而听治，其教至也。
君子也者而好之，其人也；其人而不教，不祥。非君子而好之，非其人也；非其人而教之，赍盗粮，借贼兵也。
不自嗛其行者，言滥过。古之贤人，贱为布衣，贫为匹夫，食则饘粥不足，衣则竖褐不完；然而非礼不进，非义不受，安取此？
子夏家贫，衣若县鹑。人曰：“子何不仕？”曰：“诸侯之骄我者，吾不为臣；大夫之骄我者，吾不复见。柳下惠与后门者同衣，而不见疑，非一日之闻也。争利如蚤甲，而丧其掌。”
君人者不可以不慎取臣，匹夫不可不慎取友。友者、所以相有也。道不同，何以相有也？均薪施火，火就燥；平地注水，水流湿。夫类之相从也，如此其着也，以友观人，焉所疑？取友善人，不可不慎，是德之基也。诗曰：“无将大车，维尘冥冥。”言无与小人处也。
蓝苴路作，似知而非。懦弱易夺，似仁而非。悍戆好斗，似勇而非。
仁义礼善之于人也，辟之若货财粟米之于家也，多有之者富，少有之者贫，至无有者穷。故大者不能，小者不为，是弃国捐身之道也。
凡物有乘而来，乘其出者，是其反也。
流言灭之，货色远之。祸之所由生也，生自纤纤也。是故君子蚤绝之。
言之信者，在乎区盖之间。疑则不言，未问则不言。
知者明于事，达于数，不可以不诚事也。故曰：“君子难说，说之不以道，不说也。”
语曰：“流丸止于瓯臾，流言止于知者。”此家言邪说之所以恶儒者也。是非疑，则度之以远事，验之以近物，参之以平心，流言止焉，恶言死焉。
曾子食鱼，有余，曰：“泔之。”门人曰：“泔之伤人，不若奥之。”曾子泣涕曰：“有异心乎哉！”伤其闻之晚也。
无用吾之所短，遇人之所长。故塞而避所短，移而从所仕。疏知而不法，辨察而操僻，勇果而无礼，君子之所憎恶也。
多言而类，圣人也；少言而法，君子也；多言无法，而流湎然，虽辩，小人也。
国法禁拾遗，恶民之串以无分得也，有夫分义，则容天下而治；无分义，则一妻一妾而乱。
天下之人，唯各特意哉，然而有所共予也。言味者予易牙，言音者予师旷，言治者予三王。三王既以定法度，制礼乐而传之，有不用而改自作，何以异于变易牙之和，更师旷之律？无三王之法，天下不待亡，国不待死。
饮而不食者，蝉也；不饮不食者，浮蝣也。
虞舜、孝己孝而亲不爱，比干、子胥忠而君不用，仲尼、颜渊知而穷于世。劫迫于暴国而无所辟之，则崇其善，扬其美，言其所长，而不称其所短也。
惟惟而亡者，诽也；博而穷者，訾也；清之而俞浊者，口也。
君子能为可贵，不能使人必贵己；能为可用，不能使人必用己。
诰誓不及五帝，盟诅不及三王，交质子不及五伯', '', '', '概括地说，统治人民的君主，崇尚礼义尊重贤人就能称王天下，注重法治爱护人民就能称霸诸侯，贪图财利多搞欺诈就会危险。
想要接近那四旁，那就不如在中央。所以称王天下的君主一定住在天下的中心地区，这是一种礼制。
天子将照壁设在门外，诸侯将照壁设在门内，这是一种礼制。把照壁设在门外，是不想让里面看见外面；把照壁设在门内，是不想让外面看见里面。
诸侯召见他的臣子时，臣子不等驾好车，没把衣裳穿整齐就跑，这是一种礼制。《诗经》上说：“颠倒歪斜穿衣裙，因人召我来自君。”天子召见诸侯的时候，诸侯让人拉着车子去靠近马，这是一种礼制。《诗经》上说：“战车推出套上马，急驰野外点兵场。我从天子身边来，奉命出征上前方。”
天子穿画有山形图案的礼服、戴礼帽，诸侯穿黑色的礼服、戴礼帽，大夫穿裨衣、戴礼帽，士戴熟皮制的暗红色帽子，这是一种礼制。天子使用上端呈椎形的大玉版，诸侯使用上端呈圆形的玉版，大夫使用斑竹制的手版，这是一种礼制。天子用雕有花纹的弓，诸侯用红色的弓，大夫用黑色的弓，这是一种礼制。
诸侯互相会见的时候，卿做介绍人，使自己那些受过礼仪教育的士人全部前往，让仁厚的人留守。派使者到诸侯国去问侯人用珪，去作国事访问用璧，召见群臣用瑷，与人断绝关系用玦，召回被拒绝的人用环。
君主首先要具备仁爱之心，智慧是仁爱之心役使的东西，礼制是仁爱之心的完备体现。所以，称王天下的人首先讲究仁德，然后才讲究礼节，自然的安排就是这样。《聘礼》记载说：“礼物丰厚就会伤害德行，财物奢侈就会吞没礼制。”礼呀礼呀，难道只是指玉帛这些贵重礼品吗？《诗经》上说：“各种食物味真美，因为它们合口味。”如果不与时节相适合，不恭敬有礼貌，不喜悦快乐，那么即使味道很美，也不合乎礼制的要求。
在水中跋涉的人用标志来表明深度，使人不致于陷入深水淹死；治理民众的人用标准来表明祸乱，使人不致于失误。礼制，就是这种标准，古代的圣明帝王用礼制来彰明天下的祸乱。现在废除礼制，这是在丢掉标准啊，所以民众迷惑而陷于祸乱。这就是刑罚繁多的原因。
舜说：“只有我能随心所欲地治理天下。”所以，礼的产生，是为了贤人以及下面群众的，并不是为了使人成为圣人，然而这也是人之所以成为圣人的原因。如果不经过学习，是不能成为有成就的圣人的。尧曾向君畴学习，舜曾向务成昭学习，禹曾向西王国学习。
五十岁的人不需要全部做到守丧的礼节，七十岁的人只要丧服在身就行了。
新郎亲自去迎接新娘的礼仪：父亲面向南站着，儿子面向北跪着，父亲一边斟酒祭神一边嘱咐儿子：“去迎接你的贤内助，完成我家传宗接代以祭祀宗庙的大事，好好带领她去恭敬你的母亲，做你母亲的继承人，你的行动则要有常规。”儿子说：“是，我只怕没有能力做到，决不敢忘记您的嘱咐。”
所谓德行，就是指奉行礼义。所谓礼义，就是对地位高贵的人要尊敬，对年老的人要孝顺，对年长的人要敬从，对年幼的人要慈爱，对卑贱的人要给予恩惠。
在自己家庭内进行赏赐，应当像在国家中使用表彰赏赐一样；对自己的家臣、妻妾奴婢发怒动刑，应当像对民众使用刑罚一样；君子对于子女，疼爱他们而不表现在脸上，使唤他们而不露神色，用正确的道理来引导他们而不强迫他们接受。
礼以顺应人心为根本。所以，在《礼经》上虽然没有记载，但只要能顺应人心的，都是礼。
礼仪的大致情况是：用于侍奉生者的，是为了润饰喜悦之情；用于葬送死者的，是为了更好地表现悲哀之情；用于军队的，是为了装饰威武之势。
亲近父母亲、热情对待老朋友、奖赏有功劳的人、慰劳付出劳力的人，这是仁方面的等级差别；尊崇身份贵重的人、尊敬官爵显赫的人、尊重有德才的人、敬爱年老的人、敬重年长的人，这是义方面的伦理常规。奉行这些仁义之道能恰如其分，就是礼的秩序。
仁，就是爱人，所以能和人互相亲近；义，就是合乎道理，所以能够实行；礼，就是适度，所以能够成功。仁有安居之处，义有进出之门。仁，如果不是它应该安居的地方却去安顿在那里，就不是什么仁；义，如果不是它应该进出的门户而从那里进出，就不是什么义。施行恩惠而不合乎道理，就不成为仁；通达道理而不敢遵行，就不成为义；明白制度而不能使人们和睦协调，就不成为礼；和睦协调了而不抒发出来，就不成为乐。所以说：仁、义、礼、乐，它们要达到的目标是一致的。
君子根据义来处置仁，然后才有了仁；根据礼来奉行义，然后才有了义；制定礼时回头抓住它的根本原则，从而再完成它的具体细节，然后才有了礼。这三者都精通了，然后才是正道。
帮助别人办丧事而赠送的财物叫做赙，赠送的车马叫做赗，赠送的寿衣衾服叫做禭，赠送死者所玩赏嗜好的物品叫做赠，赠送的珠玉贝壳供死人含在口中的叫做唅。赙、赗，是用来帮助死者家属的；赠、禭、唅，是用来葬送死者的。送别死者时不见到棺材里的尸体，哀悼死者而安慰其家属时不达到悲哀，是不合乎礼制的。所以，参加吉礼时一天走五十里，而奔丧时一天要跑一百里，帮助别人办丧事而赠送的东西一定要赶上丧事，这是礼节的大端啊。
礼，是政治的指导原则。治理政事如果不按照礼义行事，政策就不能实行。天子刚登上帝位时，上卿走上前说：“天下的忧虑这样深长，您该怎么办呢？能够除去祸患就有幸福，不能除去祸患就会受害。”说完就把第一篇册书交给天子。中卿走上前说：“和上天相配而拥有天下土地的人，在事情发生之前就要考虑到那事情，在祸患来到之前就要考虑到祸患。在事情发生之前就考虑到那事情叫做敏捷，能够敏捷，那么事情就会圆满成功；在祸患来到之前就考虑到祸患叫做预先准备，能够预先准备，那么祸患就不会发生。事情发生以后才加以考虑的叫做落后；落后了，那么事情就办不成；祸患来了以后才加以考虑的叫做困厄，困厄了，那么祸患就不能抵挡了。”说完就把第二篇册书交给天子。下卿走上前说：“慎重戒备而不要懈怠！有时庆贺的人还在大堂上，吊丧的人已到了大门口。灾祸和幸福紧靠着，人们有时还不知道它们产生的原因和地方。要预先准备啊！要预先准备啊！亿万人民都仰望着您。”说完就把第三篇册书交给天子。
禹看见耕地的人两人并肩耕作，就站起来扶着车厢前的横木；经过十来户人家的小镇，一定下车。
猎取禽兽太早，上朝太晚，不合乎礼。治理民众不根据礼，一动就会失足。
弯腰后头与腰相平叫做拜，头比腰低叫做稽首，头着地叫做稽颡。大夫的家臣对大夫只拜而不稽首，这不是为了提高家臣的地位，而是避免大夫和国君在礼节等级上的相同。
在乡内饮酒时，一级官员和乡里的人按照年龄大小来排列位次；二级官员和同宗族的人按年龄大小来排列位次；至于三级官员，那么同宗族的人即使七十岁了，也不敢排在他前面。大夫分上大夫、中大夫、下大夫。
在吉庆的事中，要按照官位高低或地位尊卑的关系位列座次，在丧事中，要按照与死者的亲疏关系来排列座次。君臣之间如果得不到君子的治理就不会有尊重，父子之间得不到君子的治理就不会亲近，兄弟之间得不到君子的治理就不会和顺，夫妻之间得不到君子的治理就不会欢乐。年幼的人靠了君子的治理而长大成人，年老的人靠了君子的治理而得到赡养。所以，天地提供物质生活而养育了人，圣人进行礼仪教化与治理而成就了人。
聘，就是相互派遣使者问候。享，就是使者奉命把礼物进献给天子和诸侯。私觌，就是以私人的身份和为臣之礼私下拜见诸侯。形容言语的美好，就说“穆穆皇皇”。形容朝廷的美好，就说“济济跄跄”。
给人当臣子的，只能规劝而不能毁谤上司，只能出走而不能憎恨上司，只能埋怨而不能对上司发怒。君主对于大夫，在他生病时去慰问三次，在他死后去祭奠三次；对于士，慰问一次，祭奠一次。诸侯如果不是探望疾病、祭奠死者，不到臣子的家里。父亲或母亲已经埋葬以后，君主或者父亲的朋友让自己吃饭，就可以吃了，不回避米饭肉食，但有酒就要谢辞。寝殿的规模不能超过庙堂，参加燕礼所穿的衣服不能超过祭祀所穿的礼服，这是一种礼制。
《易经》中的《咸》卦，显示了夫妻之道。夫妻之道，是不能不端正的，它是君臣、父子关系的根本。咸，就是感应的意思，它的符号是把高的置于低的之下，把男的置于女的之下，是柔和在上面而刚劲在下面。聘请贤士的仪式，新郎亲自去迎接新娘的办法，都是注重开端。
礼，是人立身处事必须遵照执行的基本原则。人如果失去了立身之处，就一定会跌倒沉沦，陷入危难之中。只要稍微有偏差，就会导致的巨大的祸乱，这就是礼的作用。礼对于整饬国家，就像秤对于轻重一样，就像墨线对于曲直一样。所以，人不懂得礼义就不能在社会上生存，办事情不懂得礼义就不能办成，国家没有礼就不得安宁。
车铃的声音，在车子慢行时合乎《武》、《象》的节奏，在车子奔驰时合乎《韶》、《护》的节奏。君子要听听走路时佩玉的声音是否合乎节律，并练习好举止仪表，然后才可以成为儒雅之士。
从霜降开始娶妻，到第二年河里的冰溶化时就停止婚娶。对正妻，十天同房一次。
对方坐着，注视他的膝部；对方站着，注视他的脚；回答说话时，注视他的脸。对方站着时，在他前面六尺处注视他，而最远是六六三十六尺，即在三丈六尺之处注视他。礼仪容貌和感情作用互相构成内外表里的关系，这是适中的礼。善于思索叫做虑。礼制的根本原则和具体细节互不抵触，人生终结的仪式与人生开始的仪式互相应合。所谓礼制，就是把钱财物品等外在之物作为工具，把尊贵与卑贱的区别作为礼义制度，把享受的多少作为尊卑贵贱的差别。
下等的臣子用财物来侍奉君主，中等的臣子用自己的不懈努力乃至用自己的生命来侍奉君主，上等的臣子推荐人才来侍奉君主。《易经》上说：“回到自己的道路，有什么过错？”赞许秦穆公，认为他能够改正自己的过失、转变自己固有的思想。
士人一旦结交了喜欢妒忌的朋友，那么贤德之人就不会亲近他；君主有了喜欢妒忌的臣子，那么贤德之人就不会到来。隐瞒公道的人叫做欺昧，埋没贤良的人叫做妒忌，奉承妒忌欺昧的人叫做狡猾诡诈。狡猾诡诈的小人，妒忌欺昧的臣子，是国家的垃圾和妖孽。
嘴里能够谈论礼义，自身能够奉行礼义，这种人是国家的珍宝。嘴里不能谈论礼义，自身能够奉行礼义，这种人是国家的器具。嘴里能够谈论礼义，自身不能奉行礼义，这种人只能是国家的工具。嘴里说得好，自身干坏事，这种人简直就是是国家的妖孽。治理国家的人敬重国家的珍宝，爱护国家的器具，使用国家的工具，铲除国家的妖孽。
不使民众富裕就无法调养民众的思想感情，不进行教育就无法整饬民众的本性。每家配置五亩宅基地，一百亩耕地，努力从事农业生产而不耽误他们的农时，这是使他们富裕起来的办法。建立国家的高等学府，设立地方学校，整饬六种礼仪，彰明七个方面的教育，这是用来引导他们的办法。《诗》云：“给人喝啊给人吃，教育人啊指导人。”像这样，称王天下的政事就完备了。
周武王刚进入殷都的时候，在商容所住的里巷门口设立了标记以表彰他的功德，解除了箕子的囚禁生活，在比干的墓前痛哭哀悼，于是天下人就都趋向行善了。天下的每一个国家都有才智出众的人，每个时代都有贤能的人。迷失方向的人，是由于不询问道路；被水淹没的人，是因为不询问水路的结果；导致国家灭亡的，是那些喜欢独断专行的君主。《诗经》上说：“我所说的是要事，不要以为开玩笑。古人曾经有句话：要向樵夫去请教。”这是说要广泛地询问各方面的人。
有法律依据的就按照法律来办理，没有法律条文可遵循的就按照类推的办法来办理。根据它的根本原则推知它的细节，根据它的一个方面推知它的另一个方面。大凡各种事情，道理虽然不同却互相制约着。对于表扬奖赏与用刑处罚，通达了类推的原理，然后才能有相应的处置。政治教化与风俗习惯相适应，然后才能实行。
八十岁的人，可以有一个儿子不服劳役；九十岁的人，全家都可以不服劳役；残废有病、没有人照顾就不能活下去的，家里可以有一个人不服劳役。有父亲、母亲的丧事，可以三年不服劳役；齐衰和大功，可以三个月不服劳役。从其他诸侯国迁来以及新结婚的，可以一年不服劳役。
孔子说：子家驹是增益君主明察的大夫，及不上晏子；晏子，是个有成效的臣子，及不上子产；子产，是个给人恩惠的人，及不上管仲；管仲的立身处事，致力于功效而不致力于道义，致力于智谋而不致力于仁爱，是个缺乏礼义修养的人，不可以做天子的大夫。
孟子三次见到齐宣王而不谈国事。他的学生说：“为什么三次碰到齐王都不谈国事？”孟子说：“我先要打击他只讲求功利称霸的坏思想。”
公行子之到燕国去，在路上碰到曾元，说：“燕国国君怎么样？”曾元说：“他的志向不远大。志向不远大的人看轻事业，看轻事业的人不找人帮助。如果不找人帮助，哪能成就事业呢？他只能是氐族人、羌族人的俘虏。他不担忧自己被捆绑，却担忧自己死后不能按照氐族、羌族的习俗被火化。得到的利益就像那秋天新长出来的兽毛一样细微，而危害却有损于国家，这样的事他尚且要去做，哪能算是懂得治理国家大计的人呢？”
现在那丢了针的人，整天找它都没找到；当他找到它时，并不是眼睛更加明亮了，而是睁大了眼睛才发现它的。心里考虑问题也是这样。
讲求道义和私利，是人们兼有的东西。即使是尧舜这样的贤君也不能除去民众追求私利的欲望，但是能够使他们对私利的追求敌不过他们对道义的爱好；即使是夏桀、商纣这样的暴君也不能去掉民众对道义的爱好，但是能够使他们对道义的爱好敌不过他们对私利的追求。所以，道义胜过私利的就是治理得好的社会，私利胜过道义的就是混乱的社会。君主看重道义，道义就会胜过私利；君主推崇私利，私利就会胜过道义。所以，天子不谈论财物多少，诸侯不谈论有利还是有害，大夫不谈论得到还是失去，士不去贩运买卖货物。拥有国家的君主不养殖牛和羊，献身于君主的臣子不养殖鸡和小猪，上卿不放高利贷，大夫不筑场种菜，从士以上的官吏都以追求私利为羞耻而不和民众争抢职业，喜欢施舍而以囤积私藏为耻辱。所以，民众不为钱财所困扰，贫穷的人也不会手足无措了。
周文王讨伐了四个国家，周武王诛杀了两个人，周公旦完成了称王天下的大业，到周成王、周康王的时候就没有杀伐了。
赞许积聚钱财而把一无所有看作羞耻，加重人民的负担而惩处不堪负担的人，这是邪恶行为产生的根源，也是刑罚繁多的原因。
君主爱好义，那么民众就暗自振作、端正自己的言行了；君主爱好财富，那么民众就为利而死了。这两点，是治和乱的分水岭。民间俗语说：“想富贵吗？忍着耻辱吧，道德败坏吧，与故旧一刀两断吧，与道义背道而驰吧。”君主爱好财富，那么人民的行为就是这样，怎么能不乱呢？
商汤因为大旱而向神祷告说：“是我的政策不适当吗？是我役使民众太苦了吗？为什么旱到这种极端的地步还不下雨呢？是我的宫殿房舍太华丽了吗？是妻妾嫔妃说情请托太多了吗？为什么旱到这种极端的地步还不下雨呢？是贿赂盛行吗？是毁谤的人发迹了吗？为什么旱到这种极端的地步还不下雨呢？”
上天生育民众并不是为了君主，上天设立君主却是为了民众。所以在古代，分封土地建立诸侯国，并不只是用来尊重诸侯而已；安排各种官职，区别爵位俸禄的等级，并不只是用来尊重大夫而已。
为君之道在于选拔使用人才，为臣之道在于精通和处理好政事。所以，从前舜治理天下，不用事事告诫而各种事情也就办成了。农夫对种地很精通却不能因此而去做管理农业的官吏，工人和商人也是这样。
用贤能的人去替换没有德才的人，不等占卜就知道是吉利的。用安定的国家去攻打混乱的国家，不等交战就知道能攻克。齐国人想攻打鲁国，顾忌卞庄子，不敢经过卞城。晋国人想攻打卫国，害怕子路，不敢经过蒲邑。
不懂政治就去询问尧舜的治国之道，没有学问就去去求助于天子的库籍。要我说啊，古代圣王的政治原则，就是尧舜的政治原则；六经包含的丰富内容，就是知识的宝库。君子的学习就像蛇，蝉等脱壳一样，很快就会有所改变。所以，他走路效仿，站立效仿，坐着效仿，他摆什么脸色、讲什么话、用什么口气都效仿。不把好事留下不做，不把要问的事拖过夜。善于学习的人彻底搞通事物的道理，善于做事的人彻底克服工作中的困难。
君子一旦树立了志向就坚定不移，即使天子、三公询问政事，也根据是非的实际情况来回答。君子穷困而不丧失志气，劳累而不苟且偷安，面临祸患而不背弃平时坐席上说的话。岁月不寒冷就无从知道松柏的坚毅挺拔，事情不危难就无从知道君子的志向远大。作为君子，没有一天不在坚持他所认为正确的东西即道的。
雨虽然小，汉水却照旧流入潜水。尽量收罗微小的就能变成巨大，不断积累隐微的就会变得显著。道德极高的人脸色态度就和润，品行完美的人名声就传得远。而小人却不充实自己的内在品质只是到外界去追求美好的声誉，这是徒劳的。
说话时不称道老师叫做反叛，教学时不称道老师叫做背离。背叛老师的人，英明的君主不接纳，朝廷内的士大夫在路上碰到他不和他说话。在行动上不踏实的人，往往言过其实，夸夸其谈；在信用方面不诚实的人，往往表面上装成说话诚恳的样子。所以，《春秋》赞美诸侯互相之间的口头约定，而《诗经》非议诸侯们屡次订立盟约，他们的用心是一致的。善于研治《诗》的人不作解说，善于研治《易》的人不占卦，善于研治《礼》的人不辅助行礼，他们的用心是相同的。
曾子说：“孝子说的话是可以让人听的，做的事是可以让人看的。说的话可以让人听，是用来使远方的人悦服；做的事可以让人看，是用来使近处的人高兴。近处的人高兴了就会来亲近，远方的人悦服了就会来归附。使近处的人来亲近而远方的人来归附，这是孝子遵行的原则。”
曾子要走了，晏子跟着送到郊外，说：“晏婴听说过这样的话：‘君子用言语赠送人，百姓用财物赠送人。’我晏婴贫穷没有财物，请让我冒充君子，拿话来赠送给您：马车的轮子，原是泰山上的木头，把它放置在整形器中，经过三五个月就做成了车框、车幅和车毂，即使是裹住车毂的皮革坏了，也不会使它恢复到原来的形状了。君子对于正身的工具，不能不谨慎地对待啊，要慎重地对待它！兰芷、稿本等香草，如果浸在蜂蜜和甜酒中，一经佩带就要更换它。正直的君主如果泡在香酒似的甜言蜜语中，也会被谗言俘虏。君子对于所渐染的环境，不能不谨慎地对待啊。”
“人对于学习研究古代文献典籍，就像雕琢师对于雕琢玉石一样。《诗经》上说：“就像治骨磨象牙，就像雕玉磨石器。”就是说的做学问啊。卞和的玉璧，原是乡里固定门闩的楔形石块，经过加工玉器的工匠对它进行仔细雕琢之它，就成了天下的珍宝。子贡、子路，原是浅陋的人，受到了文献典籍的影响，遵从了礼义，就成了天下屈指可数的儒士名人。”
学习请教不满足，爱好文人贤达之士不厌倦，就可以获得很多知识，取得巨大的成就。君子对于存有疑惑的就不说，还没有请教过的就不谈论。这样做的时间长了，知识就会一天天增加。但知道得很多而没有什么特别的爱好，学习得很广而没有个主攻方向，喜欢学得很多而没有个确定目标的人，君子是不会和他结交的。少年时不读书，壮年时不发表议论，这样的人即使资质还可以，也不能有所成就。君子专心一意教授，学生专心一意学习，就能迅速取得成就。君子入朝做官，就能增加君主的荣誉而减少民众的忧患。没有才能而呆在官位上，就是行骗；对君主民众毫无裨益而享受优厚的俸禄，就是盗窃。学习的人不一定都是为了去做官，而做官的人一定要努力学习。
子贡问孔子说：“我对学习感到厌倦了，希望停止学习去侍奉君主。”孔子说：“《诗经》上说：‘早晚温和又恭敬，做事认真又谨慎。’侍奉君主不容易，侍奉君主怎么可以停止学习呢？”子贡说：“这样的话，那么我希望停止学习去侍奉父母。”孔子说：“《诗经》上说：‘孝子之孝无穷尽，上天才会赐福你。’侍奉父母不容易，侍奉父母怎么可以停止学习呢？”子贡说：“这样的话，那么我希望停止学习去娶妻生子。”孔子说：“《诗经》上说：‘先给妻子作榜样，然后影响到兄弟，以此治理家和邦。’养育妻儿不容易，养育妻儿怎么可以停止学习呢？”子贡说：“这样的话，那么我希望停止学习去结交朋友。”孔子说：“《诗经》上说：‘朋友之间要相互辅助，相助才能仪表威严。’和朋友在一起不容易，在朋友那里怎么可以停止学习呢？”子贡说：“这样的话，那么我希望停止学习去种田。”孔子说：“《诗经》上说：‘白天要去割茅草，夜里搓绳要搓好，急忙登屋修屋顶，又要开始播种了。’种田不容易，种田怎么可以停止学习呢？”子贡说：“这样的话，那么我就永远没有停止学习的时候了吗？”孔子说：“远望那个坟墓，高高的样子，山顶般的样子，鼎鬲似的样子，看到这个你就知道可以停止学习的时间了。”
子贡说：“死亡的意义可真伟大啊！君子停止学习了，小人也就完结了。”
《国风》所讲的好色之事，按照古书上说法就是：“满足情欲而又不越轨。它的真诚不渝可以和金属石头的坚固不变相比，它的音乐可以纳入到宗庙中去。”《小雅》的作者不被腐朽的君主所用，自己引退而处于卑下的官位上，他们痛恨当时的政治，因而怀念过去，《小雅》的言辞富有文采，音乐具有哀怨的情调。
国家将要兴盛的时候，一定是尊敬老师而看重有技能的人才的；尊敬老师而看重有技能的人才，那么法度就能保持并得以推行。国家将要衰微的时候，一定是鄙视老师而看轻有技能的人才的；鄙视老师而看轻有技能的人才，那么人们就会有放肆之心；人有了放肆之心，那么法度就会破坏。
古代平民百姓到五十岁才能做官，而天子与诸侯的儿子十九岁就举行冠礼，举行冠礼后就可以参与治理政事，这是因为他们受到的教育极好的缘故啊。对于君子倾心爱慕的，就是可堪造就的理想的人选；对这种理想的人选不施教，是不吉利的。对于并非君子的人也倾心爱慕的人，就不是可堪造就的理想的人选；对这种并非理想的人选去施教，就是把粮食送给小偷，把兵器借给强盗。
不自我意识到自己德行不足的人，说话往往言过其实、夸夸其谈。古代的贤人，宁可卑贱得做个平民，贫穷得做个百姓，吃饭连稀饭也吃不饱，穿着连粗布衣也不完整。但是如果不按照礼制来提拔他，他就不入朝做官；如果不按照道义给他东西，他就不接受；哪会采取这种言过其实、夸夸其谈的做法？
子夏贫穷，衣服破烂得就像悬挂着的鹌鹑。有人说：“您为什么不去做官？”子夏说：“诸侯傲视我的，我不做他的臣子；大夫傲视我的，我不再见他。柳下惠和看守后门的人同样穿破烂的衣服，可是并没有人怀疑他的正直和德行，这已不是一天的传闻了。争权夺利就像抓住了指甲而丢了自己的手掌。”
统治人民的君主不可以不慎重地选取臣子，平民百姓不可以不慎重地选择朋友。朋友，是用来互相帮助的。如果奉行的原则不同，用什么来互相帮助呢？把柴草均匀地铺平而点上火，火总是向干燥的柴草上烧去；在平整的土地上灌水，水总是向潮湿的低洼地流去。那同类事物的互相依随就像这样的显著，根据朋友来观察人，还有什么可怀疑的呢？选取朋友、和别人友好，不可以不慎重，这是成就德行的基础啊。《诗经》上说：“别扶牛车向前进，尘土茫茫会脏身。”这是说不要和小人相处啊。
过分傲慢而喜欢显露自己，好像很明智其实并不是真正的明智。软弱无能而容易被人改变自己的志向，好像很仁慈其实并不是真正的仁慈。凶狠鲁莽而喜欢争斗，好像很勇敢其实并不是真正的勇敢。仁爱、道义、礼制、善行对于人来说，打个比方，就像是钱财粮食和家庭的关系一样，较多地拥有它的就富裕，较少地拥有它的就贫穷，丝毫没有的就困窘。所以，如果一个人像诸如仁爱、道义、礼制、善行等这些大事做不到，小事又不肯去做，这是抛弃国家、丢弃自己身家性命的做法啊。
所有的事物都是有一定的原因才出现和来临的。它所出现和来临的地方，也就是它所回归的地方。对于流言蜚语，要消灭它；面对钱财女色，要远离它。祸患所赖以产生的根源，都发生于那些细微的地方。所以君子及早地消灭祸患的苗头。
说话真实的人，存在于阙疑之中。疑惑的不说，没有请教过的不说。明智的人对事情十分清楚，对事理十分精通，我们不可以不忠诚地去侍奉明智的人啊。所以说：“对于君子，是难以使他高兴的，不通过正当的途径去使他高兴，他是不会高兴的。”
俗话说：“滚动的圆球滚到凹坑就停止了，流言蜚语碰到明智的人就止息了。”这就是那些私家之言与邪恶的学说憎恶儒者的原因。是对是错疑惑不决，就用久远的事情来衡量它，用新近的事情来检验它，用公正的观点来考察它，流言蜚语便会因此而止息，邪恶的言论便会因此而消亡。
曾子吃鱼有吃剩的，说：“把它和别的菜搀和在一起。”他的学生说：“搀和起来会伤害人的身体，不如再把它熬一下。”曾子流着眼泪说：“我难道别有用心吗？”为自己听到这种话太晚而感到悲伤。
不要用自己的短处去对付别人的长处。所以。要掩盖并回避自己的短处，迁就并依从自己的特长。通达聪明而不守法度，明察善辩而坚持的观点邪恶怪僻，勇敢果断而不按照礼法的要求去办事，这是君子所憎恶的。
话说得多而合乎礼义法度，便是圣人；话说得少而合乎礼义法度，就是君子；说多说少都不合礼义法度却还是放纵沉醉在其中，即使能言善辩，也是个小人。
国家的法令禁止拾取别人遗失的财物，这是憎恶民众习惯于不按规矩去取得财物。有了那名分道义，那就能包揽天下而把它治理好；没有名分道义，那么就是只有一妻一妾，也会搞得乱七八糟。
天下的人，虽然各有独特的看法，却也有共同赞许的东西。谈论美味的都赞许易牙，谈论音乐的都赞许师旷，谈论政治的都赞许三王。三王既已确定了法度、制作了礼乐制度而把它们传了下来，如果不遵用而加以改变并自己重新搞一套，那和变更易牙的调味、变更师旷的音律有什么不同呢？如果这样，天下不等片刻就会沦亡，国家不等片刻就会覆灭。
只喝水而不吃东西的，是蝉；不喝水又不吃东西的，是蜉蝣。
虞舜、孝己，孝顺父母而父母不爱他们，比干、子胥，忠于君主而君主不任用他们，孔子、颜渊，明智通达而在社会上穷困窘迫。被迫生活在暴君统治的国家中而又没有办法避开这种处境，那就崇尚这个国家的美好德行，宣扬这个国家的美好名声，称道这个国家的长处，而不宣扬这个国家的短处。
唯唯诺诺却没有好结果的，是由于他经常诽谤别人；知识渊博而处境困厄的，是由于他经常诋毁别人；越想澄清自己的名声，而名声愈来愈混浊的，是由于他经常搬弄口舌。
君子能够做到使自己品德高尚，但不能保证别人一定尊重自己；能够做到使自己成为可用之才，但不能保证别人一定任用自己。
向下发布告诫的命令与誓言，追溯不到五帝；两国之间结盟誓约，追溯不到三王；君主互相交换自己的儿子作为人质，追溯不到五霸。', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3aa", "shortContent": "王侯公卿多为人所敬畏，富与贵多为人所欲求，凡此爵禄财富，皆为身外之物，君子多淡然处之。荀子说，意志修立就可傲视富贵；以道义为己任，自身气势厚重，则可以轻视王侯公卿；内心不断自省，外物就都微不足道了。孔子云：“不义而富且贵，于我如浮云。”（《论语·述而》）孟子说：“古之贤士何独不然？乐其道而忘人之势，故王公不致敬尽礼则不得亟见之。”（《孟子·尽心上》）庄子曰：“物物而不物于物。”（《庄子·山木》）荀...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3ad", "shortContent": "这是说“勇”，其实还是在说“义”。\n\n《说文》：“勇，气也。从力甬声。……古文勇从心。”段注：“气之所至，力亦至焉。心之所至，气乃至焉。故古文勇从心。”这是说，虽然“勇”是一种“气”，但真正的“勇”，还得在“心”上找动力。“匹夫之勇”和“士君子之勇”的区别正在此。匹夫以“气”为主，气之所至，勇即随之。士君子“以志帅气”，“自反而不缩，虽褐宽博，吾不惴焉；自反而缩，虽千万人，吾往矣。”（《孟子·公孙...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3ae", "shortContent": "大分，最大分界。常体，通常的体现。\n\n这是讲荣辱与义利的关系以及由此而来的处世之道。荀子并不如汉儒一样否定利：“正其义不谋其利，明其道不计其功”（《汉书·董仲舒传》），而是让人注意两者的实现顺序：以“义”为出发点，利自然在其中；以“利”为出发点，不但得不到利，还会受辱。\n\n那么，什么是义，什么是利，两者的区别在何处？\n\n“义”的繁体字为“義”。《说文》：“义，己之威仪也。”段注：“古者威仪字作义。...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3bc", "shortContent": "义利之辩是中国自古以来备受关注的一个问题。\n\n义即宜，指公正合宜的道理和行为；利是物质利益。义在中国两千多年的封建社会中，一直是居于主导地位的道德价值评判标准，也是人们恪守的行为准则。中华民族历来就是一个尚义的民族：为了报燕太子丹的恩，荆轲慷慨高唱“风萧萧兮易水寒，壮士一去兮不复还”，西渡易水，只身一人深入虎穴刺杀秦王；刘备、关羽、张飞为了拯救百姓于水深火热之中，在桃园结为兄弟，希望共同做出一番事...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1545341889, '5c1b9b431579a3005fc8fb30', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640795, '续诗品·尚识', NULL, 27, 173, 1, 0, '袁枚', NULL, 10099, '57b921bed342d3005ac840e9', '清', 'shi', '诗', 'https://baike.baidu.com/item/%E5%AD%A6%E5%A6%82%E5%BC%93%E5%BC%A9%EF%BC%8C%E6%89%8D%E5%A6%82%E7%AE%AD%E9%95%9E/6315703?fr=aladdin', '', '学如弓弩，才如箭镞。
识以领之，方能中鹄。
善学邯郸，莫失故步。
善求仙方，不为药误。
我有禅灯，独照独知。
不取亦取，虽师勿师。', '“学如弓弩，才如箭镞”出自袁简斋的《续诗品·尚识》，说的是学问的根基好比弓弩，才能好比箭头，只有依靠厚实的见识来引导，才可以让才能很好发挥作用。', '', '', NULL, '', 'center', 1545342315, '5c1b9d074773f7005f0b7724', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640796, '杂兴', NULL, 35, 3, 1, 1, '顾嗣协', NULL, 36981, '5c1c3a03fb4ffe005f18b733', '清', 'shi', '诗', '', '', '骏马能历险，力田不如牛。
坚车能载重，渡河不如舟。
舍长以就短，智者难为谋。
生材贵适用，慎勿多苛求。', '', '力：一作犁。', '跑得快的好马能够穿越艰难险阻的地方，但耕起田地来，就不如牛了；坚固的车子能够载很重的东西，但过河就比不上船了；舍弃了它们的长处优点却要求他们在不善长的地方发挥作用，再聪明的人也很为难，用人做到扬长避短，不要过分要求别人！', NULL, '', 'center', 1545382617, '5c1c3a751579a3005fcd5790', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640797, '赠蒋经国', NULL, 31, 38, 1, 1, '于右任', NULL, 18916, '583baaa6c59e0d006b408160', '当代', 'shi', '诗', '', '', '计利当计天下利
求名应求万世名', '', '语出书法家于右任先生1961年给蒋经国题的条幅：
计利当计天下利
求名应求万世名
这副联语明白晓畅，含义隽永，深刻诠释了“利”、“名”二字的内涵，并晓以“天下”、“万世”之理，反映了儒家积极入世的名利观。关于“名”与“利”，古来论之多矣，惟明人庄元臣评析较详。他在《叔苴子·外编》中说：“人之好名者，其等有三：有好闾阎之名者，有好士大夫之名者，有好圣贤之名者，同为名而品第殊矣。惟利亦然，有好目睫之利者，好终身之利者，好子孙数十世之利者。好闾阎之名与目睫之利者，众人也；好士大夫之名与终身之利者，君子也；好圣贤之名与子孙数十世之利者，圣贤也。人之所异者，惟其所好名利者，有远近大小之不同而已矣。”联语作者正是从这样的圣贤之道的名利观出发，鼓励蒋氏从国家民族的长远利益出发，“计天下利”、“求万世名”。', '', NULL, '', 'center', 1545383417, '5c1c3b43808ca4565c827f8b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640798, '一花独放不是春', NULL, 30, 103, 1, 1, '无名氏', NULL, 10396, '57e63abf0bd1d0005bfbba07', '明', 'shi', '诗', 'https://baike.baidu.com/item/%E4%B8%80%E8%8A%B1%E7%8B%AC%E6%94%BE%E4%B8%8D%E6%98%AF%E6%98%A5/1857431', '', '一花独放不是春，万紫千红春满园。', '格言：出自明、清两代文人编写、增补的中国古代儿童启蒙书目《古今贤文（合作篇）》：一花独放不是春，万紫千红春满园。比喻缺少各种不同形式和风格的艺术作品就不算繁荣；也常比喻一个人、一个地区先进不是理想的效果。', '', '', NULL, '', 'center', 1545383369, '5c1c3d7167f356005fd35f45', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640804, '唐故监察御史赠尚书右仆射王公神道碑', NULL, 7, 815, 1, 1, '刘禹锡', NULL, 10047, '57b922b57db2a2005427bf3a', '唐', 'wen', '文', 'https://baike.baidu.com/item/%E5%94%90%E6%95%85%E7%9B%91%E5%AF%9F%E5%BE%A1%E5%8F%B2%E8%B5%A0%E5%B0%9A%E4%B9%A6%E5%8F%B3%E4%BB%86%E5%B0%84%E7%8E%8B%E5%85%AC%E7%A5%9E%E9%81%93%E7%A2%91/22855879?fr=aladd', '', '唐故监察御史赠尚书右仆射王公神道碑
公讳俊，字真长，其先叶黄帝。夫圣人之后，与庶姓不同，如河出昆仑，潜于厚地，焉振起，奋为洪澜，环回自天，非众川也。故自黄帝八代而生舜，武王克殷，求有妫之允满封于陈，是为胡公。十三叶生完，自以公子，国难不得立，乃抱乐器奔齐，桓公以卿礼接之。下又十一叶和，以久为政，阴浃于人，遂有齐国，三代称王。至建为秦所灭。项羽入秦，封建孙安为济北王。汉兴失国，齐人谓之王家，因以为氏。安子涓，仕汉，为镇东将军、青州牧，封剧县伯。自涓至彤，凡一十九代，两汉公卿牧守如家牒然。十代祖猛，字景略，符秦尚书令，伉秦成霸业，与孔明佐蜀同功，故时人谓之王葛，史云北海剧人，遂著为族望。九代祖休，仪曹尚书。八代祖镇恶，佐命宋，长安擒姚宏。至北齐五代祖斤，七兵尚书，兄弟九人，时号王氏九龙，于齐史有传。高祖，字君粹，北齐著作郎、燕郡太守。曾祖敬忠，成州刺史。大父上客，高宗封岳，进士及第，历侍御史主客兵部员外郎，累迁兵右金吾卫将军冀州刺史灵州都督朔方道总管。见《职官仪》及衣（阙）。
烈考瞰，宣州宣城县令，赠工部郎中。娶河东裴氏，乃生仆射。季睦馀力，工为文。始以崇文生应深谋秘策，考入上第，拜监察御史。天之赋予，莫能两大，既扬令名，而不以景福，享龄五十五。葬于河南府偃师县亳邑乡。后以子贵，累赠礼部尚书至右仆射。夫人江夏李氏祔焉。李门多奇才：父暄，起居舍人；暄子鄘，门下侍郎平章事；高叔祖善，兰台郎崇文馆学士，注《文选》行于时；善子邕，北海郡太守，有重名，四方之士求为碑志者倾天下。故夫人于盛宗礼范可法，累赠至江夏郡夫人。
仆射有三子。长子早终。次子处元，少婴沈恙，慕道士养生之术，高尚其趣，强仕而没，积善不试，后来果大焉。季子彦威，字子美，始以五经登甲科，历太常博士祠部员外郎，迁屯田郎中，转户部司封，并充礼仪使判官、宏文馆学士、京兆少尹、谏议大夫、史馆修撰。以直谏出为河南少尹，入为少府监司农卿，改淄青节度使，征拜户部侍郎判度支。势逼生患，出为卫尉，分司东都。寻起为陈许节度使检校礼部尚书，充汴、宋、亳等州节度观察处置等使，北海县开国子，食邑五百户。娶颍川韩氏，主客员外郎衢之女，国子祭酒杨顼之外孙。夫人有三弟，皆材，无子，早谢，已如礼祔葬于亳邑原。仆射厚德覆露之，尚书丕承之，以蚤孤，锐意向学。尝阅《诗》至《蓼莪》篇，感激流涕，故其志如刃始淬。及学成，立遂为鸿儒，入用为能臣。参定仪制，财成经费。起书生，拥旌节。今又领全师镇上游，握神符，垂三组，皆向时感发之所激也。志就而学成，名闻而身达。欲报无所，外荣中悲。人子之孝，在乎扬其先德以耀于远，乃俾学古者书本系所自，且铭于龟趺螭首云。铭曰：
山积而高，泽积而长。圣人之后，必大而昌。由圣与贤，或为霸强。建不克嗣，济北疏疆。齐人德之，其族称王。佐于符秦，北海重光。仆射之生，负材而起。策于万乘，擢为御史。同时条对，千目仰视。桂林一枝，拾芥相似。名动海内，夫岂不伟。种德而牙，乃生令子。出入鼎贵，理财统师。流根之泽，密印累累。峻其追崇，幽显有辉。孝嗣之志，歉然弗怡。春露秋霜，感伤履之。时久能慕，禄丰益悲。明发不寐，永怀孝思。摅之无穷，曷若丰碑。景亳之原，佳城在斯。乃金石刻，揭于道陲。松耶柏耶，有洛之湄。过者必下，来观信辞。', '《唐故监察御史赠尚书右仆射王公神道碑》是唐代刘禹锡创作的一篇散文。', '', '', NULL, '', 'indent', 1545384987, '5c1c43b0808ca400733331bc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640805, '淮南子.泰族训', NULL, 28, 27, 1, 1, '刘安', NULL, 18114, '5858ec6a8d6d810065c34715', '汉', 'wen', '文', '', '', '故不言而信，不施而仁，不怒而威，是以天心动化者也。施而仁，言而信，怒而威，是以精诚感之者也。施而不仁，言而不信，怒而不威，是以外貌为之者也。故有道以统之，法虽少，足以化矣;无道以行之，法虽众，足以乱矣。', '', '', '', NULL, '', 'indent', 1545385320, '5c1c4446808ca4565c82ddde', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640806, '盐铁论-忧边第十二', NULL, 13, 2, 1, 1, '桓宽', NULL, 36984, '5c1c44b167f356005fd3aef2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E7%9B%90%E9%93%81%E8%AE%BA/610183?fr=aladdin', '', '大夫曰：“文学言：‘天下不平，庶国不宁，明王之忧也。’故王者之于天下，犹一室之中也，有一人不得其所，则谓之不乐。故民流溺而弗救，非惠君也。国家有难而不忧，非忠臣也。夫守节死难者，人臣之职也；衣食饥寒者，慈父之道也。今子弟远劳于外，人主为之夙夜不宁，群臣尽力毕议，册滋国用。故少府丞令请建酒榷，以赡边，给战士，拯民于难也。为人父兄者，岂可以已乎！内省衣食以恤在外者，犹未足，今又欲罢诸用，减奉边之费，未可为慈父贤兄也。”
文学曰：“周之季末，天子微弱，诸侯力政，故国君不安，谋臣奔驰。何者？敌国众而社稷危也。今九州同域，天下一统，陛下优游岩廊，览群臣极言至论，内咏雅、颂，外鸣和銮，纯德粲然，并于唐、虞，功烈流于子孙。夫蛮、貊之人，不食之地，何足以烦虑，而有战国之忧哉？若陛下不弃，加之以德，施之以惠，北夷必内向，款塞自至，然后以为胡制于外臣，即匈奴没齿不食其所用矣。”
大夫曰：“圣主思中国之未宁，北边之未安，使故廷尉评等问人间所疾苦。拯恤贫贱，周赡不足。群臣所宣明王之德，安宇内者，未得其纪，故问诸生。诸生议不干天则入渊，乃欲以闾里之治，而况国家之大事，亦不几矣！发于畎亩，出于穷巷，不知冰水之寒，若醉而新寤，殊不足与言也。”
文学曰：“夫欲安民富国之道，在于反本，本立而道生。顺天之理，因地之利，即不劳而功成。夫不修其源而事其流，无本以统之，虽竭精神，尽思虑，无益于治。欲安之适足以危之，欲救之适足以败之。夫治乱之端，在于本末而已，不至劳其心而道可得也。孔子曰：‘不通于论者难于言治，道不同者，不相与谋。’今公卿意有所倚，故文学之言，不可用也。”
大夫曰：“吾闻为人臣者尽忠以顺职，为人子者致孝以承业。君有非，则臣覆盖之。父有非，则子匿逃之。故君薨，臣不变君之政，父没，则子不改父之道也。春秋讥毁泉台，为其隳先祖之所为，而扬君父之恶也。今盐、铁、均输，所从来久矣，而欲罢之，得无害先帝之功，而妨圣主之德乎？有司倚于忠孝之路，是道殊而不同于文学之谋也。”
文学曰：“明者因时而变，知者随世而制。孔子曰：‘麻冕，礼也，今也纯，俭，吾从众。’故圣人上贤不离古，顺俗而不偏宜。鲁定公序昭穆，顺祖祢，昭公废卿士，以省事节用，不可谓变祖之所为，而改父之道也？二世充大阿房以崇绪，赵高增累秦法以广威，而未可谓忠臣孝子也。”', '《盐铁论》是西汉的桓宽根据著名的“盐铁会议”记录整理撰写的重要史书，书中记述了当时对汉武帝时期的政治、经济、军事、外交、文化的一场大辩论。', '', '', NULL, '', 'indent', 1545385329, '5c1c45039f545400706b7e27', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642125, '幽梦影 · 卷一 · 九十四', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '藏书不难，能看为难；看书不难，能读为难；读书不难，能用为难；能用不难，能记为难。', '', '', '', NULL, '', 'indent', 1556102184, '5cbfcba50237d70068c0884e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640809, '禁止馈送檄', NULL, 42, 4, 1, 1, '张伯行', NULL, 23414, '5858f143570c35006917f917', '清', 'wen', '文', 'https://baike.baidu.com/item/%E7%A6%81%E6%AD%A2%E9%A6%88%E9%80%81%E6%AA%84/9497720', '', '一丝一粒，我之名节；一厘一毫，民之脂膏。宽一分，民受赐不止一分；取一文，我为人不值一文。谁云交际之常，廉耻实伤；倘非不义之财，此物何来？', '（清）张伯行《禁止馈送檄》', '', '一丝一粒”虽小，却牵涉我的名节；“一厘一毫”虽微，却都是民脂民膏。对百姓宽待一分，那么百姓所受的恩赐就不止一分；向百姓多索取一文，那么我的为人便一文不值。虽说交际是人之常情，来路不干净也伤廉耻。因为如果不是不义之财，这些礼物又是从哪里来的？所以禁止馈送。', NULL, '', 'indent', 1545385813, '5c1c46ec9f545400706b9462', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640810, '商君书 · 算地', NULL, 2, 2, 0, 1, '商鞅', NULL, 36985, '5c1c461a7f6fd3005d00d510', '秦', 'wen', '文', '', '', '凡世主之患，用兵者不量力，治草莱者不度地。故有地狭而民众者，民胜其地；地广而民少者，地胜其民。民胜其地，务开；地胜其民者，事徕。
开，则行倍。民过地，则国功寡而兵力少；地过民，则山泽财物不为用。夫弃天物、遂民淫者，世主之务过也，而上下事之，故民众而兵弱，地大而力小。
故为国任地者：山林居什一，薮泽居什一，薮谷流水居什一，都邑蹊道居什四，此先王之正律也。故为国分田数：小亩五百，足待一役，此地不任也；方土百里，出战卒万人者，数小也。此其垦田足以食其民，都邑遂路足以处其民，山林、薮泽、溪谷足以供其利，薮泽堤防足以畜。故兵出，粮给而财有余；兵休，民作而畜长足。此所谓任地待役之律也。
今世主有地方数千里，食不足以待役实仓，而兵为邻敌，臣故为世主患之。夫地大而不垦者，与无地同；民众而不用者，与无民同。故为国之数，务在垦草；用兵之道，务在壹赏。私利塞于外，则民务属于农；属于农，则朴；朴，则畏令。私赏禁于下，则民力抟于敌；抟于敌，则胜。奚以知其然也？夫民之情，朴则生劳而易力，穷则生知而权利。易力则轻死而乐用，权利则畏罚而易苦。易苦则地力尽，乐用则兵力尽。夫治国者，能尽地力而致民死者，名与利交至。
民之性：饥而求食，劳而求佚，苦则索乐，辱则求荣，此民之情也。民之求利，失礼之法；求名，失性之常。奚以论其然也？今夫盗贼上犯君上之所禁，而下失臣民之礼，故名辱而身危，犹不止者，利也。其上世之士，衣不暖肤，食不满肠，苦其志意，劳其四肢，伤其五脏，而益裕广耳，非性之常也，而为之者，名也。故曰：名利之所凑，则民道之。
主操名利之柄而能致功名者，数也。圣人审权以操柄，审数以使民。数者，臣主之术，而国之要也。故万乘失数而不危、臣主失术而不乱者，未之有也。今世主欲辟地治民而不审数，臣欲尽其事而不立术，故国有不服之民，主有不令之臣。故圣人之为国也，入令民以属农，出令民以计战。夫农，民之所苦；而战，民之所危也。犯其所苦、行其所危者，计也。故民生则计利，死则虑名。名利之所出，不可不审也。利出于地，则民尽力；名出于战，则民致死。入使民尽力，则草不荒；出使民致死，则胜敌。胜故而草不荒，富强之功可坐而致也。
今则不然。世主之所以加务者，皆非国之急也。身有尧、舜之行，而功不及汤、武之略者，此执柄之罪也。臣请语其过。夫治国舍势而任说说，则身剽而功寡。故事《诗》、《书》谈说之士，则民游而轻其君；事处士，则民远而非其上；事勇士，则民竞而轻其禁；技艺之士用，则民剽而易徙；商贾之士佚且利，则民缘而议其上。故五民加于国用，则田荒而兵弱。谈说之士资在于口，处士资在于意勇士资在于气，技艺之士资在于手，商贾之士资在于身。故天下一宅，而圜身资。民资重于身，而偏托势于外。挟重资，归偏家，尧、舜之所难也。故汤、武禁之，则功立而名成。圣人非能以世之所易胜其所难也，必以其所难胜其所易。故民愚，则知可以胜之；世知，则力可以胜之。臣愚，则易力而难巧；世巧，则易知而难力。故神农教耕而王天下，师其知也；汤、武致强而征诸侯，服其力也。今世巧而民淫，方效汤、武之时，而行神农之事，以随世禁。故千乘惑乱，此其所加务者过也。
民之生：度而取长，称而取重，权而索利。明君慎观三者，则国治可立，而民能可得。国之所以求民者少，而民之所以避求者多，入使民属于农，出使民壹于战，故圣人之治也，多禁以止能，任力以穷诈。两者偏用，则境内之民壹；民壹，则农；农，则朴；朴，则安居而恶出。故圣人之为国也，民资藏于地，而偏托危于外。资藏于地则朴，托危于外则惑。民入则朴，出则惑，故其农勉而战戢也。民之农勉则资重，战戢则邻危。资重则不可负而逃，邻危则不归。于无资、归危外托，狂夫之所不为也。故圣人之为国也，观俗立法则治，察国事本则宜。不观时俗，不察国本，则其法立而民乱，事剧而功寡。此臣之所谓过也。
夫刑者，所以禁邪也；而赏者，所以助禁也。羞辱劳苦者，民之所恶也；显荣佚乐者，民之所务也。故其国刑不可恶而爵禄不足务也，此亡国之兆也。
刑人复漏，则小人辟淫而不苦刑，则徼幸于民、上；徼于民、上以利。求显荣之门不一，则君子事势以成名。小人不避其禁，故刑烦。君子不设其令，则罚行。刑烦而罚行者，国多奸，则富者不能守其财，而贫者不能事其业，田荒而国贫。田荒，则民诈生；国贫，则上匮赏。故圣人之为治也，刑人无国位，戮人无官任。刑人有列，则君子下其位；衣锦食肉，则小人冀其利。
君子下其位，则羞功；小人冀其利，则伐奸。故刑戮者，所以止奸也；而官爵者，所以劝功也。今国立爵而民羞之，设刑而民乐之，此盖法术之患也。
故君子操权一正以立术，立官贵爵以称之，论荣举功以任之，则是上下之称平。上下之称平，则臣得尽其力，而主得专其柄。', '', '', '', NULL, '', 'indent', 1576314094, '5c1c471767f356005fd3ca92', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640812, '申鉴·政体第一', NULL, 4, 3, 1, 0, '荀悦', NULL, 36978, '5c1a7693303f39005f23dcde', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E7%94%B3%E9%89%B4/2857129?fr=aladdin#3', '申鉴五卷．汉荀悦着．悦仕献帝朝．辟曹操府．与孔融及弟彧同侍讲禁中．悦每有献替而意有未尽．此申鉴所为作者．盖有志于经世也．然当时政体．顾有大于总揽机务．使权不下移者乎．而曾无一言及之．何哉．厥后融以论建渐广．彧以不阿九锡．皆不得其死悦独优游以寿终．其亦善处浊世者矣．其论政体．无贾谊之经制而近于醇．无刘向之愤激而长于讽．其杂言等篇．颇似扬雄法言．雄曲意美新．而悦无一言及于操．视雄为优矣．或言悦书似徐干王符．考其归．兹若人之俦乎．吾未知所先后也．而三品之说．昌黎公有取焉．其书世亦罕传．吾苏黄勉之好蓄异书．又为之训释．搜讨磔裂．出入五经．三史．春秋内外传．老．庄．淮南．素．难．天官．地志．博洽精密．多得悦旨．虽然．悦之书．其有所感而为乎．勉之之注．岂亦有感而为乎．勉之春秋方富．行将抒其学．出而效用．当炳焉赫焉．流声实于天朝．尚．何悦之慕哉．正德十四年岁在己卯冬十月既望吴郡王鏊撰．
申鉴汉颍川荀悦着南丰吴道传校', '夫道之本．仁义而已矣．五典以经之．群籍以纬之．咏之歌之．弦之舞之．前鉴既明．后复申之．故古之圣王．其于仁义也．申重而已．笃序无强．谓之申鉴．圣汉统天．惟宗时亮．其功格宇宙．粤有虎臣乱政．虎臣汉兴辅弼之臣乱治也时亦惟荒圯湮．治荒曰荒兹洪轨仪．鉴于三代之典．王允迪厥德．迪蹈也功业有尚．天道在尔．惟帝茂止．陟降肤止．万国康止．允出兹．斯行远矣．立天之道．曰阴与阳．立地之道．曰柔与刚．立人之道．曰仁与义．阴阳以统其精气．刚柔以品其群形．仁义以经其事业．是为道也．故凡政之大经．法教而已矣．教者．阳之化也．法者．阴之符也．仁也者．慈此者也．义也者．宜此者也．礼也者．履此者也．信也者．守此者也．智也者．知此者也．是故好恶以章之．喜怒以莅之．哀乐以恤之．若乃二端不愆．二端者教与法也五德不离．五德者仁义礼智信也六节不悖．六节者好恶喜怒哀乐也则三才允序．五事交备．百工惟厘．庶绩咸熙．天作道．皇作极．臣作辅．民作基．惟先哲王之政．一曰承天．二曰正身．三曰任贤．四曰恤民．五曰明制．六曰立业．承天惟允．正身惟常．任贤惟固．恤民惟勤．明制惟典．立业惟敦．是谓政体也．致治之术．先屏四患．乃崇五政．一曰伪．二曰私．三曰放．四曰奢．伪乱俗．私坏法．放越轨．奢败制．四者不除．则政末由行矣．俗乱则道荒．虽天地不得保其性矣．法坏则世倾．虽人主不得守其度矣．轨越则礼亡．虽圣人不得全其道矣．制败则欲肆．虽四表不能充其求矣．是谓四患．兴农桑以养其生．审好恶以正其俗．宣文教以章其化．立武备以秉其威．明赏罚以统其法．是谓五政．民不畏死．不可惧以罪．民不乐生．不可观按汉书作劝字以善．虽使■布五教．咎繇作士．政不行焉．故在上者．先丰民财以定其志．帝耕籍田．后桑蚕宫．国无游民．野无荒业．财不虚用．力不妄加．以周民事．是谓养生．此政之当崇者一也君子所以动天地应神明正万物．而成王治者．必本乎真实而已．故在上者审则仪道以定好恶．善恶要于功罪．毁誉效于准验．听言责事．举名察实．无或诈伪以荡众心．故事无不核．物无不切．善无不显．恶无不彰．俗无奸怪．民无淫风．百姓上下睹利害之存乎己也．故肃恭其心．慎修其行．内不忒惑．外无异望．虑其睹去徼幸．无罪过不忧惧．请谒无所听．财赂无所用．则民志平矣．是谓正俗．此政之当崇者二也君子以情用．小人以刑用．荣辱者．赏罚之精华也．故礼教荣辱以加君子．化其情也．桎梏鞭朴以加小人．治其刑也．君子不犯辱．况于刑乎．小人不忌刑．况于辱乎．若夫中人之伦．则刑礼兼焉．教化之废．推中人而坠于小人之域．教化之行．引中人而纳于君子之途．是谓章化．此政之当崇者三也小人之情．缓则骄．骄则恣．恣则急．急则怨．怨则畔．危则谋乱．安则思欲．非威强无以惩之．故在上者．必有武备．以戒不虞．以遏寇虐．安居则寄之内政．有事则用之军旅．是谓秉威．此政之当崇者四也赏罚．政之柄也．明赏必罚．审信慎令．赏以劝善．罚以惩恶．人主不妄赏．非徒爱其才也．赏妄行则善不劝矣．不妄罚．非徒慎其刑也．罚妄行则恶不惩矣．赏不劝．谓之止善．赏及淫人则善无所劝而为善者止矣罚不惩．谓之纵恶．罚及善人则恶无所惩而为恶者纵矣在上者能不止下为善．不纵下为恶．则治国矣．是谓统法．此政之当崇者五也四患既蠲．五政既立．行之以诚．守之以固．简而不怠．疏而不失．无为为之．使自施之．无事事之．使自交之．不肃而治．垂拱揖逊而海内平矣．是谓为政之方也．惟修六则以立道经．一曰中．二曰和．三曰正．四曰公．五曰诚．六曰通．以天道作中．以地道作和．以仁德作正．以事物作公．以身极作诚．以变量作通．易传曰通其变又曰变则通是谓道实．惟恤十难以任贤能．一曰不知．二曰不进．三曰不任．四曰不终．五曰以小怨弃大德．六曰以小过黜大功．七曰以小失掩大美．八曰以讦奸伤忠正．九曰以邪说乱正度．十曰以谗嫉废贤能．是谓十难．十难不除．则贤臣不用．用臣不贤．则国非其国也．
惟察九风以定国常．一曰治．二曰衰．三曰弱．四曰乖．五曰乱．六曰荒．七曰叛．八曰危．九曰亡．君臣亲而有礼．百僚和而不同．让而不争．勤而不怨．无事惟职是司．此治国之风也．礼俗不一．位职不重．小臣谗嫉．庶人作议．此衰国之风也．君好让．臣好逸．士好游．民好流．此弱国之风也．君臣争明．朝廷争功．士大夫争名．庶人争利．此乖国之风也．上多欲．下多端．法不定．政多门．此乱国之风也．以侈为博．以伉为高．以滥为通．遵礼谓之劬．守法谓之固．此荒国之风也．以苛为密．以利为公．以割下为能．以附上为忠．此叛国之风也．上下相疏．内外相蒙．小臣争宠．大臣争权．此危国之风也．上不访．下不谏．妇言用．私政行．此亡国之风也．故上必察乎国风也．
惟慎庶狱以昭人情．天地之大德曰生．易系辞文万物之大极曰死．洪范六极一曰凶短折死者不可以生．刑者不可以复．故先王之刑也．官师以成之．棘槐以断之．周礼朝士掌建邦外朝之法左九棘孤卿大夫位焉群士在其后右九棘公侯伯子男位焉又王制曰成狱辞史以狱成告于大司寇大司寇听之击木之下情讯以宽之．朝市以共之．矜哀以恤之．刑斯断．乐不举．施刑之日则弛悬慎之至也．刑哉刑哉．其慎矣夫．惟稽五赦以绥民中．一曰原心．心可矜也二曰明德．德可释也三曰劝功．功可准也四曰褒化．化所关也五曰权计．权时之宜非常典也凡先王之攸赦．必是族也．非是族焉．刑兹无赦．族类也天子有四时．朝以听政．昼以访问．夕以修令．夜以安身．上有师傅．下有燕臣．大则讲业．小则咨询．不拒直辞．不耻下问．公私不愆．外内不贰．是谓有交．问明于治者其统近．万物之本在身．天下之本在家．治乱之本在左右．内正立而四表定矣．
问通于道者其守约．有一言而可常行者．恕也．有一行而可常履者．正也．恕者．仁之术也．正者．义之要也．至哉．此谓道根．万化存焉尔．是谓不思而得．不为而成．执之胸心之间．而功覆天下也．自天子达于庶人．好恶哀乐．其修一也．丰约劳佚．各有其制．上足以备礼．下足以备乐．夫是谓大道．天下国家一体也．君为元首．臣为股肱．民为手足．下有忧民．则上不尽乐．下有饥民．则上不备膳．下有寒民．则上不具服．徒跣而垂旒．非礼也．故足寒伤心．民寒伤国．
问君以至美之道道民．民以至美之物养君．君降其惠．民升其功．此无往不复．相报之义也．故太平备物．非极欲也．物损礼阙．非谦约也．其数云耳．问人主有公赋无私求．有公用无私费．有公役无私使．有公赐无私惠．有公怒无私怨．私求则下烦而无度．是谓伤清．私费则官耗而无限．是谓伤制．私使则民挠扰而无节．是谓伤义．私惠则下虚望而无准．是谓伤正．正谓赐予之正私怨则下疑惧而不安．是谓伤德．问善治民者．治其性也．或曰．冶金而流．去火则刚．激水而升．舍之则降．恶平声乎治．曰．不去其火则常流．激而不止则常升．故大冶之炉．可使无刚．则踊水之机．可使无降．善立教者若兹．则终身治矣．故凡器可使与颜冉同趋．投百金于前．白刃加其身．虽巨跖弗敢掇也．善立法者若兹．则终身不掇矣．故跖可使与伯夷同功．
问民由水也．济大川者．太上乘舟．其次泅．泅浮行水上也泅者劳而危．乘舟者逸而安．虚入水则必溺矣．以知能治民者．泅也．以道德治民者．舟也．纵民之情谓之乱．绝民之情谓之荒．曰．然则如之何．曰．为之限．使弗越也．为之地亦勿越．故水可使不滥．不可使无流．善禁者．先禁其身而后人．不善禁者．先禁人而后身．善禁之至于不禁．令亦如之．若乃肆情于身而绳欲于众．行诈于官而矜实于民．求己之所有余．夺下之所不足．舍己之所易．责人之所难．怨之本也．谓理之源斯绝矣．自上御下．犹夫钓者焉．隐于手．按手下当有而字应于钩．则可以得鱼．自近御远．犹夫御马焉．和于手而调于衔．则可以使马．故至道之要．不于身非道也．睹孺子之驱鸡也而见御民之方．孺子驱鸡者．急则惊．缓则滞．方其北也．遽要之则折而过南．方其南也．遽要之则折而过北．迫则飞．疏则放．志闲则比之．比近也？鸡志闲然后近之则不惊流缓而不安则食之．食之则不滞不驱之驱．驱之至者也．志安则循路而入门．太上不空市．其次不偷窃．其次不掠夺．上以功惠绥民．下以财力奉．是以上下相与．空市则民不与．民不与则为巧诈而取之．谓之偷窃．偷窃则民备之．备之而不得．则暴迫而取之．谓之掠夺．民必交争．则祸乱矣．或曰．圣王以天下为乐．曰．否．圣王以天下为忧．天下以圣王为乐．凡主以天下为乐．天下以凡主为忧．圣王屈己以申天下之乐．凡主伸己以屈天下之忧．申天下之乐．故乐亦报之．屈天下之忧．故忧亦及之．天下之道也．治世所贵乎位者三．一曰达道于天下．二曰达惠于民．三曰达德于身．衰世所贵乎位者三．一曰以贵高人．二曰以富奉身．三曰以报肆心．治世之位．真位也．衰世之位．则生灾矣．苟高人．则必损之．灾也．苟奉身．则必遗之．灾也．苟肆心．则必否之．灾也．
治世之臣．所贵乎顺者三．一曰心顺．二曰职顺．三曰道顺．治世之顺．真顺也．衰世之顺．生逆也．体苟顺则逆节．乱苟顺则逆忠事苟顺则逆道．高下失序则位轻．班级不固则位轻．汉爵有二十级禄薄卑宠则位轻．官职屡改则位轻．迁转烦渎则位轻．黜陟不明则位轻．待臣不以礼则位轻．夫位轻而政重者．未之有也．圣人之大宝曰位．轻则丧吾宝也．
好恶之不行．其俗尚矣．嘉守节而轻狭陋．疾威福而尊权右．贱求欲而崇克济．贵求己而荣华誉．万物类是已．夫心与言．言与事．参相应也．好恶毁誉赏罚．参相福也．六者有失．则实乱矣．守实者益荣．求己者益达．处幽者益明．然后民知本也．', '', '', '', NULL, '', 'indent', 1545386142, '5c1c4827fb4ffe005f194f92', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640813, '公生明廉生威', NULL, 33, 1, 1, 1, '年富', NULL, 36986, '5c1c48b0fb4ffe005f19578c', '明', 'wen', '文', 'https://baike.baidu.com/item/%E5%85%AC%E7%94%9F%E6%98%8E%E5%BB%89%E7%94%9F%E5%A8%81/5295991?fr=aladdin', '', '吏不畏吾严而畏吾廉，民不服吾能而服吾公。廉则吏不敢慢，公则民不敢欺。公生明，廉生威。', '“公生明廉生威”，据王克煜等学者考证这是一则明清官吏引以自戒的座右铭，出自明朝山东巡抚年富之手。最先立此言为碑的明代泰安知州顾景祥一生为官清正廉明。后山东巡抚年富用楷体书《官箴》刻石，作为自己为官清正廉明，刚直不阿的座右铭。朱镕基同志曾在多次讲话中引用这段名言。', '“公生明 廉生威”，王克煜考证这是一则明清官吏引以自戒的座右铭，出自明朝山东巡抚年富之手。
“吏，不畏吾严而畏吾廉；民，不服吾能而服吾公。廉则吏不敢慢，公则民不敢欺。公生明，廉生威。”这块谓之《官箴》的刻石，是明代山东巡抚年富所撰，体为楷书，庄重而平稳，横、竖、撇、捺、点落笔和用笔显得峻峭、浑实、锐利、酣畅，可谓笔笔精到，字字珠玑。据考证，这块最先是由泰安知州顾景祥于明孝宗朱祐樘弘治十四年（公元1 5 0 1 年）八月刻立于泰安府衙的。', '官吏不怕我严厉，而害怕我廉洁。百姓不服我的才能，而服我的公正。为政清廉，官吏就不敢有所怠慢；办事公正，百姓就不敢有所欺瞒。为官公正，才能使政治清明；为官清廉，才能在百姓中树立威信。', NULL, '', 'indent', 1545386343, '5c1c4907808ca40073337199', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640814, '抱朴子', NULL, 16, 3, 1, 1, '葛洪', NULL, 36987, '5c1c4a40fb4ffe005f19698b', '晋', 'wen', '文', '', '', '至于飞走之属，蠕动之类，禀形造化，既有定矣。及其倏忽而易旧体，改更而为异物者，千端万品，不可胜论。人之为物，贵性最灵，而男女易形，为鹤为石，为虎为猿，为沙为鼋，又不少焉。至于高山为渊，深谷为陵，此亦大物之变化。变化者，乃天地之自然，何为嫌金银之不可以异物作乎？', '', '', '', NULL, '', 'indent', 1545386808, '5c1c4aa7fb4ffe005f196df8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640815, '格言联璧·持躬类', NULL, 14, 1, 1, 1, '金缨', NULL, 36988, '5c1c4bd71579a3005fce1661', '清', 'wen', '文', '', '', '俭则约，约则百善俱兴；侈则肆，肆则百恶俱纵。', '', '', '勤俭了就有了约束，有约束了就会各种好事都做；奢侈就放肆，放肆则各种坏事都泛滥。', NULL, '', 'indent', 1545387092, '5c1c4bf7fb4ffe005f197c9e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640817, '新唐书·列传第三十·褚遂良', NULL, 6, 1229, 1, 1, '欧阳修', NULL, 10018, '57b98d625bbb50005347ace1', '宋', 'wen', '文', '', '', '褚遂良，字登善，通直散骑常侍亮子。隋大业末，为薛举通事舍人。仁杲平，授秦王府铠曹参军。贞观中，累迁起居郎。博涉文史，工隶楷。太宗尝叹曰“虞世南死，无与论书者”魏征白见遂良，帝令侍书。帝方博购王羲之故帖，天下争献，然莫能质真伪。遂良独论所出，无舛冒者。
　　十五年，帝将有事太山，至洛阳，星孛太微，犯郎位。遂良谏曰“陛下拨乱反正，功超古初，方告成岱宗，而彗辄见，此天意有所未合。昔汉武帝行岱礼，优柔者数年，臣愚愿加详虑”帝寤，诏罢封禅。
　　迁谏议大夫，兼知起居事。帝曰“卿记起居，大抵人君得观之否”对曰“今之起居，古左右史也，善恶必记，戒人主不为非法，未闻天子自观史也”帝曰“朕有不善，卿必记邪”对曰“守道不如守官，臣职载笔，君举必书”刘洎曰“使遂良不记，天下之人亦记之矣”帝曰“朕行有三：一，监前代成败，以为元龟，二，进善人，共成政道。三，斥远群小，有受谗言。朕能守而勿失，亦欲史氏不能书吾恶也”
　　是时，魏王泰礼秩如嫡，群臣未敢谏。帝从容访左右曰“方今何事尤急”岑文本泛言礼义为急，帝以不切，未领可。遂良曰“今四方仰德，谁弗率者。唯太子、诸王宜有定分”帝曰“有是哉。朕年五十，日以衰怠，虽长子守器，而弟、支子尚五十人，心常念焉。自古宗姓无良，则倾败相仍，公等为我柬贤者保傅之。夫事人久，情媚熟，则非意自生，其令王府官不得过四考，著为令”帝尝怪“舜造漆器，禹雕其俎，谏者十馀不止，小物何必尔邪”遂良曰“雕琢害力农，纂绣伤女工，奢靡之始，危亡之渐也。漆器不止，必金为之，金又不止，必玉为之，故谏者救其源，不使得开。及夫横流，则无复事矣”帝咨美之。
　　于时皇子虽幼，皆外任都督、刺史，遂良谏曰“昔二汉以郡国参治，杂用周制。今州县率仿秦法，而皇子孺年并任刺史，陛下诚以至亲扞四方。虽然，刺史，民之师帅也，得人则下安措，失人则家劳τ。故汉宣帝曰：与我共治，惟良二千石乎。臣谓皇子未冠者，可且留京师，教以经学，畏仰天威，不敢犯禁，养成德器，审堪临州，然后敦遣。昔东汉明、章诸帝，友爱子弟，虽各有国，幼者率留京师，训饬以礼。讫其世，诸王数十百，惟二人以恶败，自余餐和染教，皆为善良。此前事已验，惟陛下省察”帝嘉纳。
　　太子承乾废，魏王泰间侍，帝许立为嗣，因谓大臣曰“泰昨自投我怀中云：臣今日始得为陛下子，更生之日也。臣惟有一子，百年后，当杀之，传国晋王。朕甚怜之”遂良曰“陛下失言。安有为天下主而杀其爱子，授国晋王乎。陛下昔以承乾为嗣，复宠爱泰，嫡庶不明，纷纷至今。若必立泰，非别置晋王不可”帝泣曰“我不能”即诏长孙无忌、房玄龄、李勣与遂良等定策立晋王为皇太子。
　　时飞雉数集宫中，帝问“是何祥也”遂良曰“昔秦文公时，有侲子化为雉，雌鸣陈仓，雄鸣南阳。侲子曰：得雄者王，得雌者霸。文公遂雄诸侯，始为宝鸡祠。汉光武得其雄，起南阳，有四海。陛下本封秦，故雄雌并见，以告明德”帝悦，曰“人之立身，不可以无学。遂良所谓多识君子哉”俄授太子宾客。
　　薛延陀请婚，帝己纳其聘，复绝之。遂良曰“信为万事本，百姓所归。故文王许枯骨而不违，仲尼去食存信，贵之也。延陀，曩一俟斤耳。因天兵北讨，荡平沙塞，威加诸外，而恩结于内，以为余寇不可以无酋长，故玺书鼓纛，立为可汗。负抱之恩，与天无极。数遣使请婚于朝，陛下既开许，为御北门受献食。今一朝自为进退，所惜少，所失多，亏信夷狄，方生嫌恨，殆不可以训戎兵、励军事也。且龙沙以北，部落牛毛，中国击之不能尽，亦犹可北败，芮芮兴，突厥亡，延陀盛。是以古人虚外实内，怀之以德。使为恶，在夷不在华。失信，在彼不在此也。惟陛下裁幸”不纳。
　　帝欲自讨辽东，遂良固劝无行“一不胜，师必再兴。再兴，为忿兵。兵忿者，胜负不可必”帝然可。会李勣诋其计，帝意遂决东。遂良惧，上言“臣请譬诸身。两京，腹心也。四境，手足也。殊裔绝域，殆非支体所属。高丽王陛下所立，莫离支杀之。讨其逆，夷其地，固不可失，但遣一二慎将，付锐兵十万，翔旝云輣，唾手可取。昔侯君集、李靖皆庸人尔，犹能撅高昌，缨突厥，陛下止发踪指示，得归功圣明。前日从陛下平天下，虓士爪臣，气力未衰，可驱策，惟陛下所使。臣闻涉辽而左，或水潦，平地淖三尺，带方、玄菟，海壤荒漫，决非万乘六师所宜行”是时，帝锐意荡平，不见省。进黄门侍郎，参综朝政。莫离支遣使贡金，遂良曰“古者讨杀君之罪，不受其赂。鲁纳郜鼎太庙，《春秋》讥之。今莫离支所贡不臣之篚，不容受”诏可，以其使属吏。
　　帝既平高昌，岁调兵千人往屯，遂良诵诤不可，帝志取西域，寘其言不用。西突厥寇西州，帝曰“往魏征、褚遂良劝我立麹文泰子弟，不用其计，乃今悔之”帝于寝宫侧别置院居太子，遂良谏，以为“朋友深交者易怨，父子滞爱者多愆。宜许太子间还东宫，近师傅，专学艺，以广懿德”帝从其言。会父丧免，起复，拜中书令。
　　帝寝疾，召遂良、长孙无忌曰“叹武帝寄霍光，刘备托诸葛亮，朕今委卿矣。太子仁孝，其尽诚辅之”谓太子曰“无忌、遂良在，而毋忧”因命遂良草诏。高宗即位，封河南县公，进郡公。坐事出为同州刺史。再岁，召拜吏部尚书、同中书门下三品，监修国史，兼太子宾客。进拜尚书右仆射。
　　帝将立武昭仪，召长孙无忌、李勣、于志宁及遂良人。或谓无忌当先谏，遂良曰“太尉，国元舅，有不如意，使上有弃亲之讥”又谓勣上所重，当进，曰“不可。司空，国元勋，有不如意，使上有斥功臣之嫌”曰“吾奉遗诏，若不尽愚，无以下见先帝”既入，帝曰“罪莫大于绝嗣，皇后无子，今欲立昭仪，谓何”遂良曰“皇后本名家，奉事先帝。先帝疾，执陛下手语臣曰：我儿与妇今付卿”且德音在陛下耳，可遽忘之。皇后无它过，不可废”帝不悦。翌日，复言，对曰“陛下必欲改立后者，请更择贵姓。昭仪昔事先帝，身接帷第，今立之，奈天下耳目何”帝羞默。遂良因致笏殿阶，叩头流血，曰“还陛下此笏，丐归田里”帝大怒，命引出。武氏从幄后呼曰“何不扑杀此獠”无忌曰“遂良受顾命，有罪不加刑”会李勣议异，武氏立，乃左迁遂良潭州都督。
　　显庆二年，徙桂州，未几，贬爱州刺史。遂良内忧祸，恐死不能自明，乃上表曰“往者承乾废，岑文本、刘洎奏东宫不可少旷，宜遣濮王居之，臣引义固争。明日仗入，先帝留无忌、玄龄、勣及臣定策立陛下。当受遗诏。独臣与无忌二人在，陛下方草土号恸，臣即奏请即位大行柩前。当时陛下手抱臣颈，臣及无忌请即还京，发哀大告，内外宁谧。臣力小任重，动贻伊戚，蝼蚁余齿，乞陛下哀怜”帝昏懦，牵于武后，讫不省。岁馀，卒，年六十三。
　　后二岁，许敬宗、李义府奏长孙无忌逆谋皆遂良驱煽，乃削官爵。二子彦甫、彦冲流爱州，杀之。帝遣诏听其家北还。神龙中，复官爵。德宗追赠太尉。文宗时，诏以遂良五世孙虔为临汝尉。安南观察使高骈表遂良客窆爱州，二男一孙祔。咸通九年，诏访其后护丧归葬阳翟云。
　　遂良曾孙璆，字伯玉，擢进士第，累拜监察御史里行。先天中，突厥围北庭，诏璆持节监总督诸将，破之。迁侍御史，拜礼部员外郎。而气象凝挺，不减在台时', '', '', '', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f7f911759740c9ca2fa", "shortContent": "此文记陈良死而复生事。陈良经商获利，为同邻李焉所觊觎，乃见害。然命不该绝，大概是“生死簿”上时辰未到，以故成为不受阴间统摄的游魂。阴间的官吏查问明白，就把他遣返人世。陈良向官府告发了李焉，报了仇。这不过是一个很一般的还魂故事，同情被害者，希望被冤横死者得以复生，正义得到伸张。此事之奇，奇在陈良在阴间竟遇到早死的好友刘舒，并受刘舒之托，为他生前的家中除去了兴妖作祟的怪物。\n文中刘舒之事的描写使人感到...", "authors": ["刘明今"], "pressName": "上海辞书出版社"}]', '', 'indent', 1545387651, '5c1c4e08808ca4007333ae58', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640818, '与公肃甥书', NULL, 6, 411, 1, 1, '顾炎武', NULL, 26592, '5858f453128fe1006dcc92d9', '清', 'wen', '文', '', '', '所谓大臣者，以道事君，不可则止。吾甥宜三复斯言，不贻讥于后世，则衰朽与有荣施矣。
此中自京兆抵二崤皆得雨，陇西、上郡、平凉皆旱荒，恐为大同之续。与其赈恤于已伤，孰若蠲除于未病。又有异者，身为秦令，而隔河买临晋之小儿，阉为火者，以充僮竖，至割死一人，岂非自陕以西别一世界乎？
诚欲正朝廷以正百官，当以激浊扬清为第一要义，而其本在于养廉。故先以俸禄一议附览，然此今日所必不行，留以俟之可耳。说经之外，所论著大抵如此。世有孟子，或以之劝齐、梁，我则终于韫椟而已。', '顾亭林，明末清初杰出的思想家、学者。他一生不忘复明，屡以死拒清廷聘，坚守民族气节。此信为亭林写给外甥徐元文的。徐元文，字公肃，顺治十六年（西元一六五九年）状元，官至文华殿大学士兼翰林院掌院学士。其母为亭林五妹。
信中，亭林首先引用《论语》中孔子的话「所谓大臣者，以道事君，不可则止」。告诫公肃要「以道事君」，如果统治者不听劝谏，就要辞官而去。他以自己沿途所见以及地方官吏草菅人命的骇人之举，提出：「诚欲正朝廷以正百官，当以激浊扬清为第一要义，而其本在于养廉。」认为要正朝廷必须先正百官，应以激浊扬清为第一要旨，而其根本在于培养并保持廉洁的美德。「激浊扬清」，语本《尸子·君治》：「扬清激浊，荡去滓秽，义也。」激，衝去；浊，脏水；清，清水。衝去污水，让清水上来。喻除恶扬善。
亭林一生提倡「天下兴亡，匹夫有责」，主张「君子为学，以明道也，以救世也」。虽然他与清廷势不两立，终身不仕，但他时刻关注着社稷民生，并对仕清的外甥苦口婆心，悉心劝导。他曾这样勉励公肃：「有体国经野之心，而後可以登山临水；有济世安民之略，而後可以考古论今。」', '', '', NULL, '', 'indent', 1545388093, '5c1c4fcf4773f717363ee960', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640819, '题白云岩书院联', NULL, 21, 1475, 1, 1, '朱熹', NULL, 10015, '57b936ccc4c971005590f2c8', '宋', 'wen', '文', '', '', '地位清高，日月每从肩上过；门庭开豁，江山常在掌中看。', '此联是宋朱晦菴知漳州任时为创白云岩书院所题。联语借用唐宣宗七律《百丈山》之颔联“日月每从肩上过，山河长在掌中看”。上联说儒者肩负社会道义，两袖清风，可昭日月；下联说儒者读万卷、品万物、识时局，身在书斋，心系天下。寥寥数语，把儒者的责任以及应具备的境界和品质说得清楚明白，给人以深刻启迪。', '', '', NULL, '', 'indent', 1545388385, '5c1c51039f545400706c0dda', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642126, '幽梦影 · 卷一 · 九十五', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '求知己于朋友，易；求知己于妻妾，难；求知己于君臣，则尤难之难。', '', '', '', NULL, '', 'indent', 1556102200, '5cbfcbb6a91c930069db46f2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640820, '后汉书·桓荣丁鸿列传第二十七', NULL, 24, 6, 1, 1, '范晔', NULL, 35882, '5858fcde128fe1006dccddd3', '南北朝', 'wen', '文', '', '', ' 夫坏崖破岩之水，源自涓涓；干云蔽日之木，起于葱青。禁微则易，救末者难，人莫不忽于微细，以致其大。恩不忍诲，义不忍割，去事之后，未然之明镜也。', '', ' 据《后汉书·桓荣丁鸿列传》记载，丁鸿是东汉时期的名儒，对经书极为通晓。当时东汉和帝继承皇位，但朝政大权把持在窦太后手中。同时窦太后的哥哥窦宪官居大将军，任用窦家兄弟为文武大臣，独揽国家军政大权。丁鸿对窦太后的专权十分不满，决心为国家除掉这一隐患。几年后，天上发生日食。丁鸿就借此上书皇帝，认为这是个不祥的征兆，指出窦氏的专横跋扈对国家造成的危害，建议迅速改变这种状况。汉和帝于是撤掉窦宪的官职，窦氏兄弟们也被逼自杀。在给和帝的奏疏中，丁鸿还说：“若敕政责躬，杜渐防萌，则凶妖销灭，害除福凑矣。”劝说皇帝整顿国政，在事态萌芽时就加以防止，这样才能使国家长治久安。成语“防微杜渐”即源于此。', ' “禁微则易，救末者难”是东汉太常丁鸿在写给汉和帝奏疏中的话。微：细小，指事物的开端。末：指事物的终结。意思是说，禁止事情于开端时容易，抢救事情于终结时困难。这句话告诫我们，小节易制，大错难救，任何事物都有一个形成、发展、终止的过程，从事情的量变开始阶段就入手矫正，才不会酿成不可救药的质变后果来。

      ', NULL, '', 'indent', 1545388551, '5c1c51a87f6fd3005d015ce3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640822, '魏书·吐谷浑列传', NULL, 7, 18, 1, 1, '魏收', NULL, 36167, '5858fd1e1b69e6006cb1b29c', '南北朝', 'wen', '文', '', '', '阿豺有子二十人，纬代，长子也。阿豺又谓曰：“汝等各奉吾一只箭，折之地下。”俄而命母弟慕利延曰：“汝取一只箭折之。”慕利延折之。又曰：“汝取十九只箭折之。”延不能折。阿豺曰：“汝曹知否？单者易折，众则难摧，戮力一心，然后社稷可固。”言终而死。兄子慕璝立。', '', '', '', NULL, '', 'indent', 1545389585, '5c1c55b47f6fd3005d018c0f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640823, '伪古文尚书 · 商书 · 说命（中）', NULL, 21, 14, 1, 1, '王肃', NULL, 37087, '5e9aab01671c4f00082fea3d', '三国', 'wen', '文', 'https://baike.baidu.com/item/%E8%AF%B4%E5%91%BD/12550658', '', '惟说命总百官，乃进于王曰：“呜呼！明王奉若天道，建邦设都，树后王君公，承以大夫师长，不惟逸豫，惟以乱民。惟天聪明，惟圣时宪，惟臣钦若，惟民从乂。惟口起羞，惟甲胄起戎，惟衣裳在笥，惟干戈省厥躬。王惟戒兹，允兹克明，乃罔不休。惟治乱在庶官。官不及私昵，惟其能；爵罔及恶德，惟其贤。虑善以动，动惟厥时。有其善，丧厥善；矜其能，丧厥功。惟事事，乃其有备，有备无患。无启宠纳侮，无耻过作非。惟厥攸居，政事惟醇。黩予祭祀，时谓弗钦。礼烦则乱，事神则难。”
王曰：“旨哉！说，乃言惟服。乃不良于言，予罔闻于行。”说拜稽首曰：“非知之艰，行之惟艰。王忱不艰，允协于先王成德，惟说不言有厥咎。”', '《伪古文尚书》篇名，共上、中、下三篇。《礼记》作《兑命》，有说“兑”或为“说”之误。', '说：傅说。
总：统率。
奉若：承受，遵从。
建邦：指在天下分别设立国家。
设都：指分别在每个国家设立都城。
树：设立。
后王：指天子。
君公：指诸侯国的国君。
承：通“丞”，辅佐。
大夫师长：指各级官吏。
逸豫：安逸享乐。
乱：治理。
时：通“是”，这。
宪：法。
钦若:恭敬地遵循。
乂：治理。
口：指从口中说出的话。
起：引发。
羞：耻辱。
甲胄：古时士兵的铠甲和头盔。
戎：兵戎，指战祸。
衣裳：指标示官吏等级的服装。
笥（sì）：盛放食品衣物的竹器。
省：明白。
厥：其，此处指武丁。
躬：自身，也指武丁。
兹：此，这。
允：信。
克：能。
罔：无。
休：美好。
庶：众。
私昵：与个人关系亲近的人。
爵：官位爵禄。
恶德：无德之人。
虑善：思虑成熟。
有其善：指自满其善而不思更善。
矜：自夸。
事事：每一件事。
启宠纳侮：孔颖达疏：“无得开小人以宠，自纳此轻侮也。”
耻过：羞于承认错误。
醇：通“纯”，纯正，不杂乱。
黩：轻慢不敬。
时：通“是”。
弗钦：不敬。
旨：美好。
乃：你。
服：实行。
罔：无。
忱：诚信。
允：信。
协：与…相合。
咎：过失。', '傅说接受王命总理百官，于是向王进言说：“啊！古代明王顺从天道，建立邦国，设置都城，树立侯天子、诸侯，又以大夫众长辅佐他们，这不是为了逸乐，而是用来治理人民。上天聪明公正，圣主效法他，臣下敬顺他，人民就顺从治理了。号令轻出会引起羞辱；甲胄轻用会引起战争；衣裳放在箱子里不用来奖励，会损害自己；干戈藏在府库里不用来讨伐，会伤害自身。王应警诫这些！这些真能明白，政治就无不美好了。治和乱在于众官，官职不可授予亲近，当授予那些能者；爵位不可赐给坏人，当赐给那些贤人。考虑妥善而后行动，行动当适合它的时机。夸自己美好，就会失掉其美好；夸自己能干，就会失去其成功。做事情，就要有准备，有准备才没有后患。不要开宠幸的途径而受侮辱；不要以改过为耻而形成大非。这样思考所担任的事，政事就不会杂乱。轻慢对待祭祀，这叫不敬。礼神烦琐就会乱，这样，事奉鬼神就难了。”
王说：“好呀！傅说，你的话应当实行。你如果不善于进言，我就不能勉力去做了。”傅说跪拜叩头，说道：“不是知道它艰难，而是实行它很难。王诚心不以实行为难，就真合于先王的盛德；我傅说如果不说，就有罪过了。”', NULL, '', 'indent', 1545389848, '5c1c56b1fb4ffe005f19fefd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640824, '竹扇赋', NULL, 8, 136, 0, 1, '班固', NULL, 18080, '5830da0e2e958a0069d595a2', '汉', 'fu', '赋', '', '', '青青之竹形兆直，妙华长秆纷实翼。杳筱丛生于水泽，疾风时纷纷萧飒。削为扇翣成器美，托御君王供时有。度量异好有圆方，来风辟暑致清凉。安体定神达消息，百王传之赖功力，寿考康宁累万亿。', '', '', '', NULL, '', 'indent', 1545390033, '5c1c57797f6fd3005d01a682', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640825, '淮南子 · 主术训', NULL, 17, 27, 1, 2, '刘安', NULL, 18114, '5858ec6a8d6d810065c34715', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E6%B7%AE%E5%8D%97%E5%AD%90%C2%B7%E4%B8%BB%E6%9C%AF%E8%AE%AD/5437518?fr=aladdin', '', '人主之术，处无为之事，而行不言之教。清静而不动，一度而不摇，因循而任下，责成而不劳。是故心知规而师傅谕导，口能言而行人称辞，足能行而相者先导，耳能听而执正进谏。是故虑无失策，谋无过事，言为文章，行为仪表于天下。进退应时，动静循理，不为丑美好憎，不为赏罚喜怒，名各自名，类各自类，事犹自然，莫出于己。故古之王者，冕而前旒所以蔽明也，纩塞耳所以掩聪，天子外屏所以自障。故所理者远，则所在者迩；所治者大，则所守者小。
夫目妄视则淫，耳妄听则惑，口妄言则乱。夫三关者，不可不慎守也。若欲规之，乃是离之；若欲饰之，乃是贼之。天气为魂，地气为魄，反之玄房，各处其宅，守而勿失，上通太一。太一之精，通于天道，天道玄默，无容无则，大不可极，深不可测，尚与人化，知不能得。昔者神农之治天下也，神不驰于胸中，智不出于四域，怀其仁诚之心。甘雨时降，五谷蕃植，春生夏长，秋收冬藏。月省时考，岁终献功，以时尝谷，祀于明堂。明堂之制，有盖而无四方，风雨不能袭，寒暑不能伤，迁延而入之，养民以公。其民朴重端悫，不纷争而财足，不劳形而功成。因天地之资而与之和同，是故威厉而不杀，刑错而不用，法省而不烦。故其化如神。其地南至交止，北至幽都，东至谷，西至三危，莫不听从。当此之时，法宽刑缓，囹圄空虚，而天下一俗，莫怀奸心。
末世之政则不然。上好取而无量，下贪狼而无让，民贫苦而仇争，事力劳而无功，智诈萌兴，盗贼滋彰，上下相怨，号令不行。执政有司，不务反道矫拂其本，而事修其末，削薄其德，曾累其刑，而欲以为治，无以异于执弹而来鸟，捭而狎犬也，乱乃逾甚。夫水浊则鱼佥，政苛则民乱。故夫养虎豹犀象者，为之圈槛，供其嗜欲，适其饥饱，违其怒恚。然而不能终其天年者，形有所劫也。是以上多故则下多诈，上多事则下多态，上烦扰则下不定，上多求则下交争。不直之于本，而事之于末，璧犹扬果而弭尘，抱薪以救火也。故圣人事省而易治，求寡而易澹，不施而仁，不言而信，不求而得，不为而成。块然保真，抱德推诚，天下从之，如响之应声，景之像形，其所修者本也。刑罚不足以移风，杀戮不足以禁奸，唯神化为贵。至精为神。
夫疾呼不过闻百步，志之所在，逾于千里。冬日之阳，夏日之阴，万物归之，而莫使之然。故至精之像，弗招而自来，不麾而自住，窈窈冥冥，不知为之者谁，而功自成。智者弗能诵，辩者弗能形。昔孙叔敖恬卧，而郢人无所害其锋；市南宜辽弄丸，而两家之难无所关其辞。鞅合铁铠，目扼？14，其于以御兵刃，县矣；券契束帛，刑罚斧钺，其于以解难，薄矣；待目而照见，待言而使令，其于为治，难矣。蘧伯玉为相，子贡往观之，曰：“何以治国？”曰：“以弗治治之。”简子欲伐卫，使史黯往觌焉，还报曰：“蘧伯玉为相，未可以加兵。”固塞险阻，何足以致之！故皋陶而为大理，天下无虐刑，有贵于言者也；师旷瞽而为太宰，晋无乱政，有贵于见者也。故不言之令，不视之见，此伏牺、神农之所以为师也。
故民之化也，不从其所言而从所行。故齐庄公好勇，不使斗争，而国家多难，其渐至于崔杼之乱。顷襄好色，不使风议，而民多昏乱，其积至昭奇之难。故至精之所动，若春气之生，秋气之杀也，虽驰传鹜置，不若此其亟。故君人者，共犹射者乎！于此豪末，于彼寻常矣。故慎所以感之也。夫荣启期一弹，而孔子三日乐，感于和；邹忌一徽，而威王终夕悲，感于忧。动诸琴瑟，形诸音声，而能使人为之哀乐，县法设赏而不能移风易俗者，其诚心弗施也。宁戚商歌车下，桓公喟然而寤。至精入人深矣。故曰：乐听其音，则知其俗；见其俗，则知其化。孔子学鼓琴于师襄，而谕文王之志，见微以知明矣。延陵季子听鲁乐，而知殷、夏之风，论近以识远也。作之上古，施及千岁，而文不灭；况于并世化民乎！汤之时，七年旱，以身祷于桑林之际，而四海之云凑，千里之雨至。抱质效诚，感动天地，神谕方外。令行禁止，岂足为哉！古圣王至精形于内，而好憎忘于外，出言以副情，发号以明旨，陈之以礼乐，风之以歌谣，业贯万世而不壅，横扃四方而不穷，禽兽昆虫，与之陶化，又况于执法施令乎！
故太上神化，其次使不得为非，其次赏贤而罚暴。衡之于左右，无私轻重，故可以为平；绳之于内外，无私曲直，故可以为正。人主之于用法，无私好憎，故可以为命。夫权轻重不差？15首，扶拨枉桡不失针锋，直施矫邪不私辟险。奸不能枉，谗不能乱，德无所立，怨无所藏，是任术而释人心者也。故为治者不与焉。夫舟浮于水，车转于陆，此势之自然也。木击折，水戾破舟，不怨木石而罪巧拙者，知故不载焉。是故道有智则惑，德有心则险，心有目则眩。兵莫よ于志，而莫邪为下；寇莫大于阴阳，而χ鼓为小。
今夫权衡规矩，一定而不易，不为秦、楚变节，不为胡、越改容，常一而不邪，方行而不流，一日刑之，万世传之，而以无为为之，故国有亡主，而世无废道；人有困穷，而理无不通。由此观之，无为者，道之宗。故得道之宗，应物无穷，任人之才，难以至治。汤、武，圣主也，而不能与越人乘干舟而浮于江湖；伊尹，贤相也，而不能与胡人骑原马而服驹余；孔、墨博通，而不能与山居者入榛薄险阻也。由此观之，则人知之于物也浅矣，而欲以遍照海内，存万方，不因道之数，而专己之能，则其穷不达矣。故智不足以治天下也。桀之力，制<角各>伸钩，索铁歙金，椎移大牺，水杀鼋鼍，陆捕熊罴；然汤革车三百乘，困之鸣条，擒之焦门。由此观之，勇力不足以持天下矣。智不足以为治，勇不足以为强，则人材不足任，明也。而君人者不下庙堂之上，而知四海之外者，因物以识物，因人以知人也。故积力之所举，则无不胜也；众智之所为，则无不成也。陷井之无鼋鼍，隘也；园中之无修木，小也。夫举重鼎者，力少而不能胜也，及至其移徙之，不待其多力者。故千人之群无绝梁，万人之聚无废功。
夫华骝、绿耳，一日而至千里，然其使之搏兔，不如豺狼，伎能殊也。鸱夜撮蚤蚊，察分秋豪，昼日颠越，不能见丘山，形性诡也。夫蛇游雾而动，应龙乘云而举，猿得木而捷，鱼得水而鹜。故古之为车也，漆者不画，凿者不斫，工无二伎，士不兼官，各守其职，不得相奸，人得其宜，物得其安。是以器械不苦，而职事不曼。夫责少者易偿，职寡者易守，任轻者易权。上操约省之分，下效易为之功，是以君臣弥久而不相厌。君人之道，其犹零星之尸也，俨然玄默，而吉祥受福。是故得道者不为丑饰，不为伪善，一人被之而不袤，万人蒙之而不褊。是故重为惠，若重为暴，则治道通矣。为惠者，尚布施也。无功而厚赏，无劳而高爵，则守职者懈于官，而游居者亟于进矣。为暴者，妄诛也。无罪者而死亡，行直而被刑，则修身者不劝善，而为邪者轻犯上矣。故为惠者生奸，而为暴者生乱。奸乱之俗，亡国之风。是故明主之治，国有诛者而主无怒焉，朝有赏者而君无与焉。诛者不怨君，罪之所当也；赏者不德上，功之所致也。民知诛赏之来，皆在于身也。故务功修业，不受赣于君。是故朝廷芜而无迹，田野辟而无草。故太上，下知有之。桥直植立而不动，俯仰取制焉；人主静漠而不躁，百官得修焉。譬而军之持麾者，妄指则乱矣。慧不足以大宁，智不足以安危，与其誉尧而毁桀也，不如掩聪明而反修其道也。
清静无为，则天与之时；廉俭守节，则地生之财；处愚称德，则圣人为之谋。是故下者万物归之，虚者天下遗之。夫人主之听治也，清明而不暗，虚心而弱志。是故群臣辐凑并进，无愚智贤不肖，莫不尽其能。于是乃始陈其礼，建以为基。是乘众势以为车，御众智以为马。虽幽野险途，则无由惑矣。
人主深居隐处以避燥湿，闺门重袭以避奸贼，内不知闾里之情，外不知山泽之形，帷幕之外，目不能见十里之前，耳不能闻百步之外；天下之物，无不通者，其灌输之者大，而斟酌之者众也。是故不出户而知天下，不窥牖而知天道，乘众人之智，则天下之不足有也。专用其心，则独身不能保也。是故人主覆之以德，不行其智，而因万人之所利。夫举踵天下而得所利，故百姓载之上，弗重也，错之前，弗害也，举之而弗高也，推之而弗厌。
主道员者，运转而无端，化育如神，虚无因循，常后而不先也；臣道员者，运转而无方，论是而处当，为事先倡，守职分明，以立成功也。是故君臣异道则治，同道则乱。各得其宜，处其当，则上下有以相使也。夫人主之听治也，虚心而弱志，清明而不暗。是故群臣辐凑并进，无愚智贤不肖，莫不尽其能者，则君得所以制臣，臣得所以事君，治国之道明矣。文王智而好问，故圣；武王勇而好问，故胜。夫乘众人之智，则无不任也；用众人之力，则无不胜也。千钧之重，乌获不能举也；众人相一，则百人有余力矣。是故任一人之力者，则乌获不足恃；乘众人之制者，则天下不足有也。
禹决江疏河，以为天下兴利，而不能使水西流；稷辟土垦草，以为百姓力农，然不能使禾冬生。岂其人事不至哉？其势不可也。夫推而不可为之势，而不修道理之数，虽神圣人不能以成其功，而况当世之主乎！夫载重而马羸，虽造父不能以致远；车轻马良，虽中工可使追速。是故圣人举事也，岂能拂道理之数，诡自然之性，以曲为直，以屈为伸哉！未尝不因其资而用之也。是以积力之所举，无不胜也，而众智之所为，无不成也。聋者可令嚼筋，而不可使有闻也；者可使守圉，而不可使言也。形有所不周，而能有所不容也。是故有一形者处一位，有一能者服一事。力胜其任，则举之者不重也；能称其事，则为之者不难也。毋小大修短，各得其宜，则天下一齐，无以相过也。圣人兼而用之，故无弃才。人主贵正而尚忠，忠正在上位，执正营事，则谗佞奸邪无由进矣。譬犹方员之不相盖，而巨直之不相入。夫鸟兽之不可同群者，其类异也；虎鹿之不同游者，力不敌也。是故圣人得志而在上位，谗佞奸邪而欲犯主者，譬犹雀之见，而鼠之遇狸也，亦必无余命也。
是故人主之一举也，不可不慎也。所任者得其人，则国家治，上下和，群臣亲，百姓附。所任非其人，则国家危，上下乖，群臣怨，百姓乱。故一举而不当，终身伤。得失之道，权要在主。是绳正于上，木直于下，非有事焉，所缘以修者然也。故人主诚正，则直士任事，而奸人伏匿矣；人主不正，则邪人得志，忠者隐蔽矣。夫人主之所以莫扌瓜玉石而扌瓜瓜瓠者，何也？无得于玉石，弗犯也。使人主执正持平，如从绳准高下，则群臣以邪来者，犹以卵投石，以火投水。故灵王好细要，而民有杀食自饥也；越王好勇，而民皆处危争死。由此观之，权势之柄，其以移风易俗矣。尧为匹夫，不能仁化一里，桀在上位，令行禁止。由此观之，贤不足以为治，而势可以易俗明矣。《书》曰：“一人有庆，万民赖之。”此之谓也。
天下多眩于名声，而寡察其实。是故处人以誉尊，而游者以辩显，察其所尊显，无它故焉，人主不明分数利害之地，而贤众口之辩也。治国则不然，言事者必究于法，而为行者必治于官。上操其名以责其实，臣守其业以效其功，言不得过其实，行不得逾其法。群臣辐凑，莫敢专君。事不在法律中，而可以便国佐治，必参五行之，阴考以观其归，并用周听，以察其化。不偏一曲，不党一事。是以中立而遍，运照海内，群臣公正，莫敢为邪，百官述职，务致其公迹也。主精明于上，官劝力于下，奸邪灭迹，庶功日进，是以勇者尽于军。乱国则不然。有众咸誉者无功而赏，守职者无罪而诛。主上暗而不明，群臣党而不忠，说谈者游于辩，修行者竞于住。主上出令，则非之以与；法令所禁，则犯之以邪。为智者务于巧诈，为勇者务于斗争。大臣专权，下吏持势，朋党周比，以弄其上。国虽若存，古之人曰亡矣。且夫不治官职，而被甲兵，不随南亩而有贤圣之声者，非所以教于国也。骐骥耳，天下之疾马也，驱之不前，引之不止，虽愚者不加体焉。今治乱之机，辙迹可见也，而世主莫之能察，此治道之所以塞。权势者，人主之车舆；爵禄者，人臣之辔衔也。是故人主处权势之要，而持爵禄之柄，审缓急之度，而适取予之节。是以天下尽力而不倦。
夫臣主之相与也，非有父子之厚，骨肉之亲也，而竭力殊死，不辞其躯者，何也？势有使之然也。昔者豫让，中行文子之臣。智伯伐中行氏，并吞其地。豫让背其主而臣智伯。智伯与赵襄子战于晋阳之下，身死为戮，国分为三。豫让欲报赵襄子，漆身为厉，吞炭变音，レ齿易貌。夫以一人之心而事两主，或背而去，或欲身徇之，岂其趋舍厚薄之势异哉？人之恩泽使之然也。纣兼天下，朝诸侯，人迹所及，舟楫所通，莫不宾服。然而武王甲卒三千人，禽之于牧野。岂周民死节，而殷民背叛哉？其主之义德厚而号令行也。夫疾风而波兴，木茂而鸟集，相生之气也。是故臣不得其所欲于君者，君亦不能得其所求于臣也。君臣之施者，相报之势也。是故臣尽力死节以与君，君计功垂爵以与臣。是故君不能赏无功之臣，臣亦不能死无德之君。君德不下流于民，而欲用之，如鞭蹄马矣。是犹不待雨而熟稼，必不不可之数也。
君人之道，处静以修身，俭约以率下。静则下不扰矣，俭则民不怨矣；下扰则政乱，民怨则德薄；政乱则贤者不为谋，德薄则勇者不为死。是故人主好鸷鸟猛兽，珍怪奇物，狡躁康荒，不爱民力，驰骋田猎，出入不时，如此，则百官务乱，事勤财匮，万民悉苦，生业不修矣。人主好高台深池，雕琢刻镂，黼黻文章，
绮绣，宝玩珠玉；则赋敛无度，而万民力竭矣。尧之有天下也，非贪万民之富而安人主之位也，以为百姓力征，强凌弱，众暴寡，于是尧乃身服节俭之行，而明相爱之仁，以和辑之。是故茅茨不剪，采椽不断，大路不画，越席不缘，大羹不和，粢食不？16。巡狩行教，勤劳天下，周流五岳。岂其奉养不足乐哉！举天下而以为社稷，非有利焉。年衰志悯，举天下而传之舜，犹却行而脱屣也。衰世则不然。一日而有天下之富，处人主之势，则竭百姓之力，以奉耳目之欲，志专在宫室台榭，陂池苑囿，猛兽熊罴，玩好珍怪。是故贫民糟糠不接于口，而虎狼熊罴厌刍豢；百姓短褐不完，而宫室衣锦绣。人主急兹无用之功，百姓黎民，憔悴于天下。是故使天下不安其性。
人主之居也，如日月之明也。天下之所同侧目而视，侧耳而听，延颈举踵而望也。是故非澹薄无以明德，非宁静无以致远，非宽大无以兼覆，非慈厚无以怀众，非平正无以制断。是故贤主之用人也，犹巧工之制木也，大者以为舟航柱梁，小者以为楫楔，修者以为阎榱，短者以为朱儒开栌。无小大修短，各得其所宜；规矩方圆，各有所施。天下之物，莫凶于鸡毒，然而良医橐而藏之，有所用也。是故林莽之材，犹无可弃者，而况人乎？今夫朝廷之所不举，乡曲之所不誉，非其人不肖也，其所以官之者非其职也。鹿之上山，獐不能也，及其下，牧竖能追之；才有所修短也。是故有大略者，不可责以捷巧；有小智者，不可任以大功。人有其才，物有其形，有任一而太重，或任百而尚轻。是故审豪厘计者，必遗天下之大数；不失小物之选者，惑于大数之举。譬犹狸之不可使搏牛，虎之不可使捕鼠也。今人之才，或欲平九州，并方外，存危国，继绝世，志在直道正邪，决烦理，而乃责之以闺阁之礼，奥之间；或佞巧小具，谄进愉说，随乡曲之俗，卑下众人之耳目，而乃任之以天下之权，治乱之机。是犹以斧赞刂毛，以刀伐木也，皆失其宜矣。
人主者，以天下之目视，以天下之耳听，以天下之智虑，以天下之力争。是故号令能下究，而臣情得上闻。百官修同，群君辐凑，喜不以赏赐，怒不以罪诛。是故威立而不废，聪明光而不蔽，法令察而不苛，耳目达而不暗，善否之情，日陈于前而无所逆。是故贤者尽其智，而不肖者竭其力。德泽兼覆而不偏，群臣劝务而不怠，近者安其性，远者怀其德。所以然者，何也？得用人之道，而不任己之才者也。故假舆马者，足不劳而致千里；乘舟楫者，不能游而绝江海。夫人主之情，莫不欲总海内之智，尽众人之力，然而群臣志达效忠者，希不困其身。使言之而是，虽在褐夫刍荛，犹不可弃也；使言之而非也，虽在卿相人君，揄策于庙堂之上，未必可用。是非之所在，不可以贵贱尊卑论也。是明主之听于群臣，其计乃可用，不羞其位；其言可行，而不责其辩。暗主则不然。所爱习亲近者，虽邪枉不正，不能见也；疏远卑贱者，竭力尽忠，不能知也。有言者穷之以辞，有谏者诛之以罪。如此而欲照海内，存万方，是犹塞耳而听清浊，掩目而视青黄也，其离聪明则亦远矣！
法者，天下之度量，而人主之准绳也。县法者，法不法也；设赏者，赏当赏也。法定之后，中程者赏，缺绳者诛。尊贵者不轻其罚，而卑贱者不重其刑，犯法者虽贤必诛，中度者虽不肖必无罪，是故公道通而私道塞矣。古之置有司也，所以禁民，使不得自恣也；其立君也，所以刂有司，使无专行也；法籍礼仪者，所以禁君，使无擅断也。人莫得自恣，则道胜；道胜而理达矣，故反于无为。无为者，非谓其凝滞而不动也，以其言莫从己出也。夫寸生于粟，々生于日，日生于形，形生于景，此度之本也。乐生于音，音生于律，律生于风，此声之宗也。法生于义，义生于众适，众适合于人心，此治之要也。故通于本者不乱于末，睹于要者不惑于详。法者，非天堕，非地生，发于人间，而反以自正。是故有诸己不非诸人，无诸己不求诸人。所立于下者，不废于上；所禁于民者，不行于身。所谓亡国，非无君也，无法也。变法者，非无法也，有法者而不用，与无法等。是故人主之立法，先自为检式仪表，故令行于天下。孔子曰：“其身正，不令而行；其身不正，虽令不从。故禁胜于身，则令行于民矣。
圣主之治也，其犹造父之御。齐辑之于辔衔之际，而急缓之于唇吻之和；正度于胸臆之中，而执节于掌握之间；内得于心中，外合于马志。是故能进退履绳，而旋曲中规；取道致远，而气力有余。诚得其术也。是故权势者，人主之车舆也；大臣者，人主之驷马也。体离车舆之安，而手失驷马之心，而能不危者，古今未有也。是故舆马不调，王良不足以取道；君臣不和，唐、虞不能以为治。执术而御之，则管、晏之智尽矣；明分以示之，则庶、乔之奸止矣。夫据除而窥井底，虽达视犹不能见其晴，借明于鉴以照之，则寸分可得而察也。是故明主之耳目不劳，精神不竭，物至而观其象，事来而应其化，近者不乱，远者治也。是故不用适然之数，而行必然之道，故万举而无遗策矣。今夫御者，马体调于车，御心和于马，则历险致远，进退周游，莫不如志。虽有骐骥耳之良，臧获御之，则马反自恣，而人弗能制矣。故治者不贵其自是，而贵其不得为非也。故曰：勿使可欲，毋曰弗求，勿使可夺，毋曰不争。如此，则人材释而公道行矣。美者正于度，而不足者建于用，故海内可一也。夫释职事而听非誉，弃公劳而用朋党，则奇材佻长而干次，守官者雍遏而不进。如此，则民俗乱于国，而功臣争于朝。故法律度量者，人主之所以执下，释之而不用，是犹无辔衔而驰也，群君百姓反弄其上。是故有术则制人，无术则制于人。吞舟之鱼，荡而失水，则制于蝼蚁，离其居也；猿失木，而禽于狐狸，非其处也。君人者释所守而与臣下争，则有司以无为持位，守职者以从君取容。是以人臣藏智而弗用，反以事转任其上矣。夫富贵者之于劳也，达事者之于察也，骄恣者之于恭也，势不及君；君人者不任能而好自为之，则智日困而自负其责也。数穷于下，则不能伸理；行堕于国，则不能专制。智不足以为治，威不足以行诛，则无以与天下交也。喜怒形于心者，欲见于外，则守职者离正而阿上，有司枉法而从风，赏不当功，诛不应罪，上下离心，而君臣相怨也。是以执政阿主，而有过则无以责之。有罪而不诛，则百官烦乱，智弗能解也；毁誉萌生，而明不能照也。不正本而反自然，则人主逾劳，人臣逾逸，是犹代庖宰剥牲，而为大匠斫也。与马竞走，筋绝而弗能及，上车执辔，则马？17于衡下。故伯乐相之，王良御之，明主乘之，无御相之劳而致千里者，乘于人资以为羽翼也。是故君人者，无为而有守也，有为而无好也。有为则谗生，有好则谀起。昔者齐桓公好味，而易牙烹其首子而饵之；虞君好宝，而晋献以璧马钓之；胡王好音，而秦穆公以女乐诱之。是皆以利见制于人也。故善建者不拔。夫火热而水灭之，金刚而火销之，木强而斧伐之，水流而土遏之，唯造化者，物莫能胜也。故中欲不出谓之扃，外邪不入谓之塞。中扃外闭，何事之不节！外闭中扃，何事之不成？弗用而后能用之，弗为而后能为之。精神劳则越，耳目淫则竭。故有道之主，灭想去意，清虚以待，不伐之言，不夺之事，循名责实，使有司，任而弗诏，责而弗教，以不知为道，以奈何为宝。如此，则百官之事，各有所守矣。摄权势之柄，其于化民易矣。卫君役子路，权重也；景、桓公臣管晏，位尊也。怯服勇而愚制智，其所托势者胜也。故枝不得大于，末不强于本，则轻重大小，有以相制也。若五指之属于臂，搏援攫捷，莫不如志。言以小属于大也。是故得势之利者，所持甚小，其存甚大；所守甚约，所制甚广。是故十围之木，持千钧之屋；五寸之键，制开阖之门。岂其材之巨小足哉？所居要也。孔丘、墨翟，修先圣之术，通六艺之论，口道其言，身行其志，慕义从风，而为之服役者不过数十人。使居天子之位，则天下遍为儒、墨矣。楚庄王伤文无畏之死于宋也，奋袂而起，衣冠相连于道，遂成军宋城之下，权重也。楚文王好服獬冠，楚国效之，赵武灵王贝带寿而朝，赵国化之。使在匹夫布衣，虽冠獬冠，带贝带、寿而朝，则不免为人笑也。夫民之好善乐正，不待禁诛而自中法度者，万无一也。下必行之令，从之者利，逆之者凶，日阴未移，而海内莫不被绳矣。故握剑锋，以离北宫子，司马蒯蒉不使应敌；操其觚，招其末，则庸人能以制胜。今使乌获、藉蕃从后牵牛尾，尾绝而不从者，逆也；若指之桑条以贯其鼻，则五尺童子，牵而周四海者，顺也。夫七尺之桡而制船之左右者，以水为资；天子发号，令行禁止，以众为势也。夫防民之所害，开民之所利，威行也，若发咸决唐。故循流而下易以至，背风而驰易以远。桓公立政，去食肉之兽，食粟之鸟，系之网，三举而百姓说。纣杀王子比干而骨肉怨，<昔斤>朝涉者之胫而万民叛，再举而天下失矣。故义者，非能遍利天下之民也，利一人而天下从风；暴者，非尽害海内之众也，害一人而天下离叛。故桓公三举而九合诸侯，纣再举而不得为匹夫。故举错不可不审。
人主租敛于民也。必先计岁收，量民积聚，知饥馑有余不足之数，然后取车舆衣食供养其欲。高台层榭，接屋连阁，非不丽也，然民有掘穴狭庐所以托身者，明主弗乐也。肥Ο甘脆，非不美也，然民有糟糠菽粟不接于口者，则明主弗甘也。匡床席，非不宁也，然民有处边城，犯危难，泽死暴骸者，明主弗安也。故古之君人者，其惨怛于民也。国有饥者，食不重味；民有寒者，而冬不被裘。岁登民丰，乃始县钟鼓，陈干戚，君臣上下，同心而乐之，国无哀人。故古之为金石管弦者，所以宣乐也；兵革斧钺者，所以饰怒也；觞酌俎豆，酬酢之礼，所以效善也；衰菅屦，辟踊哭泣，所以谕哀也。此皆有充于内而成像于外。及至乱主，取民则不裁其力，求于下则不量其积，男女不得事耕织之业，以供上之求，力勤财匮，君臣相疾也。故民至于焦唇沸肝，有今无储，而乃始撞大钟，击鸣鼓，吹竽笙，弹琴瑟，是犹贯甲胄而入宗庙，被罗纨而从军旅，失乐之所由生矣。夫民之为生也，一人庶耒而耕，不过十亩，中田之获，卒岁之收，不过亩四石，妻子老弱，仰而食之，时有涔旱灾害之患，无以给上之征赋车马兵革之费。由此观之，则人之生，悯矣！夫天地之大，计三年耕而余一年之食，率九年而有三年之畜，十八年而有六年之积，二十七年而有九年之储，虽涔旱灾害之殃，民莫困穷流亡也。故国无九年之畜，谓之不足；无六年之积，谓之悯急；无三年之畜，谓之穷乏。故有仁君明王，其取下有节，自养有度，则得承受于天地，而不离饥寒之患矣。若贪主暴君，挠于其下，侵渔其民，以适无穷之欲，则百姓无以被天和而履地德矣。
食者，民之本也；民者，国之本也；国者，君之本也。是故人君者，上因天时，下尽地财，中用人力，是以群生遂长，五谷蕃殖，教民养育六畜，以时种树，务修田畴，滋植桑麻，肥尧高下，各因其宜，丘陵阪险不生五谷者，以树竹木。春伐枯槁，夏取果，秋畜疏食，冬伐薪蒸，以为民资。是故生无乏用，死无转尸。故先王之法，畋不掩群，不取は夭。不涸泽而渔，不焚林而猎。豺未祭兽，{孚}不得布于野；獭未祭鱼，网罟不得入于水；鹰隼未挚，罗网不得张于溪谷；草木未落，斤斧不得入山林；昆虫未蛰，不得以火烧田。孕育不得杀，？18卵不得探，鱼不长尺不得取，彘不期年不得食。是故草木之发若蒸气，禽兽之归若流泉，飞鸟之归若烟云，有所以致之也。故先王之政，四海之云至，而修封疆；虾蟆鸣燕降，而达路除道；阴降百泉，则修桥梁；张中，则务种谷；大火中，则种黍菽；虚中，则种宿麦；昴中，则收敛畜积，伐薪木。上告于天，下布之民。先王之所以应时修备，富国利民，实旷来远者，其道备矣。非能目见而足行之也，欲利之也。欲利之也，不忘于心，则官自备矣。心之于九窍四支也，不能一事焉。然而动静听视皆以为主者，不忘于欲利之也。故尧为善而众善至矣，桀为非而众非来矣。善积则功成，非积则祸极。
凡人之论，心欲小而志欲大，智欲员而行欲方，能欲多而事欲鲜。所以心欲小者，虑患未生，备祸未发，戒过慎微，不敢纵其欲也；志欲大者，兼包万国，一齐殊俗，并覆百姓，若合一族，是非辐凑而为之毂；智欲员者，环复转运，终始无端，旁流四达，渊泉而不竭，万物并兴，莫不响应也；行欲方者，直立而不挠，素白而不污，穷不易操，通不肆志；能欲多者，文武备具，动静中仪，举动废置，曲得其宜，无所击戾，无不毕宜也；事欲鲜者，执柄持术，得要以应众，执约以治广，处静持中，运于璇枢，以一合万，若合符者也。故心小者，禁于微也；志大者，无不怀也；智员者，无不知也；行方者，有不为也；能多者，无不治也；事鲜者，约所持也。
古者天子听朝，公卿正谏，博士诵诗，瞽箴师诵，庶人传语，史书其过，宰彻其膳。犹以为未足也，故尧置敢谏之鼓，舜立诽谤之木，汤有司直之人，武王立戒慎之召。过若豪厘，而既已备之也。夫圣人之于善也，无小而不举；其于过也，无微而不改。尧、舜、禹、汤、文、武，皆坦然天下而南面焉。当此之时，鼓而食，奏《雍》而彻，已饭而祭灶，行不用巫祝，鬼神弗敢祟，山川弗敢祸，可谓至贵矣。然而战战栗栗，日慎一日。由此观之，则圣人之心小矣。《诗》云：惟此文王，小心翼翼，昭事上帝，聿怀多福。”其斯之谓欤！武王伐纣，发钜桥之粟，散鹿台之钱，封比干之墓，表商容之闾，朝成汤之庙，解箕子之囚。使各处其宅，田其田，无故无新，惟贤是亲，用非其有，使非其人，晏然若故有之。由此观之，则圣人之志大也。文王、周公观得失，遍览是非，尧、舜所以昌，桀、纣所以亡者，皆著于明堂，于是略智博问，以应无方。由此观之，则圣人之智员矣。成、康继文、武之业，守明堂之制，观存亡之迹，见成败之变，非道不言，非义不行，言不苟出，行不苟为，择善而后从事焉。由此观之，则圣人之行方矣。孔子之通，智过于苌弘，勇服于孟贲，足蹑效菟，力招城关，能亦多矣。然而勇力不闻，伎巧不知，专行教道，以成素王，事亦鲜矣。《春秋》二百四十二年，亡国五十二，弑君三十六，采善Θ丑，以成王道，论亦博矣。然而围于匡，颜色不变，弦歌不辍，临死亡之地，犯患难之危，据义行理而志不慑，分亦明矣。然为鲁司寇，听狱必为断，作为《春秋》，不道鬼神，不敢专己。夫圣人之智，固已多矣。其所守者约，故举而必荣。愚人之智，固已少矣，其所事者多，故动而必穷矣。吴起、张仪，智不若孔、墨，而争万乘之君，此其所以车裂支解也。夫以正教化者，易而必成；以邪巧世者，难而必败。凡将设行立趣于天下，舍其易成者，而从事难而必败者，愚惑之所致也。凡此六反者，不可不察也。遍知万物而不知人道，不可谓智；遍爱群生而不爱人类，不可谓仁。仁者爱其类也，智者不可惑也。仁者虽在断割之中，其所不忍之色可见也。智者虽烦难之事，其不暗之效可见也。内恕反情，心之所欲，其不加诸人，由近知远，由己知人，此仁智之所合而行也。小有教而大有存也，小有诛而大有宁也，唯恻隐推而行之，此智者之所独断也。故仁智错，有时合，合者为正，错者为权，其义一也。府吏守法，君制义，法而无义，亦府吏也，不足以为政。
耕之为事也劳，织之为事也扰，扰劳之事而民不舍者，知其可以衣食也。人之情不能无衣食，衣食之道，必始于耕织，万民之所公见也。物之若耕织者，始初甚劳，终必利也。众愚人之所见者寡，事可权者多，愚之所权者少，此愚者之所多患也。物之可备者，智者尽备之；可权者，尽权之；此智者所以寡患也。故智者先忤而后合，愚者始于乐而终于哀。今日何为而荣乎？旦日何为而义乎？此易言也。今日何为而义，旦日何为而荣，此难知也。问瞽师曰：“白素何如？”曰：“缟然。”曰：“黑何若？”曰：“<黑甚>然。”授白黑而示之，则不处焉。人之视白黑以目，言白黑以口，瞽师有以言白黑，无以知白黑，故言白黑与人同，其别白黑与人异。
入孝于亲，出忠于君，无愚智贤不肖，皆知其为义也，使陈忠孝行而知所出者，鲜矣！凡人思虑，莫不先以为可而后行之，其是或非，此愚智之所以异。凡人之性，莫贵于仁，莫急于智。仁以为质，智以行之，两者为本，而加之以勇力、辩慧、捷疾、劬录、巧敏、迟利、聪明、审察，尽众益也。身材未修，伎艺曲备，而无仁智以为表干，而加之以众美，则益其损。故不仁而有勇力果敢，则狂而操利剑；不智而辩慧怀给，则弃骥而不式。虽有材能，其施之不当，其处之不宜，适足以辅伪饰非，伎艺之众，不如其寡也。故有野心者，不可借便势；有愚质者，不可与利器。鱼得水而游焉则乐，唐决水涸，则为蝼蚁所食。有掌修其堤防，补其缺漏，则鱼得而利之，国有以存，人有以生。国之所以存者，仁义是也；人之所以生者，行善是也。国无义，虽大必亡；人无善志，虽勇必伤。治国上使不得与焉。孝于父母，弟于兄嫂，信于朋友，不得上令而可得为也。释己之所得为，而责于其所不得制，悖矣。士处卑隐，欲上达，必先反诸己。上达有道，名誉不起，而不能上达矣；取誉有道，不信于友，不能得誉；信于友有道，事亲不说，不信于友；说亲有道，修身不诚，不能事亲矣；诚身有道，心不专一，不能专诚。道在易而求之难，验在近而求之远，故弗得也。', '《淮南子·主术训》是西汉初年淮南王刘安创作的一篇散文。', '', '君主治理天下，应实施无为而治，推行无须说教就能使人明白的原则。君主自身应清静而不浮躁，坚持自然法度而不动摇；以顺循事物固有特性的态度任用下属，充分发挥群臣百官的作用，使他们各尽其责而自己不必亲自操劳和费心。所以根据上述的原则，君主心里明白，藏有韬略却让国师来晓喻开导，能说会道却让行人去陈说，脚腿灵便却让相者引导宾客，耳朵聪敏却由执政官员来转达百官意见或计谋。因而，君主考虑问题便不会失策，行动计划便不会过错；言论合理，行为可作天下之表率；进退适合时宜，动静遵循原理；也不会因事物的美丑而产生好恶之情，更不会因赏罚而喜怒；事物叫什么名称就随它叫什么名称，事物属什么类别就让它属什么类别；事物是什么样子都是自然而然的，并不是由个人意志所决定的。所以，古代帝王君主，带的冠冕前面装饰一串珠玉，这是用来遮挡视线的；冠冕两侧垂悬的绵丸球，这是用来堵塞耳朵的；皇帝宫外设立的屏风，这是用来阻隔自己、远离小人的。因此君主管辖的范围越远，所审察的范围却越近；治理的事情越大，所操持的事情却越小（越简约）。眼睛乱看则易淫邪，耳朵乱听则易迷惑，嘴巴乱说则易搅乱。这三道关口，平时不可不谨慎把持。如果要去规范它，则是离散了它；如果要去修饰它，则是伤害了它。
接受天之阳气的叫魂，接受地之阴气的叫魄；魂魄返聚心体玄房，各自所处自己位置，持守而不散失，人的精神就能上通太一元气。这太一元气是与天道融会相通。天道沉静玄妙、没有形貌也没有常态规则，其大不可极，其深不可测；它常与人一起化育，而人的智慧却无法把握它。
过去神农氏治理天下，精神沉静而不躁动驰骋于胸中，智慧藏匿而不显露于身外，只怀着一颗仁爱真诚之心。因而自然界甘雨及时降落，五谷繁茂生长，春生夏长，秋收冬藏。按月检查，每季考察，到年底向祖宗神灵汇报丰收成功的喜讯，按季节尝吃新谷，在明堂祭祀祖宗神灵。明堂的建制式样，有天穹一样的圆形顶盖而无四面墙壁，但风雨却不能侵袭，寒暑也不能伤害。每当祭祀祖宗神灵时，怀着公心养育民众的神农氏率领随从胸襟坦荡步履从容地进入明堂。他的民众朴素稳重、正直诚实，不用互相争夺，因为财物富足，不用过分劳累身体而能大功告成。他凭借着大自然的资助，而与天地自然融会一体。所以，他尽管身处威厉地位，但却从不逞威逞凶；制定刑法政令，但却不必动用；法令简略而不烦杂，所以对民众的教化功效神奇。他的管辖范围南到交趾，北到幽都，东到旸谷，西到三危，各处无不听从归附。在这个时候，法律宽厚，刑罚轻缓，监狱空虚，而天下风俗却纯一，谁也不怀奸诈之心。
而晚世的政治就不是这样了。君主热衷于索取而没有休止，官吏贪婪得不懂得半点谦让；民众因贫困而被迫互相怨恨争夺，费尽辛劳而不得报酬；智巧奸诈从此萌发兴起，盗贼从此滋生泛滥；上上下下互相怨恨，法规号令不能推行实施；政府各级官员不致力于归依天道，而是违逆治国的根本，只注意修饰枝节、小事；这时德政受到砍削，而刑罚却得到加强增重，而想这样来治理好天下，无异于手拿弹弓却想招引鸟雀，挥动木棍却想与狗玩耍，那只会乱上添乱。水混浊则鱼儿就会浮出水面呼吸喘气，政令烦琐苛刻则民众烦躁不安。所以那些驯养虎、豹、犀牛、大象的人，尽管给这些动物修建了栅栏，供给这些动物喜爱吃的食物，并适时投放不让这些动物挨饿，改变这些动物的暴怒性情，使之驯驯服服，但就是不能使它们享尽自然寿命，原因何在？这是因为这些动物的身体受到了强制的约束和胁迫。因此，在上的君主多智巧，在下的臣民就多奸诈；在上的君主多事情，在下的臣民易生事；在上的君主好烦扰，在下的臣民必受干扰而不安定；在上的君主多贪欲，在下的臣民好争斗。不立足根本而去追求末节，就好像扬起尘土去制止飞尘、抱着薪柴去救火一样。
所以，圣人简省事务而治理容易，欲求少而容易满足；不需布施而能表示仁爱，不须信誓旦旦反能显示诚实，不需索取就能获得，不用做什么反能收到成效；他安然不动保守纯真，怀抱道德以诚待人；天下人都归顺跟随他，如同回音应和声音，物影跟随形体：这些都在于圣人修养根本的缘故。刑罚不足以移风易俗，杀戮不足以禁绝奸邪；唯有从精神上纯化才是根本，那至精的无为之道才有神奇作用。
大声呼喊只能传到百步之远，而心志精神却能超越千里之外。冬天的阳光、夏天的荫凉，万物都向往和喜欢它，却又没有谁要万物这样子。所以，最纯精的东西，你不用召唤它就会自然到来、不用挥手它就会自然离去；它幽深玄妙，神不知鬼不觉地就使事物自然成功；有智慧者无法说清楚，善辩者又无法形容它。以前，孙叔敖安然静卧，使楚国不用刀枪却能称雄天下；楚都城南的勇士宜辽熊面对白公胜举剑威逼，心志不惧泰然自若地转动着手中的球丸，表达自己保持中立的立场，使自己在白公胜和令尹子西两家的战难中免受牵连。披挂着皮革护胸甲和铁制铠甲，怒目扼腕、情绪激愤、立马横刀来抵御敌兵的刀枪，其功效要比以德服人差远了！以钱财笼络、刑法镇慑，这样来解决危难，其作用要比以德感化小得多！凭眼睛观察事物、靠言辞发号施令，这样治理天下比无为而治难得多！
过去蘧伯玉做卫国的丞相，子贡前去拜访他，问：“你是如何治理国家的？”蘧伯玉回答说：“靠不治来治理。”赵简子准备征伐卫国，先派史墨前去侦察。史墨回来报告说：“蘧伯玉担当卫国的丞相，所以不可以出兵。”由此看来，坚固的要塞和险峻的关隘又怎么能起到这种功效呢？所以皋陶尽管聋哑，但就是凭着哑疾而做上了舜帝的司法官，天下没有暴虐的刑罚，哑巴却有着比语言更值得珍贵的地方；师旷眼瞎而当上晋国的太宰，晋国便没有混乱的政局，瞎子有着比明目者更珍贵的东西。所以说，不动嘴说话就能实行政令，不睁眼观看就能明察秋毫，这就是伏羲和神农能成为后人师表的缘故。民众受感化，不是根据君主的言传，而是根据君主的身教。
所以，齐庄公好养武士和穷兵黩武，尽管他并没有要百姓互相争斗，但国家就是多灾多难，致使后来崔杼弑君作乱。楚襄王专淫好色，尽管他并没有公开宣传色情，但民众却淫乱昏昧，最后发展到国土丧失、逃离京城的灾难发生。所以最精粹的精神感化作用，就像春天生长、秋天肃杀一样，哪怕是驿马传递，都不如它快速。所以，治理国家的君主，大概就像射手一样，瞄准发射时的毫毛之差，都会造成极大误差的后果。所以要慎重地对待精神感化这一事情。', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a702eebf5e0fdea577b8", "shortContent": "此语出自《主术训》。它的意思是说，水太浑浊了，鱼儿就会浮出水面呼吸喘气；政令烦琐苛刻，民众就会动乱不安。这句话也曾出现于《韩诗外传》，但文字略有不同，今本《韩诗外传》作“水浊则鱼喁，令苛则民乱。”“噞”、“喁”古音相近，意思相通。“噞”，高诱注作：“鱼短气出口于水，喘息之喻也。”“喁”，《说文解字》解释作：“喁，鱼口上见。”曾有学者据此推断此语是《淮南子》作者采《韩诗》而改之，但也有学者如马宗霍等...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a702eebf5e0fdea577b9", "shortContent": "大声呼喊只能传到百步之远，而人的志向所在却能够超越千里之外。《淮南子》由此所要突出的是志向的巨大效力，鼓励人们要敢于树立远大的志向。因为志向决定了一个人一生事业的方向，只有这个大方向确定了，人在为人处世的过程中才能够有一个明确的目标；同时，立志也意味着一个人的真正自觉与独立，意味着一个人对于自己责任的觉醒。就此而言，立志是一个人一生事业的起点，因此不可不慎。\n\n历史上对“立志”讲述得最为透彻的人，...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a702eebf5e0fdea577ba", "shortContent": "此语出自《主术训》。它的意思是说，大禹能够疏通长江引导黄河，替天下人兴修水利，然而他却不能使江河改道西流。《淮南子》作者在这里借此以喻证黄老道家“无为而治”的思想。\n\n我们一般说黄老道家“无为而治”的思想是消极的、否定性的，但事实上这种“无为而治”思想却蕴含着积极的、肯定性的意蕴。“无为而治”并不是真的无所作为、不作为，而是强调遵循事物变化发展的客观规律，因势利导，顺应民情民意，以尽可能小的代价来...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a702eebf5e0fdea577bc", "shortContent": "此语出自《主术训》。它的意思是说，圣主明君对于善事，无论有多小也必定去做；而对于过失，不论多小也要立即改正。《淮南子》作者在这里阐述了统治者自身素质与社会的长治久安、百姓的安定和谐之间的关系，这也是黄老道家“无为而治”思想的应有之义。\n\n黄老道家学者虽然主张“无为而治”，提倡以“无为”的方式和手段来实现社会的长治久安、百姓的安定和谐，但是，“无为而治”并不排斥统治者的作用和意义。他们和儒家学者一样...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fbed05fc8182fe989db7d", "bookTitle": "淮南子鉴赏辞典", "articleId": "647c714fa5f1e74f95edefe6", "shortContent": "本卷作者详尽阐述了君主“为君之道”，即统治术，就像高诱题解说的那样：“主，君也。术，道也。君之宰国，统御臣下，五帝三王以来，无不用道而兴，故曰‘主术’也。”由于君主在古代政治、行政体系中起着非常关键的作用，因而古人一直都很重视对于为君之道的探讨，如《荀子》曾提出“君道”的概念，《吕氏春秋》亦曾对“君守”做过专门论述。正是由于认识到君主在政治中的关键地位，《淮南子》在阐述了其政治哲学之后，紧接着便用...", "authors": ["刘康德", "张锋宾"], "pressName": "上海辞书出版社"}, {"bookId": "645fbed05fc8182fe989db7d", "bookTitle": "淮南子鉴赏辞典", "articleId": "647c8ea6c98d685fd9dd4333", "shortContent": "这句话的意思是，水太浑浊了，鱼儿就会浮出水面呼吸喘气；政令烦琐苛刻，民众就会动乱不安。这句话也曾出现于《韩诗外传》，但文字略有不同，今本《韩诗外传》作“水浊则鱼喁，令苛则民乱。”“噞”“喁”古音相近，意思相通。“噞”，高诱注作：“鱼短气出口于水，喘息之喻也。”“喁”，《说文解字》解释作：“喁，鱼口上见。”曾有学者据此推断此语是《淮南子》作者采《韩诗》而改之，但也有学者如马宗霍等认为，二书未必即出《...", "authors": ["张锦波"], "pressName": "上海辞书出版社"}, {"bookId": "645fbed05fc8182fe989db7d", "bookTitle": "淮南子鉴赏辞典", "articleId": "647c8ef782772d45948674b7", "shortContent": "大声呼喊只能传到百步之远，而人的志向所在却能够超越千里之外。《淮南子》由此所要突出的是志向的巨大效力，鼓励人们要敢于树立远大的志向。因为志向决定了一个人一生事业的方向，只有这个大方向确定了，人在为人处世的过程中才能够有一个明确的目标；同时，立志也意味着一个人的真正自觉与独立，意味着一个人对于自己责任的觉醒。就此而言，立志是一个人一生事业的起点，因此不可不慎。\n\n历史上对“立志”讲述得最为透彻的人，...", "authors": ["刘康德"], "pressName": "上海辞书出版社"}, {"bookId": "645fbed05fc8182fe989db7d", "bookTitle": "淮南子鉴赏辞典", "articleId": "647c8f32a5f1e74f95ee861f", "shortContent": "这句话的意思是，大禹能够疏通长江引导黄河，替天下人兴修水利，然而他却不能使江河改道西流。《淮南子》作者在这里借此以喻证黄老道家“无为而治”的思想。\n\n我们一般说黄老道家“无为而治”的思想是消极的、否定性的，但事实上这种“无为而治”思想却蕴含着积极的、肯定性的意蕴。“无为而治”并不是真的无所作为、不作为，而是强调遵循事物变化发展的客观规律，因势利导，顺应民情民意，以尽可能小的代价来换取最大化的社会长...", "authors": ["张锦波"], "pressName": "上海辞书出版社"}, {"bookId": "645fbed05fc8182fe989db7d", "bookTitle": "淮南子鉴赏辞典", "articleId": "647c8f71a5f1e74f95ee8715", "shortContent": "“非淡泊无以明志，非宁静无以致远”是我们耳熟能详的一则名言，一般我们都认为这句话出自诸葛亮五十四岁时写给他八岁儿子诸葛瞻的《诫子书》：“夫君子之行，静以修身，俭以养德。非淡泊无以明志，故非宁静无以致远。”但是，事实上这句话并非是诸葛亮的原创，而是出自《淮南子·主术训》。\n\n《主术训》在这里主要是想告诫君主应当如何修养自己的德性，才能成为天下人的楷模，从而影响天下百姓，使社会养成一股正气。因为在作者...", "authors": ["刘康德"], "pressName": "上海辞书出版社"}, {"bookId": "645fbed05fc8182fe989db7d", "bookTitle": "淮南子鉴赏辞典", "articleId": "647c8fa0c98d685fd9dd47a2", "shortContent": "这句话的意思是，圣主明君对于善事，无论有多小也必定去做；而对于过失，不论多小也要立即改正。《淮南子》作者在这里阐述了统治者自身素质与社会的长治久安、百姓的安定和谐之间的关系，这也是黄老道家“无为而治”思想的应有之义。\n\n黄老道家学者虽然主张“无为而治”，提倡以“无为”的方式和手段来实现社会的长治久安、百姓的安定和谐，但是，“无为而治”并不排斥统治者的作用和意义。他们和儒家学者一样，都强调统治者的圆...", "authors": ["张锦波"], "pressName": "上海辞书出版社"}, {"bookId": "645fbed05fc8182fe989db7d", "bookTitle": "淮南子鉴赏辞典", "articleId": "647c8fca66a763596a03e4fb", "shortContent": "这句话的意思是，普遍地爱护各种生物而不爱护人类本身，就不能叫“仁”。“仁”本是儒家所竭力提倡的道德品质之一，《淮南子》作者在这里将之作为君主的重要品质，与“智”一样，都放到“人主之术”的语境下加以阐述。从而强调，“仁”不仅仅是君子必修的德性之一，还是君主实现其统御百姓、治理国家的重要政治品格。\n\n在儒家那里，“仁”是重要的道德品格，属于道德哲学或伦理学的哲学范畴。《主术训》中，“仁”固然也被界定为...", "authors": ["张锦波"], "pressName": "上海辞书出版社"}]', '', 'indent', 1545390207, '5c1c58047f6fd3005d01adff', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640826, '默觚下·治篇八', NULL, 19, 39, 1, 1, '魏源', NULL, 26304, '5858f40d8d6d810065c3866d', '清', 'wen', '文', 'https://baike.baidu.com/item/%E9%BB%98%E8%A7%9A/8679050', '', '孤举者难起，众行者易趋；倾厦非一木之支也，决河非捧土之障也。', '《默觚》是中国近代思想家魏源的著作。其中包含了作者的哲学思想。分《学篇》和《治篇》两大部分。', '《默觚》是中国近代思想家魏源的著作，分《学篇》《治篇》两部分，集中反映了魏源的修身论、认识论、天理论、人才观、历史观等思想。“默”取自魏源的字“默深”，“觚”为古代用来书写的木简，故名“默觚”。

上面这段话阐述了魏源的人才思想。“孤举者难起，众行者易趋”，意思是一个人独自奋起很困难，许多人一块儿行走就容易走得快，从正反两方面强调了团结合作的重要性。接着又打了两个比方：“倾厦非一木之支也，决河非捧土之障也”，倾斜的大厦不是一根木头就能支撑得了的，决了口的河道不是一捧土就能堵塞得住的。说明挽救危局，单凭个人力量是不够的，必须群策群力，既要造就特殊人才，还需培养有凝聚力的人才群体助其成功。

魏源身处嘉道之际的大变革时代，是中国近代史上“睁眼看世界”的先行者。他反对乾嘉以来脱离实际的烦琐考据学和空谈心性修养的理学，主张通经致用，积极用世，故为文多论及人才问题。如《默觚下·治篇九》：“古之得人家国者，先得其贤才。士心之归如此，而民心有不景（同“影”）从者乎？”《默觚下·治篇四》：“不难于立法而难得行法之人。”将人才视为关乎国家兴衰成败的关键。', '', NULL, '', 'indent', 1545390398, '5c1c58e0808ca4565c83d892', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640827, '礼记章句·中庸衍', NULL, 3, 1536, 1, 1, '王夫之', NULL, 14557, '5858e94d128fe1006b87e239', '明', 'wen', '文', '', '', '诚明相资以为体，知行相资以为用。惟其各有致功，而亦各有其效，故相资以互用。则于其相互，益知其必分矣。同者不相为用，资于异者乃和同而起功，此定理也。', '', '知行关系，即认识与实践关系，是中国哲学的基本命题。“知行”范畴最早见于《尚书·说命中》：“非知之艰，行之惟艰。”出自商王武丁与贤相傅说的“君臣对话录”，这是“知易行难”的原始表述。', '', NULL, '', 'indent', 1565352047, '5c1c5b364773f717363f747f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641181, '劝学', NULL, 1204, 13, 0, 8, '荀子', NULL, 10279, '57b902bbdf0eea006334f0d0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%8A%9D%E5%AD%A6/1055', '', '君子曰：学不可以已。
青，取之于蓝，而青于蓝；冰，水为之，而寒于水。木直中绳，輮以为轮，其曲中规。虽有槁暴，不复挺者，輮使之然也。故木受绳则直，金就砺则利，君子博学而日参省乎己，则知明而行无过矣。
故不登高山，不知天之高也；不临深溪，不知地之厚也；不闻先王之遗言，不知学问之大也。幹、越、夷、貉之子，生而同声，长而异俗，教使之然也。诗曰：「嗟尔君子，无恒安息。靖共尔位，好是正直。神之听之，介尔景福。」神莫大于化道，福莫长于无祸。
吾尝终日而思矣，不如须臾之所学也；吾尝跂而望矣，不如登高之博见也。登高而招，臂非加长也，而见者远；顺风而呼，声非加疾也，而闻者彰。假舆马者，非利足也，而致千里；假舟楫者，非能水也，而绝江河。君子生非异也，善假于物也。
南方有鸟焉，名曰蒙鸠，以羽为巢，而编之以发，系之苇苕，风至苕折，卵破子死。巢非不完也，所系者然也。西方有木焉，名曰射幹，茎长四寸，生于高山之上，而临百仞之渊，木茎非能长也，所立者然也。蓬生麻中，不扶而直；白沙在涅，与之俱黑。兰槐之根是为芷，其渐之滫，君子不近，庶人不服。其质非不美也，所渐者然也。故君子居必择乡，游必就士，所以防邪辟而近中正也。
物类之起，必有所始。荣辱之来，必象其德。肉腐出虫，鱼枯生蠹。怠慢忘身，祸灾乃作。强自取柱，柔自取束。邪秽在身，怨之所构。施薪若一，火就燥也，平地若一，水就湿也。草木畴生，禽兽群焉，物各从其类也。是故质的张，而弓矢至焉；林木茂，而斧斤至焉；树成荫，而众鸟息焉。醯酸，而蚋聚焉。故言有召祸也，行有招辱也，君子慎其所立乎！
积土成山，风雨兴焉；积水成渊，蛟龙生焉；积善成德，而神明自得，圣心备焉。故不积跬步，无以至千里；不积小流，无以成江海。骐骥一跃，不能十步；驽马十驾，功在不舍。锲而舍之，朽木不折；锲而不舍，金石可镂。蚓无爪牙之利，筋骨之强，上食埃土，下饮黄泉，用心一也。蟹六跪而二螯，非蛇鳝之穴无可寄托者，用心躁也。
是故无冥冥之志者，无昭昭之明；无惛惛之事者，无赫赫之功。行衢道者不至，事两君者不容。目不能两视而明，耳不能两听而聪。螣蛇无足而飞，鼫鼠五技而穷。《诗》曰：「尸鸠在桑，其子七兮。淑人君子，其仪一兮。其仪一兮，心如结兮！」故君子结于一也。
昔者瓠巴鼓瑟，而流鱼出听；伯牙鼓琴，而六马仰秣。故声无小而不闻，行无隐而不形。玉在山而草木润，渊生珠而崖不枯。为善不积邪？安有不闻者乎？
学恶乎始？恶乎终？曰：其数则始乎诵经，终乎读礼；其义则始乎为士，终乎为圣人，真积力久则入，学至乎没而后止也。故学数有终，若其义则不可须臾舍也。为之，人也；舍之，禽兽也。故书者，政事之纪也；诗者，中声之所止也；礼者，法之大分，类之纲纪也。故学至乎礼而止矣。夫是之谓道德之极。礼之敬文也，乐之中和也，诗书之博也，春秋之微也，在天地之间者毕矣。君子之学也，入乎耳，箸乎心，布乎四体，形乎动静。端而言，蠕而动，一可以为法则。小人之学也，入乎耳，出乎口；口耳之间，则四寸耳，曷足以美七尺之躯哉！古之学者为己，今之学者为人。君子之学也，以美其身；小人之学也，以为禽犊。故不问而告谓之傲，问一而告二谓之囋。傲、非也，囋、非也；君子如向矣。
学莫便乎近其人。礼乐法而不说，诗书故而不切，春秋约而不速。方其人之习君子之说，则尊以遍矣，周于世矣。故曰：学莫便乎近其人。
学之经莫速乎好其人，隆礼次之。上不能好其人，下不能隆礼，安特将学杂识志，顺诗书而已耳。则末世穷年，不免为陋儒而已。将原先王，本仁义，则礼正其经纬蹊径也。若挈裘领，诎五指而顿之，顺者不可胜数也。不道礼宪，以诗书为之，譬之犹以指测河也，以戈舂黍也，以錐飡壶也，不可以得之矣。故隆礼，虽未明，法士也；不隆礼，虽察辩，散儒也。
问楛者，勿告也；告楛者，勿问也；说楛者，勿听也。有争气者，勿与辩也。故必由其道至，然后接之；非其道则避之。故礼恭，而后可与言道之方；辞顺，而后可与言道之理；色从而后可与言道之致。故未可与言而言，谓之傲；可与言而不言，谓之隐；不观气色而言，谓之瞽。故君子不傲、不隐、不瞽，谨顺其身。诗曰：「匪交匪舒，天子所予。」此之谓也。
百发失一，不足谓善射；千里跬步不至，不足谓善御；伦类不通，仁义不一，不足谓善学。学也者，固学一之也。一出焉，一入焉，涂巷之人也。其善者少，不善者多，桀纣盗跖也；全之尽之，然后学者也。
君子知夫不全不粹之不足以为美也，故诵数以贯之，思索以通之，为其人以处之，除其害者以持养之。使目非是无欲见也，使耳非是无欲闻也，使口非是无欲言也，使心非是无欲虑也。及至其致好之也，目好之五色，耳好之五声，口好之五味，心利之有天下。是故权利不能倾也，群众不能移也，天下不能荡也。生乎由是，死乎由是，夫是之谓德操。德操然后能定，能定然后能应。能定能应，夫是之谓成人。天见其明，地见其光，君子贵其全也。', '《劝学》是战国时期思想家、文学家荀子创作的一篇论说文，是《荀子》一书的首篇。文章较系统地论述了学习的理论和方法，分别从学习的重要性、学习的态度以及学习的内容和方法等方面，全面而深刻地论说了有关学习的问题。全文可分四段，第一段阐明学习的重要性，第二段讲正确的学习态度，第三段讲学习的内容，第四段讲学习应当善始善终。全文说理深入，结构严谨，代表了先秦论说文成熟阶段的水平。', '君子：指有学问有修养的人。
学不可以已（yǐ）：学习不能停止。
青取之于蓝：靛青，从蓝草中取得。青，靛青，一种染料。蓝，蓼蓝，一年生草本植物，叶子含蓝汁，可以做蓝色染料。
中（zhòng）绳：（木材）合乎拉直的墨线。绳，墨线。
輮（róu）：通「煣」，古代用火烤使木条弯曲的一种工艺。
规：圆规，画圆的工具。
虽有（yòu）槁暴（pù）：即使又晒干了。有，通「又」。槁，枯。暴，同「曝」，晒干。
挺：直。
受绳：用墨线量过。
金：指金属制的刀剑等。
就砺：拿到磨刀石上去磨。砺，磨刀石。就，动词，接近，靠近。
日参（cān）省（xǐng）乎己：每天对照反省自己。参，一译检验，检查；二译同「叁」，多次。省，省察。乎，介词，己，即“于己”，介宾短语作状语后置，对自己检查、省察。
博学：广泛地学习。
知（zhì）：通「智」，智慧。
明：明达。
行无过：行为没有过错。
遗言：犹古训。
幹（hán）：同「邗」，古国名，在今江苏扬州东北，春秋时被吴国所灭而成为吴邑，此指代吴国。夷：中国古代居住在东部的民族。
貉（mò）：通「貊」，中国古代居住在东北部的民族。
「嗟尔君子」六句：引诗见《诗经·小雅·小明》。靖，安。共，通「供」。介，给予。景，大。
须臾（yú）：片刻，一会儿。
跂（qǐ）：踮起脚后跟。
博见：看见的范围广，见得广。
疾：声音宏大。
彰：明显，清楚。这里指听得更清楚。
假：凭借，利用。
舆：车厢，这里指车。
利足：脚走得快。
水：游泳。
绝：横渡。
生（xìng）非异：本性（同一般人）没有差别。生，通「性」，天赋，资质。
蒙鸠：即鹪鹩，俗称黄脰鸟，又称巧妇鸟，全身灰色*，有斑，常取茅苇一毛一毳为巢。）
滫（xiǔ）：淘米水，此引为脏水、臭水。
苕（tiáo）：芦苇的花穗。
射（yè）幹：又名乌扇，一种草本植物，根入药，茎细长，多生于山崖之间，形似树木，所以荀子称它为「木」，其实是一种草。一说「木」为「草」字之误。
「蓬生麻中」四句：草长在麻地里，不用扶持也能挺立住，白沙混进了黑土里，就会变得和土一样黑。比喻生活在好的环境里，也能成为好人。蓬，蓬草。麻，麻丛。涅，黑色染料。《集解》无「白沙在涅与之俱黑」八字，据《尚书·洪范》「时人斯其惟皇之极」《正义》引文补。
兰槐：香草名，又叫白芷，开白花，味香。古人称其苗为「兰」，称其根为「芷」。
渐（jiān）：浸。
滫（xiǔ）：泔水，已酸臭的淘米水。此引为脏水、臭水。
服：穿戴。
所渐者然也：被熏陶、影响的情况就是这样的。然，这样。
邪辟：品行不端的人。
中正：正直之士。
蠹（dù）：蛀蚀器物的虫子。
强自取柱：谓物性过硬则反易折断。柱，通「祝」（王引之说），折断。《大戴礼记·劝学》作「折」。
柔自取束：柔弱的东西自己导致约束。
构：结，造成。
畴：通「俦」，类。
质：箭靶。
的（dì）：箭靶的中心。
斤：斧子。
醯（xī）：本意指醋。
蜹（ruì）：飞虫名，属蚊类。
跬（kuǐ）：行走时两脚之间的距离，等于现在所说的一步、古人所说的半步。
步：古人说一步，指左右脚都向前迈一次的距离，等于现在的两步。
骐（qí）骥（jì）：骏马，千里马。
驽马十驾：劣马拉车连走十天也能到达。驽马，劣马。驾，古代马拉车时，早晨套一上车，晚上卸去。套车叫驾，所以这里用「驾」指代马车一天的行程。十驾就是套十次车，指十天的行程。此指千里的路程。
舍：舍弃。指放弃行路。
锲（qiè）：用刀雕刻。
镂（lòu）：原指在金属上雕刻，泛指雕刻。
蟹六跪而二螯（áo）：螃蟹有六只爪子，两个钳子。六跪，六条腿。蟹实际上是八条腿。跪，蟹脚。一说，海蟹后面的两条腿只能划水，不能用来走路或自卫，所以不能算在「跪」里面。螯，螃蟹等节肢动物身前的大爪，形如钳。
冥冥：昏暗不明的样子，形容专心致志、埋头苦干。下文「惛惛」与此同义。
昭昭：明白的样子。
螣（téng）蛇：古代传说中的一种能飞的神蛇。
鼫（shí）鼠：原作「梧鼠」，据《大戴礼记·劝学》改。鼫鼠能飞但不能飞上屋面，能爬树但不能爬到树梢，能游泳但不能渡过山谷，能挖洞但不能藏身，能奔跑但不能追过人，所以说它「五技而穷」。穷，窘困。
「尸鸠在桑」六句：引诗见《诗经·曹风·鸤鸠》。仪，通「义」。
结：结聚不散开，比喻专心一致，坚定不移。
瓠（hù）巴：楚国人，善于弹瑟。
沈：同「沉」。《集解》作「流」，据《大戴礼记·劝学》改。
伯牙：古代善于弹琴的人。
六马：古代天子之车驾用六匹马拉；此指拉车之马。
仰秣：《淮南子·说山训》高诱注：「仰秣，仰头吹吐，谓马笑也。」一说「秣」通「末」，头。
崖：岸边。
邪：同「耶」，疑问语气词。
数：术，即方法、途径，引申为「科目」。
大分：大的原则、界限。
蠕（rú）：同「蠕」，微动。
傲：浮躁。
囋：形容言语繁碎。
向：通「响」，回音。
方：通「仿」，仿效。
顺：通「训」，解释词义。
原、本：均作动词，指追溯本源。
经纬：直线与横线，这里指道路。
另辟蹊径：小路，这里泛指道路。
挈：提，拎。
裘：皮衣。
诎：通「屈」，弯曲。
顿：抖动，整理。
道：由，遵。礼宪：礼法。
舂：把谷类的皮捣掉。
黍：黍子，谷类。
飡：即「餐」，吃。
壶：古代盛食物的器皿，这里指饭。
楛：原指器物粗糙恶劣，这里是恶劣的意思，即指不合礼义。
争气：指意气用事。
致：极致，最高的境界。
隐：有意隐瞒。
瞽：盲目从事。
谨顺其身：指君子谨慎修养自己，做到不傲、不隐、不瞽，待人接物恰到好处。
「匪交匪舒」二句：语本《诗经·小雅·采菽》。匪，非，不。交，通「侥」，侥幸急躁。舒，缓，慢。予，通「与」，赞成。
伦：与「类」同义，指类别。
桀纣：夏朝和商朝的亡国之君。
盗跖：古代一个名叫跖的大盗。
数：数说，与「诵」意义相近。
是：指全而粹合乎礼仪之美。
五声：宫、商、角、徵、羽，这里指美妙的音乐。
五味：甜、酸、苦、辣、咸，这里指美味。
应：指对外界事物的应变能力。
成人：全人，完美的人。', '君子说：学习是不可以停止的。
靛青是从蓝草里提取的，可是比蓝草的颜色更深；冰是水凝结而成的，却比水还要寒冷。木材直得符合拉直的墨线，用煣的工艺把它制成车轮，那么木材的弯度就合乎标准了。即使又被风吹日晒而干枯了，木材也不会再挺直，是因为经过加工使它成为这样的。所以木材用墨线量过再经辅具加工就能取直，刀剑在磨刀石上磨过就能变得锋利，君子广博地学习并且每天检验反省自己，那么他就会智慧明达而且行为没有过失了。
因此，不登上高山，就不知天多么高；不面临深涧，就不知道地多么厚；不懂得先代帝王的遗教，就不知道学问的博大。干、越、夷、貉的孩子，刚生下来啼哭的声音是一样的，而长大后风俗习性却不相同，这是教育使之如此。《诗经》上说：「你这个君子啊，不要总是贪图安逸。恭谨对待你的本职，爱好正直的德行。神明听到这一切，就会赐给你洪福祥瑞。」精神修养没有比受道德熏陶感染更大了，福分没有比无灾无祸更长远了。
我曾经整天思索，却不如片刻学到的知识多；我曾经踮起脚远望，却不如登到高处看得广阔。登到高处招手，胳膊没有加长，可是别人在远处也能看见；顺着风呼叫，声音没有变得洪亮，可是听的人在远处也能听得很清楚。借助车马的人，并不是脚走得快，却可以达到千里之外；借助舟船的人，并不善于游泳，却可以横渡江河。君子的资质秉性跟一般人没有不同，只是君子善于借助外物罢了。
南方有一种叫「蒙鸠」的鸟，用羽毛作窝，还用毛发把窝编结起来，把窝系在嫩芦苇的花穗上，风一吹苇穗折断，鸟窝就坠落了，鸟蛋全部摔烂。不是窝没编好，而是不该系在芦苇上面。西方有种叫「射干」的草，生长在高山之上，只有四寸高，却能俯瞰百里之遥，不是草能长高，而是因为它长在了高山之巅。蓬草长在麻地里，不用扶持也能挺立住，白沙混进了黑土里，就再不能变白了，兰槐的根叫香艾，一但浸入臭水里，君子下人都会避之不及，不是艾本身不香，而是被浸泡臭了。所以君子居住要选择好的环境，交友要选择有道德的人，才能够防微杜渐保其中庸正直。
事情的发生都是有起因的，荣辱的降临也与德行相应。肉腐了生蛆，鱼枯死了生虫，懈怠疏忽忘记了做人准则就会招祸。太坚硬物体易断裂，太柔弱了又易被束缚，与人不善会惹来怨恨，干柴易燃，低洼易湿，草木丛生，野兽成群，万物皆以类聚。所以靶子设置好了就会射来弓箭，树长成了森林就会引来斧头砍伐，树林繁茂荫凉众鸟就会来投宿，醋变酸了就会惹来蚊虫，所以言语可能招祸，行为可能受辱，君子为人处世不能不保持谨慎。
堆积土石成了高山，风雨从这里兴起；汇积水流成为深渊，蛟龙从这儿产生；积累善行养成高尚的道德，精神得到提升，圣人的心境由此具备。所以不积累一步半步的行程，就没有办法达到千里之远；不积累细小的流水，就没有办法汇成江河大海。骏马一跨跃，也不足十步远；劣马连走十天，它的成功在于不停止。如果刻几下就停下来了，那么腐朽的木头也刻不断。如果不停地刻下去，那么金石也能雕刻成功。蚯蚓没有锐利的爪子和牙齿，强健的筋骨，却能向上吃到泥土，向下喝到地下的泉水，这是由于它用心专一。螃蟹有六条腿，两个蟹钳，但是没有蛇、鳝的洞穴它就无处藏身，这是因为它用心浮躁。
因此没有刻苦钻研的心志，学习上就不会有显著成绩；没有埋头苦干的实践，事业上就不会有巨大成就。在歧路上行走达不到目的地，同时事奉两个君主的人，两方都不会容忍他。眼睛不能同时看两样东西而看明白，耳朵不能同时听两种声音而听清楚。螣蛇没有脚但能飞，鼫鼠有五种本领却还是没有办法。《诗经》上说：「布谷鸟筑巢在桑树上，它的幼鸟儿有七只。善良的君子们，行为要专一不偏邪。行为专一不偏邪，意志才会如磐石坚。」所以君子的意志坚定专一。
古有瓠巴弹瑟，水中鱼儿也浮出水面倾听，伯牙弹琴，拉车的马会停食仰头而听。所以声音不会因为微弱而不被听见，行为不会因为隐秘而不被发现。宝玉埋在深山，草木就会很润泽，珍珠掉进深渊，崖岸就不会干枯。行善可以积累，哪有积善成德而不被广为传诵的呢？
学习究竟应从何入手又从何结束呢？答：按其途径而言，应该从诵读《诗》、《书》等经典入手到《礼经》结束；就其意义而言，则从做书生入手到成为圣人结束。真诚力行，这样长期积累，必能深入体会到其中的乐趣，学到死方能后已。所以学习的教程虽有尽头，但进取之愿望却不可以有片刻的懈怠。毕生好学才成其为人，反之又与禽兽何异？《尚书》是政事的记录；《诗经》是心声之归结；《礼经》是法制的前提、各种条例的总纲，所以要学到《礼经》才算结束，才算达到了道德之顶峰。《礼经》敬重礼仪，《乐经》讲述中和之声，《诗经》《尚书》博大广阔，《春秋》微言大义，它们已经将天地间的大学问都囊括其中了。
君子学习，是听在耳里，记在心里，表现在威仪的举止和符合礼仪的行动上。一举一动，哪怕是极细微的言行，都可以垂范于人。小人学习是从耳听从嘴出，相距不过四寸而已，怎么能够完美他的七尺之躯呢？古人学习是自身道德修养的需求，今人学习则只是为了炫耀于人。君子学习是为了完善自我，小人学习是为了卖弄和哗众取宠，将学问当作家禽、小牛之类的礼物去讨人好评。所以，没人求教你而去教导别人叫做浮躁；问一答二的叫啰嗦；浮躁啰嗦都是不对的，君子答问应象空谷回音一般，不多不少、恰到好处。
学习没有比亲近良师更便捷的了。《礼经》《乐经》有法度但嫌疏略；《诗经》《尚书》古朴但不切近现实；《春秋》隐微但不够周详；仿效良师学习君子的学问，既崇高又全面，还可以通达世理。所以说学习没有比亲近良师更便捷的了。
崇敬良师是最便捷的学习途径，其次就是崇尚礼仪了。若上不崇师，下不尚礼，仅读些杂书，解释一下《诗经》《尚书》之类，那么尽其一生也不过是一介浅陋的书生而已。要穷究圣人的智慧，寻求仁义的根本，从礼法入手才是能够融会贯通的捷径。就像弯曲五指提起皮袍的领子，向下一顿，毛就完全顺了。如果不究礼法，仅凭《诗经》《尚书》去立身行事，就如同用手指测量河水，用戈舂黍米，用锥子到饭壶里取东西吃一样，是办不到的。所以，尊崇礼仪，即使对学问不能透彻明了，不失为有道德有修养之士；不尚礼仪，即使明察善辩，也不过是身心散漫无真实修养的浅陋儒生而已。
如果有人前来向你请教不合礼法之事，不要回答；前来诉说不合礼法之事，不要去追问；在你面前谈论不合礼法之事，不要去参与；态度野蛮好争意气的，别与他争辩。所以，一定要是合乎礼义之道的，才给予接待；不合乎礼义之道的，就回避他；因此，对于恭敬有礼的人，才可与之谈道的宗旨；对于言辞和顺的人，才可与之谈道的内容；态度诚恳的，才可与之论及道的精深义蕴。所以，跟不可与之交谈的交谈，那叫做浮躁；跟可与交谈的不谈那叫怠慢；不看对方回应而随便谈话的叫盲目。因此，君子不可浮躁，也不可怠慢，更不可盲目，要谨慎地对待每位前来求教的人。《诗经》说：「不浮躁不怠慢才是天子所赞许的。」说的就是这个道理。
射出的百支箭中有一支不中靶，就不能算是善射；驾驭车马行千里的路程，只差半步而没能走完，这也不能算是善驾；对伦理规范不能融会贯通、对仁义之道不能坚守如一，当然也不能算是善学。学习本是件很需要专心致志的事情，学一阵又停一阵那是市井中的普通人。好的行为少而坏的行为多，桀、纣、拓就是那样的人。能够全面彻底地把握所学的知识，才算得上是个学者。
我们已经知道了学得不全不精就不算是完美，所以要常用朗读和训释去融会贯通，用思考和探索去理解，用寻师访友来把握，从而达到排除所有干扰去潜心修炼。使眼不再看不该看的、耳不再听不该听的，嘴不再说不该说的，心不再想不该想的，以达到完全醉心于学习的理想境地。如同眼好五色，耳好五声，嘴好五味那样，一门心思就只想着如何造福天下。如果做到了这般地步，那么，在权利私欲面前你就不会有邪念，人多势众你也不会屈服的，天下万物都不能动摇你的信念。活着是如此，到死也不变。这就叫做有德行、有操守。有德行和操守，才能做到坚定不移，有坚定不移然后才有随机应变。能做到坚定不移和随机应变，那就是完美的人生了。到那时上天会为你显现它的光明，大地会为你显现它的广阔，君子最应该珍惜的就是自身德行的完美了', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3a4", "shortContent": "这段话是《劝学》的开篇，它常常作为《荀子》的著名段落被选入中学语文课本进行讲解。若从义理角度来看，它几乎可说是《劝学》篇乃至整部《荀子》中最重要的一段话。战国时期儒家学派的两大传承者，一为战国中叶的孟子，他认为人性本善，只要将人与生俱来的恻隐之心施及大众，就能称为“仁心”，有“仁心”，则人皆可为尧舜；另一位则是战国末的荀子，他提出了人性本恶的观点，认为人天性本能中就有趋利、贪欲、好色之心，如果不加...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3a5", "shortContent": "在《庄子·秋水》中有一个“望洋兴叹”的寓言：黄河之神河伯见百川融汇于自身，泾流庞大，两岸之间，无法互相分辨景物，于是欣欣然以为天下美景都在自己这里，顺流而东，到了北海，一望天际，不见水端，才醒悟到自己实是井底之蛙，未见大道，有所叹悟。北海之神若因此才说它“可与语大理矣”。意为可以对河伯谈论大道了。这段“望洋兴叹”的寓言旨意与荀子所发“不知天高地厚”之论非常相似，但庄子更注重发挥天人合一的哲理，荀子...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3a6", "shortContent": "这几句行文近似《孟子·滕文公下》：“富贵不能淫，贫贱不能移，威武不能屈，此之谓大丈夫。”孟子所谓不淫、不移、不屈的“大丈夫之道”，实际也与荀子所说的“君子之德操”相去不远。但凡学习者有所学即有所获，日积月累，学习心得转化为坚定不移的意志与信念，且无论死生富贵，它们在学者日常言行思想中都会得以贯彻不辍，这即是荀子“君子德操”之义。这种因学习所得，发自内心而施于外界的“德操”，不会被威权禄利倾覆；不会...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3a7", "shortContent": "这句名言的大意是说，人的修身，必须时时刻刻以“礼”为准则，如果不由“礼”，不是目中无人、狂妄自大，就是孤陋寡闻、庸俗不堪。\n\n《说文》曰：“礼，履也。所以事神致福也。”段注曰：“履，足所依也。引申之凡所依皆曰履。”“礼”本是原始巫术图腾文明的产物。中国文明的可贵处在于，“把本来是维系氏族社会的图腾歌舞、巫术礼仪，转化为自觉人性和心理本体的建设。”（李泽厚《华夏美学》）所以孔子才会说：“克己复礼，天...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3a8", "shortContent": "“礼”之一字，在先秦儒家典籍中多有涉及。孔子说：“不学礼，无以立。”有子说：“礼之用，和为贵……有所不行，知和而和，不以礼节之，亦不可行也。”孟子则说：“辞让之心，礼之端也。”其义或为“礼法”，或为“礼节”，或作“秩序制度”，或作“和谐节制”，在不同场合下义理也各有不同。\n\n荀子认为人在日常生活中的一切行为，包括衣食、起居、出行等都应依礼而行，依礼而节，否则便会使身躯不适染病，生命不得安乐。举例而...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3a9", "shortContent": "古代社会的信息传递能力极其低下，掌握知识的途径除了向贤师求教学习，阅读典籍效法古人之外，最根本的就是依靠自身的社会经历，多听多看，乃至多思多想，通过自己的阅历与识见获得新的知识与技能。《论语·为政》载：“子张学干禄。子曰：‘多闻阙疑，慎言其余，则寡尤；多见阙殆，慎行其余，则寡悔。言寡尤，行寡悔，禄在其中矣。’”又《论语·述而》载：“子曰：‘盖有不知而作之者，我无是也。多闻，择其善者而从之；多见而识...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3ab", "shortContent": "《诗·小雅·鱼丽》云：“物其有矣，唯其时矣。”君子所崇尚的行为、言语、名望，都须与自身所处时代潮流相适应，并且与自己的志向操守相契合，如若不然，则不取也。荀子认为，殷商时申徒狄恨道不行而负石投河，可称坚贞之士；战国时名家学派提出卵有毛、鸡三足、火不热、白马非马等命题，竞相诡辩争论，谈说无穷，可称善辩之人；夏商二代的暴君桀、纣，名声昭如日月，能与五帝并而传世。这些人的行为、言语、名望都是一般人难以企...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3ac", "shortContent": "《易·乾卦·文言》：“子曰：同声相应，同气相求；水流湿，火就燥，云从龙，风从虎；圣人作而万物睹；本乎天者亲上，本乎地者亲下，则各从其类也。”此盖为荀子所本。《易·系辞上》又有“方以类聚，物以群分”，今人俗语“物以类聚，人以群分”，亦本于此。而《楚辞·渔父》亦有“屈原曰：‘吾闻之：新沐者必弹冠，新浴者必振衣。安能以身之察察受物之汶汶者乎？’”几与《荀子》此语相同。现代人在洗浴之后会换上新衣，并且小心...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3af", "shortContent": "这是荀子的“耻”论。\n\n应该说，儒家是很看重“耻”的。“好学近乎知，力行近乎仁，知耻近乎勇。”（《礼记·中庸》）“恭近于礼，远耻辱也。”（《论语·学而》）“道之以政，齐之以刑，民免而无耻；道之以德，齐之以礼，有耻且格。”（《论语·为政》）“声闻过情，君子耻之。”（《孟子·离娄下》）“人不可以无耻，无耻之耻，无耻矣。”（《孟子·尽心上》）这样谈“耻”的言论在儒家经典中几乎俯拾即是。\n\n那么，究竟什么...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3b1", "shortContent": "人是什么（What is human）？这个终极问题，从古至今的一切哲人都在回答。有人说，人是神创造的，是神的奴仆，灵魂可以不朽（如基督教）。也有人认为，人是高级动物，虽然高级，也只是一次性消费，人死如灯灭（如当代盛行的唯物主义）。围绕这两种回答，宗教与科学展开了长期的论战。可以说，当今人类文化的一切冲突，都跟人们在这个问题上的看法不一致有关。\n\n那么，有没有跳出这两种视域的第三种回答呢？\n\n中国...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "647177df5e6bb82b8cf93d78", "shortContent": "本文选自《荀子·劝学》。“劝学”的“劝”意为劝勉、鼓励，这是一篇用来劝导人们进行学习的文章。\n与孟子的“性善”说相反，荀子认定人性生来是“恶”的，要通过后天的学习才能为善，注重环境与教育对人的影响。因此，荀子格外重视学习的作用。\n开头即开宗明义：“学不可以已。”荀子认为，学习决不可以停止。以下各段分别论述学习的作用、方法与态度，各有侧重，却又都指向“学不可以已”这个中心，使得文章结构严谨而有条理，...", "authors": ["徐卉"], "pressName": "上海辞书出版社"}]', '', 'indent', 1549821647, '5c5ff63ea91c930054dbd230', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640828, '论衡 · 别通', NULL, 22, 5, 1, 1, '王充', NULL, 36800, '589c4939128fe1005806fa23', '汉', 'wen', '文', '', '', '人目不见青黄曰盲，耳不闻宫商曰聋，鼻不知香臭曰痈。痈、聋与盲，不成人者也。人不博览者，不闻古今，不见事类，不知然否，犹目盲、耳聋、鼻痈者也。儒生不览，犹为闭暗，况庸人无篇章之业，不知是非，其为闭暗甚矣！此则土木之人，耳目俱足，无闻见也。涉浅水者见虾，其颇深者察鱼鳖，其尤甚者观蛟龙。足行迹殊，故所见之物异也。入道浅深，其犹此也。浅者则见传记谐文；深者入圣室观秘书，故入道弥深，所见弥大。人之游也，必欲入都，都多奇观也。入都必欲见市，市多异货也。百家之言，古今行事，其为奇异，非徒都邑大市也。游于都邑者心厌，观于大市者意饱，况游于道艺之际哉！', '', '青黄：指青色与黄色。这里泛指颜色。
宫商：古代以宫、商、角（jué决）、徵（zhǐ指）、羽为五音，相当于简谱中的“1”、“2”、“3”、“5”、“6”、五个音阶。宫商在这里泛指声音。
痈：毒疮。这里指失去嗅觉的鼻病。
递修本“览”前有“博”字，正与上文“人不博览者”义同。可从。
无篇章之业：没有文章的学业，意思是没有读过书。
迹：足迹。这里指到过的地方。
入：进入。这里是掌握的意思。
入圣室：到圣人的室内。这里比喻对经书了解得很精深。观秘书：读罕见的书籍。这里比喻博通古今。
奇异：奇闻异物。这里是非同一般的意思。
游：这里指博览，钻研。', '人的眼睛看不见颜色叫盲，耳朵听不到声音叫聋，鼻子不知道香臭叫痈。有痈、聋和盲，就成不了健全的人。人不博览群书，不通古今，不能识别各种事物，不懂得是非，就像眼瞎、耳聋、鼻痈的人一样。儒生不博览群书，尚且是闭塞不明，何况俗人没有读过书，不知道是非，他们就更是闭塞不明了！这就是些泥塑木雕的人，耳朵眼睛都齐全，就是听不见看不见。淌过浅水的人能看见虾子，淌过稍微深水的人能看见鱼鳖，到过深渊的人能看见蛟龙。脚走的地方不同，所以见到的东西也不一样。人掌握先王之道的深浅，那更是这样。浅薄的人就看些传记小说一类的东西；深厚的人就要进到圣人室内读罕见的书籍，因此掌握的先王之道更加深刻，见闻更加广博。人去游玩，肯定想去都市，因为都市有很多新奇的东西看。进都市一定想去看市场，因为市场上有很多不同的货物。各家的学说，是些古往今来的事情，它们非同一般，不只是都市大市场可比。游都市的人心里感到满足，逛大市场的人心里感到满意，何况是博览、钻研经书的时候呢！', NULL, '', 'indent', 1545391376, '5c1c5caf1579a3005fceee2a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640829, '尹师鲁墓志铭', NULL, 18, 1229, 1, 1, '欧阳修', NULL, 10018, '57b98d625bbb50005347ace1', '宋', 'wen', '文', 'https://baike.baidu.com/item/%E5%B0%B9%E5%B8%88%E9%B2%81%E5%A2%93%E5%BF%97%E9%93%AD/947925?fr=aladdin', '', '尹师鲁墓志铭
师鲁，河南人，姓尹氏，讳洙。然天下之士识与不识皆称之曰师鲁，盖其名重当世。而世之知师鲁者，或推其文学，或高其议论，或多其材能。至其忠义之节，处穷达，临祸福，无愧于古君子，则天下之称师鲁者未必尽知之。
师鲁为文章，简而有法。博学强记，通知今古，长于《春秋》。其与人言，是是非非，务穷尽道理乃已，不为苟止而妄随，而人亦罕能过也。遇事无难易，而勇于敢为，其所以见称于世者，亦所以取嫉于人，故其卒穷以死。
师鲁少举进士及第，为绛州正平县主簿、河南府户曹参军、邵武军判官。举书判拔萃，迁山南东道掌书记、知伊阳县。王文康公荐其才，召试，充馆阁校勘，迁太子中允。天章阁待制范公贬饶州，谏官、御史不肯言。师鲁上书，言仲淹臣之师友，愿得俱贬。贬监郢州酒税，又徙唐州。遭父丧，服除，复得太子中允、知河南县。赵元昊反，陕西用兵，大将葛怀敏奏起为经略判官。师鲁虽用怀敏辟，而尤为经略使韩公所深知。其后诸将败于好水，韩公降知秦州，师鲁亦徙通判濠州。久之，韩公奏，得通判秦州。迁知泾州，又知渭州，兼泾原路经略部署。坐城水洛与边臣略异议，徙知晋州。又知潞州，为政有惠爱，潞州人至今思之。累迁官至起居舍人，直龙图阁。
师鲁当天下无事时独喜论兵，为《叙燕》、《息戍》二篇行于世。自西兵起，凡五六岁，未尝不在其间，故其论议益精密，而于西事尤习其详。其为兵制之说，述战守胜败之要，尽当今之利害。又欲训土兵代戍卒，以减边用，为御戎长久之策，皆未及施为。而元昊臣，西兵解严，师鲁亦去而得罪矣。然则天下之称师鲁者，于其材能，亦未必尽知之也。
初，师鲁在渭州，将吏有违其节度者，欲按军法斩之而不果。其后吏至京师，上书讼师鲁以公使钱贷部将，贬崇信军节度副使，徙监均州酒税。得疾，无医药，舁至南阳求医。疾革，隐几而坐，顾稚子在前，无甚怜之色，与宾客言，终不及其私。享年四十有六以卒。
师鲁娶张氏，某县君固。有兄源，字子渐，亦以文学知名，前一岁卒。师鲁凡十年间三贬官，丧其父，又丧其兄。有子四人，连丧其三。女一适人固，亦卒。而其身终以贬死。一子三岁，四女未嫁，家无余资，客其丧于南阳不能归。平生故人无远迩皆往赙之，然后妻子得以其柩归河南，以某年某月某日葬于先茔之次。
余与师鲁兄弟交，尝铭其父之墓矣固，故不复次其世家焉钞。铭曰：
藏之深，固之密。石可朽，铭不灭。', '《尹师鲁墓志铭》是北宋文学家欧阳修为好友尹师鲁所作的墓志铭。作者分别写尹师鲁的志节、文章、历官、论兵才略、贬官病卒，最后写石碑可以腐朽，而其功绩不朽。从而颂扬他的文学、议论和才能，着重赞颂他的忠义节操。全文感情真挚，文字凝练含蓄，耐人寻味。', '尹师鲁：尹洙（1001—1047年），字师鲁，河南人，世称河南先生。为文简古，曾与欧阳修等倡为古文。
墓志铭：古代的一种文体，刻在石上，埋在墓内，或立在墓旁。一般包括“志”和“铭”两部分。
河南：河南府，治所在今河南洛阳市。
讳（huì）：即名，专用于对所尊敬的人物不得不称其名时。
推：推崇。
多：称赞。
处穷达，临祸福：在人生道路上或困顿或顺利，或面临祸事或得到幸福。
简而有法：指作文时能像孔子修《春秋》那样，对素材有所取舍和剪裁。叙事时善于在含蓄中寓褒贬之意。
强记：记忆力强。
通知今古：指知识面宽广，贯通古今。
是是非非：肯定正确的，否定错误的。
不为苟止而妄随：绝不轻易放弃自己所坚持的东西，也决不盲目地附和别人。
其所以见称于世者，亦所以取嫉于人，故其卒穷以死：指尹师鲁受到世人称赞的那些特出的品行和才干，又使他受到一些小人嫉妒和怨恨，导致他最终困顿而死。
绛（jiàng）州正平县：故城在今山西新绛县西南。
邵（shào）武军：宋军州名，治所在今福建邵武市。
书判拨萃（cuì）：书判工作优等，这是当时州县地方长官荐举佐吏的考语。
伊阳县：今河南嵩县。
王文康公：即王曙，当时任西京留守、河南府知府。
馆阁校勘（kān）：官名，为翰林院三馆的属官之一。
太子中允：官名，为太子东宫属官之一。
天章阁待制范公贬饶州，谏官、御史不肯言。师鲁上书，言仲淹臣之师友，愿得俱贬：指宋仁宗景祐三年（1036年）范仲淹与宰相吕夷简论争、范被贬饶州，尹师鲁、余靖、欧阳修等人亦因支持范而被贬事。
郢（yǐng）州：宋州名，治所在今湖北钟祥。
唐州：宋州名，州治在今河南唐河县。
赵元昊反：指宋仁宗宝元元年（1038年）西夏元吴建国称帝。
葛怀敏：宋大将，时任泾愿路马步军副总管兼泾原、秦凤两路经略安抚副使。
辟：召请。
韩公：指韩琦，当时任陕西安抚使。
好水：指好水川，即今甜水河，源出宁夏隆德东六盘山。西流至甘肃静宁注入苦水河。
秦州：宋州名，州治在今甘肃天水市。
濠（háo）州：宋州名，州治在今安徽凤阳市东北。
泾（jīng）州：宋州名，州治在今甘肃泾县。
渭州：宋州名，州治在今甘肃平凉市西。
晋州：宋州名，州治在今山西临汾市。
潞（lù）州：宋州名，州治在今山西长治市。
《叙燕》、《息戊》：尹师鲁的两篇军事论文，今存干莫文集《河南集》中，《宋史·尹洙传》亦全文引录。
土兵：即乡兵，宋代训练当地丁壮保护地方的一种兵制。
御戎：抵御敌兵。
元昊臣：指元昊于宋仁宗庆历四年（1044年）五月向宋朝称臣。
得罪：即下文所述其属下告发他“以公使钱贷部将”事。
将吏有违其节度者，欲按军法斩之而不果：指陕西路将领刘沪、董士廉因不服从尹师鲁的军令，被尹命令狄青逮捕下狱事。
吏：指董士廉。
均州：宋州名，州治在今湖北均县。
舁（yú）：扛，抬。
南阳：即邓州，州治为今河南南阳市。
疾革：病重。
隐几：靠着桌子。
县君：宋代中级官员的妻子和母亲的封诰。
适人：出嫁。
无远迩（ěr）：无论远近。迩：近。
赙（fù）：送钱财帮助别人办理丧事。
先茔（yíng）：祖先的坟墓。
兄弟交：交情有如骨肉兄弟。
铭其父之墓：为他的父亲写过墓志铭。
不复次其世家：不再重复叙述他的家世。', '师鲁是河南人，他姓尹名叫洙。可是天下的士人不管认不认识他都管他叫师鲁，他的名声很为当代人重视。那些深知师鲁的人，有的人崇拜的是他的文学才能，有的人看重的是他看问题很独到，有的人赞美的是他的才能。论及他的忠义之节，无论处在逆境和顺境，面临的是祸福喜悲他身上都有古代君子的风度，然而那些称颂师鲁的人却不一定知道这些东西。
师鲁写文章，语言简洁而有章法。他博学多识，论古及今无所不通，他很擅长《春秋》。当他和别人谈论时，对于正确的就给予肯定，错误的就给予批判，一定要把道理讲明白才停止，从不盲目听从别人所说的，而且没有几个人能超过他。不论遇上什么事情，他都能敢作敢当，这也是他受到世人称道的缘由，也是遭到某些人嫉恨的原因，因此他才会穷困潦倒而终。
师鲁很年轻的时候就考中进士，担任绛州正平县主簿、河南府户曹参军、邵武军判官。后来调任为山南东道掌书记的官职、做伊阳县知县。王文康公喜爱他的才能举荐他，皇帝召见面试后，任命他担任馆阁校勘，后来又任命他做太子中允。天章阁待制范仲淹遭到贬谪，调任饶州，谏官、御史都不想为他说话，求情。师鲁却毅然上书，说范仲淹和他曾经是师友，希望一块接受贬谪。于是师鲁被贬监管郢州酒税后来又调到唐州。在这个时候，他的父亲去世了，等到守孝期满，他又恢复做太子中允、河南知县的官职。西夏趟元吴造反，陕西一带战争风起云涌，大将葛怀敏上奏朝廷请求让师鲁担任经略判官。师鲁见解敏锐，尤其为经略便韩公所赏识，在好水这个地方大家打了败仗，韩公被贬官到了秦州做知州，师鲁被贬谪到濠州做通判。很长时间之后，韩公上奏朝廷，师鲁随后调到秦州做通判。后来又调到泾州担任知州，在渭州担任知州，同时还兼任泾源路经略部署的官职。他因在水洛时与边将意见不合，又被调往晋州任职，后又到潞州任知州，在政务上他广施仁爱之心，潞州人到现在还念他的好。后来累官升至起居舍人，掌管龙图阁。
师鲁在国家安定的时候对军事情有独钟，他的《叙燕》、《息戍》两篇文章在当时很有名气。师鲁的议论非常精密，对子军事也了解得很详细。他很看重军事备战的重要性，论述了作战、守卫的成败的要义，这些在当时是很有价值的。他还想训练土兵让他们来代替戍守的士卒，用这种方式减少边境的开支，把这作为抵御外敌的长远计策，可是没有被采纳。等到元吴臣服，西部的边防士兵的戒备被解除了，师鲁也离职了，他的言论触及了权臣的利益。在这样的情况下，那些称赞师鲁的人，对于师鲁的才能，也不可能完全了解啊。
在最初的时候，师鲁调任渭州，有不听他管理违规乱法的官吏，他想按军法处置他们，但是没有实现。这件事后，一些官吏到京师向朝廷上书控告师鲁，说他挪用公款借给部下，师鲁遭到贬职，做崇信军节度服使，后来又调任监管均州酒税。后来他病了，没有药物可以治病，就被抬到南阳求医。等到他好了，靠着几案坐着，看到幼子在眼前，丝毫没有疼爱的表现，和宾客谈话始终不涉及自己的私事。他四十六岁的时候就去世了。
师鲁的妻子张氏是某县县君，他的兄长尹源，字子渐，也以文学而出名，比他早一年去世。师鲁在这几十年间，三次被贬官，先是死了父亲，后来又死了兄长。他的四个儿子，也连着死了三个。一个女儿嫁人了，现在也已死了。他自己也因为被贬而去世。还有一个儿子才三岁，有四个女儿未出嫁，家里没有什么值钱的东西，他死在南阳没办法返回故乡。以前的朋友不管路途的远近都拿出钱来帮忙处理他的后事，这样其妻子才能将他的灵柩送回河南。某年某月某日，将他葬在先人的坟墓旁边。
我与师鲁称兄道弟，也曾给他父亲写墓志铭，因此他的墓志铭我也代写了。铭曰：
墓藏得很深，也很牢固，石头也许会朽烂，但铭不会被淹灭。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1f603048e64fbd9cd19", "shortContent": "欧阳修一踏上仕途，便结识了比他大六岁的尹洙，他曾在《记旧本韩文后》中说过：“官于洛阳，而尹师鲁之徒皆在，遂相与作为古文。”应该说尹洙古峭凝练的文风，以及他的“大抵文字所忌者，格弱字冗”（《湘山野录》卷中引）的见解，对欧阳修都是很有启发的。两人志趣相投，情如兄弟，偶一小别，便生悬念。这从欧阳修的诗中可以看出：“追怀洛中俊，已动思归操。为别未期月，音尘一何杳。因书写行役，聊以为君导。”（《代书寄尹十一...", "authors": ["赵其钧"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f935914587d02f66f7a", "shortContent": "这是一则原于奇人奇事而转变为怪异的故事，写得很生动。\n赵不易的妻子有奇疾，不吃熟肉，专吃生肉。尽管她的生活起居如常，但却与丈夫别室而居。赵调官湖南后，妻子的病愈甚，供他使令的婢女，一连三个都渐渐黄瘦而死。送肉给她，从正门送去，她不受，从后园送去才吃。后来赵官广东封州，赵妻竟“白昼化为虎，腾吼而出”。\n后来则是赵的同事对赵妻的奇事的有关忆述：赵妻是太监的女儿，虽然貌美，却未尝怀孕；性好洁，丈夫坐过的...", "authors": ["龙潜庵"], "pressName": "上海辞书出版社"}, {"bookId": "646a05a345e4710056dab21f", "bookTitle": "欧阳修诗文鉴赏辞典（珍藏本）", "articleId": "646cc2c65b7b0d4f45339f20", "shortContent": "欧阳修一踏上仕途，便结识了比他大六岁的尹洙，他曾在《记旧本韩文后》中说过：“官于洛阳，而尹师鲁之徒皆在，遂相与作为古文”。应该说尹洙古峭凝练的文风，以及他的“大抵文字所忌者，格弱字冗”（《湘山野录》卷中引）的见解，对欧阳修都是很有启发的。两人志趣相投，情如兄弟，偶一小别，便生悬念。这从欧阳修的诗中可以看出：“追怀洛中俊，已动思归操。为别未期月，音尘一何杳。因书写行役，聊以为君导。”（《代书寄尹十一...", "authors": ["赵其钧"], "pressName": "崇文书局"}]', '明茅坤《唐宋八大家文钞》：欧公最得意友，亦欧公最着意之文。
清方苞《方苞集》：欧公志诸朋友，悲思激宕，风格最近太史公。
清何焯《义门读书记》：谨严而凄婉。
清方东树《昭昧詹言》：欧公情韵幽折，往反咏唱，令人低回欲绝，一唱三叹，而有遗音，如啖橄榄，时有余味。', 'indent', 1545391488, '5c1c5d06808ca4565c8411f1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640830, '二程遗书 · 伊川先生语', NULL, 33, 7, 2, 1, '程颐', NULL, 31734, '5858f90ab123db00658e1775', '宋', 'wen', '文', '', '', '为学之道，必本于思。思则得之，不思则不得也。故《书》曰：“思曰睿，睿作圣”。思所以睿，睿所以圣也。　　
不深思则不能造于道；不深思而得者，其得易失。然而学者有无思虑而得者，何也？曰：以无思无虑而得者，乃所以深思而得之也；以无思无虑为不思而自以为得者，未之有也。', '', '', '', NULL, '', 'indent', 1545392098, '5c1c5f6e808ca400733494bc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640832, '论衡 · 实知', NULL, 16, 5, 1, 1, '王充', NULL, 36800, '589c4939128fe1005806fa23', '汉', 'wen', '文', '', '', '人才有高下，知物由学。学之乃知，不问不识。子贡曰：「夫子焉不学，而亦何常师之有？」孔子曰：「吾十有五而志乎学。」五帝、三王，皆有所师。曰：「是欲为人法也。」曰：精思亦可为人法，何必以学者？事难空知，贤圣之才能立也。所谓神者，不学而知。所谓圣者，须学以圣。以圣人学，知其非圣。天地之间，含血之类，无性知者。狌狌知往，鳱鹊知来，禀天之性，自然者也。', '', '夫子：这里指孔子。
皆有所师：《韩诗外传·五》：「黄帝学乎大填，颛顼学乎录图，帝喾学乎赤松子，尧学乎尹寿，舜学乎务成子附，禹学乎西王国，汤学乎贷子相，文王学乎锡畴子斯，武王学乎太公。」圣：据文意疑当为「神」字。
鳱（gān）鹊：喜鹊。
禀天之性：王充认为万物的本性都是承受上天自然而然施放的气而形成的，所以这里这样说。', '人的才智有高低之分，认识事物要通过学习纔行。通过学习纔能知道，不请教别人就不能认识事物。子贡说：「我的老师是无处不学习的，可是又何必要有个固定的老师呢？」孔子说：「我十五岁就有志于学问。」五帝、三王，都是有所师法的。有人说：「这是为了给人们做榜样。」我说：精心思考也可以作为人们的榜样，为什么一定要以勤学做榜样呢？事理很难凭空思考而得知，贤圣的才能却可以通过学习而具备。那些称为「神」的，是不学而知的；那些称为「圣」的，必须通过学习纔能成为圣。因为圣人也需要学习，所以知道他并不是神。天地之间，含有血气的动物，没有天生就知道一切的。猩猩知道过往人的姓名，喜鹊知道未来的喜事，因为它们承受了天的本性，自然就是如此的。', NULL, '', 'indent', 1545392379, '5c1c609467f356005fd50ade', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640833, '论衡 · 超奇篇', NULL, 15, 5, 1, 1, '王充', NULL, 36800, '589c4939128fe1005806fa23', '汉', 'wen', '文', '', '', '通书千篇以上，万卷以下，弘畅雅闲，审定文读，而以教授为人师者，通人也。杼其义旨，损益其文句，而以上书奏记，或兴论立说，结连篇章者，文人、鸿儒也。好学勤力，博闻强识，世间多有；著书表文，论说古今，万不耐一。然则著书表文，博能所能用之者也。入山见木，长短无所不知；入野见草，大小无所不识。然而不能伐木以作室屋，采草以和方药，此知草木所不能用也。夫通人览见广博，不能掇以论说，此为匿生书主人，孔子所谓“诵《诗》三百，授之以政，不达者也，与彼草木不能伐采，一实也。孔子得史记以作《春秋》，及其立义创意，褒贬赏诛，不复因史记者，眇思自出于胸中也。凡贵通者，贵其能用之也。即徒诵读，读诗讽术，虽千篇以上，鹦鹉能言之类也。衍传书之意，出膏腴之辞，非俶傥之才，不能任也。夫通览者，世间比有；著文者，历世希然。近世刘子政父子、杨子云、桓君山，其犹文、武、周公并出一时也；其余直有，往往而然，譬珠玉不可多得，以其珍也。', '', '读（dòu豆）：句读，断句。
通人：这里专指读书多，但不会发挥运用的人，与《别通篇》中的文人、鸿儒、通人不同。
杼（shù树）：通“抒”，发挥。
损益：增加或减少。这里是灵活引用的意思。
表：显露。这里是写出的意思。
耐：通“能”。
递修本“药”下有“者”字，可从。
生：句不可通，疑“生”是衍文。
引文参见《论语·子路》。
句难通。根据上文“入山见本。。入野见草”，疑“彼”下脱一“见”字。
眇（miào）：通“妙”，精深。
术：艺，经。
传书：这里泛指古书。
俶傥（tìtǎng）：卓越。
刘子政父子：指刘向与他的儿子刘歆。桓君子：桓谭（约公元前24～公元56年），字君山。沛国相（今安徽省濉溪县西北）人。官至议郎给事中。博学多通，遍习五经，喜非毁俗儒。反对谶纬神学，几遭光武帝斩处。提出“以烛火喻形神”的著名论点，对后来无神论思想的发展有影响。著有《新论》二十九篇，早佚。现存《新论·形神》一篇，为后人辑本。', '通读书千篇以上，万卷以下，读得很流畅，很熟练，能分析确定章节和断句，并以教授做老师的是通人。能够发挥古书意思，灵活引用古书词句，能上书奏记，或者提出见解和主张，串连成篇写成文章的是文人、鸿儒。努力好学，见识多，记得牢的，世上有很多；著书写文章，能说古论今的，万人中没有一个。然而能著书写文章的，是知识渊博精通而能运用的人。进山里看见树木，是长是短没有不知道的；到野外看见青草，是粗是细没有不了解的。然而不会砍伐树木用来作房子，采集百草用来配方调药，这是知道草木而不会运用。通人见识广博，却不会用它来论述事情，这叫藏书家，就是孔子所说的那种“能背诵《诗经》三百篇，把政治事务交给他，都干不了”的人，这跟那些见过草木不会采伐运用的人，是同一回事。孔子拿鲁国编年史来写《春秋》，等到他创新立义，赞赏和贬责一番，就不再沿袭鲁国编年史，而是经过深思熟虑自然从胸中产生出来的了。大凡重视通人，是看重他们能运用学到的东西。如果他们仅仅能熟读，读诗读经，即使是千篇以上，也是鹦鹉能说话之类。能引申古书上的意思，写出美好的文辞，没有卓越的才能，是不能胜任的。能通读的人，世上到处有；能著书写文章的人，历代却少得很。近代的刘子政父子、杨子云、桓君山，他们就象周文王、周武王、周公一样同时出现在同个时代；其余仅有而已，往往如此，譬如珍珠宝玉不可能多得，因为它们珍贵。', NULL, '', 'indent', 1545395355, '5c1c6c361579a3005fcfc8a9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640834, '尚书引义·太甲二', NULL, 6, 1536, 1, 1, '王夫之', NULL, 14557, '5858e94d128fe1006b87e239', '明', 'wen', '文', '', '', '形之恶也，倏而赘疣生焉；形之善也，俄而肌肤荣焉；非必初生之有成形也。气之恶也，倏而疢（chèn）疾生焉；气质善也，俄而荣卫畅焉；非必初生之有成气也。……形气者，亦受于天者也，非人之能自有也，而新故相推、日生不滞如斯矣。', '', '', '', NULL, '', 'indent', 1565181801, '5c1c73161579a3005fd0202f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640836, '思问录·外篇', NULL, 23, 1536, 1, 1, '王夫之', NULL, 14557, '5858e94d128fe1006b87e239', '明', 'wen', '文', '', '', '非天所有，名因人立。名非天造，必从其实。', '', '', '上天不是什么都有，名称是靠人来确立的。名称并不是天生造成的，必须依据事实。', NULL, '', 'indent', 1545398546, '5c1c78b11579a3005fd062a6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640904, '凤求凰', NULL, 931, 11, 1, 0, '司马相如', NULL, 10286, '57b8e6f57db2a20054260acc', '汉', 'shi', '诗', 'https://baike.baidu.com/item/%E5%87%A4%E6%B1%82%E5%87%B0/63800', '', '有一美人兮，见之不忘。
一日不见兮，思之如狂。
凤飞翱翔兮，四海求凰。
无奈佳人兮，不在东墙。
将琴代语兮，聊写衷肠。
何时见许兮，慰我彷徨。
愿言配德兮，携手相将。
不得於飞兮，使我沦亡。
凤兮凤兮归故乡，遨游四海求其凰。
时未遇兮无所将，何悟今兮升斯堂！
有艳淑女在闺房，室迩人遐毒我肠。
何缘交颈为鸳鸯，胡颉颃兮共翱翔！
凰兮凰兮从我栖，得托孳尾永为妃。
交情通意心和谐，中夜相从知者谁？
双翼俱起翻高飞，无感我思使余悲。', '《凤求凰》传说是汉代的古琴曲，演绎了司马相如与卓文君的爱情故事。以「凤求凰」为通体比兴，不仅包含了热烈的求偶，而且也象征着男女主人公理想的非凡，志趣的高尚，知音的默契等丰富的意蕴。', '', '其一
有位俊秀漂亮的女子啊，我见了她的容貌就难以忘怀。
我如果一天见不到她啊，心中牵念得像是要发狂一般。
我就像高飞盘旋的凤鸟，在天下各处苦苦寻觅着凰鸟。
可惜那个娴静的美人啊，没有居住在我那东墙的附近。
我以琴声替代心中情语，姑且描写我内心衷切的情意。
什么时候可以允诺婚事，慰藉我往返徘徊的相思之情？
望我的德行能与你相配，与你携手同在而成百年好合。
无法比翼偕飞的结果啊，令我沦陷于这情愁而欲丧亡。
其二
凤鸟啊凤鸟啊回到了家乡，行踪无定游览天下寻求心中凰鸟。
未遇凰鸟之时啊不知所往，怎能悟解今日登门后心中之所感！
有美丽娴静的女子在居室，居处虽近人却远而残虐我的心肠。
如何能做恩爱的交颈鸳鸯，使我这凤鸟与你这凰鸟一同翔游！
凰鸟啊凰鸟啊愿你我相依，共同哺育生子并永远做我的配偶。
情投意合而两心和睦谐顺，半夜与我互相追随又有谁能知晓？
展开双翼一起远走而高飞，徒然为你感念相思而使我心悲伤。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecc9003572034f65a94c7", "shortContent": "司马相如，蜀郡成都人，字长卿，是西汉大辞赋家。他与卓文君私奔的故事，长期以来脍炙人口，传为佳话。据《史记·司马相如列传》记载：他从京师、梁国宦游归蜀，应好友临邛（今四川邛崃）令王吉之邀，前往作客。当地头号富翁卓王孙之女卓文君才貌双全，精通音乐，青年寡居。一次，卓王孙举行数百人的盛大宴会，王吉与相如均以贵宾身份应邀参加。席间，王吉介绍相如精通琴艺，请他弹奏，相如就当众弹了两首琴曲，意欲以此挑动文君。...", "authors": ["熊", "笃"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b9434bfda01e0eab209", "bookTitle": "唐宋小说鉴赏辞典（新一版）", "articleId": "610f43ee911759740c9cb61f", "shortContent": "本篇为宋代话本，辑存于《清平山堂话本》，撰人未详。\n\n话本叙汉武帝时，四川成都府青年文士司马相如受临邛王知县之邀，在临邛相会。又受王知县推荐并介绍，访问当地巨富卓王孙家名园，受到卓王孙热情款待，并留住园中瑞仙亭。卓王孙之女卓文君窥相如容貌仪表“俊雅风流”，又具文名，产生了爱慕之意，而相如也闻文君“貌美聪慧，甚知音律”，有心于她。相如借一曲《凤求凰》表明自己的心迹，文君坦诚接受相如的求爱并随即与相如...", "authors": ["曾庆雨"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "646f3a317f27182da3811806", "shortContent": "司马相如，蜀郡成都人，字长卿，是西汉大辞赋家。他与卓文君私奔 的故事，长期以来脍炙人口，传为佳话。据《史记·司马相如列传》记载: 他从京师、梁国宦游归蜀，应好友临邛(今四川邛崃)令王吉之邀，前往作 客。当地头号富翁卓王孙之女卓文君才貌双全，精通音乐，青年寡居。一 次，卓王孙举行数百人的盛大宴会，王吉与相如均以贵宾身份应邀参加。 席间，王吉介绍相如精通琴艺，请他弹奏，相如就当众弹了两首琴曲，意欲 以...", "authors": ["熊笃"], "pressName": "上海辞书出版社"}]', '', 'center', 1546014807, '5c25dfdf808ca400739de15b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640837, '张子正蒙注卷五至当篇', NULL, 5, 1536, 1, 1, '王夫之', NULL, 14557, '5858e94d128fe1006b87e239', '明', 'wen', '文', '', '', '此篇推前篇未尽之旨而征之于日用，尤为切近。然皆存神知化之理所一以贯之者，所谓易简而天下之理得也。篇内言易简、知几而归本于大经之正，学者反而求之于父子君臣之间，以察吾性之所不容已，则天之所以为天，人之所以为人，圣之所以为圣，无待他求之矣。

　　至当之谓德，百顺之谓福。

　　当于理则顺。于事至当，则善协于一，无不顺矣。事无所逆之谓福。

　　德者福之基，福者德之致，无入而非百顺，故君子乐得其道。

　　以德致福，因其理之所宜，乃顺也。无入不顺，故尧水、汤旱而天下安，文王囚、孔子厄而心志适，皆乐也，乐则福莫大蔫。小人以得其欲为乐，非福也。

　　循天下之理之谓道，得天下之理之谓德，

　　理者，物之固然，事之所以然也。显著于天下，循而得之，非若异端孤守一己之微明，离理气以为道德。

　　故曰“易简之善配至德”。

　　至德，天之德也。顺天下之理而不凿，五伦百行晓然易知而简能，天之所以行四时、生百物之理在此矣。

　　“大德敦化”，仁智合一，厚且化也；

　　敦，存仁之体也；化，广知之用也。大德存仁于神而化无不行，智皆因仁而发，仁至而智无不明。化者，厚之化也，故化而不伤其厚，举错而枉者直，此理也。

　　“小德川流”，渊泉时出之也。敔按：此言用涵于体，体著于用，小德大德，一诚而已

　　渊泉则无不流，惟其时而已，故德以敦仁为本。

　　“大德不逾闲，小德出入可也”，大者器，则小者不器矣。

　　器者，有成之谓。仁成而纯乎至善，为不逾之矩则。小德如川之流，礼有损益，义有变通，运而不滞，而皆协于至一，故任让、进退、质文、刑赏，随施而可。

　　德者，得也，凡有性质而可有者也。

　　得，谓得之于天也。凡物皆太和氤氲之气所成，有质则有性，有性则有德，草木鸟兽非无性无德，而质与人殊，则性亦殊，德亦殊尔。若均是人也，所得者皆一阴一阳继善之理气，才虽或偏而德必同，故曰“人无有不善”。

　　“日新之谓盛德”，过而不有，不凝滞于心知之细也。

　　日新盛德，乾之道，天之化也。人能体之，所知所能，皆以行乎不得不然而不居，则后日之德非倚前日之德，而德日盛矣。时已过而犹执者，必非自然之理，乃心知缘于耳目一曲之明尔，未尝不为道所散见，而不足以尽道体之弘。

　　浩然无害，则天地合德；

　　以理御气，周遍于万事万物，而不以己私自屈挠，天之健，地之顺也。

　　照无偏系，则日月合明；

　　以理烛物，则顺逆、美恶皆容光必照，好而知恶，恶而知美，无所私也，如日月之明矣。

　　天地同流，则四时合序；

　　因天之时，顺地之理，时行则行，时止则止，一四时之过化而日新也。

　　酬酢不倚，则鬼神合吉凶。

　　应天下以喜怒刑赏，善善恶恶各如其理，鬼神之福善祸淫无成心者，此尔。故鬼神不可以淫祀祷，君子不可以非道悦。

　　天地合德，日月合明，然后能无方体；能无方体，然后能无我。

　　方体，以用言；我，以体言。凡方而皆其可行之方，凡体而皆其可立之体，则私意尽而廓然大公，与天同化矣。无方体者，神之妙；无我者，圣之纯。

　　礼器则藏诸身，用无不利。

　　礼器，礼运曲礼之要。礼器于多寡、大小、高下、质文，因其理之当然，随时位而变易，度数无方而不立所尚以为体，故曰“礼器是故大备”，言尽其变以合于大常也。全乎不一之器，藏于心以为斟酌之用，故无不协其宜，而至当以成百顺。

　　礼运云者，语其达也；礼器云者，语其成也。

　　运云者，运行于器之中，所以为体天地日月之化而酬酢于人事者也。达，谓通理而为万事之本；成者，见于事物而各成其事也。

　　达与成，体与用之道合。

　　礼运，体也；礼器，用也。达则无不可成，成者成其达也。体必有用，显诸仁也。用即用其体，藏诸用也。达以成而成其所达，则体用合矣。

　　体与用，大人之事备矣。

　　体无不成，用无不达，大人宰制万物、役使群动之事备矣。

　　礼器不泥于小者，则无非礼之礼，非义之义。盖大者器，则出入小者，莫非时中也。

　　礼器备而斟酌合乎时位，无所泥矣；不备，则贵多有时而侈，贵寡有时而陋，贵高有时而亢，贵下有时而屈，自以为礼义，而非天理之节文，吾心之裁制矣。达乎礼之运，而合吉凶、高下以不逾于大中之矩，故度数之小，可出可入，用无不利。

　　子夏谓“大德不逾闲，小德出入可也”，斯之谓尔。

　　出入，损益也。虽有损益，不逾天地日月运行各正之矩，非谓小节之可以自恣也。

　　礼器则大矣，

　　能备知礼器而用之，大人之事备矣。盖礼器云者，以天理之节文合而为大器，不倚于一偏者也。

　　修性而非小成者与！

　　性，谓理之具于心者；修，如修道之修，修著其品节也。修性而不小成，所以尽吾性之能而非独明其器数。

　　运则化矣，

　　礼运本天地日月之化而推行于节文，非知化者不能体。

　　达顺而乐亦至焉尔。

　　通达大顺，得中而无不和，则于多寡、大小、高下、质文之损益，曲畅人情之安矣。律吕之高下，人心之豫悦，此理而已。盖中和一致，中本于和而中则和，著于声容，原于神化，阴阳均而动静以时，所谓“明则有礼乐”也。故礼器以运为本。敔按：中本于和，谓时中本于太和

　　“万物皆备于我”，言万物皆有素于我也；

　　素，犹豫也，言豫知其理而无不得。此孟子自言其所得之辞。

　　“反身而诚”，谓行无不慊于心，则乐莫大焉。

　　知之尽，则实践之而已。实践之，乃心所素知，行焉皆顺，故乐莫大焉。

　　未能如玉，不足以成德；未能成德，不足以孚天下。

　　如玉，表里纯善而无疵也。放道而行，非诚有其得于心者，虽善，不足以感人。

　　“修己以安人。”修己而不安人，不行乎妻子，况可忾于天下？

　　忾，气相感也。修己之尽者，成如玉之德，无私无欲而通天下之志；如其不然，刻意尚行，矫物以为高，妻子不可行也。德至则感通自神，岂以己之是临物之非哉！

　　“正己而不求于人”，不愿乎外之盛者与！

　　君子之不愿乎外，非恬淡寡欲而已，随所处而必居正，则自无外愿也。盛，谓道之大者。

　　仁道有本，近譬诸身，推以及人，乃其方也。

　　心备万物之理，爱之本也。推以及人，于此求之而已。

　　必欲博施济众，扩之天下，施之无穷，必有圣人之才，能弘其道。

　　用之大者因其才，性其本也，性全而才或不足，故圣人不易及。然心日尽则才亦日生；故求仁者但求之心，不以才之不足为患。

　　制行以己，非所以同乎人。必物之同者，己则异矣；必物之是者，己则非矣。

　　制行必极于至善，非人之所能企及也。德盛则物自化，己有善而必人之己若，则立异而成乎过。君子不忍人之不善，唯严于责己而已。

　　此节旧分为二，今合之。

　　能通天下之志者，为能感人心。圣人同乎人而无我，故和平天下，莫盛于感人心。

　　天下之人，嗜好习尚移其志者无所不有，而推其本原，莫非道之所许。故不但兵农礼乐为所必务，即私亲、私长、好货、好色，亦可以其情之正者为性之所弘。圣人达于太和氤氲之化，不执己之是以临人之非，则君子乐得其道，小人乐得其欲，无不可感也，所以天下共化于和。敔按：《易》咸卦彖曰：“圣人感人心而天下和平。”张子引伸其义，见圣人之化天下，唯无朋从而光大故也。

　　道远人则不仁。

　　仁者，己与万物所同得之生理。倚其偏至之识才，可为人所不能为者，老、释是已。己与天下殊异而不相通，则一身以外皆痿痹也；发焉而为己甚之行，必惨薄而寡恩。

　　易简理得则知几，知几然后经可正。

　　易简，乾、坤之至德，万物同原之理。知此，则吾所自生微动之几，为万化所自始，皆知矣。即此而见君臣、父子、昆弟、夫妇、朋友天叙天秩不容已之爱敬，则亲、义、序、别、信，皆原本德性以尽其诚，而无出入、过不及于大经之中。盖惟尽性者为能尽伦，非独行之士，一往孤行之忠孝也。

　　天下达道五，其生民之大经乎！经正则道前定，事豫立，不疑其所行，利用安身之要莫先焉。

　　终身所行，自此五者而外无事，仁民、爱物、制礼、作乐，全此五者而已。五者豫立，则推行万事，无不安利；舍此则妄揣冥行，事赜而志乱，吉凶悔吝莫知所从。张子推天道人性变化之极而归之于正经，则穷神知化，要以反求大正之中道，此由博反约之实学，《西铭》一此意广言之也。

　　性天经，然后仁义行，故曰“有父子、君臣、上下，然后礼义有所错。”

　　性天经者，知大伦之秩叙自天，本吾性自然之理，成之为性，安焉而无所勉强也。能然，则爱敬之用扩充而无不行矣。礼义，仁义之用也，舍五者而泛施之，礼伪而义私，冥行而鲜当，刑名、法术之所以违天、拂人、戕仁义也。

　　仁通极其性，故能致养而静以安；

　　仁者，生理之函于心者也；感于物而发，而不待感而始有，性之藏也。人能心依于仁，则不为物欲所迁以致养于性，静存不失。

　　义致行其知，故能尽文而动以变。

　　义者，心所喻之物则也；知者，仁所发见之觉也。诚之明，知之良，因而行之，则仁之节文具而变动不居，无所往而非仁矣。

　　此章言义所以成仁之用，行无非义，则尽仁而复性矣。

　　义，仁之动也；流于义者于仁或伤。

　　仁存而必动，以加于物，则因物之宜而制之。然因物审处，则于本体之所存有相悖害者矣。故处物必不忘其静之所函，而屡顾以求安。

　　仁，体之常也；过于仁者于义或害。

　　体之常者，贯动静而恒也。乃方动而过持以静，则于事几之变失矣。故必静存万里、化裁不滞之圆神，曲成万物而不遗。

　　此章言仁义之相为体用，动静、刚柔以相济而不可偏也。

　　立不易方，安于仁而已乎！

　　乎，叹美之辞。随所立而不易其方，义也。然唯安于仁者，动而不失其静之理，故虽遇变而恒贞。

　　此章言仁所以立义之体，仁熟则义自正矣。以上三章，互相发明仁义合一之理。盖道之所自行，德之所自立，原其所本，则阴阳也，刚柔也，仁义也，当其氤氲而太和，初未尝分而为两；尽性合天者，得其合一、两在之神，则义不流，仁不过，而天下之理无不得。若徒袭仁义之迹，则或致两妨，故学者以存神为要。《易》以仁配阴，以义配阳，释者纷纭，唯此以一静一动为言，发明特切。然在天，在地，在人，理同而撰异，初不可画然分属，读者得意而舍迹可也。

　　安所遇而敦仁，故其爱有常心，有常心则物被常爱也。

　　安遇所以自处，敦仁则必及物。然人之所以不能常其爱者，境遇不齐而心为之变；心为境迁，则虽欲敦爱，而利于物者恐伤于己，仁不容不薄矣。若得丧安危，无遇不安，则苟可以爱而仁无所吝，一言一介，无迁就规避之心，不必泽及天下而后为仁也。

　　大海无润，因暍者有润；至仁无恩，因不足者有恩。乐天安土，所居而安，不累于物也。

　　无恩者，非以为恩于物而施之，爱犹大海，非为润人之渴而有水也。君子自存其仁，不为境迁，则物不能累己，而己亦不致为物之累，则因物之利而利之而已。若沾沾然以为恩于物为功，则必需势位以行爱而爱穷。

　　爱人然后能保其身，张子自注：寡助则亲戚畔之能保其身则不择地而安；自注：不能有其身，则资安处以置之不择地而安，盖所达者大矣；

　　四海之广，古今之变，顺逆险阻，无不可行矣。

　　大达于天，则成性成身矣。

　　大而化之，仁熟而无土不安，合于天德之无不覆，圣矣。无所遇而不安于性，以成身也。故舜之饭糗茹草，与为天子一也；孔子之困厄，与尧、舜一也。通乎屈伸而安身利用，下学而上达矣。

　　此章之指，言近而指远，尤学者所宜加省。

　　上达则乐天，乐天则不怨；下学则治己，治己则不无尤。

　　上达于天，屈伸之理合一，而不疑时位之不齐，皆天理之自然，富贵厚吾生，贫贱玉吾成，何怨乎！治己则去物之累，以责人之心责己，爱己之心爱人，不见人之可尤矣。圣之所以合天安土，敦仁而已。

　　不知来物，不足以利用；

　　来物，方来之事也。人之所以不利用者，据现在之境遇而执之也，若知将来之变不可测而守其中道，则无不利矣。

　　不通昼夜，未足以乐天。

　　屈伸往来之理，莫著于昼夜。昼必夜，夜必昼，昼以成夜，夜以息昼，故尧、舜之伸必有孔子之屈，一时之屈所以善万世之伸，天之所命无不可乐也。

　　圣人成其德，不私其身，故乾乾自强，所以成之于天尔。

　　身者，天之化也；德者，身之职也。乾乾自强，以成其德。以共天职，而归健顺之理气于天地，则生事毕而无累于太虚，非以圣智之功名私有于其身，所遇之通塞何足以系其念哉！

　　君子于仁圣，为不厌，诲不倦，然且自谓不能，盖所以为能也。

　　仁圣之道，乾乾不息而已。

　　能不过人，故与人争能，以能病人；

　　少有所得，则其气骄；广大无涯，则其志逊。

　　大则天地合德，自不见其能也。

　　时行物生，岂以今岁之成功自居，而息其将来之化哉！

　　君子之道达诸夭，故圣人有所不能；

　　道通于天之化，君子之所必为著明；而天之盛德大业，古今互成而不迫，生杀并行而不悖，圣人能因时裁成，而不能效其广大。

　　夫妇之智淆诸物，故大人有所不与。

　　夫妇之智偶合于道，而天明孤发，几与蜂蚁之君臣、虎狼之父子相杂，故自经沟渎之信，从井救人之仁，夫妇能之而大人弗为，大人贞一以动也。

　　匹夫匹妇，非夭之聪明不成其为人。

　　非能自立人道，天使之然尔。

　　圣人，天聪明之尽者尔。

　　天之聪明，在人者有隐有显，有变有通，圣人以圣学扩大而诚体之，则尽有天之聪明，而视听无非理矣。

　　大人者，有容物，无去物；有爱物，无徇物，天之道然。

　　大人不离物以自高，不绝物以自洁，广爱以全仁，而不违道以干誉，皆顺天之理以行也。

　　天以直养万物，

　　万物并育于天地之间，天顺其理而养之，无所择于灵蠢、清浊，挠其种性，而后可致其养直也。

　　代天而理物者，曲成而不害其直，斯尽道矣。

　　道立于广大而化之以神，则天下之人无不可感，天下之物无不可用，愚明、强柔，治教皆洽焉；声色、货利，仁义皆行焉，非有所必去，有所或徇也。若老、释之徒，绝物以孤立，而徇人以示爱，违天自用，不祥久矣。

　　志大则才大事业大，故曰“可大”，又曰“富有”；志久则气久德性久，故曰“可久”，又曰“日新”。

　　志立则学思从之，故才日益而聪明盛，成乎富有；志之笃，则气从其志，以不倦而日新，盖言学者德业之始终，一以志为大小久暂之区量，故《大学》教人，必以知止为始，孔子之圣，唯志学之异于人也。天载物，则神化感通之事，下学虽所不逮，而志必至焉，不可泥于近小，以苶其气而弃其才也。

　　清为异物，和为徇物。

　　清之过，和之流也。

　　金和而玉节之则不过，知运而贞一之则不流。

　　金坚玉白，而养之以和，节之以润，则至清而不异，智能运物，而恒贞于一，则至和而不徇，孔子之所以圣不可知，其涵养德性者密也。

　　此章上二句旧分一章，“金和”以下连下章，今正之。

　　道所以可久可大，以其肖天地而不离也；

　　肖其化则可大，乾乾不息而不离则可久。

　　与天地不相似，其违道也远矣。

　　意欲之私，限于所知而不恒，非天理之自然也。释、老执一己之生灭，畏死厌难，偷安而苟息，曲学拘闻见之习而不通于神化，以自画而小成，邪正虽殊，其与道违一也。“道二，仁与不仁而已”，天与人之辨焉耳。

　　久者一之纯，大者兼之富。

　　不杂以私伪，故纯；久，非专执不化也。穷天地万物之理，故富；大，非故为高远也。兼之富者，合万于一；一之纯者，一以贯万。一故神，两在故不测，下学而上达矣。

　　大则直不绞，方不刿，故不习而无不利。

　　大则通于万理而无不顺，直不伤激，方不矫廉，坤之六二，居中得正，刚柔合德，纯一而大，天下之理皆伸而情皆得，故无不利。

　　易简然后能知险阻，

　　以险阻之心察险阻，则险阻不在天下而先生于心，心有险阻，天下之险阻愈变矣。以乾之纯于健，自强而不恤天下之险，其道易；以坤之纯于顺，厚载而不忧天下之阻，其道简。险阻万变，奉此以临之，情形自著，而吾有以治之矣。

　　易简理得，然后一以贯天下之道。

　　险阻可通，况其大常者乎。

　　易简故能说诸心，知险阻故能研诸虑；

　　道在己而无忧，故悦，悦而忧惑不妄起，则所虑者正而自精。不然，在己无大常之理，物至情移，愈变而愈迷矣。

　　知几为能以屈为伸。

　　几者，动静必然之介，伸必有屈，屈所以伸，动静之理然也。以屈为伸，则善吾生者善吾死，死生不易其素，一以贯久大之德矣。乾之“知存亡进退而不失其正”，坤之“先迷后得”，所以平天下之险阻也

　　“君子无所争”，彼伸则我屈，知也。

　　阴阳、柔刚，迭相为屈伸，君子、小人各乘其时，知者知此，则量自弘矣。

　　彼屈则吾不伸而自伸矣。

　　彼屈则我自伸，不待鸣其屈以求伸。

　　又何争！

　　屈亦无争，伸亦无争，保吾大正而已。

　　无不容然后尽屈伸之道，至虚则无所不伸矣。

　　于人有君子小人，于世有治乱，于己有富贵、贫贱、夷狄、患难，天地之化至大，其屈伸非旦夕之效也。人所以不能尽屈伸之道者，遇屈则不能容也。至虚，则古今如旦暮，人我如影响，交感于太和之中而神不损。龙蛇蛰而全身，尺蠖之伸在屈，浩然之气，亘古今而常伸。“言忠信，行笃敬，虽之夷狄不可弃也”，利害于我何有焉？

　　“君子无所争”，知几于屈伸之感而已。

　　屈伸必相感者也，无待于求伸，而又何争！

　　“精义入神”，交神于不争之地，顺莫甚焉，利莫大焉。“天下何思何虑”，明屈伸之变，斯尽之矣。

　　精义，则伸有伸之义，屈有屈之义，知进退、存亡而不失其正。入神者，否泰消长之机化有变而神不变。故六十四象而乾、坤之德在焉，阴阳之多少，位之得失，因乎屈伸尔。知达于此，理无不顺，用无不利矣。彼与物争者，唯于天下生其思虑，而不自悦其心，研其虑，故憧憧尔思而不宁，唯己小而天下大，异于大人之无不知而无不容也。

　　此章旧分为二，今合之。

　　胜兵之胜，胜在至柔，明屈伸之神尔。

　　兵以求伸者也，而胜以柔，屈伸相感之神，于斯见矣。善为国者不师，至于用兵争胜，至能全体屈伸之神，窥见其几而已。老氏遂奉此以为教，欲伸固屈，以柔胜刚，与至虚能容之诚相违远矣。读者当分别观之。

　　敬斯有立，有立斯有为。

　　庄敬自持，而后耳目口体从心而定其物，则卓然知有我之立于两间，不因物而迁矣。有我而备万之诚存焉，奉此以有为而仁义行。

　　敬，礼之舆也，不敬则礼不行。

　　敬者，礼之神也，神运乎仪文之中，然后安以敏而天下孚之。

　　“恭敬、撙节、退让以明礼”，仁之至也，爱道之极也。

　　敛情自约以顺爱敬之节，心之不容已而礼行焉；不崇己以替天下，仁爱之心至矣。故复礼为为仁之极致，心之德即爱之理也。

　　己不勉明，则人无从倡，道无从弘，教无从成矣。

　　既明其理，尤详其事，君子之所以耄而好学，有余善以及天下后世也。

　　礼，直斯清，挠斯昏，

　　顺天理自然之节文为直；众论起而挠之，奉吾直而折之乃不乱。欧阳修、张孚敬皆成乎一说，惟其曲而不直也。敔按：《濮议》及《兴献帝谥说》，行乎一时而理不顺乎人心，故曰“曲而不直”

　　和斯利，乐斯安。

　　顺心理而直行，和于人心而己心适矣；安而利，孰得而挠之！退让为节，直清为守，合斯二者而后可以言礼。

　　将致用者，几不可缓；

　　心之初动，善恶分趣之几，辨之于早，缓则私意起而惑之矣。

　　思进德者，徙义必精；

　　辨其几，则已取义矣；而义必精而后尽理之极致，故进此而研之以充类至尽。

　　此君子所以立多凶多惧之世，乾乾德业，不少懈于趋时也。

　　义精，则有以处凶惧而无不正矣。趋时者，与时行而不息，宵昼瞬息，皆有研几徙义之功也。

　　“动静不失其时”，义之极也。

　　动静，以事言，谓行止进退也。不失其时者，顺天下之大经，合于时之中，研几速而徙义精，一于正也。

　　义极则光明著见，

　　晓然可以对于天下后世而无不白之隐。

　　唯其时，物前定而不疚。

　　物，事也。前定者，义精而诚立，因时必发而皆当。

　　有吉凶利害，然后人谋作，大业生；

　　此屈伸相感之机也。故尧有不肖之子，舜有不顺之亲，文王有不仁之君，周公有不轨之兄，孔子有不道之世，皆惟其时而精其义，归于大正。

　　若无施不宜，则何业之有！

　　无施不宜，所遇皆顺也。知此，则不怨不尤，而乐天敦仁于不息矣。

　　“天下何思何虑”，行其所无辜，斯可矣。

　　所谓天下有道不与易也。处变则不怨尤，处常则不妄作，皆与时偕行之精义，非以己意思虑之。

　　旧本分为二，今合之。

　　知崇，天也，形而上也；通昼夜而知，其知崇矣。

　　知崇者，知天者也，知形而上之神也。化有晦明而人用为昼夜，神则不息，通昼夜而无异行；略屈伸之迹而知其恒运之理，知合于天，崇矣。时有屈伸而君子之神无间，《易》曰“知崇法天”，法其不息也。

　　知及之而不以礼性之，非己有也。

　　礼之节文见于事为，形而下之器，地之质也。性，安也。形而上之道，有形而即丽于器，能体礼而安之，然后即此视听言动之中，天理流行而无不通贯，乃以凝形而上之道于己，否则亦高谈性命而无实矣。

　　故知礼成性而道义出，如天地位而易行。

　　知极于高明，礼不遗于卑下，如天地奠位而变化合一，以成乎乾、坤之德业，圣学所以极高明而道中庸也。

　　知德之难言，知之至也。

　　天下之所言者，道而已。德则通极于天，存之以神，和之于气，至虚而诚有，体一而用两；若倚于一事一念之所得而畅言之，则非德矣。知已至，乃知其言之难。

　　孟子谓“我于辞命而不能”，又谓“浩然之气难言”。《易》谓“不言而信，存乎德行”，又以尚辞为圣人之道，非知德，达乎是哉？

　　圣贤知德之难言，然必言之而后自信其知之已至，故以尚辞为道之极致。“性与天道不可得而闻”，“修辞立诚”，言其所自知，非中人以下所可与闻也。

　　暗然，修于德也；

　　入德以凝道。

　　的然，著于外也。

　　附托于道而不知德。', '', '', '', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf580f8fda556506123e", "shortContent": "《晋书·傅咸传》说：“好属文论，虽绮丽不足，而言成规鉴。”应该概括了傅咸赋的特点。傅咸的赋，不受时风影响，有自己的特色。在写法上，平实精当，与“结藻清英，流韵绮靡”的西晋文风大相径庭。在内容上，往往包含劝谏、批判的意味，有政教功利的倾向，也与西晋重情的倾向颇不合拍。\n傅咸赋不论抒情、咏物大都直接切入正题，造语端直，言不虚发，表现出一种平实的文风。就此赋而言，开始九句写纸的产生，表达了作者发展变化的...", "authors": ["赵茂林"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1e95e272d4b2254f08e", "shortContent": "号称“燕、许大手笔”之一的燕国公张说，擅长碑文墓志，当时无能及者。这篇记述阳鸿事迹德义的墓碣，是这类文字中有代表性的一篇。题内“碣”字《全唐文》作“碑”。按《唐六典》卷四：“五品以上立碑，螭首龟趺，趺上高不过九尺；七品以上立碣，圭首方趺，趺上高不过四尺。”据文中所述阳鸿仕历，当依本集作“碣”。\n文章在按碑碣文字惯例简要叙述阳鸿的卒、葬与籍贯家世后，随即转入对其学问识见及著述的评赞。“倜傥奇杰，瑰玮...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '', 'indent', 1565181806, '5c1c7bc39f545400706e42da', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640838, '八卦大演论', NULL, 8, 132, 1, 1, '王勃', NULL, 10034, '57b9109fa633bd00665dcd5d', '唐', 'wen', '文', 'https://baike.baidu.com/item/%E5%85%AB%E5%8D%A6%E5%A4%A7%E6%BC%94%E8%AE%BA/22805769?fr=aladdin', '', '八卦大演论
昔者圣人之作易也，始画八卦，以通神明之德，以类万物之情。以为分太极者两仪也，分四象者八卦也，成八卦者十六将也，司八卦者十二月也，分十六将者三十二候也，分十二月者二十四气也，分三十二候者六十四卦也，司二十四气者三十六旬也。进退于三百六十六日，屈伸于三百八十四爻。往来飞伏之理尽矣。孤虚消息之端极矣。三才之道，不可不及也；五行之义，不能复过也。翕之以幽明，张之以寒暑，会之以生死，申之以去就。祸福生焉，吉凶著焉；成败行焉，逆顺兴焉。贤者识其大者、远者，不贤者识其小者、近者。奉之者则顺，背之者则愆，圆立者称圣，偏据者号贤。
尝试论之曰：三才者，易之门户也；八卦者，易之径路也。引而伸之，终于六十四卦，天下之能事毕矣。陈而别之，极于三百八十四爻，天下之微理罄矣。夫阴阳之道，一向一背；天地之道，一升一降。故明暗相随，寒暑相因，刚柔相形，高下相倾，动静相乘，出入相藉。泯之者神也，形之者道也。可以一理征也，可以一端验也。
故天尊则地卑矣，水湿则火燥矣，山盈则泽虚矣，雷动则风适矣。是以天下有风，可以后矣；则地中有雷，可以复矣。天下有山，可以遁矣；则地上于泽，可以临矣。天地不交，可以否矣；则天地既交，可以泰矣。风行地上，可以观矣；则雷行天上，可以大壮矣。山附地上，可以剥矣；则火附天上，可以大有矣。风行水上，可谓涣矣；则水在地上，可以比矣。雷出地奋，可以豫矣；则风行天上，可以小畜矣。雷之与水，可作解矣；则风之与火，可以家人矣。雷在风上，可以恒矣；则风在雷上，可以益矣。风在地下，可以升矣；则雷在天下，可以无妄矣。风在水下，可以井矣；则雷在火下，可以噬嗑矣。风在泽下，可谓大过矣；则雷在山下，可为颐矣。雷在泽下，可以随矣；则风在山下，可为蛊矣。泽上有水，可为节矣；则山上有火，可为旅矣。雷在水下，可为屯矣；则风在火下，可为鼎矣。水在火上，可为既济矣；则火在水上，可为未济矣。泽中有火，可以革矣；则山下有水，可为蒙矣。火在地下，可以明夷矣；则水在天下，可为讼矣。地下有水，可为师矣；则山下有火，可为贲矣。泽上于天，可为矣；则泽下有水，可为困矣。山下有天，可以为大畜矣；则泽下有地，可以为萃矣。山在泽上，可为损矣；则泽在山上，可为咸矣。泽上有火，可为暌矣；则山上有水，可为蹇矣。上天下泽，可为履矣；则地下有山，可为谦矣。泽上有风，可为中孚矣；则山上有雷，可为小过矣。山上有风，可为渐矣；则泽上有雷，可以归妹矣。此天地以对成之义，阴阳反合之理。故卦相次，则反爻以成义，易之八卦是也。
八八相生，则错卦以与理，因而重之是也。故圣人之道，可纵焉，可横焉，可合焉，可离焉。逆而陈之，未縢逆焉；顺而别之，未尝顺焉。三画以变，虽天地之数，可无韬也。九六相推，虽万二千五百之浩荡，不能逾于三百八十四。三百八十四之纠纷，不能逾于六十四。重之以六十四，不能过于八卦。张之于八卦，不能过四象。纪之两仪，两仪之理达，而太极得矣。故古往今来，寒进暑退，死生乱动，是非滕结，未尝非两仪也。而未尝离太极也。故曰有寒有暑，则两仪不废也；无思无为，则太极未尝远也。见之则两仪，忘之则太极。夫然，故不舍二求一，未尝离动以求静，未尝离动以达静也。有可有不可，非圣人之谓也；无可无不可，是夫子之心也。
然天下之理，不可穷也；天下之性，不可尽也。有穷尽之地者，其唯圣心乎？有穷尽之路者，其唯圣言乎？故据沧海而观众水，则江河之会归可见也；登泰山而览群岳，则冈峦之本末可知也。是以贞一德之极，权六爻之变，振三才之柄，寻万方之动，又何往而不通乎？又何疑而不释乎？故孔子曰：“必也正名乎！”名者义之本也，非圣人孰能正之哉？若抑末执本，研精覃思，非圣人之书，则不读也；非圣人之言，则不取也。庶几乎神明之德可通乎？万物之情可类乎？未之思也，夫何远之有？君子可不务乎哉？', '《八卦大演论》是唐代创作的一篇散文。', '', '', NULL, '', 'indent', 1545399608, '5c1c7cca808ca4565c85b529', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640839, '准诏言事上书', NULL, 9, 1229, 1, 1, '欧阳修', NULL, 10018, '57b98d625bbb50005347ace1', '宋', 'wen', '文', 'https://baike.baidu.com/item/%E5%87%86%E8%AF%8F%E8%A8%80%E4%BA%8B%E4%B8%8A%E4%B9%A6/22474816?fr=aladdin', '', '月日，臣修谨昧死再拜上书于皇帝陛下。臣近准诏书，许臣上书言事。臣学识愚浅，不能广引深远，以明治乱之原，谨采当今急务，条为三弊五事，以应诏书所求，伏惟陛下裁择。
臣闻自古王者之治天下，虽有忧勤之心而不知致治之要，则心愈劳而事愈乖；虽有纳谏之明，而无力行之果断，则言愈多而听愈惑。故为人君者，以细务而责人，专大事而独断，此致治之要术也；纳一言而可用，虽众说不得以沮之，此力行之果断也。知此二者，天下无难治矣。
伏见国家自大兵一动，中外骚然。陛下思社稷之安危，念兵民之疲弊，四五年来，圣心忧劳，可谓至矣。然而兵日益老，贼日益强，并九州之力讨一西戎小者，尚无一人敢前，今又北戎大者违盟而动，其将何以御之？从来所患者夷狄，今夷狄叛矣；所恶者盗贼，今盗贼起矣；所忧者水旱，今水旱作矣；所赖者民力，今民力困矣；所须者财用，今财用乏矣。陛下之心日忧于一日，天下之势岁危于一岁。此臣所谓用心虽劳，不知求致治之要者也。近年朝廷开发言路，献计之士不下数千，然而事绪转多，枝梧不暇。从前所采，众议纷纭，至于临事，谁策可用？此臣所谓听言虽多，不如力行之果断者也。
伏思圣心所甚忧而当今所尚阙者，不过曰无兵也，无将也，无财用也，无御戎之策也，无可任之臣也。此五者，陛下忧其未有，而臣谓今皆有之。然陛下未得而用者，未思其术也。国家创业之初，四方割据，中国地狭，兵民不多，然尚能南取荆楚、收伪唐、定闽岭，西平两蜀，东下并、潞，北窥幽、燕。当时所用兵财将吏，其数几何？惟善用之，故不觉其少。何况今日，承百年祖宗之业，尽有天下之富强，人众物盛，十倍国初，故臣敢言有兵、有将、有财用、有御戎之策、有可任之臣。然陛下皆不得而用者，其故何哉？由朝廷有三大弊故也。
何谓三弊？一曰不慎号令，二曰不明赏罚，三曰不责功实。此三弊因循于上，则万事弛慢废坏于下。臣闻号令者，天子之威也；赏罚者，天子之权也。若号令不信，赏罚不当，则天下不服。故又须责臣下以功实，然后号令不虚出，而赏罚不滥行。是以慎号令，明赏罚，责功实，此三者帝王之奇术也。自古人君，英雄如汉武帝，聪明如唐太宗，皆知用此三术，而自执威权之柄，故所求无不得，所欲皆如意。汉武好用兵，则诛灭四夷，立功万里，以快其心。欲求将，则有卫、霍之材以供其指使；欲得贤士，则有公孙、董汲之徒以称其意。唐太宗好用兵，则诛突厥，服辽东，威振夷狄，以逞其志。欲求将，则有李靖、李勣之徒入其驾驭；欲得贤士，则有房、杜之徒在其左右。此二帝者，凡有所为，后世莫及。可谓所求无不得，所欲皆如意。无他术也，惟能自执威权之柄耳。
伏惟陛下以圣明之姿，超出二帝，又尽有汉、唐之天下。然而欲御边，则常患无兵；欲破贼，则常患无将；欲赡军，则常患无财用；欲威服四夷，则常患无策；欲任使贤材，则常患无人。是所求皆不得，所欲皆不如意，其故无他，由不用威权之术也。自古帝王，或为强臣所制，或为小人所惑，则威权不得出于己。今朝无强臣之患，旁无小人偏任之溺，内外臣庶尊陛下如天，爱陛下如父，倾耳延首愿听陛下之所为，然何所惮而不为乎？若一日赫然执威权以临之，则万事皆办，何患五者之无。奈何为三弊之因循，一事之不集。臣请言三弊。
夫言多变则不信，令频改则难从。今出令之初，不加详审，行之未久，寻又更张。以不信之言行难从之令，故每有处置之事，州县知朝廷未是一定之命，则官吏或相谓曰“且未要行，不久必须更改”，或曰“备礼行下，略与应破指挥”。旦夕之间，果然又变。至于将吏更易，道路疲于送迎；符牒纵横，上下莫能遵守。中外臣庶，或闻而叹息，或闻而窃笑，叹息者有忧天下之心，窃笑者有轻朝廷之意。号令如此，欲威天下，其可得乎？此不慎号令之弊也。
用人之术，不过赏罚。然赏及无功则恩不足劝，罚失有罪则威无所惧，虽有人，不可用矣。太祖时，王全斌破蜀而归，功不细矣，犯法一贬，十年不问。是时方讨江南，故黜全斌，与诸将立法，及江南已下，乃复其官。太祖神武英断，所以能平定天下者，其赏罚之法皆如此也。昨关西用兵，四五年矣，赏罚之际，是非莫分。大将以无功罢者依旧居官，军中见无功者不妨得好官，则诸将谁肯立功矣。裨将畏懦逗留者皆当斩罪，或暂贬而寻迁，或不贬而依旧，军中见有罪者不诛，则诸将谁肯用命矣。所谓赏不足劝，罚无所惧，赏罚如此而欲用人，其可得乎？此不明赏罚之弊也。
自兵动以来，处置之事不少，然多有名而无实。臣请略言其一二，则其他可知。数年以来，点兵不绝，诸路之民半为兵矣，其间老弱病患、短小怯懦者不可胜数，兵额空多，所用者少，是有点兵之虚名，而无得兵之实数也。新集之兵，所在教习，追呼上下，民不安居，主教者非将领之材，所教者无旗鼓之节，往来州县，愁叹嗷嗷，既多是老病小怯之人，又无训齐精练之法。此有教兵之虚名，而无训兵之实艺也。诸路州军分造器械，工作之际已劳民力，辇运般送又苦道涂。然而铁刃不刚，筋胶不固，长短大小多不中度。造作之所但务充数而速了，不计所用之不堪，经历官司又无检责。此有器械之虚名，而无器械之实用也。以草草之法教老怯之兵，执钝折不堪之器械，百战百败，理在不疑，临事而悟，何可及乎！故事无大小，悉皆卤莽，则不责功实之弊也。
臣故曰三弊因循于上，则万事弛慢废坏于下。万事不可尽言，臣请言大者五事。
其一曰兵。臣闻攻人以谋不以力，用兵斗智不斗多。前代用兵之人，多者常败，少者常胜。汉王寻等以百万之兵遇光武九千人而败，是多者败而少者胜也；苻坚以百万之兵遇东晋二三万人而败，是多者败而少者胜也；曹操以三十万青州兵大败于吕布，退而归许，复以二万人破袁绍十四五万，是用兵多则败、少则胜之明验也。况于夷狄，尤难以力争，只可以计取。李靖破突厥于定襄，只用三千人，其后破颉利于阴山，亦不过一万。其他以三五千人立功塞外者，不可悉数。盖兵不在多，能以计取尔。故善用兵者，以少而为多；不善用者，虽多而愈少也。为今计者，添兵则耗国，减兵则破贼。今沿边之兵不下七八十万，可谓多矣。然训练不精，又有老弱虚数，则十人不当一人，是七八十万之兵，不当七八万人之用。加又军无统制，分散支离，分多为寡，兵法所忌。此所谓不善用兵者虽多而愈少，故常战而常败也。臣愿陛下赫然奋威，敕励诸将，精加训练，去其老弱，七八十万中可得四五十万数。古人用兵以一当百，今既未能，但得以一当十，则五十万精兵可当五百万兵之用。此所谓善用兵者以少而为多，古人所以少而常胜者，以此也。今不思实效，但务添多，耗国耗民，积以年岁，贼虽不至，天下已困矣。此一事也。
其二曰将。臣又闻古语曰“将相无种”。故或出于奴仆，或出于军卒，或出于盗贼，惟能不次而用之，乃为名将耳。国家求将之意虽劳，选将之路太狭。今诏近臣举将而限以资品，则英豪之士在下位者不可得矣；试将材者限以弓马一夫之勇，则智略万人之敌皆遗之矣；山林奇杰之士召而至者，以其贫贱而薄之，不过与一主簿借职，使其怏怏而去，则古之屠钓饭牛之杰皆激怒而失之矣。至于无人可用，则宁用龙钟跛躄庸懦暗劣之徒，皆委之要地，授之兵柄，天下三尺童子皆为朝廷危之。前日澶渊之卒几为国家生事，此可见也。议者不知取将之无术，但云当今之无将臣。臣愿陛下革去旧弊，奋然精求。有贤豪之士，不须限以下位；有智略之人，不必试以弓马；有山林之杰，不可薄其贫贱。惟陛下能以非常之礼待人，人臣亦将以非常之效报国，又何患于无将哉？此二事也。
其三曰财用。臣又闻善治病者，必医其受病之处；善救弊者，必寻其起弊之源。今天下财用困乏，其弊安在？起于用兵而费大故也。汉武好穷兵，用尽累世之财，当时勒兵单于台，不过十八万，尚能困其国力。况未若今日七八十万，连四五年而不罢，所以天地之所生，竭万民之膏血，而用不足也。今虽有智者，物不能增，而计无所出矣。惟有减冗卒之虚费，练精兵而速战，功成兵罢，自然足矣。今兵有可减之理，无人敢当其事；贼有速击之便，无将敢奋其勇。后时败事，徒耗国而耗民。惟陛下以威权督责之，乃有期耳。此三事也。
其四曰御戎之策。臣又闻兵法曰：“上兵伐谋，其次伐交。”北虏与朝廷通好仅四十年，不敢妄动，今一旦发其狂谋者，其意何在？盖见中国频为元昊所败，故敢启其贪心，伺隙而动尔。今若敕励诸将，选兵秣马，疾入西界，但能痛败昊贼一阵，则吾军威大振，而虏计沮矣。此所谓上兵伐谋者也。今诇事者皆知北虏与西贼通谋，欲并二国之力，窥我河北、陕西。若使二虏并寇，则难以力支。今若我能先击败其一国，则虏势减半，不能独举。此兵法所谓伐交者也。元昊地狭，贼兵不多，向来攻我，传闻北虏常有助兵。今若虏中自有点集之谋，而元昊骤然被击，必求助于北虏。北虏分兵助昊，则可牵其南寇之力；若不助昊，则二国有隙，自相疑贰。此亦伐交之策也。假令二国克期分路来寇，我能先期大举，则元昊仓皇自救不暇，岂能与北虏相为表里？是破其素定之约，乖其克日之期。此兵法所谓亲而离之者，亦伐交之策也。元昊叛逆以来，幸而屡胜，常有轻视诸将之心，今又见朝廷北忧戎虏，方经营于河朔，必谓我师不能西出。今乘其骄怠，正是疾驱急击之时。此兵法所谓出其不意者，此取胜之上策也。前年西将有请出攻者，当时贼气力方盛，我兵未练，朝廷尚许其出师，况今元昊有可攻之势，此不可失之时。彼方幸吾忧河北，而不虞我能西征，出其不意，此可攻之势也。自四路分帅，今已半年，训练恩信，兵已可用，故近日屡奏小捷。是我师渐振，贼气渐衄，此可攻之势也。苟失此时，而使二虏先来，则吾无策矣。臣愿陛下诏执事之臣，熟议而行之。此四事也。
其五曰可任之臣。臣又闻仲尼曰：“十室之邑，必有忠信。”况今文武列职遍于天下，其间岂无材智之臣？而陛下总治万机之大，既不暇尽识其人，故不能躬自进贤而退不肖；执政大臣动拘旧例，又不敢进贤而退不肖；审官、吏部、三班之职，但掌文簿差除而已，又不敢越次进贤而退不肖。是上自天子，下至有司，无一人得进贤而退不肖者。所以贤愚混杂，侥幸相容，三载一迁，更无旌别。平居无事，惟患太多，而差遣不行，一旦临事要人，常患乏人使用。自古任官之法，无如今日之缪也。今议者或谓举主转官为进贤，犯罪黜责为退不肖，此不知其弊之深也。大凡善恶之人，各以类聚。故守廉慎者，各举清干之人；有赃污者，各举贪浊之人；好徇私者，各举请求之人；性庸暗者，各举不材之人。朝廷不问是非，但见举主数足，便与改官，则清干者进矣，贪浊者亦进矣，请求者亦进矣，不材者亦进矣。混淆如此，便可为进贤之法乎？方今黜责官吏，岂有澄清纠举之术哉？惟犯赃之人因民论诉者，乃能黜之耳。夫能舞弄文法而求财赂者，亦强黠之吏，政事必由己出，故虽诛剥豪民，尚或不及贫弱。至于不材之人不能主事，众胥群吏共为奸欺，则民无贫富，一时受弊。以此而言，则赃吏与不材之人为害等耳。今赃吏因自败者，乃加黜责，十不去其一二。至于不材之人，上下共知而不问，宽缓容奸。其弊如此，便可为退不肖之法乎？贤不肖既无别，则宜乎设官虽多而无人可用也。
臣愿陛下明赏罚，责功实，则材皆列于陛下之前矣。臣故曰五者皆有，然陛下不得而用者，为有弊也。三弊五事，臣既已详言之矣，惟陛下择之，天下之务不过此也。方今天文变于上，地理逆于下，人心怨于内，四夷攻于外，事势如此矣，非是陛下迟疑疑宽缓之时，惟愿为社稷生民留意。臣修昧死再拜。', '《准诏言事上书》是宋代文学家欧阳修创作的一篇文章。', '', '', NULL, '', 'indent', 1545400125, '5c1c7d3067f356005fd68599', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640840, '宋史赵普列传', NULL, 5, 3, 1, 1, '脱脱', NULL, 36991, '5c1c80c39f545400706e7fc4', '元', 'wen', '文', '', '', '赵普字则平，幽州蓟人。后唐幽帅赵德钧连年用兵，民力疲弊。普父回举族徙常山，又徙河南洛阳。普沈厚寡言，镇阳豪族魏氏以女妻之。
周显德初，永兴军节度刘词辟为从事，词卒，遗表荐普于朝。世宗用兵淮上，太祖拔滁州，宰相范质奏普为军事判官。宣祖卧疾滁州，普朝夕奉药饵，宣祖由是待以宗分。太祖尝与语，奇之。时获盗百馀，当弃市，普疑有无辜者，启太祖讯鞫之，获全活者众。淮南平，调补渭州军事判官。太祖领同州节度，辟为推官。移镇宋州，表为掌书记。
太祖北征至陈桥，被酒卧帐中，众军推戴，普与太宗排闼入告。太祖欠伸徐起，而众军擐甲露刃，喧拥麾下。及受禅，以佐命功，授右谏议大夫，充枢密直学士。
车驾征李筠，命普与吕馀庆留京师，普愿扈从，太祖笑曰“若胜胃介乎”从平上党，迁兵部侍郎、枢密副使，赐第一区。建隆三年，拜枢密使、检校太保。
乾德二年，范质等三相同日罢，以普为门下侍郎、平章事、集贤殿大学士。中书无宰相署敕，普以为言，上曰“卿但进敕，朕为卿署之可乎”普曰“此有司职尔，非帝王事也”令翰林学士讲求故实，窦仪曰“今皇弟尹开封，同平章事，即宰相任也”令署以赐普。既拜相，上视如左右手，事无大小，悉咨决焉。是日，普兼监修国史。命薛居正、吕馀庆参知政事以副之，不宣制，班在宰相后，不知印，不预奏事，不押班，但奉行制书而已。先是，宰相兼敕，皆用内制，普相止用敕，非旧典也。
太祖数微行过功臣家，普每退朝，不敢便衣冠。一日，大雪向夜，普意帝不出。久之，闻叩门声，普亟出，帝立风雪中，普惶惧迎拜。帝曰“已约晋王矣”已而太宗至，设重裀地坐堂中，炽炭烧肉。普妻行酒，帝以嫂呼之。因与普计下太原。普曰“太原当西北二面，太原既下，则我独当之，不如姑俟削平诸国，则弹丸黑子之地，将安逃乎”帝笑曰“吾意正如此，特库卿尔”
五年春，加右仆射、昭文馆大学士。俄丁内艰，诏起复视事。遂劝帝遣使分诣诸道，征丁壮籍名送京师，以备守卫。诸州置通判，使主钱谷。由是兵甲精锐，府为充实。
开宝二年冬，普尝病，车驾幸中书。三年春，又幸其第抚问之。赐赉加等。六年，帝又幸其第。时钱王俶遣使致书于普，及海物十瓶，置于庑下。会车驾至，仓卒不及屏，帝顾问何物，普以实对。上曰“海物必佳”即命启之。皆瓜子金也。普惶恐顿首谢曰“臣未发书，实不知”帝叹曰“受之无妨，彼谓国家事皆由汝书生尔”
普为政颇专，廷臣多忌之。时官禁私贩秦、陇大木，普尝遣亲吏诣市屋材，联巨筏至京师治第，吏因之窃货大木，冒称普市货鬻都下。权三司使赵玭廉得之以闻。太祖大怒，促令追班，将下制逐普，赖王溥奏解之。
故事，宰相、枢密使每候对长春殿，同止庐中。上闻普子承宗娶枢密使李崇矩女，即令分异之。普又以隙地私易尚食蔬圃以广其居，又营邸店规利。卢多逊为翰林学士，因召对屡攻其短。会雷有粼击登闻鼓，讼堂后官胡赞、李可度受赇骫法及刘伟伪作摄牒得官，王洞尝纳赂可度，赵孚授西川官称疾不上，皆普庇之。太祖怒，下御史府按问，悉抵罪，以有邻为秘书省正字。普恩益替，始诏参知政事与普更知印、押班、奏事，以分其权。未几，出为河阳三城节度、检校太傅、同平章事。
太平兴国初入朝，改太子少保，迁太子太保。颇为卢多逊所毁，奉朝请数年，郁郁不得志。会柴禹锡、赵镕等告秦王廷美骄恣，将有阴谋窃发。帝召问，普言愿备枢轴以察奸变，退又上书，自陈预闻太祖、昭宪皇太后顾托之事，辞甚切至。太宗感悟，召见慰谕。俄拜司徒兼侍中，封梁国公。先是，秦王廷美班在宰相上，至是，以普勋旧，再登元辅，表乞居其下，从之。及涪陵事败，多逊南迁，皆普之力也。
八年，出为武胜军节度、检校太尉兼侍中。帝作诗以饯之，普奉而泣曰“陛下赐臣诗，当刻石，与臣朽骨同葬泉下”帝为之动容。翌日，谓宰相曰“普有功国家，朕昔与游，今齿发衰矣，不容烦以枢务，择善地处之，因诗什以导意。普感激泣下，朕亦为之堕泪”宋琪对曰“昨日普至中书，执御诗涕泣，谓臣曰：此生馀年，无阶上答，庶希来世得效犬马力。臣昨闻普言，今复闻宣谕，君臣始终之分，可谓两全”
雍熙三年春，大军出讨幽蓟，久未班师，普手疏谏曰：
伏睹今春出师，将以收复关外，屡闻克捷，深快舆情。然晦朔屡更，荐臻炎夏，飞挽日繁，战斗未息，老师费财，诚无益也。
伏念陛下自剪平太原，怀徕闽、浙，混一诸夏，大振英声，十年之间，遂臻广济。远人不服，自古圣王置之度外，何足介意。窃虑邪谄之辈，蒙蔽睿聪，致兴无名之师，深蹈不测之地。臣载披典籍，颇识前言，窃见汉武时主父偃、徐乐、严安所上书及唐相姚无崇献明皇十事，忠言至论，可举而行。伏望万机之暇，一赐观览，其失未远，虽悔可追。
臣窃念大发骁雄，动摇百万之众，所得者少，所丧者多。又闻战者危事，难保其必胜。兵者凶器，深戒于不虞。所系甚大，不可不思。臣又闻上古圣人，心无固必，事不凝滞，理贵变通。前书有“兵久生变”之言，深为可虑，苟或更图稽缓，转失机宜。旬朔之间，时涉秋序，边庭早凉，弓劲马肥，我军久困，切虑此际，或误指踪。臣方冒宠以守藩，曷敢兴言而沮众。盖臣已日薄西山，馀光无几，酧恩报国，正在斯时。伏望速诏班师，无容玩敌。
臣复有全策，愿达圣聪。望陛下精调御膳，保养圣躬，挈彼疲氓，转之富庶。将见边烽不警，外户不扃，率土归仁，殊方异俗，相率向化，契丹独将焉往。陛下计不出此，乃信邪谄之徒，谓契丹主少事多，所以用武，以中陛下之意。陛下乐祸求功，以为万全，臣窃以为不可。伏愿陛下审其虚实，究其妄谬，正奸臣误国之罪，罢将士伐燕之师。非特多难兴王，抑亦从谏则圣也。古之人尚闻尸谏，老臣未死，岂敢百谀为安身之计而不言哉。
帝赐手诏曰：
朕昨者兴师选将，止令曹彬、米信等顿于雄、霸，裹粮坐甲以张军声。俟一两月间山后平定，潘美、田重进等会兵以进，直抵幽州，然后控扼险固，恢复旧疆，此朕之志也。奈何将帅等不遵成算，各骋所见，领十万甲士出塞远斗，速取其郡县，更还师以援辎重，往复劳弊，为辽人所袭，此责在主将也。
况朕踵百王之末，粗到承平，盖念彼民陷于边患，将救焚而拯溺，匪黩武以佳兵，卿当悉之也。疆场之事，已为之备，卿勿为忧。卿社稷元臣，忠言苦口，三复来奏，嘉愧实深。
普表谢曰：
昨以天兵久驻塞外，未克恢复，渐及炎蒸，事危势迫，辄陈狂狷，甘俟宪章。陛下特鉴衷诚，亲纡宸翰，密谕圣谋。臣窃审命师讨罪，信为上策，将帅能遵成算，必可平定。惟其不副天心，由兹败事。今既边鄙有备，更复何虞。况陛下登极十年，坐隆大业，无一物之失所，见万国之咸宁。所宜端拱穆清，啬神和志，自可远继九皇，俯观五帝。岂必穷边极武，与契丹较胜负哉。臣素亏壮志，矧在衰龄，虽无功伐，愿竭忠纯。
观者咸嘉其忠。四年，移山南东道节度，自梁国公改封许国公。会诏下亲耕籍田，普表求入觐，辞甚恳切。上恻然谓宰相曰“普开国元臣，朕所尊礼，宜从其请”既至，慰抚数四，普呜咽流涕。陈王元僖上言曰：
臣伏见唐太宗有魏玄成、房玄龄、杜如晦，明皇有姚崇、宋璟、知古，皆任以辅弼，委之心膂，财成帝道，康济九区，宗祀延洪，史策昭焕，良由登用得其人也。今陛下君临万方，焦劳庶政，宵衣旰食，以民为心。历考前王，诚无所让，而辅相之重，未偕曩贤。况为邦在于任人，任人在乎公正，公正之道莫先于赏罚，斯为政之大柄也。苟赏罚匪当，淑慝莫分，朝廷纪纲，渐致隳紊。必须公正之人典衡轴，直躬敢言，以辨得失，然后彝伦式序，庶务用康。
伏见山南东道节度使赵普，开国元老，参谋缔构，厚重有识，不妄希求恩顾以全禄位，不私徇人情以邀名望，此真圣朝之良臣也。窃闻憸巧之辈，朋党比周，众口嗷嗷，恶直丑正，恨不斥逐遐徼，以快其心。何者。盖虑陛下之再用普也。然公谠之人，咸愿陛下复委以政，启沃君心，羽翼圣化。国有大事，使之谋之。朝有宏纲，使之举之。四目未察，使之明之。四聪未至，使之达之”官人以材，则无窃禄，致君以道，则无苟容。贤愚洞分，玉石殊致，当使结朋党以驰骛声势者气索，纵巧佞以援引侪类者道消。沈冥废滞得以进，名儒懿行得以显，大政何患乎不举，生民何患乎不康，匪窬期月之间，可臻清静之治。臣知虑庸浅，发言鲁直。伏望陛下旁采群议，俯察物情，苟用不失人，实邦国大幸。
籍田礼毕，太宗欲相吕蒙正，以其新进，藉普旧德为之表率，册拜太保兼侍中。帝谓之曰“卿国之勋旧，朕所毗倚，古人耻其君不及尧、舜，卿其念哉”普顿首谢。
时枢密副使赵昌言与胡旦、陈象舆、董俨、梁颢厚善。会旦令翟马周上封事，排毁时政，普深嫉之，奏流马周，黜昌言等。郑州团练使侯莫陈利用骄肆僭侈，大为不法，普廉得之，尽以条奏，利用坐流商州，普固请诛之。其嫉恶强直皆此类。
李继迁之扰边，普建议以赵保忠复领夏台故地，因令图之。保忠反与继迁同谋为边患，时论归咎于普，颇为同列所窥，不得专决。
旧制，宰相以未时归第，是岁大热，特许普夏中至午时归私第。明年，免朝谒，止日赴中书视事，有大政则召对。冬，被疾请告，车驾屡幸其第省之，赐予加等。普遂称疾笃，三上表求致仕，上勉从之，以普为西京留守、河南尹，依前守太保兼中书令。普三表恳让。赐手诏曰“开国旧勋，惟卿一人，不同他等，无至固让，俟首涂有日，当就第与卿为别”普捧诏涕泣，因力疾请对，赐坐移晷，颇言及国家事，上嘉纳之。普将发，车驾幸其第。
淳化三年春，以老衰久病，令留守通判刘昌言奉表求致政，中使驰传抚问，凡三上表乞骸骨。拜太师，封魏国公，给宰相奉料，令养疾，俟损日赴阙，仍遣其弟宗正少卿安易赍诏书赐之。又特遣使赐普诏曰“卿顷属微疴，恳求致政，朕以居守之重，虑烦耆耋，维师之命，用表尊贤。伫闻有瘳，与朕相见。今赐羊酒如别录，卿宜爱精神，近医药，强饮食，以副朕眷遇之意”七月卒，年七十一。
卒之先一岁，普生日，上遣其子承宗赍器币、鞍马就赐之。承宗复命，未几卒。次岁，普已罢中书令。故事，无生辰之赐，特遣普侄婿左正言、直昭文馆张秉赐之礼物。普闻之，因追悼承宗，秉未至而普疾笃。先是，普遣亲吏甄潜诣上清太平宫致祷，神为降语曰“赵普，宋朝忠臣，久被病，亦有冤累耳”潜还，普力疾冠带，出中庭受神言，涕泗感咽，是夕卒。
上闻之震悼。谓近臣曰“普事先帝，与朕故旧，能断大事，向与朕尝有不足，众所知也。朕君临以来，每优礼之，普亦倾竭自效，尽忠国家，真社稷臣也，朕甚惜之”因出涕，左右感动。废朝五日，为出次发哀。赠尚书令，追封真定王，赐谥忠献。上撰神道碑铭，亲八分书以赐之。遣右谏议大夫范杲摄鸿胪卿，护丧事。缚绡布各五百匹，米面各五百石。葬日，有司设卤簿鼓吹如式。
二女皆笄，普妻和氏言愿为尼，太宗再三谕之，不能夺。赐长女名志愿，号智果大师。次女名志英，号智圆大师。
初，太祖侧微，普从之游，既有天下，普屡以微时所不足者言之。太祖豁达，谓普曰“若尘埃中可识天子、宰相，则人皆物色之矣”自是不复言。普少习吏事，寡学术，及为相，太祖常劝以读书。晚年手不释卷，每归私第，阖户启箧取书，读之竟日。及次日临政，处决如流。既薨，家人发箧视之，则《论语》二十篇也。
普性深沉有岸谷，虽多忌克，而能以天下事为己任。宋初，在相位者多龌龊循默，普刚毅果断，未有其比。尝奏荐某人为某官，太祖不用。普明日复奏其人，亦不用。明日，普又以其人奏，太祖怒，碎裂奏牍掷地，普颜色不变，跪而拾之以归。他日补缀旧纸，复奏如初。太祖乃悟，卒用其人。又有群臣当迁官，太祖素恶其人，不与。普坚以为请，太祖怒曰“朕固不为迁官。卿若之何”普曰“刑以惩恶，赏以酧功，古今通道也。且刑赏天下之刑赏，非陛下之刑赏，岂得以喜怒专之”太祖怒甚，起，普亦随之。太祖入宫，普立于宫门，久之不去，竟得俞允。
太宗入弭德超之谗，疑曹彬不轨，属普再相，为彬辨雪保证，事状明白。太宗叹曰“朕听断不明，几误国事”即日窜逐德超，遇彬如旧。
祖吉守郡为奸利，事觉下狱，案劾，爰书未具。郊礼将近，太宗疾其贪墨，遣中使谕旨执政曰“郊赦可特勿贷祖吉”普奏曰“败官抵罪，宜正刑辟。然国家卜郊肆类，对越天地，告于神明，奈何以吉而隳陛下赦令哉”太宗善其言，乃止。
真宗咸平初，追封韩王。二年，诏曰“故太师赠尚书令、追封韩王赵普，识冠人彝，才高王佐，翊戴兴运，光启鸿图，虽吕望肆伐之勋，萧何指纵之效，殆无以过也。自辅弼两朝，周旋三纪，茂岩廊之硕望，分屏翰之剧权，正直不回，始终无玷，谋猷可复，风烈如生。宜预享于大烝，永同休于宗祏，兹为茂典，以答旧勋，其以普配飨太祖庙庭”
普子承宗，羽林大将军，知潭、郓二州，皆有声。承煦，成州团练使。弟固、安易。固至都官郎中。
安易字季和。建隆初，摄府州录事参军，节度使折德扆言其清干，遂命即真。再迁河南府推官。会普居相位，十年不赴调。太平兴国中，历华、邢二镇掌书记。部刍粮至太原城下，拜监察御史，知兴元府。转殿中，赐绯鱼袋。先是，两川民输税者以铁钱易铜钱。安易言其非便，请许纳铁钱，诏从之。九年，起拜宗正少卿，知定州。会以曹璨知州，徙安易为通判，未几代归。又表求外任，命知耀州，留不遣，命按视北边事。
淳化中，尝建议以蜀地用铁钱，准铜钱数倍，小民市易颇为不便，请如刘备时令西川铸大钱，以十当百。下都省集议，吏部尚书宋琪等言“刘备时盖患钱少，因而改作，今安易之请反患钱多，非经久计也”而安易论请不已，仍募工铸大钱百馀进之，极其精好，俄坠殿阶皆碎，盖熔铄尽其精液矣。太宗不之诘，犹嘉其用心，赐以金紫，且遣其典铸。既而大有亏耗，岁中裁得三千馀缗，众议喧然，遂罢之。事具《食货志》。
历知襄、庐二州，就迁宗正卿，归朝，复领卿职。时属籍未备，奏请纂录，咸平初，乃命梁周翰与安易同修。安易略涉书传，性强狠，好谈世务，而疏阔不可用。初，太宗尝问农政，安易请复井田之制。又以其家本燕蓟，多访以边事。
景德初，礼官详定明德皇太后灵驾发引，于京师壬地权攒，依礼埋悬重，升祔神主。安易上言：
《礼》云“既虞作主”，虞者，已葬设吉祭也。明未葬则未立虞主及神主。所以周制但凿木为悬重，以主神灵。王后七月而葬，则埋悬重，掩玄堂，凶仗、辒辌车、龙輴之属焚于柏城讫，始可立虞主。吉仗还京，备九祭，复埋虞主，然后立神主，升庙室。自旷古至皇朝，上奉祖宗陵庙行此礼，何以今日乃违典章，苟且升祔，方权攒妄立神主，未大葬辄埋悬重。且棺柩未归园陵，则神灵岂入太庙。奈柏城未焚凶仗，则凶秽唐突祖宗。望约孝章近例，但于壬地权攒，未立神主升祔，凶仪一切祗奉。俟丙午年灵驾西去园陵，东回祔庙。如此则免于颠倒，不利国家。
乃诏有司再加详定。判礼院孙何等上言：
按《晋书》羊太后崩，废一时之祀，天地明堂，去乐不作。又按《礼》，王后崩，五祀之祭不行既殡而祭。所言五祀不行，则天地之祭不废，遂议以园陵年月不便，须至变礼从宜。又缘先准礼文，候神主升祔毕，方行享祀。若俟丙午岁，则三年不祭宗庙，礼文有阙。况明德皇太后德配先朝，礼合升祔。遂与史馆检讨同共参详，以为庙未祔则神灵不至，伏恐祭祀难行。攒既毕则梓宫在郊，可以葬礼比附。遂按《礼》云“葬者藏也，欲人不得而见也”既不欲穿圹动土，则龙輴、攒木、题凑，蒙椁上四柱如屋以覆，尽涂之。所合埋重，一依近例，便可升祔神主。安易妄言，以凶仗为凶秽，目群官为颠倒，指梓宫为棺柩，令百司分析园陵，浼渎圣听，诬罔臣下。
安易又云“昔日睹群官尽公，奉二帝诸后，并先山陵，后祔庙。今日睹群官颠倒，奉明德皇太后，独先祔庙，后园陵”者。今详当时先山陵后祔庙，正为年月便顺，别无阴阳拘忌。今则年月未便，理合从宜。未埋重则礼文不备，未升祔则庙祭犹阙，须从变礼，以合圣情。兼明德皇太后将赴权攒，而安易所称“柏城未焚凶仗，则凶秽唐突祖宗”按《檀弓》云“丧之朝也，顺死者之孝心也”郑玄注云，谓迁柩于庙。
又云“其哀离其室也，故至于祖考之庙而后行，商朝而殡于祖，周朝而遂葬”今亦遥辞宗庙而后行，岂可以《礼经》所出目为颠倒，吉凶具仪谓之唐突哉。
又云“孝章皇后至道元年崩，亦缘有所嫌避，未赴园陵，出京权攒之时，不立神主入庙。直至至道三年，西去园陵，礼毕，然后奉虞主还京，易神主祔庙，以合典礼”今详当时文籍，缘孝章为太宗嫂氏，上仙之时，止辍五日视朝，百官不曾成服，与今不同。从初亦无诏命令住庙享。今明德皇太后母仪天下，主上孝极曾、颜，况上仙之初，即有遗命权停享祀。今按礼文，固合如此。安易荒唐庸昧，妄有援引，以大功之亲，比三年之制，欺罔君上，乃至于斯。
况安易以讦直自负，所诋者无非良善。以清要自高，所尚者无非鄙俗。名宦之志，老而益坚。诗书之文，懵而不习。本院所议，并明称典故，旁考时宜，虽曰从权，粗亦稽古，请依无议施行。
从之。安易又屡言陵庙事，词多鄙俚。晚岁进趋不已，时论嗤之。二年卒，年七十六。赠工部尚书。录其子承庆为国子博士，孙从政为太常寺奉礼郎。
论曰：自古创业之君，其居潜旧臣，定策佐命，树事建功，一代有一代之才，未尝乏也。求其始终一心，休戚同体，贵为国卿，亲若家相，若宋太祖之于赵普，可谓难矣。陈桥之事，人谓普及太宗先知其谋，理势或然。事定之后，普以一枢密直学士立于新朝数年，范、王、魏三人罢相，始继其位，太祖不亟于酧功，普不亟于得政。及其当揆，献可替否，惟义之从，未尝以勋旧自伐。偃武而修文，慎罚而薄敛，三百馀年之宏规，若平昔素定，一旦举而措之。太原、幽州之役，终身以轻动为戒，后皆如其言。家人见其断国大议，闭门观书，取决方册，他日窃视，乃《鲁论》耳。昔傅说告商高宗曰“学于古训乃有获，事不师古，以克永世，匪说攸闻”普为谋国元臣，乃能矜式往哲，蓍龟圣模，宋之为治，气象醇正，兹岂无助乎。晚年廷美、多逊之狱，大为太宗盛德之累，而普与有力焉。岂其学力之有限而犹有患失之心欤。君子惜之。', '', '', '', NULL, '', 'indent', 1545400636, '5c1c80d07f6fd3005d03c867', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640841, '物理论', NULL, 1, 1, 0, 1, '杨泉', NULL, 36992, '5c1c82cb67f356005fd6cce6', '三国', 'wen', '文', '', '', '天者。旋也。均也。积阳为刚。其体回旋。羣生之所大仰。
北堂书钞天部。太平御览天部
杨雄非浑天而作盖天圆。其盖左转。日月星辰随而东西。桓谭难之。雄不解。此盖天者。复难知也。
太平御览天部
元气皓大则称皓天。皓天。元气也。皓然而已。无他物也。
太平御览天部
儒家立浑天。以追天形。从车轮焉。周髀立天（案天上应有葢字。）言天气循边而行。从磨石焉。斗极。天之中也。言天者必拟之人。故自脐以下。人之阴也。自极以北。天之阴也。所以立天地者。水也。成天地者。气也。水土之气升而为天。（案水土句又见初学记天部。）天者。君也。夫地有形而天无体。譬如灰焉。烟在上。灰在下也。浑天说天。言天如车轮。而日月旦从上过。夜从下过。故得出卯入酉。或以斗极难之。故作盖天。言天左转。日月不行。皆缘边为道。就浑天之说。则斗极不正。若用盖天。则日月出入不定。夫天。元气也。皓然而已。无他物焉。
太平御览天部
自极以南。天之阳。自极以北。天之阴。
北堂书钞天部
北极。天之中。阳气之北极也。极南为太阳。极北为太阴。太阴则无光。太阳则能照。故为昏明寒暑之极也。
史记天官书索隐。北堂书钞天部
日者。太阳之精也。夏则阳盛阴衰。故昼长夜短。冬则阴盛阳衰。故昼短夜长。气之引也。行阴阳之道长。故出入卯酉之北。行阴阳之道短。故出入卯酉之南。春秋阴阳等。故日行中平。昼夜等也。
太平御览天部
月。水之精。潮有大小。月有亏盈。
北堂书钞天部
上弦月从下侵。
北堂书钞天部
日月之□为星辰。星辰。辰生於地。
太平御览天部
京房说月与星。至阴也。有形无光。日照之乃光。如以影照日而有影见。
艺文类聚天部
星者。元气之英也。汉水之精也。气发而升。精华上浮。宛转随流。名之曰天河。一曰云汉。众星出焉。
诗小雅正义。北堂书钞天部。太平御览天部
星。元气之精。日精也。二十八宿。度数有数。故谓恒星。
太平御览天部
斗极所以成寒暑。
北堂书钞天部
岁行一次谓之岁星。则十二岁而星一周天也。
史记天官书索隐
岂有太乙之君坐于庶人之座。魁罡之神存于匹妇之室。
意林
风者。阴阳乱气激。（案文选风赋注引作击。）发而起者也。犹人之内气。因喜怒哀乐激越而发也。故春气温。其风温以和。喜风也。夏气盛。其风熛以怒。怒风也。秋风劲。其风淸以直。淸风也。冬气□。其风惨以烈。固风也。此四正之风也。又有四维之风。东北明庶。庶物出幽入明也。东南融风。以道以长也。西南淸和。万物备成也。西北不周。方潜藏也。此八风者。方土异气。疾徐不同。和平则顺。违逆则凶。非有使之者也。气积自然。怒则飞沙扬砾。发屋拔树。喜则不摇枝动草。顺物布气。天下之性。自然之理也。
太平御览天部。事类赋天部注
积风成雷。
北堂书钞天部。初学记天部。艺文类聚天部。太平御览天部。事类赋天部注
风。淸热之气。散为电。
北堂书钞天部。太平御览天部（案北堂书钞引作热气散而为电。）
轩辕。主雷雨之神。
北堂书钞天部
云雨于是乎出。霜雪于是乎降。
北堂书钞天部
畴昔神农始治农功。正节气。正寒温。以为早晚之期。故立历日。
艺文类聚岁时部。事物纪原一（案事物纪原又引神农立历日。）
正月朝四面黄气。其岁大丰。此黄帝用事。土气均和。四方并熟。
太平御览岁时部
阳盈而过。故致旱。
艺文类聚灾异部。太平御览咎徵部
地者。底也。底之言著也。阴体下著也。
尔雅释文
地者。卦曰坤。其德曰母。其神曰祗。亦曰媪。大而名之曰黄地祗。小而名之曰神州。亦曰后土。
初学记地部。太平御览地部
其神曰祗。祗。成也。百生万物备成也。其卦为坤。其德曰母。地形有高下。气有刚柔。物有巨细。味有甘苦。鎭之以五岳。积之以邱陵。播之以四渎。流之以四川。盖气。自然之体也。地发黄泉。周伏回转。以生万物。地者。天之根本也。形西北高而东南下。东西长。南北短。其尽四海者也。
北堂书钞地理部。太平御览地部
