INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640842, '春秋穀梁传·庄公三年', NULL, 12, 4, 1, 1, '穀梁子', NULL, 36790, '586e4968da2f600055d635c5', '周', 'wen', '文', '', '', '五月，葬桓王。……独阴不生，独阳不生，独天不生，三合然后生。故曰：母之子也可，天之子也可。尊者取尊称焉；卑者取卑称焉。其曰王者，民之所归往也。', '', '', '', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b6bedc98d685fd9d8f807", "shortContent": " 本篇所记载和议论的宋楚泓之战在《左传》中也有记叙（本书《左传》鉴赏部分“子鱼论战”收录了关于同一事件的原文），我们可以把《左传》和《春秋穀梁传》关于这次战争的记载加以比较研究，从中可以看到这两传的特点和它们之间的同异。\n\n非常明显的是《左传》主要是记载史实，对历史事件的分析和评论一般是当时的或稍后的历史人物做出的，作者很少直接发表自己的见解，尤其缺少思想理论层面上的评述。《穀梁传》则不同，在这篇...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1565181958, '5c1c8548fb4ffe005f1c6a22', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640843, '中兴五论·论执要之道', NULL, 4, 90, 1, 1, '陈亮', NULL, 10206, '57b9b9b0128fe1005f861320', '宋', 'wen', '文', '', '', '今朝廷有一政事，而多出于御批；有一委任，而多出于特旨。使政事而皆善，委任而皆当，固足以彰陛下之圣德，而犹不免好详之名。万一不然，而徒使宰辅之避事者得用以藉口，此臣爱君之心所不能以自已也。臣愿陛下操其要于上，而分其详于下。', '', '', '现在朝廷有政事，⼤多是由皇帝亲⾃批；有地⽅官员委任，也是由皇帝亲⾃批的。假如政事都能妥当处置，官员任命都能正确得当，当然⾜以彰显皇上的功绩圣德，但依然不免会有揽权独断的不好名声。如果处置不好，则让⼿下的宰相⼤⾂不作为找到了借⼝。这是我忠爱皇上您，所以不得不说的话。我希望皇上要在上⾯抓⼤事、要事，⽽把具体繁杂的事务分给⾂下去做。', NULL, '', 'indent', 1545401898, '5c1c85c79f545400706ec055', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640844, '四书集注·孟子集注', NULL, 16, 1475, 1, 1, '朱熹', NULL, 10015, '57b936ccc4c971005590f2c8', '宋', 'wen', '文', '', '', '孟子曰：“羿之教人射，必志于彀；学者亦必志于彀。大匠诲人，必以规矩；学者亦必以规矩。”朱注:大匠，工师也。规矩，匠之法也。此章言事必有法，然后可成，师舍是则无以教，弟子舍是则无以学。曲艺且然，况圣人之道乎？', '', '', '', NULL, '', 'indent', 1545402012, '5c1c863d808ca40073369090', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640845, '论衡 · 卷二十八 · 书解篇', NULL, 8, 5, 1, 1, '王充', NULL, 36800, '589c4939128fe1005806fa23', '汉', 'wen', '文', '', '', '或曰：“士之论高，何必以文？”
答曰：夫人有文质乃成。物有华而不实，有实而不华者。《易》曰：“圣人之情见乎辞。”出口为言，集札为文，文辞施设，实情敷烈。夫文德，世服也。空书为文，实行为德，著之于衣为服。故曰：德弥盛者文弥缛，德弥彰者人弥明。大人德扩其文炳。小人德炽其文斑。官尊而文繁，德高而文积。华而晥者，大夫之箦，曾子寝疾，命元起易。由此言之，衣服以品贤，贤以文为差。愚杰不别，须文以立折。非唯于人，物亦咸然。龙鳞有文，于蛇为神；凤羽五色，于鸟为君；虎猛，毛蚡蚖；龟知，背负文：四者体不质，于物为圣贤。且夫山无林，则为土山，地无毛，则为泻土；人无文，则为仆人。土山无麋鹿，泻土无五谷，人无文德，不为圣贤。上天多文而后土多理。二气协和，圣贤禀受，法象本类，故多文彩。瑞应符命，莫非文者。晋唐叔虞、鲁成季友、惠公夫人号曰仲子，生而怪奇，文在其手。张良当贵，出与神会，老父授书，卒封留侯。河神，故出图，洛灵，故出书。竹帛所记怪奇之物，不出潢洿。物以文为表，人以文为基。棘子成欲弥文，子贡讥之。谓文不足奇者，子成之徒也。
著作者为文儒，说经者为世儒。二儒在世，未知何者为优。或曰：“文儒不若世儒。世儒说圣人之经，解贤者之传，义理广博，无不实见，故在官常位，位最尊者为博士，门徒聚众，招会千里，身虽死亡，学传于后。文儒为华淫之说，于世无补，故无常官，弟子门徒不见一人，身死之后，莫有绍传，此其所以不如世儒者也。”
答曰：不然。夫世儒说圣情，共起并验，俱追圣人。事殊而务同，言异而义钧。何以谓之文儒之说无补于世？世儒业易为，故世人学之多；非事可析第，故宫廷设其位。文儒之业，卓绝不循，人寡其书，业虽不讲，门虽无人，书文奇伟，世人亦传。彼虚说，此实篇。折累二者，孰者为贤？案古俊又著作辞说，自用其业，自明于世。世儒当时虽尊，不遭文儒之书，其迹不传。周公制礼乐，名垂而不灭。孔子作《春秋》，闻传而不绝。周公、孔子，难以论言。汉世文章之徒，陆贾、司马迁、刘子政、扬子云，其材能若奇，其称不由人。世传《诗》家鲁申公，《书》家千乘欧阳、公孙，不遭太史公，世人不闻。夫以业自显，孰与须人乃显？夫能纪百人，孰与廑能显其名？
或曰：“著作者，思虑间也，未必材知出异人也。居不幽，思不至。使著作之人，总众事之凡，典国境之职，汲汲忙忙，〔何〕暇著作？试使庸人积闲暇之思，亦能成篇八十数。文王日昃不暇食，周公一沐三握发，何暇优游为丽美之文于笔札？孔子作《春秋》，不用于周也。司马长卿不预公卿之事，故能作子虚之赋。扬子云存中郎之官，故能成《太玄经》，就《法言》。使孔子得王，《春秋》不作。〔籍〕长卿、子云为相，赋玄不工。”
答曰：文王日昃不暇食，此谓演《易》而益卦。周公一沐三握发，为周改法而制。周道不弊，孔子不作，休思虑间也！周法阔疏，不可因也。夫禀天地之文，发于胸臆，岂为间作不暇日哉？感伪起妄，源流气。管仲相桓公，致于九合。商鞅相孝公，为秦开帝业。然而二子之书，篇章数十。长卿、子云，二子之伦也。俱感，故才并；才同，故业钧。皆士而各著，不以思虑间也。问事弥多而见弥博，官弥剧而识弥泥。居不幽则思不至，思不至则笔不利。嚚顽之人，有幽室之思，虽无忧，不能著一字。盖人材有能，无有不暇。有无材而不能思，无有知而不能著。有鸿材欲作而无起，细知以问而能记。盖奇有无所因，无有不能言，两有无所睹，无不暇造作。
或曰：“凡作者精思已极，居位不能领职。盖人思有所倚着，则精有所尽索。著作之人，书言通奇，其材已极，其知已罢。案古作书者，多位布散盘解，辅倾宁危，非著作之人所能为也。夫有所逼，有所泥，则有所自，篇章数百。吕不韦作《春秋》举家徙蜀；淮南王作道书，祸至灭族；韩非著治术，身下秦狱。身且不全，安能辅国？夫有长于彼，安能不短于此？深于作文，安能不浅于政治？”
答曰：人有所优，固有所劣；人有所工，固有所拙。非劣也，志意不为也，非拙也，精诚不加也。志有所存，顾不见泰山；思有所至，有身不暇徇也。称干将之利，刺则不能击，击则不能刺，非刃不利，不能一旦二也。蛢弹雀则失鷃，射鹊则失雁，方员画不俱成，左右视不并见，人材有两为，不能成一。使干将寡刺而更击，舍鹊而射雁，则下射无失矣。人委其篇章，专为〔政〕治，则子产、子贱之迹不足侔也。古作书者，多立功不用也。管仲、晏婴，功书并作；商鞅、虞卿，篇治俱为。高祖既得天下，马上之计未败，陆贾造《新语》，高祖粗纳采。吕氏横逆，刘氏将倾，非陆贾之策，帝室不宁。盖材知无不能，在所遭遇，遇乱则知立功，有起则以其材著书者也。出口为言，著文为篇。古以言为功者多，以文为败者希。吕不韦、淮南王以他为过，不以书有非，使客作书，不身自为；如不作书，犹蒙此章章之祸。人古今违属，未必皆著作材知极也。邹阳举疏，免罪于梁。徐乐上书，身拜郎中。材能以其文为功于人，何嫌不能营卫其身？韩蚤信公子非，国不倾危。及非之死，李斯如奇，非以著作材极，不能复有为也。春物之伤，或死之也，残物不伤，秋亦不长。假令非不死，秦未可知。故才人能令其行可尊，不能使人必法己；能令其言可行，不能使人必采取之矣。
或曰：“古今作书者非一，各穿凿失经之实传，违圣人质，故谓之蕞残，比之玉屑。故曰：“蕞残满车，不成为道；玉屑满箧，不成为宝。”前人近圣，犹为蕞残，况远圣从后复重为者乎？其作必为妄，其言必不明，安可采用而施行？”
答曰：圣人作其经，贤者造其传，述作者之意，采圣人之志，故经须传也。俱贤所为，何以独谓经传是，他书记非？彼见经传，传经之文，经须而解，故谓之是。他书与书相违，更造端绪，故谓之非。若此者，韪是于《五经》。使言非《五经》，虽是不见听。使《五经》从孔门出，到今常令人不缺灭，谓之纯壹，信之可也。今《五经》遭亡秦之奢侈，触李斯之横议，燔烧禁防，伏生之休，抱经深藏。汉兴，收《五经》，经书缺灭而不明，篇章弃散而不具。晁错之辈，各以私意分拆文字，师徒相因相授，不知何者为是。亡秦无道，败乱之也。秦虽无道，不燔诸子。诸子尺书，文篇具在，可观读以正说，可采掇以示后人。后人复作，犹前人之造也。夫俱鸿而知，皆传记所称，文义与经相薄。何以独谓文书失经之实？由此言之，经缺而不完，书无佚本，经有遗篇。折累二者，孰与蕞残？《易》据事象，《诗》采民以为篇，《乐》须〔民〕欢，《礼》待民平。四经有据，篇章乃成。《尚书》、《春秋》，采掇史记。史记兴无异，以民事一意，《六经》之作皆有据。由此言之，书亦为本，经亦为末，末失事实，本得道质。折累二者，孰为玉屑？知屋漏者在宇下，知政失者在草野，知经误者在诸子。诸子尺书，文明实是。说章句者，终不求解扣明，师师相传，初为章句者，非通览之人也。', '', '', '有人说：“士人的议论高明，为什么一定要依靠借助文采呢？”
回答说：“人要具备文和质两个方面才算完美。物有只开花不结果的，有只结果不开花的。《易》上说：“圣人的情感通过文辞表达出来。”说出口就成了语言，把简扎编在一起就成了文章，文辞书写出来，真实的情感就显现了。体现德行的文采，就是社会的服饰。只见之于文字叫“文”，实际去做叫“德”，装饰在衣上叫“服”。所以说：道德越高的文饰就越多采，道德越明显的文饰就越鲜明。官大位尊的人道德丰盈，他的文饰就鲜明；君子的道德高尚，他的文饰就华丽。官高位尊文饰就繁多，道德高尚文饰就丰盛。华丽而又光滑的，是大夫享用的席子，曾子病重卧床，让儿子把这种席子换掉。由此说来，以穿的服饰来区别贤人，贤人是以文采的多少来区分高低。愚昧杰出不能分别，必须要靠文采来判断。不仅人类是如此，万物也都是这样。龙的鳞上有花纹，在蛇类中是神物；凤的羽毛有五色，在鸟类中是首领；老虎威猛，毛色花纹很多；龟智慧，背甲上有花纹。这四种动物的躯体花色华丽，在动物类中是圣贤。如果山没有林木，就是土山；地上不长草木，就是潟土；人没有文采，就是无用的人。土山上不会有麋鹿，潟土上不会生五谷，人没有体现德行的文采就不会是圣贤。上天多日月星辰而大地多山川陵谷，阴阳二气协和，圣贤承受此二气，仿效天地，所以文采繁多。祥瑞吉兆，没有不以文采来显现的。晋唐叔虞，鲁成季友，惠公夫人名叫仲子，他们生下来就很奇怪，有字样在他们手上。张良命该显贵，出逃时与神人相会，黄石老人授以兵书，终于被封为留侯。黄河神异，所以出现河图；洛水神灵，所以出现洛书。书籍所记载的怪奇的事物，不会出现在小水坑中。物以文采为外表，人以文采为根基。棘子成想取消文采，子贡就讥讽他。认为文采不足为奇的，是棘子成这类人。
　　能著书立说的是文儒，能解释经书的是世儒。两种儒生同在社会上，不知哪一种更优些。有人说：“文儒不如世儒。世儒解释圣人的经书，解释贤人的传述，意义道理广博，没有不见实效的，所以在官府有固定的职位；其中地位最高的是五经博士，聚集了许多门徒，招引会集了千里之外的学生，即使他本人死了，他的学说仍然流传于后代。文儒发表的是华而不实的议论，对社会毫无补益，所以没有固定的官职，不见他们有一个弟子门徒，他们本人死亡之后，没有人继承他们的学业。这就是文儒不如世儒的道理。”
　　回答说：并非如此。文儒世儒解释圣人的实情，是出于同一个动机，有同样的效验，目的都是想追随圣人。事情虽然不同但勉力从事是一致的，说的话不一样但道理却是相同的。为什么说文儒的议论对社会没有补益呢？世儒的学问容易做，所以世人学习的就多，平凡的事情都可以分出高低来，所以官府朝廷中都设置了他们的职位。文儒的学问，卓越非凡不循常规，人们很少读他们的书，他们的学问即使没有用来传授，门下即使没有弟子，但他们的著作文章奇伟不凡，世上的人同样流传他们的著述。那些世儒的都是虚妄的言论，只有这些文儒的才是有实际内容的文章。判断比较这两种儒生，哪一个贤明呢？考察古代贤能的人著书立说，自己用自己的学问，自己在社会上出名。世儒在当时即使尊贵，如果没有被文儒把他们写进书里，他们的事迹就不会流传。周公制礼作乐，名声流传而不灭绝。孔子编写《春秋》，名声流传而不灭绝。周公、孔子是圣人，难以用他们作例子来论证人才。汉代写书的人有陆贾、司马迁、刘子政、杨子云等人，他们的才能如同奇人一样，他们的名声不是靠别人得来的。世人传闻的《诗》家鲁申公，《书》家千乘郡的欧阳生和公孙弘，如果不是遇上太史公将他们记载下来，世上的人也不会知道他们。凭自己的学问出名的人与依赖别人才出名的人相比，哪个更好呢？能够记载一百个人的事迹使他们出名，与仅仅能使自己出名的人相比，哪个更高明呢？
　　有人说：“从事著述的人，只是有空闲时间来思考罢了，不一定是他才智出众不同于平常人。居住的地方不幽静，文思就不会到来。如果让从事著述的人，总揽各方面的事，掌管国境之内的职责，心情急切忙忙碌碌，他还有什么空闲去从事著述呢？假使让一个平庸的人把闲暇时的思虑积累起来，也能写出八十多篇文章。周文王忙于政务太阳偏西也没有空吃饭，周公洗一次头要中断三回来接待客人，还有什么空余时间悠闲自在地用笔在简扎上写出美丽的文章呢？孔子写成了《春秋》，是因为没有被周天子重用。司马长卿因为不能参预公卿的事务，所以能写成《子虚赋》。扬子云因为只当了中郎这样一个闲官，所以才能写成《太玄经》和《法言》。如果孔子能当上君王，《春秋》就写不出来；假如司马长卿和扬子云做了丞相，《子虚赋》和《太玄经》就不会有如此的巧妙。”
　　回答说：周文王忙得到太阳偏西了还没有空去吃饭，这是为推演《易》和增加卦数。周公洗一次头要中断三回，这是忙于为周朝改订法度和制礼作乐。周朝的礼制不败坏，孔子就不会写作《春秋》，并不是因为他有空闲时间来思考，而是因为周代的礼制已经不完备，不能再沿用了。他承受了天地的文采，发自内心而写作，哪里是闲着无事而写作以免荒废日月呢？这乃是对虚妄有所感触而引起的，就像水源会流淌热气会蒸腾一样非写不可。管仲辅佐齐桓公，以致于多次召集诸侯会盟；商鞅辅佐秦孝公，为秦国开创了帝王之业。然而他们两人写的书，也有几十篇之多。司马长卿和扬子云，也是管仲、商鞅这类人。由于他们都有所感触，因此才干不相上下；才干相同，因此学问相当。他们都在做官而又各自著书，并不是因为他们有空闲。过问的事情越多见识也就越广博，官务越繁忙见识也就越深厚。居住的地方不幽静文思就不会到来，文思不来下笔就不流利，顽固愚笨的人，有幽室供他思考，即使他无所忧虑，还是写不出一个字来。人才有能与不能，而不在于有没有空闲。有缺乏才智而不能思考的人，没有具备才智而不能写作的人。有才智很高想写作而无所缘起的人，没有才智很低而由于有空闲就能记录成文的人。大概奇才有无从下笔的，没有不会写作的，有看不到的，没有缺乏功夫进行写作的。
　　有人说：“凡是著书立说的人他的精力智慧已经穷尽，居官位就不能胜任职责。大约人的思想偏重于某个方面，那么精力也就会在这方面用尽。著书立说的人，写的东西精深奇特，他的才智已经到了极限，他的智慧已消耗殆尽。考察古代著书立说的人，大多处在闲散无事的地位；至于辅佐将要倾覆的社稷，安定将要危亡的国家，这不是著书立说的人所能做到的。有所推动，有所坚持，就会有所开端，写出成百篇的文章来。吕不韦写《吕氏春秋》，全家流放四川；淮南王作《淮南子》，遭祸至全家被处死；韩非著《韩非子》一书，自己被害死在秦国的狱中。自身尚且不能保全、怎么能辅佐国家呢？在那方面有所擅长，在这方面怎么能不有所不足呢？精通写文章，怎么能不在政治上有所不足呢？”
　　回答说：人有优的地方，必然也有劣的地方；人有工巧的时候，必然也有笨拙的时候。并不是由于低劣，而是心思没放在这方面；并不是由于笨拙，而是精神没有集中于这方面。心中存有某种志向，就会连泰山也看不见；思想达到了某种境地，自己就没有空闲来有所谋求。世人称赞干将的锋利，但它能刺就不能砍，能砍就不能刺，不是剑刃不锋利。而是同时不能起两种作用。用蛢弹雀就不能同时弹，用弓射鹊就不能同时射雁；方和圆不能同时都画成，眼睛向左右看不能同时两边都看见，一个人如果同时做两件事，结果一件事也做不成。如果干将不用来刺而改为砍，不用蛢射鹊而改为射雁，就一定能砍下来，一定能射中而不会失误了。人如果放弃他的写作，专心搞政治，那么子产和子贱的事迹就不值得一比了。古代著书的人，很多都是能建立功业的人，只是没有受到重用。管仲和晏婴，功业和著书都有所建树；商鞅和虞卿，文章和政治都有所成就。汉高祖得天下之后，使用武力治国的主张没有改变，陆贾写出《新语》，汉高祖大体都采用了。吕氏阴谋篡权，刘氏的天下将要倾覆，如果不是陆贾的政策，汉家帝室就不会得安宁。有才智的人没有办不到的事情，关键在于他的遭遇如何，如果遇到乱世，就会去建立功业，有所感触，就会以他的才智从事著述。说出口就是语言，写成字就是文章。古代凭说话建功的人多，为写文章而遭受败家灭族的人极少。吕不韦、淮南王是由于别的事而犯罪，不是因为著书才有罪的。让门客来写书，自己并不写，即使不写书，也仍然要蒙受灾祸，灾祸害人，从古至今接连不断，不一定都是在写作上才智穷尽了的人。邹阳在狱中上书，被梁孝王免去了罪；徐乐给汉武帝上书，自己被拜为郎中。才智能以文章的形式有功于人，为什么要怀疑它不能保护自身呢？韩王安如果早点听从公子韩非的意见，国家不会有倾覆的危险。至于韩非的死，是因为李斯嫉妒他才能出众，并不是由于他著书才智竭尽，不能在政治上再有作为的缘故。春天植物受到伤害，有的因此而死了；有些被摧残过的植物如果不再受伤害，到秋天也会长大成熟。如果韩非不死的话，秦王朝的前途就很难说了。所以有才学的人能够使自己的德行受人尊敬，却不能使别人必定效法自己；能够使自己的议论切实可行，却不能使别人必定采纳自己的主张。
　　有人说：“从古到今写书的人不止一个，各自牵强附会失去了经传的真实内容，违背了圣人的本质意义，所以称之为残缺之物，把它比作玉屑。因此说：‘残缺之物装满车，不能成为什么学说；玉屑装满箱子，不能成为什么宝物。”前人最接近圣人，还被称为残缺之物，何况远离圣人随前人之后重新来写书的人呢？他们的著作必定是愚妄的，他们的言论必定是不贤明的，怎么能够采用而用来施行呢？”
　　回答说：圣人写经，贤人作传，要阐述著书人的本意，采集圣人的遗志，所以经必须要有传来解释。都是贤人所写的，为什么偏认为经传是对的，而其他的书和记都不对呢？那些可以见到的经传以及解释经的文章，说明经必须要传才能解释清楚，所以说它们是对的。其他书与传上的解释不相符合，别创一说，所以说它们不对。像这样的话，以五经作为是非标准，假如说的话不符合五经，即使完全正确，也不会被人听信。假使五经从孔子门中出来，至今毫无残缺散失，称得上是纯粹完整的东西，相信它是可以的。现在五经已经遭受了秦朝的糟踏，受到李斯主张的触犯，焚烧并禁止流传，伏生这类人，怀抱经书深藏在山中。汉朝兴起，征收五经，经书残缺散失而下落不明，篇章亡佚散失而不完备。晁错这类人，各按自己的想法，分割拆散文字的本意，师徒相继沿袭传授，不知道哪一个是对的。秦朝无道义，所以就败乱了。秦朝即使无道，并没有烧诸子的著作。诸子的著作，文章篇目全都存在，可以阅读用来纠正各种言论，可以拿来给后人看。后人重新写书，就和前人创作一样。都博学而有智慧，全是史书所称道的，文义与经书不相上下，为什么单认为诸子的著作偏离了经书的真实呢？由此说来，经书残缺而不完整，诸子百家的书没有散失不全的，而经书反而有遗失的篇目。分析比较二者，谁是支离破碎的呢？《易》是根据事物的表象写成的，《诗》是向民间采集而编辑成篇的，《乐》的成书有赖于老百姓的欢愉，《礼》的成文全靠老百姓安乐讲礼节。四经都有所依据，它的篇章才能写成。《尚书》和《春秋》，采取了史官的记载。史官的记载与诸子的著作没有区别，与依据百姓和事象写成的经书是同一个道理。六经的写作全都有所依据。由此说来，诸子的书是根本，经书则是枝节，枝节偏离了事实，根本却具备了道的实质。分析比较二者，谁才是玉屑呢？知道房屋漏雨的人在房屋下，知道政治有失误的人在民间，知道经书错误的人在诸子。诸子的著述，文句明白，事情真实。解释经书章句的人不想求得彻底地理解而去问个一清二楚，一代代师承下去，仍就如此解释经书章句的人，就不会是通晓古今的人。', NULL, '', 'indent', 1545406749, '5c1c98564773f7173642c350', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640846, '潜书·权实', NULL, 14, 2, 1, 1, '唐甄', NULL, 36933, '5b617e0e808ca4006ff320e9', '清', 'wen', '文', 'https://baike.baidu.com/item/%E6%BD%9C%E4%B9%A6/11014547?fr=aladdin', '', '群臣奏入，下于有司；公卿集议，复奏行之。其所行者，著为故事，因时增易，百职准以决事。自汉以来皆然，舍是无以为政。然有治不治者，以实则治，以文则不治。若徒以文也，譬之优偶之戏，衣冠言貌，陈事辨理，无不合度，而岂其实哉！', '', '', '群臣上奏自己的奏疏，分门别类归总到有司那里去，公卿在一起决议，再向上奏表而后执行。这样的一套体制，一方面，继承了以前的体制，另一方面，与时增益，百官得以以此来决定事情。从汉代以来就是这样，不这样就无法实行政事。但是即便是这样，也有天下得到治理的时候，也有天下没有得到治理的时候。当百官都以实干为主的时候，天下就得到了治理，当百官都文过饰非，粉饰太平的时候，天下就得不到治理。如果仅仅是文过饰非，粉饰太平的话，就像是木偶戏一样，衣冠言貌，所诀议的事情，事理，都是徒有其表，知其然不知其所以然的（被人操纵的，而不是自然而然的），这样不就脱离实际了么？	', NULL, '', 'indent', 1545412315, '5c1cae79fb4ffe005f1ec5a7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640847, '因擒鬼章论西羌夏人事宜札子', NULL, 28, 3406, 1, 1, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'wen', '文', '', '', '夫为国不可以生事，亦不可以畏事。畏事之弊，与生事均。譬如无病而服药，与有病而不服药，皆可以杀人。夫生事者，无病而服药也。畏事者，有病而不服药也。乃者阿里骨之请，人人知其不当予，而朝廷予之，以求无事，然事之起，乃至于此，不几于有病而不服药乎？今又欲遽纳夏人之使，则是病未除而药先止，其与几何。', '', '', '', NULL, '', 'indent', 1545412433, '5c1caef99f54540070712142', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640848, '东周列国志第二十六回', NULL, 8, 7, 1, 1, '冯梦龙', NULL, 17086, '5858eb7aac502e0067086998', '明', 'wen', '文', '', '', '第二十六回　歌扊扅百里认妻　获陈宝穆公证梦
    话说秦穆公深知百里奚之才，欲爵为上卿，百里奚辞曰：“臣之才，不如臣友蹇叔十倍，君欲治国家，请任蹇叔而臣佐之。”
    穆公曰：“子之才，寡人见之真矣，未闻蹇叔之贤也。”
    奚对曰：“蹇叔之贤，岂惟君未之闻。虽齐、宋之人，亦莫之闻也，然而臣独知之。臣尝出游于齐，欲委质于公子无知。蹇叔止臣曰：‘不可。''臣因去齐，得脱无知之祸。嗣游于周，欲委质于王子颓，蹇叔复止臣曰：‘不可。''臣复去周，得脱子颓之祸。后臣归虞，欲委质于虞公，蹇叔又止臣曰：‘不可。''臣时贫甚，利其爵禄，姑且留事，遂为晋俘。夫再用其言，以脱于祸，一不用其言，几至杀身，此其智胜于中人远矣。今隐于宋之鸣鹿村，宜速召之。”
    穆公乃遣公子絷假作商人，以重币聘蹇叔于宋，百里奚另自作书致意。
    公子絷收拾行囊，驾起犊车二乘，径投鸣鹿村来。见数人息耕于陇上，相赓而歌。歌曰：
    山之高兮无撵，途之泞兮无烛。
    相将陇上兮，泉甘而土沃。
    勤吾四体兮，分吾五谷。
    三时不害兮，饔飧足。
    乐此天命兮无荣辱！
    絷在车中，听其音韵，有绝尘之致，乃叹谓御者曰：“古云：里有君子，而鄙俗化。”今入蹇叔之乡，其耕者皆有高遁之风，信乎其贤也。”乃下车，问耕者曰：“蹇叔之居安在？”耕者曰：“子问之何为？”
    絷曰：“其故人百里奚有书，托吾致之。”
    耕者指示曰：“前去竹林深处，左泉右石，中间一小茅庐，乃其所也。”
    絷拱手称谢，复登车，行将半里，来至其处。絷举目观看，风景果是幽雅。陇西居士有隐居诗云：
    翠竹林中景最幽，人生此乐更何求？
    数方白石堆云起，一道清泉接涧流。
    得趣猿猴堪共乐，忘机麋鹿可同游。
    红尘一任漫天去，高卧先生百不忧。
    絷停车于草庐之外，使从者叩其柴扉。有一小童子，启门而问曰：“佳客何来？”
    絷曰：“吾访蹇先生来也。”
    童子曰：“吾主不在。”
    絷曰：“先生何往？”
    童子曰：“与邻叟观泉于石梁，少顷便回。”
    絷不敢轻造其庐，遂坐于石上以待之。
    童子将门半掩，自入户内。
    须臾之间，见一大汉，浓眉环眼，方面长身，背负鹿蹄二只，从田塍西路而来。絷见其容貌不凡，起身迎之，那大汉即置鹿蹄于地，与絷施礼。絷因叩其姓名，大汉答曰：“某蹇氏，丙名，字白乙。”
    絷曰：“蹇叔是君何人？”
    对曰：“乃某父也。”
    絷重复施礼，口称：“久仰。”
    大汉曰：“足下何人，到此贵干？”
    絷曰：“有故人百里奚，今仕于秦，有书信托某奉候尊公。”
    蹇丙曰：“先生请入草堂少坐，吾父即至矣。”言毕，推开双扉，让公子絷先入。蹇丙复取鹿蹄负之，至于草堂。童子收进鹿蹄。蹇丙又复施礼，分宾主坐定。
    公子絷与蹇丙谈论些农桑之事，因及武艺，丙讲说甚有次第，絷暗暗称奇，想道：“有其父方有其子，井伯之荐不虚也。”
    献茶方罢，蹇丙使童子往门首伺候其父。少顷，童子报曰：“翁归矣！”
    却说蹇叔与邻叟二人，肩随而至，见门前有车二乘，骇曰：“吾村中安得有此车耶？”蹇丙趋出门外，先道其故。蹇叔同二叟进入草堂，各各相见，叙次坐定。
    蹇叔曰：“适小儿言吾弟井伯有书，乞以见示。”公子絷遂将百里奚书信呈上，蹇叔启缄观之，略曰：
    奚不听兄言，几蹈虞难。幸秦君好贤，赎奚于牧竖之中，委以秦政。奚自量才智不逮恩兄，举兄同事。秦君敬慕若渴，特命大夫公子絷布币奉迎。惟冀幡然出山，以酬生平未足之志，如兄恋恋山林，奚亦当弃爵禄，相从于鸣鹿之乡矣。
    蹇叔曰：“井伯何以见知于秦君也？”公子絷将百里奚为媵逃楚，秦君闻其贤，以五羊皮赎归始末，叙述一遍：“今寡君欲爵以上卿，井伯自言不及先生，必求先生至秦，方敢登仕。寡君有不腆之币，使絷致命。”言讫，即唤左右于车厢中取出征书礼币，排列草堂之中。
    邻叟俱山野农夫，从未见此盛仪，相顾惊骇，谓公子絷曰：“吾等不知贵人至此，有失回避。”
    絷曰：“何出此言？寡君望蹇先生之临，如枯苗望雨，烦二位老叟相劝一声，受赐多矣！”二叟谓蹇叔曰：“既秦邦如此重贤，不可虚贵人来意。”蹇叔曰：“昔虞公不用井伯，以致败亡。若秦君肯虚心仕贤，一井伯已足。老夫用世之念久绝，不得相从，所赐礼币，望乞收回，求大夫善为我辞。”
    公子絷曰：“若先生不往，井伯亦必不独留！”
    蹇叔沉吟半晌，叹曰：“井伯怀才未试，求仕已久，今适遇明主，吾不得不成其志。勉为井伯一行，不久仍归耕于此耳！”
    童子报：“鹿蹄已熟！”
    蹇叔命取床头新酿， 之以奉客。公子絷西席，二叟相陪，瓦杯木箸，宾主劝酬，欣然醉饱。不觉天色已晚，遂留絷于草堂安宿。
    次早，二叟携樽饯行，依前叙坐。良久，公子絷夸白乙之才，亦要他同至秦邦，蹇叔许之。乃以秦君所赠礼币，分赠二叟，嘱咐看觑家间：“此去不久，便再得相叙！”再吩咐家人：“勤力稼穑，勿致荒芜！”二叟珍重而别。
    蹇叔登车，白乙丙为御。公子絷另自一车，并驾而行。
    夜宿晓驰，将近秦郊，公子絷先驱入朝，参谒了秦穆公，言：“蹇先生已到郊外，其子蹇丙亦有挥霍之才，臣并取至，以备任使！”
    穆公大喜，乃命百里奚往迎。
    蹇叔既至，穆公降阶加礼，赐坐而问之曰：“井伯数言先生之贤，先生何以教寡人乎？”
    蹇叔对曰：“秦僻在西土，邻于戎、狄，地险而兵强，进足以战，退足以守。所以不列于中华者，威德不及故也！非威何畏，非德何怀，不畏不怀，何以成霸？”
    穆公曰：“威与德，二者孰先？”
    蹇叔对曰：“德为本，威济之；德而不威，其国外削；威而不德，其民内溃。” （奇*书*网.整*理*提*供）
    穆公曰：“寡人欲布德而立威，何道而可？”
    蹇叔对曰：“秦杂戎俗，民鲜礼教，等威不辨，贵贱不明，臣请为君先教化而后刑罚。教化既行，民知尊敬其上，然后恩施而知感，刑用而知惧，上下之间，如手足头目之相为。管夷吾节制之师，所以号令天下而无敌也！”
    穆公曰：“诚如先生之言，遂可以霸天下乎？”
    蹇叔对曰：“未也！夫霸天下者有三戒：毋贪、毋忿、毋急。贪则多失，忿则多难，急则多蹶。夫审大小而图之，乌用贪；衡彼己而施之，乌用忿；酌缓急而布之，乌用急。君能戒此三者，于霸也近矣！”
    穆公曰：“善哉言乎。请为寡人酌今日之缓急！”
    蹇叔对曰：“秦立国西戎，此祸福之本也。今齐侯已耄，霸业将衰。君诚善抚雍渭之众，以号召诸戎，而征其不服者。诸戎既服，然后敛兵以俟中原之变，拾齐之遗，而布其德义，君虽不欲霸，不可得而辞矣！”
    穆公大悦曰：“寡人得二老，真庶民之长也。”乃封蹇叔为右庶长，百里奚为左庶长，位皆上卿，谓之“二相”。并召白乙丙为大夫。
    自二相兼政，立法教民，兴利除害，秦国大治。史官有诗云：
    子絷荐奚奚荐叔，转相汲引布秦庭。
    但能好士如秦穆，人杰何须问地灵？
    穆公见贤才多出于异国，益加采访。公子絷荐秦人西乞术之贤，穆公亦召用之。百里奚素闻晋人繇余负经纶之略，私询于公孙枝。枝曰：“繇余在晋不遇，今已仕于西戎矣。”奚叹惜不已。
    却说百里奚之妻杜氏，自从其夫出游，纺绩度日，后遇饥荒，不能存活，携其子趁食他乡。展转流离，遂入秦国，以浣衣为活。其子名视，字孟明，日与乡人打猎角艺，不肯营生，杜氏屡谕不从。及百里奚相秦，杜氏闻其姓名，曾于车中望见，未敢相认。因府中求浣衣妇，杜氏自愿入府浣衣。勤于捣濯，府中人皆喜，然未得见奚之面也。
    一日，奚坐于堂上，乐工在庑下作乐，杜氏向府中人曰：“老妾颇知音律，愿引至庑，一听其声。”
    府中人引至庑下，言于乐工，问其所习，杜氏曰：“能琴亦能歌。”乃以琴授之。
    杜氏援琴而鼓，其声凄怨，乐工俱倾耳静听，自谓不及，再使之歌，杜氏曰：“老妾自流移至此，未尝发声，愿言于相君，请得升堂而歌之。”
    乐工禀知百里奚，奚命之立于堂左，杜氏低眉敛袖，扬声而歌，歌曰：
    百里奚，五羊皮！
    忆别时，烹伏雌，
    舂黄齑，炊扊扅。
    今日富贵忘我为？
    百里奚，五羊皮！
    父粱肉，子啼饥，
    夫文绣，妻浣衣。
    嗟乎！
    富贵忘我为？
    百里奚，五羊皮！
    昔之日，君行而我啼；
    今之日，君坐而我离。
    嗟乎！
    富贵忘我为？
    百里奚闻歌愕然，召至前询之，正其妻也。遂相持大恸，良久，问：“儿子何在？”杜氏曰：“村中射猎。”使人召之。是日，夫妻父子再得完聚。
    穆公闻百里奚妻子俱到，赐以粟千钟，金帛一车。
    次日，奚率其子孟明视朝见谢恩，穆公亦拜视为大夫，与西乞术、白乙丙并号将军，谓之“三帅”，专掌征伐之事。姜戎子吾离，桀骜侵掠，三帅统兵征之，吾离兵败奔晋，遂尽有瓜州之地。
    时西戎主赤斑见秦人强盛，使其臣繇余聘秦，以观穆公之为人，穆公与之游于苑囿，登三休之台，夸以宫室苑囿之美。
    繇余曰：“君之为此者，役鬼耶，抑役人耶？役鬼劳神，役人劳民。”
    穆公异其言，曰：“汝戎夷无礼乐法度，何以为治？”
    繇余笑曰：“礼乐法度，此乃中国所以乱也。自上圣创为文法，以约束百姓，仅仅小治，其后日渐骄淫，借礼乐之名，以粉饰其身；假法度之威，以督责其下。人民怨望，因生篡夺。若戎夷则不然，上含淳德以遇其下，下怀忠信以事其上，上下一体，无形迹之相欺，无文法之相扰，不见其治，乃为至治。”
    穆公默然，退而述其言于百里奚。奚对曰：“此晋国之大贤人，臣熟闻其名矣。”
    穆公蹴然不悦曰：“寡人闻之：‘邻国有圣人，敌国之忧也。''今繇余贤而用于戎，将为秦患奈何？”
    奚对曰：“内史廖多奇智，君可谋之。”穆公即召内史廖，告以其故。
    廖对曰：“戎主僻处荒徼，未闻中国之声。君试遗之女乐，以夺其志；留繇余不遣，以爽其期。使其政事怠废，上下相疑。虽其国可取，况其臣乎？”
    穆公曰：“善。”乃与繇余同席而坐，共器而食，居常使蹇叔、百里奚、公孙枝等，轮流作伴，叩其地形险夷，兵势强弱之实，一面装饰美女能音乐者六人，遣内史廖至戎报聘，以女乐献之。戎主赤斑大悦，日听音而夜御女，遂疏于政事。
    繇余留秦一年乃归。戎主怪其来迟，繇余曰：“臣日夜求归，秦君固留不遣。”
    戎主疑其有二心于秦，意颇疏之。繇余见戎主耽于女乐，不理政事，不免苦口进谏，戎主拒而不纳。穆公因密遣人招之，繇余弃戎归秦，即擢亚卿，与二相同事。繇余遂献伐戎之策，三帅兵至戎境，宛如熟路，戎主赤斑不能抵敌，遂降于秦。后人有诗云：
    虞违百里终成虏，戎失繇余亦丧邦。
    毕竟贤才能干国，请看齐霸与秦强！
    西戎主赤斑，乃诸戎之领袖，向者诸戎俱受服役。及闻赤斑归秦，无不悚惧，纳土称臣者，相继不绝。
    穆公论功行赏，大宴群臣，群臣更番上寿，不觉大醉，回宫一卧不醒，宫人惊骇。事闻于外，群臣皆叩宫门问安。世子蔤召太医入宫诊脉，脉息如常，但闭目不能言动。太医曰：“是有鬼神。”
    欲命内史廖行祷，内史廖曰：“此是尸厥，必有异梦，须俟其自复，不可惊之，祷亦无益。”
    世子蔤守于床席之侧，寝食俱不敢离，直候至第五日，穆公方醒，颡间汗出如雨，连叫：“怪哉！”
    世子蔤跪而问曰：“君体安否，何睡之久也？”
    穆公曰：“顷刻耳。” 曰：“君睡已越五日，得无有异梦乎？”
    穆公惊问曰：“汝何以知之？”
    世子蔤曰：“内史廖固言之。”
    穆公乃召廖至榻前，言曰：“寡人今者梦一妇人，妆束宛如妃嫔，容貌端好，肌如冰雪，手握天符，言奉上帝之命，来召寡人，寡人从之，忽若身在云中，缥缈无际，至一宫阙，丹青炳焕，玉阶九尺，上悬珠帘，妇人引寡人拜于阶下，须臾帘卷，见殿上黄金为柱，壁衣锦绣，精光夺目，有王者冕旒华衮，凭玉几上坐，左右侍立，威仪甚盛，王者传命：‘赐礼！''有如内侍者，以碧玉斝赐寡人酒，甘香无比，王者以一简授左右，即闻堂上大声呼寡人名曰：‘任好听旨，尔平晋乱！''如是者再。妇人遂教寡人拜谢，复引出宫阙，寡人问妇人何名，对曰：‘妾乃宝夫人也，居于太白山之西麓，在君宇下，君不闻乎？妾夫叶君，别居南阳，或一二岁来会妾，君能为妾立祠，当使君霸，传名万载。''寡人因问：‘晋有何乱，乃使寡人平之？''宝夫人曰：‘此天机不可预泄。''已闻鸡鸣，声大如雷霆，寡人遂惊觉。不知此何祥也？”
    廖对曰：“晋侯方宠骊姬，疏太子，保无乱乎？天命及君，君之福也！”
    穆公曰：“宝夫人何为者？”
    廖对曰：“臣闻先君文公之时，有陈仓人于土中得一异物，形如满囊，色间黄白，短尾多足，嘴有利喙。陈仓人谋献之先君，中途遇二童子，拍手笑曰：‘汝虐于死人，今乃遭生人之手乎？''陈仓人请问其说，二童子曰：‘此物名猬，在地下惯食死人之脑，得其精气，遂能变化，汝谨持之。''猬亦张喙忽作人言曰：‘彼二童子者，一雌一雄，名曰陈宝，乃野雉之精，得雄者王，得雌者霸。''陈仓人遂舍猬而逐童子，二童子忽化为雉飞去。陈仓人以告先君，命书其事于简，藏之内府，臣实掌之，可启而视也。夫陈仓正在太白山之西，君试猎于两山之间，以求其迹，则可明矣！”穆公命取文公藏简观之，果如廖之语，因使廖详记其梦，并藏内府。
    次日，穆公视朝，群臣毕贺。穆公遂命驾车，猎于太白山。迤逦而西，将至陈仓山，猎人举网得一雉鸡，玉色无瑕，光采照人，须臾化为石鸡，色光不减，猎者献于穆公。内史廖贺曰：“此所谓宝夫人也。得雌者霸，殆霸征乎？君可建祠于陈仓，必获其福。”
    穆公大悦，命沐以兰汤，覆以锦衾，盛以玉匮。即日鸠工伐木，建祠于山上，名其祠曰：“宝夫人祠。”改陈仓山为宝鸡山，有司春秋二祭，每祭之晨，山上闻鸡鸣，其声彻三里之外。间一年或二年，望见赤光长十余丈，雷声殷殷然，此乃叶君来会之期。叶君者，即雄雉之神，所谓别居南阳者也。至四百余年后，汉光武生于南阳，起兵诛王莽，复汉祚，为后汉皇帝，乃是得雄者王之验。
    毕竟秦穆公如何定晋乱，再看下回分解。', '', '', '', NULL, '', 'indent', 1545413230, '5c1caf95fb4ffe005f1ed3ca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640849, '资治通鉴• 周纪一', NULL, 14, 1577, 1, 1, '司马光', NULL, 10351, '57b9c6d179bc4400639cc661', '宋', 'wen', '文', 'https://baike.baidu.com/item/%E8%B5%84%E6%B2%BB%E9%80%9A%E9%89%B4/521532?fromtitle=%E3%80%8A%E8%B5%84%E6%B2%BB%E9%80%9A%E9%89%B4%E3%80%8B&fromid=320741', '', '臣光曰：智伯之亡也，才胜德也。夫才与德异，而世俗莫之能辨，通谓之贤，此其所以失人也。夫聪察强毅之谓才，正直中和之谓德。才者，德之资也；德者，才之帅也。……是故才德全尽谓之圣人，才德兼亡谓之愚人，德胜才谓之君子，才胜德谓之小人。凡取人之术，苟不得圣人、君子而与之，与其得小人，不若得愚人。何则？君子挟才以为善，小人挟才以为恶。挟才以为善者，善无不至矣；挟才以为恶者，恶亦无不至矣。', '《资治通鉴》（常简作《通鉴》），由北宋司马光主编的一部多卷本编年体史书，共294卷，历时19年完成。主要以时间为纲，事件为目，从周威烈王二十三年（公元前403年）写起，到五代后周世宗显德六年（公元959年）征淮南停笔，涵盖16朝1362年的历史。', '', '', NULL, '', 'indent', 1565181757, '5c1cb01e67f356005fd9594e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640851, '荀子 · 王制', NULL, 13, 13, 1, 1, '荀子', NULL, 10279, '57b902bbdf0eea006334f0d0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E8%8D%80%E5%AD%90%C2%B7%E7%8E%8B%E5%88%B6/8495669?fr=aladdin', '', '北海则有走马吠犬焉，然而中国得而畜使之；南海则有羽翮、齿革、曾青、丹干焉，然而中国得而财之；东海则有紫鱼盐焉，然而中国得而衣食之；西海则有皮革、文旄焉，然而中国得而用之。故泽人足乎木，山人足乎鱼，农夫不斫削、不陶冶而足械用，工贾不耕田而足菽粟。故虎豹为猛矣，然君子剥而用之。故天之所覆，地之所载，莫不尽其美、致其用，上以饰贤良，下以养百姓而安乐之。夫是之谓大神。曰：“天作高山，大王荒之；彼作矣，文王康之。”此之谓也。
此类行杂，以一行万，始则终，终则始，若环之无端也，舍是而天下以衰矣。天地者，生之始也；礼义者，治之始也；君子者，礼义之始也。为之，贯之，积重之，致好之者，君子之始也。故天地生君子，君子理天地；君子者，天地之参也，万物之总也，民之父母也。无君子则天地不理，礼义无统，上无君师，下无父子，夫是之谓至乱。君臣、父子、兄弟、夫妇，始则终，终则始，与天地同理，与万世同久，夫是之谓大本。故丧祭、朝聘、师旅一也。贵贱、杀生、与夺一也。君君、臣臣、父父、子子、兄兄、弟弟一也。农农、士士、工工、商商一也。
水火有气而无生，草木有生而无知，禽兽有知而无义；人有气、有生、有知，亦且有义，故最为天下贵也。力不若牛，走不若马，而牛马为用，何也？曰：人能群，彼不能群也。人何以能群？曰：分。分何以能行？曰：义。故义以分则和，和则一，一则多力，多力则强，强则胜物，故宫室可得而居也。故序四时，裁万物，兼利天下，无它故焉，得之分义也。
故人生不能无群，群而无分则争，争则乱，乱则离，离则弱，弱则不能胜物，故宫室不可得而居也，不可少顷舍礼义之谓也。能以事亲谓之孝，能以事兄为之弟，能以事上谓之顺，能以使下谓之君。君者，善群也。群道当则万物皆得其宜，六畜皆得其长，群生皆得其命。故养长时则六畜育，杀生时则草木殖，政令时则百姓一，贤良服。
圣王之制也，草木荣华滋硕之时则斧斤不入山林，不夭其生，不绝其长也；鼋鼍、鱼、鳖、鳅鳝孕别之时，罔罟毒药不入泽，不夭其生，不绝其长也；春耕、夏耘、秋收、冬藏四者不失时，故五谷不绝而百姓有余食也；污池渊沼川泽谨其时禁，故鱼鳖优多而百姓有余用也；斩伐养长不失其时，故山林不童而百姓有余材也。
圣王之用也，上察于天，下错于地，塞备天地之间，加施万物之上；微而明，短而长，狭而广，神明博大以至约。故曰：一与一是为人者，谓之圣人。', '《王制》出自《礼记》是指古代君主治理天下的规章制度，内容涉及封国、职官、爵禄、祭祀、葬丧、刑罚、建立成邑、选拨官吏以及学校教育等方面的制度。', '', '', NULL, '', 'indent', 1545413059, '5c1cb155808ca400733919b1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640852, '治国犹栽树', NULL, 13, 377, 1, 1, '无名氏', NULL, 10156, '57b9dc73a633bd005d303896', '唐', 'wen', '文', '', '', '唐太宗谓侍臣曰：“往昔初平京师，宫中美女珍玩，无院不满。炀帝意犹不足，征求不已，兼东征西讨，穷兵黩武，百姓不堪，遂致灭亡，此皆朕所目见。故夙夜孜孜，惟欲清净，使天下无事。遂得徭役不兴，年谷丰稔，百姓安乐。夫治国犹栽树，本根不摇，则枝叶茂盛。君能清净，百姓何得不安乐乎？”', '', '', '贞观九年之时，唐太宗对侍臣说：“以前（隋炀帝）刚刚平定了京师，宫中的美女和珍奇玩物，没有一个院子不是满满的。隋炀帝仍旧不满足，搜刮不停，并且东西讨伐，用尽兵力发动战争，老百姓苦不堪言，所以导致了灭亡。这些都是我亲眼所见的。因此我从早到晚孜孜不倦，只是希望清清静静，这使得天下平安无事。于是就能不兴徭役，谷物丰收，百姓安居乐业。治理国家就像种树一样，根基不动摇，才会枝繁叶茂。帝王能做到清静，百姓怎么会不安居乐业呢？”', NULL, '', 'indent', 1545413390, '5c1cb2a9fb4ffe005f1efd92', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640853, '汉书 · 纪 · 宣帝纪', NULL, 0, 136, 0, 2, '班固', NULL, 18080, '5830da0e2e958a0069d595a2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E6%B1%89%E4%B9%A6%E5%AE%A3%E5%B8%9D%E7%BA%AA/2509837?fr=aladdin', '', '孝宣皇帝，武帝曾孙，戾太子孙也。太子纳史良娣，生史皇孙。皇孙纳王夫人，生宣帝，号曰皇曾孙。生数月，遭巫蛊事，太子、良娣、皇孙、王夫人皆遇害。语在《太子传》。曾孙虽在襁褓，犹坐收系郡邸狱。而邴吉为廷尉监，治巫蛊于郡邸，怜曾孙之亡辜，使女徒复作淮阳赵征卿、渭城胡组更乳养，私给衣食，视遇甚有恩。
巫蛊事连岁不决。至后元二年，武帝疾，往来长杨、五柞宫，望气者言长安狱中有天子气，上遣使者分条中都官狱系者，轻、重皆杀之。内谒者令郭穰夜至郡邸狱，吉拒闭，使者不得入，曾孙赖吉得全。因遭大赦，吉乃载曾孙送祖母史良娣家。语在吉及外戚《传》。
后有诏掖庭养视，上属籍宗正。时掖庭令张贺尝事戾太子，思顾旧恩，哀曾孙，奉养甚谨，以私钱供给教书。既壮，为取暴室啬夫许广汉女。曾孙因依倚广汉兄弟及祖母家史氏。受《诗》于东海澓中翁，高材好学，然亦喜游侠，斗鸡走马，具知闾里奸邪，吏治得失。数上下诸陵，周遍三辅，常困于莲勺卤中。尤乐杜、鄠之间，率常在下杜。时会朝请，舍长安尚冠里，身足下有毛，卧居数有光耀。每买饼，所从买家辄大雠，亦以是自怪。
元平元年四月，昭帝崩，毋嗣。大将军霍光请皇后征昌邑王。六月丙寅，王受皇帝玺、绶，尊皇后曰皇太后。癸已，光奏王贺淫乱，请废。语在贺及光《传》。
秋七月，光奏议曰：“礼，人道亲亲故尊祖，尊祖故敬宗。大宗毋嗣，择支子孙贤者为嗣。孝武皇帝曾孙病已，有诏掖庭养视，至今年十八，师受《诗》、《论语》、《孝经》，操行节俭，慈仁爱人，可以嗣孝昭皇帝后，奉承祖宗，子万姓。”奏可。遣宗正德至曾孙尚冠里舍，洗沐，赐御府衣。太仆以軨猎车奉迎曾孙，就齐宗正府。庚申，入未央宫，见皇太后，封为阳武侯。已而群臣奉上玺、绶，即皇帝位，谒高庙。
八月已巳，丞相敞薨。
九月，大赦天下。
十一月壬子，立皇后许氏。赐诸侯王以下金钱，至吏、民鳏、寡、孤、独各有差。皇太后归长乐宫。长乐宫初置屯卫。
本始元年春正月，募郡国吏、民訾百万以上徙平陵。遣使者持节诏郡国二千石谨牧养民而风德化。
大将军光稽首归政，上谦让委任焉。论定策功，益封大将军光万七千户，车骑将军光禄勋富平侯安世万户。诏曰：“故丞相安平侯敞等居位守职，与大将军光、车骑将军安世建议定策，以安宗庙，功赏未加而甍。其益封敞嗣子忠及丞相阳平侯义、度辽将军平陵侯明友、前将军龙雒侯增、太仆建平侯延年、太常蒲伺昌、谏大夫宜春侯谭、当涂侯平、杜侯屠耆堂、长信少府关内侯胜邑户各有差。封御史大夫广明为昌水侯，后将军充国为营平侯，大司农延年为阳城侯，少府乐成为爰氏侯，光禄大夫迁为平丘侯。赐右扶风德、典属国武、廷尉光、宗正德、大鸿胪贤、詹事畸、光禄大夫吉、京辅都尉广汉爵皆关内侯。德、武食邑。”
夏四月庚午，地震。诏内郡国举文学高第各一人。
五月，凤皇集胶东、千乘。赦天下。赐吏二千石、诸侯相、下至中都官、宦吏、六百石爵，各有差，自左更至五大夫。赐天下人爵各一级，孝者二级，女子百户牛、酒。租税勿收。
六月，诏曰：“故皇太子在湖，未有号谥、岁时祠。其议谥，置园邑。”语在《太子传》。
秋七月，诏立燕剌王太子建为广阳王，立广陵王胥少子弘为高密王。
二年春，以水衡钱为平陵，徙民起第宅。
大司农阳城侯田延年有罪，自杀。
夏五月，诏曰：“朕以眇身奉承祖宗，夙夜惟念孝武皇帝躬履仁义，选明将，讨不服，匈奴远遁，平氐、羌、昆明、南越，百蛮乡风，款塞来享；建太学，修郊祀，定正朔，协音律；封泰山，塞宣房，符瑞应，宝鼎出，白麟获。功德茂盛，不能尽宣，而庙乐未称，其议奏。”有司奏请宜加尊号。
六月庚午，尊孝武庙为世宗庙，奏《盛德》、《文始》、《五行》之舞，天子世世献。武帝巡狩所幸之郡国，皆立庙。赐民爵一级，女子百户牛、酒。
匈奴数侵边，又西伐乌孙。乌孙昆弥及公主因国使者上书，言昆弥愿发国精兵击匈奴，唯天子哀怜，出兵以救公主。
秋，大发兴调关东轻车锐卒，选郡国吏三百石伉健习骑射者，皆从军。御史大夫田广明为祁连将军，后将军赵充国为蒲类将军，云中太守田顺为虎牙将军，及度辽将军范明友、前将军韩增，凡五将军，兵十五万骑，校尉常惠持节护乌孙兵，咸击匈奴。
三年春正月癸亥，皇后许氏崩。戊辰，五将军师发长安。
夏五月，军罢。祁连将军广明、虎牙将军顺有罪，下有司，皆自杀。校尉常惠将乌孙兵入匈怒右地，大克获，封列侯。
大旱，郡国伤旱甚者，民毋出租赋。三辅民就贱者，且毋收事，尽四年。
六月已丑，丞相义薨。
四年春正月，诏曰：“盖闻农者兴德之本也，今岁不登，已遣使者振贷困乏。其令太官损膳省宰，乐府减乐人，使归就农业。丞相以下至都官令、丞上书入谷，输长安仓，助贷贫民。民以车船载谷入关者，得毋用传。”
三月乙卯，立皇后霍氏。赐丞相以下至郎吏从官金、钱、帛各有差。赦天下。
夏四月壬寅，郡国四十九地震，或山崩水出。诏曰：“盖灾异者，天地之戒也。朕承洪业，奉宗庙，托于士民之上，未能和群生。乃者地震北海、琅邪，坏祖宗庙，朕甚惧焉。丞相、御史其与列侯、中二千石博问经学之士，有以应变，辅朕之不逮，毋有所讳。令三辅、太常、内郡国举贤良方正各一人。律令有可蠲除以安百姓，条奏。被地震坏败甚者，勿收租赋。”大赦天下。上以宗庙堕，素服，避正殿五日。
五月，凤皇集北海安丘、淳于。
秋，广川王吉有罪，废迁上庸，自杀。
地节元年春正月，有星孛于西方。
三月，假郡国贫民田。
夏六月，诏曰：“盖闻尧亲九族，以和万国。朕蒙遗德，奉承圣业，惟念宗室属未尽而以罪绝，若有贤材，改行劝善，其复属，使得自新。”
冬十一月，楚王延寿谋反，自杀。
十二月癸亥晦，日有蚀之。
二年春三月庚午，大司马大将军光薨。诏曰：“大司马大将军博陆侯宿卫孝武皇帝三十余年，辅孝昭皇帝十有余年，遭大难，躬秉义，率三公、诸侯、九卿、大夫定万世策，以安宗庙。天下蒸庶，咸以康宁，功德茂盛，朕甚嘉之。复其后世，畴其爵邑，世世毋有所与。功如萧相国。”
夏四月，凤皇集鲁，群鸟从之。大赦天下。
五月，光禄大夫平丘侯王迁有罪，下狱死。
上始亲政事，又思报大将军功德，乃复使乐平侯山领尚书事，而令群臣得奏封事，以知下情。五日一听事，自丞相以下各奉职奏事，以傅奏其言，考试功能。侍中尚书功劳当迁及有异善，厚加赏赐，至于子孙，终不改易。枢机周密，品式备具，上下相安，莫有苟且之意也。
三年春三月，诏曰：“盖闻有功不赏，有罪不诛，虽唐、虞犹不能以化天下。今胶东相成劳来不怠，流民自占八万余口，治有异等，其秩成中二千石，赐爵关内侯。”
又曰：“鳏、寡、孤、独、高年、贫困之民，朕所怜也。前下诏假公田，贷种、食。其加赐鳏、寡、孤、独、高年帛。二千石严教吏谨视遇，毋令失职。”
令国郡国举贤良方正可亲民者。
夏四月戊申，立皇太子，大赦天下。赐御史大夫爵关内侯，中二千石爵右庶长。天下当为父后者爵一级。赐广陵王黄金千斤，诸侯王十五人黄金各百斤，列侯在国者八十七人黄金各二十斤。
冬十月，诏曰：“乃者九月壬申地震，朕甚惧焉。有能箴朕过失，及贤良方正直言极谏之士以匡朕之不逮，毋讳有司。朕既不德，不能附远，是以边境屯戍未息。今复饬兵重屯，久劳百姓，非所以绥天下也。其罢车骑将军、右将军屯兵。”又诏：“池崇未御幸者，假与贫民。郡国宫、馆，勿复修治。流民还归者，假公田，贷种、食，且勿算事。”
十一月，诏曰：“朕既不逮，导民不明，反侧晨兴，念虑万方，不忘元元。唯恐羞先帝圣德，故并举贤良方正以亲万姓，历载臻兹，然而俗化阙焉。传曰：‘孝、弟也者，其为仁之本与！’其令郡国举孝、弟有行义闻于乡里者各一人。”
十二月，初置廷尉平四人，秩六百石。
省文山郡，并蜀。
四年春二月，封外祖母为博平君，故酂侯萧何曾孙建世为侯。
诏曰：“导民以孝，是天下顺。今百姓或遭衰绖凶灾，而吏徭事使不得葬，伤孝子之心，朕甚怜之。自今，诸有大父母、父母丧者勿徭事，使得收敛送终，尽其子道。”
夏五月，诏曰：“父子之亲，夫妇之道，天性也。虽有患祸，犹蒙死而存之。诚爱结于心，仁厚之至也，岂能违之哉！自今，子首匿父母、妻匿夫、孙匿大父母，皆勿坐。其父母匿子、夫匿妻、大父母匿孙，罪殊死，皆上请廷尉以闻。”
立广川惠王孙文为广川王。
秋七月，大司马霍禹谋反。诏曰：“乃者，东织室令史张赦使魏郡豪李竟报冠阳侯霍云谋为大逆，朕以大将军故，抑而不扬，冀其自新。今大司马博陆侯禹与母宣成侯夫人显及从昆弟冠阳侯云、乐平侯山、诸姊妹婿度辽将军范明友、长信少府邓广汉、中郎将任胜、骑都尉赵平、长安男子冯殷等谋为大逆。显前又使女侍医淳于衍进药杀共哀后，谋毒太子，欲危宗庙。逆乱不道，咸伏其辜。诸为霍氏所诖误未发觉在吏者，皆赦除之。”
八月已酉，皇后霍氏废。
九月，诏曰：“朕惟百姓失职不赡，遣使者循行郡国问民所疾苦。吏或营私烦扰，不顾厥咎，朕甚闵之。今年郡国颇被水灾，已振贷。盐，民之食，而贾咸贵，众庶重困。其减天下盐贾。”
又曰：“令甲，死者不可生，刑者不可息。此先帝之所重，而吏未称。今系者或以掠辜若饥寒瘐死狱中，何用心逆人道也！朕甚痛之。其令郡国岁上系囚以掠笞若瘐死者所坐名、县、爵、里，丞相、御史课殿最以闻。”
十二月，清河王年有罪，废迁房陵。
元康元年春，以杜东原上为初陵，更名杜县为杜陵。徙丞相、将军、列侯、吏二千石、訾百万者杜陵。
三月，诏曰：“乃者凤皇集泰山、陈留，甘露降未央宫。朕未能章先帝休烈，协宁百姓，承天顺地，调序四时，获蒙嘉瑞，赐兹祉福，夙夜兢兢，靡有骄色，内省匪解，永惟罔极。《书》不云乎？‘凤皇来仪，庶尹允谐。’其赦天下徒，赐勤事吏中二千石以下至六百石爵，自中郎吏至五大夫，佐史以上二级，民一级，女子百户牛、酒。加赐鳏、寡、孤、独、三老、孝弟、力田帛。所振贷勿收。”
夏五月，立皇考庙。益奉明园户为奉明县。
复高皇帝功臣绛侯周勃等百三十六人家子孙，令奉祭祀，世世勿绝。其毋嗣者，复其次。
秋八月，诏曰：“朕不明六艺，郁于大道，是以阴阳风雨未时。其博举吏民，厥身修正，通文学，明于先王之术，宣究其意者，各二人，中二千石各一人。”
冬，置建章卫尉。
二年春正月，诏曰：“《书》云‘文王作罚，刑兹无赦’，今吏修身奉法，未有能称朕意，朕甚愍焉。其赦天下，与士大夫厉精更始。”
二月乙丑，立皇后王氏。赐丞相以下至郎从官钱、帛各有差。
三月，以凤皇、甘露降集，赐天下吏爵二级，民一级，女子百户牛、酒，鳏、寡、孤、独、高年帛。
夏五月，诏曰：“狱者，万民之命，所以禁暴止邪，养育群生也。能使生者不怨，死者不恨，则可谓文吏矣。今则不然，用法或持巧心，析律贰端，深浅不平，增辞饰非，以成其罪。奏不如实，上亦亡由知。此朕之不明，吏之不称，四方黎民将何仰哉！二千石各察官属，勿用此人。吏务平法。或擅兴徭役，饰厨、传，称过使客，越职逾法，以取名誉，譬犹践薄冰以待白日，岂不殆哉！今天下颇被疾疫之灾，朕甚愍之。其令郡国被灾甚者，毋出今年租赋。”
又曰：“闻古天子之名，难知而易讳也。今百姓多上书触讳以犯罪者，朕甚怜之。其更讳询。诸触讳在令前者，赦之。”
冬，京兆尹赵广汉有罪，要斩。
三年春，以神爵数集泰山，赐诸侯王、丞相、将军、列侯二千石金，郎从官帛，各有差。赐天下吏爵二级，民一级，女子百户牛、酒、鳏、寡、孤、独、高年帛。
三月，诏曰：“盖闻象有罪，舜封之，骨肉之亲粲而不殊。其封故昌邑王贺为海昏侯。”
又曰：“朕微眇时，御史大夫丙吉，中郎将史曾、史玄、长乐卫尉许舜、侍中光禄大夫许延寿皆与朕有旧恩。及故掖庭令张贺辅导朕躬，修文学经术，恩惠卓异，厥功茂焉。《诗》不云乎？‘无德不报。’封贺所子弟子侍中中郎将彭祖为阳都侯，追赐贺谥曰阳都哀侯。吉、曾、玄、舜、延寿皆为列侯。故人下至郡邸狱复作尝有阿保之功，皆受官禄、田宅、财物，各以恩深浅报之。”
夏六月，诏曰：“前年夏，神爵集雍。今春，五色鸟以万数飞过属县，翱翔而舞，欲集未下。其令三辅毋得以春夏擿巢探卵，弹射飞鸟。具为令。”
立皇子钦为淮阳王。
四年春正月，诏曰：“朕惟耆老之人，发齿堕落，血气衰微，亦亡暴虐之心，今或罹文法，拘执囹圄，不终天命，朕甚怜之。自今以来，诸年八十以上，非诬告、杀伤人，佗皆勿坐。”
遣太中大夫强等十二人循行天下，存问鳏、寡，览观风俗，察吏治得失，举茂材异伦之士。
二月，河东霍徵史等谋反，诛。
三月，诏曰：“乃者，神爵五采以万数集长乐、未央、北宫、高寝、甘泉泰畤殿中及上林苑。朕之不逮，寡于德厚，屡获嘉祥，非朕之任。其赐天下吏爵二级，民一级，女子百户牛、酒。加赐三老、孝弟、力田帛，人二匹，鳏、寡、孤、独各一匹。”
秋八月，赐故右扶风尹翁归子黄金百斤。以奉其祭祀。又赐功臣适后黄金，人二十斤。
丙寅，大司马卫将军安世薨。
比年丰，谷石五钱。
神爵元年春正月，行幸甘泉，郊泰畤。三月，行幸河东，祠后土。诏曰：“朕承宗庙，战战栗栗，惟万事统，未烛厥理。乃元康四年嘉谷、玄稷降于郡国，神爵仍集，金芝九茎产于函德殿铜池中，九真献奇兽，南郡获白虎、威凤为宝。朕之不明，震于珍物，饬躬斋精，祈为百姓。东济大河，天气清静，神鱼舞河。幸万岁宫，神爵翔集。朕之不德，惧不能任。其以五年为神爵元年。赐天下勤事吏爵二级，民一级，女子百户牛、酒，鳏、寡、孤、独、高年帛。所振贷物勿收。行所过，毋出田租。”
西羌反，发三辅、中都官徒弛刑，及应募佽飞射士、羽林孤儿，胡、越骑，三河、颍川、沛郡、淮阳、汝南材官，金城、陇西、天水、安定、北地、上郡骑士、羌骑，诣金城。
夏四月，遣后将军赵充国、强弩将军许延寿击西羌。
六月，有星孛于东方。
即拜酒泉太守辛武贤为破羌将军，与两将军并进。诏曰：“军旅暴露，转输烦劳，其令诸侯王、列侯、蛮夷王、侯、君、长当朝二年者，皆毋朝。”
秋，赐故大司农朱邑子黄金百斤，以奉祭祀。后将军充国言屯田之计，语在《充国传》。
二年春二月，诏曰：“乃者正月乙丑，凤皇、甘露降集京师，群鸟从以万数。朕之不德，屡获天福，祗事不怠，其赦天下。”
夏五月，羌虏降服，斩其首恶大豪杨玉、酋非首。置金城属国以处降羌。
秋，匈奴日逐王先贤掸将人众万余来降。使都护西域骑都尉郑吉迎日逐，破车师，皆封列侯。
九月，司隶校尉盖宽饶有罪，下有司，自杀。
匈奴单于遣名王奉献，贺正月，始和亲。
三年春，起乐游苑。
三月丙午，丞相相薨。
秋八月，诏曰：“吏不廉平则治道衰。今小吏皆勤事，而奉禄薄，欲其毋侵渔百姓，难矣。其益吏百石以下奉十五。”
四年春二月，诏曰：“乃者凤皇、甘露降集京师，嘉瑞并见。修兴泰一、五帝、后士之祠，祈为百姓蒙祉福。鸾凤万举，蜚览翱翔，集止于旁。斋戒之暮，神光显著。荐鬯之夕，神光交错。或降于天，或登于地，或从四方来集于坛。上帝嘉飨，海内承福。其赦天下，赐民爵一级，女子百户牛、酒，鳏、寡、孤、独、高年帛。”
夏四月，颍川太守黄霸以治行尤异秩中二千石，赐爵关内侯，黄金百斤。及颍川吏、民有行义者爵，人二级，力田一级，贞妇、顺女帛。
令内郡国举贤良可亲民者各一人。
五月，匈奴单于遣弟呼留若王胜之来朝。
冬十月，凤皇十一集杜陵。
十一月，河南太守严延年有罪，弃市。
十二月，凤皇集上林。
五凤元年春正月，行幸甘泉，郊泰畤。
皇太子冠。皇太后赐丞相、将军、列侯、中二千石帛，人百匹，大夫人八十匹，夫人六十匹。又赐列侯嗣子爵五大夫，男子为父后者爵一级。
夏，赦徒作杜陵者。
冬十二月乙酉朔，日有蚀之。
左冯翊韩延寿有罪，弃市。
二年春三月，行幸雍，祠五畤。
夏四月已丑，大司马车骑将军增薨。
秋八月，诏曰：“夫婚姻之礼，人伦之大者也；酒食之会，所以行礼乐也。今郡国二千石或擅为苛禁，禁民嫁娶不得具酒食相贺召。由是废乡党之礼，令民亡所乐，非所以导民也。《诗》不云乎？‘民之失德，乾餱以愆。’勿行苛政。”
冬十一月，匈奴呼遬累单于帅众来降，封为列侯。
十二月，平通侯杨恽坐前为光禄勋有罪，免为庶人。不悔过，怨望，大逆不道，要斩。
三年春正月癸卯，丞相吉薨。
三月，行幸河东，祠后土。诏曰：“往者匈奴数为边寇，百姓被其害。朕承至尊，未能绥安匈奴。虚闾权渠单于请求和亲，病死。右贤王屠耆堂代立。骨肉大臣立虚闾权渠单于子为呼韩邪单于，击杀屠耆堂。诸王并自立，分为五单于，更相攻击，死者以万数，畜产大耗什八九，人民饥饿，相燔烧以求食，因大乖乱。单于阏氏子孙、昆弟及呼遬累单于、名王、右伊秩訾、且渠、当户以下将众五万余人来降归义。单于称臣，使弟奉珍朝驾正月，北边晏然，靡有兵革之事。朕饬躬斋戒，郊上帝，祠后土，神光并见，或兴于谷，烛耀齐宫，十有余刻。甘露降，神爵集。已诏有司告祠上帝、宗庙。三月辛丑，鸾凤又集长乐宫东阙中树上，飞下止地，文章五色，留十余刻，吏民并观。朕之不敏，惧不能任，娄蒙嘉瑞，获兹祉福。《书》不云乎？‘虽休勿休，祗事不怠。’公卿大夫其勉焉。减天下口钱。赦殊死以下。赐民爵一级，女子百户牛、酒。大酺五日。加赐鳏、寡、孤、独、高年帛。”
置西河、北地属国以处匈奴降者。
四年春正月，广陵王胥有罪，自杀。
匈奴单于称臣，遣弟谷蠡王入侍。以边塞亡寇，减戍卒什二。
大司农中丞耿寿昌奏设常平仓，以给北边，省转漕。赐爵关内侯。
夏四月辛丑晦，日有蚀之。昭曰：“皇天见异，以戒朕躬，是朕之不逮，吏之不称也。以前使使者问民所疾苦，复遣丞相、御史掾二十四人循行天下，举冤狱，察擅为苛禁深刻不改者。”
甘露元年春正月，行幸甘泉，郊泰畤。
匈奴呼韩邪单于遣子右贤王铢娄渠堂入侍。
二月丁已，大司马车骑将军延寿薨。
夏四月，黄龙见新丰。
丙申，太上皇庙火。甲辰，孝文庙火。上素服五日。
冬，匈奴单于遣弟左贤王来朝贺。
二年春正月，立皇子嚣为定陶王。
诏曰：“乃者凤皇、甘露降集，黄龙登兴，醴泉滂流，枯槁荣茂，神光并见，咸受祯祥。其赦天下。减民算三十。赐诸侯王、丞相、将军、列侯、中二千石金、钱各有差。赐民爵一级，女子百户牛、酒，鳏、寡、孤、独、高年帛。”
夏四月，遣护军都尉禄将兵击珠崖。
秋九月，立皇子宇为东平王。
冬十二月，行幸萯阳宫属玉观。
匈奴呼韩邪单于款五原塞，愿奉国珍朝三年正月。诏有司议。咸曰：“圣王之制，施德行礼，先京师而后诸夏，先诸夏而后夷狄。《诗》云：‘率礼不越，遂视既发。相土烈烈，海外有截。’陛下圣德。充塞天地，光被四表。匈奴单于乡风慕义，举国同心，奉珍朝贺，自古未之有也。单于非正朔所加，王者所客也，礼仪宜如诸侯王，称臣昧死再拜，位次诸侯王下。”诏曰：“盖闻五帝三王，礼所不施，不及以政。今匈奴单于称北籓臣，朝正月，朕之不逮，德不能弘覆。其以客礼待之，位在诸侯王上。”
三年春正月，行幸甘泉，郊泰畤。
匈奴呼韩邪单于稽侯犭册来朝，赞谒称籓臣而不名。赐以玺绶、冠带、衣裳、安车、驷马、黄金、锦绣、缯絮。使有司道单于先行就邸长安，宿长平。上自甘泉宿池阳宫。上登长平阪，诏单于毋谒。共左右当户之群皆列观，蛮夷君、长、王、侯迎者数万人，夹道陈。上登渭桥，咸称万岁。单于就邸。置酒建章宫，飨赐单于，观以珍宝。
二月，单于罢归。遣长乐卫尉高昌侯忠、车骑都尉昌、骑都尉虎将万六千骑送单于。单于居幕南，保光禄城。诏北边振谷食。郅支单于远遁，匈奴遂定。
诏曰：“乃者凤皇集新蔡，群鸟四面行列，皆乡凤皇立，以万数。其赐汝南太守帛百匹，新蔡长吏、三老、孝弟、力田、鳏、寡、孤、独各有差。赐民爵二级。毋出今年租。”
三月已丑，丞相霸薨。
诏诸儒讲《五经》同异，太子太傅萧望之等平奏其议，上亲称制临决焉。乃立梁丘《易》、大小夏侯《尚书》、穀梁《春秋》博士。
冬，乌孙公主来归。
四年夏，广川王海阳有罪，废迁房陵。
冬十月丁卯，未央宫宣室阁火。
黄龙元年春正月，行幸甘泉，郊泰畤。
匈奴呼韩邪单于来朝，礼赐如初。二月，单于归国。
诏曰：“盖闻上古之治，君臣同心，举措曲直，各得其所。是以上下和洽，海内康平，其德弗可及已。朕既不明，数申诏公卿、大夫务行宽大，顺民所疾苦，将欲配三王之隆，明先帝之德也。今吏或以不禁奸邪为宽大，纵释有罪为不苛，或以酷恶为贤，皆失其中。奉诏宣化如此，岂不谬哉！方今天下少事，徭役省减，兵革不动，而民多贫，盗贼不止，其咎安在？上计簿，具文而已，务为欺谩，以避其课。三公不以为意，朕将何任？诸请诏省卒徒自给者皆止。御史察计簿，疑非实者，按之，使真伪毋相乱。”
三月，有星孛于王良、阁道，入紫宫。
夏四月，诏曰：“举廉吏，诚欲得其真也。吏六百石位大夫，有罪先请，秩禄上通，足以效其贤材，自今以来毋得举。”
冬十二月甲戌，帝崩于未央宫。癸巳，尊皇太后曰太皇太后。
赞曰：孝先之治，信赏必罚，综核名实，政事、文学、法理之士咸精其能，至于技巧、工匠、器械，自元、成间鲜能及之，亦足以知吏称其职，民安其业也。遭值匈奴乖乱，推亡固存，信威北夷，单于慕义，稽首称籓。功光祖宗，业垂后嗣，可谓中兴，侔德殷宗、周宣矣！', '', '', '', NULL, '', 'indent', 1557311763, '5c1cb3b71579a3005fd3a4c5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640854, '吕氏春秋·不苟论·自知', NULL, 14, 12, 1, 1, '吕不韦', NULL, 36825, '58e65ba9ac502e006c291e90', '秦', 'wen', '文', 'https://baike.baidu.com/item/%E5%90%95%E6%B0%8F%E6%98%A5%E7%A7%8B/615121?fr=aladdin', '', '欲知平直，则必准绳；欲知方圆，则必规矩；人主欲自知，则必直士。故天子立辅弼，设师保，所以举过也。夫人固不能自知，人主犹甚。存亡安危，勿求于外，务在自知。', '《吕氏春秋》是在秦国丞相吕不韦主持下，集合门客们编撰的一部黄老道家名著。成书于秦始皇统一中国前夕。此书以儒家学说为主干，以道家理论为基础，以名、法、墨、农、兵、阴阳家思想学说为素材，熔诸子百家学说为一炉，闪烁着博大精深的智慧之光。吕不韦想以此作为大一统后的意识形态。但后来执政的秦始皇却选择了法家思想，使包括道家在内的诸子百家全部受挫。《吕氏春秋》集先秦道家之大成，是秦道家的代表作，全书共分二十六卷，一百六十篇，二十余万字。', '', '要知道平直，一定要依靠水准墨线;要知道方圆，一定要依靠圆规矩尺；君主要想了解自己的过失，一定要依靠正直之士。所以天子设立辅弼，设置师保，这是用来举发天子过错的。人本来就不能了解自己的过失，天子尤为严重。国存身安不用到外部寻求，关键在于了解自己的过失。', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3c9", "shortContent": "这两句都出自《去私》篇，所言的核心思想就是去除私心。烛，即照。天覆盖万物，没有偏私；地承载万物，没有偏私；日月普照万物，没有偏私；春夏秋冬更迭交替，没有偏私。天地、日月、四季施其恩德，于是万物得以生长。天和地、日和月，春夏秋冬，寒来暑往，对人类来说，都是公平的。这是自然的规律。《吕氏春秋》是以道家的哲学思想为基础的，以道家思想为世界观和方法论。既然天地日月四时都对人类是公正无私的，那么，代表天地日...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3cc", "shortContent": "这几句名言是《吕氏春秋》关于“民”的思想的集中表述，内容涉及审民、君民、用民几个方面，分析这几句对于认识《吕氏春秋》的民本思想具有重要意义。\n\n首先，《吕氏春秋》充分认识到民心的作用。君主要做事，先要看民心的向背然后再做。不能得到人民的拥戴，所处的地位虽然尊贵，对于自己的安定又有什么益处呢？这就是说，国家的政权，君主的合理性实际上都是建立在民意的基础上的。上文《顺民》篇说：“先王先顺民心，故功名成...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3cd", "shortContent": "这两句专门论忠。是《吕氏春秋》关于“忠”的集中表述，其蕴有的含义是十分有价值的。\n\n首先，《吕氏春秋》认为“忠”的对象只能是一个。所谓“利不可两，忠不可兼”，意思是人不可能同时获取两种利益，也不可同时忠于两个对象。忠，强调对象的单一性和纯粹性。\n\n何谓“忠”？《说文解字》的解释是：“忠，敬也，尽心曰忠。”“忠”的本意是指尽心竭力、全身心地投入到某项事情之中。“忠”字，首先是作为一般社会性道德观念而...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70244d24b2a4416f3ce", "shortContent": "这两则名言主要是从制度上来说国家如何治理的，体现了《吕氏春秋》以治国为核心的思想主张。\n\n首先，国家不能没有君主。这里的天子实际上就是君主。一个国家如果没有君主，那么必然会产生动乱。所以，混乱没有什么比没有天子更大的了。没有天子，那么势力强的就会压倒势力弱的，人多的就会危害人少的，用军队互相残杀，人民生活不得止息。在战国时期，人们已经认识到国家或天下必须统一于一个君主，国家或任何社会权力体系都只能...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1565181973, '5c1cb4d5808ca4565c88e0f7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640855, '文赋', NULL, 62, 115, 2, 1, '陆机', NULL, 10283, '57b8fc6a128fe10054c9696b', '晋', 'fu', '赋', '', '', '余每观才士之所作，窃有以得其用心。
夫放言谴辞，良多变矣，妍蚩好恶，可得而言。
每自属文，尤见其情。
恒患意不称物，文不逮意。
盖非知之难，能之难也。
故作《文赋》，以述先士之盛藻，因论作文之利害所由，它日殆可谓曲尽其妙。
至于操斧伐柯，虽取则不远，若夫随手之变，良难以辞逮。
盖所能言者具于此云。
伫中区以玄览，颐情志于典坟。
遵四时以叹逝，瞻万物而思纷。
悲落叶于劲秋，喜柔条于芳春。
心懔懔以怀霜，志眇眇而临云。
咏世德之骏烈，诵先人之清芬。
游文章之林府，嘉丽藻之彬彬。
慨投篇而援笔，聊宣之乎斯文。
其始也，皆收视反听，耽思傍讯。
精骛八极，心游万仞。
其致也，情曈昽而弥鲜，物昭晰而互进。
倾群言之沥液、漱六艺之芳润。
浮天渊以安流，濯下泉而潜浸。
于是沉辞怫悦，若游鱼衔钩，而出重渊之深；浮藻联翩，若翰鸟婴缴，而坠曾云之峻。
收百世之阙文，采千载之遗韵。
谢朝华于已披，启夕秀于未振。
观古今于须臾，抚四海于一瞬。
然后选义按部，考辞就班。
抱景者咸叩，怀响者毕弹。
或因枝以振叶，或沿波而讨源。
或本隐以之显，或求易而得难。
或虎变而兽扰，或龙见而鸟澜。
或妥帖而易施，或岨峿而不安。
罄澄心以凝思，眇众虑而为言。
笼天地于形内，挫万物于笔端。
始躑躅于燥吻，终流离于濡翰。
理扶质以立干，文垂条而结繁。
信情貌之不差，故每变而在颜。
思涉乐其必笑，方言哀而已叹。
或操觚以率尔，或含毫而邈然。
伊兹事之可乐，固圣贤之所钦。
课虚无以责有，叩寂寞而求音。
函绵邈于尺素，吐滂沛乎寸心。
言恢之而弥广，思按之而逾深。
播芳蕤之馥馥，发青条之森森。
粲风飞而猋竖，郁云起乎翰林。
体有万殊，物无一量。
纷纭挥霍，形难为状。
辞程才以效伎，意司契而为匠。
在有无而黾勉，当浅深而不让。
虽离方而遯圆，期穷形而尽相。
故夫夸目者尚奢，惬心者贵当。
言穷者无隘，论达者唯旷。
诗缘情而绮靡，赋体物而浏亮。
碑披文以相质，诔缠绵而悽怆。
铭博约而温润，箴顿挫而清壮。
颂优游以彬蔚，论精微而朗畅。
奏平彻以闲雅，说炜晔而谲诳。
虽区分之在兹，亦禁邪而制放。
要辞达而理举，故无取乎冗长。
其为物也多姿，其为体也屡迁；其会意也尚巧，其遣言也贵妍。
暨音声之迭代，若五色之相宣。
虽逝止之无常，故崎錡而难便。
苟达变而相次，犹开流以纳泉；如失机而后会，恒操末以续颠。
谬玄黄之秩叙，故淟涊而不鲜。
或仰逼于先条，或俯侵于后章；或辞害而理比，或言顺而意妨。
离之则双美，合之则两伤。
考殿最于锱铢，定去留于毫芒；苟铨衡之所裁，固应绳其必当。
或文繁理富，而意不指适。
极无两致，尽不可益。
立片言而居要，乃一篇之警策；虽众辞之有条，必待兹而效绩。
亮功多而累寡，故取足而不易。
或藻思绮合，清丽千眠。
炳若缛绣，悽若繁弦。
必所拟之不殊，乃闇合乎曩篇。
虽杼轴于予怀，忧他人之我先。
苟伤廉而愆义，亦虽爱而必捐。
或苕发颖竖，离众绝致；形不可逐，响难为系。
块孤立而特峙，非常音之所纬。
心牢落而无偶，意徘徊而不能揥。
石韫玉而山辉，水怀珠而川媚。
彼榛楛之勿剪，亦蒙荣于集翠。
缀《下里》于《白雪》，吾亦济夫所伟。
或托言于短韵，对穷迹而孤兴，俯寂寞而无友，仰寥廓而莫承；譬偏弦之独张，含清唱而靡应。
或寄辞于瘁音，徒靡言而弗华，混妍蚩而成体，累良质而为瑕；象下管之偏疾，故虽应而不和。
或遗理以存异，徒寻虚以逐微，言寡情而鲜爱，辞浮漂而不归；犹弦么而徽急，故虽和而不悲。
或奔放以谐和，务嘈囋而妖冶，徒悦目而偶俗，故高声而曲下；寤《防露》与桑间，又虽悲而不雅。
或清虚以婉约，每除烦而去滥，阙大羹之遗味，同朱弦之清氾；虽一唱而三叹，固既雅而不艳。
若夫丰约之裁，俯仰之形，因宜适变，曲有微情。
或言拙而喻巧，或理朴而辞轻；或袭故而弥新，或沿浊而更清；或览之而必察，或研之而后精。
譬犹舞者赴节以投袂，歌者应弦而遣声。
是盖轮扁所不得言，故亦非华说之所能精。
普辞条与文律，良余膺之所服。
练世情之常尤，识前修之所淑。
虽发于巧心，或受蚩于拙目。
彼琼敷与玉藻，若中原之有菽。
同橐籥之罔穷，与天地乎并育。
虽纷蔼于此世，嗟不盈于予掬。
患挈瓶之屡空，病昌言之难属。
故踸踔于短垣，放庸音以足曲。
恒遗恨以终篇，岂怀盈而自足？
惧蒙尘于叩缶，顾取笑乎鸣玉。
若夫应感之会，通塞之纪，来不可遏，去不可止，藏若景灭，行犹响起。
方天机之骏利，夫何纷而不理？
思风发于胸臆，言泉流于唇齿；纷葳蕤以馺遝，唯豪素之所拟；文徽徽以溢目，音冷冷而盈耳。
及其六情底滞，志往神留，兀若枯木，豁若涸流；揽营魂以探赜，顿精爽而自求；理翳翳而愈伏，思轧轧其若抽。
是以或竭情而多悔，或率意而寡尤。
虽兹物之在我，非余力之所戮。
故时抚空怀而自惋，吾未识夫开塞之所由。
伊兹文之为用，固众理之所因。
恢万里而无阂，通亿载而为津。
俯殆则于来叶，仰观象乎古人。
济文武于将坠，宣风声于不泯。
涂无远而不弥，理无微而弗纶。
配沾润于云雨，象变化乎鬼神。
被金石而德广，流管弦而日新。', '', '', '', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf6503048e64fbd9c9e7", "shortContent": "本文见于《皮子文薮》及《全唐文》等。在体裁上属于句法变化较自由的文赋，“文赋尚理”（《文体明辨·序说》）。有学者认为唐宋古文家的文赋：“题材、主题较多，构思变化也较多”，可以称为新文赋（马积高《赋史》）。此赋其前有序，认为前代宰相宋璟写过《梅花赋》，所以他也可写《桃花赋》。大概时人认为文人应写可讽可感的有益世道人心，合乎比兴之旨的作品，只是“清便富艳”的吟咏花草则有伤大雅。如比皮日休稍早的舒元舆作...", "authors": ["欧天发"], "pressName": "上海辞书出版社"}]', '', 'indent', 1545413957, '5c1cb4e467f356005fd99aea', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640856, '学治臆说·用亲不如用友', NULL, 5, 5, 1, 1, '汪辉祖', NULL, 21140, '5858ef2061ff4b0063d73eb9', '清', 'wen', '文', 'https://baike.baidu.com/item/%E5%AD%A6%E6%B2%BB%E8%87%86%E8%AF%B4/2558369', '', '谚曰：莫用三爷，废职亡家。盖子为少爷，婿为姑爷，妻兄弟为舅爷也。之三者未必才无可用，第内有蔽聪塞明之方，外有投鼠忌器之虑。威之所行，权辄附焉；权之所附，威更炽焉。任以笔墨，则售承行，鬻差票；任以案牍，则通贿赂，变是非；任以仓库，则轻出重入，西掩东挪，弊难枚举。即令总核买办杂务，其细已甚，亦必至于短发价值，有玷官声，故无一而可。事非十分败坏，不入于耳；迨入于耳，已难措手。以法则伤恩，以恩则坏法。三者相同，而子为尤甚，其见利忘亲者无论。意在爱亲，而孳孳焉为亲计利，势必陷亲于不义，所以危也。', '', '', '', NULL, '', 'indent', 1565181977, '5c1cb5a867f356005fd9adda', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640857, '策林一·兴五福，销六极', NULL, 23, 2952, 1, 1, '白居易', NULL, 10005, '57b9247f2e958a005fa67ccb', '唐', 'wen', '文', '', '', '然臣窃闻，善除害者察其本，善理疾者绝其源。伏惟陛下欲纾人之忧，先念忧之所自；欲救人之病，先思病之所由。知所自以绝之，则人忧自弭也；知所由以去之，则人病自瘳也。然后申之以救疗之术，则人易康宁；鼓之以安乐之音，则人易和悦。斯必应疾而化速，利倍而功兼。六极待此而销，五福待此而作。', ' 《策林》是唐代诗人白居易于元和元年（806年） 参加制科考试前，独自拟作的75篇文章。分别就与中唐时务密切相关的八方面问题进行了深入系统的探讨，即：为君为圣之道、施政化民之略、求贤选能之方、整肃吏治之法、省刑慎罚之术、治军御兵之要、矜民恤情之核、礼乐文教之功等，体现了白居易的早期政治思想。

“五福六极”是《尚书·洪范》中的概念。周武王灭商后，向箕子请教治国之道。箕子答以“洪范九畴”，其第九条为“向用五福，威用六极”，就是用五福劝勉臣民，用六极惩戒罪恶。这“五福六极”代表了人生的五种美好和六种不幸。五福:一曰寿，二曰富，三曰康宁，四曰攸好德，五曰考终命。六极:一曰凶、短、折，二曰疾，三曰忧，四曰贫，五曰恶，六曰弱。

《策林》采用君臣问对的形式，在回答皇上“思欲销六极，致五福”的提问时，白居易提出了“善除害者察其本，善理疾者绝其源”的观点。意思是善于消除灾害的人，先查找灾害的根由；善于治疗疾病的人，先断绝疾病的源头。并进一步申论道：“欲纾人之忧，先念忧之所自；欲救人之病，先思病之所由。知所自以绝之，则人忧自弭（mǐ，消除）也；知所由以去之，则人病自瘳（chōu，病愈）也。”将消除灾害与治疗疾病进行类比论证：“善除害者察其本”，就是“防患于未然”；“善理疾者绝其源”，就是“上医治未病”。二者同此一理，可相参证。

《兴五福，销六极》探讨了国君、人民和天地的关系。指出“君得其中，则人得其所；人得其所，则和乐生焉”，“君人之心不和，则天地之气不和；天地之气不和，则万物之生不和”，从正反两方面分析了三者之间相辅相成的关系。  ', '', '', NULL, '', 'indent', 1545414380, '5c1cb684808ca4565c89009b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641628, ' 雪中偶题', NULL, 9, 327, 0, 1, '郑谷', NULL, 10237, '57bb009e0a2b58006cba3d19', '唐', 'shi', '诗', '', '', '乱飘僧舍茶烟湿，密洒歌楼酒力微。
江上晚来堪画处，渔人披得一蓑归。', '', '', '', NULL, '', 'center', 1554118793, '5ca1880617b54d0070ddfaed', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641629, '酬友人春暮寄枳花茶', NULL, 9, 105, 0, 1, '李郢', NULL, 12569, '5858e789128fe1006dcc2bad', '唐', 'shi', '诗', '', '', '昨日东风吹枳花，酒醒春晚一瓯茶。
如云正护幽人堑，似雪才分野老家。
金饼拍成和雨露，玉尘煎出照烟霞。
相如病渴今全校，不羡生台白颈鸦。', '', '', '', NULL, '', 'center', 1554118855, '5ca18841c05a80007465dcf6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640858, '管子 · 参患', NULL, 2, 573, 1, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E7%AE%A1%E5%AD%90%C2%B7%E5%8F%82%E6%82%A3/19830564?fr=aladdin', '', '凡人主者，猛毅则伐，懦弱则杀，猛毅者何也？轻诛杀人之谓猛毅。懦弱者何也，重诛杀人之谓懦弱。此皆有失彼此。凡轻诛者杀不辜，而重诛者失有皋，故上杀不辜，则道正者不安；上失有皋，则行邪者不变。道正者不安，则才能之人去亡；行邪者不变，则群臣朋党；才能之人去亡，则宜有外难，群臣朋党，则宜有内乱。故曰猛毅者伐，懦弱者杀也。
君之所以卑尊，国之所以安危者，莫要于兵。故诛暴国必以兵，禁辟民必以刑。然则兵者外以诛暴，内以禁邪。故兵者尊主安国之经也，不可废也。若夫世主则不然。外不以兵，而欲诛暴，则地必亏矣。内不以刑，而欲禁邪，则国必乱矣。
故凡用兵之计，三惊当一至，三至当一军，三军当一战；故一期之师，十年之蓄积殚；一战之费，累代之功尽；今交刃接兵而后利之，则战之自胜者也。攻城围邑，主人易子而食之，析骸而爨之，则攻之自拔者也。是以圣人小征而大匡，不失天时，不空地利，用日维梦，其数不出于计。故计必先定而兵出于竟，计未定而兵出于竟，则战之自败，攻之自毁者也。
得众而不得其心，则与独行者同实。兵不完利，与无操者同实，甲不坚密，与俴者同实。弩不可以及远，与短兵同实。射而不能中，与无矢者同实。中而不能入，与无镞者同实。将徒人，与俴者同实。短兵待远矢，与坐而待死者同实。故凡兵有大论。必先论其器，论其士，论其将，论其主，故曰：“器滥恶不利者，以其士予人也，士不可用者，以其将予人也；将不知兵者，以其主予人也；主不积务于兵者，以其国予人也；故一器成，往夫具，而天下无战心。二器成，惊夫具，而天下无守城。三器成，游夫具，而天下无聚众。”所谓无战心者，知战必不胜，故曰无战心。所谓无守城者，知城必拔，故曰无守城。所谓无聚众者，知众必散，故曰无聚众。', '', '', '凡为人君，猛毅就为人所伐，懦弱就被人所杀。什么叫猛毅呢？轻易杀人的，叫作猛毅。什么是懦弱呢？姑息于杀人的，叫作懦弱。此二者各有所失。凡轻易杀人的，会杀了无罪的人；凡姑息于杀人的，会遗漏真正的罪犯。国君杀了无罪的人，正人君子就心怀不安；遗漏真正的罪犯，干坏事的就不肯改正。正人君子不放心，人材就会外流；做坏事的不改正，群臣就结党营私。人材外流，势必带来外患；群臣结党，势必带来内乱。所以说，猛毅之君为人所伐，懦弱之君将被人所杀。
决定君主尊卑、国家安危的，没有比军队更重要的了。征伐暴国，必用军队；镇压坏人，必用刑杀。于是军队是对外用于征伐暴国，对内用于镇压坏人的。因此，军队是尊君安国的根本，不可废置。现时的君主则不然，对外不用军队而想征伐暴国，那就必然要丧失国土；对内不用刑杀而想镇压坏人，国家就一定混乱了。
凡用兵的计划，三次警备等于一次出征，三次出征等于一次围敌，三次围敌等于一次交战。所以，一年的军费，要准备消耗十年的积蓄；一战的费用，要准备用光几代的积累。现在，如果等到两国交兵以后，才创造有利于备战的条件，那只好一接战就自己宣告失败。如果等到攻城围邑以后，才知道守城者易子而食，烧骨为炊的顽强抵抗，那只好一进攻就自己宣告拔寨而退了。所以圣人总是对小的征战有大的警惧、争取不失天时，不失地利，白天作战夜间就计划好。其各项办法都不超出于计划，所以，计划必须先定而后才兴兵出境，没有计划好而兴兵出境，那是战起来自己就失败，攻起来自己就毁灭的。
拥有众多军队但不得军心，实质上和单人行动一样；兵器既不齐全又不锋利，实质上和没有兵器一样；盔甲既不坚固又不严密，实质上和无甲单衣者一样；弓弯射不远，实质上和短兵器一样；射而不能中，实质上和没有箭支一样；射中而不能穿，实质上和没有箭头一样；率领未经训练的人作战，实质上和自我残杀一样；用短兵器抵御远射的弓箭，实质上和坐而待毙一样。所以，凡是用兵，都有几项重大的考评。必须首先考评武器，考评士兵，考评将领，考评君主。所以说，武器粗恶不良，等于把士兵奉送给敌人；士兵不可用，等于把主将送给敌人；主将不懂用兵，等于把君主送给敌人；君主不能坚持不懈地注重军事，就等于把国家送给别人了。有一种武器达到最高水平，再有敢于出征的战士，则天下没有战心；有两种武器达到最高水平，再有智勇惊众的战士，则天下无可守之城；有三种武器达到最高水平，再有才辩游说的人士，则天下都不敢聚集兵众迎战了。所谓没有战心，就是知道了战争一定不能打胜，所以说不敢有战心；所谓无可守之城，就是知道了城堡一定被攻破，所以说无守住之城；所谓不取聚集兵众，就是知道兵众必然逃散，所以说没有人敢于聚集兵众迎战了。', NULL, '', 'indent', 1565181980, '5c1cb73e9f54540070719bb1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640859, '资治通鉴·陈纪', NULL, 3, 1577, 1, 1, '司马光', NULL, 10351, '57b9c6d179bc4400639cc661', '宋', 'wen', '文', 'https://baike.baidu.com/item/%E8%B5%84%E6%B2%BB%E9%80%9A%E9%89%B4%20%EF%BC%88%E9%99%88%E7%BA%AA%EF%BC%89/17618130', '', '周主将视学，以太傅燕国公于谨为三老。……谨起，立于席后，对曰：“木受绳则正，后从谏则圣。明王虚心纳谏以知得失，天下乃安。”又曰：“去食去兵，信不可去；愿陛下守信勿失。”又曰：“有功必赏，有罪必罚，则为善者日进，为恶者日止。”', '《资治通鉴（陈纪）》是司马光创作的中国史类书籍。', '', '', NULL, '', 'indent', 1565181984, '5c1cb7f89f5454007071a6af', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640860, '伪古文尚书·周书·旅獒', NULL, 26, 14, 1, 2, '王肃', NULL, 37087, '5e9aab01671c4f00082fea3d', '三国', 'wen', '文', '', '', '西旅献獒，太保作《旅獒》。
惟克商，遂通道于九夷八蛮。西旅厎贡厥獒，太保乃作《旅獒》，用训于王。
曰：「呜呼！明王慎德，西夷咸宾。无有远迩，毕献方物，惟服食器用。王乃昭德之致于异姓之邦，无替厥服；分宝玉于伯叔之国，时庸展亲。人不易物，惟德其物！德盛不狎侮。狎侮君子，罔以尽人心；狎侮小人，罔以尽其力。不役耳目，百度惟贞。玩人丧德，玩物丧志。志以道宁，言以道接。不作无益害有益，功乃成；不贵异物贱用物，民乃足。犬马非其土性不畜，珍禽奇兽不育于国，不宝远物，则远人格；所宝惟贤，则迩人安。呜呼！夙夜罔或不勤，不矜细行，终累大德。为山九仞，功亏一篑。允迪兹，生民保厥居，惟乃世王。」', '', '', '', NULL, '', 'indent', 1565181988, '5c1cb91d4773f7173644a688', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640861, '上刘右相书', NULL, 4, 132, 1, 1, '王勃', NULL, 10034, '57b9109fa633bd00665dcd5d', '唐', 'wen', '文', 'https://baike.baidu.com/item/%E4%B8%8A%E5%88%98%E5%8F%B3%E7%9B%B8%E4%B9%A6/19329439', '', '盖闻圣人以四海为家，英宰与千龄合契。用能不行而至，春霆仗天地之威；以息相吹，时雨郁山川之兆。故有元蛟晚集，凭鹤鼎而先鸣；苍兕晨惊，运龙韬而首出。并能风腾雾跃，指麾成烈士之功；蠖屈虬奔，谈笑坐群卿之右。未如越苍海，弃行间，排紫微，谒天子。于是遭不讳之主，拥非常之位。龙章凤黻照其前，锵金鸣玉叠其后。三灵叶赞，超然奉天下之图；四海承平，高步取寰中之托。君侯之富贵足矣，圣朝之付遇深矣。
故知阳侯息浪，长鲸卧横海之鳞；风伯停机，大鹏铩垂天之翼。及其投形巨壑，触丹浦而雷奔；假势灵飙，指青霄而电击。神气洋洋，谓鳞翮使之然也。殊不知两仪超忽，动止系于无垠；万化纠纷，舒卷存乎非我。是以陈平昔之智士也，俯同降卒；百里奚曩之达人也，亲为饿隶。当其背强敌，转康衢，雄虑耿于风？，危途迫于朝夕，岂自期荣称相府，西藩开虎据之图；宠冠斋坛，东向举能飞之策？顾盼可以荡川岳，咄嗟可以降雷雨。遂令用与不用，是非于楚汉之间；知与不知，得失于虞秦之际。故曰：死生有数，审穷达者系于天；材运相符，决行藏者定于已。君侯足下可不谓然乎？
借如勃者，眇小之一书生耳，曾无击钟鼎食之荣，非有南邻北阁之援。山野悖其心迹，烟雾养其神爽。未尝降身摧气，逡巡于列相之门；窃誉干时，匍匐于群公之室。所以慷慨于君侯者，有气存乎心耳。实以四海兄弟，齐远契于萧、韩；千载风？，托神知于管、鲍。不然，则荷裳桂楫，拂衣于东海之东；菌阁松楹，高枕于北山之北。焉复区区屑屑，践名利之门哉？
至尊以摇河徙岳之威，当立地开天之运。圣人有作，群材毕举。星辰入仕，揖让朱鸟之门；风雨称臣，奔走苍龙之阙。方欲停旒金室，引成康于已往；辟纩瑶林，复尧舜于兹日，可谓明明穆穆，尽天子之容貌矣。
抑尝闻之：丹山九仞，烟峰非数篑之功；紫极千门，？台俟万楹之力。故天下至旷，神器不可独专；天道无私，元勋有待而立。《书》曰：「元首明哉！股肱良哉！」好问则裕，自用则小。况掌万国之权，受一人之宠，动见臧否，言知利害。君侯足下何时易耶？虽国有大命，不资童子之言；而恭此小心，敢进狂夫之说？伏见辽阳未靖，大军频进，有识寒心，群黎破胆。昔明王之制国也，自近而及远，先仁而后罚，徵实则郊存，徇名则功浅。是以农疏十野，仅逾重石之乡；禹截九州，不叙流沙之境。岂才不及而智有遗哉？将以辨离方而存正功也。虽至人无外，甲兵曜天子之威；王事有征，金鼓发将军之气。而长城在界，秦汉所以失全昌；巨海横流，天地所以限殊俗。辟土数千里，无益神封；勒兵十八万，空疲帝卒。惊烽走传，骇秦洛之；飞刍免粟，竭淮海之费。于是乘奸放命者出绳纟墨以生威。因公挟私者入闾阎而竞法。虽一物失所，太阶延旰食之忧；而百战方雄，中国鲜终年之乐。图得而不图失，知利而不知害。移手足之病，成心腹之疾。征税屈于东西，威信蹇于表里。语曰：「胜之不武，不胜为辱，天下之责，四面至矣。」诚可远凝高策，上荐忠言，决人事于去就，合天情于终始。遂令回麾转檄，背青邱而骛；列障分亭，巡苍波而守。昔者齐侯以力，方城为楚国之辞；虞帝崇文，苗人失洞庭之险。况乎仗德绥乱，以直乘邪，明逆顺之端，耸华夷之望，虽复舳舻沸海，旌旗触天，铁山四面，金城千里，亦不能为敌人计矣。此君侯之未谕一也。
盖闻星回日运，御洪荒者贞夫一；电照风行，制寥廓者归乎静。《易》曰：「复其见天地之心乎？」语曰：「动之斯和，绥之斯来。」是知源洁则流清，形端则影直，大道起而仁义息，神化周而市狱定。虽复体元立教，眚灾耀知远之书；顺时宰物，宥罪发精微之典。而况浇风易渐，淳化难归？孔明耿介于当朝，子舆殷勤于易箦，盖有由也。伏见边凶尚梗，殊恩屡发，亡命山泽者，日月相趋，朝脱桎梏，夕还囹圄。奸徒抱袂因时立侥幸之谋；顽夫顿足，中路纡吁嗟之惨。皆由宽胜于猛，人迷所习，劝沮不彰，廉耻相冒。亦有公卿失职，耻受符之任；郎宫有衅，俯舍铜墨之荣。又焉可以宏长风流，抑扬众务者也？且夫朽索充羁，不收奔马之逸；轻缗振网，或随吞舟之势。况非常之化，方洽于齐人；无妄之恩，乃及于群小。将恐匡衡、管仲，复灵诏于下泉矣。古之善为国者不然。信赏而必罚，道德而齐礼，泽配风雨而无曲惠，威振雷霆而绝私戮。交书耸币，伏慈厚之师；投金散璧，树仁明之长。故虽开衢室，盖明堂，亦将四三皇而六五帝矣，此君侯之未谕二也。
盖《易》曰：「天地之大德曰生，圣人之大宝曰位，何以守位曰仁，何以聚人曰财。」是知发挥地利，农桑启其业；振荡天功，泉贝流其用。伏睹前制屡扰，事非画一，廛市萧然，人情怪动，夫烦简并用，未尽交易之宜；轻重齐行，适启兼并之路。于是连掩者，闭肆而乘其屈；布衣韦带者，阖门而受其困。五方竞爽，务浅术以相雄；百郡争胜，驱末技而成弊。田夫织妇，衣食鲜终朝之给；巨驵洪商。舆马挟封君之势，盖有由来矣。故曰国储阙于九载，则公上无所给；家廪乏于三年，则妻子非其有。夫阴阳覆逆，天地之常数；百六运穷，汤尧所不免。一旦洪泉决地，大旱焦山，风雨于一岁之间，霜雹于数州之境。繁运广役，首尾于中外；沓税增徭，日夕们都鄙。燮阴阳者，将何以处之？一夫窃议，公之盛德亏矣。愚谓严程峻法，绝轻陋之货，则奸之源塞矣。沿风正典，重耕耘之务，则邪赢之计沮矣。然后远宏教旨，大变流俗，法立有犯而必施，令出唯行而不返。违公窃铸者，具五刑之戮；因时力田者，悬一命之赏。不然，则贾生、晃错，复流涕而言矣，此君侯之未谕三也。
嵩衡不拒细壤，故能崇其峻；江海不让纤流，所以存其广。是以星台晓辟，上台忘吐握之劳；月殿宵兴，中宇轸山林之慕。知夫御天下者，必待人也。《诗》曰：「济济多士，文王以宁。未见君子，忧心如醉。」伏见皇明远烛，帝采遐宣，张乐岱郊，腾勋社首。徵廉察孝，瑶坛虚不次之阶；署行议年，检动非常之诏。天下可谓幸甚矣。于是友月朋霞之客，背青皋而至；冯唐颜驷之才，排紫阁而集。夫岂知终始异数，泾渭同流，萝薜失图，簪缨解体？惜哉！群英雾散，名侯招蔽善之嫌；天下雷同，君子鲜长鸣之地。而欲招绝足，致真龙，难矣！此君侯之未谕四也。
《易》曰：「拔茅连茹，以其汇征吉。」岂非顺物不若招类，报国不如进贤。阳事而雨露归，阴驾凝而风霜厉。莫不观时有记，抚气相求。穷则独善其私，达则兼善天下。而利已疵物者，以自任为身谋；知进忘退者，谓专荣而得计。岂知夫尺波易谢，寸晷难留？陵谷好迁，乾坤忌满？君侯足下出纳王命，升降天衢，激扬凤之前，趋步麟台之上，亦复知天下有遗俊乎？夫心之精微，口不能言也；言之微妙，书不能文也。伏愿辟东阁，开北堂，待之以上宾，期之以国士，使得披肝胆，布腹心，大论古今之利害，高谈帝王之纲纪。然后鹰扬豹变，出蓬户而拜青墀；附景抟风，舍苔衣而见绛阙。幸甚！斯不为难矣。庶几乎卵不弃，终感元枵之精；骏骨时收，或致飞黄之锡。书生王勃死罪死罪再拜。
', '《上刘右相书》是唐代文学家王勃创作的名篇。', '', '', NULL, '', 'indent', 1565181991, '5c1cb9fd808ca40073399d33', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640862, '管子 · 九守', NULL, 3, 573, 1, 1, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E7%AE%A1%E5%AD%90%C2%B7%E4%B9%9D%E5%AE%88/19831146?fr=aladdin', '', '主位
安徐而静，柔节先定，虚心平意以待须。
主明
目贵明，耳贵聪，心贵智。以天下之目视则无不见也，以天下之耳听则无不闻也，以天下之心虑则无不知也。辐凑并进，则明不塞矣。
主听
听之术，曰：勿望而距，勿望而许。许之则失守，距之则闭塞。高山，仰之不可极也；深渊，度之不可测也。神明之德，正静其极也。
主赏
用赏者贵诚，用刑者贵必。刑赏信必于耳目之所见，则其所不见，莫不暗化矣。诚，畅乎天地，通于神明，见奸伪也？
主问
一曰天之，二曰地之，三曰人之，四（曰）上下，左右前后，荧惑其处安在？
主因
心不为九窍，九窍治；君不为五官，五官治。为善者，君予之赏；为非者，君予之罚。君因其所以来，因而予之，则不劳矣。圣人因之，故能掌之。因之修理，故能长久。
主周
人主不可不周。人主不周则群臣下乱。寂乎其无端也。外内不通，安知所怨？关闬不开，善否无原。
主参
一曰长目，二曰飞耳，三曰树明。明知千里之外，隐微之中，曰动奸。奸动则变更矣。
督名
修名而督实，按实而定名。名实相生，反相为情。名实当则治，不当则乱。名生于实，实生于德，德生于理，理生于智，智生于当。', '《管子·九守》是春秋时期军事家管仲创作的一篇散文。管子一书是稷下道家推尊管仲之作的集结，即以此为稷下之学的管子学派。《汉书·艺文志》将其列入子部道家类，《隋书·经籍志》列入法家类。《四库全书》将其列入子部法家类。书篇幅宏伟，内容复杂，思想丰富，是研究中国古代特别是先秦学术文化思想的重要典籍。', '', '主位
安定沉着而保持静默，和柔克制而率先保持镇定，虚心平意地准备着和等待着。
主明
目贵在明，耳贵在聪，心贵在智。利用天下人的眼睛看，没有看不到的事物；利用天下人的耳朵听，没有听不到的消息；利用天下人的心思考虑，就没有理解不了的问题。集中大家的力量共同行事，聪明就不会被蒙蔽了。
主听
听取情况的方法是：不要一下子就拒绝，也不要一下子就肯定。肯定则可能失误，拒绝则可能闭塞。要象高山一样，仰视看不到顶；象深渊一样，计量摸不到底。象神明的德性一样，端正、冷静到极点。
主赏
行赏贵在信实。处刑贵在坚决。刑赏信实坚决，对于亲身耳闻目见的人兑现了，那么，没有亲身见到的，也无不潜移默化了。“信实”这一点，有着畅行天地、通于神明的力量，何况对于奸邪的人们呢？
主问
一是天上的，二是地上的，三是人间的。四方上下，左有前后。不清楚之处都在哪里呢？
主因
心不包办九窍的事，九窍会治理得好；君主不包办大臣的事，大臣会治理得好。做好了的，君主给予赏赐；犯错误的，君主给予刑罚。君主只需利用人们提供的成果，因而给予赏罚就不至政务烦劳了。圣人就是能做到“因势利导”，所以就能管理。因势利导能够合理，所以国运长久。
主周
人君不可不注意保密，不保密则群臣在下面会发生混乱。静默地不露出任何倾向，使内外不串通消息，人们怎么能产生不满呢？传话的门户不开，好坏的传闻也就没有发源地了。
主参
第一是看得远，第二是听得远，第三是做到明察。明察到了解千里之外和隐微之中的情况，便可以洞察奸恶。奸恶被洞察，变乱就被阻止了。
督名
依照名称考察实际，根据实际确定名称。名、实互相促进，反过来又互为说明。名实相当则治，不相当则乱。名产生于实，实产生于德，德产生于理，理产生于智，智则产生于“当”。', NULL, '', 'indent', 1565182003, '5c1cbaa31579a3005fd40ee0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640863, '答宣大巡抚吴环洲策黄酋', NULL, 5, 23, 1, 1, '张居正', NULL, 16508, '5858eaff128fe10069b2675c', '明', 'wen', '文', '', '', '黄酋书，昨鉴川公亦曾抄寄本兵。此酋贪纵寡谋，终当归吾羁绁。观其书词，已非昔时之倔强，可用其几而制之。多行间谍，以疑其心，时用利饵，以中其欲。谅彼无能为也。其妻家在三卫者，即传与蓟人，量加优恤，亦制驭之一机也。……但愿审度时宜，虑定而动，天下无不可为之事。况今时则易然耳。', '', '', '', NULL, '', 'indent', 1565182007, '5c1cbb5b9f5454007071d818', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640864, '策略第四', NULL, 9, 3406, 1, 1, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'wen', '文', '', '', '夫宽深不测之量，古人所以临大事而不乱，有以镇世俗之躁，盖非以隔绝上下之情，养尊而自安也。', ' “临大事而不乱”，出自宋仁宗嘉祐五年（1060年）苏轼应制科考试的试卷《策略》，苏轼时年23岁；“临利害之际不失故常”，则出自苏轼在任翰林学士知制诰时为皇帝代拟的圣旨《陈侗知陕州制》。
早在青年时代，苏轼就主张革新政治。在这篇《策略》中，苏轼认为圣人之道在于诚，因此，为政者应以诚为本，要有古代圣贤的宽深的胸襟，能临大事而不乱，有所决断才能有助于民。故曰：“夫宽深不测之量，古人所以临大事而不乱，有以镇世俗之躁。”后来，他又提出了“临利害之际而不失故常”的观点，主张在紧要关头，要保持原有的常态。', '', '', NULL, '', 'indent', 1565182010, '5c1cbc58808ca4565c8951a6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640865, '冬至', NULL, 14, 7, 0, 1, '龙辅', NULL, 17638, '5858ebfd128fe1006dcc4fa2', '明', 'shi', '诗', '', '', '冬至宵难短，孤眠恨自长。
枕单寒入梦，窗破月窥床。', '', '', '', NULL, '', 'center', 1545471272, '5c1d94d3fb4ffe005f276bcf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640899, '盐铁论 · 后刑第三十四', NULL, 13, 2, 1, 1, '桓宽', NULL, 36984, '5c1c44b167f356005fd3aef2', '汉', 'wen', '文', '', '', '大夫曰：古之君子，善善而恶恶。人君不畜恶民，农夫不畜无用之苗。无用之苗，苗之害也；无用之民，民之贼也。锄一害而众苗成，刑一恶而万民悦。虽周公、孔子不能释刑而用恶。……故刑所以正民，锄所以别苗也。', '《盐铁论》是西汉的桓宽根据著名的“盐铁会议”记录整理撰写的重要史书，书中记述了当时对汉武帝时期的政治、经济、军事、外交、文化的一场大辩论。', '', '', NULL, '', 'indent', 1545875616, '5c23c04b67f356005f267b8d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640902, '千字文', NULL, 1054, 4, 8, 0, '周兴嗣', NULL, 10395, '57e6969467f356005794443d', '南北朝', 'wen', '文', 'https://baike.baidu.com/item/%E5%8D%83%E5%AD%97%E6%96%87/447586?fr=aladdin', '', '天地玄黄，宇宙洪荒。
日月盈昃，辰宿列张。
寒来暑往，秋收冬藏。
闰余成岁，律吕调阳。
云腾致雨，露结为霜。
金生丽水，玉出昆冈。
剑号巨阙，珠称夜光。
果珍李柰，菜重芥姜。
海咸河淡，鳞潜羽翔。
龙师火帝，鸟官人皇。
始制文字，乃服衣裳。
推位让国，有虞陶唐。
吊民伐罪，周发殷汤。
坐朝问道，垂拱平章。
爱育黎首，臣伏戎羌。
遐迩壹体，率宾归王。
鸣凤在竹，白驹食场。
化被草木，赖及万方。
盖此身发，四大五常。
恭惟鞠养，岂敢毁伤。
女慕贞洁，男效才良。
知过必改，得能莫忘。
罔谈彼短，靡恃己长。
信使可覆，器欲难量。
墨悲丝染，诗赞羔羊。
景行维贤，克念作圣。
德建名立，形端表正。
空谷传声，虚堂习听。
祸因恶积，福缘善庆。
尺璧非宝，寸阴是金。
资父事君，曰严与敬。
孝当竭力，忠则尽命。
临深履薄，夙兴温凊。
似兰斯馨，如松之盛。
川流不息，渊澄取映。
容止若思，言辞安定。
笃初诚美，慎终宜令。
荣业所基，籍甚无竟。
学优登仕，摄职从政。
存以甘棠，去而益咏。
乐殊贵贱，礼别尊卑。
上和下睦，夫唱妇随。
外受傅训，入奉母仪。
诸姑伯叔，犹子比儿。
孔怀兄弟，同气连枝。
交友投分，切磨箴规。
仁慈隐恻，造次弗离。
节义廉退，颠沛匪亏。
性静情逸，心动神疲。
守真志满，逐物意移。
坚持雅操，好爵自縻。
都邑华夏，东西二京。
背邙面洛，浮渭据泾。
宫殿盘郁，楼观飞惊。
图写禽兽，画彩仙灵。
丙舍傍启，甲帐对楹。
肆筵设席，鼓瑟吹笙。
升阶纳陛，弁转疑星。
右通广内，左达承明。
既集坟典，亦聚群英。
杜稿钟隶，漆书壁经。
府罗将相，路侠槐卿。
户封八县，家给千兵。
高冠陪辇，驱毂振缨。
世禄侈富，车驾肥轻。
策功茂实，勒碑刻铭。
磻溪伊尹，佐时阿衡。
奄宅曲阜，微旦孰营。
桓公匡合，济弱扶倾。
绮回汉惠，说感武丁。
俊乂密勿，多士寔宁。
晋楚更霸，赵魏困横。
假途灭虢，践土会盟。
何遵约法，韩弊烦刑。
起翦颇牧，用军最精。
宣威沙漠，驰誉丹青。
九州禹迹，百郡秦并。
岳宗泰岱，禅主云亭。
雁门紫塞，鸡田赤城。
昆池碣石，钜野洞庭。
旷远绵邈，岩岫杳冥。
治本于农，务兹稼穑。
俶载南亩，我艺黍稷。
税熟贡新，劝赏黜陟。
孟轲敦素，史鱼秉直。
庶几中庸，劳谦谨敕。
聆音察理，鉴貌辨色。
贻厥嘉猷，勉其祗植。
省躬讥诫，宠增抗极。
殆辱近耻，林皋幸即。
两疏见机，解组谁逼。
索居闲处，沉默寂寥。
求古寻论，散虑逍遥。
欣奏累遣，戚谢欢招。
渠荷的历，园莽抽条。
枇杷晚翠，梧桐早凋。
陈根委翳，落叶飘飖。
游鲲独运，凌摩绛霄。
耽读玩市，寓目囊箱。
易輶攸畏，属耳垣墙。
具膳餐饭，适口充肠。
饱饫烹宰，饥厌糟糠。
亲戚故旧，老少异粮。
妾御绩纺，侍巾帷房。
纨扇圆洁，银烛炜煌。
昼瞑夕寐，篮笋象床。
弦歌酒宴，接杯举觞。
矫手顿足，悦豫且康。
嫡后嗣续，祭祀烝尝。
稽颡再拜，悚惧恐惶。
笺牒简要，顾答审详。
骸垢想浴，执热愿凉。
驴骡犊特，骇跃超骧。
诛斩贼盗，捕获叛亡。
布射僚丸，嵇琴阮啸。
恬笔伦纸，钧巧任钓。
释纷利俗，并皆佳妙。
毛施淑姿，工颦妍笑。
年矢每催，曦晖朗曜。
璇玑悬斡，晦魄环照。
指薪修祜，永绥吉劭。
矩步引领，俯仰廊庙。
束带矜庄，徘徊瞻眺。
孤陋寡闻，愚蒙等诮。
谓语助者，焉哉乎也。', '千字文，由南北朝时期梁朝散骑侍郎、给事中周兴嗣编纂、一千个汉字组成的韵文（在隋唐之前，不押韵、不对仗的文字，被称为「笔」，而非「文」）。梁武帝命人从王右军书法作品中选取千个不重复汉字，命员外散骑侍郎周兴嗣编纂成文。全文为四字句，对仗工整，条理清晰，文采斐然。《千字文》语句平白如话，易诵易记，是中国影响很大的儿童启蒙读物。', '盈昃（zè）：盈：月光圆满。昃：太阳西斜。
宿（xiù）〈古〉中国天文学家将天空中某些星的集合体叫做「宿」。
律吕：律管和吕管，中国古代用来校定音律的一種设备，相当于现代的定音器。中国古代将一个八度分为十二个不完全相等的半音，从低到高依次排列，每个半音称为一律，其中奇数各律叫做「律」，偶数各律叫做「吕」，十二律分为「六律」、「六吕」，简称「律吕」。相传黄帝时伶伦制乐，用律吕以调阴阳。
崑冈：崑崙山。
夜光：《搜神记》中说，隋侯救好了一条受伤的大蛇，后来大蛇衔了一颗珍珠来报答他的恩情，那珍珠夜间放射出的光辉能照亮整个殿堂，因此人称「夜光珠」。
李柰（nài）：两種水果的名称，「李」是李子；「柰」是柰子，果木名，落葉小乔木，花白色，果小，俗名花红，又叫沙果。
龙师：相传伏羲氏用龙给百官命名，因此叫他「龙师」。
火帝：神农氏用火给百官命名，因此叫他「火帝」。
鸟官：少昊（hào）氏用鸟给百官命名，叫他「鸟官」。
人皇：传说中的三皇之一。《史记·补三皇本纪》中说：「人皇有九个头，乘着云车，驾着六隻大鸟，兄弟九人，分掌九州，各立城邑」，共传了一百五十代，合计四萬五千六百年。
陶唐：陶唐氏，传说中的远古部落名，尧是它的首领。这裏指尧，又称唐尧。尧当了七十年君主，他死时把君位让给了舜；舜当了五十年君主，又把君位传给了禹；史称「禅（shàn）让」。
率宾：出自《诗经》：「普天之下，莫非王土；率土之滨，莫非王臣。」
盖此身发，四大五常。恭惟鞠养，岂敢毁伤。
四大：指地、水、风、火四種元素。
五常：指儒家认为人应具备的五種品德，即仁、义、礼、智、信。
恭惟鞠（jū）养：恭惟也作恭维，对上的谦辞，一般用于文章开头。鞠养，抚养，养育。
笃初诚美，慎终宜令。荣业所基，藉甚无竟。
籍甚：盛大。
学优登仕，摄职从政。存以甘棠，去而益咏。
摄（shè）：代理。
甘棠：木名。即棠梨。《史记·燕召公世家》：「周武王之灭纣，封召公于北燕……召公巡行乡邑，有棠树，决狱政事其下，自侯伯至庶人各得其所，无失职者。召公卒，而民人思召公之政，怀棠树不敢伐，哥咏之，作《甘棠》之诗。」后遂以「甘棠」称颂循吏的美政和遗爱。
邑（yì）：国都，京城。
甲帐：汉武帝时所造的帐幕。
横：连横。战国时，苏秦说（shuì）六国联合拒秦，史称「合纵」。张仪主和拆散合纵，使六国一个个服从秦国，称为「连横」。由于连横，秦国采取远交近攻政策，首先打击赵、魏，所以说「赵魏困横」。
蚤（zǎo）：通「早」，指月初或早晨。
攸（yōu）：所。
垣（yuán）：矮墙，也泛指墙。
毛施：毛嫱（qiáng）和西施。《庄子·齐物论》：「毛嫱、西施，人之所美也。」
工：善。
颦（pín）：皱眉。
妍（yán）：美丽。
璇玑（xuánjī）：古代称北斗星的第一星至第四星。
斡（wò）：旋转。
晦魄：月亮。', '天是青黑色的，地是黄色的，宇宙形成于混沌蒙昧的状态中。太阳正了又斜，月亮圆了又缺，星辰布满在无边的太空中。
寒暑循环变换，来了又去，去了又来；秋天收割庄稼，冬天储藏粮食。积累数年的闰馀并成一个月，放在闰年裏；古人用六律六吕来调节阴阳。
云气上升遇冷就形成了雨，夜裏露水遇冷就凝结成霜。黄金产在金沙江，玉石出在崑崙山岗。
最锋利的宝剑叫「巨阙」，最贵重的明珠叫「夜光」。水果裏最珍贵的是李子和柰子，蔬菜中最重要的是芥菜和生薑。
海水是鹹的，河水是淡的，鱼儿在水中潜游，鸟儿在空中飞翔。龙师、火帝、鸟官、人皇，这都是上古时代的帝皇官员。
苍颉（jié）创制了文字，嫘（léi）祖制作了衣裳。唐尧、虞舜英明无私，主动把君位禅让给功臣贤人。
安抚百姓，讨伐暴君，是周武王姬发和商王成汤。贤明的君主坐在朝廷上向大臣们询问治国之道，垂衣拱手，毫不费力就能使天下太平，功绩彰著。
他们爱抚、体恤老百姓，使四方各族人俯首称臣。普天之下都统一成了一个整体，所有的老百姓都服服帖帖地归顺于他的统治。
凤凰在竹林中欢乐的鸣叫，小白马在草场上自由自在地喫着草食。圣君贤王的仁德之治使草木都沾受了恩惠，恩泽遍及天下百姓。
人的身体发肤分属于「四大」，一言一动都要符合「五常」。诚敬的想着父母养育之恩，哪裏还敢毁坏损伤它。
女子要仰慕那些持身严谨的贞妇洁女，男子要倣效那些有才能有道德的人。知道自己有过错，一定要改正；适合自己幹的事，不要放弃。
不要谈论别人的短处，也不要依仗自己有长处就不思进取。诚实的话要经得起考验，器度要大，让人难以估量。
墨子悲叹白丝被染上了杂色，《诗经》赞颂羔羊能始终保持洁白如一。要仰慕圣贤的德行，要克制私欲，努力倣效圣人。
养成了好的道德，就会有好的名声；就如同形体端庄了，仪表就正直了一样。空旷的山谷中呼喊声传得很远，宽敞的厅堂裏说话声非常清晰。
灾祸是作恶多端的结果，福禄是乐善好施的回报。一尺长的美玉不能算是真正的宝贝，而即使是片刻时光也值得珍惜。
奉养父亲，侍奉君主，要严肃而恭敬。孝顺父母应当竭尽全力，忠于君主要不惜献出生命。
要「如临深渊，如履薄冰」那样小心谨慎；要早起晚睡，侍候父母让他们感到冬暖夏凉。让自己的德行像兰草那样的清香，像松柏那样的茂盛。
还能延及子孙，像大河川流不息；影响世人，像碧潭清澄照人。仪容举止要沉静安详，言语措辞要稳重，显得从容沉静。
无论修身、求学、重视开头固然不错，认真去做，有好的结果更为重要。这是一生荣誉的事业的基础，有此根基，发展就没有止境。
书读好了就能做官，可以行使职权参加国政。周人怀念召伯的德政，召公活着时曾在甘棠树下理政，他过世后老百姓对他更加怀念歌咏。
音乐要根据人们身份的贵贱而有所不同，礼节要根据人们地位的高低而有所区别。上下要和睦相处，夫妇要一唱一随，协调和谐。
在外接受师傅的训诲，在家遵从父母的教导。对待姑姑、伯伯、叔叔等长辈，要像是他们的亲生子女一样。
兄弟之间要相互关心，因为同受父母血气，如同树枝相连。结交朋友要意气相投，要能学习上切磋琢磨，品行上互相告勉。
仁义、慈爱，对人的恻隐之心，在任何时候，任何地方都不能抛离。气节、正义、廉洁、谦让这些品德，在最穷困潦倒的时候也不可亏缺。
保持内心清静平定，情绪就会安逸舒适，心为外物所动，精神就会疲惫困倦。保持自己天生的善性，愿望就可以得到满足，追求物欲享受，善性就会转移改变。
坚定地保持着高雅情操，好的职位自然就会属于你。中国古代的都城华美壮观，有东京洛阳和西京长安。
洛阳北靠邙山，面临洛水；长安北横渭水，远据泾河。宫殿回环曲折，楼臺宫阙凌空欲飞，使人心惊。
宫殿裏画着飞禽走兽，还有彩绘的天仙神灵。正殿两边的配殿从侧面开启，豪华的帐幕对着高高的楹柱。
宫殿裏摆着酒席，弹琴吹笙一片欢腾。官员们上下臺阶互相祝酒，珠帽转动，像满天的星斗。
右面通向用以藏书的广内殿，左面到达朝臣休息的承明殿。这裏收藏了很多的典籍名著，也集着成群的文武英才。
裏边有杜度草书的手稿和钟繇隶书的真迹，有从汲（jí）县魏安厘王冢中发现掘出来的漆写古书，以及汉代鲁恭王在曲阜（fù）孔庙墙壁内发现的古文经书。宫延内将相依次排成两列，宫廷外大夫公卿夹道站立。
他们每家都有八县以上的封地，还有上千名的侍卫武装。戴着高大帽子的官员们陪着皇帝出遊，驾着车马，帽带飘舞着，好不威风。
他们的子孙世代领受俸禄，奢侈豪富，出门时轻车肥马，春风得意。朝廷还详尽确实地记载他们的功德，刻在碑石上流传后世。
周武王磻溪遇吕尚，尊他为「太公望」；伊尹辅佐时政，商汤王封他为「阿衡」。周成王佔领了古奄国曲阜一带地面，要不是周公旦辅政哪裏能成？
齐桓公匡正天下诸侯，都打着「帮助弱小」、「拯救危亡」的旗号。汉惠帝做太子时靠绮里季才幸免废黜，商君武丁感梦而得贤相傅说。
贤才的勤奋谨慎，换来了百官的各安其位。晋文公、楚庄王先后称霸，赵国、魏国受困于连横。
晋国向虞国借路去消灭虢国，晋文公在践土召集诸侯歃血会盟。萧何遵奉汉高祖简约的法律，韩非惨死在他自己所主张的苛刑之下。
秦将白起、王剪，赵将廉颇、李牧，用兵作战最为精通。他们的声威远扬到北方的沙漠，美名和肖像永远流传在千古史册之中。
九州之内都留下了大禹治水的足迹，全国各郡在秦并六国后归于统一。五岳以泰山为尊，历代帝王都在云山和亭山主持禅礼。
名关有北疆雁门，要塞有万里长城，驿站有边地鸡田，奇山有天台赤城。赏池赴昆明滇池，观海临河北碣石，看泽去山东巨野，望湖上湖南洞庭。
中国的土地辽阔遥远，没有穷极，名山奇谷幽深秀丽，气象万千。把农业作为治国的根本，一定要做好播種与收获。
一年的农活该开始幹起来了，種植着小米和黄米。收获季节，用刚熟的新穀交纳税粮，庄稼種得好的受到表彰和赏赐，種得不好的就要受到处罚。
孟子崇尚朴素，史官子鱼秉性刚直。做人要尽可能合乎中庸的标准，必须勤劳谦逊，谨慎检点，懂得规劝告诫自己。
听人说话要审察其中的道理，看人容貌要看出他的心情。要给人家留下正确高明的忠告或建议，勉励别人谨慎小心地处世立身。
听到别人的讥讽告诫，要反省自身；备受恩宠不要得意忘形，对抗权尊。如果知道有危险耻辱的事快要发生就退隐山林，还可以幸免于祸。
汉代疏广、疏受叔姪见机归隐，有谁逼迫他们辞去官职呢？离君独居，悠闲度日，整天不用多费唇舌，清静无为岂不是好事。
探求古人古事，读点至理名言，就可以排除杂念，自在逍遥。轻鬆的事凑到一起，费力的事丢在一边，消除不尽的烦恼，得来无限的快乐。
池塘中的荷花开得多么鲜艳，园林内的青草抽出嫩芽。到了冬天枇杷葉子还是绿的，梧桐一到秋天葉子就凋了。
老树根蜿蜒曲折，落葉在秋风裏四处飘荡。衹有远遊的鲲鹏独立翱翔，直衝布满彩霞的云霄。
汉代王充在街市上沉迷留恋于读书，眼睛注视的全是书袋和书籍。换了轻便的车子要注意危险，说话要防止隔墙有耳。
平时的饭菜，要适合口味，让人喫得饱。饱的时候自然满足于大鱼大肉，饿的时候应当满足于粗菜淡饭。
亲属、朋友会面要盛情款待，老人、小孩的食物应和自己不同。小妾婢女要管理好家务，尽心恭敬地服侍好主人。
圆圆的绢扇洁白素雅，白白的蜡烛明亮辉煌。白日小憩，晚上就寝，有青篾编成的竹席和象牙雕屏的床榻。
奏着乐，唱着歌，摆酒开宴；接过酒杯，开怀畅饮。情不自禁地手舞足蹈，真是又快乐又安康。
子孙一代一代传续，四时祭祀不能懈怠。跪着磕头，拜了又拜；礼仪要周全恭敬，心情要悲痛虔诚。
给人的书信要简明扼要，回答别人的问题时要审慎周详。身上髒了就想洗个澡，捧着热东西就希望它有风把它吹凉。
家裏有了灾祸，连驴子、骡子，大小牲口都会受惊，狂蹦乱跳，东奔西跑。官府诛杀盗贼，捕获叛乱分子和亡命之徒。
吕布善于射箭，宜僚善玩弹丸，嵇康善于弹琴，阮籍善于撮口长啸。蒙恬制造了毛笔，蔡伦发明了造纸，马钧发明了水车，任公子善于钓鱼。
他们或者善于为人解决纠纷，或者善于发明创造有利于社会，这些都非常巧妙。毛嫱、西施，姿容姣美，哪怕皱着眉头，也像美美的笑。
青春易逝，岁月匆匆催人渐老，衹有太阳的光辉永远朗照。高悬的北斗随着四季变换转动，明晦的月光洒遍人间每个角落。
顺应自然，修德积福，永远平安，多么美好。如此心地坦然，方可以昂头迈步，一举一动都像在神圣的庙宇中一样仪表庄重。
衣带穿着整齐端庄，举止从容，高瞻远瞩。这些道理孤陋寡闻就不会明白，衹能和愚昧无知的人一样空活一世，让人耻笑。
说到古书中的语助词，那就是「焉」、「哉」、「乎」、「也」了。', NULL, '', 'center', 1546003170, '5c25b28b9f54540070d3bf27', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640906, '诫子书', NULL, 723, 60, 1, 2, '诸葛亮', NULL, 10026, '57b8f8452e958a005fa50d86', '三国', 'wen', '文', 'https://baike.baidu.com/item/%E8%AF%AB%E5%AD%90%E4%B9%A6/394?fr=aladdin', '', '夫君子之行，静以修身，俭以养德。非淡泊无以明志，非宁静无以致远。夫学须静也，才须学也，非学无以广才，非志无以成学。淫慢则不能励精，险躁则不能冶性。年与时驰，意与日去，遂成枯落，多不接世，悲守穷庐，将复何及！', '《诫子书》是三国时期政治家诸葛亮临终前写给他儿子诸葛瞻的一封家书。从文中可以看作出诸葛亮是一位品格高洁、才学渊博的父亲，对儿子的殷殷教诲与无限期望尽在此书中。全文通过智慧理性、简练谨严的文字，将普天下为人父者的爱子之情表达得非常深切，成为后世历代学子修身立志的名篇。', '诫：警告，劝人警惕。
夫（fú）：发语词，无实义。
君子：品德高尚的人。指操守、品德、品行。
修身：个人的品德修养。
养德：培养品德。
淡泊：一作“澹（dàn）泊”，清静而不贪图功名利禄。内心恬淡，不慕名利。清心寡欲。
明志：表明自己崇高的志向。
宁静：这里指安静，集中精神，不分散精力。
致远：实现远大目标。
广才：增长才幹。
成：达成，成就。
淫慢：一作“慆（tāo）慢”，漫不经心。慢：懈怠，懒惰。
励精：尽心，专心，奋勉，振奋。
险躁：冒险急躁，狭隘浮躁，与上文「宁静」相对而言。
冶性：陶冶性情。
与：跟随。
驰：疾行，增长之义。
日：时间。
去：消逝，逝去。
枯落：枯枝和落叶，此指像枯叶一样飘零，形容人韶华逝去。
多不接世：意思是对社会没有任何贡献。接世，接触社会，承担事务，对社会有益。有「用世」的意思。
穷庐：破房子。
将复何及：又怎么来得及。', '君子的行为操守，从宁静来提高自身的修养，以节俭来培养自己的品德。不恬静寡欲无法明确志向，不排除外来干扰无法达到远大目标。学习必须静心专一，而才干来自学习。所以不学习就无法增长才干，没有志向就无法使学习有所成就。放纵懒散就无法振奋精神，急躁冒险就不能陶冶性情。年华随时光而飞驰，意志随岁月而流逝。最终枯败零落，大多不接触世事、不为社会所用，只能悲哀地坐守着那穷困的居舍，其时悔恨又怎么来得及？', NULL, '', 'indent', 1546015776, '5c25e39c808ca4565cedd740', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640908, '前赤壁赋', NULL, 1894, 3406, 3, 16, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'wen', '文', 'https://baike.baidu.com/item/赤壁赋', '', '壬戌之秋，七月既望，苏子与客泛舟游于赤壁之下。清风徐来，水波不兴。举酒属客，诵明月之诗，歌窈窕之章。少焉，月出于东山之上，裴回于斗牛之间。白露横江，水光接天。纵一苇之所如，陵万顷之茫然。浩浩乎如凭虚御风，而不知其所止；飘飘乎如遗世独立，羽化而登仙。
于是饮酒乐甚，扣舷而歌之。歌曰：“桂棹兮兰桨，击空明兮溯流光。渺渺兮余怀，望美人兮天一方。”客有吹洞箫者，倚歌而和之。其声呜呜然，如怨如慕，如泣如诉；馀音袅袅，不绝如缕。舞幽壑之潜蛟，泣孤舟之嫠妇。
苏子愀然，正襟危坐，而问客曰：“何为其然也？”客曰：“‘月明星稀，乌鹊南飞。’此非曹孟德之诗乎？西望夏口，东望武昌，山川相缪，郁乎苍苍，此非孟德之困于周郎者乎？方其破荆州，下江陵，顺流而东也，舳舻千里，旌旗蔽空，酾酒临江，横槊赋诗，固一世之雄也，而今安在哉？况吾与子渔樵于江渚之上，侣鱼虾而友麋鹿，驾一叶之扁舟，举匏樽以相属。寄蜉蝣于天地，渺浮海之一粟。哀吾生之须臾，羡长江之无穷。挟飞仙以遨游，抱明月而长终。知不可乎骤得，托遗响于悲风。”
苏子曰：“客亦知夫水与月乎？逝者如斯，而未尝往也；赢虚者如彼，而卒莫消长也。盖将自其变者而观之，则天地曾不能以一瞬；自其不变者而观之，则物与我皆无尽也，而又何羡乎！且夫天地之间，物各有主，苟非吾之所有，虽一毫而莫取。惟江上之清风，与山间之明月，耳得之而为声，目遇之而成色，取之无禁，用之不竭。是造物者之无尽藏也，而吾与子之所共食。”
客喜而笑，洗盏更酌。肴核既尽，杯盘狼籍。相与枕藉乎舟中，不知东方之既白。', '《赤壁赋》是北宋文学家东坡创作的一篇赋，作于宋神宗元丰五年贬谪黄州（今湖北黄冈）时。本篇文字以台北故宫博物院所藏东坡真迹为正。
此赋记叙了作者与朋友们月夜泛舟游赤壁的所见所感，以作者的主观感受为线索，通过主客问答的形式，反映了作者由月夜泛舟的舒畅，到怀古伤今的悲咽，再到精神解脱的达观。全赋在布局与结构安排中映现了其独特的艺术构思，情韵深致、理意透辟，在中国文学上有着很高的文学地位，并对之后的赋、散文、诗产生了重大影响。', '壬戌（rénxū）：元丰五年，岁次壬戌。古代以干支纪年，该年为壬戌年。
既望：农历毎月十六。农历毎月十五日为望日，十六日为既望。
徐：缓缓地。
兴：起。
属（zhǔ）：倾注，引申为劝酒。
明月之诗：指《诗经·陈风·月出》。
窈窕（yǎotiǎo）之章：《陈风·月出》诗首章为：“月出皎兮，佼人僚兮，舒窈纠兮，劳心悄兮。”“窈纠”同“窈窕”。
少焉：一会儿。
裴回：意同“徘徊”。此处苏轼墨迹原作“裴回”，非教科书所写的“徘徊”。
斗牛：星座名，即斗宿（南斗）、牛宿。
白露：白茫茫的水气。
横江：横贯江面。
“纵一苇之所如，陵万顷之茫然”句：任凭小船在宽广的江面上飘荡。纵，任凭。一苇，喻极小的船。《诗经·卫风·河广》：“谁谓河广，一苇杭（航）之。”如，往。凌，越过。万顷，极为宽阔的江面。
茫然：旷远的样子。
凭虚御风：乘风腾空而遨遊。虚，太空。凭虚，凌空；御，驾御。教科书中作“冯虚”，实误，东坡真迹为“憑虛”二字，“冯（馮）虚”版本系传抄过程中心字底脱落所致。
遗世：离开尘世。
羽化：传说成仙的人能像长了翅膀一样飞昇。
登仙：登上仙境。
扣舷（xián）：敲打着船边，指打节拍。
桂棹（zhào）兰桨：桂树做的棹，兰木做的桨。
空明：月亮倒映水中的澄明之色。
溯：逆流而上。
流光：在水波上闪动的月光。
渺渺：悠远的样子。
余怀：教科书中作“予怀”，实误，东坡自书原迹为“余怀”，可见“予怀”版本是编书者失误不察所致。
美人：喻心中美好的理想或好的君王。
倚歌：按照歌曲的声调节拍。
和：同声相应，唱和。
怨：哀怨。
慕：眷恋。
余音：尾声。
袅袅（niǎo）：形容声音婉转悠长。
缕：细丝。
幽壑：深谷，这里指深渊。此句意谓：潜藏在深渊里的蛟龙为之起舞。
嫠（lí）妇：寡妇。唐·白乐天《琵琶行》写孤居商人妻云：“去来江口守空船，绕舱明月江水寒。夜深忽梦少年事，梦啼妆泪红阑干。”这里化用其事。
愀（qiǎo）然：容色改变的样子。
正襟危坐：整理衣襟，（严肃地）端坐着。
何为其然也：箫声为什么会这么悲凉呢？
夏口：故城在今湖北武昌。
武昌：今湖北鄂城县。
缪（liáo）：通“缭”，盘绕。
郁：茂盛的样子。
孟德之困于周郎：指汉献帝建安十三年，吴将周公瑾败曹孟德八十万大军于赤壁。周郎，公瑾二十四岁拜中郎将，吴中皆呼为“周郎”。
荆州：辖南阳、江夏、长沙等八郡，今湖南、湖北一带。
江陵：当时的荆州首府，今湖北县名。
“方其破荆州，下江陵，顺流而东也”句：指建安十三年刘琮率众降于曹孟德，曹军不战而占领荆州、江陵。方，当。
舳舻（zhúlú）：战船前后相接，这里指战船。
酾（shī）酒：滤酒，这里指斟酒。
横槊（shuò）：横执长矛。槊，长矛。
侣：以……为伴侣，这里为意动用法。
麋（mí）：鹿的一种。
扁（piān）舟：小舟。
匏（páo）樽：用葫芦做成的酒器。匏，葫芦。
寄：寓托。
蜉蝣（fúyóu）：一种朝生暮死的昆虫。此句喻人生之短暂。
渺：小。
浮海：大海。此句喻人类在天地之间极为渺小。教科书中作“沧海”，而东坡自书墨迹中实为“浮海”二字，“沧海”版本是为后世编者不察而留下的传抄错误。
须臾：片刻，形容生命之短。
长终：至于永远。
骤：多。
遗响：馀音，指箫声。
悲风：秋风。
逝者如斯：流逝的像这江水。语出《论语·子罕》：“子在川上曰：‘逝者如斯夫，不舍昼夜。’”逝，往；斯，指水。
赢虚者如彼：指月亮的圆缺。此处亦依东坡真迹版本，而不取“盈虚”版本。
卒：最终。
消长：增减。
曾（zēng）不能：固定词组，连……都不够。曾，连……都。
一瞬：一眨眼的工夫。
是：这。
造物者：天地自然。
无尽藏（zàng）：无穷无尽的宝藏。
食：享用。《释典》谓六识以六人为养，其养也胥谓之食，目以色为食，耳以声为食，鼻以香为食，口以味为食，身以触为食，意以法为食。清风明月，耳得成声，目遇成色。故曰“共食”。易以“共适”，则意味索然。当时有问东坡“食”字之义，坡曰：“如食吧之‘食’，犹共用也。”坡盖不欲以博览上人，故权词以答，古人谦抑如此。明代版本将“共食”妄改为“共适”，以致误从至今。
肴核：菜肴、果品。
枕藉：相互靠着。', '壬戌年秋天，七月十六日，我与友人在赤壁下泛舟遊玩。清风阵阵拂来，水面波澜不起。举起酒杯向同伴劝酒，吟诵《明月》中“窈窕”这一章。不一会儿，明月从东山后升起，在斗宿与牛宿之间来回移动。白茫茫的雾气横贯江面，水光连着天际。放纵一片苇叶似的小船随意漂浮，越过茫茫的江面。浩浩淼淼好像乘风凌空而行，并不知道到哪里才会停栖，飘飘摇摇好像要离开尘世飘飞而起，羽化成仙进入仙境。
在这时喝酒喝得非常高兴，敲着船边唱起歌来。歌中唱到：“桂木船棹啊香兰船桨，击打着月光下的清波，在泛着月光的水面逆流而上。我的情思啊悠远茫茫，眺望美人啊，却在天的另一方。”有会吹洞箫的客人，配着节奏为歌声伴和，洞箫的声音呜呜咽咽：有如哀怨有如思慕，既像啜泣也像倾诉，余音在江上回荡，像细丝一样连续不断。能使深谷中的蛟龙为之起舞，能使孤舟上的寡妇为之饮泣。
我的神色也愁惨起来，整好衣襟坐端正，向客人问道：“箫声为什么这样哀怨呢？”客人回答：“‘月明星稀，乌鹊南飞’，这不是曹公孟德的诗么？这里向西可以望到夏口，向东可以望到武昌，山河接壤连绵不绝，目力所及，一片郁郁苍苍。这不正是曹孟德被周瑜所围困的地方么？当初他攻陷荆州，夺得江陵，沿长江顺流东下，麾下的战船首尾相连延绵千里，旗子将天空全都蔽住，面对大江斟酒，横执长矛吟诗，本来是当世的一位英雄人物，然而现在又在哪里呢？何况我与你在江中的小洲打渔砍柴，以鱼虾为侣，以麋鹿为友，在江上驾着这一叶小舟，举起杯盏相互敬酒，如同蜉蝣置身于广阔的天地中，像沧海中的一粒粟米那样渺小。唉，哀叹我们的一生衹是短暂的片刻，不由羡慕长江的没有穷尽。想要携同仙人携手遨游各地，与明月相拥而永存世间。知道这些终究不能实现，只得将憾恨化为箫音，托寄在悲凉的秋风中罢了。”
我问道：“你可也知道这水与月？时间流逝就像这水，其实并没有真正逝去；时圆时缺的就像这月，终究没有增减。可见，从事物易变的一面看来，那么天地间万事万物时刻在变动，连一眨眼的工夫都不停止；而从事物不变的一面看来，万物同我们来说都是永恒的，又有什么可羡慕的呢？何况天地之间，万物各有主宰者，若不是自己应该拥有的，即使一分一毫也不能求取。只有江上的清风，以及山间的明月，听到便成了声音，进入眼帘便绘出形色，取得这些不会有人禁止，感受这些也不会有竭尽的忧虑。这是大自然恩赐的没有穷尽的宝藏，我和你可以共同享受。”
客人高兴地笑了，洗净酒杯重新斟酒。菜肴果品都已吃完，杯子盘子杂乱一片。大家互相枕着垫着睡在船上，不知不觉东方已经露出白色的曙光。', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf685914587d02f59d5b", "shortContent": "苏轼善处逆境，以理性和智慧来观照现实，常常能得出与众不同的结论，进入超妙的人生境界。元丰五年（1082）是苏轼贬官黄州（今湖北黄冈）团练副使的第四个年头，“乌台诗案”带给他的消极影响仍未散去，但政治上的苦闷期也是文学创作上的丰收期。这一年的秋天，苏轼游玩黄州城外的赤鼻矶，联想到三国时的赤壁之战，因此写下了《前赤壁赋》《后赤壁赋》和《念奴娇·赤壁怀古》。《前赤壁赋》依照时间顺序，将叙事、写景、议论、...", "authors": ["孔燕妮"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1fbc6e67846a921a151", "shortContent": "此赋作于北宋神宗元丰五年（1082）作者谪居黄州（今湖北黄冈）时，因同年另有《后赤壁赋》，故世人习称为《前赤壁赋》。\n关于这一次赤壁之游，苏轼在《与范子丰》函中曾有所记述：“黄州少西，山麓斗入江中，石室如丹，传云曹公败所———所谓‘赤壁’者；或曰非也。……今日李委秀才来相别，因以小舟载酒饮赤壁下。李善吹笛，酒酣作数弄，风起水涌，大鱼皆出，山上有栖鹘，亦惊起。坐念孟德、公瑾如昨日耳！”可知此赋确是记...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "645fb72a5e6bb82b8cafd5e3", "bookTitle": "苏轼诗文鉴赏辞典", "articleId": "64685d3e7da2f75ac7f71359", "shortContent": "此赋作于北宋神宗元丰五年（1082）作者谪居黄州（今湖北黄冈）时，因同年另有《后赤壁赋》，故世人习称为《前赤壁赋》。\n\n关于这一次赤壁之游，苏轼在《与范子丰》函中曾有所记述：“黄州少西，山麓斗入江中，石室如丹，传云曹公败所——所谓‘赤壁’者；或曰非也。……今日李委秀才来相别，因以小舟载酒饮赤壁下。李善吹笛，酒酣作数弄，风起水涌，大鱼皆出，山上有栖鹘，亦惊起。坐念孟德、公瑾如昨日耳！”可知此赋确是记...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "64717b6982772d4594259493", "shortContent": "此赋作于北宋神宗元丰五年(1082)作者谪居黄州（今湖北黄冈）时。凡是记游的诗文，首先当然要求写景叙事生动有味，更需要在写景叙事中注入作家浓郁的主观感情，才能神情飞动，诗趣盎然；倘若景与情交融之外，更能从物我之间即主客观的契合之间生发出哲理的意蕴，那便是上乘之作了。苏轼的许多杰作，大抵能达到这种最高境界。例如人们都熟悉的一首小诗《题西林壁》，全诗只有四句二十八字，就景、情、理三者兼备。头一句“横看...", "authors": ["何满子"], "pressName": "上海辞书出版社"}]', '宋·晁无咎《续〈离骚〉序》：《赤壁》前、后赋者，苏公之所作也。曹操气吞宇内，楼船浮江，以谓遂无吴矣。而周瑜少年，黄盖裨将，一炬以焚之。公滴黄冈，数游赤壁下，盖忘意于世矣。观江涛汹涌，慨然怀古，犹壮瑜事而赋之。
宋·俞文蔚《吹剑四录》：碑记文字铺叙易，形容难，扰之传神，面目易摹写，容止气象难描摹。……《赤壁赋》：「清风徐来，……水落石出。」此类如伸殊所谓费尽丹青，只这些儿画不成。
宋·唐鲁国《唐子西文录》：余作《南征赋》，或者称之，然仅与曹大家辈争衡耳。惟东坡《赤壁》二赋，一洗万古，欲仿佛其一语，毕世不可得也。
宋·张正民《珊瑚钩诗话》：《赤壁赋》卓绝近于雄风。
宋·苏仲滋《栾城遗言》：子瞻诸文皆有奇气。至《赤壁赋》，仿佛屈原宋玉之作，汉唐诸公皆莫及也。
宋·方时佐《读赤壁赋》：万舸浮江互荡磨，一番蛟鳄战盘涡。中天日月悲分影，对局英雄付逝波。形胜空传二赤壁，文章谁肯百东坡。荆州风景今何似，秋夜时闻窈窕歌。
宋·罗鹤林《鹤林玉露》：太史公《伯夷传》，苏东坡《赤壁赋》，文章绝唱也。其机轴略同《伯夷传》，以求仁得仁又何怨之语设问，谓夫子称其不怨，而《采薇》之诗，犹若未免怨何也？盖天道无亲，常与善人，而遍观古今操行不轨者多富乐。公正发愤者，毎遇祸，是以不免于怨也。虽然富贵何足求，节操为可尚，其重在此，其轻在彼，况君子疾没世而名不称，伯夷颜子得夫子而名益彰，则所得亦已多矣。又何怨之有？《赤壁赋》因客吹箫而有怨慕之声，以此漫问，谓举酒相属，凌万顷之茫，可谓至乐，而箫声乃若哀怨何也？盖此乃周郎破曹公之地，以曹公之雄豪亦终归于安在，况吾与子寄蜉蝣于天地，哀吾生之须臾，宜其托遗响而悲也。虽然自其变者而观之，虽天地曾不能一瞬，自其不变者而观之，则物与我皆无尽也。又何必羡长江而哀吾生哉！矧江风山月用之无尽，此天下之至乐。于是洗盏更酌，而向之感慨，风休冰释矣。东坡步骤太史公者也。
宋·谢叠山《文章规范》：此赋学《庄》、《骚》文法，无一句与《庄》、《骚》相似。非超然之才、绝伦之识不能为也。潇洒神奇，出尘绝俗，如乘云御风而立乎九霄之上，俯视六合，何物茫茫？非惟不挂之齿牙，亦不足入其灵台丹府也。
宋·周草窗《浩然斋雅谈》：《赤壁赋》谓：「自其变者而观之，则天地曾不能以一瞬；自其不变者而观之，则物与我皆无尽也。」此葢用《庄子》句法：「自其异者而眂之，肝胆楚越也；自其同者而眂之，万物皆一也。」又用《楞严经》意，佛告波斯匿王言：「汝今自伤发白面，皱其面，必定皱于童年，则汝今时观此恒河与昔童时观河之见，有童耄不？」王言：「不也。世尊佛言：汝面虽皱，而此见精性未甞皱。皱者为变，不皱非变，变者受生灭，不变者元无生灭。」东坡《赤壁赋》，多用《史记》语，如杯盘狼藉，归而谋诸妇，皆《滑稽传》；正襟危坐，《曰者传》；举网得鱼，《龟策传》；开户视之，不见其处，则如《神女赋》。所谓以文为戏者。
金·王滹南《滹南遗老集》：或疑《前赤壁赋》所用客字。予曰：「与『泛舟』及『举酒属』之者，众客也；其后『吹洞箫』而酬答者，一人耳。此固易见，复何疑哉！」
元·方虚谷《追和东坡先生亲笔陈季常见过三首》：前后赤壁赋，悲歌惨江风。江山元不改，在公神游中。
明·归震川《文章指南》：如陶渊明《归去来兮辞》，于举业虽不甚切，观其词义，潇洒夷旷，无一点风尘俗态，两晋文章，此其杰然者。苏子瞻《赤壁赋》之趣，脱自是篇。
明代茅坤：予尝谓东坡文章仙也，读此二赋。令人有遗世之想。
明·高瑞南《遵生八笺》：李太白诗「清风明月不用一钱买」，《赤壁赋》云：「惟江上之清风与山间之明月，耳得之而为声，目遇之而成色，取之无禁，用之不竭，此造物之无尽藏也。」东坡之意盖自太白诗句得来，夫风月不用钱买，而取之无禁，太白诗之所言信矣。然而能知清风明月为可乐者能有几人，清风明月，一岁之间亦无几日，人即能知此乐，或为俗事相夺、或为病苦所缠，欲乐之有不能者。有闲居无事，遇此清风明月不用钱买，又无人禁而不知此乐者，是自生障碍也。
明·郑之惠《苏长公合作》：东坡在儋耳与客论食品书，纸末云：「既饱以庐山康王谷廉泉，烹曾坑斗品，少焉，解衣仰卧，使人诵东坡先生前、后《赤壁赋》，亦足以一笑也。」观此有所谓曹大家辈诸赋尚得争衡，独此二赋，一洗万古，不能仿佛其一语，良然。骚赋祖于屈宋，穷工肆极，若长卿者，可为兼之。予云宏丽，盖于《高唐》；《长门》凄婉，不下《九章》；又有赋事赋物，如《芜城》。《赤壁》、《恨别》两赋，亦皆原本屈宋，第语稍浮露；若文通高华，子瞻飘洒，各自擅场。世之耳食者，闻宋无赋，诋两《赤壁》不值一钱，则屈三闾不应有《卜居》、《渔父》；且文何定体，即三闾又从何处得来？邵宝曰：「『风、月』二字是一篇张本。」
明·曹以宁《谰言长语》：古人之文老杜、二苏多不知道，叹老嗟卑，如《七歌》及《赤壁赋》，逝者如斯，而未尝往也等可见。
明·杨升菴《三苏文范》：钟惺曰：「《赤壁》二赋，皆赋之变也。此又变中之至理奇趣，故取此可以赅彼。」文征明曰：「言曹孟德气势皆已消灭无余，讥当时用事者。尝见墨迹寄傅钦之者云：『多事畏人，幸无轻出。』盖有所讳也。」
清·金圣叹《天下才子必读书》：游赤壁，受用现今元边风月，乃是此老一生本领，却因平平写不出来，故特借洞萧呜咽，忽然从曹公发议，然后接口一句喝倒。痛陈其胸前一片空阔了悟，妙甚！
清·孙寒巢《山晓阁选宋大家苏东坡全集》：因赤壁而思曹、周，亦是意中情景。此却从饮酒乐甚，说到正襟危坐，则因乐而悲。及说水月共适，则客喜而笑，又因悲而喜，一悲一喜，触绪纷来。写景机其工练，言情极其深至。江山不朽，此文应与俱寿。才如子瞻，眉山草木为枯，赤壁声色数倍矣。
清·吴楚材、吴调侯《古文观止》：欲写受用现前无边风月，欲借吹洞萧者发出一段悲感，然後痛陈其胸前一片空阔了悟。风月不死，先生不亡也。
清·张伯行《唐宋八大家文钞》：以文为赋，藏叶韵于不觉，此坡公工笔也。凭吊江山，恨人生之如寄；流连风月，喜造物之无私。一难一解，悠然旷然。
清·储同人《唐宋十大家全集录·东坡全集录》：行歌笑傲，愤世嫉邪。
清·储同人《唐宋八大家类选》：出入仙佛，赋一变矣。
清·林损斋《古文析义》：二《赤壁》俱是夜游。此篇十二易韵，以江风山月作骨，前面步步点出，一泛舟间，胜游已毕，坡翁忽借对境感慨之意，现前指点，发出许多大议论。然以江山无穷，音生有尽，尚论古人遗迹，欷歔凭吊。虽文人悲秋常调，但从吹箫和歌声中引入，则文境奇。其论曹公之诗、曹公之事，低回流连，两叠而出，则文致奇。盛言曹公英雄，较论我生微细，蜉蝣短景，对境易哀，则文势奇。迨至以水、月为喻，发出正论，则《南华》、《楞严》之妙理，可以包络天地，伭同造化，尤非文人梦想所能到也。
清·余诚《重订古文释义新编》：起首一段，就风月上写游赤壁情景，原自含共适之意。入后从渺渺抒怀，引出客箫，复从客箫借吊古意，发出物我皆无尽的大道理。说到这个地位，自然可以共适，而平日一肚皮不合时宜都消归乌有，哪复有人世兴衰成败在其意中？尤妙在江上数语，回应起首，始终总是一个意思。游览一小事耳，发出这等大道理。遂堪不朽。
清·浦山伧《古文眉诠》：二赋皆志游也。记序之体，出以韵语，故曰赋焉。其托物也不私，其感兴也不脱，纯乎化机。
清·爱新觉罗·弘历《唐宋文醇》：盖与造物者游而天机自畅，并无意于吊古，更何预今世事？尝书寄傅钦之而曰「多难畏事，幸毋轻出」者，畏宵不之捃摭无已，又或作蛰龙故事耳，乃文征明谓以曹孟德气势消灭无余，讥当时用事者，转以寄傅钦之之语为证，谓为实有所讥刺，可谓乌焉成马矣。
清·王均卿《评校音注古文辞类纂》：方苞曰：」所见无绝殊者，而文境邈不可攀，良由身闲地旷，胸无杂物，触处流露，斟酌饱满，不知其所以然而然，色惟他人不能摹效，即使子瞻更为之，亦不能如此调适而曹遂也。」吴汝纶曰：「此所谓文章天成偶然得之者。是知奇妙之作，通于造化，非人力也。」胸襟既高，识解亦文绝非常，不得如方氏之说谓所见无绝殊也。
清·李扶九原编、黄仁黼重订《古文笔法百篇》：以文体论，似赤壁记也，然记不用韵，而赋方用韵，此盖以记而为赋者也。故文带叙带赋，忽用韵，忽不用韵，古赋如《风赋》，如《色赋》，皆此类也。以文法讲，纯得吹箫一段生波，下乃发出如许妙理。会尝参神学佛，故号「东坡居士」；其笔墨之飘洒，成趣之活波，又似于仙，故世号「坡仙」。此文前乐、中悲、后乐，有似王右军《兰亭序》；其藉客发慨，不必实有其言，亦知昌黎之《进学解》，乃巧为譬忌也。《辑注评》：「风只作线索，悲、乐作转，抉引曹孟德为赤壁设色，服应点缀，抒轴亦工，篇中凡十二用韵。」
近·贺培新《文编》：东坡天仙化人，其于文章驱使惟心，无不如志，最为流俗所慕爱。学者纷纷摹拟，徒滋流弊，不知公文天马行空，绝去羁绊，固无轨辙之可寻也。即如此篇，初何尝为古今赋家体格所拘，而纵意所如，自抒怀抱，空旷高邀，夐不可攀，包复敢有学步者哉！', 'indent', 1546019276, '5c25f1731579a3005f3989bc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640909, '大学', NULL, 687, 4, 0, 2, '曾子', NULL, 36773, '583da971a22b9d006dd8b4c0', '周', 'wen', '文', 'https://baike.baidu.com/item/%E5%A4%A7%E5%AD%A6/5655065?fr=aladdin', '', '大学之道，在明明德，在亲民，在止于至善。知止而后有定，定而后能静，静而后能安，安而后能虑，虑而后能得。物有本末，事有终始。知所先后，则近道矣。
古之欲明明德于天下者，先治其国。欲治其国者，先齐其家。欲齐其家者，先修其身。欲修其身者，先正其心。欲正其心者，先诚其意。欲诚其意者，先致其知。致知在格物。物格而后知至，知至而后意诚，意诚而后心正，心正而后身修，身修而后家齐，家齐而后国治，国治而后天下平。
自天子以至于庶人，壹是皆以修身为本。其本乱而末治者否矣。其所厚者薄，而其所薄者厚，未之有也。此谓知本，此谓知之至也。
所谓诚其意者，毋自欺也。如恶恶臭，如好好色，此之谓自谦。故君子必慎其独也。小人闲居为不善，无所不至，见君子而后厌然，掩其不善而著其善。人之视己，如见其肺肝然，则何益矣。此谓诚于中，形于外，故君子必慎其独也。曾子曰：「十目所视，十手所指，其严乎！」富润屋，德润身，心广体胖，故君子必诚其意。
《诗》云：「瞻彼淇澳，菉竹猗猗。有斐君子，如切如磋，如琢如磨。瑟兮僴兮，赫兮喧兮。有斐君子，终不可喧兮。」「如切如磋」者，道学也。「如琢如磨」者，自修也。「瑟兮僴兮」者，恂傈也。「赫兮喧兮」者，威仪也。「有斐君子，终不可喧兮」者，道盛德至善，民之不能忘也。《诗》云：「于戏，前王不忘！」君子贤其贤而亲其亲，小人乐其乐而利其利，此以没世不忘也。《康诰》曰：「克明德。」《大甲》曰：「顾諟天之明命。」《帝典》曰：「克明峻德。」皆自明也。汤之《盘铭》曰：「苟日新，日日新，又日新。」《康诰》曰：「作新民。」《诗》曰：「周虽旧邦，其命维新。」是故君子无所不用其极。《诗》云：「邦畿千里，维民所止。」《诗》云：「缗蛮黄鸟，止于丘隅。」子曰：「于止，知其所止，可以人而不如鸟乎？」《诗》云：「穆穆文王，于缉熙敬止！」为人君，止于仁；为人臣，止于敬；为人子，止于孝；为人父，止于慈；与国人交，止于信。子曰：「听讼，吾犹人也。必也使无讼乎！」无情者不得尽其辞，大畏民志。此谓知本」
所谓修身在正其心者，身有所忿懥，则不得其正，有所恐惧，则不得其正，有所好乐，则不得其正，有所忧患，则不得其正。心不在焉，视而不见，听而不闻，食而不知其味。此谓修身在正其心。
所谓齐其家在修其身者，人之其所亲爱而辟焉，之其所贱恶而辟焉，之其所畏敬而辟焉，之其所哀矜而辟焉，之其所敖惰而辟焉。故好而知其恶，恶而知其美者，天下鲜矣。故谚有之曰：「人莫知其子之恶，莫知其苗之硕。」此谓身不修，不可以齐其家。
所谓治国必先齐其家者，其家不可教而能教人者，无之。故君子不出家而成教于国。孝者，所以事君也；弟者，所以事长也；慈者，所以使众也。《康诰》曰：「如保赤子。」心诚求之，虽不中，不远矣。未有学养子而后嫁者也。一家仁，一国兴仁；一家让，一国兴让；一人贪戾，一国作乱，其机如此。此谓一言偾事，一人定国。尧、舜率天下以仁，而民从之。桀、纣率天下以暴，而民从之。其所令反其所好，而民不从。是故君子有诸己而后求诸人，无诸己而后非诸人。所藏乎身不恕，而能喻诸人者，未之有也。故治国在齐其家。《诗》云：「桃之夭夭，其叶蓁蓁。之子于归，宜其家人。」宜其家人，而后可以教国人。《诗》云：「宜兄宜弟。」宜兄宜弟，而后可以教国人。《诗》云：「其仪不忒，正是四国。」其为父子兄弟足法，而后民法之也。此谓治国在齐其家。
所谓平天下在治其国者，上老老而民兴孝，上长长而民兴弟，上恤孤而民不倍，是以君子有絜矩之道也。所恶于上，毋以使下，所恶于下，毋以事上；所恶于前，毋以先后；所恶于后，毋以从前；所恶于右，毋以交于左；所恶于左，毋以交于右；此之谓絜矩之道。《诗》云：「乐只君子，民之父母。」民之所好好之，民之所恶恶之，此之谓民之父母。《诗》云：「节彼南山，维石岩岩。赫赫师尹，民具尔瞻。」有国者不可以不慎，辟，则为天下僇矣。《诗》云：「殷之未丧师，克配上帝。仪监于殷，峻命不易。」道得众则得国，失众则失国。
是故君子先慎乎德。有德此有人，有人此有土，有土此有财，有财此有用。德者本也，财者末也。外本内末，争民施夺。是故财聚则民散，财散则民聚。是故言悖而出者，亦悖而入；货悖而入者，亦悖而出。《康诰》曰：「惟命不于常。」道善则得之，不善则失之矣。《楚书》曰：「楚国无以为宝，惟善以为宝。」舅犯曰：「亡人无以为宝，仁亲以为宝。」
《秦誓》曰：「若有一介臣，断断兮无他技，其心休休焉，其如有容焉。人之有技，若己有之；人之彦圣，其心好之，不啻若自其口出。实能容之，以能保我子孙黎民，尚亦有利哉！人之有技，媢疾以恶之；人之彦圣，而违之俾不通：实不能容，以不能保我子孙黎民，亦曰殆哉！」唯仁人放流之，迸诸四夷，不与同中国。此谓唯仁人为能爱人，能恶人。见贤而不能举，举而不能先，命也；见不善而不能退，退而不能远，过也。好人之所恶，恶人之所好，是谓拂人之性，菑必逮夫身。是故君子有大道，必忠信以得之，骄泰以失之。
生财有大道，生之者众，食之者寡，为之者疾，用之者舒，则财恒足矣。仁者以财发身，不仁者以身发财。未有上好仁而下不好义者也，未有好义其事不终者也，未有府库财非其财者也。孟献子曰：「畜马乘，不察于鸡豚；伐冰之家，不畜牛羊；百乘之家，不畜聚敛之臣。与其有聚敛之臣，宁有盗臣。」此谓国不以利为利，以义为利也。长国家而务财用者，必自小人矣。彼为善之，小人之使为国家，灾害并至。虽有善者，亦无如之何矣！此谓国不以利为利，以义为利也。', '《大学》是一篇论述儒家修身治国平天下思想的散文，原是《小戴礼记》第四十二篇，相传为曾子所作，实为秦汉时儒家作品，是一部中国古代讨论教育理论的重要著作。经北宋程颢、程颐竭力尊崇，南宋朱晦菴又作《大学章句》，最终和《中庸》、《论语》、《孟子》并称「四书」。宋、元以后，《大学》成为学校官定的教科书和科举考试的必读书，对中国古代教育产生了极大的影响。', '大学之道：大学的宗旨，大学的最终目的。大学：在古代其含义有两种：「博学」之态；与「小学」相对的「大人之学」。古代儿童八岁上小学，主要学习「洒扫、应对、进退、礼乐射御书数」之类的文化课和基本的礼节。十五岁后可进入大学，开始学习伦理、政治、哲学等「穷理正心，修己治人」的学问。两种含义虽有明显的区别之处，但都有「博学」之意。道：本指道路，在这里指的是在学习政治、哲学时所掌握的规律和原则。
明明德：第一个「明」是动词，彰显、发扬之意。第二个「明」是形容词，含有高尚、光辉的意思。
亲民：一说是「新民」，使人弃旧因新，弃恶扬善。引导、教化人民之意。
止于：处在。
知止：明确目标所在。
静：心不妄动。
安：所处而安。
虑：处事精详。
得：得到成果。
齐其家：将自己家庭或家族的事务安排管理得井井有条，人与人之间的关系和谐，家业繁荣的意思。
修其身：锻造、修炼自己的品行和人格。
致其知：让自已得到知识和智慧。
格物：研究、认识世间万物。
庶人：普通百姓。
壹是皆以修身为本：壹是：全部都是之意。本：本源、根本。
末：与「本」相对，末节之意。
厚者薄：该厚待的却怠慢。
薄者厚：该怠慢的反倒厚待。
未之有也：宾语前置句，「未有之也」。是说还不曾有过这样的做法或是事情。
诚其意：指意念真诚。
毋：不要。
恶（wù）恶（è）臭：指的是讨厌恶臭的气味。
好（hào）好（hǎo）色：喜爱容貌出众的女子。
谦：心满意足的样子。
慎其独：在独处时要慎重。
闲居：单独在家中，独处。
厌然：遮遮掩掩、躲避之意。
掩：隐藏之意。著：彰显出来。
益：益处，好处。
中：内心。
外：指外表。
严：严峻，令人敬畏。
润屋：装饰住所。
润身：修炼自己。
心广体胖（pán）：心胸宽广，身体舒适。胖：舒适之意。
《诗》：此指《诗经·卫风·淇澳》。
淇：古代的水名，在今河南北部。澳（yù）：水曲之处。
菉（lù）：通「绿」。猗（yī）猗：美丽茂盛。
斐：文雅。
切、磋：对骨角进行切割磋光。
琢、磨：雕琢打磨玉石。这里用来比喻研究学问，修养品德。
瑟：庄严。
僴（xiàn）：威严。
赫兮喧兮：显赫的样子。
喧：又作「谖」，忘却之意。
道：说、谈论。
恂（xún）栗：惊恐、畏惧之意。
《诗》：此指《诗经·周颂·烈文》。
于戏（wūhū）：感叹词。
前王：指的是周文王和周武王。
贤其贤：尊重有贤德的人。亲其亲：亲近亲人。
乐其乐：安享他的快乐。
此以：所以。没世：过世之意。没，通「殁」。
《康诰》：《尚书·周书》中的一篇。五经之一的《尚书》是记录古代历史事件和人物的著作，全书分为《虞书》、《夏书》、《商书》、《周书》四大部分。
克：能够。
《大甲》：即《太甲》，是《尚书·商书》中的一篇。
顾：顾念之意。諟（shì）：此。明命：坦荡正义的禀性。
《帝典》：即《尧典》，是《尚书·虞书》中的一篇。
克明峻德：《尧典》原句为「克明俊德」。俊，与「峻」通，是崇高之意。
自明：自己去发扬光明的德性。
汤：历史上的商汤。盘铭：刻在金属器皿警示语言或是箴言。这里的金属器皿指的是商汤的洗澡盆。
苟：假如。新：本义指洗澡时除去身上污浊的东西，清洁身体，在这里是精神层面的弃旧革新。
作：激发。新民：使民新的意思，弃旧从新，弃恶从善。
《诗》：此指《诗经·大雅·文王》。
周：周朝。旧邦：旧有的国家。
其命：在这里指周朝所秉承的天命。维：助词，无意义。
是故：因此。极：完善、极致。
《诗》此指《诗经·商颂·玄鸟》。
畿（jī）：指都城和周边地区。
止：停止、栖息，在这里是居住之意。
《诗》此指《诗经·小雅·绵蛮》。
缗（mín）蛮：鸟叫声。
隅：角落之意。止：栖息。
于止：对于所居住的地方。
可以：即何以，为什么。
《诗》：此指《诗经·大雅·文玉》。
穆穆：雍容庄重的样子。
于（wū）：感叹词。缉：接着。熙：光明、光亮。止：助词，无意义。
听讼：审理诉讼案件。
犹人：和别人一样。
必：一定。
无情者：有违实情的人。辞：花言巧语。
民志：指民心。
修身：指的是修养良好的品德。
忿懥（zhì）：愤怒之意。
好乐：喜好，偏好。
之：「对于」之意。辟：亲近、偏爱之意。
恶：厌恶。
畏：害怕。
哀矜：同情怜悯之意。
敖惰：敖：骄教，傲慢。惰：懈怠。
好：喜欢。
硕：大。
不出家而成教于国：不出家门就能把教化推行到国家。
弟：通「悌」。指弟弟对哥哥要尊重服从。
慈：长辈对晚辈的爱。
如保赤子：出自《尚书·周书·康诰》。如：与「若」同，好像。指的是作为国君保护老白姓就要像保护自己的婴儿一样。
中：指的是达到预期的目标。
让：谦让，礼让。
贪戾：贪婪暴戾。
机：古代弓箭上的机关，这里指的是关键。
偾（fèn）：败坏之意。
尧舜：古代仁君的代表。率：带领、领导。
桀纣：桀：夏代的最后一位君主，残暴至极。纣：商代的最后一位君主。两人与尧舜相对，是古代暴君的代表。
诸：「之于」的合音词。指具有这些善德。
非：指责。
恕：恕道之意。孔子曾说：「己所不欲，勿施于人。」就是指自己不想做的，也不要让别人去做。这种推己及人的品德就是儒家所提倡的恕道。
喻：知晓、明白。
《诗》：此指《诗经·周南·桃夭》。
夭夭：鲜美的样子。
蓁蓁（zhēn）：浓密茂盛的样子。
之子：与「之女子于归」同，是说女子出嫁。
宜：适宜，和睦。
《诗》：此指《诗经·小雅·蓼萧》。
宜兄宜弟：是尊敬兄长、爱护兄弟之意。
《诗》：此指《诗经·曾风·鸬鸠》。
仪：仪容。忒（tè）：差错。
正：匡正，教正。四国：四方各国。
法：效法。
老老：第一个「老」是动词，指的是把老人当做老人看待的意思。老老，尊敬老人之意。
长长：敬重长辈之意。
恤：体恤怜爱之意。孤：指的是幼年丧父的孤儿。倍：通「背」，背离、背叛之意。
絜（xié）：度量之意。矩：画矩形所用的尺子，是规则、法度之意。絜矩之道：是儒家的伦理思想，指一言一行要有模范作用。
《诗》：此指《诗经·小雅·南山有台》。
乐：欢快、喜悦之意。只：助词，无意义。
好（hào）：喜好。
恶（wù）：厌恶。
《诗》：此指《诗经·小雅·节南山》。
节：通「截」，高耸的样子。
维：语气词，无意义。岩岩：险峻之意。
赫赫：显赫，显著的样子。师尹：指的是太师尹氏，太师是周代的三公之一。
具：通「俱」。尔：你。瞻：瞻仰、仰视之意。
僇（lù）：杀戮之意。
《诗》：此指《诗经·大雅·文王》。
丧师：丧失民心。
克：能够。配：与……相符。
仪：应该。监：警戒，鉴戒。
峻：大。不易：不易保有。
道：说。
此：才。
用：用度。
外本内末：指本末倒置。外：疏远，轻视。内：亲近，重视。
争民：民众互相争斗之意。施夺：抢夺财富。
悖（bèi）：逆、反。
货：财富。
常：恒常留驻一方。
道：说。
《楚书》是楚昭王时编写的史书。
楚国无为宝，惟善以为宝：出自《楚书》。王孙圉受楚昭王之命出使晋国。晋国赵简子问楚国珍宝美玉之事。王孙圉回应说楚国从来不把美玉当珍宝，而只是将那些和观射父一样的大臣看做珍宝。
舅犯：是晋文公重耳的舅舅，名狐偃，字子犯。
亡人无以为宝，仁亲以为宝：亡人：逃亡之人，特指重耳。子犯对重耳说这些话的历史情形是，晋僖公四年，晋献公因听信谗言，逼迫太子中生自缢而死。重耳避难逃亡在狄国时，晋献公逝世。秦穆公派人劝重耳回国执政。子犯得知此事，认为不能回去，随即对重耳说了这样的话。
《秦誓》：《尚书·周书》中的一篇。
断断：心地诚实之意。
休休：胸怀宽广之意。
有容：指能够包容人。
彦圣：德才兼备之意。彦：美好。圣：开明。
不啻（chì）：不只是。
实：是。
媢（mào）疾：嫉妒之意。
违：阻碍之意。俾（bǐ）：使得。
殆：危险。
放流：流放。
迸：驱逐之意。四夷：东南西北各方之夷。夷是古代东方的百姓。
中国：指的是国家的中心地区。
举：举荐。
先：优先。
命：是「慢」之误字。轻慢之意。
退：黜退。
过：过错。
好（hào）人之所恶（wù）：喜好众人所厌恶的。
拂：逆，违背。
菑（zāi）：同灾。逮：等到之意。夫：助词，无意义。
大道：常理正道。
骄泰：放肆骄奢。
生：生产。
食：享用。
疾：迅速。
舒：舒缓，缓慢。
发身：修炼身心。发：发起之意。
不终：不成功。
府库：存放国家贵重器物的地方。
孟献子：鲁国的大夫，姓仲孙，名蔑。
乘（shèng）：是四匹马拉的车，古代大夫级的待遇。
伐冰之家：办丧事时能够用冰来保存尸体的人家。卿大夫以上的大官能享受的待遇。
百乘之家：家中有一百辆车，是古代的大家族，通常是有封地的诸侯王。
聚敛之臣：聚敛民财的家臣。
盗臣：指盗窃公家财物的家臣。
长（zhǎng）国家：成为一国之长，指的是帝王。务：致力于。
彼：这里指国君。
为：治理。
无如之何：拿它没有办法。', '《大学》的宗旨，在于弘扬高尚的德行，在于关爱人民，在于达到最高境界的善。知道要达到「至善」的境界方能确定目标，确定目标后方能心地宁静，心地宁静方能安稳不乱，安稳不乱方能思虑周详，思虑周详方能达到「至善」。凡物都有根本有末节，凡事都有终端有始端，知道了它们的先后次序，就与《大学》的宗旨相差不远了。
在古代，意欲将高尚的德行弘扬于天下的人，则先要治理好自己的国家；意欲治理好自己国家的人，则先要调整好自己的家庭；意欲调整好自己家庭的人，则先要修养好自身的品德；意欲修养好自身品德的人，则先要端正自己的心意；意欲端正自己心意的人，则先要使自己的意念真诚；意欲使自己意念真诚的人，则先要获取知识；获取知识的途径则在于探究事理。探究事理后才能获得正确认识，认识正确后才能意念真诚，意念真诚后才能端正心意，心意端正后才能修养好品德，品德修养好后才能调整好家族，家族调整好后才能治理好国家，国家治理好后才能使天下太平。
从天子到普通百姓，都要把修养品德作为根本。人的根本败坏了，末节反倒能调理好，这是不可能的。正像我厚待他人，他人反而慢待我；我慢待他人，他人反而厚待我这样的事情，还未曾有过。这就叫知道了根本，这就是认知的最高境界。
所谓意念真诚，就是说不要自己欺骗自己。就像厌恶难闻的气味，喜爱好看的女子，这就是求得自己的心满意足。所以君子在独处时一定要慎重。小人在家闲居时什么坏事都可以做出来。当他们看到君子后，才会遮掩躲闪，藏匿他们的不良行为，表面上装作善良恭顺。别人看到你，就像能见到你的五脏六腑那样透彻，装模作样会有什么好处呢？这就是所说的心里是什么样的，会显露在外表上。因此，君子在独处的时候就好比十双眼睛盯着自己，十个手指指着自己这样严肃慎重。曾子说：「一个人被众人注视，被众人指责，这是很可怕的啊！」富能使房屋华丽，德能使人品德高尚，心胸宽广能体态安适，所以，君子一定要意念真诚。
《诗经》上说：「看那弯弯的淇水岸边，绿竹苍郁。那文质彬彬的君子，像切磋骨器、琢磨玉器那样治学修身。他庄重威严，光明显耀。那文质彬彬的君子啊，令人难以忘记！」所谓「像切磋骨器」，是说治学之道；所谓「像琢磨玉器」，是说自身的品德修养；所谓「庄重威严」，是说君子谦逊谨慎，所谓「光明显耀」，是说君子仪表的威严；「那文质彬彬的君子啊，令人难以忘记」，是说君子的品德完美，达到了最高境界的善，百姓自然不会忘记他。《诗经》上说：「哎呀，先前的贤王不会被人忘记。」后世君子，尊前代贤王之所尊，亲前代贤王之所亲，后代百姓因先前贤王而享安乐，获收益。这样前代贤王虽过世而不会被人遗忘。《尚书·周书》中的《康诰》篇上说：「能够弘扬美德。」《尚书·商书》中的《太甲》篇中说：「思念上天的高尚品德。」《尚书·虞书》中《帝典》篇中说：「能够弘扬伟大的德行。」这些都是说要自己发扬美德。商汤的《盘铭》上说：「如果一日洗刷干净了，就应该天天洗净，不间断。」《康诰》篇上说：「劝勉人们自新。」《诗经》上说：「周朝虽是旧国，但文王承受天命是新的。」因此，君子处处都要追求至善的境界。《诗经》上说：「京城方圆千里，都为百姓居住。」《诗经》上说：「啁啾鸣叫的黄莺，栖息在多树的山丘上。」孔子说：「啊呀，黄莺都知道自己的栖息之处，难道人反而不如鸟吗？」《诗经》上说：「仪态端庄美好的文王啊，他德行高尚，使人无不仰慕。」身为国君，当努力施仁政；身为下臣，当尊敬君主；身为人之子，当孝顺父母；身为人之父，当慈爱为怀；与国人交往，应当诚实，有信用。孔子说：「审断争讼，我的能力与他人的一般无二，但我力争使争讼根本就不发生。」违背实情的人，不能尽狡辩之能事，使民心敬畏。这叫做知道什么是根本。
如要修养好品德，则先要端正心意。心中愤愤不平，则得不到端正；心中恐惧不安，则得不到端正；心里有偏好，则得不到端正；心里有忧患，则得不到端正。一旦心不在焉，就是看了，却什么也看不到；听了，却什么也听不到；吃了，却辨别不出味道。所以说，修养品德关键在端正心意。
如要调整好家族，则先要修养好品德，为什么呢？因为人往往对他所亲近喜爱的人有偏见，对他所轻视讨厌的人有偏见，对他所畏惧恭敬的人有偏见，对他所怜惜同情的人有偏见，对他所傲视怠慢的人有偏见。所以喜爱一个人但又认识到他的缺点，不喜欢一个人但又认识到他优点的人，也少见。因此有一则谚语说：「人看不到自己孩子的过错，人察觉不到自己的庄稼好。」这就是不修养好品德，就调整不好家族的道理。
要治理好国家，必须先要调整好自己的家族，因为不能教育好自己家族的人反而能教育好一国之民，这是从来不会有的事情。所以，君子不出家门而能施教于国民。孝顺，是侍奉君主的原则，尊兄，是侍奉长官的原则，仁慈，是控制民众的原则。《康诰》中说：「像爱护婴儿那样。」诚心诚意去爱护，即便不合乎婴儿的心意，也相差不远。不曾有过先学养育孩子再出嫁的人呀！一家仁爱相亲，一国就会仁爱成风；一家谦让相敬，一国就会谦让成风；一人贪婪暴戾，一国就会大乱——它们的相互关系就是这样。这就叫做一句话可以败坏大事，一个人可以决定国家。尧、舜用仁政统治天下，百姓就跟从他们实施仁爱。桀、纣用暴政统治天下，百姓就跟从他们残暴不仁。他们命令大家做的，与他自己所喜爱的凶暴相反，因此百姓不服从。因此，君子要求自己具有品德后再要求他人，自己先不做坏事，然后再要求他人不做。自己藏有不合「己所不欲，勿施于人」这一恕道的行为，却能使他人明白恕道，这是不会有的事情。因此，国家的治理，在于先调整好家族。《诗经》上说：「桃花绚烂，枝繁叶茂。姑娘出嫁，合家欢快。」只有合家相亲和睦后，才能够调教一国之民。《诗经》上说：「尊兄爱弟。」兄弟相处和睦后，才可以调教一国的人民。《诗经》上说：「他的仪容没有差错，成为四方之国的准则。」能使父亲、儿子、兄长、弟弟各谋其位，百姓才能效法。这就叫做治理好国家首先要调整好家族。
要平定天下，先要治理好自己的国家。因为居上位的人敬重老人，百姓就会敬重老人；居上位的人敬重兄长，百姓就会敬重兄长，居上位的人怜爱孤小，百姓就不会不讲信义。所以，君子的言行具有模范作用。厌恶上级的所作所为，就不要用同样的做法对待下级；厌恶下级的所作所为，就不要用同样的做法对待上级；厌恶在我之前的人的所作所为，就不要用同样的做法对待在我之后的人，厌恶在我之后的人的所作所为，就不要用同样的做法对待在我之前的人，厌恶在我右边的人的所作所为，就不要用同样的方法与我左侧的人交往；厌恶在我左边的人的所作所为，就不要用同样的方法与我右侧的人交往。这就是所说的模范作用。《诗经》上说：「快乐啊国君，你是百姓的父母。」百姓喜爱的他就喜爱，百姓厌恶的他就厌恶，这就是所说的百姓的父母。《诗经》上说：「高高的南山啊，重峦叠嶂。光耀显赫的尹太师啊，众人都把你仰望。」统治国家的人不能不谨慎，出了差错就会被天下百姓杀掉。《诗经》上说：「殷朝没有丧失民众时，能够与上天的意旨相配合。应以殷朝的覆亡为鉴，天命得来不易啊。」这就是说得到民众的拥护，就会得到国家；失去民众的拥护，就会失去国家。
所以，君子应该谨慎地修养德行。具备了德行才能获得民众，有了民众才会有国土，有了国土才会有财富，有了财富才能享用。德行为根本，财富为末端。如若本末倒置，民众就会互相争斗、抢夺。因此，财富聚集在国君手中，就可以使百姓离散，财富疏散给百姓，百姓就会聚在国君身边。所以你用不合情理的言语说别人，别人也会用不合情理的言语说你，用不合情理的方法获取的财富，也会被人用不合情理的方法夺走。《康诰》上说：「天命不是始终如一的。」德行好的就会得天命，德行不好就会失掉天命。《楚书》上说：「楚国没有什么可以当做珍宝的，只是把德行当做珍宝。」舅犯说：「流亡的人没有什么可以当做珍宝的，只是把挚爱亲人当做珍宝。」
《秦誓》上说：「如果有这样一个大臣，他虽没有什么才能，但心地诚实宽大，能够容纳他人。别人有才能，如同他自己有一样；别人德才兼备，他诚心诚意喜欢，不只是口头上说说而已。能够留用这人，便能够保护我的子孙百姓。这对百姓是多么有利啊。如果别人有才能，就嫉妒厌恶；别人德才兼备，就阻拦他施展才干。不能留用这样的人，他不能保护我的子孙百姓，这种人也实在是危险啊。」只有仁德的人能把这种嫉妒贤人的人流放，驱逐到边远地区，使他们不能留在国家的中心地区。这叫做只有仁德的人能够爱人，能够恨人。看到贤人而不举荐，举荐了但不尽快使用，这是怠慢。看到不好的人却不能摈弃，摈弃了却不能放逐到远方，这是过错。喜欢人所厌恶的，厌恶人所喜欢的，这是违背了人性，灾害必然会降临到他的身上。因此，君子所有的高尚德行，一定要忠诚老实才能够获得，骄纵放肆便会失去。
发财致富有这样一条原则：生产财富的人要多，消耗财富的人要少；干得要快，用得要慢，这样就可以永远保持富足了。有德行的人会舍财修身，没有德行的人会舍身求财。没有居上位的人喜爱仁慈而下位的人不喜爱忠义的；没有喜爱忠义而完不成自己事业的；没有国库里的财富最终不归属于国君的。孟献子说：「拥有一车四马的人，不应计较一鸡一猪的财物；卿大夫家不饲养牛羊；拥有马车百辆的人家，不豢养收敛财富的家臣。与其有聚敛民财的家臣，还不如有盗贼式的家臣。」这是说，国家不应把财物当做利益，而应把仁义作为利益。掌管国家大事的人只致力于财富的聚敛，这一定是来自小人的主张。假如认为这种做法是好的，小人被用来为国家服务，那么灾害就会一起来到，纵使有贤臣，也无济于事啊！这就是说国家不要把财利当做利益，而应把仁义当做利益。', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8c03048e64fbda97a9", "shortContent": "本篇写新罗国第一贵族金哥祖上的传说。金哥远祖旁㐌兄弟分居，兄旁㐌贫穷，又受弟欺，后竟因贫致富；其弟却因贪心受罚，惭恚而死。旁㐌兄弟的不同结局，其中自有鬼神差使，这就应了中国的一句老话：人间善恶，鬼神可鉴。这个故事虽在新罗国流传，并带有强烈的东方色彩，但故事的“母题”（即善人因贫苦得神助，偶获一宝物，所欲辄有；贪心人亦欲获其宝，却受祸累），无论东西方都有永恒的传说。故事中的“金锥子”，也可以是宝葫芦...", "authors": ["李", "晓"], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文(高中)", "articleId": "6471e14082772d4594278c30", "shortContent": "《大学》原是儒家经典《礼记》中的一篇，相传为孔门弟子曾参所作。到了宋代，程朱理学兴起，将其和《中庸》摘出，与《论语》《孟子》合编为“四书”。“大学”者，意味着成大事、立大业的博大之学。因而被列为“四书之首”。是宋代以后学子们在学业之路上要诵读的首要篇章。\n《大学》篇从三个方面提出了人生和事业的终极目标：“明明德”“亲民”“止于至善”，通过修身上的不断“日新”，在美德上达到最完善的境界，并从而拥有治...", "authors": ["孙逊"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b15dee49f46528a417fb7", "shortContent": "《大学》原为《礼记》中的一篇，传为曾子所作，一说为秦汉之际佚名儒家的作品。其独立成书要比《中庸》晚得多。《汉书·艺文志》录有《中庸说》二篇，而《大学》则迟至北宋司马光才单独列卷。\n\n确认《大学》在儒学史、经学史发展中的特殊作用，当始于唐代的韩愈、李翱。韩、李两人把《大学》（连同《中庸》）看得和《论语》、《孟子》同样重要。北宋程氏兄弟承韩、李之意，详述二书之意涵，强调《大学》系“孔氏之遗书，而初学入...", "authors": ["施炎平", "魏薪"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b184b66a763596afdc8fa", "shortContent": " 这几章是逐句解释《大学》经文的上半部，引用了许多以前的经典著作，也作了自己的发挥，其中提出的一些概念和命题，阐发的一些思想对于后世哲学理论的发展产生了重大的影响。作者在诠释经文中突出了《大学》这一理念：求圣人之道的关键是增强完善自我的自觉性，它从以下几方面阐发了这一理念的涵义。\n\n首先，自我的完善是“自明”。第一章引证的《尚书》中三段语录证明《大学》首句“明明德”在古圣人之书中都有出处，然后总结...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b1b4fb6a81d0c538c19de", "shortContent": "儒家政治哲学的基本观念是治理国家的根本原则同治理家庭和对待他人的准则相一致，由此这几章着重阐述了两个观点：\n\n第一，“治国必先齐其家”。在儒家看来，不能教育好家人的那些人是不可能治理好国家的。其理由是在家中都不能实行仁义道德，在国家政治生活中也就不会讲仁义道德。因此，要首先在治家的过程中培育治国所需要的那些道德品质和才干。所以作者说：“故君子不出家而成教于国。”治国必先齐家的另外一个理由是，统治者...", "authors": ["施炎平", "魏薪"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b5006b6a81d0c538d2808", "shortContent": "《文言》曰:“元”者，善之长也；“亨”者，嘉之会也；“利”者，义之和也；“贞”者，事之干也。君子体仁足以长人，嘉会足以合礼，利物足以和义，贞固足以干事。君子行此四德者，故曰：“乾：元、亨、利、贞。”\n初九曰：“潜龙勿用”，何谓也？子曰：“龙，德而隐者也。不易乎世，不成乎名。遯世无闷，不见是而无闷。乐则行之，忧则违之，确乎其不可拔，‘潜龙’也。”\n九二曰：“见龙在田，利见大人”，何谓也？子曰：“龙德...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b511ea5f1e74f95e9acb1", "shortContent": "天尊地卑，乾坤定矣。卑高以陈，贵贱位矣。动静有常，刚柔断矣。方以类聚，物以群分，吉凶生矣。在天成象，在地成形，变化见矣。\n是故刚柔相摩，八卦相荡，鼓之以雷霆，润之以风雨，日月运行，一寒一暑。乾道成男，坤道成女。乾知太始，坤作成物。乾以易知，坤以简能。易则易知，简则易从。易知则有亲，易从则有功。有亲则可久，有功则可大。可久则贤人之德，可大则贤人之业。易简而天下之理得矣，天下之理得而成位乎其中矣。……...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b51907f27182da3ee45cd", "shortContent": "《系辞传》分上、下两篇，列《易传》十翼的第六、七篇，系对《易经》卦象和文辞之义理、意蕴的解释和发挥。相传作者为孔子，似根据不足。后世治易者有许多猜测，都难有确论。有学者根据战国后期哲学家已引用《系辞传》文字的事实，提出它是战国中期的作品。也有学者认为《系辞传》成书当在战国末诸子思想出现合流以后，其作者兼有儒道思想的色彩。\n\n宋代大儒张载曾指出：“观《易》必由系辞（传）。”意谓从《系辞传》入手，方是...", "authors": ["施炎平"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b52c5a5f1e74f95e9b367", "shortContent": "《书经·尧典》记尧事，这一部分可分四段。首段，赞颂尧之德行事功。次段，记叙任命羲和观天象、定历法之事。第三段，讲述尧询问群臣、举用人才的过程。末段议定天子——部落联盟领袖候选人。所记反映古代的民主制度以及定历治水等国之大事。\n\n《尧典》的成书年代，有殷末周初至汉武帝时的不同说法。对此，王世舜先生在《尚书今译》中说：“我们可以把这个时期当作《尧典》的流传时期。在流传过程中，由于后人的不断润色或附益，...", "authors": ["贺圣迪"], "pressName": "上海辞书出版社"}]', '程子：「大学，孔氏之遗书，而初学入德之门也。」于今可见古人为学次第者，独赖此篇之存，而论、孟次之。学者必由是而学焉，则庶乎其不差矣。
郑玄《三礼目录》：名为《大学》者，以其记博学可以为政也。
孔颖达《礼记正义》：此《大学》之篇，论学成之事，能治其国，章明其德于天下。
孙中山：中国政治哲学谓其最有系统之学，无论外国任何政治哲学家都未见过，都未说出，为中国独有之宝贝。', 'indent', 1546021076, '5c25f84a808ca4565cef0beb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640910, '八至', NULL, 358, 20, 1, 0, '李冶', NULL, 10309, '57b9a157a633bd005d2dd486', '唐', 'shi', '诗', 'https://baike.baidu.com/item/八至/144642', '', '至近至远东西，至深至浅清溪。
至高至明日月，至亲至疏夫妻。', '《八至》是唐代女诗人李冶创作的六言诗。此诗首字“至”字在诗中反复出现八次，故题名“八至”。从内容上说，全诗四句，说的都是浅显而至真的道理，具有深刻的辩证法，富有哲理意味。从结构上说，作者设置了层云叠嶂，前三句只是个过场，主要是为了引出最后一句“至亲至疏夫妻”，专在针砭世情，极为冷峻。', '至：最。八至：此以诗中有八个“至”字为题。
东西：指东、西两个方向。
疏：生疏，关系远，不亲近。', '最近也是最远的是东与西，最深也是最浅的是清溪。
最高也是最明的是日和月，最亲也是最疏的是夫妻。', '[{"bookId": "60fc32b023353c0ba53dd945", "bookTitle": "历代女性诗词鉴赏辞典", "articleId": "610ec7870f8fda5565060772", "shortContent": "这是一篇极其简单，又极其深刻的诗。唐代流传很广，敦煌也有写本。法藏敦煌文书题注：“此一篇天下□子不能过。”缺一个字，可能是男子，或者是才子，总是感叹这样好的诗，出自一位妇人之口，男子又何能过此。\n古人有四至的说法，指一个国家或州县领土，从东西南北四边来说，达到最远的地方。这首诗的八至，与此毫无关系，只是因为诗里出现八个“至”字而已，因此称为《八至》。\n《八至》讲了四层意思。第一是从方向来说的，东西...", "authors": ["陈尚君"], "pressName": "上海辞书出版社"}]', '明人钟惺《名媛诗归》：字字至理，第四句尤是至情。
清人黄周星《唐诗快》：六字出自男子之口，则为薄幸无情；出自妇人之口，则为防微虑患。大抵从老成历练中来，可为惕然戒惧（末句下）。', 'center', 1546021635, '5c25fab067f356005f40207c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640911, '送别', NULL, 853, 39, 2, 0, '李叔同', NULL, 10312, '57b8fc5ea633bd00665d2bb0', '当代', 'qu', '曲', 'https://baike.baidu.com/item/%E9%80%81%E5%88%AB/1287670?fr=aladdin', '', '长亭外，古道边，芳草碧连天。晚风拂柳笛声残，夕阳山外山。
天之涯，地之角，知交半零落。一壶浊酒尽余欢，今宵别梦寒。
长亭外，古道边，芳草碧连天。问君此去几时还，来时莫徘徊。
天之涯，地之角，知交半零落。人生难得是欢聚，唯有别离多。', '《送别》，曲调取自约翰·P·奥德威作曲的美国歌曲《梦见家和母亲》。《梦见家和母亲》是首“艺人歌曲”，这种歌曲19世纪后期盛行于美国，由涂黑了脸扮演黑人的白人演员领唱，音乐也仿照黑人歌曲的格调创作而成。奥德威是“奥德威艺人团”的领导人，曾写过不少艺人歌曲。李叔同留日期间，日本歌词作家犬童球溪采用《梦见家和母亲》的旋律填写了一首名为《旅愁》的歌词。而李叔同作于1915年的《送别》，则取调于犬童球溪的《旅愁》。如今《旅愁》在日本传唱不衰，而《送别》在中国则已成骊歌中的不二经典。沈心工也曾根据《梦见家和母亲》写过一首《昨夜梦》，但最终没有抵得过李叔同《送别》的光芒。', '', '', NULL, '', 'indent', 1546022672, '5c25febc9f54540070d81fa0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641129, '共内人夜坐守岁', NULL, 17, 1, 1, 1, '徐君倩', NULL, 37006, '5c5790e6a91c9300545e89f5', '南北朝', 'shi', '诗', '', '', '欢多情未极，赏至莫停杯。
酒中喜桃子，粽里觅杨梅。
帘开风入帐，烛尽炭成灰。
勿疑鬓钗重，为待晓光催。', '', '“欢多”句：除夕之夜，家人共坐，欢乐多多但尚未尽兴，故酒儿一杯又一杯。
“酒中”句：可能是用桃子泡的酒。
“烛尽”句：指天已经快接近拂晓。
“勿疑”句：不要疑惑为什么夜深还打扮得整整齐齐，这是为了等待清晨的到来（以拜年）。此处特点点出“鬓钗重”已示庄重。', '', NULL, '', 'center', 1549271525, '5c57916117b54d00576f21cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641687, '寒食江州满塘驿', NULL, 55, 209, 0, 2, '宋之问', NULL, 10130, '57b9a06a2e958a00693191e7', '唐', 'shi', '诗', 'https://baike.baidu.com/item/%E5%AF%92%E9%A3%9F%E6%B1%9F%E5%B7%9E%E6%BB%A1%E5%A1%98%E9%A9%BF/9511057?fr=aladdin', '', '去年上巳洛桥边，今年寒食庐山曲。
遥怜巩树花应满，复见吴洲草新绿。
吴洲春草兰杜芳，感物思归怀故乡。
驿骑明朝发何处？猿声今夜断君肠。', '', '', '', NULL, '', 'center', 1554214811, '5ca2ff19a91c9300724a5527', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642127, '幽梦影 · 卷一 · 九十六', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '何谓善人？无损于世者，则谓之善人。何谓恶人？有害于世者，则谓之恶人。', '', '', '', NULL, '', 'indent', 1556102218, '5cbfcbc7a673f500684c91eb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640933, '临池管见', NULL, 7, 1, 1, 0, '周星莲', NULL, 36994, '5c2e3c15fb4ffe005fe7c452', '清', 'wen', '文', '', '士先器识而后文艺，艺末也。礼、乐、射、御、书、数皆艺，而书居其末，由书而言，探制作之精，辨形声之正，于以穷苞，苻匡伪谬，上窥古圣贤之用心，志道者犹或少之。至舍意义而讲字画，遗宗旨而究标格，抑又末已。余志识浅陋，艰于问学，顾雅爱古人法书，见辄临摹。临摹之久，每苦形似，既而思得其意，乃遍览诸家碑帖，参观互证，始规其立法，因玩其取势，进勘其用笔，继悟其行神，夫而后觉。古人作书之意，往往超乎笔画行墨之外，而求其意者不可泥笔画行墨之迹，而仍不能越乎笔画行墨之中。苟非会而通之，神而明之，其不为刻舟求剑、买椟还珠者，盖亦鲜矣。余从事既久，间有心得，更于前人所论稍有发明，得如干则，冗杂无次，雅不足观。有以余为知言者，谋付剞劂。余固辞不获，缘自叙其取业之小，与嗜好之偏，而名之曰临池管见。噫，锺、王而降，以书名无家者代不数人，一艺之末成名者之不多覯如此！余于书未尝有得，而积数十年之力，仅能粗识其梗概，则进乎艺而言器识，更由是而上企。夫文章性道之精，不诚戛戛乎，其难之哉！世之易视，一切徒竞时俗，无足重轻之名，而不求合于古人者，亦可以废然返矣。时同治七年岁次戊辰夏六月，星莲自序。', '上世结绳而治，自伏羲画八卦，而文字兴焉。故前人作字，谓之字画，画分也，界限也。尔雅释地：涂出其右而还之，画邱。注言：为道所规画。释名：道出其右曰画邱，人尚右，凡有指画，皆尚右。故用右手画字。或篆，或隶，或楷，或行，或草，皆当不忘画字之义；为横、为竖、为波、为磔、为钩、为，当永守画字之法。盖画则笔无不直，笔无不圆，而字之千变万化，穷工极巧，从此出焉。乃后人不曰画字，而曰写字。写有二义。说文：“写，置物也。”韵书：写，输也。置者，置物之形；输者，输我之心。两义并不相悖，所以字为心画。若仅能置物之形，而不能输我之心，则画字、写字之义，两失之矣。无怪书道不成也。
字画本自同工，字贵写，画亦贵写，以书法透入于画，而画无不妙；以画法参入于书，而书无不神。故曰：善书者必善画。善画者亦必善书。自来书画兼擅者，有若米襄阳，有若倪云林，有若赵松雪，有若沈石田，有若文衡山，有若董思白。其书其画，类能运用一心，贯串道理，书中有画，画中有书，非若后人之拘形迹以求书，守格辙以求画也。米元章谓：东坡为画字。自谓刷字。此不过前人等而上之，精益求精之语，非谓不能写字，而竟同剔刷成字，描画成字也。自桧以下无讥。后之作书者欲求苏、米之刷字、画字，不可得矣。
书法在用笔，用笔贵用锋。用锋之说吾闻之矣，或曰正锋，或曰中锋，或曰藏锋，或曰出锋，或曰侧锋，或曰扁锋。知书者有得于心，言之了了，知而不知者各执一见，亦复言之津津，究竟聚讼纷纭，指归莫定，所以然者，因前人指示后学要言不烦，未尝倾筐倒箧而出之。后人摹仿前贤，一知半解，未能穷追极究而思之也。余尝辨之，试详言之：所谓中锋者，自然要先正其笔。柳公权曰：心正则笔正，笔正则锋易于正。中锋即是正锋，自不必说。而余则偏有说焉，笔管以竹为之，本是直而不曲，其性刚，欲使之正，则竟正。笔头以毫为之，本是易起易倒，其性柔，欲使之正，却难保其不偃。倘无法以驱策之，则笔管坚而笔头已卧，可谓之中锋乎？又或极力把持，收其锋于笔尖之内，贴毫根于纸素之上，如以箸头画字一般，是笔则正矣、中矣，然锋已无矣，尚得谓之锋乎？或曰：此藏锋法也。试问所谓藏锋者，藏锋于笔头之内乎？抑藏锋于字画之内乎？必有爽然失、恍然悟者。第藏锋画内之说，人亦知之。知之而谓惟藏锋乃是中锋，中锋无不藏锋，则又有未尽然也。盖藏锋、中锋之法，如匠人钻物，然下手之始四面展动，乃可入木三分。既定之后，则钻已深入，然后持之以正。字法亦然。能中锋自能藏锋，如锥画沙，如印印泥，正谓此也，然笔锋所到收处、结处、掣笔映带处，亦正有出锋者。字锋出，笔锋亦出。笔锋虽出，而仍是笔尖之锋，则藏锋、出锋皆谓之中锋，不得专以藏锋为中锋也。至侧锋之法，则以侧势取其利导，古人间亦有之。若俗笔笔正锋，则有意于正势，必至无锋而后止。欲笔笔侧笔，则有意于侧势，必至扁锋而后止。琴瑟专一，谁能听之？其理一也。画家皴石之法，三面皆锋，须以侧锋为之。笔锋出，则石锋乃出。若竟横卧其笔，则一片模糊，不成其为石矣。总之，作字之法，先使腕灵笔活，凌空取势，沈著痛快，淋漓酣畅，纯任自然，不可思议，能将此笔正用、侧用、顺用、重用、轻用、虚用、实用、擒得定，纵得出，遒得紧，拓得开，浑身都是解数，全仗笔尖毫末锋芒指使，乃为合拍。钝根人胶柱鼓瑟，刻舟求剑，以团笔为中锋，以扁笔为侧锋，犹斤斤曰：若者中锋，若者偏锋，若者是，若者不是。纯是梦呓！故知此事虽藉人功，亦关天分，道中、道外，自有定数，一艺之细，尚索解人而不得。噫，难矣！ 用墨之法，浓欲其活，淡欲其华。活与华非墨宽不可，古砚微凹聚墨多，可想见古人意也。濡染大笔何淋漓，淋漓二字，正有讲究。濡染亦自有法。作书时须通开其笔，点入砚池，如篙之点水，使墨从笔尖入，则笔酣而墨饱，挥洒之下，使墨从笔尖出，则墨浥而笔凝。杜诗云：元气淋漓障犹湿。古人字画流传久远之后，如初脱手光景，精气神采不可磨灭。不善用墨者浓则易枯，淡则近薄，不数年间已淹淹无生气矣。不知用笔，安知用墨？此事难为俗工道也。
凡作书不可信笔，董思翁尝言之。盖以信笔，则中无主宰，波画易偃故也。吾谓信笔固不可太矜意，亦不可意为。笔蒙则意阑，笔为意拘，则笔死。要使我顺笔性，笔随我势，两相得，则两相融。而字之妙处，从此出矣。
字有一定步武、一定绳尺，不必我去造作。右军书因物付物，纯任自然，到得自然之极，自能变化从心，涵盖万有，宜其俎豆千秋也。
取法乎上，仅得乎中，人人言之。然天下最上的境界，人人要到，却非人人所能到，看天分做去。天分能到，则竟到矣。天分不能到，到得那将上的地步，偏拦住了，不使你上去。此即学问止境也。但天分虽有止境，而学者用功断不能自画，自然要造到上层为是。惟所造之境，须循序渐进，如登梯然，得一步、进一步。画曰：若升高必自下。言不容躐等也。今之讲字学者，初学执笔，便高谈晋、唐，满口羲、献；稍得形模，即欲追踪汉、魏，不但苏、黄、米、蔡不在意中，即欧、虞、褚、薛以上，溯羲、献犹以为不足，真可谓探本穷源，识高于顶者矣！及至写出字来，亦只平平无奇。噫，何弗思之甚也！余亦曾犯此病，初学时取欧书以定间架，久之字成印板，因爱褚书跌宕，乃学褚书；久之又患过于流走，此皆自己习气与欧、褚无干，如是者亦有年。嗣后东涂西抹，率意酬应，喜作行草，乃取怀仁所集圣教及兴福寺断碑、孙过庭书谱学之，对帖时少，挥洒时多，总觉依稀仿佛无有是处。乃阅近世石刻墨迹，颇有入处；再阅同时书家真迹，反觉易于揣摩，而尤难于学步，乃叹自己学问不但远不及古人，且远不及今人。于是将今人笔墨逐一研究，时而进观董、赵诸公书，更长一见识焉。又进而观宋人碑帖，又得其解数焉。又进而摹欧、虞、褚、薛、颜、柳、徐、李诸家书，已略得其蹊径焉，再上而求右军、大令诸法；已稍能寻其端倪焉。至此，乃恍然于前此之取法乎上者，真躐等而进也。近又见得颜鲁公书最好，以其天趣横生、脚踏实地、继往开来，惟此为最。昔人云：诗至子美，书至鲁公，足叹观止。此言不余欺也！余书无所得，惟屡疑屡悟，或出或入，不敢谓三折肱于此，而于书中甘苦尝之久矣，因书之以为知书者告。
字学以用敬为第一义，凡遇笔砚辄起矜庄，则精神自然振作，落笔便有主宰，何患书道不成！泛泛涂抹，无有是处。
作字须提得笔起，稍知书法者皆知之。然往往手欲提而转折顿挫辄自偃者，无擒纵故也。擒纵二字是书家要诀，有擒纵方有节制，有生杀用笔乃醒，醒则骨节通灵，自无僵卧纸上之病。否则寻行数墨，暗中索摸，虽略得其波磔往来之迹，不过优孟衣冠，登场傀儡，何足语斯道耶？
余自幼观唐、宋诸名家石刻，以为唐书如玉，宋书如水晶，心目中所见如此，未尝申明其所以然也。后读朱子语类云：孔子之学如玉，孟子之学如水晶，乃拍案惊喜，以为比拟切当。见得天地间人也、物也、学问也、技艺也，皆各分浑与露之两途，而心目中所见，古今人不甚相远也。
初学不外临摹。临书得其笔意，摹书得其间架。临摹既久，则莫如多看、多悟、多商量、多变通。坡翁学书，尝将古人字帖悬诸壁间，观其举止动静，心摹手追，得其大意。此中有人、有我，所谓：学不纯，师也。又尝有句云：诗不求工字不奇，天真烂漫是吾师。古人用心不同，故能出人头地。余尝谓：临摹不过学字中之字，多会悟则字中有字、字外有字，全从虚处着精神。彼钞帖、画帖者，何曾梦见？
废纸败笔，随意挥洒，往往得心应手。一遇精纸佳笔，整襟危坐，公然作书，反不免思遏手蒙。所以然者，一则破空横行，孤行己意，不期工而自工也；一则刻意求工，局于成见，不期拙而自拙也。又若高会酬酢，对客挥毫，与闲窗自怡，兴到笔随，其乖合亦复迥别。欲除此弊，固在平时用功多写，或于临时酬应多尽数纸，则腕愈熟、神愈闲，心空笔脱，指与物化矣。总之，凡事有人则天不全，不可不知。
徐而庵先生说唐诗，阐发尽致，开卷有论诗数条，内一条云：学诗如僧家托钵，积千家米煮成一锅饭。余谓学书亦然，执笔之法，始先择笔之相近者仿之，逮步伐点画稍有合处，即宜纵览诸家法帖，辨其同异，审其出入，融会而贯通之，酝酿之久，自成一家面目。否则刻舟求剑，依样葫芦，米海岳所谓奴书是也。古人作书，遗貌取神。今人作书，貌合神离。其间相去之远，岂可以道里计哉？
名家作书，只是一鼻孔出气。赵集贤云：书法随时变迁，用笔千古不易，古人得佳帖数行，专心学之，便能名家。据此似与余前说博观之义相戾，殊不知由一贯万，由万会一，总是一个道理。所谓千古不易者，要在善于弄翰磬控纵，送锋芒不顿，如庖丁解牛，批却导窾，迎刃而解；即所谓其中非尔力也。不明此旨，无论博搜约取，茫无把鼻。谚云：见一个菩萨磕一个头，不免终身为门外汉耳。
凡学艺，于古人论说总须细心体会，粗心浮气，无有是处。尝见某帖跋尾有驳赵文敏笔法不易之说者，谓欧、虞、薛、褚笔法已是不同，试以褚书笔法为欧书结构，断难相合，安得谓千古不易乎？余窃笑其翻案之谬。盖赵文敏为有元一代大家，岂有道外之语！所谓千古不易者，指笔之肌理言之，非指笔之面目言之也。谓笔锋落纸，势如破竹，分肌劈理，因势利导，要在落笔之先腾掷而起，飞行绝迹，不粘定纸上讲求生活，笔所未到，气已吞。笔所已到，气亦不尽，故能墨无旁渖，肥不剩肉，瘦不露骨，魄力、气韵、风神皆于此出。书法要旨，不外是矣。集贤所说只是浑而举之，古人于此等处不落言诠。余曾得斯旨，不惮反复言之，亦仅能形容及此，会心人定当首肯。若以形迹求之，何异痴人说梦！
作字有顺逆，有向背，有起伏，有轻重，有聚散，有刚柔，有燥湿，有疾徐，有疏密，有肥瘦，有浓淡，有连有断，有脱御，有承接，具此数者，方能成书。否则，墨猪、算子，全是魔道矣。
古人作书，落笔一圆便圆到底，落笔一方便方到底，各成一种章法。兰亭用圆，圣教用方，二帖为百代书法模楷，所谓规矩方圆之至也！欧颜大、小字皆方；虞书则大、小皆圆；褚书则大字用方，小字用圆。究竟方圆，仍是并用。以结构言之，则体方而用圆；以转束言之，则内方而外圆；以笔质言之，则骨方而肉圆。此是一定之理。又晋人体势多扁，唐人体势多长，合晋、唐观之，惟右军、鲁公无长扁之偏，而为方圆之极则。
晋人取韵，唐人取法，宋人取意，人皆知之。吾谓晋书如仙，唐书如圣，宋书如豪杰。学书者从此分门别户，落笔时方有宗旨。
字有筋骨、血脉、皮肉、神韵、脂泽、气息，数者缺一不可。无论真楷行草，皆宜讲究。楷书须八面俱到，古人称卫夫人、逸少父子、欧阳率更、虞永兴、智永禅师、颜鲁公此七家谓之楷书，其馀不过真书而已。楷书者字体端正，用笔合法之谓也。行楷者，字虽绾结，笔仍典则之谓也。此外或真书，或行书，或真行，或行草，或大草，或墨色不到而意与笔皆到，或笔墨不到而意无不到，总之以法为主，气以辅之，则任笔所之，无不如志矣。
欧、虞、褚、薛不拘拘于说文，犹之韩、柳、欧、苏不斤斤于音韵。空诸所有，精神乃出。古人作楷，正体、帖体纷见错出，随意布置。惟鲁公干禄字书一正一帖，剖析详明，此专为字画偏旁而设，而其用笔尽合楷则。近来书生笔墨、台阁文章，偏旁布置，穷工极巧，其实不过写正体字，非真楷书也。
楷书如立，行书如走，草书如飞，此就字体言之，用笔亦然，执笔落纸如人之立地，脚根既定，伸腰舒背，骨立自然强健，稍一转动，四面皆应。不善用笔者，非坐卧纸上，即蹲伏纸上矣。欲除此弊，无他谬巧，只如思翁所谓：落笔时先提得笔起耳。
所谓落笔先提得笔起者，总不外凌空起步、意在笔先。一到著纸，便如兔起鹘落，令人不可思议。笔机到则笔势劲，笔锋出，随倒随起，自无僵卧之病矣！古人谓：心正则气定，气定则腕活，腕活则笔端，笔端则墨注，墨注则神凝，神凝则象滋，无意而皆意，不法而皆法。此正是先天一著工夫，省却多少言思拟议，所谓一了百了也。
字无所谓山林、台阁也，古来书家类多置身廓庙之士，若终身隐沦者恐亦不少，而其书之传与不传，或传之远与近，虽各因名位为显晦，而诣之所至，不可磨灭。且有学问经术超越寻常，反为书名所掩者。盖亦有数存乎其间也。自帖括之习成，字法遂别为一体。土龙木偶，毫无意趣，矫其弊者又复貌为高古，自出新奇。究之学台阁者，趣入官样；学山林者，流为野战。皆非书家正法眼藏也。
字莫患乎散，尤莫病于结。散则贯注不下，结则摆脱不开。古人作书，于联络处见章法，于洒落处见意境。右军书转左侧右，变化迷离，所谓状若断而复连，势如斜而反正者，妙于离合故也。欧、虞、褚、薛各得其秘，而欧书尤为显露，其要在从谨严得森挺，从密栗得疏朗，或行或楷，必左右揖让，倜傥权奇，戈戟铦锐，物象生动，自成一家风骨。史称其人貌丑而颖悟，观其书信然！学者得其一鳞片甲，由唐入晋，自有门径矣。
字有九宫，分行布白是也。右军黄庭经、乐毅论，欧阳率更醴泉铭、千字文，皆九宫之最准者，其要不外斗笋接缝，八面皆满，字内无短缺处，字外无长出处，总归平直中正，无他谬巧也。
字有解数，大旨在逆，逆则紧，逆则劲，缩者伸之势，郁者畅之机，而又须因迟见速，寓巧于拙，取圆于方。狐疑不决，病在馁。剽急不留，病在滑。得笔须随，失笔须救，细参消息，斯为得之。
用笔之法，太轻则浮，太重则踬。到恰好处，直当得意。唐人妙处正在不轻不重之间，重规叠矩，而仍以风神之笔出之。褚河南谓：字里金生，行间玉润。又云：如锥画沙，如印印泥。虞永兴书如抽刀断水，颜鲁公古钗股、屋漏痕，皆是善使笔锋，熨帖不陂，故臻绝境。不善学者，非失之偏软，即失之生硬；非失之浅率，即失之重滞。貌为古拙，反入于颓靡；托为强健，又流于倔强。未识用笔分寸，无怪去古人日远也。
古人谓：喜气画兰，怒气画竹，各有所宜。余谓：笔墨之间，本足觇人气象，书法亦然。王右军、虞世南字体馨逸，举止安和，蓬蓬然得春夏之气，即所谓喜气也。徐季海善用渴笔，世状其貌如怒猊抉石、渴骥奔泉，即所谓怒气也。褚登善、颜常山、柳谏议文章妙古今，忠义贯日月，其书严正之气溢于楮墨。欧阳父子险劲秀拔，鹰隼摩空，英俊之气咄咄逼人。李太白书新鲜秀活，呼吸清淑，摆脱尘凡，飘飘乎有仙气。坡老笔挟风涛，天真烂漫；米痴龙跳天门，虎卧凤阙。二公书横绝一时，是一种豪杰之气。黄山谷清癯雅脱，古澹绝伦，超卓之中寄托深远，是名贵气象。凡此皆字如其人，自然流露者。惟右军书，醇粹之中，清雄之气俛视一切，所以为千古字学之圣。鲁公浑厚天成，精深博大，所以为有唐一代之冠。
凡字每落笔皆纵点起，点定则四面皆圆，笔有主宰，不致偏枯草率，波折钩勒，一气相生，风骨自然遒劲。董文敏谓：如大力人通身是力，倒辄能起。又云：自收自到，自起自结。皆此意也。褚河南行书、赵文敏行楷，细参自能悟入。
作字先学执笔，明戈汉溪守智书法辨异一书，载有笔阵图，执笔诸式其最正中者，莫如拨镫、平覆两法。拨镫或谓挑镫，或谓马镫，于义皆是。总之执笔须浅，浅则易于转动，其法先拓大指，使虎口圆则掌心自虚，大指为捺，食指为压，中指为钩，无名指为抵推导送，五指则紧贴名指之内，相助为力。字之讲遒劲者用之。平覆之法，使掌下覆，大指与二、三指稍齐，或用二、三指双钩。字之讲犀利者用之。此外有三指立异法，则以大、二、三指搦管，四、五指不用。四指立异法，则大指在内，二、三、四指在外。或谓即马镫法，如两人并乘，各不相犯。此二法最妙，以其不必留心运腕，而指自能不动也。撮笔法，著纸轻浅，字之尚逸趣者用之。悬腕法，则运腕离案，能使通身气力贯注笔尖。回腕法，掌心向内，五指俱平，腕竖锋正，笔画兜裹。此二法，量字体大小为离案之远近。即拨镫、平覆、撮笔、立异法，亦无不离案也。枕腕法，间或为之，亦无不可。其他如抓斗式、握拳式，擘窠大书用作榜署者，不能不尔，无所为法则也。运指不如运腕，书家遂有腕活指死之说。不知腕固宜活，指安得死！肘使腕，腕使指，血脉本是流通，牵一发而全身尚能皆动，何况臂指之近乎？此理易明。若使运腕而指竟漠不相关，则腕之运也，必滞其书，亦必至麻木不仁，所谓腕活指死者，不可以辞害意。不过腕灵则指定，其运动处不著形迹，运指腕随，运腕指随，有不知指之使腕与腕之使指者，久之，肘中血脉贯注，而腕亦随之定矣。周身精神贯注，则运肘亦不自知矣。此自然之气机，非可以矫揉造作也。所以把笔宜浅，用力宜轻，指宜密、宜直；或作环抱状，则虎口自圆，掌心自虚。又先须端坐正心，则气自和，血脉自贯，臂自活，腕自灵，指自凝，笔自端。是臂也、腕也、掌也、提也、笔也，皆运用在一心，不知所使，而无不一一效命者也。至于熟极巧生，直便化去，并执笔、运笔之法，亦皆忘之，所谓心忘手，手忘笔也。王献之少时学书，右军从背后取其笔而不可，知其长大必能名世。盖谓初学时着意在笔，非谓用笔宜紧也。又昔有人问索靖笔法，索靖以三指执笔，闭目谓之曰：胆、胆、胆。欧阳文忠公谓：执笔无定法，要使虚而宽。米襄阳谓：学书贵弄翰，迅速天真，出于意外。黄涪翁论书谓：须通身气力来笔尾上，直当得意。坡老云：作书不在笔牢，浩然听笔之所之，而不失法度。数公之言皆是，由执几化，绝妙悟境。中庸云：诚者不勉而中，不思而得，从容中道。诚之者，择善而固执之。道也通乎艺矣！学书者由勉强以渐近自然，艺也进于道矣。古人书，行间茂密，体势宽博。唐之颜，宋之米，其精力弥满，令人洞心駴目。自思翁出，而章法一变，密处皆疏，宽处皆紧，天然秀削，有振衣千仞、洁身自好光景，然篇幅较狭，去古人远矣。
作书能养气，亦能助气。静坐作楷法数十字或数百字，便觉矜躁俱平。若行草，任意挥洒，至痛快淋漓之候，又觉灵心焕发。下笔作诗、作文，自有头头是道，汨汨其来之势。故知书道，亦足以恢扩才情、酝酿学问也。', '《临池管见》一卷，论行楷法则，凡三十一条，直抒所见，可供参考。', '', '', NULL, '', 'indent', 1546563046, '5c2e3d3167f356005feda4a8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640936, '笔论', NULL, 8, 18, 1, 0, '蔡邕', NULL, 18111, '5858ec6a61ff4b0063d728d9', '汉', 'wen', '文', '', '', '书者，散也。欲书先散怀抱，任情恣性，然后书之。若迫于事，虽中山兔毫，不能佳也。夫书，先默坐静思，随意所适，言不出口，气不盈息，沉密神彩，如对至尊，则无不善矣。
为书之体，须入其形。若坐若行，若飞若动，若往若来，若卧若起，若愁若喜，若虫食木叶，若利剑长戈，若强弓硬矢，若水火，若云雾，若日月。纵横有可象者，方得谓之书矣。', '', '', '', NULL, '', 'indent', 1546611643, '5c2efb5144d904005de80d13', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640939, '海岳名言', NULL, 13, 330, 1, 0, '米芾', NULL, 27438, '582c66af67f35600632c242d', '宋', 'wen', '文', '', '', '历观前贤论书，征引迂远，比况奇巧，如“龙跳天门，虎卧凤阁”，是何等语？或遣辞求工，去法逾远，无益学者。故吾所论，要在入人，不为溢辞。
吾书小字行书，有如大字。唯家藏真迹跋尾，间或有之，不以与求书者。心既贮之，随意落笔，皆得自然，备其古雅。壮岁未能立家，人谓吾书为集古字，盖取诸长处总而成之。既老始自成家，人见之，不知以何为祖也。
江南吴岏、登州王子韶，大隶题榜有古意，吾儿友仁大隶题榜与之等。又幼儿友知代吾名书碑及手大字更无辨。门下许侍郎尤爱其小楷，云每小简可使令嗣书，谓友知也。
老杜作《薛稷慧普寺》诗云：“郁郁三大字，蛟龙岌相缠。”今有石本得视之，乃是勾勒倒收笔锋，笔笔如蒸饼，“普”字如人握两拳，伸臂而立，丑怪难状。由是论之，古无真大字明矣。
葛洪“天台之观”飞白，为大字之冠、古今第一。欧阳询“道林之寺”，寒俭无精神。柳公权国清寺，大小不相称，费尽筋骨。裴休率意写牌，乃有真趣，不陷丑怪。真字甚易，唯有体势难，谓不如画算，勾，其势活也。
字之八面，唯尚真楷见之，大小各自有分。智永有八面已少钟法。丁道护，欧、虞笔始勾，古法亡矣。柳公权师欧，不及远甚，而为丑怪恶札之祖。自柳世始有俗书。
唐官告在世，为褚、陆、徐峤之体，殊有不俗者。开元已来，缘明皇字体肥俗，始有徐浩以合时君所好，经生字亦自此肥，开元已前古气无复有矣。
唐人以徐浩比僧虔，甚失当。浩大小一伦，犹吏楷也。僧虔，萧子云传钟法，与子敬无异，大小各有分，不一伦。徐浩为颜真卿辟客书韵，自张颠血脉来，教颜大字促令小，小字展令大，非古也。
石刻不可学，但自书使人刻之已非己书也，故必须真迹观之乃得趣。如颜真卿，每使家僮刻字，故会主人意，修改披撇，致大失真。唯吉州庐山题名，题讫而去，后人刻之，故皆得其真，无做作凡差，乃知颜出于褚也。又真迹皆无蚕头燕尾之笔，《与郭知运争坐位帖》有篆籀气，颜杰思也。柳与欧为丑怪恶札祖，其弟公绰乃不俗于兄，筋骨之说出于柳。世人但以怒张为筋骨，不知不怒张，自有筋骨焉。
凡大字要如小字，小字要如大字。褚遂良小字如大字，其后经生祖述，间有造妙者。大字如小字未之见也。
世人多写大字时用力捉笔，字愈无筋骨神气，作圆笔头如蒸饼大，可鄙笑。要须如小字锋势备全，都无刻意做作，乃佳。自古及今，余不敏，实得之榜字，固已满世自有识者知之。
石曼卿作佛号，都无回互转折之势，小字展令大，大字促令小，是颠教颜真卿谬论。盖字自有大小相称，且如写太一之殿，作四窠分，岂可将一字肥满一窠，以对殿字乎？盖自有相称大小，不展促也。余尝书天庆之观，天、之字皆四笔，庆、观字多画在下，各随其相称写之，挂起气势自带过，皆如大小一般，虽真有飞动之势也。
书至隶兴，大篆古法大坏矣。篆籀各随字形大小，故知百物之状，活动圆备，各各自足，隶乃始有展促之势，而三代法亡矣。
欧、虞、褚、柳、颜皆一笔书也。安排费工，岂能垂世。李邕脱子敬，体乏纤浓。徐浩晚年力过，更无气骨，皆不如作郎官时婺州碑也。董孝子不空皆晚年恶札，全无妍媚，此自有识者知之；沈传师变格，自有超世真趣，徐不及也；御史萧诚书太原题名，唐人无出其右，为《司马系南岳真君观碑》，极有钟王趣，余皆不及矣。
智永临集千文，秀润圆劲，八面具备，有真迹。自颠沛字起在唐林夫处，他人所收不及也。
字要骨格，肉须裹筋，筋须藏肉，帖乃秀润生布置，稳不俗，险不怪，老不枯，润不肥。变态贵形不贵苦，苦生怒，怒生怪；贵形不贵作，作入画，画入俗：皆字病也。
“少成若天性，习惯若自然。”兹古语也。吾梦古衣冠人授以摺纸书，书法自此差进。写与他人，都不晓。蔡元长见而惊曰：“法何太遽异耶？”此公亦具眼人。章子厚以真自名，独称吾行草，欲吾书如排算子，然真字须有体势，乃佳尔。
颜鲁公行字可教，真便入俗品。
尹仁等古人书，不知此学吾书多。小儿作草书，大假有意思。
智永砚成臼，乃能到右军；若穿透，始到钟、索也。可永勉之。
一日不书，便觉思涩。想古人未尝片时废书也。因思苏之才《恒公至洛帖》字明意，殊有工，为天下法书第一。
半山庄台上多文公书，今不知存否。文公与杨凝式书人鲜知之。余语其故，公大赏其见鉴。
金陵幕山楼隶榜石，关蔚宗二十一年前书。想六朝宫殿榜皆如是。
薛稷书慧普寺，老杜以为“蛟龙岌相缠”。今见其本，乃如柰重儿，握蒸饼势，信老杜不能书也。
学书须得趣，他好但为乃入妙。别为一好萦之，便不工也。
海岳以书学博士召对。上问本朝以书名世者凡数人。海岳各以其人对曰：“蔡京不得笔，蔡卞得笔而乏逸韵，蔡襄勒字，沈辽排字，黄庭坚描字，苏轼画字。”上复问卿书如何，对曰：“臣书刷字。”', '', '', '遍观前代名家关于书法的评论，引证之事，全都曲折而抽象，就好比“龙跃天门，虎臣凤阁”之类，这是什么语言呢？要不就是追求华丽的辞藻，这样其实离具体的笔法更远了，对学书者没什么益处。所以我这里所说的，只想人易理解，不用那些浮夸之辞。
我写的小字行书，有如大字；但我只在家藏的真迹题跋后，偶尔这么写，不给求字的人。写这种字，关键是要胸有成竹，心中有底就可以随意下笔，写起来很自然，而字迹也古朴雅致。我成年时书法还未能自成一家，别人都说我的字是“集古字”。其实我这是吸取各家之长，将其综合起来。等到年老的时候，就开始独成一家，别人见了，竟然不知道我是学哪一家的字呢。
江南的吴<山完>，登州的王子韶，用大字隶书题榜很有古意；我儿子友仁，大字隶书跟他们一样。再者，我小儿子友知，代我写碑及手书大字，别人都分不出来；门下省的许侍郎尤其喜欢他的小楷，曾对我说过：“若有给我的短简，可让你儿子代写。”他说的就是我小儿友知。
杜甫写了首题为《薛稷慧普寺》的诗，其中有两句说：“郁郁三大字，蛟龙岌相缠”。现在见到了原石的拓本，一看，原来是用回锋色勒的，每一笔都显得跟蒸饼似的。其中的“普”字，就像一人握紧两拳，伸直了双臂杵在那儿，实在是怪异不美。由此说来，古人根本就没有真正的大字。
葛洪所书“天台之观”四字飞白书，为大字之冠，古今第一。欧阳询写的“道林之寺”，单薄寒酸，没有精神。柳公权所书“国清寺”，字体大小不相称，还费尽气力。裴休随心书写牌匾，倒很有味道，不至于丑怪。楷书很容易写，只是写出气势来难。应该说，只有不像画算筹似地那么刻板，笔势就活了。
字有八面，只有在正楷中能全部表现出来，大字小字各具其妙。智永的字有八面，可是已经缺少钟繇笔法。丁道护，欧阳询，虞世南等人，笔法开始变得整齐匀称，此时已是古法殆尽了。柳公权字学欧阳询，但远不如欧，反成丑陋怪诞之祖。自柳公权开始，世上便有了俗书。
当初唐朝的委任文书都用褚遂良、陆柬之及徐峤的字体，其中颇有不俗之作。开元以来，只因唐明皇的字体属肥俗一路，开始有徐浩之流，写丰肥之字以取悦皇上，抄经者的字体也开始变肥了。开元之前的古气就不再有了。
唐朝人把徐浩比作王僧虔，是很不恰当的。徐浩的字，大小一致，跟下层文吏的楷书差不多。王僧虔、萧子云传承钟繇笔法，和王献之的字一样，大小各得其所，不会强求一致。徐浩是颜真卿的门客，书体源自张旭一派；张旭教颜真卿大字缩小，小字扩大，这却非古法。
不能学石刻上的字。因为自己写的字拿去让别人刻，刻出来就变了样了。所以说，还须拿真迹来观赏研究，才能得其真谛。比如，颜真卿就常让家仆去把他的字上石，家仆猜度主人心思，刻字时就将撇捺等笔画作了修改，于是颜氏书迹大为失真。只有在吉州庐山的题名，是当时题完就走了，后人根据原迹刻石，所以保存了颜书的本来面目，没有做作庸俗的的缺点。看了这个才知道颜书是出于褚体的。况且，颜字真迹中也没有蚕头雁尾的笔画。颜真卿写给郭英乂的《争座位帖》，有篆书籀字的味道，是颜书中的杰作。柳公权与欧阳询的字是丑怪俗烂之祖，不过其弟枊公绰却不和兄长一般俗气。字贵筋骨之说出于柳。世人只知字怒张者有筋骨，却不知不故作怒张者，也自有筋骨在的。
都说大字要当小字写，小字要当大字写。褚遂良小字写得如同大字般有气势开张，以后的抄生者学他，偶尔也有字写得好的。大字写得跟小字一样细致入微，一丝不苟，还没见过别人有这样的字。
世人写大字时大多用力抓笔，这样反而更没有筋骨精神，写出的圆笔末尾就和蒸饼似的，实在鄙陋可笑。大字要写得跟小字一样细微，笔锋气势一应俱全，必须无半点刻意造作才算佳品。自古以来，还没有写大字如小字的，在下不才，幸而掌握了其中的诀窍。现如今的大字随处可见，这些人中总会有人明白我的。
石延年（字曼卿）所写的佛祖名号，全无回环转折的体势；小字扩大，大字缩小，那是随性癫狂的张教给颜真卿的谬论。事实上，字本身有大有小，比如说写“太一之殿”四个字，分四格写，难道要把“一”字写得肥大，占满一整格，以和“殿”字保持大小一致吗？其实大小适宜即可不必特意扩大或缩小。我曾经写过“天庆之观”四个大字，“天”字和“之”字都只有四笔，“庆（慶）”字和“观（觀）”字下面笔画多，我根据其自然的形态来写，写完挂起来一看，气势连贯，大小适宜，确乎有飞动之势。
到隶书产生，大篆古法就被破坏殆尽了。篆文籀字都是各随其字形大小而写的，正如世间万物，生动完美，各具其态。隶书开始有了大者缩小，小者扩大的写法，从此古文，篆，籀的书写古法就不复存在了。
欧阳询、虞世南、褚遂良，颜真卿，柳公权诸人，都只有一种笔法，写起来刻意造作，苦心经营，这样的书法怎能流传后世？李邕书法出自王献之，但失去了纤细与丰腴的适宜调节。徐浩晚年笔力衰退，写的字就更没了气骨，还不如作郎官时的《婺州碑》写得好。他的《董孝子碑》《不空和尚碑》都是晚年所书，完全是败笔，毫无美感，凡是有欣赏眼光的人都会明白这一点。沈传师独辟蹊径，却有不凡的真趣，徐浩是不如他的。御史萧诚写的太原题名，唐人中没有比他强的。为司马氏所书《南岳真君观碑》，很有钟繇，王羲之的味道，其它作品都不如这一件。
智永临写千字文，面秀色润，笔圆力劲，八面俱备；这件作品有真迹传世。自“颠沛（匪亏）”起，在唐林夫处，别人所收集的都没有他的多。
字要有骨力格调，肉须裹筋，筋要藏肉，这样就能俊秀丰润，结构妥贴，不落俗套。要做到险而不怪，老而不枯，丰而不肿。图变求新，贵在形态巧妙而不在苦用蛮力。苦则怒张，怒则怪异；贵在形态巧妙却又不能做作，做作就成了画画了，写字成了画画，那就俗了。这些都是写字的弊病。
“少成若天性，习惯若自然”这是自古传下来的老话。我曾梦见有一个穿着服装的人教我折纸作书，自那以后书法就有了些进步，写给别人看都看不出区别来；只有蔡京见了惊奇地说：“你的笔法怎么突然变了那么多？”他真算是明眼人了。章惇自恃楷书优异，却单单称赞我的行草，暗示我的楷书跟排算筹似的呆板无神；不过楷书必须有体势才能算是佳品。
颜鲁公（真卿）行书可学，楷书就俗了。
我的儿子友仁等学习古人的字体，其实学的还是我的风格居多。这小子写的草书，还有那么一点意思。
智永写字写到磨砚成臼，才能学到王羲之的样子。如果将砚穿透，才能上追到钟繇索靖的境界吧。所以说学书还得加倍努力啊！
一天不写字，就觉得思路迟钝了，想来古人片刻不停地在练习啊。由此我想起苏之才的《恒公致洛帖》，字迹明朗，意味不凡，很见功力，应该算是天下字帖第一了。
半山庄的台上曾有许多王文公（安石）的字迹，不知道今天还有没有？王文公学的是杨凝式的字体，世人很少有知道的。我一说出，他很赞赏我的眼力。
金陵幕山楼的隶书匾额，是关蔚宗二十一年前所写。估计六朝时宫殿的匾额都是这个样子的吧。
薛稷写的“慧普寺”三字，杜甫认为是“蛟龙岌相缠”。现在看到原石拓本，就小孩子吃力地手握蒸饼的样子，可见杜甫是不会写字的。
学习书法，必须要有兴趣，忘掉其它嗜好才能写得精到。但凡有其它爱好萦绕在心，就写不好了。
我因对书法博学而被皇帝召去答话。皇上问起本朝几个时人认为会写字的人，我这样回答：“蔡京不得笔法要领，蔡卞有笔法而少韵致，蔡襄写字是用刻的，沈辽是用码的，黄庭坚是用描的，苏轼是用画的。”皇上又问：“那你写字呢？”我回答说：“我写字用刷的。”', NULL, '', 'indent', 1546646376, '5c2efd2b0b616000673cd159', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640941, '用笔论', NULL, 10, 9, 1, 0, '欧阳询', NULL, 10558, '5858e5a561ff4b0063d6f040', '隋', 'wen', '文', '', '', '有翰林善书大夫言于寮故无名公子曰：“自书契之兴，篆、隶滋起，百家千体，纷杂不同。至于尽妙穷神，作范垂代，腾芳飞誉，冠绝古今，惟右军王逸少一人而已。然去之数百年之内，无人拟者，盖与天挺之性，功力尚少，用笔运神未通其趣，可不然欤？”公子从容敛衽而言曰：“仆庸疏愚昧，禀命轻微，无禄代耕，留心笔砚。至如天挺、功力，诚如大夫之说。用笔之趣，请闻其说。”大夫欣然而笑曰：“此难能也。子欲闻乎？”公子曰：“予自少及长，凝情翰墨，每览异体奇迹，未尝不循环吟玩。抽其妙思，终日临仿，至于皓首而无退倦也。” 
“夫用笔之法，急捉短搦，迅牵疾掣，悬针垂露，蠖屈蛇伸，洒落萧条，点缀闲雅，行行眩目，字字惊心，若上苑之春花，无处不发，抑亦可观，是予用笔之妙也。” 
公子曰：“幸甚，幸甚！仰承余论，善无所加。然仆见闻异于是，辄以闻见便耽玩之，奉对大贤座，未敢抄说。”大夫曰：“与子同寮，索居日久，既有异同，焉得不叙？”公子曰：“向之造次，滥有斯言，今切再思，恐不足取。”大夫曰：“妙善异述，达者共传，请不秘之，粗陈梗概。”公子安退位逡巡，缓颊而言曰：“夫用笔之体会，须钩粘才把，缓绁徐收，梯不虚发，斫必有由。徘徊俯仰，容与风流。刚则铁画，媚若银钩，壮则啒吻而嶱嶫，丽则绮靡而清道。若枯松之卧高岭，类巨石之偃鸿沟，同鸾凤之鼓舞，等鸳鸯之沉浮。仿佛兮若神仙来往，宛转兮似兽伏龙游。其墨或洒或淡，或浸或燥，遂其形势，随其变巧，藏锋靡露，压尾难讨，忽正忽斜，半真半草。唯截纸棱，撇捩窈绍，务在经实，无令怯少。隐隐轸轸，譬河汉之出众星，昆冈之出珍宝，既错落而灿烂，复趢连而埽撩。方圆上下而相副，绎络盘桓而围绕，观寥廓兮似察，始登岸而逾好。用笔之趣，信然可珍，窃谓合乎古道。”
大夫应声而起，行吟而叹曰：“夫游畎浍者，讵测溟海之深；升培塿者，宁知泰山之峻。今属公子吐论，通幽洞微，过钟、张之门，入羲、献之室，重光前哲，垂裕后昆。中心藏之，盖棺乃止。”公子谢曰：“鄙说疏浅，未足可珍，忽枉话言，不胜惭惧。” ', '', '翰林善书大夫：这是一个虚拟的官名，与后面“无名公子”都是虚拟的人物。
寮：通“僚”。同官为寮。
书契：指文字。
垂代：流传后世。
天挺：天资。
禀命：受于天的命运。指在世为人。
无禄代耕：没有俸禄收入。语出《孟子·万章下》：“禄足以代其耕也。”
捉、搦（nuò）：握笔。
牵、掣（chè）：运笔。掣，拉、拽。
上苑：供帝王玩赏、打猎的园林。 
安：于是。 
缓颊而言：婉转地说。缓颊二字乃面带笑容之意，语出《史记·高帝纪上》：“汉王如荥阳，谓郦食其曰：“缓颊往说魏王豹。”
钩粘才把：钩，钩索义理，犹言穷理也，《易·系辞》：“钩深致远。”钩粘作深入探理解。才，通“载”。把，掌握。 
绁：本义为牵引牲畜的绳子，引申为牵引，这里指运笔。 
梯：导致事故的因由，指笔。
斫：砍。这里指下笔。 
容与：闲暇自得貌。 
风流：谓作品超逸美妙。 
啒吻：疑为“崛岉”二字之误。崛岉，高耸屹立貌。语出《文选·鲁殿灵光赋》：“隆崛岉乎青云”。 
嶱嶫：山之高峻之貌。 
鸿沟：古运河名。 
压尾：收笔之意。
窈绍：窈窕、美好貌。 
经实：充实之意。 
隐隐轸轸：形容众多、丰盛。
河汉：即银河。
昆冈：古代传说中的产玉之山。
趢连：“趢”字疑为”逮”字之误。逮，古文作“逯”。逮，及也，也就是连的意思。 
扫撩：扫，弃也，作散解，撩，理也，拢取物为撩。按文乃既散又合之意。
方圆：作周围解。
察：昭著、明显。
逾：通”愈”，更加。
畎浍：田间小沟。
培塿：小土丘。
钟：钟繇（151～230）字元常。三国魏大臣、书法家。
张：张芝（？～约192）字伯英，东汉时书法家。
羲：东晋书法家王羲之。
献：王羲之第七子献之，书法与父齐名，并称“二王”。
中心藏之：见《诗经·小雅·隰桑》：“心乎爱矣，退不谓矣，中心藏之，何日忘之”。 ', '有翰林善书大夫对旧同僚某公子说：”自从文字之创，篆、隶兴起，百家千体，纷杂不同。至于能完美入神，可作楷模流传后世，美名飞扬，古今称绝的，只有王羲之一人而已。以往数百年间，无人能相比者，因天资、功力都缺乏，对笔法的奇幻莫测未通其妙。可不是吗？”公子从容地整整衣袖后说：“我庸疏愚昧，人微言轻，不食俸禄，专心于书法。至于天资、功力，正如大夫所说。而用笔之妙，想听听你的见解。”大夫高兴地笑着说：“这是不容易的，你希望听吗？”公子说：“我自少及长，专心书法，每见结体多变，用笔奇妙，未尝不反复的玩赏、体会。分析其美妙构思，终日临仿，以至头发已白也没厌倦和后退。”
“用笔的方法，笔要紧握低捏，快行快拽，如悬针，如垂露，如蠖的屈曲，如蛇的伸展。萧洒脱略，从容大方，行行光彩夺目，字字惊心动魄，如园中之花，无处不发，多么可观啊！这就是我用笔的奥妙。”
公子说：“非常幸运！非常幸运！听到你的高论，真是再好没有了。然而我的见闻有不同于此的，每当闻见便深加玩味，现在面对着您，不敢全照您的说法。”大夫说：“与你同僚，相处日久，既有不同见解，哪可不谈？”公子说：“以前轻率，言谈过度，现在仔细再想，恐不可取。”大夫说：“美妙的不同论点，是通达事理的人应相互交流的，请勿秘守，粗说大概。”公子于是离开座位，踱步再三，婉转地说：“用笔的体会，必须深入探取，掌握裁夺。缓行慢收，笔不虚发，砍必有由。来去上下，悠闲而超逸。刚如铁画，媚若银钩，壮则高耸而峻立，丽则柔美而清劲。如枯松长于高山，巨石卧于鸿沟，与鸾凤的鼓舞，鸳鸯的沉浮相仿。好像神仙来往，飘忽无踪，兽伏龙游，委充曲折。其墨色或鲜明或淡雅、或湿润或枯燥。按照字的态势，随其巧妙变化，藏锋不露，收笔难寻。忽正忽斜，半真半草。只有用“断”的笔法（作方笔解）在纸上呈现出棱侧之势，一撇一折才能美好，点画务必充实，不使怯弱。茂茂密密，譬如银河的众星，昆冈的美玉，既交错缤纷而光彩鲜明，又相续连接而既散又拢。周围上下相称，来往徘徊相绕，看空阔处（用笔之趣）非常昭著，才能登达更为美好的（书艺）之岸。用笔之趣，确实可珍，私心以为这就合乎古代（笔法）的道理了。”
大夫听完霍地立起身来，边走边自言自语地叹息道：“走田间小沟的人，岂能测知大海的深度，立在小丘之上，哪知泰山的高大。现在听到公子的谈论，洞察书法的秘奥，已是近于钟繇、张芝，进入羲之、献之的堂奥了。真乃可以光复前贤，流传后代。我将藏于心中，直至终身。”公子谢道：“我的话粗疏肤浅，不足以珍重，现在屈尊听我讲话，十分惭愧惶恐。”', NULL, '', 'indent', 1546647881, '5c2f88dd44d904005df639dc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (640947, '石门岩上宿诗', NULL, 1, 135, 2, 1, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E7%9F%B3%E9%97%A8%E5%B2%A9%E4%B8%8A%E5%AE%BF/6297871?fr=aladdin', '', '朝搴苑中兰，畏彼霜下歇。
暝还云际宿，弄此石上月。
鸟鸣识夜栖，木落知风发。
异音同至听，殊响俱清越。
妙物莫为赏，芳醑谁与伐。
美人竟不来，阳阿徒晞发。', '《石门岩上宿》是南朝宋诗人谢灵运创作的一首五言古诗。这首诗可以分为三部分，首四句为第一部分以朝游引出暝宿与赏月；中四句为第二部分以夜间所闻来写景，颇得神韵；最后四句为第三部分慨叹景色虽美却无人共赏。这首诗的写景不写目中所见，只写耳中所闻，不写事物的形象，只写事物的声响，这种写法独出心栽，另辟蹊经，独特新颖。', '石门：即石门山，在今浙江嵊州市。诗中写夜宿石门时的所见所闻，并流露出孤高落寞的情绪。
朝搴苑中兰：袭用屈原《离骚》“朝搴阰之木兰兮”句意。搴（qiān）：取。
彼：指木兰等花草。霜下歇：经霜冻而凋谢。歇，衰竭。
弄：玩。
识：知。
异音、殊响：指上两句所说鸟声、树叶声、风声等。致听：传到耳朵里使能听见。
清越：清脆悠扬。
妙物：指上文兰、云、月、鸟、木、风等景物。
芳醑（xǔ）：芳香的美酒。谁与伐：谁与我共同品赏其美味。伐，赞美。
美人竟不来，阳阿徒晞发：引用屈原《九歌·少司命》：“与汝沐兮咸池，晞汝发兮阳之阿。望美人兮未来，临风恍兮浩歌。”诗中以美女喻友人，表达了缺少知音的落寞情绪。阳阿，古代神话传说中的山名。晞发，晒干头发。', '早上，到园子里摘兰花，担心秋霜会把花朵摧残。
晚上，回到高入云际的别墅中休息，玩赏着山石上婆娑的月影，难以入眠。
窗外，传来归鸟疲倦的叫声，它们在寻找栖息的树干，树叶飘落，簌簌作响，是起风了凉风在寒林中回旋。
静谧的山居，各种各样的声音，清晰入耳，听来各具异趣，又都那么悠扬，那么清远。
可惜如此美妙的夜晚，却无人同我一起欣赏，这满壶香醇的美酒，又有谁能与我同醉共欢。
远行的朋友，依然迟迟不归，不知不觉中，夜色渐渐褪尽，东方，已经朝霞初染。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb2911759740c9bd661", "shortContent": "谢灵运于宋景平元年（423）辞去永嘉太守之职，回到始宁的祖居，又营造了一些新的庄园别墅，其一在石门山上（今浙江嵊州境内）。石门别墅地势甚高，茂林修竹，环绕四周，一道山溪，曲折流过，是一个幽深而美丽的居所，很受谢灵运的喜爱。这诗写他夜宿于石门别墅的岩石上，外物与内情相激的特殊感觉。谢灵运的山水诗，大多以刻画景物之精巧见长，此诗却以听觉感受为主；大多好谈老庄玄理，此诗却不发议论，而自有深趣在字里行间；...", "authors": ["孙", "明"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "6470a54eb5420e27678a6ad3", "shortContent": "谢灵运于宋景平元年(423)辞去永嘉太守之职，回到始宁的祖居，又 营造了一些新的庄园别墅，其一在石门山上(今浙江嵊县境内)。石门别 墅地势甚高，茂林修竹，环绕四周，一道山溪，曲折流过，是一个幽深而美 丽的居所，很受谢灵运的喜爱。这诗写他夜宿于石门别墅的岩石上，外物 与内情相激的特殊感觉。谢灵运的山水诗，大多以刻画景物之精巧见长， 此诗却以听觉感受为主;大多好谈老庄玄理，此诗却不发议论，而自有深 趣...", "authors": ["孙", "明"], "pressName": "上海辞书出版社"}]', '浙江省古代文学学会常务理事俞樟华《池塘春草——谢灵运、孟浩然、王维诗选》：“诗人夜宿于石门别墅的岩石上，听着乌声风声，感受着秋夜的美景，不禁悲从中来，如此佳色绝景，却无具有高情逸趣的人相伴同游，一起欣赏，一种孤独寂寞之感，油然而生。此诗没有在景物描写之后来一段哲理性的议论，与作者的其他山水诗的写法不同。”', 'center', 1553685048, '5c30de6944d904005d112db4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641001, '江行无题一百首', NULL, 1, 435, 0, 1, '钱起', NULL, 10114, '57bbbb372e958a00694032d7', '唐', 'shi', '诗', '', '', '【其一】
倾酒向涟漪，乘流东去时。
寸心同尺璧，投此报冯夷。
【其二】
江曲全萦楚，云飞半自秦。
岘山回首望，如别故关人。
【其三】
浦烟函夜色，冷日转秋旻。
自有沈碑石，清光不照人。
【其四】
楚岸云空合，楚城人不来。
只今谁善舞，莫恨发阳台。
【其五】
行背青山郭，吟当白露秋。
风流无屈宋，空咏古荆州。
【其六】
晚来渔父喜，罾重欲收迟。
恐有长江使，金钱愿赎龟。
【其七】
去指龙沙路，徒悬象阙心。
夜凉无远梦，不为偶闻砧。
【其八】
霁云疏有叶，雨浪细无花。
隐放扁舟去，江天自有涯。
【其九】
好日当秋半，层波动旅肠。
已行千里外，谁与共秋光。
【其十】
润色非东里，官曹更建章。
宦游难自定，来唤棹船郎。
【其十一】
夜江清未晓，徒惜月光沉。
不是因行乐，堪伤老大心。
【其十二】
翳日多乔木，维舟取束薪。
静听江叟语，俱是厌兵人。
【其十三】
箭漏日初短，汀烟草未衰。
雨馀虽更绿，不是采蘋时。
【其十四】
山雨夜来涨，喜鱼跳满江。
岸沙平欲尽，垂蓼入船窗。
【其十五】
渚边新雁下，舟上独凄凉。
俱是南来客，怜君缀一行。
【其十六】
牵路沿江狭，沙崩岸不平。
尽知行处险，谁肯载时轻。
【其十七】
云密连江暗，风斜著物鸣。
一杯真战将，笑尔作愁兵。
【其十八】
柳拂斜开路，篱边数户村。
可能还有意，不掩向江门。
【其十九】
不识桓公渴，徒吟子美诗。
江清唯独看，心外更谁知。
【其二十】
憔悴异灵均，非谗作逐臣。
如逢渔父问，未是独醒人。
【其二十一】
水涵秋色静，云带夕阳高。
诗癖非吾病，何妨吮短毫。
【其二十二】
登舟非古岸，还似阻西陵。
箕伯无多少，回头讵不能。
【其二十三】
帆翅初张处，云鹏怒翼同。
莫愁千里路，自有到来风。
【其二十四】
秋云久无雨，江燕社犹飞。
却笑舟中客，今年未得归。
【其二十五】
佳节虽逢菊，浮生正似萍。
故山何处望，荒岸小长亭。
【其二十六】
行到楚江岸，苍茫人正迷。
只知秦塞远，格磔鹧鸪啼。
【其二十七】
月下江流静，村荒人语稀。
鹭鸶虽有伴，仍共影双飞。
【其二十八】
斗转月未落，舟行夜已深。
有村知不远，风便数声砧。
【其二十九】
棹惊沙鸟迅，飞溅夕阳波。
不顾鱼多处，应防一目罗。
【其三十】
渐觉江天远，难逢故国书。
可能无往事，空食鼎中鱼。
【其三十一】
岸草连荒色，村声乐稔年。
晚晴初获稻，闲却采莲船。
【其三十二】
滩浅争游鹭，江清易见鱼。
怪来吟未足，秋物欠红蕖。
【其三十三】
蛩响依莎草，萤飞透水烟。
夜凉谁咏史，空泊运租船。
【其三十四】
睡稳叶舟轻，风微浪不惊。
任君芦苇岸，终夜动秋声。
【其三十五】
自念平生意，曾期一郡符。
岂知因谪宦，斑鬓入江湖。
【其三十六】
烟渚复烟渚，画屏休画屏。
引愁天末去，数点暮山青。
【其三十七】
水天凉夜月，不是惜清光。
好物随人秘，秦淮忆建康。
【其三十八】
古来多思客，摇落恨江潭。
今日秋风至，萧疏独沔南。
【其三十九】
映竹疑村好，穿芦觉渚幽。
渐安无旷土，姜芋当农收。
【其四十】
秋风动客心，寂寂不成吟。
飞上危樯立，啼乌报好音。
【其四十一】
见底高秋水，开怀万里天。
旅吟还有伴，沙柳数枝蝉。
【其四十二】
九日自佳节，扁舟无一杯。
曹园旧尊酒，戏马忆高台。
【其四十三】
兵火有馀烬，贫村才数家。
无人争晓渡，残月下寒沙。
【其四十四】
渚禽菱芡足，不向稻粱争。
静宿凉湾月，应无失侣声。
【其四十五】
轻云未护霜，树杪橘初黄。
信是知名物，微风过水香。
【其四十六】
渺渺望天涯，清涟浸赤霞。
难逢星汉使，乌鹊日乘槎。
【其四十七】
土旷深耕少，江平远钓多。
生平皆弃本，金革竟如何。
【其四十八】
海月非常物，等闲不可寻。
披沙应有地，浅处定无金。
【其四十九】
风晚冷飕飕，芦花已白头。
旧来红叶寺，堪忆玉京秋。
【其五十】
风好来无阵，云闲去有踪。
钓歌无远近，应喜罢艨艟。
【其五十一】
吴疆连楚甸，楚俗异吴乡。
漫把尊中物，无人啄蟹筐。
【其五十二】
岸绿野烟远，江红斜照微。
撑开小渔艇，应到月明归。
【其五十三】
雨馀江始涨，漾漾见流薪。
曾叹河中木，斯言忆古人。
【其五十四】
叶舟维夏口，烟野独行时。
不见头陀寺，空怀幼妇碑。
【其五十五】
晚泊武昌岸，津亭疏柳风。
数株曾手植，好事忆陶公。
【其五十六】
坠露晓犹浓，秋花不易逢。
涉江虽已晚，高树搴芙蓉。
【其五十七】
舟航依浦定，星斗满江寒。
若比阴霾日，何妨夜未阑。
【其五十八】
近戍离金落，孤岑望火门。
唯将知命意，潇洒向乾坤。
【其五十九】
丛菊生堤上，此花长后时。
有人还采掇，何必在春期。
【其六十】
夕景残霞落，秋寒细雨晴。
短缨何用濯，舟在月中行。
【其六十一】
堤坏漏江水，地坳成野塘。
晚荷人不折，留取作秋香。
【其六十二】
左宦终何路，摅怀亦自宽。
襞笺嘲白鹭，无意喻枭鸾。
【其六十三】
楼空人不归，云似去时衣。
黄鹤无心下，长应笑令威。
【其六十四】
白帝朝惊浪，浔阳暮映云。
等闲生险易，世路只如君。
【其六十五】
橹慢开轻浪，帆虚带白云。
客船虽狭小，容得庾将军。
【其六十六】
风雨正甘寝，云霓忽晚晴。
放歌虽自遣，一岁又峥嵘。
【其六十七】
静看秋江水，风微浪渐平。
人间驰竞处，尘土自波成。
【其六十八】
风劲帆方疾，风回棹却迟。
较量人世事，不校一毫厘。
【其六十九】
咫尺愁风雨，匡庐不可登。
只疑云雾窟，犹有六朝僧。
【其七十】
幽思正迟迟，沙边濯弄时。
自怜非博物，犹未识凫葵。
【其七十一】
曾有烟波客，能歌西塞山。
落帆唯待月，一钓紫菱湾。
【其七十二】
千顷水纹细，一拳岚影孤。
君山寒树绿，曾过洞庭湖。
【其七十三】
光阔重湖水，低斜远雁行。
未曾无兴咏，多谢沈东阳。
【其七十四】
晚菊绕江垒，忽如开古屏。
莫言时节过，白日有馀馨。
【其七十五】
秋寒鹰隼健，逐雀下云空。
知是江湖阔，无心击塞鸿。
【其七十六】
日落长亭晚，山门步障青。
可怜无酒分，处处有旗亭。
【其七十七】
江草何多思，冬青尚满洲。
谁能惊鵩鸟，作赋为沙鸥。
【其七十八】
远岸无行树，经霜有半红。
停船搜好句，题叶赠江枫。
【其七十九】
身世比行舟，无风亦暂休。
敢言终破浪，唯愿稳乘流。
【其八十】
数亩苍苔石，烟濛鹤卵洲。
定因词客遇，名字始风流。
【其八十一】
兴闲停桂楫，路好过松门。
不负佳山水，还开酒一尊。
【其八十二】
幽怀念烟水，长恨隔龙沙。
今日滕王阁，分明见落霞。
【其八十三】
短楫休敲桂，孤根自驻萍。
自怜非剑气，空向斗牛星。
【其八十四】
江流何渺渺，怀古独依依。
渔父非贤者，芦中但有矶。
【其八十五】
高浪如银屋，江风一发时。
笔端降太白，才大语终奇。
【其八十六】
细竹渔家路，晴阳看结缯。
喜来邀客坐，分与折腰菱。
【其八十七】
幸有烟波兴，宁辞笔砚劳。
缘情无怨刺，却似反离骚。
【其八十八】
平湖五百里，江水想通波。
不奈扁舟去，其如决计何。
【其八十九】
数峰云断处，去岸映高山。
身到韦江日，犹应未得闲。
【其九十】
一湾斜照水，三版顺风船。
未敢相邀约，劳生只自怜。
【其九十一】
江雨正霏微，江村晚渡稀。
何曾妨钓艇，更待得鱼归。
【其九十二】
沙上独行时，高吟到楚词。
难将垂岸蓼，盈把当江蓠。
【其九十三】
新野旧楼名，浔阳胜赏情。
照人长一色，江月共凄清。
【其九十四】
愿饮西江水，那吟北渚愁。
莫教留滞迹，远比蔡昭侯。
【其九十五】
湖口分江水，东流独有情。
当时好风物，谁伴谢宣城。
【其九十六】
浔阳江畔菊，应似古来秋。
为问幽栖客，吟时得酒不。
【其九十七】
高峰有佳号，千尺倚寒松。
若使炉烟在，犹应为上公。
【其九十八】
万木已清霜，江边村事忙。
故溪黄稻熟，一夜梦中香。
【其九十九】
楚水苦萦回，征帆落又开。
可缘非直路，却有好风来。
【其一百】
远谪岁时晏，暮江风雨寒。
仍愁系舟处，惊梦近长滩。', '', '一说作者为钱珝。', '', NULL, '', 'center', 1547076690, '5c3613fb9f54540070d52b4a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641015, '清思赋', NULL, 11, 90, 1, 0, '阮籍', NULL, 10412, '581a0b630ce4630058684ead', '南北朝', 'fu', '赋', '', '', '余以为形之可见，非色之美；音之可闻，非声之善。昔黄帝登仙于荆山之上，振《咸池》于南岳之冈，鬼神其幽，而夔、牙不闻其章；女娃耀荣于东海之滨，而翩翻于西山之旁，林石之陨从，而瑶台不照其光。是以微妙无形，寂寞无听，然后乃可以睹窈窕而淑清。故白日丽光，则季后不步其容；钟鼓阊铪，则延子不扬其声。
夫清虚寥廓，则神物来集；飘飖恍忽，则洞幽贯冥；冰心玉质，则激洁思存；恬淡无欲，则泰志适情。伊虑之遒好兮，又焉处而靡逞？寒风迈于黍谷兮，诲子而游 。申孺悲而母归兮，吴鸿哀而象生。兹感激以达神，岂浩瀁而弗营？志不凯而神正，心不荡而自诚。固秉一而内修，堪奥止之匪倾。惟清朝而夕晏兮，指蒙汜以永宁。
是时羲和既颓，玄夜始扃；望舒整辔，素风来征。轻帷连飏，华茵肃清。彭蚌微吟，蝼蛄徐鸣。望南山之崔巍兮，顾北林之葱菁。太阴潜乎后兮，明月耀乎前庭。乃申展而缺寐兮，忽一悟而自惊。驾长灵以遂寂兮，将有歙乎所之。意流荡而改虑兮，心震动而有思。若有来而可接兮，若有去而不辞。心恍忽而失度，情散越而靡治。岂觉察而明真兮，诚云梦其如兹。惊奇声之异造兮，鉴殊色之在斯。开丹桂之琴瑟兮，聆崇陵之参差。始徐唱而微响兮，情悄慧以蜲虵。遂招云以致气兮，乃振动而大骇。声飂飂以洋洋，若登昆仑而临四海；超遥茫渺，不能究其所在。
心瀁瀁而无所终薄兮，思悠悠而未半。邓林殪于泽兮，钦邳悲于瑶岸。徘徊夷由兮，猎靡广衍；游平圃以长望兮，乘修水之华旗。长飔肃以永至兮，涤平衢之大夷。循路旷以径通兮，辟闺闼而洞闱。羡要眇之飘游兮，倚东风以扬晖。沐洧渊以淑密兮，体清洁而靡讥。厌白玉以为面兮，披丹霞以为衣。袭九英之曜精兮，佩瑶光以发辉。服儵煜以缤纷兮，綷众采以相绥。色熠熠以流烂兮，纷杂错以葳蕤。象朝云之一合兮，似变化之相依。麾常仪使先好兮，命河女以胥归。步容与而特进兮，盼两楹而升墀。振瑶溪而鸣玉兮，播陵阳之婓婓。蹈消漺之危迹兮，蹑离散之轻微。释安朝之朱履兮，践席假而集帷。敷斯来之在室兮，乃飘忽之所晞。馨香发而牙扬兮，媚颜灼以显姿。清言窍其如兰兮，辞婉婉而靡违。托精灵之运会兮，浮日月之余晖。假淳气之精微兮，幸备嬿以自私。愿申爱于今夕兮，尚有访乎是非！
被芬芳之夕畅兮，将暂往而永归。观悦怿而未静兮，言未究而心悲。嗟云霓之可凭兮，翻挥翼而俱飞。弃中堂之局促兮，遗户牗之不处。帷幕张而靡御兮，几筵设而莫拊。载云舆之奄霭兮，乘夏后之两龙。折丹木以蔽阳兮，竦芝盖之三重。翩翼翼以左右兮，纷悠悠以容容。瞻朝霞之相承兮，似美人之怀忧。采色杂以成文兮，忽离散而不留。若将言之未发兮，又气变而飘浮。若垂髦而失鬋兮，饰未集而形消。目流盼而自别兮，心欲来而貌辽。纷绮靡而未尽兮，先列宿之规矩。时傥莽而阴曀兮，忽不识乎旧宇。迈黄妖之崇台兮，雷师奋而下雨。内英哲与长年兮，笞离伦与膺贾。摧魍魉而折鬼神兮，直径登乎秘期。历四方而纵怀兮，谁云顾乎或疑。超高跃而疾骛兮，至北极而放之！援间维以相示兮，临寒门而长辞。既不以万物累心兮，岂一女子之足思！', '', '', '', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf592e6a6b501f968197", "shortContent": "《悼亡赋》是一篇悼念亡妻的抒情小赋。悼亡，悼念已故之人，这里指悼念亡妻。潘岳妻杨氏，荆州刺史杨肇之女，荥阳宛陵人。潘岳在为悼念其岳父杨肇而作《怀旧赋》中说：“余十二而获见于父友东武戴侯杨君，始见知名，遂申之以婚姻。”在《杨仲武诔》中说：“杨经字仲武，荥阳宛陵人也。……既藉三叶世亲之恩，而子之姑，余之伉俪焉，往岁卒于德宫里。丧服同次，绸缪累月。苟人必有心，此亦款诚之至也。不幸短命，春秋二十九，元康九...", "authors": ["杨晓斌"], "pressName": "上海辞书出版社"}, {"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf665e272d4b2254edb4", "shortContent": "乃知接武烟鸿，追踪霜鹄，既横空而似阵，自违寒而顺燠。北方远兮南图，遥云飞兮水宿。\n田锡为北宋著名律赋作家，李调元说：“宋初人之律赋最夥者，田、王（禹偁）、文（彦博）、范（仲淹）、欧阳（修）五公……故论宋朝律赋，当以表圣、宽夫（文彦博）为正则。”（《赋话》卷五）此篇为一律赋，描写大雁迁徙时飞行的阵形。\n律赋讲求起承转合，首尾呼应。田锡此赋，开篇即破题。“绝塞霜早，阴山叶飞”，首八字写出秋霜初凝、木叶...", "authors": ["尹占华"], "pressName": "上海辞书出版社"}]', '', 'indent', 1547311424, '5c39a8ea0b6160007041c744', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641052, '清明二绝（其二）', NULL, 7, 662, 1, 0, '陈与义', NULL, 10102, '57baf563165abd0066277faf', '宋', 'shi', '诗', '', '', '卷地风抛市井声，病夫危坐了清明。
一帘晚日看收尽，杨柳微风百媚生。', '', '', '', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea7252cee9a0c24ed480c", "shortContent": "宣和四年（1122），由于知州葛胜仲的推荐，陈与义以《墨梅》诗见赏于徽宗。《清明二绝》即写于宣和五年，为其前期作品。“其一”云：“街头女儿双髻鸦，随蜂趁蝶学妖邪。东风也作清明节，开遍来禽一树花。”描写的是清明佳节人们户外游乐的情景。这首诗则表现了诗人自己清明时的情状，虽然抒写的不过是流连光景的闲情逸致，但也体现了诗人的个性和艺术风格。\n前首已经渲染了少女的天真无邪和东风的通晓人意，本首起句便从这两...", "authors": ["萧作铭"], "pressName": "上海辞书出版社"}]', '', 'center', 1547648512, '5c3ecd920b6160007096ff11', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641121, '临池心解', NULL, 39, 1, 7, 0, '朱和羹', NULL, 37004, '5c55a0bc44d904004bc909c5', '清', 'wen', '文', '', '', '凡欲学书之人，工夫分作三段，初要专一，次要广大，三要脱化，每段三五年火候方足。初取古人之大家，一人以为宗主。门庭一立，脚根牢把，朝夕沉酣其中，务使笔笔相似，使人望之便知是此种法嫡，纵有谏我、谤我，我不为之稍动，常有一笔一画数十日不能合辙者，此际如触墙壁，全无入路。他人到此，每每退步、灰心。我于此心愈坚，志愈猛，功愈勤，一往直前，久之则有少分相应，初段之难如此。此后方做中段工夫，取魏、晋、唐、宋、元、明数十大家，逐字临摹数十日，当其临时，诸家形模，时时引入吾胸，又须步步回头顾祖，将诸家之长默识归源，庶几不为所诱，工夫到此，倏忽五六年矣。至末段则无他法，只是守定一家，以为宗主，又时出入各家，无古无今无人无我写个不休，到熟极处，忽然悟门大开，层层透入，洞见古人精奥，我之笔底迸出天机，变动挥洒，回想初时宗主不缚不脱之境，方可自成一家，到此又五六年。
书路小道夫，岂易易哉！能用笔便是大家、名家，必笔笔有活趣。飞鸿戏海，舞鹤游天，太傅之得意也；龙跃天门，虎卧凤阙，羲之之赏心也。即此数语，可悟古人用笔之妙。古人每称弄笔弄字，最可深玩。临《乐毅论》十五日，深悟藏蜂之妙；廿五日，深悟回腕藏锋并用；作为两层悟入，癸巳临来仲楼《十七帖》，深悟转换之妙；至二十日，又悟侧左让右之诀。余廿岁外见东坡书，即知其为偏锋，亦时有此疑，不敢率论，直至癸巳秋，见黄山谷小品于蒋子久家，其中有东坡不善作草书，只用诸葛笔，又云举背作案，倚笔成书，不能用双钩悬腕，自视此说，二十年不可解之疑，一日豁然冰解矣！
凡欲学书名世者，虽学楷学草，然当以行为主，守定一家以为宗主，专心临摹，得其用笔俯仰向背，姿态横生之处，一一入微，然后别取一种临数月，再将前所宗者临三月，觉此一番，眼力与前不同，如此数转，以各家之妙资我一人，转阻转变转变，转入转入转妙，如此三年，然后取所主书摹写数月，则飞动之态，尽入笔端，结体虽雅正，用笔则奇宕，此时真书草书行书一时尽悟，可入古人之室矣！
行书点画之间须有草意，盖笔笔飞动，纯是天真横溢，无迹可寻，而有遒劲萧远之致，必深得回腕藏锋之妙，而以自然出之。其先习《黄庭》、《洛神》以端其本，其后习各种草书以发其气，其中又习数十种行书以成其格，安得不至妙境。行书之功十倍草书。或曰古人有忙中不作草字，奈何？曰：斯人斯时所未学者，草耳，未学则以为难，理或然欤？或曰：此说误。不及作草者，不及起草再誊真耳。学行书即能通真，学真书不能通行。以此知行书之功不小。
锺太傅书，一点一画皆有篆隶之遗，至于结构，不如右军。格之凤翥龙蟠如张芝，如索靖，皆锺一家书，以右军视之，正如太羹元酒不复过而问矣！锺书须玩其点画，如鱼如虫如枯枝如坠石，其旨趣在点画之间，虽古却少变动，简却少蕴藉，于势之一字尚未尽致，若夫王则纯以势胜势，欹而反正，则又秘之又秘矣！
华亭少时，学李北海，又学米襄阳，于二家盘旋最久，故得李十之二三，得米十之六七。生平虽无所不临，而得力则在此。今后学董者，不得舍李米而竟取董也。盖以董学董终不是董。米中年方临颜。陈中丞好学书，元章授以提笔法，曰以腕抵纸，则笔端有指力，无臂力也。曰提笔亦可作小字乎？元章笑顾，小吏取纸书黼黻，赞笔划端严，字如蝇头，而位置规模皆若大字，因请其法。曰：无他，惟自今以往，每作字时，不可一字不提笔，久之自熟矣！
八法转换，要笔笔分得清，笔笔合得浑。所以能清能浑者，全在能留得笔住。留笔总在能换处，见之转换者，用笔一反一正也，此结构用笔也，即古人回腕藏锋之秘，不肯明言。所谓手授口诀者，试问笔如何能留由，先一步是用腕力，腕力用得不坠之时，方才用留，笔笔既留矣，如何能转，曰，即此提笔之果，能提笔，然又要认得换笔，自然笔笔清，笔笔浑。其法贵在窗下用熟，及临书时，一切相忘，惟有神气飞舞而已。所谓抽刀断水，断而不断是也。观舞剑而悟者，张旭也，斗蛇而悟者，文与可也。舞剑斗蛇最得古人用笔之妙，临来仲楼所刻《舞鹤赋》五年，字体始定。用笔四处，不可不留心，如出也收也放也转也。
余虽得元宰嫡传，初学书时，只临肥本《兰亭》，三年不辍，又不敢易他贴。介子尝笑其拙。三年后方临董书，旋临《官奴贴》，又稍涉坡仙北海，旋弃之，遂转学杨少师《乐志论》，又复有悟，但嫌其结构谨严，无疏散之致，又以《舞鹤赋》为主，如此二年，遂临二王全帖十册不停手，不下座者，七月及临毕。之后作字更拙陋，无一笔如意。余私心恨之，乃掷笔不敢作书者数月，后又猎心复萌，取旧日所临再虚心奋入，觉此际较从前大有不同，每一字中，又开无限法门，与我相瞻于静对之际，若以精微相合者，然后知古人之妙，未敢轻示后人，又必待后人有一分眼力，则见一分，有十分则见十分也。盖每字有数层悟入者，余乃知之又敛。我胜气淡，我妄心临颜、柳、欧、虞而寝食于褚者，数月于宋之四家，元之一家，明之诸家，皆无所不窥，而独以米老为最，又取从前诸帖，时时拈起，回旋往复屈指计之，不知费几许几月矣！
乙巳春，过昆陵，见王双白，双白见余书静正因偏，告同人曰：此似董而深于少师之法者，元宰之后一人也。因劝余，不必泛临各家，当以董为主，间入少师之法，已足成家传世也。自是始专业华亭，誓以终老。双白髫年，即从董先生游，今六十余矣。董历游南北，双白多从之，故笔法精深，自谓得不传之秘，又亲书三十二字授余，其中有“侧笔取势，晋人不传之秘”十字。余初见以为不然，盖势之一字，余未深明，然每从诸家之说，以为未有不从中锋而得者，今日侧笔，胡为乎第？余从事于此有年，惟此一势字未了得，毋中锋之过乎。归来临帖数百字试双白传法，犹未了解此势字。初秋一病，淹留至十九日不愈，即起坐亭中，见风吹竹叶相迎相亚，忽迫忽避，恍有所得，觉前日半解半阻，至此神悟顿开，涣然冰释矣！羲之云，执笔在手，手不知运，运笔在腕，腕不自执。此四句贵先讲明。透观此语，转腕之法贵矣。次选临古帖，择其佳者摹之，所贵识得弃取，次折笔点画之间一一折开，看其起止，法熟后自臻神化。以上五条乃元宰先生临池妙诀。
此外，侧笔取势，晋人不传之秘也。侧笔取势者，于结构处一反一正。所谓锋锋相向，此从运腕得之。凡字得势则活，得势则传。徐欣二字，让左侧右可悟势欹而反正。永兴抽刀断水，自谓于道有悟，及舞剑斗蛇龙蟠凤翥诸法，一以贯之矣！又，前人诗云：舵楼一夜雨催诗，果有蛟龙起墨池，悟得将军舞剑势，分明草圣折锋时。“势”字最妙侧笔取势，言其书画有锋，势欹而反正也。
丰南隅《考功》云：双钩悬腕，让左侧右，掌虚指实，意前笔后。此十六字，古人所传用笔之诀也。双钩悬腕，食指中指圆曲如钩，节与母指相齐，而撮管指尖则执笔，挺直大字，运上腕，小字运下腕，不使肉衬于指；让左侧右者，左腕让而居外，右腕侧而居中，当使笔管与鼻准相对，则颌下无欹斜之患；掌虚指实者，指不实则颤掣无准，掌不虚则窒碍无势，三指撮齐，上俯仰，进退往复，垂缩刚柔，曲直钩环，纵横转运，无不如意，则笔在画中而左右皆无病矣；若夫意前笔后，工夫熟后，方可臻也，非纸成堆，笔成冢，安能有此神化。此南隅论临池家法，矜为神妙。以余观之，只是搦管法，至所以运笔并未之及，况让左侧右，注解总非耶？或曰让左侧右，毕竟如何，此拗腕法也，亦只向右边之一法耳。
《六书》象形、会意、谐声，指事转注假借，发笔处、收笔处、转笔处皆有口授妙诀。又起不孤，伏不寡，亦双白妙语。陈眉公执笔撮于指尖，横担又斜又扁，不肯对客作书，恐人盗去笔法，此与古人执笔稍异。右军执笔向内，大令执笔向外，鲁公执笔真正中锋，今持其墨迹，向日中照之，划中微有一线，其色更黑，画画皆然。三人执笔虽不同，然皆悬腕、悬肘。董先生学大令，邹虎臣则全仿鲁公。
董先生于明朝书家不甚许可，或有推祝枝山者曰，枝山只能作草，颇不入格。于文徵明，但服其能画，于米万钟则更唾之矣。于黄邓稍蒙许可。董用羊毫，其头甚长，约一寸七八分，又略丰美。所谓毫毛茂茂，但笔笔尖耳！用之写小楷、小行或微杂紫毫。若匾额宜用羊毫，字大者，绝不用棕及猪毫。匾额横字，书宜长瘦，不宜扁阔。直竖匾额，高悬七八丈者，上字宜微大，下字宜微小，大字宜笔笔用力，黑多白少，言用笔宜肥也。
凡写字，先小字后大字，先缜密后纵宕，理所必然。王觉斯字，课一日，临帖一日，应请索，以此相间，终身不易。大抵临摹不可一日间断耳。觉斯字，一味用力，彼必误认铁画银钩，所以魔气太大。先生每云，吾书无他奇，但姿态高秀，为古今独步耳。心忘手，手忘笔，笔忘法，纯是天真潇洒。邹虎臣初学书最服膺董先生，及双钩悬腕三年而后成之。又邹虎臣评“宋四家”书，蔡曰嫩，苏曰俗，黄曰野，米曰贱，以其偏旁欹斜鲜庄雅之度耳。
毗陵有“束第”二字，经一尺五六寸，乃元宰书，真得势字。元宰尝云，余学三十年，悟得书法而能实证者，在起倒收束处耳，过此一关，虽右军父子亦无奈何耳！
转左侧右乃右军字势。所谓迹似欹而反正者，世人不能解也。字之巧处在用笔，尤在用墨。然非多见古人真迹，不足与谈此窍也。盖用笔之难，难在遒劲，而遒劲非怒笔木僵之谓。乃如大力之人，通身是力，倒辄能起，此惟褚河南虞永兴得之，须悟后始知余言也。颜平原屋漏痕、折钗股，谓欲藏锋，后人不识，遂以墨猪当之，皆成俗笔。痴人前不得说梦，欲知屋漏痕、折钗股，当于圆熟处求之，未可朝执笔而暮合辙也。
吾学书在十七岁时，先是吾家仲子名传绪，与余同试于郡，郡守以余书拙置第二，自是始发愤临池矣。初师颜平原《多宝塔碑》，又改学虞永兴，以为唐不如晋，遂专仿《黄庭经》及锺元常《宣示表》、《戎辂表》、《丙舍帖》，凡三年，自谓偪古不复，以文徵仲祝希哲置之眼角比。游嘉兴，得亲观项子京家藏古人真迹，又见右军《官奴帖》于金陵，方悟从前妄自标许，譬如香岩和尚，一经洞山问倒，愿一生作粥饭僧，余亦愿焚笔砚矣。然自此，渐渐有心得，今将二十七年，犹作随波逐流书。虽翰墨小道，其艰如此，况学道乎？
庚戍二月二十日华亭论书。内度景有历代内府玉宝及历代名人图章，又有一长印云：“玉皇殿上掌书仙。”此七字甚俗，然朱色如新，是亦一奇。观其语，疑宋徽宗所用之物也。古洲藏此神物，提督马进宝欲得之，以为进京入贡之用。古洲索价虽三千金，亦权意终无售意也。马价六百金，古洲不应。有人献计于马，遂以暗通海上郑成功为名，发兵黑夜围古洲宅，擒置于狱，凡家之所藏尽为马有，不独内景经也。又馈金珠乃得免。后马自京师还，召古洲一饭而已。刘玉少家藏眉公真迹甚多。余昔婆娑其下，见一白纸，便面，横书“闲挥白羽扇”五字，此款极新。山谷小品云：心能转腕，手能转笔，书字便如人意。观眉公此书，方知古人工书无他奇，但能用笔耳。大令草书淳古，殊近伯英，论者以右军草入能品，大令草入神品。余以右军父子草书比之，文章右军似左氏，大令似庄周，似右军者，惟颜鲁公，杨少师仿佛大令耳。山谷谓《洛神赋》非王子敬书。以字格笔力去之太远，乃米宣猷书。山谷诗云：小字莫作痴冻蝇，乐毅论胜遗教经，大字无《瘗鹤铭》，隋人作计终后人，自成一家始逼真。然适能作小楷，亦不能摆脱规矩。客曰：子何不舍子之冻蝇？余无以应，因知此技非得不传之秘者，未易易也。凡欲作书，先端坐静思，随意所适，言不出口，气不盈息，沉密寡默，如对至尊，则无不美也。褚河南印印泥，张长史锥画沙，颜太师屋漏痕、折钗股，怀素飞鸟出林惊蛇入草，可以悟入也。
肥字须要有骨，瘦字须要有肉。字美观则不古，初见之使人甚爱，次见之则得其不到古人处，三见之则其不合者盈眼矣。故观今人之字，如观文绣，观古人之字，如观钟鼎，行行须求合法，字字须求生动。
《淳化阁帖》初刻系枣版，银定拓。余友吴天定为余父述古公门人所居，又相怜。余朝夕得把玩后，湖广胡天骝出一册见示，乃二王草书，生动变化，余一见即知为潭帖，在淳化之上。观其后款，果然为二王草书。邢子愿得力于此。淳化秘阁续帖内欧阳太子率更、李太白皆极妙。太白字，天真豪放，逼似其为人，云得力于南唐李后主七法。余见董先生所刻戏鸿堂、宝鼎斋、来仲楼，书种堂正续，二刻鹪了瓴、红绶轩、海鸥堂、青来馆、蒹葭室、众香堂、大来堂、研庐帖十余种，其中惟戏鸿堂、宝鼎斋为最。先生平生学力皆在此二种，其余诸帖，研蚩各半，而最劣者，则青众香也。笔意酷似杨彦仲，疑其伪作也。
《淳化阁贴》所见诸本，皆系钱文倩物。文倩囊涩，先质六册于一富贾，余四册，余尝见之。其中二王一册，笔法秀宕，下真迹一等，果俊物也，细玩却是潭帖。在明朝唯陕西肃王府翻刻石拓为最妙，谓之肃本。从宋拓原本双钩勒上石所刻，费数万，较今市本相去天渊焉。
明朝法贴，大刻有“郁冈斋”乃王氏所刻，“停云馆”乃文氏所刻。“郁冈斋”余童年曾见之，不复记忆。“停云馆”余见之于张玉立家，其中《黄庭》、《兰亭》刻有多种，而帖中所载宋、元诸家最详。又涿州冯相公所刻“快雪堂”，亦备载苏、米书，采摭颇精，于晋魏历代之书，十得四五耳。至于董先生所刻“戏鸿堂“、“宝鼎斋”，临摹历代大家及自书题跋，精妙绝伦，近则可掩“郁冈斋”，远则踞诸《淳化》各种名帖之上，诚罕观也。
余见二王帖十卷，首幅刻右军、大令二像，前六卷皆右军书，后三卷皆大令书，共一百七十余页，末一卷皆名贤题跋，乃金坛李氏所刻。李为元、明两朝世家，故能办此。余曾不停手临七月余，后以乏米，质之张氏，得六星后未能赎，可叹耳！
二王有《甲戍帖》，在《淳化》之上。宜兴蒋如奇，号邃初，在扬州盐商家得之，价值千金。蒋与刘馀佑同年，蒋死，其子中落，适刘子名芳烈者，为镇江太守，蒋子修谒刘，请看不还，以北寄为辞，及蒋归，然刘所赠不下数百金也，后数年，蒋游京师谒馀佑，又赠数百金。蒋遂不敢言，至今竟为刘氏所有。
米南宫对宋仁宗曰：“蔡京不得笔，蔡卞得笔，而乏逸气，蔡襄勒字，杜衍摆字，黄庭坚描字，苏轼画字，臣刷字。”
余学书十六年，方悟得势字，至二十七年，方悟得三折笔锋。今人把笔无几时，便思挥屏扇纤素，开口便轻议前贤，只是不自知丑态耳。历代名家，各有妙悟，如孤蓬自振，惊沙坐飞，如飞鸟出林，惊蛇入草，如折钗股屋漏痕、锥画沙、印印泥，如两峰出云，忽然自合，如见舞剑器，如见道斗蛇，如闻嘉陵江声，乃于道字方有悟，抽刀断水，总只悟得个势字，是取势又兼用笔，其余三折锋之说，自卫夫人及羲、献而后无有问途者，岂知之，固秘之耶。抑得势即三折笔耶，可以不言耶，妙极！
落笔要有疏宕纵逸之气，凡作字时，便存此想，不可忽略，然必在极熟之后，笔忘手，手忘笔，方能臻此三折笔法。
元宰以争座位为颜书第一，为其字相连属，诡异飞动得于意外，最为深思。
学书之人先须笔笔能到古人，及至到处，则须劈破天荒自成一家。秦少游绝爱政黄牛书，问其笔法，政曰：字，心书也。着意则不佳，故每求儿童书以观其神气。
余学书在戊子元旦至甲申二十七年，临摹古帖备极苦心，虽时与古人盘旋，然堂奥未窥也。壬子腊月回山西陈家集，晴窗之下，偶临元宰禅悦一则，忽悟得变化笔法，然非口授，亦不能透彻耳。
凡临贴到数月之后，工夫沉密则平日笔意反为法所缚，动笔辄更拙滞，不得如意，如须换一两种帖，庶前之所临，活变生动，从不经意处潇洒而出。临小字是日，不得为人写大字，临大字是日，不得为人写小字，若转换数日笔意飞舞，厥迹既佳，大小亦可任意矣！
余十六岁时，过金陵，侄孙直儒家见其五百金所购欧书《乐志论》墨迹，余极爱之，因屡愿习此种，又苦其难弃前学，心识其法，五十二年未尝语人，后传李锡奇、乐继武及明晋卿子，名观者共传三人焉。在直孺家见颜鲁公《争坐位》墨迹，在唐版纸上无一字涂抹遗漏，与世所传草稿不同，字形瘦劲奇变，踊跃生动，如龙眼大，后幅并无人题跋，只有数行落年月姓名，但云是鲁公当日誊清，上之当事者，历代藏之。粤西荔波县瑶蛮洞中，传为世宝。万历末，有浙西顾姓者，官于其地，诱而得之，藏于其家。天启间转入吴门韩某之手，直儒用八百金购得之。此卷华亭且未之见，况前此书家乎？宜其题跋之无人也。余得华亭门人传法，眼能小具别鉴，故知其为真迹也。
镇江曹次师家藏苏、米真迹，来扬求售。米之用笔，顿跌清古，与世所传真壤十纸，相去天渊，即较之方圆庵《张志孝碑》，亦不相类。乍视之，不知为米书。米老儒古帖，结构盘桓，气魄雄浑，笔意磊落。王双白云：明朝只有一大家，董元宰是也，下此都是名家。总明朝书家论之，可与唐宋匹者，一邓太素，二邹衣白，三倪苏门，四陈眉公，盖太素得力于米而天姿古劲有屈铁之势，全以骨胜，所少者细筋，又无变化，新新之态。至于邹书则中锋悬腕，荧迥刚劲，但拘于颜法，又时伤瘦硬，未能变化耳。若倪书，笔法秀逸，从董脱胎，于历代之法蕴蓄宏深，而出之简远，不似他人着力。陈眉公用笔甚活，自成一家，能于紧处用藏锋，其结构如松柯掩缭，有骨有趣，从苏脱胎，一毫不背。此四人皆亚于董，正是孔门有四哲耳。
凡用新笔，以滚水洗毫二三分，胶腥散毫为之一净则刚健者，遇滚水必软熟，与笔中柔毫为一类，后以指攒圆，且不可令曲，听干三四日后，剔砚上垢，去墨腥，新水浓研，即以前笔饱醮，仍深二三分，不可濡水，随意作大小字百余个，再以指攒圆，直候干收贮，量所用笔头浅深清水缓开，如意中式，然后醮墨，此华亭秘传也。又作字先开笔，开笔之法，先点清水，少歇又点，如此三次，令水透毫，然后取笔向干净砚上旋转捺之，令四面之毫，无一不和，又由浅入深，令四面毫之润处无一丝不齐，酌字大小，以分浅深。若临米，纵小字亦须深开，运用轻重方能随意。若写毕，亦另有秘传。
凡作字时，几上当安笔七八枝或十余枝，若用笔少不如意即弃去另换一枝，勿惜小费致留恶札于世相传。善书者不择笔，此英雄欺人语也。
凡书字，墨须新磨，重按缓转，则汁细色鲜，书笺纸宜用烟墨，书宣纸宜用胶墨。书熟宣胶墨与烟墨同研乃佳。若纯用烟墨，一经裱后，则墨色晕出，字迹模糊矣。研墨成后，必须令其停十余分钟，乃取笔醮写之，则光彩异常。又，墨须浓，笔须健，以健笔用浓墨，则作字有力而气韵浮动。又作字须有胆，胆大则悬腕自足，胆小虽悬肘不成。
凡书字，自运在服古，临古须有我，两者合之则变美，离之则两伤。临古须要无我，一有我便是已意，必不能与古人相消息。摄天地清明之气，入指腕间，方能与造化相通，而尽万物之变态，然非穷极古今，一步步脚踏实地，积习久之，纵横变化无适不当，必不能地负海涵，独扛百斛。故知千里者跬步之积，万仞者尺寸之移。孙虔礼云，察之者尚精，拟之者贵似。凡临古人，始必求其甚似，久久剥换遗貌，取神则相契，在牝牡骊黄之外，斯为神似。宋人谓，颜字学褚，绝不相似。此可悟临古之妙矣！
凡临古人，始在能取，继则能舍。能取易，能舍难，然不能取无由能舍。善学柳下惠，莫若鲁男子，于此可悟舍法。非折骨还父，折肉还母，何从现得清静法身来。余忆七岁时，读书东门王忆峰家，王称道董先生之学，余即慕其为人。余十七岁时，得笔法于南都。所谓手授口诀者，于此始知之。十九岁得“宝鼎斋”初拓，甚爱之。是时购先生真迹，然余以沉溺八股，既鲜闲暇，又生畏惮，是以不果学。乙酉之变，余家片纸只字都无存者，避乱湖边，教授阅三四年，复购数种。丙戊春，学永兴真书，两月即弃去，仍临肥本《兰亭》，直到戊子元旦，始落笔志毕生。于此年三月廿四日临《所堂大罗经·止静太古》一则。岁月蹉跎，忽惊老迈，古之书家，自成童即能把笔，如大令六七岁受笔法，一到壮年，名满四方。子昂三十八岁已官就名成。余年四十八始有此志，不知何年得入古人之室，亦帷有立志坚定，工夫不懈，庶几有成耳。
折须提笔，转须捻笔，折乃圆，圆乃劲。
习古人书，必须专精一家，至于信手触笔，无所不似，然后可兼收并蓄，淹贯众有，亦决不能自成一家。若专此一家，到得似来，只为此一家所盖，枉费一生气力。又临古须透一步，翻一局，乃适得其正。古人言，智过其师，方名得髓。此最解人语。
人必各自立一家，乃可与古人相抗。魏晋迄今，无有一家同者，非由风会迁流，亦缘规模自树。仆常谓，使右军在今日，亦学不得，正恐为古人所盖耳。作书须笔笔有原本乃佳，一笔杜撰便不成字。作书不可不通篆隶，今人作书，别字满纸，只缘其末，未详其本，随意写写耳。通篆法则字体无差，通隶法则用笔有则，此入门第一正步。
东坡论唐六家书，永禅师骨深称体兼众妙精能之至，反造疏淡。欧阳率更妍紧拔群，尤工于小楷。褚河南清远潇洒，微杂隶体。张长史草书颓然天放，略有点画处而意态自足，号为神逸。颜鲁公雄秀独出，一变古法，后之作者，殆难复措手。柳少师本于颜而能自出新意，其言心正则笔正者，非独讽谏，理固然也。东坡于唐代变迁之迹论之最精，而武断私造之字则置而不论也。北宋书家，东坡及山谷米襄阳大抵高际阔步，气韵轩昂，或诋其棱角怒张则失之过。蔡襄李时亦有声于时。宣和时徽宗留意书法，得杜唐稽一人书法不传。高宗南渡，力图恢复，乃作评书之文，为翰墨志，玩物而已。大旨可宗，惟在羲、献，彼何不援羲之之言曰：区区江右，固足以寒心乎！后之学书者，当思有益于国家社会乃可。
宋以后书家，变迁最异者为洪武体或谓之宋字，横细纵角，字体方正，施之刻书，良有裨益，惟文人习之者，除碑版亦无用之者，仅为书手（原为手民）专家之学也。
凡写榜书，须我之气足盖世，虽字寻丈，只如小楷，乃可指挥如意，有意展拓，即气为字所夺，便书不成。榜书每一字中，必有两笔不用力处，须安顿使简淡，令全字之势，宽然有余，乃能跌荡尽意，此正善用力处。
凡作榜书，不须拘结构长短阔狭，随其字体为之，则差参错落，自成法度，一排比令整齐，便是俗格。
凡榜书，三字须中一字略小，四字须中二字略小，若齐一则高悬起便中二字突出矣。又榜书结构体宜少长，高悬则方，若结体太方则高悬起便扁阔，而势散矣！
今楷书之匀圆丰满者，谓之馆阁体，类皆千手雷同。乾隆中叶后，四库馆开，而其风益盛。然此体唐宋亦有之。段成式《酉阳杂俎》诡习内载有官楷手书《沈括笔谈》云：三馆楷书不可谓不精不丽，求其佳处，则死无一笔是矣。窃以谓此种楷法为书手则可，士大夫亦从而效之，何耶？清朝若沈文恪、姜西溟之在圣祖时，查詹事、汪中允、陈弈禧之在世宗时，张文敏、汪文端之在高宋时，庶几卓尔不群矣。至若梁文定、彭文勤之楷法，则又昔人所云堆墨书矣！
凡写对联，落己名不宜太低，太低则吊脚不合格。若拓图章则宜留地步，不拓则少低亦可，总以合式为上乘。又首联宜站左边，对联宜站右边，以便路款。又凡字格宜上紧下松，留有余地，步且见人福泽。
定武《兰亭》石刻，出自率更，若以为率更所书者，余偿疑焉。太宗於此叙爱之如此其笃也，得之如此其难也，既欲寿诸贞石，嘉彼士林，乃舍右军之真迹用率更之临本，殆不然矣！后见何延之《兰亭始末记》云：帝得帖，命冯承素、韩通政等各拓数本赐太子诸王，一时能书如欧阳、虞、褚诸公，皆临拓相尚，刘竦嘉话录云：兰亭序，武德四年入秦府，贞观十年始拓以分赐近臣。何子楚跋云：唐太宗诏，供奉临《兰亭序》惟率更令欧阳询自拓之文夺其勒石留之禁中，然后知定武本乃率更相拓而非其手书也。又《兰亭博议》云：欧公集古不录定武本，自山谷喜定武本，于是士大夫争宝之。
欲学书者，必得传授。明季华亭董公其昌传执笔法于其邑人沈公荃、逮国朝传王公鸿绪，鸿绪传张公照，照传何公国宗，国宗传金陵梅君钜。余学书三十年后，始缘钜得其传，先是张公秘其法，不授人，一日同何公坐狱中，何公叩之再三，乃告之，仍嘱勿泄。及出狱，何公偏语人梅君，因得之。及张公总裁某馆梅君誊录馆中见公作书，狐裘袖拂几上。张公曰，观吾袖拂几乎，腕实悬而动也。于此可以知书法之秘诀矣，亦贵学者有恒耳。', '', '', '', NULL, '', 'indent', 1549144594, '5c55a188c05a800056d8c03a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641886, '黄鹤楼', NULL, 1, 408, 0, 1, '贾岛', NULL, 10153, '57b928ae8ac2470062e0e27d', '唐', 'shi', '诗', '', '', '高槛危檐势若飞，孤云野水共依依。
青山万古长如旧，黄鹤何年去不归。
岸映西山城半出，烟生南浦树将微。
定知羽客无因见，空使含情对落晖。', '', '', '', NULL, '', 'center', 1554809390, '5cac11aca3180b0068219531', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641195, '赠画师', NULL, 24, 23, 1, 0, '鲁迅', NULL, 10118, '57b93fd70a2b58005c946328', '当代', 'shi', '诗', '', '', '风生白下千林暗，雾塞苍天百卉殚。
愿乞画家新意匠，只研朱墨作春山。', '这首诗作于1933年1月26日，是书赠日本画家望月玉成的。这位画家为搜寻作画题材，远道而来。鲁迅当时一方面目睹日军不断的侵略，而国民政府不断的军事、文化“围剿”，中国满目疮痍，焦土千里的景象，使他感到悲愤；另一方面又对中国抗战胜利充满信心；有感于此创作了此诗。
这首诗的前两句，作者用象征的手法描写了由来自当时民国首都南京的各项政策所造成的国危时乱、民生凋敝的时局。后两句是希望画家有新的艺术创见，以用来描画明媚秀丽的中国山水，使能得见光明灿烂的前途的中国。诗虽是寄寓画师，但含意深远，寄托无穷，表达了作者对国家和民族未来的信心。', '画师：指日本画师望月玉成。
白下：白下城，故址在今南京金川门外。唐武德九年（626年）移金陵县治于此，改名白下县，故旧时以白下为南京的别称。
百卉（huì）：百种花草。
殚（dān）：尽，指枯萎。
意匠：陆机《文赋》：“意习契而为匠。”指艺术创造上的构思。
研：磨，旧时写字作画，须将墨磨于砚中。
朱墨：朱为红色，墨为黑色，均为写字作画的颜色。
春山：朝气蓬勃的山。', '从南京城刮出的阴风使千林万树暗淡无光，沉沉雾气遮天蔽日使百花枯萎凋零。
希望画家构想出新的意境，只管用鲜丽的颜彩描绘春光明媚的山色。', NULL, '北京师范大学中文系教授张紫晨：“这首《赠画师》，立意不俗，构思新巧，画中有诗，诗中有情。”
中国鲁迅研究会副秘书长郑心伶：“这首诗意境深远，画外有画。纵使“风生”，“雾塞”，“千林暗”，“百卉殚”，却还有肃然不屈的“春山”。这里面蕴藏着多少希望和理想！”', 'center', 1550055818, '5c638908c05a800054befbb6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641222, '从斤竹涧越岭溪行', NULL, 1, 135, 2, 1, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E4%BB%8E%E6%96%A4%E7%AB%B9%E6%B6%A7%E8%B6%8A%E5%B2%AD%E6%BA%AA%E8%A1%8C/1067782?fr=aladdin', '', '猿鸣诚知曙，谷幽光未显。
岩下云方合，花上露犹泫。
逶迤傍隈隩，迢递陟陉岘。
过涧既厉急，登栈亦陵缅。
川渚屡径复，乘流玩回转。
苹萍泛沉深，菰蒲冒清浅。
企石挹飞泉，攀林摘叶卷。
想见山阿人，薜萝若在眼。
握兰勤徒结，折麻心莫展。
情用赏为美，事昧竟谁辨。
观此遗物虑，一悟得所遣。', '《从斤竹涧越岭溪行》是南朝宋诗人谢灵运创作的一首五言古诗。这首诗由两大部分组成。第一部分十二句以记行写景缴足题意，其中前四句先交代动身启程的时间，中四句接着记叙沿山路曲折前行，翻越丛岭，移步换景。后四句则描写“溪行”，弯曲的水流，回环的溪路。第二部分十句用山行的想象和感悟来充实全诗，前六句写山中景色以及由想象落入现实的转折，使诗的意境更加生动充实，后四句发出感悟人情可因观赏景物而获得美感。这首诗就记行、写景、想象、领悟层层写来，次序井然，结构严整，是谢灵运诗成功借鉴辞赋创作经验的作品。', '斤竹涧（jiàn）：溪水名。今浙江绍兴县东南有斤竹岭，离浦阳江约十里。题中之岭即此斤竹岭，而溪涧或在此岭山下。
诚：确实，原本。
曙：黎明。
谷幽：山谷深邃而阴暗。
犹：仍然，还在。
泫（xuàn）：水珠欲滴的样子。
逶迤（wēiyí）：道路弯曲而漫长的样子。
隈隩（wēiyù）：山崖转弯的地方。
迢递（tiáodì）：遥远的样子。
陟：登高。
陉岘（xíngxiàn）：山脉中断处叫陉，不太高的山岭叫岘。
厉急：渡过急流。厉，“濿”之省文，穿着衣服涉水。
栈：栈道。在山上用木材架成的道路。
陵缅（miǎn）：凌空面对着高深的山谷。
川渚（zhǔ）：这里指河水。
屡：每每，多次。
径复：时直时曲，弯来拐去
乘流：随着溪流。
玩：欣赏的意思。
回转：倒回来转过去。
苹（pín）萍：都是水草，浮生水面。苹大萍小。
沉深：指深沉的溪水。
菰（gū）：即茭白。是生长在浅水中的植物。
蒲：昌蒲。是生长在浅水中的植物。
冒：覆盖。
企：同“跂”，举踵。
挹（yì）：舀。
叶卷：即卷叶，初生尚未展开的嫩叶。
山阿人：指诗人所仰慕的高人隐士。
薛萝：薜荔和女萝。出于屈原《九歌·山鬼》：“若有人兮山之阿，披薜荔兮带女萝”。
勤：企望。
麻：疏麻，又叫神麻，一种香草。出于《九歌·大司命》：“折疏麻兮瑶华，将以遗兮离居。”
用：以
昧：不明。
观此：观览沿途的景物。
遗：弃，抛开。
物虑：尘世问的各种顾虑。', '从猿鸣声中可以知道已经是黎明了，但在幽深的山谷间却还看不到阳光。
山下的云方才还是合在一起的，野花上面的水珠仍然晶莹圆转。
沿着弯弯曲曲的道路前进，又登上遥远的山路。
通过溪涧也用不着脱衣服，爬上栈道就可以凌空面对高深的山谷。
溪谷沙洲时直时曲，弯来拐去，顺着溪流游玩，倒回来转过去。
水草漂浮在深沉的水潭上，水生植物从清浅的水泽里伸出枝叶来。
在石上提起脚跟，用脚趾做为全身的力点，去挹取飞溅的泉水，高攀丛林中的树枝，去摘取那还没有舒展开的初生卷叶。
本想见到山里的高人隐士，却好像看到山角里有穿着薛荔衣，系着女萝带的“山鬼”。
手握兰花希望赠给知己，但却无法寄到，所以常常是忧思结于心中，折了疏麻却无从投赠给所思念的人，所以心愁莫展。
自己所真心欣赏的就是最美的，何必还要去分辨其真假呢？
看到这样动人的风景就会有所领悟而忘却世俗，排除一切烦恼。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb203048e64fbd9c6ce", "shortContent": "这是谢灵运一首典型的山水诗。山水诗大抵有两种写法。作者以某一风景胜地为据点，静观周围山水景物，这是一种写法；另一种，则是作者本人在旅途之中，边行路边观赏，所见之景物是不断变化的。此诗即属于后者。\n谢灵运本身写过一篇《游名山志》，文中提到“斤竹涧”。后人或据今绍兴东南有斤竹岭，去浦阳江约十里，以为斤竹涧即在其附近；近人余冠英先生在其所注《汉魏六朝诗选》中则以为此涧在今浙江乐清县东，而乐清是在永嘉附近...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}]', '上海古籍出版社资深编辑叶笑雪《谢灵运诗选》：“末尾两句，说在静观佳景时，可以排除物虑，只须在这个基础上提高一步，便可达到向郭所说的‘无所不遣’的境界了。又把清晨出游的现实的我（诗人），导往玄气絪蕴的玄学之途。”
耶鲁大学东亚语言文学系教授孙康宜《抒情与描写：六朝诗歌概论》：“从强烈的抒情转向一种使个人感情客观化的哲理性结尾，是典型的道家态度。对谢灵运来说，山水原本是用来放纵感情的，然而其诗写到最后却远远避开，不再让自己充当抒情主体。这是因为他在更多的情况下，是用酷似道家的语言来作诗歌结尾的缘故。”', 'center', 1553684992, '5c6b8c4d44d90419c121d999', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641230, '送储邕之武昌', NULL, 1, 1052, 0, 1, '李白', NULL, 10041, '57b8e7ac165abd0054bf3de3', '唐', 'shi', '诗', 'https://baike.baidu.com/item/%E9%80%81%E5%82%A8%E9%82%95%E4%B9%8B%E6%AD%A6%E6%98%8C/10839630?fr=aladdin', '', '黄鹤西楼月，长江万里情。
春风三十度，空忆武昌城。
送尔难为别，衔杯惜未倾。
湖连张乐地，山逐泛舟行。
诺为楚人重，诗传谢朓清。
沧浪吾有曲，寄入櫂歌声。', '《送储邕之武昌》是唐代大诗人李白创作的一首五排。此诗开头四句主要是说因送朋友而引起对武昌的怀念，中间四句是写与储邕的惜别之情，结尾四句是送别时的祝托语。全诗以古风起法运作排律，自然流畅地表现了诗人对武昌的深切怀念和对储邕的深情厚谊，风格飘逸秀丽，自然浑成，情趣盎然。', '储邕（yōng）：李白友人。武昌：唐属江南西道鄂州，即今湖北省鄂城县。
黄鹤：即今武汉市武昌蛇山之黄鹤楼。《潜确居类书》：”黄鹤山，在武昌府城西南，俗呼蛇山，一名黄鹄山。昔仙人王子安骑黄鹤憩此，地志云：黄鹤山蛇行而西，吸于江，其首隆然，黄鹤楼枕焉。其下即黄鹤矶。“西：一作”高“。
张乐：奏乐。《庄子·天运》：“帝张咸池之乐于洞庭之野。”谢朓《新亭渚别范零陵云》：“洞庭张乐地，潇湘帝于游。”
诺（nuò）为楚人重：司马迁《史记·季布列传》：“楚人谚曰：‘得黄金百斤，不如得季布一诺。’”
诗传谢朓（tiǎo）清：谓谢朓诗以清丽著名。《南齐书》：”谢朓善草隶，长五言诗，沈约常云：‘二百年来，无此诗也。’“
沧浪吾有曲：沧浪即《沧浪歌》。《孟子·离娄上》：“有孺子歌曰：‘沧浪之水清兮，可以濯吾缨。沧浪之水浊兮，可以濯吾足。’”又见《楚辞·渔父》。此言自己高洁其志，不与世同流合污。
棹歌：行船时所唱之歌。张衡《西京赋》：“齐栧女，纵棹歌。”', '黄鹤楼西天的月亮，长江万里的流水，那就是我的心，我的情！
春风三十多次去了又来，这些年里我徒然怀念着武昌城。
现在来送你，分别实难，举起酒杯不忍一下子喝空。
山崖追逐着流荡的行舟，湖水连着黄帝置乐的洞庭。
作为楚人，你最重视自己的诺言，你的诗也如谢朓一样清丽。
我也有一曲《沧浪歌》，一边行船，一边吟唱。', NULL, '《唐诗直解》：起四语韵胜，不比自佳。後亦流动，行雲流水，飘然不群。
《唐诗训解》：起语雄健，亦复自然，景物收入笔端如矢口唱出。
《汇编唐诗十集》：唐云：此诗音韵铿锵，俪偶参错，排律之变体，同时惟孟襄阳有然不可无一，不可有二。
《唐诗选脉会通评林》：逸度逸才，铿然合节。
《唐诗评选》：供奉体本非胜场，乃此一篇又一空万占，要唯胸中无排律名目也。衝口雲烟，无端萦绕。
《唐诗别裁》：以古风起法运作长律，太白天才，不拘绳墨乃尔！
《唐宋诗醇》：健笔凌空，如列子御风而行，冷然善也。
《李太白诗醇》：严云：起两句一字非类，而错揉成对，最新，不独情境之佳。', 'center', 1555497448, '5c6cc50a44d90419c133b2f8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641237, '大铁椎传', NULL, NULL, 19, 0, 1, '魏禧', NULL, 26265, '5858f403b123db00658dec92', '清', 'wen', '文', 'https://baike.baidu.com/item/%E5%A4%A7%E9%93%81%E6%A4%8E%E4%BC%A0', '', '庚戌十一月，予自广陵归，与陈子灿同舟。子灿年二十八，好武事，予授以左氏兵谋兵法，因问：“数游南北，逢异人乎？”子灿为述大铁椎，作《大铁椎传》。
大铁椎，不知何许人，北平陈子灿省兄河南，与遇宋将军家。宋，怀庆青华镇人，工技击，七省好事者皆来学，人以其雄健，呼宋将军云。宋弟子高信之，亦怀庆人，多力善射，长子灿七岁，少同学，故尝与过宋将军。
时座上有健啖客，貌甚寝，右胁夹大铁椎，重四五十斤，饮食拱揖不暂去。柄铁折叠环复，如锁上练，引之长丈许。与人罕言语，语类楚声。扣其乡及姓字，皆不答。
既同寝，夜半，客曰：“吾去矣！”言讫不见。子灿见窗户皆闭，惊问信之。信之曰：“客初至，不冠不袜，以蓝手巾裹头，足缠白布，大铁椎外，一物无所持，而腰多白金。吾与将军俱不敢问也。”子灿寐而醒，客则鼾睡炕上矣。
一日，辞宋将军曰：“吾始闻汝名，以为豪，然皆不足用。吾去矣！”将军强留之，乃曰：“吾数击杀响马贼，夺其物，故仇我。久居，祸且及汝。今夜半，方期我决斗某所。”宋将军欣然曰：“吾骑马挟矢以助战。”客曰：“止！贼能且众，吾欲护汝，则不快吾意。”宋将军故自负，且欲观客所为，力请客。客不得已，与偕行。将至斗处，送将军登空堡上，曰：“但观之，慎弗声，令贼知也。”
时鸡鸣月落，星光照旷野，百步见人。客驰下，吹觱篥数声。顷之，贼二十余骑四面集，步行负弓矢从者百许人。一贼提刀突奔客，客大呼挥椎，贼应声落马，马首裂。众贼环而进，客奋椎左右击，人马仆地，杀三十许人。宋将军屏息观之，股栗欲堕。忽闻客大呼曰：“吾去矣。”尘滚滚东向驰去。后遂不复至。
魏禧论曰：子房得力士，椎秦皇帝博浪沙中。大铁椎其人欤？天生异人，必有所用之。予读陈同甫《中兴遗传》，豪俊、侠烈、魁奇之士，泯泯然不见功名于世者，又何多也！岂天之生才不必为人用欤？抑用之自有时欤？子灿遇大铁椎为壬寅岁，视其貌当年三十，然大铁椎今年四十耳。子灿又尝见其写市物帖子，甚工楷书也。', '《大铁椎传》是清代文学家魏禧的一篇传记散文。作者因为不知道那个人叫什么名字，就用他的兵器“大铁椎”来代替。文中以细腻生动的手法，刻画了一位有识见、有气节、精武艺、识文墨，使用铁椎的大力士的“异人”的形象，描写出这样一个英雄人物，本可大有作为，在当时却所遇不合，无用武之地，只能去与响马决斗的可悲境遇，透露出作者对明朝亡国君臣的不满，抒发了他的亡国之痛，表达了作者希望有人起来“抗清复明”的爱国思想。', '大铁椎传：选自《魏叔子文钞》，有删节。文章是一篇传记，因为不知道这个人叫什么名字，就用他的兵器“大铁锥”来代替。
庚戌：1670年（康熙九年）。
广陵：扬州古名。
陈子灿：生平不详。
左氏兵谋兵法：指《左传》中记述战事的文字。
北平：北京。明初改元大都为北平，1403年（明成祖永乐元年）改名北京。此用明初名称。省（xǐng）兄河南：到河南探望哥哥。
怀庆：府名，今河南沁阳。
工技击：擅长武术。
七省：指河南及其邻近的河北、山东、山西、陕西、安徽、湖北七省。
少同学：青少年时代的同学。
过：访问。
健啖（dàn淡）：食量很大。啖，吃。
貌甚寝：相貌甚丑陋。寝，丑陋。
右胁：右腋下。
“饮食”句：谓椎不离身。不暂去：一会也不离身。
“柄铁”句：椎之铁柄可折叠环绕，如同锁链。练，通“链”。
引：伸长。
语类楚声：说话像楚地的口音。楚地，现为湖南、湖北一带，古为楚地。
扣：通“叩”，询问。
言讫（qì）：说完。
白金：银子。
鼾（hān酣）睡：熟睡。鼾，打呼噜。炕：用土坯搭制的床。
豪：豪杰。
强：（qiǎng）尽力挽留。
响马贼：结伙拦路抢劫的强盗，抢劫时先打呼哨，或放响箭，故称。
仇：怨恨，仇恨。
且：将。
期：约定。
能：有本领。
不快吾意：不能让我痛快搏斗。
与偕行：和（他）一起去。
慎弗声：小心不要出声。
觱篥（bìlì）：古代一种管乐器。用竹做管，用芦苇做嘴。汉代从西域传入。
环而进：围攻。
仆：向前倒下。
屏息：暂时抑制呼吸。屏，抑制。
股栗：两腿发抖。栗，战栗，发抖。
“子房”三句：谓大铁椎与汉代张良所得力士为一类人。子房，张良，字子房。秦灭韩，张良欲为韩复仇，后来找到一名力士，能举起一百二十斤重的铁椎，狙击秦始皇于博浪沙，但只击中副车（参看《史记·留侯世家》）。欤（yú），助词，表示疑问、感叹、反诘等语气。
陈同甫：南宋陈亮，字同甫，文学家，著有《龙川文集》、《龙川词》。其所著《中兴遗传》，为宋朝南渡前后大臣、大将、死节、能臣、能将各类人物立传，其中有侠士、义勇两门，人物类似大铁椎，所以这样说，以引出下文之感慨。
泯泯（mǐn敏）然：形容纷纷消亡。
壬寅岁：1662年（康熙元年）。
市物帖子：购物单。', '庚戌年十一月，我从扬州回家，与陈子灿同船。子灿时年二十八岁，爱好弄枪使棒，我给他讲授《左传》中的兵谋兵法时，趁机问：“你走南闯北，碰到过奇异之人吗？”子灿向我讲述了大铁椎的事，于是我写了《大铁椎传》。
大铁椎，不知是什么地方人。北平陈子灿到河南去看望他的哥哥，在宋将军家里遇见了大铁椎。宋将军是怀庆青华镇人，擅长武术，七省爱好武术的人都来向他学习，人们因他长得魁梧健壮，所以叫他宋将军。宋将军的徒弟高信之，也是怀庆人，力气大，擅长射箭，比陈子灿大七岁，是他小时候的同学，因此陈子灿曾经与他一同访问过宋将军。
当时座上有个饭量很大的客人，容貌很丑陋，右腋下夹着个大铁椎，有四五十斤重，吃饭以及拱手行礼时，一刻也不放下它。大铁椎柄上的铁链折迭围绕着，像锁上的链子，把它拉开有一丈多长。他很少跟人们交谈，说话像楚地（今湖南湖北一带）的口音。问他家乡在哪，姓甚名何，都不作回答。
我们在一起睡觉，到半夜，客人说：“我走了。”话音刚落，人就不见了。陈子灿见窗门都关着，就吃惊地问高信之。高信之说：“客人刚来时，不戴帽子，不穿袜子，用蓝手巾包着头，脚上缠着白布，除了大铁椎外，什么东西都没有携带，而腰带中裹着很多银子。我和宋将军都不敢问他。”陈子灿一觉醒来，侠客却已打着呼噜睡在床上了。
有一天，侠客向宋将军告辞说：“我当初听到你的名声时，把你当作英雄豪杰，然而你的武艺全不顶用，我走了。”宋将军竭力挽留他，他就说：“我曾屡次打杀拦路抢劫的强盗，夺取他们的财物，因此他们很恨我。我若久留此地，灾祸将会牵连到你。今晚半夜，强盗们正约定和我到某个地方决斗。”宋将军高兴地说：“我骑着马带着弓箭来助战。”侠客说：“不要去，强盗本领强且人又多，我想要保护你，就不能杀个痛快。”宋将军向来自以为了不起，并且也很想看看侠客的本领，就竭力请求侠客同往。侠客没办法，就带他一起走。将要到达决斗的地方，侠客送宋将军登上一座荒废无人的堡垒，说：“你只许观看，千万别作声，（以免）让强盗们发觉你。”
这时，鸡叫月落，星光照着空旷的原野，百步之内能够看见人。侠客骑马飞驰而下，吹了几声觱篥。一会儿，二十多个骑马的强盗从四面聚集过来，徒步行走背着弓箭跟在后面的有一百多人。一个强盗提着刀纵马冲向侠客，侠客大喊：“看椎。”挥舞起铁椎，强盗应声坠落马下，马头也被砸得碎裂。那伙强盗向前包围上来，侠客奋力挥舞铁椎左右猛击，强盗们连人带马栽倒在地，三十多人被杀死。宋将军屏住呼吸观看这场恶战，吓得两腿发抖，几乎从堡垒上掉下来。忽然听到侠客大声呼喊道：“我走啦！”尘灰滚滚，朝着东方飞奔而去。之后就再也没有回来。
魏禧评论说：张良找到了大力士，在博浪沙用铁椎捶击秦始皇，大铁椎大概也是那种人吧？老天生下有奇异才能的人，一定有用得着他的地方。但我读陈亮的《中兴遗传》，发现那些才智出众、侠义刚烈、雄奇卓异的人，无声无息地不能在当代显露功绩声名的，又为什么这样多呢？是不是上天降生的人才不一定被人任用呢？还是任用他们自会有一定的时机呢？陈子灿遇见大铁椎是壬寅年，看他的相貌应当是三十岁，那么大铁椎当时已有四十岁了。子灿又曾经看见他写买东西的单子，楷书写得非常工整漂亮。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed20b0f8fda55650615fc", "shortContent": "魏禧论文，主张“积理”、“练识”，写出“关系天下国家之故”（《宗子发文集序》）的文章。“积理”，指观察社会事理，以提高认识；“练识”，指在提高认识的基础上，获得过人的胆识。这是魏禧散文写作的重要理论。因此他的论文多有深刻见解，记叙文（包括传记在内）多有不平凡的寓意。\n《大铁椎传》属传记文，作者也增加了一些艺术的想象和虚构，塑造出一个丰满的侠客、大力士的英雄形象，透露了对社会现实的不满和人材不被世用...", "authors": ["李茂肃"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f840f8fda556506e444", "shortContent": "这篇小说写的是后母因虐杀前妻之子而遭果报的故事。这样的故事自古以来可谓屡见不鲜，说起来尽人皆信。而且人们的感情倾向十分鲜明，几乎无不同情弱子而痛恨恶母。文章对于后母陈氏虐待铁臼的事实用笔甚为简约，而对于铁臼亡魂复仇的情节则予以详写，并且通过一些细节描写的渲染，造成一种特定的复仇气氛。作品分三个层次写铁臼复仇的情况。首先是亡魂还家，登陈氏床痛斥陈氏，控诉陈氏罪恶，并声言已诉之于天，得天曹符来取铁杵，...", "authors": ["孙秀荣"], "pressName": "上海辞书出版社"}]', '清代张潮《虞初新志》：“篇中点睛，在三称''吾去矣’句。至其历落入古处，如名手画龙，有东云见麟、西云见爪之妙。“', 'indent', 1624487972, '5c710f64303f3900479a0e1d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641244, '书论', NULL, 22, 90, 1, 0, '王羲之', NULL, 10033, '57b8fc225bbb50005b7801ea', '晋', 'wen', '文', '', '', '夫书者，玄妙之伎也，若非通人志士，学无及之。大抵书须存思，余览李斯等论笔势，及钟繇书，骨甚是不轻，恐子孙不记，故叙而论之。夫书字贵平正安稳。先须用笔，有偃有仰，有攲有侧有斜，或小或大，或长或短。凡作一字，或类篆籀，或似鹄头，或如散隶，或八分；或如虫食木叶，或如水中蝌蚪；或如壮士佩剑，或似妇女纤丽。欲书先构筋力，然后装束，必注意详雅起发，绵密疏阔相间。每作一点，必须悬手作之，或作一波，抑而后曳。每作一字，须用数种意，或横画似八分，而发如篆籀，或竖牵如深林之乔木，而屈折如钢钩；或上尖如枯秆，或下细若针芒；或转侧之势似飞鸟空坠，或棱侧之形如流水激来。作一字，横竖相向；作一行，明媚相成。第一须存筋藏锋，灭迹隐端。用尖笔须落锋混成，无使毫露浮怯，举新笔爽爽若神，即不求于点画瑕玷也。为一字，数体俱入。若作一纸之书，须字字意别，勿使相同。若书虚纸，用强笔；若书强纸，用弱笔。强弱不等，则蹉跌不入。凡书贵乎沉静，令意在笔前，字居心后，未作之始，结思成矣。仍下笔不用急，故须迟，何也？笔是将军，故须迟重。心欲急不宜迟，可也？心是箭锋，箭不欲迟，迟则中物不入。夫字有缓急，一字之中，何者有缓者？至如“乌”字，下手一点，点须急，横直即须迟，欲“乌”三脚急，斯乃取形势也。每书欲十迟五急，十曲五直，十藏五出，十起五伏，方可谓书。若直笔急牵裹，此暂视似书，久味无力。仍须用笔著墨，不过三分，不得深浸，毛弱无力。墨用松节同研，久久不动弥佳矣。', '', '玄妙：深奥微妙。
伎：通“技”。
通人：谓学识渊博贯通古今的人。
志士：有高尚志向和节操的人。
存思：用心思索。李斯等论笔势：相传秦相李斯曾著《笔妙》论势：“书之微妙与道合，然篆籀之前不可得而闻矣。”
叙：记述。
篆籀：篆书及籀文。籀文，周代文字，即大篆。
鹄头：大雁的头。相传古代的一种书体。
详雅起发：详雅，安详温雅。详，通祥。起发，出发。开始提笔写字。
绵密疏阔相间：谓稠密开阔相间隔。指字的结体及章法安排，有疏有密，疏密相间，乃为佳作。
上尖如枯秆：上头尖锐像枯瘦的秸秆。
下细若针芒：下边细如针尖。
爽爽若神：爽爽，俊朗出众的样子。意为俊朗清新若神明气爽。
瑕玷：玉上的斑点或裂痕，比喻小毛病。
虚纸：柔弱的纸。
强笔：毫毛强硬的笔。
蹉跌：失势，相差。
不入：不合。
直笔：即纵笔，指用笔急率。
著墨不过三分：著墨不得超过三分。此意为着墨处不过笔十分之三，当保持笔毫的强力。
松节：松树结疤。因其中含有油脂，可使墨色更有光泽。', '书法，是种深奥微妙的技艺，如果不是学识渊博通达且有大志之人，是学不到手的。大抵作书必须用心思索，我看李斯等人论笔势的文章，及钟繇的书法，很有功力，我担心子孙们不能记取，故作此文，记述并加以讨论。
书法，贵在平正安稳。首先要会用笔，有偃有仰，有攲有侧有斜，或大或小，或长或短。但凡写一字，或类似篆籀，或类似鹄头；或有如散隶，或近似八分；或者如虫食木叶，或者如水中蝌蚪；或者如壮士佩剑一样雄健有力，或者如妇女一样婉媚纤丽。书写要先构筑筋力，然后才可装束，必须注意安详温雅，疏密相间。作点画须悬手，作横画收笔时要先下按，然后拖笔出锋。每写一字，要用多用笔意：有的横画似八分，下笔又如篆籀；有的竖画如深林乔木，屈折之画又如钢钩有力；有的落笔尖如枯秆，竖画收笔细如针芒；有的转侧之势如飞鸟坠空而下，有的棱侧之形如流水转弯激来。一字中，纵横笔画要相关联；一行中，上下之间要连气通声，最要紧的是注意存筋骨藏锋毫，隐灭笔锋毫端的痕迹。用尖笔须落锋浑然天成，不使毫露显得漂浮怯弱，用新笔要俊朗出众如有神明，不必过分计较一点一画的瑕疵。每写一个字都要吸收各种书体的笔法，写整幅字，就要每个字都各有笔意，切忌相互雷同。纸质柔软的，用硬毫，纸质硬的，则用软毫。强弱不当就会导致笔法蹉跌，失势不合。
凡作书贵在沉稳庄静，立意在动笔之前，写字在动笔之后，未写之前，构思就已成熟了。但下笔仍然不要着急，这是为什么呢？笔是将军，所以须要谨慎稳重。心要急不宜迟缓，为什么呢？心是箭锋，箭发出去不要迟缓，迟缓则中物不深。字有缓急，那么，在一字中，缓急又体现在那里呢？如“乌”字，下笔一点，就要点得急，接下去的横直笔就要缓慢，最后一钩出锋也要迅疾有力，这种急与缓的安排，也正是为了体现“乌”字的体势形态。每逢作书要多迟少急，多曲少直，多藏少出，多起少伏，这才是书法。如果纵笔急忙牵引束裹，乍看好像是书法作品，久一回味就感觉毫无笔力了。用笔着墨方面，不要超过十分之三，免得浸墨太深使毫弱无力。墨要和松节一道研磨，越是耐磨的墨当然越好。', NULL, '', 'indent', 1551017900, '5c72372744d90419c1841e3a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641887, '吊祢正平', NULL, 1, 55, 0, 1, '王炎（双溪）', NULL, 18536, '5858ecd08e450a006cba6f4c', '宋', 'shi', '诗', '', '', '曹瞒忍杀杨德祖，不敢复害祢正平。
区区黄祖雀鼠辈，乃以嬉笑生五兵。
才虽可爱亦可忌，人间险过羊肠路。
不锄骄气祸之媒，祖也不仁衡未智。
黄鹤楼前江水平，鹦鹉洲边春草青。
凭君酹酒吊孤冢，古来贤哲非贪生。 ', '', '', '', NULL, '', 'center', 1554809581, '5cac126aa91c932819c0de6a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641888, '余过荆州张安国已请祠先行', NULL, 0, 497, 0, 1, '王质', NULL, 36794, '588c9e6361ff4b006bd4783c', '宋', 'shi', '诗', '', '', '心事何曾吐一分，鼓严早已报三声。
元戎十乘公先启，野渡孤舟我自横。
细看好山须少驻，缓摇柔橹莫多鸣。
倘能黄鹤楼前见，安得春江尾柁行。', '', '', '', NULL, '', 'center', 1554809632, '5cac129ea91c932819c0e1cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642128, '幽梦影 · 卷一 · 九十七', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '有工夫读书，谓之福；有力量济人，谓之福；有学问著述，谓之福；无是非到耳，谓之福；有多闻、直、谅之友，谓之福。', '', '', '', NULL, '', 'indent', 1556102236, '5cbfcbdaa91c930069db48cd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641377, '菩萨蛮二首', NULL, 7, 1, 1, 0, '萧淑兰', NULL, 37018, '5c95c1d7fe88c20066b149e4', '元', 'ci', '词', '', '', '【其一】
天教刘阮迷蓬岛，桃花片片依芳草。
芳草惹春思，王孙知不知？
妾身轻似叶，君意坚如铁。
妾意为君多，君心弃妾那。
【其二】
有情潮落西陵浦，无情人向西陵去。
去也不教知，怕人留恋伊。
忆了千千万，恨了千千万。
毕竟忆时多，恨时无奈何。', '萧淑兰两寄《菩萨蛮》词之本事，见于明·卓人月《古今词统》（《明史·志第七十五·艺文四》载录“卓人月《古今词统》十六卷”）。《录鬼簿续编》、《曲海总目提要》均著录，其以词入曲事《词苑丛谈》亦载录。萧淑兰词事曰：
张世英馆於萧公让家。其妹萧淑兰慕张俊才，尝挑之，张拒而不纳。萧乃赋《菩萨蛮》赠之云：
天教刘阮迷蓬岛，桃花片片依芳草。
芳草惹春思，王孙知不知？
妾身轻似叶，君意坚如铁。
妾意为君多，君心弃妾那。
张得词，遂未辞而归。萧又赋云：
有情潮落西陵浦，无情人向西陵去。
去也不教知，怕人留恋伊。
忆了千千万，恨了千千万。
毕竟忆时多，恨时无奈何。
后其兄公让知之，以妹许张，备礼而婚焉。', '', '', NULL, '清代徐釚《词苑丛谈》：词虽以险丽为宗，实不及本色语之妙。如李易安“眼波才动被人猜”。萧淑兰“去也不教知，怕人留恋伊。”魏夫人“为报归期须及早，休误妾，一身闲”。孙光宪“留不得，留得也应无益”。', 'indent', 1553347590, '5c95c37067f3560062d4f90e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641380, '野塘', NULL, 5, 341, 0, 2, '韩偓', NULL, 10164, '57b9272dd342d3005ac86d7a', '唐', 'shi', '诗', '', '', '侵晓乘凉偶独来，不因鱼跃见萍开。
卷荷忽被微风触，泻下清香露一杯。', '', '', '', NULL, '《碛砂唐诗》：谦曰：比兴之意居多。', 'center', 1581205681, '5c97094fc05a800073f8b9d3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641387, '卜算子 · 尊前一曲歌', NULL, 1, 80, 1, 0, '杜安世', NULL, 10341, '57c3a535c4c9710061929134', '宋', 'ci', '词', '', '', '尊前一曲歌，歌里千重意。才欲歌时泪已流，恨应更、多于泪。
试问缘何事，不语如痴醉。我亦情多不忍闻，怕和我、成憔悴。', '《卜算子》，非深于情思者，绝无如此深刻。非工于描写者，绝无如此自然。
这首词类白乐天《琵琶行》，写的是作者闻歌伤怀之感。
上片写歌女的演唱，相当于白诗对琵琶女演奏的叙写。「尊前一曲歌，歌里千重意」，一曲歌而能具千重意，想必亦能说尽胸中无限事；而这「无限事」又必非乐事，当是平生種種不得意之恨事。这是从后二句中「恨」「泪」等字可得而知的。首二句巧妙地运用了对仗加顶真的修辞，比较一般的「流水对」更见跌宕多姿，对于歌唱本身亦有模似效用 。「才欲歌时泪已流」一句乃倒折一笔，意即「未成曲调先有情」。
「恨应更、多于泪」，又翻进一笔，突出歌中苦恨之多。白乐天诗对音乐本身的高低、疾徐、滑涩、断连等等，有极为详尽的描摹形容。而此词抓住歌者形态特点层层推进，启发读者去想象那歌声的悲苦与宛转。
「试问缘何事？不语如痴醉」，对歌女的悲凄身世作了暗示，相当于琵琶女放拨沉吟、自道辛酸的大段文字。但白诗中的详尽的直白，在此完全作了暗示的处理。当听者为动听的演唱感染，希望进一步了解歌者身世时，她却「不语如痴醉 」。这样写大有「此时无声胜有声」之妙。
末三句写词人由此产生同情并勾起自我感伤，相当于白居易对琵琶女的自我表白。但此词却只说「我亦情多不忍闻 」，好象是说歌女不语也罢，只怕我还受不了呢。由此可知，这里亦有一种同病相怜、物伤其类的感情，因此以至于「怕和我、成憔悴」。
和白乐天《琵琶行》不同的是，这首词善在抒情，妙在悬念的设置，化实为虚，得其空灵。同时，此词运笔颇饶顿挫 ，上片用递进写法，下片则一波三折，读来引人入胜。', '', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e74a9c6e67846a9206af1", "shortContent": "这首词写闻歌有感。一位歌女的动情演唱引起词人强烈共鸣，不禁一掬同情之泪。其情事大类白居易《琵琶行》，然而小词对于长歌，在形式上有尺幅与千里之差别。对照读之，最足见此词在写作上的特色。\n词分三层。上片都为一层，写歌女的演唱，相当于白诗对琵琶女演奏的叙写。“尊前一曲歌，歌里千重意”，一曲歌而能具千重意，想必亦能说尽胸中无限事；而这“无限事”又必非乐事，当是平生种种不得意之恨事。这是从后二句中“恨”、“...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec5b0d635634aee3e9a6e", "shortContent": "这首词写闻歌有感。一位歌女的动情演唱引起词人强烈共鸣，不禁一掬同情之泪。其情事大类白居易《琵琶行》，然而小词对于长歌，在形式上有尺幅与千里之差别。对照读之，最足见此词在写作上的特色。\n词分三层。上片都为一层，写歌女的演唱，相当于白诗对琵琶女演奏的叙写。“尊前一曲歌，歌里千重意”，一曲歌而能具千重意，想必亦能说尽胸中无限事；而这“无限事”又必非乐事，当是平生种种不得意之恨事。这是从后二句中“恨”“泪...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}]', '', 'indent', 1553476467, '5c97999cfe88c2006f531020', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641443, '渔家傲·东昌道上', NULL, 10, 1, 1, 0, '张渊懿', NULL, 37028, '5c99956e12215f0072c2ba3f', '清', 'ci', '词', '', '', '野草凄凄经雨碧，远山一抹晴云积。午睡觉来愁似织，孤帆直，游丝绕梦飞无力。
古渡人家烟水隔，乡心撩乱垂杨陌。鸿雁自南人自北，风萧瑟，荻花满地秋江白。', '', '', '', '[{"bookId": "60fc157134bfda01e0e91549", "bookTitle": "元明清词鉴赏辞典（新一版）", "articleId": "610e865134a8757d5a0de90c", "shortContent": "此词抒写的是旅途中的清秋之景和思乡之情。东昌为清东昌府（治今山东聊城），地处大运河中段，其南为济宁，其北为临清。此词正是作者乘船北上，在东昌道中写下的纪行之作。\n“野草凄凄经雨碧，远山一抹晴云积”，开头两句写途中所见之景：苍苍茫茫的野草经过一场秋雨的冲洗，格外的青翠。雨后初霁，天色明净，远山顶上积有一抹如棉絮般的白云。这两句写景设色清雅，用笔轻淡，犹如一幅淡远的水墨画，从而为下面的抒情营造了凄清渺...", "authors": ["陈", "列"], "pressName": "上海辞书出版社"}, {"bookId": "6464506e7f27182da3524606", "bookTitle": "元明清词三百首鉴赏辞典", "articleId": "646ae044e49f46528abed717", "shortContent": "此词抒写的是旅途中的清秋之景和思乡之情。东昌为清东昌府（治今山东聊城），地处大运河中段，其南为济宁，其北为临清。此词正是作者乘船北上，在东昌道中写下的纪行之作。\n\n“野草凄凄经雨碧，远山一抹晴云积”，开头两句写途中所见之景：苍苍茫茫的野草经过一场秋雨的冲洗，格外的青翠。雨后初霁，天色明净，远山顶上积有一抹如棉絮般的白云。这两句写景设色清雅，用笔轻淡，犹如一幅淡远的水墨画，从而为下面的抒情营造了凄清...", "authors": ["陈列"], "pressName": "上海辞书出版社"}]', '', 'indent', 1553598007, '5c9995a412215f0072c2bef1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641457, '咏燕', NULL, 0, 33, 1, 0, '秋瑾', NULL, 36401, '58309b9ea22b9d006b8637b6', '当代', 'shi', '诗', '', '', '飞向花间两翅翔，燕儿何用苦奔忙？
谢王不是无茅屋，偏处卢家玳瑁梁！', '此诗是秋瑾对婚后依人篱下生活的窘迫的感叹，更多的是一个闺阁女子的幽怨情怀。', '', '', '[{"bookId": "60fc32b023353c0ba53dd945", "bookTitle": "历代女性诗词鉴赏辞典", "articleId": "610ec7c1d635634aee3e9e93", "shortContent": "这首诗大约写于秋瑾出嫁前不久，郭延礼《秋瑾年谱》将此诗列入1895年中。诗人于光绪二十二年（1896年）奉父母命与湖南湘潭王氏联姻，但秋瑾并不十分情愿。在这首小诗里，诗人借物咏怀，曲折传达出自己对于婚姻的看法以及对命运的思索。\n前两句作者问道：在花间飞来飞去的燕子呵，你这样不辞辛苦地奔波，究竟所为何事？渠本非燕，自不知燕之苦乐，看似没有道理的一问，其实道出的正是作者本人的复杂感受：既似有轻微的责备...", "authors": ["曾庆雨"], "pressName": "上海辞书出版社"}]', '', 'center', 1553599835, '5c999ca60237d7006886a8cc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641480, '赠安成诗七首 · 其三', NULL, 42, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', '', '', '相彼景响，有比形声。
始云同宗，终焉友生。
棠棣隆亲，頍弁鉴情。
缅邈岁月，缱绻平生。', '', '', '', NULL, '', 'center', 1553601378, '5c99a2df42cda60074b6df37', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641515, '邻里相送至方山诗 ', NULL, 0, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E9%82%BB%E9%87%8C%E7%9B%B8%E9%80%81%E8%87%B3%E6%96%B9%E5%B1%B1/1099682?fr=aladdin', '', '祗役出皇邑，相期憩瓯越。
解缆及流潮，怀旧不能发。
析析就衰林，皎皎明秋月。
含情易为盈，遇物难可歇。
积疴谢生虑，寡欲罕所阙。
资此永幽栖，岂伊年岁别。
各勉日新志，音尘慰寂蔑。', '《邻里相送至方山》是南朝宋诗人谢灵运创作的一首五言律诗。这首诗分三层，前四句为第一层写自己将出任郡守，因与邻里有旧情而不忍分别。中间四句为第二层写行程中的所见，表达诗人本不欲迁外郡，而朝命难违，身不由己，欲罢不能，只好扬帆上路。最后六句为第三层就题意言是点明与邻里告别之主旨，写的是对朋友的勉励和叮嘱。这首诗运用比兴，且情与景的结合紧密自然。', '方山：当时皇都建康（今南京）附近的一个山名，山呈方形，山下有河水码头，亲友常于此送别行人。
抵役：敬奉朝命赴外地任职。只，敬也。皇邑（yì）：京城，指刘宋都城建业（今南京市）。
憩（qì）：休息。瓯越：指水嘉郡。永嘉一带在汉代地属东瓯，东越王摇曾在那里建都，故称瓯越。
解缆：解开系船的缆绳，指开船。及：乘。
怀旧：留恋老朋友。
析析：风吹树木的声响。就：靠近。
皎皎（jiǎo）：光洁的样子。
含情：这里指怀旧之情。盈：满。
遇物：指一路上遇到的衰林、秋月。
积疴（ē）：多年患病。疴，病。谢：绝。虑：思虑、谋求。
寡欲：少欲。阙：同“缺”。
资：借。此：指永嘉郡。幽栖：隐退屏居。
岂伊：岂惟。
日新：一天比一天进步。《周易》屡见，如《大畜》云：“日新其德。”《系辞上》云：“日新之谓盛德。”又《礼记·大学》引汤之盘铭云：“苟日新，日日新，又日新。”都是进德修身之意。
音尘：音信，消息。寂蔑（miè）：寂寞。', '自己奉王命离开京城去永嘉赴任，希望到那里后能安适地居住下来。
当船要趁着潮水解缆出发的时候，我却因留恋故人而不忍离去。
船在行驶中靠近了析析作响的凋败的树林，又看到秋月在放射着皎洁的光芒。
本来就因有怀旧之情，容易感到心中充满哀伤，现在又看到衰林、秋月，内心的悲愁就更加难以遏制了。
自己因久病而断绝了对于生活方面的追求。自己本来个人欲望就很少，所以现在并不觉得有什么不足。
我是想借永嘉郡永远隐居下去，哪里是只离开你们一年半载去做官呢！
希望你们努力做到天天进步，并经常来信以安慰我的寂寥。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb00ce818559d0646aa", "shortContent": "谢灵运是晋代世家大族名将谢玄的孙子。在当时门阀制度下，他作为豪门世族的后裔，不仅拥有大量财产，而且政治上影响也很大。尽管宋武帝刘裕出身不够高贵，倚仗兵权在握才篡夺了晋室天下，做了皇帝，但他对当时的豪门世族还是要拉拢敷衍的。所以在刘宋开国以后，谢灵运虽未身居显要，却依然在朝任闲散官职，名气还是很大的。等刘裕一死，少帝即位，由于各派政治势力互相倾轧，谢灵运终于受到排挤，于永初三年（422）七月出任永嘉...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}]', '清·王夫之《姜斋诗话》：“情景相人，涯际不分，振往古，尽来今，唯康乐能之。”', 'center', 1553684164, '5c9ae64242cda600685f2f36', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641517, '登永嘉绿嶂山诗 ', NULL, 0, 135, 3, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E7%99%BB%E6%B0%B8%E5%98%89%E7%BB%BF%E5%B6%82%E5%B1%B1%E8%AF%97/4555895?fr=aladdin', '', '裹粮杖轻策，怀迟上幽室。
行源径转远，距陆情未毕。
澹潋结寒姿，团栾润霜质。
涧委水屡迷，林迥岩逾密。
眷西谓初月，顾东疑落日。
践夕奄昏曙，蔽翳皆周悉。
蛊上贵不事，履二美贞吉。
幽人常坦步，高尚邈难匹。
颐阿竟何端，寂寂寄抱一。
恬如既已交，缮性自此出。', '这首诗虽然多了一个语言晦涩乏味的“玄言尾巴”，但它不仅模山范水方面极为生动、清新，而且对于游历的过程、时间，地点、心情，都交待得明白清晰，表现出一种登涉之趣。因此，读者读这首诗，仍然会在不知不觉中跟随着诗人攀岩泛流，徜徉于山光水色之中，从而获得与大自然交感会通的审美上的愉悦。谢灵运的山水诗多采取纪游的写法。其章法结构，大抵是先纪游，继写景，最后兴情悟理。此诗即采取这种井然的推展次序。', '绿嶂山：在永嘉城北，一名青嶂山，上有大湖。
裹粮：准备好食物。
仗轻策：拿起轻便的手杖。
怀迟：犹逶迤，迂回曲折貌。
幽室：石室，山洞。此指风景清幽之地。
行源：溯流而上，向溪流的源头前进。
径：小路。
距陆：到上岸处。
情未毕：意谓沿溪而游的兴致还十分浓厚。
澹潋（dànliàn）：水波微微动荡的样子。
结：凝结。
团栾（luán）：犹檀栾。竹秀美貌，这里指代竹。
润霜质：谓竹性耐寒，经霜愈见青翠光润。
涧（jiàn）委：涧水弯曲。
水屡迷：谓因为涧流弯曲，故屡屡不辨水流的去向。
林迥（jiǒng）：丛林深远。
眷（juàn）：眷顾，细细观看。
顾：回顾，回头看。
奄昏曙（shǔ）：谓从早到晚，一会儿就过去了。
蔽翳（bìyì）：指山岩和林木的最隐蔽幽深之处。
周悉：完全熟悉。
蛊（gǔ）上：指《易经·蛊卦》上九。句用《易·蛊》“上九，不事王侯，高尚其事”之意，意谓虽然身在仕途，但却不为所累。
履二：指《易经·履卦》九二。此句用《易·履》“九二，履道坦坦，幽人贞吉”之意，说明在永嘉太守任上优游的乐趣。
贞吉：谓人能守正道而不自乱则吉。
幽人：指隐者，诗人自称。
坦步：安然地步行。
颐（yí）阿：应诺与呵责，指善良与罪恶。或谓颐阿即伊我，你我之间，借指不事王侯的隐士和凡夫俗子。
何端：有何区别。这句意谓颐阿之间本来相差很远，但在老子看来，却并没有多少区别。
寄抱一：将思想感情寄托于玄理。抱一，道家谓专精固守不失其道。一，指道。
恬如：恬静和智慧。
缮（shàn）性：即涵养本性之意。以上二句概括《庄子·缮性》篇的主要思想，说明自己已经得到本性的自然，达到物我合一的境界。', '准备好食物拿起手杖，蜿蜒曲折的爬上风景清幽之地。
沿着小路向溪流的源头越走越远，到了上岸的地方沿溪而游的兴致还十分浓厚。
水波微微动荡的样子凝结成孤寒的姿色，竹子经霜愈见青翠光润。
涧水弯曲故屡屡不辨水流的去向，丛林深远岩石也越来越密。
朝西看密林中漏下的落日余光斑斑驳驳令人怀疑可能已是夜晚，再向东看，岩壁上隐现出昏黄的月色，又使他怀疑是夕阳正在沉落。
从早到晚，一会儿就过去了，山岩和林木的最隐蔽幽深之处都已经完全熟悉了。
虽然身在仕途，但却不为所累，在永嘉太守任上游玩其乐无穷，人能守正道而不自乱则吉。
我自己经常安然地步行，都难以与绵邈的高尚相匹敌。
颐阿之间本来相差很远，但在老子看来，却并没有多少区别。
恬静和智慧既然已经有了，涵养本性就是从此处变现出来的。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb103048e64fbd9c6cd", "shortContent": "永初三年（422），谢灵运被降职外放永嘉任太守。诗人在郡不理政务，恣情遨游山水。每游一处，必有诗篇记胜。这首诗即是其一。据《读史方舆纪要》说：“（永嘉）西北二十里有青嶂山，上有大湖，澄波浩渺，一名七峰山。”此青嶂山，似即绿嶂山。\n谢灵运的山水诗多采取纪游的写法。其章法结构，大抵是先纪游，继写景，最后兴情悟理。此诗即采取这种井然的推展次序。起首二句，写他出发前的准备和启程情况。诗人携带足够的干粮，拄...", "authors": ["陶文鹏"], "pressName": "上海辞书出版社"}]', '', 'center', 1553684465, '5c9ae76f42cda600685f4d98', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641519, '游岭门山诗 ', NULL, 1, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E6%B8%B8%E5%B2%AD%E9%97%A8%E5%B1%B1%E8%AF%97/12649233?fr=aladdin', '', '西京谁修政？龚汲称良吏。
君子岂定所，清尘虑不嗣。
早莅建德乡，民怀虞芮意。
海岸常寥寥，空馆盈清思。
协以上冬月，晨游肆所喜。
千圻邈不同，万岭状皆异。
威摧三山峭，瀄汩两江驶。
渔舟岂安流，樵拾谢西芘。
人生谁云乐？贵不屈所志。', '《游岭门山诗》是南朝宋诗人谢灵运创作的一首五言古诗。这首诗分三部分。前八句为第一部分，写了“龚汲”的事情和“虞芮”的故事，以自标风操的方式回答政敌的打击，在失意中仍可见其倔强的个性。中间八句第二部分，写景，记游山，以“晨游”发端，而以“西芘”收束，其间由朝入暮，包含了完整的一天。最后两句为第三部分，以言志作结，发出了守志不屈、身处逆境之中而不向坎壈命运低头的抗争之声。这首诗巧用典故，章句严整、匀称。', '岭门山：据《温州府志》，在今瑞安县治前，其山分左右两翼，中间夹坡如门，故称岭门。
西京：本指洛阳西边的京都长安，这里代指西汉王朝。
龚（gōng）：指龚遂，字少卿。汉宣帝时被派往边地渤海郡作太守，采取一系列有效措施，使原来乱糟糟的渤海郡盗贼消隐，狱讼止息，人民安居乐业，生活迅速富裕起来。
汲（jí）：指汲黯，信黄老，好清静。他作东海太守时，因多病，常卧床不出，于政事只求大旨，不细管束，过了一年多，东海大治。
良吏（lì）：德才兼备的好官。
岂定所：何必有固定的生活场所。这是对自己迁降永嘉作官的一种自我安慰。
清尘：清高的遗风，指龚、汲等前贤的美德。
虑不嗣（sì）：担心不能继承。
莅（lì）：到达。
建德乡：即永嘉郡。语本《庄子·山木》篇：“南越有邑焉，名为建德之国，其民愚朴，少私寡欲，其生可乐，其死可葬。”
民怀虞（yú）芮（ruì）意：指永嘉百姓具有虞芮人民那样容易受教从善的品质。据《史记·周本纪》，虞芮之人常有纠纷而不肯相让，就到周国去请周伯来评判，但见周国耕者皆让畔，民俗皆让长，虞芮之人深受教育，惭愧返还，从此不再争执。
协：合议，商量。
以：于，在。
上冬：孟冬，初冬。
肆所喜：放开手脚无拘无束地作自己喜欢作的事，指尽情游乐。
圻（qí）：涯岸。
邈：通貌。
威摧：同崔崴，高峻的样子。
三山：即《山居赋》自注所提到的太平、天台、方石等海中三山。
瀄汩（zhìgǔ）：流水发出的声音。
两江：即《山居赋》自注所提到的双流，也就是剡江和小江。
驶：流水疾速奔腾而去。
渔商：渔人和商人。郭璞《江赋》：“溯泗沿流，或渔或商。”
安流：指渔商的舟船在江河中平安航行。《楚辞·九歌》：“令沅湘兮安流。”
樵（qiáo）拾：山间砍柴和采摘果实野菜的人。
芘（pí）：同庇，荫蔽。
谁云乐：什么是快乐。', '前朝炎汉，谁人能，修明政治？龚遂汲黯，两太守，世称良吏。
君子出仕，又何须，定位京邑，前贤清风，我步尘，惟恐不继。
到此永嘉，民立德，寡欲少私，百姓乐生，淳风俗，尤尚忠恕。
滨海之地，远故乡，常怀旷寂，官署悠闲，无争讼，空馆清思。
欣和怡悦，于盂冬，十月夏历，晨问出游，纵我情，尽历所喜。
千涯逶迤，一程程，弯弯曲曲，万岭崇峻，一层层，重重峙峙。
崔巍岭峙，如三山，陡峭壁立，云腾水淼，似两江，疾速奔逝。
商贾渔舟，顺江河，安稳航驶，农夫樵子，林荫中，落日归去。
人之一生，如何是，快乐一世？可贵在于，无拘束，心志所之。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb134a8757d5a0ed4c9", "shortContent": "这首诗从题目看，应是纪游之作，而诗的前半部分却从治郡的政绩写起，这种闲笔似无关宏旨，实际上正透露了诗人潜结的意绪。永初三年（422）谢灵运出任永嘉郡守，原是刘宋朝廷内部权力之争的结果，以出身士族名门、“自谓才能宜参权要”的诗人，而今迁谪到一个僻远的边郡任职，其愤懑悒郁的心情不难想见。诗人骨鲠在喉，不得不吐，而驱走其笔端的山水，不过是他用来浇胸中垒块的酒杯而已。\n诗的结构组织颇为均衡：全诗十八句，前...", "authors": ["钟元凯"], "pressName": "上海辞书出版社"}]', '', 'center', 1553684595, '5c9ae7f0fe88c20070808337', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641520, '石室山诗 ', NULL, 0, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E7%9F%B3%E5%AE%A4%E5%B1%B1%E8%AF%97/12538544?fr=aladdin', '', '清旦索幽异，放舟越垌郊。
莓莓兰渚急，藐藐苔岭高。
石室冠林陬，飞泉发山椒。
虚泛径千载，峥嵘非一朝。
乡村绝闻见，樵苏限风霄。
微戎无远览，总笄羡升乔。
灵域久韬隐，如与心赏交。
合欢不容言，摘芳弄寒条。', '。', '石室山：谢灵运生活过的永嘉和始宁都有石室山，黄节以为始宁之石室，而顾绍柏考证为永嘉郡郊外楠溪江畔的石室山，又名大箬岩。此从顾说。
索幽异：探寻隐蔽特异的景点。
垌（dòng）郊：泛指郊野。
莓莓：水草茂盛义。
兰渚（zhǔ）：生有兰惠等香草的河洲。左思《魏都赋》有“兰渚莓莓”语，或即此句所本。
急：既指水流湍急，也指舟行急速。
藐藐（miǎo）：通“邈邈”，遥远的样子。
苔岭：但见一片青翠，好像是覆盖苔衣的山岭。
冠：像帽子一样盖在上面。
林陬（zōu）：成片森林的一角。
山椒：山尖，山顶。
虚泛：形容水之广大。
径：通“经”，直通，经历。
峥嵘（zhēngróng）：指山势高峻。
樵（qiáo）苏：指砍柴割草的人。
限：阻隔。
风霄：云霄。
微戎（róng）：信述堂重刊本“百三家集”作“微我”。微我，非我是。
总笄（jī），泛指少年时期。总，束发，指童年。笄，挽髻插簪，指刚成年时。
羡（xiàn）升乔：谓羡慕升仙的王子乔。王子乔是春秋时周灵王太子。姓姬，名晋。传说王子乔曾游伊水、洛水间，后被道士浮丘公接上嵩山成仙。
灵域：指石室石。
韬（tāo）隐：韬光隐晦。谓石室山久藏穷乡僻野，鲜为人知。
心赏：即赏心。作名词，指推心置腹的朋友。
合欢：表面上指合欢树，实际上也指山有人知，人为山醉，相得共喜。
摘芳：采摘花朵。芳：指花果。
弄：抚弄。
条：指枝叶。', '为探幽索奇，放舟江中，越过城郊林野，向前疾驶而去。
那江心兰草丰茂的沙洲仿佛在急急地向后退去，而前方本来隐隐可见的长满苔藓的青山，去逐渐高大起来。
举目远望在那大片森林的一角，石室山秀峰峭拔，耸出林表，一条清泉飞瀑，自山顶倾泻而下。
水之广大是因为它经历了千年，山势高峻也不是一朝一夕可以形成的。
在乡村里是绝对看不到也听不到的，砍柴割草的人阻隔了云霄。
自己年轻时虽未能云游，但早已企羡王子乔的升仙。
现在身处这幽绝的山中，不由觉得此处就是他韬光藏隐的地方，自己的心灵也似乎与他沟通起来。
站在合欢树下摘下它的花瓣，玩赏着它那还带有寒意的枝条。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb12cee9a0c24eda8b7", "shortContent": "灵运《山居赋》有句云：“室、壁带溪。”自注云：“石室，在小江口南岸；壁，小江北岸。”《山居赋》描写的是灵运家乡始宁一带的山水景物，所以本诗应是在始宁墅时所作的。\n在这首纪游诗中，前六句写一个天气清爽的早晨，诗人为探幽索奇，追寻异景，放舟江中，越过城郊林野，向前疾驶而去。随着舟驶水逝，那江心兰草丰茂的沙洲，仿佛在急急地向后退去；而前方本来隐隐可见的长满苔藓的青山，却逐渐高大起来。举目远望在那大片森林...", "authors": ["臧维熙"], "pressName": "上海辞书出版社"}]', '', 'center', 1553684664, '5c9ae83642cda600685f6176', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641521, '登石室饭僧诗', NULL, 0, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', '', '', '迎旭凌绝嶝，映泫归溆浦。
钻燧断山木，掩岸墐石户。 
结架非丹甍，藉田资宿莽。
同游息心客，暧然若可睹。 
清霄扬浮烟，空林响法鼓。 
忘怀狎鸥鯈，摄生驯兕虎。 
望岭眷灵鹫，延心念净土。 
若乘四等观，永拔三界苦。', '', '', '', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb15914587d02f599df", "shortContent": "此诗系作者任永嘉太守时所作。其题目一作“登石室饭僧”，又作“过瞿溪山饭僧”。瞿溪、石室山均在永嘉郡永宁县（今浙江温州）。饭僧，犹言斋僧，施饭食与僧人。\n开头六句写诗人一路经行所见。他迎着旭日，凌越陡峭的山间小路；渡过溪涧，映着活泼泼的流水，来到水滨。嶝，登山小径。泫，即泫泫，水流貌。溆、浦，都是水边的意思。一路上但见山里人家过着简朴艰苦的生活：他们截断树木，钻木取火；他们的屋舍掩蔽于水边高崖之下，...", "authors": ["杨", "明"], "pressName": "上海辞书出版社"}]', '', 'center', 1553684744, '5c9ae88617b54d0074a1e0b2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641522, '登上戍石鼓山诗 ', NULL, 0, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E7%99%BB%E4%B8%8A%E6%88%8D%E7%9F%B3%E9%BC%93%E5%B1%B1/1072589', '', '旅人心长久，忧忧自相接。
故乡路遥远，川陆不可涉。
汩汩莫与娱，发春托登蹑。
欢愿既无并，戚虑庶有协。
极目睐左阔，回顾眺右狭。
日没涧增波，云生岭逾叠。
白芷竞新苕，绿蘋齐初叶。
摘芳芳靡谖，愉乐乐不燮。
佳期缅无像，骋望谁云惬。', '《登上戍石鼓山》是南朝宋诗人谢灵运创作的一首五言古诗。这首诗可分为三个部分。前八句为第一部分，写的是将要登山，以及登山的原因。中间六句为第二部分，写的是登山时看到的景物。最后四句为第三部分，写的是登览总的感慨，表达了去国离乡的悒郁之情。这首诗用笔比较清朗、生动，情景交融，是谢灵运写景抒情诗之佳作。', '上戍（shù）：即上戍浦，在永嘉江中。石鼓山：在永嘉西约四十里，山上有石，扣之则响，放名石鼓山。
旅人：自指。
涉：不用舟船过水而行。
汩汩（gǔ）：心情不安。
发春：开春。
欢愿：欢乐美好的愿望。
并：合，这里有实现的意思。
庶（shù）：表示希望的副词。
协：有谐调、缓和的意思。
睐（lài）左阔：斜视左边，是一望无际的宽阔平原。
回顾：回过头来。
眺右狭：远望右边，峰岭对耸，形成狭隘的山沟深谷。
日没：太阳沉没人海（或下山）。
涧（jiàn）增波：太阳下山时海水涨潮，临海的江河沟渎都会提高水位，故言“涧增波”。
岭逾叠：云团笼罩于山峰之上，好像又叠加了许多山峰，所以说“岭逾叠”。
白芷（zhǐ）：一种香草。
竞新苕（tiáo）：跟刚刚发芽的芦苇竞相生长。
绿蘋（píng）：一种水草。
齐初叶：刚刚长出的嫩叶大小一致，非常整齐可爱。
摘芳：摘取鲜花香草。
靡谖（mǐxuān）：不能忘优。
燮（xiè）：和谐。
佳期：指回乡与亲友团聚的日子。
缅（miǎn）无像：遥远渺茫无影无踪。
谁云惬（qiè）：哪里能得舒适惬意。', '谪居永嘉并非我的心愿，心中装满沉甸甸的忧愁。
回家的路多么遥远啊，望眼欲穿总难如意。
时光飞逝，而内心的落寞无法排遣，只好在明媚的春光里登山解忧。
归家的愿望无法实现，思也悠悠，恨也悠悠。
睁大眼睛斜视左边，是一望无际的宽阔平原，回过头来远望右边，峰岭对耸，形成狭隘的山沟深谷。
太阳下山了，初春的寒风吹起了山涧的水波，令人感到丝丝凉意，晚云一层层起来，萦绕在山头、横亘在山腰，在暮色中望去，似乎山岭又增添了许多重叠。
白芷这时生出了新茎，绿苹也长出了新叶。
摘取芳草而芳草并未使他忘忧，一时愉乐而终不愉快。
那回归的日子不知在何时，即使登高遥望，又叫人怎么高兴得起来呢！', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb1c6e67846a9219aeb", "shortContent": "上戍，地名；石鼓，山名：都在永嘉城西四十里。谢灵运在宋武帝永初三年（422）秋任职永嘉，这是到任后第二年春天写的。他是被排挤出朝的，所以赴任途中郁郁不乐，经过会稽始宁老家，他郑重告诉乡亲：“三载期归旋”（《过始宁墅》）。来永嘉后写的作品也一再流露出这些情绪。\n这首诗开头就写道：“旅人心长久，忧忧自相接。”“旅人”，自指。把郡守的身份说成是旅人，可见他对职守的态度。这两句应连成一句读，就是：旅人的心...", "authors": ["汤华泉"], "pressName": "上海辞书出版社"}]', '清·王夫之《古诗评选》：“谢诗有极易入目者，而引之益无尽；有极不易寻取者，而径遂正自显。然顾非其人，弗与察尔。言情则于往来动止缥缈有无之中，得灵响而执之有象；取景则于击目经心丝分缕合之际，貌固有而言之不欺。而且情不虚情，情皆可景；景非滞景，景总含惰。神理流于两间，天地供其一目，大无外而细无垠，落笔之先，匠意之始，有不可知者存焉。岂徒兴会标举如沈约之所云者哉？自有五言，未有康乐；既有康乐，更无五言。或曰不然，将无知量之难乎？”
浙江省古代文学学会常务理事俞樟华《池塘春草——谢灵运、孟浩然、王维诗选》：“诗人登高览胜，意不在景，而是要抒发去国离乡的抑郁之情，既有思归故乡之意，亦有重返朝廷之心，可惜两者无一可以如愿，这怎么叫诗人高兴得起来呢！诗中频繁袭用屈原作品的语汇和意象，后人誉为‘能换面目’。”', 'center', 1553684794, '5c9ae8b6a3180b00686c4b79', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641889, '读翰林集', NULL, 0, 8, 0, 1, '田锡（表圣）', NULL, 36959, '5b9ca39a67f356005c9934e6', '宋', 'shi', '诗', '', '', ' 太白谪仙人，换酒鹔鹴裘。
扁舟弄云海，声动南诸侯。
诸侯尽郊迎，葆吹罗道周。
哆目若饿虎，逸翰飞灵虬。
落日青山亭，浮云黄鹤楼。
浩浩歌谣兴，滔滔江汉流。
下交魏王屋，长揖韩荆州。
千载有英气，兰君安可俦。
', '', '', '', NULL, '', 'center', 1554809727, '5cac12fd0237d70068086f7a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641523, '石壁立招提精舍诗 ', NULL, 0, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E7%9F%B3%E5%A3%81%E7%AB%8B%E6%8B%9B%E6%8F%90%E7%B2%BE%E8%88%8D/1071389', '', '四城有顿踬，三世无极已。
浮欢昧眼前，沈照贯终始。
壮龄缓前期，颓年迫暮齿。
挥霍梦幻顷，飘忽风雷起。
良缘迨未谢，时逝不可俟。
敬拟灵鹫山，尚想祗洹轨。
绝溜飞庭前，高林映窗里。
禅室栖空观，讲宇析妙理。', '《石壁立招提精舍》是南朝宋诗人谢灵运创作的一首五言古诗。这诗分三层，前六句为第一层结合身世说明佛理。中六句为第二层正写顿悟前非，于石壁立招提精舍。最后四句为第三层状精舍美景，拟想今后在其中的悟道生活。这首诗结构造语上有着高度的艺术性，结构与造景两妙相融，遂使枯燥乏味的哲理诗显得墨气精光。', '招提：本义为僧房，后来也作寺院的别称。
四城：指佛陀在俗为太子时所游四城门。典出《因果经》：“尔时太子，年渐长大，出家时至，故辞父王，出四城门游观。前三所逢生厌唯欲，第四出家。”顿踬（dùnzhì）：绊倒，意谓不顺利。
三世：过、现、未三世。这里疑代指佛界。《维摩经》曰：“此经广说过去未来现在诸佛。僧肇日：三世菩萨，不思议道，皆陈在此经。”无极已：无限期。
浮欢：现世的欢乐。昧（mèi）眼前：连眼前的事物也看不清楚。昧，模糊。
沈照：深入地观照。
颓（tuí）：衰弱。迫暮齿：晚年时感到了时光的紧迫可贵。
挥霍：此谓急速的样子。
飘忽：快捷疾速的意思。
迨（dài）：同“逮”，及。谢：凋谢，结束。
俟（sì）：等待。
拟：向往。灵鹫山：在古印度摩揭陀国王舍城东北，佛陀曾在此居住、说法多年。
祗洹（zhīhuán）：祗垣，即只树给孤独园，在古印度乔萨罗国舍卫城南，也是佛陀居住、说法的场所。
绝溜（liù）：凌空而下的涧水或瀑布。
栖：栖息，居住。空观：佛教认识世界的理论之一，具体内涵各时期、各派别理解并不一致。如三论宗有三观：空观、假观、中道观。
讲宇：讲堂。妙理：指佛教的各种精微理论，《法华经》载有迹门十妙。', '当年佛陀出游四门看见人生的困苦，体会到过、现、未三世流转无穷。
现世的欢乐挡住了人的视野，深刻的观照才能了解事物的真相。
年轻的时候总以为来日方长，到年老的时候才发现时光紧迫。
时间急速流逝如梦幻一般，又飘忽好象是闪电一样。
人世的因缘还没有完结，时光流逝也不可期待。
恭敬地设想灵鹫山的情景，还有当年只园的轨范。
高悬的瀑布奔流在这庭院之前，高大的树林映照在窗户里。
在禅室里体会大乘“空”现，在讲堂里解析玄妙的佛理。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb17d0ac1145495f331", "shortContent": "大诗人而兼大学者，两方面都能拔萃超群，俯视当世者，在诗史上似乎仅谢灵运一人足以当之。灵运家“长玄学”，说理谈玄有“万顷陂”之称，更广交高僧，玄佛互参。他不仅参与《大涅槃经》华译，《金刚般若经》，而且对佛学理论有极深的造诣。当时竺道生倡众生都可顿悟成佛之说，因不见于旧译经藏，被视为异端新论。灵运作《辨宗论》阐述之，发为积学顿悟之说，所论竟为后译《大涅槃经》所证实。唐代南宗禅精义，于此已具大体。本诗就...", "authors": ["赵昌平"], "pressName": "上海辞书出版社"}]', '中国书法家协会会员黄德昌《观色悟空——佛教智慧》：“谢灵运写有《石壁立招提精舍》一诗，显示了他玄佛互参的悟性，不愧为以诗文阐佛理，以玄学解性空的一代宗师。”
浙江省古代文学学会常务理事俞樟华《池塘春草谢灵运、孟浩然、王维诗选》：“诗人结合自己的生活实感，追溯了自己明道顿悟，参透怫理的经过，觉今是而昨非，长期纠缠于心的仕与隐的矛盾和痛苦，于此得到了解决。诗人表示，从此将在石壁精舍过着悟道参禅的生活。以禅入诗，使理和景融为一体，这是谢灵运在诗歌史上的一个创新。”', 'center', 1553684860, '5c9ae8f8a3180b00686c5387', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641524, '登石门最高顶诗 ', NULL, 0, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E7%99%BB%E7%9F%B3%E9%97%A8%E6%9C%80%E9%AB%98%E9%A1%B6/1069924', '', '晨策寻绝壁，夕息在山栖。
疏峰抗高馆，对岭临回溪。
长林罗户庭，积石拥基阶。
连岩觉路塞，密竹使径迷。
来人忘新术，去子惑故蹊。
活活夕流驶，噭噭夜猿啼。
沉冥岂别理，守道自不携。
心契九秋干，目玩三春荑。
居常以待终，处顺故安排。
惜无同怀客，共登青云梯。', '《登石门最高顶》是南朝宋诗人谢灵运创作的一首五言古诗。这首诗分三个层次，起二句为第一层点题，写晨登夕栖。中间十句为第二层，写宿山之所见、所闻。最后八句为第三层即景抒情，结出诗旨。这首诗的妙处是全诗十分注意偶句的锤炼，几乎通篇对偶，融情造景的精致有含与结构布局上的顺逆疏密，二者相合形成全诗森然傲兀的意态。', '石门：即石门山，在今浙江嵊州市，谢灵运《游名山志》说：“石门涧六处，石门溯水，上入两山口，两边石壁，后边石岩，下临涧水。”又云石门为己南居。
策：拄着手杖。
寻：小心翼翼地探着走路。
栖：住宿。
疏峰：远处的山峰。
抗：遥相对举。
高馆（guǎn）：指建于石门绝壁上的精舍。
回溪：曲折回旋的溪流。
长林：高大的树木。
罗户庭：排列在门前庭外。
拥：堆满。
阶基：屋檐下靠墙脚高出地面的小块平台。
术：道路。
去子：离开的人。
惑故蹊（xī）：忘记了原先走过的小路。
活活（guō）：水流声。《诗经·卫风·硕人》：“河水洋洋，北流活活。”
嗷嗷（jiào）：动物的吼鸣声。
沉冥：深沉无欲。
守道：遵守养生之道。
不携：指没有二心。携，分离。
契：相合。
九秋：即秋天，因为一秋九十天。
干：树干，指经得起深秋风霜侵凌的松柏等。
目玩：用眼睛审视、欣赏。
三春：即春天，因为春季三个月。
荑（tí）：草木的初生嫩叶。
居常：甘处贫穷。
处顺：采取顺应自然的态度。
安排：安于推移。指达到道家物我不分、人天合一、无忧无乐的境界。
同怀客：抱负相同的人。
青云梯：传说中架于青天白云间的梯子，登之可以升天成仙，这里借指隐逸之路。', '早晨拄着手杖在山里小心翼翼地探着走路，晚上走累了在山里住宿。
远处的山峰遥相对举，迎面的山峰夹着曲折回旋的溪流。
高大的树木排列在门前庭外，石头堆满屋檐下靠墙脚高出地面的小块平台。
山岩连着山岩会让路没法走，茂密的竹林会使人道路迷失。
过来的人会忘记新走出来的路，离开的人忘记了原先走过的小路。
晚间溪水流动的声音“活活”作响，夜晚猿猴“噭噭”地叫着。
深沉无欲怎么能不理，遵守养生之道自己没有二心。
心相合则经得起深秋风霜侵凌，用眼睛欣赏春天草木的初生嫩叶。
甘处贫穷以等待终老，采取顺应自然的态度达到道家物我不分、人天合一、无忧无乐的境界。
可惜没有抱负相同的人，一起走上隐逸之路。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb2d635634aee3ea594", "shortContent": "石门山，在今浙江嵊州，谢灵运《游名山志》说：“石门涧六处，石门溯水，上入两山口，两边石壁，后边石岩，下临涧水。”又云石门为己南居。谢集中更有《石门新营所住，四面高山，回溪石濑，茂林修竹》诗、《石门岩上宿》诗，会同参看，当是宦海挫折，归隐所作，唯具体时间难以确定。有的选本谓《石门新营所住》诗为景平元年（423）由永嘉归隐作。本诗及《石门岩上宿》为元嘉五年（428）由秘书监任，不得意称疾东归后作。似并...", "authors": ["赵昌平"], "pressName": "上海辞书出版社"}]', '浙江省古代文学学会常务理事俞樟华《池塘春草——谢灵运、孟浩然、王维诗选》：“石门之景，优美奇特，诗人登山临水，乐而忘返，自然希望有志同道合的朋友能一起隐居山林，超然世外。全诗十分注意偶句的锤炼，几乎通篇对偶，陆时雍《诗镜总论》谓‘康乐神工巧铸，不知有对偶之烦’，斯言可信。”', 'center', 1553684932, '5c9ae94042cda600685f874c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641526, '白石岩下径行田诗 ', NULL, 0, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E7%99%BD%E7%9F%B3%E5%B2%A9%E4%B8%8B%E5%BE%84%E8%A1%8C%E7%94%B0/1016016?fr=aladdin&fromid=12537433&fromtitle=%E7%99%BD%E7%9F%B3%E5%B2%A9%E4%B8%8B%E5%BE%84%E8%A1%8C%E7%94%B', '', '小邑居易贫，灾年民无生。
知浅惧不周，爱深忧在情。
莓蔷横海外，芜秽积颓龄。
饥馑不可久，甘心务经营。
千顷带远堤，万里泻长汀
州流涓浍合，连统塍埒并。
虽非楚宫化，荒阙亦黎萌
虽非郑白渠，每岁望东京。
天鉴倘不孤，来兹验微诚。', '《白石岩下径行田》是南朝宋诗人谢灵运的所写的一首五言诗。诗作先笼统而言“灾年民无生”，表明自己“爱深忧在情”。继写灾情实况，引出其理想中的农田水利工程。诗末六句，诗人叙写自己的心愿。该诗体现了诗人既有寻幽探胜，肆意游遨，“民间听讼，不复关怀”的一面；又有身处灾年，关心黎民，正视现实，注重农业的一面。全诗表达了诗人对贫困人民的同情之情。', '白石岩：即白石山，在永嘉郡乐城县（今浙江乐清市）。行田，巡视农田。
小邑：小县，指乐城县。居：住。
无生：无法生活。
知：智。知浅：指自己智能浅薄。惧：怕。不周：考虑不周到。
爱深：指对百姓的深深的爱。忧：担忧。情：心。
旧业：使旧的圃宅。横：横陈。海外：海边。
芜秽：荒芜，谓田地不整治而杂草丛生。积：积久。颓龄：衰败的岁月。
饥馑：饥荒。
甘心：情愿。经营：筹划营造。
干顷：形容农田之多。堤：这里指海边的堤塘。
泻：水很快地流，这里指排灌的设想。汀：水边平地。
州：古代行政单位名。涓：细流。浍：田间小沟。
连：古代行政单位名。塍（chéng）：田埂。埒（liè）：小界堤。
楚宫：楚丘的富室。楚丘：在今河南滑县东。化：教化。
荒阙：指灾荒歉收之年。黎萌：即“黎民”、百姓。“虽非”二句说，虽不能同卫文公在楚丘的业绩相比，但遇上灾荒年，也能使百姓受益。
郑白渠：指郑国渠和白渠。郑国渠是战国末期秦国在韩人郑国指导下开凿的。分泾水东流，注入洛水。白渠是汉代白公设计开凿的。引泾水东南流，注入渭水。
天鉴：指上天监视着下界的善恶。倘：假如。不孤：不负。
兹：来年。验：检验，证明。微诚：微薄的诚心。这二句话是说如果上天不负有心人，来年定能丰收。', '这里的百姓，非常贫寒。遇到灾年就更加困难，我担心没有能力救济他们，忧虑就总是挂在心间。如今灾难降临，庄稼颗粒无收，荒芜丛生，杂草蔓延。这疾苦要捱到什么时间呀？不能让灾荒这样持续下去了，我要帮助他们，度过岁月的难关。要把兴修水利的蓝图绘好，筑好海堤，护卫良田；挖好乡村沟渠，引来涓涓流水，浇灌千里沃野，使黎民百姓安居乐业，迎来一个又一个丰收年。这功劳即使比不上郑渠和白渠，也要让我的努力和我的真诚，不辜负我热爱着的百姓和苍天！', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb2dbb8b379ee0a0e43", "shortContent": "谢灵运以其精深华妙的山水诗著名六朝诗坛，所作名篇佳什，多优游山水，无关民瘼，向有“学者之诗”的评语。与谢诗的总体倾向不同，《白石岩下径行田》这首诗在一定程度上流露出对民生疾苦的同情，是难能可贵的。《昭明文选》未收此诗，其后的评点家、诗论家亦鲜有言及者，也许是因为前人觉察到这首诗与谢灵运的为人和诗风不甚协调而有意回避之吧？殊不知，从这不协调中，正能发现谢灵运其人其诗的另一侧面，因此它更应引起重视。\n...", "authors": ["宋绪连"], "pressName": "上海辞书出版社"}]', '明代陈祚明《采菽堂古诗选》：“起四句，咏之恻然，足当《舂陵行》数篇。诗‘畇畇原隰’，简固佳，此四语繁亦不厌。千古咏田间景，逊此为妙。”', 'center', 1553685142, '5c9aea1542cda600685f9a24', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641527, '斋中读书诗 ', NULL, 0, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E6%96%8B%E4%B8%AD%E8%AF%BB%E4%B9%A6/1015985', '', '昔余游京华，未尝废丘壑。
矧乃归山川，心迹双寂寞。
虚馆绝诤讼，空庭来鸟雀。
卧疾丰暇豫，翰墨时间作。
怀抱观古今，寝食展戏谑。
既笑沮溺苦，又哂子云阁。
执戟亦以疲，耕稼岂云乐。
万事难并欢，达生幸可托。', '《斋中读书》是南朝宋诗人谢灵运创作的一首五言律诗。这首诗作纵向展开，从过去写到现在。开头两句说过去，接着四句主要讲述到永嘉担任地方官以后的情况。中间六句具体写读书的情形。结尾四句直接说到诗人自己的政治态度与生活情趣。这首诗从大处落笔，委婉见意，通篇又具有感情深沉凝重、语调平易亲切的特点。', '斋：指谢灵运在永嘉郡时的书斋。
京华：指当时的京都建康，即今南京。谢灵运来永嘉前曾在京都做官多年，游京华即指这一段时间。
废：忘怀。丘壑：泛指山水。
矧（shěn）乃：何况是。归山川：回归到山水之中，实际是指来到以山水闻名的永嘉郡。
心迹：指内心思想和事务行为两个方面。双寂寞：都感到空虚，即作永嘉太守既无事可想，也无事可干。
诤讼（zhèngsòng）：狱讼案件。
丰暇豫：多有闲暇安乐的日子。
翰墨：笔墨，代指文章诗赋。时间作：时常写一写。
怀抱：似指怀抱典籍图书。观古今：从典籍图书中观览古今人事。
戏谑：谈论说笑。《诗经·卫风·淇奥》：“善戏谑兮，不为虐兮。”
沮溺：指长沮和桀溺，春秋时贤人，不肯游仕，结伴耕种，一辈子辛苦劳作。《论语·微子》中记载，长沮与桀溺一同耕田，孔子经过时，叫他的学生子路向两人打问渡口的所在。后代诗文常用为避世隐士的典故，给予肯定的评价，如王粲《从军诗》说：“不能效沮溺，相随把锄犁。”陶渊明《劝农》诗说：“冀缺携俪，沮溺结耦。相彼贤达，犹勤垄亩。”
哂（shěn）：讥笑，嘲笑。子云阁：指扬雄投阁自杀一事。扬雄在西汉成帝时在朝为官，王莽篡汉，立“新”朝，扬雄作《剧秦美新》加以吹捧，并受任大夫之职校书天禄阁，后来因事被株连，投阁自杀，几乎死去。
执戟（jǐ）：秦汉时宫廷的侍卫官，因值勤时手执戟而得名，这里泛指做官。以疲：太疲倦。
岂云乐：哪里能算快乐。
达生：老庄的思想。《庄子》有《达生》篇，其中说：“达生之情者，不务生之所无以为。”所谓“生之所无以为”，是指分限以外的事物。', '曾在京都做官多年游览了不少地方，却从未忘怀过山水。
何况是来到以山水闻名的永嘉郡，内心思想和事务行为都感到空虚。
官衙内没有狱讼案件而显得清闲，官堂庭院空旷清静以致招来鸟雀止息觅食。
卧病在床多有闲暇安乐的日子，文章诗赋时常写一写。
怀抱典籍图书从典籍图书中观览古今人事，在寝卧饮食之时展开谈论说笑。
即嘲笑长沮和桀溺的苦，又讥笑扬雄投阁自杀一事。
做官既然太疲倦了，耕种哪里能算快乐。
要寻求解决世事难并欢的矛盾，只好寄希望于老庄的道家思想。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb203048e64fbd9c6d0", "shortContent": "南朝宋武帝永初三年（422），谢灵运由京官太子左卫率改任永嘉太守。长期以来，诗人被出仕与归隐的矛盾所困扰。由于仕途不顺利，政治理想无法实现，归隐的思想逐渐占了上风，在永嘉任职一年后，终于“称疾去职”（《宋书·谢灵运传》），开始了他那悠闲的隐居生活。《斋中读书》诗作于永嘉太守任上，相当典型地表现了他在仕隐问题上的思想矛盾，以及为了摆脱这一矛盾向老庄的“达生”思想的复归。\n全诗作纵向展开，从过去写到现...", "authors": ["陈志明"], "pressName": "上海辞书出版社"}]', '清·方东树《昭昧詹言》：“起四句入题，峥嵘飞动。‘虚馆’六句，交代正面。‘沮溺’四句，题后绕补，衔承谨密。收句，结束全篇。所谓‘达生’，取知足、知止义。杜公取适事莫并，又‘古来达士志，幽真愧双全’，同此。”', 'center', 1553685203, '5c9aea4ec05a800074477b9b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641531, '东阳溪中赠答二首 · 其一', NULL, 0, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E4%B8%9C%E9%98%B3%E6%BA%AA%E4%B8%AD%E8%B5%A0%E7%AD%94%E4%BA%8C%E9%A6%96/917970?fr=aladdin', '', '可怜谁家妇？缘流洗素足。
明月在云间，迢迢不可得。 ', '《东阳溪中赠答二首》是南朝宋诗人谢灵运创作的五言绝句组诗作品。第一首为男子所唱，写郎看妇犹如云间明月，可爱而不可就；第二首为女子所唱，写妇看郎，因见郎动情，当郎向她一问，她便立刻投入郎的怀抱。这组诗语言美妙自然，比喻生动形象。', '东阳溪，即东阳江（今金华江），流经今浙江东阳、金华一带。
可怜：可爱。
洒（xǐ）：通洗。
迢迢（tiáo）：高远。
', '可爱哟，这是谁家的妇人？就着这河流洗她那白皙的脚。
溪中美女和云中的明月一样，可望而不可得。
', NULL, '盐城师范学院文学院教授丁福林《谢灵运鲍照集》：“二诗都用明月作比，感情坦率健康，语言质朴晓畅，一反大谢诗富艳精工的风格，与文人此类作品的忸怩作态也大不相同，若置之于南朝乐府诗中恐难以辨其真伪。”', 'center', 1553685475, '5c9aeb29a3180b00686c89e6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641533, '登临海峤初发彊中作与从弟惠连可见羊何共和之', NULL, 0, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E7%99%BB%E4%B8%B4%E6%B5%B7%E5%B3%A4%E5%88%9D%E5%8F%91%E5%BD%8A%E4%B8%AD%E4%BD%9C%E4%B8%8E%E4%BB%8E%E5%BC%9F%E6%83%A0%E8%BF%9E%E5%8F%AF%E8%A7%81%E7%BE%8A%E4%BD%95%E5%85%B1', '', '杪秋寻远山，山远行不近。
与子别山阿，含酸赴修畛。
中流袂就判，欲去情不忍。
顾望脰未悁，汀曲舟已隐。
隐汀绝望舟，骛棹逐惊流。
欲抑一生欢，并奔千里游。
日落当栖薄，系缆临江楼。
岂惟夕情敛，忆尔共淹留。
淹留昔时欢，复增今日叹。
兹情已分虑，况乃协悲端。
秋泉鸣北涧，哀猿响南峦。
戚戚新别心，凄凄久念攒。
攒念攻别心，旦发清溪阴。
暝投剡中宿，明登天姥岑。
高高入云霓，还期那可寻。
傥遇浮丘公，长绝子徽音。', '《登临海峤初发彊中作与从弟惠连可见羊何共和之》是南朝宋诗人谢灵运创作的一首五言古诗。这首诗可分为四层，每八句一层。第一层写作者与谢惠连等依依惜别的场景。第二层写旅途的经过，看到惊流泛棹，日落栖泊，往事都来心头。第三层承接第二层，写昔日兄弟共游时欢乐融合的回忆反而更增加了现今别离后的伤感。第四层与首章相呼应，将与从弟的惜别伤感之情在远游的遐想中如丝如缕般延伸开去。这首诗用词精妙，虚实详略安排恰当，构思巧妙，耐人寻味。', '临海：郡名，今浙江省天台县。
峤（qiáo）：尖锐而高峻的山。
彊中：地名。《游名山志》：“桂林顶远则嵊尖强中。”今浙江嵊州有地名强口，即古之彊中。
从弟：堂弟，指谢惠连，也是宋初的著名诗人之一。
羊、何：羊璇之、何长瑜，皆谢灵运之友。
和（hè）：依照别人的诗词题材或形式另作诗词。
杪（miǎo）秋：晚秋，秋末。
子：男子美称，指谢惠连等。
别山阿：在山坡上道别。
酸：喻指离人心中的凄苦滋味。
修畛（zhěn）：漫长的路途，此泛指道路。
中流袂就判：船到水中，朋友问并连的衣袖就只好分开了。衣袖分开意味着分手离别。
顾望：回头看。
脰（dòu）：头颈。
悁（yuān）：通“痛”，酸痛，疲惫。
汀曲舟已隐：舟船因河道弯曲而隐没不见。汀，水边平地，这里指河道。
绝望：停止顾望。
骛棹（wùzhào）：猛力划桨。
逐惊流：在骇人的波浪里追逐前行。
抑：犹尽。《文选》注引《列子》公孙朝曰：“欲尽一生之欢，穷当年之乐。”或即与此意近。
并：共同。
栖薄（qībáo）：停泊住宿。“薄”通“泊”。
系缆：拴上缆绳，使船停住。
临江楼：楼名。《游名山志》：“从临江楼步路南上二里馀，左望湖中，右傍长江。”
敛（liǎn）：止息。
尔：你，指谢惠连。
淹留：长时间停留。
淹留昔时欢，复增今日叹：此两句大意与潘岳《哀永逝》“忆旧欢兮增新悲”同。
协：合。
悲端：悲愁的开端，指初秋。秋季象征着肃杀悲愁，故《楚辞》曰“悲哉秋之为气也”。
峦（luán）：山峦，山岭。
戚戚（戚）：忧愁的样子。
凄凄（qī）：悲伤的样子。
久念：旧时的思念。
攒（zǎn）：聚集。
攒念攻别心：萦绕难去的旧时思念和新近离别的愁苦心情纠缠在一起。
清溪：清澈的水流，指强口溪。
阴：水流的南岸。
暝（暝）：日暮，晚上。
剡（shàn）：古县名，属会稽郡，即今浙江省嵊县。
岑（cén）：小而高的山。
霓（ní）：虹，太阳斜照空中水汽而映现的光彩。
还期那可寻：言山高路远，哪能预料回家的日期。
浮丘公：接王子乔登山成仙的人。《列仙传》载：“王子乔好吹笙，道人浮丘公接以上嵩山。”
绝：断绝，不通。
子：指谢惠连。
徽（huī）音：佳音，美好的消息。', '晚秋寻找远方的山，远方的山想过去的话不是很近。
和谢惠连在山坡上道别，心中含着凄苦走上漫长的路途。
船到水中，朋友问并连的衣袖就只好分开了，想要离去但是心里又舍不得。
回头看直到头颈都酸痛疲倦了，舟船因河道弯曲而隐没不见。
船消失在河道才停止顾望，猛力划桨在骇人的波浪里追逐前行。
真想把一生的欢乐合在一起，与从弟并作这一次的千里之游。
当太阳落山了就停泊住宿，吧船上的缆绳系在临江楼上。
偏偏选中此地泊舟的理由，不仅是因为黄昏当息，更因为此地曾与从弟等同来共游。
故地独栖，回忆当时的情景，也是稍纾离思，慰情聊胜无的办法。
现在离别的感情只是刚开始，更何况这只是悲愁的开端。
耳畔只听得，秋泉活活，哀猿嗷嗷，悲愁断肠的秋声，弥漫在夹江两岸。
闻此，戚戚新别之心，更引动了旧事万千，都来心头。
不堪新愁旧悲转相交煎的心情，就计算起行程，明日从鬼谷子修行的清溪出发。
傍晚就可到达浙东名胜剡中，而后日清晨就可攀登“势拔五岳掩赤城”的天姥山了。
在高出尘嚣的云霓中徜徉，山高路远，哪能预料回家的日期。
要是意外遇到接王子乔登山成仙的人，就断绝了你谢惠连的美好消息了。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb32cee9a0c24eda8bb", "shortContent": "宋文帝刘义隆元嘉五年（428），谢灵运因文帝示意，上表陈疾，再次东归会稽故里。当初文帝登基，诛杀灵运宿敌徐羡之等，谢客曾满怀希望，就任秘书监丞，与修《晋书》。但宋帝所赏识谢灵运者，不过是他的族望与文才，实际上对他却心存疑忌，因而可以“慷慨”地称誉灵运的诗书为“二宝”，但却并不予以高位实权，灵运意殊不平，旷政游行，默示抗议，终于引来了这第二次的放归——贬逐。这次打击，较之前番外放永嘉更为沉重，绝望之...", "authors": ["赵昌平"], "pressName": "上海辞书出版社"}]', '浙江省古代文学学会常务理事俞樟华《池塘春草——谢灵运、孟浩然、王维诗选》：“钟嵘《诗品》谓谢灵运诗‘其源出于陈思’，这首诗可谓明证。此诗体制酷学曹植名篇《赠白马王彪》章章相联的笔法而有所创新，表达的感情也更加细腻复杂，锤炼经营的工夫也更加明显。”', 'center', 1553685552, '5c9aeba9fe88c2007080dd66', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641535, '初发石首城 ', NULL, 1, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E5%88%9D%E5%8F%91%E7%9F%B3%E9%A6%96%E5%9F%8E/999061?fr=aladdin', '', '白珪尚可磨，斯言易为缁。
遂抱中孚爻，犹劳贝锦诗。
寸心若不亮，微命察如丝。
日月垂光景，成贷遂兼兹。
出宿薄京畿，晨装抟曾飓。
重经平生别，再与朋知辞。
故山日已远，风波岂还时。
迢迢万里帆，茫茫欲何之？
游当罗浮行，息必庐霍期。
越海陵三山，游湘历九嶷。
钦圣若旦暮，怀贤亦凄其。
皎皎明发心，不为岁寒欺。', '《初发石首城》是南朝宋诗人谢灵运创作的一首五言古诗。全诗分四层，前八句叙述被诬与不罪之事，揭露并贬斥了孟颛的险恶用心，歌颂了宋文帝的圣明宽容。接下来八句，写自己再次背井离乡，辞别亲友，出任外宫，前途渺茫，归来无期。再四句写自己打算借这次出任之机去游历名山大川。最后四句，写自己缅怀古人，心中产生共鸣，决心向古入学习，保持高风亮节，不向恶势力低头。这首诗在表现上时以比兴出之，不是一味地作理语，诗中用字典重，既富有书卷气，又无不妥贴稳老，在语言上含英咀华、镕铸新词。', '石首城：即石头城，在今南京西南。
珪（guī）：瑞玉。
斯言：指会稽太守孟颛诬陷他图谋不轨的话。
缁（zī）：黑色。
中孚（fú）：《易经》中卦名，六十四卦之一。
爻（yáo）：《易经》中六爻的爻辞。《易·中孚》爻辞说：“中孚以利贞，乃应乎天也。”意谓心中诚信，应为吉利。
贝锦诗：指《诗经·小雅》中的《巷伯》诗，其中有“萋兮菲兮，成是锦贝”，意谓进谗言者罗织自己的过失以成罪名，犹如女工用五色丝编织织锦上的花纹一样。贝锦，指像贝的文采一样美丽的织锦。
若不亮：意谓假如不是被宋文帝所信任。亮，相信，信任。
光景：光辉，光亮，比喻恩泽。
成贷：语出《老子》第四十一章“夫唯道，善贷且成”，这里借指有幸保全生命。
兼兹：指出任临川内史。
出宿：出游之意。
薄：至，到。
京畿（jī）：京城的近郊，指石头城。
抟（tuán）曾飓：谓凭借风力挂帆而去。抟，凭借。曾飓，指疾风。
苕苕（tiáo）：遥远貌。苕通“迢”。
茫茫：广无边际的样子。
罗浮：山名，在今广东省。
庐霍：指庐山与霍山，分别在今江西与安徽二省，与上一句的“罗浮”都是古来传说中的求仙登遐之处。
三山：指蓬莱、方丈、瀛洲，为古代传说中的三座神山。
湘：指湘江。
九嶷（yí）：山名，与湘江都在今湖南省境内。
钦圣：倾慕圣人。圣，指虞舜，传说大舜南巡死后即葬于九嶷山。
旦暮：早晚。
贤：指屈原，屈原自沉于泪罗江，泪罗为湘江支流。
凄其：凄凉。
皎皎（jiǎo）：洁白明亮貌。
明发心：指光明磊落的心迹。明发，黎明，平明。', '白玉的污点还可以磨掉，而遭人诬陷诋毁，就难以申辩了。
即使是忠信端正的人，也仍然会因谗言而苦。
若不是文帝明了我的一片忠心的话，那我这条小命就会如同细小的丝线一样被轻易断杀了。
文帝的恩德像日月一样普照万物，恩赐我出任临川内史。
又一次对现在的事物告别，再一次与朋友知己辞别。
过去的山一天时间就离我很远，一路风急浪险，哪里还会有平安回归的时候。
千里迢迢舟行万里，广大无边我到底应该去哪里呢？
要想出游应该去罗浮山，休息的话就去庐山或者霍山停留。
登上传说中的蓬莱、方丈、瀛洲三座神山，畅游湘江游历九嶷山。
与舜心灵相通就好像早晚相处在一块，想着屈原也感到凄凉。
洁白明亮，光明磊落的心迹，决不向谗言恶运低头屈服。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb303048e64fbd9c6d5", "shortContent": "永嘉八年（431）春，谢灵运离开京都石首城（即石头城，在今南京西南），溯江西上赴任临川内史。其时诗人刚刚在一场政治风波中幸免于难，而前面等待着他的，仍是生死未卜的命运。由于他与会稽太守孟顗构成仇隙，孟上疏告他有“异志”，并“发兵自防，露板上言”，造成他有谋反行为的严重事态。谢灵运不得不仓皇赶到建康，向朝廷剖明心迹。这次宋文帝虽然暂没有治他的罪，可是不准他回始宁的老家，而把他外放到临川（治今江西抚州...", "authors": ["钟元凯"], "pressName": "上海辞书出版社"}]', '宋·方虚谷《瀛奎律髓》：“惜无同怀客，共登青云梯’，灵运每有赏心之叹，即义真所谓‘未能忘言于悟赏’。然则赏一也，有独赏，有共赏，灵运思夫共赏而不可得，则以独赏为憾，亦篇篇致言于斯。”
浙江省古代文学学会常务理事俞樟华《池塘春草——谢灵运、孟浩然、王维诗选》：“信而见疑，忠而被谤的事，历代都有。谢灵运自负才智，与刘宋当权者面和心不和，常常闹出一些不协调的事，对刘宋政权并不十分忠信，其被统治者猜忌、排斥，就在所难免了。这首诗大量化用《易》辞《庄》语，诉说自己遭谗受诬的委屈和离开京城之时的复杂感受，目的是剖明心迹，免除猜忌。”', 'center', 1553685648, '5c9aec0e17b54d0074a232fc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641542, '重阳志感', NULL, 2, 33, 0, 1, '秋瑾', NULL, 36401, '58309b9ea22b9d006b8637b6', '当代', 'shi', '诗', '', '', '容易东篱菊绽黄，却教风雨误重阳。
无端身世茫茫感，独上高楼一举觞。 ', '', '', '', NULL, '', 'center', 1553726971, '5c9b584e42cda60068698b4d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641554, '入华子岗是麻源第三谷五言', NULL, 0, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E5%85%A5%E5%8D%8E%E5%AD%90%E5%B2%97%E6%98%AF%E9%BA%BB%E6%BA%90%E7%AC%AC%E4%B8%89%E8%B0%B7%E4%BA%94%E8%A8%80/12688100', '', '南州实炎德，桂树凌寒山。
铜陵映碧涧，石磴泻红泉。
既枉隐沦客，亦栖肥遯贤。
险径无测度，天路非术阡。
遂登群峰首，邈若升云烟。
羽人绝仿佛，丹丘徒空筌。
图牒复摩灭，碑版谁闻传？
莫辩百世后，安知千载前。
且申独往意，乘月弄潺湲。
恒充俄顷用，岂为古今然！', '', '', '', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb32e6a6b501f967e4f", "shortContent": "人在对现世失望后，往往祈向神仙佛道，企望在作彼岸世界的徜徉想象中，获得对此岸世界失去的东西的补偿。而一旦到达彼岸世界也进而怀疑，进而不信，那么他也就大彻大悟，也就“嗒焉若丧”，“心如死灰”了。道家不同于道教，庄子笔下的神人与张天师也大异其趣，要领会道家的至妙玄理，还必须参透道教这一关，从对神仙化的世俗之欲中再超脱，达到至人无我的逍遥游的精神境界。然而虽说超脱，其骨子里，却仍是对人间世的翻了一个筋斗...", "authors": ["赵昌平"], "pressName": "上海辞书出版社"}]', '', 'center', 1553769822, '5c9c34dda3180b0068835158', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641555, '南楼中望所迟客 ', NULL, 1, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E5%8D%97%E6%A5%BC%E4%B8%AD%E6%9C%9B%E6%89%80%E8%BF%9F%E5%AE%A2/1000730?fr=aladdin', '', '杳杳日西颓，漫漫长路迫。
登楼为谁思？临江迟来客。
与我别所期，期在三五夕。
圆景早已满，佳人犹未适。
即事怨睽携，感物方凄戚。
孟夏非长夜，晦明如岁隔。
瑶华未堪折，兰苕已屡摘。
路阻莫赠问，云何慰离析？
搔首访行人，引领冀良觌。', '《南楼中望所迟客》是南朝宋诗人谢灵运创作的一首五言古诗。这首诗可以分为三部分。前八句为第一部分，写迟客不至的失望，通过回想月亮最圆、月色最好时与友人会面，更反衬了今日失望的深。中间八句为第二部分，大量引用《楚辞》中的典故，表现了对友人入骨的思念，也表现了对友人一种温情的体贴。最后两句为第三部分，写自己在焦急地询问友人的消息，企望着能与友人欢乐相会。这首诗用典故很多，切对人物心理变化写的非常细腻、深情。', '南楼：始宁墅中一座住宅的门楼。迟：等待。
杳杳（yǎo）：深远幽暗的样子。
迫：窘迫，着急。
为谁思：即思念谁。
三五夕：十五日的夜晚。
圆景：月亮。
佳人：指友人。
适：来也。
睽携（kuíxié）：分离。
方：常。
孟夏：初夏。
晦（huì）明：由黑暗到明亮，指一夜。
瑶华、兰苕（tiáo）：皆指香花美草。
搔首：爬弄头发，表示焦急。
引领：伸长颈项。
良觌（dí）：欢乐的会见。觌，相见。', '太阳在遥远的西方沉落，漫漫长路，依然不见他的踪影，我的心情，开始焦躁忐忑。
登上高楼，思念何人？望着流逝的江水，闷闷地等待着远方的友人前来赴约。
分手的时候，他和我约定，十五的晚上，要来看我。
今晚的月亮，早已圆满无缺，好友却迟迟没有前来赴约。
早知如此，当初就不该分手如今，望着孤零零的月儿，内心倍感忧伤凄切。
初夏的夜晚，应该并不漫长，可太阳再次升起的时候，却似乎经过了许多岁月。
疏麻的花，依然含苞未放，兰草的花，却已屡屡采摘。
搞得也是徒然，前方长路阻隔，无法把鲜花赠送，怎么安慰远离的你，孤独的我？
我焦躁不安，向行人打听你的消息，翘首等待，等待和你共享重逢的欢乐。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb3c6e67846a9219af0", "shortContent": "“南楼”，始宁墅中一座住宅的门楼。“迟”，等待。这诗是写伫望朋友来相会的心情。\n“杳杳日西颓，漫漫长路迫。”“杳杳”，深远幽暗的样子。“迫”，窘迫，着急。这两句是化用刘向《九叹·远逝》：“日杳杳以西颓兮，路长远而窘迫。”是说落日西沉了，而行人还困于漫漫长途。“杳杳”、“漫漫”两个叠词虽是描状客体，却也传达出主体那种莫可如何的惆怅。起句从傍晚写起，那么整个白天如何呢？读者不难想象。“登楼为谁思？临江...", "authors": ["汤华泉"], "pressName": "上海辞书出版社"}]', '浙江省古代文学学会常务理事俞樟华《池塘春草——谢灵运、孟浩然、王维诗选》：“古人云‘有朋自远方来，不亦乐乎？’但是相约的朋友未能及时赴约，却不免令人焦急失望。这首诗写的就是这种情景，作者先写等客不至的失望，再写与友人分别以来的情怀，后写与友人相会的企望，把思念友人的心理变化写的十分细腻、深情。”', 'center', 1553769908, '5c9c3532fe88c20070977cb7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641890, '湖学别苏召叟', NULL, 0, 451, 0, 1, '刘过', NULL, 10073, '57b9aa917db2a20068bdc258', '宋', 'shi', '诗', 'https://baike.baidu.com/item/%E6%B9%96%E5%AD%A6%E5%88%AB%E8%8B%8F%E5%8F%AC%E5%8F%9F/12665140', '', '失学老无成，宁不心自慊。
子聊生吾后，逸俟眼未见。
委身入罏锤，顾此金百炼。
有如顽钝质，岂可便磨划。
看君说经旨，不异瓴水建。
小诗虽有技，风味亦不浅。
我途未易穷。本自安眠饭。
俯仰道德光。耳目自濡染。
凉风忽秋思，一夜窗纸飐。
平生湖海梦，高兴动淮沔。
追思狂踪迹，失处不可掩。
醉捶黄鹤楼，一掷财百万。
只今觉衰甚，四海游已倦。
所馀习气在，未了一第欠。
师友贵隆亲，古学当自反。
小夫事机械，心甚山川险，
半生客吴粤，生死交情见。
谁知尘土中，得君初识面。
何时束装来，草草衾裘辨。
密迩恋轩诚，功名期岁晚。 ', '', '', '', NULL, '', 'center', 1554810008, '5cac1415c05a800073ed9240', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641905, '治西湖诗', NULL, 1, 7, 0, 2, '范雲', NULL, 35910, '5858fce4570c350069185f20', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E6%B2%BB%E8%A5%BF%E6%B9%96%E8%AF%97/12532795', '', '史氏导漳水，西门溉河潮。
图始未能悦，克终良可要。
拥锸劝年首，提爵劳春朝。
平皋草色嫩，通林鸟声娇。
已集故池鹜，行莳新田苗。
何吁畚筑苦，方欢鱼稻饶。', '', '', '', NULL, '', 'center', 1554892662, '5cad56eea3180b0068336d69', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641565, '庐陵王墓下作 ', NULL, 0, 135, 1, 0, '谢灵运', NULL, 10277, '57b903a57db2a2005426b53e', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E5%BA%90%E9%99%B5%E7%8E%8B%E5%A2%93%E4%B8%8B%E4%BD%9C/10921372?fr=aladdin', '', '晓月发云阳，落日次朱方。
含凄泛广川，洒泪眺连冈。
眷言怀君子，沉痛结中肠。
道消结愤懑，运开申悲凉。
神期恒若存，德音初不忘。
徂谢易永久，松柏森已行。
延州协心许，楚老惜兰芳。
解剑竟何及，抚坟徒自伤。
平生疑若人，通蔽互相妨。
理感深情恸，定非识所将。
脆促良可哀，夭枉特兼常。
一随往化灭，安用空名扬？
举声沥已洒，长叹不成章。', '《庐陵王墓下作》是南朝宋诗人谢灵运创作的一首五言古诗。这首诗的开头写诗人奉召还京，一早从丹阳出发，傍晚才到刘宋宗室的墓地。面对着庐陵王之墓，心头自是凄苦难言。他想到刘义真的为人，想到自己与义真的情谊以及义真的被害，自己因受牵连而被逐出京城等，便顿觉“沈痛切中肠”。而今，文帝当政，徐羡之等受到惩办，诗人也得能昭雪还京。“脆促”以下四句，悲痛之中包含着对统治者所玩弄的假仁假义的憎恨和厌恶。这首诗感情真挚，哀婉动人，“举声”“长叹”与发端的“含凄”“洒泪”互为照应，使前后融合为一，令人回味无穷。', '庐陵王：指宋武帝子刘义真。永初元年（423年），刘义真被封为庐陵孝献王，简称庐陵王。
晓月：月亮还没有完全隐没的拂晓时分。
发云阳：从云阳出发。云阳即今江苏省丹阳县。
次：途中临时住宿歇息。
朱方：春秋时地名，三国时称丹徒，即今江苏省镇江市。刘宋王朝宗室墓地所在。
泛广川：在广阔的江面上泛舟而行。
眺（tiào）连冈：远望安葬庐陵王的连绵山冈。青乌子《相冢书》：“天子葬高山，诸侯葬连冈。”连冈指连绵不断的低矮小山丘。
眷（juàn）言：思念的样子。言，作词尾，无实意。
君子：正派人，指庐陵王刘义真。
结中肠：一作“切中肠”。
道消：君子势力减弱以致为小人所欺。语本《周易·否卦》彖辞“内小人而外君子，小人道长君子道消也”，这里暗指少帝之时。
结愤懑（mèn）：悲愤郁积于胸。
运开：国运开张，正派人势力占上风，指文帝之初。其时拨乱反正，刘义真被枉杀事得到昭雪。
申悲凉：长期压抑的悲伤情绪得到伸展发泄。
神期：明灵精气。
恒若存：似觉永久存在。
德音：品行及音容笑貌。
初不忘：一点也没有忘记。
徂（cú）谢：去世，死亡。
延州：即延陵。本为地名，这里代指封于延陵的吴国王子季札。《新序·节士》有记叙：“延陵季子将西聘晋，带宝剑以过徐君。徐君观剑，不言而色欲之。延陵季子为有上国之使，未献也，然其心许之矣。致事于晋，顾反，则徐君死于楚……遂脱剑致之嗣君。嗣君曰：‘先君无命，孤不敢受剑。’于是季子以剑带徐君墓树而去。”
协心许：完成心中的许诺。
楚老惜兰芳：指楚地彭城一位老人悼念龚胜的故事。据《汉书·龚胜传》，龚胜是楚地人，因不愿为新莽王朝效力而自杀。有一同乡老父前来吊唁，抚坟痛哭，非常伤心。但他又感慨惋惜地说：“嗟乎！薰以香自烧，膏以明白销，龚先生竟天天年，非吾徒也。”于是赶快离开了。
平生：平时，以前，指诗人自己而言。
若人：这些人，指季札和楚老。
通蔽互相妨（fáng）：指季札和楚老这些人既有通智的一面，又有愚蔽的一面，互相抵触矛盾。
脆促：脆弱窘迫，指庐陵王生前所受的排挤欺压。
良：甚，很。
夭（yāo）枉：指庐陵玉受冤枉短命而死。
特兼常：其悲哀又特别要超过平常。
一随往化灭：一切都跟着死亡而消失。
空名扬：指原嘉三年为刘义真平反，恢复庐陵王封号，并追赠侍中、大将军等名号而言。
举声：放声痛哭。
沥（lì）：液体一滴一滴地往下掉，此指眼泪快流干了。
长叹不成章：由于过度悲伤，只能哀叹声声，连诗也写不成篇了。', '拂晓时分从云阳出发，晚上在朱方临时住宿歇息。
含着凄凉在广阔的江面上泛舟而行，流着泪远望安葬庐陵王的连绵山冈
思念正派人庐陵王刘义真，如同切伤腹中肠胃一般痛苦。
君子势力减弱以致为小人所欺，悲愤郁积于胸，文帝之初长期压抑的悲伤情绪得到伸展发泄。
明灵精气似觉永久存在，品行及音容笑貌一点也没有忘记。
死去的是永久的事情，墓旁的松柏数已经森然成形。
吴国王子季札完成心中的许诺，楚地彭城一位老人悼念龚胜的事情。
季札赠剑究竟有什么用，楚老悼念龚胜只会让自己感到悲伤。
自己以前怀疑季札和楚老，季札和楚老这些人既有通智的一面，又有愚蔽的一面，互相抵触矛盾。
以前老怀疑人家怎么会作出解剑、抚坟这样的荒唐事来，而今面对庐陵王的墓地，不禁悲从中来，才明白一个人的感情在受到深深刺激的时候，决不是理智识见所能控制得了的。
庐陵王生前所受的排挤欺压很是悲哀，受冤枉短命而死其悲哀又特别要超过平常。
一切都跟着死亡而消失，又何必恢复庐陵王封号，并追赠侍中、大将军等名号。
放声痛哭眼泪很快就流干了，由于过度悲伤，只能哀叹声声，连诗也写不成篇了。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb35914587d02f599e4", "shortContent": "在谈这首诗之前，必须简单介绍一下谢灵运与庐陵王的关系。庐陵王名刘义真，是宋武帝刘裕的次子。年纪虽小，对刘裕篡晋的做法却持保留态度，在刘裕诸子中算是个佼佼者。谢灵运出身豪门贵族，本来同刘宋王朝就存在着矛盾。刘裕称帝后，由于刘义真爱好文学，谢乃依附于义真。且义真尝言，自己如果得志，将以谢灵运、颜延之为宰相。可见他们之间有着特殊的政治关系。未几刘裕死，长子义符即位，是为少帝。他当然容不下条件比他优越的刘...", "authors": ["吴小如"], "pressName": "上海辞书出版社"}]', '清·陈祚明《采菽堂古诗选》：“常论康乐情深而多爱人也，惟其多爱，故山水亦爱，友朋亦爱。观墓下之作，哀惨异常，知忠义之感，亦非全伪。”
清·王夫之《古诗评选》：“古今第一首挽诗。”', 'center', 1553770259, '5c9c369117b54d0074b8deb4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641568, '满江红·己巳二月二十二日游北门，有感', NULL, 19, 656, 1, 1, '陆文圭', NULL, 11145, '5858e62eb123db00658d7b64', '元', 'ci', '词', '', '', '试检春光，都不在，槿篱茅屋。荒城外，牯眠衰草，鸦啼枯木。黄染菜花无意绪，青描柳叶浑粗俗。忆繁华，不似少年游，伤心目。
棠坞锦，梨园玉。燕衣舞，莺簧曲。艳阳天，输与午桥金谷。行处绮罗香不断，归时弦管声相逐。怕夕阳，影散近黄昏，烧银烛。', '', '', '', NULL, '', 'indent', 1553813459, '5c9cdf45c05a8000746ab13d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641615, '史记 · 七十列传 · 仲尼弟子列传', NULL, 2, 139, 0, 1, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', 'https://baike.baidu.com/item/%E4%BB%B2%E5%B0%BC%E5%BC%9F%E5%AD%90%E5%88%97%E4%BC%A0/2438460?fr=aladdin', '', '孔子曰“受业身通者七十有七人”，皆异能之士也。德行：颜渊，闵子骞，冉伯牛，仲弓。政事：冉有，季路。
言语：宰我，子贡。文学：子游，子夏。师也辟，参也鲁，柴也愚，由也喭，回也屡空。赐不受命而货殖焉，亿则屡中。
孔子之所严事：于周则老子；于卫，蘧伯玉；于齐，晏平仲；于楚，老莱子；于郑，子产；于鲁，孟公绰。数称臧文仲、柳下惠、铜鞮伯华、介山子然，孔子皆后之，不并世。
颜回者，鲁人也，字子渊。少孔子三十岁。
颜渊问仁，孔子曰：“克己复礼，天下归仁焉。”
孔子曰：“贤哉回也！一箪食，一瓢饮，在陋巷，人不堪其忧，回也不改其乐。”“回也如愚；退而省其私，亦足以发，回也不愚。”“用之则行，舍之则藏，唯我与尔有是夫！”
回年二十九，发尽白，蚤死。孔子哭之恸，曰：“自吾有回，门人益亲。”
鲁哀公问：“弟子孰为好学？”孔子对曰：“有颜回者好学，不迁怒，不贰过。不幸短命死矣，今也则亡，未闻好学者也。”
闵损字子骞。少孔子十五岁。
孔子曰：“孝哉闵子骞！人不间于其父母昆弟之言。”不仕大夫，不食污君之禄。“如有复我者，必在汶上矣。”
冉耕字伯牛。孔子以为有德行。
伯牛有恶疾，孔子往问之，自牖执其手，曰：“命也夫！斯人也而有斯疾，命也夫！”
冉雍字仲弓。
仲弓问政，孔子曰：“出门如见大宾，使民如承大祭。在邦无怨，在家无怨。”
孔子以仲弓为有德行，曰：“雍也可使南面。”
仲弓父，贱人。孔子曰：“犁牛之子骍且角，虽欲勿用，山川其舍诸？”
冉求字子有，少孔子二十九岁。为季氏宰。
季康子问孔子曰：“冉求仁乎？”曰：“千室之邑，百乘之家，求也可使治其赋。仁则吾不知也。”复问：“子路仁乎？”孔子对曰：“如求。”
求问曰：“闻斯行诸？”子曰：“行之。”子路问：“闻斯行诸？”子曰：“有父兄在，如之何其闻斯行之！”子华怪之，“敢问问同而答异？”孔子曰：“求也退，故进之。由也兼人，故退之。”
仲由字子路，卞人也。少孔子九岁。
子路性鄙，好勇力，志伉直，冠雄鸡，佩豭豚，陵暴孔子。孔子设礼稍诱子路，子路后儒服委质，因门人请为弟子。
子路问政，孔子曰：“先之，劳之。”请益。曰：“无倦。”
子路问：“君子尚勇乎？”孔子曰：“义之为上。君子好勇而无义则乱，小人好勇而无义则盗。”
子路有闻，未之能行，唯恐有闻。
孔子曰：“片言可以折狱者，其由也与！”“由也好勇过我，无所取材。”“若由也，不得其死然。”“衣敝缊袍与衣狐貉者立而不耻者，其由也与！”“由也升堂矣，未入于室也。”
季康子问：“仲由仁乎？”孔子曰：“千乘之国可使治其赋，不知其仁。”
子路喜从游，遇长沮、桀溺、荷丈人。
子路为季氏宰，季孙问曰：“子路可谓大臣与？”孔子曰：“可谓具臣矣。”
子路为蒲大夫，辞孔子。孔子曰：“蒲多壮士，又难治。然吾语汝：恭以敬，可以执勇；宽以正，可以比众；恭正以静，可以报上。”
初，卫灵公有宠姬曰南子。灵公太子蒉聩得过南子，惧诛出奔。及灵公卒而夫人欲立公子郢。郢不肯，曰：“亡人太子之子辄在。”于是卫立辄为君，是为出公。出公立十二年，其父蒉聩居外，不得入。子路为卫大夫孔悝之邑宰。蒉聩乃与孔悝作乱，谋入孔悝家，遂与其徒袭攻出公。出公奔鲁，而蒉聩入立，是为庄公。方孔悝作乱，子路在外，闻之而驰往。遇子羔出卫城门，谓子路曰：“出公去矣，而门已闭，子可还矣，毋空受其祸。”
子路曰：“食其食者不避其难。”
子羔卒去。有使者入城，城门开，子路随而入。造蒉聩，蒉聩与孔悝登台。子路曰：“君焉用孔悝？请得而杀之。”蒉聩弗听。于是子路欲燔台，蒉聩惧，乃下石乞、壶黡攻子路，击断子路之缨。子路曰：“君子死而冠不免。”遂结缨而死。
孔子闻卫乱，曰：“嗟乎，由死矣！”已而果死。故孔子曰：“自吾得由，
恶言不闻于耳。”是时子贡为鲁使于齐。
宰予字子我。利口辩辞。既受业，问：“三年之丧不已久乎？君子三年不为礼，礼必坏；三年不为乐，乐必崩。旧谷既没，新谷既升，钻燧改火，期可已矣。”
子曰：“于汝安乎？”曰：“安。”“汝安则为之。君子居丧，食旨不甘，闻乐不乐，故弗为也。”宰我出，子曰：“予之不仁也！子生三年然后免于父母之怀。夫三年之丧，天下之通义也。”
宰予昼寝。子曰：“朽木不可雕也，粪土之墙不可圬也。”
宰我问五帝之德，子曰：“予非其人也。”
宰我为临菑大夫，与田常作乱，以夷其族，孔子耻之。
端沐赐，卫人，字子贡。少孔子三十一岁。子贡利口巧辞，孔子常黜其辩。问曰：“汝与回也孰愈？”对曰：“赐也何敢望回！回也闻一以知十，赐也闻一以知二。”
子贡既已受业，问曰：“赐何人也？”孔子曰：“汝器也。”曰：“何器也？”曰：“瑚琏也。”卫公孙朝问子贡曰：“仲尼焉学？”子贡曰：“文武之道未坠于地，在人，贤者识其大者，不贤者识其小者，莫不有文武之道。夫子焉不学，而亦何常师之有！”
又问曰：“孔子适是国必闻其政。求之与？抑与之与？”子贡曰：“夫子温良恭俭让以得之。夫子之求之也，其诸异乎人之求之也。”
子贡问曰：“富而无骄，贫而无谄，何如？”孔子曰：“可也；不如贫而乐道，富而好礼。”
田常欲作乱于齐，惮高、国、鲍、晏，故移其兵欲以伐鲁。孔子闻之，谓门弟子曰：“夫鲁，坟墓所处，父母之国，国危如此，二三子何为莫出？”子路请出，孔子止之。子张、子石请行，孔子弗许。子贡请行，孔子许之。
遂行，至齐，说田常曰：“君之伐鲁过矣。夫鲁，难伐之国，其城薄以卑，其地狭以泄，其君愚而不仁，大臣伪而无用，其士民又恶甲兵之事，此不可与战。君不如伐吴。夫吴，城高以厚，地广以深，甲坚以新，士选以饱，重器精兵尽在其中，又使明大夫守之，此易伐也。”田常忿然作色曰：“子之所难，人之所易；子之所易，人之所难：而以教常，何也？”
子贡曰：“臣闻之，忧在内者攻彊，忧在外者攻弱。今君忧在内。吾闻君三封而三不成者，大臣有不听者也。今君破鲁以广齐，战胜以骄主，破国以尊臣，而君之功不与焉，则交日疏于主。是君上骄主心，下恣群臣，求以成大事，难矣。夫上骄则恣，臣骄则争，是君上与主有却，下与大臣交争也。如此，则君之立于齐危矣。故曰不如伐吴。伐吴不胜，民人外死，大臣内空，是君上无彊臣之敌，下无民人之过，孤主制齐者唯君也。”
田常曰：“善。虽然，吾兵业已加鲁矣，去而之吴，大臣疑我，柰何？”
子贡曰：君按兵无伐，臣请往使吴王，令之救鲁而伐齐，君因以兵迎之。”田常许之，使子贡南见吴王。
说曰：“臣闻之，王者不绝世，霸者无强敌，千钧之重加铢两而移。今以万乘之齐而私千乘之鲁，与吴争彊，窃为王危之。且夫救鲁，显名也；伐齐，大利也。以抚泗上诸侯，诛暴齐以服彊晋，利莫大焉。名存亡鲁，实困彊齐。智者不疑也。”
吴王曰：“善。虽然，吾尝与越战，栖之会稽。越王苦身养士，有报我心。子待我伐越而听子。”子贡曰：“越之劲不过鲁，吴之彊不过齐，王置齐而伐越，则齐已平鲁矣。且王方以存亡继绝为名，夫伐小越而畏彊齐，非勇也。夫勇者不避难，仁者不穷约，智者不失时，王者不绝世，以立其义。今存越示诸侯以仁，救鲁伐齐，威加晋国，诸侯必相率而朝吴，霸业成矣。且王必恶越，臣请东见越王，令出兵以从，此实空越，名从诸侯以伐也。”吴王大说，乃使子贡之越。
越王除道郊迎，身御至舍而问曰：“此蛮夷之国，大夫何以俨然辱而临之？”
子贡曰：“今者吾说吴王以救鲁伐齐，其志欲之而畏越，曰‘待我伐越乃可’。如此，破越必矣。且夫无报人之志而令人疑之，拙也；有报人之志，使人知之，殆也；事未发而先闻，危也。三者举事之大患。”
句践顿首再拜曰：“孤尝不料力，乃与吴战，困于会稽，痛入于骨髓，日夜焦唇干舌，徒欲与吴王接踵而死，孤之愿也。”遂问子贡。子贡曰：“吴王为人猛暴，群臣不堪；国家敝以数战，士卒弗忍；百姓怨上，大臣内变；子胥以谏死，太宰嚭用事，顺君之过以安其私：是残国之治也。今王诚发士卒佐之徼其志，重宝以说其心，卑辞以尊其礼，其伐齐必也。彼战不胜，王之福矣。战胜，必以兵临晋，臣请北见晋君，令共攻之弱吴必矣。其锐兵尽于齐，重甲困于晋，而王制其敝，此灭吴必矣。”越王大说，许诺。送子贡金百镒，剑一，良矛二。
子贡不受，遂行。报吴王曰：“臣敬以大王之言告越王，越王大恐，曰：‘孤不幸，少失先人，内不自量，抵罪于吴，军败身辱，栖于会稽，国为虚莽，赖大王之赐，使得奉俎豆而修祭祀，死不敢忘，何谋之敢虑！’”后五日，越使大夫种顿首言于吴王曰：“东海役臣孤句践使者臣种，敢修下吏问于左右。今窃闻大王将兴大义，诛彊救弱，困暴齐而抚周室，请悉起境内士卒三千人，孤请自被坚执锐，以先受矢石。因越贱臣种奉先人藏器，甲二十领，鈇屈卢之矛，步光之剑，以贺军吏。”
吴王大说，以告子贡曰：“越王欲身从寡人伐齐，可乎？”
子贡曰：“不可。夫空人之国，悉人之众，又从其君，不义。君受其币，许其师，而辞其君。”吴王许诺，乃谢越王。于是吴王乃遂发九郡兵伐齐。子贡因去之晋，谓晋君曰：“臣闻之，虑不先定不可以应卒，兵不先辨不可以胜敌。今夫齐与吴将战，彼战而不胜，越乱之必矣；与齐战而胜，必以其兵临晋。”
晋君大恐，曰：“为之柰何？”
子贡曰：“修兵休卒以待之。”晋君许诺。
子贡去而之鲁。吴王果与齐人战于艾陵，大破齐师，获七将军之兵而不归，果以兵临晋，与晋人相遇黄池之上。吴晋争彊。晋人击之，大败吴师。越王闻之，涉江袭吴，去城七里而军。吴王闻之，去晋而归，与越战于五湖。三战不胜，城门不守，越遂围王宫，杀夫差而戮其相。破吴三年，东向而霸。
故子贡一出，存鲁，乱齐，破吴，强晋而霸越。子贡一使，使势相破，十年之中，五国各有变。
子贡好废举，与时转货赀。喜扬人之美，不能匿人之过。常相鲁卫，家累千金，卒终于齐。
言偃，吴人，字子游。少孔子四十五岁。
子游既已受业，为武城宰。孔子过，闻弦歌之声。孔子莞尔而笑曰：“割鸡焉用牛刀？”子游曰：“昔者偃闻诸夫子曰，君子学道则爱人，小人学道则易使。”
孔子曰：“二三子，偃之言是也。前言戏之耳。”孔子以为子游习于文学。
卜商字子夏。少孔子四十四岁。
子夏问：“‘巧笑倩兮，美目盼兮，素以为绚兮’，何谓也？”子曰：“绘
事后素。”曰：“礼后乎？”孔子曰：“商始可与言诗已矣。”
子贡问：“师与商孰贤？”
子曰：“师也过，商也不及。”“然则师愈与？”曰：“过犹不及。”
子谓子夏曰：“汝为君子儒，无为小人儒。”
孔子既没，子夏居西河教授，为魏文侯师。其子死，哭之失明。
颛孙师，陈人，字子张。少孔子四十八岁。
子张问干禄，孔子曰：“多闻阙疑，慎言其馀，则寡尤；多见阙殆，慎行其馀，则寡悔。言寡尤，行寡悔，禄在其中矣。”
他日从在陈蔡间，困，问行。孔子曰：“言忠信，行笃敬，虽蛮貊之国行也；言不忠信，行不笃敬，虽州里行乎哉！立则见其参于前也，在舆则见其倚于衡，夫然后行。”子张书诸绅。
子张问：“士何如斯可谓之达矣？”孔子曰：“何哉，尔所谓达者？”子张对曰：“在国必闻，在家必闻。”孔子曰：“是闻也，非达也。夫达者，质直而好义，察言而观色，虑以下人，在国及家必达。夫闻也者，色取仁而行违，居之不疑，在国及家必闻。”
曾参，南武城人，字子舆。少孔子四十六岁。
孔子以为能通孝道，故授之业。作孝经。死于鲁。
澹台灭明，武城人，字子羽。少孔子三十九岁。状貌甚恶。欲事孔子，孔子以为材薄。既已受业，退而修行，行不由径，非公事不见卿大夫。
南游至江，从弟子三百人，设取予去就，名施乎诸侯。孔子闻之，曰：“吾以言取人，失之宰予；以貌取人，失之子羽。”
宓不齐字子贱。少孔子三十岁。
孔子谓“子贱君子哉！鲁无君子，斯焉取斯？”
子贱为单父宰，反命于孔子，曰：“此国有贤不齐者五人，教不齐所以治者。”
孔子曰：“惜哉不齐所治者小，所治者大则庶几矣。”
原宪字子思。
子思问耻。孔子曰：“国有道，谷。国无道，谷，耻也。”
子思曰：“克伐怨欲不行焉，可以为仁乎？”孔子曰：“可以为难矣，仁则吾弗知也。”
孔子卒，原宪遂亡在草泽中。子贡相卫，而结驷连骑，排藜藿入穷阎，过谢原宪。宪摄敝衣冠见子贡。子贡耻之，曰：“夫子岂病乎？”原宪曰：“吾闻之，无财者谓之贫，学道而不能行者谓之病。若宪，贫也，非病也。”子贡惭，不怿而去，终身耻其言之过也。
公冶长，齐人，字子长。
孔子曰：“长可妻也，虽在累绁之中，非其罪也。”以其子妻之。
南宫括字子容。
问孔子曰：“羿善射，奡荡舟，俱不得其死然；禹稷躬稼而有天下？”孔子弗答。容出，孔子曰：“君子哉若人！上德哉若人！”“国有道，不废；国无道，免于刑戮。”三复“白珪之玷”，以其兄之子妻之。
公皙哀字季次。
孔子曰：“天下无行，多为家臣，仕于都；唯季次未尝仕。”
曾蒧字皙。
侍孔子，孔子曰：“言尔志。”蒧曰：“春服既成，冠者五六人，童子六七人，浴乎沂，风乎舞雩，咏而归。”孔子喟尔叹曰：“吾与蒧也！”
颜无繇字路。路者，颜回父，父子尝各异时事孔子。
颜回死，颜路贫，请孔子车以葬。孔子曰：“材不材，亦各言其子也。鲤也死，有棺而无椁，吾不徒行以为之椁，以吾从大夫之后，不可以徒行。”
商瞿，鲁人，字子木。少孔子二十九岁。
孔子传易于瞿，瞿传楚人馯臂子弘，弘传江东人矫子庸疵，疵传燕人周子家竖，竖传淳于人光子乘羽，羽传齐人田子庄何，何传东武人王子中同，同传菑川人杨何。何元朔中以治易为汉中大夫。
高柴字子羔。少孔子三十岁。
子羔长不盈五尺，受业孔子，孔子以为愚。
子路使子羔为费郈宰，孔子曰：“贼夫人之子！”子路曰：“有民人焉，有社稷焉，何必读书然后为学！”孔子曰：“是故恶夫佞者。”
漆雕开字子开。
孔子使开仕，对曰：“吾斯之未能信。”孔子说。
公伯缭字子周。
周愬子路于季孙，子服景伯以告孔子，曰：“夫子固有惑志，缭也吾力犹能
肆诸市朝。”孔子曰：“道之将行，命也；道之将废，命也。公伯缭其如命何！”
司马耕字子牛。
牛多言而躁。问仁于孔子，孔子曰：“仁者其言也讱。”曰：“其言也讱，斯可谓之仁乎？”子曰：“为之难，言之得无讱乎！”问君子，子曰：“君子不忧不惧。”曰：“不忧不惧，斯可谓之君子乎？”子曰：“内省不疚，夫何忧何惧！”
樊须字子迟。少孔子三十六岁。
樊迟请学稼，孔子曰：“吾不如老农。”请学圃，曰：“吾不如老圃。”樊
迟出，孔子曰：“小人哉樊须也！上好礼，则民莫敢不敬；上好义，则民莫敢不服；上好信，则民莫敢不用情。夫如是，则四方之民襁负其子而至矣，焉用稼！”
樊迟问仁，子曰：“爱人。”问智，曰：“知人。”
有若少孔子四十三岁。有若曰：“礼之用，和为贵，先王之道斯为美。小大
由之，有所不行；知和而和，不以礼节之，亦不可行也。”“信近于义，言可复也；恭近于礼，远耻辱也；因不失其亲，亦可宗也。”
孔子既没，弟子思慕，有若状似孔子，弟子相与共立为师，师之如夫子时也。
他日，弟子进问曰：“昔夫子当行，使弟子持雨具，已而果雨。弟子问曰：‘夫子何以知之？’夫子曰：‘诗不云乎？“月离于毕，俾滂沱矣。”昨暮月不宿毕乎？’他日，月宿毕，竟不雨。商瞿年长无子，其母为取室。孔子使之齐，瞿母请之。孔子曰：‘无忧，瞿年四十后当有五丈夫子。’已而果然。敢问夫子何以知此？”有若默然无以应。弟子起曰：“有子避之，此非子之座也！”
公西赤字子华。少孔子四十二岁。
子华使于齐，冉有为其母请粟。孔子曰：“与之釜。”请益，曰：“与之庾。”
冉子与之粟五秉。孔子曰：“赤之适齐也，乘肥马，衣轻裘。吾闻君子周急不继富。”
巫马施字子旗。少孔子三十岁。
陈司败问孔子曰：“鲁昭公知礼乎？”孔子曰：“知礼。”退而揖巫马旗曰：“吾闻君子不党，君子亦党乎？鲁君娶吴女为夫人，命之为孟子。孟子姓姬，讳称同姓，故谓之孟子。鲁君而知礼，孰不知礼！”施以告孔子，孔子曰：“丘也幸，苟有过，人必知之。臣不可言君亲之恶，为讳者，礼也。”
梁鳣字叔鱼。少孔子二十九岁。
颜幸字子柳。少孔子四十六岁。
冉孺字子鲁，少孔子五十岁。
曹恤字子循。少孔子五十岁。
伯虔字子析，少孔子五十岁。
公孙龙字子石。少孔子五十三岁。
自子石已右三十五人，显有年名及受业见于书传。其四十有二人，无年及不
见书传者纪于左：
冉季字子产。
公祖句兹字子之。
秦祖字子南。
漆雕哆字子敛。
颜高字子骄。
漆雕徒父。
壤驷赤字子徒。
商泽。
石作蜀字子明。
任不齐字选。
公良孺字子正。
后处字子里。
秦冉字开。
公夏首字乘。
奚容箴字子皙。
公肩定字子中。
颜祖字襄。
鄡单字子家。
句井疆。
罕父黑字子索。
秦商字子丕。
申党字周。
颜之仆字叔。
荣旗（荣旗）字子祈。
县成字子祺。
左人郢字行。
燕伋字思。
郑国字子徒。
秦非字子之。
施之常字子恒。
颜哙字子声。
步叔乘字子车。
原亢籍。
乐欬字子声。
廉絜字庸。
叔仲会字子期。
颜何字冉。
狄黑字皙。
邦巽字子敛。
孔忠。
公西舆如字子上。
公西葴字子上。
太史公曰：学者多称七十子之徒，誉者或过其实，毁者或损其真，钧之未睹厥容貌，则论言弟子籍，出孔氏古文近是。余以弟子名姓文字悉取论语弟子问并次为篇，疑者阙焉。', '《仲尼弟子列传》是西汉史学家司马迁创作的一篇文言文，收录于《史记》中。是孔门弟子的一篇多人合传。仲尼，即孔子。在这篇列传中，有的人记述较详，洋洋洒洒一大篇；有的人记述简略，只有两个字的人名。本传主要记述了孔子及其弟子的言语和行事。孔子是我国古代伟大的思想家、教育家，虽然他“述而不作”，但他总结了前人的文化遗产并传授给学生，打破了贵族垄断教育的局面，首创私人讲学的风气，得以弟子三千，育有大贤七十。本传在记述之中，仍然保留了孔子与弟子的问答形式。', '', '孔子说：“跟着我学习而精通六艺的弟子有七十七人”，他们都是具有奇异才能的人。德行方面突出的：颜渊，闵子骞，冉伯牛，仲弓。擅长处理政事的：冉有，季路。语言方面的：宰我，子贡。文章博学方面的：子游，子夏。颛孙师偏激，曾参迟钝，高柴愚笨，仲由粗鲁，颜回经常贫穷无所有。端木赐不接受命运的摆布而去经营商业，不过他推测的行情经常是准确的。
孔子所礼敬的人：在周朝是老子；在卫国是蘧伯玉；在齐国是晏仲平；在楚国是老莱子；在郑国是子产；在鲁国是孟公绰。他也经常称颂臧文仲、柳下惠、铜鞮伯华、介山子然，孔子出生的时间比他们都晚，不是同一时代的人。
颜回，是鲁国人，字子渊。比孔子小三十岁。
颜渊问什么是仁，孔子说：“约束自己，使你的言行符合于礼，天下的人就会称许你是有仁德的人了。”
孔子说：“颜回！多么德的人啊！吃的是一小竹筐饭，喝的是一瓢水，住在简陋的胡同里，一般人忍受不了这种困苦，颜回却也不改变自己的乐趣。听我授业时，颜回像个蠢笨的人，下课后考察他私下的言谈，也能够刻意发挥，颜回实在不笨。”“任用你的时候，就匡时救世，不被任用的时候，就藏道在身，只有我和你才有这样的处世态度吧！”
颜回才二十九岁，头发就全白了，过早的死去。孔子哭得特别伤心，说：“自从我有了颜回，学生们越来越和我亲近。”鲁哀公问：“学生中谁是最好学习的？”孔子回答说：“有个叫颜回的人最好学习，从不把怒火转移到别人身上，不再犯同样的过失。不幸的是寿命很短，死了，现在就没有这样的人了。”
闵损，字子骞，比孔子小十五岁。
孔子说：“闵子骞太孝顺啦！他侍奉父母，顺从兄弟，别人对他的父母兄弟夸赞他都没有非议的闲话。”他不做大夫的家臣，不要昏君的俸禄。
所以他说：“如果有人再来召我，我一定逃到汶水以北了。”
冉耕，字伯牛。孔子认为他有德行。
伯牛得了难治的病，孔子前去问候他，从窗户里握手住他的手，说：“这是命啊！这样好的人却得了这样的病，这是命啊！”
冉雍，字仲弓。
仲弓问如何处理政事，孔子说：“出门做事如同接待贵宾一样谦恭有礼，使用百姓如同承办隆重的祭典一样虔诚谨慎。这样，在诸侯的封国里任职，就没人怨恨你，在卿大夫的家邑里任职也不会有人怨恨你。”
孔子认为仲弓在德行方面有成就，说：“冉雍啊，可以让他作个卿大夫一样的大官。”
仲弓的父亲，是个地位卑微的人。孔子打比方说：“杂色牛生出红色的小牛，两角长得周正，即便你不想用它作祭品，山川的神灵难道会舍弃它吗？”
冉求，字子有，比孔子小二十九岁。作季氏家臣之长。
季康子问孔子说：“冉求有仁德吗？”孔子回答说：“有千户人家的城邑，有百辆兵车的采邑，冉求能够把那里的军政事物管理好。至于他仁德不仁德，我就不知道了。”季康子又问：“子路有仁德吗？”孔子回答说：“象冉求一样。”
冉求问孔子说：“听到应做的事情就立刻行动吗？”孔子回答说：“立刻行动。”子路问孔子说：“听到应做的事就应该立刻行动吗？”孔子回答说：“有父亲兄长在，怎么听到就能立刻行动呢？”子华感到这件事很奇怪，不解地说：“我大胆地问问，为什么问同样的问题而回答却不一样呢？”孔子回答说：“冉求做事畏缩多虑，所以我激励他。仲由做事有两个人的胆量，所以我要抑制他。”
仲由，字子路，卞地人。比孔子小九岁。
子路性情粗朴，喜欢逞勇斗力，志气刚强，性格直爽，头戴雄鸡式的帽子，佩戴着公猪皮装饰的宝剑，曾经欺凌孔子。孔子用礼乐慢慢地诱导他，后来，子路穿着儒服，带着拜师的礼物，通过孔子学生的引荐，请求作孔子的学生。
子路问如何处理政事，孔子说：“自己先给百姓作出榜样，然后才能使百姓辛勤地劳作。”子路请求进一步讲讲。孔子说：“持久不懈。”
子路问：“君子崇尚勇敢吗？”孔子说：“君子最崇尚的是义。君子只好勇而不崇尚义，就会叛逆作乱。小人只好勇而不崇尚义，就会做强盗。”
子路要听到什么道理，没有马上行动，只怕又听到别的道理。
孔子说：“只听单方面言辞就可以决断案子的，恐怕只有仲由吧！”“仲由崇尚勇敢超过我之所用，就不适用了。”像仲由这种性情，不会得到善终。”“穿着用乱麻絮做的破旧袍子和穿着裘皮大衣的人站在一起而不认为羞愧的，恐怕只有仲由吧！”“仲由的学问好像登上了正厅，可是还没能进入内室呢。”
季康子问道：“仲由有仁德吗？”孔子答说：“拥有一千辆兵车的国家，可以让他管理军政事务，至于他有没有仁德，我就不知道了。”
子路喜欢跟随孔子出游，曾遇到过长沮、桀溺、扛着农具的老人等隐士。
子路出任季氏的家臣，季孙问孔子说：“子路可以说是人臣了吗？”孔子回答说：“可以说是备位充数的臣子了。”
子路出任蒲邑的大夫，向孔子辞行。孔子说：“蒲邑勇武之士很多，又难治理。可是，我告诉你：恭谨谦敬，就可以驾驭勇武的人；宽厚清正，就可以使大家亲近；恭谨清正而社会安静，就可以用来报效上司了。”
当初，卫灵公有位宠姬叫作南子。灵公的太子蒉聩曾得罪过她，害怕被谋杀就逃往国外。等到灵公去世，夫人南子想让公子郢继承王位。公子郢不肯接受，说：“太子虽然逃亡了，太子的儿辄还在。”于是卫国立了辄为国君，这就是卫出公。出公继位十二年，他的父亲蒉聩一直留在国外，不能够回来。这时子路担任卫国大夫孔悝采邑的长官。蒉聩就和孔悝一同作乱，想办法带人潜入孔悝家，就和他的党徒去袭击卫出公。出公逃往鲁国，蒉聩进宫继位，这就卫庄公。当孔悝作乱时，子路还有事在外，听到这个消息就立刻赶回来。子羔从卫国城门出来，正好相遇，对子路说：“卫出公逃走了，城门已经关闭，您可以回去了，不要为他遭受祸殃。”子路说：“吃着人家的粮食就不能回避人家的灾难。”子羔终于离去了。正赶上有使者要进城，城门开了，子路就跟了进去。找到蒉聩，蒉聩和孔悝都在台上。子路说：“大王为什么要任用孔悝呢？请让我捉住他杀了。”蒉聩不听从他的劝说。于是子路要放火烧台，蒉聩害怕了，于是叫石乞、壶黡到台下去攻打子路，斩断了子路的帽带。子路说：“君子可以死，帽子不能掉下来。”说完系好帽子就死了。
孔子听到卫国发生暴乱的消息，说：“唉呀，仲由死了！”不久，果真传来了他的死讯。所以孔子说：“自从我有子仲由，恶言恶语的话再也听不到了。”这时，子贡正为鲁国出使到了齐国。
宰予，字子我。他口齿伶俐，擅长辞辩。拜在孔子门下以后，问道：“一个人的父母死了，守孝三年，时间不是太长了吗？君子三年不习礼，礼义必定会毁坏；三年不演奏音乐，音乐一定会败环。一年间，陈旧的谷子吃完了，新的谷子又成熟了，钻木取火的木材换遍了，守丧一年也就可以了。”孔子说：“只守丧一年，你内心安不安呢？”宰我回答说：“心安。”孔子说：“你既然感到心安理得，你就这样做吧。君子守孝期间，即使吃美味的食品，也感觉不到甜美，听到动听的音乐也感觉不到高兴，所以君子才不这样做呀。”宰我退了出去，孔子说：“宰予不是个仁人君子啊！孩子生下来三年，才能脱离母亲的怀抱。为父母守孝三年，是天下共同遵行的礼仪啊。”
宰予白天睡大觉。孔子说：“腐朽了的木头是不能雕刻器物的，腐秽的墙壁是不能够粉刷的。”
宰我询问五帝的德行，孔子回答说：“你不是问这种问题的人。”
宰我做齐国临菑的大夫，和田常一起同谋作乱，因此被灭族，孔子为他感到羞耻。
端木赐，是卫国人，字子贡。比孔子小三十一岁。
子贡口齿伶俐，巧于辞令，孔子常常驳斥他的言辞。孔子问子贡说：“你和颜回比，谁更加出色？”子贡回答说：“我怎么敢指望跟颜回相比呢？颜回听知一个道理，能够推知十个道理，我听说一个道理，也不过推导出两个道理。”
子贡拜在孔子门下求学以后，问道：“我是什么样的人？”孔子说：“你象个有用器物。”子贡说：“什么样的器物呀？”孔子说：“宗庙里的瑚琏呀。”
卫公孙朝问子贡说：“仲尼在哪里得来这么广博的学问啊？”子贡说：“文王、武王的治国思想并没有完全丢掉，还在人间流传，贤能人记住它重要的部分，不贤的人只记住了它细枝末节，无处不有文王、武王的思想存在着。先生在哪里不能学习，又何必要有固定的老师！”陈子禽又问道：“孔子每到一个国家，一定了解到这个国家的政事。这是请求人家告诉他的呢，还是人家主动告诉他的呢？”子贡说：“先生凭借着温和、善良、恭谨、俭朴、谦让的美德得来的。先生这种求得的方式，或许与别人求得的方式不同吧。”
子贡问孔子说：“富有而不骄纵，贫穷而不谄媚，这样的人怎么样？”孔子说：“可以了；不过，不如即使贫穷乐于恪守圣贤之道，虽然富有却能处事谦恭守礼。”
田常想要在齐国叛乱，却害怕高昭子，国惠子，鲍牧，晏圉的势力，所以想转移他们的军队去攻打鲁国。孔子听说这件事，对门下弟子们说：“鲁国，是祖宗坟墓所在的地方，是我们出生的国家，我们的祖国危险到这种地步，诸位为什么不挺身而出呢？”子路请求前去，孔子制止了他。子张、子石请求前去救鲁，孔子也不答应。子贡请求前去救鲁，孔子答应他。
子贡就出发了，来到齐国，游说田常说：“您攻打鲁国是错误的。鲁国，是难攻打的国家，它的城墙单薄而矮小，它的护城河狭窄而水浅，它的国君愚昧而不仁慈，大臣们虚伪而中用，它的士兵百姓又厌恶打仗的事，这样的国家不可以和它交战。您不如去攻打吴国。吴国，它的城墙高大而厚实，护城河宽阔而水深，铠甲坚固而崭新，士卒经过挑选而精神饱满，可贵的人才、精锐的部队都在那里，又派英明的大臣守卫着它，这样的国家是容易攻打的。”田常顿时忿怒了，脸色一变说：“你认为难，人家认为容易；你认为容易的，人家认为是难的。用这些话来指教我，是什么用心？”子贡说：“我听说，忧患在国内的，要去攻打强大的国家；忧患在国外的，要去攻打弱小的国家。如今，您的忧患在国内。我听说您多次被授予封号而多次未能封成，是因为朝中大臣的有反对你的呀。现在，你要攻占鲁国来扩充齐国的疆域，若是打胜了，你的国君就更骄纵，占领了鲁国土地，你国的大臣就会更尊贵，而您的攻劳都不在其中，这样，您和国君的关系会一天天地疏远。这是您对上使国君产生骄纵的心理，对下使大臣们放纵无羁，想要因此成就大业，太困难啦。国君骄纵就要无所顾忌，大臣骄纵就要争权夺利，这样，对上您与国君感情上产生裂痕，对下您和大臣们相互争夺。象这样，那您在齐国的处境就危险了。所以说不如攻打吴国。假如攻打吴国不能取得胜利，百姓死在国外，大臣率兵作战朝廷势力空虚，这样，在上没有强臣对抗，在下没有百姓的非难，孤立国君专制齐国的只有您了。”田常说：“好。虽然如此，可是我的军队已经开赴鲁国了，现在从鲁国撤军转而进兵吴国。大臣们怀疑我，怎么办？”子贡说：“您按兵不动，不要进攻，请让我为您出使去见吴王，让他出兵援助鲁国而攻打齐国，您就趁机出兵迎击它。”田常采纳了子贡的意见，就派他南下去见吴王。
子贡游说吴王说：“我听说，施行王道的不能让诸侯属国灭绝，施行霸道的不能让另外的强敌出现，在千钧重的物体上，再加上一铢一两的分量也可能产生移位。如今，拥有万辆战车的齐国再独自占有千辆战车的鲁国，和吴国来争高低，我私下替大王感到危险。况且去援救鲁国，是显扬名声的事情；攻打齐国，是能获大利的事情。安抚泗水以北的各国诸侯，讨伐强暴的齐国，用来镇服强大的晋国，没有比这样做获利更大的了。名上保存危亡的鲁国，实际上阻阨了强齐的扩张，这道理，聪明人是不会疑的。”吴王说：“好。虽然如此，可是我曾经和越国作战，越王退守在会稽山上栖身，越王自我刻苦，优待士兵，有报复我的决心。您等我攻打越国后再按您的话做罢。”子贡说：“越国的力量超不过鲁国，吴国的强大超不过齐国，大王把齐国搁置在一边，去攻打越国，那么，齐国早已平定鲁国了，况且大王正借着”使灭亡之国复存，使断绝之嗣得续“的名义，却攻打弱小的越国而害怕强大的齐国，这不是勇敢的表现。勇敢的人不回避艰难，仁慈的人不让别人陷入困境。聪明的人失掉时机，施行王道的人不会让一个国家灭绝，凭借这些来树立你们的道义。现在，保存越国向各国诸侯显示您的仁德，援助鲁国攻打齐国，施加晋国以威力，各国诸侯一定会竞相来吴国朝见，称霸天下的大业就成功了。大王果真畏忌越国，我请求东去会见越王，让他派出军队追随您，这实际上使越国空虚，名义上追随诸侯讨伐齐国。”吴王特别高兴，于是派子贡到越国去。
越王清扫道路，到郊外迎接子贡，亲自驾驭着车子到子贡下榻的馆舍致问说：“这是个偏远落后的国家，大夫怎么屈辱自己庄重的身份光临到这里来了！”子贡回答说：“现在我已劝说吴王援救鲁国攻打齐国，他心里想要这么做却害怕越国，说：‘等我攻下越国才可以’。像这样，攻破越国是必然的了。况且要没有报复人的心志而使人怀疑他，太拙劣了；要有报复人的心志又让人知道他，就不安全了；事情还没有发动先叫人知道，就太危险了。这三种情况是办事的最大祸患。”勾践听罢叩头到地再拜说：“我曾不自量力，才和吴国交战，被围困在会稽，恨入骨髓，日夜唇焦舌燥，只打算和吴王一块儿拼死，这就是我的愿望。”于是问子贡怎么办。子贡说：“吴王为人凶猛残暴，大臣们难以忍受；国家多次打仗，弄得疲惫衰败，士兵不能忍耐；百姓怨恨国君，大臣内部发生变乱；伍子胥因谏诤被杀死，太宰嚭执政当权，顺应着国君的过失，用来保全自己的私利：这是残害国家的政治表现啊。现在大王果真能出兵辅佐吴王，以投合他的心志，用重金宝物来获取他的欢心，用谦卑的言辞尊他，以表示对他的礼敬，他一定会攻打齐国。如果那场战争不能取胜，就是大王您的福气了。如果打胜了，他一定会带兵逼近晋国，请让我北上会见晋国国君，让他共同攻打它，一定会削弱吴国的势力。等他们的精锐部队全部消耗在齐国，重兵又被晋国牵制住，而大王趁它疲惫不堪的时候攻打它，这样一定能灭掉吴国。”越王非常高兴，答应照计行动。送给子贡黄金百镒，宝剑一把，良矛二支。子贡没有接受，就走了。
子贡回报吴王说：“我郑重地把大王的话告诉了越王，越王非常惶恐，说：‘我很不走运，从小就失去了父亲，又不自量力，触犯吴国而获罪，军队被打败，自身受屈辱，栖居在会稽山上，国家成了荒凉的废墟，仰赖大王的恩赐，使我能够捧着祭品而祭祀祖宗，我至死也不敢忘怀，怎么另有其他的打算！’”过了五天，越国派大夫文种以头叩地对吴王说：“东海役使之臣勾践谨派使者文种，来修好您的属下近臣，托他们向大王问候。如今我私下听说大王将要发动正义之师，讨伐强暴，扶持弱小，困厄残暴的齐国而安抚周朝王室，请求出动越国境内全部军队三千人，勾践请求亲自披挂铠甲、拿着锐利的武器，甘愿在前面去冒箭石的危险。因此派越国卑贱的臣子文种进献祖先珍藏的宝器，铠甲十二件，斧头、屈卢矛、步光剑、用来作贵军吏的贺礼。”吴王听了非常高兴，把文种的话告诉子贡说：“越王想亲自跟随我攻打齐国，可以吗？”子贡回答说：“不可以。使人家国内空虚，调动人家所有的人马，还要人家的国君跟着出征，这是不道义的。你可接受他的礼物，允许他派出军队，辞却他的国君随行。”吴王同意了，就辞谢越王。于是吴王就是调动了九个郡的兵力去攻打齐国。
子贡因而离开吴国前往晋国，对晋国国君说：“我听说，不事先谋划好计策，就不能应付突然来的变化，不事先治理好军队，就不能战胜敌人。现在齐国和吴国即将开战，如果那场战争吴国不能取得胜利，越国必定会趁机扰乱它；和齐国一战取得了胜利，吴王一定会带他的军队逼近晋国。”晋非常恐慌，说：“那该怎么办呢？”子贡说：“整治好武器，休养士卒，等着吴军的到来。”晋君依照他的话做了。
子贡离开晋国前往鲁国。吴王果然和齐国人在艾陵打了一仗，把齐军打得大败，俘虏了七个将军的士兵而不肯班师回国，果然带兵逼近晋国，和晋国人在黄池相遇。吴晋两国争雄，晋国人攻击吴国，大败吴军。越王听到吴军惨败的消息，就渡过江去袭击吴国，直打到离吴国都城七里的路程才安营扎寨。吴王听到这个消息，离开晋国返回吴国，和越国军队在五湖一带作战。多次战斗都失败了，连城门都守不住了，于是越军包围了王宫，杀死了吴王夫差和他的国相。灭掉吴国三年后，越国称霸东。
所以，子贡这一出行，保全了鲁国，扰乱了齐国，灭掉了吴国，使晋国强大而使越国称霸。子贡一次出使，使各国形势发生了相应变化，十年当中，齐、鲁、吴、晋、越五国的形势各自有了变化。
子贡擅长囤积居奇，贱买贵卖，随着供需情况转手谋取利润。他喜欢宣扬别人的长处，也不隐瞒别人的过失。曾出任过鲁国和卫国的国相，家产积累千金，最终死在齐国。
言偃，是吴国人，字子游。比孔子小四十五岁。
子游受业以后，出任武城的长官。孔子路过武城，听到弹琴唱歌的声音。孔子微微地笑了，说：“杀鸡何必用宰牛刀呢？”子游说：“从前我听先生说过：‘有才德的人学了礼乐，就会涵养仁心，爱护人民；普通人学了礼乐，就会谨守法规，容易使唤。’”孔子对随行的学生们说：“诸位，言偃的话是对的。我刚才说的那句话不过是开玩笑罢了。”孔子认为子游熟习文章博学。
卜商，字子夏。比孔子小四十四岁。
子夏问道：“‘姣美的笑容妩媚动人啊，明沏的眼珠流动生辉啊，仿佛洁白的生绡染上了绚烂的文彩’，这三句诗是什么意思？”孔子回答说：“绘画要先有洁白的底子，然后再彩饰图画。”子夏说：“是不是礼乐的产生在仁义之后呢？”孔子说：“卜商啊，现在可以和你讨论《诗经》了。”
子贡问道：“颛孙师和卜商那一位更有才能些？”孔子说：“师么，有些过分，商么，有些赶不上。”子贡说：“那么颛孙师好一些吗？”孔子说：“过分和赶不上同样是不完美的。”
孔子对子夏说：“你要立志作个有才德的读书人，不要作浅薄不正派的读书人。
孔子逝世后，子夏定居河西教授学生，成了魏文侯的教师。子夏的儿子死了，把眼睛都哭瞎了。
颛孙师，是陈国人，字子张。比孔子小四十八岁。
子张向孔子学习求取官职俸禄的方法。孔子说：“多听人家说，对疑难未解的，不要妄加评论，其余有把屋的要谨慎地说出，能少犯错误；多看人家行事，对疑难未解的，不要妄加行动，其余有把握的要谨慎地行动，能减少懊悔。说话的错误少、行动的懊悔少，你要求取的官职俸禄就在里面了。”
有一天子张跟随孔子在陈国和蔡国之间的被围困，子张问怎样才能处处行得通。孔子说：“说话要忠诚信实，行为要真诚恭敬，即使在南蛮北狄也行得通；说话不忠诚信实，行为不真诚恭敬，即使是在本乡本土，能行得通吗？站着的时候，就象‘忠信笃敬’几个字呈现在眼前；坐在车上，就象‘忠信笃敬’几个字挂在车前的横木上，做到这种地步之后，就到处行得通了。”子张就把这些话写在束腰的大带子上。
子张问：“读书人怎样做才可以叫通达了呢？”孔子说：“你所说的通达，是指的什么呢？”子张回答说：“在诸侯的邦国中一定要有声望，在卿大夫家里也一定要有声誉。”孔子说：“这是声望，不是通达。所谓通达，应当是立身正直而好义，审度别人的言论，观察别人的表情，时常想着谦恭退让，这样，在诸侯的邦国和卿大夫的封地一定能够通达。所说的声望，外表上好像追求仁德的样子，而实际行动上却违背仁德，自己要安然处之，毫不怀疑，这样的人在诸侯的邦国和卿大夫的封地一定能取得名望。”
曾参，是南武城人，字了舆，比孔子小四十六岁。
孔子认为他能通达孝道，所以传授他学业。他撰写了一部《孝经》。他死在鲁国。
澹台灭明，是武城人，字子羽。比孔子小三十九岁。
他的体态相貌很丑陋。想要事奉孔子，孔子认为他资质低下。从师学习以后，回去就致力于修身实践，处事光明正大，不走邪路，不是为了公事，从来不去会见公卿大夫。
他往南游历到长江，追随他的学生有三百人，他获取、给予离弃、趋就都完美无缺，他的声誉传遍了四方诸侯。孔子听到这些事，说：“我只凭言辞判断人，对宰予的判断就错了；单从相貌上判断人，对子羽的判断就错了。”
宓不齐，字子贱。比孔子小三十岁。
孔子谈论宓子贱，说：“子贱真是个君子啊！假如鲁国没有君子，这个人又从哪儿学到这种好品德呢？”
子贱出任单父地方长官，回来向孔子报告，说：“这个地方有五个人比我贤能，他们教给我施政治民的方法。”孔子说：“可惜呀！不齐治理的地方太小了，要是治理的地方大就差不多了。”
原宪，字子思。
子思问什么是耻辱。孔子说：“国家政治清明，可以做官领取俸禄，却不能有所见树。国家政治黑暗，做官领取俸禄，却不能独善其身，就是耻辱。
子思说：“好胜、自我夸耀、怨恨、贪欲都没有显现出来，可以算是做到了仁了吗？”孔子说：“可以说是难能可贵了，是否算是做到仁，那我就不知道了。”
孔子逝世以后，原宪就跑到低洼积水、野草丛生的地方隐居起来。子贡做了卫国的国相，出门车马接连不断，排开丛生的野草，来到偏远简陋破败的小屋，前去看望原宪。原宪整理好破旧的衣帽，会见子贡。子贡见状替他感到羞耻，说：“难道你很困窘吗？”原宪回答说：“我听说，没有财产的叫做贫穷，学习了道理而不能施行的叫做困窘。像我，贫穷，不是困窘啊。”子贡感到很惭愧，不高兴地离去了，一辈子都为这次说错了话感到羞耻。
公冶长，是齐国人，字子长。
孔子说：“公冶长，可以把女儿嫁给他，即使他在囚禁之中，并不是他的罪过。”就把自己的女儿嫁给了他。
南宫括，字子容。
南宫括问孔子说：“羿擅长射箭，奡擅长荡舟，他们都不能够善终；禹、稷亲自耕种而为什么能得到天下呢？”孔子不回答。南子容退出后，孔子说：“这个人真是个君子啊！这个人崇尚道德啊！”孔子评论他说：“国家政治清明，他会被任用；国家政治黑暗，他也不会遭受刑罚”。他把“白珪之玷”的几句诗再三吟诵，孔子就把自己的侄女嫁给了他。
公皙哀，字季次。
孔子说：“天下没有德行的读书人，大多数作了卿大夫们的家臣，在都邑作官，只有季次不曾出来作官。”
曾蒧，字皙。
他陪着孔子，孔子说：“谈谈你的志趣。”曾蒧说：“穿着刚做好的春装，和五六个成年人，六七个小孩子，在沂水里洗个澡，在祈雨台上吹吹风，唱着歌回来。”孔子听了，长长地叹息说：“我赞成曾蒧的志趣啊！”
颜无繇，字路。颜路，是颜回的父亲，父子俩曾先后在孔子门下求学。
颜回死了，颜路贫穷，请求孔子把车子卖掉安葬颜回。孔子说：“他们（孔鲤和颜回）不论是有才华或没有才华，但对我们来说都是自己的儿子。孔鲤死了，只有内棺，没有外椁，我不能卖掉车子徒步走路给他买椁，因为自从我位居大夫行列，就不可以徒步行走。”
商瞿，是鲁国人。字子木，比孔子小二十九。
孔子把《易经》传授给商瞿，商瞿传给楚国人臂子弘，子弘传给江东人矫子庸疵，庸疵传给燕国人周子家竖，周竖传给淳于人光子乘羽，光羽传给齐国人田子庄何，田何传给东武人王子中同，中同传给菑川人杨何。杨何在汉武元朔年间，因为研究《易经》出任子当朝的中大夫。
高柴，字子羔。比孔子小三十岁。
子羔的身长不足五尺，在孔子门下学习，孔子认为他很愚笨。
子路派子羔担任费邑的长官。孔子说：“这是残害人家的子弟！”子路说：“那里有人民百姓。有祭祀土神和谷神的庙宇，为什么一定要读书才叫做学问呢？”孔子说：“所以我厌恶用花言巧语谄媚的人”。
漆雕开，字子开。
孔子叫子开去做官，子开回答说：“我对作官还没有信心。”孔子听了很高兴。
公伯缭，字子周。
子周在季孙面前说子路的坏话，子服景伯把这件事告诉了孔子并且说：“季孙本来就有了疑心，可是我还有力量杀死公伯缭，把他的尸体陈放在街头示众。”孔子说：“正道能够行得通，那是天意，正道废弃不能施得，也是天意，公伯缭对天意又能怎么样呢？”
司马耕，字子牛。
子牛话多而性情急躁。他向孔子问仁德，孔子说：“有仁德的人，说话很谨慎。”子牛又问：“说话很谨慎，这就可以算是仁德吗？”孔子说：“做起来很困难，说起来能不谨慎吗！”
子牛问怎样才算是君子，孔子说：“一个君子既不忧愁，也不畏惧。”他接着问：“不忧愁，不畏惧，这就可以算是君子吗？”孔子说：“自我反省，内心无愧，有什么忧愁，有什么畏惧的呢！”
樊须，字子迟。比孔子小三十六岁。
樊须向孔子请求学种庄稼，孔子说：“我不如老农民。”又请求学种蔬菜，孔子说：“我不如老菜农。”樊迟退出后，孔子说：“樊须，是个志向浅薄的小人啊！统治者提倡礼义，百姓就没有人敢不敬；统治者诚恳信实，百姓就没有人敢不说真情实话。如果能这样，那么四方的百姓就会背负着包裹着的孩子前来投奔，哪里用得着自己种庄稼。
樊迟问什么是仁德，孔子说：“爱所有的人！”又问什么智慧，孔子说：“了解人。”
有若，比孔子小四十三岁。有若说：“礼的应用，以恰到好处为可贵。过去圣明的君王治理国家的办法，最高明的地方就在这里；小事大事都按照这一条原则去理，有时就行不通；但是只知道和的重要而一味地追求和，而不用礼去节制它，也是不可行的。”有若又说：“所守的信约要符合于义，这约言就能经得起实践的检验。恭敬要符合礼，就能避免耻辱；依傍那些不失为亲近的人，也就可靠了。”
孔子逝世以后，学生们都很怀念他。有若长得很象孔子，学生们共同拥戴他当教师，就象当年侍奉孔子一样对待他。有一天，学生进来问他说：“从前先生正要出行，就叫同学们带好雨具，不久果真下起雨来。同学们请教说：‘先生怎么知道要下雨呢？’先生回答说：‘《诗经》里不是说了吗：月亮依附于毕星的位子上，接着就会下大雨。昨天夜里月亮不是宿在毕星的位子上吗？’有一天，月亮又宿在毕星的位了上，却没有下雨。商瞿年纪大了还没有儿子，他的母亲要替他另外娶妻。孔子派他到齐国去，商瞿的母亲请求不要派他。孔子说：‘不要担忧，商瞿四十岁以后会有五个男孩子。’过后，果真是这样的。请问先生当年怎么能够预先知道是这样的呢？”有若沉默无以回答。学生们站起来说：“有先生，你躲开这儿吧，这个位子不是您能坐的啊！”
公西赤，字子华。比孔子小四十二岁。
子华出使去齐国，冉有为他的母亲向孔子请求粮食。孔子说：“给他一釜。”冉有请求增加，孔子说：“那就给他一庾。”，冉有给了她五秉粮食。孔子说：“公西赤到齐国去，坐的是肥马拉的车子，穿的是又轻又暖的裘皮衣裳。我听说，君子救济紧急需要的穷人而不是为他增加财富。
巫马施，字子旗，比孔子小三十岁。
陈司败问孔子说：“鲁昭公懂礼吗？”孔子说：“懂礼。”孔子出去后，陈司败向巫马旗作了个揖说：“我听说君子是不偏私袒护的，莫非君子也会偏私袒护？鲁昭公娶来吴女作夫人，给她起名叫她孟子。孟子本姓姬，避忌称呼同姓，所以叫她吴孟子。鲁君要是懂得礼仪，那还有谁不懂得礼节呢？”巫马施把这些话转告给孔子，孔子说：“我真幸运，如果有了过失，人家一定会知道。作臣子的不能说国君的过错的，替他避忌的人，就是懂礼啊。”
梁鳣，字叔鱼，比孔子小二十九岁。
颜幸，字子柳，比孔子小四十六岁。
冉儒，字子鲁，比孔子小五十岁。
曹，字子循，比孔子小五十岁。
伯虔，字子析，比孔子小五十岁。
公孙龙，字子石，比孔子小五十三岁。
从子石以上三十五人，他们的年龄、姓名和受业经过、事迹都能明显地见么文字记载。其余的四十二人，没有年龄可考，也没有文字记载的记在下面：
冉季，字子产。
公祖句兹，字子之。
秦祖，字子南。
漆雕哆，字子敛。
颜高，这字骄。
漆雕徒父。
壤驷赤，字子徒。
商泽。
石作蜀，字子明。
任不齐，字选。
公良儒，字子正。
后处，字子里。
秦冉，字开。
公夏首，字乘。
奚容箴，字子皙。
公肩定，字子中。
颜祖，字襄。
鄡单，字子家。
句井疆。
罕父黑，字子索。
秦商，字子丕。
申党，字周。
颜之仆，字叔。
荣旗，字子祈。
县成，字子祺。
左人郢，字行。
燕伋，字思。
郑国，字子徒。
秦非，字子之。
施之常，字子恒。
颜哙，字子声。
步叔乘，字子车。
原亢，字籍。
乐欬，字子声。
廉絜，字庸。
叔仲会，字子期。
颜何，字冉。
狄黑，字皙。
邦巽，字子敛。
孔忠。
公西舆如，字子上。
公西葳，字子上。
太史公说：“后世学者们都称述孔子门下七十位门徒，赞誉他们的人，有的超过了他们的实际，诋毁他们的人，有的损害了他们的真实形象。”总之，谁都没有看到他们的真实相貌，而议论品评。孔门弟子的生平事迹还是孔氏古文接近真相，关于孔子门下弟子们的名字、姓氏、言行等情况，我全部取自《论语》的弟子问答，编次成篇，有疑问的地方就空缺着。', '[{"bookId": "62de4d1258b41e18820703e1", "bookTitle": "二十四史鉴赏辞典", "articleId": "6305a3d730a1d3054c7563fb", "shortContent": "《仲尼弟子列传》是《史记》中记述孔子诸多弟子言行事迹的一篇合传，其中对于各弟子的记述详略不等，有时通过若干小故事，有时以孔子与门生们的对话记录，勾勒司马迁出一个个孔门弟子鲜活的形象，比如贤良好学的颜回、勇敢直率的子路、能言善辩的子贡、文采斐然的子游、子夏……其中所用篇幅最多也最有意思的一则故事，是关于子贡如何游说诸侯以解救鲁国的一次危机。\n春秋末期，天下诸侯早就不把当初周朝开国时周武王的分封属地看...", "authors": ["李欢"], "pressName": "上海辞书出版社"}]', '', 'indent', 1554114953, '5ca178fdc05a80007464ca02', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641624, '沁园春 · 羊角飘尘', NULL, 6, 158, 0, 1, '赵师侠', NULL, 32903, '5858fa1d61ff4b0063d79be1', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E6%B2%81%E5%9B%AD%E6%98%A5%C2%B7%E7%BE%8A%E8%A7%92%E9%A3%98%E5%B0%98/18855229?fr=aladdin', '', '羊角飘尘，金乌烁石，雨凉念秋。有虚堂临水，披襟散发，纱帱雾卷，湘簟波浮。远列云峰，近参荷气，卧看文书琴枕头。蝉声寂，向庄周梦里，栩栩无谋。
茶瓯。醒困堪求。粗饱饭安居可以休。算悠闲静胜，吾能自乐，荣华纷扰，人谩多愁。习懒非痴，觉迷是病，一力那能胜九牛。俱休问，且追寻觞咏，知友从游。', '', '', '', NULL, '', 'indent', 1554118303, '5ca1861ba91c93007302c7b5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641625, '元旦口占用柳亚子怀人韵', NULL, 5, 2, 0, 1, '董必武', NULL, 36578, '5858fd5fac502e00670901a2', '当代', 'shi', '诗', 'https://baike.baidu.com/item/%E5%85%83%E6%97%A6%E5%8F%A3%E5%8D%A0%E7%94%A8%E6%9F%B3%E4%BA%9A%E5%AD%90%E6%80%80%E4%BA%BA%E9%9F%B5/1191140?fr=aladdin', '', '共庆新年笑语哗，红岩士女赠梅花。
举杯互敬屠苏酒，散席分尝胜利茶。
只有精忠能报国，更无乐土可为家。
陪都歌舞迎佳节，遥祝延安景物华。', '《元旦口占用柳亚子怀人韵》是近代诗人董必武在重庆八路军办事处庆祝1942年元旦时，用柳亚子怀人诗的原韵，即兴口占的一首七律。该诗体现了诗人伟大的革命豪情和抗战必胜的坚定信念，表达了诗人精忠报国的爱国情怀以及怀念革命圣地延安的深厚感情。', '口占：随口吟出，不打草稿。
红岩：指八路军驻重庆办事处红岩村。士女：青年男女。
屠苏酒：酒名。此指宴会上所饮之酒。
胜利茶：当时重庆市商店出售纸包茶，名“胜利茶”，表示预祝抗日战争胜利的意思。
陪都：指重庆。国民党政府的首都本来在南京，因陷落，临时迁至重庆，故称陪都。
景物华：景物有光彩。此为祝颂延安繁荣。', '大家聚集在一起共同庆祝新年的到来，笑语喧哗，十分热闹，红岩村的年青同志送来梅花，更增添了节日气氛。
大家在一起举杯互相敬酒，表达着新年的祝愿，散席后众人意犹未尽，又一起品尝这胜利茶，谈论当今时事。
只有精忠才能报答祖国，如今祖国正遭外侮，烽烟遍地，没有地方去寻求一家安乐。
我们在陪都重庆载歌载舞地欢庆新年，但不要忘了延安，让我们遥祝延安解放区繁荣昌盛。', NULL, '现代欧阳少鸣：“这首诗歌以朴质无华的语句，表达了深挚的革命情感，同时也带上了浓厚的时代色彩。而情感的热情洋溢，与深沉感慨的融合，也是该诗的一大特色。”', 'center', 1554118417, '5ca1868e42cda61644ad63f3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641626, '夏昼偶作', NULL, 20, 243, 0, 1, '柳宗元', NULL, 10055, '57b9042f7db2a2005426b940', '唐', 'shi', '诗', '', '', '南州溽暑醉如酒，隐几熟眠开北牖。
日午独觉无馀声，山童隔竹敲茶臼。', '', '南州：指永州。溽（rù入）暑：又湿又热，指盛夏的气候。《礼记·月令》：“土润溽暑，大雨时行。”醉如酒：像喝醉了酒那样要打盹。
隐几：凭倚着几案。《庄子·徐无鬼》：“南伯子綦隐几而坐。”隐几，亦作“隐机”。《秋水》：“公子牟隐机太息。”
北牖：北窗。
日午：中午。
敲茶臼（jiù）：制作新茶。茶臼，指捣茶用的石臼。', '永州的夏天又湿又热，困得使人像醉汉打盹，推开北窗，凭案酣睡长精神。
中午醒来，只觉得大地死一般的寂静，隔着竹林，惟有山童捣制新茶时敲击茶臼的声音。', NULL, '', 'center', 1554118563, '5ca1871da3180b0068e5a666', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641627, '春昼回文', NULL, 7, 3, 0, 1, '李涛', NULL, 12367, '5858e759128fe1006dcc29e2', '唐', 'shi', '诗', '', '', '茶饼嚼时香透齿，水沉烧处碧凝烟。
纱窗避著犹慵起，极困新晴乍雨天。 ', '', '回文：把相同的词汇或句子，在下文中调换位置或颠倒过来，产生首尾回环的情趣，叫做回文，也叫回环。
纱窗：蒙纱的窗户。 ', '', NULL, '', 'center', 1554118701, '5ca187a9c05a80007465d37f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641688, '寒食还陆浑别业', NULL, 56, 209, 0, 2, '宋之问', NULL, 10130, '57b9a06a2e958a00693191e7', '唐', 'shi', '诗', 'https://baike.baidu.com/item/%E5%AF%92%E9%A3%9F%E8%BF%98%E9%99%86%E6%B5%91%E5%88%AB%E4%B8%9A/9964098?fr=aladdin', '', '洛阳城里花如雪，陆浑山中今始发。
旦别河桥杨柳风，夕卧伊川桃李月。
伊川桃李正芳新，寒食山中酒复春。
野老不知尧舜力，酣歌一曲太平人。', '《寒食还陆浑别业》是唐朝诗人宋之问创作的一首七言古诗。此诗首先描写了寒食节里洛阳城和陆浑别业两地的花儿盛开的情况，接下来描写了诗人对洛阳春光的留恋，并且透出了卧赏山庄春夜美景的惬意，然后对比伊川的春意美景和此时陆浑别业的酒水，写出了自己愿作一名老人歌颂这太平盛世的心愿，最后表达了诗人对春天的喜悦之情及对官场留恋。全诗语言清新，格调优美。', '陆浑：地名，在今河南嵩县。别业：即别墅。
杨柳：柳与留谐音，古人有折柳送别之俗。清明亦有插柳、戴柳之俗。
伊川：水名。即“伊河”。洛河支流，在河南西部。
酒复春：唐人名酒多用春字，如竹叶春、松醪春、烧春等。
野老句：据《艺文类聚》所引皇甫谧《帝王世纪》，在帝尧的时候，天下太平，百姓无事。有一位老人年八十余，击壤于道中。看见他的人感叹帝尧之德，听见了反驳道，我日出而作，日入而息，辛苦劳作而衣食无虞，这跟尧有什么关系，他对我有什么恩德呢？', '洛阳城里，花儿已经开得如雪一般铺天盖地，而陆浑山中的花儿，如今才开始发芽。
早上刚刚辞别了河桥那掠过杨柳吹来的风儿，晚上又卧在这伊川桃李间的月色中。
伊川的桃李正是芬芳面新鲜的时候。在寒食节里，山中的酒也是醉香宜人的。
山野间的老人安居乐业，快活地唱上一曲，唱一唱这身在太平盛世中的人。', NULL, '明末清初学者唐汝询《唐诗解》卷十一：“此山居燕饮之诗，言城中花落如雪，而此地始开者，山深故耳。于是别河桥而归卧伊川，则桃李含英，春酒方熟。熙游圣化之中，酣饮而歌《击壤》之曲，非太平何以能此！其开元致治之时乎？”
清代书法家周珽《删补唐诗选脉笺释会通评林·初七古》：“此篇语意转折，亦初唐七古佳调。”', 'center', 1554215397, '5ca3015fc05a80007367b6a6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641786, '兰花', NULL, 6, 1624, 0, 1, '刘基', NULL, 10076, '57ba8247c4c97100614d49ee', '明', 'shi', '诗', '', '', '幽兰花，在空山，美人爱之不可见，裂素写之明窗间。
幽兰花，何菲菲，世方被佩资簏施，我欲纫之充佩韦，袅袅独立众所非。
幽兰花，为谁好，露冷风清香自老。', '', '', '', NULL, '', 'indent', 1554384896, '5ca59765c05a8000738c74d5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641787, '《复堂词录》序', NULL, 3, 138, 1, 0, '谭献', NULL, 26443, '5858f42d61ff4b00687635ae', '清', 'wen', '文', '', '', '右录三百四十余人，词一千四十七首。叙曰：“词为诗余，非徒诗之余，而乐府之余也。律吕废坠，则声音衰息。声音衰息，则风俗迁改。乐经亡而六艺不完，乐府之官废，而四始六义之遗，荡焉泯焉。夫音有抗队，故句有长短。声有抑扬，故韵有缓促。生今日而求乐之似，不得不有取于词矣。唐人乐府，多采五七言绝句。自李太白创词调，比至宋初，慢词尚少。至大晟之署，应天长、瑞鹤仙之属，上荐郊廊，拓大厥宇，正变日备。愚谓词不必无颂，而大旨近雅。于雅不能大，然亦非小，殆雅之变者欤。其感人也尤捷，无有远近幽深，风之使来。是故比兴之义，升降之故，视诗较著，夫亦在于为之者矣。上之言志，永言次之。志絜行芳，而后洋洋乎会于风雅。琱琢曼辞，荡而不反，文焉而不物者，过矣靡矣，又岂词之本然也哉。献十有五而学诗，二十二旅病会稽，乃始为词，未尝深观之也。然喜寻其恉于人事，论作者之世，思作者之人。三十而后，审其流别，乃复得先正绪言以相启发。年逾四十，益明于古乐之似在乐府，乐府之余在词。昔云：“礼失而求之野。”其诸乐失，而求之词乎。然而靡曼荧眩，变本加厉，日出而不穷，因是以鄙夷焉，挥斥焉。又其为体，固不必与庄语也，而后侧出其言，旁通其情，触类以感，充类以尽。甚且作者之用心未必然，而读者之用心何必不然。言思拟议之穷，而喜怒哀乐之相发，响之未有得于诗者，今遂有得于词。如是者年至五十，其见始定。先是写本朝人词五卷，以相证明。复就二十二岁以来，审定由唐至明之词，始多所弃，中多所取，终则旋取旋弃，旋弃旋取，乃写定此千篇，为复堂词录。前集一卷，正集七卷，后集二卷。其间字句不同，名氏互异，皆有据依，殊于流俗。其大意则折衷古今名人之论，而非敢逞一人之私言，故以论词一卷附焉。大雅之才三十六，小雅之才七十二，世有其人，则终以词为小道也，亦奚不可之有。', '', '前集一卷，正集七卷，后集二卷：珂谨按：书成于光绪八年九月，未刊行，师归道山矣。
甚且作者之用心未必然，而读者之用心何必不然：作者的用意不一定在此，可是读者也许能解出此意。与西方罗兰·巴特的提出的“作者死了”的观点不谋而合。', '', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf64d635634aee3ea89a", "shortContent": "白居易作为唐代重要的文学批评家，所作《赋赋》因其以赋论赋的独特形式，在中国古代赋论发展史上具有了一席之地。《赋赋》的创作，实与东晋陆机著名的文学创作专论《文赋》有莫大关系。从形式上看，《文赋》首开以赋论文的先河，而《赋赋》借鉴了这种文论特点，并在赋论史上第一次运用以赋论赋的形式批评赋作。从内容上看，《文赋》字数近两千言，关于赋作仅提及“赋体物而浏亮”一句，至《赋赋》全篇已扩充至三百余字的论赋专文。...", "authors": ["牛思仁", "王勋成"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1ebc6e67846a921a11f", "shortContent": "在唐人选唐诗中，殷璠的《河岳英灵集》专选盛唐诗歌，有着严格的选录标准，并结合对入选诗人、诗作的品评，表达自己对诗歌的见解，是一部重要唐诗选本，历来受到文学史家、文学批评史家和选家的重视。这部选集的序，集中表述了编选者选录当代诗歌的审美标准和严肃态度，是诗歌理论批评史上一篇重要的文献，也是一篇颇见作者个性的文章。\n序文开头一段，通过批评萧统《文选》以来许多文学选本“诠简不精”的弊病，强调选家的选录标...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}, {"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed2102e6a6b501f9685f0", "shortContent": "清嘉庆二年（1797），武进（今江苏常州）张惠言、张琦兄弟编辑了《词选》，搜集唐、五代、两宋词人四十四家，词一百十六首，共二卷。当时他们方馆于安徽歙县经学大师金榜的家中，教授金氏的子弟，同时也向金榜求教。清初以来，朱彝尊提倡姜夔、张炎词，形成所谓“浙派”，但其末流，词的内容渐趋空虚、浮薄。而“阳羡”一派，以陈维崧（迦陵）为首，标举苏轼、辛弃疾；由于缺乏现实生活的坚实基础，只是一味追求激昂豪放，末流...", "authors": ["宋", "廓"], "pressName": "上海辞书出版社"}]', '', 'indent', 1554489675, '5ca73081a3180b0068da2f39', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641791, '访杨云卿淮上别墅', NULL, 1, 117, 1, 1, '释惠崇', NULL, 35169, '5858fc46128fe1006b887fb7', '宋', 'shi', '诗', '', '', '地近得频到，相携向野亭。
河分冈势断，春入烧痕青。
望久人收钓，吟余鹤振翎。
不愁归路晚，明月上前汀。', '', '', '', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea6f02cee9a0c24ed46f0", "shortContent": "杨云卿其人不详，他在淮水之上有一套别墅。僧惠崇乃淮南人，两人邻近，因此过从甚密。这首五律便是惠崇至淮上别墅访杨云卿时所作，写两人相携同游的情致。\n首联点题，写过访。因为两人居处邻近，所以惠崇得以屡到淮上别墅访杨云卿，一个春日的下午，他又去了。宾主二人便相携向郊野一个亭子走去，那里无遮无拦，正可饱览野外景色。\n颔联描写郊野景致。河，该就是指淮河了。烧痕，火烧草地所留之痕。二人站在野亭之中，纵目远望淮...", "authors": ["周慧珍"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "6464a1f845e4710056c422b6", "shortContent": "杨云卿其人不详，他在淮水之上有一套别墅。僧惠崇乃淮南人，两人邻近，因此过从甚密。这首五律便是惠崇至淮上别墅访杨云卿时所作，写两人相携同游的情致。\n\n首联点题，写过访。因为两人居处邻近，所以惠崇得以屡到淮上别墅访杨云卿，一个春日的下午，他又去了。宾主二人便相携向郊野一个亭子走去，那里无遮无拦，正可饱览野外景色。\n\n颔联描写郊野景致。河，该就是指淮河了。烧痕，火烧草地所留之痕。二人站在野亭之中，纵目远...", "authors": ["周慧珍"], "pressName": "上海辞书出版社"}]', '', 'center', 1554652108, '5ca789bac05a800073acc98c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641881, '薛宝钗 · 雪竹', NULL, 3, 1, 0, 1, '环山樵', NULL, 37035, '5caab8eaa3180b00680d893e', '清', 'shi', '诗', 'https://baike.baidu.com/item/%E8%96%9B%E5%AE%9D%E9%92%97%C2%B7%E9%9B%AA%E7%AB%B9/1299003', '', '大雪北风催，家家贫白屋。
玉树犹难伸，压倒千竿竹。
高节志凌云，不敢当滕六。
君子本虚心，甘自低头伏。
无复绿猗猗，何如在淇澳？
寒林尽白封，奚第琅玕独。
寒梅也不禁，何只君瑟缩？
读书小窗前，不见青矗矗。
搦管坐空斋，不听声谡谡。
缅怀文典可，佳画添几幅。
更思僵卧人，岂只食无肉。', '', '滕六：téngliù/lù，传说中雪神名，也叫“封六”，此用以指雪。
寒林：秋冬之林。
奚第：何只，哪里仅仅。
琅玕：翠竹的美称。
矗矗：chùchù，高峻貌。重叠貌。
搦管：nuòguǎn，指提笔作文。搦，持、拿；管，指毛笔。
斋：zhāi，屋舍，常指书房、学舍。
谡谡：sùsù，∶象声词，形容风声呼呼作响。
文典：wéndiǎn，文籍典册。', '', NULL, '', 'center', 1554721160, '5caab8fba91c932819acc4c7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641882, '咏檐前竹', NULL, 5, 376, 1, 2, '沈约', NULL, 35895, '5858fce161ff4b0068768127', '南北朝', 'shi', '诗', 'https://baike.baidu.com/item/%E5%92%8F%E6%AA%90%E5%89%8D%E7%AB%B9/184503?fr=aladdin', '', '萌开箨已垂，结叶始成枝。
繁荫上蓊茸，促节下离离。
风动露滴沥，月照影参差。
得生君户牖，不愿夹华池。', '《咏檐前竹》是南朝文学家沈约创作的一首咏物诗。这首诗就像作水墨画一样描绘了檐前竹子的风姿与神韵，赞美了檐竹的高节。', '箨：指笋壳。
蓊茸：表现檐竹枝叶披离之态。
户牖：门和窗。', '', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccc1d635634aee3ea5bd", "shortContent": "岁寒三友，竹居其中。人们之所以看重它，或者因为它“翠叶与飞雪争采，贞柯与曾冰竞鲜”的凌寒之质（齐·王俭《灵丘竹赋》）；或者因为它“未出土时便已有节，直到凌云高处依然虚心”的君子之风（近人管桦《竹颂》）。传说它的竹实只为凤凰所食；竹竿又能制成箫笛横吹。所以碰到豪爽之士，便以它的“所欣高蹈客，未待伶伦吹”慨然自诩（陈·贺循《赋得夹池修竹》）；遇上才高位卑者流，便又借它发出“谁能制长笛，当为吐龙吟”的孤...", "authors": ["潘啸龙"], "pressName": "上海辞书出版社"}]', '', 'center', 1554721231, '5caab94c0237d70068f4352e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641885, '送王侍御赴夏口座主幕', NULL, 0, 501, 0, 1, '杜牧', NULL, 10109, '57b9836cc4c971005593dfec', '唐', 'shi', '诗', 'https://baike.baidu.com/item/%E9%80%81%E7%8E%8B%E4%BE%8D%E5%BE%A1%E8%B5%B4%E5%A4%8F%E5%8F%A3%E5%BA%A7%E4%B8%BB%E5%B9%95/4597736?fr=aladdin', '', '君为珠履三千客，我是青衿七十徒。
礼数全优知隗始，讨论常见念回愚。
黄鹤楼前春水阔，一杯还忆故人无？', '', '', '', NULL, '', 'center', 1554808551, '5cac0e57a3180b0068215dc9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641908, '赠赵侍御', NULL, 0, 352, 0, 1, '张说', NULL, 13343, '5858e82c8e450a006cba4a71', '唐', 'shi', '诗', '', '', '禄放迹异端，偏荒事同蹇。苟忘风波累，俱会云壑践。
险式压西湖，侨庐对南岘。夜楼江月入，朝幌山云卷。
山势远涛连，江途斜汉转。坐啸予多暇，行吟子独善。
并辔躧郊郭，方舟玩游演。虚声万籁分，水色千里辨。
不知岸阴谢，再见春露泫。绿壤发欣颜，华年助虫篆。
上世时难接，古人情可选。泊渚烦为媒，多才怨成褊。
长沙鵩作赋，任道可知浅。请从三已心，荣辱两都遣。 ', '', '', '', NULL, '', 'center', 1554892989, '5cad583a0237d700681a4961', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641909, '题汉州西湖', NULL, 0, 321, 0, 1, '薛能', NULL, 14188, '5858e8f9ac502e006708562e', '唐', 'shi', '诗', '', '', '西湖天下名，可以濯吾缨。
况是携家赏，从妨半驿程。
尝茶春味渴，断酒晚怀清。
尽得幽人趣，犹嫌守吏迎。
重餐逢角暮，百事喜诗成。
坐阻湘江谪，谁为话政声。', '', '', '', NULL, '', 'center', 1554893111, '5cad58b6c05a800073ff4df2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641910, '蓦山溪 · 其九', NULL, 0, 149, 0, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '重黎默运，可意萦人处。清楚玉蕤仙，独幽栖、村溪月坞。冰腮露鬓，佳致在西湖，月出早，雪消迟，立马红墙序。寒梢微萼，点点蝇头许。欲露小檀心，似生怕、施朱红紫。返魂香细，堪吊独醒人，临泽国，袭清风，且咏离骚句。 ', '', '', '', NULL, '', 'indent', 1554893291, '5cad59690237d700681a5c88', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641911, '蓦山溪 · 其十一', NULL, 0, 149, 0, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '竹篱茆舍，底是藏春处。玉蓓锁檀心，带黄昏、轻烟细雨。神清骨莹，端似雪堂仙，临岁晚，傲寒威，寂寞江村住。琼林阆苑，有信终归去。冷暖笑凡情，辨南枝、北枝几许。灵芳绝艳，知肯为谁容，东阁里，西湖畔，总与花为主。', '', '', '', NULL, '', 'indent', 1554893332, '5cad5987a91c932819d2d636', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641912, '醉花阴 · 其一', NULL, 0, 149, 0, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '粉妆一捻和香聚。教露华休妒。今日在尊前，只为情多，脉脉都无语。西湖雪过留难住。指广寒归去。去后又明年，人在江南。梦到花开处。
', '', '', '', NULL, '', 'indent', 1554893998, '5cad59b7c05a800073ff5f54', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641913, '点绛唇 · 其八', NULL, 0, 149, 0, 1, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '赋雪归来，绿窗一夜霜风紧。也知春信。消息南枝近。
隐映斜阳，玉暖香成阵。西湖景。繁英有恨。只□□□□。', '', '', '', NULL, '', 'indent', 1554893410, '5cad59e0a3180b0068339f26', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641914, '题君山', NULL, 3, 342, 0, 1, '方干', NULL, 11976, '5858e6f8128fe10069b24543', '唐', 'shi', '诗', '', '', ' 曾于方外见麻姑，闻说君山自古无。
元是昆仑山顶石，海风吹落洞庭湖。
', '此诗一般认为是方干的作品，但也有诗集注为“一作程贺诗”。方干集中有《早发洞庭》一诗，说明方干曾游览过洞庭湖。这首《题君山》当是方干游洞庭时所作。其具体创作时间不详。 ', '君山：在湖南洞庭湖口，又名湘山、洞庭山，山势奇秀，景色旖旎。北魏郦道元《水经注·湘水》：“湖（ 洞庭湖 ）中有君山……湘君之所游处，故曰君山矣。”
于：一作“游”。方外：世外。指仙境或僧道的生活环境。《楚辞·远游》：“览方外之荒忽兮，沛罔象而自浮。”麻姑：神话中仙女名。传说东汉桓帝 时曾应仙人王远（字方平）召，降于蔡经家，为一美丽女子，年可十八九岁，手纤长似鸟瓜。蔡经见之，心中念曰：“背大痒时，得此爪以爬背，当佳。”方平知经心中所念，使人鞭之，且曰：“麻姑，神人也，汝何思谓爪可以爬背耶？”麻姑自云：“接侍以来，已见东海三为桑田。”又能掷米成珠，为种种变化之术。事见晋葛洪《神仙传》。
“闻说”句：一作“说道君山此本无”。闻说，听说。唐孟浩然《洛中访袁拾遗不遇》诗：“闻说梅花早，何如北地春？”
元：原来，原本。一作“云”。昆仑：山名，绵亘在今新疆、西藏和青海，在古代传说中是神仙遨游的地方。
海风：飓风。海，古代称塞外湖泊亦曰“海”。落：落到。洞庭湖：在湖南省北部、长江南岸，中国第二大淡水湖，素有“八百里洞庭”之称。湘、资、沅、澧四水汇流于此，在岳阳县城陵矶入长江。', '曾经在世外见到麻姑，听说君山古时候本无。
原是昆仑山顶一块石，飓风吹来落入洞庭湖。', '[{"bookId": "60cf5570f4aeaa0de5a29c42", "bookTitle": "唐诗鉴赏辞典（新一版）", "articleId": "610e92e47d0ac11454953a8e", "shortContent": "洞庭湖中有一座奇秀的青山，传说它是湘君曾游之地，故名君山，又名湘山、洞庭山。由于美丽的湖光山色与动人的神话传说，它激发过许多诗人的想象，写下许多美丽篇章。其中多有为人传诵的名句，如“遥望洞庭山水色，白银盘里一青螺”（刘禹锡《望洞庭》），“疑是水仙梳洗处，一螺青黛镜中心”（雍陶《题君山》）等等，巧比妙喻，尽态极妍，异曲同工。\n而方干这首《题君山》写法上全属别一路数，他采用了“游仙”的格局。\n“曾于方...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "6277b67724f39e08a5cb7c81", "bookTitle": "唐诗鉴赏辞典", "articleId": "6312707bf2af4e09d55b67a6", "shortContent": "在湖南岳阳市西南的洞庭湖中，有一座风景秀丽的青山，传说舜帝妃娥皇、女英曾游历此地，所以叫作君山。又叫湘山、洞庭山。君山由72个大小山峰所组成，山中异竹丛生，有斑竹、罗汉竹、实竹、方竹、紫竹、毛竹等，各具特色。它四面环水，刘禹锡《望洞庭》因此比之为“白银盘里一青螺”，雍陶《题君山》则说“疑是水仙梳洗处，一螺青黛镜中心”。\n\n方干初次来到君山，就被它的美所震惊。这些连绵起伏的峰峦，这些石堆中生长着的绿...", "authors": ["陈文新"], "pressName": "崇文书局"}, {"bookId": "6277bd28bdbf4803d00807c9", "bookTitle": "唐诗宋词鉴赏辞典", "articleId": "6312714a77683d1933015476", "shortContent": "在湖南岳阳市西南的洞庭湖中，有一座风景秀丽的青山，传说舜帝的二妃娥皇、女英曾游历此地，所以叫作君山。又叫湘山、洞庭山。君山由72个大小山峰所组成，山中异竹丛生，有斑竹、罗汉竹、实竹、方竹、紫竹、毛竹等，各具特色。它四面环水，刘禹锡《望洞庭》因此比之为“白银盘里一青螺”，雍陶《题君山》则说“疑是水仙梳洗处，一螺青黛镜中心”。\n方干初次来到君山，就被它的美所震惊。这些连绵起伏的峰峦，这些石堆中生长着的...", "authors": ["陈文新"], "pressName": "崇文书局"}]', '', 'center', 1554978356, '5caea5b1eaa375007444196a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641915, '秋晚自洞庭湖别业寄穆秀才', NULL, 5, 409, 0, 2, '皮日休', NULL, 12188, '5858e72b128fe1006dcc2881', '唐', 'shi', '诗', 'https://baike.baidu.com/item/%E7%A7%8B%E6%99%9A%E8%87%AA%E6%B4%9E%E5%BA%AD%E6%B9%96%E5%88%AB%E4%B8%9A%E5%AF%84%E7%A9%86%E7%A7%80%E6%89%8D/9786843?fr=aladdin', '', '破村寥落过重阳，独自撄宁葺草房。
风撦红蕉仍换叶，雨淋黄菊不成香。
野猿偷栗重窥户，落雁疑人更绕塘。
他日若修耆旧传，为予添取此书堂。', '', '', '', NULL, '', 'center', 1554978446, '5caea60c0237d700682db139', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641916, '绝句 · 其十六', NULL, 2, 321, 0, 1, '吕岩', NULL, 12581, '5835b348128fe10062cb8166', '唐', 'shi', '诗', '', '', '朝游北越暮苍梧，袖里青蛇胆气粗。
三入岳阳人不识，朗吟飞过洞庭湖。', '', '', '', NULL, '', 'center', 1554978984, '5caea78dc8959c0073d265d6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641917, '中秋夜君山台望月', NULL, 0, 125, 0, 1, '李涉', NULL, 12358, '5858e7571b69e6006cb0fa8c', '唐', 'shi', '诗', '', '', '大堤花里锦江前，诗酒同游四十年。
不料中秋最明夜，洞庭湖上见当天。', '', '', '', NULL, '', 'center', 1554979055, '5caea86ec8959c0073d27431', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641918, '题洞庭湖', NULL, 0, 1, 0, 1, '蔡押衙', NULL, 13881, '5858e8b18d6d810065c32a04', '唐', 'shi', '诗', '', '', '可怜洞庭湖，恰到三冬无髭须。', '', '湘江北流至岳阳，达蜀江，夏潦后，蜀江涨，势高，遏住湘波，让而退，溢为洞庭湖，阔数百里。秋水归壑，湖底渐出，唯一条湘川而已，此言其不成湖也。', '', NULL, '', 'center', 1554979228, '5caea911c05a80007312aa84', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641919, '过洞庭湖', NULL, 0, 54, 0, 1, '裴说', NULL, 13844, '5858e8a6b123db00658d90d0', '五代十国', 'shi', '诗', '', '', '浪高风力大，挂席亦言迟。及到堪忧处，争如未济时。
鱼龙侵莫测，雷雨动须疑。此际情无赖，何门寄所思。', '', '', '', NULL, '', 'center', 1554979278, '5caea945eaa3750074445a1a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641920, '上岳守', NULL, 1, 54, 0, 1, '裴说', NULL, 13844, '5858e8a6b123db00658d90d0', '五代十国', 'shi', '诗', '', '', '入郭宽万里，岳阳堪画图。
及窥贤太守，不见洞庭湖。', '', '', '', NULL, '', 'center', 1554979322, '5caea979a673f50068cf86db', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641968, '沉醉东风 · 有所感 ', NULL, 2, 11, 0, 1, '周德清', NULL, 10933, '5846342861ff4b006c3c5cbc', '元', 'qu', '曲', 'https://baike.baidu.com/item/%E6%B2%89%E9%86%89%E4%B8%9C%E9%A3%8E%C2%B7%E6%9C%89%E6%89%80%E6%84%9F/6230713?fr=aladdin', '', '羊续高高挂起，冯苦苦伤悲。大海边，长江内，多少渔矶？记得荆公旧日题：何处无鱼羹饭吃？', '', '羊续：东汉人。汉灵帝时任庐江、南阳二郡太守，为官廉正。同僚曾送他一条鱼，他推受不了，就挂在庭前。后来人们再要送鱼，他指着悬挂未动的鱼，示意无心收受。
冯（huān）：战国时齐国孟尝君的门客。因初时不受赏识，弹铗（长剑）作歌云：“长铗归去乎？食无鱼。”
荆公：北宋王安石封荆国公，人称王荆公。
鱼羹饭：以鱼羹做成的饭，借指江湖隐士的饭食。', '羊续做官，把送来的生鱼在庭前高悬；冯依人，为吃不上鱼而弹铗悲叹。大海旁边，长江里面，有多少渔人垂钓的矶岸。我记起王安石当年曾言，江湖隐居，哪里会吃不到鱼羹饭！', NULL, '', 'indent', 1555496137, '5cb68c48a3180b783271658c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641928, '满江红 · 题南京夷山驿', NULL, 1, 7, 6, 1, '王清惠', NULL, 18402, '5858ecb4128fe10069b27498', '宋', 'ci', '词', 'https://baike.baidu.com/item/%E6%BB%A1%E6%B1%9F%E7%BA%A2%C2%B7%E9%A2%98%E5%8D%97%E4%BA%AC%E5%A4%B7%E5%B1%B1%E9%A9%BF/17983680?fr=aladdin', '', '太液芙蓉，浑不似、旧时颜色。曾记得、春风雨露，玉楼金阙。名播兰馨妃后里，晕潮莲脸君王侧。忽一声、鼙鼓揭天来，繁华歇。
龙虎散，风云灭。千古恨，凭谁说。对山河百二，泪盈襟血。客馆夜惊尘土梦，宫车晓碾关山月。问嫦娥、于我肯从容，同圆缺？', '《满江红·题南京夷山驿》是南宋词人王清惠（一说张琼瑛）所写的一首词。词的上片以“太液芙蓉”开篇，追忆了宋亡前春风得意的宫廷生活。下片写宋室的覆亡，抒发了千古难消的亡国之恨。全词通过描写国家破灭，多次用典，描述自己的处境，婉转低回，细腻忧伤，表达了词人内心的悲痛之情。', '满江红：词牌名，又名：“上江虹”、“念良游”、“伤春曲”。双调九十三字，前片四十七字，八句，四仄韵；后片四十六字，十句，五仄韵。用入声韵者居多。
太液芙蓉：唐代长安城东大明宫内有太液池，此借指南宋宫廷。芙蓉，即荷花，比喻女子姣好的面容。
浑不似：全不像。
春风雨露：比喻帝王的宠爱。
玉楼金阙：指富丽的皇宫。
兰馨：本是女子首饰，这里借喻宫中的后妃。馨，一作“簪”。
晕潮：指女性脸上泛起红润的美丽光彩。
鼙（pí）鼓：指战鼓。
龙虎：比喻南宋的君臣。
风云：形容国家的威势。
山河百二：险要之地。
客馆：指驿馆，旅途中居住的地方。
宫车：指作者和后妃一行乘坐的车子。
从容：舒缓不迫。', '太液池的荷花浑然不似旧时娇艳记得曾经，沐浴春风，备承雨露，富丽堂皇的皇宫之中美好的名声在后妃中广播，莲颜生春，陪伴在君王左右。忽听得，军鼓声掀天而来，繁华顿歇。
君臣离敞，往日的风光消歇，千古之恨，向谁诉说？对着旧时的广阔山河，血泪沾湿衣袖，夜宿驿馆，扰被日闻尘土，飞扬、颠簸流离的赶路场景隙醒，一大早官车就踏着关山的月色赶路了。问嫦娥：是否能让我与你一道在月宫过邪清静的生活，共赏月囤月缺？', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e750e34a8757d5a0d9f85", "shortContent": "元至元十三年（1276）二月，元兵攻入杭州。三月，宫中自后妃以下都被俘虏北上。经过汴京夷山驿站时，嫔妃中有位才女昭仪王清惠，在驿站墙壁上题了上面这首《满江红》词，抒写亡国之痛。据《永乐大典》记载，王清惠这首词深受人们赞赏，中原传诵一时。\n词的起句“太液芙蓉，浑不似、旧时颜色”，仿佛是一声长长的叹息：好一朵生长在皇宫太液池里的荷花，如今“菡萏香销翠叶残”，同过去娇艳的颜色完全不一样了！显然，这是以花...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec60f03048e64fbd9be10", "shortContent": "据周密《浩然斋雅谈》与陶宗仪《辍耕录》记载：至元十三年（1276）正月，元兵攻入杭州，南宋从此灭亡。三月，宫中自后妃以下都被俘虏北上。经过汴京夷山驿站时，嫔妃中有位才女昭仪王清惠，在驿站墙壁上题了上面这首《满江红》词，抒写亡国之痛。据《永乐大典》记载，王清惠这首词深受人们赞赏，中原传诵一时。\n词的起句“太液芙蓉，浑不似、旧时颜色”，仿佛是一声长长的叹息：好一朵生长在皇宫太液池里的荷花，如今“菡萏香...", "authors": ["高", "原"], "pressName": "上海辞书出版社"}, {"bookId": "60fc32b023353c0ba53dd945", "bookTitle": "历代女性诗词鉴赏辞典", "articleId": "610ec790dbb8b379ee0a0598", "shortContent": "德祐二年（1276年）正月，元兵攻入南宋首都临安，时为昭仪（宫中嫔妃名，位列九嫔之首）的王清惠随三宫被掳，一起被押解到大都。北上途中，经过原北宋都城汴梁的夷山驿站时，今昔对比，勾起了深沉的家国之痛，于是在驿站的墙壁上题写了这首《满江红》。\n起始二句，写来到北宋皇宫所在地所引起的感受。汉唐两代皇宫内都有太液池，此用以比皇宫。王清惠刚刚经历了南宋的灭亡，现在又来到早已灭亡的北宋都城，以她宫人的身份，自...", "authors": ["张宏生"], "pressName": "上海辞书出版社"}, {"bookId": "62de2c40969f752916a586df", "bookTitle": "宋词三百首", "articleId": "63059256251899613caec0cb", "shortContent": "据周密《浩然斋雅谈》与陶宗仪《辍耕录》记载：至元十三年（1276）正月，元兵攻入杭州，南宋从此灭亡。三月，宫中自后妃以下都被俘虏北上。经过汴京夷山驿站时，嫔妃中有位才女昭仪王清惠，在驿站墙壁上题了上面这首《满江红》词，抒写亡国之痛。据《永乐大典》记载，王清惠这首词深受人们赞赏，中原传诵一时。\n\n词的起句“太液芙蓉，浑不似、旧时颜色”，仿佛是一声长长的叹息：好一朵生长在皇宫太液池里的荷花，如今“菡萏...", "authors": ["高　原"], "pressName": "上海辞书出版社"}]', '晚清词家陈廷焯《词则·放歌集》：凄凉怨慕，和者虽多，无出其右。', 'indent', 1555064256, '5caff53ec8959c0073c81a49', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641935, '丑奴儿 · 木犀', NULL, 0, 1659, 0, 1, '李纲', NULL, 28019, '5858f5ad128fe1006b884764', '宋', 'ci', '词', '', '', '幽芳不为春光发，直待秋风，直待秋风，香比馀花分外浓。
步摇金翠人如玉，吹动珑璁，吹动珑璁，恰似瑶台月下逢。', '', '', '', NULL, '', 'indent', 1583078776, '5cb16cf5d5de2b0071a0a101', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641947, ' 平山堂 ', NULL, 1, 513, 0, 1, '吴潜', NULL, 10788, '5858e5d8570c350069179bc0', '宋', 'shi', '诗', '', '', '昔日西风卷地狂，只堪吹雁过潇湘。
黄沙万里暮天远，白水一杯秋井香。
杨柳年年人老大，江山处处客凄凉。
朅来无限兴亡事，泪落淮南古战场。
', '', '', '', NULL, '', 'center', 1555323983, '5cb3ebcd7b968a0075f5a9ac', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641948, '平山堂吊古 ', NULL, 0, 65, 0, 1, '张蕴', NULL, 30842, '5858f83a128fe1006b885d63', '宋', 'shi', '诗', '', '', '隔江山色画图中，故址荒来与庙通。
画地雄吞淮海水，占星高直斗牛宫。
试评蜀味长泉变，欲唱欧词古柳空。
往事茫茫增感慨，聊凭戍卒指西东。', '', '', '', NULL, '', 'center', 1555324163, '5cb3ec81c8959c007591c478', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641949, ' 平山堂 ', NULL, 0, 131, 0, 1, '赵善括', NULL, 33054, '5858fa478e450a006cbaddc5', '宋', 'shi', '诗', '', '', '平山堂对妙高峰，极目郊原万里同。
杳霭四垂天不尽，萦纡一带水无穷。
城闉遥隔芙蓉浦，栏槛几经杨柳风。
想见风流贤太守，一尊时复酹欧翁。 ', '', '', '', NULL, '', 'center', 1555324209, '5cb3ecb0a91c930067e49b69', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641950, '平山堂观雨 ', NULL, 0, 590, 0, 1, '释道潜', NULL, 35200, '5858fc4d8e450a006cbaedcf', '宋', 'shi', '诗', '', '', '午枕藜床梦忽惊，柳边雷送雨如倾。
蜀冈西望芜城路，银竹森森十里横。', '', '', '', NULL, '', 'center', 1555324968, '5cb3efa6a673f5006814a5e2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641951, '登平山堂故址 ', NULL, 0, 292, 0, 1, '李孝光', NULL, 10899, '5858e5f061ff4b006875be1f', '元', 'shi', '诗', '', '', '蜀山有堂已改作，骑马出门西北行。日落牛羊散平楚，风高鸿雁过三城。
山河已失金汤固，汗竹空遗带砺盟。骆驼坡头孔融墓，令人忆尔泪纵横。
', '', '', '', NULL, '', 'center', 1555324998, '5cb3efc5c8959c007592038b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641961, '送刘判官赴丰州', NULL, 0, 341, 0, 1, '卢纶', NULL, 10014, '57b9c2f6c4c97100614832f4', '唐', 'shi', '诗', 'https://baike.baidu.com/item/%E9%80%81%E5%88%98%E5%88%A4%E5%AE%98%E8%B5%B4%E4%B8%B0%E5%B7%9E/4367895', '', '衔杯吹急管，满眼起风砂。
大漠山沉雪，长城草发花。
策行须战伐，寇至莫言家。
余亦祈勋者，如何别左车。', '', '衔杯：指饯别饮酒。
急管：指催行的军乐吹的很紧。
策行：古时命官授爵都用策书为信符。策行就是奉朝命而行。
祈勋：希望建立功勋。
左车：西汉李左车，为人深有谋略。此处借用，指刘判官，表示惜别的意思。', '', NULL, '', 'center', 1555411786, '5cb542c8a91c930067f83f09', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641962, '送流人', NULL, 0, 444, 0, 1, '张籍', NULL, 10134, '57b9c2fd7db2a20068bebb37', '唐', 'shi', '诗', '', '', '独向长城北，黄云暗塞天。
流名属边将，旧业作公田。
拥雪添军垒，收冰当井泉。
知君住应老，须记别乡年。', '', '', '', NULL, '', 'center', 1555411849, '5cb54308a673f5006827ff18', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641963, '续古二十九首', NULL, 2, 147, 1, 1, '陈陶', NULL, 10105, '57bb1449128fe1005f90affb', '唐', 'shi', '诗', 'https://baike.baidu.com/item/%E7%BB%AD%E5%8F%A4%E4%BA%8C%E5%8D%81%E4%B9%9D%E9%A6%96/12543777?fr=aladdin', '', '大尧登宝位，麟凤焕宸居。
海曲沾恩泽，还生比目鱼。
生值揖逊历，长歌东南春。
钓鳌年三十，未见天子巡。
轩辕承化日，群凤戏池台。
大朴衰丧后，仲尼生不来。
大道归孟门，萧兰日争长。
想得巢居时，碧江应无浪。
矻矻蓬舍下，慕君麒麟阁。
笑杀王子乔，寥天乘白鹤。
杳杳巫峡云，悠悠汉江水。
愁杀几少年，春风相忆地。
吴洲采芳客，桂棹木兰船。
日晚欲有寄，裴回春风前。
仙家风景晏，浮世年华速。
邂逅汉武时，蟠桃海东熟。
南国珊瑚树，好裁天马鞭。
鱼龙不解语，海曲空蝉娟。
周穆恣游幸，横天驱八龙。
宁知泰山下，日日望登封。
秦国饶罗网，中原绝麟凤。
万乘巡海回，鲍鱼空相送。
秦家无庙略，遮虏续长城。
万姓陇头死，中原荆棘生。
秦作东海桥，中州鬼辛苦。
纵得跨蓬莱，群仙亦飞去。
隋炀弃中国，龙舟巡海涯。
春风广陵苑，不见秦宫花。
范子相句践，灭吴成大勋。
虽然五湖去，终愧磻溪云。
麟凤识翔蛰，圣贤明卷舒。
哀哉嵇叔夜，智不及鶢鶋。
战地三尺骨，将军一身贵。
自古若吊冤，落花少于泪。
楚国千里旱，土龙日已多。
九谷竟枯死，好云闲嵯峨。
汉家三殿色，恩泽若飘风。
今日黄金屋，明朝长信宫。
南园杏花发，北渚梅花落。
吴女妒西施，容华日消铄。
山鸡理毛羽，自言胜乌鸢。
一朝逢鸑鷟，羞死南海边。
秦家卷衣贵，本是倡家子。
金殿一承恩，貂蝉满乡里。
魏宫薛家女，秀色倾三殿。
武帝鼎湖归，一身似秋扇。
婵娟越机里，织得双栖凤。
慰此殊世花，金梭忽停弄。
学古三十载，犹依白云居。
每览班超传，令人慵读书。
雄剑久濩落，夜吟秋风起。
不是懒为龙，此非延平水。
朝为杨柳色，暮作芙蓉好。
春风若有情，江山相逐老。
景龙临太极，五凤当庭舞。
谁信壁间梭，升天作云雨。
曾梦诸侯笑，康囚议脱枷。
千根池底藕，一朵火中花。', '', '', '', NULL, '', 'center', 1555412041, '5cb543bfa673f50068280a68', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641964, '登八达岭', NULL, 1, 23, 0, 1, '沈用济', NULL, 21170, '5858ef2961ff4b0063d73ef0', '清', 'shi', '诗', '', '', '策马出居庸，盘回上碧峰。
 坐窥京邑尽，行绕塞垣重。
夕照沉千帐，寒声折万松。
 回瞻陵寝地，云气总成龙。', '', '', '', NULL, '', 'center', 1555412170, '5cb54449c8959c0075a59f0a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641965, '饮马长城窟', NULL, 0, 376, 0, 1, '沈约', NULL, 35895, '5858fce161ff4b0068768127', '南北朝', 'shi', '诗', '', '', '介马渡龙堆，涂萦马屡回。前访昌海驿，
杂种宼轮台。旌幕卷烟雨，徒御犯冰埃。', '', '', '', NULL, '', 'center', 1555412265, '5cb544a8c8959c0075a5a53f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641967, '江上阻风 ', NULL, 1, 262, 0, 1, '宋琬', NULL, 20858, '5858eed5570c35006917e5a5', '清', 'shi', '诗', 'https://baike.baidu.com/item/%E6%B1%9F%E4%B8%8A%E9%98%BB%E9%A3%8E/1685667?fr=aladdin', '', '睡起无聊倚舵楼，瞿塘西望路悠悠。
长江巨浪征人泪，一夜西风共白头。', '《江上阻风》是清代诗人宋琬创作的一首七言绝句。这首诗前两句直抒胸臆，主要绘述无聊之状；后两句运用了比喻、夸张、拟人的修辞手法，着重诉说悲愁之思。此诗用语奇丽，比喻清新，委婉含蓄；寓情于景，情景交融。', '阻风：受大风影响，而阻断行程。
瞿塘：即瞿塘峡，在四川奉节县东，为长江三峡之首，诗中为四川的代称。
悠悠：遥远的样子。
征人：行旅者。
共白头：兼指江水和征人而言。', '睡醒起身心绪无聊，闲倚着舵楼，西望瞿塘水路悠悠，前程未可酬。
风险浪惊船阻江上，客思洒清泪，一夜西风吹白浪头，愁白游子头。', '[{"bookId": "60d939cea06dc908f045ad24", "bookTitle": "元明清诗鉴赏辞典（新一版）", "articleId": "610e8cf70f8fda5565053af3", "shortContent": "宋琬在顺康年间，因山东于七事曾两次下狱，释放后长期赋闲，康熙十一年（1672），年近花甲的宋琬又被起任四川按察使，这首诗就是赴任途中所作。瞿塘峡为举世闻名的三峡第一峡，“瞿塘险过白牢关”（杜甫《夔州歌十绝》），加上西风大作，巨浪拍空，雷轰咆哮，其惊险足以铺叙出一大篇文章。宋琬此诗，对此历代骚人墨客吟咏不绝的题目避之不就，以意切入，以景辅之，驱景入意，耐人寻味。“睡起无聊倚舵楼”，起句就不落窠臼。七...", "authors": ["王", "琳"], "pressName": "上海辞书出版社"}]', '中国作家协会会员王琳：宋琬的这首小诗典型地写出了清初文人在高压统治之下惊惧惶恐，愤懑悲凉的心态，而以白浪来比喻白发，更是前所未有的新奇手法，足可使此诗的艺术魅力，丝毫不逊色于它的社会认识作用。（《元明清诗鉴赏辞典》）', 'center', 1555496013, '5cb68bcba3180b7832715daf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642043, '幽梦影 · 卷一 · 十二', NULL, 4, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '对渊博友，如读异书；对风雅友，如读名人诗文；对谨饬友，如读圣贤经传；对滑稽友，如阅传奇小说。', '', '', '', NULL, '', 'indent', 1556016005, '5cbe7b02c8959c00752d319b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642044, '幽梦影 · 卷一 · 十三', NULL, 5, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '楷书须如文人，草书须如名将，行书介乎二者之间。如羊叔子缓带轻裘，正是佳处。', '', '', '', NULL, '程韡老曰：心斋不工书法，乃解作此语耶。', 'indent', 1556016020, '5cbe7b11f884af0065c02b27', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641969, '凤凰台次李太白韵', NULL, 0, 1434, 1, 1, '郭祥正', NULL, 30172, '5858f7b4128fe1006b88593a', '宋', 'shi', '诗', 'https://baike.baidu.com/item/%E5%87%A4%E5%87%B0%E5%8F%B0%E6%AC%A1%E6%9D%8E%E5%A4%AA%E7%99%BD%E9%9F%B5/2690635?fr=aladdin', '', '高台不见凤凰游，浩浩长江入海流。
舞罢青蛾同去国，战残白骨尚盈丘。
风摇落日催行棹，潮卷新沙换故洲。
结绮临春无处觅，年年荒草向人愁。', '《凤凰台次李太白韵》是宋代诗人郭祥正创作的一首七言律诗。这首诗首联写登临凤凰台后的所见。颔联写陈后主当年的历史。颈联写风中长江上急急行驶的舟船和新洲。尾联再回到陈后主的历史来，并对此沧桑变化发出感叹。这首诗追念古昔，叙述今朝，用独特的方式抒发吊古讽今的感慨，其蕴意使人回味不尽。', '凤凰台：故址在南京市城西风凰山。相传刘宋元嘉年间，有三只状如孔雀之异鸟集此，人谓凤凰，遂筑此台。
凤凰游：用李白诗首句“凤凰台上凤凰游”意。
青蛾（é）：原指美人之眉，此泛指美女。
盈：满。
棹（zhào）：摇船工具，泛指船。
故洲：白鹭洲，在南京西南长江中，李白诗有“二水中分白鹭洲”句。
结绮（qǐ）临春：两阁名。《陈书·张贵妃传》：南朝陈后主至德二年（584年），于光昭殿前起临春、结绮、望仙三阁。高数十丈，并数十问。后主自居临春阁。张贵妃等居结绮、望仙，以复道交相往来。', '登上了金陵凤凰高台，已经看不见凤凰游的盛景了，只见浩浩长江汹涌澎湃，入海东流。
那一批粉黛青蛾也都被掳离故国，唯有当年弃下的白骨，依旧掩埋在长江边野草丛中的古墓中。
傍晚起风了，风助浪势，不断地催送着那些船，湖水拥来的新沙，便改换了故洲，如今只能见新洲了。
临春、结绮两阁已经找不到了，荒草年年发，清风徐来时，随风飘动，如同在诉说着不尽的愁意。', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea7047d0ac11454958dd6", "shortContent": "凤凰台在金陵（今江苏南京）西南凤凰山上。据云，南朝刘宋元嘉年间曾有凤凰集于山上，乃筑台，并以“凤凰”分别命名山与台。唐天宝年间，大诗人李白离长安南游金陵，与友人崔宗之同上凤凰台，赋《登金陵凤凰台》七律一首。洎乎北宋，诗人郭祥正（表字功甫）步太白后尘，亦登台赋诗。《娱书堂诗话》道：“郭功甫尝与王荆公（王安石封号荆国公）登金陵凤凰台，追次李太白韵，援笔立成，一座尽倾”，说的即是本诗。这首诗不仅在形式上...", "authors": ["周慧珍"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646b0e9fb6a81d0c530dbec0", "shortContent": "凤凰台在金陵（今江苏南京）西南凤凰山上。据云，南朝刘宋元嘉年间曾有凤凰集于山上，乃筑台，并以“凤凰”分别命名山与台。唐天宝年间，大诗人李白离长安南游金陵，与友人崔宗之同上凤凰台，赋《登金陵凤凰台》七律一首。洎乎北宋，诗人郭祥正（表字功甫）步太白后尘，亦登台赋诗。《娱书堂诗话》道：“郭功甫尝与王荆公（王安石封号荆国公）登金陵凤凰台，追次李太白韵，援笔立成，一座尽倾”，说的即是本诗。这首诗不仅在形式上...", "authors": ["周慧珍"], "pressName": "上海辞书出版社"}]', '宋·赵与虤《娱书堂诗话》：“郭功甫尝与王荆公登金陵凤凰台，追次李太白韵，援笔立成，一座尽倾。”
明·朱承爵《存余堂诗话》：“真得太白逸气。”', 'center', 1555496201, '5cb68c87c8959c0075b7c7c4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641970, ' 长江 ', NULL, 0, 6, 0, 1, '赵蕃（昌父）', NULL, 36920, '5b0e085fee920a0044a0f0ee', '宋', 'shi', '诗', '', '', '长江滚滚来无尽，顺流逆挽纷成阵。
谁令转侧入漕河，舟似凫鹥亦难进。
长江漕河唇齿间，去留异态空浩叹。
孰能稍激长江水，顾使漕河舟亦起。 ', '', '', '', NULL, '', 'center', 1555496907, '5cb68f45a91c9300670ae4cf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641997, '再游蒋山', NULL, 2, 654, 0, 1, '李流谦', NULL, 27578, '5858f5401b69e60056f68be8', '宋', 'shi', '诗', '', '', '寒山寺里立斜晖，只有垂杨自在垂。
不待新亭成洒涕，向来已识宁馨儿。 ', '', '', '', NULL, '', 'center', 1555584092, '5cb7e3daa3180b7832863161', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (641998, '泊阊门', NULL, 0, 164, 0, 2, '顾瑛', NULL, 11670, '5858e6b061ff4b0063d6f98c', '元', 'shi', '诗', '', '', '枫叶芦花暗画船，银筝断绝十三弦。
西风只在寒山寺，长送钟声搅客眠。 ', '', '', '', NULL, '', 'center', 1555584158, '5cb7e41c7b968a0075306526', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642004, '登鹳雀楼', NULL, 6, 18, 0, 1, '畅当', NULL, 13783, '5858e89461ff4b006cb8be05', '唐', 'shi', '诗', 'https://baike.baidu.com/item/%E7%99%BB%E9%B9%B3%E9%9B%80%E6%A5%BC/5660164?fr=aladdin', '', '迥临飞鸟上，高出世尘间。
天势围平野，河流入断山。', '《登鹳雀楼》是唐代诗人畅当创作的一首五言绝句。这首诗描写宏伟的鹳雀楼和登楼所见的壮阔景象。前二句写楼高以寄胸怀，后二句写四围景象以抒激情。', '鹳（guàn）雀楼：古名鹳鹊楼，因时有鹳鹊栖其上而得名，其故址在永济市境内古蒲州城外西南的黄河岸边。
迥（jiǒng）临：远道而来。飞鸟：指鹳雀。
天势：天体的势。围：这里有“笼盖”的意思。
断山：指西山之间。', '远道来登鹳雀楼，楼阁高比人间。天空笼盖着辽阔的原野，奔明的黄河泻入群由之夺。', NULL, '沈德潜《唐诗别裁》：不减王之涣作。', 'center', 1555670377, '5cb934e77b968a00754393c9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642005, '和赵相公登鹳雀楼', NULL, 2, 58, 0, 1, '殷尧藩', NULL, 13025, '5858e7e4128fe10069b24d40', '唐', 'shi', '诗', 'https://baike.baidu.com/item/%E5%92%8C%E8%B5%B5%E7%9B%B8%E5%85%AC%E7%99%BB%E9%B9%B3%E9%9B%80%E6%A5%BC/16990474?fr=aladdin', '', '危楼高架泬寥天，上相闲登立彩旃。树色到京三百里，
河流归汉几千年。晴峰耸日当周道，秋谷垂花满舜田。
云路何人见高志，最看西面赤阑前。', '', '', '', NULL, '', 'center', 1555670474, '5cb93548a91c9377aa65a25a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642028, '幽梦影 · 序 · 一', NULL, 16, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '余穷经读史之余，好览稗官小说，自唐以来不下数百种。不但可以备考遗志，亦可以增长意识。如游名山大川者，必探断崖绝壑；玩乔松古柏者，必采秀草幽花。使耳目一新，襟情怡宕。此非头巾能戴、章句腐儒之所知也。
故余于咏诗譔文之暇，笔录古轶事、今新闻，自少至老，杂着数十种。如《说史》、《说诗》、《党鉴》、《盈鉴》、《东山谈苑》、《汗青余语》、《砚林不妄语》、《述茶史补》、《四莲花斋杂录》、《曼翁漫录》、《禅林漫录》、《读史浮白集》、《古今书字辨讹》、《秋雪丛谈》、《金陵野抄》之类，虽未雕版问世，而友人借抄，几遍东南诸郡，直可傲子云而睨君山矣！
天都张仲子心斋，家积缥缃，胸罗星宿，笔花缭绕，墨沉淋漓。其所著述，与余旗鼓相当，争奇斗富，如孙伯符与太史子义相遇于神亭；又如石崇、王恺击碎珊瑚时也。
其《幽梦影》一书，尤多格言妙论。言人之所不能言，道人之所未经道。展味低徊，似餐帝浆沆瀣，听钧天之广乐，不知此身在下方尘世矣。至如：律己宜带秋气，处世宜带春气。
婢可以当奴，奴不可以当婢。
无损于世谓之善人，有害于世谓之恶人。
寻乐境乃学仙，避苦境乃学佛。
超超玄着，绝胜支许清谈。
人当镂心铭肺，岂止佩韦书绅而已哉！', '', '', '', NULL, '', 'indent', 1556015345, '5cbe785bf884af0065c00236', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642029, '幽梦影 · 序 · 二', NULL, 3, 12, 0, 1, '孙致弥', NULL, 22345, '5858f03d570c35006917f076', '清', 'wen', '文', '', '', '心斋所著书满家，皆含经咀史，自出机杼，卓然可传。是编是其一脔片羽，然三才之理，万物之情，古今人事之变，皆在是矣。
顾题之以梦且影云者，吾闻海外有国焉。夜长而昼短，以昼之所为为幻，以梦之所遇为真；又闻人有恶其影而欲逃之者。然则梦也者，乃其所以为觉；影也者，乃其所以为形也耶？
广叟辞之隐语，言无罪而闻足戒，是则心斋所为尽心焉者也。读是编也，其可以闻破梦之钟，而就阴以息影也夫！
江东同学孙致弥题。', '', '', '', NULL, '', 'indent', 1556015368, '5cbe7886a91c9377aab2faa5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642045, '幽梦影 · 卷一 · 十四', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '人须求可入诗，物须求可入画。', '', '', '', NULL, '石天外曰：人须求可入画，物须求可入诗。亦妙。', 'indent', 1556016035, '5cbe7b22c8959c00752d33dd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642046, '幽梦影 · 卷一 · 十五', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '少年人须有老成之识见，老成人须有少年之襟怀。', '', '', '', NULL, '王司直曰：如此方不使岁月弄人。', 'indent', 1556016110, '5cbe7b6cf884af0065c0305e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642047, '幽梦影 · 卷一 · 十六', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '春者天之本怀，秋者天之别调。', '', '', '', NULL, '尤悔庵曰：夏者天之客气，冬者天之素风。', 'indent', 1556016126, '5cbe7b7df884af0065c0314b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642048, '幽梦影 · 卷一 · 十七', NULL, 4, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '昔人云：「若无花月美人，不愿生此世界。」予益一语云：「若无翰墨棋酒，不必定作人身。」', '', '', '', NULL, '', 'indent', 1556016144, '5cbe7b8ff884af0065c03271', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642030, '幽梦影 · 序 · 三', NULL, 2, 1, 0, 1, '石庞', NULL, 37060, '5dd016b3d4b56c0074c53f3f', '清', 'wen', '文', '', '', '张心斋先生，家自黄山，才奔陆海。丹榴赋就，锦月投怀；芍药辞成，敏花作馔。苏子瞻「十三楼外」，景物犹然；杜枚之「廿四桥头」，流风仍在。静能见性，洵哉人我不间而喜瞋不形！弱仅胜衣，或者清虚日来而滓秽日去。怜才惜玉，心是灵犀；绣腹锦胸，身同丹凤。花间选句，尽来珠玉之音；月下题词，已满珊瑚之笥。岂如兰台作赋，仅别东西；漆园著书，徒分内外而已哉！
然而繁文艳语，止才子余能；而卓识奇思，诚词人本色。若夫舒性情而为著述，缘阅历以作篇章，清如梦室之钟，令人猛省；响若尼山之铎，别有深思。则《幽梦影》一书 诚不能已于手舞足蹈、心旷神怡也！
其云「益人谓善，害物谓恶」感仿佛乎外王内圣之言；又谓「律己宜秋，处世宜春」，亦陶溶乎诚意正心之旨。他如片花寸草，均有会心；遥水近山，不遗玄想。息机物外，古人之糟粕不论；信手拈时，造化之精微入悟。湖山乘兴，尽可投囊；风月维潭，兼供挥麈。金绳觉路，宏开入梦之毫；宝筏迷津，直渡文长之舌。以风流为道学，寓教化于诙谐。
为色为空，知犹有这个在；如梦如影，且应做如是观。
湖上晦村学人石庞天外氏偶书。', '', '', '', NULL, '', 'indent', 1556015395, '5cbe78a2a91c9377aab2fbfd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642031, '幽梦影 · 序 · 四', NULL, 4, 1, 0, 1, '王守训', NULL, 37061, '5dd018ae43c257006aa44146', '清', 'wen', '文', '', '', '记曰：「和顺积于中，英华发于外。」
凡文人之立言，皆英华之发于外者也。无不本乎中之积，而适与其人肖焉。是故其人贤者，其言雅；其人哲者，其言快；其人高者，其言爽；其人达者，其言旷；其人奇者，其言创；其人韵者，其言多情思。张子所云：？对渊博友如读异书，对风雅友如读名人诗文，对谨饬友如读圣贤经传，对滑稽友如阅传奇小说。
正此意也。
彼在昔立言之人，到今传者，岂徒传其言哉！传其人而已矣。今举集中之言，有快若并州之剪，有爽若哀家之梨，有雅若钧天之奏，有旷若空谷之音；创者则如新锦出机，多情则如游丝袅树。
以为贤人可也，以为达人、奇人可也，以为哲人可也。譬之瀛洲之木，日中视之，一叶百形。
张子以一人而兼众妙，其殆瀛木之影欤？
然则阅乎此一编，不啻与张子晤对，罄彼我之怀！又奚俟梦中相寻，以致迷不知路，中道而返哉！
同学弟松溪王拜题。', '', '', '', NULL, '', 'indent', 1556015437, '5cbe78c5a673f51cbdf2d8a8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642032, '幽梦影 · 卷一 · 其一', NULL, 7, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '读经宜冬，其神专也；读史宜夏，其时久也；读诸子宜秋，其致别也；读诸集宜春，其机畅也。', '', '', '', NULL, '庞笔奴曰：读幽梦影，则春夏秋冬无时不宜。', 'indent', 1556015558, '5cbe7945c8959c00752d187c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642033, '幽梦影 · 卷一 · 其二', NULL, 5, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '经传宜独坐读，史鉴宜与友共读。', '', '', '', NULL, '', 'indent', 1556015583, '5cbe795cc8959c00752d19be', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642034, '幽梦影 · 卷一 · 其三', NULL, 9, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '无善无恶是圣人，善多恶少是贤者，善少恶多是庸人，有恶无善是小人，有善无恶是仙佛。', '', '', '', NULL, '江含征曰：先恶后善是回头人，先善后恶是两截人。', 'indent', 1556015646, '5cbe799cf884af0065c0160c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642035, '幽梦影 · 卷一 · 其四', NULL, 4, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '天下有一人知己，可以不恨。不独人也，物亦有之。如菊以渊明为知己，梅以和靖为知己，竹以子猷为知己，莲以濂溪为知己，桃以避秦人为知己，杏以董奉为知己，石以米颠为知己，荔枝以太真为知己，茶以卢仝、陆羽为知己，香草以灵均为知己，莼鲈以季鹰为知己，蕉以怀素为知己，瓜以邵平为知己，鸡以处宗为知己，鹅以右军为知己，鼓以祢衡为知己，琵琶以明妃为知己。一与之订，千秋不移。若松之于秦始、鹤之于卫懿，正所谓不可与作缘者也。', '', '董奉：字君异，三国名医。为人治病不取酬，惟令愈者植杏。数年得十余万株，杏结实则换谷济贫。
季鹰：晋朝人张翰字季鹰，在洛阳作官，见秋风起，想到家乡的味美的莼羹、鲈鱼，便弃官回乡。', '', NULL, '周星远曰：鹤于卫懿，犹当感恩，至吕政五大夫之爵，直是唐突十八公耳。', 'indent', 1556015775, '5cbe7a16c8959c00752d248b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642036, '幽梦影 · 卷一 · 其五', NULL, 6, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '为月忧云，为书忧蠹，为花忧风雨，为才子佳人忧命薄，真是菩萨心肠。', '', '', '', NULL, '江含征曰：我读此书时，不免为蟹忧雾；张竹坡曰：江子此言，直是为自己忧蟹耳。', 'indent', 1556015793, '5cbe7a30a3180b7832e6953b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642037, '幽梦影 · 卷一 · 其六', NULL, 5, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '花不可以无蝶，山不可以无泉，石不可以无苔，水不可以无藻，乔木不可以无藤萝，人不可以无癖。', '', '', '', NULL, '', 'indent', 1556015816, '5cbe7a45f884af0065c01fea', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642038, '幽梦影 · 卷一 · 其七', NULL, 8, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '春听鸟声，夏听蝉声，秋听虫声，冬听雪声；白昼听棋声，月下听箫声；山中听松声，水际听欸乃声，方不虚生此耳。若恶少斥辱，悍妻诟谇，真不若耳聋也。', '', '', '', NULL, '张迂庵曰：可见对恶少悍妻，尚不若日与禽虫周旋也。又曰：读此方知先生耳聋之妙。', 'indent', 1556015842, '5cbe7a61c8959c00752d2921', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642039, '幽梦影 · 卷一 · 其八', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '上元须酌豪友，端午须酌丽友，七夕须酌韵友，中秋须酌淡友，重九须酌逸友。', '', '', '', NULL, '尤谨庸曰：上元酌灯，端午酌彩丝，七夕酌双星，中秋酌月，重九酌菊，则吾友俱备矣。', 'indent', 1556015865, '5cbe7a77f884af0065c022d4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642040, '幽梦影 · 卷一 · 其九', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '鳞虫中金鱼，羽虫中紫燕，可云物类神仙。正如东方曼倩避世，金马门人不得而害之。', '', '东方曼倩：即东方朔，西汉辞赋家。字曼倩。性格诙谐，言词敏捷，滑稽多智。
金马门：官署之门，以门旁有铜马，故称。', '', NULL, '', 'indent', 1556015887, '5cbe7a8da673f51cbdf2f74e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642041, '幽梦影 · 卷一 · 其十', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '入世，须学东方曼倩；出世，须学佛印了元。', '', '东方曼倩：即东方朔，西汉辞赋家。字曼倩。性格诙谐，言词敏捷，滑稽多智。
佛印了元：即佛印禅师，宋代高僧与大文学家苏东坡过从甚密，往来酬唱，出世又入世。', '', NULL, '殷日戒曰：曼倩诗有云，依隐玩世，诡时不逢，此其所以免死也。
石天外曰：入得世，然后出世，入世出世打成一片，方可得心应手处。', 'indent', 1556015933, '5cbe7aa2a91c9377aab31ba0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642042, '幽梦影 · 卷一 · 十一', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '赏花宜对佳人，醉月宜对韵人，映雪宜对高人。', '', '', '', NULL, '张竹坡曰：聚花月雪于一时，合佳韵高为一人，吾当不赏而心醉矣。', 'indent', 1556015953, '5cbe7acfa3180b7832e69e52', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642049, '幽梦影 · 卷一 · 十八', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '愿在木而为樗，愿在草而为蓍，愿在鸟而为鸥，愿在兽而为廌，愿在虫而为蝶，愿在鱼而为鲲。', '', '樗（chū）：臭椿，取其不才终其天年。
蓍（shī）：草本植物，古代用以占卜，取其前知之意。
鸥：取其自在忘忧。
廌（zhì）：古同「獬豸」，古代神兽，相传能辨是非。
鲲：取其逍遥遨游。', '', NULL, '尤悔庵曰：第一大愿又曰：愿在人而为梦。
尤慧珠曰：我亦有大愿，愿在梦而为影。', 'indent', 1556016163, '5cbe7ba1a3180b7832e6ac32', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642050, '幽梦影 · 卷一 · 十九', NULL, 4, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '黄九烟先生云：「古今人必有其偶双。千古而无偶者，其惟盘古乎？」予谓：「盘古亦未尝无偶，但我辈不及见耳。其人为谁？即此劫尽时最后一人是也。」', '', '', '', NULL, '', 'indent', 1556016188, '5cbe7bb9a3180b7832e6ad7b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642051, '幽梦影 · 卷一 · 二十', NULL, 3, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '古人以冬为三余。予谓当以夏为三余：晨起者，夜之余；夜坐者，昼之余；午睡者，应酬人事之余。古人诗曰：「我爱夏日长」，洵不诬也。', '', '', '', NULL, '张竹坡曰：眼前问冬夏皆有余者，能几人乎？', 'indent', 1556016215, '5cbe7bd4a3180b7832e6af34', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642052, '幽梦影 · 卷一 · 二十一', NULL, 9, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '庄周梦为蝴蝶，庄周之幸也；蝴蝶梦为庄周，蝴蝶之不幸也。', '', '', '', NULL, '黄九烟曰：惟庄周乃能梦为蝴蝶，惟蝴蝶乃能梦为庄周耳。若世之扰扰红尘者，其能有此等梦乎。
江含征曰：周之喜梦为蝴蝶者，以其入花深也。若梦甫酣而乍醒，则又如嗜酒者梦赴席。而为妻惊醒，不得不加痛诟谇矣。', 'indent', 1556016231, '5cbe7be6f884af0065c037ca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642053, '幽梦影 · 卷一 · 二十二', NULL, 4, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '艺花可以邀蝶，累石可以邀云，栽松可以邀风，贮水可以邀萍，筑台可以邀月，种蕉可以邀雨，植柳可以邀蝉。', '', '', '', NULL, '曹秋岳曰：藏书可以邀友。
崔莲峰曰：酿酒可以邀我。
庞天池曰：不仁可以邀富。', 'indent', 1556016257, '5cbe7c00a91c9377aab332f1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642054, '幽梦影 · 卷一 · 二十三', NULL, 4, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '景有言之极幽，而实萧索者，烟雨也；境有言之极雅，而实难堪者，贫病也；声有言之极韵，而实粗鄙者，卖花声也。', '', '', '', NULL, '谢海翁曰：物有言之极俗，而实可爱者，阿堵物也。
张竹坡曰：我幸得极雅之境。', 'indent', 1556016278, '5cbe7c15a3180b7832e6b3bc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642055, '幽梦影 · 卷一 · 二十四', NULL, 3, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '才子而富贵，定从福慧双修得来。', '', '', '', NULL, '陈鹤山曰：释氏云：「修福不修慧，象身挂璎珞。修慧不修福，罗汉供应薄。」正以其难兼耳，山翁发为此论，直是夫子自道。
江含征曰：宁可拚一副菜园肚皮，不可有一副酒肉面孔。', 'indent', 1556016295, '5cbe7c26a3180b7832e6b456', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642056, '幽梦影 · 卷一 · 二十五', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '新月恨其易沉，缺月恨其迟上。', '', '', '', NULL, '冒青若曰：天道忌盈，沉与迟，请君勿恨。', 'indent', 1556016315, '5cbe7c3ac8959c00752d4628', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642057, '幽梦影 · 卷一 · 二十六', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '躬耕，吾所不能，学灌园而已矣；樵薪，吾所不能，学薙草而已矣。', '', '', '', NULL, '汪扶晨曰：不为老农，而为老圃，可云半个樊迟。', 'indent', 1556016335, '5cbe7c4da91c9377aab33881', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642058, '幽梦影 · 卷一 · 二十七', NULL, 4, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '一恨书囊易蛀，二恨夏夜有蚊，三恨月台易漏，四恨菊叶多焦，五恨松多大蚁，六恨竹多落叶，七恨桂、荷易谢，八恨薜、萝藏虺，九恨架花生刺，十恨河豚多毒。', '', '', '', NULL, '石天外曰：予另有二恨：一曰才人无行，二曰佳人薄命。', 'indent', 1556016353, '5cbe7c5fc8959c00752d4810', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642059, '幽梦影 · 卷一 · 二十八', NULL, 6, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '楼上看山，城头看雪，灯前看月，舟中看霞，月下看美人，另是一番情境。', '', '', '', NULL, '尤谨庸曰：山上看雪，雪中看花，花中看美人。亦可。', 'indent', 1556016371, '5cbe7c72c8959c00752d4934', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642060, '幽梦影 · 卷一 · 二十九', NULL, 4, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '山之光，水之声，月之色，花之香，文人之韵致，美人之姿态，皆无可名状，无可执着。真足以摄召魂梦，颠倒情思。', '', '', '', NULL, '吴街南曰：以极有韵致之文人，与极有姿态之美人，共坐于山水花月间，不知此时魂梦何如？情思何如？', 'indent', 1556016388, '5cbe7c83a673f51cbdf317fa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642061, '幽梦影 · 卷一 · 三十', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '假使梦能自主，虽千里无难命驾，可不羡长房之缩地；死者可以晤对，可不需少君之招魂；五岳可以卧游，可不俟婚嫁之尽毕。', '', '', '', NULL, '张竹坡曰：梦魂能自主，则可一生死、通人鬼，真见道之言也。', 'indent', 1556016412, '5cbe7c9ba3180b7832e6bc42', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642062, '幽梦影 · 卷一 · 三十一', NULL, 4, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '昭君以和亲而显，刘蕡以下第而传；可谓之不幸，不可谓之缺陷。', '', '', '', NULL, '江含征曰：若故折黄雀腿而后医之，亦不可。', 'indent', 1556016431, '5cbe7cacf884af0065c043a7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642063, '幽梦影 · 卷一 · 三十二', NULL, 3, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '以爱花之心爱美人，则领略自饶别趣；以爱美人之心爱花，则护惜倍有深情。', '', '', '', NULL, '', 'indent', 1556016444, '5cbe7cbbf884af0065c044ab', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642064, '幽梦影 · 卷一 · 三十三', NULL, 6, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '美人之胜于花者，解语也；花之胜于美人者，生香也。二者不可得兼，舍生香而解语者也。', '', '', '', NULL, '', 'indent', 1556016461, '5cbe7ccba3180b7832e6bec6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642065, '幽梦影 · 卷一 · 三十四', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '窗内人于窗纸上作字，吾于窗外观之，极佳。', '', '', '', NULL, '江含征曰：若索债人于窗外纸上画，吾且望之却走矣！', 'indent', 1556016477, '5cbe7cdcc8959c00752d503b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642066, '幽梦影 · 卷一 · 三十五', NULL, 17, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '少年读书，如隙中窥月；中年读书，如庭中望月；老年读书，如台上玩月。皆以阅历之浅深，为所得之浅深耳。', '', '', '', NULL, '张竹坡曰：吾叔此论，直置身广寒宫里，下视大千世界，皆清光似水矣。', 'indent', 1556016495, '5cbe7cecc8959c00752d5117', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642129, '幽梦影 · 卷一 · 九十八', NULL, 3, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '人莫乐于闲，非无所事事之谓也。闲则能读书，闲则能游名胜，闲则能交益友，闲则能饮酒，闲则能著书。天下之乐，孰大于是？', '', '', '', NULL, '', 'indent', 1556102259, '5cbfcbf1a673f500684c95c1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642103, '幽梦影 · 卷一 · 七十二', NULL, 3, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '积画以成字，积字以成句，积句以成篇，为之文。文体日增，至八股而遂止。如古文、如诗、如赋、如词、如曲、如说部、如传奇小说，皆自无而有。方其未有之时，固不料后来之有此一体也。逮既有此一体之后，又若天造地设，为世必应有之物。然自明以来，未见有创一体裁新人耳目者。遥计百年之后，必有其人，惜乎不及见耳。', '', '', '', NULL, '', 'indent', 1556017209, '5cbe7fb7a3180b7832e6e80e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642104, '幽梦影 · 卷一 · 七十三', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '云映日而成霞，泉挂岩而成瀑。所托者异，而名亦因之。此友道之所以可贵也。', '', '张竹坡曰：非日而云不映，非岩而泉不挂，此友道之所以当择也。', '', NULL, '', 'indent', 1556101775, '5cbfca0da673f500684c74ff', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642105, '幽梦影 · 卷一 · 七十四 ', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '大家之文，吾爱之慕之，吾愿学之；名家之文，吾爱之慕之，吾不敢学之。学大家而不得，所谓「刻鹄不成尚类鹜」也，学名家而不得，则是「画虎不成反类狗」矣。', '', '', '', NULL, '', 'indent', 1556101791, '5cbfca1d17b54d0068918010', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642106, '幽梦影 · 卷一 · 七十五', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '由戒得定，由定得慧，勉强渐近，自然炼精化气，炼气化神，清虚有何渣滓？', '', '', '', NULL, '尤悔庵曰：极平常语，然道在是矣。', 'indent', 1556101808, '5cbfca2ea673f500684c767d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642107, '幽梦影 · 卷一 · 七十六', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '南北东西，一定之位也；前后左右，无定之位也。', '', '', '', NULL, '', 'indent', 1556101833, '5cbfca47a91c930069db2517', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642108, '幽梦影 · 卷一 · 七十七', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '予尝谓二氏不可废，非袭夫大养济院之陈言也。盖名山胜景，我辈每思褰裳就之，使非琳宫、梵刹，则倦时无可驻足，饥时谁与授餐？忽有疾风暴雨，五大夫果真足恃乎？又或邱壑深邃，非一日可了，岂能露宿以待明日乎？虎豹蛇虺，能保其不人患乎？又或为士大夫所有，果能不问主人，任我登陟凭吊而莫之禁乎？不特此也，甲之所有，乙思起而夺之，是启争端也；祖父之所创建，子孙贫，力不能修葺，其倾颓之状，反足令山川减色矣。然此特就名山胜境言之耳。', '', '二氏：指佛、道二家。
养济院：收容救助贫民的机构。
褰裳：提起衣裳。
琳宫：道观的美称。
五大夫：松树的别称。', '', NULL, '释中洲曰：此论一出，量无悭檀越矣。', 'indent', 1556101861, '5cbfca60a673f500684c799e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642109, '幽梦影 · 卷一 · 七十八', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '即城市之内，与夫四达之衢，亦不可少此一种。客游可做居停，一也；长途可以稍憩，二也；夏之茗，冬之姜汤，复可以济役夫负戴之困，三也。凡此皆就事理言之，非二氏福报之说也。', '', '', '', NULL, '', 'indent', 1556101881, '5cbfca750237d70068c072c4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642110, '幽梦影 · 卷一 · 七十九', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '虽不善书，而笔砚不可不精；虽不业医，而验方不可不存；虽不工弈，而楸枰不可不备。', '', '', '', NULL, '', 'indent', 1556101896, '5cbfca860237d70068c073cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642111, '幽梦影 · 卷一 · 八十', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '方外不必戒酒，但须戒俗；红裙不必通文，但须得趣。', '', '', '', NULL, '', 'indent', 1556101914, '5cbfca97c8959c006c962ec2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642112, '幽梦影 · 卷一 · 八十一', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '梅边之石，宜古；松下之石，宜拙；竹傍之石，宜瘦；盆内之石，宜巧。', '', '', '', NULL, '', 'indent', 1556101937, '5cbfcaae0237d70068c075fa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642113, '幽梦影 · 卷一 · 八十二', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '律己宜带秋气，处事宜带春气。', '', '', '', NULL, '', 'indent', 1556101952, '5cbfcabe0237d70068c076fa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642114, '幽梦影 · 卷一 · 八十三', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '厌催租之败意，亟宜早早完粮；喜老衲之谈禅，难免常常布施。', '', '', '', NULL, '', 'indent', 1556101969, '5cbfcacf0237d70068c077bf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642115, '幽梦影 · 卷一 · 八十四', NULL, 4, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '松下听琴，月下听箫，涧边听瀑布，山中听梵呗，觉耳中别有不同。', '', '', '', NULL, '', 'indent', 1556101988, '5cbfcae2a91c930069db2e54', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642116, '幽梦影 · 卷一 · 八十五', NULL, 3, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '月下听禅，旨趣益远；月下说剑，肝胆益真；月下论诗，风致益幽；月下对美人，情意益笃。', '', '', '', NULL, '', 'indent', 1556102004, '5cbfcaf117b54d0068918de6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642117, '幽梦影 · 卷一 · 八十六', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '有地上之山水，有画上之山水，有梦中之山水，有胸中之山水。地上者，妙在邱壑深邃；画上者，妙在笔墨淋漓；梦中者，妙在景象变幻；胸中者，妙在位置自如。', '', '', '', NULL, '', 'indent', 1556102021, '5cbfcb030237d70068c07afb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642118, '幽梦影 · 卷一 · 八十七', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '一日之计，种蕉；一岁之计，种竹；十年之计，种柳；百年之计，种松。', '', '', '', NULL, '', 'indent', 1556102040, '5cbfcb15c8959c006c9636cc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642119, '幽梦影 · 卷一 · 八十八', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '春雨宜读书，夏雨宜弈棋，秋雨宜检藏，冬雨宜饮酒。', '', '', '', NULL, '', 'indent', 1556102056, '5cbfcb26a91c930069db32d9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642120, '幽梦影 · 卷一 · 八十九', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '诗文之体，得秋气为佳；词曲之体，得春气为佳。', '', '', '', NULL, '', 'indent', 1556102072, '5cbfcb3617b54d00689192dc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642121, '幽梦影 · 卷一 · 九十', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '抄写之笔墨，不必过求其佳，若施之缣素，则不可不求其佳；诵读之书籍，不必过求其备，若以供稽考，则不可不求其备；游历之山水，不必过求其妙，若因之卜居，则不可不求其妙。', '', '', '', NULL, '', 'indent', 1556102102, '5cbfcb5417b54d0068919646', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642122, '幽梦影 · 卷一 · 九十一', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '人非圣贤，安能无所不知？只知其一，惟恐不止其一，复求知其二者，上也；止知其一，因人言始知有其二者，次也；止知其一，人言有其二而莫之信者，又其次也；止知其一，恶人言有其二者，斯下之下矣。', '', '', '', NULL, '', 'indent', 1556102125, '5cbfcb69a673f500684c8bb3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642123, '幽梦影 · 卷一 · 九十二', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '史官所纪者，直世界也；职方所载者，横世界也。', '', '', '', NULL, '', 'indent', 1556102141, '5cbfcb7b17b54d00689199e4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642124, '幽梦影 · 卷一 · 九十三', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '先天八卦，竖看者也；后天八卦，横看者也。', '', '', '', NULL, '', 'indent', 1556102157, '5cbfcb8b0237d70068c086cd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642131, '幽梦影 · 卷一 · 一百', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '平、上、去、入，乃一定之至理。然入声之为字也少，不得谓凡字有四声也。世之调平仄者，于入声之无其字者，往往以不相合之音隶于其下。为所隶者，苟无平、上、去之三声，则是以寡妇配鳏夫，犹之可也。若所隶之字，自有其平、上、去三声，而欲强以从我，则是干有夫之妇矣，其可乎？', '', '', '', NULL, '', 'indent', 1556102297, '5cbfcc170237d70068c08f58', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642133, '幽梦影 · 卷二 · 其一', NULL, 6, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '《水浒传》是一部怒书，《西游记》是一部悟书，《金瓶梅》是一部哀书。', '', '', '', NULL, '', 'indent', 1556102362, '5cbfcc580237d70068c09879', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642134, '幽梦影 · 卷二 · 其二', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '读书最乐，若读史书，则喜少怒多。究之，怒处亦乐处也。', '', '', '', NULL, '', 'indent', 1556102378, '5cbfcc6917b54d006891af4b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642135, '幽梦影 · 卷二 · 其三', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '发前人未发之论，方是奇书；言妻子难言之情，乃为密友。  ', '', '', '', NULL, '', 'indent', 1556102398, '5cbfcc7ca91c930069db592d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642136, '幽梦影 · 卷二 · 其四', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '一介之士，必有密友，密友，不必定是刎颈之交。大率虽千里之遥，皆可相信，而不为浮言所动；闻有谤之者，即多方为之辩析而后已；事之宜行宜止者，代为筹画决断；或事当利害关头，有所需而后济者，即不必与闻，亦不虑其负我与否，竟为力承其事。此皆所谓密友也。', '', '', '', NULL, '', 'indent', 1556102413, '5cbfcc8ca673f500684ca954', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642137, '幽梦影 · 卷二 · 其五', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '风流自赏，只容花鸟趋陪；真率谁知？合受烟霞供养。', '', '', '', NULL, '', 'indent', 1556102429, '5cbfcc9ba673f500684caa4d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642138, '幽梦影 · 卷二 · 其六', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '万事可忘，难忘者名心一段；千般易淡，未淡者美酒三杯。', '', '', '', NULL, '', 'indent', 1556102452, '5cbfccb20237d70068c09cf1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642139, '幽梦影 · 卷二 · 其七', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '芰荷可食，而亦可衣；金石可器，而亦可服。', '', '', '', NULL, '', 'indent', 1556102476, '5cbfcccac8959c006c9660fd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642140, '幽梦影 · 卷二 · 其八 ', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '宜于耳复宜于目者，弹琴也，吹箫也；宜于耳不宜于目者，吹笙也，擫（原字厌上手下）管也。', '', '', '', NULL, '', 'indent', 1556102494, '5cbfccdc17b54d006891b609', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642141, '幽梦影 · 卷二 · 其九', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '看晓妆宜于傅粉之后。', '', '', '', NULL, '', 'indent', 1556102516, '5cbfccf117b54d006891b725', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642142, '幽梦影 · 卷二 · 其十', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '我不知我之生前，当春秋之季，曾一识西施否？当典午之时，曾一看卫玠否？当义熙之世，曾一醉渊明否？当天宝之代，曾一睹太真否？当元丰之朝，曾一晤东坡否？千古之上，相思者不止此，数人则其尤甚者，故姑举之，以概其余也。', '', '', '', NULL, '', 'indent', 1556102532, '5cbfcd0217b54d006891b80c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642143, '幽梦影 · 卷二 · 十一', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '我又不知在隆万时，曾于旧院中交几名妓？眉公、伯虎、若士、赤水诸君，曾共我谈笑几回？茫茫宇宙，我今当向谁问之耶？', '', '', '', NULL, '', 'indent', 1556102549, '5cbfcd1317b54d006891b8ed', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642144, '幽梦影 · 卷二 · 十二', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '文章是有字句之锦绣，锦绣是无字句之文章，两者同出于一原。姑即粗迹论之，如金陵，如武林，如姑苏，书林之所在，即机杼之所在也。', '', '', '', NULL, '', 'indent', 1556102570, '5cbfcd28c8959c006c966738', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642145, '幽梦影 · 卷二 · 十三', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '予尝集诸法帖字为诗。字之不复而多者，莫善于《千字文》，然诗家目前常用之字，犹苦其未备。如天文之烟、霞、风、雪，地理之江、山、塘、岸，时令之春、宵、晓、暮，人物之翁、僧、渔、樵，花木之花、柳、苔、萍，鸟兽之蜂、蝶、莺、燕，宫室之台、栏、轩、窗，器用之舟、船、壶、杖，人事之梦、忆、愁、恨，衣服之裙、袖、锦、绮，饮食之茶、浆、饮、酌，身体之须、眉、韵、态，声色之红、绿、香、艳，文史之骚、赋、题、吟，数目之一、三、双、半，皆无其字。《千字文》且然，况其它乎？', '', '', '', NULL, '', 'indent', 1556102590, '5cbfcd3c17b54d006891bb18', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642146, '幽梦影 · 卷二 · 十四', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '花不可见其落，月不可见其沉，美人不可见其夭。', '', '', '', NULL, '', 'indent', 1556102607, '5cbfcd4e0237d70068c0a593', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642147, '幽梦影 · 卷二 · 十五', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '种花须见其开，待月须见其满，著书须见其成，美人须见其畅适，方有实际。否则皆为虚设。', '', '', '', NULL, '', 'indent', 1556102625, '5cbfcd5f17b54d006891bd67', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642148, '幽梦影 · 卷二 · 十六', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '惠施多方，其书五车；虞卿以穷愁著书，今皆不传。不知书中果作何语？我不见古人，安得不恨！', '', '', '', NULL, '', 'indent', 1556102648, '5cbfcd7617b54d006891be74', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642149, '幽梦影 · 卷二 · 十七', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '以松花为量，以松实为香，以松枝为麈尾，以松阴为步障，以松涛为鼓吹。山居得乔松百余章，真乃受用不尽。', '', '', '', NULL, '', 'indent', 1556102666, '5cbfcd8817b54d006891bfa2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642150, '幽梦影 · 卷二 · 十八', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '玩月之法，皎洁则仰观，朦胧则宜俯视。', '', '', '', NULL, '', 'indent', 1556102680, '5cbfcd960237d70068c0a9bd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642151, '幽梦影 · 卷二 · 十九', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '孩提之童，一无所知。目不能辨美恶，耳不能判清浊，鼻不能别香臭。至若味之甘苦，则不第知之，且能取之弃之。告子以甘食、悦色为性，殆指此类耳。', '', '', '', NULL, '', 'indent', 1556102981, '5cbfcec1c8959c006c967bb3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642152, '幽梦影 · 卷二 · 二十', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '凡事不宜刻，若读书则不可不刻；凡事不宜贪，若买书则不可不贪；凡事不宜痴，若行善则不可不痴。', '', '', '', NULL, '', 'indent', 1556103000, '5cbfced5a673f500684cc9ef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642153, '幽梦影 · 卷二 · 二十一', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '酒可好，不可骂座；色可好，不可伤生；财可好，不可昧心；气可好，不可越理。', '', '', '', NULL, '', 'indent', 1556103370, '5cbfd04817b54d006891ed3b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642173, '幽梦影 · 卷二 · 四十', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '黎举云：「欲令梅聘海棠，枨子臣樱桃，以芥嫁笋，但时不同耳。」予谓物各有偶，儗必于伦，今之嫁娶，殊觉未当。如梅之为物，品最清高；棠之为物，姿极妖艳。即使同时，亦不可为夫妇。不若梅聘梨花，海棠嫁杏，橼臣佛手，荔枝臣樱桃，秋海棠嫁雁来红，庶几相称耳。至若以芥嫁笋，笋如有知，必受河东狮子之累矣。', '', '', '', NULL, '', 'indent', 1556185362, '5cc11090d5de2b007360cab5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642174, '幽梦影 · 卷二 · 四十一', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '五色有太过，有不及，惟黑与白无太过。', '', '', '', NULL, '', 'indent', 1556185380, '5cc110a217b54d0068358d12', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642175, '幽梦影 · 卷三 · 其一', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '许氏《说文》分部，有止有其部，而无所属之字者，下必注云：「凡某之属，皆从某。」赘句殊觉可笑，何不省此一句乎？', '', '注：《说文》说解条例之一，用来标明部首的用语。如《示部》「示」字下「凡示之属皆从示」。', '', NULL, '', 'indent', 1556185396, '5cc110b10237d70068fc820e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642176, '幽梦影 · 卷三 · 其二', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '阅《水浒传》，至鲁达打镇关西，武松打虎，因思人生必有一桩极快意事，方不枉在生一场；即不能有其事，亦须着得一种得意之书，庶几无憾耳。', '如李太白有贵妃捧砚事，司马相如有文君当炉事，严子陵有足加帝腹事，王涣、王昌龄有旗亭画壁事，王子安有顺风过江作滕王阁序事之类。', '', '', NULL, '', 'indent', 1556185416, '5cc110c6a91c930068221aef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642177, '幽梦影 · 卷三 · 其三', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '春风如酒，夏风如茗，秋风如烟，冬风如姜芥。', '', '', '', NULL, '张竹坡：安得东风夜夜来。', 'indent', 1556185431, '5cc110d6d5de2b007360ce72', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642178, '幽梦影 · 卷三 · 其四', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '冰裂纹极雅，然宜细，不宜肥。若以之作窗栏，殊不耐观也。', '', '冰裂纹：陶瓷上的面裂纹，形状犹如冰裂后的纹路，所以叫冰裂纹。', '', NULL, '', 'indent', 1556185446, '5cc110e4d5de2b007360cf0d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642179, '幽梦影 · 卷三 · 其五', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '鸟声之最佳者：画眉第一，黄鹂、百舌次之。然黄鹂、百舌，世未有笼而畜之者，其殆高士之俦，可闻而不可屈者耶。', '', '', '', NULL, '', 'indent', 1556185461, '5cc110f30237d70068fc85c6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642180, '幽梦影 · 卷三 · 其六', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '不治生产，其后必致累人；专务交游，其后必致累己。', '', '', '', NULL, '杨圣藻：晨钟夕磬，发人深省。', 'indent', 1556185477, '5cc111030237d70068fc86b0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642181, '幽梦影 · 卷三 · 其七', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '昔人云：「妇人识字，多致诲淫。」予谓此非识字之过也。盖识字则非无闻之人，其淫也，人易得而知耳。', '', '', '', NULL, '', 'indent', 1556185496, '5cc11117f884af00678a077b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642182, '幽梦影 · 卷三 · 其八', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '善读书者，无之而非书：山水亦书也，棋酒亦书也，花月亦书也。善游山水者，无之而非山水：书史亦山水也，诗酒亦山水也，花月亦山水也。', '', '', '', NULL, '尤悔庵：山耶水耶书耶，一而二，二而三，三而一者也。', 'indent', 1556185512, '5cc11126f884af00678a0887', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642183, '幽梦影 · 卷三 · 其九', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '园亭之妙在邱壑布置，不在雕绘琐屑。往往见人家园亭，屋脊墙头，雕砖镂瓦。非不穷极工巧，然未久即坏，坏后极难修葺。是何如朴素之为佳乎？', '', '', '', NULL, '弟木山：予尝悟作园亭与作光棍二法，园亭之善，在多回廊，光棍之恶，在能结讼。', 'indent', 1556185530, '5cc11138d5de2b007360d5d1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642184, '幽梦影 · 卷三 · 其十', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '清宵独坐，邀月言愁；良夜孤眠，呼蛩语恨。', '', '', '', NULL, '黄孔植：此逆旅无聊之况，心斋亦知之乎？', 'indent', 1556185555, '5cc1115117b54d006835971e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642185, '幽梦影 · 卷三 · 十一', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '官声采于舆论，豪右之口与寒乞之口，俱不得其真；花案定于成心，艳媚之评与寝陋之评，概恐失其实。', '', '', '', NULL, '黄九烟：先师有言：「不如乡人之善者好之，其不善者恶之。」
李若金：豪右而不讲分上，寒乞而不望推恩者，亦未尝无公论。', 'indent', 1556185574, '5cc11164a91c930068222525', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642186, '幽梦影 · 卷三 · 十二', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '胸藏邱壑，城市不异山林；兴寄烟霞，阎浮有如蓬岛。', '', '阎浮：即阎浮提，亦即吾人所住的世界。', '', NULL, '', 'indent', 1556185590, '5cc111740237d70068fc8d1a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642187, '幽梦影 · 卷三 · 十三', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '梧桐为植物中清品，而形家独忌之，甚且谓「梧桐大如斗，主人往外走。」若竟视为不祥之物也者。夫剪桐封弟，其为宫中之桐可知。而卜世最久者，莫过于周。俗言之不足据，类如此夫！', '', '翦桐封弟：「周成王剪桐封弟」故事，在《吕氏春秋．重言》、《说苑．君道》和《史记．晋世家》中都有记载。', '', NULL, '倪永清：心斋为梧桐雪千古之奇冤，百卉俱当九顿。', 'indent', 1556185604, '5cc11182f884af00678a0cff', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642188, '幽梦影 · 卷三 · 十四', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '多情者，不以生死易心；好饮者，不以寒暑改量；喜读书者，不以忙闲作辍。', '', '', '', NULL, '', 'indent', 1556185620, '5cc11192a91c930068222738', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642189, '幽梦影 · 卷三 · 十五', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '蛛为蝶之敌国，驴为马之附庸。', '', '', '', NULL, '周星远：妙论解颐，不数晋人危语隐语。', 'indent', 1556185636, '5cc111a217b54d0068359b40', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642190, '幽梦影 · 卷三 · 十六', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '立品，须发乎宋人之道学；涉世，须参以晋代之风流。', '', '', '', NULL, '胡静夫：予赠金陵前辈赵客庵句云：「文章鼎立庄骚外，杖履风流晋宋间。」今当移赠山来。
陆云士：有不风流之道学，有风流之道学，有不道学之风流，有道学之风流，毫厘千里。', 'indent', 1556185652, '5cc111b217b54d0068359c2e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642191, '幽梦影 · 卷三 · 十七', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '古谓禽兽亦知人伦。予谓匪独禽兽也，即草木亦复有之。牡丹为王，芍药为相，其君臣也；南山之乔，北山之梓，其父子也；荆之闻分而枯，闻不分而活，其兄弟也；莲之并蒂，其夫妇也；兰之同心，其朋友也。', '', '匪：通“非”。', '', NULL, '', 'indent', 1556185670, '5cc111c417b54d0068359cb3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642192, '幽梦影 · 卷三 · 十八', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '豪杰易于圣贤，文人多于才子。', '', '', '', NULL, '', 'indent', 1556185685, '5cc111d3d5de2b007360ddd0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642196, '幽梦影 · 卷三 · 二十二', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '孔子生于东鲁，东者生方。故礼乐文章，其道皆自无而有。释迦生于西方，西者死地。故受想行识，其教皆自有而无。', '', '', '', NULL, '殷日戒曰：孔子止勉人生时用功，佛氏只教人死后作主，各自一意。', 'indent', 1556185756, '5cc1121a0237d70068fc966d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642197, '幽梦影 · 卷三 · 二十三', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '有青山方有绿水，水惟借色于山；有美酒便有佳诗，诗亦乞灵于酒。', '', '', '', NULL, '', 'indent', 1556185771, '5cc11229d5de2b007360e2bd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642198, '幽梦影 · 卷三 · 二十四', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '严君平，以卜讲学者也；孙思邈，以医讲学者也；诸葛武侯，以出师讲学者也。', '', '严君平：公元前86年～公元10年，西汉道家学者，思想家。', '', NULL, '', 'indent', 1556185792, '5cc1123da91c930068223042', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642199, '幽梦影 · 卷三 · 二十五', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '人则女美于男，禽则雄华于雌，兽则牝牡无分者也。', '', '', '', NULL, '徐松之曰：此是茶村兴到之言，亦非定论。', 'indent', 1556185811, '5cc1125017b54d006835a54e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642200, '幽梦影 · 卷三 · 二十六', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '镜不幸而遇嫫母，砚不幸而遇俗子，剑不幸而遇庸将，皆无可奈何之事。', '', '', '', NULL, '曹冲谷曰：最无可奈何者，佳人定随痴汉。', 'indent', 1556185827, '5cc1126117b54d006835a67a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642201, '幽梦影 · 卷三 · 二十七', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '天下无书则已，有则必当读；无酒则已，有则必当饮；无名山则已，有则必当游；无花月则已，有则必当赏玩；无才子佳人则已，有则必当爱慕怜惜。', '', '', '', NULL, '', 'indent', 1556185842, '5cc112700237d70068fc9adb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642202, '幽梦影 · 卷三 · 二十八', NULL, 3, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '秋虫春鸟，尚能调声弄舌，时吐好音。我辈搦管拈毫，岂可甘作鸦鸣牛喘？', '', '', '', NULL, '', 'indent', 1556185861, '5cc11283d5de2b007360e716', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642203, '幽梦影 · 卷三 · 二十九', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '媸颜陋质，不与镜为仇者，亦以镜为无知之死物耳。使镜而有知，必遭扑破矣。', '', '', '', NULL, '江含征曰：镜而有知，遇若辈早已回避矣。
张竹坡曰：　镜而有知，必当化媸为妍。', 'indent', 1556185876, '5cc1129217b54d006835a8c9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642204, '幽梦影 · 卷三 · 三十', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '吾家公艺，恃百忍以同居，千古传为美谈。殊不知忍而至于百，则其家庭乖戾睽隔之处，正未易更仆数也。', '', '', '', NULL, '倪永清曰：若用忍字，则百犹嫌少，否则以剑字处之足矣。或曰出家二字足以处之。', 'indent', 1556185890, '5cc112a00237d70068fc9d4d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642205, '幽梦影 · 卷三 · 三十一', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '九世同居，诚为盛事，然止当与割股庐墓者，作一例看，可以为难矣，不可以为法也，以其非中庸之道也。', '', '', '', NULL, '', 'indent', 1556185910, '5cc112b4d5de2b007360e982', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642206, '幽梦影 · 卷三 · 三十二', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '作文之法：意之曲折者，宜写之以显浅之词；理之显浅者，宜运之以曲折之笔；题之熟者，参之以新奇之想；题之庸者，深之以关系之论。至于窘者舒之使长，缛者删之使简，俚者文之使雅，闹者摄之使静，皆所谓裁制也。', '', '', '', NULL, '陈康畴曰：深得作文三昧语。', 'indent', 1556185928, '5cc112c617b54d006835ab46', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642207, '幽梦影 · 卷三 · 三十三', NULL, 3, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '笋为蔬中尤物，荔枝为果中尤物，蟹为水族中尤物，酒为饮食中尤物，月为天文中尤物，西湖为山水中尤物，词曲为文字中尤物。', '', '', '', NULL, '', 'indent', 1556185943, '5cc112d417b54d006835ac28', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642208, '幽梦影 · 卷三 · 三十四', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '买得一本好花，犹且爱护而怜惜之，矧其为解语花乎！', '', '矧（shěn）：况且。', '', NULL, '', 'indent', 1556185965, '5cc112eb17b54d006835ad3f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642209, '幽梦影 · 卷三 · 三十五', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '观手中便面，足以知其人之雅俗，足以识其人之交游。', '', '便面：古代扇子。', '', NULL, '', 'indent', 1556185985, '5cc112fe17b54d006835ae22', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642210, '行京口至竹里', NULL, 1, 185, 2, 0, '鲍照', NULL, 10386, '57e7c50d67f35600579b3511', '南北朝', 'shi', '诗', 'baike.baidu.com/item/行京口至竹里/11032471', '', '高柯危且竦，锋石横复仄。
复涧隐松声，重崖伏云色。
冰闭寒方壮，风动鸟倾翼。
斯志逢凋严，孤游值曛逼。
兼途无憩鞍，半菽不遑食。
君子树令名，细人效命力。
不见长河水，清浊俱不息。', '《行京口至竹里》是南朝宋诗人鲍照创作的一首五言古诗。这首诗可以分三个部分。前六句为第一部分，写途中所见，描绘出一个不安宁的、充满冲突的、为某一种强大的力量所压迫、钳制着的世界。中间四句为第二部分，写气候的恶劣和行路的艰难，暗寓人生多艰、仕宦不顺。最后四句为第三部分，抒发怀才不遇的感慨，表现寒士被压抑的痛苦和不平。这首诗语言蕴藉含蓄，修辞奇特，耐人寻味。', '竹里：山名，在今江苏句容市境内，山势陡峭，又名翻车岘。
锋石：尖利的山石。
复涧（jiàn）：夹于两山之间的涧流。
伏：掩盖。
云色：云气所生成的色彩。
冰闭：冰冻闭合，覆盖。
凋严：指严冬。
曛（xūn）：黄昏，傍晚。
兼途：犹兼程，以加倍速度赶路。
憩（qì）：休息，歇息。
半菽（shū）：指杂以蔬菜的食物，语出《汉书·项籍传》：“卒食半菽”。菽，豆类的总称。
令名：美名。
细人：小人。
命力：被人役使而致力。', '高高的树枝，挺拔地耸立着，直刺蓝天，犬牙般的岩石，有的横阻当道，有的斜向两边。
层层深涧中，隐隐传来阵阵松涛，重重悬崖上，浓厚的云朵凝聚着，连绵一片。
到处都是坚冰，正是最寒冷的时候，北风劲吹，把飞鸟的翅膀也吹得倾斜。
意气落寞的寒士，偏碰上这肃杀的严冬，孤独无依的行旅，又正值黄昏落日时刻。
一路风雪兼程，无法解鞍休息，也没有时间吃点一半蔬莱一半豆类帕粗粮，只好忍饥挨饿。
地位高贵的人想要建功立业，获得美好的名声，地位低微的人定要拼死效力，日夜奔波。
请看那长河的水流吧，总是滚滚向前不停息，不论清澈还是浑浊。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccb6dbb8b379ee0a0e50", "shortContent": "此诗的写作年代，钱仲联先生增补《鲍参军集注》，以为当在宋文帝元嘉十七年（440）初冬，时临川王刘义庆由江州移镇南兖州（治所广陵，在今扬州市西北），鲍照作为刘义庆的国侍郎，与之同行。京口，今江苏镇江市，是从都城建康（今南京市）去广陵的必经之地。“行京口”犹言往京口。竹里，即竹里山，在江苏句容市境内，山势陡峭，又名“翻车岘”。\n鲍照是一个性格和人生欲望都非常强烈的人，追求富贵荣华、及时享乐、建功立业，...", "authors": ["骆玉明"], "pressName": "上海辞书出版社"}]', '中国作家协会会员殷光熹《文学散论》：“最后四句诗揭示了这样一个道理：看问题不能仅着眼于表面现象，而不深入到具体事物的内部，因为同一表面现象，可以反映不同的质。同是流淌着的水，就有清、浊之分，同是奔波劳累的人，又有君子、小人之别。”', 'center', 1556186004, '5cc11311d5de2b007360ee4b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642211, '幽梦影 · 卷三 · 三十六', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '水为至污之所会归，火为至污之所不到，若变不洁为至洁，则水火皆然。', '', '', '', NULL, '', 'indent', 1556186018, '5cc11320f884af00678a26c8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642212, '幽梦影 · 卷三 · 三十七', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '貌有丑而可观者，有虽不丑而不足观者；文有不通而可爱者，有虽通而极可厌者。此未易与浅人道也。', '', '', '', NULL, '', 'indent', 1556186032, '5cc1132e17b54d006835b0eb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642213, '幽梦影 · 卷三 · 三十八', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '游玩山水亦复有缘，苟机缘未至，则虽近在数十里之内，亦无暇到也。', '', '', '', NULL, '', 'indent', 1556186053, '5cc11344f884af00678a286b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642215, '幽梦影 · 卷三 · 四十', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '昔人欲以十年读书，十年游山，十年检藏。予谓检藏尽可不必十年，只二、三载足矣，若读书与游山，虽或相倍蓰，恐亦不足以偿所愿也，必也如黄九烟前辈之所云：「人生必三百岁而后可乎！」', '', '', '', NULL, '江含征曰：昔贤原谓：尽则安能？但身到处莫放过耳！', 'indent', 1556186083, '5cc1136117b54d006835b37a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642216, '幽梦影 · 卷三 · 四十一', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '宁为小人之所骂，毋为君子之所鄙；宁为盲主司之所摈弃，毋为诸名宿之所不知。', '', '', '', NULL, '陈康畴曰：世之人自今以后，慎毋骂心斋也。', 'indent', 1556186096, '5cc1136f17b54d006835b3e8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642217, '幽梦影 · 卷三 · 四十二', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '傲骨不可无，傲心不可有；无傲骨则近于鄙夫，有傲心不得为君子。', '', '', '', NULL, '石天外曰：道学之言，才人之笔。', 'indent', 1556186110, '5cc1137c17b54d006835b49f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642218, '幽梦影 · 卷三 · 四十三', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '蝉为虫中之夷齐，蜂为虫中之管晏。', '', '', '', NULL, '吴镜秋曰：蚊是虫中之酷吏，蝇是虫中之游客。', 'indent', 1556186123, '5cc1138af884af00678a2c3e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642219, '幽梦影 · 卷三 · 四十四', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '曰「痴」、曰「愚」、曰「拙」、曰「狂」，皆非好字面，而人每乐居之；曰「奸」、曰「黠」、曰「强」、曰「佞」反是，而人每不乐居之。何也？', '', '', '', NULL, '', 'indent', 1556186136, '5cc1139717b54d006835b66e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642220, '幽梦影 · 卷三 · 四十五', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '唐虞之际，音乐可感鸟兽，此盖唐虞之鸟兽，故可感耳。若后世之鸟兽，恐未必然。', '', '', '', NULL, '', 'indent', 1556186150, '5cc113a417b54d006835b6ee', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642221, '幽梦影 · 卷三 · 四十六', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '痛可忍，而痒不可忍；苦可耐，而酸不可耐。', '', '', '', NULL, '释牧堂曰：若知痛痒，辨苦酸，便是居士悟处。', 'indent', 1556186165, '5cc113b3f884af00678a2e2c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642222, '幽梦影 · 卷三 · 四十七', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '镜中之影，着色人物也；月下之影，写意人物也；镜中之影，钩边画也；月下之影，没骨画也；月中山河之影，天文中地理也；水中星月之象，地理中天文也。', '', '', '', NULL, '', 'indent', 1556186185, '5cc113c6d5de2b007360f866', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642223, '幽梦影 · 卷三 · 四十八', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '能读无字之书，方可得惊人妙句；能会难通之解，方可参最上禅机。', '', '', '', NULL, '', 'indent', 1556186207, '5cc113de0237d70068fcae58', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642224, '幽梦影 · 卷三 · 四十九', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '若无诗酒，则山水为具文；若无佳丽，则花月皆虚设。', '', '', '', NULL, '', 'indent', 1556186221, '5cc113ecf884af00678a311e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642225, '幽梦影 · 卷三 · 五十', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '才子而美姿容，佳人而工著作，断不能永年者。匪独为造物之所忌，盖此种原不独为一时之宝，乃古今万世之宝，故不欲久留人世，以取亵耳。', '', '', '', NULL, '', 'indent', 1556186261, '5cc11413f884af00678a336a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642226, '幽梦影 · 卷三 · 五十一', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '陈平封「曲逆侯」，《史》、《汉》注皆云：「音去遇。」予谓此是北人土音耳。若南人四音俱全，似仍当读作本音为是。', '', '曲逆侯：北水于唱曲之曲，亦读如去字；「曲逆」──古地名，在今河北顺平县东。', '', NULL, '', 'indent', 1556186279, '5cc1142417b54d006835be59', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642227, '幽梦影 · 卷三 · 五十二', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '古人四声俱备，如「六」「国」二字，皆入声也。今梨园演《苏秦剧》，必读「六」为溜，读「国」为鬼，从无读入声者。然考之《诗经》，如「良马六之」，「无衣六兮」之类，皆不与去声协，而协祝、告、燠。「国」字皆不与上声协，而协入、陌、质韵。则是古人似亦有入声，未必尽读「六」为溜，读「国」为鬼也。', '', '协：此则之协，原文为左口右十口十，协的古字。', '', NULL, '', 'indent', 1556186294, '5cc11434d5de2b007360fddc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642228, '幽梦影 · 卷三 · 五十三', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '闲人之砚，固欲其佳，而忙人之砚，尤不可不佳；娱情之妾，固欲其美，而广嗣之妾，亦不可不美。', '', '', '', NULL, '江含征曰：砚美下墨可也，妾美招妒奈何！张竹坡曰：妒在妾不在美。', 'indent', 1556186308, '5cc11442d5de2b007360fea5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642229, '幽梦影 · 卷三 · 五十四', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '如何是独乐乐？曰鼓琴；如何是与人乐乐？曰弈棋；如何是与众乐乐？曰马吊。', '', '马吊：古代博戏，始于明代中叶。因合四十叶纸牌而成，故又称「叶子戏」。', '', NULL, '', 'indent', 1556186329, '5cc11457a91c930068224e26', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642230, '幽梦影 · 卷三 · 五十五', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '不待教而为善为恶者，胎生也；必待教而后为善为恶者，卵生也；偶因一事之感触，而突然为善为恶者，湿生也；前后判若两截，究非一日之故者，化生也。', '', '湿生：如周处、戴渊之改过，李怀光反叛之类。
化生：如唐玄宗、卫武公之类。', '', NULL, '', 'indent', 1556186347, '5cc1146ad5de2b0073610120', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642231, '幽梦影 · 卷三 · 五十六', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '凡物皆以形用，其以神用者，则镜也，符印也，日晷也，指南针也。', '', '', '', NULL, '', 'indent', 1556186363, '5cc114790237d70068fcb622', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642232, '幽梦影 · 卷三 · 五十七', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '才子遇才子，每有怜才之心；美人遇美人，必无惜美之意。我愿来世托生为绝代佳人，一反其局而后快。', '', '', '', NULL, '郑蕃修曰：俟心斋来世为佳人时再议。
倪永清曰：再来时，不可忘却。', 'indent', 1556186380, '5cc1148ad5de2b0073610308', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642233, '幽梦影 · 卷三 · 五十八', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '予尝欲建一无遮大会，一祭历代才子，一祭历代佳人。俟遇有真正高僧，即当为之。', '', '', '', NULL, '顾天石曰：君若果有此盛举，请迟至二三十年之后，则我亦可拜领盛情也。', 'indent', 1556186396, '5cc1149af884af00678a39bd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642234, '幽梦影 · 卷三 · 五十九', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '圣贤者，天地之替身。', '', '', '', NULL, '', 'indent', 1556186415, '5cc114ad17b54d006835c66d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642235, '幽梦影 · 卷三 · 六十', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '天极不难做，只须生仁人、君子、有才德者，二、三十人足矣。君一、相一、冢宰一，及诸路总制抚军是也。', '', '', '', NULL, '黄九烟曰：吴歌有云：「做天切莫做四月天。」可见天亦有难做之时。
倪永清曰：天若都生善人，君相皆当袖手，便可无为而治。', 'indent', 1556186439, '5cc114c417b54d006835c82f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642236, '幽梦影 · 卷三 · 六十一', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '掷升官图，所重在德，所忌在赃。何一登仕版，辄与之相反耶？', '', '', '', NULL, '', 'indent', 1556186457, '5cc114d717b54d006835c957', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642237, '幽梦影 · 卷三 · 六十二', NULL, 4, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '动物中有三教焉：蛟龙麟凤之属，近于儒者也；猿狐鹤鹿之属，近于仙者也；狮子牯牛之属，近于释者也。植物中有三教焉：竹梧兰蕙之属，近于儒者也；蟠桃老桂之属，近于仙者也；莲花薝卜之属，近于释者也。', '', '薝卜：栀子花。唐卢纶《送静居法师》诗：「薝卜名花飘不断，醍醐法味洒何浓。」', '', NULL, '石天外曰：众人碌碌，动物中蜉蝣而已；世人峥嵘，植物中荆棘而已。', 'indent', 1556186471, '5cc114e50237d70068fcbbc9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642238, '幽梦影 · 卷三 · 六十三', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '佛氏云：「日月在须弥山腰。」果尔，则日月必是绕山横行而后可，苟有升有降，必为山巅所碍矣。又云：「地上有阿耨达池，其水四出，流入诸印度。」又云：「地轮之下为水轮，水轮之下为风轮，风轮之下为空轮。」余谓此皆喻言人身也，须弥山喻人首，日月喻两目，池水四出喻血脉流动，地轮喻此身，水为便溺，风为泄气，此下则无物矣。', '', '', '', NULL, '释远峰曰：却被此公道破。', 'indent', 1556186485, '5cc114f30237d70068fcbdc5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642239, '幽梦影 · 卷三 · 六十四', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '苏东坡和陶诗，尚遗数十首，予尝欲集坡句以补之，苦于韵之弗备而止。如责子诗中：「不识六与七，但觅梨与栗。」「七」字、「栗」字，皆无其韵也。', '', '', '', NULL, '', 'indent', 1556186504, '5cc11506d5de2b0073610b6d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642240, '幽梦影 · 卷三 · 六十五', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '予尝偶得句，亦殊可喜，惜无佳对，遂未成诗。其一为「枯叶带虫飞」，其一为「乡月大于城」，姑存之，以俟异日。', '', '', '', NULL, '', 'indent', 1556274157, '5cc26b6643e78c9ba4167bf0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642241, '幽梦影 · 卷三 · 六十六', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '「空山无人，水流花开」二句，极琴心之妙境；「胜固欣然，败亦可喜」二句，极手谈之妙境；「帆随湘转，望衡九面」二句，极泛舟之妙境；「胡然而天，胡然而帝」二句，极美人之妙境。', '', '「胡然而天，胡然而帝」二句：语出《诗经．庸风．君子偕老》：「胡然而天也！胡然而帝也！」，形容服饰容貌像天神一样美丽。', '', NULL, '', 'indent', 1556274181, '5cc26b8417b54d006949ae06', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642242, '幽梦影 · 卷三 · 六十七', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '镜与水之影，所受者也；日与灯之影，所施者也。月之有影，则在天者为受，而在地者为施也。', '', '', '', NULL, '', 'indent', 1556274201, '5cc26b9617b54d00695b201b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642243, '幽梦影 · 卷三 · 六十八', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '水之为声，有四：有瀑布声，有流泉声，有滩声，有沟浍声。风之为声，有三：有松涛声，有秋叶声，有波浪声。雨之为声，有二：有梧叶荷叶上声，有承檐溜竹筩中声。', '', '浍（kuài）：细小的水流。
筩（tǒng）：竹筩即竹筒。', '', NULL, '', 'indent', 1556274218, '5cc26ba817b54d00695b214b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642244, '幽梦影 · 卷三 · 六十九', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '文人每好鄙薄富人，然于诗文之佳者，又往往以金玉、珠玑、锦绣誉之，则又何也？', '', '', '', NULL, '江含征曰：富人嫌其悭且俗耳，非嫌其珠玉文绣也。
张竹坡曰：不文虽富可鄙，能文虽穷可敬。', 'indent', 1556274238, '5cc26bbd43e78c9ba4168116', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642245, '幽梦影 · 卷三 · 七十', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '能闲世人之所忙者，方能忙世人之所闲。', '', '', '', NULL, '', 'indent', 1556274254, '5cc26bcc43e78c9ba4168229', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642246, '幽梦影 · 卷三 · 七十一', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '先读经，后读史，则论事不谬于圣贤；既读史，复读经，则观书不徒为章句。', '', '', '', NULL, '王宓草曰：妄论轻史者，还宜退而读经。', 'indent', 1556274269, '5cc26bdb7b968a00738583b2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642247, '幽梦影 · 卷三 · 七十二', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '居城市中，当以画幅当山水，以盆景当苑囿，以书籍当朋友。', '', '', '', NULL, '', 'indent', 1556274285, '5cc26beb17b54d00695b24e9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642248, '幽梦影 · 卷三 · 七十三', NULL, 3, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '乡居须得良朋始佳。若田夫樵子，仅能辨五谷而测晴雨，久且数，未免生厌矣。而友之中，又当以能诗为第一，能谈次之，能画次之，能歌又次之，解觞政者又次之。', '', '', '', NULL, '', 'indent', 1556274308, '5cc26c01a91c93006cd8d2c4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642249, '幽梦影 · 卷三 · 七十四', NULL, 3, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '玉兰，花中之伯夷也；葵，花中之伊尹也；莲，花中之柳下惠也。鹤，鸟中之伯夷也；鸡，鸟中之伊尹也；莺，鸟中之柳下惠也。', '', '花中之伯夷：喻高而且洁。
花中之伊尹：即倾心向日。
花中之柳下惠：污泥不染。
鸟中之伯夷：仙品。
鸟中之伊尹：司晨。
鸟中之柳下惠：求友。', '', NULL, '', 'indent', 1556274323, '5cc26c117b968a0073858686', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642250, '幽梦影 · 卷三 · 七十五', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '无其罪而虚受恶名者，蠹鱼也；有其罪而恒逃清议者，蜘蛛也。', '', '无其罪而虚受恶名者，蠹鱼也：蛀书之虫，另是一种；其形如蚕蛹而差小。', '', NULL, '张竹坡曰：自是老吏断狱。', 'indent', 1556274337, '5cc26c1fa91c93006cd8d4a8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642251, '幽梦影 · 卷三 · 七十六', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '臭腐化为神奇，酱也、腐乳也、金汁也；至神奇化为臭腐，则是物皆然。', '', '', '', NULL, '', 'indent', 1556274357, '5cc26c33a91c93006cd8d5c7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642252, '幽梦影 · 卷三 · 七十七', NULL, 1, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '黑与白交，黑能污白，白不能掩黑；香与臭混，臭能胜香，香不能敌臭；此君子小人相攻之大势也。', '', '', '', NULL, '弟木山曰：人必喜白恶黑，黜臭而取香，此又君子必胜小人之理也，理在又乌论乎势。', 'indent', 1556274375, '5cc26c44a91c93006cd8d6eb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642253, '幽梦影 · 卷三 · 七十八', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '「耻」之一字，所以治君子；「痛」之一字，所以治小人。', '', '', '', NULL, '', 'indent', 1556274391, '5cc26c5617b54d006949bb43', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642255, '幽梦影 · 卷三 · 八十', NULL, 2, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '古人云：「诗必穷而后工。」盖穷则与多感慨，易于见长耳。若富贵中人，既不可忧贫叹贱，所谈者不过风云月露而已，诗安得佳？苟思所变，计惟有出游一法。即以所见之山川风土物产人情，或当疮痍兵燹之余，或值旱潦灾祲之后，无一不可寓之诗中。借他人之穷愁，以供我之咏叹，则诗亦不必待穷而后工也。', '', '祲（jìn）：阴阳之气相侵而形成的象征不祥的妖气。', '', NULL, '', 'indent', 1556274425, '5cc26c7743e78c9ba4168bdd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642256, '幽梦影 · 跋 · 一', NULL, 0, 226, 0, 1, '张潮', NULL, 36815, '58b45cf68ac2475ccb5e4f10', '清', 'wen', '文', '', '', '抱异疾者多奇梦，梦所未到之境，梦所未见之事，以心为君主之官邪干之故如此，此则病也，非梦也。至若梦木橕天，梦河无水，则休咎应之；梦牛尾梦蕉鹿，则得失应之。此则梦也，非病也。心斋之《幽梦影》，非病也，非梦也，影也。影者维何？石火之一敲，电光之一瞥也。东坡所谓一掉头时生老病，一弹指顷去来今也。昔人云芥子纳须弥，而心斋则于倏忽备古今也。此因其心闲手闲，故弄墨如此之闲适也。心斋盖长于勘梦者也，然而未可向痴人说也。
寓东淘香雪斋江之兰草。', '', '', '', NULL, '', 'indent', 1556274449, '5cc26c8ea91c93006cd8dc24', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642258, '幽梦影 · 跋 · 二', NULL, 0, 2, 0, 1, '葛元煦', NULL, 37059, '5dd0147d7d577441a5c31041', '清', 'wen', '文', '', '', '余习闻《幽梦影》一书，着墨不多，措词极隽，每以未获一读为恨事。客秋南沙顾耐圃茂才示以钞本，展玩之馀，爱不释手。所惜尚有残阙，不无余憾。今从同里袁翔甫大令处见有刘君式亭所赠原刊之本，一无遗漏，且有同学诸君评语 ，尤足令人寻绎。间有未评数条 ，经大令一一补之 ，功媲娲皇，允称全璧。爰乞重付手民，冀可流传久远。大令欣然曰 ：「诺。」故略其巅末云。
光绪五年岁次已卯冬十月仁和葛元煦理斋氏识。', '', '', '', NULL, '', 'indent', 1556274484, '5cc26cb217b54d006949c095', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642334, '宋书 · 卷二十一 · 志第十一 · 乐三', NULL, 3, 376, 1, 1, '沈约', NULL, 35895, '5858fce161ff4b0068768127', '南北朝', 'wen', '文', '', '', '《但歌》四曲，出自汉世。无弦节，作伎，最先一人倡，三人和。魏武帝尤好之。时有宋容华者，清彻好声，善唱此曲，当时特妙。自晋以来，不复传，遂绝。《相和》，汉旧歌也。丝竹更相和，执节者歌。本一部，魏明帝分为二，更递夜宿。本十七曲，朱生、宋识、列和等复合之为十三曲。
《相和》《驾六龙》、《气出倡》，武帝词：
驾六龙乘风而行，行四海外。路下之八邦，历登高山，临溪谷，乘云而行，行四海外，东到泰山。仙人玉女，下来翱游，骖驾六龙，饮玉浆，河水尽，不东流。解愁腹，饮玉浆。奉持行，东到蓬莱山。上至天之门。玉阙下，引见得入，赤松相对，四面顾望，视正焜煌。开王心正兴，其气百道至，传告无穷。闭其口，但当爱气，寿万年。东到海，与天连。神仙之道，出窈入冥。常当专之，心恬憺无所愒欲，闭门坐自守，天与期气。愿得神之人，乘驾云车，骖驾白鹿，上到天之门，来赐神之药。跪受之，敬神齐。当如此，道自来。
华阴山，自以为大，高百丈，浮云为之盖。仙人欲来，出随风，列之雨。吹我洞箫鼓瑟琴，何壒壒，酒与歌戏。今日相乐诚为乐，玉女起，起舞移数时。鼓吹一何嘈嘈，从西北来时，仙道多驾烟，乘云驾龙，郁何蓩々。遨游八极，乃到昆仑之山，西王母侧。神仙金止玉亭，来者为谁。赤松王乔，乃德旋之门。乐共饮食到黄昏，多驾合坐，万岁长宜子孙。
游君山，甚为真，磪磈砟硌，尔自为神。乃到王母台，金阶玉为堂，芝草生殿旁。东西厢，客满堂。主人当行觞，坐者长寿遽何央。长乐甫始宜孙子，常愿主人增年，与天相守。
《厥初生》、《精列》，武帝词：
厥初生，造化之陶物，莫不有终期。莫不有终期，圣贤不能免，何为怀此忧。愿螭龙之驾，思想昆仑居。思想昆仑居，见期于迂怪，志意在蓬莱。志意在蓬莱，周孔圣徂落，会稽以坟丘。会稽以坟丘，陶陶谁能度，君子以弗忧。年之暮，奈何，过时时来微。
《江南可采莲》、《江南》，古祠：
江南可采莲，莲叶何田田。鱼戏莲叶间，鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北。《天地间》、《度关山》，武帝词：
天地间，人为贵。立君牧民，为之轨则。车辙马迹，经纬四极。绌陟幽明，黎庶繁息。于铄贤圣，总统邦域，封建五爵，井田刑狱。有燔丹书，无普赦赎。皋陶《甫刑》，何有失职。嗟哉后世，改制易律。劳民为君，役赋其力。舜漆食器，畔者十国。不及唐尧，采椽不斫。世叹伯夷，欲以厉俗。侈恶之大，俭为恭德。许由推让，岂有讼曲。兼爱尚同，疏者为戚。
《东光乎》、《东光乎》，古词：
东光乎。仓梧何不乎。仓梧多腐粟，无益诸军粮。诸军游荡子，蚤行多悲伤。《登山有远望》、《十五》，文帝词：
登山而远望，溪谷多所有。楩柟千余尺，众草之盛茂。华叶耀人目。五色难可纪。雉雊山鸡鸣，虎啸谷风起。号罴当我道，狂顾动牙齿。《惟汉二十二世》、《薤露》，武帝词：
惟汉二十二世，所任诚不良。沐猴而冠带，智小而谋强。犹豫不敢断，因狩执君王。白虹为贯日，己亦先受殃。贼臣持国柄，杀主灭宇京。荡覆帝基业，宗庙以燔丧。播越西迁移，号泣而且行。瞻彼洛城郭，微子为哀伤。
《关东有义士》、《蒿里行》，武帝词：
关东有义士，兴兵讨群凶。初期会孟津，乃心在咸阳。军合力不齐，踌躇而雁行。势利使人争，嗣还自相戕。淮南弟称号，刻玺于北方。铠甲生虮虱，万姓以死亡。白骨露于野，千里无鸡鸣。生民百遗一，念之绝人肠。
《对酒歌太平时》、《对酒》，武帝词：
对酒歌，太平时，吏不呼门。王者贤且明，宰相股肱皆忠良，咸礼让，民无所争讼。三年耕有九年储，仓谷满盈，斑白不负戴。雨泽如此，五谷用成。却走马以粪其土田。爵公侯伯子男，咸爱其民，以黜陟幽明，子养有若父与兄。犯礼法，轻重随其刑。路无拾遗之私，囹圄空虚，冬节不断人。耄耋皆得以寿终，恩德广及草木昆虫。
《鸡鸣高树颠》、《鸡鸣》，古词：
鸡鸣高树颠，狗吠深宫中。荡子何所之，天下方太平。刑法非有贷，柔协正乱名。黄金为君门，璧玉为轩堂。上有双尊酒，作使邯郸倡。刘玉碧青甓，后出郭门王。舍后有方池，池中双鸳鸯。鸳鸯七十二，罗列自成行。鸣声何啾啾，闻我殿东厢。兄弟四五人，皆为侍中郎。五日一时来，观者满道傍。黄金络马头，颎颎何煌煌。桃生露井上，李树生桃傍，虫来啮桃根，李树代桃僵。树木身相代，兄弟还相忘。
《乌生八九子》、《乌生》，古词：
乌生八九子，端坐秦氏桂树间。唶我秦氏，家有游遨荡子，工用睢阳强苏合弹。左手持强弹，两丸出入乌东西。唶我一丸即发中乌身，乌死魂魄飞扬上天。阿母生乌子时，乃在南山岩石间。唶我人民安知乌子处，蹊径窈窕安从通。白鹿乃在上林西苑中，射工尚复得白鹿脯哺。唶我黄鹄摩天极高飞，后宫尚复得烹煮之。鲤鱼乃在洛水深渊中，钓钩尚得鲤鱼口。唶我人民生各各有寿命，死生何须复道前后。
《平陵东》、《平陵》，古词：
平陵东，松柏桐，不知何人劫义公。劫义公在高堂下，交钱百万两走马。两走马，亦诚难，顾见追吏心中恻。心中恻，血出漉，归告我家卖黄犊。《弃故乡》〔亦在瑟调《东西门行》〕《陌上桑》，文帝词：
弃故乡，离室宅，远从军旅万里客。披荆棘，求阡陌，侧足独窘步，路局笮。虎豹嗥动，鸡惊，禽失群，鸣相索。登南山，奈何蹈盘石，树木丛生郁差错。寝蒿草，荫松柏，涕泣雨面沾枕席。伴旅单，稍稍日零落，惆怅窃自怜，相痛惜。
《今有人》、《陌上桑》，《楚词》钞：
今有人，山之阿，被服薜荔带女萝。既含睇，又宜笑，子恋慕予善窈窕。乘赤豹，从文狸，辛夷车驾结桂旗。被石兰，带杜衡，折芳拔荃遗所思。处幽室，终不见，天路险艰独后来。表独立，山之上，云何容容而在下。杳冥冥，羌昼晦，东风飘濆神灵雨。风瑟瑟，木搜搜，思念公子徒以忧。
《驾虹霓》、《陌上桑》，武帝词：
驾虹霓，乘赤云，登彼九疑历玉门。济天汉，至昆仑，见西王母，谒东君。交赤松，及羡门，受要秘道爱精神。食芝英，饮醴泉，柱杖桂枝佩秋兰。绝人事，游浑元，若疾风游欻飘飘。景未移，行数千，寿如南山不忘愆。
清商三调歌诗，荀勖撰，旧词施用者，平调。《周西》、《短歌行》，武帝词〔六解〕：
周西伯昌，怀此圣德，参分天下，而有其二。修奉贡献，臣节不坠。崇侯谗之，是以拘系。〔一解〕后见赦原，赐之斧钺，得使征伐。为仲尼所称，达及德行，犹奉事殷，论叙其美。〔二解〕齐桓之功，为霸之首，九合诸侯，一匡天下。一匡天下，不以兵车。正而不谲，其德传称。〔三解〕孔子所叹，并称夷吾，民受其恩。赐与庙胙，命无下拜。小白不敢尔，天威在颜咫尺。〔四解〕晋文亦霸，躬奉天王。受赐珪瓒、秬鬯雕弓、卢弓、矢千，虎贲三百人。〔五解〕威服诸侯，师之者尊，八方闻之，名亚齐桓。河阳之会，诈称周王，是以其名纷葩。〔六解〕
《秋风》、《燕歌行》，文帝词〔七解〕：
秋风萧瑟天气凉，草木摇落露为霜。〔一解〕群燕辞归鹄南翔，念君客游多思肠。〔二解〕慊慊思归恋故乡，君何淹留寄它方。〔三解〕贱妾茕茕守空房，忧来思君不敢忘。〔四解〕不觉泪下沾衣裳，援瑟鸣弦发清商。〔五解〕短歌微吟不能长，明月皎皎照我床。〔六解〕星汉西流夜未央，牵年织女遥相望，尔独何辜限河梁。〔七解〕
《仰瞻》、《短歌行》，文帝词〔六解〕：
仰瞻帷幕，俯察几筵。其物如故，其人不存。〔一解〕神灵倏忽，弃我遐迁。靡瞻靡恃，泣涕连连。〔二解〕呦呦游鹿，衔草鸣麑。翩翩飞鸟，挟子巢栖。〔三解〕我独孤茕，怀此百离。忧心孔疚，莫我能知。〔四解〕人亦有言，忧令人老。嗟我白发，生一何早。〔五解〕长吟永叹，怀我圣考。曰仁者寿，胡不是保。〔六解〕
《别日》、《燕歌行》，文帝词〔六解〕：
别日何易会日难，山川悠远路漫漫。〔一解〕郁陶思君未敢言，寄书浮云往不还。〔二解〕涕零雨面毁形颜，谁能怀忧独不叹。〔三解〕耿耿伏枕不能眠，披衣出户步东西。〔四解〕展诗清歌聊自宽，乐往哀来摧心肝。悲风清厉秋气寒，罗帷徐动经秦轩。〔五解〕仰戴星月观云间，飞鸟晨鸣，声气可怜，留连顾怀不自存。〔六解〕
《对酒》、《短歌行》，武帝词〔六解〕：
对酒当歌，人生几何。譬如朝露，去日苦多。〔一解〕慨当以慷，忧思难忘。以何解愁，唯有“杜康”。〔二解〕青青子衿，悠悠我心。但为君故，沉吟至今。〔三解〕明明如月，何时可掇。忧从中来，不可断绝。〔四解〕呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。〔五解〕山不厌高，水不厌深。周公吐哺，天下归心。〔六解〕
清调《晨上》、《秋胡行》，武帝词：
晨上散关山，此道当何难。晨上散关山，此道当何难。牛顿不起，车堕谷间。坐盘石之上，弹五弦之琴，作为清角韵，意中述烦。歌以言志，晨上散关山。〔一解〕有何三老公，卒来在我傍。有何三老公，卒来在我傍。员掩被裘，似非恒人。谓卿云何，困苦以自怨，徨徨所欲，来到此间。歌以言志，有何三老公。〔二解〕我居昆仑山，所谓者真人。我居昆仑山，所谓者真人。道深有可得。名山历观，遨游八极。枕石漱流饮泉。沉吟不决，遂上升天。歌以言志，我居昆仑山。〔三解〕去去不可追，长恨相牵攀。去去不可追，长恨相牵攀。夜夜安得寐，惆怅以自怜。正而不谲，辞赋依因。经传所过，西来所传。歌以言志，去去不可追。〔四解〕又本：晨上散关山，此道当何难。有何三老公，卒来在我傍。我居我昆仑山，所谓真人，去不可追，长相牵攀。
《北上》、《苦寒行》，武帝词〔六解〕：
北上太‖行‖山‖，艰‖哉‖何‖巍‖巍‖。羊肠坂诘屈，车轮为之摧。〔一解〕树木何萧‖瑟‖，北‖风‖声‖正‖悲‖。熊罴对我蹲，虎豹夹道啼。〔二解〕溪谷少‖人‖民‖，雪‖落‖何‖霏‖霏‖。延颈长叹息，远行多所怀。〔三解〕我心何‖佛‖郁‖，思‖欲‖一‖东‖归‖。水深桥梁绝，中道正裴回。〔四解〕迷惑失‖径‖路‖，暝‖无‖所‖宿‖栖‖。行行日以远，人马同时饥。〔五解〕担‖囊‖行‖取‖薪‖，斧‖冰‖持‖作‖糜‖。悲彼东山诗，悠悠使我哀。〔六解〕
《愿登》、《秋胡行》，武帝词〔五解〕：
愿‖登‖泰‖华‖山‖，神‖人‖共‖远‖游‖。经历昆仑山，到蓬莱。飘濆八极，与神人俱。思得神药，万岁为期。歌以言志，愿登泰华山。〔一解〕天‖地‖何‖长‖久‖，人‖道‖居‖之‖短‖。世言伯阳，殊不知老，赤松王乔，亦云得道。得之未闻，庶以寿考。歌以言志，天地何长久。〔二解〕明‖明‖日‖月‖光‖，何‖所‖不‖光‖昭‖。二仪合圣化，贵者独人不。万国率土，莫非王臣。仁义为名，礼乐为荣。歌以言志，明明日月光。〔三解〕四‖时‖更‖逝‖去‖，昼‖夜‖以‖成‖岁‖。大人先天，而天弗违。不戚年往，世忧不治。存亡有命，虑之为蚩。歌以言志，四时更逝去。〔四解〕戚‖戚‖欲‖何‖念‖，欢‖笑‖意‖所‖之‖。盛壮智惠，殊不再来。爱时进趣，将以惠谁。泛泛放逸，亦同何为。歌以言志，戚戚欲何念。〔五解〕
《上谒》、《董桃行》，古词〔五解〕：
吾欲上谒从高山，山头危崄大难。遥望五岳端，黄金为阙，班璘。但见芝草，叶落纷纷。〔一解〕百鸟集，来如烟。山兽纷纶，麟辟邪其端。鹍鸡声鸣，但见山兽援戏相拘攀。〔二解〕小复前行玉堂，未心怀流还。传教出门来，门外人何求。所言欲从圣道，求一得命延。〔三解〕教敕凡吏受言，采取神药若木端。白兔长跪捣药虾蟆丸，奉上陛下一玉盘，服此药可得即仙。〔四解〕服尔神药，无不欢喜。陛下长生老寿，四面肃肃稽首，天神拥护左右，陛下长与天相保守。〔五解〕
《蒲生》、《塘上行》，武帝词〔五解〕：
蒲‖生‖我‖池‖中‖，其叶何离离。傍能行仪仪，莫能缕自知。众口铄黄金，使君生别离。〔一解〕念‖君‖去‖我‖时‖，独愁常苦悲。想见君颜色，感结伤心脾。今悉夜夜愁不寐。〔二解〕莫‖用‖豪‖贤‖故‖，弃捐素所爱。莫用鱼肉贵，弃捐葱与薤。莫用麻枲贱，弃捐菅与蒯。〔三解〕倍‖恩‖者‖苦‖栝‖，蹶船常苦没。教君安息定，慎莫致仓卒。念与君一共离别，亦当何时共坐复相对。〔四解〕出‖亦‖复‖苦‖愁‖，入亦复苦愁。边地多悲风，树木何萧萧。今日乐相乐，延年寿千秋。〔五解〕
《悠悠》、《苦寒行》，明帝词〔五解〕：
悠‖悠‖发‖洛‖都‖，{艹幵}‖我‖征‖东‖行‖。征行弥二旬，屯吹龙陂城。〔一解〕顾观故‖垒‖处‖，皇‖祖‖之‖所‖营‖。屋室若平昔，栋宇无邪倾。〔二解〕奈何‖我‖皇‖祖‖，潜‖德‖隐‖圣‖形‖。虽没而不朽，书贵垂休名。〔三解〕光光我‖皇‖祖‖，轩‖耀‖同‖其‖荣‖。遗化布四海，八表以肃清。〔四解〕虽有吴‖蜀‖寇‖，春‖秋‖足‖耀‖兵。徒悲我皇祖，不永享百龄。赋诗以写怀，伏轼泪沾缨。〔五解〕
瑟调《朝日》、《善哉行》，文帝词。〔五解〕：
朝日乐相乐，酣饮不知醉。悲弦激新声，长笛吐清气。〔一解〕弦歌感人肠，四坐皆欢说。寥寥高堂上，凉风入我室。〔二解〕持满如不盈，有得者能卒。君子多苦心，所愁不但一。〔三解〕慊慊下白屋，吐握不可失。众宾饱满归，主人苦不悉。〔四解〕比翼翔云汉，罗者安所羁。冲静得自然，荣华何足为。〔五解〕
《上山》、《善哉行》，文帝词〔六解〕：
上山采薇，薄莫苦饥。溪谷多风，霜露沾衣。〔一解〕野雉群雊，猿猴相追。还望故乡，郁何垒垒，〔二解〕高山有崖，林木有支。忧来无方，人莫之知。〔三解〕人生若寄，多忧何为。今我不乐，岁月其驰。〔四解〕汤汤川流，中有行舟。随波转薄，有似客游。〔五解〕策我良马，被我轻裘。载驰载驱，聊以忘忧。〔六解〕
《朝游》、《善哉行》，文帝词〔五解〕：
朝游高台观，夕宴华池阴。大酋奉甘醪，狩人献嘉禽。〔一解〕齐倡发东舞，秦筝奏西音。有客从南来，为我弹清琴。〔二解〕五音纷繁会，拊者激微吟。淫鱼乘波听，踊跃自浮沉。〔三解〕飞鸟翻翔舞，悲鸣集北林。乐极哀情来，憀亮摧肝心。〔四解〕清角岂不妙，德薄所不任。大哉子野言，弭弦且自禁。〔五解〕
《古公》、《善哉行》，武帝词〔七解〕：
古公亶甫，积德垂仁。思弘一道，哲王于幽。〔一解〕太伯仲雍，王德之仁。行施百世，断发文身。〔二解〕伯夷叔齐，古之遗贤。让国不用，饿殂首山。〔三解〕智哉山甫，相彼宣王。何用杜伯，累我圣贤。〔四解〕齐桓之霸，赖得仲父。后任竖刁，虫流出户。〔五解〕晏子平仲，积德兼仁。与世沈德，未必思命。〔六解〕仲尼之世，王国为君。随制饮酒，扬波使官。〔七解〕
《自惜》、《善哉行》，武帝词〔六解〕：
自惜身薄祜，夙贱罹孤苦。既无三徙教，不闻过庭语。〔一解〕其穷如抽裂，自以思所怙。虽怀一介志，是时其能与。〔二解〕守穷者贫贱，惋叹泪如雨。泣涕于悲夫，乞活安能睹。〔三解〕我愿于天穷，琅邪倾侧左。虽欲竭忠诚，欣公归其楚。〔四解〕快人曰为叹，抱情不得叙。显行天教人，谁知莫不绪。〔五解〕我愿何时随，此叹亦难处。今我将何照于光耀，释衔不如雨。〔六解〕
《我徂》、《善哉行》，明帝词〔八解〕：
我徂我征，伐彼蛮虏。练师简卒，爰正其旅。〔一解〕轻舟竟川，初鸿依浦。桓桓猛毅，如罴如虎。〔二解〕发炮若雷，吐气成雨。旄旍指麾，进退应矩。〔三解〕百马齐辔，御由造父。休休六军，咸同斯武。〔四解〕兼涂星迈，亮兹行阻。行行日远，西背京许。〔五解〕游弗淹旬，遂届扬土。奔寇震惧，莫敢当御。〔六解〕虎臣列将，怫郁充怒。淮泗肃清，奋扬微所。〔七解〕运德耀威，惟镇惟抚。反旆言归，告入皇祖。〔八解〕
《赫赫》、《善哉行》，明帝词〔四解〕：
赫赫大魏，王师徂征。冒暑讨乱，振耀威灵。〔一解〕泛舟黄河，随波潺湲。通渠回越，行路绵绵。〔二解〕采旄蔽日，旗旒翳天。淫鱼瀺灂，游戏深渊。〔三解〕唯塘泊，从如流。不为单，握扬楚。心惆怅，歌《采薇》。心绵绵，在淮肥。愿君速捷蚤旋归。〔四解〕
《来日》、《善哉行》，古词〔六解〕：
来日大难，口燥唇干。今日相乐，皆当喜欢。〔一解〕经历名山，芝草翻翻。仙人王乔，奉药一丸。〔二解〕自惜袖短，内手知寒。惭无灵辄，以报赵宣。〔三解〕月没参横，北斗阑干。亲交在门，饥不及餐。〔四解〕欢日尚少，戚日苦多。以何忘忧，弹筝酒歌。〔五解〕淮南八公，要道不烦。参驾六龙，游戏云端。〔六解〕
大曲《东门》、《东门行》，古词〔四解〕：
出东门，不愿归。来入门，怅欲悲。盎中无斗储，还视桁上无县衣。〔一解〕拔剑出门去，儿女牵衣啼。它家但愿富贵，贱妾与君共餔糜。〔二解〕共铺糜，上用仓浪天故，下为黄口小儿。今时清廉，难犯教言，君复自爱莫为非。〔三解〕今时清廉，难犯教言，君复自爱莫为非。行。吾去为迟，平慎行，望吾归。〔四解〕
《西山》、《折杨柳行》，文帝词〔四解〕：
西山一何高，高高殊无极。上有两仙僮，不饮亦不食。与我一丸药，光耀有五色。〔一解〕服药四五日，身体生羽翼。轻举乘浮云，倏忽行万亿。流览观四海，芒芒非所识。〔二解〕彭祖称七百，悠悠安可原。老聃适西戎，于今竟不还。王乔假虚词，赤松垂空言。〔三解〕达人识真伪，愚夫好妄传。追念往古事，愦愦千万端。百家多迂怪，圣道我所观。〔四解〕
《罗敷》、《艳歌罗敷行》，古词〔三解〕：
日出东南隅，照我秦氏楼。秦氏有好女，自名为罗敷。罗敷喜蚕桑，采桑城南隅。青丝为笼系，桂枝为笼钩。头上倭堕发，耳中明月珠。缃绮为下群，紫绮为上襦。行者见罗敷，下担捋髭须。少年见罗敷，脱帽著帩头。耕者忘其犁，锄者忘其锄。来归相怒怨，但坐观罗敷。〔一解〕使君从南来，五马立歭躇。使君遣吏往，问是谁家姝。秦氏有好女，自名为罗敷。罗敷年几何。二十尚不足，十五颇有余。使君谢罗敷，宁可共载不。罗敷前置词，使君一何愚。使君自有妇，罗敷自有夫。〔二解〕东方千余骑，夫婿居上头。何用识夫婿。白马从骊驹。青丝系马尾，黄金络马头。腰中鹿卢剑，可直千万余。十五府小史，二十朝大夫，三十侍中郎，四十专城居。为人洁白晳，鬑鬑颇有须。盈盈公府步，冉冉府中趋。坐中数千人，皆言夫婿殊。〔三解〕〔前有艳词曲，后有趋。〕
《西门》、《西门行》，古词〔六解〕：
出西门，步念之。今日不作乐，当待何时。〔一解〕夫为乐，为乐当及时。何能坐愁怫郁，当复来兹。〔二解〕饮醇酒，炙肥牛。请呼心所欢，可用解愁忧。〔三解〕人生不满百，常怀千岁忧。昼短而夜长，何不秉烛游。〔四解〕自‖非‖仙‖人‖王‖子‖乔‖，计‖会‖寿‖命‖难‖‖与‖期‖。〔五解〕人寿非金石，年命安可期。贪财爱惜费，但为后世嗤。〔六解〕。〔一本“烛游”后“行去之，如云除，弊车羸马为自推”，无“自非”以下四十八字。〕
《默默》、《折杨柳行》，古词〔四解〕：
默默施行违，厥罚随事来，末喜杀龙逢，桀放于鸣条。〔一解〕祖伊言不用，纣头县白旄。指鹿用为马，胡亥以丧躯。〔二解〕夫差临命绝，乃云负子胥。戎王纳女乐，以亡其由余。璧马祸及虢，二国俱为墟。〔三解〕三夫成市虎，慈母投杼趋。卞和之刖足，接予归草庐。〔四解〕
《园桃》、《煌煌京洛行》，文帝词〔五解〕：
夭夭园桃，无子空长。虚美难假，偏轮不行。〔一解〕淮阴五刑，鸟得弓藏。保身全名，独有子房。大愤不收，褒衣无带。多言寡诚，只令事败。〔二解〕苏秦之说，六国以亡。倾侧卖主，车裂固当。贤矣陈轸，忠而有谋，楚怀不从，祸卒不救。〔三解〕祸夫吴起，智小谋大，西河何健，伏尸何劣。〔四解〕嗟彼郭生，古之雅人，智矣燕昭，可谓得臣。峨峨仲连，齐之高士。北辞千金，东蹈沧海。〔五解〕
《白鹄》、《艳歌何尝》〔一曰《飞鹄行》〕，古词〔四解〕：
飞来双白鹄，乃从西北来。十十五五，罗列成行。〔一解〕妻卒被病，行不能相随。五里一反顾，六里一裴回。〔二解〕吾欲衔汝去，口噤不能开。吾欲负汝去，毛羽何摧颓。〔三解〕乐哉新相知，忧来生别离。躇踌顾群侣，泪下不自知。〔四解〕念与君离别，气结不能言。各各重自爱，道远归还难。妾当守空房，闭门下重关。若生当相见，亡者会黄泉。今日乐相乐，延年万岁期。〔“念与”下为趋曲，前有艳。〕
《碣石》、《步出夏门行》，武帝词〔四解〕：
云行雨步，超越九江之皋，临观异同。心意怀游豫，不知当复何从。经过至我碣石，心惆怅我东海。〔《云行》至此为艳。〕东临碣石，以观沧海。水何淡淡，山岛竦峙。树木丛生，百草丰茂。秋风萧瑟，洪涛涌起。日月之行，若出其中。星汉粲烂，若出其里。幸甚至哉。歌以咏志。〔《观沧海》，一解。〕
孟冬十月，北风裴回。天气肃清，繁霜霏霏。鹍鸡晨鸣，鸿雁南飞，鸷鸟潜藏，熊罴窟栖。钱袴停置，农收积场。逆旅整设，以通贾商。幸甚至哉。歌以咏志。〔《冬十月》，二解。〕
乡土不同，河朔隆寒。流澌浮漂，舟船行难。锥不入地，蘴裛深奥。水竭不流，冰坚可蹈。士隐者贫，勇侠轻非。心常叹怨，戚戚多悲。幸甚至哉。歌以咏志。〔《河朔寒》，三解。〕
神龟虽寿，犹有竟时。腾蛇乘雾，终为土灰。骥老伏枥，志在千里。烈士暮年，壮心不已。盈缩之期，不但在天。养怡之福，可得永年。幸甚至哉。歌以咏志。〔《神龟虽寿》，四解。〕
《何尝》、《艳歌何尝行》，古词〔五解〕：
何尝快独无忧。但当饮醇酒，炙肥牛。〔一解〕长兄为二千石，中兄被貂裘。〔二解〕小弟虽无官爵，鞍马反反，往来王侯长者游。〔三解〕但当在王侯殿上，快独摴蒲六博，对坐弹棋。〔四解〕男儿居世，各当努力。蹙迫日暮，殊不久留。〔五解〕少小相触抵，寒苦常相随，忿恚安足诤，吾中道与卿共别离。约身奉事君，礼节不可亏。上惭沧浪之天，下顾黄口小儿。奈何复老心皇皇，独悲谁能知。〔“少小”下为趋曲，前为艳。〕
《置酒》、《野田黄雀行》，〔《空侯引》亦用此曲。〕东阿王词〔四解〕：
置酒高殿上，亲交从我游。中厨办丰膳，烹羊宰肥牛。秦筝何慷慨，齐瑟和且柔。〔一解〕阳阿奏奇舞，京洛出名讴。乐饮过三爵，缓带倾庶羞，主称千金寿，宾奉万年酧。〔二解〕久要不可忘，薄终义所尤。谦谦君子德，磬折欲何求。盛时不再来，百年忽我遒。〔三解〕惊风飘白日，光景驰西流。生存华屋处，零落归山丘。先民谁不死，知命复何忧。〔四解〕
《为乐》、《满歌行》，古词：〔四解〕：
为乐未几时，遭世险巇，逢此百离。伶丁荼毒，愁懑难支。遥望辰极，天晓月移。忧来阗心，谁当我知。〔一解〕戚戚多思虑，耿耿不宁。祸福无形，唯念古人，逊位躬耕。遂我所愿，以兹自宁。自鄙山栖，守此一荣。〔二解〕莫秋冽风起。西蹈沧海，心不能安。揽衣起瞻夜，北斗阑干。星汉照我，去去自无它。奉事二亲，劳心可言。〔三解〕穷达天所为，智者不愁，多为少忧。安贫乐正道，师彼庄周。遗名者贵，子熙同巇。往者二贤，名垂千秋。〔四解〕饮酒歌舞，不乐何须。善哉照观日月，日月驰驱。轗轲世间，何有何无。贪财惜费，此一何愚。命如凿石见火，居世竟能几时。但当欢乐自娱，尽心极所熙怡。安善养君德性，百年保此期颐。〔“饮酒”下为趋。〕
《夏门》、《步出夏门行》，〔一曰《陇西行》〕明帝词〔二解〕：
步出夏门，东登首阳山。嗟哉夷叔，仲尼称贤。君子退让，小人争先。惟斯二子，于今称传。林钟受谢，节改时迁。日月不居，谁得久存。善哉殊复善，弦歌乐情。〔一解〕商风夕起，悲彼秋蝉，变形易色，随风东西。乃眷西顾，云雾相连，丹霞蔽日，采虹带天。弱水潺潺，落叶翩翩，孤禽失群，悲鸣其间。善哉殊复善，悲鸣在其间。〔二解〕朝游清泠，日莫嗟归。〔“朝游”上为艳。〕蹙迫日莫，乌鹊南飞。绕树三匝，何枝可依。卒逢风雨，树折枝摧。雄来惊雌，雌独愁栖。夜失群侣，悲鸣裴回。芃芃荆棘，葛生绵绵。感彼风人，惆怅自怜。月盈则冲，华不再繁。古来之说，嗟哉一言。〔“蹙迫”下为趋。〕
《王者布大化》、《棹歌行》，明帝词〔五解〕：
王者布大化，配乾稽后祗。阳育则阴杀，晷景应度移。〔一解〕文德以时振，武功伐不随。重华舞干戚，有苗服从妫。〔二解〕蠢尔吴蜀虏，冯江栖山阻。哀哀王士民，瞻仰靡依怙。〔三解〕皇上悼愍斯，宿昔奋天怒。发我许昌宫，列舟于长浦。〔四解〕翌日乘波扬，棹歌悲且凉。大常拂白日，旗帜纷设张。〔五解〕将抗旄与钺，耀威于彼方。伐罪以吊民，清我东南疆。〔“将抗”下为趋。〕
《洛阳行》、《雁门太守行》，古词〔八解〕：
孝和帝在时，洛阳令王君，本自益州广汉民，少行宦，学通五经论。〔一解〕明知法令，历世衣冠。从温补洛阳令，治行致贤，拥护百姓，子养万民。〔二解〕外行猛政，内怀慈仁。文武备具，料民富贫，移恶子姓名，五篇著里端。〔三解〕，伤杀人，比伍同罪对门。禁镏矛八尺，捕轻薄少年，加笞决罪，诣马市论。〔四解〕无妄发赋，念在理冤，敕吏正狱，不得苛烦。财用钱三十，买绳礼竿。〔五解〕贤哉贤哉。我县王君。臣吏衣冠，奉事皇帝。功曹主簿，皆得其人。〔六解〕临部居职，不敢行恩。清身苦体，夙夜劳勤。治有能名，远近所闻。〔七解〕天年不遂，蚤就奄昏。为君作祠，安阳亭西。欲令后世，莫不称传。〔八解〕
《白头吟》、与《棹歌》同调，古词〔五解〕：
晴如山上云，皎若云间月。闻君有两意，故来相决绝。〔一解〕平生共城中，何尝斗酒会。今日斗酒会，明旦沟水头。蹀趶御沟上，沟水东西流。〔二解〕郭东亦有樵，郭西亦有樵。两樵相推与，无亲为谁骄。〔三解〕凄凄重凄凄，嫁娶亦不啼。愿得一心人，白头不相离。〔四解〕竹竿何袅袅，鱼尾何离簁，男儿欲相知，何用钱刀为。<齿立>如五马啖萁，川上高士嬉。今日相对乐，延年万岁期。〔五解〕〔一本云：词曰上有“紫罗咄咄奈何”。〕
楚调怨诗《明月》，东阿王词〔七解〕：
明月照高楼，流光正裴回。上有愁思妇，悲叹有余哀。〔一解〕借问叹者谁。自云客子妻。夫行逾十载，贱妾常独栖。〔二解〕念君过于渴，思君剧于饥。君为高山柏，妾为浊水泥。〔三解〕北风行萧萧，烈烈入吾耳。心中念故人，泪堕不能止。〔四解〕沉浮各异路，会合当何谐。愿作东北风，吹我入君怀。〔五解〕君怀常不开，贱妾当何依。恩情中道绝，流止任东西。〔六解〕我欲竟此曲，此曲悲且长。今日乐相乐，别后莫相忘。〔七解〕', '', '', '', NULL, '', 'indent', 1557152112, '5ccfd0ec7b968a0072d68c05', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642335, '宋书 · 卷二十二 · 志第十二 · 乐四', NULL, 2, 376, 1, 1, '沈约', NULL, 35895, '5858fce161ff4b0068768127', '南北朝', 'wen', '文', '', '', '汉《鼙舞歌》五篇：《关东有贤女》、《章和二年中》、《乐久长》、《四方皇》、《殿前生桂树》。
魏《鼙舞歌》五篇：《明明魏皇帝》、《太和有圣帝》、《魏历长》、《天生烝民》、《为君既不易》。魏陈思王《鼙舞歌》五篇：
《圣皇篇》，当《章和二年中》：圣皇应历数，正康帝道休。九州咸宾服，威德洞八幽。三公奏诸公，不得久淹留。蕃位任至重，旧章咸率由。侍臣省文奏，陛下体仁慈。沉吟有爱恋，不忍听可之。迫有官典宪，不得顾恩私。诸王当就国，玺绶何累缞。便时舍外殿，宫省寂无人。主上增顾念，皇母怀苦辛。何以为赠赐，倾府竭宝珍。文钱百亿万，采帛若烟云。乘舆服御物，锦罗与金银。龙旗垂九旒，羽盖参斑轮。诸王自计念，无功荷厚德。思一效筋力，糜躯以报国。鸿胪拥节卫，副使随经营。贵戚并出送，夹道交辎軿。车服齐整设，鞾晔耀天精。武骑卫前后，鼓吹箫笳声。祖道魏东门，泪下沾冠缨。扳盖因内顾，俯仰慕同生。行行将日莫，何时还阙庭。车轮为裴回，四马踌躇鸣。路人尚酸鼻，何况骨肉情。
《灵芝篇》，当《殿前生桂树》：灵芝生玉地，朱草被洛滨。荣华相晃耀，光采晔若神。古时有虞舜，父母顽且嚚。尽孝于田陇，烝烝不违仁。伯瑜年七十，采衣以娱亲，慈母笞不痛，歔欷涕沾巾。丁兰少失母，自伤蚤孤茕，刻木当严亲，朝夕致三牲。暴子见陵侮，犯罪以亡形，丈人为泣血，免戾全其名。董永遭家贫，父老财无遗。举假以供养，佣作致甘肥。责家填门至，不知何用归。天灵感至德，神女为秉机。岁月不安居，乌乎我皇考。生我既已晚，弃我何期蚤。《蓼莪》谁所兴，念之令人老。退咏《南风》诗，洒泪满袆抱。乱曰：圣皇君四海，德教朝夕宣。万国咸礼让，百姓家肃虔。庠序不失仪，孝悌处中田。户有曾闵子，比屋皆仁贤。髫龀无夭齿，黄发尽其年。陛下三万岁，慈母亦复然。
《大魏篇》，当《汉吉昌》：大魏应灵符，天禄方甫始。圣德致泰和，神明为驱使。左右宜供养，中殿宜皇子。陛下长寿考，群臣拜贺咸说喜。积善有余庆，荣禄固天常。众善填门至，臣子蒙福祥。无患及阳遂，辅翼我圣皇。众吉咸集会，凶邪奸恶并灭亡。黄鹄游殿前，神鼎周四阿。玉马充乘舆，芝盖树九华。白虎戏西除，舍利从辟邪。骐驎蹑足舞，凤凰拊翼歌。丰年大置酒，玉尊列广庭。乐饮过三爵，朱颜暴己形。式宴不违礼，君臣歌《鹿鸣》。乐人舞鼙鼓，百官雷抃赞若惊。储礼如江海，积善若陵山。皇嗣繁且炽，孙子列曾玄。群臣咸称万岁，陛下长乐寿年。御酒停未饮，贵戚跪东厢。侍人承颜色，奉进金玉觞。此酒亦真酒，福禄当圣皇。陛下临轩笑，左右咸欢康。杯来一何迟，群僚以次行。赏赐累千亿，百官并富昌。
《精微篇》，当《关东有贤女》：精微烂金石，至心动神明。杞妻哭死夫，梁山为之倾。子丹西质秦，乌白马角生。邹羡囚燕市，繁霜为夏零。关东有贤女，自字苏来卿。壮年报父仇，身没垂功名。女休逢赦书，白刃几在颈。俱上列仙籍，去死独就生。太仓令有罪，远征当就拘。自悲居无男，祸至无与俱。缇萦痛父言，何担西上书。盘桓北阙下，泣泪何涟如。乞得并姊弟，没身赎父躯。汉文感其义，肉刑法用除。其父得以免，辨义在列图。多男亦何为，一女足成居。简子南渡河，津吏废舟船。执法将加刑，女娟拥棹前。“妾父闻君来，将涉不测渊。畏惧风波起，祷祝祭名川。备礼飨神祇，为君求福先。不胜釂祀诚，至令犯罚艰。君必欲加诛，乞使知罪愆。妾愿以身代”，至诚感苍天。国君高其义，其父用赦原。河激奏中流，简子知其贤。归娉为夫人，荣宠超后先。辩女解父命，何况健少年。黄初发和气，明堂德教施。治道致太平，礼乐风俗移。刑错民无枉，怨女复何为。圣皇长寿考，景福常来仪。
《孟冬篇》，当《狡兔》：孟冬十月，阴气厉清。武官诫田，讲旅统兵。元龟袭吉，元光著明。蚩尤跸路，风弭雨停。乘舆启行，鸾鸣幽轧。虎贲采骑，飞象珥鹖。钟鼓铿锵，箫管嘈喝。万骑齐镳，千乘等盖。夷山填谷，平林涤薮。张罗万里，尽其飞走。翟翟狡兔，扬白跳翰。猎以青骹，掩以修竿。韩卢宋鹊，呈才骋足。噬不尽厓，牵麋掎鹿。魏氏发机，养基抚弦。都卢寻高，搜索猴猨。庆忌孟贲，蹈谷超峦。张目决眦，发怒穿冠。顿熊扼虎，蹴豹搏貙。气有余势，负象而趋。获车既盈，日侧乐终。罢役解徒，大飨离宫。乱曰：圣皇临飞轩，论功校猎徒。死禽积如京，流血成沟渠。明诏大劳赐，大官供有无。走马行酒醴，驱车布肉鱼。鸣鼓举觞爵，钟击位无余。绝网纵麟麑，弛罩出凤雏。收功在羽校，威灵振鬼区。陛下长欢乐，永世合天符。
《晋鼙舞歌》五篇：
《洪业篇》、《鼙舞歌》，当魏曲《明明魏皇帝》，古曲《关东有贤女》：宣文创洪业，盛德在太始。圣皇应灵符，受命君四海。万国何所乐，上有明天子。唐尧禅帝位，虞舜惟恭己。恭己正南面，道化与时移。大赦荡萌渐，文教被黄支。象天则地，体无为。聪明配日月，神圣参两仪。虽有三凶类，静言无所施。象天则地，体无为。稷契并佐命，伊吕升王臣。兰芷登朝肆，下无失宿民。声发响自应，表立景来附。虓虎从羁制，潜龙升天路。备物立成器，变通极其数。百事以时叙，万机有常度。训之以克让，纳之以忠恕。群下仰清风，海外同欢慕。象天则地，化云布。昔日贵雕饰，今尚俭与素。昔日多纤介，今去情与故。象天则地，化云布。济济大朝士，夙夜综万机。万机无废理，明明降畴咨。臣譬列星景，君配朝日晖。事业并通济，功烈何巍巍。五帝继三皇，三王世所归。圣德应期运，天地不能违。仰之弥已高，犹天不可阶。将复御龙氏，凤皇在庭栖。
《天命篇》、《鼙舞歌》，当魏曲《太和有圣帝》，古曲《章和二年中》：圣祖受天命，应期辅魏皇。入则综万机，出则征四方。朝廷无遗理，方表宁且康。道隆舜臣尧，积德逾太王。孟度阻穷险，造乱天一隅。神兵出不意，奉命致天诛。赦善戮有罪，元恶宗为虚。威风震劲蜀，武烈慑强吴。诸葛不知命，肆逆乱天常。拥徒十余万，数来寇边疆。我皇迈神武，秉钺镇雍凉。亮乃畏天威，未战先仆僵。盈虚自然运，时变固多难。东征陵海表，万里枭贼渊。受遗齐七政，曹爽又滔天。群凶受诛殛，百禄咸来臻。黄华应福始，王凌为祸先。
《景皇帝》、《鼙舞歌》，当魏曲《魏历长》，古曲《乐久长》：景皇帝，聪明命世生，盛德参天地。帝王道，创基既已难，继世亦未易。外则夏侯玄，内则张与李，三凶称逆，乱帝纪。从天行诛，穷其奸宄。遏将御其渐，潜谋不得起。罪人咸伏辜，威风震万里。平衡综万机，万机无不理。召陵桓不君，内外何纷纷，众小便成群。蒙昧恣心，治乱不分。睿圣独断，济武常以文。从天惟废立，扫霓披浮云。云霓既已辟，清和未几间。羽檄首尾至，变起东南蕃。俭钦为长蛇，外则冯吴蛮。万国纷骚扰，戚戚天下惧不安。神武御六军，我皇秉钺征。俭钦起寿春，前锋据项城。出其不意，并纵奇兵。奇兵诚难御，庙胜实难支。两军不期遇，敌退计无施。虎骑惟武进，大战沙阳陂。钦乃亡魂走，奔虏若云披。天恩赦有罪，东土放鲸鲵。
《大晋篇》、《鼙舞歌》，当魏曲《天生烝民》，古曲《四方皇》：赫赫大晋，于穆文皇。荡荡巍巍，道迈陶唐。世称三皇五帝，及今重其光。九德克明，文既显，武又章。恩弘六合，兼济万方。内举元凯，朝政以纲。外简虎臣，时惟鹰扬。靡从不怀，逆命斯亡。仁配春日，威逾秋霜。济济多士，同兹兰芳。唐虞至治，四凶滔天。致讨俭钦，罔不肃虔。化感海外，海外来宾。献其声乐，并称妾臣。西蜀猾夏，僭号方域。命将致讨，委国稽服。吴人放命，冯海阻江。飞书告谕，响应来同。先王建万国，九服为蕃卫。亡秦坏诸侯，序胙不二世。历代不能复，忽逾五百岁。我皇迈圣德，应期创典制。分土五等，蕃国正封界。莘莘文武佐，千秋遘嘉会。洪业溢区内，仁风翔海外。
《明君篇》、《鼙舞歌》，当魏曲《为君既不易》，古曲《殿前生桂树》：明君御四海，听鉴尽物情。顾望有谴罚，竭忠身必荣。兰茝出荒野，万里升紫庭。茨草秽堂阶，扫截不得生。能否莫相蒙，百官正其名。恭己慎有为，有为无不成。暗君不自信，群下执异端。正直罹谮润，奸臣夺其权。虽欲尽忠诚，结舌不敢言。结舌亦何惮，尽忠为身患。清流岂不洁，飞尘浊其源。歧路令人迷，未远胜不还。忠臣立君朝，正色不顾身。邪正不并存，譬若胡与秦。秦胡有合时，邪正各异津。忠臣遇明君，乾乾惟日新。群目统在纲，众星拱北辰。设令遭暗主，斥退为凡民。虽薄供时用，白茅犹可珍。冰霜昼夜结，兰桂摧为薪。邪臣多端变，用心何委曲。便辟从情指，动随君所欲。偷安乐目前，不问清与浊。积伪罔时主，养交以持禄。言行恒相违，难餍甚溪谷。昧死射乾没，觉露则灭族。右五篇《鼙舞歌行》。
《铎舞》歌诗二篇。《圣人制礼乐篇》：
昔皇文武邪 弥弥舍善 谁吾时吾 行许帝道 衔来治路万邪 治路万邪赫赫意黄运道吾治路万邪 善道明邪金邪 善道 明邪金邪帝邪 近帝武武邪邪圣皇八音 偶邪尊来 圣皇八音 及来义邪同邪 乌及来义邪 善草供国吾 咄等邪乌 近帝邪武邪 近帝武邪武邪 应节合用 武邪尊邪 应节合用 酒期义邪同邪 酒期义邪善草供国吾 咄等邪乌 近帝邪武邪 近帝武武邪邪 下音足木 上为鼓义邪 应众义邪 乐邪邪延否 已邪乌已礼祥 咄等邪乌 素女有绝其圣乌乌武邪
《云门篇》、《铎舞歌行》，当魏《太和时》：黄《云门》，唐《咸池》，虞《韶舞》，夏殷《濩》。列代有五，振铎鸣金，近《大武》。清歌发倡，刑为主。声和八音，协律吕。身不虚动，手不徒举。应节合度，周其叙。时奏宫商，杂之以徵羽。下餍众目，上从钟鼓。乐以移风，与德礼相辅，安有失其所。
右二篇《铎舞歌行》。《拂舞》歌诗五篇：
《白鸠篇》：翩翩白鸠，再飞再鸣。怀我君德，来集君庭。白雀呈瑞，素羽明鲜。翔庭舞翼，以应仁乾。交交鸣鸠，或丹或黄。乐我君惠，振羽来翔。东壁余光，鱼在江湖。惠而不费，敬我微躯。策我良驷，习我驱驰。与君周旋，乐道亡余。我心虚静，我志沾濡。弹琴鼓瑟，聊以自娱。陵云登台，浮游太清。扳龙附凤，日望身轻。
《济济篇》：畅飞畅舞，气流芳。追念三五，大绮黄。去失有，时可行。去来同时，此未央。时冉冉，近桑榆。但当饮酒，为欢娱。衰老逝，有何期。多忧耿耿，内怀思。渊池广，鱼独希。愿得黄浦，众所依。恩感人，世无比。悲歌具舞，无极已。
《独禄篇》：独禄独禄，水深泥浊。泥浊尚可，水深杀我。雍雍双雁，游戏田畔。我欲射雁，念子孤散。翩翩浮苹，得风遥轻。我心何合，与之同并。空床低帷，谁知无人。夜衣锦绣，谁别伪真。刀呜削中，倚床无施。父冤不报，欲活何为。猛虎班班，游戏山间。虎欲啮人，不避豪贤。
《碣石篇》：东临碣石，以观沧海。水何澹澹，山岛竦峙。树木丛生，百草丰茂。秋风萧瑟，洪波涌起。日月之行，若出其中。星汉粲烂，若出其里。幸甚至哉。歌以咏志。
《观沧海》。
孟冬十月，北风裴回。天气肃清，繁霜霏霏。鹍鸡晨鸣，雁过南飞。鸷乌潜藏，熊罴窟栖。钱袴停置，农收积场。逆旅整设，以通贾商。幸甚至哉。歌以咏志。《冬十月》。
乡土不同，河朔隆寒。流澌浮漂，舟船行难。锥不入地，丰籁深奥，水竭不流，冰坚可蹈。士隐者贫，勇侠轻非。心常叹怨，戚戚多悲。幸甚至哉。歌以咏志。
《土不同》。
神龟虽寿，犹有竟时。腾蛇乘雾，终为土灰。老骥伏枥，志在千里。烈士莫年，壮心不已。盈缩之期，不但在天。养怡之福，可得永年。幸甚至哉。歌以咏志。
《龟虽寿》。
《淮南王篇》：淮南王，自言尊，百尺高楼与天连。后园凿井银作床，金瓶素绠汲寒浆。汲寒浆，饮少年。少年窈窕何能贤。扬声悲歌音绝天。我欲度河河无梁，愿化双黄鹄，还故乡。还故乡，入故里。徘徊故乡，苦身不已。繁舞寄声无不泰，徘徊桑梓游天外。
右五篇《拂舞行》。
《杯盘舞》歌诗一篇：晋世宁，四海平，普天安乐永大宁。四海安，天下欢，乐治兴隆舞杯盘。舞杯盘，何翩翩，举坐翻覆寿万年。天与日，终与一，左回右转不相失。筝笛悲，酒舞疲，心中慷慨可健儿。樽酒甘，丝竹清，愿令诸君醉复醒。醉复醒，时合同，四坐欢乐皆言工。丝竹音，可不听，亦舞此盘左右轻。自相当，合坐欢乐人命长。人命长，当结友，千秋万岁皆老寿。
右《杯盘舞歌行》。
《巾舞》歌诗一篇：吾不见公莫时吾何婴公来婴姥时吾哺声何为茂时为来婴当思吾明月之上转起吾何婴土来婴转去吾哺声何为土转南来婴当去吾城上羊下食草吾何婴下来吾食草吾哺声汝何三年针缩何来婴吾亦老吾平平门淫涕下吾何婴何来婴涕下吾哺声昔结吾马客来婴吾当行吾度四州洛四海吾何婴海何来婴海何来婴四海吾哺声熇西马头香来婴吾洛道吾治五丈度汲水吾噫邪哺谁当求儿母何意零邪钱健步哺谁当吾求儿母何吾哺声三针一发交时还弩心意何零意弩心遥来婴弩心哺声复相头巾意何零何邪相哺头巾相吾来婴头巾母何何吾复来推排意何零相哺推相来婴推非母何吾复车轮意何零子以邪相哺转轮吾来婴转母何吾使君去时意何零子以邪使君去时使来婴去时母何吾思君去时意何零子以邪思君去时思来婴吾去时母何何吾吾
右《公莫巾舞歌行》。
《白纻舞》歌诗三篇：高举两手白鹄翔。轻躯徐起何洋洋。凝停善睐容仪光。宛若龙转乍低昂。随世而变诚无方。如推若引留且行。宋世方昌乐未央。舞以尽神安可忘。爱之遗谁赠佳人。质如轻云色如银。袍以光躯巾拂尘。制以为袍余作巾。四坐欢乐胡可陈。清歌徐舞降祗神。
右一篇。
双袂齐举鸾凤翔。罗裾飘濆昭仪光。趋步生姿进流芳。鸣弦清歌及三阳。人生世间如电过。乐时每少苦日多。幸及良辰曜春花。齐倡献舞赵女歌。羲和驰景逝不停。春露未晞严霜零。百草凋索花落英。蟋蟀吟牖寒蝉鸣。百年之命忽若倾。蚤知迅速秉烛行。东造扶桑游紫庭。西至昆仑戏曾城。
右一篇。
阳春白日风花香。趋步明玉舞瑶珰。声发金石媚笙簧。罗袿徐转红袖扬。清歌流响绕凤梁。如矜若思凝且翔。转盼遗精艳辉光。将流将引双雁翔。欢来何晚意何长。明君御世永歌倡。
右一篇。《白纻》旧新合三篇。宋泰始歌舞曲词：
《皇业颂》〔歌自尧至楚元王、高祖，世世载圣德。〕明帝造：皇业沿德建，帝运资勋融。胤唐重盛轨，胄楚载休风。尧帝兆深祥，元王衍遐庆。积善传上业，祚福启英圣。衰数随金禄，登历昌水命。维宋垂光烈，世美流舞咏。
《圣祖颂》：圣祖惟高德，积勋代晋历。永建享鸿基，万古盛音册。睿文缵宸驭，广运崇帝声。衍德被仁祉，留化洽民灵。孝建缔孝业，允协天人谋。宇内齐政轨，宙表烛威流。钟管腾列圣，彝铭贲重猷。
《明君大雅》，虞龢造：明君应乾数，拨乱纽颓基。民庆来苏日，国颂《薰风》诗。天步或暂难，列蕃扇迷慝。庙胜敷九代，神谟洞七德。文教洗昏俗，武谊清昆埏。英勋冠帝则，万寿永衍天。
《通国风》，明帝造：开宝业，资贤昌，谟明盛，弼谐光。烈武惟略，景王勋。南康华容，变政文。猛绩爰著，有左军。三王到氏，文武赞。丞相作辅，属伊旦。沈柳宗侯，皆殄乱。泰始开运，超百王。司徒骠骑，勋德康。江安谋效，殷诚彰。刘沈承规，功名扬。庆归我后，祚无疆。
《天符颂》，明帝造：天符革运，世诞英皇。在馆神炫，既壮龙骧。六钟集表，四纬骈光。于穆配天，永休厥祥。
《明德颂》，明帝造：明德孚教，幽符丽纪。山鼎见奇，醴液涵祉。鹓雏耀仪，驺虞游趾。福延亿祚，庆流万祀。
《帝图颂》：帝图凝远，瑞美昭宣。济流月镜，鹿毳霜鲜。甘露降和，花雪表年。孝德载衍，芳风永传。
《龙跃大雅》：龙跃式符，玉耀蕃宫。岁淹豫野，玺属嫔中。江波澈映，石柏开文。观毓花蕊，楼凝景云。白乌三获，甘液再呈。嘉穟表沃，连理协成。德充动物，道积通神。宋业允大，灵瑞方臻。
《淮祥风》：淮祥应，贤彦生。翼赞中兴，致太平。《宋世大雅》，虞龢造：
宋世宁，在太始。醉酒欢，饱德喜。万国朝，上寿酒。帝同天，惟长久。
《治兵大雅》，明帝造：王命治兵，有征无战。巾拂以净，丑类革面。王仪振旅，载戢在辰。中虚巾拂，四表静尘。
《白纻篇大雅》，明帝造：在心曰志发言诗，声成于文被管丝。手舞足蹈欣泰时，移风易俗王化基。琴角挥韵白云舒，《箫韶》协音神凤来。拊击和节咏在初，章曲乍毕情有馀。文同轨壹道德行，国靖民和礼乐成。四县庭响美勋英，八列陛倡贵人声。舞饰丽华乐容工，罗裳皎日袂随风。金翠列辉蕙麝丰，淑姿委体允帝衷。
汉鼓吹铙歌十八曲，《朱鹭曲》：朱鹭，鱼以乌路訾邪。鹭何食，食茄下。不之食，不以吐，将以问诛〔一作谏〕者。
《思悲翁曲》：思悲翁，唐思，夺我美人侵以遇，悲翁也，但我思。蓬首〔一作蕞〕狗，逐狡兔，食交君，枭子五。枭母六，拉沓高飞莫安宿。
《艾如张曲》：艾而张罗，夷于何。行成之，四时和。山出黄雀亦有罗，雀以高飞柰雀何。为此倚欲，谁肯礞室。
《上之回曲》：上之回，所中益。夏将至，行将北。以承甘泉宫，寒暑德。游石关，望诸国，月支臣，匈奴服。令从百官疾驱驰，千秋万岁乐无极。
《翁离曲》：拥离趾中，可筑室，何用葺之蕙用兰。拥离趾中。
《战城南曲》：战城南，死郭北，野死不葬乌可食。为我谓乌“且为客豪。野死谅不葬，腐肉安能去子逃”。水深激激，蒲苇冥冥。枭骑战斗死，驽马裴回鸣。梁筑室，何以南。梁何北。禾黍不获君何食。愿为忠臣安可得。思子良臣，良臣诚可思：朝行出攻，莫不夜归。
《巫山高曲》：巫山高，高以大。淮水深，难以逝。我欲东归，害梁不为。我集无高，曳水何梁。汤汤回回，临水远望。泣下沾衣，远道之人心思归。谓之何。
《上陵曲》：上陵何美美，下津风以寒。问客从何来，言从水中央。桂树为君船，青丝为君笮，木兰为君棹，黄金错其间。沧海之雀赤翅鸿，白雁随，山林乍开乍合，曾不知日月明。醴泉之水，光泽何蔚蔚。芝为车，龙为马。览遨游，四海外。甘露初二年，芝生铜池中，仙人下来饮，延寿千万岁。
《将进酒曲》：将进酒，乘太白。辨加哉，诗审搏。放故歌，心所作。同阴气，诗悉索。使禹良工，观者苦。
《君马黄歌》：君马黄，臣马苍，三马同逐臣马良。易之有騩蔡有赭，美人归以南，驾车驰马。美人伤我心。佳人归以北，驾车驰马。佳人安终极。
《芳树曲》：芳树，日月君乱，如于风，芳树不上无心。温而鹄，三而为行。临兰池，心中怀我怅。心不可匡，目不可顾，妒人之子悲杀人。君有它心，乐不可禁。王将何似。如孙如鱼乎。悲矣。
《有所思曲》：有所思，乃在大海南。何用问遣君，双珠玳瑁簪，用玉绍缭之。闻君有它心，拉杂摧烧之。摧烧之，当风扬其灰。从今以往，勿复相思。相思与君绝。鸡鸣狗吠，兄嫂当知之。妃呼狶。秋风肃肃晨风谷，东方须臾高知之。
《雉子曲》：雉子，班如此，之于雉梁，无以吾翁孺。雉子，知得雉子高飞止，黄鹄蜚之以千里，王可思。雄来蜚从雌，视子趋一雉。雉子车大驾马滕，被王送行所中，尧芊蜚从王孙行。
《圣人出曲》：圣人出，阴阳和。美人出，游九河。佳人来，騑离哉何。驾六飞龙四时和。君之臣明护不道，美人哉，宜天子。免甘星筮乐甫始，美人子，含四海。
《上邪曲》：上邪。我欲与君相知，长命无绝衰。山无陵，江水为竭，冬雷震震夏雨雪，天地合，乃敢与君绝。
《临高台曲》：临高台以轩，下有清水清且寒。江有香草目以兰，黄鹄高飞离哉翻。关弓射鹄，令我主寿万年。收中吾。
《远如期曲》：远如期，益如寿，处天左侧，大乐，万岁与天无极。雅乐陈，佳哉纷，单于自归，动如惊心。虞心大佳，万人还来，谒者引，乡殿陈，累世未尝闻之。增寿万年亦诚哉。
《石留曲》：石留凉阳凉石水流为沙锡以微河为香向始<奚禾>冷将风阳北逝肯无敢与于杨心邪怀兰志金安薄北方开留离兰
魏鼓吹曲十二篇，缪袭造：汉第一曲《朱鹭》，今第一曲《初之平》，言魏也。
初之平，义兵征。神武奋，金鼓鸣。迈武德，扬洪名。汉室微，社稷倾。皇道失，桓与灵。阉宦炽，群雄争。边韩起，乱金城。中国扰，无纪经。赫武皇，起旗旌。麾天下，天下平。济九州，九州宁。创武功，武功成。越五帝，邈三王。兴礼乐，定纪纲。普日月，齐晖光。
右《初之平曲》凡三十句，句三字。汉第二曲《思悲翁》，今第二曲《战荥阳》，言曹公也。
战荥阳，汴水陂。戎士愤怒，贯甲驰。陈未成，退徐荣。二万骑，堑垒平。戎马伤，六军惊。势不集，众几倾。白日没，时晦冥，顾中牟，心屏营。同盟疑，计无成。赖我武皇，万国宁。
右《战荥阳》曲凡二十句，其十八句句三字，二句句四字。
汉第三曲《艾如张》，今第三曲《获吕布》，言曹公东围临淮，生擒吕布也。获吕布，戮陈宫。芟夷鲸鲵，驱骋群雄。囊括天下，运掌中。右《获吕布曲》凡六句，其三句句三字，三句句四字。
汉第四曲《上之回》，今第四曲《克官渡》，言曹公与袁绍战，破之于官渡也。
克绍官渡，由白马。僵尸流血，被原野。贼众如犬羊，王师尚寡。沙醿傍，风飞扬。转战不利，士卒伤。今日不胜，后何望。土山地道，不可当。卒胜大捷，震冀方。屠城破邑，神武遂章。
右《克官渡曲》凡十八句，其八句句三字，一句句五字，九句句四字。
汉第五曲《翁离》，今第五曲《旧邦》，言曹公胜袁绍于官渡，还谯收藏士卒死亡也。
旧邦萧条，心伤悲。孤魂翩翩，当何依。游士恋故，涕如摧。兵起事大，令愿违。博求亲戚，在者谁。立庙置后，魂来归。右《旧邦曲》凡十二句，其六句句三字，六句句四字。
汉第六曲《战城南》，今第六曲《定武功》，言曹公初破邺，武功之定，始乎此也。
定武功，济黄河。河水汤汤，旦莫有横流波。袁氏欲衰，兄弟寻干戈。决漳水，水流滂沱。嗟城中如流鱼，谁能复顾室家。计穷虑尽，求来连和。和不时，心中忧戚。贼众内溃，君臣奔北。拨邺城，奄有魏国。王业艰难，览观古今，可为长叹。
右《定武功曲》凡二十一句，其五句句三字，三句句六字，十二句句四字，一句五字。
汉第七曲《巫山高》，今第七曲《屠柳城》，言曹公越北塞，历白檀，破三郡乌桓于柳城也。
屠柳城，功诚难。越度陇塞，路漫漫。北逾冈平，但闻悲风正酸。踏顿授首，遂登白狼山。神武{埶心}海外，永无北顾患。
右《屠柳城曲》凡十句，其三句句三字，三句句四字，三句句五字，一句六字。汉第八曲《上陵》，今第八曲《平南荆》，言曹公南平荆州也。
南荆何辽辽，江汉浊不清。菁茅久不贡，王师赫南征。刘琮据襄阳，贼备屯樊城。六军庐新野，金鼓震天庭。刘子面缚至，武皇许其成。许与其成，抚其民。陶陶江汉间，普为大魏臣。大魏臣，向风思自新。思自新，齐功古人。在昔虞与唐，大魏得与均。多选忠义士，为喉唇。天下一定，万世无风尘。
右《平南荆曲》凡二十四句，其十七句句五字，四句句三字，三句句四字。
汉第九曲《将进酒》，今第九曲《平关中》，言曹公征马超，定关中也。
平关中，路向潼。济浊水，立高墉。斗韩马，离群凶。选骁骑，纵两翼，虏崩溃，级万亿。右《平关中曲》凡十句，句三字。
汉第十曲《有所思》，今第十曲《应帝期》，言曹文帝以圣德受命，应运期也。
应帝期，于昭我文皇，历数承天序，龙飞自许昌。聪明昭四表，恩德动遐方。星辰为垂耀，日月为重光。河洛吐符瑞，草木挺嘉祥。麒麟步郊野，黄龙游津梁。白虎依山林，凤凰鸣高冈。考圆定篇籍，功配上古羲皇。羲皇无遗文，仁圣相因循。运期三千岁，一生圣明君。尧授舜万国，万国皆附亲。四门为穆穆，教化常如神。大魏兴盛，与之为邻。
右《应帝期曲》凡二十六句，其一句三字，二句四字，二十二句句五字，一句六字。
汉第十一曲《芳树》，今第十一曲《邕熙》，言魏氏临其国，君臣邕穆，庶绩咸熙也。
邕熙，君臣合德，天下治。隆帝道，获瑞宝，颂声并作，洋洋浩浩。吉日临高堂，置酒列名倡。歌声一何纡余，杂笙簧。八音谐，有纪纲。子孙永建万国，寿考乐无央。
右《邕熙曲》凡十五句，其六句句三字，三句句四字，一句二字，三句句五字，二句句六字。
汉第十二曲《上邪》，今第十二曲《太和》，言魏明帝继体承统，太和改元，德泽流布。
惟太和元年，皇帝践阼，圣且仁，德泽为流布。灾蝗一时为绝息，上天时雨露。五谷溢田畴，四民相率遵轨度。事务澄清，天下狱讼察以情。元首明，魏家如此，那得不太平。
右《太和曲》凡十三句，其二句句三字，五句句五字，三句句四字，三句句七字。
晋鼓吹歌曲二十二篇，傅玄作：《灵之祥》，古《朱鹭行》。《灵之祥》，言宣皇帝之佐魏，犹虞舜之事尧也。既有石瑞之征，又能用武以诛孟度之逆命也。
灵之祥，石瑞章。旌金德，出西方。天命降，授宣皇。应期运，时龙骧。继大舜，佐陶唐。赞武文，建帝纲。孟氏叛，据南疆。追有扈，乱五常。吴寇劲，蜀虏强。交誓盟，连遐荒。宣赫怒，奋鹰扬。震乾威，耀电光。陵九天，陷石城。枭逆命，拯有生。万国安，四海宁。
《宣受命》，古《思悲翁行》。《宣受命》，言宣皇帝御诸葛亮，养威重，运神兵，亮震怖而死。
宣受命，应天机。风云时动，神龙飞。御葛亮，镇雍凉。边境安，民夷康。务节事，勤定倾。览英雄，保持盈。渊穆穆，赫明明。冲而泰，天之经。养威重，运神兵。亮乃震死，平下宁。
《征辽东》、古《艾而张行》。《征辽东》，言宣皇帝陵大海之表，讨灭公孙渊而枭其首也。
征辽东，敌失据，威灵迈日域。渊既授首，群逆破胆，咸震怖。朔北响应，海表景附。武功赫赫，德云布。
《宣辅政》，古《上之回行》：《宣辅政》，言宣皇帝圣道深远，拨乱反正，网罗文武之才，以定二仪之序也。
宣皇辅政，圣列深。拨乱反正，从天心。网罗文武才，慎厥所生。所生贤，遗教施，安上治民，化风移。肇创帝基，洪业垂。于铄明明，时赫戏。功济万世，定二仪。定二仪，云泽雨施，海外风驰。
《时运多难》，古《拥离行》：《时运》，言宣皇帝致讨吴方，有征无战也。
时运多难，道教痡。天地变化，有盈虚。蠢尔吴蛮，虎视江湖。我皇赫斯，致天诛。有征无战，弭其图。天威横被，震东隅。
《景龙飞》，古《战城南行》。《景龙飞》，言景帝克明威教，赏从夷逆，祚隆无疆，崇此洪基也。
景龙飞，御天威。聪鉴玄发，动与神明协机。从之者显，逆之者灭夷。文教敷，武功巍。普被四海，万邦望风，莫不来绥。圣德潜断，先天弗违。弗违祥，享世永长。猛以致宽，道化光。赫明明，祚隆无疆。帝绩惟期，有命既集，崇此洪基。
《平玉衡》，古《巫山高行》。《平玉衡》，言景皇帝一万国之殊风，齐四海之乖心，礼贤养士，而纂洪业也。
平玉衡，纠奸回。万国殊风，四海乖。礼贤养士，羁御英雄思心齐。纂成洪业，崇皇阶。品物咸亨，圣敬日跻。聪鉴尽下情，明明综天机。
《文皇统百揆》，古《上陵行》。《百揆》，言文皇帝始统百揆，用人有序，以敷泰平之化也。
文皇统百揆，继天理万方。武将镇四隅，英佐盈朝堂。谋言协秋兰，清风发其芳。洪泽所渐润，砾石为珪璋。大道侔五帝，盛德逾三王。咸光大，上参天与地，至化无内外。无内外，六合并康乂。并康乂，遘兹嘉会。在昔羲与农，大晋德斯迈。镇征及诸州，为蕃卫。功济四海，洪烈流万世。
《因时运》，古《将进酒行》。《因时运》，言文皇帝因时运变，圣谋潜施，解长蛇之交，离群桀之党，以武济文，审其大计，以迈其德也。
因时运，圣策施。长蛇交解，群桀离。势穷奔吴，虎骑厉。惟武进，审大计。时迈其德，清一世。
《惟庸蜀》，古《有所思行》。《惟庸蜀》，言文皇帝既平万乘之蜀，封建万国，复五等之爵也。
惟庸蜀，僭号天一隅。刘备逆帝命，禅亮承其余。拥众数十万，窥隙乘我虚。驿骑进羽檄，天下不遑居。姜维屡寇边，陇上为荒墟。文皇愍斯民，历世受罪辜。外谟蕃屏臣，内谋众士夫。爪牙应指授，腹心献良图。良图协成文，大兴百万军。雷鼓震地起，猛势陵浮云。逋虏畏天诛，面缚造垒门。万里同风教，逆命称妾臣。光建五等，纪纲天人。
《天序》，古《芳树行》。《天序》，言圣皇应历受禅，弘济大化，用人各尽其才也。
天序，应历受禅，承灵祜。御群龙，勒螭虎。弘济大化，英俊作辅。明明统万机，赫赫镇四方。咎由稷契之畴，协兰芳。礼王臣，覆兆民。化之如天与地，谁敢爱其身。
《大晋承运期》，古《上邪行》。《大晋承运期》，言圣皇应箓受图，化象神明也。
大晋承运期，德隆圣皇。时清晏，白日垂光。庆箓图，陟帝位，继天正玉衡，化行象神明。至哉道隆虞与唐。元首敷洪化，百僚股肱并忠良，民大康。隆隆赫赫，福祚盈无疆。
《金灵运》，古《君马黄行》。《灵运》，言圣皇践阼，致敬宗庙，而孝道施于天下也。
金灵运，天符发。圣征见，参日月。惟我皇，体神圣。受魏禅，应天命。皇之兴，灵有征。登大麓，御万乘。皇之辅，若虓虎。爪牙奋，莫之御。皇之佐，赞清化。百事理，万邦贺。神只应，嘉瑞章。恭享祀，荐先皇。乐时奏，磬管锵。鼓渊渊，钟喤々。奠尊俎。实玉觞。神歆飨，咸说康。宴孙子，祐无疆。大孝烝烝，德教被万方。
《于穆我皇》，古《雉子行》。《于穆》，言圣皇受命，德合神明也。
于穆我皇，盛德圣且明。受禅君世，光济群生。普天率土，莫不来庭。颙颙六合内，望风仰泰清。万国雍雍，兴颂声。大化洽，地平而天成。七政齐，玉衡惟平。峨峨佐命，济济群英。夙夜乾乾，万机是经。虽治兴，匪荒宁。谦道光，冲不盈。天地合德，日月同荣。赫赫煌煌，耀幽冥。三光克从，于显天垂景星。龙凤臻，甘露宵零。肃神祇，祗上灵。万物欣戴，自天效其成。
《仲春振旅》，古《圣人出行》。《仲春》，言大晋申文武之教，田猎以时也。
仲春振旅，大致民，武教于时日新。师执提，工执鼓，坐作从，节有序，盛矣允文允武。搜田表祃，申法誓，遂围禁，献社祭，允矣时明国制。文武并用，礼之经，列车如战，大教明，古今谁能去兵。大晋继天，济群生。
《夏苗田》，古《临高台行》。《苗田》，言大晋田狩从时，为苗除害也。
夏苗田，运将徂，军国异容，文武殊。乃命群吏，选车徒，辩其名号，赞契书。王军启八门，行同上帝居。时路建大麾，云旗翳紫虚。百官象其事，疾则疾，徐则徐。回衡旋轸，罢陈敝车。献禽享祠，烝烝配有虞。惟大晋，德参两仪，化云敷。
《仲秋狝田》，古《远期行》。《仲秋》，言大晋虽有文德，不废武事，从时以杀伐也。仲秋狝田，金德常刚。凉风清且厉，凝露结为霜。白虎司辰，苍隼时鹰扬。鹰扬犹周尚父，从天以杀伐。春秋时叙，雷霆震威耀，进退由钲鼓。致禽祀惣，羽毛之用充军府。赫赫大晋德，芬烈陵三五，敷化以文，虽治不废武。光宅四海，永享天之祜。
《从天道》，古《石留行》。《从天道》，言仲冬大阅，用武修文，大晋之德配天也。
从天道，握神契。三时亦讲武事，冬大阅。鸣镯振鼓铎，旌旗象虹霓。文制其中，武不穷武，动军誓众，礼成而义举。三驱以崇仁，进止不失其序。兵卒练，将如虎。惟虓虎，气陵青云。解围三面，杀不殄群。偃旌麾，班六军。献享烝，修典文。嘉大晋，德配天。禄报功，爵俟贤。飨燕乐，受兹百禄，嘉万年。
《唐尧》，《古务成行》，古曲亡。《唐尧》，言圣皇陟帝位，德化光四表也。
唐尧咨务成，谦谦德所兴。积渐终光大，履霜致坚冰。神明道自然，河海犹可凝。舜禹统百揆，元凯以次升。禅让应天历，睿圣世相承。我皇陟帝位，平衡正准绳。德化飞四表，祥气见其征。兴王坐俟旦，亡主恬自矜。致远由近始，覆篑成山陵。披图按先籍，有其证灵液。
《玄云》，古《玄云行》，古曲亡。《玄云》，言圣皇用人，各尽其材也。
玄云起山岳，祥气万里会。龙飞何蜿蜿，凤翔何翙翙。昔在唐虞朝，时见青云际。今亲游方国，流光溢天外。鹤鸣在后园，清音随风迈。成汤隆显命，伊挚来如飞。周文猎渭滨，遂载吕望归。符合如影响，先天天弗违。辍耕总地纲，解褐衿天维。元功配二主，芬馨世所稀。我皇叙群才，洪烈何巍巍。桓桓征四表，济济理万机。神化感无方，髦才盈帝畿。丕显惟昧旦，日新孔所咨。茂哉圣明德，日月同光辉。
《伯益》，古《黄爵行》，古曲亡。《伯益》，言赤乌衔书，有周以兴。今圣皇受命，神雀来也。
伯益佐舜禹，职掌山与川。德侔十六相，思心入无间。智理周万物，下知众鸟言。黄雀应清化，翔集何翩翩。和鸣栖庭树，徘徊云日间。夏桀为无道，密网施山阿。酷祝振纤网，当柰黄雀何。殷汤崇天德，去其三面罗。逍遥群飞来，鸣声乃复和。朱雀作南宿，凤皇统羽群。赤鸟衔书至，天命瑞周文。神雀今来游，为我受命君。嘉祥致天和，膏泽降青云。兰风发芳气，阖世同其芬。
《钓竿》，古《钓竿行》，〔汉《铙歌》二十二无《钓竿》。〕《钓竿》，言圣皇德配尧、舜，又有吕望之佐以济大功致太平也。
钓竿何冉冉，甘饵芳且鲜。临川运思心，微纶沈九渊。太公宝此术，乃在灵秘篇。机变随物移，精妙贯未然。游鱼惊着钓，潜龙飞戾天。戾天安所至，抚翼翔太清。太清一何异，两仪出浑成。玉衡正三辰，造化赋群形。退愿辅圣君，与神合其灵。我君弘远略，天人不足并。天人初并时，昧昧何茫茫。日月有征兆，文象兴二皇。蚩尤乱生民，黄帝用兵征万方。逮夏禹而德衰，三代不及虞与唐。我皇圣德配尧舜，受禅即阼享天祥。率土蒙祐，靡不肃，庶事康。庶事康，穆穆明明。荷百禄，保无极，永泰平。
吴鼓吹曲十二篇，韦昭造：《炎精缺》者，言汉室衰，武烈皇帝奋迅猛志，念在匡救，然而王迹始乎此也。汉曲有《朱鹭》，此篇当之。第一。
炎精缺，汉道微。皇纲弛，政德违。众奸炽，民罔依。赫武烈，越龙飞。陟天衢，耀灵威。鸣雷鼓，抗电麾。抚乾衡，镇地机。厉虎旅，骋熊罴。发神听，吐英奇。张角破，边韩羁。宛颍平，南土绥。神武章，渥泽施。金声震，仁风驰。显高门，启皇基。统罔极，垂将来。
右《炎精缺曲》凡三十句，句三字。
《汉之季》者，武烈皇帝悼汉之微，痛卓之乱，兴兵奋击，功盖海内也。汉曲有《曲悲翁》，此篇当之。第二。
汉之季，董卓乱。桓桓武烈，应时运。义兵兴，云旗建。厉六师，罗八陈。飞鸣镝，接白刃。轻骑发，介士奋。丑虏震，使众散。劫汉主，迁西馆。雄豪怒，元恶偾。赫赫皇祖，功名闻。
右《汉之季曲》凡二十句，其十八句句三字，二句句四字。
《摅武师》者，言大皇帝卒武烈之业而奋征也。汉曲有《艾如张》，此篇当之。第三。摅武师，斩黄祖。肃夷凶族，革平西夏。炎炎大烈，震天下。
右《摅武师曲》凡六句，其三句句三字，三句句四字。
《乌林》者，言曹操既破荆州，从流东下，欲来争锋。大皇帝命将周瑜逆击之于乌林而破走也。汉曲有《上之回》，此篇当之。第四。
曹操北伐，拔柳城。乘胜席卷，遂南征。刘氏不睦，八郡震惊。众既降，操屠荆。舟车十万，扬风声。议者狐疑，虑无成。赖我大皇，发圣明。虎臣雄烈，周与程。破操乌林，显章功名。
右《伐乌林曲》凡十八句，其十句句四字，八句句三字。
《秋风》者，言大皇帝说以使民，民忘其死。汉曲有《拥离》，此篇当之。第五。
秋风扬沙尘，寒露沾衣裳。角弓持弦急，鸠鸟化为鹰。边垂飞羽檄，寇贼侵界疆。跨马披介胄，慷慨怀悲伤。辞亲向长路，安知存与亡。穷达固有分，志士思立功。邀之战场，身逸获高赏，身没有遗封。
右《秋风曲》凡十五句，其十四句句五字，一句四字。
《克皖城》者，言曹操志图并兼，而令朱光为庐江太守。上亲征光，破之于皖城也。汉曲有《战城南》，此篇当之。第六。
克灭皖城，遏寇贼。恶此凶孽，阻奸慝。王师赫征，众倾覆。除秽去暴，戢兵革。民得就农，边境息。诛君吊臣，昭至德。右《克皖城曲》凡十二句，其六句句三字，六句句四字。
《关背德》者，言蜀将关羽背弃吴德，心怀不轨。大皇帝引师浮江而禽之也。汉曲有《巫山高》，此篇当之。第七。
关背德，作鸱张。割我邑城，图不祥。称兵北伐，围樊襄阳。嗟臂大于股，将受其殃。巍巍吴圣主，睿德与玄通。与玄通，亲任吕蒙。泛舟洪氾池，溯涉长江。神武一何桓桓。声烈正与风翔。历抚江安城，大据郢邦。虏羽授首，百蛮咸来同，盛哉无比隆。
右《关背德曲》凡二十一句，其八句句四字，二句句六字，七句句五字，四句句三字。
《通荆门》者，言大皇帝与蜀交好齐盟，中有关羽自失之愆，戎蛮乐乱，生变作患，蜀疑其眩，吴恶其诈，乃大治兵，终复初好也。汉曲有《上陵》，此篇当之。第八。
荆门限巫山，高峻与云连。蛮夷阻其险，历世怀不宾。汉王据蜀郡，崇好结和亲。乖微中情疑，谗夫乱其间。大皇赫斯怒，虎臣勇气震。荡涤幽薮，讨不恭。观兵扬炎耀，厉锋整封疆。整封疆，阐扬威武容。功赫戏，洪烈炳章。邈矣帝皇世，圣吴同厥风。荒裔望清化，化恢弘。煌煌大吴，延祚永未央。
右《通荆门曲》凡二十四句，其十七句句五字，四句句三字，三句句四字。
《章洪德》者，言大皇帝章其大德，而远方来附也。汉曲有《将进酒》，此篇当之。第九。
章洪德，迈威神。感殊风，怀远邻。平南裔，齐海滨。越裳贡，扶南臣。珍货充庭，所见日新。右《章洪德曲》凡十句，其八句句三字，二句句四字。
《从历数》者，言大皇帝从箓图之符，而建大号也。汉曲有《有所思》，此篇当之。第十。
从历数，于穆我皇帝。圣哲受之天，神明表奇异。建号创皇基，聪睿协神思。德泽浸及昆虫，浩荡越前代。三光显精耀，阴阳称至治。肉角步郊畛，凤凰栖灵囿。神龟游沼池，图谶摹文字。黄龙觌鳞，符祥日月记。览往以察今，我皇多哙事。上钦昊天象，下副万姓意。光被弥苍生，家户蒙惠赉。风教肃以平，颂声章嘉喜。大吴兴隆，绰有余裕。
右《从历数曲》凡二十六句，其一句句三字，三句句四字，二十二句句五字，一句六字。
《承天命》者，言上以圣德践位，道化至盛也。汉曲有《芳树》，此篇当之。第十一。
承天命，于昭圣德。三精垂象，符灵表德。巨石立，九穗植。龙金其鳞，乌赤其色。舆人歌，亿夫叹息。超龙升，袭帝服。躬淳懿，体玄默。夙兴临朝，劳谦日昃。易简以崇仁，放远谗与慝。举贤才，亲近有德。均田畴，茂稼穑。审法令，定品式。考功能，明黜陟。人思自尽，惟心与力。家国治，王道直。思我帝皇，寿万亿。长保天禄，祚无极。
右《承天命曲》凡三十四句，其十九句句三字，二句句五字，十三句句四字。
《玄化》者，言上修文训武，则天而行，仁泽流洽，天下喜乐也。汉曲有《上邪》，此篇当之。第十二。
玄化象以天，陛下圣真。张皇纲，率道以安民。惠泽宣流而云布，上下睦亲。君臣酣宴乐，激发弦歌扬妙新。修文筹庙胜，须时备驾巡洛津。康哉泰，四海欢欣，越与三五邻。
右《玄化曲》凡十三句，其五句句五字，二句句三字，三句句四字，三句句七字。今鼓吹铙歌词。〔乐人以音声相传，训诂不可复解。〕
大竭夜乌自云何来堂吾来声乌奚姑悟姑尊卢圣子黄尊来餭清婴乌白日为随来郭吾微令吾
应龙夜乌由道何来直子为乌奚如悟姑尊卢鸡子听乌虎行为来明吾微令吾
诗则夜乌道禄何来黑洛道乌奚悟如尊尔尊卢起黄华乌伯辽为国日忠雨令吾
伯辽夜乌若国何来日忠雨乌奚如悟姑尊卢面道康尊录龙永乌赫赫福胙夜音微令吾右四解，《上邪曲》。几令吾几令诸韩乱发正令吾
几令吾诸韩从听心令吾若里洛何来韩微令吾尊卢忌卢文卢子路子路为路鸡如文卢炯乌诸胙微令吾几令诸韩或公随令吾几令吾几诸或言随令吾黑洛何来诸韩微令吾
尊卢安成随来免路路子为吾路奚如文卢炯乌诸胙微令吾右九解，《晚芝曲》。〔汉曲有《远期》，疑是。〕几令吾呼历舍居执来随咄武子邪令乌衔针相风其右其右
几令吾呼群议破葫执来随吾咄武子邪令乌今乌今狖入海相风及后
几令吾呼无公赫吾执来随吾咄武子邪令乌无公赫吾婮立诸布始布右三解，《艾如张曲》。鼓吹铙歌十五篇，何承天义熙中私造：
《朱路篇》：朱路扬和鸾，翠盖耀金华。玄牡饰樊缨，流旌拂飞霞。雄戟辟旷涂，班剑翼高车。三军且莫喧，听我奏铙歌。清鞞惊短箫，朗鼓节鸣笳。人心惟恺豫，兹音亮且和。轻风起红尘，渟澜发微波。逸韵腾天路，颓响结城阿。仁声被八表，威震振九遐。嗟嗟介胄士，勖哉念皇家。
《思悲公篇》：思悲公，怀衮衣。东国何悲，公西归。公西归，流二叔，幼主既悟，偃禾复。偃禾复，圣志申。营都新邑，从斯民。从斯民，德惟明。制礼作乐，兴颂声。兴颂声，致嘉祥。鸣凤爰集，万国康。万国康，犹弗已。握发吐餐，下群士。惟我君，继伊周。亲睹盛世，复何求。
《雍离篇》：雍士多离心，荆民怀怨情。二凶不量德，构难称其兵。王人衔朝命，正辞纠不庭。上宰宣九伐，万里举长旌。楼船掩江濆，驷介飞重英。归德戒后夫，贾勇尚先鸣。逆徒既不济，愚智亦相倾。霜锋未及染，鄢郢忽已清。西川无潜鳞，北渚有奔鲸。凌威致天府，一战夷三城。江汉被美化，宇宙歌太平。惟我东郡民，曾是深推诚。
《战城南篇》：战城南，衡黄尘。丹旌电烻，鼓雷震。勍敌猛，戎马殷。横陈亘野，若屯云。仗大从，应三灵。义之所感，士忘生。长剑击，繁弱鸣。飞镝炫晃，乱奔星。虎骑跃，华毦旋。朱火延起，腾飞烟。骁雄斩，高旗搴。长角浮叫，响清天。夷群寇，殪逆徒。余黎沾惠，咏来苏。奏恺乐，归皇都。班爵献俘，邦国娱。
《巫山高篇》：巫山高，三峡峻。青壁千寻，深谷万仞。崇岩冠灵，林冥冥。山禽夜响，晨猿相和鸣。洪波迅澓，载逝载停。悽悽商旅之客，怀苦情。在昔阳九，皇纲微。李氏窃命，宣武耀灵威。蠢尔逆纵，复践乱机。王旅薄伐，传首来至京师。古之为国，惟德是贵。力战而虚民，鲜不颠坠。矧乃叛戾，伊胡能遂。咨尔巴子，无放肆。
《上陵者篇》：上陵者，相追攀。被服纤丽，振绮纨。携童幼，升崇峦。南望城阙，郁盘桓。王公第，通衢端。高甍华屋，列朱轩。临浚谷，掇秋兰。士女悠奕，映隰原。指营丘，感牛山。爽鸠既没，景君叹。嗟岁聿，游不还。志气衰沮，玄鬓斑。野莽宿，坟土干。顾此累累，中心酸。生必死，亦何怨。取乐今日，展情欢。
《将进酒篇》：将进酒，庆三朝。备繁礼，荐嘉肴。荣枯换，霜雾交。缓春带，命朋僚。车等旗，马齐镳。怀温克，乐林濠。士失志，愠情劳。思旨酒，寄游遨。败德人，甘醇醪。耽长夜，或淫妖。兴屡舞，厉哇谣。形亻差亻差，声号呶。首既濡，志亦荒。性命天，国家亡。嗟后生，节酣觞。匪酒辜，孰为殃。
《君马篇》：君马丽且闲，扬镳腾逸姿。骏足蹑流景，高步追轻飞。冉冉六辔柔，奕奕金华晖。轻霄翼羽盖，长风靡淑旗。愿为范氏驱，雍容步中畿。岂效诡遇子，驰骋趣危机。铅陵策良驷，造父为之悲。不怨吴坂峻，但恨伯乐稀。赦彼岐山盗，实跻韩原师。柰何汉魏主，纵情营所私。疲民甘藜藿，厩马患盈肥。人畜贸厥养，苍生将焉归。
《芳树篇》：芳树生北庭，丰隆正裴徊。翠颖陵冬秀，红葩迎春开。佳人闲幽室，惠心婉以谐。兰房掩绮幌，绿草被长阶。日夕游云际，归禽命同栖。皓月盈素景，凉风拂中闺。哀弦理虚堂，要妙清且悽。啸歌流激楚，伤此硕人怀。梁尘集丹帷，微飙扬罗袿。岂怨嘉时莫，徒惜良愿乖。
《有所思篇》：有所思，思昔人。曾闵二子，善养亲。和颜色，奉晨昏。至诚烝烝，通明神。邹孟轲，为齐卿。称身受禄，不贪荣。道不用，独拥楹。三徙既谇，礼义明。飞鸟集，猛兽附。功成事毕，乃更娶。哀我生，遘凶旻。幼罹荼毒，备艰辛。慈颜绝，见无因。长怀永思，托丘坟。
《雉子游原泽篇》：雉子游原泽，初怀耿介心。饮啄虽勤苦，不愿栖园林，古有避世士，抗志清霄岑。浩然寄卜肆，挥棹通川阴。消摇风尘外，散发抚鸣琴。卿相非所眄，何况于千金。功名岂不美，宠辱亦相寻。冰炭结六府，忧虞缠胸襟。当世须大度，量己不克任。三复泉流诫，自惊良已深。
《上邪篇》：上邪下难正，众枉不可矫。音和响必清，端影缘直表。大化扬仁风，齐人犹偃草。圣王既已没，谁能弘至道。开春湛柔露，代终肃严霜。承平贵孔孟，政敝侯申商。孝公明赏罚，六世犹克昌。李斯肆滥刑，秦氏所以亡。汉宣隆中兴，魏祖宁三方。譬彼针与石，效疾故称良。《行苇》非不厚，悠悠何讵央。琴瑟时永调，改弦当更张。矧乃治天下，此要安可忘。
《临高台篇》：临高台，望天衢，飘然轻举，陵太虚。携列子，超帝乡。云衣雨带，乘风翔。肃龙驾，会瑶台。清晖浮景，溢蓬莱。济四海，濯洧盘。伫立云岳，结幽兰。驰迅风，游炎州。愿言桑梓，思旧游。倾霄盖，靡电旌。降彼天涂，颓窈冥。辞仙族，归人群。怀忠抱义，奉明君。任穷达，随所遭。何为远想，令心劳。
《远期篇》：远期千里客，肃驾候良辰。近命城郭友，具尔惟懿亲。高门启双闱，长筵列嘉宾。中唐舞六佾，三厢罗乐人。箫管激悲音，羽毛扬华文。金石响高宇，弦歌动梁尘。修标多巧捷，九剑亦入神。迁善自雅调，成化由清均。主人垂隆庆，群士乐亡身。愿我圣明君，迩期保万春。
《石流篇》：石上流水，湔湔其波。发源幽岫，永归长河。瞻彼逝者，岁月其偕。子在川上，惟以增怀。嗟我殷忧，载劳寤寐。遘此百罹，有志不遂。行年倏忽，长勤是婴。永言没世，悼兹无成。幸遇开泰，沐浴嘉运。缓带安寝，亦又何愠。古之为仁，自求诸己。虚情遥慕，终于徒已。
《圣人制礼乐》一篇，《巾舞歌》一篇，按《景祐广乐记》言，字讹谬，声辞杂书。宋鼓吹铙歌辞四篇，旧史言，诂不可解。汉鼓吹铙歌十八篇，按《古今乐录》，皆声、辞、艳相杂，不复可分。
