INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642534, '孟子 · 第一卷 · 梁惠王上 · 第一节', NULL, 42, 271, 2, 2, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子见梁惠王。王曰：“叟不远千里而来，亦将有以利吾国乎？”
孟子对曰：“王何必曰利？亦有仁义而已矣。王曰‘何以利吾国’？大夫曰‘何以利吾家’？士庶人曰‘何以利吾身’？上下交征利而国危矣。万乘之国弑其君者，必千乘之家；千乘之国弑其君者，必百乘之家。万取千焉，千取百焉，不为不多矣。苟为后义而先利，不夺不餍。未有仁而遗其亲者也，未有义而后其君者也。王亦曰仁义而已矣，何必曰利？”', '', '梁惠王：即魏惠王。他是魏武侯之子，公元前370年即位，即位后九年由旧都安邑（今山西夏县北）迁往大梁（今河南开封西北），所以又叫梁惠王。
士庶人：士人和庶人；庶人，老百姓。
交征：互相争夺。征：取。
万乘（shèng）之国：拥有一万辆兵车的国家，代指的是大国。
弑（shì）：古代称杀父杀君叫做“弑”。
', '孟子见到了梁惠王。梁惠王说：“老先生，你不远千里而来，一定是有什么对我的国家有利的高见吧？”
孟子回答说：“大王何必说利呢？只要说仁义就可以了。大王说：‘怎样对我国有利？’大夫说：‘怎样对我的封地有利？’士人和老百姓说：‘怎样对我自己有利？’上下争相求利，那国家就危险了啊。在一个拥有一万辆兵车的国家，杀害君王的人，一定是拥有一千辆兵车的大夫；在一个拥有一千辆兵车的国家，杀害君王的人，一定是拥有一百辆兵车的大夫。就大夫来说，在一万辆兵车的国家里，拥有一千辆兵车，在一千辆兵车的国家里，拥有一百辆兵车，不可不算是富有了。如果先利后义，那他们不夺得国君的地位就不会得到满足。如果先义后利的话，就没有讲‘仁’的人却抛弃父母的，也从来没有讲‘义’的人却不顾君王的。从没有讲仁却遗弃自己父母的，也没有讲义却轻慢自己君王的。所以，大王只要讲仁义就可以了，何必讲利呢？”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0ee", "shortContent": "义利之辩，孔子早有见解：“君子喻于义，小人喻于利。”（《论语·里仁》）“不义而富且贵，于我如浮云。”（《论语·述而》）可见，义是孔子心中理想君子必备的品格。梁惠王向孟子请教治国策略，一开口便问利，这当然与孟子的仁义思想违背。因此孟子向梁惠王说明了只追求利的弊端，希望君王能够秉持重义轻利的原则治理国家。孟子继承了孔子重义轻利的观点，不仅将义与仁、礼、智看作是人心固有的品质，认为“仁义礼智，非由外铄我...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1557501796, '5cd526e1c8959c00685273f8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642535, '孟子 · 第一卷 · 梁惠王上 · 第二节 ', NULL, 18, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子见梁惠王，王立于沼上，顾鸿雁麋鹿，曰：「贤者亦乐此乎？」
孟子对曰：「贤者而后乐此，不贤者虽有此，不乐也。诗云：『经始灵台，经之营之，庶民攻之，不日成之。经始勿亟，庶民子来。王在灵囿，麀鹿攸伏，麀鹿濯濯，白鸟鹤鹤。王在灵沼，于牣鱼跃。』文王以民力为台为沼。而民欢乐之，谓其台曰灵台，谓其沼曰灵沼，乐其有麋鹿鱼鳖。古之人与民偕乐，故能乐也。汤誓曰：『时日害丧？予及女偕亡。』民欲与之偕亡，虽有台池鸟兽，岂能独乐哉？」', '', '沼：大的水洼，相当于池塘、水池。
所引的是《诗经·大雅·灵臺》，写周文王兴建灵台、灵囿、灵沼而庶民相助的盛况。
灵台：台名，故址在今陕西西安西北。
子来：像儿子为父母效劳那样来帮忙。
麀（yōu）：母鹿。鹿：指公鹿。
攸：同「所」。
濯濯（zhuó zhuó）：肥硕而有光泽的样子。
鹤鹤：羽毛洁白的样子。
於（wū）：语气词，表示叹美。
牣（rèn）：盈满。
时日：这个太阳，指夏桀；时，这。
害（hé）：何，何时。
丧：毁灭。
予及女（rǔ）：我和你；女，通「汝」。《汤誓》是《尚书》中的一篇，记载的是商汤讨伐夏桀时的誓师词。', '孟子觐见梁惠王，梁惠王站在池塘边，观看着鸿雁和麋鹿，问道：「贤人对此也感受到快乐吗？」
孟子答道：「衹有贤人才能感受到这种快乐，不贤的人纵然拥有珍禽异兽，也不会（真正感受到）快乐的。《诗经·大雅·灵台》篇道：『文王规划筑灵台，基址方位细安排。百姓踊跃来建造，灵台很快就造好。文王劝说不要急，百姓干活更积极。文王巡遊到灵囿，母鹿自在乐悠悠。母鹿肥美光泽好，白鸟熠熠振羽毛。文王游观到灵沼，鱼儿满池喜跳跃。』文王用民众的劳力建高台挖深池，然而民众乐意去做，称这个台叫灵台，称这个池叫灵沼，还欣喜园囿中有这么多的麋鹿鱼鳖。古代的贤君与民同乐，所以能感受到这种快乐。《尚书·汤誓》篇有这样的话：『这个太阳什么时候灭亡？我们要跟你同归于尽！』民众想跟他拼命，夏桀纵然有高台美池，奇禽异兽，难道能够独自享受这种快乐吗？」', NULL, '', 'indent', 1557501836, '5cd5270a7b968a00755d737a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642537, '孟子 · 第一卷 · 梁惠王上 · 第四节 ', NULL, 22, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '梁惠王曰：“寡人愿安承教。”
孟子对曰：“杀人以梃与刃，有以异乎？”曰：“无以异也。”“以刃与政，有以异乎？”曰：“无以异也。”
曰：“庖有肥肉，厩有肥马，民有饥色，野有饿莩，此率兽而食人也。兽相食，且人恶之。为民父母，行政不免于率兽而食人。恶在其为民父母也？仲尼曰：‘始作俑者，其无后乎！’为其象人而用之也。如之何其使斯民饥而死也？”', '', '愿安：乐意。
梃（tǐng）：木棍。刃：刀。
率：放任。
且人恶（wù）之：按现在的词序，应是“人且恶之”。且：尚且。恶：讨厌，憎恨。
恶（wū）：古同“乌”，疑问副词，何。
俑（yǒng）：古代陪葬用的土偶、木偶。始作俑者：指最初来用土偶、木偶陪葬的人，后来这句话成为成语，指首开恶例的人。
', '梁惠王对孟子说：“我乐于听取您的指教。”
孟子答道：“用木棍打死人跟用刀杀死人，（本质上）有什么不同吗？”
惠王说：“没有什么不同。”
（孟子问：）“用刀子杀死人跟用苛政害死人，有什么不同吗？”
惠王说：“没有什么不同。”
孟子说：“厨房里有肥嫩的肉，马棚里有膘肥体壮的马，（可是）老百姓面带饥色，野外有饿死的尸体，这如同率领着野兽来吃人啊！野兽自相残食，人们见了尚且厌恶，而身为老百姓的父母官，施行政事，却避免不了（这种如同）率领野兽来吃人的结局，这又怎能算是老百姓的父母官呢？孔子说过：‘最初制作出陪葬用的土偶、木俑的人，应该会断子绝孙吧！’这是因为土偶、木俑做得像人的样子却用来殉葬。这样尚且不可以，那让老百姓饥饿而死的人（父母官），该如何对待呢？
', NULL, '', 'indent', 1557501999, '5cd527ac0237d70069bf172e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642774, '孟子 · 第十三卷 · 尽心上 · 第二十七节 ', NULL, 8, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“饥者甘食，渴者甘饮，是未得饮食之正也，饥渴害之也。岂惟口腹有饥渴之害？人心亦皆有害。人能无以饥渴之害为心害，则不及人不为忧矣。”
', '', '', '孟子说：“饥饿的人觉得任何食物都好吃，干渴的人觉得任何饮料都甘美，他不知道饮料、食物的正常味道，是因为受了饥渴的损害。难道只有嘴巴肚皮受到饥渴的损害吗？人心也都有这类伤害。假如一个人能够不把饥渴的损害变成对心的损害，那么即使发现自己有不及他人的地方，又有什么值得忧虑的呢？”
', NULL, '', 'indent', 1558348964, '5ce214226e9ba1006821d592', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642538, '孟子 · 第一卷 · 梁惠王上 · 第五节 ', NULL, 18, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '梁惠王曰：“晋国，天下莫强焉，叟之所知也。及寡人之身，东败于齐，长子死焉；西丧地于秦七百里；南辱于楚。寡人耻之，愿比死者一洒之，如之何则可？”
孟子对曰：“地方百里而可以王。王如施仁政于民，省刑罚，薄税敛，深耕易耨。壮者以暇日修其孝悌忠信，入以事其父兄，出以事其长上，可使制梃以挞秦楚之坚甲利兵矣。彼夺其民时，使不得耕耨以养其父母，父母冻饿，兄弟妻子离散。彼陷溺其民，王往而征之，夫谁与王敌？故曰：‘仁者无敌。’王请勿疑！”', '', '晋国：韩、赵、魏三家分晋，列为诸侯，战国时还被称为三晋，所以，惠王也称魏国为晋国。
东败于齐，长子死焉：公元前341年，魏与齐战，败于马陵，齐虏魏太子申，杀魏将军庞涓。
西丧地于秦七百里：惠王时，魏国曾屡败于秦国，被迫多次割地。
南辱于楚：惠王时，围赵都邯郸，楚救赵，取魏睢、秽之间七邑。
比：代替。壹：专一地，集中全力地。洒：与“洗刷”的“洗”同，报仇雪耻的意思。
省：俭省。税敛：税收。易：治理得很好。耨（nòu）：除草。易耨：干净地彻底地拔掉田草，以免扰害禾苗。
', '梁惠王说：“我们晋国（魏国），以前天下没有哪个国家比它更强大的了，这是老先生您也知道的。（可是）传到我手中，东边败给了齐国，我的大儿子战死了；在西面被秦国夺去七百里土地；在南面又受辱于楚国。我深以为耻，很想替死在战场上的将士报仇雪恨。应该怎样做才好呢？”
孟子回答道：“方圆百里的小国也能够取得天下。大王如果对百姓施行仁政，少用刑罚，减轻赋税，（提倡）深耕细作、勤除杂草，让年轻人在耕种之余学习孝亲、敬兄、忠诚、守信的道理，在家侍奉父兄，在外敬重尊长，（这样）就可以让他们拿起木棍打赢盔甲坚硬、刀枪锐利的秦楚两国的军队了。他们（秦、楚）常年夺占百姓的农时，使百姓不能耕作来奉养父母。父母受冻挨饿，兄弟妻儿各自逃散。他们让老百姓陷入水深火热之中，（若）大王前去讨伐他们，谁能是大王您的对手呢？所以（古语）说：‘有仁德的人没有敌人。’大王请不要怀疑这个道理了。”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b44fee49f46528a4284b3", "shortContent": " 仁政是孟子最喜欢谈论的话题，可以说是贯穿《孟子》始终的论题。此书的全部文字展示了他在各个时期，在各种不同的场合，以各种不同的表达方式，从不同的学术领域和思想理论层次，充分地展开这一论题涵盖的一切，从而把仁政的观念发挥到淋漓尽致的地步。\n\n战国时期，天下大乱，群雄并起，各国君主穷兵黩武，扩张土地，而孟子却高扬王道大旗，到处奔走，宣传圣王之道，主张以德治国，施行仁政。这看起来是迷恋一种理想主义，具有...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557502049, '5cd527de7b968a00755d8278', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642539, '孟子 · 第一卷 · 梁惠王上 · 第六节 ', NULL, 20, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子见梁襄王。出，语人曰：“望之不似人君，就之而不见所畏焉。卒然问曰：‘天下恶乎定？’吾对曰：‘定于一。
’‘孰能一之？’对曰：‘不嗜杀人者能一之。
’‘孰能与之？’对曰：‘天下莫不与也。王知夫苗乎？七八月之间旱，则苗槁矣。天油然作云，沛然下雨，则苗浡然兴之矣。其如是，孰能御之？今夫天下之人牧，未有不嗜杀人者也，如有不嗜杀人者，则天下之民皆引领而望之矣。诚如是也，民归之，由水之就下，沛然谁能御之？’”', '', '梁襄王：即魏襄王，魏惠王的儿子，名嗣。因魏惠王将都城迁至大梁（今开封），故称魏为梁。
定于一：安定以统一为前提。
与：跟从，追随。
油然：盛多的样子。沛然：大雨滂沱的样子
今夫：掉换话头的连词。人牧：人君，指统治者。
由：与“犹”同。
', '孟子见到了梁襄王。出来之后，告诉别人说：“梁襄王远远地望去不像人君的样子，靠近些也看不出威严的样子。他突然问我：‘天下怎么样才能安定呢？’我对他说：‘统一了就能安定。’
“‘那么谁能统一天下呢？’我说：‘不喜欢杀人的人能统一天下。’
“‘什么人能归顺呢？’我说：‘天下百姓都会归顺。大王知道禾苗吗？七、八月之间天气大旱无雨，禾苗就枯黄了。（一旦）天空突然起了很厚的云，下了很大的雨，禾苗就重新旺盛起来。能够像这样，谁又能抵挡得了呢？现在天下各国的国君，没有一个不爱好杀人的。如果有不好杀人的人出现，那么天下的老百姓就会伸长脖子盼望了！如果能做到这样，老百姓归顺他就像水向下奔流一样，气势汹涌，谁又能阻挡得了呢！’”
', NULL, '', 'indent', 1557502130, '5cd52830c8959c0068528aaf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642541, '孟子 · 第一卷 · 梁惠王上 · 第七节 · 二', NULL, 29, 271, 4, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '王说曰：“《诗》云：‘他人有心，予忖度之。’夫子之谓也。夫我乃行之，反而求之，不得吾心。夫子言之，于我心有戚戚焉。此心之所以合于王者，何也？”
曰：“有复于王者曰：‘吾力足以举百钧，而不足以举一羽；明足以察秋毫之末，而不见舆薪。’则王许之乎？”
曰：“否。”
“今恩足以及禽兽，而功不至于百姓者，独何与？然则一羽之不举，为不用力焉；舆薪之不见，为不用明焉；百姓之不见保，为不用恩焉。故王之不王，不为也，非不能也。”
曰：“不为者与不能者之形何以异？”
曰：“挟太山以超北海，语人曰：‘我不能。’是诚不能也。为长者折枝，语人曰：‘我不能。’是不为也，非不能也。故王之不王，非挟太山以超北海之类也；王之不王，是折枝之类也。老吾老，以及人之老；幼吾幼，以及人之幼。天下可运于掌。《诗》云：‘刑于寡妻，至于兄弟，以御于家邦。’言举斯心加诸彼而已。故推恩足以保四海，不推恩无以保妻子。古之人所以大过人者，无他焉，善推其所为而已矣。今恩足以及禽兽，而功不至于百姓者，独何与？
“权，然后知轻重；度，然后知长短。物皆然，心为甚。王请度之！
“抑王兴甲兵，危士臣，构怨于诸侯，然后快于心与？”
王曰：“否！吾何快于是？将以求吾所大欲也。”
', '', '说（yuè）：同“悦”，得到理解而喜悦。
钧：古代重量单位，三十斤为一钧。
舆薪：以车载薪，大而易见；舆：车。
不王（wàng）：指未能实行王道。
形：情况，状况。何以异：怎样区别。
有一说“枝”通“肢”，“为长者折枝”翻译：为长者鞠躬弯腰的事。
挟：用腋挟持。太（tài）山：即“泰山”。超：跳过。北海：渤海。
老吾老、幼吾幼：第一个“老”和“幼”字都是动词，老，尊敬；幼，爱护。第二个“老”和“幼”字都是名词。
“刑于”三句：这三句诗引自《诗经·大雅·思齐》篇。刑：典型，法则，此作动词用。寡妻：正妻；“寡”有独特的意义。御：治。推进：国家。诗意歌颂周文王的美德，由近及远地为妻子所取法，推及兄弟，更推进于全国。
权：秤锤，这里名词动用，就是用权称量的意思。
', '齐宣王高兴地说：“《诗经》上说：‘他人的心思，我能揣摩到。’说的正像是老先生你啊。我做完这件事，又回过头剖析我的心理，自己都搞不清楚。先生你的这番话，使我心里有点开窍了。这样的心理就符合王道，又是为什么呢？”
孟子说：“有人跟大王说：‘我的力量能举起三千斤，但我不能举起一根羽毛；我的眼睛可以明察秋毫的末梢，但却不能看到一车薪柴。’那么大王会同意他吗？”
齐宣王说：“不同意。”
孟子说：“现在您的恩惠能到达禽兽，却不能到老百姓那里，这是为什么呢？一根羽毛举不起来，是不用劲呀；一车薪柴看不见，是不用视力呀；老百姓没受到爱护，是不用恩惠呀。所以大王您没能称王于天下，是不肯去做，并不是不能。”
齐宣王问：“不去做与不能做的表现有什么不同吗？”
孟子说：“胳肢窝里夹着泰山要去跳跃过渤海，告诉人说：‘我不能。’这确实不能。帮年纪大的人折取树枝，说：‘我不能。’这就是不去做，而不是做不到。所以大王您没能称王于天下，是像替老年人折取树枝一样，而不是夹着泰山跳过渤海。尊敬自己的老人，就把这种尊敬推及别人的老人；爱护自己的孩子，也把这种爱护推及别人的孩子；天下就像是手掌中翻转小东西一样容易治理。《诗经》上说：‘为我的正妻做出表率，兄弟们也跟着学，进而能治理国家。’这说的是推己及人的方法罢了。所以说推广恩惠能保有四海，不推广恩惠不能保护自己的老婆孩子。古代圣王之所以远远超过别人，没有别的原因，也只是善于推广他的善心罢了。现在大王您的恩惠可以到达禽兽，而老百姓却享受不到，究竟是为什么呢？
“称一称，才能知道物体的轻重；量一量，才能知道物体的长短。所有的事物都是这样，而心尤其如此。请大王您好好想想吧！
“大王您是想兴兵打仗，让士臣处于危险境地，与诸侯结下仇怨，然后心中才能快活吗？”
齐宣王说：“不是的。我怎么能这样做呢？我将要追求我的更高远的目标。”
', NULL, '', 'indent', 1557502634, '5cd52a2730863b00702d75ca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642543, '孟子 · 第一卷 · 梁惠王上 · 第七节 · 四', NULL, 17, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '王曰：“吾惛，不能进于是矣。愿夫子辅吾志，明以教我。我虽不敏，请尝试之。”
曰：“无恒产而有恒心者，惟士为能。若民，则无恒产，因无恒心。苟无恒心，放辟邪侈，无不为已。及陷于罪，然后从而刑之，是罔民也。焉有仁人在位，罔民而可为也？是故明君制民之产，必使仰足以事父母，俯足以畜妻子，乐岁终身饱，凶年免于死亡；然后驱而之善，故民之从之也轻。
“今之制民之产，仰不足以事父母，俯不足以畜妻子；乐岁终身苦，凶年不免于死亡。此惟救死而恐不赡，奚暇治礼义哉？
“王欲行之，则盍反其本矣：五亩之宅，树之以桑，五十者可以衣帛矣。鸡豚狗彘之畜，无失其时，七十者可以食肉矣。百亩之田，勿夺其时，八口之家可以无饥矣。谨庠序之教，申之以孝悌之义，颁白者不负戴于道路矣。老者衣帛食肉，黎民不饥不寒，然而不王者，未之有也。”
', '', '惛：神志不清，思想混乱。是：这。
恒产：长久经营的产业。恒心：坚定不变的信念。
放：放荡。辟：同“僻”，与“邪”同义。侈：不依制度，胡行乱为。
罔：同“网”，作动词用，陷害。
制：规定，订立制度、政策。
仰：上。俯：下。畜：养。
乐岁：丰年。凶年：荒年。
驱：驱使。“之善”的“之”：往，向。轻：易。
惟：仅只。不赡（shàn）：不足，不及。奚暇：怎么顾得上。', '齐宣王说：“我糊涂，不能达到这种境地啊。希望先生帮助我，明明白白地教导我。我虽然不聪明，但请让我试一试。”
孟子说：“没有固定的财产却有坚定的心志，只有士阶层能做到。至于老百姓，要是没有固定财产，也就不会有坚定的心志了。一旦没有坚定的心志，就会胡作非为，什么都干。等到犯了罪去惩罚他，这就等于张网捕捉老百姓。哪能有仁德的君王在位，却陷害百姓的呢？所以贤能的君主统治，规定百姓的产业，一定让他们向上可赡养父母，向下可养活老婆孩子。收成好时能一年到头吃饱饭，收成不好的年头不至于饿死。这之后再引导他们追求善，老百姓也就容易听从了。现在管理国家，弄得老百姓上不能赡养父母，下不能养活老婆孩子，收成好了受苦，收成不好难免饿死。活命都还来不及，哪有闲功夫讲求礼义呢？
“大王如要试一试，何不从根本处入手呢？五亩大的宅院，房前屋后种植桑树，五十岁的人就能穿上丝绸了。鸡狗猪等家畜不失时机地畜养起来，七十岁的人就能吃上肉了。百亩大的农田，不去妨碍农夫适时耕种，八口人的家庭就可以免于饥饿了，认认真真地办学校，反复用孝悌的道理来教导子弟，须发斑白的老人就不必背着或顶着重物在路上行走了。老年人都有绸缎穿，有肉吃，老百姓饿不着，冻不着，这样还不能使天下归服的，是从没有过的事。”
', NULL, '', 'indent', 1557502843, '5cd52af730863b00702d831c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642549, '悼亡诗', NULL, 0, 376, 1, 0, '沈约', NULL, 35895, '5858fce161ff4b0068768127', '南北朝', 'shi', '诗', '', '', '去秋三五月，今秋还照梁。
今春兰蕙草，来春复吐芳。
悲哉人道异，一谢永销亡。
帘屏既毁撤，帷席更施张。
游尘掩虚座，孤帐覆空床。
万事无不尽，徒令存者伤。', '', '', '', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccc10f8fda5565060f1b", "shortContent": "晋潘岳妻亡故，作《悼亡》诗三首。后人以《悼亡》为题之作，均悼其亡妻。\n去秋十五的圆月，几经圆缺，今秋圆月依旧高高挂在天幕，如水的清辉还和去年一样，透过窗棂，洒落房内。今春逗人喜爱的兰花蕙草，经夏而秋，经秋而冬，无不枯萎，可是来年冰化雪消，它们将会同去春一样溢香吐艳，为春天添色增辉。“悲哉人道异，一谢永销亡”，然而，人毕竟与“三五月”、“兰蕙草”不同。月缺了，有再圆的时候；花枯了，有重放的时候，而一...", "authors": ["陈庆元"], "pressName": "上海辞书出版社"}]', '', 'center', 1557637124, '5cd737817b968a007577ff46', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642551, '孟子 · 第二卷 · 梁惠王下 · 第一节', NULL, 10, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '庄暴见孟子，曰：“暴见于王，王语暴以好乐，暴未有以对也。”曰：“好乐何如？”
孟子曰：“王之好乐甚，则齐国其庶几乎？”
他日，见于王曰：“王尝语庄子以好乐，有诸？”
王变乎色，曰：“寡人非能好先王之乐也，直好世俗之乐耳。”
曰：“王之好乐甚，则国其庶几乎，今之乐犹古之乐也。”
曰：“可得闻与？”
曰：“独乐乐，与人乐乐，孰乐？”
曰：“不若与人。”
曰：“与少乐乐，与众乐乐，孰乐？”
曰：“不若与众。”
“臣请为王言乐。今王鼓乐于此，百姓闻王钟鼓之声，管籥之音，举疾首蹙頞而相告曰：‘吾王之好鼓乐，夫何使我至于此极也？父子不相见，兄弟妻子离散。’今王田猎于此，百姓闻王车马之音，见羽旄之美，举疾首蹙頞而相告曰：‘吾王之好田猎，夫何使我至于此极也？父子不相见，兄弟妻子离散。’此无他，不与民同乐也。今王鼓乐于此，百姓闻王钟鼓之声，管籥之音，举欣欣然有喜色而相告曰：‘吾王庶几无疾病与，何以能鼓乐也？’今王田猎于此，百姓闻王车马之音，见羽旄之美，举欣欣然有喜色而相告曰：‘吾王庶几无疾病与，何以能田猎也？’此无他，与民同乐也。今王与百姓同乐，则王矣。”', '', '庄暴：齐臣。
王：指齐宣王。见于王：进见于王前。
直：不过。
管：笙。籥（yuè）：箫。
举：皆。疾首：因忧愁而头痛。蹙頞（cù è）：皱眉头，表现忧愁的情状。
田：与“畋”同，打猎。
羽旄（máo）：指装饰着羽（鸟羽毛）旄（旄牛尾）的旌旗。
', '齐国的庄暴来见孟子，说：“大王接见我，告诉我他喜爱音乐，我不知该怎样回答他。”接着又问：“喜欢音乐好不好呢？”孟子说：“齐王如果喜爱音乐，那么齐国也应该治理得差不多了吧？”
后来的某一天，孟子被齐王接见，问（齐王）道：“大王曾对庄暴说喜爱音乐，有这回事吗？”
齐王（不好意思地）变了脸色，说：“我不是喜爱古代先王的音乐，只是喜爱现在社会上流行的音乐罢了。”
孟子说：“大王如此喜好音乐，那么齐国该治理得差不多了吧！流行的音乐与先王的音乐也是相通的呀。”
齐宣王说：“能否给我解释一下原因？”
孟子问：“一个人独自欣赏音乐的快乐，和与大家一起欣赏音乐的快乐相比，哪一种更快乐呢？”
齐宣王说：“不如与众人一起欣赏音乐快乐。”
孟子又问：“与很少的人一起欣赏音乐的快乐，和与很多人一起欣赏音乐的快乐相比，哪一种更为快乐呀？”
齐宣王说：“不如与很多人一起欣赏音乐快乐。”
孟子说：“就让我为您谈谈什么是真正的快乐吧。假设现在大王演奏音乐，老百姓听到大王的钟、鼓、管、籥等各种乐器发出的声音，都头疼地皱着鼻子互相议论说：‘我们大王喜欢演奏音乐，为什么让我们到了走投无路的境地？父子不能相见，兄弟分开，妻儿离散。’假设大王在这里打猎，百姓听到大王车马的声音，看到飘扬的旗帜威武雄壮，都头疼地皱着鼻子互相议论说：‘我们大王喜欢打猎，怎么能让我们到了痛苦至极呢？父子不能相见，兄弟分开，妻儿离散。’这没有别的原因，就在于不能跟老百姓一起快乐。假设现在大王在这里奏乐，百姓听到钟鼓的声音、箫笛的曲调，都欢欣鼓舞，喜形于色，互相议论说：‘我们的君王大概没什么疾病吧，不然怎么能奏乐呢？’假设现在大王在这里打猎，百姓听到君王车马的声音，看到旗帜的华美，都欢欣鼓舞，喜形于色，互相议论说：‘我们君王大概没什么疾病吧，不然怎么能打猎呢？’这没有别的原因，是和百姓共同快乐的缘故。如果大王能和百姓共同快乐，那就能称王于天下了。”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b45c5b6a81d0c538cf3e2", "shortContent": " 这一部分记录了几段孟子同君主的谈话，虽然没有深奥、系统的理论表述，表面看来话题也好像无关宏旨，然而正是在闲谈君主游乐之事的过程中，孟子确立了儒家仁政学说的哲学基础，阐明了国家的功能，规定了政府治国的根本目标，从而进一步发展了他的仁政学说。\n\n关于人对声色享乐的欲望，孟子的态度其实要比后代道学家们开明得多。在孟子看来，耳目喜好美声美色，口腹喜好美味佳肴，都是人们共同的喜好，是人的天生的本性。什么叫...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557741719, '5cd8d0147b968a007589fb64', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642552, '孟子 · 第二卷 · 梁惠王下 · 第二节 ', NULL, 12, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '齐宣王问曰：“文王之囿方七十里，有诸？”
孟子对曰：“于传有之。”
曰：“若是其大乎？”
曰：“民犹以为小也。”
曰：“寡人之囿方四十里，民犹以为大，何也？”
曰：“文王之囿方七十里，刍荛者往焉，雉兔者往焉。与民同之，民以为小，不亦宜乎？臣始至于境，问国之大禁，然后敢入。臣闻郊关之内有囿方四十里，杀其麋鹿者如杀人之罪。则是方四十里，为阱于国中。民以为大，不亦宜乎？”
', '', '传：古诗记。
刍荛（chú ráo）：割草打柴。
雉：野鸡。雉兔者：猎取雉、兔的人。
关：境界上的门。郊关：齐国四境之郊皆有关。
', '齐宣王问道：“听说周文王的园林占地七十里见方，有这回事吗？”
孟子回答说：“古书上是有这样的记载。”
齐宣王说：“竟然有这么大？”
孟子说：“老百姓还认为它小呢。”
齐宣王说：“我的园林仅四十里见方，老百姓还认为太大了，这是为什么呢？”
孟子说：“周文王的园林七十里见方，砍柴割草的，捉野鸡逮野兔的，都可自由出入。与老百姓共同使用，老百姓以为太小，不是很自然的吗？我刚到齐国的边境，先问清楚有什么禁令，才敢进入齐国。我听说齐国国都近郊有园林四十里见方，谁要是杀了那里的麋鹿就等于犯了杀人之罪。这就等于在国土上设置了一个四十里见方的大陷阱。老百姓认为它太大，不也是应该的吗？”', NULL, '', 'indent', 1557741785, '5cd8d05630863b00705a630d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642553, '孟子 · 第二卷 · 梁惠王下 · 第三节 ', NULL, 15, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '齐宣王问曰：“交邻国有道乎？”
孟子对曰：“有。惟仁者为能以大事小，是故汤事葛，文王事昆夷。惟智者为能以小事大，故太王事獯鬻，勾践事吴。以大事小者，乐天者也；以小事大者，畏天者也。乐天者保天下，畏天者保其国。《诗》云：‘畏天之威，于时保之。’”
王曰：“大哉言矣！寡人有疾，寡人好勇。”
对曰：“王请无好小勇。夫抚剑疾视曰，‘彼恶敢当我哉！’此匹夫之勇，敌一人者也。王请大之！《诗》云：‘王赫斯怒，爰整其旅，以遏徂莒，以笃周祜，以对于天下。’此文王之勇也。文王一怒而安天下之民。《书》曰：‘天降下民，作之君，作之师，惟曰其助上帝宠之。四方有罪无罪惟我在，天下曷敢有越厥志？’一人衡行于天下[8]，武王耻之。此武王之勇也。而武王亦一怒而安天下之民。今王亦一怒而安天下之民，民惟恐王之不好勇也。”
', '', '汤事葛：详见《滕文公下》第五章。葛，商的邻国。
昆夷：又作“混夷”，周朝初年的西戎国名。
太王事獯鬻（xūn yù）：详见本卷第十五章。太王，即周部族首领古公亶父，文王的祖父。獯鬻，即猃狁（xiǎn yǔn），当时北方的少数民族。
天：理，天理，天命。乐天：自然合理。畏天：不敢违理。
《诗》：指《诗经·周颂·我将》篇。于时：于是。引诗见《诗经·周颂·我将》，是一篇祭祀上天和周文王的诗。
《诗》：指《诗经·大雅·皇矣》篇。王：指周文王。爰：于是。以遏徂莒：遏，阻止。莒（jǔ），《诗经》作“旅”，指入侵来犯密国的部队。笃：厚，指增添。祜（hù）：福。以上引诗见《诗好·大雅·皇矣》，这首诗主要写文王伐崇、伐密的功绩。
书：指《尚书》，此段见《尚书·周书·泰誓上》。
一人：指商纣王。衡：同“横”。
', '齐宣王问道：“同邻国交往有原则吗？”
孟子答道：“有。只有仁的人能以大国服侍小国，所以商汤服侍葛伯，周文王服侍昆夷。只有聪明的人能以小国服侍大国，所以周太王古公亶父服侍獯鬻，勾践服侍吴王。以大国服侍小国的，是乐安天命的人；以小国服侍大国的，是敬畏天命的人。乐安天命者保有天下，敬畏天命者保有自己的国家。《诗经》说：‘敬畏上天的威严，于是保有这国家。’”
宣王说：“讲得太好了！（不过）我有个毛病，我喜欢勇武。”
孟子答道：“大王请不要喜欢小勇。按着剑、瞪着眼说：‘他哪敢抵挡我！’这是平常之人的小勇，只能对付一个人罢了。大王请把它（小勇）扩大开去！
“《诗经》上说：‘周文王勃然发怒，于是整肃部队，挡住侵犯莒国的敌人，增我周朝的威福，以此报答天下的期望。’这就是文王的勇武。文王一怒而安定了天下的百姓。
“《尚书》上说：‘上天降生万民，为他们设君主，立师长，要他们协助上天爱护百姓，天下有罪和无罪的，都有我在（处罚或安抚他们），天下谁敢超越它的本分？’有一个人横行天下，武王就感觉到耻辱。这就是武王的勇武。而武王也是一怒就安定了天下的百姓。如果现在大王也一怒就安定天下的百姓，那么百姓还唯恐大王不喜欢勇武呢！”', NULL, '', 'indent', 1557741863, '5cd8d0a57b968a00758a077f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642554, '孟子 · 第二卷 · 梁惠王下 · 第四节', NULL, 18, 271, 3, 2, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '齐宣王见孟子于雪宫。王曰：“贤者亦有此乐乎？”
孟子对曰：“有。人不得，则非其上矣。不得而非其上者，非也；为民上而不与民同乐者，亦非也。乐民之乐者，民亦乐其乐；忧民之忧者，民亦忧其忧。乐以天下，忧以天下，然而不王者，未之有也。
昔者齐景公问于晏子曰：‘吾欲观于转附、朝舞，遵海而南，放于琅邪。吾何修而可以比于先王观也？’
晏子对曰：‘善哉问也！天子适诸侯曰巡狩，巡狩者巡所守也；诸侯朝于天子曰述职，述职者述所职也。无非事者。春省耕而补不足，秋省敛而助不给。夏谚曰：“吾王不游，吾何以休？吾王不豫，吾何以助？一游一豫，为诸侯度。”今也不然：师行而粮食，饥者弗食，劳者弗息。睊睊胥谗，民乃作慝。方命虐民，饮食若流。流连荒亡，为诸侯忧。从流下而忘反谓之流，从流上而忘反谓之连，从兽无厌谓之荒，乐酒无厌谓之亡。先王无流连之乐，荒亡之行。惟君所行也。’
景公说，大戒于国，出舍于郊。于是始兴发补不足。召大师曰：‘为我作君臣相说之乐！’盖徵招角招是也。其诗曰：‘畜君何尤？’畜君者，好君也。”', '', '雪宫：齐宣王的郊外别墅。
非：非议。
以：有连及之意，作介词用。连及天下为乐为忧，即与天下同乐同忧的意思。
晏子：名婴，字平仲，春秋时齐景公的宰相。齐景公：原名姜杵臼，齐庄公的异母弟。
转附、朝（cháo）舞（wǔ）：二山名。
遵：循，顺。放：至。琅邪（lángyá）：山名。
修：方法，办法。观：游览。
适：往。巡：出去视察。狩：与“守”通用。
无非事者：天子诸侯离开国都是没有空行的，总是有事。
省：察看。敛：收获。
“游”和”休”，“豫”和“助”、“度”押韵。度：法度，榜样。夏王这样关心民事，实行恩惠的游览是诸侯的榜样。
师行而粮食：兴师动众，聚敛粮食。
睊睊（juàn）：眼睛表示出恨人的样子。胥：皆，相。谗：说坏话。慝（tè）：藏在心坎深处的念头。
方命：放弃先王的教训。方：放弃。饮食若流：饮食纵情享乐，像水流一样的没有穷尽。
从流下：顺水行舟。从流上：逆水行舟。忘反：纵情事乐，没有止境。反：同“返”。连：有用人力勉强拉着走的意思。从兽：跟着禽兽追赶。无厌：没有满足。荒：荒度政事。亡：亡国，亡身。
大戒于国：郑重地发布指示于国中——准备“兴发”“补不足”的事。出舍于郊：留宿郊外。
大（tài）师：即太师，宫廷乐长。
畜：限制。尤：过失。
', '齐宣王在他的郊外别墅雪宫接见孟子。齐宣王问道：“贤德的人也有在这样的别墅里居住游玩的快乐吗？”
孟子回答说：“是的。但是，人要是得不到这种快乐，就会非议他的君长，不能得到快乐而非议君长，这是不对的。可是作为老百姓的君长而不能与民同乐，也是不对的。（国君）以百姓的欢乐为欢乐的，老百姓也以他的欢乐为欢乐；（国君）以老百姓的忧愁为忧愁的，老百姓也以他的忧愁为忧愁。与百姓同忧同乐还不能称王于天下，这是从来没有过的。
“过去齐景公曾向晏子请教说：‘我想到转附、朝舞山去游览，然后沿着大海向南，一直到琅邪，我怎样做才能跟先王的出游相比呢？’
“晏子回答说：‘问得好啊！天子到诸侯那里叫做巡狩，所谓巡狩，也就是巡视所掌管的疆土。诸侯朝觐天子叫做述职，所谓述职，也就是报告自己的任职情况。都是有许多事务要做的。春天巡视耕田播种，对那些不能度春荒的人予以救济；秋天巡视收获，也要帮助生活艰难的人。夏朝时的谚语说：“我王不出来游历，我怎么能得到休息？我王不出来巡视，我怎么能得到赏赐？天子的游玩娱乐，可为诸侯做出表率。”现在可就不同了：国君出发时，带着大量的军队，军队一出动，要消耗大量的粮食，以至于让饥饿者不得食，劳动者不能得到休息。他们侧目而视，怨声载道。部下又违背命令，残害百姓，吃喝毫无节制，真是流连荒亡，连诸侯们都为此而忧虑。什么叫流连荒亡呢？沿着河流朝下游去，忘了回来叫做流，溯河而上忘了回来叫做连。无节制地追野兽，叫做荒。大量酗酒而无满足，叫做亡。古代圣贤君王没有流连的快乐，也没有荒亡的行为。至于大王您的行为，关键是看您怎样选择。’
“齐景公（听了晏子的话）非常高兴，在国中宣布禁令，自己离开宫殿，住在郊区。打开仓库，救济贫民，召集乐师，命令道：‘替我创作君臣相乐的音乐。’这大概就是《徵招》《角招》之类。其歌词中说：‘限制君王有什么不对呢？’限制君王的人是爱护君王啊！”
齐宣王住在别墅雪宫里，快乐无比，却不知“乐以天下，忧以天下”。孟子借晏子教训齐景公的话，来教训齐宣王，希望齐宣王能像齐景公那样，认识到荒淫无度的危害，从而关心自己的百姓，当一个好君王。“乐以天下，忧以天下”，显示了孟子政治学说中的民本主义思想。
“人君能与民同乐，则人皆有此乐；不然，则下之不得此乐者，必有非其君上之心。明人君当与民同乐，不可使人有不得者，非但当与贤者共之而已也。”
“乐民之乐而民乐其乐，则乐以天下矣；忧民之忧而民忧其忧，则忧以天下矣。”
“晏子能畜止其君之欲，宜为君之所尤，然其心则何过哉？孟子释之，以为臣能畜止其君之欲，乃是爱其君者也。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0ef", "shortContent": "齐宣王在自己的离宫里问孟子，贤德的人是否也有赏园游猎的乐趣，孟子便用以上两句回答，意在告诫齐宣王：贤德的人即便有赏园游猎的乐趣，但如果不能与民同乐，那他也不会去寻求这种乐趣。君王如果能做到乐以天下，忧以天下，就能实现王道理想，进而“王天下”。可见，与民同乐和与民同忧是孟子王道理想中的一个重要因素，也是仁政中的具体举措。\n\n在当时大部分君王、士人以及政治、军事改革家的思想里，扩充疆土、富国强兵是最终...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1557742000, '5cd8d12d30863b00705a7147', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642555, '孟子 · 第二卷 · 梁惠王下 · 第五节 ', NULL, 11, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '齐宣王问曰：“人皆谓我毁明堂，毁诸？已乎？”
孟子对曰：“夫明堂者，王者之堂也。王欲行王政，则勿毁之矣。”
王曰：“王政可得闻与？”
对曰：“昔者文王之治岐也，耕者九一，仕者世禄，关市讥而不征，泽梁无禁，罪人不孥。老而无妻曰鳏，老而无夫曰寡，老而无子曰独，幼而无父曰孤。此四者，天下之穷民而无告者。文王发政施仁，必先斯四者。诗云，‘哿矣富人，哀此茕独。’”
王曰：“善哉言乎！”
曰：“王如善之，则何为不行？”
王曰：“寡人有疾，寡人好货。”
对曰：“昔者公刘好货，《诗》云：‘乃积乃仓，乃裹糇粮，于橐于囊[8]。思戢用光。弓矢斯张，干戈戚扬，爰方启行。’故居者有积仓，行者有裹囊也，然后可以爰方启行。王如好货，与百姓同之，于王何有？”
王曰：“寡人有疾，寡人好色。”
对曰：“昔者太王好色，爱厥妃。《诗》云：‘古公亶父，来朝走马，率西水浒，至于岐下，爰及姜女，聿来胥宇。’当是时也，内无怨女，外无旷夫。王如好色，与百姓同之，于王何有？”
', '', '谓我：劝我。明堂：周天子出巡，东至泰山，在明堂祭天，朝见诸侯，发布政令，故孟子说为“王者之堂”。那时，这些典礼已经不行，明堂旧址还在。毁诸：毁之。已：止，即不毁。
岐：今陕西岐山一带。九一：指“井田”制度，其税率九分抽一，是孟子以为最理想的土地制度。
讥：察问，干涉。关市：只检查商贾和行旅的言行。不征：不征税。
泽：筑堤阪把水挡住的大池。梁：指渔梁，拦水为“梁”以捕鱼。无禁：任民捕鱼，不加禁止。不孥：只处分罪人本身，不加罚于其妻和子。
先斯四者：首先照顾这四种人。
“哿（gě）矣”二句：此两句诗引自《诗经·小雅·正月》。哿：与“可”同。茕（qióng）：孤单。
公刘：周朝的始祖后稷的曾孙，“公”是称号，“刘”是名。
乃积乃仓；以下七句诗引自《诗经·大雅·公刘》篇第一章。乃：助词，无义。积：露天堆积粮谷。仓：库房内堆积粮谷。糇（hóu）：干粮。橐（tuó）、囊：都是装裹粮食的口袋。“橐”无底，结束两端；“囊”有底，结束一端。
戢（jí）：安，和睦安定。用：犹“以”。光：大。
斯：犹“则”。干、戈、戚、扬：皆古兵器。干用以捍卫（即盾），戈用以刺击，戚和扬都是斧类，扬比戚大。爰：犹“于是”。方：开始。启行（háng）：开辟道路。
太王：即“大王”，公刘九世孙，文王的祖父，本号“古公”，名“亶”，后被尊为“太王”。
《诗》云：以下六句诗引自《诗经·大雅·绵》篇第二章。率：沿着。浒（hǔ）：水边。及：俱。姜女：姜氏女，周太王之妃。聿（yù）：助词，无义。胥：视察。宇：居处的地方。胥宇：考察地势，规建宫室。
怨女：过时没有结婚的女子。旷夫：过时没有结婚的男子。
', '齐宣王问孟子说：“别人都建议我把泰山周天子东巡时的明堂毁掉，是毁掉好还是保留好呢？”
孟子回答说：“明堂是王者施行王政的地方。大王若想要施行王者之政，就不用毁掉它了。’
齐宣王问：“关于王政能听你讲一讲吗？”
孟子说：“过去周文王治理岐山的时候，实行井田制，农家每家耕田百亩，八家共一井；做官的人可世代享受俸禄，关口和市场上货物只盘查有无违禁品，不征税，水中的鱼鳖也任百姓去捕捞，犯罪的人只需自己受罚，不牵连他的妻子儿女。老来没有妻子的叫鳏夫，老来没有丈夫的叫寡妇，老来没有子女的叫独老，年幼就没有父母的叫孤儿。这四种人，是天下没办法生活而又无处求助的。周文王实行仁政的时候，一定要先考虑他们。《诗经》上说：‘富人过得真潇洒，可怜的是这些孤独的穷人！’”
齐宣王感叹道：“说得好啊！”
孟子说：“大王既然认为好，为什么不去实行呢？”
齐宣王说：“我这个人有个毛病，我喜爱财物。”
孟子说：“过去公刘也喜爱财物。《诗经》上说：‘把粮食堆积起来，储存在仓库里，制成干粮，装进小袋和大囊，想着安定人民，让国家繁荣富强。拉满弓搭上箭，盾、枪刀、斧头一齐上，于是出发向远方。’所以说住下来要有储备的粮食，出行要带干粮，这以后才可以到远方去。大王如果喜爱财物，跟老百姓共同拥有，出行要带干粮，这以后才可以到远方去。大王如果喜爱财物，跟老百姓共同拥有，这对施行王政有什么影响呢？”
齐宣王说：“我还有一个毛病，我喜爱美女。”
孟子说：“过去周太王也喜欢美女，爱他的妻子。《诗经》上说：‘太王早晨骑着马，顺着水边到岐山下。带着他妻姜氏女，来看新居差不差。’这个时候，家中没有到了婚龄尚未出嫁的姑娘，也没有该娶未娶的小伙。大王如果喜爱美女，和老百姓一起来喜爱，这对施行王政有什么影响呢？”
', NULL, '', 'indent', 1557742120, '5cd8d1a530863b00705a78b9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642775, '孟子 · 第十三卷 · 尽心上 · 第二十八节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“柳下惠不以三公易其介。”
', '', '三公：周代指太师、太傅、太保，此指有高官厚禄者。介：耿介，有操守。
', '孟子说：“柳下惠不因为做高官而改变他的操守。”
', NULL, '', 'indent', 1558349006, '5ce214456e9ba1006821d72a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642556, '孟子 · 第二卷 · 梁惠王下 · 第六节', NULL, 8, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子谓齐宣王曰：“王之臣有托其妻子于其友而之楚游者，比其反也，则冻馁其妻子，则如之何？”
王曰：“弃之。”
曰：“士师不能治士，则如之何？”
王曰：“已之。”
曰：“四境之内不治，则如之何？”
王顾左右而言他。

', '', '比：及，等到。反：同“返”。
士师：狱官。治士：办案。
已：停止，罢免。
四境之内：国境以内。不治：政事坏乱。', '孟子对齐宣王说：“大王如果你的臣子把妻子儿女托付给朋友，自己到楚国去游历。等他回来的时候，妻子儿女又冻又饿，对这样的朋友该（拿他）怎么办呢？”
齐宣王说：“和他绝交。”
孟子接着说：“狱官不能管理好他的下属，又该（拿他）怎么办呢？”
齐宣王说：“罢免他。”
孟子又问他：“一个国家治理不好，这样的国君应该（拿他）怎么办呢？”
齐宣王左右张望，（假装没听到）转移了话题。', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b45f97f27182da3edfd88", "shortContent": " 在封建制度下君主至上，没有民主，君主把国家当成私人的家业，完全根据个人的意志和好恶处理政事，不顾百姓的死活，为所欲为，人们对此司空见惯，视为当然。孟子没有批判君权本身，也没有从政治理论或法学上规定君权的内涵和使用范围，但是他在论述君主应当采取的政纲和国策，他们应有的道德品质、行为举止的大量文字中对君权加以限定，规定了君主必须承担的职责，实际上否定了君主绝对权力的天然合理性，赞同推翻祸国殃民的统治...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557742174, '5cd8d1db0237d70069ec14c2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642557, '孟子 · 第二卷 · 梁惠王下 · 第七节 ', NULL, 6, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子谓齐宣王，曰：“所谓故国者，非谓有乔木之谓也，有世臣之谓也。王无亲臣矣，昔者所进，今日不知其亡也。”
王曰：“吾何以识其不才而舍之？”
曰：“国君进贤，如不得已，将使卑逾尊，疏逾戚，可不慎与？左右皆曰贤，未可也；诸大夫皆曰贤，未可也；国人皆曰贤，然后察之；见贤焉，然后用之。左右皆曰不可，勿听；诸大夫皆曰不可，勿听；国人皆曰不可，然后察之；见不可焉，然后去之。左右皆曰可杀，勿听；诸大夫皆曰可杀，勿听；国人皆曰可杀，然后察之，见可杀焉，然后杀之。故曰，国人杀之也。如此，然后可以为民父母。”
', '', '故国：有历史的旧国。乔木：久经年代的高大树木。世臣：世世代代和国家有密切关系的大官僚家族。
亲臣：可以亲近信任的臣僚。进：进用。亡：去位，去国，被扔弃。
逾：越过。戚：亲近。
', '孟子拜见齐宣王，对他说：“我们平时所说历史悠久的国家，并不是说国中有高大久远的树木，而是说有历代能为国家建立功勋、与国家休戚与共的大臣。可是大王现在连真正亲近的臣子都没有，过去提拔的，现今都不知到什么地方去了。”
齐宣王说：“我应该如何识别一个人没有才能而不用他呢？”
孟子说：“国君选拔贤才，在不得已的情况下，会将原本地位低的人，提拔到地位高的人之上，将原本关系疏远的提拔到关系亲近的人之上，这能够不慎重吗？左右近臣都说贤能的人，还不能任用。朝中大夫都说他贤能，也不行。全国人都说他贤能，再去考察他是否真的贤能。若真的贤能，就任用他。（那么，）左右近臣都说某人不行，不要轻易听信。朝中大夫都说他不行，也不要听信。国内的人都说他不行，就考察一下实际情况。若果他真的不行，就罢免掉。左右近臣都说这人该杀，不要听信。朝中大夫都说他该杀，也不要听从。国内的人都说他该杀，就去考察实情，发现真的该杀，再把他杀掉。所以说，这是国全国人民杀了他呀。能够明白这样做，就能成为百姓的父母（君王）了。”
', NULL, '', 'indent', 1557742230, '5cd8d21443e78c0065ca66fd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642558, '孟子 · 第二卷 · 梁惠王下 · 第八节 ', NULL, 12, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '齐宣王问曰：“汤放桀，武王伐纣，有诸？”
孟子对曰：“于传有之。”
曰：“臣弑其君，可乎？”
曰：“贼仁者谓之‘贼’，贼义者谓之‘残’。残贼之人谓之‘一夫’。闻诛一夫纣矣，未闻弑君也。”
', '', '放：流放。
贼：害。残：伤。贼仁者：凶暴淫虐，绝灭人性。贼义者：颠倒是非，丧失理性。
一夫：失掉人民同情的孤立者。
', '齐宣王问孟子：“商汤流放夏桀，周武王讨伐商纣王，有这些事吗？
孟子答道：“历史记载中有这回事。”
齐宣王说：“臣下弑杀他的君王，行吗？”
孟子说：“破坏仁的叫做贼，破坏义的叫做残。既害仁又害义的叫做独夫民贼。我只听说周武王诛杀独夫民贼纣，没听说他是弑君。”
', NULL, '', 'indent', 1557742289, '5cd8d24f17b54d0075b21a47', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642559, '孟子 · 第二卷 · 梁惠王下 · 第九节 ', NULL, 10, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子见齐宣王，曰：“为巨室，则必使工师求大木。工师得大木，则王喜，以为能胜其任也。匠人斫而小之，则王怒，以为不胜其任矣。夫人幼而学之，壮而欲行之，王曰：‘姑舍女所学而从我’，则何如？今有璞玉于此，虽万镒，必使玉人雕琢之。至于治国家，则曰：‘姑舍女所学而从我’，则何以异于教玉人雕琢玉哉？”
', '', '工师：管理工匠的长官。
姑：姑且。女：通“汝”，你。
璞玉：未经加工的玉石。镒（yì）：古代重量单位，二十两为一镒。
', '孟子见到齐宣王，说：“大王想建造巨大的宫殿，就一定得派工师去找大木料。工师找到大木料，大王就高兴，认为他能胜任。如若工匠把这木料砍小了，大王就会动怒，以为他不能胜任。有人从小学习一种本事，长大后便要来实践它，大王却说‘姑且扔掉你所学的，听从我’，这可怎么行呢？假如现在这里有一块璞玉，就算它价值二十万两，您一定会让玉匠雕琢它。至于治理国家，却说‘姑且扔掉你所学的，听从我’，可这同教导玉匠雕琢玉石又有什么区别呢？”', NULL, '', 'indent', 1557742341, '5cd8d282c8959c00687f70c6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642571, '孟子 · 第三卷 · 公孙丑上 · 第五节 ', NULL, 8, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“尊贤使能，俊杰在位，则天下之士皆悦而愿立于其朝矣。市廛而不征，法而不廛，则天下之商皆悦而愿藏于其市矣。关讥而不征，则天下之旅皆悦而愿出于其路矣。耕者助而不税，则天下之农皆悦而愿耕于其野矣。廛无夫里之布，则天下之民皆悦而愿为之氓矣。信能行此五者，则邻国之民仰之若父母矣。率其子弟，攻其父母，自生民以来，未有能济者也。如此，则无敌于天下。无敌于天下者，天吏也。然而不王者，未之有也。”', '', '廛（chán）：公家所建供商人租用的货仓，这里指抽取货仓税。征：抽取货物税。
关，讥而不征：关口，稽查而不征税。讥，稽查。
助：按古代井田制中央百亩为公田，由八家助耕。
廛（chán）：这里指民居。夫里之布：指夫布和里布。因故不能服徭役者，需出钱雇役，雇役钱叫做夫布。宅有空地而不种植桑麻，由国家抽取惩罚性的地税，叫做里布。布：货币。
氓（méng）：流动人口，侨民。
天吏：替天行道的官吏。
', '孟子说：“尊重有德行的人，任用有才能的人，在位为官的人优异杰出，那么，天下的士人都会高兴，而乐意在他的朝廷做官了；做生意的，只抽取货仓税而不征货物税，或竟连货仓税也不收，那么，天下的商人都会高兴，而乐意把货物存放在他的市场上了。关卡，只稽查而不征税，那么天下旅行的人都会高兴，而乐意从他的道路经过了。种田的人，只需助耕公田而不征地税，那么天下的农夫都会高兴，而乐意在他的田野上耕种了。人们居住的地方，不收雇役钱和惩罚性地税，那么，天下的老百姓都会高兴，而乐意到那里侨居了。一个君王如果能实行这五项措施，那么邻国的老百姓就会仰望他像仰望父母一样了。率领子女，来攻打他们的父母，这种事情自从有人类以来，没有能够成功的。这样做，就能无敌于天下。无敌于天下的人，就是天所派遣的官吏。如果这样还不能统一天下的，从来没有过的呀。”
这段话，孟子从五个方面详细谈了他的“仁政”构想，合起来看，就是任贤使能，宽厚民生，老百姓就有归属感。如果有人要毁掉这样的政权，破坏老百姓的好日子，老百姓就会拼命。这就是孟子反复讲的“仁者无敌”的意思。
这五个方面，除第一条是讲用人问题外，其余四条全讲赋税问题。而且《孟子》一书中多次讲要减轻农民、商人的赋税，他甚至说，要是谁的税率超过了十分抽一，那他就是夏桀那样的暴君。这些也就是孟子的施政纲领。由此可见，孟子仁政思想的核心，是让老百姓丰衣足食，“有恒产”，使老百姓（包括农民、商人）都变成有产者。这种思想对现在的当政者也有启示的作用。
“此章言能行王政，则寇戎为父子；不行王政，则赤子为仇雠。”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b464982772d459481615a", "shortContent": "在这一部分孟子首先提出了实施仁政的五项基本政策：第一，尊重贤才，重用能人；第二，开放市场，不征重税，政府为客商提供仓库，收购滞销商品，鼓励贸易；第三，为旅游和交通提供方便，在关卡对行人只加以检查而不征税；第四，实行井田制，农民在完成公田的劳务以后就不需交税；第五，对居民不摊派各种徭役费和住宅税。所有这些政策的主要目的是发展经济，减轻人民负担，藏富于民，让百姓过上好日子。由此可见，孟子讲仁政，并不只...", "authors": ["魏薪", "徐克谦"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557743164, '5cd8d5b917b54d0075b24bd3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (950079, '檐前铁', NULL, NULL, 149, 1, 0, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'ci', '词', '', '', '悄无人，宿雨厌厌，空庭乍歇。听檐前铁马戛叮当，敲破梦魂残结。丁年事，天涯恨，又早在心头咽。谁怜我、绮帘前，镇日鞋儿双跌。今番也、石人应下千行血。拟展青天，写作断肠文，难尽说。', '', '', '', NULL, '', 'indent', 1686251278, '6481b6879beb5c6c1af2471a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642560, '孟子 · 第二卷 · 梁惠王下 · 第十节 ', NULL, 8, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '齐人伐燕，胜之。宣王问曰：“或谓寡人勿取，或谓寡人取之。以万乘之国伐万乘之国，五旬而举之，人力不至于此。不取，必有天殃。取之，何如？”
孟子对曰：“取之而燕民悦，则取之。古之人有行之者，武王是也。取之而燕民不悦，则勿取，古之人有行之者，文王是也。以万乘之国伐万乘之国，箪食壶浆以迎王师，岂有他哉？避水火也。如水益深，如火益热，亦运而已矣。”
', '', '武王是也：指周武王占领殷地，诛纣王而享有天下。
文王是也：据说，周文王三分天下有其二，但仍臣服于商。
箪（dān）：盛食物的竹器。
水火：比喻害民的虐政。
运：回转。
', '齐国攻打燕国，打了胜仗。齐宣王问孟子：“有人劝我占领燕国，有人劝我不要占领。万乘的大国去打另一万乘的大国，五十天就拿了下来，单单依靠人力是不能取得这样的胜利。不占领的话，上天一定会降下祸灾的，你说说占领下来会怎样呢？”
呢？”
孟子回答说：“占领之后如果燕国的老百姓高兴，就占领它。古代有人这样做，周武王就是。占领之后如果燕国老百姓不高兴，就别占领。古代也有人这样做，周文王就是这样。万乘的大国去攻打万乘的大国，老百姓提着篮子带着水壶把食物和水放在路边去迎接大王的军队，难道还有别的原因吗？是为了避免水深火热的处境呀。如果水更深了，火更热了，老百姓也就只能指望别人来营救了。”
', NULL, '', 'indent', 1557742417, '5cd8d2cf7b968a00758a2867', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642561, '孟子 · 第二卷 · 梁惠王下 · 第十一节', NULL, 7, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '齐人伐燕，取之。诸侯将谋救燕。宣王曰：“诸侯多谋伐寡人者，何以待之？”
孟子对曰：“臣闻七十里为政于天下者，汤是也。未闻以千里畏人者也。书曰：‘汤一征，自葛始。’天下信之。‘东面而征，西夷怨；南面而征，北狄怨。曰，奚为后我？’民望之，若大旱之望云霓也。归市者不止，耕者不变。诛其君而吊其民，若时雨降，民大悦。书曰：‘徯我后，后来其苏。’
今燕虐其民，王往而征之。民以为将拯己于水火之中也，箪食壶浆，以迎王师。若杀其父兄，系累其子弟，毁其宗庙，迁其重器，如之何其可也？天下固畏齐之强也。今又倍地而不行仁政，是动天下之兵也。王速出令，反其旄倪，止其重器，谋于燕众，置君而后去之，则犹可及止也。”
', '', '一征：即“始征”，初次出战。葛：古国名，在今河南宁陵。
面：向，作动词用。夷、狄：距王朝较远的部族，包括在所谓“四海”或“天下”之中。
徯（xī）：等待。后：君。苏：更生，重新得到生命。
系累：捆绑，拘囚。
固：本来。倍地：齐国如果吞并燕国，就增加了一倍的土地。
反：同“返”，遣返。旄（mào）：通“耄”，指老人。倪：幼儿，指小孩。止：停止，不移动。
', '齐国攻打燕国并占领了燕国。众诸侯正谋划救助燕国。齐宣王问：“诸侯中不少人正谋划攻打我（齐国），怎么办呢？”
孟子回答说：“我听说有以七十里的地盘统一天下的，商汤就是这样，但没听说有上千里的土地还惧怕别的国家。《尚书》中说：‘商汤最初征讨，是从葛国开始的。’天下人都信任他。向东方征讨，西方的部族就埋怨；向南方征讨，北方的部族就埋怨，说：‘为什么把解放我们摆在后面呢？’老百姓盼望他来，就像大旱时盼望云彩。商人能继续做生意，耕田者也没被扰动。诛讨不义的君王而安抚老百姓，就像及时雨从天而降，老百姓非常喜欢。《尚书》里说：‘等待我们的君王，他来了我们才得解放！’而今燕王残害他的老百姓，大王您去征讨他，老百姓认为您将拯救他们出水深火热的困境，所以用饭筐装着饭，用酒壶盛着酒浆来迎接您的军队。如果您杀死他们的壮年人，拘禁他们的年轻人，毁坏燕国的宗庙，拉走他们的宝器，这样做的话怎么可以呢？天下本来就畏惧齐国的强大，现在疆域增加了一倍又不实行仁政，这就等于让天下处于战争状态。大王应该赶快发布命令，送还他们的老人孩子，不要运走他们的宝器，与燕国的民众商量，为他们设立新君然后撤离，那么，还是可以及时制止各国兴兵的。”
', NULL, '', 'indent', 1557742475, '5cd8d30943e78c0065ca7471', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642562, '孟子 · 第二卷 · 梁惠王下 · 第十二节 ', NULL, 8, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '邹与鲁哄。穆公问曰：“吾有司死者三十三人，而民莫之死也。诛之，则不可胜诛；不诛，则疾视其长上之死而不救，如之何则可也？”
孟子对曰：“凶年饥岁，君之民老弱转乎沟壑，壮者散而之四方者，几千人矣；而君之仓廪实，府库充，有司莫以告，是上慢而残下也。曾子曰：‘戒之戒之！出乎尔者，反乎尔者也。’夫民今而后得反之也。君无尤焉。君行仁政，斯民亲其上、死其长矣。”', '', '邹：国都在今山东邹市。哄：吵闹，这里指交战。
穆公：指邹穆公。
有司：官吏。疾：恨。长上：官长。
转乎沟壑：谓尸体被扔弃于沟壑，不及埋葬，可见死者甚多；壑，坑。几：接近。仓廪：用来储藏粮谷。府库：用来储藏货财。上：指有司和君。慢：高高在上，不关心人民，不理政事。残：伤害。下：指人民。
曾子：名参，孔子弟子。戒之：当心啊！出乎尔者，反乎尔者：从你发出的就是回答你的。反：同“返”，回答。
尤：责备。
', '邹国与鲁国交战。邹穆公问孟子：“我国将吏有三十三人牺牲在战场上，但却没有一个老百姓为之死难的。杀掉他们吧，却不能杀那么多；不杀吧，却恨他们眼看着长官赴死而不救，到底该怎么办才好呢？”
孟子回答说：“遇到灾荒，收成不好的时候，您的老百姓中老弱病残的大量饿死，尸体填满沟壑，壮年人离开家乡逃荒到远方，差不多有千人之多；但您的仓库里粮食和财物却很多，官员们没把实情上报，这是因居上位者的冷漠而残害了百姓啊。曾子说：‘小心呀，小心呀！怎样对待他人，他人以同样手段回敬你。’老百姓现在可以用同样手段回敬了。大王不要责怪他们。您能实行仁政，那样百姓就会亲近在上位的人，而为他们去死了。”
', NULL, '', 'indent', 1557742518, '5cd8d3347b968a00758a2d7b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642563, '孟子 · 第二卷 · 梁惠王下 · 第十三节 ', NULL, 7, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '滕文公问曰：“滕，小国也，间于齐、楚。事齐乎？事楚乎？”
孟子对曰：“是谋非吾所能及也。无已，则有一焉：凿斯池也，筑斯城也，与民守之，效死而民弗去，则是可为也。”

', '', '滕文公：战国时滕国的国君，滕定公儿子。滕：滕国，滕国在今山东滕县。
事：侍奉。
一：一种主张或想法。', '滕文公问道：“我们滕国是个小国，又处在齐、楚两个大国之间。是亲近齐国好呢？还是亲近楚国好呢？”
孟子回答说：“（为滕国）谋划这种事情不是我所能够办得到的呀。在不得已的情况下，有这样一种方法：把护城河挖深，把城墙加固，与老百姓共同来防守。百姓愿意为献出生命，而不逃向其他地方，做到这样这就有希望了。”
', NULL, '', 'indent', 1557742568, '5cd8d364c8959c00687f7b10', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642564, '孟子 · 第二卷 · 梁惠王下 · 第十四节 ', NULL, 8, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '滕文公问曰：“齐人将筑薛，吾甚恐。如之何则可？”
孟子对曰：“昔者大王居邠，狄人侵之，去之岐山之下居焉。非择而取之，不得已也。苟为善，后世子孙必有王者矣。君子创业垂统，为可继也。若夫成功，则天也。君如彼何哉？强为善而已矣。”', '', '薛：古国名，任姓诸侯国，邻近滕国，为齐所灭。
大：同“太。”邠（bīn）：同“豳”，在今陕西旬邑西。
狄人：即獯鬻（xūn yù），又称猃狁，中国古代北方的少数民族。岐山：在今陕西岐山县东北部。
垂统：把皇位和基业传给子孙后代。
', '滕文公问道：“齐国要修筑薛城，我很害怕，怎么办才好呢？”
孟子答道：“从前周太王住在邠，狄人侵犯他，他便离开，迁到岐山下去住。这并不是主动选择住在那里，是不得已的。可见如果实行仁政，后代子孙一定有成为天下之王的。君子创立基业，奠定传统，正是为了可以被继承下去。如果能取得成功，那就是天意呀。您能拿齐国怎样呢？只有努力实行仁政而已。”
', NULL, '', 'indent', 1557742612, '5cd8d392c8959c00687f7d3c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642637, '孟子 · 第八卷 · 离娄下 · 第五节 ', NULL, 11, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“君仁，莫不仁；君义，莫不义。”
', '', '', '孟子说：“君主如果心存仁爱，就没有人不仁爱；君主如果坚守道义，就没有人不坚守道义。”

', NULL, '', 'indent', 1557915256, '5cdb75f6c8959c0068c96d10', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642638, '孟子 · 第八卷 · 离娄下 · 第六节 ', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“非礼之礼，非义之义，大人弗为。”

', '', '', '孟子说：“不合礼制的礼，不合正义的义，有德行的人是不去做的。”
', NULL, '', 'indent', 1557915280, '5cdb760f6e9ba10068cc9285', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642565, '孟子 · 第二卷 · 梁惠王下 · 第十五节 ', NULL, 6, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '滕文公问曰：“滕，小国也。竭力以事大国，则不得免焉。如之何则可？”
孟子对曰：“昔者大王居邠，狄人侵之。事之以皮币，不得免焉；事之以犬马，不得免焉；事之以珠玉，不得免焉。乃属其耆老而告之曰：‘狄人之所欲者，吾土地也。吾闻之也：君子不以其所以养人者害人。二三子何患乎无君？我将去之。’去邠，逾梁山，邑于岐山之下居焉。邠人曰：‘仁人也，不可失也。’从之者如归市。或曰：‘世守也，非身之所能为也。效死勿去。’君请择于斯二者。”', '', '币：缯帛。
属：召集。耆（qí）老：指老人。耆，六十岁的人。老，七十岁的人。
梁山：在今陕西干县西北。
归市：拥向集市。
', '滕文公问道：“滕国，是个小国，全心全力来服侍大国，却不能躲过祸患，要怎么办才好呢？”
孟子答道：“从前周太王住在邠，狄人侵犯他。太王进献兽皮和丝帛服侍他，不能免遭侵犯；进献狗和马服侍他，不能免遭侵犯；进献珍珠美玉服侍他，不能免遭侵犯。于是召集邠地的父老，对他们说：‘狄人想要的，是我们的土地。我听说过：君子不把那些生养人的东西用来害人。你们何必担心没有君主呢？我准备离开这里。’于是他离开邠地，越过梁山，在岐山下建造城邑住了下来。邠地的老百姓说：‘他是有仁德的人啊，不能失去他。’跟随着他来的人多得就像赶集一样。
“也有人说：‘（土地）是必须世世代代守护的，不是自己可以决定放弃的。宁死而不能离开。’
“请您在这两种情形中择取一种吧。”
', NULL, '', 'indent', 1557742685, '5cd8d3db7b968a00758a36e3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642566, '孟子 · 第二卷 · 梁惠王下 · 第十六节 ', NULL, 11, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '鲁平公将出。嬖人臧仓者请曰：“他日君出，则必命有司所之。今乘舆已驾矣，有司未知所之，敢请。”
公曰：“将见孟子。”
曰：“何哉，君所为轻身以先于匹夫者？以为贤乎？礼义由贤者出；而孟子之后丧逾前丧。君无见焉！”
公曰：“诺。”
乐正子入见，曰：“君奚为不见孟轲也？”
曰：“或告寡人曰：‘孟子之后丧逾前丧’，是以不往见也。”
曰：“何哉，君所谓逾者？前以士，后以大夫；前以三鼎，而后以五鼎与？”
曰：“否。谓棺椁衣衾之美也。”
曰：“非所谓逾也，贫富不同也。”
乐正子见孟子，曰：“克告于君，君为来见也。嬖人有臧仓者沮君，君是以不果来也。”
曰：“行，或使之；止，或尼之。行止，非人所能也。吾之不遇鲁侯，天也。臧氏之子焉能使予不遇哉？”
', '', '鲁平公：战国时鲁国国君姬叔，景公的儿子，前316年至前297年在位。
嬖（bì）人：指受宠的姬妾或侍臣。
乐正子：名克，孟子弟子。
后丧、前丧：孟子先丧父，后丧母。后丧指母亲的丧事，前丧指父亲的丧事。
三鼎：用三个鼎盛供品。五鼎：用五个鼎盛供品。办丧事时用三鼎是士礼，用五鼎是卿大夫之礼。
棺：内棺。椁：外棺。衣衾（qīn）：装殓死者的衣被。
沮（jǔ）：通“阻”。
尼（nǐ）：阻止。
', '鲁平公准备要外出。他所宠幸的近臣臧仓请示说：“往日您外出，一定是先通知有关官员要去哪里。现在您的乘舆已准备好了，那些官员人还不知道要到哪里去，因此来请示。”
鲁平公说：“我要去见孟子。”
臧仓说：“您降低自己的身份主动去见一个普通人，是为什么呢？您以为他是贤人吗？礼义是由贤人做出表率，然而孟子为母亲办丧事比为父亲办丧事还隆重。您别去见他了吧！”
鲁平公说：“好吧。”
乐正子进宫见到鲁平公，说：“您为什么不见孟轲了？”
鲁平公说：“有人告诉我说，‘孟子为母亲办丧事的隆重超过了父亲的丧事’，所以我不去见他了。”
乐正子说：“您所说的超过，是指什么呢？是指先前为父亲办丧事用士礼，后来为母亲办丧事用大夫之礼；先前办丧事用三个鼎，后来用五个鼎吗？”
鲁平公说：“不是的，是指棺椁衣物的华美。”
乐正子说：“这不叫超过，这是前后家境贫富不同而已。”
乐正子去见孟子，说：“我告诉过国君，他本来打算来见您的。有个受宠的近臣臧仓阻止了他，因此他终于没来。”
孟子说：“来，也许是有人促成的；不来，也许是有人阻止他。不过来或不来，并不是人力所能主宰。我不能被鲁君信用，是天意啊。姓臧的家伙怎能使我见不到鲁君呢？”
', NULL, '', 'indent', 1557742761, '5cd8d426c8959c00687f855f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642567, '孟子 · 第三卷 · 公孙丑上 · 第一节 ', NULL, 12, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '公孙丑问曰：“夫子当路于齐，管仲、晏子之功，可复许乎？”
孟子曰：“子诚齐人也，知管仲、晏子而已矣。或问乎曾西曰；‘吾子与子路孰贤？’曾西蹙然曰：‘吾先子之所畏也。’曰：‘然则吾子与管仲孰贤？’曾西艴然不悦，曰：‘尔何曾比予于管仲？管仲得君，如彼其专也；行乎国政，如彼其久也；功烈，如彼其卑也。尔何曾比予于是？’”
曰：“管仲，曾西之所不为也，而子为我愿之乎？”
曰：“管仲以其君霸，晏子以其君显。管仲、晏子犹不足为与？”
曰：“以齐王，由反手也。”
曰：“若是，则弟子之惑滋甚。且以文王之德，百年而后崩，犹未洽于天下；武王、周公继之，然后大行。今言王若易然，则文王不足法与？”
曰：“文王何可当也？由汤至于武丁，贤圣之君六七作。天下归殷久矣，久则难变也。武丁朝诸侯有天下，犹运之掌也。纣之去武丁未久也，其故家遗俗，流风善政，犹有存者；又有微子、微仲、王子比干、箕子、胶鬲皆贤人也，相与辅相之，故久而后失之也。尺地莫非其有也，一民莫非其臣也，然而文王犹方百里起，是以难也。齐人有言曰：‘虽有智慧，不如乘势；虽有镃基，不如待时。’今时则易然也。夏后、殷、周之盛，地未有过千里者也，而齐有其地矣；鸡鸣狗吠相闻，而达乎四境，而齐有其民矣。地不改辟矣，民不改聚矣，行仁政而王，莫之能御也。且王者之不作，未有疏于此时者也；民之憔悴于虐政，未有甚于此时者也。饥者易为食，渴者易为饮。孔子曰：‘德之流行，速于置邮而传命。’当今之时，万乘之国行仁政，民之悦之，犹解倒悬也。故事半古之人，功必倍之，惟此时为然。”', '', '公孙丑：战国时期齐国人，孟子弟子。
当路：指身居要职。
曾西：曾申，字子西，曾参之子。
蹵（cù）然：不安的样子。
先子：指自己已死的父亲。
艴（fú）然：生气的样子。
功烈：功业，霸业。
由：通“犹”。
百年而后崩：古代传说周文王九十七岁死，这里说“百年”，是举其成数。崩：古代称天子、王后死。洽：达到完满。武王：姓姬，名发，周文王的儿子。周公：名旦，武王的弟弟。大行：指大力推行王道。
武丁：即殷高宗，盘庚的弟弟小乙的儿子，曾用兵征伐四方的部族。
微子：名启，据《左传》《史记》等书载，为纣的庶兄，《孟子·告子上》则以为是纣的叔父。微仲：微子之弟，名衍。王子比干：纣的叔父，屡次向纣进谏，为纣所杀。箕子：纣的叔父，比干被杀后，佯狂为奴，被纣囚禁。胶鬲（jiāo gé）：纣王之臣。
镃（zī）基：锄头。
置邮：置、邮都是名词，相当于后代的驿站。
倒悬：倒转吊起，比喻困苦。

', '公孙丑问道：“先生如果做了齐国的相，管仲、晏子的功业，有希望再度出现吗？”
孟子说：“你果然是齐国人，就知道管仲、晏子。曾有人问曾西说：‘您和子路相比，谁更贤能些？’曾西不安地说：‘他是先父所敬畏的人呀。’那人又问：‘那么您和管仲相比，谁更贤能些？’曾西变了脸色，很不高兴地说：‘你怎么能拿我和管仲相比？管仲得到他的君王的信任是那样专一，行使国家的政权是那样长久，功业却是那样卑微，你怎么能拿我和他相比？’”孟子又接着说：“管仲，是曾西所不屑的，你以为我愿意学他吗？”
公孙丑说：“管仲辅佐其君而称霸，晏子辅佐其君而扬名。管仲、晏子还不值得学吗？”
孟子说：“以齐国的实力推行王道来统一天下，易如反掌。”
公孙丑说：“您这么说，我更糊涂了。以文王的贤德，活了将近一百岁才逝世，还没有能统一天下，直到武王，周公继承他的事业，然后大大地推行王道，才统一天下。现在您把统一天下说得这么容易，那么，连周文王都不值得学习了吗？”
孟子说：“文王，怎么是能与他相比呢？从汤到武丁，贤圣的君王有六七个，天下归附于殷商久了，久了就难以改变。武丁使诸侯来朝贡，统治天下，就像玩弄于手掌之上那么轻而易举。纣离武丁不久，先王时的世家贵族、美好习俗、醇厚民风、仁惠政教，还有所留存，又有微子、微仲、王子比干、箕子、胶鬲——都是些贤人——在共同辅佐他，所以能统治很久以后才失去政权。当时没有一尺土地不属于纣王所有，没有一个百姓不归纣王统治，在那种情况下，文王还只能从方圆百里的小地方兴起，所以是很困难的。齐国人有句话说：‘虽然有智慧，不如趁形势；虽然有农具，不如等农时。’现在的时势就很利于用王道统一天下：夏、商、周三代兴盛的时候，没有哪一国的国土有超过方圆千里的，而现在的齐国却超过了；鸡鸣狗吠的声音互相听得见，一直到四周的边境，现在齐国有了这么多的百姓。疆土不必再扩张，百姓不必再增加，只需推行仁政就能统一天下，谁也阻挡不住啊。况且仁义的君王没有出现，这是从来不曾像现在这样稀缺的：老百姓被暴政所残害，从来不曾像现在这样严重的。饥饿的人，可以很容易让他吃饱；口渴的人，可以很容易让他喝足。孔子说：‘贤德的推广，比驿站传递政令还要迅速。’现在这个时候，拥有万辆兵车的国家推行起仁政来，老百姓必然爱戴它，就像被倒挂吊着的人得到解救一样。所以只要做到古人一半的事情，功业就会比古人多出一倍，只有现在这个时候才能如此。”

', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b4628a5f1e74f95e9752e", "shortContent": " 《孟子》散文以气势见长，苏辙《上枢密韩太尉书》中说：“文不可以学而能，气可以养而致。孟子曰：‘我善养吾浩然之气’，今观其文章，宽厚宏博，充乎天地之间，称其气之大小。……其气充乎其中而溢乎其貌，动乎其言而见乎其文，而不自知也。”明代王文禄《文脉》也说：“或曰：后世无《孟子》七篇，何也？曰：孰养浩然之气也？故曰文以气为主，有塞天地之气，而后有垂世之文。”孟子文章中的气势跟他本人在道德修养上善于培养“...", "authors": ["徐克谦"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557742863, '5cd8d48d17b54d0075b23bb8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642568, '孟子 · 第三卷 · 公孙丑上 · 第二节 ', NULL, 30, 271, 5, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '公孙丑问曰：“夫子加齐之卿相，得行道焉，虽由此霸王不异矣。如此，则动心否乎？”
孟子曰：“否。我四十不动心。”
曰：“若是，则夫子过孟贲远矣。”
曰：“是不难，告子先我不动心。”
曰：“不动心有道乎？”
曰：“有。北宫黝之养勇也，不肤挠，不目逃，思以一豪挫于人，若挞之于市朝。不受于褐宽博，亦不受于万乘之君。视刺万乘之君，若刺褐夫。无严诸侯。恶声至，必反之。孟施舍之所养勇也，曰：‘视不胜犹胜也。量敌而后进，虑胜而后会，是畏三军者也。舍岂能为必胜哉？能无惧而已矣。’孟施舍似曾子，北宫黝似子夏。夫二子之勇，未知其孰贤，然而孟施舍守约也。昔者曾子谓子襄曰：‘子好勇乎？吾尝闻大勇于夫子矣：自反而不缩，虽褐宽博，吾不惴焉；自反而缩，虽千万人，吾往矣。’孟施舍之守气，又不如曾子之守约也。”
曰：“敢问夫子之不动心，与告子之不动心，可得闻与？”
“告子曰：‘不得于言，勿求于心；不得于心，勿求于气。’不得于心，勿求于气，可；不得于言，勿求于心，不可。夫志，气之帅也；气，体之充也。夫志至焉，气次焉。故曰：‘持其志，无暴其气。’”
“既曰‘志至焉，气次焉’，又曰‘持其志无暴其气’者，何也？”
曰：“志壹则动气，气壹则动志也。今夫蹶者趋者，是气也，而反动其心。”
“敢问夫子恶乎长？”
曰：“我知言，我善养吾浩然之气。”
“敢问何谓浩然之气？”
曰：“难言也。其为气也，至大至刚，以直养而无害，则塞于天地之间。其为气也，配义与道；无是，馁也。是集义所生者，非义袭而取之也。行有不慊于心，则馁矣。我故曰，告子未尝知义，以其外之也。必有事焉而勿正，心勿忘，勿助长也。无若宋人然：宋人有闵其苗之不长而揠之者，芒芒然归。谓其人曰：‘今日病矣，予助苗长矣。’其子趋而往视之，苗则槁矣。天下之不助苗长者寡矣。以为无益而舍之者，不耘苗者也；助之长者，揠苗者也。非徒无益，而又害之。”
“何谓知言？”
曰：“诐辞知其所蔽，淫辞知其所陷，邪辞知其所离，遁辞知其所穷。生于其心，害于其政；发于其政，害于其事。圣人复起，必从吾言矣。”
“宰我、子贡善为说辞，冉牛、闵子、颜渊善言德行。孔子兼之，曰：‘我于辞命则不能也。’然则夫子既圣矣乎？”
曰：“恶！是何言也？昔者子贡、问于孔子曰：‘夫子圣矣乎？’孔子曰：‘圣则吾不能，我学不厌而教不倦也。’子贡曰：‘学不厌，智也；教不倦，仁也。仁且智，夫子既圣矣！’夫圣，孔子不居，是何言也？”
“昔者窃闻之：子夏、子游、子张皆有圣人之一体，冉牛、闵子、颜渊则具体而微。敢问所安。”
曰：“姑舍是。”
曰：“伯夷、伊尹何如？”
曰：“不同道。非其君不事，非其民不使；治则进，乱则退，伯夷也。何事非君，何使非民；治亦进，乱亦进，伊尹也。可以仕则仕，可以止则止，可以久则久，可以速则速，孔子也。皆古圣人也，吾未能有行焉；乃所愿，则学孔子也。”
“伯夷、伊尹于孔子，若是班乎？”
曰：“否。自有生民以来，未有孔子也。”
曰：“然则有同与？”
曰：“有。得百里之地而君之，皆能以朝诸侯有天下。行一不义、杀一不辜而得天下，皆不为也。是则同。”
曰：“敢问其所以异？”
曰：“宰我、子贡、有若智足以知圣人。污，不至阿其所好。宰我曰：‘以予观于夫子，贤于尧舜远矣。’子贡曰：‘见其礼而知其政，闻其乐而知其德。由百世之后，等百世之王，莫之能违也。自生民以来，未有夫子也。’有若曰：‘岂惟民哉？麒麟之于走兽，凤凰之于飞鸟，太山之于丘垤，河海之于行潦，类也。圣人之于民，亦类也。出于其类，拔乎其萃，自生民以来，未有盛于孔子也。’”
', '', '加：任。
孟贲：古代勇士，卫国人。
告子：名不害，与孟子同时而年长于孟子，曾受教于墨子。
北宫黝（yǒu）：姓北宫，名黝，战国时期齐国人。
桡（náo）：同“挠”，退却。
褐（hè）宽博：指卑贱者。褐，粗布衣服；宽博，宽大的衣服。褐、宽博，都是贱者之服。
孟施舍：古代勇士。
会：指交战。
曾子：即曾参，孔子弟子。子夏：姓卜名商，孔子弟子。
子襄：曾子弟子。
缩：直。
暴：乱。
蹶（jué）：跌倒。
浩然：形容盛大流行的样子。
义袭：义，偶然从外进入内心。袭，偷袭。
慊（qiàn）：不满意，怨恨。
正：止，中止。
芒芒然：疲倦的样子。
病：疲倦。
耘：除草。
诐（bì）：偏颇。蔽：遮蔽。淫：过分。陷：沉溺。
邪：邪僻，不正。离：背离。遁：逃避。
宰我：孔子弟子宰予。子贡：孔子弟子端木赐。
冉牛：孔子弟子冉耕，字伯牛。闵子：孔子弟子闵损，字子骞。颜回：孔子弟子颜渊。
子游：孔子弟子言偃。子张：孔子弟子颛孙师。
伊尹：商汤的贤臣。
何：同“可”。
班：同等，并列的意思。
有若：孔子的弟子。
污：夸大。阿（ē）徇私，偏袒。
等：指分出等次。
违：指违背“见其礼而知其政，闻其乐而知共德”的规律。
垤（dié）：小土堆。行潦（lǎo）：路上的积水。潦，雨水。
', '公孙丑问道：“先生如果做了齐国的卿相，得以推行自己的主张，即使成就了霸王的事业，也是不奇怪的。如果这样，您会动心吗？”
孟子说：“不。我四十岁以后就不再动心了。”
公孙丑说：“这么说，先生远远超过孟贲了。”
孟子说：“这不难，告子在我之前就做到不动心了。”
公孙丑说：“做到不动心，有什么方法吗？”
孟子说：“有。北宫黝培养勇气的办法是，肌肤被刺也不颤动发抖，眼睛被戳也能目不转睛，但他觉得，受了他人一点小委屈，就像在大庭广众之下被人鞭打了一般。既不受平民百姓的侮辱，也不受大国之君的侮辱。在他看来，刺杀大国之君，和刺杀普通老百姓是一样的。他不畏惧诸侯王。有人骂他，他一定回击。孟施舍培养勇气呢，是说：‘我把不能取胜的形势看成可以取胜。如果先估量敌人的力量才前进，考虑到可以取胜才交战，这是害怕敌人的三军。我孟施舍咋能战无不胜，只能无所畏惧罢了。’（培养勇气的方法，）孟施舍像曾子，北宫黝像子夏。这两个人的勇气，不知道谁更强，然而，孟施舍所守的较能符合要领。从前曾子对子襄说：‘你喜欢勇敢吗？我曾经从先生那里听过什么是大勇：自我反省而发现正义不在我，那么即使是普通百姓，我也不去恐吓他；自我反省而认为正义在我，即使面对千军万马，我也勇往直前。’孟施舍所守的是一身盛气，曾子却能有所反省，循理而动，所以，孟施舍又不如曾子所守把握住要领。”
孟子说：“告子讲过：‘言语有过失，不必到内心去寻求原因，心中有所不安，不必求助于意气。’心中有所不安，不必求助于意气，是可以的；言语有过失，不必到内心去寻求原因，却不可以。思想意志呢，是感情意气的统帅，感情意气是充满体内的力量。思想意志到哪里，感情意气就跟着到哪里。所以说：‘要坚定自己的思想意志，也不要滥用感情妄动意气。’”
公孙丑说：“既然说‘思想意志到哪里，感情意气就跟着到哪里’，又说‘要坚定自己的思想意志，也不要滥用感情妄动意气’，为什么呢？”
孟子说：“思想意志专一，就能调动感情意气跟随它；感情意气专一，就会影响思想意志。比方说跌倒、奔跑，这是下意识的气有所动，但也能反过来扰动心志。”
公孙丑说：“请问先生擅长哪方面？”
孟子说：“我能够判断人们的语言，我善于培养我的浩然之气。”
公孙丑说：“请问什么叫做浩然之气？”
孟子说：“难以讲清楚啊。它作为一种气，是最强大，最刚健的，用正直来培养它而不伤害它，就能充塞于天地之间。它作为一种气，是合乎义和道的；没有这个，它就疲弱了。它是日积月累的正义所生长出来的，不是偶然地有过正义的举动就取得的。如果行为有愧于心，气就萎缩了。因此我说，告子不曾懂得义，因为他把义看做是外在的东西。（对浩然之气，）一定要培养它，不能停止下来；心里不能忘记它，也不妄自助长它。不要像那个宋国人一样。宋国有个担心禾苗长不快而把它拔高的人，非常疲倦地回去，告诉他的家人说：‘今天累坏了，我帮助禾苗长高了。’他的儿子跑过去看，禾苗都枯槁了。天底下不拔苗助长的人少见啊。（说到浩然之气，）以为培养无益而放弃的，是不为禾苗除草的人；有意帮助它生长的，是拔苗的人。不仅无益，而且有害。”
公孙丑说：“怎样才算‘能够判断人们的语言’？”
孟子说：“偏颇的言辞，知道它在哪一方面被遮蔽而不明事理；过分的言辞，知道它耽溺于什么而不能自拔；邪僻的言辞，知道它违背了什么道理而乖张不正；搪塞的言辞，知道它在哪里理屈而终于词穷。言辞的过失产生于思想认识，危害于政治；把它体现于政令措施，就会危害具体工作。如果圣人复生，一定会赞同我的话。”
公孙丑说：“宰我、子贡善于说话，冉牛、闵子、颜渊善于阐述德行。孔子兼而有之，但他又说：‘我对于辞令是不擅长的。’那么先生您已经是圣人了吧？”
孟子说：“呦！这是什么话呀？从前子贡问孔子道：‘先生是圣人了吧？’孔子说：‘圣人，我做不到，我只是学习而不知满足，教育而不知疲倦。’子贡说：‘学习而不知满足，是明智；教育而不知疲倦，是仁爱。明智而且仁爱，先生已经是圣人了！’圣人，连孔子都不愿自居，你说的是什么话呀！”
公孙丑说：“以前我听说：子夏、子游、子张都有某一方面得到孔子真传，冉牛、闵子、颜渊则全面地得到孔子真传但气象比孔子小些。请问您自居于哪一种人？
孟子说：“暂且不谈这个。”
公孙丑说：“伯夷、伊尹怎么样？”
孟子说：“与孔子不同。不是他理想的君主，他不服侍；不是他理想的百姓，他不使唤；天下太平就进取，天下大乱就退隐，这是伯夷。服侍不理想的君主有什么关系，使唤不理想的百姓有什么关系；天下太平也进取，天下大乱也进取，这是伊尹。可以做官就做官，可以不做就不做，可以长久留任就长久留任，可以迅速离任就迅速离任，这是孔子。这都是古代的圣人，我没有一样能做到；要说愿望的话，我愿学孔子。”
公孙丑说：“伯夷、伊尹和孔子不是一样的吗？”
孟子说：“不。自从有人类以来，还没有像孔子那样的。”
公孙丑说：“那么他们有相同之处吗？”
孟子说：“有。如果得到纵横百里的土地而做君王，他们都能使诸侯来朝觐而统一天下。做一件不义的事，杀一个无辜的人因而得到天下，他们都不干。这是他们的相同之处。”
公孙丑说：“请问他们又有什么不同呢？”
孟子说：“宰我、子贡、有若的聪明足以了解孔子。他们的智慧再低下，也不至于偏袒他们所喜爱的人。宰我说：‘凭我对先生的观察，他比尧、舜强多了。’
子贡说：‘看某时某地的礼制，就可以了解它的政治状况；听某时某地的音乐，就可以了解它的道德风气。从百代以后，去评价百代以来的君王，没有人能违背这个规律而有所隐蔽。我认为自从有人类以来，还没有像先生那样的人。’有若说：‘难道只是人有高下之分吗？麒麟对于走兽，凤凰对于飞鸟，泰山对于土堆，河海对于积水，都算是同类。圣人对于人，也是同类。突出于所属的类，超拔于所属的群，自从有人类以来，还没有比孔子更伟大的。’”
', '[{"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "6471e1b2902ee364cc94ecdb", "shortContent": "孟子为战国时儒家代表人物之一，其文章以刚劲雄辩、富于感染力著称，同时又擅长运用比喻和寓言，化抽象枯燥的说理为生动活泼的形象化呈现，因而历来为人称道。后世名家如韩愈、苏轼，均自《孟子》获益良多。\n选段之文，即是最能体现孟子文风特点的章节之一。孟子于此答弟子之问，指出自己的长处在于“知言”和“养浩然之气”。前者意味着能够判断各种邪曲不正的有害言论，指出其危害性；后者则是培养心中至大至刚的浩然正气，从而...", "authors": ["孙逊"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557743022, '5cd8d52b0237d70069ec4869', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642569, '孟子 · 第三卷 · 公孙丑上 · 第三节 ', NULL, 10, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“以力假仁者霸，霸必有大国；以德行仁者王，王不待大。汤以七十里，文王以百里。以力服人者，非心服也，力不赡也；以德服人者，中心悦而诚服也，如七十子之服孔子也。《诗》云：‘自西自东，自南自北，无思不服。’此之谓也。”
', '', '待：倚仗。
赡：足，够。
七十子：指孔子弟子。相传孔子有弟子三千人，通六艺者七十二人。
思：语助词。以上引诗出自《诗经·大雅·文王有声》。
', '孟子说：“倚仗实力，打着仁义的旗号而统一天下的就是霸道；推行霸道，一定得有强大的国家作为基础；依靠道德，推行仁义而统一天下的叫做王道；实行王道，不一定要有强大的国家作为基础。商汤凭借的仅是纵横七十里的土地，文王凭借的仅是纵横百里的土地。倚仗实力来使人服从的，并不是真心服从，只不过力量不足相敌罢了；依靠道德来使人服从的，却是心悦诚服，就像七十个弟子服从孔子一样。《诗经》说：‘从西从东，从南从北，无不心悦诚服。’正是说的这一点。”
', NULL, '', 'indent', 1557743067, '5cd8d55943e78c0065ca95fb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642570, '孟子 · 第三卷 · 公孙丑上 · 第四节', NULL, 7, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“仁则荣，不仁则辱。今恶辱而居不仁，是犹恶湿而居下也。
如恶之，莫如贵德而尊士，贤者在位，能者在职。国家闲暇，及是时明其政刑。虽大国，必畏之矣。诗云：‘迨天之未阴雨，彻彼桑土，绸缪牖户。今此下民，或敢侮予？’孔子曰：‘为此诗者，其知道乎！能治其国家，谁敢侮之？’
今国家闲暇，及是时般乐怠敖，是自求祸也。祸褔无不自己求之者。诗云：‘永言配命，自求多褔。’太甲曰：‘天作孽，犹可违；自作孽，不可活。’此之谓也。”', '', '', '', NULL, '', 'indent', 1557743117, '5cd8d58530863b00705ab369', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642572, '孟子 · 第三卷 · 公孙丑上 · 第六节 ', NULL, 35, 271, 5, 3, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“人皆有不忍人之心。先王有不忍人之心，斯有不忍人之政矣。以不忍人之心，行不忍人之政，治天下可运之掌上。
所以谓人皆有不忍人之心者，今人乍见孺子将入于井，皆有怵惕恻隐之心。非所以内交于孺子之父母也，非所以要誉于乡党朋友也，非恶其声而然也。
由是观之，无恻隐之心，非人也；无羞恶之心，非人也；无辞让之心，非人也；无是非之心，非人也。恻隐之心，仁之端也；羞恶之心，义之端也；辞让之心，礼之端也；是非之心，智之端也。人之有是四端也，犹其有四体也。有是四端而自谓不能者，自贼者也；谓其君不能者，贼其君者也。
凡有四端于我者，知皆扩而充之矣，若火之始然，泉之始达。苟能充之，足以保四海；苟不充之，不足以事父母。”', '', '怵惕（chù tì）：恐惧。恻隐：哀痛。
内交：交结，交好。内，同“纳”。孺（rú）子：幼童。
然：“燃”的本字。
保四海：保有天下之民而为君王。
', '孟子说：“人都有怜恤别人的心理。古代的君王有怜恤别人的心，这才有怜恤别人的政治。用怜恤别人的心去实行怜恤别人的政治，治理天下就像在手掌上玩弄东西那样简单。所以说人们都有怜恤别人的心理，譬如说，现在有人忽然看见小孩子快要掉到井里去，都有惊骇、同情的心情，这并不是为了和小孩子的父母攀交情，不是为了在乡里朋友间博取声誉，也不是因为厌恶那小孩子的哭声才这样的。
“由此看来，没有恻隐之心，不算人；没有羞耻之心，不算人；没有辞让之心，不算人；没有是非之心，不算人。恻隐之心，是仁的萌芽；羞耻之心，是义的萌芽；辞让之心，是礼的萌芽；是非之心，是智的萌芽。人有这四种萌芽，就如同他有四肢。有这四种萌芽而自称不能行善的人，是自己残害自己的人；说他的君王不能行善的人，是残害君王的人。凡是有这四种萌芽在身上的人，就该懂得把它们都扩充起来，就像火开始燃烧，泉水开始流出。如果能够扩充它们，就足以安抚天下；如果不能扩充它们，那就连父母都侍奉不了。”
', NULL, '', 'indent', 1557743209, '5cd8d5e617b54d0075b24e25', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642573, '孟子 · 第三卷 · 公孙丑上 · 第七节 ', NULL, 12, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“矢人岂不仁于函人哉？矢人唯恐不伤人，函人唯恐伤人。巫匠亦然，故术不可不慎也。孔子曰：‘里仁为美。择不处仁，焉得智？’夫仁，天之尊爵也，人之安宅也。莫之御而不仁，是不智也。不仁、不智、无礼、无义，人役也。人役而耻为役，由弓人而耻为弓，矢人而耻为矢也。如耻之，莫如为仁。仁者如射，射者正己而后发。发而不中，不怨胜己者，反求诸己而已矣。”', '', '矢人：做箭的人。函人：造铠甲的人。函，铠甲。
巫：指巫医。匠：指制造棺椁的木匠。
引文见《论语·里仁》。
莫之御而不仁：没人阻拦你却不仁。
由：通“犹”。
', '孟子说：“造箭的人难道比造铠甲的人本性残忍吗？造箭的人唯恐不能伤害人，造铠甲的人唯恐伤害人。巫医和木匠也是这样。所以选择职业不可不慎重。孔子说：‘和仁人处邻里是最好的。自己选择而不自处于仁，怎能说是明智的？’仁哪，是天设的最尊贵的爵位，是人最安稳的宅居。没有人能阻挡，这样还不仁，这就是不智了。不仁、不智，无礼、无义，是要被他人所奴役的。被人奴役却耻于服役，就好比造弓的人却耻于造弓，造箭的人却耻于造箭。如果确实以为耻辱，不如实行仁。实行仁，就好比射箭，射箭的人先端正自己的姿势然后才发射；发射而没有射中，不埋怨胜过自己的人，只要反过来找自己的问题就行了。”', NULL, '', 'indent', 1557743249, '5cd8d60e17b54d0075b250a0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642574, '孟子 · 第三卷 · 公孙丑上 · 第八节 ', NULL, 9, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“子路，人告之以有过则喜。禹闻善言则拜。大舜有大焉，善与人同。舍己从人，乐取于人以为善。自耕稼、陶、渔以至为帝，无非取于人者。取诸人以为善，是与人为善者也。故君子莫大乎与人为善。”', '', '有：通“又”。
自耕稼、陶、渔以至为帝：传说舜为天子之前曾在历山耕种，在河滨做瓦器，在雷泽打鱼。
禹：传说中古代部落联盟领袖，曾经奉舜命治水。
', '孟子说：“子路，别人指出他的过错，他就高兴。禹，听到好的言论，就向人家行礼。大舜更加了不起，他把善当作人所共享，舍弃自己的不足，学习别人的长处，乐于吸取别人的优点来完善自己。从他种田、做瓦器、打鱼一直到做天子，无时无刻不是从别人那里吸取优点。吸取别人的优点来完善自己，这就是同别人一起行善。所以君子最了不起的就是同别人一起行善。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0f0", "shortContent": "舜是孔子和孟子都非常崇敬的一位古代圣人，他的一大优点便在于他乐于学习他人的善处，即句中所说的“与人为善”。此处的“与人为善”与今人的理解有一定差距，孟子的原意是，吸取他人的优点来自己行善，这就相当于偕同他人一起行善。舜在取得禅位之前，向他人学习耕稼、陶、渔的方法，在获得帝王之位后，又向他的大臣们学习治理国家的策略和方法。可以说，舜能成为圣君，与他一生都乐于向人学习，特别是学习他人的善处是密不可分的...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1557743290, '5cd8d63717b54d0075b2523e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642575, '孟子 · 第三卷 · 公孙丑上 · 第九节 ', NULL, 9, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“伯夷，非其君不事，非其友不友。不立于恶人之朝，不与恶人言。立于恶人之朝，与恶人言，如以朝衣朝冠坐于涂炭。推恶恶之心，思与乡人立，其冠不正，望望然去之，若将浼焉。是故诸侯虽有善其辞命而至者，不受也。不受也者，是亦不屑就已。柳下惠，不羞污君，不卑小官。进不隐贤，必以其道。遗佚而不怨，阨穷而不悯。故曰：‘尔为尔，我为我，虽袒裼裸裎于我侧，尔焉能浼我哉？’故由由然与之偕而不自失焉，援而止之而止。援而止之而止者，是亦不屑去已。”
孟子曰：“伯夷隘，柳下惠不恭。隘与不恭，君子不由也。”', '', '伯夷：周时孤竹君的长子，与其弟叔齐因反对武王伐纣，隐居于首阳山，采薇而食，饿死。
思：语助词，无义。
望望然：羞愧的样子。浼（měi）：污，肮脏。
不屑：不以……为洁。屑，洁。
柳下惠：春秋时鲁国大夫，姓展名禽，字季。
遗佚：指被弃不用。佚，隐遁，不为世用。阨（è）穷：困穷。悯：忧愁。
袒（tǎn）裼（xī）裸（luǒ）裎（chéng）：赤身露体之意。
由：行，做。
', '孟子说：“伯夷（这个人），不是他敬仰的君主，不去侍奉；不是他中意的朋友，不去结交。不在有坏人的朝廷做官，不同坏人讲话。在有坏人的朝廷做官，同坏人讲话，就像穿着上朝的礼服，戴着上朝的礼帽坐在泥土和炭灰上一样。他把厌恶坏人的心情扩充开来，于是，同乡下人站在一起，假如那人帽子不正，他就羞愧地避开，好像会弄脏了自己似的。因此诸侯王尽管有好言好语来请他做官，他也不接受。他不接受，这是因为他以为接近他们就不干净了。柳下惠不以侍奉污浊的君主为羞愧，不以当小官为卑微，入朝做官，不隐藏他的贤能，一定依照他的原则办事；被弃不用，他不埋怨，处境困穷，他不发愁。所以他说：‘你是你，我是我，即使在我身边赤身裸体，你怎么能玷污我呢？’因此他能高高兴兴地与任何人相处而不丧失自己，让他留下他就留下。让他留下他就留下，这是因为他不把避开当作高洁。”孟子又说：“伯夷气量小，柳下惠不严肃。气量小和不严肃，君子是不效仿的呀。”', NULL, '', 'indent', 1557743363, '5cd8d67fc8959c00687fa48e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642639, '孟子 · 第八卷 · 离娄下 · 第七节 ', NULL, 9, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“中也养不中，才也养不才，故人乐有贤父兄也。如中也弃不中，才也弃不才，则贤不肖之相去，其间不能以寸。”', '', '中：中道，中庸，代指有德行的人。养：影响，教育。不中：过或不及。
其间不能以寸：指差距极小。
', '孟子说：“有德行的人影响、教育没有德行的人，有才能的人影响、教育没有才能的人，所以人人都喜欢有贤能的父兄。如果有德行的人嫌弃没有德行的人，有才能的人不理会没有才能的人，那么贤和不肖的距离，就近得没有办法用分寸来衡量了。”
', NULL, '', 'indent', 1557915332, '5cdb764143e78c00686ba866', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642577, '孟子 · 第四卷 · 公孙丑下 · 第二节 ', NULL, 6, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子将朝王，王使人来曰：“寡人如就见者也，有寒疾，不可以风。朝，将视朝，不识可使寡人得见乎？”
对曰：“不幸而有疾，不能造朝。”
明日，出吊于东郭氏。公孙丑曰：“昔者辞以病，今日吊，或者不可乎？”
曰：“昔者疾，今日愈，如之何不吊？”
王使人问疾，医来。
孟仲子对曰：“昔者有王命，有采薪之忧，不能造朝。今病小愈，趋造于朝，我不识能至否乎。”
使数人要于路，曰：“请必无归，而造于朝！”
不得已而之景丑氏宿焉。
景子曰：“内则父子，外则君臣，人之大伦也。父子主恩，君臣主敬。丑见王之敬子也，未见所以敬王也。”
曰：“恶！是何言也！齐人无以仁义与王言者，岂以仁义为不美也？其心曰：‘是何足与言仁义也’云尔，则不敬莫大乎是。我非尧舜之道，不敢以陈于王前，故齐人莫如我敬王也。”
景子曰：“否，非此之谓也。礼曰：‘父召无诺；君命召不俟驾。’固将朝也，闻王命而遂不果，宜与夫礼若不相似然。”
曰：“岂谓是与？曾子曰：‘晋楚之富，不可及也；彼以其富，我以吾仁；彼以其爵，我以吾义，吾何慊乎哉？’夫岂不义而曾子言之？是或一道也。天下有达尊三：爵一，齿一，德一。朝廷莫如爵，乡党莫如齿，辅世长民莫如德。恶得有其一以慢其二哉？故将大有为之君，必有所不召之臣；欲有谋焉，则就之。其尊德乐道，不如是，不足与有为也。故汤之于伊尹，学焉而后臣之，故不劳而王；桓公之于管仲，学焉而后臣之，故不劳而霸。今天下地丑德齐，莫能相尚，无他．好臣其所教，而不好臣其所受教。汤之于伊尹，桓公之于管仲，则不敢召。管仲且犹不可召，而况不为管仲者乎？”', '', '王：指齐王。
如：应该。
不可以风：不可冒风。
东郭氏：齐国大夫。
孟仲子：孟子的从弟，跟随孟子学习。
采薪之忧：生病的代词。
要（yāo）：遮拦。
景丑氏：齐国大夫。
伦：儒家为社会制度所规定的人与人之间的正常关系。儒家以君臣、父子、夫妇、兄弟、朋友五种关系为五伦。
恶（wū）：叹词，表惊讶。
是：指齐王。
父召，无诺：《礼记·曲礼》：“父命呼，唯而不诺。”意思是，父亲有招呼，该答“唯”，不答“诺”。按“唯”和“诺”都表示答应，以“唯”为恭敬。
君命召，不俟驾：《论语·乡党》：“君命召，不俟驾行矣。”又《荀子·大略》：“诸侯召其臣，臣不俟驾，颠倒衣裳而走，礼也。”可见礼经上确有这样的规范，即君王召见时，臣下不等车马准备好就应立刻动身。
宜：似乎，大概。
慊（qiàn）：以为少，不满足。
达尊：公认为尊贵者。达，通。
齿：年龄。
不召之臣：受特殊礼貌待遇，不被召唤的贤臣。
丑：相同。
', '孟子正要去朝见齐王，齐王派人来说：“我本该来见您，可是着凉了，不能吹风。您如果来朝见，我就临朝办公，不知道可以让我见到您吗？”
孟子答道：“我也不幸得了病，不能上朝廷去。”
次日，孟子到东郭家吊丧。公孙丑说：“昨天托病拒绝朝见，今天又去吊丧，恐怕不好吧？”
孟子说：“昨天病了，今天好了，为什么不去吊丧？”
齐王派人来问病，医生也来了。
孟仲子答道：“昨天大王有命令来，正赶上夫子也得了小病，不能上朝廷去。今天病稍好些，他就上朝廷去了，我不知到了没有？”
他又打发几个人到孟子归家的路上拦住孟子，说：“请一定别回来，直接到朝廷去吧！”
孟子不得已，到景丑家歇宿。景子说：“在家有父子，在外有君臣，这都是重要的人际关系。父子以恩爱为主，君臣以恭敬为主。我只见大王尊敬您，却没见您尊敬大王。”
孟子说：“嗬！这是什么话！齐国人没有拿仁义向大王进言的，难道认为仁义不好吗？他心里说，‘这个人哪里值得和他讲仁义’，如此而已，没有比这更不恭敬的了。我呢，不是尧、舜的道理，不敢在大王的面前说，所以齐国人没有比我更尊敬大王的。”
景子说：“不，我不是指这个。礼经上说：‘父亲召唤，答“唯”不答“诺”，君王召唤，不等车马准备好就出发。’你本来要去朝见，听到大王的命令反而不去，似乎和礼的规范有些不合。”
孟子说：“难道我说的是这个道理？曾子说：‘晋王和楚王的财富，我是比不上的。但是他倚仗他的财富，我倚仗我的仁；他倚仗他的爵位，我倚仗我的义，我何必自以为比他少点什么？’不义的话，曾子会说吗？这话也许有一番道理吧。天下公认为尊贵的东西有三个：爵位是一个，年龄是一个，道德是一个。在朝廷上先论爵位，在乡里先论年龄，辅助君王治理天下、统治人民，先论道德。怎么可以因为占了其中一个，而来骄慢其他两个？所以想要大有作为的君王，一定有他不能召见的臣子。如果有事要商量，就主动到臣子那里去。他尊重道德喜爱道义，如果达不到这个程度，是不足以和他一道有所作为的。所以商汤对于伊尹，首先是向他学习，然后才把他当臣子，因此不操劳就统一了天下；齐桓公对于管仲，首先是向他学习，然后才把他当臣子，因此不操劳就称霸于诸侯。当今天下各国，国土是一样大小，品德是一般高低，没有人能超过别人。没有别的原因，就因为都喜欢把自己所教导的人当臣子，而不喜欢把教导自己的人当臣子。商汤对于伊尹，齐桓公对于管仲，那是不敢召唤的。管仲尚且不可以召唤，何况不屑于做管仲的人呢？”
', NULL, '', 'indent', 1557743524, '5cd8d71c0237d70069ec6017', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642578, '孟子 · 第四卷 · 公孙丑下 · 第三节 ', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '陈臻问曰：“前日于齐，王馈兼金一百而不受；于宋，馈七十镒而受；于薛，馈五十镒而受。前日之不受是，则今日之受非也；今日之受是，则前日之不受非也。夫子必居一于此矣。”
孟子曰：“皆是也。皆适于义也。当在宋也，予将有远行。行者必以赆，辞曰：‘馈赆。’予何为不受？当在薛也，予有戒心。辞曰：‘闻戒。’故为兵馈之，予何为不受？若于齐，则未有处也。无处而馈之，是货之也。焉有君子而可以货取乎？”', '', '陈臻：孟子弟子。
馈：赠送。
兼金：好金，价值双倍于普通金，故称。一百：指一百镒；一镒为二十两。
赆（jìn）：送给别人的财物。这里指盘缠。
', '陈臻问道：“前些日子在齐国，齐王送您上等金一百镒，而您不接受；在宋国，宋君送您七十镒，您接受了；在薛，薛君送您五十镒，您也接受了。如果先前的不接受是对的，那么今天的接受就是错的了；如果今天的接受是对的，那么先前的不接受就是错的了。二者之间，您必有一个是错的。”
孟子说：“都是对的。在宋国的时候，我将要去远行，对远行的人照风俗是要送些盘缠的；因此他说：‘赠送盘缠。’我为何不接受？在薛的时候，我有戒备之心；因此他说：‘听说您有戒备之心，赠送买兵器的钱。’我为何不接受？至于在齐国，就没什么理由了。没有理由而送钱给我，这是收买我。哪里有君子能被收买的呢？”
', NULL, '', 'indent', 1557743571, '5cd8d75017b54d0075b261a9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642579, '孟子 · 第四卷 · 公孙丑下 · 第四节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子之平陆。谓其大夫曰：“子之持戟之士，一日而三失伍，则去之否乎？”曰：“不待三。”
“然则子之失伍也亦多矣。凶年饥岁，子之民，老羸转于沟壑，壮者散而之四方者，几千人矣。”曰：“此非距心之所得为也。”
曰：“今有受人之牛羊而为之牧之者，则必为之求牧与刍矣。求牧与刍而不得，则反诸其人乎？抑亦立而视其死与？”曰：“此则距心之罪也。”
他日，见于王曰：“王之为都者，臣知五人焉。知其罪者，惟孔距心。为王诵之。”王曰：“此则寡人之罪也。”', '', '平陆：齐国边境邑名，故城在今山东汶上北。大夫：这里指邑宰，即邑的长官。
距心：姓孔，即本章对话中平陆邑宰之名。
牧：指牧地。刍：草料。
反：还。抑：或。与：疑问助词。
都：县邑。为都：治理都邑。

', '孟子到平陆去，对当地的邑宰说：“先生的士卒，如果—天失职三次，你会杀了他吗？”
邑宰说：“不必等到三次。”
孟子说：“那么，您失职的地方可就多了。饥荒年岁，您的百姓，年老体弱的辗转死于沟壑，年轻力壮的四散逃荒，几乎达一千人啊。”
邑宰说：“这不是我距心力所能及的。”
孟子说：“假如现在有个接受别人牛羊而替人放牧的人，他一定会替人去找牧场和草料。找不到牧场和草料的话，是把牛羊还给人家呢？还是站着眼看它们死掉呢？”
邑宰说：“这么说是我距心的罪过了。”
过些日子，孟子朝见齐王，说：“王的都邑长官中，我认识五个人。明白自己的罪过的，只有孔距心一人。”接着向齐王重述了一遍他与孔距心的对话。
王说：“这么说是我的罪过了。”', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b468e7f27182da3ee0023", "shortContent": "这几章文字都是记述孟子在齐国的见闻、活动和与人谈对自己在齐的遭遇的看法和情感。孟子是在五十四岁左右来到齐国的，在此之前他曾在魏国（也称为梁）游说其统治者，没有取得什么成效。他对到齐国的活动充满了期望，在那里住了五六年时间，在个人的人生事业和情感上曾经有过很大的起伏。齐国在列国之中是个大国，在当时相当强盛。而且齐宣王有雄心壮志，想有所作为。他对孟子曾经十分尊重，一度委以官职，任他为卿。孟子因此曾经对...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557743664, '5cd8d7ad30863b00705acf77', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642580, '孟子 · 第四卷 · 公孙丑下 · 第五节', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子谓蚳鼃曰：“子之辞灵丘而请士师，似也，为其可以言也。今既数月矣，未可以言与？”蚔鼁谏于王而不用，致为臣而去。齐人曰：“所以为蚔鼁，则善矣；所以自为，则吾不知也。”公都子以告。
曰：“吾闻之也：有官守者，不得其职则去；有言责者，不得其言则去。我无官守，我无言责也，则吾进退，岂不绰绰然有余裕哉？”', '', '蚳鼃（chí wā）：齐国大夫。鼃，即今“蛙”字。
灵丘：齐国边境邑名。
致为臣：犹言“致仕”，交还官职，这里指辞职。致，还。
公都子：孟子弟子。
', '孟子对蚳鼃说：“你辞去灵丘邑的邑宰而请求做狱官，似乎是有道理的，因为可以进言。现在你做狱官已经有几个月了，还不能进言吗？”
蚳鼃向齐王进谏而得不到采纳，就辞职走了。
齐国有人说：“孟子为蚳鼃考虑的主意是好的；为自己考虑的主意怎样呢，那我就不知道了。”
公都子把这话告诉孟子。
孟子说：“我听说过，有官职在身的人，如果不能尽职，就辞去；有进言职责的人，如果进言不被采纳，就辞职而去。我没有官职在身，也没有进言的职责，那么，我的进退，难道不是宽松自如，大有余地吗？”
', NULL, '', 'indent', 1557743719, '5cd8d7de17b54d0075b26910', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642581, '孟子 · 第四卷 · 公孙丑下 · 第六节 ', NULL, 4, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子为卿于齐，出吊于滕，王使盖大夫王欢为辅行。王欢朝暮见，反齐、滕之路，未尝与之言行事也。
公孙丑曰：“齐卿之位，不为小矣；齐、滕之路，不为近矣，反之而未尝与言行事，何也？”
曰：“夫既或治之，予何言哉？”
', '', '盖（gě）大夫：指盖邑的邑宰。盖，齐国邑名，故城在今山东沂水西北。王欢（huān）：齐王宠臣，后为右师，是个谗佞小人。辅行：副使。
“齐卿”句：这里是指孟子而言。公孙丑以为孟子任齐卿，不小于王欢，宜有所指挥，因而有此一问。
', '孟子在齐国做卿，出使滕国去吊丧，齐王派盖邑的长官王欢任副使同行。孟子与王欢朝夕相处。在往返齐国和滕国的路上，孟子没和王欢讲过出使的事。
公孙丑说：“齐卿的官位，不算小了。齐滕间的路途，也不算近了。往返一趟而没和他讲过出使的事，这是为什么？”
孟子说：“他既然自作主张办事了，我还说什么呢？”
', NULL, '', 'indent', 1557743758, '5cd8d80b17b54d0075b26ae6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642582, '孟子 · 第四卷 · 公孙丑下 · 第七节 ', NULL, 8, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子自齐葬于鲁，反于齐，止于嬴。充虞请曰：“前日不知虞之不肖，使虞敦匠事。严，虞不敢请。今愿窃有请也，木若以美然。”
曰：“古者棺椁无度，中古棺七寸，椁称之。自天子达于庶人。非直为观美也，然后尽于人心。不得，不可以为悦；无财，不可以为悦。得之为有财，古之人皆用之，吾何为独不然？且比化者，无使土亲肤，于人心独无恔乎？吾闻之也，君子不以天下俭其亲。”', '', '嬴（yíng）：齐国邑名，故城在今山东莱芜西北。
充虞：孟子弟子。
严：急。
以：太。
度：厚薄长短的标准。中古：指周公制礼的时候。
比：为。化者，死者。
恔（xiào）：满意。
', '孟子为安葬母亲，从齐国回到了鲁国，然后又返回齐国，在嬴邑停了下来。
充虞请教说：“前些日子承蒙您错爱，让我管木匠的事。当时事情急迫，我不敢请教。现在愿有所请教：棺木似乎太好了。”
孟子说：“古时候，棺椁没有固定的尺寸，到了中古的时候，规定棺厚七寸，椁与之相称。从天子到老百姓，讲究棺椁，不只是为了美观，而是因为这样才能孝心。因礼制限定而不能用，不能算如意；没钱，也不能如意。礼制规定可以用，又有钱，古人都这样用了，为什么就我不行？而且为死者考虑，不使泥土挨着肌肤，对于孝子来说不是可以少点遗憾吗？我听说过，君子不会因为天下的缘故而在父母的身上节俭。”

', NULL, '', 'indent', 1557743811, '5cd8d841c8959c00687fbafb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642583, '孟子 · 第四卷 · 公孙丑下 · 第八节 ', NULL, 6, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '沈同以其私问曰：“燕可伐与？”
孟子曰：“可。子哙不得与人燕，子之不得受燕于子哙。有仕于此，而子悦之，不告于王而私与之吾子之禄爵；夫士也，亦无王命而私受之于子，则可乎？何以异于是？”齐人伐燕。或问曰：“劝齐伐燕，有诸？”
曰：“未也。沈同问‘燕可伐与’？吾应之曰‘可’，彼然而伐之也。彼如曰‘孰可以伐之’？则将应之曰：‘为天吏，则可以伐之。’今有杀人者，或问之曰‘人可杀与’？则将应之曰‘可’。彼如曰‘孰可以杀之’？则将应之曰：‘为士师，则可以杀之。’今以燕伐燕，何为劝之哉？”', '', '沈同：齐大臣。
子哙（kuài）：燕王。子之：燕相。
以燕伐燕：前一个燕字喻指齐国，犹言以暴制暴。
', '沈同以私人身份问道：“可以讨伐燕国吗？”
孟子说：“可以。子哙不可以把燕国送给子之，子之也不可以从子哙那里接受燕国。譬如这里有个士人，您喜欢他，不跟王打招呼就私自把您的俸禄和爵位给他，那士人呢，也没有王的任命就私自从您这里接受了，那能行吗？燕国的事和这个有什么不同呢？”
齐国讨伐了燕国。
有人问孟子：“您劝齐国讨伐燕国，有这事吗？”
孟子说：“没有。沈同问：‘燕国可以讨伐吗？’我回答他说‘可以’。他便赞同而去讨伐燕国。他如果再问：‘谁可以去讨伐？’我就会答道：‘作为天吏，就可以去讨伐它。’譬如现在有个杀人的，有人问道：‘那人可以杀吗？’我就会回答说‘可以。’他如果问：‘谁可以杀他？’我就会答‘作为狱官，就可以杀他’。如今拿一个同燕国一样暴虐的齐国去讨伐燕国，我为什么去劝他呢？”
', NULL, '', 'indent', 1557743867, '5cd8d8780237d70069ec7576', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642584, '孟子 · 第四卷 · 公孙丑下 · 第九节 ', NULL, 9, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '燕人畔。王曰：“吾甚惭于孟子。”
陈贾曰：“王无患焉。王自以为与周公，孰仁且智？”王曰：“恶！是何言也？”
曰：“周公使管叔监殷，管叔以殷畔。知而使之，是不仁也；不知而使之，是不智也。仁智，周公未之尽也，而况于王乎？贾请见而解之。”见孟子问曰：“周公何人也？”
曰：“古圣人也。”曰：“使管叔监殷，管叔以殷畔也，有诸？”曰：“然。”
曰：“周公知其将畔而使之与？”曰：“不知也。”
“然则圣人且有过与？”
曰：“周公，弟也；管叔，兄也。周公之过，不亦宜乎？且古之君子，过则改之；今之君子，过则顺之。古之君子，其过也，如日月之食，民皆见之；及其更也，民皆仰之。今之君子，岂徒顺之，又从为之辞。”


', '', '畔：通“叛”，背叛。齐国吞并燕国后，燕人另立太子平为燕王，不肯归附于齐，这在齐宣王而言便是背叛。
陈贾：齐国大夫。
周公使管叔监殷：武王克商后，立纣的儿子武庚治理商地，派管叔、蔡叔等监督。管叔，名鲜，武王之弟，周公之兄。
管叔以殷畔：武王死后，成王年幼，周公摄政。管叔与武庚发动叛乱，周公前住讨伐，杀武庚、管叔。
', '燕国人背叛齐国。齐王说：“我对孟子感到很惭愧。”
陈贾说：“大王不必忧虑。大王自以为和周公相比，谁更仁爱而明智？”
王说：“哪里！这是什么话呢！”
陈贾说：“周公让管叔监督殷国，管叔却凭借殷国发动叛乱，如果知道他要叛乱而让他去，这是不仁，如果不知道他要叛乱而让他去，这是不智。仁和智，周公尚且不能完全做到，何况大王呢？请让我见孟子并向他解释。”
陈贾见了孟子，问道：“周公是什么人呢？”
孟子说：“古代圣人。”
陈贾说：“他让管叔监督殷国，管叔却凭借殷国发动叛乱，有这事吗？”
孟子说：“有。”
陈贾说：“周公是知道他要叛乱而让他去的吗？”
孟子说：“他不知道。”
陈贾说：“那么圣人也会有过错吗？”
孟子说：“周公是弟弟，管叔是哥哥。周公犯这个错误，不是很自然吗？况且古时候的君子，犯了错误就改正，现在的君子，犯了错误却将错就错。古时候的君子，他的错误呢，就像日食和月食一般，老百姓都看得见；等他改正了，老百姓都抬头仰望着他们。现在的君子，不但将错就错，还接着编一套说辞文过饰非。”
', NULL, '', 'indent', 1557743934, '5cd8d8b80237d70069ec78f3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642585, '孟子 · 第四卷 · 公孙丑下 · 第十节 ', NULL, 4, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子致为臣而归。王就见孟子，曰：“前日愿见而不可得，得侍，同朝甚喜。今又弃寡人而归，不识可以继此而得见乎？”对曰：“不敢请耳，固所愿也。”
他日，王谓时子曰：“我欲中国而授孟子室，养弟子以万钟，使诸大夫国人皆有所矜式。子盍为我言之？”时子因陈子而以告孟子，陈子以时子之言告孟子。
孟子曰：“然。夫时子恶知其不可也？如使予欲富，辞十万而受万，是为欲富乎？季孙曰：‘异哉子叔疑！使己为政，不用，则亦已矣，又使其子弟为卿。人亦孰不欲富贵？而独于富贵之中，有私龙断焉。’古之为市也，以其所有易其所无者，有司者治之耳。有贱丈夫焉，必求龙断而登之，以左右望而罔市利。人皆以为贱，故从而征之。征商，自此贱丈夫始矣。”', '', '致为臣：致仕，退休。
时子：齐国的臣。
中国：国都之中。万钟：指万钟粮食。一钟为六石四斗，万钟则为六万四千石，约折合今日之一万三千石。
矜式：敬重效法。矜，敬重。式，效法。
陈子：即孟子弟子陈臻。
恶：哪里。
龙断：即垄断，本意是断面陡峭的冈垄，引申为把持集市，牟取高利。
', '孟子辞掉客卿的官职准备回乡。齐王来见孟子，说：“从前希望见到您而没有机会，（后来）能在一个朝廷里共事，很高兴。现在您又要抛弃我而回乡，不知道今后还能见到您不？”
孟子答道：“我只是不敢请求（同你相见）而已，这（再次相见）本来也是我所希望的。”
后来的某一天，王对时子说：“我想在国都之中给孟子一幢房子，用万钟粮食供养他的弟子，使众大夫和平民百姓都有学习的榜样。你何不替我向孟子谈谈！”
时子托陈子把（齐王的）这个意思告诉孟子，陈子把时子的话转告了孟子。
孟子说：“原来是这样。时子哪里知道这是不可以的呢？假如我想发财，辞去十万钟的俸禄来接受一万钟的俸禄，这是想发财吗？季孙说：‘真奇怪啊，子叔疑这个人！想让自己做官，没被任用，那也就罢了，却又打发他的子弟来做卿相。人们谁个不想富贵？而偏偏在富贵之中有人想独自垄断。’古人做生意，拿自己所有的交换自己所无的，有专门的部门管理这种事。有个卑鄙汉子在那，一定要找个断而高的冈垄登上去，左顾右盼来网罗整个集市的利益。人人都认为他卑鄙，所以向他抽税。向商人抽税就是从这个卑鄙汉子开始的。”
', NULL, '', 'indent', 1557829307, '5cd8d8f67b968a00758a82e6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642586, '孟子 · 第四卷 · 公孙丑下 · 第十一节 ', NULL, 5, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子去齐，宿于昼。有欲为王留行者，坐而言不应，隐几而卧。
客不悦曰：“弟子齐宿而后敢言，夫子卧而不听，请勿复敢见矣。”
曰：“坐！我明语子。昔者鲁缪公无人乎子思之侧，则不能安子思；泄柳、申详无人乎缪公之侧，则不能安其身。子为长者虑，而不及子思；子绝长者乎？长者绝子乎？”
', '', '昼：齐国邑名，在齐国国都临淄西南，是孟子从齐国回邹国的必经之地。
坐：指危坐，即跪。古人席地而坐，双膝着地，臀部靠在脚后跟上，这是安坐；双膝着地而臀部离开脚后跟，这是危坐，即跪。隐：倚靠。几：坐几，设于座侧以便倚靠的小桌子。
齐（zhāi）宿：前一日斋戒。齐，通“斋”。
鲁缪（mù）公：即鲁穆公。缪，通“穆”。子思：孔子之孙，名伋，字子思。
泄柳、申详：都是鲁穆公时的贤人。泄柳即《告子下》第六章中的子柳，申详是孔子学生子张之子，子游之婿。
不及子思：不及鲁穆公安排在子思身边的贤人。
', '孟子离开齐国，在昼邑歇宿。有个人想替齐王挽留孟子，恭敬地坐着向孟子进言。孟子没答话，靠着坐几睡觉。
客人不高兴，说：“学生斋戒一天才敢跟您说话，先生却靠着坐几睡觉而不听我说话，以后我再也不敢和您见面了。”
孟子说：“坐下来！我清楚地告诉你。从前，鲁穆公如果没有人在子思身边及时表达尊贤的诚意，就不能使子思安心留下；泄柳、申详（在鲁国），如果没有人在鲁穆公身边随时劝王礼贤下士，就不能使自己安心。你为老人考虑，却比不上为子思考虑的那些贤人。（光劝我留下而不去劝齐王改变态度），这是你跟我这个长辈搞僵了呢，还是我这个长辈跟你搞僵了呢？”
', NULL, '', 'indent', 1557829369, '5cda267543e78c00698a142a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642640, '孟子 · 第八卷 · 离娄下 · 第八节 ', NULL, 12, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“人有不为也，而后可以有为。”
', '', '', '孟子说：“人要有所不为，才能有所作为。”
', NULL, '', 'indent', 1557915361, '5cdb765f17b54d0068e00f43', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642587, '孟子 · 第四卷 · 公孙丑下 · 第十二节 ', NULL, 4, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子去齐。尹士语人曰：“不识王之不可以为汤武，则是不明也；识其不可，然且至，则是干泽也。千里而见王，不遇故去。三宿而后出昼，是何濡滞也？士则兹不悦。”
高子以告。 
曰：“夫尹士恶知予哉？千里而见王，是予所欲也；不遇故去，岂予所欲哉？予不得已也。予三宿而出昼，于予心犹以为速。王庶几改之。王如改诸，则必反予。夫出昼而王不予追也，予然后浩然有归志。予虽然，岂舍王哉？王由足用为善。王如用予，则岂徒齐民安，天下之民举安。王庶几改之，予日望之。予岂若是小丈夫然哉？谏于其君而不受，则怒，悻悻然见于其面。去则穷日之力而后宿哉？” 
尹士闻之曰：“士诚小人也。” ', '', '尹士：齐国人。
干泽：求爵禄。干，求。泽，恩泽，指俸禄。
濡滞：迟滞，久留。
高子：齐国人，孟子弟子。
庶几：或许，表希冀。
浩然：水流不止的样子。
由：通“犹”。足用：足以。
悻悻（xìng xìng）然：不满貌，形容气量狭小的样子。见：现。
', '孟子离开齐国。尹士对人说：“不知道大王不能够做商汤、武王，那是不明智呀；知道他不能，但还是来了，那是来求富贵的吧。千里迢迢来见大王，不能投合而离开，歇了三个晚上才出昼邑，怎么这样慢腾腾的？我对这种情况不高兴。”
高子把这些话告诉了孟子。
孟子说：“那尹士哪能了解我呢？千里迢迢来见大王，是我所希望的。不能投合而离开，难道是我所希望的？我不得已啊。我歇了三个晚上才出昼邑，在我心里还是认为太快了，我心想，大王也许会改变态度的！大王若是改变了态度，就一定会让我回去。（等到）离开了昼邑，大王没有（派人）追我回去，我这才毅然下定决心回老家去。我虽然这么做，难道是要舍弃大王吗？大王还是足以做正事的，大王假如用我，那何止是齐国的百姓得到太平？天下的百姓都能得到太平。大王也许会改变态度的！我天天盼望！我难道像那种小气的汉子吗？向君王进谏而不被采纳，就发怒，气呼呼地表现在脸上，一旦离开，就走上一整天，没力气了才住下来吗？”
尹士听到这些话后，说：“我真是个小人呀！”
', NULL, '', 'indent', 1557829474, '5cda26bc7b968a007597d085', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642588, '孟子 · 第四卷 · 公孙丑下 · 第十三节 ', NULL, 21, 271, 3, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子去齐。充虞路问曰：“夫子若有不豫色然。前日虞闻诸夫子曰：‘君子不怨天，不尤人。’”
曰：“彼一时，此一时也。五百年必有王者兴，其间必有名世者。由周而来，七百有余岁矣。以其数则过矣，以其时考之则可矣。夫天，未欲平治天下也；如欲平治天下，当今之世，舍我其谁也？吾何为不豫哉？”', '', '不豫：不快。豫，悦，高兴。
不怨天，不尤人：这是孔子的话，见《论语·宪问》。尤，指责，责怪。
名世者：闻名于世的人。这里指德高望重，可以辅佐君王实现王道的人。
', '孟子离开齐国，充虞在路上问道：“先生似乎有点不太高兴。从前我听先生说过：‘君子不埋怨天，不责怪人。’”
孟子说：“那时是那个时候，现在是这个时候。每过五百年一定有圣王出现，那时一定有闻名于世的贤人。从周代以来，七百多年了。按年数算来，已经超过了五百；按照时势来考察，也该出现了。看来上天还不想使天下太平啊，如果想使天下太平，当今世上，除了我还有谁呢？我还有什么不高兴的呢？”
', NULL, '', 'indent', 1557829521, '5cda270fc8959c00688cd77a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642589, '孟子 · 第四卷 · 公孙丑下 · 第十四节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子去齐，居休。公孙丑问曰：“仕而不受禄，古之道乎？”
曰：“非也。于崇，吾得见王。退而有去志，不欲变，故不受也。继而有师命，不可以请。久于齐，非我志也。”', '', '休：地名，距孟子老家不远。
崇：地名。
师命：师旅之命。
', '孟子离开齐国，停住在休地。公孙丑问道：“做官却不接受俸禄，是古人的规矩吗？”
孟子说：“不是。在崇，我得以见到齐王。退出来后便有离开的意思，不想改变这种想法，所以不接受俸禄。后来齐国有战事，不好提出请求。长时间待在齐国，不是我的意愿啊。”
', NULL, '', 'indent', 1557829663, '5cda276143e78c0065d80435', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642590, '孟子 · 第五卷 · 滕文公上 · 第一节 ', NULL, 5, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '滕文公为世子，将之楚，过宋而见孟子。孟子道性善，言必称尧舜。
世子自楚反，复见孟子。孟子曰：“世子疑吾言乎？夫道一而已矣。成覸谓齐景公曰：‘彼丈夫也，我丈夫也，吾何畏彼哉？’颜渊曰：‘舜何人也？予何人也？有为者亦若是。’公明仪曰：‘文王我师也，周公岂欺我哉？’今滕，绝长补短，将五十里也，犹可以为善国。书曰：‘若药不瞑眩，厥疾不瘳。’”', '', '成覵（jiàn）：齐国的臣，以勇敢着称。
公明仪：孔子学生曾参的弟子，复姓公明，名仪。
瞑眩（miàn xuàn）：头昏。瘳（chōu）：痊愈。以上引语见今本《尚书·说命上》。
', '滕文公做太子时，（有一次）到楚国去，路过宋国时会见了孟子。孟子（给他）讲人性本善的道理，言语之间不离尧、舜。
太子从楚国回来，又来见孟子。孟子说：“太子怀疑我的话吗？道理只有一个而已。成覵对齐景公说：‘他是个男子汉，我也是个男子汉，我为什么害怕他呢？’颜渊说：‘舜是什么人呢？我是什么人呢？有所作为的人跟他一样。’公明仪说：‘文王，是我的老师；周公难道欺骗我吗？’现在滕国的土地，截长补短，将近五十里见方，仍然可以治理成一个好国家。《尚书》上说：‘如果药力不能使病人头晕目眩，那病是治不好的。’”
', NULL, '', 'indent', 1557829731, '5cda27e17f6fd30065ae7cb6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642591, '孟子 · 第五卷 · 滕文公上 · 第二节', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '滕定公薨。世子谓然友曰：“昔者孟子尝与我言于宋，于心终不忘。今也不幸至于大故，吾欲使子问于孟子，然后行事。”然友之邹问于孟子。
孟子曰：“不亦善乎！亲丧固所自尽也。曾子曰：‘生，事之以礼；死，葬之以礼，祭之以礼，可谓孝矣。’诸侯之礼，吾未之学也；虽然，吾尝闻之矣。三年之丧，齐疏之服，饘粥之食，自天子达于庶人，三代共之。”然友反命，定为三年之丧。
父兄百官皆不欲，曰：“吾宗国鲁先君莫之行，吾先君亦莫之行也，至于子之身而反之，不可。且志曰：‘丧祭从先祖。’”
曰：“吾有所受之也。”谓然友曰：“吾他日未尝学问，好驰马试剑。今也父兄百官不我足也，恐其不能尽于大事，子为我问孟子。”然友复之邹问孟子。
孟子曰：“然。不可以他求者也。孔子曰：‘君薨，听于冢宰。歠粥，面深墨。即位而哭，百官有司，莫敢不哀，先之也。’上有好者，下必有甚焉者矣。‘君子之德，风也；小人之德，草也。草尚之风必偃。’是在世子。”然友反命。
世子曰：“然。是诚在我。”五月居庐，未有命戒。百官族人可谓曰知。及至葬，四方来观之，颜色之戚，哭泣之哀，吊者大悦。


', '', '滕定公：滕文公的父亲。薨：侯王之死称“薨”。然友：滕文公做太子时的师傅。
自尽：指主动地尽孝心。
“曾子曰”数语：见《论语·为政》，本来是孔子对弟子樊迟说的话。这里引为曾子所说，大概曾子曾经以此教导弟子。
齐（zī）疏之服：粗布所制，缝了衣边的丧服。齐，缝衣边。疏，粗，指粗布。飦（zhān）：同“饘”，稠粥。粥：稀粥。
三代：夏商周三代。
父兄：指与滕文公同姓的老臣。百官：指与滕文公不同姓的百官。
宗国：宗主国。滕国和鲁国的始封祖分别是叔绣、周公，都是文王之子，而周公为长，所以滕国称鲁国为宗国。
《志》：史书。
冢宰：百官之长，后代称为“宰相”。
歠（chuò）：饮，喝。
尚：加。
庐：专供居丧时所住的房子，形制简陋。
知：知礼。
', '滕定公死了。太子对然友说：“以前孟子曾经同我在宋国交谈过，我心里始终没有忘记。现在不幸遇到了这大变故（我父王逝世了），我想请先生去请教一下孟子，然后才办丧事。”
然友到邹国去请教孟子。
孟子说：“不错呀。父亲的丧事是应该尽到自己的心意去办的事。曾子说：‘父母生前，按照礼来侍奉他们；死后，按照礼来埋葬他们，按照礼来祭祀他们，这样可以称得上孝了。’诸侯的礼，我没学过；尽管如此，我还是听说过的。守孝三年，穿着粗布缝边的丧服，喝着粥，从天子到平民百姓，夏、商、周三代都是一样的。”
然友回去复命，太子决定实行守孝三年的丧礼。父老百官都不愿意，说：“我们的宗国鲁国的历代君主都没这么办，我国历代的君主也没这么办，到了您这里却违反规矩，不行的。况且《志》上说：‘丧礼、祭礼遵循祖宗的成例。’”他们又说：“我们是有所根据的。”
太子对然友说：“我以前没做过学问，喜欢跑马舞剑。现在宗室百官都不满意我，担心我不能竭尽孝道办好丧事，请您替我再向孟子请教。”
然友又到邹国去请教孟子。
孟子说：“是啊。但这是不能要求别人的。孔子说：‘君主死了，政务听命于冢宰，太子只得喝粥，面色深黑，就临孝子之位便哭，大小官吏没有人敢不悲哀，这是因为太子带了头。’上面爱好什么，下面一定爱好得更厉害。尊贵者的德行，像风；卑微者的德行，像草。草上有风吹过，一定随之扑倒。这事全在太子怎么做。”
然友回去报告。
太子说：“是。这件事的关键的确实在于我怎么做。”
太子在丧庐住了五个月，没有发布任何政令。百官和族人都赞成，称道太子懂礼。到了举行葬礼的时候，四方宾客都来观礼，太子面容悲戚，哭声哀伤，使吊丧的人非常满意。
', NULL, '', 'indent', 1557829818, '5cda283630863b00706800e8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642592, '孟子 · 第五卷 · 滕文公上 · 第三节', NULL, 5, 271, 3, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '滕文公问为国。
孟子曰：“民事不可缓也。《诗》云：‘昼尔于茅，宵尔索绹；亟其乘屋，其始播百谷。’民之为道也，有恒产者有恒心，无恒产者无恒心。苟无恒心，放僻邪侈，无不为已。及陷乎罪，然后从而刑之。是罔民也。焉有仁人在位罔民而可为也？是故贤君必恭俭礼下，取于民有制。阳虎曰：‘为富不仁矣，为仁不富矣。’
“夏后氏五十而贡，殷人七十而助，周人百亩而彻，其实皆什一也。彻者，彻也；助者，藉也。龙子曰：‘治地莫善于助，莫不善于贡。’贡者，挍数岁之中以为常。乐岁，粒米狼戾，多取之而不为虐，则寡取之；凶年，粪其田而不足，则必取盈焉。为民父母，使民盻盻然，将终岁勤动，不得以养其父母，又称贷而益之，使老稚转乎沟壑，恶在其为民父母也？夫世禄，滕固行之矣。诗云：‘雨我公田，遂及我私。’惟助为有公田。由此观之，虽周亦助也。
“设为庠序学校以教之。庠者，养也；校者，教也；序者，射也。夏曰校，殷曰序，周曰庠；学则三代共之，皆所以明人伦也。人伦明于上，小民亲于下。有王者起，必来取法，是为王者师也。
“《诗》云：‘周虽旧邦，其命惟新。’文王之谓也。子力行之，亦以新子之国！”
使毕战问井地。
孟子曰：“子之君将行仁政，选择而使子，子必勉之！夫仁政，必自经界始。经界不正，井地不钧，谷禄不平，是故暴君污吏必慢其经界。经界既正，分田制禄可坐而定也。
“夫滕，壤地褊小，将为君子焉，将为野人焉。无君子，莫治野人；无野人，莫养君子。请野九一而助，国中什一使自赋。卿以下必有圭田，圭田五十亩；余夫二十五亩。死徙无出乡，乡田同井，出入相友，守望相助，疾病相扶持，则百姓亲睦。方里而井，井九百亩，其中为公田。八家皆私百亩，同养公田；公事毕，然后敢治私事，所以别野人也。此其大略也；若夫润泽之，则在君与子矣。”

', '', '引诗出《诗经·豳风·七月》。
尔：语助词，无义，于：往。茅：取茅。索：搓。绹（táo）：绳子。
亟：急，赶快。乘屋：登屋顶，指修理草房。始：岁始，年初。
阳虎：即阳货，鲁国大夫季氏的家臣，与孔子同时。
夏后氏：以禹为首领的古代氏族部落，到禹的儿子启时建立了夏王朝。五十而贡：传说夏代每户授田五十亩，每户上缴一定的收成作为地租。这与下文的“助”“彻”，都是儒家说的土地税法，在历史上未必实行过。
龙子：古代贤人。
挍（jiào）：同“校”，比较。
狼戾：狼藉。
盻盻（xì）然：勤苦不得休息的样子。
雨（yù）：下雨。引诗出《诗经·小雅·大田》。
庠（xiáng）序学校：庠、序、校，都是乡里学校；学，国立学校。
射（yì）：通“绎”，陈列，指陈列人伦秩序以教导。
引诗出自《诗经·大雅·文王》。
毕战：滕国的臣。
钧：通“均”。
经界：土地、疆域的分界。
圭田：俸禄以外另授给官吏的田，供祭祀用。
', '滕文公问怎样治国。
孟子说：“老百姓的事情不能拖。《诗经》上说：‘白天去割茅草，晚上把绳搓好；赶紧上房修屋，开春就要播种百谷。’老百姓中的情况是，有固定产业的人会有坚定的心志，没有固定产业的就不会有坚定的心志。假如没有坚定的心志，就会为非作歹，无所不为。等他们犯了罪，然后处罚他们，这叫陷害百姓。哪有仁德的人在位治国却做出陷害百姓的事来？所以英明的君王一定严肃而节俭，对下级有礼，向百姓征税有一定的制度。阳虎说：‘要发财致富就不能讲仁义，要讲仁义就不能发财致富。’
“夏代每户五十亩地，实行贡法；商代每户亩地，实行助法，周代每户一百亩地，实行彻法。其实质都是抽取十分之一税率的地租。彻，是‘通’的意思；助，是‘借’的意思。龙子说：‘地租中没有比助法更好，没有比贡法更不好的。’贡法，是比较几年中的收成以确定一个平均数，作为每年收税的税额。如果年成好，粮食就多得满地狼藉，多收一些地租也不算暴虐，倒收得少；如果年成不好，收成还不够来年施肥的费用，地租却一定要收到满额。做老百姓的父母官，却使老百姓累得惨兮兮，而且终年辛苦劳作，还不够养活父母，还得借高利贷来凑足地租，使老的小的抛尸露骨于山沟之中，这哪里是为民父母呢？做官的人有世袭的俸禄，滕国早就实行了。《诗经》说：‘下雨下到我公田，然后又到我私田。’只有借力助耕才谈得上‘公田’。由此看来，即使周代的制度其实质也还是助法。
“又设立庠、序、学、校来教导百姓。庠，是教养的意思；校，是教导的意思；序，是陈列的意思。乡里学校，夏代叫‘校’，商代叫‘序’，周代叫‘庠’；国立学校则三代都叫‘学’，都是使人明白伦理道德的。上面的人明白伦理道德，下面的平民百姓自然爱戴他们。如果有圣王出现，一定要来取法，这就成了圣王的师傅了。
“《诗经》上说：‘岐周虽是古老的邦国，却新接受了新的天命。’这是讲的文王。您努力实行吧，也以此来使您的国家气象一新。”
滕文公让毕战来问井田制。
孟子说：“你的君王要实行仁政，选派你（到我这里来），你一定要尽力。仁政一定要从划分田界做起。划分田界如果不公正，井田就分得不均匀，作为俸禄的谷物田租也就收得不公平了，所以暴君污吏一定把划分田界当儿戏。田界如果划得公正，分发田地、订立俸禄制度，就可以轻易办妥了。
“滕国虽土地狭小，但也有当官的，也有种田的。没有当官的人，就没人管理种田的，没有种田的，就没人养活当官的。建议在郊野实行九分抽一的助法，在城市实行十分抽一的贡法。卿以下官吏都授给圭田，圭田的大小是五十亩。家里还有剩余劳力的，另授田二十五亩。老死或搬家，也不离开本乡，乡里同一井田的人家，出入相伴，防盗御寇互相帮助，有病互相照料，于是老百姓就会彼此亲爱，相处和睦。纵横方圆一里的地为一个井田，每个井田九百亩，当中一百亩是公田。八家都授给私田一百亩，共同耕种公田。公田里的活干完了，然后才敢干私田的活，以此来区别当官的和种田的。这就是井田制的大概。至于调整润饰，关键就在于你的国君和你（的努力）了。”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b46b466a763596afebe43", "shortContent": " 滕文公是战国中期一位深受孟子思想影响的小国君主。在作世子时，他曾两次拜见孟子，向其请教治国之道。其父滕定公死后，他专门派大臣去向孟子请教治丧之礼，采纳并践行了孟子关于三年之丧的建议。在其即位之后不久，孟子从邹国来到了滕国，于是便与滕国君臣有了本篇中的这样一番对话。\n\n这篇对话的中心内容是教滕文公行仁政，仁政作为孟子政治哲学的主要理念，其实质就是将仁义等道德精神贯彻到社会、国家的治理之中，即其所谓...", "authors": ["丁笃敬", "宋道贵"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557829984, '5cda28da43e78c0065d81509', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642641, '孟子 · 第八卷 · 离娄下 · 第九节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“言人之不善，当如后患何？”
', '', '', '孟子说：“宣扬别人的不好，该怎么对付后患呢？”
', NULL, '', 'indent', 1557915379, '5cdb767243e78c00686baab7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642593, '孟子 · 第五卷 · 滕文公上 · 第四节 ', NULL, 27, 271, 6, 2, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '有为神农之言者许行，自楚之滕，踵门而告文公曰：“远方之人闻君行仁政，愿受一廛而为氓。”
文公与之处。
其徒数十人，皆衣褐，捆屦、织席以为食。
陈良之徒陈相与其弟辛，负耒耜而自宋之滕，曰：“闻君行圣人之政，是亦圣人也，愿为圣人氓。”
陈相见许行而大悦，尽弃其学而学焉。
陈相见孟子，道许行之言曰：“滕君则诚贤君也，虽然，未闻道也。贤者与民并耕而食，饔飧而治。今也滕有仓廪府库，则是厉民而以自养也，恶得贤？”
孟子曰：“许子必种粟而后食乎？”
曰：“然。”
“许子必织布然后衣乎？”
曰：“否！许子衣褐。”
“许子冠乎？”
曰：“冠。”
曰：“奚冠？”
曰：“冠素。”
曰：“自织之与？”
曰：“否，以粟易之。”
曰：“许子奚为不自织？”
曰：“害于耕。”
曰：“许子以釜甑爨，以铁耕乎？”
曰：“然。”
“自为之与？”
曰：“否！以粟易之。”
“以粟易械器者，不为厉陶冶；陶冶亦以其械器易粟者，岂为厉农夫哉？且许子何不为陶冶，舍皆取诸其宫中而用之？何为纷纷然与百工交易？何许子之不惮烦？”
曰：“百工之事固不可耕且为也。”
“然则治天下独可耕且为与？有大人之事，有小人之事。且一人之身，而百工之所为备，如必自为而后用之，是率天下而路也。故曰，或劳心，或劳力；劳心者治人，劳力者治于人；治于人者食人，治人者食于人，天下之通义也。
“当尧之时，天下犹未平，洪水横流，泛滥于天下，草木畅茂，禽兽繁殖，五谷不登，禽兽偪人，兽蹄鸟迹之道交于中国。尧独忧之，举舜而敷治焉。舜使益掌火，益烈山泽而焚之，禽兽逃匿。禹疏九河，瀹济漯而注诸海，决汝汉，排淮泗而注之江，然后中国可得而食也。当是时也，禹八年于外，三过其门而不入，虽欲耕，得乎？
“后稷教民稼穑，树艺五谷；五谷熟而民人育。人之有道也。饱食、暖衣、逸居而无教，则近于禽兽。圣人有忧之，使契为司徒，教以人伦，父子有亲，君臣有义，夫妇有别，长幼有叙，朋友有信。放勋曰：‘劳之来之，匡之直之，辅之翼之，使自得之，又从而振德之。’圣人之忧民如此，而暇耕乎？
“尧以不得舜为己忧，舜以不得禹、皋陶为己忧。夫以百亩之不易为己忧者，农夫也。分人以财谓之惠，教人以善谓之忠，为天下得人者谓之仁。是故以天下与人易，为天下得人难，孔子曰：‘大哉尧之为君！惟天为大，惟尧则之，荡荡乎民无能名焉！君哉舜也！巍巍乎有天下而不与焉！’尧舜之治天下，岂无所用其心哉？亦不用于耕耳。吾闻用夏变夷者，未闻变于夷者也。陈良，楚产也，悦周公、仲尼之道，北学于中国。北方之学者，未能或之先也。彼所谓豪杰之士也。子之兄弟事之数十年，师死而遂倍之！昔者孔子没，三年之外，门人治任将归，入揖于子贡，相向而哭，皆失声，然后归。子贡反，筑室于场，独居三年，然后归。
他日，子夏、子张、子游以有若似圣人，欲以所事孔子事之，强曾子。曾子曰：‘不可；江汉以濯之，秋阳以暴之，皜皜乎不可尚已。’今也南蛮鴂舌之人，非先王之道，子倍子之师而学之，亦异于曾子矣。吾闻出于幽谷迁于乔木者，未闻下乔木而入于幽谷者。《鲁颂》曰：‘戎狄是膺，荆舒是惩。’周公方且膺之，子是之学，亦为不善变矣。”
“从许子之道，则市贾不贰，国中无伪，虽使五尺之童适市，莫之或欺。布帛长短同，则贾相若；麻缕丝絮轻重同，则贾相若；五谷多寡同，则贾相若；屦大小同，则贾相若。”
曰：“夫物之不齐，物之情也；或相倍蓰，或相什百，或相千万。子比而同之，是乱天下也。巨屦小屦同贾，人岂为之哉？从许子之道，相率而为伪者也，恶能治国家？”
', '', '神农之言：指农家学说。神农，上古传说中发明耜、耒，教民稼穑的人物，农家托为宗师。许行：楚国人，战国时期的农民学家。
廛（chán）：民居。氓：从别处迁来的人。
褐：麻制的短衣。屦（jù）：草鞋。
陈良：楚国的儒家人物。耒耜（lěisì）：翻土的农具。耜是起土的部分，耒为其柄。
饔飧（yōngsūn）：熟食。这里指做饭。饔，早餐。飧，晚餐。
厉：病，残害。
釜：无脚的锅。甑（zèng）；陶制烹饪器。爨（cuàn）：做饭。
械器：器物。舍：止，不肯。宫：室，房。陶冶：指烧制陶器和冶炼金属的工匠。
路：同“露”，败亡。
五谷：指稻、黍、稷、麦、菽。稻即水稻，黍即黄米，稷即小米，麦即小麦，菽是豆类的总名。登：成熟。偪（bī）：即逼。
敷：遍，全都。
益：舜的臣。
瀹（yuè）：疏导。济、漯（tà）：二水名。
决、排：都是去除障碍使㈠水畅通的意思。汝汉、淮泗：为四个水名。，
后稷：名弃，周人的始祖，尧时为农师。艺：种植。
契（xiè）：殷人的始祖。司徒：官名。
放勋：尧的名。
劳之来之：使他们勤劳。劳、来，都是勤劳的意思，这里用作动词。
皋陶（gāoyáo）：亦作皋繇，舜时的司法官。
易：治理。
巍巍，高大的样子。引孔子语见《论语·泰伯》。
倍：通“背”。
任：担、负，指行李。治任：整修扁担。
秋：指周历七，八月，相当于夏历五、六月，正当盛暑。暴（pù）：晒。皜皜（hàohào）：洁白的样子。
鴂（jué）舌：形容说话怪腔怪调像鸟叫一样。鴂，伯劳鸟。“南蛮鴂舌之人”，指许行。
出于幽谷迁于乔木：语出《诗经·小雅·伐木》：“伐木丁丁，鸟鸣嘤嘤。出自幽谷，迁于乔木。”
膺（yīng）：抵挡，防范。荆：楚国的别名。舒：楚的属国。引诗出自《诗经·鲁颂·閟宫》。戎狄：古代西方的部族叫做“戎”；北方的部族叫做“狄”。
贾：价。下同。五尺：大约相当于今天的三尺半。
蓰（xǐ）：五倍。
巨屦（jù）：粗糙的鞋。小屦：精细的鞋。
', '有个奉行神农氏学说的人叫许行，从楚国来到滕国，上门对文公说：“我这个大老远来的人听说您正在实行仁政，希望能得到一个住所，成为侨民。”
文公给了他房屋。
他的门徒有几十个，都穿着麻衣，以编草鞋、织席子为生。
陈良的门徒陈相和他的弟弟陈辛，背着耒耜从宋国来到滕国，对文公说：“听说您正在实行圣人的政治，这也是圣人了，我希望做圣人的侨民。”
陈相见了许行，十分高兴，完全抛弃以前的学问而向许行学习。
陈相见了孟子，引述许行的话说：“滕君确实是个贤明的君主，尽管如此，他却不真懂得道理。贤人是和老百姓一同耕作才吃饭，自己做饭，又治国理政。现在滕国有粮仓，有库房，这是残害人民来养活自己，这又怎能称得上贤明？”
孟子说：“许子一定自己种庄稼才吃饭吗？”
陈相说：“对。”
“许子一定自己织布才穿衣吗？”
陈相说：“不。许子穿麻衣。”
“许子戴帽子吗？”
陈相说：“戴。”
孟子说：“戴什么帽子？”
陈相说：“戴白帽子。”
孟子说：“是自己织的吗？”
陈相说：“不。是用粮食换来的。”
孟子说：“许子为什么不自己织呢？”
陈相说：“那会耽误耕种。”孟子说：“许子用釜甑做饭，用铁器耕田吗？”
陈相说：“对。”
“是自己造的吗？”
陈相说：“不。是用粮食换来的。”
“农夫拿粮食交换（生活、生产所需的）器具，不算是侵害陶工和冶匠；陶工和冶匠也拿他们的器具交换粮食，难道就是侵害了农夫的利益了吗？再说，许子为什么不自己制陶、冶铁，停止交换，不肯样样东西都从自家屋里取来用？为什么要忙忙碌碌同各种工匠交换呢？为什么许子这样不怕麻烦呢？”
陈相说：“各种工匠，本来就不能一边耕种一边又干他们的事情。”
“那么，难道治理天下可以一边耕种一边又干他们的事情吗？有官吏的事情，有平民的事情。而且一个人，就需要各行各业的产品。如果一定要自己造出来的才用，这是让天下人疲于奔命。所以说：有人劳动脑力，有人劳动体力；劳动脑力的管理人，劳动体力的被人管理；被人管理的养活人，管理人的被人养活。这是天下通行的道理。
“在尧的时候，天下还不太平，洪水不循水地道乱流，到处泛滥。草木长得又快又茂密，禽兽成群地繁殖，五谷不熟，禽兽害人。野兽的蹄印和飞鸟的踪迹，在中国纵横交错。尧一个人为此忧虑，选拔舜处理全部事务。舜命令伯益掌管火政，益在山野沼泽放火，烧掉草木。禽兽或逃跑或隐藏。禹又疏浚九条河道，疏导济水和源水，使之入海；导引汝水和汉水，疏通淮水和泗水，使之流入长江，这样中国才可以种庄稼了。在那时候，禹在外八年，三次从家门口路过都没进门，即使他想耕种，可能吗？
“后稷教老百姓种庄稼，栽培五谷，五谷成熟而人民得到养育。人是有善良天性的，但吃饱了、穿暖了、住安逸了却不加教育，就和禽兽差不多。圣人又为此忧虑，让契做司徒，用伦理道德来教育人民：父子之间有慈爱，君臣之间有礼义，夫妇之间有区别，老少之间有等级，朋友之间有诚信。尧说：‘敦促他们，纠正他们，帮助他们，使他们各得其所，又加以栽培和引导。’圣人为老百姓忧虑，到了这种地步，还有闲工夫来种庄稼吗？
“尧把得不到舜作为自己的忧虑，舜把得不到禹和皋陶作为自己的忧虑。把百亩田地耕种得不好作为自己的忧虑，那是农夫。把钱财送给别人叫做惠，把善良教给别人叫做忠，为天下找到人才叫做仁。所以把天下让给别人是容易的，为天下找到人才是困难的。孔子说：‘伟大啊，尧做君主！只有天最伟大，只有尧效法天，那宽广的气象，老百姓没办法用言语来形容！了不起的君主啊，舜呀！光明正大地统治天下而毫不利己！’尧、舜治理天下，难道无所用心吗？只不过不用于种庄稼罢了。
“我听说过中原改变落后的蛮夷，没听说过中原被蛮夷改变的。陈良，是楚国人，喜爱周公，孔子的学说，北上到中原来学习。北方的学者，没有人能超过他。他真是所谓豪杰之士啊。你们兄弟向他学习了几十年，老师死后就背叛他。从前，孔子去世，弟子们守丧三年以后，收拾行李准备回家，进门向子贡作揖告别，大家相对而哭，泣不成声，然后才各自回去。子贡回到墓地，在墓边的灵场盖了间房，又独自住了三年，然后才回去。过些时候，子夏、子张、子游认为有若像孔子，就想要像服侍孔子那样服侍他，强求曾子同意。曾子说：‘不行的。老师就像在长江、汉水洗涤过，就像在夏天的烈日下暴晒过，光辉洁白得无以复加。’如今南方蛮族里讲鸟语的人，也来非难我们祖先圣王的学说，你竟背叛你的老师而向他学习，和曾子真不一样啊。我听说过飞出幽暗山谷而迁到高大树木的，没听说过飞下高大树木而进到幽暗山谷里去的。《诗经·鲁颂》里说：‘戎狄是要防范的，荆舒是要严惩的。’周公尚且要防范他们，你却向他们学，真是不懂得用中国来改变蛮夷的道理啊。”
陈相说：“如果听从许子的主张，就能做到同一货物的市价一致，国内没有欺诈行为。即使打发五尺高的小孩到市场去，也没人欺骗他。布帛的长短如果一样，价格就相同；麻线丝绵的轻重如果一样，价格就相同；谷物的多少如果一样，价格就相同；鞋的大小如果一样，价格就相同。”
孟子说：“货物的品相质量各不相同，这是自然的；有的相差一倍五倍，有的相差十倍百倍，有的相差千倍万倍。你要只以大小轻重相比而使它们价格相同，这是扰乱天下。做工粗糙的鞋与做工精细的鞋同一个价钱，人们难道还肯做（做工好的鞋）吗？听从许子的主张，就是带着大家做假，哪还能够治理好国家？”
', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d12cee9a0c24edae23", "shortContent": "本篇节选自《孟子·滕文公上》。滕（今山东滕县）是个小国，介于齐、楚两大国之间。滕文公是孟子周游列国碰到的唯一信服孟子主张的国君。这篇文章是在滕文公接受孟子意见，国家很有声望时发生的一场辩论，是孟子对农家思想的有力批判和对儒家治国主张的根本方针的进一步发挥。从这场论辩中我们可以看到孟子善辩的高度技巧和他对社会分工的具体思想。\n全文可按内容分成六大段。第一段是论辩的起因，可以分三个层次。从开始到“捆屦...", "authors": ["周本淳"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b46dde49f46528a428d81", "shortContent": "战国时期，学派蜂起，百家争鸣，农家就是其中有一定影响的一家。农家假托神农氏立言，其基本主张是，不论是天子还是庶民，都应当从事农业劳动，自食其力。他们还总结了古代的农业技术。农家的著作流传下来的很少，《孟子》这一部分就保存了关于农家思想的一些十分可贵的材料，虽然它们是作为批判的对象放在文中的。\n\n从文中我们可以看到农家的主张与实践在当时还是相当有吸引力的，跟随农家人物许行从楚国到滕国来的有数十人，他...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557830230, '5cda29ce7f6fd30065ae9b4b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642594, '孟子 · 第五卷 · 滕文公上 · 第五节 ', NULL, 6, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '墨者夷之，因徐辟而求见孟子。孟子曰：“吾固愿见，今吾尚病，病愈，我且往见，夷子不来！”他日又求见孟子。
孟子曰：“吾今则可以见矣。不直，则道不见；我且直之。吾闻夷子墨者。墨之治丧也，以薄为其道也。夷子思以易天下，岂以为非是而不贵也？然而夷子葬其亲厚，则是以所贱事亲也。”徐子以告夷子。
夷子曰：“儒者之道，古之人‘若保赤子’，此言何谓也？之则以为爱无差等，施由亲始。”徐子以告孟子。
孟子曰：“夫夷子，信以为人之亲其兄之子为若亲其邻之赤子乎？彼有取尔也。赤子匍匐将入井，非赤子之罪也。且天之生物也，使之一本，而夷子二本故也。盖上世尝有不葬其亲者。其亲死，则举而委之于壑。他日过之，狐狸食之，蝇蚋姑嘬之。其颡有泚，睨而不视。夫泚也，非为人泚，中心达于面目。盖归反虆梩而掩之。掩之诚是也，则孝子仁人之掩其亲，亦必有道矣。”徐子以告夷子。夷子怃然为间曰：“命之矣。”


', '', '墨者：信奉墨子学说的人。夷之：姓夷之。徐辟：孟子弟子。
若保赤子：语出《尚书·康诰》：“若保赤子，惟民其康父。”
取：取譬，打比方。
一本、二本：孟子的意思是，人都是父母所生，这便是天所指定的唯一根源，而墨家主张爱无等差，就把父母和陌路人等同起来，所以说是“二本”。
蚋（ruì）：蚊子。姑（gū）：咀。嘬（chuài）：叮，咬。
颡（sǎng）：额头。泚（cǐ）：出汗的样子。睨（nì）：斜视。视：正视。
虆（léi）：盛土的笼。梩（lí）：锹、锸一类挖土的工具。
', '墨家学派的夷之通过徐辟求见孟子。孟子说：“我本来愿意接见，现在我还病着。等病好了，我将去见他，夷子不必来。”
（过了些日子，）夷子又求见孟子。孟子说：“我现在可以见他了。如果不直言，真理就不能显现；我姑且直截了当地说。我听说夷子是墨家的信徒，墨家办丧事，以薄葬为原则；夷子想拿这个来改变天下的风俗，难道认为不这样做就不可贵，但夷子埋葬他的父母却是很丰厚的，那么他是以自己所鄙薄的来侍奉父母了。”
徐子把这些话转告给夷子。
夷子说：“儒家的学说认为，古人‘爱护百姓就像爱护婴儿’，这话是什么意思呢？我认为意思就是爱没有亲疏厚薄的区别，只不过实行起来是从父母亲开始的。”
徐子把这些话转告给孟子。
孟子说：“夷子真的以为一个人爱自己的兄弟的儿子同他爱邻居家的婴儿是一样的吗？那句话只是打个比方嘛。婴儿在地上爬，快要掉到井里去了，那不是婴儿的罪过；老百姓犯了错误，也不是他的罪过。‘爱护百姓就像爱护婴儿’，是这个意思，不是说爱没有亲疏厚薄之别。而且天生养万物，使万物只有一个根源，而夷子却有两个根源。大概上古曾经有不埋葬父母亲尸体的人。父母死了，就把尸体抛到山沟里。过些时候他路过那里，狐狸正吃着尸体，成群的苍蝇蚊子正叮咬着尸体。他的额上出了汗，只敢斜视而不敢正视了。出汗呢，不是出给别人看的，是心里的悲痛流露在脸上。大概他会回去取来簸箕、铁锹把尸体掩埋了。掩埋了尸体就对了。那么，孝子、仁人掩埋父母亲的尸体，也就必然有他（讲究方式的）道理啊。”
徐子把这些话转告夷子。夷子怅然若失，过了一会儿，说：“他教我懂得道理了。”
', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3faa7d0ac1145496bcf8", "shortContent": "本篇着重写一位狐妻料事如神的“特异功能”。\n徐某沾染上了赌博的不良习气。每逢他外出赌钱时，狐妻总是交给他一个钱袋；丈夫赌输了，到最后一局结账时，口袋中钱的数目恰好和他输的钱数相等，毫厘不爽。\n这个例子安排在文章的开头部分，一方面与前文中“举止如常人”形成鲜明的对比和强烈的反差——她的思维异于常人；另一方面也为后文中她的料事如神埋下了伏笔。\n徐某心地善良。他看到富家的仆人因为遗失了主人的金钏而不得不...", "authors": ["储有明"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557830297, '5cda2a1643e78c00698a3979', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642595, '孟子 · 第六卷 · 滕文公下 · 第一节 ', NULL, 7, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '陈代曰：“不见诸侯，宜若小然；今一见之，大则以王，小则以霸。且志曰：‘枉尺而直寻’，宜若可为也。”
孟子曰：“昔齐景公田，招虞人以旌，不至，将杀之。志士不忘在沟壑，勇士不忘丧其元。孔子奚取焉？取非其招不往也，如不待其招而往，何哉？且夫枉尺而直寻者，以利言也。如以利，则枉寻直尺而利，亦可为与？昔者赵简子使王良与嬖奚乘，终日而不获一禽。嬖奚反命曰：‘天下之贱工也。’或以告王良。良曰：‘请复之。’强而后可，一朝而获十禽。嬖奚反命曰：‘天下之良工也。’简子曰：‘我使掌与女乘。’谓王良。良不可，曰：‘吾为之范我驰驱，终日不获一；为之诡遇，一朝而获十。诗云：“不失其驰，舍矢如破。”我不贯与小人乘，请辞。’御者且羞与射者比。比而得禽兽，虽若丘陵，弗为也。如枉道而从彼，何也？且子过矣，枉己者，未有能直人者也。”', '', '陈代：孟子弟子。
小：小节。
枉尺而直寻：屈一尺可得伸直八尺；寻，八尺。意思是小有所屈必大有收获。
招虞人以旌：古代君王有所召唤，视所召唤者的身份地位出示相应的信物，旌是召唤大夫所用，召唤虞人该用皮冠。虞人，守苑囿的吏。
赵简子：晋国正卿赵鞅。王良：春秋末年善于驾车的人。奚：人名。
范：法度。
诡遇：指不依法度驾驭。
舍矢：发箭。如：而。破：破的，指射中猎物。引诗见《诗经·小雅·车攻》。
比：合作。

', '陈代（对孟子）说：“不去谒见诸侯，好像有些过分拘泥小节似的。现在您去见一见，从大处说可以行仁政使天下归服，从小处说可以成就霸者的事业。何况《志》上说：‘委曲一尺可以伸张八尺’，好像是值得去做的。”
孟子说：“从前齐景公打猎，（误）用旌旗召唤管猎场的小吏（当用皮冠招之），小吏不来，齐景公要杀他。有志之士不怕弃尸沟壑，勇敢的人不怕丢掉脑袋。孔子称赞他什么？就是称赞他这一点：不是用召唤他的礼数的召唤，他就不去。假如不等待人家的召唤就去，那算什么？况且所谓委曲一尺而伸张八尺，这是根据功利来说的。如果以功利为根据，那么，委曲八尺伸张一尺而有利，也可以做吗？从前赵简子命令王良为他的宠幸小臣奚驾车，一整天都没有猎获一只禽兽。小臣奚回去禀告说：‘王良是个拙劣的驾车人。’有人把这话告诉王良。王良说：‘请让我再来一次。’奚勉强同意了，一个上午就猎获了十只禽兽。小臣奚回去禀告说：‘王良是个很能干的驾车人。’赵简子说：‘我让他专门为你驾车。’就跟王良说。王良不同意，说：‘我为他规规矩矩驾车，一整天打不着一只；为他不守规矩驾车，一个上午就打到了十只。《诗经》说：“跑起车来中规矩，发出的箭就能射中。”我不习惯为小人驾车，请允许我推辞。’驾车人尚且羞于跟坏射手合作；合作而猎获禽兽，即使是堆积如山，也不愿干了。假如委曲真理而跟从诸侯，那又算什么？再说，你的说法也不对呀，背弃自己主张（变得不正直）的人，是不能去改正别人（让别人变得正直）的。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0f2", "shortContent": "这句话的意思是说，自己不正直，也就不能够要求别人正直。这是孟子教育弟子陈代的话。陈代希望孟子不要拘泥于小节，他认为即使是违背礼义去拜见诸侯，如果能因此得到重用，从而实现仁政，统一天下，也是可以做的。陈代的这种看法，正反映了当时士人们的实际情况：他们纷纷向诸侯国君进言献策，宣扬自己的政治主张和治国策略，希望得到国君的赏识，从而达到建功立业、出人头地的目的。其中许多人为了迎合国君而放弃操守，不顾道义，...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1557830396, '5cda2a6a0237d70069f9bc32', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642596, '孟子 · 第六卷 · 滕文公下 · 第二节 ', NULL, 79, 271, 3, 4, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '景春曰：“公孙衍、张仪岂不诚大丈夫哉？一怒而诸侯惧，安居而天下熄。”
孟子曰：“是焉得为大丈夫乎？子未学礼乎？丈夫之冠也，父命之；女子之嫁也，母命之，往送之门，戒之曰：‘往之女家，必敬必戒，无违夫子！’以顺为正者，妾妇之道也。居天下之广居，立天下之正位，行天下之大道。得志与民由之，不得志独行其道。富贵不能淫，贫贱不能移，威武不能屈。此之谓大丈夫。”', '', '景春：纵横家。
公孙衍、张仪：都是著名策士。
冠：古时男子二十岁行加冠礼，表示已成人。
女家：通“汝家”，指夫家。夫子：指丈夫。
广居；指“仁”。正位：指“礼”。大道：指“义”。
淫：过分，指态度傲慢骄狂。
', '景春说：“公孙衍、张仪难道不是真正的大丈夫吗？他们一发怒，诸侯就害怕，他们安定下来，天下的战火就熄灭。”
孟子说：“这哪里称得上大丈夫呢？你没学过礼吗？男子举行冠礼的时候，父亲训导他。女子出嫁的时候，母亲训导她，送她到门口，告诫她说：‘到了你家，一定要恭敬，一定要警惕，不要违背丈夫！’（公孙衍、张仪在诸侯面前竟也像女子一样！）把顺从当作标准，这是妇女的原则。住在天下最宽广的住宅——仁——里，站在天下最中正的位置——礼——上，走在天下最开阔的大路——义——上；得志的时候，和老百姓一道走，不得志的时候，自己走自己的路。富贵不能使他骄狂，贫贱不能改变他的心志，威武不能使他屈服，这样才叫做大丈夫。”', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b4723c98d685fd9d84cab", "shortContent": "景春是战国中期研究纵横权谋之术的学者，他自然很佩服公孙衍、张仪那样的著名纵横家，认为他们才是“大丈夫”。不料孟子却来了个当头棒喝：他们哪能算大丈夫！他们只能算是小媳妇！因为他们只是“以顺为正”，一味顺从统治者的意志。接下来文章一口气用几个对仗工整的排比句，指明什么样的人才是真正的大丈夫。这些句子从视觉上看，端庄整齐，错落有致，具有结构美的特点；从听觉来说，铿锵有力，抑扬顿挫，具有音乐美的特点。几句...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557830464, '5cda2abd7b968a00759809b8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642642, '孟子 · 第八卷 · 离娄下 · 第十节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“仲尼不为已甚者。”
', '', '', '孟子说：“孔子不做过火的事情。”
', NULL, '', 'indent', 1557915400, '5cdb768630863b00696a8077', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642643, '孟子 · 第八卷 · 离娄下 · 第十一节 ', NULL, 13, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“大人者，言不必信，行不必果，惟义所在。”
', '', '', '孟子说：“作为大人物，说话不一定都讲信用，做事不一定非有结果不可，只看是否合乎义。”
', NULL, '', 'indent', 1557915422, '5cdb769b17b54d0068e01242', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642597, '孟子 · 第六卷 · 滕文公下 · 第三节', NULL, 4, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '周霄问曰：“古之君子仕乎？”
孟子曰：“仕。传曰：‘孔子三月无君，则皇皇如也，出疆必载质。’公明仪曰：‘古之人三月无君则吊。’”
“三月无君则吊，不以急乎？”
曰：“士之失位也，犹诸侯之失国家也。礼曰：‘诸侯耕助，以供粢盛；夫人蚕缫，以为衣服。牺牲不成，粢盛不洁，衣服不备，不敢以祭。惟士无田，则亦不祭。’牲杀器皿衣服不备，不敢以祭，则不敢以宴，亦不足吊乎？”
“出疆必载质，何也？”
曰：“士之仕也，犹农夫之耕也，农夫岂为出疆舍其耒耜哉？”
曰：“晋国亦仕国也，未尝闻仕如此其急。仕如此其急也，君子之难仕，何也？”
曰：“丈夫生而愿为之有室，女子生而愿为之有家。父母之心，人皆有之。不待父母之命、媒妁之言，钻穴隙相窥，逾墙相从，则父母国人皆贱之。古之人未尝不欲仕也，又恶不由其道。不由其道而往者，与钻穴隙之类也。”


', '', '周霄：魏国人。
皇皇：形容心不安的样子。质：通“贽”，指见面礼。
助：即“藉”，指藉田，天子和诸侯都有藉田，天子千亩，诸侯百亩。粢（zī）盛（chéng）：祭品，指盛在祭器里的黍稷。
夫人：指诸侯的正妻。缫（sāo）：抽茧出丝。
牺牲：为祭祀所杀的牲畜。
晋国：指魏国。战国时韩、赵、魏三国，系由晋国分出，称为“三晋”，故魏国自称为晋。
', '周霄问道：“古代的君子做官吗？”
孟子说：“做官。《传》说：‘孔子三个月没有君主任用他，就会忧心忡忡而不安，离开一个国家一定带着备用的（去下一个国家）见面礼。’公明仪说：‘古代的人，三个月没有君主任用，就要去安慰他。’”
（周霄说：）“三个月没有被君主任用，就要去安慰，（这）不是求官太迫切了吗？”
孟子说：“士人失去官位，就好比诸侯失掉了国家。《礼》说：‘诸侯亲自耕种藉田，来供给祭品；夫人亲自养蚕缫丝，来供给祭服。牲畜不肥壮，谷物不干净，祭服不具备，就不敢祭祀。士如果没有田地，那也不能祭祀。’牲畜、祭器、祭服不具备，不敢祭祀，那也就不敢办宴会，这还不该去安慰他吗？”
（周霄说：）“离开一个国家一定带着备用的见面礼，这又是为什么？”
孟子说：“士人做官，就好比农夫耕田；农夫难道因为离开一个国家就扔掉他的农具（耒和耜）吗？”
周霄说：“魏国也是一个有官可做的国家，我却不曾听说做官要这么着急的。做官既然是这么急迫的事，君子却不轻易做官，为什么？”
孟子说：“男孩子，一出生，（父母）便希望为他找到妻室，女孩子，一出生，（父母）便希望为她找到婆家，父母亲的这种心情，人人都有。但是，如果没有父母的命令、媒人的言语，就钻墙洞、扒墙缝互相窥视，爬墙相会，那么，父母和其他人就都会看不起他。古代的人不是不想做官，但又厌恶不从正道找官做。不从正道去做官的，跟钻墙洞、扒墙缝是一样的。”
', NULL, '', 'indent', 1557830529, '5cda2af2c8959c00688d0fc0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642598, '孟子 · 第六卷 · 滕文公下 · 第四节 ', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '彭更问曰：“后车数十乘，从者数百人，以传食于诸侯，不以泰乎？”
孟子曰：“非其道，则一箪食不可受于人；如其道，则舜受尧之天下，不以为泰，子以为泰乎？”
曰：“否。士无事而食，不可也。”
曰：“子不通功易事，以羡补不足，则农有余粟，女有余布；子如通之，则梓匠轮舆皆得食于子。于此有人焉，入则孝，出则悌，守先王之道，以待后之学者，而不得食于子。子何尊梓匠轮舆而轻为仁义者哉？”
曰：“梓匠轮舆，其志将以求食也；君子之为道也，其志亦将以求食与？”
曰：“子何以其志为哉？其有功于子，可食而食之矣。且子食志乎？食功乎？”曰：“食志。”
曰：“有人于此，毁瓦画墁，其志将以求食也，则子食之乎？”曰：“否。”
曰：“然则子非食志也，食功也。”


', '', '彭更：孟子弟子。
传（zhuàn）食：转食。泰：过分，过甚。
通功易事：各个不同的职业互通有无。羡（xiàn）：剩余。
梓、匠：即梓人、匠人，指木工。轮：轮人，制车轮的人。舆：舆人，制车厢的人。
待：持，扶助。
墁（màn）：墙壁上的涂饰。
', '彭更问（孟子）道：“跟随其后的车子有几十辆，跟从其后的人有几百人，从这个诸侯国吃到那个诸侯国，这是不是太过分了？”
孟子说：“如果不符合原则，那就一筐饭也不从别人那里接受；如果符合原则，那么，舜接受尧的天下，也不以为过分——你认为过分吗？”
彭更说：“不。士人不干活而吃白食，是不可以的。”
孟子说：“你如果不让各种行当互通有无，交换成果，用多余的来补充不足的，农民就有多余的粮食，妇女就有多余的布帛；你如果让他们互通有无，那么，木匠和车工就都可以从你那里得到吃的。这里有个人，在家就孝敬父母，在外就尊敬长辈，严守着古代圣王的道义，等待将来的读书人发扬光大，却不能从你那里得到吃的，你为什么看重各类工匠、车工而轻视遵行仁义的人呢？”
彭更说：“工匠和车工，他们的动机就是谋饭吃；君子为实行道义而做的事情，他们的动机也是谋饭吃吗？”
孟子说：“你为什么要论动机呢？如果他们对你有功劳，可以给吃的就给他们吃的好了。而且你是为了报答动机给饭吃？还是为了报答功劳给饭吃？”
彭更说：“报答动机。”
孟子说：“有人在这里，毁坏屋瓦，在新刷的墙上乱画，他的动机是谋饭吃，那你给他饭吃吗？”
彭更说：“不。”
孟子说：“那么，你就不是根据动机，而是根据所做事的功劳给饭吃的了。”
', NULL, '', 'indent', 1557830591, '5cda2b36c8959c00688d129a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642599, '孟子 · 第六卷 · 滕文公下 · 第五节 ', NULL, 6, 271, 3, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '万章问曰：“宋，小国也。今将行王政，齐楚恶而伐之，则如之何？”
孟子曰：“汤居亳，与葛为邻，葛伯放而不祀。汤使人问之曰：‘何为不祀？’曰：‘无以供牺牲也。’汤使遗之牛羊。葛伯食之，又不以祀。汤又使人问之曰：‘何为不祀？’曰：‘无以供粢盛也。’汤使亳众往为之耕，老弱馈食。葛伯率其民，要其有酒食黍稻者夺之，不授者杀之。有童子以黍肉饷，杀而夺之。书曰：‘葛伯仇饷。’此之谓也。为其杀是童子而征之，四海之内皆曰：‘非富天下也，为匹夫匹妇复雠也。’‘汤始征，自葛载’，十一征而无敌于天下。东面而征，西夷怨；南面而征，北狄怨，曰：‘奚为后我？’民之望之，若大旱之望雨也。归市者弗止，芸者不变，诛其君，吊其民，如时雨降。民大悦。书曰：‘徯我后，后来其无罚。’‘有攸不惟臣，东征，绥厥士女，匪厥玄黄，绍我周王见休，惟臣附于大邑周。’其君子实玄黄于匪以迎其君子，其小人箪食壶浆以迎其小人，救民于水火之中，取其残而已矣。太誓曰：‘我武惟扬，侵于之疆，则取于残，杀伐用张，于汤有光。’不行王政云尔，苟行王政，四海之内皆举首而望之，欲以为君。齐楚虽大，何畏焉？”', '', '万章：战国时期齐国人，孟子弟子。
亳（bó）：在今河南商丘北。葛：古国名，故城在今河南宁陵北。放：放肆，放纵。
要（yāo）：拦截。
葛伯仇饷：见今本《尚书·仲虺之诰》，饷：馈赠。
载：开始。
芸：通“耘”。
“有攸不惟臣”以下数句：见今本《尚书·武成》。攸，古国名。惟，为。篚（fěi），盛放物品的竹器。这里指把物品装在篚内。玄黄，这里指代布帛。休，美。
《太誓》：《尚书·周书》中篇名。
于：古国名，即“邘”。
', '万章问道：“宋国，是个小国；如今要实行仁政，齐国、楚国厌恨它而加以讨伐，该怎么办？”
孟子说：“汤住在亳地，和葛国是邻国，葛伯放肆，不举行祭祀（祭先祖的仪式）。汤派人问他：‘为什么不祭祀？’他说：‘没有祭杞用的牲畜。’汤派人送他牛羊。葛伯吃掉了牛羊，却不用来祭祀。汤又派人问他：‘为什么不祭祀？’他说：‘没有祭祀用的谷米。’汤派亳地的老百姓去为他耕种，老弱的人为他们送饭。葛伯带着他的老百姓，拦住那些带着酒食黍稻的送饭者，抢夺他们，不给的就杀掉。有个孩子去送饭和肉，葛伯竟把他杀了，抢走饭和肉。《尚书》说：‘葛伯仇视送饭者。’说的就是这个。因为葛伯杀了这个孩子，汤才去讨伐他，天下人都说：‘他不是为天下的财富，而是为给平民百姓报仇。’汤的讨伐，从葛国开始，征讨十一次而天下无敌。他向东边出征，西边各族的老百姓就埋怨；他向南边出征，北边各族的老百姓就埋怨，（他们埋怨）说：‘怎么把我们（这里）放在后面？’老百姓盼望他，就像大旱时节盼望下雨。（汤所到之处，）做生意的没停过买卖，种田的照常下地。汤杀掉他们的君主，安抚当地的人民，这就像及时雨一样，老百姓很高兴。《尚书》说：‘等待我们的君王，君王来了我们就不再受刑罚！’又说，‘攸国不肯臣服，（周武王）就向东征伐，安抚那里的男男女女，（人们）用竹筐装着黑色、黄色的绢帛迎接周王，愿意侍奉周王而受他恩泽，称臣臣服于大周国。’当地的官员把黑色的、黄色的布帛盛满了筐篚来迎接官员，当地的百姓用箪盛着饭，用壶盛着酒浆来迎接士卒；周王出师把老百姓从水火之中解救出来，只收拾那残暴的君主。《太誓》说：‘我们的威武大发扬，攻入邘国的疆界，收拾邘国的暴君，于是有伸张正义的杀伐，比起汤来更辉煌。’不实行仁政也就罢了。如果实行仁政，天下人人都抬头盼望他，要让他来做君王。齐国和楚国纵然强大，又有什么可怕的呢？”
', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9f5e272d4b2255c267", "shortContent": "本篇叙葛某惹鬼缠身，幸以机智得脱的故事。故事寓恐怖的刺激于轻松谐谑之中。\n鬼怪故事中的鬼，大部分是面目狰狞可怖的，有的先化成美女，后来再现出原形。那些故事中不怕鬼的人，总是一身正气，对鬼严阵以待，一旦鬼来了，便打点起精神，挥刀仗剑，战而胜之。也有出于好奇心对鬼窟狐薮索幽探胜的，真正与鬼接上手，大半也和上面所说的情景相同。当然这不包括蒲松龄的那些“多具人情”的花妖狐魅和人真诚相爱的故事，她们身上实在...", "authors": ["姚品文"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557830646, '5cda2b7343e78c00698a4755', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642600, '孟子 · 第六卷 · 滕文公下 · 第六节 ', NULL, 4, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子谓戴不胜曰：“子欲子之王之善与？我明告子。有楚大夫于此，欲其子之齐语也，则使齐人傅诸？使楚人傅诸？”
曰：“使齐人傅之。”
曰：“一齐人傅之，众楚人咻之，虽日挞而求其齐也，不可得矣；引而置之庄岳之间数年，虽日挞而求其楚，亦不可得矣。子谓薛居州，善士也。使之居于王所。在于王所者，长幼卑尊，皆薛居州也，王谁与为不善？在王所者，长幼卑尊，皆非薛居州也，王谁与为善？一薛居州，独如宋王何？”', '', '戴不胜：孟子同时人，宋国的臣子。
傅：辅佐，教导。
庄岳：庄街、岳里，均在齐都临淄。
薛居州：宋国的臣子。
', '孟子对戴不胜说：“你希望你的王学好吗？我明白告诉你。假如有个楚国的大夫在这里，要他的儿子学会齐国话，那么，让齐国人教他还是让楚国人教他？”
戴不胜说：“让齐国人教他。”
孟子说：“一个齐国人教他，许多楚国人向他嚷嚷说话干扰他，即使天天鞭打他，逼他说齐国话，也不可能学到；带着他到齐国都城庄街、岳里这些地方住上几年，即使天天鞭打他，逼他说楚国话，他同样办不到。你说薛居州是个好人，让他住在（宋国）王宫里。如果住在王宫里的人，不论老少尊卑都是薛居州，王和谁去做坏事？如果住在王宫里的人，不论老少尊卑都不是薛居州，王和谁去做好事？一个薛居州，对宋王来说怎么样呢？”
', NULL, '', 'indent', 1557830689, '5cda2b9e43e78c00698a48e6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642601, '孟子 · 第六卷 · 滕文公下 · 第七节 ', NULL, 2, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '公孙丑问曰：“不见诸侯，何义？”
孟子曰：“古者不为臣不见。段干木逾垣而辟之，泄柳闭门而不内，是皆已甚。迫，斯可以见矣。阳货欲见孔子而恶无礼，大夫有赐于士，不得受于其家，则往拜其门。阳货矙孔子之亡也，而馈孔子蒸豚；孔子亦矙其亡也，而往拜之。当是时，阳货先，岂得不见？曾子曰：‘胁肩谄笑，病于夏畦。’子路曰：‘未同而言，观其色赧赧然，非由之所知也。’由是观之，则君子之所养可知已矣。”', '', '段干木：姓段干，名木，战国初年魏文侯时贤者，曾师事孔子弟子子夏，守道不仕。
泄柳：春秋鲁国人。鲁穆公曾亲自登门会见，泄柳闭门不纳，后为鲁穆公臣。
瞰（kàn）：窥伺，看望。
胁肩谄笑：缩敛肩膀，假装笑脸。畦（xí）：田园。
赧赧（nǎn）：因惭愧而脸红的样子。由：仲由，即子路。
', '公孙丑问道：“不去谒见诸侯，是什么道理？”
孟子说：“古时候，不是臣属的话，就不去谒见。段干木翻墙以躲避魏文侯，泄柳关起门来不接见鲁穆公，这都太过分了。如果对方主动求见，是可以见的。阳货要孔子来见，又怕自己失礼。大夫对士有所赏赐，士如果没能在家里亲自接受，就该前往大夫家里去拜谢。于是阳货就等孔子不在家时，送小蒸猪给孔子。孔子也等阳货不在家时，前往拜谢。在这个时候，如果阳货先来见孔子，孔子难道不见他？曾子说：‘耸着肩膀，做出媚笑，比夏天在菜园里干活还累。’子路说：‘跟别人不同道，却又上去搭话，看他的脸色，还一副惭愧的样子，这我就不懂了。’由此来看，君子怎样修身养性，可以知晓了。”
', NULL, '', 'indent', 1557830738, '5cda2bcf7f6fd30065aeb37d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642602, '文王世子第八', NULL, 9, 65, 1, 2, '戴圣', NULL, 36788, '586e300a1b69e6006306cdc6', '汉', 'wen', '文', '', '', '文王之为世子，朝于王季，日三。鸡初鸣而衣服，至于寝门外，问内竖之御者曰：“今日安否何如？”内竖曰：“安”。文王乃喜。乃日中又至，亦如之。及莫又至，亦如之。其有不安节，则内竖以告文王，文王色忧，行不能正履。王季复膳，然后亦复初。食上，必在，视寒暖之节，食下，问所膳，命膳宰曰：“末有原！”应曰：“诺。”然后退。
武王帅而行之，不敢有加焉。文王有疾，武王不说冠带而养。文王一饭，亦一饭，文王再饭，亦再饭。旬有二日乃间。
文王谓武王曰：“女何梦矣？”武王对曰：“梦帝与我九龄。”文王曰：“女以为何也？”武王曰：“西方有九国焉，君王其终抚诸？”文王曰：“非也。古者谓年龄，齿亦龄也。我百尔九十，吾与尔三焉。”文王九十七乃终，武王九十三而终。
成王幼，不能莅阼，周公相，践阼而治。抗世子法于伯禽，欲令成王之知父子君臣长幼之道也。成王有过，则挞伯禽，所以示成王世子之道也。文王之为世子也。
凡学世子及学士，必时：春夏学干戈，秋冬学羽，皆于东序。小乐正学干，大胥赞之。师学戈，龠师丞赞之，胥鼓南。春诵夏弦，大师诏之；瞽宗秋学礼，执礼者诏之；冬读书，典书者诏之。礼在瞽宗，书在上庠。
凡祭与养老，乞言合语之礼，皆小乐正诏之于东序。大乐正学舞干戚，语说，命乞言，皆大乐正授数，大司成论说在东序。凡侍坐于大司成者，远近问三席，可以问。终则负墙，列事未尽，不问。
凡学，春官释奠于其先师，秋冬亦如之。凡始立学者，必释奠于先圣先师，及行事，必以币。凡释奠者，必有合也，有国故则否。凡大合乐，必遂养老。凡语于郊者，必取贤敛才焉。或以德进，或以事举，或以言扬。曲艺皆誓之，以待又语。三而有一焉，乃进其等，以其序，谓之郊人。远之于成均以及取爵于上尊也。始立学者，既兴器用币，然后释菜，不舞不授器，乃退。傧于东序，一献，无介语可也。
凡三王教世子必以礼乐。乐，所以修内也；礼，所以修外也。礼乐交错于中，发形于外，是故其成也怿，恭敬而温文。立大傅少傅以养之，欲知其父子君臣之道也。大傅审父子君臣之道以示之，少傅奉世子，以观大傅之德行而审喻之。大傅在前，少傅在后；入则有保，出则有师，是以教喻而德成也。师也者，教之以事而喻诸德者也；保也者，慎其身以辅翼之而归诸道者也。《记》曰：“虞夏商周，有师保，有疑丞，设四辅及三公。不必备，唯其人。”语使能也。君子曰德，德成而教尊，教尊而官正，官正而国治，君之谓也。仲尼曰：“昔者周公摄政，践阼而治，抗世子法于伯禽，所以善成王也。闻之曰：‘为人臣者，杀其身有益于君则为之。’况于其身以善其君乎？周公优为之，是故知为人子，然后可以为人父；知为人臣，然后可以为人君；知事人，然后能使人。成王幼，不能莅阼，以为世子，则无为也，是故抗世子法于伯禽，使之与成王居，欲令成王之知父子君臣长幼之义也。君之于世子也，亲则父也，尊则君也。有父之亲，有君之尊，然后兼天下而有之。是故，养世子不可不慎也。行一物而三善皆得者，唯世子而已。其齿于学之谓也。故世子齿于学，国人观之曰：“将君我而与我齿让，何也？”曰：“有父在则礼然。”然而众知父子之道矣。其二曰：“将君我而与我齿让，何也？”曰：“有君在则礼然。”然而众著于君臣之义也。其三曰：“将君我而与我齿让，何也？”曰：“长长也。”然而众知长幼之节矣。故父在斯为子，居在斯谓之臣，君子与臣之节，所以尊君亲亲也。故学之为父子焉，学之为君臣焉，学之为长幼焉，父子君臣长幼之道得，而国治。语曰：“乐正司业，父师司成，一有元良，万国以贞。”世子之谓也。周公践阼。
庶子之正于公族者，教之以孝弟睦友子爱，明父子之义，长幼之序。其朝于公，内朝则东面北上，臣有贵者以齿。其在外朝，则以官，司士为之。其在宗庙之中，则如外朝之位，宗人授事，以爵以官，其登献受爵，则以上嗣。
庶子治之，虽有三命，不逾父兄，其公大事，则以其丧服之精粗为序。虽于公族之丧亦如之，以次主人。若公之族燕，则异姓为宾，膳宰为主人，公与父兄齿。族食，世降一等。
其在军，则守于公祢。公若有出疆之政，庶子以公族之无事者守于公宫，正室守大庙，诸父守贵宫贵室，诸子诸孙守下宫下室。五庙之孙，祖庙未毁，虽为庶人，冠、取妻必告，死必赴，练祥则告。族之相为也，宜吊不吊，宜免不免，有司罚之。至于赙承含，皆有正焉。
公族其有死罪，则磬于甸人。其刑罪，则纤专刂，亦告于甸人。公族无宫刑。狱成，有司谳于公。其死罪，则曰某之罪在大辟；其刑罪，则曰某之罪在小辟。公曰：“宥之。”有司又曰：“在辟”。公又曰：“宥之。”有司又曰：“在辟。”及三宥，不对，走出，致刑于甸人。公又使人追之曰：“虽然，必赦之。”有司对曰：“无及也！”反命于公，公素服不举，为之变，如其伦之丧。无服，亲哭之。
公族朝于内朝，内亲也。虽有贵者以齿，明父子也。外朝以官，体异姓也。宗庙之中，以爵为位，崇德也。宗人授事以官，尊贤也。登受爵以上嗣，尊祖之道也。丧纪以服之轻重为序，不夺人亲也。公与族燕则以齿，而孝弟之道达矣。其族食世降一等，亲亲之杀也。战则守于公祢，孝爱之深也。正室守大庙，尊宗室，而君臣之道著矣。诸父诸兄有守贵室，子弟守下室，而让道达矣。五庙之孙，祖庙未毁，虽及庶人，冠、取妻必告，死必赴，不忘亲也。亲未绝而列于庶人，贱无能也。敬吊临赙，睦友之道也。古者庶子之官治，而邦国有伦邦国有伦，而众乡方矣。公族之罪，虽亲不以犯有司，正术也，所以体百姓也。刑于隐者，不与国人虑兄弟也。弗吊，弗为服，哭于异姓之庙，为忝祖远之也。素服居外，不听乐，私丧之也，骨肉之亲无绝也。公族无宫刑，不剪其类也。
天子视学，大昕鼓徵，所以警众也。众至，然后天子至，乃命有司行事，兴秩节，祭先师先圣焉。有司行事反命，始之养也。适东序，释奠于先老，遂设三老五更群老之席位焉。适馔省醴，养老之珍具，遂发咏焉，退，修之以孝养也。反，登歌《清庙》，既歌而语，以成之也。言父子君臣长幼之道，合德音之致，礼之大者也。下管象，舞大武，大合众以事，达有神，兴有德也。正君臣之位，贵贱之等焉，而上下之义行矣。有司告以乐阕，王乃命公侯伯子男及群吏曰：“反，养老幼于东序”，终之以仁也。是故，圣人之记事也，虑之以大，爱之以敬，行之以礼，修之以孝养，纪之以义，终之以仁。是故古之人一举事，而众皆知其德之备也。古之君子，举大事，必慎其终始，而众安得不喻焉？《兑命》曰：“念终始典于学。”
《世子》之《记》曰：“朝夕至于大寝之门外，问于内竖曰：‘今日安否何如？’内竖曰：‘今日安。’世子乃有喜色。其有不安节，则内竖以告世子，世子色忧不满容。内竖言复初，然后亦复初。”朝夕之食上，世子必在，视寒暖之节。食下，问所膳羞。必知所进，以命膳宰，然后退。若内竖言疾，则世子亲齐玄而养。膳宰之馔，必敬视之，疾之药，必亲尝之。尝馔善，则世子亦能食；尝馔寡，世子亦不能饱。以至于复初，然后亦复初。
', '', '', '
', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf6e0ce818559d0649a2", "shortContent": "王翰此赋当为其元季隐居中条山时所作。中条山在陕西西南部，山下曾有古虞、芮两国。两国之间有一块地，因分封时未作明确划分，所以两国为这块地的归属发生了争执，争了几年都没有结果。后来两国想请周文王来评判，于是一起到周去。入周境后发现周地的百姓相互让畔，两国深为感动，于是相互退让，乃以相争之田作为“闲田”。王翰在隐居东条山时看到了这块地方，想起当年虞、芮两国相争和相让之事，深有感触，即就此事而赋。其感触最...", "authors": ["孙海洋"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f912e6a6b501f974ba5", "shortContent": "妾本钱塘江上住。花落花开，不管流年度。燕子衔将春色去。纱窗几阵黄梅雨。\n斜插犀梳云半吐。檀板朱唇，唱彻《黄金缕》。望断行云无觅处。梦回明月生春浦。\n银河漾漾。正桐飞露井，寒生斗帐。芳草梦惊，人忆高唐惆怅。感离愁，甚情况！春风二月桃花浪。扁舟征棹，又过吴江上。人去雁回，千里风云相望。倚江楼，倍凄怆。\n长天书阔雁来尽，深院落花莺更多。发策决科[5]君自尔，求田问舍我如何？\n苏东坡门下有两位名士自言遇见...", "authors": ["穆", "俦"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42ae2cee9a0c24ee86a1", "shortContent": "右《惜花春起早》\n香肩半軃[11]金钗卸，寂寂重门锁深夜。素魄[12]初离碧海壖[13]，清光已透朱帘罅。徘徊不语倚阑干，参横斗落[14]风露寒。小娃低语唤归寝，犹过蔷薇架后看。\n右《爱月夜眠迟》\n银塘水满蟾光吐，嫦娥夜入冯夷府。荡漾明珠若可扪，分明兔颖[15]如堪数。美人自挹濯春葱，忽讶冰轮在掌中。女伴临流笑相语，指尖擎出广寒宫。\n右《掬水月在手》\n铃声响处东风急，红紫丛边久凝立。素手攀条恐刺伤...", "authors": ["宁稼雨芦茜"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42c234a8757d5a0fb147", "shortContent": "本篇采自钮琇《觚剩》卷三。\n在清初传奇小说中，本文是思想性与艺术性结合较好的作品之一。从思想性方面讲，本文通过对一个多才多艺的少女睐娘的悲剧人生的描写，一方面反映了清兵南下给人民带来的深重灾难；一方面深刻地揭露了封建社会末期的道德沦丧和封建婚姻制度的不合理及社会的人情险恶。\n睐娘出生在一个诗书礼仪之家。自幼聪慧，善记诵，对书画有浓厚的兴趣，故其父令其管理家中的书画。“长及齿龀”，即可作花鸟小图。工...", "authors": ["王恒展"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557830778, '5cda2bf87f6fd30065aeb4fd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642644, '孟子 · 第八卷 · 离娄下 · 第十二节 ', NULL, 7, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“大人者，不失其赤子之心者也。”
', '', '赤子：婴儿，引申的含义指纯洁。
', '孟子说：“有德行的君子，就是不丧失婴儿般天真纯朴的人。”
', NULL, '', 'indent', 1557915454, '5cdb76bcc8959c0068c97899', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642603, '孟子 · 第六卷 · 滕文公下 · 第九节 ', NULL, 18, 271, 4, 2, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '公都子曰：“外人皆称夫子好辩，敢问何也？”
孟子曰：“予岂好辩哉？予不得已也。天下之生久矣，一治一乱。当尧之时，水逆行泛滥于中国，蛇龙居之，民无所定，下者为巢，上者为营窟。书曰：‘洚水警余。’洚水者，洪水也。使禹治之。禹掘地而注之海，驱蛇龙而放之菹，水由地中行，江、淮、河、汉是也。险阻既远，鸟兽之害人者消，然后人得平土而居之。
尧舜既没，圣人之道衰，暴君代作，坏宫室以为污池，民无所安息，弃田以为园囿，使民不得衣食，邪说暴行又作，园囿污池，沛泽多而禽兽至，及纣之身，天下又大乱。周公相武王，诛纣伐奄，三年讨其君，驱飞廉于海隅而戮之，灭国者五十，驱虎豹犀象而远之，天下大悦。书曰：‘丕显哉，文王谟，丕承哉，武王烈，佑启我后人，咸以正无缺。’
世衰道微，邪说暴行有作，臣弑其君者有之，子弑其父者有之。孔子惧，作春秋。春秋，天子之事也，是故孔子曰：‘知我者，其惟春秋乎；罪我者，其惟春秋乎。’
圣王不作，诸侯放恣，处士横议，杨朱墨翟之言，盈天下，天下之言，不归杨则归墨。杨氏为我，是无君也；墨氏兼爱，是无父也。无父无君。是禽兽也。公明仪曰：‘庖有肥肉，厩有肥马，民有饥色，野有饿莩，此率兽而食人也。’杨墨之道不怠，孔子之道不着，是邪说诬民，充塞仁义也。仁义充塞，则率兽食人，人将相食。吾为此惧。闲先圣之道，距杨墨，放淫辞，邪说者，不得作，作于其心，害于其事，作于其事，害于其政，圣人复起，不易吾言矣。
昔者禹抑洪水，而天下平；周公兼夷狄，驱猛兽，而百姓宁；孔子成春秋，而乱臣贼子惧。诗云：‘戎狄是膺，荆舒是惩，则莫我敢承。’无父无君，是周公所膺也。我亦欲正人心，息邪说，距跛行，放淫辞，以承三圣者。岂好辩哉？予不得已也。能言距杨墨者，圣人之徒也。
', '', '公都子：孟子弟子。
营窟：土屋，穴居。
洚（jiàng）水警余：《尚书》逸篇里的话。洚水：大水。
菹（zū）：水草多的沼泽地。
代作：更代而作，不断出现。污池：蓄水的池子。
伐奄三年讨其君：这是周成王时的事。飞廉：传说中善跑的人，为纣王所用。
《书》曰：以下所引，见今本《尚书·周书·君牙》。
丕：宏大。谟：谋略。承：继承。烈：功绩，事业。
有：通“又”。
《春秋》：古代编年体史书，相传孔子据鲁史修订而成。
处士：不做官而居家的士人。杨朱：战国时魏人，晚于墨翟，早于孟子。墨翟，战国时鲁人，或说宋人，学说详见《墨子》。
闲：防御，捍卫。
承：抵抗。引诗出自《诗经·鲁颂·阔宫》。
', '公都子说：“外面的人都说先生您喜欢辩论，请问这是为什么呢？”
孟子说：“我难道喜欢辩论吗？我是不得已（而辩论）啊。天下有人类以来很久了，太平一时，动乱一时。在尧的时候，（东流的水）水倒流（一样），在中国泛滥，陆地成为蛇和龙的居所，使老百姓无处安身；低地的人在树上做巢，高地的人挖洞穴而居。《尚书》说：‘洚水警告我们。’洚水就是洪水。于是让禹来治水。禹挖地而把水导流入海，把蛇和龙赶到多草的沼泽；水从大地上穿行而过，这就是长江、淮河。黄河、汉水。险阻远离了人类，害人的鸟兽消灭了，然后人才能在平地上居住。
“尧、舜死后，圣人之道衰落，暴君一代又一代地出现，他们毁坏房屋来开挖深池，使老百姓无处安身；荒废农田来建园林，使老百姓得不到吃穿。这时又出现荒谬的学说、暴虐的行为。园林、深池、沼泽一多，禽兽又聚集来了。到了商纣的时候，天下又大乱。周公辅佐武王杀掉纣，又讨伐奄国，三年后，杀掉奄国的国君，把飞廉赶到海边杀掉了他。灭了五十个国家，把老虎、豹子、犀牛、大象赶到远方。天下人很高兴。《尚书》说：‘伟大而显赫啊，文王的谋略！伟大的继承者啊，武王的功烈！庇佑我们，启发我们，直到后代，使大家都正确而没有错误。’
“时世衰落，道义微茫，荒谬的学说和暴虐的行为又出现了，有臣子杀掉他的君主的，有儿子杀掉他的父亲的。孔子为此忧虑，写了《春秋》。《春秋》说的是天子的事情（纠正君臣父子的名分，褒贬诸侯大夫的善恶，）。所以孔子说：‘了解我的可以只凭《春秋》这部书了！怪罪我的也可以只凭《春秋》这部书了！’
“（如今）圣王不出现，诸侯放纵恣肆，隐居不仕的人横发议论，杨朱、墨翟的学说充满了天下。天下种种议论，不是归附杨朱，就是归附墨翟。杨氏讲的是‘为我’的道理，这叫不把君主当回事，墨氏讲的是‘兼爱’的道理，这叫不把父亲当回事。目中无父，目中无君，这是禽兽啊。公明仪说：‘厨房里有肥肉，马厩里有肥马，而百姓面黄肌瘦，野外有饿死的尸体，这好似率领着野兽来吃人啊！’杨、墨的学说不消灭，孔子的学说就不能发扬，这就是荒谬的学说在欺骗百姓，堵塞了仁义的道路。仁义的道路被堵塞，就导致带领禽兽吃人，人们之间互相残杀。我为此忧虑，因而捍卫古代圣人的学说，抵制杨、墨，驳斥荒诞的言论，使发布邪说谬论的人起不来。种种邪说谬论从心里产生，就会妨害行动；妨害了行动，也就妨害了政治。即使有圣人再起，也不会改变我的这番话。
“从前禹平息了洪水而天下太平，周公兼并了夷狄，赶跑了猛兽而使百姓安宁，孔子作成了《春秋》而叛乱作逆的人感到害怕。《诗经》说：‘戎狄是要防范的，荆舒是要严惩的，那就没有人能抗拒我。’目中无父、目中无君，是周公所防范的。我也要端正人心，抑制邪说谬论，反对偏激的行为，驳斥荒诞的言论，来继承这三位圣人。我难道喜欢辩论吗？我是不得已啊。能够用言论来反对杨朱、墨翟的，也就是圣人的门徒了。”
', NULL, '', 'indent', 1557830862, '5cda2c4a7f6fd30065aeb7d5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642604, '孟子 · 第六卷 · 滕文公下 · 第十节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '匡章曰：“陈仲子岂不诚廉士哉？居於陵，三日不食，耳无闻，目无见也。井上有李，螬食实者过半矣，匍匐往将食之，三咽，然后耳有闻，目有见。”
孟子曰：“于齐国之士，吾必以仲子为巨擘焉。虽然，仲子恶能廉？充仲子之操，则蚓而后可者也。夫蚓，上食槁壤，下饮黄泉。仲子所居之室，伯夷之所筑与？抑亦盗跖之所筑与？所食之粟，伯夷之所树与？抑亦盗跖之所树与？是未可知也。”
曰：“是何伤哉？彼身织屦，妻辟纑，以易之也。”
曰：“仲子，齐之世家也。兄戴，盖禄万钟。以兄之禄为不义之禄而不食也，以兄之室为不义之室而不居也，辟兄离母，处于於陵。他日归，则有馈其兄生鹅者，己频顣曰：‘恶用是鶂鶂者为哉？’他日，其母杀是鹅也，与之食之。其兄自外至，曰：‘是鶂鶂之肉也。’出而哇之。以母则不食，以妻则食之；以兄之室则弗居，以於陵则居之。是尚为能充其类也乎？若仲子者，蚓而后充其操者也。”


', '', '匡章：战国时期齐国将军，曾率军拒秦，破燕，攻楚。
陈仲子：又称於陵仲子，战国时期齐国人，和孟子同时。
於（wū）陵：地名，在今山东长山南。
螬（cáo）：蛴螬，金龟子的幼虫。将：取。
巨擘（bò）：大拇指。这里比喻杰出的人物。
黄泉：指地下的泉水。
辟：同“避”；绩麻。纑（1ú）：练麻。辟纑指将绩过的麻搓成线。
盖（gě）：地名，陈戴的采邑。
辟：同“避”。
频顣（cù）：又作“颦蹙”，紧皱眉头，表示不高兴的样子。
', '匡章说：“陈仲子难道不是个廉洁的士人吗？住在於陵，三天没吃东西，饿得耳朵听不见，眼睛看不着。井上有个李子，被金龟子吃了大半，他爬过去，取来吃了三口，耳朵才听得见了，眼睛才看得着了。”
孟子说：“在齐国的士人中，我一定把陈仲子当作大拇指。尽管这样，仲子怎能算作廉洁呢？要扩充仲子的操守，那一定得当蚯蚓才可以。蚯蚓，在地上吃干土，在地下喝黄泉水（一切都不求人）。仲子所住的房子，是伯夷那样廉洁的人所建筑的呢？还是盗跖那样的强盗所建筑的呢？所吃的谷米，是伯夷那样廉洁的人所种的呢？还是盗跖那样的强盗所种的呢？这都是很难说的。”
匡章说：“这有什么关系呢？他亲自编织草鞋，他的妻子绩麻练麻，用它们来换取生活用品。”
孟子说：“陈仲子，是齐国的大家族。他的哥哥陈戴，从盖邑得的俸禄有几万石。他把哥哥的俸禄看作不义之禄而不吃，把哥哥的房屋看作不义之室而不住。避开哥哥，离开母亲，住在於陵。有一天回家，有个人送给他哥哥一只活鹅，仲子就皱缩着眉鼻说：‘哪里用得着这个嗷嗷叫的东西？’过些时候，他的母亲杀了这只鹅，给他吃。他的哥哥从外面回来，说：‘这就是那嗷嗷叫的东西的肉呀。’仲子出去吐掉了。母亲的东西不吃，妻子的东西就吃；哥哥的房子不住，於陵的房子就住。这还能算扩充操守吗？像仲子这样的人，只有变成了蚯蚓才能扩充他的操守呢。
', NULL, '', 'indent', 1557830929, '5cda2c8f0237d70069f9d7d1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642605, '孟子 · 第七卷 · 离娄上 · 第一节 ', NULL, 15, 271, 5, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“离娄之明，公输子之巧，不以规矩，不能成方圆；师旷之聪，不以六律，不能正五音；尧舜之道，不以仁政，不能平治天下。
今有仁心仁闻而民不被其泽，不可法于后世者，不行先王之道也。故曰，徒善不足以为政，徒法不能以自行。诗云：‘不愆不忘，率由旧章。’遵先王之法而过者，未之有也。
圣人既竭目力焉，继之以规矩准绳，以为方员平直，不可胜用也；既竭耳力焉，继之以六律，正五音，不可胜用也；既竭心思焉，继之以不忍人之政，而仁覆天下矣。故曰，为高必因丘陵，为下必因川泽。为政不因先王之道，可谓智乎？是以惟仁者宜在高位。不仁而在高位，是播其恶于众也。
上无道揆也。下无法守也，朝不信道，工不信度，君子犯义，小人犯刑，国之所存者幸也。故曰：城郭不完，兵甲不多，非国之灾也；田野不辟，货财不聚，非国之害也。上无礼，下无学，贼民兴，丧无日矣。
诗曰：‘天之方蹶，无然泄泄。’泄泄，犹沓沓也。事君无义，进退无礼，言则非先王之道者，犹沓沓也。故曰：责难于君谓之恭，陈善闭邪谓之敬，吾君不能谓之贼。”', '', '离娄：又作“离朱”，相传是黄帝时目力极强的人。公输子：名般（或作“班”），春秋时期鲁国人，又叫“鲁班”，著名的巧匠。
规矩：圆规和角尺，画圆、画方的工具。
师旷：春秋时著名音乐家，晋平公的大师，生而目盲，相传能辨音以知吉凶。
六律：相传黄帝时伶伦截竹为管，以管的长短分别声音的高低清浊，乐器的音调均以之为准，此即标示绝对音高的乐律。乐律共十二，阴阳各六。由于阴六律又称“六吕”，所以，六律常单指六个阳律，即黄钟、太簇、姑洗、蕤宾、夷则、无射。五音：指宫、商、角、徵、羽五个音阶。
闻（wèn）：声誉。
指《诗经·大雅·假乐》篇。
愆（qiān）：过错。
忘：指疏漏。
率：遵循。
准：测定平面的水准器。
绳：量直线的墨线。
道揆（kuí）：以义理度量事物；揆，尺度，准则。
完：牢固。
辟：开辟。聚：积聚。
指《诗经·大雅·板》篇。
蹶（guì）：动，颠覆。
泄泄（yì）：多语的样子。
沓沓：和“泄泄”同义，形容多语的样子。
非：通“诽”，诋毁。', '孟子说：“即使有离娄的好眼神，公输般的好技巧，但如果不靠规和矩，也不能画成方和圆；即使像师旷一样的耳力聪敏，但如果不依据六律，也不能校正五音；就是有尧、舜之道，如果不凭借仁政，也不能使天下太平。如今有些诸侯尽管有仁爱的心肠、仁爱的声誉，但老百姓却没有受到他的恩泽，他也不能被后世效法，之所以如此，就是因为不实行前代圣王之道的缘故。
“所以说，只有好心不足以搞政治，只有法度不足以自动运行。《诗经》说：‘没有过失没有疏漏，一切遵循先王的典章。’遵循先王的法度而犯错误的，从来没有过。圣人既已用尽了目力，又接着用规、矩、准、绳，来制作方的、圆的、平的、直的东西，这些东西用都用不完：既已用尽了耳力，又接着用六律来校正五音，这些音阶也就运用无穷；既已用尽了心思，又接着推行不忍心别人受苦的仁政，仁爱也就覆盖天下了。
“所以说，建高台一定要凭借丘陵，挖深池一定要凭借沼泽，搞政治不凭借前代圣王之道，能说是明智吗？因此只有仁人可以处在统治的地位。不仁的人如果处在统治的地位，这就会在民众中散布他的罪恶。在上的没有道义准则，在下的不守法令制度，朝廷不相信道义，工匠不相信尺度，官员触犯义理，百姓触犯刑法，而国家还能生存的，那是侥幸。所以说，城墙不坚固，兵器甲胄不够多，不是国家的灾难；田野尚未开辟，钱财不够集中，不是国家的祸害。在上的不讲礼，在下的没学问，刁民纷纷兴起，国家的灭亡也就快了。
“《诗经》上说：‘上天要颠覆国家，群臣不要这样多话。’多话，就是喋喋不休。服侍君主不讲义，进退出入不守礼，说起话来便非难先王之道，这就是喋喋不休。所以说，要求君主克服困难，这叫‘恭’；陈述美善的道理而抑制谬论，这叫‘敬’；以为自己的君主不能行善，这叫‘贼’。”', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0f3", "shortContent": "离娄，传说中视力特别强的人；公输子，即鲁班，古代杰出的土木工匠。“规”、“矩”在古代是木匠术语，“规”指的是圆规，用来画圆；“矩”指的是用来打制方形必备的直角尺。没有这两样东西，就算是离娄和公输子，也没办法准确地画出方与圆。孟子借这一比喻向国君阐述了行仁政的必要：王天下犹如画方圆，画方圆必须借助规和矩，而王天下也必须借助一定的方法，即仁政。所以孟子紧接着这句话说：“尧舜之道，不以仁政，不能平治天下...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b4758b5420e2767eea084", "shortContent": "在这几章中孟子进一步阐发得人心者得天下、仁者无敌的思想。虽然这些观点在前面已经得到了精彩的阐述，但是在这里，它们获得了更深刻的表述和新的意义，显示了更大的说服力。\n\n为了利用现成的国家机构推行仁政学说，让它对现实政治和社会产生直接而巨大的影响，孟子在游说诸侯国君主时费尽了心机。考虑到要让统治者容易理解和接受，孟子在这里不是从道义的角度、根据伦理学的道理讲仁政，而是着眼于统治者和一般人的切身好处或根...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557831103, '5cda2d3c0237d70069f9e1ca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642606, '孟子 · 第七卷 · 离娄上 · 第二节 ', NULL, 6, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“规矩，方圆之至也；圣人，人伦之至也。欲为君尽君道，欲为臣尽臣道，二者皆法尧舜而已矣。不以舜之所以事尧事君，不敬其君者也；不以尧之所以治民治民，贼其民者也。孔子曰：‘道二：仁与不仁而已矣。’暴其民甚，则身弑国亡；不甚，则身危国削。名之曰‘幽厉’，虽孝子慈孙，百世不能改也。诗云‘殷鉴不远，在夏后之世’，此之谓也。”', '', '至：极至，最高标准。
幽、厉：指周幽王、周厉王，都是含贬义的谥号。
指《诗经·大雅·荡》篇。
殷：殷商。鉴：铜镜，这里指借鉴。夏后：夏王，指夏桀。
', '孟子说：“规和矩，是方与圆最高的标准；圣人，是处理人际关系最好的典范。要做君王，便该尽君道；要做臣，便该尽臣道。二者都效法尧、舜就足够了。不用舜服侍尧的态度和方式来服侍君主，就是对君主不恭敬；不用尧统治百姓的态度和方式来统治百姓，就是残害百姓。孔子说：‘路只有两条，仁和不仁，如此而已。’暴虐百姓严重的，就会自己被杀，国家灭亡；不严重的，也会自己遭遇危险，国家受到削弱，死后人们给他们‘幽’‘厉’这样的谥号，即使有孝子贤孙，经历一百代也改不掉这个坏名声。《诗经》上说：‘殷商的借鉴并不遥远，就在夏王桀的时代’，就是这个意思。”', NULL, '', 'indent', 1557831145, '5cda2d670237d70069f9e3a0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642607, '孟子 · 第七卷 · 离娄上 · 第三节 ', NULL, 8, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“三代之得天下也以仁，其失天下也以不仁。国之所以废兴存亡者亦然。天子不仁，不保四海；诸侯不仁，不保社稷；卿大夫不仁，不保宗庙；士庶人不仁，不保四体。今恶死亡而乐不仁，是犹恶醉而强酒。”', '', '社稷：土神和谷神，指代国家。
宗庙：祭祀祖先的处所，这里指代卿大夫的采邑。
士庶人：士人和老百姓。四体：四肢。
强（qiǎng）：勉强。

', '孟子说：“夏、商、周三代得天下是因为仁，失去天下是因为不仁。国家之所以衰落、兴盛、生存、灭亡也都是这个道理。天子如果不仁，就不能保有天下；诸侯如果不仁，就不能保有国家；卿大夫如果不仁，就不能保有祖庙；士人和普通老百姓如果不仁，就不能保全自己的身体。现在是厌恶死亡而喜欢不仁，这犹如厌恶醉酒却又使劲喝酒一样。”', NULL, '', 'indent', 1557831183, '5cda2d8d43e78c00698a5c2a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642608, '孟子 · 第七卷 · 离娄上 · 第四节 ', NULL, 19, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“爱人不亲，反其仁；治人不治，反其智；礼人不答，反其敬。行有不得者皆反求诸己，其身正而天下归之。《诗》云：‘永言配命，自求多福。’”
', '', '言：语助词。
引诗见《诗经·大雅·文王》篇。
', '孟子说：“爱别人，别人却不亲近自己，那就反过来检讨自己是否够仁爱；管理别人，却管理不好，那就反过来检讨自己是否够明智；对别人有礼，别人却不回应，那就反过来检讨自己是否够恭敬。凡是行为有不能达到预期效果的，都反过来在自己身上找原因，自己端正了，天下的人自然就会归顺他。《诗经》上说：‘永远配合天的命令，自己寻求盛多的福。’”
', NULL, '', 'indent', 1557831214, '5cda2dac17b54d0075bffb1b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642609, '孟子 · 第七卷 · 离娄上 · 第五节 ', NULL, 16, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“人有恒言，皆曰‘天下国家’。天下之本在国，国之本在家，家之本在身。” ', '', '', '孟子说：“人们有句老话，都说‘天下国家’。天下的基础在国，国的基础在家，家的基础在个人。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0f4", "shortContent": "“天下国家”是一个内涵丰富的社会和政治概念。在很长一段时期，中国的社会结构都是由天下、国、家、个人共同组成。天下即古人理解的整个地域，它为天子所专有；国是指诸侯之国，为诸侯治理之地；家是指以血缘关系建立起来的社会最小组织；个人则是社会的最小元素。《大学》云：“物格而后知至，知至而后意诚，意诚而后心正，心正而后身修，身修而后家齐，家齐而后国治，国治而后天下平。”这就是我们常说的修身、齐家、治国、平天...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1557831241, '5cda2dc743e78c0065d84a79', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642610, '孟子 · 第七卷 · 离娄上 · 第六节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“为政不难，不得罪于巨室。巨室之所慕，一国慕之；一国之所慕，天下慕之；故沛然德教溢乎四海。”
', '', '巨室：指贤明的卿大夫家。这里指贤明的卿大夫。
沛然：形容盛大流行的样子。
', '孟子说：“搞好（国家的）政治不难，只要不得罪那些贤明的卿大夫们就行了。因为他们所思慕的，一国人都会思慕；一国的人所思慕的，天下的人都会思慕。所以道德教化就浩浩荡荡地溢满四海了。”
', NULL, '', 'indent', 1557831327, '5cda2e1443e78c0065d84d4d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642611, '孟子 · 第七卷 · 离娄上 · 第七节 ', NULL, 9, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“天下有道，小德役大德，小贤役大贤；天下无道，小役大，弱役强。斯二者天也。顺天者存，逆天者亡。齐景公曰：‘既不能令，又不受命，是绝物也。’涕出而女于吴。今也小国师大国而耻受命焉，是犹弟子而耻受命于先师也。如耻之，莫若师文王。师文王，大国五年，小国七年，必为政于天下矣。诗云：‘商之孙子，其丽不亿。上帝既命，侯于周服。侯服于周，天命靡常。殷士肤敏，祼将于京。’孔子曰：‘仁不可为众也。夫国君好仁，天下无敌。’今也欲无敌于天下而不以仁，是犹执热而不以濯也。诗云：‘谁能执热，逝不以濯？’”', '', '小德役大德：即“小德役于大德”。
绝物：没有国家与之来往，犹现在所说的走投无路。
女（nǜ）：以女嫁人。
指《诗经·大雅·文王》篇。
丽：数目。亿：周代称十万为亿。这里形容众多。
侯于周服：乃臣服于周；侯，语助词，乃。
肤敏：品德优美，言行敏捷。裸（guàn）将：“将裸”的倒文，助祭。裸，古代一种祭礼，称“灌鬯礼”。祭祀时，在神主前将玉制酒器中的酒洒在白茅上，表示神在饮酒。将，助。京：镐京，西周国都。
执：救治。濯（zhuó）：洗涤。
逝：发语词，无义。引诗见《诗经·大雅·桑柔》。
', '孟子说：“天下有道的时候，道德低的受道德高的役使，才智少的受才智多的役使；天下无道的时候，力量小的被力量大的役使，力量弱的被力量强的役使。这两种情况，都是天意。符合天理。顺从天理的生存，违逆天理的灭亡。齐景公说：‘既不能发号施令，又不愿服从命令，这是无路可走了。’于是流着眼泪把女儿嫁到吴国。如今小国以大国为师而又耻于服从命令，这就像弟子耻于服从老师的命令一样。如果以此为耻辱，不如师从文王。如果师从文王，大国只需五年，小国不超过七年，一定能在天下掌权。《诗经》上说：‘殷商的子孙，数目不下十万。上帝既已降命，于是臣服于周。于是臣服于周，天命并不固定。商臣漂亮聪明，也上镐京助祭。’孔子说：‘仁德是不在乎人多势众的。国君如果爱仁德，就可以无敌于天下。’如今有人想要无敌于天下却不依靠仁德，这就像要解除炎热却不洗浴一样。《诗经》说：‘谁能解除炎热，却不凭借洗浴？’”', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0f5", "shortContent": "孟子的意思是说：“政治清明之时，道德低的人为道德高的人所役使，小贤能的人为大贤能的人所役使；政治黑暗之时，力量小的被力量大的所役使，弱的被强的所役使。这两种情况都是由天决定的。顺从天的就生存，违背天的就灭亡。”\n\n孟子所说的清明之世，是指诸如尧、舜、禹，以及汤、文、武、周公之世，因为他们能“尊贤使能，俊杰在位”，治世是依靠德行的高低而非力量的大小；黑暗之时则应该是指春秋战国时代，诸侯间兼并不断，实...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1557831401, '5cda2e6630863b00706841d1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642612, '孟子 · 第七卷 · 离娄上 · 第八节 ', NULL, 11, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“不仁者可与言哉？安其危而利其菑，乐其所以亡者。不仁而可与言，则何亡国败家之有？有孺子歌曰：‘沧浪之水清兮，可以濯我缨；沧浪之水浊兮，可以濯我足。’孔子曰：‘小子听之！清斯濯缨，浊斯濯足矣，自取之也。’夫人必自侮，然后人侮之；家必自毁，而后人毁之；国必自伐，而后人伐之。太甲曰：‘天作孽，犹可违；自作孽，不可活。’此之谓也。”', '', '菑（zāi）：同“灾”。
沧浪：河名，即汉水。缨：系在颈下的帽带。
沧浪四句：上古流传的民谣。
太甲：《尚书》篇名。
', '孟子说：“不仁的人可以同他谈论仁道吗？别人有危险，他安然不动，别人遭了灾，他却趁火打劫，高兴于别人所遭受的惨祸。不仁的人如果可以同他谈论仁道，那还会有亡国败家的事吗？有个小孩子唱道：‘沧浪的水清呀，可以洗我的帽缨；沧浪的水浊呀，可以洗我的双脚。’孔子说：‘弟子们听着！清呢，就洗帽缨；浊呢，就洗双脚。这都取决于水本身啊。’人一定先是有自取侮辱的原因，然后别人才侮辱他；家一定先是有自毁的原因，然后别人才毁掉它；国一定先是有自己招来攻伐的原因，然后别人才攻伐它。《太甲》说：‘天降的灾难还可以躲避，自找的灾难那可活不了。’说的就是这个意思。”
', '[{"bookId": "60fccb5034bfda01e0ea02ff", "bookTitle": "先秦诗鉴赏辞典（新一版）", "articleId": "610f376234a8757d5a0f813c", "shortContent": "这是春秋战国时代流传在汉水以北的一首民歌。《孟子·离娄》中说孔丘曾听到有小孩子唱这首歌，而据《论语》和《史记·楚世家》，孔丘曾到过楚国北部的叶县等地。《楚辞·渔父》写屈原听过渔父唱这首歌，因屈原曾被放汉北。\n就诗的蕴含而言，首先，因为江河之水同洗浴联系起来是在天气和暖之时，而且是一件愉快的事，所以这首诗从意象上来说是美的，从情调上来说是轻松的。其次，作为产生在楚国的民歌，似乎同屈原作品中表现出的喜...", "authors": ["赵逵夫"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557831445, '5cda2e9330863b007068449b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642613, '孟子 · 第七卷 · 离娄上 · 第九节 ', NULL, 12, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“桀纣之失天下也，失其民也；失其民者，失其心也。得天下有道：得其民，斯得天下矣；得其民有道：得其心，斯得民矣；得其心有道：所欲与之聚之，所恶勿施尔也。
民之归仁也，犹水之就下、兽之走圹也。故为渊驱鱼者，獭也；为丛驱爵者，鹯也；为汤武驱民者，桀与纣也。今天下之君有好仁者，则诸侯皆为之驱矣。虽欲无王，不可得已。
今之欲王者，犹七年之病求三年之艾也。苟为不畜，终身不得。苟不志于仁，终身忧辱，以陷于死亡。诗云‘其何能淑，载胥及溺’，此之谓也。”', '', '圹（kuàng）：同“旷”，旷野。
獭（tǎ）：兽名，喜食鱼。
爵：同“雀”。鹯（zhān）：猛禽，喜食雀。
艾：艾草。治病用的艾草，干的时间越长越管用，因此用“三年之艾”为喻，意谓如果平时不准备，则难以立刻得到。
指《诗经·大雅·桑柔》篇。
其：指朝内君臣。淑：好。载：语首助词，无义。胥：相互。及溺：至于沉溺。
', '孟子说：“桀、纣丧失天下，是因为失去老百姓的支持。失去支持，是因为失去了民心。得天下有办法：得到老百姓的支持就能得天下。得到老百姓的支持有办法：得民心，就能得到老百姓支持。得民心有办法：他们想要的，就给他们聚积起来；他们所厌恶的，不要强加给他们。老百姓归服仁政，就像水往下流，野兽往旷野跑。因此，为深池把鱼赶来的，是水獭；为森林把鸟雀赶来的，是猛鹰；为商汤、周武王把老百姓赶来的，是桀和纣。
“当今天下君王如果有爱仁德的，那么，各国诸侯都在为他驱赶百姓。即使不想统一天下，也办不到。当今想统一天下的，却像生了七年病的人要得到干了三年的艾草。如果不积蓄，是终身得不到的。如果不立志于仁德，是要终身忧患、受辱，以至于死亡的。《诗经》说：‘他们哪能变好，只能同归于尽。’说的就是这个意思。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0f6", "shortContent": "孟子从历史上反面君王的典型桀纣说起，分析了其失天下的根本原因：不得民心。又从正面剖析了得天下、得民心的正确做法：得天下的方法，在于获得百姓支持；获得百姓支持的方法，在于获得民心；获得民心的方法，在于给予和聚积百姓想要的，去掉百姓所厌恶的。孟子从正反两面说明了得民心的重要性，体现了他强烈的民本思想。那怎样才能让百姓满意呢？在孟子看来，让百姓满意莫过于推行仁政。他说：“夏商周三代获得天下是因为仁，失去...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1557831491, '5cda2ec07b968a00759833ee', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642614, '孟子 · 第七卷 · 离娄上 · 第十节 ', NULL, 18, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“自暴者，不可与有言也；自弃者，不可与有为也。言非礼义，谓之自暴也；吾身不能居仁由义，谓之自弃也。仁，人之安宅也；义，人之正路也。旷安宅而弗居，舍正路而不由，哀哉！”
', '', '暴：残害，糟蹋。
非：诋毁，破坏。
', '孟子说：“戕害自己的人，不可能同他有所谈论；自己抛弃自己的人，不可能同他有所作为。说出话来破坏礼义，这便叫做自己残害自己。自以为不能安居于仁，由义而行，这便叫做自己抛弃自己。仁，是人最安稳的住宅；义，是人最中正的道路。空着安稳的住宅而不住，舍弃正确的道路而不走，可悲啊！”

', NULL, '', 'indent', 1557831531, '5cda2ee817b54d0075c00757', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642615, '孟子 · 第七卷 · 离娄上 · 第十一节 ', NULL, 19, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“道在迩而求诸远，事在易而求之难。人人亲其亲、长其长而天下平。”', '', '迩：近。
', '孟子说：“道就在近处，却往远处去找它；事情本来容易，却往难处去做它。其实只要人人爱自己的双亲，尊敬自己的长辈，天下就太平了。”
', NULL, '', 'indent', 1557831571, '5cda2f117b968a0075983724', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642616, '孟子 · 第七卷 · 离娄上 · 第十二节 ', NULL, 12, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“居下位而不获于上，民不可得而治也。获于上有道：不信于友，弗获于上矣；信于友有道：事亲弗悦，弗信于友矣；悦亲有道：反身不诚，不悦于亲矣；诚身有道：不明乎善，不诚其身矣。是故诚者，天之道也；思诚者，人之道也。至诚而不动者，未之有也；不诚，未有能动者也。” ', '', '不获于上：得不到上级的信任。', '孟子说：“处于下级的地位而不能得到上级的信任，是不能治理好百姓的。得到上级的信任有办法，首先要得到朋友的信任，假如不能取信于朋友，就不能得到上级的信任。取信于朋友有办法，首先要得到父母的欢心。侍奉双亲而不能让他们高兴，就不能取信于朋友。让双亲高兴有办法，首先要诚心诚意，反躬自问而心意不诚，就不能让双亲高兴。使自己诚心诚意有办法，首先要明白什么是善，不明白善的道理，就不能使自己诚心诚意。因此，诚，是自然的道理。思慕诚，是做人的道理。极端诚心而不能使别人动心的，是从来没有的事；不诚心，是没有人会被感动的。”
', NULL, '', 'indent', 1557831602, '5cda2f30c8959c00688d3951', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642617, '孟子 · 第七卷 · 离娄上 · 第十三节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“伯夷辟纣，居北海之滨，闻文王作，兴曰：‘盍归乎来！吾闻西伯善养老者。’太公辟纣，居东海之滨，闻文王作，兴曰：‘盍归乎来！吾闻西伯善养老者。’二老者，天下之大老也，而归之，是天下之父归之也。天下之父归之，其子焉往？诸侯有行文王之政者，七年之内，必为政于天下矣。”', '', '辟：同“避”，躲避。
作：兴起。兴：起来。
盍：何不。来，语气助词。
西伯：即周文王。
太公：即姜太公吕尚。
大老：最有声望的老人。
', '孟子说：“伯夷避开纣王，住在北海岸边，听说文王兴起，便说：‘为什么不归附他！我听说西伯是善于奉养老人的人。’姜太公避开纣王住在东海岸边，听说文王兴起，便说：‘为什么不归附他！我听说西伯是善于奉养老人的人。’这两位老人，是天下德高望重的老人，都去归附文王，这好比天下做父亲的人都归附西伯。天下人的父亲都归附西伯了，他们的儿子还会去哪儿呢？当今的诸侯如果有能实行文王的政治的，不超过七年，就一定能统治天下。”
', NULL, '', 'indent', 1557831643, '5cda2f5930863b0070684cf0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642618, '孟子 · 第七卷 · 离娄上 · 第十四节 ', NULL, 4, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“求也为季氏宰，无能改于其德，而赋粟倍他日。孔子曰：‘求非我徒也，小子鸣鼓而攻之可也。’由此观之，君不行仁政而富之，皆弃于孔子者也。况于为之强战？争地以战，杀人盈野；争城以战，杀人盈城。此所谓率土地而食人肉，罪不容于死。故善战者服上刑，连诸侯者次之，辟草莱、任土地者次之。”', '', '求：冉求，字子有，孔子弟子。季氏：鲁国大夫。宰：家臣。
孔门弟子冉求为鲁国季氏家臣，增加了老百姓的赋税。事见《左传·哀公十一年》。
善战者：善于带兵打战的人，如孙膑、吴起之类。上刑：重刑。连诸侯者：指主张合纵或连横的纵横家。
辟草莱、任土地者：指主张尽地力的李悝、主张开阡陌的商鞅之类。辟草莱，开垦荒地。任土地，分土授民。孟子以为这些主张虽然意在发展生产，但并不是为百姓着想，而是为了统治者的私利，所以反对。
', '孟子说：“冉求做季氏的家臣，不能改善他的德行。反而多征收了一倍佃租。孔子说：‘冉求不是我的学生，你们打响战鼓去攻击他都可以。’由此看来，不帮助君主实行仁政而帮助他聚敛财富，都是被孔子鄙弃的。何况是努力为君主作战的人？为争夺土地而作战，杀死的人遍布原野；为争夺城池而作战，杀死的人遍布城池，这就叫带领土地吃人肉，死刑都不足以惩罚他们的罪行。因此好战的人应该受最重的刑罚，鼓吹诸侯合纵连横发动战争的人，受次一等的刑罚，开垦荒地，分土授田的人受再次一等的刑罚。”
', NULL, '', 'indent', 1557831723, '5cda2fa843e78c0065d85c95', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642619, '孟子 · 第七卷 · 离娄上 · 第十五节 ', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“存乎人者，莫良于眸子。眸子不能掩其恶。胸中正，则眸子瞭焉；胸中不正，则眸子眊焉。听其言也，观其眸子，人焉廋哉？”', '', '存：考察。眸子：瞳仁。
瞭（liǎo）：明亮。
眊（mào）：暗昧不明。
廋（sōu）：隐藏，藏匿。
', '孟子说：“观察一个人，没有比观察他的眼睛更好的了。眼睛不能掩饰一个人的丑恶。内心正直，眼睛就明亮；心术不正，眼睛就昏暗。听他说话，观察他的眼睛，这人的善恶哪里能隐藏得住！”
', NULL, '', 'indent', 1557831758, '5cda2fccc8959c00688d4005', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642620, '孟子 · 第七卷 · 离娄上 · 第十六节 ', NULL, 3, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“恭者不侮人，俭者不夺人。侮夺人之君，惟恐不顺焉，恶得为恭俭？恭俭岂可以声音笑貌为哉？”', '', '', '孟子说：“恭敬的人不会侮辱别人，生活节俭的人不会掠夺别人。侮辱、掠夺别人的君主，惟恐别人不顺从他，怎能称得上恭敬、节俭呢？恭敬和节俭这两种品德，难道可以只靠声音和笑貌勉强装出来的吗？”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b47807f27182da3ee0516", "shortContent": "孟子认为“恭”和“俭”是为人的两个重要品德。恭，敬也；俭，节俭。对人要恭敬有礼，具有这种品德就不会欺侮和侮辱别人；对己要节约俭朴，具有这种品德就不会掠夺别人。孟子还强调指出，恭和俭的品德光凭声音笑貌是做不出来的。就是说，恭敬和节俭是发之于内心真情的美德。心敬体恭，孔子的弟子子夏说：“君子敬而无失，与人恭而有礼”（《论语·颜渊》）。在现代语境中，恭敬之德就是要尊重他人的人格和权利，由此自然也就不会侵...", "authors": ["朱贻庭"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557914596, '5cdb73627b968a0073bd7efe', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642645, '孟子 · 第八卷 · 离娄下 · 第十三节 ', NULL, 2, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“养生者不足以当大事，惟送死可以当大事。”
', '', '', '孟子说：“只奉养健在的父母的难以担当大事情，只有为他们安葬送终了，才可以担当大事情。”
', NULL, '', 'indent', 1557915481, '5cdb76d5c8959c0068c9796f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642776, '孟子 · 第十三卷 · 尽心上 · 第二十九节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“有为者辟若掘井，掘井九轫而不及泉，犹为弃井也。”
', '', '辟：通“譬”。
轫（rèn）：通“仞”，古代长度单位，具体长度说法不一，通常认为一仞七尺或八尺。
', '孟子说：“做事情好比挖井，挖得很深还见不到泉水，仍是一口废井。”
', NULL, '', 'indent', 1558349032, '5ce214667b968a0073123829', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642621, '孟子 · 第七卷 · 离娄上 · 第十七节 ', NULL, 11, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '淳于髡曰：“男女授受不亲，礼与？”
孟子曰：“礼也。”
曰：“嫂溺则援之以手乎？”
曰：“嫂溺不援，是豺狼也。男女授受不亲，礼也；嫂溺援之以手者，权也。”
曰：“今天下溺矣，夫子之不援，何也？”
曰：“天下溺，援之以道；嫂溺，援之以手。子欲手援天下乎？”', '', '淳于髡（kūn）：姓淳于，名髡，齐人。曾在齐威王、齐宣王和梁惠王的朝廷做官。
权：变通。
', '淳于髡说：“男女之间不亲手递接东西，这是礼制吗？”
孟子说：“是礼制。”
淳于髡说：“嫂嫂掉到水里，用手拉她吗？”
孟子说：“嫂嫂掉到水里而不拉她，是豺狼。男女之间不亲手递接，是礼制。嫂嫂掉到水里，用手拉她，是变通的办法。”
淳于髡说：“当今天下都掉到水里了，先生不拉一把，为什么？”
孟子说：“天下掉到水里，要用道来救援。嫂嫂掉到水里，是用手去救援。你想用手来救援天下吗？”
', NULL, '', 'indent', 1557914641, '5cdb738f17b54d0068dfeb5e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642622, '孟子 · 第七卷 · 离娄上 · 第十八节 ', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '公孙丑曰：“君子之不教子，何也？”
孟子曰：“势不行也。教者必以正；以正不行，继之以怒；继之以怒，则反夷矣。‘夫子教我以正，夫子未出于正也。’则是父子相夷也。父子相夷，则恶矣。古者易子而教之。父子之间不责善。责善则离，离则不祥莫大焉。”', '', '夷：伤害。
夫子：儿子称父亲，可译作“您”。
', '公孙丑说：“君子不亲自教育自己的儿子，为什么呢？”
孟子说：“因为情势行不通，教育者一定用正确的道理。用正确的道理如果行不通，接着就发火。接着就发火，那反而伤感情了。儿子会说：‘您用正确的道理教导我，您却不从正确的道理出发。’那父子就会互相伤感情。父子互相伤感情，就坏了。古人互相交换儿子来教育，父子之间不用善的道理来责备对方。如果用善的道理来责备对方，就有了隔阂，一有隔阂，那就没有什么比这更不好的了。”

', NULL, '', 'indent', 1557914688, '5cdb73be43e78c00686b8125', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642623, '孟子 · 第七卷 · 离娄上 · 第十九节 ', NULL, 9, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“事孰为大？事亲为大；守孰为大？守身为大。不失其身而能事其亲者，吾闻之矣；失其身而能事其亲者，吾未之闻也。孰不为事？事亲，事之本也；孰不为守？守身，守之本也。曾子养曾皙，必有酒肉。将彻，必请所与。问有余，必曰‘有’。曾皙死，曾元养曾子，必有酒肉。将彻，不请所与。问有余，曰：‘亡矣’。将以复进也。此所谓养口体者也。若曾子，则可谓养志也。事亲若曾子者，可也。”', '', '曾子：曾参，孔子弟子。曾皙：名点，曾参之父，也是孔子弟子。
彻：撤除，撤去。这里指撤下酒肉。
曾元：曾参之子。
亡：同“无”。
', '孟子说：“侍奉谁最要紧？侍奉父母最要紧。守护谁最要紧？守护自己最要紧。不遗失自己的节操而能侍奉好父母的，我听说过，遗失了自己的节操而能侍奉好父母的，我没听说过。谁不该侍奉？侍奉父母，是侍奉中的根本。谁不该守护？守护自己，却是守护中的根本。从前曾参奉养曾皙，每餐必有酒肉，将要撤下时，一定问父亲剩下的给谁。如果父亲问这东西是否还有，他一定说‘有’。曾皙死后，曾元奉养曾参，每餐必有酒肉，将要撤下时，不问父亲剩下的给谁。如果父亲问这东西是否还有，他就说‘没有了’。其实他是想留着预备以后进用，不想给别人。这叫做奉养父母的口腹（身体）。像曾参那样，就可以叫做奉养意旨。侍奉父母像曾参那样的，就可以了。”
', NULL, '', 'indent', 1557914731, '5cdb73e86e9ba10068cc75c6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642624, '孟子 · 第七卷 · 离娄上 · 第二十节 ', NULL, 9, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“人不足与适也，政不足间也。惟大人为能格君心之非。君仁莫不仁，君义莫不义，君正莫不正。一正君而国定矣。”', '', '适（zhé）：通“谪”，谴责。
间（jiàn）：诋毁，非议。
格：纠正。
', '孟子说：“为官的小人不值得去谴责，政治不值得去非议。只有大人才能纠正君主心术的错误。君主仁，就没有人不仁；君主义，就没有人不义；君主正，就没有人不正，一旦把君主端正了，国家就安定了。”
', NULL, '', 'indent', 1557914763, '5cdb740817b54d0068dff192', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642625, '孟子 · 第七卷 · 离娄上 · 第二十一节 ', NULL, 3, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“有不虞之誉，有求全之毁。”
', '', '虞：料想。
', '孟子说：“有料想不到的赞誉，也有求全责备的非议。”
', NULL, '', 'indent', 1557914801, '5cdb742743e78c00686b8664', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642626, '孟子 · 第七卷 · 离娄上 · 第二十二节 ', NULL, 10, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“人之易其言也，无责耳矣。” ', '', '', '孟子说：“一个人之所以信口开河，是因为他不必负说话的责任。”
', NULL, '', 'indent', 1557914828, '5cdb744a7b968a0073bd8ee3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642627, '孟子 · 第七卷 · 离娄上 · 第二十三节 ', NULL, 71, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“人之患在好为人师。”
', '', '', '孟子说：“人的毛病在于喜欢做别人的老师。”
', NULL, '', 'indent', 1557914847, '5cdb745c43e78c00686b8959', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642628, '孟子 · 第七卷 · 离娄上 · 第二十四节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '乐正子从于子敖之齐。乐正子见孟子。孟子曰：“子亦来见我乎？”
曰：“先生何为出此言也？”
曰：“子来几日矣？”曰：“昔者。”
曰：“昔者，则我出此言也，不亦宜乎？”
曰：“舍馆未定。”
曰：“子闻之也，舍馆定，然后求见长者乎？”
曰：“克有罪。”', '', '子敖：王驩的字，齐王宠臣。（参见卷四第六章。）
昔者：昨天。
舍馆：住宿的馆驿。
克：乐正子名。
', '乐正子跟随子敖来到齐国。
乐正子前来见孟子。孟子说：“你也是来见我的吗？”
乐正子说：“先生为什么说这个话？”
孟子说：“你来了几天了？”
乐正子说：“前天来的。”
孟子说：“前天！那么我这么说话，不应该吗？”
乐正子说：“（刚来的时候）住处还没安定下来。”
孟子说：“你听说过，住处安定了，然后再求见长辈吗？”
乐正子说：“我有错。”
', NULL, '', 'indent', 1557914903, '5cdb74956e9ba10068cc802c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642629, '孟子 · 第七卷 · 离娄上 · 第二十五节 ', NULL, 4, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子谓乐正子曰：“子之从于子敖来，徒餔啜也。我不意子学古之道而以餔啜也。”
', '', '徒：仅仅。餔（bū）：吃。啜（chuò）：饮。
', '孟子对乐正子说：“你跟随子敖来，只是为了吃吃喝喝呀。我没想到你（跟随我）学习古人之道竟然是为了吃吃喝喝呀。”
', NULL, '', 'indent', 1557914932, '5cdb74b230863b00696a67bf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642630, '孟子 · 第七卷 · 离娄上 · 第二十六节 ', NULL, 12, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“不孝有三，无后为大。舜不告而娶，为无后也，君子以为犹告也。”
', '', '不孝有三，无后为大：孟子的原意，并不是说不生孩子就是不孝，最不孝的是没有对长辈尽到后代的责任。在孟子的原话中并没有讲明其他的两种不孝是什么。到了东汉，赵岐在《十三经注》中阐述了他个人对于孟子这段话的理解：“于礼有不孝者三事，谓阿意曲从，陷亲不义，一不孝也；家穷亲老，不为禄仕，二不孝也；不娶无子，绝先祖祀，三不孝也。三者之中，无后为大。”这才将“无后为大”曲解成为：不娶妻生子，断绝后代。
不告：不禀告父母。
', '孟子说：“不孝顺的事有三种，其中没有循守后辈的责任，是最大的不孝。舜不先禀告父母就娶妻，就因为担心没有子孙，因此君子认为他（虽然）没有禀告也同禀告过了是一样的。”
', NULL, '', 'indent', 1557914998, '5cdb74f230863b00696a6ab6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642631, '孟子 · 第七卷 · 离娄上 · 第二十七节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“仁之实，事亲是也；义之实，从兄是也；智之实，知斯二者弗去是也；礼之实，节文斯二者是也；乐之实，乐斯二者，乐则生矣；生则恶可已也，恶可已，则不知足之蹈之手之舞之。”
', '', '实：犹言核心、本质。下同。
节文：有次第有分寸地体现出来。
', '孟子说：“仁的实质，就是侍奉双亲；义的实质，就是服从兄长；智的实质，就是懂得这二者的道理而不可离弃。礼的实质，就是对这二者加以调节和修饰；乐的实质，在于高兴地做到这二者，于是快乐就产生了。只要一产生快乐，就抑制不住，怎么能停下来，于是不知不觉就手舞足蹈起来。”
', NULL, '', 'indent', 1557915040, '5cdb751e6e9ba10068cc86b0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642632, '孟子 · 第七卷 · 离娄上 · 第二十八节 ', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“天下大悦而将归己，视天下悦而归己，犹草芥也，惟舜为然。不得乎亲，不可以为人；不顺乎亲，不可以为子。舜尽事亲之道而瞽瞍厎豫，瞽瞍厎豫而天下化，瞽瞍厎豫而天下之为父子者定，此之谓大孝。”
', '', '草芥：像草和芥一样不足珍惜，比喻轻贱。
瞽（gǔ）瞍（sǒu）：舜的父亲。厎（zhī）豫：得以快乐。厎，致。豫，安乐，安逸。
', '孟子说：“天下人都很高兴地来归附自己，把天下人都高兴归附（这件事），看得像草芥一样，只有舜能做到。不能得父母的欢心，不可以做人。不顺从父母，不可以做孩子。舜尽心尽力侍奉父亲而瞽瞍终于高兴，瞽瞍终于高兴而天下的风俗为之潜移默化，瞽瞍终于高兴而天下做父亲、做儿子的伦常也由此确定，这叫做大孝。”
', NULL, '', 'indent', 1557915072, '5cdb753e30863b00696a6ec0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642633, '孟子 · 第八卷 · 离娄下 · 第一节', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“舜生于诸冯，迁于负夏，卒于鸣条，东夷之人也。文王生于岐周，卒于毕郢，西夷之人也。地之相去也，千有余里；世之相后也，夭有余岁。得志行乎中国，若合符节。先圣后圣，其揆一也。” ', '', '诸冯、负夏、鸣条：古代的地名，传说中舜居住过的地方。
岐周：岐山下的周邑。毕郢：地名，在今陕西咸阳东。
符节：古代表示印信之物，用玉或铜、竹等原料制成虎、龙等形状，或篆刻文字，剖为两半，各执其一，有事则左右相合，以为印信。
揆（kuí）：道理，准则。
', '孟子说：“舜诞生在诸冯，迁居到负夏，死在鸣条，是东方偏远地区的人。文王生在周国的岐山，死在毕郢，是西方偏远地区的人人。两地距离一千多里，时代相隔一千多年。但是当他们得志时在中国的所作所为，却像符节相合那样相同，古代的圣人和后代的圣人，他们的准则是相同的。”
', NULL, '', 'indent', 1557915129, '5cdb757643e78c00686b9e33', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642634, '孟子 · 第八卷 · 离娄下 · 第二节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '子产听郑国之政，以其乘舆济人于溱洧。
孟子曰：“惠而不知为政。岁十一月徒杠成，十二月舆梁成，民未病涉也。君子平其政，行辟人可也。焉得人人而济之？故为政者，每人而悦之，日亦不足矣。”', '', '子产：春秋时郑国贤相公孙侨，字子产。溱（zhēn）洧（wěi）：都是水名，在今河南省。
十一月：指周历，相当于夏历九月。下文十二月，相当于夏历十月。夏历九、十月是农闲时节，所以在这时修桥。徒杠：可供徒步行走的独木桥。
舆梁：可供车行的桥。病：发愁。
辟（pì）人：指执鞭者开道，让行人回避。辟，辟除。
', '子产主持郑国的政治，曾用他自己的车帮人渡过溱水、洧水。孟子说：“这是私恩小惠却不懂得搞政治。如果在十一月修成可供徒步的桥，在十二月修成可供车行的桥，老百姓就不必为渡河发愁了。君子只要把政治搞好，外出时执鞭开道，让行人回避都可以，哪里能人人帮他过河呢？所以，如果搞政治的人，想讨人人欢心，日子也就不够用了。”
', NULL, '', 'indent', 1557915168, '5cdb759e43e78c00686ba03a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642635, '孟子 · 第八卷 · 离娄下 · 第三节 ', NULL, 7, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子告齐宣王曰：“君之视臣如手足；则臣视君如腹心；君之视臣如犬马，则臣视君如国人；君之视臣如土芥，则臣视君如寇雠。”
王曰：“礼，为旧君有服，何如斯可为服矣？”
曰：“谏行言听，膏泽下于民；有故而去，则君使人导之出疆，又先于其所往；去三年不反，然后收其田里。此之谓三有礼焉。如此，则为之服矣。今也为臣。谏则不行，言则不听；膏泽不下于民；有故而去，则君搏执之，又极之于其所往；去之日，遂收其田里。此之谓寇雠。寇雠何服之有？”', '', '雠（chóu）：仇敌。
旧君：旧时侍奉的君主。服：古代丧礼穿的丧服。
膏泽：比喻恩惠。
搏执：捆绑。极：困穷，使动用法。
', '孟子告诉齐宣王说：“君主把臣下当作自己的手足，那么臣下就会把君主当作腹心；君主把臣下当作狗马，那么臣子就会把君主当作路人；君主把臣下当作土和草，那么臣下就会把君主当作仇敌。”
王说：“礼制规定，（已经离开职位的）臣下要为往日的君主穿孝服，怎样才能使臣下为他服孝呢？”
孟子说：“有劝谏，就照着做，有什么话，都听从，恩惠普及于百姓；臣下如果有事离开，就派人引导他离开国境，又打发人先到他要去的地方作好准备；离开了三年还不回来，这才收回他的田地房产。这叫三有礼。这样，臣下就会为他服孝了。现在做臣下的，劝谏，王不照着办，说的话，王不听从，恩惠不能普及于百姓；臣下有事离开，君主就把他捆绑起来，又设法让他在所去的地方走投无路；离开的当天，就收回他的田地房产。这叫做仇敌。对仇敌样的旧君，还服什么孝？”

', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0f7", "shortContent": "中国在漫长的封建统治时代，不断上演着朝代更迭、江山易主的剧目，一代代的君与一朝朝的臣演绎着复杂的君臣关系。提到这一关系，首先让人想到的自然是“君君臣臣、父父子子”（《论语·颜渊》）、“君要臣死，臣不得不死”这样的字句，似乎臣之于君，必须是绝对的忠心，无条件的付出。但孟子却认为，君与臣之间应当是一种相互的关系：君对待臣下如同手足，那么臣下待君王便会推心置腹；君对待臣下如同狗马，那么臣下待君王便如同陌...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b47a966a763596afec38a", "shortContent": "与《论语》相比，总体上来看，《孟子》中的对话、论辩、议论体裁的文字明显增多，篇幅也普遍加长。但是，它在文体上也继承和发展了《论语》的语录体，书中有不少类似于《论语》的那种简短的语录。它们只表述观点，往往只有两三句话，不加以充分的展开与论证，但却思想深邃，含义隽永，耐人寻味，发人深思。语录体最适合保存民族精神导师的思想成果，虽然缺少逻辑分析，看不到理论思维过程，但观点鲜明，具有指导性，读后令人刻骨铭...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1557915213, '5cdb75c443e78c00686ba24c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642636, '孟子 · 第八卷 · 离娄下 · 第四节 ', NULL, 2, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“无罪而杀士，则大夫可以去；无罪而戮民，则士可以徙。”
', '', '', '孟子说：“士人无罪却被杀掉，那么大夫可以离开；百姓无罪却被屠戮，那么士人可以迁走。”
', NULL, '', 'indent', 1557915236, '5cdb75e3c8959c0068c96c2d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642646, '孟子 · 第八卷 · 离娄下 · 第十四节 ', NULL, 12, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“君子深造之以道，欲其自得之也。自得之，则居之安；居之安，则资之深；资之深，则取之左右逢其原，故君子欲其自得之也。”', '', '资：积蓄。
左右逢其原：原，同“源”，水源。意思是学问的功夫深，则取之不尽，用之不竭。比喻处事行文，得心应手。
', '孟子说：“君子依循正确的方法获得高深的造诣，就是要能自觉地有所得。自觉地有所得，就能牢固地掌握它而不动摇，就能积蓄深厚（知识）；积蓄深厚（知识），就能取之不尽，左右逢源，所以君子希望能自觉地有所得。”
', NULL, '', 'indent', 1557915518, '5cdb76fc43e78c00686bb2b5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642647, '孟子 · 第八卷 · 离娄下 · 第十五节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“博学而详说之，将以反说约也。”
', '', '约：简明，扼要。', '孟子说：“广博地学习，详尽地解说，最终还是要回到简略地陈述大义的境界。”
', NULL, '', 'indent', 1557915553, '5cdb771ec8959c0068c98048', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642648, '孟子 · 第八卷 · 离娄下 · 第十六节 ', NULL, 11, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“以善服人者，未有能服人者也；以善养人，然后能服天下。天下不心服而王者，未之有也。”
', '', '', '孟子说：“用善来使人服输，没有能使人服输的。用善来熏陶教养人，这才能使天下人信服。天下人不能心服，却能统一天下的，是从来没有过的事。”
', NULL, '', 'indent', 1557915578, '5cdb773817b54d0068e01b94', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642649, '孟子 · 第八卷 · 离娄下 · 第十七节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“言无实不祥，不祥之实，蔽贤者当之。”
', '', '不祥：不善。
', '孟子说：“说话不符合实际，是不会有好的结果的。说话符合实际，而得到不好的结果，那些阻碍贤者进用的人应当承担责任。”
', NULL, '', 'indent', 1557915606, '5cdb77546e9ba10068cca504', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642650, '孟子 · 第八卷 · 离娄下 · 第十八节', NULL, 9, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '徐子曰：“仲尼亟称于水，曰：‘水哉，水哉！’何取于水也？”
孟子曰：“原泉混混，不舍昼夜。盈科而后进，放乎四海，有本者如是，是之取尔。苟为无本，七八月之闲雨集，沟浍皆盈；其涸也，可立而待也。故声闻过情，君子耻之。”', '', '徐子：即徐辟，孟子弟子。
亟（qì）：屡次。
混混（gǔngǔn）：水流旺盛的样子。科：坎地。
浍（kuài）：田间的排水渠。
声闻：名声。
', '徐子说：“孔子多次称赞水，说：‘水啊，水啊！’他赞同水的什么方面呢？”
孟子说：“从源头里流出的泉水滚滚奔流，日夜不停，注满了洼地以后才向前进，一直流到大海去。有本源的（事物）就像这样，孔子赞同水的这一点。如果是没有本源的，像七八月间雨水汇集，水沟、水渠一下都满了，但它们的干涸，也是立等可待的。所以名誉超过实情，是君子引以为耻辱的。”
', NULL, '', 'indent', 1557915660, '5cdb778917b54d0068e01f58', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642651, '孟子 · 第八卷 · 离娄下 · 第十九节 ', NULL, 6, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“人之所以异于禽兽者几希，庶民去之，君子存之。舜明于庶物，察于人伦，由仁义行，非行仁义也。”', '', '几希：形容少。
由：经由，遵循。
', '孟子说：“人不同于禽兽的就只有那么一点点，一般的老百姓把仁义丢弃了，而君子却时时心里装着它。舜明白万物的规律，了解人事的道理，自觉遵循仁义的道路行走，而不是把仁义作为手段来使用。”
', NULL, '', 'indent', 1557915699, '5cdb77b0c8959c0068c988c8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642652, '孟子 · 第八卷 · 离娄下 · 第二十节 ', NULL, 9, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“禹恶旨酒而好善言。汤执中，立贤无方。文王视民如伤，望道而未之见。武王不泄迩，不忘远。周公思兼三王，以施四事；其有不合者，仰而思之，夜以继日；幸而得之，坐以待旦。”', '', '旨酒：美酒。
执中：守中庸之道。方：类，常规。
而（rú）：通“如”。
泄（xiè）：通“媟”，狎，轻侮。迩：近，指朝臣。远：指远方的贤士。
三王：指夏、商、周三代贤王。四事：前述禹、汤、文王、武王四人的事迹。
', '孟子说：“禹厌恶美酒而喜爱有道理的话。汤坚守中庸之道，选拔贤人却都不照死规矩办。文王对待老百姓就像对待受伤的人（总是同情抚慰），渴望真理就像从未见过一样。武王不轻侮近臣，也不遗忘远方的贤人。周公想要兼学夏、商、周三代的王，来实践禹、汤、文王、武王所行的勋业，自己的言行有与他们不符合的，就仰头考虑，白天想不好，晚上接着想；侥幸想出了结果，就坐着等待天亮去付诸实施。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0f8", "shortContent": "人们常说“读万卷书，行万里路”，书给予我们真知，而行则是对真知的实践和历练，知行要做到合一。周公为一代圣贤，为后世所推崇敬仰，他辅佐成王治国，治国之时，想要兼学夏、商、周三朝君王，来实践禹、汤、文、武四王所行的功业，遇到有不相符合的地方，便抬头思索，夜以继日，一旦侥幸想通了，就坐等着，一到天亮便马上实行。这是讲周公勤于思考，积极践行思考所得。“知”犹如杰出设计师心中完美的设计构图，无论构思得如何精...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1557915738, '5cdb77d730863b00696a91c8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642653, '孟子 · 第八卷 · 离娄下 · 第二十一节 ', NULL, 2, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“王者之迹熄，而诗亡，诗亡然后春秋作。晋之乘，楚之梼杌，鲁之春秋，一也。其事则齐桓、晋文，其文则史。孔子曰：‘其义则丘窃取之矣。’”', '', '王者之迹熄：指平王东迁，周王朝的政教号令不及于天下。
《乘（shèng）》《梼杌（táo wù）》《春秋》：春秋各国史书通名为“春秋”，《乘》《梼杌》分别是晋国和楚国史书的别名。鲁之《春秋》，也是鲁国当日的史书，为孔子编订《春秋》之所本。
义：善善恶恶，暗寓褒贬。
', '孟子说：“王者的（采集民间歌谣的）事迹泯灭了，《诗》也就没有了，《诗》没有后，《春秋》出现了。晋国的《乘》、楚国的《梼杌》、鲁国的《春秋》，是一样的。所记载的是齐桓公、晋文公的事，所用的笔法是一般史书的笔法。孔子说：‘扬善抑恶的大义，我在《春秋》上便借用了。’
', NULL, '', 'indent', 1557915774, '5cdb77fc17b54d0068e0250e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642654, '孟子 · 第八卷 · 离娄下 · 第二十二节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“君子之泽五世而斩，小人之泽五世而斩。予未得为孔子徒也，予私淑诸人也。”
', '', '泽：禄位。斩：断绝。
', '孟子说：“君子的德泽五代以后便断绝了，小人的德泽也是五代以后便断绝了。我没能成为孔子的门徒，我是私下向人学习来的。”
', NULL, '', 'indent', 1557915808, '5cdb781c6e9ba10068ccb0fe', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642655, '孟子 · 第八卷 · 离娄下 · 第二十三节', NULL, 5, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“可以取，可以无取，取伤廉；可以与，可以无与，与伤惠；可以死，可以无死，死伤勇。”', '', '', '孟子说：“可以取，可以不取，取了就有损于廉洁；可以给，可以不给，给了就有损于恩惠；可以死，可以不死，死了就有损于勇敢。”
', NULL, '', 'indent', 1557915849, '5cdb784730863b00696a96e6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642656, '孟子 · 第八卷 · 离娄下 · 第二十四节 ', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '逄蒙学射于羿，尽羿之道，思天下惟羿为愈己，于是杀羿。
孟子曰：“是亦羿有罪焉。公明仪曰：‘宜若无罪焉。’曰薄乎云尔，恶得无罪？郑人使子濯孺子侵卫，卫使庾公之斯追之。子濯孺子曰：‘今日我疾作，不可以执弓，吾死矣夫！’问其仆曰：‘追我者谁也？’其仆曰：‘庾公之斯也。’曰：‘吾生矣。’其仆曰：‘庾公之斯，卫之善射者也，夫子曰“吾生”，何谓也？’曰：‘庾公之斯学射于尹公之他，尹公之他学射于我。夫尹公之他，端人也，其取友必端矣。’庾公之斯至，曰：‘夫子何为不执弓？’曰：‘今日我疾作，不可以执弓。’曰：‘小人学射于尹公之他，尹公之他学射于夫子。我不忍以夫子之道反害夫子。虽然，今日之事，君事也，我不敢废。’抽矢扣轮，去其金，发乘矢而后反。”', '', '逄（páng）蒙：羿的学生、家众。羿（yì）：擅长射箭，篡夏自立，逄蒙助寒浞杀羿。
子濯孺子：郑国的武将。庾公之斯：卫国的将领。
尹公之他：卫国人。
端人：正派人或正直的人。
金：指箭镞。乘矢：四支箭。
', '逄蒙向羿学习射箭，完全掌握了羿的本领，心想天下只有羿超过自己，于是杀了羿。孟子说：“这事也有羿的过错。”
公明仪说：“好像没有他的过错吧。”
孟子说：“过错不大罢了，怎能说没有过错呢？郑国派子濯孺子攻打卫国，卫国派庾公之斯追击他。子濯孺子说：‘今天我的病发作，拿不了弓，我必死无疑了！’向给他驾车的人问道：‘追我的是谁呢？’驾车的人说：‘是庾公之斯。’子濯孺子说：‘我死不了了。’驾车的人问道：‘庾公之斯是卫国擅长射箭的人，先生却说我死不了，什么意思？’子濯孺子回答道：‘庾公之斯是向尹公之他学的射箭，尹公之他是向我学的射箭。尹公之他是个正派人，他所交的朋友一定也是正派人。’尹公之他是向我学的射箭。尹公之他是个正派人，他所交的朋友一定也是正派人。’庾公之斯赶到了，说：‘先生为什么不拿弓？’子濯孺子说：‘今天我的病发作，拿不了弓。’庾公之斯便说：‘我是向尹公之他学的射箭，尹公之他是向先生学的射箭。我不忍心用先生的本领反过来伤害先生。尽管这样，今天的事，是君主的公事，我不敢不办。’于是抽出箭，在车轮上敲了几下，把箭镞去掉，发射了四支后便回去了。”
', NULL, '', 'indent', 1557915927, '5cdb7895c8959c0068c99366', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642657, '孟子 · 第八卷 · 离娄下 · 第二十五节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“西子蒙不洁，则人皆掩鼻而过之。虽有恶人，齐戒沐浴，则可以祀上帝。”', '', '西子：西施，古代传说中的美人。
恶：丑陋。
', '孟子说：“即使是西施沾染了不干净的东西，别人从她身边走过，也都会捂着鼻子。而即使是丑陋的人，只要斋戒沐浴了，也可以祭祀上帝。”
', NULL, '', 'indent', 1558001230, '5cdcc5bf43e78c00687f1c69', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642658, '孟子 · 第八卷 · 离娄下 · 第二十六节 ', NULL, 18, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“天下之言性也，则故而已矣。故者以利为本。所恶于智者，为其凿也。如智者若禹之行水也，则无恶于智矣。禹之行水也，行其所无事也。如智者亦行其所无事，则智亦大矣。天之高也，星辰之远也，苟求其故，千岁之日至，可坐而致也。”', '', '性：物性或人性。故：指事物已有的迹象，即事物的本然状态。
利：顺应。
日至：冬至。
', '孟子说：“天下讲本性的，都是指它的本身固有的状态罢了。它的本身固有的状态是以顺应自然为根本。聪明之所以令人厌恶，是因为它的穿凿。如果聪明人像大禹治水那样，聪明就不令人厌恶了。大禹治水，只是顺应水势，因势利导，看来就像无所作为。如果聪明人也能这样无所作为，那就是大聪明了。天极高，星辰极远，如果研究它们已有的迹象，千年以后的冬至，都可以坐着推算出来。”
', NULL, '', 'indent', 1558001271, '5cdcc5f530863b00697e35ab', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642659, '孟子 · 第八卷 · 离娄下 · 第二十七节 ', NULL, 4, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '公行子有子之丧，右师往吊，入门，有进而与右师言者，有就右师之位而与右师言者。孟子不与右师言，右师不悦曰：“诸君子皆与欢言，孟子独不与欢言，是简欢也。”
孟子闻之，曰：“礼，朝廷不历位而相与言，不逾阶而相揖也。我欲行礼，子敖以我为简，不亦异乎？”', '', '公行子：齐国大夫。右师：官名。其人即王欢，字子敖。
简：轻视，怠慢。
历、逾：超越，跨越。
异：奇怪。
', '公行子的儿子死了。右师去吊唁，进了门，有上前去和他说话的，坐定后，又有靠近他的座位和他说话的。孟子不和右师说话，右师不高兴，说：“各位君子都和我说话，唯有孟子不和我说话，这是怠慢我。”
孟子听说了，说：“礼的规矩是，在朝廷上不越过位次来交谈，不越过台阶来作揖。我要依礼而行，子敖却以为我怠慢他，不是很奇怪吗？”
', NULL, '', 'indent', 1558001303, '5cdcc61530863b00697e377f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642660, '孟子 · 第八卷 · 离娄下 · 第二十八节 ', NULL, 29, 271, 5, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“君子所以异于人者，以其存心也。君子以仁存心，以礼存心。仁者爱人，有礼者敬人。爱人者人恒爱之，敬人者人恒敬之。
有人于此，其待我以横逆，则君子必自反也：我必不仁也，必无礼也，此物奚宜至哉？其自反而仁矣，自反而有礼矣，其横逆由是也，君子必自反也：我必不忠。自反而忠矣，其横逆由是也，君子曰：‘此亦妄人也已矣。如此则与禽兽奚择哉？于禽兽又何难焉？’
是故，君子有终身之忧，无一朝之患也。乃若所忧则有之：舜人也，我亦人也。舜为法于天下，可传于后世，我由未免为乡人也，是则可忧也。忧之如何？如舜而已矣。
若夫君子所患则亡矣。非仁无为也，非礼无行也。如有一朝之患，则君子不患矣。”', '', '横（hèng）逆：强暴不顺理。
物：事。
由：通“犹”。
择：区别。
', '孟子说：“君子和一般人不同的地方，在于他的存心。君子把仁放在心上，把礼放在心上。仁人爱别人，有礼的人尊敬别人。爱别人的人，别人常爱他；尊敬别人的人，别人常尊敬他。假如这里有个人，他对我粗暴无理，那么，君子一定自我反省：我一定不仁，一定无礼，否则这种事怎么会落到我头上？自我反省之后认为自己是仁的，自我反省之后认为自己是有礼的，那粗暴无理的还是这样，君子一定又自我反省，我一定不忠。自我反省之后认为自己是忠心耿耿的，那粗暴无理的还是这样。君子就说：‘这是个狂妄的人罢了。既是这样，他和禽兽有什么区别呢？对于禽兽还有什么可责备的呢？’因此君子有终身的忧虑，但没有意外的痛苦。这样的忧虑是有的：舜，是个人；我，也是个人。舜成为天下人的模范，可以流传到后代，我只不过是个普通人，这就是值得忧虑的。有忧虑了怎么办？努力像舜一样罢了。至于君子的痛苦，那是没有的。不是仁的事不做，不是合于礼的事不干。假如有意外的灾难到来，君子也不会为它感到特别的痛苦了。”

', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0fa", "shortContent": "孟子认为：君子同一般人不同的地方，就在于其居心。君子居心于仁，居心于礼。仁人爱别人，有礼的人恭敬别人。爱别人的人，别人经常爱他；恭敬别人的人，别人经常恭敬他。这里涉及的是一个人的为人处世方法，以及由此带来的人际关系问题。\n\n在孟子看来，君子为人处世离不开仁和礼。仁是儒家最重要的伦理规范之一，照孔子的话讲，仁就是“爱人”，就是“克己复礼”，其核心是孝悌，即孝敬父母，敬爱兄弟。所以孔子“爱人”的实质又...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1558001346, '5cdcc63fc8959c0068dd35ec', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642676, '孟子 · 第十卷 · 万章下 · 第二节 ', NULL, 2, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '北宫锜问曰：“周室班爵禄也，如之何？”
孟子曰：“其详不可得闻也。诸侯恶其害己也，而皆去其籍。然而轲也，尝闻其略也。天子一位，公一位，侯一位，伯一位，子、男同一位，凡五等也。君一位，卿一位，大夫一位，上士一位，中士一位，下士一位，凡六等。天子之制，地方千里，公侯皆方百里，伯七十里，子、男五十里，凡四等。不能五十里，不达于天子，附于诸侯，曰附庸。天子之卿受地视侯，大夫受地视伯，元士受地视子、男。大国地方百里，君十卿禄，卿禄四大夫，大夫倍上士，上士倍中士，中士倍下士，下士与庶人在官者同禄，禄足以代其耕也。次国地方七十里，君十卿禄，卿禄三大夫，大夫倍上士，上士倍中士，中士倍下士，下士与庶人在官者同禄，禄足以代其耕也。小国地方五十里，君十卿禄，卿禄二大夫，大夫倍上士，上士倍中士，中士倍下士，下士与庶人在官者同禄，禄足以代其耕也。耕者之所获，一夫百亩。百亩之粪，上农夫食九人，上次食八人，中食七人，中次食六人，下食五人。庶人在官者，其禄以是为差。”', '', '北宫锜（yǐ）：姓北宫，名锜，卫国人。
班：等列，规定等级。
位：爵次。
不能：不及，不足。
视：比照，同。
四大夫：四倍于大夫。倍上士：比上士多一倍。
粪：施肥耕作。食：养活。
', '北宫锜问道：“周王朝规定官爵和俸禄的等级，是什么情况？”
孟子说：“详细的情况不能了解了，由于诸侯厌恶那制度对自己的不利，都把文献毁坏了；不过我曾经听说过它的大致情况。普天下爵位的制度是，天子一级，公一级，侯一级，伯一级，子、男同为一级，共五等。各国官位的制度是，君主一级，卿一级，大夫一级，上士一级，中士一级，下士一级，共六等。俸禄的制度是，天子的土地，方圆各一千里，公与侯都是方圆各一百里，伯是方圆各七十里，子和男都是方圆各五十里，共四等。不足五十里的小国，不能直接隶属天子，而是附属于诸侯，叫做附庸。天子的卿所受的封地与侯同样大小，大夫所受的封地与伯同样大小，元士所受的封地与子、男同样大小。公、侯大国的土地方圆各一百里，君主的俸禄是卿的十倍，卿的俸禄是大夫的四倍，大夫比上士多一倍，上士比中士多一倍，中士比下士多一倍，下士的俸禄和在官当差的老百姓相同，俸禄足够代替他耕田的收入。中等国家的土地是方圆各七十里，君主的俸禄是卿的十倍，卿的俸禄是大夫的三倍，大夫比上士多一倍，上士比中士多一倍，中士比下士多一倍，下士的俸禄和在官当差的老百姓相同，俸禄足够代替他耕田的收入。小国的土地是方圆各五十里，君主的俸禄是卿的十倍，卿的俸禄是大夫的二倍，大夫比上士多一倍，上士比中士多一倍，中士比下士多一倍，下士的俸禄和在官当差的老百姓相同，俸禄足够代替他耕田的收入。农夫的所得，是一夫受田百亩。百亩地进行施肥耕种，上等的农夫可以养活九口人，上等偏下的农夫可以养活八口人，中等的农夫可以养活七口人，中等偏下的农夫可以养活六口人，下等的农夫可以养活五口人。老百姓在官家当差的，他们的俸禄也照这样分等级。”
', NULL, '', 'indent', 1558002231, '5cdcc9b56e9ba10068e06a60', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642661, '孟子 · 第八卷 · 离娄下 · 第二十九节 ', NULL, 4, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '禹、稷当平世，三过其门而不入，孔子贤之。颜子当乱世，居于陋巷。一箪食，一瓢饮。人不堪其忧，颜子不改其乐，孔子贤之。
孟子曰：“禹、稷、颜回同道。禹思天下有溺者，由己溺之也；稷思天下有饥者，由己饥之也，是以如是其急也。禹、稷、颜子易地则皆然。今有同室之人斗者，救之，虽被发缨冠而救之，可也。乡邻有斗者，被发缨冠而往救之，则惑也，虽闭户可也。”', '', '三过其门而不入：此本大禹之事，亦用以称颂后稷。
颜子：颜回，孔子弟子。一箪食，一瓢饮：一筐饭，一瓢水。此言颜回生活清苦。
被（pī）发：披散着头发；被，同“披”。缨冠，把帽带顶在头上。帽带本该自上而下系在颈上，这里指因急于戴帽，来不及这样办，所以只和帽子一样顶在头上。
', '禹、稷处在太平的时代，三次经过自己家门都不进去，孔子称赞他们。颜回处在动乱的时代，住在简陋的巷子里，一筐饭，一瓢水；别人受不了那种忧患，颜回却不改他的快乐，孔子称赞他。孟子说：“禹、稷和颜回走的是同一条路。禹想到天下有溺水的人，就如同自己溺水一样；稷想到天下有饥饿的人，就如同自己饿了一样，所以那样急迫（去解救他们）。禹、稷和颜回如果交换地位，颜回也会三过家门而不入，禹、稷也会深居陋巷而自得其乐。假如现在有同屋的人互相争斗，你去救他，即使披散着头发，连帽缨也不结就去救他，也是可以的。如果本乡有邻居互相争斗，你也披散着头发，连帽缨也不结就去救他，那就是糊涂了，对此即使关着门（不去管它）都可以。”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b47cc7f27182da3ee068c", "shortContent": " 这几章主要是讲述“存心”，即存养仁德之心的必要性和方法。同其他儒学大师一样，孟子从不把自我修养当成完全脱离世俗生活、纯粹内省式的心灵活动，而视为主客体互动的过程。在这里他是从个体同他人的关系、个体与其所处的社会历史条件和生活环境的关系，以及个体与家人的关系这三方面来说明怎样通过“自反”来存养善心。\n\n“存心”可以先从人际关系开始，如果有人对自己横暴无理，那么首先不是去埋怨他人，更不是马上就以眼还...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558001396, '5cdcc672c8959c0068dd382a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642662, '孟子 · 第八卷 · 离娄下 · 第三十节 ', NULL, 8, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '公都子曰：“匡章，通国皆称不孝焉。夫子与之游，又从而礼貌之，敢问何也？”
孟子曰：“世俗所谓不孝者五：惰其四支，不顾父母之养，一不孝也；博弈好饮酒，不顾父母之养，二不孝也；好货财，私妻子，不顾父母之养，三不孝也；从耳目之欲，以为父母戮，四不孝也；好勇斗很，以危父母，五不孝也。章子有一于是乎？
夫章子，子父责善而不相遇也。责善，朋友之道也；父子责善，贼恩之大者。
夫章子，岂不欲有夫妻子母之属哉？为得罪于父，不得近。出妻，屏子，终身不养焉。其设心以为不若是，是则罪之大者，是则章子已矣。”', '', '四支：四体；支，同“肢”。
博弈：六博（古代的一种游戏）和围棋。这里指赌博。
从：同“纵”。戮：羞辱。
很：今作“狠”。
遇：合。
屏（bǐng）：赶出。
', '公都子说：“匡章，全国都说他不孝，先生和他交往，而且对他礼敬有加，请问这是为什么？”
孟子说：“一般所谓不孝有五种：四肢懒惰，不管父母的赡养，是第一种不孝；喜欢赌博、喝酒，不管父母的赡养，是第二种不孝；喜欢钱财，偏爱妻子儿女，不管父母的赡养，是第三种不孝；放纵耳目的欲望，使父母蒙受羞辱，是第四种不孝；逞勇好斗，危及父母，是第五种不孝。章子可有其中的一种吗？章子呀，不过是父子之间以善相责而不能好好相处。以善相责，是朋友相处的道理。父子之间以善相责，是最伤感情的。章子呀，难道不想有夫妻、母子的团聚？因为得罪了父亲，不能和他亲近，所以把妻子儿女赶出门，终身不养育他们。他心想如果不是这样，那罪过就更大了，这就是章子呀。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a7014b56e213e684f0f9", "shortContent": "“孝”历来是中华民族的传统美德。所谓国家，有国才有家，有家乃成国，家庭是社会的基本组成单位。家是以血缘关系为基础而存在的，千百年来，中国社会极其重视血亲关系，而血亲关系以父母子女为最亲最重要，孝则是维系这一关系的道德准则。列夫·托尔斯泰说：“幸福的家庭都是相似的，不幸的家庭却各有各的不幸。”（《安娜·卡列尼娜》）中国式的幸福家庭也是相似的，都是父慈子孝、兄友弟恭。“百善孝为先”，可见中国传统对孝的...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1558001441, '5cdcc69e6e9ba10068e041e7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642663, '孟子 · 第八卷 · 离娄下 · 第三十一节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '曾子居武城，有越寇。或曰：“寇至，盍去诸？”
曰：“无寓人于我室，毁伤其薪木。”寇退，则曰：“修我墙屋，我将反。”寇退，曾子反。
左右曰：“待先生，如此其忠且敬也。寇至则先去以为民望，寇退则反，殆于不可。”
沈犹行曰：“是非汝所知也。昔沈犹有负刍之祸，从先生者七十人，未有与焉。”
子思居于卫，有齐寇。或曰：“寇至，盍去诸？”子思曰：“如急去，君谁与守？”
孟子曰：“曾子、子思同道。曾子，师也，父兄也；子思，臣也，微也。曾子、子思易地则皆然。”
', '', '武城：鲁国邑名，故城在今山东费县西南。
左右：指曾参的学生。
殆于：近于。
沈犹行：曾参弟子，姓沈犹，名行。
负刍：人名。七十人：古称孔门弟子有“七十二贤人”，简称“七十人”。此处泛指曾参门徒，未可坐实。
子思：孔子之孙，名伋，字子思。
', '曾子住在武城，有越国军队入侵。有人说：“敌人要来了，何不离开这里？”
曾子说：“不要让人住到我屋里，毁坏那些树木。”敌人撤退了，他又说：“修葺好我的房屋，我要回来了。”敌人撤退，曾子回来了。曾子的学生议论说：“武城的人们待先生这样忠诚恭敬，敌人一来您先走开，给老百姓树立了一个坏榜样；敌人一退您就回来，恐怕不可以的。”沈犹行说：“这不是你们懂得的。从前先生住在我那里，遇到一个叫负刍的人作乱，随从先生的七十人，也都跟着先生走了，没有人参加抵抗。”
子思住在卫国，有齐国的军队入侵。有人说：“敌人要来了，何不离开这里？”子思说：“如果我走了，君主和谁一道来守城呢？”
孟子说：“曾子、子思走的是同一条道路。曾子，是老师，是父兄。子思，是臣子，是地位较低的人。曾子和子思如果互换地位，也会像对方一样行动的。”
', NULL, '', 'indent', 1558001492, '5cdcc6d217b54d0068f3bd5d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642664, '孟子 · 第八卷 · 离娄下 · 第三十二节 ', NULL, 3, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '储子曰：“王使人瞷夫子，果有以异于人乎？”孟子曰：“何以异于人哉？尧舜与人同耳。”', '', '储子：齐国人。
瞷（jiàn）：窥视。
', '储子说：“大王派人来窥探先生，先生真的有跟别人不同之处吗？”
孟子说：“哪有跟别人不同的呢？尧、舜跟别人也都是一样的。”
', NULL, '', 'indent', 1558001532, '5cdcc6f943e78c00687f2cbe', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642665, '孟子 · 第八卷 · 离娄下 · 第三十三节 ', NULL, 5, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '齐人有一妻一妾而处室者，其良人出，则必餍酒肉而后反。其妻问所与饮食者，则尽富贵也。其妻告其妾曰：“良人出，则必餍酒肉而后反；问其与饮食者，尽富贵也，而未尝有显者来，吾将瞷良人之所之也。”蚤起，施从良人之所之，遍国中无与立谈者。卒之东郭墦闲，之祭者，乞其余；不足，又顾而之他，此其为餍足之道也。其妻归，告其妾曰：“良人者，所仰望而终身也。今若此。”与其妾讪其良人，而相泣于中庭。而良人未之知也，施施从外来，骄其妻妾。
由君子观之，则人之所以求富贵利达者，其妻妾不羞也，而不相泣者，几希矣。', '', '良人：丈夫。
蚤：通“早”。施（yǐ）：通“迤”，逶迤行进。
墦（fán）：坟墓。
讪（shàn）：讥刺，毁谤。相：相向，相与。
施施：喜悦自得的样子。
几希：很稀少。
', '齐国有个人，家里有一妻一妾。那丈夫外出，一定酒足饭饱以后才回来。他的妻子问是谁与他一起吃喝，他回答说，都是些富人权贵。他的妻子对妾说：“丈夫外出，一定酒足饭饱以后才回来，若问是谁与他一起吃喝，所答都是些富人权贵，但家里从来没有显贵的人来访，我打算偷偷地看他究竟到哪儿去。”
第二天一早起来，她便尾随丈夫到他所去的地方，走遍城中，没有一个人站住同他说话的。最后到了东郊的墓地间，向祭扫坟墓的人乞讨残羹剩饭，不够吃，又四下张望找别人，这就是他吃饱喝足的办法。
那妻子回到家来，告诉妾说：“丈夫，是我们仰望而终身依靠的人，如今他竟是这样的。”于是同妾一道嘲骂丈夫，又在院子里相对而泣，而丈夫还不知道，得意扬扬地从外面回来，向他的妻妾耍威风。
在君子看来，人们用来求富贵显达的办法，能使他们的妻妾不感到羞耻，不相对而哭泣的，恐怕是很少的。
', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d10f8fda5565061579", "shortContent": "本文选自《孟子·离娄下》。\n孟子的文章以论辩见长，气势磅礴，力量充沛，令人不得不为之口服心折。但《齐人》这一章，却从另一角度显示他的文学功夫，读来另有一番情趣。无怪乎后人有的称之为开小品之先河，有的把它看做小说的雏形。因为全文虽只有二百余字，可是含有辛辣而深刻的讽刺意味，而且初步具备了作为小说所必需的三要素———人物、情节、环境。\n孟子对待富贵利禄的态度是，不是完全排斥它，而是要取之以其道，不能强...", "authors": ["卢", "元"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f852e6a6b501f974b65", "shortContent": "关于中国绘画的怪诞记载，精彩的不多，画龙点睛，龙即腾空飞去是最著名的，《画工》也甚为离奇，可以比美“画龙点睛”的故事。\n画上美人为什么叫“真真”呢？这可不是随意决定的。因为画上美人明明是假的。画工要求赵颜昼夜不止地呼上一百天“真真”，也就是要求赵颜百分之百地把画上美人信以为真，相信如画工所说那样，会使之变成活生生的人。\n赵颜完全依照画工的要求这样做了，画上美人果真走了下来，并且和赵颜开始了同居，还...", "authors": ["蒋星煜"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3fa7dbb8b379ee0aecf2", "shortContent": "本篇情节曲曲折折，读来颇具兴味。一个富人生了毒疮，从两脚蔓延开来，“脓血溃腐，孔如蜂房”，无法行走，躺在床上多年了。这一天，忽然来了个道士，声称能够治这病，而索要的报酬，却只是“蔬食一饱耳”。情节进展至此，为之“一折”：世上哪有这么便宜的事？那妻子一心要为丈夫治病，无暇考虑及此。那富人不信，说是“诳也”，也在情理之中。此时读者的心中，恐怕大多也会认为是“诳也”。但是，“令却之”却有点令人惋惜：“蔬...", "authors": ["全岳春"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558001580, '5cdcc72943e78c00687f2ecc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (950233, '折桂令·棋', NULL, NULL, 1, 2, 0, '鲜于必仁', NULL, 50581, '648db34406326254dc1a0f93', '元', 'qu', '曲', '', '', '烂樵柯石室忘归，足智神谋，妙理仙机。险似隋唐，胜如楚汉，败若梁齐。
消日月闲中是非，傲乾坤忙里轻肥。不曳旌旗，寸纸关河，万里安危。', '', '', '', NULL, '', 'indent', 1690653939, '648db39448e44a05aa264e64', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (950266, '杂剧 · 破幽梦孤雁汉宫秋', NULL, NULL, 68, 1, 0, '马致远', NULL, 10091, '57b9b9eb79bc4400639c4264', '元', 'qu', '曲', '', '', '楔子
（冲末扮番王引部落上，诗云）毡帐秋风迷宿草，穹庐夜月听悲笳。控弦百万为君长，款塞称藩属汉家。某乃呼韩耶单于是也。若论俺家世，久居朔漠，独霸北方，以射猎为生，攻伐为事。大王曾避俺东徙，魏绛曾怕俺讲和。獯鬻犭严狁，逐代易名：单于可汗，随时称号。当秦汉交兵之时，中原有事，俺国强盛，有控弦甲士百万。俺祖公冒顿单于，围汉高帝于白登七日，用娄敬之谋，两国讲和，以公主嫁俺国中。至惠帝、吕后以来，每代必循故事，以宗女归俺番家。宣帝之世，我众兄弟争立不定，国势稍弱。今众部落立我为呼韩耶单于，实是汉朝外甥。我有甲士十万，南移近塞，称藩汉室。昨曾遣使进贡，欲请公主，未知汉帝肯寻盟约否？今日天高气爽，众头目每，向沙堤射猎一番，多少是好！正是：番家无产业，弓矢是生涯。（下）（净扮毛延寿上，诗云）为人雕心雁爪，做事欺大压小。全凭谄佞奸贪，一生受用不了。某非别人，毛延寿的便是。现在汉朝驾下，为中大夫之职。因我百般巧诈，一味谄谀，哄的皇帝老头儿十分欢喜，言听计从。朝里朝外，那一个不怕我，那一个不敬我？我又学的一个法儿，只是教皇帝少见儒臣，多昵女色，我这宠幸才得牢固。道尤末了，圣驾早上。（正末扮汉元帝引内官、宫女上，诗云）嗣传十叶继炎刘，独掌乾坤四百州。边塞久盟和议策，从今高枕已无忧。某汉元帝是也。俺祖高皇帝，奋布衣，起丰沛，灭秦屠项，挣下这等基业。传到朕躬，已是十代。自朕嗣位以来，四海晏然，八方宁静。非朕躬有德，皆赖众文武扶持。自先帝晏驾之后，宫女尽放出宫去了。今后宫寂寞，如何是好！（毛延寿云）陛下，田舍翁多收十斛麦，尚欲易妇，况陛下贵为天子，富有四海。合无遣官遍行天下，选择室女。不分王侯宰相、军民人家，但要十五以上，二十以下者，容貌端正，尽选将来，以充后宫，有何不可？（驾云）卿说的是。就加卿为选择使，赍领诏书一通，遍行天下刷选。将选中者各图形一轴送来，朕按图临幸。待卿成功回时，别有区处。（唱）
【仙吕】【赏花时】四海平安绝士马，五谷丰登没战伐。寡人待刷室女选宫娃，你避不的驰驱困乏。看那一个合属俺帝王家。（下）
第一折
（毛延寿上，诗云）大块黄金任意挝，血海王条全不怕。生前只要有钱财，死后那管人唾骂。某毛延寿，领着大汉皇帝圣旨，遍行天下，刷选室女，已选够九十九名。各家尽肯馈送，所得金银却也不少。昨日来到成都秭归县，选得一人，乃是王长者之女，名唤王嫱，字昭君。生得光彩射人，十分艳丽，真乃天下绝色。争奈他本是庄农人家，无大钱财。我问他要百两黄金，选为第一。他一则说家道贫穷，二则倚着他容貌出众，全然不肯。我本待退了他。（做忖科，云）不要倒好了他！眉头一纵，计上心来，只把美人图点上些破绽，到京师必定发入冷宫，教他受苦一世。正是：恨小非君子，无毒不丈夫。（下）（正旦扮王嫱引二宫女上，诗云）一日承宣入上阳，十年未得见君王。良宵寂寂谁来伴，唯有琵琶引兴长。妾身王嫱，小字昭君，成都秭归人也。父亲王长者，平生务农为业。母亲生妾时，梦月入怀，复坠于地，后来生下妾身。年长一十八岁，蒙恩选充后宫。不想使臣毛延寿问妾身索要金银，不曾与他，将妾影图点破，不曾得见君王，现今退居永巷。妾身在家颇通丝竹，弹得几曲琵琶。当此夜深孤闷之时，我试理一曲消遣咱。（做弹科）（驾引内官提灯上，云）某汉元帝。自从刷选室女入宫，多有不曾宠幸，煞是怨望咱。今日万机稍暇，不免寻宫走一遭，看那个有缘的，得遇朕躬也呵。（唱）
【仙吕】【点绛唇】车碾残花，玉人月下，吹箫罢。未遇宫娃，是几度添白发。
【混江龙】料必他竹帘不挂，望昭阳一步一天涯。疑了些无风竹影，恨了些有月窗纱。他每见弦管声中寻玉辇，恰便似斗牛星畔盼浮槎。（旦做弹科）（驾云）是那里弹的琵琶响？（内官云）是。（正末唱）是谁人偷弹一曲，写出嗟呀？（内官云）快报去接驾。（驾云）不要。（唱）莫便要忙传圣旨，报与他家。我则怕乍蒙恩，把不定心儿怕，惊起宫槐宿鸟、庭树栖鸦。（云）小黄门，你看是那一宫的宫女弹琵琶，传旨去教他来接驾，不要惊吓着他。（内官报科，云）兀那弹琵琶的是那位娘娘？圣驾到来，急忙迎接者。（旦趋接科）（驾唱）
【油葫芦】恕无罪，吾当亲问咱。这里属那位下？休怪我不曾来往乍行踏。我特来填还你这泪揾湿鲛鱼肖帕，温和你露冷透凌波袜。天生下这艳姿，合是我宠幸他。今宵画烛银台下，剥地管喜信爆灯花。（云）小黄门，你看那纱笼内烛光越亮了，你与我挑起来看咱。（唱）
【天下乐】和他也弄着精神射绛纱。卿家，你觑咱，则他那瘦岩岩影儿可喜杀。（旦云）妾身早知陛下驾临，只合迎接。接驾不早，妾该万死。（驾唱）迎头儿称妾身，满口儿呼陛下，必不是寻常百姓家。（云）看了他容貌端正，是好女子也呵！（唱）
【醉中天】将两叶赛宫样眉儿画，把一个宜梳裹脸儿搽；额角香钿贴翠花，一笑有倾城价。若是越勾践姑苏台上见他，那西施半筹也不纳，更敢早十年败国亡家。
（云）你这等模样出众，谁家女子？（旦云）妾姓王名嫱，字昭君，成都秭归县人。父亲王长者。祖父以来务农为业，闾阎百姓，不知帝王家礼度。（驾唱）
【金盏儿】我看你眉扫黛，鬓堆鸦，腰弄柳，脸舒霞。那昭阳到处难安插，谁问你一梨两坝做生涯？也是你君恩留枕簟，天教雨露润桑麻。既不沙俺江山千万里，直寻到茅舍两三家。
（云）看卿这等体态，如何不得近幸？（旦云）妾父王长者，止生妾身，当初选时，使臣毛延寿索要金银，妾家贫寒无凑，故将妾眼下点成破绽，因此发入冷宫。（驾云）小黄门，你取那影图来看，（黄门取图看科）（驾唱）
【醉扶归】我则问那待诏别无话，却怎么这颜色不加搽？点得这一寸秋波玉有暇。端的是卿眇目，他双瞎？便宣的八百姻娇比并他，也未必强如俺娘娘带破赚丹青画。
（云）小黄门，传旨说与金吾卫，便拿毛延寿斩首报来。（旦云）陛下，妾父母在成都见隶民籍，望陛下恩典宽免，量与些恩荣咱。（驾云）这个容易。（唱）
【金盏儿】你便晨挑菜，夜看瓜，春种谷，夏浇麻。情取棘针门粉壁上除了差法，你向正阳门改嫁的倒荣华。俺官职颇高如村社长，这宅院刚大似县官衙。谢天地可怜穷女婿，再谁敢欺负俺丈人家！（云）近前来，听寡人旨，封你做明妃者。（旦云）量妾身怎生消受的陛下恩宠！（做谢恩科）（驾唱）
【赚煞】且尽此宵情，休问明朝话。（旦云）陛下明朝早早驾临，妾这里侯驾。（驾唱）到明日，多管是醉卧在昭阳御榻。（旦云）妾身贱微，虽蒙恩宠，怎敢耍望与陛下同榻？（驾唱）休烦恼，吾当且是耍，斗卿来便当真假。恰才家辇路儿熟滑，怎下的真个长门再不踏！明夜里西宫阁下，你是必悄声儿接驾，我则怕六宫人攀例拨琵琶。（下）
（旦云）驾回了也。左右，且掩上宫门，我睡些去。（下）
第二折
（番王引部落上，云）某呼韩单于。昨遣使臣款汉，请嫁公主与俺。汉皇帝以公主尚幼为辞，我心中好不自在。想汉家宫中，无边宫女，就与俺一个，打甚不紧？直将使臣赶回。我欲待起兵南侵，又恐怕失了数年和好。且看事势如何，别做道理。（毛延寿上，云）某毛延寿。只因刷选宫女，索要金银，将王昭君美人图点破，送入冷宫。不想皇帝亲幸，问出端的，要将我加刑。我得空逃走了，无处投奔。左右是左右，将着这一轴美人图，献与单于王，着他按图索要，不怕汉朝不与他。走了数日，来到这里，远远的望见人马浩大，敢是穹庐也。（做问科，云）头目，你启报单于王知道，说汉朝大臣来投见哩。（卒报科）（番王云）着他过来。（见科，云）你是甚么人？（毛延寿云）某是汉朝中大夫毛延寿。有我汉朝西宫阁下美人王昭君，生得绝色。前者大王遣使求公主时，那昭君情愿请行，汉主舍不的，不肯放来。某再三苦谏，说："岂可重女色，失两国之好？"汉主倒要杀我。某因此带了这美人图，献与大王。可遣使按图索要，必然得了也。这就是图样。（进上看科）（番王云）世间那有如此女人！若得他做阙氏，我愿足矣。如今就差一番官，率领部从写书与汉天子，求索王昭君与俺和亲。若不肯与，不日南侵，江山难保。就一壁厢引控甲士，随地打猎，延入塞内，侦候动静，多少是好！（下）（旦引宫女上，云）随身王嫱。自前日蒙恩临幸，不觉又旬月。主上昵爱过甚，久不设朝。闻的升殿去了，我且向妆台边梳妆一会，收拾整齐，只怕驾来好服侍。（做对镜科）（驾上，云）自从西宫阁下得见了王昭君，使朕如痴似醉，久不临朝。今日方才升殿，等不的散了，只索再到西宫看一看去。（唱）
【南吕】【一枝花】四时雨露匀，万里江山秀。忠臣皆有用，高枕已无忧。守着那皓齿星眸，争忍的虚白昼。近新来染得些症候，一半儿为国忧民，一半儿愁花病酒。
【梁州第七】我虽是见宰相似文王施礼，一头地离明妃，早宋玉悲秋。怎奈他带天香着莫定龙衣袖。他诸余可爱，所事儿相投；消磨人幽闷，陪伴我闲游；偏宜向梨花月底登楼，芙蓉烛下藏阄。体态是二十年挑剔就的温柔，姻缘是五百载该拨下的配偶，脸儿有一千般说不尽的风流，寡人乞求他左右，他比那落伽山观自在无杨柳，见一面得长寿。情系人心早晚休，则除是雨歇云收。
（做望见科，云）且不要惊着他，待朕悄悄地看咱。（唱）
【隔尾】恁的般长门前抱怨的宫娥旧，怎知我西宫下偏心儿梦境熟。爱他晚妆罢，描不成画不就，尚对菱花自羞。（做到旦背后看科）（唱）我来到这妆台背后，原来广寒殿嫦娥在这月明里有。
（旦做见接驾科）（外扮尚书、丑扮常侍上，诗云）调和鼎鼐理阴阳，秉轴持钧政事堂。只会中书陪伴食。何曾一日为君王。某尚书令五鹿充宗是也。这个是内常侍石显。今日朝罢，有番国遣使来索王嫱和番，不免奏驾。来到西宫阁下，只索进去。（做见科，云）奏的我主得知：如今北番呼韩单于，差一使臣前来，说毛延寿将美人图献与他，索要昭君娘娘和番，以息刀兵。不然，他大势南侵，江山不可保矣。（驾云）我养军千日，用军一时。空有满朝文武，那一个与我退的番兵！都是些畏刀避箭的，您不去出力，怎生教娘娘和番！（唱）
【牧羊关】兴废从来有，干戈不肯休。可不食君禄，命悬君口。太平时卖你宰相功劳，有事处把俺佳人递流。你们干请了皇家奉，着甚的分破帝王忧？那壁厢锁树的怕弯着手，这壁厢攀栏的怕攧破了头。（尚书云）他外国说，陛下宠昵王嫱，朝纲尽废，坏了国家。若不与他，兴兵吊伐。臣想纣王只为宠妲己，国破身亡，是其鉴也。（驾唱）
【贺新郎】俺又不曾彻青霄，高盖起摘星楼。不说他伊尹扶汤，则说那武王伐纣。有一朝身到黄泉后，若和他留侯、留侯厮遘，你可也羞那不羞？您卧重裀食列鼎，乘肥马衣轻裘。您须见舞春风嫩柳宫腰瘦，怎下的教他环佩影摇青冢月，琵琶声断黑江秋！（尚书云）陛下，咱这里兵甲不利，又无猛将与他相持，倘或疏失，如之奈何？望陛下割恩与他，以救一国生灵之命。（驾唱）
【斗虾蟆】当日个谁展英雄手，能枭项羽头，把江山属俺炎刘？全亏韩元帅九里山前战斗，十大功劳成就。您也丹犀里头，枉被金章紫绶；您也朱门里头，都宠着歌衫舞袖。恐怕边关透漏，央及家人奔骤。似箭穿着雁口，没个人敢咳嗽。吾当僝僽，他也、他也红妆年幼无人搭救。昭君共你每有甚么杀父母冤仇？休、休，少不的满朝中都做了毛延寿！我呵，空掌着文武三千队，中原四百州，只待要割鸿沟。陡恁的千军易得，一将难求！
（常侍云）现今番使朝外等宣。（驾云）罢、罢、罢，教番使临朝来。（番使入见科，云）呼韩耶单于差臣南来，奏大汉皇帝：北国与南朝，自来结交和好，曾两次差人求公主不与。今有毛延寿，将一美人图献与俺单于。特差臣来，单索昭君为阏氏，以息两国刀兵。陛下若不从，俺有百万雄兵，刻日南侵，以决胜负。伏望圣鉴不错。（驾云）且教使臣馆驿中安歇去。（番使下）（驾云）您众文武商量，有策献来，可退番兵，免教昭君和番。大抵是欺娘娘软善，若当时吕后在日，一言之出，谁敢违拗！若如此，久已后也不用文武，只凭佳人平定天下便了。（唱）
【哭皇天】你有甚事疾忙奏，俺无那鼎镬边滚热油。我道您文臣安社稷，武将定戈矛；您只会文武班头，山呼万岁，舞蹈扬尘，道那声诚惶顿首。如今阳关路上，昭君出塞；当日未央宫里，女主垂旒。文武每，我不信你敢差排吕太后。枉以后、龙争虎斗，都是俺鸾交凤友。
（旦云）妾既蒙陛下厚恩，当效一死，以报陛下。妾情愿和番，得息刀兵，亦可留名青史。但妾与陛下闱房之情，怎生抛舍也！（驾云）我可知舍不的卿哩！（尚书云）陛下割恩断爱，以社稷为念，早早发送娘娘去罢。（驾唱）
【乌夜啼】今日嫁单于，宰相休生受，早则俺汉明妃有国难投，它那里黄云不出青山岫。投至两处凝眸，盼得一雁横秋。单注着寡人今岁揽闲愁，王嫱这运添憔瘦。翠羽冠，香罗绶，都做了锦蒙头暖帽，珠络缝貂裘。
（云）卿等今日先选送明妃到驿中，交付番使，待明日朕亲出灞陵桥，送饯一杯去。（尚书云）只怕使不的，惹外夷耻笑。（驾云）卿等所言，我都依着。我的意思，如何不依？好歹去送一送。我一会家只恨毛延寿那厮。（唱）
【三煞】我则恨那忘恩咬主贼禽兽，怎生不画在凌烟阁上头？紫台行都是俺手里的众公侯，有那椿儿不共卿谋，那件儿不依卿奏，争忍教第一夜梦迤逗？从今后不见长安望北斗，生扭作织女牵牛！（尚书云）不是臣等强逼娘娘和番，奈番使定名索取。况自古以来，多有因女色败国者。（驾唱）
【二煞】虽然似昭君般成败都皆有，谁似这做天子的官差不自由！情知他怎收那膘满的骅骝。往常时翠轿香兜，兀自倦朱帘揭绣，上下处要成就。谁承望月自空明水自流，恨思悠悠。
（旦云）妾身这一去，虽为国家大计，争奈舍不的陛下。（驾唱）
【黄钟尾】怕娘娘觉饥时吃一块淡淡盐烧肉，害渴时喝一杓儿酪和粥。我索折一枝断肠柳，饯一杯送路酒。眼见得赶程途趁宿头，痛伤心重回首。则怕他望不见凤阁龙楼，今夜且则向灞陵桥畔宿。（下）
第三折
（番使拥旦上，奏胡乐科，旦云）妾身王昭君。自从选入宫中，被毛延寿将美人图点破，送入冷宫。甫能得蒙恩幸，又被他献与番王形像。今拥兵来索，待不去，又怕江山有失。没奈何将妾身出塞和番。这一去，胡地风霜，怎生消受也！自古道"红颜胜人多薄命，莫怨春风当自嗟。"（驾引文武内官上，云）今日灞桥饯送明妃，却早来到也。（唱）
【双调】【新水令】锦貂裘生改尽汉宫妆，我则索看昭君图画模样。旧恩金勒短，新恨玉鞭长。本是对金殿鸳鸯，分飞翼怎承望！
（云）您文武百官计议，怎生退了番兵，免明妃和番者？（唱）
【驻马听】宰相每商量，大国使还朝多赐赏。早是俺夫妻悒怏，小家儿出外也摇装。尚兀自渭城衰柳助凄凉，共那灞桥流水添惆怅。您偏不断肠。想娘娘那一天愁都撮在琵琶上。
（做下马科）（与旦打悲科）（驾云）左右慢慢唱者，我与明妃饯一杯酒。（唱）
【步步娇】您将那一曲阳关休轻放，俺咫尺如天样。慢慢捧玉觞，朕本意待尊前捱些时光。且休问劣了宫商，您则与我半句儿俄延着唱。
（番使云）请娘娘早行，天色晚了也。（驾唱）
【落梅风】可怜俺别离重，你好是归去的忙。寡人心先到他李陵台上。回头儿却才魂梦里想，便休题贵人多忘。
（旦云）妾这一去，再何时得见陛下？把我汉家衣服都留下者。（诗云）正是：今日汉宫人，明朝胡地妾。忍着主衣裳，为人作春色。（留衣服科）（驾唱）
【殿前欢】说甚么留下舞衣裳，被西风吹散旧时香。我委实怕宫车再过青苔巷，猛到椒房，那一会想菱花镜里妆，风流相，兜的又横心上。看今日昭君出塞，几时似苏武还乡？
（番使云）请娘娘行罢，臣等来多时了也。（驾云）罢罢罢，明妃，你这一去，休怨朕躬也。（做别科，驾云）我那里是大汉皇帝！（唱）
【雁儿落】我做了别虞姬楚霸王，全不见守玉关征西将。那里取保亲的李左车，送女客的萧丞相？（尚书云）陛下不必挂念。（驾唱）
【得胜令】那里也架海紫金梁？枉养着那边庭上铁衣郎。您也要左右人扶持，俺可甚糟糠妻不下堂！您但提起刀枪，却早小鹿儿心头撞。今日央及煞娘娘，怎做的男儿当自强！
（尚书云）陛下，咱回朝去罢。（驾唱）
【川拨棹】怕不待放丝缰，咱可甚鞭敲金镫响。你管燮理阴阳，掌握朝纲。治国安邦，展土开疆。假若俺高皇，差你个梅香，背井离乡，卧雪眠霜。若是他不恋您春风画堂，我便官封你一字王。
（尚书云）陛下，不必苦死留他，着他去了罢。（驾唱）
【七兄弟】说甚么大王、不当、恋王嫱，兀良，怎禁他临去也回头望！那堪这散风雪旌节影悠扬，动关山鼓角声悲壮。
【梅花酒】呀！俺向着这回野悲凉：草已添黄，兔早迎霜；犬褪得毛苍，人搠起缨枪；马负着行装，车运着粮，打猎起围场。他、他、他伤心辞汉主，我、我、我携手上河梁。他部从入穷荒，我銮舆返咸阳。返咸阳，过宫墙；过宫墙，绕回廊；绕回廊，近椒房；近椒房，月昏黄；月昏黄，夜生凉；夜生凉，泣寒螀，绿纱窗；绿纱窗，不量思。
【收江南】呀！不思量除是铁心肠。铁心肠也愁泪滴千行。美人图今夜挂昭阳，我那里从养，便是我高烧银烛照红妆。
（尚书云）陛下回銮罢，娘娘去远了也。（驾唱）
【鸳鸯煞】我则索大臣行说一个推辞谎，又则怕笔尖儿那火编修讲。不见他花朵儿精神，怎趁那草地里风光？唱道伫立多时，徘徊半响；猛听的塞雁南翔，呀呀的声嘹亮。却原来满目牛羊，是兀那载离恨的毡车半坡里响。（下）
（番王引部落拥昭君上，云）今日汉朝不弃旧盟，将王昭君与俺番家和亲。我将昭君封为宁胡阏氏，坐我正宫。两国息兵，多少是好。众将士，传下号令，大众起行，望北而去。（做行科）（旦问云）这里甚地面了？（番使云）这是黑龙江，番汉交界去处。南边属汉家，北边属我番国。（旦云）大王，借一杯酒，望南浇奠；辞了汉家，长行去罢。（做奠酒科，云）汉朝皇帝，妾身今生已矣，尚待来生也。（做跳江科）（番王惊救不及，叹科，云）嗨，可惜可惜！昭君不肯入番，投江而死。罢罢罢，就葬在此江边，号为青冢者。我想来，人也死了，枉与汉朝结下这般仇隙，都是毛延寿那厮搬弄出来的。把都儿，将毛延寿拿下，解送汉朝处治。我依旧与汉朝结和，永为甥舅，却不是好！（诗云）则为他丹青画误了昭君，背汉主暗地私奔；将美人图又来哄我，要索取出塞和亲。岂知道投江而死，空落的一见消魂。似这等奸邪逆贼，留着他终是祸根。不如送他去汉朝哈剌，依还的甥舅礼，两国长存。（下）
第四折
（驾引内官上，云）自家汉元帝。自从明妃和番，寡人一百日不曾设朝。今当此夜景萧索，好生烦恼。且将这美人图挂起，少解闷怀也呵。（唱）
【中吕】【粉蝶儿】宝殿凉生，夜迢迢六宫人静。对银台一点寒灯，枕席间、临寝处，越显的吾身薄幸。万里龙廷，知他宿谁家一灵真性。
（云）小黄门，你看炉香尽了，再添上些香。（唱）
【醉春风】烧尽御炉香，再添黄串饼。想娘娘似竹林寺不见半分形，则留下这个影、影。未死之时，再生之日，我可也一般恭敬。
（云）一时困倦，我且睡些儿。（唱）
【叫声】高唐梦苦难成，那里也爱卿、爱卿，却怎生无些灵圣？偏不许楚襄王枕上雨云情。（做睡科，）（旦上，云）妾身王嫱，一番到北地，私自逃回。兀的不是我主人！陛下，妾身来了也。（番兵上，云）恰才我打了个盹，王昭君就偷走回去了。我急急赶来，进的汉宫，兀的不是昭君！（做拿旦下）（驾醒科，云）恰才见昭君回来，这些儿如何就不见了？（唱）
【剔银灯】恰才这搭儿单于王使命，呼唤俺那昭君名姓。偏寡人唤娘娘不肯灯前应，却原来是画上的丹青。猛听得仙音院凤管鸣，更说甚萧韶九成。
【蔓青菜】白日里无承应，教寡人不曾一觉到天明，做的个团圆梦境。（雁见科）（唱）却原来雁叫长门两三声，怎知道更有个人孤另。
（雁叫科）（唱）
【白鹤子】多管是春秋高，筋力短，莫不是食水少，骨毛轻？待去后，愁江南网罗宽；待向前，怕塞北雕弓硬。
【幺篇】伤感似替昭君思汉主，哀怨似作薤露哭田横，凄怆似和半夜梦歌声，悲切似唱三叠阳关令。（雁叫科）（云）则被那泼毛团叫的凄楚人也。（唱）
【上小楼】早是我神思不安，又添个冤家缠定。他叫得慢一会儿紧一声儿，和尽寒更。不争你打盘旋，这搭里同声相应，可不差讹了四时节令？
【幺篇】你却待寻子卿、觅李陵，对着银台，叫醒咱家，对影生情。则俺那远乡的汉明妃虽然得命，不见你个泼毛团也耳根清净。
（雁叫科）（云）这雁儿呵。（唱）
【满庭芳】又不是心中爱听，大古似林风瑟瑟，岩溜冷冷。我只见山长水远天如镜，又生怕误了你途程。见被你冷落了潇湘暮景，更打动我边塞离情，还说甚雁过留声。那堪更瑶阶夜永，嫌杀月儿明。（黄门云）陛下省烦恼，龙体为重。（驾云）不由我不烦恼也。（唱）
【十二月】休道是咱家动情，你宰相每也生憎。不比那雕梁燕语，不比那锦树莺鸣。汉昭君离乡背井，知他在何处愁听！
（雁叫科）（唱）
【尧民歌】呀呀的飞过蓼花汀，孤雁儿不离了凤凰城。画檐间铁马响丁丁，宝殿中御榻冷清清。寒也波更，萧萧落叶声，烛暗长门静。
【随煞】一声儿绕汉宫，一声儿寄渭城；暗添人白发成衰病，直恁的吾家可也劝不省。
（尚书上，云）今日早朝散后，有番国差使命绑送毛延寿来，说因毛延寿叛国败盟，致此祸衅。今昭君已死，情愿两国讲和。伏候圣旨。（驾云）既如此，便将毛延寿斩首祭献明妃。着光禄寺大排筵席，犒赏来使回去。（诗云）叶落深宫雁叫时，梦回孤枕夜相思。虽然青冢人何在，还为蛾眉斩画师。
题目沉黑江明妃青冢恨
正名破幽梦孤雁汉宫秋', '', '', '', NULL, '', 'indent', 1689021817, '64abfcacaebece3efca27286', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642666, '孟子 · 第九卷 · 万章上 · 第一节 ', NULL, 8, 271, 3, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '万章问曰：“舜往于田，号泣于旻天，何为其号泣也？”孟子曰：“怨慕也。”
万章曰：“父母爱之，喜而不忘；父母恶之，劳而不怨。然则舜怨乎？”
曰：“长息问于公明高曰：‘舜往于田，则吾既得闻命矣；号泣于旻天，于父母，则吾不知也。’公明高曰：‘是非尔所知也。’夫公明高以孝子之心，为不若是恝，我竭力耕田，共为子职而已矣，父母之不我爱，于我何哉？帝使其子九男二女，百官牛羊仓廪备，以事舜于畎亩之中。天下之士多就之者，帝将胥天下而迁之焉。为不顺于父母，如穷人无所归。天下之士悦之，人之所欲也，而不足以解忧；好色，人之所欲，妻帝之二女，而不足以解忧；富，人之所欲，富有天下，而不足以解忧；贵，人之所欲，贵为天子，而不足以解忧。人悦之、好色、富贵，无足以解忧者，惟顺于父母，可以解忧。人少，则慕父母；知好色，则慕少艾；有妻子，则慕妻子；仕则慕君，不得于君则热中。大孝终身慕父母。五十而慕者，予于大舜见之矣。”', '', '旻（mín）天：泛指天。
“父母爱之”四句：系引用曾子之语。《礼记·祭义》：“曾子曰：‘父母爱之，喜而弗忘；父母恶之，惧而无怨。’”忘，懈怠。劳，忧愁。
长息：公明高弟子。公明高：曾子弟子。
恝（jiá）：无忧无虑的样子。
共：通“恭”。
帝：指尧。九男：尧的九个儿子。二女：尧的两个女儿，即娥皇、女英。
畎（quǎn）亩：田地，田间。
胥：尽，全部。
少艾：年轻貌美；艾，美好。
热中：急躁。
', '万章问道：“舜到田里去，向着天号哭，他为什么边号哭？”
孟子说：“因为对父母既埋怨又依恋。”
万章说：“曾子说过：‘父母喜爱他，他既高兴又不敢懈怠。父母厌恶他，他尽管发愁却不埋怨。’可是舜竟然埋怨父母吗？”
孟子说：“长息曾经问公明高说：‘舜到田里去，这我懂得了。但他向着天号哭，哭诉父母的不是，这我就不懂了。’公明高说：‘这不是你所了解的。’在公明高看来，孝子之心是不能这样漫不经心的。我尽力耕田，恭敬地履行儿子的职责罢了。父母不爱我，我有什么办法？尧打发他的九个儿子、两个女儿，（带领）大小官吏，带着牛羊、粮食等等，到田地里服侍舜，天下的士人也多奔着他去，尧准备把整个天下都让给他。舜却因为不得父母的欢心，就像走投无路的人那样无所归属。天下的士人喜欢他，这是谁都盼望的，却不足以消除他的忧愁，漂亮的姑娘，这是谁都盼望的，娶了尧帝的两个女儿，却不足以消除他的忧愁。富有，这是谁都盼望的，富到拥有整个天下，却不足以消除他的忧愁；显贵，这是谁都盼望的，贵到身为天子，却不足以消除他的忧愁。别人喜欢他、漂亮的姑娘、财富和尊贵，都不足以消除忧愁，只有得父母的欢心才可以消除忧愁。人在小时候，就依恋父母；懂得喜欢女子的时候，就爱慕年轻漂亮的姑娘，有了妻室儿女，就爱护妻室儿女；做了官，就爱戴君主，不得君主的欢心就焦虑不安。具有大孝心的人是终身依恋父母的。到了五十岁还依恋父母的，我在伟大的舜身上见到了。”
', NULL, '', 'indent', 1558001646, '5cdcc76c43e78c00687f31e7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642667, '孟子 · 第九卷 · 万章上 · 第二节 ', NULL, 4, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '万章问曰：“诗云：‘娶妻如之何？必告父母。’信斯言也，宜莫如舜。舜之不告而娶，何也？”
孟子曰：“告则不得娶。男女居室，人之大伦也。如告，则废人之大伦，以怼父母，是以不告也。”
万章曰：“舜之不告而娶，则吾既得闻命矣；帝之妻舜而不告，何也？”
曰：“帝亦知告焉则不得妻也。”
万章曰：“父母使舜完廪，捐阶，瞽瞍焚廪。使浚井，出，从而揜之。象曰：‘谟盖都君咸我绩。牛羊父母，仓廪父母，干戈朕，琴朕，弤朕，二嫂使治朕栖。’象往入舜宫，舜在床琴。象曰：‘郁陶思君尔。’忸怩。舜曰：‘惟兹臣庶，汝其于予治。’不识舜不知象之将杀己与？”
曰：“奚而不知也？象忧亦忧，象喜亦喜。”
曰：“然则舜伪喜者与？”
曰：“否。昔者有馈生鱼于郑子产，子产使校人畜之池。校人烹之，反命曰：‘始舍之圉圉焉，少则洋洋焉，攸然而逝。’子产曰‘得其所哉！得其所哉！’校人出，曰：‘孰谓子产智？予既烹而食之，曰：得其所哉？得其所哉。’故君子可欺以其方，难罔以非其道。彼以爱兄之道来，故诚信而喜之，奚伪焉？”', '', '引诗见《诗经·齐风·南山》。
怼（duì）：怨恨。
捐阶：除掉梯子。
浚：加深。揜（yǎn）：同“掩”，掩盖。
象：舜的同父异母弟。
谟盖：谋害。谟，同“谋”。盖，同“害”。都君：指舜。
干戈：常用作兵器的通称。弤（dǐ）：舜弓之名。二嫂：指娥皇、女英。栖：床。
郁陶：想念的样子。
忸怩：惭愧的样子。
惟：想念。于：帮助。
校（xiào）人：管理沼池的小吏。
圉圉（yǔ）：鱼在水中瘦弱的样子。洋洋：舒缓摇尾的样子。
', '万章问道：“《诗经》上说：‘娶妻该怎么办？一定先禀告父母。’信从这话的，应该没有人比得上舜。但舜却是没有禀告父母就娶妻，这是怎么回事？”
孟子说：“舜如果先禀告父母就不能娶妻了。男女成婚，是人与人之间重要的伦常。如果禀告了父母，就将破坏这重要的伦常，就会怨恨父母，所以便不禀告了。”
万章说：“舜不禀告就娶妻的道理，我懂得了。帝尧把女儿嫁给舜，也不禀告舜的父母，又是怎么回事？”
孟子说：“帝尧也知道禀告了就不能把女儿嫁给舜。”
万章说：“父母打发舜修粮仓，等舜上了屋顶，就撤掉梯子，舜的父亲瞽瞍放火烧粮仓，他们打发舜淘井，不知道舜逃了出来，便往井里填土。象说：‘谋害舜都是我的功劳，牛羊归父母，仓糜归父母，干戈归我，琴归我，弤弓归我，两位嫂嫂要她们为我铺床叠被。’象到舜的屋里去，舜却坐在床边抚琴。象说：‘我好想你呀！’脸上带着惭愧之色。舜说：‘我想念这些臣下和百姓，你帮我治理吧。’
不知道舜知不知道象要杀害他？”
孟子说：“怎么不知道？只不过象忧愁，他也忧愁，象高兴，他也高兴。”
万章说：“那么，舜是假装高兴吗？”
孟子说：“不是。从前有人送活鱼给郑国的子产，子产打发管池塘的小吏把它养起来。小吏却煮了吃掉，回报说：‘刚放到池塘里，它蔫蔫的；过了一会儿，它便摆着尾巴游起来，很快就游得不知哪里去了。’子产说：‘找到它自己的地方了！找到它自己的地方了！’小吏出来说：‘谁说子产聪明？我已经把那条鱼煮了吃掉，他还说，找到它自己的地方了！找到它自己的地方了！’所以，君子是可以用合乎常情的方式来欺骗他，却不能用违背常理的办法欺罔他。象假装着敬爱兄长的方式来，所以舜就诚心实意地相信而为之喜悦，怎么是假装的呢？”
', NULL, '', 'indent', 1558001722, '5cdcc7b76e9ba10068e05045', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642668, '孟子 · 第九卷 · 万章上 · 第三节 ', NULL, 2, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '万章问曰：“象日以杀舜为事，立为天子，则放之，何也？”孟子曰：“封之也，或曰放焉。”
万章曰：“舜流共工于幽州，放驩兜于崇山，杀三苗于三危，殛鲧于羽山，四罪而天下咸服，诛不仁也。象至不仁，封之有庳。有庳之人奚罪焉？仁人固如是乎？在他人则诛之，在弟则封之。”
曰：“仁人之于弟也，不藏怒焉，不宿怨焉，亲爱之而已矣。亲之欲其贵也，爱之欲其富也。封之有庳，富贵之也。身为天子，弟为匹夫，可谓亲爱之乎？”
“敢问或曰放者，何谓也？”
曰：“象不得有为于其国，天子使吏治其国，而纳其贡税焉，故谓之放，岂得暴彼民哉？虽然，欲常常而见之，故源源而来。‘不及贡，以政接于有庳’，此之谓也。”', '', '共（gōng）工：人名，相传为尧的臣。
驩兜：人名。崇山：地名，在南方偏远之地。
杀：当为“窜”的假借字。三苗：国名。三危：山名，在西方偏远之地。
殛（jí）：诛杀。鲧：人名，传说为禹之父。羽山：山名，在东方偏远之地。
有庳（bì）：又作有鼻，国名。
', '万章问道：“象每天把杀掉舜当作一件大事，舜做了天子后却只是流放他，为什么？”
孟子说：“其实舜是封象为诸侯，有的人却说是流放。”
万章说：“舜把共工流放到幽州，把驩兜发配到崇山，把三苗之君驱逐到三危，在羽山杀掉了鲧，惩罚了这四个罪人而天下人都归服，这就是讨伐不仁了。象是极为不仁的，却封为有庳国的侯。有庳国的人难道有罪吗，仁人就是这样做事吗？一对别人，就讨伐他，对弟弟，就封赏他？”
孟子说：“仁人对于弟弟呀，不把愤怒藏在心里，不记仇，只是亲近他、爱护他罢了。亲近他，就要他显贵；爱护他，就要他富有。封为有庳国的侯，就是使他富贵。自己做天子，弟弟却是普通百姓，可以叫做亲近他、爱护他吗？”
万章说：“请问有的人说是流放，又是什么意思？”
孟子说：“象不能在他的国家有所作为，天子派官吏来治理他的国家，收缴贡税，所以有人说是流放。象难道能够残害他的百姓吗？尽管这样，舜还想常常能见到他，所以不断让他来，‘没到缴纳贡税的时候，就以政治上的原因接待有庳’。说的就是这件事。”
', NULL, '', 'indent', 1558001771, '5cdcc7e917b54d0068f3cb3f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642669, '孟子 · 第九卷 · 万章上 · 第四节 ', NULL, 10, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '咸丘蒙问曰：“语云：‘盛德之士，君不得而臣，父不得而子。’舜南面而立，尧帅诸侯北面而朝之，瞽瞍亦北面而朝之。舜见瞽瞍，其容有蹙。孔子曰：‘于斯时也，天下殆哉，岌岌乎！’不识此语诚然乎哉？”
孟子曰：“否。此非君子之言，齐东野人之语也。尧老而舜摄也。尧典曰：‘二十有八载，放勋乃徂落，百姓如丧考妣，三年，四海遏密八音。’孔子曰：‘天无二日，民无二王。’舜既为天子矣，又帅天下诸侯以为尧三年丧，是二天子矣。”
咸丘蒙曰：“舜之不臣尧，则吾既得闻命矣。诗云：‘普天之下，莫非王土；率土之滨，莫非王臣。’而舜既为天子矣，敢问瞽瞍之非臣，如何？”曰：“是诗也，非是之谓也；劳于王事，而不得养父母也。曰：‘此莫非王事，我独贤劳也。’故说诗者，不以文害辞，不以辞害志。以意逆志，是为得之。如以辞而已矣，云汉之诗曰：‘周余黎民，靡有孑遗。’信斯言也，是周无遗民也。孝子之至，莫大乎尊亲；尊亲之至，莫大乎以天下养。为天子父，尊之至也；以天下养，养之至也。诗曰：‘永言孝思，孝思维则。’此之谓也。书曰：‘只载见瞽瞍，夔夔齐栗，瞽瞍亦允若。’是为父不得而子也。”', '', '咸丘蒙：孟子弟子。
蹙（cù）：不安。
《尧典》曰：以下数句在今本《尚书·舜典》。今本《舜典》与《尧典》本是一篇。
二十有八载：指舜摄政后的二十八年。有，通“又”。放勋：尧。徂（cú）落：同“殂落”，死亡。考妣（bǐ）：父母。
遏：停止。密：无声。八音：指金、石、丝、竹、匏、土、革、木八种乐器。
“普天之下”四句，见《诗经·小雅·北山》。
贤劳：辛劳，劳苦；贤，劳。
逆：揣测。
《云汉》：《诗经·大雅·云汉》。
靡（mǐ）有：没有。孑（jié）遗：遗留。“周余”二句，是形容灾难深重，多有死亡。
孝思：孝心。维则：作为行动的准则。引诗见《诗经·大雅·下武》。
指《尚书·大禹谟》篇。
祗（zhī）：敬。载：事。夔夔（kuíkuí）斋栗：因谨慎而战栗的样子。允若：顺从。
', '咸丘蒙问道：“常言说：‘道德最高的人，君主不得以他为臣，父亲不得以他为子。’舜向南站立，尧带领诸侯向北朝觐他，瞽瞍也向北朝觐他。舜见到瞽瞍，面有不安之色。孔子说：‘在这个时候啊，天下岌岌可危啊！’不知道这话是真的吗？”
孟子说：“不是。这不是君子的话，是齐东野人的话。尧年老时，舜代他管理政务。《尧典》说：‘过了二十八年后，尧死了，老百姓好像死了父母，服丧三年间，四海之内停止了一切音乐。’孔子说：‘天上没有两个太阳，百姓没有两个君王。’如果舜在尧死前做了天子，又带领天下诸侯为尧服丧三年，这就是同时有两个君王了。”
咸丘蒙说：“舜不以尧为臣，我懂得您的教诲了。《诗经》说：‘整个天下，没有一块土地不是王的土地；从陆地到海滨，没有一个人不是王的臣民。’而舜既已经做了君王，瞽瞍却还不是他的臣民，请问这是怎么回事呢？”
孟子说：“这诗讲的不是这个意思，诗里说的是诗歌里的人物为王的公事而辛劳，却不能够奉养父母。他说：‘这些事没有一件不是王的公事，却只有我一人辛勤劳苦。’所以讲诗的人，不要凭个别文字歪曲了词句，不要凭个别词句歪曲了本意。用自己的体会揣度诗人的本意，这才对了。如果只是凭借词句，《云汉》诗里说：‘周朝剩余的老百姓，没有一个遗留在世。’假如相信这话，那么周朝是一个人都没有留下了。孝子的极至，没有比尊敬双亲更高的；尊敬双亲的极至，没有比用整个天下来奉养他们更高的。身为天子的父亲，是尊贵至极的，舜用天下来奉养，可说是奉养的极至。《诗经》上又说：‘永远保持孝心，孝心是天下的准则。’说的就是这个意思。《尚书》说：‘恭恭敬敬来见瞽瞍，态度谨慎而恐惧，瞽瞍也确实顺理而行了。’这难道是父亲不能以他为子吗？”
', NULL, '', 'indent', 1558001861, '5cdcc83717b54d0068f3cf13', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642670, '孟子 · 第九卷 · 万章上 · 第五节 ', NULL, 7, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '万章曰：“尧以天下与舜，有诸？”孟子曰：“否。天子不能以天下与人。”
“然则舜有天下也，孰与之？”曰：“天与之。”
“天与之者，谆谆然命之乎？”曰：“否。天不言，以行与事示之而已矣。”
曰：“以行与事示之者如之何？”曰：“天子能荐人于天，不能使天与之天下；诸侯能荐人于天子，不能使天子与之诸侯；大夫能荐人于诸侯，不能使诸侯与之大夫。昔者尧荐舜于天而天受之，暴之于民而民受之，故曰：天不言，以行与事示之而已矣。”
曰：“敢问荐之于天而天受之，暴之于民而民受之，如何？”
曰：“使之主祭而百神享之，是天受之；使之主事而事治，百姓安之，是民受之也。天与之，人与之，故曰：天子不能以天下与人。舜相尧二十有八载，非人之所能为也，天也。尧崩，三年之丧毕，舜避尧之子于南河之南。天下诸侯朝觐者，不之尧之子而之舜；讼狱者，不之尧之子而之舜；讴歌者，不讴歌尧之子而讴歌舜，故曰天也。夫然后之中国，践天子位焉。而居尧之宫，逼尧之子，是篡也，非天与也。太誓曰：‘天视自我民视，天听自我民听’，此之谓也。”', '', '谆谆然：诚挚地，教导不倦的样子。
暴（pù）：显示，公布。
行：指个人的行为。事：指政事。
南河：即黄河，因在尧时都城的南面，故称。
朝觐（cháojìn）:臣子晋见君主。
《太誓》：《尚书》篇名。
', '万章说：“尧把天下给了舜，有这事吗？”
孟子说：“没有。天子不能把天下给人。”
“那么舜享有天下，是谁给他的？”
孟子说：“天给他的。”
“天给他，是反复叮咛命令他的吗？”
孟子说：“不。天不说话，只通过行为和政事显示给他罢了。”
万章说：“通过行为和政事显示给他，是怎样的？”
孟子说：“天子能把人推荐给天，却不能让天给他天下；诸侯能把人推荐给天子，却不能让天子给他诸侯之位；大夫能把人推荐给诸侯，却不能让诸侯给他大夫之位。从前尧把舜推荐给天而天接受了他，把舜显示给老百姓而老百姓接受了他，所以说，天不说话，只通过行为和政事显示给他罢了。”
“请问把舜推荐给天而天接受了他，把舜展现给老百姓而老百姓接受了他，是怎样的？”
孟子说：“让他主持祭祀而百神享用，这是天接受了他，让他主持政事而政事有条不紊，老百姓满意他，这是老百姓接受了他。天下是天给他的，是老百姓给他的，所以说：天子不能把天下给人。舜辅佐尧二十八年，这不是他一个人所能决定的，是天意。尧死后，三年的服丧期限也结束时，舜避开尧的儿子，到南河的南边去。天下诸侯来朝见的，不到尧的儿子那里而到舜那里；打官司的，不到尧的儿子那里而到舜那里；歌颂的，不歌颂尧的儿子而歌颂舜，所以说是天意。这样他才回到中国，继承了天子的职位。如果是当初就住到尧的宫室里，逼迫尧的儿子，那是篡夺，不是天给他。《太誓》说：‘天的看法来自于用我们老百姓的眼睛，天的听闻来自于用我们老百姓的耳朵。’说的就是这个意思。”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b480d66a763596afec581", "shortContent": " 这一章记载了孟子与弟子讨论三代政权交接的合法依据问题的对话，这段对话很有意义，因为其中包含了一种带有民主色彩的政权观。传说尧把天下禅让给了舜。可是当万章就此事向孟子询问时，孟子却予以否定：“天子没有权力自作主张把天下让给别人！”这里其实包含了一个重要的观点，即天下并不是属于天子个人的东西。无论是尧舜的“禅让”还是禹启的“世袭”，都只是一种政权交接的表面形式，这种形式本身并不决定政权交接的合法性。...", "authors": ["徐克谦"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558001913, '5cdcc87743e78c00687f3f21', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642695, '孟子 · 第十一卷 · 告子上 · 第十一节 ', NULL, 16, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“仁，人心也；义，人路也。舍其路而弗由，放其心而不知求，哀哉！人有鸡犬放，则知求之；有放心，而不知求。学问之道无他，求其放心而已矣。”', '', '由：经过，通过。
放：放任。
', '孟子说：“仁指的是人心，义指的是人走的路。放弃那正道不走，放任他的本心而不知道去寻找，可悲啊！人们有鸡狗走丢了，便知道去找回来；本心有所放任，却不知道去寻找。学问之道没有别的，就是把那放任了的本心探求回来罢了。”
', NULL, '', 'indent', 1558089790, '5cde1fb9c8959c0068ef2a38', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642671, '孟子 · 第九卷 · 万章上 · 第六节 ', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '万章问曰：“人有言：‘至于禹而德衰，不传于贤而传于子。’有诸？”
孟子曰：“否，不然也。天与贤，则与贤；天与子，则与子。昔者舜荐禹于天，十有七年，舜崩。三年之丧毕，禹避舜之子于阳城。天下之民从之，若尧崩之后，不从尧之子而从舜也。禹荐益于天，七年，禹崩。三年之丧毕，益避禹之子于箕山之阴。朝觐讼狱者不之益而之启，曰：‘吾君之子也。’讴歌者不讴歌益而讴歌启，曰：‘吾君之子也。’丹朱之不肖，舜之子亦不肖。舜之相尧，禹之相舜也，历年多，施泽于民久。启贤，能敬承继禹之道。益之相禹也，历年少，施泽于民未久。舜、禹、益相去久远，其子之贤不肖，皆天也，非人之所能为也。莫之为而为者，天也；莫之致而至者，命也。匹夫而有天下者，德必若舜禹，而又有天子荐之者，故仲尼不有天下。继世以有天下，天之所废，必若桀纣者也，故益、伊尹、周公不有天下。伊尹相汤以王于天下。汤崩，太丁未立，外丙二年，仲壬四年。太甲颠覆汤之典刑，伊尹放之于桐。三年，太甲悔过，自怨自艾，于桐处仁迁义；三年，以听伊尹之训己也，复归于亳。周公之不有天下，犹益之于夏，伊尹之于殷也。孔子曰：‘唐虞禅，夏后、殷、周继，其义一也。’”', '', '阳城：山名，在今河南登封北。
益：秦赵始祖。禹老，联盟会议决定由益即位，后被禹之子启强夺了君位。
箕山：在今河南登封东南。阴：山北。
启：禹之子，夏代第一个王。
丹朱：尧之子。
舜、禹、益相去久远：指三者相距或久远或短暂。按，舜相尧二十八年，禹相舜十七年，这是久远者，益相禹只七年，是短暂者。
太丁：汤之太子，未立而死。外丙、仲壬：均为太丁之弟。
太甲：太丁之子。典刑：常法。桐：在今河南偃师西南。
艾（yì）：治理。
亳（bó）：在今河南商丘北。
唐虞：尧舜。禅（shàn）：以王位传人。
', '万章问道：“人们有这样的说法，‘到了禹的时候道德就衰落了，他不传位给贤人而传给自己的儿子’，有这事吗？”
孟子说：“不，不对的。天要授给贤人，就授给贤人；天要授给儿子，就授给儿子。从前，舜把禹推荐给天，十七年后，舜死了，三年服丧的期限结束后，禹避开舜的儿子到阳城去，可是天下的老百姓都跟从他，就像尧死后，老百姓不跟从尧的儿子而跟从舜一样。禹也把益推荐给天，七年后，禹死了。三年服丧的期限结束后，益为避开禹的儿子躲到箕山北面去。朝见和打官司的人不到益那里去，而到启那里去，说：‘这是我们君主的儿子。’歌颂的人不歌颂益而歌颂启，说：‘这是我们君主的儿子啊。’尧的儿子丹朱不好，舜的儿子也不好。舜辅佐尧、禹辅佐舜，都历时多年，对老百姓施与恩泽的时间长。启是贤明的，能恭敬地继承禹的作风。益辅佐禹，历时较短，对老百姓施与恩泽的时间不长。舜和禹、禹和益，相距的时间或长或短，他们的儿子或者贤明，或者不好，都是天意，不是人的意志所能主宰。没有人叫他们这样去做，而做成了，这是天意；没有人去争取，而得到了，这是命运。以一个平头百姓而享有天下，他的道德一定像舜和禹，而且又有天子推荐他，所以孔子没赶上天子推荐，便不能享有天下。因世袭而享有天下，而天又把他废弃的，一定是像桀、纣那样的人，所以益、伊尹、周公没赶上桀、纣那样的，也便不能享有天下。伊尹辅佐汤统一了天下，汤死后，太丁未立就死了，外丙在位两年，仲壬在位四年，大甲（继位后）破坏了汤的典章法度，伊尹就把他流放到桐邑，三年过后，太甲悔过，自己怨恨，自己改正，在桐邑就自处于仁，自迁于义，三年过后，因为听从伊尹对自己的教导而重新回到亳都做天子。周公不享有天下，就如益在夏、伊尹在殷的情况。孔子说：‘唐尧、虞舜实行禅让制，夏、商、周三代实行世袭制，道理是一样的。”
', NULL, '', 'indent', 1558001973, '5cdcc8b330863b00697e5b2e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642672, '孟子 · 第九卷 · 万章上 · 第七节 ', NULL, 6, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '万章问曰：“人有言‘伊尹以割烹要汤’有诸？”
孟子曰：“否，不然。伊尹耕于有莘之野，而乐尧舜之道焉。非其义也，非其道也，禄之以天下，弗顾也；系马千驷，弗视也。非其义也，非其道也，一介不以与人，一介不以取诸人，汤使人以币聘之，嚣嚣然曰：‘我何以汤之聘币为哉？我岂若处畎亩之中，由是以乐尧舜之道哉？’汤三使往聘之，既而幡然改曰：‘与我处畎亩之中，由是以乐尧舜之道，吾岂若使是君为尧舜之君哉？吾岂若使是民为尧舜之民哉？吾岂若于吾身亲见之哉？天之生此民也，使先知觉后知，使先觉觉后觉也。予，天民之先觉者也；予将以斯道觉斯民也。非予觉之，而谁也？’思天下之民匹夫匹妇有不被尧舜之泽者，若己推而内之沟中。其自任以天下之重如此，故就汤而说之以伐夏救民。吾未闻枉己而正人者也，况辱己以正天下者乎？圣人之行不同也，或远或近，或去或不去，归洁其身而已矣。吾闻其以尧舜之道要汤，未闻以割烹也。《伊训》曰：‘天诛造攻自牧宫，朕载自亳。’”', '', '割烹：切割、烹调，指当厨师。
有莘（xīn）：古国名，在今河南陈留。
介：即“芥”，草。比喻极轻微的东西。
币：帛，泛指礼物。嚣嚣（áoáo）：自得其乐的样子。
幡（fān）然：反过来；幡，通“翻”。
说（shuì）：游说。
《伊训》：《尚书》篇名，已佚。今本《尚书》中的《伊训》是伪古文。
造：开始。牧宫：桀的宫室。朕：伊尹自称。载：开始。
', '万章问道：“有人这样说，‘伊尹通过自己当厨师来向汤求职’，有这回事吗？”
孟子说：“不，不是这样的。伊尹在有莘国的郊野耕田，而喜爱尧舜的道理。（如果）不合乎义的，不合乎道的，即使拿天下当俸禄给他，他连头都不回一下；即使有四千匹马系在那里，他也不会看。不合乎义的，不合乎道的，一根草也不送给人，一根草也不取于别人。汤打发人用币帛聘任他，他自得地说：‘我拿汤的聘礼币帛干什么？这难道比得上我独处田野之中，由此来喜爱尧舜的道理吗？’汤多次打发人去聘任他，后来他翻然改变了态度，说：‘我与其独处田野之中，由此来喜爱尧舜的道理，我何不如使这个君主成为尧舜一样的君主呢？我何不如使这些老百姓成为尧舜时候的老百姓呢？我何不如自己亲眼看见呢？上天生育老百姓，就是要使先知者唤醒后知者，使先觉者唤醒后觉者。我，是天下百姓中的先觉者；我将用这道理来使这些百姓觉悟。如果不是我来使他们觉悟，那还有谁呢？’他想到天下的百姓、男男女女有不能获得尧舜恩泽的人，就像是自己把他们推到水沟里去一样。他就是这样自己承担天下的重担，所以找到汤，用讨伐夏桀、救助百姓的道理游说他。我没听说过自己不正而能使别人端正的，何况是屈辱自己来端正天下呢？圣人的行为是不一样的，有的疏远君主，有的接近君主；有的离开，有的不离开；归根结底都要使自己干干净净。我听说他用尧舜的道理来向汤求职，没听说通过自己当厨师来求职。《伊训》说：‘天的诛伐是从桀的牧宫里开始的，我从商都亳邑开始。’”
', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d25914587d02f5a002", "shortContent": "本文选自《韩非子·难一》，题目为编者所加，主要批判儒者所提倡的尊崇圣贤的人治德化思想，提倡法家的法治学说。\n文章一开头写舜在三年之内躬亲化民，先后去干耕种、打鱼、制陶之事，解决了田界纠纷，培养了谦让风气，改善了器物质量。接着引出孔子的赞叹，突出了舜的救败功绩与儒家的德化主张。\n在先秦时代，儒家为显学，上述观点与主张，在一般人心目中似乎是天经地义，无可置疑的。但儒家在无限美化圣君以宣扬德化思想时，却...", "authors": ["张葆全"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558002016, '5cdcc8de17b54d0068f3d738', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642673, '孟子 · 第九卷 · 万章上 · 第八节 ', NULL, 7, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '万章问曰：“或谓孔子于卫主痈疽，于齐主侍人瘠环，有诸乎？”
孟子曰：“否，不然也。好事者为之也。于卫主颜雠由。弥子之妻与子路之妻，兄弟也。弥子谓子路曰：‘孔子主我，卫卿可得也。’子路以告。孔子曰：‘有命。’孔子进以礼，退以义，得之不得曰‘有命’。而主痈疽与侍人瘠环，是无义无命也。孔子悦于鲁卫，遭宋桓司马将要而杀之，微服而过宋。是时孔子当阨，主司城贞子，为陈侯周臣。吾闻观近臣，以其所为主；观远臣，以其所主。若孔子主痈疽与侍人瘠环，何以为孔子？”
', '', '主痈疽（yōng jū）：以痈疽为主人，指住在痈疽家里。痈疽：人名，卫灵公所宠幸的宦官。侍人：即“寺人”，宦官。瘠环：人名。
颜雠由：卫国贤大夫。
弥子：卫灵公幸臣弥子瑕。兄弟：姊妹，古亦称姊妹为女兄女弟。
桓司马：宋国司马桓魋（tuí）。要（yāo）：拦截。微服，指更换平常的服装。
厄：困厄。司城贞子：陈国人。陈侯周：陈怀公之子，名周，后为楚灭，无谥。
', '万章问道：“有人说，孔子在卫国住在痈疽家里，在齐国住在宦官瘠环家里，有这回事吗？”
孟子说：“不，不是这样的。这是好事之徒编出来的。他在卫国住在颜雠由家里。弥子瑕的妻子和子路的妻子是姊妹。弥子瑕对子路说：‘如果孔子住到我家里，卫国的卿相之位便可得到。’子路把这话告诉孔子。孔子说：‘得不得卿相之位是由天命决定的。’孔子依礼而进，依义而退，得到或得不到都说‘由天命决定’。如果住在痈疽和宦官瘠环的家里，都是无视道义、无视天命的。孔子在鲁国、卫国不得意，又碰到宋国的司马桓魋将拦截他要杀掉他，孔子换了服装，悄悄走过宋国。这时孔子正处在困难的境地，住在司城贞子家里，做陈侯周的臣。我听说观察在朝的臣子，看他所招待的客人；观察远来的臣子，看他所寄居的主人。如果孔子以痈疽和宦官瘠环为主人，怎么能成为孔子？”
', NULL, '', 'indent', 1558002061, '5cdcc90b17b54d0068f3daa1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642674, '孟子 · 第九卷 · 万章上 · 第九节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '万章问曰：“或曰：‘百里奚自鬻于秦养牲者，五羊之皮，食牛，以要秦穆公。’信乎？”
孟子曰：“否，不然。好事者为之也。百里奚，虞人也。晋人以垂棘之璧与屈产之乘，假道于虞以伐虢。宫之奇谏，百里奚不谏。知虞公之不可谏而去，之秦，年已七十矣，曾不知以食牛干秦穆公之为污也，可谓智乎？不可谏而不谏，可谓不智乎？知虞公之将亡而先去之，不可谓不智也。时举于秦，知穆公之可与有行也而相之，可谓不智乎？相秦而显其君于天下，可传于后世，不贤而能之乎？自鬻以成其君，乡党自好者不为，而谓贤者为之乎？”', '', '百里奚：一说姓百，名里，字奚，原为虞国人，虞亡后作秦国的大夫。鬻（yù）：卖。
食：同“饲”。要：接近。
虞：国名，在今山西平陆东北。
垂棘（chuí jí）：晋国地名，产美玉。屈：晋国地名，产良马。乘：四匹马。虢（guó）：国名，在今山西平陆县北，公元前655年为晋所灭。
宫之奇：虞国贤臣。
曾：乃，竟。污：肮脏之事。
', '万章问道：“有人说：‘百里奚用五张羊皮的价钱和为人喂牛的条件，把自己卖给秦国养牲畜的人，（以此寻求机会）向秦穆公求职。’可信吗？”
孟子说：“不，不是这样。这是好事者编出来的。百里奚，是虞国人。晋国人用垂棘的玉璧和屈地所产的四匹马为代价，向虞国借路，要去攻打虢国。宫之奇向虞国的国君谏阻，百里奚不谏阻。他知道虞国国君不会接受谏议，因而离开虞国，到秦国去，那时他已经七十岁了，竟不懂得通过为人喂牛来向秦穆公求职是污浊的，可以叫明智吗？但他却是知道不可提出谏议就不谏议，这可以叫不明智吗？知道虞国将要灭亡而提前离开虞国，也不能叫不明智。当时他在秦国被提拔，就知道秦穆公有所作为，因而辅佐他，这可以叫不明智吗？辅佐秦国而使其君主名扬天下，足以流传于后世，不贤的人能办到吗？卖掉自己来成就他的君主，乡里洁身自好的人都不干，竟说贤者肯干吗？”
', NULL, '', 'indent', 1558002120, '5cdcc94443e78c00687f4a34', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642675, '孟子 · 第十卷 · 万章下 · 第一节 ', NULL, 6, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“伯夷，目不视恶色，耳不听恶声。非其君不事，非其民不使。治则进，乱则退。横政之所出，横民之所止，不忍居也。思与乡人处，如以朝衣朝冠坐于涂炭也。当纣之时，居北海之滨，以待天下之清也。故闻伯夷之风者，顽夫廉，懦夫有立志。
伊尹曰：‘何事非君？何使非民？’治亦进，乱亦进。曰：‘天之生斯民也，使先知觉后知，使先觉觉后觉。予，天民之先觉者也；予将以此道觉此民也。’思天下之民匹夫匹妇有不与被尧舜之泽者，若己推而内之沟中，其自任以天下之重也。
柳下惠，不羞污君，不辞小官。进不隐贤，必以其道。遗佚而不怨，阨穷而不悯。与乡人处，由由然不忍去也。‘尔为尔，我为我，虽袒裼裸裎于我侧，尔焉能浼我哉？’故闻柳下惠之风者，鄙夫宽，薄夫敦。
孔子之去齐，接淅而行；去鲁，曰：‘迟迟吾行也。’去父母国之道也。可以速而速，可以久而久，可以处而处，可以仕而仕，孔子也。”
孟子曰：“伯夷，圣之清者也；伊尹，圣之任者也；柳下惠，圣之和者也；孔子，圣之时者也。孔子之谓集大成。集大成也者，金声而玉振之也。金声也者，始条理也；玉振之也者，终条理也。始条理者，智之事也；终条理者，圣之事也。智，譬则巧也；圣，譬则力也。由射于百步之外也，其至，尔力也；其中，非尔力也。”', '', '横（hèng）政：暴政。横（hèng）民：暴民。
顽：贪。懦：柔弱。
由由然：怡然自得的样子。
袒裼裸裎：指赤身裸体。浼：污染，弄脏。
接淅：把正在淘洗的大米滤干，比喻行色匆忙；淅，淘洗大米。
而：用法同“则”。
金声：指音乐开始演奏时，由金属乐器钟、镈等最先发出的声音。玉振：指演奏即将结束时由玉盘最后发出的声音。
由：同“犹”。
', '孟子说：“伯夷，眼睛不看不好的颜色，耳朵不听不好的声音。他认为不理想的君主，不去服侍，他认为不理想的百姓，不去使唤。国家太平就进取，天下动乱就引退。暴政出现的地方，暴民停留的地方，他都不愿意去住。他以为同乡下人相处，就像穿着上朝的礼服，戴着上朝的礼帽坐在泥土和炭灰上。在商纣的时候，他住在北海的海滨，来等待天下清平。所以听说过伯夷的风节的人，贪婪者也会变得廉洁，懦弱者也会有自立的意志。
“伊尹说：‘服侍谁不是服侍君主，使唤谁不是使唤百姓？’天下太平他也进取，天下动乱他也进取。说：‘天生育这些百姓，就要让先知者唤醒后知者，让先觉者唤醒后觉者。我，是天下人中的先觉者，我将用真理来唤醒老百姓。他想到天下的百姓、男男女女有不能获得尧、舜的恩泽的人，就像是自己把他们推到水沟里去一样——他就是这样地自己承担天下的重担。
“柳下惠，不为侍奉污浊的君主而感到羞耻，不辞去小官。做官时，不隐藏自己的贤能，一定照原则办事。被遗弃时不抱怨，困穷时不发愁。与乡下人相处，高高兴兴地不忍离去。照他的话说，‘你是你，我是我，就算你赤身裸体在我身边，又怎么能污染我呢？’所以听说过柳下惠的风节的人，鄙陋者变得宽宏大量，刻薄者变得温柔敦厚。
“孔子离开齐国时，拿着正在淘洗的大米，等不及做饭就走。离开鲁国，却说：‘我们慢慢走吧。’这是离开祖国的态度。可以快走就快走，可以久留就久留，可以不做官就不做官，可以做官就做官，这就是孔子。”
孟子说：“伯夷，是圣贤中清高的人；伊尹，是圣贤中负责任的人；柳下惠，是圣贤中随和的人；孔子，是圣贤中识时务的人。孔子，可说是集大成的人。集大成，就像奏乐时先以击打钟镈开场，再以敲击玉盘收尾一样，完完整整。击打钟镈，是条理的开始；敲击玉盘，是条理的终结。条理的开始，是运用智慧的事业；条理的终结，是完成圣德的事业。智慧，好比技巧；圣德，好比力量。就像在百步之外射箭，箭射到靶子，是你的力量在起作用；箭射中靶子，就不是你的力量能起作用了。”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b4830b6a81d0c538cfff9", "shortContent": "穷则独善其身，达则兼善天下，这是儒家在仕途进退问题上的基本态度。至于什么时候可以做官，什么时候不可以做官，古代圣人的做法并不一样。但基本原则还是有的，那就是不能为了做官而不择手段，投机钻营；不能为了做官而丧失原则，丧失尊严；做了官就要尽到做官的责任，就要认真努力为民众为国家办事。\n\n伯夷、伊尹、柳下惠、孔子，四位都是仁者，但他们对待做官的态度，却各不相同。\n\n伯夷看不得一点不良的现象，听不得一点不...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558002181, '5cdcc982c8959c0068dd5f95', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642677, '孟子 · 第十卷 · 万章下 · 第三节 ', NULL, 7, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '万章问曰：“敢问友。”

孟子曰：“不挟长，不挟贵，不挟兄弟而友。友也者，友其德也，不可以有挟也。孟献子，百乘之家也，有友五人焉：乐正裘、牧仲，其三人，则予忘之矣。献子之与此五人者友也，无献子之家者也。此五人者，亦有献子之家，则不与之友矣。非惟百乘之家为然也。虽小国之君亦有之。费惠公曰：‘吾于子思，则师之矣；吾于颜般，则友之矣；王顺、长息则事我者也。’非惟小国之君为然也，虽大国之君亦有之。晋平公之于亥唐也，入云则入，坐云则坐，食云则食。虽疏食菜羹，未尝不饱，盖不敢不饱也。然终于此而已矣。弗与共天位也，弗与治天职也，弗与食天禄也，士之尊贤者也，非王公之尊贤也。舜尚见帝，帝馆甥于贰室，亦飨舜，迭为宾主，是天子而友匹夫也。用下敬上，谓之贵贵；用上敬下，谓之尊贤。贵贵、尊贤，其义一也。”', '', '挟：倚仗，持以自重。
孟献子：春秋时期鲁国大夫仲孙蔑。
费（bì）惠公：春秋时期费国的君主。
晋平公：春秋时期晋国的君主。亥唐：晋平公时隐居于市的贤士。
入云、坐云、食云：云入、云坐、云食的倒文。
疏食：粗糙的食物。
馆：馆舍，指止宿。甥：女婿。贰室：副宫。
', '万章问道：“请问怎样交朋友？”
孟子说：“不倚仗自己的年长，不倚仗自己的显贵，也不倚仗兄弟的势力来交朋友。所谓友，是以对方的品德为友，不可有所倚仗。孟献子，是拥有百辆车马的大夫，他有五个朋友：乐正裘、牧仲，其他三人我忘了。献子和这五人交朋友，心中没有献子是大夫的想法。这五人，也是这样，如果心存献子是大夫的念头，就不同他交朋友了。不仅拥有百辆车马的大夫是这样，即使是小国的君主也有这种人。费惠公说：‘我对于子思，是把他当老师；我对于颜般，是把他当朋友。王顺、长息，是服侍我的。’不仅小国的君主是这样，即使大国的君主也有这种人。晋平公对于亥唐，亥唐叫他进去，他才进去；叫他坐，他才坐；叫他吃饭，他才吃饭。即使是粗糙的米饭、菜羹，也不曾不吃饱，因为不敢不吃饱。但也仅此而已，并不和他共有君主之位，不和他一起处理政务，也不和他分享俸禄。这只是士人的尊贤，而不是王公的尊贤。舜拜见帝尧，帝尧请他这位女婿住在他的副宫里，也请舜吃饭，两人轮着做东，这才是天子结交普通老百姓为友的态度。以地位卑微者尊敬地位显贵者，这叫尊重贵人；以地位显贵者尊敬地位卑微者，这叫尊重贤人。尊重贵人和尊重贤人，道理是一样的。”
', NULL, '', 'indent', 1558002275, '5cdcc9e117b54d0068f3e7a9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642678, '孟子 · 第十卷 · 万章下 · 第四节 ', NULL, 4, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '万章问曰：“敢问交际何心也？”孟子曰：“恭也。”
曰：“却之却之为不恭，何哉？”曰：“尊者赐之，曰‘其所取之者，义乎，不义乎”，而后受之，以是为不恭，故弗却也。”
曰：“请无以辞却之，以心却之，曰‘其取诸民之不义也’，而以他辞无受，不可乎？”曰：“其交也以道，其接也以礼，斯孔子受之矣。”
万章曰：“今有御人于国门之外者，其交也以道，其馈也以礼，斯可受御与？”曰：“不可。康诰曰：‘杀越人于货，闵不畏死，凡民罔不譈。’是不待教而诛者也。殷受夏，周受殷，所不辞也。于今为烈，如之何其受之？”
曰：“今之诸侯取之于民也，犹御也。苟善其礼际矣，斯君子受之，敢问何说也？”曰：“子以为有王者作，将比今之诸侯而诛之乎？其教之不改而后诛之乎？夫谓非其有而取之者盗也，充类至义之尽也。孔子之仕于鲁也，鲁人猎较，孔子亦猎较。猎较犹可，而况受其赐乎？”
曰：“然则孔子之仕也，非事道与？”曰：“事道也。”
“事道奚猎较也？”曰：“孔子先簿正祭器，不以四方之食供簿正。”曰：“奚不去也？”
曰：“为之兆也。兆足以行矣，而不行，而后去，是以未尝有所终三年淹也。孔子有见行可之仕，有际可之仕，有公养之仕也。于季桓子，见行可之仕也；于卫灵公，际可之仕也；于卫孝公，公养之仕也。”', '', '交际：指以礼物、币帛相交往。
却：推辞不受。
御：阻止。这里指拦路抢劫。
《康诰》：《尚书》篇名。
越：抢劫。闵：通“暋”，强横。譈（duì）：同“憝”，怨恨。
比：同。
充类：类推。
鲁人：指鲁国士大夫。猎较：大夫率士众打猎，猎时以所获猎物各归猎者所有，作为祭祀祖先的祭品。较：争夺。
簿正：在簿书上规定。
兆：开始。
淹：停留。
行可：可行其道。际：接。指对自己的礼节待遇等。公养：指对一般贤者的礼节待遇等。
季桓子：季孙氏，名斯，春秋时期鲁国的大夫。
卫灵公：名元，春秋时卫国大夫。卫孝公：史无记述。
', '万章问道：“请问交际应该怎样用心呢？”
孟子说：“恭敬。”
万章说：“常言道：‘一再拒绝人家的礼物是不恭敬的。’为什么？”
孟子说：“尊贵的人有所赏赐，自己先考虑，‘对方得到这礼物的办法，是合乎义，还是不合乎义’，考虑妥当了，才接受，这样做是不恭敬的，所以说不该拒绝。”
万章说：“不要直说拒绝，而是心里拒绝，心里说‘对方从老百姓那里得到这东西的办法，是不义的’，而用别的借口推辞，不可以吗？”
孟子说：“对方按规矩结交我，按礼节接待我，这样的活，连孔子也都是会接受的。”
万章说：“如今有个在城门外拦路抢劫的人，他按规矩结交我，按礼节馈赠我，这样可以接受他抢劫来的东西吗？”
孟子说：“不可以。《康诰》说：‘杀人而抢夺人家的财物，强横而不怕死，这种人，是没有人不怨恨的。’这是不必先教育就可以杀掉的人。殷接受了夏这条法律，周接受了殷这条法律，没有改动过。现在抢劫比以往还厉害，怎么能接受呢？”
万章说：“现在的诸侯对百姓巧取豪夺，和拦路抢劫一样。如果搞好接待的礼节，君子就可以接受他的礼物，请问这有什么说头？”
孟子说：“你认为今天假如有圣王兴起，将把当今的诸侯通通杀掉呢？还是教而不改再杀呢？不是自己所有，却把它弄到手——把这种行为叫做强盗，这只是类推到义理的极端。孔子在鲁国做官，鲁国士大夫在打猎时争夺猎物，孔子也在打猎时争夺猎物。打猎时争夺猎物都可以，何况接受赏赐呢？”
万章说：“那么，孔子做官，不是为了发扬道吗？”
孟子说：“是为了发扬道。”
“为了发扬道，为什么还在打猎时争夺猎物？”
孟子说：“孔子先在簿书上规定可用的祭器，又规定不得用别处打来的猎物供在簿书上所定的祭器内。”
万章说：“孔子为什么不离开鲁国呢？”
孟子说：“孔子是先试一下。试过了证明可行，而竟不得推行，这才离开，所以孔子不曾在一个地方待满三年。孔子有时是因可行其道而做官，有时因君主对自己的礼遇不错而做官，有时因君主养贤而做官。对季桓子，是因可行其道而做官；对卫灵公，是因君主对自己的礼遇不错而做官；对卫孝公，是因君主养贤而做官。”
', NULL, '', 'indent', 1558002364, '5cdcca3830863b00697e6fe9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642679, '孟子 · 第十卷 · 万章下 · 第五节 ', NULL, 5, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“仕非为贫也，而有时乎为贫；娶妻非为养也，而有时乎为养。为贫者，辞尊居卑，辞富居贫。辞尊居卑，辞富居贫，恶乎宜乎？抱关击柝。孔子尝为委吏矣，曰‘会计当而已矣’。尝为乘田矣，曰‘牛羊茁壮，长而已矣’。位卑而言高，罪也；立乎人之本朝，而道不行，耻也。”
', '', '养：赡养、侍奉父母。
抱关击柝（tuò）：守门打更。
委吏：负责保管仓库、会计事务的小官。
乘（shèng）田：管理牧场的小吏。
', '孟子说：“做官不是因为贫困，但有时也是因为贫困。娶妻不是为了奉养父母，但有时也是为了奉养父母。为贫困而做官的，（便应该）辞掉高官（安心）做小官，拒绝厚禄只领薄俸。辞掉高官做小官，拒绝厚禄只领薄俸，做什么合适呢？守门打更都行。孔子曾做过管仓库的小官，说：‘财物的出纳没差错就行了。’也曾做过管理牧场的小吏，说：‘牛羊都长得茁壮就行了。’地位低下而议论大事，那是罪过。在朝廷上做官而道得不到发扬，那是耻辱。”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b4852a5f1e74f95e97f6e", "shortContent": " 孟子认为士人做官，本来目的并不在于养家糊口，但有时也的确是因为穷才出来做官的。这话说得很通达，很实际。但是孟子又指出，如果只是为了养家糊口而做官，那就不要去做大官，找个责任不太大，薪水不太高的官职就行了。什么样的职位呢？哪怕守关打更的职务都行。孔子早年就曾担任过管理仓库的小官吏，还担任过看管牛羊的小官吏，并且干得很不错。孟子为什么说这样的话？或许是希望士人看到，官职的大小不只意味着薪水的高低，更...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558002402, '5cdcca6043e78c00687f58c8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642680, '孟子 · 第十卷 · 万章下 · 第六节 ', NULL, 2, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '万章曰：“士之不托诸侯，何也？”孟子曰：“不敢也。诸侯失国，而后托于诸侯，礼也；士之托于诸侯，非礼也。”
万章曰：“君馈之粟，则受之乎？”曰：“受之。”
“受之何义也？”曰：“君之于氓也，固周之。”
曰：“周之则受，赐之则不受，何也？”曰：“不敢也。”
曰：“敢问其不敢何也？”曰：“抱关击柝者，皆有常职以食于上。无常职而赐于上者，以为不恭也。”
曰：“君馈之，则受之，不识可常继乎？”曰：“缪公之于子思也，亟问，亟馈鼎肉。子思不悦。于卒也，摽使者出诸大门之外，北面稽首再拜而不受。曰：‘今而后知君之犬马畜伋。’盖自是台无馈也。悦贤不能举，又不能养也，可谓悦贤乎？”
曰：“敢问国君欲养君子，如何斯可谓养矣？”曰：“以君命将之，再拜稽首而受。其后廪人继粟，庖人继肉，不以君命将之。子思以为鼎肉，使己仆仆尔亟拜也，非养君子之道也。尧之于舜也，使其子九男事之，二女女焉，百官牛羊仓廪备，以养舜于畎亩之中，后举而加诸上位。故曰：“王公之尊贤者也。”', '', '托：依靠。
氓：迁移来的人，此指士。周：同“赒”，救济。
缪公：指鲁缪公。亟：屡次。鼎肉：熟肉。
摽（biāo）：赶走。稽（qǐ）首：磕头。再拜：拜两次。“稽首再拜”，有拒绝之意。“再拜稽首”，有接受之意。
伋：子思之名。
台：通“始”，才。
将：送。
廪人：管仓库的小吏。庖人：掌管伙食的小吏。
仆仆尔：烦扰的样子。
加：犹言提拔。
', '万章说：“士不依靠诸侯为生，这是为什么呢？”
孟子说：“因为不敢。诸侯丧失了自己的国家，然后流亡国外，依靠别的诸侯为生，这是礼。士依靠诸侯为生，是不合于礼的。”
万章说：“君主所赠的粮食，就接受吗？”
孟子说：“接受。”
“接受有什么道理？”
孟子说：“君主对于侨居本国的人，本来就应该周济。”
万章说：“周济他，就接受，赏赐他，就不接受，这是什么道理呢？”
孟子说：“因为不敢。”
万章说：“请问为什么不敢？”
孟子说：“守门打更的人都有固定的职务，来接受上面的（禄米）给养。没有固定的职务而接受上面的赏赐，人们以为这是不恭敬的。”
万章说：“君主馈赠，就接受，不知道可以经常这样吗？”
孟子说：“鲁缪公对于子思，屡次问候，屡次馈赠肉食。子思不高兴。最后一次，他把使者赶出大门外，向北先磕头，又拜了两次，拒绝说：‘今天才知道君主是像养狗养马一样地对待我。’大概从此以后不再馈赠了。喜爱贤人却不能任用他，又不能养他，可以叫做喜爱贤人吗？”
万章说：“请问国君要养君子的话，怎样才可以叫做养呢？”
孟子说：“先给他传达君主的旨意，他就先拜两次，又磕头，接受下来。以后管仓库的人常送来粮食，管伙食的人常送来肉食，就不再传达是君主的旨意了。子思认为为了一点肉食使自己不胜其烦地一拜再拜，不是养君子的方式。尧对于舜，打发自己的九个儿子服侍他，两个女儿嫁给她，百官、牛羊、仓库都具备，把舜养在田野之中，以后又提拔他到最高的职位，所以说，这才是王公尊敬贤者的方式。
', NULL, '', 'indent', 1558002625, '5cdccb3bc8959c0068dd757d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642681, '孟子 · 第十卷 · 万章下 · 第七节 ', NULL, 2, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '万章曰：“敢问不见诸侯，何义也？”孟子曰：“在国曰市井之臣，在野曰草莽之臣，皆谓庶人。庶人不传质为臣，不敢见于诸侯，礼也。”
万章曰：“庶人，召之役，则往役；君欲见之，召之，则不往见之，何也？”曰：“往役，义也；往见，不义也。且君之欲见之也，何为也哉？”
曰：“为其多闻也，为其贤也。”曰：“为其多闻也，则天子不召师，而况诸侯乎？为其贤也，则吾未闻欲见贤而召之也。缪公亟见于子思，曰：‘古千乘之国以友士，何如？’子思不悦，曰：‘古之人有言：曰事之云乎，岂曰友之云乎？’子思之不悦也，岂不曰：‘以位，则子，君也；我，臣也。何敢与君友也？以德，则子事我者也。奚可以与我友？’千乘之君求与之友，而不可得也，而况可召与？齐景公田，招虞人以旌，不至，将杀之。志士不忘在沟壑，勇士不忘丧其元。孔子奚取焉？取非其招不往也。”
曰：“敢问招虞人何以？”曰：“以皮冠。庶人以旃，士以旗，大夫以旌。以大夫之招招虞人，虞人死不敢往。以士之招招庶人，庶人岂敢往哉。况乎以不贤人之招招贤人乎？欲见贤人而不以其道，犹欲其入而闭之门也。夫义，路也；礼，门也。惟君子能由是路，出入是门也。诗云：‘周道如底，其直如矢；君子所履，小人所视。’”
万章曰：“孔子，君命召，不俟驾而行。然则孔子非与？”曰：“孔子当仕有官职，而以其官召之也。”', '', '传质：送见面礼；质，通“贽”，见面礼。
役：服役。
齐景公田：参见《滕文公下》第一章。虞人：管理猎场的人。旌：用旄牛尾和彩色鸟羽做杆饰的旗。
皮冠：古时田猎时戴的冠，国君田猎时，以皮冠为符信招虞人。
]旃（zhān）：赤色曲柄的旗。旗（qí）：上画龙形，杆头系铃的旗。
指《诗经·小雅·大东》篇。
底：同“砥”，磨刀石。
视：注视，指看在眼里。
不俟驾：不等车马驾好。
', '万章说：“请问士人不主动谒见诸侯，是什么道理呢？”
孟子说：“住在城市里的，叫做市井之臣，住在田野里的，叫做草莽之臣，都叫老百姓。老百姓，如果不是送了见面礼做了属臣，就不敢去谒见诸侯，这是礼制。”
万章说：“老百姓，召唤他服役，就去服役；君主要见他，召唤他，却不去谒见，这是为什么呢？”
孟子说：“去服役，是义；去谒见，是不义。而且君主要见他，是为什么呢？”
万章说：“因为他的见多识广，因为他的贤能。”
孟子说：“如果是因为他的见多识广，那么，天子是不能召唤老师的，何况是诸侯呢？如果是因为他的贤能，那么，我没听说过要见贤人却随便召唤他。鲁缪公屡次去见子思，说：‘古代拥有千辆兵车的国君与士人交友，是怎样的？’子思不高兴，说：‘古人的话，说的是君主以士人为师，哪里是说和他交友？’子思的不高兴，难道不是这个意思：‘论地位，那么，你是君主，我是臣属，怎么敢和君主交朋友？论道德，那么，你是向我学习的人，怎么可以和我交朋友？’拥有千辆兵车的国君请求和他交朋友都不能够，何况是召唤呢？齐景公田猎，用旌旗召唤管猎场的小吏，他不来，准备杀他。有志之士不怕弃尸沟壑，勇敢的人不怕丢掉脑袋。孔子赞同他什么？就是赞同这一点，违背礼的召唤，他不去。
万章说：“请问召唤管猎场的小吏应该用什么呢？”
孟子说：“用皮帽子，召唤老百姓用旃，召唤士人用旗，召唤大夫用旌。用召唤大夫的旗帜来召唤猎场管理员，猎场管理员死也不敢去，用召唤士人的礼节来召唤老百姓，老百姓难道敢去吗？何况用召唤不贤之人的礼节来召唤贤人呢？要见贤人而不走恰当的路，就好比要人家进来却关着门。义，就是路；礼，就是门。只有君子能走这条路，出入这个门。《诗经》说：‘大路子得像磨刀石，直得像箭，这是君子所行走的，是平民所关注的。’”
万章说：“孔子，只要国君有召唤，不等车马准备好就步行出发；那么，孔子错了吗？”
孟子说：“那时孔子正在做官，有官职，国君用召唤官员的礼节召唤他。”
', NULL, '', 'indent', 1558002693, '5cdccb8030863b00697e808d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642682, '孟子 · 第十卷 · 万章下 · 第八节 ', NULL, 8, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子谓万章曰：“一乡之善士，斯友一乡之善士；一国之善士，斯友一国之善士；天下之善士，斯友天下之善士。以友天下之善士为未足，又尚论古之人。颂其诗，读其书，不知其人，可乎？是以论其世也。是尚友也。”', '', '尚：上。
颂：通“诵”，诵读。
', '孟子对万章说：“一个乡村里的优秀人物就同这一乡村的优秀人物交朋友，一个国家里的优秀人物就同这个国家的优秀人物交朋友，天下的优秀人物就同天下的优秀人物交朋友。和天下的优秀人物交朋友还不满足，便又追论古人。吟诵他们的诗，研读他们的著作，不了解他们的为人，可以吗？所以要研究他们所处的时代，这就是上溯历史，与古人交朋友。”
', NULL, '', 'indent', 1558002723, '5cdccba143e78c00687f6896', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642683, '孟子 · 第十卷 · 万章下 · 第九节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '齐宣王问卿。孟子曰：“王何卿之问也？”
王曰：“卿不同乎？”曰：“不同。有贵戚之卿，有异姓之卿。”
王曰：“请问贵戚之卿。”曰：“君有大过则谏，反覆之而不听，则易位。”王勃然变乎色。
曰：“王勿异也。王问臣，臣不敢不以正对。”王色定，然后请问异姓之卿。
曰：“君有过则谏，反覆之而不听，则去。”
', '', '问卿：问公卿之事。
贵戚：指君主的亲族。
异：奇怪。
正：诚，老实话。
', '齐宣王问有关公卿的事。孟子说：“大王问的是哪一种公卿呢？”
王说：“公卿还有所不同吗？”
孟子说：“不同的。有和王室同宗族的公卿，也有和王室不同姓氏的公卿。”
王说：“我请问和王室同宗族的公卿。”
孟子说：“君王如果有重大错误，他就上谏，反复上谏还不听从，就废弃他的王位改立别人。”
王突然变了脸色。
孟子说：“大王不要诧异。大王问我，我不敢不用正义来回答。”
王的脸色恢复平静以后，又问和王室不同姓氏的公卿。
孟子说：“君王如果有错误，他就上谏，反复上谏还不听从，他们就辞职而去。”
', NULL, '', 'indent', 1558002763, '5cdccbc97b968a0073d18162', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642684, '孟子 · 第十一卷 · 告子上 · 第一节 ', NULL, 4, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '告子曰：“性，犹杞柳也；义，犹杯棬也。以人性为仁义，犹以杞柳为杯桊。”
孟子曰：“子能顺杞柳之性而以为杯棬乎？将戕贼杞柳而后以为杯棬也？如将戕贼杞柳而以为杯棬，则亦将戕贼人以为仁义与？率天下之人而祸仁义者，必子之言夫！”', '', '告子：墨子门徒，年龄长于孟子。
杞（qǐ）柳：杨柳科植物，落叶丛生灌木，枝条柔软，可用来编器物。
杯（bēi）棬（quān）：器物名。杯，同“杯”。棬，用树条编成的饮器。
戕（qiāng）贼：残害。
', '告子说：“人的本性就像杞柳树，仁义就像杯盘；把人性纳入仁义当中，就像用杞柳树来制作杯盘一样。”
孟子说：“你能够顺应杞柳树的本性来制作杯盘吗？还是残害它的本性，然后才制成杯盘呢？如果要通过残害杞柳树本性的方式来制作杯盘，那么也要残害人的本性才能使人具有仁义吗？率领天下人来损害仁义的，一定是你的这种论调吧！”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b487566a763596afec812", "shortContent": " 性善论是孟子学说的重要内容，也是他的其他思想主张的理论基础。关于人性，在战国中、后期有几种不同的看法，除了性善论以外，还有四种观点：一、人性无所谓善，无所谓不善；二、人性既可以为善，也可以为不善；三、人性有善也有不善；四、性恶论。在孟子时代告子提出的人性无所谓善、无所谓不善的观点影响最大，孟子同他展开了四个回合的辩论。\n\n在第一个回合中孟子首先指出告子人性论的危害。告子把人性比作杞柳，把仁义道德...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558002810, '5cdccbf830863b00697e8718', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642685, '孟子 · 第十一卷 · 告子上 · 第二节 ', NULL, 5, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '告子曰：“性犹湍水也，决诸东方则东流，决诸西方则西流。人性之无分于善不善也，犹水之无分于东西也。”
孟子曰：“水信无分于东西。无分于上下乎？人性之善也，犹水之就下也。人无有不善，水无有不下。今夫水，搏而跃之，可使过颡；激而行之，可使在山。是岂水之性哉？其势则然也。人之可使为不善，其性亦犹是也。”
', '', '湍（tuān）：急流的水。决（jué）：打开缺口，引导水流。
信：的确。
搏（bó）：击打。颡（sǎng）：额头。
', '告子说：“人性好比湍急的水流，从东方打开缺口就向东流，从西方打开缺口就向西流。人性不分善与不善，就好像水没有东流、西流的分别。”
孟子说：“水的确没有东流、西流的定向，难道也没有上流、下流的定向吗？人性的善良，就像水性趋向下流。人的本性没有不善良的，水的本性没有不向下流的。假如拍打水让它飞溅起来，可以高过人的额头，堵住水道让它倒流，可以引上高山。然而，这难道是水的本性吗？是所处形势迫使它这样的。人之所以能够使他做坏事，是由于他的本性也像这样受到了逼迫。”
', NULL, '', 'indent', 1558003096, '5cdccd146e9ba10068e09572', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642686, '孟子 · 第十一卷 · 告子上 · 第三节 ', NULL, 4, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '告子曰：“生之谓性。”
孟子曰：“生之谓性也，犹白之谓白与？”曰：“然。”
“白羽之白也，犹白雪之白；白雪之白，犹白玉之白与？”曰：“然。”“然则犬之性，犹牛之性；牛之性，犹人之性与？”', '', '', '告子说：“天生的东西叫做天性。”
孟子说：“天生的东西叫做天性，就像所有物体的白色都叫做白吗？”
告子回答说：“是的。”
“这么说，白羽毛的白就像白雪的白；白雪的白如同白玉的白吗？”
告子回答说：“是的。”
“那么，狗的天性就像牛的天性，牛的天性就像人的天性吗？”
', NULL, '', 'indent', 1565349532, '5cdccd467b968a0073d1938e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642688, '孟子 · 第十一卷 · 告子上 · 第四节 ', NULL, 6, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '告子曰：“食色，性也。仁，内也，非外也；义，外也，非内也。”
孟子曰：“何以谓仁内义外也？”
曰：“彼长而我长之，非有长于我也；犹彼白而我白之，从其白于外也，故谓之外也。”
曰：“异于白马之白也，无以异于白人之白也；不识长马之长也，无以异于长人之长与？且谓长者义乎？长之者义乎？”
曰：“吾弟则爱之，秦人之弟则不爱也，是以我为悦者也，故谓之内。长楚人之长，亦长吾之长，是以长为悦者也，故谓之外也。”
曰：“耆秦人之炙，无以异于耆吾炙。夫物则亦有然者也，然则耆炙亦有外与？”', '', '食色，性也：《礼记·礼运》：“饮食男女，人之大欲存焉。”食，指物质资料生产；色，指人口自身的生产。
异于：此二字疑为衍文。
耆：同“嗜”。炙：烤的肉。
', '告子说：“饮食男女，是人的天性。仁是内在的，而不是外在的；义是外在的，而不是内在的。”
孟子说：“为什么说仁是内在的，而义是外在的呢？”
告子回答说：“他年纪大所以我尊敬他，并不是我内心原本就尊敬他。正如白色的东西我认为它白，是根据它外表的白色，所以说义是外在的。”
孟子说：“白马的白和白人的白或许没什么不同；但是不知道怜惜老马和不知道尊敬年长的人，也是没有什么不同吗？而且你说的义，在于年长者一方呢？还是在于尊敬年长者的一方呢？”
告子回答说：“是我的弟弟就爱他，是秦国人的弟弟就不爱他，爱不爱是由我自己内心决定的，所以说仁是内在的。尊敬楚国的长者，也尊敬我自己的长者，尊敬与否，是由年长这个外在因素决定的，所以说义是外在的。”
孟子说：“喜欢吃秦国人的烤肉，和喜欢吃自己的烤肉没什么不同，事物也有这种情况，那么，喜欢吃烤肉的心也是外在的吗？”
', NULL, '', 'indent', 1558003192, '5cdccd7643e78c00687f80b4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642689, '孟子 · 第十一卷 · 告子上 · 第五节 ', NULL, 4, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟季子问公都子曰：“何以谓义内也？”
曰：“行吾敬，故谓之内也。”
“乡人长于伯兄一岁，则谁敬？”曰：“敬兄。”
“酌则谁先？”曰：“先酌乡人。”
“所敬在此，所长在彼，果在外，非由内也。”公都子不能答，以告孟子。
孟子曰：“敬叔父乎？敬弟乎？彼将曰‘敬叔父’。曰：‘弟为尸，则谁敬？’彼将曰‘敬弟。’子曰：‘恶在其敬叔父也？’彼将曰：‘在位故也。’子亦曰：‘在位故也。庸敬在兄，斯须之敬在乡人。’”季子闻之曰：“敬叔父则敬，敬弟则敬，果在外，非由内也。”公都子曰：“冬日则饮汤，夏日则饮水，然则饮食亦在外也？”', '', '孟季子：人名，其人不详。
酌（zhuó）：斟酒。
尸（shī）：神主或神像。古代祭祀时，代死者受祭、象征死者神灵的人，以臣下或死者晚辈的人充当，后世逐渐用牌位、画像代替。
庸：常。斯须：暂时，片刻。
汤：开水。
', '孟季子问公都子说：“为什么说义是内在的东西呢？”
公都子回答说：“恭敬发自我的内心，所以说是内在的东西。”
孟季子问：“同乡人比你的大哥年长一岁，那你该恭敬谁呢？”
公都子说：“恭敬哥哥。”
“假如在一起喝酒，该先给谁斟酒？”
公都子说：“先给那个年长的乡人斟酒。”
“所敬重的是哥哥，却要向那个年长的乡人敬酒，说明义果然是外在的，而不是内在的。”
公都子无法回答这个问题，于是将这件事告诉了孟子。
孟子说：“你问他，该恭敬叔父还是恭敬弟弟？他会说：‘恭敬叔父。’问他：‘弟弟如果做了受祭的代理人，那么该恭敬谁呢？’他会说：‘恭敬弟弟。’你再问：‘那你为什么说要恭敬叔父呢？’他会说：‘这是由于弟弟处在受恭敬位置的缘故。’你就说：‘那也是由于本乡长者处在先敬酒位置的缘故，平日恭敬的对象是哥哥，临时的恭敬对象是同乡。’”
季子听了这话，说：“恭敬叔父是敬，恭敬弟弟也是敬，可见义是外在的，不是发自内心的。”
公都子说：“冬天喝热水，夏天喝凉水，那么饮食也取决于外物，并非是内在的需要吗？”
', NULL, '', 'indent', 1558003243, '5cdccda87b968a0073d19955', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642690, '孟子 · 第十一卷 · 告子上 · 第六节 ', NULL, 19, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '公都子曰：“告子曰：‘性无善无不善也。’或曰：‘性可以为善，可以为不善；是故文武兴，则民好善；幽厉兴，则民好暴。’或曰：‘有性善，有性不善；是故以尧为君而有象，以瞽瞍为父而有舜；以纣为兄之子且以为君，而有微子启、王子比干。’今曰‘性善’，然则彼皆非与？”
孟子曰：“乃若其情，则可以为善矣，乃所谓善也。若夫为不善，非才之罪也。恻隐之心，人皆有之；羞恶之心，人皆有之；恭敬之心，人皆有之；是非之心，人皆有之。恻隐之心，仁也；羞恶之心，义也；恭敬之心，礼也；是非之心，智也。仁义礼智，非由外铄我也，我固有之也，弗思耳矣。故曰：‘求则得之，舍则失之。’或相倍蓰而无算者，不能尽其才者也。诗曰：‘天生蒸民，有物有则。民之秉彝，好是懿德。’孔子曰：‘为此诗者，其知道乎！故有物必有则，民之秉彝也，故好是懿德。’”', '', '文、武：即周文王、周武王。
幽、厉：即周幽王、周厉王，是周代的两个暴君。
微子启：商纣王庶兄，名启。曾屡次劝谏商纣。周灭商后，称臣于周，后被封于宋，为宋国始祖。王子比干：商纣王的叔父，因屡次劝谏商纣，被剖心而死。
指《诗经·大雅·烝民》篇。
蒸：众。
秉彝：执守天的常道；秉，执；彝，常道。懿：美。
', '公都子说：“告子说：‘人的本性没有善和不善的问题。’有人说：‘人的本性可以让它善良，也可以让它不善。因此，周文王、周武王当政的时候，百姓就趋于善良；周幽王、周厉王当政的时候，百姓就趋于残暴。’又有人说：‘有本性善良的，有本性不善良的；因此，有尧这样的圣人做君主，却有象这样恶劣的百姓，有瞽瞍这样的坏父亲，却有舜这样的好儿子；有商纣这样恶劣的侄儿，而且身为君主，却有微子启、王子比干这样的仁人。’如今您说人本性善良，那么他们说的都不对吗？”
孟子说：“从人的天赋资质来看，是可以使它善良的，这就是我所说的人性善良。至于有些人做坏事，不是天赋资质的错。同情心，人人有；羞耻心，人人有；恭敬心，人人有；是非心，人人有。同情心即是仁；羞耻心即是义；恭敬心即是礼；是非心即是智。仁、义、礼、智，不是外人教我的，是我原本就有的，只是没深入思考过罢了。因此说：‘一经探求就会得到它，一经放弃就会失掉它。’人们之间有相差一倍、五倍甚至无数倍的，就是不能全部发挥出人的天赋资质的缘故。《诗经》说：‘上天生养万民，事物都有法则。百姓把握常规，喜爱美好品德。’孔子说：‘作这首诗的人，一定是个了解大道的人啊！因此，有事物便有其不变的法则；百姓把握了它，所以喜欢美好的品德。’”
', NULL, '', 'indent', 1558003285, '5cdccdd217b54d0068f41e09', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642691, '孟子 · 第十一卷 · 告子上 · 第七节 ', NULL, 6, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“富岁，子弟多赖；凶岁，子弟多暴，非天之降才尔殊也，其所以陷溺其心者然也。
今夫麰麦，播种而耰之，其地同，树之时又同，浡然而生，至于日至之时，皆熟矣。虽有不同，则地有肥硗，雨露之养，人事之不齐也。故凡同类者，举相似也，何独至于人而疑之？圣人与我同类者。故龙子曰：‘不知足而为屦，我知其不为蒉也。’屦之相似，天下之足同也。
口之于味，有同耆也。易牙先得我口之所耆者也。如使口之于味也，其性与人殊，若犬马之与我不同类也，则天下何耆皆从易牙之于味也？至于味，天下期于易牙，是天下之口相似也惟耳亦然。至于声，天下期于师旷，是天下之耳相似也。惟目亦然。至于子都，天下莫不知其姣也。不知子都之姣者，无目者也。故曰：口之于味也，有同耆焉；耳之于声也，有同听焉；目之于色也，有同美焉。至于心，独无所同然乎？心之所同然者何也？谓理也，义也。圣人先得我心之所同然耳。故理义之悦我心，犹刍豢之悦我口。”', '', '富岁：丰年。赖：通“懒”，懒惰。
麰（móu）麦：大麦。耰（yōu）：古农具，用于碎土平田。文中指播种后，覆土保护种子。
日至：指夏至和冬至。文中指夏至。
硗（qiāo）：坚硬多石的贫瘠土地。
齐：同“济”。
蒉（kuì）：草编的筐。
耆：同“嗜”。
易牙：春秋时齐桓公的宠臣。长于调味，善于逢迎，传说曾烹其子为羹以献齐桓公。
师旷：春秋时晋国盲人乐师，极善辨音。
子都：人名，春秋时郑国的美男子。姣（jiāo）：美丽。
刍豢（huàn）：草食动物叫刍，如牛、羊等；谷食动物叫豢，如狗、猪等。
', '孟子说：“丰年，年轻人大多懒惰；灾年，年轻人大多强暴，不是天生资质如此不同，而是所处的环境使他们心情变得糟糕。就拿大麦来说吧，撒下种子用土盖好，如果土质相同，播种时间又相同，便会生机勃勃地长起来。到夏至的时候，都会成熟了。即使有所不同，那也是土地有肥有瘠，雨露滋养有多有少，人们劳作程度不同的缘故。
“因此说，凡是同类的事物，都是相似的，为何单单说到人，就心生疑问了呢？圣人也是和我们同类的人。因此，龙子曾说：‘不用看清脚样去编草鞋，我知道编出来的不会是筐。’草鞋之所以相似，是由于天下人的脚都大致相同。嘴巴对于味道，有着同样的嗜好，易牙是预先摸清了这一嗜好的人。假如嘴巴对于味道的感觉，因人而异，而且就像狗、马和我们人类有着本质的不同一样，那么天下人为何都追随易牙的口味呢？说到口味，天下人都希望成为易牙，这是由于天下人的味觉都相似。耳朵也是这样。说到声音，天下人都希望成为师旷，这是由于天下人的听觉都相似。眼睛也是这样。说到子都，天下没有谁不知道他英俊。不知道子都的英俊的，是没长眼睛的人。因此说，嘴巴对于味道，有着相同的嗜好；耳朵对于声音，有着相同的听觉：眼睛对于姿色，有着相同的美感。一说到心，难道就单单没有什么相同的了吗？人心所公认的东西是什么？是理，是义。圣人先于普通人得知了我们心中共同的东西。因此说，理义使我心愉悦，就像牛、羊、猪、狗的肉合我的口味一样。”
', NULL, '', 'indent', 1558003346, '5cdcce1043e78c00687f8b7f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642692, '孟子 · 第十一卷 · 告子上 · 第八节', NULL, 11, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“牛山之木尝美矣，以其郊于大国也，斧斤伐之，可以为美乎？是其日夜之所息，雨露之所润，非无萌蘖之生焉，牛羊又从而牧之，是以若彼濯濯也。人见其濯濯也，以为未尝有材焉，此岂山之性也哉？
虽存乎人者，岂无仁义之心哉？其所以放其良心者，亦犹斧斤之于木也，旦旦而伐之，可以为美乎？其日夜之所息，平旦之气，其好恶与人相近也者几希，则其旦昼之所为，有梏亡之矣。梏之反覆，则其夜气不足以存；夜气不足以存，则其违禽兽不远矣。人见其禽兽也，而以为未尝有才焉者，是岂人之情也哉？
故苟得其养，无物不长；苟失其养，无物不消。孔子曰：‘操则存，舍则亡；出入无时，莫知其乡。’惟心之谓与？”', '', '牛山：在今山东临淄南。郊：此指生长在郊外。大国：指临淄，是当时的大城市。
萌：草木萌发。蘖（niè）：树木枝砍伐后再生的枝芽。
濯濯：光秃的样子。
放其良心：丧失其良心。
乡：通“向”。
', '孟子说：“牛山的树木曾经是繁茂的，可是它生长在大城市的郊外，总有斧子去砍伐它，还能长得繁茂吗？这些树木日夜不停地生长繁殖着，雨水露珠滋润着它们，不是没有新条，嫩芽长出来，可是人们又紧跟着在这里放牧牛羊，因此才那样光秃。人们看见那山光秃秃的，就以为它不曾生长过树木，这难道是山的本性吗？在人的身上，难道没有仁义之心吗？之所以有人失掉了他的善良之心，也像斧子对待树木一样，天天砍它，怎么能让它繁茂呢？他在日里夜里萌生的善心，他在清晨触及的清新之气，这些在他心中所引发的好恶跟一般人也有点接近。然而，到了第二天白天做出的事，就把那点与常人相同的善心给泯灭了。反反复复地泯灭，那么他夜里心中萌生的良善就不能存在下去，夜里萌生的良善不能存留在心，那么他就和禽兽相差无几了。别人看见他是个禽兽，就以为他不曾有过好的资质，这难道是人的本性吗？因此说，假如得到好的滋养，没有东西不能生长；假如丧失了好的滋养，没有东西不会消亡。孔子说：‘抓住了就存在，放弃了就失去，出来进去没有确定的时间，没谁知道它的去向。’说的就是人心吧？”
', NULL, '', 'indent', 1558003390, '5cdcce3a43e78c00687f8d74', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642693, '孟子 · 第十一卷 · 告子上 · 第九节', NULL, 20, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“无或乎王之不智也，虽有天下易生之物也，一日暴之，十日寒之，未有能生者也。吾见亦罕矣，吾退而寒之者至矣。吾如有萌焉何哉！今夫弈之为数，小数也；不专心致志，则不得也。弈秋，通国之善弈者也。使弈秋诲二人弈，其一人专心致志，惟弈秋之为听。一人虽听之，一心以为有鸿鹄将至，思援弓缴而射之，虽与之俱学，弗若之矣。为是其智弗若与？曰：非然也。”', '', '或：通“惑”，疑惑。
暴（pù）：同“曝”，晾晒。
弈（yì）：围棋。数：技艺。
弈秋：古代善弈的人。
鸿鹄（hú）：鸟名，即天鹅。缴（zhuó）：系于箭上的丝蝇。
', '孟子说：“对大王的不明智，大家不必困惑。天下即使有容易生长的植物，晒它一天后，又冻它十天，没有能长得了的。我和大王相处的机会太少了，我退居家中，向他吹阴风的人就包围了他，纵使有善心萌动的情况，我又能对它怎么办呢？下棋在各种技艺当中属于很小的技艺；可是，如果不全心全意，就学不好。弈秋是全国的下棋高手。假如让弈秋教两个人学下棋，其中一个人一心一意地学，只听弈秋的讲解。另一个人虽然也听着，但一心以为也许会有大雁飞来，想着拿起弓箭去射它，虽然和前一个人一起学下棋，但却不如那个人学得好。是因为他的聪明程度赶不上人家吗？当然不是这样。”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b48a1b6a81d0c538d0271", "shortContent": " 东汉时候为《孟子》书作注的赵岐，在其《孟子题辞》中说：“孟子长于譬喻。”善于用形象性的譬喻来帮助说理，的确是孟子的一大特长。有人统计，《孟子》全书261章，有93章总共使用了159种譬喻。此外，孟子还善于运用生动幽默的寓言故事深入浅出地阐明他的思想，这些小故事情节生动，幽默风趣，寓意深刻，耐人寻味，不少也具有比喻的功能，用来说明一些抽象的道理。这些手法的运用，使得《孟子》的文章非常富有形象性。本...", "authors": ["徐克谦"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558003432, '5cdcce66c8959c0068dda00b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642696, '孟子 · 第十一卷 · 告子上 · 第十二节 ', NULL, 11, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“今有无名之指，屈而不信，非疾痛害事也，如有能信之者，同不远秦楚之路，为指之不若人也。指不若人，则知恶之；心不若人，则不知恶，此之谓不知类也。”
', '', '信（shēn）：通“伸”。
', '孟子说：“现在有人有一个无名指弯曲着，伸展不开，不是很疼痛，也不妨碍做事。可是，如果有人能让它重新伸直，那么就是让他前往秦国、楚国去治，他也不会觉得路远，为的是无名指不及别人。手指不如别人，就知道厌恶，心性赶不上别人，却不知道厌恶，这就叫不知道哪个轻，哪个重啊。”
', NULL, '', 'indent', 1558089830, '5cde1fdc6e9ba10068f21f37', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642697, '孟子 · 第十一卷 · 告子上 · 第十三节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“拱把之桐梓，人苟欲生之，皆知所以养之者。至于身，而不知所以养之者，岂爱身不若桐梓哉？弗思甚也。”', '', '拱把：指树木尚小。桐：梧桐树。梓：一种落叶树。
', '孟子说：“两手合围般粗的桐树、梓树，假如人想要它生长起来，都知道怎么才能把它养大。说到自身，却不知道如何去修养，难道对自己的爱还赶不上对桐树、梓树的爱吗？实在是太不愿动脑子了。”
', NULL, '', 'indent', 1558089862, '5cde20046e9ba10068f22171', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642698, '孟子 · 第十一卷 · 告子上 · 第十四节', NULL, 10, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“人之于身也，兼所爱。兼所爱，则兼所养也。无尺寸之肤不爱焉，则无尺寸之肤不养也。所以考其善不善者，岂有他哉？于己取之而已矣。体有贵贱，有小大。无以小害大，无以贱害贵。养其小者为小人，养其大者为大人。今有场师，舍其梧槚，养其樲棘，则为贱场师焉。养其一指而失其肩背，而不知也，则为狼疾人也。饮食之人，则人贱之矣，为其养小以失大也。饮食之人无有失也，则口腹岂适为尺寸之肤哉？”
', '', '场师：园艺师。梧：梧桐树。槚（jiǎ），即楸树，木理细密，是上等木料。樲（èr）：即酸枣。棘：荆棘。
狼疾：即“狼藉”，糊涂。
适：通“啻”（chì），但，只。
', '孟子说：“人们对于自己的身体，无所不爱。全都爱护，就全都保养。没有一尺、一寸的肌肤不爱护，那么就没有一尺、一寸的肌肤得不到保养。因此，考察他保养得好与不好，难道有别的好办法吗？只要看他重点养护的是哪些部分就可以了。身体有至关重要的部分，有微不足道的部分：有小的部分，有大的部分。不要因为小的部分而损害大的部分，不要因为微不足道的部分而损害至关重要的部分。能保养好小的部分的是小人，能保养好大的部分的是君子。假如说有这样一个园艺家，把梧桐、梓树丢在一边，而去养护酸枣、荆棘，那么他就是个不称职的园艺家。假如有人只保养他的一根手指，而失掉了肩头、后背的功能，自己却还不知道，那便是个糊涂虫。只在吃喝上下工夫的人，人们看不起他，因为他保养小的部分，而失掉了大的部分。如果讲究吃喝的那些人没丢掉思想的培养，那么他们吃喝的目的难道只为保养口腹这些小部分的需要吗？”
', NULL, '', 'indent', 1558089896, '5cde20267b968a0073e31031', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642699, '孟子 · 第十一卷 · 告子上 · 第十五节 ', NULL, 18, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '公都子问曰：“钧是人也，或为大人，或为小人，何也？”
孟子曰：“从其大体为大人，从其小体为小人。”
曰：“钧是人也，或从其大体，或从其小体，何也？”
曰：“耳目之官不思，而蔽于物，物交物，则引之而已矣。心之官则思，思则得之，不思则不得也。此天之所与我者，先立乎其大者，则其小者弗能夺也。此为大人而已矣。”', '', '钧：通“均”，同样。
大体：指心。小体：指耳、目等感官。
', '公都子问道：“同样是人，有人是君子，有人是小人，这是为什么呢？”
孟子说：“从心志上用功夫的，就是君子；从耳目一类的小体上用功夫的，就是小人。”
公都子又问：“同样是人，有人从心志上用功夫，有人从耳目一类的小体上用功夫，这又是为什么呢？”
孟子回答说：“耳朵、眼睛这类器官不会思考，所以被外物所蒙蔽。耳朵、眼睛也只不过是物，它们与外物接触，只能起到引导的作用。心的功能在于思考，思考了就会有所得，不思考就一无所获。这是上天赐予我们人类的。所以，先把心志这一大的方面树立起来，那么，那些次要的方面就不能侵夺它了。这样就成为君子了。”
', NULL, '', 'indent', 1558089933, '5cde20497b968a0073e31238', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642700, '孟子 · 第十一卷 · 告子上 · 第十六节 ', NULL, 7, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“有天爵者，有人爵者。仁义忠信，乐善不倦，此天爵也；公卿大夫，此人爵也。古之人修其天爵，而人爵从之。今之人修其天爵，以要人爵；即得人爵，而弃其天爵，则惑之甚者也，终亦必亡而已矣。”
', '', '', '孟子说：“有天赐爵位，有社会爵位。仁义忠信，行善且乐此不疲，这是天赐的爵位；公卿大夫，这是社会的爵位。古时的人，修养自己的天赐爵位，然后社会爵位就随之而来。现在的人修养天赐爵位，以此来追逐社会爵位；得到社会爵位以后，就丢掉了天赐爵位，那实在是太糊涂了，最终必然连社会爵位也丧失掉。”
', NULL, '', 'indent', 1558089954, '5cde206043e78c00689121ef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642701, '孟子 · 第十一卷 · 告子上 · 第十七节 ', NULL, 8, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“欲贵者，人之同心也。人人有贵于己者，弗思耳。人之所贵者，非良贵也。赵孟之所贵，赵孟能贱之。诗云：‘既醉以酒，既饱以德。’言饱乎仁义也，所以不愿人之膏粱之味也；令闻广誉施于身，所以不愿人之文绣也。”', '', '赵孟：春秋时晋国正卿赵盾，字孟。此指代有权势的人。
[2]诗句见《诗经·大雅·既醉》。
[3]德：今人高亨认为“德”字当作“食”，古德字作“惪”，与食形近而误（说见其《诗经今注》）。
', '孟子说：“希求富贵，是人们的共同心理。每个人自身都有可宝贵的东西，只是不去想它罢了。别人给予的尊贵，不是真正的尊贵。赵孟所尊贵的，赵孟也能使他卑贱。《诗经》说：‘既供奉美酒使他陶醉，又献上仁德使他满足。’说的就是已经饱尝了仁义之德，因而不羡慕人家肥肉、精米的美味；广为人知的好名声集于一身，因而不羡慕别人的锦绣衣裳。”
', NULL, '', 'indent', 1558089996, '5cde208930863b00699003d4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642766, '孟子 · 第十三卷 · 尽心上 · 第十九节 ', NULL, 4, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“有事君人者，事是君则为容悦者也；有安社稷臣者，以安社稷为悦者也；有天民者，达可行于天下而后行之者也；有大人者，正己而物正者也。”', '', '', '孟子说：“有侍奉君主的人，把侍奉某个君主当作快乐；有安定国家的臣子，把安定国家当作快乐；有天民，就是那些先使大道通行于天下，然后再去实行的人；有大人，就是那些使自身端正，外物便随之端正的人。”
', NULL, '', 'indent', 1558348644, '5ce212e0eaa3750067330ed8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642702, '孟子 · 第十一卷 · 告子上 · 第十八节 ', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“仁之胜不仁也，犹水胜火。今之为仁者，犹以一杯水，救一车薪之火也；不熄，则谓之水不胜火，此又与于不仁之甚者也。亦终必亡而已矣。”
', '', '与：助，增加。
', '孟子说：“仁能够战胜不仁，就像水能够战胜火。如今实行仁德的人，就像拿一杯水来救一车木柴燃起的大火；灭不了火，就说水不能战胜火，这又助长了不仁之人的嚣张气焰，最后连他们已有的那点仁德也会丧失掉。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf302a", "shortContent": "孟子用杯水车薪的比喻说明：仁要胜过不仁是有条件的。\n\n孟子虽然对仁义、仁政的作用保有坚定信心，反复向君王们宣称“仁者无敌”（《梁惠王上》）的观念，如“老吾老，以及人之老；幼吾幼，以及人之幼。天下可运于掌”（《梁惠王上》），“与百姓同乐，则王矣”（《梁惠王下》）。孟子甚至相信实行仁政“可使制梃以挞秦楚之坚甲利兵矣”（《梁惠王上》）。这里，孟子较为客观地分析了仁与不仁之间的辩证关系。他首先肯定仁必能战...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1558090024, '5cde20a5c8959c0068ef35d3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642703, '孟子 · 第十一卷 · 告子上 · 第十九节 ', NULL, 2, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“五谷者，种之美者也；苟为不熟，不如荑稗。夫仁亦在乎熟之而已矣。”', '', '荑（tí）稗（bài）：即“稊稗”。荑，类似谷子的一种杂草。稗：稻田里的一种杂草。
', '孟子说：“五谷是庄稼中的好东西，可是如果没成熟，还不如稗子之类的野草。仁也是这样，关键在于使它成熟罢了。”
', NULL, '', 'indent', 1558090052, '5cde20c27b968a0073e31897', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642704, '孟子 · 第十一卷 · 告子上 · 第二十节 ', NULL, 6, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“羿之教人射，必志于彀；学者亦必志于彀。大匠诲人，必以规矩；学者亦必以规矩。”', '', '彀（gòu）：把弓拉满。
', '孟子说：“羿教人射箭，一定要让人把弓拉满；学习的人也一定要努力把弓拉满。技艺高超的木工教导人，一定要遵循规矩，学习的人也一定要遵循规矩。”
', NULL, '', 'indent', 1558090091, '5cde20e97b968a0073e31a44', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642705, '孟子 · 第十二卷 · 告子下 · 第一节 ', NULL, 10, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '任人有问屋庐子曰：“礼与食孰重？”曰：“礼重。”
“色与礼孰重？”曰：“礼重。”
曰：“以礼食，则饥而死；不以礼食，则得食，必以礼乎？亲迎，则不得妻；不亲迎，则得妻，必亲迎乎！”屋庐子不能对，明日之邹以告孟子。
孟子曰：“于答是也何有？不揣其本而齐其末，方寸之木可使高于岑楼。金重于羽者，岂谓一钩金与一舆羽之谓哉？取食之重者，与礼之轻者而比之，奚翅食重？取色之重者，与礼之轻者而比之，奚翅色重？往应之曰：‘紾兄之臂而夺之食，则得食；不紾，则不得食，则将紾之乎？逾东家墙而搂其处子，则得妻；不搂，则不得妻，则将搂之乎？’”', '', '任：春秋战国时，诸侯国名，风姓。屋庐子：孟子的弟子，名连。
亲迎：古代婚礼仪式之一，新郎亲自到女方家迎娶新娘，此指依传统礼法娶妻。不亲迎：指用违反传统礼法的方法娶妻，如掠夺婚、野合等。
邹：古国名，曹姓。周武王所封，称邾。战国时改称邹，后为楚所灭。
揣：度量。
岑（cén）楼：尖角高楼。
一钩金：带钩用金半钧，重量为三钱多。
翅（chì）：通“啻”，只，仅。
紾（zhěn）：扭转。
处子：未出嫁的女子，即处女。
', '有个任国人问屋庐子说：“礼仪和饮食哪个重要？”
屋庐子回答说：“礼仪重要。”
“娶妻和礼仪哪个重要？”
屋庐子说：“礼仪重要。”
任国人继续问：“如果依照礼仪去谋食，就会饿死；不依礼仪去谋食，就能得到吃的，那么一定要遵守礼法吗？依亲迎礼行事，就得不到妻子；不依亲迎礼行事，就能得到妻子，那么一定要依亲迎礼吗？”
屋庐子回答不上来，第二天去邹国，把任国人的话告诉孟子。
孟子说：“回答这个问题有什么难的呢？不去度量根基的高低，而只让顶端平齐，这样的话，一寸厚的小木块，若是放在高处，都可以使它高过尖角的高楼。金子比羽毛重，难道能因此说三钱多重的金子比一车羽毛都重吗？如果拿饮食的重要方面来和礼仪的次要方面对比，何止是吃的重要？拿婚姻的重要方面和礼仪的次要方面对比，何止是娶妻重要？你去跟他说：‘扭住哥哥的胳膊，抢他的饭吃，就能得到吃的；不扭他的胳膊，就得不到吃的，那么就该去扭吗？跨过东邻家的院墙，搂抱未出嫁的女子，就会得到妻子；不搂抱，就得不到妻子，那么就该去搂抱吗？’”


', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b48cae49f46528a429823", "shortContent": " 伦理学中一个至关紧要的大问题是如何把道德的纯洁性和可行性结合起来，就是说既要保持道德的高尚，又不能使它高不可攀，让人望而生畏，它应当为一般人愿意实行。儒家特别重视这个问题，以为圣人之道不远人，远人不可以为道。《中庸》提出君子之道如行远路，要从近的地方开始，又如登高，必定从低处出发；它能为普通百姓认识和实行，但它的最高境界连圣人也有所不知，也难以达到。孟子在这里着力阐发这个道理。\n\n首先，礼与人的...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558090176, '5cde213c17b54d00680594bc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642706, '孟子 · 第十二卷 · 告子下 · 第二节 ', NULL, 5, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '曹交问曰：“人皆可以为尧舜，有诸？”孟子曰：“然。”“交闻文王十尺，汤九尺，今交九尺四寸以长，食粟而已，如何则可？”
曰：“奚有于是？亦为之而已矣。有人于此，力不能胜一匹雏，则为无力人矣；今曰举百钧，则为有力人矣。然则举乌获之任，是亦为乌获而已矣。夫人岂以不胜为患哉？弗为耳。徐行后长者谓之弟，疾行先长者谓之不弟。夫徐行者，岂人所不能哉？所不为也。尧舜之道，孝弟而已矣。子服尧之服，诵尧之言，行尧之行，是尧而已矣；子服桀之服，诵桀之言，行桀之行，是桀而已矣。”
曰：“交得见于邹君，可以假馆，愿留而受业于门。”
曰：“夫道，若大路然，岂难知哉？人病不求耳。子归而求之，有余师。”', '', '曹交：曹国国君的弟弟，名交。
一匹雏：一只小鸡。
乌获：人名，秦武王时的力士。文中代指力士。
弟：同“悌”。
诵：讲述，陈述。
病：毛病，缺点。
', '曹交问道：“人人都可以成为尧、舜，有这话吗？”
孟子说：“有。”
“我听说周文王身长一丈，商汤身长九尺，现在我身长九尺四寸，只会吃饭罢了，要怎样才可以成为尧、舜呢？”
孟子说：“这有什么关系呢？只要去做就可以了。假如有个人，他的力气提不起一只小鸡，那么他就是个没力气的人；假如他能举起三千斤，就是个有力气的人了。那么，举得起乌获那样的大力士所能承受的重量的，也就是乌获了。人难道该为不能胜任发愁吗？只是不去做罢了。在长者身后慢慢走，叫做悌；快步走到长者前边去，叫做不悌。慢一点走，难道是人做不到的事吗？只是不去做罢了。尧、舜之道，就是孝和悌而已。你穿上尧的衣服，说尧说的话，做尧做的事，你就是尧了。你穿桀的衣服，说桀说的话，干桀干的事，你就是桀了。”
曹交说：“我要是能见到邹国国君，就向他借个住处，愿意留下来在您门下学习。”
孟子回答说：“道就像条大路，难道难以知晓吗？人的缺点在于不去寻求罢了。你回去找找，老师多着呢。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf302b", "shortContent": "《孟子》书中，把尧、舜合在一起说的地方约有四十余处，“孟子道性善，言必称尧舜”（《滕文公上》），可以说，在孟子眼里，尧舜已成为最完美的道德典范，成为内圣之道的最高代表，并已符号化为一种理想人格的象征。\n\n既然尧舜代表着完美的理想人格，那为何又说人人都可以成为尧舜呢？孟子的这一结论有两个前后相承的依据：一是人人都有恻隐之心、羞恶之心、辞让之心和是非之心，因而人人都有善性；二是“凡同类者，举相似也，何...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1558090234, '5cde217730863b00699010a2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642707, '孟子 · 第十二卷 · 告子下 · 第三节 ', NULL, 4, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '公孙丑问曰：“高子曰：‘小弁，小人之诗也。’”
孟子曰：“何以言之？”曰：“怨。”
曰：“固哉，高叟之为诗也！有人于此，越人关弓而射之，则己谈笑而道之；无他，疏之也。其兄关弓而射之，则己垂涕泣而道之；无他，戚之也。小弁之怨，亲亲也。亲亲，仁也。固矣夫，高叟之为诗也！”曰：“凯风何以不怨？”
曰：“凯风，亲之过小者也；小弁，亲之过大者也。亲之过大而不怨，是愈疏也；亲之过小而怨，是不可矶也。愈疏，不孝也；不可矶，亦不孝也。孔子曰：‘舜其至孝矣，五十而慕。’”', '', '高子：齐国人。
《小弁》：《诗经·小雅》中的诗篇。旧说是讽刺周幽王的诗，或说是周宣王名臣尹吉甫之子因遭后母谗言而作。
关：通“弯”，拉满弓，开弓。
戚：亲。
《凯风》：《诗经·邶风》中的诗篇。通篇是自责以安慰母亲的言词。
矶（jī）：激怒，触犯。
慕：依恋。
', '公孙丑问道：“高子说《小弁》这首诗是小人写的。”
孟子说：“凭什么这么说呢？”
公孙丑回答说：“因为诗里含有怨恨之意。”
孟子说：“高老先生讲诗实在是太机械了。假如说有这么个人，越国人开弓去射他，那么他会笑着讲述此事；没有别的原因，因为越国人和他关系很远。如果是他的哥哥开弓去射他，他会流着眼泪讲述此事，没有别的原因，因为哥哥是他的亲人。《小弁》的怨恨，正是出于对亲人的爱。热爱亲人是仁的体现。高老先生讲诗实在是太机械了！”
公孙丑说：“《凯风》这首诗为什么没有怨恨之意呢？”
孟子答道：“《凯风》这首诗，母亲的过错不大；《小弁》这首诗，父亲的过错很大。父母的过错很大，却不怨恨，这是越发疏远他们了。父母的过错不大，却去怨恨他们，是受不得刺激。越发疏远是不孝；受不得刺激，也是不孝。孔子说：‘舜大概是最孝顺的了，五十岁还依恋父母。’”
', NULL, '', 'indent', 1558090286, '5cde21a9c8959c0068ef43f2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642708, '孟子 · 第十二卷 · 告子下 · 第四节 ', NULL, 6, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '宋牼将之楚，孟子遇于石丘。曰：“先生将何之？”
曰：“吾闻秦楚构兵，我将见楚王说而罢之。楚王不悦，我将见秦王说而罢之，二王我将有所遇焉。”
曰：“轲也请无问其详，愿闻其指。说之将何如？”
曰：“我将言其不利也。”
曰：“先生之志则大矣，先生之号则不可。先生以利说秦楚之王，秦楚之王悦于利，以罢三军之师，是三军之士乐罢而悦于利也。为人臣者怀利以事其君，为人子者怀利以事其父，为人弟者怀利以事其兄。是君臣、父子、兄弟终去仁义，怀利以相接，然而不亡者，未之有也。先生以仁义说秦楚之王，秦楚之王悦于仁义，而罢三军之师，是三军之士乐罢而悦于仁义也。为人臣者怀仁义以事其君，为人子者怀仁义以事其父，为人弟者怀仁义以事其兄，是君臣、父子、兄弟去利，怀仁义以相接也。然而不王者，未之有也。何必曰利？”', '', '宋牼（kēng）：也叫宋钘（jiān）、宋荣，宋国人，战国时期著名学者，齐宣王时曾在稷下学宫游学。石丘：地名。
构兵：交战。构，交合，连接。
指：意向，大意。
大：有美意。古今大、强、高、快、长等均有美意。号：提法，说法。
终：尽，全，都的意思。
', '宋牼要到楚国去，孟子在石丘遇到他，孟子说：“您要到哪儿去？”
宋牼回答说：“我听说秦国和楚国要开战，我要去面见楚王劝说他罢兵。假如楚王不听的话，我就去面见秦王劝他罢兵。这两个国君总会有一个听我话的。”
孟子说：“我不想问您详细情况，愿听听你的大意。您打算怎样去劝说他们呢？”
宋牼回答说：“我打算说说交战的不利之处。”
孟子说：“您的志向是很好的，然而您的提法却行不通。您用利来劝说秦王、楚王，秦王、楚王因为有利可图而欢喜，于是终止军事行动，这样的话，军队的将士就会为休战而高兴，从而喜欢利。做臣子的，怀着利益之心去侍奉他的君主，做儿子的怀着利益之心去侍奉他的父亲，做弟弟的怀着利益之心去侍奉他的兄长，这就会导致君臣、父子、兄弟之间最终都会抛弃仁义，怀着利益之心交往，在这种情况下国家不灭亡的，还没有过。您若以仁义去劝说秦王、楚王，秦王、楚王喜欢仁义而高兴，于是撤除军队，这会使军队将士高兴休兵，进而喜欢仁义。做臣子的怀着仁义之心去侍奉他的君主，做儿子的怀着仁义之心去侍奉他的父亲，做人弟弟的怀着仁义之心去侍奉兄长，这会使君臣、父子、兄弟去除求利的念头，而怀着仁义之心交往，这样却不能统一天下，是不曾有过的。为什么一定要谈到‘利’呢？”
', '[{"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42b0c6e67846a9227c06", "shortContent": "本篇采自《艾子后语》。这是一篇讽刺性的笑话，揭露和嘲笑了相面者的骗人伎俩。作者采用的方法，是以他可笑的言行来戳穿他的谎言。先写他大言不惭地吹嘘自己是鬼谷子之高足弟和唐举的受业师，实际上却连一点本事也没有。相面不论其验否，都是要预言未来的祸福吉凶的，而他却是等待和观察已有的事实，然后根据事实来瞎编胡诌。齐王的话无情地揭破了他的骗局：“此已验之祸，请勿言。”这样的骗子，作者在标题中却称他为“神相”，这...", "authors": ["周先慎"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558090338, '5cde21df43e78c0068913a78', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642709, '孟子 · 第十二卷 · 告子下 · 第五节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子居邹，季任为任处守，以币交，受之而不报。处于平陆，储子为相，以币交，受之而不报。他日由邹之任，见季子；由平陆之齐，不见储子。屋庐子喜曰：“连得间矣。”
问曰：“夫子之任见季子，之齐不见储子，为其为相与？”
曰：“非也。书曰：‘享多仪，仪不及物曰不享，惟不役志于享。’为其不成享也。”
屋庐子悦。或问之。屋庐子曰：“季子不得之邹，储子得之平陆。”', '', '季任：任国国君的弟弟。币：帛，此泛指礼物。
平陆：地名，战国时为齐地。储子：齐国相。
连：屋庐子的名。
此处引自《尚书·周书·洛诰》篇。
享：指将珍品、宝物奉献给天子、诸侯。多：注重，推重。
', '孟子住在邹国的时候，季任留守任国，代理政事，送礼物给孟子，想交个朋友，孟子收下了礼物，但没有回谢。当孟子住在平陆的时候，储子做齐国卿相，送礼物给孟子，想交朋友，孟子也收下了礼物而没有回谢。过了些日子，孟子从邹国到任国去，拜访了季子；从平陆到齐都去，却没有拜访储子。屋庐子高兴地说：“这回我可找到老师的岔子了。”于是问道：“您到任国去，拜访了季子，到齐都，却没拜访储子，是因为储子只是个卿相吗？”
孟子回答说：“不是这样的。《尚书》说：‘享献之礼推重仪节，如果仪节没有到位，礼物再多也不算是享献，因为没有用心于此。’是因为这样不称其为享献。
屋庐子很高兴。有人问他，屋庐子回答说：“季子无法亲自到邹国去拜访先生，储子却可以亲自到平陆去拜访。”
', NULL, '', 'indent', 1558090383, '5cde220d7b968a0073e329b7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642710, '孟子 · 第十二卷 · 告子下 · 第六节 ', NULL, 7, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '淳于髡曰：“先名实者，为人也；后名实者，自为也。夫子在三卿之中，名实未加于上下而去之，仁者固如此乎？”
孟子曰：“居下位，不以贤事不肖者，伯夷也；五就汤，五就桀者，伊尹也；不恶污君，不辞小官者，柳下惠也。三子者不同道，其趋一也。一者何也？曰：仁也。君子亦仁而已矣，何必同？”
曰：“鲁缪公之时，公仪子为政，子柳、子思为臣，鲁之削也滋甚。若是乎贤者之无益于国也！”
曰：“虞不用百里奚而亡，秦穆公用之而霸。不用贤则亡，削何可得与？”
曰：“昔者王豹处于淇，而河西善讴；绵驹处于高唐，而齐右善歌；华周、杞梁之妻善哭其夫，而变国俗。有诸内必形诸外。为其事而无其功者，髡未尝睹之也。是故无贤者也，有则髡必识之。”
曰：“孔子为鲁司寇，不用，从而祭，燔肉不至，不税冕而行。不知者以为为肉也。其知者以为为无礼也。乃孔子则欲以微罪行，不欲为苟去。君子之所为，众人固不识也。”', '', '淳于髡（kūn）：人名。姓淳于，名髡，齐国人。
三卿：在孟子所处时代，一般指上卿、亚卿和下卿。名实未加于上下：指未建立功业，未曾兼济；上指国君，下指百姓。
公仪子：即公仪休。子柳：即泄柳，春秋时鲁国人。
王豹：齐人，擅长歌唱。河西：黄河以西，指卫地。讴：歌唱。
绵驹：齐人，擅长歌唱。高唐：地名，故址在今山东禹城西南。
华周：也叫华旋，齐国人。杞梁：春秋时期齐国大夫。
燔（fán）肉：祭肉。燔，通“膰”。税（tuō）冕：脱掉祭祀时戴的礼帽。税，通“脱”，冕是祭祀时戴的礼帽。
', '淳于髡说：“把名声功业看得很重的人，是为了济世救民，不很看重名声功业的人，是为了独善其身。您是齐国三卿之一，有关上助君王、下救百姓的名声、功业都没有，就要离开齐国，仁者难道原本就是这样的吗？”
孟子说：“身处卑贱的地位，不以自己贤能之身侍奉无德之君，这是伯夷；五次前往商汤那里，又五次前往夏桀那里的，这是伊尹；不厌恶污浊之君，不拒绝做个小官的人是柳下惠。这三个人的处世之道并不相同，但大方向是一致的。这一致的东西是什么呢？应该说就是仁。君子做到仁就可以了，为什么一定要处处相同呢？”
淳于髡说：“鲁穆公的时候，公仪子执政，子柳、子思当大臣，鲁国的国土削减得更厉害了。像这样，贤德的人对国家没有什么好处。”
孟子说：“虞国不任用百里奚，因而亡国，秦穆公重用百里奚，因而称霸。不任用贤人就会导致灭亡，想要勉强支撑都是做不到的。”
淳于髡说：“从前王豹住在淇水边的时候，住在河西的人都善于唱歌，绵驹住在高唐，齐国西部的人都善唱歌，华周、杞梁的妻子擅长哭夫，因而改变了国家的民俗。里面存在的东西，一定会体现在外面。做某种事，却不见功效的，我从未见过。因此说，是没有贤人；有的话，我一定会知道他。”
孟子说：“孔子做鲁国司寇的时候，不被重用，跟随君主祭祀，祭肉没有送到他这里，于是没顾上摘掉祭祀时戴的礼帽，就离开了。不了解孔子的人以为他是为了祭肉的缘故，了解孔子的人认为他是为了鲁君的失礼而离开的。至于孔子，他就是想要担点小罪名离开，不想随便走掉。君子所做的事，普通人本来就不能了解。”
', NULL, '', 'indent', 1558090463, '5cde225d7b968a0073e32e25', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642711, '孟子 · 第十二卷 · 告子下 · 第七节', NULL, 3, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“五霸者，三王之罪人也；今之诸侯，五霸之罪人也；今之大夫，今之诸侯之罪人也。天子适诸侯曰巡狩，诸侯朝于天子曰述职。春省耕而补不足，秋省敛而助不给。入其疆，土地辟，田野治，养老尊贤，俊杰在位，则有庆，庆以地。入其疆，土地荒芜，遗老失贤，掊克在位，则有让。一不朝，则贬其爵；再不朝，则削其地；三不朝，则六师移之。是故天子讨而不伐，诸侯伐而不讨。五霸者，搂诸侯以伐诸侯者也，故曰：五霸者，三王之罪人也。五霸，桓公为盛。葵丘之会诸侯，束牲、载书而不歃血。初命曰：‘诛不孝，无易树子，无以妾为妻。’再命曰：‘尊贤育才，以彰有德。’三命曰：‘敬老慈幼，无忘宾旅。’四命曰：‘士无世官，官事无摄，取士必得，无专杀大夫。’五命曰：‘无曲防，无遏籴，无有封而不告。’曰：‘凡我同盟之人，既盟之后，言归于好。’今之诸侯，皆犯此五禁，故曰：今之诸侯，五霸之罪人也。长君之恶其罪小，逢君之恶其罪大。今之大夫，皆逢君之恶，故曰：今之大夫，今之诸侯之罪人也。”', '', '五霸：一般指齐桓公、晋文公、秦穆公、宋襄公、楚庄王。三王：夏禹、商汤、周文王、武王。
省：视察。敛：收聚。给：丰足。
庆：封赏。
掊（póu）克：又作“掊克”，以苛税搜刮民财。这里指搜刮民财的人。让：责难。
搂：聚合。
葵丘：今河南考城县东三十里。载书：把盟书放在牺牲上。歃（shà）血：盟誓时杀牲而饮其血以示诚信。
摄：代理。专：专擅，独断独行。
曲：无不，遍。籴（dí）：买进粮食。
逢君：迎合君王。
', '孟子说：“五霸，是三王的罪人；如今的诸侯，是五霸的罪人；如今的大夫，是诸侯的罪人。天子到诸侯那里巡视叫巡狩，诸侯到天子那里朝拜叫述职。天子巡狩，春天视察耕种的情况，弥补财力不足的百姓；秋天视察收藏的情况，赈济粮食短缺的百姓。进入诸侯的疆土，如果土地得到开辟，田野得到治理，老人得到供养，贤人得到尊敬，杰出的人得以做官，那么就有封赏；拿土地来封赏。如果进入诸侯的疆土，发现土地得不到开垦，老人得不到供养，贤人得不到任用，聚敛之人得以做官，就有贵罚。一次不朝拜，就要降低他的爵位；两次不朝拜，就要削减他的封地；三次不朝拜，就要把军队开过去。因此，天子出兵是讨而不是伐，诸侯出兵是伐而不是讨。五霸，是聚合一部分诸侯去攻打另一部分诸侯的人，因此说，五霸是三王的罪人。五霸当中，齐桓公影响最大。在葵丘盟会诸侯，捆绑好牺牲，把盟书放在牺牲身上，而没有饮血。第一条盟约说，声讨不孝之人，不要废立太子，不要立妾为妻。第二条盟约说，尊重贤人，培养人才，用来表彰有德之人。第三条盟约说，尊重老人，爱护幼小，不要慢待宾客、旅客。第四条盟约说，士人的官职不可世代相传，公家职务不可兼任，选用士人一定要得当，不可擅自杀戮大夫。第五条盟约说，不可到处构筑堤防，不可阻止邻国来采购粮食，不可实行封赏而不告诉盟主。说，所有参与这次同盟的人，在订立盟约以后，恢复从前的友好关系。如今的诸侯都触犯了这五条禁令，因此说，如今的诸侯是五霸的罪人。助长君主的恶行，是小罪；逢迎君主的恶行，罪过就大了。如今的大夫都逢迎君主的恶行，因此说，如今的大夫，是诸侯的罪人。”
', NULL, '', 'indent', 1558090697, '5cde2344c8959c0068ef5ebc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642712, '孟子 · 第十二卷 · 告子下 · 第八节 ', NULL, 3, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '鲁欲使慎子为将军。孟子曰：“不教民而用之，谓之殃民。殃民者，不容于尧舜之世。一战胜齐，遂有南阳，然且不可。”
慎子勃然不悦曰：“此则滑厘所不识也。”
曰：“吾明告子。天子之地方千里；不千里，不足以待诸侯。诸侯之地方百里；不百里，不足以守宗庙之典籍。周公之封于鲁，为方百里也；地非不足，而俭于百里。太公之封于齐也，亦为方百里也；地非不足也，而俭于百里。今鲁方百里者五，子以为有王者作，则鲁在所损乎？在所益乎？徒取诸彼以与此，然且仁者不为，况于杀人以求之乎？君子之事君也，务引其君以当道，志于仁而已。”', '', '慎子：名滑厘，鲁国大臣，善于用兵。
殃：残害。
南阳：地名，即汶阳。在泰山西南，汶水之北，是春秋时期齐、鲁两国争夺的要地。
俭：少。
方百里者五：有五个方圆一百里的诸侯国那么大。
', '鲁国要让慎子做将军。孟子说：“不对百姓实行教化就使用他们作战，这叫残害百姓。残害百姓的人，在尧、舜那个时代是绝对不能容许的。打一次仗，战胜齐国，于是拥有南阳，这样尚且不可以——”
慎子勃然不高兴地说：“这可是我所不知道的。”
孟子说：“我明白地告诉你。天子的土地方圆千里；不够一千里的话，就不能够接待诸侯。诸侯的土地方圆百里；不够百里的话，就不能守住祖宗传下来的礼法制度。周公被封于鲁，方圆一百里；土地不是不够，可实际上少于一百里。太公被封于齐，也是方圆一百里；土地不是不够，可实际上少于一百里。如今鲁国有五个方圆一百里的诸侯国那么大，你认为如果有圣主明王兴起的话，那么鲁国的土地会处在被减损之列，还是被增加之列呢？不用兵力只是从那个国家拿来东西给予这个国家，仁人尚且不去做，何况用杀人的方式去求取土地呢？君子侍奉君主，应一心一意地引导君王走正路，用心于仁罢了。”
', NULL, '', 'indent', 1558090747, '5cde237943e78c0068915707', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642713, '孟子 · 第十二卷 · 告子下 · 第九节 ', NULL, 4, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“今之事君者曰：‘我能为君辟土地，充府库。’今之所谓良臣，古之所谓民贼也。君不乡道，不志于仁，而求富之，是富桀也。‘我能为君约与国，战必克。’今之所谓良臣，古之所谓民贼也。君不乡道，不志于仁，而求为之强战，是辅桀也。由今之道，无变今之俗，虽与之天下，不能一朝居也。”', '', '乡：同“向”。
约与国：邀约盟国。
', '孟子说：“如今侍奉君主的人都说：‘我能为您开辟土地，充实府库。’如今所谓的好大臣，就是古代所说的祸害百姓的人。君主不向往道德，不用心于仁，却想让他富足，这是使夏桀富足。‘我能替您邀集盟国，作战一定会取胜。’如今所谓的好大臣，就是古代所说的残害百姓的人。君主不向往道德，不用心于仁，却要替他尽力作战，这等于在辅佐夏桀。沿着今天的道路走下去，不改变今天的习俗，即使把天下交给他，他也是一天都坐不稳的。”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b4903b6a81d0c538d044f", "shortContent": " 儒学的核心是主张修身为本，由此不少人产生了一个错觉，以为儒家只关心个人的道德行为。其实修身为本只是要把一种最高的精神价值变成整个社会所有个体的自我意识和不竭的精神生命力，实际上他们心目中首要关切的是整个社会的精神价值取向，这也是贯穿《孟子》全书的主要论题。\n\n战国时期可以说是一个崇尚功利、功效至上的时代，为了争霸、兼并土地，或为了求生存而不断发生的残酷战争迫使统治者千方百计增强实力，这就是强调富...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558090793, '5cde23a76e9ba10068f25466', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642714, '孟子 · 第十二卷 · 告子下 · 第十节 ', NULL, 1, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '白圭曰：“吾欲二十而取一，何如？”
孟子曰：“子之道，貉道也。万室之国，一人陶，则可乎？”
曰：“不可，器不足用也。”
曰：“夫貉，五谷不生，惟黍生之。无城郭、宫室、宗庙、祭祀之礼，无诸侯币帛饔飧，无百官有司，故二十取一而足也。今居中国，去人伦，无君子，如之何其可也？陶以寡，且不可以为国，况无君子乎？欲轻之于尧舜之道者，大貉小貉也；欲重之于尧舜之道者，大桀小桀也。”', '', '白圭：名丹，字圭，魏惠王臣，善于筑堤防，修水利。
貉（mò）：同“貊”，古代泛指居于北方的民族。
黍：谷物名，子粒性黏。北方称之为黄米。
饔飧（yōng sūn）：熟食。饔，早餐；飧，晚餐。文中指用饮食款待客人的礼节。
去人伦：无君臣祭祀交际之礼。无君子：无百官有司。
', '白圭说：“我想把税率定为二十抽一，怎么样？”
孟子说：“你的办法是貉国实行的方法。假如一个国家有上万户人家，只有一个人制作陶器，那能行吗？”
回答说：“不行，陶器不够用。”
孟子说：“貊这个国家，各种谷物都不生长，只产糜子；没有城墙、房屋、祖庙、祭祀的礼仪，没有国家间的交往、互赠礼物和宴享，没有各种官吏，因此二十抽一就足够了。如今在中原国家，无君臣祭祀交际之礼，无百官有司，怎么能行呢？做陶器的太少，尚且不能够治理好国家，何况没有官吏呢？想要比尧、舜的税率还轻的，是大貊、小貊；想要比尧、舜的税率还重的，是大桀、小桀。”
', NULL, '', 'indent', 1558090833, '5cde23cd7b968a0073e341b1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642715, '孟子 · 第十二卷 · 告子下 · 第十一节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '白圭曰：“丹之治水也愈于禹。”孟子曰：“子过矣。禹之治水，水之道也。是故禹以四海为壑，今吾子以邻国为壑。水逆行，谓之洚水。洚水者，洪水也，仁人之所恶也。吾子过矣。”
', '', '壑：本指沟壑。文中指承受水患的地方。
水逆行：指下流壅塞，水倒流。洚（jiàng）水：大水泛滥。
', '白圭说：“我治理水患比大禹强。”
孟子说：“你错了。夏禹治理水患，是顺应水的本性而行，因此夏禹是使水流入四海。如今你治理水患是使水流到邻国那里去。水逆流行进叫做洚水。洚水，就是洪水，是仁人最厌恶的。你错了。”
', NULL, '', 'indent', 1558090867, '5cde23efc8959c0068ef6952', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642716, '孟子 · 第十二卷 · 告子下 · 第十二节 ', NULL, 9, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“君子不亮，恶乎执？”
', '', '亮：同“谅”，诚信。执：秉持。
', '孟子说：“君子不讲信用，拿什么待人处世呢？”
', NULL, '', 'indent', 1558090892, '5cde240a17b54d006805c173', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642717, '孟子 · 第十二卷 · 告子下 · 第十三节 ', NULL, 6, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '鲁欲使乐正子为政。孟子曰：“吾闻之，喜而不寐。”
公孙丑曰：“乐正子强乎？”曰：“否。”
“有知虑乎？”曰：“否。”
“多闻识乎？”曰：“否。”
“然则奚为喜而不寐？”曰：“其为人也好善。”
“好善足乎？”曰：“好善优于天下，而况鲁国乎？夫苟好善，则四海之内，皆将轻千里而来告之以善。夫苟不好善，则人将曰：‘訑訑，予既已知之矣。’訑訑之声音颜色，距人于千里之外。士止于千里之外，则谗谄面谀之人至矣。与谗谄面谀之人居，国欲治，可得乎？”', '', '好善：好纳善言。
优于天下：治天下而能应付自如。
轻千里：以千里之远为易行；轻，易。
訑訑（yí）：傲慢自满的样子。
距：同“拒”。
', '鲁国将要让乐正子执政。孟子说：“我听说这件事，高兴得睡不着觉。”
公孙丑说：“乐正子刚强吗？”
孟子回答说：“没有。”
“那他有智慧和谋略吗？”
孟子回答说：“不。”
“他见识很多吗？”
孟子回答说：“不。”
“既然这样，那您为什么高兴得睡不着呀？”
孟子回答说：“他这个人喜欢采纳善言。”
“喜欢吸纳善言就够了吗？”
孟子回答说：“喜欢吸纳善言，治理天下都能应付自如，何况是治理鲁国呢？一旦执政者喜欢吸纳善言，那么全天下的人都会不远千里地来把善言告诉他，一旦执政者不喜欢吸纳善言，人们就会学着他的样子说：‘嗯、嗯，我都已经知道了。’嗯嗯的声音脸色就能把人拒绝在千里之外。士人在千里以外止步，那么喜欢进谗言和当面阿谀奉承的人就会到来。同喜欢进谗言和当面阿谀奉承的人在一起相处，想要把国家治理好，办得到吗？”
', NULL, '', 'indent', 1558090953, '5cde24406e9ba10068f26113', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642767, '孟子 · 第十三卷 · 尽心上 · 第二十节 ', NULL, 23, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“君子有三乐，而王天下不与存焉。父母俱存，兄弟无故，一乐也。仰不愧于天，俯不怍于人，二乐也。得天下英才而教育之，三乐也。君子有三乐，而王天下不与存焉。”', '', '故：变故，如灾难、祸患、死亡、疾病等。
怍（zuò）：惭愧。
王天下不与存：再次强调“王天下”之事不在“三乐”之中，因为这不是一个等量级的问题。
', '孟子说：“君子有三种乐事，但用仁德统一天下并不在其中。父母都健在，兄弟没有灾祸，这是第一件乐事；抬头无愧于天，低头无愧于人，这是第二件乐事；得到天下的优秀人才而去教育他们，这是第三件乐事。君子有这三件乐事，而称王于天下并不在其中。”
', NULL, '', 'indent', 1558348725, '5ce21331c8959c00681e86d4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642718, '孟子 · 第十二卷 · 告子下 · 第十四节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '陈子曰：“古之君子何如则仕？”孟子曰：“所就三，所去三。迎之致敬以有礼，言将行其言也，则就之；礼貌未衰，言弗行也，则去之。其次，虽未行其言也，迎之致敬以有礼，则就之；礼貌衰，则去之。其下，朝不食，夕不食，饥饿不能出门户。君闻之曰：‘吾大者不能行其道，又不能从其言也，使饥饿于我土地，吾耻之。’周之，亦可受也，免死而已矣。”', '', '陈子：指陈臻，孟门弟子。
周：周济。
', '陈子问：“古代的君子要怎样才去做官？”
孟子说：“前去就职的情况有三种，自动离职的情况有三种。毕恭毕敬地以礼相迎；对他所说的话，打算去实行，便去就职；礼貌虽然没有衰减，但他所说的话，不能够得以实行，便离开。其次，虽然没有将他的言论付诸实践，但毕恭毕敬地以礼相迎，那么便就职；礼貌衰减，就离开。最次，从早到晚都吃不上饭，饿得走不出屋门，君主知道了，说：‘我从大的方面说不能推行他的主张，又不能听从他的进言，使他在我的国土上饿肚子，我为此感到羞耻。’于是周济他，若能这样，也可以接受，只为免于一死罢了。”
', NULL, '', 'indent', 1558090983, '5cde24656e9ba10068f262f4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642720, '孟子 · 第十二卷 · 告子下 · 第十六节 ', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“教亦多术矣，予不屑之教诲也者，是亦教诲之而已矣。”', '', '术：方法。
不屑：不值得，表示轻视。
', '孟子说：“教育的方法也有很多种呢，我认为不值得去教诲就不教诲他，这对他也是一种教诲呀。”
', NULL, '', 'indent', 1558091067, '5cde24b8c8959c0068ef7963', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642721, '孟子 · 第十三卷 · 尽心上 · 第一节 ', NULL, 16, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“尽其心者，知其性也。知其性，则知天矣。存其心，养其性，所以事天也。夭寿不贰，修身以俟之，所以立命也。”', '', '夭（yāo）：同“夭”，短命，早死。贰：怀疑。
', '孟子说：“充分发挥人的善良的本心，就是知晓了人的本性。知晓人的本性，就知晓天命了。保持人的本心，养护人的本性，这是侍奉上天的办法。生命的长短不必去疑虑，修养好自身，等待着天命就是了，这就是用以安身立命的方法。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf302d", "shortContent": "这段话孟子主要讲了心、性、天以及安身立命的问题。孟子的意思是说：“充分发挥善良的本心，就可以懂得人的本性了。懂得了人的本性，也就懂得天命了。”孟子把发挥本心看成是知人性、知天命的基础，这是因为他主张性本善，而本善之性就源自心先天具有的仁义礼智四端，性善也就是心善，修身实际上就是修心，因此了解本心、悟知本性，这就是所谓的明心见性。同时，孟子又认为知人性也就是知天命了，知天命就包含在知人性里。在孟子这...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b493e7f27182da3ee10a2", "shortContent": " 这部分是构造儒家人生哲学的基本框架，论述人们应当如何度过一个富有意义、成功而又愉快的人生，着重说明人们应当有怎样的人生追求，树立怎样的幸福观。为此孟子深刻地阐述了个人奋斗与个人命运的关系。\n\n孟子的人生哲学的理论基础是心性学说，他的心性论是对儒家哲学最重要的贡献之一，以至于后世的学者把他视为儒家心性之学的主要奠基者。本篇第一章提出的尽心、知性、知天的递进关系是他的心性学说的最高概括，包含了非常丰...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558091107, '5cde24e16e9ba10068f26b76', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642722, '孟子 · 第十三卷 · 尽心上 · 第二节 ', NULL, 8, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“莫非命也，顺受其正。是故知命者，不立乎岩墙之下。尽其道而死者，正命也。桎梏死者，非正命也。”', '', '岩墙：高而危的墙。
桎梏：古代束缚犯人的刑具。这里比喻因犯法而被处死。
', '孟子说：“没有什么不是命运决定的，但顺应规律去行事，就会得到正常的命运；因此，知晓天命的人不站在有倒塌危险的墙壁下。尽力行道而死的人，所受的是正常的命运，犯法而被处死的人，不是正常的命运。”
', NULL, '', 'indent', 1558091137, '5cde24fe17b54d006805d12f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642723, '孟子 · 第十三卷 · 尽心上 · 第三节 ', NULL, 10, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“求则得之，舍则失之，是求有益于得也，求在我者也。求之有道，得之有命，是求无益于得也，求在外者也。”
', '', '', '孟子说：“有些东西寻求就能得到，不寻求就会失去，这是有益于收获的寻求，因为所寻求的存在于我自身。寻求有一定的方法，能否得到却取决于命运，这是无益于收获的寻求，因为所寻求的存在于我自身以外。”
', NULL, '', 'indent', 1558091157, '5cde2513c8959c0068ef7ddc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642724, '孟子 · 第十三卷 · 尽心上 · 第四节 ', NULL, 4, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“万物皆备于我矣。反身而诚，乐莫大焉。强恕而行，求仁莫近焉。”
', '', '', '孟子说：“天地万物的根本原理都具备于我的本心之中了。反省自身发现自己是诚实的，这是最大的快乐。勉励自己依从推己及人的恕道行事，这是最近的求仁之路了。”
', NULL, '', 'indent', 1558091181, '5cde252b6e9ba10068f26fea', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642725, '孟子 · 第十三卷 · 尽心上 · 第五节 ', NULL, 13, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“行之而不著焉，习矣而不察焉，终身由之而不知其道者，众也。”
', '', '著：彻底明白。
', '孟子说：“做了却不知道为什么要这样做，习以为常却不知其所以然。终生都顺着这条道走，却不知道这是条什么道，在人群中这种人占多数。”
', NULL, '', 'indent', 1558091209, '5cde254730863b0069904a2d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642726, '孟子 · 第十三卷 · 尽心上 · 第六节 ', NULL, 9, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“人不可以无耻，无耻之耻，无耻矣。”
', '', '', '孟子说：“人不可以没有羞耻之心，不对无耻感到羞耻，就没有耻辱了。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf302e", "shortContent": "孟子的意思是说：“人不可以没有羞耻。不知羞耻的那种羞耻，就真是不知羞耻了。”他认为人最大的羞耻莫过于不知羞耻的羞耻。此外，他还说，“声闻过情，君子耻之。”（《离娄下》）出仕为官，“立乎人之本朝，而道不行，耻也。”（《万章下》）名声超过了实际，就有沽名钓誉之实；在朝为官，自己正义的主张得不到实现，就有在其位不谋其政之嫌，这些都是值得羞耻的事。可见，孟子的羞耻之心涉及道德、行为实践。\n\n孟子之所以推崇...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1558091227, '5cde255a7b968a0073e35993', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642727, '孟子 · 第十三卷 · 尽心上 · 第七节 ', NULL, 16, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“耻之于人大矣，为机变之巧者，无所用耻焉。不耻不若人，何若人有？”
', '', '机变：巧诈。
', '孟子说：“羞耻之心对于人来说是很重要的，行巧诈之事的人没有地方用得着羞耻之心。不把赶不上别人看作羞耻，怎么能赶上别人呢？”
本章仍论人当有羞耻之心。
', NULL, '', 'indent', 1558091252, '5cde25726e9ba10068f27319', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642728, '孟子 · 第十三卷 · 尽心上 · 第八节 ', NULL, 3, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“古之贤王好善而忘势，古之贤士何独不然？乐其道而忘人之势。故王公不致敬尽礼，则不得亟见之。见且由不得亟，而况得而臣之乎？”', '', '亟（jí）见：犹言想见就见；亟，急。
由：同“犹”。亟（qì）：屡次。
', '孟子说：“古代的贤明君主喜欢善行，就忘记了自身的权势，古代的贤明士人又何尝不是如此？他们喜欢行道却忘记了别人的权势。因此王公贵族不对他恭敬尽礼，就不能够想见就见。多见一面尚且不行，何况要把他当臣下呢？”
', NULL, '', 'indent', 1558091305, '5cde25a77b968a0073e35ec1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642729, '孟子 · 第十三卷 · 尽心上 · 第九节 ', NULL, 34, 271, 3, 3, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子谓宋勾践曰：“子好游乎？吾语子游。人知之，亦嚣嚣；人不知，亦嚣嚣。”
曰：“何如斯可以嚣嚣矣？”
曰：“尊德乐义，则可以嚣嚣矣。故士穷不失义，达不离道。穷不失义，故士得己焉；达不离道，故民不失望焉。古之人，得志，泽加于民；不得志，修身见于世。穷则独善其身，达则兼善天下。”', '', '宋勾践：姓宋，名勾践，孟子同时代人。
游：游说。
嚣嚣（xiāoxiāo）：自得无欲的样子。
得己：自得其乐。
', '孟子对宋勾践说：“你喜欢游说君主吗？我和你说说游说的事。别人了解你的用意，你要自得其乐；别人不了解你的用意，你也要自得其乐。”
宋勾践问道：“怎么做才能够自得其乐呢？”
孟子回答说：“尊崇德，喜欢义，就能够自得其乐了。因此，士人困窘时，不会失去义；得意时，不会背离道。困窘时不失去义，所以士就能够自得其乐；有地位的时候不背离道，因此百姓不会对他感到失望。古时的人，得志时施恩泽于百姓；不得志时，修养自身显现于世间。困窘时便独善其身；得志时便兼善天下。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf302f", "shortContent": "先秦哲学家大多立足于人生，偏重于对人性和社会的思考。因此，人生境遇问题便成了他们关注的焦点所在。人的境遇风云多变，古代的文人士大夫往往总是在“穷困”与“显达”这两种境遇中纠结徘徊。为了寻找到一种更合理更人性化的处世方式，先哲圣贤们针对这一问题进行了长期的思索和探讨。\n\n儒家注重独立的人格和高度的社会责任感，孟子的“穷达之道”就是“穷不失义，达不离道”。在儒家道德体系中，孟子极为看重“义”，认为“言...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1558091355, '5cde25d917b54d006805dbbd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642730, '孟子 · 第十三卷 · 尽心上 · 第十节 ', NULL, 11, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“待文王而后兴者，凡民也。若夫豪杰之士，虽无文王犹兴。”
', '', '', '孟子说：“等待周文王那样的贤王出来才奋发的，是普通的百姓。至于那些杰出的人才，即使没有周文王，也能够奋发。”
', NULL, '', 'indent', 1558091377, '5cde25ee6e9ba10068f278cc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642731, '孟子 · 第十三卷 · 尽心上 · 第十一节', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“附之以韩魏之家，如其自视欿然，则过人远矣。”', '', '附：增加。韩、魏：春秋时晋国的上卿韩氏和魏氏。
欿（kǎn）然：不自满的样子。
', '孟子说：“拿春秋时晋国韩、魏两家大臣的财富来增强他，如果他不因此而自满，那么这种人就大大超出常人。”
', NULL, '', 'indent', 1558091456, '5cde263ec8959c0068ef8db0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642732, '孟子 · 第十三卷 · 尽心上 · 第十二节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“以佚道使民，虽劳不怨。以生道杀民，虽死不怨杀者。”
', '', '', '孟子说：“本着让百姓安逸的原则去役使百姓，百姓虽然劳苦，但不会怨恨，本着让百姓生存的原则去杀人，被杀的人虽死，但不会怨恨杀他的人。”
', NULL, '', 'indent', 1558091485, '5cde265bc8959c0068ef8fd5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642760, '孟子 · 第十三卷 · 尽心上 · 第十三节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“霸者之民，欢虞如也；王者之民，皞皞如也。杀之而不怨，利之而不庸，民日迁善而不知为之者。夫君子所过者化，所存者神，上下与天地同流，岂曰小补之哉？”', '', '庸：酬功。
君子：此处的君子指圣人而言。
', '孟子说：“霸主的功业显著，百姓很快乐；圣王的功德浩荡，百姓怡然自得。他们即使被杀，也不会怨恨谁，得到恩惠，也不会酬谢谁，百姓一天天向善，却不知是谁使他们这样的。圣人所经过的地方，百姓会受到感化；圣人停留之处，会产生神奇的效果，在上与天，在下与地共同运转，难道只是小小的补益吗？”
', NULL, '', 'indent', 1558348487, '5ce2124543e78c0068c09572', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642761, '孟子 · 第十三卷 · 尽心上 · 第十四节 ', NULL, 9, 271, 1, 2, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“仁言不如仁声之入人深也，善政不如善教之得民也。善政民畏之；善教民爱之。善政得民财，善教得民心。”', '', '仁声：即仁闻，仁德的声誉。', '孟子说：“仁德的言语赶不上仁德的声誉深入人心，良好的政治赶不上良好的教化深入民心。良好的政治，百姓畏惧它；良好的教化，百姓热爱它。良好的政治可以得到百姓的财富，良好的教化可以得到百姓的心。”', NULL, '', 'indent', 1558348518, '5ce2126317b54d0068353c4f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642762, '孟子 · 第十三卷 · 尽心上 · 第十五节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“人之所不学而能者，其良能也；所不虑而知者，其良知也。孩提之童无不知爱其亲者，及其长也，无不知敬其兄也。亲亲，仁也；敬长，义也；无他，达之天下也。”
', '', '', '孟子说：“人不用学习就能做到的，那是良能；不用思考就能知道的，那是良知。两三岁的小孩没有不知道爱他父母的，等到他长大以后，没有不知道尊敬兄长的。亲爱父母就是仁；尊敬兄长就是义；这没有别的原因，这是由于仁义可以通行天下。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf3030", "shortContent": "孟子认为，人不经过学习就能做到的，是良能，不用思考就能知道的，是良知。这里的“良能”和“良知”其实指的就是人的天赋。不过，孟子注重的这个“天赋”跟我们日常所说的“天赋”不同，我们日常所说的“天赋”内容广泛，涉及社会领域的各个方面。而孟子所说的“天赋”是具有特定指向性的。\n\n孟子在这句话后面还举了一个例子：“孩提之童，无不知爱其亲者；及其长也，无不知敬其兄也。亲亲，仁也；敬长，义也。无他，达之天下也...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1558348539, '5ce212796e9ba1006821c034', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642763, '孟子 · 第十三卷 · 尽心上 · 第十六节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“舜之居深山之中，与木石居，与鹿豕游，其所以异于深山之野人者几希。及其闻一善言，见一善行，若决江河，沛然莫之能御也。”
', '', '', '孟子说：“舜居住在深山的时候，和树木，石头共处，和鹿、猪打交道，他和深山里的普通人不同的地方很少。等到他听到一句善良的言语，见到一次善良的行为，便受到触动，像打开缺口的江河，气势充沛，没有谁能阻挡得了。”
', NULL, '', 'indent', 1558348563, '5ce2128e17b54d0068353db6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642764, '孟子 · 第十三卷 · 尽心上 · 第十七节 ', NULL, 16, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“无为其所不为，无欲其所不欲，如此而已矣。”
', '', '', '孟子说：“不要做自己不该做的事，不想望不该想望的东西，这样就可以了。”
', NULL, '', 'indent', 1558348584, '5ce212a430863b0069bf2b7a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642765, '孟子 · 第十三卷 · 尽心上 · 第十八节', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“人之有德、慧、术、知者，恒存乎疢疾。独孤臣孽子，其操心也危，其虑患也深，故达。”
', '', '疢（chèn）疾：疾病，这里可理解为灾难。
孽子：即庶子。古代一夫多妻，不是嫡妻所生的孩子，称为庶子。危：不安。
', '孟子说：“人之所以能够拥有德行、智慧、技艺、知识，常常是由于灾患的缘故。只有那些孤立无援的大臣、地位卑贱的庶子，他们操心劳神总是不得安宁，忧虑灾患更深，所以通达事理。”
', NULL, '', 'indent', 1558348618, '5ce212c8c8959c00681e81e8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642768, '孟子 · 第十三卷 · 尽心上 · 第二十一节 ', NULL, 4, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“广土众民，君子欲之，所乐不存焉。中天下而立，定四海之民，君子乐之，所性不存焉。君子所性，虽大行不加焉，虽穷居不损焉，分定故也。君子所性，仁义礼智根于心，其生色也睟然，见于面，盎于背，施于四体，四体不言而喻。”', '', '大行：指理想通行于天下。
睟（suì）然：温润的样子。
盎（àng）：显现。施：推及，扩展。
', '孟子说：“拥有广大的土地，众多的人民，是君子所希望得到的，但他们的乐趣并不在此，居于天下的中央，安抚天下的百姓，君子以此为乐，但他们的本性不在于此。君子的本性，即使他的主张通行于天下，也并不因此而增加；即使困窘隐居，也不会因此而减损，因为他的本分已确定。君子的本性，仁义礼智已根植于内心，生发出来的神色是温润和顺的，流露在脸上，充盈在肩背，推及肢体，肢体的动作，不必言说，就能使人明了。”
', NULL, '', 'indent', 1558348760, '5ce21356c8959c00681e88a2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642769, '孟子 · 第十三卷 · 尽心上 · 第二十二节', NULL, 2, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“伯夷辟纣，居北海之滨，闻文王作兴，曰：‘盍归乎来！吾闻西伯善养老者。’太公辟纣，居东海之滨，闻文王作兴，曰：‘盍归乎来！吾闻西伯善养老者。’天下有善养老，则仁人以为己归矣。五亩之宅，树墙下以桑，匹妇蚕之，则老者足以衣帛矣。五母鸡，二母彘，无失其时，老者足以无失肉矣。百亩之田，匹夫耕之，八口之家足以无饥矣。所谓西伯善养老者，制其田里，教之树畜，导其妻子，使养其老。五十非帛不暖，七十非肉不饱。不暖不饱，谓之冻馁。文王之民，无冻馁之老者，此之谓也。”', '', '伯夷：人名，殷商时孤竹君之子。辟：逃避，躲避。
西伯：即周文王。
', '孟子说：“伯夷躲避商纣王，居住在北海边上，听说周文王兴起，说：‘何不归附西伯呢？我听说他善于奉养老人。’姜太公躲避商纣王，住在东海边上，听说周文王兴起，说：‘何不归附西伯呢？我听说他善于奉养老人。’天下有善于奉养老人的，仁人便把他作为自己的归宿。五亩的住宅，在墙下种上桑树，妇女靠它养蚕，老年人就能穿上丝绵做成的衣服了。五只母鸡，两头母猪，不错过繁殖期，老年人就能吃上肉了。百亩农田，男人去耕种，八口人的家庭就能吃饱了。所说的西伯善于奉养老人，就是指他制定了土地制度，教育百姓种植桑田，畜养牲畜，引导百姓的妻子儿女奉养老人。五十岁的人，没有丝绵穿就不觉得暖和，七十岁的人，没有肉吃就不觉得饱。穿不暖，吃不饱，就叫挨冻受饿。周文王的百姓没有挨冻受饿的老人，说的就是这个意思。”
', NULL, '', 'indent', 1558348793, '5ce213776e9ba1006821cd1a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642770, '孟子 · 第十三卷 · 尽心上 · 第二十三节 ', NULL, 6, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“易其田畴，薄其税敛，民可使富也。食之以时，用之以礼，财不可胜用也。民非水火不生活，昏暮叩人之门户，求水火，无弗与者，至足矣。圣人治天下，使有菽粟如水火。菽粟如水火，而民焉有不仁者乎？”', '', '易：治理。田畴：田地。
食之以时：按时节食用。
', '孟子说：“治理好田地，减轻税收，就可以使百姓富裕。按照时令安排饮食，按照礼的规定去消费，财物就会用之不竭。百姓没有水和火便无法生存，黄昏夜晚敲开别人家的门要水、火，没有不给的，因为水、火极其充足。圣人治理天下，应使粮食如同水、火那样多。粮食如果像水、火那样充足，百姓哪里会不讲仁爱呢？”
', NULL, '', 'indent', 1558348823, '5ce2139543e78c0068c0a4c9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642771, '孟子 · 第十三卷 · 尽心上 · 第二十四节 ', NULL, 36, 271, 3, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“孔子登东山而小鲁，登泰山而小天下。故观于海者难为水，游于圣人之门者难为言。观水有术，必观其澜。日月有明，容光必照焉。流水之为物也，不盈科不行；君子之志于道也，不成章不达。”', '', '东山：即蒙山，在今山东蒙阴南。
澜：大波浪。
容光：有空隙即能纳光，指幽暗的间隙。
科：同“窠”，坎，坑。
成章：古称乐曲终结为一章。此指事物达到一定阶段或程度。
', '孟子说：“孔子登上东山，就觉得鲁国变小了；登上了泰山，就觉得天下变小了。因此见过大海的人，难以对别的水感兴趣；在圣人门下游学的人，难以对别的言论感兴趣。观赏水有方法，一定要观赏它的波澜。太阳月亮都有光辉，极小的缝隙都能照得到。流水这种东西，不把小的坑洼灌满，就不会继续向前流动。君子有志于追求大道，不达到一定的程度不能通达。”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b496db1076d58637895e1", "shortContent": "在古代世界，关于人的精神生活的重要性、提升人的精神境界的方法的理论大多是由宗教哲学提供的，而在中国则主要包含于儒家的心性之学之中。关于自我完善和精神修养的问题，孟子形成了内容非常完备的理论体系，对理想的人格应有的道德观念和品质及其关系、修身养性的各种方法和途径及其关系，作出了十分细致的规定。这几章所涉及的主要是关于道德修养需标本兼治的问题。\n\n孟子一直有这样一个看法：普通人在道德修养上的通病是“不...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558348871, '5ce213bd6e9ba1006821d040', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642772, '孟子 · 第十三卷 · 尽心上 · 第二十五节 ', NULL, 8, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“鸡鸣而起，孳孳为善者，舜之徒也。鸡鸣而起，孳孳为利者，跖之徒也。欲知舜与跖之分，无他，利与善之间也。”', '', '孳孳（zī zī）：不懈怠的样子。
跖（zhí）：人名，春秋时期郑国的大盗。
间（jiàn）：不同。
', '孟子说：“鸡一叫就起来，孜孜不倦地做善事的，是舜一类的人；鸡一叫就起来，努力追求利益的，是跖一类的人。想要知道舜和跖的分别，没有别的，只是求利和求善的不同罢了。”
', NULL, '', 'indent', 1558348905, '5ce213e66e9ba1006821d29f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642773, '孟子 · 第十三卷 · 尽心上 · 第二十六节 ', NULL, 6, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“杨子取为我，拔一毛而利天下，不为也。墨子兼爱，摩顶放踵利天下，为之。子莫执中，执中为近之，执中无权，犹执一也。所恶执一者，为其贼道也，举一而废百也。”', '', '杨子：即杨朱，战国时期魏国人。其学说重在爱己，不为外物所累。
摩顶放踵（zhǒng）：从头顶到脚跟都磨伤，极言墨家为救天下而辛苦奔忙之状。
子莫：鲁国的贤人。执中：犹言折中。
', '孟子说：“杨子主张一切为自己，如果拔下一根汗毛能够有利于天下，他都不肯做。墨子主张兼爱，就是磨光头顶，走破脚跟，只要对天下人有利，他就去做。子莫主张中道而行。主张中道便差不多了。但是坚持中道缺乏变通，就是执着于一点。厌恶执着于一点的人，是因为它损害人道，抓住一点就不管其他了。”
', NULL, '', 'indent', 1558348938, '5ce2140843e78c0068c0aa2b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642777, '孟子 · 第十三卷 · 尽心上 · 第三十节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“尧舜，性之也；汤武，身之也；五霸，假之也。久假而不归，恶知其非有也。”
', '', '恶（wū）：如何。
', '孟子说：“尧、舜实行仁义，是本性使然；汤、武实行仁义，是身体力行；五霸实行仁义，是假借名义。然而，长时间假借不还，怎么能知道他不是真的拥有了仁义呢？”
', NULL, '', 'indent', 1558349062, '5ce214846e9ba1006821da16', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642778, '孟子 · 第十三卷 · 尽心上 · 第三十一节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '公孙丑曰：“伊尹曰：‘予不狎于不顺。’放太甲于桐，民大悦。太甲贤。又反之，民大悦。贤者之为人臣也，其君不贤，则固可放与？”
孟子曰：“有伊尹之志，则可；无伊尹之志，则篡也。”', '', '伊尹：人名，商汤之臣，曾助商汤讨伐夏桀。
狎（xiá）：亲近。放太甲于桐：事见卷九第六章。
', '公孙丑说：“伊尹说：‘我不亲近违背礼义道德的人，因而把太甲放逐到桐邑，百姓十分高兴。太甲变贤明了，又让他返回来做君主，百姓十分高兴。’贤人做臣子，如果他的君主不贤德，本来就可以放逐的吗？”
孟子说：“如果有伊尹那样的心志便可；没有伊尹那样的心志，就是篡位了。”
', NULL, '', 'indent', 1558349099, '5ce214a8eaa37500673322ae', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642779, '孟子 · 第十三卷 · 尽心上 · 第三十二节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '公孙丑曰：“《诗》曰：‘不素餐兮。’君子之不耕而食，何也？”
孟子曰：“君子居是国也，其君用之，则安富尊荣；其子弟从之，则孝悌忠信。‘不素餐兮’，孰大于是？”
', '', '诗句见《诗经·魏风·伐檀》。
', '公孙丑说：“《诗经》说：‘不白吃饭啊。’君子不耕种却可得食，这是为什么？”
孟子说：“君子居住在一个国家，国君任用他，这个国家便会安宁、富足、尊贵、荣耀；少年子弟追随他，便会孝顺父母，敬爱兄长，忠实守信。‘不白吃饭啊’，还有比这更大的贡献吗？”
', NULL, '', 'indent', 1558349133, '5ce214c46e9ba1006821ddf3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642780, '孟子 · 第十三卷 · 尽心上 · 第三十三节 ', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '王子垫问曰：“士何事？”孟子曰：“尚志。”曰：“何谓尚志？”
曰：“仁义而已矣。杀一无罪，非仁也；非其有而取之，非义也。居恶在？仁是也；路恶在？义是也。居仁由义，大人之事备矣。”', '', '王子垫（diàn）：齐王之子，名垫。
', '王子垫问道：“士应该做什么呢？”
孟子说：“士要使自己的志向高尚。”
王子垫问：“使志向高尚是什么意思？”
孟子说：“行仁义就是了。杀死一个没罪的人就是不仁；不是自己的东西却强行拿来就是不义。居所在哪里？仁就是。道路在哪里？义就是。居住于仁，行走由义，大人所做的事就齐备了。”
', NULL, '', 'indent', 1558349171, '5ce214f17b968a0073123e41', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642781, '孟子 · 第十三卷 · 尽心上 · 第三十四节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“仲子，不义与之齐国而弗受，人皆信之，是舍箪食豆羹之义也。人莫大焉亡亲戚、君臣、上下。以其小者信其大者，奚可哉？”', '', '仲子：即陈仲子，孟门弟子。详见卷六第十章。
箪（dān）：盛饭的竹器。
焉：犹“于”。亡：无。
', '孟子说：“陈仲子，假如不合道义地把齐国交给他，他是不会接受的，别人都相信他这点，但这只是舍弃一筐饭、一碗汤的义。人的罪过没有比不讲父兄君臣尊卑关系更大的了。因为他在小事上的节义，而去相信他在大事上的节义，怎么行呢？”
', NULL, '', 'indent', 1558349214, '5ce2151cc8959c00681e9e40', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642782, '孟子 · 第十三卷 · 尽心上 · 第三十五节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '桃应问曰：“舜为天子，皋陶为士，瞽瞍杀人，则如之何？”孟子曰：“执之而已矣。”“然则舜不禁与？”
曰：“夫舜恶得而禁之？夫有所受之也。”
“然则舜如之何？”
曰：“舜视弃天下，犹弃敝蹝也。窃负而逃，遵海滨而处，终身䜣然，乐而忘天下。”', '', '桃应：孟子弟子。
士：法官。皋陶：传说为舜的大臣，掌管刑狱之事。瞽瞍（gǔ sǒu），此指舜的父亲。
蹝（xǐ）：没有后跟的鞋子，一说草鞋。
䜣（xīn）：同“欣”，快乐。
', '桃应问道：“舜做天子，皋陶当法官，如果瞽瞍杀了人，那该怎么办呢？”
孟子说：“把他抓起来就是了。”
“那么舜不去制止吗？”
孟子回答说：“舜怎么能去制止呢？皋陶抓人是有依据的。”
“那么舜该怎么办？”
孟子回答说：“舜把抛弃天子的位置看得如同丢弃破鞋。他会偷偷地背上父亲逃跑，沿着海边住下来，一生都高高兴兴的，快乐得忘掉了天下。”
', NULL, '', 'indent', 1558349267, '5ce2154f6e9ba1006821e366', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642783, '孟子 · 第十三卷 · 尽心上 · 第三十六节 ', NULL, 2, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子自范之齐，望见齐王之子。喟然叹曰：“居移气，养移体，大哉居乎！夫非尽人之子与？”
孟子曰：“王子宫室、车马、衣服多与人同，而王子若彼者，其居使之然也；况居天下之广居者乎？鲁君之宋，呼于垤泽之门。守者曰：‘此非吾君也，何其声之似我君也？’此无他，居相似也。”', '', '范：古地名，在今山东莘县境内。齐王之子：指齐宣王，尚在为其父守孝。
广居：指“仁”。
垤（dié）泽之门：宋国都邑东南门。
', '孟子从范邑到齐国都城，远远地看见齐王的儿子，长叹一声说：“居处环境改变气质，所得奉养改变体质，居处环境真是太重要了。他不同样都是人的儿子吗，为什么显得那么特别？”
孟子说：“王子的住所、车马和衣服大多和别人相同，而王子却那样与众不同，就是因为他所居住的环境使他这样的。何况居住在‘仁’这个天下最宽广住所中的人呢？鲁国的国君到宋国去，在宋国的东南城门下喊话。守城人说：‘这个人不是我们的国君，为什么他的声音和我们国君这样相似呢？’这没有别的原因，是由于居处环境相似罢了。”
', NULL, '', 'indent', 1558349319, '5ce21585c8959c00681ea38a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642784, '孟子 · 第十三卷 · 尽心上 · 第三十七节 ', NULL, 8, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“食而弗爱，豕交之也；爱而不敬，兽畜之也。恭敬者，币之未将者也。恭敬而无实，君子不可虚拘。”', '', '币：古代以束帛为祭祀或馈赠的礼物，叫做“币”。后来称其他聘享的礼物，如车、马、玉等也叫“币”。将：送。
', '孟子说：“只给吃的而不爱护，等于在养猪；爱护却不敬重，等于在畜养牲畜。恭敬之心，应该是在进出礼物之前就有的。只有表面的恭敬，而并非实心实意，君子便不可以被虚假的礼节所束缚。”
', NULL, '', 'indent', 1558349359, '5ce215a4eaa3750067332de6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642785, '孟子 · 第十三卷 · 尽心上 · 第三十八节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“形色，天性也；惟圣人然后可以践形。”
', '', '践形：体现上天赋予人的品质；践，同“善”，完善之意。
', '孟子说：“人的身体容貌是与生俱来的；只有圣人才能够通过修养而无愧于这一天赋。”
', NULL, '', 'indent', 1558349386, '5ce215c830863b0069bf57c5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642786, '孟子 · 第十三卷 · 尽心上 · 第三十九节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '齐宣王欲短丧。公孙丑曰：“为期之丧，犹愈于已乎？”
孟子曰：“是犹或紾其兄之臂，子谓之姑徐徐云尔，亦教之孝弟而已矣。”王子有其母死者，其傅为之请数月之丧。公孙丑曰：“若此者，何如也？”
曰：“是欲终之而不可得也。虽加一日愈于已，谓夫莫之禁而弗为者也。', '', '丧：孔子认为，子为父母、臣为君主守丧三年，为天下之通例。胡适先生曾考证，这可能只是东部今山东一带的习俗。
期（jī）：丧服制度，期服的简称，指服丧一年。
“王子有其母”两句：按照古代丧礼规定，王子母亲死后，因父亲尚在，不能为母服三年丧，甚至无服。母亲下葬前，只穿麻衣，下葬后脱掉。
', '齐宣王想要缩短服丧时间。公孙丑说：“父母去世的话，服一年丧，不是比不服丧好吗？”
孟子说：“这就像有人扭他哥哥的胳膊，你对他说姑且慢慢地拧，这不是个办法，只是教导他孝敬父母兄长罢了。”
有个死了生母的王子，他的师傅替他请求守几个月的丧。公孙丑说：“像这种情况该怎么办？”
孟子说：“这个王子是想服完三年丧却无法做到。即使多服一天也比不服好，是对那些没人禁止他，而自己不愿服丧的人说的。”
', NULL, '', 'indent', 1558349450, '5ce21608c8959c00681ea963', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642787, '孟子 · 第十三卷 · 尽心上 · 第四十节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“君子之所以教者五：有如时雨化之者，有成德者，有达财者，有答问者，有私淑艾者。此五者，君子之所以教也。”', '', '私淑艾（yì）：私下拾取。文中指私下里学习。淑，通“叔”，拾取，获益。艾，通“刈”，收获。
', '孟子说：“君子实施教化的方式有五种：有像及时雨一样滋润万物的，有帮助成就德行的，有培养才干的，有解答疑问的，有以学识风范感化他人使之成为私淑弟子的。这五种就是君子所用来实行教化的方法。”
', NULL, '', 'indent', 1558349480, '5ce21626c8959c00681eaab3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642788, '孟子 · 第十三卷 · 尽心上 · 第四十一节 ', NULL, 10, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '公孙丑曰：“道则高矣，美矣，宜若登天然，似不可及也；何不使彼为可几及而日孳孳也？”
孟子曰：“大匠不为拙工改废绳墨，羿不为拙射变其彀率。君子引而不发，跃如也。中道而立，能者从之。”
', '', '羿：古代传说中的人物，善射。彀（gòu）率：弓弩张开的程度。
', '公孙丑说：“道的确是很高、很美，就像登天一样，似乎是不可企及的；为何不让道变成能够有希望达到的东西，从而让人们每天都努力追求呢？”
孟子说：“高明的木匠不会为手艺拙劣的木工改变或废弃规矩，羿不会为技艺拙劣的射手而改变他拉弓的标准。君子教导别人正如射手拉满弓，但却不把箭射出去，做出跃跃欲试的样子。他站在正确的道路上，有才能的人就会追随他。”
', NULL, '', 'indent', 1558349523, '5ce2165030863b0069bf5e3c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642789, '孟子 · 第十三卷 · 尽心上 · 第四十二节 ', NULL, 12, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“天下有道，以道殉身；天下无道，以身殉道；未闻以道殉乎人者也。”', '', '', '孟子说：“天下政治清明，就终身行道；天下统治黑暗，就为道献身；还没听说过牺牲道来迎合人的。”', NULL, '', 'indent', 1558349553, '5ce2166f7b968a0073124da6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642790, '孟子 · 第十三卷 · 尽心上 · 第四十三节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '公都子曰：“滕更之在门也，若在所礼，而不答，何也？”
孟子曰：“挟贵而问，挟贤而问，挟长而问，挟有勋劳而问，挟故而问，皆所不答也。滕更有二焉。”
', '', '滕更：滕国君主的弟弟，孟子弟子。
', '公都子说：“滕更在您的门下时，似乎应属于您以礼相待的人，可您却不解答他的问题，这是为什么呢？”
孟子说：“依仗自己地位高贵来发问，依仗自己贤能来发问，依仗自己年纪大来发问，依仗自己有功劳来发问，依仗自己有老交情来发问，都属于我不回答的范畴。滕更占了其中的两条。”
', NULL, '', 'indent', 1558349589, '5ce2169217b54d00683573c7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642791, '孟子 · 第十三卷 · 尽心上 · 第四十四节 ', NULL, 4, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“于不可已而已者，无所不已。于所厚者薄，无所不薄也。其进锐者，其退速。”', '', '', '孟子说：“对于不该停止的事却停止了，那么就没什么不可以停止的了。对于本应厚待的人而薄待，那么没有谁不可薄待了。前进得太猛的人，后退得也就快。”
', NULL, '', 'indent', 1558349630, '5ce216bc6e9ba1006821f363', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642792, '孟子 · 第十三卷 · 尽心上 · 第四十五节 ', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“君子之于物也，爱之而弗仁；于民也，仁之而弗亲。亲亲而仁民，仁民而爱物。”
', '', '', '孟子说：“君子对于万物，爱护它，但不必以仁德之心对它；对于百姓，施仁给他而不必亲爱他。君子热爱亲人，进而施仁德于百姓；施仁德于百姓，进而爱惜万物。”
', NULL, '', 'indent', 1558349653, '5ce216d27b968a007312524c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642793, '孟子 · 第十三卷 · 尽心上 · 第四十六节 ', NULL, 3, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“知者无不知也，当务之为急；仁者无不爱也，急亲贤之为务。尧舜之知而不遍物，急先务也；尧舜之仁不遍爱人，急亲贤也。不能三年之丧，而缌小功之察；放饭流歠，而问无齿决，是之谓不知务。”', '', '缌（sī）：麻布之细疏者，文中指缌麻，是丧服五服中最轻的一种，也称“缌衰”，服期为三个月。小功：古代丧服名，五服之一，用较粗的熟布制成，服期为五个月。
放饭：大口吃饭。流歠（chuò）：大口喝汤；歠，饮。齿决：用牙齿啃断东西。
', '孟子说：“智者没有什么不想知道的，但急于知道当前该做的紧要事情；仁者没有什么不爱惜的，但急于先爱亲人和贤人。尧、舜的智慧不能遍知所有的事物，是因为他急于去做眼前的大事，尧、舜的仁德不能遍爱所有的人，是因为他急于去爱亲人和贤人。不能够实行三年的丧礼，却仔细地讲求缌麻三月，小功五月的丧礼；在尊长面前进餐，大口吃饭，大口喝汤，却讲求不用牙齿咬断干肉，这就叫不识大体。”
', NULL, '', 'indent', 1558349702, '5ce217046e9ba1006821f60c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642825, '孟子 · 第十四卷 · 尽心下 · 第二十八节 ', NULL, 9, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“诸侯之宝三：土地、人民、政事。宝珠玉者，殃必及身。”
', '', '政事：指仁政。
', '孟子说：“诸侯的宝物有三种：土地、百姓和仁政。把珍珠、美玉当作宝物的，灾祸一定会降临到他身上。”
', NULL, '', 'indent', 1558433553, '5ce35e8feaa37500681ab3a8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642794, '孟子 · 第十四卷 · 尽心下 · 第一节 ', NULL, 8, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“不仁哉，梁惠王也！仁者以其所爱及其所不爱，不仁者以其所不爱及其所爱。”公孙丑曰：“何谓也？”
“梁惠王以土地之故，糜烂其民而战之，大败，将复之，恐不能胜，故驱其所爱子弟以殉之，是之谓以其所不爱及其所爱也。”', '', '糜烂：牺牲。
', '孟子说：“梁惠王实在是不仁德啊！仁人把施与他所爱的人的仁德推及他所不爱的人身上；不仁者把加给他所不爱的人的祸害推及他所爱的人身上。”
公孙丑说：“这话是什么意思？”
“梁惠王因为土地的缘故，不惜牺牲百姓的血肉之躯去作战，遭到惨重的失败。想要收复失地，唯恐不能战胜敌人，因此又驱使他所喜爱的子弟去作战送死，这就是把加给不爱的人的祸害推及所爱的人的身上。”
', NULL, '', 'indent', 1558349750, '5ce2173317b54d0068357e2b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642795, '孟子 · 第十四卷 · 尽心下 · 第二节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“春秋无义战。彼善于此，则有之矣。征者，上伐下也。敌国不相征也。”
', '', '', '孟子说：“春秋时代没有正义的战争。那一方比这一方好点，那是有的。‘征’的意思是上级讨伐下级，同等级别的国家是不互相征讨的。”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b499aa5f1e74f95e9877a", "shortContent": " 这一部分所涉及的论题非常广泛，其中有些是高度概括的，是对孟子思想提纲挈领式的表达，可展开的空间非常广阔。如十四章孟子大胆地提出：“民为贵，社稷次之，君为轻。”这是对法家加强君主权力的理论的批判，更是对传统的尊君观念的一个挑战。这一论断虽然不是要把社会等级的尊卑次序和政治地位加以颠倒，但是从根本上否定了君权的神圣，肯定了人民是历史的主体，从中我们可以看到人民主权论的萌芽。“得乎丘民而为天子”之说表...", "authors": ["徐克谦", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558349772, '5ce21749eaa37500673340e5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642796, '孟子 · 第十四卷 · 尽心下 · 第三节 ', NULL, 7, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“尽信书，则不如无书。吾于武成，取二三策而已矣。仁人无敌于天下。以至仁伐至不仁，而何其血之流杵也？”', '', '《书》：指《尚书》。
《武成》：《尚书·周书》篇名，叙述了周武王伐纣之事。今存《武成》是伪古文。策：编成的竹简。
杵：舂杵，舂米用的棒槌。一说形状像杵的兵器。
', '孟子说：“完全相信《尚书》，还不如没有《尚书》。我对于《武成》这一篇，只取其中的两三页罢了。仁人天下无敌，凭借周武王这样最仁的人去讨伐商纣这样最不仁的人，怎么会让鲜血流淌得足以把杵都漂起来呢？”
', NULL, '', 'indent', 1558349801, '5ce21767c8959c00681eb848', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642797, '孟子 · 第十四卷 · 尽心下 · 第四节', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“有人曰：‘我善为陈，我善为战。’大罪也。国君好仁，天下无敌焉。南面而征北狄怨，东面而征西夷怨。曰：‘奚为后我？’武王之伐殷也，革车三百两，虎贲三千人。王曰：‘无畏！宁尔也，非敌百姓也。’若崩厥角稽首。征之为言正也，各欲正己也，焉用战？”', '', '陈：同“阵”。
革车：兵车。两：同“辆”。虎贲（bēn）：勇士。
若崩厥角稽首：“厥角稽首若崩”之倒文。厥角：这里指以额触地。厥，同“蹶”，顿。角，额角。稽（qǐ）首：古时的跪拜礼，叩头于地。
', '孟子说：“有人说：‘我善于布阵，我善于作战。’这是大罪过。国君喜好仁，就会天下无敌。商汤向南方征讨，北方的民族就会埋怨，向东方去征讨，西方的民族就会埋怨，说：‘为什么不先来我们这儿？’周武王讨伐殷商的时候，战车三百辆，勇士三千人。武王对殷商的百姓说：‘不要害怕！我是来让你们得到安宁的，不是和你们为敌的。’殷商的百姓都把额角触地叩头，发出的声响如同山陵崩塌。‘征’的意思是‘正’，如果各个国家都端正自身，哪里用得着作战呢？”
', NULL, '', 'indent', 1558349841, '5ce2178f7b968a0073125a03', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642798, '孟子 · 第十四卷 · 尽心下 · 第五节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“梓匠、轮舆能与人规矩，不能使人巧。”
', '', '梓匠：木工。梓人造器具；匠人造房子。轮舆：车匠。轮人制车轮；舆人制车厢。
', '孟子说：“木匠和车匠能够把圆规、曲尺的使用方法传授给别人，却不能使人一定技艺高超。”
', NULL, '', 'indent', 1558349899, '5ce217c8c8959c00681ebc8b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642799, '孟子 · 第十四卷 · 尽心下 · 第六节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“舜之饭糗茹草也，若将终身焉；及其为天子也，被袗衣，鼓琴，二女果，若固有之。”', '', '糗（qiǔ）：干粮。茹：吃。
袗（zhěn）衣：绣有文采的华贵衣服，指天子所穿的盛服。
二女：尧的两个女儿娥皇、女英。果（wǒ）：同“婐”，女侍。
', '孟子说：“当舜啃干粮吃野菜的时候，好像一生就将这样度过；等他做了天子后，穿着有纹饰的华贵衣服，弹着琴，尧的两个女儿服侍着，又好像原本就拥有了这一切。”
', NULL, '', 'indent', 1558349927, '5ce217e517b54d00683585c7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642804, '孟子 · 第十四卷 · 尽心下 · 第七节', NULL, 7, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“吾今而后知杀人亲之重也：杀人之父，人亦杀其父；杀人之兄，人亦杀其兄。然则非自杀之也，一间耳。”', '', '一间：指相距很近；间，隔。
', '孟子说：“我从今以后才知道杀死别人亲人的严重性：杀死别人的父亲，别人也会杀死他的父亲；杀死别人的哥哥，别人也会杀死他的哥哥。那么，虽然父亲和哥哥不是自己杀死的，但也相差无几了。”
', NULL, '', 'indent', 1558432803, '5ce35b9ea673f50068c2e5a1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642805, '孟子 · 第十四卷 · 尽心下 · 第八节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“古之为关也，将以御暴；今之为关也，将以为暴。”
', '', '', '孟子说：“古时候设立关卡，是打算用来抵御强暴的；如今设立关卡，却是打算实行强暴的。”
', NULL, '', 'indent', 1558432826, '5ce35bb7a673f50068c2e72e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642826, '孟子 · 第十四卷 · 尽心下 · 第二十九节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '盆成括仕于齐，孟子曰：“死矣盆成括！”
盆成括见杀，门人问曰：“夫子何以知其将见杀？”
曰：“其为人也小有才，未闻君子之大道也，则足以杀其躯而已矣。”
', '', '盆成括：姓盆成，名括。曾为孟子弟子，后去齐国做官。
', '盆成括在齐国做官，孟子说：“盆成括要死了。”
盆成括被杀，学生问道：“您怎么知道他会被杀？”
孟子回答说：“盆成括这个人有点小才智，但还不知道做君子的大道理，这就足以招致杀身之祸了。”
', NULL, '', 'indent', 1558433581, '5ce35eaa6e9ba10069a4e2f9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642806, '孟子 · 第十四卷 · 尽心下 · 第九节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“身不行道，不行于妻子。使人不以道，不能行于妻子。”
', '', '', '孟子说：“本人不践行大道，大道在妻子、儿女身上都行不通，更不要说对别人了。使唤别人不遵道而行，那么连妻子、儿女都使唤不了，更不要说使唤别人了。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf3031", "shortContent": "孟子这是说的“道”，主要是指儒家的一套伦理道德规范，包含仁、义、礼、智、诚以及孝悌、忠信等范畴。在孟子看来，推行道的前提是自己身体力行，否则，道在妻子身上都行不通；使唤别人也要合于道，否则，就连使唤自己的妻子都不可能。\n\n纵观整个古代社会，不难发现这是一个明显的以男性为主导的社会形态。男子的品德、见识和能力的高低直接决定着这个国家发展的潜力和前景。儒家一向倡导积极进仕，建功立业，并把个人的成长道路...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1558432853, '5ce35bd130863b00699ef914', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642807, '孟子 · 第十四卷 · 尽心下 · 第十节 ', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“周于利者凶年不能杀，周于德者邪世不能乱。”
', '', '周：充足。杀：窘困。
', '孟子说：“财富充足的人，荒年不能让他窘困；德行深厚的人，乱世也不能让他迷惑。”
', NULL, '', 'indent', 1558432880, '5ce35bed7b968a007308479f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642808, '孟子 · 第十四卷 · 尽心下 · 第十一节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“好名之人，能让千乘之国；苟非其人，箪食豆羹见于色。”
', '', '', '孟子说：“喜好名声的人能够谦让拥有千辆兵车的国家；如果他本不是能够轻视富贵之人，即使让出一筐饭、一碗汤，他都会流露出不悦的神情。”
', NULL, '', 'indent', 1558432916, '5ce35c0c6e9ba10069a4c49a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642809, '孟子 · 第十四卷 · 尽心下 · 第十二节 ', NULL, 6, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“不信仁贤，则国空虚；无礼义，则上下乱；无政事，则财用不足。”
', '', '政事：清明的政治；政，正。
', '孟子说：“不信任仁德贤能之人（就没有贤能之人为国家效力），那么国家就会空虚；不讲礼义，那么上下级的关系就会混乱；不推行清明的政治，那么国家的财源用度就会入不敷出。”
', NULL, '', 'indent', 1558432943, '5ce35c2c30863b00699efe07', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642810, '孟子 · 第十四卷 · 尽心下 · 第十三节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“不仁而得国者，有之矣；不仁而得天下者，未之有也。”
', '', '', '孟子说：“不实行仁德却能得到一个国家的，有这样的事；不实行仁德，却能得到天下，这样的事不曾有过。”
', NULL, '', 'indent', 1558432964, '5ce35c4230863b00699eff29', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642811, '孟子 · 第十四卷 · 尽心下 · 第十四节 ', NULL, 5, 271, 1, 2, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“民为贵，社稷次之，君为轻。是故得乎丘民而为天子，得乎天子为诸侯，得乎诸侯为大夫。诸侯危社稷，则变置，牺牲既成，粢盛既洁，祭祀以时，然而旱干水溢，则变置社稷。”
', '', '社稷：此处指本义，土神、谷神。有时引申为国家。
丘民：众民；丘，众。
牺牲：供祭祀用的纯色牲畜。粢盛（zīchéng）：盛在祭器中的黍稷等。
', '孟子说：“老百姓最重要，土神、谷神次之，君主为轻。因此得到老百姓的拥护，就可以做天子，得到天子的赏识就可以做诸侯；得到诸侯的赏识就可以做大夫。如果诸侯危害国家，那么就改立诸侯。牺牲已经肥壮，祭品已经洁净，祭祀也按时进行，然而依旧发生旱灾水灾，那么就要改立土神、谷神。”
', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf3032", "shortContent": "“民本”思想是中国古代政治思想的精华。它源起于先秦，对历朝历代的政治、军事乃至思想文化都有着重大的影响。在先秦，孟子是大力倡导民本思想的第一人。\n\n民贵君轻思想是孟子思想体系的重要组成部分。孟子非常重视人民的力量，他认为“天时不如地利，地利不如人和”，“得其民，斯得天下矣”，“得乎丘民而为天子”。孟子深刻地认识到，百姓的支持是国家兴衰存亡的关键，统治者只有赢得民心才能赢得天下。这也是孟子宣扬“仁政...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1558433001, '5ce35c6717b54d006cf3408b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642812, '孟子 · 第十四卷 · 尽心下 · 第十五节', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“圣人，百世之师也，伯夷、柳下惠是也。故闻伯夷之风者，顽夫廉，懦夫有立志；闻柳下惠之风者，薄夫敦，鄙夫宽。奋乎百世之上，百世之下，闻者莫不兴起也。非圣人而能若是乎？而况于亲炙之者乎？”
', '', '顽：贪婪。
鄙：质朴，鄙陋。
亲炙：直接受到熏陶；炙，熏烤。
', '孟子说：“圣人是百代后人的老师，伯夷、柳下惠就是这样的人。因此听到伯夷的节操的，贪婪的人也会变得清廉，懦弱的人也会有自立的志向；听到柳下惠的节操的，鄙陋浅薄的人也会变得敦厚，气量狭小的人也会变得大度。他们在百代以前奋发，百代以后，听到他们的事情的人，没有不为之振作的。不是圣人能像这样有感召力吗？更何况曾经亲自接受过圣人熏陶的人呢？”
', NULL, '', 'indent', 1558433043, '5ce35c90c8959c0069b9b334', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642813, '孟子 · 第十四卷 · 尽心下 · 第十六节 ', NULL, 2, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“仁也者，人也。合而言之，道也。”
', '', '', '孟子说：“‘仁’的意思就是‘人’。‘仁’和‘人’的意思合起来说，就是‘道’。”
', NULL, '', 'indent', 1558433072, '5ce35cadeaa37500681a9f0c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642814, '孟子 · 第十四卷 · 尽心下 · 第十七节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“孔子之去鲁，曰：‘迟迟吾行也’，去父母国之道也。去齐，接淅而行，去他国之道也。”
', '', '接淅：把正在淘洗的大米滤干，比喻行色匆忙；淅，淘米。
', '孟子说：“孔子离开鲁国的时候，说‘我们慢慢地走吧’，这是离开祖国的态度。离开齐国的时候，把淘完的米捞出来，来不及把它做熟就出发了，这是离开别国的态度。”
', NULL, '', 'indent', 1558433105, '5ce35cce6e9ba10069a4ced8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642815, '孟子 · 第十四卷 · 尽心下 · 第十八节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“君子之厄于陈蔡之间，无上下之交也。” ', '', '君子：指孔子。
厄（è）：受困。
', '孟子说：“孔子被围困在陈国、蔡国之间，是因为和两个国家的君臣都没有交往的缘故。”
', NULL, '', 'indent', 1558433135, '5ce35cebeaa37500681aa19d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642816, '孟子 · 第十四卷 · 尽心下 · 第十九节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '貉稽曰：“稽大不理于口。”
孟子曰：“无伤也。士憎兹多口。诗云：‘忧心悄悄，愠于群小。’孔子也。‘肆不殄厥愠，亦不陨厥问。’文王也。”', '', '貉（mò）稽：人名。姓貉，名稽。
理：和顺。
“忧心”两句：见《诗经·邶风·柏舟》。悄悄，忧愁的样子。愠，恼怒。
“肆不殄”句：见《诗经·大雅·绵》。肆，故，既然。殄（tiǎn），灭尽。厥，代词，其。问（wèn），通“闻”，声誉。
', '貉稽说：“我的口碑很差。”
孟子说：“没有关系。士人厌恶这种多嘴多舌。《诗经》说过：‘愁思重重压在心，小人视我眼中钉。’孔子是这样的人。‘不能消灭别人的怨恨，也不要失去自己的声誉。’文王是这样的人。”
', NULL, '', 'indent', 1558433203, '5ce35d316e9ba10069a4d31a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642817, '孟子 · 第十四卷 · 尽心下 · 第二十节 ', NULL, 14, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“贤者以其昭昭，使人昭昭；今以其昏昏，使人昭昭。”
', '', '昭昭：明白。
', '孟子说：“贤明的人以自己的清楚明白，使他人清楚明白；如今的人却以自己的模模糊糊，想使他人清楚明白。”
', NULL, '', 'indent', 1558433233, '5ce35d4eeaa37500681aa5e3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642818, '孟子 · 第十四卷 · 尽心下 · 第二十一节 ', NULL, 7, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子谓高子曰：“山径之蹊间，介然用之而成路。为间不用，则茅塞之矣。今茅塞子之心矣。”', '', '径：同“陉”，山坡。蹊：小路。间：狭窄。
介然：用心专一的样子。
为间：隔段儿时间。
', '孟子对高子说：“山坡上的小路很窄，专心致志地去走，然后便变成了路；如果隔了段时间不去走，就又会被茅草塞住。现在茅草堵塞你的心了。”
', NULL, '', 'indent', 1558433268, '5ce35d7130863b00699f0e19', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642819, '孟子 · 第十四卷 · 尽心下 · 第二十二节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '高子曰：“禹之声，尚文王之声。”孟子曰：“何以言之？”
曰：“以追蠡。”曰：“是奚足哉？城门之轨，两马之力与？”', '', '尚：通“上”，超过。
追（duī）蠡（lí）：钟钮要断的样子。追，钟钮。蠡，欲断的样子。
', '高子说：“大禹的音乐要胜过文王的音乐。”
孟子说：“为什么这样说呢？”
高子回答说：“因为大禹传下来的乐钟，钟钮都快断了。”
孟子说：“这怎能足以说明问题呢？城门下面的车辙，难道只是两匹马的力量造成的吗？是因为天长日久车马经过造成的呀。”
', NULL, '', 'indent', 1558433310, '5ce35d9a30863b00699f1090', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642820, '孟子 · 第十四卷 · 尽心下 · 第二十三节', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '齐饥。陈臻曰：“国人皆以夫子将复为发棠，殆不可复。”
孟子曰：“是为冯妇也。晋人有冯妇者，善搏虎，卒为善士。则之野，有众逐虎。虎负嵎，莫之敢撄。望见冯妇，趋而迎之。冯妇攘臂下车。众皆悦之，其为士者笑之。”', '', '发：打开。文中指打开粮仓赈济百姓。棠：地名，在今山东即墨。
冯妇：人名。姓冯，名妇。后以冯妇喻重操旧业的人。
嵎（yú）：山势曲折险峻的地方。撄（yīng）：迫近，触犯。
', '齐国发生饥荒。陈臻说：“国中的百姓都以为您会再次劝说齐王打开棠邑的粮仓来赈济灾民，恐怕不能再这样做了吧。”
孟子说：“再这样做就成了冯妇了。晋国有个叫冯妇的人，擅长和老虎搏斗，后来成了一个善人。有一次他到野外去，有很多人在追赶一只老虎。老虎背依山险，没有人敢迫近它。他们望见冯妇来了，就赶紧快步上前迎接他。冯妇捋袖伸臂跳下车来，大家见了都很高兴，可是那些士人却在讥笑他。”
', NULL, '', 'indent', 1558433363, '5ce35dcf7b968a0073085f57', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642821, '孟子 · 第十四卷 · 尽心下 · 第二十四节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“口之于味也，目之于色也，耳之于声也，鼻之于臭也，四肢之于安佚也，性也，有命焉，君子不谓性也。仁之于父子也，义之于君臣也，礼之于宾主也，知之于贤者也，圣人之于天道也，命也，有性焉，君子不谓命也。”
', '', '臭（xiù）：各种气味。文中特指芳香的气味。安佚：安逸，舒适。
', '孟子说：“口对于美味，眼对于美色，耳对于好听的声音，鼻对于芬芳的气味，手足四肢对于安逸，这些爱好都是天性，但能否得到，要由命来决定，君子不把它们看成是天性所致。仁对于父子，义对于君臣，礼对于宾主，智慧对于贤人，圣人对于天道，能否实现有命的作用，但也有天性的作用，君子不把它们看作是命运的范畴。”
', NULL, '', 'indent', 1558433395, '5ce35df0c8959c0069b9c392', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642822, '孟子 · 第十四卷 · 尽心下 · 第二十五节 ', NULL, 5, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '浩生不害问曰：“乐正子何人也？”
孟子曰：“善人也，信人也。”
“何谓善？何谓信？”
曰：“可欲之谓善，有诸己之谓信，充实之谓美，充实而有光辉之谓大，大而化之之谓圣，圣而不可知之之谓神。乐正子，二之中，四之下也。”
', '', '
', '浩生不害：姓浩生，名不害。齐国人。
浩生不害问道：“乐正子是什么样的人？”
孟子说：“是善人，是个诚信的人。”
“什么叫做善？什么叫做信？”
孟子回答说：“值得人喜欢叫做善，善为自身所拥有叫做信，使之充盈实在叫做美，不但充盈实在而且能够光彩夺目地表现出来叫做大，大而又能化育万物叫做圣，圣达到不可测度的境界叫做神。乐正子是处在‘善’与‘信’两者之中，但还没达到‘美’‘大’‘圣’‘神’四者的要求。”', NULL, '', 'indent', 1558433438, '5ce35e1bc8959c0069b9c584', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642823, '孟子 · 第十四卷 · 尽心下 · 第二十六节 ', NULL, 1, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“逃墨必归于杨，逃杨必归于儒。归，斯受之而已矣。今之与杨墨辩者，如追放豚，既入其苙，又从而招之。”', '', '放：放任，走失。
苙（lì）：养牲畜的栅栏。招：羁绊。
', '孟子说：“避开墨子学派的，一定会归入杨朱学派；避开杨朱学派的，一定会归入儒家学派。回归了，就接纳他罢了。如今和杨朱、墨翟学派辩论的人，就像追赶走丢了的猪，已经回到猪圈了，还要跟着把它的脚拴好。”
', NULL, '', 'indent', 1558433497, '5ce35e5630863b00699f199a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642824, '孟子 · 第十四卷 · 尽心下 · 第二十七节 ', NULL, 0, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“有布缕之征，粟米之征，力役之征。君子用其一，缓其二。用其二而民有殍，用其三而父子离。”', '', '力役之征：通过征劳役的方式征税。
殍（piǎo）：饿死的人。
', '孟子说：“有征收布帛的税，有征收粮食的税，有征发人力的税。君子只采用其中的一种，对于另外两种，暂不使用。如果同时征收两种税，百姓就会有饿死的；如果同时征收三种税，那么父子就会离散。”
', NULL, '', 'indent', 1558433526, '5ce35e74c8959c0069b9c92b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642827, '孟子 · 第十四卷 · 尽心下 · 第三十节 ', NULL, 13, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子之滕，馆于上宫。有业屦于牖上，馆人求之弗得。
或问之曰：“若是乎从者之廋也？”曰：“子以是为窃屦来与？”
曰：“殆非也。”“夫予之设科也，往者不追，来者不拒。苟以是心至，斯受之而已矣。”', '', '馆：住馆舍。上宫：别宫名。
业屦：指尚未编织好的草鞋。屦，草鞋。
廋（sōu）：隐藏。
夫：语气助词，用于对设科的论述，例如夫战，勇气也。
设科：开设课程，犹言开门授徒。
', '孟子到滕国去，住在上宫。有一双没编好的草鞋放在窗台上不见了，旅馆里的人来找，但没找到。有人问孟子说：“这么说是您的随从把草鞋藏起来了吧？”
孟子回答说：“你以为他们是为偷草鞋来的吗？”
那人回答说：“大概不是。”孟子说：“我在这里开设课程教学，往者不挽留，来者不拒绝，只要他是带有求学之心而来到这里的，就这样接受他罢了。”
', NULL, '', 'indent', 1558433628, '5ce35ed87b968a0073086b43', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642828, '孟子 · 第十四卷 · 尽心下 · 第三十一节 ', NULL, 6, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“人皆有所不忍，达之于其所忍，仁也；人皆有所不为，达之于其所为，义也。人能充无欲害人之心，而仁不可胜用也；人能充无穿逾之心，而义不可胜用也。人能充无受尔汝之实，无所往而不为义也。士未可以言而言，是以言餂之也；可以言而不言，是以不言餂之也，是皆穿逾之类也。”', '', '穿窬：穿洞越墙，偷窃之意。
无受尔汝之实：指不愿受别人的轻贱，就要先有不受轻贱的言语行为。“尔”“汝”是古代汉语中表示轻蔑感情色彩的人称代词。
餂（tiǎn）：取。
', '孟子说：“人人都有不忍心做的事，把这种心推及他所忍心做的事上，就是仁。人人都有不愿做的事，推及他想做的事上，就是义。人如果能够把不想害人的心扩展开，那么仁就会用之不竭了；人如果能够把不挖洞、跳墙的心扩展开，那么，义就会用之不竭了；人如果能够把不受人轻蔑的心理扩展开，就能无论到哪里，行为都符合义。士人不该说话的时候说话，这是用言语来套取人；该说话的时候不说话，这是用沉默来套取人，这些都是挖洞、跳墙之类的行径。”
', NULL, '', 'indent', 1558433670, '5ce35f01eaa37500681ab7f4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642829, '孟子 · 第十四卷 · 尽心下 · 第三十二节 ', NULL, 20, 271, 2, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“言近而指远者，善言也；守约而施博者，善道也。君子之言也，不下带而道存焉。君子之守，修其身而天下平。人病舍其田而芸人之田，所求于人者重，而所以自任者轻。”', '', '指：意旨，意向。
施：恩惠。
不下带：古代注视人，目光不可低于对方的腰带。文中比喻注意眼前常见之事。带，腰带。
芸：同“耘”。
', '孟子说：“言语浅近但意旨深远的，是‘善言’；操持简约而恩泽博大的，是‘善道’。君子的言谈，讲的都是眼前的事，然而道却蕴含其中；君子的操守，从修养自身开始，进而使天下太平。人们的毛病在于舍弃自己的田地，而去耕耘别人的田地——要求他人的太多，而对自己的要求却很少。”
', NULL, '', 'indent', 1558433723, '5ce35f3930863b00699f23b5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642830, '孟子 · 第十四卷 · 尽心下 · 第三十三节 ', NULL, 2, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“尧舜，性者也；汤武，反之也。动容周旋中礼者，盛德之至也；哭死而哀，非为生者也；经德不回，非以干禄也；言语必信，非以正行也。君子行法，以俟命而已矣。”', '', '经德不回：遵循道德而行，不致违礼；回，同“违”。干禄：求官。禄，官吏的俸禄。
行法：依法而行。
', '孟子说：“尧、舜的仁德是天性；商汤和周武王的仁德是经过修身而回复到天性。举止仪容无不合于礼，这是德行深厚到了极点。哭死者而悲哀，不是为了给活人看的；依据道德而行，不去违礼，不是为了谋求官职。言语一定要真实，不是为了让人知道行为端正。君子按法度做事，去等待命运的安排罢了。”
', NULL, '', 'indent', 1558433755, '5ce35f576e9ba10069a4e9a4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642831, '孟子 · 第十四卷 · 尽心下 · 第三十四节 ', NULL, 2, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“说大人，则藐之，勿视其巍巍然。堂高数仞，榱题数尺，我得志弗为也；食前方丈，侍妾数百人，我得志弗为也；般乐饮酒，驱骋田猎，后车千乘，我得志弗为也。在彼者，皆我所不为也；在我者，皆古之制也，吾何畏彼哉？”', '', '堂高：据前人研究，经传当中称“堂高”，一般均指堂阶而言。榱（cuī）题：亦作“榱提”，屋檐的椽子头，今通称出檐。
食前方丈：极言饮食的丰盛。美酒佳肴摆满眼前一丈见方的所在。
般（pán）乐：大作乐，尽情作乐。般，大。
', '孟子说：“游说诸侯，就得藐视他，不要在意他高高在上的样子。殿基几丈高，屋檐的椽子有几尺长，我得志的话，不会这样做。满桌的美味佳肴，侍奉的姬妾有几百人，我得志的话，不会这样做。尽情饮酒作乐，驰骋射猎，随从的车辆上千辆，我得志的话，不会这样做。他所做的，都是我所不做的；我所做的，都是符合古代制度的，我为什么要害怕他呢？”
', NULL, '', 'indent', 1558433795, '5ce35f81c8959c0069b9d480', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642832, '孟子 · 第十四卷 · 尽心下 · 第三十五节 ', NULL, 26, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“养心莫善于寡欲。其为人也寡欲，虽有不存焉者，寡矣；其为人也多欲，虽有存焉者，寡矣。”', '', '不存、存：文中指善性的缺失或保留。', '孟子说：“修养心性没有比减少欲望更好的办法。他的为人如果欲望少，即使善性有所缺失，也不会失去很多；他的为人如果欲望很多，那么即使善性有所保存，保留的也不会很多。”', '[{"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a701251899613caf3033", "shortContent": "孟子这里主要讲修养心性的方法。他认为，修养心性的最好方法莫过于减少物质欲望。一个人如果物欲不多，那么善性即使有所丧失，也不会多；反之，如果物欲很多，那么善性即使有所保存，也是极少的了。\n\n古代的圣贤们对于如何修身养性进行了长期的思索和探讨，而他们给我们最重要的一点建议就是“寡欲”。老子曾说过：“祸莫大于不知足，咎莫大于欲得。”（《老子·第四十六章》）他把人的贪欲看成是一种灾难和过错，并把“少私寡欲...", "authors": [], "pressName": "上海辞书出版社"}]', '', 'indent', 1558433816, '5ce35f966e9ba10069a4ebd1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642833, '孟子 · 第十四卷 · 尽心下 · 第三十六节 ', NULL, 4, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '曾皙嗜羊枣，而曾子不忍食羊枣。
公孙丑问曰：“脍炙与羊枣孰美？”孟子曰：“脍炙哉！”
公孙丑曰：“然则曾子何为食脍炙而不食羊枣？”曰：“脍炙所同也，羊枣所独也。讳名不讳姓，姓所同也，名所独也。”', '', '羊枣：果名。初生色黄，熟则黑，似羊屎。
脍炙：即脍和炙，都是佳肴。肉细切曰脍，烹炒曰炙。
讳：指对君主或尊长辈的名字避开而不直称。
', '曾皙喜欢吃羊枣，曾子因此便不忍心吃羊枣。公孙丑问道：“炒肉和羊枣比，哪个更好吃？”
孟子说：“炒肉好吃呀！”
公孙丑说：“既然这样，那么曾子为什么吃炒肉而不吃羊枣？”
孟子回答说：“炒肉是人们的共同爱好，吃羊枣却是曾皙的独特喜好。就像避讳，只避名，不避姓，因为姓是大家所共有的，名却是一个人所独有的。”
', NULL, '', 'indent', 1558433858, '5ce35fc030863b00699f28c4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642834, '孟子 · 第十四卷 · 尽心下 · 第三十七节 ', NULL, 3, 271, 1, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '万章问曰：“孔子在陈曰：‘盍归乎来！吾党之士狂简，进取，不忘其初。’孔子在陈，何思鲁之狂士？”
孟子曰：“孔子‘不得中道而与之，必也狂狷乎！狂者进取，狷者有所不为也’。孔子岂不欲中道哉？不可必得，故思其次也。”
“敢问何如斯可谓狂矣？”曰：“如琴张、曾皙、牧皮者，孔子之所谓狂矣。”
“何以谓之狂也？”曰：“其志嘐嘐然，曰‘古之人，古之人’。夷考其行而不掩焉者也。狂者又不可得，欲得不屑不洁之士而与之，是狷也，是又其次也。
孔子曰：‘过我门而不入我室，我不憾焉者，其惟乡原乎！乡原，德之贼也。’”曰：“何如斯可谓之乡原矣？”
曰：“‘何以是嘐嘐也？言不顾行，行不顾言，则曰：古之人，古之人。行何为踽踽凉凉？生斯世也，为斯世也，善斯可矣。’阉然媚于世也者，是乡原也。”
万章曰：“一乡皆称原人焉，无所往而不为原人，孔子以为德之贼，何哉？”
曰：“非之无举也，刺之无刺也；同乎流俗，合乎污世；居之似忠信，行之似廉洁；众皆悦之，自以为是，而不可与入尧舜之道，故曰德之贼也。孔子曰：‘恶似而非者：恶莠，恐其乱苗也；恶佞，恐其乱义也；恶利口，恐其乱信也；恶郑声，恐其乱乐也；恶紫，恐其乱朱也；恶乡原，恐其乱德也。’君子反经而已矣。经正，则庶民兴；庶民兴，斯无邪慝矣。”', '', '孔子在陈曰：此处所引，亦见于《论语·公冶长》，字句稍异。
党：乡里。
中道：无过无不及，中庸之道。狂狷（juàn）：狂，不受拘束，放荡。狷，拘谨有所不为。
琴张、曾皙、牧皮：均为孔门之中的狂放弟子。
嘐嘐（xiāo）：志大言大，言行不一。
夷：疑为语首助词，无义。
乡原（yuàn）：外有谨愿之名，实与流俗合污的伪善者。原，也作“愿”。
踽踽（jǔ）：孤独的样子。凉凉：冷冷清清的样子。
阉然：曲意迎人的样子。
原（yuàn）人：又作“愿人”，诚实的人。
莠（yǒu）：草名，似稷而无实。又名狗尾草。
朱：大红色，属正色。
反经：回归正道。反，同“返”。经，常道，正道。
', '万章问道：“孔子在陈国时说：‘何不回去啊！我乡里的晚辈们志大、狂放，积极进取，不忘当初的志向。’孔子在陈国，为什么思念鲁国那些狂放之人呢？”
孟子回答说：“孔子说过，‘找不到不偏不倚、合于道义的人相结交，那就只能找狂放者和狷介者了。狂放的人勇于进取，狷介的人有所不为’。孔子难道不想与合于道义的人交友吗？不能一定得到，所以只能想次—点的了。”
“请问怎样才可以算是狂放人呢？”
孟子回答说：“像琴张、曾皙、牧皮这样的人，就是孔子所说的狂放人了。”
“为什么说他们是狂放的人呢？”
孟子回答说：“他们志向远大，口气也大，总是说：‘古时的人，古时的人。’可是考察他们的行为，却不能与所说的话相符。狂放的人如果又得不到的话，就想得到不屑去做有辱自身之事的人来交友，这种人就是狷介之人，这又次了一等。孔子说：‘路过我的家门却不进到屋里，我不对此感到遗憾的，恐怕只有乡里的好好先生吧。乡里的好好先生，是德行的损害者。”
“怎样的人才算是乡里的好好先生呢？”
孟子回答说：“这种人批评狂放之士说：‘为什么要志存高远，口吐狂言呢？言语不顾及行为，行为不顾及言语，就只说古时的人，古时的人。’又批评狷介之士说，‘处事为什么要特立独行呢？生在这个世上，就要迎合这个世道，让别人都说个好就是了。’曲意逢迎，谄媚世人的就是好好先生。”
“全乡的人都称他是老好人，到哪儿都被视为老好人，孔子却认为他是德行的损害者，这是为什么呢？”
孟子回答说：“这种人，想指责他却列举不出缺点，想责骂他却找不到由头，他只是同流合污，平时似乎忠诚老实，处事似乎方正、廉洁，大家都喜欢他，自己以为做得正确，却与尧、舜之道格格不入，所以说是‘德行的损害者’。孔子说：厌恶那种外表相似实质不同的东西；厌恶狗尾草，怕它会混淆了禾苗；厌恶歪才，怕它会混淆了仁义；厌恶夸夸其谈，怕它会混淆了诚信；厌恶郑国的音乐，怕它会混淆了雅乐；厌恶紫色，怕它会混淆了朱红色；厌恶乡里的老好人，怕他会混淆了德行。君子只是让一切都回归正道罢了。路子对了，百姓就会奋发振作，百姓奋发振作了，也就没有了邪恶。”
', NULL, '', 'indent', 1558433931, '5ce3600930863b00699f2c0f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642835, '孟子 · 第十四卷 · 尽心下 · 第三十八节 ', NULL, 3, 271, 0, 1, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '孟子曰：“由尧舜至于汤，五百有余岁，若禹、皋陶，则见而知之；若汤，则闻而知之。由汤至于文王，五百有余岁，若伊尹、莱朱则见而知之；若文王，则闻而知之。由文王至于孔子，五百有余岁，若太公望、散宜生，则见而知之；若孔子，则闻而知之。由孔子而来至于今，百有余岁，去圣人之世，若此其未远也；近圣人之居，若此其甚也，然而无有乎尔，则亦无有乎尔。”', '', '莱朱：又名仲虺（huì），商汤时的贤臣。
散宜生：周文王时的贤臣，后曾帮助周武王灭商。
', '孟子说：“从尧、舜到商汤，有五百多年，像禹、皋陶，是亲眼目睹而知道尧、舜之道的；至于商汤，则是听到传闻而知道的。从商汤到周文王，有五百多年，像伊尹、莱朱，是亲眼目睹而知道的；至于文王，则是听到传闻而知道的。从周文王到孔子，又有五百多年，像太公望、散宜生，便是亲眼目睹而知道的；至于孔子，则是听到传闻而知道的。从孔子以来到现在，有百来年，距离圣人生活的时代不是很远，距离圣人的家乡如此接近，却没有继承圣人之道的，那也就不会有继承人了。”
', NULL, '', 'indent', 1558433969, '5ce3602feaa37500681ac49b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642869, '左传 · 隐公 · 隐公二年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二年春，公会戎于潜。夏五月，莒人入向。无骇帅师入极。秋八月庚辰，公及戎盟于唐。九月，纪裂繻来逆女。冬十月，伯姬归于纪。纪子帛、莒子盟于密。十有二月乙卯，夫人子氏薨。郑人伐卫。
【传】二年春，公会戎于潜，修惠公之好也。戎请盟，公辞。
莒子娶于向，向姜不安莒而归。夏，莒人入向以姜氏还。
司空无骇入极，费庈父胜之。
戎请盟。秋，盟于唐，复修戎好也。
九月，纪裂繻来逆女，卿为君逆也。
冬，纪子帛、莒子盟于密，鲁故也。
郑人伐卫，讨公孙滑之乱也。', '', '', '二年春季，鲁隐公在潜地与戎人会见，再一次加强惠公时期的友好关系，戎人请求结盟，隐公婉言拒绝了。
莒子在向国娶了妻子，向姜在莒国不安心而回到向国。夏季，莒子领兵进入向国，带着向姜回国。
司空无骇带兵进入极国，派费庈父灭亡了极国。
戎人请求结盟。秋季，在唐地结盟，这是为了再次加强和戎人的友好关系。
九月，纪国的裂繻来迎接隐公的女儿，这是卿为了国君而来迎娶的。
冬季，纪子帛和莒子在密地结盟，这是为了调解鲁国和莒国间的不和睦。
郑国人进攻卫国，讨伐公孙滑的叛乱。


', NULL, '', 'indent', 1558623674, '5ce64537a673f50068da3128', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642870, '左传 · 隐公 · 隐公三年 ', NULL, 12, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三年春王二月，己巳，日有食之。三月庚戌，天王崩。夏四月辛卯，君氏卒。秋，武氏子来求赙。八月庚辰，宋公和卒。冬十有二月，齐侯，郑伯盟于石门。癸未，葬宋穆公。
【传】三年春，王三月壬戌，平王崩，赴以庚戌，故书之。
夏，君氏卒。声子也。不赴于诸侯，不反哭于寝，不祔于姑，故不曰薨。不称夫人，故不言葬，不书姓。为公故，曰「君氏」。
郑武公、庄公为平王卿士。王贰于虢，郑伯怨王，王曰「无之」。故周、郑交质。王子狐为质于郑，郑公子忽为质于周。王崩，周人将畀虢公政。四月，郑祭足帅师取温之麦。秋，又取成周之禾。周、郑交恶。
君子曰：「信不由中，质无益也。明恕而行，要之以礼，虽无有质，谁能间之？苟有明信，涧溪沼沚之毛，苹蘩温藻之菜，筐筥錡釜之器，潢污行潦之水，可荐于鬼神，可羞于王公，而况君子结二国之信。行之以礼，又焉用质？《风》有《采繁》、《采苹》，《雅》有《行苇》、《泂酌》，昭忠信也。」
武氏子来求赙，王未葬也。
宋穆公疾，召大司马孔父而属殇公焉，曰：「先君舍与夷而立寡人，寡人弗敢忘。若以大夫之灵，得保首领以没，先君若问与夷，其将何辞以对？请子奉之，以主社稷，寡人虽死，亦无悔焉。」对曰：「群臣愿奉冯也。」公曰：「不可。先君以寡人为贤，使主社稷，若弃德不让，是废先君之举也。岂曰能贤？光昭先君之令德，可不务乎？吾子其无废先君之功。」使公子冯出居于郑。八月庚辰，宋穆公卒。殇公即位。
君子曰：「宋宣公可谓知人矣。立穆公，其子飨之，命以义夫。《商颂》曰：『殷受命咸宜，百禄是荷。』其是之谓乎！」
冬，齐、郑盟于石门，寻卢之盟也。庚戌，郑伯之车偾于济。
卫庄公娶于齐东宫得臣之妹，曰庄姜，美而无子，卫人所为赋《硕人》也。又娶于陈，曰厉妫，生孝伯，早死。其娣戴妫生桓公，庄姜以为己子。公子州吁，嬖人之子也，有宠而好兵，公弗禁，庄姜恶之。石碏谏曰：「臣闻爱子，教之以义方，弗纳于邪。骄、奢、淫、泆，所自邪也。四者之来，宠禄过也。将立州吁，乃定之矣，若犹未也，阶之为祸。夫宠而不骄，骄而能降，降而不憾，憾而能珍者鲜矣。且夫贱妨贵，少陵长，远间亲，新间旧，小加大，淫破义，所谓六逆也。君义，臣行，父慈，子孝，兄爱，弟敬，所谓六顺也。去顺效逆，所以速祸也。君人者将祸是务去，而速之，无乃不可乎？」弗听，其子厚与州吁游，禁之，不可。桓公立，乃老。


', '', '', '三年春季，周王朝历法的三月二十四日，周平王逝世。讣告上写的是庚戌日，所以《春秋》也记载死日为庚戌，即十二日。
夏季，君氏死。君氏就是声子，没有发讣告给诸侯，安葬后没有回到祖庙哭祭，没有把神主放在婆婆神主的旁边，所以《春秋》不称“薨”。又由于没有称她为“夫人”，所以不记载下葬的情况，也没有记载她的姓氏。只是因为她是隐公的生母的缘故，所以才称她为“君氏”。
郑武公、郑庄公先后担任周平王的卿士，平王暗中又将朝政分托给虢公，郑庄公埋怨周平王，平王说：“没有这回事。”所以周、郑交换人质。王子狐在郑国作为人质，郑国的公子忽在周朝作为人质。平王死后，周王室的人想把政权交给虢公。四月，郑国的祭足带兵割取了温地的麦子。秋天，又割取了成周的谷子。周朝和郑国彼此怀恨。君子说：“诚意不发自内心，即使交换人质也没有益处。设身处地将心比心来办事，又用礼仪加以约束，虽然没有人质，又有谁能离间他们？假如确有诚意，即使是山沟、池塘里生长的野草，蘋、蘩、蕴、藻这一类的野菜，一般的竹器和金属器皿，大小道上的积水，都可以献给鬼神，进给王公，何况君子建立了两国的信约，按照礼仪办事，又哪里还用得着人质？《国风》
有《采繁》、《采蘋》，《大雅》有《行苇》、《泂酌》这些诗篇，就是为了表明忠信的。”
武氏的儿子来鲁国求取办丧事的财物，这是由于周平王还没有举行葬礼。
宋穆公病重了，召见大司马孔父而把殇公嘱托给他，说：“先君抛弃了他的儿子与夷而立我为国君，我不敢忘记。如果托大夫的福，我能得以保全脑袋，先君如果问起与夷，将用什么话回答呢？请您事奉与夷来主持国家事务，我虽然死去，也不后悔什么了。”孔父回答说：“群臣愿意事奉您的儿子冯啊！”穆公说：“不行，先君认为我有德行，才让我主持国家事务。如果丢掉道德而不让位，这就是废弃了先君的提拔，哪里还能说有什么德行？发扬光大先君的美德，难道能不急于办理吗？您不要废弃先君的功业！”于是命令公子冯到郑国去住。八月初五，宋穆公死，殇公即位。君子说：“宋宣公可以说是能了解人了。立了兄弟穆公，他的儿子却仍然享受了君位，这是他的遗命出于道义。《诗经•商颂》说：‘殷王传授天命都合于道义，所以承受了各种福禄’，就是这种情况。”
冬季，齐国和郑国在石门会盟，这是为了重温在庐地结盟的友好关系。
冬季某一天，郑伯在济水翻了车。
卫庄公娶了齐国太子得臣的妹妹，称为庄姜。庄姜漂亮却没有生孩子，卫国人因此为她创作了《硕人》这篇诗。卫庄公又在陈国娶了一个妻子，名叫厉妫，生了孝伯，很早就死了。跟厉妫陪嫁来的妹妹戴妫，生了卫桓公，庄姜就把他作为自己的儿子。
公子州吁，是卫庄公宠妾的儿子，得到庄公的宠爱，州吁喜欢军器，庄公不加禁止。庄姜很讨厌他。石碏规劝庄公说：“我听说喜欢自己的儿子，应当以道义去教育他，不要使他走上邪路。骄傲、奢侈、放荡、逸乐，这是走上邪路的开始。这四种恶习之所以发生，是由于宠爱和赐予太过份。如果准备立州吁做太子，那就应该定下来；如果还不定下来，会逐渐酿成祸乱。那种受宠而不骄傲，骄傲而能安于地位下降，地位下降而不怨恨，怨恨而能克制的人，是很少见的。而且低贱的妨害尊贵的，年少的驾凌年长的，疏远的离间亲近的，新的离间旧的，弱小的欺侮强大的，淫欲的破坏道义的，这就是六种反常现象。国君行事得宜，臣子服从命令，父亲慈爱，儿子孝顺，兄爱弟、弟敬兄，这就是六种正常现象。去掉正常而效法反常，这就会很快地招致祸害。作为君主，应该尽力于去掉祸害，现在却加速它的到来，恐怕不可以吧！”庄公不听。石碏的儿子石厚和州吁交游，石碏禁止他，石厚不听。卫桓公即位，石碏就告老回家了。', NULL, '', 'indent', 1558623719, '5ce6456430863b0068bc05d6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642871, '左传 · 隐公 · 隐公四年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】四年春王二月，莒人伐杞，取牟娄。戊申，卫州吁弑其君完。夏，公及宋公遇于清。宋公、陈侯、蔡人、卫人伐郑。秋，翬帅师会宋公、陈侯、蔡人、卫人伐郑。九月，卫人杀州吁于濮。冬十有二月，卫人立晋。
【传】四年春，卫州吁弑桓公而立。公与宋公为会，将寻宿之盟。未及期，卫人来告乱。夏，公及宋公遇于清。
宋殇公之即位也，公子冯出奔郑，郑人欲纳之。及卫州吁立，将修先君之怨于郑，而求宠于诸侯以和其民，使告于宋曰：「君若伐郑以除君害，君为主，敝邑以赋与陈、蔡从，则卫国之愿也。」宋人许之。于是，陈、蔡方睦于卫，故宋公、陈侯、蔡人、卫人伐郑，围其东门，五日而还。
公问于众仲曰：「卫州吁其成乎？」对曰：「臣闻以德和民，不闻以乱。以乱，犹治丝而棼之也。夫州吁，阻兵而安忍。阻兵无众，安忍无亲，众叛亲离，难以济矣。夫兵犹火也，弗戢，将自焚也。夫州吁弑其君而虐用其民，于是乎不务令德，而欲以乱成，必不免矣。」
秋，诸侯复伐郑。宋公使来乞师，公辞之。羽父请以师会之，公弗许，固请而行。故书曰「翬帅师」，疾之也。诸侯之师败郑徒兵，取其禾而还。
州吁未能和其民，厚问定君于石子。石子曰：「王觐为可。」曰：「何以得觐？」曰：「陈桓公方有宠于王，陈、卫方睦，若朝陈使请，必可得也。」厚从州吁如陈。石碏使告于陈曰：「卫国褊小，老夫耄矣，无能为也。此二人者，实弑寡君，敢即图之。」陈人执之而请莅于卫。九月，卫人使右宰丑莅杀州吁于濮，石碏使其宰乳羊肩莅杀石厚于陈。
君子曰：「石碏，纯臣也，恶州吁而厚与焉。『大义灭亲』，其是之谓乎！」
卫人逆公子晋于邢。冬十二月，宣公即位。书曰「卫人立晋」众也。', '', '', '四年春季，卫国的州吁杀了卫桓公而自立为国君。
鲁隐公和宋殇公会见，打算重温在宿地所建立的友好。还没有到预定的日子，卫国人来报告发生了叛乱。夏季，隐公和宋殇公在清地会见。
当宋殇公即位的时候，公子冯逃到了郑国。郑国人想送他回国。等到州吁立为国君，准备向郑国报复前代国君结下的怨恨，以此对诸侯讨好，安定国内人心。他派人告诉宋国说：“君王如果进攻郑国，除去君王的祸害，以君王为主，敝邑出兵出物，和陈、蔡两国一道作为属军，这就是卫国的愿望。”宋国答应了。这时候陈国、蔡国正和卫国友好，所以宋殇公、陈桓公、蔡国人、卫国人联合进攻郑国，包围了国都的东门，五天以后才回去。
鲁隐公向众仲询问说：“卫国的州吁能成功吗？”众仲回答说：“我只听说用德行安定百姓，没有听说用祸乱的。用祸乱，如同要理出乱丝的头绪，反而弄得更加纷乱。州吁这个人，仗恃武力而安于残忍。仗恃武力就没有群众，安于残忍就没有亲附的人。大家背叛，亲近离开，难以成功。军事，就像火一样，不去制止，将会焚烧自己。州吁杀了他的国君，又暴虐地使用百姓，不致力于建立美德，反而想通过祸乱来取得成功，就一定不能免于祸患了。”
秋季，诸侯再次进攻郑国。宋殇公派人前来请求出兵相救，隐公推辞了。羽父请求出兵相会合，隐公不同意。羽父坚决请求以后便前去。所以《春秋》记载说：“翚帅师”，这是表示讨厌他不听命令。诸侯的军队打败了郑国的步兵，割取了那里的谷子便回来。
州吁不能安定他的百姓。石厚向石碏询问安定君位的办法。石碏说：“朝觐周天子就可以取得合法地位。”石厚说：“如何才能去朝觐呢？”石碏说：“陈桓公正在受到天子的宠信。现在陈、卫两国正互相和睦，如果朝见陈桓公，让他代为请求，就一定可以成功。”于是石厚就跟随州吁到了陈国。石碏派人告诉陈国说：“卫国地方狭小，我老头子年纪已七十多了，不能做什么事了，这两个人，确实杀死了我国君主，请您趁此机会搞掉他们。”陈国人把这两个人抓住，而请卫国派人来陈国处理。九月，卫国人派右宰丑在陈国的濮地杀了州吁，石碏派他的管家獳羊肩在陈国杀了石厚。
君子说：“石碏真是个忠臣。讨厌州吁，同时加上儿子石厚。‘大义灭亲’就是这样的情况吧！”
卫国人到邢国迎接公子晋。冬季，十二月，卫宣公即位。《春秋》记载说“卫人立晋”，这是说出于大众的意思。', NULL, '', 'indent', 1558623763, '5ce6458eba39c8006842f9b2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642887, '左传 · 桓公 · 桓公九年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】九年春，纪季姜归于京师。夏四月，秋七月。冬，曹伯使其世子射姑来朝。
【传】九年春，纪季姜归于京师。凡诸侯之女行，唯王后书。
巴子使韩服告于楚，请与邓为好。楚子使道朔将巴客以聘于邓。邓南鄙郁人攻而夺之币，杀道朔及巴行人。楚子使薳章让于邓，邓人弗受。
夏，楚使斗廉帅师及巴师围郁。邓养甥、聃甥帅师郁救。三逐巴师，不克。斗廉衡陈其师于巴师之中，以战，而北。邓人逐之，背巴师而夹攻之。邓师大败，郁人宵溃。
秋，虢仲、芮伯、梁伯、荀侯、贾伯伐曲沃。
冬，曹大子来朝，宾之以上卿，礼也。享曹大子，初献，乐奏而叹。施父曰：「曹大子其有忧乎？非叹所也。」', '', '', '九年春季，纪国的季姜出嫁到京师。凡是诸侯的女儿出嫁，只有出嫁做王后才加以记载。
巴子派遣韩服向楚国报告，请求和邓国友好。楚武王派遣道朔带领巴国的使者到邓国聘问。邓国南部边境的鄾地人攻击他们，并掠夺财礼，杀死了道朔和巴国的使者。楚武王派遣薳章责备邓国，邓国人拒不接受。
夏季，楚国派遣鬬廉率领楚军和巴军包围鄾地。邓国的养甥、聃甥率领邓军救援鄾地。邓军三次向巴军发起冲锋，不能得胜。鬬廉率军在巴军之中列为横阵，当与邓军交战时，假装败逃。邓军追逐楚军，巴军就处于他们背后。楚、巴两军夹攻邓军，邓军大败。鄾地人黄昏后就溃散了。
秋季，虢仲、芮伯、梁伯、荀侯、贾伯，共同出兵讨伐曲沃。
冬季，曹国的太子来鲁国朝见。用上卿之礼接待他，这是合于礼的。设享礼招待曹太子。首先献酒，接着奏乐，曹太子就叹气。施父说：“曹太子恐怕会有什么忧心事吧？因为这里不是叹息的地方。”', NULL, '', 'indent', 1558624420, '5ce64821ba39c8006843183e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642872, '左传 · 隐公 · 隐公五年 ', NULL, 4, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】五年春，公矢鱼于棠。夏四月，葬卫桓公。秋，卫师入郕。九月，考仲子之宫。初献六羽。邾人、郑人伐宋。螟。冬十有二月辛巳，公子彄卒。宋人伐郑，围长葛。
【传】五年春，公将如棠观鱼者。臧僖伯谏曰：「凡物不足以讲大事，其材不足以备器用，则君不举焉。君将纳民于轨物者也。故讲事以度轨量谓之轨，取材以章物采谓之物，不轨不物谓之乱政。乱政亟行，所以败也。故春蒐夏苗，秋獮冬狩，皆于农隙以讲事也。三年而治兵，入而振旅，归而饮至，以数军实。昭文章，明贵贱，辨等列，顺少长，习威仪也。鸟兽之肉不登于俎，皮革齿牙、骨角毛羽不登于器，则公不射，古之制也。若夫山林川泽之实，器用之资，皂隶之事，官司之守，非君所及也。」公曰：「吾将略地焉。」遂往，陈鱼而观之。僖伯称疾，不从。书曰「公矢鱼于棠」，非礼也，且言远地也。
曲沃庄伯以郑人、邢人伐翼，王使尹氏、武氏助之。翼侯奔随。
夏，葬卫桓公。卫乱，是以缓。
四月，郑人侵卫牧，以报东门之役。卫人以燕师伐郑。郑祭足、原繁、泄驾以三军军其前，使曼伯与子元潜军军其后。燕人畏郑三军而不虞制人。六月，郑二公子以制人败燕师于北制。君子曰：「不备不虞，不可以师。」
曲沃叛王。秋，王命虢公伐曲沃而立哀侯于翼。
卫之乱也，郕人侵卫，故卫师入郕。
九月，考仲子之宫，将万焉。公问羽数于众仲。对曰：「天子用八，诸侯用六，大夫四，士二。夫舞所以节八音而行八风，故自八以下。」公从之。于是初献六羽，始用六佾也。
宋人取邾田。邾人告于郑曰：「请君释憾于宋，敝邑为道。」郑人以王师会之。伐宋，入其郛，以报东门之役。宋人使来告命。公闻其入郛也，将救之，问于使者曰：「师何及？」对曰：「未及国。」公怒，乃止，辞使者曰：「君命寡人同恤社稷之难，今问诸使者，曰『师未及国』，非寡人之所敢知也。」
冬十二月辛已，臧僖伯卒。公曰：「叔父有憾于寡人，寡人弗敢忘。葬之加一等。
宋人伐郑，围长葛，以报入郛之役也。', '', '', '五年春季，鲁隐公准备到棠地观看捕鱼。臧僖伯劝阻说：“凡是一种东西不能用到讲习祭祀和兵戎的大事上，它的材料不能制作礼器和兵器，国君对它就不会采取行动。国君是要把百姓引入正‘轨’、善于取材的人。所以演习大事以端正法度叫做‘轨’，选取材料以制作重要器物叫做‘物’。事情不合于‘轨’、‘物’，叫做乱政。乱政屡次执行，国家将由此败亡。所以春蒐、夏苗、秋狝、冬狩这四种打猎的举动，都是在农业空闲时讲习。每三年大演习一次，进入国都整顿军队，回来祭祖告宗庙，宴请臣下，犒赏随员，以计算俘获的东西。要车服文采鲜明，贵贱有别，辨别等级，少长有序，这是讲习威仪。鸟兽的肉不摆上宗庙的祭器里，它的皮革、牙齿、骨角、毛羽不用到礼器上，国君就不去射它，这是古代的规定。至于山林河泽的产品，一般器物的材料，这是下等人的事情，有关官吏的职责，不是国君所应涉及的。”隐公说：“我是打算视察边境呀！”于是隐公就动身前往棠邑，让捕鱼者摆出捕鱼场面来观看。臧僖伯推说有病，没有跟随前去。《春秋》说：“公矢鱼于棠”，隐公在棠地陈列渔具，这是由于隐公的行为不合于礼制，而且暗示棠地离国都较远。
曲沃庄伯带领郑军、邢军进攻翼地，周桓王派尹氏、武氏帮助他。在翼地的晋鄂侯逃到随地。
夏季，安葬卫桓公。由于卫国发生动乱，所以迟缓了。
四月，郑国人入侵卫国郊外，来报复去年东门这一战役。卫国人带领南燕军队进攻郑国，郑国的祭足、原繁、泄驾带领三军进攻燕军的前面，派曼伯和子元偷偷率领制地的军队袭击燕军的后面。燕国人害怕郑国的三军，而没有防备从制地来的军队。六月，郑国的两个公子曼伯和子元在虎牢关击败了燕军。
君子说：“不防备意外，就不可以带兵作战。”曲沃背叛周桓王。秋季，周桓王命令虢公进攻曲沃，而在翼地立哀侯为晋君。
当卫国动乱的时候，郕国人入侵卫国，所以卫国的军队进入郕国。
九月，祭仲子庙，又准备在庙里献演万舞。隐公向众仲询问执羽舞的人数。众仲回答说：“天子用八行，诸侯用六行，大夫四行，士二行。舞，用来调节八种材料所制乐器的乐音而传播八方之风。所以人数在八行以下。”
隐公听从了。从此以后献演六羽乐舞，开始使用六行舞人。
宋国人掠取邾国的土地，邾国人告诉郑国说：“请君王攻打宋国，报仇雪恨，敝邑愿意做向导。”郑国人带领周天子的军队和邾军会合，进攻宋国，
进入了外城，以报复去年东门这一战役。宋国人派人前来用国君的名义告急请救。隐公听说军队已经进入外城，打算出兵救援宋国，询问使者说：“军队到了什么地方？”使者欺骗他说：“还没有到国都。”隐公发怒，不去救援。他辞谢使者说：“君王命令我一起为宋国的危难忧虑，现在询问使者，回答说‘军队还没有到国都’，这就不是我所敢知道的了。”
冬季，十二月二十九日，臧僖伯死了。隐公说：“叔父对我有怨恨，我不敢忘记他的忠诚。”于是按照原等级加一级的葬仪安葬他。
宋国人进攻郑国，包围长葛，以报复攻进外城这一战役。', NULL, '', 'indent', 1558623829, '5ce645d27b968a007629efb4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642874, '左传 · 隐公 · 隐公七年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】七年春王三月，叔姬归于纪。滕侯卒。夏，城中丘。齐侯使其弟年来聘。秋，公伐邾。冬，天王使凡伯来聘。戎伐凡伯于楚丘以归。
【传】七年春，滕侯卒。不书名，未同盟也。凡诸侯同盟，于是称名，故薨则赴以名，告终嗣也，以继好息民，谓之礼经。
夏，城中丘，书，不时也。
齐侯使夷仲年来聘，结艾之盟也。
秋，宋及郑平。七月庚申，盟于宿。公伐邾，为宋讨也。
初，戎朝于周，发币于公卿，凡伯弗宾。冬，王使凡伯来聘。还，戎伐之于楚丘以归。
陈及郑平。十二月，陈五父如郑莅盟。壬申，及郑伯盟，歃如忘泄伯曰：「五父必不免，不赖盟矣。」
郑良佐如陈莅盟，辛巳，及陈侯盟，亦知陈之将乱也。
郑公子忽在王所，故陈侯请妻之。郑伯许之，乃成昏。


', '', '', '七年春季，滕侯逝世，《春秋》没有记载滕侯的名字，是由于没有和鲁国同盟的缘故。凡是诸侯各国缔结过同盟，就彼此把国名向神明报告，所以当国君死后则在讣告上也写上名字，这是为了向同盟国报告国君逝世和继承的人，以便继续过去的友好关系，并以此安定人民，这是礼的大法。
夏季，在中丘筑城。《春秋》加以记载，由于妨碍了农时。
齐僖公派夷仲年前来聘问，这是为了巩固艾地的盟会。
秋季，宋国和郑国讲和。七月十七日，在宿地结盟。隐公进攻邾国，这是为宋国而去进攻的。
当初，戎人朝觐周王，向公卿送了财币，唯有凡伯不以宾礼款待。冬季，周天子派凡伯来鲁国聘问。在回去的路上，戎人在楚丘对他加以截击，俘虏他回去。
陈国与郑国讲和。十二月，陈国的五父到郑国参与结盟。初二，和郑庄公盟誓，歃血的时候心不在焉。泄伯说：“五父一定不免于祸，因为他不认为结盟是国家的利益。”
郑国的良佐到陈国参加结盟，十一日，和陈侯结盟，看出了陈国将要发生骚乱。
郑国的公子忽在周桓王那里，所以陈桓公请求把女儿嫁给他。郑庄公同意，于是就订了婚。', NULL, '', 'indent', 1558623933, '5ce6463b7b968a007629f4ca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642875, '左传 · 隐公 · 隐公八年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】八年春，宋公、卫侯遇于垂。三月，郑伯使宛来归祊。庚寅，我入祊。夏六月己亥，蔡侯考父卒。辛亥，宿男卒。秋七月庚午，宋公、齐侯、卫侯盟于瓦屋。八月，葬蔡宣公。九月辛卯，公及莒入盟于浮来。螟。冬十有二月，无骇卒。
【传】八年春，齐侯将平宋、卫，有会期。宋公以币请于卫，请先相见，卫侯许之，故遇于犬丘。
郑伯请释泰山之祀而祀周公，以泰山之祊易许田。三月，郑伯使宛来归祊，不祀泰山也。
夏，虢公忌父始作卿士于周。
四月甲辰，郑公子忽如陈逆妇妫。辛亥，以妫氏归。甲寅，入于郑。陈金咸子送女。先配而后祖。金咸子曰：「是不为夫妇。诬其祖矣，非礼也，何以能育？」
齐人卒平宋、卫于郑。秋，会于温，盟于瓦屋，以释东门之役，礼也。
八月丙戌，郑伯以齐人朝王，礼也。
公及莒人盟于浮来，以成纪好也。
冬，齐侯使来告成三国。公使众仲对曰：「君释三国之图以鸠其民，君之惠也。寡君闻命矣，敢不承受君之明德。」
无骇卒。羽父请谥与族。公问族于众仲。众仲对曰：「天子建德，因生以赐姓，胙之土而命之氏。诸侯以字为谥，因以为族。官有世功，则有官族，邑亦如之。」公命以字为展氏。


', '', '', '八年春季，齐僖公准备要宋、卫两国和郑国讲和，已经有了结盟的日期。宋殇公用财币向卫国请求，希望先行见面。卫宣公同意，所以在犬丘举行非正式会见的仪式。
郑庄公请求免除对泰山的祭祀而祭祀周公，用泰山旁边的祊地交换鲁国。
在许地的土田。三月，郑庄公派遣宛来致送祊地，表示不再祭祀泰山了。夏季，虢公忌父开始在成周做卿士。四月初六日，郑公子忽到陈国迎娶妻子妫氏，十三日，带着妫氏回来。
十六日，进入郑国，陈鍼子送妫氏到郑国。他们先结婚而后告祭祖庙。鍼子说：“这不能算夫妇，欺骗了他的祖先，这不合于礼，怎么能够使子孙繁衍兴旺呢？”
齐国人终于让宋、卫两国和郑国讲和。秋季，在温地会见，在瓦屋结盟，
丢弃东门这一役的旧怨，这是合于礼的。八月某一天，郑庄公带着齐国人朝觐周桓王，这是合于礼的。隐公和莒子在浮来结盟，以达成对纪国的友好。冬季，齐僖公派人来报告宋、卫、郑三国讲和的事。隐公派众仲回答说：
“君王使三国舍弃相互仇敌的图谋，安定他们的百姓，这都是君王的恩惠。寡君听到了，岂敢不承受君王的高明的好行动！”
无骇去世，羽父为他请求谥号和族氏。隐公向众仲询问关于族氏的事。众仲回答说：“天子建立有德之人以做诸侯，根据他的生地而赐姓，分封土地而又赐给他族氏。诸侯以字作为谥号，他的后人又以这作为族氏。先代做官而世代有功绩，就可以用官名作为族氏。也有以封邑为族氏的。”隐公命令以无骇的字作为族氏，就是展氏。
', NULL, '', 'indent', 1558623974, '5ce6466330863b0068bc1b2e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642876, '左传 · 隐公 · 隐公九年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】九年春，天子使南季来聘。三月癸酉，大雨，震电。庚辰，大雨雪。挟卒。夏，城郎。秋七月。冬，公会齐侯于防。
【传】九年春，王三月癸酉，大雨霖以震，书始也。庚辰，大雨雪，亦如之。书，时失也。凡雨，自三日以往为霖。平地尺为大雪。
夏，城郎，书，不时也。
宋公不王。郑伯为王左卿士，以王命讨之，伐宋。宋以入郛之役怨公，不告命。公怒，绝宋使。
秋，郑人以王命来告伐宋。
冬，公会齐侯于防，谋伐宋也。
北戎侵郑，郑伯御之。患戎师，曰；「彼徒我车，惧其侵轶我也。」公子突曰：「使勇而无刚者尝寇，而速去之。君为三覆以待之。戎轻而不整，贪而无亲，胜不相让，败不相救。先者见获必务进，进而遇覆必速奔，后者不救，则无继矣。乃可以逞。」从之。
戎人之前遇覆者奔。祝聃逐之。衷戎师，前后击之，尽殪。戎师大奔。十一月甲寅，郑人大败戎师。', '', '', '九年春季，周王朝历法的三月初十日，天久下大雨而且打雷闪电，《春秋》记载了开始的日期。十七日，又久下大雨雪，《春秋》也只记开始的日期。所以记载，是由于天时不正常的缘故。凡是下雨，连续下三天以上就叫“霖”。平地雪深一尺就叫“大雪”。
夏季，在郎地筑城。《春秋》记载这件事，由于妨碍农时。
宋殇公不去朝见周桓王。这时郑庄公正担任周桓王的卿士，于是用天子的名义讨伐他。郑国进攻宋国。宋国由于被攻外城那次战役对隐公不满，不来报告。隐公发怒，就断绝与宋国的往来。
秋季，郑国人用天子的名义前来报告进攻宋国。
冬季，隐公和齐僖公在防地会面，策划进攻宋国。
北戎人侵略郑国。郑庄公率兵抵御他们，又忧心戎军力量强大，说：“他们是步兵，我们用战车，我很担心他们从后边突然绕到我军之前袭击我们。”公子突说：“派遣一些勇敢而不刚毅的兵士，和敌人一接触就赶紧退走，君王就设下三批伏兵等待他们。戎人轻率而不整肃，贪婪而不团结，打赢了各不相让，打败了各不相救。走到前面的见到有财物俘虏，必然一意前进，前进而遭遇伏兵，必然赶快奔逃。走在后面的人不去救援，敌兵就没有后继者了。这样，我们就可以得胜。”郑庄公听从了公子突的意见。
戎人的前锋部队遇到了伏兵就奔逃，祝聃追逐他们，把戎军从中截断，前后夹攻，将戎军全部歼灭。戎军后继部队拼命奔逃。十一月二十六日，郑人把戎军打得大败而逃。
', NULL, '', 'indent', 1558624011, '5ce64688a673f50068da49d4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642877, '左传 · 隐公 · 隐公十年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十年春王二月，公会齐侯、郑伯于中丘。夏，翬帅师会齐人、郑人伐宋。六月壬戌，公败宋师于菅。辛未，取郜。辛巳，取防。秋，宋人、卫人入郑。宋人、蔡人、卫人伐戴。郑伯伐取之。冬十月壬午，齐人、郑人入郕。
【传】十年春，王正月，公会齐侯，郑伯于中丘。癸丑，盟于邓，为师期。
夏五月羽父先会齐侯、郑伯伐宋。
六月戊申，公会齐侯、郑伯于老桃。壬戌，公败宋师于菅。庚午，郑师入郜。辛未，归于我。庚辰，郑师入防。辛巳，归于我。
君子谓：「郑庄公于是乎可谓正矣。以王命讨不庭，不贪其土以劳王爵，正之体也。」
蔡人、卫人、郕人不会王命。
秋七月庚寅，郑师入郊。犹在郊，宋人、卫人入郑。蔡人从之，伐戴。八月壬戌，郑伯围戴。癸亥，克之，取三师焉。宋、卫既入郑，而以伐戴召蔡人，蔡人怒，故不和而败。
九月戊寅，郑伯入宋。
冬，齐人、郑人入郕，讨违王命也。', '', '', '十年春季，周王朝历法的正月，鲁隐公在中丘会见齐僖公、郑庄公。二月二十五日，在邓地结盟，决定出兵日期。夏季五月，羽父事先会合齐僖公、郑庄公，进攻宋国。六月某一天，隐公在老桃会见齐僖公、郑庄公。初七日，隐公在菅地打败宋军。十五日，郑国军队开进郜地。十六日，郑国把郜地归属于我国。二十五日，郑国军队又开进防地。二十六日，郑国把防地归属于我国。
君子说：“郑庄公这样做，可以说合于正道了。用天子的命令讨伐不来朝觐的诸侯，自己不贪求土地，而以犒赏受天子的爵位的鲁国，这是得到治理政事的本体了。”
蔡国人、卫国人、郕国人没有按照天子的命令会师讨伐宋国。
秋季，七月初五日，郑国的军队进入本国的远郊，仍然停留在那里。宋军、卫军趁此攻进郑国。蔡军跟在后面进攻戴地。八月初八日，郑庄公包围戴地。初九日，攻克戴地，俘虏了三国军队。
宋军、卫军已经攻入郑国，而又为了攻打戴地才联合蔡军，蔡国人发怒。
由于三支军队不合作而失败。九月的一天，郑庄公率军攻入宋国。冬季，齐军、郑军攻入郕国，这是讨伐郕国违背天子的命令。
', NULL, '', 'indent', 1558624048, '5ce646aeba39c8006843058b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642878, '左传 · 隐公 · 隐公十一年 ', NULL, 3, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有一年春，滕侯、薛侯来朝。夏，公会郑伯于时来。秋七月壬午，公及齐侯、郑伯入许。冬十有一月壬辰，公薨。
【传】十一年春，滕侯、薛侯来朝，争长。薛侯曰：「我先封。」滕侯曰：「我，周之卜正也。薛，庶姓也，我不可以后之。」
公使羽父请于薛侯曰：「君与滕君辱在寡人。周谚有之曰：『山有木，工则度之；宾有礼，主则择之。』周之宗盟，异姓为后。寡人若朝于薛，不敢与诸任齿。君若辱贶寡人，则愿以滕君为请。」
薛侯许之，乃长滕侯。
夏，公会郑伯于郲，谋伐许也。
郑伯将伐许，五月甲辰，授兵于大宫。公孙阏与颖考叔争车，颖考叔挟輈以走，子都拔棘以逐之，及大逵，弗及，子都怒。
秋七月，公会齐侯、郑伯伐许。庚辰，傅于许，颖考叔取郑伯之旗蝥弧以先登。子都自下射之，颠。瑕叔盈又以蝥弧登，周麾而呼曰：「君登矣！」郑师毕登。壬午，遂入许。许庄公奔卫。
齐侯以许让公。公曰：「君谓许不共，故从君讨之。许既伏其罪矣，虽君有命，寡人弗敢与闻。」乃与郑人。
郑伯使许大夫百里奉许叔以居许东偏，曰：「天祸许国，鬼神实不逞于许君，而假手于我寡人。寡人唯是一二父兄不能共亿，其敢以许自为功乎？寡人有弟，不能和协，而使，糊其口于四方，其况能久有许乎？吾子其奉许叔以抚柔此民也，吾将使获也佐吾子。若寡人得没于地，天其以礼悔祸于许？无宁兹许公复奉其社稷。唯我郑国之有请谒焉，如旧昏媾，其能降以相从也。无滋他族，实逼处此，以与我郑国争此土也。吾子孙其覆亡之不暇，而况能禋祀许乎？寡人之使吾子处此，不唯许国之为，亦聊以固吾圉也。」
乃使公孙获处许西偏，曰：「凡而器用财贿，无置于许。我死，乃亟去之。吾先君新邑于此，王室而既卑矣，周之子孙日失其序。夫许，大岳之胤也，天而既厌周德矣，吾其能与许争乎？」
君子谓：「郑庄公于是乎有礼。礼，经国家，定社稷，序民人，利后嗣者也。许无刑而伐之，服而舍之，度德而处之，量力而行之，相时而动，无累后人，可谓知礼矣。」
郑伯使卒出豭，行出犬鸡，以诅射颖考叔者。君子谓：「郑庄公失政刑矣。政以治民，刑以正邪，既无德政，又无威刑，是以及邪。邪而诅之，将何益矣！」
王取邬、刘、功蒍、邗之田于郑，而与郑人苏忿生之田温、原、丝希、樊、隰郕、欑茅、向、盟、州、陉、隤、怀。君子是以知桓王之失郑也。恕而行之，德之则也，礼之经也。己弗能有而以与人，人之不至，不亦宜乎？
郑、息有违言，息侯伐郑。郑伯与战于竟，息师大败而还。君子是以知息之将亡也。不度德，不量力，不亲亲，不征辞，不察有罪，犯五不韪而以伐人，其丧师也，不亦宜乎！
冬十月，郑伯以虢师伐宋。壬戌，大败宋师，以报其入郑也。宋不告命，故不书。凡诸侯有命，告则书，不然则否。师出臧否，亦如之。虽及灭国，灭不告败，胜不告克，不书于策。羽父请杀桓公，将以求大宰。公曰：「为其少故也，吾将授之矣。使营菟裘，吾将老焉。」羽父惧，反谮公于桓公而请弑之。公之为公子也，与郑人战于狐壤，止焉。郑人囚诸尹氏，赂尹氏而祷于其主钟巫，遂与尹氏归而立其主。十一月，公祭钟巫，齐于社圃，馆于寪氏。壬辰，羽父使贼弑公于寪氏，立桓公而讨寪氏，有死者。不书葬，不成丧也。', '', '', '十一年春季，滕侯和薛侯前来朝见鲁君，两人争执行礼的先后。薛侯说：“我先受封。”腾侯说：“我是成周的卜正官，薛国是外姓，我不能落后于他。”鲁隐公派羽父向薛侯商量说：“承君王和滕侯问候寡君，成周的俗话说：‘山上有树木，工匠就加以量测；宾客有礼貌，主人就加以选择。’成周的会盟，异姓在后面。寡人如果到薛国朝见，就不敢和任姓诸国并列，如果承君王加惠于我，那就希望君王同意滕侯的请求。”薛侯同意，就让滕侯先行朝礼。
夏季，隐公和郑庄公在郲地会见，策划进攻许国。郑庄公准备进攻许国时，五月十四日，在太祖庙内颁发武器。公孙阏（子都）和颍考叔争夺兵车，颍考叔挟起车辕奔跑，子都拔出戟追上去。追到大路上，没有追上，子都很愤怒。
秋季，七月，隐公会合齐僖公、郑庄公进攻许国。初一日，军队汇合攻打许城。颍考叔拿着郑庄公的旗帜“蝥弧”争先登上城墙，子都从下面用箭射他，颍考叔摔下来死了。瑕叔盈又举着“蝥弧”冲上城，向四周挥动旗帜，大喊说：“国君登城了！”于是郑国的军队全部登上了城墙。初三日，便占领了许国。许庄公逃亡到卫国。
齐僖公把许国让给隐公。隐公说：“君王说许国不交纳贡品，所以寡人才跟随君王讨伐它。许国既然已经认罪了，虽然君王有这样的好意，我也不敢参与这件事。”于是就把许国领土送给了郑庄公。
郑庄公让许国大夫百里事奉许叔住在许都的东部边邑，说：“上天降祸于许国，鬼神确实对许君不满意，而借我的手惩罚他。我这儿连一两个父老兄弟都不能和睦共处，难道敢把讨伐许国作为自己的功劳？我有个兄弟，不能和和气气共同过日子，而使他四方求食，我难道还能长久占有许国？您应当事奉许叔来安抚这里的百姓，我准备让公孙获来帮助您。假如我得以善终，上天可能又依礼而撤回加于许国的祸害，让许公再来治理他的国家。那时候只要我郑国对许国有所请求，可能还是会像对待老亲戚一样，降格而同意的。不要让别国逼近我们住的这里，来同我郑国争夺这块土地。我的子孙挽救危亡还来不及，难道还能替许国敬祭祖先吗？我让您留在这里，不仅为了许国，也是姑且巩固我的边疆。”于是就让公孙获住在许城的西部边境，对他说：“凡是你的器用财货，不要放在许国。我死后就赶紧离开这里。我祖先在这里新建城邑，眼看到周王室已经逐渐衰微，我们这些周朝的子孙一天天丢掉自己的事业。而许国，是四岳的后代，上天既然已经厌弃了成周，我哪里还能和许国竞争呢？”
君子说：“郑庄公在这件事情上合乎礼。礼，是治理国家、安定社稷、使百姓有秩序、使后代有利的大法。许国违背法度而庄公讨伐他们，服罪了就宽恕他们，揣度自己德行而决定事情，衡量自己的力量而办理事务，看准了时机而行动，不要让忧虑连累后人，可以说是懂得礼了。”
郑庄公让一百名士兵拿出一头公猪，二十五人拿出一条狗和一只鸡，来诅咒射死颍考叔的凶手。君子说：“郑庄公失掉了政和刑。政用来治理百姓，刑用来纠正邪恶。既缺乏清明的政治，又没有威严的刑法，所以才发生邪恶。已经发生邪恶而加以诅咒，有什么好处！”
周天子在郑国取得邬、刘、蒍、邘的土田，却给了郑国人原来属于苏忿生的土田：温、原、絺、樊、隰郕、攒茅、向、盟、州、陉、隤、怀。君子因此而知道桓王会失去郑国了，认为“按照恕道办事，是德的准则，礼的常规。自己不能保有，就拿来送给别人。别人不再来朝见，不也应该吗？”
郑伯与息侯因言语不和，息侯就带兵讨伐郑国，郑伯在郑国的边境迎战，息师被打得狼狼大败而回。君子们因此知道息国将要灭亡了。不考虑郑伯的德望，不衡量自己的力量，不亲近同姓的郑国（郑、息两国同姓姬），不对证言语不和的实际原因，不调查有罪之事，犯了“五大不对”却要攻伐他人，这种人丧失军队，难道不应该吗！
冬季十月，郑庄公带着虢国的军队攻打宋国。十四日，把宋国的军队打得大败，以报复宋国攻入郑国的那次战役。宋国没有前来报告这件事，所以《春秋》没有记载。凡是诸侯发生大事，前来报告就记载，不然就不记载。出兵顺利或者不顺利，也是一样。即使国家被灭亡，被灭的不报告战败，胜利的不报告战胜，也不记载在简册上。
鲁国大夫羽父请求杀掉桓公，想借此求得宰相的官职。隐公说：“从前由于他年轻的缘故，所以我代为摄政，现在我打算把国君的位子交还给他。已经派人在菟裘建筑房屋，我已经打算退休养老了。”羽父害怕了，反而在鲁桓公那里诬陷鲁隐公而请求桓公杀死隐公。
隐公还是公子的时候，曾率兵同郑国人在狐壤打仗，被俘获。郑国人把他囚禁在尹氏那里。隐公贿赂尹氏，并在尹氏所祭神主钟巫之前祷告，于是就和尹氏一起回国而在鲁国立了钟巫的神主。十一月，隐公将要祭祀钟巫，在社圃斋戒，住在寪氏那里。十五日，羽父让坏人在寪家刺杀隐公，立桓公为国君，并且讨伐寪氏，寪氏有人被杀害。《春秋》不记载安葬隐公，是由于没有按国君的规格正式为隐公举行丧礼。', NULL, '', 'indent', 1558624089, '5ce646d5c8959c0069a1b470', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642879, '左传 · 桓公 · 桓公元年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】元年春王正月，公即位。三月，公会郑伯于垂，郑伯以璧假许田。夏四月丁未，公及郑伯盟于越。秋，大水。冬十月。
【传】元年春，公即位，修好于郑。郑人请复祀周公，卒易祊田。公许之。三月，郑伯以璧假许田，为周公、祊故也。
夏四月丁未，公及郑伯盟于越，结祊成也。盟曰：「渝盟无享国。」
秋，大水。凡平原出水为大水。
冬，郑伯拜盟。
宋华父督见孔父之妻于路，目逆而送之，曰：「美而艳。」', '', '', '元年春季，鲁桓公即位，对郑国恢复友好。郑人请求重新祭祀周公、完成祊田的交换。桓公答应了。三月，郑庄公用璧玉来作许田的交易，这是为了请求祭祀周公和以祊交换许田的缘故。
夏季，四月初二日，鲁桓公和郑庄公在越地结盟，这是为了祊田的交换
表示友好。誓辞说：“如果违背盟约，就不能享有国家。”秋季，发大水，凡是平原上被水淹了叫做大水。冬季，郑庄公前来拜谢结盟。宋国的华父督在路上见到孔父的妻子，他目迎她从对面走过来，又回头
从后面盯着她走过去，说：“既美丽，又光彩动人。”', NULL, '', 'indent', 1558624129, '5ce646fe43e78c0067d8c9b8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642880, '左传 · 桓公 · 桓公二年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二年春，王正月戊申，宋督弑其君与夷及其大夫孔父。滕子来朝。三月，公会齐侯、陈侯、郑伯于稷，以成宋乱。夏四月，取郜大鼎于宋。戊申，纳于大庙。秋七月，杞侯来朝。蔡侯、郑伯会于邓。九月，入杞。公及戎盟于唐。冬，公至自唐。
【传】二年春，宋督攻孔氏，杀孔父而取其妻。公怒，督惧，遂弑殇公。
君子以督为有无君之心而后动于恶，故先书弑其君。会于稷以成宋乱，为赂故，立华氏也。
宋殇公立，十年十一战，民不堪命。孔父嘉为司马，督为大宰，故因民之不堪命，先宣言曰：「司马则然。」已杀孔父而弑殇公，召庄公于郑而立之，以亲郑。以郜大鼎赂公，齐、陈、郑皆有赂，故遂相宋公。
夏四月，取郜大鼎于宋。戊申，纳于大庙。非礼也。臧哀伯谏曰：「君人者将昭德塞违，以临照百官，犹惧或失之。故昭令德以示子孙：是以清庙茅屋，大路越席，大羹不致，粢食不凿，昭其俭也。衮、冕、黻、珽，带、裳、幅、舄，衡、紞、紘、綖，昭其度也。藻、率、鞞、革□，鞶、厉、游、缨，昭其数也。火、龙、黼、黻，昭其文也。五色比象，昭其物也。锡、鸾、和、铃，昭其声也。三辰旗旗，昭其明也。夫德，俭而有度，登降有数。文、物以纪之，声、明以发之，以临照百官，百官于是乎戒惧，而不敢易纪律。今灭德立违，而置其赂器于大庙，以明示百官，百官象之，其又何诛焉？国家之败，由官邪也。官之失德，宠赂章也。郜鼎在庙，章孰甚焉？武王克商，迁九鼎于雒邑，义士犹或非之，而况将昭违乱之赂器于大庙，其若之何？」公不听。周内史闻之曰：「臧孙达其有后于鲁乎！君违不忘谏之以德。」
秋七月，杞侯来朝，不敬，杞侯归，乃谋伐之。
蔡侯、郑伯会于邓，始惧楚也。
九月，入杞，讨不敬也。
公及戎盟于唐，修旧好也。
冬，公至自唐，告于庙也。凡公行，告于宗庙；反行，饮至、舍爵，策勋焉，礼也。
特相会，往来称地，让事也。自参以上，则往称地，来称会，成事也。
初，晋穆侯之夫人姜氏以条之役生太子，命之曰仇。其弟以千亩之战生，命之曰成师。师服曰：「异哉，君之名子也！夫名以制义，义以出礼，礼以体政，政以正民。是以政成而民听，易则生乱。嘉耦曰妃。怨耦曰仇，古之命也。今君命大子曰仇，弟曰成师，始兆乱矣，兄其替乎？」
惠之二十四年，晋始乱，故封桓叔于曲沃，靖侯之孙栾宾傅之。师服曰：「吾闻国家之立也，本大而末小，是以能固。故天子建国，诸侯立家，卿置侧室，大夫有贰宗，士有隶子弟，庶人、工、商，各有分亲，皆有等衰。是以民服事其上而下无觊觎。今晋，甸侯也，而建国。本既弱矣，其能久乎？」
惠之三十年，晋潘父弑昭侯而立桓叔，不克。晋人立孝侯。
惠之四十五年，曲沃庄伯伐翼，弑孝侯。翼人立其弟鄂侯。鄂侯生哀侯。哀侯侵陉庭之田。陉庭南鄙启曲沃伐翼。', '', '', '二年春，宋国卿大夫华父督攻打孔氏，杀死孔父而夺取其妻。宋殇公发怒，华父督惧怕，随后杀害宋殇公。君子认为华父督心里早就没有国君，然后才会产生这种邪恶，所以先记载杀害其国君。集会于稷地，为的是平定宋国混乱，由于赠送财物的缘故，便立华氏为君。
宋殇公即位后，十年间经历十一次战争，民众不堪此命运。当时孔父嘉为司马，华父督为大宰，因为民众不堪此命运，华父督就先宣传说：“这是司马造成的。”已杀害孔父嘉而后杀害宋殇公，便把庄公从郑国召回而立庄公为国君，以亲近郑国。并把郜国大鼎赠送给鲁桓公，齐国、陈国、郑国都赠送礼物，所以华父督就担任了宋国的相国。
夏四月，鲁桓公从宋国取来郜国大鼎。戊申日，置于太庙。这不符合社会行为规范。
臧哀伯劝谏说：“统治人民的人，要显扬规律堵塞违法，以治理显示百官，仍然担心有所失误，所以显扬美善的规律以示范于子孙。因此纯洁的太庙铺以茅草屋顶，大的车辆铺以草席，大的羹汤不加调料，祭祀用的粮食不加工，以显扬俭朴。礼服、礼帽、祭服、大圭、腰带、下裳、绑腿、木鞋、横木、帽带、帽垂、玉带等，要显扬其度数。五彩丝绳、丝网、刀鞘、刀鞘饰物、大带子、磨刀石、旗旒、旗缨等，要显扬其数。画火、画龙、绣黼、绣黻，要显扬其文明。五色和同于形象，要显扬其选择。锡铃、鸾铃、衡铃、旗铃等，要显扬其声音。画有日月星三辰的旌旗，要显扬其明亮。那规律，俭朴而有度，升降而有数。文明教化以治理，用声音明亮来发扬，以治理显示百官，百官于是而有戒惧而不敢改变治理之律。如今废弃规律树立违法之事，而把送来的礼器置于太庙，以明示百官，百官都来效法，还能惩罚谁呢？国家的败亡，是从官员的邪恶开始的。官府失去规律，就是宠爱与贿赂彰显。郜国的大鼎在太庙，彰显什么呢？武王攻克殷商，把九鼎迁到雒邑，有最佳行为方式的读书人或有非议，何况是将显扬违法乱纪的礼器置于太庙，这又该怎么办？”鲁桓公不听。周国的内史听说后，说：“臧孙达的后代在鲁国可能长享福禄吧。君主违礼，不忘劝谏以规律。”
秋七月，杞侯来朝见，不恭敬。杞侯归去后，桓公就策划征伐他。
蔡侯、郑伯在邓地会见，开始畏惧楚国。
九月，攻入杞国，声讨杞侯的不恭敬。
桓公与戎国人在唐地会见，是为了重修友好。冬，桓公从唐地回来，在太庙祷告。凡是国君出行，都要祷告宗庙；返回，饮食、放弃爵位、鞭策功勋，都是社会行为规范。单独相见，往来只述说地名，这是对事情的谦让。会见的国君有三个以上，那么去时就述说地方，回来就述说会见，这是成就事情。
当初，晋国穆侯的夫人姜氏在条地战役的时候生了太子，取名叫做仇。仇的兄弟在千亩战役中出生，取名叫做成师。师服说：“奇怪呀，君主替儿子取名，那取名要裁断于最佳行为方式，最佳行为方式出自于社会行为规范，社会行为规范体现于政事，政事用于端正民众。因此政事成就而民众听从，改变就会产生混乱。美好的夫妻叫做配偶，怨恨的夫妻叫做仇，这是古人命名的方法。如今君主给太子命名叫做仇，弟弟命名叫做成师，这是预兆混乱，兄弟恐怕要替代了。”
鲁惠公二十四年时，晋国开始混乱，所以封桓叔在曲沃，靖侯的孙子栾宾做师傅。师服说：“我听说国家的建立，根本大而枝节小，因此能够牢固。所以天子建立国家，诸侯建立家庭，卿大夫设置侧室，大夫有两支宗族，读书人有隶子弟，庶人、工匠、商人各有亲属，都有不同的等级。因此民众服从侍奉上级，而下面的人也不会有非分的希望或企图。如今的晋国，只是天子郊外的诸侯，而另外建国，根本既已衰弱，怎么还能长久呢？”
鲁惠公三十年时，晋国潘父杀昭侯而接纳桓叔，没有成功。晋国人立孝侯为君主。
鲁惠公四十五年时，曲沃庄伯征伐翼国，杀死孝侯。翼国人立孝侯的弟弟鄂侯为君主。鄂侯生哀侯。哀侯侵犯陉庭地方的田土。陉庭南部边境的人打开边境与曲沃共同攻伐翼国。
', NULL, '', 'indent', 1558624168, '5ce647247b968a00762a04e8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642881, '左传 · 桓公 · 桓公三年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三年春正月，公会齐侯于嬴。夏，齐侯、卫侯胥命于蒲。六月，公会杞侯于郕。秋七月壬辰朔，日有食之，既。公子翬如齐逆女。九月，齐侯送姜氏于欢。公会齐侯于欢。夫人姜氏至自齐。冬，齐侯使其弟年来聘。有年。
【传】三年春，曲沃武公伐翼，次于陉庭，韩万御戎，梁弘为右，逐翼侯于汾隰，骖絓而止。夜获之，及栾共叔。
会于嬴，成昏于齐也。
夏，齐侯、卫侯胥命于蒲，不盟也。
公会杞侯于欢，杞求成也。
秋，公子翬如齐逆女。修先君之好。故曰「公子」。
齐侯送姜氏于欢，非礼也。凡公女嫁于敌国，姊妹则上卿送之，以礼于先君，公子则下卿送之。于大国，虽公子亦上卿送之。于天子，则诸卿皆行，公不自送。于小国，则上大夫送之。
冬，齐仲年来聘，致夫人也。
芮伯万之母芮姜恶芮伯之多宠人也，故逐之，出居于魏。', '', '', '三年春季，曲沃武公进攻翼城，军队驻扎在陉庭。韩万为武公驾车，梁弘作为车右。在汾水边的低洼地追赶晋哀侯，由于骖马被绊住才停下来。夜里，俘获了晋哀侯和栾共叔。
桓公和齐僖公在嬴地会见，这是由于和齐女订婚。夏季，齐僖公、卫宣公在蒲地只是会谈，没有结盟。桓公和杞侯在郕地会见，这是由于杞国要求议和。秋季，公子翚到齐国迎接齐女，因为是重修前代国君的友好关系，所以
《春秋》称翚为“公子”。齐僖公护送姜氏出嫁，到了讙地，这是不合于礼的。凡是本国的公室女子出嫁到同等国家，如果是国君的姐妹，就由上卿护送她，以表示对前代国君的尊敬。如果是国君的女儿，就由下卿护送她。出嫁到大国，即便是国君的女儿，也由上卿护送她。嫁给天子，就由各位大臣都去护送，国君不亲自护送。出嫁到小国，就由上大夫护送她。
冬季，齐仲年前来聘问，这是为了把姜氏护送到鲁都。芮伯万的母亲芮姜嫌恶芮伯的宠姬太多，因此把他赶走，让他住到魏城。', NULL, '', 'indent', 1558624199, '5ce64745d5de2b00703db35a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642882, '左传 · 桓公 · 桓公四年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】四年春正月，公狩于郎。夏，天王使宰渠伯纠来聘。
【传】四年春正月，公狩于郎。书，时，礼也。
夏，周宰渠伯纠来聘。父在，故名。
秋，秦师侵芮，败焉，小之也。
冬，王师、秦师围魏，执芮伯以归。
', '', '', '四年春季，正月，鲁桓公在郎地打猎。《春秋》记载这件事，是由于这正是（夏历十一月）狩猎之时，合于礼。
夏季，周朝的宰官渠伯纠来鲁国聘问。由于他的父亲还活着，所以《春秋》写出他的名字。
秋季，秦国的军队袭击芮国，秦军战败，由于小看了敌人的缘故。
冬季，周桓王的军队和秦国军队联合包围芮国，俘虏了芮伯回来。', NULL, '', 'indent', 1558624234, '5ce6476830863b0068bc3395', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642883, '左传 · 桓公 · 桓公五年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】五年春正月，甲戌、己丑，陈侯鲍卒。夏，齐侯郑伯如纪。天王使仍叔之子来聘。葬陈桓公。城祝丘。秋，蔡人、卫人、陈人从王伐郑。大雩。螽。冬，州公如曹。
【传】五年春正月，甲戌，己丑，陈侯鲍卒，再赴也。于是陈乱，文公子佗杀大子免而代之。公疾病而乱作，国人分散，故再赴。
夏，齐侯、郑伯朝于纪，欲以袭之。纪人知之。
王夺郑伯政，郑伯不朝。
秋，王以诸侯伐郑，郑伯御之。
王为中军；虢公林父将右军，蔡人、卫人属焉；周公黑肩将左军，陈人属焉。
郑子元请为左拒以当蔡人、卫人，为右拒以当陈人，曰：「陈乱，民莫有斗心，若先犯之，必奔。王卒顾之，必乱。蔡、卫不枝，固将先奔，既而萃于王卒，可以集事。」从之。曼伯为右拒，祭仲足为左拒，原繁、高渠弥以中军奉公，为鱼丽之阵，先偏后伍，伍承弥缝。战于繻葛，命二拒曰：「旝动而鼓。」蔡、卫、陈皆奔，王卒乱，郑师合以攻之，王卒大败。祝聃射王中肩，王亦能军。祝聃请从之。公曰：「君子不欲多上人，况敢陵天子乎！苟自救也，社稷无陨，多矣。」
夜，郑伯使祭足劳王，且问左右。
仍叔之子，弱也。
秋，大雩，书，不时也。凡祀，启蛰而郊，龙见而雩，始杀而尝，闭蛰而烝。过则书。
冬，淳于公如曹。度其国危，遂不复。', '', '', '五年春季，正月，去年十二月二十一日，今年正月初六，陈侯鲍逝世。《春秋》所以记载两个日子，是由于发了两次讣告而日期不同。当时陈国发生动乱，文公的儿子佗杀了太子免而取代他。陈侯病危的时候动乱发生，国内臣民纷纷离散，因此发了两次讣告
夏季，齐僖公、郑庄公去纪国访问，想要乘机袭击纪国。纪国人发觉了。周桓王夺去了郑庄公的政权，郑庄公不再朝觐。
秋季，周桓王带领诸侯讨伐郑国，郑庄公出兵抵御。周桓王率领中军；虢公林父率领右军，蔡军、卫军隶属于右军；周公黑肩率左军，陈军隶属于左军。
郑国的子元建议用左方阵来对付蔡军和卫军，用右方阵来对付陈军，说：“陈国动乱，百姓都缺乏战斗意志，如果先攻击陈军，他们必定奔逃。周天子的军队看到这种情形，又一定会发生混乱。蔡国和卫国的军队支撑不住，也一定会争先奔逃。这时我们可集中兵力对付周天子的中军，我们就可以获得成功。”郑庄公听从了。曼伯担任右方阵的指挥，祭仲足担任左方阵的指挥，原繁、高渠弥带领中军护卫郑庄公，摆开了叫做鱼丽的阵势，前有偏，后有伍，伍弥补偏的空隙。
在繻葛双方交战。郑庄公命令左右两边方阵说：“大旗一挥，就击鼓进军。”郑国的军队发起进攻，蔡、卫、陈军一起奔逃，周军因此混乱。郑国的军队从两边合拢来进攻，周军终于大败。祝聃射中周桓王的肩膀，桓王还能指挥军队。祝聃请求前去追赶。郑庄公说：“君子不希望欺人太甚，哪里敢欺凌天子呢？只要能挽救自己，国家免于危亡，这就足够了。”
夜间，郑庄公派遣祭仲足去慰问周桓王，同时也问候他的左右随从。
仍叔的儿子前来聘问。《春秋》所以记为“仍叔之子”而不记他的名字，是由于他年轻。
秋季，为求雨而举行大雩祭。《春秋》记载这件事，是由于这不是按时的祭祀。凡是祭祀，昆虫惊动举行郊祭，苍龙角亢二宿出现举行雩祭，秋天寒气降临举行尝祭，昆虫蛰伏举行烝祭。如果过了规定的时间举行祭礼，就要记载。
冬季，淳于公到曹国。自己估计他的国家将发生危难，因此没有再回国了。', NULL, '', 'indent', 1558624269, '5ce647897b968a00762a08da', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642884, '左传 · 桓公 · 桓公六年 ', NULL, 8, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】六年春正月，实来。夏四月，公会纪侯于成。秋八月壬午，大阅。蔡人杀陈佗。九月丁卯，子同生。冬，纪侯来朝。
【传】六年春，自曹来朝。书曰「实来」，不复其国也。
楚武王侵随，使薳章求成焉。军于瑕以待之。随人使少师董成。斗伯比言于楚子曰：「吾不得志于汉东也，我则使然。我张吾三军而被吾甲兵，以武临之，彼则惧而协以谋我，故难间也。汉东之国随为大，随张必弃小国，小国离，楚之利也。少师侈，请羸师以张之。」熊率且比曰：「季梁在，何益？」斗伯比曰：「以为后图，少师得其君。」王毁军而纳少师。
少师归，请追楚师，随侯将许之。季梁止之曰：「天方授楚，楚之蠃，其诱我也，君何急焉？臣闻小之能敌大也，小道大淫。所谓道，忠于民而信于神也。上思利民，忠也；祝史正辞，信也。今民馁而君逞欲，祝史矫举以祭，臣不知其可也。」公曰：「吾牲牷肥腯，粢盛丰备，何则不信？」对曰：「夫民，神之主也。是以圣王先成民而后致力于神。故奉牲以告曰『博硕肥腯』，谓民力之普存也，谓其畜之硕大蕃滋也，谓其不疾瘯蠡也，谓其备腯咸有也。奉盛以告曰『洁粢丰盛』，谓其三时不害而民和年丰也。奉酒醴以告曰『嘉栗旨酒』，谓其上下皆有嘉德而无违心也。所谓馨香，无谗慝也。故务其三时，修其五教，亲其九族，以致其禋祀。于是乎民和而神降之福，故动则有成。今民各有心，而鬼神乏主，君虽独丰，其何福之有！君姑修政而亲兄弟之国，庶免于难。」随侯惧而修政，楚不敢伐。
夏，会于成，纪来咨谋齐难也。
北戎伐齐，齐侯使乞师于郑。郑大子忽帅师救齐。六月，大败戎师，获其二帅大良、少良，甲首三百，以献于齐。于是，诸侯之大夫戍齐，齐人馈之饩，使鲁为其班，后郑。郑忽以其有功也，怒，故有郎之师。
公之未昏于齐也，齐侯欲以文姜妻郑大子忽。大子忽辞，人问其故，大子曰：「人各有耦，齐大，非吾耦也。《诗》云：『自求多福。』在我而已，大国何为？」君子曰：「善自为谋。」及其败戎师也，齐侯又请妻之，固辞。人问其故，大子曰：「无事于齐，吾犹不敢。今以君命奔齐之急，而受室以归，是以师昏也。民其谓我何？」遂辞诸郑伯。
秋，大阅，简车马也。
九月丁卯，子同生，以大子生之礼举之，接以大牢，卜士负之，士妻食之。公与文姜、宗妇命之。
公问名于申繻。对曰：「名有五，有信，有义，有象，有假，有类。以名生为信，以德命为义，以类命为象，取于物为假，取于父为类。不以国，不以官，不以山川，不以隐疾，不以畜牲，不以器币。周人以讳事神，名，终将讳之。故以国则废名，以官则废职，以山川则废主，以畜牲则废祀，以器币则废礼。晋以僖侯废司徒，宋以武公废司空，先君献，武废二山，是以大物不可以命。」公曰：「是其生也，与吾同物，命之曰同。」
冬，纪侯来朝，请王命以求成于齐，公告不能。


', '', '', '六年春季，（淳于公）从曹国前来朝见。《春秋》记载作“实来”，是由于他真正不再回国了。
楚武王入侵随国，先派薳章去求和，把军队驻在瑕地以等待结果。随国人派少师主持和谈。
鬬伯比对楚武王说：“我国在汉水东边不能达到目的，是我们自己造成的。我们扩大军队，整顿装备，用武力逼迫别国，他们害怕因而共同来对付我们，所以就难于离间了。在汉水东边的国家中，随国最大。随国要是自高自大，就必然抛弃小国。小国离心，对楚国有利。少师这个人很骄傲，请君王隐藏我军的精锐，而让他看到疲弱的士卒，助长他的骄傲。”熊率且比说：“有季梁在，这样做有什么好处？”鬬伯比说：“这是为以后打算，因为少师可以得到他们国君的信任。”楚武王故意把军容弄得疲疲塌塌来接待少师。
少师回去，请求追逐楚军。随侯将要答应，季梁劝阻说：“上天正在帮助楚国，楚国军队显得疲塌的样子，是引诱我们。君王何必急于从事？下臣听说小国之所以能够抵抗大国，是小国有道，而大国君主沉溺于私欲。所谓道，就是忠于百姓而取信于神明。上边的人想到对百姓有利，这是忠；祝史真实不欺地祝祷，这是信。现在百姓饥饿而国君放纵个人享乐，祝史浮夸功德来祭祀，下臣不知怎样行得通？”随侯说：“我祭祀用的牲口都既无杂色，又很肥大，黍稷也都丰盛完备，为什么不能取信于神明？”季梁回答说：“百姓，是神明的主人。因此圣王先团结百姓，而后才致力于神明，所以在奉献牺牲的时候祝告说：‘牲口又大又肥。’这是说百姓的财力普遍富足，牲畜肥大而繁殖生长，并没有得病而瘦弱，又有各种优良品种。在奉献黍稷的时候祷告说：‘洁净的粮食盛得满满的。’这是说春、夏、秋三季没有天灾，百姓和睦而收成很好。在奉献甜酒的时候祝告说：‘又好又清的美酒。’这是说上上下下都有美德而没有坏心眼。所谓的祭品芳香，就是人心没有邪念。因为春、夏、秋三季都努力于农耕，修明五教，敦睦九族，用这些行为来致祭神明，百姓便和睦，神灵也降福，所以做任何事情都能成功。现在百姓各有各的想法，鬼神没有依靠，君王一个人祭祀丰富，又能求得什么福气呢？君王姑且修明政治，亲近兄弟国家，看能否免于祸难。”随侯害怕了，从而修明政治，楚国就没有敢来攻打。
夏季，鲁桓公和纪侯在成地相会。这是由于纪侯前来商谈如何对付齐国灭纪的企图。
北戎进攻齐国，齐国派人到郑国求援。郑国的太子忽率领军队救援齐国。六月，大败戎军，俘虏了它的两个主帅大良、少良，砍了带甲戎军三百人的脑袋，献给齐国。当时，诸侯的大夫在齐国防守边境，齐国人馈送他们食物，让鲁国来确定致送各国军队的先后次序。鲁国因依照周王朝所定的次序，把郑国排在后面。郑太子忽认为自己有功劳，很恼怒，所以四年之后就有郎地的战役。
桓公在没有向齐国求婚以前，齐僖公想把文姜嫁给太子忽。太子忽辞谢，别人问为什么，太子忽说：“人人都有合适的配偶，齐国强大，不是我的配偶。《诗》说：‘求于自己，多受福德。’靠我自己就是了，要大国干什么？”君子说：“太子忽善于为自己打算。”等到他打败了戎军，齐僖公又请求把别的女子嫁给他。太子忽坚决辞谢，别人问为什么，太子忽说：“我为齐国
没有做什么事情，尚且不敢娶他们的女子。现在由于国君的命令急忙地到齐国解救危急，反而娶了妻子回国，这是利用战争而成婚，百姓将会对我有什么议论呢？”于是就用郑庄公的名义辞谢了。
没有做什么事情，尚且不敢娶他们的女子。现在由于国君的命令急忙地到齐国解救危急，反而娶了妻子回国，这是利用战争而成婚，百姓将会对我有什么议论呢？”于是就用郑庄公的名义辞谢了。
九月二十四日，儿子同出生，举行太子出生的礼仪：父亲接见儿子时用牛、羊、豕各一的太宰，用占卜选择士人背他，用占卜选择士人的妻子给他喂奶，桓公和文姜、同宗妇人为他取名字。
桓公向申繻询问取名字的事。申繻回答说：“取名有五种方式，有信，有义，有像，有假，有类。用出生的某一种情况来命名是信，用祥瑞的字眼来命名是义，用相类似的字眼来命名是像，假借某种事物的名称来命名是假，借用和父亲有关的字眼来命名是类。命名不用国名，不用官名，不用山川名，不用疾病名，不用牲畜名，不用器物礼品名。周朝人用避讳来奉事神明，名，在死了以后就要避讳。所以用国名命名，就会废除人名，用官名命名就会改变官称，用山川命名就会改变山川的神名，用牲畜命名就会废除祭祀，用器物礼品命名就会废除礼仪。晋国因为僖公而废除司徒之官，宋国因为武公而废除司空之官名，我国因为先君献公、武公而废除具山、敖山二山之名，所以大的事物不可以用来命名。”桓公说：“这孩子的出生，和我在同一个干支，把他命名叫做同。”
冬季，纪侯前来朝见，请求鲁国代纪国取得周天子的命令去向齐国求和。桓公告诉他说自己做不到。', NULL, '', 'indent', 1558624310, '5ce647b043e78c0067d8d22b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642885, '左传 · 桓公 · 桓公七年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】七年春二月己亥，焚咸丘。夏，谷伯绥来朝。邓侯吾离来朝。
【传】七年春，谷伯、邓侯来朝。名，贱之也。
夏，盟、向求成于郑，既而背之。
秋，郑人、齐人、卫人伐盟、向。王迁盟、向之民于郏。
冬，曲沃伯诱晋小子侯，杀之。


', '', '', '七年春季，穀伯绥、邓侯吾离来鲁国朝见。《春秋》记载他们的名字，是由于轻视他们。
夏季，盟邑、向邑向郑国求和，不久又背叛郑国。
秋季，郑军、齐军、卫军攻打盟邑、向邑。周桓王把盟邑、向邑的百姓迁到郏地。
冬季，曲沃伯诱骗晋国小子侯，把他杀死了。', NULL, '', 'indent', 1558624340, '5ce647d2a673f50068da5b10', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642886, '左传 · 桓公 · 桓公八年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】八年春正月己卯，烝。天王使家父来聘。夏五月丁丑，烝秋，伐邾。冬十月，雨雪。祭公来，遂逆王后于纪。
【传】八年春，灭翼。
随少师有宠。楚斗伯比曰：「可矣。仇有衅，不可失也。」
夏，楚子合诸侯于沈鹿。黄、随不会，使薳章让黄。楚子伐随，军于汉、淮之间。
季梁请下之：「弗许而后战，所以怒我而怠寇也。」少师谓随侯曰：「必速战。不然，将失楚师。」随侯御之，望楚师。季梁曰：「楚人上左，君必左，无与王遇。且攻其右，右无良焉，必败。偏败，众乃携矣。」少师曰：「不当王，非敌也。」弗从。战于速杞，随师败绩。随侯逸，斗丹获其戎车，与其戎右少师。
秋，随及楚平。楚子将不许，斗伯比曰：「天去其疾矣，随未可克也。」乃盟而还。
冬，王命虢仲立晋哀侯之弟缗于晋。
祭公来，遂逆王后于纪，礼也。


', '', '', '八年春季，曲沃伯灭亡了翼邑。随国少师受到宠信。楚国的鬬伯比说：“可以了，敌国内部有了裂痕，不可以失掉机会。”
夏季，楚武王在沈鹿会合诸侯的军队。黄、随两国不参加会见。楚武王派薳章去责备黄国，然后亲自讨伐随国，军队驻扎在汉水、淮水之间。
季梁建议向楚人表示投降，说：“等他们不肯，然后作战，这样就可以激怒我军而使敌军懈怠。”少师对随侯说：“必须速战，不这样，就会丢失战胜楚军的机会。”随侯率军抵御楚军。远望楚国的军队，季梁说：“楚人以左为尊，国君一定在左军之中，不要和楚王正面作战，姑且攻击他的右军。右军没有好指挥官，必然失败。他们的偏军一败，大众就离散了。”少师说：“不与楚王正面作战，这就表示我们和他不能对等。”随侯又没有听从季梁的话。在速杞交战，随军大败。随侯逃走，鬬丹俘获了随侯的战车和车右少师。
秋季，随国要同楚国讲和。楚武王本拟不同意。鬬伯比说：“上天已经铲除他们讨厌的少师了，但随国还不可能战胜。”于是订立了盟约而回国。冬季，周桓王命令虢仲立了晋哀侯的兄弟缗为晋侯。祭公到鲁国来，然后到纪国迎接王后，这是合于礼的。', NULL, '', 'indent', 1558624379, '5ce647f9ba39c8006843166b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642901, '左传 · 庄公 · 庄公五年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】五年春王正月。夏，夫人姜氏如齐师。秋，郳犁来来朝。冬，公会齐人、宋人、陈人、蔡人伐卫。
【传】五年秋，郳犁来来朝，名，未王命也。
冬，伐卫纳惠公也。


', '', '', '', NULL, '', 'indent', 1558624906, '5ce64a08a673f50068da7b68', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642888, '左传 · 桓公 · 桓公十年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十年春王正月，庚申，曹伯终生卒。夏五月，葬曹桓公。秋，公会卫侯于桃丘，弗遇。冬十有二月丙午，齐侯、卫侯、郑伯来战于郎。
【传】十年春，曹桓公卒。
虢仲谮其大夫詹父于王。詹父有辞，以王师伐虢。夏，虢公出奔虞。
秋，秦人纳芮伯万于芮。
初，虞叔有玉，虞公求旃。弗献。既而悔之。曰：「周谚有之：『匹夫无罪，怀璧其罪。』吾焉用此，其以贾害也？」乃献。又求其宝剑。叔曰：「是无厌也。无厌，将及我。」遂伐虞公，故虞公出奔共池。
冬，齐、卫、郑来战于郎，我有辞也。
初，北戎病齐，诸侯救之。郑公子忽有功焉。齐人饩诸侯，使鲁次之。鲁以周班后郑。郑人怒，请师于齐。齐人以卫师助之。故不称侵伐。先书齐、卫，王爵也。
', '', '', '十年春季，曹桓公逝世。
虢仲在周桓王那里进谗言诬陷大夫詹父。詹父有理，带领周天子的军队进攻虢国。夏季，虢公逃亡到虞国。
秋季，秦国人把芮伯万送回芮国。
当初，虞公的兄弟虞叔藏有宝玉，虞公向他索求玉。虞叔没有进献，不久又后悔这件事，说：“周朝的谚语说：‘百姓没有罪，怀藏玉璧就有了罪。’我哪用得着美玉，难道要用它买来祸害？”于是就把玉璧献给了虞公。虞公又向虞叔索求宝剑。虞叔说：“这是没有满足了。满足不了，祸害会连累到我身上。”于是就攻打虞公，所以虞公逃亡到共池。
冬季，齐国、卫国、郑国联军前来和我军在郎地作战，我国是有理的。
当初，北戎多次骚扰齐国，使它困疲，诸侯救援齐国，郑国的公子忽有功劳。齐国人给诸侯的军队馈送食物，让鲁国确定馈送的次序。鲁国按周室封爵的次序把郑国排在后面。郑国人发怒，请求齐国出兵。齐国人率领卫国军队帮助郑国，所以《春秋》不称这次战争为“侵伐”。先记载齐国和卫国，是按照周室封爵的次序。
', NULL, '', 'indent', 1558624463, '5ce6484dd5de2b00703dc1d2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642889, '左传 · 桓公 · 桓公十一年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有一年春正月，齐人、卫人、郑人盟于恶曹。夏五月癸未，郑伯寤生卒。秋七月，葬郑庄公。九月，宋人执郑祭仲。突归于郑。郑忽出奔卫。柔会宋公、陈侯、蔡叔盟于折。公会宋公于夫钟。冬十月有二月，公会宋公于阚。
【传】十一年春，齐、卫、郑、宋盟于恶曹。
楚屈瑕将盟贰、轸。郧人军于蒲骚，将与随、绞、州、蓼伐楚师。莫敖患之。斗廉曰：「郧人军其郊，必不诫，且日虞四邑之至也。君次于郊郢，以御四邑。我以锐师宵加于郧，郧有虞心而恃其城，莫有斗志。若败郧师，四邑必离。」莫敖曰：「盍请济师于王？」对曰：「师克在和，不在众。商、周之不敌，君之所闻也。成军以出，又何济焉？」莫敖曰：「卜之？」对曰：「卜以决疑，不疑何卜？」遂败郧师于蒲骚，卒盟而还。郑昭公之败北戎也，齐人将妻之，昭公辞。祭仲曰：「必取之。君多内宠，子无大援，将不立。三公子皆君也。」弗从。
夏，郑庄公卒。
初，祭封人仲足有宠于庄公，庄公使为卿。为公娶邓曼，生昭公，故祭仲立之。宋雍氏女于郑庄公，曰雍姞，生厉公。雍氏宗有宠于宋庄公，故诱祭仲而执之，曰：「不立突，将死。」亦执厉公而求赂焉。祭仲与宋人盟，以厉公归而立之。
秋九月丁亥，昭公奔卫。己亥，厉公立。
', '', '', '十一年春季，齐国、卫国、郑国、宋国在恶曹举行会盟。
楚国的屈瑕打算和贰、轸两国结盟。郧国人的军队驻扎在蒲骚，准备和随、绞、州、蓼四国一起进攻楚国军队。莫敖担心这件事。鬬廉说：“郧国的军队驻扎在他们的郊区，一定缺乏警戒，并且天天盼望四国军队的来到。您驻在郊郢来抵御这四个国家，我们用精锐部队夜里进攻郧国。郧国一心盼望四国军队，而且又依仗城郭坚固，没有人再有战斗意志。如果打败郧军，四国一定离散。”莫敖说：“何不向君王请求增兵？”鬬廉回答说：“军队能够获胜，在于团结一致，不在于人多。商朝敌不过周朝，这是您所知道的。整顿军队而出兵，又增什么兵呢？”莫敖说：“占卜一下？”鬬廉回答说：“占卜是为了决断疑惑，没有疑惑，为什么占卜？”于是就在蒲骚打败郧国军队，终于和贰、轸两国订立了盟约回国。
郑昭公打败北戎的时候，齐侯打算把女儿嫁给他，昭公辞谢了。祭仲说：“您一定要娶她。国君姬妾很多，您如果没有有力的外援，将不能继承君位。其他三位公子都可能做国君的。”昭公不同意。
夏季，郑庄公死。
当初，祭地封人仲足受到郑庄公的宠信，庄公任命他做卿。祭仲为庄公娶了邓曼，生了昭公。所以祭仲立他为国君。宋国的雍氏把女儿嫁给郑庄公，名叫雍姞，生了厉公。雍氏为人所尊重，受到宋庄公的宠爱，所以就诱骗祭仲而把他抓起来，说：“不立突为国君，就没有你的命。”雍氏还抓了厉公索取财货。祭仲和宋国人结盟，让厉公归国而立他为国君。
秋季，九月十三日，郑昭公逃亡到卫国。二十五日，郑厉公立为国君。', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b6afab6a81d0c538da0bb", "shortContent": " 正确处理经与权、常与变之间的关系，是《春秋》公羊学所着力探索的一大问题。知经善权、守常应变甚至构成了公羊家评论历史事件和人物的基本方法。范晔在《后汉书·贾逵传》中说，《春秋公羊传》一向“多任于权、变”。\n\n公羊家之所以赞扬祭仲“贤”，是因为他“知权”。郑国的庄公在临终之前，欲立次子突，大夫祭仲以废长立幼、国家必乱为理由加以反对。庄公薨，忽即位为昭公。突的母亲雍姞是宋大夫雍氏之女，《左传》说，雍氏...", "authors": ["余治平"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558624497, '5ce6486fa673f50068da616f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642890, '左传 · 桓公 · 桓公十二年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有二年春正月。夏六月壬寅，公会杞侯、莒子盟于曲池。秋七月丁亥，公会宋公、燕人盟于谷丘。八月壬辰，陈侯跃卒。公会宋公于虚。冬十有一月，公会宋公于龟。丙戌，公会郑伯，盟于武父。丙戌，卫侯晋卒。十有二月，及郑师伐宋。丁未，战于宋。
【传】十二年夏，盟于曲池，平杞、莒也。
公欲平宋、郑。秋，公及宋公盟于句渎之丘。宋成未可知也，故又会于虚。冬，又会于龟。宋公辞平，故与郑伯盟于武父。遂帅师而伐宋，战焉，宋无信也。
君子曰：「苟信不继，盟无益也。《诗》云：『君子屡盟，乱是用长。』无信也。」
楚伐绞，军其南门。莫敖屈瑕曰：「绞小而轻，轻则寡谋，请无扞采樵者以诱之。」从之。绞人获三十人。明日，绞人争出，驱楚役徒于山中。楚人坐其北门，而覆诸山下，大败之，为城下之盟而还。
伐绞之役，楚师分涉于彭。罗人欲伐之，使伯嘉谍之，三巡数之。
', '', '', '十二年，夏季，鲁桓公和杞侯、莒子在曲池会盟，这是让杞国和莒国讲和。
桓公想和宋国、郑国讲和。秋季，桓公和宋庄公在句渎之丘会盟。由于不知道宋国对议和有无诚意，所以又在虚地会见；冬季，又在龟地会见。宋公拒绝议和，所以桓公和郑厉公在武父结盟，盟后就率领军队进攻宋国。发生这场战争，是因为宋国不讲信用。
君子说：“如果一再不讲信用，结盟也没有好处。《诗经》说：‘君子多次结盟，反而使动乱滋长。’就是由于没有信用。”
楚国进攻绞国，军队驻扎在南门。莫敖屈瑕说：“绞国地小而人轻浮，轻浮就缺少主意。请对砍柴的人不设保卫，用这引诱他们。”楚王听从了屈瑕的意见。绞军俘获了三十个砍柴人。第二天，绞军争着出城，把楚国的砍柴人赶到山里。楚军坐等在北门，同时在山下设伏兵，大败绞军，强迫绞国订立城下之盟而回国。
在进攻绞国的这次战役中，楚军分兵渡过彭水。罗国准备攻打楚军，派遣伯嘉去侦探，三次遍数了楚军的人数。', NULL, '', 'indent', 1558624530, '5ce6489043e78c0067d8de2f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642891, '左传 · 桓公 · 桓公十三年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有三年春二月，公会纪侯、郑伯。己巳，及齐侯、宋公、卫侯、燕人战。齐师、宋师、卫师、燕师败绩。三月，葬卫宣公。夏，大水。秋七月。冬十月。
【传】十三年春，楚屈瑕伐罗，斗伯比送之。还，谓其御曰：「莫敖必败。举趾高，心不固矣。」遂见楚子曰：「必济师。」楚子辞焉。入告夫人邓曼。邓曼曰：「大夫其非众之谓，其谓君抚小民以信，训诸司以德，而威莫敖以刑也。莫敖狃于蒲骚之役，将自用也，必小罗。君若不镇抚，其不设备乎？夫固谓君训众而好镇抚之，召诸司而劝之以令德，见莫敖而告诸天之不假易也。不然，夫岂不知楚师之尽行也？」楚子使赖人追之，不及。
莫敖使徇于师曰：「谏者有刑。」及鄢，乱次以济。遂无次，且不设备。及罗，罗与卢戎两军之。大败之。莫敖缢于荒谷，群帅囚于冶父以听刑。楚子曰：「孤之罪也。」皆免之。
宋多责赂于郑，郑不堪命。故以纪、鲁及齐与宋、卫、燕战。不书所战，后也。
郑人来请修好。', '', '', '十三年春季，楚国的屈瑕进攻罗国，鬬伯比为他送行。回来时，对他的御者说：“莫敖一定失败。走路把脚抬得很高，表明他的心神不稳定了。”
于是进见楚武王，说：“一定要增派军队！”楚武王拒绝了，回宫告诉夫人邓曼。邓曼说：“大夫鬬伯比的意思不在人数的多少，而是说君王要以诚信来镇抚百姓，以德义来训诫官员，而以刑法来使莫敖畏惧。莫敖已经满足于蒲骚这一次战功，他会自以为是，必然轻视罗国。君王如果不加控制，不是等于不设防范吗！鬬伯比所说的请君王训诫百姓而好好地安抚督察他们，召集官员们而勉之以美德，见到莫敖而告诉他上天对他的过错是不会宽恕的。
不是这样，鬬大夫难道不知道楚国军队已经全部出发了？”楚王派赖国人追赶屈瑕，没有追上。
莫敖派人在军中通告：“敢于进谏的人要受刑罚！”到达鄢水，楚军由于渡河而次序大乱。全军乱七八糟毫无秩序，而且又不设防。到达罗国，罗国和卢戎的军队从两边夹攻楚军，把楚军打得大败。莫敖吊死在荒谷，其他将领们被囚禁在冶父，等待处罚。楚武王说：“这是我的罪过。”把将领们都赦免了。
宋国多次向郑国索取财货，郑国实在不能忍受，所以率领纪、鲁两国的军队和齐、宋、卫、燕四国的军队交战。《春秋》没有记载战争的地点，是由于桓公迟到了。
郑国派人来鲁国，请求重修旧好。', NULL, '', 'indent', 1558624564, '5ce648b2c8959c0069a1d389', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642892, '左传 · 桓公 · 桓公十四年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有四年春正月，公会郑伯于曹。无冰。夏五，郑伯使其弟语来盟。秋八月壬申，御廪灾。乙亥，尝。冬十有二月丁巳，齐侯禄父卒。宋人以齐人、蔡人、卫人、陈人伐郑。
【传】十四年春，会于曹。曹人致饩，礼也。
夏，郑子人来寻盟，且修曹之会。
秋八月壬申，御廪灾。乙亥，尝。书，不害也。
冬，宋人以诸侯伐郑，报宋之战也。焚渠门，入，及大逵。伐东郊，取牛首。以大宫之椽归，为卢门之椽。', '', '', '十四年春季，鲁桓公和郑厉公在曹国会见。曹国人送来食物，这是合于礼的。
夏季，郑国的子人前来重温过去盟会的友好，并且也是重温在曹国的会见。
秋季，八月十五日，储藏祭祀谷物的仓库发生火灾。十八日，举行尝祭。《春秋》所以记载这件事，是表示火灾尚不足为害。
冬季，宋国人联合诸侯进攻郑国，这是为了报复在宋国的那次战争。诸侯联军焚烧了郑国都城的渠门，进了城到了大街上，攻打东郊，占取牛首，把郑国太庙的椽子拿回去做宋国卢门的椽子。 ', NULL, '', 'indent', 1558624592, '5ce648ceba39c8006843214c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642893, '左传 · 桓公 · 桓公十五年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有五年春二月，天王使家父来求车。三月乙未，天王崩。夏四月己巳，葬齐僖公。五月，郑伯突出奔蔡。郑世子忽复归于郑。许叔入于许。公会齐侯于艾。邾人、牟人、葛人来朝。秋九月，郑伯突入于栎。冬十有一月，公会宋公、卫侯、陈侯于衰，伐郑。
【传】十五年春，天王使家父来求车，非礼也。诸侯不贡车、服，天子不私求财。
祭仲专，郑伯患之，使其婿雍纠杀之。将享诸郊。雍姬知之，谓其母曰：「父与夫孰亲？」其母曰：「人尽夫也，父一而已，胡可比也？」遂告祭仲曰：「雍氏舍其室而将享子于郊，吾惑之，以告。」祭仲杀雍纠，尸诸周氏之汪。公载以出，曰：「谋及妇人，宜其死也。」夏，厉公出奔蔡。
六月乙亥，昭公入。
许叔入于许。
公会齐侯于艾，谋定许也。
秋，郑伯因栎人杀檀伯，而遂居栎。
冬，会于衰，谋伐郑，将纳厉公也。弗克而还。', '', '', '十五年春季，周桓王派大夫家父来鲁国索取车辆，这是不合于礼的。诸侯不进贡车辆、礼服，天子不求取个人财物。
祭仲专权，郑厉公对他很担心，派祭仲的女婿雍纠去杀他。雍纠准备在郊外宴请祭仲。雍姬知道了，对她母亲说：“父亲与丈夫哪一个更亲近？”她母亲说：“任何男子，都可能成为一个女人的丈夫，父亲却只有一个，怎么能够相比呢？”于是雍姬就告诉祭仲说：“雍氏不在他家里而在郊外宴请您，我怀疑这件事，所以告诉您。”祭仲就杀了雍纠，把尸体摆在周氏的池塘边。郑厉公装载了尸体逃离郑国，说：“大事和妇女商量，死得活该。”
夏季，郑厉公逃亡到蔡国。六月二十二日，郑昭公进入郑国。许叔进入许国都城。桓公和齐襄公在艾地会见，目的是为了谋划安定许国。
秋季，郑厉公凭借栎地的人杀了檀伯，因而就居住在栎地。
冬季，鲁桓公与宋庄公、卫惠公、陈庄公在袲地会见，策划进攻郑国，以便护送厉公回国。可是战争失败了，军队各自回国。', NULL, '', 'indent', 1558624631, '5ce648f27b968a00762a18f0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643532, '月令七十二候集解 · 秋分', NULL, 0, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '秋分，八月中。解见春分。
雷始收声。鲍氏曰：雷二月阳中发声，八月阴中收声入地，则万物随入也。
蛰虫坏【音培】户。淘瓦之泥曰坏，细泥也。按《礼记注》曰：坏益其蛰穴之户，使通明处稍小，至寒甚乃墐塞之也。
水始涸。《礼记注》曰：水本气之所为，春夏气至故长，秋冬气返故涸也。', '', '', '', NULL, '', 'indent', 1574374959, '5db29d09eaa375006ced9801', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642894, '左传 · 桓公 · 桓公十六年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有六年春正月，公会宋公、蔡侯、卫侯于曹。夏四月，公会宋公、卫侯、陈侯、蔡侯伐郑。秋七月，公至自伐郑。冬，城向。十有一月，卫侯朔出奔齐。
【传】十六年春正月，会于曹，谋伐郑也。
夏，伐郑。
秋七月，公至自伐郑，以饮至之礼也。
冬，城向，书，时也。
初，卫宣公烝于夷姜，生急子，属诸右公子。为之娶于齐，而美，公取之，生寿及朔，属寿于左公子。夷姜缢。宣姜与公子朔构急子。公使诸齐，使盗待诸莘，将杀之。寿子告之，使行。不可，曰：「弃父之命，恶用子矣！有无父之国则可也。」及行，饮以酒，寿子载其旌以先，盗杀之。急子至，曰：「我之求也。此何罪？请杀我乎！」又杀之。二公子故怨惠公。
十一月，左公子泄、右公子职立公子黔牟。惠公奔齐。', '', '', '十六年春季，正月，鲁桓公和宋庄公、蔡桓侯、卫惠公在曹国会见，又策划进攻郑国。
夏季，进攻郑国。
秋季七月，桓公进攻郑国回到国内，举行了祭告宗庙、大宴臣下的礼仪。
冬季，在向地筑城。《春秋》所以记载这件事，是由于不妨碍农时。
当初，卫宣公和父亲的姬妾夷姜私通，生了急子。卫宣公把急子托给右公子抚养，又为他在齐国娶妻，这个女人很美，卫宣公就自己娶了她，生了寿和朔，把寿嘱托给左公子。夷姜自己吊死了。宣姜和公子朔诬陷急子。卫宣公派急子出使到齐国，指使坏人在莘地等着，打算杀死他。寿子把这件事告诉急子，让他逃走。急子不同意说：“丢掉父亲的命令，哪里还用得着儿子！如果世界上有没有父亲的国家就可以逃到那里去了。”等到临走，寿子用酒把急子灌醉。寿子车上插着太子的旗帜走在前面，坏人就杀了寿子。急子赶到，说：“他们要杀的是我。他有什么罪？请杀死我吧！”坏人又杀了急子。左、右两公子因此怨恨惠公。十一月，左公子泄、右公子职立公子黔牟为国君。卫惠公逃亡到齐国。', NULL, '', 'indent', 1558624668, '5ce6491943e78c0067d8e3c5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642895, '左传 · 桓公 · 桓公十七年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有七年春正月丙辰，公会齐侯、纪侯盟于黄。二月丙午，公会邾仪父，盟于趡。夏五月丙午，及齐师战于奚。六月丁丑，蔡侯封人卒。秋八月，蔡季自陈归于蔡。癸巳，葬蔡桓侯。及宋人、卫人伐邾。冬十月朔，日有食之。
【传】十七年春，盟于黄，平齐、纪，且谋卫故也。
乃邾仪父盟于趡，寻蔑之盟也。
夏，及齐师战于奚，疆事也。于是齐人侵鲁疆，疆吏来告，公曰：「疆场之事，慎守其一，而备其不虞。姑尽所备焉。事至而战，又何谒焉？」
蔡桓侯卒。蔡人召蔡季于陈。
秋，蔡季自陈归于蔡，蔡人嘉之也。
伐邾，宋志也。
冬十月朔，日有食之。不书日，官失之也。天子有日官，诸侯有日御。日官居卿以底日，礼也。日御不失日，以授百官于朝。
初，郑伯将以高渠弥为卿，昭公恶之，固谏，不听，昭公立，惧其杀己也。辛卯，弑昭公，而立公子亹。
君子谓昭公知所恶矣。公子达曰：「高伯其为戮乎？复恶已甚矣。」', '', '', '十七年春季，鲁桓公和齐襄公、纪侯在黄地结盟，目的是为了促成齐、纪的和议，同时商量对付卫国。桓公和邾仪父在趡地结盟，这是由于重申蔑地的盟约。夏季，鲁军与齐国军队在奚地发生战争，这是边境局部冲突。当时齐国
人入侵鲁国的边境，边境官吏前来报告。桓公说：“边境上的事情，谨慎地防守自己一边而且防备发生意外。暂且尽力防备就是了。发生了事情就迎战，又何必先行请示报告呢？”
蔡桓侯去世了，蔡国人把蔡季从陈国召回来。秋季，蔡季从陈国回到蔡国，被立为国君，因为蔡国人都拥护他。进攻邾国，这是宋国的意愿。冬季，十月初一，日蚀。《春秋》没有记载日子，这是史官的漏记。天
子有日官，诸侯有日御。日官居于卿的地位，以推算历象，这是合于礼的。日御详细记载每月大小和干支，无所遗漏，在朝廷上通告百官。
当初，郑庄公准备任命高渠弥做卿，昭公讨厌他，坚决劝阻，庄公不听从。昭公即位后，高渠弥畏惧昭公会杀掉自己，就在十月二十二日，杀死昭公而立公子亹。
君子认为“昭公了解他所讨厌的人”。公子达说：“高伯恐怕要被诛杀的吧！因为他报仇报得太过分了。”', NULL, '', 'indent', 1558624704, '5ce6493dd5de2b00703dd77b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642896, '左传 · 桓公 · 桓公十八年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有八年春王正月，公会齐侯于泺。公与夫人姜氏遂如齐。夏四月丙子，公薨于齐。丁酉，公之丧至自齐。秋七月，冬十有二月己丑，葬我君桓公。
【传】十八年春，公将有行，遂与姜氏如齐。申繻曰：「女有家，男有室，无相渎也，谓之有礼。易此，必败。」
公会齐侯于泺，遂及文姜如齐。齐侯通焉。公谪之，以告。
夏四月丙子，享公。使公子彭生乘公，公薨于车。
鲁人告于齐曰：「寡君畏君之威，不敢宁居，来修旧好，礼成而不反，无所归咎，恶于诸侯。请以彭生除之。」齐人杀彭生。
秋，齐侯师于首止；子亹会之，高渠弥相。七月戊戌，齐人杀子亹而轘高渠弥，祭仲逆郑子于陈而立之。是行也，祭仲知之，故称疾不往。人曰：「祭仲以知免。」仲曰：「信也。」
周公欲弑庄王而立王子克。辛伯告王，遂与王杀周公黑肩。王子克奔燕。
初，子仪有宠于桓王，桓王属诸周公。辛伯谏曰：「并后、匹嫡、两政、耦国，乱之本也。」周公弗从，故及。', '', '', '十八年春季，鲁桓公准备外出旅行，便和姜氏到齐国去。申繻劝阻说：“女人有夫家，男人有妻室，不可以互相轻慢，这就叫有礼。违反这一点必然坏事。”桓公和齐襄公在泺地会见，然后就和文姜到了齐国。齐襄公和文姜通奸。桓公责怪文姜，文姜把这件事告诉了齐襄公。
夏季，四月初十日，齐襄公设宴招待鲁桓公。宴后齐襄公派公子彭生帮助桓公登车，桓公死在车中。
鲁国人告诉齐襄公说：“我们国君畏惧您的威严，不敢苟安，来到贵国重修旧好，礼仪完成后却没有回国。我国不知道该归罪于谁，在诸侯中造成了恶劣影响。请求用彭生来清除这种影响。”齐国人杀死了彭生。
秋季，齐襄公率领军队驻扎在首止。子亹前去会见，高渠弥作为首席随员。七月初三日，齐国人杀死了子亹而把高渠弥五马分尸。祭仲到陈国迎接郑子而立他为国君。
这次会见，祭仲事先预料到情况，所以假称有病而没有去。有人说：“祭仲由于有先见之明，所以才免祸。”祭仲说：“那是对的。”
周公打算杀死周庄王而立王子克。辛伯报告庄王，就帮着庄王杀了周公黑肩。王子克逃亡到燕国。
当初，子仪受到桓王的宠信，桓王把他嘱托给周公。辛伯曾劝谏周公说：“妾媵并同于王后，庶子相等于嫡子，权臣和卿士互争权力，大城和国都一样，这都是祸乱的根本。”周公不听，所以招致杀身之祸。', NULL, '', 'indent', 1558624740, '5ce649617b968a00762a1d33', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642897, '左传 · 庄公 · 庄公元年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】元年春王正月。三月，夫人孙于齐。夏，单伯送王姬。秋，筑王姬之馆于外。冬十月乙亥，陈侯林卒。王使荣叔来锡桓公命。王姬归于齐。齐师迁纪、郱、鄑、郚。
【传】元年春，不称即位，文姜出故也。
三月，夫人孙于齐。不称姜氏，绝不为亲，礼也。
秋，筑王姬之馆于外。为外，礼也。
', '', '', '元年春季，《春秋》没有记载鲁庄公即位，这是由于文姜外出没有回国的缘故。
三月，鲁桓公夫人到了齐国。《春秋》不称姜氏而称夫人，是由于断绝了母子关系，这是合于礼的。
秋季，在城外建造王姬的行馆。因为王姬不是鲁国的女子，而是周天子的女儿，这是合于礼的。', NULL, '', 'indent', 1558624777, '5ce64987ba39c80068432bdc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642898, '庄公（元年～三十二年）', NULL, 0, 12, 0, 2, '公羊高', NULL, 36789, '586e4843b123db005d0e97e6', '秦', 'wen', '文', '', '', '◇庄公元年春王正月，公何以不言即位？《春秋》君弑子不言即位。君弑则子何以不言即位？隐之也。孰隐？隐子也。三月，夫人孙于齐。孙者何？孙犹孙也。内讳奔谓之孙。夫人固在齐矣，其言孙于齐何？念母也。正月以存君，念母以首事。夫人何以不称姜氏？贬。曷为贬？与弑公也。其与弑公奈何？夫人谮公于齐侯，公曰：「同非吾子，齐侯之子也。」齐侯怒，与之饮酒。于其出焉，使公子彭生送之。于其乘焉，胁干而杀之。念母者所善也，则曷为于其念母焉贬？不与念母也。
夏，单伯逆王姬。单伯者何？吾大夫之命乎天子者也。何以不称使？天子召而使之也。逆之者何？使我主之也。曷为使我主之？天子嫁女乎诸侯，必使诸侯同姓者主之。诸侯嫁女于大夫，必使大夫同姓者主之。
秋，筑王姬之馆于外。何以书？讥。何讥尔？筑之礼也，于外非礼也。于外何以非礼？筑于外非礼也。其筑之何以礼？主王姬者必为之改筑。主王姬者则曷为必为之改筑？于路寝则不可。小寝则嫌。群公子之舍则以卑矣。其道必为之改筑者也。冬十月乙亥，陈侯林卒。
王使荣叔来锡桓公命。锡者何？赐也。命者何？加我服也。其言桓公何？追命也。王姬归于齐。何以书？我主之也。
齐师迁纪、郱、鄑、郚。迁之者何？取之也。取之则曷为不言取之也？为襄公讳也。外取邑不书，此何以书？大之也。何大尔？自是始灭也。
◇庄公二年
春王二月，葬陈庄公。
夏，公子庆父帅师伐馀丘。馀丘者何？邾娄之邑也。曷为不系乎邾娄？国之也。曷为国之？君存焉尔。
秋七月，齐王姬卒，外夫人不卒，此何以卒？录焉尔。曷为录焉尔？我主之也。
冬十有二月，夫人姜氏会齐侯于郜。
乙酉，宋公冯卒。
◇庄公三年
春王正月，溺会齐师伐卫。溺者何？吾大夫之未命者也。
夏四月，葬宋庄公。
五月，葬桓王。此未有言崩者何以书葬？盖改葬也。
秋，纪季以酅入于齐。纪季者何？纪侯之弟也。何以不名？贤也。何贤乎？纪季服罪也。其服罪奈何？鲁子曰：「请后五庙以存姑姊妹」。
冬，公次于郎。其言次于郎何？刺欲救纪而后不能也。
◇庄公四年
春王二月，夫人姜氏飨齐侯于祝丘。
三月，纪伯姬卒。
夏，齐侯，陈侯，郑伯遇于垂。纪侯大去其国。大去者何？灭也。孰灭之？齐灭之。曷为不言齐灭之？为襄公讳也。《春秋》为贤者。讳何贤乎襄公？复仇也。何仇尔？远祖也。哀公亨乎周，纪侯谮之。以襄公之为于此焉者，事祖祢之心尽矣。尽者何？襄公将复仇乎纪，卜之曰：「师丧分焉」。「寡人死之，不为不吉也。」远祖者几世乎？九世矣。九世犹可以复仇乎？虽百世可也。家亦可乎？曰：「不可。」国何以可？国君一体也。先君之耻，犹今君之耻也。今君之耻，犹先君之耻也。国君何以为一体？国君以国为体，诸侯世，故国君为一体也。今纪无罪，此非怒与？曰：「非也。」古者有明天子，则纪侯必诛，必无纪者。纪侯之不诛，至今有纪者，犹元明天子也。古者诸侯必有会聚之事，相朝聘之道，号辞必称先君以相接，然则齐纪无说焉，不可以并立乎天下。故将去纪侯者，不得不去纪也，有明天子则襄公得为若行乎？曰：「不得也」。不得则襄公曷为为之，上无天子，下无方伯，缘恩疾者可也。六月乙丑，齐侯葬纪伯姬。外夫人不书葬，此何以书？隐之也。何隐尔？其国亡矣，徒葬于齐尔。此复仇也，曷为葬之？灭其可灭，葬其可葬。此其为可葬奈何？复仇者非将杀之，逐之也。以为虽遇纪侯之殡，亦将葬之也。
秋七月。
冬，公及齐人狩于郜。公曷为与微者狩？齐侯也。齐侯则其称人何？讳与仇狩也，前此者有事矣，后此者有事矣，则曷为独于此焉？讥于仇者将壹讥而已。故择其重者而讥焉，莫重乎其与仇狩也。于仇者则曷为将壹讥而已？仇者无时焉可与通，通则为大讥，不可胜讥，故将壹讥而已，其馀从同同。
◇庄公五年
春王正月。
夏，夫人姜氏如齐师。
秋，倪黎来来朝。倪者何？小邾娄也。小邾娄则曷为谓之倪？未能以其名通也。黎来者何？名也。其名何？微国也。
冬，公会齐人、宋人、陈人、蔡人伐卫。此伐卫何？纳朔也。曷为不言纳卫侯朔？辟王也。◇庄公六年
春王三月，王人子突救卫。王人者何？微者也。子突者何？贵也。贵则其称人何？系诸人也。曷为系诸人？王人耳。
夏六月，卫侯朔入于卫。卫侯朔何以名？绝。曷为绝之？犯命也。其言入何？篡辞也。
秋，公至自伐卫。曷为或言致会？或言致伐？得意致会，不得意致伐。卫侯朔入于卫，何以致伐？不敢胜天子也。
螟。
冬，齐人来归卫宝。此卫宝也，则齐人曷为来归之？卫人归之也。卫人归之，则其称齐人何？让乎我也。其让乎我奈何？齐侯曰：「此非寡人之力，鲁侯之力也！」
◇庄公七年
春，夫人姜氏会齐侯于防。夏四月辛卯，夜，恒星不见，夜中，星陨如雨。恒星者何？列星也。列星不见何以知？夜之中星反也。如雨者何？如雨者非雨也。非雨则曷为谓之如雨？不修《春秋》曰「雨星不及地尺而复」。君子修之曰：「星陨如雨。」何以书？记异也。
秋，大水。
无麦苗。无苗则曷为先言无麦而后言无苗？一灾不书，待无麦然后书无苗。何以书？记灾也。
冬，夫人姜氏会齐侯于谷。
◇庄公八年春王正月，师次于郎，以俟陈人、蔡人。次不言俟，此其言俟何？托不得已也。甲午，祠兵。祠兵者何？出曰祠兵，入曰振旅，其礼一也，皆习战也。何言乎祠兵？为久也。曷为为久？吾将以甲午之日，然后祠兵于是。
夏，师及齐师围城，成降于齐师。成者何？盛也。盛则曷为谓之成？讳灭同姓也。曷为不言降吾师？辟之也。
秋，师还。还者何？善辞也。此灭同姓何善尔？病之也。曰：「师病矣」。曷为病之，非师之罪也。
冬十有一月癸未，齐无知弑其君诸儿。
◇庄公九年春，齐人杀无知。
公及齐大夫盟于暨。公曷为与大夫盟？齐无君也。然则何以不名？为其讳与大夫盟也，使若众然。夏，公伐齐纳纠。纳者何？入辞也。其言伐之何？伐而言纳者，犹不能纳也。纠者何？公子纠也。何以不称公子？君前臣名也。齐小白入于齐。曷为以国氏？当国也。其言入何？篡辞也。
秋，七月丁酉，葬齐襄公。
八月庚申，及齐师战于乾时，我师败绩。内不言败，此其言败何？伐败也。曷为伐败？复仇也。此复仇乎大国，曷为使微者？公也。公则曷为不言公？不与公复仇也。曷为不与公复仇？复仇者在下也。
九月，齐人取子纠，杀之。其取之何？内辞也，胁我使我杀之也。其称子纠何？贵也。其贵奈何？宜为君者也。冬，浚洙。洙者何？水也。浚之者何？深之也。曷为深之？畏齐也。曷为畏齐也？辞役子纠也。
◇庄公十年
春王正月，公败齐师于长勺。二月，公侵宋，曷为或言侵，或言伐？粗者曰侵，精者曰伐。战不言伐，围不言战，入不言围，灭不言入，书其重者也。
三月，宋人迁宿。迁之者何？不通也，以地还之也。子沈子曰：「不通者，盖因而臣之也。」
夏六月，齐师、宋师次于郎。公败宋师于乘丘。其言次于郎何？伐也。伐则其言次何？齐与伐而不与战，故言伐也。我能败之，故言次也。
秋九月，荆败蔡师于莘，以蔡侯献舞归。荆者何？州名也。州不若国，国不若氏，氏不若人，人不若名，名不若字，字不若子。蔡侯献舞何以名？绝。曷为绝之？获也。曷为不言其获？不与夷狄之获中国也。
冬十月，齐师灭谭，谭子奔莒。何以不言出？国已灭矣，无所出也。◇庄公十一年春王正月。
夏五月戊寅，公败宋师于鄑。秋，宋大水。何以书，记灾也。外灾不书，此何以书？及我也。冬，王姬归于齐。何以书？过我也。
◇庄公十二年
春王三月，纪叔姬归于酅。其言归于酅何？隐之也。何隐尔？其国亡矣，徒归于叔尔也。夏四月。
秋八月甲午，宋万弑其君接，及其大夫仇牧。及者何？累也。弑君多矣，舍此无累者乎？孔父、荀息皆累也。舍孔父、荀息无累者乎？曰：「有。」有则此何以书？贤也。何贤乎仇牧？仇牧可谓不畏强御矣。其不畏强御奈何？万尝与庄公战，获乎庄公。庄公归，散舍诸宫中，数月然后归之。归反为大夫于宋。与闵公博，妇人皆在侧。万曰：「甚矣，鲁侯之淑，鲁侯之美也！天下诸侯宜为君者，唯鲁侯尔！」闵公矜此妇人，妒其言，顾曰：「此虏也！尔虏焉故，鲁侯之美恶乎至？」万怒搏闵公，绝其脰。仇牧闻君弑，趋而至，遇之于门，手剑而叱之。万臂摋仇牧，碎其首，齿着乎门阖。仇牧可谓不畏强御矣。冬十月，宋万出奔陈。
◇庄公十三年
春，齐侯、宋人、陈人、蔡人、邾娄人会于北杏。
夏六月，齐人灭遂。
秋七月。
冬，公会齐侯，盟于柯。何以不日？易也。其易奈何？桓之盟不日，其会不致，信之也。其不日何以始乎此？庄公将会乎桓，曹子进曰：「君之意何如？」庄公曰：「寡人之生则不若死矣。」曹子曰「然则君请当其君，臣请当其臣。」庄公曰：「诺。」于是会乎桓。庄公升坛，曹子手剑而从之。管子进曰：「君何求乎？」曹子曰：「城坏压竟，君不图与？」管子曰：「然则君将何求？」曹子曰：「愿请汶阳之田。」管子顾曰：「君许诺。」桓公曰：「诺。」曹子请盟，桓公下与之盟。已盟，曹子摽剑而去之。要盟可犯，而桓公不欺。曹子可仇，而桓公不怨，桓公之信着乎天下，自柯之盟始焉。
◇庄公十四年
春，齐人、陈人、曹人伐宋。
夏，单伯会伐宋。其言会伐宋何？后会也。秋七月荆入蔡。
冬，单伯会齐侯、宋公、卫侯、郑伯于鄄。◇庄公十五年
春，齐侯、宋公、陈侯、卫侯、郑伯会于鄄。夏，夫人姜氏如齐。
秋，宋人，齐人、邾娄人伐儿。
郑人侵宋。
冬十月。
◇庄公十六年
春王正月。
夏，宋人、齐人、卫人伐郑。
秋，荆伐郑。
冬十有二月，公会齐侯、宋公、陈侯、卫侯、郑伯、许男、曹伯、滑伯、滕子同盟于幽。同盟者何？同欲也。邾娄子克卒。
◇庄公十七年
春，齐人执郑瞻。郑瞻者何？郑之微者也。此郑之微者，何言乎齐人执之？书甚佞也。
夏，齐人歼于遂。歼者何？歼积也，众杀戍者也。
秋，郑瞻自齐逃来。何以书？书甚佞也。曰：「佞人来矣，佞人来矣。」冬，多麋。何以书，记异也。◇庄公十八年
春王三月，日有食之。
夏，公追戎于济西。此未有言伐者，其言追何？大其为中国追也。此未有伐中国者，则其言为中国追何？大其未至而豫御之也。其言于济西何？大之也。
秋，有{或虫}。何以书？记异也。
冬十月。
◇庄公十九年
春王正月。
夏四月。
秋，公子结媵陈人之妇于鄄，遂及齐侯、宋公盟。媵者何？诸侯娶一国，则二国往媵之，以侄娣从。侄者何？兄之子也。娣者何？弟也。诸侯壹聘九女，诸侯不再娶。媵不书，此何以书？为其有遂事书。大夫无遂事，此其言遂何？聘礼，大夫受命不受辞，出竟有可以安社稷利国家者，则专之可也。
夫人姜氏如莒。
冬，齐人、宋人、陈人伐我西鄙。
◇庄公二十年
春王二月，夫人姜氏如莒。夏，齐大灾。大灾者何？大瘠也。大瘠者何？《疒列》也。何以书？记灾也。外灾不书，此何以书：及我也。
秋七月。
冬，齐人伐戎。
◇庄公二十一年春王正月。夏五月，辛酉，郑伯突卒。
秋七月戊戌，夫人姜氏薨。
冬十有二月，葬郑厉公。
◇庄公二十二年
春王正月，肆大省，肆者何？跌也。肆大省者何？灾省也。肆大省何以书？讥。何讥尔？讥始忌省也。
癸丑，葬我小君文姜。文姜者何？庄公之母也。陈人杀其公子御寇。
夏五月。秋七月丙申，及齐高徯盟于防。齐高徯者何？贵大夫也。曷为就吾微者而盟？公也。公则曷为不言公？讳与大夫盟也。
冬，公如齐纳币。纳币不书，此何以书？讥。何讥尔？亲纳币，非礼也。
◇庄公二十三年
春，公至自齐。桓之盟不日，其会不致，信之也。此之桓国何以致，危之也。何危尔？公一陈佗也。
祭叔来聘。
夏，公如齐观社。何以书？讥。何讥尔？诸侯越竟观社，非礼也。公至自齐。
荆人来聘。荆何以称人？始能聘也。
公及齐侯遇于谷。
萧叔朝公。其言朝公何？公在外也。
秋，丹桓宫楹。何以书？讥。何讥尔？丹桓宫楹，非礼也。
冬，十有一月，曹伯射姑卒。十有二月甲寅，公会齐侯，盟于扈。桓之盟不日，此何以日？危之也。何危尔？我贰也。鲁子曰：「我贰者，非彼然，我然也。」◇庄公二十四年
春王三月，刻桓宫桷。何以书？讥。何讥尔？刻桓宫桷，非礼也。
葬曹庄公。夏，公如齐逆女。何以书？亲迎礼也。
秋，公至自齐。八王丁丑，夫人姜氏入。其言入何？难也。其言日何？难也。其难奈何？夫人不偻不可使入，与公有所约，然后入。戊寅，大夫、宗妇觌，用币。宗妇者何？大夫之妻也。觌者何？见也。用者何？用者不宜用也。见用币，非礼也。然则曷用？枣栗云乎？腶修云乎。
大水。
冬，戎侵曹，曹羁出奔陈。曹羁者何？曹大夫也。曹无大夫，此何以书？贤也。何贤乎曹羁？戎将侵曹，曹羁谏曰：「戎众以无义。君请勿自敌也。」曹伯曰：「不可」。三谏不从，遂去之，故君子以为得君臣之义也。赤归于曹郭公。赤者何？曹无赤者，盖郭公也。郭公者何？失地之君也。
◇庄公二十五年
春，陈侯使女叔来聘。
夏五月癸丑，卫侯朔卒。
六月辛未朔，日有食之，鼓，用牲于社。日食则曷为鼓用牲于社？求乎阴之道也，以朱丝营社，或曰胁之，或曰为暗，恐人犯之，故营之。
伯姬归于杞。
秋，大水，鼓用牲于社于门。其言于社于门何？于社礼也，于门非礼也。
冬，公子友如陈。
◇庄公二十六年
公伐戎。
夏，公至自伐戎。
曹杀其大夫。何以不名？众也。曷为众杀之？不死于曹君者也。君死乎位曰灭。曷为不言其灭？为曹羁讳也。此盖战也，何以不言战？为曹羁讳也。
秋，公会宋人、齐人、伐徐。冬十有二月癸亥朔，日有食之。
◇庄公二十七年
春，公会杞伯姬于洮。
夏六月，公会齐侯，宋公、陈侯、郑伯，同盟于幽。
秋，公子友如陈，葬原仲。原仲者何？陈大夫也。大夫不书葬，此何以书？通乎季子之私行也。何通乎季子之私行？辟内难也。君子辟内难而不辟外难。内难者何？公子庆父、公子牙、公子友皆庄公之母弟也。公子庆父、公子牙通乎夫人以胁公，季子起而治之，则不得与于国政，坐而视之则亲亲。因不忍见也，故于是复请至于陈而葬原仲也。冬，杞伯姬来。其言来何？直来曰来，大归曰来归。
莒庆来逆叔姬。莒庆者何？莒大夫也。莒无大夫，此何以书？讥。何讥尔？大夫越竟逆女，非礼也。
杞伯来朝。
公会齐侯于城濮。
◇庄公二十八年春王三月甲寅，齐人伐卫。卫人及齐人战，卫人败绩。伐不日，此何以日？至之日也。战不言伐，此其言伐何？至之日也。《春秋》伐者为客，伐者为主，故使卫主之也。曷为使卫主之？卫未有罪尔。败者称师，卫何以不称师？未得乎师也。
夏四月丁未，邾娄子琐卒。
秋，荆伐郑。公会齐人、宋人、邾娄人救郑。
冬，筑微。大无麦禾。冬既见无麦禾矣，曷为先言筑微而后言无麦禾？讳，以凶年造邑也。
臧孙辰告籴于齐。告籴者何？请籴也。何以不称使？以为臧孙辰之私行也。曷为以臧孙辰之私行？君子之为国也，必有三年之委。一年不熟告籴，讥也。◇庄公二十九年春，新延厩。新延厩者何？修旧也。修旧不书，此何以书？讥。何讥尔？凶年不修。夏，郑人侵许。秋，有蜚。何以书？记异也。冬十有二月，纪叔姬卒。
城诸及防。
◇庄公三十年春，王正月。
夏，师次于成。
秋七月，齐人降鄣。鄣者何？纪之遗邑也。降之者何？取之也。取之则曷为不言取之？为桓公讳也。外取邑不书，此何以书？尽也。
八月癸亥，葬纪叔姬。外夫人不书葬，此何以书？隐之也。何隐尔？其国亡矣，徒葬乎叔尔。
九月庚午朔，日有食之，鼓，用牲于社。冬，公及齐侯遇于鲁济。齐人伐山戎。此齐侯也，其称人何？贬。曷为贬？子司马子曰：「盖以操之为已蹙矣。」此盖战也，何以不言战？《春秋》敌者言战，桓公之与戎狄，驱之尔。
◇庄公三十一年
春，筑台于郎。何以书？讥。何讥尔？临民之所漱浣也。
夏四月，薛伯卒。
筑台于薛。何以书？讥。何讥尔？远也。
六月，齐侯来献戎捷。齐大国也，曷为亲来献戎捷？威我也。其威我奈何？旗获而过我也。秋，筑台于秦。何以书？，讥。何讥尔？临国也。
冬，不雨，何以书？记异也。
◇庄公三十二年春，城小谷。夏，宋公、齐侯遇于梁丘。
秋七月癸巳，公子牙卒。何以不称弟？杀也。杀则曷为不言刺？为季子讳杀也，曷为为季子讳杀？季子之遏恶也，不以为国狱，缘季子之心而为之讳。季子之遏恶奈何？庄公病将死，以病召季子，季子至而授之以国政，曰：「寡人即不起此病，吾将焉致乎鲁国？」季子曰：「般也存，君何忧焉？」公曰：「庸得若是乎？牙谓我曰：『鲁一生一及，君已知之矣。庆父也存。』」季子曰：「夫何敢？是将为乱乎？夫何敢？」俄而牙弑械成。季子和药而饮之曰：「公子从吾言而饮此，则必可以无为天下戮笑，必有后乎鲁国。不从吾言而不饮此，则必为天下戮笑，必无后乎鲁国。」于是从其言而饮之，饮之无累氏，至乎王堤而死。公子牙今将尔。辞曷为与亲弑者同？君亲无将，将而诛焉，然则善之与？曰：「然。」杀世子母弟直称君者，甚之也。季子杀母兄何善尔？诛不得辟兄，君臣之义也。然则曷为不直诛而鸩之？行诛乎兄，隐而逃之，使托若以疾死，然亲亲之道也。
八月癸亥，公薨于路寝。路寝者何？正寝也。冬十月乙未，子般卒。子卒云子卒，此其称子般卒何？君存称世子，君薨称子某，既葬称子，逾年称公。子般卒，何以不书葬？未逾年之君也。有子则庙，庙则书葬。无子不庙，不庙则不书葬。公子庆父如齐。
狄伐邢。', '', '', '', NULL, '', 'indent', 1558624804, '5ce649a243e78c0067d8e8ee', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642899, '左传 · 庄公 · 庄公三年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三年春王正月，溺会齐师伐卫。夏四月，葬宋庄公。五月，葬桓王。秋，纪季以酅入于齐。冬，公次于滑。
【传】三年春，溺会齐师伐卫，疾之也。
夏五月，葬桓王，缓也。
秋，纪季以酅入于齐，纪于是乎始判。
冬，公次于滑，将会郑伯，谋纪故也。郑伯辞以难。凡师，一宿为舍，再宿为信，过信为次。
', '', '', '三年春季，公子溺会合齐国军队攻打卫国，《春秋》单称他的名字溺，不称公子，是表示对他的贬斥。夏季五月，安葬周桓王。这在丧礼的时间上太迟缓了。秋季，纪季把酅地割让给齐国，纪国从这时候开始分裂。冬季，鲁庄公带领护卫军屯驻在滑地多夜，打算会见郑伯，策划纪国的事务。郑伯用国内不安定为理由加以推脱。凡是军队在外，住一夜叫做舍，两夜叫做信，两夜以上叫做次。', NULL, '', 'indent', 1558624832, '5ce649be7b968a00762a21f2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642900, '左传 · 庄公 · 庄公四年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】四年春王二月，夫人姜氏享齐侯于祝丘。三月，纪伯姬卒。夏，齐侯、陈侯、郑伯遇于垂。纪侯大去其国。六月乙丑，齐侯葬纪伯姬。秋七月。冬，公及齐人狩于禚。
【传】四年春，王三月，楚武王荆尸，授师孑焉，以伐随，将齐，入告夫人邓曼曰：「余心荡。」邓曼叹曰：「王禄尽矣。盈而荡，天之道也。先君其知之矣，故临武事，将发大命，而荡王心焉。若师徒无亏，王薨于行，国之福也。」王遂行，卒于樠木之下。令尹斗祁、莫敖屈重除道、梁溠，营军临随。随人惧，行成。莫敖以王命入盟随侯，且请为会于汉汭，而还。济汉而后发丧。
纪侯不能下齐，以与纪季。夏，纪侯大去其国，违齐难也。


', '', '', '四年春季，周王朝历法的三月，楚武王运用名叫荆尸的军阵，把戟颁发给士兵，要去攻打随国。准备斋戒，进宫告诉夫人邓曼说：“我心神动荡不安。”邓曼叹气说：“君王的福禄尽了。满了就会动荡，这是自然的道理。先君大概知道了，所以面临作战，将要发布征伐命令而使君王心跳。如果军队没有什么损失，而君王死在行军途中，这就是国家之福了。”楚武王于是出征，死在樠树下面。令尹鬬祁、莫敖屈重秘不发丧，开通新路，并在溠水筑桥，在随国境外建筑营垒。随国人恐惧，向楚军求和。莫敖屈重以楚王的名义进入随国，和随侯结盟，而且邀请随侯在汉水转湾处会见，然后退兵。渡过了汉水以后公布丧事。
纪侯不能屈从齐国，把国家政权让给了纪季。夏季，纪侯永远离开了他的国家，以避免齐国对他所加的祸害。 ', NULL, '', 'indent', 1558624872, '5ce649e630863b0068bc6aab', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642902, '左传 · 庄公 · 庄公六年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】六年春王正月，王人子突救卫。夏六月，卫侯朔入于卫。秋，公至自伐卫。螟。冬，齐人来归卫俘。
【传】六年春，王人救卫。
夏，卫侯入，放公子黔牟于周，放宁跪于秦，杀左公子泄、右公子职，乃即位。
君子以二公子之立黔牟为不度矣。夫能固位者，必度于本末而后立衷焉。不知其本，不谋。知本之不枝，弗强。《诗》云：「本枝百世。」
冬，齐人来归卫宝，文姜请之也。
楚文王伐申，过邓。邓祁侯曰：「吾甥也。」止而享之。骓甥、聃甥、养甥请杀楚子，邓侯弗许。三甥曰：「亡邓国者，必此人也。若不早图，后君噬齐。其及图之乎？图之，此为时矣。」邓侯曰：「人将不食吾余。」对曰：「若不从三臣，抑社稷实不血食，而君焉取余？」弗从。还年，楚子伐邓。十六年，楚复伐邓，灭之。', '', '', '六年春季，周庄王的属官叫子突的率军救援卫国。
夏季，卫惠公回国，放逐公子黔牟到成周，放逐甯跪到秦国，杀了左公子泄、右公子职，这才即位。
君子认为左、右二公子扶立黔牟为国君，“是一种很欠考虑始终的行为。对能够巩固自己地位的人，必须考虑他的各方面，然后用适当的方式立他为国君。不了解他的根本，就是缺乏谋略；了解到虽有根本却没有枝叶，就不要勉强树立他。《诗》说：‘有本有枝，繁衍百世。’”
冬季，齐国人前来归还卫国的宝器，这是由于文姜的请求。
楚文王进攻申国，路过邓国。邓祁侯说：“他是我的外甥。把他留下而设宴招待他。骓甥、聃甥、养甥请求杀掉楚文王。邓侯不允许。这三甥都说：“灭亡邓国的，必定是这个人。如果不早打主意，君王后悔便来不及了。现在下手还来得及！下手吧，现在正是时候！”邓侯说：“如果这样做，人们会唾弃我而不吃我剩下的东西的。”三位外甥回答说：“如果不听我们三个人的话，土地和五谷的神明就得不到祭享，君王到哪里去取得祭神的剩余？”邓祁侯还是不答应。攻打申国回国的那一年，楚王进攻邓国。庄公十六年，楚国再次攻打邓国，终于灭亡了邓国。', NULL, '', 'indent', 1558624941, '5ce64a2b7b968a00762a2884', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642903, '左传 · 庄公 · 庄公七年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】七年春，夫人姜氏会齐侯于防。夏四月辛卯，夜，恒星不见。夜中，星陨如雨。秋，大水。无麦、苗。冬，夫人姜氏会齐侯于谷。
【传】七年春，文姜会齐侯于防，齐志也。
夏，恒星不见，夜明也。星陨如雨，与雨偕也。
秋，无麦苗，不害嘉谷也。
', '', '', '七年春季，文姜和齐襄公在防地相会，这是出于齐襄公的主意。
夏季，看不到常见的星星，这是由于夜空明亮的缘故。流星坠落而且带着雨点，这是和雨一起落下来的。
秋季，麦子不收，小苗不长，但没有影响黍稷的收成。', NULL, '', 'indent', 1558624977, '5ce64a4f43e78c0067d8f42f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642904, '左传 · 庄公 · 庄公八年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】八年春王正月，师次于郎，以俟陈人，蔡人。甲午，治兵。夏，师及齐师围郕，郕降于齐师。秋，师还。冬十有一月癸未，齐无知弑其君诸儿。
【传】八年春，治兵于庙，礼也。
夏，师及齐师围郕。郕降于齐师。仲庆父请伐齐师。公曰：「不可。我实不德，齐师何罪？罪我之由。《夏书》曰：『皋陶迈种德，德，乃降。』姑务修德以待时乎。」秋，师还。君子是以善鲁庄公。
齐侯使连称、管至父戍葵丘。瓜时而往，曰：「及瓜而代。」期戍，公问不至。请代，弗许。故谋作乱。
僖公之母弟曰夷仲年，生公孙无知，有宠于僖公，衣服礼秩如适。襄公绌之。二人因之以作乱。连称有从妹在公宫，无宠，使间公，曰：「捷，吾以女为夫人。」
冬十二月，齐侯游于姑棼，遂田于贝丘。见大豕，从者曰：「公子彭生也。」公怒曰：「彭生敢见！」射之，豕人立而啼。公惧，坠于车，伤足丧屦。反，诛屦于徒人费。弗得，鞭之，见血。走出，遇贼于门，劫而束之。费曰：「我奚御哉！」袒而示之背，信之。费请先入，伏公而出，斗，死于门中。石之纷如死于阶下。遂入，杀孟阳于床。曰：「非君也，不类。」见公之足于户下，遂弑之，而立无知。
初、襄公立，无常。鲍叔牙曰：「君使民慢，乱将作矣。」奉公子小白出奔莒。乱作，管夷吾、召忽奉公子纠来奔。
初，公孙无知虐于雍廪。', '', '', '八年春季，鲁庄公在太庙把武器发给军队，这是合于礼的。
夏季，鲁军和齐军包围郕国。郕国向齐军投降。仲庆父请求进攻齐军。庄公说：“不行，我实在缺乏德行，齐军有什么罪？罪是由我引起的。《夏书》说：‘皋陶勉力培育德行，德行具备，别人就会降服。’我们姑且致力于修养德行，以等待时机吧！”
秋季，军队回国。君子因此而赞美鲁庄公。
齐襄公派连称、管至父驻守葵丘，瓜熟的时节前去，说：“到明年瓜熟的时候派人替代你们。”驻守了一周年，齐襄公的命令并没有下来。连称、管至父请求派人替代，齐襄公不同意，因此就策划叛乱。
齐僖公的同母兄弟叫夷仲年，生了公孙无知，受到僖公的宠信，衣服礼仪等种种待遇都和嫡子一样。齐襄公降低了公孙无知的待遇。连称、管至父两个人就利用公孙无知而发动叛变。连称有个堂妹在齐襄公的后宫，不得宠，就让她去侦察襄公的情况。公孙无知说：“事情成功，我把你立为君夫人。”
冬季，十二月，齐襄公在姑棼游玩，就在贝丘打猎。看到一头大野猪，随从说：“这是公子彭生啊！”齐襄公发怒说：“彭生敢来见我！”就用箭射它。野猪像人一样站起身啼叫。齐襄公害怕，从车上摔下来，伤了脚，丢了鞋。回去以后，责令徒人费去找鞋，费找不着，齐襄公就鞭打他，打得皮开血出。费走出去，在宫门口遇到叛贼。叛贼把他劫走并捆起来。费说：“我哪里会抵抗你们啊！”解开衣服让他们看自己的背后。叛贼相信了。费表示愿意和他们一起行动，请求先进宫去。进去以后把齐襄公隐藏起来，然后出宫同其他宦官和叛贼格斗，死在宫门里，石之纷如死在台阶下。叛贼就进入宫中，在床上杀了孟阳，说：“不是国君，样子不像。”一眼看到齐襄公的脚露出在门下边，就把他杀死了，而拥立无知为国君。
当初，齐襄公即位，施政没有准则，使人不知所措。鲍叔牙说：“国君放纵，百姓懈怠，祸乱将要发生了。”就事奉公子小白避乱到莒国。叛乱发生，管夷吾、召忽事奉公子纠逃避到鲁国来。
当初，公孙无知对待雍廪很暴虐。', NULL, '', 'indent', 1558625008, '5ce64a6fd5de2b00703de834', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642905, '左传 · 庄公 · 庄公九年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】九年春，齐人杀无知。公及齐大夫盟于既。夏，公伐齐纳子纠。齐小白入于齐。秋七月丁酉，葬齐襄公。八月庚申，及齐师战于乾时，我师败绩。九月，齐人取子纠杀之。冬，浚洙。
【传】九年春，雍廪杀无知。
公及齐大夫盟于既，齐无君也。
夏，公伐齐，纳子纠。桓公自莒先入。
秋，师及齐师战于乾时，我师败绩，公丧戎路，传乘而归。秦子、梁子以公旗辟于下道，是以皆止。
鲍叔帅师来言曰：「子纠，亲也，请君讨之。管、召、仇也，请受而甘心焉。」乃杀子纠于生窦，召忽死之。管仲请囚，鲍叔受之，乃堂阜而税之。归而以告曰：「管夷吾治于高傒，使相可也。」公从之。', '', '', '九年春季，雍廪杀死公孙无知。
鲁庄公和齐国的大夫在蔇地结盟，这是由于当时齐国没有国君。
夏季，庄公进攻齐国，护送公子纠回国即位。齐桓公从莒国抢先回到齐国。
秋季，我军和齐军在乾时作战，我军大败。庄公丧失战车，乘坐轻车逃了回来。秦子、梁子打着庄公的旗号躲在小道上作掩护，都被齐军俘虏了。
鲍叔率领军队代表齐桓公来鲁国说：“子纠，是我齐君的亲人，请君王代我齐国讨伐。管仲、召忽，是我齐君的仇人，请把他们交给我齐国才能甘心。”于是就在生窦把公子纠杀死，召忽也自杀了。管仲请求把他押送回齐国，鲍叔接受请求，到了齐境堂阜就把他释放了。回国后，鲍叔报告齐桓公说：“管仲治国的才能比高傒都强，可以让他辅助君主。”齐桓公听从了这个意见。', NULL, '', 'indent', 1558625047, '5ce64a9543e78c0067d8f6d7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642907, '左传 · 庄公 · 庄公十一年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有一年春王正月。夏五月，戊寅，公败宋师于鄑。秋，宋大水。冬，王姬归于齐。
【传】十一年夏，宋为乘丘之役故侵我。公御之，宋师未陈而薄之，败诸鄑。
凡师，敌未陈曰败某师，皆陈曰战，大崩曰败绩，得人隽曰克，覆而败之曰取某师，京师败曰王师败绩于某。
秋，宋大水。公使吊焉，曰：「天作淫雨，害于粢盛，若之何不吊？」对曰：「孤实不敬，天降之灾，又以为君忧，拜命之辱。」臧文仲曰：「宋其兴乎。禹、汤罪己，其兴也悖焉、桀、纣罪人，其亡也忽焉。且列国有凶称孤，礼也。言惧而名礼，其庶乎。」既而闻之曰公子御说之辞也。臧孙达曰：「是宜为君，有恤民之心。」
冬，齐侯来逆共姬。
乘丘之役，公之金仆姑射南宫长万，公右遄孙生搏之。宋人请之，宋公靳之，曰：「始吾敬子，今子，鲁囚也。吾弗敬子矣。」病之。', '', '', '十一年夏季，宋国为了乘丘那次战役的缘故而入侵我国。庄公出兵迎战。
宋国的军队还没有摆开阵势，我军就逼近压过去，在戬地打败宋军。
凡是作战，敌方没有摆开阵势叫做“败某师”，都摆开了阵势叫做“战”，大崩溃叫做“败绩”，俘虏敌方的勇士叫做“克”，伏兵而击败敌军叫做“取某师”，周天子的军队被打败叫做“王师败绩于某”。
秋季，宋国发大水。庄公派使者去慰问，说：“上天降下大雨，危害了庄稼，为什么不慰问呢？”宋闵公回答说：“我对于上天不诚敬，上天降灾，还使贵国国君担忧，承蒙关注，实不敢当。”臧文仲说：“宋国恐怕要兴盛了吧！禹、汤责罚自己，他们勃然兴起；桀、纣责罚别人，他们马上灭亡。
而且别国发生灾荒，国君称孤，这是合于礼的。言语有所戒惧而名称合于礼制，这就差不多了吧！”不久，又听说上面那番话是公子御说所说的，臧孙达说：“这个人适合当国君，因为他有体恤百姓的心思。”
冬季，齐桓公来鲁国迎娶共姬。
在乘丘战役中，庄公用叫金仆姑的箭射中南宫长万，庄公的车右歂孙活捉了长万。宋国人请求把南宫长万释放回国。长万是力气极大的人，宋闵公开玩笑说：“原来我尊敬你，如今你成了鲁国的囚犯，所以我便不敬重你了。”
南宫长万因此而怀恨他。', NULL, '', 'indent', 1558625120, '5ce64adec8959c0069a1f1e2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642908, '左传 · 庄公 · 庄公十二年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有二年春王三月，纪叔姬归于酅。夏四月。秋八月甲午，宋万弑其君捷及其大夫仇牧。十月，宋万出奔陈。
【传】十二年秋，宋万弑闵公于蒙泽。遇仇牧于门，批而杀之。遇大宰督于东宫之西，又杀之。立子游。群公子奔萧。公子御说奔亳。南宫牛、猛获帅师围亳。
冬十月，萧叔大心及戴、武、宣、穆、庄之族以曹师伐之。杀南宫牛于师，杀子游于宋，立桓公。猛获奔卫。南宫万奔陈，以乘车辇其母，一日而至。
宋人请猛获于卫，卫人欲勿与，石祁子曰：「不可。天下之恶一也，恶于宋而保于我，保之何补？得一夫而失一国，与恶而弃好，非谋也。」卫人归之。亦请南宫万于陈，以赂。陈人使妇人饮之酒，而以犀革裹之。比及宋手足皆见。宋人皆醢之。
', '', '', '十二年秋季，宋国的南宫长万在蒙泽杀死了宋闵公。他在城门口遇到仇牧，反手便打死了他。在东宫的西面遇到太宰华督，又杀了他。拥立子游为国君。公子们都逃亡到萧邑，而公子御说逃亡到亳地，南宫牛、猛获率领军队包围了亳地。
冬季，十月，萧叔大心和宋戴公、武公、宣公、穆公、庄公的族人借调曹国的军队付伐南宫牛和猛获。在阵前杀死了南宫牛，在宋国都城杀死了子游，拥立宋桓公为国君。猛获逃亡到卫国，南宫长万逃亡到陈国，长万自己驾车拉着他母亲，一天就到达了。
宋国人到卫国请求归还猛获。卫国人想不给他们。石祁子说：“不行。
普天下的邪恶都是一样可恶的，在宋国作恶而在我国受到保护，保护了他有什么好处？得到一个人而失去一个国家，结交邪恶的人而丢掉友好的国家，这不是好主意。”卫国人把猛获归还给了宋国。宋国又到陈国请求归还南宫长万，并且施以贿赂。陈国人让女人劝南宫长万饮酒，灌醉了他就用犀牛皮把他包了起来。等到达宋国时，南宫长万的手脚都露出来了。宋国人把猛获和南宫长万剁成了肉酱。
', NULL, '', 'indent', 1558625157, '5ce64b037b968a00762a3147', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642909, '左传 · 庄公 · 庄公十三年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有三年春，齐侯、宋人、陈人、蔡人、邾人会于北杏。夏六月，齐人灭遂。秋七月。冬，公会齐侯盟于柯。
【传】十三年春，会于北杏，以平宋乱。遂人不至。
夏，齐人灭遂而戍之。
冬，盟于柯，始及齐平也。
宋人背北杏之会。', '', '', '十三年春季，鲁庄公和齐、宋、陈、蔡、邾各国国君在北杏会见，是为了平定宋国的动乱。遂国人没有来。夏季，齐国人灭亡遂国并派人戍守。
冬季，宋桓公和齐桓公在柯地结盟，开始和齐国讲和。
宋国人违背了北杏的盟约。', NULL, '', 'indent', 1558625187, '5ce64b2130863b0068bc893b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642910, '左传 · 庄公 · 庄公十四年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有四年春，齐人、陈人、曹人伐宋。夏，单伯会伐宋。秋七月，荆入蔡。冬，单伯会齐侯、宋公、卫侯、郑伯于鄄。
【传】十四年春，诸侯伐宋，齐请师于周。夏，单伯会之，取成于宋而还。
郑厉公自栎侵郑，及大陵，获傅瑕。傅瑕曰：「苟舍我，吾请纳君。」与之盟而赦之。六月甲子，傅瑕杀郑子及其二子而纳厉公。
初，内蛇与外蛇斗于郑南门中，内蛇死。六年而厉公入。公闻之，问于申繻曰：「犹有妖乎？」对曰：「人之所忌，其气焰以取之，妖由人兴也。人无衅焉，妖不自作。人弃常则妖兴，故有妖。」 　　厉公入，遂杀傅瑕。使谓原繁曰：「傅瑕贰，周有常刑，既伏其罪矣。纳我而无二心者，吾皆许之上大夫之事，吾愿与伯父图之。且寡人出，伯父无里言，入，又不念寡人，寡人憾焉。」对曰：「先君桓公命我先人典司宗祏。社稷有主而外其心，其何贰如之？苟主社稷，国内之民其谁不为臣？臣无二心，天之制也。子仪在位十四年矣，而谋召君者，庸非二乎。庄公之子犹有八人，若皆以官爵行赂劝贰而可以济事，君其若之何？臣闻命矣。」乃缢而死。
蔡哀侯为莘故，绳息妫以语楚子。楚子如息，以食入享，遂灭息。以息妫归，生堵敖及成王焉，未言。楚子问之，对曰：「吾一妇人而事二夫，纵弗能死，其又奚言？」楚子以蔡侯灭息，遂伐蔡。秋七月，楚入蔡。
君子曰：「《商书》所谓『恶之易也，如火之燎于原，不可乡迩，其犹可扑灭』者，其如蔡哀侯乎。」
冬，会于鄄，宋服故也。
', '', '', '十四年春季，齐国、陈国、曹国联军进攻宋国。齐国请求成周出兵。夏季，单伯带兵同诸侯相会。同宋国讲和后回国。
郑厉公从栎地带兵入侵郑国国都，到达大陵，俘虏了傅瑕。傅瑕说：“如果放了我，我可以使君王回国再登君位。”郑厉公和他盟誓，便把他释放了。
六月二十日，傅瑕杀死郑子子仪和他的两个儿子，接纳厉公回国。
当初，在郑国国都的南门下面，一条在门里的蛇和一条在门外的蛇相斗，门里的蛇被咬死。过了六年而郑厉公回国。鲁庄公听说这件事，向申繻询问说：“厉公的回国难道与妖蛇有关系吗？”申繻回答说：“一个人是否会遇到他所顾忌的事，是由于他自己的气焰所招致的。妖孽是由于人才起来的。
人没有毛病，妖孽自己不能起来。人丢弃正道，妖孽就自己来了，所以才有妖孽。”
郑厉公回国，就杀死了傅瑕。派人对原繁说：“傅瑕对国君有二心，周朝定有惩处这类奸臣的刑罚，现在傅瑕已经得到惩处了。帮助我回国而没有二心的人，我都答应给他上大夫的职位，我愿意跟伯父一起商量。而且我离开国家在外，伯父没有告诉我国内的情况。回国以后，又并不亲附我，我对此感到遗憾。”原繁回答说：“先君桓公命令我的先人管理宗庙列祖列宗的主位，国家有君主而自己的心却在国外，还有比这更大的二心吗？如果主持国家，国内的百姓，又谁不是他的臣下呢？臣下不应该有二心，这是上天的规定。子仪居于君位，十四年了，现在策划召请君王回国的，难道不是二心吗？庄公的儿子还有八个人，如果都用官爵做贿赂以劝说别人三心二意而又可能成功，君王又怎么办？下臣知道君王的意思了。”原繁说完，就上吊死了。
蔡哀侯由于莘地战役被俘，在楚文王面前赞美息妫。楚文王到息国，设宴招待息侯而加以袭杀，就灭亡了息国。他把息妫带回楚国，生了堵敖和成王。息妫没有主动说过话，楚文王问她，她回答说：“我一个女人，伺候两个丈夫，即使不能死，又能说什么？”楚文王由于蔡侯的缘故才灭亡了息国，于是再进攻蔡国。秋季，七月，楚军进入蔡国。
君子说：“《商书》所说的‘恶的蔓延，如同大火在草原上燃烧，不可以接近，难道还可以扑灭？’恐怕就像蔡哀侯吧！”
冬季，单伯和齐桓公、宋桓公、卫惠公、郑厉公在鄄地会见，这是由于宋国顺服的缘故。
', NULL, '', 'indent', 1558693693, '5ce756baba39c800684d6c34', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642911, '左传 · 庄公 · 庄公十五年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有五年春，齐侯、宋公、陈侯、卫侯、郑伯会于鄄。夏，夫人姜氏如齐。秋，宋人、齐人、邾人伐郳。郑人侵宋。冬十月。
【传】十五年春，复会焉，齐始霸也。
秋，诸侯为宋伐郳。郑人间之而侵宋。
', '', '', '十五年春季，齐桓公、宋桓公、陈宣公、卫惠公、郑厉公再次在鄄地会见，齐国开始称霸。
秋季，各诸侯为宋国而共同攻打郳国。郑国人便乘机入侵宋国。', NULL, '', 'indent', 1558693729, '5ce756de30863b0068d06e54', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642912, '左传 · 庄公 · 庄公十六年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有六年春王正月。夏，宋人、齐人、卫人伐郑。秋，荆伐郑。冬十有二月，会齐侯、宋公、陈侯、卫侯、郑伯、许男、滑伯、滕子同盟于幽。邾子克卒。
【传】十六年夏，诸侯伐郑，宋故也。
郑伯自栎入，缓告于楚。秋，楚伐郑，及栎，为不礼故也。
郑伯治与于雍纠之乱者。九月，杀公子阏，刖强锄。公父定叔出奔卫。三年而复之，曰：「不可使共叔无后于郑。」使以十月入，曰：「良月也，就盈数焉。」
君子谓：「强锄不能卫其足。」
冬，同盟于幽，郑成也。
王使虢公命曲沃伯以一军为晋侯。
初，晋武公伐夷，执夷诡诸。蒍国请而免之。既而弗报。故子国作乱，谓晋人曰：「与我伐夷而取其地。」遂以晋师伐夷，杀夷诡诸。周公忌父出奔虢。惠王立而复之。', '', '', '十六年夏季，各诸侯联军进攻郑国，这是由于郑国入侵宋国的缘故。
郑厉公从栎地回到国都，没有及时通知楚国。秋季，楚国进攻郑国，到达栎地，这是为了报复郑厉公对楚国不恭敬没有及时通知的缘故。
郑厉公惩罚参与雍纠之乱的人。九月，杀死了公子阏，砍去强锄的两脚。
公父定叔逃亡到卫国。过了三年，郑厉公又让他回国了，说：“不能让共叔在郑国的后代没有禄位。”让他在十月回到国内，说：“这是好月份，十月是个满数呢。”
君子认为，“强锄不能保住他的两脚”。
冬季，鲁庄公和齐桓公、宋桓公、陈宣公、卫惠公、郑厉公、许穆公、滑伯、滕子在幽地一起结盟，这是为了对郑国讲和。
周僖王派虢公命令曲沃伯建立一军，做晋国国君。
当初，晋武公进攻夷地，俘虏了夷诡诸。..国为他请求因而释放了他。
后来夷诡诸并不报答，所以子国（即..国）作乱，对晋国人说：“和我一起进攻夷地而夺取它的土地。”就带着晋国军队进攻夷地，杀死了夷诡诸。周公忌父逃亡到虢国。到周惠王时便又立他为君而恢复夷地。
', NULL, '', 'indent', 1558693768, '5ce75704a673f50068e4b361', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642913, '左传 · 庄公 · 庄公十七年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有七年春，齐人执郑詹。夏，齐人歼于遂。秋，郑詹自齐逃来。冬，多麋。
【传】十七年春，齐人执郑詹，郑不朝也。
夏，遂因氏，颌氏、工娄氏、须遂氏飨齐戍，醉而杀之，齐人歼焉。

', '', '', '十七年春季，齐国人抓住郑詹，这是由于郑国不去朝见齐国。
夏季，遂国的因氏、颌氏、工娄氏、须遂氏用酒食招待在遂国戍守的齐军，灌醉以后杀了他们。齐国戍守者被因氏四族全部杀尽。', NULL, '', 'indent', 1558693802, '5ce7572843e78c0067e32272', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642914, '左传 · 庄公 · 庄公十八年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有八年春王三月，日有食之。夏，公追戎于济西。秋，有《或虫》。冬十月。
【传】十八年春，虢公、晋侯朝王，王飨醴，命之宥，皆赐玉五珏，马三匹。非礼也。王命诸侯，名位不同，礼亦异数，不以礼假人。
虢公、晋侯、郑伯使原庄公逆王后于陈。陈妫归于京师，实惠后。
夏，公追戎于济西。不言其来，讳之也。
秋，有蜮，为灾也。
初，楚武王克权，使斗缗尹之。以叛，围而杀之。迁权于那处，使阎敖尹之。及文王即位，与巴人伐申而惊其师。巴人叛楚而伐那处，取之，遂门于楚。阎敖游涌而逸。楚子杀之，其族为乱。冬，巴人因之以伐楚。', '', '', '十八年春季，虢公、晋献公朝觐周惠王。周惠王用甜酒招待，又允许他们向自己敬酒。同时各赐给他们玉五对，马三匹。这是不合于礼的。周天子对诸侯有所策命，封爵地位不一样，礼仪的等级也不一样，不能把礼仪随便给人。
虢公、晋献公、郑厉公派原庄公去陈国迎接王后。陈妫嫁到京城，就是惠后。
夏季，庄公在济水的西边追逐戎人。《春秋》没有记载戎人来攻，这是由于避讳提起这件事。
秋季，有蜮虫，《春秋》所以记载，是由于造成了灾害。
当初，楚武王攻克权国，派鬬缗做这里的长官，鬬缗据有权地而叛变楚国。楚国包围权地而杀掉了鬬缗，又把权地的百姓迁到那处，改派阎敖治理这个地方。等到文王即位，和巴国人一起进攻申国，楚军使巴军受到惊恐。巴国人背叛楚国而进攻那处，加以占领，于是又攻打楚国都城的城门。阎敖在涌水里游泳逃走，楚文王杀了阎敖，他的族人作乱。冬季，巴国人因此进攻楚国。
', NULL, '', 'indent', 1558693875, '5ce757717b968a007634447e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642915, '左传 · 庄公 · 庄公十九年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有九年春王正月。夏四月。秋，公子结媵陈人之妇于鄄，遂及齐侯、宋公盟。夫人姜氏如莒。冬，齐人、宋人、陈人伐我西鄙。
【传】十九年春，楚子御之，大败于津。还，鬻拳弗纳。送伐黄，败黄师于碏陵。还，及湫，有疾。夏六月庚申卒，鬻拳葬诸夕室，亦自杀也，而葬于絰
初，鬻拳强谏楚子，楚子弗从，临之以兵，惧而从之。鬻拳曰：「吾惧君以皇。兵，罪莫大焉。」遂自刖也。楚人以为大阍，谓之大伯，使其后掌之。君子「鬻拳可谓爱君矣，谏以自纳于刑，刑犹不忘纳君于善。」
初，王姚嬖于庄王，生子颓。子颓有宠，蒍国为之师。及惠王即位。取蒍国之圃以为囿，边伯之宫近于王宫，王取之。王夺子禽祝跪与詹父田，而收膳夫之秩。故蒍国、边伯、石速、詹父、子禽祝跪作乱，因苏氏。秋，五大夫奉子颓以伐王，不克，出奔温。苏子奉子颓以奔卫。卫师、燕师伐周。冬，立子颓。', '', '', '十九年春季，楚文王发兵抵御巴军，在津地被巴军打得大败。回国，鬻拳不开城门接纳，楚文王就转而进攻黄国，在踖陵打败了黄国的军队。楚文王回国，到达湫地时得了病。夏季，六月十五日，楚文王死去。鬻拳把他安葬在夕室，然后自己也自杀身亡，死后被安葬在地下宫殿的前院里。
当初，鬻拳坚决劝阻楚文王，楚文王不听从。鬻拳拿起武器对准楚文王，楚文王害怕而被迫听从。鬻拳说：“我用武器威胁国君，没有比这再大的罪过了。”于是就自己砍去两脚。楚国人让他担任卫戍楚都城门的官职，称之为太伯，并且让他的后代执掌这个官职。
君子说：“鬻拳可以说是爱护国君了，由于劝阻而自己使自己受刑，受了刑还不忘记使国君归于正道。”
当初，王姚受到周庄王的宠爱，生了子穨。子穨也受到宠爱，..国做他的师傅。等惠王继承王位，夺取了..国的菜园来畜养野兽。边伯的房子，近在王宫的旁边，惠王也占取了。惠王又夺取了子禽祝跪和詹父的田地，收回了膳夫石速的俸禄。所以..国、边伯、石速、詹父、子禽祝跪发动叛乱，依靠苏氏。秋季，五位大夫拥戴子穨攻打惠王，没有得胜，逃亡到温地。苏子拥着子穨逃亡到卫国。卫国、燕国的军队进攻成周。冬季，立王子穨为周天子。', NULL, '', 'indent', 1558693913, '5ce757977b968a0076344655', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642916, '左传 · 庄公 · 庄公二十年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十年春王二月，夫人姜氏如莒。夏，齐大灾。秋七月。冬，齐人伐戎。
【传】二十年春，郑伯和王室，不克。执燕仲父。夏，郑伯遂以王归，王处于栎。秋，王及郑伯入于邬。遂入成周，取其宝器而还。
冬，王子颓享五大夫，乐及遍舞。郑伯闻之，见虢叔，曰：「寡人闻之，哀乐失时，殃咎必至。今王子颓歌舞不倦，乐祸也。夫司寇行戮，君为之不举，而况敢乐祸乎！奸王之位，祸孰大焉？临祸忘忧，忧必及之。盍纳王乎？」虢公曰：「寡人之愿也。」
', '', '', '二十年春季，郑厉公调解周惠王和子穨之间的纠纷，没有成功。逮捕了燕仲父。夏季，郑厉公就带了周惠王回国。惠王住在栎地。秋季，惠王和郑厉公到了邬地，于是就进入成周，取得了成周的宝器而回。
冬季，王子穨设享礼招待五位大夫，奏乐及于各个时代所有的舞蹈。郑厉公听到这件事，见到虢叔说：“我听说，悲哀或者高兴，若不是时候，灾祸一定会到来。现在王子穨观赏歌舞而不知疲倦，这是以祸患为高兴。司寇杀人，国君为此而减膳撤乐，何况敢以祸患而高兴呢？篡夺天子的职位，祸患还有比这更大的吗？面临祸患而忘记忧愁，忧愁一定到来。何不让天子复位呢？”虢公说：“这是我的愿望。”', NULL, '', 'indent', 1558693944, '5ce757b6c8959c0069ac33f2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642917, '左传 · 庄公 · 庄公二十一年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有一年春，王正月。夏五月辛酉，郑伯突卒。秋七月戊戌，夫人姜氏薨。冬十有二月，葬郑厉公。
【传】二十一年春，胥命于弭。夏，同伐王城。郑伯将王，自圉门入，虢叔自北门入，杀王子颓及五大夫。郑伯享王于阙西辟，乐备。王与之武公之略，自虎牢以东。原伯曰：「郑伯效尤，其亦将有咎。」五月，郑厉公卒。
王巡虢守。虢公为王宫于玤，王与之酒泉。郑伯之享王也，王以后之鞶鉴予之。虢公请器，王予之爵。郑伯由是始恶于王。
冬，王归自虢。', '', '', '二十一年春季，郑厉公和虢公在弭地会谈。夏季，一起进攻王城。郑厉公拥着惠王从圉门入城，虢叔从北门入城。杀了王子穨和五个大夫。郑厉公在宫门口西阙设宴招待惠王，全套乐舞齐备。惠王赐给他郑武公时代从虎牢以东的土地。原伯说：“郑伯学了做坏事，恐怕也会招来灾祸。”五月，郑厉公去世。
周惠王巡视虢公防守的土地，虢公为惠王在玤地建造了行宫，惠王就把酒泉赐给他。
以前当郑厉公设宴招待惠王的时候，惠王把王后的鞶鉴赐给他。虢公也请求赏赐器物，惠王把青铜酒杯赐给他。由于鞶鉴没有青铜酒杯贵重，郑厉公从此怨恨周惠王。
冬季，周惠王从虢国回到成周。', NULL, '', 'indent', 1558693972, '5ce757d2ba39c800684d7a2c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642918, '左传 · 庄公 · 庄公二十二年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十二年春王正月，肆大眚。癸丑，葬我小君文姜。陈人杀其公子御寇。夏五月。秋七月丙申，及齐高傒盟于防。冬，公如齐纳币。
【传】二十二年春，陈人杀其大子御寇，陈公子完与颛孙奔齐。颛孙自齐来奔。
齐侯使敬仲为卿。辞曰：「羁旅之臣，幸若获宥，及于宽政，赦其不闲于教训而免于罪戾，弛于负担，君之惠也，所获多矣。敢辱高位，以速官谤。请以死告。《诗》云：『翘翘车乘，招我以弓，岂不欲往，畏我友朋。』」使为工正。
饮桓公酒，乐。公曰：「以火继之。」辞曰：「臣卜其昼，未卜其夜，不敢。」君子曰：「酒以成礼，不继以淫，义也。以君成礼，弗纳于淫，仁也。」
初，懿氏卜妻敬仲，其妻占之，曰：「吉，是谓『凤皇于飞，和鸣锵锵，有妫之后，将育于姜。五世其昌，并于正卿。八世之后，莫之与京。』」陈厉公，蔡出也。故蔡人杀五父而立之，生敬仲。其少也。周史有以《周易》见陈侯者，陈侯使筮之，遇《观》之《否》。曰：「是谓『观国之光，利用宾于王。』代陈有国乎。不在此，其在异国；非此其身，在其子孙。光，远而自他有耀者也。《坤》，土也。《巽》，风也。《乾》，天也。风为天于土上，山也。有山之材而照之以天光，于是乎居土上，故曰：『观国之光，利用宾于王。』庭实旅百，奉之以玉帛，天地之美具焉，故曰：『利用宾于王。』犹有观焉，故曰其在后乎。风行而着于土，故曰其在异国乎。若在异国，必姜姓也。姜，大岳之后也。山岳则配天，物莫能两大。陈衰，此其昌乎。」
及陈之初亡也，陈桓子始大于齐。其后亡成，成子得政。', '', '', '二十二年春季，陈国人杀了他们的太子御寇。陈国的敬仲和颛孙逃亡到齐国。颛孙又从齐国逃亡到鲁国来。
齐桓公想任命敬仲做卿，他辞谢说：“寄居在外的小臣如果有幸获得宽恕，能在宽厚的政治之下，赦免我的缺乏教训，而得以免除罪过，放下恐惧，这是君王的恩惠。我所得的已经很多了，哪里敢接受这样的高位而很快地招来官员们的指责？谨昧死上告。《诗》说：‘高高的车子，招呼我用的是弓。
难道我不想前去？怕的是我的友朋。’”齐桓公就让他担任了工正官。
敬仲招待齐桓公饮酒，桓公很高兴。天晚了，桓公说：“点上烛继续喝酒。”敬仲辞谢说：“臣只知道白天招待君主，不知道晚上陪饮。不敢遵命。”
君子说：“酒用来完成礼仪，不能没有节制，这是义；由于和国君饮酒完成了礼仪，不使他过度，这是仁。”
当初，懿氏要把女儿嫁给敬仲而占卜吉凶。他的妻子占卜，说：“吉利。这叫做‘凤凰飞翔，唱和的声音嘹亮。妫氏的后代，养育于齐姜。第五代就要昌盛，官位和正卿一样。第八代以后，没有人可以和他争强。’”
陈厉公是蔡国女人所生，所以蔡国人杀了五父而立他为君，生了敬仲。
在敬仲年幼的时候，有一个成周的太史用《周易》去见陈厉公，陈厉公让他占筮，占得的《观》卦变成《否》卦。周太史说：“这就叫做‘出聘观光，利于作上宾于君王’。这个人恐怕要代替陈而享有国家了吧！但不在这里，而在别国，不在这个人身上，而在他的子孙。光，是从另外地方照耀而来的。《坤》是土，《巽》是风，《乾》是天。风起于天而行于土上，这就是山。有了山上的物产，又有天光照射，这就居于地土上，所以说‘出聘观光，利于作上宾于君王’，庭中陈列的礼物上百件，另外进奉束帛玉璧，天上地下美好的东西都具备了，所以说‘利于作上宾于君王’。还有等着观看，所以说他的昌盛在于后代吧！风行走最后落在土地上，所以说他的昌盛在于别国吧！如果在别国，必定是姜姓之国。姜是太岳的后代。山岳高大可以与天相配。但事物不可能两者一样大，陈国衰亡，这个氏族就要昌盛吧！”
等到陈国第一次灭亡，陈桓子才在齐国有强大的势力，后来楚国再次灭亡陈国，陈成子取得了齐国政权。
', NULL, '', 'indent', 1558694036, '5ce758127b968a0076344c65', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642919, '左传 · 庄公 · 庄公二十三年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有三年春，公至自齐。祭叔来聘。夏，公如齐观社。公至自齐。荆人来聘。公及齐侯遇于谷。萧叔朝公。秋，丹桓宫楹。冬十有一月，曹伯射姑卒。十有二月甲寅，公会齐侯盟于扈。
【传】二十三年夏，公如齐观社，非礼也。曹刿谏曰：「不可。夫礼，所以整民也。故会以训上下之则，制财用之节；朝以正班爵之义，帅长幼之序；征伐以讨其不然。诸侯有王，王有巡守，以大习之。非是，君不举矣。君举必书，书而不法，后嗣何观？」
晋桓、庄之族逼，献公患之。士蔿曰：「去富子，则群公子可谋也已。」公曰：「尔试其事。」士蔿与群公子谋，谮富子而去之。
秋，丹桓宫之楹。', '', '', '二十三年夏季，鲁庄公到齐国去观看祭祀社神，这是不合于礼的。曹刿劝谏说：“不行。礼，是用来整饬百姓的。所以会见是用以训示上下之间的法则，制订节用财赋的标准；朝觐是用以排列爵位的仪式，遵循老少的次序；征伐是用以攻打对上的不尊敬。诸侯朝聘天子，天子视察四方，以熟悉会见和朝觐的制度。如果不是这样，国君是不会有举动的。国君的举动史官一定要加以记载。记载而不合于法度，后代子孙看到的是什么？”
晋国桓叔、庄伯的家族势力强盛而威逼公族，晋献公担心这种情况。士蔿说：“去掉富子，对公子们就好办了。”晋献公说：“你试着办这件事。”
士蔿就在公子们中间讲富子的坏话，然后和公子们设法去掉了富子。秋季，在桓公庙的梁柱上涂上红漆。', NULL, '', 'indent', 1558694070, '5ce7583443e78c0067e32ecb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642920, '左传 · 庄公 · 庄公二十四年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有四年春王三月，刻桓宫桷。葬曹庄公。夏，公如齐逆女。秋，公至自齐。八月丁丑，夫人姜氏入。戊寅，大夫宗妇觌，用币。大水。冬，戎侵曹。曹羁出奔陈。赤归于曹。郭公。
【传】二十四年春，刻其桷，皆非礼也。御孙谏曰：「臣闻之：『俭，德之共也；侈，恶之大也。』先君有共德而君纳诸大恶，无乃不可乎！」
秋，哀姜至。公使宗妇觌，用币，非礼也。御孙曰：「男贽大者玉帛，小者禽鸟，以章物也。女贽不过榛栗枣修，以告虔也。今男女同贽，是无别也。男女之别，国之大节也。而由夫人乱之，无乃不可乎！」
晋士蒍又与群公子谋，使杀游氏之二子。士蒍告晋侯曰：「可矣。不过二年，君必无患。」
', '', '', '二十四年春季，又在桓公庙的椽子上雕花，这件事与去年庙柱上涂红漆都是不合礼制的。御孙劝阻说：“下臣听说：‘节俭，是善行中的大德；奢侈，是邪恶中的大恶。’先君具有大德，而君王却把它放到大恶里去，恐怕不可以吧？”
秋季，哀姜来到鲁国，庄公让同姓大夫的夫人相见，相见时用玉帛作为见面礼，这是不合于礼的。御孙说：“男人相见的礼物，大的是玉帛，小的是禽鸟，用东西来表明等级。女人相见的礼物，不超过榛子、栗子、枣子、干肉，以表示诚敬而已。现在男女用相同的相见礼，这是没有区别了。男女的区别，是国家的大法，由于夫人而搞乱了，恐怕不可以吧！”
晋国的士..又和公子们策划，让他们杀了游氏的两个儿子。士..告诉晋献公说：“行了。不超过两年，君王就不必担心了。”', NULL, '', 'indent', 1558694106, '5ce758577b968a0076344ed7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642921, '左传 · 庄公 · 庄公二十五年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有五年春，陈侯使女叔来聘。夏五月癸丑，卫侯朔卒。六月辛未，朔，日有食之，鼓、用牲于社。伯姬归于杞。秋，大水，鼓、用牲于社、于门。冬，公子友如陈。
【传】二十五年春，陈女叔来聘，始结陈好也。嘉之，故不名。
夏六月辛未，朔，日有食之。鼓，用牲于社，非常也。唯正月之朔，慝未作，日有食之，于是乎用币于社，伐鼓于朝。
秋，大水。鼓，用牲于社、于门，亦非常也。凡天灾，有币无牲。非日月之眚，不鼓。
晋士蒍使群公子尽杀游氏之族，乃城聚而处之。
冬，晋侯围聚，尽杀群公子。', '', '', '二十五年春季，陈国的女叔来鲁国聘问，这是开始和陈国友好。《春秋》赞美这件事，所以不记载女叔的名字。
夏季六月初一日，发生了日食。击鼓，用牺牲祭祀土地神庙，这是不合于常礼的。只有夏历四月的初一，阴气没有发作，如果发生日食，才用玉帛祭祀土地之神，在朝廷之上击鼓。
秋季，有大水，击鼓，用牺牲祭祀土地神庙和城门门神，也不合于常礼。
凡是天灾，祭祀时只能用玉帛而不用牺牲。不是日食、月蚀，不击鼓。
晋国的士..让公子们杀尽了游氏家族，于是在聚地筑城而让公子们去住。冬季，晋献公包围了聚城，把公子们全部杀光。
', NULL, '', 'indent', 1558694140, '5ce7587ad5de2b007048347b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642922, '左传 · 庄公 · 庄公二十六年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有六年春，公伐戎。夏，公至自伐戎。曹杀其大夫。秋，公会宋人、齐人，伐徐。冬十有二月癸亥，朔，日有食之。
【传】二十六年春，晋士蒍为大司空。
夏，士蒍城绛，以深其宫。
秋，虢人侵晋。冬，虢人又侵晋。
', '', '', '二十六年春季，晋国的士..做了大司空。
夏季，士..加高并加大绛都城垣，同时也加高宫墙。
秋季，虢国人入侵晋国。
冬季，虢国人又入侵晋国。', NULL, '', 'indent', 1558694186, '5ce758a7c8959c0069ac3e33', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642923, '左传 · 庄公 · 庄公二十七年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有七年春，公会杞伯姬于洮。夏六月，公会齐侯、宋公、陈侯、郑伯同盟于幽。秋，公子友如陈，葬原仲。冬，杞伯姬来。莒庆来逆叔姬。杞伯来朝。公会齐侯于城濮。
【传】二十七年春，公会杞伯姬于洮，非事也。天子非展义不巡守，诸侯非民事不举，卿非君命不越竟。
夏，同盟于幽，陈，郑服也。
秋，公子友如陈，葬原仲，非礼也。原仲，季友之旧也。
冬，杞伯姬来，归宁也。凡诸侯之女，归宁曰来，出曰来归。夫人归宁曰如某，出曰归于某。
晋侯将伐虢，士蒍曰：「不可，虢公骄，若骤得胜于我，必弃其民。无众而后伐之，欲御我谁与？夫礼乐慈爱，战所畜也。夫民让事乐和，爱亲哀丧而后可用也。虢弗畜也，亟战将饥。」
王使召伯廖赐齐侯命，且请伐卫，以其立子颓也。', '', '', '二十七年春季，鲁庄公和杞伯姬在洮地会见，与国家大事无关。天子不是为了宣扬德义不出去视察，诸侯不是为了百姓的事情不能出行，卿没有国君的命令不能越过国境。
夏季，鲁庄公和齐桓公、宋桓公、陈宣公、郑文公在幽地一起结盟，由于陈国和郑国都顺服了。
秋季，公子友到陈国安葬原仲，这不合于礼。原仲，只是季友私人的老朋友。
冬季，杞伯姬来，这是回娘家。凡是诸侯的女儿，回娘家叫做“来”，被夫家休弃叫做“来归”，本国国君的夫人回娘家叫做“如某”，被休弃叫做“归于某”。
晋献公准备进攻虢国。士..说：“不行。虢公骄傲，如果突然和我国交战而得胜，就必定会丢弃他的百姓。他失去群众然后我们再去进攻，即使要抗拒，有谁会跟他呢？礼、乐、慈、爱，这是作战所应当事先具备的。百姓谦让、和协、对亲属爱护，对丧事哀痛，这才可以使用。现在虢国不具备这些，多次对外作战，百姓会气馁的。”
周惠王派遣召伯廖赐命齐桓公，并要求他进攻卫国，因为卫国曾拥立子穨做周天子。', NULL, '', 'indent', 1558694222, '5ce758cba673f50068e4c57a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642924, '左传 · 庄公 · 庄公二十八年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有八年春，王三月甲寅，齐人伐卫。卫人及齐人战，卫人败绩。夏四月丁未，邾子琐卒。秋，荆伐郑，公会齐人、宋人救郑。冬，筑郿。大无麦、禾，臧孙辰告籴于齐。
【传】二十八年春，齐侯伐卫。战，败卫师。数之以王命，取赂而还。
晋献公娶于贾，无子。烝于齐姜，生秦穆夫人及大子申生。又娶二女于戎，大戎狐姬生重耳，小戎子生夷吾。晋伐骊戎，骊戎男女以骊姬。归生奚齐。其娣生卓子。骊姬嬖，欲立其子，赂外嬖梁五，与东关嬖五，使言于公曰：「曲沃，君之宗也。蒲与二屈，君之疆也。不可以无主。宗邑无主则民不威，疆埸无主则启戎心。戎之生心，民慢其政，国之患也。若使大子主曲沃，而重耳、夷吾主蒲与屈，则可以威民而惧戎，且旌君伐。」使俱曰：「狄之广莫，于晋为都。晋之启土，不亦宜乎？」晋侯说之。夏，使大子居曲沃，重耳居蒲城，夷吾居屈。群公子皆鄙，唯二姬之子在绛。二五卒与骊姬谮群公子而立奚齐，晋人谓之二五耦。
楚令尹子元欲蛊文夫人，为馆于其宫侧，而振万焉。夫人闻之，泣曰：「先君以是舞也，习戎备也。今令尹不寻诸仇雠，而于未亡人之侧，不亦异乎！」御人以告子元。子元曰：「妇人不忘袭仇，我反忘之！」
秋，子元以车六百乘伐郑，入于桔柣之门。子元、斗御疆、斗梧、耿之不比为旆，斗班、王孙游、王孙喜殿。众车入自纯门，及逵市。县门不发，楚言而出。子元曰：「郑有人焉。」诸侯救郑，楚师夜遁。郑人将奔桐丘，谍告曰：「楚幕有乌。」乃止。
冬，饥。臧孙辰告籴于齐，礼也。
筑郿，非都也。凡邑有宗庙先君之主曰都，无曰邑。邑曰筑，都曰城。
', '', '', '二十八年春季，齐桓公讨伐卫国，作战，打败了卫军，用周天子的名义责备卫国，取得了财货回国。
晋献公从贾国娶了妻子，没生儿子。他和齐姜私通，生了秦穆夫人和太子申生。又在戎娶了两个女人，大戎狐姬生了重耳，小戎子生了夷吾。晋国攻打骊戎，骊戎男把骊姬献给晋献公，回国后生了奚齐，她的妹妹生了卓子。
骊姬受到宠爱，想立自己的儿子为太子，贿赂男宠梁五和东关嬖五，让他们对晋献公说：“曲沃是君王的宗邑，蒲地和二屈是君王的边疆，不可以没有强大的地方官。宗邑缺乏有力的主管，百姓就不会畏惧；边疆没有有力的主管，就会勾引戎狄侵犯的念头。戎狄有侵犯的念头，百姓就会轻视政令，这是国家的祸患。如果让太子主管曲沃，又让重耳、夷吾主管蒲地和二屈，就可以使百姓畏惧、戎狄害怕，而且可以表彰君王的功绩。”又让这两个人一起对晋献公说：“狄人广漠的土地，如果归属晋国，可以在那里开疆辟土。
晋国开疆辟土，不也恰当吗？”晋侯很高兴。夏季，让太子住在曲沃，重耳住在蒲地，夷吾住在屈地。别的公子也都住在边境上，只有骊姬和她妹妹的儿子在绛城。两个五梁五和东关嬖五最终和骊姬诬陷了公子们而立了奚齐为太子，晋国人称他们为“两个名叫五的狼狈朋比”。
楚国的令尹子元想诱惑文王夫人，在她的宫旁造了房舍，在里边摇铃铎跳万舞。夫人听到了，哭着说：“先君让人跳这个舞蹈，是用来演习战备的。
现在令尹不用于仇敌而用于一个寡妇的旁边，不也是奇怪吗？”侍者告诉了子元。子元说：“女人不忘记袭击仇敌，我反倒忘了。”
秋季，子元带领六百辆战车进攻郑国，进入桔柣之门。子元、鬬御彊、鬬梧、耿之不比率领前军，鬬班、王孙游、王孙喜在后面。车队从纯门进去，到达大路上的市场。内城的闸门没有放下。楚国人用楚国方言说了一阵就退出去了。子元说：“郑国有人才。”诸侯救援郑国，楚军就夜里溜走了。郑国人已经准备逃往桐丘，间谍报告说：“楚国的帐篷上有乌鸦。”于是就停止逃跑。
冬季，发生饥荒。鲁国的大夫臧孙辰向齐国购买粮食，这是合于礼的。
鲁国筑郿邑，因为郿不是都市。凡是城邑，有宗庙和先君神主的叫做“都”，没有的叫做“邑”。建造邑叫做“筑”，建造都叫做“城”。
', NULL, '', 'indent', 1558694261, '5ce758f37b968a0076345640', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642925, '左传 · 庄公 · 庄公二十九年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有九年春，新延厩。夏，郑人侵许。秋，有蜚。冬十有二月，纪叔卒。城诸及防。
【传】二十九年春，新作延厩。书，不时也。凡马日中而出，日中而入。
夏，郑人侵许。凡师有钟鼓曰伐，无曰侵，轻曰袭。
秋，有蜚，为灾也。凡物不为灾不书。
冬十二月，城诸及防，书，时也。凡土功，龙见而毕务，戒事也。火见而致用，水昏正而栽，日至而毕。
樊皮叛王。', '', '', '二十九年春季，新造延厩。《春秋》所以记载这件事，是由于不合时令。
凡是马，春分时节放牧，秋分时节入马圈。
夏季，郑国人入侵许国。凡是出兵，有钟鼓之声叫做“伐”，没有叫做“侵”，轻装部队快速突击叫做“袭”。
秋季，发现蜚盘虫，成了灾。凡是事物不成灾，《春秋》就不加记载。
冬季十二月，在诸地和防地筑城。《春秋》记载这件事，是因为合于时令。凡是土木工程，苍龙星出现，此时农事完毕，就要做准备了；大火星出现，就要把用具放到工场上，黄昏，营室星在南方出现，就要筑墙立板，冬至以后不再施工。
周大夫樊皮背叛周惠王。', NULL, '', 'indent', 1558694297, '5ce7591743e78c0067e33925', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642926, '左传 · 庄公 · 庄公三十年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三十年春王正月。夏，次于成。秋七月，齐人降鄣。八月癸亥，葬纪叔。九月庚午朔，日有食之，鼓、用牲于社。冬，公及齐侯遇于鲁济。齐人伐山戎。
【传】三十年春，王命虢公讨樊皮。夏四月丙辰，虢公入樊，执樊仲皮，归于京师。
楚公子元归自伐郑，而处王宫，斗射师谏，则执而梏之。
秋，申公斗班杀子元，斗谷於菟为令尹，自毁其家以纾楚国之难。
冬，遇于鲁济，谋山戎也，以其病燕故也。', '', '', '三十年春季，周惠王命令虢公讨伐樊皮。夏季，四月十四日，虢公进入樊国，俘虏了樊皮，带到京城。
楚国的公子元攻打郑国回来，住在王宫里。鬬射师劝阻，就把他抓起来带上手铐。秋季，申公鬬班杀死子元。鬬穀於菟做令尹，自己捐献家财，来缓和楚国的危难。
冬季，鲁庄公和齐桓公在鲁国济水非正式会见，策划攻打山戎，因为山戎危害燕国的缘故。
', NULL, '', 'indent', 1558694331, '5ce75939ba39c800684d89b1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642927, '左传 · 庄公 · 庄公三十一年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三十有一年春，筑台于郎。夏四月，薛伯卒。筑台于薛。六月，齐侯来献戎捷。秋，筑台于秦。冬，不雨。
【传】三十一年夏六月，齐侯来献戎捷，非礼也。凡诸侯有四夷之功，则献于王，王以警于夷。中国则否。诸侯不相遗俘。
', '', '', '三十一年夏季，六月，齐桓公来鲁国奉献讨伐山戎的战利品，这是不合于礼的。凡是诸侯讨伐四方夷狄有功，就要奉献给周天子，周天子用来警戒四方夷狄；在中原作战就不这样。诸侯之间不能互相赠送俘虏。 ', NULL, '', 'indent', 1558694352, '5ce7594e7b968a0076345abe', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643118, '左传 · 哀公 · 哀公二十二年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【传】二十二年夏四月，邾隐公自齐奔越，曰：「吴为无道，执父立子。」越人归之，大子革奔越。
冬十一月丁卯，越灭吴。请使吴王居甬东，辞曰：「孤老矣，焉能事君？」乃缢。越人以归。
', '', '', '二十二年夏季，四月，邾隐公从齐国逃亡到越国，说：“吴国无道，拘捕了父亲立了儿子。”越国人把他送回去，太子革逃亡到越国。
冬季，十一月二十七日，越国灭亡吴国，请求让吴王住在甬东。吴王辞谢说：“我老了，哪里还能事奉君王？”于是就上吊死了。越国人把他的尸体送了回去。', NULL, '', 'indent', 1559296684, '5cf08a2ac8959c00690f4053', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642928, '左传 · 庄公 · 庄公三十二年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三十有二年春，城小谷。夏，宋公、齐侯遇于梁丘。秋七月癸巳，公子牙卒。八月癸亥，公薨于路寝。冬十月己未，子般卒。公子庆父如齐。狄伐邢。
【传】三十二年春，城小谷，为管仲也。
齐侯为楚伐郑之故，请会于诸侯。宋公请先见于齐侯。夏，遇于梁丘。
秋七月，有神降于莘。
惠王问诸内史过曰：「是何故也？」对曰：「国之将兴，明神降之，监其德也；将亡，神又降之，观其恶也。故有得神以兴，亦有以亡，虞、夏、商、周皆有之。」王曰：「若之何？」对曰：「以其物享焉，其至之日，亦其物也。」王从之。内史过往，闻虢请命，反曰：「虢必亡矣，虐而听于神。」
神居莘六月。虢公使祝应、宗区、史嚚享焉。神赐之土田。史嚚曰：「虢其亡乎！吾闻之：国将兴，听于民；将亡，听于神。神，聪明正直而一者也，依人而行。虢多凉德，其何土之能得！」
初，公筑台临党氏，见孟任，从之。閟，而以夫人言许之。割臂盟公，生子般焉。雩，讲于梁氏，女公子观之。圉人荦自墙外与之戏。子般怒，使鞭之。公曰：「不如杀之，是不可鞭。荦有力焉，能投盖于稷门。」
公疾，问后于叔牙。对曰：「庆父材。」问于季友，对曰：「臣以死奉般。」公曰：「乡者牙曰庆父材。」成季使以君命命僖叔待于金咸巫氏，使金咸季鸩之，曰：「饮此则有后于鲁国，不然，死且无后。」饮之，归及逵泉而卒，立叔孙氏。
八月癸亥，公薨于路寝。子般即位，次于党氏。冬十月己未，共仲使圉人荦贼子般于党氏。成季奔陈。立闵公。', '', '', '三十二年春季，齐国在小穀筑了一座城，这是为管仲而筑的。
齐桓公由于楚国进攻郑国的缘故，请求和诸侯会见。宋桓公请求和齐桓公先行会见。夏季，在梁丘非正式会见。
秋季，七月，有神明在莘地下降。周惠王向内史过询问说：“这是什么原因？”内史过回答说：“国家将要兴起，神明下降，观察它的德行；将要灭亡，神明也会下降，观察它的邪恶。所以有的得到神明而兴起，也有的得到神明而灭亡，虞、夏、商、周都有过这种情况。”周惠王说：“怎么办呢？”
内史过回答说：“用相应的物品来祭祀。他来到的日子，按规定，这个日子的祭祀该是什么，也就是他的祭品。”周惠王听从了。内史过前去祭祀，听到虢国请求神明赐予，回来说：“虢国必定要灭亡了，暴虐而听命于神明。”
神明在莘地住了六个月，虢公派遣祝应、宗区、史嚚去祭祀。神明答应赐给他疆土田地。史嚚说：“虢国恐怕要灭亡了吧！我听说：‘国家将要兴起，听百姓的；将要灭亡，听神明的。’神明，是聪明正直而一心一意的，按照不同的人而行事。虢国多的是恶德坏事，又有什么土地能够得到？”
当初，庄公建造高台，可以看到党家。在台上望见党氏的女儿孟任，就跟着她走。孟任闭门拒绝。庄公答应立她为夫人。她答应了，割破手臂和庄公盟誓，后来就生了子般。一次正当雩祭，事先在梁家演习，庄公的女公子观看演习，圉人荦从墙外对她调戏。子般发怒，让人鞭打荦。庄公说：“不如杀掉他，这个人不能鞭打。他很有力气，可以举起稷门的城门，能将门扇远远地扔出去。”
庄公得了重病，向叔牙询问继承人的事。叔牙回答说：“庆父有才能。”向季友询问，季友回答说：“臣用死来事奉子般。”庄公说：“刚才叔牙说‘庆父有才能’。”季友就派人用国君的名义让僖叔（叔牙）等待在鍼巫家里，让鍼巫用毒酒毒死叔牙，说：“喝了这个，你的后代在鲁国还可以享有禄位；不这样，你死了，后代还没有禄位。”叔牙喝了毒酒，回去，到达逵泉就死去了。鲁国立他的后人为叔孙氏。
八月初五日，鲁庄公死在正寝里。子般即位，住在党氏家里。冬季，十月初二日，共仲派圉人荦在党家刺死了子般。成季逃亡到陈国。立闵公为国君。
', NULL, '', 'indent', 1558694387, '5ce759707b968a0076345c25', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642929, '左传 · 闵公 · 闵公元年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】元年春王正月。齐人救邢。夏六月辛酉，葬我君庄公。秋八月，公及齐侯盟于落姑。季子来归。冬，齐仲孙来。
【传】元年春，不书即位，乱故也。
狄人伐邢。管敬仲言于齐侯曰：「戎狄豺狼，不可厌也。诸夏亲昵，不可弃也。宴安鸩毒，不可怀也。《诗》云：『岂不怀归，畏此简书。』简书，同恶相恤之谓也。请救邢以从简书。」齐人救邢。
夏六月，葬庄公，乱故，是以缓。
秋八月，公及齐侯盟于落姑，请复季友也。齐侯许之，使召诸陈，公次于郎以待之。「季子来归」，嘉之也。
冬，齐仲孙湫来省难。书曰「仲孙」，亦嘉之也。
仲孙归曰：「不去庆父，鲁难未已。」公曰：「若之何而去之？」对曰：「难不已，将自毙，君其待之。」公曰：「鲁可取乎？」对曰：「不可，犹秉周礼。周礼，所以本也。臣闻之，国将亡，本必先颠，而后枝叶从之。鲁不弃周礼，未可动也。君其务宁鲁难而亲之。亲有礼，因重固，间携贰，覆昏乱，霸王之器也。」
晋侯作二军，公将上军，大子申生将下军。赵夙御戎，毕万为右，以灭耿、灭霍、灭魏。还，为大子城曲沃。赐赵夙耿，赐毕万魏，以为大夫。
士蒍曰：「大子不得立矣，分之都城而位以卿，先为之极，又焉得立。不如逃之，无使罪至。为吴大伯，不亦可乎？犹有令名，与其及也。且谚曰：『心苟无瑕，何恤乎无家。』天若祚大子，其无晋乎。」
卜偃曰：「毕万之后必大。万，盈数也；魏，大名也；以是始赏，天启之矣。天子曰兆民，诸侯曰万民。今名之大，以从盈数，其必有众。」
初，毕万筮仕于晋，遇《屯》䷂之《比》䷯。辛廖占之，曰：「吉。《屯》固《比》入，吉孰大焉？其必蕃昌。《震》为土，车从马，足居之，兄长之，母覆之，众归之，六体不易，合而能固，安而能杀。公侯之卦也。公侯之子孙，必复其始。」', '', '', '元年春季，《春秋》没有记载即位，是由于动乱不能举行即位仪式。
狄人进攻邢国。管仲对齐桓公说：“戎狄好像豺狼，是不会满足的；中原各国互相亲近，是不能抛弃的。安逸等于毒药，是不能怀恋的。《诗》说：‘难道不想着回去，怕的是这个竹简上的军事文字。’竹简上的军事文字，就是同仇敌忾而忧患与共的意思，所以请按照简书而救援邢国。”于是齐国人出兵救援邢国。
夏季，六月，安葬庄公。由于发生动乱，所以推迟了，过了十一个月才安葬。
秋季，八月，闵公和齐桓公在落姑结盟，请求齐桓公帮助季友回国。齐桓公同意，派人从陈国召回季友，闵公住在郎地等候他。《春秋》记载说“季子来归”，这是赞美季友。
冬季，齐国的仲孙湫前来对祸难表示慰问，《春秋》称之为“仲孙”，也是赞美他。仲孙回国说：“不除掉庆父，鲁国的祸难没完没了。”齐桓公说：“怎么样才能除掉他？”仲孙回答说：“祸难不止，将会自取灭亡，您就等着吧！”齐桓公说：“鲁国可以取得吗？”仲孙说：“不行。他们还遵行周礼。周礼，是立国的根本。下臣听说：‘国家将要灭亡，如同大树，躯干必然先行仆倒，然后枝叶随着落下。’鲁国不抛弃周礼，是不能动它的。您应当从事于安定鲁国的祸难并且亲近它。亲近有礼仪的国家，依靠稳定坚固的国家，离间内部涣散的国家，灭亡昏暗动乱的国家，这是称霸称王的方法。”
晋献公建立两个军，自己率领上军，太子申生率领下军。赵夙为晋献公驾御战车，毕万作为车右。出兵灭掉耿国、灭掉霍国、灭掉魏国。回国来，晋献公为太子在曲沃建造城墙，把耿地赐给赵夙，把魏地赐给毕万，派他们做大夫。
士..说：“太子不能做继承者了，把都城分给他，而给他以卿的地位，先让他达到顶点，又哪里能够立为国君？与其得到罪过，不如逃走，不要让罪过到来。做一个吴太伯，不也是可以的吗？这样还可以保有好名声。而且俗话说：‘心里如果没有毛病，又何必担心没有家？’上天如果保佑您，您就不要在晋国了吧！”
卜偃说：“毕万的后代必定昌大。万，是满数；魏，是巍巍高大的名称。
开始赏赐就这样，上天已经启示了。天子统治兆民，所以称为‘兆民’，诸侯统治万民，所以称为‘万民’。现在名称的高大跟着满数，他就必然会得到群众。”
当初，毕万占卜在晋国做官的吉凶，得到《屯》卦变成《比》卦。
辛廖预测说：“吉利。《屯》坚固，《比》进入，还有比这更大的吉利吗？
所以他必定蕃衍昌盛。《震》卦变成了土，车跟随着马，两脚踏在这里，哥哥抚育他，母亲保护他，群众归附他，这六条不变，集合而能坚固，安定而有威武，这是公侯的封象。公侯的子孙，必定能回复到他开始的地位。”', NULL, '', 'indent', 1558694442, '5ce759a7d5de2b00704844ce', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642930, '左传 · 闵公 · 闵公二年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二年春王正月，齐人迁阳。夏五月乙酉，吉禘于庄公。秋八月辛丑，公薨。九月，夫人姜氏孙于邾。公子庆父出奔莒。冬，齐高子来盟。十有二月，狄入卫。郑弃其师。
【传】二年春，虢公败犬戎于渭汭。舟之侨曰：「无德而禄，殃也。殃将至矣。」遂奔晋。
夏，吉禘于庄公，速也。
初，公傅夺卜齮田，公不禁。
秋八月辛丑，共仲使卜齮贼公于武闱。成季以僖公适邾。共仲奔莒，乃入，立之。以赂求共仲于莒，莒人归之。及密，使公子鱼请，不许。哭而往，共仲曰：「奚斯之声也。」乃缢。
闵公，哀姜之娣叔姜之子也，故齐人立之。共仲通于哀姜，哀姜欲立之。闵公之死也，哀姜与知之，故孙于邾。齐人取而杀之于夷，以其尸归，僖公请而葬之。
成季之将生也，桓公使卜楚丘之父卜之。曰：「男也。其名曰友，在公之右。间于两社，为公室辅。季氏亡，则鲁不昌。」又筮之，遇《大有》之《乾》，曰：「同复于父，敬如君所。」及生，有文在其手曰「友」，遂以命之。
冬十二月，狄人伐卫。卫懿公好鹤，鹤有乘轩者。将战，国人受甲者皆曰：「使鹤，鹤实有禄位，余焉能战！」公与石祁子玦，与宁庄子矢，使守，曰：「以此赞国，择利而为之。」与夫人绣衣，曰：「听于二子。」渠孔御戎，子伯为右，黄夷前驱，孔婴齐殿。及狄人战于荧泽，卫师败绩，遂灭卫。卫侯不去其旗，是以甚败。狄人囚史华龙滑与礼孔以逐卫人。二人曰：「我，大史也，实掌其祭。不先，国不可得也。」乃先之。至则告守曰：「不可待也。」夜与国人出。狄入卫，遂从之，又败诸河。
初，惠公之即位也少，齐人使昭伯烝于宣姜，不可，强之。生齐子、戴公、文公、宋桓夫人、许穆夫人。文公为卫之多患也，先适齐。及败，宋桓公逆诸河，宵济。卫之遗民男女七百有三十人，益之以共，滕之民为五千人，立戴公以庐于曹。许穆夫人赋《载驰》。齐侯使公子无亏帅车三百乘、甲士三千人以戍曹。归公乘马，祭服五称，牛羊豕鸡狗皆三百，与门材。归夫人鱼轩，重锦三十两。
郑人恶高克，使帅师次于河上，久而弗召。师溃而归，高克奔陈。郑人为之赋《清人》。
晋侯使大子申生伐东山皋落氏。里克谏曰：「大子奉冢祀，社稷之粢盛，以朝夕视君膳者也，故曰冢子。君行则守，有守则从。从曰抚军，守曰监国，古之制也。夫帅师，专行谋，誓车旅，君与国政之所图也，非大子之事也。师在制命而已。禀命则不威，专命则不孝。故君之嗣适不可以帅师。君失其官，帅师不威，将焉用之。且臣闻皋落氏将战，君其舍之。」公曰：「寡人有子，未知其谁立焉。」不对而退。
见大子，大子曰：「吾其废乎？」对曰：「告之以临民，教之以军旅，不共是惧，何故废乎？且子惧不孝，无惧弗得立，修己而不责人，则免于难。」
大子帅师，公衣之偏衣，佩之金玦。狐突御戎，先友为右，梁余子养御罕夷，先丹木为右。羊舌大夫为尉。光友曰：「衣身之偏，握兵之要，在此行也，子其勉之。偏躬无慝，兵要远灾，亲以无灾，又何患焉！」狐突叹曰：「时，事之征也；衣，身之章也；佩，衷之旗也。故敬其事则命以始，服其身则衣之纯，用期衷则佩之度。今命以时卒，閟其事也；衣之龙服，远其躬也；佩以金玦，弃其衷也。服以远之，时以閟之，龙凉冬杀，金寒玦离，胡可恃也？虽欲勉之，狄可尽乎？」梁余子养曰：帅师者受命于庙，受脤于社，有常服矣。不获而龙，命可知也。死而不孝，不如逃之。」罕夷曰：「龙奇无常，金玦不复，虽复何为，君有心矣。」先丹木曰：「是服也。狂夫阻之。曰『尽敌而反』，敌可尽乎！虽尽敌，犹有内谗，不如违之。」狐突欲行。羊舌大夫曰：「不可。违命不孝，弃事不忠。虽知其寒，恶不可取，子其死之。」
大子将战，狐突谏曰：「不可，昔辛伯谂周桓公云：『内宠并后，外宠二政，嬖子配适，大都耦国，乱之本也。』周公弗从，故及于难。今乱本成矣，立可必乎？孝而安民，子其图之，与其危身以速罪也。」
成风闻成季之繇，乃事之，而属僖公焉，故成季立之。
僖之元年，齐桓公迁邢于夷仪。二年，封卫于楚丘。邢迁如归，卫国忘亡。
卫文公大布之衣，大帛之冠，务材训农，通商惠工，敬教劝学，授方任能。元年革车三十乘，季年乃三百乘。', '', '', '二年春季，虢公在渭水入河的地方打败犬戎。舟之侨说：“没有德行受到宠禄，这是灾祸。灾祸将要来到了。”就逃亡到晋国。
夏季，为庄公举行大祭。未免太快了。
当初，闵公的保傅夺取卜齮的田地，闵公不加禁止。秋季，八月二十四日，共仲指使卜齮在武闱杀害闵公。成季带着僖公跑到邾国。共仲逃亡到莒国，季友和僖公就回到鲁国，拥立僖公为国君。用财货到莒国求取共仲，莒国人把他送了回来。共仲到达密地，让公子鱼请求赦免。没有得到同意，公子鱼哭着回去。共仲说：“这是公子鱼的哭声啊！”于是上吊死了。
闵公是哀姜的妹妹叔姜的儿子，所以齐人立他为国君。共仲和哀姜私通，哀姜想立他为国君。闵公的被害，哀姜事先知道内情，所以逃到邾国。齐人向邾人索取哀姜，在夷地杀了她，把她的尸首带回去，僖公请求归还尸首安葬。
成季将要出生的时候，鲁桓公让掌卜官楚丘的父亲占卜。他说：“是男孩子。他名叫友，是您的右手；处于周社和亳社之间，作为公室的辅助。季氏灭亡，鲁国不能盛昌。”又占筮，得到《大有》变成《乾》，说：“尊贵如同父亲，敬重如同国君。”等到生下来，在手掌心有个“友”字，就以友命名。
冬季，十二月，狄人进攻卫国。卫懿公喜欢鹤，鹤有坐车子的。将要作战时，接受甲胄的人们都说：“让鹤去，鹤实际上享有官禄官位，我们哪里能打仗！”懿公把玉佩给了石祁子，把箭给了甯庄子，让他们防守，说：“用这个来赞助国家，选择有利的去做。”把绣衣给了夫人，说：“听他们二人的！”渠孔为卫懿公驾御战车，子伯作为车右；黄夷打冲锋，孔婴齐指挥后军。和狄人在荧泽作战，卫军大败，狄人就灭亡了卫国。卫侯不肯去掉自己的旗帜，所以惨败。狄人囚禁了史官华龙滑和礼孔以追赶卫国人。这两个人说：“我们，是太史之官，执掌祭祀。如果不先回去，你们是不能得到国都的。”于是就让他们先回去。他们到达，就告诉守卫的人说：“不能抵御了。”夜里和国都的人一起退走。狄人进入卫国国都，跟着追上去，又在黄河边上打败了卫国人。
当初，卫惠公即位的时候还很年轻，齐人让昭伯和宣姜私通，昭伯不同意，就逼迫他干。生了齐子、戴公、文公、宋桓夫人、许穆夫人。文公由于卫国祸患太多，先到了齐国。等到卫国这次大败，宋桓公在黄河边上迎接，夜里渡河。卫国的遗民男女共计七百三十人，加上共地、滕地的百姓共五千人。立戴公为国君。暂时寄居在曹邑，许穆夫人作了《载驰》这首诗。齐桓公派遣公子无亏率领战车三百辆、披甲战士三千人守卫曹邑，赠送给戴公驾车的马匹，祭服五套，牛、羊、猪、鸡、狗都是三百头，还有做门户的木材。
赠送给夫人用鱼皮装饰的车子，上等的绸缎三十匹。
郑国人讨厌高克，派他率领军队住在黄河边，很久也不召他回来，军队溃散逃回，高克逃亡到陈国。郑国人为高克作了《清人》这首诗。
晋献公派遣太子申生进攻东山的皋落氏。里克进谏说：“太子，是奉事宗庙祭祀、社稷大祭和早晚照看国君饮食的人，所以叫做冢子。国君外出就守护国家，如果有别人守护就跟随国君。跟随在外叫做抚军，守护在内叫做监国，这是古代的制度。说到带兵一事，对各种策略作出决断，对军队发号施令，这是国君和正卿所应该策划的，不是太子的事情。率领大军在于控制命令，太子领兵，如果遇事都要请示就失去威严，擅自发令而不请示就是不孝，所以国君的大儿子不能带领军队。国君失去了任命职官的准则，太子统率军队也没有威严，何必如此呢？而且下臣听说皋落氏准备出兵迎战，君王还是不要太子去为好。”晋献公说：“我有好几个儿子，还不知道立谁为嗣君呢！”里克不回答，退了下去。里克进见太子。太子说：“我恐怕要被废了吧！”里克回答说：“命令您在曲沃治理百姓，教导您熟悉军事，害怕的是不能完成任务，为什么会废立呢？而且做儿子的应该害怕不孝，不应该害怕不能立为嗣君。修养自己而不要去责备别人，就可以免于祸难。”
太子申生带领军队，晋献公让他穿左右两色的衣服，佩带有缺口的青铜环形佩器。狐突驾御战车，先友作为车右。梁馀子养为罕夷驾御战车，先丹木作为车右。羊舌大夫作为军尉。先友说：“穿着国君衣服的一半，掌握着军事的机要，成败全在这一回了，您要自己勉励啊！分出一半衣服没有恶意，兵权在手可以远离灾祸，与国君亲近又远离灾祸，又担心什么！”狐突叹息说：“时令，是事情的象征，衣服，是身分的标识，佩饰，是心志的旗帜。
所以如果看重这件事，就应该在春、夏季发布命令；赐予衣服，就不要用杂色；使人衷心为自己所用，就要让他佩带合于礼度的装饰品。如今在年终发布命令，那是要让事情不能顺利进行；赐给他穿杂色衣服，那是要使他疏远；让他佩带缺口青铜环佩器，那是表示出丢弃太子的内心。现在是用衣服疏远他，用时令使他不能顺利进行；杂色，意味凉薄；冬天，意味肃杀；金，意味寒冷；玦，意味决绝，这怎么可以依靠呢？虽然要勉力而为，狄人难道可以消灭得一人不剩吗？”梁馀子养说：“领兵的人，在太庙里接受命令，在祭祀土神的地方接受祭肉，还应该有一定的服饰。现在得不到规定的服饰而得到杂色衣服，命令不怀好意可想而知。死了以后还要落个不孝的罪名，不如逃了吧！”罕夷说：“杂色的奇装异服不合规定，青铜环形佩器表示不再回来。这样，即使是回来还有什么用？国君已经有别的心思了。”先丹木说：“这样的衣服，狂人也不会去穿的。国君说：‘将敌人消灭光了再回来’，敌人难道可以消灭得一干二净吗？即使把敌人消灭干净了，还有内部谗言，不如离开这里。”狐突要走，羊舌大夫说：“不行。违背命令是不孝，抛弃责任是不忠。虽然已经感到了国君的心里冷酷，不孝不忠这样的邪恶是不可取的。您还是为此而死吧！”
太子准备作战，狐突劝阻说：“不行。从前辛伯劝阻周桓公说：‘妾媵并同于王后，宠臣相等于正卿，庶子和嫡子同等，大城和国都相同，这就是祸乱的根本。’周桓公不听，所以遭到祸难。现在祸乱的根本已经形成，您还能肯定会立您为嗣君吗？您就考虑一下吧！与其危害自身而加快罪过的到来，何如尽孝道而安定百姓！”
成风听到成季出生时占卜的卦辞，就和他结交，并且把僖公嘱托给他，所以成季立僖公为国君。
僖公元年，齐桓公把邢国迁到夷仪。二年，把卫国封在楚丘。邢国迁居，好像回到原来的国土；卫国重建，却忘记了亡国之痛。
卫文公穿着粗布衣服，戴着粗帛帽子，努力生产，教导农耕，便利商贩，加惠各种手工业，重视教化，奖励求学，向臣下传授为官之道，任用有能力的人。头一年，战车只有三十辆，到末年，就有了三百辆。', NULL, '', 'indent', 1558694489, '5ce759d6c8959c0069ac4de6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642931, '左传 · 僖公 · 僖公元年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】元年春王正月。齐师、宋师、曹伯次于聂北，救邢。夏六月，邢迁于夷仪。齐师、宋师、曹师城邢。秋七月戊辰，夫人姜氏薨于夷，齐人以归。楚人伐郑。八月，公会齐侯、宋公、郑伯、曹伯、邾人于柽。九月，公败邾师于偃。冬十月壬午，公子友帅师败莒于郦。获莒拏。十有二月丁巳，夫人氏之丧至自齐。
【传】元年春，不称即位，公出故也。公出复入，不书，讳之也。讳国恶，礼也。
诸侯救邢。邢人溃，出奔师。师遂逐狄人，具邢器用而迁之，师无私焉。
夏，邢迁夷仪，诸侯城之，救患也。凡侯伯救患分灾讨罪，礼也。
秋，楚人伐郑，郑即齐故也。盟于荦，谋救郑也。
九月，公败邾师于偃，虚丘之戍将归者也。
冬，莒人来求赂。公子友败诸郦，获莒子之弟拏。非卿也，嘉获之也。公赐季友汶阳之田及费。
夫人氏之丧至自齐。君子以齐人杀哀姜也为已甚矣，女子，从人者也。
', '', '', '元年春季，《春秋》没有记载即位，这是由于僖公出奔在外的缘故。僖公出奔而又回到国内，《春秋》不加记载，这是由于避讳。不记国家的坏事，这是合于礼的。
齐桓公、宋桓公、曹昭公率领军队驻扎在聂北，诸侯联军救援邢国。邢军已经溃散，逃到诸侯的军队里。军队便赶走了狄人，装载了邢国的器物财货而让邢军搬走，各国军队没有私自占有。
夏季，邢国把都城迁到夷仪，诸侯替它筑城，为的是救援患难。凡是诸侯领袖，救援患难、分担灾害、讨伐罪人，都是合于礼的。
秋季，楚国人进攻郑国，这是由于郑国亲近齐国的缘故。鲁僖公和齐桓公、宋桓公、郑文公、邾子在荦地结盟，策划救援郑国。九月，僖公在偃地打败了邾国的军队，这支队伍是戍守在虚丘将要回国的军队。
冬季，莒国人来求取财货，公子友在郦地打败了他们，俘虏了莒子的弟弟挐。挐并不是卿，《春秋》这样记载，是为了称赞公子友俘获的功劳。僖公把汶阳的田地和费地赐给季友。
鲁庄公夫人姜氏的尸体从齐国运来。君子认为齐国人杀死哀姜是太过分了，妇女，本来应该听从丈夫的。', NULL, '', 'indent', 1558694579, '5ce75a2f43e78c0067e346c9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642932, '左传 · 僖公 · 僖公二年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二年春王正月，城楚丘。夏五月辛巳，葬我小君哀姜。虞师、晋师灭下阳。秋九月，齐侯、宋公、江人、黄人盟于贯。冬十月，不雨。楚人侵郑。
【传】二年春，诸侯城楚丘而封卫焉。不书所会，后也。
晋荀息请以屈产之乘与垂棘之璧，假道于虞以伐虢。公曰：「是吾宝也。」对曰：「若得道于虞，犹外府也。」公曰：「宫之奇存焉。」对曰：「宫之奇之为人也，懦而不能强谏，且少长于君，君昵之，虽谏，将不听。」乃使荀息假道于虞，曰：「冀为不道，入自颠軨，伐鄍三门。冀之既病。则亦唯君故。今虢为不道，保于逆旅，以侵敝邑之南鄙。敢请假道以请罪于虢。」虞公许之，且请先伐虢。宫之奇谏，不听，遂起师。夏，晋里克、荀息帅师会虞师伐虢，灭下阳。先书虞，贿故也。
秋，盟于贯，服江、黄也。
齐寺人貂始漏师于多鱼。
虢公败戎于桑田。晋卜偃曰：「虢必亡矣。亡下阳不惧，而又有功，是天夺之鉴，而益其疾也。必易晋而不抚其民矣，不可以五稔。」
冬，楚人伐郑，斗章囚郑聃伯。', '', '', '二年春季，诸侯在楚丘筑城，而将由周天子封给卫国。《春秋》没有记载诸侯会见，是由于僖公到会晚了。
晋国的荀息请求用屈地出产的马和垂棘出产的璧玉向虞国借路来进攻虢国。晋献公说：“这是我的宝物啊！”荀息回答说：“如果向虞国借到了路，东西放在虞国，就像放在宫外的库房里一样。”晋献公说：“宫之奇还在那里。”荀息回答说：“宫之奇的为人，懦弱而不能坚决进谏，而且从小就和虞君在宫里一起长大，虞君对他亲昵，虽然进谏，虞君不会听从的。”于是晋献公就派荀息到虞国去借路，说：“冀国无道，从颠軨入侵，围攻虞国鄍邑的三面城门。敝国伐冀而使冀国受到损失，也是为了君王的缘故。现在虢国无道，在客舍里筑起堡垒，来攻打敝国的南部边境。谨大胆地请求贵国借路，以便到虢国去问罪。”虞公答应了，而且自己请求先去进攻虢国。宫之奇劝阻，虞公不听，就带兵进攻虢国。夏季，晋国的里克、荀息领兵会合虞军，进攻虢国，灭亡了下阳。《春秋》把虞国写在前面，因为虞国接受了贿赂。
秋季，齐桓公、宋桓公、江、黄两地的头目在贯地结盟，这是为了江、黄两国归服于齐。
齐国的寺人貂开始在多鱼地方泄漏了军事机密。
虢公在桑田打败了戎人。晋国的卜偃说：“虢国必将被灭亡。被灭掉了下阳不知戒惧，反而又建立了武功，这是上天夺去了虢国的镜子，而加重它的作恶啊！虢国必定轻视晋国又不爱抚百姓，过不了五年，必然灭亡。”
冬季，楚国人进攻郑国，鬬章囚禁了郑国的聃伯。', NULL, '', 'indent', 1558694617, '5ce75a5630863b0068d0bb83', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642933, '左传 · 僖公 · 僖公三年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三年春王正月，不雨。夏四月不雨。徐人取舒。六月雨。秋，齐侯、宋公、江人、黄人会于阳谷。冬，公子友如齐位盟。楚人伐郑。
【传】三年春，不雨。夏六月，雨。自十月不雨至于五月，不曰旱，不为灾也。
秋，会于阳谷，谋伐楚也。
齐侯为阳谷之会，来寻盟。冬，公子友如齐位盟。
楚人伐郑，郑伯欲成。孔叔不可，曰：「齐方勤我，弃德不祥。」
齐侯与蔡姬乘舟于囿，荡公。公惧，变色。禁之，不可。公怒，归之，未绝之也。蔡人嫁之。', '', '', '三年春季，不下雨，到六月才下雨。从去年十月不下雨一直到五月，《春秋》没有记载说旱，因为没有造成灾害。
秋季，齐桓公、宋桓公、江人、黄人在阳穀会见，这是由于预谋进攻楚国。
齐桓公为了阳穀的盟会而来重温旧好。冬季，公子友到齐国参加盟会。
楚军进攻郑国，郑文公想求和。孔叔不同意，说：“齐国正为我国忙着，丢弃他们的恩德而向楚国讲和，不会有好结果。”
齐桓公和蔡姬在园子里坐船游览，蔡姬故意摇动游船，使齐桓公摇来晃去。齐桓公害怕，脸色都变了，叫她别摇，蔡姬不听。齐桓公很生气，把她送回蔡国，但并不是断绝婚姻关系。蔡国人却把蔡姬改嫁了。


', NULL, '', 'indent', 1558694660, '5ce75a82a673f50068e4de52', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642936, '左传 · 僖公 · 僖公六年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】六年春王正月。夏，公会齐侯、宋公、陈侯、卫侯、曹伯伐郑，围新城。秋，楚人围许，诸侯遂救许。冬，公至自伐郑。
【传】六年春，晋侯使贾华伐屈。夷吾不能守，盟而行。将奔狄郤芮曰：「后出同走，罪也。不如之梁。梁近秦而幸焉。」乃之梁。
夏，诸侯伐郑，以其逃首止之盟故也。围新密，郑所以不时城也。
秋，楚子围许以救郑，诸侯救许，乃还。
冬，蔡穆侯将许僖公以见楚子于武城。许男面缚，衔璧，大夫衰絰，士舆榇。楚子问诸逢伯，对曰：「昔武王克殷，微子启如是。武王亲释其缚，受其璧而祓之。焚其榇，礼而命之，使复其所。」楚子从之。', '', '', '六年春季，晋献公派遣贾华率军进攻屈地。夷吾守不住，和屈人订立盟约然后出走。准备逃亡到狄。郤芮说：“在重耳之后离开而且同样逃到狄，这就表明你有同谋的罪过。不如去梁国。梁国接近秦国而又得到它的信任。”于是夷吾就到了梁国。
夏季，诸侯进攻郑国，因为郑国逃避首止那次结盟的缘故。诸侯军包围了新密，这就是郑国在不宜动土筑城的时令而筑城的缘故。
秋季，楚成王出兵包围许国来救援郑国。诸侯出兵救援许国，楚军于是回国。
冬季，蔡穆侯带领许僖公到武城去见楚成王。许男两手反绑，嘴里衔着璧玉，大夫穿着孝服，士抬着棺材。楚成王询问逢伯。逢伯回答说：“从前武王打胜殷朝，微子启就是这样做的。武王亲自解开他的捆绑，接受他的璧玉而举行扫除凶恶之礼，烧掉他的棺材，给以礼遇而命令他，让他回到原地原位去。”楚成王接受了逢伯的建议。', NULL, '', 'indent', 1558694780, '5ce75afac8959c0069ac5b65', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642937, '左传 · 僖公 · 僖公七年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】七年春，齐人伐郑。夏，小邾子来朝。郑杀其大夫申侯。秋七月，公会齐侯、宋公、陈世子款、郑世子华盟于宁母。曹伯班卒。公子友如齐。冬葬曹昭公。
【传】七年春，齐人伐郑。孔叔言于郑伯曰：「谚有之曰：『心则不竞，何惮于病。』既不能强，又不能弱，所以毙也。国危矣，请下齐以救国。」公曰：「吾知其所由来矣。姑少待我。」对曰：「朝不及夕，何以待君？」
夏，郑杀申侯以说于齐，且用陈辕涛涂之谮也。
初，申侯，申出也，有宠于楚文王。文王将死，与之璧，使行，曰，「唯我知女，女专利而不厌，予取予求，不女疵瑕也。后之人将求多于女，女必不免。我死，女必速行。无适小国，将不女容焉。」既葬，出奔郑，又有宠于厉公。子文闻其死也，曰：「古人有言曰『知臣莫若君。』弗可改也已。」
秋，盟于宁母，谋郑故也。
管仲言于齐侯曰：「臣闻之，招携以礼，怀远以德，德礼不易，无人不怀。」齐侯修礼于诸侯，诸侯官受方物。
郑伯使大子华听命于会，言于齐侯曰：「泄氏、孔氏、子人氏三族，实违君命。若君去之以为成。我以郑为内臣，君亦无所不利焉。」齐侯将许之。管仲曰：「君以礼与信属诸侯，而以奸终之，无乃不可乎？子父不奸之谓礼，守命共时之谓信。违此二者，奸莫大焉。」公曰：「诸侯有讨于郑，未捷。今苟有衅。从之，不亦可乎？」对曰：「君若绥之以德，加之以训辞，而帅诸侯以讨郑，郑将覆亡之不暇，岂敢不惧？若总其罪人以临之，郑有辞矣，何惧？且夫合诸侯以崇德也，会而列奸，何以示后嗣？夫诸侯之会，其德刑礼义，无国不记。记奸之位，君盟替矣。作而不记，非盛德也。君其勿许，郑必受盟。夫子华既为大子而求介于大国，以弱其国，亦必不免。郑有叔詹、堵叔、师叔三良为政，未可间也。」齐侯辞焉。子华由是得罪于郑。
冬，郑伯请盟于齐。
闰月，惠王崩。襄王恶大叔带之难，惧不立，不发丧而告难于齐。', '', '', '七年春季，齐国人进攻郑国。孔叔对郑文公说：“俗语有这样的话：‘心志假若不坚强，怎么能又怕屈辱？’既然不能强硬，又不能软弱，因此只有死路一条。国家危险了，请您向齐国屈服以挽救国家。”郑文公说：“我知道他们是为什么来的了，姑且稍稍等我一下。”孔叔回答说：“情况危急，早晨到不了晚上，怎么等待君王呢？”
夏季，郑文公杀死申侯以讨好齐国，同时也是由于陈国辕涛涂的诬陷。当初，因为申侯是申氏所生，受到楚文王的宠信。文王将要死的时候，把璧玉给他，让他走，说：“只有我了解你，你垄断财货而永不满足，从我这里取，从我这里求，我不加罪于你。后来的人将会向你索取大量财货，你必然不免于罪。我死，你一定要赶快走，不要到小国去，他们不会容纳你的。”安葬楚文王后，申侯逃到郑国，又受到厉公的宠信。子文听到他的死讯，说：“古人有这样的话说：‘了解臣子没有像国君那样清楚的。’这句话是不能改变的啊！”
秋季，鲁僖公和齐桓公、宋桓公、陈国的世子款、郑国的世子华在宁母结盟，策划进攻郑国。
管仲对齐桓公说：“臣听说：招抚有二心的国家，用礼；怀念疏远的国家，用德。凡事不违背德和礼，没有人不归附的。”齐桓公就以礼对待诸侯，诸侯的官员接受了齐国赏的土特产。
郑文公派遣太子华接受会议的命令，对齐桓公说：“泄氏、孔氏、子人氏三族，违背您的命令。您如果除掉他们而和敝国讲和，我国作为您的内臣，这对您也没有什么不利。”齐桓公准备答应他。管仲说：“君王用礼和信会合诸侯，而用邪恶来结束，未免不行吧。儿子和父亲不相违背叫做礼，见机行事完成君命叫做信。违背这两点，没有比这再大的邪恶了。”齐桓公说：“诸侯进攻郑国，没有得胜；现在幸而有机可乘，利用这点，不也行吗？”管仲回答说：“君王如果用德来安抚，加上教训，他们不接受，然后率领诸侯讨伐郑国；郑国挽救危亡还来不及，哪敢不害怕？如果领着他的罪人以兵进攻郑国，郑国就有理了，还害怕什么？而且会合诸侯，这是为了尊崇德行。会合而让奸邪之人列于国君，怎么能向后代交代？诸侯的会见，他们的德行、刑罚、礼仪、道义，没有一个国家不加以记载。如果记载了让邪恶的人居于君位，君王的盟约就要废弃了。事情做了而不能见于记载，这就不是崇高的道德。君王还是同意为好！郑国一定会接受盟约的。子华既然做了太子，而要求凭借大国来削弱他的国家，也一定不能免于祸患。郑国有叔詹、堵叔、师叔三个贤明的人执政，还不能去钻它的空子。”齐桓公于是向子华辞谢。子华因此得罪了郑国。
冬季，郑文公派遣使者到齐国请求订立盟约。
闰十二月，周惠王去世。襄王担心大叔王子带作乱，又害怕不能立为国君，所以不发布丧事的消息，却把将要发生内乱的事向齐国报告。', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf702e6a6b501f9681c7", "shortContent": "此赋作于杨慎遭贬谪戍居云南永昌卫期间。杨慎虽多才多艺，但命运多舛。他诗文兼长，又善散曲，个性狂放，喜用诙谐幽默笔法结构短章。其赋在题材上虽多咏物，但寓意深刻，手法老辣，足显作者之个性。\n关于此赋，杨慎曾在《后蚊赋》序中明言：“余暇之日，戏为《蚊赋》。或谓规规兰陵（按：荀子曾两任兰陵令）之体，未尽蚊之典也。”可见是一篇模仿追步荀卿赋之作。全赋就像一个谜语，通篇言蚊而不出现“蚊”字，直到文末才点出谜底...", "authors": ["孙京荣"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f7ec6e67846a9226d74", "shortContent": "在关于野生动物的传说中，狐狸与人的感情纠葛可能最多。从华夏先祖大禹的“狐鸣娶妻”，到陈胜、吴广的“篝火狐鸣”，再到汉魏六朝层出不穷的狐魅逸事，狐狸的行踪就像“鬼董狐”笔下的正史一般代代相传。到唐代竟然形成“无狐魅不成村”的俗谚，可见流传之深广。但在明清以前，狐狸多以蛊惑人的角色出现，唯本篇中的伯裘，则是一只既正直又富于智慧的“义狐”。它帮助陈斐渡过一道道难关，家事、政事无不通晓，不仅保障了陈斐的安...", "authors": ["鄢化志"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8534a8757d5a0fa474", "shortContent": "《任氏传》写的是美丽聪慧的狐女任氏与贫苦无依的青年郑六相爱，一年后任氏随郑六赴任途中为猎犬所害的故事。作者有意识地借狐女来写人，通过曲折的情节，生动的形象，把狐写成有真情实感的现实生活中的美丽动人的女性。后世的《聊斋志异》等显然是受其影响的。\n《任氏传》的成功之处很多，这里只谈两点：\n一、作者以满腔的热情，通过生花妙笔，塑造了一个机智、善良、性格鲜明的女性形象。作品的开头就说明：“任氏，女妖也。”...", "authors": ["陈谦豫"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558694821, '5ce75b22a673f50068e4e46d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642938, '左传 · 僖公 · 僖公八年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】八年春王正月，公会王人、齐侯、宋公、卫侯、许男、曹伯、陈世子款盟于洮。郑伯乞盟。夏，狄伐晋。秋七月，禘于大庙，用致夫人。冬十有二月丁未，天王崩。
【传】八年春，盟于洮，谋王室也。郑伯乞盟，请服也。襄王定位而后发丧。
晋里克帅师，梁由靡御。虢射为右，以败狄于采桑。梁由靡曰：「狄无耻，从之必大克。」里克曰：「拒之而已，无速众狄。」虢射曰：「期年，狄必至，示之弱矣。」
夏，狄伐晋，报采桑之役也。复期月。
秋，禘而致哀姜焉，非礼也。凡夫人不薨于寝，不殡于庙，不赴于同，不祔于姑，则弗致也。
冬，王人来告丧，难故也，是以缓。
宋公疾，大子兹父固请曰：「目夷长，且仁，君其立之。」公命子鱼，子鱼辞，曰：「能以国让，仁孰大焉？臣不及也，且又不顺。」遂走而退。', '', '', '八年春季，鲁僖公和周王室的使者、齐桓公、宋桓公、卫文公、许僖公、曹共公、郑世子款在洮地会盟，商谈安定王室。郑文公请求参加盟会，表示顺服。襄王的君位安定后，才举行丧礼。
晋国的里克率领军队，梁由靡驾御战车，虢射作为车右，在采桑打败了狄人。梁由靡说：“狄人不以逃走为耻，如果追击，必然大胜。”里克说：“吓唬一下就行了，不要因为追击招来更多的狄人。”虢射说：“只要一年，狄人必然再来，不去追击，就是向他们示弱了。”
夏季，狄人进攻晋国，这是为了报复采桑这一战役，应验了，虢射所说一年的预言。
秋季，举行宗庙合祭，把哀姜的神主放在太庙里，这是不合于礼的。凡是夫人，如果不死在正房里，不在祖庙里停棺，不向同盟国家发讣告，不陪祀祖姑，就不能把神主放进太庙里去。
冬季，周王室的使者来鲁国讣告丧事，由于发生祸难，所以讣告迟了。
宋桓公得了重病，太子兹父再三请求说：“目夷年长而且仁爱，君王应该立他为国君。”宋桓公就下令要目夷继位。目夷推谢说：“能够把国家辞让给别人，还有比这更大的仁爱吗？下臣不如他！而且又不符合立君的顺序。”于是就退了出去。', NULL, '', 'indent', 1558694858, '5ce75b4830863b0068d0cf09', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642939, '左传 · 僖公 · 僖公九年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】九年春王三月丁丑，宋公御说卒。夏，公会宰周公、齐侯、宋子、卫侯、郑伯、许男、曹伯于葵丘。秋七月乙酉，伯姬卒。九月戊辰，诸侯盟于葵丘。甲子，晋侯佹诸卒。冬，晋里奚克杀其君之子奚齐。
【传】九年春，宋桓公卒，未葬而襄公会诸侯，故曰子。凡在丧，王曰小童，公侯曰子。
夏，会于葵丘，寻盟，且修好，礼也。
王使宰孔赐齐侯胙，曰：「天子有事于文武，使孔赐伯舅胙。」齐侯将下拜。孔曰：「且有后命。天子使孔曰：『以伯舅耋老，加劳，赐一级，无下拜』」。对曰：「天威不违颜咫尺，小白余敢贪天子之命无下拜？恐陨越于下，以遗天子羞。敢不下拜？」下，拜；登，受。
秋，齐侯盟诸侯于葵丘，曰：「凡我同盟之人，既盟之后，言归于好。」宰孔先归，遇晋侯曰：「可无会也。齐侯不务德而勤远略，故北伐山戎，南伐楚，西为此会也。东略之不知，西则否矣。其在乱乎。君务靖乱，无勤于行。」晋侯乃还。
九月，晋献公卒，里克、ぶ郑欲纳文公，故以三公子之徒作乱。
初，献公使荀息傅奚齐，公疾，召之，曰：「以是藐诸孤，辱在大夫，其若之何？」稽首而对曰：「臣竭其股肱之力，加之以忠贞。其济，君之灵也；不济，则以死继之。」公曰：「何谓忠贞？」对曰：「公家之利，知无不为，忠也。送往事居，耦俱无猜。贞也。」及里克将杀奚齐，先告荀息曰：「三怨将作，秦、晋辅之，子将何如？」荀息曰：「将死之。」里克曰：「无益也。」荀叔曰：「吾与先君言矣，不可以贰。能欲复言而爱身乎？虽无益也，将焉辟之？且人之欲善，谁不如我？我欲无贰而能谓人已乎？」
冬十月，里克杀奚齐于次。书曰：「杀其君之子。」未葬也。荀息将死之，人曰：「不如立卓子而辅之。」荀息立公子卓以葬。十一月，里克杀公子卓于朝，荀息死之。君子曰：「诗所谓『白圭之玷，尚可磨也；斯言之玷，不可为也，』荀息有焉。」
齐侯以诸侯之师伐晋，及高梁而还，讨晋乱也。令不及鲁，故不书。
晋郤芮使夷吾重赂秦以求入，曰：「人实有国，我何爱焉。入而能民，土于何有。」从之。齐隰朋帅师会秦师，纳晋惠公。秦伯谓郤芮曰：「公子谁恃？」对曰：「臣闻亡人无党，有党必有仇。夷吾弱不好弄，能斗不过，长亦不改，不识其他。」公谓公孙枝曰：「夷吾其定乎？对曰：「臣闻之，唯则定国。《诗》曰：『不识不知，顺帝之则。』文王之谓也。又曰：『不僭不贼，鲜不为则。』无好无恶，不忌不克之谓也。今其言多忌克，难哉！」公曰：「忌则多怨，又焉能克？是吾利也。」
宋襄公即位，以公子目夷为仁，使为左师以听政，于是宋治。故鱼氏世为左师。', '', '', '', NULL, '', 'indent', 1558694891, '5ce75b62ba39c800684da1f8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642940, '左传 · 僖公 · 僖公十年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十年春王正月，公如齐。狄灭温，温子奔卫。晋里克弑其君卓及其大夫荀息。夏，齐侯、许男伐北戎。晋杀其大夫里克。秋七月。冬，大雨雪。
【传】十年春，狄灭温，苏子无信也。苏子叛王即狄，又不能于狄，狄人伐之，王不救，故灭。苏子奔卫。
夏四月，周公忌父、王子党会齐隰朋立晋侯。晋侯杀里克以说。将杀里克，公使谓之曰：「微子则不及此。虽然，子弑二君与一大夫，为子君者不亦难乎？」对曰：「不有废也，君何以兴？欲加之罪，其无辞乎？臣闻命矣。」伏剑而死。于是丕郑聘于秦，且谢缓赂，故不及。
晋侯改葬共大子。
秋，狐突适下国，遇大子，大子使登，仆，而告之曰：「夷吾无礼，余得请于帝矣。将以晋畀秦，秦将祀余。」对曰：「臣闻之，神不歆非类，民不祀非族。君祀无乃殄乎？且民何罪？失刑乏祀，君其图之。」君曰：「诺。吾将复请。七日新城西偏，将有巫者而见我焉。」许之，遂不见。及期而往，告之曰：「帝许我罚有罪矣，敝于韩。」
丕郑之如秦也，言于秦伯曰：「吕甥、郤称、冀芮实为不从，若重问以召之，臣出晋君，君纳重耳，蔑不济矣。」
冬，秦伯使冷至报问，且召三子。郤芮曰：「币重而言甘，诱我也。」遂杀丕郑、祁举及七舆大夫：左行共华、右行贾华、叔坚、骓颛、累虎、特宫、山祁，皆里、丕之党也。丕豹奔秦，言于秦伯曰：「晋侯背大主而忌小怨，民弗与也，伐之必出。」公曰：「失众，焉能杀。违祸，谁能出君。」', '', '', '十年春季，狄人灭亡温国，这是由于苏子不讲信义。苏子背叛周襄王而投奔狄人，又和狄人处不来，狄人进攻他，周襄王不去救援，因此灭亡。苏子逃亡到卫国。
夏季，四月，周公忌父、王子党会合齐国的隰朋立了晋惠公。晋惠公杀死里克表示讨好。将要杀掉里克以前，晋惠公派人对他说：“如果没有您，我就做不了晋君。尽管如此，您杀了两个国君一个大夫，做您国君的人，不也太难了吗？”里克回答说：“没有奚齐、卓子的被废，君王怎么能兴起？要给人加上罪名，还怕没有话说吗？下臣知道国君的意思了。”说完，用剑自杀而死。当时邳郑正在秦国聘问，也是为了推迟割让国土而去致歉，所以没有碰上这场灾祸。
晋惠公改葬恭太子。
秋季，狐突到陪都曲沃去，遇到太子申生。太子让他登车作为驾车的人，告诉他说：“公子夷吾无礼，我已经请求上帝并且得到同意，准备把晋国给予秦国，秦国将会祭祀我。”狐突回答说：“臣听说，神明不享受别的族的祭品，百姓也不祭祀别的族，您的祭祀恐怕会断绝了吧？而且百姓有什么罪？处罚不当而又祭祀断绝，请您考虑一下！”太子申生说：“好，我打算重新请求。过七天，新城西边将要有一个巫人表达我的意见。”狐突同意去见巫人，申生就一下子不见了。到时候前去，巫人告诉他说：“天帝允许我惩罚有罪的人，他将在韩地大败。”
邳郑去秦国的时候，对秦伯说：“吕甥、郤称、冀芮是不同意给秦国土地的。如果用重礼对他们表示问候而后召请他们，下臣赶走晋国国君，国王让重耳回国即位，这就没有不成功的。”
冬季，秦穆公派遣泠至到晋国回聘，并且召请吕甥、郤称、冀芮三人。郤芮说：“财礼重而说话好听，这是在引诱我们。”就杀了邳郑、祁举和七个舆大夫：左行共华、右行贾华、叔坚、骓歂、纍虎、特宫、山祁，都是里克邳郑的党羽。
邳豹逃亡到秦国，对秦穆公说：“晋侯背叛大主而忌恨小怨，百姓不拥护他。如果进攻，百姓一定赶走他。”秦穆公说：“如果夷吾失去群众，哪里还能杀掉大臣？百姓都要逃难，谁能赶走国君？”
', NULL, '', 'indent', 1558694928, '5ce75b8d7b968a00763474f7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643417, '论书·上篇', NULL, 23, 2398, 5, 0, '黄庭坚', NULL, 10086, '57b9594b8ac2470062e29b7d', '宋', 'wen', '文', '', '', '《兰亭》虽真行书之宗，然不必一笔一画为准，譬如周公、孔子不能无小过，过而不害其聪明睿圣，所以为圣人。不善学者，即圣人之过处而学之，故蔽于一曲。今世学《兰亭》者，多此也。鲁之闭门者曰：“吾将以吾之不可，学柳下惠之可。”可以学书矣。
王氏书法，以为如锥画沙，如印印泥，盖言锋藏笔中，意在笔前耳。承学之人更用《兰亭》“永”字以开字中眼目，能使学家多拘忌，成一种俗气。要之右军二言，群言之长也。
东坡先生云：“大字难于结密而无间，小字难于宽绰而有余。”如《东方朔画像赞》《乐毅论》《兰亭禊事诗叙》。先秦古器，科斗文字，结密而无间，如焦山崩崖《瘗鹤铭》、永州摩崖《中兴颂》、《李斯峄山刻》秦始皇及二世皇帝诏。近世兼二美，如杨少师之正书行草，徐常侍之小篆。此虽难为俗学者言，要归毕竟如此。如人眩时，五色无主，及其神澄意定，青黄皂白，亦自粲然。学书时时临摹，可得形似。大要多取古书细看，令入神，乃到妙处。唯用心不杂，乃是入神要路。
学书端正，则窘于法度；侧笔取妍，往往工左而病右。古人作《兰亭序》《孔子庙堂碑》，皆作一淡墨本，盖见古人用笔，回腕余势。若深墨本，但得笔中意耳。今人但见深墨本收书锋芒，故以旧笔临仿，不知前辈书初亦有锋锷，此不传之妙也。
心能转腕，手能转笔，书字便如人意。古人工书无他异，但能用笔耳。
草书妙处，须学者自得，然学久乃当知之。墨池笔冢，非传者妄也。
凡书要拙多于巧。近世少年作字，如新妇子妆梳，百种点缀，终无烈妇态也。
学书须要胸中有道义，又广之以圣哲之学，书乃可贵。若其灵府无程，政使笔墨不减元常、逸少，只是俗人耳。余尝言，士大夫处世可以百为，唯不可俗，俗便不可医也。
字中有笔，如禅家句中有眼，直须具此眼者，乃能知之。凡学书，欲先学用笔。用笔之法，欲双钩回腕，掌虚指实，以无名指倚笔，则有力。古人学书不尽临摹，张古人书于壁间，观之入神，则下笔时随人意。学字既成，且养于心中无俗气，然后可以作，示人为楷式。凡作字须熟观魏、晋人书，会之于心，自得古人笔法也。欲学草书，须精真书，知下笔向背，则识草书法，不难工矣。
肥字须要有骨，瘦字须要有肉。古人学书，学其二处，今人学书，肥瘦皆病，又常偏得其人丑恶处，如今人作颜体，乃其可慨然者。
楷法欲如快马入阵，草法欲左规右矩，此古人妙处也。书字虽工拙在人，要须年高手硬，心意闲澹，乃入微耳。', '《论书》是从《山谷文集》摘录的关于书法理论的片段文章。黄庭坚的书法思想与苏轼主张差不多。他主张学书不要模仿古人，要表现人的性情等。“随人作计终后人，自成一家始逼真”，即是他的艺术观点。他讲求书法创作上要进行禅宗功夫的修炼，尤其是对草书的创作，要潜心冥会，先除去俗气，然后上逼魏晋人书法所具有的逸气，达到超俗绝尘的境地。', '周公：西周文王之子，武王之弟，成王之叔。姓姬名旦，又称周公旦。辅武王灭商，武王崩，成王幼，其摄政，史称“周公辅成王”。睿圣：圣明，明智。
蔽于一曲：蒙蔽于片面，受限于一隅。或说因一叶而障目。
鲁之闭门者：《诗·小雅·巷伯》传云，鲁人有男子独处于室，邻之嫠妇又独处于室，暴风雨至而室处，妇人趋而托之，男子闭户而不纳。柳下惠：即展禽，春秋时鲁国人。居柳下，谥惠。相传有一次他夜宿郭门，见一女子受冻，便用衣服裹着她，抱着坐了一夜，却未生淫乱之心。这里借鲁之男子“闭门不纳”和柳下惠“坐怀不乱”的故事，说明尽管表现形式不同，但其精神实质是一样的。学习书法当师古人之意，而莫拘于形迹。
以开字中眼目：指将“永”字的八种笔画，作为汉字构成的基本部件，以此作为汉字书写的规范。
大结密而无间：结构紧密而不散疏。
宽绰而有余：结体疏朗而宽松。
《东方朔画像赞》：小楷法帖，为王羲之所书。
《乐毅论》：王羲之所书小楷法帖。
《兰亭禊事诗叙》：即被誉为天下第一行书的《兰亭序》。
《瘗鹤铭》：著名的摩崖石刻，字势雄强秀逸，是隶书向楷书转变时期的重要刻石。它是一方悼念仙鹤的摩崖石刻。
《中兴颂》：即《大唐中兴颂》，唐刻石，元结撰文，颜真卿书，刻于湖南祁阳浯溪崖壁上。
《李斯峄山刻》：即《峄山碑》，李斯书，字形较长方，笔画均匀，为小篆法书。
杨少师：即杨凝式。五代书法家，字景度，号虚白，华阴（今属陕西）人。历仕梁、唐、晋、汉、周五朝，官至太子太保，人称杨少师。
徐常侍：即徐铉（916年—991年），五代宋初文字学家。扬州广陵（今江苏扬州）人。
窘于法度：受制于法度，受技法的约束。
《孔子庙堂碑》：唐武德九年（629年）刻。虞世南撰并书，为初唐碑刻中杰出作品。
墨池笔冢：笔成冢：宋朱长文《续书断》云：“释怀素字藏真，长沙人也，自云得草书三昧。始其临学勤苦，故笔颓萎，作笔冢以瘗文。”墨成池：晋卫恒《四体书势》云：“弘农张伯英者，因而转精其巧，凡家之衣帛，必先书而后练之。临池学书，池水尽墨。”张芝：字伯英，东汉时敦煌人，好书，善章草。索靖：西晋书法家。字动安，敦煌人，张芝的姐孙。
元常：即钟繇。字元常，三国时魏书法家，颍川长社（今河南长葛）人。逸少：即王羲之。东晋书法家，字逸少，人称“王右军”。
肥字须要有骨，瘦字须要有肉：丰腴的字要有笔，瘦硬的字要有墨。', '《兰亭序》虽是楷书与行书的范本，但不必一笔一画都作为准则。正如周公、孔子不能没有过错一样，但小过错不影响他们的圣明，所以能成为圣人。不善于学习的人，连圣人的过错都学，所以容易固守一隅。今天学《兰亭序》的人，多是这样。鲁国那位闭门不纳邻居嫠妇的男子说：“我将用不让妇人进屋的办法，来学习柳下惠坐怀不乱的精神。”有了这种“以吾之不可学人之可”的认识，就可以学习书法了。
王羲之书法，被认为如同以锥画沙、用印印泥一般。重要的是他在书写时中锋藏锋，意在笔先。师承王氏的人总是以《兰亭序》开头的“永”字作为楷模，这样容易拘泥于法，形成俗气。重要的是明白王羲之“如锥画沙”、“如印印泥”这两句话，这是我们值得师法的。
苏东坡先生说：“大字书写难以达到结体严密不散，小字书写难达到结体宽绰疏朗。”像王羲之的《东方朔画像赞》、《乐毅论》、《兰亭禊事诗叙》等就是这样。先秦古物器皿上的文字，蝌蚪篆文，紧密而不散，如焦山摩崖《瘗鹤铭》、永州摩崖《大唐中兴颂》、李斯所书秦始皇及二世皇帝诏文的《峄山石刻》等。近人能够兼有二美的，如杨凝式的楷书与行草书，徐铉的小篆。这虽然不被俗人认可，但书法毕竟应当如此。正如人在目眩之时，五色难辨，等到神情安静，意定神闲之时，青黄皂白，就自然分明。学习书法经常临摹，可以做到形似。重要的是要多取古人法帖本细细品读，做到心领神会，才能到达妙境。只有专心致志，才能做到神似。
学习书法过分强调端正，则受制于法度；侧锋能求得妍美，但往往容易左工而右病。古人临《兰亭序》、《孔子庙堂碑》，都以淡墨临摹一遍，从中可以看出古人如何用笔，如何回腕收笔，藏锋蓄势。如果是浓墨临摹，仅得其笔中意趣罢了。今人只见浓墨帖本，用笔多半是收笔蓄势，锋不外露，所以用秃笔临摹，岂不知古代书家作书时，笔锋尖锐，这恰是古人没有传给后人的秘诀。
作书时意在笔先，心使手，手运笔，写出来的字才能合乎书者心意。古人作书没有其他不一样的，只是用笔熟练罢了。
草书的妙处，须学书人自己体会，学得久了，就会明白。池水尽墨和用笔成冢的故事，并非胡乱编造出来的。
作书要宁拙毋巧。当前年轻人学书，宛如新娘子梳妆打扮，花枝招展，到底缺少贞女烈妇的端庄稳重之态。
学书要胸中有道义，再广泛吸收圣贤哲人的学问，作品才能成为可贵。如果胸无点墨，即使笔墨达到钟繇、王羲之的水平，也只是一个写字匠而已。我曾经说过：读书人做什么都可以，只是不可俗气，一旦庸俗便不可救药了。
写字有笔法，就像禅诗中有“诗眼”一样，具有把握诗眼的能力，才算懂得诗。凡学习书法，要先学会用笔。用笔的方法，要采用双钩或回腕执笔法，掌要虚，指要实，用无名指抵住笔管，这样才有力。古人学习书法不全在于临摹，他们将前人的字张贴在墙壁上，直到看得入神，下笔就会轻松自然。字写好了，加上自身学养的提高而无世俗之气，然后进行创作，则可作为别人学习的范本。学习书法须熟读魏晋书法墨迹，心领神会，自然可得古人笔法。要学习草书，须精通楷书，知道下笔向背，这样就会懂得草书用笔和结字法则，写好草书就不算难事了。
肥腴的字要有笔，瘦硬的字要有墨。古人学习书法，兼学这两方面，今人学习书法，肥与瘦都是病，还常学某人拙劣的东西，像今人学颜体就是如此，让人感慨不已。
楷书要如快马入阵，有草书的爽快，草书要出规入矩，有楷书的法度，这是古人书法的妙处。书法的工拙因人而异，但毕竟阅历深厚、笔法娴熟、心意恬淡的人，才能进入精妙之境。', NULL, '', 'indent', 1569457307, '5d8b9411d3761600732ed0ec', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642941, '左传 · 僖公 · 僖公十一年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有一年春。晋杀其大夫ぶ郑父。夏，公及夫人姜氏会齐侯于阳谷。秋八月，大雩。冬，楚人伐黄。
【传】十一年春，晋侯使以ぶ郑之乱来告。
天王使召武公、内史过赐晋侯命。受玉惰。过归，告王曰：「晋侯其无后乎。王赐之命而惰于受瑞，先自弃也已，其何继之有？礼，国之干也。敬，礼之舆也。不敬则礼不行，礼不行则上下昏，何以长世？」
夏，扬、拒、泉、皋、伊、洛之戎同伐京师，入王城，焚东门，王子带召之也。秦、晋、伐戎以救周。秋，晋侯平戎于王。
黄人不归楚贡。冬，楚人伐黄。', '', '', '十一年春季，晋惠公派遣使者报告邳郑发动的叛乱。
周襄王派遣召武公、内史过以荣宠赐给晋惠公。晋惠公接受瑞玉的时候精神不振作。内史过回去，向周襄王报告说：“晋侯的后代恐怕不能享有禄位了吧！天子以荣宠赐给他，他反而懒散地接受瑞玉，这就是先自暴自弃了，他还会有什么继承人？礼，是国家的躯干；敬，是载礼的车箱。不恭敬，礼就不能实施；礼不能实施，上下就昏乱，如何能长久？”夏季，扬、拒、泉、皋和伊洛的戎人一起进攻京城，进了王城，烧了东门，这是王子带召引来的。
秦军、晋军攻打戎军来救援周朝。秋季，晋惠公让戎人和周襄王讲和。
黄国人不向楚国进贡品。冬季，楚国人进攻黄国。', NULL, '', 'indent', 1558694965, '5ce75bb3d5de2b0070485c17', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642942, '左传 · 僖公 · 僖公十二年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有二年春王三月庚午，日有食之。夏，楚人灭黄。秋七月。冬十有二月丁丑，陈侯杵臼卒。
【传】十二年春，诸侯城卫楚丘之郛，惧狄难也。
黄人恃诸侯之睦于齐也，不共楚职，曰：「自郢及我九百里，焉能害我？」夏，楚灭黄。 　　王以戎难故，讨王子带。秋，王子带奔齐。
冬，齐侯使管夷吾平戎于王，使隰朋平戎于晋。
王以上卿之礼飨管仲，管仲辞曰：「臣，贱有司也，有天子之二守国、高在。若节春秋来承王命，何以礼焉？陪臣敢辞。」王曰：「舅氏，余嘉乃勋，应乃懿德，谓督不忘。往践乃职，无逆朕命。」管仲受下卿之礼而还。君子曰：「管氏之世祀也宜哉！让不忘其上。《诗》曰：『恺悌君子，神所劳矣。』」
', '', '', '十二年春季，诸侯在卫国的楚丘建筑外城，这是因为担心狄人来犯。黄人依靠诸侯和齐国和睦，不向楚国进贡，说：“从郢都到我国有九百里，楚国哪能危害我国？”夏季，楚国就灭亡了黄国。
周襄王由于戎人骚扰的缘故，讨伐王子带。秋季，王子带逃亡到齐国。冬季，齐桓公派遣管仲让戎人和周襄王讲和，派隰朋让戎人和晋国讲和。
周襄王以上卿的礼节设宴招待管仲。管仲辞谢说：“陪臣是低贱的官员。现在有天子所任命的国氏、高氏在那里，如果他们按春秋两季接受天子的命令，又用什么礼节来待他们呢？陪臣谨请辞谢。”天子说：“舅父，我赞美你的功勋，接受你的美德，这可以说是深厚而不能忘记的。去执行你的职务吧，不要违抗我的命令！”管仲最终还是接受了下卿的礼节而回国。君子说：“管氏世世代代受到祭祀是多么恰当啊！谦让而不忘记爵位比他高的上卿。《诗》说：‘和蔼平易的君子，就是神明所保佑的了。’”', NULL, '', 'indent', 1558695008, '5ce75bdeba39c800684da6ec', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642943, '左传 · 僖公 · 僖公十三年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有三年春，狄侵卫。夏四月，葬陈宣公。公会齐侯、宋公、陈侯、郑伯、许男、曹伯于咸。秋九月，大雩。冬，公子友如齐。
【传】十三年春，齐侯使仲孙湫聘于周，且言王子带。事毕，不与王言。归，覆命曰：「未可。王怒未怠，其十年乎。不十年，王弗召也。」
夏，会于咸，淮夷病杞故，且谋王室也。
秋，为戎难故，诸侯戍周，齐仲孙湫致之。
冬，晋荐饥，使乞籴于秦。秦伯谓子桑：「与诸乎？」对曰：「重施而报，君将何求？重施而不报，其民必携，携而讨焉，无众必败。」谓百里：「与诸乎？」对曰：「天灾流行，国家代有，救灾恤邻，道也。行道有福。」
ぶ郑之子豹在秦，请伐晋。秦伯曰：「其君是恶，其民何罪？」秦于是乎输粟于晋，自雍及绛相继，命之曰泛舟之役。
', '', '', '十三年春季，齐桓公派遣仲孙湫到成周聘问，同时要他说起王子带的事情。聘问完了，仲孙湫不和周襄王谈起王子带。回国，向齐桓公汇报说：“还不行。周襄王的怒气没有消除，恐怕要等十年了。不到十年周王是不会召他回去的。”
夏季，鲁僖公和齐桓公、宋襄公、陈穆公、卫文公、郑文公、许僖公、曹共公在咸地会见，一则由于淮夷让杞国感到担心，同时也由于商量使周王朝安定。
秋季，为了戎人造成的祸难，诸侯派兵防守成周。齐国的仲孙湫也带领军队前去。
冬季，晋国再次发生饥荒，派人到秦国请求购买粮食。秦穆公对子桑说：“给他们吗？”子桑回答说：“再一次给他们恩惠而报答我们，君王还要求什么？再一次给他们恩惠而不报答我们，他们的老百姓必然离心；离心以后再去讨伐，他没有群众就必然失败。”秦穆公对百里说：“给他们吗？”百里回答说：“天灾流行，总会在各国交替发生的。救援灾荒，周济邻国，这是正道。按正道办事会有福禄。”邳郑的儿子豹在秦国，请求进攻晋国。秦穆公说：“厌恶他们的国君，百姓有什么罪？”秦国就这样把粟米运送到晋国，船队从雍城到绛城接连不断，人们把这次运粮称为“泛舟之役”。', NULL, '', 'indent', 1558695074, '5ce75c1ec8959c0069ac68fa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642944, '左传 · 僖公 · 僖公十四年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有四年春，诸侯城缘陵。夏六月，季姬及鄫子遇于防。使鄫子来朝。秋八月辛卯，沙鹿崩。狄侵郑。冬，蔡侯肝卒。
【传】十四年春，诸侯城缘陵而迁杞焉。不书其人，有阙也。
鄫季姬来宁，公怒，止之，以鄫子之不朝也。夏，遇于防，而使来朝。
秋八月辛卯，沙鹿崩。晋卜偃曰：「期年将有大咎，几亡国。」
冬，秦饥，使乞籴于晋，晋人弗与。庆郑曰：「背施无亲，幸灾不仁，贪爱不祥，怒邻不义。四德皆失，何以守国？」虢射曰：「皮之不存，毛将安傅？」庆郑曰：「弃信背邻，患孰恤之？无信患作，失授必毙，是则然矣。」虢射曰：「无损于怨而厚于寇，不如勿与。」庆郑曰：「背施幸灾，民所弃也。近犹仇之，况怨敌乎？」弗听。退曰：「君其悔是哉！」', '', '', '十四年春季，诸侯在缘陵筑城而把杞都迁去。《春秋》没有记载筑城的是哪些国家，是由于文字有缺。
鄫季姬回鲁国娘家，僖公发怒，留住她不准回去，这是因为鄫子不来朝见的缘故。夏季，鄫季姬和鄫子在防地见面，要鄫子前来朝见。
秋季，八月初五日，沙鹿山崩塌。晋国的卜偃说：“一周年将会有大灾难，几乎要亡国。”
冬季，秦国发生饥荒，派人到晋国请求购买粮食。晋国人不给。庆郑说：“背弃恩惠就没有亲人，幸灾乐祸就是不仁，贪图所爱惜的东西就是不祥，使邻国愤怒就是不义。这四种道德都丢掉了，用什么来保卫国家？”虢射说：“皮已经不存在，毛又依附在哪里？”庆郑说：“丢弃信用，背弃邻国，患难谁来周济？没有信用就会发生患难，失掉了救援，必定灭亡。这就是那样的。”虢射说：“即使给粮食，对怨恨不会有所减少，反而使敌人增加实力，不如不给。”庆郑说：“背弃恩惠，幸灾乐祸，是百姓所唾弃的。亲近的人还会因此结仇，何况是敌人呢？”晋惠公不听。庆郑退下来说：“国君要后悔的！”
', NULL, '', 'indent', 1558695111, '5ce75c45ba39c800684dab43', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642945, '左传 · 僖公 · 僖公十五年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有五年春王正月，公如齐。楚人伐徐。三月，公会齐侯、宋公、陈侯、卫候、郑伯、许男、曹伯盟于牡丘，遂次于匡。公孙敖帅师及诸侯之大夫救徐。夏五月，日有食之。秋七月，齐师、曹师伐厉。八月，螽。九月，公至自会。季姬归于鄫。己卯晦，震夷伯之庙。冬，宋人伐曹。楚人败徐于娄林。十有一月壬戌，晋侯及秦伯战于韩，获晋侯。
【传】十五年春，楚人伐徐，徐即诸夏故也。三月，盟于牡丘，寻蔡丘之盟，且救徐也。孟穆伯帅师及诸侯之师救徐，诸侯次于匡以待之。
夏五月，日有食之。不书朔与日，官失之也。
秋，伐，厉，以救徐也。
晋侯之入也，秦穆姬属贾君焉，且曰：「尽纳群公子。」晋侯烝于贾君，又不纳群公子，是以穆姬怨之。晋侯许赂中大夫，既而皆背之。赂秦伯以河外列城五，东尽虢略，南及华山，内及解梁城，既而不与。晋饥，秦输之粟；秦饥，晋闭之籴，故秦伯伐晋。
卜徒父筮之，吉。涉河，侯车败。诘之，对曰：「乃大吉也，三败必获晋君。其卦遇《蛊》，曰：『千乘三去，三去之馀，获其雄狐。』夫狐蛊，必其君也。《蛊》之贞，风也；其悔，山也。岁云秋矣，我落其实而取其材，所以克也。实落材亡，不败何待？」
三败及韩。晋侯谓庆郑曰：「寇深矣，若之何？」对曰：「君实深之，可若何？」公曰：「不孙。」卜右，庆郑吉，弗使。步扬御戎，家仆徒为右，乘小驷，郑入也。庆郑曰：「古者大事，必乘其产，生其水土而知其人心，安其教训而服习其道，唯所纳之，无不如志。今乘异产，以从戎事，及惧而变，将与人易。乱气狡愤，阴血周作，张脉偾兴，外强中乾。进退不可，周旋不能，君必悔之。」弗听。
九月，晋侯逆秦师，使韩简视师，复曰：「师少于我，斗士倍我。」公曰：「何故？」对曰：「出因其资，入用其宠，饥食其粟，三施而无报，是以来也。今又击之，我怠秦奋，倍犹未也。」公曰：「一夫不可狃，况国乎。」遂使请战，曰：「寡人不佞，能合其众而不能离也，君若不还，无所逃命。」秦伯使公孙枝对曰：「君之未入，寡人惧之，入而未定列，犹吾忧也。苟列定矣，敢不承命。」韩简退曰：「吾幸而得囚。」
壬戌，战于韩原，晋戎马还泞而止。公号庆郑。庆郑曰：「愎谏违卜，固败是求，又何逃焉？」遂去之。梁由靡御韩简，虢射为右，辂秦伯，将止之。郑以救公误之，遂失秦伯。秦获晋侯以归。晋大夫反首拔舍从之。秦伯使辞焉，曰：「二三子何其戚也？寡人之从君而西也，亦晋之妖梦是践，岂敢以至。」晋大夫三拜稽首曰：「君履后土而戴皇天，皇天后土实闻君之言，群臣敢在下风。」
穆姬闻晋侯将至，以大子荦、弘与女简、璧登台而履薪焉，使以免服衰絰逆，且告曰：「上天降灾，使我两君匪以玉帛相见，而以兴戎。若晋君朝以入，则婢子夕以死；夕以入，则朝以死。唯君裁之。」乃舍诸灵台。
大夫请以入。公曰：「获晋侯，以厚归也。既而丧归，焉用之？大夫其何有焉？且晋人戚忧以重我，天地以要我。不图晋忧，重其怒也；我食吾言，背天地也。重怒难任，背天不祥，必归晋君。」公子絷曰：「不如杀之，无聚慝焉。」子桑曰：「归之而质其大子，必得大成。晋未可灭而杀其君，只以成恶。且史佚有言曰：『无始祸，无怙乱，无重怒。』重怒难任，陵人不祥。」乃许晋平。
晋侯使郤乞告瑕吕饴甥，且召之。子金教之言曰：「朝国人而以君命赏，且告之曰：『孤虽归，辱社稷矣。其卜贰圉也。』」众皆哭。晋于是乎作爰田。吕甥曰：「君亡之不恤，而群臣是忧，惠之至也。将若君何？」众曰：「何为而可？」对曰：「征缮以辅孺子，诸侯闻之，丧君有君，群臣辑睦，甲兵益多，好我者劝，恶我者惧，庶有益乎！」众说。晋于是乎作州兵。
初，晋献公筮嫁伯姬于秦，遇《归妹》三之《睽》三。史苏占之曰：「不吉。其繇曰：『士刲羊，亦无亡也。女承筐，亦无贶也。西邻责言，不可偿也。《归妹》之《睽》，犹无相也。』《震》之《离》，亦《离》之《震》，为雷为火。为嬴败姬，车说问其輹，火焚其旗，不利行师，败于宗丘。《归妹》《睽》孤，寇张之弧，侄其从姑，六年其逋，逃归其国，而弃其家，明年其死于高梁之虚。」及惠公在秦，曰：「先君若从史苏之占，吾不及此夫。」韩简侍，曰：「龟，像也；筮，数也。物生而后有象，像而后有滋，滋而后有数。先君之败德，乃可数乎？史苏是占，勿从何益？《诗》曰：『下民之孽，匪降自天，僔沓背憎，职竞由人。』」
震夷伯之庙，罪之也，于是展氏有隐慝焉。
冬，宋人伐曹，讨旧怨也。
楚败徐于娄林，徐恃救也。
十月，晋阴饴甥会秦伯，盟于王城。
秦伯曰：「晋国和乎？」对曰：「不和。小人耻失其君而悼丧其亲，不惮征缮以立圉也，曰：『必报仇，宁事戎狄。』君子爱其君而知其罪，不惮征缮以待秦命，曰：『必报德，有死无二。』以此不和。」秦伯曰：「国谓君何？」对曰：「小人戚，谓之不免。君子恕，以为必归。小人曰：『我毒秦，秦岂归君？』君子曰：『我知罪矣，秦必归君。贰而执之，服而舍之，德莫厚焉，刑莫威焉。服者怀德，贰者畏刑。此一役也，秦可以霸。纳而不定，废而不立，以德为怨，秦不其然。』」秦伯曰：「是吾心也。」改馆晋侯，馈七牢焉。
蛾析谓庆郑曰：「盍行乎？」对曰：「陷君于败，败而不死，又使失刑，非人臣也。臣而不臣，行将焉入？」十一月，晋侯归。丁丑，杀庆郑而后入。 　　是岁，晋又饥，秦伯又饩之粟，曰：「吾怨其君而矜其民。且吾闻唐叔之封也，箕子曰：『其后必大。』晋其庸可冀乎！姑树德焉以待能者。」于是秦始征晋河东，置官司焉。', '', '', '十五年春季，楚国人进攻徐国，由于徐国依靠中原诸侯的缘故。三月，鲁僖公和齐桓公、宋襄公、陈穆公、卫文公、郑文公、许僖公、曹共公在牡丘结盟，重温葵丘的盟约，同时为了救援徐国。孟穆伯率领鲁军和诸侯的军队救援徐国，诸侯住在匡地等待他。
夏季，五月，发生日食。《春秋》没有记载朔日和日期，由于史官的漏记。
秋季，进攻厉国，以此来救援徐国。
晋惠公回国继承君位的时候，秦穆姬把贾君嘱托给他，而且说：“把公子们都接回国内。”晋惠公和贾君通奸，又不接纳公子们回国，由此穆姬就怨恨他。晋惠公曾经答应给中大夫送礼，后来也都不给了。还答应给秦穆公黄河以西和以南的五座城，东边到虢略镇，南边到华山，还有黄河之内的解梁城，后来都不兑现。晋国有饥荒，秦国给它运送粟米；秦国有饥荒，晋国却拒绝秦国买粮，所以秦穆公攻打晋国。
卜徒父用筮草占卜，吉利：“渡过黄河，毁坏侯的车子。”秦穆公仔细追问，卜徒父回答说：“这是大吉大利。晋军连败三次，晋国国君必然被俘获。这一卦得到《蛊》，繇辞说：‘三次驱除一千辆兵车，三次驱除之余，获得了那条雄狐。’雄狐指的一定是他们的国君。《蛊》的内卦是风，外卦是山。时令到了秋天了，我们的风吹过他们山上，吹落了他们的果实，还取得他们的木材，所以能战胜。果实落地而木材丢失，不打败仗还等待什么？”晋军三次战败，退到韩地。晋惠公对庆郑说：“敌人深入了，怎么办？”庆郑回答说：“君王让他们深入的，能够怎么办？”晋惠公说：“答话放肆无礼！”占卜车右的人选，庆郑得吉卦。但是晋惠公不用他，让步扬驾御战车，家仆徒作为车右。以小驷马驾车，是从郑国来的。庆郑说：“古代发生战争，一定要用本国的马驾车。出生在自己的水土上，知道主人的心意；安于受主人的调教，熟悉这里的道路；随你放在哪里，没有不如意的。现在用外国出产的马来驾车，从事战斗，等到一害怕而失去正常状态，就会不听指挥了。鼻子里乱喷粗气表示狡猾和愤怒，血液在全身奔流，使血管扩张突起，外表强壮而内部枯竭。进也不能，退也不是，旋转也不能，君王必然要后悔。”晋惠公不听。
九月，晋惠公将要迎战秦军，派韩简视察军队。韩简回来说：“军队比我们少，能奋力作战的人却倍于我们。”晋惠公说：“什么原因？”韩简回答说：“君王逃离晋国是由于他的资助，回国是由于他的宠信，有了饥荒吃他的粟米，三次给我们恩惠而没有报答，由于这样他们才来的。现在又将迎击他们，我方懈怠，秦国奋发，斗志岂止相差一倍啊！”晋惠公说：“一个人还不能轻侮，何况是国家呢？”于是就派韩简去约战，说：“寡人不才，能集合我的部下而不能让他们离散。君王如果不回去，我们将没有地方逃避命令。”秦穆公派公孙枝回答说：“晋君没有回国，我为他忧惧；回国后没有安定位置，还是我所担心的。如果君位已定，寡人敢不接受作战的命令？”韩简退下去说：“我如果能被俘囚禁就是幸运的。”
十四日，秦、晋两军在韩原作战。晋惠公的小驷马陷在烂泥中盘旋不出。晋惠公向庆郑呼喊求救。庆郑说：“不听劝谏，违抗占卜，本来就是自取失败，为什么又要逃走呢？”于是就离开了。梁由靡驾韩简的战车，虢射作为车右，迎战秦穆公的战车，将要俘虏他。庆郑因为叫他们救援晋惠公而耽误，就使秦穆公走脱了。秦国俘虏了晋惠公。晋国的大夫披头散发，拔出帐篷，跟随晋惠公。秦穆公派使者辞谢说：“你们几位为什么那样忧愁啊！寡人跟随晋国国君往西去，只不过实现晋国的妖梦罢了，难道敢做得太过分吗？”晋国的大夫三拜叩头说：“君王踩着后土，而顶着皇天，皇天后土都听到了您的话，下臣们谨在下边听候吩咐。”
秦穆姬听说晋惠公将要来到，领着太子莹、儿子弘和女儿简璧登上高台，踩着柴草。她派遣使者捧着遭丧所着丧服前去迎接秦穆公，说：“上天降下灾祸，让我两国国君不是用礼品相见而是兴动甲兵。如果晋国国君早晨进入国都，那么我就晚上自焚；晚上进入，那么我就早晨自焚。请君王裁夺。”
于是秦穆公把晋惠公拘留在灵台。大夫请求把晋惠公带回国都。秦穆公说：“俘获晋侯，本来是带着丰厚的收获回来的，但一回来就要发生丧事，这有什么用？大夫又能得到什么呢？而且晋国人用忧愁来感动我，用天地来约束我，如果不考虑晋国人的忧愁，就会加深他们对秦国的愤怒。我如果不履行自己的诺言，就是违背天地，加深愤怒会使我担当不起，违背天地会不吉利，一定要放晋君回国。”公子絷说：“不如杀了他，不要积聚邪恶。”子桑说：“放他回国而用他的太子作为人质，必然会得到很有利的讲和条件。晋国还不会灭亡，而杀掉它的国君，只能造成很坏的后果。而且史佚有话说：‘不要发动祸患，不要依靠动乱，不要增加愤怒。’增加愤怒会使人难于担当，欺凌别人会不吉利。”于是就允许晋国讲和。
晋惠公派遣郤乞告诉瑕吕饴甥，同时召他前来，饴甥教郤乞该怎么说话，说：“把都城里的人都召到宫门前而用国君的名义给予赏赐。而且告诉他们说：“我虽然回国了，但已经给国家带来了耻辱，还是占卜一个吉日，让我的继承人圉就国君之位吧。’”郤乞回去照办，大家一齐号哭。晋国就在这时开始改易田制，开阡陌从新规定田界。吕饴甥说：“国君不为自己在外而担忧，反而为群臣担忧，这是最大的恩惠了，我们准备怎样对待国君？”大家说：“怎么办才行呢？”吕饴甥回答说：“征收赋税，修理装备武器，以辅助继承人。诸侯听到我国失去了国君，又有新的国君，群臣和睦，装备武器比以前更多。喜欢我们的就会勉励我们，讨厌我们的就会有所害怕，也许会有好处吧！”大家很高兴，晋国因为这样而开始兵制改革。
当初，晋献公为嫁伯姬给秦国而占筮，得到《归妹》变成《睽》卦。史苏预测说：“不吉利。卦辞说：‘男人宰羊，不见血浆；女人拿筐，白忙一场。西邻责备，不可补偿。《归妹》变《睽》，没人相帮。’《震》卦变成《离》卦，也就是《离》卦变成《震》卦。‘又是雷，又是火，胜者姓嬴，败者姓姬。车子脱离车轴，大火烧掉军旗，不利于出师，在宗丘打得大败。《归妹》嫁女，《睽》离单孤，敌人的木弓将要张舒。侄子跟着姑姑，六年之后，逃回自己所居，抛弃了他的家，明年死在高梁的废墟。’”等到惠公在秦国，说：“先君如果听从了史苏的占卜，我不会到这个地步！”韩简随侍在侧，说：“龟甲，是形象；筮草，是数字。事物生长以后才有形象，有形象以后才能滋长，滋长以后才有数字。先君败坏的道德，难道可以数得完吗？史苏的占卜，即使听从了，又有什么好处？《诗》说：‘百姓的灾祸，不是从天下降。当面附和，背后毁谤，主要都由于人的无状。’”
雷击夷伯的庙宇，这是降罪于他，由于可以看到展氏有别人不知道的隐恶。
冬季，宋国人进攻曹国，为了报复以前结下的怨恨。楚国在娄林打败徐国，徐国所以失败，是由于专靠别国去救援。十月，晋国的阴饴甥会见秦穆公，在王城订立盟约。
秦穆公说：“晋国和睦吗？”阴饴甥回答悦：“不和睦。小人以失掉国君为耻辱，而哀悼失去了的亲属，不怕筹集资金，重整军队而立圉为国君，说：“一定报仇，宁可因此而事奉戎狄。’君子爱护国君而知道他的罪过，不怕筹集资金，重整军队来等待秦国的命令，说：‘一定要报答恩德，有必死之志而无二心。’因为这样才不和睦。”秦穆公说：“全国认为国君的前途会怎么样？”阴饴甥回答说：“小人忧愁，认为他不会被赦免；君子宽恕，以为他一定会回来。小人说：‘我们得罪了秦国，秦国怎么能让国君回来？’君子说：‘我们已经认罪了，秦国一定让国君回来。有三心二意，就抓起来；服了罪，就释放他。德行没有比这再宽厚的了，刑罚没有比这再威严的了。服罪的怀念德行，有三心二意的害怕刑罚，这一战役，秦国可以称霸诸侯。让他回国而不使之安定，甚至废掉他而不立他为国君，使恩惠变为怨恨，秦国不会这样做的吧！’”秦穆公说：“我正是这样想的。”于是改变对晋惠公的待遇，让他住在宾馆里，馈送了七副牛、羊、猪等食用物品。蛾析对庆郑说：“何不逃走呢？”庆郑回答说：“使国君陷于失败，失败了不死反而逃亡，又让国君失去刑罚，这就不是做臣下的样子。臣下而不合于臣道，又能逃到哪里去？”十一月，晋惠公回国。二十九日，杀了庆郑，然后进入国都。
这一年，晋国又发生饥荒，秦穆公赠送给他们粟米，说：“我怨恨他们的国君，而怜悯他们的百姓。而且我听说唐叔受封的时候，箕子说：‘他的后代一定昌大。’晋国是可以图谋的吗！我们姑且树立恩惠，来等待有才能的人。”于是，秦国就开始在晋国黄河东部征收赋税，设置官员。', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b6512b5420e2767ef2aa9", "shortContent": "春秋时代秦、晋是邻国，也都是大国，两国在相当长的历史时期内保持了一种十分奇特的关系。一方面从晋献公把女儿（即文中的穆姬）嫁给秦穆公开始，两国公室就不断通婚。政治联姻对于双方而言是两全其美的事情，增强了两国对付外部压力的能力。另一方面，在此期间两国之间不时发生战事，而韩之战则是秦晋之间第一次最大规模的战争。这次战争对于秦国来说具有重要意义，由于秦在韩之战中的胜利，秦开始将其地盘东扩，秦国因此逐步强盛...", "authors": ["何善蒙"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558695152, '5ce75c6d30863b0068d0e8f8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642946, '左传 · 僖公 · 僖公十六年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有六年春王正月戊申朔，陨石于宋五。是月，六鷁退飞，过宋都。三月壬申，公子季友卒。夏四月丙申，鄫季姬卒。秋七月甲子，公孙兹卒。冬十有二月，公会齐侯、宋公、陈侯、卫侯、郑伯、许男、邢侯、曹伯于淮。
【传】十六年春，陨石于宋五，陨星也。六鷁退飞过宋都，风也。周内史叔兴聘于宋，宋襄公问焉，曰；「是何祥也？吉凶焉在？」对曰：「今兹鲁多大丧，明年齐有乱，君将得诸侯而不终。」退而告人曰：「君失问。是阴阳之事，非吉凶所生也。吉凶由人，吾不敢逆君故也。」
夏，齐伐厉不克，救徐而还。
秋，狄侵晋，取狐、厨、受铎，涉汾，及昆都，因晋败也。
王以戎难告于齐，齐征诸侯而戍周。
冬，十一月乙卯，郑杀子华。
十二月会于淮，谋郐，且东略也。城鄫，役人病。有夜登丘而呼曰：「齐有乱。」不果城而还。', '', '', '十六年春季，在宋国上空坠落五块石头，这是坠落的星星。六只鹢鸟后退着飞，经过宋国国都，这是由于风太大的缘故。成周的内使叔兴在宋国聘问，宋襄公询问这两件事，说：“这是什么预兆？吉凶在于哪里？”叔兴回答说：“今年鲁国多有大的丧事，明年齐国有动乱，君王将会得到诸侯拥护却不能保持到最后。”退下来告诉别人说：“国君询问得不恰当，这是有关阴阳的事情，人事吉凶与此无关。吉凶由人的行为所决定。我这样回答是由于不敢违背国君的缘故。”
夏季，齐国进攻厉国，没有得胜，救援了徐国而后回国。
秋季，狄人攻打晋国，占取了狐、厨、受铎，渡过汾水，到达昆都，因为晋国战败了。
周襄王把戎人造成的祸难告诉齐国。齐国调集诸侯的军队到成周去防守。
冬季，十一月十二日，郑国杀了子华。十二月，鲁僖公和齐桓公、宋襄公、陈穆公、卫文公、郑文公、许僖公、邢侯、曹共公在淮地会见，是为了商量救援鄫国免被淮夷所侵。并且商量向东方用兵。替鄫国筑城，服劳役的人困乏，有人夜里登上小山头喊叫说：“齐国发生动乱！”诸侯没有等到筑完城就各自回国了。', NULL, '', 'indent', 1558695189, '5ce75c93ba39c800684dae54', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643451, '定武兰亭十三跋', NULL, 27, 574, 2, 0, '赵孟頫', NULL, 11456, '5858e678ac502e006708402d', '元', 'wen', '文', '', '', '【第一跋】
兰亭帖自定武石刻既亡，在人间者有数。有日减，无日增，故博古之士以为至宝。然极难辨。又有未损五字者，五字未损，其本尤难得。此盖已损者，独孤长老送余北行，携以自随。至南浔北，出以见示。因从独孤乞得，携入都。他日来归，与独孤结一重翰墨缘也。至大三年九月五日，跋于舟中。独孤名淳朋，天台人。
【第二跋】
兰亭帖当宋未度南时，士大夫人人有之。石刻既亡，江左好事者，往往家刻一石，无虑数十百本，而真赝始难别矣。王顺伯，尤延之诸公，其精识之尤者。于墨色、纸色、肥瘦秾纤之间，分毫不爽。故朱晦翁跋兰亭谓：“不独议礼如聚讼”，盖笑之也。然传刻既多，实亦未易定其甲乙。此卷乃致佳本，五字镵损，肥瘦得中。与王子庆所藏赵子固本无异，石本中至宝也。至大三年九月十六日。舟次宝应重题。子昂。
【第三跋】
兰亭诚不可忽。世间墨本日亡日少，而识真者盖难。其人既识而藏之，可不宝诸。十八日清河舟中。
【第四跋】
河声如吼，终日屏息。非得此卷时时展玩，何以解日。盖日数十舒卷。所得为不少矣。廿二日邳州北题。
【第五跋】
昔人得古刻数行，专心而学之，便可名世。况兰亭是右军得意书，学之不已，何患不过人耶。顷闻吴中北禅主，僧有定武兰亭，是其师晦岩照法师所藏。从其借观不可。一旦得此，喜不自胜。独孤之与东屏，贤不肖何如也。廿三日将过吕梁泊舟题。
【第六跋】
学书在玩味古人法帖，悉知其用笔之意，乃为有益。右军书兰亭是已退笔，因其势而用之，无不如志，兹其所以神也。昨晚宿沛县。廿六日早饭罢题。
【第七跋】
书法以用笔为上，而结字亦须用工。盖结字因时相传，用笔千古不易。右军字势古法一变，其雄秀之气出于天然，故古今以为师法。齐梁间人，结字非不古，而乏俊气，此又存乎其人，然古法终不可失也。廿八日济州南待闸题。
【第八跋】
廿九日至济州，遇周景远新除行台监察御史，自都下来，酌酒于驿亭。人以纸素求书于景远者甚众，而乞余书者坌集，殊不可当。急登舟解缆，乃得休。是晚，至济州北三十里，重展此卷，因题。
【第九跋】
东坡诗云：“天下几人学杜甫，谁得其皮与其骨。”学兰亭者亦然。黄太史亦云：“世人但学兰亭面，欲换凡骨无金丹。”此意非学书者不知也。十月一日。
【第十跋】
大凡石刻虽一石，而墨本辄不同，盖纸有厚薄、麁细、燥湿，墨有浓淡，用墨有轻重，而刻之肥瘦明暗随之，故兰亭难辨。然真知书法者，一见便当了然，正不在肥瘦明暗之间也。十月二日过安山北寿张书。
【第十一跋】
右军人品甚高，故书入神品。奴隶小夫，乳臭之子，朝学执笔，暮已自夸其能。薄俗可鄙，可鄙。三日泊舟虎陂，待放闸书。
【第十二跋】
余北行三十二日，秋冬之间而多南风，船窗晴暖，时对兰亭，信可乐也。七日书。
【第十三跋】
兰亭与丙舍帖绝相似。', '元代著名书法家赵孟頫的传世名作《定武兰亭十三跋》作于至大三年（公元1310年），受当时还是太子的仁宗之邀，赵孟頫结束了在杭州十年的江浙儒学提举之任，取道运河北上大都。离开杭州时，赵孟頫的好友吴森决定陪他同行。吴森是嘉兴的大藏家，他随身携带了一本家藏的《定武兰亭》（五字损本）。九月五日，当船行到湖州南浔的时候，赶来送别的僧人独孤长老（名正吾，号东屏）也带了一本《定武兰亭》（五字不损本），并将它送给了赵孟頫。在船从杭州到大都（今北京）的34天的行程中，赵孟頫写了著名的《定武兰亭十三跋》，也称《兰亭十三跋》。
后来由于一场大火，这篇《兰亭十三跋》被烧的面目全非，仅留下些许残片，现存于日本。从残留下来的片段我们可以看到，赵子昂的这篇行书《兰亭十三跋》的用笔仍然是他的一贯书风，下笔果断有力，行笔方圆兼施，而收笔又含蓄内敛，给人一种飘逸潇洒的美感。不光是书法美，赵子昂在这篇《兰亭十三跋》中的相关论点同样精彩。著名的“用笔千古不易，而结字亦需用功”，成为了后世学书者努力方向的指南。在那段一个多月的行程中，周边一片宁静，唯有这欧阳询临摹的《定武兰亭》相伴，日日品读，沉迷其中，才有了这段流传千年的学书经典论述。不光是赞叹，赵子昂还品读出了些许的无奈。正所谓“世人尽学兰亭面，欲脱凡骨无金丹。”，大家都在追随王羲之的用笔，可是最后只是得到了肤浅的表面，真正想要脱胎换骨，却发现世上根本找不到改头换面的良药。其中的失落和有力，也许只有迷恋书法的人才有体会吧。', '', '', NULL, '', 'indent', 1570823104, '5da06b39ba39c800683cdb94', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642947, '左传 · 僖公 · 僖公十七年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有七年春，齐人、徐人伐英氏。夏，灭项。秋，夫人姜氏会齐侯于卞。九月，会至自会。冬十有二月乙亥，齐侯小白卒。
【传】十七年春，齐人为徐伐英氏，以报娄林之役也。
夏，晋大子圉为质于秦，秦归河东而妻之。惠公之在梁也，梁伯妻之。梁赢孕，过期，卜招父与其子卜之。其子曰：「将生一男一女。」招曰：「然。男为人臣，女为人妾。」故名男曰圉，女曰妾。及子圉西质，妾为宦女焉。
师灭项。淮之会，公有诸侯之事未归而取项。齐人以为讨，而止公。
秋，声姜以公故，会齐侯于卞。九月，公至。书曰：「至自会。」犹有诸侯之事焉，且讳之也。
齐侯之夫人三：王姬，徐嬴，蔡姬，皆无子。齐侯好内，多内宠，内嬖如夫人者六人：长卫姬，生武孟；少卫姬，生惠公；郑姬，生孝公；葛嬴，生昭公；密姬，生懿公，宋华子，生公子雍。公与管仲属孝公于宋襄公，以为太子。雍巫有宠于卫共姬，因寺人貂以荐羞于公，亦有宠，公许之立武孟。
管仲卒，五公子皆求立。冬十月乙亥，齐桓公卒。易牙入，与寺人貂因内宠以杀群吏，而立公子无亏。孝公奔宋。十二月乙亥赴。辛巳夜殡。', '', '', '十七年春季，齐国人为徐国攻打英氏，以报复前二年楚击败徐于娄林那一次战役。
夏季，晋国的太子圉在秦国作人质，秦国把河东土地归还晋国并把女儿嫁给圉。晋惠公在梁国的时候，梁伯把女儿嫁给他。梁嬴怀孕，过了预产期。卜招父和他的儿子占卜，他的儿子说：“将要生一男一女。”卜招父说：“对。男的做别人的奴仆，女的做别人的奴婢。”所以把男的叫做圉，女的取名叫做妾。等到子圉到西方作人质，妾就在秦国作了侍女。
鲁国军队灭亡项国。在淮地的会见，僖公正有和各国诸侯相会的大事，没有回国，鲁军就占取了项国。齐国人认为这是由僖公下令进攻，因此把僖公拘留，不让他回国。
秋季，声姜由于僖公的缘故，在卞地会见齐桓公。九月，僖公到达。《春秋》记载说“至自会”，这是由于国家大事还没有处理完，而且不愿说出被拘留这件事。
齐桓公的三位夫人，王姬、徐嬴、蔡姬，都没有儿子。齐桓公喜欢女色，宠爱的姬妾不少，宫内受宠的女人待遇如同夫人一样的有六人：大卫姬，生了武孟；小卫姬，生了惠公；郑姬，生了孝公；葛嬴，生了昭公；密姬，生了懿公；宋华子，生了公子雍。桓公和管仲把孝公托付给宋襄公，以他为太子。雍巫受到卫共姬的宠信，由于寺人貂的关系把美味的食品进献给齐桓公，又受到齐桓公的宠信。齐桓公答应他们立武孟为继承人。管仲死，五个公子都谋求立为嗣君。
冬季，十月初七日，齐桓公死。易牙进宫，和寺人貂依靠那些内宠的权贵而杀死一批官吏，立公子无亏为国君。孝公逃亡到宋国。十二月初八日，发出讣告。十四日夜间，将桓公尸体大殓入棺。
', NULL, '', 'indent', 1558695230, '5ce75cbba673f50068e4f4cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642948, '左传 · 僖公 · 僖公十八年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有八年春王正月，宋公、曹伯、卫人、邾人伐齐。夏，师救齐。五月戊寅，宋师及齐师战于甗。齐师败绩。狄救齐。秋八月丁亥，葬齐桓公。冬，邢人，狄人伐卫。
【传】十八年春，宋襄公以诸侯伐齐。三月，齐人杀无亏。
郑伯始朝于楚，楚子赐之金，既而悔之，与之盟曰：「无以铸兵。」故以铸三钟。
齐人将立孝公，不胜，四公子之徒遂与宋人战。夏五月，宋败齐师于，立孝公而还。
秋八月，葬齐桓公。
冬，邢人、狄人伐卫，围菟圃。卫侯以国让父兄子弟及朝众曰：「苟能治之，毁请从焉。」众不可，而后师于訾娄。狄师还。
梁伯益其国而不能实也，命曰新里，秦取之。', '', '', '十八年春季，宋襄公率领曹共公等攻打齐国。三月，齐国人杀了无亏。
郑文公开始到楚国朝见。楚成王把铜赐给他，不久又后悔，和他盟誓说：“不要拿来铸造武器。”所以郑文公用它铸造了三座钟。
齐国人准备立孝公为国君，挡不住四公子一伙的反对，孝公逃亡到宋国，四公子一伙就和宋军作战。夏季，五月，宋国在甗地打败了齐国，立了孝公，然后回国。
秋季，八月，安葬齐桓公。
冬季，邢人、狄人进攻卫国，包围了菟圃。卫文公把国君的地位推让给父兄子弟和朝廷上的其他人，说：“谁如果能治理国家，我就跟从他。”大家不同意，而后在訾娄摆开阵势。狄军就退回去了。梁伯扩充了疆土，筑了很多城邑，却不能把百姓迁往那里，把那地方命名为新里，但被秦国占取了。
', NULL, '', 'indent', 1558695263, '5ce75cdd7b968a0076348295', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642949, '左传 · 僖公 · 僖公十九年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有九年春王三月，宋人执滕子婴齐。夏六月，宋公、曹人、邾人盟于曹南。鄫子会盟于邾。己酉，邾人执郐子，用之。秋，宋人围曹。卫人伐邢。冬，会陈人、蔡人、楚人、郑人盟于齐。梁亡。
【传】十九年春，遂城而居之。
宋人执滕宣公。
夏，宋公使邾文公用鄫子于次睢之社，欲以属东夷。司马子鱼曰：「古者六畜不相为用，小事不用大牲，而况敢用人乎？祭祀以为人也。民，神之主也。用人，其谁飨之？齐桓公存三亡国以属诸侯，义士犹曰薄德。今一会而虐二国之君，又用诸淫昏之鬼，将以求霸，不亦难乎？得死为幸！」
秋，卫人伐邢，以报菟圃之役。于是卫大旱，卜有事于山川，不吉。宁庄子曰：「昔周饥，克殷而年丰。今邢方无道，诸侯无伯，天其或者欲使卫讨邢乎？」从之，师兴而雨。
宋人围曹，讨不服也。子鱼言于宋公曰：「文王闻崇德乱而伐之，军三旬而不降，退修教而复伐之，因垒而降。《诗》曰：『刑于寡妻，至于兄弟，以御于家邦。』今君德无乃犹有所阙，而以伐人，若之何？盍姑内省德乎？无阙而后动。」
陈穆公请修好于诸侯，以无忘齐桓之德。冬，盟于齐，修桓公之好也。
梁亡，不书其主，自取之也。初，梁伯好土功，亟城而弗处，民罢而弗堪，则曰：「某寇将至。」乃沟公宫，曰：「秦将袭我。」民惧而溃，秦遂取梁。', '', '', '十九年春季，秦国人就筑了城而移民居住在新里。宋人抓住了滕宣公。
夏季，宋襄公让邾文公杀死鄫子来祭祀次睢的土地神，想因此使东夷来降附。司马子鱼说：“古时候六种畜牲不能相互用来祭祀，小的祭祀不杀大牲口，何况敢于用人作牺牲呢？祭祀是为了人。百姓，是神的主人。杀人祭祀，有什么神来享用？齐桓公恢复了三个被灭亡的国家以使诸侯归附，义士还说他薄德，现在一次会盟而侵害两个国家的国君，又用来祭祀邪恶昏乱的鬼神，要拿这个来求取霸业，不也是很难吗？得以善终就算幸运了。”
秋季，卫军进攻邢国，以报复菟圃这一役。这时卫国大旱，为祭祀山川而占卜，不吉利。甯庄子说：“从前周室发生饥荒，打败了商朝就丰收。现在正当邢国无道，诸侯没有领袖，上天或者是要让卫国进攻邢国吧！”听从了他的话，征集军队就下了雨。
宋军包围曹国，为了讨伐曹国的不肯顺服。子鱼对宋公说：“文王听到崇国德行昏乱而去攻打，打了三十天，崇国不投降。退兵回国，修明教化，再去攻打，文王就驻扎在过去所筑的营垒里，崇国就投降了。《诗》说：‘在嫡妻面前作出示范，由此而作为兄弟们的表率，以此来治理一家一国。’现在君王的德行恐怕还有所欠缺，而以此攻打曹国，能把它怎么办？何不姑且退回去自己检查一下德行，等到没有欠缺了再采取行动。”
陈穆公请求在诸侯间重新建立友好关系，表示不忘齐桓公的德行。冬季，在齐国会盟，重新建立齐桓公时代的友好关系。
梁国灭亡了，《春秋》没有记载灭亡梁国的是谁，是因为祸害是梁国自己找取的。当初，梁伯喜好大兴土木，屡次筑城而无人居住，百姓疲倦得不能忍受，就说：“某某敌人要来了。”于是在国君的宫室外挖沟，说：“秦国将要袭击我国。”百姓害怕而溃散，秦国就趁机占取了梁国。', NULL, '', 'indent', 1558695300, '5ce75d02d5de2b00704869cd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642950, '左传 · 僖公 · 僖公二十年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十年春，新作南门。夏，郜子来朝。五月乙巳，西宫灾。郑人入滑。秋，齐人、狄人盟于邢。冬，楚人伐随。
【传】二十年春，新作南门。书，不时也。凡启塞从时。
滑人叛郑而服于卫。夏，郑公子士、泄堵寇帅师入滑。
秋，齐、狄盟于邢，为邢谋卫难也。于是卫方病邢。
随以汉东诸侯叛楚。冬，楚斗谷於菟帅师伐随，取成而还。君子曰：「随之见伐，不量力也。量力而动，其过鲜矣。善败由己，而由人乎哉？《诗》曰：『岂不夙夜，谓行多露。』」
宋襄公欲合诸侯，臧文仲闻之，曰：「以欲从人，则可；以人从欲，鲜济。」', '', '', '二十年春季，重新建造南门。《春秋》记载这件事，是由于妨碍农时。凡是修筑城门和制作门闩，应该不妨碍农时。
滑国人背叛郑国而顺服于卫国。夏季，郑国的公子士、泄堵寇率领军队攻入滑国。
秋季，齐国和狄人在邢国相会并订立盟约，为邢国策划对付卫国的侵袭。这时候卫国才担心邢国。
随国依靠汉水东边各诸侯的力量背叛楚国。冬季，楚国的鬬穀於菟率领军队进攻随国，讲和以后回国。君子说：“随国被攻打，是由于不估量自己的国力。估量自己的力量然后动作，祸害就少了。成败在于自己，难道在于别人？《诗》说：‘难道不想早晚奔波，无奈路上露水太多。’”
宋襄公想要会合诸侯。臧文仲听到了，说：“拿自己的愿望服从别人就可以，要使别人服从自己的愿望就很少有成功的。”
', NULL, '', 'indent', 1558695340, '5ce75d2a30863b0068d0f752', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642980, '左传 · 文公 · 文公十七年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有七年春，晋人、卫人、陈人、郑人伐宋。夏四月癸亥，葬我小君声姜。齐侯伐我西鄙。六月癸未，公及齐侯盟于谷。诸侯会于扈。秋，公至自谷。冬，公子遂如齐。
【传】十七年春，晋荀林父、卫孔达、陈公孙宁、郑石楚伐宋。讨曰：「何故弑君！」犹立文公而还，卿不书，失其所也。
夏四月癸亥，葬声姜。有齐难，是以缓。
齐侯伐我北鄙，襄仲请盟。六月，盟于谷。
晋侯蒐于黄父，遂复合诸侯于扈，平宋也。公不与会，齐难故也。书曰「诸侯」，无功也。
于是，晋侯不见郑伯，以为贰于楚也。
郑子家使执讯而与之书，以告赵宣子，曰：「寡君即位三年，召蔡侯而与之事君。九月，蔡侯入于敝邑以行。敝邑以侯宣多之难，寡君是以不得与蔡侯偕。十一月，克灭侯宣多而随蔡侯以朝于执事。十二年六月，归生佐寡君之嫡夷，以请陈侯于楚而朝诸君。十四年七月，寡君又朝，以蒇陈事。十五年五月，陈侯自敝邑往朝于君。往年正月，烛之武往朝夷也。八月，寡君又往朝。以陈、蔡之密迩于楚而不敢贰焉，则敝邑之故也。虽敝邑之事君，何以不免？在位之中，一朝于襄，而再见于君。夷与孤之二三臣相及于绛，虽我小国，则蔑以过之矣。今大国曰：『尔未逞吾志。』敝邑有亡，无以加焉。古人有言曰：『畏首畏尾，身其馀几。』又曰：『鹿死不择音。』小国之事大国也，德，则其人也；不德，则其鹿也，铤而走险，急何能择？命之罔极，亦知亡矣。将悉敝赋以待于鯈，唯执事命之。
文公二年六月壬申，朝于齐。四年二月壬戌，为齐侵蔡，亦获成于楚。居大国之间而从于强令，岂其罪也。大国若弗图，无所逃命。」
晋巩朔行成于郑，赵穿、公婿池为质焉。
秋，周甘蜀败戎于垂，乘其饮酒也。
冬十月，郑大子夷、石楚为质于晋。
襄仲如齐，拜谷之盟。复曰：「臣闻齐人将食鲁之麦。以臣观之，将不能。齐君之语偷。臧文仲有言曰：『民主偷必死』。」
', '', '', '十七年春季，晋国荀林父、卫国孔达、陈国公孙宁、郑国石楚联军攻打宋国，质问说：“为什么杀死你们国君？”还是立了宋文公而回国。《春秋》没有记载卿的姓名，这是由于他们改变初衷。
夏季，四月初四日，安葬声姜。由于有齐国攻战造成的困难，因此推迟。
齐懿公攻打我国北部边境，襄仲请求结盟。六月，在穀地结盟。
晋灵公在黄父阅兵，就因此再次在扈地会合诸侯，这是为了和宋国讲和。鲁文公没有参加会合，这是由于发生了齐国征战造成的困难的缘故。《春秋》记载说“诸侯”而不记名字，这是讥讽他们并没有取得成效。
当时，晋灵公拒绝会见郑穆公，以为他背晋而亲楚。郑国的子家派通信使者去晋国，并且给他一封信，告诉赵宣子，说：我郑国国君即位三年，召了蔡侯和他一起事奉贵国君主。九月，蔡侯来到敝邑前去贵国。敝邑由于侯宣多造成的祸难，我君因此而不能和蔡侯一同前来。十一月，消灭了侯宣多，就随同蔡侯而向执事朝觐。十二年六月，归生辅佐我君的长子夷，到楚国请求陈侯一同朝见贵国君主。十四年七月，我君又向贵国君主朝见，以完成关于陈国的事情。十五年五月，陈侯从我国前去朝见贵国君主。去年正月，烛之武前去贵国，这是为了使夷前往朝见贵国君主。八月，我君又前去朝见。因陈、蔡两国紧紧挨着楚国而不敢对晋有二心，那是由于我们的缘故。为什么唯独我们这样事奉贵国君主，反而不能免于祸患呢？
我郑君在位期间，一次朝见贵国先君襄公，两次朝见现在的君主。夷和我的几个臣下紧接着到绛城来。我郑国虽然是个小国，却没有谁能比我国对贵国更有诚意了。如今大国说：“你没有能让我称心如意。”敝邑只有等待灭亡，也不能再增加一点什么了。古人有话说：“怕头怕尾，剩下来的身子还有多少？”又说：“鹿在临死前，顾不上选择庇护的地方。”小国事奉大国，如果大国以德相待，小国就会以人道相事奉；如果不是以德相待，那就会像鹿一样，狂奔走险，急迫的时候，哪里还能选择地方？贵国的命令没有止境，我们也知道面临灭亡了，只好准备派出敝邑全部的士兵在鯈地等待。该怎么办，就听凭您的命令吧！
我郑文公二年六月二十日，曾到齐国朝见。四年二月某一天，为齐国进攻蔡国，也和楚国取得讲和。处于齐、楚两个大国之间而屈从于强国的命令，这难道是我们的罪过吗？大国如果不加谅解，我们是没有地方可以逃避你们的命令了。晋国的巩朔到郑国讲和修好，赵穿，公婿池作为人质。
秋季，周朝的甘歜在邥垂打败戎人，一战取胜是由于趁着戎人正在喝酒而用兵。
冬季，十一月，郑国的太子夷、大夫石楚到晋国作为人质。
襄仲到齐国去，拜谢穀地的结盟。回来说：“下臣听说齐国人将要吃鲁国的麦子。据下臣看来，恐怕做不到。齐国国君的话极不严肃。臧文仲曾说过：‘百姓的主人说话不严肃，必然很快就会死。’”', '[{"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42c434a8757d5a0fb155", "shortContent": "本篇节选自《东周列国志》第三十四回。\n《东周列国志》，一百零八回。原名《新列国志》，由明代末期著名通俗文学家冯梦龙编写。清代乾隆年间，蔡元放对《新列国志》略作修订润色，并加以大量评点，改名为《东周列国志》，成为两百多年来最流行的本子。\n在众多的明清历史演义小说中，《东周列国志》是成就较高，影响较大的一部。它沿着《三国演义》开辟的道路，以一种“知往事，鉴来者”的反思精神，形象地再现了春秋战国时期纷纭...", "authors": ["沈伯俊"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558952665, '5ceb4a56c8959c0069dd1df6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642981, '左传 · 文公 · 文公十八年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有八年春王二月丁丑，公薨于台下。秦伯荦卒。夏五月戊戌，齐人弑其君商人。六月癸酉，葬我君文公。秋，公子遂、叔孙得臣如齐。冬十月，子卒。夫人姜氏归于齐。季孙行父如齐。莒弑其君庶其。
【传】十八年春，齐侯戒师期，而有疾，医曰：「不及秋，将死。」公闻之，卜曰：「尚无及期。」惠伯令龟，卜楚丘占之曰：「齐侯不及期，非疾也。君亦不闻。令龟有咎。」二月丁丑，公薨。
齐懿公之为公子也，与邴蜀之父争田，弗胜。及即位，乃掘而刖之，而使蜀仆。纳阎职之妻，而使职骖乘。
夏五月，公游于申池。二人浴于池，蜀以扑抶职。职怒。曰：「人夺女妻而不怒，一抶女庸何伤！」职曰：「与刖其父而弗能病者何如？」乃谋弑懿公，纳诸竹中。归，舍爵而行。齐人立公子元。
六月，葬文公。
秋，襄仲、庄叔如齐，惠公立故，且拜葬也。
文公二妃敬赢生宣公。敬赢嬖而私事襄仲。宣公长而属诸襄仲，襄仲欲立之，叔仲不可。仲见于齐侯而请之。齐侯新立而欲亲鲁，许之。
冬十月，仲杀恶及视而立宣公。书曰「子卒」，讳之也。仲以君命召惠伯。其宰公冉务人止之，曰：「入必死。」叔仲曰：「死君命可也。」公冉务人曰：「若君命可死，非君命何听？」弗听，乃入，杀而埋之马矢之中。公冉务人奉其帑以奔蔡，既而复叔仲氏。
夫人姜氏归于齐，大归也。将行，哭而过市曰：「天乎，仲为不道，杀适立庶。」市人皆哭，鲁人谓之哀姜。
莒纪公生大子仆，又生季佗，爱季佗而黜仆，且多行无礼于国。仆因国人以弑纪公，以其宝玉来奔，纳诸宣公。公命与之邑，曰：「今日必授。」季文子使司寇出诸竟，曰：「今日必达。」公问其故。季文子使大史克对曰：「先大夫臧文仲教行父事君之礼，行父奉以周旋，弗敢失队。曰：『见有礼于其君者，事之如孝子之养父母也。见无礼于其君者，诛之如鹰鸇之逐鸟雀也。』先君周公制《周礼》曰：『则以观德，德以处事，事以度功，功以食民。』作《誓命》曰：『毁则为贼，掩贼为藏，窃贿为盗，盗器为奸。主藏之名，赖奸之用，为大凶德，有常无赦，在《九刑》不忘。』行父还观莒仆，莫可则也。孝敬忠信为吉德，盗贼藏奸为凶德。夫莒仆，则其孝敬，则弑君父矣；则其忠信，则窃宝玉矣。其人，则盗贼也；其器，则奸兆也，保而利之，则主藏也。以训则昏，民无则焉。不度于善，而皆在于凶德，是以去之。
「昔高阳氏有才子八人，苍舒、隤岂、檮寅、大临、龙降、庭坚、仲容、叔达，齐圣广渊，明允笃诚，天下之民谓之八恺。高辛氏有才子八人，伯奋、仲堪、叔献、季仲、伯虎、仲熊、叔豹、季狸，忠肃共懿，宣慈惠和，天下之民谓之八元。此十六族也，世济其美，不陨其名，以至于尧，尧不能举。舜臣尧，举八恺，使主后土，以揆百事，莫不时序，地平天成。举八元，使布五教于四方，父义、母慈、兄友、弟共、子孝，内平外成。昔帝鸿氏有不才子，掩义隐贼，好行凶德，丑类恶物，顽嚚不友，是与比周，天下之民谓之浑敦。少嗥氏有不才子，毁信废忠，崇饰恶言，靖谮庸回，服谗蒐慝，以诬盛德，天下之民谓之穷奇。颛顼有不才子，不可教训，不知话言，告之则顽，舍之则嚚，傲很明德，以乱天常，天下之民谓之檮杌。此三族也，世济其凶，增其恶名，以至于尧，尧不能去。缙云氏有不才子，贪于饮食，冒于货贿，侵欲崇侈，不可盈厌，聚敛积实，不知纪极，不分孤寡，不恤穷匮，天下之民以比三凶，谓之饕餮。舜臣尧，宾于四门，流四凶族浑敦、穷奇、檮杌、饕餮，投诸四裔，以御魑魅。是以尧崩而天下如一，同心戴舜以为天子，以其举十六相，去四凶也。故《虞书》数舜之功，曰『慎徽五典，五典克从』，无违教也。曰『纳于百揆，百揆时序』，无废事也。曰『宾于四门，四门穆穆』，无凶人也。
舜有大功二十而为天子，今行父虽未获一吉人，去一凶矣，于舜之功，二十之一也，庶几免于戾乎！」
宋武氏之族道昭公子，将奉司城须以作乱。十二月，宋公杀母弟须及昭公子，使戴、庄、桓之族攻武氏于司马子伯之馆。遂出武、穆之族，使公孙师为司城，公子朝卒，使乐吕为司寇，以靖国人。', '', '', '十八年春季，齐懿公下达了出兵日期，不久就得了病。医生说：“过不了秋天就会死去。”鲁文公听说以后，占了个卜，说：“希望他不到发兵日期就死！”惠伯在占卜前把所要占卜的事情致告龟甲，卜楚丘占了个卜说：“齐懿公不到期而死，但不是由于生病；国君也听不到这件事了。致告龟甲的人有灾祸。”二月二十三日，鲁文公逝世。
齐懿公在做公子的时候，和邴歜的父亲争夺田地，没有得胜。等到即位以后，就掘出尸体而砍去他的脚，但又让邴歜为他驾车。夺取了阎职的妻子而又让阎职作他的骖乘。
夏季，五月，齐懿公在申池游玩。邴歜、阎职两个人在池子里洗澡，邴歜用马鞭打阎职。阎职发怒。邴歜说：“别人夺了你的妻子你不生气，打你一下，有什么妨碍？”阎职说：“比砍了他父亲的脚而不敢怨恨的人怎么样？”于是二人就一起策划，杀死了齐懿公，把尸体放在竹林里。回去，在宗庙里祭祀，摆好酒杯然后公然出走。齐国人立了公子元为国君。
六月，安葬鲁文公。
秋季，襄仲、庄叔去齐国，这是由于齐惠公即位，同时拜谢齐国前来参加葬礼。
鲁文公的第二个妃子敬嬴生了宣公。敬嬴受到宠爱，而私下结交襄仲。宣公年长，敬嬴把他嘱托给襄仲。襄仲要立他为国君，仲叔不同意，仲叔进见齐惠公。请求不要立宣公为国君。齐惠公新即位，想要亲近鲁国，同意了仲叔的请求。
冬季，十月，襄仲杀死了太子恶和他的弟弟视，拥立宣公为国君。《春秋》记载说“子卒”，这是为了隐讳真象。襄仲用国君的名义召见叔仲惠伯，惠伯的家臣头子公冉务人劝止他，说：“进去必定死。”叔仲说：“死于国君的命令是可以的。”公冉务人说：“如果是国君的命令，可以死；不是国君的命令，为什么听从？”叔仲不听，就进去了，襄仲把他杀死了而埋在马粪中间。公冉务人事奉叔仲的妻子儿女逃亡到蔡国，不久以后重新立了叔仲氏。
鲁文公夫人姜氏回到齐国，这是回娘家而不再回来了。她将要离开的时候，哭着经过集市，说：“天哪！襄仲无道，杀死了嫡子立庶子。”集市上的人都随着她哭泣，鲁国人称她为哀姜。
莒纪公生了太子仆，又生了季佗，喜爱季佗而废黜太子仆，而且在国内办了许多不合礼仪的事情。太子仆依靠国内人们的力量杀了纪公，拿了他的宝玉逃亡前来，送给鲁宣公。宣公命令给他城邑，说：“今天一定得给。”季文子让司寇把他赶出国境，说：“今天一定得彻底执行。”鲁宣公询问这样做的缘故。季文子让太史克回答说：先大夫臧文仲教导行父事奉国君的礼仪，行父根据它而应酬对答，不敢丢失。先大夫说：“见到对他的国君有礼的，事奉他，如同孝子奉养父母一样；见到对他的国君无礼的，诛戮他，如同鹰鹯追逐鸟雀一样。”先君周公制作《周礼》说：“礼仪用来观察德行，德行用来处置事情，事情用来衡量功劳，功劳用来取食于民。”又制作《誓命》说：“毁弃礼仪就是贼，窝藏贼人就是赃，偷窃财物就是盗，偷盗宝器就是奸。有窝赃的名声，利用奸人的宝器，这是很大的凶德，国家对此有规定的刑罚，不能赦免，记载在《九刑》之中，不能忘记。”行父仔细观察莒仆，没有可以效法的。孝敬、忠信是吉德，盗贼、赃奸，是凶德。这个莒仆，如果取法他的孝敬吧，那么他是杀了国君父亲的；取法他的忠信吧，那么他是偷窃了宝玉的。他这个人，就是盗贼；他的器物，就是赃证。如果保护这个人而用他的器物，那就是窝赃。以此来教育百姓，百姓就昏乱无所取法了。莒仆的这些表现都不能算好事，而都属于凶德，所以才把他赶走。
从前高阳氏有才能强的子孙八位：苍舒、隤？？、梼戭、大临、尨降、庭坚、仲容、叔达，他们中正、通达、宽宏、深远、明智、守信、厚道、诚实，天下的百姓称之为八恺。高辛氏有才能强的子孙八位：伯奋、仲堪、叔献、季仲、伯虎、仲熊、叔豹、季狸，他们忠诚、恭敬、勤谨、端美、周密、慈祥、仁爱、宽和，天下的百姓称之为八元。这十六个家族，世世代代继承他们的美德，没有丧失前世的声名，一直到尧的时代，但是尧没有能举拔他们。舜做了尧的臣下以后，举拔八恺，让他们担任管理土地的官职，处理各种事务，没有不顺当的，地上和天上都平和无事。又举拔八元，让他们在四方之国宣扬五种教化，父亲讲道义，母亲慈爱，哥哥友爱，弟弟恭敬，儿子孝顺，里里外外都平安无事。从前帝鸿氏有一个没有才能的儿子，掩蔽道义，包庇奸贼，喜欢办那些属于凶德的事情，把坏东西引为同类，那些愚昧奸诈的人，和他混在一起，天下的百姓称他为浑敦。少皞氏有一个没有才能的儿子，毁坏信义，废弃忠诚，花言巧语，惯听谗言，任用奸邪，造谣中伤，掩盖罪恶，诬陷盛德的人，天下的百姓称他为穷奇。颛顼氏有一个没有才能的儿子，没办法教训，不知道好话，他愚顽不灵，丢开他，他又刁恶奸诈，鄙视美德，搅乱上天的常道，天下的百姓称他为梼杌。这三个家族，世世代代继承他们的凶恶，加重了他们的坏名声，一直到尧的时代，但是尧没有能赶走他们。缙云氏有一个没有才能的儿子，追求吃喝，贪图财货，任性奢侈，不能满足，聚财积谷，没有限度，不分给孤儿寡妇，不周济穷人，天下的百姓把他和三凶相比，称他为饕餮。舜做了尧的臣下以后，开辟四方的城门，流放四个凶恶的家族，把浑敦、穷奇、梼杌、饕餮赶到四边荒远的地方，让他们去抵御妖怪。由于这样，尧死后而天下就像一个人一样，同心拥戴舜做天子，因为他举拔了十六相而去掉了四凶的缘故。所以《虞书》举出舜的功业，说“谨慎地发扬五典，五典就能服从他”，这是说没有错误的教导。说“放在许多事务之中，事务都能顺利”，这是说没有荒废的事务。说“开辟四方的城门，从远方来的宾客都恭敬肃穆”，这是说没有凶顽的人物。舜建立了二十种大功才成为天子，现在行父没有得到一个好人，但已经赶走一个凶顽的人了。与舜的功业相比，已是二十分之一，差不多可以免于罪过了吧！
宋国武氏的族人领着昭公的儿子，准备事奉司城须来发动叛乱。十二月，宋文公杀死了同胞兄弟须和昭公的儿子，让戴公、庄公、桓公的族人在司马子伯的宾馆里攻打武氏，于是就把武公、穆公的族人驱逐出境，派遣公孙师做司城。公子朝去世，派了乐吕做司寇，来安定国内的人心。', NULL, '', 'indent', 1558952709, '5ceb4a81a673f5006815b019', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642951, '左传 · 僖公 · 僖公二十一年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有一年春，狄侵卫。宋人、齐人、楚人盟于鹿上。夏，大旱。秋，宋公、楚子、陈侯、蔡侯、郑伯、许男、曹伯会于盂。执宋公以伐宋。冬，公伐邾。楚人使宜申来献捷。十有二月癸丑，公会诸侯盟于薄。释宋公。
【传】二十一年春，宋人为鹿上之盟，以求诸侯于楚。楚人许之。公子目夷曰：「小国争盟，祸也。宋其亡乎，幸而后败。」
夏，大旱。公欲焚巫兀。臧文仲曰：「非旱备也。修城郭，贬食省用，务穑劝分，此其务也。巫兀何为？天欲杀之，则如勿生；若能为旱，焚之滋甚。」公从之。是岁也，饥而不害。
秋，诸侯会宋公于盂。子鱼曰：「祸其在此乎！君欲已甚，其何以堪之？」于是楚执宋公以伐宋。
冬，会于薄以释之。子鱼曰：「祸犹未也，未足以惩君。」
任、宿、须句、颛臾，风姓也。实司大皞与有济之祀，以服事诸夏。邾人灭须句，须句子来奔，因成风也。成风为之言于公曰：「崇明祀，保小寡，周礼也；蛮夷猾夏，周祸也。若封须句，是崇皞、济而修祀，纾祸也。」', '', '', '二十一年春季，宋国和齐国人、楚国人在鹿上举行了会盟，便向楚国要求当时归附楚国的中原诸侯奉自己为盟主，楚国人答应了。公子目夷说：“小国争当盟主，这是灾祸。宋国或许会被灭亡吧！失败得晚一点，就算运气了。”
夏季，很久没有下雨，干旱得很。僖公要烧死巫人和仰面朝天的怪人。臧文仲说：“这不是解决旱灾的办法。修理城墙、节用饮食、节省开支、致力农事、劝人施舍，这是应该做的。巫人、仰面朝天的怪人能做什么？上天要杀他们，就应当不生他们；如果他们能造成旱灾，烧死他们会更厉害。”僖公听从了。这一年，虽有饥荒，却没有伤害百姓。
秋季，楚成王、陈穆公、蔡庄公、郑文公、许僖公、曹共公在盂地会见宋襄公。子鱼说：“祸根子就在这里吧！国君的欲望太过分，那怎能忍受得了？”在会上楚国抓住了宋襄公来攻打宋国。
冬季，诸侯在薄地会盟，释放了宋襄公。子鱼说：“祸殃还没有完，这点够不上惩罚国君。”
任国、宿国、须句、颛臾，都姓风，主管太皞和济水神的祭祀，而服从中原各国。邾国人灭亡了须句，须句君逃亡到鲁国来，这是由于须句是成风的娘家。成风对僖公说：“尊崇明祀，保护弱小，这是周的礼仪；蛮夷扰乱中原，这是周的祸患。如果封了须句国的爵位，这是尊崇太皞、济水神而修明祭祀和缓解祸患啊。”', NULL, '', 'indent', 1558695378, '5ce75d5043e78c0067e36812', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642952, '左传 · 僖公 · 僖公二十二年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有二年春，公伐邾，取须句。夏，宋公、卫侯、许男、滕子伐郑。秋八月丁未，及邾人战于升陉。冬十有一月己巳朔，宋公及楚人战于泓，宋师败绩。
【传】二十二年春，伐邾，取须句，反其君焉，礼也。
三月，郑伯如楚。
夏，宋公伐郑。子鱼曰：「所谓祸在此矣。」
初，平王之东迁也，辛有适伊川，见被发而祭于野者，曰：「不及百年，此其戎乎！其礼先亡矣。」秋，秦、晋迁陆浑之戎于伊川。
晋大子圉为质于秦，将逃归，谓嬴氏曰：「与子归乎？」对曰：「子，晋大子，而辱于秦，子之欲归，不亦宜乎？寡君之使婢子侍执巾栉，以固子也。从子而归，弃君命也。不敢从，亦不敢言。」遂逃归。
富辰言于王曰：「请召大叔。《诗》曰：『协比其邻，昏姻孔云。』吾兄弟之不协，焉能怨诸侯之不睦？」王说。王子带自齐复归于京师，王召之也。
邾人以须句故出师。公卑邾，不设备而御之。臧文仲曰：「国无小，不可易也。无备，虽众不可恃也。《诗》曰：『战战兢兢，如临深渊，如履薄冰。』又曰：『敬之敬之，天惟显思，命不易哉！』先王之明德，犹无不难也，无不惧也，况我小国乎！君其无谓邾小。蜂虿有毒，而况国乎？」弗听。
八月丁未，公及邾师战于升陉，我师败绩。邾人获公胄，县诸鱼门。
楚人伐宋以救郑。宋公将战，大司马固谏曰：「天之弃商久矣，君将兴之，弗可赦也已。」弗听，
冬十一月己巳朔，宋公及楚人战于泓。宋人既成列，楚人未既济。司马曰：「彼众我寡，及其未既济也请击之。」公曰：「不可。」既济而未成列，又以告。公曰：「未可。」既陈而后击之，宋师败绩。公伤股，门官歼焉。
国人皆咎公。公曰：「君子不重伤，不禽二毛。古之为军也，不以阻隘也。寡人虽亡国之馀，不鼓不成列。」子鱼曰：「君未知战。勍敌之人隘而不列，天赞我也。阻而鼓之，不亦可乎？犹有惧焉。且今之勍者，皆吾敌也。虽及胡《老司》，获则取之，何有于二毛？明耻教战，求杀敌也，伤未及死，如何勿重？若受重伤，则如勿伤；爱其二毛，则如服焉。三军以利用也，金鼓以声气也。利而用之，阻隘可也；声盛致志，鼓儳可也。」
丙子晨，郑文夫人芈氏、姜氏劳楚子于柯泽。楚子使师缙示之俘馘。君子曰：「非礼也。妇人送迎不出门，见兄弟不逾阈，戎事不迩女器。」
丁丑，楚子入飨于郑，九献，庭实旅百，加笾豆六品。飨毕，夜出，文芈送于军，取郑二姬以归。叔詹曰：「楚王其不没乎！为礼卒于无别，无别不可谓礼，将何以没？」诸侯是以知其不遂霸也。', '', '', '二十二年春季，鲁国讨伐邾国，占领须句，护送须句的国君回国，这是符合礼的。
三月，郑文公到楚国去。
夏季，宋襄公进攻郑国。子鱼说：“所说的祸乱就在这里了。”
当初，周平王向东迁都洛阳的时候，辛有到了伊川，见到披着头发在野外祭祀的人，说：“不到一百年，这里就要变成戎人居住的地方了！它的礼仪先就消失了。”秋季，秦国和晋国把陆浑之戎迁到伊川。
晋国的太子圉在秦国作人质，准备逃回晋国，对嬴氏说：“跟你一起回去么？”嬴氏说：“你是晋国的太子而屈居在秦国。你想回去，不也很应该吗？我国君主让婢子侍候你，为你捧着手巾梳子，是为了使你安心，跟你回去，就丢弃了国君的命令。我不敢跟从，也不敢泄露。”太子圉就逃回晋国。富辰对周襄王说：“请您把太叔召回来。《诗》说：‘和他的邻居融洽，姻亲才能友好。’我国兄弟都不融洽，哪里能埋怨诸侯的不顺服？”周襄王听了很高兴。王子带从齐国回到京师，这是周襄王把他召回来的。
邾人由于鲁国帮助须句的缘故出兵攻打鲁国。僖公轻视邾国，不作准备便去抵御。臧文仲说：“国家无所谓弱小，不能轻视。没有准备，人虽然众多，还是不足依靠的。《诗》说：‘战战兢兢，如同面向深渊，如同踩着薄冰。’又说：‘谨慎又谨慎，上天光明普照，得到上天保佑不容易啊！’以先王的美德，还没有不困难、没有不戒惧的，何况我们小国呢？君王不要认为邾国弱小，黄蜂、蝎子都有毒，何况一个国家呢？”僖公不听。八月初八日，僖公率军与邾军在升陉作战，我军大败。邾军获得僖公的头盔，挂在鱼门上。
楚人进攻宋国以救援郑国。宋襄公准备应战，大司马固劝阻说：“上天丢弃我们商朝后代已经很久了，您想复兴它，这是违背上天而不能被赦免的。”宋襄公不听。
冬季，十一月初一日，宋襄公与楚国人在泓水边上作战。宋军已经排成队列，楚军还没有全部渡过河。司马说：“他们兵多，我们兵少，趁他们没有全部渡过河的时候，请君王下令攻击他们。”宋襄公说：“不行。”楚军渡过河以后还没有排开阵势，司马又把刚才的情况报告宋襄公。宋襄公说：“还不行。”等楚军摆开阵势然后才攻击他们，宋军被打得大败，宋襄公大腿后受箭伤，跟随宋襄公的卿大夫子弟任护卫的被歼灭。都城里的人都责怪宋襄公。宋襄公说：“君子不两次伤害敌人，不擒捉头发花白的敌人。古代的作战，不靠关塞险阻取胜。寡人虽然是殷商亡国的后裔，不攻击没有摆开阵势的敌人。”子鱼说：“国君不懂战争。强大的敌人，由于地形狭隘而没有摆开阵势，这是上天在帮助我，把他们拦截而攻击，不也是可以的吗？可是还害怕不能取胜。现在强大的国家，都是我们的敌人，虽然是老头子，捉了也不能放，管什么头发花白不花白。说明国家耻辱是什么，以此教导士兵作战，目的就是为了多杀敌人。敌人受伤而没有死，为什么不可以再次打击他一次？如果爱惜敌人伤员而不再打击，就应该一开始就不伤害他；爱惜那些头发花白的人，就不如向他们投降。军队，由于有利才加以使用；战鼓雷鸣，是用声音来激励士气。有利而使用，在狭路攻击是可以的；鼓声大作鼓舞了士气，攻击没有摆开阵势的敌人也是可以的。”
十一月初八日早晨，郑文公夫人芈氏、姜氏在柯泽慰劳楚成王。楚成王派师缙把俘虏和被杀死的敌人的左耳给他们看。君子说：“这是不合于礼的。女人送迎不出房门，和兄弟相见不出门槛，打仗时不接近女人的用具。”初九日，楚成王进入郑国接受享礼，主人敬酒九次，庭院里陈列的礼品有一百件，另外再加笾豆礼品六件。宴请完毕，夜里出来，文芈送他到军营里。楚成王带了郑国的两个侍妾回去。叔詹说：“楚成王恐怕不得寿终正寝吧！执行礼节而最后至于男女混杂。男女混杂不能认为合于礼，他将怎么能得到好死？”所以诸侯知道楚成王不能完成霸业。', NULL, '', 'indent', 1558695418, '5ce75d7730863b0068d0fddf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642953, '左传 · 僖公 · 僖公二十三年 ', NULL, 3, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有三年春，齐侯伐宋，围婚。夏五月庚寅，宋公兹父卒。秋，楚人伐陈。冬十有一月，杞子卒。
【传】二十三年春，齐侯伐宋，围缗，以讨其不与盟于齐也。
夏五月，宋襄公卒，伤于泓故也。
秋，楚成得臣帅师伐陈，讨其贰于宋也。遂取焦、夷，城顿而还。子文以为之功，使为令尹。叔伯曰：「子若国何？」对曰：「吾以靖国也。夫有大功而无贵仕，其人能靖者与有几？」
九月，晋惠公卒。怀公命无从亡人。期，期而不至，无赦。狐突之子毛及偃从重耳在秦，弗召。冬，怀公执狐突曰：「子来则免。」对曰：「子之能仕，父教之忠，古之制也。策名委质，贰乃辟也。今臣之子，名在重耳，有年数矣。若又召之，教之贰也。父教子贰，何以事君？刑之不滥，君之明也，臣之愿也。淫刑以逞，谁则无罪？臣闻命矣。」乃杀之。
卜偃称疾不出，曰：「《周书》有之：『乃大明服。』己则不明而杀人以逞，不亦难乎？民不见德而唯戮是闻，其何后之有？」
十一月，杞成公卒。书曰「子」，杞，夷也。不书名，未同盟也。凡诸侯同盟，死则赴以名，礼也。赴以名，则亦书之，不然则否，辟不敏也。
晋公子重耳之及于难也，晋人伐诸蒲城。蒲城人欲战。重耳不可，曰：「保君父之命而享其生禄，于是乎得人。有人而校，罪莫大焉。吾其奔也。」遂奔狄。从者狐偃、赵衰、颠颉、魏武子、司空季子。狄人伐啬咎如，获其二女：叔隗、季隗，纳诸公子。公子取季隗，生伯儵、叔刘，以叔隗妻赵衰，生盾。将适齐，谓季隗曰：「待我二十五年，不来而后嫁。」对曰：「我二十五年矣，又如是而嫁，则就木焉。请待子。」处狄十二年而行。
过卫。卫文公不礼焉。出于五鹿，乞食于野人，野人与之块，公子怒，欲鞭之。子犯曰：「天赐也。」稽首，受而载之。
及齐，齐桓公妻之，有马二十乘，公子安之。从者以为不可。将行，谋于桑下。蚕妾在其上，以告姜氏。姜氏杀之，而谓公子曰：「子有四方之志，其闻之者吾杀之矣。」公子曰：「无之。」姜曰：』行也。怀与安，实败名。」公子不可。姜与子犯谋，醉而遣之。醒，以戈逐子犯。
及曹，曹共公闻其骈胁。欲观其裸。浴，薄而观之。僖负羁之妻曰：「吾观晋公子之从者，皆足以相国。若以相，夫子必反其国。反其国，必得志于诸侯。得志于诸侯而诛无礼，曹其首也。子盍蚤自贰焉。」乃馈盘飨，置璧焉。公子受飨反璧。
及宋，宋襄公赠之以马二十乘。
及郑，郑文公亦不礼焉。叔詹谏曰：「臣闻天之所启，人弗及也。晋公子有三焉，天其或者将建诸，君其礼焉。男女同姓，其生不蕃。晋公子，姬出也，而至于今，一也。离外之患，而天不靖晋国，殆将启之，二也。有三士足以上人而从之，三也。晋、郑同侪，其过子弟，固将礼焉，况天之所启乎？」弗听。
及楚，楚之飨之，曰：「公子若反晋国，则何以报不谷？」对曰：「子女玉帛则君有之，羽毛齿革则君地生焉。其波及晋国者，君之馀也，其何以报君？」曰：「虽然，何以报我？」对曰：「若以君之灵，得反晋国，晋、楚治兵，遇于中原，其辟君三舍。若不获命，其左执鞭弭、右属櫜健，以与君周旋。」子玉请杀之。楚子曰：「晋公子广而俭，文而有礼。其从者肃而宽，忠而能力。晋侯无亲，外内恶之。吾闻姬姓，唐叔之后，其后衰者也，其将由晋公子乎。天将兴之，谁能废之。违天必有大咎。」乃送诸秦。秦伯纳女五人，怀嬴与焉。奉也活盥，既而挥之。怒曰：「秦、晋匹也，何以卑我！」公子惧，降服而囚。
他日，公享之。子犯曰：「吾不如衰之文也。请使衰从。公子赋《河水》，公赋《六月》。赵衰曰：「重耳拜赐。」公子降，拜，稽首，公降一级而辞焉。衰曰：「君称所以佐天子者命重耳，重耳敢不拜。」
', '', '', '二十三年春季，齐孝公发兵进攻宋国，包围缗地，讨伐宋国不到齐国参加会盟。
夏季，五月，宋襄公死，这是由于在泓地战役中受伤的缘故。
秋季，楚国的成得臣领兵进攻陈国，讨伐陈国倾向宋国。于是占领了焦、夷两地，在顿地筑城后回国。子文把这些作为他的功劳，让他做令尹。叔伯说：“您打算把国家怎么办？”子文回答说：“我是用这个来安定国家的。有了大功而不居高位，这样的人能够安定国家的有几个？”
九月，晋惠公死了。怀公即位，命令臣民不准跟随逃亡在外的人。规定了期限，不回来的不赦免。狐突的儿子毛和偃跟随重耳在秦国，不肯召他们回国。怀公抓住狐突，说：“儿子回来就赦免。”狐突回答说：“当儿子能够做官，父亲教他懂得忠诚的道理，这是古代的制度。名字写在简策上，给主子送了进见的礼物，如果三心二意就是罪过。现在下臣的儿子，名字在重耳那里已经有年头了，如果又召他回来，这是教他三心二意。父亲教儿子三心二意，用什么来事奉国君？刑罚的不滥用，这是君主的贤明，下臣的愿望。滥用刑罚以图快意，谁能没有罪？下臣知道您的意思了。”晋怀公于是杀了狐突。卜偃推说有病不出门，说：“《周书》上有这样的话：‘君主伟大贤明臣民然后顺服。’自己如果不贤明，反而杀人以图快意，不也很难办事吗？百姓看不到德行，反而只听到杀戮，哪里还能有什么后代？”
十一月，杞成公去世。《春秋》记载称“子”，因为杞是夷人。不记载名字，是由于没有和鲁国结过盟的缘故。凡是同盟的诸侯，死后就在讣告上写上名字，这是合于礼的。讣告上写上名字，《春秋》就加以记载，否则就不记载，这是为了避免弄不清楚而误记。
晋公子重耳遭到祸难的时候，晋献公的军队在蒲城攻打他。蒲城人想要迎战，重耳不肯，说：“仰仗着国君父亲的恩宠而享有奉养自己的俸禄，因此才得到百姓的拥护。有百姓的拥护而反抗，没有比这再大的罪过了。我还是逃亡吧。”于是就逃亡到狄人那里，跟随的有狐偃、赵衰、颠颉、魏武子、司空季子。狄人攻打廧咎如，俘虏了他两个女儿叔隗、季隗，送给公子。公子娶了季隗，生了伯儵、叔刘。把叔隗嫁给赵衰，生了盾。公子要到齐国去，对季隗说：“等我二十五年，不回来再改嫁。”季隗回答说：“我已经二十五岁了，又再过二十五年改嫁，我就要进棺材了。我等您。”公子在狄一共住了十二年，然后离开。经过卫国，卫文公不以礼来待他。
经过五鹿时，向乡下人要饭。乡下人给他一块泥土。公子发怒，要鞭打他。子犯说：“这是上天赐与的啊！”公子叩着头接受，把泥土装上车子。
重耳到达齐国，齐桓公也给他娶妻，有马八十匹。公子安于齐国的生活。跟随的人认为这样不行，准备离去，在桑树下商量。养蚕的侍妾正好在树上听到，把这事告诉姜氏。姜氏杀了她，告诉公子说：“您有远大的志向，听到的人，我已经杀了。”公子说：“没有这回事。”姜氏说：“走吧！留恋妻子和贪图安逸，实在会有损前途。”公子不肯。姜氏和子犯商量，灌醉了公子，然后打发他走。公子酒醒，拿起长戈追逐子犯。
重耳到达曹国，曹共公听说他的肋骨排比很密，似乎并成一整块，想从他裸体中看个真相。乘重耳洗澡，他就在帘子外观看。僖负羁的妻子对负羁说：“我看晋公子的随从人员，都足以辅助国家。如果用他们作辅助，晋公子必定能回晋国做国君。回到晋国，肯定在诸侯中称霸。在诸侯中称霸而惩罚对他无礼的国家，曹国就是第一个。您何不早一点向他表示好感呢！”僖负羁于是就向晋公子馈送一盘食品，里边藏着璧玉。公子接受食品，退回璧玉。
重耳到达宋国，宋襄公把马八十匹送给他。到达郑国，郑文公也不加礼遇。叔詹劝谏说：“臣听说上天所赞助的人，别人就赶不上了。晋公子具有三条，上天或者将要立他为国君吧，您最好还是以礼相待。父母同姓，子孙不能昌盛。晋公子是姬姓女子生的，所以能活到今天，这是一。经受逃亡在外的忧患，而上天使晋国不安定，大概是将要赞助他了，这是二。有三个人足以居于别人之上，却一直跟随着他，这是三。晋国和郑国地位平等，他们的子弟路过还应当以礼相待，何况是上天所赞助的呢？”郑文公没有听叔詹的劝谏。
重耳到达楚国，楚成王设宴会招待他，说：“公子如果回到晋国，用什么报答我？”公子回答说：“子、女、玉、帛都是君王所拥有的，鸟羽、皮毛、象牙、犀革都是君王土地上所生长的。那些波及晋国的，已经是君王剩馀的了，我能用什么来报答君王呢？”楚成王说：“尽管这样，究竟用什么报答我？”公子回答说：“如果托君王的福，能够回到晋国，一旦晋、楚两国演习军事，在中原相遇，那就后退九十里。如果还得不到君王的宽大，那就左手执鞭执弓，右边挂着弓袋箭袋，跟君王较量一下。”子玉请求楚王杀掉他。楚成王说：“晋公子志向远大而生活俭约，文辞华美而合乎礼仪。他的随从严肃而宽大，忠诚又有能力。晋侯没有亲近的人，国内国外都讨厌他。我听说姬姓是唐叔后代，将会最后衰亡，这恐怕是从晋公子为君以后的缘故吧！上天将要使他兴起，谁能够废掉他？违背上天，必然有大灾。”于是就把他送回秦国。
秦穆公送给重耳五个女子，怀嬴也在内。怀嬴捧着盛水的器皿伺候重耳洗脸，他洗了手不用手巾擦手，而挥挥手把手上的水甩干。怀嬴很生气，说：“秦、晋两国地位平等，为什么轻视我？”公子害怕，脱去上衣自囚表示谢罪。有一天，秦穆公设宴席招待重耳，子犯说：“我不如赵衰那样有文采，请您让赵衰跟随赴宴。”公子在宴会上赋《河水》这首诗，秦穆公赋《六月》这首诗。赵衰说：“重耳拜谢恩赐！”公子退到阶下，拜，叩头，秦穆公走下一级台阶辞谢。赵衰说：“君王把所以辅助天子的事命令重耳，重耳岂敢不拜？”', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b65b5c98d685fd9d8d62a", "shortContent": "这篇文字是《左传》中的精品，也是中国史学史和文学史上的名篇。它非常具体、详尽、真实地记载了晋公子重耳自骊姬之乱后流亡国外十九年，最后回国执政的全过程。重耳即晋文公，晋文公称霸是春秋时期的重大历史事件，而这篇文字记述的史实则构成了晋文公霸业的前奏，因而具有很高的史学价值。《左传》在讲述这段历史的时候，不是平铺直叙地记录历史现象，而是以人物为中心剪裁史料。《左传》本来是编年体历史著作，一般是按照时间顺...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558951499, '5ceb45c030863b0068265f66', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642954, '左传 · 僖公 · 僖公二十四年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有四年春王正月。夏，狄伐郑。秋七月。冬，天王出居于郑。晋侯夷吾卒。
【传】二十四年春，王正月，秦伯纳之，不书，不告入也。
及河，子犯以璧授公子，曰：「臣负羁绁从君巡于天下，臣之罪甚多矣。臣犹知之，而况君乎？请由此亡。」公子曰：「所不与舅氏同心者，有如白水。」投其璧于河。济河，围令狐，入桑泉，取臼衰。二月甲午，晋师军于庐柳。秦伯使公子絷如晋师，师退，军于郇。辛丑，狐偃及秦、晋之大夫盟于郇。壬寅，公子入于晋师。丙午，入于曲沃。丁未，朝于武宫。戊申，使杀怀公于高梁。不书，亦不告也。吕、郤畏逼，将焚公宫而弑晋侯。寺人披请见，公使让之，且辞焉，曰：「蒲城之役，君命一宿，女即至。其后余从狄君以田渭滨，女为惠公来求杀余，命女三宿，女中宿至。虽有君命，何其速也。夫祛犹在，女其行乎。」对曰：「臣谓君之入也，其知之矣。若犹未也，又将及难。君命无二，古之制也。除君之恶，唯力是视。蒲人、狄人，余何有焉。今君即位，其无蒲、狄乎？齐桓公置射钩而使管仲相，君若易之，何辱命焉？行者甚众，岂唯刑臣。」公见之，以难告。三月，晋侯潜会秦伯于王城。己丑晦，公宫火，瑕甥、郤芮不获公，乃如河上，秦伯诱而杀之。晋侯逆夫人嬴氏以归。秦伯送卫于晋三千人，实纪纲之仆。
初，晋侯之竖头须，守藏者也。其出也，窃藏以逃，尽用以求纳之。及入，求见，公辞焉以沐。谓仆人曰：「沐则心覆，心覆则图反，宜吾不得见也。居者为社稷之守，行者为羁绁之仆，其亦可也，何必罪居者？国君而仇匹夫，惧者甚众矣。」仆人以告，公遽见之。
狄人归季隗于晋而请其二子。文公妻赵衰，生原同、屏括、搂婴。赵姬请逆盾与其母，子余辞。姬曰：「得宠而忘旧，何以使人？必逆之！」固请，许之，来，以盾为才，固请于公以为嫡子，而使其三子下之，以叔隗为内子而己下之。
晋侯赏从亡者，介之推不言禄，禄亦弗及。推曰「献公之子九人，唯君在矣。惠、怀无亲，外内弃之。天未绝晋，必将有主。主晋祀者，非君而谁？天实置之，而二三子以为己力，不亦诬乎？窃人之财，犹谓之盗，况贪天之功以为己力乎？下义其罪，上赏其奸，上下相蒙，难与处矣！」其母曰：「盍亦求之，以死谁怼？」对曰：「尤而效之，罪又甚焉，且出怨言，不食其食。」其母曰：「亦使知之若何？」对曰：「言，身之文也。身将隐，焉用文之？是求显也。」其母曰：「能如是乎？与女偕隐。」遂隐而死。晋侯求之，不获，以绵上为之田，曰：「以志吾过，且旌善人。」
郑之入滑也，滑人听命。师还，又即卫。郑公子士、泄堵俞弥帅师伐滑。王使伯服、游孙伯如郑请滑。郑伯怨惠王之入而不与厉公爵也，又怨襄王之与卫、滑也，故不听王命而执二子。王怒，将以狄伐郑。富辰谏曰：「不可。臣闻之，大上以德抚民，其次亲亲以相及也。昔周公吊二叔之不咸，故封建亲戚以蕃屏周。管蔡郕霍，鲁卫毛聃，郜雍曹滕，毕原酆郇，文之昭也。邗晋应韩，武之穆也。凡蒋刑茅胙祭，周公之胤也。召穆公思周德之不类，故纠合宗族于成周而作诗，曰：『常棣之华，鄂不□韦□韦，凡今之人，莫如兄弟。』其四章曰：『兄弟阋于墙，外御其侮。』如是，则兄弟虽有小忿，不废懿亲。今天子不忍小忿以弃郑亲，其若之何？庸勋亲亲，昵近尊贤，德之大者也。即聋从昧，与顽用嚚，奸也大者也。弃德崇奸，祸之大者也。郑有平、惠之勋，又有厉、宣之亲，弃嬖宠而用三良，于诸姬为近，四德具矣。耳不听五声之和为聋，目不别五色之章为昧，心不则德义之经为顽，口不道忠信之言为嚚，狄皆则之，四奸具矣。周之有懿德也，犹曰『莫如兄弟』，故封建之。其怀柔天下也，犹惧有外侮，扞御侮者莫如亲亲，故以亲屏周。召穆公亦云。今周德既衰，于是乎又渝周、召以从诸奸，无乃不可乎？民未忘祸，王又兴之，其若文、武何？」王弗听，使颓叔、桃子出狄师。夏，狄伐郑，取栎。
王德狄人，将以其女为后。富辰谏曰：「不可。臣闻之曰：『报者倦矣，施者未厌。』狄固贪淋，王又启之，女德无极，妇怨无终，狄必为患。」王又弗听。
初，甘昭公有宠于惠后，惠后将立之，未及而卒。昭公奔齐，王复之，又通于隗氏。王替隗氏。颓叔、桃子曰：「我实使狄，狄其怨我。」遂奉大叔，以狄师攻王。王御士将御之。王曰：「先后其谓我何？宁使诸。侯图之。璲出。及坎□，国人纳之。
秋，颓叔、桃子奉大叔，以狄师伐周，大败周师，获周公忌父、原伯、毛伯、富辰。王出适郑，处于汜。大叔以隗氏居于温。
郑子华之弟子臧出奔宋，好聚鹬冠。郑伯闻而恶之，使盗诱之。八月，盗杀之于陈、宋之间。君子曰：「服之不衷，身之灾也。《诗》曰：『彼己之子，不称其服。』子臧之服，不称也夫。《诗》曰，『自诒伊戚』，其子臧之谓矣。《夏书》曰，『地平天成』，称也。」
宋及楚平。宋成公如楚，还入于郑。郑伯将享之，问礼于皇武子。对曰：「宋，先代之后也，于周为客，天子有事膰焉，有丧拜焉，丰厚可也。」郑伯从之，享宋公有加，礼也。
冬，王使来告难曰：「不谷不德，得罪于母弟之宠子带，鄙在郑地汜，敢告叔父。」臧文仲对曰：「天子蒙尘于外，敢不奔问官守。」王使简师父告于晋，使左鄢父告于秦。天子无出，书曰「天王出居于郑」，辟母弟之难也。天子凶服降名，礼也。郑伯与孔将锄、石甲父、侯宣多省视官具于汜，而后听其私政，礼也。
卫人将伐邢，礼至曰：「不得其守，国不可得也。我请昆弟仕焉。」乃往，得仕。', '', '', '二十四年春季，周王朝历法的正月，秦穆公把公子重耳送回晋国。《春秋》没有记载这件事，因为晋国没有向鲁国报告重耳回晋国的事。到达黄河岸边，子犯把玉璧还给公子，说：“下臣背着马笼头马缰绳跟随您在天下巡行，下臣的罪过很多，下臣自己尚且知道，何况您呢？请您让我从这里走开吧。”公子说：“如果不和舅父同一条心，有河神作证。”把他的璧玉扔到了黄河里。
重耳等一行渡过黄河，包围了令狐，进入桑泉，占取了臼衰。二月的一天， 晋国的军队驻扎在庐柳。秦穆公派遣公子絷到晋国军队里去交涉。晋军退走，驻扎在郇地。又一天，狐偃和秦国、晋国的大夫在郇地结盟。又一天，公子重耳到达晋国军队里。又一天，重耳进入曲沃。又一天，重耳在晋武公的庙宇中朝见群臣。又一天，重耳派人在高梁杀死了晋怀公。《春秋》没有记载这件事，也是由于晋国没有来鲁国报告的缘故。
吕、郤两家害怕祸难逼近，准备焚烧宫室而杀死晋文公。寺人披请求进见。晋文公派人责备他，而且拒绝接见，说：“蒲城那一次战役，国君命令你一个晚上到达，你马上就来了。后来我跟随狄君在渭水边上打猎，你为惠公来杀我，惠公命令你过三个晚上再来，你过两个晚上就来了。虽然有国君的命令，为什么那么快呢？那只被割断的袖子还在，你还是走开吧！”寺人披回答说：“小臣原来认为国君回国以后，已经了解情况了。如果还没有，就会又一次遇到祸难。执行国君的命令只有一心一意，这是古代的制度。除去国君所厌恶的人，只看自己有多大力量。蒲人、狄人，对我来说算什么呢？现在您即位做国君，也会同我心目中一样没有蒲、狄吧！齐桓公把射钩的事故在一边，而让管仲辅助他。君王如果改变这种做法，我会自己走的，哪里需要君王的命令呢？离开的人很多，岂独是我受过宫刑的小臣？”晋文公接见了寺人披，寺人披就把祸乱告诉了晋文公。三月，晋文公秘密地和秦穆公在王城会见。三十日，文公的宫殿起火。瑕甥、郤芮找不到晋文公，于是就到黄河边上去找，秦穆公把他们诱去杀死了。晋文公迎接夫人嬴氏回国。秦穆公赠送给晋国卫士三千人，都是一些得力的臣仆。
当初，晋文公有个侍臣名叫头须，是专门管理财物的。当晋文公在国外的时候，头须偷盗了财物潜逃，把这些财物都用来设法让晋文公回国。没有成功，只好留在国内。等到晋文公回来，头须请求进见。晋文公推托说正在洗头。头须对仆人说：“洗头的时候心就倒过来，心倒了意图就反过来，无怪我不能被接见了。留在国内的人是国家的守卫者，跟随在外的是背着马笼头马缰绳的仆人，这也都是可以的，何必要怪罪留在国内的人？身为国君而仇视普通人，害怕的人就多了。”仆人把这些话告诉晋文公，晋文公立即接见了他。
狄人把季隗送回到晋国，而请求留下她的两个儿子。晋文公把女儿嫁给赵衰，生了原同、屏括、楼婴。赵姬请求迎接盾和他的母亲。赵衰辞谢不肯。赵姬说：“得到新宠而忘记旧好，以后还怎样使用别人？一定要把他们接回来。”坚决请求，赵衰同意了。叔隗和赵盾回来以后，赵姬认为赵盾有才，坚决向赵衰请求，把赵盾作为嫡子，而让她自己生的三个儿子居于赵盾之下，让叔隗作为正妻，而自己居于她之下。
晋文公赏赐跟随他逃亡的人，介之推没有提及禄位，禄位也没有赐到他身上。介之推说：“献公的儿子有九个，只有公子在世了。惠公、怀公没有亲近的人，国内国外都抛弃了他们。上天不使晋国绝后，必定会有君主。主持晋国祭祀的人，不是公子又会是谁？这实在是上天立他为君，而他们这些人却以为是自己的力量，这不是欺骗吗？偷别人的财物，尚且叫做盗，何况贪上天的功劳以为自己的力量呢？下面的人把贪功的罪过当成合理，上面的人对欺骗加以赏赐，上下相互欺骗，这就难和他们相处了。”介之推的母亲说：“为什么不也去求赏？这样的死，又能怨谁？”介之推回答说：“明知错误而去效法，罪就更大了。而且我口出怨言，不能吃他的俸禄。”他母亲说：“也让他知道一下，怎么样？”介之推回答说：“说话，是身体的文饰。身体将要隐藏，哪里用得着文饰？这只不过是去求显露罢了。”他母亲说：“你能够这样吗？我和你一起隐居起来。”于是就隐居而死。晋文公派人寻找介之推，找不到，就把绵上的田封给他，说：“用这来记载我的过失，来表扬好人。”
郑军进入滑国的时候，滑人听从命令。军队回去，滑国又亲附卫国。郑国的公子士、洩堵俞弥带兵进攻滑国。周襄王派伯服、游孙伯到郑国请求不要进攻滑国。郑文公怨恨周惠王回到成周而不给厉公饮酒礼器杯子，又怨恨周襄王偏袒卫、滑两国，所以不听周襄王的命令而逮捕了伯服和游孙伯。周襄王发怒，准备领着狄人进攻郑国。富辰劝谏说：“不行。下臣听说，最高的人用德行来安抚百姓，其次的亲近亲属，由近到远。从前周公叹息管叔、蔡叔不得善终，所以把土地分封给亲戚作为周朝的屏障。管、蔡、郕、霍、鲁、卫、毛、聃、郜、雍、曹、滕、毕、原、酆、郇各国，是文王的儿子。邢、晋、应、韩各国，是武王的儿子。凡、蒋、邢、茅、胙、祭各国，是周公的后代。召穆公忧虑周德衰微，所以集合了宗族在成周而做诗，说：‘小叶杨的花儿，花朵是那样漂亮艳丽，现在的人们，总不能亲近得像兄弟。’诗的第四章说：‘兄弟们在墙里争吵，一到墙外就共同对敌。’像这样，那么兄弟之间虽然有小不和睦，也不能废弃好亲属。现在您不忍耐小怨而丢弃郑国这门亲属，又能把它怎么办？酬答勋劳，亲近亲属，接近近臣，尊敬贤人，这是德行中的大德。靠拢耳背的人，跟从昏暗的人，赞成固陋的人，使用奸诈的人，这是邪恶中的大恶，抛弃德行，崇尚邪恶，这是祸患中的大祸。郑国有过辅助平王、惠王的勋劳，又有厉王、宣王的亲属关系，郑国国君舍弃宠臣而任用三个好人，在姬姓诸姓中属于近亲，四种德行都具备了。耳朵不能听到五声的唱和是耳聋，眼睛不能辨别五色的文饰是昏暗，心里不学德义的准则是顽固，嘴里不说忠信的话是奸诈。狄人效法这些，四种邪恶都具备了。周室具有美德的时候，尚且说‘总不能亲近得像兄弟’，所以分封建制。当它笼络天下的时候，尚且害怕有外界的侵犯；抵御外界侵犯的措施，没有比亲近亲属再好的了，所以用亲属作为周室的屏障。召穆公也是这样说的。现在周室的德行已经衰败，而这时又改变周公、召公的措施以跟从各种邪恶，恐怕不可以吧！百姓没有忘记祸乱，君王又把它挑起来，怎么来对待文王、武王呢？”周襄王不听，派遣颓叔、桃子出动狄军。
夏季，狄军进攻郑国，占领了栎地。
周襄王感谢狄人，准备把狄君的女儿做王后。富辰劝阻说：“不行。臣听说：‘报答的人已经厌倦了，施恩的人还没有满足。’狄人本来贪婪，而您又启发他们。女子的行为没有准则，妇人的怨恨没有终结，狄人必然成为祸患。”周襄王又不听。
当初，甘昭公受到惠后的宠爱，惠后打算立他为嗣君，没有来得及惠后就死去了。昭公逃亡到齐国，周天子让他回来，他又和隗氏私通。周天子废了隗氏。颓叔、桃子说：“狄人这样，是我们指使的，狄人可能会怨恨我们。”就奉戴大叔攻打周天子，周王的侍卫人员准备抵御，周王说：“如果杀死太
叔，先王后将会说我什么？宁可让诸侯来商量一下。”周王于是就离开成周，到达坎欿，都城里的人又把周王接回都城。秋季，颓叔、桃子奉事太叔领了狄人的军队进攻成周，把周军打得大败，俘虏了周公忌父、原伯、毛伯、富辰。周襄王离开成周去郑国，住在汜地。太叔和隗氏住在温地。
郑国子华的兄弟子臧逃亡到宋国，喜欢收集鹬毛帽子。郑文公听说后很讨厌他，指使杀手骗他出来。八月，杀手将子臧杀死在陈国和宋国交界的地方。君子说：“衣服的不合适，这是身体的灾祸。《诗》说：‘那一个人啊，和他的服饰不能相称。’子臧的服饰，就是不相称啊！《诗》说：‘自己给自己找来祸害。’子臧就是这样。《夏书》说：‘大地平静，上天成全。’这就是上下相称了。”
宋国和楚国讲和，宋成公到楚国。回国时，进入郑国。郑文公准备设宴招待他，向皇武子询问礼仪。皇武子回答说：“宋国是先朝的后代，在周朝来说是客人。周天子祭祀宗庙，要送给他祭肉；有了丧事，宋国国君来吊唁，周天子是要答拜的。丰盛地招待他是可以的。”郑文公听从皇武子的话，设享礼招待宋公，比常礼有所增加。这是合于礼的。
冬季，周襄王的使者前来报告发生的祸难，说：“不穀缺乏德行，得罪了母亲所宠爱的儿子带，现在僻处在郑国的汜地，谨敢将这件事情报告叔父。”臧文仲回答说：“天子在外边蒙受尘土，岂敢不赶紧去问候左右。”
周襄王派简师父向晋国报告，派左鄢父到秦国报告。天子无所谓出国，《春秋》记载说“天王出居于郑”，意思是由于躲避兄弟所造成的祸难。天子穿着素服，自称“不穀”，这是合于礼的。
郑文公和孔将锄、石甲父、侯宣多到汜地问候天子的官员和检查供应天子的用品，然后听取关于郑国的政事，这是合于礼的。
卫国人准备攻打邢国，卫大夫礼至说：“不和他们的大官接近，是难以得到他们的国家的。我请求让我的兄弟去邢国做官。”他们就前去邢国，并做了官。', NULL, '', 'indent', 1558951543, '5ceb45f3d5de2b007078e68a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642955, '左传 · 僖公 · 僖公二十五年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有五年春王正月，丙午，卫侯毁灭邢。夏四月癸酉，卫侯毁卒。宋荡伯来逆妇。宋杀其大夫。秋，楚人围陈，纳顿子于顿。葬卫文公。冬十有二月癸亥，公会卫子、莒庆盟于洮。
【传】二十五年春，卫人伐邢，二礼从国子巡城，掖以赴外，杀之。正月丙午，卫侯毁灭邢，同姓也，故名。礼至为铭曰：「余掖杀国子，莫余敢止。」
秦伯师于河上，将纳王。狐偃言于晋侯曰：「求诸侯，莫如勤王。诸侯信之，且大义也。继文之业而信宣于诸侯，今为可矣。」使卜偃卜之，曰：「吉。遇黄帝战于阪泉之兆。」公曰：「吾不堪也。」对曰：「周礼未改。今之王，古之帝也。」公曰：「筮之。」筮之，遇《大有》ⅵⅰ之《睽》ⅵⅷ，曰：「吉。遇『公用享于天子』之卦也。战克而王飨，吉孰大焉，且是卦也，天为泽以当日，天子降心以逆公，不亦可乎？《大有》去《睽》而复，亦其所也。」晋侯辞秦师而下。三月甲辰，次于阳樊。右师围温，左师逆王。夏四月丁巳，王入于王城，取大叔于温，杀之于隰城。
戊午，晋侯朝王，王飨醴，命之宥。请隧，弗许，曰：「王章也。未有代德而有二王，亦叔父之所恶也。」与之阳樊、温、原、欑茅之田。晋于是始启南阳。
阳樊不服，围之。苍葛呼曰：「德以柔中国，邢以威四夷，宜吾不敢服也。此谁非王之亲姻，其俘之也！」乃出其民。
秋，秦、晋伐鄀。楚斗克、屈御寇以申、息之师戍商密。秦人过析隈，入而系舆人以围商密，昏而傅焉。宵，坎血加书，伪与子仪、子边盟者。商密人惧曰：「秦取析矣，戍人反矣。」乃降秦师。囚申公子仪、息公子边以归。楚令尹子玉追秦师，弗及，遂围陈，纳顿子于顿。
冬，晋侯围原，命三日之粮。原不降，命去之。谍出，曰：「原将降矣。」军吏曰：「请待之。」公曰：「信，国之宝也，民之所庇也，得原失信，何以庇之？所亡滋多。」退一舍而原降。迁原伯贯于冀。赵衰为原大夫，狐溱为温大夫。
卫人平莒于我，十二月，盟于洮，修卫文公之好，且及莒平也。
晋侯问原守于寺人勃鞮，对曰：「昔赵衰以壶□食从径，馁而弗食。」故使处原。', '', '', '二十五年春季，卫军进攻邢国，礼氏两兄弟跟随邢国大官国子在城上巡察，两人左右挟持国子把他扔到城外，使他摔死。正月二十日，卫侯燬灭亡邢国。由于卫国和邢国同姓，所以记载卫侯的名字。礼至在铜器上作铭文说：“我挟持杀死国子，没有人敢来阻止我。”
秦穆公把军队驻扎在黄河边上，准备送周襄王回朝。狐偃对晋文公说：“求得诸侯的拥护，没有像为天子的事情尽力这样有效。可以得到诸侯信任，而且合于大义。继续文侯的事业，同时信用宣扬在诸侯之中，现在是机会了。”让卜偃占卜，说：“大吉。得到黄帝在阪泉作战的预兆。”晋文公说：“我当不起啊。”卜偃回答说：“周室的礼制没有改变，现在的王，就是古代的帝。”晋文公说：“占筮！”又占筮，得到《大有》变成《睽》，说：“吉利。得到‘公被天子设享礼招待’这个卦，战胜以后天子设享礼招待，还有比这更大的吉利吗？而且这一卦，天变成水泽来承受太阳的照耀，象征天子自己降格来迎接您，不也是可以吗？《大有》变成《睽》而又回到《大有》，天子也就回到他的处所。”
晋文公辞退秦军，顺流而下。三月十九日，军队驻扎在阳樊，右翼部队包围温地，左翼部队迎接周襄王。夏季四月初三日，襄王进入王城。在温地抓了太叔，把他杀死在隰城。初四日，晋文公朝觐周襄王。周襄王用甜酒招待晋文公，又让晋文公向自己回敬酒。晋文公请求死后能用隧道葬他，周襄王没有允许，说：“这是王室的规章。还没有取代周室的行为而有两个天子，这也是叔父所厌恶的。”赐给晋文公阳樊、温、原、攒茅的田地。晋国在这时候才开辟了南阳的疆土。
阳樊人不服，晋国军队包围了阳樊。仓葛大喊说：“德行用来安抚中原国家，刑罚用来威慑四方夷狄，你们这样干，无怪我们不敢降服了。这里谁不是天子的亲戚，难道能俘虏他们吗？”于是就放百姓出城了。
秋季，秦国和晋国进攻鄀国。楚国的鬬克、屈御寇带领申、息两地的军队戍守商密。秦军经过析地，绕道丹江水湾子，同时捆绑着自己的士兵假装俘虏，以包围商密，黄昏的时候逼近城下。夜里，掘地歃血，把盟书放在上面，假装和鬬克、御寇盟誓的样子。商密的人害怕，说：“秦军已经占领析地了！戍守的人背叛了！”于是就向秦军投降。秦国军队囚禁了申公鬬克、息公屈御寇而回国。楚国的令尹子玉追赶秦军，没有赶上。楚军就包围陈国，把顿子送回顿国。
冬季，晋文公率军包围原国，命令携带三天的粮食。到了三天原国不投降，就下令离开。间谍从城里出来，说：“原国准备投降了。”军官说：“请等待一下。”晋文公说：“信用，是国家的宝贝，百姓靠它庇护。得到原国而失去信用，用什么庇护百姓？所损失的东西更多。”退兵三十里，原国投降。晋文公把原伯贯迁到冀地。任命赵衰作为原地的地方官，狐溱作为温地的地方官。
卫国人调停莒国和我国的关系。十二月，鲁僖公和卫成公、莒庆在洮地结盟，重温卫文公时代的旧好，同时和莒国讲和。
晋文公向寺人勃鞮询问镇守原地的人选。勃鞮回答说：“以前赵衰用壶盛饮料并携带了食物跟随您，他一个人走在小道上，饿了也不去吃它。”所以晋文公让赵衰作为原地的地方官。', NULL, '', 'indent', 1558951589, '5ceb461d7b968a0076652426', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642956, '左传 · 僖公 · 僖公二十六年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有六年春王正月，己未，公会莒子、卫宁速盟于向。齐人侵我西鄙，公追齐师，至酅，不及。夏，齐人伐我北鄙。卫人伐齐。公子遂如楚乞师。秋，楚人灭夔，以夔子归。冬，楚人伐宋，围婚。公以楚师伐齐，取谷。公至自伐齐。
【传】二十六年春，王正月，公会莒兹ぶ宁庄子盟于向，寻洮之盟也。齐师侵我西鄙，讨是二盟也。夏，齐孝公伐我北鄙。卫人伐齐，洮之盟故也。公使展喜犒师，使受命于展禽。
齐侯未入竟，展喜从之，曰：「寡君闻君亲举玉趾，将辱于敝邑，使下臣犒执事。」齐侯曰：「鲁人恐乎？」对曰：「小人恐矣，君子则否。」齐侯曰：「室如县罄，野无青草，何恃而不恐？」对曰：「恃先王之命。昔周公、大公股肱周室，夹辅成王。成王劳之而赐之盟，曰：『世世子孙，无相害也。』载在盟府，大师职之。桓公是以纠合诸侯而谋其不协，弥缝其阙而匡救其灾，昭旧职也。及君即位，诸侯之望曰：『其率桓之功。』我敝邑用不敢保聚，曰：『岂其嗣世九年而弃命废职，其若先君何？』君必不然。恃此以不恐。」齐侯乃还。
东门襄仲、臧文仲如楚乞师，臧孙见子玉而道之伐齐、宋，以其不臣也。
夔子不祀祝融与鬻熊，楚人让之，对曰：「我先王熊挚有疾，鬼神弗赦而自窜于夔。吾是以失楚，又何祀焉？」秋，楚成得臣、斗宜申帅师灭夔，以夔子归。
宋以其善于晋侯也，叛楚即晋。冬，楚令尹子玉、司马子西帅师伐宋，围缗。
公以楚师伐齐，取谷。凡师能左右之曰以。置桓公子雍于谷，易牙奉之以为鲁援。楚申公叔侯戍之。桓公之子七人，为七大夫于楚。


', '', '', '二十六年春季，周王朝历法的正月，鲁僖公会见莒兹邳公、甯庄子，在向地结盟。重温洮地盟会的旧好。
齐国军队进攻我国西部边境，表示对洮、向两次会盟的不满。
夏季，齐孝公进攻我国北部边境，卫军便攻打齐国，这是卫国履行洮地的盟约。
僖公派遣展喜犒劳军队，派他向展禽请教如何措辞。齐孝公尚未进入我国国境，展喜出境见他，说：“我的君主听说君王亲自出动大驾，将要光临敝邑，所以派遣下臣来慰劳您的左右侍从。”齐孝公说：“鲁国人害怕吗？”展喜回答说：“小人害怕了，君子不怕。”齐孝公说：“房屋中像挂起的磬一样的空，四野里连青草都没有，靠什么不害怕？”展喜回答说：“靠着先王的命令。从前周公、太公辅助周王朝，在左右协助成王。成王慰劳他们，赐给他们盟约，说：‘世世代代的子孙不要互相侵犯。’这个盟约藏在盟府之中，由太史掌管。桓公因此联合诸侯，而商讨解决他们之间的纠纷，弥补他们的过失，而救援他们的灾难，这都是显扬过去的职责。等君王即位，各国诸侯盼望说：‘他会继续桓公的功业吧！’我敝邑因此不敢保护城郭纠聚民众，说：‘难道他即位九年，就背弃王命、废弃职责？他怎么对得住先君？他一定不会这样做的。’靠着这个，所以不害怕。”齐孝公就收兵回国了。
东门襄仲、臧文仲到楚国请求出兵。臧孙进见楚国的大臣子玉而引导他攻打齐、宋两国，因为齐、宋两国不肯尊事楚国。
夔君不祭祀祝融和鬻熊，楚国人责备他。夔君回答说：“我们的先王熊挚有病，鬼神不肯赦免他，使他死去，所以自己流窜到夔，我国因此失去楚国的救助，又祭祀什么？”秋季，楚国的成得臣、鬬宜申领兵灭亡夔国，抓了夔君回国。
宋国因为他们曾经对晋侯表示友善，所以背叛楚国而靠拢晋国。冬季，楚国的令尹子玉、司马子西领兵攻打宋国，包围缗地。
僖公指挥楚国军队攻打齐国，占领了穀地。凡是出兵，能够随意指挥别国军队叫做“以”。把齐桓公的儿子雍安置在穀地，易牙奉事他作为鲁国的后援。齐桓公的儿子有七个人，都在楚国做了大夫。
', NULL, '', 'indent', 1558951628, '5ceb464aba39c800687e5ec6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642982, '左传 · 宣公 · 宣公元年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】元年春王正月，公即位。公子遂如齐逆女。三月，遂以夫人妇姜至自齐。夏，季孙行父如齐。晋放其大夫胥甲父于卫。公会齐侯于平州。公子遂如齐。六月，齐人取济西田。秋，邾子来朝。楚子、郑人侵陈，遂侵宋。晋赵盾帅师救陈。宋公、陈侯、卫侯、曹伯会晋师于棐林，伐郑。冬，晋赵穿帅师侵崇。晋人、宋人伐郑。
【传】元年春，王正月，公子遂如齐逆女，尊君命也。三月，遂以夫人妇姜至自齐，尊夫人也。
夏，季文子如齐，纳赂以请会。
晋人讨不用命者，放胥甲父于卫，而立胥克。先辛奔齐。
会于平州，以定公位。东门襄仲如齐拜成。
六月，齐人取济西之田，为立公故，以赂齐也。
宋人之弑昭公也，晋荀林父以诸侯之师伐宋，宋及晋平，宋文公受盟于晋。又会诸侯于扈，将为鲁讨齐，皆取赂而还。郑穆公曰：「晋不足与也。」遂受盟于楚。陈共公之卒，楚人不礼焉。陈灵公受盟于晋。
秋，楚子侵陈，遂侵宋。晋赵盾帅师救陈、宋。会于棐林，以伐郑也。楚蒍贾救郑，遇于北林。囚晋解扬，晋人乃还。
晋欲求成于秦，赵穿曰：「我侵崇，秦急崇，必救之。吾以求成焉。」冬，赵穿侵崇，秦弗与成。
晋人伐郑，以报北林之役。于是，晋侯侈，赵宣子为政，骤谏而不入，故不竞于楚。
', '', '', '元年春，周王朝历法的正月，公子遂到齐国迎接齐女。《春秋》所以称之为“公子遂”，是由于尊重国君的命令。
三月，遂和夫人妇姜从齐国来到，《春秋》所以又称之为“遂”，是由于尊重夫人。
夏季，季文子到齐国，进献财礼。以请求参加盟会。
晋国人惩罚不听命令的人，把胥甲父放逐到卫国，而立了胥克。先辛逃亡到齐国。
宣公和齐惠公在平州会见，以稳定宣公的君位。东门襄仲去齐国，拜谢宣公能够参加盟会。
六月，齐国人取得了济水以西的土田，这是由于齐国帮助宣公得为国君的缘故，用此作为对齐国的谢礼。
宋国人杀死昭公的时候，晋国的荀林父带领诸侯的军队攻打宋国，宋国和晋国讲和，宋文公在晋国接受盟约。又在扈地会合诸侯，准备为鲁国讨伐齐国。两次都取得了财货而回国。
郑穆公说：“晋国是不值得亲附的。”就在楚国接受盟约。陈共公死的时候，楚国不行诸侯吊丧的礼仪，陈灵公在晋国接受盟约。
秋季，楚庄王侵袭陈国，乘机又侵袭宋国。晋国赵盾带兵救陈、宋。宋文公、陈灵公、卫成公、曹文公和晋军在棐林会合，讨伐郑国。楚国..贾去救援郑国，在北林和晋军相遇，囚禁了晋国的解扬，晋军就回国了。
晋国想要和秦国讲和。赵穿说：“我们侵袭崇国，秦国为崇国着急，一定会去救崇国，我们就以此向秦国要求讲和。”冬季。赵穿侵袭崇国。秦国不肯和晋国讲和。晋军攻打郑国，以报复北林的那次战役。当时，晋灵公奢侈，赵宣子执政，多次劝谏都不听，所以不能和楚国竞争。
', NULL, '', 'indent', 1558952749, '5ceb4aaaba39c800687e8d76', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642957, '左传 · 僖公 · 僖公二十七年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有七年春，杞子来朝。夏六月庚寅，齐侯昭卒。秋八月乙未，葬齐孝公。乙巳，公子遂帅师入杞。冬，楚人、陈侯、蔡侯、郑伯、许男围宋。十有二月甲戌，公会诸侯，盟于宋。
【传】二十七年春，杞桓公来朝，用夷礼，故曰子。公卑杞，杞不共也。
夏，齐孝公卒。有齐怨，不废丧纪，礼也。
秋，入杞，责无礼也。
楚子将围宋，使子文治兵于睽，终朝而毕，不戮一人。子玉复治兵于蒍，终日而毕，鞭七人，贯三人耳。国老皆贺子文，子文饮之酒。蒍贾尚幼，后至，不贺。子文问之，对曰：「不知所贺。子之传政于子玉，曰：『以靖国也。』靖诸内而败诸外，所获几何？子玉之败，子之举也。举以败国，将何贺焉？子玉刚而无礼，不可以治民。过三百乘，其不能以入矣。苟入而贺，何后之有？」
冬，楚子及诸侯围宋，宋公孙固如晋告急。先轸曰：「报施救患，取威定霸，于是乎在矣。」狐偃曰：「楚始得曹而新昏于卫，若伐曹、卫，楚必救之，则齐、宋免矣。」于是乎蒐于被庐，作三军。谋元帅。赵衰曰：「郤縠可。臣亟闻其言矣，说礼乐而敦《诗》《书》。《诗》、《书》，义之府也。礼乐，德之则也。德义，利之本也。《夏书》曰：『赋纳以言，明试以功，车服以庸。』君其试之。」及使郤縠将中军，郤溱佐之；使狐偃将上军，让于狐毛，而佐之；命赵衰为卿，让于栾枝、先轸。使栾枝将下军，先轸佐之。荀林父御戎，魏准为右。
晋侯始入而教其民，二年，欲用之。子犯曰：「民未知义，未安其居。」于是乎出定襄王，入务利民，民怀生矣，将用之。子犯曰：「民未知信，未宣其用。」于是乎伐原以示之信。民易资者不求丰焉，明征其辞。公曰：「可矣乎？」子犯曰：「民未知礼，未生其共。」于是乎大蒐以示之礼，作执秩以正其官，民听不惑而后用之。出谷戍，释宋围，一战而霸，文之教也。
', '', '', '二十七年春季，杞桓公来鲁国朝见。因为他用的是夷人的礼节，所以《春秋》称他为“子”。僖公看不起杞子，由于他认为杞子不恭敬。
夏季，齐孝公去世。鲁国虽然对齐国有怨恨，但是仍然没有废弃对邻国君主的吊唁，这是合于礼的。
秋季，公子遂领兵攻入杞国，这是为了责备杞桓公的无礼。
楚成王准备包围宋国，派遣子文在睽地演习作战，一早上就完事，没有杀一个人。子玉又在?地演习作战，一天才完事，鞭打七个人，用箭穿三个人的耳朵。元老们都祝贺子文。子文招待他们喝酒。?贾年纪还小，迟到了，不祝贺。子文问他，回答说：“不知道要祝贺什么。您把政权传给子玉，说‘为了安定国家’，安定于内而失败于外，所得到的有多少？子玉的对外作战失败，是由于您的推举。推举而使国家失败，有什么可贺的呢？子玉刚愎无礼，不能让他治理军民，率领的兵车超过三百辆，恐怕就不能回来了。如果回来，再祝贺，有什么晚呢？”
冬季，楚成王和诸侯包围宋国。宋国的公孙固到晋国报告紧急情况。先轸说：“报答施舍，救援患难，取得威望，成就霸业，就在这里了。”狐偃说：“楚国刚刚得到曹国，又新近和卫国结为婚姻之国，如果攻打曹、卫两国，楚国必定救援，那么齐国和宋国就可以免于被攻了。”晋国因此而在被庐阅兵，建立三个军，商量元帅的人选。赵衰说：“郤縠可以。我屡次听到他的话，喜爱礼乐而重视《诗》、《书》。《诗》、《书》，是道义的府库；礼乐，是道德的表率；道德礼义，是利益的基础。《夏书》说：‘有益的话全部采纳，考察效果加以试验，如果成功，用车马衣服作为酬劳。’您不妨试一下！”于是晋国派郤縠率领中军，郤溱辅助他。派狐偃率领上军，狐偃让给狐毛而自己辅助他。任命赵衰为卿，赵衰让给栾枝、先轸。命栾枝率领下军，先轸辅助他。荀林父驾御战车，魏犫作为车右。
晋文公一回国，就训练百姓，过了两年，就想使用他们。子犯说：“百姓还不知道道义，还没能各安其位。”晋文公就离开晋国去安定周襄王的君位，回国后致力于便利百姓，百姓就各安于他们的生活了。又打算使用他们，子犯说：“百姓还不知道93 信用，还不能十分明白信用的作用。”就攻打原国来让百姓看到信用，百姓做买卖不求暴利，明码实价，各无贪心。晋文公说：“行了吗？”子犯说：“百姓还不知道礼仪，没有产生他们的恭敬。”由此举行盛大阅兵来让百姓看到礼仪，建立执秩的官职来规定主管官员的职责。等到百姓看到事情就能明辨是非，然后才使用他们。赶走穀地的驻军，解除宋国的包围，一次战争就称霸诸侯，这都是文公的教化。
', NULL, '', 'indent', 1558951675, '5ceb46757b968a007665272e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642958, '左传 · 僖公 · 僖公二十八年', NULL, 5, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有八年春，晋侯侵曹，晋侯伐卫。公子买戍卫，不卒戍，刺之。楚人救卫。三月丙午，晋侯入曹，执曹伯。畀宋人。夏四月己巳，晋侯、齐师、宋师、秦师及楚人战于城濮，楚师败绩。楚杀其大夫得臣。卫侯出奔楚。五月癸丑，公会晋侯、齐侯、宋公、蔡侯、郑伯、卫子、莒子，盟于践土。陈侯如会。公朝于王所。六月，卫侯郑自楚复归于卫。卫元咺出奔晋。陈侯款卒。秋，杞伯姬来。公子遂如齐。冬，公会晋侯、齐侯、宋公、蔡侯、郑伯、陈子、莒子、邾人、秦人于温。天王狩于河阳。壬申，公朝于王所。晋人执卫侯，归之于京师。卫元咺自晋复归于卫。诸侯遂围许。曹伯襄复归于曹，遂会诸侯围许。
【传】二十八年春，晋侯将伐曹，假道于卫，卫人弗许。还，自南河济。侵曹伐卫。正月戊申，取五鹿。二月，晋郤縠卒。原轸将中军，胥臣佐下军，上德也。晋侯、齐侯盟于敛盂。卫侯请盟，晋人弗许。卫侯欲与楚，国人不欲，故出其君以说于晋。卫侯出居于襄牛。
公子买戍卫，楚人救卫，不克。公惧于晋，杀子丛以说焉。谓楚人曰：「不卒戍也。」
晋侯围曹，门焉，多死，曹人尸诸城上，晋侯患之，听舆人之谋曰称：「舍于墓。」师迁焉，曹人凶惧，为其所得者棺而出之，因其凶也而攻之。三月丙午，入曹。数之，以其不用僖负羁而乘轩者三百人也。且曰：「献状。」令无入僖负羁之宫而免其族，报施也。魏准、颠颉怒曰：「劳之不图，报于何有！」蓺僖负羁氏。魏准伤于胸，公欲杀之而爱其材，使问，且视之。病，将杀之。魏准束胸见使者曰：「以君之灵，不有宁也。」距跃三百，曲踊三百。乃舍之。杀颠颉以徇于师，立舟之侨以为戎右。
宋人使门尹般如晋师告急。公曰：「宋人告急，舍之则绝，告楚不许。我欲战矣，齐、秦未可，若之何？」先轸曰：「使宋舍我而赂齐、秦，藉之告楚。我执曹君而分曹、卫之田以赐宋人。楚爱曹、卫，必不许也。喜赂怒顽，能无战乎？」公说，执曹伯，分曹、卫之田以畀宋人。
楚子入居于申，使申叔去谷，使子玉去宋，曰：「无从晋师。晋侯在外十九年矣，而果得晋国。险阻艰难，备尝之矣；民之情伪，尽知之矣。天假之年，而除其害。天之所置，其可废乎？《军志》曰：『允当则归。』又曰：『知难而退。』又曰：『有德不可敌。』此三志者，晋之谓矣。」子玉使伯棼请战，曰：「非敢必有功也，愿以间执谗慝之口。」王怒，少与之师，唯西广、东宫与若敖之六卒实从之。
子玉使宛春告于晋师曰：「请复卫侯而封曹，臣亦释宋之围。」子犯曰：「子玉无礼哉！君取一，臣取二，不可失矣。」先轸曰：「子与之。定人之谓礼，楚一言而定三国，我一言而亡之。我则无礼，何以战乎？不许楚言，是弃宋也。救而弃之，谓诸侯何？楚有三施，我有三怨，怨仇已多，将何以战？不如私许复曹、卫以携之，执宛春以怒楚，既战而后图之。」公说，乃拘宛春于卫，且私许复曹、卫。曹、卫告绝于楚。
子玉怒，从晋师。晋师退。军吏曰：「以君辟臣，辱也。且楚师老矣，何故退？」子犯曰：「师直为壮，曲为老。岂在久乎？微楚之惠不及此，退三舍辟之，所以报也。背惠食言，以亢其仇，我曲楚直。其众素饱，不可谓老。我退而楚还，我将何求？若其不还，君退臣犯，曲在彼矣。」退三舍。楚众欲止，子玉不可。
夏四月戊辰，晋侯、宋公、齐国归父、崔夭、秦小子憖次于城濮。楚师背酅而舍，晋侯患之，听舆人之诵，曰：「原田每每，舍其旧而新是谋。」公疑焉。子犯曰：「战也。战而捷，必得诸侯。若其不捷，表里山河，必无害也。」公曰：「若楚惠何？」栾贞子曰：「汉阳诸姬，楚实尽之，思小惠而忘大耻，不如战也。」晋侯梦与楚子搏，楚子伏己而监其脑，是以惧。子犯曰：「吉。我得天，楚伏其罪，吾且柔之矣。」
子玉使斗勃请战，曰：「请与君之士戏，君冯轼而观之，得臣与寓目焉。」晋侯使栾枝对曰：「寡君闻命矣。楚君之惠未之敢忘，是以在此。为大夫退，其敢当君乎？既不获命矣，敢烦大夫谓二三子，戒尔车乘，敬尔君事，诘朝将见。」
晋车七百乘，革显、革引、鞅、革半。晋侯登有莘之虚以观师，曰：「少长有礼，其可用也。」遂伐其木以益其兵。鲁巳，晋师陈于莘北，胥臣以下军之佐当陈、蔡。子玉以若敖六卒将中军，曰：「今日必无晋矣。」子西将左，子上将右。胥臣蒙马以虎皮，先犯陈、蔡。陈、蔡奔，楚右师溃。狐毛设二旆而退之。栾枝使舆曳柴而伪遁，楚师驰之。原轸、郤溱以中军公族横击之。狐毛、狐偃以上军夹攻子西，楚左师溃。楚师败绩。子玉收其卒而止，故不败。
晋师三日馆谷，及癸酉而还。甲午，至于衡雍，作王宫于践土。
乡役之三月，郑伯如楚致其师，为楚师既败而惧，使子人九行成于晋。晋栾枝入盟郑伯。五月丙午，晋侯及郑伯盟于衡雍。丁未，献楚俘于王，驷介百乘，徒兵千。郑伯傅王，用平礼也。己酉，王享醴，命晋侯宥。王命尹氏及王子虎、内史叔兴父策命晋侯为侯伯，赐之大辂之服，戎辂之服，彤弓一，彤矢百，玈弓矢千，秬鬯一卣，虎贲三百人。曰：「王谓叔父，敬服王命，以绥四国。纠逖王慝。」晋侯三辞，从命。曰：「重耳敢再拜稽首，奉扬天子之丕显休命。」受策以出，出入三觐。
卫侯闻楚师败，惧，出奔楚，遂适陈，使元咺奉叔武以受盟。癸亥，王子虎盟诸侯于王庭，要言曰：「皆奖王室，无相害也。有渝此盟，明神殛之，俾队其师，无克祚国，及而玄孙，无有老幼。」君子谓是盟也信，谓晋于是役也能以德攻。
初，楚子玉自为琼弁玉缨，未之服也。先战，梦河神谓己曰：「畀余，余赐女孟诸之麋。」弗致也。大心与子西使荣黄谏，弗听。荣季曰：「死而利国。犹或为之，况琼玉乎？是粪土也，而可以济师，将何爱焉？」弗听。出，告二子曰：「非神败令尹，令尹其不勤民，实自败也。」既败，王使谓之曰：「大夫若入，其若申、息之老何？」子西、孙伯曰：「得臣将死，二臣止之曰：『君其将以为戮。』」及连谷而死。晋侯闻之而后喜可知也，曰：「莫馀毒也已！蒍吕臣实为令尹，奉己而已，不在民矣。」
或诉元咺于卫侯曰：「立叔武矣。」其子角从公，公使杀之。咺不废命，奉夷叔以入守。
六月，晋人复卫侯。宁武子与卫人盟于宛濮，曰：「天祸卫国，君君臣不协，以及此忧也。今天诱其衷，使皆降心以相从也。不有居者，谁守社稷？不有行者，谁扞牧圉？不协之故，用昭乞盟于尔大神以诱天衷。自今日以往，既盟之后，行者无保其力，居者无惧其罪。有渝此盟，以相及也。明神先君，是纠是殛。」国人闻此盟也，而后不贰。卫侯先期入，宁子先，长佯守门以为使也，与之乘而入。公子颛犬、华仲前驱。叔孙将沐，闻君至，喜，捉发走出，前驱射而杀之。公知其无罪也，枕之股而哭之。颛犬走出，公使杀之。元咺出奔晋。
城濮之战，晋中军风于泽，亡大旆之左旃。祁瞒奸命，司马杀之，以徇于诸侯，使茅伐代之。师还。壬午，济河。舟之侨先归，士会摄右。秋七月丙申，振旅，恺以入于晋。献俘授馘，饮至大赏，征会讨贰。杀舟之侨以徇于国，民于是大服。
君子谓：「文公其能刑矣，三罪而民服。《诗》云：『惠此中国，以绥四方。』不失赏刑之谓也。」
冬，会于温，讨不服也。
卫侯与元咺讼，宁武子为辅，金咸庄子为坐，士荣为大士。卫侯不胜。杀士荣，刖金咸庄子，谓宁俞忠而免之。执卫侯，归之于京师，置诸深室。宁子职纳橐饘焉。元咺归于卫，立公子瑕。
是会也，晋侯召王，以诸侯见，且使王狩。仲尼曰：「以臣召君，不可以训。」故书曰：「天王狩于河阳。」言非其地也，且明德也。
壬申，公朝于王所。
丁丑，诸侯围许。
晋侯有疾，曹伯之竖侯孺货筮史，使曰：「以曹为解。齐桓公为会而封异姓，今君为会而灭同姓。曹叔振铎，文之昭也。先君唐叔，武之穆也。且合诸侯而灭兄弟，非礼也。与卫偕命，而不与偕复，非信也。同罪异罚，非刑也。礼以行义，信以守礼，刑以正邪，舍此三者，君将若之何？」公说，复曹伯，遂会诸侯于许。
晋侯作三行以御狄，荀林父将中行，屠击将右行，先蔑将左行。', '', '', '二十八年春季，晋文公准备攻打曹国，向卫国借路。卫国不答应。回来，从南河渡过黄河，入侵曹国，攻打卫国。正月初九日，占取了五鹿。二月，郤縠死。原轸率领中军，胥臣辅助下军，把原轸提升，是为了重视才德。晋文公和齐昭公在敛盂结盟。卫成公请求参加盟约，晋国人不答应。卫成公想亲附楚国，国内的人们不愿意，所以赶走了他们的国君，来讨好晋国。卫成公离开国都住在襄牛。
公子买驻守在卫国，楚国人救援卫国，没有得胜。鲁僖公害怕晋国，杀了公子买来讨好晋国。骗楚国人说：“他驻守没到期就想回来，所以杀了他。”
晋文公发兵包围曹国，攻城，战死的人很多。曹军把晋军的尸体陈列在城上，晋文公很担心。听了士兵们的主意，声称“在曹国人的墓地宿营”。军队转移。曹国人恐惧，把他们得到的晋军的尸体装进棺材运出来，晋军由于曹军恐惧而攻城。三月初八日，进入曹国，责备曹国不任用僖负羁，做官坐车的反倒有三百人，并且说当年观看自己洗澡，现在罪有应得。下令不许进入僖负羁的家里，同时赦免他的族人，这是为了报答恩惠。魏犫、颠颉发怒说：“不替有功劳或者苦劳的人着想，还报答个什么恩惠？”放火烧了僖负羁的家。魏犫胸部受伤，晋文公想杀死他，但又爱惜他的才能，派人去慰问，同时观察病情。如果伤势很重，就准备杀了他。魏犫捆紧胸膛出见使者，说：“由于国君的威灵，难道我敢图安逸吗！”说着就向上跳了很多次，又向前跳了很多次。晋文公于是就饶恕了他，而杀死颠颉通报全军，立舟之侨作为车右。
宋国派门尹般到晋军中报告危急情况。晋文公说：“宋国来报告危急情况，不去救他就断绝了交往，请求楚国解围，他们又不答应。我们想作战，齐国和秦国又不同意。怎么办？”先轸说：“让宋国丢开我国而去给齐国、秦国赠送财礼。假借他们两国去请求楚国。我们逮住曹国国君，把曹国、卫国的田地分给宋国。楚国喜欢曹国、卫国，一定不答应齐国和秦国的请求。齐国和秦国对宋国的财礼喜欢，而对楚国的固执很生气，能够不打仗吗？”晋文公很高兴，拘捕了曹共公，把曹国和卫国的田地分给了宋国人。楚成王进入申城并住下来，让申叔离开穀地，让子玉离开宋国，说：“不要去追逐晋国军队！晋文公在外边，十九年了，而果然得到了晋国。险阻艰难，都尝过了；民情真假，也都知道了。上天给予他年寿，同时除去了他的祸害，上天所设置的，难道可以废除吗？《军志》说：‘适可而止。’又说：‘知难而退。’又说：‘有德的人不能抵挡。’这三条记载，适用于晋国。”
子玉派遣伯棼向成王请战，说：“不敢说一定有功劳，愿意借此堵塞奸邪小人的口。”楚成王发怒，少给他军队，只有西广、东宫和若敖的一百八十辆战车跟去。
子玉派宛春到晋军中报告说：“请恢复卫侯的君位，同时把土地退还曹国，我也解除对宋国的包围。”子犯说：“子玉无礼啊！给君王的，只是解除对宋国的包围一项，而要求君王给出的，却是复卫封曹两项。这次打仗的机会不可失掉了。”先轸说：“君王应该答应他的请求。安定别人叫做礼，楚国人一句话安定三国，我们一句话而使它们灭亡。我们就无礼，拿什么来作战呢？不答应楚国的请求，这是抛弃宋国；救援了又抛弃他，将对诸侯说什么？楚国有三项恩惠，我们有三项怨仇，怨仇已经太多了，准备拿什么作战？不如私下里答应恢复曹国和卫国来离间他们，逮了宛春来激怒楚国，等打起仗再说。”晋文公很高兴。于是把宛春囚禁在卫国，同时私下里允诺恢复曹、卫。曹、卫就与楚国断绝邦交。
子玉发怒，追逐晋军。晋军撤退。军吏说：“以国君而躲避臣下，这是耻辱；而且楚军已经疲劳不堪，为什么退走？”子犯说：“出兵作战，有理就气壮，无理就气衰，哪里在于在外边时间的长短呢？如果没有楚国的恩惠，我们到不了这里。退三舍躲避他们，就是作为报答。背弃恩惠而说话不算数，要用这个来蔽护他们的敌人，我们缺理而楚国有理，加上他们的士气一向饱满，不能认为是衰疲。我们退走而楚军回去，我们还要求什么？如果他们不回去，国君退走，而臣下进犯，他们就缺理了。”晋军退走三舍。楚国骑士要停下来，子玉不同意。
夏季，四月初一日，晋文公、宋成公、齐国的国归父、崔夭、秦国的小子慭驻在城催。楚军背靠着险要的地方扎营，晋文公担心这件事。听到士兵念诵说：“休耕田里的绿草繁茂，丢开旧草而对新的加以犁锄。”晋文公很疑惑。子犯说：“出战吧！战而得胜，一定得到诸侯；如果不胜，我国外有大河，内有高山，一定没有什么害处。”晋文公说：“对楚国的恩惠怎么办？”栾枝说：“汉水以北的姬姓诸国，楚国都把它们吞并完了。想着小恩惠，而忘记大耻大辱，不如出战。”晋文公梦中和楚王搏斗，楚王伏在自己身上咀嚼自己的脑浆，因而害怕。子犯说：“吉利。我得到上天，楚国伏罪，而且我们已经安抚他们了。”
子玉派遣鬬勃向晋国挑战，说：“请和君王的斗士作一次角力游戏，君王靠在车横板上观看，得臣可以陪同君王一起观看了。”晋文公派遣栾枝回答说：“我们国君知道您的意思了。楚君的恩惠，没有敢忘记，所以待在这里。我们以为大夫已经退兵了，臣下难道敢抵挡国君吗？既然大夫不肯退兵，那就烦大夫对贵部将士们说：‘准备好你们的战车，忠于你们的国事，明天早晨将再见面。’”晋国战车七百辆，装备齐全。晋文公登上有莘的废城观看军容，说：“年少的和年长的，排列有序，合于礼，可以使用了。”就命令砍伐山上的树木，以增加武器。
初二日，晋军在莘北摆开阵势，胥臣让下军分别抵挡陈、蔡军队。子玉用若敖的一百八十乘率领中军，说：“今天一定灭掉晋国了。”子西率领左军，子上率领右军。胥臣把马蒙上老虎皮，先攻陈、蔡两军。陈、蔡两军奔逃，楚军的右翼部队溃散。狐毛派出前军两队击退楚军的溃兵。栾枝让车子拖着木柴假装逃走，楚军追击，原轸、郤溱率领中军的公族拦腰袭击。狐毛、狐偃率领上军夹攻子西，楚国的左翼部队溃散。楚军大败。子玉及时下令收兵，得以不败。
晋军休整三天，吃楚军留下的粮食，到初六日起程回国。二十七日，到达衡雍，为天子在践土建造了一座王宫。
这一战役之前的三个月，郑文公派军队到楚国助战，因为楚军已经失败而害怕了，派遣子人九和晋国讲和。晋国的栾枝进入郑国和郑文公订立盟约。
五月初九日，晋文公和郑文公在衡雍结盟。初十日，把楚国的战俘献给周襄王：驷马披甲的战车一百辆，步兵一千人。郑文公作为相礼，用的是周平王时的礼仪。十二日，周襄王设享礼用甜酒招待晋文公，又允许他向自己回敬酒。周襄王命令尹氏和王子虎、内史叔兴父用策书任命晋文公为诸侯的领袖，赐给他大辂车、戎辂车以及相应的服装仪仗，红色的弓一把、红色的箭一百枝，黑色的弓十把和箭一千枝，黑黍加香草酿造的酒一卣，勇士三百人，说：“天子对叔父说：‘恭敬地服从天子的命令，以安抚四方诸侯，惩治王朝的邪恶。’”晋文公辞谢三次，然后接受命令，说：“重耳谨再拜叩头，接受和宣扬天子的重大赏赐和命令。”接受了策书就离开成周。从进入成周到离开，三次朝见周王。
卫成公听说楚军失败，害怕，逃亡到楚国，又到了陈国，派遣元咺奉事叔武去接受盟约。二十六日，王子虎和诸侯在天子的庭院里盟誓，约定说：“全部辅助王室，不要互相伤害！谁要违背盟约，就要受到神的诛杀，使他军队颠覆，不能享有国家，直到你的玄孙，不论老小。”君子认为这次结盟是守信用的，认为晋国在这次战役中能够用道德来进攻。
当初，楚国的子玉自己制作了镶玉的马冠马鞅，还没有使用。作战之前，梦见黄河河神对他说：“送给我，我赐给你孟诸的水草地。”子玉没有送去。他儿子大心和子西派荣黄劝谏，子玉不听。荣黄说：“死而有利于国家，尚且还要去做，何况是美玉呢？和国家比起来这不过是粪土罢了。如果可以使军队成功，有什么可惜的？”子玉仍然不肯。荣黄出来告诉两个人说：“不是神明让令尹失败，令尹不以百姓的事情为重，实在是自取失败啊。”子玉失败之后，楚成王派使臣对子玉说：“申、息的子弟大多伤亡了，大夫如果回来，怎么向申、息两地的父老交代呢？”子西、大心对使臣说：“子玉本来要自杀的，我们两个阻拦他说：‘不要自杀，国君还准备杀你呢。’”到达连穀，子玉就自杀了。
晋文公听说子玉自杀的消息以后，喜形于色，说：“没有人再来为害于我了。蔿吕臣做令尹，不过是维护自己罢了，并不是为了百姓。”
有人在卫成公面前毁谤元咺说：“他已立了叔武做国君了。”元咺的儿子角跟随卫成公，卫成公派人杀了他。元咺并没有因此而废弃卫成公的命令，还是奉事叔武回国摄政。六月，晋国人听任卫侯回国。甯武子和卫国官吏、大族等在宛濮结盟，说：“上天降祸卫国，君臣不和谐，所以才遭到这样的忧患。现在天意保佑我国，让大家放弃成见而互相听从。没有留下的人，谁来守卫国家？没有跟随君王的人，谁去保卫那些牧牛养马的人？由于不和协，因此乞求在大神面前明白宣誓，以求天意保佑。从今天订立盟约之后，在外的人不要仗恃自己的功劳，留下的人不要害怕有罪。谁要违背盟约，祸害就降临到他头上。神明和先君在上，加以惩罚诛杀。”国内的人们知道了这盟约，才没有二心。
卫成公比约定的日期先进入卫国，甯武子在卫成公之前，长牂把守城门，以为他是国君的使者，和他同乘一辆车进入。公子歂犬、华仲作为前驱，叔武正要洗发，听说国君来到，很高兴，用手抓着头发跑出来，前驱却把他射死了。卫成公知道他没有罪，把头枕在尸体的大腿上而哭他。歂犬逃跑，卫成公派人把他杀死了。元咺逃亡到晋国。
在城濮的战役中，晋军的中军在沼泽地遇到大风，丢掉了前军左边的大旗。祁瞒犯了军令，司马把他杀了，并通报诸侯，派茅茷代替他。军队回来，六月十六日，渡过黄河，舟之侨擅自先行回国，士会代理车右。秋季，七月某一天，胜利归来，高唱凯歌进入晋国，在太庙报告俘获和杀死敌人的数字，饮酒犒赏，召集诸侯会盟和攻打有二心的国家。杀舟之侨并通报全国，百姓因此而大为顺服。君子认为：“晋文公能够严明刑罚，杀了颠颉、祁瞒、舟之侨三个罪人而百姓顺服。《诗》说：‘施惠于中原国家，安定四方的诸侯’，说的就是没有失去公正的赏赐和刑罚。”
冬季，僖公和晋文公、齐昭公、宋成公、蔡庄公、郑文公、陈子、莒子、邾子、秦同人在温地会见，商量出兵攻打不顺服的国家。
卫成公和元咺争讼，甯武子作为卫成公的诉讼人，鍼庄子作为卫成公的代理人，士荣作为卫成公的答辩人。卫成公没有胜诉。作为诸侯领袖的晋国杀了士荣，砍了鍼庄子的脚，认为甯武子忠诚而赦免了他。逮捕卫成公，把他送到京师，关在牢房里。甯武子负责给卫成公送衣食。元咺回到卫国，立公子瑕为国君。
这次温地的会盟，晋文公召请周襄王前来，并且带领诸侯朝见他，又让周襄王打猎。孔子说：“以臣下而召请君主，是不能作为榜样的。”所以《春秋》记载说“天王狩于河阳”，天下本都是周王朝的地方，而这里却不是周襄王的地方了，而且是为了表明晋国的功德而避讳的说法。
十月初七日，僖公到周襄王的住处朝觐。
十一月十二日，诸侯包围许国。
晋文公有重病，曹共公的侍从侯獳贿赂晋文公的筮史，让他把得病的原因说成是由于灭了曹国。他就对晋文公说：“齐桓公主持会盟而封异姓的国家，现在君王主持会盟而灭同姓的国家。曹国的叔振铎，是文王的儿子；先君唐叔，是武王的儿子。而且会合诸侯而灭掉兄弟之国，这是不符合礼仪的；曹国和卫国一样得到君王的诺言，但是不能一同复国，这是不讲信用的；罪过相同而惩罚不同，这是不符合刑律的。礼仪用来推动道义，信用用来保护礼仪，刑律用来纠正邪恶。丢开了这三项，君王准备怎么办？”晋文公很高兴，恢复了曹共公的君位，曹共公就在许国和诸侯会盟。
晋文公建立三个步兵师来抵抗狄人，荀林父将领中行，屠击将领右行，先蔑将领左行。
', NULL, '', 'indent', 1558951721, '5ceb46a5d5de2b007078ece7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642959, '左传 · 僖公 · 僖公二十九年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有九年春，介葛卢来。公至自围许。夏六月，会王人、晋人、宋人、齐人、陈人、蔡人、秦人盟于翟泉。秋，大雨雹。冬，介葛卢来。
【传】二十九年春，葛卢来朝，舍于昌衍之上。公在会，馈之刍米，礼也。
夏，公会王子虎、晋狐偃、宋公孙固、齐国归父、陈辕涛涂、秦小子憖，盟于翟泉，寻践土之盟，且谋伐郑也。卿不书，罪之也。在礼，卿不会公、侯，会伯、子、男可也。
秋，大雨雹，为灾也。
冬，介葛卢来，以未见公，故复来朝，礼之，加燕好。
介葛卢闻牛鸣，曰：「是生三牺，皆用之矣，其音云。」问之而信。', '', '', '二十九年春季，介葛卢前来朝见，让他住在昌衍山上。当时鲁僖公正在参加许国翟泉的会见，赠送给他草料、粮食等物，这是合于礼的。
夏季，僖公和王子虎、晋国狐偃、宋国公孙固、齐国国归父、陈国辕涛涂、秦国小子?在翟泉结盟，重温践土的盟约，同时策划进攻郑国。参加结盟的卿没有记载，这是表示谴责他们。按照礼制，诸侯的卿不能参加公、侯的会见，参加伯、子、男的会见是可以的。
秋季，有大雨和雹子，成了灾害，《春秋》才加以记载。
冬季，介葛卢前来，由于前次没有见到僖公，再次来朝。对他加以礼遇，再加上燕礼和赠送上等财礼。
介葛卢听到牛叫，说：“这头牛生了三头小牛，都用来祭祀了，所以它的声音如此。”加以询问，果然这样。', NULL, '', 'indent', 1558951760, '5ceb46cec8959c0069dcf300', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642960, '左传 · 僖公 · 僖公三十年', NULL, 5, 300, 0, 2, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三十年春王正月。夏，狄侵齐。秋，卫杀其大夫元咺及公子瑕。卫侯郑归于卫。晋人、秦人围郑。介人侵萧。冬，天王使宰周公来聘。公子遂如京师。遂如晋。
【传】三十年春，晋人侵郑，以观其可攻与否。狄间晋之有郑虞也，夏，狄侵齐。
晋侯使医衍鸩卫侯。宁俞货医，使薄其鸩，不死。公为之请，纳玉于王与晋侯。皆十□王许之。秋，乃释卫侯。卫侯使赂周颛、治廑，曰：「苟能纳我，吾使尔为卿。」周、冶杀元咺及子适、子仪。公入祀先君。周、冶既服将命，周颛先入，及门，遇疾而死。冶廑辞卿。
九月甲午，晋侯、秦伯围郑，以其无礼于晋，且贰于楚也。晋军函陵，秦军汜南。佚之狐言于郑伯曰：「国危矣，若使烛之武见秦君，师必退。」公从之。辞曰：「臣之壮也，犹不如人，今老矣，无能为也已。」公曰：「吾不能早用子，今急而求子，是寡人之过也。然郑亡，子亦有不利焉。」许之，夜缒而出，见秦伯，曰：「秦、晋围郑，郑既知亡矣。若亡郑而有益于君，敢以烦执事。越国以鄙远，君知其难也，焉用亡郑以陪邻。邻之厚，君之薄也。若舍郑以为东道主，行李之往来，共其乏困，君亦无所害。且君尝为晋君赐矣，许君焦、瑕，朝济而夕设版焉，君之所知也。夫晋何厌之有？既东封郑，又欲肆其西封，若不阙秦，将焉取之？阙秦以利晋，唯君图之。」秦伯说，与郑人盟，使杞子、逢孙、扬孙戍之，乃还。
子犯请击之，公曰：「不可。微夫人力不及此。因人之力而敝之，不仁。失其所与，不知。以乱易整，不武。吾其还也。」亦去之。
初，郑公子兰出奔晋，从于晋侯。伐郑，请无与围郑。许之，使待命于东。郑石甲父、侯宣多逆以为大子，以求成于晋，晋人许之。
冬，王使周公阅来聘，飨有昌蜀、白、黑、形盐。辞曰：「国君，文足昭也，武可畏也，则有备物之飨以象其德。荐五味，羞嘉谷，盐虎形，以献其功。吾何以堪之？」
东门襄仲将聘于周，遂初聘于晋。', '', '', '三十年春季，晋国人入侵郑国，以此来试探郑国是否可以攻打。狄人钻了晋国侵犯郑国这个空子，夏季，狄人入侵齐国。
晋文公派了医生衍毒死卫成公。甯俞贿赂医生，让他少放点毒药，所以卫成公没有被毒死。僖公为卫成公请求，把玉献给周襄王和晋文公，都是十对。周襄王允许了。秋季，卫成公被释放了。
卫成公派人贿赂周歂、冶廑说：“如果能接纳我当国君，我让你们当卿。”周、冶两人杀了元咺和子适、子仪。卫成公回国，在太庙祭祀先君，周、冶两人已经穿好卿的礼服，准备接受任命，周歂先进太庙，到门口，发病而死。冶廑骇怕了，便辞去卿位。
九月初十日，晋文公、秦穆公包围郑国，因为郑国对晋国无礼，而且心向着楚国。晋军驻扎在函陵，秦军驻扎在汜南。佚之狐对郑文公说：“国家危急了。假若派遣烛之武去进见秦君，军队必然退走。”郑文公采纳了这个建议，便请烛之武去进见秦君，烛之武推辞说：“下臣年壮的时候，尚且不如别人；现在老了，无能为力了。”郑文公说：“我没有能及早任用您，现在形势危急而来求您，这是我的过错。然而郑国被灭亡，您也不好啊。”烛之武答应了，夜里用绳子把自己从城上吊到城外，进见秦穆公，说：“秦、晋两国包围郑国，郑国已经知道自己要灭亡了。如果灭亡郑国而对君王有好处，那是值得劳动君王左右随从的。越过别国而以远方的土地作为边邑，君王知道是不容易的，哪里用得着灭亡郑国来增加邻国的土地？邻国实力加强，就是君王的削弱。如果赦免郑国，让他做东路上的主人，使者的往来，供应他所缺少的一切东西，对君王也没有害处。而且君王曾经把好处赐给晋国国君了，他答应给君王焦、瑕两地，早晨过河回国，晚上就设版筑城，这是君王所知道的。晋国哪有满足的时候，已经在东边向郑国开拓土地，又要肆意扩大它西边的土地。如果不损害秦国，还能到哪里去取得土地呢？损害秦国来有利于晋国的事，请君王考虑。”秦穆公很高兴，和郑国人结盟，派遣杞子、逢孙、杨孙在郑国戍守，就撤退了。
子犯请求追击秦军。晋文公说：“不行。如果没有他们的力量，我们不会有今天这个地位。靠了别人的力量，反而损害他，这是不讲仁德；失掉了同盟国家，这是不明智；用动乱代替整齐，这是不勇敢。我还是回去吧。”晋文公也就撤军回国。
当初，郑国的公子兰逃亡到晋国，跟随晋文公攻打郑国，请求不要参加对郑都的包围。晋文公答应了，让他在东部边境等候命令。郑国的石甲父、侯宣多把他接回来做太子，向晋国讲和，晋国允许了。
冬季，周襄王派遣周公阅来鲁国聘问，宴请他的食物有昌蒲菹、白米糕、黑黍糕和虎形块盐。周公阅推辞说：“国家的君主，文治足以显扬四方，武功可以使人畏惧，就备有各种物品宴请，以像征他的德行；进五味的调和，献美好的粮食，有虎形的盐，以像征他的功业。我怎么当得起这个？”
东门襄仲将要到成周聘问，就顺路到晋国作初次聘问。
', NULL, '', 'indent', 1558951799, '5ceb46f4ba39c800687e6572', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642961, '左传 · 僖公 · 僖公三十一年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三十有一年春，取济西田。公子遂如晋。夏四月，四卜郊，不从，乃免牲。犹三望。秋七月。冬，杞伯姬来求妇。狄围卫。十有二月，卫迁于帝丘。
【传】三十一年春，取济西田，分曹地也。使臧文仲往，宿于重馆。重馆人告曰：「晋新得诸侯，必亲其共，不速行，将无及也。」从之，分曹地，自洮以南，东傅于济，尽曹地也。
襄仲如晋，拜曹田也。
夏四月，四卜郊，不从，乃免牲，非礼也。犹三望，亦非礼也。礼不卜常祀，而卜其牲、日，牛卜日曰牲。牲成而卜郊，上怠慢也。望，郊之细也。不郊，亦无望可也。
秋，晋搜于清原，作五军御狄。赵衰为卿。
冬，狄围卫，卫迁于帝丘。卜曰三百年。卫成公梦康叔曰：「相夺予享。」公命祀相。宁武子不可，曰：「鬼神非其族类，不歆其祀。杞、鄫何事？相之不享于此。久矣，非卫之罪也，不可以间成王、周公之命祀。请改祀命。」
郑泄驾恶公子瑕，郑伯亦恶之，故公子瑕出奔楚。', '', '', '三十一年春季，取得济水以西的田土，这本是分割给曹国的土地。派臧文仲前去，住在重地的宾馆里。重地宾馆里的人告诉他说：“晋国新近得到许多诸侯国家为盟邦，必定亲近恭顺他的人，你不快点走，怕会赶不上。”臧文仲听从了。分割曹国的土地，从洮水以南，东边挨着济水，都是曹国的土地。
襄仲到晋国去，拜谢取得曹国的田地。
夏季，四月，四次占卜郊祭，都不吉利，就不举行郊祭，不杀牛，这是不合于礼的。仍旧祭祀名山大川泰山、淮水、东海三处，这也是不合于礼的。按礼制，不占卜常规的祭祀，而只是占卜使用的牺牲和日期。牛，在占卜到好日子以后就改称牲，已经成为牲而还要占卜郊祭的吉凶，这是在上者侮慢大典、亵渎龟甲。望祭，是郊祭的细节，不举行郊祭，更不必举行对山川的望祭。
秋季，晋国在清原检阅军队，建立五个军来抵抗狄人。赵衰被任命为卿。
冬季，狄人包围卫国，卫国迁移到帝丘，占卜的结果是立国三百年。卫成公梦见康叔说：“相夺走了我的祭献。”成公命令祭祀相。甯武子不同意，说：“不是同族人的祭祀，鬼神就不享用那种祭品。杞国和鄫国为什么不祭祀？相在杞国和卫国没有受到祭献很久了，这不是卫国的罪过，不能违反成王、周公所规定的祭祀，请求您改变祭祀相的命令。”郑国的洩驾讨厌公子瑕，郑文公也很讨厌他，所以公子瑕逃亡到楚国。', NULL, '', 'indent', 1558951835, '5ceb47197b968a0076652ea9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642962, '左传 · 僖公 · 僖公三十二年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三十有二年春王正月。夏四月己丑，郑伯捷卒。卫人侵狄。秋，卫人及狄盟。冬十有二月己卯，晋侯重耳卒。
【传】三十二年春，楚斗章请平于晋，晋阳处父报之。晋、楚始通。
夏，狄有乱。卫人侵狄，狄请平焉。秋，卫人及狄盟。
冬，晋文公卒。庚辰，将殡于曲沃，出绛，柩有声如牛。卜偃使大夫拜。曰：「君命大事。将有西师过轶我，击之，必大捷焉。」杞子自郑使告于秦，曰：「郑人使我掌其北门之管，若潜师以来，国可得也。」穆公访诸蹇叔，蹇叔曰：「劳师以袭远，非所闻也。师劳力竭，远主备之，无乃不可乎！师之所为，郑必知之。勤而无所，必有悖心。且行千里，其谁不知？」公辞焉。召孟明、西乞、白乙，使出师于东门之外。蹇叔哭之，曰：「孟子，吾见师之出而不见其入也。」公使谓之曰：「尔何知？中寿，尔墓之木拱矣。」蹇叔之子与师，哭而送之，曰：「晋人御师必于殽。殽有二陵焉。其南陵，夏后皋之墓也；其北陵，文王之所辟风雨也。必死是间，余收尔骨焉。」秦师遂东。', '', '', '三十二年春，楚国鬥章请求与晋国媾和，晋国的阳处父回报。晋国、楚国从此开始正式交往。
夏，狄国发生动乱。卫国人侵犯狄国，狄国请求媾和。秋，卫国人与狄国结盟。
冬，晋文公去世。庚辰日，将在曲沃殡葬。离开绛城，棺柩中有声音像牛叫。卜偃让大夫跪拜，说：“君主命令大事，将有西边的军队超越国境袭我，攻击他们，必能大捷。”
杞子从郑国派人告诉秦国，说：“郑国人让我掌管他们北门的钥匙，如果你们偷偷前来，郑国就可以得到了。”秦穆公拜访蹇叔，蹇叔说：“疲劳的军队远袭，我没有听说过。军队劳累力量用尽，远方的主人有准备，恐怕不行吧。我们军队一动，郑国必然知晓。费力不讨好，士兵必然有抵触情绪。而且行动千里，有谁不知？”秦穆公不接受意见。召孟明、西乞、白乙，让他们从东门外出兵。蹇叔哭着送行，说：“孟先生，我看到军队出去而看不到回来了。”秦穆公派人告诉他说：“你怎么知道？如果你中年死去，你坟墓上的树木已经合抱了。”蹇叔的儿子随从军队，蹇叔哭着送他，说：“晋国人必定在殽山抵御我们。殽山有两座坟陵，它的南陵，是夏后皋的陵墓，它的北陵，是周文王躲避风雨之地。你必定死在两座陵墓之间，我会去那里收你的尸骨。”秦国军队于是向东出发。
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b6635e49f46528a431c69", "shortContent": "晋在城濮之战中打败了楚国之后，成为称霸中原的盟主，抑制了秦国向东的扩张，两国之间的关系开始紧张。然而由于晋文公之妻是秦穆公之女，文公又是在穆公的支持下才登上晋国君主之位的，所以两国仍然维持着良好的关系。公元前630年，晋曾约秦共同围郑。但是在晋文公去世以后，形势发生了变化。秦穆公趁晋国新君登临大位未稳之机，偷袭郑国，企图将它一举吞并，这样，就揭开了秦晋殽之战的序幕。这一场伏击歼灭战发生于公元前62...", "authors": ["熊岳", "邱轶皓"], "pressName": "上海辞书出版社"}]', '', 'indent', 1558951894, '5ceb4754a673f50068158e81', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642963, '左传 · 僖公 · 僖公三十三年', NULL, 0, 12, 0, 2, '公羊高', NULL, 36789, '586e4843b123db005d0e97e6', '秦', 'wen', '文', '', '', '【经】三十有三年春王二月，秦人入滑。齐侯使国归父来聘。夏四月辛巳，晋人及姜戎败秦师于殽。癸巳，葬晋文公。狄侵齐。公伐邾，取訾娄。秋，公子遂帅师伐邾。晋人败狄于箕。冬十月，公如齐。十有二月，公至自齐。乙巳，公薨于小寝。陨霜不杀草。李梅实。晋人、陈人、郑人伐许。
【传】三十三年春，秦师过周北门，左右免胄而下。超乘者三百乘。王孙满尚幼，观之，言于王曰：「秦师轻而无礼，必败。轻则寡谋，无礼则脱。入险而脱。又不能谋，能无败乎？」及滑，郑商人弦高将市于周，遇之。以乘韦先，牛十二犒师，曰：「寡君闻吾子将步师出于敝邑，敢犒从者，不腆敝邑，为从者之淹，居则具一日之积，行则备一夕之卫。」且使遽告于郑。
则束载、厉兵、秣马矣。使皇武子辞焉，曰：「吾子淹久于敝邑，唯是脯资饩牵竭矣。为吾子之将行也，郑之有原圃，犹秦之有具囿也。吾子取其麋鹿以闲敝邑，若何？」杞子奔齐，逢孙、扬孙奔宋。孟明曰：「郑有备矣，不可冀也。攻之不克，围之不继，吾其还也。」灭滑而还。
齐国庄子来聘，自郊劳至于赠贿，礼成而加之以敏。臧文仲言于公曰：「国子为政，齐犹有礼，君其朝焉。臣闻之，服于有礼，社稷之卫也。」
晋原轸曰：「秦违蹇叔，而以贪勤民，天奉我也。奉不可失，敌不可纵。纵敌患生，违天不祥。必伐秦师。」栾枝曰：「未报秦施而伐其师，其为死君乎？」先轸曰：「秦不哀吾丧而伐吾同姓，秦则无礼，何施之为？吾闻之，一日纵敌，数世之患也。谋及子孙，可谓死君乎？」遂发命，遽兴姜戎。子墨衰絰，梁弘御戎，莱驹为右。
夏四月辛巳，败秦师于殽，获百里孟明视、西乞术、白乙丙以归，遂墨以葬文公。晋于是始墨。
文嬴请三帅，曰：「彼实构吾二君，寡君若得而食之，不厌，君何辱讨焉！使归就戮于秦，以逞寡君之志，若何？」公许之，先轸朝。问秦囚。公曰：「夫人请之，吾舍之矣。」先轸怒曰：「武夫力而拘诸原，妇人暂而免诸国。堕军实而长寇仇，亡无日矣。」不顾而唾。公使阳处父追之，及诸河，则在舟中矣。释左骖，以公命赠孟明。孟明稽首曰：「君之惠，不以累臣衅鼓，使归就戮于秦，寡君之以为戮，死且不朽。若从君惠而免之，三年将拜君赐。」
秦伯素服郊次，乡师而哭曰：「孤违蹇叔以辱二三子，孤之罪也。不替孟明，孤之过也。大夫何罪？且吾不以一眚掩大德。」
狄侵齐，因晋丧也。
公伐邾，取訾娄，以报升陉之役。邾人不设备。秋，襄仲复伐邾。
狄伐晋，及箕。八月戊子，晋侯败狄于箕。郤缺获白狄子。先轸曰：「匹夫逞志于君而无讨，敢不自讨乎？」免胄入狄师，死焉。狄人归其元，面如生。
初，臼季使过冀，见冀缺耨，其妻盍之。敬，相待如宾。与之归，言诸文公曰：「敬，德之聚也。能敬必有德，德以治民，君请用之。臣闻之，出门如宾，承事如祭，仁之则也。」公曰：「其父有罪，可乎？」对曰：「舜之罪也殛鲧，其举也兴禹。管敬仲，桓之贼也，实相以济。《康诰》曰：『父不慈，子不祗，兄不友，弟不共，不相及也。』《诗》曰：『采葑采菲，无以下体。』君取节焉可也。」文公以为下军大夫。反自箕，襄公以三命命先且居将中军，以再命命先茅之县赏胥臣曰：「举郤缺，子之功也。」以一命命郤缺为卿，复与之冀，亦未有军行。
冬，公如齐，朝，且吊有狄师也。反，薨于小寝，即安也。
晋、陈、郑伐许，讨其贰于楚也。
楚令尹子上侵陈、蔡。陈、蔡成，遂伐郑，将纳公子瑕，门于桔柣之门。瑕覆于周氏之汪，外仆髡屯禽之以献。文夫人敛而葬之郐城之下。
晋阳处父侵蔡，楚子上救之，与晋师夹泜而军。阳子患之，使谓子上曰：「吾闻之，文不犯顺，武不违敌。子若欲战，则吾退舍，子济而陈，迟速唯命，不然纾我。老师费财，亦无益也。」乃驾以待。子上欲涉，大孙伯曰：「不可。晋人无信，半涉而薄我，悔败何及，不如纾之。」乃退舍。阳子宣言曰：「楚师遁矣。」遂归。楚师亦归。大子商臣谮子上曰：「受晋赂而辟之，楚之耻也，罪莫大焉。」王杀子上。
葬僖公，缓作主，非礼也。凡君薨，卒哭而祔，祔而作主，特祀于主，烝尝禘于庙。', '', '', '', NULL, '', 'indent', 1558951937, '5ceb477d30863b0068268280', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642964, '左传 · 文公 · 文公元年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】元年春王正月，公即位。二月癸亥，日有食之。天王使叔服来会葬。夏四月丁巳，葬我君僖公。天王使毛伯来锡公命。晋侯伐卫。叔孙得臣如京师。卫人伐晋。秋，公孙敖会晋侯于戚。冬十月丁未，楚世子商臣弑其君頵。公孙敖如齐。
【传】元年春，王使内史叔服来会葬。公孙敖闻其能相人也，见其二子焉。叔服曰：「谷也食子，难也收子。谷也丰下，必有后于鲁国。」
于是闰三月，非礼也。先王之正时也，履端于始，举正于中，归余于终。履端于始，序则不愆。举正于中，民则不惑。归余于终，事则不悖。
夏四月丁巳，葬僖公。
王使毛伯卫来锡公命。叔孙得臣如周拜。
晋文公之季年，诸侯朝晋。卫成公不朝，使孔达侵郑，伐绵、訾，及匡。晋襄公既祥，使告于诸侯而伐卫，及南阳。先且居曰：「效尤，祸也。请君朝王，臣从师。」晋侯朝王于温，先且居、胥臣伐卫。五月辛酉朔，晋师围戚。六月戊戌，取之，获孙昭子。
卫人使告于陈。陈共公曰：「更伐之，我辞之。」卫孔达帅师伐晋，君子以为古。古者越国而谋。
秋，晋侯疆戚田，故公孙敖会之。
初，楚子将以商臣为大子，访诸令尹子上。子上曰：「君之齿未也。而又多爱，黜乃乱也。楚国之举。恒在少者。且是人也。蜂目而豺声，忍人也，不可立也。」弗听。既又欲立王子职而黜大子商臣。商臣闻之而未察，告其师潘崇曰：「若之何而察之？」潘崇曰：「享江问而勿敬也。」从之。江芈怒曰：「呼，役夫！宜君王之欲杀女而立职也。」告潘崇曰：「信矣。」潘崇曰：「能事诸乎？」曰：「不能。」「能行乎？」曰：「不能。」「能行大事乎？」曰：「能。」
冬十月，以宫甲围成王。王请食熊蹯而死。弗听。丁未，王缢。谥之曰：「灵」，不瞑；曰：「成」，乃瞑。穆王立，以其为大子之室与潘崇，使为大师，且掌环列之尹。
穆伯如齐，始聘焉，礼也。凡君即位，卿出并聘，践修旧好，要结外授，好事邻国，以卫社稷，忠信卑让之道也。忠，德之正也；信，德之固也；卑让，德之基也。
殽之役，晋人既归秦帅，秦大夫及左右皆言于秦伯曰：「是败也，孟明之罪也，必杀之。」秦伯曰：「是孤之罪也。周芮良夫之诗曰；『大风有隧，贪人败类，听言则对，诵言如醉，匪用其良，覆俾我悖。』是贪故也，孤之谓矣。孤实贪以祸夫子，夫子何罪？」复使为政。
', '', '', '元年春季，周襄王派遣内史叔服来鲁国参加僖公的葬礼。公孙敖听说叔服能给人看相，便引出自己两个儿子穀和难来见他。叔服说：“穀可以祭祀供养您，难可以安葬您。穀的下颔丰满，后代在鲁国必然昌大。”
今年闰三月，这是不合传统习惯的。先王端正时令，年历的推算以冬至作为开始，测定春分、秋分、夏至、冬至的月份作为四季的中月，把剩余的日子归在一年的末尾。年历的推算以冬至作为开始，四季的次序就不会错乱；以正朔的月份作为标准，百姓就不会迷惑；把剩余的月份归总在一年的终了置闰月，事情就不会差误。
夏季，四月二十六日，安葬僖公。周襄王派遣毛伯卫来鲁国赐给鲁文公写在竹简上的奖状。叔孙得臣到成周答谢。
晋文公的晚年，诸侯朝见晋国，卫成公不去朝见，反而派遣孔达侵袭郑国，攻打绵、訾和匡地。晋襄公在举行小祥祭祀以后，派人通告诸侯而讨伐卫国，到达南阳。先且居说：“学坏样子，这是祸害。请您朝觐周天子，下臣跟随军队。”晋襄公在温地朝觐了周襄王。先且居、胥臣进攻卫国。五月初一日，晋军包围戚地。六月初八日，占取戚地，俘虏了孙昭子。
卫国人派人报告陈国。陈共公说：“转过去进攻他们。我去对他们说。”卫国的孔达就率兵进攻晋国。君子认为，这样做属于过于粗心。粗心，指的是让别国给自己出主意。
秋季，晋襄公划定戚地田土的疆界，所以公孙敖参加了。
当初，楚成王打算立商臣为太子，征求令尹子上的意见。子上说：“君王的年纪还不算大，而且内宠又多，立了商臣再加以废黜，就会有祸乱。楚国立太子，常常选择年轻的。而且商臣这个人，眼睛像胡蜂，声音像豺狼，是一个残忍的人，不能立为太子。”楚成王没有听从。立了商臣以后，又想立王子职而废掉太子商臣。商臣听到消息但还没有弄准确，告诉他老师潘崇说：“怎么样能弄准确？”潘崇说：“你设宴招待江芈而故意表示不尊敬。”商臣这样做了。江芈发怒说：“啊！贱东西！难怪君王要杀掉你而立职做太子。”商臣告诉潘崇说：“事情确实了。”潘崇说：“你能事奉公子职吗？”商臣说：“不能。”潘崇说：“能逃亡出国吗？”商臣说：“不能。”潘崇说：“能够办大事吗？”商臣说：“能。”
冬季，十月，商臣率领宫中的警卫军包围楚成王，并且逼成王自杀。成王请求吃了熊掌以后去死，商臣不答应。十八日，楚成王上吊而死。给他上谥号称为“灵”，尸体不闭眼睛；谥为“成”，才闭上眼睛。楚穆王即位，把他做太子时的房屋财物给了潘崇，让潘崇做太师，而且作为掌管宫中警卫军的长官。
穆伯到齐国去，开始聘问，这是合于礼的。凡是国君即位，卿出国普遍聘问，继续重温过去的友好，团结外援，善待邻国，来保卫国家，这是合于忠、信、卑让的。忠，意味政治道德的纯正；信，意味政治道德的巩固；卑让，意味政治道德有基础。
殽地这次战役，晋国放回了秦国的主将，秦国的大夫和左右待臣都对秦穆公说：“这次战败，是孟明的罪过，一定要杀死他。”秦穆公说：“这是我的罪过。周朝芮良夫的诗说：‘大风迅猛把一切摧毁，贪婪的人把善良败坏。听到不相干的就喜欢插嘴，听到《诗》、《书》就打瞌睡，不能任用有才能的人，反而使我和道义相背。’这是由于贪婪的缘故，说的就是我啊。我由于贪婪而使孟明受祸，孟明有什么罪？”重新让孟明执政。
', NULL, '', 'indent', 1558951982, '5ceb47ab30863b006826859d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642965, '左传 · 文公 · 文公二年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二年春王二月甲子，晋侯及秦师战于彭衙，秦师败绩。丁丑，作僖公主。三月乙巳，及晋处父盟。夏六月，公孙敖会宋公、陈侯、郑伯、晋士縠盟于垂陇。自十有二月不雨，至于秋七月。八月丁卯，大事于大庙，跻僖公。冬，晋人、宋人、陈人、郑人伐秦。公子遂如齐纳币。
【传】二年春，秦孟明视帅师伐晋，以报殽之役。二月晋侯御之。先且居将中军，赵衰佐之。王官无地御戎，狐鞫居为右。甲子，及秦师战于彭衙。秦师败绩。晋人谓秦「拜赐之师」。
战于殽也，晋梁弘御戎，莱驹为右。战之明日，晋襄公缚秦囚，使莱驹以戈斩之。囚呼，莱驹失戈，狼瞫取戈以斩囚，禽之以从公乘，遂以为右。箕之役，先轸黜之而立续简伯。狼瞫怒。其友曰：「盍死之？」瞫曰：「吾未获死所。」其友曰：「吾与女为难。」瞫曰；「《周志》有之，『勇则害上，不登于明堂。』死而不义，非勇也。共用之谓勇。吾以勇求右，无勇而黜，亦其所也。谓上不我知，黜而宜，乃知我矣。子姑待之。」及彭衙，既陈，以其属驰秦师，死焉。晋师从之，大败秦师。君子谓：「狼瞫于是乎君子。诗曰：『君子如怒，乱庶遄沮。』又曰：『王赫斯怒，爰整其旅。』怒不作乱而以从师，可谓君子矣。」
秦伯犹用孟明。孟明增修国政，重施于民。赵成子言于诸大夫曰：「秦师又至，将必辟之，惧而增德，不可当也。诗曰：『毋念尔祖，聿修厥德。』孟明念之矣，念德不怠，其可敌乎？」
丁丑，作僖公主，书，不时也。
晋人以公不朝来讨，公如晋。夏四月己巳，晋人使阳处父盟公以耻之。书曰：「及晋处父盟。」以厌之也。适晋不书，讳之也。公未至，六月，穆伯会诸侯及晋司空士縠盟于垂陇，晋讨卫故也。书士縠，堪其事也。
陈侯为卫请成于晋，执孔达以说。
秋八月丁卯，大事于大庙，跻僖公，逆祀也。于是夏父弗忌为宗伯，尊僖公，且明见曰：「吾见新鬼大，故鬼小。先大后小，顺也。跻圣贤，明也。明、顺，礼也。」
君子以为失礼。礼无不顺。祀，国之大事也，而逆之，可谓礼乎？子虽齐圣，不先父食久矣。故禹不先鲧，汤不先契，文、武不先不窋。宋祖帝乙，郑祖厉王，犹上祖也。是以《鲁颂》曰：「春秋匪解，享祀不忒，皇皇后帝，皇祖后稷。」君子曰礼，谓其后稷亲而先帝也。《诗》曰：「问我诸姑，遂及伯姊。」君子曰礼，谓其姊亲而先姑也。仲尼曰：「臧文仲，其不仁者三，不知者三。下展禽，废六关，妾织蒲，三不仁也。作虚器，纵逆祀，祀爰居，三不知也。」
冬，晋先且居、宋公子成、陈辕选、郑公子归生伐秦，取汪，及彭衙而还，以报彭衙之役。卿不书，为穆公故，尊秦也，谓之崇德。
襄仲如齐纳币，礼也。凡君即位，好舅甥，修昏姻，娶元妃以奉粢盛，孝也。孝，礼之始也。
', '', '', '二年春季，秦国的孟明视领兵攻打晋国，以报复殽地这次战役。二月，晋襄公抵抗秦军，先且居率领中军，赵衰辅助他。王官无地为先且居驾御战车，狐鞫居作为车右。二月七日，和秦军在彭衙作战，秦军大败。晋国人说这是秦国“拜谢恩赐的战役”。
在殽地作战的时候，晋国的梁弘为晋襄公驾御战车，莱驹作为车右。作战的第二天，晋襄公捆绑了秦国的俘虏，派莱驹用戈去杀他们，俘虏大声喊叫，莱驹把戈掉在地上，狼瞫拿起戈砍了俘虏的头，抓起莱驹追上了晋襄公的战车，晋襄公就让他作为车右。箕地这一战役，先轸废掉了狼瞫，而以续简伯作为车右。狼瞫发怒。他的朋友说：“为什么不去死？”狼瞫说：“我没有找到死的地方。”他的朋友说：“我跟你一起发难杀死先轸。”狼瞫说：“《周志》有这样的话：‘勇敢如果杀害在上的人，死后不能进入明堂。’死而不合于道义，这不是勇敢。为国家所用叫做勇敢，我用勇敢得到了车右，没有勇敢而被废黜，也是合适的。如果说上面的人不了解我，废黜得得当，就是了解我了。您姑且等着吧！”到达彭衙，摆开阵势以后，狼瞫率领部下冲进秦军的队伍，死在阵地上。晋军跟着上去，把秦军打得大败。君子认为：“狼瞫由于这样可以算得君子了。《诗》说：‘君子如果发怒，动乱就可以很快阻止。’又说：‘文王勃然大怒，于是就整顿军队。’发怒不去作乱，反而上去打仗，可以说是君子了。”
秦穆公还是任用孟明。孟明进一步修明政事，给百姓以优厚的待遇。赵成子对大夫们说：“秦军如果再一次前来，必定要避开它。由于畏惧而进一步修明了德行，那是不能抵挡的。《诗》说：‘怀念着你的祖先，修明你的德行。’孟明想到这两句诗了。想到德行而努力不懈，难道可以抵挡吗？”
二十日，制作僖公的神主牌位。《春秋》之所以记载，是由于制作不及时。
晋国人由于鲁文公不去朝见而前来讨伐。文公去了晋国。夏季，四月十三日，晋国派阳处父和文公结盟来羞辱他。《春秋》记载说“及晋处父盟”，这是表示厌恶的意思。到晋国去而不加记载，这是出于隐讳。
鲁文公没有到达鲁国，六月，穆伯在垂陇和诸侯以及晋国司空士縠结盟，这是由于晋国攻打卫国的缘故。《春秋》记载称为“士縠”，是由于认为他能够胜任。陈共公为卫国向晋国求和，拘捕了孔达以向晋国解说。
秋季，八月十三日，在太庙祭祀，升僖公的神位在闵公之上，这是不按顺序的祭祀。当时夏父弗忌担任宗伯，尊崇僖公，而且宣布他所见到的说：“我见到新鬼大，旧鬼小，先大后小，这是顺序。使圣上升位，这是明智。明智、顺序，这是合于礼的。”君子认为，这样做是失礼。礼没有不合顺序的。祭祀是国家的大事，不按顺序，难道能说合于礼吗？儿子虽然聪明圣哲，不能在父亲之前享受祭品，由来己久。所以禹不能在鲧之前，汤不能在契之前，文王、武王不能在窋之前。宋国以帝乙为祖宗，郑国以厉王为祖宗，这还是对祖宗的尊崇。所以《鲁颂》说：“一年四季的祭祀不懈怠，没有差错，致祭于上帝，又致祭于伟大的祖先后稷。”君子说这合于礼，说的是后稷虽然亲近，然而却先称上帝。《诗》说：“问候我的姑母们，再问候到各位姐姐。”君子说这合于礼，说的是姐姐虽然亲近，然而却先称姑姑。孔子说：“臧文仲，他不仁爱的事情有三件，不聪明的事情有三件。使展禽居于下位，设立六个关口，小老婆织席贩卖，这是三件不仁爱的事情。养一个大乌龟、迷信卜卦，纵容不合顺序的祭祀，祭祀海鸟爰居，这是三件不聪明的事情。”
冬季，晋国先且居、宋国公子成、陈国辕选、郑国公子归生攻打秦国，占取了汪地和彭衙，然后回国，以报复上次彭衙的战役。卿的名字不加记载，这是为了穆公的缘故。尊重秦国，叫做尊重德行。襄仲到齐国致送玉帛财礼，这是合于礼的。凡是国君即位，加强舅甥国家间的友好，办理婚姻的事，娶元配夫人来主持祭祀，这是孝道。孝道，是礼的开始。', NULL, '', 'indent', 1558952026, '5ceb47d643e78c00671407d6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643533, '月令七十二候集解 · 寒露', NULL, 0, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '寒露，九月节。露气寒冷，将凝结也。
鸿雁来宾。宾，客也。先至者为主，后至者为宾，盖将尽之谓。雁以仲秋先至者为主，季秋后至者为宾。《通书》作来滨。滨，水际也，亦通。
雀入大水为蛤。雀，小鸟也，其类不一，此为黄雀。大水，海也，《国语》云：雀入大海为蛤。盖寒风严肃，多入于海。变之为蛤，此飞物化为潜物也。蛤，蚌属，此小者也。
菊有黄华。草木皆华于阳，独菊华于阴，故言有桃桐之华皆不言色，而独菊言者，其色正应季秋土旺之时也。', '', '', '', NULL, '', 'indent', 1574374956, '5db29e4917b54d006c1ff350', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642966, '左传 · 文公 · 文公三年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三年春王正月，叔孙得臣会晋人、宋人、陈人、卫人、郑人伐沈。沈溃。夏五月，王子虎卒。秦人伐晋。秋，楚人围江。雨螽于宋。冬，公如晋。十有二月己巳，公及晋侯盟。晋阳处父帅师伐楚以救江。
【传】三年春，庄叔会诸侯之师伐沈，以其服于楚也。沈溃。凡民逃其上曰溃，在上曰逃。
卫侯如陈，拜晋成也。
夏四月乙亥，王叔文公卒，来赴吊如同盟，礼也。
秦伯伐晋，济河焚舟，取王官，及郊。晋人不出，遂自茅津济，封殽尸而还。遂霸西戎，用孟明也。君子是以知「秦穆公之为君也，举人之周也，与人之壹也；孟明之臣也，其不解也，能惧思也；子桑之忠也，其知人也，能举善也。《诗》曰：『于以采蘩，于沼于沚，于以用之公侯之事』，秦穆有焉。『夙夜匪解，以事一人』，孟明有焉。『诒阙孙谋，以燕翼子』，子桑有焉。」
秋，雨螽于宋，队而死也。
楚师围江。晋先仆伐楚以救江。
冬，晋以江故告于周。王叔桓公、晋阳处父伐楚以救江，门于方城，遇息公子朱而还。
晋人惧其无礼于公也，请改盟。公如晋，及晋侯盟。晋侯飨公，赋《菁菁者莪》。庄叔以公降，拜，曰：「小国受命于大国，敢不慎仪。君贶之以大礼，何乐如之。抑小国之乐，大国之惠也。」晋侯降，辞。登，成拜。公赋《嘉乐》。
', '', '', '三年春季，庄叔会合诸侯的军队攻打沈国，因为沈国向楚国顺服，沈国百姓溃散。凡是百姓逃避他们上级叫做“溃”，上级逃走叫做“逃”。卫成公到陈国去，这是为了拜谢陈国促成的卫、晋和议。
夏季，四月二十四日，王叔文公死，发来讣告，像对同盟国一样去吊唁，这是合于礼仪的。
秦穆公攻打晋国，渡过黄河，烧掉渡船，占取了王官和郊地。晋军不出战。秦军就从茅津渡黄河，在殽地为死亡的将士筑一个大坟墓，然后回国。秦穆公就此称霸于西方少数民族诸国，这是由于任用了孟明。君子因此知道，秦穆公作为国君，提拔人才考虑全面，任用人才专一无二；孟明作为臣子，努力不懈，能够因为畏惧而思考；子桑忠诚，他了解别人，能够推举好人。《诗》说：“在哪里去采蒿子？在池塘里、在小洲上。在哪里使用它？在公侯的祭祀典礼上。”秦穆公就是这样的。“早晚努力不懈，以事奉在最上层的一个人”，孟明就是这样的。“把谋略留给子孙，以安定和辅佐他们”，子桑就是这样的。
秋季，在宋国有大批螽斯像雨点一样落下来，这是死了以后掉下来的。
楚国的军队包围江国，晋国的先仆攻打楚国去救援江国。
冬季，晋国把江国的事情报告周襄王，王叔桓公、晋国的阳处父攻打楚国以救援江国。攻打方城山关口，并看到了楚国的息公子朱才回国。晋国人为曾经对鲁文公的失礼而感到恐惧，请求改订盟约。文公到了晋国，和晋襄公结盟。晋襄公设享礼招待文公，赋《菁菁者莪》这首诗。庄叔让文公降阶下拜，说：“小国在大国接受命令，岂敢对礼仪有所不谨慎？君王赐我们以重大典礼，还有什么比这再高兴的呢？小国的高兴，是大国的恩赐。”晋襄公走下台阶辞谢，再登上台阶，完成拜礼。文公赋《嘉乐》这首诗。
', NULL, '', 'indent', 1558952063, '5ceb47fcd5de2b007078fa7b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642967, '左传 · 文公 · 文公四年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】四年春，公至自晋。夏，逆妇姜于齐。狄侵齐。秋，楚人灭江。晋侯伐秦。卫侯使宁俞来聘。冬十有一月壬寅，夫人风氏薨。
【传】四年春，晋人归孔达于卫，以为卫之良也，故免之。
夏，卫侯如晋拜。曹伯如晋，会正。
逆妇姜于齐，卿不行，非礼也。君子是以知出姜之不允于鲁也。曰：「贵聘而贱逆之，君而卑之，立而废之，弃信而坏其主，在国必乱，在家必亡。不允宜哉？《诗》曰：『畏天之威，于时保之。』敬主之谓也。」
秋，晋侯伐秦，围刓、新城，以报王官之役。
楚人灭江，秦伯为之降服、出次、不举、过数。大夫谏，公曰：「同盟灭，虽不能救，敢不矜乎！吾自惧也。」君子曰：「《诗》云：『惟彼二国，其政不获，惟此四国，爰究爰度。』其秦穆之谓矣。」
卫宁武子来聘，公与之宴，为赋《湛露》及《彤弓》。不辞，又不答赋。使行人私焉。对曰：「臣以为肄业及之也。昔诸侯朝正于王，王宴乐之，于是乎赋《湛露》，则天子当阳，诸侯用命也。诸侯敌王所忾而献其功，王于是乎赐之彤弓一，彤矢百，玈弓矢千，以觉报宴。今陪臣来继旧好，君辱贶之，其敢干大礼以自取戾。」
冬，成风薨。', '', '', '四年春季，晋国人释放孔达回到卫国，这是由于把他作为卫国的好人材，所以赦免了他。
夏季，卫成公到晋国拜谢释放孔达。曹共公到晋国商谈纳贡的事情。
在齐国迎接姜氏，鲁国的卿没有去迎接，这是不合于礼的。君子因此知道出姜在鲁国不会有好结果，说：“用尊贵的礼节行聘而用低贱的礼节迎接她，身分是国家的第一夫人而轻待她，立为第一夫人而废弃她，丢掉信用而损害妇女之首的身分，这样的事情发生在国家中必然使国家动乱，在家族中必然使家族灭亡。没有好下场是应该的了。《诗》说：‘畏惧上天的威灵，因此就能保有福禄。’这就是说要看重妇女之首这样的身分。”
秋季，晋襄公攻打秦国，包围邧地、新成，以报复王官那次战役。楚国人灭亡了江国，秦穆公为这件事穿上素服，出居别室，减膳撤乐，超过了应有的礼数。大夫劝谏。秦穆公说：“同盟的国家被灭，虽然没有救援，岂敢不哀怜呢？我是自己警惕呀。”君子说：“《诗》说：‘他们两个国家，政事不合法度；四方的国家，只好设法自谋。’秦穆公就是这样的。”卫国的甯武子来鲁国聘问，文公设宴招待他，为他赋《湛露》和《彤弓》两首诗。甯武子没有辞谢，又不赋诗回答。文公派使者私下探问。甯武子回答说：“下臣以为是在练习演奏的。从前诸侯正月去京师向天子朝贺，天子设宴奏乐，在这个时候赋《湛露》这首诗，那就表示天子对着太阳，诸侯听候命令。诸侯把天子所痛恨的人作为敌人，而且献上自己的功劳。天子因为这样而赐给他们红色的弓一把、红色的箭一百枝、黑色的弓十把和箭一千枝，以表彰功劳而用宴乐来报答。现在陪臣前来继续过去的友好，承君王赐宴，哪里敢触犯大礼来自取罪过？”
冬季，成风去世。', NULL, '', 'indent', 1558952107, '5ceb482930863b0068268fef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642968, '左传 · 文公 · 文公五年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】五年春王正月，王使荣叔归含，且賵。三月辛亥，葬我小君成风。王使召伯来会葬。夏，公孙敖如晋。秦人入鄀。秋，楚人灭六。冬十月甲申，许男业卒。
【传】五年春，王使荣叔来含且賵，召昭公来会葬，礼也。
初，鄀叛楚即秦，又贰于楚。夏，秦人入鄀。
六人叛楚即东夷。秋，楚成大心、仲归帅师灭六。
冬，楚公子燮灭蓼，臧文仲闻六与蓼灭，曰：「皋陶庭坚不祀忽诸。德之不建，民之无援，哀哉！」
晋阳处父聘于卫，反过宁，宁嬴从之，及温而还。其妻问之，嬴曰；「以刚。《商书》曰：『沈渐刚克，高明柔克。』夫子壹之，其不没乎。天为刚德，犹不干时，况在人乎？且华而不实，怨之所聚也，犯而聚怨，不可以定身。余惧不获其利而离其难，是以去之。」
晋赵成子，栾贞子、霍伯、臼季皆卒。', '', '', '五年春季，周襄王派遣荣叔前来致送含在死者口中的玉和丧仪，召昭公来参加葬礼，这是符合礼仪的。
当初，鄀国背叛楚国亲近秦国，后来又倾向楚国。夏季，秦国进入鄀国。六国人背叛楚国亲近东夷。秋季，楚国的成大心、仲归带兵灭亡了六国。
冬季，楚国的公子燮灭亡蓼国。臧文仲听到六国和蓼国灭亡，说：“皋陶、庭坚没有人祭祀了。德行不建立，百姓没有人救援，可悲啊！”
晋国的阳处父到卫国聘问，回国时路过甯地，甯嬴愿意跟着他。甯嬴到达温地又回来了，他妻子问他，甯嬴说：“太刚强了。《商书》说：‘深沉的人要用刚强来克服，爽朗的人要用柔弱来克服。’那个人只具备其中之一，恐怕不得善终吧！上天纯阳，属于刚强的德行，尚且不触犯寒暑四时运行的次序，何况人呢？而且华而不实，就会聚集怨恨。触犯别人而聚集怨恨，不能够安定自身。我是害怕不能得到利益反而遭到祸害，因此才离开他。”
晋国的赵成子、栾贞子、霍伯、臼季都已经去世了。
', NULL, '', 'indent', 1558952143, '5ceb484da673f50068159873', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642969, '左传 · 文公 · 文公六年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】六年春，葬许僖公。夏，季孙行父如陈。秋，季孙行父如晋。八月乙亥，晋侯欢卒。冬十月，公子遂如晋。葬晋襄公。晋杀其大夫阳处父。晋狐射姑出奔狄。闰月不告月，犹朝于庙。
【传】六年春，晋蒐于夷，舍二军。使狐射姑将中军，赵盾佐之。阳处父至自温，改蒐于董，易中军。阳子，成季之属也，故党于赵氏，且谓赵盾能，曰：「使能，国之利也。」是以上之。宣子于是乎始为国政，制事典，正法罪。辟狱刑，董逋逃。由质要，治旧污，本秩礼，续常职，出滞淹。既成，以授大傅阳子与大师贾佗，使行诸晋国，以为常法。
臧文仲以陈、卫之睦也，欲求好于陈。夏，季文子聘于陈，且娶焉。
秦伯任好卒。以子车氏之三子奄息、仲行、金咸虎为殉。皆秦之良也。国人哀之，为之赋《黄鸟》。君子曰：「秦穆之不为盟主也，宜哉。死而弃民。先王违世，犹诒之法，而况夺之善人乎！《诗》曰：『人之云亡，邦国殄瘁。』无善人之谓。若之何夺之？」古之王者知命之不长，是以并建圣哲，树之风声，分之采物，着之话言，为之律度，陈之艺极，引之表仪，予之法制，告之训典，教之防利，委之常秩，道之礼则，使毋失其土宜，众隶赖之，而后即命。圣王同之。今纵无法以遗后嗣，而又收其良以死，难以在上矣。君子是以知秦之不复东征也。
秋，季文子将聘于晋，使求遭丧之礼以行。其人曰：「将焉用之？」文子曰：「备豫不虞，古之善教也。求而无之，实难，过求何害？」
八月乙亥，晋襄公卒。灵公少，晋人以难故，欲立长君。赵孟曰：「立公子雍。好善而长，先君爱之，且近于秦。秦，旧好也。置善则固，事长则顺，立爱则孝，结旧则安。为难故，故欲立长君，有此四德者，难必抒矣。贾季曰：「不如立公子乐。辰嬴嬖于二君，立其子，民必安之。」赵孟曰：「辰嬴贱，班在九人，其子何震之有？且为二嬖，淫也。为先君子，不能求大而出在小国，辟也。母淫子辟，无威。陈小而远，无援。将何安焉？杜祁以君故，让逼姞而上之，以狄故，让季隗而己次之，故班在四。先君是以爱其子而仕诸秦，为亚卿焉。秦大而近，足以为援，母义子爱，足以威民，立之不亦可乎？」使先蔑、士会如秦，逆公子雍。贾季亦使召公子乐于陈。赵孟使杀诸郫。贾季怨阳子之易其班也，而知其无援于晋也。九月，贾季使续鞫居杀阳处父。书曰：「晋杀其大夫。」侵官也。
冬十月，襄仲如晋。葬襄公。
十一月丙寅，晋杀续简伯。贾季奔狄。宣子使臾骈送其帑。夷之蒐，贾季戮臾骈，臾骈之人欲尽杀贾氏以报焉。臾骈曰：「不可。吾闻《前志》有之曰：『敌惠敌怨，不在后嗣』，忠之道也。夫子礼于贾季，我以其宠报私怨，无乃不可乎？介人之宠，非勇也。损怨益仇，非知也。以私害公，非忠也。释此三者，何以事夫子？」尽具其帑，与其器用财贿，亲帅扞之，送致诸竟。
闰月不告朔，非礼也。闰以正时，时以作事，事以厚生，生民之道，于是乎在矣。不告闰朔，弃时政也，何以为民？', '', '', '六年春季，晋国在夷地检阅军队，撤去两个军。让狐姑射率领中军，赵盾辅助他。阳处父从温地来，改在董地检阅军队，调换了中军主将。阳子，原是成季（赵衰）的下属，所以偏向赵氏，而且认为赵盾富有才能，说：“任用能干的人，这是国家的利益。”所以使赵盾居于上位。赵宣子从这时开始掌握国家的政权，制定章程，修订法令，清理诉讼，督察逃亡，使用契约，清除政治上的污垢，恢复被破坏的次序，重建已经废弃的官职，提拔被压抑的贤能。政令法规完成以后，交给太傅阳子和太师贾佗，使之在晋国推行，作为经常的法则。
臧文仲由于陈、卫两国和睦，想要讨好陈国。夏季，季文子到陈国聘问，同时娶了家室。
秦穆公任好死了，用子车氏的三个儿子奄息、仲行、鍼虎殉葬，这三个人都是秦国的杰出人物。国都的人哀悼他们，为他们赋了《黄鸟》这首诗。君子说：“秦穆公没有当上盟主，活该！死了以后还抛弃百姓。以前的国君离世，还留下了法度，而何况夺百姓的好人呢？《诗》说：‘贤人的死亡，国家就困乏损伤。’这就是说没有好人。为什么还去夺走好人呢？古代身居王位的人知道寿命不能长久，因此就普遍选出贤能，给他们树立风气教化，分给他们旗帜服装，把对他们有益的话记录在典册上，为他们制订法度，对他们公布准则，设立表率来引导他们，给予规章让他们使用，告诉他们先王遗留下来的训导，教育他们防止谋求私利，委任他们一定的职务，开导他们使之合于礼仪，让他们不要违背了因地制宜，让大家都信赖他们，然后到死为止。这样的做法，圣人和先王都是相同的。现在即使没有法则留给后代，反而将杰出人物作为殉葬，这就难于处在上面了。”君子因此而知道秦国再也无法向东征伐了。
秋季，季文子准备到晋国聘问，让人代他请求如果遭到丧事以后应得的礼仪然后才动身。随行的人说：“准备了做什么用？”文子说：“预备好意外的事，这是古代的好教训。临时去请求而没有得到，这会遇到困难。所得虽然一时用不着，有什么害处？”
八月十四日，晋襄公死了。晋灵公年幼，晋国人由于发生祸难的缘故，要立年长的国君。赵孟说：“立公子雍为君。他乐于行善而且年长，先君宠爱他，而且为秦国所亲近。秦国，是老朋友了。能安排好人就巩固，立年长的人就名正言顺，立先君所爱就合于孝道，结交老朋友就安定。因为祸难的缘故，所以要立年长的国君。有了这四项德行的人，祸难就必定可以缓和了。”贾季说：“不如立公子乐。辰嬴受到两位国君的宠爱，立她的儿子，百姓必然安定。”赵孟说：“辰嬴低贱，位次第九，她的儿子有什么威严呢？而且为两位国君所宠幸，这是淫荡。作为先君的儿子，不能求得大国而出居小国，这是鄙陋。母亲淫荡，儿子鄙陋，就没有威严；陈国小而且远，有事不能救援，怎么能安定呢？杜祁由于国君的缘故，让位给偪姞而使她在上；由于狄人的缘故，让位给季隗而自己居她之下，所以位次第四。先君因此喜欢她的儿子，让他在秦国做官，做到亚卿。秦国大而且近，有事足以救援；母亲具有道义，儿子受到喜欢，足以威临百姓。立公子雍，不也可以吗？”派先蔑、士会到秦国迎接公子雍。贾季也派人到陈国召回公子乐。赵孟派人在郫地杀了公子乐。贾季怨恨阳子改变他的地位，又知道他在晋国没有人援助。九月，贾季派续鞠居杀死阳处父。《春秋》记载说“晋杀其大夫”，这是由于阳处父侵夺了官职的缘故。
冬季十月，襄仲到晋国参加晋襄公的葬礼。
十一月某一天，晋国杀了续简伯。贾季逃亡到狄。宣子派臾骈把他的妻子儿女送到他那里去。在夷地阅兵的时侯，贾季曾经侮辱过臾骈。臾骈手下的人因此要杀尽贾氏来图报复。臾骈说：“不行。我听说《前志》上有这样的话：‘有惠于人或有怨于人，和他的后代无关，这合于忠诚之道。’他老人家对贾季表示礼貌，我因为受到他的宠信而报复自己的私怨，恐怕不可以吧！因为别人的宠信而去报复，这不是勇敢。消减怨气而增加仇恨，这不是明智。以私害公，这不是忠诚。舍弃了这三条，用什么去事奉他老人家？”所以就把贾季的妻儿以及他们的器用财货准备齐全，亲自领头保卫，把他们送到边境上。
闰月不举行告朔的仪式，这是不合于礼仪的。闰用来补正四时，根据四时来安排农事，农事合于时令可以使百姓富裕，养活百姓的方法就在于此了。不举行闰月告朔仪式，这是放弃了施政的时令，怎么能治理百姓？', NULL, '', 'indent', 1558952179, '5ceb4871ba39c800687e75fe', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642970, '左传 · 文公 · 文公七年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】七年春，公伐邾。三月甲戌，取须句。遂城郚。夏四月，宋公王臣卒。宋人杀其大夫。戊子，晋人及秦人战于令狐。晋先蔑奔秦。狄侵我西鄙。秋八月，公会诸侯、晋大夫盟于扈。冬，徐伐莒。公孙敖如莒莅盟。
【传】七年春，公伐邾。间晋难也。
三月甲戌，取须句，置文公子焉，非礼也。
夏四月，宋成公卒。于是公子成为右师，公孙友左师，乐豫为司马，鳞矔为司徒，公子荡为司城，华御事为司寇。
昭公将去群公子，乐豫曰：「不可。公族，公室之枝叶也，若去之则本根无所庇荫矣。葛藟犹能庇其本根，故君子以为比，况国君乎？此谚所谓庇焉而纵寻斧焉者也。必不可，君其图之。亲之以德，皆股肱也，谁敢携贰？若之何去之？」不听。穆、襄之族率国人以攻公，杀公孙固、公孙郑于公宫。六卿和公室，乐豫舍司马以让公子卬，昭公即位而葬。书曰：「宋人杀其大夫。」不称名，众也，且言非其罪也。
秦康公送公子雍于晋，曰：「文公之入也无卫，故有吕、郤之难。」乃多与之徒卫。穆赢日抱大子以啼于朝，曰：「先君何罪？其嗣亦何罪？舍适嗣不立而外求君，将焉置此？」出朝，则抱以适赵氏，顿首于宣子曰：「先君奉此子也而属诸子，曰：『此子也才，吾受子之赐；不才，吾唯子之怨。』今君虽终，言犹在耳，而弃之，若何？」宣子与诸大夫皆患穆嬴，且畏逼，乃背先蔑而立灵公，以御秦师。箕郑居守。赵盾将中军，先克佐之。荀林父佐上军。先蔑将下军，先都佐之，步招御戎，戎津为右。及堇阴，宣子曰：「我若受秦，秦则宾也；不受，寇也。既不受矣，而复缓师，秦将生心。先人有夺人之心，军之善谋也。逐寇如追逃，军之善政也。」训卒利兵，秣马蓐食，潜师夜起。戊子，败秦师于令狐，至于刳首。己丑，先蔑奔秦。士会从之。
先蔑之使也，荀林父止之，曰：「夫人、大子犹在，而外求君，此必不行。子以疾辞，若何？不然，将及。摄卿以往可也，何必子？同官为寮，吾尝同寮，敢不尽心乎！」弗听。为赋《板》之三章。又弗听。及亡，荀伯尽送其帑及其器用财贿于秦，曰：「为同寮故也。」
士会在秦三年，不见士伯。其人曰：「能亡人于国，不能见于此，焉用之？」士季曰：「吾与之同罪，非义之也，将何见焉？」及归，遂不见。
狄侵我西鄙，公使告于晋。赵宣子使因贾季问酆舒。且让之。酆舒问于贾季曰：「赵衰、赵盾孰贤？」对曰：「赵衰，冬日之日也。赵盾，夏日之日也。」
秋八月，齐侯、宋公、卫侯、郑伯、许男、曹伯会晋赵盾盟于扈，晋侯立故也。公后至，故不书所会。凡会诸侯，不书所会，后也。后至，不书其国，辟不敏也。
穆伯娶于莒，曰戴己，生文伯，其娣声己生惠叔。戴己卒，又聘于莒，莒人以声己辞，则为襄仲聘焉。
冬，徐伐莒。莒人来请盟。穆伯如莒莅盟，且为仲逆。及鄢陵。登城见之，美，自为娶之。仲请攻之，公将许之。叔仲惠伯谏曰：「臣闻之，兵作于内为乱，于外为寇，寇犹及人，乱自及也。今臣作乱而君不禁，以启寇仇，若之何？」公止之，惠伯成之。使仲舍之，公孙敖反之，复为兄弟如初。从之。
晋郤缺言于赵宣子曰：「日卫不睦，故取其地，今已睦矣，可以归之。叛而不讨，何以示威？服而不柔，何以示怀？非威非怀，何以示德？无德，何以主盟？子为正卿，以主诸侯，而不务德，将若之何？《夏书》曰：『戒之用休，董之用威，劝之以《九歌》，勿使坏。』九功之德皆可歌也，谓之九歌。六府、三事，谓之九功。水、火、金、木、土、谷，谓之六府。正德、利用、厚生，谓之三事。义而行之，谓之德、礼。无礼不乐，所由叛也。若吾子之德莫可歌也，其谁来之？盍使睦者歌吾子乎？」宣子说之。', '', '', '七年春季，鲁文公发兵攻打邾国，这是鲁国利用晋国内乱的空子。三月十七日，占取须句，让邾文公的儿子当守官，这是不合于礼仪的。
夏季，四月，宋成公死了。这时候公子成做右师，公孙友做左师，乐豫做司马，鳞矔做司徒，公子荡做司城，华御事做司寇。宋昭公准备杀死公子们。乐豫说：“不行。公族，是公室的枝叶，如果去掉它，那么树干树根就没有遮盖了。葛藟还能遮蔽它的躯干和根子，所以君子以它作为比喻，何况是国君呢？这就是俗话所说‘树阴遮蔽，偏偏使用斧子’，一定不可以。君王要考虑一下，如果用德行去亲近他们，那就都是左右辅弼的臣子，谁敢有二心？怎么要杀他们呢？”宋昭公不听。穆公、襄公的族人率领国内的人们攻打昭公，在宫里杀了公孙固和公孙郑。六卿和公室讲和，乐豫放弃了司马的官职来让给公子卬。昭公即位后安葬被杀的人。《春秋》记载说：“宋人杀其大夫”，不记载名字，这是由于人多而且他们没有罪。
秦康公送公子雍到晋国，说：“晋文公回国的时候没有卫士，所以有吕、郤发动的祸难。”于是就多给他步兵卫士。穆嬴每天抱着太子在朝廷上啼哭，说：“先君有什么罪？他的合法继承人有什么罪？丢开嫡子不立，反而到外边去求国君，你们准备怎样安置这个孩子？”出了朝廷，就抱着孩子到赵氏家去，向赵盾叩头，说：“先君捧着这个孩子嘱托给您，说：‘这个孩子如果成材，我就是受了您的赐予；如果不成材，我就要怨您。’现在国君虽然去世，话音还在耳边，现在反而丢掉它，怎么办？”赵盾和大夫们都怕穆嬴，而且害怕威逼，就背弃了先蔑而立灵公为君，并且发兵抵御秦国军队。箕郑留守。赵盾率领中军，先克辅助他；荀林父辅助上军；先蔑率领下军，先都辅助他。步招为赵盾驾御战车，戎津作为车右。到达堇阴。赵盾说：“我们如果接受秦国送公子雍回来，他们就是客人；不接受，他们就是敌人。已经不接受了，而又慢慢地出兵，秦国将会动别的念头。争取主动而有夺取敌人的决心，这是作战的好谋略。驱逐敌人好像追赶逃亡者，这是作战的好战术。”于是就训练士兵，磨砺武器，把马喂饱，让部队吃饱，隐蔽行动，夜里出兵。四月初一日，在令狐打败秦军，一直追到刳首。初二日，先蔑逃亡到秦国，士会跟着他。
先蔑出使秦国的时候，荀林父劝阻他，说：“夫人和太子还在，反而到外边去求国君，这一定是行不通的。您以生病作借口，行吗？不这样，祸患将会惹到您身上。派一个代理卿前去就可以了，为什么一定要您去？在一起做官就是‘寮’，我曾经和您同寮，岂敢不尽我的心意呢？”先蔑没有听从。荀林父为他赋《板》这首诗的第三章，又没有听从。等到逃亡出国，荀林父把他的妻子儿女和财货全部送到秦国，说：“这是为了同寮的缘故。”
士会在秦国三年，没有和先蔑见面。随行的人说：“能和别人一起逃亡到这个国家，而不能在这里见面，那有什么用处？”士会说：“我和他罪过相同，并不是认为他有道义才跟他来的，见面干什么？”一直到回国，没有见过面。
狄人侵袭我国西部边境，鲁文公派使者向晋国报告。赵宣子派贾季去问酆舒，同时责备他。酆舒问贾季说：“赵衰、赵盾哪一个贤明？”贾季回答说：“赵衰，是冬天的太阳；赵盾，是夏天的太阳。”
秋季，八月，齐昭公、宋昭公、卫成公、陈共公、郑穆公、许昭公、曹共公和晋国的赵盾在扈地结盟，这是由于晋灵公即位的缘故。鲁文公晚到，所以《春秋》没有记载他参加会议。凡是和诸侯会盟，如果不记载参加会的国家，就是因为晚到的缘故。晚到，不记载这些国家，这是为了避免弄不清而误记。
穆伯在莒国娶妻，名叫戴己，生了文伯；她的妹妹声己，生了惠叔。戴己死，穆伯又到莒国行聘，莒国人由于有声己而辞谢，所以就为襄仲行聘。冬季，徐国攻打莒国，莒国人前来请求结盟，穆伯到莒国参加盟会，同时为襄仲迎接莒女。到达鄢陵，登上城见到莒女，很美丽，就自己娶了她。襄仲请求攻打穆伯，文公准备答应。叔仲惠伯劝谏说：“下臣听说：‘战争起于内部叫做乱，起于外部叫做寇。寇尚且伤人，乱就是自己打自己了。’现在臣下作乱而国君不加禁止，如果因此而引起外部敌人的进攻，怎么办？”文公就阻止襄仲的进攻。惠伯给他们调解：让襄仲丢开莒女不娶，公孙敖就把莒女送回莒国，重新作为兄弟像起初一样。襄仲和公孙敖听从了。
晋国的郤缺对赵宣子说：“过去卫国不顺服，所以占取它的土地，现在已经顺服，可以还给它了。背叛了不加讨伐，用什么显示声威？顺服了不加抚慰，用什么表示关怀？不显示声威和不表示关怀，用什么显示德行？没有德行，如何主持盟会？您作为正卿，主持诸侯之事而不致力于德行，打算怎么办？《夏书》说：‘把喜事告诉他，用威严督察他，用《九歌》勉励他，不要让他学坏。’有关九功的德行都可以歌唱，叫做《九歌》。六府、三事，叫做九功。水、火、金、木、土、谷，叫做六府；端正德行、利于使用、富裕民生，叫做三事。合于道义而推行这些，叫做德、礼。没有礼就不快乐，这是叛变之所由来。像您的德行，没有可以歌唱的，有谁肯来归服？何不使归服的人歌颂您呢？”赵宣子听了这番话很高兴。
', NULL, '', 'indent', 1558952219, '5ceb4898a673f50068159b65', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642971, '左传 · 文公 · 文公八年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】八年春王正月。夏四月。秋八月戊申，天王崩。冬十月壬午，公子遂会晋赵盾盟于衡雍。乙酉，公子遂会洛戎盟于暴。公孙敖如京师，不至而复。丙戌，奔莒。螽。宋人杀其大夫司马。宋司城来奔。
【传】八年春，晋侯使解扬归匡、戚之田于卫，且复致公婿池之封，自申至于虎牢之竟。
夏，秦人伐晋，取武城，以报令狐之役。
秋，襄王崩。
晋人以扈之盟来讨。冬，襄仲会晋赵孟，盟于衡雍，报扈之盟也，遂会伊洛之戎。书曰「公子遂」，珍之也。
穆伯如周吊丧，不至，以币奔莒，从己氏焉。
宋襄夫人，襄王之姊也，昭公不礼焉。夫人因戴氏之族，以杀襄公之孙孔叔、公孙钟离及大司马公子卬，皆昭公之党也。司马握节以死，故书以官。司城荡意诸来奔，效节于府人而出。公以其官逆之，皆复之，亦书以官，皆贵之也。
夷之蒐，晋侯将登箕郑父、先都，而使士縠、梁益耳将中军。先克曰：「狐、赵之勋，不可废也。」从之。先克夺蒯得田于堇阴。故箕郑父、先都、士縠、梁益耳、蒯得作乱。
', '', '', '八年春季，晋灵公派遣解扬把匡地、戚地的土田归还给卫国，而且再送公婿池的封地，从申地到虎牢边境。
夏季，秦军攻打晋国，占领了武城，以报复令狐那一次战役。
秋季，周襄王逝世。
晋国人由于扈地的结盟文公晚去而来攻打鲁国。冬季，襄仲和晋国的赵孟在衡雍会见，这是为了补偿扈地那次结盟，并因此而和伊、雒的戎人会见。《春秋》称他为“公子遂”，这是表示重视他。
穆伯去成周吊丧，没有到成周，带了礼物逃亡到莒国，跟随己氏去了。宋襄夫人是周襄王的姐姐，宋昭公对她不加礼遇。宋襄夫人依靠戴氏的族人杀了襄公的孙子孔叔、公孙钟离和大司马公子卬，都是宋昭公的党羽。司马手里拿着符节死去，所以《春秋》记载他的官职而不写名字。司城荡意诸逃亡前来，把符节还给府人然后出去。文公按照他原来的官职接待他，而且都恢复了他们原来的官职。《春秋》也记载他的官职而不写名字。所有这些都是表示尊重他们。
在夷地阅兵的时候，晋襄公准备提升箕郑父、先都，而让士縠、梁益耳率领中军。先克说：“狐、赵两人的功劳，不能废弃。”晋襄公听从了这个意见。先克在堇阴夺取了蒯得的田地，因此箕郑父、先都、士縠、梁益耳、蒯得发动叛乱。
', NULL, '', 'indent', 1558952258, '5ceb48c0d5de2b0070790397', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642972, '左传 · 文公 · 文公九年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】九年春，毛伯来求金。夫人姜氏如齐。二月，叔孙得臣如京师。辛丑，葬襄王。晋人杀其大夫先都。三月，夫人姜氏至自齐。晋人杀其大夫士縠及箕郑父。楚人伐郑。公子遂会晋人、宋人、卫人、许人救郑。夏，狄侵齐。秋八月，曹伯襄卒。九月癸西，地震。冬，楚子使椒来聘。秦人来归僖公、成风之襚。葬曹共公。
【传】九年春，王正月己酉，使贼杀先克。乙丑，晋人杀先都，梁益耳。
毛伯卫来求金，非礼也。不书王命，未葬也。
二月庄叔如周。葬襄王。
三月甲戌，晋人杀箕郑父、士縠、蒯得。
范山言于楚子曰：「晋君少，不在诸侯，北方可图也。」楚子师于狼渊以伐郑。囚公子坚、公子龙及乐耳。郑及楚平。公子遂会晋赵盾、宋华耦、卫孔达、许大夫救郑，不及楚师。卿不书，缓也，以惩不恪。
夏，楚侵陈，克壶丘，以其服于晋也。
秋，楚公子朱自东夷伐陈，陈人败之，获公子伐。陈惧，乃及楚平。
冬，楚子越椒来聘，执币傲。叔仲惠伯曰：「是必灭若敖氏之宗。傲其先君，神弗福也。」
秦人来归僖公、成风之襚，礼也。诸侯相吊贺也，虽不当事，苟有礼焉，书也，以无忘旧好。
', '', '', '九年春季，周王朝历法的正月初二日，晋灵公派遣凶手杀死了先克。十八日，晋国人杀死了先都、梁益耳。
毛伯卫前来求取丧仪，这不合于礼。没有记载说这是天子的命令，这是由于周襄王还没有安葬。
二月，庄叔去成周参加襄王的葬礼。
三月二十八日，晋国人杀死了箕郑父、士縠、蒯得。
范山对楚穆王说：“晋国国君年少，心意不在于称霸诸侯，北方是可以打主意的。”楚王在狼渊出兵来攻打郑国。囚禁了公子坚、公子尨和乐耳。郑国和楚国讲和。
公子遂会合晋国赵盾、宋国华耦、卫国孔达、许国大夫，救援郑国，没有碰上楚军。《春秋》没有记载卿的名字，由于他们出兵迟缓，以此惩戒他们的办事不严肃认真。
夏季，楚国入侵陈国，攻下壶丘，因为陈国归服了晋国。
秋季，楚国公子朱从东夷进攻陈国，陈国军队打败了他，俘虏了公子茷。陈国害怕楚国报复，就和楚国讲和。
冬季，楚国子越椒前来聘问，手拿着礼物显出傲慢的样子。叔仲惠伯说：“这个人必然会使若敖氏的宗族灭亡。向他的先君表示傲慢，神灵不会降福给他。”
秦国人前来向死去的僖公和成风赠送衣衾，这是合于礼的。诸侯之间互相吊丧贺喜，虽然不及时，如果符合礼仪，《春秋》就要加以记载，以表示不忘记过去的友好。', NULL, '', 'indent', 1558952304, '5ceb48e4a673f50068159ed5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642973, '左传 · 文公 · 文公十年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十年春王三月辛卯，臧孙辰卒。夏，秦伐晋。楚杀其大夫宜申。自正月不雨，至于秋七月。及苏子盟于女栗。冬，狄侵宋。楚子、蔡侯次于厥貉。
【传】十年春，晋人伐秦，取少梁。
夏，秦伯伐晋，取北征。
初，楚范巫矞似谓成王与子玉、子西曰：「三君皆将强死。」城濮之役，王思之，故使止子玉曰：「毋死。」不及。止子西，子西缢而县绝，王使适至，遂止之，使为商公。沿汉溯江，将入郢。王在渚宫，下，见之。惧而辞曰：「臣免于死，又有谗言，谓臣将逃，臣归死于司败也。」王使为工尹，又与子家谋弑穆王。穆王闻之。五月杀斗宜申及仲归。
秋七月，及苏子盟于女栗，顷王立故也。
陈侯、郑伯会楚子于息。冬，遂及蔡侯次于厥貉。将以伐宋。宋华御事曰：「楚欲弱我也。先为之弱乎，何必使诱我？我实不能，民何罪？」乃逆楚子，劳，且听命。遂道以田孟诸。宋公为右盂，郑伯为左盂。期思公复遂为右司马，子朱及文之无畏为左司马。命夙驾载燧，宋公违命，无畏抶其仆以徇。
或谓子舟曰：「国君不可戮也。」子舟曰：「当官而行，何强之有？《诗》曰：『刚亦不吐，柔亦不茹。』『毋从诡随，以谨罔极。』是亦非辟强也，敢爱死以乱官乎！」
厥貉之会，麇子逃归。', '', '', '十年春季，晋国人攻打秦国，占领了少梁。
夏季，秦国攻打晋国，占领了北征。
当初，楚国范地的巫人矞似预言成王和子玉、子西说：“这三位都将被杀死。”城濮那次战役，楚王想起了这句话，所以阻止子玉说：“不要自杀。”但是没有来得及。去阻止子西，子西正在上吊而绳子断了，楚王的使者刚刚来到，就阻止了他自杀，让他做了商公。子西沿汉江而下，逆长江而上，将要进入郢都。楚王正在渚宫，下来接见他，子西害怕，就解释说：“下臣幸而免于一死，但又有人诬陷，说下臣准备逃走，下臣现在回来请求死在司败那里。”楚王让他做了工尹，他又和子家策划杀死穆王。穆王听到后，在五月间杀了子西和子家。
秋季，七月，文公和苏子在女栗结盟，这是由于周顷王即位的缘故。
陈恭公、郑穆公在息地会见楚穆王。冬季，就和蔡庄侯一起领兵驻扎在厥貉，准备攻打宋国。宋国的华御事说：“楚国想要让我们归服，是不是我们先主动表示顺服？他们何必摆出这副架势来逼迫我们？我们实在没有能耐，但是百姓有什么罪？”于是就亲自去迎接楚穆王，向他表示慰劳，同时听候命令。于是就引导楚穆王在孟诸打猎。宋昭公率领右边圆阵，郑穆公率领左边圆阵。期思公复遂作为右司马，子朱和文之无畏作为左司马，下令早晨在车上装载取火工具出发。宋昭公违背命令，无畏笞打他的仆人并在全军示众。有人对文之无畏说：“国君是不能够侮辱的。”文之无畏说：“按照职责办事，有什么强横？《诗》说：‘硬的不吐出来，软的不吞下去。’又说：‘不要放纵狡诈的人，以使放荡的行为得以检点。’这也是不避强横的意思。我哪里敢爱惜生命而放弃职守呢！”
在厥貉会见的时候，麇子逃走回国。', NULL, '', 'indent', 1558952359, '5ceb4924a673f5006815a124', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642974, '左传 · 文公 · 文公十一年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有一年春，楚子伐麋。夏，叔仲彭生会晋郤缺于承筐。秋，曹伯来朝。公子遂如宋。狄侵齐。冬十月甲午，叔孙得臣败狄于咸。
【传】十一年春，楚子伐麇，成大心败麇师于防渚。潘崇复伐麇，至于锡穴。
夏，叔仲惠伯会晋郤缺于承筐，谋诸侯之从于楚者。
秋，曹文公来朝，即位而来见也。
襄仲聘于宋，且言司城荡意诸而复之，因贺楚师之不害也。
鄋瞒侵齐。遂伐我。公卜使叔孙得臣追之，吉。侯叔夏御庄叔，绵房甥为右，富父终甥驷乘。冬十月甲午，败狄于咸，获长狄侨如。富父终甥舂其喉以戈，杀之，埋其首于子驹之门，以命宣伯。
初，宋武公之世，鄋瞒伐宋，司徒皇父帅师御之，耏班御皇父充石，公子谷甥为右，司寇牛父驷乘，以败狄于长丘，获长狄缘斯，皇父之二子死焉。宋公于是以门赏耏班，使食其征，谓之耏门。晋之灭潞也，获侨如之弟焚如。齐襄公之二年，鄋瞒伐齐，齐王子成父获其弟荣如，埋其首于周首之北门。卫人获其季简如，鄋瞒由是遂亡。
郕大子朱儒自安于夫钟，国人弗徇。
', '', '', '十一年春季，楚穆王攻打麇国。成大心在防渚打败麇军。潘崇再次攻打麇国，到达锡穴。
夏季，叔仲惠伯在承筐会见晋国郤缺，这是为了商量对付追随楚国的诸侯。
秋季，曹文公前来朝见，这是由于他刚即位而来朝见的。
襄仲到宋国聘问，同时又替司城荡意诸说话而让他回国。这次聘问并且为了祝贺宋军没有遭到楚军兵害。
鄋瞒侵袭齐国，并因此攻打我国。文公占了一个卦，卜派遣叔孙得臣追赶敌人，吉利。侯叔夏驾御叔孙得臣的战车，绵房甥作为车右，富父终甥作为驷乘。冬季，十月初三日，在咸地打败狄人，俘虏了长狄侨如。富父终甥用戈抵住他的咽喉，杀死了他，把他的脑袋埋在子驹之门下边。就把宣伯名叫侨如。
当初，在宋武公时代，鄋瞒进攻宋国，司徒皇父带兵抵御。耏班驾御皇父充石的战车，公子穀甥为车右，司寇牛父作驷乘，在长丘打败狄人，俘虏了长狄缘斯。皇父的两个儿子战死，宋公因此就把城门赏给耏班，让他征收城门税，把城门称为耏门。
晋国灭亡潞国的时候，俘虏了侨如的弟弟焚如。齐襄公二年，鄋瞒进攻齐国，齐国的王子成父俘虏了侨如的弟弟荣如，把他的脑袋埋在周首的北门下边。卫国人又俘虏了侨如的弟弟简如，鄋瞒由此就被灭亡。
郕国的太子朱儒自己安逸地居住在夫钟，国内的人们不肯顺服他。
', NULL, '', 'indent', 1558952409, '5ceb495730863b006826a892', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642975, '左传 · 文公 · 文公十二年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有二年春王正月，郕伯来奔。杞伯来朝。二月庚子，子叔姬卒。夏，楚人围巢。秋，滕子来朝。秦伯使术来聘。冬十有二戊午，晋人、秦人战于河曲。季孙行父帅师城诸及郓。
【传】十二年春，郕伯卒，郕人立君。大子以夫钟与郕邽来奔。公以诸侯逆之，非礼也。故书曰：「郕伯来奔。」不书地，尊诸侯也。
杞桓公来朝，始朝公也。且请绝叔姬而无绝昏，公许之。
二月，叔姬卒，不言杞，绝也。书叔姬，言非女也。
楚令尹大孙伯卒，成嘉为令尹。群舒叛楚。夏，子孔执舒子平及宗子，遂围巢。
秋，滕昭公来朝，亦始朝公也。
秦伯使西乞术来聘，且言将伐晋。襄仲辞玉曰：「君不忘先君之好，照临鲁国，镇抚其社稷，重之以大器，寡君敢辞玉。」对曰：「不腆敝器，不足辞也。」主人三辞。宾客曰：「寡君愿徼福于周公、鲁公以事君，不腆先君之敝器，使下臣致诸执事以为瑞节，要结好命，所以藉寡君之命，结二国之好，是以敢致之。」襄仲曰：「不有君子，其能国乎？国无陋矣。」厚贿之。
秦为令狐之役故，冬，秦伯伐晋，取羁马。晋人御之。赵盾将中军，荀林父佐之。郤缺上军，臾骈佐之。栾盾将下军，胥甲佐之。范无恤御戎，以从秦师于河曲。臾骈曰：「秦不能久，请深垒固军以待之。」从之。
秦人欲战，秦伯谓士会曰：「若何而战？」对曰：「赵氏新出其属曰臾骈，必实为此谋，将以老我师也。赵有侧室曰穿，晋君之婿也，有宠而弱，不在军事，好勇而狂，且恶臾骈之佐上军也，若使轻者肆焉，其可。」秦伯以璧祈战于河。
十二月戊午，秦军掩晋上军，赵穿追之，不及。反，怒曰：「裹粮坐甲，固敌是求，敌至不击，将何俟焉？」军吏曰：「将有待也。」穿曰：「我不知谋，将独出。」乃以其属出。宣子曰：「秦获穿也，获一卿矣。秦以胜归，我何以报？」乃皆出战，交绥。秦行人夜戒晋师曰：「两君之士皆未憖也，明日请相见也。」臾骈曰：「使者目动而言肆，惧我也，将遁矣。薄诸河，必败之。」胥甲、赵穿当军门呼曰：「死伤未收而弃之，不惠也；不待期而薄人于险，无勇也。」乃止。秦师夜遁。复侵晋，入瑕。
城诸及郓，书，时也。', '', '', '十二年春季，郕伯死了，郕国人又立了国君。太子把夫钟和郕国的宝圭作为奉献而逃亡到鲁国来。文公把他作为诸侯迎接，这不合于礼。所以《春秋》记载说“郕伯来奔”，不记载关于奉献土地的事情，把郕伯作为诸侯来尊重。
杞桓公来鲁国朝见，这是第一次前来朝见鲁文公。同时又请求和叔姬离婚，但不断绝两国的婚姻关系，文公答应了。二月，叔姬死了。《春秋》不记载“杞”字，是由于杞国和她断绝了关系。写明“叔姬”，是说她已经出过嫁。
楚国的令尹大孙伯去世，成嘉做了令尹。舒氏的一批人背叛楚国。夏季，子孔逮捕了舒子平和宗子，就乘机包围巢地。
秋季，滕昭公来鲁国朝见，也是第一次前来朝见文公。
秦康公派遣西乞术前来聘问，而且说将要攻打晋国。襄仲不肯受玉，说：“贵国国君没有忘记和先君的友好，光临鲁国，镇定安抚我们这个国家，十分厚重地赠给我们大器，寡君不敢受玉。”西乞术回答说：“不丰厚的器物，不值得辞谢。”主人辞谢了三次，客人回答说：“寡君愿意在周公、鲁公这里求取福禄来事奉贵国国君，一点微薄的礼物，派遣下臣致送给执事，以作为祥瑞的信物，相约友好，把它用来表示寡君的命令，缔结两国之间的友好，因此才敢致送。”襄仲说：“若没有这样的外交人才，难道能治理国家吗？秦国不是鄙陋的国家。”就用重礼赠送给西乞术。
秦国为了令狐那次战役的缘故，冬季，秦康公发兵攻打晋国，占取了羁马。晋国发兵抵御。赵盾率领中军，荀林父作为辅佐。郤缺率领上军，臾骈作为辅佐。栾盾率领下军，胥甲作为辅佐。范无恤为赵盾驾御战车，在河曲迎战秦军。臾骈说：“秦军不能持久，请高筑军垒巩固军营等着他们。”赵盾听从了他的意见。
秦军准备出战。秦康公对士会说：“用什么办法作战？”士会回答说：“赵盾新近提拔他的部下名叫臾骈，必定是他出的这个主意，打算使我军久驻在外面感到疲乏。赵氏有一个旁支的子弟名叫穿，是晋国国君的女婿，受到宠信而年少，不懂得作战，喜好勇猛而又狂妄，又讨厌臾骈作为上军的辅佐。如果派出一些勇敢而不刚强的人对上军加以袭击，或许还有可能战胜赵穿。”秦康公把玉璧丢在黄河里，向河神祈求战争胜利。
十二月初四日，秦国袭击晋军的上军，赵穿追赶秦军，没有追上。回来，发怒说：“装着粮食披着甲胄，就是要寻求敌人。敌人来了不去攻击，打算等待什么呢？”军官说：“将要有所等待啊。”赵穿说：“我不懂得计谋，我打算自己出战。”就带领他的士兵出战。赵盾说：“秦军要是俘虏了赵穿，就是俘虏了一位卿了。秦国带着胜利回去，我用什么回报晋国的父老？”于是全部出战，双方刚一交战就彼此退兵。秦军的使者夜里告诉晋国军队说：“我们两国国君的将士都还没有痛快地打一仗，明天请再相见。”臾骈说：“使者眼神不安而声音失常，这是害怕我们，秦军将要逃走了。我军把他们逼到黄河边上，一定可以打败他们。”胥甲、赵穿挡住营门大喊说：“死伤的人还没有收集就把他们丢弃，这是不仁慈。不等到约定的日期而把人逼到险地，这是没有勇气。”于是晋军就停止出击。秦军夜里逃走了。后来又入侵晋国，进入瑕地。
鲁国在诸地和郓地筑城，《春秋》记载这件事，是由于合于时令。', NULL, '', 'indent', 1558952473, '5ceb497b43e78c0067141812', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642976, '左传 · 文公 · 文公十三年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有三春王正月。夏五月壬午，陈侯朔卒。邾子蘧蒢卒。自正月不雨，至于秋七月。大室屋坏。冬，公如晋。卫侯会公于沓。狄侵卫。十有二月己丑，公及晋侯盟。公还自晋，郑伯会公于棐。
【传】十三年春，晋侯使詹嘉处瑕，以守桃林之塞。
晋人患秦之用士会也，夏，六卿相见于诸浮，赵宣子曰；「随会在秦，贾季在狄，难日至矣，若之何？」中行桓子曰：「请复贾季，能外事，且由旧勋。」郤成子曰：「贾季乱，且罪大，不如随会，能贱而有耻，柔而不犯，其知足使也，且无罪。」
乃使魏寿余伪以魏叛者以诱士会，执其帑于晋，使夜逸。请自归于秦，秦伯许之。履士会之足于朝。秦伯师于河西，魏人在东。寿余曰：「请东人之能与夫二三有司言者，吾与之先。」使士会。士会辞曰：「晋人，虎狼也，若背其言，臣死，妻子为戮，无益于君，不可悔也。」秦伯曰：「若背其言，所不归尔帑者，有如河。」乃行。绕朝赠之以策，曰：「子无谓秦无人，吾谋适不用也。」既济，魏人噪而还。秦人归其帑。其处者为刘氏。
邾文公卜迁于绎。史曰：「利于民而不利于君。」邾子曰：「苟利于民，孤之利也。天生民而树之君，以利之也。民既利矣，孤必与焉。」左右曰：「命可长也，君何弗为？」邾子曰：「命在养民。死之短长，时也。民苟利矣，迁也，吉莫如之！」遂迁于绎。
五月，邾文公卒。君子曰：「知命。」
秋七月，大室之屋坏，书，不共也。
冬，公如晋，朝，且寻盟。卫侯会公于沓，请平于晋。公还，郑伯会公于棐，亦请平于晋。公皆成之。郑伯与公宴于棐。子家赋《鸿雁》。季文子曰：「寡君未免于此。」文子赋《四月》。子家赋《载驰》之四章。文子赋《采薇》之四章。郑伯拜。公答拜。
', '', '', '十三年春季，晋灵公派詹嘉住在瑕地，以防守桃林这个险要的地方。晋国人担心秦国任用士会，夏季，六卿在诸浮相见。赵宣子说：“士会在秦国，贾季在狄人那里，祸患每天都可能发生，怎么办？”中行桓子说：“请让贾季回来，他了解外界的事情，而且因为有过去的功劳。”郤成子说：“贾季喜欢作乱，而且罪过大，不如让士会回来。士会能够做到卑贱而知道耻辱，柔弱而不受侵犯，他的智谋足以使用，而且没有罪过。”于是晋国就让魏寿馀假装率领魏地的人叛乱，以引诱士会。把魏寿馀的妻子儿女抓在晋国，让他夜里逃走。魏寿馀请求把魏地归入秦国，秦康公答应了。魏寿馀在朝廷上踩一下士会的脚，示意士会与他一起回晋国。秦康公驻军在河西，魏地人在河东。魏寿馀说：“请派一位东边人而能够跟魏地几位官员说话的，我跟他一起先去。”秦康公派遣士会。士会辞谢说：“晋国人，是老虎豺狼。如果违背原来的话不让下臣回来，下臣死，妻子儿女也将被诛戮，这对君王没有好处，而且后悔不及。”秦康公说：“如果晋国违背原来的话不让你回来，我若不送还你的妻子儿女，有河神作证！”这样士会才敢去。绕朝把马鞭送给士会，说：“您别说秦国没有人才，我的计谋正好不被采用罢了。”渡过黄河以后，魏地人因得到士会而欢呼，熙熙嚷嚷地回去了。秦国人送还了士会的妻子儿女。士会留在秦国的家人都改姓为刘氏。
邾文公为了迁都到绎地而占了卦问吉凶。史官说：“对百姓有利而对国不利。”邾文公说：“如果对百姓有利，也就是我的利益。上天生育了百姓而为他们设置君主，就是用来给他们利益的。百姓得到利益，我就必然也在其中了。”左右随从说：“生命是可以延长的，君王为什么不这样做？”邾文公说：“活着就是为了抚养百姓。而死的或早或晚，那是由于偶然因素的缘故。百姓如果有利，迁都就是了，没有比这再吉利的了。”于是就迁都到绎地。五月，邾文公死了。君子说：“邾文公真正懂得天命。”
秋季，七月，太庙正屋屋顶损坏，《春秋》所以记载，是为了表示臣下的不恭敬。
冬季，文公到晋国朝见，同时重温过去的友好关系。卫成公在沓地会见文公，请求和晋国讲和。文公回国时，郑穆公在棐地会见文公，也请求和晋国讲和。鲁文公都一一帮助他们达成和议。
郑穆公和鲁文公在棐地举行宴会，子家赋了《鸿雁》这首诗。季文子说：“寡君也不能免于这种处境。”就赋了《四月》这首诗，子家又赋了《载驰》这首诗的第四章，季文子赋了《采薇》这首诗的第四章。郑穆公拜谢，鲁文公答谢。
', NULL, '', 'indent', 1558952511, '5ceb49bc30863b006826b1b6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642977, '左传 · 文公 · 文公十四年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有四年春王正月，公至自晋。邾人伐我南鄙，叔彭生帅师伐邾。夏五月乙亥，齐侯潘卒。六月，公会宋公、陈侯、卫侯、郑伯、许男、曹伯、晋赵盾。癸酉，同盟于新城。秋七月，有星孛入于北斗。公至自会。晋人纳捷菑于邾。弗克纳。九月甲申，公孙敖卒于齐。齐公子商人弑其君舍。宋子哀来奔。冬，单伯如齐。齐人执单伯。齐人执子叔姬。
【传】十四年春，顷王崩。周公阅与王孙苏争政，故不赴。凡崩、薨，不赴，则不书。祸、福，不告亦不书，惩不敬也。
邾文公之卒也，公使吊焉，不敬。邾人来讨，伐我南鄙，故惠伯伐邾。
子叔姬齐昭公，生舍。叔姬无宠，舍无威。公子商人骤施于国，而多聚士，尽其家，贷于公，有司以继之。夏五月，昭公卒，舍即位。
邾文公妃元齐姜生定公，二妃晋姬生捷菑。文公卒，邾人立定公，捷菑奔晋。
六月，同盟于新城，从于楚者服，且谋邾也。
秋七月乙卯夜，齐商人弑舍而让元。元曰：「尔求之久矣。我能事尔，尔不可使多蓄憾。将免我乎？尔为之！」
有星孛入于北斗，周内史叔服曰：「不出七年，宋、齐、晋之君皆将死乱。」
晋赵盾以诸侯之师八百乘纳捷菑于邾。邾人辞曰：「齐出玃且长。」宣子曰：「辞顺而弗从，不祥。」乃还。
周公将与王孙苏讼于晋，王叛王孙苏，而使尹氏与聃启讼周公于晋。赵宣子平王室而复之。
楚庄王立，子孔、潘崇将袭群舒，使公子燮与子仪守而伐舒蓼。二子作乱，城郢而使贼杀子孔，不克而还。八月，二子以楚子出，将如商密。庐戢梨及叔麋诱之，遂杀斗克及公子燮。
初，斗克囚于秦，秦有殽之败，而使归求成，成而不得志。公子燮求令尹而不得。故二子作乱。
穆伯之从己氏也，鲁人立文伯。穆伯生二子于莒而求复，文伯以为请。襄仲使无朝。听命，复而不出，二年而尽室以复适莒。文伯疾而请曰：「谷之子弱，请立难也。」许之。文伯卒，立惠叔。穆伯请重赂以求复，惠叔以为请，许之。将来，九月卒于齐，告丧，请葬，弗许。
宋高哀为萧封人，以为卿，不义宋公而出，遂来奔。书曰：「宋子哀来奔去贵之也。」
齐人定懿公，使来告难，故书以九月。齐公子元不顺懿公之为政也，终不曰「公」，曰「夫己氏」。
襄仲使告于王，请以王宠求昭姬于齐。曰：「杀其子，焉用其母？请受而罪之。」
冬，单伯如齐，请子叔姬，齐人执之。又执子叔姬。
', '', '', '十四年春季，周顷王逝世。周公阅和王孙苏争夺政权，所以没有发布讣告。凡是天子“逝世”，诸侯“去世”，没有发来讣告，《春秋》就不加记载。灾祸、喜庆，如果没有前来报告，也不加记载。那是为了惩诫那些不认真负责的人。
邾文公死的时候，鲁文公派遣使者前去吊丧，礼仪不周到。邾国兴师问罪，攻打我国南部边境，所以惠伯领兵攻打邾国。
子叔姬嫁给齐昭公为夫人，生了儿子舍。叔姬不受宠爱，舍没有威信。公子商人却多次在国内施舍财物，养着许多门客，把家产都用光了，又向掌管公室财物的官员借贷而继续施舍。夏季，五月，齐昭公去世，舍即国君位。邾文公的第一夫人齐姜，生了定公；第二夫人晋姬，生了捷菑。邾文公去世后，邾国人立定公为君，捷菑逃亡到晋国。
六月，鲁文公和宋昭公、陈灵公、卫成公、郑穆公、许男、曹文公、晋国赵盾一起在新城会盟，这是由于以前跟随楚国的国家都顺服，同时谋划攻打邾国。
秋季，七月某一天，夜里，齐公子商人杀死舍而让位给元。元说：“你谋求这个君位已经很久了。我能够事奉你，你不能积下许多怨恨，要是这样，你会让我免于被杀吗？你去做国君吧！”
有彗星进入北斗。成周的内史叔服说：“不出七年，宋国、齐国、晋国的国君，都将死于叛乱。”
晋国的赵盾率领诸侯联军的八百辆战车，把捷菑送回邾国。邾国人辞谢说：“齐女生的貜且年长。”赵宣子说：“说话合于情理而不听从，不吉祥。”于是就回去了。
周公阅打算和王孙苏在晋国争讼，周顷王违背了对王孙苏的诺言，而让尹氏和聃启在晋国替周公阅争讼。赵宣子调停了王室之间的纠纷而使各人恢复了原来的职位。
楚庄王即位，子孔、潘崇准备袭击舒族的那些部落或国家，派公子燮和子仪留守而进攻舒蓼。这两个人发动叛乱，加筑郢都城墙，又派贼人去刺死子孔，没有成功而返回郢城。八月，两个人挟持了楚庄王离开郢都，准备去商密，庐戢梨和叔麇设计引诱他们；于是就杀死了子仪和公子燮。
当初，子仪囚禁在秦国，秦国在殽地战败，派他回国求和。媾和以后，子仪的愿望没有得到满足，公子燮要求做令尹也没有得到手，所以两人就发动叛乱。
穆伯跟随己氏的时候，鲁国人立了文伯做继承人。穆伯在莒国生了两个儿子，要求回国。文伯代替他申请。襄仲不让穆伯上朝参与政事。穆伯听从命令，回来以后也不外出，过了三年又将全家再次搬到莒国去。文伯生重病，请求说：“穀的儿子年纪太小，请立难吧。”大家同意了。文伯去世，立了惠叔。穆伯让惠叔给大家送重礼再次要求回国，惠叔代他请求，得到允许。穆伯将要回来，九月间，死在齐国。向鲁国报丧，请求归葬于鲁，没有得到允许。
宋国的高哀担任萧地的守将，让他做卿，他认为宋公不义而离去，于是就逃亡到鲁国来。《春秋》记载“宋子哀来奔”，这是表示对他的尊重。
齐国人安定了齐懿公的地位，才派人前来报告祸难，所以《春秋》把商人杀死舍这件事记为“九月”。齐国的公子元不服懿公执政，始终不称他做“公”，而称他做“那个人”。
襄仲派人报告周顷王，请用周天子的尊荣在齐国求取子叔姬，说：“杀了她的儿子，哪里还用得着他的母亲？请求接纳她而惩办她。”冬季，单伯到齐国请求送回子叔姬，齐国人逮捕了他，同时又逮捕了子叔姬。
', NULL, '', 'indent', 1558952550, '5ceb49e3d5de2b007079100b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642978, '左传 · 文公 · 文公十五年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有五年春，季孙行父如晋。三月，宋司马华孙来盟。夏，曹伯来朝。齐人归公孙敖之丧。六月辛丑朔，日有食之。鼓、用牲于社。单伯至自齐。晋郤缺帅师伐蔡。戊申，入蔡。齐人侵我西鄙。季孙行父如晋。冬十有一月，诸侯盟于扈。十有二月，齐人来归子叔姬。齐侯侵我西鄙，遂伐曹入期郛。
【传】十五年春，季文子如晋，为单伯与子叔姬故也。
三月，宋华耦来盟，其官皆从之。书曰「宋司马华孙」，贵之也。
公与之宴，辞曰：「君之先臣督，得罪于宋殇公，名在诸侯之策。臣承其祀，其敢辱君，请承命于亚旅。」鲁人以为敏。
夏，曹伯来朝，礼也。诸侯五年再相朝，以修王命，古之制也。
齐人或为孟氏谋，曰：「鲁，尔亲也。饰棺置诸堂阜，鲁必取之。」从之。卞人以告。惠叔犹毁以为请。立于朝以待命。许之，取而殡之。齐人送之。书曰：「齐人归公孙敖之丧。」为孟氏，且国故也。葬视共仲。
声己不视，帷堂而哭。襄仲欲勿哭，惠伯曰：「丧，亲之终也。虽不能始，善终可也。史佚有言曰：『兄弟致美。』救乏、贺善、吊灾、祭敬、丧哀，情虽不同，毋绝其爱，亲之道也。子无失道，何怨于人？」襄仲说，帅兄弟以哭之。他年，其二子来，孟献子爱之，闻于国。或谮之曰：「将杀子。」献子以告季文子。二子曰：「夫子以爱我闻，我以将杀子闻，不亦远于礼乎？远礼不如死。」一人门于句鼆，一人门于戾丘，皆死。
六月辛丑朔，日有食之，鼓、用牲于社，非礼也。日有食之，天子不举，伐鼓于社，诸侯用币于社，伐鼓于朝，以昭事神、训民、事君，示有等威。古之道也。
齐人许单伯请而赦之，使来致命。书曰：「单伯至自齐。」贵之也。
新城之盟，蔡人不与。晋郤缺以上军、下军伐蔡，曰：「君弱，不可以怠。」戊申，入蔡，以城下之盟而还。凡胜国，曰灭之；获大城焉，曰入之。
秋，齐人侵我西鄙，故季文子告于晋。
冬十一月，晋侯、宋公、卫侯、蔡侯、郑伯、许男、曹伯盟于扈，寻新城之盟，且谋伐齐也。齐人赂晋侯，故不克而还。于是有齐难，是以公不会。书曰：「诸侯盟于扈。」无能为故也。凡诸侯会，公不与，不书，讳君恶也。与而不书，后也。
齐人来归子叔姬，王故也。
齐侯侵我西鄙，谓诸侯不能也。遂伐曹，入其郛，讨其来朝也。季文子曰：「齐侯其不免乎。己则无礼，而讨于有礼者，曰：『女何故行礼！』礼以顺天，天之道也，己则反天，而又以讨人，难以免矣。诗曰：『胡不相畏，不畏于天？』君子之不虐幼贱，畏于天也。在周颂曰：『畏天之威，于时保之。』不畏于天，将何能保？以乱取国，奉礼以守，犹惧不终，多行无礼，弗能在矣！」

', '', '', '十五年春季，季文子去晋国，为了单伯和子叔姬的缘故。
三月，宋国的华耦前来会盟，他的部属都跟随前来。《春秋》称他为“宋司马华孙”，这是表示尊重他。鲁文公要和他同席宴会。华耦婉辞谢绝说：“君王的先臣督得罪了宋殇公，名字记载在诸侯的简册上。下臣承继他的祭祀，怎么敢使君王蒙受耻辱？请在亚旅那里接受命令。”鲁国人认为华耦措辞得体。
夏季，曹文公前来朝见，这合于礼。诸侯每五年再一次互相朝见，以重温天子的命令，这是古代的制度。
齐国有人为孟氏策划，说：“鲁国，是你的亲戚，把公孙敖的饰棺放在堂阜，鲁国必定会取去的。”孟氏听从了。卞邑大夫把这件事作了报告。惠叔仍然很悲哀，容颜消瘦，请求取回饰棺，立在朝廷上以等待命令。鲁国答应了这项请求，于是取回了饰棺停放。齐国人也来送丧，《春秋》记载说：“齐人归公孙敖之丧”，这是为了孟氏，同时又为了国家的缘故。依照安葬共仲的葬礼安葬了公孙敖。声己不肯去看棺材，在帷堂里哭泣。襄仲不想去哭丧，惠伯说：“办丧事，是对待亲人的最后大事。虽不能有一个好的开始，有一个好的终结是可以的。史佚有这样的话，说：‘兄弟之间各自尽力做到完美。救济困乏，祝贺喜庆，吊唁灾祸，祭祀恭敬，丧事悲哀，感情虽然不一样，不要断绝他们之间的友爱，这就是对待亲人的道义。’您自己只要不丧失道义，怨恨别人干什么呢？”襄仲听了很高兴，带领了兄弟们前去哭丧。后来，穆伯的两个儿子回来，孟献子喜爱他们，闻名于全国。有人诬陷他们，对孟献子说：“这两个人准备杀死你。”孟献子把这话告诉季文子。这两个人说：“他老人家因为爱我们，全国都知道，我们以准备杀死他而臭名在外，这不是远离于礼了吗？远离于礼还不如死。”后来，两兄弟一人在句鼆守门，一人在戾丘守门，都战死了。
六月初一日，发生日食。击鼓，用牺牲在土地神庙里祭祀，这是合于礼的。发生日食，天子减膳撤乐，在土地神庙里击鼓。诸侯用玉帛在土地神庙里祭祀，在朝廷上击鼓，以表明事奉神灵、教训百姓、事奉国君。表示威仪有等级，这是古代的制度。
齐国人允许了单伯要子叔姬回国的请求而赦免了他，派遣他来鲁国传达命令。《春秋》记载说“单伯至自齐”，这是表示尊重他。
在新城的盟会，蔡国人不参加。晋国的郤缺率领上军、下军攻打蔡国，说：“国君年少，不能因此懈怠。”六月初八日，进入蔡国，订立了城下之盟，然后回国。凡是战胜别的国家，叫做“灭之”；得到大城，叫做“入之”。
秋季，齐军侵犯我国西部边境，所以季文子向晋国报告。
冬季，十一月，晋灵公、宋昭公、卫成公、蔡庄侯、陈灵公、郑穆公、许昭公、曹文公在扈地结盟，重温新城盟会的友好，同时策划攻打齐国。齐国人给晋灵公馈送财礼，所以没有战胜就回来了。在这时候发生了齐国进攻我国的灾难，所以文公没有参加盟会。《春秋》记载说“诸侯盟于扈”，这是由于没有救援我国的缘故。凡是诸侯会见，鲁公不参加，《春秋》就不加记载，这是由于隐讳国君的过失。参加了而不记载，这是由于迟到。齐国人前来送回子叔姬，这是由于天子有命令的缘故。
齐懿公发兵进攻我国西部边境，他认为诸侯不能救援。并因此而攻打曹国，进入外城，讨伐曹国曾经前来朝见过鲁国。季文子说：“齐侯恐怕不能免于患难吧？自己就不合于礼，反而讨伐合于礼的国家，说：‘你为什么实行礼？’礼用来顺服上天，这是上天的常道。自己就违反上天，反而又因此付伐别人，这就难免有祸难了。《诗》说：‘为什么不互相敬畏？因为不敬畏上天。’君子不虐待幼小和卑贱，这是由于畏惧上天。在《周颂》里说：‘畏敬上天的威灵，因此就能保有福禄。’不畏敬上天，如何能保得住？用动乱取得国家，奉行礼仪来保持国君的地位，还害怕不得善终，多做不合于礼的事情，这就不得善终了。”', NULL, '', 'indent', 1558952591, '5ceb4a0cba39c800687e86e9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642979, '左传 · 文公 · 文公十六年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有六年春，季孙行父会齐侯于阳谷，齐侯弗及盟。夏五月，公四不视朔。六月戊辰，公子遂及齐侯盟于郪丘。秋八月辛未，夫人姜氏薨。毁泉台。楚人、秦人、巴人灭庸。冬十有一月，宋人弑其君杵臼。
【传】十六年春，王正月，及齐平。公有疾，使季文子会齐侯于阳谷。请盟，齐侯不肯，曰：「请俟君间。」
夏五月，公四不视朔，疾也。公使襄仲纳赂于齐侯，故盟于郪丘。
有蛇自泉宫出，入于国，如先君之数秋八月辛未，声姜薨，毁泉台。
楚大饥，戎伐其西南，至于阜山，师于大林。又伐其东南，至于阳丘，以侵訾枝。庸人帅群蛮以叛楚。麇人率百濮聚于选，将伐楚。于是申、息之北门不启。
楚人谋徙于阪高。蒍贾曰：「不可。我能往，寇亦能住。不如伐庸。夫麇与百濮，谓我饥不能师，故伐我也。若我出师，必惧而归。百濮离居，将各走其邑，谁暇谋人？」乃出师。旬有五日，百濮乃罢。自庐以往，振廪同食。次于句澨。使庐戢黎侵庸，及庸方城。庸人逐之，囚子扬窗。三宿而逸，曰：「庸师众，群蛮聚焉，不如复大师，且起王卒，合而后进。」师叔曰：「不可。姑又与之遇以骄之。彼骄我怒，而后可克，先君蚡冒所以服陉隰也。」又与之遇，七遇皆北，唯裨、鯈、鱼人实逐之。
庸人曰：「楚不足与战矣。」遂不设备。楚子乘馹，会师于临品，分为二队，子越自石溪，子贝自仞，以伐庸。秦人、巴人从楚师，群蛮从楚子盟。遂灭庸。
宋公子鲍礼于国人，宋饥，竭其粟而贷之。年自七十以上，无不馈诒也，时加羞珍异。无日不数于六卿之门，国之才人，无不事也，亲自桓以下，无不恤也。公子鲍美而艳，襄夫人欲通之，而不可，夫人助之施。昭公无道，国人奉公子鲍以因夫人。
于是华元为右师，公孙友为左师，华耦为司马，鳞鱼雚为司徒，荡意诸为司城，公子朝为司寇。初，司城荡卒，公孙寿辞司城，请使意诸为之。既而告人曰：「君无道，吾官近，惧及焉。弃官则族无所庇。子，身之贰也，姑纾死焉。虽亡子，犹不亡族。」既，夫人将使公田孟诸而杀之。公知之，尽以宝行。荡意诸曰：「盍适诸侯？」公曰：「不能其大夫至于君祖母以及国人，诸侯谁纳我？且既为人君，而又为人臣，不如死。」尽以其宝赐左右以使行。夫人使谓司城去公，对曰：「臣之而逃其难，若后君何？」
冬十一月甲寅，宋昭公将田孟诸，未至，夫人王姬使帅甸攻而杀之。荡意诸死之。书曰：「宋人弑其君杵臼。」君无道也。
文公即位，使母弟须为司城。华耦卒，而使荡虺为司马。
', '', '', '十六年春季，周王朝历法的正月，鲁国与齐国议和。文公生病，派季文子和齐懿公在阳穀会见。季文子请求盟誓，齐懿公不肯，说：“请等贵国国君病好了再说吧。”
夏季，五月，文公四次没有在朔日听政，这是由于生重病的缘故。文公派襄仲向齐懿公馈送财礼，所以就在郪丘结盟。
有蛇从泉宫出来，进入国都，共十七条，和先君的数目一样。秋季，八月初八日，声姜死，因此拆毁了泉台。
楚国发生大饥荒，戎人攻打它的西南部，到达阜山，军队驻扎在大林。又进攻它的东南部，到达阳丘，以进攻訾枝。庸国人率领蛮人们背叛楚国，麇国人率领百濮聚集在选地，准备攻打楚国。在这时候，申地、息地的北门不敢打开。
楚国人商量迁到阪高去。蒍贾说：“不行。我们能去，敌人也能去，不如攻打庸国。麇国和百濮，认为我们遭受饥荒而不能出兵，所以攻打我们。如果我们出兵，他们必然害怕而回去。百濮散居各处，将会各回各的地方，谁还有空来打别人的主意？”于是楚国就出兵，过了十五天，百濮就罢兵回去了。
楚军从庐地出发以后，每到一地就打开仓库让将士一起食用。军队驻扎在句澨。派庐戢梨进攻庸国，到达庸国的方城。庸国人赶走楚军，囚禁了子扬窗。过了三个晚上，子扬窗逃跑回来，说：“庸国的军队人数众多，蛮人们聚在那里，不如再发大兵，同时出动国君的直属部队，合兵以后再进攻。”师叔说：“不行。姑且再跟他们交战使他们骄傲。他们骄傲，我们奋发，然后就可以战胜，先君蚡冒就是这样使陉隰归服的。”楚军又和他们接战，七次接战都败走，蛮人中只有裨、鯈、鱼人追赶楚军。庸国人说：“楚国不足以一战了。”就不再设防。
楚庄王乘坐驿站的传车，在临品和前方部队会师，把军队分做两队：子越从石溪出发，子贝从仞地出发，以进攻庸国。秦军、巴军跟随着楚军，蛮人们服从楚王，和他结盟，就把庸国灭亡了。
宋国的公子鲍对国人加以优礼，宋国发生饥荒，把粮食全部拿出来施舍。对年纪在七十岁以上的，没有不送东西的，还按时令加送珍贵食品。没有一天不进出六卿的大门。对国内有才能的人，没有不加事奉的；对亲属中从桓公以下的子孙，没有不加周济的。公子鲍漂亮而且艳丽，宋襄公夫人想和他私通，公子鲍不肯，襄公夫人就帮助他施舍。宋昭公无道，国内的人们都由于襄公夫人的关系而拥护公子鲍。
当时，华元做右师，公子友做左师，华耦做司马、鳞鱹做司徒，荡意诸做司城，公子朝做司寇。当初，司城荡死了，公子寿辞掉司城的官职，请求让荡意诸担任。后来告诉别人说：“国君无道，我的官位接近国君，很怕祸患引到身上。如果丢掉官职不干，家族就无所庇护。儿子，是我的代表，姑且让我晚点死去。这样，虽然丧失儿子，还不致于丧失家族。”不久以后，襄公夫人准备让宋昭公在孟诸打猎而乘机杀死他。宋昭公知道以后，带上了全部珍宝而出行。荡意诸说：“何不到诸侯那里去？”宋昭公说：“得不到自己的大夫至于君祖母以及人们的信任，诸侯谁肯接纳我？而且已经做了别人的君主，再做别人的臣下，不如死了好。”昭公把他的珍宝全部赐给左右随行人员，而让他们离去。襄公夫人派人告诉司城荡意诸离开宋昭公，司城回答说：“做他的臣下，而又逃避他的祸难，怎么能事奉以后的国君呢？”
冬季，十一月二十二日，宋昭公准备去孟诸打猎，没有到达，襄公夫人王姬派遣帅甸进攻并杀死了他，荡意诸为此死了。《春秋》记载说“宋人弑其君杵臼”，这是由于国君无道。宋文公即位，派同母弟做了司城。华耦死后，派荡虺担任司马。
', NULL, '', 'indent', 1558952628, '5ceb4a32c8959c0069dd1c6c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643534, '月令七十二候集解 · 霜降', NULL, 0, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '霜降，九月中。气肃而凝露结为霜矣。《周语》曰：驷见而陨霜。
豺祭兽【《月令》作豺乃祭兽戮禽】。祭兽，以兽而祭天，报本也。方铺而祭，秋金之义。
草木黄落。色黄而摇落也。
蛰虫咸俯【淮南子作俯】。咸，皆也；俯，垂头也。此时寒气肃凛，虫皆垂头而不食矣。', '', '', '', NULL, '', 'indent', 1574374953, '5db29e7dba39c800738a3e34', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642983, '左传 · 宣公 · 宣公二年 ', NULL, 5, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二年春王二月壬子，宋华元帅师及郑公子归生帅师，战于大棘。宋师败绩，获宋华元。秦师伐晋。夏，晋人、宋人、卫人、陈人侵郑。秋九月乙丑，晋赵盾弑其君夷皋。冬十月乙亥，天王崩。
【传】二年春，郑公子归生受命于楚，伐宋。宋华元、乐吕御之。二月壬子，战于大棘，宋师败绩，囚华元，获乐吕，及甲车四百六十乘，俘二百五十人，馘百人。狂狡辂郑人，郑人入于井，倒戟而出之，获狂狡。君子曰：「失礼违命，宜其为禽也。戎，昭果毅以听之之谓礼，杀敌为果，致果为毅。易之，戮也。」
将战，华元杀羊食士，其御羊斟不与。及战，曰：「畴昔之羊，子为政，今日之事，我为政。」与人郑师，故败。君子谓：「羊斟非人也，以其私憾，败国殄民。于是刑孰大焉。《诗》所谓『人之无良』者，其羊斟之谓乎，残民以逞。」
宋人以兵车百乘、文马百驷以赎华元于郑。半入，华元逃归，立于门外，告而入。见叔佯，曰：「子之马然也。」对曰：「非马也，其人也。」既合而来奔。
宋城，华元为植，巡功。城者讴曰：「睅其目，皤其腹，弃甲而复。于思于思，弃甲复来。」使其骖乘谓之曰：「牛则有皮，犀兕尚多，弃甲则那？」役人曰：「从其有皮，丹漆若何？」华元曰：「去之，夫其口众我寡。」
秦师伐晋，以报崇也，遂围焦。夏，晋赵盾救焦，遂自阴地，及诸侯之师侵郑，以报大棘之役。楚斗椒救郑，曰：「能欲诸侯而恶其难乎？」遂次于郑以待晋师。赵盾曰：「彼宗竞于楚，殆将毙矣。姑益其疾。」乃去之。
晋灵公不君：厚敛以雕墙；从台上弹人，而观其辟丸也；宰夫胹熊蹯不熟，杀之，置诸畚，使妇人载以过朝。赵盾、士季见其手，问其故，而患之。将谏，士季曰：「谏而不入，则莫之继也。会请先，不入则子继之。」三进，及溜，而后视之。曰：「吾知所过矣，将改之。」稽首而对曰：「人谁无过？过而能改，善莫大焉。《诗》曰：『靡不有初，鲜克有终。』夫如是，则能补过者鲜矣。君能有终，则社稷之固也，岂唯群臣赖之。又曰：『衮职有阙，惟仲山甫补之。』能补过也。君能补过，衮不废矣。」犹不改。宣子骤谏，公患之，使锄麑贼之。晨往，寝门辟矣，盛服将朝，尚早，坐而假寐。麑退，叹而言曰：「不忘恭敬，民之主也。贼民之主，不忠。弃君之命，不信。有一于此，不如死也。」触槐而死。
秋九月，晋侯饮赵盾酒，伏甲将攻之。其右提弥明知之，趋登曰：「臣侍君宴，过三爵，非礼也。」遂扶以下，公嗾夫獒焉。明搏而杀之。盾曰：「弃人用犬，虽猛何为。」斗且出，提弥明死之。
初，宣子田于首山，舍于翳桑，见灵辄饿，问其病。曰：「不食三日矣。」食之，舍其半。问之，曰：「宦三年矣，未知母之存否，今近焉，请以遗之。」使尽之，而为之箪食与肉，置诸橐以与之。既而与为公介，倒戟以御公徒，而免之。问何故。对曰：「翳桑之饿人也。」问其名居，不告而退，遂自亡也。
乙丑，赵穿攻灵公于桃园。宣子未出山而复。大史书曰：「赵盾弑其君。」以示于朝。宣子曰：「不然。」对曰：「子为正卿，亡不越竟，反不讨贼，非子而谁？」宣子曰：「乌呼，『我之怀矣，自诒伊戚』，其我之谓矣！」孔子曰：「董孤，古之良史也，书法不隐。赵宣子，古之良大夫也，为法受恶。惜也，越竟乃免。」
宣子使赵穿逆公子黑臀于周而立之。壬申，朝于武宫。
初，丽姬之乱，诅无畜群公子，自是晋无公族。及成公即位，乃宦卿之适子而为之田，以为公族，又宦其馀子亦为余子，其庶子为公行。晋于是有公族、余子、公行。赵盾请以括为公族，曰：「君姬氏之爱子也。微君姬氏，则臣狄人也。」公许之。
冬，赵盾为旄车之族。使屏季以其故族为公族大夫。', '', '', '二年春季，郑国公子归生接受楚国命令攻打宋国。宋国华元、乐吕带兵抵御。二月十日，在大棘地方开战，宋军大败。郑国囚禁了华元，得到乐吕的尸首，缴获战车四百六十辆，俘虏二百五十人，割了一百个被打死的敌人的耳朵。
狂狡迎战郑国人，那个郑国人逃进井里。狂狡把戟柄放下井去拉他上来。那个人出井以后反而俘虏了狂狡。君子说：“丢掉礼而违背命令，他活该被俘。战争，发扬果敢刚毅的精神以服从命令叫做礼。杀死敌人就是果敢，达到果敢就是刚毅。如果反过来，就要被杀戮。”
准备开战的时候，华元杀羊犒赏士兵，他的车夫羊斟没有吃到。等到打起仗来，羊斟说：“前天的羊，是你作主；今天的打仗，是我作主。”就驱车进入郑军，所以宋军失败。君子认为：“羊斟不像个人，由于私怨，使国家战败、百姓受害，还有比这应当受到更重的刑罚吗？《诗》所谓‘存心不良’，羊斟就是这种人吧！他残害百姓以使自己快意。”
宋国人用兵车一百辆、毛色漂亮的马四百匹，从郑国赎取华元。仅送去一半，华元就逃回来了。华元站在城门外，告诉守门人自己的身分，然后进城。见到羊斟说：“您的马不受驾御才会这样吧？”羊斟回答说：“不是马，是人。”回答完就逃到鲁国来。
宋国筑城，华元作为主持者，巡视工作。筑城的人唱歌说：“鼓着眼，挺着肚，丢了皮甲往回走。连鬓胡，长满腮，丢盔卸甲逃回来。”华元使他的骖乘对他们说：“有牛就有皮，犀牛兕牛多的是，丢了皮甲又有什么了不起？”做工的人说：“即使有牛皮，又去哪里找红漆？”华元说：“走吧！他们的嘴多，我们的嘴少。”
秦国军队攻打晋国，以报复晋军侵入崇地的那次战役，因此而包围焦地。夏季，晋国赵盾救援焦地，于是从阴地会同诸侯的军队袭击郑国，以报复郑国攻打大棘的那次战役。楚国鬬椒救援郑国，说：“难道想得到诸侯的拥护，而又害怕困难吗？”楚军就驻扎在郑国，等待晋军。赵盾说：“他那个宗族在楚国争权夺利，差不多要完蛋了。暂且让他加重弊病。”于是就离开郑国。
晋灵公做事不合为君之道：重重地收税用来彩画墙壁，从高台上用弹丸打人而看他们躲避弹丸的形状。有一次，厨子烧煮熊掌不熟，灵公杀死他，放在畚箕里，让女人用车装着走过朝廷。赵盾和士会看到死人的手，问起杀人的缘故，感到担心，准备进谏。士会对赵盾说：“你劝谏如果听不进去，就没有人继续劝谏了。请让士会先去，不听，你再接着劝谏。”士会前去三次，到达屋檐下，晋灵公才转眼看他，说：“我知道错了，打算改正。”士会叩头回答说：“一个人谁没有错，有了过错能够改正，就没有比这再好的事情了。《诗》说：‘事情不难有个好开始，很少能有个好结果。’如果像这样，能够弥补过错的人就很少了。君王能够有好结果，那就是国家的保障了，岂只仅仅臣下们依靠它。《诗》又说：‘周宣王有了过失，只有仲山甫来弥补。’这说的是能够弥补错误。君王能够弥补错误，礼服就不会丢弃了。”晋灵公尽管口头上说要改错，行动上还是不改正。赵盾屡次进谏，晋灵公很讨厌，派遣鉏麑去刺杀他。一天清早，赵盾的卧室门已经打开了，穿得整整齐齐，准备入朝。时间还早，赵盾正坐着打瞌睡。鉏麑退出来，叹气说：“不忘记恭敬，真是百姓的主人。刺杀百姓的主人，就是不忠；放弃国君的使命，
就是不信。两件事情有了一件，不如死了好。”撞在槐树上死去了。
秋九月，晋灵公请赵盾喝酒，预先埋伏下甲士准备攻杀赵盾。赵盾的车右提弥明发觉了，快步登上殿堂，说：“臣子陪侍国君饮酒，超过三杯就是违背礼节。”说完便扶着赵盾下了殿堂，晋灵公急忙唤出猛犬，提弥明徒手与猛犬搏斗，并打死了它。赵盾说：“废弃忠良之人而用猛犬，犬虽猛又有何用！”一路且斗且退，提弥明为掩护赵盾被杀。
当初，赵盾在首阳山打猎，住在翳桑，看见灵辄饿倒在地上，问他有什么病。灵辄说：“已经三天没吃东西了。”赵盾给他食物，他留下一半。问他为什么，他说：“在外学习做官已经三年了，不知道母亲还在不在，现在快到家了，请让我把这个留给她。”赵盾让他吃完，并且又给他准备了一筐饭和一些肉，放在袋子里给了他。后来灵辄做了晋灵公的卫兵，在这次事件中，倒过戟来抵御晋灵公的其他卫兵，使赵盾免于祸难。赵盾问他为什么这样做，他回答说：“我就是翳桑那个饿倒的人。”问他的姓名住处，他不回答而退了出去，就自己逃亡了。
九月二十六日，赵穿在桃园杀死了晋灵公。赵盾没有走出晋国国境就回来再度做卿。太史记载说：“赵盾弑其君”，在朝廷上公布。赵盾说：“不是这样。”太史回答说：“您是正卿，逃亡而没有走出国境，回来不惩罚凶手，弑君的人不是您还是谁？”赵盾说：“哎呀！《诗》说：‘因为我的怀恋，给自己带来了忧戚。’恐怕就是说的我了。”孔子说：“董狐，是古代的好史官，据事直书而不加隐讳。赵宣子，是古代的好大夫，因为法度而蒙受恶名。太可惜了，要是走出了国境，就可以避免背上弑君的罪名了。”
赵盾派遣赵穿到成周迎接公子黑臀而立他为国君。十月初三日，公子黑臀到武官庙朝祭。
当初，丽姬作乱的时候，在神前诅咒，不许收容公子们，从此晋国没有公族这个官职。等到晋成公即位，就把官职授给卿的嫡长子，并且给他们土田，让他们做公族大夫。又把官职授给卿的其他儿子，也让他们担任馀子的官，让他们的庶子担任公行的官。晋国从此开始有了公族、馀子、公行三种官职。
赵盾请求让赵括担任公族大夫，说：“他是君姬氏的爱子。如果没有君姬氏，那么下臣就是狄人了。”晋成公同意了。冬季，赵盾掌管旄车之族，让赵括统率他的旧族，做公族大夫。
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b665bb5420e2767ef2eef", "shortContent": " 这篇文章以夹叙夹议的方式讲述两件事。一是郑、宋两国的大棘之战，宋国惨败，主将乐吕战死，华元被俘。另一件事，即晋国统治集团内部的一场惊心动魄的政治斗争。大臣赵盾因多次批评晋灵公的胡作非为而两次遭到昏君派遣的杀手的行刺，幸免于难后外出流亡，将要出境时获悉灵公被杀，返回迎立公子黑臀为君。这篇记述对其中人物的行为表明了自己的立场，表明人们对于国家和人民应有的态度，也反映了古人在对待君主问题上的两难处境。...", "authors": ["贺圣迪", "魏自厚"], "pressName": "上海辞书出版社"}]', '', 'indent', 1565349556, '5ceb4adc43e78c0067142761', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642984, '左传 · 宣公 · 宣公三年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三年春王正月，郊牛之口伤，改卜牛。牛死，乃不郊。犹三望。葬匡王。楚子伐陆浑之戎。夏，楚人侵郑。秋，赤狄侵齐。宋师围曹。冬十月丙戌。郑伯兰卒。葬郑穆公。
【传】三年春，不郊而望，皆非礼也。望，郊之属也。不郊亦无望，可也。
晋侯伐郑，及郔。郑及晋平，士会入盟。
楚子伐陆浑之戎，遂至于洛，观兵于周疆。定王使王孙满劳楚子。楚子问鼎之大小轻重焉。对曰：「在德不在鼎。昔夏之方有德也，远方图物，贡金九牧，铸鼎象物，百物而为之备，使民知神、奸。故民入川泽山林，不逢不若。螭魅罔两，莫能逢之，用能协于上下以承天休。桀有昏德，鼎迁于商，载祀六百。商纣暴虐，鼎迁于周。德之休明，虽小，重也。其建回昏乱，虽大，轻也。天祚明德，有所底止。成王定鼎于郏鄏，卜世三十，卜年七百，天所命也。周德虽衰，天命未改，鼎之轻重，未可问也。」
夏，楚人侵郑，郑即晋故也。
宋文公即位三年，杀母弟须及昭公子。武氏之谋也，使戴、桓之族攻武氏于司马子伯之馆。尽逐武、穆之族。武、穆之族以曹师伐宋。秋，宋师围曹，报武氏之乱也。
冬，郑穆公卒。
初，郑文公有贱妾曰燕姞，梦天使与己兰，曰：「余为伯鯈。余，而祖也，以是为而子。以兰有国香，人服媚之如是。」既而文公见之，与之兰而御之。辞曰：「妾不才，幸而有子，将不信，敢征兰乎。」公曰：「诺。」生穆公，名之曰兰。
文公报郑子之妃，曰陈妫，生子华、子臧。子臧得罪而出。诱子华而杀之南里，使盗杀子臧于陈、宋之间。又娶于江，生公子士。朝于楚，楚人鸩之，及叶而死。又娶于苏，生子瑕、子俞弥。俞弥早卒。泄驾恶瑕，文公亦恶之，故不立也。公逐群公子，公子兰奔晋，从晋文公伐郑。石癸曰：「吾闻姬、姞耦，其子孙必蕃。姞，吉人也，后稷之元妃也，今公子兰，姞甥也。天或启之，必将为君，其后必蕃，先纳之可以亢宠。」与孔将锄、侯宣多纳之，盟于大宫而立之。以与晋平。
穆公有疾，曰：「兰死，吾其死乎，吾所以生也。」刈兰而卒。
', '', '', '三年春季，没有举行郊祭却举行望祭，这都不合于礼。望祭，是属于郊祭的一种，不举行郊祭，也不必举行望祭了。晋成公发兵攻打郑国，到达郔地。郑国和晋国讲和，士会到郑国缔结盟约。
楚庄王发兵攻打陆浑的戎人，到达雒水，在周朝的直辖地域陈兵示威。周定王派遣王孙满慰劳楚庄王。楚庄王问起九鼎的大小轻重如何。王孙满回答说：“鼎的大小轻重在于德而不在于鼎本身。从前夏朝正是有德的时候，把远方的东西画成图像，让九州的长官进贡铜器，铸造九鼎并且把图像铸在鼎上，所有物像都具备在上面了，让百姓知道神物和怪物。所以百姓进入川泽山林，就不会碰上不利于自己的东西。螭魅魍魉这些鬼怪都不会遇上，因而能够使上下和谐，以承受上天的福佑。夏桀昏乱，把鼎迁到了商朝，前后六百年。商纣暴虐，鼎又迁到了周朝，德行如果美善光明，鼎虽然小，也是重的。如果奸邪昏乱，鼎虽然大，也是轻的。上天赐福给明德的人，是有一定期限的。成王把九鼎固定在郏鄏，占卜的结果是传世三十代，享国七百年，这是上天所命令的。周朝的德行虽然衰微，天命并没有改变。鼎的轻重，是不能询问的。”
夏季，楚国人入侵郑国，这是由于郑国倾向晋国的缘故。
宋文公即位的第三年，杀了同胞弟弟须和昭公的儿子，这是出于武氏的谋划。于是就让戴公、桓公的族人在司马子伯的客馆里攻打武氏，把武公、穆公的族人全部驱赶出国。武公、穆公的族人用曹国的军队攻打宋国。秋季，宋国军队包围曹国，以报复武氏的叛乱。
冬季，郑穆公去世。当初，郑文公有一个贱妾名叫燕姞，梦见天使给她一支兰花，说：“我是伯鯈。我，是你的祖先，把兰作为你的儿子。因为兰花的香味在全国数第一，佩带着它，别人就会像爱它一样地爱你。”不久以后，文公见到燕姞，给她一支兰花而让她侍寝。燕姞告诉文公说：“我的地位低贱，侥幸怀了孩子。如果别人不相信，敢请把兰花用来作为信物。”文公说：“好。”生了穆公，取名叫兰。
郑文公奸淫了郑子的妃子叫做陈妫的，生了子华、子臧。子臧得了罪而离开了郑国。郑文公将子华诱骗到南里并杀死了他，又派坏人把子臧杀死在陈、宋两国之间。又在江国娶妻，生了公子士。公子士到楚国朝见，楚国人给他喝了毒酒，到叶地就死了。又在苏国娶妻，生了子瑕、子俞弥。俞弥早死。泄驾讨厌子瑕，郑文公也讨厌他，所以没有立为太子。郑文公赶走公子们，公子兰逃亡到晋国，跟随晋文公攻打郑国。石癸说：“我听说姬、姞两姓适合于成为配偶，他们的子孙必定蕃衍。姞，就是吉人的意思，是后稷的嫡妻。现在公子兰是姞氏的外甥，上天或许要使他光大，必然会做国君，他的后代必然蕃盛。如果先接纳他为国君，就可以保持他的宠信。”于是石癸就和孔将鉏、侯宣多收纳了公子兰，在大宫里盟誓以后而立了公子兰为国君，以此与晋国讲和。
郑穆公有病，说：“兰花死了，我也许要死了吧！我是靠着它出生的。”割掉了兰花，郑穆公就死了。
', NULL, '', 'indent', 1558952827, '5ceb4af8ba39c800687e9127', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642985, '左传 · 宣公 · 宣公四年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】四年春王正月，公及齐侯平莒及郯。莒人不肯。公伐莒，取向。秦伯稻卒。夏六月乙酉，郑公子归生弑其君夷。赤狄侵齐。秋，公如齐。公至自齐。冬，楚子伐郑。
【传】四年春，公及齐侯平莒及郯，莒人不肯。公伐莒，取向，非礼也。平国以礼不以乱，伐而不治，乱也。以乱平乱，何治之有？无治，何以行礼？
楚人献鼋于郑灵公。公子宋与子家将见。子公之食指动，以示子家，曰：「他日我如此，必尝异味。」及入，宰夫将解鼋，相视而笑。公问之，子家以告，及食大夫鼋，召子公而弗与也。子公怒，染指于鼎，尝之而出。公怒，欲杀子公。子公与子家谋先。子家曰：「畜老，犹惮杀之，而况君乎？」反谮子家，子家惧而从之。夏，弑灵公。书曰：「郑公子归生弑其君夷。」权不足也。君子曰：「仁而不武，无能达也。」凡弑君，称君，君无道也；称臣，臣之罪也。
郑人立子良，辞曰：「以贤则去疾不足，以顺则公子坚长。」乃立襄公。襄公将去穆氏，而舍子良。子良不可，曰：「穆氏宜存，则固愿也。若将亡之，则亦皆亡，去疾何为？」乃舍之，皆为大夫。
初，楚司马子良生子越椒，子文曰：「必杀之。是子也，熊虎之状，而豺狼之声，弗杀，必灭若敖氏矣。谚曰：『狼子野心。』是乃狼也，其可畜乎？」子良不可。子文以为大戚，及将死，聚其族，曰：「椒也知政，乃速行矣，无及于难。」且泣曰：「鬼犹求食，若敖氏之鬼，不其馁而？」及令尹子文卒，斗般为令尹，子越为司马。蒍贾为工正，谮子扬而杀之，子越为令尹，己为司马。子越又恶之，乃以若敖氏之族圄伯嬴于□□阳而杀之，遂处烝野，将攻王。王以三王之子为质焉，弗受，师于漳澨。秋七月戊戌，楚子与若敖氏战于皋浒。伯棼射王，汰輈，及鼓跗，着于丁宁。又射汰輈，以贯笠毂。师惧，退。王使巡师曰：「吾先君文王克息，获三矢焉。伯棼窃其二，尽于是矣。」鼓而进之，遂灭若敖氏。
初，若敖娶于云阜，生斗伯比。若敖卒，从其母畜于云阜，淫于云阜子之女，生子文焉云阜夫人使弃诸梦中，虎乳之。云阜子田，见之，惧而归，以告，遂使收之。楚人谓乳谷，谓虎於菟，故命之曰斗谷於菟。以其女妻伯比，实为令尹子文。其孙箴尹克黄使于齐，还，及宋，闻乱。其人曰，「不可以入矣。」箴尹曰：「弃君之命，独谁受之？尹，天也，天可逃乎？」遂归，覆命而自拘于司败。王思子文之治楚国也，曰：「子文无后，何以劝善？」使复其所，改命曰生。
冬，楚子伐郑，郑未服也。
', '', '', '四年春季，鲁宣公和齐惠公使莒国和郯国讲和，莒人不肯。宣公攻打莒国，占领了向地，这是不合于礼的。和别国讲和应该用礼，不应该用动乱。讨伐就不能安定，就是动乱。用动乱去平定动乱，还有什么安定？没有安定，用什么来实行礼？
楚国人献给郑灵公一只大甲鱼。公子宋和子家将要进见，走在路上，公子宋的食指忽然自己动了起来，就把它给子家看，说：“以往我遇到这种情况，一定可以尝到美味。”等到进去以后，厨师正准备切甲鱼，两人互相看着而笑起来。郑灵公问他们为什么笑，子家就把刚才的情况告诉郑灵公。等到郑灵公把甲鱼赐给大夫们吃的时候，也把公子宋召来但偏不给他吃。公子宋发怒，用手指头在鼎里蘸了蘸，尝到味道后才退出去。郑灵公发怒，要杀死公子宋。公子宋和子家策划先下手。子家说：“牲口老了，尚且怕杀，何况国君？”公子宋就反过来诬陷子家。子家害怕，只好跟着他干，夏季，杀死了郑灵公。《春秋》记载说：“郑公子归生弑其君夷。”这是由于子家的权力不足的缘故。君子说：“仁爱而没有勇武，总是达不到目的。”凡是杀死国君，如果只记载国君的名字，这是由于国君无道；记载臣下的名字，这就是臣下有罪过。
郑国人要立子良为国君，子良辞谢说：“以贤明而论，去疾是不够的，以顺序而论，公子坚年长。”就立了郑襄公。襄公准备驱逐他的兄弟们，而赦免了子良。子良不同意，说：“穆公的儿子如果适合留下来，去疾本来就有这样的愿望。如果要离开郑国，那就都离开，为什么单独留下去疾？”于是赦免了他们，让他们都做大夫。
当初，楚国的司马子良生了子越椒。子文说：“一定要杀死他！这个孩子，有熊虎的形状、豺狼的声音，不杀，必然会灭亡若敖氏了。俗话说：‘狼子野心。’这孩子是一条狼，难道能够养着吗？”子良不同意，子文把这件事当成一件很大的忧心事，到他临死的时候，聚集了他的族人，说：“如果越椒一旦执政，就快点走吧，不要遭到祸难。”同时哭着说：“鬼尚且要求吃东西，若敖氏的鬼不是要挨饿了吗！”等到令尹子文死去，鬬般担任令尹，子越担任司马。..贾出任工正，诬陷子扬并且杀了他，子越就做了令尹，他自己做了司马。子越又讨厌他，就带领了若敖氏的族人把伯嬴囚禁在轑阳并且杀死了他，于是就住在烝野地方，准备进攻楚庄王。楚庄王用三代国王的子孙作为人质，子越不接受。楚庄王在漳澨用兵。秋季，七月初九日，楚庄王和若敖氏在皋浒作战。子越椒用箭射楚庄王，力量强而箭镞锋利，箭飞过车辕，穿过鼓架，射在铜钲上。又射一箭，飞过车辕，透过车盖。士兵害怕，开始退却。楚庄王派人在军队里到处喊着说：“我们的先君文王攻克息国，得到三枝箭，子越椒偷去两枝，已经全用完了。”于是楚王下令击鼓进军，就消灭了若敖氏。
当初，若敖在..国娶妻，生了鬬伯比。若敖死后，跟着他的母亲养在..国，和..子的女儿私通，生了子文。..夫人让人把子文丢在云梦泽里，有老虎给他喂奶，..子打猎，看到这场面，害怕而回来。夫人把女儿私生子的情况告诉..子，..子就让人收养了子文。楚国人把奶叫做“穀”，把老虎叫做“於菟”，所以就把这个孩子叫做鬬穀於菟。..子把他的女儿嫁给鬬伯比做妻子。鬬穀於菟就是令尹子文。
子文的孙子箴尹克黄出使齐国，回来时到达宋国，听到叛乱消息。有人说：“不能回去了。”箴尹说“丢掉国君的命令，还有谁来接受我？国君，就是上天，难道可以逃避上天吗？”就回到楚国复命，并且自动到法官那里请求囚禁。楚庄王想起子文治理楚国的功绩，说：“子文如果没有后代，如何劝人为善？”就让克黄恢复原来的官职，把他的名字改为“生”。
子文的孙子箴尹克黄出使齐国，回来时到达宋国，听到叛乱消息。有人说：“不能回去了。”箴尹说“丢掉国君的命令，还有谁来接受我？国君，就是上天，难道可以逃避上天吗？”就回到楚国复命，并且自动到法官那里请求囚禁。楚庄王想起子文治理楚国的功绩，说：“子文如果没有后代，如何劝人为善？”就让克黄恢复原来的官职，把他的名字改为“生”。
', NULL, '', 'indent', 1558952894, '5ceb4b3ca673f5006815b7f3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642986, '左传 · 宣公 · 宣公五年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】五年春，公如齐。夏，公至自齐。秋九月，齐高固来逆叔姬。叔孙得臣卒。冬，齐高固及子叔姬来。楚人伐郑。
【传】五年春，公如齐，高固使齐侯止公，请叔姬焉。
夏，公至自齐，书，过也。
秋九月，齐高固来逆女，自为也。故书曰：「逆叔姬。」即自逆也。
冬，来，反马也。
楚子伐郑，陈及楚平。晋荀林父救郑，伐陈。
', '', '', '楚国人献给郑灵公一只大甲鱼。公子宋和子的妻子。
夏季，宣公从齐国回来，《春秋》记载这件事，这是因为他有过失。
秋季，九月，齐国的高固前来迎接叔姬，这是为了自己。所以《春秋》记载说“逆叔姬”，这是由于卿亲自迎娶的缘故。
冬季，高固和子叔姬来鲁国，这是为了履行“返马”这一古代婚姻礼节。
楚庄王进攻郑国。陈国和楚国讲和。晋国的荀林父救援郑国，进攻陈国。
', NULL, '', 'indent', 1558952935, '5ceb4b6543e78c0067142c94', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642987, '左传 · 宣公 · 宣公六年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】六年春，晋赵盾、卫孙免侵陈。夏四月。秋八月，螽。冬十月。
【传】六年春，晋、卫侵陈，陈即楚故也。
夏，定王使子服求后于齐。
秋，赤狄伐晋。围怀，及邢丘。晋侯欲伐之。中行桓子曰：「使疾其民，以盈其贯，将可殪也。《周书》曰：『殪戎殷。』此类之谓也。」
冬，召桓公逆王后于齐。
楚人伐郑，取成而还。
郑公子曼满与王子伯廖语，欲为卿。伯廖告人曰：「无德而贪，其在《周易》《丰》三之《离》三，弗过之矣。」间一岁，郑人杀之。


', '', '', '六年春季，晋国、卫国入侵陈国，这是由于陈国偏向楚国的缘故。
夏季，周定王派遣子服到齐国求娶齐女为王后。
秋季，赤狄进攻晋国，包围了怀地和邢丘。晋成公打算反攻。中行桓子说：“让他危害他自己的百姓，以使他恶贯满盈，到时候大概就可以歼灭了。《周书》说：‘歼灭大国殷朝’，说的就是这一类的事情。”
冬季，周卿士召桓公到齐国迎接王后。
楚军攻打郑国，讲和以后就回去了。
郑国的公子曼满对王子伯廖说，他想要做卿。伯廖告诉别人说：“没有德行而又贪婪，他是应在《周易》《丰》卦变成《离》卦这样的卦象上，不会超过三年，必然灭亡。”隔了一年，郑国人杀死了公子曼满。', NULL, '', 'indent', 1558952977, '5ceb4b8fc8959c0069dd2a62', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642988, '左传 · 宣公 · 宣公七年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】七年春，卫侯使孙良夫来盟。夏，公会齐侯伐莱。秋，公至自伐莱。大旱。冬，公会晋侯、宋公、卫侯、郑伯、曹伯于黑壤。
【传】七年春，卫孙桓子来盟，始通，且谋会晋也。
夏，公会齐侯伐莱，不与谋也。凡师出，与谋曰及，不与某曰会。
赤狄侵晋，取向阴之禾。
郑及晋平，公子宋之谋也，故相郑伯以会。冬，盟于黑壤，王叔桓公临之，以谋不睦。
晋侯之立也，公不朝焉，又不使大夫聘，晋人止公于会，盟于黄父。公不与盟，以赂免。故黑壤之盟不书，讳之也。', '', '', '七年春季，卫国的孙桓子来鲁国缔结盟约，两国开始修好，同时商量和晋国会见。
夏季，鲁宣公会合齐惠公联兵进攻莱国，这是由于事先并没有让我国参与策划。凡是出兵，事先参与策划叫做“及”，没有参与策划叫做“会”。
赤狄入侵晋国，割取了向阴的谷子。
郑国和晋国讲和，这是出于公子宋的谋划，所以公子宋作为郑君的赞助行礼者来参加盟会。冬季，在黑壤结盟。周卿士王叔桓公到会监临，以促成不和睦的诸侯重建邦交。
晋成公即位的时候，鲁宣公没有去朝见，又不派大夫访问，晋国人因此在会上拘留了他。在黄父结盟，宣公没有参加，由于向晋国送了一些财物才得以被释放回国。所以《春秋》不记载黑壤的结盟，这是由于隐讳国君受辱。', NULL, '', 'indent', 1558953031, '5ceb4bc430863b006826dbb8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642989, '左传 · 宣公 · 宣公八年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】八年春，公至自会。夏六月，公子遂如齐，至黄乃复。辛巳，有事于大庙，仲遂卒于垂。壬午，犹绎。万入，去籥。戊子，夫人赢氏薨。晋师、白狄伐秦。楚人灭舒蓼。秋七月甲子，日有食之，既。冬十月己丑，葬我小君敬赢。雨，不克葬。庚寅，日中而克葬。城平阳。楚师伐陈。
【传】八年春，白狄及晋平。夏，会晋伐秦。晋人获秦谍，杀诸绛市，六日而苏。
有事于大庙，襄仲卒而绎，非礼也。
楚为众舒叛，故伐舒蓼，灭之。楚子疆之，及滑汭。盟吴、越而还。
晋胥克有蛊疾，郤缺为政。秋，废胥克。使赵朔佐下军。
冬，葬敬赢。旱，无麻，始用葛茀。雨，不克葬，礼也。礼，卜葬，先远日，辟不怀也。
城平阳，书，时也。
陈及晋平。楚师伐陈，取成而还。', '', '', '八年春季，白狄和晋国讲和。夏季，会合晋国进攻秦国。晋国人抓住秦国的一个间谍，把他杀死在绛城的街市上，过了六天又复活了。
在太庙举行祭祀，襄仲死后接连两天举行祭祀，这是不合于礼的。
楚国因为舒姓诸侯背叛，所以进攻舒、蓼，灭亡了舒、蓼两国。楚庄王给它们划定疆界，到达滑水的转折处，同时和吴国、越国结盟而回去。
晋国胥克得了食物中毒的病，郤缺主持国政。秋季，废了胥克，任命赵朔做下军的副帅。
冬季，安葬敬嬴。由于旱灾，没有麻，开始用葛做牵引棺材的绳子。由于下雨，不能如期下葬，这是符合礼的。按礼的一般的规定，占卜安葬的日期，先占卜较远的日期，以避免别人认为对死者不加怀念。
鲁国在平阳筑城，《春秋》记载这件事，是因为合于时令。
陈国和晋国讲和。楚国的军队进攻陈国，讲和以后回国。', NULL, '', 'indent', 1558953068, '5ceb4bea30863b006826de08', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (645951, '将苑 · 卷一 · 将刚', NULL, 1, 60, 1, 1, '诸葛亮', NULL, 10026, '57b8f8452e958a005fa50d86', '三国', 'wen', '文', '将苑', '', '善将者，其刚不可折，其柔不可卷，故以弱制强，以柔制刚。纯柔纯弱，其势必削；纯刚纯强，其势必亡；不柔不刚，合道之常。', '', '', '好的将帅应该具备的性格是刚强、刚烈，但不固执己见，温和、柔和但不软弱无力，即通常听说的刚柔相济。单纯一味的柔和、软弱，就会使自己的力量被削减，以至失败，单纯一味的刚烈、刚强又会导致刚愎自用也注定要灭亡。所以，不柔不刚，刚柔并济才是最理想的性格特点，才是最佳的状态。', NULL, '', 'indent', 1588354546, '5eabed70d6e3f2000808f72d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642990, '左传 · 宣公 · 宣公九年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】九年春王正月，公如齐。公至自齐。夏，仲孙蔑如京师。齐侯伐莱。秋，取根牟。八月，滕子卒。九月，晋侯、宋公、卫侯、郑伯、曹伯会于扈。晋荀林父帅师伐陈。辛酉，晋侯黑臀卒于扈。冬十月癸酉，卫侯郑卒。宋人围滕。楚子伐郑。晋郤缺帅师救郑。陈杀其大夫泄冶。
【传】九年春，王使来徵聘。夏，孟献于聘于周，王以为有礼，厚贿之。
秋，取根牟，言易也。
滕昭公卒。
会于扈，讨不睦也。陈侯不会。晋荀林父以诸侯之师伐陈。晋侯卒于扈，乃还。
冬，宋人围滕，因其丧也。
陈灵公与孔宁、仪行父通于夏姬，皆衷其示日服以戏于朝。泄冶谏曰：「公卿宣淫，民无效焉，且闻不令，君其纳之。」公曰：「吾能改矣。」公告二子，二子请杀之，公弗禁，遂杀泄冶。孔子曰：「《诗》云：『民之多辟，无自立辟。』其泄冶之谓乎。」
楚子为厉之役故，伐郑。
晋郤缺救郑，郑伯败楚师于柳棼。国人皆喜，唯子良忧曰：「是国之灾也，吾死无日矣。」
', '', '', '九年春季，周定王的使者来鲁国要求派人去聘问。夏季，孟献子去成周聘问。周定王认为有礼，赠给他丰厚的财礼。
秋季，占领了根牟，《春秋》记载是说很容易。
滕昭公死。
晋成公、宋文公、卫成公、郑襄公、曹文公在扈地会见，这是由于准备攻打不听从晋国的国家。陈灵公没有参加会见，晋国的荀林父率领诸侯的军队进攻陈国。晋成公死在扈地，荀林父便率兵回国。
冬季，宋军包围滕国，这是乘滕国有丧事。
陈灵公和孔宁、仪行父与夏姬通奸，都把夏姬的汗衣贴身穿着，而且在朝廷上开玩笑。泄冶进谏说：“国君和卿宣扬淫乱，百姓就无所效法，而且名声不好。君王还是把那件汗衫收藏起来吧！”陈灵公说：“我能够改过了。”陈灵公把泄冶的话告诉孔宁、仪行父两个人，这两个人请求杀死泄冶，陈灵公不加禁止，于是就杀了泄冶。孔子说：“《诗》说：‘百姓多行邪恶，就不要再去自立法度。’这说的就是泄冶吧！”
楚庄王为了厉地战役的缘故，进攻郑国。
晋国的郤缺率兵去救援郑国，郑襄公在柳棼打败了楚军。国内的人们都很欢喜，只有子良担心说：“这是国家的灾难，我离死期不远了。”', NULL, '', 'indent', 1558953102, '5ceb4c0c30863b006826e0f1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642991, '左传 · 宣公 · 宣公十年 ', NULL, 2, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十年春，公如齐。公至自齐。齐人归我济西田。夏四月丙辰，日有食之。己巳，齐侯元卒。齐崔氏出奔卫。公如齐。五月，公至自齐。癸巳，陈夏征舒弑其君平国。六月，宋师伐滕。公孙归父如齐，葬齐惠公。晋人、宋人、卫人、曹人伐郑。秋，天王使王季子来聘。公孙归父帅师伐邾，取绎。大水。季孙行父如齐。冬，公孙归父如齐。齐侯使国佐来聘。饥。楚子伐郑。
【传】十年春，公如齐。齐侯以我服故，归济西之田。
夏，齐惠公卒。崔杼有宠于惠公，高、国畏其逼也，公卒而逐之，奔卫。书曰「崔氏」，非其罪也，且告以族，不以名。凡诸侯之大夫违，告于诸侯曰：「某氏之守臣某，失守宗庙，敢告。」所有玉帛之使者，则告，不然，则否。
公如齐奔丧。
陈灵公与孔宁、仪行父饮酒于夏氏。公谓行父曰：「征舒似女。」对曰：「亦似君。」征舒病之。公出，自其厩射而杀之。二子奔楚。
滕人恃晋而不事宋，六月，宋师伐滕。
郑及楚平。诸侯之师伐郑，取成而还。
秋，刘康公来报聘。
师伐邾，取绎。
季文子初聘于齐。
冬，子家如齐，伐邾故也。
国武子来报聘。
楚子伐郑。晋士会救郑，逐楚师于颖北。诸侯之师戍郑。郑子家卒。郑人讨幽公之乱，斫子家之棺而逐其族。改葬幽公，谥之曰灵。', '', '', '十年春季，鲁宣公到了齐国。齐惠公因为我国顺服的缘故，把济水以西的土田归还给我国。
夏季，齐惠公去世。崔杼受到齐惠公的宠信，高、国两族惧怕他威逼，惠公死后就赶走了崔杼，崔杼逃亡到卫国。《春秋》记载说“崔氏”，是说这不是他的罪过，而且把这件事通告诸侯时，也称族而不称名。凡是诸侯的大夫离开本国，通告诸侯说：“某氏的守臣某，不能守宗庙了，谨此通告。”凡是有友好往来的国家就发给通告，不是，就不发通告。
宣公奔赴齐国参加丧礼。
陈灵公和孔宁、仪行父在夏征舒家喝酒。灵公对仪行父说：“征舒长得像你。”仪行父回答说：“也像君王。”夏征舒对此感到愤恨。灵公出去，夏征舒从马房里用箭射死灵公。孔宁、仪行父逃亡到楚国。
滕国人依靠晋国而不事奉宋国，六月，宋国的军队进攻滕国。
郑国和楚国讲和，诸侯的军队进攻郑国，讲和以后回国。
秋季，刘康公前来回聘。
鲁国出兵进攻邾国，占领了绎地。
季文子第一次到齐国聘问。
冬季，子家到了齐国，这是为了向齐国解释鲁国进攻了邾国的缘故。
国武子前来回聘。
楚庄王进攻郑国。晋国的士会去救郑国，在颍水北面赶走了楚军。诸侯的军队在郑国留守。郑国的子家死。郑国人为了讨伐杀害幽公的那次动乱，打开了子家的棺材，并赶走了他的族人。改葬幽公，把他的谥号改为“灵”。
', NULL, '', 'indent', 1558953150, '5ceb4c3ad5de2b0070792916', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642992, '左传 · 宣公 · 宣公十一年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有一年春王正月。夏，楚子、陈侯、郑伯盟于辰陵。公孙归父会齐人伐莒。秋，晋侯会狄于欑函。冬十月，楚人杀陈夏征舒。丁亥，楚子入陈。纳公孙宁、仪行父于陈。
【传】十一年春，楚子伐郑，及栎。子良曰：「晋、楚不务德而兵争，与其来者可也。晋、楚无信，我焉得有信。」乃从楚。夏，楚盟于辰陵，陈、郑服也。
楚左尹子重侵宋，王待诸郔。令尹蒍艾猎城沂，使封人虑事，以授司徒。量功命日，分财用，平板干，称畚筑，程土物，议远迩，略基趾，具□粮，度有司，事三旬而成，不愆于素。
晋郤成子求成于众狄，众狄疾赤狄之役，遂服于晋。秋，会于欑函，众狄服也。是行也。诸大夫欲召狄。郤成子曰：「吾闻之，非德，莫如勤，非勤，何以求人？能勤有继，其从之也。《诗》曰：『文王既勤止。』文王犹勤，况寡德乎？」
冬，楚子为陈夏氏乱故，伐陈。谓陈人无动，将讨于少西氏。遂入陈，杀夏征舒，轘诸栗门，因县陈。陈侯在晋。
申叔时使于齐，反，覆命而退。王使让之曰：「夏征舒为不道，弑其君，寡人以诸侯讨而戮之，诸侯、县公皆庆寡人，女独不庆寡人，何故」对曰：「犹可辞乎？」王曰：「可哉」曰：夏征舒弑其君，其罪大矣，讨而戮之，君之义也。抑人亦有言曰：『牵牛以蹊人之田，而夺之牛。』牵牛以蹊者，信有罪矣；而夺之牛，罚已重矣。诸侯之从也，曰讨有罪也。今县陈，贪其富也。以讨召诸侯，而以贪归之，无乃不可乎？王曰：「善哉！」吾未之闻也。反之，可乎？对曰：「可哉！吾侪小人所谓取诸其怀而与之也。」乃复封陈，乡取一人焉以归，谓之夏州。故书曰：「楚子入陈，纳公孙宁、仪行父于陈。」书有礼也。
厉之役，郑伯逃归，自是楚未得志焉。郑既受盟于辰陵，又徼事于晋。
', '', '', '十一年春季，楚庄王发兵进攻郑国，到达栎地。子良说：“晋国、楚国不讲德行，而用武力争夺，谁来我们就接近他。晋国、楚国没有信用，我们哪里能够有信用？”于是就跟从楚国。夏季，楚国在辰陵会盟，这是由于陈、郑两国都顺服了。
楚国的左尹子重袭击宋国，楚庄王住在郔地等待。令尹蒍艾猎在沂地筑城，派遣主持人考虑工程计划，将情况报告给司徒。计量工程，规定日期，分配材料和用具，放平夹板和支柱，规定土方和器材劳力的多少，研究取材和工作的远近，巡视城基各处，准备粮食，审查监工的人选，工程三十天就完成，没有超过原定的计划。
晋国的郤成子向狄人各部族谋求友好。狄人各部族憎恨赤狄对他们的役使，于是顺服晋国。秋季，在欑函会见，狄人各部族都来顺服。在这次欑函之行以前，大夫们要召集狄人前来。郤成子说：“我听说，没有德行，就只能勤劳；没有勤劳，如何能要求别人服从我？能够勤劳，就有成果，还是到狄人那里去吧。《诗》说：‘文王已经做到勤劳。’文王尚且勤劳，何况缺少德行的人呢？”
冬季，楚庄王由于陈国夏氏作乱的缘故，进攻陈国。对陈国人说：“不要惊俱，我将要讨伐少西氏。”就进入陈国，杀了夏征舒，把他五马分尸在栗门。因而就把陈国设置为县。这时陈成公正在晋国。
申叔时在齐国出使，回国，向楚庄王复了命以后就退下去。楚庄王派人责备他说：“夏征舒无道，杀死他的国君。我带领诸侯讨伐而杀了他，诸侯、县公都庆贺我，你独独不庆贺我，什么缘故？”申叔时回答说：“还可以申述理由吗？”楚庄王说：“可以呀！”申叔时说：“夏征舒杀死他的国君，他的罪恶是是很大了；讨伐而杀了他，这是君王所应当做的事。不过人们也有话说：‘牵牛践踏别人的田地，就把他的牛夺过来。’牵牛践踏田地的人，肯定是有过错的了；但夺走他的牛，惩罚就太重了。诸侯跟从君王，说是讨伐有罪的人。现在把陈国设置为县，这就是贪图一国的富有。用伐罪号召诸侯，而以贪婪来告终，恐怕不可以吧？”楚庄王说：“好啊！我没有听说过这些话。归还陈国的土地，可以吗？”申叔时回答说：“这就是我们这一班小人所说的‘从怀里拿出来给他’呀。”楚庄王就重新封立陈国，从每个乡带一个人回楚国，集中住在一地，称为夏州。所以《春秋》记载说“楚子入陈，纳公孙宁、仪行父于陈”，这是表扬这一举动合于礼。
厉地这一战役，郑襄公逃走回国。从这时候以来，楚国就没有得志。郑国既然在辰陵接受盟约，又要求事奉晋国。
', NULL, '', 'indent', 1558953248, '5ceb4c9da673f5006815c53e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642994, '左传 · 宣公 · 宣公十二年 ', NULL, 0, 300, 0, 2, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有二年春，葬陈灵公。楚子围郑。夏六月乙卯，晋荀林父帅师及楚子战于邲，晋师败绩。秋七月。冬十有二月戊寅，楚子灭萧。晋人、宋人、卫人、曹人同盟于清丘。宋师伐陈。卫人救陈。
【传】十二年春，楚子围郑。旬有七日，郑人卜行成，不吉。卜临于大宫，且巷出车，吉。国人大临，守陴者皆哭。楚子退师，郑人修城，进复围之，三月克之。入自皇门，至于逵路。郑伯肉袒牵羊以逆，曰：「孤不天，不能事君，使君怀怒以及敝邑，孤之罪也。敢不唯命是听。其俘诸江南以实海滨，亦唯命。其剪以赐诸侯，使臣妾之，亦唯命。若惠顾前好，徼福于厉、宣、桓、武，不泯其社稷，使改事君，夷于九县，君之惠也，孤之愿之，非所敢望也。敢布腹心，君实图之。」左右曰：「不可许也，得国无赦。」王曰：「其君能下人，必能信用其民矣，庸可几乎？」退三十里而许之平。潘□入盟，子良出质。
夏六月，晋师救郑。荀林父将中军，先縠佐之。士会将上军，郤克佐之。赵朔将下军，栾书佐之。赵括、赵婴齐为中军大夫。巩朔、韩穿为上军大夫。荀首、赵同为下军大夫。韩厥为司马。及河，闻郑既及楚平，桓子欲还，曰：「无及于郑而剿民，焉用之？楚归而动，不后。」随武子曰：「善。会闻用师，观衅而动。德刑政事典礼不易，不可敌也，不为是征。楚军讨郑，怒其贰而哀其卑，叛而伐之，服而舍之，德刑成矣。伐叛，刑也；柔服，德也。二者立矣。昔岁入陈，今兹入郑，民不罢劳，君无怨讟，政有经矣。荆尸而举，商农工贾不败其业，而卒乘辑睦，事不奸矣。蒍敖为宰，择楚国之令典，军行，右辕，左追蓐，前茅虑无，中权，后劲，百官象物而动，军政不戒而备，能用典矣。其君之举也，内娃选于亲，外姓选于旧；举不失德，赏不失劳；老有加惠，旅有施舍；君子小人，物有服章，贵有常尊，贱有等威；礼不逆矣。德立，刑行，政成，事时，典从，礼顺，若之何敌之？见可而进，知难而退，军之善政也。兼弱攻昧，武之善经也。子姑整军而经武乎，犹有弱而昧者，何必楚？仲虺有言曰：『取乱侮亡。』兼弱也。《汋》曰：『于铄王师，遵养时晦。』耆昧也。《武》曰：『无竞惟烈。』抚弱耆昧以务烈所，可也。」彘子曰：「不可。晋所以霸，师武臣力也。今失诸侯，不可谓力。有敌而不从，不可谓武。由我失霸，不如死。且成师以出，闻敌强而退，非夫也。命为军师，而卒以非夫，唯群子能，我弗为也。」以中军佐济。
知庄子曰：「此师殆哉。《周易》有之，在《师》三之《临》三，曰：『师出以律，否臧凶。』执事顺成为臧，逆为否，众散为弱，川壅为泽，有律以如己也，故曰律。否臧，且律竭也。盈而以竭，夭且不整，所以凶也。不行谓之《临》，有帅而不从，临孰甚焉！此之谓矣。果遇，必败，彘子尸之。虽免而归，必有大咎。」韩献子谓桓子曰：「彘子以偏师陷，子罪大矣。子为元师，师不用命，谁之罪也？失属亡师，为罪已重，不如进也。事之不捷，恶有所分，与其专罪，六人同之，不犹愈乎？」师遂济。
楚子北师次于郔，沈尹将中军，子重将左，子反将右，将饮马于河而归。闻晋师既济，王欲还，嬖人伍参欲战。令尹孙叔敖弗欲，曰：「昔岁入陈，今兹入郑，不无事矣。战而不捷，参之肉其足食乎？」参曰：「若事之捷，孙叔为无谋矣。不捷，参之肉将在晋军，可得食乎？」令尹南辕反旆，伍参言于王曰：「晋之从政者新，未能行令。其佐先縠刚愎不仁，未肯用命。其三帅者专行不获，听而无上，众谁适从？此行也，晋师必败。且君而逃臣，若社稷何？」王病之，告令尹，改乘辕而北之，次于管以待之。
晋师在敖、鄗之间。郑皇戌使如晋师，曰：「郑之从楚，社稷之故也，未有贰心。楚师骤胜而骄，其师老矣，而不设备，子击之，郑师为承，楚师必败。」彘子曰：「败楚服郑，于此在矣，必许之。」栾武子曰：「楚自克庸以来，其君无日不讨国人而训之于民生之不易，祸至之无日，戒惧之不可以怠。在军，无日不讨军实而申儆之于胜之不可保，纣之百克，而卒无后。训以若敖、蚡冒，筚路蓝缕，以启山林。箴之曰：『民生在勤，勤则不匮。』不可谓骄。先大夫子犯有言曰：『师直为壮，曲为老。』我则不德，而徼怨于楚，我曲楚直，不可谓老。其君之戎，分为二广，广有一卒，卒偏之两。右广初驾，数及日中；左则受之，以至于昏。内官序当其夜，以待不虞，不可谓无备。子良，郑之良也。师叔，楚之崇也。师叔入盟，子良在楚，楚、郑亲矣。来劝我战，我克则来，不克遂往，以我卜也，郑不可从。」赵括、赵同曰：「率师以来，唯敌是求。克敌得属，又何矣？必从彘子。」知季曰：「原、屏，咎之徒也。」赵庄子曰：「栾伯善哉，实其言，必长晋国。」
楚少宰如晋师，曰：「寡君少遭闵凶，不能文。闻二先君之出入此行也，将郑是训定，岂敢求罪于晋。二三子无淹久。」随季对曰：「昔平王命我先君文侯曰：『与郑夹辅周室，毋废王命。』今郑不率，寡君使群臣问诸郑，岂敢辱候人？敢拜君命之辱。」彘子以为谄，使赵括从而更之，曰：「行人失辞。寡君使群臣迁大国之迹于郑，曰：『无辟敌。』群臣无所逃命。」
楚子又使求成于晋，晋人许之，盟有日矣。楚许伯御乐伯，摄叔为右，以致晋师，许伯曰：「吾闻致师者，御靡旌摩垒而还。」乐伯曰：「吾闻致师者，左射以菆，代御执辔，御下两马，掉鞅而还。」摄叔曰：「吾闻致师者，右入垒，折馘，执俘而还。」皆行其所闻而复。晋人逐之，左右角之。乐伯左射马而右射人，角不能进，矢一而已。麋兴于前，射麋丽龟。晋鲍癸当其后，使摄叔奉麋献焉，曰：「以岁之非时，献禽之未至，敢膳诸从者。」鲍癸止之，曰：「其左善射，其右有辞，君子也。」既免。
晋魏錡求公族未得，而怒，欲败晋师。请致师，弗许。请使，许之。遂往，请战而还。楚潘党逐之，及荧泽，见六麋，射一麋以顾献曰：「子有军事，兽人无乃不给于鲜，敢献于从者。」叔党命去之。赵旃求卿未得，且怒于失楚之致师者。请挑战，弗许。请召盟。许之。与魏錡皆命而往。郤献子曰：「二憾往矣，弗备必败。」彘子曰：「郑人劝战，弗敢从也。楚人求成，弗能好也。师无成命，多备何为。」士季曰：「备之善。若二子怒楚，楚人乘我，丧师无日矣。不如备之。楚之无恶，除备而盟，何损于好？若以恶来，有备不败。且虽诸侯相见，军卫不彻，警也。」彘子不可。
士季使巩朔、韩穿帅七覆于敖前，故上军不败。赵婴齐使其徒先具舟于河，故败而先济。
潘党既逐魏錡，赵旃夜至于楚军，席于军门之外，使其徒入之。楚子为乘广三十乘，分为左右。右广鸡鸣而驾，日中而说。左则受之，日入而说。许偃御右广，养由基为右。彭名御左广，屈荡为右。乙卯，王乘左广以逐赵旃。赵旃弃车而走林，屈荡搏之，得其甲裳。晋人惧二子之怒楚师也，使軘车逆之。潘党望其尘，使聘而告曰：「晋师至矣。」楚人亦惧王之入晋军也，遂出陈。孙叔曰：「进之。宁我薄人，无人薄我。《诗》云：『元戎十乘，以先启行。』先人也。《军志》曰：『先人有夺人之心』。薄之也。」遂疾进师，车驰卒奔，乘晋军。桓子不知所为，鼓于军中曰：「先济者有赏。」中军、下军争舟，舟中之指可掬也。
晋师右移，上军未动。工尹齐将右拒卒以逐下军。楚子使唐狡与蔡鸠居告唐惠侯曰：「不谷不德而贪，以遇大敌，不谷之罪也。然楚不克，君之羞也，敢藉君灵以济楚师。」使潘党率游阙四十乘，从唐侯以为左拒，以从上军。驹伯曰：「待诸乎？」随季曰：「楚师方壮，若萃于我，吾师必尽，不如收而去之。分谤生民，不亦可乎？」殿其卒而退，不败。
王见右广，将从之乘。屈荡尸之，曰：「君以此始，亦必以终。」自是楚之乘广先左。
晋人或以广队不能进，楚人惎之脱扃，少进，马还，又惎之拔旆投衡，乃出。顾曰：「吾不如大国之数奔也。」
赵旃以其良马二，济其兄与叔父，以他马反，遇敌不能去，弃车而走林。逢大夫与其二子乘，谓其二子无顾。顾曰：「赵叟在后。」怒之，使下，指木曰：「尸女于是。」授赵旃绥，以免。明日以表尸之，皆重获在木下。
楚熊负羁囚知荦。知庄子以其族反之，厨武子御，下军之士多从之。每射，抽矢，菆，纳诸厨子之房。厨子怒曰：「非子之求而蒲之爱，董泽之蒲，可胜既乎？」知季曰：「不以人子，吾子其可得乎？吾不可以苟射故也。」射连尹襄老，获之，遂载其尸。射公子谷臣，囚之。以二者还。
及昏，楚师军于邲，晋之馀师不能军，宵济，亦终夜有声。
丙辰，楚重至于邲，遂次于衡雍。潘党曰：「君盍筑武军，而收晋尸以为京观。臣闻克敌必示子孙，以无忘武功。」楚子曰：「非尔所知也。夫文，止戈为武。武王克商。作《颂》曰：『载戢干戈，载櫜弓矢。我求懿德，肆于时夏，允王保之。』又作《武》，其卒章曰『耆定尔功』。其三曰：『铺时绎思，我徂求定。』其六曰：『绥万邦，屡丰年。』夫武，禁暴、戢兵、保大、定功、安民、和众、丰财者也。故使子孙无忘其章。今我使二国暴骨，暴矣；观兵以威诸侯，兵不戢矣。暴而不戢，安能保大？犹有晋在，焉得定功？所违民欲犹多，民何安焉？无德而强争诸侯，何以和众？利人之几，而安人之乱，以为己荣，何以丰财？武有七德，我无一焉，何以示子孙？其为先君宫，告成事而已。武非吾功也。古者明王伐不敬，取其鲸鲵而封之，以为大戮，于是乎有京观，以惩淫慝。今罪无所，而民皆尽忠以死君命，又可以为京观乎？」祀于河，作先君宫，告成事而还。
是役也，郑石制实入楚师，将以分郑而立公子鱼臣。辛未，郑杀仆叔子服。君子曰：「史佚所谓毋怙乱者，谓是类也。《诗》曰：『乱离瘼矣，爰其适归？』归于怙乱者也夫。」
郑伯、许男如楚。
秋，晋师归，桓子请死，晋侯欲许之。士贞子谏曰：「不可。城濮之役，晋师三日谷，文公犹有忧色。左右曰：『有喜而忧，如有忧而喜乎？』公曰：『得臣犹在，忧未歇也。困兽犹斗，况国相乎！』及楚杀子玉，公喜而后可知也，曰：『莫馀毒也已。』是晋再克而楚再败也。楚是以再世不竞。今天或者大警晋也，而又杀林父以重楚胜，其无乃久不竞乎？林父之事君也，进思尽忠，退思补过，社稷之卫也，若之何杀之？夫其败也，如日月之食焉，何损于明？」晋侯使复其位。
冬，楚子伐萧，宋华椒以蔡人救萧。萧人囚熊相宜僚及公子丙。王曰：「勿杀，吾退。」萧人杀之。王怒，遂围萧。萧溃。申公巫臣曰：「师人多寒。」王巡三军，拊而勉之。三军之士，皆如挟纩。遂傅于萧。还无社与司马卯言，号申叔展。叔展曰：「有麦曲乎？」曰：「无」。「有山鞠穷乎？」曰：「无」。「河鱼腹疾奈何？」曰：「目于眢井而拯之。」「若为茅絰，哭井则己。」明日萧溃，申叔视其井，则茅絰存焉，号而出之。
晋原縠、宋华椒、卫孔达、曹人同盟于清丘。曰：「恤病讨贰。」于是卿不书，不实其言也。宋为盟故，伐陈。卫人救之。孔达曰：「先君有约言焉，若大国讨，我则死之。」
', '', '', '十二年春季，楚庄王包围郑国十七天。郑国人占卜以求和，不吉利；为在太庙号哭和出车于街巷去占卜，吉利。城里的人们在太庙大哭，守城的将士在城上大哭。楚庄王退兵。郑国人修筑城墙，楚国又进军，再次包围郑国，经三个月，攻克了郑国。楚军从皇门进入，到达京城的大路上。郑襄公脱去衣服，牵着羊迎接楚庄王，说：“我不能承奉天意，不能事奉君王，使君王带着怒气来到敝邑，这是我的罪过，岂敢不唯命是听？要把我俘虏到江南，放到海边，也听君王吩咐；要灭亡郑国，把郑地赐给诸侯，让郑国人作为奴隶，也听君王吩咐。如果承君王顾念从前的友好，向周厉王、宣王、郑桓公、武公求福，而不灭绝我国，让我国重新事奉君王，等同于楚国的诸县，这是君王的恩惠，我的心愿，但又不是我所敢于指望的了。谨坦露心里的话，请君王考虑。”左右随从说：“不能允许他，得到了国家没有赦免的。”楚庄王说：“他的国君能够屈居他人之下，必然能够取信和使用他的百姓，恐怕还是很有希望的吧！”楚军退兵三十里而允许郑国讲和。潘尪入郑国结盟，子良到楚国作为人质。
夏季，六月，晋国的军队去救郑国。荀林父率领中军，先縠为辅佐；士会率领上军，郤作辅佐；赵朔率领下军，栾书作为辅佐。赵括、赵婴齐担任中军大夫，巩朔、韩穿担任上军大夫，荀首、赵同担任下军大夫。韩厥担任司马。到达黄河，听到郑国已经和楚国讲和，荀林父想要回去，说：“没有赶到郑国，又劳动百姓，出兵有什么用？等楚军回去以后我军再出兵进攻郑国，还不算晚。”士会说：“好。会听说用兵之道，观察敌人的间隙而后行动，德行、刑罚、政令、事务、典则、礼仪合乎常道，就是不可抵挡的，不能进攻这样的国家。楚国的军队讨伐郑国，讨厌郑国有二心，又可怜郑国的卑下，郑国背叛就讨伐他，郑国顺服就赦免他，德行、刑罚都完成了。讨伐背叛，这是刑罚；安抚顺服，这是德行，这二者树立起来了。往年进入陈国，如今进入郑国，百姓并不感到疲劳，国君没有受到怨恨，政令就合于常道了，楚军摆成荆尸之阵而后发兵，井井有条，商贩、农民、工匠、店主都不废时失业，步兵车兵关系和睦，事务就互不相犯了。蒍敖做令尹，选择实行楚国好的法典，军队出动，右军跟随主将的车辕，左军打草作为歇息的准备，前军以旄旌开路以防意外，中军斟酌谋划，后军以精兵押阵。各级军官根据象征自己的旌旗的指示而采取行动，军事政务不必等待命令而完备，这就是能够运用典则了。他们国君选拔人材，同姓中选择亲近的支系，异姓中选择世代旧臣，提拔不遗漏有德行的人，赏赐不遣漏有功劳的人。对老人有优待，对旅客有赐予。君子和小人，各有规定的服饰。对尊贵的有一定的礼节示以尊重，对低贱的有一定的等级示以威严。这就是礼节没有不顺的了。德行树立，刑罚施行，政事成就，事务合时，典则执行，礼节顺当，怎么能抵挡楚国？看到可能就前进，遇到困难就后退，这是治军的好办法。兼并衰弱进攻昏暗，这是用兵的好规则。您姑且整顿军队、筹划武备吧！还有弱小而昏暗的国家，为什么一定要进攻楚军？仲虺说：‘占取动乱之国，欺侮可以灭亡之国。’说的就是兼并衰弱。《诗经•周倾•酌》篇说：‘天子的军队多么神气，率领他们把昏昧的国家占取。’说的就是进攻昏昧。《武》篇说：‘武王的功业无比伟大强盛。’安抚衰弱进攻昏暗，以致力于功业所在，这就可以了。”先縠说：“不行。晋国所以能称霸诸侯，是由于军队勇敢、臣下得力。现在失去了诸侯，不能说是得力；有了敌人不去追逐，不能说是勇敢。由于我们而丢掉霸主的地位，不如去死。而且晋国整顿军队不出动，听到敌人强大就退却，这不是大丈夫。任命为军队的统帅，而做出了不是大丈夫所做的事，这只有你们能办到，我是不会干的。”说完，就带领中军副帅所属军队渡过黄河。
荀首说：“先縠这些军队危险了。《周易》上有这样的卦象，从《师》卦变成《临》卦，爻辞说：‘出兵用法令治理，法令不严明，结果必凶。’执行顺当而成功就是‘臧’，反其道就是‘否’。大众离散是柔弱，流水壅塞就成为沼泽。有法制指挥三军如同指挥自己一样，所以叫做律。执行不顺当，法制治理就穷尽而无用。从充满到穷尽，阻塞而且不整齐，就是凶险的征兆了。不能流动叫做‘临’，有统帅而不服从，还有比这更严重的‘临’吗？说的就是先縠的这个行为了。果真和敌人相遇，一定失败，彘子将会是主要罪魁，即使免于战死而回国，一定有大的灾祸。”韩厥对荀林父说：“彘子率领一部分军队失陷，您的罪过大了。您作为最高统帅，军队不听命令，这是谁的罪过？失去属国，丢掉军队，构成的罪过已经太重，不如干脆进军。作战如果不能得胜，失败的罪过可以共分担，与其一个人承担罪责，六个人共同承担，不还好一点吗？”于是晋国的军队就渡过了黄河。
楚庄王率军北上，军队驻扎在郔地。沈尹率领中军，子重率领左军，子反率领右军，准备在黄河饮马以后就回国。听到晋国军队已经渡过黄河，楚庄王想要回去，宠臣伍参想打仗，令尹孙叔敖不想干，说：“往年进入陈国，今年进入郑国，不是没有战争。打起来以后不能得胜，吃了伍参的肉难道就够了吗？”伍参说：“如果作战得胜，孙叔就是没有谋略。不能得胜，参的肉将会在晋军那里，哪里还能吃得上呢？”令尹回车向南，倒转旌旗。伍参对楚庄王说：“晋国参政的是新人，不能行使命令。他的副手先縠刚愎不仁，不肯听从命令。他们的三个统帅，想要专权行事而不能办到。想要听从命令而没有上级，大军听从谁的命令？这一次，晋军一定失败。而且国君逃避臣下，国君怎能蒙受这耻辱？”楚庄王听了不高兴，告诉令尹把战车改而向北，楚军驻扎在管地等待晋军。
晋国军队驻在敖、鄗两山之间。郑国的皇戌出使到晋军中，说：“郑国跟从楚国，是为了保存国家的缘故，对晋国并没有二心。楚军屡次得胜而骄傲，他们在外面已经很久了，又不设防御。您攻击他们，郑国的军队作为后继，楚军一定失败。”先縠说：“打败楚军，降服郑国，就在此一举了，一定要答应皇戌的请求。”栾书说：“楚国自从战胜庸国以来，楚国的国君没有一天不用不列的方式治理国内的人们：教训百姓生计的不容易、祸患不知哪天就会到来、戒备警惕不能放松。在军队里，没有一天不用这样的方式管理军官士兵，告诫军队：胜利的不能永远保有、纣得到一百次胜利而终究没有好结果。用若敖、蚡冒乘柴车、穿破衣开辟山林的事迹来教训他们。告诫说：‘百姓的生计在于勤劳，勤劳就不会匮乏。’这就不能说他们骄傲。先大夫子犯说过：‘出兵作战，理直就气壮，理亏就气衰。’我们所做的事情不合于道德，又和楚国结怨，我们理曲，楚国理直，这就不能说他们气衰。他们国君的战车分为左右二广，每广有战车一卒三十辆，每卒又分左右两偏。右广先套车，计算时间等到中午，左广就接替它，一直到晚上。左右近臣按次序值夜，以防备发生意外，这就不能说没有防备。子良，是郑国的杰出人物；师叔，是楚国地位崇高的人物。师叔进入郑国结盟，子良作为人质住在楚国，楚国和郑国是亲近的。他们来劝我们作战，我们战胜就来归服，不胜就去依靠楚国，这是用我们作为占卜！郑国的话不能听从。”赵括、赵同说：“领兵而来，就是为了寻找敌人。战胜敌人，得到属国，又等待什么？一定要听从彘子的话。”荀首说：“赵同、赵括的主意，是一条自取祸乱之道。”赵庄子说：“栾伯好啊！实践他的话，一定能使晋国长久。”
楚国的少宰到晋军中去，说：“寡君年轻时就遭到忧患，不善于辞令。听到两位先君来往在这条道路上，就是打算教导和安定郑国，岂敢得罪晋国？您几位不要呆得太久了！”士会回答说：“以前周平王命令我们的先君晋文侯说：‘和郑国共同辅佐周王室，不要废弃天子的命令。’现在郑国不遵循天子的命令，寡君派遣下臣们质问郑国，岂敢劳动楚国官吏来迎送？恭敬地拜谢君王的命令。”先穀认为这是奉承楚国，派遣赵括跟上去更正说：“我们的临时代表的说法不恰当。寡君使臣下们把楚国从郑国迁出去，说：‘不要躲避敌人！’臣下们没有地方可以逃避命令。”
楚庄王又派使者向晋国求和，晋国人答应了，已约定了结盟的日期。楚国的许伯替乐伯驾御战车，摄叔作为车右，向晋军单车挑战。许伯说：“我听说单车挑战，驾车人疾驰而使旌旗斜倒，迫近敌营，然后回来。”乐伯说：“我听说单车挑战，车左用利箭射敌，代替御者执掌马缰，驾车人下车，整齐马匹，整理好马脖子上的皮带，然后回来。”摄叔说：“我听说单车挑战，车右进入敌营，杀死敌人割取左耳、抓住俘虏，然后回来。”这三个人都按照自己所听到的完成了任务，而后回来。晋国人追赶他们，左右两面夹攻。乐伯左边射马，右边射人，使晋军左右翼不能前进。箭只剩下一枝。有麋鹿出现在前面，乐伯射麋鹿正中背部。晋国的鲍癸正在后面，乐伯让摄叔拿着麋鹿献给他，说：“由于今年还不到时令，应当奉献的禽兽没有来，谨把它奉献给您的随从作为膳食。”鲍癸阻止部下，不再追赶，说：“他们的车左善于射箭，车右善于辞令，都是君子啊。”因此许伯等三人都免于被俘。
晋国的魏锜请求做公族大夫，没有达到目的，因而发怒，想要使晋军失败。请求单车挑战，没有得到允许。请求出使，允许了。于是就去到楚军中，请战以后而回国。楚国的潘党追赶他，到达荧泽，魏锜看到六只麋鹿，就射死一只，回车献给潘党，说：“您有军事在身，打猎的人恐怕不能供给新鲜的野兽吧？谨以此奉献给您的随从人员。”潘党下令不再追赶魏锜。赵旃请求做卿没有达到目的，而且对于失掉楚国单车挑战的人很生气，就请求挑战，没有得到允许。请求召请楚国人前来结盟，允许了。赵旃和魏锜都接受命令而前去。郤克说：“这两个心怀不满的人去了，不加防备，必然失败。”先縠说：“郑国人劝我们作战，不敢听从；楚国人求和，又不能实行友好。带兵没有固定的策略，多加防备做什么？”士会说：“防备他们为好。如果这两位激怒了楚国，楚国人乘机掩袭，马上可以丧失军队。不如防备他们，楚国人没有恶意，撤除戒备而结盟，哪里会损害友好？如果带着恶意而来，有了防备，不会失败。而且即使是诸侯相见，军队的守备也不加撤除，这就是警惕。”先縠不同意。
士会派遣巩朔、韩穿率领七队伏兵埋伏在敖山之前，所以上军不败。赵婴齐派遣他的部下先在黄河准备了船只，所以战败以后就渡过河去了。
潘党已经赶走了魏锜，赵旃在夜里达到楚军驻地，铺开席子坐在军门的外面，派遣他的部下先进军门。楚庄王的战车一广三十辆，共分为左右两广。右广在早晨鸡叫的时候套车，太阳到了中天才卸车；左广就接替右广，太阳落山才卸车。许偃驾御右广的指挥车，养由基作为车右；彭名驾御左广的指挥车，屈荡作为车右。六月十四日，楚庄王乘坐左广的指挥车，以追赶赵旃。赵旃丢掉车子跑进树林里，屈荡和他搏斗，获得了他的铠甲和下衣。晋国人害怕这两个人激怒楚军，让驻守的兵车前来接他们。潘党远望飞起来的尘土，派战车奔驰报告说：“晋国的军队来了。”楚国人也害怕楚庄王陷入晋军中，就出兵迎战。孙叔敖说：“前进！宁可我们迫近敌人，不要让敌人迫近我们。《诗》说：‘大兵车十辆，冲在前面开道’，这是要抢在敌人的前面。《军志》说：‘抢在敌人前面，可以夺去敌人的斗志。’这是要主动迫近敌人。”于是就很快地进军，战车奔驰、士卒奔跑，围攻晋军。荀林父不知所措，在军中击鼓宣布说：“先过河的有赏。”中军、下军互相争夺船只，争先恐后，先上船的人用刀砍断后来者攀着船舷的手指，船中砍断的指头多得可以用手捧起来。
晋军向右转移，上军没有动。工尹齐率领右方阵的士兵，以追逐晋国的下军。楚庄王派唐狡和蔡鸠居报告唐惠侯说：“我无德而贪功，而又遭遇强大的敌人，这是我的罪过。楚国如果不能得胜，这也是君王的羞耻。谨借重君王的福佑，以帮助楚军成功。”派遣潘党率领后备的战车四十辆，跟随唐侯作为左方阵，以迎战晋国的上军。驹伯说：“抵御他们吗？”士会说：“楚军的士气正旺盛，如果楚军集中兵力对付我们的上军，我们的军队必然被消灭，不如收兵离开。分担战败的指责，保全士兵的生命，不也是可以的吗？”就亲自作为上军的后殿而退兵，因此没有被打败。
楚庄王见到右广，准备乘坐。屈荡阻止说：“君王乘坐左广开始作战，也一定要乘坐它结束战争。”从此楚国的乘广改以左广为先。
晋国人有战车陷在坑里不能前进，楚国人教他们抽出车前横木，没走多远，马盘旋不能前进，楚国人又教他们拔掉大旗，扔掉车辕头上的横木，这样才逃了出去。晋军转过头来说：“我们可不像大国的人有多次逃跑的经验。”
赵旃用他的好马两匹帮助他的哥哥和叔父逃跑，而用其他的马驾车回来。碰上敌人不能逃脱，就丢弃车子跑到树林里。逢大夫和他两个儿子坐在车上，对他两个儿子说：“不要回头去望。”儿子回头去望说：“赵老头在后边。”逢大夫发怒，让他们下车，指着树木说：“在这里收你们的尸首。”逢大夫就把缰绳交给了赵旃，赵旃登上战车得以逃脱。第二天，按照标志前去收尸，在树下得到了两个叠压的尸首。
楚国的熊负羁囚禁了知罃，荀首率领他的部属回来战斗，魏锜驾御战车，下军的士兵大多跟着回来。荀首每次发射，抽箭，如果是利箭，就放在魏锜的箭袋里。魏锜发怒说：“不去寻找儿子，反而爱惜蒲柳，董泽的蒲柳，难道可以用得完吗？”荀首说：“不得到别人的儿子，我的儿子难道可以得到吗？利箭我是不能随便射出去的。”荀首射中了连尹襄老，得到他的尸首，就用战车装上；射中公子谷臣，把他囚禁起来。荀首带了这两个人回去。
到黄昏时，楚军驻扎在邲地，晋国剩余的士兵已经溃不成军，夜里渡河，喧吵了一整夜。
六月十五日，楚军的辎重到达邲地，军队就驻扎在衡雍。潘党说：“君王何不建筑起军营显示武功，收集晋国人的尸首建立一个大坟堆？下臣听说战胜了敌人一定要有纪念物给子孙看，表示不忘记武功。”楚庄王说：这不是你所知道的。说到文字，止戈二字合起来是个武字。武王战胜商朝，作《周颂》说：“收拾干戈，包藏弓箭。我追求那美德，陈于这《夏》乐之中，成就王业而保有天下。”又作《武》篇，它的最后一章说：“得以巩固你的功业。”《周颂》的第三章说：“布陈先王的美德而加以发扬，我前去征讨只是为了求得安定。”它的第六章说：“安定万邦，常有丰年。”武功，是用来禁止强暴、消灭战争、保持强大、巩固功业、安定百姓、调和大众、丰富财物的，所以要让子孙不要忘记他的大功。现在我让两国士兵暴露尸骨，这是强暴了；显耀武力以使诸侯畏惧，战争不能消灭了；强暴而不消灭战争，哪里能够保持强大？还有晋国存在，如何能够巩固功业？所违背百姓的愿望还很多，百姓如何能够安定？没有德行而勉强和诸侯相争，用什么调和大众？乘别人之危作为自己的利益，趁人之乱作为自己的安定，如何能丰富财物？武功具有七种美德，我对晋国用兵却没有一项美德，用什么来昭示子孙后代？还是为楚国的先君修建宗庙，把成功的事祭告先君罢了。用武不是我追求的功业。古代圣明的君王征伐对上不恭敬的国家，抓住它的罪魁祸首杀掉埋葬，作为一次大杀戮，这样才有了京观以惩戒罪恶。现在并不能明确指出晋国的罪恶在哪里，士卒都尽忠为执行国君的命令而死，又难道能建造京观来惩戒吗？楚庄王说完，就在黄河边上祭祀了河神，修建了先君的神庙，报告战争胜利，然后回国。
这次战役，是郑国的石制把楚国军队引进来的，企图分割郑国，并且立公子鱼臣为国君。七月二十九日，郑国人杀死了鱼臣和石制。君子说：“史佚所谓‘不要依仗动乱’，说的就是这一类人，《诗》说：‘动乱离散是那么厉害，有哪里可以归宿’？这是归罪于靠动乱来谋私利的人吧！”
郑襄公、许昭公去到楚国。
秋季，晋国军队回国，荀林父自己请求处以死罪，晋景公打算答应他。士贞子劝谏说：“不行，城濮那一次战役，晋军三天吃着楚军留下的粮食，文公还面带忧色。左右的人说：‘有了喜事而忧愁，如果有了忧事反倒喜悦吗？’文公说：‘得臣还在，忧愁还不能算完结。被困的野兽还要争斗一下，何况是一国的宰相呢？’等到楚国杀了得臣，文公便喜形于色，说：‘没有人来同我作对了。’这是晋国的再次胜利，也是楚国的再次失败，楚国由此两世都不能强盛。现在上天或者是要大大地警戒晋国，但又杀了荀林父以增加楚国的胜利，这恐怕会使晋国好久还不能强盛的吧？荀林父的事奉国君，进，想着竭尽忠诚，退，想着弥补过错，是捍卫国家的人，怎么能杀他？他的失败，如同日蚀月蚀，怎么会损害日月的光明？”晋景公就命令荀林父官复原位。
冬季，楚庄王攻打萧国。宋国华椒率领蔡军去救萧国。萧军囚禁了熊相宜僚和公子丙。楚庄王说：“不要杀，我退兵。”萧国人杀了他们。楚庄王发怒，就包围了萧国。萧国崩溃，申公巫臣说：“军队里的人大多很冷。”楚庄王巡视三军，安抚慰勉士兵们，三军的战士感到温暖，都好像披上了丝棉一样。军队就前进而逼近萧城。还无社告诉司马卯，把申叔展喊出来。申叔展说：“你有酒药吗？”还无社说：“没有。”“有川芎吗？”还无社说：“没有。”“得了风湿病怎么办？”还无社说：“注意看枯井就可以拯救我。”申叔展说：“你在井上放一条草绳子，有向井里哭的人就是我。”第二天，萧国崩溃。申叔展看到井上有草绳子在那里，就放声号哭，把还无社救出枯井。
晋国的原縠、宋国的华椒、卫国的孔达、曹国人在清丘结盟，说：“周济有困难的国家，讨伐三心二意的国家。”对这次盟会，《春秋》没有记载卿的姓名，这是由于没有实行盟约。宋国为了盟约的缘故，进攻陈国。卫军救援陈国，孔达说：“先君有约定，如果大国进攻我们，我愿意为此去死。”
', NULL, '', 'indent', 1559037806, '5cec96e530863b00683e4e77', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642995, '左传 · 宣公 · 宣公十三年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有三年春，齐师伐莒。夏，楚子伐宋。秋，螽。冬，晋杀其大夫先縠。
【传】十三年春，齐师伐莒，莒恃晋而不事齐故也。
夏，楚子伐宋，以其救萧也。君子曰：「清丘之盟，唯宋可以免焉。」
秋，赤狄伐晋，及清，先縠召之也。
冬，晋人讨邲之败，与清之师，归罪于先縠而杀之，尽灭其族。君子曰：「恶之来也，己则取之，其先縠之谓乎。」
清丘之盟，晋以卫之救陈也讨焉。使人弗去，曰：「罪无所归，将加而师。」孔达曰：「苟利社稷，请以我说。罪我之由。我则为政而亢大国之讨，将以谁任？我则死之。」
', '', '', '十三年春季，齐国军队进攻莒国，由于莒国依仗晋国而不奉事齐国的缘故。
夏季，楚庄王进攻宋国，因为宋国曾救援萧国。君子说：“清丘的结盟，只有宋国可以免去被讥议。”
秋季，赤狄进攻晋国，到达清地，这是先縠把他们召来的。
冬季，晋国人追究邲地失败和清地战争的责任，归罪于先穀而杀死了他，把他的族人也全部杀掉了。君子说“‘刑戮来到，那是自找’，先縠就是这样的吧？”
清丘的盟约，晋国由于卫国救援陈国，就加以责备。晋国使者不肯离去，说：“罪责如果无所归属，将要把战争加在你们头上。”孔达说：“如果有利于社稷，就请用我的死来作为解说吧，罪过由于我。我在执政，而面对大国的责备，这个罪责还能推给谁？我愿意为此而死。”
', NULL, '', 'indent', 1559037844, '5cec9711d5de2b007085399f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642996, '左传 · 宣公 · 宣公十四年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有四年春，卫杀其大夫孔达。夏五月壬申，曹伯寿卒。晋侯伐郑。秋九月，楚子围宋。葬曹文公。冬，公孙归父会齐侯于谷。
【传】十四年春，孔达缢而死。卫人以说于晋而免。遂告于诸侯曰：「寡君有不令之臣达，构我敝邑于大国，既伏其罪矣，敢告。」卫人以为成劳，复室其子，使复其位。
夏，晋侯伐郑，为邲故也。告于诸侯，搜焉而还。中行桓子之谋也。曰：「示之以整，使谋而来。」郑人惧，使子张代子良于楚。郑伯如楚，谋晋故也。郑以子良为有礼，故召之。
楚子使申舟聘于齐，曰：「无假道于宋。」亦使公子冯聘于晋，不假道于郑。申舟以孟诸之役恶宋，曰：「郑昭宋聋，晋使不害，我则必死。」王曰：「杀女，我伐之。」见犀而行。及宋，宋人止之，华元曰：「过我而不假道，鄙我也。鄙我，亡也。杀其使者必伐我，伐我亦亡也。亡一也。」乃杀之。楚子闻之，投袂而起，屦及于窒皇，剑及于寝门之外，车及于蒲胥之市。秋九月，楚子围宋。
冬，公孙归父会齐侯于谷。见晏桓子，与之言鲁乐。桓子告高宣子曰：「子家其亡乎，怀于鲁矣。怀必贪，贪必谋人。谋人，人亦谋己。一国谋之，何以不亡？」
孟献子言于公曰：「臣闻小国之免于大国也，聘而献物，于是有庭实旅百。朝而献功，于是有容貌采章嘉淑，而有加货。谋其不免也。诛而荐贿，则无及也。今楚在宋，君其图之。」公说。', '', '', '十四年春季，卫国的孔达上吊死了，卫国人以此向晋国解说而免于被讨伐。于是就通告诸侯说：“寡君有一个不好的臣子孔达，在敝邑和大国之间进行挑拨，已经伏罪了，谨此通告。”卫国人因为孔达过去有不少劳绩并辅助成公，便为他的儿子娶妻，而且让他的儿子接任了父亲的官位。
夏季，晋景公进攻郑国，这是为了邲地战役郑国帮助过楚国的缘故。通告诸侯，阅兵以后回国。这是中行桓子的计谋，他说：“给他们看到我军队伍严整，让他们自己谋划前来归服我们。”郑国害怕、派子张到楚国代替子良。郑襄公前去楚国，这是由于策划对付晋国的缘故。郑国认为子良合于礼，所以召他回国。
楚庄王派遣申舟到齐国聘问，说：“不要向宋国请求借路。”同时还派公子冯到晋国聘问，也不许公子冯向郑国请求借路。申舟由于孟诸这一役得罪了宋国，说：“郑国明白、宋国糊涂，去晋国的使者没有危险，我就必然会死。”楚庄王说：“要是杀死了你，我就攻打宋国。”申舟把儿子申犀引见给楚庄王然后出使。到达宋国，宋国人不让他走。华元说：“经过我国而不请求借路，这是把我国作为楚国边境内的县城。把我们当作县城，这是视我为被灭亡之国。杀了楚国的使者，楚国必然会进攻我国，进攻我国也不过是被灭亡。反正一样是灭亡。”就杀死了申舟。楚庄王听到申舟被杀的消息，一甩袖子就站起来，随从赶上去到前院才送上鞋子，追到寝宫门外才送上佩剑，追到蒲胥街市才让他坐上车子。秋季，九月，楚庄王进攻宋国。
冬季，公孙归父在穀地会见齐襄公、见到晏桓子，跟他谈到鲁国，很高兴。晏桓子告诉高宣子说：“归父恐怕会逃亡吧！他留恋鲁国。留恋必然贪婪，贪婪必然算计别人。算计别人，别人也算计他自己。一个国家里的人算计他，怎么会不逃亡？”
孟献子对鲁宣公说：“臣听说小国能免罪于大国，是去聘问又进献财物，因此就有庭中陈列的礼物上百件；去朝见并进献功劳，因此就有各色各样的装饰品，美好而且加之以额外礼物，这是为了谋求免除不能赦免的罪过。当大国加以责罚后再进奉财货，就来不及了。现在楚国正屯兵在宋国，君王应该考虑一下！”鲁宣公很高兴。', NULL, '', 'indent', 1559037884, '5cec9739ba39c800688ab42e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642997, '左传 · 宣公 · 宣公十五年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有五年春，公孙归父会楚子于宋。夏五月，宋人及楚人平。六月癸卯，晋师灭赤狄潞氏，以潞子婴儿归。秦人伐晋。王札子杀召伯、毛伯。秋，螽。仲孙蔑会齐高固于无娄。初，税亩。冬，蝝生。饥。
【传】十五年春，公孙归父会楚子于宋。
宋人使乐婴齐告急于晋。晋侯欲救之。伯宗曰：「不可。古人有言曰：『虽鞭之长，不及马腹。』天方授楚，未可与争。虽晋之强，能违天乎？谚曰：『高下在心。』川泽纳污，山薮藏疾，瑾瑜匿瑕，国君含垢，天之道也，君其待之。」乃止。使解扬如宋，使无降楚，曰：「晋师悉起，将至矣。」郑人囚而献诸楚，楚子厚赂之，使反其言，不许，三而许之。登诸楼车，使呼宋人而告之。遂致其君命。楚子将杀之，使与之言曰：「尔既许不谷而反之，何故？非我无信，女则弃之，速即尔刑。」对曰：「臣闻之，君能制命为义，臣能承命为信，信载义而行之为利。谋不失利，以卫社稷，民之主也。义无二信，信无二命。君之赂臣，不知命也。受命以出，有死无《员雨》，又可赂乎？臣之许君，以成命也。死而成命，臣之禄也。寡君有信臣，下臣获考死，又何求？」楚子舍之以归。
夏五月，楚师将去宋。申犀稽首于王之马前，曰：「毋畏知死而不敢废王命，王弃言焉。」王不能答。申叔时仆，曰：「筑室反耕者，宋必听命。」从之。宋人惧，使华元夜入楚师，登子反之床，起之曰：「寡君使元以病告，曰：『敝邑易子而食，析骸以爨。虽然，城下之盟，有以国毙，不能从也。去我三十里，唯命是听。』」子反惧，与之盟而告王。退三十里。宋及楚平，华元为质。盟曰：「我无尔诈，尔无我虞。」
潞子婴儿之夫人，晋景公之姊也。酆舒为政而杀之，又伤潞子之目。晋侯将伐之，诸大夫皆曰：「不可。酆舒有三俊才，不如待后之人。」伯宗曰：「必伐之。狄有五罪，俊才虽多，何补焉？不祀，一也。耆酒，二也。弃仲章而夺黎氏地，三也。虐我伯姬，四也。伤其君目，五也。怙其俊才，而不以茂德，兹益罪也。后之人或者将敬奉德义以事神人，而申固其命，若之何待之？不讨有罪，曰将待后，后有辞而讨焉，毋乃不可乎？夫恃才与众，亡之道也。商纣由之，故灭。天反时为灾，地反物为妖，民反德为乱，乱则妖灾生。故文反正为乏。尽在狄矣。」晋侯从之。六月癸卯，晋荀林父败赤狄于曲梁。辛亥，灭潞。酆舒奔卫，卫人归诸晋，晋人杀之。
王孙苏与召氏、毛氏争政，使王子捷杀召戴公及毛伯卫。卒立召襄。
秋七月，秦桓公伐晋，次于辅氏。壬午，晋侯治兵于稷以略狄土，立黎侯而还。及洛，魏颗败秦师于辅氏。获杜回，秦之力人也。
初，魏武子有嬖妾，无子。武子疾，命颗曰：「必嫁是。」疾病，则曰：「必以为殉。」及卒，颗嫁之，曰：「疾病则乱，吾从其治也。」及辅氏之役，颗见老人结草以亢杜回，杜回踬而颠，故获之。夜梦之曰：「余，而所嫁妇人之父也。尔用先人之治命，余是以报。」
晋侯赏桓子狄臣千室，亦赏士伯以瓜衍之县。曰：「吾获狄土，子之功也。微子，吾丧伯氏矣。」羊舌职说是赏也，曰：「《周书》所谓『庸庸祗祗』者，谓此物也夫。士伯庸中行伯，君信之，亦庸士伯，此之谓明德矣。文王所以造周，不是过也。故《诗》曰：『陈锡哉周。』能施也。率是道也，其何不济？」
晋侯使赵同献狄俘于周，不敬。刘康公曰：「不及十年，原叔必有大咎，天夺之魄矣。」
初税亩，非礼也。谷出不过藉，以丰财也。
冬，蝝生，饥。幸之也。', '', '', '十五年春季，鲁国的公孙归父在宋国会见楚庄王。
宋国人派乐婴齐到晋国报告急难，晋景公想要救援宋国。伯宗说：“不行。古人有话说：‘鞭子虽然长，达不到马肚子。’上天正在保佑楚国，不能和他竞争。晋国虽然强盛，能够违背上天吗？俗话说：‘高高下下，都在心里。’河流湖泊里容纳污泥浊水，山林草野里暗藏毒虫猛兽，美玉也藏匿着斑痕，国君也得忍受点耻辱，这是上天的常道。君王还是等着吧！”于是，晋景公就停止发兵救宋，派遣解扬到宋国去，让宋国不要投降楚国，解扬对宋国说：“晋国的军队都已经出发，将要到达了。”解扬路过郑国时，郑国人把他囚禁起来献给楚国。楚庄王重重地贿赂他，让他把话反过来说。解扬不答应。经过三次劝说以后才答应了。楚国人让解扬登上楼车，向宋国人喊话，而将楚国人要说的话告诉他们。解扬就乘机传达晋君的命令。楚庄王准备杀死他，派人对他说：“你既已答应了我，现在又反过来，是什么缘故？不是我没有信用，而是你丢失了它。快去受你的刑罚吧！”解扬回答说：“臣听说，国君能制订命令就是道义，臣下能接受命令就是信用，信用贯彻了道义然后去做就是利益。谋划不失去利益，以保卫国家，才是百姓的主人。道义不能有两种信用，信用不能接受两种命令。君王的贿赂下臣，就是不懂得命令的意义。接受了国君的命令而出国，宁可一死而不能废弃命令，难道又可以贿赂的吗？下臣所以答应您，那是为了借机会完成国君的使命。死而能完成使命，这是下臣的福气。寡君有守信的下臣，下臣死得其所，又有什么可以追求的？”楚庄王赦免了解扬放他回去。
夏季，五月，楚军准备离开宋国，申犀在楚庄王马前叩头说：“无畏知道死而不敢废弃君王的命令，君王丢掉自己的话了。”楚庄王不能回答。申叔时正为楚庄王驾车，说：“造起房子，让种田的人回来，宋国必然听从命令。”楚庄王听从了。宋国人害怕，派华元在夜里进入楚军营，登上子反的床，叫他起来，说：“寡君派元把困难情况告诉你，说：‘敝邑交换着儿子杀了吃掉，把尸骨拆开来烧着做饭。尽管如此，无条件投降，宁可让国家灭亡，也是不能这样做的。你们退兵三十里，宋国将唯命是听。’”子反害怕，就和华元私自订盟誓然后报告楚庄王。楚军退兵三十里，宋国和楚国讲和。华元作为人质。盟誓说：“我不骗你，你不欺我。”
潞子婴儿的夫人，是晋景公的姐姐。鄷舒执政以后杀了她，又伤了潞子的眼睛。晋景公准备进攻他。大夫们都说：“不行。鄷舒有三项显著的才能，不如等待他的后任。”伯宗说：“一定要进攻他。狄人有五条罪状，突出的才能虽然多，有什么补益？不祭祀，这是一。喜欢喝酒，这是二。废弃仲章而夺取黎氏的土地，这是三。杀害我们伯姬，这是四。伤了他国君的眼睛，这是五。依仗他自己的显著才能，而不用美德，这就更增加了罪过。继任的人或者将会敬奉德义以奉事神明，而巩固国家的命运，到时又怎么对待他？不进攻有罪的人，说‘将等待后继人’，以后有了理由再去进攻，恐怕不可以吧！依仗才能和人多，这是亡国之道。商纣按这样去做，所以被灭亡。天违反时令就是灾难，地违反物性就是妖异，百姓违反道德就是祸乱。有了祸乱就有妖异和灾祸发生。所以在文字上，正字反过来就是乏字。上面这些反常的事在狄人那里都是存在的。”晋景公听从了。六月十八日，晋国荀林父在曲梁打败赤狄。二十六日，灭潞国。鄷舒逃亡到卫国，卫国人把他送还到晋国，晋国人杀死了他。
王孙苏与召氏、毛氏争夺政权，指使王子捷杀死了召戴公和毛伯卫，最后立了召襄为执政卿士。
秋季，七月，秦桓公进攻晋国，驻扎在辅氏。二十七日，晋景公在稷地进行武装演习，来占领狄人的土地，立了黎侯然后回来。到达洛水，魏颗在辅氏击败秦军，俘获了杜回这个秦国的大力士。
当初，魏武子有一个爱妾，没有生儿子。魏武子生病，分咐魏颗说：“等我死去以后，一定要嫁了她”病危时，又说：“一定要让她殉葬！”等到魏武子死后，魏颗把她嫁了，说：“病重了就神志不清，我听从他清醒时候的话。”等到辅氏这一役，魏颗看到一个老人把草打成结来遮拦杜回。杜回绊倒在地，所以俘虏了他。夜里梦见老人说：“我，是你所嫁女人的父亲。你执行你先人清醒时候的话，我以此作为报答。”
晋景公赏给桓子狄国的臣民一千家，也把瓜衍的县城赏给士伯，说：“我得到狄国的土地，是您的功劳。如果没有您，我就丧失伯氏了。”羊舌职对这些赏赐感到高兴，说：“《周书》所谓‘能用可用的、能敬可敬的’，说的就是这一类吧。士伯认为中行伯为可以任用，国君相信他，就任用他，这就叫做明德了。文王所以能创立周朝，也不超过这些了。所以《诗》说‘把利益布施给天下，创立了周朝’，这是说文王能够施恩于百姓。遵循这个道理去做，还有什么不能成功的？”
晋景公派遣赵同到成周进献俘虏的狄人，表现得不恭敬。刘康公说：“不到十年，原叔一定有大灾难。上天已经夺走了他的魂魄了。”
鲁国开始按田亩征税，这是不合于礼的。过去的征税方法是所征的稻谷不超过“藉”的规定，这是用以增加财货的办法。
冬季，蝗的幼虫蜉化，造成饥荒。《春秋》所以记载这件事，是由于庆幸没有造成严重灾害。', NULL, '', 'indent', 1559037929, '5cec9765a673f50068219ce5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642998, '左传 · 宣公 · 宣公十六年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有六年春王正月。晋人灭赤狄甲氏及留吁。夏，成周宣榭火。秋，郯伯姬来归。冬，大有年。
【传】十六年春，晋士会帅师灭赤狄甲氏及留吁、铎辰。
三月，献狄俘。晋侯请于王。戊申，以黻冕命士会将中军，且为大傅。于是晋国之盗逃奔于秦。羊舌职曰：「吾闻之，『禹称善人，不善人远』，此之谓也夫。《诗》曰：『战战兢兢，如临深渊，如履薄冰。』善人在上也。善人在上，则国无幸民。谚曰：『民之多幸，国之不幸也。』是无善人之谓也。」
夏，成周宣榭火，人火之也。凡火，人火曰火，天火曰灾。
秋，郯伯姬来归，出也。
为毛、召之难故，王室复乱。王孙苏奔晋，晋人复之。
冬，晋侯使士会平王室，定王享之，原襄公相礼，殽烝。武子私问其故。王闻之，召武子曰：「季氏，而弗闻乎？王享有体荐，宴有折俎。公当享，卿当宴，王室之礼也。」武子归而讲求典礼，以修晋国之法。
', '', '', '十六年春季，晋国的士会率领军队灭亡了赤狄的甲氏和留吁、铎辰。
三月，晋国向周定王进献俘虏的狄人。晋景公向周定王请求，二十七日，把礼服赐给士会命令他率领中军，并且担任太傅。在这种情况下，晋国的盗贼逃奔到秦国。羊舌职说：“我听说，‘禹提拔好人，不好的人因此远离’，说的就是这样的事情吧！《诗》说，‘战战兢兢，如同面临深渊，如同踩着薄冰’，这是因为有好人在上面执政。有好人在上面，国家中就没有心存侥幸的百姓。俗话说，‘百姓多存侥幸，就是国家不幸’，这就是没有好人在位的说法。”
夏季，成周的宣榭失火，这是由于人放火烧着的。凡是失火，人为的火叫做火。天降的火叫做灾。
秋季，郯伯姬回来，这是由于被遗弃送回娘家。
由于毛氏、召氏祸难的缘故，周王室又发生动乱，王孙苏逃亡到晋国。晋国人让他重新恢复了卿士。
冬季，晋景公派遣士会调解王室的纠纷，周定王设享礼招待他。周大夫原襄公主持典礼，把切开的带骨的肉放在盛肉的器具里。士会暗中问这是什么缘故。周定王听到，召见士会说：“季氏，你没有听说过吗？天子设享礼有摆而不食的‘体荐’，设宴礼有把肉切成块的‘折俎’。诸侯应当设享礼招待，卿、大夫应当设宴会招待。这是王室的礼节。”士会回国以后就讲求典礼，以修明晋国的法度。', NULL, '', 'indent', 1559037966, '5cec978bd5de2b0070853e92', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (642999, '左传 · 宣公 · 宣公十七年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有七年春王正月庚子，许男锡我卒。丁未，蔡侯申卒。夏，葬许昭公。葬蔡文公。六月癸卯，日有食之。己未，公会晋侯、卫侯、曹伯、邾子同盟于断道。秋，公至自会。冬十有一月壬午，公弟叔肸卒。
【传】十七年春，晋侯使郤克征会于齐。齐顷公帷妇人，使观之。郤子登，妇人笑于房。献子怒，出而誓曰：「所不此报，无能涉河。」献子先归，使栾京庐待命于齐，曰：「不得齐事，无覆命矣。」郤子至，请伐齐，晋侯弗许。请以其私属，又弗许。
齐侯使高固、晏弱、蔡朝、南郭偃会。及敛孟，高固逃归。夏，会于断道，讨贰也。盟于卷楚，辞齐人。晋人执晏弱于野王，执蔡朝于原，执南郭偃于温。苗贲皇使，见晏桓子，归言于晋侯曰：「夫晏子何罪？昔者诸侯事吾先君，皆如不逮，举言群臣不信，诸侯皆有贰志。齐君恐不得礼，故不出，而使四子来。左右或沮之，曰：『君不出，必执吾使。』故高子及敛盂而逃。夫三子者曰：『若绝君好，宁归死焉。』为是犯难而来，吾若善逆彼以怀来者。吾又执之，以信齐沮，吾不既过矣乎？过而不改，而又久之，以成其悔，何利之有焉？使反者得辞，而害来者，以惧诸侯，将焉用之？」晋人缓之，逸。
秋八月，晋师还。
范武子将老，召文子曰：「燮乎！吾闻之，喜怒以类者鲜，易者实多。《诗》曰：『君子如怒，乱庶遄沮；君子如祉，乱庶遄已。』君子之喜怒，以已乱也。弗已者，必益之。郤子其或者欲已乱于齐乎？不然，余惧其益之也。余将老，使郤子逞其志，庶有豸乎？尔从二三子唯敬。」乃请老，郤献子为政。
冬，公弟叔肸卒。公母弟也。凡大子之母弟，公在曰公子，不在曰弟。凡称弟，皆母弟也。
', '', '', '十七年春季，晋景公派遣郤克到齐国征召齐顷公参加盟会。齐顷公用帷幕遮住妇人让她观看。郤克登上台阶，那妇人在房里笑起来。郤克生气，出来发誓说：“不报复这次耻辱，就不能渡过黄河！”郤克先回国，让栾京庐在齐国等候命令，说：“不能完成在齐国的使命，就不要回国复命。”郤克到达晋国，请求进攻齐国，晋景公不答应，请求带领家族去进攻齐国，晋景公也不答应。
齐顷公派遣高固、晏弱、蔡朝、南郭偃参加会盟。到达敛盂，高固逃回来。夏季，在断道会盟，这是为了讨伐有二心的国家。又在卷楚结盟，拒绝齐国人参加。晋国人在野王逮捕了晏弱，在原地逮捕了蔡朝，在温地逮捕了南郭偃。苗贲皇出使路过，见到晏弱。回去，对晋景公说：“晏子有什么罪？从前诸侯奉事我们的先君，都急得像赶不上的样子，都说是因为晋国君臣不讲信用，所以诸侯都有二心。齐国的国君恐怕不能得到礼遇，所以不出国而派这四个人来。齐顷公左右的随从有人阻止，说：‘您不出国，一定会抓住我国的使者。’所以高子到达敛盂就逃走了。这三个人说：‘如果因为我们断绝了国君的友好，宁可回国被处死。’为此他们甘冒危险而来。我们应该好好迎接他们，以使前来的人对我们怀念，但是我们偏偏逮捕了他们，以证明齐国人的劝阻是对的，我们不是已经做错了吗？做错了而不加以改正，而又久久不肯释放，以造成他们的后悔，这有什么好处？让回去的人有了逃走的理由，而伤害前来的人，以使诸侯害怕，这有什么用？”于是晋国人放松了看管，齐国的三名使者就逃走了。
秋季，八月，晋军回国。
范武子打算告老还乡，把儿子范文子喊过来，说：“燮儿啊！我听说，喜怒合于礼法的是很少的，和它相反的倒是很多。《诗》说：‘君子如果发怒，祸乱或许可以很快阻住。君子如果喜悦，祸乱或许可以很快停歇。’君子的喜怒是用来阻止祸乱的。如果不是阻止，就一定会增加祸乱。郤子或者是想要在齐国阻止祸乱吧。如果不是这样，我怕他会增加祸乱呢！我打算告老还乡了，让郤子能够心满意足，祸乱或许可以解除。你跟随几位大夫，唯有恭敬从事。”于是就请求告老。郤克执政。
冬季，鲁宣公的弟弟叔肸死，他是宣公的同母兄弟。凡是太子的同母兄弟，国君在世叫做公子，不在世叫做弟。凡称为弟的，都是同母兄弟。
', NULL, '', 'indent', 1559038003, '5cec97b043e78c0067204d8e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643000, '左传 · 宣公 · 宣公十八年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有八年春，晋侯、卫世子臧伐齐。公伐杞。夏四月。秋七月，邾人伐鄫子于鄫。甲戌，楚子旅卒。公孙归父如晋。冬十月壬戌，公薨于路寝。归父还自晋，至笙。遂奔齐，
【传】十八年春，晋侯、卫大子臧伐齐，至于阳谷。齐侯会晋侯盟于缯，以公子强为质于晋。晋师还，蔡朝、南郭偃逃归。
夏，公使如楚乞师，欲以伐齐。
秋，邾人戕鄫子于鄫。凡自虐其君曰弑，自外曰戕。
楚庄王卒。楚师不出，既而用晋师，楚于是乎有蜀之役。
公孙归父以襄仲之立公也，有宠，欲去三桓以张公室。与公谋而聘于晋，欲以晋人去之。冬，公薨。季文子言于朝曰：「使我杀适立庶以失大援者，仲也夫。」臧宣叔怒曰：「当其时不能治也，后之人何罪？子欲去之，许请去之。」遂逐东门氏。子家还，及笙，坛帷，覆命于介。既覆命，袒、括发，即位哭，三踊而出。遂奔齐。书曰「归父还自晋。」善之也。', '', '', '十八年春季，晋景公、卫国的太子臧共同发兵进攻齐国，到达阳穀，齐顷公与晋景公在缯地会见订立盟约，齐国派公子彊在晋国作为人质。晋军回国。蔡朝、南郭偃逃回国内。
夏季，鲁宣公的使者到楚国请求出兵，想要进攻齐国。
秋季，邾国人在鄫国戕杀鄫子。凡从国内杀死他们国君叫做“弑”，从国外来人杀的叫做“戕”。
楚庄王去世，楚军不能出兵。不久鲁国就利用晋军攻打齐国，楚国因此而有蜀地的战役。
公孙归父由于他父亲襄仲立了鲁宣公，而受到宣公宠信，他想要去掉孟孙、叔孙、季孙这“三桓”，以伸张公室的权力。他和宣公策划以后就到晋国去聘问，想要用晋国人的力量来去掉三桓。冬季，宣公逝世。季文子在朝廷上说：“让我杀死嫡子立了庶子以失掉强大的援助的，就是襄仲啊！”臧宣叔发怒说：“当时不能治罪，他的后人有什么罪？您要去掉他，许就请求去掉他。”于是就把襄仲的家族东门氏驱逐出国。
公孙归父回国，到达笙地，用帷幕遮住土坛，向他的副手举行复命的礼节。复命完了，脱去外衣，以麻束发，回到自己的位置痛哭，顿脚三次退出。于是就逃亡到齐国。《春秋》记载说“归父还自晋”，是对他表示赞许。', NULL, '', 'indent', 1559038041, '5cec97d6d5de2b00708540ba', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643001, '左传 · 成公 · 成公元年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】元年春王正月，公即位。二月辛酉，葬我君宣公。无冰。三月，作丘甲。夏，臧孙许及晋侯盟于赤棘。秋，王师败绩于茅戎。冬十月。
【传】元年春，晋侯使瑕嘉平戎于王，单襄公如晋拜成。刘康公徼戎，将遂伐之。叔服曰：「背盟而欺大国，此必败。背盟，不祥；欺大国，不义；神人弗助，将何以胜？」不听，遂伐茅戎。三月癸未，败绩于徐吾氏。
为齐难故，作丘甲。
闻齐将出楚师，夏，盟于赤棘。
秋，王人来告败。
冬，臧宣叔令修赋、缮完、具守备，曰：「齐、楚结好，我新与晋盟，晋、楚争盟，齐师必至。虽晋人伐齐，楚必救之，是齐、楚同我也。知难而有备，乃可以逞。」
', '', '', '元年春季，晋景公派遣瑕嘉调解周天子和戎人的冲突，单襄公到晋国拜谢调解成功。刘康公对戎人心存侥幸，打算乘此进攻他们。叔服说：“背弃盟约而又欺骗大国，这一定失败。背弃盟约就是不吉祥，欺骗大国就是不义，神明、百姓都不会帮助，将要如何去取胜利？”刘康公没有听从，于是就进攻茅戎。三月十九日，在徐吾氏地方被打得大败。
鲁国为了防备齐国入侵，定出“丘甲”的制度。
鲁国听说齐国将要率同楚军前来进攻，夏季，（臧孙许和晋景公）在赤棘结盟。
秋季，周定王的使者来鲁国报告战败。
冬季，臧宣叔命令整顿军赋、修治城郭，完成防御设施，说：“齐国和楚国结成友好，我国最近和晋国订了盟约。晋国和楚国争夺盟主，齐国的军队一定会来攻打我国。虽然晋国进攻齐国，楚国必然去救它，这就是齐、楚两国一起与我为敌。预计到祸难而有所防备，祸难就得以解除。”', NULL, '', 'indent', 1559038080, '5cec97fdd5de2b00708541ed', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643002, '左传 · 成公 · 成公二年', NULL, 3, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二年春，齐侯伐我北鄙。
夏四月丙戌，卫孙良夫帅师及齐师战于新筑，卫师败绩。
六月癸酉，季孙行父、臧孙许、叔孙侨如、公孙婴齐帅师会晋郤克、卫孙良夫、曹公子首及齐侯战于鞌，齐师败绩。
秋七月，齐侯使国佐如师。
己酉，及国佐盟于袁娄。
八月壬午，宋公鲍卒。
庚寅，卫侯速卒。
取汶阳田。
冬，楚师、郑师侵卫。
十有一月，公会楚公子婴齐于蜀。
丙申，公及楚人、秦人、宋人、陈人、卫人、郑人、齐人、曹人、邾人、薛人、鄫人盟于蜀。
【传】二年春，齐侯伐我北鄙，围龙。顷公之嬖人卢蒲就魁门焉，龙人囚之。齐侯曰：“勿杀！吾与而盟，无入而封。”弗听，杀而膊诸城上。齐侯亲鼓士陵城，三日，取龙，遂南侵及巢丘。
卫侯使孙良夫、石稷、甯相、向禽将侵齐，与齐师遇。石子欲还，孙子曰：“不可。以师伐人，遇其师而还，将谓君何？若知不能，则如无出。今既遇矣，不如战也。”
夏有石成子曰：“师败矣。子不少须，众惧尽。子丧师徒，何以复命？”皆不对。又曰：“子，国卿也。陨子，辱矣。子以众退，我此乃止。”且告车来甚众。齐师乃止，次于鞫居。
新筑人仲叔于奚救孙桓子，桓子是以免。既，卫人赏之以邑，辞。请曲县、繁缨以朝，许之。仲尼闻之曰：“惜也，不如多与之邑。唯器与名，不可以假人，君之所司也。名以出信，信以守器，器以藏礼，礼以行义，义以生利，利以平民，政之大节也。若以假人，与人政也。政亡，则国家从之，弗可止也已。”
孙桓子还于新筑，不入，遂如晋乞师。臧宣叔亦如晋乞师。皆主郤献子。
晋侯许之七百乘。郤子曰：“此城濮之赋也。有先君之明与先大夫之肃，故捷。克于先大夫，无能为役。”请八百乘，许之。郤克将中军，士燮佐上军，栾书将下军，韩厥为司马，以救鲁、卫。臧宣叔逆晋师，且道之。季文子帅师会之。及卫地，韩献子将斩人，郤献子驰，将救之，至则既斩之矣。郤子使速以徇，告其仆曰：“吾以分谤也。”
师从齐师于莘。六月壬申，师至于靡笄之下。齐侯使请战，曰：“子以君师，辱于敝邑，不腆敝赋，诘朝请见。”对曰：“晋与鲁、卫，兄弟也。来告曰：‘大国朝夕释憾于敝邑之地。’寡君不忍，使群臣请于大国，无令舆师淹于君地。能进不能退，君无所辱命。”齐侯曰：“大夫之许，寡人之愿也；若其不许，亦将见也。”齐高固入晋师，桀石以投人，禽之而乘其车，系桑本焉以徇齐垒，曰：“欲勇者贾余馀勇。”
癸酉，师陈于鞌。邴夏御齐侯，逢丑父为右。晋解张御郤克，郑丘缓为右。齐侯曰：“余姑翦灭此而朝食。”不介马而驰之。郤克伤于矢，流血及屦，未绝鼓音，曰：“余病矣！”张侯曰：“自始合，而矢贯余手及肘，余折以御，左轮朱殷，岂敢言病。吾子忍之！”缓曰：“自始合，苟有险，余必下推车，子岂识之？然子病矣！”张侯曰：“师之耳目，在吾旗鼓，进退从之。此车一人殿之，可以集事，若之何其以病败君之大事也？擐甲执兵，固即死也。病未及死，吾子勉之！”左并辔，右援枹而鼓，马逸不能止，师从之。齐师败绩。逐之，三周华不注。
韩厥梦子舆谓己曰：“旦辟左右。”故中御而从齐侯。邴夏曰：“射其御者，君子也。”公曰：“谓之君子而射之，非礼也。”射其左，越于车下。射其右，毙于车中。綦毋张丧车，从韩厥，曰：“请寓乘从左右。”皆肘之，使立于后。韩厥俛，定其右。逢丑父与公易位。将及华泉，骖絓于木而止。丑父寝于轏中，蛇出于其下，以肱击之，伤而匿之，故不能推车而及。韩厥执絷马前，再拜稽首，奉觞加璧以进，曰：“寡君使群臣为鲁、卫请曰：‘无令舆师陷入君地。’下臣不幸，属当戎行，无所逃隐。且惧奔辟而忝两君，臣辱戎士，敢告不敏，摄官承乏。”丑父使公下，如华泉取饮。郑周父御佐车，宛茷为右，载齐侯以免。韩厥献丑父，郤献子将戮之。呼曰：“自今无有代其君任患者，有一于此，将为戮乎！”郤子曰：“人不难以死免其君，我戮之不祥，赦之以劝事君者。”乃免之。
齐侯免，求丑父，三入三出。每出，齐师以帅退，入于狄卒。狄卒皆抽戈楯冒之，以入于卫师。卫师免之。遂自徐关入。齐侯见保者，曰：“勉之！齐师败矣。”辟女子，女子曰：“君免乎？”曰：“免矣。”曰：“锐司徒免乎？”曰：“免矣。”曰：“苟君与吾父免矣，可若何！”乃奔。齐侯以为有礼，既而问之，辟司徒之妻也。予之石窌。
晋师从齐师，入自丘舆，击马陉。齐侯使宾媚人赂以纪甗、玉磬与地。不可，则听客之所为。宾媚人致赂，晋人不可，曰：“必以萧同叔子为质，而使齐之封内尽东其亩。”对曰：“萧同叔子非他，寡君之母也。若以匹敌，则亦晋君之母也。吾子布大命于诸侯，而曰：‘必质其母以为信。’其若王命何？且是以不孝令也。《诗》曰：‘孝子不匮，永锡尔类。’若以不孝令于诸侯，其无乃非德类也乎？先王疆理天下物土之宜，而布其利，故《诗》曰：‘我疆我理，南东其亩。’今吾子疆理诸侯，而曰‘尽东其亩’而已，唯吾子戎车是利，无顾土宜，其无乃非先王之命也乎？反先王则不义，何以为盟主？其晋实有阙。四王之王也，树德而济同欲焉。五伯之霸也，勤而抚之，以役王命。今吾子求合诸侯，以逞无疆之欲。《诗》曰：‘布政优优，百禄是遒。’子实不优，而弃百禄，诸侯何害焉！不然，寡君之命使臣则有辞矣，曰：‘子以君师，辱于敝邑，不腆敝赋，以犒从者。畏君之震，师徒桡败。吾子惠徼齐国之福，不泯其社稷，使继旧好，唯是先君之敝器、土地不敢爱。子又不许。请收合馀烬，背城借一。敝邑之幸，亦云从也。况其不幸，敢不唯命是听。’”鲁、卫谏曰：“齐疾我矣！其死亡者，皆亲暱也。子若不许，仇我必甚。唯子则又何求？子得其国宝，我亦得地，而纾于难，其荣多矣！齐、晋亦唯天所授，岂必晋？”晋人许之，对曰：“群臣帅赋舆以为鲁、卫请，若苟有以藉口而复于寡君，君之惠也。敢不唯命是听。”
禽郑自师逆公。
秋七月，晋师及齐国佐盟于爰娄，使齐人归我汶阳之田。公会晋师于上鄍，赐三帅先路三命之服，司马、司空、舆帅、候正、亚旅，皆受一命之服。
八月，宋文公卒。始厚葬，用蜃炭，益车马，始用殉。重器备，椁有四阿，棺有翰桧。君子谓：“华元、乐举，于是乎不臣。臣治烦去惑者也，是以伏死而争。今二子者，君生则纵其惑，死又益其侈，是弃君于恶也。何臣之为？”
九月，卫穆公卒，晋三子自役吊焉，哭于大门之外。卫人逆之，妇人哭于门内，送亦如之。遂常以葬。
楚之讨陈夏氏也，庄王欲纳夏姬，申公巫臣曰：“不可。君召诸侯，以讨罪也。今纳夏姬，贪其色也。贪色为淫，淫为大罚。《周书》曰：‘明德慎罚。’文王所以造周也。明德，务崇之之谓也。慎罚，务去之之谓也。若兴诸侯，以取大罚，非慎之也。君其图之！”王乃止。子反欲取之，巫臣曰：“是不祥人也！是夭子蛮，杀御叔，杀灵侯，戮夏南，出孔、仪，丧陈国，何不祥如是！人生实难，其有不获死乎？天下多美妇人，何必是？”子反乃止。
王以予连尹襄老。襄老死于邲，不获其尸，其子黑要烝焉。巫臣使道焉，曰：“归！吾聘女。”又使自郑召之，曰：“尸可得也，必来逆之。”姬以告王，王问诸屈巫。对曰：“其信！知[插图]之父，成公之嬖也，而中行伯之季弟也，新佐中军，而善郑皇戌，甚爱此子。其必因郑而归王子与襄老之尸以求之。郑人惧于邲之役而欲求媚于晋，其必许之。”王遣夏姬归。将行，谓送者曰：“不得尸，吾不反矣。”巫臣聘诸郑，郑伯许之。
及共王即位，将为阳桥之役，使屈巫聘于齐，且告师期，巫臣尽室以行。申叔跪从其父将適郢，遇之，曰：“异哉！夫子有三军之惧，而又有《桑中》之喜，宜将窃妻以逃者也。”及郑，使介反币，而以夏姬行。将奔齐，齐师新败，曰：“吾不处不胜之国。”遂奔晋，而因郤至以臣于晋。晋人使为邢大夫。
子反请以重币锢之，王曰：“止！其自为谋也，则过矣。其为吾先君谋也，则忠。忠，社稷之固也，所盖多矣。且彼若能利国家，虽重币，晋将可乎？若无益于晋，晋将弃之，何劳锢焉。”
晋师归，范文子后入。武子曰：“无为吾望尔也乎？”对曰：“师有功，国人喜以逆之，先入，必属耳目焉，是代帅受名也，故不敢。”武子曰：“吾知免矣。”郤伯见，公曰：“子之力也夫！”对曰：“君之训也，二三子之力也，臣何力之有焉！”范叔见，劳之如郤伯，对曰：“庚所命也，克之制也，燮何力之有焉！”栾伯见，公亦如之，对曰：“燮之诏也，士用命也，书何力之有焉！”
宣公使求好于楚。庄王卒，宣公薨，不克作好。公即位，受盟于晋。会晋伐齐。卫人不行使于楚，而亦受盟于晋，从于伐齐。故楚令尹子重为阳桥之役以救齐。将起师，子重曰：“君弱，群臣不如先大夫，师众而后可。《诗》曰：‘济济多士，文王以宁。’夫文王犹用众，况吾侪乎？且先君庄王属之曰：‘无德以及远方，莫如惠恤其民而善用之。’”乃大户，已责，逮鳏，救乏，赦罪，悉师。王卒尽行，彭名御戎，蔡景公为左，许灵公为右。二君弱，皆强冠之。
冬，楚师侵卫，遂侵我，师于蜀。使臧孙往，辞曰：“楚远而久，固将退矣。无功而受名，臣不敢。”楚侵及阳桥，孟孙请往赂之。以执斫、执针、织纴，皆百人，公衡为质，以请盟。楚人许平。
十一月，公及楚公子婴齐、蔡侯、许男、秦右大夫说、宋华元、陈公孙宁、卫孙良夫、郑公子去疾及齐国之大夫盟于蜀。卿不书，匮盟也。于是乎畏晋而窃与楚盟，故曰匮盟。蔡侯、许男不书，乘楚车也，谓之失位。君子曰：“位其不可不慎也乎！蔡、许之君，一失其位，不得列于诸侯，况其下乎？《诗》曰：‘不解于位，民之攸塈。’其是之谓矣。”
楚师及宋，公衡逃归。臧宣叔曰：“衡父不忍数年之不宴，以弃鲁国，国将若之何？谁居？后之人必有任是夫！国弃矣。”
是行也，晋辟楚，畏其众也。君子曰：“众之不可以已也。大夫为政，犹以众克，况明君而善用其众乎？《大誓》所谓‘商兆民离，周十人同’者，众也。”
晋侯使巩朔献齐捷于周，王弗见，使单襄公辞焉，曰：“蛮夷戎狄，不式王命，淫湎毁常，王命伐之，则有献捷，王亲受而劳之，所以惩不敬，劝有功也。兄弟甥舅，侵败王略，王命伐之，告事而已，不献其功，所以敬亲暱，禁淫慝也。今叔父克遂有功于齐，而不使命卿镇抚王室，所使来抚余一人，而巩伯实来，未有职司于王室，又奸先王之礼，余虽欲于巩伯，其敢废旧典以忝叔父？夫齐，甥舅之国也，而大师之后也，宁不亦淫从其欲以怒叔父，抑岂不可谏诲？”士庄伯不能对。王使委于三吏，礼之如侯伯克敌使大夫告庆之礼，逄于卿礼一等。王以巩伯宴而私贿之。使相告之曰：“非礼也，勿籍。”', '', '', '二年春季，齐顷公进攻我国北部边境，包围龙地。齐顷公的宠臣卢蒲就魁攻打城门，龙地的人把他逮住囚禁。齐顷公说：“不要杀，我和你们盟誓，不进入你们的境内。”龙地的人不听，把他杀了，暴尸城上。齐顷公亲自击鼓，兵士爬上城墙。三天，占领了龙地。于是就向南入侵，到达巢丘。
卫穆公派遣孙良夫、石稷、宁相、向禽率兵入侵齐国，和齐军相遇。石稷想要回去，孙良夫说：“不行。用军队攻打别人，遇上敌人就回去，将怎样对国君说呢？如果知道不能作戕，就应当不出兵。现在既然和敌军相遇，不如打一仗。”
夏季，有。
石稷说：“军队战败了，您如果不稍稍等待，顶住敌军，将会全军覆灭。您丧失了军队，如何回报君命？”大家都不回答。石稷又说：“您，是国家的卿。损失了您，就是一种羞耻了。您带着大家撤退，我就留在这里。”同时通告军中，说援军的战车来了不少。齐国的军队就停止前进，驻扎在鞠居。
新筑大夫仲叔于奚援救了孙良夫，孙良夫因此得免于难。不久，卫国人把城邑赏给仲叔于奚。仲叔于奚辞谢，而请求得到诸侯所用三面悬挂的乐器，并用繁缨装饰马匹来朝见，卫君允许了。孔子听说这件事，说：“可惜啊，还不如多给他城邑。惟有器物和名号，不能假借给别人，这是国君掌握的。名号用来赋予威信，威信用来保持器物，器物用来体现礼制，礼制用来推行道义，道义用来产生利益，利益用来治理百姓，这是政权中的大节。如果把名位、礼器假借给别人，这就是把政权给了别人。失去政权，国家也就跟着失去，这是不能阻止的。”
孙桓子回到新筑，不进国都，就到晋国请求出兵。臧宣叔也到晋国请求出兵。两人都投奔郤克。晋景公答应派出七百辆战车。郤克说：“这是城濮之战的战年数。当时有先君的明察和先大夫的敏捷，所以得胜。克和先大夫相比，还不足以做他们的仆人。请发八百乘战车。”晋景公答应了。郤克率领中军，士燮辅佐上军，栾书率领下军，韩厥做司马，以救援鲁国和卫国，臧宣叔迎接晋军，同时向导开路。季文子率领军队和他们会合。到达卫国境内，韩厥要杀人，郤克驾车疾驰赶去，打算救下那个人。等赶到，已经杀了。郤克派人把尸体在军中示众，还告诉他的御者说：“我用这样的做法来分担指责。”
晋、鲁、卫联军在莘地追上齐军。六月十六日，军队到达靡笄山下。齐顷公派人请战，说：“您带领国君的军队光临敝邑，敝国的士兵不强，也请在明天早晨相见决战。”郤克回答说：“晋和鲁、卫是兄弟国家，他们前来告诉我们说：‘大国不分早晚都在敝邑的土地上发泄气愤。’寡君不忍，派下臣们前来向大国请求，同时又不让我军长久留在贵国。我们只能前进不能后退，您的命令是不会不照办的。”齐顷公说：“大夫允许，正是齐国的愿望；如果不允许，也要兵戎相见的。”齐国的高固攻打晋军，拿起石头扔向晋军，抓住晋军战俘，然后坐上他的战车，把桑树根子系在车上，巡行到齐营说：“想要勇气的人可以来买我剩下的勇气！”
十七日，齐、晋两军在鞌地摆开阵势。邴夏为齐顷公驾车，逢丑父作为车右。晋国的解张为郤克驾车，郑丘缓作为车右。齐顷公说：“我暂且消灭了这些人再吃早饭。”马不披甲，驰向晋军。郤克受了箭伤，血流到鞋子上，但是鼓声不断，说：“我受伤了！”解张说：“从一开始交战，箭就射穿了我的手和肘，我折断了箭杆仍驾车，左边的车轮都染成黑红色，哪里敢说受伤？您忍着点吧！”郑丘缓说：“从一开始交战，如果遇到危险，我必定下车推车，您难道了解吗？不过您真是受伤了！”解张说：“军队的耳目，在于我的旗子和鼓声，前进后退都要听从它。这辆车子由一个人镇守，战事就可以完成。为什么要为了一点痛苦而败坏国君的大事呢？身披盔甲，手执武器，本来就抱定必死的决心，受伤还没有到死的程度，你还是尽力而为吧！”于是就左手一把握着马缰，右手拿着鼓槌击鼓。马奔跑不能停止，全军就跟着上去。齐军大败，晋国追赶齐军，绕了华不注山三圈。
韩厥梦见他父亲子舆对他说：“明天不要站在战车左右两侧。”因此韩厥就在中间驾战车而追赶齐顷公。邴夏说：“射那位驾车人，他是君子。”齐顷公说：“认为他是君子而射他，这不合于礼。”射车左，车左死在车下。射车右，车右死在车中。綦毋张丢失了战车，跟上韩厥说：“请允许我搭乘您的战车。”上车，准备站在左边或右边，韩厥用肘推他，使他站在身后。韩厥弯下身子，放稳车右的尸体。逢丑父和齐顷公乘机互换位置。将要到达华泉，骖马被树木绊住了。头几天，逢丑父睡在栈车里，有一条蛇爬到他身边，他用小臂去打蛇，小臂受伤，但隐瞒了这件事，由于这样，他不能用臂推车前进，这样才被韩厥追上。韩厥拿着马缰走向马前，跪下叩头，捧着酒杯加上玉璧献上，说：“寡君派臣下们替鲁、卫两国请求，说：‘不要让军队进入齐国的土地。’下臣不幸，正好在军队服役，不能逃避服役。而且也害怕奔走逃避成为两国国君的耻辱。下臣身为一名战士，谨向君王报告我的无能，但由于人手缺乏，只好承当这个官职。”逢丑父要齐顷公下车，到华泉去取水。郑周父驾御副车，宛茷作为车右，带着齐顷公逃走而免于被俘。韩厥献上逢丑父，郤克要杀死逢丑父。逢丑父喊叫说：“从今以后再没有代替他国君受难的人了，有一个在这里，还要被杀死吗？”郤克说：“一个人不畏惧用死来使他的国君免于祸患，我杀了他，不吉利。赦免了他，用来勉励事奉国君的人。”于是就释放了逢丑父。
齐顷公免于被俘以后，寻找逢丑父，在晋军中三进三出。每次出来的时候，齐军都簇拥着护卫他。进入狄人军队中，狄人的士兵都抽出戈和盾以保护齐顷公。进入卫国的军队中，卫军也对他们不加伤害。于是，齐顷公就从徐关进入齐国临淄。齐顷公看到守军，说：“你们努力吧！齐军战败了！”齐顷公的车前进时使一个女子让路，这个女子说：“国君免于祸难了吗？”说：“免了。”她说：“锐司徒免于祸难了吗？”说：“免了。”她说：“如果国君和我父亲免于祸难了，还要怎么样？”就跑开了。齐顷公认为她知礼，不久查询，才知道是辟司徒的妻子，就赐给她石窌地方作为封邑。
晋军追赶齐军，从丘舆进入齐国，进攻马陉。齐顷公派遣宾媚人把纪甗、玉磬和土地送给战胜诸国，说：“如果他们不同意讲和，就随他们怎么办吧。”宾媚人送去财礼，晋国人不同意，说：“一定要让萧同叔子作为人质，同时使齐国境内的田陇全部东向。”宾媚人回答说：萧同叔子不是别人，是寡君的母亲，如果从对等地位来说，那也就是晋军的母亲。您在诸侯中发布重大的命令，反而说一定要把人家的母亲作为人质以取信，您又将要怎样对待周天子的命令呢？而且这样做，就是用不孝来命令诸侯。《诗》说：“孝子的孝心没有竭尽，永远可以感染你的同类。”如果用不孝号令诸侯，这恐怕不是道德的准则吧！先王对天下的土地，定疆界、分地理，因地制宜，以获取应得的利益。所以《诗》说：“我划定疆界、分别地理，南向东向开辟田亩。”现在您让诸侯定疆界、分地理，反而只说什么“田垄全部东向”，不顾地势是否适宜，只管自己兵车进出的有利，恐怕不是先王的政令吧！违反先王的遗命就是不合道义，怎么能做盟主？晋国确实是有缺点的。四王能统一天下，主要是能树立德行而满足诸侯的共同愿望；五伯能领导诸侯，主要是能自己勤劳而安抚诸侯，使大家服从天子的命令。现在您要求会合诸侯，来满足没有止境的欲望。《诗》说：“政事的推行宽大和缓，各种福禄都将积聚。”您确实不能宽大，丢弃了各种福禄，这对诸侯有什么害处呢？如果您不肯答应，寡君命令我使臣，就有话可说了：“您带领国君的军队光临敝邑，敝邑用很少的财富，来犒劳您的左右随员。害怕贵国国君的愤怒，我军战败。您惠临而肯赐齐国的福，不灭亡我们的国家，让齐、晋两国继续过去的友好，那么先君的破旧器物和土地我们是不敢爱惜的。您如果又不肯允许，我们就请求收集残兵败将，背靠自己的城下再决最后一战。敝邑有幸而战胜，也会依从贵国的；何况不幸而败，哪敢不听从您的命令？”
鲁、卫两国劝谏郤克说：“齐国怨恨我们了。齐国死去和溃散的，都是齐侯亲近的人。您如果不肯答应，必然更加仇恨我们。即使是您，还有什么可追求的？如果您得到齐国的国室，我们也得到失地，而缓和了祸难，这荣耀也就很多了。齐国和晋国都是由上天授与的，难道一定只有晋国永久胜利吗？”晋国人答应了鲁、卫的意见，回答说：“下臣们率领兵车，来为鲁、卫两国请求。如果有话可以向寡君复命，这就是君王的恩惠了。岂敢不遵命？”
禽郑从军中去迎接鲁成公。
秋季，七月，晋军和齐国宾媚人在爰娄结盟，让齐国归还我国汶阳的土田。成公在上鄍会见晋军，把先路和三命的车赐给三位高级将领，司马、司空、舆帅、候正、亚旅都接受了一命的车服。
八月，宋文公去世。开始厚葬：用蚌蛤和木炭，增加陪葬的车马，开始用活人殉葬，用很多器物陪葬。椁有四面呈坡形，棺有翰、桧等装饰。
君子认为：“华元、乐举，在这里有失为臣之道。臣子，是为国君去掉烦乱解除迷惑的，因此要冒死去谏诤。现在这两个人，国君活着的时候就由他去放纵作恶，死了以后又增加他的奢侈，这是把国君推入邪恶里去，这算是什么臣子？”
九月，卫穆公去世，晋国的三位将领从战地率兵返国途中顺便去吊唁，在大门之外哭吊。卫国人迎接他们，女人在门内哭。送他们的时候也是这样。以后别国官员来吊唁就是以此为常，直到下葬。
楚国在攻打陈国夏氏的时候，楚庄王想收纳夏姬。申公巫臣说：“不行。君王召集诸侯，是为了讨伐有罪；现在收纳夏姬，就是贪恋她的美色了。贪恋美色叫做淫，淫就会受到重大处罚。《周书》说：‘宣扬道德，谨慎惩罚’，文王因此而创立周朝。宣扬道德，就是致力于提倡它，谨慎惩罚，就是致力于不用它。如果出动诸侯的军队反而得到重大处罚，就是不谨慎了。君王还是考虑一下吧！”楚庄王就不要夏姬了。子反想要娶夏姬，巫臣说：“这是个不吉利的人。她使子蛮早死，杀了御叔，弑了灵侯，诛了夏南，使孔宁、仪行父逃亡在外，陈国因此被灭亡，为什么不吉利到这个样子！人生在世实在很不容易，如果娶了夏姬，恐怕不得好死吧！天下多的是漂亮的女人，为什么一定要她？”子反也就不要她了。楚庄王把夏姬给了连尹襄老。襄老在邲地战役中死去，没有找到尸首。他的儿子黑要和夏姬私通。巫臣派人向夏姬示意，说：“回娘家去，我娶你。”又派人从郑国召唤她说：“襄老尸首可以得到，一定要亲自来接。”夏姬把这话报告楚庄王。楚庄王就问巫臣。巫臣回答说：“恐怕是靠得住的。知罃的父亲，是成公的宠臣，又是中行伯的小兄弟，新近做了中军佐，和郑国的皇戌交情很好，非常喜爱这个儿子，他一定是想通过郑国而归还王子和襄老尸首而来要求交换知罃。郑国人对邲地战役感到害怕，同时要讨好于晋国，他们一定会答应。”楚庄王就打发夏姬回去。将要动身的时候，夏姬对送行的人说：“不能得到尸首，我就不回来了。”巫臣在郑国聘她为妻，郑襄公允许了。等到楚共王即位，将要发动阳桥战役，派巫臣到齐国聘问，同时把出兵的日期告诉齐国。巫臣把一切家财全部带走。申叔跪跟着他的父亲将要到郢都去，碰上巫臣，说：“怪哉！这个人有肩负军事重任的戒惧之心，却又有‘桑中’幽会的喜悦之色，可能是将要带着别人的妻子私奔吧！”到了郑国，巫臣派副使带回财礼，就带着夏姬走了。准备逃亡到齐国，齐国又被战败，巫臣说：“我不住在不打胜仗的国家。”就逃亡到晋国，并且由于郤至的关系在晋国做臣下。晋国人让他做邢地的大夫。子反请求把巨款送给晋国，而要求晋国对巫臣永不录用，楚共王说：“别那样做！他为自己打算是错误的，他为我的先君打算则是忠诚的。忠诚，国家靠着它来巩固，所能保护的东西就多了。而且他如果能有利于晋国，虽然送去重礼，晋国会同意永不录用吗？如果对晋国没有好处，晋国将会不要他，何必求其永不录用呢？”
晋国军队回国，范文子最后回来。他的父亲范武子说“你不也知道我在盼望你吗？”范文子回答说：“出兵有功劳，国内的人们高兴地迎接他们。先回来，一定受到人们的注意，这是代替统帅接受荣誉，所以我不敢。”武子说：“你这样谦让，我认为可以免于祸害了。”
郤伯入见，晋景公说：“这是您的功劳啊！”郤伯回答说：“这是君王的教导，诸位将帅的功劳，下臣有什么功劳呢？”范文子入见，晋景公像对郤伯一样慰劳他。范文子回答说：“这是范庚的命令，郤克的节制，小臣士燮有什么功劳呢？”栾伯进见，晋景公也如同慰劳郤伯他们一样慰劳他。栾伯回答说：“这是士燮的指示，士兵服从命令，小臣栾书有什么功劳呢？”
鲁宣公曾派遣使者到楚国要求建立友好关系，由于楚庄王死了，不久鲁宣公也死去，没有能够建立友好关系。鲁成公即位，在晋国接受盟约，会合晋国进攻齐国。卫国人不派使者去楚国聘问，也在晋国接受盟约，跟从着进攻齐国。因此楚国的令尹子重发动阳桥战役来救齐国。将要发兵，子重说：“国君年幼，臣下们又比不上先大夫，军队人数众多然后才可以取胜。《诗》说：‘众多的人士，文王借以安宁。’文王尚且使用大众，何况是我们这些人呢？而且先君庄王把国君嘱托给我们说：‘如果没有德行到达边远的地方，还不如加恩体恤百姓而很好地使用他们。’”于是楚国就大事清查户口，免除税收的拖欠，施舍鳏夫，救济困乏，赦免罪人。动员全部军队，楚王的警卫军也全部出动。彭名驾御战车，蔡景公作为车左，许灵公作为车右。两位国君还没有成年，都勉强行了冠礼。
冬季，楚军入侵卫国，就乘机在蜀地进攻我国。派臧孙去到楚军中求和。臧孙辞谢说：“楚军远离本国为时很久，本来就要退兵了。没有功劳而接受荣誉，下臣不敢。”楚军进攻到达阳桥，孟孙请求前去送给楚军木工、缝工、织工各一百人，公衡作为人质，请求结盟。楚国人答应讲和。
十一月，鲁成公和楚国公子婴齐、蔡景侯、许灵公、秦国右大夫说、宋国华元、陈国公孙宁、卫国孙良夫、郑国公子去疾和齐国大夫在蜀地结盟。《春秋》没有记载卿的名字，这是由于结盟缺乏诚意。在这种情况下又因为鲁国畏惧晋国而偷偷和楚国结盟，所以说“结盟缺乏诚意”。《春秋》没有记载蔡景侯、许灵公，这是由于他们乘坐了楚国的战车，叫做失去了身份。君子说：“身份是不可以不慎重的啊！蔡、许两国国君，一旦失去身份，就不能列在诸侯之中，何况在他们之下的人呢！《诗》说：‘在高位的人不懈怠，百姓就能得到休息。’说的就是这种情况了。”
楚军到达宋国，公衡逃了回来。臧孙说：“衡父不能忍耐几年的不安宁，抛弃鲁国，国家将怎么办？谁来受祸？他的后代一定会有受到祸患的！国家被抛弃了”
在这次军事行动中，晋军避开楚军，由于害怕他们人数过多。君子说：“大众是不可以不用的。大夫当政，尚且可以利用大众来战胜敌人，何况是贤明的国君而且又能善于使用大众呢？《大誓》所说商朝亿万人离心离德，周朝十个人同心同德，都是说的大众啊。”
晋景公派遣巩朔到成周进献战胜齐国的战利品，周定王不接见，派遣单襄公辞谢，说：“蛮夷戎狄，不遵奉天子的命令，迷恋酒色，败坏了天子的制度，天子命令讨伐他，就有了进献战利品的礼仪。天子亲自接受而加以慰劳，用这来惩罚不敬，勉励有功。如果是兄弟甥舅的国家侵犯败坏天子的法度，天子命令讨伐他，只向天子报告一下情况罢了，不用进献俘虏，用这来尊敬亲近、禁止邪恶。现在叔父能够顺利成功，在齐国建立了功勋，而不派遣曾受天子任命的卿来安抚王室，所派遣来安抚我的使者，仅仅是巩伯，他在王室中没有担任职务，又违反了先王的礼制。我虽然喜爱巩伯，岂敢废弃旧的典章制度以羞辱叔父？齐国和周室是甥舅之国，而且是姜太公的后代，叔父攻打齐国，难道是齐国放纵了私欲以激怒了叔父？或是齐国已经不可谏诤和教诲了呢？”巩朔不能回答。周定王把接待的事情交给三公，让他们用侯、伯战胜敌人派大夫告捷的礼节接待巩朔，比接待卿的礼节低一等。周定王和巩伯饮宴，私下送给他财礼，让相礼者告诉他说：“这是不合于礼制的，不要记载在史册上。”', NULL, '', 'indent', 1559038128, '5cec982ba673f5006821a473', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643003, '左传 · 成公 · 成公三年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三年春王正月，公会晋侯、宋公、卫侯、曹伯伐郑。辛亥，葬卫穆公。二月，公至自伐郑。甲子，新宫灾。三日哭。乙亥，葬宋文公。夏，公如晋。郑公子去疾帅师伐许。公至自晋。秋，叔孙侨如帅师围棘。大雩。晋郤克、卫孙良夫伐啬咎如。冬十有一月，晋侯使荀庚来聘。卫侯使孙良夫来聘。丙午，及荀庚盟。丁未，及孙良夫盟。郑伐许。
【传】三年春，诸侯伐郑，次于伯牛，讨邲之役也，遂东侵郑。郑公子偃帅师御之，使东鄙覆诸鄤，败诸丘舆。皇戌如楚献捷。
夏，公如晋，拜汶阳之田。
许恃楚而不事郑，郑子良伐许。
晋人归公子谷臣与连尹襄老之尸于楚，以求知荦。于是荀首佐中军矣，故楚人许之。王送知荦，曰：「子其怨我乎？」对曰：「二国治戎，臣不才，不胜其任，以为俘馘。执事不以衅鼓，使归即戮，君之惠也。臣实不才，又谁敢怨？」王曰：「然则德我乎？」对曰：「二国图其社稷，而求纾其民，各惩其忿以相宥也，两释累囚以成其好。二国有好，臣不与及，其谁敢德？」王曰：「子归，何以报我？」对曰：「臣不任受怨，君亦不任受德，无怨无德，不知所报。」王曰：「虽然，必告不谷。」对曰：「以君之灵，累臣得归骨于晋，寡君之以为戮，死且不朽。若从君之惠而免之，以赐君之外臣首；首其请于寡君而以戮于宗，亦死且不朽。若不获命，而使嗣宗职，次及于事，而帅偏师以修封疆，虽遇执事，其弗敢违。其竭力致死，无有二心，以尽臣礼，所以报也。」王曰：「晋未可与争。」重为之礼而归之。
秋，叔孙侨如围棘，取汶阳之田。棘有服，故围之。
晋郤克、卫孙良夫伐啬咎如，讨赤狄之馀焉。啬咎如溃，上失民也。
冬十一月，晋侯使荀庚来聘，且寻盟。卫侯使孙良夫来聘，且寻盟。公问诸臧宣叔曰：「中行伯之于晋也，其位在三。孙子之于卫也，位为上卿，将谁先？」对曰：「次国之上卿当大国之中，中当其下，下当其上大夫。小国之上卿当大国之下卿，中当其上大夫，下当其下大夫。上下如是，古之制也。卫在晋，不得为次国。晋为盟主，其将先之。」丙午，盟晋，丁未，盟卫，礼也。
十二月甲戌，晋作六军。韩厥、赵括、巩朔、韩穿、荀骓、赵旃皆为卿，赏鞍之功也。
齐侯朝于晋，将授玉。郤克趋进曰：「此行也，君为妇人之笑辱也，寡君未之敢任。」晋侯享齐侯。齐侯视韩厥，韩厥曰：「君知厥也乎？」齐侯曰：「服改矣。」韩厥登，举爵曰：「臣之不敢爱死，为两君之在此堂也。」
荀荦之在楚也，郑贾人有将置诸褚中以出。既谋之，未行，而楚人归之。贾人如晋，荀荦善视之，如实出己，贾人曰：「吾无其功，敢有其实乎？吾小人，不可以厚诬君子。」遂适齐。', '', '', '三年春季，诸侯联军进攻郑国，联军驻扎在伯牛，这是讨伐邲地战役郑国对晋国有二心，于是就从东边入侵郑国。郑国的公子偃领兵抵御，命令东部边境地方部队在鄤地设下埋伏，把敌军在丘舆击败。皇戌到楚国进献战利品。
夏季，鲁成公到晋国，拜谢晋国让齐国退还汶阳的土田。
许国依仗楚国而不事奉郑国，郑国的子良进攻许国。
晋国人把楚国公子穀臣和连尹襄老尸首归还给楚国，以此要求换回知罃。当时荀首已经是中军副帅，所以楚国人答应了。楚共王送别知罃，说：“您恐怕怨恨我吧！”知罃回答说：“两国交战，下臣没有才能，不能胜任所当职务，所以做了俘虏。君王的左右的人没有用我的血来祭鼓，而让我回国去接受杀戮，这是君王的恩惠啊。下臣实在没有才能，又敢怨恨谁？”楚共王说：“那么感激我吗？”知罃回答说：“两国为自己的国家打算，希望让百姓得到安宁，各自抑止自己的愤怒，求得互相原谅，两边都释放被俘的囚犯，以结成友好。两国友好，下臣不曾与谋，又敢感激谁？”楚共王说：“您回去，用什么报答我？”知罃回答说：“下臣既不怨恨，君王也不值得感恩，没有怨恨，没有恩德，就不知道该报答什么。”楚共王说：“尽管这样，也一定把您的想法告诉我。”知罃回答说：“承君王的福佑，被囚的下臣能够带着这把骨头回晋国，寡君如果加以诛戮，死得幸运。如果由于君王的恩惠而赦免下臣，把下臣赐给您的外臣荀首，荀首向我君请求，而把下臣杀戮在自己的宗庙中，也死得幸运。如果得不到寡君诛戮的命令，而让下臣继承宗子的地位，按次序承担晋国的大事，率领一部分军队以保卫边疆，虽然碰到君王的左右，我也不敢违背礼义回避，要竭尽全力以至于死，没有二心，以尽到为臣的职责，这就是所报答于君王的。”楚共王说：“晋国是不可以和它相争的。”于是就对知罃重加礼遇而放他回晋国去。
秋季，叔孙侨如包围棘地，占取了汶阳的土田。由于棘地人不服从，所以包围了棘。
晋国的郤克、卫国的孙良夫进攻廧咎如，讨伐赤狄的残余。廧咎如溃败，这是由于他们的上级失去了民心。
冬季，十一月，晋景公派遣荀庚前来聘问，同时重温过去的盟约。卫定公派遣孙良夫前来聘问，并且重温过去的盟约。鲁成公向臧宣叔询问说：“中行伯在晋国，位次排列第三；孙子在卫国，位次是上卿，应该让谁在前？”臧宣叔回答说：“次国的上卿，相当于大国的中卿，中卿相当于它的下卿，下卿相当于它的上大夫。小国的上卿，相当于大国的下卿，中卿相当于它的上大夫，下卿相当于它的下大夫。位次的上下如此，这是古代的制度。卫国对晋国来说，不能算是次国。晋国是盟主，晋国应该先行礼。”二十八日，和晋国结盟。二十九日，和卫国结盟。这是合于礼的。
十二月二十六日，晋国编成六个军。韩厥、赵括、巩朔、韩穿、荀骓、赵旃都做了卿，这是为了赏赐在鞌地战役中的功劳。
齐顷公到晋国朝见，将要举行授玉的仪式。郤克快步走进来，说：“这一趟，君王是为女人的取笑而受到了羞辱，寡君不敢当。”晋景公设宴招待齐顷公。齐顷公注视着韩厥。韩厥说：“君王认识厥吗？”齐顷公说：“服装换了。”韩厥登阶，举起酒杯说：“下臣所以不惜一死，当时就是为了两位国君现在在这个堂上饮宴啊。”
荀罃在楚国的时侯，郑国的商人准备把他藏在袋子里逃出楚国。已经商量好，还没有动身，楚国人就把他送回来了。这个商人到晋国，荀罃待他很好，好像确实救了自己一样。商人说：“我没有那样的功劳，敢有这样的实惠吗？我是小人，不能够这样来欺骗君子。”商人于是就到齐国去了。
', NULL, '', 'indent', 1559038172, '5cec98587b968a0076718276', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643004, '左传 · 成公 · 成公四年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】四年春，宋公使华元来聘。三月壬申，郑伯坚卒。杞伯来朝。夏四月甲寅，臧孙许卒。公如晋。葬郑襄公。秋，公至自晋。冬，城郓。郑伯伐许。
【传】四年春，宋华元来聘，通嗣君也。
杞伯来朝，归叔姬故也。
夏，公如晋，晋侯见公，不敬。季文子曰：「晋侯必不免。《诗》曰：『敬之敬之！天惟显思，命不易哉！』夫晋侯之命在诸侯矣，可不敬乎？」
秋，公至自晋，欲求成于楚而叛晋，季文子曰：「不可。晋虽无道，未可叛也。国大臣睦，而迩于我，诸侯听焉，未可以贰。史佚之《志》有之，曰：『非我族类，其心必异。』楚虽大，非吾族也，其肯字我乎？」公乃止。
冬十一月，郑公孙申帅师疆许田，许人败诸展陂。郑伯伐许，锄任、泠敦之田。
晋栾书将中军，荀首佐之，士燮佐上军，以救许伐郑，取汜、祭。楚子反救郑，郑伯与许男讼焉。皇戌摄郑伯之辞，子反不能决也，曰：「君若辱在寡君，寡君与其二三臣共听两君之所欲，成其可知也。不然，侧不足以知二国之成。」
晋赵婴通于赵庄姬。
', '', '', '四年春季，宋国的华元前来聘问，这是为继位的国君通好。
杞桓公来鲁国朝见，这是由于要将叔姬送回鲁国。
夏季，鲁成公去到晋国。晋景公会见成公，不恭敬。季文子说：“晋景公一定不免于祸难。《诗》说：‘谨慎又谨慎，上天光明普照，得到天命不容易啊！’晋景公的命运决定于诸侯，可以不恭敬吗？”
秋季，成公从晋国到达鲁国，想要向楚国要求友好而背叛晋国。季文子说：“不行。晋国虽然无道，尚不能背叛。国家广大、群臣和睦，而且靠近我国，诸侯听他的命令，不能有二心。史佚的《志》有这样的话：‘不是我们同族，他的心思必然不同。’楚国虽然土地广大，不是我们同族，难道肯爱我们吗？”成公就没有那样做。
冬季，十一月，郑国的公孙申带兵去划定所得许国土田的疆界。许国人在展陂打败了他们。郑伯进攻许国，占领了锄任、冷敦的土田。
晋将栾书率领中军，荀首作为副帅，士燮为上军副帅，救援许国，进攻郑国，占领了汜地、祭地。
楚国的子反救援郑国，郑襄公和许灵公在子反那里争论是非，皇戌代表郑襄公发言。子反不能判断，说：“您二位如果屈驾去问候寡君，寡君和他几个臣子共同听取两位君王的意见才可以判断出是非。否则，侧不大了解两国之间的是非。”
晋国的赵婴和赵庄姬私通。', NULL, '', 'indent', 1559038209, '5cec987f7b968a00767183c2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643005, '左传 · 成公 · 成公五年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】五年春王正月，杞叔姬来归。仲孙蔑如宋。夏，叔孙侨如会晋荀首于谷。梁山崩。秋，大水。冬十有一月己酉，天王崩。十有二月己丑，公会晋侯、齐侯、宋公、卫侯、郑伯、曹伯、邾子、杞伯同盟于虫牢。
【传】五年春，原、屏放诸齐。婴曰：「我在，故栾氏不作。我亡，吾二昆其忧哉！且人各有能有不能，舍我何害？」弗听。婴梦天使谓己：「祭余，余福女。」使问诸士贞伯，贞伯曰：「不识也。」既而告其人曰：「神福仁而祸淫，淫而无罚，福也。祭，其得亡乎？」祭之，之明日而亡。、孟献子如宋，报华元也。
孟献子如宋，报华元也。
夏，晋荀首如齐逆女，故宣伯餫诸谷。
梁山崩，晋侯以传召伯宗。伯宗辟重，曰：「辟传！」重人曰：「待我，不如捷之速也。」问其所，曰：「绛人也。」问绛事焉，曰：「梁山崩，将召伯宗谋之。」问：「将若之何？」曰：「山有朽壤而崩，可若何？国主山川。故山崩川竭，君为之不举，降服，乘缦，彻乐，出次，祝币，史辞以礼焉。其如此而已，虽伯宗若之何？」伯宗请见之，不可。遂以告而从之。
许灵公愬郑伯于楚。六月，郑悼公如楚，讼，不胜。楚人执皇戌及子国。故郑伯归，使公子偃请成于晋。秋八月，郑伯及晋赵同盟于垂棘。
宋公子围龟为质于楚而还，华元享之。请鼓噪以出，鼓噪以复入，曰：「习功华氏。」宋公杀之。
冬，同盟于虫牢，郑服也。诸侯谋复会，宋公使向为人辞以子灵之难。
十一月己酉，定王崩。', '', '', '五年春季，赵同、赵括把赵婴放逐到齐国。赵婴说：“有我在，所以栾氏不敢作乱。我逃亡，两位兄长恐怕就有忧患了。而且人们各有所能，也有所不能，赦免我又有什么坏处？”赵同、赵括不听。赵婴梦见天使对自己说：“祭祀我，我降福给你。”派人向士贞伯询问。士贞伯说：“不知道。”不久士贞伯就告诉别人说：“神灵降福给仁爱的人，而降祸给淫乱的人。淫乱而没有受到惩罚，这就是福了。祭祀了，难道无祸？”赵婴祭祀了神灵，第二天就逃亡了。
孟献子到了宋国，这是回报华元的聘问。
夏季，晋国的荀首去到齐国迎接齐女，所以宣伯在穀地给他馈送食物。
梁山崩塌，晋景公用传车召见伯宗。伯宗在路上叫一辆载重车避开，说：“为传车让路。”押送重车的人说：“与其等我，不如走小路要快一些。”伯宗问他是哪里人，押车人说：“绛城人。”伯宗问起绛城的事情。押车人说：“梁山崩塌，打算召见伯宗商量。”伯宗问：“准备怎么办？”押车人说：“山有了腐朽的土壤而崩塌。又能怎么办？国家以山川为主，所以遇到山崩川竭，国君就要为它减膳撤乐、穿素服、乘坐没有彩画的车子、不奏音乐、离开寝宫、陈列献神的礼物。太史宣读祭文，以礼祭祀山川之神。就是这样罢了，即使是伯宗，还能怎么样？”伯宗要求带押车人去见晋景公，他不答应。于是伯宗就把押车人的话告诉了晋景公，晋景公听从了。
许灵公在楚国控告郑悼公。六月，郑悼公去到楚国争讼，没有取得胜利，楚国人抓住了皇戌和子国。所以郑悼公回国以后，派遣公子偃到晋国要求讲和。秋季，八月，郑悼公和晋国的赵同在垂棘结盟。
宋国的公子围龟在楚国当人质以后回到宋国，华元设享礼招待他。围龟请求打鼓呼叫而出华元的大门，又打鼓呼叫而进去，说：“这就是演习进攻华氏。”宋共公把他杀了。
冬季，鲁成公和晋景公、齐顷公、宋共公、卫定公、郑悼公、曹宣公、邾子、杞桓公在虫牢结盟，这是由于郑国顺服。
诸侯商量再次会见，宋共公派向为人以子灵事件为理由而辞谢了，不参加会见。
十一月十二日，周定王逝世。', NULL, '', 'indent', 1559038248, '5cec98a530863b00683e68fd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643006, '左传 · 成公 · 成公六年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】六年春王正月，公至自会。二月辛巳，立武宫。取鄟卫孙良夫帅师侵宋。夏六月，邾子来朝。公孙婴齐如晋。壬申，郑伯费卒。秋，仲孙蔑、叔孙侨如帅师侵宋。楚公子婴齐帅师伐郑。冬，季孙行父如晋。晋栾书帅师救郑。
【传】六年春，郑伯如晋拜成，子游相，授玉于东楹之东。士贞伯曰：「郑伯其死乎？自弃也已！视流而行速，不安其位，宜不能久。」
二月，季文子以鞍之功立武宫，非礼也。听于人以救其难，不可以立武。立武由己，非由人也。
取鄟，言易也。
三月，晋伯宗、夏阳说，卫孙良夫、宁相，郑人，伊、洛之戎，陆浑，蛮氏侵宋，以其辞会也。师于金咸，卫人不保。说欲袭卫，曰：「虽不可入，多俘而归，有罪不及死。」伯宗曰：「不可。卫唯信晋，故师在其郊而不设备。若袭之，是弃信也。虽多卫俘，而晋无信，何以求诸侯？」乃止，师还，卫人登陴。
晋人谋去故绛。诸大夫皆曰：「必居郇瑕氏之地，沃饶而近盬，国利君乐，不可失也。」韩献子将新中军，且为仆大夫。公揖而入。献子从。公立于寝庭，谓献子曰：「何如？」对曰：「不可。郇瑕氏土薄水浅，其恶易觏。易觏则民愁，民愁则垫隘，于是乎有沉溺重膇之疾。不如新田，土厚水深，居之不疾，有汾、浍以流其恶，且民从教，十世之利也。夫山、泽、林、盬，国之宝也。国饶，则民骄佚。近宝，公室乃贫，不可谓乐。」公说，从之。夏四月丁丑，晋迁于新田。
六月，郑悼公卒。
子叔声伯如晋。命伐宋。
秋，孟献子、叔孙宣伯侵宋，晋命也。
楚子重伐郑，郑从晋故也。
冬，季文子如晋，贺迁也。
晋栾书救郑，与楚师遇于绕角。楚师还，晋师遂侵蔡。楚公子申、公子成以申、息之师救蔡，御诸桑隧。赵同、赵括欲战，请于武子，武子将许之。知庄子、范文子、韩献子谏曰：「不可。吾来救郑，楚师去我，吾遂至于此，是迁戮也。戮而不已，又怒楚师，战必不克。虽克，不令。成师以出，而败楚之二县，何荣之有焉？若不能败，为辱已甚，不如还也。」乃遂还。
于是，军帅之欲战者众，或谓栾武子曰：「圣人与众同欲，是以济事。子盍从众？子为大政，将酌于民者也。子之佐十一人，其不欲战者，三人而已。欲战者可谓众矣。《商书》曰：『三人占，从二人。』众故也。」武子曰：「善钧，从众。夫善，众之主也。三卿为主，可谓众矣。从之，不亦可乎？」', '', '', '六年春季，郑悼公到晋国去拜谢讲和，子游辅助行礼，在东楹的东边举行授玉的仪式。士贞伯说：“郑悼公恐怕要死了！自己不尊重自己。目光流动东张西望而走路又快，很不安地坐在自己的位子上，大概不能活多久了。”
二月，鲁大夫季文子由于鞌地战役的武功建立了武宫，这是不合于礼的。听从别人的话来解救鲁国的灾难，不能标榜武功。建立武功应该在于自己，而不是由于别人的功劳。
占领鄟地，《春秋》记载说事情完成得很容易。
三月，晋国伯宗、夏阳说、卫国孙良夫、宁相、郑人、伊洛戎人、陆浑、蛮氏入侵宋国，这是由于宋国拒绝参加盟会。军队驻扎在鍼地。卫国人不加防守。夏阳说要袭击卫国，说：“虽然不能进入，多抓一些俘虏回去，有罪也不至于死。”伯宗说：“不行。卫国因为相信晋国，所以军队驻扎在他们郊外而不加防守，如果袭击他们，这是丢弃信用。虽然多抓了卫国俘虏，而晋国没有信义，用什么去获得诸侯的拥戴？”于是就停止了行动。军队回国，卫国人却登上了城墙。
晋国人计划离开故都绛城，大夫们都说：“一定要住在郇瑕氏的地方，那里肥沃富饶而靠近盐池，国家有利，国君欢乐，不可以失掉它。”韩献子正率领新中军，同时掌管宫中的事。晋景公朝罢向群臣作揖而后退入路门，韩献子跟着。晋景公站在正寝外边的庭院里，对韩献子说：“怎么样？”韩献子回答说：“不行。郇瑕氏土薄水浅，污秽肮脏的东西容易积聚。污秽的东西容易积聚，百姓就发愁，百姓发愁，身体就瘦弱，在这种情况下就会有风湿脚肿的疾病，不如新田，土厚水深，住在那里不生疾病，有汾水、浍水以冲走污秽，而且百姓习惯服从，这是子孙十代的利益。深山、大泽、森林、盐池，是国家的宝藏，国家富饶，百姓就骄傲放荡。靠近宝藏，大家争利，国家财富就少。不能说是欢乐。”晋景公很高兴，听从了他的话。夏季，四月十三日，晋国迁都到新田。
六月，郑悼公去世。
子叔声伯去到晋国，晋国命令鲁国进攻宋国。
秋季，孟献子、叔孙宣伯率兵入侵宋国，奉了晋国的命令。楚国的子重进攻郑国，这是由于郑国跟随晋国的缘故。
冬季，季文子去到晋国，为了祝贺晋国迁都。
晋国栾书救援郑国，和楚军在绕角相遇。楚军回国，晋军就侵袭蔡国。楚国公子申、公子成带领申地、息地的军队去救援蔡国，在桑隧抵抗晋军。赵同、赵括想要出战，向栾武子请求，栾武子打算答应。知庄子、范文子、韩献子劝谏说：“不行。我们来救援郑国，楚军离开我们，我们就到了这里，这是把杀戮转移到别人头上。杀戮而不停止，又激怒楚军，战争一定不能得胜。即便战胜，也不是好事。整顿军队出国，仅仅打败楚国两个县的军队，有什么光荣呢？如果不打败他们，受到的耻辱就太过分了。不如回去。”于是晋军就回去了。
当时军官中要作战的很多，有人对栾武子说：“圣人的愿望和大众相同，所以能成功。您何不听从大家的意见？您是执政大臣，应当斟酌百姓的意见。您的辅佐者十一个人，不想作战的仅仅三个人。想要作战的人可以说是大多数。《商书》说：‘三个人占卜，听从两个人的。’因为是多数的缘故。”栾武子说：“同样是好事，才服从多数，好事是大众的主张。现在有三位大臣主张，可以说是大众了。依从他们，不也是可以的吗？”', NULL, '', 'indent', 1559038293, '5cec98d243e78c006720575b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643007, '左传 · 成公 · 成公七年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】七年春王正月，鼷鼠食郊牛角，改卜牛。鼷鼠又食其角，乃免牛。吴伐郯。夏五月，曹伯来朝。不郊，犹三望。秋，楚公子婴齐帅师伐郑。公会晋侯、齐侯、宋公、卫侯、曹伯、莒子、邾子、杞伯救郑。八月戊辰，同盟于马陵。公至自会。吴入州来。冬，大雩。卫孙林父出奔晋。
【传】七年春，吴伐郯，郯成。季文子曰：「中国不振旅，蛮夷入伐，而莫之或恤，无吊者也夫！《诗》曰：『不吊昊天，乱靡有定。』其此之谓乎！有上不吊，其谁不受乱？吾亡无日矣！」君子曰：「如惧如是，斯不亡矣。」
郑子良相成公以如晋，见，且拜师。
夏，曹宣公来朝。
秋，楚子重伐郑，师于汜。诸侯救郑。郑共仲、侯羽军楚师，囚郧公钟仪，献诸晋。
八月，同盟于马陵，寻虫牢之盟，且莒服故也。
晋人以钟仪归，囚诸军府。
楚围宋之役，师还，子重请取于申、吕以为赏田，王许之。申公巫臣曰：「不可。此申、吕所以邑也，是以为赋，以御北方。若取之，是无申、吕也。晋、郑必至于汉。」王乃止。子重是以怨巫臣。子反欲取夏姬，巫臣止之，遂取以行，子反亦怨之。及共王即位，子重、子反杀巫臣之族子阎、子荡及清尹弗忌及襄老之子黑要，而分其室。子重取子阎之室，使沈尹与王子罢分子荡之室，子反取黑要与清尹之室。巫臣自晋遗二子书，曰：「尔以谗慝贪婪事君，而多杀不辜。余必使尔罢于奔命以死。」
巫臣请使于吴，晋侯许之。吴子寿梦说之。乃通吴于晋。以两之一卒适吴，舍偏两之一焉。与其射御，教吴乘车，教之战陈，教之叛楚。置其子狐庸焉，使为行人于吴。吴始伐楚，伐巢、伐徐。子重奔命。马陵之会，吴入州来。子重自郑奔命。子重、子反于是乎一岁七奔命。蛮夷属于楚者，吴尽取之，是以始大，通吴于上国。
卫定公恶孙林父。冬，孙林父出奔晋。卫侯如晋，晋反戚焉。
', '', '', '七年春季，吴国进攻郯国，郯国和吴国讲和。季文子说：“中原诸国不能镇慑蛮夷，蛮夷却来进攻，而没有人对此担忧，这是因为没有好国君的缘故啊！《诗》说：‘上天不善，动乱没有个安定的时候。’说的就是这种情况吧！有了上面的人但是不善，还有谁不受到动乱？我们很快就会灭亡了。”君子说：“像这样知道戒惧，这就不会灭亡了。”
郑国的子良作为郑成公的相礼到了晋国，进见晋景公，同时拜谢出兵救郑。
夏季，曹宣公前来朝见。
秋季，楚国的子重进攻郑国，军队驻扎在汜地。诸侯救援郑国。郑国的共仲、侯羽包围楚军，囚禁郧公钟仪，把他献给晋国。
八月，鲁成公和晋景公、齐顷公、宋共公、卫定公、曹宣公、莒子、邾子、杞桓公在马陵结盟，这是由于重温虫牢的盟约，同时又因莒国顺服的缘故。
晋国人带着钟仪回去，把他囚禁在军用储藏室里。
楚国包围宋国那一次战役，楚军回国，子重请求取得申邑、吕邑土地作为赏田。楚共王答应了。申公巫臣说：“不行。申、吕两地之所赖以成为城邑的，是因为从这里征发兵赋，以抵御北方。如果私人占有它，这就不能成为申邑和吕邑了。晋国和郑国一定可以到达汉水。”楚庄王就不给了。子重因此怨恨巫臣。子反想娶夏姬。巫臣阻止他，自己反而娶了夏姬逃到晋国，子反因此也很怨恨巫臣。等到楚共王即位，子重，子反杀了巫臣的族人子阎、子荡和清尹弗忌以及襄老的儿子黑要，并且瓜分他们的家产。子重取得了子阎的家产，让沈尹和王子罢瓜分子荡的家产，子反取得黑要和清尹弗忌的家产。巫臣从晋国写信给子反、子重两个人，说：“你们用邪恶贪婪事奉国君，杀了很多无罪的人，我一定要让你们疲于奔命而死。”
巫臣请求出使到吴国去，晋景公允许了。吴子寿梦喜欢他。于是巫臣就使吴国和晋国通好，带领了楚国的三十辆兵车到吴国做教练，留下十五辆给吴国。送给吴国射手和御者，教吴国人使用兵车，教他们安排战阵，教他们背叛楚国。巫臣又把自己的儿子狐庸留在那里，让他在吴国做外交官。吴国开始进攻楚国、进攻巢国、进攻徐国，子重奉命奔驰。在马陵会见的时候，吴军进入州来，子重从郑国奉命赶去救援。子重、子反在这种情况下，一年之中七次奉命奔驰以抵御吴军。蛮夷属于楚国的，吴国全部加以占取，因此吴国开始强大，吴国才得以和中原诸国往来。
卫定公讨厌孙林父。冬季，孙林父逃亡到晋国。卫定公去到晋国，晋国把孙林父的封邑戚地归还给了卫国。
', NULL, '', 'indent', 1559038335, '5cec98fba673f5006821abf8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643008, '左传 · 成公 · 成公八年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】八年春，晋侯使韩穿来言汶阳之田，归之于齐。晋栾书帅师侵蔡。公孙婴齐如莒。宋公使华元来聘。夏，宋公使公孙寿来纳币。晋杀其大夫赵同、赵括。秋七月，天子使召伯来赐公命。冬十月癸卯，杞叔姬卒。晋侯使士燮来聘。叔孙侨如会晋士燮、齐人、邾人代郯。卫人来媵。
【传】八年春，晋侯使韩穿来言汶阳之田，归之于齐。季文子饯之，私焉，曰：「大国制义以为盟主，是以诸侯怀德畏讨，无有贰心。谓汶阳之田，敝邑之旧也，而用师于齐，使归诸敝邑。今有二命曰：『归诸齐。』信以行义，义以成命，小国所望而怀也。信不可知，义无所立，四方诸侯，其谁不解体？《诗》曰：『女也不爽，士贰其行。士也罔极，二三其德。』七年之中，一与一夺，二三孰甚焉！士之二三，犹丧妃耦，而况霸主？霸主将德是以，而二三之，其何以长有诸侯乎？《诗》曰：『犹之未远，是用大简。』行父惧晋之不远犹而失诸侯也，是以敢私言之。」
晋栾书侵蔡，遂侵楚获申骊。楚师之还也，晋侵沈，获沈子揖初，从知、范、韩也。君子曰：「从善如流，宜哉！《诗》曰：『恺悌君子，遐不作人。』求善也夫！作人，斯有功绩矣。」是行也，郑伯将会晋师，门于许东门，大获焉。
声伯如莒，逆也。
宋华元来聘，聘共姬也。
夏，宋公使公孙寿来纳币，礼也。
晋赵庄姬为赵婴之亡故，谮之于晋侯，曰：「原、屏将为乱。」栾、郤为征。六月，晋讨赵同、赵括。武从姬氏畜于公宫。以其田与祁奚。韩厥言于晋侯曰：「成季之勋，宣孟之忠，而无后，为善者其惧矣。三代之令王，皆数百年保天之禄。夫岂无辟王，赖前哲以免也。《周书》曰：『不敢侮鳏寡。』所以明德也。」乃立武，而反其田焉。
秋，召桓公来赐公命。
晋侯使申公巫臣如吴，假道于莒。与渠丘公立于池上，曰：「城已恶！」莒子曰：「辟陋在夷，其孰以我为虞？」对曰：「夫狡焉思启封疆以利社稷者，何国蔑有？唯然，故多大国矣，唯或思或纵也。勇夫重闭，况国乎？」
冬，杞叔姬卒。来归自杞，故书。
晋士燮来聘，言伐郯也，以其事吴故。公赂之，请缓师，文子不可，曰：「君命无贰，失信不立。礼无加货，事无二成。君后诸侯，是寡君不得事君也。燮将复之。」季孙惧，使宣伯帅师会伐郯。
卫人来媵共姬，礼也。凡诸侯嫁女，同姓媵之，异姓则否。', '', '', '八年春季，晋景公派遣韩穿来鲁国谈到关于汶阳土田的事，要把汶阳之田归还给齐国。季文子设酒给他饯行，和他私下交谈，说：“大国处理事务合理适宜，凭这个作为盟主，因此诸侯怀念德行而害怕讨伐，没有二心。说到汶阳的土田，那原是敝邑所有，后来对齐国用兵，晋国命令齐国把它还给敝邑。现在又有不同的命令，说‘归还给齐国’。信用用来推行道义，道义用来完成命令，这是小国所盼望而怀念的。信用不能得知，道义无所树立，四方的诸侯，谁能不涣散瓦解？《诗》说：‘女子毫无过失，男人却有过错。男人没有标准，他的行为前后不一。’七年当中，忽而给予忽而夺走，前后不一还有比这更甚的吗？一个男人前后不一，尚且丧失配偶，何况是霸主？霸主应该用德，但却前后不一，他怎么能长久得到诸侯的拥护呢？《诗》说：‘谋略缺乏远见，因此极力劝谏。’行父害怕晋国不能深谋远虑而失去诸侯，因此敢于和您作私下的交谈。”
晋国栾书率军侵袭蔡国，接着又侵袭楚国，俘虏了申骊。楚军回去的时候，晋军侵袭沈国，俘虏了沈子揖初，这是听从了知庄子、范文子、韩献子等人的意见。君子说：“听从好主意好像流水一样，这是多么恰当啊！《诗》说：‘恭敬随和的君子，为什么不起用人材？’这就是求取善人啊！起用人材，这就有功绩了。” 这次行动，郑成公准备会合晋军，经过许国，攻打许国的东门，俘获很多。
声伯去到莒国，这是去迎接妻子。
宋国华元来鲁国聘问，为宋共公聘共姬为夫人。
夏季，宋共公派公孙寿前来代宋共公订婚，这是合于礼的。
晋国的赵庄姬为了赵婴逃亡的缘故，向晋景公诬陷说：“原（赵同）、屏（赵括）将要作乱。栾氏、郤氏可作证。”六月，晋国讨伐赵同、赵括。赵武跟随庄姬寄住在晋景公宫里。晋景公把赵氏的土田赐给祁奚。韩厥对晋景公说：“成季的功勋，宣孟的忠诚，但他们却没有后代来继承，做好事的人就要害怕了。三代的贤明君王，都能够几百年保持上天的禄位。难道就没有邪恶的君王？这是靠着他祖先的贤明才得以免于亡国。《周书》说：‘不敢欺侮鳏夫寡妇’，就是用这样的做法来发扬道德。”于是就立赵武为赵氏的继承人，归还了赵氏的土田。
秋季，周卿士召桓公前来向鲁成公颁赐袭爵的命令。
晋景公派遣申公巫臣去吴国，向莒国借路。巫臣和渠丘公站在护城河上，说：“城太坏了。”渠丘公说：“敝国偏僻简陋，处在蛮夷之地，有谁会把敝国作为觊觎的目的呢？”巫臣说：“狡猾的人想开辟疆土以利国家的，哪个国家没有？惟其如此，所以大国就多了。不过受觊觎的小国有的思虑有备，也有的放纵不备。勇敢的人还要层层关闭好内外门户，何况国家？”
冬季，杞国的叔姬死了。由于她从杞国被休了回到鲁国来，所以《春秋》加以记载。
晋国的士燮来鲁国聘问，声称要进攻郯国，因为郯国奉事吴国的缘故。鲁成公送给他财礼，请求从缓进兵。士燮不答应，说：“国君的命令说一不二，失去信义难以自立。除规定的礼物外，不应该增加财币，公事私事不能两全其美。君王后于诸侯出兵，这样寡君就不能事奉君王了。燮打算就这样向寡君回报。”季孙听了这话很害怕，派宣伯率兵会合进攻郯国。
卫国人送女子前来鲁国作为共姬的陪嫁，这是合于礼的。凡是诸侯女儿出嫁，同姓的国家送女作为陪嫁，异姓就不送。', NULL, '', 'indent', 1559038376, '5cec9924d5de2b0070854bc8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643009, '左传 · 成公 · 成公九年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】九年春王正月，杞伯来逆叔姬之丧以归。公会晋侯、齐侯、宋公、卫侯、郑伯、曹伯、莒子、杞伯，同盟于蒲。公至自会。二月伯姬归于宋。夏，季孙行父如宋致女。晋人来媵。秋七月丙子，齐侯无野卒。晋人执郑伯。晋栾书帅师伐郑。冬十有一月，葬齐顷公。楚公子婴齐帅师伐莒。庚申，莒溃。楚人入郓。秦人、白狄伐晋。郑人围许。城中城。
【传】九年春，杞桓公来逆叔姬之丧，请之也。杞叔姬卒，为杞故也。逆叔姬，为我也。
为归汶阳之田故，诸侯贰于晋。晋人惧，会于蒲，以寻马陵之盟。季文子谓范文子曰：「德则不竞，寻盟何为？」范文子曰：「勤以抚之，宽以待之，坚强以御之，明神以要之，柔服而伐贰，德之次也。」是行也，将始会吴，吴人不至。
二月，伯姬归于宋。
楚人以重赂求郑，郑伯会楚公子成于邓。
夏，季文子如宋致女，覆命，公享之。赋《韩奕》之五章，穆姜出于房，再拜，曰：「大夫勤辱，不忘先君以及嗣君，施及未亡人。先君犹有望也！敢拜大夫之重勤。」又赋《绿衣》之卒章而入。
晋人来媵，礼也。
秋，郑伯如晋。晋人讨其贰于楚也，执诸铜鞮。
栾书伐郑，郑人使伯蠲行成，晋人杀之，非礼也。兵交，使在其间可也。楚子重侵陈以救郑。
晋侯观于军府，见钟仪，问之曰：「南冠而絷者，谁也？」有司对曰：「郑人所献楚囚也。」使税之，召而吊之。再拜稽首。问其族，对曰：「泠人也。」公曰：「能乐乎？」对曰：「先父之职官也，敢有二事？」使与之琴，操南音。公曰：「君王何如？」对曰：「非小人之所得知也。」固问之，对曰：「其为大子也，师保奉之，以朝于婴齐而夕于侧也。不知其他。」公语范文子，文子曰：「楚囚，君子也。言称先职，不背本也。乐操土风，不忘旧也。称大子，抑无私也。名其二卿，尊君也。不背本，仁也。不忘旧，信也。无私，忠也。尊君。敏也。仁以接事，信以守之，忠以成之，敏以行之。事虽大，必济。君盍归之，使合晋、楚之成。」公从之，重为之礼，使归求成。
冬十一月，楚子重自陈伐莒，围渠丘。渠丘城恶，众溃，奔莒。戊申，楚入渠丘。莒人囚楚公子平，楚人曰：「勿杀！吾归而俘。」莒人杀之。楚师围莒。莒城亦恶，庚申，莒溃。楚遂入郓，莒无备故也。
君子曰：「恃陋而不备，罪之大者也；备豫不虞，善之大者也。莒恃其陋，而不修城郭，浃辰之间，而楚克其三都，无备也夫！《诗》曰：『虽有丝、麻，无弃菅、蒯；虽有姬、姜，无弃蕉萃。凡百君子，莫不代匮。』言备之不可以已也。」
秦人、白狄伐晋，诸侯贰故也。
郑人围许，示晋不急君也。是则公孙申谋之，曰：「我出师以围许，为将改立君者，而纾晋使，晋必归君。」
城中城，书，时也。
十二月，楚子使公子辰如晋，报钟仪之使，请修好结成。', '', '', '九年春季，杞桓公来鲁国迎接叔姬的灵柩，这是由于鲁国的请求。杞叔姬的死，是由于被杞国遗弃的缘故。迎接叔姬的灵柩，是为了我国的颜面。
由于晋国让鲁国把汶阳的土田归还给齐国的缘故，诸侯对晋国有了二心。晋国人畏惧，在蒲地和诸侯会见，重温马陵的盟会。鲁大夫季文子对晋大夫范文子说：“晋国德行已经不强，重温旧盟做什么？”范文子说：“用勤勉来安抚诸侯，用宽厚来对待诸侯，用坚强来驾御诸侯，用盟誓来约束诸侯，笼络顺服的而讨伐有二心的，这也是次等的德行了。”晋国召集的这一次会议，是首次邀请吴国，吴国人没有来。
二月，伯姬出嫁到宋国。
楚国人用很重的礼物求取郑国，郑成公和楚国公子成在邓地相会。
夏季，季文子去到宋国慰问伯姬，回国复命，鲁成公设宴招待他。季文子赋《韩弈》的第五章。穆姜从房里出来，两次下拜，说：“大夫辛勤，不忘记先君以及于嗣君，延及于未亡人，先君也是这样来期望您的。谨拜谢大夫加倍的辛勤。”穆姜又赋《绿衣》的最后一章然后才进去。
晋国人来鲁国送女陪嫁，这是合于礼的。
秋季，郑成公去到晋国，晋国人为了惩罚他倾向楚国，在铜鞮逮住了他。
晋将栾书率兵进攻郑国，郑国人派遣伯蠲求和，晋国人杀死了伯蠲，这是不合于礼的。两国交兵，使者可以来往两国之间。
楚国的子重入侵陈国以救郑国。
晋景公视察军用仓库，见到钟仪，问人说：“戴着南方的帽子而被囚禁的人是谁？”官吏回答说：“是郑国人所献的楚国俘虏。”晋景公让人把他释放出来，召见并且慰问他。钟仪再拜，叩头。晋景公问他在楚国的族人，他回答说：“是乐人。”晋景公说：“能够奏乐吗？”钟仪回答说：“这是先人的职责，岂敢从事于其他工作呢？”晋景公命令把琴给钟仪，他弹奏的是南方乐调。晋景公说：“你们的君王怎样？”钟仪回答说：“这不是小人能知道的。”晋景公再三问他，他回答说：“当他做太子的时候，师保奉事着他，每天早晨向婴齐请教，晚上向侧去请教。我不知道别的事。”晋景公把这些告诉了范文子。文子说：“这个楚囚，是君子啊。说话中举出先人的职官，这是不忘记根本；奏乐奏家乡的乐调，这是不忘记故旧；举出楚君做太子时候的事，这是没有私心；称二卿的名字，这是尊崇君王。不背弃根本，这是仁；不忘记故旧，这是守信；没有私心，这是忠诚；尊崇君王，这是敏达。用仁来办理事情，用信来守护，用忠来成就，用敏来执行。事情虽然大，必然会成功。君王何不放他回去，让他结成晋、楚的友好。”晋景公听从了，对钟仪重加礼遇，让他回国去替晋国求和。
冬季，十一月，楚国子重从陈国进攻莒国，包围了渠丘。渠丘城池破败，大众溃散而逃亡到莒城。初五日，楚国进入渠丘。莒国人抓住了楚国的公子平。楚国人说：“不要杀他，我们归还你们俘虏。”莒国人杀了公子平，楚国的军队包围了莒城。莒城的城墙也不好，十七日，莒国溃败。楚军就进入郓城，这是由于莒国没有防备的缘故。
君子说：“依仗简陋而不设防备，这是罪中的大罪；防备意外，这是善中的大善。莒国依仗它的简陋而不修城郭，十二天之间而楚军攻克它的三个城市，这是由于没有防备的缘故啊！《诗》说：‘虽然有了丝麻，不要丢掉杂草；虽然有了美人儿，不要丢掉不美的。凡是君子们，没有不缺此少彼的时候。’说的就是防备不能停止。”
秦军、白狄进攻晋国，由于诸侯对晋国有了二心的缘故。
郑国人包围许国，这是为了向晋国表示他们并不急于救出郑成公。这是公孙申出的计谋，他说：“我们出兵包围许国，假装打算另立国君的样子，而暂时不派使者去晋国，晋国必然放我们国君回来。”
鲁国在内城筑城，《春秋》记载这件事，因为合于时令。
十二月，楚共王派公子辰去晋国，以回报钟仪的使命，请求重温友好，缔结和约。
', NULL, '', 'indent', 1559038420, '5cec99517b968a0076718c5f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643010, '左传 · 成公 · 成公十年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十年春，卫侯之弟黑背帅师侵郑。夏四月，五卜郊，不从，乃不郊。五月，公会晋侯、齐侯、宋公、卫侯、曹伯伐郑。齐人来媵。丙午，晋侯獳卒。秋七月，公如晋。冬十月。
【传】十年春，晋侯使籴伐如楚，报大宰子商之使也。
卫子叔黑背侵郑，晋命也。
郑公子班闻叔申之谋。三月，子如立公子繻。夏四月，郑人杀繻，立髡顽。子如奔许。栾武子曰：「郑人立君，我执一人焉，何益？不如伐郑而归其君，以求成焉。」晋侯有疾。五月，晋立大子州蒲以为君，而会诸侯伐郑。郑子罕赂以襄钟，子然盟于修泽，子驷为质。辛巳，郑伯归。
晋侯梦大厉，被发及地，搏膺而踊，曰：「杀余孙，不义。余得请于帝矣！」坏大门及寝门而入。公惧，入于室。又坏户。公觉，召桑田巫。巫言如梦。公曰：「何如？曰：「不食新矣。」公疾病，求医于秦。秦伯使医缓为之。未至，公梦疾为二竖子，曰：「彼，良医也。惧伤我，焉逃之？」其一曰：「居肓之上，膏之下，若我何？」医至，曰：「疾不可为也。在肓之上，膏之下，攻之不可，达之不及，药不至焉，不可为也。」公曰：「良医也。」厚为之礼而归之。六月丙午，晋侯欲麦，使甸人献麦，馈人为之。召桑田巫，示而杀之。将食，张，如厕，陷而卒。小臣有晨梦负公以登天，及日中，负晋侯出诸厕，遂以为殉。
郑伯讨立君者，戊申，杀叔申、叔禽。君子曰：「忠为令德，非其人犹不可，况不令乎？」
秋，公如晋。晋人止公，使送葬。于是籴伐未反。
冬，葬晋景公。公送葬，诸侯莫在。鲁人辱之，故不书，讳之也。', '', '', '十年春季，晋景公派遣籴茷去楚国，这是回报太宰子商的出使。
卫国子叔黑背侵袭郑国，这是执行晋国的命令。
郑国的公子班听到了叔申的策划。三月，公子班立公子繻为国君。夏季四月，郑国人杀了公子繻，立了髡顽，公子班逃亡到许国。栾武子说：“郑国人立了国君，我们抓的就是一个普通人，有什么好处？不如进攻郑国，把他们的国君送回国，以此求和。”晋景公有病，五月，晋国立太子州蒲为国君，会合诸侯进攻郑国。郑国的子罕把襄公宗庙中的钟赠送给晋国，子然和诸侯在脩泽结盟，子驷作为人质。十一日，郑成公回国。
晋景公梦见一个厉鬼，披的长发拖到地上，捶胸跳跃，说：“你杀了我的子孙，这是不义。我请求为子孙复仇，已经得到上帝的允许了！”厉鬼毁掉宫门、寝门走了进来。晋景公害怕，躲进内室，厉鬼又毁掉内室的门。晋景公醒来，召见桑田的巫人。巫人所说的和晋景公梦见的情况一样。晋景公说：“怎么样？”巫人说：“君王吃不到新收的麦子了！”晋景公病重，到秦国请医生。秦桓公派医缓给晋景公诊病。医缓还没有到达，晋景公又梦见疾病变成两个小儿童，一个说：“他是个好医生，恐怕会伤害我们，往哪儿逃好？”另一个说：“我们待在肓的上边，膏的下边，拿我们怎么办？”医生来了，说：“病不能治了，病在肓的上边，膏的下边，灸不能用，针达不到，药物的力量也达不到了，不能治了。”晋景公说：“真是好医生啊。”于是馈送给他丰厚的礼物让他回去。六月初六日，晋景公想吃新麦子，让管食物的人献麦，厨师烹煮。景公召见桑田巫人来，把煮好的新麦给他看，然后杀了他。景公将要进食，突然肚子发胀，上厕所，跌进厕所里死去。有一个宦官早晨梦见背着晋景公登天，等到中午，他背着晋景公从厕所出来，于是就以他为景公殉葬了。
郑成公讨伐立国君的人，六月初八日，杀了叔申、叔禽。君子说：“忠诚是美德，所忠的人不合式尚且不可以，何况本人又不好呢？”
秋季，鲁成公到晋国。晋国人留下成公，让他送葬。当时籴茷还没有回来。
冬季，安葬晋景公。鲁成公送葬，诸侯都不在场。鲁国人认为这是耻辱，所以《春秋》不加记载，这是隐讳国耻。', NULL, '', 'indent', 1559038458, '5cec9976d5de2b0070854f67', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643011, '左传 · 成公 · 成公十一年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有一年春王三月，公至自晋。晋侯使郤犨来聘，己丑，及郤犨盟。夏，季孙行父如晋。秋，叔孙侨如如齐。冬十月。
【传】十一年春，王三月，公至自晋。晋人以公为贰于楚，故止公。公请受盟，而后使归。
郤犨来聘，且莅盟。
声伯之母不聘，穆姜曰：「吾不以妾为姒。」生声伯而出之，嫁于齐管于奚。生二子而寡，以归声伯。声伯以其外弟为大夫，而嫁其外妹于施孝叔。郤犨来聘，求妇于声伯。声伯夺施氏妇以与之。妇人曰：「鸟兽犹不失俪，子将若何？」曰：「吾不能死亡。」妇人遂行，生二子于郤氏。郤氏亡，晋人归之施氏，施氏逆诸河，沉其二子。妇人怒曰：「己不能庇其伉俪而亡之，又不能字人之孤而杀之，将何以终？」遂誓施氏。
夏，季文子如晋报聘，且莅盟也。
周公楚恶惠、襄之逼也，且与伯与争政，不胜，怒而出。及阳樊，王使刘子复之，盟于鄄而入。三日，复出奔晋。
秋，宣伯聘于齐，以修前好。
晋郤至与周争鄇田，王命刘康公、单襄公讼诸晋。郤至曰：「温，吾故也，故不敢失。」刘子、单子曰：「昔周克商，使诸侯抚封，苏忿生以温为司寇，与檀伯达封于河。苏氏即狄，又不能于狄而奔卫。襄王劳文公而赐之温，狐氏、阳氏先处之，而后及子。若治其故，则王官之邑也，子安得之？」晋侯使郤至勿敢争。
宋华元善于令尹子重，又善于栾武子。闻楚人既许晋籴伐成，而使归覆命矣。冬，华元如楚，遂如晋，合晋、楚之成。
秦、晋为成，将会于令狐。晋侯先至焉，秦伯不肯涉河，次于王城，使史颗盟晋侯于河东。晋郤犨盟秦伯于河西。范文子曰：「是盟也何益？齐盟，所以质信也。会所，信之始也。始之不从，其何质乎？」秦伯归而背晋成。
', '', '', '十一年，春季，周王朝历法的三月，鲁成公从晋国回来。晋国人认为成公倾向楚国，所以扣留了他。成公请求接受盟约，然后让他回国。
郤犫来鲁国聘问，而且参加结盟。
声伯的母亲没有举行媒聘之礼就和叔肸同居，穆姜说：“我不能把姘妇当成嫂嫂。”声伯的母亲生了声伯，就被遗弃了，嫁给齐国的管于奚，生了两个孩子以后又守寡，就把两个孩子给了声伯。声伯让他的异父兄弟做了大夫，又把异父妹妹嫁给施孝叔。郤犫前来聘问，向声伯求取妻子。声伯把施氏的妻子夺过来给了郤犫。这个女人对丈夫说：“鸟兽还不肯失掉配偶，您打算怎么办？”她的丈夫说：“我不能够因此死去或者逃亡。”这个女人就随郤犫走了。在郤氏那里生了两个孩子，郤氏被灭，晋国人又把她还给施氏。施氏在黄河边迎接她，把她的两个孩子沉进黄河里。这个妇女发怒说：“自己不能保护自己的配偶而让她离开，又不能爱护别人的孤儿而杀死他们，这怎么能有好结果？”就发誓不再做施氏的妻子。
夏季，季文子去到晋国，回报聘问，同时也参加结盟。
周公楚讨厌周惠王、周襄王族人的逼迫，同时又和伯舆争夺政权，没有得胜，就生气而离开。到达阳樊，周简王派刘子让周公楚回来，在鄄地结盟然后进入国内。三天后，周公楚再次离去，逃亡到晋国。
秋季，宣伯到齐国聘问，重修过去的友好。
晋国的郤至和周室争夺鄇地的土地，周简王命令刘康公、单襄公到晋国争讼。郤至说：“温地，过去就是我的封邑，所以不敢丢失。”刘康公、单襄公说：“以前周朝战胜商朝，让诸侯据有封地。苏忿生据有温地，做了司寇，和檀伯达封在黄河边上。苏氏投奔狄人，又和狄人不合式而逃到卫国。襄王为了慰劳文公，将温地赐给了他，狐氏、阳氏先住在这里，然后才轮到您。如果要追查过去的原因，那么它是周天子属官的封邑，您怎么能得到它？”晋厉公下令要郤至不要争夺。
宋国大夫华元和楚令尹子重友好，又和晋大夫栾武子友好，听到楚人已经允许晋国的籴茷求和，而让他回国复命了。冬季，华元到楚国，又到晋国，促成晋、楚的和好。
秦、晋两国和好，准备在令狐会见。晋厉公先到达。秦桓公不肯渡过黄河，住在王城，派遣史颗和晋厉公在河东会盟。晋国的郤犫和秦桓公在河西结盟。范文子说：“这样的结盟有什么好处？斋戒盟誓，是用来表示信用的。约定会见地点，这是信用的开始。开始都不顺从，难道可以相信吗？”秦桓公回去就背弃了和晋国的友好盟约。', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8c03048e64fbda97a7", "shortContent": "本篇写临清县刘伯玉妻段氏因妒洛神之美而投水亦为水神的故事。刘伯玉常于妻前诵曹植名篇《洛神赋》，本可成为闺房雅事，夫妻同赏子建之才和洛神之美，但是，错在夫曰：“娶妇得如此，吾无憾矣。”妻曰：“君何得以水神美而欲轻我？”夫不该在妻前多次赞赏他妇之美，妻也不该于此而莫名生妒。且不去说曹植慕洛神之美，借宓妃而寄托情思，也仅是“超长吟以永慕兮，声哀厉而弥长”，是可思可想而不可望不可即之虚幻之事；“翩若惊鸿，...", "authors": ["李", "晓"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559038498, '5cec999f43e78c0067205ff7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643012, '左传 · 成公 · 成公十二年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有二年春，周公出奔晋。夏，公会晋侯、卫侯于琐泽。秋，晋人败狄于交刚。冬十月。
【传】十二年春，王使以周公之难来告。书曰：「周公出奔晋。」凡自周无出，周公自出故也。
宋华元克合晋、楚之成。夏五月，晋士燮会楚公子罢、许偃。癸亥，盟于宋西门之外，曰：「凡晋、楚无相加戎，好恶同之，同恤菑危，备救凶患。若有害楚，则晋伐之。在晋，楚亦如之。交贽往来，道路无壅，谋其不协，而讨不庭有渝此盟，明神殛之，俾队其师，无克胙国。」郑伯如晋听成，会于琐泽，成故也。
狄人间宋之盟以侵晋，而不设备。秋，晋人败狄于交刚。
晋郤至如楚聘，且莅盟。楚子享之，子反相，为地室而县焉。郤至将登，金奏作于下，惊而走出。子反曰：「日云莫矣，寡君须矣，吾子其入也！」宾曰：「君不忘先君之好，施及下臣，贶之以大礼，重之以备乐。如天之福，两君相见，何以代此。下臣不敢。」子反曰：「如天之福，两君相见，无亦唯是一矢以相加遗，焉用乐？寡君须矣，吾子其入也！」宾曰：「若让之以一矢，祸之大者，其何福之为？世之治也，诸侯间于天子之事，则相朝也，于是乎有享宴之礼。享以训共俭，宴以示慈惠。共俭以行礼，而慈惠以布政。政以礼成，民是以息。百官承事，朝而不夕，此公侯之所以扞城其民也。故《诗》曰：『赳赳武夫，公侯干城。』及其乱也，诸侯贪冒，侵欲不忌，争寻常以尽其民，略其武夫，以为己腹心股肱爪牙。故《诗》曰：『赳赳武夫，公侯腹心。』天下有道，则公侯能为民干城，而制其腹心。乱则反之。今吾子之言，乱之道也，不可以为法。然吾子，主也，至敢不从？」遂入，卒事。归，以语范文子。文子曰：「无礼必食言，吾死无日矣夫！」
冬，楚公子罢如晋聘，且莅盟。十二月，晋侯及楚公子罢盟于赤棘。
', '', '', '十二年春季，周简王的使者来鲁国通告周公楚的祸难事件。《春秋》记载说“周公出奔晋”。凡是从周朝外逃的不能叫做“出”，周公楚自己出逃，所以才用“出”字。
宋国华元完成了晋、楚两国的和好。夏季，五月，晋国士燮会见楚国公子罢、许偃。初四日，在宋国西门之外结盟，说：“凡是晋、楚两国，不要互相以兵戎相见，要好恶相同，一起救济灾难危亡，救援饥荒祸患。如果有危害楚国的，晋国就攻打它；对晋国，楚国也是这样做。两国使者往来，道路不要阻塞，协商不和，讨伐背叛。谁要违背盟约，神灵就要诛杀，使他军队颠覆，不能保佑国家。”郑成公去到晋国听受和约，和诸侯在琐泽会见，这是由于晋、楚和好的缘故。
狄人乘宋国促成的结盟会这一空隙攻打晋国，但又不设防备。秋季，晋国人在交刚打败了狄人。
晋国郤至到楚国聘问，同时参加盟约。楚共王设享礼招待他，子反作为相礼者，在地下室悬挂乐器。郤至将要登堂，下面击钟又击鼓，惊慌地退了出来。子反说：“时间不早了，寡君等着呢，您还是进去吧！”客人说：“贵国君王不忘记先君的友好，加之于下臣，赐给下臣以重大的礼仪，又加上钟鼓音乐，如果上天降福，两国国君相见，还能用什么礼节来代替这个呢？下臣不敢当。”子反说：“如果上天降福，两国国君相见，也只能用一支箭彼此相赠，哪里还用奏乐？寡君等着呢，您还是进去吧！”客人说：“如果用一支箭来款待，这是祸中的大祸，还有什么福可说？当天下大治的时候，诸侯在完成天子使命的闲暇之时，就互相朝见，在这时就有享、宴的礼仪。享礼用来教导恭敬节俭，宴礼用来表示慈爱恩惠。恭敬节俭用来推行礼仪，而慈爱恩惠则用来施行政教。政教用礼仪来完成，百姓因此得到休息。百官承受政事，白天朝见晚上就不再朝见，这就是公侯所用来捍卫他们百姓的措施，所以《诗》说：‘雄赳赳的武士，是公侯的捍卫。’等到它动乱的时候，诸侯贪婪，侵占欲望已无所顾忌，为争夺尺寸之地而驱使百姓致于死亡，收取他的武士，作为自己的心腹、股肱、爪牙。所以《诗》说：‘雄赳赳的武士，是公侯的心腹。’天下有道，那么公侯就能做百姓的捍卫，而控制他的心腹。动乱时，就反过来。现在您的话，是动乱之道，不能用来作为法则。然而您，是主人，至岂敢不听从？”于是就进去，把事情办完。郤至回去把情况告诉范文子。文子说：“无礼，必然说话不算话，我们离开死日不远了。”
冬季，楚国公子罢去到晋国聘问，同时参加结盟，十二月，晋厉公和楚公子罢在赤棘结盟。', NULL, '', 'indent', 1559038536, '5cec99c57b968a0076718f70', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643013, '左传 · 成公 · 成公十三年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有三年春，晋侯使郤錡来乞师。三月，公如京师。夏五月，公自京师，遂会晋侯、齐侯、宋公、卫侯、郑伯、曹伯、邾人、滕人伐秦。曹伯卢卒于师。秋七月，公至自伐秦。冬，葬曹宣公。
【传】十三年春，晋侯使郤錡来乞师，将事不敬。孟献子曰：「郤氏其亡乎！礼，身之干也。敬，身之基也。郤子无基。且先君之嗣卿也，受命以求师，将社稷是卫，而惰，弃君命也。不亡何为？」
三月，公如京师。宣伯欲赐，请先使，王以行人之礼礼焉。孟献子从。王以为介，而重贿之。
公及诸侯朝王，遂从刘康公、成肃公会晋侯伐秦。成子受脤于社，不敬。刘子曰：「吾闻之，民受天地之中以生，所谓命也。是以有动作礼义威仪之则，以定命也。能者养以之福，不能者败以取祸。是故君子勤礼，小人尽力，勤礼莫如致敬，尽力莫如敦笃。敬在养神，笃在守业。国之大事，在祀与戎，祀有执膰，戎有受脤，神之大节也。今成子惰，弃其命矣，其不反乎？」
夏四月戊午，晋侯使吕相绝秦，曰：「昔逮我献公，及穆公相好，戮力同心，申之以盟誓，重之以昏姻。天祸晋国，文公如齐，惠公如秦。无禄，献公即世，穆公不忘旧德，俾我惠公用能奉祀于晋。又不能成大勋，而为韩之师。亦悔于厥心，用集我文公，是穆之成也。文公躬擐甲胄，跋履山川，逾越险阻，征东之诸侯，虞、夏、商、周之胤，而朝诸秦，则亦既报旧德矣。郑人怒君之疆埸，我文公帅诸侯及秦围郑。秦大夫不询于我寡君，擅及郑盟。诸侯疾之，将致命于秦。文公恐惧，绥静诸侯，秦师克还无害，则是我有大造于西也。无禄，文公即世，穆为不吊，蔑死我君，寡我襄公，迭我淆地，奸绝我好，伐我保城，殄灭我费滑，散离我兄弟，挠乱我同盟，倾覆我国家。我襄公未忘君之旧勋，而惧社稷之陨，是以有淆之师。犹愿赦罪于穆公，穆公弗听，而即楚谋我。天诱其衷，成王殒命，穆公是以不克逞志于我。穆、襄即世，康、灵即位。康公，我之自出，又欲阙剪我公室，倾覆我社稷，帅我蝥贼，以来荡摇我边疆。我是以有令狐之役。康犹不悛，入我河曲，伐我涷川，俘我王官，剪我羁马，我是以有河曲之战。东道之不通，则是康公绝我好也。
及君之嗣也，我君景公引领西望曰：『庶抚我乎！』君亦不惠称盟，利吾有狄难，入我河县，焚我箕、郜，芟夷我农功，虔刘我边陲。我是以有辅氏之聚。「君亦悔祸之延，而欲徼福于先君献、穆，使伯车来，命我景公曰：『吾与女同好弃恶，复修旧德，以追念前勋，』言誓未就，景公即世，我寡君是以有令狐之会。君又不祥，背弃盟誓。白狄及君同州，君之仇仇，而我之昏姻也。君来赐命曰：『吾与女伐狄。』寡君不敢顾昏姻，畏君之威，而受命于吏。君有二心于狄，曰：『晋将伐女。』狄应且憎，是用告我。楚人恶君之二三其德也，亦来告我曰：『秦背令狐之盟，而来求盟于我：「昭告昊天上帝、秦三公、楚三王曰：『余虽与晋出入，余唯利是视。』不谷恶其无成德，是用宣之，以惩不壹。」诸侯备闻此言，斯是用痛心疾首，昵就寡人。寡人帅以听命，唯好是求。君若惠顾诸侯，矜哀寡人，而赐之盟，则寡人之愿也。其承宁诸侯以退，岂敢徼乱。君若不施大惠，寡人不佞，其不能以诸侯退矣。敢尽布之执事，俾执事实图利之！」
秦桓公既与晋厉公为令狐之盟，而又召狄与楚，欲道以伐晋，诸侯是以睦于晋。晋栾书将中军，荀庚佐之。士燮将上军，郤錡佐之。韩厥将下军，荀罃佐之。赵旃将新军，郤至佐之。郤毅御戎，栾金咸为右。孟献子曰：「晋帅乘和，师必有大功。」五月丁亥，晋师以诸侯之师及秦师战于麻隧。秦师败绩，获秦成差及不更女父。曹宣公卒于师。师遂济泾，及侯丽而还。迓晋侯于新楚。
成肃公卒于瑕。
六月丁卯夜，郑公子班自訾求入于大宫，不能，杀子印、子羽。反军于市，己巳，予驷帅国人盟于大宫，遂从而尽焚之，杀子如、子□龙、孙叔、孙知。
曹人使公子负刍守，使公子欣时逆曹伯之丧。秋，负刍杀其大子而自立也。诸侯乃请讨之，晋人以其役之劳，请俟他年。冬，葬曹宣公。既葬，子臧将亡，国人皆将从之。成公乃惧，告罪，且请焉，乃反，而致其邑。
', '', '', '十三年春季，晋厉公派遣郤犫来鲁国请求援兵，处理事情态度不严肃。孟献子说：“郤氏恐怕要灭亡了吧！礼仪，是身体的躯干；恭敬，是身体的基础。郤子却没有基础。而且作为先君的嗣卿，接受命令而来请求出兵，想保卫国家，但却怠惰，这是不顾国君的命令，不灭亡还做什么？”
三月，鲁成公到京师。宣伯想要得到赏赐，请求先行出使。周简王用对普通外交官的礼仪来接待他。孟献子跟从成公，周简王把他作为成公的第一位外交官，而重重地赠给他财礼。
成公和诸侯朝觐周简王，接着就跟从刘康公、成肃公会合晋厉公进攻秦国。成肃公在社神庙接受祭肉的时候，不恭敬。刘康公说：“我听说：百姓得到天地的中和之气而降生，这就是所谓生命。因此就有动作、礼义、威仪的准则，用来固定天命。有能力的人保持这些可以得福，没有能力的人败坏这些足以取祸。所以君子勤于礼法，小人竭尽力量。勤于礼法莫过于恭敬，竭尽力量莫过于敦厚笃实。恭敬在于供奉神灵，笃实在于各安本分。国家的大事情，在于祭祀和战争。祭祀有分祭肉之礼，战争有受祭肉之礼，这是和神灵交往的大节。现在成子表现出懒惰不恭，丢弃天命了，恐怕回不来了吧！”
夏季，四月初五日，晋厉公派遣吕相去和秦国断绝外交关系，说：
从前我先君晋献公和贵国先君秦穆公互相友好，合力同心，用盟誓来表明，再用婚姻加深两国关系。上天降祸于晋国，文公到了齐国，惠公到了秦国。不幸，献公去世。穆公不忘记过去的恩德，使我们惠公因此能在晋国主持祭祀，但又不能完成重大的勋劳，却和我国有了韩地之战。后来心里又有些懊悔，因此成就了我们文公回国为君，这都是秦穆公的功劳。文公亲自身披甲胄，登山涉水，经历艰难险阻，征服东方的诸侯，虞、夏、商、周的后代都向秦国朝见，也就已经报答过去的恩德了。郑国人侵犯君王的边界，我们文公率领诸侯和秦国共同包围郑国，秦国的大夫不和我们国君商量，擅自和郑国订立了盟约。诸侯痛恨这件事，打算和秦国拚命，文公恐惧，安抚诸侯，使秦军得以平安回国而没有受到损害，这就是我国有大功劳于西方秦国之处。
“不幸，文公去世，穆公不善，蔑视我们故去的国君，以我们晋襄公为软弱可欺，突然侵犯我们的殽地，断绝我们同友好国家的往来，攻打我们的城堡，绝灭我们的滑国，离散我们的兄弟之邦，扰乱我们的同盟之国，颠覆我们的国家。我们襄公没有忘记君王过去的勋劳，而又害怕国家的颠覆，这样才有殽地的这一战役，但还是愿意在穆公那里解释以求赦免罪过。穆公不听，反而亲近楚国来谋害我们。天意保佑我国，楚成王丧命，穆公因此不能在我国称心如意。穆公、襄公去世，康公、灵公即位。康公，是我国穆姬所生的，但又想损害我们的公室，颠覆我们的国家，率领我国的内奸，以动摇我们的边疆，因此我国才有了令狐这一战役。秦康公还是不肯改悔，又进入我国河曲，攻打我国涑川，掠取我国王官，割断我国的羁马，因此我国才有了河曲这一战役。东边的道路不通，那是由于康公同我们断绝友好所造成的。
“等到君王继位以后，我们的国君晋景公伸着脖子望着西边说：‘也许要安抚我们了吧！’但君王也不考虑和我们结盟，却利用我国有狄人的祸难，侵入我国的河县，焚烧我国的箕地、郜地，抢割我国的庄稼，骚扰我国边境，我国因此而有辅氏的战役。君王也后悔战祸的蔓延，而想求福于先君晋献公和秦穆公，派遣伯车前来命令我们景公说：‘我跟你重修旧好、丢弃怨恨，恢复以往的关系，以追念以前的勋劳。’盟誓还没有完成，我晋景公就去世了，因此我们国君才和秦国有令狐的会见。君王又不善，背弃了盟誓。白狄和君王同在雍州境内，他们是君王的仇敌，却是我们的亲戚。君王前来命令说：‘我跟你攻打狄人。’寡君不敢顾及亲戚，畏惧君王的威严，就给官吏下令攻打狄人。但君王又对狄人有了别的念头，告诉他们说：‘晋国将要攻打你们。’对君王的做法，狄人接受而又厌恶，因此就告诉了我们。楚国人讨厌君王的反复无常，也来告诉我们说：‘秦国背弃了令狐的盟约，而来向我国请求结盟：‘对着皇天上帝、秦国的三位先公、楚国的三位先王发誓：我虽然和晋国有往来，我只是唯利是图。’楚国人讨厌秦君反复无常，因此把事情公布出来，以惩戒言行不一的人。’”
秦桓公已经和晋厉公在令狐结盟，而又召来狄人和楚人，要引导他们进攻晋国，诸侯因此跟晋国和睦。晋国的栾书率领中军，荀庚作为辅佐；士燮率领上军，郤锜作为辅佐；韩厥率领下军，荀罃作为辅佐；赵旃率领新军，郤至作为辅佐。郤毅驾御战车，栾鍼作为车右。孟献子说：“晋国的将领和甲士上下一致，军队必然建立大功。”五月初四日，晋军率领诸侯的军队和秦军在麻隧作战。秦军大败，俘虏了秦国的成差和不更女父。曹宣公死在军中。军队就渡过泾水，到达侯丽然后回去。军队在新楚迎接晋厉公。
成肃公死在瑕地。
六月十五日夜里，郑国公子班从訾地请求进入祖庙，没有做到，就杀了子印、子羽，回来驻扎在市上。十七日，子驷率领国内的人们在祖庙结盟，跟着就全部烧了它，杀了公子班、子駹、孙叔、孙知。
曹国人派公子负刍留守，派公子欣时去迎接曹宣公尸体。秋季，公子负刍杀了曹宣公的太子而自立为国君，诸侯就请求讨伐他。晋国人由于他在和秦国作战中有功劳，请求等到以后再讨伐。冬季，安葬曹宣公。安葬以后，子臧准备逃亡，国内的人都要跟着他逃亡。曹成公负刍才感到恐惧，承认罪过，而且请求子臧留下来不要出走。子臧这才返回来，然后把采邑还给曹成公。', NULL, '', 'indent', 1559038579, '5cec99f0d5de2b0070855458', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643041, '左传 · 襄公 · 襄公二十三年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有三年春王二月癸酉朔，日有食之。三月己巳，杞伯□卒。夏，邾畀我来奔。葬杞孝公。陈杀其大夫庆虎及庆寅。陈侯之弟黄自楚归于陈。晋栾盈复入于晋，入于曲沃。秋，齐侯伐卫，遂伐晋。八月，叔孙豹帅师救晋次于雍榆。己卯，仲孙速卒。冬十月乙亥，臧孙纥出奔邾。晋人杀栾盈。齐侯袭莒。
【传】二十三年春，杞孝公卒，晋悼夫人丧之。平公不彻乐，非礼也。礼，为邻国阙。
陈侯如楚。公子黄愬二庆于楚，楚人召之。使庆乐往，杀之。庆氏以陈叛。夏，屈建从陈侯围陈。陈人城，板队而杀人。役人相命，各杀其长。遂杀庆虎、庆寅。楚人纳公子黄。君子谓：「庆氏不义，不可肆也。故《书》曰：『惟命不于常。』」
晋将嫁女于吴，齐侯使析归父媵之，以藩载栾盈及其士，纳诸曲沃。栾盈夜见胥午而告之。对曰：「不可。天之所废，谁能兴之？子必不免。吾非爱死也，知不集也。」盈曰：「虽然，因子而死，吾无悔矣。我实不天，子无咎焉。」许诺。伏之，而觞曲沃人。乐作。午言曰：「今也得栾孺子，何如？」对曰：「得主而为之死，犹不死也。」皆叹，有泣者。爵行，又言。皆曰：「得主，何贰之有？」盈出，遍拜之。
四月，栾盈帅曲沃之甲，因魏献子，以昼入绛。初，栾盈佐魏庄子于下军，献子私焉，故因之。赵氏以原、屏之难怨栾氏，韩、赵方睦。中行氏以伐秦之役怨栾氏，而固与范氏和亲。知悼子少，而听于中行氏。程郑嬖于公。唯魏氏及七舆大夫与之。
乐王鲋待坐于范宣子。或告曰：「栾氏至矣！」宣子惧。桓子曰：「奉君以走固宫，必无害也。且栾氏多怨，子为政，栾氏自外，子在位，其利多矣。既有利权，又执民柄，将何惧焉？栾氏所得，其唯魏氏乎！而可强取也。夫克乱在权，子无懈矣。」公有姻丧，王鲋使宣子墨縗冒絰，二妇人辇以如公，奉公以如固宫。
范鞅逆魏舒，则成列既乘，将逆栾氏矣。趋进，曰：「栾氏帅贼以入，鞅之父与二三子在君所矣。使鞅逆吾子。鞅请骖乘。」持带，遂超乘，右抚剑，左援带，命驱之出。仆请，鞅曰：「之公。」宣子逆诸阶，执其手，赂之以曲沃。
初，斐豹隶也，着于丹书。栾氏之力臣曰督戎，国人惧之。斐豹谓宣子曰：「苟焚丹书，我杀督戎。」宣子喜，曰：「而杀之，所不请于君焚丹书者，有如日！」乃出豹而闭之，督戎从之。逾隐而待之，督戎逾入，豹自后击而杀之。范氏之徒在台后，栾氏乘公门。宣子谓鞅曰：「矢及君屋，死之！」鞅用剑以帅卒，栾氏退。摄车从之，遇栾氏，曰：「乐免之，死将讼女于天。」乐射之，不中；又注，则乘槐本而覆。或以戟钩之，断肘而死。栾鲂伤。栾盈奔曲沃，晋人围之。
秋，齐侯伐卫。先驱，谷荣御王孙挥，召扬为右。申驱，成秩御莒恒，申鲜虞之傅挚为右。曹开御戎，晏父戎为右。贰广，上之登御邢公，卢蒲癸为右。启，牢成御襄罢师，狼蘧疏为右。胠，商子车御侯朝，桓跳为右。大殿，商子游御夏之御寇，崔如为右，烛庸之越驷乘。
自卫将遂伐晋。晏平仲曰：「君恃勇力以伐盟主，若不济，国之福也。不德而有功，忧必及君。」崔杼谏曰：「不可。臣闻之，小国间大国之败而毁焉，必受其咎。君其图之！」弗听。陈文子见崔武子，曰：「将如君何？」武子曰：「吾言于君，君弗听也。以为盟主，而利其难。群臣若急，君于何有？子姑止之。」文子退，告其人曰：「崔子将死乎！谓君甚，而又过之，不得其死。过君以义，犹自抑也，况以恶乎？」
齐侯遂伐晋，取朝歌，为二队，入孟门，登大行，张武军于荧庭，戍郫邵，封少水，以报平阴之役，乃还。赵胜帅东阳之师以追之，获晏□。八月，叔孙豹帅师救晋，次于雍榆，礼也。
季武子无适子，公弥长，而爱悼子，欲立之。访于申丰，曰：「弥与纥，吾皆爱之，欲择才焉而立之。」申丰趋退，归，尽室将行。他日，又访焉，对曰：「其然，将具敝车而行。」乃止。访于臧纥，臧纥曰：「饮我酒，吾为子立之。」季氏饮大夫酒，臧纥为客。既献，臧孙命北面重席，新尊絜之。召悼之，降，逆之。大夫皆起。及旅，而召公锄，使与之齿，季孙失色。
季氏以公锄为马正，愠而不出。闵子马见之，曰：「子无然！祸福无门，唯人所召。为人子者，患不孝，不患无所。敬共父命，何常之有？若能孝敬，富倍季氏可也。奸回不轨，祸倍下民可也。」公锄然之。敬共朝夕，恪居官次。季孙喜，使饮己酒，而以具往，尽舍旃。故公锄氏富，又出为公左宰。
孟孙恶臧孙，季孙爱之。孟氏之御驺丰点好羯也，曰：「从余言，必为孟孙。」再三云，羯从之。孟庄子疾，丰点谓公锄：「苟立羯，请仇臧氏。」公锄谓季孙曰：「孺子秩，固其所也。若羯立，则季氏信有力于臧氏矣。」弗应。己卯，孟孙卒，公锄奉羯立于户侧。季孙至，入，哭，而出，曰：「秩焉在？」公锄曰：「羯在此矣！」季孙曰：「孺子长。」公锄曰：「何长之有？唯其才也。且夫子之命也。」遂立羯。秩奔邾。
臧孙入，哭甚哀，多涕。出，其御曰：「孟孙之恶子也，而哀如是。季孙若死，其若之何？」臧孙曰：「季孙之爱我，疾疢也。孟孙之恶我，药石也。美疢不如恶石。夫石犹生我，疢之美，其毒滋多。孟孙死，吾亡无日矣。」
孟氏闭门，告于季秋曰：「臧氏将为乱，不使我葬。」季孙不信。臧孙闻之，戒。冬十月，孟氏将辟，藉除于臧氏。臧孙使正夫助之，除于东门，甲从己而视之。孟氏又告季孙。季孙怒，命攻臧氏。乙亥，臧纥斩鹿门之关以出，奔邾。
初，臧宣叔娶于铸，生贾及为而死。继室以其侄，穆姜之姨子也。生纥，长于公宫。姜氏爱之，故立之。臧贾、臧为出在铸。臧武仲自邾使告臧贾，且致大蔡焉，曰：「纥不佞，失守宗祧，敢告不吊。纥之罪，不及不祀。子以大蔡纳请，其可。」贾曰：「是家之祸也，非子之过也。贾闻命矣。」再拜受龟。使为以纳请，遂自为也。臧孙如防，使来告曰：「纥非能害也，知不足也。非敢私请！苟守先祀，无废二勋，敢不辟邑。」乃立臧为。臧纥致防而奔齐。其人曰：「其盟我乎？」臧孙曰：「无辞。」将盟臧氏，季孙召外史掌恶臣，而问盟首焉，对曰：「盟东门氏也，曰：『毋或如东门遂，不听公命，杀适立庶。』盟叔孙氏也，曰：『毋或如叔孙侨如，欲废国常，荡覆公室。』」季孙曰：「臧孙之罪，皆不及此。」孟椒曰：「盍以其犯门斩关？」季孙用之。乃盟臧氏曰：「无或如臧孙纥，干国之纪，犯门斩关。」臧孙闻之，曰：「国有人焉！谁居？其孟椒乎！」
晋人克栾盈于曲沃，尽杀栾氏之族党。栾鲂出奔宋。书曰：「晋人杀栾盈。」不言大夫，言自外也。
齐侯还自晋，不入。遂袭莒，门于且于，伤股而退。明日，将复战，期于寿舒。杞殖、华还载甲，夜入且于之隧，宿于莒郊。明日，先遇莒子于蒲侯氏。莒子重赂之，使无死，曰：「请有盟。」华周对曰：「贪货弃命，亦君所恶也。昏而受命，日未中而弃之，何以事君？」莒子亲鼓之，从而伐之，获杞梁。莒人行成。
齐侯归，遇杞梁之妻于郊，使吊之。辞曰：「殖之有罪，何辱命焉？若免于罪，犹有先人之敝庐在，下妾不得与郊吊。」齐侯吊诸其室。
齐侯将为臧纥田。臧孙闻之，见齐侯，与之言伐晋，对曰：「多则多矣！抑君似鼠。夫鼠昼伏夜动，不穴于寝庙，畏人故也。今君闻晋之乱而后作焉。宁将事之，非鼠如何？」乃弗与田。
仲尼曰：「知之难也。有臧武仲之知，而不容于鲁国，抑有由也。作不顺而施不恕也。《夏书》曰：『念兹在兹。』顺事、恕施也。」', '', '', '二十三年春季，杞孝公死去，晋悼夫人为他服丧。晋平公不撤除音乐，这是不合于礼的。按照礼，应该为邻国的丧事撤除音乐。
陈哀公到达楚国，公子黄在楚国对二庆提出控诉，楚国人召见二庆，二庆让庆乐前往，楚国人杀了庆乐。庆氏带领陈国背叛楚国。夏季，屈建跟从陈哀公包围陈国。陈国人筑城，夹板掉下来，庆氏就杀死了筑城人。筑城的人互相传令，各自杀死他们的工头，于是乘机杀死了庆虎、庆寅。楚国人把公子黄送回陈国。君子认为：“庆氏行动不合于道义，就不能放肆。所以《书》说：‘天命不能常在。’”
晋国将要把女儿嫁给吴国，齐庄公让析归父致送妾媵，用篷车装着栾盈和他的士，把他安置在曲沃。栾盈夜里进见胥午并把情况告诉他。胥午回答说：“不能那么做。上天所废弃的，谁能够把他兴起？您必然不免于死。我不是爱惜一死，明知事情是不能成功的。”栾盈说：“尽管这样，依靠您而死去，我不后悔。我确实不为上天保佑，您没有过错。”胥午答应了。把栾盈藏起来以后就请曲沃人喝酒，音乐开始演奏，胥午发话说：“现在要是找到栾孺子，怎么办？”人们回答说：“找到了主人而为他死，虽死犹生。”大家都叹息，还有哭泣的。举杯，胥午又说栾盈回来的话。大家都说：“找到了主人，还有什么二心的！”栾盈走出来，对大家一一拜谢。
四月，栾盈率领曲沃的甲兵，靠着魏献子，在白天进入绛地。当初，栾盈在下军中辅佐魏庄子，魏献子和他私下里很要好，所以依靠他。赵氏由于原、屏的祸难怨恨栾氏，韩氏、赵氏刚刚和睦。中行氏由于攻打秦国的那次战役怨恨栾氏，本来和范宣子亲近。知悼子年纪小，因此听从中行氏的话。程郑受到晋平公的宠信。只有魏氏和七舆大夫帮助栾氏。
乐王鲋陪侍在范宣子旁边。有人报告说：“栾氏来了。”宣子恐惧。乐王鲋说：“奉事国君逃到固宫，一定没有危害。而栾氏怨敌很多，您主持国政，栾氏从外边来的，您处在掌权的地位，这有利的条件就多了。既然有利有权，又掌握着对百姓的赏罚，还害怕什么？栾氏所得到的，不就仅仅魏氏吗！而且魏氏是可以用强力争取过来的。平定叛乱在于有权力，您不要懈怠！”
晋平公有亲戚的丧事，乐王鲋让范宣子穿着黑色的丧服，和两个女人坐上手拉车去到晋平公那里，陪侍晋平公去到固宫。范鞅去迎接魏献子，魏献子的军队已经排成行列、登上战车，准备去迎接栾氏了。范鞅快步走进，说：“栾氏率领叛乱分子进入国都，鞅的父亲和几位大夫都在国君那里，派鞅来迎接您，鞅请求在车上作为骖乘。”拉着带子，就跳上魏献子的战车。范鞅右手摸着剑，左手拉着带子，下令驱车离开行列。驾车的人请问到哪里去，范鞅说：“到国君那里。”范宣子在阶前迎接魏献子，拉着他的手，答应把曲沃送给他。
当初，斐豹是一个奴隶，用红字记载在竹简上，栾氏有一个大力士叫督戎，国内的人们都害怕他。斐豹对范宣子说：“如果烧掉这竹简，我去杀死督戎。”范宣子很高兴，说：“你杀了他，如果不请求国君烧掉这竹简，太阳可作明证！”于是就让斐豹出宫门，然后关上宫门，督戎跟上他。斐豹翻进矮墙等着督戎，督戎翻进墙来，斐豹从后面猛击而杀死了他。
范氏的手下人在公台的后面，栾氏登上宫门。范宣子对范鞅说：“箭要射到国君的屋子，你就死去！”范鞅用剑带领步兵迎战，栾氏败退，范鞅跳上战车追击，遇到栾乐，范鞅说：“乐，别打了，我死了将会向上天控告你。”栾乐用箭射他，没有射中，又把箭搭上弓弦，车轮碰上槐树根而翻了车。有人用戟钩打他，把他的手臂打断，他就死了。栾鲂受伤。栾盈逃到曲沃，晋国人包围了他。
秋季，齐庄公发兵攻打卫国。第一前锋，穀荣驾御王孙挥的战车，召扬作为车右。第二前锋，成秩驾御莒恒的战车，申鲜虞的儿子傅挚作为车右。曹开驾御齐庄公的战车，晏父戎作为车右。齐庄公的副车，上之登驾御邢公的战车，卢蒲癸作为车右，左翼部队，牢成驾御襄罢师的战车，狼蘧疏作为车右。右翼部队，商子车驾御侯朝的战车，桓跳作为车右。后军，商子游驾御夏之御寇的战车，崔如作为车右，烛庸之越等四人共乘一辆车殿后。
从卫国出发并将由此进攻晋国。晏平仲说：“君王依靠勇力，来进攻盟主。如果不成功，这是国家的福气。没有德行而有功劳，忧患必然会降到君王身上。”崔杼劝谏说：“不行。下臣听说：‘小国钻了大国败坏的空子而加之以武力，一定要受到灾祸。’君王还是考虑一下。”齐庄公不听。陈文子进见崔杼，说：“打算把国君怎么办？”崔杼说：“我对国君说了，国君不听。把晋国奉为盟主，反而以它的祸难为利。下臣们如果急了，哪里还能顾及国君？您暂且不用管了。”陈文子退出，告诉他的手下人说：“崔子将要死了吧！指责国君太狠而所作所为又超过国君所为，会得不到善终的。用道义超过国君，还需要自己抑制，何况自己将作恶呢？”
齐庄公因此而进攻晋国，占取朝歌。兵分两路，一路进入孟门，一路上太行山口，在荧庭建筑纪念物，派人戍守郫邵，在少水收集晋军尸体合于一坑筑成大坟，以报复平阴那次战役，这才收兵回去，赵胜领着东阳的军队追赶上，俘虏了晏氂。八月，叔孙豹领兵救援晋国，驻扎在雍榆，这是合于礼的。
季武子没有嫡子，公弥年长，但是季武子喜欢悼子，想立他为继承人。向申丰说：“弥和纥，我都喜欢，想要选择有才能的立为继承人。”申丰快步走出，回家，打算全家出走。过了几天，季武子又问申丰。申丰回答说：“如果这样，我准备套上我的车走了。”季武子就不说了。季武子又去问臧纥。臧纥说：“招待我喝酒，我为您立他。”季氏招待大夫们喝酒，臧纥是上宾。向宾客献酒完毕，臧纥命令朝北铺上两层席子，换上洗净的酒杯，召见悼子，走下台阶迎接他。大夫们都站起来，等到宾主互相敬酒酬答以后，才召见公锄，让他和别人按年龄大小排列座位。季武子感到突然，脸上都变了颜色。
季氏让公锄担任马正，公锄怨恨，不肯做。闵子马见到公锄，说：“您不要这样，祸和福没有门，在于人们所召唤。做儿子的，只怕不孝，而不怕没有地位。恭敬地对待父亲的命令，难道会没有变化吗？如果能够孝顺恭敬，富有可以比季氏增加一倍。邪乱不合法度，祸患可以比老百姓增加一倍。”公锄同意他的话，就恭敬地早晚问父亲安，谨慎地执行任务。季武子高兴了，让他招待自己喝酒，而带着饮宴的器具前往，季氏把器具全部留下给他，公锄氏因此致富。又做了鲁襄公的左宰。
孟庄子讨厌臧孙，但季武子喜欢他。孟氏的车马官丰点，喜欢羯，说：“听从我的话，你一定成为孟氏的继承人。”再三地说，羯就听从了他。孟庄子生病，丰点对公锄说：“如果立了羯，就是报复了臧氏。”公锄对季武子说：“孺子秩本来应当做孟氏的继承人。如果羯能够改立为继承人，那么季氏就确实比臧氏有力量了。”季武子不答应。八月初十日，孟孙死了。公锄奉事羯立在门边接受宾客来吊唁。季武子来到，进门就哭，出门，说：“秩在哪里？”公锄说：“羯在这里了。”季孙说：“孺子年长。”公锄说：“有什么年长不年长？只要他有才能，而且是他老人家的命令。”就立了羯。秩逃亡到邾国。
臧孙进门也哭，很哀痛的样子，眼泪很多。出门，他的御者说：“孟庄子讨厌您，而您却悲哀成这个样子。季武子如果死了，您怎么办？”臧孙说：“季武子喜欢我，这是没有痛苦的疾病。孟庄子讨厌我，这是治疾病的药石。没有痛苦的疾病不如使人痛苦的药石。药石还可以让我活下去，疾病没有痛苦，它的毒害太多。孟庄子死了，我的灭亡也没有多少日子了。”
孟氏关起大门，告诉季武子说：“臧氏准备发动变乱，不让我家安葬。”季武子不相信。臧孙听到了，实行戒备。冬季，十月，孟氏准备挖开墓道，在臧氏那里借用役夫。臧孙让正夫去帮忙，在东门挖掘墓道，让甲士跟随着自己前去视察。孟氏又告诉季武子。季武子生气，命令进攻臧氏。十月初七日，臧孙砍断鹿门的门栓逃亡到邾国。
当初，臧宣叔在铸国娶妻，她生了臧贾和臧为就死了。臧宣叔以妻子的侄女作为继室，就是穆姜妹妹的女儿，生了纥，长在鲁公的宫中。穆姜喜欢他，所以立为臧宣叔的继承人。臧贾、臧为离开家住在铸国。臧孙从邾国派人告诉臧贾，同时送去大龟说：“纥没有才能，不能祭祀宗庙，谨向您报告不善。纥的罪过不至于断绝后代，您把大龟进献而请求立为我家的继承人，看是否可行。”臧贾说：“这是家里的灾祸，不是您的过错，贾听到命令了。”再拜，接受了大龟，让臧为去代他进献大龟并请求，臧为却请求立自己为继承人。臧纥去到防地，派人来报告说：“纥并不能伤害别人，而是由于智谋不足的缘故。纥并不敢为个人请求。如果保存先人的祭祀，不废掉两位先人的勋劳，岂敢不离开防地？”于是就立了臧为。臧纥献出了防地而逃亡到齐国。他的手下人说：“他们能为我们盟誓吗？”臧纥说：“不好写盟辞。”打算为臧氏盟誓。季武子召见掌管逃亡臣子的外史而询问盟辞的写法。外史回答说：“为东门氏盟誓，说：‘不要有人像东门遂那样，不听国君的命令，杀嫡子、立庶子。’为叔孙氏盟誓，说‘不要有人像叔孙侨如那样，想要废弃国家的常道，颠覆公室！”季武子说：“臧纥的罪过都不至于此。”孟椒说：“何不把他攻砍城门栓写进盟辞？”季武子采用，就和臧氏盟誓，说：“不要像臧孙纥那样触犯国家的法纪，进城门砍门栓！”臧纥听到了，说：“国内有人才啊！是谁呀？恐怕是孟椒吧！”
晋国人在曲沃战胜栾盈，把栾氏的亲族全部杀完。栾鲂逃亡到宋国。《春秋》记载说“晋人杀栾盈”，不说大夫，这是说他从国外进入国内发动叛乱。
齐庄公从晋国回来，不进入国都，就袭击莒国，攻打且于，大腿受伤而退却。第二天，准备再战，约定军队在寿舒集中。杞梁、华还用战车装载甲士夜里进入且于的狭路，宿在莒国郊外。第二天，先和莒子在蒲侯氏相遇。莒子赠给他们以重礼，让他们不要死，说：“请和你们结盟。”华还回答说：“贪得财货丢弃命令，这也是君王所厌恶的。昨天晚上接受命令，今天太阳没有正午就丢掉，还用什么事奉君王？”莒子亲自击鼓，追击齐军，杀死了杞梁。莒国人就和齐国讲和。
齐庄公回国以后，在郊外遇到杞梁的妻子，派人向他吊唁，她辞谢说：“杞梁有罪，岂敢劳动国君派人吊唁？如果能够免罪，还有先人的破屋在那里，下妾不能在郊外接受吊唁。”于是齐庄公又到杞梁家去吊唁。
齐庄公准备封给臧纥土地。臧纥听说了，来见齐庄公。齐庄公对他说起进攻晋国的事，他回答说：“功劳太多了，可是君王却像老鼠，白天藏起来，夜里出动，不在宗庙里打洞，这是由于怕人的缘故。现在君王听说晋国有了动乱然后出兵，一旦晋国安宁又准备事奉晋国，这不是老鼠又是什么？”齐庄公听了就不赏赐臧纥田地了。
孔子说：“聪明是很难做到的啊。有了臧武仲的聪明，而不能为鲁国容纳，这是有原因的，因为他的所作不顺于事理而所施不合于恕道。《夏书》说：‘想着这个，一心在于这个’，这就是顺于事理，合于恕道啊。”
', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1dd0f8fda5565061591", "shortContent": "铭按其撰刻宗旨，可概分为两类：记功德，使传扬于后世；表誓戒，求闻达于当代。张载的《剑阁铭》则是表誓戒铭文中的杰作。张载之父张收，晋武帝太康初任蜀郡太守，载至蜀省父，道经剑阁。剑阁，即剑门关，在今四川剑阁县北二十五公里的剑门山，山势横亘百余公里，七十二峰绵延起伏，形若利剑，高连霄汉，峭壁中断处，两山相峙如门，故名剑门关，为镇扼秦蜀通道之咽喉，历代兵家必争之地。张载以蜀人恃险好乱，因著此铭以作诫。益州...", "authors": ["章尚正"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559125817, '5cedeeb47b968a00767d3015', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643014, '左传 · 成公 · 成公十四年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有四年春王正月，莒子朱卒。夏，卫孙林父自晋归于卫。秋，叔孙侨如如齐逆女。郑公子喜帅师伐许。九月，侨如以夫人妇姜氏至自齐。冬十月庚寅，卫侯臧卒。秦伯卒。
【传】十四年春，卫侯如晋，晋侯强见孙林父焉，定公不可。夏，卫侯既归，晋侯使郤犨送孙林父而见之。卫侯欲辞，定姜曰：「不可。是先君宗卿之嗣也，大国又以为请，不许，将亡。虽恶之，不犹愈于亡乎？君其忍之！安民而宥宗卿，不亦可乎？」卫侯见而复之。
卫侯飨苦成叔，宁惠子相。苦成叔傲。宁子曰：「苦成家其亡乎！古之为享食也，以观威仪、省祸福也。故《诗》曰：『兕觥其觩，旨酒思柔，彼交匪傲，万福来求。』今夫子傲，取祸之道也。」
秋，宣伯如齐逆女。称族，尊君命也。
八月，郑子罕伐许，败焉。戊戌，郑伯复伐许。庚子，入其郛。许人平以叔申之封。
九月，侨如以夫人妇姜氏至自齐。舍族，尊夫人也。故君子曰：「《春秋》之称，微而显，志而晦，婉而成章，尽而不污，惩恶而劝善。非圣人谁能修之？」
卫侯有疾，使孔成子、宁惠子立敬姒之子衎以为大子。冬十月，卫定公卒。夫人姜氏既哭而息，见大子之不哀也，不内酌饮。叹曰：「是夫也，将不唯卫国之败，其必始于未亡人！乌呼！天祸卫国也夫！吾不获鱄也使主社稷。」大夫闻之，无不耸惧。孙文子自是不敢舍其重器于卫，尽置诸戚，而甚善晋大夫。', '', '', '十四年春季，卫定公去到晋国，晋厉公强请卫定公接见孙林父，卫定公不同意。夏季，卫定公回国以后，晋厉公派郤犫送孙林父去见他。卫定公想要推辞。定姜说：“不行。他是先君宗卿的后代，大国又以此作为请求，如果不答应，我国将要灭亡。虽然讨厌他，总比亡国强些吧？君王还是忍耐一下吧！安定百姓而赦免宗卿，不也是可行的吗？”卫定公接见了孙林父，并且恢复了他的职位和采邑。
卫定公设享礼招待苦成叔，宁惠子作陪，苦成叔表现出傲慢的样子。宁惠子说：“苦成叔恐怕要被灭亡了吧！古代举行享礼，是用来观察威仪，省察祸福的，所以《诗》说：‘弯弯角杯，柔和甜酒。不骄不傲，聚集万福。’现在他老人家表现傲慢，是取祸之道啊！”
秋季，鲁大夫宣伯到齐国迎接齐女。《春秋》称他的族名，这是由于尊重国君的命令。
八月，郑国的子罕进攻许国，战败。二十三日，郑成公再次进攻许国。二十五日，进入许国的外城。许国人把叔申的封地交还郑国以此与郑国讲和。
九月，侨如带着夫人姜氏从齐国来到。《春秋》不称族名，这是由于尊重夫人。所以君子说：《春秋》的记载，言词不多而意义显明，记载史实而意义深远，婉转而顺理成章，穷尽而不歪曲，警戒邪恶而奖励善良。如果不是圣人，谁能够编写？”
卫定公有病，让孔成子、宁惠子立敬姒的儿子衎作为太子。冬季，十一月，卫定公去世。夫人姜氏哭丧以后休息，看到太子并不悲哀，就连水也不喝，叹气说：“这个人啊，将要不仅会使卫国遭致败亡，而且必然从我这个未亡人身上开始动手。唉呀！这是上天降祸给卫国吧！我不能得到鱄来主持国家。”大夫们听到以后，无不感到十分恐惧。孙文子从此不敢把他的宝器藏在卫国，而都放在采邑戚地，同时尽量和晋国的大夫友好。', NULL, '', 'indent', 1559038618, '5cec9a16c8959c0069e95664', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643015, '左传 · 成公 · 成公十五年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有五年春王二月，葬卫定公。三月乙巳，仲婴齐卒。癸丑，公会晋侯、卫侯、郑伯、曹伯、宋世子成、齐国佐，邾人同盟于戚。晋侯执曹伯归于京师。公至自会。夏六月，宁公固卒。楚子伐郑。秋八月庚辰，葬宋共公。宋华元出奔晋。宋华元自晋归于宋。宋杀其大夫山。宋鱼石出奔楚。冬十有一月，叔孙侨如会晋士燮、齐高无咎、宋华元、卫孙林父、郑公子酉、邾人会吴于钟离。许迁于叶。
【传】十五年春，会于戚，讨曹成公也。执而归诸京师。书曰：「晋侯执曹伯。」不及其民也。凡君不道于其民，诸侯讨而执之，则曰某人执某侯。不然，则否。
诸侯将见子臧于王而立之，子臧辞曰：「《前志》有之，曰：『圣达节，次守节，下失节。』为君，非吾节也。虽不能圣，敢失守乎？」遂逃，奔宋。
夏六月，宋共公卒。
楚将北师。子囊曰：「新与晋盟而背之，无乃不可乎？」子反曰：「敌利则进，何盟之有？」申叔时老矣，在申，闻之，曰：「子反必不免。信以守礼，礼以庇身，信礼之亡，欲免得乎？」楚子侵郑，及暴隧，遂侵卫，及首止。郑子罕侵楚，取新石。栾武子欲报楚，韩献子曰：「无庸，使重其罪，民将叛之。无民，孰战？」
秋八月，葬宋共公。于是华元为右师，鱼石为左师，荡泽为司马，华喜为司徒，公孙师为司城，向为人为大司寇，鳞朱为少司寇，向带为大宰，鱼府为少宰。荡泽弱公室，杀公子肥。华元曰：「我为右师，君臣之训，师所司也。今公室卑而不能正，吾罪大矣。不能治官，敢赖宠乎？」乃出奔晋。
二华，戴族也；司城，庄族也；六官者，皆桓族也。鱼石将止华元，鱼府曰：「右师反，必讨，是无桓氏也。」鱼石曰：「右师苟获反，虽许之讨，必不敢。且多大功，国人与之，不反，惧桓氏之无祀于宋也。右师讨，犹有戌在，桓氏虽亡，必偏。」鱼石自止华元于河上。请讨，许之，乃反。使华喜、公孙师帅国人攻荡氏，杀子山。书曰：「宋杀大夫山。」言背其族也。
鱼石、向为人、鳞朱、向带、鱼府出舍于睢上。华元使止之，不可。冬十月，华元自止之，不可。乃反。鱼府曰：「今不从，不得入矣。右师视速而言疾，有异志焉。若不我纳，今将驰矣。」登丘而望之，则驰。聘而从之，则决睢澨，闭门登陴矣。左师、二司寇、二宰遂出奔楚。华元使向戌为左师，老佐为司马，乐裔为司寇，以靖国人。
晋三郤害伯宗，谮而杀之，及栾弗忌。伯州犁奔楚。韩献子曰：「郤氏其不免乎！善人，天地之纪也，而骤绝之，不亡何待？」
初，伯宗每朝，其妻必戒之曰：「『盗憎主人，民恶其上。』子好直言，必及于难。」
十一月，会吴于钟离，始通吴也。
许灵公畏逼于郑，请迁于楚。辛丑，楚公子申迁许于叶。', '', '', '十五年春季，鲁成公和晋厉公、卫献公、郑成公、曹成公、宋国世子成、齐国国佐、邾人在戚地会盟，这是为了讨伐曹成公。逮捕了曹成公送到京师。《春秋》记载说“晋侯执曹伯”，这是由于曹成公的罪过不及于百姓。凡是国君对百姓无道，诸侯讨伐而且逮捕了他，就说“某人执某侯”，否则就不这样记载。
诸侯要让子臧进见周王而立他为曹国国君。子臧辞谢说：“古书上有这样的话：‘圣人通达节义，其次保守节义，最下失去节义’。做国君这件事不合于我的节义。虽然不能像圣人那样，岂敢失节呢？”于是逃亡到宋国。
夏季，六月，宋共公去世。
楚国准备向北方出兵，子囊说：“新近和晋国结盟而背弃它，恐怕不可吧！”子反说：“敌情有利于我就前进，结什么盟？”申叔时已经老了，住在采邑申地，听到这话，说：“子反必然不能免于祸难。信用用来保持礼义，礼义用来保护生存，信用、礼义都没有了，想要免于祸难，行吗？”
楚子入侵郑国，到达暴隧，因此入侵卫国，到达首止。郑国子罕入侵楚国，战领了新石。
晋将栾武子想要报复楚国，韩献子说：“不用，让他自己加重罪过，百姓将会背叛他。失了人心，谁去替他打仗。”
秋季，八月，安葬宋共公。在这时，华元做右师，鱼石做左师，荡泽做司马，华喜做司徒，公孙师做司城，向为人做大司寇，鳞朱做少师寇，向带做太宰，鱼府做少宰。荡泽要削弱公室，杀了公子肥。华元说：“我做右师，国君和臣下的教导，这是师所掌管的。现在公室的地位低下，却不能拨正，我的罪过大了。不能尽到职责，岂敢以得到宠信为利呢？”于是出奔晋国。
二位华氏，是戴公的后代；司城，是庄公的后代；其他六大臣都是桓公的后代。鱼石准备阻止华元逃亡。鱼府说：“右师如果回来，必然要讨伐荡泽，这就会没有桓氏这一族了。”鱼石说：“右师如果能够回来，虽然允许他讨伐，他必然不敢。而且他建立了大功，国内的人们亲附他，如果他不回来，恐怕桓氏在宋国没有人祭祀了。右师如果讨伐，还有向戌在那里。桓氏虽然灭亡，必然只是亡掉一部分而已。”鱼石自己在黄河岸上阻止华元。华元请求讨伐荡泽，鱼石答应了。华元这才回来，派遣华喜、公孙师率领国内的人们进攻荡氏，杀了荡泽，《春秋》记载说“宋杀其大夫山”，就是说荡泽背弃了自己的宗族。
鱼石、向为人、鳞朱、向带、鱼府离开都城住在睢水旁边，华元派人劝阻他们，他们不同意。冬季，十月，华元亲自去劝阻，他们又不同意，华元就回来了。鱼府说：“现在不听从华元的话，以后就不能进入国都了。右师眼睛转动很快而说话很急，有别的想法呀。如果不接纳我们，现在就要疾驰而去了。”他们登上山头一看，就看到华元疾驰而去。这五个人驱车跟随华元，华元已经掘开睢水堤防，关闭城门登上城墙了。左师、两个司寇、两个宰就逃亡到楚国。华元派向戌做左师、老佐做司马、乐裔做司寇，来安定国内的人。
晋国三郤陷害伯宗，诬陷以后再杀了他，并且连累及于栾弗忌。伯州犁逃亡到楚国。韩献子说：“郤氏恐怕不能免于祸难吧！善人，是天地的纲纪，而多次加以杀害，不灭亡还等什么？”
当初，伯宗每次朝见，他的妻子一定劝戒他说：“盗贼憎恨主人，百姓讨厌统治者，您喜欢说直话，必然遭到祸难。”
十一月，叔孙侨如会合晋国士燮、齐国高无咎、宋国华元、卫国孙林父、郑国公子？和吴国在钟离会见，这是开始和吴国友好往来。
许灵公害怕郑国逼迫，请求迁到楚国。十一月初三日，楚国公子申把许国迁到叶地。', NULL, '', 'indent', 1559038658, '5cec9a3fa673f5006821b8fa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643016, '左传 · 成公 · 成公十六年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有六年春王正月，雨，木冰。夏四月辛未，滕子卒。郑公子喜帅师侵宋。六月丙寅朔，日有食之。晋侯使栾□来乞师。甲午晦，晋侯及楚子、郑伯战于鄢陵。楚子、郑师败绩。楚杀其大夫公子侧。秋，公会晋侯、齐侯、卫侯、宋华元、邾人于沙随，不见公。公至自会。公会尹子，晋侯、齐国佐、邾人伐郑。曹伯归自京师。九月，晋人执季孙行父，舍之于苕丘。冬十月乙亥，叔孙侨如出奔齐。十有二月乙丑，季孙行父及晋郤犨盟于扈。公至自会。乙酉，刺公子偃。
【传】十六年春，楚子自武城使公子成以汝阴之田求成于郑。郑叛晋，子驷从楚子盟于武城。
夏四月，滕文公卒。
郑子罕伐宋，宋将锄、乐惧败诸汋陂。退，舍于夫渠，不儆，郑人覆之，败诸汋陵，获将锄、乐惧。宋恃胜也。
卫侯伐郑，至于鸣雁，为晋故也。
晋侯将伐郑，范文子曰：「若逞吾愿，诸侯皆叛，晋可以逞。若唯郑叛，晋国之忧，可立俟也。」栾武子曰：「不可以当吾世而失诸侯，必伐郑。」乃兴师。栾书将中军，士燮佐之。郤錡将上军，荀偃佐之。韩厥将下军，郤至佐新军，荀罃居守。郤犨如卫，遂如齐，皆乞师焉。栾□来乞师，孟献子曰：「有胜矣。」戊寅，晋师起。
郑人闻有晋师，使告于楚，姚句耳与往。楚子救郑，司马将中军，令尹将左，右尹子辛将右。过申，子反入见申叔时，曰：「师其何如？」对曰：「德、刑、详、义、礼、信，战之器也。德以施惠，刑以正邪，详以事神，义以建利，礼以顺时，信以守物。民生厚而德正，用利而事节，时顺而物成。上下和睦，周旋不逆，求无不具，各知其极。故《诗》曰：『立我烝民，莫匪尔极。』是以神降之福，时无灾害，民生敦庞，和同以听，莫不尽力以从上命，致死以补其阙。此战之所由克也。今楚内弃其民，而外绝其好，渎齐盟，而食话言，奸时以动，而疲民以逞。民不知信，进退罪也。人恤所底，其谁致死？子其勉之！吾不复见子矣。」姚句耳先归，子驷问焉，对曰：「其行速，过险而不整。速则失志，不整丧列。志失列丧，将何以战？楚惧不可用也。」
五月，晋师济河。闻楚师将至，范文子欲反，曰：「我伪逃楚，可以纾忧。夫合诸侯，非吾所能也，以遗能者。我若群臣辑睦以事君，多矣。」武子曰：「不可。」
六月，晋、楚遇于鄢陵。范文子不欲战，郤至曰：「韩之战，惠公不振旅。箕之役，先轸不反命，邲之师，荀伯不复从。皆晋之耻也。子亦见先君之事矣。今我辟楚，又益耻也。」文子曰：「吾先君之亟战也，有故。秦、狄、齐、楚皆强，不尽力，子孙将弱。今三强服矣，敌楚而已。唯圣人能外内无患，自非圣人，外宁必有内忧。盍释楚以为外惧乎？」
甲午晦，楚晨压晋军而陈。军吏患之。范□趋进，曰：「塞井夷灶，陈于军中，而疏行首。晋、楚唯天所授，何患焉？」文子执戈逐之，曰：「国之存亡，天也。童子何知焉？」栾书曰：「楚师轻窕，固垒而待之，三日必退。退而击之，必获胜焉。」郤至曰：「楚有六间，不可失也。其二卿相恶。王卒以旧。郑陈而不整。蛮军而不陈。陈不违晦，在陈而嚣，合而加嚣，各顾其后，莫有斗心。旧不必良，以犯天忌。我必克之。」
楚子登巢车以望晋军，子重使大宰伯州犁侍于王后。王曰：「骋而左右，何也？」曰：「召军吏也。」「皆聚于军中矣！」曰：「合谋也。」「张幕矣。」曰：「虔卜于先君也。」「彻幕矣！」曰：「将发命也。」「甚嚣，且尘上矣！」曰：「将塞井夷灶而为行也。」「皆乘矣，左右执兵而下矣！」曰：「听誓也。」「战乎？」曰：「未可知也。」「乘而左右皆下矣！」曰：「战祷也。」伯州犁以公卒告王。苗贲皇在晋侯之侧，亦以王卒告。皆曰：「国士在，且厚，不可当也。」苗贲皇言于晋侯曰：「楚之良，在其中军王族而已。请分良以击其左右，而三军萃于王卒，必大败之。」公筮之，史曰：「吉。其卦遇《复》三，曰：『南国戚，射其元王中厥目。』国戚王伤，不败何待？」公从之。有淖于前，乃皆左右相违于淖。步毅御晋厉公，栾金咸为右。彭名御楚共王，潘党为右。石首御郑成公，唐苟为右。栾、范以其族夹公行，陷于淖。栾书将载晋侯，金咸曰：「书退！国有大任，焉得专之？且侵官，冒也；失官，慢也；离局，奸也。有三不罪焉，可犯也。」乃掀公以出于淖。
癸巳，潘□之党与养由基蹲甲而射之，彻七札焉。以示王，曰：「君有二臣如此，何忧于战？」王怒曰：「大辱国。诘朝，尔射，死艺。」吕錡梦射月，中之，退入于泥。占之，曰：「姬姓，日也。异姓，月也，必楚王也。射而中之，退入于泥，亦必死矣。」及战，射共王，中目。王召养由基，与之两矢，使射吕錡，中项，伏弢。以一矢覆命。
郤至三遇楚子之卒，见楚子，必下，免胄而趋风。楚子使工尹襄问之以弓，曰：「方事之殷也，有韎韦之跗注，君子也。识见不谷而趋，无乃伤乎？」郤至见客，免胄承命，曰：「君之外臣至，从寡君之戎事，以君之灵，间蒙甲胄，不敢拜命，敢告不宁君命之辱，为事之故，敢肃使者。」三肃使者而退。
晋韩厥从郑伯，其御杜溷罗曰：「速从之！其御屡顾，不在马，可及也。」韩厥曰：「不可以再辱国君。」乃止。郤至从郑伯，其右茀翰胡曰：「谍辂之，余从之乘而俘以下。」郤至曰：「伤国君有刑。」亦止。石首曰：「卫懿公唯不去其旗，是以败于荧。」乃旌于弢中。唐苟谓石首曰：「子在君侧，败者壹大。我不如子，子以君免，我请止。」乃死。
楚师薄于险，叔山冉谓养由基曰：「虽君有命，为国故，子必射！」乃射。再发，尽殪。叔山冉搏人以投，中车，折轼。晋师乃止。囚楚公子伐。
栾金咸见子重之旌，请曰：「楚人谓夫旌，子重之麾也。彼其子重也。日臣之使于楚也，子重问晋国之勇。臣对曰：『好以众整。』曰：『又何如？』臣对曰：『好以暇。』今两国治戎，行人不使，不可谓整。临事而食言，不可谓暇。请摄饮焉。」公许之。使行人执榼承饮，造于子重，曰：「寡君乏使，使金咸御持矛。是以不得犒从者，使某摄饮。」子重曰：「夫子尝与吾言于楚，必是故也，不亦识乎！」受而饮之。免使者而复鼓。
旦而战，见星未已。子反命军吏察夷伤，补卒乘，缮甲兵，展车马，鸡鸣而食，唯命是听。晋人患之。苗贲皇徇曰：「搜乘补卒，秣马利兵，修陈固列，蓐食申祷，明日复战。」乃逸楚囚。王闻之，召子反谋。谷阳竖献饮于子反，子反醉而不能见。王曰：「天败楚也夫！余不可以待。」乃宵遁。晋入楚军，三日谷。范文子立于戎马之前，曰：「君幼，诸臣不佞，何以及此？君其戒之！《周书》曰『唯命不于常』，有德之谓。」
楚师还，及瑕，王使谓子反曰：「先大夫之覆师徒者，君不在。子无以为过，不谷之罪也。」子反再拜稽首曰：「君赐臣死，死且不朽。臣之卒实奔，臣之罪也。」子重复谓子反曰：「初陨师徒者，而亦闻之矣！盍图之？」对曰：「虽微先大夫有之，大夫命侧，侧敢不义？侧亡君师，敢忘其死。」王使止之，弗及而卒。
战之日，齐国佐、高无咎至于师。卫侯出于卫，公出于坏隤。宣伯通于穆姜，欲去季、孟，而取其室。将行，穆姜送公，而使逐二子。公以晋难告，曰：「请反而听命。」姜怒，公子偃、公子锄趋过，指之曰：「女不可，是皆君也。」公待于坏隤，申宫儆备，设守而后行，是以后。使孟献子守于公宫。
秋，会于沙随，谋伐郑也。宣伯使告郤犨曰：「鲁侯待于坏隤以待胜者。」郤犨将新军，且为公族大夫，以主东诸侯。取货于宣伯而诉公于晋侯，晋侯不见公。
曹人请于晋曰：「自我先君宣公即位，国人曰：『若之何忧犹未弭？』而又讨我寡君，以亡曹国社稷之镇公子，是大泯曹也。先君无乃有罪乎？若有罪，则君列诸会矣。君唯不遗德刑，以伯诸侯。岂独遗诸敝邑？取私布之。」
七月，公会尹武公及诸侯伐郑。将行，姜又命公如初。公又申守而行。诸侯之师次于郑西。我师次于督扬，不敢过郑。子叔声伯使叔孙豹请逆于晋师。为食于郑郊。师逆以至。声伯四日不食以待之，食使者而后食。
诸侯迁于制田。知武子佐下军，以诸侯之师侵陈，至于鸣鹿。遂侵蔡。未反，诸侯迁于颖上。戊午，郑子罕宵军之，宋、齐、卫皆失军。
曹人复请于晋，晋侯谓子臧：「反，吾归而君。」子臧反，曹伯归。子臧尽致其邑与卿而不出。
宣伯使告郤犨曰：「鲁之有季、孟，犹晋之有栾、范也，政令于是乎成。今其谋曰：『晋政多门，不可从也。宁事齐、楚，有亡而已，蔑从晋矣。』若欲得志于鲁，请止行父而杀之，我毙蔑也而事晋，蔑有贰矣。鲁不贰，小国必睦。不然，归必叛矣。」
九月，晋人执季文子于苕丘。公还，待于郓。使子叔声伯请季孙于晋，郤犨曰：「苟去仲孙蔑而止季孙行父，吾与子国，亲于公室。」对曰：「侨如之情，子必闻之矣。若去蔑与行父，是大弃鲁国而罪寡君也。若犹不弃，而惠徼周公之福，使寡君得事晋君。则夫二人者，鲁国社稷之臣也。若朝亡之，鲁必夕亡。以鲁之密迩仇雠，亡而为仇，治之何及？」郤犨曰：「吾为子请邑。」对曰：「婴齐，鲁之常隶也，敢介大国以求厚焉！承寡君之命以请，若得所请，吾子之赐多矣。又何求？」范文子谓栾武子曰：「季孙于鲁，相二君矣。妾不衣帛，马不食粟，可不谓忠乎？信谗慝而弃忠良，若诸侯何？子叔婴齐奉君命无私，谋国家不贰，图其身不忘其君。若虚其请，是弃善人也。子其图之！」乃许鲁平，赦季孙。
冬十月，出叔孙侨如而盟之，侨如奔齐。
十二月，季孙及郤犨盟于扈。归，刺公子偃，召叔孙豹于齐而立之。
齐声孟子通侨如，使立于高、国之间。侨如曰：「不可以再罪。」奔卫，亦间于卿。
晋侯使郤至献楚捷于周，与单襄公语，骤称其伐。单子语诸大夫曰：「温季其亡乎！位于七人之下，而求掩其上。怨之所聚，乱之本也。多怨而阶乱，何以在位？《夏书》曰：『怨岂在明？不见是图。』将慎其细也。今而明之，其可乎？」', '', '', '十六年春季，楚共王从武城派公子成用汝阴的土田向郑国求和。郑国背叛晋国，子驷跟随楚子在武城结盟。
夏季，四月，滕文公去世。
郑国的子罕进攻宋国，宋国将锄、乐惧在汋陂打败了他。宋军退兵，驻扎在夫渠，不加警备。郑军伏兵袭击，在汋陵打败了他们，俘虏了将锄、乐惧。这是由宋国仗恃打了胜仗而不加戒备。
卫献公发兵攻打郑国，到达鸣雁，这是为了晋国的缘故。
晋厉公打算讨伐郑国，范文子说：“如果按照我的愿望，诸侯都背叛，晋国的危机可以得到缓和。如果只是一个郑国背叛，晋国的忧患，可能马上就会来了。”栾武子说：“不能在我们这一辈执政的时候失去诸侯，一定要进攻郑国。”于是就发兵。栾书率领中军，士燮作为辅佐；郤锜率领上军，荀偃作为辅佐；韩厥率领下军，郤至作为新军辅佐。荀罃留守。郤犫去到卫国，乘机到齐国，请求两国出兵。栾黡前来请求出兵，孟献子说：“晋国可能得胜了。”四月十二日，晋军出兵。
郑国人听说晋国出兵，就派使者报告楚国，姚句耳同行。楚共王救援郑国。司马子反率领中军，令尹子重率领左军，右尹子辛率领右军。路过申地，子反进见申叔时，说：“这次出兵会怎么样？”申叔时回答说：“德行、刑罚、和顺、道义、礼法、信用，这是战争的手段。德行用来施予恩惠，刑罚用来纠正邪恶，和顺用来事奉神灵，道义用来建立利益，礼法用来适合时宜，信用用来护守事物。人民生活优厚，道德就端正；举动有利，事情就合于节度，时宜合适，生产就有所成就；这样就能上下和睦，相处没有矛盾，有所需求无不具备，各人都知道行动的准则。所以《诗》说：‘安置百姓，没有不合乎准则。’这样，神灵就降福于他，四时没有灾害，百姓生活优厚，齐心一致地听命，没有不尽力以服从上面命令的，不顾性命来弥补死去的战士的空缺，这样就是战争所以能够胜利的原因。现在楚国内部丢弃他的百姓，外部断绝他的友好，亵渎神圣的盟约而说话不讲信用，违反时令发动战争，使百姓疲劳以求快意。人们不知道什么是信用，进退都是罪过。人们为他们的结局在担忧，还有谁肯去送命？您还是尽力做吧！我不会再看到您了。”姚句耳先回来，子驷询问情况，他回答说：“楚军行军迅速，经过险要的地方行列不整齐。动作太快就会考虑不周，军容不整齐就丧失了行列。考虑不周、行列丧失，怎么能打仗？楚国恐怕不能依靠了。”
五月，晋军渡过黄河。他们听说楚军将要到达，范文子想要回去，说：“我们假装逃避楚国，这样就能够缓和忧患。会合诸侯，不是我所能做到的，还是遗留给有能力的人吧。我们如果群臣和睦以奉事国君，这就够了。”栾武子说：“不可以。”
六月，晋、楚两军在鄢陵相遇。范文子不想作战。郤至说：“韩地这一战，惠公失败归来；箕地这一役，先轸不能回国复命；邲地这一仗，荀伯又失败，这都是晋国的耻辱。您也了解先君时代的情况了。现在我们逃避楚国，这又是增加耻辱。”范文子说：“我们先君的屡次作战，是有原因的。秦国、狄人、齐国、楚国都很强大，如果我们不尽自己的力量，子孙将会被削弱。现在三强已经顺服，敌人仅楚国而已。只有圣人才能够外部内部都没有祸患。如果不是圣人，外部安定，内部必然还有忧患，何不放掉楚国把它作为外部的戒惧呢？”
二十九日（阴历月终），楚军在清早逼近晋军而摆开阵势。晋国的军吏担心这种情况。范匄快步向前，说：“填井平灶，就在军营摆开阵势，把行列间的距离放宽。晋、楚两国都是上天的赐予，有什么可担心的？”范文子拿起戈来驱逐他，说：“国家的存亡，这是天意，小孩子知道什么？”栾书说：“楚军轻佻，加固营垒而等待他们，三天一定退军。乘他们退走而加以追击，一定可以得胜。”郤至说：“楚国有六个空子，我们不可失掉时机：楚国的两个卿不和；楚共王的亲兵们从旧家中选拔，都已衰老；郑国虽然摆开阵势却不整齐；蛮人虽有军队却没有阵容；楚军摆阵不避讳月底；士兵在阵中就喧闹，各阵式相联合后就更加喧闹，各军彼此观望依赖，没有战斗意志。旧家子弟的士兵不一定是强兵，所以这些都触犯了天意和兵家大忌。我们一定能战胜他们。”
楚共王登上楼车了望晋军。子重让大宰伯州犁侍立在楚共王身后。楚共王说：“车子向左右驰骋，干什么？”伯州犁说：“这是召集军官们。”楚共王说：“那些人都集合在中军了。”伯州犁说：“这是一起谋议。”楚共王说：“帐幕张开了。”伯州犁说：“这是在先君的神主前占卜。”楚共王说：“帐幕撤除了。”伯州犁说：“这是将要发布命令了。”楚共王说：“喧闹得厉害。而且尘土飞扬起来了。”伯州犁说：“这是准备填井平灶摆开阵势。”楚共王说：“都登上战车了，将帅和车右都拿着武器下车了。”伯州犁说：“这是宣布号令。”楚共王说：“他们要作战吗？”伯州犁说：“还不能知道。”楚共王说：“晋军上了战车，将帅和车右又下来了。”伯州犁说：“这是战前的祈祷。”伯州犁把晋厉公亲兵的情况向楚共王报告。苗贲皇在晋厉公的旁边，也把楚共王亲兵的情况向晋厉公报告。晋厉公左右的将士们都说：“有国家中杰出的人物在那里，而且军阵厚实，不能抵挡。”苗贲皇对晋厉公说：“楚国的精兵在于他们中军的王族而已。请求把我们的精兵分开去攻击他们的左右军，再集中三军攻打楚王的亲兵，一定可以把他们打得大败。”晋厉公让太史占筮。太史说：“吉利。得到《复》。卦辞说：‘南方的国家局促，射它的国王，箭头中目。’国家局促，国王受伤，不失败，还等待什么？”晋厉公听从了。晋军营前头有泥沼，于是晋军都或左或右地避开泥沼而行。步毅驾御晋厉公的战车，栾鍼作为车右。彭名驾御楚共王的战车，潘党作为车右。石首驾御郑成公的战车，唐苟作为车右。栾、范领着他们私族部队左右护卫着晋厉公前进。战车陷在泥沼里。栾书打算将晋厉公装载在自己车上。他儿子栾鍼说：“书退下去！国家有大事，你哪能一人揽了？而且侵犯别人的职权，这是冒犯；丢弃自己的职责，这是怠慢；离开自己的部下，这是扰乱。有三件罪名，不能违犯啊。”于是就掀起晋厉公的战车离开泥沼。
六月二十八日，潘尫的儿子党和养由基把皮甲重叠而射它，穿透了七层。拿去给楚共王看，说：“君王有这样两个臣下在这里，还有什么可怕的？”楚共王发怒说：“真丢人！明早作战，你们射箭，将会死在这武艺上。”吕锜梦见自己射月亮，射中，自己却退进了泥塘里。占卜，说：“姬姓，是太阳；异姓，是月亮，这一定是楚共王了。射中了他，自己又退进泥里，就一定会战死。”等到作战时，吕锜射中了楚共王的眼睛。楚王召唤养由基，给他两支箭，让他射吕锜。结果射中吕锜的脖子，伏在弓套上死了。养由基拿了剩下的一支向楚共王复命。
郤至三次碰到楚共王的士兵，见到楚共王时，一定下车，脱下头盔，快步向前而走。楚共王派工尹襄送上一张弓去问候，说：“正当战事激烈的时候，有一位身穿浅红色牛皮军服的人，是君了啊！刚才见到我而快走，恐怕是受伤了吧！”郤至见到客人，脱下头盔接受命令，说：“贵国君王的外臣郤至跟随寡君作战，托君王的福，参与了披甲的行列，不敢拜谢命令。谨向君王报告没有受伤，感谢君王惠赐给我的命令。由于战事的缘故，谨向使者敬礼。”于是，三次向使者肃拜以后才退走。
晋国的韩厥追赶郑成公，他的车夫杜溷罗说：“是否赶快追上去？他们的御者屡屡回头看，注意力不在马上，可以赶上。”韩厥说：“不能再次羞辱国君。”于是就停止追赶。郤至追赶郑成公，他的车右茀翰胡说：“另外派轻车从小道迎击，我追上他的战车而把他俘虏下来。”郤至说：“伤害国君要受到刑罚。”也停止了追赶。石首说：“从前卫懿公由于不去掉他的旗子，所以才在荧地战败。”于是就把旗子放进弓袋里。唐苟对石首说：“您在国君旁边，战败者应该一心保护国君。我不如您，您带着国君逃走，我请求留下。”于是唐苟就战死了。
楚军被逼在险阻的地带，叔山冉对养由基说：“虽然国君有命令，为了国家的缘故，您一定要射箭。”养由基就射晋军，再射，被射的人都被射死。叔山冉举起晋国人投掷过去，掷中战车，折断了车前的横木。晋军于是停下来。囚禁了楚国的公子茷。
栾鍼见到子重的旌旗，请求说：“楚国人说那面旌旗是子重的旗号，他恐怕就是子重吧。当初下臣出使到楚国，子重问起晋国的勇武表现在哪里，下臣回答说：‘喜好整齐，按部就班。’子重说：‘还有什么？’下臣回答说：‘喜好从容不迫。’现在两国兴兵，不派遣使者，不能说是按部就班；临到事情而不讲信用，不能说是从容不迫。请君王派人替我给子重进酒。”晋厉公答应了，派遣使者拿着酒器奉酒，到了子重那里，说：“寡君缺乏使者，让栾鍼执矛侍立在他左右，因此不能犒赏您的从者，派我前来代他送酒。”子重说：“他老人家曾经跟我在楚国说过一番话，送酒来一定是这个原因。他的记忆力不也是很强吗？”受酒而饮，不留难使者而重新击鼓。
早晨开始作战，直到黄昏还没有结束战争。子反命令军官视察伤情，补充步兵车兵，修理盔甲武器，陈列战车马匹，鸡叫的时候吃饭，唯主帅的命令是听。晋国因此担心。苗贲皇通告全军说：“检阅战车、补充士卒，喂好马匹，磨快武器，整顿军阵、巩固行列，饱吃一顿、再次祷告，明天再战！”就故意放松楚国的俘虏让他们逃走。楚共王听到这些情况，召子反一起商量。穀阳竖献酒给子反，子反喝醉了不能进见。楚共王说：“这是上天要让楚国失败啊！我不能等待了。”于是就夜里逃走了。晋军进入楚国军营，吃了三天楚军留下的粮食。范文子站在兵马前面，说：“君王年幼，下臣们不才，怎么能得到这个地步？君王还是要警惕啊！《周书》说，‘天命不能常在不变’，说的是有德的人就可以享有天命。”
楚军回去，到达瑕地，楚共王派人对子反说：“先大夫让军队覆没，当时国君不在军中。现在您没有过错，这是我的罪过。”子反再拜叩头说：“君王赐下臣去死，死而不朽。下臣的士兵的确败逃了，这是下臣的罪过。”子重也派人对子反说：“当初让军队覆没的人，他的结果你也听到过了。何不自己打算一下！”子反回答说：“即使没有先大夫自杀谢罪的事，大夫命令侧死去，侧岂敢贪生而陷于不义？侧使国君的军队败亡，岂敢忘记一死？”楚共王派人阻止他，没来得及，子反就自杀了。
作战的第二天，齐国国佐、高无咎到达军中，卫献公从卫国出来，鲁成公从坏隤出来。宣伯和穆姜私通，想要去掉季、孟两人而占取他们的家财。成公将要出行，穆姜送他，让他驱逐这两个人。成公把晋国的危难告诉她，说：“请等我回来再听取您的命令。”穆姜生气，公子偃、公子锄快步走过，穆姜指着他们说：“你要不同意，他们都可以是国君！”鲁成公在坏隤等待，防护宫室、加强戒备、设置守卫，然后出行，所以去晚了。让孟献子在公宫留守。
秋季，鲁成公和晋厉公、齐灵公、卫献公、宋国华元、邾国人在沙随会见，商量进攻郑国。宣伯派人告诉郤犫说：“鲁侯在坏隤等着，以等待胜利者。”郤犫率领新军，同时做公族大夫，主持东方诸侯的事务。他从宣伯那里拿了财物，而在晋厉公那里毁谤鲁成公。晋厉公就不和鲁成公见面。
曹国人向晋国请求说：“自从我先君宣公去世，国内的人们说：‘怎么办？忧患还没有消除。’而贵国又讨伐我寡君，因而使镇抚曹国国家的公子子臧逃亡，这是在大举灭曹，莫非由于先君有罪吧！可是如果有罪，那么君王又使他参加会盟。君王不丢失德行和刑罚，所以才能称霸诸侯，岂独丢弃敝邑？谨在私下向贵国表达真情。”
七月，鲁成公会合尹武公和诸侯进攻郑国。成公将要出行，穆姜又像以前一样命令成公。成公又在宫中设了防备以后才出行。诸侯的军队驻扎在郑国西部，我国的军队驻扎在督扬，不敢经过郑国。子叔声伯派叔孙豹请求晋军前来迎接我军，又在郑国郊外为晋军准备饭食。晋军为迎接我军而来到。声伯四天没有吃饭等着他们，直到让晋国的使者吃了饭以后自己才吃。
诸侯迁移到制田，知武子作为下军副帅，率领诸侯的军队入侵陈国，到达鸣鹿，因此入侵蔡国。还没有回来，诸侯又迁移到颍上。七月二十四日，郑国的子罕发动夜袭，宋国、齐国、卫国都溃不成军。
曹国人再次向晋国请求。晋厉公对子臧说：“你回去，我送回你们国君。”子臧回国，曹成公也回来了，子臧把他的封邑和卿的职位全部交出去而不再做官。
叔孙侨如派人告诉郤犫说：“鲁国有季氏、孟氏，就好像晋国有栾氏、范氏，政令就是在那里制订的。现在他们商量说：‘晋国的政令出于不同的家族，不能统一，这是不能服从的。宁可事奉齐国和楚国，哪怕亡国，也不要跟从晋国了。’晋国如果要在鲁国行使自己的意志，请留下行父而杀了他，我把蔑杀死，事奉晋国，就没有二心了。鲁国没有二心，其他小国一定服从晋国。不这样，行父回国就必然背叛晋国。”
九月，晋国人在苕丘逮捕了季孙行父。成公回来。在郓地等待，派子叔声伯向晋国请求放回季孙。郤犫说：“如果去掉仲孙蔑而留下季孙行父，我给您鲁国的政权，对待您比对公室还亲。”声伯回答说：“侨如的情况，您一定听到了。如果去掉蔑和行父，这是大大地丢弃鲁国而加罪寡君。如果还不丢弃鲁国，而承您向周公求福，让寡君能够事奉晋国国君，那么这两个人，是鲁国的社稷之臣。如果早晨去掉他们，鲁国必然晚上灭亡。鲁国靠近晋国的仇敌，灭亡了以后就会变成仇敌，还来得及补救吗？”郤犫说：“我为您请求封邑。”声伯回答说：“婴齐，是鲁国的小臣，岂敢仗恃大国以求取丰厚的官禄？我奉了寡君的命令前来请求，如果得到所请求的，您的恩赐就很多了，还有什么请求？”范文子对栾武子说：“季孙在鲁国，辅助过两个国君。妾不穿丝绸，马不吃粮食，难道他不是忠诚吗？相信奸邪而丢弃忠良，怎么对付诸侯？子叔婴齐接受国君的命令没有私心，为国家谋划也没有二心，为自己打算而不忘国君。如果拒绝他的请求，这是丢弃善人啊！您还是考虑一下吧！”于是允许鲁国讲和，赦免了季孙行父。
冬季，十月，放逐叔孙侨如并且和大夫们结盟。侨如逃亡到齐国。
十二月，季孙和郤犫在扈地结盟。回国，暗杀了公子偃，把叔孙豹从齐国召回而立了他。
齐国的声孟子和侨如私通，让他位于高氏、国氏之间。侨如说：“不能再犯罪了。”便逃亡到卫国，也位于各卿之间。
晋厉公派遣郤至到成周去献对楚国作战的战利品，郤至和单襄公说话，屡次夸耀自己的功劳。单襄公对大夫们说：“郤至恐怕要被杀吧！他的地位在七个人之下，而想要盖过他的上级。聚集怨恨，这是祸乱的根本。多招怨恨，是自造祸乱的阶梯，怎么还能据有官位？《夏书》说：‘怨恨难道只是在看得到的地方？看不到的倒是应该考虑。’这是说在细微之处也要谨慎。现在郤至把看不到的怨恨都变得明显了，这样可以吗？”', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b680bc98d685fd9d8df73", "shortContent": "公元前578年，晋国在麻隧之战中战胜了秦国，一时国威大振，中原中小诸侯国大都听命于晋，惟有郑国仍然以楚为后盾，与晋对抗，因此晋处心积虑地要打败楚、郑，以进一步巩固自己的霸权。这场多国卷入的大战终于在成公十六年（前575年）于鄢陵（今河南鄢陵西南）爆发。战争以楚方的败北而告终，在此后一段相当长的时期内楚国再也无力北向争霸。\n\n《左传》作者左丘明始终把战争看成是两方综合国力的较量，尽管他有时对占卜表现...", "authors": ["贺圣迪", "魏自厚"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559038717, '5cec9a787b968a007671956e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643017, '左传 · 成公 · 成公十七年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有七年春，卫北宫括帅师侵郑。夏，公会尹子、单子、晋侯、齐侯、宋公、卫侯、曹伯、邾人伐郑。六月乙酋，同盟于柯陵。秋，公至自会。齐高无咎出奔莒。九月辛丑，用郊。晋侯使荀罃来乞师。冬，公会单子、晋侯、宋公、卫侯、曹伯、齐人、邾人伐郑。十有一月，公至自伐郑。壬申，公孙婴卒于狸脤。十有二月丁巳朔，日有食之。邾子玃且卒。晋杀其大夫郤錡、郤犨、郤至。楚人灭舒庸。
【传】十七年春，王正月，郑子驷侵晋虚、滑。卫北宫括救晋，侵郑，至于高氏。
夏五月，郑大子髡顽、侯孺为质于楚，楚公子成、公子寅戍郑。公会尹武公、单襄公及诸侯伐郑，自戏童至于曲洧。
晋范文子反自鄢陵，使其祝宗祈死，曰：「君骄侈而克敌，是天益其疾也。难将作矣！爱我者惟祝我，使我速死，无及于难，范氏之福也。」六月戊辰，士燮卒。
乙酉同盟于柯陵，寻戚之盟也。
楚子重救郑，师于首止。诸侯还。
齐庆克通于声孟子，与妇人蒙衣乘辇而入于闳。鲍牵见之，以告国武子，武子召庆克而谓之。庆克久不出，而告夫人曰：「国子谪我！」夫人怒。国子相灵公以会，高、鲍处守。及还，将至，闭门而索客。孟子诉之曰：「高、鲍将不纳君，而立公子角。国子知之。」秋七月壬寅，刖鲍牵而逐高无咎。无咎奔莒，高弱以卢叛。齐人来召鲍国而立之。
初，鲍国去鲍氏而来为施孝叔臣。施氏卜宰，匡句须吉。施氏之宰，有百室之邑。与匡句须邑，使为宰。以让鲍国，而致邑焉。施孝叔曰：「子实吉。」对曰：「能与忠良，吉孰大焉！」鲍国相施氏忠，故齐人取以为鲍氏后。仲尼曰：「鲍庄子之知不如葵，葵犹能卫其足。」
冬，诸侯伐郑。十月庚午，围郑。楚公子申救郑，师于汝上。十一月，诸侯还。
初，声伯梦涉洹，或与己琼瑰，食之，泣而为琼瑰，盈其怀。从而歌之曰：「济洹之水，赠我以琼瑰。归乎！归乎！琼瑰盈吾怀乎！」惧不敢占也。还自郑，壬申，至于狸脤而占之，曰：「余恐死，故不敢占也。今众繁而从余三年矣，无伤也。」言之，之莫而卒。
齐侯使崔杼为大夫，使庆克佐之，帅师围卢。国佐从诸侯围郑，以难请而归。遂如卢师，杀庆克，以谷叛。齐侯与之盟于徐关而复之。十二月，卢降。使国胜告难于晋，待命于清。
晋厉公侈，多外嬖。反自鄢陵，欲尽去群大夫，而立其左右。胥童以胥克之废也，怨郤氏，而嬖于厉公。郤錡夺夷阳五田，五亦嬖于厉公。郤犨与长鱼矫争田，执而梏之，与其父母妻子同一辕。既，矫亦嬖于厉公。栾书怨郤至，以其不从己而败楚师也，欲废之。使楚公子伐告公曰：「此战也，郤至实召寡君。以东师之未至也，与军帅之不具也，曰：『此必败！吾因奉孙周以事君。』」公告栾书，书曰：「其有焉！不然，岂其死之不恤，而受敌使乎？君盍尝使诸周而察之？」郤至聘于周，栾书使孙周见之。公使觇之，信。遂怨郤至。
厉公田，与妇人先杀而饮酒，后使大夫杀。郤至奉豕，寺人孟张夺之，郤至射而杀之。公曰：「季子欺余。」
厉公将作难，胥童曰：「必先三郤，族大多怨。去大族不逼，敌多怨有庸。」公曰：「然。」郤氏闻之，郤錡欲攻公，曰：「虽死，君必危。」郤至曰：「人所以立，信、知、勇也。信不叛君，知不害民，勇不作乱。失兹三者，其谁与我？死而多怨，将安用之？君实有臣而杀之，其谓君何？我之有罪，吾死后矣！若杀不辜，将失其民，欲安，得乎？待命而已！受君之禄是以聚党。有党而争命，罪孰大焉！」
壬午，胥童、夷羊五帅甲八百，将攻郤氏。长鱼矫请无用众，公使清沸魋助之，抽戈结衽，而伪讼者。三郤将谋于榭。矫以戈杀驹伯、苦成叔于其位。温季曰：「逃威也！」遂趋。矫及诸其车，以戈杀之，皆尸诸朝。
胥童以甲劫栾书、中行偃于朝。矫曰：「不杀二子，忧必及君。」公曰：「一朝而尸三卿，余不忍益也。」对曰：「人将忍君。臣闻乱在外为奸，在内为轨。御奸以德，御轨以刑。不施而杀，不可谓德。臣逼而不讨，不可谓刑。德刑不立，奸轨并至。臣请行。」遂出奔狄。公使辞于二子，曰：「寡人有讨于郤氏，既伏其辜矣。大夫无辱，其复职位。」皆再拜稽首曰：「君讨有罪，而免臣于死，君之惠也。二臣虽死，敢忘君德。」乃皆归。公使胥童为卿。
公游于匠丽氏，栾书、中行偃遂执公焉。召士□，士□辞。召韩厥，韩厥辞，曰：「昔吾畜于赵氏，孟姬之谗，吾能违兵。古人有言曰：『杀老牛莫之敢尸。』而况君乎？二三子不能事君，焉用厥也！」
舒庸人以楚师之败也，道吴人围巢，伐驾，围厘、虺，遂恃吴而不设备。楚公子櫜师袭舒庸，灭之。
闰月乙卯晦，栾书、中行偃杀胥童。民不与郤氏，胥童道君为乱，故皆书曰：「晋杀其大夫。」
', '', '', '十七年春季，周王朝历法的正月，郑国子驷进攻晋国的虚、滑两地。卫国的北宫括救援晋国，侵袭郑国，到达高氏。
夏季，五月，郑国太子髡顽和侯卻獳到楚国作为人质，楚国公子成、公子寅戍守在郑国。鲁成公会合尹武公、单襄公以及诸侯进攻郑国，从戏童到达曲洧。
晋国的范文子从鄢陵回国，让他的祝宗祈求早点死去，说：“国君骄横奢侈而又战胜敌人，这是上天增加他的毛病，祸难将要起来了。爱我的人只有诅咒我，让我快点死去，不要及于祸难，这就是范氏的福气。”六月初九日，”范文子死。
六月二十六日，鲁成公和尹子、单子、晋厉公、齐灵公、宋平公、卫献公、曹成公、邾国人在柯陵结盟，这是为了重温戚地的盟会。
楚国的子重援救郑国，军队驻扎在首止。诸侯就退兵回国。
齐国的庆克和声孟子私通，穿着女人衣服和女人一起坐辇进入宫中的夹道门。鲍牵见到了，报告国武子。武子把庆克召来告诉他。庆克躲在家里很久不出门，报告声孟子说：“国子责备我。”声孟子发怒。国武子作为齐灵公的相礼参加会见，高无咎、鲍牵留守。等到回国，将要到达的时候，关闭城门，检查旅客。声孟子诬陷说：“高、鲍两人打算不接纳国君而立公子角，国子参与这件事。”秋季，七月十三日，砍去了鲍牵的双脚而驱逐了高无咎。高无咎逃亡到莒国。高弱据有卢地而发动叛乱。齐国人来鲁国召回鲍国而立了他。
当初，鲍国离开鲍氏来鲁国做施孝叔的家臣。施氏占卜总管的人选，匡句须吉利。施氏的总管拥有一百家的采邑。施氏给了匡句须采邑，让他做总管，他却让给鲍国而且把采邑也给了鲍国。施孝叔说：“你是占卜认为吉利的。”匡句须回答说：“能够给忠良，还有比这再大的吉利吗？”鲍国辅助施氏很忠诚，所以齐国人把他召回去作为鲍氏的后嗣。孔子说：“鲍牵的聪明不如葵菜，葵菜还能保护自己的脚。”
冬季，诸侯进攻郑国。十月十二日，包围郑国。楚国公子申救援郑国，军队驻扎在汝水边上。十一月，诸侯退兵回国。
当初，声伯梦见步行渡过洹水，有人将琼瑰给他吃了，哭出来的眼泪都成了琼瑰装满怀抱，跟着唱歌说：“渡过洹水，赠给我琼瑰。回去吧回去吧，琼瑰装满我的怀内！”醒来由于害怕而不敢占卜。从郑国回来，十一月某一天，到达狸脤，而占卜这件事，说：“我害怕死，所以不敢占卜。现在大家跟随我已经三年了，没有妨碍了。”说了这件事，到晚上就死了。
齐灵公派崔杼做大夫，派庆克辅佐他，率领军队包围卢地。国佐跟从诸侯包围郑国，由于齐国发生祸难请求回国。国佐于是就到了包围卢地的军队里，杀了庆克，据有穀地而发动叛乱。齐灵公和国佐在徐关结盟以后，恢复了他的官位。十二月，卢地人投降。齐灵公派遣国胜向晋国报告祸难，并且让他在清地等候命令。
晋厉公奢侈，有很多宠信的大夫。从鄢陵回来，想要全部去掉其他的大夫，而立左右宠信的人。胥童因为胥克的被废，怨恨郤氏而成为厉公宠臣。郤犫夺走了夷阳五的土田，夷阳五也为厉公所宠信。郤犫和长鱼矫争夺土田，把长鱼矫逮捕囚禁，和他的父母妻子同系在一个车辕上。不久以后，长鱼矫也受到厉公的宠信。栾书怨恨郤至，因为他不听自己的主意而又打败了楚军，想要废掉他。栾书让楚国的公子茷告诉厉公说：“这次战役，郤至实在是召来我寡君的，因为东方的军队没有到达和晋军统帅没有完全出动，他说：‘这一战晋国必然失败，我就乘机拥立孙周来事奉君王。’”厉公告诉栾书。栾书说：“恐怕有这回事。否则，难道他会不顾虑死，而接受敌人的使者吗？君王何不试着派他到成周而考察他一下呢？”郤至到成周聘问，栾书让孙周接见他，晋厉公派人窥探，证实了。于是厉公就怨恨郤至。
晋厉公打猎，和女人一起首先射猎，并且喝酒，然后让大夫射猎。郤至奉献野猪，寺人孟张夺走野猪，郤至射死了孟张。厉公说：“郤至欺负我！”
厉公准备发动群臣讨伐郤至，胥童说：“一定要先从三郤开刀。他们族大，怨恨多。去掉大族，公室就不受逼迫；讨伐怨恨多的，容易有功。”厉公说：“对。”郤氏听到这件事，郤锜想要攻打厉公，说：“虽然我们一族就要死了，国君也必定危险了。”郤至说：“人能站得住，是由于有信用、明智、勇敢。有信用不能背叛国君，明智不能残害百姓，勇敢不能发动祸难。没有这三样，还有谁亲近我们？死了又增多怨恨，还有什么用？国君有了臣下而杀了他们，能把国君怎么办？我若有罪，死得已经晚了。如果国君杀害的是无罪的人，他将要失掉百姓，想要安定，行吗？还是听候命令吧。受了国君的禄位，因此才能聚集亲族。有了亲族而和国君相争，还有比这更大的罪过吗？”
十二月二十六日，胥童、夷羊五率领甲士八百人准备进攻郤氏，长鱼矫请求不要兴师动众，晋厉公派清沸魋去帮助他们。长鱼矫和清沸魋抽出戈来，衣襟相结，装成打架争讼的样子。三郤准备在台榭里和他们计议，长鱼矫乘机用戈在座位上刺死了郤锜和郤犫。郤至说：“无罪被杀，不如逃走。”于是赶快逃走。长鱼矫追上郤至的车子，用戈刺死了他。都陈尸在朝廷上。
胥童带领甲士在朝廷上劫持了栾书、中行偃。长鱼矫说：“不杀这两个人，忧患必然会到国君身上。”晋厉公说：“一天之中而把三个卿的尸摆在朝上，我不忍心增加了。”长鱼矫回答说：“别人对君王会忍心的。下臣听说祸乱在外就是奸，在内就是轨。用德行来对待奸，用刑罚来对待轨。不施教化就加以杀戮，不能叫做德行；臣下逼迫国君而不加讨伐，不能叫做刑罚。德行和刑罚不加树立，奸、轨就一起来了，下臣请求离去。”于是就逃亡到狄人那里。厉公派人向栾书和中行偃辞谢说：“寡人讨伐郤氏，郤氏已经伏罪，大夫不要把劫持的事作为耻辱，还是各复其位吧！”他们都再拜叩头说：“君王讨伐有罪的人，而赦免下臣一死，这是君王的恩惠。我们两个人即使死了，哪里敢忘记君王的恩德？”于是都回去了。晋厉公派胥童做卿。
晋厉公在匠丽氏那里游玩，栾书、中行偃就乘机抓住了他。召唤士匄，士匄辞谢。召唤韩厥，韩厥辞谢说：“从前我在赵氏家里养大，孟姬诬陷赵氏，我能顶住不出兵。古人有话说，‘杀老牛没有人敢作主’，何况是国君呢？您几位不能事奉国君，又哪里用得到厥呢？”
舒庸人由于楚军的战败，引导吴国人包围巢地，进攻驾地，包围厘地和虺地，因此就依仗着吴国而不设防。楚国公子槖师入侵舒庸，灭亡了舒庸。
闰月二十九日，栾书、中行偃杀了胥童。百姓不亲附郤氏，胥童引导国君作乱，所以《春秋》都记载说“晋杀其大夫”。', NULL, '', 'indent', 1559038762, '5cec9aa4ba39c800688ad159', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643018, '左传 · 成公 · 成公十八年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有八年春王正月，晋杀其大夫胥童。庚申，晋弑其君州蒲。齐杀其大夫国佐。公如晋。夏，楚子、郑伯伐宋。宋鱼石复入于彭城。公至自晋。晋侯使士□来聘。秋，杞伯来朝。八月，邾子来朝，筑鹿囿。己丑，公薨于路寝。冬，楚人、郑人侵宋。晋侯使士鲂来乞师。十有二月，仲孙蔑会晋侯、宋公、卫侯、邾子、齐崔杼同盟于虚朾。丁未，葬我君成公。
【传】十八年春，王正月庚申，晋栾书、中行偃使程滑弑厉公，葬之于翼东门之外，以车一乘。使荀罃、士鲂逆周子于京师而立之，生十四年矣。大夫逆于清原，周子曰：「孤始愿不及此。虽及此，岂非天乎！抑人之求君，使出命也，立而不从，将安用君？二三子用我今日，否亦今日，共而从君，神之所福也。」对曰：「群臣之愿也，敢不唯命是听。」庚午，盟而入，馆于伯子同氏。辛巳，朝于武宫，逐不臣者七人。周子有兄而无慧，不能辨菽麦，故不可立。
齐为庆氏之难故，甲申晦，齐侯使士华免以戈杀国佐于内宫之朝。师逃于夫人之宫。书曰：「齐杀其大夫国佐。」弃命，专杀，以谷叛故也。使清人杀国胜。国弱来奔，王湫奔莱。庆封为大夫，庆佐为司寇。既，齐侯反国弱，使嗣国氏，礼也。
二月乙酉朔，晋侯悼公即位于朝。始命百官，施舍、己责，逮鳏寡，振废滞，匡乏困，救灾患，禁淫慝，薄赋敛，宥罪戾，节器用，时用民，欲无犯时。使魏相、士鲂、魏颉、赵武为卿。荀家、荀会、栾□、韩无忌为公族大夫，使训卿之子弟共俭孝弟。使士渥浊为大傅，使修范武子之法。右行辛为司空，使修士蒍之法。弁纠御戎，校正属焉，使训诸御知义。荀宾为右，司士属焉，使训勇力之士时使。卿无共御，立军尉以摄之。祁奚为中军尉，羊舌职佐之，魏绛为司马，张老为候奄。铎遏寇为上军尉，籍偃为之司马，使训卒乘亲以听命。程郑为乘马御，六驺属焉，使训群驺知礼。凡六官之长，皆民誉也。举不失职，官不易方，爵不逾德，师不陵正，旅不逼师，民无谤言，所以复霸也。
公如晋，朝嗣君也。
夏六月，郑伯侵宋，及曹门外。遂会楚子伐宋，取朝郏。楚子辛、郑皇辰侵城郜，取幽丘，同伐彭城，纳宋鱼石、向为人、鳞朱、向带、鱼府焉，以三百乘戍之而还。书曰「复入」，凡去其国，国逆而立之，曰「入」；复其位，曰「复归」；诸侯纳之，曰「归」。以恶曰复入。宋人患之。西锄吾曰：「何也？若楚人与吾同恶，以德于我，吾固事之也，不敢贰矣。大国无厌，鄙我犹憾。不然，而收吾憎，使赞其政，以间吾衅，亦吾患也。今将崇诸侯之奸，而披其地，以塞夷庚。逞奸而携服，毒诸侯而惧吴、晋。吾庸多矣，非吾忧也。且事晋何为？晋必恤之。」
公至自晋。晋范宣子来聘，且拜朝也。君子谓：「晋于是乎有礼。」
秋，杞桓公来朝，劳公，且问晋故。公以晋君语之。杞伯于是骤朝于晋而请为昏。
七月，宋老佐、华喜围彭城，老佐卒焉。
八月，邾宣公来朝，即位而来见也。
筑鹿囿，书，不时也。
己丑，公薨于路寝，言道也。
冬十一月，楚子重救彭城，伐宋，宋华元如晋告急。韩献子为政，曰：「欲求得人，必先勤之，成霸安强，自宋始矣。」晋侯师于台谷以救宋，遇楚师于靡角之谷。楚师还。
晋士鲂来乞师。季文子问师数于臧武仲，对曰：「伐郑之役，知伯实来，下军之佐也。今彘季亦佐下军，如伐郑可也。事大国，无失班爵而加敬焉，礼也。」从之。
十二月，孟献子会于虚朾，谋救宋也。宋人辞诸侯而请师以围彭城。孟献子请于诸侯，而先归会葬。
丁未，葬我君成公，书，顺也。', '', '', '十八年春季，周王朝历法的正月初五日，晋国的栾书、中行偃派程滑杀死晋厉公，葬在翼地的东门外边，仅仅用了一辆车子。派遣荀罃、士鲂到京师迎接周子而立他为国君，这时周子才十四岁。大夫在清原迎接，周子说：“我开始的愿望并没有到这地步，现在虽然到了这地步，难道不是上天的意志吗？然而人们要求有国君，这是为了让他发布命令。立了以后又不听他的，还哪里用得着国君？您几位用得着我，在今天；用不着，也在今天，恭敬而听从国君，这是神灵所保佑的。”大夫们回答说：“这是下臣们的愿望，岂敢不唯命是听。”十五日，结盟以后才进入国都，住在伯子同氏家里。二十六日，周子在武宫朝见。驱逐了不适合做臣的七个人。周子有一个哥哥是白痴，不能辨别豆子和麦子，所以不能立为国君。
齐国由于庆氏祸难的缘故，正月二十九日，齐灵公派士华免用戈把国佐杀死在内宫的前堂，大家逃到夫人的宫里。《春秋》记载说“齐杀其大夫国佐”，这是由于国佐丢弃君命、专权杀人、据有穀地而叛变的缘故。让清地人杀了国胜。国弱逃亡到鲁国来。王湫逃亡到莱地。庆封做大夫，庆佐做司寇。不久以后，齐灵公让国弱回国，要他继承国氏宗嗣，这是合于礼的。
二月初一日，晋悼公在朝廷上即位。开始任命百官，赐舍财物而免除百姓对国家的欠债，照顾施恩惠给鳏夫寡妇，起用被废黜和长居下位的好人，救济贫困，援救灾难，禁止邪恶，少征赋税，宽恕罪过，节约器用，在农闲时使用农民，个人的欲望不侵占农时。派魏相、士鲂、魏颉、赵武做卿；荀家、荀会、栾黡、韩无忌做公族大夫，让他们教育卿的子弟恭敬、节俭、孝顺、友爱。派士渥浊做太傅，让他学习范武子的法度；右行辛做司空，让他学习士？的法度。弁纠驾御战车，校正官属他管辖，让他教育御者们明白道理。荀宾作为车右，司士官属他管辖，让他教育勇士们待时选用。卿没有固定的御者，设立军尉兼管这些事。祁奚做中军尉，羊舌职辅佐他；魏绛做司马，张老做侦察长，铎遏寇做上军尉，籍偃为他做司马，让他教育步兵车兵，一致听从命令。程郑做乘马御，六驺属他管辖，让他教育他们明白礼仪。凡是各部门的长官，都是百姓赞扬的人。举拔的人不失职，做官的人不改变常规，爵位不超过德行，师不欺陵正，旅不逼迫师，百姓没有指责的话，这就是晋悼公再次称霸于诸侯的原因。
鲁成公去到晋国，朝见新立的国君晋悼公。
夏季，六月，郑成公入侵宋国，到达宋国曹门外。于是就会合楚共王一起进攻宋国，占领了朝郏。楚国子辛、郑国的皇辰入侵城郜，占取幽丘。一起进攻彭城，送回了宋国的鱼石、向为人、鳞朱、向带、鱼府，用三百辆战车留守，然后回国。《春秋》记载说“复入”。凡是离开自己的国家，本国迎接而且立他，叫做“入”；回复原来的位置，叫做“复归”；诸侯把他送回来，叫做“归”；用武力的叫做“复入”。宋国人担心这件事。西锄吾说：“担心干什么？如果楚国人和我们同仇敌忾，施恩德给我们，我们本来是会事奉他们的，不敢有三心二意。现在大国的欲望没有个止境，即使把我国作为他们的边邑还会觉得遗憾。否则，收留我们讨厌的人，让他们辅助政事，等机会钻我们的空子，也是我们的祸害。现在却尊崇诸侯的乱臣而且分给他们以土地，阻塞各国之间的通道，使乱臣得以快意而使服从他们的国家离心，毒害诸侯而使吴国，晋国恐惧，这样，我们的利益多啦，并不是我们的忧患。而且事奉晋国为了什么？晋国必然会来救助我们。”
鲁成公从晋国回到鲁国。晋国的范宣子来鲁国聘问，同时答拜对晋君的朝见。君子认为晋国在这件事情上合于礼。
秋季，杞桓公前来朝见，慰劳成公，同时询问晋国的消息。成公把晋君的政治措施告诉他。杞桓公因此很快地向晋国朝见并请求通婚。
七月，宋国的老佐、华喜包围彭城，老佐死于这次战役中。
八月，邾宣公前来朝见，这是由于他新即位而前来进见。
鲁国建造鹿囿，《春秋》所以记载这件事，是由于不合于时令。
初七日，鲁成公死在寝宫里，这是说合于正常的情况。
冬季，十一月，楚国的子重救援彭城，进攻宋国。宋国的华元去到晋国告急。这时韩献子执政，说：“想要得到别人的拥护，一定要先为他付出勤劳。成就霸业，安定疆土，从宋国开始了。”晋悼公领兵驻扎在台谷以救宋国。在靡角之谷和楚军相遇，楚军退走回国。
晋国的士鲂前来请求出兵。季文子向臧武仲问出兵的数字，他回答说：“攻打郑国那次战役，是知伯来请求出兵的，他是下军的辅佐。现在士鲂也辅佐下军，所出兵数，像攻打郑国时一样就可以了。事奉大国，不要违背使者的爵位次序而要更加恭敬，这是合于礼的。”季文子听从了。
十二月，孟献子和晋悼公、宋平公、卫献公、邾宣公、齐国崔杼在虚朾会见，策划救援宋国。宋国人辞谢诸侯，而请求出兵以包围彭城。孟献子向诸侯请求先回国参加葬礼。
十二月二十六日，“葬我君成公”，《春秋》这样说，是表示一切安排顺当。', NULL, '', 'indent', 1559038802, '5cec9acea673f5006821bcf8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643019, '左传 · 襄公 · 襄公元年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】元年春王正月，公即位。仲孙蔑会晋栾□、宋华元、卫宁殖、曹人、莒人、邾人、滕人、薛人围宋彭城。夏，晋韩厥帅师伐郑，仲孙蔑会齐崔杼、曹人、邾人、杞人次于鄫。秋，楚公子壬夫帅师侵宋。九月辛酉，天王崩。邾子来朝。冬，卫侯使公孙剽来聘。晋侯使荀罃来聘。
【传】元年春己亥，围宋彭城。非宋地，追书也。于是为宋讨鱼石，故称宋，且不登叛人也，谓之宋志。彭城降晋，晋人以宋五大夫在彭城者归，置诸瓠丘。齐人不会彭城，晋人以为讨。二月，齐大子光为质于晋。
夏五月，晋韩厥、荀偃帅诸侯之师伐郑，入其郛，败其徒兵于洧上。于是东诸侯之师次于鄫，以待晋师。晋师自郑以鄫之师侵楚焦夷及陈，晋侯、卫侯次于戚，以为之援。
秋，楚子辛救郑，侵宋吕、留。郑子然侵宋，取犬丘。
九月，邾子来朝，礼也。
冬，卫子叔、晋知武子来聘，礼也。凡诸侯即位，小国朝之，大国聘焉，以继好结信，谋事补阙，礼之大者也。
', '', '', '元年春季，正月己亥这一天，诸侯军队包围宋国彭城。彭城已经不属于宋国的地方了，《春秋》所以这样记载，这是追记以前的情况。当时为了宋国去讨伐鱼石，所以仍称宋国，而且反对叛变者，这是宋国人的意志。彭城投降晋国，晋国人带了在彭城的五个宋国大夫回去，安置在瓠丘。齐国人没有在彭城会合，晋国人因此讨伐齐国。二月，齐太子光到晋国作为人质。
夏季，五月，晋国韩厥、荀偃率领诸侯的军队进攻郑国，进入它的外城，在洧水边上打败了它的步兵。在这时候东方各诸侯国的军队驻扎在鄫地，等待晋军。晋军从郑国带领驻在鄫地的军队入侵楚国的焦地、夷地和陈国。晋悼公、卫献公住在戚地，作为后援。
秋季，楚国子辛救援郑国，入侵宋国的吕地和留地。郑国子然入侵宋国，占取了犬丘。
九月，邾宣公来鲁国朝见，这是合于礼的。
冬季，卫国子叔、晋国知武子来鲁国聘问，这是合于礼的。凡是诸侯即位，小国前来朝见，大国就来聘问，以继续友好、取得信任、商讨国事、补正过失，这是礼仪中的大事。
', NULL, '', 'indent', 1559038841, '5cec9af7a673f5006821be1d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643020, '左传 · 襄公 · 襄公二年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二年春王正月，葬简王。郑师伐宋。夏五月庚寅，夫人姜氏薨。六月庚辰，郑伯仑卒。晋师、宋师、卫宁殖侵郑。秋七月，仲孙蔑会晋荀罃、宋华元、卫孙林父、曹人、邾人于戚。己丑，葬我小君齐姜。叔孙豹如宋。冬，仲孙蔑会晋荀罃、齐崔杼、宋华元、卫孙林父、曹人、邾人、滕人、薛人、小邾人于戚，遂城虎牢。楚杀其大夫公子申。
【传】二年春，郑师侵宋，楚令也。
齐侯伐莱，莱人使正舆子赂夙沙卫以索马牛，皆百匹，齐师乃还。君子是以知齐灵公之为「灵」也。
夏，齐姜薨。初，穆姜使择美檟，以自为榇与颂琴。季文子取以葬。君子曰：「非礼也。礼无所逆，妇，养姑者也，亏姑以成妇，逆莫大焉。《诗》曰：『其惟哲人，告之话言，顺德之行。』季孙于是为不哲矣。且姜氏，君之妣也。《诗》曰：『为酒为醴，烝畀祖妣，以洽百礼，降福孔偕。』」
齐侯使诸姜宗妇来送葬。召莱子，莱子不会，故晏弱城东阳以逼之。
郑成公疾，子驷请息肩于晋。公曰：「楚君以郑故，亲集矢于其目，非异人任，寡人也。若背之，是弃力与言，其谁昵我？免寡人，唯二三子！」
秋七月庚辰，郑伯仑卒。于是子罕当国，子驷为政，子国为司马。晋师侵郑，诸大夫欲从晋。子驷曰：「官命未改。」 　　会于戚，谋郑故也。孟献子曰：「请城虎牢以逼郑。」知武子曰：「善。鄫之会，吾子闻崔子之言，今不来矣。滕、薛、小邾之不至，皆齐故也。寡君之忧不唯郑。罃将复于寡君，而请于齐。得请而告，吾子之功也。若不得请，事将在齐。君子之请，诸侯之福也，岂唯寡君赖之。」
穆叔聘于宋，通嗣君也。
冬，复会于戚，齐崔武子及滕、薛、小邾之大夫皆会，知武子之言故也。遂城虎牢，郑人乃成。
楚公子申为右司马，多受小国之赂，以逼子重、子辛，楚人杀之。故书曰：「楚杀其大夫公子申。」', '', '', '二年春季，郑国的军队侵袭宋国，这是受楚国的命令。
齐灵公进攻莱国，莱国人派正舆子把精选的马和牛各一百匹赠送给夙沙卫，齐军就退兵回去。君子因此而知道了齐灵公所以谥为“灵”的缘故。
夏季，齐姜去世。当初，穆姜派人选择上好的槚木，为自己作了内棺和颂琴，季文子把它拿来安葬齐姜。君子说：“这是不合于礼的，礼不能有所不顺。媳妇是奉养婆婆的人，亏损婆婆以成全了媳妇，没有比这再大的不顺了。《诗》说：‘只有明智的人，才可以把好话告诉他，要他顺着道德而行事。’季孙在这件事情上就很不明智了，而且穆姜还是国君的祖母。《诗》说：‘酿造甜酒，敬献祖妣，合于礼仪，遍降福气。’”
齐灵公派遣嫁给齐大夫的宗女和同姓大夫的妻子前来鲁国送葬，召见莱子。莱子不参加会见，所以晏弱在东阳筑城来逼迫莱国。
郑成公生病，子驷请求服从晋国来解除对楚国的负担。郑成公说：“楚国的国君由于郑国的缘故，他的眼睛被箭射中。不是为了别人，是为了我啊！如果背弃他，这是丢弃了人家的功劳和自己的誓言，还有谁来亲近我？使我免于过错，就是看你们几位的了。”
秋季，七月庚辰，郑成公仑去世。于是由子罕掌政，由子驷处理政务，子国出任司马。当时晋军侵略郑国，郑大夫都主张服从晋国。子驷说：“国君的命令没有改变。”
仲孙蔑和晋国荀罃、宋国华元、卫国孙林父、曹国人、邾国人在戚地会见，这是为了商讨征服郑国的办法。仲孙蔑说：“请在虎牢筑城以逼迫郑国。”知武子说：“好。鄫地的盟会，您听到了齐国代表崔杼的话，现在他不来了。滕国、薛国、小邾国的都不来了，都是由于齐国的缘故。寡君的忧虑不仅在于郑国。罃准备向寡君报告并向齐国请求会见。得到允许后而告诉诸侯在虎牢筑城，这是大夫的功劳。如果得不到允许，战争就会在齐国发生。大夫的请求，是诸侯的福气，岂独寡君依靠这些？”
穆叔到宋国聘问，通告新君即位的事。
冬季，再次在戚地会见，齐国的崔武子和滕国、薛国、小邾国的大夫都参加会见，这是由于知武子这一番话的缘故。于是就在虎牢筑城。郑国人这才要求讲和。
楚国的公子申做右司马，接受了小国很多财礼，以逼迫子重、子辛。楚国人杀了他，所以《春秋》记载说“楚杀其大夫公子申。”', NULL, '', 'indent', 1559038882, '5cec9b1e43e78c0067206bb9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643021, '左传 · 襄公 · 襄公三年', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三年春，楚公子婴齐帅师伐吴。公如晋。夏四月壬戌，公及晋侯盟于长樗。公至自晋。六月，公会单子、晋侯、宋公、卫侯、郑伯、莒子、邾子、齐世子光。己未，同盟于鸡泽。陈侯使袁侨如会。戊寅，叔孙豹及诸侯之大夫及陈袁侨盟。秋，公至自会。冬，晋荀罃帅师伐许。
【传】三年春，楚子重伐吴，为简之师，克鸠兹，至于衡山。使邓廖帅组甲三百、被练三千以侵吴。吴人要而击之，获邓廖。其能免者，组甲八十、被练三百而已。子重归，既饮至，三日，吴人伐楚，取驾。驾，良邑也。邓廖，亦楚之良也。君子谓：「子重于是役也，所获不如所亡。」楚人以是咎子重。子重病之，遂遇心病而卒。
公如晋，始朝也。夏，盟于长樗。孟献子相，公稽首。知武子曰：「天子在，而君辱稽首，寡君惧矣。」孟献子曰：「以敝邑介在东表，密迩仇雠，寡君将君是望，敢不稽首？」
晋为郑服故，且欲修吴好，将合诸侯。使士□告于齐曰：「寡君使□，以岁之不易，不虞之不戒，寡君愿与一二兄弟相见，以谋不协，请君临之，使□乞盟。」齐侯欲勿许，而难为不协，乃盟于耏外。
祁奚请老，晋侯问嗣焉。称解狐，其仇也，将立之而卒。又问焉，对曰：「午也可。」于是羊舌职死矣，晋侯曰：「孰可以代之？」对曰：「赤也可。」于是使祁午为中军尉，羊舌赤佐之。君子谓：「祁奚于是能举善矣。称其仇，不为谄。立其子，不为比。举其偏，不为党。《商书》曰：『无偏无党，王道荡荡。』其祁奚之谓矣！解狐得举，祁午得位，伯华得官，建一官而三物成，能举善也！夫唯善，故能举其类。《诗》云：『惟其有之，是以似之。』祁奚有焉。」
六月，公会单顷公及诸侯。己未，同盟于鸡泽。
晋侯使荀会逆吴子于淮上，吴子不至。
楚子辛为令尹，侵欲于小国。陈成公使袁侨如会求成，晋侯使和组父告于诸侯。秋，叔孙豹及诸侯之大夫及陈袁侨盟，陈请服也。
晋侯之弟扬干乱行于曲梁，魏绛戮其仆。晋侯怒，谓羊舌赤曰：「合诸侯以为荣也，扬干为戮，何辱如之？必杀魏绛，无失也！」对曰：「绛无贰志，事君不辟难，有罪不逃刑，其将来辞，何辱命焉？」言终，魏绛至，授仆人书，将伏剑。士鲂、张老止之。公读其书曰：「日君乏使，使臣斯司马。臣闻师众以顺为武，军事有死无犯为敬。君合诸侯，臣敢不敬？君师不武，执事不敬，罪莫大焉。臣惧其死，以及扬干，无所逃罪。不能致训，至于用金戊。臣之罪重，敢有不从，以怒君心，请归死于司寇。」公跣而出，曰：「寡人之言，亲爱也。吾子之讨，军礼也。寡人有弟，弗能教训，使干大命，寡人之过也。子无重寡人之过，敢以为请。」
晋侯以魏绛为能以刑佐民矣，反役，与之礼食，使佐新军。张老为中军司马，士富为候奄。
楚司马公子何忌侵陈，陈叛故也。
许灵公事楚，不会于鸡泽。冬，晋知武子帅师伐许。', '', '', '三年春季，楚国的子重率军进攻吴国，选择了一支经过演习的军队。攻克鸠兹，到达衡山。派遣邓廖率领穿组甲的车兵三百人、穿被练的步兵三千人以侵袭吴国。吴军拦阻攻击楚军，俘掳了邓廖。免于死及被俘的只有车兵八十人、被练的步兵三百人而已。子重回国，在太庙庆祝慰劳，三天后，吴国人攻打楚国，占领了驾地。驾地，是好的城邑；邓廖，也是楚国的良将。君子认为：“子重在这次战役中，所得到的不如所失去的。”楚国人因此责备子重。子重很不痛快，就碰上心脏病发作而死去。
鲁襄公到晋国，这是初次去朝见。夏季，在长樗会盟，孟献子作为相礼者。襄公行叩头礼。知武子说：“有天子在那里，而承贵君行叩头的大礼，寡君感到害怕。”孟献子说：“由于敝邑地近东海，紧挨着仇敌，寡君将要仰望贵君协助，哪里敢不叩头呢？”
晋国由于郑国顺服的缘故，又想要和吴国修好，准备会合诸侯。派遣士匄向齐国报告说：“寡君派匄前来，是由于近年来各国之间纠纷不少，对意外的事情又没有戒备，寡君愿意和几位兄弟相见，来商讨解决彼此的不和睦。请君王光临，派匄来请求结盟。”齐灵公本想不答应，而又难于表示不和睦，就在耏水之外结盟。
祁奚请求告老退休，晋悼公问谁来接替他。祁奚称道解狐。解狐，是祁奚的仇人，晋悼公打算任命解狐，他却死了。晋悼公又问祁奚，祁奚回答说：“祁午也可以胜任。”这时羊舌职死了，晋悼公说：“谁可以接代他？”祁奚回答说：“羊舌赤也可以胜任。”因此，晋悼公就派遣祁午做中军尉，羊舌赤为副职。君子认为：“祁奚在这种情况下能够推举有德行的人。举荐他的仇人而不是谄媚，推荐他的儿子而不是自私，推举他的副手而不是结党。《商书》说：‘不偏私不结党，君王之道浩浩荡荡。’这说的就是祁奚啊。解狐得到推荐，祁午得到安排，羊舌赤能有官位，建立一个官位而成全三件事，这是由于能够推举贤能的人的缘故啊。唯其有德行，才能推举类似他的好人。《诗》说，‘正因为具有美德，推举他的人才能和他相似’，祁奚就是这样的人。”
六月，鲁襄公会见单顷公和诸侯。二十三日，在鸡泽会盟。
晋悼公派遣荀会在淮水边上迎接吴子，吴子没有来。
楚国的子辛做令尹，侵害小国以满足欲望。陈成公派遣袁侨到会求和好。晋悼公派遣和组父向诸侯报告。秋季，叔孙豹和诸侯的大夫同陈国的袁侨结盟，这是由于陈国请求顺服的缘故。
晋悼公的弟弟扬干在曲梁扰乱军队的行列，魏绛杀了他的驾车人。晋悼公发怒，对羊舌赤说：“会合诸侯，是以此为光荣。扬干受到侮辱，还有什么侮辱比这更大？一定要杀掉魏绛，不要耽误了。”羊舌赤回答说：“魏绛一心为公，事奉国君不避危难，有了罪过不逃避惩罚，他大概会来说明的，何必劳动君王发布命令呢？”话刚说完，魏绛来了，把信交给仆人，准备抽剑自杀。士鲂、张老劝阻了他。晋悼公读他的上书，说：“以前君王缺乏使唤的人，让下臣担任司马的职务。下臣听说‘军队里的人服从军纪叫做武，在军队里做事宁死也不触犯军纪叫做敬’。君王会合诸侯，下臣岂敢不执行军纪军法？君王的军队不武，办事的人不敬，没有比这再大的罪过了。下臣畏惧触犯死罪，所以连累到扬干，罪责无可逃避。下臣不能够事先教导全军，以至于动用了斧钺，下臣的罪过很重，岂敢不服从惩罚来激怒君王呢？请求回去死在司寇那里。”晋悼公光着脚赶紧走出来，说：“寡人的话，是出于对兄弟的亲爱；大夫杀杨干，是出于按军法从事。寡人有弟弟，没有能够教导他，而让他触犯了军令，这是寡人的过错。您不要加重寡人的过错，谨以此作为请求。”
晋悼公认为魏绛能够用刑罚来治理百姓了，从盟会回国，在太庙设宴招待魏绛，派他为新军副帅。张老做中军司马，士富做了侦察长。
楚国的司马公子何忌率军入侵陈国，这是由于陈国背叛了楚国的缘故。
许灵公事奉楚国，不参加鸡泽的会见。冬季，晋国的知武子领兵讨伐许国。', NULL, '', 'indent', 1559038921, '5cec9b46ba39c800688ad6f5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643022, '左传 · 襄公 · 襄公四年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】四年春王三月己酉，陈侯午卒。夏，叔孙豹如晋。秋七月戊子，夫人姒氏薨。葬陈成公。八月辛亥，葬我小君定姒。冬，公如晋。陈人围顿。
【传】四年春，楚师为陈叛故，犹在繁阳。韩献子患之，言于朝曰：「文王帅殷之叛国以事纣，唯知时也。今我易之，难哉！」
三月，陈成公卒。楚人将伐陈，闻丧乃止。陈人不听命。臧武仲闻之，曰：「陈不服于楚，必亡。大国行礼焉而不服，在大犹有咎，而况小乎？」夏，楚彭名侵陈，陈无礼故也。
穆叔如晋，报知武子之聘也，晋侯享之。金奏《肆夏》之三，不拜。工歌《文王》之三，又不拜。歌《鹿鸣》之三，三拜。韩献子使行人子员问之，曰：「子以君命，辱于敝邑。先君之礼，藉之以乐，以辱吾子。吾子舍其大，而重拜其细，敢问何礼也？」对曰：「三《夏》，天子所以享元侯也，使臣弗敢与闻。《文王》，两君相见之乐也，使臣不敢及。《鹿鸣》，君所以嘉寡君也，敢不拜嘉。？《四牡》，君所以劳使臣也，敢不重拜？《皇皇者华》，君教使臣曰：『必咨于周。』臣闻之：『访问于善为咨，咨亲为询，咨礼为度，咨事为诹，咨难为谋。』臣获五善，敢不重拜？」
秋，定姒薨。不殡于庙，无榇，不虞。匠庆谓季文子曰：「子为正卿，而小君之丧不成，不终君也。君长，谁受其咎？」
初，季孙为己树六檟于蒲圃东门之外。匠庆请木，季孙曰：「略。」匠庆用蒲圃之檟，季孙不御。君子曰：「《志》所谓『多行无礼，必自及也』，其是之谓乎！」
冬，公如晋听政，晋侯享公。公请属鄫，晋侯不许。孟献子曰：「以寡君之密迩于仇雠，而愿固事君，无失官命。鄫无赋于司马，为执事朝夕之命敝邑，敝邑褊小，阙而为罪，寡君是以愿借助焉！」晋侯许之。
楚人使顿间陈而侵伐之，故陈人围顿。
无终子嘉父使孟乐如晋，因魏庄子纳虎豹之皮，以请和诸戎。晋侯曰：「戎狄无亲而贪，不如伐之。」魏绛曰：「诸侯新服，陈新来和，将观于我，我德则睦，否则携贰。劳师于戎，而楚伐陈，必弗能救，是弃陈也，诸华必叛。戎，禽兽也，获戎失华，无乃不可乎？《夏训》有之曰：『有穷后羿。』」公曰：「后羿何如？」对曰：「昔有夏之方衰也，后羿自锄迁于穷石，因夏民以代夏政。恃其射也，不修民事而淫于原兽。弃武罗、伯困、熊髡、龙圉而用寒浞。寒浞，伯明氏之谗子弟也。伯明后寒弃之，夷羿收之，信而使之，以为己相。浞行媚于内而施赂于外，愚弄其民而虞羿于田，树之诈慝以取其国家，外内咸服。羿犹不悛，将归自田，家众杀而亨之，以食其子。其子不忍食诸，死于穷门。靡奔有鬲氏。浞因羿室，生浇及豷，恃其谗慝诈伪而不德于民。使浇用师，灭斟灌及斟寻氏。处浇于过，处豷于戈。靡自有鬲氏，收二国之烬，以灭浞而立少康。少康灭浇于过，后杼灭豷于戈。有穷由是遂亡，失人故也。昔周辛甲之为大史也，命百官，官箴王阙。于《虞人之箴》曰：『芒芒禹迹，尽为九州，经启九道。民有寝庙，兽有茂草，各有攸处，德用不扰。在帝夷羿，冒于原兽，忘其国恤，而思其麀牡。武不可重，用不恢于夏家。兽臣司原，敢告仆夫。』《虞箴》如是，可不惩乎？」于是晋侯好田，故魏绛及之。
公曰：「然则莫如和戎乎？」对曰：「和戎有五利焉：戎狄荐居，贵货易土，土可贾焉，一也。边鄙不耸，民狎其野，穑人成功，二也。戎狄事晋，四邻振动，诸侯威怀，三也。以德绥戎，师徒不勤，甲兵不顿，四也。鉴于后羿，而用德度，远至迩安，五也。君其图之！」公说，使魏绛盟诸戎，修民事，田以时。
冬十月，邾人、莒人伐鄫。臧纥救鄫，侵邾，败于狐骀。国人逆丧者皆髽。鲁于是乎始髽，国人诵之曰：「臧之狐裘，败我于狐骀。我君小子，朱儒是使。朱儒！朱儒！使我败于邾。」', '', '', '四年春季，楚军由于陈国背叛的缘故，仍旧驻扎在繁阳。韩献子担心这件事，在朝廷上说：“周文王率领背叛商朝的国家去事奉纣，这是由于知道时机未到。现在我们反了过来，想要称霸，难哪！”
三月，陈成公死。楚国人正准备进攻陈国，听到陈国有丧事，就停止进攻。陈国不听从楚国的命令，臧武仲听说这种情况，说：“陈国不服从楚国，一定灭亡。大国实行礼仪而不去顺服，对大国来说尚且有灾难，何况是小国呢？”
夏季，楚国的彭名攻打陈国，这是由于陈国缺乏礼节的缘故。
穆叔去到晋国，回报知武子的聘问。晋悼公设享礼招待他。乐器演奏《肆夏》的三章，穆叔没有答拜。乐工歌唱《文王》三曲，又没有答拜。歌唱《鹿鸣》三曲，三次答拜。韩献子派行人子员去问他，说：“您奉着君王的命令光临敝邑，敝邑按先君之礼并用音乐来招待大夫。大夫舍弃重大的而三拜细小的，请问这是什么礼仪？”穆叔回答说：“《三夏》，是天子用来招待诸侯领袖的，使臣不敢听到。《文王》，是两国国君相见的音乐，使臣不敢参预。《鹿鸣》，是君王用来嘉奖寡君的，岂敢不拜谢这种嘉奖？《四牡》，是君王用来慰劳使臣的，岂敢不再拜？《皇皇者华》，君王告诫使臣说：‘一定要向忠信的人咨询。’使臣听说：‘向善人访求询问就是咨，咨询亲戚就是询，咨询礼仪就是度，咨询事情就是诹，咨询困难就是谋。’臣得到这五善，岂敢不再三拜谢？”
秋季，定姒去世。没有在祖庙内停放棺木，没有用内棺，没有举行虞祭。匠庆对季文子说：“您做正卿，但是小君的丧礼没有完成，这是让国君不能为他生母送终。国君长大后，谁将会受到责备？”
起初，季孙为自己在蒲圃的东门外边种植六棵檟木，匠庆请求用它做定姒的棺椁木料，季孙说：“简单点吧。”匠庆还是使用了蒲圃的檟木，季孙也没有阻止。君子说：“《志》所说的‘多做不合礼仪的事，祸患一定会来到自己身上’，说的就是这个吧！”
冬季，鲁襄公去到晋国听取晋国的要求。晋悼公设享礼招待襄公，襄公请求把鄫国作为鲁国的附庸，晋悼公不答应。孟献子说：“由于寡君紧挨着仇敌，还是愿意坚决事奉君王，没有耽误君王的命令。鄫国并没有向晋国的司马交纳贡赋，而君王的左右却经常对我国有所命令，我国褊窄狭小，无法满足要求就是罪过，寡君因此希望得到鄫国作为帮助。”晋悼公允许了。
楚国人让顿国乘陈国的空子而进攻陈国，所以陈国人包围了顿国。
无终子嘉父派遣孟乐去到晋国，依靠魏庄子的关系，奉献了虎豹的皮革，以请求晋国和各部戎人讲和。晋悼公说：“戎狄没有什么亲近的人而且贪婪，不如进攻他们。”魏庄子说：“诸侯新近顺服，陈国最近前来讲和，都将观察我们的行动。我们有德，就亲近我们；不这样，就背离我们。在戎人那里去用兵，楚国进攻陈国，一定不能去救援，这就是丢弃陈国了。中原诸国一定背叛我们。戎人，不过是禽兽。得到戎人而失去中原，恐怕不可以吧！《夏训》有这样的话‘有穷的后羿——’”晋悼公说：“后羿怎么样？”魏庄子回答说：“从前夏朝刚刚衰落的时候，后羿从锄地迁到穷石，依靠夏朝的百姓取代了夏朝政权。后羿仗着他的射箭技术，不致力于治理百姓而沉溺于打猎，抛弃了武罗、伯因、熊髡、尨圉等贤臣而任用寒浞。寒浞，是伯明氏的坏子弟，伯明后寒丢弃了他。后羿收养了他，信任并且使用他，作为自己的辅助。寒浞在里边对女人献媚，在外边广施财物，愚弄百姓而使后羿专以打猎为乐。扶植了奸诈邪恶，用这个取得了后羿的国和家，外部和内部都顺从归服。后羿还是不肯改悔，准备从打猎的地方回来，他的手下人把他杀了煮熟，让他的儿子吃，他的儿子不忍心吃，又被杀死在穷国的城门口。靡逃亡到有鬲氏。寒浞和后羿的妻妾生了浇和豷，仗着他的奸诈邪恶，对百姓不施恩德，派浇带兵，灭了斟灌和斟寻氏。让浇住在过地，让豷住在戈地。靡从有鬲氏那里收集两国的遗民，用以灭亡了寒促而立了少康。少康在过地灭掉了浇，后杼在戈地灭掉了豷，有穷从此就灭亡了，这是由于失去贤人的缘故。从前周朝的辛甲做太史的时候，命令百官，每人都劝诫天子的过失。在《虞人之箴》里说：‘辽远的夏禹遗迹，分为九州，开通了许多大道。百姓有屋有庙，野兽有丰茂的青草；各得其所，他们因此互不干扰。后羿身居帝位，贪恋着打猎，忘记了国家的忧患，想到的只是飞鸟走兽。武事不能太多，太多就不能扩大夏后氏的国家。主管禽兽的臣，谨以此报告君王左右的人。’《虞箴》是这样，难道能不警戒吗？”当时晋悼公喜欢打猎，所以魏庄子提到这件事。
晋悼公说：“然而再好的办法也莫过于跟戎人讲和吗？”魏庄子回答说：“跟戎人讲和有五种利益：戎狄逐水草而居，重财货而轻土地，他们的土地可以收买，这是一。边境不再有所警惧，百姓安心在田野里耕作，农田管理的人可以完成任务，这是二。戎狄事奉晋国，四边的邻国震动，诸侯因为我们的威严而慑服，这是三。用德行安抚戎人，将士不辛劳，武器不损坏，这是四。有鉴于后羿的教训，而利用道德法度，远国前来而邻国安心，这是五。君王还是慎重谋划吧！”晋悼公听了很高兴，派遣魏庄子与各部戎人讲和。又致力于治理百姓，按照时令去打猎。
冬季，十月，邾国人、莒国人进攻鄫国，臧纥救援鄫国，入侵邾国，在狐骀被击败。国内的人们去接丧的都用麻系发，鲁国从这时开始就有了用麻系发的习俗。国内的人们讽刺说：“姓臧的身穿狐皮袄，使我们在狐骀战败了。我们的国君小孩子，把个侏儒当差使。侏儒啊，侏儒！使我们被打败在邾。”', NULL, '', 'indent', 1559038964, '5cec9b7143e78c0067206f9b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643042, '左传 · 襄公 · 襄公二十四年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有四年春，叔孙豹如晋。仲孙羯帅师侵齐。夏，楚子伐吴。秋七月甲子朔，日有食之，既。齐崔杼帅师伐莒。大水。八月癸巳朔，日有食之。公会晋侯、宋公、卫侯、郑伯、曹伯、莒子、邾子、滕子、薛伯、杞伯、小邾子于夷仪。冬，楚子、蔡侯、陈侯、许男伐郑。公至自会。陈金咸宜咎出奔楚。叔孙豹如京师。大饥。
【传】二十四年春，穆叔如晋。范宣子逆之，问焉，曰：「古人有言曰，『死而不朽』，何谓也？」穆叔未对。宣子曰：「昔□之祖，自虞以上，为陶唐氏，在夏为御龙氏，在商为豕韦氏，在周为唐杜氏，晋主夏盟为范氏，其是之谓乎？」穆叔曰：「以豹所闻，此之谓世禄，非不朽也。鲁有先大夫曰臧文仲，既没，其言立。其是之谓乎！豹闻之，大上有立德，其次有立功，其次有立言，虽久不废，此之谓不朽。若夫保姓受氏，以守宗祊，世不绝祀，无国无之，禄之大者，不可谓不朽。」
范宣子为政，诸侯之币重。郑人病之。二月，郑伯如晋。子产寓书于子西以告宣子，曰：「子为晋国，四邻诸侯，不闻令德，而闻重币，侨也惑之。侨闻君子长国家者，非无贿之患，而无令名之难。夫诸侯之贿聚于公室，则诸侯贰。若吾子赖之，则晋国贰。诸侯贰，则晋国坏。晋国贰，则子之家坏。何没没也！将焉用贿？夫令名，德之舆也。德，国家之基也。有基无坏，无亦是务乎！有德则乐，乐则能久。《诗》云：『乐只君子，邦家之基。』有令德也夫！『上帝临女，无贰尔心。』有令名也夫！恕思以明德，则令名载而行之，是以远至迩安。毋宁使人谓子『子实生我』，而谓『子濬我以生』乎？像有齿以焚其身，贿也。」宣子说，乃轻币。是行也，郑伯朝晋，为重币故，且请伐陈也。郑伯稽首，宣子辞。子西相，曰：「以陈国之介恃大国而陵虐于敝邑，寡君是以请罪焉。敢不稽首。」
孟孝伯侵齐，晋故也。
夏，楚子为舟师以伐吴，不为军政，无功而还。
齐侯既伐晋而惧，将欲见楚子。楚子使薳启强如齐聘，且请期。齐社，搜军实，使客观之。陈文子曰：「齐将有寇。吾闻之，兵不戢，必取其族。」
秋，齐侯闻将有晋师，使陈无宇从薳启强如楚，辞，且乞师。崔杼帅师送之，遂伐莒，侵介根。
会于夷仪，将以伐齐，水，不克。
冬，楚子伐郑以救齐，门于东门，次于棘泽。诸侯还救郑。晋侯使张骼、辅跞致楚师，求御于郑。郑人卜宛射犬，吉。子大叔戒之曰：「大国之人，不可与也。」对曰：「无有众寡，其上一也。」大叔曰：「不然，部娄无松柏。」二子在幄，坐射犬于外，既食而后食之。使御广车而行，己皆乘乘车。将及楚师，而后从之乘，皆踞转而鼓琴。近，不告而驰之。皆取胄于櫜而胄，入垒，皆下，搏人以投，收禽挟囚。弗待而出。皆超乘，抽弓而射。既免，复踞转而鼓琴，曰：「公孙！同乘，兄弟也。胡再不谋？」对曰：「曩者志入而已，今则怯也。」皆笑，曰：「公孙之亟也。」
楚子自棘泽还，使薳启强帅师送陈无宇。
吴人为楚舟师之役故，召舒鸠人，舒鸠人叛楚。楚子师于荒浦，使沈尹寿与师祁犁让之。舒鸠子敬逆二子，而告无之，且请受盟。二子覆命，王欲伐之。薳子曰：「不可。彼告不叛，且请受盟，而又伐之，伐无罪也。姑归息民，以待其卒。卒而不贰，吾又何求？若犹叛我，无辞有庸。」乃还。
陈人复讨庆氏之党，金咸宜咎出奔楚。
齐人城郏。穆叔如周聘，且贺城。王嘉其有礼也，赐之大路。
晋侯嬖程郑，使佐下军。郑行人公孙挥如晋聘。程郑问焉，曰：「敢问降阶何由？」子羽不能对。归以语然明，然明曰：「是将死矣。不然将亡。贵而知惧，惧而思降，乃得其阶，下人而已，又何问焉？且夫既登而求降阶者，知人也，不在程郑。其有亡衅乎？不然，其有惑疾，将死而忧也。」', '', '', '二十四年春季，穆叔到了晋国，范宣子迎接他，询问他，说：“古人有话说，‘死而不朽’，这是说的什么？”穆叔没有回答。范宣子说：“从前匄的祖先，从虞舜以上是陶唐氏，在夏朝是御龙氏，在商朝是豕韦氏，在周朝是唐杜氏，晋国主持中原的盟会的时候是范氏，恐怕所说的不朽就是这个吧！”穆叔说：“据豹所听到的，这叫做世禄，不是不朽。鲁国有一位先大夫叫臧文仲，死了以后，他的话世代不废，所谓不朽，说的就是这个吧！豹听说：‘最高的是树立德行，其次是树立功业，再其次是树立言论。’能做到这样，虽然死了也久久不会废弃，这叫做不朽。像这样保存姓、接受氏，用业守住宗庙，世世代代不断绝祭祀。没有一个国家没有这种情况。这只是官禄中的大的，不能说是不朽。”
范宣子主持政事，诸侯朝见晋国的贡品很重，郑国人对这件事感到忧虑。二月，郑简公去到晋国，子产托子西带信给范宣子，说：“您治理晋国，四邻的诸侯不听说有美德，而听说要很重的贡品，侨对这种情况感到迷惑。侨听说君子治理国和家，不是担心没有财礼，而是害怕没有好名声。诸侯的财货，聚集在国君家里，内部就分裂。如果您把这个作为利己之物，晋国的内部就不和。诸侯的内部不和，晋国就受到损害。晋国的内部不和，您的家就受到损害。为什么那么糊涂呢！还哪里用得着财货？好名声，是装载德行的车子。德行，是国家和家族的基础。有基础才不至于毁坏，您不也应该这么做吗？有了德行就快乐，快乐了就能长久。《诗》说，‘快乐啊君子，是国家和家族的基础’，这就是有美德吧！‘天帝在你的上面，你不要有二心’，这就是有好名声吧！用宽恕来发扬德行，那么好的名声就会自然传布天下，因此远方的人会因仰慕而来，近处的人也会获得安宁。您是宁可使人对您说‘您确实养活了我’，还是说‘您剥削了我，来养活自己’呢？象有了象牙而毁了自己，这是由于象牙值钱的缘故。”范宣子听了子产的这番道理之后很高兴，就减轻了贡品。这一趟，郑简公朝见晋国，是为了贡品太重的缘故，同时请求进攻陈国。郑简公行叩首礼，范宣子辞谢不敢当。子西相礼，说：“由于陈国仗恃大国而欺凌侵害敝邑，寡君因此请求向陈国问罪，岂敢不叩头？”
孟孝伯入侵齐国，这是为了晋国的缘故。
夏季，楚康王出动水兵以攻打吴国，由于不教育军队，没有得到成功就回来了。
齐庄公对晋国发动进攻以后又害怕，打算会见楚康王。楚康王派薳启彊去到齐国聘问，同时请问会见的日期。齐国人在军队中祭祀土地神，并举行大检阅，让客人观看。陈文子说：“齐国将要受到侵犯。我听说，不收敛武力，还会自己害自己。”
秋季，齐庄公听说晋国打算出兵，就派遣陈无宇跟随薳启彊去到楚国。说明将有战事而不能会见，同时请求出兵。崔杼带兵送他，就乘机进攻莒国，侵袭介根。
鲁襄公和晋平公、宋平公、卫殇公、郑简公、曹武公、莒子、邾子、滕子、薛伯、杞伯、小邾子在夷仪会见，准备进攻齐国。由于大水，没有能进攻。
冬季，楚康王进攻郑国以救援齐国，进攻东门，驻扎在棘泽。诸侯回军救援郑国。晋平公派遣张骼，辅跞向楚军单车挑战，向郑国求取驾御战车的人。郑国人占卜派遣宛射犬，吉利。子太叔告诫宛射犬说：“对大国的人不能和他们平行抗礼。”宛射犬回答说：“不论兵多兵少，御者的地位在车左车右之上是一样的。”太叔说：“不是这样。小土山上没有松柏。”张骼、辅跞两个人在帐篷里，让射犬坐在帐篷外，吃完饭，才让射犬吃。让射犬驾御进攻的车前进，张、辅自己却坐着平时的战车，将要到达楚军营垒，然后才登上射犬的车子，二人均蹲在车后边的横木上弹琴。车子驶近楚营，射犬没有告诉这两个人就疾驰而进。这两个人都从袋子里拿出头盔戴上，进入营垒，都下车，把楚兵抓起来扔出去，把俘虏的楚兵捆绑好或者挟在腋下。射犬不等待这两个人而独自驱车出来，这两个人就都跳上车，抽出弓箭来射向追兵。脱险以后，张、辅二人又蹲在车后边横木上弹琴，说：“公孙！同坐一辆战车，就是兄弟，为什么两次都不招呼一下？”射犬回答说：“从前一心想着冲人敌营，这次是心里害怕敌军人多，顾不上商量。”两个人都笑了，说：“公孙是个急性的人啊！”
楚康王从棘泽回来，派薳启彊护送陈无宇。
吴国人为楚国“舟师之役”的缘故，召集舒鸠人。舒鸠人背叛楚国。楚康王在荒浦驻兵，派沈尹寿和师祁犁责备他们。舒鸠子恭恭敬敬地迎接这两个人，告诉他们没有这回事。同时请求接受盟约。这两个人回见楚康王复命，楚康王想要进攻舒鸠。薳子说：“不行。他告诉我们说不背叛，同时又请求接受盟约，而我们又去进攻他，这是进攻无罪的国家。姑且回去使百姓休息，以等待结果。结果没有三心二意，我们还有什么可要求的？如果还是背叛我们，他就无话可说，我们打它就可以获得成功了。”楚康王于是就退兵回去。
陈国人再次讨伐庆氏的亲族，鍼宜咎逃亡到楚国。
齐国人在郏地为周王筑城。穆叔到成周聘问，同时祝贺筑城完工。周灵王嘉奖穆叔合于礼仪，赐给他大路之车。
晋平公宠信程郑，任命他为下军副帅。郑国的行人公孙挥去到晋国聘问，程郑向他请教，说：“谨敢请问怎样才能降级？”公孙挥不能回答，回去告诉了然明。然明说：“这个人将要死了。否则，就将要逃亡。地位尊贵而知道害怕，害怕而想到了降级，就可以得到适合他的地位，不过是在别人下面罢了，又问什么？而且既己登上高位而要求降级的，这是聪明人，不是程郑这样的人。恐怕有了逃亡的迹象了吧！否则，恐怕就是有疑心病，自知将要死了而忧虑啊！”', NULL, '', 'indent', 1559125858, '5cedeedf7b968a00767d31de', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643023, '左传 · 襄公 · 襄公五年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】五年春，公至自晋。夏，郑伯使公子发来聘。叔孙豹、鄫世子巫如晋。仲孙蔑、卫孙林父子会吴于善道。秋，大雩。楚杀其大夫公子壬夫。公会晋侯、宋公、陈侯、卫侯、郑伯、曹伯、莒子、邾子、滕子、薛伯、齐世子光、吴人、鄫人于戚。公至自会。冬，戍陈。楚公子贞帅师伐陈。公会晋侯、宋公、卫侯、郑伯、曹伯、齐世子光救陈。十有二月，公至自救陈。辛未，季孙行父卒。
【传】五年春，公至自晋。
王使王叔陈生愬戎于晋，晋人执之。士鲂如京师，言王叔之贰于戎也。
夏，郑子国来聘，通嗣君也。
穆叔觌鄫大子于晋，以成属鄫。书曰：「叔孙豹、鄫大子巫如晋。」言比诸鲁大夫也。
吴子使寿越如晋，辞不会于鸡泽之故，且请听诸侯之好。晋人将为之合诸侯，使鲁、卫先会吴，且告会期。故孟献子、孙文子会吴于善道。
秋，大雩，旱也。
楚人讨陈叛故，曰：「由令尹子辛实侵欲焉。」乃杀之。书曰：「楚杀其大夫公子壬夫。」贪也。君子谓：「楚共王于是不刑。《诗》曰：『周道挺挺，我心扃扃，讲事不令，集人来定。』己则无信，而杀人以逞，不亦难乎？《夏书》曰：『成允成功。』」
九月丙午，盟于戚，会吴，且命戍陈也。穆叔以属鄫为不利，使鄫大夫听命于会。
楚子囊为令尹。范宣子曰：「我丧陈矣！楚人讨贰而立子囊，必改行而疾讨陈。陈近于楚，民朝夕急，能无往乎？有陈，非吾事也，无之而后可。」
冬，诸侯戍陈。子囊伐陈。十一月甲午，会于城棣以救之。
季文子卒。大夫入敛，公在位。宰庀家器为葬备，无衣帛之妾，无食粟之马，无藏金玉，无重器备。君子是以知季文子之忠于公室也。相三君矣，而无私积，可不谓忠乎？', '', '', '五年春季，鲁襄公从晋国到达鲁国。
周灵王派遣王叔陈生向晋国控告戎人，晋国人把他抓了起来。士鲂去到京师，报告说王叔倾向戎人。
夏季，郑国的子国来鲁国聘问，这是由于为新立的国君来通好。
穆叔带领鄫国的太子去到晋国和君臣作私人会晤，以完成鄫国归属鲁国的手续。《春秋》记载说：“叔孙豹、鄫太子巫如晋”，这就是把鄫国的太子巫比作鲁国的大夫。
吴子派遣寿越去到晋国，解释没有参加鸡泽会见的缘故，同时请求听从命令和诸侯友好。晋人将为吴国会合诸侯，于是让鲁国、卫国先会见吴国，同时告诉吴国会见的日期。所以孟献子、孙文子在善道会见了吴人。
秋季，举行盛大的雩祭，这是由于天旱的缘故。
楚国人质问陈国背叛的原因，陈人说：“由于令尹子辛侵害小国以满足他个人欲望。”楚国就杀死了子辛。《春秋》记载说：“楚杀其大夫公子壬夫”，是由于他贪婪的缘故。君子认为：“楚共王在这件事情上用刑律不当。《诗》说：‘大道笔直，我的心里明白。计划不善灵，应招集贤人决定。’自己就没有信用，反而杀人以快意，不也是很难了吗？《夏书》说：‘完成信用然后才能成功。’”
九月二十三日，鲁襄公和晋悼公、宋平公、陈哀公、卫献公、郑僖公、曹成公、莒子、邾子、滕成公、薛伯、齐国世子光、吴国人、鄫国人在戚地结盟，这是为了会见吴人，同时由晋悼公命令诸侯出兵戍守陈国。穆叔认为鄫国的归属对鲁国不利，就让鄫国的大夫以独立国家的身份参加会见听取命令。
楚国的子囊做令尹，范宣子说：“我们失去陈国了。楚国人讨伐三心二意的国家而又立了子囊，一定会改变子辛的所作所为而很快讨伐陈国。陈国接近楚国，百姓时时骇怕兵患，能够不归向楚国吗？保有陈国，不是我们的事情；放弃陈国，以后反倒好办。”
冬季，诸侯派兵戍守陈国。子囊进攻陈国。十一月十二日，鲁襄公和晋悼公、宋平公、卫献公、郑僖公、曹成公、齐国世子光在城棣会合以救援陈国。
冬季，诸侯派兵戍守陈国。子囊进攻陈国。十一月十二日，鲁襄公和晋悼公、宋平公、卫献公、郑僖公、曹成公、齐国世子光在城棣会合以救援陈国。季文子死。根据大夫人敛的礼仪，鲁襄公亲自看视。家臣收集家里的器物作为葬具。家里没有穿丝绸的妾，没有吃粮食的马，没有收藏铜器玉器，一切用具没有重复。君子从这里知道季文子对公室的忠心：辅助过三位国君而没有私人积蓄，可以说不是忠心吗？', NULL, '', 'indent', 1559038999, '5cec9b94d5de2b00708561a8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643024, '左传 · 襄公 · 襄公六年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】六年春王三月，壬午，杞伯姑容卒。夏，宋华弱来奔。秋，杞葬桓公。滕子来朝。莒人灭鄫。冬，叔孙豹如邾，季孙宿如晋。十有二月，齐侯灭莱。
【传】六年春，杞桓公卒，始赴以名，同盟故也。
宋华弱与乐辔少相狎，长相优，又相谤也。子荡怒，以弓梏华弱于朝。平公见之，曰：「司武而梏于朝，难以胜矣！」遂逐之。夏，宋华弱来奔。司城子罕曰：「同罪异罚，非刑也。专戮于朝，罪孰大焉！」亦逐子荡。子荡射子罕之门，曰：「几日而不我从！」子罕善之如初。
秋，滕成公来朝，始朝公也。
莒人灭鄫，鄫恃赂也。
冬，穆叔如邾，聘，且修平。
晋人以鄫故来讨，曰：「何故亡鄫？」季武子如晋见，且听命。
十一月，齐侯灭莱，莱恃谋也。于郑子国之来聘也，四月，晏弱城东阳，而遂围莱。甲寅，堙之环城，傅于堞。及杞桓公卒之月，乙未，王湫帅师及正舆子、棠人军齐师，齐师大败之。丁未，入莱。莱共公浮柔奔棠。正舆子、王湫奔莒，莒人杀之。四月，陈无宇献莱宗器于襄宫。晏弱围棠，十一月丙辰，而灭之。迁莱于郳。高厚、崔杼定其田。', '', '', '六年春季，杞桓公死了。讣告首次记载他的名字，这是由于两国同盟的缘故。
宋国的华弱和乐辔小时候彼此很亲昵，长大了就彼此戏谑，又互相诽谤。乐辔有一次发怒，在朝廷上用弓套住华弱的脖子如同带枷一样。宋平公见到了，说：“司武而在朝廷上带弓枷，打仗就难于取胜了。”于是就把他赶走。夏季，华弱逃亡到鲁国。司城子罕说：“罪过相同而惩罚不同，这是不合于刑法的。在朝廷上专横和侮辱别人，还有比这大的罪过吗？”于是也赶走乐辔，乐辔把箭射在子罕的大门上，说：“看你还有几天会不跟着我一样被赶走？”子罕害怕，优待乐辔像过去一样。
秋季，滕成公前来朝见，这是第一次朝见鲁襄公。
莒国人灭亡了鄫国，这是由于鄫国仗着送过财礼而疏于防备的缘故。
冬季，穆叔去到邾国聘问，同时重修友好关系。
晋国人由于鄫国的缘故前来讨伐，说：“为什么把鄫国灭亡？”季武子去到晋国，听候晋国处置。
十一月，齐灵公灭亡莱国，这是由于莱国只是仗着谋略而不务实际的缘故。当郑国子国来鲁国聘问的时候，即去年四月，晏弱在东阳筑城，因而就包围莱国，四月的一天，环城堆起土山，紧挨着女墙。到杞桓公死去的那一个月的十五日，王湫领兵和正舆子、棠邑人迎战齐军，齐军把他们打得大败。二十七日，进入莱国。莱共公浮柔逃亡到棠地，正舆子、王湫逃亡到莒国，莒国人杀了他们。四月，陈无宇把莱国宗庙里的宝器献于襄宫。晏弱包围棠邑，十二月初十灭了它，把莱国的百姓迁到郳地。高厚、崔杼主持划定分配莱国的土地疆界。', NULL, '', 'indent', 1559039035, '5cec9bb9c8959c0069e964bb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643025, '左传 · 襄公 · 襄公七年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】七年春，郯子来朝。夏四月，三卜郊，不从，乃免牲。小邾子来朝。城费。秋，季孙宿如卫。八月，螽。冬十月，卫侯使孙林父来聘。壬戌，及孙林父盟。楚公子贞帅师围陈。十有二月，公会晋侯、宋公、陈侯、卫侯、曹伯、莒子、邾子于鄬。郑伯髡顽如会，未见诸侯，丙戌，卒于鄵。陈侯逃归。
【传】七年春，郯子来朝，始朝公也。
夏四月，三卜郊，不从，乃免牲。孟献子曰：「吾乃今而后知有卜筮。夫郊，祀后稷以祈农事也。是故启蛰而郊，郊而后耕。今既耕而卜郊，宜其不从也。」
南遗为费宰。叔仲昭伯为隧正，欲善季氏而求媚于南遗，谓遗：「请城费，吾多与而役。」故季氏城费。
小邾穆公来朝，亦始朝公也。
秋，季武子如卫，报子叔之聘，且辞缓报，非贰也。
冬十月，晋韩献子告老。公族穆子有废疾，将立之。辞曰：「《诗》曰：『岂不夙夜，谓行多露。』又曰：『弗躬弗亲，庶民弗信。』无忌不才，让，其可乎？请立起也！与田苏游，而曰好仁。《诗》曰：『靖共尔位，好是正直。神之听之，介尔景福。』恤民为德，正直为正，正曲为直，参和为仁。如是，则神听之，介福降之。立之，不亦可乎？」庚戌，使宣子朝，遂老。晋侯谓韩无忌仁，使掌公族大夫。
卫孙文子来聘，且拜武子之言，而寻孙桓子之盟。公登亦登。叔孙穆子相，趋进曰：「诸侯之会，寡君未尝后卫君。今吾子不后寡君，寡君未知所过。吾子其少安！」孙子无辞，亦无悛容。
穆叔曰：「孙子必亡。为臣而君，过而不悛，亡之本也。《诗》曰：『退食自公，委蛇委蛇。』谓从者也。衡而委蛇必折。」
楚子囊围陈，会于鄬以救之。
郑僖公之为大子也，于成之十六年，与子罕适晋，不礼焉。又与子丰适楚，亦不礼焉。及其元年，朝于晋。子丰欲愬诸晋而废之，子罕止之。及将会于鄬，子驷相，又不礼焉。侍者谏，不听，又谏，杀之。及鄵，子驷使贼夜弑僖公，而以疟疾赴于诸侯。简公生五年，奉而立之。
陈人患楚。庆虎、庆寅谓楚人曰：「吾使公子黄往而执之。」楚人从之。二庆使告陈侯于会，曰：「楚人执公子黄矣！君若不来，群臣不忍社稷宗庙，惧有二图。」陈侯逃归。', '', '', '七年春季，郯子前来朝见，这是他第一次朝见鲁襄公。
夏季，四月，鲁国三次为郊祭而占卜，都不吉利，于是就免除使用牺牲。孟献子说：“我从今以后才知道有占卜和占筮了。郊祭是祭祀后稷，而祈求农事顺利。所以一到启蛰节就举行郊祭，郊祭以后开始耕种。现在已经开始耕种再来为郊祭占卜，占卜不吉利是应该的。”
南遗出任费邑县宰。叔仲昭伯做了管理修隧道的头目，想要讨好季氏，因而谄媚南遗。他对南遗说：“你去请求在费地筑城，我多给你劳力。”所以季氏在费地筑城。
小邾穆公来鲁国朝见，也是第一次朝见襄公。
秋季，季武子去到卫国，这是为了回报子叔的聘问，同时解释所以延迟回报不是出于三心二意。
冬季，十月，晋国韩献子告老退休，公族穆子患有残疾，准备立他为卿。穆子辞谢说：“《诗》说：‘难道不是早晚都想着前来？无奈路上的露水太多。’又说：‘不能亲自办事，百姓不会信任。’无忌没有才能，让给别人，也许可以吧？请立起吧。起和田苏有交往，田苏称赞他‘好仁’。《诗》说：‘忠诚谨慎地对待你的职位，喜爱这正直的人。神灵将会听到，赐给你以大福。’体恤百姓是德，纠正直是正，纠正曲是直，把这三者合而为一是仁。像这样，那么神灵就会听到，降给他大福。立他为卿，不也是可以的吗？” 初九日，让韩宣子朝见，于是他就告老退休。晋悼公认为韩无忌具有仁德，让他做首席公族大夫。
卫国的孙文子来鲁国聘问，同时答谢季武子的解释，重温和孙桓子结盟的友好关系。鲁襄公登上台阶，孙林父同时登上。叔孙穆子相礼，快步进入，说：“诸侯会见，寡君从来没有走在卫君后面。现在您没有走在寡君后面，寡君不知道自己错在哪里。大夫您稍停一下吧！”孙林父没有话说，也没有改悔的样子。穆叔说：“孙子必然逃亡。作为臣下而和国君并行，有了过错又不改悔，这是逃亡的根本原因。《诗》说，‘退朝回家吃饭，从容自得’，说的是小心顺从的人。专横而又自得，必然遭受挫折。”
楚国的子襄包围陈国，鲁襄公和晋悼公、宋平公、陈哀公、卫献公、曹成公、莒子、邾子在鄬地会见以救援陈国。
郑值公做太子的时候，在鲁成公十六年和子罕同去晋国，对子罕不加礼遇。又和子丰同去楚国，对子丰也不加礼遇。等到僖公即位的元年去晋国朝见，子丰想要向晋国控告而废立僖公，子罕加以劝阻。等到将要在鄬地会见，子驷做相礼，僖公不以礼遇待子驷。侍者劝谏，不听；又劝谏，杀了说话的人。到达鄵地，子驷派人夜里害死僖公，而用急病致死讣告诸侯。简公当时五岁，就奉立他为国君。
陈国人担心楚国。庆虎、庆寅对楚国人说：“我们派公子黄去，你们逮住他。”楚国人听从了。二庆派人到会报告陈哀公，说：“楚国人抓住公子黄了。君王如果不回来，群臣不忍心国家宗庙的被楚灭亡，恐怕会有其他想法。”陈哀公于是就逃了回来。', NULL, '', 'indent', 1559039078, '5cec9be3c8959c0069e965f2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643026, '左传 · 襄公 · 襄公八年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】八年春王正月，公如晋。夏，葬郑僖公。郑人侵蔡，获蔡公子燮。季孙宿会晋侯、郑伯、齐人、宋人、卫人、邾人于邢丘。公至自晋。莒人伐我东鄙。秋九月，大雩。冬，楚公子贞帅师伐郑。晋侯使士□来聘。
【传】八年春，公如晋，朝，且听朝聘之数。
郑群公子以僖公之死也，谋子驷。子驷先之。夏四月庚辰，辟杀子狐、子熙、子侯、子丁。孙击、孙恶出奔卫。
庚寅，郑子国、子耳侵蔡，获蔡司马公子燮。郑人皆喜，唯子产不顺，曰：「小国无文德，而有武功，祸莫大焉。楚人来讨，能勿从乎？从之，晋师必至。晋、楚伐郑，自今郑国不四五年，弗得宁矣。」子国怒之曰：「尔何知？国有大命，而有正卿。童子言焉，将为戮矣。」
五月甲辰，会于邢丘，以命朝聘之数，使诸侯之大夫听命。季孙宿、齐高厚、宋向戌、卫宁殖、邾大夫会之。郑伯献捷于会，故亲听命。大夫不书，尊晋侯也。
莒人伐我东鄙，以疆鄫田。
秋九月，大雩，旱也。
冬，楚子囊伐郑，讨其侵蔡也。
子驷、子国、子耳欲从楚，子孔、子蟜、子展欲待晋。子驷曰：「《周诗》有之曰：『俟河之清，人寿几何？兆云询多，职竞作罗。』谋之多族，民之多违，事滋无成。民急矣，姑从楚以纾吾民。晋师至，吾又从之。敬共币帛，以待来者，小国之道也。牺牲玉帛，待于二竞，以待强者而庇民焉。寇不为害，民不罢病，不亦可乎？」子展曰：「小所以事大，信也。小国无信，兵乱日至，亡无日矣。五会之信，今将背之，虽楚救我，将安用之？亲我无成，鄙我是欲，不可从也。不如待晋。晋君方明，四军无阙，八卿和睦，必不弃郑。楚师辽远，粮食将尽，必将速归，何患焉？舍之闻之：『杖莫如信。』完守以老楚，杖信以待晋，不亦可乎？」子驷曰：「《诗》云：『谋夫孔多，是用不集。发言盈庭，谁敢执其咎？如匪行迈谋，是用不得于道。』请从楚，□非也受其咎。」乃及楚平。
使王子伯骈告于晋，曰：「君命敝邑：『修而车赋，儆而师徒，以讨乱略。』蔡人不从，敝邑之人，不敢宁处，悉索敝赋，以讨于蔡，获司马燮，献于邢丘。今楚来讨曰：『女何故称兵于蔡？』焚我郊保，冯陵我城郭。敝邑之众，夫妇男女，不皇启处，以相救也。剪焉倾覆，无所控告。民死亡者，非其父兄，即其子弟，夫人愁痛，不知所庇。民知穷困，而受盟于楚，狐也与其二三臣不能禁止。不敢不告。」知武子使行人子员对之曰：「君有楚命，亦不使一介行李告于寡君，而即安于楚。君之所欲也，谁敢违君？寡君将帅诸侯以见于城下，唯君图之！」
晋范宣子来聘，且拜公之辱，告将用师于郑。公享之，宣子赋《摽有梅》。季武子曰：「谁敢哉！今譬于草木，寡君在君，君之臭味也。欢以承命，何时之有？」武子赋《角弓》。宾将出，武子赋《彤弓》。宣子曰：「城濮之役，我先君文公献功于衡雍，受彤弓于襄王，以为子孙藏。□也，先君守官之嗣也，敢不承命？」君子以为知礼。', '', '', '八年春季，鲁襄公去到晋国朝见，同时听取晋国要求所献财币的数字。
郑国的公子们由于僖公的死去，谋划杀死子驷。子驷先下手。夏季，四月十二日，假造罪名，杀了子狐、子熙、子侯、子丁。孙击、孙恶逃亡到卫国。
四月二十二日，郑国的子国、子耳入侵蔡国，俘虏了蔡国司马公子燮。郑国人都高兴，唯独子产不随声附和，说：“小国没有文治却有了武功，没有比这再大的祸患了。楚国人前来讨伐，能够不顺从他们吗？顺从楚国，晋国的军队必然来到。晋、楚两国进攻郑国，从今以后郑国至少四五年内不得安宁。”子国对他发怒说：“你知道什么！国家有出兵的重大命令，而且有执政的卿在那里，小孩子说这些话，将要被杀的！”
五月初七日，季孙宿和晋悼公、郑简公、齐国人、宋国人、卫国人、邾国人在邢丘会见，由晋国提出朝聘的财礼数字，让诸侯的大夫听取命令。鲁国季孙宿、齐国高厚、宋国向戌、卫国宁殖、邾国大夫参加会见。郑简公在这次会上奉献战利品，所以亲自听取命令。《春秋》没有记载大夫的名字，为的是尊重晋侯。
莒国人攻打我国东部边境，以划定鄫国土田的疆界。
秋季九月，举行盛大的雩祭，这是由于天旱。
冬季，楚国的子囊进攻郑匡，讨伐郑国入侵蔡国。
子驷、子国、子耳要顺从楚国，子孔、子？、子展要等待晋国救援。子驷说：“《周诗》有这样的话：‘等待黄河澄清，人的寿命能有几何？占卜太多，等于为自己结成网罗。’跟很多人商量，主意太多，百姓多数不能跟从，事情更难成功。百姓危急了，姑且顺从楚国，以缓和百姓的苦难。晋国军队来到，我们又再顺从他。恭恭敬敬地供给财货，以等待别人前来，这是小国所应当做的。用牺牲玉帛，在两国的边境上等待，以等待强有力的国家来保护百姓。敌人不为祸害，百姓不疲劳困乏，不也是可以的吗？”子展说：“小国用来事奉大国的，是信用。小国没有信用，战争和祸乱会每天都有，很快就要灭亡了。与晋国五次盟会的条约，如今却打算背弃，虽然楚国救援我国，还有什么用？楚国的亲近对我国不会有了结果，他们是想把我国作他们的边郡县邑，不能顺从他们。不如等待晋国。晋国的国君正当贤明的时候，四个军完备无缺，八个卿和睦无间，必然不会丢弃郑国。楚军距离我们遥远，粮食将要吃完了，一定会很快回去，怕什么？舍之听说：仗恃不如讲信用。完缮守备以使楚军疲惫，依靠信用以等待晋军，不也是可以的吗？”子驷说：“《诗》说：‘出主意的人很多，因此不能有所成就。发言的人挤满庭院，谁敢承担过错？好象一个人一边走路一边还和路人商量，因此一无所得。”请顺从楚国，騑来承担责任。”
于是郑国就和楚国讲和，派王子伯骈向晋国报告，说：“君王命令敝邑：‘整修你们的战车，使你们的车兵徒兵保持戒备，以讨伐动乱。’蔡国人不顺从，敝邑的人不敢贪图安逸，收尽我国的军队，以讨伐蔡国，俘虏了司马燮，奉献于邢丘的盟会上。现在楚国前来付伐，说：‘你们为什么对蔡国用兵？’焚烧我国郊外的小堡，侵略我国的城郭。敝邑的大众，夫妻男女，顾不得休息而互相救援。国家将要倾覆，没有地方可以控告。百姓死去和逃亡的，不是父兄，就是子弟。人人忧愁悲痛，不知道在哪里可以得到保护。百姓知道毫无办法，只好接受楚国的盟约。我和我的几个臣子不能禁止，不敢不报告。” 知武子派行人子员回答说：“君王受到楚国讨伐的命令，也不派一个使者来告诉我，反而立刻屈服于楚国。君王的愿望，谁敢反对？寡君准备率领诸侯和你们在城下相见。请君王考虑一下。”
晋国范宣子来鲁国聘问，同时拜谢鲁襄公的朝见，报告将出兵郑国。襄公设享礼招待他，范宣子赋《摽有梅》这首诗。季武子说：“谁敢不及时啊！现在用草木来比喻，寡君之于君王，不过是作为草木散发出来的气味而已。高高兴兴地接受命令，有什么时间早晚？”季武子赋《角弓》这首诗。客人将要退出，季武子赋《彤弓》这首诗。范宣子说：“城濮这一战，我们的先君文公在衡雍奉献战功，在襄王那里接受了红色的弓，作为子孙的宝藏。匄是先君官员的后代，岂敢不接受您的命令？”君子认为范宣子懂得礼仪。', NULL, '', 'indent', 1559039129, '5cec9c16d5de2b00708566d8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643027, '左传 · 襄公 · 襄公九年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】九年春，宋灾。夏，季孙宿如晋。五月辛酉，夫人姜氏薨。秋八月癸未，葬我小君穆姜。冬，公会晋侯、宋公、卫侯、曹伯、莒子、邾子、滕子、薛伯、杞伯，小邾子、齐世子光伐郑。十有二月己亥，同盟于戏。楚子伐郑。
【传】九年春，宋灾。乐喜为司城以为政。使伯氏司里，火所未至，彻小屋，涂大屋；陈畚挶具绠缶，备水器；量轻重，蓄水潦，积土涂；巡丈城，缮守备，表火道。使华臣具正徒，令隧正纳郊保，奔火所。使华阅讨右官，官庀其司。向戌讨左，亦如之。使乐遄庀刑器，亦如之。使皇郧命校正出马，工正出车，备甲兵，庀武守使西锄吾庀府守，令司宫、巷伯儆宫。二师令四乡正敬享，祝宗用马于四墉，祀盘庚于西门之外。
晋侯问于士弱曰：「吾闻之，宋灾，于是乎知有天道。何故？」对曰：「古之火正，或食于心，或食于咮，以出内火。是故咮为鹑火，心为大火。陶唐氏之火正阏伯居商丘，祀大火，而火纪时焉。相土因之，故商主大火。商人阅其祸败之衅，必始于火，是以日知其有天道也。」公曰：「可必乎？」对曰：「在道。国乱无象，不可知也。」
夏，季武子如晋，报宣子之聘也。
穆姜薨于东宫。始往而筮之，遇《艮》之八三。史曰：「是谓《艮》之《随》三。《随》其出也。君必速也。」姜曰：「亡。是于《周易》曰：『《随》，元亨利贞，无咎。』元，体之长也；享，嘉之会也；利，义之和也；贞，事之干也。体仁足以长人，嘉德足以合礼，利物足以和义，贞固足以干事，然，故不可诬也，是以虽《随》无咎。今我妇人而与于乱。固在下位而有不仁，不可谓元。不靖国家，不可谓亨。作而害身，不可谓利。弃位而姣，不可谓贞。有四德者，《随》而无咎。我皆无之，岂《随》也哉？我则取恶，能无咎乎？必死于此，弗得出矣。」
秦景公使士雅乞师于楚，将以伐晋，楚子许之。子囊曰：「不可。当今吾不能与晋争。晋君类能而使之，举不失选，官不易方。其卿让于善，其大夫不失守，其士竞于教，其庶人力于农穑。商工皂隶，不知迁业。韩厥老矣，知罃禀焉以为政。范□少于中行偃而上之，使佐中军。韩起少于栾□，而栾□、士鲂上之，使佐上军。魏绛多功，以赵武为贤而为之佐。君明臣忠，上让下竞。当是时也，晋不可敌，事之而后可。君其图之！」王曰：「吾既许之矣。虽不及晋，必将出师。」秋，楚子师于武城以为秦援。秦人侵晋，晋饥，弗能报也。
冬十月，诸侯伐郑。庚午，季武子、齐崔杼、宋皇郧从荀罃、士□门于鄟门。卫北宫括、曹人、邾人从荀偃、韩起门于师之梁。滕人、薛人从栾□、士鲂门于北门。杞人、郳人从赵武、魏绛斩行栗。甲戌，师于汜，令于诸侯曰：「修器备，盛□粮，归老幼，居疾于虎牢，肆眚，围郑。」郑人恐，乃行成。中行献子曰：「遂围之，以待楚人之救也而与之战。不然，无成。」知武子曰：「许之盟而还师，以敝楚人。吾三分四军，与诸侯之锐以逆来者，于我未病，楚不能矣，犹愈于战。暴骨以逞，不可以争。大劳未艾。君子劳心，小人劳力，先王之制也」诸侯皆不欲战，乃许郑成。十一月己亥，同盟于戏，郑服也。
将盟，郑六卿公子□非、公子发、公子嘉、公孙辄、公孙虿、公孙舍之及其大夫、门子皆从郑伯。晋士庄子为载书，曰：「自今日既盟之后，郑国而不唯晋命是听，而或有异志者，有如此盟。」公子□非趋进曰：「天祸郑国，使介居二大国之间。大国不加德音而乱以要之，使其鬼神不获歆其禋祀，其民人不获享其土利，夫妇辛苦垫隘，无所底告。自今日既盟之后，郑国而不唯有礼与强可以庇民者是从，而敢有异志者，亦如之。」荀偃曰：「改载书。」公孙舍之曰：「昭大神，要言焉。若可改也，大国亦可叛也。」知武子谓献子曰：「我实不德，而要人以盟，岂礼也哉！非礼，何以主盟？姑盟而退，修德息师而来，终必获郑，何必今日？我之不德，民将弃我，岂唯郑？若能休和，远人将至，何恃于郑？」乃盟而还。
晋人不得志于郑，以诸侯复伐之。十二月癸亥，门其三门。闰月，戊寅，济于阴阪，侵郑。次于阴口而还。子孔曰：「晋师可击也，师老而劳，且有归志，必大克之。」子展曰：「不可。」
公送晋侯。晋侯以公晏于河上，问公年，季武子对曰：「会于沙随之岁，寡君以生。」晋侯曰：「十二年矣！是谓一终，一星终也。国君十五而生子。冠而生子，礼也，君可以冠矣！大夫盍为冠具？」武子对曰：「君冠，必以祼享之礼行之，以金石之乐节之，以先君之祧处之。今寡君在行，未可具也。请及兄弟之国而假备焉。」晋侯曰：「诺。」公还，及卫，冠于成公之庙，假钟磬焉，礼也。
楚子伐郑，子驷将及楚平。子孔、子蟜曰：「与大国盟，口血未干而背之，可乎？」子驷、子展曰：「吾盟固云：『唯强是从。』今楚师至，晋不我救，则楚强矣。盟誓之言，岂敢背之？且要盟无质，神弗临也，所临唯信。信者，言之瑞也，善之主也，是故临之。明神不蠲要盟，背之可也。」乃及楚平。公子罢戎入盟，同盟于中分。
楚庄夫人卒，王未能定郑而归。
晋侯归，谋所以息民。魏绛请施舍，输积聚以贷。自公以下，苟有积者，尽出之。国无滞积，亦无困人。公无禁利，亦无贪民。祈以币更，宾以特性，器用不作，车服从给。行之期年，国乃有节。三驾而楚不能与争。', '', '', '九年春季，宋国发生火灾。乐喜正做司城执掌政权，派伯氏管理街巷。火没有到达的地方，拆除小屋，用泥土涂在大屋上，摆列盛土和运土的器具；具备汲水的绳索和瓦罐，准备盛水的器具，估量人力的大小、任务的轻重，储满水塘，堆积泥土，巡查城郭，修缮守卫工具，标明火的趋向。乐喜派华臣调集常备兵，华臣又命令隧正调集远郊城堡的士兵，奔赴火灾发生的地点。派华阅主管右师，作为长官督促他的官属。向戌主管左师，也如同华阅一样。派乐遄准备刑具，也如同华阅一样。派皇郧命令管马的人牵出马匹，工正推出战车，装备武器，守卫武器库，派西锄吾保护国库。西锄吾命令司宫，巷伯在宫内警戒。左师、右师命令四个乡正祭祀四乡的神灵，祝宗杀马来祭祀四城的神灵，在宋都西门外边祭祀盘庚。
晋悼公向士弱询问说：“我听说，宋国遭了火灾，从这里就知道了天道，为什么？”士弱回答说：“古代的火正，祭祀火星的时候或者用心宿陪祭，或者用柳宿陪祭，由于火星运行在这两个星宿中间。所以柳宿就是鹑火星，心宿就是大火星。陶唐氏的火正阏伯住在商丘，祭祀大火星，而用火星来确定时节。相土沿袭这个方法，所以商朝以大火星为祭祀的主星。商朝人观察他们祸乱失败的预兆，一定从火灾开始，因此在过去自以为掌握了天道。”晋悼公说：“靠得住吗？”士弱回答说：“在于有道或者无道。国家动乱而上天不给预兆，这就不能预知了。”
夏季，季武子去到晋国，这是由于回报范宣子的聘问。
穆姜死在东宫里。开始住进去的时候，占筮，得到《艮》变为八■，太史说：“这叫做《艮》变为《随》■。《随》，是出走的意思。您一定要赶紧出去。”穆姜说：“不用出去！这卦象在《周易》里说‘《随》，元、亨、利、贞，没有灾祸。’元，是躯体最高的地方；亨，是嘉礼中的主宾相会；利，是道义的总和；贞，是事情的本体。体现了仁就足以领导别人，美好的德行足以协调礼仪，有利于万物足以总括道义，本体坚强足以办好事情。这样，所以是不能欺骗的。因此虽然得到《随》卦而没有灾祸。现在我作为女人而参与了动乱。本来地位低下而又没有仁德，不能说是元。使国家不安定，不能说是亨。做了事情而害自身，不能说是利。丢弃寡妇的地位而修饰爱美，不能说是贞。具有上面四种德行的，得到《随》卦才可以没有灾祸。而我都没有，难道合于《随》卦卦辞吗？我挑取邪恶，能够没有灾祸吗？一定死在这里，不能出去了。”
秦景公派遣士雃向楚国请求出兵，准备进攻晋国，楚共王答应了。子囊说：“不行。目前我们不能和晋国争夺。晋国国君按人的能力之大小而使用他们，举拔人才不失去能胜任的人，任命官员不改变原则。他的卿把职位让给善人，他的大夫不失职守，他的士努力于教育百姓，他的庶人致力于农事，商贾技工和贱役不想改变职业。韩厥告老退休，知罃继承他而执政。范匄比中行偃年轻而在中行偃之上，让他辅佐中军。韩起比栾黡年轻，而栾黡、士鲂使他在自己之上，让他辅佐上军。魏绛的功劳很多，却认为赵武贤能而甘愿做他的辅佐。国君明察，臣下忠诚，上面谦让，下面尽力。在这个时候，晋国不能抵挡，事奉他们才行。君王还是考虑一下！”楚共王说：“我已经答应他们了，虽然比不上晋国，一定要出兵。”
秋季，楚共王驻军在武城，以作为秦国的后援。秦国人侵袭晋国。晋国正遭受饥荒，不能反击。
冬季，十月，诸侯进攻郑国。十月十一日，季武子、齐国的崔杼、宋国的皇郧跟荀罃、士匄进攻鄟门。卫国的北宫括、曹国人、邾国人跟随荀偃、韩起进攻师之梁门，滕国人、薛国人跟随栾黡、士鲂进攻北门，杞国人、郳国人跟随赵武、魏绛砍伐路边的栗树。十五日，军队驻扎在汜水边上，于是传令诸侯说：“修理作战工具，备好干粮，送回老的小的，让有病的人住在虎牢，赦免错误，包围郑国。”
郑国人害怕，就派人求和。荀偃说：“对郑国实际包围，以等待楚国人救援，和他们作战。不这样，就没有真正的讲和。”知罃说：“答应他们结盟然后退兵，用这样的办法引诱楚国人进攻郑国，使楚国人疲劳。我们把四军分为三部分，加上诸侯的精锐部队，以迎击前来的军队，对我们来说并不困乏，而楚军就不能持久了。这样，还是比打仗好。暴露白骨以图一时之快，不能用这样的办法和敌人争胜。很大的疲劳还没有停止，君子用智，小人用力，这是先王的训示。”诸侯都不想打仗，于是就允许郑国讲和。
十一月初十日，一起在戏地结盟，这是由于郑国顺服了。
准备结盟，郑国的六卿公子騑、公子发、公子嘉、公孙辄、公孙虿、公孙舍之以及他们的大夫、卿的嫡子，都跟随郑简公赴会。晋国的士庄子制作盟书，说：“从今天已经盟誓以后，郑国如果对晋国不唯命是听或者有别的想法，就像这份盟书所记载的一样。”公子騑快步走上前，说：“上天降祸郑国，让我国夹于两个大国之间。大国不赐给我们友好的话语，反而发动战乱以要挟我们结盟，让我们的鬼神不能得到祭祀，百姓不能享受土地上的出产，男人女人都辛苦瘦弱，没有地方可以诉说。从今天已经盟誓以后，郑国如果不服从既合于礼仪而且有强大力量来保护我们的国家，反而敢有其他想法，也像这份盟书所记载的一样。”荀偃说：“修改这篇盟辞！”公孙舍之说：“已经把盟约报告神灵了。如果可以修改，大国也可以背叛了。”知罃对荀偃说：“我们实在不合于道德，反而用盟约来要挟别人，这难道合于礼仪吗？不合礼仪，用什么主持盟会？姑且结盟而退兵，修养德行、休整军队然后再来，最终必然得到郑国，何必一定在今天？我们不合于道德，百姓将会丢弃我们，岂只是郑国？如果能够休养民力和睦民心，远方的人将会来顺服，有什么要依靠郑国呢？”于是就结盟然后回国。
晋国人不能随心所欲号令郑国，便带领诸侯再次进攻郑国。十二月初五日，攻击郑国的三面城门，十二月二十日在阴阪渡河，侵袭郑国。驻扎在阴口然后回去。子孔说：“晋军可以攻击，军队长久在外边因而疲劳，只想回去。必然可以胜他们。”子展说：“不行。”
鲁襄公送晋悼公，晋悼公为襄公在黄河边上设宴，问起襄公的年龄。季武子回答说：“在沙随会见的那一年，寡君出生。”晋悼公说：“十二年了，这叫做一终，这是岁星运行一圈的终止。国君十五岁而生孩子，举行冠礼以后生孩子，这是合于礼仪的，您可以举行冠礼了。大夫何不准备举行冠礼的用具？”季武子回答说：“国君举行冠礼，一定要请补饮酒的仪节作为序幕，用钟磬的音乐表示节度，在先君的宗庙里才能举行。现在寡君正在路上，不能具备各种冠礼工具，请在到达兄弟国家以后借用这些设备。”晋悼公说：“好。”襄公回国，到达卫国，在卫成公庙里举行冠礼，借用了钟磬，这是合于礼的。
楚共王进攻郑国，子驷打算和楚国讲和，子孔、子蟜说：“和大国结盟，嘴里的血没有干就违背了它，行吗？”子驷、子展说：“我们的盟誓本来就说‘唯有跟从强大的国家’，现在楚国军来到，晋国不救援我国，那么楚国就是强大的国家了。盟誓的话，难道敢违背？而且在要挟之下举行的盟誓没有诚信可言，神灵不会降临，神灵所降临的只是有诚信的盟会。信，是言语的凭证，善良的主体，所以神灵降临。明察一切的神灵认为在要挟下举行的盟会不洁净，违背它是可以的。”于是郑国就和楚国讲和。公子罢戎进入郑国结盟，一起在中分盟誓。
楚庄王夫人死，楚共王没有能安定郑国就回国了。
晋悼公回国，计议让百姓休养生息的办法。魏绛请求赐予恩惠，把积聚的财物拿出来借给百姓。从晋侯以下，如果有积聚的财物，全都拿了出来。国内没有不流通的财物，也没有困乏的百姓；公家不禁止百姓牟利，也没有贪婪的百姓。祈祷用财币代替牺牲，招待宾客只用一种牲畜，新的器物不添制，车马服饰只要够用就行了。这些措施推行一年，国家才有了法度。三次出兵而楚国不能和晋国争夺。', NULL, '', 'indent', 1559039247, '5cec9c76c8959c0069e96a73', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643028, '左传 · 襄公 · 襄公十年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十年春，公会晋侯、宋公、卫侯、曹伯、莒子、邾子、滕子、薛伯、杞伯、小邾子、齐世子光会吴于柤。夏，五月甲午，遂灭逼阳。公至自会。楚公子贞、郑公孙辄帅师伐宋。晋师伐秦。秋，莒人伐我东鄙。公会晋侯、宋公、卫侯、曹伯、莒子、邾子、齐世子光、滕子、薛伯、杞伯、小邾子伐郑。冬，盗杀郑公子□非、公子发、公孙辄。戍郑虎牢。楚公子贞帅师救郑。公至自伐郑。
【传】十年春，会于柤，会吴子寿梦也。三月癸丑，齐高厚相大子光以先会诸侯于钟离，不敬。士庄子曰：「高子相大子以会诸侯，将社稷是卫，而皆不敬，弃社稷也，其将不免乎！」
夏四月戊午，会于柤。
晋荀偃、士□请伐逼阳，而封宋向戌焉。荀罃曰：「城小而固，胜之不武，弗胜为笑。」固请。丙寅，围之，弗克。孟氏之臣秦堇父辇重如役。逼阳人启门，诸侯之士门焉。县门发，郰人纥抉之以出门者。狄虒弥建大车之轮而蒙之以甲以为橹，左执之，右拔戟，以成一队。孟献子曰：「《诗》所谓『有力如虎』者也。」主人县布，堇父登之，及堞而绝之。队则又县之，苏而复上者三。主人辞焉乃退，带其断以徇于军三日。
诸侯之师久于逼阳，荀偃、士□请于荀罃曰：「水潦将降，惧不能归，请班师。」知伯怒，投之以机，出于其间，曰：「女成二事而后告余。余恐乱命，以不女违。女既勤君而兴诸侯，牵帅老夫以至于此，既无武守，而又欲易余罪，曰：『是实班师，不然克矣』。余赢老也，可重任乎？七日不克，必尔乎取之！」五月庚寅，荀偃、士□帅卒攻逼阳，亲受矢石。甲午，灭之。书曰「遂灭逼阳」，言自会也。以与向戌，向戌辞曰：「君若犹辱镇抚宋国，而以逼阳光启寡君，群臣安矣，其何贶如之？若专赐臣，是臣兴诸侯以自封也，其何罪大焉？敢以死请。」乃予宋公。
宋公享晋侯于楚丘，请以《桑林》。荀罃辞。荀偃、士□曰：「诸侯宋、鲁，于是观礼。鲁有禘乐，宾祭用之。宋以《桑林》享君，不亦可乎？」舞，师题以旌夏，晋侯惧而退入于房。去旌，卒享而还。及着雍，疾。卜，桑林见。荀偃、士□欲奔请祷焉。荀罃不可，曰：「我辞礼矣，彼则以之。犹有鬼神，于彼加之。」晋侯有间，以逼阳子归，献于武宫，谓之夷俘。逼阳妘姓也。使周内史选其族嗣，纳诸霍人，礼也。
师归，孟献子以秦堇父为右。生秦丕兹，事仲尼。
六月，楚子囊、郑子耳伐宋，师于訾毋。庚午，围宋，门于桐门。
晋荀罃伐秦，报其侵也。
卫侯救宋，师于襄牛。郑子展曰：「必伐卫，不然，是不与楚也。得罪于晋，又得罪于楚，国将若之何？」子驷曰：「国病矣！」子展曰：「得罪于二大国，必亡。病不犹愈于亡乎？」诸大夫皆以为然。故郑皇耳帅师侵卫，楚令也。孙文子卜追之，献兆于定姜。姜氏问繇。曰：「兆如山陵，有夫出征，而丧其雄。」姜氏曰：「征者丧雄，御寇之利也。大夫图之！」卫人追之，孙蒯获郑皇耳于犬丘。
秋七月，楚子囊、郑子耳伐我西鄙。还，围萧，八月丙寅，克之。九月，子耳侵宋北鄙。孟献子曰：「郑其有灾乎！师竞已甚。周犹不堪竞，况郑乎？有灾，其执政之三士乎！」
莒人间诸侯之有事也，故伐我东鄙。
诸侯伐郑。齐崔杼使大子光先至于师，故长于滕。己酉，师于牛首。
初，子驷与尉止有争，将御诸侯之师而黜其车。尉止获，又与之争。子驷抑尉止曰：「尔车，非礼也。」遂弗使献。初，子驷为田洫，司氏、堵氏、侯氏、子师氏皆丧田焉，故五族聚群不逞之人，因公子之徒以作乱。于是子驷当国，子国为司马，子耳为司空，子孔为司徒。冬十月戊辰，尉止、司臣、侯晋、堵女父、子师仆帅贼以入，晨攻执政于西宫之朝，杀子驷、子国、子耳，劫郑伯以如北宫。子孔知之，故不死。书曰「盗」，言无大夫焉。
子西闻盗，不儆而出，尸而追盗，盗入于北宫，乃归授甲。臣妾多逃，器用多丧。子产闻盗，为门者，庀群司，闭府库，慎闭藏，完守备，成列而后出，兵车十七乘，尸而攻盗于北宫。子蟜帅国人助之，杀尉止，子师仆，盗众尽死。侯晋奔晋。堵女父、司臣、尉翩、司齐奔宋。
子孔当国，为载书，以位序，听政辟。大夫、诸司、门子弗顺，将诛之。子产止之，请为之焚书。子孔不可，曰：「为书以定国，众怒而焚之，是众为政也，国不亦难乎？」子产曰：「众怒难犯，专欲难成，合二难以安国，危之道也。不如焚书以安众，子得所欲，众亦得安，不亦可乎？专欲无成，犯众兴祸，子必从之。」乃焚书于仓门之外，众而后定。
诸侯之师城虎牢而戍之。晋师城梧及制，士鲂、魏绛戍之。书曰「戍郑虎牢」，非郑地也，言将归焉。郑及晋平。楚子囊救郑。十一月，诸侯之师还郑而南，至于阳陵，楚师不退。知武子欲退，曰：「今我逃楚，楚必骄，骄则可与战矣。」栾□曰：「逃楚，晋之耻也。合诸侯以益耻，不如死！我将独进。」师遂进。己亥，与楚师夹颖而军。子矫曰：「诸侯既有成行，必不战矣。从之将退，不从亦退。退，楚必围我。犹将退也。不如从楚，亦以退之。」宵涉颖，与楚人盟。栾□欲伐郑师，荀罃不可，曰：「我实不能御楚，又不能庇郑，郑何罪？不如致怨焉而还。今伐其师，楚必救之，战而不克，为诸侯笑。克不可命，不如还也！」丁未，诸侯之师还，侵郑北鄙而归。楚人亦还。
王叔陈生与伯舆争政。王右伯舆，王叔陈生怒而出奔。及河，王复之，杀史狡以说焉。不入，遂处之。晋侯使士□平王室，王叔与伯舆讼焉。王叔之宰与伯舆之大夫瑕禽坐狱于王庭，士□听之。王叔之宰曰：「筚门闺窦之人而皆陵其上，其难为上矣！」瑕禽曰：「昔平王东迁，吾七姓从王，牲用备具。王赖之，而赐之騂旄之盟，曰：『世世无失职。』若筚门闺窦，其能来东底乎？且王何赖焉？今自王叔之相也，政以贿成，而刑放于宠。官之师旅，不胜其富，吾能无筚门闺窦乎？唯大国图之！下而无直，则何谓正矣？」范宣子曰：「天子所右，寡君亦右之。所在，亦左之。」使王叔氏与伯舆合要，王叔氏不能举其契。王叔奔晋。不书，不告也。单靖公为卿士，以相王室。', '', '', '十年春季，鲁襄公和晋悼公、宋平公、卫献公、曹成公、莒子、邾子、滕子、薛伯、杞伯、小邾子、齐国太子光在柤地会见，这是为了会见吴王寿梦。三月二十六日，齐国的高厚作为太子光的相礼，和诸侯在钟离先行会见，表现出不恭敬。士庄子说：“高子作为太子的相礼会见了诸侯，应当捍卫他们的国家，但却表现出不严肃，这是丢弃国家，恐怕将会不免于祸吧！”
夏季，四月初一日，诸侯在柤地会见。
晋国的荀偃、士匄请求进攻偪阳而把它作为向戌的封邑。荀罃说：“城小而坚固，攻下来不算勇敢，攻它不下被人讥笑。”荀偃等人坚决请求。初九日，包围偪阳，不能攻克。孟氏的家臣秦堇父用人力拉了装备车到达战地，偪阳人打开城门，诸侯的将士乘机进攻。内城的人把闸门放下，郰县长官纥双手举门，把进攻城里的将士放出来。狄虒弥把大车轮子立起来，蒙上皮甲作为大盾牌，左手拿着它，右手拔戟，领兵单成一队。孟献子说：“这就是《诗》所说的‘像老虎一样有力气’的人啊。”偪阳的守城人把布挂下来，秦堇父拉着布登城，刚到墙垛，守城人就把布割断。秦堇父跌落在地，守城人又把布挂下来。秦堇父醒起来重新上去，这样三次，守城人表示钦佩他的勇敢，不再挂布。这才退兵，把割的布做了带子在军内游行示众三天。
诸侯的军队在偪阳很久了，荀偃、士匄请示荀罃说：“快下雨了，恐怕到时不能回去，请您退兵吧。”荀罃发怒，把弩机向他们扔过去，机从两个人中间飞过，说：“你们把这两件事情办成了再来跟我说话，原来我恐怕意见不一而扰乱了军令，所以不违背你们。你们既已使国君勤劳而发动了诸侯的军队，牵着我老头子到了这里，既没有坚持进攻，而又想归罪于我，回去说：‘就是他下令退兵。不这样，攻下来了。’我已经衰老了，还能再承担一次罪责吗？七天攻不下来，一定要取你们的脑袋！”五月初四日，荀偃、士匄率领步兵攻打偪阳，亲身受到箭和石块的攻击，初八日，灭亡了偪阳。《春秋》记载说“遂灭偪阳”，说的是从柤地盟会以后就进攻了偪阳。把偪阳封给向戌。向戌辞谢说：“如果还承蒙君王安抚宋国，而用偪阳来扩大寡君的疆土，下臣们就安心了，还有什么比得上这样的赐予呢？如果专门赐给下臣，那就是下臣发动诸侯的军队而为自己求得封地了，还有什么罪过比这再大呢？谨以一死来请求。”于是就把偪阳给了宋平公。
宋平公在楚丘设宴招待晋悼公，请求使用《桑林》之乐舞。荀罃辞谢。荀偃、士匄说：“诸侯中的鲁国、宋国，在那里可以参观礼仪。鲁国有禘乐，在招待贵宾和举行大祭的时候用它。宋国使用《桑林》之舞招待国君，不也是可以的吗？”开始舞蹈，乐师手举旌夏之旗率领乐队进来，晋悼公害怕而退入房里。宋国人去掉旌夏，使这次宴会顺利结束，晋悼公方才回国。到达著雍，晋悼公生病。占卜，从卜兆里见到桑林之神。荀偃、士匄想要奔回宋国请求祈祷，荀罃不同意，说：“我们已经辞去这种礼仪了，他们还是要用它。如果有鬼神，会把灾祸加在他们身上的。”晋悼公病愈，带了偪阳子回国，奉献于武宫，把它称为夷人俘虏。偪阳，是姓妘的一族统治的。晋悼公派周朝的内史选择妘姓宗族的族嗣，让他们居住在霍人地方，这是合于礼的。
鲁军回国，孟献子让秦堇父做车右。秦堇父生了秦丕兹，拜孔子为师。
六月，楚国的子囊、郑国的子耳进攻宋国，军队驻扎在訾毋。十四日，包围宋国，攻打桐门。
晋国的荀罃进攻秦国，这是为了报复秦国的入侵。
卫献公救援宋国，军队驻在襄牛。郑国的子展说：“一定要进攻卫国。不这样，就是不亲附楚国了。得罪了晋国，又得罪了楚国，国家怎么办？”子驷说：“国家已经很困乏了。”子展说：“得罪了两个大国，一定灭亡。困乏，不还比灭亡强一些吗？”大夫们都认为子展的话说得对，所以郑国的皇耳入侵卫国，这是出于楚国的命令。
孙文子为追逐郑国军队占卜，把卜兆献给定姜。定姜问繇辞怎么样。孙文子说：“繇辞是：‘卜兆如同山陵，有人出国征伐，丧失他们的英雄。’”定姜说：“征伐而丧失英雄，这是有利于抵御敌人的。大夫考虑一下！”卫国人追逐郑国军队，孙蒯在犬耳俘虏了郑将皇耳。
秋季七月，楚国的子囊、郑国的子耳联军入侵我国西部边境。回国，包围萧地。八月十一日，攻克萧地。九月，子耳入侵宋国北部边境。孟献子说：“郑国恐怕有灾祸吧！军队争战太过分了。周天子还经不起经常用兵，何况郑国呢？有灾祸，恐怕会在执政的三位大夫身上吧！”
莒国人钻了诸侯有战事的空子，所以进攻我国东部边境。
诸侯发兵攻打郑国，齐国的崔杼让太子光先到达军队里，所以排在滕国前面。二十五日，军队驻扎在牛首。
当初，子驷和尉止有争执，在将要抵御诸侯军队的时候减少了尉止的兵车。尉止俘虏了敌人，子驷又和他争夺功劳。子驷压抑尉止说：“你的战车太多不合礼制。”于是就不让他献俘虏。当初，子驷疏通田里的水沟，司氏、堵氏、侯氏、子师氏都丧失了土田。所以五个宗族聚集了一伙不得志的人凭借了公子的族党以发动叛乱。这时候子驷掌握国政，子国做司马，子耳做司空，子孔做司徒。冬季，十月十四日，尉止、司臣、侯晋、堵女父、子师仆率领叛乱分子进入，早晨在西宫的朝廷上攻打执政，杀死了子驷、子国、子耳，劫持郑简公到了北宫。子孔事先知道这件事，所以没有死。《春秋》记载说“盗”，这是说没有大夫参预这次叛乱。
子西听说有叛乱，不设警戒就出来了，收了他父亲子驷的尸骨就去追赶叛乱分子。叛乱分子进入北宫，子西就回去，召集甲兵，但是家臣和妾婢多数已经逃走，器物也已经大多丢失。子产听说有叛乱，设置守门的警卫，配齐所有的官员，关闭档案库，慎重收藏，完成防守设备，把士兵排成行列以后才出来，有战车十七辆。子产先收他父亲尸骨然后在北宫攻打叛乱分子，子？率领国内的人们帮助他，杀了尉止、子师仆，这伙叛乱分子全部被杀死。侯晋逃亡到晋国，堵女父、司臣、尉翩、司齐逃亡到宋国。
子孔掌握国政，制作盟书，规定官员各守其位、听取执政的法令。大夫、官员们、卿的嫡子不肯顺从，子孔准备加以诛杀。子产劝阻他，请求烧掉盟书。子孔不同意，说：“制作盟书用来安定国家，大伙发怒就烧了它，这是大伙当政，国家不也很为难了吗？”子产说：“大伙怒气难于触犯，专权的愿望难于成功，把两件难办的事合在一起来安定国家，这是危险的办法。不如烧掉盟书来安定大家，您得到了所需要的东西，大伙也能够安定，不也是可以的吗？专权的愿望不能成功，触犯大伙会发生祸乱，您一定要听我的话。”于是就在仓门外边烧掉了盟书，大伙这才安定下来。
诸侯的军队在虎牢筑城并且戍守，晋国军队在梧地和制地筑城，士鲂、魏绛戍守。《春秋》记载说“戍郑虎牢”，不是郑国的领土而这样记载，这是说将要归还给郑国了。郑国和楚国讲和。楚国的子囊救援郑国。十一月，诸侯联军环绕郑国然后往南，到达阳陵，楚军不退。知武子想要退兵，说：“现在我们避开楚军，楚军必然骄傲，骄傲了就可以和他们打仗了。”栾黡说：“避开楚军，这是晋国的耻辱。会和诸侯来增加耻辱，不如一死。我打算单独进军。”军队就往前推进。十六日，和楚军隔着颍水相对而驻扎下来。郑将子？说：“诸侯已经完成了退兵准备，一定不会作战了。顺从他们要退兵，不顺从他们也要退兵。他们退兵，楚国必然包围我们。同样是要退兵，不如顺从楚国，用这样的办法让他们退兵。”郑军夜里渡过颍水，和楚国人结盟。栾黡想要攻打郑国军队，荀罃不同意，说：“我们实在不能抵抗楚军，又不能保护郑国，郑国有什么罪？不如把怨恨奉送给楚国然后回去。现在攻打他们的军队，楚国必然救援他们。作战不能胜利，就被诸侯笑话，胜利不能肯定，不如回去吧。”二十四日，诸侯的军队撤退，攻打了郑国的北部边境然后回国。楚国人也退兵回国。
王叔陈生和伯舆争夺政权，周灵王赞助伯舆。王叔陈生发怒而逃亡。到达黄河，周灵王让他官复原位，杀了史狡以让他高兴。王叔陈生不回成周，就住在黄河边上。晋悼公派士匄调和王室的争端，王叔陈生和伯舆提出争讼。王叔的家臣头子和伯舆的大夫瑕禽在周天子的朝廷上争论是非，士匄听取他们的诉讼。王叔的家臣头子说：“柴门小户的人都要陵驾于他上面的人，上面的人就很难处了。”瑕禽说：“从前平王东迁，我们七姓人家跟随周天子，牺牲全都具备，天子信赖他们，而赐给他们用赤牛祭神的盟约，说：‘世世代代不要失职’如果是柴门小户，他们能够来到东方而住下来吗？而且天子又怎么信赖他们呢？现在自从王叔把持周政权，政事用贿赂来完成，而把执行法律的责任放在宠臣身上。官员中的师和旅，阔气得没有办法，这样，我们能够不是柴门小户吗？请大国考虑一下！下面的人就不能有理，那么什么叫做公正呢？”士匄说：“天子所赞助的，寡君也赞助他；天子所不赞助的，寡君也不赞助他。”就让王叔和伯舆对证讼辞，王叔拿不出他的文件来。王叔逃亡到晋国，《春秋》所以没有记载，这是由于没有通告鲁国的缘故。单靖公做了卿士以辅助王室。', NULL, '', 'indent', 1559039293, '5cec9cb943e78c0067207a48', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643029, '左传 · 襄公 · 襄公十一年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有一年春王正月，作三军。夏四月，四卜郊，不从，乃不郊。郑公孙舍之帅师侵宋。公会晋侯、宋公、卫侯、曹伯、齐世子光、莒子、邾子、滕子、薛伯、杞伯、小邾子伐郑。秋七月己未，同盟于亳城北。公至自伐郑。楚子、郑伯伐宋。公会晋侯、宋公、卫侯、曹伯、齐世子光、莒子、邾子、滕子、薛伯、杞伯、小邾子伐郑，会于萧鱼。公至自会。楚执郑行人良霄。冬，秦人伐晋。
【传】十一年春，季武子将作三军，告叔孙穆子曰：「请为三军，各征其军。」穆子曰：「政将及子，子必不能。」武子固请之，穆子曰：「然则盟诸？」乃盟诸僖闳，诅诸五父之衢。
正月，作三军，三分公室而各有其一。三子各毁其乘。季氏使其乘之人，以其役邑入者，无征；不入者，倍征。孟氏使半为臣，若子若弟。叔孙氏使尽为臣，不然，不舍。
郑人患晋、楚之故，诸大夫曰：「不从晋，国几亡。楚弱于晋，晋不吾疾也。晋疾，楚将辟之。何为而使晋师致死于我，楚弗敢敌，而后可固与也。」子展曰：「与宋为恶，诸侯必至，吾从之盟。楚师至，吾又从之，则晋怒甚矣。晋能骤来，楚将不能，吾乃固与晋。」大夫说之，使疆埸之司恶于宋。宋向戌侵郑，大获。子展曰：「师而伐宋可矣。若我伐宋，诸侯之伐我必疾，吾乃听命焉，且告于楚。楚师至，吾又与之盟，而重赂晋师，乃免矣。」夏，郑子展侵宋。
四月，诸侯伐郑。己亥，齐大子光、宋向戌先至于郑，门于东门。其莫，晋荀罃至于西郊，东侵旧许。卫孙林父侵其北鄙。六月，诸侯会于北林，师于向，右还，次于琐，围郑。观兵于南门，西济于济隧。郑人惧，乃行成。
秋七月，同盟于亳。范宣子曰：「不慎，必失诸侯。诸侯道敝而无成，能无贰乎？」乃盟，载书曰：「凡我同盟，毋蕴年，毋壅利，毋保奸，毋留慝，救灾患，恤祸乱，同好恶，奖王室。或间兹命，司慎司盟，名山名川，群神群祀，先王先公，七姓十二国之祖，明神殛之，俾失其民，队命亡氏，踣其国家。」
楚子囊乞旅于秦，秦右大夫詹帅师从楚子，将以伐郑。郑伯逆之。丙子，伐宋。
九月，诸侯悉师以复伐郑。郑人使良霄、大宰石□如楚，告将服于晋，曰：「孤以社稷之故，不能怀君。君若能以玉帛绥晋，不然则武震以摄威之，孤之愿也。」楚人执之，书曰「行人」，言使人也。诸侯之师观兵于郑东门，郑人使王子伯骈行成。甲戌，晋赵武入盟郑伯。冬十月丁亥，郑子展出盟晋侯。十二月戊寅，会于萧鱼。庚辰，赦郑囚，皆礼而归之。纳斥候，禁侵掠。晋侯使叔肸告于诸侯。公使臧孙纥对曰：「凡我同盟，小国有罪，大国致讨，苟有以藉手，鲜不赦宥。寡君闻命矣。」郑人赂晋侯以师悝、师触、师蠲，广车、軘车淳十五乘，甲兵备，凡兵车百乘，歌钟二肆，及其鏄磐，女乐二八。
晋侯以乐之半赐魏绛，曰：「子教寡人和诸戎狄，以正诸华。八年之中，九合诸侯，如乐之和，无所不谐。请与子乐之。」辞曰：「夫和戎狄，国之福也；八年之中，九合诸侯，诸侯无慝，君之灵也，二三子之劳也，臣何力之有焉？抑臣愿君安其乐而思其终也！《诗》曰：『乐只君子，殿天子之邦。乐只君子，福禄攸同。便蕃左右，亦是帅从。』夫乐以安德，义以处之，礼以行之，信以守之，仁以厉之，而后可以殿邦国，同福禄，来远人，所谓乐也。《书》曰：『居安思危。』思则有备，有备无患，敢以此规。」公曰：「子之教，敢不承命。抑微子，寡人无以待戎，不能济河。夫赏，国之典也，藏在盟府，不可废也，子其受之！」魏绛于是乎始有金石之乐，礼也。
秦庶长鲍、庶长武帅师伐晋以救郑。鲍先入晋地，士鲂御之，少秦师而弗设备。壬午，武济自辅氏，与鲍交伐晋师。己丑，秦、晋战于栎，晋师败绩，易秦故也。', '', '', '十一年春季，季武子准备编定三个军，告诉叔孙穆子说：“请编三个军，每家管一个军。”叔孙穆子说：“政权将要轮到您执掌，您一定办不好的。”季武子坚决请求，叔孙穆子说：“那么结个盟吧。”于是就在僖公宗庙门口订立盟约，在五父之衢发誓。
正月，编定三个军，把公室的军队一分为三，而各家掌握一军。三家各自把原有私家车兵合并，季氏让他私人武装中的成员参加军队的免除征税，不参加的人加倍征税。孟氏让他的私邑士兵中的一半，或子或弟做奴隶兵。叔孙氏仍然把他私邑士兵全编为奴隶兵，不这样，就不并入所分的公室军队里。
郑国人担心晋国和楚国，大夫们说：“不顺从晋国，国家几乎灭亡。楚国比晋国弱，而晋国并不急于争夺我国。如果晋国急于争夺我国，楚国会避开他们的。怎么才能让晋军出死力攻打我们，楚国就不敢抵挡，然后才能够坚决依附晋国。”子展说：“向宋国挑衅，诸侯必然来到，我们跟从他们结盟。楚军来到，我们又跟从楚国，这样晋国就更要生气了。晋国如果能不断地前来，楚国将会不能抵挡，我们就坚决依附晋国。”大夫们对这计划表示高兴，派边境的官吏向宋国挑衅。宋国的向戌入侵郑国，俘获甚多。子展说：“可以出兵攻打宋国了。如果我们进攻宋国，诸侯进攻我们必然努力攻击。我们就听从命令，同时报告楚国。楚军来到，我们就和他们结盟而又重重地贿赂晋军，就可以免于祸患了。”夏季，郑国的子展率军入侵宋国。
四月，诸侯联军进攻郑国。十九日，齐国太子光、宋国向戌先到达郑国，驻军在东门外。当天晚上，晋国荀罃到达西郊，往东进攻许国的旧地。卫国孙林父进攻郑国的北部边境。六月，诸侯在北林会见，军队驻扎在向地。又转向西北，驻扎在琐地。包围郑国，在南门外显示军力。又有军队从西边渡过济隧。郑国人畏惧，就向诸侯求和。
秋季，七月，各诸侯和郑国在毫地结盟。范宣子说：“如果盟辞不谨慎，必然失去诸侯。诸侯来往疲乏而没有得到成功，能够没有二心吗？”于是就盟誓。盟书说：“凡是我们同盟国家，不要囤积粮食，不要垄断利益，不要庇护罪人，不要收留坏人。救济灾荒，安定祸患，统一好恶，辅助王室。有人触犯这些命令，司慎、司盟的神，名山、名川的神，各种天神，先王、先公，七姓十二国的祖宗，明察的神灵诛戮他，使他失去百姓，丧君灭族，灭国亡家。”
楚国的子囊向秦国请求出兵，秦国的右大夫詹率领军队跟随楚共王，由楚王率领进攻郑国。郑简公前去迎接表示顺服。七月二十七日，进攻宋国。
九月，诸侯用全部兵力再次进攻郑国，郑国人派良霄、太宰石chuò[“免”字之“儿”换为“比”。一种似兔而大的青色小兽]去到楚国，告诉说准备对晋国顺服，说：“孤由于国家的缘故，不能怀念君王了。君王如果能够用玉帛安抚晋国，不这样，那就用武力对他们加以威慑，这都是我的愿望。”楚国人囚禁了他们。《春秋》记载说“行人”，这是说他们是使者“不应该有罪”的意思。
诸侯联军在东门外示威，郑国人派王子伯骈求和。九月二十六日，晋国的赵武进入郑国和郑简公结盟。冬季十月初九日，郑国的子展出城和晋悼公结盟。十二月初一日，在萧鱼会见。初三日，赦免郑国的俘虏，都给以礼遇放回去。收回巡逻兵，禁止掠夺。晋悼公派叔肸通告诸侯。鲁襄公派臧孙纥回答说：“凡是我们同盟国家，小国有了罪过，大国派兵讨伐，如果稍有所得，很少对小国不加赦免的，寡君听到命令了。”
郑国人赠给晋悼公师悝、师触、师蠲；配对的广车、軘车各十五辆，盔甲武器齐备，和其他战车一共一百辆；歌钟两架以及和它相配的鎛和磬；女乐两佾十六人。晋悼公把乐队的一半赐给魏绛，说：“您教寡人同各部落戎狄讲和以整顿中原诸国，八年中间九次会合诸侯，好像音乐的和谐，没有地方不协调，请和您一起享用快乐。”魏绛辞谢说：“同戎狄讲和，这是国家的福气。八年中间九次会合诸侯，诸侯顺从，这是由于君王的威灵，也是由于其他人员的功劳，下臣有什么力量？然而下臣希望君王既安于这种快乐，而又想到它的终了。《诗》说：‘快乐啊君子，镇抚天子的家邦。快乐啊君子，他的福禄和别人同享。治理好附近的小国，使他们相率服从。’音乐用来巩固德行，用道义对待它，用礼仪推行它，用信用保守它，用仁爱勉励它，然后能用来安定邦国、同亨福禄、召来远方的人，这就是所说的快乐。《书》说：‘处于安定要想到危险。’想到了就有防备，有了防备就没有祸患。谨以此向君王规劝。”晋悼公说：“您的教导，岂敢不承受命令！而且要是没有您，寡人无法对待戎人，又不能渡过黄河。赏赐，是国家的典章，藏在盟府，不能废除的。您还是接受吧！”魏绛从这时开始才有了金石的音乐，这是合于礼的。
秦国庶长鲍、庶长武领兵进攻晋国来救援郑国。鲍先进入晋国国境，士鲂抵御他，认为秦军人少而不加防备。十二月初五日，武从辅氏渡河，和鲍夹攻晋军。十二日，秦军和晋军在栎地作战，晋军大败，这是由于轻视秦军的缘故。', NULL, '', 'indent', 1559039445, '5cec9d537b968a007671b157', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643030, '左传 · 襄公 · 襄公十二年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有二年春王二月，莒人伐我东鄙，围台。季孙宿帅师救台，遂入郓。夏，晋侯使士鲂来聘。秋九月，吴子乘卒。冬，楚公子贞帅师侵宋。公如晋。
【传】十二年春，莒人伐我东鄙，围台。季武子救台，遂入郓，取其钟以为公盘。
夏，晋士鲂来聘，且拜师。
秋，吴子寿梦卒。临于周庙，礼也。凡诸侯之丧，异姓临于外，同姓于宗庙，同宗于祖庙，同族于祢庙。是故鲁为诸姬，临于周庙。为邢、凡、蒋、茅、胙、祭临于周公之庙。
冬，楚子囊、秦庶长无地伐宋，师于扬梁，以报晋之取郑也。
灵王求后于齐。齐侯问对于晏桓子，桓子对曰：「先王之礼辞有之，天子求后于诸侯，诸侯对曰：『夫妇所生若而人。妾妇之子若而人。』无女而有姊妹及姑姊妹，则曰：『先守某公之遗女若而人。』」齐侯许昏，王使阴里逆之。
公如晋，朝，且拜士鲂之辱，礼也。
秦嬴归于楚。楚司马子庚聘于秦，为夫人宁，礼也。', '', '', '十二年春季，莒国人进攻我国东部边境，包围台地。季武子救援台地，就乘机进入郓国，掠取了他们的钟，改铸为鲁襄公的盘。
夏季，晋国的士鲂来鲁国聘问，同时拜谢我国出兵。
秋季，吴王寿梦死了，鲁襄公在周文王庙哭泣吊唁，这是合于礼的。诸侯的丧事，异姓的在城外哭泣吊唁，同姓的在宗庙里，同宗的在祖庙里，同族的在父庙里。因为这样，鲁国为了姬姓诸国，到周文王庙里哭泣吊唁。为了邢、凡、蒋、茅、胙、祭各国，在周公庙里哭泣吊唁。
冬季，楚国子囊、秦国庶长无地进攻宋国，军队驻扎在杨梁，以报复晋国的得到郑国。
周灵王在齐国求娶王后，齐灵公向晏桓子询问如何答复。桓子回答说：“先王的礼仪辞令有这样的话：天子在诸侯那里求取王后，诸侯回答说：‘夫人所生的若干人，妾妇所生的若干人。’没有女儿而有姐妹和姑母，就说：‘先君某公的遗女若干人。’齐灵公答应了婚事，周灵王派遣阴里作了口头约定。
鲁襄公去到晋国朝见，同时拜谢士鲂的到来，这是合于礼的。
秦赢嫁给楚国，楚国的司马子庚到秦国聘问，为了夫人回娘家，这是合于礼的。', NULL, '', 'indent', 1559039485, '5cec9d7bba39c800688aea9c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643031, '左传 · 襄公 · 襄公十三年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有三年春，公至自晋。夏，取邿。秋九月庚辰，楚子审卒。冬，城防。
【传】十三年春，公至自晋，孟献子书劳于庙，礼也。
夏，邿乱，分为三。师救邿，遂取之。凡书「取」，言易也。用大师焉曰「灭」。弗地曰「入」。
荀罃、士鲂卒。晋侯搜于上以治兵，使士□将中军，辞曰：「伯游长。昔臣习于知伯，是以佐之，非能贤也。请从伯游。」荀偃将中军，士□佐之。使韩起将上军，辞以赵武。又使栾□，辞曰：「臣不如韩起。韩起愿上赵武，君其听之！」使赵武将上军，韩起佐之。栾□将下军，魏绛佐之。新军无帅，晋侯难其人，使其什吏，率其卒乘官属，以从于下军，礼也。晋国之民，是以大和，诸侯遂睦。君子曰：「让，礼之主也。范宣子让，其下皆让。栾□为汰，弗敢违也。晋国以平，数世赖之。刑善也夫！一人刑善，百姓休和，可不务乎？《书》曰：『一人有庆，兆民赖之，其宁惟永。』其是之谓乎？周之兴也，其《诗》曰：『仪刑文王，万邦作孚。』言刑善也。及其衰也，其《诗》曰：『大夫不均，我从事独贤。』言不让也。世之治也，君子尚能而让其下，小人农力以事其上，是以上下有礼，而谗慝黜远，由不争也，谓之懿德。及其乱也，君子称其功以加小人，小人伐其技以冯君子，是以上下无礼，乱虐并生，由争善也，谓之昏德。国家之敝，恒必由之。」
楚子疾，告大夫曰：「不谷不德，少主社稷，生十年而丧先君，未及习师保之教训，而应受多福。是以不德，而亡师于鄢，以辱社稷，为大夫忧，其弘多矣。若以大夫之灵，获保首领以殁于地，唯是春秋窀穸之事，所以从先君于祢庙者，请为『灵』若『厉』。大夫择焉！」莫对。及五命乃许。
秋，楚共王卒。子囊谋谥。大夫曰：「君有命矣。」子囊曰：「君命以共，若之何毁之？赫赫楚国，而君临之，抚有蛮夷，奄征南海，以属诸夏，而知其过，可不谓共乎？请谥之『共』。」大夫从之。
吴侵楚，养由基奔命，子庚以师继之。养叔曰：「吴乘我丧，谓我不能师也，必易我而不戒。子为三覆以待我，我请诱之。」子庚从之。战于庸浦，大败吴师，获公子党。君子以吴为不吊。《诗》曰：「不吊昊天，乱靡有定。」
冬，城防，书事，时也。于是将早城，臧武仲请俟毕农事，礼也。
郑良霄、大宰石□犹在楚。石□言于子囊曰：「先王卜征五年，而岁习其祥，祥习则行，不习则增修德而改卜。今楚实不竞，行人何罪？止郑一卿，以除其逼，使睦而疾楚，以固于晋，焉用之？使归而废其使，怨其君以疾其大夫，而相牵引也，不犹愈乎？」楚人归之。', '', '', '十三年春季，鲁襄公从晋国回来，孟献子在宗庙里记载功勋，这是合于礼的。
夏季，邿国发生动乱，一分为三。出兵救援邿国，就乘机占取了它。凡是《春秋》记载说“取”，就是说事情很容易。使用了大军叫做“灭’。虽得了国家，并不占有它的土地叫做“入”。
荀罃、士鲂死了。晋悼公在绵上打猎并训练军队。派遣士匄率领中军，他辞谢说：“荀偃比我强。过去下臣熟悉知伯，因此辅佐他，而不是由于我的贤能啊。请派遣荀偃。”荀偃率领中军，士匄作为辅佐。派遣韩起率领上军，他辞让给赵武。又派遣栾黡，他辞谢说：“下臣不如韩起。韩起愿意让赵武在上位，君王还是听从他的意见。”就派遣赵武率领上军，韩起作为辅佐。栾黡率领下军，魏绛作为辅佐。新军没有统帅，晋悼公对这个人选感到困难，让新军的十个官吏率领步兵、骑兵和所属官员，附在下军里，这是合于礼的。晋国的百姓因此大大和顺，诸侯也就和睦。
君子说：“谦让，是礼的主体。士匄谦让，他的下属都谦让。栾黡即使专横，也不敢违背。晋国因此而团结，几世都受到利益，这是由于取法于善的缘故啊！一个人取法于善，各族各姓都美好协调，难道可以不尽力于这一点吗？《书》说，‘一个人好善，亿万人有利，国家的安宁可以久长’，说的就是这个吧！周朝兴起的时候，反映它的诗说，‘效法文王，万邦信任’，说的是取法于善。等到它衰弱的时候，反映它的诗说，‘大夫不公平，我所作的独最多’，说的是不谦让。当时世太平的时候，君子崇尚贤能而对下属谦让，小人努力以事奉他的上司，因此上下有礼而奸邪废黜远离，这是由于不争夺的缘故，这叫做美德。到了天下动乱的时候，君子夸耀他的功劳以凌驾于小人之上，小人夸耀他的技能以凌驾于君子之上，因此上下无礼，动乱和残暴一起发生，这是由于争相自以为是。这叫做昏德。国家的败坏，常常是由于这样而来的。”
楚共王生病，告诉大夫说：“寡人没有德行，年幼的时候就做了一国之主。生下来十年而先君去世，没有来得及学习师保的教训而承受了许多福禄，因此缺乏德行而在鄢陵丧失了军队，让国家蒙受耻辱，让大夫担心，这都够严重的了。如果由于大夫的福气，我得以保全首领而善终，在这些祭祀安葬的事情上，得以在祢庙中追随先君，只能请求谥做‘灵’或者‘厉’了，请大夫选择吧。”没有人回答。等到五次命令以后才答应了。
秋季，楚共王去世。子囊和大家商量谥号。大夫说：“国君已经有过命令了。”子囊说：“国君是用‘恭’来命令的，怎么能不用这个字呢？声威赫赫的楚国，国君在上边统治，安抚着蛮夷，大征南海，让他们从属于中原诸国，而国君又知道自己的过错，可以不说是恭吗？请谥做‘共’。”大夫们都听从了他的意见。
吴国侵袭楚国，养由基迅速奔向敌人，子庚领兵跟着去。养由基说：“吴国乘我国有丧事，认为我们是不能出兵的，必然轻视我们而不存戒备之心。您设置三处伏兵来等我，我去引诱他们。”子庚听从了。在庸浦作战，大败吴军，俘虏了公子党。君子认为吴国不善，《诗》说：“上天认为你不善，国家祸乱就不能安定。”
冬季，在防地筑城。《春秋》所以记载这件事，这是由于合于时令。当时准备早些时候筑城，臧武仲请求等待农活完了以后再动工，这是合于礼的。
郑国的良霄、太宰石毚还在楚国。石毚对子囊说：“先王为了征伐，要连续占卜五年，每年重复吉兆，就出兵。如果有一年卜征不吉利，那就更加努力于修养道德而重新占卜。现在楚国实在不能自强，行人有什么罪过？留下郑国一个卿，这就去掉了对郑国君臣的威逼，让他们上下和睦而怨恨楚国，因而坚决顺从晋国，这对楚国有什么好处？让他回去，使他没有完成出使任务，他会埋怨国君和怀恨大夫，因而互相牵制，这不是好一些吗？”于是楚国人就把良霄放了回去。
', NULL, '', 'indent', 1559039557, '5cec9dc2c8959c0069e9755d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643032, '左传 · 襄公 · 襄公十四年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有四年春王正月，季孙宿、叔老会晋士□、齐人、宋人、卫人、郑公孙虿、曹人、莒人、邾人、滕人、薛人、杞人、小邾人会吴于向。二月乙朔，日有食之。夏四月，叔孙豹会晋荀偃、齐人、宋人、卫北宫括、郑公孙虿、曹人、莒人、邾人、滕人、薛人、杞人、小邾人伐秦。己未，卫侯出奔齐。莒人侵我东鄙。秋，楚公子贞帅师伐吴。冬，季孙宿会晋士□、宋华阅、卫孙林父、郑公孙虿、莒人、邾人于戚。
【传】十四年春，吴告败于晋。会于向，为吴谋楚故也。范宣子数吴之不德也，以退吴人。
执莒公子务娄，以其通楚使也。
将执戎子驹支。范宣子亲数诸朝，曰：「来！姜戎氏！昔秦人迫逐乃祖吾离于瓜州，乃祖吾离被苫盖，蒙荆棘，以来归我先君。我先君惠公有不腆之田，与女剖分而食之。今诸侯之事我寡君不知昔者，盖言语漏泄，则职女之由。诘朝之事，尔无与焉！与将执女！」对曰：「昔秦人负恃其众，贪于土地，逐我诸戎。惠公蠲其大德，谓我诸戎，是四岳之裔胄也，毋是剪弃。赐我南鄙之田，狐狸所居，豺狼所嗥。我诸戎除剪其荆棘，驱其狐狸豺狼，以为先君不侵不叛之臣，至于今不贰。昔文公与秦伐郑，秦人窃与郑盟而舍戍焉，于是乎有殽之师。晋御其上，戎亢其下，秦师不复，我诸戎实然。譬如捕鹿，晋人角之，诸戎掎之，与晋踣之，戎何以不免？自是以来，晋之百役，与我诸戎相继于时，以从执政，犹殽志也。岂敢离逖？今官之师旅，无乃实有所阙，以携诸侯，而罪我诸戎！我诸戎饮食衣服，不与华同，贽币不通，言语不达，何恶之能为？不与于会，亦无瞢焉！」赋《青蝇》而退。宣子辞焉，使即事于会，成恺悌也。于是，子叔齐子为季武子介以会，自是晋人轻鲁币，而益敬其使。
吴子诸樊既除丧，将立季札。季札辞曰：「曹宣公之卒也，诸侯与曹人不义曹君，将立子臧。子臧去之，遂弗为也，以成曹君。君子曰：『能守节。』君，义嗣也。谁敢奸君？有国，非吾节也。扎虽不才，愿附于子臧，以无失节。」固立之。弃其室而耕。乃舍之。
夏，诸侯之大夫从晋侯伐秦，以报栎之役也。晋侯待于竟，使六卿帅诸侯之师以进。及泾，不济。叔向见叔孙穆子。穆子赋《匏有苦叶》。叔向退而具舟，鲁人、莒人先济。郑子蟜见卫北宫懿子曰：「与人而不固，取恶莫甚焉！若社稷何？」懿子说。二子见诸侯之师而劝之济，济泾而次。秦人毒泾上流，师人多死。郑司马子蟜帅郑师以进，师皆从之，至于棫林，不获成焉。荀偃令曰：「鸡鸣而驾，塞井夷灶，唯余马首是瞻！」栾□曰：「晋国之命，未是有也。余马首欲东。」乃归。下军从之。左史谓魏庄子曰：「不待中行伯乎？」庄子曰：「夫子命从帅。栾伯，吾帅也，吾将从之。从帅，所以待夫子也。」伯游曰：「吾令实过，悔之何及，多遗秦禽。」乃命大还。晋人谓之迁延之役。
栾金咸曰：「此役也，报栎之败也。役又无功，晋之耻也。吾有二位于戎路，敢不耻乎？」与士鞅驰秦师，死焉。士鞅反，栾□谓士□曰：「余弟不欲住，而子召之。余弟死，而子来，是而子杀余之弟也。弗逐，余亦将杀之。」士鞅奔秦。
于是，齐崔杼、宋华阅、仲江会伐秦，不书，惰也。向之会亦如之。卫北宫括不书于向，书于伐秦，摄也。
秦伯问于士鞅曰：「晋大夫其谁先亡？」对曰：「其栾氏乎！」秦伯曰：「以其汰乎？」对曰：「然。栾□汰虐已甚，犹可以免。其在盈乎！」秦伯曰：「何故？」对曰：「武子之德在民，如周人之思召公焉，爱其甘棠，况其子乎？栾□死，盈之善未能及人，武子所施没矣，而□之怨实章，将于是乎在。」秦伯以为知言，为之请于晋而复之。
卫献公戒孙文子、宁惠子食，皆服而朝。日旰不召，而射鸿于囿。二子从之，不释皮冠而与之言。二子怒。孙文子如戚，孙蒯入使。公饮之酒，使大师歌《巧言》之卒章。大师辞，师曹请为之。初，公有嬖妾，使师曹诲之琴，师曹鞭之。公怒，鞭师曹三百。故师曹欲歌之，以怒孙子以报公。公使歌之，遂诵之。
蒯惧，告文子。文子曰：「君忌我矣，弗先。必死。」并帑于戚而入，见蘧伯玉曰：「君之暴虐，子所知也。大惧社稷之倾覆，将若之何？」对曰：「君制其国，臣敢奸之？虽奸之，庸如愈乎？」遂行，从近关出。公使子蟜、子伯、子皮与孙子盟于丘宫，孙子皆杀之。四月己未，子展奔齐。公如鄄，使子行于孙子，孙子又杀之。公出奔齐，孙氏追之，败公徒于河泽。鄄人执之。
初，尹公佗学射于庚公差，庚公差学射于公孙丁。二子追公，公孙丁御公。子鱼曰：「射为背师，不射为戮，射为礼乎。」射两軥而还。尹公佗曰：「子为师，我则远矣。」乃反之。公孙丁授公辔而射之，贯臂。
子鲜从公，及竟，公使祝宗告亡，且告无罪。定姜曰：「无神何告？若有，不可诬也。有罪，若何告无？舍大臣而与小臣谋，一罪也。先君有冢卿以为师保，而蔑之，二罪也。余以巾栉事先君，而暴妾使余，三罪也。告亡而已，无告无罪。」
公使厚成叔吊于卫，曰：「寡君使瘠，闻君不抚社稷，而越在他竟，若之何不吊？以同盟之故，使瘠敢私于执事曰：『有君不吊，有臣不敏，君不赦宥，臣亦不帅职，增淫发泄，其若之何？』」卫人使大叔仪对曰：「群臣不佞，得罪于寡君。寡君不以即刑而悼弃之，以为君忧。君不忘先君之好，辱吊群臣，又重恤之。敢拜君命之辱，重拜大贶。」厚孙归，覆命，语臧武仲曰：「卫君其必归乎！有大叔仪以守，有母弟鱄以出，或抚其内，或营其外，能无归乎？」
齐人以郲寄卫侯。及其复也，以郲粮归。右宰谷从而逃归，卫人将杀之。辞曰：「余不说初矣，余狐裘而羔袖。」乃赦之。卫人立公孙剽，孙林父、宁殖相之，以听命于诸侯。
卫侯在郲，臧纥如齐，唁卫侯。与之言，虐。退而告其人曰：「卫侯其不得入矣！其言粪土也，亡而不变，何以复国？」子展、子鲜闻之，见臧纥，与之言，道。臧孙说，谓其人曰：「卫君必入。夫二子者，或挽之，或推之，欲无入，得乎？」
师归自伐秦，晋侯舍新军，礼也。成国不过半天子之军，周为六军，诸侯之大者，三军可也。于是知朔生盈而死，盈生六年而武子卒，彘裘亦幼，皆未可立也。新军无帅，故舍之。
师旷侍于晋侯。晋侯曰：「卫人出其君，不亦甚乎？」对曰：「或者其君实甚。良君将赏善而刑淫，养民如子，盖之如天，容之如地。民奉其君，爱之如父母，仰之如日月，敬之如神明，畏之如雷霆，其可出乎？夫君，神之主而民之望也。若困民之主，匮神乏祀，百姓绝望，社稷无主，将安用之？弗去何为？天生民而立之君，使司牧之，勿使失性。有君而为之贰，使师保之，勿使过度。是故天子有公，诸侯有卿，卿置侧室，大夫有贰宗，士有朋友，庶人、工、商、皂、隶、牧、圉皆有亲昵，以相辅佐也。善则赏之，过则匡之，患则救之，失则革之。自王以下，各有父兄子弟，以补察其政。史为书，瞽为诗，工诵箴谏，大夫规诲，士传言，庶人谤，商旅于市，百工献艺。故《夏书》曰：『遒人以木铎徇于路。官师相规，工执艺事以谏。』正月孟春，于是乎有之，谏失常也。天之爱民甚矣。岂其使一人肆于民上，以从其淫，而弃天地之性？必不然矣。」
秋，楚子为庸浦之役故，子囊师于棠以伐吴，吴不出而还。子囊殿，以吴为不能而弗儆。吴人自皋舟之隘要而击之，楚人不能相救。吴人败之，获楚公子宜谷。
王使刘定公赐齐侯命，曰：「昔伯舅大公，右我先王，股肱周室，师保万民，世胙大师，以表东海。王室之不坏，繄伯舅是赖。今余命女环！兹率舅氏之典，纂乃祖考，无忝乃旧。敬之哉，无废朕命！」
晋侯问卫故于中行献子，对曰：「不如因而定之。卫有君矣，伐之，未可以得志而勤诸侯。史佚有言曰：『因重而抚之。』仲虺有言曰：『亡者侮之，乱者取之，推亡固存，国之道也。』君其定卫以待时乎！」
冬，会于戚，谋定卫也。
范宣子假羽毛于齐而弗归，齐人始贰。
楚子囊还自伐吴，卒。将死，遗言谓子庚：「必城郢。」君子谓：「子囊忠。君薨不忘增其名，将死不忘卫社稷，可不谓忠乎？忠，民之望也。《诗》曰：『行归于周，万民所望。』忠也。」', '', '', '十四年春季，吴国到晋国报告战败情况，季孙宿，叔老和晋国的士匄、齐国人、宋国人、卫国人、郑国公孙趸、曹国人、莒国人、邾人、滕人、薛人、杞人、小邾人和吴国人在向地会见，这是为吴国策划进攻楚国的缘故。范宣子责备吴国不道德，以此拒绝了吴国人。
晋国逮捕了莒国的公子务娄，这是因为莒国的使者和楚国有来往。将要逮捕戎子驹支，范宣子亲自在朝廷上责备他，说：“过来，姜戎氏！从前秦国人追逐你的祖父吾离到瓜州，你的祖父吾离身披蓑衣、头戴草帽前来归附我们先君。我们先君惠公只有并不太多的土田，还和你的祖父平分着吃。现在诸侯事奉我们寡君不如从前，这是因为说话泄漏机密，应当是由于你的缘故。明天早晨的事情，你不要参加了。如果参加，将要把你抓起来。”戎子回答说：“从前秦国人仗着他们人多，贪求土地，驱逐我们各部戎人。晋惠公显示了他的大德，说我们各部戎人，都是四岳的后代，不能加以丢弃。赐给我们南部边境的土田，那里是狐狸居住的地方，豺狼嚎叫的地方。我们各部戎人砍伐这里的荆棘，驱逐这里的狐狸豺狼，作为先君不侵犯不背叛的臣下，直到如今没有三心二意。从前晋文公和秦国进攻郑国时，秦国人偷偷地和郑国结盟而并派兵戍守，因此就有殽地的战役。晋国在上边抵御，戎人在下边对抗，秦国的军队回不去，实在是我们各部戎人出力才让他们这样的。譬如捕鹿，晋国人抓住它的角，各部戎人拖住了它的后腿，和晋国一起让它仆倒。戎人为什么不能免于罪责呢？从这个时候以来，晋国的多次战役，我各部戎人没有不按时与晋军共同参加，以追随执事，如同支援殽地战役一样，岂敢违背？现在各级官员恐怕实在有着过失，因而使诸侯有二心反倒要责怪我们各部戎人！我们各部戎人饮食衣服和中原不同，财礼不相往来，言语不通，能够做什么坏事呢？不参加明天的会见，我也没有什么不舒畅的。”赋了《青蝇》这首诗然后退下。范宣子表示歉意，让他参加会见的事务，显示了平易而不听谗言的美德。当时子叔齐子作为季武子的副手而参加会见，从此晋国人减轻了鲁国的财礼而更加敬重鲁国的使臣。
吴子诸樊已经免除了丧服，打算立季札为国君，季札辞谢说：“曹宣公死的时候，诸侯和曹国人不赞成曹成公，打算立子臧为国君。子臧离开了曹国，曹国人就没有按原来的计划去做，以成全了曹成公。君子称赞子臧说‘能够保持节操’。君王是合法的继承人，谁敢冒犯君位？据有国家，不是我的节操。扎虽然没有才能，愿意追随子臧，以不失节操。”诸樊坚决要立他为国君，季札丢掉了他的家产而去种田，于是就不再勉强他。
夏季，诸侯的大夫跟随着晋悼公进攻秦国，以报复栎地一役。晋悼公在国境内等待，让六卿率领诸侯的军队前进。到达泾水，诸侯的军队不肯渡河。叔向进见叔孙穆子，穆子赋《匏有苦叶》这首诗。叔向退出以后就准备船只，鲁国人、莒国人先渡河。郑国的子蟜进见卫国的北宫懿子说：“亲附别人而不坚定，最使人讨厌了，把国家怎么办？”懿子很高兴。两个人去见诸侯的军队而劝他们渡河，军队渡过泾水驻扎下来。秦国人在泾水上游放置毒物，诸侯的军队死去很多。郑国司马子？率领郑国的军队前进，其他国家的军队也都跟上，到达棫林，不能让秦国屈服讲和。荀偃命令说：“鸡叫套车，填井平灶，你只看着我的马首而行动。”栾黡说：“晋国的命令，从来没有这样的。我的马头可要往东呢。”就回国了。下军跟随他回去。左史对魏庄子说：“不等中行伯了吗？”魏庄子说：“他老人家命令我们跟从主将，栾黡，是我的主将，我打算跟从他。跟从主将，也就是合理地对待他老人家。”荀偃说：“我的命令确实有错误，后悔哪里来得及，多留下人马只能被秦国俘虏。”于是就命令全军撤退。晋国人称这次战役为“迁延之役”。
栾鍼说：“这次战役，是为了报复栎地的战败。作战又没有功劳，这是晋国的耻辱。我兄弟俩在兵车上，哪能不感到耻辱呢？”和士鞅冲入秦军中间，战死，士鞅回来。栾黡对士匄说：“我的兄弟不想前去，你的儿子叫他去。我的兄弟战死，你的儿子回来，这是你的儿子杀了我的兄弟。如果不赶走他，我也要杀死他。”士鞅逃亡到秦国。
当时，齐国崔杼、宋国华阅、仲江一起进攻秦国。《春秋》没有记载他们的名字，是由于他们怠惰。向地会见的记载也和这一样。对卫国的北宫括在向地的会见不加记载，而记载在这次攻打秦国的战役中，这是由于他积极帮助的缘故。
秦景公问士鞅说：“晋国的大夫谁先灭亡？”士鞅回答说：“恐怕是栾氏吧！”秦景公说：“由于他的骄横吗？”士鞅回答说：“对。栾黡太骄横了，还可以免于祸难，祸难恐怕要落在栾盈的身上吧！”秦景公说：“为什么？”士鞅回答说：“栾武子的恩德留在百姓中间，好像周朝人思念召公，就爱护他的甘棠树，何况他的儿子呢？栾黡死了，盈的好处没有能到达别人那里，栾武子所施舍的又逐渐完了，而对栾黡的怨恨实在太明显，所以灭亡将会落在栾盈身上了。”秦景公认为这是有见识的话，就为士鞅向晋国请求而恢复了他的职位。
卫献公约请孙文子、宁惠子吃饭，这两个人都穿上朝服在朝廷上等待。太阳快下山了还不召见，反而在林子里射鸿雁。两个人跟到林子里，卫献公不取下皮帽跟他们说话。两个人都生气。孙文子去了戚地，孙蒯入朝请命。卫献公招待孙蒯喝酒，让乐官唱《巧言》的最后一章。乐宫辞谢。乐工师曹请求歌唱这一章。当初，卫献公有一个宠妾，让师曹教她弹琴，师曹鞭打过她。卫献公生气，鞭打师曹三百下。所以现在师曹想利用唱这章诗的机会，来激怒孙蒯，以作为对卫献公的报复。卫献公让师曹歌唱，师曹作了朗诵。
孙蒯恐惧，告诉孙文子。孙文子说：“国君忌恨我了，如果不先下手，就必死于他的手中。”孙文子把家中大小集中在戚地，然后进入国都，遇见蘧伯玉，说：“国君的暴虐，这是您所知道的。我很害怕国家的颠覆，您准备怎么办？”蘧伯玉回答说：“国君控制他的国家，下臣哪里敢冒犯他？即使冒犯了他，立了新的国君，难道能确知比旧的国君会强一些吗？”于是就从最近的关口出国。
卫献公派子蟜、子伯、子皮和孙文子在丘宫结盟，孙文子把他们全都杀了。四月二十六日，子展逃亡到齐国，卫献公到了鄄地，派子行向孙文子请求和解，孙文子又杀了他。卫献公逃亡到齐国，孙家的人追了上去，把卫献公的亲兵在阿泽击败，鄄地人逮捕了败兵。
当初，尹公佗到庾公差那里学射箭，庾公差又到公孙丁那里学射箭，尹公佗和庾公差追逐卫献公，公孙丁驾御卫献公的车子。庾公差说：“如果射，是背弃老师；不射，将被诛戮，射了还是合于礼的吧！”射中了车子两边的曲木然后回去。尹公佗说：“您为了老师，我和他的关系就远了。”于是回过车去追赶。公孙丁把马缰递给卫献公然后向尹公佗射去，射穿了他的臂膀。
子鲜跟随卫献公出亡。到达边境，卫献公派祝宗向祖先报告逃亡，同时说自己没有罪过。定姜说：“如果没有神灵，报告什么？如果有，就不能欺骗。有罪，为什么报告说没有罪？不与大臣商量而和小臣商量，这是第一条罪。先君有正卿作为师保，而你却轻视他们，这是第二条罪。我用手巾梳子事奉过先君，而你残暴地对待我像对婢妾一样，这是第三条罪。只报告逃亡算了，不要报告没有罪！”
鲁襄公派厚成叔到卫国慰问，说：“寡君派遣瘠，听说君王失去了国家而流亡在别国境内，怎么能不来慰问？由于同盟的缘故，谨派瘠私下对大夫们说：‘国君不善良，臣下不明达事理，国君不宽恕，臣下也不尽职责，积怨很久而发泄出来，怎么办？’”卫国人派太叔仪回答，说：“下臣们没有才能，得罪了寡君。寡君不把下臣们依法惩处，反而远远地抛弃了下臣们，以成为君王的忧虑。君王不忘记先君的友好，承您来慰问下臣们，又再加哀怜。谨拜谢君王的命令，再拜谢对下臣们的哀怜。”厚成叔回国复命，告诉臧武仲说：“卫君恐怕会回去的吧！有太叔仪留守，有同胞兄弟鱄和他一起出国。有人安抚国内，有人经营国外，能够不回去吗？”
齐国人把郲地让给卫献公寄住。等到卫献公复位的时候，还带着郲地的粮食回去。右宰穀先跟从卫献公后来又逃回国去，卫国人要杀掉他。他辩解说：“对过去的事情我不是乐于干的。我穿的是狐皮衣羊皮袖子。”于是就赦免了他。卫国人立公孙剽为国君，孙林父、宁殖辅助他，以听取诸侯的命令。
卫献公在郲地，臧纥去到齐国慰问卫献公。卫献公和他说话，态度粗暴。臧纥退出以后告诉他的手下人说：“卫献公大概不能回国了。他的话好像粪土。逃亡在外而不悔改，怎么能够恢复国君的地位呢？”子展、子鲜听说这话，进见臧纥，和他们说话，通情达理。臧纥很高兴，对他的手下人说：“卫君一定能回国。这两个人，有的拉他，有的推他，想不回国，行吗？”
军队进攻秦国回来。晋悼公取消新军，这是合于礼的。大国不超过天子军队的一半。周朝编定六个军，诸侯中强大的，三个军就可以了。当时，知朔生了盈就死去，盈出生六年以后武子就死了，彘裘也还小，都不能做继承人。新军没有主将，所以就取消编制解散了。
师旷随侍在晋悼公旁边，晋悼公说：“卫国人赶走他们的国君，不也太过分了吗？”师旷回答说：“也许是他们国君实在太过分了。好的国君将会奖赏善良而惩罚邪恶，抚养百姓好像儿女，覆盖他们好像上天一样，容纳他们好像大地一样。百姓尊奉国君，热爱他好像父母，尊仰他好像日月，恭敬他好像神灵，害怕他好像雷霆，哪里能够赶走呢？国君，是祭神的主持者同时是百姓的希望。如果让百姓的财货缺乏，神灵失去了祭祀者，百姓绝望，国家没有主人，哪里还用得着他？不赶走干什么？上天生了百姓而立他们的国君，让他统治他们，不让失去天性。有了国君而又为他设立辅佐，让他们去教育保护他，不让他做事过分。由于这样天子有公，诸侯有卿，卿设置侧室，大夫有贰宗，士有朋友，庶人、工、商、皂、隶、牧、圉各有他们亲近的人，用来互相帮助。善良就奖赏，过失就纠正，患难就救援，错失就改正。从天子以下各有父兄子弟来观察补救他们的过失。太史加以记载，乐师写作诗歌，乐工诵读箴谏，大夫规劝开导，士传话，庶人指责，商人在市场上议论，各种工匠献技艺。所以《夏书》说：“宣令的官员摇着木铎在大路上巡行，官师小吏规劝，工匠呈献技艺以作为劝谏。”正月初春，在这个时候有人在路上摇动木铎，这是由于劝谏失去常规的缘故。上天爱护百姓无微不至，难道会让一个人在百姓头上任意妄为，以放纵他的邪恶而失去天地的本性？一定不会这样的。”
秋季，楚康王由于庸浦这次战役的缘故，让子囊在棠地出兵，以攻打吴国。吴军不出战，楚军就回去了。子囊殿后，认为吴国无能因而不加警戒。吴国人从皋舟的险道上拦腰截击楚军，楚国人不能彼此救应，吴国人打败了他们，俘虏了楚国公子宜穀。
周灵王派刘定公将荣宠赐给齐灵公，说：“从前伯舅太公辅助我先王，作为周室的左右手，百姓的师保。世世代代酬谢太师的功劳，为东海各国的表率。王室之所以没有败坏，所依靠的就是伯舅。现在我命令你环，孜孜不倦地遵循舅氏的常法，继承你的祖先，不要玷辱你的先人。要恭敬啊！不要废弃我的命令！”
晋悼公向中行献子询问卫国的事情。中行献子回答说：“不如根据现状而安定它。卫国有国君了，攻打它，不见得能够如愿，反而烦劳诸侯。史佚有话说：‘因为他已经安定而加以安抚。’仲虺有话说：‘灭亡着的可以欺侮，动乱着的可以打倒。推翻已灭亡的巩固已存在的，这是国家的常道。’君王还是安定卫国以等待时机吧！”
冬季，季孙宿和晋国的士匄，宋国华阅、卫国孙林父、郑国公孙虿、莒人、邾人在戚地会见，这是为了商讨安定卫国。
范宣子在齐国借了装饰仪仗的羽毛而不归还，齐国人开始有了二心。
楚国的子囊进攻吴国回来后，就死了。临死，遗言对子庚说：“一定要在郢地筑城。”君子认为：“子囊忠心。国君死，不忘记谥他为‘共’；临死，不忘记保卫国家，难道能不说他忠心吗？忠心，是百姓的希望。《诗》说，‘行动归结到忠信，这是广大百姓的希望’，这就是忠心的意思。”
', NULL, '', 'indent', 1559039602, '5cec9deea673f5006821dff6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643033, '左传 · 襄公 · 襄公十五年', NULL, 2, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有五年春，宋公使向戌来聘。二月己亥，及向戌盟于刘。刘夏逆王后于齐。夏，齐侯伐我北鄙，围成。公救成，至遇。季孙宿、叔孙豹帅师城成郛。秋八月丁巳，日有食之。邾人伐我南鄙。冬十有一月癸亥，晋侯周卒。
【传】十五年春，宋向戌来聘，且寻盟。见孟献子，尤其室，曰：「子有令闻，而美其室，非所望也！」对曰：「我在晋，吾兄为之，毁之重劳，且不敢间。」
官师从单靖公逆王后于齐。卿不行，非礼也。
楚公子午为令尹，公子罢戎为右尹，蒍子冯为大司马，公子櫜师为右司马，公子成为左司马，屈到为莫敖，公子追舒为箴尹，屈荡为连尹，养由基为宫厩尹，以靖国人。君子谓：「楚于是乎能官人。官人，国之急也。能官人，则民无觎心。《诗》云：「嗟我怀人，置彼周行。』能官人也。王及公、侯、伯、子、男，甸、采、卫大夫，各居其列，所谓周行也。」
郑尉氏、司氏之乱，其馀盗在宋。郑人以子西、伯有、子产之故，纳贿于宋，以马四十乘与师伐、师慧。三月，公孙黑为质焉。司城子罕以堵女父、尉翩、司齐与之。良司臣而逸之，托诸季武子，武子置诸卞。郑人醢之，三人也。
师慧过宋朝，将私焉。其相曰：「朝也。」慧曰：「无人焉。」相曰：「朝也，何故无人？」慧曰：「必无人焉。若犹有人，岂其以千乘之相易淫乐之？必无人焉故也。」子罕闻之，固请而归之。
夏，齐侯围成，贰于晋故也。于是乎城成郛。
秋，邾人伐我南鄙。使告于晋，晋将为会以讨邾、莒晋侯有疾，乃止。冬，晋悼公卒，遂不克会。
郑公孙夏如晋奔丧，子蟜送葬。
宋人或得玉，献诸子罕。子罕弗受。献玉者曰：「以示玉人，玉人以为宝也，故敢献之。」子罕曰：「我以不贪为宝，尔以玉为宝，若以与我，皆丧宝也。不若人有其宝。」稽首而告曰：「小人怀璧，不可以越乡。纳此以请死也。」子罕置堵其里，使玉人为之攻之，富而后使复其所。
十二月，郑人夺堵狗之妻，而归诸范氏。
', '', '', '十五年春季，宋国的向戌来鲁国聘问，同时重温过去的盟约。见了孟献子，责备他的房屋太华丽，说：“您有好名声而把房屋修饰得太华丽，这不是别人所希望的。”孟献子回答说：“我在晋国的时候，我哥哥修建的。要毁坏它，又觉得毁坏又得用劳力，而且不敢说哥哥所做的事不对。”
官师跟随单靖公在齐国迎接王后。卿没有去，这是不合于礼的。
楚国公子午做令尹，公子罢戎做右尹，蒍子冯做大司马，公子橐师做右司马，公子成做左司马，屈到做莫敖，公子追舒做箴尹，屈荡做连尹，养由基做宫厩尹，来安定国内的人们。君子认为“楚国在这时候能够合理地安排官职的人选。安排官职的人选，这是国家的当务之急。能够合理地安排，那么百姓就没有非分的想法。《诗》说，‘嗟叹我所怀念的贤人，要把他们全都安排在恰当的职位上’，这就是能够安排官职的人选。天子和公、侯、伯、子、男以及甸、采、卫的各级大夫，各就各位。这就是所说的‘同行’了。”
郑国尉氏、司氏的叛乱，留下的叛乱分子待在宋国。郑国人由于子西、伯有、子产的缘故，用马一百六十匹和师茷、师慧作为财礼送给宋国。三月，公孙黑去宋国作为人质。司城子罕把堵女父、尉翩、司齐给了郑国，认为司臣有才能而放走了他，托付给季武子，武子把他安置在卞地。郑国人把这三个人剁成肉酱。
师慧经过宋国朝廷，打算小便。扶他的人说：“这里是朝廷。”师慧说：“没有人啊。”扶他的人说：“朝廷，为什么没有人？”师慧说：“一定是没有人啊。如果还有人，难道会用拥有千乘战车国家的相国去交换一个演唱淫乐的瞎子？一定是由于没有人的缘故。”子罕听到了，坚决向宋平公请求而让师慧回国。
夏季，齐灵公包围成地，这是因为齐国对晋国有了二心的缘故。在那时候就在成邑建造外城。
秋季，邾国人攻打我国南部边境，我国派使者向晋国报告。晋国准备举行会见以讨伐邾国、莒国。晋悼公有病，就停止下来。冬季，晋悼公死，就没有能举行会见。
郑国的公孙夏去到晋国奔丧吊唁，又派子蟜前去送葬。
宋国有人得到美玉，献给子罕。子罕不受。献玉的人说：“拿给玉工看过，玉工认为是宝物，所以才敢进献。”子罕说：“我把不贪婪作为宝物，你把美玉作为宝物，如果把玉给了我，我们两人都丧失了宝物，不如各人保有自己的宝物。”献玉的人叩头告诉子罕说：“小人带着玉璧，不能够越过乡里，把它送给您是用来免于一死的。”子罕把美玉放在自己的乡里，让玉工为他雕琢，卖出去，使献玉的人富有以后，然后让他回到家里。
十二月，郑国人夺取了堵狗的妻子，让她回到娘家范氏去。
', NULL, '', 'indent', 1559039678, '5cec9e3bc8959c0069e9791c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643034, '左传 · 襄公 · 襄公十六年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有六年春王正月，葬晋悼公。三月，公会晋侯、宋公、卫侯、郑伯、曹伯、莒子、邾子、薛伯、杞伯、小邾子，于湨梁。戊寅，大夫盟。晋人执莒子、邾子以归。齐侯伐我北鄙。夏，公至自会。五月甲子，地震。叔老会郑伯、晋荀偃、卫宁殖、宋人伐许。秋，齐侯伐我北鄙，围郕。大雩。冬，叔孙豹如晋。
【传】十六年春，葬晋悼公。平公即位，羊舌肸为傅，张君臣为中军司马，祁奚、韩襄、栾盈、士鞅为公族大夫，虞丘书为乘马御。改服修官，烝于曲沃。警守而下，会于湨梁。命归侵田。以我故，执邾宣公、莒犁比公，且曰：「通齐、楚之使。」
晋侯与诸侯宴于温，使诸大夫舞，曰：「歌诗必类！」齐高厚之诗不类。荀偃怒，且曰：「诸侯有异志矣！」使诸大夫盟高厚，高厚逃归。于是，叔孙豹、晋荀偃、宋向戌、卫宁殖、郑公孙虿、小邾之大夫盟曰：「同讨不庭。」
许男请迁于晋。诸侯遂迁许，许大夫不可。晋人归诸侯。
郑子蟜闻将伐许，遂相郑伯以从诸侯之师。穆叔从公。齐子帅师会晋荀偃。书曰：「会郑伯。」为夷故也。
夏六月，次于棫林。庚寅，伐许，次于函氏。
晋荀偃、栾□帅师伐楚，以报宋扬梁之役。楚公子格帅师及晋师战于湛阪，楚师败绩。晋师遂侵方城之外，复伐许而还。
秋，齐侯围郕，孟孺子速缴之。齐侯曰：「是好勇，去之以为之名。」速遂塞海陉而还。
冬，穆叔如晋聘，且言齐故。晋人曰：「以寡君之未禘祀，与民之未息。不然，不敢忘。」穆叔曰：「以齐人之朝夕释憾于敝邑之地，是以大请！敝邑之急，朝不及夕，引领西望曰：『庶几乎！』比执事之间，恐无及也！」见中行献子，赋《圻父》。献子曰：「偃知罪矣！敢不从执事以同恤社稷，而使鲁及此。」见范宣子，赋《鸿雁》之卒章。宣子曰：「丐在此，敢使鲁无鸠乎？」
', '', '', '十六年春季，安葬晋悼公。晋平公即位，羊舌肸做太傅，张君臣做中军司马，祁奚、韩襄、栾盈、士鞅做公族大夫，虞丘书做乘马御。改穿吉服，选贤任能，在曲沃举行烝祭。晋平公在国都布置守备以后就沿黄河而下，和鲁襄公、宋平公、卫献公、郑简公、曹成公、莒子、邾子、薛伯、杞伯、小邾子在湨梁会见。命令诸侯退回互相侵占的土田。由于我国的缘故，拘捕了邾宣公、莒犁比公，而且说这两国“使者来往齐国、楚国之间”。
晋平公和诸侯在温地举行宴会，让大夫们舞蹈，说：“唱诗一定要和舞蹈相配合。”齐国高厚的诗与舞蹈配不好。荀偃发怒，并且说：“诸侯有别的想法了。”让大夫们和高厚结盟，高厚逃走回国。当时叔孙豹、晋国荀偃、宋国向戌、卫国宁殖、郑国公孙虿、小邾国的大夫盟誓说：“共同讨伐不忠于盟主的人。”
许灵公向晋国请求迁都。诸侯就让许国迁移，许国的大夫不同意，晋国人让各国诸侯回国而单独出兵进攻许国。
郑国的子蟜听到将要进攻许国，就辅佐郑简公跟从诸侯的军队。穆叔跟从鲁襄公回国。齐子率领军队会见晋国荀偃。《春秋》记载说“会郑伯”，是为了把序列摆平。
夏季，六月，军队驻扎在棫林。初九日，攻进许国，驻扎在函氏。
晋国的荀偃、栾黡带兵进攻楚国，报复在宋国扬梁的那一次战役。楚国的公子格带兵，和晋军在湛坂作战。楚军大败。晋军就侵袭方城山的外边，再次进攻许国然后回国。
秋季，齐灵公包围成地，孟孺子速拦击齐军。齐灵公说：“这个人喜欢勇敢，我们离开这里以使他成名。”孟孺子速就堵塞了海陉险道然后回去。
冬季，穆叔去到晋国聘问，同时说到齐国的事情。晋国人说：“由于寡君还没有举行禘祭和百姓没有安息，所以不能救援，如果不是这样，那是不敢忘记的。”穆叔说：“由于齐国人早晚都在敝邑的土地上发泄愤恨，因此才来郑重请求。敝邑的危急，早晨等不到晚上，伸长了脖子望着西边说：‘也许可以来救援了吧！’等到执事得空闲，恐怕来不及了。”见了中行献子，赋了《圻父》这首诗。献子说“偃知道罪过了，岂敢不跟从执事来一起为国家忧虑，而让鲁国到达这样的地步！”见了范宣子，赋《鸿雁》这首诗的最后一章。范宣子说：“丐在这里，岂敢让鲁国不得安宁？”', NULL, '', 'indent', 1559125454, '5ceded4bc8959c0069f4c926', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643035, '左传 · 襄公 · 襄公十七年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有七年春王二月庚午，邾子卒。宋人伐陈。夏，卫石买帅师伐曹。秋，齐侯伐我北鄙，围桃。高厚帅师伐我北鄙，围防。九月，大雩。宋华臣出奔陈。冬，邾人伐我南鄙。
【传】十七年春，宋庄朝伐陈，获司徒卬，卑宋也。
卫孙蒯田于曹隧，饮马于重丘，毁其瓶。重丘人闭门而呴之，曰：「亲逐而君，尔父为厉。是之不忧，而何以田为？」
夏，卫石买、孙蒯伐曹，取重丘。曹人愬于晋。
齐人以其未得志于我故，秋，齐侯伐我北鄙，围桃。高厚围臧纥于防。师自阳关逆臧孙，至于旅松。郰叔纥、臧畴、臧贾帅甲三百，宵犯齐师，送之而复。齐师去之。
齐人获臧坚。齐侯使夙沙卫唁之，且曰：「无死！」坚稽首曰：「拜命之辱！抑君赐不终，姑又使其刑臣礼于士。」以杙抉其伤而死。
冬，邾人伐我南鄙，为齐故也。
宋华阅卒。华臣弱皋比之室，使贼杀其宰华吴。贼六人以铍杀诸卢门合左师之后。左师惧曰：「老夫无罪。」贼曰：「皋比私有讨于吴。」遂幽其妻，曰：「畀余而大璧！」宋公闻之，曰：「臣也，不唯其宗室是暴，大乱宋国之政，必逐之！」左师曰：「臣也，亦卿也。大臣不顺，国之耻也。不如盖之。」乃舍之。左师为己短策，苟过华臣之门，必聘。
十一月甲午，国人逐□狗，□狗入于华臣氏，国人从之。华臣惧，遂奔陈。
宋皇国父为大宰，为平公筑台，妨于农功。子罕请俟农功之毕，公弗许。筑者讴曰：「泽门之皙，实兴我役。邑中之黔，实尉我心。」子罕闻之，亲执扑，以行筑者，而抶其不勉者，曰：「吾侪小人，皆有阖庐以辟燥湿寒暑。今君为一台而不速成，何以为役？」讴者乃止。或问其故，子罕曰：「宋国区区，而且诅有祝，祸之本也。」
齐晏桓子卒。晏婴粗縗斩，苴絰、带、杖，菅屦，食鬻，居倚庐，寝苫，枕草。其老曰：「非大夫之礼也。」曰：「唯卿为大夫。」
', '', '', '十七年春季，宋国的庄朝进攻陈国，俘虏了司徒卬，这是由于陈国轻视宋国的缘故。
卫国的孙蒯在曹隧打猎，在重丘上让马喝水，打破了水瓶。重丘人关起门来骂他，说：“亲自赶走你的国君，你的父亲做了坏事。你不为这个担忧，为什么来打猎？”
夏季，卫国的石买、孙蒯率兵进攻曹国，占取了重丘。曹国人向晋国提出诉讼。
齐国人由于他们没有能在我国满足愿望的缘故，秋季，齐灵公攻打我国北部边境，包围桃地。高厚把臧纥包围在防地。我军从阳关出动迎接臧纥，到达旅松。郰叔纥、臧畴、臧贾率领甲兵三百人，夜袭齐军，把臧纥送到旅松然后回来。齐军离开了鲁国。
齐国人俘虏了臧坚，齐灵公派夙沙卫去慰问他，并且说“不要死”。臧坚叩头说：“谨拜谢君王的命令。然而君王赐我不死，却又故意派一个宦官来对一个士表示敬意。”臧坚用小木桩刺进伤口而死。
冬季，邾国人进攻我国南部边境，这是为了齐国的缘故。
宋国的华阅死，华臣认为皋比家族力量微弱，派坏人去杀他的家总管华吴。六个坏人用铍刀把华吴杀死在卢门合左师后边。左师害怕，说：“我老头子没有罪。”坏人说：“皋比私自讨伐吴国。”就幽禁了华吴的妻子，说：“把你的大玉璧给我。”宋平公听说这件事，说：“华臣不仅残暴地对待他的宗室，而且使宋国的政令大乱，一定要驱逐他。”左师说：“华臣，也是卿。大臣不和顺，这是国家的耻辱。不如掩盖起来算了。”宋平公就不再加罪。左师讨厌华臣，他给自己做了一根短马鞭子，如果经过华臣的门口，必定快马加鞭。
十一月二十二日，国内的人们追赶疯狗。疯狗跑到华臣家里，人们就跟着追进去。华臣恐惧，就逃亡到陈国。
宋国的皇国父做太宰，给宋平公建造一座台，妨碍了农业收割。子罕请求等待农事完毕以后再建造，平公不答应。筑城的人唱着歌谣说：“泽门里的白面孔，要我们服劳役。城里的黑皮肤，体贴我们的心意。”子罕听到了，亲自拿着竹鞭，巡行督察筑城的人，又鞭打那些不勤快的人，说：“我们这一辈小人都有房子躲避干湿冷热。现在国君造一座台而不很快完成，怎么能做事情呢？”唱歌的人就停止不唱了。有人问他什么缘故？子罕说：“宋国虽小，既有诅咒，又有歌颂，这是祸乱的根本。”
齐国的晏桓子死，晏婴穿着粗布丧服，头上和腰里系着麻带，手执竹杖，脚穿草鞋，喝粥，住在草棚里，睡草垫子，用草作为枕头。他的家臣头子说：“这不是大夫的礼仪。”晏婴说：“唯独具有卿身分的人才是大夫，才能行大夫的礼仪。”', NULL, '', 'indent', 1559125493, '5ceded72d5de2b007090e619', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643036, '左传 · 襄公 · 襄公十八年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有八年春，白狄来。夏，晋人执卫行人石买。秋，齐师伐我北鄙。冬十月，公会晋侯、宋公、卫侯、郑伯、曹伯、莒子、邾子、滕子、薛伯、杞伯、小邾子同围齐。曹伯负刍卒于师。楚公子午帅师伐郑。
【传】十八年春，白狄始来。
夏，晋人执卫行人石买于长子，执孙蒯于纯留，为曹故也。
秋，齐侯伐我北鄙。中行献子将伐齐，梦与厉公讼，弗胜，公以戈击之，首队于前，跪而戴之，奉之以走，见梗阳之巫皋。他日，见诸道，与之言，同。巫曰：「今兹主必死，若有事于东方，则可以逞。」献子许诺。
晋侯伐齐，将济河。献子以朱丝系玉二□，而祷曰：「齐环怙恃其险，负其众庶，弃好背盟，陵虐神主。曾臣彪将率诸侯以讨焉，其官臣偃实先后之。苟捷有功，无作神羞，官臣偃无敢复济。唯尔有神裁之！」沉玉而济。
冬十月，会于鲁济，寻湨梁之言，同伐齐。齐侯御诸平阴，堑防门而守之，广里。夙沙卫曰：「不能战，莫如守险。」弗听。诸侯之士门焉，齐人多死。范宣子告析文子曰：「吾知子，敢匿情乎？鲁人、莒人皆请以车千乘自其乡入，既许之矣。若入，君必失国。子盍图之？」子家以告公，公恐。晏婴闻之曰：「君固无勇，而又闻是，弗能久矣。」齐侯登巫山以望晋师。晋人使司马斥山泽之险，虽所不至，必旗而疏陈之。使乘车者左实右伪，以旗先，舆曳柴而从之。齐侯见之，畏其众也，乃脱归。丙寅晦，齐师夜遁。师旷告晋侯曰：「鸟乌之声乐，齐师其遁。」邢伯告中行伯曰：「有班马之声，齐师其遁。」叔向告晋侯曰：「城上有乌，齐师其遁。」
十一月丁卯朔，入平阴，遂从齐师。夙沙卫连大车以塞隧而殿。殖绰、郭最曰：「子殿国师，齐之辱也。子姑先乎！」乃代之殿。卫杀马于隘以塞道。晋州绰及之，射殖绰，中肩，两矢夹脰，曰：「止，将为三军获。不止，将取其衷。」顾曰：「为私誓。」州绰曰：「有如日！」乃弛弓而自后缚之。其右具丙亦舍兵而缚郭最，皆衿甲面缚，坐于中军之鼓下。
晋人欲逐归者，鲁、卫请攻险。己卯，荀偃、士□以中军克京兹。乙酉，魏绛、栾盈以下军克邿。赵武、韩起以上军围卢，弗克。十二月戊戌，及秦周，伐雍门之萩。范鞅门于雍门，其御追喜以戈杀犬于门中。孟庄子斩其以为公琴。己亥，焚雍门及西郭、南郭。刘难、士弱率诸侯之师焚申池之竹木。壬寅，焚东郭、北郭。范鞅门于扬门。州绰门于东闾，左骖迫，还于门中，以枚数阖。
齐侯驾，将走邮棠。大子与郭荣扣马，曰：「师速而疾，略也。将退矣，君何惧焉！且社稷之主，不可以轻，轻则失众。君必待之。」将犯之，大子抽剑断鞅，乃止。甲辰，东侵及潍，南及沂。
郑子孔欲去诸大夫，将叛晋而起楚师以去之。使告子庚，子庚弗许。楚子闻之，使杨豚尹宜告子庚曰：「国人谓不谷主社稷，而不出师，死不从礼。不谷即位，于今五年，师徒不出，人其以不谷为自逸，而忘先君之业矣。大夫图之！其若之何？」子庚叹曰：「君王其谓午怀安乎！吾以利社稷也。」见使者，稽首而对曰：「诸侯方睦于晋，臣请尝之。若可，君而继之。不可，收师而退，可以无害，君亦无辱。」子庚帅师治兵于汾。于是子蟜、伯有、子张从郑伯伐齐，子孔、子展、子西守。二子知子孔之谋，完守入保。子孔不敢会楚师。
楚师伐郑，次于鱼陵。右师城上棘，遂涉颖，次于旃然。蒍子冯、公子格率锐师侵费滑、胥靡、献于、雍梁，右回梅山，侵郑东北，至于虫牢而反。子庚门于纯门，信于城下而还。涉于鱼齿之下，甚雨及之，楚师多冻，役徒几尽。
晋人闻有楚师，师旷曰：「不害。吾骤歌北风，又歌南风。南风不竞，多死声。楚必无功。」董叔曰：「天道多在西北，南师不时，必无功。」叔向曰：「在其君之德也。」
', '', '', '十八年春季，白狄第一次来鲁国。
夏季，晋国人在长子拘捕了卫国的行人石买，在纯留拘捕了孙蒯，这是为了曹国的缘故。
秋季，齐灵公进攻我国北部边境。中行献子准备进攻齐国，梦见和晋厉公争讼，没有胜诉。晋厉公用戈打他，脑袋在前面掉下来，跪下来安在脖子上，两手捧着他的头走路，见到梗阳的巫皋。过了几天，在路上遇见巫皋，中行献子和他谈起做梦的情况，居然和巫皋梦见的相同。巫皋说：“今年您一定要死，如果在东边有战事，那是可以如愿的。”中行献子答应了。
晋平公发兵进攻齐国，将要渡过黄河，中行献子用朱丝系着两对玉而祷告说：“齐国的环靠着地形险要，仗着人多，丢弃好友违背盟誓，欺凌虐待百姓。陪臣彪将要率领诸侯去讨伐，他的官臣偃在前后辅助，如果得到成功，不要使神灵羞耻，官臣偃不敢再次渡河。惟你神灵加以制裁。”把玉沉入黄河然后渡河。
冬季，十月，鲁襄公和晋平公、宋平公、卫殇公、郑简公、曹成公、莒子、邾子、滕子、薛伯、杞伯、小邾子在鲁国济水上会见，重温湨梁的盟誓，一起进攻齐国。齐灵公在平阴抵御，在防门外挖壕据守，壕沟的长度有一里。夙沙卫说：“如果不能作战，还不如扼守险要为好。”齐灵公不听。诸侯的士兵进攻防门，齐军战死很多人。范宣子告诉析文子说：“我了解您，难道敢隐瞒情况吗？鲁国人、莒国人都请求带一千辆战车从他们那里一往西北，一往东北打进去，我们已经答应了。如果攻进来，贵国君王必然丢掉国家。您何不考虑一下！”析文子把这些话告诉齐灵公，齐灵公听了十分恐惧。晏婴听到了，说：“国君本来没有勇气，而又听到了这些话，活不了多久了。”齐灵公登上巫山观望晋。晋国人派司马排除山林河泽的险阻，虽然是军队达不到的地方，也一定树起大旗而稀疏地布置军阵。让战车左边坐上真人而右边放上伪装的人，用大旗前导，战车后面拖上木柴跟着走。齐灵公看到，害怕晋军人多，就离开军队脱身回去。二十九日，齐军夜里逃走。师旷告诉晋平公说：“乌鸦的声音愉快，齐军恐怕逃走了。”邢伯告诉中行献子说：“有马匹盘旋不进的声音，齐军恐怕逃走了。”叔向告诉晋平公说：“城上有乌鸦，齐军恐怕逃走了。”
十一月初一日，晋军进入平阴，于是就追赶齐军。夙沙卫拉着大车，堵塞山里的小路然后自己作为殿后。殖绰、郭最说：“您来作为国家军队的殿后，这是齐国的耻辱。您姑且先走吧！”便代他殿后。夙沙卫杀了马匹放在狭路上来堵塞道路。晋国的州绰追上来，用箭射殖绰，射中肩膀，两枝箭夹着脖子。州绰说：“停下别跑，你还可以被我军俘虏；不停，我将会向你心口射一箭。”殖绰回过头来说：“你发誓。”州绰说：“有太阳为证！”于是就把弓弦解下来而从后边捆绑殖绰的手，他的车右具丙也放下武器而捆绑郭最，都不解除盔甲从后面捆绑，他们坐在中军的战鼓下边。
晋国人要追赶逃兵，鲁国、卫国请求进攻险要的地方。十三日，荀偃、士匄带领中军攻下京兹。十九日，魏绛、栾盈带领下军攻下邿地；赵武、韩起带领上军包围卢地，没有攻下。十二月初二日，到达秦周地方，砍伐了雍门外边的萩木。范鞅进攻雍门，他的御者追喜用戈在门里杀死一条狗。孟庄子砍下橁木制作颂琴。初三日，放火烧毁了雍门和西边、南边的外城。刘难、士弱率领诸侯的军队放火烧了申池边上的竹子树木。初六日，放火烧了东边、北边的外城，范鞅攻打扬门。州绰攻打东闾，左边的骖马由于拥挤而不能前进，回到门里盘旋，停留很久，把城门门扇上的铜钉都数清楚了。
齐灵公驾了车，准备逃到邮棠去。太子和郭荣牵住马，说：“诸侯的兵行动快速而且勇敢，这是在掠取物资，将要退走了，君王害怕什么？而且国家之主不能逃走，逃走就会失去大众。君王一定要等着！”齐灵公准备冲向前去，太子抽出剑来砍断马缰，这才停了下来。初八日，诸侯的军队向东边进攻到达潍水，南边到达沂水。
郑国的子孔想要除掉大夫们，准备背叛晋国然后发动楚国军队来除掉他们。派人告诉子庚，子庚不答应。楚康王听说了这件事，派扬豚尹宜告诉子庚说：“国内的人们认为我主持国政而不出兵，死后就不能用规定的礼仪安葬祭祀。我即位后，到现在五年，军队不出动，人们恐怕认为我只顾自己安逸而忘了先君的霸业了。大夫考虑一下，怎么办？”子庚叹气说：“君王恐怕认为午是贪图安逸吧！我这样做是为了有利于国家啊。”接见使者，叩头然后回答：“诸侯正和晋国和睦，下臣请求试探一下。如果可行，君王就跟着来。如果不行，收兵而退回去，可以没有损害，君王也不会受到羞辱。” 子庚率领军队在汾地颁发武器。当时子蟜、伯有、子张跟从郑简公进攻齐国，子孔、子展、子西留守。子展、子西两个人知道子孔的策略，就加强守备入城坚守。子孔不敢和楚军会合。
楚军进攻郑国，驻扎在鱼陵。右翼部队在上棘筑城，就徒步渡过颍水，驻扎在旃然水边。蒍子冯、公子格率领精锐部队攻打费滑、胥靡、献于、雍梁，向右绕过梅山，入侵郑国东北部，到达虫牢然后回去。子庚进攻纯门，在城下住了两晚然后回去。军队渡过鱼齿山下的滍水，遇到大雨，楚军大多被冻坏，服杂役的人几乎死光。
晋国人听到楚国出兵，师旷说：“没有妨害。我屡次歌唱北方的曲调，又歌唱南方的曲调。南方的曲调不强，象征死亡的声音很多。楚国一定不能建功。”董叔说：“天象在于西北。南方的军队不合天时，一定不能建功。”叔向说：“决定胜负还在于他们国君的德行。”
