INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643037, '左传 · 襄公 · 襄公十九年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有九年春王正月，诸侯盟于祝柯。晋人执邾子，公至自伐齐。取邾田，自漷水。季孙宿如晋。葬曹成公。夏，卫孙林父帅师伐齐。秋七月辛卯，齐侯环卒。晋士□帅师侵齐，至谷，闻齐侯卒，乃还。八月丙辰，仲孙蔑卒。齐杀其大夫高厚。郑杀其大夫公子嘉。冬，葬齐灵公。城西郛。叔孙豹会晋士□于柯。城武城。
【传】十九年春，诸侯还自沂上，盟于督扬，曰：「大毋侵小。」
执邾悼公，以其伐我故。遂次于泗上，疆我田。取邾田，自漷水归之于我。晋侯先归。公享晋六卿于蒲圃，赐之三命之服。军尉、司马、司空、舆尉、候奄，皆受一命之服。贿荀偃束锦，加璧，乘马，先吴寿梦之鼎。
荀偃瘅疽，生疡于头。济河，及着雍，病，目出。大夫先归者皆反。士□请见，弗内。请后，曰：「郑甥可。」二月甲寅，卒，而视，不可含。宣子盥而抚之，曰：「事吴，敢不如事主！」犹视。栾怀子曰：「其为未卒事于齐故也乎？」乃复抚之曰：「主苟终，所不嗣事于齐者，有如河！」乃暝，受含。宣子出，曰：「吾浅之为丈夫也。」
晋栾鲂帅师从卫孙文子伐齐。季武子如晋拜师，晋侯享之。范宣子为政，赋《黍苗》。季武子兴，再拜稽首曰：「小国之仰大国也，如百谷之仰膏雨焉！若常膏之，其天下辑睦，岂唯敝邑？」赋《六月》。
季武子以所得于齐之兵，作林钟而铭鲁功焉。臧武仲谓季孙曰：「非礼也。夫铭，天子令德，诸侯言时计功，大夫称伐。今称伐则下等也，计功则借人也，言时则妨民多矣，何以为铭？且夫大伐小，取其所得以作彝器，铭其功烈以示子孙，昭明德而惩无礼也。今将借人之力以救其死，若之何铭之？小国幸于大国，而昭所获焉以怒之，亡之道也。」
齐侯娶于鲁，曰颜懿姬，无子。其侄鬲声姬，生光，以为大子。诸子仲子、戎子，戎子嬖。仲子生牙，属诸戎子。戎子请以为大子，许之。仲子曰：「不可。废常，不祥；间诸侯，难。光之立也，列于诸侯矣。今无故而废之，是专黜诸侯，而以难犯不祥也。君必悔之。」公曰：「在我而已。」遂东大子光。使高厚傅牙，以为大子，夙沙卫为少傅。
齐侯疾，崔杼微逆光。疾病，而立之。光杀戎子，尸诸朝，非礼也。妇人无刑。虽有刑，不在朝市。
夏五月壬辰晦，齐灵公卒。庄公即位，执公子牙于句渎之丘。以夙沙卫易己，卫奔高唐以叛。
晋士□侵齐，及谷，闻丧而还，礼也。
于四月丁未，郑公孙虿卒，赴于晋大夫。范宣子言于晋侯，以其善于伐秦也。六月，晋侯请于王，王追赐之大路，使以行，礼也。
秋八月，齐崔杼杀高厚于洒蓝而兼其室。书曰：「齐杀其大夫。」从君于昏也。
郑子孔之为政也专。国人患之，乃讨西宫之难，与纯门之师。子孔当罪，以其甲及子革、子良氏之甲守。甲辰，子展、子西率国人伐之，杀子孔而分其室。书曰：「郑杀其大夫。」专也。子然、子孔，宋子之子也；士子孔，圭妫之子也。圭妫之班亚宋子，而相亲也；二子孔亦相亲也。僖之四年，子然卒，简之元年，士子孔卒。司徒孔实相子革、子良之室，三室如一，故及于难。子革、子良出奔楚，子革为右尹。郑人使子展当国，子西听政，立子产为卿。
齐庆封围高唐，弗克。冬十一月，齐侯围之，见卫在城上，号之，乃下。问守备焉，以无备告。揖之，乃登。闻师将傅，食高唐人。殖绰、工偻会夜缒纳师，醢卫于军。
城西郛，惧齐也。
齐及晋平，盟于大隧。故穆叔会范宣子于柯。穆叔见叔向，赋《载驰》之四章。叔向曰：「肸敢不承命。」穆叔曰：「齐犹未也，不可以不惧。」乃城武城。
卫石共子卒，悼子不哀。孔成子曰：「是谓蹶其本，必不有其宗。」
', '', '', '十九年春季，诸侯从沂水边上回来，在督扬结盟，说：“大国不要侵犯小国。”
逮捕了邾悼公，这是因为进攻我国的缘故。诸侯的军队就驻扎在泗水边上，划定我国的疆界。取得了邾国的土田，从漷水以西的地方都划归我国。
晋平公先回国。鲁襄公在蒲圃设享招待晋国的六卿，赐给他们华丽的三命车服。军尉、司马、司空、舆尉、候奄都接受一命车服。送给荀偃五匹束锦，加上玉璧，四匹马，再送给他吴寿梦的铜鼎。
荀偃长了恶疮，痈疽生在头部。渡过黄河，到达著雍，病危，眼珠子都鼓了出来。大夫先回去的都赶回来。士匄请求进见，荀偃不接见。派人问立谁为继承人，荀偃说：“郑国的外甥可以。”二月十九日，死，眼睛不闭，口闭紧不能放进珠玉。士匄盥洗然后抚摸尸体，说：“事奉吴岂敢不如事奉您！”荀偃的尸体还是没有闭眼。栾怀子说：“是为了齐国的事情没有完成的缘故吗？”就又抚摸着尸体说：“您如果死去以后，我不继续从事于齐国的事情，有河神为证！”荀偃这才闭了眼，接受了放进嘴里的含玉。士匄出去，说：“作为一个男人，我实在是浅薄啊。”
晋国的栾鲂领兵跟从卫国的孙文子进攻齐国。季武子去到晋国拜谢出兵，晋平公设享礼招待他。范宣子主政，赋《黍苗》这首诗。季武子站起来，再拜叩头，说：“小国的仰望大国，好像各种谷物仰望润泽的雨水。如果经常润泽，天下将会和睦，岂独是我国？”就赋了《六月》这首诗。
季武子把在齐国得到的兵器制作了林钟并用铭文记载鲁国的武功，臧武仲对季武子说：“这是不合于礼的。铭文，只是用来记载天子的德行，诸侯用来记载举动合于时令和建立的功绩，大夫用来记载征伐。现在记载征伐，那是降了一等了，记载功劳，那是借助别人的力量；记载合于时令，那么对百姓的妨碍又很多，用什么来载人铭文？而且大国攻打小国，拿他们所得到的东西来制作宗庙器具，记载他们的功绩，以此让子孙看到，这是为了宣扬明德而惩罚无礼。现在是借助了别人的力量来拯救自己的死亡，怎么能记载这个呢？小国侥幸战胜大国，反而显示所得的战利品以激怒敌人，这是亡国之道啊。”
齐灵公从鲁国娶妻，名叫颜懿姬，没有生孩子，她的侄女鬷声姬生了光，齐灵公把子光立为太子。姬妾中有仲子，戎子，戎子受到宠爱。仲子生了牙，把他托付给戎子，戎子请求立牙为太子，齐灵答应了。仲子说：“不行。废弃常规，不吉祥；触犯诸侯，难于成功。光立为太子，已经参与诸侯盟会的行列了。现在没有大罪而废掉他，这是专横而看不起诸侯，而用难于成功的事去触犯不吉祥的事。君王一定会后悔。”齐灵公说：“一切由我。”就把太子光迁移到东部边境，派高厚做牙的太傅，立牙为太子，让夙沙卫做少傅。
齐灵公生病了，崔杼偷偷地把光接来，趁在齐灵公病危的时候，立光为太子。光杀了戎子，把尸体摆在朝廷上，这是不合于礼的。对妇女没有专门的刑罚，即使用刑，也不能把尸体摆在朝廷上。
夏季，五月二十九日，齐灵公死。齐庄公即位，在句渎之丘逮捕了公子牙。齐庄公认为夙沙卫出主意废掉自己，夙沙卫就逃亡到高唐并且叛变。
晋国的士匄入侵齐国，到达穀地，听到齐国的丧事就回去了，这是合于礼的。
四月十三日，郑国的公孙虿死，向晋国的大夫发出讣告。范宣子告诉了晋平公，因为他在进攻秦国的战役中表现很不错。六月，晋平公向周灵王请求，周灵王追赐给他大路的车，让他跟着葬车行走，这是合于礼的。
秋季，八月，齐国崔杼在洒蓝杀了高厚，然后兼并了他的财货采邑。《春秋》记载说：“齐杀其大夫”，这是由于高厚听从了国君昏庸的命令。
郑国的子孔执政独断专行，国内的人们很担心，就追究西宫那次祸难和纯门那次出兵的罪责。子孔应该抵罪，就带领了他的甲士和子革、子良的甲士来保卫自己。十一日，子展、子西率领国内的人们进攻，杀了子孔，瓜分了他的家财采邑。《春秋》记载说“郑杀其大夫”，这是因为子孔独断专行。子然、子孔，是宋子的儿子；士子孔，是圭妫的儿子。圭妫的位置在宋子之下，但是互相亲近，两个子孔也互相亲近。郑僖公四年，子然死；郑简公元年，士子孔死。子孔辅助子革、子良两家，三家像一家一样，所以都遭到祸难。子革、子良逃亡到楚国。子革做了右尹。郑国人让子展主持国事，子西主持政事，立子产为卿。
齐国的庆封率军包围高唐，没有取胜。冬季，十一月，齐庄公亲自领兵包围高唐。见到夙沙卫在城墙上，大声喊他，他就下来了。齐庄公问夙沙卫防守的情况，夙沙卫告诉齐庄公说没有什么防备。齐庄公向夙沙卫作揖，夙沙卫还揖以后，登上城墙。他听说齐军将要依着城墙进攻，就让高唐城里的人好好吃一顿。殖绰、工偻会在夜里垂下城去，迎接齐军进城，把夙沙卫在军中剁成肉酱。
鲁国在外城西边修筑城墙，这是由于畏惧齐国入侵。
齐国和晋国讲和，在大隧结盟。所以穆叔和范宣子在柯地会见。穆叔进见叔向，赋《载驰》这首诗的第四章。叔向说：“肸岂敢不接受命令！”穆叔回国，说：“齐国还没有停止入侵，不能不害怕。”就在武城筑城。
卫国的石共子死了，他的儿子悼子不表示悲哀。孔成子说：“这叫做拔掉了根本，必然不能保有他的宗族。”', NULL, '', 'indent', 1559125578, '5cededc7a673f500682d5666', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643038, '左传 · 襄公 · 襄公二十年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十年春王正月辛亥，仲孙速会莒人盟于向。夏六月庚申，公会晋侯、齐侯、宋公、卫侯、郑伯、曹伯、莒子、邾子、滕子、薛伯、杞伯，小邾子盟于澶渊。秋，公至自会。仲孙速帅师伐邾。蔡杀其大夫公子燮。蔡公子履出奔楚。陈侯之弟黄出奔楚。叔老如齐。冬十月丙辰朔，日有食之。季孙宿如宋。
【传】二十年春，及莒平。孟庄子会莒人，盟于向，督扬之盟故也。
夏，盟于澶渊，齐成故也。
邾人骤至，以诸侯之事，弗能报也。秋，孟庄子伐邾以报之。
蔡公子燮欲以蔡之晋，蔡人杀之。公子履，其母弟也，故出奔楚。
陈庆虎、庆寅畏公子黄之逼，愬诸楚曰：「与蔡司马同谋。」楚人以为讨。公子黄出奔楚。
初，蔡文侯欲事晋，曰：「先君与于践士之盟，晋不可弃，且兄弟也。」畏楚，不能行而卒。楚人使蔡无常，公子燮求从先君以利蔡，不能而死。书曰：「蔡杀其大夫公子燮」，言不与民同欲也；「陈侯之弟黄出奔楚」，言非其罪也。公子黄将出奔，呼于国曰：「庆氏无道，求专陈国，暴蔑其君，而去其亲，五年不灭，是无天也。」
齐子初聘于齐，礼也。
冬，季武子如宋，报向戌之聘也。褚师段逆之以受享，赋《常棣》之七章以卒。宋人重贿之。归，覆命，公享之。赋《鱼丽》之卒章。公赋《南山有台》。武子去所，曰：「臣不堪也。」
卫宁惠子疾，召悼子曰：「吾得罪于君，悔而无及也。名藏在诸侯之策，曰：『孙林父、宁殖出其君。』君入则掩之。若能掩之，则吾子也。若不能，犹有鬼神，吾有馁而已，不来食矣。」悼子许诺，惠子遂卒。', '', '', '二十年春季，鲁国和莒国讲和。孟庄子在向地会见莒人结盟，这是由于有督扬的盟会的缘故。
夏季，鲁襄公和晋平公、齐庄公、宋平公、卫殇公、郑简公、曹武公、莒子、邾子、滕子、薛伯、杞伯、小邾子在澶渊结盟，这是为了和齐国讲和。
邾国人屡次来犯，这是由于邾国认为鲁国参加了诸侯的征伐盟会无力报复的缘故。秋季，孟庄子率兵攻打邾国以作为报复。
蔡国的公子燮想要让蔡国归服晋国，蔡国人杀了他。公子履，是公子燮的同母兄弟，所以逃亡到楚国。
陈国的庆虎、庆寅害怕公子黄的逼迫，向楚国起诉说：“公子黄和蔡国司马一起策划顺服晋国。”楚国人因此而讨伐，公子黄逃亡到楚国去当面辩解。
当初，蔡文侯想要事奉晋国，说：“先君参与了践土的盟会，晋国不能丢弃，而且还是兄弟国家呢。”可是又害怕楚国，没有能够办到就死了。楚国人役使蔡国没有一定的常规，公子燮要求继承先君的遗志以有利于蔡国，没有办到而死去。《春秋》记载说“蔡杀其大夫公子燮”，就是说愿望和百姓的不同；“陈哀公之弟黄出奔楚”，就是说不是公子黄的罪过。公子黄将要逃亡，在国都里喊叫说：“庆氏无道，谋求在陈国专政，轻慢和蔑视国君而去掉他的亲属，五年之内如果不灭亡，这就是没有天理了。”
齐子第一次到齐国聘问，这是合于礼的。
冬季，季武子去到宋国，这是回报向戌的聘问。褚师段迎接他让他接受宋平公的享礼，季武子赋《常棣》这首诗的第七章和最后一章。宋国人重重地送给他财礼。回国复命，鲁襄公设享礼招待他，他赋了《鱼丽》这首诗的最后一章。鲁襄公赋《南山有台》这首诗。季武子离开坐席说：“下臣不敢当。”
卫国的甯殖生了病，告诉悼子说：“我得罪了国君，后悔也来不及了。我的名字记载在诸侯的简册上而加以收藏，说‘孙林父、甯殖赶走他们的国君’。国君回国，你要掩盖这件事。如果能够掩盖它，你就是我的儿子。如果不能，假如有鬼神的话，我宁可挨饿，也不来享受你的祭祀。”悼子答应，宁殖就死了。
', NULL, '', 'indent', 1559125621, '5cededf2c8959c0069f4cf5b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643039, '左传 · 襄公 · 襄公二十一年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有一年春王正月，公如晋。邾庶其以漆、闾丘来奔。夏，公至自晋。秋，晋栾出奔楚。九月庚戌朔，日有食之。冬十月庚辰朔，日有食之。曹伯来朝。公会晋侯、齐侯、宋公、卫侯、郑伯、曹伯、莒子、邾子于商任。
【传】二十一年春，公如晋，拜师及取邾田也。
邾庶其以漆、闾丘来奔。季武子以公姑姊妻之，皆有赐于其从者。
于是鲁多盗。季孙谓臧武仲曰：「子盍诘盗？」武仲曰：「不可诘也，纥又不能。」季孙曰：「我有四封，而诘其盗，何故不可？子为司寇，将盗是务去，若之何不能？」武仲曰：「子召外盗而大礼焉，何以止吾盗？子为正卿，而来外盗；使纥去之，将何以能？庶其窃邑于邾以来，子以姬氏妻之，而与之邑，其从者皆有赐焉。若大盗礼焉以君之姑姊与其大邑，其次皋牧舆马，其小者衣裳剑带，是赏盗也。赏而去之，其或难焉。纥也闻之，在上位者，洒濯其心，壹以待人，轨度其信，可明征也，而后可以治人。夫上之所为，民之归也。上所不为而民或为之，是以加刑罚焉，而莫敢不惩。若上之所为而民亦为之，乃其所也，又可禁乎？《夏书》曰：『念兹在兹，释兹在兹，名言兹在兹，允出兹在兹，惟帝念功。』将谓由己壹也。信由己壹，而后功可念也。」
庶其非卿也，以地来，虽贱必书，重地也。
齐侯使庆佐为大夫，复讨公子牙之党，执公子买于句渎之丘。公子锄来奔。叔孙还奔燕。
夏，楚子庚卒，楚子使薳子冯为令尹。访于申叔豫，叔豫曰：「国多宠而王弱，国不可为也。」遂以疾辞。方署，阙地，下冰而床焉。重茧衣裘，鲜食而寝。楚子使医视之，复曰：「瘠则甚矣，而血气未动。」乃使子南为令尹。
栾桓子娶于范宣子，生怀子。范鞅以其亡也，怨栾氏，故与栾盈为公族大夫而不相能。桓子卒，栾祁与其老州宾通，几亡室矣。怀子患之。祁惧其讨也，愬诸宣子曰：「盈将为乱，以范氏为死桓主而专政矣，曰：『吾父逐鞅也，不怒而以宠报之，又与吾同官而专之，吾父死而益富。死吾父而专于国，有死而已，吾蔑从之矣！』其谋如是，惧害于主，吾不敢不言。」范鞅为之征。怀子好施，士多归之。宣子畏其多士也，信之。怀子为下卿，宣子使城着而遂逐之。
秋，栾盈出奔楚。宣子杀箕遗、黄渊、嘉父、司空靖、邴豫、董叔、邴师、申书、羊舌虎、叔罴。囚伯华、叔向、籍偃。人谓叔向曰：「子离于罪，其为不知乎？」叔向曰：「与其死亡若何？《诗》曰：『优哉游哉，聊以卒岁。』知也。」乐王鲋见叔向曰：「吾为子请！」叔向弗应。出，不拜。其人皆咎叔向。叔向曰：「必祁大夫。。」室老闻之，曰：「乐王鲋言于君无不行，求赦吾子，吾子不许。祁大夫所不能也，而曰『必由之』，何也？」叔向曰：「乐王鲋，从君者也，何能行？祁大夫外举不弃仇，内举不失亲，其独遗我乎？《诗》曰：『有觉德行，四国顺之。』夫子，觉者也。」
晋侯问叔向之罪于乐王鲋，对曰：「不弃其亲，其有焉。」于是祁奚老矣，闻之，乘馹而见宣子，曰：「《诗》曰：『惠我无疆，子孙保之。』《书》曰：『圣有谟勋，明征定保。』夫谋而鲜过，惠训不倦者，叔向有焉，社稷之固也。犹将十世宥之，以劝能者。今壹不免其身，以弃社稷，不亦惑乎？鲧殛而禹兴。伊尹放大甲而相之，卒无怨色。管、蔡为戮，周公右王。若之何其以虎也弃社稷？子为善，谁敢不勉？多杀何为？」宣子说，与之乘，以言诸公而免之。不见叔向而归。叔向亦不告免焉而朝。
初，叔向之母□石叔虎之母美而不使，其子皆谏其母。其母曰：「深山大泽，实生龙蛇。彼美，余惧其生龙蛇以祸女。女，敝族也。国多大宠，不仁人间之，不亦难乎？余何爱焉！」使往视寝，生叔虎。美而有勇力，栾怀子嬖之，故羊舌氏之族及于难。
栾盈过于周，周西鄙掠之。辞于行人，曰：「天子陪臣盈，得罪于王之守臣，将逃罪。罪重于郊甸，无所伏窜，敢布其死。昔陪臣书能输力于王室，王施惠焉。其子□，不能保任其父之劳。大君若不弃书之力，亡臣犹有所逃。若弃书之力，而思□之罪，臣，戮余也，将归死于尉氏，不敢还矣。敢布四体，唯大君命焉！」王曰：「尤而效之，其又甚焉！」使司徒禁掠栾氏者，归所取焉。使候出诸轘辕。
冬，曹武公来朝，始见也。
会于商任，锢栾氏也。齐侯、卫侯不敬。叔向曰：「二君者必不免。会朝，礼之经也；礼，政之舆也；政，身之守也；怠礼失政，失政不立，是以乱也。」
知起、中行喜、州绰、邢蒯出奔齐，皆栾氏之党也。乐王鲋谓范宣子曰：「盍反州绰、邢蒯，勇士也。」宣子曰：「彼栾氏之勇也，余何获焉？」王鲋曰：「子为彼栾氏，乃亦子之勇也。」
齐庄公朝，指殖绰、郭最曰：「是寡人之雄也。」州绰曰：「君以为雄，谁敢不雄？然臣不敏，平阴之役，先二子鸣。」庄公为勇爵。殖绰、郭最欲与焉。州绰曰：「东闾之役，臣左骖迫，还于门中，识其枚数。其可以与于此乎？」公曰：「子为晋君也。」对曰：「臣为隶新。然二子者，譬于禽兽，臣食其肉而寝处其皮矣。」', '', '', '二十一年春季，鲁襄公到晋国，这是为了拜谢出兵和取得邾国的土田。
邾国的庶其带着漆地和闾丘逃亡前来，季武子把鲁襄公的姑母嫁给他作妻子，对他的随从都有赏赐。
当时鲁国的盗贼很多。季武子对臧武仲说：“您为什么不禁止盗贼？”臧武仲说：“盗贼不可以禁止，纥又没有能力。”季武子说：“我国有四面的边境，用来禁止盗贼，为什么不可以？您做司寇，应当从事于禁止盗贼，为什么不能？”武仲说：“您把外边的盗贼叫来而大大地给予礼遇，怎么能禁止国内的盗贼？您做正卿，反而使外边的盗贼进来，让纥禁止国内的盗贼，怎么能够办到？庶其在邾国偷盗了城邑而前来，您把姬氏作为他的妻子，还给了他城邑，他的随从人员都得到赏赐。如果用国君的姑母和他的大城邑对盗表示尊敬，其次的用皂牧车马，再小的给衣服佩剑带子，这是赏赐盗贼。赏赐了而要去掉他，恐怕困难吧。纥听说过，在上位的人要洗涤他的心，专一地以诚待人，使它合于法度而且使人们相信，可以明确地验证，然后才能治理人。上面的所作所为，是百姓的归依。上面所不做的，百姓有人做了，因此加以惩罚就没有人敢于不警戒。如果上面的所作所为百姓也照样做了，这是势所必然，又能够禁止吗？《夏书》说：‘想要干的就是这个，想舍去不干的就是这个，所要号令的就是这个，诚信所在的就是这个，只有天帝才能记下这功劳。’大约说的是要由自身来体现言行一致。诚信是由于自己的言行一致，然后才可以谈建立功劳。”
庶其不是卿，他带着土地来鲁国，虽然身份低贱，《春秋》必定要加以记载，这是为了重视土地。
齐庄公派庆佐做大夫，再次讨伐公子牙的亲族，在句渎之丘抓了公子买。公子锄逃亡前来。叔孙还逃亡到燕国。
夏季，楚国的子庚死。楚康王派薳子冯做令尹，薳子冯与申叔豫商议。申叔豫说：“国家宠臣很多而君王又年轻，国家的事情不能办好。”于是薳子冯就用有病来推辞不干。当时正好是大热天，挖地，放上冰然后安置床。薳子冯身穿新棉衣，又穿上皮袍，少吃东西而睡在床上。楚康王派医生去诊视，回来报告说：“瘦弱到极点了，但血气还正常。”于是楚王就派子南做令尹。
栾桓子娶范宣子的女儿做妻子，生了怀子。范鞅由于他一度逃亡，怨恨栾氏，所以和栾盈一起做公族大夫而不能很好相处。栾桓子死，栾祁和他的家臣头子州宾私通，州宾几乎侵占了全部家产。怀子担心这件事。栾祁害怕怀子讨伐，向范宣子毁谤说：“盈将要发动叛乱，认为范氏弄死了桓子而在晋国专权，说：‘我的父亲赶走范鞅，范鞅回国，不对他表示愤怒反而用宠信来报答他，又和我担任同样的官职，而使他得以独断专权。我的父亲死后范氏更加富有。弄死我父亲而在国内专政，我只有死路一条，也不能跟从他了。’他的计划就是这样，我怕会伤害您，不敢不说。”范鞅为她作证。怀子喜好施舍，很多的士都归附他。宣子害怕他人多，相信了栾祁的话。怀子当时做下卿，宣子派他在著地筑城并且由此赶走了他。
秋季，栾盈逃亡到楚国。宣子杀了箕遗、黄渊、嘉父、司空靖、邴豫、董叔、邴师、申书、羊舌虎、叔罴，同时囚禁了伯华、叔向、籍偃。有人对叔向说：“您得到了罪过，恐怕是不聪明吧！”叔向说：“比起死去和逃亡来怎么样？《诗》说，‘悠闲啊多么逍遥自在，聊且这样来度过岁月’，这才是聪明啊。”乐王鲋去见叔向，说：“我为您去请求免罪。”叔向不回答。乐王鲋退出，叔向不拜送。叔向的手下人都责备叔向。叔向说：“一定要祁大夫才行。”家臣头子听到了，说：“乐王鲋对国君说的话，没有不被采纳的，他想请求赦免您，您又不答应。这是祁大夫所做不到的，但您说一定要由他去办，这是为什么？”叔向说：“乐王鲋，是一切都顺从国君的人，怎么能行？祁大夫举拔宗族外的人不放弃仇人，举拔宗族内的人不失掉亲人，难道只会留下我吗？《诗》说：‘有正直的德行，使四方的国家归顺。’他老人家是正直的人啊。”
晋平公向乐王鲋询问叔向的罪过，乐王鲋回答说：“叔向不丢弃他的亲人，他可能是同谋的。”当时祁奚已经告老回家，听说这情况，坐上快车而去拜见范宣子，说：“《诗》说‘赐给我们无边的恩惠，子子孙孙永远保持它。’《书》说：‘智慧的人有谋略训海，应当相信保护。’说到谋划而少有过错，教育别人而不知疲倦的，叔向是这样的，他是国家的柱石。即使他的十代子孙有过错还要赦免，用这样来勉励有能力的人。现在一旦自身不免于祸而死，放弃国家，这不也会使人困惑吗？鲧被诛戮而禹兴起；伊尹放逐太甲又做了他的宰相，太甲始终没有怨色；管叔、蔡叔被诛戮，周公仍然辅佐成王。为什么叔向要为了叔虎而被杀？您做了好事，谁敢不努力？多杀人作什么？”宣子高兴了，和祁奚共坐一辆车子，向晋平公劝说而赦免了叔向。祁奚不去见叔向就回去了，叔向也不向祁奚报告他已得赦，而就去朝见晋平公。
当初，叔向的母亲嫉妒叔虎的母亲美丽，而不让她陪丈夫睡觉，儿了们都劝谏母亲。叔向的母亲说：“深山大泽之中，确实会生长龙蛇。她美丽，我害怕她生下龙蛇来祸害你们，你们，是衰败的家族，国内受到宠信的大官很多，坏人又从中挑拨，不也是很难处了吗？我自己有什么可爱惜的？”就让叔虎的母亲去陪侍丈夫睡觉，生了叔虎，美丽并有勇力，栾怀子宠爱他，所以羊舌氏这一家族遭到祸难。
栾盈经过成周，周朝西部边境的人，劫掠他的财物。栾盈向周室使者申诉说：“天子的陪臣盈，得罪了天子的守土的臣，打算逃避惩罚。又重新在天子的郊外得罪，没有地方可以逃了，谨冒死上言：从前陪臣书能为王室效力，天子施给了恩惠。他的儿子黡不能保住他父亲的辛劳。天王如果不丢弃书的努力，逃亡在外的陪臣还有地方可以逃。如果丢弃书的努力，而想到黡的罪过，那么陪臣本来就是刑戮余生的人，就将要回国死在尉氏那里，不敢再回来了。谨敢直言不讳，后果怎么样，唯有听天子命令了。”周灵王说：“有了过错而去学它，过错更大了。”于是，周灵王让司徒禁止那些掠夺栾氏的人，所掠取的东西都归还，派迎送宾客的人把栾盈送出轘辕山。
冬季，曹武公前来朝见，这是第一次朝见鲁襄公。
鲁襄公和晋平公、齐庄公、宋平公、卫殇公、郑简公、曹武公、莒子、邾子在商任会见，这是为了禁锢栾盈。齐庄公、卫殇公表现得不恭敬。叔向说：“这两位国君必然不免于祸难。会见和朝见，这是礼仪的常规；礼仪，是政事的车子；政事，是身体的寄托。轻慢礼仪，政事会有失误；政事失误，就难于立身处世，因此就会发生动乱。”
知起、中行喜、州绰、邢蒯逃亡到齐国，他们都是栾氏的亲族。乐王鲋对范宣子说：“为什么不让州绰、邢蒯回来？他们是勇士啊。”宣子说：“他们是栾氏的勇士，我能得到什么？”乐王鲋说：“您如果做他们的栾氏，那就是您的勇士了。”
齐庄公上朝，指着殖绰、郭最说：“这是我的雄鸡。”州绰说：“君王认为他们是雄鸡，谁敢不认为是雄鸡？然而下臣不才，在平阴这次战役中，比他们二位可是先打鸣。”齐庄公设置勇士的爵位，殖绰、郭最想要参加。州绰说：“东闾这次战役，下臣的左骖马被逼迫，盘旋城门里不能前进，记下了门上铜钉的数字，是不是可以在这里有一份呢？”齐庄公说：“您是为的晋君啊。”州绰回答说：“臣下是初来的臣，然而这两位，如果用禽兽作比方，臣下已经吃了他们的肉而睡在他们的皮上了。”', NULL, '', 'indent', 1559125664, '5cedee1cba39c80068965213', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643040, '左传 · 襄公 · 襄公二十二年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有二年春王正月，公至自会。夏四月。秋七月辛酉，叔老卒。冬，公会晋侯、齐侯、宋公、卫侯、郑伯、曹伯、莒子、邾子、薛伯、杞伯、小邾子于沙随。公至自会。楚杀其大夫公子追舒。
【传】二十二年春，臧武仲如晋，雨，过御叔。御叔在其邑，将饮酒，曰：「焉用圣人！我将饮酒而己，雨行，何以圣为？」穆叔闻之曰：「不可使也，而傲使人，国之蠹也。」令倍其赋。
夏，晋人征朝于郑。郑人使少正公孙侨对曰：「在晋先君悼公九年，我寡君于是即位。即位八月，而我先大夫子驷从寡君以朝于执事。执事不礼于寡君。寡君惧，因是行也，我二年六月朝于楚，晋是以有戏之役。楚人犹竞，而申礼于敝邑。敝邑欲从执事而惧为大尤，曰晋其谓我不共有礼，是以不敢携贰于楚。我四年三月，先大夫子蟜又从寡君以观衅于楚，晋于是乎有萧鱼之役。谓我敝邑，迩在晋国，譬诸草木，吾臭味也，而何敢差池？楚亦不竞，寡君尽其土实，重之以宗器，以受齐盟。遂帅群臣随于执事以会岁终。贰于楚者，子侯、石盂，归而讨之。湨梁之明年，子蟜老矣，公孙夏从寡君以朝于君，见于尝酎，与执燔焉。间二年，闻君将靖东夏，四月又朝，以听事期。不朝之间，无岁不聘，无役不从。以大国政令之无常，国家罢病，不虞荐至，无日不惕，岂敢忘职？大国若安定之，其朝夕在庭，何辱命焉？若不恤其患，而以为口实，其无乃不堪任命，而剪为仇雠，敝邑是惧。其敢忘君命？委诸执事，执事实重图之。」
秋，栾盈自楚适齐。晏平仲言于齐侯曰：「商任之会，受命于晋。今纳栾氏，将安用之？小所以事大，信也。失信不立，君其图之。」弗听。退告陈文子曰：「君人执信，臣人执共，忠信笃敬，上下同之，天之道也。君自弃也，弗能久矣！」
九月，郑公孙黑肱有疾，归邑于公。召室老、宗人立段，而使黜官、薄祭。祭以特羊，殷以少牢。足以共祀，尽归其馀邑。曰：「吾闻之，生于乱世，贵而能贫，民无求焉，可以后亡。敬共事君，与二三子。生在敬戒，不在富也。」己巳，伯张卒。君子曰：「善戒。《诗》曰：『慎尔侯度，用戒不虞。』郑子张其有焉。」
冬，会于沙随，复锢栾氏也。
栾盈犹在齐，晏子曰：「祸将作矣！齐将伐晋，不可以不惧。」
楚观起有宠于令尹子南，未益禄，而有马数十乘。楚人患之，王将讨焉。子南之子弃疾为王御士，王每见之，必泣。弃疾曰：「君三泣臣矣，敢问谁之罪也？」王曰：「令尹之不能，尔所知也。国将讨焉，尔其居乎？」对曰：「父戮子居，君焉用之？泄命重刑，臣亦不为。」王遂杀子南于朝，轘观起于四竟。子南之臣谓弃疾，请徙子尸于朝，曰：「君臣有礼，唯二三子。」三日，弃疾请尸，王许之。既葬，其徒曰：「行乎？」曰：「吾与杀吾父，行将焉入？」曰：「然则臣王乎？」曰：「弃父事仇，吾弗忍也。」遂缢而死。
复使薳子冯为令尹，公子齮为司马。屈建为莫敖。有宠于薳子者八人，皆无禄而多马。他日朝，与申叔豫言。弗应而退。从之，入于人中。又从之，遂归。退朝，见之，曰：「子三困我于朝，吾惧，不敢不见。吾过，子姑告我。何疾我也？」对曰：「吾不免是惧，何敢告子？」曰：「何故？」对曰：「昔观起有宠于子南，子南得罪，观起车裂。何故不惧？」自御而归，不能当道。至，谓八人者曰：「吾见申叔，夫子所谓生死而肉骨也。知我者，如夫子则可。不然，请止。」辞八人者，而后王安之。
十二月，郑游贩将归晋，未出竟，遭逆妻者，夺之，以馆于邑。丁巳，其夫攻子明，杀之，以其妻行。子展废良而立大叔，曰：「国卿，君之贰也，民之主也，不可以苟。请舍子明之类。」求亡妻者，使复其所。使游氏勿怨，曰：「无昭恶也。」
', '', '', '二十二年春季，臧武仲到晋国去，下雨，去看望御叔。御叔在自己的封邑里，准备喝酒，说：“哪里用得着圣人？我准备喝酒，而他自己冒着雨而来，聪明有什么用？”穆叔听到了，说：“他不配出使反而对使者骄傲，这是国家的蛀虫。”命令把他的赋税增加一倍。
夏季，晋国人让郑国人前去朝见。郑国人派少正公孙侨回答，说：“在晋国先君悼公九年，我寡君在这个时候即了位。即位八个月，我国的先大夫子驷跟从寡君来向执事朝见，执事对寡君不加礼遇，寡君恐惧。由于这一趟，我国二年六月就向楚国朝见，晋国因此有了戏地这一役。楚国人还很强大，但对敝邑表明了礼仪。敝邑想要跟从执事，而又害怕犯下大罪，说，‘晋国恐怕认为我们不尊敬有礼仪的国家’，因此不敢对楚国有二心。我国四年三月，先大夫子？又跟从寡君到楚国观察他们有没有空子可钻，晋国因此有了萧鱼这一役。我们认为敝邑靠近晋国，譬如草木，我们不过是散发出来的气味，哪里敢有不一致？楚国逐渐衰弱，寡君拿出了土地上的全部出产，加上宗庙的礼器，来接受盟约。于是就率领下臣们随着执事到晋国，参加年终的会见。敝邑偏向楚国，是子侯和石盂，回去以后就讨伐了他们。湨梁会盟的第二年，子？已经告老退休了，公孙夏跟从寡君向君王朝见，在尝祭的时候拜见君王，参与了祭祀，饮酒吃肉。隔了两年，听说君王要安定东方，四月，又向君王朝见以听取结盟的日期。在没有朝见的时候，没有一年不聘问，没有一次事情不跟从。由于大国的政令没有定准，国家和家族都很困乏，意外的事情不断发生，没有一天不恐惧，岂敢忘掉自己的职责？大国如果安定敝邑，我们自己会来朝见，哪里用得着命令呢？如果不体恤敝邑的忧患，反而把它作为借口，那就恐怕不能忍受大国的命令，而被大国丢弃成为仇敌了。敝邑害怕这样的后果，岂敢忘记贵君的命令？一切托付给执事，执政深思一下。”
秋季，栾盈从楚国去到齐国。晏平仲对齐庄公说：“商任的会见，接受了晋国的命令。现在接纳栾氏，准备怎么任用他？小国所用来事奉大国的，是信用，失去信用，不能立身立国。君王还是考虑一下。”齐庄公不听。晏平仲退出以后告诉陈文子说：“做人君主的保持信用，做人臣下的保持恭敬。忠实、信用、诚笃、恭敬，上下共同保持它，这是上天的常道。国君自暴自弃，不能长久在位了。”
九月，郑国公孙黑肱有病，把封邑归还给郑简公，召来家臣之长、宗人立了段为后嗣，而且让他减省家臣、祭祀从简。通常的祭祀用羊一只，盛祭有羊和猪，留下足以供给祭祀的土地，其余的全部归还给郑简公，说：“我听说，生在乱世，地位尊贵但能够守贫，不向百姓求取什么，这就能够在别人之后灭亡。恭敬地事奉国君和几位大夫。生存，在于警戒，不在于富有。”二十五日，公孙黑肱死。君子说：“公孙黑肱善于警戒。《诗》说：‘谨慎地使用你公侯的法度，用以警戒意外’，郑国的公孙黑肱恐怕是做到了吧！”
冬季，鲁襄公和晋平公、齐庄公、宋平公、卫侯、郑简公、曹武公、莒子、邾子、薛伯、杞伯、小邾子在沙随会见，这是为了再次禁锢栾氏。
栾盈还是在齐国住着。晏子说：“祸乱将要起来了。齐国将会进攻晋国，不能不使人害怕。”
楚国的观起受到令尹子南的宠信，没有增加俸禄，而有能驾几十辆车子的马匹。楚国人担心这种情况，楚康王打算诛戮他们。子南的儿了弃疾做楚康王的御士，楚康王每次见到他，一定哭泣。弃疾说：“君王三次向下臣哭泣了，谨敢请问是谁的罪过？”楚康王说：“令尹的不善，这是你所知道的。国家打算诛戮他，你还是住着不逃走吗？”弃疾回答说：“父亲被诛戮儿子住着不逃走，君王哪里还能加以任用？泄露命令而加重刑罚，下臣也不会这么做的。”楚康王就把子南杀死在朝廷上，把观起车裂，并把尸体在国内四方示众。子南的家臣对弃疾说：“请求让我们在朝廷上把子南的尸体搬出来。”弃疾说：“君臣之间有规定的礼仪，这只有看他们诸位大臣怎么办了。”过了三天，弃疾请求收尸。楚康王答应了。安葬完毕后，他的手下人说：“出走吗？”弃疾说：“我参与杀我父亲的预谋，出走，有什么地方可以去？”手下人说：“那么还是做君王的臣下吗？”弃疾说：“丢掉父亲事奉仇人，我不能忍受这么做。”弃疾就上吊死了。
楚康王再次派薳子冯做令尹，公子齮做司马，屈建做莫敖。受到薳子冯宠信的有八个人，都没有俸禄而马匹很多。过了些日子，薳子冯上朝，和申叔豫说话，申叔豫不答应而退走。薳子冯跟着他走，申叔豫走进人群中。又跟着他走，申叔豫就回家了。薳子冯退朝，进见申叔豫，说：“您在朝廷上三次不理我，我害怕，不敢不来见您。我有过错，您不妨告诉我，为什么嫌弃我呢？”申叔豫回答说：“我害怕的是不能免于罪，哪里敢告诉您？”薳子冯说：“什么缘故？”申叔豫回答说：“从前观起受子南的宠信，子南有了罪过，观起被车裂，为什么不害怕？”薳子冯自己驾着车子回去，车子都不能走在正道上。到家，对那八个人说：“我进见申叔，这个人就是所谓能使死者复生，使白骨长肉的人啊。能够了解我像这个人一样的就可以留下，否则请就此罢休。”辞退了这八个人，楚康王才对他放心。
十二月，郑国的游眅将要回到晋国去，没有出国境，遇到迎娶妻子的人，游眅夺走了他的妻子，就在那个城里住下。十二月某一天，那个女人的丈夫攻打游眅，并杀死了游眅，带着他的妻子走了。子展废掉了良而立了太叔，说：“国卿，是君主的副手，百姓的主人，不能随便的。请舍弃游眅之流的人。”派人寻求丢失妻子的人，让他回到他的乡里，让游氏不要怨恨他，说：“不要宣扬邪恶了。”', NULL, '', 'indent', 1559125741, '5cedee6a43e78c00672c1921', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643043, '左传 · 襄公 · 襄公二十五年 ', NULL, 0, 300, 0, 2, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有五年春，齐崔杼帅师伐我北鄙。夏五月乙亥，齐崔杼弑其君光。公会晋侯、宋公、卫侯、郑伯、曹伯、莒子、邾子、滕子、薛伯、杞伯、小邾子于夷仪。六月壬子，郑公孙舍之帅师入陈。秋八月己巳，诸侯同盟于重丘。公至自会。卫侯入于夷仪。楚屈建帅师灭舒鸠。冬，郑公孙夏帅师伐陈。十有二月，吴子遏伐楚，门于巢，卒。
【传】二十五年春，齐崔杼帅师伐我北鄙，以报孝伯之师也。公患之，使告于晋。孟公绰曰：「崔子将有大志，不在病我，必速归，何患焉！其来也不寇，使民不严，异于他日。」齐师徒归。
齐棠公之妻，东郭偃之姊也。东郭偃臣崔武子。棠公死，偃御武子以吊焉。见棠姜而美之，使偃取之。偃曰：「男女辨姓，今君出自丁，臣出自桓，不可。」武子筮之，遇《困》三之《大过》三。史皆曰：「吉。」示陈文子，文子曰：「夫从风，风陨，妻不可娶也。且其《繇》曰：『困于石，据于蒺藜，入于其宫，不见其妻，凶。』困于石，往不济也。据于蒺藜，所恃伤也。入于其宫，不见其妻，凶，无所归也。」崔子曰：「嫠也何害？先夫当之矣。」遂取之。庄公通焉，骤如崔氏。以崔子之冠赐人，侍者曰：「不可。」公曰：「不为崔子，其无冠乎？」崔子因是，又以其间伐晋也，曰：「晋必将报。」欲弑公以说于晋，而不获间。公鞭侍人贾举而又近之，乃为崔子间公。
夏五月，莒为且于之役故，莒子朝于齐。甲戌，飨诸北郭。崔子称疾，不视事。乙亥，公问崔子，遂从姜氏。姜入于室，与崔子自侧户出。公拊楹而歌。侍人贾举止众从者，而入闭门。甲兴，公登台而请，弗许；请盟，弗许；请自刃于庙，勿许。皆曰：「君之臣杼疾病，不能听命。近于公宫，陪臣干掫有淫者，不知二命。」公逾墙。又射之，中股，反队，遂弑之。贾举，州绰、邴师、公孙敖、封具、铎父、襄伊、偻堙皆死。祝佗父祭于高唐，至，覆命。不说弁而死于崔氏。申蒯侍渔者，退，谓其宰曰：「尔以帑免，我将死。」其宰曰：「免，是反子之义也。」与之皆死。崔氏杀融蔑于平阴。
晏子立于崔氏之门外，其人曰：「死乎？」曰：「独吾君也乎哉？吾死也。」曰：「行乎？」曰：「吾罪也乎哉？吾亡也。」「归乎？」曰：「君死，安归？君民者，岂以陵民？社稷是主。臣君者，岂为其口实，社稷是养。故君为社稷死，则死之；为社稷亡，则亡之。若为己死而为己亡，非其私昵，谁敢任之？且人有君而弑之，吾焉得死之，而焉得亡之？将庸何归？」门启而入，枕尸股而哭。兴，三踊而出。人谓崔子：「必杀之！」崔子曰：「民之望也！舍之，得民。」卢蒲癸奔晋，王何奔莒。
叔孙宣伯之在齐也，叔孙还纳其女于灵公。嬖，生景公。丁丑，崔杼立而相之。庆封为左相。盟国人于大宫，曰：「所不与崔、庆者。」晏子仰天叹曰：「婴所不唯忠于君利社稷者是与，有如上帝。」乃歃。辛巳，公与大夫及莒子盟。
大史书曰：「崔杼弑其君。」崔子杀之。其弟嗣书而死者，二人。其弟又书，乃舍之。南史氏闻大史尽死，执简以往。闻既书矣，乃还。
闾丘婴以帷缚其妻而栽之，与申鲜虞乘而出，鲜虞推而下之，曰：「君昏不能匡，危不能救，死不能死，而知匿其昵，其谁纳之？」行及弇中，将舍。婴曰：「崔、庆其追我！」鲜虞曰：「一与一，谁能惧我？」遂舍，枕辔而寝，食马而食。驾而行，出弇中，谓婴曰：「速驱这！崔、庆之众，不可当也。」遂来奔。
崔氏侧庄公于北郭。丁亥，葬诸士孙之里，四翣，不跸，下车七乘，不以兵甲。
晋侯济自泮，会于夷仪，伐齐，以报朝歌之役。齐人以庄公说，使隰锄请成。庆封如师，男女以班。赂晋侯以宗器、乐器。自六正、五吏、三十帅、三军之大夫、百官之正长、师旅及处守者，皆有赂。晋侯许之。使叔向告于诸侯。公使子服惠伯对曰：「君舍有罪，以靖小国，君之惠也。寡君闻命矣！」
晋侯使魏舒、宛没逆卫侯，将使卫与之夷仪。崔子止其帑，以求五鹿。
初，陈侯会楚子伐郑，当陈隧者，井堙木刊。郑人怨之，六月，郑子展、子产帅车七百乘伐陈，宵突陈城，遂入之。陈侯扶其大子偃师奔墓，遇司马桓子，曰：「载余！」曰：「将巡城。」遇贾获，载其母妻，下之，而授公车。公曰：「舍而母！」辞曰：「不祥。」与其妻扶其母以奔墓，亦免。子展命师无入公宫，与子产亲御诸门。陈侯使司马桓子赂以宗器。陈侯免，拥社。使其众，男女别而累，以待于朝。子展执絷而见，再拜稽首，承饮而进献。子美入，数俘而出。祝祓社，司徒致民，司马致节，司空致地，乃还。
秋七月己巳，同盟于重丘，齐成故也。
赵文子为政，令薄诸侯之币而重其礼。穆叔见之，谓穆叔曰：「自今以往，兵其少弭矣！齐崔、庆新得政，将求善于诸侯。武也知楚令尹。若敬行其礼，道之以文辞，以靖诸侯，兵可以弭。」
楚薳子冯卒，屈建为令尹。屈荡为莫敖。舒鸠人卒叛楚。令尹子木伐之，及离城。吴人救之，子木遽以右师先，子强、息桓、子捷、子骈、子盂帅左师以退。吴人居其间七日。子强曰：「久将垫隘，隘乃禽也。不如速战！请以其私卒诱之，简师陈以待我。我克则进，奔则亦视之，乃可以免。不然，必为吴禽。」从之。五人以其私卒先击吴师。吴师奔，登山以望，见楚师不继，复逐之，傅诸其军。简师会之，吴师大败。遂围舒鸠，舒鸠溃。八月，楚灭舒鸠。
卫献公入于夷仪。
郑子产献捷于晋，戎服将事。晋人问陈之罪，对曰：「昔虞阏父为周陶正，以服事我先王。我先王赖其利器用也，与其神明之后也，庸以元女大姬配胡公，而封诸陈，以备三恪。则我周之自出，至于今是赖。桓公之乱，蔡人欲立其出。我先君庄公奉五父而立之，蔡人杀之。我又与蔡人奉戴厉公，至于庄、宣，皆我之自立。夏氏之乱，成公播荡，又我之自入，君所知也。今陈忘周之大德，蔑我大惠，弃我姻亲，介恃楚众，以凭陵我敝邑，不可亿逞。我是以有往年之告。未获成命，则有我东门之役。当陈隧者，井堙木刊。敝邑大惧不竟，而耻大姬。天诱其衷，启敝邑之心。陈知其罪，授手于我。用敢献功！」晋人曰：「何故侵小？」对曰：「先王之命，唯罪所在，各致其辟。且昔天子之地一圻，列国一同，自是以衰。今大国多数圻矣！若无侵小，何以至焉？」晋人曰：「何故戎服？」对曰：「我先君武、庄，为平、桓卿士。城濮之役，文公布命，曰：『各复旧职！』命我文公戎服辅王，以授楚捷，不敢废王命故也。」士庄伯不能诘，复于赵文子。文子曰：「其辞顺，犯顺不祥。」乃受之。
冬十月，子展相郑伯如晋，拜陈之功。子西复伐陈，陈及郑平。仲尼曰：「《志》有之：『言以足志，文以足言。』不言，谁知其志？言之无文，行而不远。晋为伯，郑入陈，非文辞不为功。慎辞也！」
楚蒍掩为司马，子木使庀赋，数甲兵。甲午，蒍掩书土田，度山林，鸠薮泽，辨京陵，表淳卤，数疆潦，规偃猪，町原防，牧隰皋，井衍沃，量入修赋。赋车籍马，赋车兵、徒卒、甲楯之数。既成，以授子木，礼也。
十二月，吴子诸樊伐楚，以报舟师之役。门于巢。巢牛臣曰：「吴王勇而轻，若启之，将亲门。我获射之，必殪。是君也死，强其少安！」从之。吴子门焉，牛臣隐于短墙以射之，卒。
楚子以灭舒鸠赏子木。辞曰：「先大夫蒍子之功也。」以与蒍掩。
晋程郑卒。子产始知然明，问为政焉。对曰：「视民如子。见不仁者诛之，如鹰鸇之逐鸟雀也。」子产喜，以语子大叔，且曰：「他日吾见蔑之面而已，今吾见其心矣。」子大叔问政于子产。子产曰：「政如农功，日夜思之，思其始而成其终。朝夕而行之，行无越思，如农之有畔。其过鲜矣。」
卫献公自夷仪使与宁喜言，宁喜许之。大叔文子闻之，曰：「乌乎！《诗》所谓『我躬不说，皇恤我后』者，宁子可谓不恤其后矣。将可乎哉？殆必不可。君子之行，思其终也，思其复也。《书》曰：『慎始而敬终，终以不困。』《诗》曰：『夙夜匪解，以事一人。』今宁子视君不如弈棋，其何以免乎？弈者举棋不定，不胜其耦。而况置君而弗定乎？必不免矣。九世之卿族，一举而灭之。可哀也哉！」
会于夷仪之岁，齐人城郏。其五月，秦、晋为成。晋韩起如秦莅盟，秦伯车如晋莅盟，成而不结。
', '', '', '二十五年春季，齐国的崔杼率领军队进攻鲁国北部边境，报复孝伯那次进攻齐国。鲁襄公担心，派人向晋国报告，孟公绰说：“崔子将要有大志，不在于困扰我国，一定很快回去，担心什么？他来的时候不劫掠，使用百姓不严厉，和平日不同。”齐军空来了一趟而退兵。
齐国棠公的妻子，是东郭偃的姐姐。东郭偃是崔武子的家臣。棠公死，东郭偃为崔武子驾车去吊唁。崔武子看到棠姜很美，便很喜爱她，让东郭偃为他娶过来。东郭偃说：“男女婚配要辨别姓氏。现在您是丁公的后代，下臣是桓公的后代，这可不行。”崔武子占筮，得到《困》卦变成《大过》，太史都说“吉利”。拿给陈文子看，陈文子说：“丈夫跟从风，风坠落妻子，不能娶的。而且它的繇辞说：‘为石头所困，据守在蒺藜中，走进屋，不见妻，凶。’为石头所困，这意味前去不能成功。据守在蒺藜中，这意味所依靠的东西会使人受伤。走进屋，不见妻，凶，这意味无所归宿。”崔武子说：“她是寡妇，有什么妨碍？死去的丈夫已经承担过这凶兆了。”于是崔武子就娶了棠姜。
齐庄公和棠姜私通，经常到崔家去，把崔武子的帽子赐给别人。侍者说：“不行。”齐庄公说：“不用崔子的帽子，难道就没有帽子了？”崔武子由此怀恨齐庄公，又因为齐庄公乘晋国的动乱而进攻晋国，说：“晋国必然要报复。”崔武子想要杀死齐庄公来讨好晋国，而又没有得到机会。齐庄公鞭打了侍人贾举，后来又亲近贾举，贾举就为崔武子找机会杀死齐庄公。
夏季，五月，莒国由于且于这次战役的缘故，莒子到齐国朝见。十六日，齐庄公在北城设享礼招待他，崔武子推说有病，不办公事。十七日，齐庄公去问候崔武子，乘机又与棠姜幽会。姜氏进入室内和崔武子从侧门出去。齐庄公拍着柱子唱歌。侍人贾举禁止庄公的随从入内，自己走进去，关上大门。甲士们一哄而起，齐庄公登上高台请求免死，众人不答应；请求在太庙自杀，还不答应。都说：“君王的下臣崔杼病得厉害。不能听取您的命令。这里靠近君王的宫室，陪臣巡夜搜捕淫乱的人，此外不知道有其他命令。”齐庄公跳墙，有人用箭射他，射中大腿，掉在墙内，于是就杀死了他。贾举、州绰、邴师、公孙敖、封具、铎父、襄伊、偻堙都被杀死。祝佗父在高唐祭祀，到达国都，复命，还没有脱掉官帽，就在崔武子家里被杀死。申蒯，是管理渔业的人，退出来，对他的家臣头子说：“你带着我的妻子儿女逃走，我准备一死。”他的家臣头子说：“如果我逃走，这是违背了您的道义了。”就和申蒯一起自杀。崔氏在平阴杀死了鬷蔑。
晏子立在崔氏的门外边，他的手下人说：“死吗？”晏子说：“是我一个人的国君吗？我去死？”手下人说：“逃吗？”晏子说：“是我的罪过吗？我逃走？”手上人说：“回去吗？”晏子说：“国君死了，回到哪儿去？作为百姓的君主，难道是用他的地位，来凌驾于百姓之上？应当主持国政。作为君主的臣下，难道是为了他的俸禄？应当保护国家。所以君主为国家而死，那么也就是为他而死，为国家而逃亡，那么也就是为他而逃亡。如果君主为自己而死，为自己而逃亡，不是他个人宠爱的人，谁敢承担这个责任？而且别人有了君主反而杀死了他，我哪能为他而死？哪里能为他而逃亡？但是又能回到哪里去呢？”开了大门，晏子进去，头枕在尸体的大腿上而号哭，起来，往上跳三次以后才出去。有人对崔武子说：“一定要杀了他！”崔武子说：“他是百姓所向往的人，放了他，可以得民心。”卢蒲癸逃亡到晋国，王何逃亡到莒国。
叔孙宣伯在齐国的时候，叔孙还把叔孙宣伯的女儿嫁给齐灵公，受到宠爱，生了齐景公。十九日，崔武子拥立景公为国君而自己出任宰相，庆封做左相，和国内的人们在太公的宗庙结盟，说：“有不依附崔氏、庆氏的—”晏子向天叹气说：“婴如果不依附忠君利国的人，有上帝为证！”于是就歃血。二十三日，齐景公和大夫以及莒子结盟。
太史记载说：“崔杼杀了他的国君。”崔武子杀死了太史。他的弟弟接着这样写，因而死了两人。太史还有一个弟弟又这样写，崔武子就没杀了。南史氏听说太史都死了，拿了照样写好了的竹简前去，听到已经如实记载了，这才回去。
闾丘婴用车子的帷幕包了妻子，装上车，和申鲜虞坐一辆车逃走。鲜虞把闾丘婴的妻子推下车，说：“国君昏昧不能纠正，国君危险不能救驾，国君死亡不能以身殉，只知道把自己所亲爱的人藏匿起来，有谁会接纳我们？”走到弇中狭道，准备住下来，闾丘婴说：“崔氏、庆氏可能在追我们。”鲜虞说：“一对一，谁能让我们害怕？”就住下来，头枕着马缰而睡，先喂饱马然后自己吃饭，套上马车继续赶路。走出弇中，对闾丘婴说：“快点赶马，崔氏、庆氏人多，是不能抵挡的。”于是就逃亡到鲁国来。
崔氏没有把齐庄公的棺材殡于庙就放在外城北边。二十九日，安葬在士孙之里，葬礼用四把长柄扇，不清道，不警戒，送葬的破车七辆，不用武器盔甲随葬。
晋平公渡过泮水，和鲁襄公、宋平公、卫殇公、郑简公、曹武公、莒子、邾于、滕子、薛伯、杞伯、小邾子在夷仪会合，进攻齐国，以报复朝歌这一战役。齐国人想用杀齐庄公这件事情向晋国解释，派隰锄请求讲和。庆封来到军中，男男女女分开排列、捆绑。齐国把宗庙里的祭器和乐器送给晋平公。从六卿、五吏、三个师的将领、各部门的首长、属官和留守的人都赠送财礼。晋平公答应了。派叔向告诉诸侯。襄公派子服惠伯回答说：“君王宽恕了有罪，以安定小国，这是君王的恩惠。寡君听到命令了。”
晋平公派魏舒、宛没迎接卫献公，准备让卫国把夷仪给卫献公居住。崔武子留下卫献公的妻子儿女，来谋求五鹿这块地方。
当初，陈哀公会合楚王进攻郑国，陈军经过的路上，水井被填，树木被砍，郑国人很怨恨。六月，郑国的子展、子产领着七百辆战车攻打陈国，夜里发动突然袭击，就进了城。陈哀公扶着他的太子偃师逃奔到坟地里，碰到司马桓子，说：“用车装上我！”司马桓子说：“我正打算巡城呢。”碰到贾获，车上装着他的母亲和妻了，贾获让他母亲、妻子下车而把车子交给陈哀公。陈哀公说：“安置好你的母亲。”贾获辞谢说：“妇女和你同坐，不吉祥。”贾获说完就和他妻子扶着他母亲逃奔到坟地里，也免于祸难。
子展命令军队不要进入陈哀公的宫室，和子产亲自守卫在宫门口，陈哀公让司马桓子把宗庙的祭器赠送给他们。陈哀公穿上丧服，抱着土地神的神主，让他手下的男男女女分开排列、捆绑，在朝廷上等待。子展拿着绳子进见陈哀公，再拜叩头，捧着酒杯向陈哀公献礼。子产进入，点了点俘虏的人数就出去了。郑国人向陈国的土地神祝告消灾去邪，司徒归还百姓，司马归还兵符，司空归还土地，于是就回国。
秋季，七月二十日，诸侯在重丘一起结盟，这是由于跟齐国讲和的缘故。
赵文子主持政事，命令减轻诸侯的贡品而着重礼仪。穆叔进见他。赵文子对穆叔说：“从今以后，战争恐怕可以稍稍停止了。齐国的崔氏、庆氏新近当政，将要向诸侯改善关系。武也了解楚国的令尹。如果恭敬地执行礼仪，用外交辞令和他说，用来安定诸侯，战争可以停止。”
楚国的薳子冯死了，屈建做令尹，屈荡做莫敖。舒鸠人终于肯叛楚国。屈建率兵进攻舒鸠，到达离城，吴国人救援舒鸠。屈建急忙让右翼部队先出动，子强、息桓、子捷、子骈、子盂率领左翼部队向后撤退。吴国人处在左右两军之间七天。子强说：“时间久了将会疲弱，疲弱就会被俘，不如赶快打仗。我请求带领家兵去引诱他们，你们选择精兵，摆开阵势等待我。我得胜就前进，我败逃就看情况办，这样就可以免于被俘。不这样，一定被吴国俘虏。”大家听从了他的话。五个人带领他们的家兵先攻吴军，吴军败逃，登山而远望，看到楚军没有后继，就再次追赶，迫近楚军。楚军精选部队就和家兵会合作战，吴军大败。楚军乘机就包围了舒鸠，舒鸠溃散。八月，楚国灭亡了舒鸠。
卫献公进入夷仪。
郑国的子产向晋国奉献战利品，穿着军服主持事务。晋国人质问陈国的罪过，子产回答说：“从前虞父做周朝的陶正，服事我们先王。我们先王嘉奖他能制作器物，于人有利，并且是虞舜的后代，就把大女儿太姬匹配给胡公，封他在陈地，以表示对黄帝、尧、舜的后代的诚敬。所以陈国是我周朝的后代，到今天还依靠着周朝。陈桓公死后发生动乱，蔡国人想要立他们的后代，我们先君庄公奉事五父而立了他，蔡国人杀死了五父。我们又和蔡国人奉事厉公，至于庄公、宣公，都是我们所立的。夏氏的祸乱杀死了灵公，成公流离失所，又是我们让他回国的，这是君王知道的。现在陈国忘记了周朝在的大德，丢弃我们的大恩，抛弃我们这个亲戚，倚仗楚国人多，以进逼我敝邑，但是并不能满足，我国因此而有去年请求攻打陈国的报告。没有得到贵国的命令，反却有了陈国进攻我国东门那次战役。在陈军经过的路上，水井被填塞，树木被砍伐。敝邑非常害怕敌兵压境，给太姬带来羞耻，上天诱导我们的心，启发了敝邑攻打陈国的念头。陈国知道自己的罪过，在我们这里得到惩罚。因此我们敢于奉献俘虏。”晋国人说：“为什么侵犯小国？”子产回答说：“先王的命令，只要是罪过所在，就要分别给刑罚。而且从前天子的土地方圆一千里，诸侯的土地方圆一百里，以此递减。现在大国的土地多到方圆几千里，如果没有侵占小国，怎么能到这地步呢？”晋国人说：“为什么穿上军服？”子产回答说：“我们先君武公、庄公做周平王、周桓王的卿士。城濮这一战役后，晋文公发布命令，说：‘各人恢复原来的职务。’命令我郑文公穿军服辅佐天子，以接受楚国俘虏献给天子，现在我穿着军服，这是由于不敢废弃天子命令的缘故。”士庄伯已经不能再质问，于是向赵文子回复。赵文子说：“他的言辞顺理成章，违背了情理不吉利。”于是就接受郑国奉献的战利品。
冬季，十月，子展作为郑简公的相礼一起去到晋国，拜谢晋国接受他们奉献的陈国战利品。子西再次发兵进攻陈国，陈国和郑同讲和。
孔子说：“古书上说：‘言语用来完成意愿，文采用来完成言语。’不说话，谁知道他的意愿是什么？说话没有文采，不能到达远方。晋国成为霸主，郑国进入陈国，不是善于辞令就不能成功。要谨慎地使用辞令。”
楚国的蒍掩做司马，子木让他治理军赋，检查盔甲武器。十月初八日，蒍掩记载土泽地田的情况：度量山林的木材，聚集水泽的出产，区别高地的情况，标出盐碱地，计算水淹地。规划蓄水池，划分小块耕地，在水草地上放牧，在肥沃的土地上划定井田。计量收入制定赋税制度，征收百姓交纳战车和马匹税、征收战车步卒所用的武器和盔甲盾牌税。完成以后，把它交付给子木，这是合于礼的。
十二月，吴王诸樊进攻楚国，为报复“舟师之战”。进攻巢地的城门。巢牛臣说：“吴王勇敢而轻率，如果我们打开城门，他将会亲自带头进门。我乘机射他，一定能射死。这个国君死了，边境上或可以稍为安定一些。”听从了他的意见。吴王进入城门，牛臣躲在短墙后用箭射他，吴王死了。
楚康王由于灭亡了舒鸠赏赐子木。子木推辞说：“这是先大夫蒍子的功劳。”楚康王就把赏赐给了蒍掩。
晋国的程郑死，子产才开始了解然明。子产向然明询问有关施政的方针。然明回答说：“把百姓看成像儿子一样。见到不仁的人，就诛戮他，好像老鹰追赶鸟雀。”子产很高兴，把这些话告诉子太叔，而且说：“以前我见到的只是然明的面貌，现在我了解到他内心甚有见识。” 子太叔向子产询问政事。子产说：“政事好像农活，白天黑夜想着它，要想着他的开始又想着要取得好结果。早晨晚上都照想着的去做，所做的不超过所想的，好像农田里有田埂一样，过错就会少一些。”
卫献公从夷仪派人向宁喜谈复国的事情，宁喜同意了。太叔文子听说了，说：“啊！《诗》所谓‘我的一身还不能被人容纳，哪里来得及顾念我的后代？”宁子可以说是不顾他的后代了。难道可以吗？大概是一定不可以的。君子有所行动，要想到结果，想到下次能够再如此。《书》说：‘慎重于开始，而重视其结果，结果就不会困惑。’《诗》说：‘早晚不敢懈怠，以事奉一人。’现在宁子看待国君不如下棋，他怎么能免于祸难呢？下棋的人举棋不定，就不能击败他的对方，而何况安置国君而不能决定呢？必定不能免于祸难了。九代相传的卿族，一旦被灭亡，可悲啊！”
在夷仪会见的那一年，齐国人在郏地筑城。那年五月，秦国、晋国讲和，晋国的韩起去到秦国参加结盟，秦国的伯车去到晋国参加结盟。虽然讲和但是并不巩固。 ', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8d7d0ac1145496bc5d", "shortContent": "本篇写河内太守崔君极其贪婪，任意搜刮人民，百姓敢怒不敢言。崔君又曾去佛寺中，拿取金子数镒，众僧也无可奈何。崔君死后，就变作佛寺中的一头牛犊，抵偿其生前之债。《河内崔守》所表现的这个内容，虽然不无因果轮回的迷信色彩，但其主旨却是要反映受剥削、受凌辱、受奴役的下层人民，对上层统治阶级的愤怒之情和复仇之心。\n俗话说：“善有善报，恶有恶报”；“今生不报来生报”；“死后也要当牛作马”。可见，在古人的思想意识...", "authors": ["王红箫"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559125908, '5cedef0f7b968a00767d3422', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643044, '左传 · 襄公 · 襄公二十六年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有六年春王二月辛卯，卫宁喜弑其君剽。卫孙林父入于戚以叛。甲午，卫侯衎复归于卫。夏，晋侯使荀吴来聘。公会晋人、郑良霄、宋人、曹人于澶渊。秋，宋公弑其世子痤。晋人执卫宁喜。八月壬午，许男宁卒于楚。冬，楚子、蔡侯、陈侯伐郑。葬许灵公。
【传】二十六年春，秦伯之弟金咸如晋修成，叔向命召行人子员。行人子朱曰：「朱也当御。」三云，叔向不应。子朱怒，曰：「班爵同，何以黜朱于朝？」抚剑从之。叔向曰：「秦、晋不和久矣！今日之事，幸而集，晋国赖之。不集，三军暴骨。子员道二国之言无私，子常易之。奸以事君者，吾所能御也。」拂衣从之。人救之。平公曰：「晋其庶乎！吾臣之所争者大。」师旷曰：「公室惧卑。臣不心竞而力争，不务德而争善，私欲已侈，能无卑乎？」
卫献公使子鲜为复，辞。敬姒强命之。对曰：「君无信，臣惧不免。」敬姒曰：「虽然，以吾故也。」许诺。初，献公使与宁喜言，宁喜曰：「必子鲜在，不然必败。」故公使子鲜。子鲜不获命于敬姒，以公命与宁喜言，曰：「苟反，政由宁氏，祭则寡人。」宁喜告蘧伯玉，伯玉曰：「瑗不得闻君之出，敢闻其入？」遂行，从近关出。告右宰谷，右宰谷曰：「不可。获罪于两君，天下谁畜之？」悼子曰：「吾受命于先人，不可以贰。」谷曰：「我请使焉而观之。」遂见公于夷仪。反曰：「君淹恤在外十二年矣，而无忧色，亦无宽言，犹夫人也。若不已，死无日矣。」悼子曰：「子鲜在。」右宰谷曰：「子鲜在，何益？多而能亡，于我何为？」悼子曰：「虽然，不可以已。」孙文子在戚，孙嘉聘于齐，孙襄居守。
二月庚寅，宁喜、右宰谷伐孙氏，不克。伯国伤。宁子出舍于郊。伯国死，孙氏夜哭。国人召宁子，宁子复攻孙氏，克之。辛卯，杀子叔及大子角。书曰：「宁喜弑其君剽。」言罪之在宁氏也。孙林父以戚如晋。书曰：「入于戚以叛。」罪孙氏也。臣之禄，君实有之。义则进，否则奉身而退，专禄以周旋，戮也。
甲午，卫侯入。书曰：「复归。」国纳之也。大夫逆于竟者，执其手而与之言。道逆者，自车揖之。逆于门者，颔之而已。公至，使让大叔文子曰：「寡人淹恤在外，二三子皆使寡人朝夕闻卫国之言，吾子独不在寡人。古人有言曰：『非所怨勿怨。』寡人怨矣。」对曰：「臣知罪矣！臣不佞不能负羁泄，以从手干牧圉，臣之罪一也。有出者，有居者。臣不能贰，通外内之言以事君，臣之罪二也。有二罪，敢忘其死？」乃行，从近关出。公使止之。
卫人侵戚东鄙，孙氏愬于晋，晋戍茅氏。殖绰伐茅氏，杀晋戍三百人。孙蒯追之，弗敢击。文子曰：「厉之不如！」遂从卫师，败之圉。雍锄获殖绰。复愬于晋。
郑伯赏入陈之功。三月甲寅朔，享子展，赐之先路，三命之服，先八邑。赐子产次路，再命之服，先六邑。子产辞邑，曰：「自上以下，隆杀以两，礼也。臣之位在四，且子展之功也。臣不敢及及赏礼，请辞邑。」公固予之，乃受三邑。公孙挥曰：「子产其将知政矣！让不失礼。」
晋人为孙氏故，召诸侯，将以讨卫也。夏，中行穆子来聘，召公也。
楚子、秦人侵吴，及雩娄，闻吴有备而还。遂侵郑，五月，至于城麇。郑皇颉戍之，出，与楚师战，败。穿封戌囚皇颉，公子围与之争之。正于伯州犁，伯州犁曰：「请问于囚。」乃立囚。伯州犁曰：「所争，君子也，其何不知？」上其手，曰：「夫子为王子围，寡君之贵介弟也。」下其手，曰：「此子为穿封戌，方城外之县尹也。谁获子？」囚曰：「颉遇王子，弱焉。」戌怒，抽戈逐王子围，弗及。楚人以皇颉归。
印堇父与皇颉戍城麇，楚人囚之，以献于秦。郑人取货于印氏以请之，子大叔为令正，以为请。子产曰：「不获。受楚之功而取货于郑，不可谓国，秦不其然。若曰：『拜君之勤郑国，微君之惠，楚师其犹在敝邑之城下。』其可。」弗从，遂行。秦人不予。更币，从子产而后获之。
六月，公会晋赵武、宋向戌、郑良霄、曹人于澶渊以讨卫，疆戚田。取卫西鄙懿氏六十以与孙氏。赵武不书，尊公也。向戌不书，后也。郑先宋，不失所也。于是卫侯会之。晋人执宁喜、北宫遗，使女齐以先归。卫侯如晋，晋人执而囚之于士弱氏。
秋七月，齐侯、郑伯为卫侯故，如晋，晋侯兼享之。晋侯赋《嘉乐》。国景子相齐侯，赋《蓼萧》。子展相郑伯，赋《缁衣》。叔向命晋侯拜二君曰：「寡君敢拜齐君之安我先君之宗祧也，敢拜郑君之不贰也。」国子使晏平仲私于叔向，曰：「晋君宣其明德于诸侯，恤其患而补其阙，正其违而治其烦，所以为盟主也。今为臣执君，若之何？」叔向告赵文子，文子以告晋侯。晋侯言卫侯之罪，使叔向告二君。国子赋《辔之柔矣》，子展赋《将仲子兮》，晋侯乃许归卫侯。叔向曰：「郑七穆，罕氏其后亡者也。子展俭而壹。」
初，宋芮司徒生女子，赤而毛，弃诸堤下，共姬之妾取以入，名之曰弃。长而美。平公入夕，共姬与之食。公见弃也，而视之，尤。姬纳诸御，嬖，生佐。恶而婉。大子痤美而很，合左师畏而恶之。寺人惠墙伊戾为大子内师而无宠。
秋，楚客聘于晋，过宋。大子知之，请野享之。公使往，伊戾请从之。公曰：「夫不恶女乎？」对曰：「小人之事君子也，恶之不敢远，好之不敢近。敬以待命，敢有贰心乎？纵有共其外，莫共其内，臣请往也。」遣之。至，则□欠，用牲，加书，征之，而聘告公曰：「大子将为乱，既与楚客盟矣。」公曰：「为我子，又何求？」对曰：「欲速。」公使视之，则信有焉。问诸夫人与左师，则皆曰：「固闻之。」公囚大子。大子曰：「唯佐也能免我。」召而使请，曰：「日中不来，吾知死矣。」左师闻之，聒而与之语。过期，乃缢而死。佐为大子。公徐闻其无罪也，乃亨伊戾。
左师见夫人之步马者，问之，对曰：「君夫人氏也。」左师曰：「谁为君夫人？余胡弗知？」圉人归，以告夫人。夫人使馈之锦与马，先之以玉，曰：「君之妾弃使某献。」左师改命曰：「君夫人。」而后再拜稽首受之。
郑伯归自晋，使子西如晋聘，辞曰：「寡君来烦执事，惧不免于戾，使夏谢不敏。」君子曰：「善事大国。」
初，楚伍参与蔡太师子朝友，其子伍举与声子相善也。伍举娶于王子牟，王子牟为申公而亡，楚人曰：「伍举实送之。」伍举奔郑，将遂奔晋。声子将如晋，遇之于郑郊，班荆相与食，而言复故。声子曰：「子行也！吾必复子。」及宋向戌将平晋、楚，声子通使于晋。还如楚，令尹子木与之语，问晋故焉，且曰：「晋大夫与楚孰贤？」对曰：「晋卿不如楚，其大夫则贤，皆卿材也。如杞、梓、皮革，自楚往也。虽楚有材，晋实用之。」子木曰：「夫独无族姻乎？」对曰：「虽有，而用楚材实多。归生闻之：『善为国者，赏不僭而刑不滥。』赏僭，则惧及淫人；刑滥，则惧及善人。若不幸而过，宁僭无滥。与其失善，宁其利淫。无善人，则国从之。《诗》曰：『人之云亡，邦国殄瘁。』无善人之谓也。故《夏书》曰：『与其杀不幸，宁失不经。』惧失善也。《商颂》有之曰：『不僭不滥，不敢怠皇，命于下国，封建厥福。』此汤所以获天福也。古之治民者，劝赏而畏刑，恤民不倦。赏以春夏，刑以秋冬。是以将赏，为之加膳，加膳则饫赐，此以知其劝赏也。将刑，为之不举，不举则彻乐，此以知其畏刑也。夙兴夜寐，朝夕临政，此以知其恤民也。三者，礼之大节也。有礼无败。今楚多淫刑，其大夫逃死于四方，而为之谋主，以害楚国，不可救疗，所谓不能也。子仪之乱，析公奔晋。晋人置诸戎车之殿，以为谋主。绕角之役，晋将遁矣，析公曰：『楚师轻窕，易震荡也。若多鼓钧声，以夜军之，楚师必遁。』晋人从之，楚师宵溃。晋遂侵蔡，袭沈，获其君；败申、息之师于桑隧，获申丽而还。郑于是不敢南面。楚失华夏，则析公之为也。雍子之父兄谮雍子，君与大夫不善是也。雍子奔晋。晋人与之鄐，以为谋主。彭城之役，晋、楚遇于靡角之谷。晋将遁矣。雍子发命于军曰：『归老幼，反孤疾，二人役，归一人，简兵搜乘，秣马蓐食，师陈焚次，明日将战。』行归者而逸楚囚，楚师宵溃。晋绛彭城而归诸宋，以鱼石归。楚失东夷，子辛死之，则雍子之为也。子反与子灵争夏姬，而雍害其事，子灵奔晋。晋人与之邢，以为谋主。扞御北狄，通吴于晋，教吴判楚，教之乘车、射御、驱侵，使其子孤庸为吴行人焉。吴于是伐巢、取驾、克棘、入州来，楚罢于奔命，至今为患，则子灵之为也。若敖之乱，伯贲之子贲皇奔晋。晋人与之苗，以为谋主。鄢陵之役，楚晨压晋军而陈，晋将遁矣。苗贲皇曰：『楚师之良，在其中军王族而已。若塞井夷灶，成陈以当之，栾、范易行以诱之，中行、二郤必克二穆。吾乃四萃于其王族，必大败之。』晋人从之，楚师大败，王夷师熠，子反死之。郑叛吴兴，楚失诸侯，则苗贲皇之为也。」子木曰：「是皆然矣。」声子曰：「今又有甚于此。椒举娶于申公子牟，子牟得戾而亡，君大夫谓椒举：『女实遣之！』惧而奔郑，引领南望曰：『庶几赦余！』亦弗图也。今在晋矣。晋人将与之县，以比叔向。彼若谋害楚国，岂不为患？」子木惧，言诸王，益其禄爵而复之。声子使椒鸣逆之。
许灵公如楚，请伐郑，曰：「师不兴，孤不归矣！」八月，卒于楚。楚子曰：「不伐郑，何以求诸侯？」冬十月，楚子伐郑。郑人将御之，子产曰：「晋、楚将平，诸侯将和，楚王是故昧于一来。不如使逞而归，乃易成也。夫小人之性，衅于勇，啬于祸，以足其性而求名焉者，非国家之利也。若何从之？」子展说，不御寇。十二月乙酉，入南里，堕其城。涉于乐氏，门于师之梁。县门发，获九人焉。涉入汜而归，而后葬许灵公。
卫人归卫姬于晋，乃释卫侯。君子是以知平公之失政也。
晋韩宣子聘于周。王使请事。对曰：「晋士起将归时事于宰旅，无他事矣。」王闻之曰：「韩氏其昌阜于晋乎！辞不失旧。」
齐人城郏之岁，其夏，齐乌余以廪丘奔晋，袭卫羊角，取之；遂袭我高鱼。有大雨，自其窦入，介于其库，以登其城，克而取之。又取邑于宋。于是范宣子卒，诸侯弗能治也，及赵文子为政，乃卒治之。文子言于晋侯曰：「晋为盟主。诸侯或相侵也，则讨而使归其地。今乌余之邑，皆讨类也，而贪之，是无以为盟主也。请归之！」公曰：「诺。孰可使也？」对曰：「胥梁带能无用师。」晋侯使往。', '', '', '二十六年春季，秦景公的弟弟鍼去到晋国重温盟约，叔向命令召唤行人子员。行人子朱说：“朱是值班的。”说了三次，叔向不答理。子朱生气，说：“职位级别相同，为什么在朝廷上不用朱？”拿着剑跟上去。叔向说：“秦国和晋国不和睦已经很久了。今天的事情，幸而成功，晋国依靠着它。不成功，就要打仗。子员沟通两国的话没有私心，您却常常违背原意。用邪恶来事奉国君的人，我是能够抵抗的。”提起衣服跟上去，被别人止住了。晋平公说：“晋国差不多要大治了吧！我的臣下所争执的是大问题。”师旷说：“公室的地位怕要下降。臣下不在心里竞争而用力量来争夺，不致力于德行而争执是非，个人的欲望太大，公室的地位能不下降吗？”
卫献公派子鲜为自己谋求再登君位，子鲜辞谢。他们的母亲敬姒一定要子鲜去，子鲜回答说：“国君没有信用，下臣害怕不能免于祸难。”敬姒说：“尽管这样，为了我的缘故，你还是去干吧！”子鲜答应了。当初，献公派人和宁喜谈这件事，宁喜说：“一定要子鲜在场。不这样，事情必然失败。”所以献公派遣，子鲜。子鲜没有得到敬姒的指示，就把献公的命令告诉宁氏，说：“如果回国，政权由宁氏主持，祭祀则由我主持。”宁喜告诉蘧伯玉。蘧伯玉说：“瑷没有能听到国君的出走，岂敢听到他的进入？”于是蘧伯玉就起程，从近处的城门出走。宁喜告诉右宰穀。右宰穀说：“不行。得罪了两个国君，天下谁能收容你？”宁喜说：“我在先人那里接受了命令，不能三心二意。”右宰穀说：“我请求出使去观望一下。”于是就在夷仪进见献公。回来，说：“国君逗留在外已十二年了，却没有忧愁的样子，也没有宽容的话，还是那样一个人。如果不停止原复君计划，我们离死就没有几天了。”宁喜说：“有子鲜在那里。”右宰穀说：“子鲜在那里，有什么用处？至多不过他自己逃亡，又能为我们做些什么呢？”宁喜说：“尽管这样，不能停止了。孙文子在戚地，孙嘉去齐国聘问，孙襄留守在都城家里。
二月初六日，宁喜、右宰穀进攻孙氏，没有取胜。孙襄受伤。宁喜退出城住在郊外。孙襄死了，孙家的人在夜里号哭。城里的人们召唤宁喜，宁喜再次攻打孙氏，攻克了。初七日，杀死了卫侯剽和太子角。《春秋》记载说：“宁喜弑其君剽”，这是说罪过在宁氏。孙林父以戚邑去投靠晋国。《春秋》记载说“入于戚以叛”，这是归罪于孙氏。臣下的俸禄，实在是为国君所有的。合于道义就往前进，不合于道义就保全身子引退。把俸禄作为私有，并以此和人打交道，应该受到诛戮。
初十日，卫献公进入都城，《春秋》记载说“复归”，这表示本国人让他回来。大夫在国境上迎接的，卫献公拉着他们的手跟他们说话；在大路上迎接的，卫献公从车上向他们作揖；在城门口迎接的，卫献公点点头而已。卫献公一到达，就派人责备太叔文子说：“寡人流亡在外边，几位大夫都使寡人早早晚晚听到卫国的消息，大夫独独不问候寡人。古人有话说：‘不是应该怨恨的，不要怨恨。’寡人可要怨恨了。”太叔文子回答说：“下臣知道罪过了。下臣没有才能，不能背着马笼头马缰绳跟随君王保护财物，这是下臣的第一条罪状。有人在国外，有人在国内，下臣不能三心二意，传递里外的消息来事奉君王，这是下臣的第二条罪状。有两条罪状，岂敢忘记一死？”于是就出走，从近处的城门出国。卫献公派人阻止了他。
卫国侵袭戚地的东部边境，孙氏向晋国控告，晋国派兵戍守茅氏，殖绰进攻茅氏杀了晋国守兵三百个人。孙蒯追赶殖绰，不敢攻击。孙文子说：“你连恶鬼都不如。”孙蒯就跟上卫军，在圉地打败了他们。雍锄俘虏了殖绰。孙氏再次向晋国控告。
郑简公赏赐攻入陈国有功劳的人。三月初一日，设享礼招待子展，赐给他先路和三命车服，然后再赐给他八个城邑。赐给子产次路和再命车服，然后再赐给他六个城邑。子产辞去城邑，说：“从上而下，礼数以二的数目递降，这是规定。下臣的地位在第四，而且这是子展的功劳，下臣不敢受到赏赐的礼仪，请求辞去城邑。”郑简公坚决要给他，他就接受了三个城邑。公孙挥说：“子产恐怕将要主持政事了。谦让而不失去礼仪。”
晋国人为了孙氏的缘故，召集诸侯，准备讨伐卫国。夏季，中行穆子来鲁国聘问，这是为了召请鲁襄公。
楚康王、秦国人联兵侵袭吴国，到达雩娄，听到吴国有了准备而退回，就乘机入侵郑国。五月，到达城虞。郑国的皇颉在城糜戍守，出城，和楚军作战，战败。穿封戌俘虏了皇颉，公子围和他争功，要伯州犁主持公正。伯州犁说：“请问一下俘虏。”于是就让俘虏站在前面。伯州犁悦：“所争夺的对象便是您，您是君子，有什么不明白的？”举起手，说：“那一位是王子围，是寡君的尊贵的弟弟。”放下手，说：“这个人是穿封戌，是方城山外边的县尹。谁俘虏您了？”俘虏说：“颉碰上王子，抵抗不住，”穿封戌发怒，抽出戈追赶王子围，没有追上。楚国人带着皇颉回去。
印堇父和皇颉一起留守在城麇，楚国人囚禁印堇父，把他献给秦国。郑国人在印氏那里拿了财货向秦国请求赎回印堇父，子太叔正做令正，为他们提出请求赎回的话。子产说：“这样是不能得到印堇父的。秦国接受了楚国奉献的俘虏，却在郑国拿财物，不能说合于国家的体统，秦国不会这样做的。如果说‘拜谢君王帮助郑国。如果没有君王的恩惠，楚军恐怕还在敝邑城下’，这才可以。”子太叔不听，就动身了。秦国人不给，把财物改为其他礼品，按照子产的话去说，然后得到了印堇父。
六月，鲁襄公和晋国赵武、宋国向戌、郑国良霄、曹国人在澶渊会见，以讨伐卫国，划正戚地的疆界。占领了卫国西部边境懿氏六十邑给了孙氏。《春秋》对赵武不加记载，这是由于尊重鲁襄公。对向戌不加记载，这是由于他到迟了。记载郑国在宋国之前，是由于郑国人如期到达。当时卫献公参加了会见。晋国人拘捕了宁喜、北宫遗，让女齐带了他们先回去。卫献公去到晋国，晋国人抓了他关闭在士弱家里。
秋季，七月，齐景公、郑简公为了卫献公的缘故去到晋国，晋平公同时设享礼招待他们。晋平公赋《嘉乐》这首诗。国景子做齐景公的相礼者，赋《蓼萧》这首诗。子展做郑简公的相礼者，赋《缁衣》这首诗。叔向要晋平公向两位国君下拜，说：“寡君谨敢拜谢齐国国君安定我国先君的宗庙，谨敢拜谢郑国国君没有二心。”国景子派晏平仲私下对叔向说：“晋国国君在诸侯之中宣扬他的明德，担心他们的忧患而补正他们的过失，纠正他们的违礼，而治理他们的动乱，因此才能作为盟主。现在为了臣下而逮了国君，怎么办？”叔向告诉赵文子，赵文子把这些话告诉晋平公。晋平公举出卫献公的罪过，派叔向告诉齐、郑二国国君。国景子赋《辔之柔矣》这首诗，子展赋《将仲子兮》这首诗，晋平公于是就允许让卫献公回国。叔向说：“郑穆公的后代七个家族，罕氏大概是最后灭亡的，因为子展节俭而用心专一。”
当初，宋国的芮司徒生了女儿，皮肤红而且长着毛，就把她丢在堤下。共姬的侍妾把她拣进宫来，命名叫做弃。长大了很漂亮。宋平公向共姬问候晚安，共姬让他吃东西。平公见了弃，细看，觉得漂亮极了。共姬就把她送给平公做侍妾，受到宠爱，生了佐。佐长得难看，但性情和顺。太子痤长得漂亮，但心里狠毒，向戌对他又害怕又讨厌。寺人惠墙伊戾做太子的内师而不受宠信。
秋季，楚国的客人到晋国聘问，经过宋国。太子和楚国的客人原来相识，请求在野外设宴招待他，平公让他去了。伊戾请求跟从太子。平公说：“他不讨厌你吗？”伊戾回答说：“小人事奉君子，被讨厌不敢远离，被喜欢不敢亲近，恭敬地等待命令，岂敢有三心二意呢？太子那里即使有人在外边服务，却没有人在里边服务，下臣请求前去。”平公就派他去了。到那里，就挖坑，用牺牲，把盟书放在牲口上，并且检查一遍，驰马回来报告平公，说“太子将要作乱，已经和楚国的客人结盟了。”宋平公说：“已经是我的继承人了，还谋求什么？”伊戾回答说：“想快点即位。”平公派人去视察，果然有这回事。向夫人和左师询问，他们都说：“的确听到过。”宋平公囚禁了太子。太子说：“只有佐能够使我免于祸难。”召请佐并让他向平公请求，说：“到中午还不来，我知道应该死了。”左师向戌听到了，就和佐说个不停。过了中午，太子就上吊死了。佐被立为太子。宋平公慢慢地听到痤没有罪，就把伊戾烹杀了。
左师见到夫人的溜马人，就问他是什么人。溜马人说：“我是君夫人家的人。”左师说：“谁是君夫人？我为什么不知道？”溜马的人回去，把这话报告夫人。夫人派人送给左师锦和马，先送去玉，说“国君的侍妾弃让我送给您的。”左师改换口气说：“君夫人”，然后再拜叩头接受了。
郑简公从晋国回来，派子西去到晋国聘问，致辞说：“寡君来麻烦执事，害怕不敬而不免于有罪，特派夏前来表示歉意。”君子说：“郑国善于事奉大国。”
当初，楚国的伍参和蔡国的太师子朝友好，他的儿子伍举和声子也互相友好。伍举娶了王子牟的女儿。王子牟为申公而逃亡，楚国人说：“伍举确实护送了他。”伍举逃亡到郑国，准备乘机再到晋国。声子打算去到晋国，在郑国郊外碰到了他，把草铺在地上一起吃东西，谈到回楚国去的事，声子说：“您走吧，我一定让您回去。”等到宋国的向戌准备调解晋国和楚国的关系，声子出使到晋国，回到楚国，令尹子木和他谈话，询问晋国的情况，而且说：“晋国的大夫和楚国的大夫谁更贤明？”声子回答说：“晋国的卿不如楚国，晋国的大夫是贤明的，都是当卿的人材。好像杞木、梓木、皮革，都是楚国运去的。虽然楚国有人才，晋国却实在使用了他们。”子木说：“他们没有同宗和亲戚吗？”声子回答说：
“虽然有，但使用楚国的人材确实多。归生听说：善于为国家做事的，赏赐不过分，而刑罚不滥用。赏赐过分，就怕及于坏人；刑罚滥用，就怕牵涉好人。如果不幸而过分了，宁可过分，不要滥用。与其失掉好人，宁可利于坏人。没有好人，国家就跟着受害。《诗》说，‘这个能人不在，国家就遭受灾害’，这就是说没有好人。所以《夏书》说：‘与其杀害无辜的人，宁可对罪人失于刑罚’，这就是怕失掉好人。《商颂》有这样的话说，‘不过分不滥用，不敢懈怠偷闲，向下国发布命令，大大地建立他的福禄’。这就是汤所以获得上天赐福的原因。古代治理百姓的人，乐于赏赐而怕用刑罚，为百姓担扰而不知疲倦。在春天、夏天行赏，在秋季、冬季行刑。因此，在将要行赏的时候就为它增加膳食，加膳以后可以把剩菜大批赐给下面，由于这样而知道他乐于赏赐。将要行刑的时候就为它减少膳食，减了膳食就撤去音乐，由于这样而知道他怕用刑罚。早起晚睡，早晚都亲临办理国事，由于这样而知道他为百姓操心。这三件事，是礼仪的大关键。讲求礼仪就不会失败。现在楚国滥用刑罚，楚国的大夫逃命到四方的国家，并且做别国的主要谋士，来危害楚国，至于不可救药了，这就是说的滥用刑罚不能容忍。子仪的叛乱，析公逃亡到晋国，晋国人把他安置在晋侯战车的后面，让他作为主要谋士。绕角那次战役，晋国人将要逃走，析公说：‘楚军不厚重，容易被震动。如果同时敲打许多鼓发出大声，在夜里全军进攻，楚军必然会逃走。’晋国人听从了，楚军夜里崩溃。晋国于是就侵入蔡国，袭击沈国，俘虏了沈国的国君，在桑隧打败申国和息国军队，俘虏了申丽而回国。郑国在那时候不敢向着南方的楚国。楚国丧失了中原，这就是析公干出来的。
“雍子的父亲的哥哥诬陷雍子，国君和大夫不为他们去调解，雍子逃亡到晋国，晋国人将鄐地给了他，让他作为主要谋士。彭城那次战役，晋国、楚国在靡角之谷相遇。晋国人将要逃走了，雍子对军队发布命令说：‘年纪老的和年纪小的都回去，孤儿和有病的也都回去，兄弟两个服役的回去一个。精选徒兵，检阅车兵，喂饱马匹，让兵士吃饱，军队摆开阵势，焚烧帐篷，明天将要决战。’让该回去的走开，并且故意放走楚国俘虏，楚军夜里崩溃。晋国降服了彭城而归还给宋国，带了鱼石回国。楚国失去东夷，子辛为此战而阵亡，这都是雍子所谋划的。
“子反和子灵争夺夏姬而阻碍子灵的婚事，子灵逃亡到晋国，晋国人将邢地给了他，让他作为谋士，抵御北狄，让吴国和晋国通好，教吴国背叛楚国，教他们坐车、射箭、驾车作战，让他的儿子狐庸做了吴国的行人。吴国在那时候时进攻巢地、占取驾地、攻下棘地、进入州来，楚国疲于奔命，到今天还是祸患，这就是子灵干出来的。若敖的叛乱，伯贲的儿子贲皇逃亡到晋国，晋国人封给他苗地，让他作为主要谋士。鄢陵那次战役，楚军早晨逼近晋军并摆开阵势，晋国人就要逃走了。苗贲皇说：‘楚军的精锐在于他们中军的王族而已，如果填井平灶，摆开阵势以抵挡他们，栾、范用家兵引诱楚军，中行和郤锜、郤至一定能够战胜子重、子辛。我们就用四军集中对付他们的王族，一定能够把他们打得大败。’晋国人听从了，楚军大败，君王受伤，军队士气不振，子反为此而死。郑国背叛，吴国兴起，楚国失去诸侯，这就是苗贲皇干出来的。”
子木说：“阁下所说的都是那样的。”声子说：“现在又有比这厉害的。椒举娶了申公子牟的女儿，子牟得罪而逃亡。国君和大夫对椒举说：‘实在是你让他走的。’椒举害怕而逃亡到郑国，伸长了脖子望着南方，说：‘也许可以赦免我。’但是我们也不存希望。现在他在晋国了。晋国人将要把县封给他，以和叔向并列。他如果要危害楚国，难道不是祸患？”子木听了这些很恐惧，对楚康王说了，楚康王提高了椒举的官禄爵位而让他官复原职。声子让椒鸣去迎接椒举。
许灵公去到楚国，请求进攻郑国，说：“不发兵，我就不回去了。”八月，许灵公死在楚国。楚康王说：“不攻打郑国，怎么能求得诸侯？”
冬季，十月，楚康王攻打郑国，郑国人准备抵御。子产说：“晋国将要和楚国讲和，诸侯将要和睦，楚康王因此冒昧来这一趟。不如让他称心回去，就容易讲和了。小人的本性，一有空子就凭血气之勇，在祸乱中有所贪图，以满足他的本性而追求虚名，这不符合国家的利益，怎么可以听从？”子展高兴了，就不抵御敌人，十二月初五日，楚军进入南里，拆毁城墙。从乐氏渡过洧水，进攻师之梁的城门。放下内城的闸门，俘虏了九个不能进城的郑国人。楚国人渡过汜水回国，然后安葬许灵公。
卫国人把卫姬送给晋国，晋国这才释放了卫献公。君子因此而知道晋平公失去了治国的常道。
晋国的韩宣子在成周聘问，周灵王派人请问明来意。韩宣子回答说：“晋国的士起前来向宰旅奉献贡品，没有别的事情。”周天子听到了，说：“韩氏恐怕要在晋国昌盛了吧！他的辞令仍和过去一样。”
齐国人在郏地筑城的那一年，夏季，齐国的乌馀带着廪丘逃亡到晋国，袭击卫国的羊角，占取了这地方，就乘机侵袭我国的高鱼。正逢下大雨，齐军从城墙的排水孔进入城中，走到城里的武器库，取出了甲胄装备士兵，然后登上城墙，攻克并占领了高鱼。又占取了宋国的城邑。当时范宣子已经死了，诸侯不能惩治乌馀。等到赵文子执政以后，才终于把他惩治了。赵文子对晋平公说：“晋国作为盟主，诸侯有人互相侵犯，就要讨伐他。让他归还侵夺的土地。现在乌馀的城邑，都是侵夺来的，属于应该讨伐之列，而我们贪图它，这就没有资格作盟主了。请归还给诸侯。”晋平公说：“好。谁可以做使者？”赵文子回答说：“胥梁带能够不用兵而完成任务。”晋平公就派胥梁带前去。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed202dbb8b379ee0a14f1", "shortContent": "《尊卢沙》为宋濂的《燕书四十首》之一。\n《燕书四十首》为杂著文字，共四十篇，所述故事均以春秋战国为历史背景，但其中的人物、情节于《左传》、《国语》、《国策》往往并无根据，有的人物虽有据，情节却出于想象。题名《燕书》，作者自云“盖取郑人误书‘举烛’之义”，表明所述全属无稽，是借虚构的春秋战国故事表述自己对政治、社会、人生问题的某种见解，有一定的“寓言”意味，与同时代刘基的《郁离子》有相似之处。\n本篇...", "authors": ["胡光舟"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559125955, '5cedef3ea673f500682d652c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643045, '左传 · 襄公 · 襄公二十七年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有七春，齐侯使庆封聘。夏，叔孙豹会晋赵武、楚屈建、蔡公孙归生、卫石恶、陈孔奂、郑良霄、许人、曹人于宋。卫杀其大夫宁喜。卫侯之弟鱄出奔晋。秋七月辛巳，豹及诸侯之大夫盟于宋。冬十有二月乙卯朔，日有食之。
【传】二十七年春，胥梁带使诸丧邑者具车徒以受地，必周。使乌余车徒以受封，乌余以众出。使诸侯伪效乌余之封者，而遂执之，尽获之。皆取其邑而归诸侯，诸侯是以睦于晋。
齐庆封来聘，其车美。孟孙谓叔孙曰：「庆季之车，不亦美乎？」叔孙曰：「豹闻之：『服美不称，必以恶终。』美车何为？」叔孙与庆封食，不敬。为赋《相鼠》，亦不知也。卫宁喜专，公患之。公孙免余请杀之。公曰：「微宁子不及此，吾与之言矣。事未可知，只成恶名，止也。」对曰：「臣杀之，君勿与知。」乃与公孙无地、公孙臣谋，使攻宁氏。弗克，皆死。公曰：「臣也无罪，父子死余矣！」夏，免余复攻宁氏，杀宁喜及右宰谷，尸诸朝。石恶将会宋之盟，受命而出。衣其尸，枕之股而哭之。欲敛以亡，惧不免，且曰：「受命矣。」乃行。
子鲜曰：「逐我者出，纳我者死，赏罚无章，何以沮劝？君失其信，而国无刑。不亦难乎！且鱄实使之。」遂出奔晋。公使止之，不可。及河，又使止之。止使者而盟于河，托于木门，不乡卫国而坐。木门大夫劝之仕，不可，曰：「仕而废其事，罪也。从之，昭吾所以出也。将准愬乎？吾不可以立于人之朝矣。」终身不仕。公丧之，如税服，终身。
公与免余邑六十，辞曰：「唯卿备百邑，臣六十矣。下有上禄，乱也，臣弗敢闻。且宁子唯多邑，故死。臣惧死之速及也。」公固与之，受其半。以为少师。公使为卿，辞曰：「大叔仪不贰，能赞大事。君其命之！」乃使文子为卿。
宋向戌善于赵文子，又善于令尹子木，欲弭诸侯之兵以为名。如晋，告赵孟。赵孟谋于诸大夫，韩宣子曰：「兵，民之残也，财用之蠹，小国之大灾也。将或弭之，虽曰不可，必将许之。弗许，楚将许之，以召诸侯，则我失为盟主矣。」晋人许之。如楚，楚亦许之。如齐，齐人难之。陈文子曰：「晋、楚许之，我焉得已。且人曰弭兵，而我弗许，则固携吾民矣！将焉用之？」齐人许之。告于秦，秦亦许之。皆告于小国，为会于宋。
五月甲辰，晋赵武至于宋。丙午，郑良霄至。六月丁未朔，宋人享赵文子，叔向为介。司马置折俎，礼也。仲尼使举是礼也，以为多文辞。戊申，叔孙豹、齐庆封、陈须无、卫石恶至。甲寅，晋荀盈从赵武至。丙辰，邾悼公至。壬戌，楚公子黑肱先至，成言于晋。丁卯，宋戌如陈，从子木成言于楚。戊辰，滕成公至。子木谓向戌：「请晋、楚之从交相见也。」庚午，向戌复于赵孟。赵孟曰：「晋、楚、齐、秦，匹也。晋之不能于齐，犹楚之不能于秦也。楚君若能使秦君辱于敝邑，寡君敢不固请于齐？」壬申，左师复言于子木。子木使馹谒诸王，王曰：「释齐、秦，他国请相见也。」秋七月戊寅，左师至。是夜也，赵孟及子皙盟，以齐言。庚辰，子木至自陈。陈孔奂、蔡公孙归生至。曹、许之大夫皆至。以藩为军，晋、楚各处其偏。伯夙谓赵孟曰：「楚氛甚恶，惧难。」赵孟曰：「吾左还，入于宋，若我何？」
辛巳，将盟于宋西门之外，楚人衷甲。伯州犁曰：「合诸侯之师，以为不信，无乃不可乎？夫诸侯望信于楚，是以来服。若不信，是弃其所以服诸侯也。」固请释甲。子木曰：「晋、楚无信久矣，事利而已。苟得志焉，焉用有信？」大宰退，告人曰：「令尹将死矣，不及三年。求逞志而弃信，志将逞乎？志以发言，言以出信，信以立志，参以定之。信亡，何以及三？」赵孟患楚衷甲，以告叔向。叔向曰：「何害也？匹夫一为不信，犹不可，单毙其死。若合诸侯之卿，以为不信，必不捷矣。食言者不病，非子之患也。夫以信召人，而以僭济之。必莫之与也，安能害我？且吾因宋以守病，则夫能致死，与宋致死，虽倍楚可也。子何惧焉？又不及是。曰弭兵以召诸侯，而称兵以害我，吾庸多矣，非所患也。」
季武子使谓叔孙以公命，曰：「视邾、滕。」既而齐人请邾，宋人请滕，皆不与盟。叔孙曰：「邾、滕，人之私也；我，列国也，何故视之？宋、卫，吾匹也。」乃盟。故不书其族，言违命也。
晋、楚争先。晋人曰：「晋固为诸侯盟主，未有先晋者也。」楚人曰：「子言晋、楚匹也，若晋常先，是楚弱也。且晋、楚狎主诸侯之盟也久矣！岂专在晋？」叔向谓赵孟曰：「诸侯归晋之德只，非归其尸盟也。子务德，无争先！且诸侯盟，小国固必有尸盟者。楚为晋细，不亦可乎？」乃先楚人。书先晋，晋有信也。
壬午，宋公兼享晋、楚之大夫，赵孟为客。子木与之言，弗能对。使叔向侍言焉，子木亦不能对也。
乙酉，宋公及诸侯之大夫盟于蒙门之外。子木问于赵孟曰：「范武子之德何如？」对曰：「夫人之家事治，言于晋国无隐情。其祝史陈信于鬼神，无愧辞。」子木归，以语王。王曰：「尚矣哉！能歆神人，宜其光辅五君以为盟主也。」子木又语王曰：「宜晋之伯也！有叔向以佐其卿，楚无以当之，不可与争。」晋荀寅遂如楚莅盟。
郑伯享赵孟于垂陇，子展、伯有、子西、子产、子大叔、二子石从。赵孟曰：「七子从君，以宠武也。请皆赋以卒君贶，武亦以观七子之志。」子展赋《草虫》，赵孟曰：「善哉！民之主也。抑武也不足以当之。」伯有赋《鹑之贲贲》，赵孟曰：「床第之言不逾阈，况在野乎？非使人之所得闻也。」子西赋《黍苗》之四章，赵孟曰：「寡君在，武何能焉？」子产赋《隰桑》，赵孟曰：「武请受其卒章。」子大叔赋《野有蔓草》，赵孟曰：「吾子之惠也。」印段赋《蟋蟀》，赵孟曰：「善哉！保家之主也，吾有望矣！」公孙段赋《桑扈》，赵孟曰：「『匪交匪敖』，福将焉往？若保是言也，欲辞福禄，得乎？」卒享。文子告叔向曰：「伯有将为戮矣！诗以言志，志诬其上，而公怨之，以为宾荣，其能久乎？幸而后亡。」叔向曰：「然。已侈！所谓不及五稔者，夫子之谓矣。」文子曰：「其馀皆数世之主也。子展其后亡者也，在上不忘降。印氏其次也，乐而不荒。乐以安民，不淫以使之，后亡，不亦可乎？」
宋左师请赏，曰：「请免死之邑。」公与之邑六十。以示子罕，子罕曰：「凡诸侯小国，晋、楚所以兵威之。畏而后上下慈和，慈和而后能安靖其国家，以事大国，所以存也。无威则骄，骄则乱生，乱生必灭，所以亡也。天生五材，民并用之，废一不可，谁能去兵？兵之设久矣，所以威不轨而昭文德也。圣人以兴，乱人以废，废兴存亡昏明之术，皆兵之由也。而子求去之，不亦诬乎？以诬道蔽诸侯，罪莫大焉。纵无大讨，而又求赏，无厌之甚也！」削而投之。左师辞邑。向氏欲攻司城，左师曰：「我将亡，夫子存我，德莫大焉，又可攻乎？」君子曰：「『彼己之子，邦之司直。』乐喜之谓乎？『何以恤我，我其收之。』向戌之谓乎？」
齐崔杼生成及强而寡。娶东郭姜，生明。东郭姜以孤入，曰棠无咎，与东郭偃相崔氏。崔成有病，而废之，而立明。成请老于崔，崔子许之。偃与无咎弗予，曰：「崔，宗邑也，必在宗主。」成与强怒，将杀之。告庆封曰：「夫子之身亦子所知也，唯无咎与偃是从，父兄莫得进矣。大恐害夫子，敢以告。」庆封曰：「子姑退，吾图之。」告卢蒲弊。卢蒲弊曰：「彼，君之仇也。天或者将弃彼矣。彼实家乱，子何病焉！崔之薄，庆之厚也。」他日又告。庆封曰：「苟利夫子，必去之！难，吾助女。」
九月庚辰，崔成、崔强杀东郭偃、棠无咎于崔氏之朝。崔子怒而出，其众皆逃，求人使驾，不得。使圉人驾，寺人御而出。且曰：「崔氏有福，止余犹可。」遂见庆封。庆封曰：「崔、庆一也。是何敢然？请为子讨之。」使卢蒲弊帅甲以攻崔氏。崔氏堞其宫而守之，弗克。使国人助之，遂灭崔氏，杀成与强，而尽俘其家。其妻缢。弊覆命于崔子，且御而归之。至，则无归矣，乃缢。崔明夜辟诸大墓。辛巳，崔明来奔，庆封当国。
楚薳罢如晋莅盟，晋将享之。将出，赋《既醉》。叔向曰：「薳氏之有后于楚国也，宜哉！承君命，不忘敏。子荡将知政矣。敏以事君，必能养民。政其焉往？」
崔氏之乱，申鲜虞来奔，仆赁于野，以丧庄公。冬，楚人召之，遂如楚为右尹。
十一月乙亥朔，日有食之。辰在申，司历过也，再失闰矣。
', '', '', '二十七年春季，胥梁带让失去城邑的那些国家准备好车兵徒兵来接受土地，行动必须周密。让乌馀准备车兵来接受封地。乌馀带领他的一批人出来，胥梁带让诸侯假装把土地送给乌馀，因而乘乌馀不备而加以逮捕，全部俘虏了他们。把乌馀的城邑都夺了回来，还给诸侯，诸侯因此归向晋国。
齐国的庆封来鲁国聘问，他的车子很漂亮。盂孙对叔孙说：“庆封的车子，不也很漂亮么！”叔孙说：“豹听说：‘衣饰和人不相称，必然得到恶果。’漂亮的车子有什么用？”叔孙设便宴招待庆封，庆封表现得不恭敬。叔孙为他赋《相鼠》这首诗，他也不明白其中的意思。
卫国的甯喜把持朝政，卫献公担心这件事，公孙免馀请求杀死甯喜。卫献公说：“如果没有甯子，我不能到这地步。我已经对他说过了‘政由甯氏’。事情的结果不能知道，只是得到坏名声，不能做。”公孙免馀回答说：“下臣去杀他，君王不要参与计划就行了。”就和公孙无地、公孙臣商量，让他们攻打甯氏，没有攻下，公孙无地和公孙臣都因此战死了。卫献公说：“臣是没有罪的，父子二人都为我而死了！”夏季，公孙免馀再次攻打甯氏，杀死了甯喜和右宰穀，陈尸在朝廷上。石恶将要参加宋国的结盟，接受了命令而出来，给尸首穿上衣服，头枕在尸体的大腿上而为他们号哭，想要入殓以后自己逃亡，又害怕不能免于祸难，姑且说：“接受使命了。”于是就动身走了。
子鲜说：“驱逐我的逃亡了，接纳我的死去了，赏罚没有章程，如何禁止为恶和勉励为善？国君失掉他的信用而国家没有正常的刑罚，不也很难了吗？而且鱄实在是让甯喜这么做的。”子鲜说完这话就逃亡到晋国去。卫献公让人阻止他，不行。子鲜到达黄河，卫献公又派人阻止他。他不让使者前进，而向黄河发誓。子鲜寄住在木门，坐着都不肯面对着卫国。木门大夫劝他做官，他不同意，说：“做官而废弃自己的职责，这是罪过；要尽自己的职责，这就宣扬了我逃亡的原因。我将要向谁诉说呢？我不能够立在别人的朝廷上了。”一辈子也不出来做官。卫献公为他服丧一直到死。
卫献公给公孙免馀六十个城邑，他辞谢说：“只有卿才具备一百个城邑，下臣已经有六十个邑了。下面的人而有了上面的人的禄位，这是祸乱。下臣不敢听到这种事。而且甯子就因为城邑多了，所以死了，下臣害怕死期快到。”卫献公一定要给他，他接受了一半。让他做了少师。卫献公让他做卿，他辞谢说：“太叔仪没有二心，能够赞助大事，君王还是任命他吧。”于是就让太叔仪做了卿。
宋国的向戌和赵文子友好，又和令尹子木友好，想要停止诸侯之间的战争以取得名声。他去到晋国，告诉了赵文子。赵文子和大夫们商量。韩宣子说：“战争，是残害百姓的祸事，是财货的蛀虫，是小国的大灾难，有人要消除它，虽然说办不到，一定要答应。不答应，楚国将会答应，用来号召诸侯，那么我国就失去盟主的地位了。”晋国人答应了向戌。向戌又去楚国，楚国也答应了。去到齐国，齐国人感到为难。陈文子说：“晋国、楚国答应了，我们怎么能够不答应？而且别人说‘消灭战争’，而我们不答应，那么就使我们的百姓离心了，将要怎么使用他们？”齐国人答应了。告诉秦国，秦国也答应了。这四个国家都通告小国，在宋国举行会见。
五月二十七日，晋国的赵文子到达宋国。二十九日，郑国的良霄也来了。六月初一日，宋国人设享礼招待赵文子，叔向作为赵文子的副手。司马把煮熟的牲畜切成碎块，放在盘子里，这是合于礼的。以后孔子看到了这次礼仪的记载，认为文辞太多。初二日，叔孙豹、齐国的庆封、陈须无、卫国的石恶到达。初八日，晋国的荀盈跟随赵文子之后到达。初十日，邾悼公到达。十六日，楚国的公子黑肱先到达，和晋国商定了有关的条件。二十一日，宋国的向戌去到陈国，和子木商定有关楚国的条件。二十二日，滕成公到达。子木告诉向戌，请求跟从晋国和楚国的国家互相见面。二十四日，向戌向赵文子复命。赵文子说：“晋、楚、齐、秦四国地位对等，晋国不能指挥齐国，如同楚国不能指挥秦国一样。楚国国君如果能让秦国国君驾临敝邑，寡君岂敢不坚决向齐国国君请求？”二十六日，向戌向子木复命，子木派传车请示楚康王。楚康王说：“放下齐国、秦国，请求和其他国家互相见面。”秋季，七月初二日，向戌到达。当夜，赵文子和公子黑肱统一了盟书的措辞。初四日，子木从陈国到达。陈国的孔奂、蔡国的公孙归生到达。曹国和许国的大夫也都来到。各国军队用篱笆做墙作为分界。晋国和楚国各自驻扎在两头。伯夙对赵文子说：“楚国的气氛很不好，恐怕会发生患难。”赵文子说：“我们转折向左，进入宋国，能把我们怎么办？”
初五日，各诸侯国代表准备在宋国西门外边结盟。楚国人在外衣里边穿上皮甲。伯州犁说：“会合诸侯的军队，而做别人不信任的事，恐怕不可以吧，诸侯盼望得到楚国的信任，因此前来顺服。如果不信任别人，这就是丢掉了所用来使诸侯顺服的东西了。”他坚决请求脱去皮甲。子木说：“晋国和楚国缺乏信用已经很久了，唯有去做对我有利的事就是了。如果能如愿，哪里用得着有信用？”伯州犁退下去。对人说：“令尹将要死了，不会到三年。但求满足意志而丢弃信用，意志会满足吗？有意志就形成为语言，有语言就要有信用，有信用就加强意志。这三件事互相关联统一，然后才能确定。信用丢掉了，怎么能活到三年呢？” 赵文子担心楚国人外衣里边穿皮甲，把这情形告诉了叔向。叔向说：“有什么危害？一个普通人一旦做出不守信用的事，尚且不可以，都不得好死。如果一个会合诸侯的卿做出不守信用的事情，就必然不能成功了。说话不算数的人不能给人造成困难，这不是您的祸患。用信用召集别人，而又利用了虚伪，必然没有人同意他，哪里能危害我们？而且我们依靠着宋国来防守他们制造的困难，那就能人人舍命。和宋军一起誓死对抗，即使楚军增加一倍也是可以抵抗的，您有什么可害怕的呢？但是事情又不至于到这一步。口称消除战争以召集诸侯，反而发动战争来危害我们，我们的用处就多了，不必担心。”
季武子派人以鲁襄公的名义对叔孙豹说：“把我国比作和邾国、滕国小国一样。”不久齐国人请求把邾国作为属国，宋国人请求把滕国作为属国，邾国、滕国都不参加结盟，叔孙说：“邾国、滕国，是别人的私属国；我们，是诸侯之国，为什么要看作和他们一样？宋国、卫国，才是和我们对等的。”于是就参加结盟。所以《春秋》不记载叔孙豹的族名，这是说他违背了鲁襄公命令的缘故。
晋国和楚国争执歃血盟誓的先后。晋国人说：“晋国本来是诸侯的盟主，从来没有在晋国之前歃血的。”楚国人说：“您说晋国和楚国的地位相等，如果晋国总是在前面，这就是楚国比晋国弱。而且晋国和楚国交换着主持诸侯的结盟已经很久了。难道专门由晋国主持？”叔向对赵文子说：“诸侯归服晋国的德行，不是归服它主持结盟。您致力于德行，不要去争执先后。而且诸侯结盟会，小国本来一定有主持结盟的事务，让楚国做小国盟主，不也是可以的吗？”于是就让楚国先歃血。《春秋》记载把晋国放在前面，这是由于晋国有信用。
初六日，宋平公同时招待晋国和楚国的大夫，赵文子作为主宾坐首席，子木跟他说话，赵文子不能回答，让叔向在旁边帮着对答，子木也不能回答。
初九日，宋平公和诸侯的大夫在蒙门外结盟。子木向赵文子询问说：“范武子的德行怎么样？”赵文子回答说：“这个人的家事治理得井井有条，对晋国人来说没有可以隐瞒的情况，他的祝史向鬼神表示诚信没有言不由衷的话。”子木回去把话报告楚康王。楚康王说：“高尚啊！能够让神和人高兴，无怪乎他能辅佐五世国君作为盟主。”子木又对楚康王说：“晋国称霸诸侯是合适的，有叔向来辅佐它的卿，楚国没有和他相当的人，不能和他相争。”于是晋国的荀盈就去到楚国参加结盟。
郑简公在垂陇设享礼招待赵文子，子展、伯有、子西、子产、子太叔、两个子石跟从郑简公。赵文子说：“这七位跟从着君王，这是赐给武以光荣。请求都赋诗以完成君王的恩赐，武也可以从这里看到这七位的志向。”子展赋《草虫》这首诗。赵文子说：“好啊，这是百姓的主人！但武是不足以承当的。”伯有赋《鹑之贲贲》这首诗。赵文子说：“床上的话不出门槛，何况在野外呢？这不是使人所应该听到的。”子西赋《黍苗》的第四章。赵文子说：“有寡君在那里，武有什么能力呢？”子产赋《隰桑》这首诗。赵文子说：“武请求接受它的最后一章。”子太叔赋《野有蔓草》这首诗。赵文子说：“这是大夫的恩惠。”印段赋《蟋蟀》这首诗。赵文子说：“好啊，这是保住家族的大夫！我有希望了。”公孙段赋《桑扈》这首诗。赵文子说：“‘不骄不傲’，福禄还会跑到哪儿去？如果保持这些话，即使想要辞掉福禄，能行吗？” 享礼结束，赵文子告诉叔向说：“伯有将要被杀了！诗用来说明心意，心意在于诬蔑他的国君并且公开怨恨国君，又以此作为宾客的光荣，他能够长久吗？即使侥幸，后来也一定逃亡。”叔向说：“对，他太骄奢。所谓不到五年，说的就是这个人了。”赵文子说：“其余的人都是可以传下几世的大夫。子展也许是最后灭亡的，因为处在上位而不忘记降抑自己。印氏是最后第二家灭亡的，因为欢乐而有节制。欢乐用来安定百姓。不要过分使用它们，灭亡在后，不也是可以的吗？”
宋国的左师请求赏赐，说：“下臣免于一死，请求赐给城邑。”宋平公给他六十个城邑，他把文件交给子罕看。子罕说：“凡是诸侯小国，晋国、楚国都用武力来威慑他们，使他们害怕然后就上下慈爱和睦，慈爱和睦然后能安定他们的国家，以事奉大国，这是所以生存的原因。没有威慑就要骄傲，骄傲了祸乱就要发生，祸乱发生必然被灭亡，这就是所以灭亡的原因。上天生长了金、木、水、火、土五种材料，百姓把它们样样使用上，缺一种都不可，谁能够废除武器？武器的设置已经很久了，这是用来威慑不轨而宣扬文德的。圣人由于武力而兴起，作乱的人由于武力而废弃。使兴起者废弃、灭亡者生存、明白者糊涂的策略，都是从武力来的，而您谋求去掉它，不也是欺骗吗？以欺骗蒙蔽诸侯，没有比这再大的罪过了。即使没有大的讨伐，反而又求取赏赐，这是不满足到了极点了。”因此，子罕就把封赏文件上的字削去并且扔了它。左师也就推辞了接受城邑。向氏想要攻打子罕，左师说：“我将要灭亡时，他老人家救了我，没有比这再大的恩德了。又可以攻打吗？”君子说：“‘那位人物，是国家主持正义的人’，这说的就是子罕吧！‘用什么赐给我，我将要接受它’，这说的就是向戌吧？”
齐国的崔杼生下成和强妻子就死了，又娶了东郭姜，生了明。东郭姜带了前夫的儿子，名叫棠无咎，和东郭偃辅佐崔氏。崔成有病被废，立了崔明做继承人。崔成请求在崔地退休，崔杼答应了，偃和无咎不给，说：“崔地，是宗庙所在的地方，一定要归于宗主。”成和强生气，要杀死他们。告诉庆封说：“他老人家的为人，也是您所知道的，惟独听从无咎和偃的话，父老兄长都说不上话。很怕有害于他老人家，谨敢向您报告。”庆封说：“您姑且退出去，我考虑一下。”就告诉卢蒲嫳。卢蒲嫳说：“他，是国君的仇人。上天或者将要抛弃他了。他家里确实出了乱子，您担的什么心？崔家的削弱，就是庆家的加强。”过几天成和强又对庆封说这件事。庆封说：“如果有利于他老人家，一定要去掉他们。如有危难，我来帮助你们。”
九月初五日，在崔氏的朝廷上，崔成、崔强把东郭偃和棠无咎杀了。崔杼生气走了出来，他的手下人都逃了，找人套车，找不着。让养马的圉人套上车，寺人驾着车子出门，崔杼还说：“崔氏如果有福气，祸患仅仅停留在我身上还可以。”就进见庆封。庆封说：“崔、庆是一家。这些人怎么敢这样？请为您讨伐他们。”让卢蒲嫳领着甲士以攻打崔氏。崔氏加筑宫墙据以防守，没有攻下。发动国内的人们帮着攻打，就灭亡了崔氏，杀了成和强，夺取了他家里全部的人口和财货。崔杼的妻子上吊死了。卢蒲嫳向崔杼复命，并且为他驾车送他回家。崔杼到家，已经无家可归了，于是就上吊而死。崔明在夜里躲在墓群里。初六日，崔明逃亡前来，庆封掌握了政权。
楚国的薳罢去到晋国参加盟会，晋平公设享礼招待他。薳罢将要退出的时候，赋了《既醉》这首诗。叔向说：“薳氏在楚国的后代将会长享禄位，应当啊！承受国君的命令，不忘记敏捷从事。子荡将要掌握政权了。用敏捷来事奉国君，必然能保养百姓，政权还跑到哪儿去？”
崔氏那次叛乱，申鲜虞逃亡到鲁国来，在郊外雇用了仆人，为齐庄公服丧。冬季，楚国人召请申鲜虞，申鲜虞去到楚国，做了右尹。
十一月初一日，日食。当时斗柄指申，应该是九月，由于主管历法官员的过错，两次应该置闰月而没有置闰月。', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9b03572034f65b5df9", "shortContent": "蒲松龄在创作《聊斋志异》时，常设茶烟于村口道旁，有行人经过，必请坐，敬茶递烟，然后请客人讲讲奇闻逸事，再由自己粉饰加工，就成了《聊斋》中的一篇。这篇《画马》故事较平淡，无甚曲折，更无讽刺寄托的大手笔，从情节看，只是写了一位穷苦书生因意外地得到了一匹成了精的画马后由贫致富的经历。因此，很可能就是蒲松龄道听途说后“归而粉饰之”的文字。\n《画马》写了一个普通人的一次奇遇，主人公崔生具有普通人虽普通平凡却...", "authors": ["应", "坚"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559126003, '5cedef6ea673f500682d672d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643046, '左传 · 襄公 · 襄公二十八年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有八年春，无冰。夏，卫石恶出奔晋。邾子来朝。秋八月，大雩。仲孙羯如晋。冬，齐庆封来奔。十有一月，公如楚。十有二月甲寅，天王崩。乙未，楚子昭卒。
【传】二十八年春，无冰。梓慎曰：「今兹宋、郑其饥乎？岁在星纪，而淫于玄枵，以有时灾，阴不堪阳。蛇乘龙。龙，宋、郑之星也，宋、郑必饥。玄枵，虚中也。枵，秏名也。土虚而民秏，不饥何为？」
夏。齐侯、陈侯、蔡侯、北燕伯、杞伯、胡子、沈子、白狄朝于晋，宋之盟故也。齐侯将行，庆封曰：「我不与盟，何为于晋？」陈文子曰：「先事后贿，礼也。小事大，未获事焉，从之如志，礼也。虽不与盟，敢叛晋乎？重丘之盟，未可忘也。子其劝行！」
卫人讨宁氏之党，故石恶出奔晋。卫人立其从子圃以守石氏之祀，礼也。
邾悼公来朝，时事也。
秋八月，大雩，旱也。
蔡侯归自晋，入于郑。郑伯享之，不敬。子产曰：「蔡侯其不免乎？日其过此也，君使子展廷劳于东门之外，而傲。吾曰：『犹将更之。』今还，受享而惰，乃其心也。君小国事大国，而惰傲以为己心，将得死乎？若不免，必由其子。其为君也，淫而不父。侨闻之，如是者，恒有子祸。」
孟孝伯如晋，告将为宋之盟故如楚也。
蔡侯之如晋也，郑伯使游吉如楚。及汉，楚人还之，曰：「宋之盟，君实亲辱。今吾子来，寡君谓吾子姑还！吾将使馹奔问诸晋而以告。」子大叔曰：「宋之盟，君命将利小国，而亦使安定其社稷，镇抚其民人，以礼承天之休，此君之宪令，而小国之望也。寡君是故使吉奉其皮币，以岁之不易，聘于下执事。今执事有命曰：『女何与政令之有？必使而君弃而封守，跋涉山川，蒙犯霜露，以逞君心。』小国将君是望，敢不唯命是听。无乃非盟载之言，以阙君德，而执事有不利焉，小国是惧。不然，其何劳之敢惮？」子大叔归，覆命，告子展曰：「楚子将死矣！不修其政德，而贪昧于诸侯，以逞其愿，欲久，得乎？《周易》有之，在《复》三之《颐》三，曰：『迷复，凶。』其楚子之谓乎？欲复其愿，而弃其本，复归无所，是谓迷复。能无凶乎？君其往也！送葬而归，以快楚心。楚不几十年，未能恤诸侯也。吾乃休吾民矣。」裨灶曰：「今兹周王及楚子皆将死。岁弃其次，而旅于明年之次，以害鸟帑。周、楚恶之。」
九月，郑游吉如晋，告将朝于楚，以从宋之盟。子产相郑伯以如楚，舍不为坛。外仆言曰：「昔先大夫相先君，适四国，未尝不为坛。自是至今，亦皆循之。今子草舍，无乃不可乎？」子产曰：「大适小，则为坛。小适大，苟舍而已，焉用坛？侨闻之，大适小有五美：宥其罪戾，赦其过失，救其灾患，赏其德刑，教其不及。小国不困，怀服如归。是故作坛以昭其功，宣告后人，无怠于德。小适大有五恶：说其罪戾，请其不足，行其政事，共某职贡，从其时命。不然，则重其币帛，以贺其福而吊其凶，皆小国之祸也。焉用作坛以昭其祸？所以告子孙，无昭祸焉可也。」
齐庄封好田而耆酒，与庆舍政。则以其内实迁于卢蒲弊氏，易内而饮酒。数日，国迁朝焉。使诸亡人得贼者，以告而反之，故反卢蒲癸。癸臣子之，有宠，妻之。庆舍之士谓卢蒲癸曰：「男女辨姓。子不辟宗，何也？」曰：「宗不馀辟，余独焉辟之？赋诗断章，余取所求焉，恶识宗？」癸言王何而反之，二人皆嬖，使执寝戈，而先后之。
公膳，日双鸡。饔人窃更之以鹜。御者知之，则去其肉而以其洎馈。子雅、子尾怒。庆封告卢蒲弊。卢蒲弊曰；「譬之如禽兽，吾寝处之矣。」使析归父告晏平仲。平仲曰：「婴之众不足用也，知无能谋也。言弗敢出，有盟可也。」子家曰：「子之言云，又焉用盟？」告北郭子车。子车曰：「人各有以事君，非佐之所能也。」陈文子谓桓子曰：「祸将作矣！吾其何得？」对曰：「得庆氏之木百车于庄。」文子曰：「可慎守也已！」
卢蒲癸、王何卜攻庆氏，示子之兆，曰：「或卜攻仇，敢献其兆。」子之曰：「克，见血。」冬十月，庆封田于莱，陈无宇从。丙辰，文子使召之。请曰：「无宇之母疾病，请归。」庆季卜之，示之兆，曰：「死。」奉龟而泣。乃使归。庆嗣闻之，曰：「祸将作矣！谓子家：「速归！祸作必于尝，归犹可及也。」子家弗听，亦无悛志。子息曰：「亡矣！幸而获在吴、越。」陈无宇济水而戕舟发梁。卢蒲姜谓癸曰：「有事而不告我，必不捷矣。」癸告之。姜曰：「夫子愎，莫之止，将不出，我请止之。」癸曰：「诺。」十一月乙亥，尝于大公之庙，庆舍莅事。卢蒲姜告之，且止之。弗听，曰：「谁敢者！」遂如公。麻婴为尸，庆圭为上献。卢蒲癸、王何执寝戈。庆氏以其甲环公宫。陈氏、鲍氏之圉人为优。庆氏之马善惊，士皆释甲束马而饮酒，且观优，至于鱼里。栾、高、陈、鲍之徒介庆氏之甲。子尾抽桷击扉三，卢蒲癸自后刺子之，王何以戈击之，解其左肩。犹援庙桷，动于甍，以俎壶投，杀人而后死。遂杀庆绳、麻婴。公惧，鲍国曰：「群臣为君故也。」陈须无以公归，税服而如内宫。
庆封归，遇告乱者，丁亥，伐西门，弗克。还伐北门，克之。入，伐内宫，弗克。反，陈于岳，请战，弗许。遂来奔。献车于季武子，美泽可以鉴。展庄叔见之，曰：「车甚泽，人必瘁，宜其亡也。」叔孙穆子食庆封，庆封汜祭。穆子不说，使工为之诵《茅鸱》，亦不知。既而齐人来让，奔吴。吴句余予之朱方，聚其族焉而居之，富于其旧。子服惠伯谓叔孙曰：「天殆富淫人，庆封又富矣。」穆子曰：「善人富谓之赏，淫人富谓之殃。天其殃之也，其将聚而歼旃？」
癸巳，天王崩。未来赴，亦未书，礼也。
崔氏之乱，丧群公子。故锄在鲁，叔孙还在燕，贾在句渎之丘。及庆氏亡，皆召之，具其器用而反其邑焉。与晏子邶殿，其鄙六十，弗受。子尾曰：「富，人之所欲也，何独弗欲？」对曰：「庆氏之邑足欲，故亡。吾邑不足欲也。益之以邶殿，乃足欲。足欲，亡无日矣。在外，不得宰吾一邑。不受邶殿，非恶富也，恐失富也。且夫富如布帛之有幅焉，为之制度，使无迁也。夫民生厚而用利，于是乎正德以幅之，使无黜嫚，谓之幅利。利过则为败。吾不敢贪多，所谓幅也。」与北郭佐邑六十，受之。与子雅邑，辞多受少。与子尾邑，受而稍致之。公以为忠，故有宠。
释卢蒲弊于北竟。求崔杼之尸，将戮之，不得。叔孙穆子曰：「必得之。武王有乱臣十人，崔杼其有乎？不十人，不足以葬。」既，崔氏之臣曰：「与我其拱璧，吾献其柩。」于是得之。十二月乙亥朔，齐人迁庄公，殡于大寝。以其棺尸崔杼于市，国人犹知之，皆曰：「崔子也。」
为宋之盟故，公及宋公、陈侯、郑伯、许男如楚。公过郑，郑伯不在。伯有廷劳于黄崖，不敬。穆叔曰：「伯有无戾于郑，郑必有大咎。敬，民之主也，而弃之，何以承守？郑人不讨，必受其辜，济泽之阿，行潦之苹藻，置诸宗室，季兰尸之，敬也。敬可弃乎？」
及汉，楚康王卒。公欲反，叔仲昭伯曰：「我楚国之为，岂为一人？行也！」子服惠伯曰：「君子有远虑，小人从迩。饥寒之不恤，谁遑其后？不如姑归也。」叔孙穆子曰：「叔仲子专之矣，子服子始学者也。」荣成伯曰：「远图者，忠也。」公遂行。宋向戌曰：「我一人之为，非为楚也。饥寒之不恤，谁能恤楚？姑归而息民，待其立君而为之备。」宋公遂反。
楚屈建卒。赵文子丧之如同盟，礼也。
王人来告丧，问崩日，以甲寅告，故书之，以征过也。', '', '', '二十八年春季，没有冰。梓慎说：“今年宋国和郑国恐怕要发生饥荒了吧！岁星应当在星纪，但已经过头到了玄枵。这是因为要发生天时不正的灾荒，阴不能战胜阳。蛇乘坐在龙的上边，龙是宋国、郑国的星宿，所以宋国、郑国必然发生饥荒。玄枵，虚宿在它的中间。枵，是消耗的名称。土地虚而百姓耗，不发生饥荒才怪呢！”
夏季，齐景公、陈哀公、蔡景侯、北燕伯、杞文公、胡子、沈子、白狄到晋国朝见，这是由于在宋国那次结盟的缘故。齐景公准备出行，庆封说：“我们没有参加结盟，为什么要向晋国朝见？”陈文子说：“先考虑事奉大国而后考虑财货，这是合于礼的。小国事奉大国，如果没有得到事奉的机会，就要顺从大国的意图，这也是合于礼的。我们虽然没有参加结盟，岂敢背叛晋国呢？重丘的盟会，不可以忘记啊。您还是劝国君出行！”
卫国人讨伐甯氏的亲族，所以石恶逃亡到晋国。卫国人立了他的侄儿石圃，以保存石氏的祭祀，这是合于礼的。
邾悼公前来朝见，这是按时令而来朝见。
秋季，八月，举行大雩祭，这是由于发生了旱灾。
蔡景侯从晋国回国，路过郑国。郑简公设享礼招待他，蔡景侯表现得不恭敬。子产说：“蔡侯恐怕不能免于祸难吧！以前经过这里的时候，国君派子展去到东门外边慰劳，但是他很骄傲。我认为他还是会改变的。现在他回来，接受享礼而显得怠惰，这就是他的本性了。作为小国的国君，事奉大国，反而把怠惰骄傲作为本性，将来能有好死吗？如果不免于祸难，一定由于他的儿子。他做国君，淫乱而不像做父亲的样子。侨听说，像这样的人，经常会遇到儿子来作乱。”
孟孝伯去到晋国，这是由于报告为“宋之盟”的缘故而将到楚国去。
蔡景公去到晋国的时候，郑简公派游吉去到楚国。到达汉水，楚国人让他回去，说：“在宋国的那次结盟，贵国君王亲自参加。现在大夫前来，寡君说大夫暂且回去，我将要派传车奔赴晋国询问以后再告诉您。”游吉说：“在宋国的那次结盟，贵国君王的命令将要有利于小国，而也使小国安定他的国家，镇抚它的百姓，用礼仪承受上天的福禄，这是贵国君王的法令，同时也是小国的希望。寡君因此派吉奉上财礼，由于年来多难，特向下级执事聘问。现在执事命令说：你怎么能参与郑国的政令？一定要让你们国君丢掉你们的疆土和守备，跋山涉水，冒着霜露，以满足我国君王的心意。小国还想期望贵国君王赐给恩惠，哪里敢不唯命是听？但这不符合盟书的话，而使贵国君王的德行有缺失，也对执享有所不利，小国就害怕这个。否则，还敢怕什么劳苦呢？”
游吉回国，复命，告诉子展说：“楚王将要死了。不修明他的政事德行，反而在诸侯那里贪图进奉，以达到自己的愿望，想要活得长久，行吗？《周易》有这样的情况，得到《复》卦变成《颐》卦，说‘迷路往回走，不吉利。’这说的就是楚王吧？想实现他的愿望，而放弃了本来的道路，想回去没有了归路，这就叫‘迷复’，能够吉利吗？国君就去吧，送了葬回来，让楚国痛快一下。楚国没有近十年的时间，不能争霸，我们就可以让百姓休息了。”裨灶说：“今年周天子和楚王都将死去。岁星失去它应有的位置，而运行在明年的位置上，要危害鸟尾，周朝和楚国要受灾祸。”
九月，郑国的游吉去到晋国，报告说按照在宋国的盟誓将要去楚国朝见。子产辅助郑伯去到楚国，搭了帐篷而不筑坛。外仆说：“从前先大夫辅助先君到四方各国，从没有不筑坛的。从那个时候到今天也都没有改变。现在您不除草就搭起帐篷，恐怕不可以吧！”子产说：“大国君臣去到小国，就筑坛；小国去到大国，随便搭个帐篷就行了，哪里用得着筑坛？侨听说过：大国君臣去到小国有五种好处：赦免它的罪过，原谅它的失误，救助它的灾难，赞赏它的德行和刑法。教导它所想不到的地方，小国不困乏，想念和顺服大国，好像回家一样，因此筑坛来表扬它的功德，公开告诉后代的人，不要怠情于修德业。小国去到大国有五种坏处：向小国掩饰它的罪过，请求得到它所缺乏的东西，要求小国奉行它的命令，供给它贡品，服从它的随时发出的命令。不这样，就得加重小国的财礼，用来祝贺它的喜事和吊唁它的祸事，这都是小国的祸患，哪里用得着筑坛招来它的祸患？把这些告诉子孙，不要招来祸患就可以了。”
齐国的庆封喜欢打猎而嗜好喝酒，把政权交付给庆舍，就带着他的妻妾财物迁到卢蒲嫳家里，交换妻妾而喝酒。几天以后，官员们就改到这里来朝见。庆封让逃亡在外而知道崔氏馀党的人，如果前来报告就允许他回国，所以就让卢蒲癸回来。卢蒲癸做了庆舍的家臣，受到宠信，庆舍就把女儿嫁给了卢蒲癸。庆舍的家臣对卢蒲癸说：“男女结婚要区别是否同姓，您却不避同宗，为什么？”卢蒲癸说：“同宗不避我，我怎么能独独避开同宗？比如赋诗时的断章取义，我取我所需要的就是了，哪里知道什么同宗不同宗？”卢蒲癸又对庆舍说起王何而让他回来，两个人都受到了庆舍的宠信。庆舍让他们拿着武器寝戈作为随身警卫。
卿大夫在朝廷办公务用餐，每天有两只鸡，管伙食的人偷偷地换成鸭子。送饭的人知道了，把肉都拿掉而只将肉汤送上来。子雅、子尾生气。庆封告诉卢蒲嫳。卢蒲嫳说：“把他们比成禽兽，我睡在他们的皮毛上了。”于是就派析归父告诉晏平仲。晏平仲说：“婴的一伙人不足以使用，聪明也出不了主意。但是决不敢泄露这些话，可以盟誓。”析归父说：“您已经这样说了，哪里还用盟誓？”又告诉北郭子车。子车说：“各人都有不同的方式事奉国君，这不是佐所能做到的。”陈文子对陈无宇说：“祸难将要发生了，我们能得到什么？”陈无宇回答说：“可以在庄街上得到庆氏的木头一百车。”陈文子说：“可以谨慎地保守住就行了。”
卢蒲癸、王何为进攻庆氏而占卜，把卦像给庆舍看，说：“有人为攻打仇人而占卜，谨敢奉献卦像。”庆舍说：“攻下了，见到血。”冬季，十月，庆封在莱地打猎，陈无宇跟从。十七日，陈文子派人召唤陈无宇回去，陈无宇请求说：“无宇的母亲病了，请求回去。”庆封占卜，把卦像给陈无宇看，陈无宇说：“这是死的卦像。”捧着龟甲而哭泣，于是就让他回去了。庆嗣听到这件事，说：“祸难将要发生了。”告诉庆封说：“赶快回去，祸难必然发生在秋祭的时候，回去还来得及。”庆封不听，也没有改悔的意思。庆嗣说：“他要逃亡了，能够逃到吴国、楚国就是侥幸。”陈无宇渡过河，就破坏了渡船撤毁了桥梁。
卢蒲姜对卢蒲癸说：“有事情而不告诉我，必然不能成功。”卢蒲癸告诉了她。卢蒲姜说：“我父亲性情倔强，没有人劝阻他，反倒不出来了。请让我去劝阻他。”卢蒲癸说：“好。”十一月初七日，在太公的庙里举行秋祭，庆舍将亲临主持祭祀。卢蒲姜告诉他有人要发动祸乱，而且劝他不要去。他不听，说：“谁敢这么干？”就去到太庙参加祭祀。麻婴充当祭尸，庆奊充当上献。卢蒲癸、王何手拿寝戈，庆氏领着他的甲士围住公宫。陈氏、鲍氏的养马人表演，庆氏的马容易受惊，甲士都解甲系马而喝酒，同时看戏，到了鱼里。栾氏、高氏、陈氏、鲍氏的徒兵就穿上了庆氏的皮甲。子尾抽出槌子，在门上敲了三下，卢蒲癸从后边刺庆舍，王何用戈对他猛击，打下了庆舍的左肩。庆舍还能攀着庙宇的椽子，震动了栋梁，把俎和壶向人扔去，杀死了人才死去。卢蒲癸等人就杀死了庆绳、麻婴。齐景公恐惧，鲍国说：“臣下们是为了君王的缘故。”陈须无带着齐景公回去，脱去祭服进了内宫。
庆封回来，碰到报告动乱的人。十九日，攻打西门，没有攻下。回过来攻打北门，攻下了。进城，攻打内宫，没有攻下。返回来，列阵于大街上，庆封请求决战，没有得到允许，就逃亡到鲁国来。庆封把车子献给季武子，美丽光亮可以作镜子。展庄叔进见季武子，说：“车很光亮，人必然憔悴，无怪乎他要逃亡了。”叔孙穆子设便宴招待庆封，庆封先遍祭诸神。穆子不高兴，让乐工为他诵《茅鸱》这首诗，他也不明白。不久以后齐国人前来责问，庆封又逃亡到吴国。吴子勾馀把朱方封给了庆封，他聚集了族人住在那里，比以前更富有。子服惠伯对叔孙穆子说：“上天大概要让坏人富有的，庆封又富有起来了。”叔孙穆子说：“好人富有叫做奖赏，坏人富有叫做灾殃。上天恐怕是降灾于他了，将要让他们聚集而一起被杀尽吧！”
十一月二十五日，周灵王逝世。没有发来讣告，《春秋》也没有记载，这是合于礼的。
崔氏那次动乱，公子们各自逃亡，所以锄在鲁国，叔孙还在燕国，贾在句渎之丘。等到庆氏逃亡，把他们都召了回来，为他们准备了器物用具并且发还给他们封邑。另外封给晏子邶殿边上六十个城邑，晏子不接受。子尾说：“富有，是人所需要的。为什么独独您不要？”晏子回答说：“庆氏的城邑满足了欲望，所以逃亡。我的城邑不能满足欲望，加上邶殿，就满足欲望了。满足了欲望，离逃亡就没有几天了。逃亡在外边连一个城邑都不能主宰。不接受邶殿，不是讨厌富有，而是恐怕失去富有。而且富有，就像布帛的有一定宽度。给它规定幅度，让它不能改变。百姓，总是想生活丰厚，器用富饶，因此就要端正道德，而加以限制，让它不要不够，也不要过分，这叫做限制私利。私利过了头就会败坏。我不敢贪多，就是所谓限制私利。”齐景公赐给北郭佐六十个城邑，他接受了。赐给子雅城邑，他婉辞了大多数而接受了少数。赐给子尾城邑，他接受之后又奉还了。齐景公认为子尾忠诚，所以子尾很得宠信。
把卢蒲嫳放逐到齐国北部边境。齐国人接着求取崔杼的尸体，准备戮尸，但没找到。叔孙穆子说：“一定找得着的。武王有十个治世之臣，崔杼难道能有吗？不到十个人，不足以安葬。”过了不久，崔氏的家臣说：“把他的大玉璧给我，我献出他的棺材。”因此就找到了崔杼的尸体。十二月初一日，齐国人迁葬庄公，停棺在正寝。用崔杼的棺材装着崔杼的尸体放在街上示众。国内人们都知道，都说：“这是崔杼。”
由于“宋国之盟”的缘故，鲁襄公和宋平公、陈哀公、郑简公、许悼公到了楚国。鲁襄公经过郑国，郑简公不在国内，伯有到黄崖慰劳，表现得不恭敬，穆叔说：“伯有如果在郑国没有罪，郑国必然有大灾祸。恭敬，是百姓的主宰，现在丢弃了它，如何能继承祖宗保持的家业？郑国人不讨伐他，必然要遭到他的灾祸。水边的薄土，路边积水中的浮萍水草，用来作祭品，季兰作为祭尸，这是由于恭敬。恭敬难道能丢弃吗？”
到达汉水，楚康王死。鲁襄公想要回去。叔仲昭伯说：“我们是为了楚国，哪里是为了一个人？继续走吧！”子服惠伯说：“君子有长远考虑，小人只看到眼前。饥寒都顾不上，谁有工夫顾到后果？不如暂且回去吧。”叔孙穆子说：“叔仲子可以被专门任用了，子服子，是刚刚开始学习的人。“荣成伯说：“长远打算的人是忠诚的。”鲁襄公就继续前往楚国。宋国的向戌说：“我们是为了一个人，不是为了楚国。饥寒都顾不上，谁能顾得上楚国？姑且回去而使百姓休息，等他们立了国君再戒备他们。”宋平公就回去了。
楚国的屈建死，赵文子去吊丧好像对待盟国一样，这是合于礼的。
周朝的使者来鲁国通知丧事，问他周天子死去的日期，用十二月十六日作为回答，所以《春秋》也这样记载，用以惩戒过错。', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8b5e272d4b2255c207", "shortContent": "在李复言的《续玄怪录》中，有好几篇小说宣扬婚姻命中注定的思想，如《定婚店》、《张老》等，本篇亦是。其以短小的篇幅塑造出生动的人物形象，在艺术上颇有特点。\n本文开始，女主人出于对即将出阁的女儿未来生活的关心，向参加婚礼的女巫询问女婿卢生的前程吉凶，是在情理之中的。但女巫却说那位卢生根本不是你的女婿！卢生长得又高又大，蓄着长须，而你的女婿却应该是中等身材，也不蓄胡须的。女巫的这番话不要说那位女主人听了...", "authors": ["史美圣"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559126049, '5cedef9b7b968a00767d3943', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643047, '左传 · 襄公 · 襄公二十九年 ', NULL, 22, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有九年春王正月，公在楚。夏五月，公至自楚。庚午，卫侯衎卒，阍弑吴子余祭。仲孙羯会晋荀盈、齐高止、宋华定、卫世叔仪、郑公孙段、曹人、莒人、滕子、薛人、小邾人城杞。晋侯使士鞅来聘。杞子来盟。吴子使札来聘。秋九月，葬卫献公。齐高止出奔北燕。冬，仲孙羯如晋。
【传】二十九年春，王正月，公在楚，释不朝正于庙也。楚人使公亲襚，公患之。穆叔曰：「祓殡而襚，则布币也。」乃使巫以桃列先祓殡。楚人弗禁，既而悔之。
二月癸卯，齐人葬庄公于北郭。
夏四月，葬楚康王。公及陈侯、郑伯、许男送葬，至于西门之外。诸侯之大夫皆至于墓。楚郏敖即位。王子围为令尹。郑行人子羽曰：「是谓不宜，必代之昌。松柏之下，其草不殖。」
公还，及方城。季武子取卞，使公冶问，玺书追而与之，曰：「闻守卞者将叛，臣帅徒以讨之，既得之矣，敢告。」公冶致使而退，及舍而后闻取卞。公曰：「欲之而言叛，只见疏也。」公谓公冶曰：「吾可以入乎？」对曰：「君实有国，谁敢违君！」公与公冶冕服。固辞，强之而后受。公欲无入，荣成伯赋《式微》，乃归。五月，公至自楚。公冶致其邑于季氏，而终不入焉。曰：「欺其君，何必使余？」季孙见之，则言季氏如他日。不见，则终不言季氏。及疾，聚其臣，曰：「我死，必以在冕服敛，非德赏也。且无使季氏葬我。」
葬灵王，郑上卿有事，子展使印段往。伯有曰：「弱，不可。」子展曰：「与其莫往，弱不犹愈乎？《诗》云：『王事靡盬，不遑启处，东西南北，谁敢宁处？坚事晋、楚，以蕃王室也。王事无旷，何常之有？」遂使印段如周。
吴人伐越，获俘焉，以为阍，使守舟。吴子余祭观舟，阍以刀弑之。
郑子展卒，子皮即位。于是郑饥而未及麦，民病。子皮以子展之命，饩国人粟，户一钟，是以得郑国之民。故罕氏常掌国政，以为上卿。宋司城子罕闻之，曰：「邻于善，民之望也。」宋亦饥，请于平公，出公粟以贷。使大夫皆贷。司城氏贷而不书，为大夫之无者贷。宋无饥人。叔向闻之，曰：「郑之罕，宋之乐，其后亡者也！二者其皆得国乎！民之归也。施而不德，乐氏加焉，其以宋升降乎！」
晋平公，杞出也，故治杞。六月，知悼子合诸侯之大夫以城杞，孟孝伯会之。郑子大叔与伯石往。子大叔见大叔文子，与之语。文子曰：「甚乎！其城杞也。」子大叔曰：「若之何哉？晋国不恤周宗之阙，而夏肄是屏。其弃诸姬，亦可知也已。诸姬是弃，其谁归之？吉也闻之，弃同即异，是谓离德。《诗》曰：『协比其邻，昏姻孔云。』晋不邻矣，其谁云之？」
齐高子容与宋司徒见知伯，女齐相礼。宾出，司马侯言于知伯曰：「二子皆将不免。子容专，司徒移，皆亡家之主也。」知伯曰：「何如？」对曰：「专则速及，侈将以其力毙，专则人实毙之，将及矣。」
范献子来聘，拜城杞也。公享之，展庄叔执币。射者三耦，公臣不足，取于家臣，家臣：展瑕、展玉父为一耦。公臣，公巫召伯、仲颜庄叔为一耦，鄫鼓父、党叔为一耦。
晋侯使司马女叔侯来治杞田，弗尽归也。晋悼夫人愠曰：「齐也取货。先君若有知也，不尚取之！」公告叔侯，叔侯曰：「虞、虢、焦、滑、霍、扬、韩、魏，皆姬姓也，晋是以大。若非侵小，将何所取？武、献以下，兼国多矣，谁得治之？杞，夏余也，而即东夷。鲁，周公之后也，而睦于晋。以杞封鲁犹可，而何有焉？鲁之于晋也，职贡不乏，玩好时至，公卿大夫相继于朝，史不绝书，府无虚月。如是可矣，何必瘠鲁以肥杞？且先君而有知也，毋宁夫人，而焉用老臣？」
杞文公来盟。书曰「子」，贱之也。
吴公子札来聘，见叔孙穆子，说之。谓穆子曰：「子其不得死乎？好善而不能择人。吾闻『君子务在择人』。吾子为鲁宗卿，而任其大政，不慎举，何以堪之？祸必及子！」
请观于周乐。使工为之歌《周南》、《召南》，曰：「美哉！始基之矣，犹未也。然勤而不怨矣。」为之歌《邶》、《鄘》、《卫》，曰：「美哉，渊乎！忧而不困者也。吾闻卫康叔、武公之德如是，是其《卫风》乎？」为之歌《王》，曰：「美哉！思而不惧，其周之东乎？」为之歌《郑》，曰：「美哉！其细已甚，民弗堪也，是其先亡乎！」为之歌《齐》，曰：「美哉！泱泱乎！大风也哉！表东海者，其大公乎！国未可量也。」为之歌《豳》，曰：「美哉！荡乎！乐而不淫，其周公之东乎？」为之歌《秦》，曰：「此之谓夏声。夫能夏则大，大之至也，其周之旧乎？」为之歌《魏》，曰：「美哉！渢渢乎！大而婉，险而易行，以德辅此，则明主也。」为之歌《唐》，曰：「思深哉！其有陶唐氏之遗民乎？不然，何忧之远也？非令德之后，谁能若是？」为之歌《陈》，曰：「国无主，其能久乎？」自《郐》以下无讥焉。为之歌《小雅》，曰：「美哉！思而不贰，怨而不言，其周德之衰乎？犹有先王之遗民焉。」为之歌《大雅》，曰：「广哉！熙熙乎！曲而有直体，其文王之德乎？」为之歌《颂》，曰：「至矣哉！直而不倨，曲而不屈，迩而不逼，远而不携，迁而不淫，复而不厌，哀而不愁，乐而不荒，用而不匮，广而不宣，施而不费，取而不贪，处而不底，行而不流，五声和，八风平，节有度，守有序，盛德之所同也。」
见舞《象箾》《南籥》者，曰：「美哉！犹有憾。」见舞《大武》者，曰：「美哉！周之盛也，其若此乎！」见舞《韶濩》者，曰：「圣人之弘也，而犹有惭德，圣人之难也。」见舞《大夏》者，曰：「美哉！勤而不德，非禹其谁能修之？」见舞《韶箾》者，曰：「德至矣哉！大矣！如天之无不帱也，如地之无不载也，虽甚盛德，其蔑以加于此矣。观止矣！若有他乐，吾不敢请已！」
其出聘也，通嗣君也。故遂聘于齐，说晏平仲，谓之曰：「子速纳邑与政！无邑无政，乃免于难。齐国之政，将有所归，未获所归，难未歇也。」故晏子因陈桓子以纳政与邑，是以免于栾、高之难。
聘于郑，见子产，如旧相识，与之缟带，子产献丝宁衣焉。谓子产曰：「郑之执政侈，难将至矣！政必及子。子为政，慎之以礼。不然，郑国将败。」
适卫，说蘧瑗、史狗、史鳅，公子荆、公叔发、公子朝，曰：「卫多君子，未有患也。」
自卫如晋，将宿于戚。闻钟声焉，曰：「异哉！吾闻之也：『辩而不德，必加于戮。』夫子获罪于君以在此，惧犹不足，而又何乐？夫子之在此也，犹燕之巢于幕上。君又在殡，而可以乐乎？」遂去之。文子闻之，终身不听琴瑟。
适晋，说赵文子、韩宣子、魏献子，曰：「晋国其萃于三族乎！」说叔向，将行，谓叔向曰：「吾子勉之！君侈而多良，大夫皆富，政将在家。吾子好直，必思自免于难。」
秋九月，齐公孙虿、公孙灶放其大夫高止于北燕。乙未，出。书曰：「出奔。」罪高止也。高止好以事自为功，且专，故难及之。
冬，孟孝伯如晋，报范叔也。
为高氏之难故，高竖以卢叛。十月庚寅，闾丘婴帅师围卢。高竖曰：「苟请高氏有后，请致邑。」齐人立敬仲之曾孙宴，良敬仲也。十一月乙卯，高竖致卢而出奔晋，晋人城绵而置旃。
郑伯有使公孙黑如楚，辞曰：「楚、郑方恶，而使余往，是杀余也。」伯有曰：「世行也。」子皙曰：「可则往，难则已，何世之有？」伯有将强使之。子皙怒，将伐伯有氏，大夫和之。十二月己巳，郑大夫盟于伯有氏。裨谌曰：「是盟也，其与几何？《诗》曰：『君子屡盟，乱是用长。』今是长乱之道也。祸未歇也，必三年而后能纾。」然明曰：「政将焉往？」裨谌曰：「善之代不善，天命也，其焉辟子产？举不逾等，则位班也。择善而举，则世隆也。天又除之，夺伯有魄，子西即世，将焉辟之？天祸郑久矣，其必使子产息之，乃犹可以戾。不然，将亡矣。」', '', '', '二十九年春季，周王朝历法的正月，“公在楚”，这是为了解释不在祖庙中举行听政的原因。楚国人让鲁襄公亲自为楚康王的尸体赠送寿衣，襄公对这感到忧虑。穆叔说：“先扫除棺材的凶邪然后给死者赠送衣服，这就等于朝见时陈列皮币。”于是就让巫人用桃棒、笤帚先在棺材上扫除不祥。楚国人没有禁止，不久以后又感到后悔。
二月初六日，齐国人在外城北部安葬齐庄公。
夏季，四月，安葬楚康王，鲁襄公和陈哀公、郑简公、许悼公都参加送葬，到达西门外边，各诸侯的大夫都到了墓地。楚国的郏敖即位，王子围做令尹。郑国的使者子羽说：“这叫做不恰当，令尹必然要代替楚君而昌盛。松柏的下面，草是不能繁殖的。”
鲁襄公回来，到达方城山。季武子占领了卞地，派公冶来问候襄公，用封泥加印把信封好了追上去给了公冶，信上说：“听到戍守卞地的人打算叛变，下臣率领部下讨伐了他，已经得到卞地了，谨此报告。”公冶表达了使命就退出去，到达帐篷以后才听到占领了卞地。鲁襄公说：“想要这块地方而又说叛变，只能是对我表示疏远。” 鲁襄公对公冶说：“我可以进入国境吗？”公冶回答说：“君王据有国家，谁敢违背君王？”鲁襄公赐给公冶冕服，公冶坚决辞谢，勉强他，然后才接受了。鲁襄公想不进入国境，荣成伯赋《式微》这首诗，鲁襄公这才回国。
五月，鲁襄公从楚国回来。公冶把他的封邑送还给季氏，而且始终不再进入季孙的家门，说：“欺骗他的国君，何必派我？”季孙和他见面，就和季孙像以前一样说话。不相见，公冶始终不谈季氏。等到公冶病危，聚集他的家臣，说：“我死了以后，一定不要用冕服入敛，因为这不是由于德行而所得的赏赐。并且还不要让季氏来安葬我。”
安葬周灵王。郑国的上卿子展有事不能离开，他派印段前去。伯有说：“年纪轻，不行。”子展说：“与其没有人去，尽管年轻，比没人去还要好一点吧？《诗》说：‘王事应当细致，没有空闲安居。’东西南北，谁敢安安稳稳地居住？坚定地事奉晋国、楚国，用以捍卫王室。王事没有缺失，有什么常例不常例？”于是就派印段前去成周。
吴国人进攻越国，抓到了俘虏，让他做看门人，派他看守船只。吴王馀祭观看船只，看门人用刀杀死了吴王。
郑国的子展死，子皮即位为上卿。当时郑国有饥荒而还没有到麦收，百姓很困乏。子皮用子展的遗命把粮食赠给国内的人们，每户一钟，因此得到郑国百姓的拥护。所以罕氏经常掌握国政，作为上卿。宋国的司城子罕听到了，说：“接近于善，这是百姓的期望。”宋国也发生了饥荒，司城子罕向宋平公请求，拿出公家的粮食借给百姓，让大夫也都出借粮食。司城氏借出粮食不写契约，又替缺少粮食的大夫借给百姓。宋国没有挨饿的人。叔向听说了这件事，说：“郑国的罕氏，宋国的乐氏，大约是最后灭亡的啊，两家恐怕都要掌握政权吧！这是因为百姓归向他们的缘故。施舍而不自以为给人恩惠，乐氏就更高出一筹了，这一家大概是会随着宋国的盛衰而升降吧！”
晋平公，是杞女所生的，所以修整杞国的城墙。六月，知悼子会合诸侯的大夫为杞国筑城墙，孟孝伯参加了。郑国的子太叔和伯石前去。子太叔见到太叔文子，和他说话。文子说：“为杞国筑城这件事过分了！”子太叔说：“拿他怎么办好啊！晋国不担心周室的衰微，反而保护夏朝的残馀，它会丢弃姬姓诸国，也就可以想象到了。丢弃姬姓诸国，有谁去归向他？吉听说：丢弃同姓而亲近异姓，这叫做离德。《诗》说：‘和谐他的近亲，姻亲就会和他友好来往。’晋国把近亲不看作近亲，还有谁来和他友好往来？”
齐国的高子容和宋国的司徒进见知伯，女齐作为相礼者，客人出去了，女齐对知伯说：“这两位将不免于祸。子容专权，司徒奢侈，都是使家族灭亡的大夫。”知伯说：“怎么呢？”女齐回答说：“专横就会很快及于祸患，奢侈将会由于力量强大而死，专横别人就会要他的命，他将要及于祸患了。”
范献子来鲁国聘问，拜谢在杞国筑城。鲁襄公设享礼招待他，展庄叔拿着束帛。参加射礼的要三对人。公臣的人选不够，在家臣中选取。家臣，展暇、展王父作为一对，公臣，公巫召伯、仲颜庄叔作为一对，鄫鼓父、党叔作为一对。
晋平公派司马女叔侯来鲁国办理使鲁国归还杞国土田的事情，但没有全部归还给杞国。晋悼公夫人很生气他说：“女齐办事不得力，先君如果有知，不会赞助他这样办事的。”晋平公把这件事告诉了叔侯。叔侯说：“虞国、虢国、焦国、滑国、霍国、杨国、韩国、魏国，都是姬姓，晋国因此而扩大。如果不是入侵小国，将要从哪里取得？武公、献公以来，兼并的国家就多了，谁能够治理它？杞国，是夏朝的后代，而接近东夷。鲁国，是周公的后代，而和晋国和睦。把杞国封给鲁国还是可以的，有什么杞国不杞国？鲁国对于晋国，贡品不缺乏，玩物按时送到，公卿大夫不断前来朝见，史官没有中断过记载，国库没有一个月不接受鲁国的贡品。像这样就可以了，何必要损害鲁国而增强杞国？如果先君有知，就宁可让夫人自己去办，又哪里用得着我老臣？”
杞文公来鲁国结盟，《春秋》称他为“子”，这是表示对他不尊重。
吴国的公子札来鲁国聘问，见到叔孙穆子，很喜欢他。对穆子说：“您恐怕不得善终吧！喜欢善良而不能够选择贤人，我听说君子应当致力选择贤人。您做鲁国的宗卿而主持国政，不慎重举拔善人，怎么能受得了呢？祸患必然到您身上。”
公子札请求聆听观看周朝的音乐和舞蹈。于是让乐工为他歌唱《周南》、《召南》。季扎说：“美啊！王业开始奠定基础了，还没有完善，然而百姓勤劳而不怨恨了。”为他歌唱《邶风》、《邶风》、《卫风》之歌，他说：“美好又深沉啊！忧愁而不困惑。我听说卫康叔、武公的德行就像这样，这大概就是《卫风》吧！”为他歌唱《王风》之歌，他说：“美啊！思虑而不恐惧，大概是周室东迁以后的音乐吧！”为他歌唱《郑风》之歌，他说：“美啊！但是它琐碎得太过分了，百姓不堪忍受了。这大概是郑国要先灭亡的原因吧！”为他歌唱《齐风》之歌，他说：“美啊，多么宏大的声音呵！这是大国的音乐啊！作为东海的表率的，大概是太公的国家吧！国家前途是不可限量的。”为他歌唱《豳风》之歌，他说：“美啊，浩荡博大呵！欢乐而不过度，大概是周公东征的音乐吧！”为他歌唱《秦风》之歌，他说：“这就叫做西方的夏声。夏就是大，大到极点了，恐怕是周朝的旧乐吧！”为他歌唱《魏风》，他说：“美啊！抑扬顿挫呵！宏亮而又婉转，艰难而流畅，再用德行加以辅助，就是贤明的君主了。”为他歌唱《唐风》，他说：“思虑很深啊！大概有陶唐氏的遗民吧？否则，为什么那么忧深思远呢？不是美德者的后代，谁能像这样？”为他歌唱《陈风》，他说：“国家没有主人，难道能够长久吗？”从《郐风》以下的诗歌，季扎听了就没有评论了。乐师为他歌唱《小雅》，他说：“美啊！忧愁而没有背叛的心，怨恨却不表现在语言中，恐怕是周朝德行衰微的乐章吧！还有先王的遗民啊。”为他歌唱《大雅》，他说：“广博啊，和美呵！抑扬顿挫而本体刚健劲直，大概是文王的德行吧！”为他歌唱《颂》，他说：“到达顶点了！正直而不倨傲，婉柔而不屈挠，亲近而不相逼，疏远而不离心，活泼而不邪乱，反复而不厌倦，哀伤而不忧愁，欢乐而不过度，常用而不匮乏，宽广而不显露，施舍而不浪费，收取而不贪婪，静止而不停滞，行进而不流荡。五声和谐，八风协调。节奏有一定的规律，乐器都按次序，这都是盛德之人所共同具有的。”
公子札看到跳《象箾》、《南籥》舞，说：“美啊，但还有所遗憾。”看到跳《大武》舞，说：“美啊！周朝兴盛的时候，大概就像这种情况吧！”看到跳《韶濩》舞，说：“像圣人那样的弘大，尚且还有所惭愧，可见当圣人不容易啊！”看到跳《大夏》舞，说：“美啊！勤劳而不自以为有德，如果不是禹，还有谁能做到呢？”看到跳《韶箾》舞，说：“功德到达顶点了，伟大啊！像上天的没有不覆盖，像大地的没有不承载。盛德到达顶点，就不能再比这更有所增加了，聆听观看就到这里了。如果还有别的音乐，我不敢再请求欣赏了。”
公子札的出国聘问，是为了新立的国君通好的缘故，因此就到齐国聘问，喜欢晏平仲，对他说：“您赶快交还封邑和政权。没有封邑没有政权，这才能免于祸难。齐国的政权将会有所归属，没有得到归属，祸难不会停止。”所以晏子通过陈桓子交还了政权和封邑，因为这样，而免于栾氏、高氏发动的祸难。
季扎到郑国聘问，见了子产，好像老朋友一般。季扎给子产赠送白绢大带，子产给季扎献上麻布衣服，公子札对子产说：“郑国的执政者奢侈，祸难将要来临了！政权必然落到您手中。您执政，要用礼来谨慎地处事。否则，郑国将会败亡。”
季扎到达卫国，与蘧瑗、史狗、史？、公子荆、公叔发、公子朝谈得很投机，他说：“卫国有很多贤能的君子，不会有什么祸患。”
公子札从卫国去晋国，准备在戚地住宿。听到钟声，说：“奇怪啊！我听说了，发动变乱而没有德行，必然遭到诛戮。这一位就在这地方得罪国君，害怕还来不及，又有什么可以寻欢作乐的？这一位在这地方，就像燕子在帐幕上做窝。国君又正停棺还没有安葬，难道可以寻欢作乐吗？”于是就不住在戚地。孙文子听到了这番话，一辈子不再听音乐。
公子札到了晋国，喜爱赵文子、韩宣子、魏献子，说：“晋国的政权大约要聚集在这三家了！”他喜爱叔向，离别时，对叔向说：“您努力吧！国君奢侈而优秀的臣子很多，大夫都富有，政权将要归于大夫家。您好直话直说，一定要考虑使自己免于祸难。”
秋季，九月，齐国的公孙虿、公孙灶放逐他们的大夫高止到北燕。初二日，出国。《春秋》记载说“出奔”，这是由于高止有罪。高止喜欢生事，而且自己居功，同时又专横，所以祸难到了他身上。
冬季，孟孝伯去到晋国，这是回报范叔的聘问。
由于高氏受到放逐的缘故，高竖在卢地发动叛乱。十月二十七日，闾丘婴带兵包围卢地。高竖说：“如果让高氏有后代，我请求把封邑交还给国君。”齐国人立了敬仲的曾孙酀，这是认为敬仲贤良。十一月二十三日，高竖归还卢地而逃亡到晋国，晋国人在绵地筑城，把他安置在那里。
郑国的伯有派公孙黑去楚国，公孙黑不肯去，说：“楚国和郑国正在关系不好，互相憎恨，而派我去，这是等于杀死我。”伯有说：“你家世世代代都是办外交的。”公孙黑说：“可以去就去，有困难就不去，有什么世世代代是办外交的。”伯有要强迫他去。公孙黑发怒，准备攻打伯有氏，大夫们为他们调和。十二月初七日，郑国的大夫们在伯有家里结盟。裨谌说：“这次结盟，它能管多久呢？《诗》说：‘君子多次结盟，动乱因此滋长。’现在这样是滋长动乱的做法，祸乱不能停止，一定要三年然后才能解除。”然明说：“政权将会到哪家去？”裨谌说：“好人代替坏人，这是天命，政权哪能避开子产？如果不是越级提拔别人，那么按班次也应该子产执政了。选择贤人而提拔，这是为大家所尊重的。上天又为子产清除障碍，使伯有丧失了精神，子西又去世了，执政的人只有子产不能辞其责。上天降祸于郑国很久了，一定要让子产平息它，国家才可以安定。不这样，就将会灭亡了。”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b68ea30675327e1250707", "shortContent": "襄公二十五年（前548年）《经》《左传》，主要记齐国事，此外，还叙郑伐陈，楚灭舒鸠、楚吴之战等史实。《左传》本年所记齐事，始于崔杼娶同姓女棠姜；继而崔杼因齐庄公与棠姜私通而弑君，并连杀二史官；再述庄公死后齐国局势及庄公之葬；最后记载晋率诸侯伐齐及齐屈服的事件。\n\n忠君是西周礼制的基本要求，弑君被视为罪大恶极之事，绝对禁止。但是在社会大变动的春秋时代，礼崩乐坏，各国内乱层出不穷，弑君之事时常发生，《...", "authors": ["贺圣迪", "魏自厚"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b68727f27182da3eea61c", "shortContent": "襄公三年（前570年），《经》《左传》所叙，以盟会为多，而突出祈奚举贤和魏绛戮扬干之仆。\n\n祁奚，晋国人，任职中军尉，因年迈体弱请求告老退休。晋悼公让他荐举继任者，他提名其仇人解狐，可是后者将被任命之时不幸去世。晋悼公又问祁奚，还有谁能担任此职，祁奚提出他的儿子祁午能够胜任。恰好此时祁奚的副手羊舌职也死去，在悼公让他推荐接替人选时，他说羊舌职的儿子羊舌赤堪当此任。这样，悼公就任祁午为中军尉，羊舌赤...", "authors": ["贺圣迪", "魏自厚"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b6932a5f1e74f95ea233c", "shortContent": " 季子所属的吴国是周初太王子太伯、仲雍让位出逃至今太湖地区，与当地居民吴人结合所建立的国家。仲雍后世子孙虽在康王时接受周室的封号，但由于家族历史上的矛盾，地域相距遥远，有大江相隔，始终不曾认真地视周王为天子，也不遵行其所颁行的礼乐征伐，而自乐于当地习俗之中。春秋时期，由于中原与太湖地区政治联系的加强，经济、文化的发展与交流，尤其是中原华夏文化对太湖地区的深刻影响，吴国统治集团认为有必要进一步加强与...", "authors": ["贺圣迪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559126077, '5cedefb9ba39c80068966288', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643048, '左传 · 襄公 · 襄公三十年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三十年春王正月，楚子使薳罢来聘。夏四月，蔡世子般弑其君固。五月甲午。宋灾。宋伯姬卒。天王杀其弟佞夫。王子瑕奔晋。秋七月，叔弓如宋，葬宋共姬。郑良霄出奔许，自许入于郑，郑人杀良霄。冬十月，葬蔡景公。晋人、齐人、宋人、卫人、郑人、曹人、莒人、邾人、滕子、薛人、杞人、小邾人会于澶渊，宋灾故。
【传】三十年春，王正月，楚子使薳罢来聘，通嗣君也。穆叔问：「王子之为政何如？」对曰：「吾侪小人，食而听事，犹惧不给命而不免于戾，焉与知政？」固问焉，不告。穆叔告大夫曰：「楚令尹将有大事，子荡将与焉，助之匿其情矣。」
子产相郑伯以如晋，叔向问郑国之政焉。对曰：「吾得见与否，在此岁也。驷、良方争，未知所成。若有所成，吾得见，乃可知也。」叔向曰：「不既和矣乎？」对曰：「伯有侈而愎，子皙好在人上，莫能相下也。虽其和也，犹相积恶也，恶至无日矣。」
三月癸未，晋悼夫人食舆人之城杞者。绛县人或年长矣，无子，而往与于食。有与疑年，使之年。曰：「臣小人也，不知纪年。臣生之岁，正月甲子朔，四百有四十五甲子矣，其季于今三之一也。」吏走问诸朝，师旷曰：「鲁叔仲惠伯会郤成子于承匡之岁也。是岁也，狄伐鲁。叔孙庄叔于是乎败狄于咸，获长狄侨如及虺也豹也，而皆以名其子。七十三年矣。」史赵曰：「亥有二首六身，下二如身，是其日数也。」士文伯曰：「然则二万六千六百有六旬也。」
赵孟问其县大夫，则其属也。召之，而谢过焉，曰：「武不才，任君之大事，以晋国之多虞，不能由吾子，使吾子辱在泥涂久矣，武之罪也。敢谢不才。」遂仕之，使助为政。辞以老。与之田，使为君复陶，以为绛县师，而废其舆尉。于是，鲁使者在晋，归以语诸大夫。季武子曰：「晋未可媮也。有赵孟以为大夫，有伯瑕以为佐，有史赵、师旷而咨度焉，有叔向、女齐以师保其君。其朝多君子，其庸可媮乎？勉事之而后可。」
夏四月己亥，郑伯及其大夫盟。君子是以知郑难之不已也。
蔡景侯为大子般娶于楚，通焉。大子弑景侯。
初，王儋季卒，其子括将见王，而叹。单公子愆期为灵王御士，过诸廷，闻其叹而言曰：「乌乎！必有此夫！」入以告王，且曰：「必杀之！不戚而愿大，视躁而足高，心在他矣。不杀，必害。」王曰：「童子何知？」及灵王崩，儋括欲立王子佞夫，佞夫弗知。戊子，儋括围蒍，逐成愆。成愆奔平畦。五月癸巳，尹言多、刘毅、单蔑、甘过、巩成杀佞夫。括、瑕、廖奔晋。书曰「天王杀其弟佞夫。」罪在王也。
或叫于宋大庙，曰：「譆，譆！出出！」鸟鸣于亳社，如曰：「譆譆。」甲午，宋大灾。宋伯姬卒，待姆也。君子谓：「宋共姬，女而不妇。女待人，妇义事也。」
六月，郑子产如陈莅盟。归，覆命。告大夫曰：「陈，亡国也，不可与也。聚禾粟，缮城郭，恃此二者，而不抚其民。其君弱植，公子侈，大子卑，大夫敖，政多门，以介于大国，能无亡乎？不过十年矣。」
秋七月，叔弓如宋，葬共姬也。
郑伯有耆酒，为窟室，而夜饮酒击钟焉，朝至未已。朝者曰：「公焉在？」其人曰：「吾公在壑谷。」皆自朝布路而罢。既而朝，则又将使子皙如楚，归而饮酒。庚子，子皙以驷氏之甲伐而焚之。伯有奔雍梁，醒而后知之，遂奔许。大夫聚谋，子皮曰：「《仲虺之志》云：『乱者取之，亡者侮之。推亡固存，国之利也。』罕、驷、丰同生。伯有汰侈，故不免。」
人谓子产：「就直助强！」子产曰：「岂为我徒？国之祸难，谁知所儆？或主强直，难乃不生。姑成吾所。」辛丑，子产敛伯有氏之死者而殡之，不乃谋而遂行。印段从之。子皮止之，众曰：「人不我顺，何止焉？」子皮曰：「夫人礼于死者，况生者乎？」遂自止之。壬寅，子产入。癸卯，子石入。皆受盟于子皙氏。乙巳，郑伯及其大夫盟于大宫。盟国人于师之梁之外。
伯有闻郑人之盟己也，怒。闻子皮之甲不与攻己也，喜。曰：「子皮与我矣。」癸丑，晨，自墓门之渎入，因马师颉介于襄库，以伐旧北门。驷带率国人以伐之。皆召子产。子产曰：「兄弟而及此，吾从天所与。」伯有死于羊肆，子产襚之，枕之股而哭之，敛而殡诸伯有之臣在市侧者。既而葬诸斗城。子驷氏欲攻子产，子皮怒之曰：「礼，国之干也，杀有礼，祸莫大焉。」乃止。
于是游吉如晋还，闻难不入，覆命于介。八月甲子，奔晋。驷带追之，及酸枣。与子上盟，用两珪质于河。使公孙肸入盟大夫。己巳，复归。书曰「郑人杀良霄。」不称大夫，言自外入也。
于子蟜之卒也，将葬，公孙挥与裨灶晨会事焉。过伯有氏，其门上生莠。子羽曰：「其莠犹在乎？」于是岁在降娄，降娄中而旦。裨灶指之曰：「犹可以终岁，岁不及此次也已。」及其亡也，岁在娵訾之口。其明年，乃及降娄。
仆展从伯有，与之皆死。羽颉出奔晋，为任大夫。鸡泽之会，郑乐成奔楚，遂适晋。羽颉因之，与之比，而事赵文子，言伐郑之说焉。以宋之盟故，不可。子皮以公孙锄为马师。
楚公子围杀大司马蒍掩而取其室。申无宇曰：「王子必不免。善人，国之主也。王子相楚国，将善是封殖，而虐之，是祸国也。且司马，令尹之偏，而王之四体也。绝民之主，去身之偏，艾王之体，以祸其国，无不祥大焉！何以得免？」
为宋灾故，诸侯之大夫会，以谋归宋财。冬十月，叔孙豹会晋赵武、齐公孙虿、宋向戌、卫北宫佗、郑罕虎及小邾之大夫，会于澶渊。既而无归于宋，故不书其人。
君子曰：「信其不可不慎乎！澶渊之会，卿不书，不信也夫！诸侯之上卿，会而不信，宠名皆弃，不信之不可也如是！《诗》曰：『文王陟降，在帝左右。』信之谓也。又曰：『淑慎尔止，无载尔伪。』不信之谓也。」书曰「某人某人会于澶渊，宋灾故。」尤之也。不书鲁大夫，讳之也。
郑子皮授子产政，辞曰：「国小而逼，族大宠多，不可为也。」子皮曰：「虎帅以听，谁敢犯子？子善相之，国无小，小能事大，国乃宽。」
子产为政，有事伯石，赂与之邑。子大叔曰：「国，皆其国也。奚独赂焉？」子产曰：「无欲实难。皆得其欲，以从其事，而要其成，非我有成，其在人乎？何爱于邑？邑将焉往？」子大叔曰：「若四国何？」子产曰：「非相违也，而相从也，四国何尤焉？《郑书》有之曰：『安定国家，必大焉先。』姑先安大，以待其所归。」既，伯石惧而归邑，卒与之。伯有既死，使大史命伯石为卿，辞。大史退，则请命焉。覆命之，又辞。如是三，乃受策入拜。子产是以恶其为人也，使次己位。
子产使都鄙有章，上下有服，田有封洫，庐井有伍。大人之忠俭者，从而与之。泰侈者，因而毙之。
丰卷将祭，请田焉。弗许，曰：「唯君用鲜，众给而已。」子张怒，退而征役。子产奔晋，子皮止之而逐丰卷。丰卷奔晋。子产请其田里，三年而复之，反其田里及其入焉。
从政一年，舆人诵之，曰：「取我衣冠而褚之，取我田畴而伍之。孰杀子产，吾其与之！」及三年，又诵之，曰；「我有子弟，子产诲之。我有田畴，子产殖之。子产而死，谁其嗣之？」', '', '', '三十年春季，周王朝历法的正月，楚王郏敖派遣薳罢来鲁国聘问，这是为新立的国君通好。穆叔问：“王子围执政的情况怎么样？”薳罢回答说：“我辈小人吃饭听使唤，还害怕不足以完成使命而不能免于罪过，哪里能参与政事？”再三地询问，他还是不回答。穆叔告诉大夫说：“楚国的令尹将要发动大乱，薳罢将参与协助，他在隐瞒情况。”
子产辅助郑简公而去到晋国，叔向问起郑国的政事。子产回答说：“我能不能见到，就在这一年了。驷氏、良氏正在争夺，不知道怎么调和。如果能调和，我能够见到，这就可以知道了。”叔向说：“不是已经和好了吗？”子产回答说：“伯有奢侈倔强而又固执，子皙喜欢居于别人之上，两人互不相让，虽然他们已经和好，还是积聚了憎恶，不久就会爆发。”
二月二十二日，晋悼公夫人请为杞国筑城的役卒吃饭。绛县人中间有一个人年纪很大了，没有儿子而自己服役，也去接受夫人的饭食。有人怀疑他的年龄，让他说出自己的年龄。他说：“下臣，是小人，不知道记录年龄。下臣生的那一年，是正月初一甲子日，已经过了四百四十五个甲子日了，最末一个甲子日到今天正好是二十天。”官吏走到朝廷里询问，师旷说：“这是鲁国的叔仲惠伯在承筐会见郤成子的那一年。这一年，狄人进攻鲁国，叔孙庄叔当时在碱地打败狄人，俘虏了长狄侨如和虺、豹，而都用来命名他儿子。满七十三岁了。”史赵说：“亥字是‘二’字头‘六’字身，把‘二’拿下来当作身子，这就是他的日子数。”士文伯说：“那么是二万六千六百六十天了。”
赵孟问起老人的县大夫是谁，原来就是他的下属。赵孟把老人召来向他道歉，说：“武没有才能，担负了国君的重要职务，由于晋国多有忧患，没有能任用您，让您屈居卑下已经很久了，这是武的罪过。谨由于没有才能而向您道歉。”于是就任命老人做官，派他辅助自己执政。老人因年纪大了而辞谢，赵孟就给了他土地，让他为国君办理免除徭役的事务，做绛地县师，而撤除了他的舆尉的职务。
当时鲁国的使臣正在晋国，回去把这件事告诉了大夫们。季武子说：“晋国不能轻视啊。有赵孟做正卿，有伯瑕做辅佐，有史赵、师旷可以咨询，有叔向、女齐做国君的师保。他们朝廷上君子很多，哪里能够轻视呢？尽力事奉他们然后才可以。”
夏季四月某一天，郑简公和他的大夫结盟。君子因此而知道郑国的祸难还没有结束。
蔡景侯为太子般在楚国娶妻，又和儿媳妇私通。太子杀死了蔡景侯。
当初，周灵王的弟弟儋季死了，他的儿子括将要进见灵王，叹气。单国的公子愆期做灵王侍卫，经过朝廷，听到叹气声，就说：“啊，一定是想夺取朝廷的权！”进去把情况报告灵王，而且说：“一定要杀了他！他不悲哀而愿望大，目光到处张望而抬高脚，心在其他地方了。不杀，必然造成危害。”灵王说：“小孩子知道什么？等到灵王死去，儋括想要立王子佞夫。佞夫不知道。二十八日，儋括包围苏地，赶走成愆。成愆逃亡到平畤。五月初四日，尹言多、刘毅、单蔑、甘过、巩成杀了佞夫。括、瑕、廖逃亡到晋国。《春秋》记载说“天王杀死他的兄弟佞夫”，这是由于罪过在于周王。
有人在宋国太庙里大喊大叫，说：“嘻嘻，出出。”鸟在亳社上鸣叫，声音好像在说：“嘻嘻。”五月初五日，宋国发生大火灾。宋伯姬被烧死，这是为了等待保姆来。君子认为：“宋伯姬奉行的是大闺女而不是媳妇的守则。大闺女应当等待保姆，媳妇就可以看具体情况行事。”
六月，郑国的子产去到陈国参加结盟，回来，复命。告诉大夫们说：“陈国，是要灭亡的国家，不能结好。他们积聚粮食，修理城郭，靠了这两条而不安抚百姓，他们的国君根基不巩固，公子奢侈，太子卑微，大夫骄傲，政事各行其是，谁也作不了主，在这种情况下处于大国之间，能够不灭亡吗？不超过十年了。”
秋季，七月，叔弓去到宋国，这是由于安葬共姬。
郑国的伯有喜欢喝酒，造了地下室，并在夜里喝酒，奏乐。朝见的人来到，他还没有喝完酒。朝见的人说：“主人在哪里？”他的手下人说：“我们的主人在地下室。”朝见的人都分路回去。不久伯有去朝见郑伯，又要派子皙去楚国，回家以后又喝酒。七月十一日，子皙带者驷氏的甲士攻打并且放火烧了他的家。伯有逃亡到雍梁，酒醒以后才明白是怎么回事，于是又逃亡到许国。大夫们聚在一起商量。子皮说：“《仲虺之志》说：‘动乱的就攻取它，灭亡的就欺侮它。’摧毁灭亡的而巩固存在的，这是国家的利益。罕氏、驷氏、丰氏本来是同胞兄弟，伯有骄傲奢侈，所以不免于祸难。”
有人对子产说：“要靠拢正直的帮助强大的。”子产说：“他们难道是我的同伙？国家的祸难，谁知道如何平定？如果有主持国政的人强大而且正直，祸难就不会发生。姑且保住我的地位吧。”十二日，子产收了伯有氏死者的尸体而加以殡葬，来不及和大夫们商量就出走了。印段跟从他。子皮不让他走。大家说：“别人不顺从我们，为什么不让他走？”子皮说：“这个人对死去的人有礼，何况对活着的人呢？”于是就亲自劝阻子产。十三日，子产进入国都。十四日，印段进入国都。两个人都在子皙家里接受了盟约。十六日，郑简公和他的大夫们在太庙结盟，又与国内的人们在郑国城门外结盟。
伯有听到郑国人为他结盟，很生气；听到子皮的甲士没有参加攻打他，很高兴，说：“子皮帮助我了。”二十四日，从墓门的排水洞进入，靠着马师颉用襄库的兵甲装备士兵，带着他们攻打旧北门。驷带率领国内的人们攻打伯有。两家都召请子产。子产说：“兄弟之间到达这地步，我服从上天所要帮助的一家。”伯有死在买卖羊的街市上，子产给伯有的尸体穿上衣服，头枕在尸体的大腿上而为他号哭，收尸并把棺材停放在街市旁边伯有家臣的家里，不久又葬在斗城。驷氏想要攻打子产。子皮为这发怒，说：“礼仪，是国家的支柱。杀死有礼的人，没有比这再大的祸患了。”于是就停止了。
当时，游吉去晋国以后回来，听说发生祸难，不进入。让副手回来复命。八月初六日，逃亡到晋国。驷带追赶他，到达酸枣。游吉和驷带结盟，把两件玉圭沉在黄河里表示诚意。让公孙肸进入国都和大夫结盟。十一日，游吉再次回到国内。《春秋》记载说：“郑人杀良霄。”不称他为大夫，这是说伯有从国外进来已经丧失官位了。
当子蟜死了以后，将要安葬时，公孙挥和裨灶早晨商量丧事。他们路过伯有氏家时，看见门上长了狗尾草，公孙挥说：“他门上的狗尾巴草还在吗？”当时岁星在降娄，降娄星在天空中部，天就亮了。裨灶指着降娄星，说：“还可以等岁星绕一周，不过活不到岁星再到这个位置就是了。”等到伯有被杀，岁星正在娵訾的口上，明年才能到达降娄。
仆展跟从伯有，和他一起死了。羽颉逃亡到晋国，做了任邑的长官。鸡泽的会见，郑国的乐成逃亡到楚国，就乘机去到晋国。羽颉靠着他，和他勾结着一起奉事赵文子，提出了进攻郑国的建议。由于有宋国盟誓的缘故，赵文子不同意这项建议。子皮让公孙锄代替羽颉做了马师。
楚国的公子围杀了大司马？掩而占取了他的家财。申无宇说：“王子必然不能免于祸难。善人，是国家的栋梁。王子辅助楚国的政事，应该培养好人，现在反倒对他们暴虐，这是危害国家。而且司马，是令尹的辅佐，也是国君的手足。断绝百姓的栋梁，去掉自己的辅佐，斩除国君的手足，以危害国家，没有比这再大的不吉利了。怎么能免于祸难呢？”
为了宋国火灾的缘故，诸侯的大夫会见，商量给宋国赠送财货。冬季十月，叔孙豹和晋国赵武、齐国的公孙虿、宋国的向戌、卫国的北宫佗、郑国的罕虎以及小邾国的大夫在澶渊会见，并没有给宋国赠送什么东西，所以《春秋》没有记载与会者的姓名。
君子说：“信用恐怕不能不谨慎吧！澶渊的会见，不记载卿的名字，这是由于不守信用的缘故。诸侯的上卿，会见了又不守信用，他们尊贵的姓名全都丢掉了，不守信用是这样的不可以啊。《诗》说，‘文王或升或降，都是在天帝的左右’，这是说要守信义。又说，‘好好地谨慎你的行动，不要表现你的虚伪’，这是说不守信义。”《春秋》记载说“某人某人会于澶渊，宋灾故”，这是为了责备他们。不记载鲁国的大夫，这是由于为他隐瞒。
郑国的子皮把政权交给子产，子产辞谢说：“国家小而逼近大国，家族庞大而受宠的人又多，我不能治理好。”子皮说：“虎率领他们听从，谁敢触犯您？您好好地辅助国政吧。国家不在于小，小国能够事奉大国，国家就可以不受逼迫了。”
子产治理政事，有事情要伯石去办，赠送给他城邑，子太叔说：“国家是大家的国家，为什么独给他送东西？”子产说：“要没有欲望确实是难的。使他们都满足欲望，去办他们的事情而取得成功。这不是我的成功，难道是别人的成功吗？对城邑有什么爱惜的，它会跑到哪里去？”子太叔说：“四方邻国将怎么看待？”子产说：“这样做不是为了互相违背，而是为了互相顺从，四方的邻国对我们有什么可责备的？《郑书》有这样的话：‘安定国家，一定要优先照顾大族。’姑且先照顾大族，再看它归向何处。”不久，伯石恐惧而把封邑归还，最终子产还是把城邑给了他。伯有死了以后，郑简公让太史去命令伯石做卿，伯石辞谢。太史退出，伯石又请求太史重新发布命令，命令下来了再次辞谢。像这样一连三次，这才接受策书入朝拜谢。子产因此讨厌伯石的为人，但担心他作乱，就让他居于比自己低一级的地位。
子产让城市和乡村有所区别，上下尊卑各有职责，田土四界有水沟，庐舍和耕地能互相适应。对卿大夫中忠诚俭朴的，听从他，亲近他；骄傲奢侈的，推翻他。
丰卷准备祭祀，请求猎取祭品。子产不答应，说：“只有国君祭祀才用新猎取的野兽，一般人只要大致足够就可以了。”丰卷生气，退出以后就召集士兵。子产准备逃亡到晋国，子皮阻止他而驱逐了丰卷。丰卷逃亡到晋国，子产请求不要没收他的田地住宅，三年以后让丰卷回国复位，把他的田地住宅和一切收入都退还给他。
子产参与政事一年，人们歌唱道：“计算我的家产而收财物税，丈量我的耕地而征收田税。谁杀死子产，我就帮助他。”到了三年，又歌唱道：“我有子弟，子产教诲；我有土田，子产使之增产。万一子产逝世谁来接替他呢？”', NULL, '', 'indent', 1559126152, '5cedf00430863b00685546c4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643049, '左传 · 襄公 · 襄公三十一年 ', NULL, 4, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三十有一年春王正月。夏六月辛巳，公薨于楚宫。秋九月癸巳，子野卒。己亥，仲孙羯卒。冬十月，滕子来会葬。癸酉，葬我君襄公。十有一月，莒人杀其君密州。
【传】三十一年春，王正月，穆叔至自会，见孟孝伯，语之曰：「赵孟将死矣。其语偷，不似民主。且年未盈五十，而谆谆焉如八九十者，弗能久矣。若赵孟死，为政者其韩子乎！吾子盍与季孙言之，可以树善，君子也。晋君将失政矣，若不树焉，使早备鲁，既而政在大夫，韩子懦弱，大夫多贪，求欲无厌，齐、楚未足与也，鲁其惧哉！」孝伯曰：「人生几何？谁能无偷？朝不及夕，将安用树？」穆叔出而告人曰：「孟孙将死矣。吾语诸赵孟之偷也，而又甚焉。」又与季孙语晋故，季孙不从。
及赵文子卒，晋公室卑，政在侈家。韩宣子为政，为能图诸侯。鲁不堪晋求，谗慝弘多，是以有平丘之会。
齐子尾害闾丘婴，欲杀之，使帅师以伐阳州。我问师故。夏五月，子尾杀闾丘婴以说于我师。工偻洒、渻灶、孔虺、贾寅出奔莒。出群公子。
公作楚宫。穆叔曰：「《大誓》云：『民之所欲，天必从之。』君欲楚也夫！故作其宫。若不复适楚，必死是宫也。」六月辛巳，公薨于楚宫。叔仲带窃其拱璧，以与御人，纳诸其怀而从取之，由是得罪。
立胡女敬归之子子野，次于季氏。秋九月癸巳，卒，毁也。
己亥，孟孝伯卒。
立敬归之娣齐归之子公子裯，穆叔不欲，曰：「大子死，有母弟则立之，无则长立。年钧择贤，义钧则卜，古之道也。非适嗣，何必娣之子？且是人也，居丧而不哀，在戚而有嘉容，是谓不度。不度之人，鲜不为患。若果立之，必为季氏忧。」武子不听，卒立之。比及葬，三易衰，衰衽如故衰。于是昭公十九年矣，犹有童心，君子是以知其不能终也。
冬十月，滕成公来会葬，惰而多涕。子服惠伯曰：「滕君将死矣！怠于其位，而哀已甚，兆于死所矣。能无从乎？」癸酉，葬襄公。
公薨之月，子产相郑伯以如晋，晋侯以我丧故，未之见也。子产使尽坏其馆之垣而纳车马焉。士文伯让之，曰：「敝邑以政刑之不修，寇盗充斥，无若诸侯之属辱在寡君者何？是以令吏人完客所馆，高其□闳，厚其墙垣，以无忧客使。今吾子坏之，虽从者能戒，其若异客何？以敝邑之为盟主，缮完葺墙，以待宾客，若皆毁之，其何以共命？寡君使□请命。」对曰：「以敝邑褊小，介于大国，诛求无时，是以不敢宁居，悉索敝赋，以来会时事。逢执之不间，而未得见，又不获闻命，未知见时，不敢输币，亦不敢暴露。其输之，则君之府实也，非荐陈之，不敢输也。其暴露之，则恐燥湿之不时而朽蠹，以重敝邑之罪。侨闻文公之为盟主也，宫室卑庳，无观台榭，以崇大诸侯之馆。馆如公寝，库厩缮修，司空以时平易道路，圬人以时塓馆宫室。诸侯宾至，甸设庭燎，仆人巡宫，车马有所，宾从有代，巾车脂辖，隶人牧圉，各瞻其事，百官之属，各展其物。公不留宾，而亦无废事，忧乐同之，事则巡之，教其不知，而恤其不足。宾至如归，无宁灾患？不畏寇盗，而亦不患燥湿。今铜鞮之宫数里，而诸侯舍于隶人。门不容车，而不可逾越。盗贼公行，而天厉不戒。宾见无时，命不可知。若又勿坏，是无所藏币，以重罪也。敢请执事，将何以命之？虽君之有鲁丧，亦敝邑之忧也。若获荐币，修垣而行，君之惠也，敢惮勤劳？」文伯覆命，赵文子曰：「信！我实不德，而以隶人之垣以赢诸侯，是吾罪也。」使士文伯谢不敏焉。晋侯见郑伯，有加礼，厚其宴好而归之。乃筑诸侯之馆。
叔向曰：「辞之不可以已也如是夫！子产有辞，诸侯赖之，若之何其释辞也？《诗》曰：『辞之辑矣，民之协矣。辞之绎矣，民之莫矣。』其知之矣。」
郑子皮使印段如楚，以适晋告，礼也。
莒犁比公生去疾及展舆，既立展舆，又废之。犁比公虐，国人患之。十一月，展舆因国人以攻莒子，弑之，乃立。去疾奔齐，齐出也。展舆，吴出也。书曰「莒人弑其君买朱锄。」言罪之在也。
吴子使屈狐庸聘于晋，通路也。赵文子问焉，曰：「延州来季子其果立乎？巢陨诸樊，阍戕戴吴，天似启之，何如？」对曰：「不立。是二王之命也，非启季子也。若天所启，其在今嗣君乎！甚德而度，德不失民，度不失事，民亲而事有序，其天所启也。有吴国者，必此君之子孙实终之。季子，守节者也。虽有国，不立。」
十二月，北宫文子相卫襄公以如楚，宋之盟故也。过郑，印段廷劳于棐林，如聘礼而以劳辞。文子入聘。子羽为行人，冯简子与子大叔逆客。事毕而出，言于卫侯曰：「郑有礼，其数世之福也，其无大国之讨乎！《诗》曰：『谁能执热，逝不以濯。』礼之于政，如热之有濯也。濯以救热，何患之有？」
子产之从政也，择能而使之。冯简子能断大事，子大叔美秀而文，公孙挥能知四国之为，而辨于其大夫之族姓、班位、贵贱、能否，而又善为辞令，裨谌能谋，谋于野则获，谋于邑则否。郑国将有诸侯之事，子产乃问四国之为于子羽，且使多为辞令。与裨谌乘以适野，使谋可否。而告冯简子，使断之。事成，乃授子大叔使行之，以应对宾客。是以鲜有败事。北宫文子所谓有礼也。
郑人游于乡校，以论执政。然明谓子产曰：「毁乡校，何如？」子产曰：「何为？夫人朝夕退而游焉，以议执政之善否。其所善者，吾则行之。其所恶者，吾则改之。是吾师也，若之何毁之？我闻忠善以损怨，不闻作威以防怨。岂不遽止，然犹防川，大决所犯，伤人必多，吾不克救也。不如小决使道。不如吾闻而药之也。」然明曰：「蔑也今而后知吾子之信可事也。小人实不才，若果行此，其郑国实赖之，岂唯二三臣？」
仲尼闻是语也，曰：「以是观之，人谓子产不仁，吾不信也。」
子皮欲使尹何为邑。子产曰：「少，未知可否？」子皮曰：「愿，吾爱之，不吾叛也。使夫往而学焉，夫亦愈知治矣。」子产曰：「不可。人之爱人，求利之也。今吾子爱人则以政，犹未能操刀而使割也，其伤实多。子之爱人，伤之而已，其谁敢求爱于子？子于郑国，栋也，栋折榱崩，侨将厌焉，敢不尽言？子有美锦，不使人学制焉。大官、大邑，身之所庇也，而使学者制焉，其为美锦，不亦多乎？侨闻学而后入政，未闻以政学者也。若果行此，必有所害。譬如田猎，射御贯则能获禽，若未尝登车射御，则败绩厌覆是惧，何暇思获？」子皮曰：「善哉！虎不敏。吾闻君子务知大者、远者，小人务知小者、近者。我，小人也。衣服附在吾身，我知而慎之。大官、大邑所以庇身也，我远而慢之。微子之言，吾不知也。他日我曰：『子为郑国，我为吾家，以庇焉，其可也。』今而后知不足。自今，请虽吾家，听子而行。」子产曰：「人心之不同，如其面焉。吾岂敢谓子面如吾面乎？抑心所谓危，亦以告也。」子皮以为忠，故委政焉。子产是以能为郑国。
卫侯在楚，北宫文子见令尹围之威仪，言于卫侯曰：「令尹似君矣！将有他志，虽获其志，不能终也。《诗》云：『靡不有初，鲜克有终。』终之实难，令尹其将不免？」公曰：「子何以知之？」对曰：「《诗》云：『敬慎威仪，惟民之则。』令尹无威仪，民无则焉。民所不则，以在民上，不可以终。」公曰：「善哉！何谓威仪？」对曰：「有威而可畏谓之威，有仪而可像谓之仪。君有君之威仪，其臣畏而爱之，则而象之，故能有其国家，令闻长世。臣有臣之威仪，其下畏而爱之，故能守其官职，保族宜家。顺是以下皆如是，是以上下能相固也。《卫诗》曰：『威仪棣棣，不可选也。』言君臣、上下、父子、兄弟、内外、大小皆有威仪也。《周诗》曰：『朋友攸摄，摄以威仪。』言朋友之道，必相教训以威仪也。《周书》数文王之德，曰：『大国畏其力，小国怀其德。』言畏而爱之也。《诗》云：『不识不知，顺帝之则。』言则而象之也。纣囚文王七年，诸侯皆从之囚。纣于是乎惧而归之，可谓爱之。文王伐崇，再驾而降为臣，蛮夷帅服，可谓畏之。文王之功，天下诵而歌舞之，可谓则之，文王之行，至今为法，可谓象之。有威仪也。故君子在位可畏，施舍可爱，进退可度，周旋可则，容止可观，作事可法，德行可像，声气可乐，动作有文，言语有章，以临其下，谓之有威仪也。」', '', '', '三十一年春季，周王朝历法的正月，穆叔从澶渊会见回来，见了孟孝伯，对他说：“赵孟将要死了。他的话毫无远虑，不像百姓的主人。而且年纪不到五十，就絮絮叨叨好像八九十岁的人，他不能活得很长久了。如果赵孟死了，掌握政权的恐怕是韩起吧！您为何不对季孙去说这件事，可以及早建立友好关系，他是个君子。晋国的国君将要失去政权了，如果不去建立友好，让韩子早点为鲁国做些准备工作，不久以后政权落在大夫手里，韩子又懦弱，大夫大多贪婪，要求和欲望没有个止境，齐国、楚国却不足以依靠，鲁国将陷入可怕的困境！”孟孝伯说：“人的一辈子能活多久，谁能说没有点得过且过的思想？早晨活着还怕到不了晚上，哪里用得着去建立友好？”穆叔出去，告诉别人说：“孟孝伯将要死了。我告诉他赵孟的得过且过，但他比赵孟还不如。”又和季孙说到晋国的事情，季孙不听。等到赵文子死了，晋国公室的地位下降，政权落在豪奢的大夫手里。韩宣子掌握国政，不能为诸侯所拥护。鲁国难以担负晋国的要求，奸邪小人很多，因此有了平丘的会见。
齐国的子尾惧怕闾丘婴，想杀死他，派他带兵进攻阳州。我国询问他们为什么要出兵。夏季，五月，子尾杀了闾丘婴，来向我军解释。工偻洒、渻灶、孔虺、贾寅逃亡到莒国。子尾驱逐了公子们。
鲁襄公建造楚国式的宫殿。穆叔说：“《大誓》说：‘百姓所要求的，上天必然听从。’国君想要楚国了，所以建造楚国式的宫殿。如果不再去楚国，必然死在这座宫殿里。”
六月二十八日，鲁襄公死在楚宫里。
叔仲带偷了襄公的大玉璧，给了驾车的人，放在他的怀里，又从他那里拿了过来，因此而得罪。
鲁国拥立胡国女人敬归的儿子子野，住在季氏那里。秋季，九月十一日，子野死，这是由于哀痛过度。
十七日，孟孝伯死了。
鲁国拥立敬归的妹妹齐归生的儿子公子裯为国君。穆叔不愿意，说：“太子死了，有同母兄弟就立他，没有就立年长的。年纪差不多就选择贤能的，贤能又差不多就占卜，这是古代的常规。死去的子野并不是嫡子，何必非要立他母亲的妹妹的儿子？而且这个人，居丧却不哀痛，父母死了反而有喜悦的脸色，这叫做不孝。不孝的人，很少不捣乱的。假如立了他，必然造成季氏的忧患。”季武子不听，结果立了他。等到安葬襄公，三次更换丧服，丧服的衣襟脏得好像旧丧服一样。当时昭公已十九岁了，还有孩子脾气，君子因此知道他不能善终。
冬季，十月，滕成公来鲁国参加葬礼，表现得不恭敬而眼泪很多。子服惠伯说：“滕国的国君将要死了。在他吊临的位置上表现懈怠，而哀痛太过分，在葬礼中已经显出将死的预兆了，能够不相继死吗？”
十月二十一日，安葬鲁襄公。
襄公死去的那一个月，子产陪同郑简公到晋国去，晋平公由于我国有丧事，没有接见。子产派人将晋国宾馆的围墙全部拆毁而安放自己的车马。士文伯责备他，说：“敝邑由于政事和刑罚不够完善，到处都是盗贼，无奈诸侯的属官来向寡君朝聘，因此派官吏修缮宾客所住的馆舍，加高大门，围墙增厚，以不让宾客使者担忧。现在您拆毁了它，虽然您的随从能够自己戒备，让别国的宾客又怎么办呢？由于敝邑是盟主，修缮围墙，为接待宾客。如果都拆毁了，那么将怎么供应宾客的需要呢？寡君派匄前来请问拆墙的意图。”
子产回答说：“由于敝邑地方狭小，夹在大国之间，而大国需索贡品又没有一定的时候，因此不敢安居，尽量搜索敝邑的财富，以便随时来朝会。碰上执事没有空闲，而没有能够见到；又得不到命令，不知道什么时候才能接见。我们不敢献上财币，也不敢让它日晒夜露。如果奉献，那么它就是君王府库中的财物，不经过在庭院里陈列的仪式，就不敢奉献。如果让它日晒夜露，就又害怕时而干燥时而潮湿因而腐朽坏，以加重敝邑的罪过。侨听说晋文公做盟主的时候，宫室矮小，没有可供观望的台榭，而把接待诸侯的宾馆修得又高又大，宾馆好像现在君王的寝宫一样。对宾馆内的库房、马厩都加以修缮，司空及时整修道路，泥瓦工按时粉刷墙壁，诸侯的宾客来了，甸人点起火把，仆人巡逻宫馆。车马有一定的处所，宾客的随从有人替代服役，管理车子的管理员为车轴加油，打扫的人、牧羊人、养马的人各人做自己分内的事情。各部官吏各自陈列他的礼品。文公不让宾客耽搁，也没有因为这样而荒废宾主的公事。和宾客忧乐相同，有事就加以安抚，对宾客所不知道的加以教导，不周到的加以体谅。宾客来到晋国就像在自己家里一样，还有什么灾患？不怕抢劫偷盗，也不担心干燥潮湿。现在铜鞮山的宫室绵延几里，而诸侯住在像奴隶住的屋子里，门口进不去车子，而又不能翻墙而入。盗贼公开行动，而传染病又不能防止。宾客进见诸侯没有一定的时候，君王接见的命令也不知道什么时候才能发布。如果还不拆毁围墙，这就没有地方收藏财礼，反而要加重罪过了。”谨敢问执事，对我们将有什么指示？虽然君王有鲁国的丧事，但这同样也是敝国的忧虑。如果能够奉上财礼，我们愿把围墙修好了再走。这是君王的恩惠，岂敢害怕修墙的辛勤劳动！”
文伯回到朝廷汇报。赵文子说：“说得对。我们实在是不好，用容纳奴隶的房屋去接待诸侯，这是我们的罪过啊。”就派士文伯去表示歉意并说自己无能。晋平公接见郑简公，礼仪有加，举行极隆重的宴会，赠送更加丰厚，然后让他回去。于是就建造接待诸侯的宾馆。叔向说：“辞令的不能废弃就像这样吧！子产善于辞令，诸侯因他而得利，为什么要放弃辞令呢？《诗》说：‘辞令和谐，百姓团结，辞令动听，百姓安定。’他已经懂得这个道理了。”
郑国的子皮派印段去楚国，先到晋国报告这件事，这是合于礼的。
莒犁比公生了去疾和展舆，已经立了展舆，又废了他。犁比公暴虐，国内的人们为此担心。十一月，展舆倚靠国内的人们攻打莒犁比公，杀死了他，就自立为国君。去疾逃亡到齐国，因为他是齐女所生的。展舆是吴女所生，《春秋》记载说“莒人弑其君买朱锄”，这是说罪过在于莒犁比公。
吴王派屈狐庸到晋国聘问，这是为了沟通吴、晋两国交往的道路。赵文子询问他，说：“延州来季子最终能立为国君吗？从前进攻巢地死了诸樊，看门人杀了戴吴，上天似乎为季子打开了做国君的大门，怎么样？”屈狐庸回答说：“不立。这是两位国王的命运不好，不是为季子打开做国君的大门。如果上天打开了大门，恐怕是为了现在的国君吧！他很有德行而又合于法度。有德行就不会失去百姓，合于法度就不会办错事情。百姓亲附而事情有秩序，大概是上天为他打开大门的。保有吴国的，最后一定是这位国君的子孙。季子，是保持节操的人，虽然他应享有国家，也是不愿做国君的。”
十二月，北宫文子陪同卫襄公到楚国去，这是由于在宋国结盟的缘故。经过郑国，印段到棐林去慰劳他们，依照聘问的礼仪，而使用慰劳的辞令。文子进入国都聘问。子羽做行人，冯简子和太叔迎接客人。事情完毕以后文子出来，对卫襄公说：“郑国讲究礼仪，这是几代的福气，恐怕不会有大国去讨伐他吧！《诗》说：‘谁能耐热，不去洗澡。’礼仪对于政事，好像天热得要洗澡一样。洗澡用来消除炎热，有什么可担心的？”
子产参与政事，选择贤能而使用他们。冯简子能决断大事。子太叔外貌秀美而内有文采。子羽能了解四方诸侯的政令而且了解他们大夫的家族姓氏、官职爵位、地位贵贱、才能高低，又善于辞令。裨谌能出谋划策，在野外策划就正确，在城里策划就不得当。郑国将要有外交上的事情，子产就向子羽询问四方诸侯的政令，并且让他写一些有关的外交辞令稿；和裨谌一起坐车到野外去，让他策划是否可行；把结果告诉冯简子，让他决定。计划完成，就交给子太叔执行，交往诸侯应对宾客，所以很少有把事情办坏的时候。这就是北宫文子所说的讲究礼节。
郑国人在乡校里游玩聚会，议论国家政事。然明对子产说：“毁了乡校怎么样？”子产说：“为什么？人们早晚事情完了到那里游玩，来议论政事的好坏。他们认为好的，我就推行它；他们所讨厌的，我就改掉它。这是我的老师。为什么要毁掉它？我听说用忠于为善，能减少怨恨，没有听说用摆出权威能防止怨恨。靠权威难道不能很快制止议论？但是就像防止河水一样：大水来了，伤人必然很多，我不能挽救。不如把水稍稍放掉一点加以疏通，不如让我听到这些话而作为药石。”然明说：“蔑从今以后知道您确实是可以成就大事的。小人实在没有才能。如果终于这样做下去，这确实有利于郑国，岂独有利于二三位大臣？”
孔子听到这些话，说：“从这里来看，别人说子产不仁，我不相信。”
子皮想要让尹何来治理自己的封邑。子产说：“尹何年纪轻，不知道能不能胜任。”子皮说：“这个人谨慎善良，我喜欢他，他不会背叛我的。让他去学习一下，他也就更加知道该怎么办事情了。”子产说：“不行。人家喜欢一个人，总是希望对这个人有利。现在您喜欢一个人却把政事交给他，这好像一个人不会用刀而让他去割东西，多半是要损伤他自己的。您喜欢他，不过是伤害他罢了，有谁还敢在您这里求得喜欢？您对于郑国来说是国家的栋梁。栋梁折断，椽子就会崩塌，侨将会被压在底下，我哪敢不把话全部说出来？您有了漂亮的丝绸，是不会让别人用它来学习裁制的。大官和大的封邑，是庇护自身的，反而让学习的人去裁制，这比起漂亮的丝绸来价值不就多得多吗？侨听说学习以后才能从政，没有听说用从政来学习的。如果真是这么办，一定有所伤害。譬如打猎，熟悉射箭驾车的，就能获得猎物，如果从没有登车射过箭驾过车，那么只担心翻车被压，哪里有闲心想获得猎物？”子皮说：“好啊！虎真是不聪明。我听说君子懂得大的远的，小人只懂得小的近的。我，是小人啊。衣服穿在我身上，我知道而且慎重对待它，大官和大的封邑是用来庇护自身的，我却疏远而且轻视它。要没有您的话，我是不知道的。从前我曾说过，您治理郑国，我治理我的家族以庇护我自己，这就可以了。从今以后才知道这样不行。从现在起我请求，虽然是我家族的事情，也听从您的意见去办理。”子产说：“每个人的想法不一样，好像他的面孔，我难道敢说您的面孔像我的面孔吗？不过心里觉得这样做是危险的，就把它告诉您了。”子皮认为他忠诚，所以把政事全交付给他。子产因此能够执掌郑国大权。
卫襄公在楚国，北宫文子见到楚令尹围的仪表，对卫襄公说：“令尹的言行像国君了，将要有别的想法。虽然能实现这种想法，但是不能善终。《诗》说：‘什么都有个开头，可是很少能有好的结束。’善终实在很难，令尹恐怕要不能免于祸难。”卫襄公说：“你怎么知道？”北宫文子回答说：“《诗》说：‘恭敬而慎重地使用威仪，因为它是百姓的准则。’令尹没有威仪，百姓就没有准则。百姓所不会效法的人，而在百姓之上，就不能善终。”卫襄公说：“好啊！什么叫威仪？”北宫文子回答说：“有威严而使人能害怕叫做威，有仪表而使人能仿效叫做仪。国君有国君的威仪，他的臣子敬畏而爱戴他，把他作为准则而仿效他，所以能保有他的国家，有好名声，传于子孙后代。臣子有臣子的威仪，他的下面害怕而爱护他，所以能保住他的官职，保护家族，使家庭和睦。按照这个次序以下都像这样，因此上下能够互相巩固。《卫诗》说‘威仪安详，好处不能计量’，这是说君臣、上下、父子、兄弟、内外、大小都有威仪。《周诗》说，‘朋友之间互相辅助，所用的就是威仪’，这是说朋友之道一定要用威仪来互相教导。《周书》列举文王的德行，说，‘大国害怕他的力量，小国怀念他的恩德’，这是说对他既害怕而又爱护。《诗》说，‘无知无识，顺着天帝的准则’，这是说把他作为准则而加以仿效。殷纣王囚禁周文王七年，诸侯跟着他去坐牢，纣王于是就害怕而把文王放了回去。可以说是敬爱文王了，文王攻打崇国，两次发兵，崇国就降服为臣，蛮夷相继归服，可以说是害怕文王了。文王的功业，天下赞诵而歌舞，可以说以文王为准则了。文王的措施，到今天还作为法则，可以说是仿效文王了。这是因为有威仪的缘故。所以君子在官位上可使人怕他，施舍可使人爱他，进退可以作为法度，应付得体，容貌举止可以值得观赏，做事情可以让人学习，德行可以作为仿效，声音气度可以使人高兴，举动有修养，说话有条理，用这些来对待下面的人，这就叫做有威仪。”
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b696ae49f46528a4327e6", "shortContent": " 本文所记之事，并非全都发生于鲁襄公三十一年（前542年），其主旨是论述子产能治好郑国的原因。子产姓公孙，名侨，曾平定贵族内乱，郑简公十二年（前554年）为卿，二十三年（前543年）执政，实行改革，整顿贵族田地和农户编制，增加了财政税收，却减轻了普通百姓的负担。他把法律条文铸在鼎上公布，为各国效法。郑处于晋楚两大国之间，动辄得咎，但由于子产内政外交处理得当，相安无事。孔子称赞子产行惠民之政。根据本...", "authors": ["贺圣迪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559126194, '5cedf02f7b968a00767d3f38', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643050, '左传 · 昭公 · 昭公元年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】元年春王正月，公即位。叔孙豹会晋赵武、楚公子围、齐国弱、宋向戌、卫齐恶、陈公子招、蔡公孙归生、郑罕虎、许人、曹人于虢。三月，取郓。夏，秦伯之弟金咸出奔晋。六月丁巳，邾子华卒。晋荀吴帅师败狄于大卤。秋，莒去疾自齐入于莒。莒展舆出奔吴。叔弓帅师疆郓田。葬邾悼公。冬十有一月己酉，楚子麇卒。公子比出奔晋。
【传】元年春，楚公子围聘于郑，且娶于公孙段氏，伍举为介。将入馆，郑人恶之，使行人子羽与之言，乃馆于外。既聘，将以众逆。子产患之，使子羽辞，曰：「以敝邑褊小，不足以容从者，请墠听命！」令尹命大宰伯州犁对曰：「君辱贶寡大夫围，谓围：『将使丰氏抚有而室。围布几筵，告于庄、共之庙而来。若野赐之，是委君贶于草莽也！是寡大夫不得列于诸卿也！不宁唯是，又使围蒙其先君，将不得为寡君老，其蔑以复矣。唯大夫图之！」子羽曰：「小国无罪，恃实其罪。将恃大国之安靖己，而无乃包藏祸心以图之。小国失恃而惩诸侯，使莫不憾者，距违君命，而有所壅塞不行是惧！不然，敝邑，馆人之属也，其敢爱丰氏之祧？」伍举知其有备也，请垂橐而入。许之。
正月乙未，入，逆而出。遂会于虢，寻宋之盟也。祁午谓赵文子曰：「宋之盟，楚人得志于晋。今令尹之不信，诸侯之所闻也。子弗戒，惧又如宋。子木之信称于诸侯，犹诈晋而驾焉，况不信之尤者乎？楚重得志于晋，晋之耻也。子相晋国以为盟主，于今七年矣！再合诸侯，三合大夫，服齐、狄，宁东夏，平秦乱，城淳于，师徒不顿，国家不罢，民无谤讟，诸侯无怨，天无大灾，子之力也。有令名矣，而终之以耻，午也是惧。吾子其不可以不戒！」文子曰：「武受赐矣！然宋之盟，子木有祸人之心，武有仁人之心，是楚所以驾于晋也。今武犹是心也，楚又行僭，非所害也。武将信以为本，循而行之。譬如农夫，是□麃是衮，虽有饥馑，必有丰年。且吾闻之：『能信不为人下。』吾未能也。《诗》曰：『不僭不贼，鲜不为则。』信也。能为人则者，不为人下矣。吾不能是难，楚不为患。」
楚令尹围请用牲，读旧书，加于牲上而已。晋人许之。
三月甲辰，盟。楚公子围设服离卫。叔孙穆子曰：「楚公子美矣，君哉！」郑子皮曰：「二执戈者前矣！」蔡子家曰：「蒲宫有前，不亦可乎？」楚伯州犁曰：「此行也，辞而假之寡君。」郑行人挥曰：「假不反矣！」伯州犁曰：「子姑忧子皙之欲背诞也。」子羽曰：「当璧犹在，假而不反，子其无忧乎？」齐国子曰：「吾代二子愍矣！」陈公子招曰：「不忧何成，二子乐矣。」卫齐子曰：「苟或知之，虽忧何害？」宋合左师曰：「大国令，小国共。吾知共而已。」晋乐王鲋曰：「《小旻》之卒章善矣，吾从之。」
退会，子羽谓子皮曰：「叔孙绞而婉，宋左师简而礼，乐王鲋字而敬，子与子家持之，皆保世之主也。齐、卫、陈大夫其不免乎？国子代人忧，子招乐忧，齐子虽忧弗害。夫弗及而忧，与可优而乐，与忧而弗害，皆取忧之道也，忧必及之。《大誓》曰：『民之所欲，天必从之。』三大夫兆忧，能无至乎？言以知物，其是之谓矣。」
季武子伐莒，取郓，莒人告于会。楚告于晋曰：「寻盟未退，而鲁伐莒，渎齐盟，请戮其使。」乐桓子相赵文子，欲求货于叔孙而为之请，使请带焉，弗与。梁其跁曰：「货以藩身，子何爱焉？」叔孙曰：「诸侯之会，卫社稷也。我以货免，鲁必受师。是祸之也，何卫之为？人之有墙，以蔽恶也。墙之隙坏，谁之咎也？卫而恶之，吾又甚焉。虽怨季孙，鲁国何罪？叔出季处，有自来矣，吾又谁怨？然鲋也贿，弗与，不已。」召使者，裂裳帛而与之，曰：「带其褊矣。」赵孟闻之，曰：「临患不忘国，忠也。思难不越官，信也；图国忘死，贞也；谋主三者，义也。有是四者，又可戮乎？」乃请诸楚曰：「鲁虽有罪，其执事不辟难，畏威而敬命矣。子若免之，以劝左右可也。若子之群吏处不辟污，出不逃难，其何患之有？患之所生，污而不治，难而不守，所由来也。能是二者，又何患焉？不靖其能，其谁从之？鲁叔孙豹可谓能矣，请免之以靖能者。子会而赦有罪，又赏其贤，诸侯其谁不欣焉望楚而归之，视远如迩？疆埸之邑，一彼一此，何常之有？王伯之令也，引其封疆，而树之官。举之表旗，而着之制令。过则有刑，犹不可壹。于是乎虞有三苗，夏有观、扈，商有姺、邳，周有徐、奄。自无令王，诸侯逐进，狎主齐盟，其又可壹乎？恤大舍小，足以为盟主，又焉用之？封疆之削，何国蔑有？主齐盟者，谁能辩焉？吴、濮有衅，楚之执事岂其顾盟？莒之疆事，楚勿与知，诸侯无烦，不亦可乎？莒、鲁争郓，为日久矣，苟无大害于其社稷，可无亢也。去烦宥善，莫不竞劝。子其图之！」固请诸楚，楚人许之，乃免叔孙。
令尹享赵孟，赋《大明》之首章。赵孟赋《小宛》之二章。事毕，赵孟谓叔向曰：「令尹自以为王矣，何如？」对曰：「王弱，令尹强，其可哉！虽可，不终。」赵孟曰：「何故？」对曰：「强以克弱而安之，强不义也。不义而强，其毙必速。《诗》曰：『赫赫宗周，褒姒灭之。』强不义也。令尹为王，必求诸侯。晋少懦矣，诸侯将往。若获诸侯，其虐滋甚。民弗堪也，将何以终？夫以强取，不义而克，必以为道。道以淫虐，弗可久已矣！」
夏四月，赵孟、叔孙豹、曹大夫入于郑，郑伯兼享之。子皮戒赵孟，礼终，赵孟赋《瓠叶》。子皮遂戒穆叔，且告之。穆叔曰：「赵孟欲一献，子其从之！」子皮曰：「敢乎？」穆叔曰：「夫人之所欲也，又何不敢？」及享，具五献之笾豆于幕下。赵孟辞，私于子产曰：「武请于冢宰矣。」乃用一献。赵孟为客，礼终乃宴。穆叔赋《鹊巢》。赵孟曰：「武不堪也。」又赋《采蘩》，曰：「小国为蘩，大国省穑而用之，其何实非命？」子皮赋《野有死麇》之卒章。赵孟赋《常棣》，且曰：「吾兄弟比以安，龙也可使无吠。」穆叔、子皮及曹大夫兴，拜，举兕爵，曰：「小国赖子，知免于戾矣。」饮酒乐。赵孟出，曰：「吾不复此矣。」
天王使刘定公劳赵孟于颖，馆于洛汭。刘子曰：「美哉禹功，明德远矣！微禹，吾其鱼乎！吾与子弁冕端委，以治民临诸侯，禹之力也。子盍亦远绩禹功，而大庇民乎？」对曰：「老夫罪戾是惧，焉能恤远？吾侪偷食，朝不谋夕，何其长也？」刘子归，以语王曰：「谚所为老将知而耄及之者，其赵孟之谓乎！为晋正卿，以主诸侯，而侪于隶人，朝不谋夕，弃神人矣。神怒民叛，何以能久？赵孟不复年矣。神怒，不歆其祀；民叛，不即其事。祀事不从，又何以年？」
叔孙归，曾夭御季孙以劳之。旦及日中不出。曾夭谓曾阜曰：「旦及日中，吾知罪矣。鲁以相忍为国也，忍其外不忍其内，焉用之？」阜曰：「数月于外，一旦于是，庸何伤？贾而欲赢，而恶嚣乎？」阜谓叔孙曰：「可以出矣！」叔孙指楹曰：「虽恶是，其可去乎？」乃出见之。
郑徐吾犯之妹美，公孙楚聘之矣，公孙黑又使强委禽焉。犯惧，告子产。子产曰：「是国无政，非子之患也。唯所欲与。」犯请于二子，请使女择焉。皆许之，子皙盛饰入，布币而出。子南戎服入。左右射，超乘而出。女自房观之，曰：「子皙信美矣，抑子南夫也。夫夫妇妇，所谓顺也。」适子南氏。子皙怒，既而櫜甲以见子南，欲杀之而取其妻。子南知之，执戈逐之。及冲，击之以戈。子皙伤而归，告大夫曰：「我好见之，不知其有异志也，故伤。」
大夫皆谋之。子产曰：「直钧，幼贱有罪。罪在楚也。」乃执子南而数之，曰：「国之大节有五，女皆奸之：畏君之威，听其政，尊其贵，事其长，养其亲。五者所以为国也。今君在国，女用兵焉，不畏威也。奸国之纪，不听政也。子皙，上大夫，女，嬖大夫，而弗下之，不尊贵也。幼而不忌，不事长也。兵其从兄，不养亲也。君曰：『余不女忍杀，宥女以远。』勉，速行乎，无重而罪！」
五月庚辰，郑放游楚于吴，将行子南，子产咨于大叔。大叔曰：「吉不能亢身，焉能亢宗？彼，国政也，非私难也。子图郑国，利则行之，又何疑焉？周公杀管叔而蔡蔡叔，夫岂不爱？王室故也。吉若获戾，子将行之，何有于诸游？」
秦后子有宠于桓，如二君于景。其母曰：「弗去，惧选。」癸卯，金咸适晋，其车千乘。书曰：「秦伯之弟金咸出奔晋。」罪秦伯也。后子享晋侯，造舟于河，十里舍车，自雍及绛。归取酬币，终事八反。司马侯问焉，曰：「子之车，尽于此而已乎？」对曰：「此之谓多矣！若能少此，吾何以得见？」女叔齐以告公，且曰：「秦公子必归。臣闻君子能知其过，必有令图。令图，天所赞也。」
后子见赵孟。赵孟曰：「吾子其曷归？」对曰：「金咸惧选于寡君，是以在此，将待嗣君。」赵孟曰：「秦君何如？」对曰：「无道。」赵孟曰：「亡乎？」对曰：「何为？一世无道，国未艾也。国于天地，有与立焉。不数世淫，弗能毙也。」赵孟曰：「天乎？」对曰：「有焉。」赵孟曰：「其几何？」对曰：「金咸闻之，国无道而年谷和熟，天赞之也。鲜不五稔。」赵孟视荫，曰：「朝夕不相及，谁能待五？」后子出，而告人曰：「赵孟将死矣。主民，玩岁而愒日，其与几何？」
郑为游楚乱故，六月丁巳，郑伯及其大夫盟于公孙段氏，罕虎、公孙侨、公孙段、印段、游吉、驷带私盟于闺门之外，实薰隧。公孙黑强与于盟，使大史书其名，且曰七子。子产弗讨。
晋中行穆子败无终及群狄于大原，崇卒也。将战，魏舒曰：「彼徒我车，所遇又厄，以什共车必克。困诸厄，又克。请皆卒，自我始。」乃毁车以为行，五乘为三伍。荀吴之嬖人不肯即卒，斩以徇。为五陈以相离，两于前，伍于后，专为左角，参为左角，偏为前拒，以诱之。翟人笑之。未陈而薄之，大败之。
莒展舆立，而夺群公子秩。公子召去疾于齐。秋，齐公子锄纳去疾，展舆奔吴。
叔弓帅师疆郓田，因莒乱也。于是莒务娄、瞀胡及公子灭明以大厖与常仪靡奔齐。君子曰：「莒展之不立，弃人也夫！人可弃乎？《诗》曰：『无竞维人。』善矣。」
晋侯有疾，郑伯使公孙侨如晋聘，且问疾。叔向问焉，曰：「寡君之疾病，卜人曰：『实沈、台骀为祟。』史莫之知，敢问此何神也？」子产曰：「昔高辛氏有二子，伯曰阏伯，季曰实沈，居于旷林，不相能也。日寻干戈，以相征讨。后帝不臧，迁阏伯于商丘，主辰。商人是因，故辰为商星。迁实沈于大夏，主参。唐人是因，以服事夏、商。其季世曰唐叔虞。当武王邑姜方震大叔，梦帝谓己：『余命而子曰虞，将与之唐，属诸参，其蕃育其子孙。』及生，有文在其手曰：『虞』，遂以命之。及成王灭唐而封大叔焉，故参为晋星。由是观之，则实沈，参神也。昔金天氏有裔子曰昧，为玄冥师，生允格、台骀。台骀能业其官，宣汾、洮，障大泽，以处大原。帝用嘉之，封诸汾川。沈、姒、蓐、黄，实守其祀。今晋主汾而灭之矣。由是观之，则台骀，汾神也。抑此二者，不及君身。山川之神，则水旱疠疫之灾，于是乎禜之。日月星辰之神，则雪霜风雨之不时，于是乎禜之。若君身，则亦出入饮食哀乐之事也，山川星辰之神，又何为焉」？侨闻之，君子有四时：朝以听政，昼以访问，夕以修令，夜以安身。于是乎节宣其气，勿使有所壅闭湫底，以露其体。兹心不爽，而昏乱百度。今无乃壹之，则生疾矣。侨又闻之，内官不及同姓，其生不殖，美先尽矣，则相生疾，君子是以恶之。故《志》曰：『买妾不知其姓，则卜之。』违此二者，古之所慎也。男女辨姓，礼之大司也。今君内实有四姬焉，其无乃是也乎？若由是二者，弗可为也已。四姬有省犹可，无则必生疾矣。」叔向曰：「善哉！肸未之闻也。此皆然矣。」
叔向出，行人挥送之。叔向问郑故焉，且问子皙。对曰：「其与几何？无礼而好陵人，怙富而卑其上，弗能久矣。」
晋侯闻子产之言，曰：「博物君子也。」重贿之。
晋侯求医于秦。秦伯使医和视之，曰：「疾不可为也。是谓：『近女室，疾如蛊。非鬼非食，惑以丧志。良巨将死，天命不佑』」公曰：「女不可近乎？」对曰：「节之。先王之乐，所以节百事也。故有五节，迟速本末以相及，中声以降，五降之后，不容弹矣。于是有烦手淫声，慆堙心耳，乃忘平和，君子弗德也。物亦如之，至于烦，乃舍也已，无以生疾。君子之近琴瑟，以仪节也，非以慆心也。天有六气，降生五味，发为五色，征为五声，淫生六疾。六气曰阴、阳、风、雨、晦、明也。分为四时，序为五节，过则为灾。阴淫寒疾，阳淫热疾，风淫末疾，雨淫腹疾，晦淫惑疾，明淫心疾。女，阳物而晦时，淫则生内热惑蛊之疾。今君不节不时，能无及此乎？」出，告赵孟。赵孟曰：「谁当良臣？」对曰：「主是谓矣！主相晋国，于今八年，晋国无乱，诸侯无阙，可谓良矣。和闻之，国之大臣，荣其宠禄，任其宠节，有灾祸兴而无改焉，必受其咎。今君至于淫以生疾，将不能图恤社稷，祸孰大焉！主不能御，吾是以云也。」赵孟曰：「何谓蛊」对曰：「淫溺惑乱之所生也。于文，皿虫为蛊。谷之飞亦为蛊。在《周易》，女惑男，风落山，谓之《蛊》三。皆同物也。」赵孟曰：「良医也。」厚其礼归之。
楚公子围使公子黑肱、伯州犁城雠、栎、郏，郑人惧。子产曰：「不害。令尹将行大事，而先除二子也。祸不及郑，何患焉？」
冬，楚公子围将聘于郑，伍举为介。未出竟，闻王有疾而还。伍举遂聘。十一月己酉，公子围至，入问王疾，缢而弑之。遂杀其二子幕及平夏。右尹子干出奔晋。宫厩尹子皙出奔郑。杀大宰伯州犁于郏。葬王于郏，谓之郏敖。使赴于郑，伍举问应为后之辞焉。对曰：「寡大夫围。」伍举更之曰：「共王之子围为长。」
子干奔晋，从车五乘。叔向使与秦公子同食，皆百人之饩。赵文子曰：「秦公子富。」叔向曰：「底禄以德，德钧以年，年同以尊。公子以国，不闻以富。且夫以千乘去其国，强御已甚。《诗》曰：『不侮鳏寡，不畏强御。』秦、楚，匹也。」使后子与子干齿。辞曰：「金咸惧选，楚公子不获，是以皆来，亦唯命。且臣与羁齿，无乃不可乎？史佚有言曰：『非羁何忌？』」
楚灵王即位，薳罢为令尹，薳启强为大宰。郑游吉如楚，葬郏敖，且聘立君。归，谓子产曰：「具行器矣！楚王汰侈而自说其事，必合诸侯。吾往无日矣。」子产曰：「不数年，未能也。」
十二月，晋既烝，赵孟适南阳，将会孟子余。甲辰朔，烝于温。庚戌，卒。郑伯如晋吊，及雍乃复。
', '', '', '元年春季，楚国的公子围到郑国去聘问，同时娶了公孙段的女儿为妻。伍举作为副使，将要进入宾馆，郑国人讨厌他，派行人子羽婉辞拒绝，于是就住在城外。聘礼举行以后，将要带领很多兵去迎娶。子产担心这件事，派子羽辞谢，说：“由于敝邑狭小，不足以容纳您的随从，请求让我们清除地面作可以祭祀的地方，再听取您的命令。”令尹命令太宰伯州犁回答说：“贵君给寡大夫围恩惠，对围说将要让丰氏的女儿嫁给你做妻子。围陈列几筵，在庄王、共王的神庙中祭告然后前来娶妇。如果在野外赐给我，这是把贵君的恩赐丢在草丛中去了，这也是让寡大夫不能处在卿的行列里了。不仅如此，又让围欺骗了我的先君，将要不再能做寡君的大臣，恐怕也不能回去复命了。请大夫考虑罢！”子羽说：“小国没有罪过，依靠大国而不设防备就是他的罪过。小国打算依靠大国安定自己，而大国却恐怕是包藏祸心来打小国的主意吧！怕的是小国失去了依靠，就让诸侯得到戒惧，而全部怨恨大国，对国君命令抗拒违背，使它行不通。否则，敝邑就等于贵国的宾馆，岂敢爱惜丰氏的神庙？”伍举知道郑国有了防备，请求倒转弓袋子进入国都。郑国才同意了。
正月十五日，公子围进入国都，迎娶后出来。于是就和叔孙豹、晋国赵武、齐国国弱、宋国向戌、陈国公子招、蔡国公子归生、郑国罕虎、许国人、曹国人在虢地会见，这是为了重温宋国盟会的友好。祁午对赵文子说：“在宋国的盟会，楚国人占了晋国的先。现在令尹不守信用，这是诸侯都听说的。您如果还不戒备，怕的是又像在宋国一样。子木的信用为诸侯所称道，尚且欺骗晋国而要驾凌在上面，何况是不守信用的突出人物呢？楚国再次占了晋国的上风，是晋国的耻辱。您辅佐晋国作为盟主，到现在已经七年了。两次会合诸侯，三次会合大夫，使齐国、狄人归服，使华夏的东方国家安宁，平定秦国造成的动乱，在淳于修筑城墙，军队不疲弊，国家不疲乏，百姓没有诽谤，诸侯没有怨言。天不降大灾，这是您的力量。有了好名声了，反而用耻辱来结束，午就是害怕这个，您不能不警惕。”赵文子说：“武接受您的恩赐了。然而在宋国的结盟，子木有害人之心，武有爱人之心，这就是楚国所以驾凌在晋国上面的缘故。现在武还是这样的心，楚国又不守信用，这可不是他所能伤害的了。武将要用信用作为根本，按照这去做。譬如农夫，只要勤于除草培土，虽然有一时灾荒，最终必然获得丰收。而且我听说，能守信用就不会在别人下面，我还是不能做到守信用啊。《诗》说，‘待人以信，很少不能做榜样’，这是由于守信用的缘故。能够做别人典范的，不会在别人的下面了。我的难处在不能做到这一点。楚国不能造成祸患。”
楚国的令尹围请求使用牺牲，宣读一遍过去的盟约然后放在牺牲上面。晋国人答应了。
三月二十五日，结盟。楚国的公子围陈列了国君的服饰，两个卫士拿着戈站在旁边。叔孙穆子说：“楚国的公子很神气，像个国君啊！”郑国的子皮说：“两个拿着戈的人站在前面来了。”蔡国的子家说：“蒲宫有一对执戈卫士站在前面，不也可以吗？”楚国的伯州犁说：“这些东西是这次出来的时侯，向国君请求而借来的。”郑国的行人子羽说：“借了就不还了。”伯州犁说：“您还是去担心一下你们子皙想要违命作乱吧。”子羽说：“公子弃疾还在那里，借了不还您难道没有忧虑吗？”齐国的国子说：“我替这两位担心哪。”陈国的公子招说：“不忧愁怎么能办成事情？这两位可高兴啦。”卫国的齐子说：“如果有人事先知道，虽然有忧虑又有什么危害？”宋国的合左师说：“大国发令，小国供职，我知道供职就是了。”恶国的乐王鲋说：《小旻》的最后一章很好，我照着那样做。”
退出会场，子羽对子皮说：“叔孙言辞恰切而委婉，宋国左师语言简明而合于礼仪，乐王鲋自爱而恭敬，您和子家说话得当，都是可以保持几代爵禄的大夫。齐国、卫国、陈国的大夫大概不能免于祸难吧！国子替人忧虑，子招以高兴代替忧虑，齐子虽然有忧虑却不当作危害，凡是忧虑没有到自己身上而替人忧虑，和可以忧虑反而高兴，和把忧虑不当作危害，这都是招来忧虑的原由，忧虑必然到他的身上来。《大誓》说：‘百姓所要求的，上天必然听从。’三位大夫有了忧虑的兆头，忧虑能不来吗？从言语来说明情况，说的就是这个了。”
季武子进攻莒国，占据了郓地，莒国人向盟会报告。楚国对晋国说：“重温过去的盟会还没有结束，鲁国就进攻莒国，轻视盟约，请求诛杀鲁国的使者。” 乐桓子辅佐赵文子，想要向叔孙豹索取财货，而为他向赵文子说情。派人向叔孙豹要他的带子，叔孙豹不给。梁其跁说：“财货用来保护身体，您有什么可吝惜呢？”叔孙豹说：“诸侯的会见，是为了保卫国家。我用财货来免于祸患，鲁国就必然受到进攻了，这是为它带来祸患啊，还有什么保卫可言？人所以有墙壁，是用来遮挡坏人的。墙壁裂缝，这是谁的过错？为了保卫反而让鲁国受攻击，我的罪过又超过了墙壁。虽然应当埋怨季孙，鲁国有什么罪过呢？叔孙出使季孙守国，一向就是这样的，我又去怨谁呢？然而鲋喜欢财货，不给他，没有完。”召见使者，撕下一片做裙子的帛给他，说：“身上的带子恐怕太窄了。”赵孟听到了，说：“面临祸患而不忘记国家，这是忠心。想到危难而不放弃职守，这是诚意。为国家打算而不惜一死，这是坚定。计谋以上述三点作为主体，这是道义。有了这四点，难道可以诛戮吗？”就向楚国请求说：“鲁国虽然有罪，它的执事不避祸难，畏惧贵国的威严而恭敬地从命了。您如果赦免他，用来勉励您的左右，这还是可以的。如果您的官吏们在国内不避困难，在国外不逃避祸难，还有什么可忧虑的？忧虑之所以产生，就是有困难而不能治理、祸难来了而不顶住，就是这样来的。能做到这两点，又忧虑什么？不安定贤能的人了，有谁去跟从他？鲁国的叔孙豹可以说是贤能的人，请求赦免他，用来安定贤能的人。您参加了盟会而赦免了有罪的国家，又奖励它的贤能的人，还有谁不高高兴兴的望着楚国而归服你们，把疏远看成亲近呢？国境上的城邑，一时属那边，一时属这边，有什么一定？三王五伯的政令，划定疆界，在那里设置官员，树立界碑，而写明在章程法令上。越境就要惩罚，尽管这样，尚且不能一成不变。在这种情况下虞舜时代有三苗，夏朝有观氏、扈氏，商朝有姺氏、邳氏，周朝有徐国、奄国。自从没有英明的天子以后，诸侯争相扩张，交替主持结盟，难道又能够一成不变吗？担心大祸不计较小错，足以做盟主，又哪里用得着管这些小事？边境被侵削，哪个国家没有？主持结盟的，谁能治理得了？吴国、百濮有隙可乘，楚国的执事难道只顾到盟约不去进攻？莒国边境上的事情，楚国不要过问，不要烦劳诸侯，不也可以吗？莒国、鲁国争执郓地，日子很久了。只要对他们国家没有大妨害，可以不必去保护。免除烦劳、赦免善人，就没有不争相努力的。您还是考虑一下。”晋国人坚决向楚国请求，楚国人答应了，就赦免了叔孙。
令尹设宴招待赵孟，赋《大明》的第一章。赵孟赋《小宛》的第二章。事情完了，赵孟对叔向说：“令尹自以为是国王了，怎么样？”叔向回答说：“国王弱，令尹强，大概是可以成功的吧！虽然可以成功，不能有好结果。”赵孟说：“为什么？”叔向回答说：“用强大制服弱小而心安理得，强大而不合于道义。不合于道义而强大，他的灭亡必然很快。《诗》说‘声威赫赫的宗周，褒姒灭亡了它’，这是由于强大又不合道义的缘故。令尹做了国王，必然请求诸侯的拥护。晋国有些衰弱了，诸侯就会投靠他。如果得到了诸侯，他的暴虐就更厉害，百姓不能忍受他的残暴，他如何能善终？用强力来取得君位，不合于道义而能获成功，必然把它作为常道。把荒淫暴虐作为常道，是不能持久的啊！”
夏季，四月，赵孟、叔孙豹、曹国的大夫进入郑国，郑简公同时设享礼招待他们。子皮通知赵孟，通知的礼仪结束，赵孟赋《瓠叶》这首诗。子皮通知叔孙豹，同时告诉他赵孟赋诗的情况。叔孙豹说：“赵孟想要一献之宴，您还是听从他。”子皮说：“敢吗？”叔孙豹说：“那个人想要这样，又有什么不敢？”等到举行享礼，在东房准备了五献的用具。赵孟辞谢，私下对子产说：“武已经向上卿请求过了。”于是就使用了一献。赵孟作为主宾，享礼完毕就饮宴。叔孙豹赋《鹊巢》这首诗，赵孟说：“武不敢当啊。”叔孙豹又赋《采蘩》这首诗，说：“小国献上薄礼蘩，大国爱惜而加以使用，岂敢不服从大国的命令？”子皮赋《野有死麇》的最后一章，赵孟赋《常棣》这首诗，同时说：“我们兄弟亲密而安好，可以别让狗叫了。”叔孙豹、子皮和曹国的大夫起立，下拜，举起牛角杯，说：“小国靠着您，知道免于罪过了。”大家喝酒喝得很高兴。赵孟出来，说：“我不会再见到这样的欢乐了。”
周景王派刘定公在颍地慰劳赵孟，让他住在洛水边上。刘定公说：“美好啊，禹的功绩！他美的德行多么深远。如果没有禹，我们大约要变成鱼了吧！我和您戴着礼帽穿着礼服，来治 理百姓、面对诸侯，都是禹的力量。您何不远继禹的功绩，而大大地庇护百姓呢？”赵孟回答说：“我老头子惟恐犯下罪过，哪里能考虑得长远的事情？我们这些人苟且度日，早晨不想到晚上，哪里能够作长远考虑呢？”刘子回去，把情况告诉周景王，说：“俗话所说老了会聪明些，可是糊涂也跟着来了，这说的就是赵孟吧！做晋国的正卿以主持诸侯，反而把自己等同于那些下贱的人，早晨不想到晚上，这是丢弃了神灵和百姓了。神灵发怒，百姓背叛，何以能长久？赵孟不再能过年了。神灵发怒，不享用他的祭祀。百姓背叛，不替他做事情。祭祀和国事不能办理，又怎么能过得了年？”
叔孙回国，曾夭为季孙驾车去慰劳他。从早晨到中午，叔孙没有出来。曾夭对曾阜说：“从早晨一直等到中午，我们已经知道罪过了。鲁国是用互相忍让来治理国家的。在国外忍让，在国内不忍让，那又何必呢？”曾阜说：“他几个月在外边，我们在这里只一早晨，有什么妨碍？商人要赢利，还能讨厌喧闹吗？”曾阜对叔孙说：“可以出去了。”叔孙指着柱子说：“虽然讨厌这个柱子，难道能够去掉吗？”于是就出去接见季孙。
郑国徐吾犯的妹妹很漂亮，公孙楚已经和她订了婚，公孙黑又硬派人送去聘礼。徐吾犯害怕，告诉子产。子产说：“这是国家政事混乱，不是您的忧患。她愿意嫁给谁就嫁给谁。”徐吾犯请求这二位，让女子自己选择。他们都答应了。公孙黑打扮得非常华丽，进来，陈设财礼然后出去了。公孙楚穿着军服进来，左右开弓，一跃登车而去。女子在房间内观看他们，说：“子皙确实是很美，不过子南是个真正的男子汉。丈夫要像丈夫，妻子要像妻子，这就是所谓顺。”徐女嫁给了公孙楚家。公孙黑发怒，不久以后就把皮甲穿在外衣里而去见公孙楚，想要杀死他而占取他的妻子。公孙楚知道他的企图，拿了戈追赶他，到达交叉路口，用戈敲击他。公孙黑受伤回去，告诉大夫说：“我很友好地去见他，不知道他有别的想法，所以受了伤。”
大夫们都议论这件事。子产说：“各有理由，年幼地位低的有罪，罪在于公孙楚。”于是就抓住公孙楚而列举他的罪状，说：“国家的大节有五条，你都触犯了。惧怕国君的威严，听从他的政令，尊重贵人，事奉长者，奉养亲属，这五条是用来治理国家的。现在国君在国都里，你动用武器，这是不惧怕威严。触犯国家的法纪，这是不听从政令。子皙是上大夫，你是下大夫，而又不肯在他下面，这是不尊重贵人。年纪小而不恭敬，这是不事奉长者。用武器对付堂兄，这是不奉养亲属。国君说：‘我不忍杀你，赦免你让你到远地。’尽你的力量，快走吧，不要加重你的罪行！”
五月初二日，郑国放逐公孙楚到吴国。准备让公孙楚起程，子产征求太叔的意见。太叔说：“吉不能保护自身，哪里能保护一族？他的事情属于国家政治，不是私家的危难。您为郑国打算，有利国家就去办，又有什么疑惑呢？周公杀死管叔，放逐了蔡叔，难道不爱他们？这是为巩固王室。吉如果得罪，您也将要执行惩罚，何必顾虑游氏诸人？”
秦国的后子受到秦桓公的宠信，在秦景公即位的时候和景公如同两君并列一样。他的母亲说：“如果不离开，恐怕会要被放逐的。”五月二十日，后子到晋国去，他的车子有一千辆。《春秋》记载说“秦伯之弟鍼出奔晋”，这是把罪责归于秦景公。
后子设享礼招待晋平公，在黄河搭了浮桥，每隔十里就停放一批车辆，从雍城绵延到绛城。回去取奉献的礼物，到享礼结束往返取币八次。司马侯询问说：“您的车辆都在这里了吗？”后子回答说：“这已经算够多了。如果能比这些少，我怎么能见到你呢？”司马侯把这些话报告晋平公，而且说：“秦公子必然回国。下臣听说君子能够知道自己的过错，一定有好的计谋。好的计谋，这是上天所赞助的。”
后子进见赵孟。赵孟说：“您大约什么时候回去呢？”后子回答说：“鍼害怕被国君放逐，因此留在这里，准备等到新君即位再回国。”赵孟说：“秦国的国君怎么样？”后子回答说：“无道。”赵孟说：“国家会灭亡吗？”后子回答说：“为什么？一代的君主无道，国家还不致到达绝境。立国在天地之间，必然有辅助的人。不是几代的荒淫，不能灭亡的。”赵孟说：“国君会短命吗？”后子回答说：“会的。”赵孟说：“大约多久呢？”后子回答说：“鍼听说，国家无道而粮食丰收，这是上天在辅助他。少则不过五年。”赵孟看着太阳的影子，说：“早晨等不到晚上，谁能等待五年？”后子出来，告诉别人说：“赵孟将要死了。主持百姓的事情，既想混日子又急于怕自己活不久，他还能活多久呢？”
郑国由于游楚作乱的缘故，六月初九日，郑简公和他的大夫们在公孙段家里结盟。罕虎、公孙侨、公孙段、印段、游吉、驷带在闺门外边私下结盟，盟地就在薰隧。公孙黑硬要参加结盟，让太史写下他的名字，而且称为“七子”。子产并不加讨伐。
晋国的中行穆子在大原打败了无终和各部狄人，这是由于重用步兵的缘故。即将作战时，魏舒说：“他们是步兵我们是车兵，两军相遇的地方形势险要，用十个步兵对付一辆战车，必然得胜。把他们围困在险地，我们又能胜他们。请全部改为步兵，从我开始。”于是就不用战车改为步兵的行列，五乘战车改成三个伍。荀吴的宠臣不肯编入步兵，就杀了巡行示众。晋军摆成五种阵势以互相呼应，两在前面，伍在后面，专作为右翼，参作为左翼，偏作为前锋方阵，用这个来诱敌。狄人讥笑他们。没有等狄人摆开阵势，晋兵就迫近进攻，大胜狄人。
莒国的展舆即位，夺去了公子们的俸禄。公子们把去疾从齐国召回来。秋季，齐国的公子锄把去疾送回莒国，展舆逃亡到吴国。
叔弓率领军队划定郓地的疆界，这是乘莒国发生内乱的缘故。在这时候莒国的务娄、瞀胡和公子灭明带着大厖和常仪靡逃亡到齐国。君子说：“莒展不能被立，这是由于失去了人才的缘故吧！人才可以不要吗？《诗》说，‘要强大只有得到贤人’，很正确啊。”
晋平公有病，郑伯派子产去到晋国聘问，同时探视病情。叔向询问子产说：“寡君的疾病，卜人说‘是实沈、台骀在作怪’，太史不知道他们，谨敢请问这是什么神灵？”子产说：“从前高辛氏有两个儿子，大的叫阏伯，小的叫实沈，住在大树林里，不能相容，每天使用武器互相攻打。帝尧认为他们不好，把阏伯迁移到商丘，用大火星来定时节。商朝人沿袭下来，所以大火星成了商星。把实沈迁移到大夏，用参星来定时节，唐国人沿袭下来，以归服事奉夏朝、商朝。它的末世叫做唐叔虞。正当武王的邑姜怀着太叔的时候，梦见天帝对自己说：‘我为你的儿子起名为虞，准备将唐国给他，属于参星，而繁衍养育他的子孙。’等到生下来，有纹路在他掌心像虞字，就名为虞。等到成王灭了唐国，就封给了太叔，所以参星是晋国的星宿。从这里看来，那么实沈就是参星之神了。从前金天氏有后代叫做昧，做水官，生了允格、台骀。台骀能世代为官，疏通汾水、洮水，堵住大泽，带领人们就住在广阔的高平的地区。颛顼因此嘉奖他，把他封在汾川，沈、姒、蓐、黄四国世代守着他的祭祀。现在晋国主宰了汾水一带而灭掉了这四个国家。从这里看来，那么台骀就是汾水之神了。然而这两位神灵与晋君之病无关。山川的神灵，遇到水旱瘟疫这些灾祸就向他们祭祀禳灾。日月星辰的神灵，遇到雪霜风雨不合时令，就向他们祭祀禳灾。至于疾病在您身上，也就是由于劳逸、饮食、哀乐不适度的缘故。山川、星辰的神灵又哪能降病给您呢？侨听说，君子有四段时间，早晨用来听取政事，白天用来调查询问，晚上用来确定政令，夜里用来安歇身体。在这时就可以有节制地散发体气，别让它有所壅塞以使身体衰弱。心里不明白这些，就会使百事昏乱。现在恐怕是体气用在一处，就生病了。侨又听说，国君的妻妾不能有同姓，因为子孙不能昌盛。美人都占尽了，那么就会得病，君子因此讨厌这个。所以《志》说：‘买姬妾侍女不知道她的姓，就占卜一下。’违反这两条，古代是很慎重的。男女要辨别姓氏，这是礼仪的大事。现在君王的宫里有四个姬姓侍妾，那恐怕就是为了这个缘故吧！如果是由于这两条，病就不能治了。去掉这四个姬姓女子还可以，否则就必然得病了。”叔向说：“好啊，肸没有听说过呢，所说都是对的啊。”
叔向出来，行人子羽送他。叔向询问郑国的情况，同时询问子皙的情况。子羽回答说：“他还能活多久？没有礼仪而喜欢凌驾于人，仗着富有而轻视他的上级，不能长久了。”
晋平公听说了子产的话，说：“他是知识渊博的君子啊。”送给子产以很厚的财物。
晋平公在秦国求医，秦景公让医和为他看病。医和说：“病不能治了，这叫做亲近女人，得病好像蛊惑。不是由于鬼神，也不是由于饮食，而是被女色迷惑而丧失了意志。良臣将要死去，上天不能保佑。”晋平公问：“女人不能亲近吗？”医和回答说：“节制它。先王的音乐，是用来节制百事的，所以有五声的节奏，快慢、本末以互相调节，声音和谐然后降下来。五声下降后，就不允许再弹了。这时候再弹就有了繁复的手法和靡靡之音，使人心烦耳乱，就会忘记了平正和谐，因此君子是不听的。事情也像音乐一样，一到过度，就应该停止，不要因此得病。君子接近妻室，是用礼来节制的，不是用来烦心的。天有六种气候，派生为五种口味，表现为五种颜色，应验为五种声音。凡是过了头就会发生六种疾病。六种气候就叫做阴、晴、风、雨、夜、昼，分为四段时间，顺序为五声的节奏，过了头就是灾祸：阴没有节制是寒病，阳没有节制是热病，风没有节制是四肢病，雨没有节制是腹病，夜里没有节制是迷惑病，白天没有节制是心病。女人，属于阳事而时间在夜里，对女人没有节制就会发生内热蛊惑的疾病。现在您没有节制不分昼夜，能不到这个地步吗？”
医和出来，告诉赵孟。赵孟说：“谁相当于良臣？”医和说：“就是您了。您辅佐晋国，到现在八年，晋国没有动乱，诸侯没有缺失，可以说是良了。和听说，国家的大臣，光荣地受到信任和爵禄，承担国家的大事。有灾祸发生却不能改变作法，必然受到灾殃。现在国君到了没有节制的程度因而得病，将要不能为国家图谋考虑，还有比这更大的灾祸吗？您不能禁止，我因此才这样说。”赵孟说：“什么叫做蛊？”医和回答说：“这是沉迷惑乱所引起的。在文字里，器皿中毒虫是蛊。稻谷中的飞虫也是蛊。在《周易》里，女人迷惑男人，大风吹落山木叫做《蛊》。这都是同类事物。”赵孟说：“真是好医生啊。”赠给他很重的礼物而让他回去。
楚国的公子围派公子黑肱、伯州犁在犫、栎、郏地筑城，郑国人害怕。子产说：“没有妨害。令尹准备干大事而先除掉这两位。祸患不会到达郑国，担心什么？”
冬季，楚国的公子围准备到晋国聘问，伍举作为副手。没有走出国境，听说楚王有病而回来，伍举就到郑国聘问。十一月初四日，公子围到达，进宫问候楚王的病情，把楚王勒死了，并乘机杀了他的两个儿子幕和平夏。右尹子干逃亡到晋国，宫厩尹子皙逃亡到郑国。把太宰伯州犁绞死在郏地。把楚王葬在郏地，称他为郏敖。派使者发讣告到郑国，伍举问使者关于继承人的措辞，使者说：“寡大夫围。”伍举改正说：“共王的儿子围是长子。”
子干逃亡到晋国，跟从的车子有五辆，叔向让他和秦公子后子食禄相同，都是一百人的口粮。赵文子说：“秦公子富有。”叔向说：“根据德行得到俸禄，德行相等根据年龄，年龄相等根据地位。公子的食禄根据他国家的大小，没有听说根据什么富有情况来给。而且带着一千辆车子离开他的国家，强暴太过分了。《诗》说：‘不欺侮鳏寡，不害怕强暴。’秦国、楚国是地位相同的大国。”于是就让后子和子干并列。后子辞谢说：“鍼害怕被放逐，楚公子怕被怀疑，所以都来晋国，也就唯命是听。而且下臣和旅客并列，恐怕不可以吧！史佚有话说：‘不是旅客，为什么要对他恭敬？’”
楚灵王即位，薳罢作令尹，薳启彊作太宰。郑国的游吉到楚国参加郏敖的葬礼，同时为新国君的即位聘问。回国后对子产说：“准备行装吧。楚王骄傲奢侈而自我欣赏他的所作所为，必然要会合诸侯，我没有几天就要前去开会了。”子产说：“没有几年是办不到的。
十二月，晋国已经举行了冬祭。赵孟去到南阳，准备祭祀孟子馀。初一日，在温地家庙举行冬祭。初七日，死去。郑简公到晋国吊唁，到达雍地就回去了。', '[{"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42b634a8757d5a0fb118", "shortContent": "本篇采自冯梦龙所编笔记集《智囊补》。是书搜集的主要是一些充满智慧的故事，大多涉及到官府的断狱。本篇案情并不复杂，且事先就将罪犯作案的过程交代得十分清楚，但读者心中有数，而当事人却并不明白。因为前面曾交代有赵妻孙氏“不欲夫行，已闹数日”的矛盾，因而赵的被杀就很容易怀疑到其妻身上。县尹就是沿着这一思路而疑孙的，当然也还可能有常见的情杀之类的联想。罪犯张潮因杀其夫而已知赵三不在，故叩门便直叫三娘子乃是一...", "authors": ["周先慎"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559126248, '5cedf06343e78c00672c2db3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643051, '左传 · 昭公 · 昭公二年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二年春，晋侯使韩起来聘。夏，叔弓如晋。秋，郑杀其大夫公孙黑。冬，公如晋，至河乃复。季孙宿如晋。
【传】二年春，晋侯使韩宣子来聘，且告为政而来见，礼也。观书于大史氏，见《易》《象》与《鲁春秋》，曰：「周礼尽在鲁矣。吾乃今知周公之德，与周之所以王也。」公享之。季武子赋《绵》之卒章。韩子赋《角弓》。季武子拜，曰：「敢拜子之弥缝敝邑，寡君有望矣。」武子赋《节》之卒章。既享，宴于季氏，有嘉树焉，宣子誉之。武子曰：「宿敢不封殖此树，以无忘《角弓》。」遂赋《甘棠》。宣子曰：「起不堪也，无以及召公。」
宣子遂如齐纳币。见子雅。子雅召子旗，使见宣子。宣子曰：「非保家之主也，不臣。」见子尾。子尾见强，宣子谓之如子旗。大夫多笑之，唯晏子信之，曰：「夫子，君子也。君子有信，其有以知之矣。」自齐聘于卫。卫侯享之，北宫文子赋《淇澳》。宣子赋《木瓜》。
夏四月，韩须如齐逆女。齐陈无宇送女，致少姜。少姜有宠于晋侯，晋侯谓之少齐。谓陈无宇非卿，执诸中都。少姜为之请曰：「送从逆班，畏大国也，犹有所易，是以乱作。」
叔弓聘于晋，报宣子也。晋侯使郊劳。辞曰：「寡君使弓来继旧好，固曰：『女无敢为宾！』彻命于执事，敝邑弘矣。敢辱郊使？请辞。」致馆。辞曰：「寡君命下臣来继旧好，好合使成，臣之禄也。敢辱大馆？」叔向曰：「子叔子知礼哉！吾闻之曰：『忠信，礼之器也。卑让，礼之宗也。』辞不忘国，忠信也。先国后己，卑让也。《诗》曰：『敬慎威仪，以近有德。』夫子近德矣。」
秋，郑公孙黑将作乱，欲去游氏而代其位，伤疾作而不果。驷氏与诸大夫欲杀之。子产在鄙，闻之，惧弗及，乘遽而至。使吏数之，曰：「伯有之乱，以大国之事，而未尔讨也。尔有乱心，无厌，国不女堪。专伐伯有，而罪一也。昆弟争室，而罪二也。薰隧之盟，女矫君位，而罪三也。有死罪三，何以堪之？不速死，大刑将至。」再拜稽首，辞曰：「死在朝夕，无助天为虐。」子产曰：「人谁不死？凶人不终，命也。作凶事，为凶人。不助天，其助凶人乎？」请以印为褚师。子产曰：「印也若才，君将任之。不才，将朝夕从女。女罪之不恤，而又何请焉？不速死，司寇将至。」七月壬寅，缢。尸诸周氏之衢，加木焉。
晋少姜卒。公如晋，及河。晋侯使士文伯来辞，曰：「非伉俪也。请君无辱！」公还，季孙宿遂致服焉。叔向言陈无宇于晋侯曰：「彼何罪？君使公族逆之，齐使上大夫送之。犹曰不共，君求以贪。国则不共，而执其使。君刑已颇，何以为盟主？且少姜有辞。」冬十月，陈无宇归。
十一月，郑印段如晋吊。', '', '', '二年春季，晋平公派韩宣子来鲁国聘问，同时报告他掌握国政，因此来进见，这是合于礼的。韩宣子在太史那里观看书籍，看到《易》、《像》和《鲁春秋》，说：“《周礼》都在鲁国了，我现在才知道周公的德行和周朝的所以能成就王业的缘故了。”昭公设享礼招待他，季武子赋《绵》的最后一章。韩宣子赋《角弓》这首诗。季武子参拜说：“谨敢拜谢您弥补敝邑，寡君有了希望了。”季武子赋了《节》的最后一章。享礼完毕，在季武子家里饮宴。有一棵好树，韩宣子赞美它。季武子说：“宿岂敢不培植这棵树，以不忘记《角弓》。”就赋了《甘棠》这首诗。韩宣子说：“起不敢当，赶不上召公。”
韩宣子于是就到齐国奉献财礼。进见子雅。子雅召见子旗，让他拜见韩宣子。韩宣子说：“这不是保住家族的大夫，不像个臣子。”进见子尾。子尾让彊拜见韩宣子。韩宣子对他的评价像对子旗的一样，大夫大多讥笑他，只有晏子相信他，说：“韩先生是个君子。君子有诚心，他是很了解的。”韩宣子从齐国到卫国聘问。卫襄公设享礼招待他。北宫文子赋《淇澳》这首诗，韩宣子赋《木瓜》这首诗。
夏季，四月，韩须到齐国迎接齐女少姜。齐国的陈无宇送少姜，把她送到晋国。晋平公宠爱少姜，晋平公称她为少齐。认为陈无宇不是卿，把他在中都抓了起来。少姜为他请求，说：“送亲的人地位同于迎亲的人。由于害怕大国，还有一些改变，因此才发生了混乱。”
叔弓到晋国聘问，这是为了回报韩宣子前来聘问的缘故。晋平公派人在郊外慰劳，叔弓辞谢说：“寡君派弓前来重修过去的友好，坚持说‘你不能作为宾客’，只要把命令上达给执事，敝邑就大有光彩了，岂敢烦劳郊使？请允许辞谢。”请他住宾馆，叔弓辞谢说：“寡君命令下臣前来重修过去的友好，友好结合，使命完成，这就是下臣的福禄了。岂敢住进宏大的宾馆！”叔向说：“子叔子懂得礼啊！我听说：‘忠信是礼的容器，卑让是礼的根本。’言辞不忘记国家，这是忠信。先国家后自己，这是卑让。《诗》说：‘不要滥用威仪，以亲近有德的人。’先生已经接近贤德了。”
秋季，郑国的公孙黑准备发动叛乱，想要去掉游氏而代替他的地位，由于旧伤发作，而没有实现。驷氏和大夫们想要杀死公孙黑。子产正在边境，听说了这件事，害怕赶不到，乘坐了传车到达。让官吏历数他的罪状，说：“伯有那次动乱，由于当时正致力于事奉大国，因而没有讨伐你。你有祸乱之心不能满足，国家对你不能容忍。专权而攻打伯有，这是你罪状的第一条。兄弟争夺妻子，这是你罪状的第二条。薰隧的盟会，你假托君位，这是你罪状的第三条。有了死罪三条，怎么能够容忍？你不快点去死，死刑就会到你的头上。”公孙黑再拜叩头，推托说：“我早晚就死，不要帮着上天来虐待我。”子产说：“人谁不死！凶恶的人不得善终，这是天命。做了凶恶的事情，就是凶恶的人。不帮着上天，难道帮着凶恶的人？”公孙黑请求让其子印担任褚师的官职。子产说：印如果有才能，国君将会任命他。如果没有才能，将会早晚跟你去。你对自己的罪过不担心，而又请求什么？不快点去死，司寇将要来到了。”七月初一日，公孙黑上吊死了。暴尸在周氏地方的要道上，把写着罪状的木头放在尸体上。
晋国的少姜死了。鲁昭公要到晋国去吊唁，到达黄河，晋平公派士文伯来辞谢，说：“不是正式的配偶，请您不必光临。”昭公回国，季孙宿就送去了少姜下葬的衣服。叔向对晋平公谈论陈无宇说：“他有什么罪？君王派公族大夫迎亲，齐国派上大夫送亲，还说不恭敬，君王的要求也太过分了。我国自己就不恭敬，反而把齐国的使者抓起来，君王的刑罚太偏了，怎么做盟主？而且少姜曾经为他说过话的。”冬季十月，陈无宇回国。
十一月，郑国的印段到晋国去吊唁。', NULL, '', 'indent', 1559126289, '5cedf08dc8959c0069f4e98d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643052, '左传 · 昭公 · 昭公三年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三年春王正月丁未，滕子原卒。夏，叔弓如滕。五月，葬滕成公。秋，小邾子来朝。八月，大雩。冬，大雨雹。北燕伯款出奔齐。
【传】三年春，王正月，郑游吉如晋，送少姜之葬。梁丙与张趯见之。梁丙曰：「甚矣哉！子之为此来也。」子大叔曰：「将得已乎？昔文、襄之霸也，其务不烦诸侯。令诸侯三岁而聘，五岁而朝，有事而会，不协而盟。君薨，大夫吊，卿共葬事。夫人，士吊，大夫送葬。足以昭礼命事谋阙而已，无加命矣。今嬖宠之丧，不敢择位，而数于守适，唯惧获戾，岂敢惮烦？少姜有宠而死，齐必继室。今兹吾又将来贺，不唯此行也。」张趯曰：「善哉！吾得闻此数也。然自今，子其无事矣。譬如火焉，火中，寒暑乃退。此其极也，能无退乎？晋将失诸侯，诸侯求烦不获。」二大夫退。子大叔告人曰：「张趯有知，其犹在君子之后乎！」
丁未，滕子原卒。同盟，故书名。
齐侯使晏婴请继室于晋，曰：「寡君使婴曰：『寡人愿事君，朝夕不倦，将奉质币，以无失时，则国家多难，是以不获。不腆先君之适，以备内官，焜耀寡人之望，则又无禄，早世殒命，寡人失望。君若不忘先君之好，惠顾齐国，辱收寡人，徼福于大公、丁公，照临敝邑，镇抚其社稷，则犹有先君之适及遗姑姊妹若而人。君若不弃敝邑，而辱使董振择之，以备嫔嫱，寡人之望也。』」韩宣子使叔向对曰：「寡君之愿也。寡君不能独任其社稷之事，未有伉俪。在縗絰之中，是以未敢请。君有辱命，惠莫大焉。若惠顾敝邑，抚有晋国，赐之内主，岂唯寡君，举群臣实受其贶。其自唐叔以下，实宠嘉之。」
既成昏，晏子受礼。叔向从之宴，相与语。叔向曰：「齐其何如？」晏子曰：「此季世也，吾弗知。齐其为陈氏矣！公弃其民，而归于陈氏。齐旧四量，豆、区、釜、钟。四升为豆，各自其四，以登于釜。釜十则钟。陈氏三量，皆登一焉，钟乃大矣。以家量贷，而以公量收之。山木如市，弗加于山。鱼盐蜃蛤，弗加于海。民参其力，二入于公，而衣食其一。公聚朽蠹，而三老冻馁。国之诸市，屦贱踊贵。民人痛疾，而或燠休之，其爱之如父母，而归之如流水，欲无获民，将焉辟之？箕伯、直柄、虞遂、伯戏，其相胡公、大姬，已在齐矣。」
叔向曰：「然。虽吾公室，今亦季世也。戎马不驾，卿无军行，公乘无人，卒列无长。庶民罢敝，而宫室滋侈。道堇相望，而女富溢尤。民闻公命，如逃寇仇。栾、郤、胥、原、狐、续、庆、伯，降在皂隶。政在家门，民无所依，君日不悛，以乐慆忧。公室之卑，其何日之有？《谗鼎之铭》曰：『昧旦丕显，后世犹怠。』况日不悛，其能久乎？」
宴子曰：「子将若何？」叔向曰：「晋之公族尽矣。肸闻之，公室将卑，其宗族枝叶先落，则公从之。肸之宗十一族，唯羊舌氏在而已。肸又无子。公室无度，幸而得死，岂其获祀？」
初，景公欲更晏子之宅，曰：「子之宅近市，湫隘嚣尘，不可以居，请更诸爽垲者。」辞曰：「君之先臣容焉，臣不足以嗣之，于臣侈矣。且小人近市，朝夕得所求，小人之利也。敢烦里旅？」公笑曰：「子近市，识贵贱乎？」对曰：「既利之，敢不识乎？」公曰：「何贵何贱？」于是景公繁于刑，有鬻踊者。故对曰：「踊贵屦贱。」既已告于君，故与叔向语而称之。景公为是省于刑。君子曰：「仁人之言，其利博哉。晏子一言而齐侯省刑。《诗》曰：『君子如祉，乱庶遄已。』其是之谓乎！」
及宴子如晋，公更其宅，反，则成矣。既拜，乃毁之，而为里室，皆如其旧。则使宅人反之，曰：「谚曰：『非宅是卜，唯邻是卜。』二三子先卜邻矣，违卜不祥。君子不犯非礼，小人不犯不祥，古之制也。吾敢违诸乎？」卒复其旧宅。公弗许，因陈桓子以请，乃许之。
夏四月，郑伯如晋，公孙段相，甚敬而卑，礼无违者。晋侯嘉焉，授之以策，曰：「子丰有劳于晋国，余闻而弗忘。赐女州田，以胙乃旧勋。」伯石再拜稽首，受策以出。君子曰：「礼，其人之急也乎！伯石之汰也，一为礼于晋，犹荷其禄，况以礼终始乎？《诗》曰：『人而无礼，胡不遄死？』其是之谓乎！」
初，州县，栾豹之邑也。及栾氏亡，范宣子、赵文子、韩宣子皆欲之。文子曰：「温，吾县也。」二宣子曰：「自郤称以别，三传矣。晋之别县不唯州，谁获治之？」文子病之，乃舍之。二子曰：「吾不可以正议而自与也。」皆舍之。及文子为政，赵获曰：「可以取州矣。」文子曰：「退！二子之言，义也。违义，祸也。余不能治余县，又焉用州？其以徼祸也？君子曰：『弗知实难。』知而弗从，祸莫大焉。有言州必死。」
丰氏故主韩氏，伯石之获州也，韩宣子为请之，为其复取之之故。
五月，叔弓如滕，葬滕成公，子服椒为介。及郊，遇懿伯之忌，敬子不入。惠伯曰：「公事有公利，无私忌，椒请先入。」乃先受馆。敬子从之。
晋韩起如齐逆女。公孙虿为少姜之有宠也，以其子更公女而嫁公子。人谓宣子：「子尾欺晋，晋胡受之？」宣子曰：「我欲得齐而远其宠，宠将来乎？」
秋七月，郑罕虎如晋，贺夫人，且告曰：「楚人日征敝邑，以不朝立王之故。敝邑之往，则畏执事其谓寡君『而固有外心。』其不往，则宋之盟云。进退罪也。寡君使虎布之。」宣子使叔向对曰：「君若辱有寡君，在楚何害？修宋盟也。君苟思盟，寡君乃知免于戾矣。君若不有寡君，虽朝夕辱于敝邑，寡君猜焉。君实有心，何辱命焉？君其往也！苟有寡君，在楚犹在晋也。」
张趯使谓大叔曰：「自子之归也，小人粪除先人之敝庐，曰子其将来。今子皮实来，小人失望。」大叔曰：「吉贱，不获来，畏大国，尊夫人也。且孟曰：『而将无事。』吉庶几焉。」
小邾穆公来朝。季武子欲卑之，穆叔曰：「不可。曹、滕、二邾，实不忘我好，敬以逆之，犹惧其贰。又卑一睦，焉逆群好也？其如旧而加敬焉！《志》曰：『能敬无灾。』又曰：『敬逆来者，天所福也。』」季孙从之。
八月，大雩，旱也。
齐侯田于莒，卢蒲弊见，泣且请曰：「余发如此种种，余奚能为？」公曰：「诺，吾告二子。」归而告之。子尾欲复之，子雅不可，曰：「彼其发短而心甚长，其或寝处我矣。」九月，子雅放卢蒲弊于北燕。
燕简公多嬖宠，欲去诸大夫而立其宠人。冬，燕大夫比以杀公之外嬖。公惧，奔齐。书曰：「北燕伯款出奔齐。」罪之也。
十月，郑伯如楚，子产相。楚子享之，赋《吉日》。既享，子产乃具田备，王以田江南之梦。
齐公孙灶卒。司马灶见晏子，曰：「又丧子雅矣。」晏子曰：「惜也！子旗不免，殆哉！姜族弱矣，而妫将始昌。二惠竞爽，犹可，又弱一个焉，姜其危哉！」', '', '', '三年春季，周王朝历法的正月，郑国的游吉到晋国去，为少姜送葬，梁丙和张趯拜见他。梁丙说：“太过分了，您为这件事情而来！”游吉说：“不得已呀！从前文公、襄公称霸的时候，他们的事情不烦劳诸侯。命令诸侯三年一聘问，五年一朝觐，有事就会见，不和睦就结盟。国君死，大夫吊唁，卿参加安葬。夫人死，士去吊唁，大夫送葬。只要发扬礼仪、发布命令，商量补救缺失就足够了，不再用额外的命令加于诸侯。现在宠姬的丧事，别国不敢选择适当职位的人参加丧礼，而且礼数超过正夫人，惟恐得到罪过，岂敢怕麻烦？少姜得到宠爱而死，齐国必然继续送女子前来。现在我又一次将要来祝贺，不仅是这一趟啊。”张趯说：“好啊，我能够听到这样的礼数！然而从今以后您大约没有这样的事情了。譬如大火星，它在天空正中，寒气或者暑气就要消退。这一次就是极点，能够不衰退吗？晋国将会失去诸侯的拥护，诸侯想要麻烦还得不到呢。”两位大夫退出。游吉告诉别人说：“张趯明白事理，也许还是跟在君子的行列里吧！”
正月二十四日，滕成公原死了。由于是同盟国家，所以《春秋》记载他的名字。
齐景公派晏婴请求继续送女子到晋国，说：“寡君派遣婴的时候说：‘寡人愿意奉事君王，早晚都不倦怠，要奉献财礼而不失去定时，然而由于国家多难，因此不能前来。先君的嫡女有幸在君王的内宫充数，照亮了寡人的希望，但又没有福气，过早地死去了，寡人失去了希望。君王如果不忘记先君的友好，加恩顾念齐国，对寡人和睦，求福于太公、丁公，光辉照耀敝邑，镇定安抚我们的国家，那么还有先君的嫡女和其余姑姐妹若干人。君王如果不抛弃敝邑，而派遣使者慎重选择，作为姬妾，这就是寡人的希望。’”韩宣子派叔向回答说：“这正是寡君的愿望。寡君不能单独承担国家大事，没有正式的配偶，由于在服丧期间，因此没有敢提出请求。君王有命令，没有比这再大的恩惠了。如果加恩顾念敝邑，安抚晋国，赐给晋国内主，岂独是寡君，所有的臣下都受到他的恩赐，从唐叔以下都会尊崇赞许他。”
订婚以后，晏子接受享礼，叔向陪他饮宴，互相谈话。叔向说：“齐国怎么样？”晏子说：“到了末世了，我不能不说齐国可能属于陈氏了。国君不爱护他的百姓，让他们归附陈氏。齐国过去有四种量器，豆、区、釜、钟。四升为一豆，各自再翻四倍，以成为一釜。十釜就是一钟。陈氏的豆、区、釜三种量器都加大四分之一，钟的容量就大了。他用私家的大量器借出，而用公家的小量器收回。山上的木料运到市场，价格不高于山上。鱼盐蜃蛤，价格不高于海边。百姓力量如果分为三份，两分归于国君，只有一份维持衣食。国君的积蓄腐朽生虫，而老人们却挨冻受饥。国都的市场上，鞋子便宜而假足昂贵。百姓有痛苦疾病，陈氏就厚加赏赐。他爱护百姓如同父母，而百姓归附如同流水。想要不得到百姓的拥护，哪里能避开？箕伯、直柄、虞遂、伯戏，他们跟随着胡公、太姬，已经在齐国了。”
叔向说：“是呀。即使是我们公室，现在也是末世了。战马不驾战车，卿不率领军队，公室的战车没有御者和戎右，步兵的行列没有长官。百姓困疲，而宫室更加奢侈。道路上饿死的人坟堆一个接着一个可以互相看见，而宠姬的家里财富特别多，百姓听到国君的命令，好像躲避仇敌一样。栾、郤、胥、原、狐、续、庆、伯这八家已经降为低贱吏役，政事在于私家，百姓无依无靠。国君毫不改悔，用欢乐来排遣忧患。公室的卑微，还能有几天？谗鼎上的铭文说，‘黎明即起，声名可以显赫，子孙后代还会懈怠’，何况毫不改悔，他能够长久吗？”
晏子说：“您打算怎么办？”叔向说：“晋国的公族完结了。肸听说，公室将要卑微，它的宗族像树叶一样先落，公室就跟着凋零了。肸的一宗十一族，只有羊舌氏还在。肸又没有好儿子，公室又没有法度，得到善终就是侥幸，难道还会受到祭祀？”
当初，齐景公要为晏子更换住宅，说：“您的住房靠近市区，低湿狭小，喧闹多尘，不能居住，请您换到高爽明亮的房子里去。”晏子辞谢说：“君王的先臣住在这里，下臣不足以继承祖业，住在里边已经过分了。而且小人靠近市场，早晚能得到所需要的东西，这是小人的利益，岂敢麻烦邻里大众为我造新房子？”齐景公笑着说：“您靠近市场，知道物价的贵贱吗？”晏子回答说：“既然以它为利，哪能不知道呢？”景公说：“什么贵？什么贱？”当时，齐景公滥用刑罚，有出卖假腿的，所以晏子回答说：“假腿贵，鞋子贱。”晏子已经告诉国君，所以跟叔向说话的时候也谈到这个。齐景公为此就减省了刑罚。君子说：“仁人的话，它的利益多么广大啊！晏子一句话，齐侯就减省刑罚。《诗》说，‘君子如果喜悦，祸乱庶几乎很快停歇’，说的就是这个吧！”
等到晏子去晋国，齐景公更换他的住宅，回来，新屋就已经完工。晏子拜谢以后，就拆毁了新房而建造邻居的房屋，恢复如原来的一样，让原来的住户回来，说：“俗话说：‘不是住宅需要占卜，惟有邻居需要占卜。’这几位已经先占卜邻居了，违背占卜不祥。君子不去做不合礼的事情，小人不去做不祥的事情，这是古代的制度，我敢违背它吗？”终于恢复了旧居。齐景公开始不允许，晏子托除桓子代为请求，齐景公才允许了。
夏季，四月，郑简公到晋国，公孙段作为相礼者，很恭敬而卑躬屈节，礼仪没有违背的。晋平公赞许，把策书授给公孙段，说：“子丰在晋国有过功劳，我听说了以后不会忘记。赐给你州县的土田，以报答你们过去的勋劳。”公孙段再拜叩头，接受了策书而去，君子说：“礼仪，大约是人所急迫需要的吧！公孙段这样骄傲，一旦在晋国有了礼仪，尚且承受了它的福禄，何况始终都有礼仪呢？《诗》说，‘人没有礼仪，为什么不快点死’，说的就是这个吧！”
当初，州县是栾豹的采邑。等到栾氏灭亡，范宣子、赵文子、韩宣子都想要这块地方。赵文子说：“温县，是我的县。”两个宣子说：“从郤称划分州县以来，已经传了三家了。晋国把一县划分为二的不仅只州县，谁能够按划分前的情况去治理它？”赵文子感到惭愧，就放弃了州县。两个宣子说：“我们不能口头上公正，而把好处给自己。”就都放弃了。等到赵文子执政，赵获说：“可以把州县拿过来了。”赵文子说：“出去！这两位的话，是合于道义的。违背道义，就是祸患。我不能治理我的封邑，又哪里用得着州县，而去自找祸患？君子说：‘不知道祸患是很难的。’知道了不照着做，没有比这再大的祸患了。再有人提到州县的一定处死！”
丰氏原来住在韩氏家里，公孙段得到州县，是韩宣子为公孙段请求的，这是为了他可以再次取得州县的缘故。
五月，叔弓到滕国去，参加滕成公的葬礼，子服椒作为副手。到达郊外，碰上懿伯的忌日，叔弓便不进入滕国。子服椒说：“公家的事情只能考虑公家的利益，没有私家的忌避。椒请求先进入。”于是就先住进宾馆。叔弓听从了他的意见。
晋国的韩起到齐国迎接齐女。公孙虿因为少姜受到宠爱，把他的女儿更换了齐景公的女儿，而把齐景公的女儿嫁给别人。别人对韩宣子说：“子尾欺骗晋国，晋国为什么接受？”韩宣子说：“我们想要得到齐国，却反而疏远他的宠臣，宠臣能够来吗？”
秋季，七月，郑国的罕虎到晋国去，祝贺夫人，并且报告说：“楚国人每天来问敝邑不去朝贺他们新立国君的原因。如果敝邑派人前去，就害怕执事会说寡君本来就有心向外。如果不去，那么在宋国的盟约又规定了是要去朝见的。进退都是罪过。寡君派虎前来陈述。”宣子派叔向回答说：“君王如果心向着寡君，在楚国有什么害处？这是为了重修在宋国盟会的友好。君王如果想到盟约，寡君就知道可以免于罪过了。君王如果心中没有寡君，虽然早晚光临敝邑，寡君也会猜疑的。君王果真实心向寡君，何必来告诉寡君。君王还是前去吧！如果心向寡君，在楚国在晋国都是一样的。”
张趯派人对太叔说：“自从您回去以后，小人扫除先人的破旧房子，说，‘您可能会来的。’现在子皮来了，小人失去了希望。”太叔说：“吉的地位低下，不能前来，这是由于害怕大国、尊敬夫人的缘故。而且孟说‘你将要没事了’，吉大概没事了。”
小邾穆公前来朝见，季武子不想用诸侯的礼仪接待他。穆叔说：“不行。曹国、滕国和两个邾国确实没有忘记和我国的友好，恭恭敬敬的迎接他，还害怕他有二心，反而又降低一个友好国家的地位，怎么能迎接许多友好国家呢？还是像过去一样更加恭敬些。《志》说：‘能够恭敬没有灾祸。’又说：‘恭敬地迎接前来的人，这就是上天降福的原因。’”季孙听从了他的话。
八月，举行大雩祭，这是由于旱灾的缘故。
齐景公在莒地打猎，卢蒲嫳进见，哭泣，而且请求说：“我的头发这么短，我还能做什么？”齐景公说：“好。我告诉那两位。”回去以后就告诉了子尾和子雅。子尾想要让他官复原位，子雅不同意，说：“他的头发短，心计长，他也许要睡在我的皮上了。”九月，子雅把卢蒲嫳放逐到北燕。
燕简公有很多宠爱的人，想要去掉大夫们而立宠臣为大夫。冬季，燕国的大夫们勾结起来杀死了简公的宠臣。简公害怕，逃亡到齐国。《春秋》记载说“北燕伯款出奔齐”，这是说他有罪。
十月，郑简公去到楚国，子产作为相礼者。楚灵王设享礼招待郑简公，赋《吉日》这首诗。享礼结束，子产就准备了打猎用具，楚灵王和郑简公在江南的云梦打猎。
齐国的公孙灶死了。司马灶进见晏子，说：“又失去了子雅了。”晏子说：“可惜啊！子旗不能免于祸患，危险啊！姜族削弱了，而妫氏将要开始昌盛。惠公的两个子孙刚强明白，还可以维持姜氏，又丧失了一个，姜氏恐怕危险呀！”', NULL, '', 'indent', 1559126331, '5cedf0b77b968a00767d44f9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643083, '左传 · 定公 · 定公二年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二年春王正月。夏五月壬辰，雉门及两观灭。秋，楚人伐吴。冬十月，新作雉门及两观。
【传】二年夏四月辛酉，巩氏之群子弟贼简公。
桐叛楚。吴子使舒鸠氏诱楚人，曰：「以师临我，我伐桐，为我使之无忌。」
秋，楚囊瓦伐吴，师于豫章。吴人见舟于豫章，而潜师于巢。冬十月，吴军楚师于豫章，败之。遂围巢，克之，获楚公子繁。
邾庄公与夷射姑饮酒，私出。阍乞肉焉。夺之杖以敲之。', '', '', '', NULL, '', 'indent', 1559211544, '5cef3d9430863b0068663578', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643053, '左传 · 昭公 · 昭公四年', NULL, 2, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】四年春王正月，大雨雹。夏，楚子、蔡侯、陈侯、郑伯、许男、徐子、滕子、顿子、胡子、沈子、小邾子、宋世子佐、淮夷会于申。楚子执徐子。秋七月，楚子、蔡侯、陈侯、许男、顿子、胡子、沈子、淮夷伐吴，执齐庆封，杀之。遂灭赖。九月，取鄫。冬十有二月乙卯，叔孙豹卒。
【传】四年春，王正月，许男如楚，楚子止之，遂止郑伯，复田江南，许男与焉。使椒举如晋求诸侯，二君待之。椒举致命曰：「寡君使举曰：『日君有惠，赐盟于宋，曰：晋、楚之从，交相见也。以岁之不易，寡人愿结欢于二三君。』使举请间。君若苟无四方之虞，则愿假宠以请于诸侯。」
晋侯欲勿许。司马侯曰：「不可。楚王方侈，天或者欲逞其心，以厚其毒而降之罚，未可知也。其使能终，亦未可知也。晋、楚唯天所相，不可与争。君其许之，而修德以待其归。若归于德，吾犹将事之，况诸侯乎？若适淫虐，楚将弃之，吾又谁与争？」曰：「晋有三不殆，其何敌之有？国险而多马，齐、楚多难。有是三者，何乡而不济？」对曰：「恃险与马，而虞邻国之难，是三殆也。四岳、三涂、阳城、大室、荆山、中南，九州之险也，是不一姓。冀之北土，马之所生，无兴国焉。恃险与马，不可以为固也，从古以然。是以先王务修德音以亨神人，不闻其务险与马也。邻国之难，不可虞也。或多难以固其国，启其疆土；或无难以丧其国，失其守宇。若何虞难？齐有仲孙之难而获桓公，至今赖之。晋有里、丕之难而获文公，是以为盟主。卫、邢无难，敌亦丧之。故人之难，不可虞也。恃此三者，而不修政德，亡于不暇，又何能济？君其许之！纣作淫虐，文王惠和，殷是以陨，周是以兴，夫岂争诸侯？」乃许楚使。使叔向对曰：「寡君有社稷之事，是以不获春秋时见。诸侯，君实有之，何辱命焉？」椒举遂请昏，晋侯许之。
楚子问于子产曰：「晋其许我诸侯乎？」对曰：「许君。晋君少安，不在诸侯。其大夫多求，莫匡其君。在宋之盟，又曰如一，若不许君，将焉用之？」王曰：「诸侯其来乎？」对曰：「必来。从宋之盟，承君之欢，不畏大国，何故不来？不来者，其鲁、卫、曹、邾乎？曹畏宋，邾畏鲁，鲁、卫逼于齐而亲于晋，唯是不来。其馀，君之所及也，谁敢不至？」王曰：「然则吾所求者，无不可乎？」对曰：「求逞于人，不可；与人同欲，尽济。」
大雨雹。季武子问于申丰曰：「雹可御乎？」对曰：「圣人在上，无雹，虽有，不为灾。古者，日在北陆而藏冰；西陆，朝觌而出之。其藏冰也，深山穷谷，固阴冱寒，于是乎取之。其出之也，朝之禄位，宾食丧祭，于是乎用之。其藏之也，黑牲、秬黍，以享司寒。其出之也，桃弧、棘矢，以除其灾。其出入也时。食肉之禄，冰皆与焉。大夫命妇，丧浴用冰。祭寒而藏之，献羔而启之，公始用之。火出而毕赋。自命夫、命妇，至于老疾，无不受冰。山人取之，县人传之，舆人纳之，隶人藏之。夫冰以风壮，而以风出。其藏之也周，其用之也遍，则冬无愆阳，夏无伏阴，春无凄风，秋无苦雨，雷不出震，无灾霜雹，疠疾不降，民不夭札。今藏川池之冰，弃而不用。风不越而杀，雷不发而震。雹之为灾，谁能御之？《七月》之卒章，藏冰之道也。」
夏，诸侯如楚，鲁、卫、曹、邾不会。曹、邾辞以难，公辞以时祭，卫侯辞以疾。郑伯先待于申。六月丙午，楚子合诸侯于申。椒举言于楚子曰：「臣闻诸侯无归，礼以为归。今君始得诸侯，其慎礼矣。霸之济否，在此会也。夏启有钧台之享，商汤有景亳之命，周武有孟津之誓，成有岐阳之搜，康有酆宫之朝，穆有涂山之会，齐桓有召陵之师，晋文有践土之盟。君其何用？宋向戌、郑公孙侨在，诸侯之良也，君其选焉。」王曰：「吾用齐桓。」王使问礼于左师与子产。左师曰：「小国习之，大国用之，敢不荐闻？」献公合诸侯之礼六。子产曰：「小国共职，敢不荐守？」献伯、子、男会公之礼六。君子谓合左师善守先代，子产善相小国。王使椒举侍于后，以规过。卒事，不规。王问其故，对曰：「礼，吾所未见者有六焉，又何以规？」宋大子佐后至，王田于武城，久而弗见。椒举请辞焉。王使往，曰：「属有宗祧之事于武城，寡君将堕币焉，敢谢后见。」
徐子，吴出也，以为贰焉，故执诸申。
楚子示诸侯侈，椒举曰：「夫六王二公之事，皆所以示诸侯礼也，诸侯所由用命也。夏桀为仍之会，有婚叛之。商纣为黎之搜，东夷叛之。周幽为大室之盟，戎狄叛之。皆所以示诸侯汰也，诸侯所由弃命也。今君以汰，无乃不济乎？」王弗听。
子产见左师曰：「吾不患楚矣，汰而愎谏，不过十年。」左师曰：「然。不十年侈，其恶不远，远恶而后弃。善亦如之，德远而后兴。」
秋七月，楚子以诸侯伐吴。宋大子、郑伯先归。宋华费遂、郑大夫从。使屈申围朱方，八月甲申，克之。执齐庆封而尽灭其族。将戮庆封。椒举曰：「臣闻无瑕者可以戮人。庆封唯逆命，是以在此，其肯从于戮乎？播于诸侯，焉用之？」王弗听，负之斧钺，以徇于诸侯，使言曰：「无或如齐庆封，弑其君，弱其孤，以盟其大夫。」庆封曰：「无或如楚共王之庶子围，弑其君、兄之子麇而代之，以盟诸侯。」王使速杀之。
遂以诸侯灭赖。赖子面缚衔璧，士袒，舆榇从之，造于中军。王问诸椒举，对曰：「成王克许，许僖公如是，王亲释其缚，受其璧，焚其榇。」王从之。迁赖于鄢。楚子欲迁许于赖，使斗韦龟与公子弃疾城之而还。申无宇曰：「楚祸之首，将在此矣。召诸侯而来，伐国而克，城竟莫校。王心不违，民其居乎？民之不处，其谁堪之？不堪王命，乃祸乱也。」
九月，取鄫，言易也。莒乱，着丘公立而不抚鄫，鄫叛而来，故曰取。凡克邑不用师徒曰取。
郑子产作丘赋。国人谤之，曰：「其父死于路，己为虿尾。以令于国，国将若之何？」子宽以告。子产曰：「何害？苟利社稷，死生以之。且吾闻为善者不改其度，故能有济也。民不可逞，度不可改。《诗》曰：『礼义不愆，何恤于人言。』吾不迁矣。浑罕曰：「国氏其先亡乎！君子作法于凉，其敝犹贪。作法于贪，敝将若之何？姬在列者，蔡及曹、滕其先亡乎！逼而无礼。郑先卫亡，逼而无法。政不率法，而制于心。民各有心，何上之有？」
冬，吴伐楚，入棘、栎、麻，以报朱方之役。楚沈尹射奔命于夏汭，咸尹宜咎城钟离，薳启强城巢，然丹城州来。东国水，不可以城。彭生罢赖之师。
初，穆子去叔孙氏，及庚宗，遇妇人，使私为食而宿焉。问其行，告之故，哭而送之。适齐，娶于国氏，生孟丙、仲壬。梦天压己，弗胜。顾而见人，黑而上偻，深目而豭喙。号之曰：「牛！助余！」乃胜之。旦而皆召其徒，无之。且曰：「志之。」及宣伯奔齐，馈之。宣伯曰：「鲁以先子之故，将存吾宗，必召女。召女，何如？」对曰：「愿之久矣。」鲁人召之，不告而归。既立，所宿庚宗之妇人，献以雉。问其姓，对曰：「余子长矣，能奉雉而从我矣。」召而见之，则所梦也。未问其名，号之曰：「牛！」曰：「唯」。皆召其徒，使视之，遂使为竖。有宠，长使为政。公孙明知叔孙于齐，归，未逆国姜，子明取之。故怒，其子长而后使逆之。田于丘莸，遂遇疾焉。竖牛欲乱其室而有之，强与孟盟，不可。叔孙为孟钟，曰：「尔未际，飨大夫以落之。」既具，使竖牛请日。入，弗谒。出，命之日。及宾至，闻钟声。牛曰：「孟有北妇人之客。」怒，将往，牛止之。宾出，使拘而杀诸外，牛又强与仲盟，不可。仲与公御莱书观于公，公与之环。使牛入示之。入，不示。出，命佩之。牛谓叔孙：「见仲而何？」叔孙曰：「何为？」曰：「不见，既自见矣。公与之环而佩之矣。」遂逐之，奔齐。疾急，命召仲，牛许而不召。
杜泄见，告之饥渴，授之戈。对曰：「求之而至，又何去焉？」竖牛曰：「夫子疾病，不欲见人。」使置馈于个而退。牛弗进，则置虚，命彻。十二月癸丑，叔孙不食。乙卯，卒。牛立昭子而相之。
公使杜泄葬叔孙。竖牛赂叔仲昭子与南遗，使恶杜泄于季孙而去之。杜泄将以路葬，且尽卿礼。南遗谓季孙曰：「叔孙未乘路，葬焉用之？且冢卿无路，介卿以葬，不亦左乎？」季孙曰：「然。」使杜泄舍路。不可，曰：「夫子受命于朝，而聘于王。王思旧勋而赐之路。覆命而致之君，君不敢逆王命而复赐之，使三官书之。吾子为司徒，实书名。夫子为司马，与工正书服。孟孙为司空，以书勋。今死而弗以，同弃君命也。书在公府而弗以，是废三官也。若命服，生弗敢服，死又不以，将焉用之？」乃使以葬。
季孙谋去中军。竖牛曰：「夫子固欲去之。」', '', '', '', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f7a2cee9a0c24ee78c1", "shortContent": "《韩凭妻》是干宝《搜神记》中的名篇之一，它不仅本身具有比较完整的文学价值，而且对后世的文学创作也有一定影响。例如，唐代敦煌俗文学中的《韩朋赋》就是根据它创作出来的。\n《韩凭妻》的主题，自然是写反抗暴君的斗争。在历史上，战国后期的宋康王本来就是一个穷兵黩武、暴戾恣睢的典型的暴君，在诸侯间有“桀宋”之称。这里写他为了满足淫欲，竟然强夺臣民之妻，把何氏占为己有；韩凭怨忿，又被他囚为城旦。仅此一事，这个暴...", "authors": ["范民声"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559126360, '5cedf0d3a673f500682d7539', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643054, '左传 · 昭公 · 昭公五年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】五年春王正月，舍中军。楚杀其大夫屈申。公如晋。夏，莒牟夷以牟娄及防、兹来奔。秋七月，公至自晋。戊辰，叔弓帅师败莒师于蚡泉。秦伯卒。冬，楚子、蔡侯、陈侯、许男、顿子、沈子、徐人、越人伐吴。
【传】五年春，王正月，舍中军，卑公室也。毁中军于施氏，成诸臧氏。初作中军，三分公室而各有其一。季氏尽征之，叔孙氏臣其子弟，孟氏取其半焉。及其舍之也，四分公室，季氏择二，二子各一。皆尽征之，而贡于公。以书。使杜泄告于殡，曰：「子固欲毁中军，既毁之矣，故告。」杜泄曰：「夫子唯不欲毁也，故盟诸僖闳，诅诸五父之衢。」受其书而投之，帅士而哭之。叔仲子谓季孙曰：「带受命于子叔孙曰：『葬鲜者自西门。』」季孙命杜泄。杜泄曰：「卿丧自朝，鲁礼也。吾子为国政，未改礼，而又迁之。群臣惧死，不敢自也。」既葬而行。
仲至自齐，季孙欲立之。南遗曰：「叔孙氏厚则季氏薄。彼实家乱，子勿与知，不亦可乎？」南遗使国人助竖牛以攻诸大库之庭。司宫射之，中目而死。竖牛取东鄙三十邑，以与南遗。
昭子即位，朝其家众，曰：「竖牛祸叔孙氏，使乱大从，杀适立庶，又披其邑，将以赦罪，罪莫大焉。必速杀之。」竖牛惧，奔齐。孟、仲之子杀诸塞关之外，投其首于宁风之棘上。
仲尼曰：「叔孙昭子之不劳，不可能也。周任有言曰：『为政者不赏私劳，不罚私怨。』《诗》云：『有觉德行，四国顺之。』」
初，穆子之生也，庄叔以《周易》筮之，遇《明夷》三之《谦》三，以示卜楚丘。曰：「是将行，而归为子祀。以谗人入，其名曰牛，卒以馁死。《明夷》，日也。日之数十，故有十时，亦当十位。自王已下，其二为公，其三为卿。日上其中，食日为二，旦日为三。《明夷》之《谦》，明而未融，其当旦乎，故曰：『为子祀』。日之《谦》，当鸟，故曰『明夷于飞』。明之未融，故曰『垂其翼』。象日之动，故曰『君子于行』。当三在旦，故曰『三日不食』。《离》，火也。《艮》，山也。《离》为火，火焚山，山败。于人为言，败言为谗，故曰『有攸往，主人有言』，言必谗也。纯《离》为牛，世乱谗胜，胜将适《离》，故曰『其名曰牛』。谦不足，飞不翔，垂不峻，翼不广，故曰『其为子后乎』。吾子，亚卿也，抑少不终。」
楚子以屈申为贰于吴，乃杀之。以屈生为莫敖，使与令尹子荡如晋逆女。过郑，郑伯劳子荡于汜，劳屈生於菟氏。晋侯送女于邢丘。子产相郑伯，会晋侯于邢丘。
公如晋，自郊劳至于赠贿，无失礼。晋侯谓女叔齐曰：「鲁侯不亦善于礼乎？」对曰：「鲁侯焉知礼？」公曰：「何为？自郊劳至于赠贿，礼无违者，何故不知？」对曰：「是仪也，不可谓礼。礼所以守其国，行其政令，无失其民者也。今政令在家，不能取也。有子家羁，弗能用也。奸大国之盟，陵虐小国。利人之难，不知其私。公室四分，民食于他。思莫在公，不图其终。为国君，难将及身，不恤其所。礼这本末，将于此乎在，而屑屑焉习仪以亟。言善于礼，不亦远乎？君子谓：「叔侯于是乎知礼。」
晋韩宣子如楚送女，叔向为介。郑子皮、子大叔劳诸索氏。大叔谓叔向曰：「楚王汰侈已甚，子其戒之。」叔向曰：「汰侈已甚，身之灾也，焉能及人？若奉吾币帛，慎吾威仪，守之以信，行之以礼，敬始而思终，终无不复，从而不失仪，敬而不失威，道之以训辞，奉之以旧法，考之以先王，度之以二国，虽汰侈，若我何？」
及楚，楚子朝其大夫，曰：「晋，吾仇敌也。苟得志焉，无恤其他。今其来者，上卿、上大夫也。若吾以韩起为阍，以羊舌肸为司宫，足以辱晋，吾亦得志矣。可乎？」大夫莫对。薳启强曰：「可。苟有其备，何故不可？耻匹夫不可以无备，况耻国乎？是以圣王务行礼，不求耻人，朝聘有珪，享《兆见》有璋。小有述职，大有巡功。设机而不倚，爵盈而不饮；宴有好货，飧有陪鼎，入有郊劳，出有赠贿，礼之至也。国家之败，失之道也，则祸乱兴。城濮之役，晋无楚备，以败于邲。邲之役，楚无晋备，以败于鄢。自鄢以来，晋不失备，而加之以礼，重之以睦，是以楚弗能报而求亲焉。既获姻亲，又欲耻之，以召寇仇，备之若何？谁其重此？若有其人，耻之可也。若其未有，君亦图之。晋之事君，臣曰可矣：求诸侯而麇至；求昏而荐女，君亲送之，上卿及上大夫致之。犹欲耻之，君其亦有备矣。不然，奈何？韩起之下，赵成、中行吴、魏舒、范鞅、知盈；羊舌肸之下，祁午、张趯、籍谈、女齐、梁丙、张骼、辅跞、苗贲皇，皆诸侯之选也。韩襄为公族大夫，韩须受命而使矣。箕襄、邢带、叔禽、叔椒、子羽，皆大家也。韩赋七邑，皆成县也。羊舌四族，皆强家也。晋人若丧韩起、杨肸，五卿八大夫辅韩须、杨石，因其十家九县，长毂九百，其馀四十县，遗守四千，奋其武怒，以报其大耻，伯华谋之，中行伯、魏舒帅之，其蔑不济矣。君将以亲易怨，实无礼以速寇，而未有其备，使群臣往遗之禽，以逞君心，何不可之有？」王曰：「不谷之过也，大夫无辱。」厚为韩子礼。王欲敖叔向以其所不知，而不能，亦厚其礼。
韩起反，郑伯劳诸圉。辞不敢见，礼也。
郑罕虎如齐，娶于子尾氏。晏子骤见之，陈桓子问其故，对曰：「能用善人，民之主也。」
夏，莒牟夷以牟娄及防兹来奔。牟夷非卿而书，尊地也。莒人愬于晋。晋侯欲止公，范献子曰：「不可。人朝而执之，诱也。讨不以师，而诱以成之，惰也。为盟主而犯此二者，无乃不可乎？请归之，间而以师讨焉。」乃归公。秋七月，公至自晋。
莒人来讨，不设备。戊辰，叔弓败诸□分泉，莒未陈也。
冬十月，楚子以诸侯及东夷伐吴，以报棘、栎、麻之役。薳射以繁扬之师，会于夏汭。越大夫常寿过帅师会楚子于琐。闻吴师出，薳启强帅师从之，遽不设备，吴人败诸鹊岸。
楚子以馹至于罗汭。吴子使其弟蹶由犒师，楚人执之，将以衅鼓。王使问焉，曰：「女卜来吉乎？」对曰：「吉。寡君闻君将治兵于敝邑，卜之以守龟，曰：『余亟使人犒师，请行以观王怒之疾徐，而为之备，尚克知之。』龟兆告吉，曰：『克可知也。』君若欢焉，好逆使臣，滋邑休殆，而忘其死，亡无日矣。今君奋焉，震电冯怒，虐执使臣，将以衅鼓，则吴知所备矣。敝邑虽羸，若早修完，其可以息师。难易有备，可谓吉矣。且吴社稷是卜，岂为一人？使臣获衅军鼓，而敝邑知备，以御不虞，其为吉孰大焉？国之守龟，其何事不卜？一臧一否，其谁能常之？城濮之兆，其报在邲。今此行也，其庸有报志？」乃弗杀。
楚师济于罗汭，沈尹赤会楚子，次于莱山。薳射帅繁扬之师，先入南怀，楚师从之。及汝清，吴不可入。楚子遂观兵于坻箕之山。是行也，吴早设备，楚无功而还，以蹶由归。楚子惧吴，使沈尹射待命于巢。薳启强待命于雩娄。礼也。
秦后子复归于秦，景公卒故也。', '', '', '五年春季，周王朝历法的正月，废除中军，这是为了降低公室的地位。在施氏家里讨论废除，在臧氏家里达成协议。开始编定中军的时候，把公室的军队一分为三而各家掌握一军。季氏掌握的公室军队采用征兵或者征税的方式，叔孙氏让壮丁作为奴隶，老弱的作为自由民，孟氏则把一半作为奴隶，一半作为自由民。等到这次废除中军，就把公室的军队一分为四，季氏择取了四分之二，叔孙氏、孟氏各有四分之一。全都改为征兵或者征税，而向昭公交纳贡赋。季氏用策书让杜泄向叔孙的棺材报告说：“您本来要废除中军，现在已经废除了，所以向您报告。”杜泄说：“他老人家正因为不想废掉中军，所以在僖公宗庙前门口盟誓，在五父之衢诅咒。”接了策书扔在地上，率领他手下人哭泣起来。叔仲子对季孙说：“带从子叔孙那里接受命令，说，安葬不是寿终的人从西门出去。”季孙命令杜泄执行。杜泄说：“卿的丧礼从朝门出去，这是鲁国的礼仪。您主持国政，没有正式修改礼仪而现在又自己加以改变。下臣们害怕被杀戮，不敢服从。”安葬完毕就出走了。
仲壬从齐国来到，季孙想要立他为叔孙的继承人。南遗说：“叔孙氏势力强大，季氏势力削弱。他发生家乱，您不要参予，不也是可以的吗？”南遗让国内人们帮助竖牛在府库的庭院里攻打仲壬。司宫用箭射仲壬，射中眼睛死了。竖牛取得了东部边境的三十个城邑，把它送给了南遗。
昭子即位，召集他家族上下人等来朝见，说：“竖牛给叔孙氏造成祸乱，搅乱了重大的正常秩序，杀死嫡子立庶子，又分裂封邑，将要以此逃避罪责，罪过没有比这再大的了。一定要赶紧杀死他！”竖牛害怕，出奔齐国。孟丙、仲壬的儿子把他杀死在塞关之外，把脑袋扔在宁风的荆棘上。
孔子说：“叔孙昭子不酬劳竖牛，这是一般人做不到的。周任有话说：‘掌握政权的人不赏赐对于私人的功劳，不惩罚个人的怨恨。’《诗》说：‘具有正直的德行，四方的国家都来归顺。’”
当初，穆子出生的时候，庄叔用《周易》来卜筮，得到《明夷》变成《谦》，把卦像给卜楚丘看。楚丘说：“这个孩子将会出奔，而又能回来为您祭祀。领着坏人回来，他名叫牛，这个孩子最终以饥饿而死。《明夷》，是日。日的数目是十，所以有十时，也和十日的位次相配。从王以下，第二位是公，第三位是卿。日从地下上升，这个时候最为尊贵，露一点头是第二，刚刚升起是第三。《明夷》变为《谦》，已经明亮然而不高，大概是正相当于刚刚升起的时候吧，所以说可以继承卿位为您祭祀。日变为《谦》，和鸟相配，所以说《明夷》飞翔。已经明亮然而不高，所以说垂下它的翅膀。像征日的运动，所以说君子在路上。位在刚刚升起的时候相当于第三，所以说三天不吃饭。《离》，是火。《艮》，是山。《离》是火，火烧山，山就毁坏。《艮》对人来说就是语言。毁坏语言就是诬罔，所以说有人离开。主人有话，这话一定是诬罔，配合《离》的是牛，世道动乱而诬罔得到胜利，胜利将会归向于《离》，所以说他名叫牛。《谦》就是不满足，所以虽然能飞而不能回旋，下垂就是不高，所以虽有翅膀而不能飞行高远。所以说大约是您的继承人吧。您，是副卿，但是继承人虽老却有点不得善终。”
楚灵王认为屈申倾向吴国，就杀了他。让屈生做莫敖，派他和令尹子荡到晋国迎接晋女。经过郑国，郑简公在汜地慰劳子荡，在菟氏慰劳屈生。晋平公送女儿到邢丘，子产辅佐郑简公在邢丘会见晋平公。
鲁昭公去到晋国，从郊外慰劳一直到赠送财货，从没有失礼。晋平公对女叔齐说：“鲁侯不也是很懂礼吗？”女叔齐回答说：“鲁侯哪里懂得礼！”晋平公说：“为什么？从郊外慰劳一直到赠送财货，没有违背礼节，为什么不懂得？”女叔齐回答说：“这是仪式，不能说是礼。礼，是用来保有国家、推行政令，不失去百姓的。现在政令在于私家，不能拿回来。有子家羁，不能任用。触犯大国的盟约，欺侮虐待小国。利用别人的危难，却不知道自己也有危难。公室的军队一分为四，百姓靠三家大夫生活。民心不在国君，国君不考虑后果。做为一个国君，危难将要到他身上，却不去忧虑他的地位。礼的根本和枝节在于此，他却琐琐屑屑地急于学习仪式。说他懂得礼，不也是距离太远了吗？”君子认为：“女叔齐在这里是懂得礼的。”
晋国的韩宣子去到楚国护送晋女，叔向做副手。郑国的子皮、子太叔在索氏慰劳他们。太叔对叔向说：“楚王骄纵太过分，您还是警惕一点。”叔向说：“骄纵太过分是自身的灾殃，哪能波及到别人？只要奉献我们的财礼，谨慎地保持我们的威仪，守信用，行礼仪，开始恭敬而考虑结果，以后就可以照样办。顺从而不过度，恭敬而有节制，以古圣先贤的言语作为引导，对传统的法度加以奉行，考核先王的事情，把两国的利害得失加以衡量，楚王虽然骄纵，能把我怎么样？”
到了楚国，楚灵王让大夫们上朝，说：“晋国，是我们的仇敌。如果我们能够满足愿望，就不用顾虑其他。现在他们来的人，是上卿、上大夫。假使我们让韩起做守门人，让叔向做内宫司宫，这足以羞辱晋国，我们也满足了愿望。行吗？”大夫没有一个人回答。薳启彊说：“行。如果有防备，为什么不行？羞辱一个普通人还不能不作防备，何况羞辱一个国家呢？因此圣王致力于推行礼仪，不想羞辱别人。朝觐聘问有圭，宴享进见有璋，小国有述职的规定，大国有巡狩的制度。设置了几而不依靠，爵中酒满而不饮用，宴会时有友好的礼品，吃饭时有很多的菜肴。入境有郊外的慰劳，离开有赠送的财货，这都是礼仪的最高形式。国家的败亡，由于失去了这种常道，祸乱就会发生。城濮那次战役，晋国得胜而没有防备楚国，因此在邲地打了败仗。邲地那次战役，楚国得胜而没有防备晋国，因此在鄢地打了败仗。自从鄢地战役以来，晋国没有丧失防备，而且对楚国礼仪有加，以和睦为重，因此楚国不能报复，而只能请求亲善了。既然得到了婚姻的亲戚关系，又想要羞辱他们，以自寻敌人，又怎么防备它？谁来承担责任？如果有能承担责任的人，羞辱他们是可以的。如果没有，君王还是考虑一下。晋国的事奉君王，下臣认为很可以了。要求得到诸侯就大家都来了，求婚就进奉女子。国君亲自送她，上卿和上大夫送到我国。如果还要羞辱他们，君王恐怕也要有所防备。不这样，怎么办？韩起的下面，有赵成、中行吴、魏舒、范鞅、知盈；叔向的下面，有祁午、张趯、籍谈、女齐、梁丙、张骼、辅跞、苗贲皇，都是诸侯所选拔的能人。韩襄做公族大夫，韩须接受命令而出使了。箕襄、邢带、叔禽、叔椒、子羽，都是大家族。韩氏征收赋税的七个城邑，都是大县。羊舌氏四族，都是强盛的家族。晋国人如果丧失韩起、叔向，五卿、八大夫辅助韩须、杨石，靠了他们的十家九县，战车九百辆，其余四十具，留守的战车有四千辆，发扬他们的勇武，发泄他们的愤怒，以报复他们的奇耻大辱。伯华为他们出谋划策，中行伯、魏舒率领他们，就没有不成功的了。君王将要把亲善换成怨恨，确实违背礼仪以招致敌人，而又没有应有的防备，让下臣们去当俘虏以满足君王的心意，有什么不可以呢？”楚灵王说：“这是我的过错，大夫不用再说了。”对韩起厚加礼遇，楚灵王想要用叔向不知道的事物来为难他，没有做到，于是也对他厚加优礼。
韩起回国，郑简公在圉地慰劳他。他辞谢不敢进见，这是合于礼的。
郑国的罕虎到齐国去，在子尾氏那里娶亲。晏子屡次进见。陈桓子问什么缘故，晏子回答说：“他能够任用好人，是百姓的主人。”
夏季，莒国的牟夷带了牟娄和防地、兹地逃亡前来。牟夷不是卿，但《春秋》加以记载，这是由于重视这些地方。莒人向晋国起诉，晋平公想要扣留昭公。范献子说：“不行。别人来朝见而囚禁人家，这就如同引诱。讨伐他不想用武力，而用引诱来取得成功，这是怠惰。做盟主而犯了这两条，恐怕不行吧！请让他回去，等有机会时再用武力去讨伐他们。”于是就让昭公回国了。秋季，七月，昭公从晋国回到鲁国。
莒国人前来攻打鲁国，但他们自己却不设防。十四日，叔弓在蚡泉击败了他们，这是由于莒国人没有摆开阵势的缘故。
冬季，十月，楚灵王带领诸侯和东夷的军队进攻吴国，以报复棘地、栎地、麻地的那次战役。薳射带领繁扬的军队在夏汭会师，越国的大夫常寿过领兵和楚王在琐地会合。听说吴军出动，薳启彊领兵迎战，匆忙中没有设防，吴国人在鹊岸击败了他。楚灵王乘坐驿车到达罗汭。
吴王派他的兄弟蹶由到楚营犒劳军队，楚国人把他抓起来，准备杀了他用血祭鼓。楚灵王派人询问，说：“你占卜过，来这里吉利吗？”蹶由回答说：“吉利。寡君听说君王将要向敝邑出兵，就用守龟占卜，致告龟甲说：‘我赶快派人去犒劳军队，请前去以观察楚王生气的大小而加以戒备，也许神能使我预先知道吉凶。’占卜的卦像告诉我们说吉利，说：‘得胜是可以预知的。’君王如果高高兴兴地迎接使臣，增加敝邑的懈怠而忘记危险，我们被灭亡就没有几天了。现在君王勃然大怒，虐待和逮捕使臣，将要用使臣的血来祭鼓，那么吴国就知道该怎么戒备了。敝邑虽然疲弱，如果早日修城郭备器用，也许可以阻止贵军的进攻。无论对患难还是平安都有准备，这可以说是吉利了。而且吴国为国家而占卜，难道是为了使臣一个人？使臣得以用血祭祀军鼓，而敝邑就知道防备，以抵御意外，难道说还有比这更大的吉利吗？国家的守护神龟，有什么事情不能占卜？一吉一凶，谁能够肯定落在哪件事情上？城濮的卦像，在邲城应验。现在这一趟出使，占卜的卦像也许会有应验的。”楚灵王于是就没有杀蹶由。
楚国的军队在罗汭渡河，沈尹赤和楚灵王会合，驻扎在莱山，薳射率领繁扬的军队先进入南怀，楚军跟上去。到达汝清，不能进入吴国。楚灵王就在坻箕之山检阅军队。这一次行动，吴国早已设防，楚国没有建功就回去了，带着蹶由回国。楚灵王惧怕吴国，派沈尹射在巢地待命，薳启彊在雩娄待命，这是合于礼的。
秦国的后子再次回到秦国，这是由于秦景公去世的缘故。', NULL, '', 'indent', 1559126430, '5cedf11a30863b0068555a63', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643055, '左传 · 昭公 · 昭公六年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】六年春王正月，杞伯益姑卒。葬秦景公。夏，季孙宿如晋。葬杞文公。宋华合比出奔卫。秋九月，大雩。楚薳罢帅师伐吴。冬，叔弓如楚。齐侯伐北燕。
【传】六年春，王正月，杞文公卒，吊如同盟，礼也。大夫如秦，葬景公，礼也。
三月，郑人铸刑书。叔向使诒子产书，曰：「始吾有虞于子，今则已矣。昔先王议事以制，不为刑辟，惧民之有争心也。犹不可禁御，是故闲之以义，纠之以政，行之以礼，守之以信，奉之以仁，制为禄位以劝其从，严断刑罚以威其淫。惧其未也，故诲之以忠，耸之以行，教之以务，使之以和，临之以敬，莅之以强，断之以刚。犹求圣哲之上，明察之官，忠信之长，慈惠之师，民于是乎可任使也，而不生祸乱。民知有辟，则不忌于上，并有争心，以征于书，而徼幸以成之，弗可为矣。夏有乱政而作《禹刑》，商有乱政而作《汤刑》，周有乱政而作《九刑》，三辟之兴，皆叔世也。今吾子相郑国，作封洫，立谤政，制参辟，铸刑书，将以靖民，不亦难乎？《诗》曰：『仪式刑文王之德，日靖四方。』又曰：『仪刑文王，万邦作孚。』如是，何辟之有？民知争端矣，将弃礼而征于书。锥刀之末，将尽争之。乱狱滋丰，贿赂并行，终子之世，郑其败乎！肸闻之，国将亡，必多制，其此之谓乎！」复书曰：「若吾子之言，侨不才，不能及子孙，吾以救世也。既不承命，敢忘大惠？」
士文伯曰：「火见，郑其火乎？火未出而作火以铸刑器，藏争辟焉。火如象之，不火何为？」
夏，季孙宿如晋，拜莒田也。晋侯享之，有加笾。武子退，使行人告曰：「小国之事大国也，苟免于讨，不敢求贶。得贶不过三献。今豆有加，下臣弗堪，无乃戾也。」韩宣子曰：「寡君以为欢也。」对曰：「寡君犹未敢，况下臣，君之隶也，敢闻加贶？」固请彻加而后卒事。晋人以为知礼，重其好货。
宋寺人柳有宠，大子佐恶之。华合比曰：「我杀之。」柳闻之，乃坎、用牲、埋书，而告公曰：「合比将纳亡人之族，既盟于北郭矣。」公使视之，有焉，遂逐华合比，合比奔卫。于是华亥欲代右师，乃与寺人柳比，从为之征，曰「闻之久矣。」公使代之，见于左师，左师曰：「女夫也。必亡！女丧而宗室，于人何有？人亦于女何有？《诗》曰：『宗子维城，毋俾城坏，毋独斯畏。』女其畏哉！」
六月丙戌，郑灾。
楚公子弃疾如晋，报韩子也。过郑，郑罕虎、公孙侨、游吉从郑伯以劳诸柤。辞不敢见，固请见之，见，如见王，以其乘马八匹私面。见子皮如上卿，以马六匹。见子产，以马四匹。见子大叔，以马二匹。禁刍牧采樵，不入田，不樵树，不采刈，不抽屋，不强丐。誓曰：「有犯命者，君子废，小人降。」舍不为暴，主不慁宾。往来如是。郑三卿皆知其将为王也。
韩宣子之适楚也，楚人弗逆。公子弃疾及晋竟，晋侯将亦弗逆。叔向曰：「楚辟我衷，若何效辟？《诗》曰：『尔之教矣，民胥效矣。』从我而已，焉用效人之辟？《书》曰：『圣作则。』无宁以善人为则，而则人之辟乎？匹夫为善，民犹则之，况国君乎？」晋侯说，乃逆之。
秋九月，大雩，旱也。
徐仪楚聘于楚。楚子执之，逃归。惧其叛也，使薳泄伐徐。吴人救之。令尹子荡帅师伐吴，师于豫章，而次于乾溪。吴人败其师于房钟，获宫厩尹弃疾。子荡归罪于薳泄而杀之。
冬，叔弓如楚聘，且吊败也。
十一月，齐侯如晋，请伐北燕也。士□相士鞅，逆诸河，礼也。晋侯许之。十二月，齐侯遂伐北燕，将纳简公。晏子曰：「不入。燕有君矣，民不贰。吾君贿，左右谄谀，作大事不以信，未尝可也。」', '', '', '六年春季，周王朝历法的正月，杞文公去世。鲁国前去吊唁好像对同盟的国家一样，这是合于礼的。鲁国大夫去到秦国，参加秦景公的葬礼，这是合于礼的。
三月，郑国把刑法铸在鼎上。叔向派人送给子产一封信，说：“开始我对您寄予希望，现在完了。从前先王衡量事情的轻重来断定罪行，不制定刑法，这是害怕百姓有争夺之心。还是不能防止犯罪，因此用道义来防范，用政令来约束，用礼仪来奉行，用信用来保持，用仁爱来奉养。制定禄位，以勉励服从的人，严厉地判罪，以威胁放纵的人。还恐怕不能收效，所以用忠诚来教诲他们，根据行为来奖励他们，用专业知识技艺教导他们，用和悦的态度使用他们，用严肃认真对待他们，用威严监临他们，用坚决的态度判断他们的罪行。还要访求聪明贤能的卿相、明白事理的官员、忠诚守信的乡长、慈祥和蔼的老师，百姓在这种情况下才可以使用，而不致于发生祸乱。百姓知道有法律，就对上面不恭敬。大家都有争夺之心，用刑法作为根据，而且侥幸得到成功，就不能治理了。夏朝有违犯政令的人，就制定禹刑。商朝有触犯政令的人，就制定汤刑。周朝有触犯政令的人，就制定九刑。三种法律的产生，都处于末世了。现在您辅佐郑国，划定田界水沟，设置毁谤政事的条例，制定三种法规，把刑法铸在鼎上，准备用这样的办法安定百姓，不也是很难的吗？《诗》说：‘效法文王的德行，每天抚定四方。’又说：‘效法文王，万邦信赖。’像这样，何必要有法律？百姓知道了争夺的依据，将会丢弃礼仪而征用刑书。刑书的一字一句，都要争个明白。触犯法律的案件更加繁多，贿赂到处使用。在您活着的时候，郑国恐怕要衰败吧！肸听说，‘国家将要灭亡，必然多订法律’，恐怕说的就是这个吧！”子产复信说：“像您所说的这样。侨没有才能，不能考虑到子孙，我是用来挽救当前的世界。既然不能接受您的命令，又岂敢忘了您的恩惠？”
士文伯说：“大火星出现，郑国恐怕会发生大火灾吧！大火星还没有出现，而使用火来铸造刑器，包藏着引起争论的法律。大火星如果象征这个，不引起火灾还能表示什么？”
夏季，季孙宿到晋国去，这是为了拜谢不讨伐占取莒国土田的缘故。晋平公设享礼招待他，有外加的菜肴。季孙宿退出，派行人报告说：“小国事奉大国，如果免于被讨伐。不敢再求赏赐。得到赏赐也不超过三献。现在菜肴有所增加，下臣不敢当，恐怕这是罪过。”韩宣子说：“寡君用它来讨取您的欢心。”季孙宿回答说：“寡君尚且不敢当，何况下臣是君王的奴隶，岂敢听到有外加多赏赐？”坚决请求撤去加菜，然后结束享宴。晋国人认为他懂得礼仪，在宴礼中重重地送给他财物。
宋国的寺人柳受到宋平公宠信，太子佐讨厌他。华合比说：“我去杀了他。”寺人柳听到了，就挖坑、杀牲口、把盟书放在牲口上埋起来。然后报告宋平公说：“合比准备将逃亡在外的人召回来，已经在北边外城结盟了。”宋平公派人去看，果然有这回事，就驱逐了华合比。华合比逃亡到卫国。当时华亥想要取代华合比的右师这一官职，就和寺人柳勾结，为他作证明说：“这件事我也早已听到。”宋平公让他代替了华合比。华亥进见左师，左师说：“你这个人一定要逃亡。你毁坏你的宗族，对别人会怎么样？别人也会对你怎么样？《诗》说：‘嫡长子就是城垣，不要使城垣毁坏，不要使自己孤立而有所害怕。’你大概会害怕的吧！”
六月初七日，郑国发生火灾。
楚国的公子弃疾到晋国去，这是为了回报韩宣子的致送晋女。经过郑国，郑国的子皮、子产、子太叔跟从郑简公在柤地慰劳他。公子弃疾辞谢不敢见面。郑简公坚决请求，这才肯见面。进见郑简公好像进见楚王，用驾车的马八匹作为私人进见的礼物。进见子皮好像进见楚国的上卿，用马六匹。进见子产，用马四匹。进见子太叔，用马两匹。禁止割草放牧采摘砍柴，不进入农田，不砍树木，不摘菜果，不拆房屋，不强行讨取。发誓说：“有触犯命令的，君子撤职，小人降等。”寄住的时期不作暴行，主人不用担心客人。一往一来都像这样，郑国的三个卿都知道他将要做楚王了。
韩宣子到楚国去的时候，楚国人不出来迎接。公子弃疾到达晋国国境，晋平公也不想派人迎接。叔向说：“楚国不正派，我们正派。为什么去学不正派？《诗》说，‘你的教导，百姓都要仿效。’根据我们自己的办就是了，哪里用得着学别人的不正派？《书》说，‘圣人做出准则。’宁可以善人做准则，难道还去学别人的不正派吗？一个普通人做好事，百姓还以他为准则，何况国君？”晋平公高兴了，就派人迎接公子弃疾。
秋季，九月，举行大的雩祭，这是由于发生了旱灾。
徐仪楚到楚国聘问，楚灵王囚禁了他，他逃回徐国。楚灵王害怕他背叛，派薳泄进攻徐国。吴国人救援徐国。令尹子荡率领军队进攻吴国，在豫章出兵而住在乾谿。吴国人在房钟击败了令尹子荡的军队，俘虏了宫厩尹弃疾。子荡把罪过推在薳泄身上而杀了他。
冬季，叔弓到楚国聘问，并且慰问战争失败。
十一月，齐景公到晋国，请求同意进攻北燕。士匄辅佐士鞅在黄河边上迎接，这是合于礼的。晋平公同意了。十二月，齐景公就发兵进攻北燕，打算把燕简公送回去。晏子说：“简公不要送回去。燕国有了国君，百姓对他没有二心。我们的国君贪财，左右的人阿谀奉承，办大事不讲信用，所以还是不可以呢！”', NULL, '', 'indent', 1559126467, '5cedf141c8959c0069f4f3f6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643056, '左传 · 昭公 · 昭公七年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】七年春王正月，暨齐平。三月，公如楚。叔孙婼如齐莅盟。夏四月甲辰朔，日有食之。秋八月戊辰，卫侯恶卒。九月，公至自楚。冬十有一月癸未，季孙宿卒。十有二月癸亥，葬卫襄公。
【传】七年春，王正月，暨齐平，齐求之也。癸巳，齐侯次于虢。燕人行成，曰：「敝邑知罪，敢不听命？先君之敝器，请以谢罪。」公孙皙曰：「受服而退，俟衅而动，可也。」二月戊午，盟于濡上。燕人归燕姬，赂以瑶瓮、玉椟、斗耳，不克而还。
楚子之为令尹也，为王旌以田。芋尹无宇断之，曰：「一国两君，其谁堪之？」及即位，为章华之宫，纳亡人以实之。无宇之阍入焉。无宇执之，有司弗与，曰：「执人于王宫，其罪大矣。」执而谒诸王。王将饮酒，无宇辞曰：「天子经略，诸侯正封，古之制也。封略之内，何非君土？食土之毛，谁非君臣？故《诗》曰：『普天之下，莫非王土。率土之滨，莫非王臣。』天有十日，人有十等，下所以事上，上所以共神也。故王臣公，公臣大夫，大夫臣士，士臣皂，皂臣舆，舆臣隶，隶臣僚，僚臣仆，仆臣台。马有圉，牛有牧，以待百事。今有司曰：『女胡执人于王宫？』将焉执之？周文王之法曰：『有亡，荒阅』，所以得天下也。吾先君文王，作仆区之法，曰：『盗所隐器，与盗同罪』，所以封汝也。若从有司，是无所执逃臣也。逃而舍之，是无陪台也。王事无乃阙乎？昔武王数纣之罪，以告诸侯曰：『纣为天下逋逃主，萃渊薮』，故夫致死焉。君王始求诸侯而则纣，无乃不可乎？若以二文之法取之，盗有所在矣。」王曰：「取而臣以往，盗有宠，未可得也。」遂赦之。
楚子成章华之台，愿与诸侯落之。大宰薳启强曰：「臣能得鲁侯。」薳启强来召公，辞曰：「昔先君成公，命我先大夫婴齐曰：『吾不忘先君之好，将使衡父照临楚国，镇抚其社稷，以辑宁尔民』。婴齐受命于蜀，奉承以来，弗敢失陨，而致诸宗祧。日我先君共王，引领北望，日月以冀。传序相授，于今四王矣。嘉惠未至，唯襄公之辱临我丧。孤与其二三臣，悼心失图，社稷之不皇，况能怀思君德！今君若步玉趾，辱见寡君，宠灵楚国，以信蜀之役，致君之嘉惠，是寡君既受贶矣，何蜀之敢望？其先君鬼神，实嘉赖之，岂唯寡君？君若不来，使臣请问行期，寡君将承质币而见于蜀，以请先君之贶。」
公将往，梦襄公祖。梓慎曰：「君不果行。襄公之适楚也，梦周公祖而行。今襄公实祖，君其不行。」子服惠伯曰：「行。先君未尝适楚，故周公祖以道之。襄公适楚矣，而祖以道君，不行，何之？」
三月，公如楚，郑伯劳于师之梁。孟僖子为介，不能相仪。及楚，不能答郊劳。
夏四月甲辰朔，日有食之。晋侯问于士文伯曰：「谁将当日食？」对曰：「鲁、卫恶之，卫大鲁小。」公曰：「何故？」对曰：「去卫地，如鲁地。于是有灾，鲁实受之。其大咎，其卫君乎？鲁将上卿。」公曰：「《诗》所谓『彼日而食，于何不臧』者，何也？」对曰：「不善政之谓也。国无政，不用善，则自取谪于日月之灾，故政不可不慎也。务三而已，一曰择人，二曰因民，三曰从时。」
晋人来治杞田，季孙将以成与之。谢息为孟孙守，不可。曰：「人有言曰：『虽有挈瓶之知，守不假器，礼也』。夫子从君，而守臣丧邑，虽吾子亦有猜焉。」季孙曰：「君之在楚，于晋罪也。又不听晋，鲁罪重矣。晋师必至，吾无以待之，不如与之，间晋而取诸杞。吾与子桃，成反，谁敢有之？是得二成也。鲁无忧而孟孙益邑，子何病焉？」辞以无山，与之莱、柞，乃迁于桃。晋人为杞取成。
楚子享公于新台，使长鬣者相，好以大屈。既而悔之。薳启强闻之，见公。公语之，拜贺。公曰：「何贺？对曰：「齐与晋、越欲此久矣。寡君无适与也，而传诸君，君其备御三邻。慎守宝矣，敢不贺乎？」公惧，乃反之。
郑子产聘于晋。晋侯疾，韩宣子逆客，私焉，曰：「寡君寝疾，于今三月矣，并走群望，有加而无瘳。今梦黄熊入于寝门，其何厉鬼也？」对曰：「以君之明，子为大政，其何厉之有？昔尧殛鲧于羽山，其神化为黄熊，以入于羽渊，实为夏郊，三代祀之。晋为盟主，其或者未之祀也乎？」韩子祀夏郊，晋侯有间，赐子产莒之二方鼎。
子产为丰施归州田于韩宣子，曰：「日君以夫公孙段为能任其事，而赐之州田，今无禄早世，不获久享君德。其子弗敢有，不敢以闻于君，私致诸子。」宣子辞。子产曰：「古人有言曰：『其父析薪，其子弗克负荷』。施将惧不能任其先人之禄，其况能任大国之赐？纵吾子为政而可，后之人若属有疆场之言，敝邑获戾，而丰氏受其大讨。吾子取州，是免敝邑于戾，而建置丰氏也。敢以为请。」宣子受之，以告晋侯。晋侯以与宣子。宣子为初言，病有之，以易原县于乐大心。
郑人相惊以伯有，曰「伯有至矣」，则皆走，不知所往。铸刑书之岁二月，或梦伯有介而行，曰：「壬子，余将杀带也。明年壬寅，余又将杀段也。」及壬子，驷带卒，国人益惧。齐、燕平之月壬寅，公孙段卒。国人愈惧。其明月，子产立公孙泄及良止以抚之，乃止。子大叔问其故，子产曰：「鬼有所归，乃不为厉，吾为之归也。」大叔曰：「公孙泄何为？」子产曰：「说也。为身无义而图说，从政有所反之，以取媚也。不媚，不信。不信，民不从也。」
及子产适晋，赵景子问焉，曰：「伯有犹能为鬼乎？」子产曰：「能。人生始化曰魄，既生魄，阳曰魂。用物精多，则魂魄强。是以有精爽，至于神明。匹夫匹妇强死，其魂魄犹能冯依于人，以为淫厉，况良霄，我先君穆公之胄，子良之孙，子耳之子，敝邑之卿，从政三世矣。郑虽无腆，抑谚曰『蕞尔国』，而三世执其政柄，其用物也弘矣，其取精也多矣。其族又大，所冯厚矣。而强死，能为鬼，不亦宜乎？」
子皮之族饮酒无度，故马师氏与子皮氏有恶。齐师还自燕之月，罕朔杀罕魋。罕朔奔晋。韩宣子问其位于子产。子产曰：「君之羁臣，苟得容以逃死，何位之敢择？卿违，从大夫之位，罪人以其罪降，古之制也。朔于敝邑，亚大夫也，其官，马师也。获戾而逃，唯执政所置之。得免其死，为惠大矣，又敢求位？」宣子为子产之敏也，使从嬖大夫。
秋八月，卫襄公卒。晋大夫言于范献子曰：「卫事晋为睦，晋不礼焉，庇其贼人而取其地，故诸侯贰。《诗》曰：『即□鴒在原，兄弟急难。』又曰：『死丧之威，兄弟孔怀。』兄弟之不睦，于是乎不吊，况远人，谁敢归之？今又不礼于卫之嗣，卫必叛我，是绝诸侯也。」献子以告韩宣子。宣子说，使献子如卫吊，且反戚田。
卫齐恶告丧于周，且请命。王使臣简公如卫吊，且追命襄公曰：「叔父陟恪，在我先王之左右，以佐事上帝。余敢高圉、亚圉？」
九月，公至自楚。孟僖子病不能相礼，乃讲学之，苟能礼者从之。及其将死也，召其大夫曰：「礼，人之干也。无礼，无以立。吾闻将有达者曰孔丘，圣人之后也，而灭于宋。其祖弗父何，以有宋而授厉公。及正考父，佐戴、武、宣，三命兹益共。故其鼎铭云：『一命而偻，再命而伛，三命而俯。循墙而走，亦莫余敢侮。饘是，鬻于是，以糊余口。』其共也如是。臧孙纥有言曰：『圣人有明德者，若不当世，其后必有达人。』今其将在孔丘乎？我若获没，必属说与何忌于夫子，使事之，而学礼焉，以定其位。」故孟懿子与南宫敬叔师事仲尼。仲尼曰：「能补过者，君子也。《诗》曰：『君子是则是效。』孟僖子可则效已矣。」
单献公弃亲用羁。冬十月辛酉，襄、顷之族杀献公而立成公。
十一月，季武子卒。晋侯谓伯瑕曰：「吾所问日食，从矣，可常乎？」对曰：「不可。六物不同，民心不一，事序不类，官职不则，同始异终，胡可常也？《诗》曰：『或燕燕居息，或憔悴事国。』其异终也如是。」公曰：「何谓六物？」对曰：「岁、时、日、月、星、辰，是谓也。」公曰：「多语寡人辰，而莫同。何谓辰？」对曰：「日月之会，是谓辰，故以配日。」
卫襄公夫人姜氏无子，嬖人婤姶生孟絷。孔成子梦康叔谓己：「立元，余使羁之孙圉与史苟相之。」史朝亦梦康叔谓己：「余将命而子苟与孔烝锄之曾孙圉相元。」史朝见成子，告之梦，梦协。晋韩宣子为政聘于诸侯之岁，婤姶生子，名之曰元。孟絷之足不良，能行。孔成子以《周易》筮之，曰：「元尚享卫国主其社稷。」遇《屯》三。又曰：「余尚立絷，尚克嘉之。」遇《屯》三之《比三。以示史朝。史朝曰：『元亨』，又何疑焉？」成子曰：「非长之谓乎？」对曰：「康叔名之，可谓长矣。孟非人也，将不列于宗，不可谓长。且其繇曰『利建侯』。嗣吉，何建？建非嗣也。二卦皆云，子其建之。康叔命之，二筮袭于梦，武王所用也，弗从何为？弱足者居，侯主社稷，临祭祀，奉民人，事民人，鬼神，从会朝，又焉得居？各以所利，不亦可乎？」故孔成子立灵公。十二月癸亥，葬卫襄公。', '', '', '七年春季，周王朝历法的正月，北燕和齐国讲和，这是由于齐国的要求。十八日，齐景公住在虢地。燕国人求和，说：“敝邑知道罪过，岂敢不听从命令？请求把先君的破旧器物用来谢罪。”公孙皙说：“接受他们的归服而退兵，等待有空子再采取行动，可以这样做。”二月十四日，在濡水边上结盟。燕国人把燕姬嫁给齐景公，送给他玉瓮、玉柜、玉杯。齐国没有取得胜利而回国。
楚灵王做令尹的时候，打了国王用的旌旗去打猎，芋尹无宇砍断旌旗的飘带，说：“一个国家两个君主，有谁能忍受得了？”等到楚灵王即位，又建造章华宫，接纳逃亡的人安置在里面。无宇的守门人逃到章华宫里。无宇要抓他，管理宫室的官员不肯，说：“在国王的宫里抓人，这罪过就大了。”抓住无宇而进见楚灵王。楚灵王准备喝酒，无宇申诉说：“天子经营天下，诸侯治理封疆，这是古代的制度。边境之内，哪里不是国君的土地？吃着土地上的出产，谁不是国君的下臣？所以《诗》说：‘普天之下，无不是天子的土地。沿着土地的边涯，无不是天子的臣仆。’天有十个日子，人有十个等级。下边以此事奉上边，上边以此祭祀神明。所以王统治公，公统治大夫，大夫统治士，士统治皂，皂统治舆，舆统治隶，隶统治僚，僚统治仆，仆统治台。养马有圉，放牛有牧，各有专司以应付各种事情。现在官员说：‘你为什么在王宫里抓人？’不在王宫，又在哪里抓他呢？周文王的法令说，‘有逃亡的，要大肆搜捕’，因此就得了天下。我们的先君文王制订惩罚窝藏的法令，说，‘隐藏盗贼的赃物，和盗贼同罪’，因此就得到直到汝水的疆土。如果按照那些官员的做法，这就是没有地方去逮捕逃亡的奴隶了。逃亡的就让他逃亡，这就没有奴仆了。这样，国家的工作恐怕就会有所缺失了！从前武王列举纣的罪状通告诸侯说：‘纣是天下逃亡者的窝藏主，是逃亡者聚集的渊薮。’所以人们致死也要攻打他。君王开始求取诸侯而效法纣，只怕不可以吧！如果用两位文王的法令来逮捕盗贼，盗贼是有地方可抓的。”楚灵王说：“抓了你的奴隶走吧。有一个盗贼正受到恩宠，还抓不到呢。”于是就赦免了无宇。
楚灵王建成章华之台，希望和诸侯一起举行落成典礼。太宰薳启彊说：“下臣能够得到鲁侯。”薳启彊前来召请鲁昭公，致辞说：“从前贵国的先君成公命令我们的先大夫婴齐说：‘我不忘记先君的友好，将要派衡父光临楚国，镇抚安定国家，使得你们百姓安宁。’婴齐在蜀地接受了命令。接受命令回来，不敢废弃，而祭告于宗庙。过去我们先君共王伸着脖子向北望，每天每月都在盼望着贵国使者的到来，世代相传，到今天经历四位国王了。恩赐没有来到，只有襄公为了我国的丧事而光临。孤和手下的几个臣子心中动摇失掉了主意，治理国家尚且不得闲空，哪里还能够怀念您的恩德！现在君王如果移步屈尊，和寡君见面，使楚国得到福泽，以重申蜀地那次会盟，送来君王的恩惠，这样，寡君就已经受到恩赐了，哪里敢希望再像蜀地那次结盟一样！敝邑的先君鬼神也会嘉许和依靠它，岂独寡君？如果君王不来，使臣请问君王带兵出动的日期，寡君将要捧着进见的财币，而到蜀地去见君王，以请问鲁先君成公的恩赐。”
鲁昭公准备前去，梦见鲁襄公为他出行，祭祀路神。梓慎说：“君王最终是去不了的。襄公去楚国的时候，梦见周公祭祀路神，然后出行。现在襄公在祭祀路神，君王还是不去为好。”子服惠伯说：“去！先君从没有去过楚国，所以周公祭祀路神来引导他。襄公去过楚国了，然后祭祀路神，来引导君王。不去，到哪里去？”
三月，昭公到楚国去，郑简公在师之梁慰劳昭公。孟僖子做副手，不能相礼。到达楚国，不能对答郊外的慰劳礼。
夏季，四月初一，日食。晋平公向士文伯询问说：“谁将要承当日食的灾祸？”士文伯说：“鲁国和卫国会遭到凶险。卫国受祸大，鲁国受祸小。”晋平公说：“什么缘故？”士文伯回答说：“日食的时候日头离开卫国的分野到了鲁国的分野。在这种情况下发生灾祸，鲁国就应该承受。这次大灾恐怕要落在卫君的头上吧！鲁国将要由上卿来承当。”晋平公说：“《诗》所说的‘那个日头发生日食。是什么地方不好’，是什么意思？”士文伯回答说：“这说的是不善于处理政事。国家没有好政事，不用好人，那就在日月的灾祸里会自找倒霉，所以政事是不能不谨慎的。致力于三条就行了：第一叫做选择贤人，第二叫做依靠百姓，第三叫做顺从时令。”
晋国派人前来划定鲁国与杞国的边界，季孙打算把成地给他们。谢息为孟孙镇守成地，不同意，说：“人们有这样的话说，‘虽然只有小智小慧，守着器物就不能出借，这是礼。”他老人家跟随国君，而守臣却丢掉他的城邑，即使是您也会怀疑我不忠的。”季孙说：“国君在楚国，对于晋国来说就是罪过。又不听从晋国，鲁国的罪过就加重了，晋军必然到来，我没法抵御他们，不如给他们算了。等晋国有机可乘，而再取之于杞国。我给您桃地，如果成地重归于我国，谁敢占有它？这就是得到两份成地了。鲁国没有忧患而孟孙增加封邑，您又担心什么呢？”谢息推辞说桃地没有山，季孙又给他莱山和柞山，谢息这才迁到桃地。晋国人为杞国取得了成地。
楚灵王在新台设享礼招待鲁昭公，让一个长须的人相礼。把大屈之弓送给昭公表示友好。随即又后悔。薳启彊听说这件事，进见昭公。昭公跟他说起这件事，薳启彊下拜祝贺。昭公说：“为什么祝贺？”薳启彊回答说：“齐国和晋国、越国想要它很久了，寡君并没有肯定给他们，而送给了君王。君王防备抵御三个邻国，谨慎地保有宝物，难道敢不祝贺吗？”昭公恐惧，就把弓送还给楚灵王。
郑国的子产到晋国聘问。晋平公有病。韩宣子迎接客人，私下说：“寡君卧病，到现在三个月了，所应该祭祀的山川都祈祷过了，但是病情只有增加而没有见好。现在梦见黄熊进入寝门，这是什么恶鬼？”子产回答说：“以君王的英明，您做正卿，哪里会有恶鬼？从前尧在羽山杀死了鲧，他的精灵变成黄熊，钻进羽渊里，成为夏朝郊祭的神灵，三代都祭祀他。晋国做盟主，或者没有祭祀他吧！”韩宣子祭祀鲧。晋平公的病逐渐痊愈，把莒国的两个方鼎赏赐给子产。
子产为丰施把州地的土田归还给韩宣子，说：“过去君王认为那个公孙段能够承担大事，因而赐给他州地的土田。现在他不幸早死，不能长久地享有君王的赐予。他的儿子不敢占有，也不敢告诉君王，所以私下送给您”宣子辞谢。子产说：“古人有话说：‘他父亲劈的柴，他的儿子不能承受。’施将会惧怕不能承受他先人的俸禄，更何况担当大国的恩赐？即使您执政而可以使他免于罪戾，后来的人如果碰巧有关于边界的闲话，敝邑得罪，丰氏就会受到大的讨伐。您取得州地，这是使敝邑免于罪过，又等于建立扶持丰氏。谨敢以此作为请求。”宣子接受了，把情况报告晋平公。晋平公把州地给了宣子。宣子由于当初的话，占有州地感到惭愧，用州地跟乐大心交换了原县。
郑国有人因为伯有而互相惊扰，说：“伯有来了！”大家都跑，不知跑到哪里去才好。把刑法铸在鼎上的那年二月，有人梦见伯有披甲而行，说：“三月初二日，我将要杀死带。明年正月二十七日，我又将要杀死段。”到去年三月初二日那一天，驷带死了，国内的人们更加害怕。齐国和燕国讲和的那一月，二十七日，公孙段死了。国内的人们就越来越恐惧了。下一月，子产立了公孙泄和良止来安抚伯有的鬼魂，这才停了下来。子太叔问这样做的原因。子产说：“鬼有所归宿，这才不做恶鬼，我是为他寻找归宿啊。”太叔说：“立公孙泄干什么？”子产说：“为了使他们高兴，立身没有道义而希图高兴，执政的人违反礼仪，这是用来取得百姓欢心。不取得百姓欢心，不能使人信服。不能使人信服，百姓是不会服从的。”
等到子产去晋国，赵景子问他，说：“伯有还能做鬼吗？”子产说：“能。人刚刚死去叫做魄，已经变成魄，阳气叫做魂。生时衣食精美丰富魂魄就强有力，因此有现形的能力，一直达到神化。普通的男人和女人不能善终，他们的魂魄还能附在别人身上，以大肆惑乱暴虐，何况伯有是我们先君穆公的后代，子良的孙子，子耳的儿子，敝邑的卿，执政已经三代了。郑国虽然不强大，或者就像俗话所说的是‘小小的国家’，可是三代执掌政权，他使用东西很多，他在其中汲取精华也很多，他的家族又大，所凭借的势力雄厚，可又不得善终，能够做鬼，不也是应该的吗？”
子皮的族人饮酒没有节制，所以马师氏和子皮氏的关系很坏。齐军从燕国回去的那个月，罕朔杀了罕魋。罕朔逃亡到晋国，韩宣子向子产询问安排他什么官职。子产说：“君王的寄居之臣，如果能容他逃避死罪，还敢选择什么官职？卿离开本国，随大夫的班位。有罪的人根据他的罪行降等，这是古代的制度。朔在敝邑的班位，是亚大夫。他的官职，是马师。得罪逃亡，就随您安排了。能够免他一死，所施的恩惠就很大了，又岂敢要求官职？”宣子由于子产答复恰当，让他随下大夫的班位。
秋季，八月，卫襄公死了。晋国的大夫对范献子说：“卫国事奉晋国恭敬亲近，晋国不加礼遇，包庇它的叛乱者而占取它的土地，所以诸侯有了二心。《诗》说：‘鹡鸰在平原上，遇到急难兄弟互相救援。’又说：‘死丧是那么可怕，兄弟要互相怀念。’兄弟不和睦，因此不相亲善，何况远方的人们，谁敢前来归服？现在又对卫国的继位之君不加礼遇，卫国必然背叛我们，这种做法是和诸侯绝交。”献子把这些话告诉韩宣子。韩宣子很高兴，派献子去卫国吊唁，同时归还戚地的土田给卫国。
卫国的齐恶向周朝报告丧事，同时请求赐予恩命。周景王派郕简公去卫国吊唁，同时追命卫襄公说：“叔父升天，在我先王的左右，以辅佐事奉上帝。我岂敢忘了高圉、亚圉？”
九月，昭公从楚国到达。孟僖子不满意自己对礼仪不熟悉，就学习礼仪，如果有精通礼仪的人就跟他学习。等到临死的时候，召集他手下的大夫，说：“礼仪，是做人的根本。没有礼仪，不能自立。我听说有一个将要得志的人名叫孔丘，是聪明人的后代，而他的家族却在宋国灭亡了。他的祖先弗父何本来应当据有宋国而让给了宋厉公。到了正考父，辅佐戴公、武公、宣公，三命而做了上卿就更加恭敬，所以他的鼎铭说：‘一命低头，二命弯身，三命把腰深深弯下。沿着墙赶快走，也没有敢把我欺侮。稠粥在这里，稀粥也在这里，用来糊住我的口。’他的恭敬就像这样。臧孙纥有话说：‘聪明人里具有明德的人，如果不能做国君，他的后代必然有显贵的。’现在恐怕会在孔丘身上吧！我如得以善终，一定把说和何忌托给他老人家，让他们事奉他而学习礼仪，以稳定他们的地位。”所以孟懿子和南宫敬叔把孔子作为老师来事奉。孔子说：“能够弥补过错的，就是君子啊。《诗》说，‘要取法仿效君子’。孟僖子可以学习仿效了。”
单献公抛开亲族而任用寄居的客臣。冬季，十月二十日，襄公、顷公的族人杀死了单献公而立了单成公。
十一月，季武子死了。晋平公对伯瑕说：“我所询问的关于日食的事情，应验了。可以经常这样占验吗？”伯瑕说：“不行。六种事物不相同，百姓心志不一致，事情轻重不是一类，官员好坏不一样，开始相同而结果相异，怎么可以经常这样呢？《诗》说‘有人舒舒服服地安居休息，有人精疲力尽地为国操劳’，它的结果不同就像这样。”晋平公说：“六种事物说的是什么？”伯瑕回答说：“这说的就是岁、时、日、月、星、辰。”晋平公说：“很多人告诉我辰的意义而没有相同的，什么叫做辰？”伯瑕回答说：“日和月相会叫做辰，所以用来和日相配。”
卫襄公夫人姜氏没有儿子，宠姬婤姶生了孟絷。孔成子梦见康叔对自己说：“立元为国君，我让羁的孙子圉和史苟辅佐他。”史朝也梦见康叔对自己说：“我将要命令你的儿子苟和孔烝鉏的曾孙圉辅佐元。”史朝进见孔成子，告诉他梦见的情况，两梦情况相合。晋国韩宣子执政，向诸侯聘问的那一年，婤姶生了儿子，为他取名叫元。孟絷的脚不好不善走路，孔成子用《周易》来占筮，祝告说：“元希望享有卫国，主持国家。”得到《屯》卦。又祝告说：“我还想立絷，希望神灵能够允许。”得到《屯》卦变成《比》卦。把卦像给史朝看。史朝说：“‘元亨’，就是元将会享有国家，又有什么怀疑呢？”孔成子说：“‘元’不是说为首的吗？”史朝回答说：“康叔为他取名，可以说是为首的了。孟不是这样的人，他将不能列为宗主，不能叫做为首的。而且它的繇辞说：‘利建侯’。嫡子嗣位而吉利，还建立什么侯？建立不就是嗣位。两次卦像都那么说，您还是建立他为好。康叔命令了我们，两次卦像告诉了我们。占筮和梦境相合，这是武王所经过的，为什么不听从？脚有毛病只能待在家里闲居。国君主持国家，亲临祭祀，奉养百姓，事奉鬼神，参加会见朝觐，又哪里能够闲居？各人按照他所有利的去做，不也可以吗？”所以孔成子立了灵公。十二月二十三日，安葬卫襄公。', NULL, '', 'indent', 1559126512, '5cedf16dc8959c0069f4f5de', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643057, '左传 · 昭公 · 昭公八年 ', NULL, 1, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】八年春，陈侯之弟招杀陈世子偃师，夏四月辛丑，陈侯溺卒。叔弓如晋。楚人执陈行人干征师杀之。陈公子留出奔郑。秋，蒐于红。陈人杀其大夫公子过。大雩，冬十月壬午，楚师灭陈。执陈公子招，放之于越。杀陈孔奂。葬陈哀公。
【传】八年春，石言于晋魏榆。晋侯问于师旷曰：「石何故言？」对曰：「石不能言，或冯焉。不然，民听滥也。抑臣又闻之曰：『作事不时，怨讟动于民，则有非言之物而言。』今宫室崇侈，民力凋尽，怨讟并作，莫保其性。石言，不亦宜乎？」于是晋侯方筑虒祁之宫。叔向曰：「子野之言，君子哉！君子之言，信而有徵，故怨远于其身。小人之言，僭而无征，故怨咎及之。《诗》曰：『哀哉不能言，匪舌是出，唯躬是瘁。哿矣能言，巧言如流，俾躬处休。』其是之谓乎？是宫也成，诸侯必叛，君必有咎，夫子知之矣。」
陈哀公元妃郑姬，生悼大子偃师，二妃生公子留，下妃生公子胜。二妃嬖，留有宠，属诸徒招与公子过。哀公有废疾。三月甲申，公子招、公子过杀悼大子偃师，而立公子留。
夏四月辛亥，哀公缢。干征师赴于楚，且告有立君。公子胜愬之于楚，楚人执而杀之。公子留奔郑。书曰「陈侯之弟招杀陈世子偃师」，罪在招也；「楚人执陈行人干征师杀之」，罪不在行人也。
叔弓如晋，贺虒祁也。游吉相郑伯以如晋，亦贺虒祁也。史赵见子大叔，曰：「甚哉，其相蒙也！可吊也，而又贺之？」子大叔曰：「若何吊也？其非唯我贺，将天下实贺。」
秋，大蒐于红，自根牟至于商、卫，革车千乘。
七月甲戌，齐子尾卒，子旗欲治其室。丁丑，杀梁婴。八月庚戌，逐子成、子工、子车，皆来奔，而立子良氏之宰。其臣曰：「孺子长矣，而相吾室，欲兼我也。」授甲，将攻之。陈桓子善于子尾，亦授甲，将助之。或告子旗，子旗不信。则数人告。将往，又数人告于道，遂如陈氏。桓子将出矣，闻之而还，游服而逆之。请命，对曰：「闻强氏授甲将攻子，子闻诸？」曰：「弗闻。」「子盍亦授甲？无宇请从。」子旗曰：「子胡然？彼孺子也，吾诲之犹惧其不济，吾又宠秩之。其若先人何？子盍谓之？《周书》曰：『惠不惠，茂不茂。』康叔所以服弘大也。」桓子稽颡曰：「顷、灵福子，吾犹有望。」遂和之如初。
陈公子招归罪于公子过而杀之。九月，楚公子弃疾帅师奉孙吴围陈，宋戴恶会之。冬十一月壬午，灭陈。舆嬖袁克，杀马毁玉以葬。楚人将杀之，请置之。既又请私，私于幄，加絰于颡而逃。使穿封戌为陈公，曰：「城麇之役，不谄。」侍饮酒于王，王曰：「城麇之役，女知寡人之及此，女其辟寡人乎？」对曰：「若知君之及此，臣必致死礼，以息楚。」晋侯问于史赵，曰：「陈其遂亡乎？」对曰：「未也。」公曰：「何故？」对曰：「陈，颛顼之族也。岁在鹑火，是以卒灭，陈将如之。今在析木之津，犹将复由。且陈氏得政于齐而后陈卒亡。自幕至于瞽瞍，无违命。舜重之以明德，置德于遂，遂世守之。及胡公不淫，胡周赐之姓，使祀虞帝。臣闻盛德必百世祀，虞之世数未也。继守将在齐，其兆既存矣。」', '', '', '八年春季，在晋国的魏榆有块石头说话。晋平公向师旷询问说：“石头为什么说话？”师旷回答说：“石头不能说话，有的东西凭借着它。否则，就是百姓听错了。下臣又听说：‘做事情违背了农时，怨恨诽谤在百姓中发生，就有不能说话的东西说话。’现在宫室高大奢侈，百姓的财力用尽，怨恨诽谤一齐起来，没有人能确保自己的性命。石头说话，不也是相宜的吗？”当时晋平公正在建造虒祁之宫，叔向说：“子野的话真是君子啊！君子的话，诚实而有证明，所以怨恨远离他的身体。小人的话，虚伪而没有证明，所以怨恨和灾祸来到他身上。《诗》说，‘不会说话多么伤心，话不能从他舌头上出来，只有劳累他自己。会说话的多么美好，漂亮话好像流水，使他自己安居休息’，说的就是这个吧！这座宫殿落成，诸侯必然背叛，国君必然有灾殃，师旷先生已经知道这一点了。”
陈哀公的第一夫人郑姬生了悼太子偃师，第二夫人生了公子留，第三夫人生了公子胜。第二夫人受到宠爱，公子留得宠，哀公把他托付给司徒招和公子过。陈哀公患有长期不愈的疾病，三月十六日，公子招、公子过杀了悼太子偃师而立公子留做太子。
夏季，四月十三日，陈哀公上吊而死。干徵师到楚国报丧，同时报告又立了国君。公子胜向楚国控诉，楚国人抓住干徵师并杀死了他。公子留逃亡到郑国。《春秋》记载说“陈侯之弟招杀陈世子偃师”，这是由于罪过在于公子招，“楚人执陈行人干徵师杀之”，这是由于罪过不在于行人。
叔弓到晋国去，祝贺虒祁之宫的落成。游吉辅佐郑伯而去到晋国，也是祝贺虒祁之宫的落成。史赵见到游吉，说：“大家互相欺骗也太过分了！可以吊唁的事，反而又来祝贺它！”游吉说：“怎么吊唁啊？大概不仅我国祝贺，天下都将会来祝贺。”
秋季，在红地举行大检阅，从根牟直到宋国、卫国边境线上，兵车有一千辆。
七月初八日，齐国的子尾死了，子旗想要管理子尾的家政。十一日，杀梁婴。八月十四日，驱逐了子成、子工、子车，这三个人都逃亡前来我国，子旗为子良立了家臣头子。子良的家臣说：“孩子已经长大了，子旗却要帮忙管我们的家事，这是想要兼并我们。”把武器发下去，准备攻打子旗。陈桓子和子尾亲近，也把武器发下去，准备帮助子良的家臣。有人报告给子旗，子旗不相信，又有几个人来报告。子旗准备去子良家里，又有几个人在路上向他报告，因此就去到陈氏那里。桓子将要出动了，听说子旗来，就转回去，穿上便服迎接子旗。子旗请问桓子的意见。桓子回答说：“听说子良家里把武器发下去准备攻打您，您听说了吗？”子旗说：“没有听说。”桓子说：“您何不也把武器发下去？无宇请求跟从您。”子旗说：“您为什么要这样做？他是个孩子，我教导他，还恐怕他不能成功，我又宠信他为他立了家臣头子，如果和他互相攻打，怎么对待先人？您何不对他去说一说？《周书》说，‘施惠于不感激施惠的人，劝勉不受劝勉的人’，这就是康叔所以能够作事宽大的缘故。”陈桓子叩着头说：“顷公、灵公保佑您，我还希望您赐惠于我呢。”于是两家和好如同以前一样。
陈国的公子招把罪过推给公子过而杀死了他。九月，楚国的公子弃疾带兵奉事太孙吴包围陈国，宋国的戴恶领兵会合。冬季，十月十八日，灭亡了陈国。管车人袁克杀了马毁了玉为陈哀公殉葬。楚国人要杀死他。他请求赦免，不久又请求去小便。他在帐幕里小便，把麻带缠在头上逃走了。
楚灵王派穿封戌做陈公，说：“在城麇那次事件中他不谄媚。”穿封戌事奉楚灵王饮酒，楚灵王说：“城麇那次事件，你要知道寡人能到这一步，你大约会让我的吧！”穿封戌回答说：“如果知道您能到这一步，臣下一定冒死来安定楚国。”
晋平公向史赵询问说：“陈国大约就此灭亡了吧！”史赵说：“没有。”晋平公说：“什么缘故？”史赵回答说：“陈国，是颛顼的后代。岁星在于鹑火，颛顼氏由此而终于灭亡。陈国也将会和过去一样。现在岁星在箕宿、斗宿间的银河中，陈国还将会复兴。而且陈氏要在齐国取得政权，以后才最终灭亡。这一族从幕直到瞽瞍都没有违背天命，舜又增加了盛德，德行一直落到遂的身上。遂的后代保持了它。到了胡公不淫，所以周朝给他赐姓，让他祭祀虞帝。下臣听说，盛德一定享有一百代的祭祀。现在虞的世代数字不满一百，将会继续在齐国保持下去，它的征兆已经有了。”', NULL, '', 'indent', 1559126556, '5cedf1887b968a00767d4ea1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643058, '左传 · 昭公 · 昭公九年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】九年春，叔弓会楚子于陈。许迁于夷。夏四月，陈灾。秋，仲孙玃如齐。冬，筑郎囿。
【传】九年春，叔弓、宋华亥、郑游吉、卫赵□会楚子于陈。
二月庚申，楚公子弃疾迁许于夷，实城父，取州来淮北之田以益之。伍举授许男田。然丹迁城父人于陈，以夷濮西田益之。迁方城外人于许。
周甘人与晋阎嘉争阎田。晋梁丙、张趯率阴戎伐颖。王使詹桓伯辞于晋曰：「我自夏以后稷，魏、骀、芮、岐、毕，吾西土也。及武王克商，蒲姑、商奄，吾东土也；巴、濮、楚、邓，吾南土也；肃慎、燕、亳，吾北土也。吾何迩封之有？文、武、成、康之建母弟，以蕃屏周，亦其废队是为，岂如弁髦而因以敝之？先王居檮杌于四裔，以御螭魅，故允姓之奸，居于瓜州，伯父惠公归自秦，而诱以来，使逼我诸姬，入我郊甸，则戎焉取之。戎有中国，谁之咎也？后稷封殖天下，今戎制之，不亦难乎？伯父图之。我在伯父，犹衣服之有冠冕，木水之有本原，民人之有谋主也。伯父若裂冠毁冕，拔本塞原，专弃谋主，虽戎狄其何有馀一人？」叔向谓宣子曰：「文之伯也，岂能改物？翼戴天子而加之以共。自文以来，世有衰德而暴灭宗周，以宣示其侈，诸侯之贰，不亦宜乎？且王辞直，子其图之。」宣子说。
王有姻丧，使赵成如周吊，且致阎田与襚，反颖俘。王亦使宾滑执甘大夫襄以说于晋，晋人礼而归之。
夏四月，陈灾。郑裨灶曰：「五年，陈将复封。封五十二年而遂亡。」子产问其故，对曰：「陈，水属也，火，水妃也，而楚所相也。今火出而火陈，逐楚而建陈也。妃以五成，故曰五年。岁五及鹑火，而后陈卒亡，楚克有之，天之道也，故曰五十二年。」
晋荀盈如齐逆女，还，六月，卒于戏阳。殡于绛，未葬。晋侯饮酒，乐。膳宰屠蒯趋入，请佐公使尊，许之。而遂酌以饮工，曰：「女为君耳，将司聪也。辰在子卯，谓之疾日。君彻宴乐，学人舍业，为疾故也。君之卿佐，是谓股肱。股肱或亏，何痛如之？女弗闻而乐，是不聪也。」又饮外嬖嬖叔曰：「女为君目，将司明也。服以旌礼，礼以行事，事有其物，物有其容。今君之容，非其物也，而女不见。是不明也。」亦自饮也，曰：「味以行气，气以实志，志以定言，言以出令。臣实司味，二御失官，而君弗命，臣之罪也。」公说，彻酒。
初，公欲废知氏而立其外嬖，为是悛而止。秋八月，使荀跞佐下军以说焉。
孟僖子如齐殷聘，礼也。
冬，筑郎囿，书，时也。季平子欲其速成也，叔孙昭子曰：「《诗》曰：『经始勿亟，庶民子来。』焉用速成？其以剿民也？无囿犹可，无民其可乎？」', '', '', '九年春季，叔弓、宋国华亥、郑国游吉、卫国赵黡在陈国会见楚灵王。
二月某日，楚国的公子弃疾把许国迁到夷地，其实就是城父。再增加州来、淮北的土田给许国，由伍举把土田授给许男。然丹把城父的人迁到陈地，用濮地、夷地西部的土田补给陈地。把方城山外边的人迁到许地。
周朝的甘地人和晋国的阎嘉争夺阎地的土田。晋国的梁丙、张趯率领阴戎进攻颍地。周天子派詹桓伯去谴责晋国说：“我们在夏代由于后稷的功劳，魏国、骀国、芮国、岐国、毕国，是我们的西部领土。到武王战胜商朝，蒲姑、商奄，是我们的东部领土。巴国、濮国、楚国、邓国，是我们的南部领土。肃慎、燕国、亳国，是我们的北部领土。我们有什么近处的封疆领土？文王、武王、成王、康王建立同母兄弟的国家，用来护卫周室，也是为了防止周室的毁坏衰落，难道只是像不用的东西因而就抛弃了它？先王让梼杌住在四方边远的地方，来抵御山中的精怪，所以允姓中的坏人住在瓜州。伯父惠公从秦国回去，就引诱他们前来，让他们逼迫我们姬姓的国家，进入我们的郊区，戎人于是就占取了这些地方。戎人占有中原，这是谁的罪责？后稷缔造了天下，现在为戎人割据，不也很难吗？伯父考虑一下，我们对于伯父来说，犹如衣服之有帽子，树木流水之有本源，百姓之有谋主。伯父如果撕毁了帽子，拔掉树木塞断水源，专断并抛弃谋主，即使是戎狄，他们心里哪里会有我这天子？”叔向对宣子说：“文公称霸诸侯，难道能改变旧制？他辅佐拥戴天子，而又加上恭敬。从文公以来，每一代都是德行衰减，而且损害、轻视王室，用来宣扬它的骄横，诸侯有三心二意，不也是应该的吗？而且天子的辞令理直气壮，您还是考虑一下。”宣子心服。
周景王有姻亲的丧事，宣子就派赵成到成周吊唁，而且送去阎地的土田和入殓的衣服，遣返在颍地抓到的俘虏。周景王也派宾滑抓了甘地的大夫襄来讨晋国的欢心，晋国人对他加以礼遇而放他回去了。
夏季，四月，陈地发生火灾。郑国的裨灶说：“过五年陈国将会重新受封，受封以后五十二年被灭亡。”子产问这样说的缘故。裨灶回答说：“陈国，是水的隶属；火，是水的配偶，而是楚国所主治。现在大火星出现而陈国发生火灾，这是驱逐楚国而建立陈国。阴阳五行用五来相配，所以说五年。岁星过五年到达鹑火，然后陈国终于灭亡，楚国战胜而占有它，这是上天之道，所以说是五十二年。”
晋国的荀盈到齐国去接齐女，回来，六月，死在戏阳。停棺在绛地，没有安葬。晋平公喝酒，奏乐。主持饮食的官员屠蒯快步走进，请求帮着斟酒，晋平公答应了，屠蒯就斟酒给乐工喝，说：“你作为国君的耳朵，职责是让它聪敏。日子在甲子乙卯，叫做忌日，国君撤除音乐，学乐的人停止演习，这是为了忌避的缘故。国君的卿佐，这叫做股肱之臣。股肱之臣有了亏损，多么痛心呀！你没有听到而奏乐，这是耳朵不灵敏。”又给宠臣嬖叔喝酒，说：“你作为国君的眼睛，职责是让它明亮。服饰用来表示礼仪，礼仪用来推行事情，事情有它的类别，类别有它的外貌。现在国君的外貌，不是他应有的类别，而你看不见，这是眼睛不明亮。”屠蒯自己也喝了一杯，说：“口味用来让气血流通，气血用来充实意志，意志用来确定语言，语言用来发布命令。臣下的职责是管调和口味，两个侍候国君的人失职，而国君没有下令治罪，这是下臣的罪过。”晋平公很高兴，撤除了酒宴。
当初，晋平公想要废掉荀盈而立他的宠臣，因为上述这件事就改变想法，而停止了。秋季，八月，派荀跞辅佐下军以表明自己的意思。
孟僖子到齐国举行盛大的聘问，这是合于礼的。
冬季，修造郎囿。《春秋》加以记载，这是由于合于时令。季平子想要迅速完成，叔孙昭子说：“《诗》说：‘营造开始不要着急，百姓却像儿子一样自动跑来。’哪里用得着急于求成来劳累百姓呢？没有园林还是可以的，没有百姓可以吗？”', NULL, '', 'indent', 1559126594, '5cedf1bfd5de2b00709114c2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643059, '左传 · 昭公 · 昭公十年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十年春王正月。夏，齐栾施来奔。秋七月，季孙意如、叔弓、仲孙玃帅师伐莒。戊子，晋侯彪卒。九月，叔孙婼如晋，葬晋平公。十有二月甲子，宋公成卒。
【传】十年春，王正月，有星出于婺女。郑裨灶言于子产曰：「七月戊子，晋君将死。今兹岁在颛顼之虚，姜氏、任氏实守其地。居其维首，而有妖星焉，告邑姜也。邑姜，晋之妣也。天以七纪。戊子，逢公以登，星斯于是乎出。吾是以讥之。」
齐惠栾、高氏皆耆酒，信内多怨，强于陈、鲍氏而恶之。
夏，有告陈桓子曰：「子旗、子良将攻陈、鲍。」亦告鲍氏。桓子授甲而如鲍氏，遭子良醉而骋，遂见文子，则亦授甲矣。使视二子，则皆从饮酒。桓子曰：「彼虽不信，闻我授甲，则必逐我。及其饮酒也，先伐诸？」陈、鲍方睦，遂伐栾、高氏。子良曰：「先得公，陈、鲍焉往？」遂伐虎门。
晏平仲端委立于虎门之外，四族召之，无所往。其徒曰：「助陈、鲍乎？」曰：「何善焉？」「助栾、高乎？」曰：「庸愈乎？」「然则归乎？」曰：「君伐，焉归？」公召之而后入。公卜使王黑以灵姑金ぶ率，吉，请断三尺焉而用之。五月庚辰，战于稷，栾、高败，又败诸庄。国人追之，又败诸鹿门。栾施、高强来奔。陈、鲍分其室。
晏子谓桓子：「必致诸公。让，德之主也，谓懿德。凡有血气，皆有争心，故利不可强，思义为愈。义，利之本也，蕴利生孽。姑使无蕴乎！可以滋长。」桓子尽致诸公，而请老于莒。
桓子召子山，私具幄幕、器用、从者之衣屦，而反棘焉。子商亦如之，而反其邑。子周亦如之，而与之夫于。反子城、子公、公孙捷，而皆益其禄。凡公子、公孙之无禄者，私分之邑。国之贫约孤寡者，私与之粟。曰：「《诗》云：『陈锡载周』，能施也，桓公是以霸。」
公与桓子莒之旁邑，辞。穆孟姬为之请高唐，陈氏始大。秋七月，平子伐莒，取郠，献俘，始用人于亳社。臧武仲在齐，闻之，曰：「周公其不飨鲁祭乎！周公飨义，鲁无义。《诗》曰：『德音孔昭，视民不佻。』佻之谓甚矣，而壹用之，将谁福哉？」
戊子，晋平公卒。郑伯如晋，及河，晋人辞之。游吉遂如晋。九月，叔孙婼、齐国弱、宋华定、卫北宫喜、郑罕虎、许人、曹人、莒人、邾人、薛人、杞人、小邾人如晋，葬平公也。郑子皮将以币行。子产曰：「丧焉用币？用币必百两，百两必千人，千人至，将不行。不行，必尽用之。几千人而国不亡？」子皮固请以行。既葬，诸侯之大夫欲因见新君。叔孙昭子曰：「非礼也。」弗听。叔向辞之，曰：「大夫之事毕矣。而又命孤，孤斩焉在衰絰之中。其以嘉服见，则丧礼未毕。其以丧服见，是重受吊也。大夫将若之何？」皆无辞以见。子皮尽用其币，归，谓子羽曰：「非知之实难，将在行之。夫子知之矣，我则不足。《书》曰：『欲败度，纵败礼。』我之谓矣。夫子知度与礼矣，我实纵欲而不能自克也。」
昭子至自晋，大夫皆见。高强见而退。昭子语诸大夫曰：「为人子，不可不慎也哉！昔庆封亡，子尾多受邑而稍致诸君，君以为忠而甚宠之。将死，疾于公宫，辇而归，君亲推之。其子不能任，是以在此。忠为令德，其子弗能任，罪犹及之，难不慎也？丧夫人之力，弃德旷宗，以及其身，不亦害乎？《诗》曰：『不自我先，不自我后。』其是之谓乎！」
冬十二月，宋平公卒。初，元公恶寺人柳。欲杀之。及丧，柳炽炭于位，将至，则去之。比葬，又有宠。', '', '', '十年春季，周王朝历法的正月，有一颗星出现在婺女宿。郑国的裨灶对子产说：“七月初三日，晋国国君将要死去。现在岁星在玄枵，姜氏、任氏保守着这里的土地，婺女宿正当玄枵的首位，而有了妖星在这里出现，这是预告灾祸将要归于邑姜。邑姜，是晋侯的先妣。上天用七来记数，七月初三日，是逢公的死日，妖星就在这时候出现了，我是用它占卜而知道的。”
齐惠公的后代栾氏、高氏都喜欢喝酒，听信女人的话，所以别人的怨恨很多，势力比陈氏、鲍氏还要大而又讨厌陈氏、鲍氏。
夏季，有人告诉陈桓子说：“子良、子旗将要进攻陈氏、鲍氏。”同时也告诉了鲍氏。陈桓子把兵器发给部下并且亲自到鲍氏那里，路上遇到子良喝醉了酒而骑马奔驰，就进见鲍文子，鲍文子也已经把兵器发下去了。派人去看子良、子旗两个人，他们都准备喝酒。陈桓子说：“他们将攻打我们的传闻即使不真实，但是他们听说我发下兵器，就一定会追赶我们。趁着他们在喝酒，抢先攻打他们怎么样？”陈氏、鲍氏正在和睦的时候，就攻打栾氏、高氏。子良说：“先得到国君的支持，陈氏、鲍氏往哪里去？”于是就攻打虎门。
晏平仲穿着朝服站在虎门外边，四个家族召见他，他都不去。他的手下人说：“帮助陈氏、鲍氏吗？”晏平仲说：“他们有什么好处值得帮助？”“帮助栾氏、高氏吗？”晏平仲说：“难道能胜过陈氏、鲍氏？”“那么回去吗？”晏平仲说：“国君被攻打，回哪里去？”齐景公召见他，然后进去。齐景公为了派王黑用龙旗领兵而占卜，吉利，请求砍去三尺以后再使用。五月某日，在稷地作战，栾氏、高氏战败，在庄地又击败他们。国内的人们追赶他们，又在鹿门再次击败他们。栾施、高彊逃亡到鲁国来，陈氏、鲍氏分了他们的家产。
晏子对陈桓子说：“一定要把获得的栾氏、高氏家产交给国君。谦让，是德行的根本，让给别人叫做美德。凡是有血气的人，都有争夺之心，所以利益不能勉强，想着道义就能胜过别人。道义，是利益的根本。积聚利益就会产生妖孽。姑且使它不要积聚吧！可以让它慢慢地生长。”陈桓子把陈氏、鲍氏的家产全都交给齐景公，并请求在莒地告老退休。
陈桓子召见子山，私下准备了帷幕、器物、从者的衣服鞋子，并把棘地还给了子山。对子商也像这样做，而把封邑也还给了子商，对子周也是这样，而把夫于给了他。让子城、子公、公孙捷回国，并且都增加了他们的俸禄。凡是公子、公孙中没有俸禄的，私下把封邑分给他们。对国内贫困孤寡的人，私下给他们粮食。他说“《诗》说，‘把受到的赏赐摆出来赐给别人就创建了周朝’，这就是能够施舍的缘故。齐桓公因此而成为霸主。”
齐景公把莒地旁边的城邑赐给陈桓子，他辞谢了。穆孟姬为他请求高唐，陈氏开始昌大。秋季，七月，季平子进攻莒国，占领郠地。奉献俘虏，在亳社开始用人祭祀。臧武子在齐国，听到了这件事，说：“周公大约不去享用鲁国的祭祀了吧！周公享用合于道义的祭祀，鲁国不符合道义。《诗》说：‘那德行声誉特别显明，让百姓不要轻佻随便。’现在的做法可以说轻佻随便得过分了，而把人同牲畜一样使用，上天将会降福给谁呀！”
七月初三日，晋平公死了。郑简公去晋国，到达黄河，晋国人辞谢了，游吉就去到晋国。九月，叔孙婼、齐国国弱、宋国华定、卫国北宫喜、郑国罕虎、许人、曹人、莒人、邾人、滕人、薛人、杞人、小邾人到晋国去，这是为了安葬晋平公。
郑国的子皮准备带着财礼前去，子产说：“吊丧哪里要用财礼，用财礼一定要一百辆车拉，一定要一千人。一千人到那里，一时不会回来。不回来，财物一定会用光。几千人的礼物出去几次，国家还有不灭亡的？”子皮坚决请求带着财礼出去。安葬完毕，诸侯的大夫想要乘机拜见新国君。叔孙昭子说：“这是不合于礼的。”大家不听。叔向辞谢他们，说：“大夫们的送葬事情已经完了，又命令我与诸卿相见，我哀痛地处在服丧期间，如果用吉服相见，那么丧礼还没有完毕；如果以丧服相见，这就是再受一次吊唁。大夫们准备怎么办？”大家都没有理由再请求拜见。子皮用光了他带去的财礼。回国后，对子羽说：“并不是难于懂得道理，难在实行。他老人家懂得道理，我对道理还懂得不够。《书》说‘欲望败坏法度，放纵败坏礼仪’，这就是说我啊。他老人家懂得法度和礼仪了，我确实是放纵欲望，又不能自我克制。”
昭子从晋国归来，大夫们都来进见。高彊进见以后就退了出去。昭子对大夫们说：“做一个人的儿子不能不谨慎啊！过去庆封逃亡，子尾接受城邑之后，又稍稍奉还给国君一部分，国君认为他忠诚，因而很宠信他。临死以前，在公宫得病，坐上车子回家，国君亲自推着他走。他的儿子不能继承父业，因此在这里。忠诚是美德，他的儿子不能继承，罪过就会延及到他身上，怎么能不谨慎呢？丧失了那个人的功劳，丢掉德行，让宗庙闲空而无人祭祀，而罪过就延及到他身上，不也是祸害吗？《诗》说，‘忧患的到来不在我前头，也不在我后头’，说的就是这个吧！”
冬季，十二月，宋平公死去。当初，宋元公讨厌寺人柳，想要杀死他。等到有了丧事，寺人柳在元公坐的地方烧上炭火，元公将要到达，就把炭撤去。等到安葬以后，寺人柳又得到了宠信。', NULL, '', 'indent', 1559126631, '5cedf1e4ba39c80068967ce2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643060, '左传 · 昭公 · 昭公十一年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有一年春王二月，叔弓如宋。葬宋平公。夏四月丁巳，楚子虔诱蔡侯般杀之于申。楚公子弃疾帅师围蔡。五月甲申，夫人归氏薨。大蒐于比蒲。仲孙玃会邾子，盟于祲祥。秋，季孙意如会晋韩起、齐国弱、宋华亥、卫北宫佗、郑罕虎、曹人、杞人于厥憖。九月己亥，葬我小君齐归。冬十有一月丁酉，楚师灭蔡，执蔡世子有以归，用之。
【传】十一年春，王二月，叔弓如宋，葬平公也。
景王问于苌弘曰：「今兹诸侯，何实吉？何实凶？」对曰：「蔡凶。此蔡侯般弑其君之岁也，岁在豕韦，弗过此矣。楚将有之，然壅也。岁及大梁，蔡复，楚凶，天之道也。」
楚子在申，召蔡灵侯。灵侯将往，蔡大夫曰：「王贪而无信，唯蔡于感，今币重而言甘，诱我也，不如无往。」蔡侯不可。五月丙申，楚子伏甲而飨蔡侯于申，醉而执之。夏四月丁巳，杀之，刑其士七十人。公子弃疾帅师围蔡。
韩宣子问于叔向曰：「楚其克乎？」对曰：「克哉！蔡侯获罪于其君，而不能其民，天将假手于楚以毙之，何故不克？然肸闻之，不信以幸，不可再也。楚王奉孙吴以讨于陈，曰：『将定而国。』陈人听命，而遂县之。今又诱蔡而杀其君，以围其国，虽幸而克，必受其咎，弗能久矣。桀克有婚以丧其国，纣克东夷而陨其身。楚小位下，而亟暴于二王，能无咎乎？天之假助不善，非祚之也，厚其凶恶而降之罚也。且譬之如天，其有五材而将用之，力尽而敝之，是以无拯，大可没振。」
五月，齐归薨，大蒐于比蒲，非礼也。
孟僖子会邾庄公，盟于祲祥，修好，礼也。泉丘人有女梦以其帷幕孟氏之庙，遂奔僖子，其僚从之。盟于清丘之社，曰：「有子，无相弃也。」僖子使助薳氏之簉。反自祲祥，宿于薳氏，生懿子及南宫敬叔于泉丘人。其僚无子，使字敬叔。
楚师在蔡，晋荀吴谓韩宣子曰：「不能救陈，又不能救蔡，物以无亲，晋之不能，亦可知也已！为盟主而不恤亡国，将焉用之？」
秋，会于厥憖，谋救蔡也。郑子皮将行，子产曰：「行不远。不能救蔡也。蔡小而不顺，楚大而不德，天将弃蔡以壅楚，盈而罚之。蔡必亡矣，且丧君而能守者，鲜矣。三年，王其有咎乎！美恶周必复，王恶周矣。」晋人使狐父请蔡于楚，弗许。
单子会韩宣子于戚，视下言徐。叔向曰：「单子其将死乎！朝有着定，会有表，衣有禬带有结。会朝之言，必闻于表着之位，所以昭事序也。视不过结、禬之中，所以道容貌也。言以命之，容貌以明之，失则有阙。今单子为王官伯，而命事于会，视不登带，言不过步，貌不道容，而言不昭矣。不道，不共；不昭，不从。无守气矣。」
九月，葬齐归，公不戚。晋士之送葬者，归以语史赵。史赵曰：「必为鲁郊。」侍者曰：「何故？」曰：「归姓也，不思亲，祖不归也。」叔向曰：「鲁公室其卑乎？君有大丧，国不废蒐。有三年之丧，而无一日之戚。国不恤丧，不忌君也。君无戚容，不顾亲也。国不忌君，君不顾亲，能无卑乎？殆其失国。」
冬十一月，楚子灭蔡，用隐大子于冈山。申无宇曰：「不祥。五牲不相为用，况用诸侯乎？王必悔之。」
十二月，单成公卒。
楚子城陈、蔡、不羹。使弃疾为蔡公。王问于申无宇曰：「弃疾在蔡，何如？」对曰：「择子莫如父，择臣莫如君。郑庄公城栎而置子元焉，使昭公不立。齐桓公城谷而置管仲焉，至于今赖之。臣闻五大不在边，五细不在庭。亲不在外，羁不在内，今弃疾在外，郑丹在内。君其少戒。」王曰：「国有大城，何如？」对曰：「郑京、栎实杀曼伯，宋萧、亳实杀子游，齐渠丘实杀无知，卫蒲、戚实出献公，若由是观之，则害于国。末大必折，尾大不掉，君所知也。」', '', '', '十一年春季，周王朝历法的二月，叔弓到宋国去，这是为了安葬宋平公。
周景王向苌弘询问说：“现在诸侯之中，哪里吉祥，哪里凶险？”苌弘回答说：“蔡国凶险。这是蔡侯般杀死他国君的年份。岁星在豕韦，不会过这一年了。楚国将会据有蔡国，然而这是积累邪恶。岁星到达大梁，蔡国复国，楚国不吉利，这是上天的常道。”
楚灵王在申地，召见蔡灵侯。蔡灵侯打算前去，蔡国的大夫说：“楚王贪婪而没有信用，唯独怨恨蔡国。现在财礼重而说话甜，这是引诱我们，不如不去。”蔡灵侯不同意。三月十五日，楚灵王在申地埋伏甲士而设享礼招待蔡灵侯，让他喝醉了酒就囚禁了他。夏季，四月初七日，杀死了蔡灵侯，杀死了蔡国的士七十人。公子弃疾领兵包围蔡国。
韩宣子向叔向询问说：“楚国会战胜吗？”叔向回答说：“可以战胜的！蔡灵侯得罪了他的国君，而得不到百姓的拥护，上天将要借楚国的手来把他杀死，为什么不能战胜？然而肸听说，由于没有信用而得利，不可能有第二次。楚灵王事奉太孙吴讨伐陈国，说：‘将要安定你们的国家。’陈国人听从了他的命令，就灭了陈国建置为县。现在又诱骗蔡国而杀了他们的国君，来包围他们的国家，虽然侥幸而得胜，必然受到它的灾殃，不能长久了。夏桀战胜了有缗而丢掉了国家，商纣战胜东夷而丢掉了生命。楚国疆域小地位低，而屡次表现得比上面两个国王还要暴虐，能够没有灾祸吗？上天借助于坏人，不是降福给他，而是增多他的凶恶然后给他惩罚。而且比如像天有金、木、水、火、土五种材料而由人加以使用，材力用尽就丢弃了，因此楚国不可拯救，最后也不能兴盛了。”
五月，齐归去世。在比蒲举行盛大的阅兵，这是不符合礼的。
孟僖子会见邾庄公，在祲祥结盟，重修从前的友好，这是符合礼的。泉丘人有一个女儿，梦见用她的帷幕覆盖了孟氏的祖庙，就私奔到孟僖子那里，她的同伴也跟着去了。在清丘的土地神庙里盟誓说：“有了儿子，不要丢掉我！”孟僖子让她们住在薳氏那个地方做妾。孟僖子从祲祥回来，住在薳氏那里，在泉丘的那个女人生了懿子和南宫敬叔。她的同伴没有儿子，就让同伴抚养敬叔。
楚国的军队在蔡国，晋国的荀吴对韩宣子说：“不能救援陈国，又不能救援蔡国，别人因此就不来亲附了。晋国的不行也就可以知道。自己做盟主而不去为灭亡的国家担忧，又哪里用得着盟主？”
秋季，季孙意如和晋国韩起、齐国国弱、宋国华亥、卫国北宫佗、郑国罕虎、曹国人、杞国人在厥慭会见，为了商量救援蔡国。郑国的子皮将要出行。子产说：“走不远的，已经不能救援蔡国了。蔡国小而不顺服，楚国大而不施仁德，上天将要抛弃蔡国来使楚国积累邪恶，恶贯满盈然后惩罚它，蔡国一定灭亡了。而且丧失了国君而能够守住国家的也是很少的。到了三年，楚王大概有灾难吧！美和恶的岁星绕行一周的时候必然会有报应，楚灵王的邪恶已经要到岁星绕行一周的时候了。”晋国人派狐父到楚国请求楚国宽免蔡国，楚国人不答应。
单成公在戚地会见韩宣子，目光向下，说话迟缓。叔向说：“单子大概将要死了吧！朝见有规定的席位，会见有标志，衣服有交叉，衣带有交结子。会见和朝见的言语，一定要使在座的人都能听到，用它来表明事情有条有理。目光不低于衣服交叉和衣带交结之处，用它来端正仪容形貌。言语用来发布命令，仪容相貌用来表明态度，做不到就有错误。现在单子做天子的百官之长，在盟会上宣布天子的命令，目光不高于衣带，声音超过一步就听不到，相貌不能端正仪容，言事就不能明白了。不端正，就不恭敬；不明白，别人就不顺从。他已经没有保养身体的精气了。”
九月，安葬齐归，鲁昭公不悲痛。晋国来送葬的士人，回去把情况告诉史赵。史赵说：“昭公一定会寄居到别国的郊外。”侍从的人说：“为什么？”史赵说：“他是归氏的儿子，不想念母亲，祖先不会保佑他的。” 叔向说：“鲁国公室的地位要下降了吧！国君发生大丧事，国家却不停止阅兵。有三年的丧期，却没有一天的悲痛。国家不为丧事去悲哀，这是不畏惧国君。国君没有悲痛的样子，这是不顾念亲人。国人不畏惧国君，国君不顾念亲人，地位能够不下降吗？恐怕将会丢掉他的国家。”
冬季，十一月，楚灵王灭亡了蔡国，杀死了隐太子用来祭祀冈山。申无宇说：“不吉祥。五种牲口不能互相用来祭祀，何况用诸侯呢？国君一定要后悔的。”
十二月，单成公去世。
楚灵王在陈地、蔡地、不羹筑城。派弃疾做蔡公。楚灵王向申无宇询问说：“弃疾在蔡地怎么样？”申无宇回答说：“选择儿子没有像父亲那样合适的，选择臣子没有像国君那样合适的。郑庄公在栎地筑城而安置子元，让昭公不能立为国君。齐桓公在穀地筑城而安置管仲，到现在齐国还得到利益。臣听说五种大人物不在边境，五种小人物不在朝廷。亲近的人不在外边，寄居的人不在里边。现在弃疾在外边，郑丹在朝廷，君王恐怕要稍加戒备！”楚灵王说：“国都有高大的城墙，怎么样？”申无宇回答说：“在郑国的京地、栎地杀死了曼伯，在宋国的萧地、亳地杀死了子游，在齐国的渠丘杀死了公孙无知，在卫国的蒲地、戚地驱逐了献公。如果从这些看来，就有害于国都。树枝大了一定折断，尾巴大了就不能摇摆，这是君王所知道的。”', NULL, '', 'indent', 1559126671, '5cedf20c7b968a00767d540a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643061, '左传 · 昭公 · 昭公十二年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有二年春，齐高偃帅师纳北燕伯于阳。三月壬申，郑伯嘉卒。夏，宋公使华定来聘。公如晋，至河乃复。五月，葬郑简公。楚杀其大夫成熊。秋七月。冬十月，公子憖出奔齐。楚子伐徐。晋伐鲜虞。
【传】十二年春，齐高偃纳北燕伯款于唐，因其众也。
三月，郑简公卒，将为葬除。及游氏之庙，将毁焉。子大叔使其除徒执用以立，而无庸毁，曰：「子产过女，而问何故不毁，乃曰：『不忍庙也！诺，将毁矣！』」既如是，子产乃使辟之。司墓之室有当道者，毁之，则朝而塴；弗毁，则日中而塴。子大叔请毁之，曰：「无若诸侯之宾何！」子产曰：「诸侯之宾，能来会吾丧，岂惮日中？无损于宾，而民不害，何故不为？」遂弗毁，日中而葬。君子谓：「子产于是乎知礼。礼，无毁人以自成也。」
夏，宋华定来聘，通嗣君也。享之，为赋《蓼萧》，弗知，又不答赋。昭子曰：「必亡。宴语之不怀，宠光之不宣，令德之不知，同福之不受，将何以在？」
齐侯、卫侯、郑伯如晋，朝嗣君也。公如晋，至河乃复。取郠之役，莒人诉于晋，晋有平公之丧，未之治也，故辞公。公子憖遂如晋。晋侯享诸侯，子产相郑伯，辞于享，请免丧而后听命。晋人许之，礼也。晋侯以齐侯宴，中行穆子相。投壶，晋侯先。穆子曰：「有酒如淮，有肉如坻。寡君中此，为诸侯师。」中之。齐侯举矢，曰：「有酒如渑，有肉如陵。寡人中此，与君代兴。」亦中之。伯瑕谓穆子曰：「子失辞。吾固师诸侯矣，壶何为焉，其以中俊也？齐君弱吾君，归弗来矣！」穆子曰：「吾军帅强御，卒乘竞劝，今犹古也，齐将何事？」公孙叟趋进曰：「日旰君勤，可以出矣！」以齐侯出。
楚子谓成虎若敖之馀也，遂杀之。或谮成虎于楚子，成虎知之而不能行。书曰：「楚杀其大夫成虎。」怀宠也。
六月，葬郑简公。
晋荀吴伪会齐师者，假道于鲜虞，遂入昔阳。秋八月壬午，灭肥，以肥子绵皋归。
周原伯绞虐其舆臣，使曹逃。冬十月壬申朔，原舆人逐绞而立公子跪寻，绞奔郊。
甘简公无子，立其弟过。过将去成、景之族，成、景之族赂刘献公。丙申，杀甘悼公，而立成公之孙鳅。丁酉，杀献太子之傅庾皮之子过，杀瑕辛于市，及宫嬖绰、王孙没、刘州鸠、阴忌、老阳子。
季平子立，而不礼于南蒯。南蒯谓子仲：「吾出季氏，而归其室于公。子更其位。我以费为公臣。」子仲许之。南蒯语叔仲穆子，且告之故。
季悼子之卒也，叔孙昭子以再命为卿。及平子伐莒，克之，更受三命。叔仲子欲构二家，谓平子曰：「三命逾父兄，非礼也。」平子曰：「然。」故使昭子。昭子曰：「叔孙氏有家祸，杀适立庶，故婼也及此。若因祸以毙之，则闻命矣。若不废君命，则固有着矣。」昭子朝，而命吏曰：「婼将与季氏讼，书辞无颇。」季孙惧，而归罪于叔仲子。故叔仲小、南蒯、公子憖谋季氏。憖告公，而遂从公如晋。南蒯惧不克，以费叛如齐。子仲还，及卫，闻乱，逃介而先。及郊，闻费叛，遂奔齐。
南蒯之将叛也，其乡人或知之，过之而叹，且言曰：「恤恤乎，湫乎，攸乎！深思而浅谋，迩身而远志，家臣而君图，有人矣哉」南蒯枚筮之，遇《坤》三之《比》三，曰：「黄裳元吉。」以为大吉也，示子服惠伯，曰：「即欲有事，何如？」惠伯曰：「吾尝学此矣，忠信之事则可，不然必败。外强内温，忠也。和以率贞，信也。故曰『黄裳元吉』。黄，中之色也。裳，下之饰也。元，善之长也。中不忠，不得其色。下不共，不得其饰。事不善，不得其极。外内倡和为忠，率事以信为共，供养三德为善，非此三者弗当。且夫《易》，不可以占险，将何事也？且可饰乎？中美能黄，上美为元，下美则裳，参成可筮。犹有阙也，筮虽吉，未也。」
将适费，饮乡人酒。乡人或歌之曰：「我有圃，生之杞乎！从我者子乎，去我者鄙乎，倍其邻者耻乎！已乎已乎，非吾党之士乎！」
平子欲使昭子逐叔仲小。小闻之，不敢朝。昭子命吏谓小待政于朝，曰：「吾不为怨府。」楚子狩于州来，次于颖尾，使荡侯、潘子、司马督、嚣尹午、陵尹喜帅师围徐以惧吴。楚子次于乾溪，以为之援。雨雪，王皮冠，秦复陶，翠被，豹舄，执鞭以出，仆析父从。右尹子革夕，王见之，去冠、被，舍鞭，与之语曰：「昔我先王熊绎，与吕级、王孙牟、燮父、禽父，并事康王，四国皆有分，我独无有。今吾使人于周，求鼎以为分，王其与我乎？」对曰：「与君王哉！昔我先王熊绎，辟在荆山，筚路蓝缕，以处草莽。跋涉山林，以事天子。唯是桃弧、棘矢，以共御王事。齐，王舅也。晋及鲁、卫，王母弟也。楚是以无分，而彼皆有。今周与四国服事君王，将唯命是从，岂其爱鼎？」王曰：「昔我皇祖伯父昆吾，旧许是宅。今郑人贪赖其田，而不我与。我若求之，其与我乎？」对曰：「与君王哉！周不爱鼎，郑敢爱田？」王曰：「昔诸侯远我而畏晋，今我大城陈、蔡、不羹，赋皆千乘，子与有劳焉。诸侯其畏我乎？」对曰：「畏君王哉！是四国者，专足畏也，又加之以楚，敢不畏君王哉！」
工尹路请曰：「君王命剥圭以为金戚铋，敢请命。」王入视之。析父谓子革：「吾子，楚国之望也！今与王言如响，国其若之何？」子革曰：「摩厉以须，王出，吾刃将斩矣。」王出，复语。左史倚相趋过。王曰：「是良史也，子善视之。是能读《三坟》、《五典》、《八索》、《九丘》。」对曰：「臣尝问焉。昔穆王欲肆其心，周行天下，将皆必有车辙马迹焉。祭公谋父作《祈招》之诗，以止王心，王是以获没于祗宫。臣问其诗而不知也。若问远焉，其焉能知之？」王曰：「子能乎？」对曰：「能。其诗曰：『祈招之愔愔，式昭德音。思我王度，式如玉，式如金。形民之力，而无醉饱之心。』」王揖而入，馈不食，寝不寐，数日，不能自克，以及于难。
仲尼曰：「古也有志：『克己复礼，仁也』。信善哉！楚灵王若能如是，岂其辱于乾溪？」
晋伐鲜虞，因肥之役也。', '', '', '十二年春季，齐国的高偃把北燕伯款送到唐地，这是因为唐地的群众愿意接纳他。
三月，郑简公去世了。将要为安葬而清除道路上的障碍。到达游氏的祖庙，准备拆毁它。子太叔让他手下清道的人拿着工具站着，暂时不要去拆，说：“子产经过你们这里，如果问你们为什么不拆，就说：‘不忍毁掉祖庙啊。对，准备拆了。’”这样一番以后，子产就让清道的人避开游氏的祖庙。管理坟墓的人的房屋，有位于当路的。拆了它，就可以在早晨下葬，不拆，就要到中午才能下葬。子太叔请求拆了它，说：“不拆，把各国的宾客怎么办？”子产说：“各国的宾客能够前来参加我国的丧礼，难道会担心迟到中午？对宾客没有损害，只要百姓不遭危害，为什么不做？”于是就不拆，到中午下葬。君子认为：“子产在这件事情上懂得礼。礼，没有毁坏别人而成全了自己的事。”
夏季，宋国的华定来鲁国聘问，为新即位的宋君通好。设享礼招待他，为他赋《蓼萧》这首诗，他不知道，又不赋诗回答。昭子说：“他必定会逃亡。诗中所说宴会的笑语不怀念，宠信和光耀不宣扬，美好的德行不知道，共同的福禄不接受，他将凭什么在卿位？”
齐景公、卫灵公、郑定公到晋国去，朝见新立的国君。昭公到晋国去，到达黄河边就返回去了。占取郠地的那一次战役，莒国人向晋国控诉，晋国正好有平公的丧事，没有能够办理，所以辞谢昭公。于是公子慭就到了晋国。
晋昭公设享礼招待诸侯，子产辅佐郑定公，请求不参加享礼，请求丧服期满然后听取命令。晋国人答应了，这是合于礼的。
晋昭公和齐景公举行宴会，中行穆子相礼。以箭投入壶中为乐，晋昭公先投，穆子说：“有酒像淮流，有肉像高丘。寡君投中壶，统帅诸侯。”投中了。齐景公举起矢，说：“有酒如渑水，有肉像山陵。寡人投中壶，代君兴盛。”也投中了。伯瑕对穆子说：“您的话不恰当。我们本来就称霸诸侯了，壶有什么用？还是不要把投中看成希奇事。齐君认为我们国君软弱，回去以后不会来了。”穆子说：“我们军队统帅强而有力，士兵争相勉励，今天就像从前一样，齐国能做些什么？”公孙傁快步走进，说：“天晚了，国君也累了，可以出去了！”就和齐景公一起出去了。
楚灵王认为成虎是若敖的余党，就杀死了他。有人在楚灵王那里诬陷成虎，成虎知道了，但是不能出走。《春秋》记载说“楚杀其大夫成虎”，这是由于他留恋宠幸。
六月，安葬郑简公。
晋国的荀吴假装会合齐军的样子，向鲜虞借路，就乘机进入昔阳。秋季，八月初十日，灭亡肥国，带了肥子绵皋回国。
周朝的原伯绞残暴，他的许多手下人集体逃走。冬季，十月初一，原地大众赶走绞，立了公子跪寻。绞逃亡到郊地。
甘简公没有儿子，立了他兄弟甘过做国君。过准备去掉成公、景公的族人。成公、景公的族人贿赂刘献公，二十五日，杀死了甘悼公，立了成公的孙子。二十六日，杀了献太子保傅、庾皮的儿子过，在市上杀了瑕辛，又杀了宫嬖绰、王孙没、刘州鸠、阴忌、老阳子。
季平子即位后，对南蒯不加礼遇。南蒯对子仲说：“我赶走季氏，把他的家产归公，您取代他的地位，我带着费地作为公臣。”子仲答应了。南蒯告诉叔仲穆子，同时把原因告诉了他。
季悼子死的时候，叔孙昭子由于再命而做了卿士。等到季平子进攻莒国得胜，昭子改受三命。叔仲穆子想要离间季氏和叔孙氏两家，对平子说：“三命超过了父兄，这是不合于礼的。”平子说：“是这样。”所以就让昭子自己辞谢。昭子说：“叔孙氏发生家祸，杀死嫡子立了庶子，所以婼才到了这一步。如果是因为祸乱而来讨伐，那么我听从命令了。如果不废弃国君的命令，那么本来就有我的位次。”昭子朝见，命令官吏说：“婼打算和季氏打官司，写诉讼辞的时候不要偏袒。”季平子畏惧，就归罪于叔仲子，因此叔仲穆子、南蒯、子仲就打季氏的主意。子仲告诉昭公，就跟随昭公去了晋国。南蒯害怕打不赢，带了费地叛变到了齐国。子仲回国，到达卫国，听到动乱的情况，丢下副使先行逃回国内，到达郊外，听到费地叛乱就逃亡到齐国。
南蒯将要叛变的时候，他的家乡有人知道情况，走过他门口，叹了口气说：“忧愁啊，愁啊，忧啊！想法高而智谋浅，关系近而志向远，作为家臣而想为国君图谋，要有人材才行啊！”南蒯不提出所问的事情而占筮，得到《坤》卦变为《比》卦，卦辞说，“黄裳元吉”，就认为是大吉大利。把它给子服惠伯看，说：“如果有事情，怎么样？”惠伯说：“我曾经学习过《易》，如果是忠信的事情就可以符合卦辞的预测，不然就必定失败。外表强盛内部温顺，这是忠诚，用和顺来实行占卜，这是信用，所以说‘黄裳元吉’。黄，是内衣的颜色。裳，是下身的服装。元，是善的第一位。内心不忠诚，就和颜色不相符合。在下面不恭敬，就和服装不相符合。事情办理不好，就和标准不相符合。内外和谐就是忠，根据诚信办事就是恭，崇尚上述三种德行，就是善，不是这三种德行就无法承当卦辞的预测。而且《易》不能用来预测冒险的事情，您打算做什么呢？而且能不能在下位而恭敬呢？中美就是黄，上美就是元，下美就是裳，这三者都具备了才可以合于卦辞的预测。如果有所缺少，卦辞虽然吉利，未必能行。”
南蒯将要到费地去，请乡里的人喝酒。乡里有人唱歌说：“我有块菜地，却生长了枸杞啊！跟我走的是大男子呵，不跟我走的是鄙陋的人呵，背弃他亲人的可耻呵！得了得了，不是我们一伙的人士呵！”
季平子想要让昭子赶走叔仲子。叔仲子听到了，不敢朝见。昭子命令官吏告诉叔仲子在朝廷上等待办公，说：“我不充当怨恨聚集的角色。”
楚灵王在州来打猎阅兵，驻扎在颍尾，派荡侯、潘子、司马督、嚣尹午、陵尹喜带兵包围徐国以威胁吴国。楚灵王驻在乾谿，作为他们的后援。下雪，楚灵王头戴皮帽子，身穿秦国的羽衣，披着翠羽披肩，脚穿豹皮鞋，手拿着鞭子走了出来。仆析父作为随从。右尹子革晚上去朝见，楚王接见他，脱去帽子、披肩，放下鞭子，和他说话，说：“从前我们先王熊绎，和吕级、王孙牟、燮父、禽父一起事奉康王，齐、晋、鲁、卫四国都分赐了宝器，唯独我国没有。现在我派人到成周，请求把鼎作为赏赐，周天子会给我吗？”子革回答说：“会给君王啊！从前我们先王熊绎住在荆山僻处，乘柴车、穿破衣以开辟丛生的杂草，跋山涉水以事奉天子，只能用桃木弓、枣木箭作为进贡。齐国，是天子的舅父。晋国和鲁国、卫国，是天子的同胞兄弟。楚国因此没有得到赏赐，而他们却有，现在是周朝和四国顺服事奉君王了。将会都听从您的命令，难道还爱惜鼎？”楚灵王说：“以前我们的皇祖伯父昆吾，居住在旧许，现在郑国人贪利这里的土田而不给我们。我们如果求取，他会给我们吗？”子革回答说：“会给君王啊！周朝不爱惜鼎，郑国还敢爱惜土田？”楚灵王说：“从前诸侯认为我国偏僻而害怕晋国，现在我们大大地修筑陈国、蔡国两个不羹城的城墙，每地都有战车一千辆，您是有功劳的，诸侯会害怕我们了吧！”子革回答说：“害怕君王啊！光是这四个城邑，也就足够使人害怕了，又加上楚国全国的力量，岂敢不怕君王呢？”
工尹路请求说：“君王命令破开圭玉以装饰斧柄，谨请发布命令。”楚灵王走进去察看。析父对子革说：“您，是楚国有名望的人。现在和君王说话，答对好像回声一样，国家将怎么办？”子革说：“我磨快了刀刃等着，君王出来，我的刀刃就将砍下去了。”楚灵王出来，又和子革说话。左史倚相快步走过，楚灵王说：“这个人是好史官，您要好好看待他，这个人能够读《三坟》、《五典》、《八索》、《九丘》。”子革回答说：“下臣曾经问过他。从前周穆王想要放纵他自己的私心，周游天下，想要让天下到处都有他的车辙马迹。祭公谋父作了《祈招》这首诗来阻止穆王的私心，穆王因此得以善终于祗宫。下臣问他这首诗，他都不知道。如果问更远的事情，他哪里能知道？”楚灵王说：“您能知道吗？”子革回答说：“能。这首诗说：‘祈招安祥和悦，表现有德者的声音。想起我们君王的风度，样子好像玉好像金。保存百姓的力量，而自己没有醉饱之心。’”楚灵王向子革作揖，便走了进去，送上饭来不吃，睡觉睡不着，有好几天，不能克制自己，所以终于遇上了祸难。
孔子说：“古时候有话说：‘克制自己回到礼仪上，这就是仁。’真是说得好啊！楚灵王如果能够这样，难道还会在乾谿受到羞辱？”
晋国进攻鲜虞，这是乘灭亡肥国以后而顺路进攻的。', NULL, '', 'indent', 1559126716, '5cedf239a673f500682d8be0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643062, '左传 · 昭公 · 昭公十三年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有三年春，叔弓帅师围费。夏四月，楚公子比自晋归于楚，杀其君虔于乾溪。楚公子弃疾杀公子比。秋，公会刘子、晋侯、宋公、卫侯、郑伯、曹伯、莒子、邾子、滕子、薛伯、杞伯、小邾子于平丘。八月甲戌，同盟于平丘。公不与盟。晋人执季孙意如以归。公至自会。蔡侯庐归于蔡。陈侯吴归于陈。冬十月，葬蔡灵公。公如晋，至河乃复。吴灭州来。
【传】十三年春，叔弓围费，弗克，败焉。平子怒，令见费人执之以为囚俘。冶区夫曰：「非也。若见费人，寒者衣之，饥者食之，为之令主，而共其乏困。费来如归，南氏亡矣，民将叛之，谁与居邑？若惮之以威，惧之以怒，民疾而叛，为之聚也。若诸侯皆然，费人无归，不亲南氏，将焉入矣？」平子从之，费人叛南氏。
楚子之为令尹也，杀大司马薳掩而取其室。及即位，夺薳居田；迁许而质许围。蔡洧有宠于王，王之灭蔡也，其父死焉，王使与于守而行。申之会，越大夫戮焉。王夺斗韦龟中犨，又夺成然邑而使为郊尹。蔓成然故事蔡公，故薳氏之族及薳居、许围、蔡洧、蔓成然，皆王所不礼也。因群丧职之族，启越大夫常寿过作乱，围固城，克息舟，城而居之。
观起之死也，其子从在蔡，事朝吴，曰：「今不封蔡，蔡不封矣。我请试之。」以蔡公之命召子干、子皙，及郊，而告之情，强与之盟，入袭蔡。蔡公将食，见之而逃。观从使子干食，坎，用牲，加书，而速行。己徇于蔡曰：「蔡公召二子，将纳之，与之盟而遣之矣，将师而从之。」蔡人聚，将执之。辞曰：「失贼成军，而杀余，何益？」乃释之。朝吴曰：「二三子若能死亡，则如违之，以待所济。若求安定，则如与之，以济所欲。且违上，何适而可？」众曰：「与之。」乃奉蔡公，召二子而盟于邓，依陈、蔡人以国。楚公子比、公子黑肱、公子弃疾、蔓成然、蔡朝吴帅陈、蔡、不羹、许、叶之师，因四族之徒，以入楚。及郊，陈、蔡欲为名，故请为武军。蔡公知之曰：「欲速。且役病矣，请藩而已。」乃藩为军。蔡公使须务牟与史卑先入，因正仆人杀大子禄及公子罢敌。公子比为王，公子黑肱为令尹，次于鱼陂。公子弃疾为司马，先除王宫。使观从从师于乾溪，而遂告之，且曰：「先归复所，后者劓。」师及訾梁而溃。
王闻群公子之死也，自投于车下，曰：「人之爱其子也，亦如余乎？」侍者曰：「甚焉。小人老而无子，知挤于沟壑矣。」王曰：「余杀人子多矣，能无及此乎？」右尹子革曰：「请待于郊，以听国人。」王曰：「众怒不可犯也。」曰：「若入于大都而乞师于诸侯。」王曰：「皆叛矣。」曰：「若亡于诸侯，以听大国之图君也。」王曰：「大福不再，只取辱焉。」然丹乃归于楚。王沿夏，将欲入鄢。芋尹无宇之子申亥曰：「吾父再奸王命，王弗诛，惠孰大焉？君不可忍，惠不可弃，吾其从王。」乃求王，遇诸棘围以归。夏五月癸亥，王缢于芋尹申亥氏。申亥以其二女殉而葬之。
观从谓子干曰：「不杀弃疾，虽得国，犹受祸也。」子干曰：「余不忍也。」子玉曰：「人将忍子，吾不忍俟也。」乃行。国每夜骇曰：「王入矣！」乙卯夜，弃疾使周走而呼曰：「王至矣！」国人大惊。使蔓成然走告子干、子皙曰：「王至矣！国人杀君司马，将来矣！君若早自图也，可以无辱。众怒如水火焉，不可为谋。」又有呼而走至者曰：「众至矣！」二子皆自杀。丙辰，弃疾即位，名曰熊居。葬子干于訾，实訾敖。杀囚，衣之王服而流诸汉，乃取而葬之，以靖国人。使子旗为令尹。
楚师还自徐，吴人败诸豫章，获其五帅。
平王封陈、蔡，复迁邑，致群赂，施舍宽民，宥罪举职。召观从，王曰：「唯尔所欲。」对曰：「臣之先，佐开卜。」乃使为卜尹。使枝如子躬聘于郑，且致犨、栎之田。事毕，弗致。郑人请曰：「闻诸道路，将命寡君以犨、栎，敢请命。」对曰：「臣未闻命。」既复，王问犨、栎。降服而对，曰：「臣过失命，未之致也。」王执其手，曰：「子毋勤。姑归，不谷有事，其告子也。」他年芋尹申亥以王柩告，乃改葬之。
初，灵王卜，曰：「余尚得天下。」不吉，投龟，诟天而呼曰：「是区区者而不馀畀，余必自取之。」民患王之无厌也，故从乱如归。
初，共王无冢适，有宠子五人，无适立焉。乃大有事于群望，而祈曰：「请神择于五人者，使主社稷。」乃遍以璧见于群望，曰：「当璧而拜者，神所立也，谁敢违之？」既，乃与巴姬密埋璧于大室之庭，使五人齐，而长入拜。康王跨之，灵王肘加焉，子干、子皙皆远之。平王弱，抱而入，再拜，皆厌纽。斗韦龟属成然焉，且曰：「弃礼违命，楚其危哉！」
子干归，韩宣子问于叔向曰：「子干其济乎？」对曰：「难。」宣子曰：「同恶相求，如市贾焉，何难？」对曰：「无与同好，谁与同恶？取国有五难：有宠而无人，一也；有人而无主，二也；有主而无谋，三也；有谋而无民，四也；有民而无德，五也。子干在晋十三年矣，晋、楚之从，不闻达者，可谓无人。族尽亲叛，可谓无主。无衅而动，可谓无谋。为羁终世，可谓无民。亡无爱征，可谓无德。王虐而不忌，楚君子干，涉五难以弑旧君，谁能济之？有楚国者，其弃疾乎！君陈、蔡，城外属焉。苛慝不作，盗贼伏隐，私欲不违，民无怨心。先神命之。国民信之，芈姓有乱，必季实立，楚之常也。获神，一也；有民，二也；令德，三也；宠贵，四也；居常，五也。有五利以去五难，谁能害之？子干之官，则右尹也。数其贵宠，则庶子也。以神所命，则又远之。其贵亡矣，其宠弃矣，民无怀焉，国无与焉，将何以立？」宣子曰：「齐桓、晋文，不亦是乎？」对曰：「齐桓，卫姬之子也，有宠于僖。有鲍叔牙、宾须无、隰朋以为辅佐，有莒、卫以为外主，有国、高以为内主。从善如流，下善齐肃，不藏贿，不从欲，施舍不倦，求善不厌，是以有国，不亦宜乎？我先君文公，狐季姬之子也，有宠于献。好学而不贰，生十七年，有士五人。有先大夫子余、子犯以为腹心，有魏犨、贾佗以为股肱，有齐、宋、秦、楚以为外主，有栾、郤、狐、先以为内主。亡十九年，守志弥笃。惠、怀弃民，民从而与之。献无异亲，民无异望，天方相晋，将何以代文？此二君者，异于子干。共有宠子，国有奥主。无施于民，无援于外，去晋而不送，归楚而不逆，何以冀国？」
晋成虒祁，诸侯朝而归者皆有贰心。为取郠故，晋将以诸侯来讨。叔向曰：「诸侯不可以不示威。」乃并征会，告于吴。秋，晋侯会吴子于良。水道不可，吴子辞，乃还。
七月丙寅，治兵于邾南，甲车四千乘，羊舌鲋摄司马，遂合诸侯于平丘。子产、子大叔相郑伯以会。子产以幄幕九张行。子大叔以四十，既而悔之，每舍，损焉。及会，亦如之。
次于卫地，叔鲋求货于卫，淫刍荛者。卫人使屠伯馈叔向羹，与一箧锦，曰：「诸侯事晋，未敢携贰，况卫在君之宇下，而敢有异志？刍荛者异于他日，敢请之。」叔向受羹反锦，曰：「晋有羊舌鲋者，渎货无厌，亦将及矣。为此役也，子若以君命赐之，其已。」客从之，未退，而禁之。
晋人将寻盟，齐人不可。晋侯使叔向告刘献公曰：「抑齐人不盟，若之何？」对曰：「盟以厎信。君苟有信，诸侯不贰，何患焉？告之以文辞，董之以武师，虽齐不许，君庸多矣。天子之老，请帅王赋，『元戎十乘，以先启行』，迟速唯君。」叔向告于齐，曰：「诸侯求盟，已在此矣。今君弗利，寡君以为请。」对曰：「诸侯讨贰，则有寻盟。若皆用命，何盟之寻？」叔向曰：「国家之败，有事而无业，事则不经。有业而无礼，经则不序。有礼而无威，序则不共。有威而不昭，共则不明。不明弃共，百事不终，所由倾覆也。是故明王之制，使诸侯岁聘以志业，间朝以讲礼，再朝而会以示威，再会而盟以显昭明。志业于好，讲礼于等。示威于众，昭明于神。自古以来，未之或失也。存亡之道，恒由是兴。晋礼主盟，惧有不治。奉承齐牺，而布诸君，求终事也。君曰：『余必废之，何齐之有？』唯君图之，寡君闻命矣！」齐人惧，对曰：「小国言之，大国制之，敢不听从？既闻命矣，敬共以往，迟速唯君。」叔向曰：「诸侯有间矣，不可以不示众。」八月辛未，治兵，建而不旆。壬申，复旆之。诸侯畏之。
邾人、莒人言斥于晋曰：「鲁朝夕伐我，几亡矣。我之不共，鲁故之以。」晋侯不见公，使叔向来辞曰：「诸侯将以甲戌盟，寡君知不得事君矣，请君无勤。」子服惠伯对曰：「君信蛮夷之诉，以绝兄弟之国，弃周公之后，亦唯君。寡君闻命矣。」叔向曰：「寡君有甲车四千乘在，虽以无道行之，必可畏也，况其率道，其何敌之有？牛虽瘠，偾于豚上，其畏不死？南蒯、子仲之忧，其庸可弃乎？若奉晋之众，用诸侯之师，因邾、莒、杞、鄫之怒，以讨鲁罪，间其二忧，何求而弗克？」鲁人惧，听命。
甲戌，同盟于平丘，齐服也。令诸侯日中造于除。癸酉，退朝。子产命外仆速张于除，子大叔止之，使待明日。及夕，子产闻其未张也，使速往，乃无所张矣。
及盟，子产争承，曰：「昔天子班贡，轻重以列，列尊贡重，周之制也。卑而贡重者，甸服也。郑伯，男也，而使从公侯之贡，惧弗给也，敢以为请。诸侯靖兵，好以为事。行理之命，无月不至，贡之无艺，小国有阙，所以得罪也。诸侯修盟，存小国也。贡献无及，亡可待也。存亡之制，将在今矣。」自日中以争，至于昏，晋人许之。既盟，子大叔咎之曰：「诸侯若讨，其可渎乎？」子产曰：「晋政多门，贰偷之不暇，何暇讨？国不竞亦陵，何国之为？」
公不与盟。晋人执季孙意如，以幕蒙之，使狄人守之。司铎射怀锦，奉壶饮冰，以蒲伏焉。守者御之，乃与之锦而入。晋人以平子归，子服湫从。
子产归，未至，闻子皮卒，哭，且曰：「吾已，无为为善矣，唯夫子知我。」仲尼谓：「子产于是行也，足以为国基矣。《诗》曰：『乐只君子，邦家之基。』子产，君子之求乐者也。」且曰：「合诸侯，艺贡事，礼也。」
鲜虞人闻晋师之悉起也，而不警边，且不修备。晋荀吴自着雍以上军侵鲜虞，及中人，驱冲竞，大获而归。
楚之灭蔡也，灵王迁许、胡、沈、道、房、申于荆焉。平王即位，既封陈、蔡，而皆复之，礼也。隐大子之子庐归于蔡，礼也。悼大子之子吴归于陈，礼也。
冬十月，葬蔡灵公，礼也。
公如晋。荀吴谓韩宣子曰：「诸侯相朝，讲旧好也，执其卿而朝其君，有不好焉，不如辞之。」乃使士景伯辞公于河。
吴灭州来。令尹子期请伐吴，王弗许，曰：「吾未抚民人，未事鬼神，未修守备，未定国家，而用民力，败不可悔。州来在吴，犹在楚也。子姑待之。」
季孙犹在晋，子服惠伯私于中行穆子曰：「鲁事晋，何以不如夷之小国？鲁，兄弟也，土地犹大，所命能具。若为夷弃之，使事齐、楚，其何瘳于晋？亲亲，与大，赏共、罚否，所以为盟主也。子其图之。谚曰：『臣一主二。』吾岂无大国？」穆子告韩宣子，且曰：「楚灭陈、蔡，不能救，而为夷执亲，将焉用之？」乃归季孙。惠伯曰：「寡君未知其罪，合诸侯而执其老。若犹有罪，死命可也。若曰无罪而惠免之，诸侯不闻，是逃命也，何免之？为请从君惠于会。」宣子患之，谓叔向曰：「子能归季孙乎？」对曰：「不能。鲋也能。」乃使叔鱼。叔鱼见季孙曰：「昔鲋也得罪于晋君，自归于鲁君。微武子之赐，不至于今。虽获归骨于晋，犹子则肉之，敢不尽情？归子而不归，鲋也闻诸吏，将为子除馆于西河，其若之何？」且泣。平子惧，先归。惠伯待礼。', '', '', '十三年春季，叔弓包围费地，没有攻下，被击败。季平子发怒，命令接见城外的费地人，就抓住他们作为囚犯。冶区夫说“不对。如果接见费地人，受冻的给他们衣服，受饿的给他们饭吃，做他们的好主子，供应他们所缺乏的东西，费地人前来就会像回家一样，南氏就要灭亡了。百姓将要背叛他，谁跟他住在围城里？如果用威严使他们害怕，用愤怒使他们畏惧，百姓讨厌而背叛您，这是为他招聚了百姓。如果诸侯都这样，费地人没有地方可去，他们不亲近南氏，还会到哪里去呢？”平子听从了他的意见，费地人背叛了南氏。
当楚灵王做令尹的时候，杀了大司马薳掩并占取了他的家财。等到即位以后，夺取了薳居的土田。把许地的人迁走而以许围作为人质。蔡洧受到楚灵王的宠信，楚灵王灭亡蔡国的时候，他的父亲死在这次战争中，楚灵王派他参与守卫国都的任务然后灵王出发到乾谿。申地的盟会，越大夫受到侮辱。楚灵王夺取了鬬韦龟的封邑中犫，又夺取了成然的封邑，而让他做郊区大夫。蔓成然以前事奉蔡公。所以薳氏的亲族和薳居、许围、蔡洧、蔓成然，都是楚王不加礼遇的人。凭借着那些丧失职位的人的亲族，诱导越大夫常寿过发动叛乱，包围固城，攻下息舟，筑城而住在里面。
观起死的时候，他儿子从在蔡地，事奉朝吴，说：“现在还不恢复蔡国，蔡国将永远被灭亡了。我请求试一下。”用蔡公的名义召回子干、子皙，到达郊区，就把真像告诉了他们，强迫与他们结盟，进而入侵蔡地。蔡公正要吃饭，见到这种情况就逃走了。观从让子干吃饭，挖坑，杀牲口，把盟书放在牲口上，然后让他赶快走。观从自己对蔡地人公开宣布说：“蔡公召见这两个人，准备送到楚国，和他们结盟以后已经把他们派出去了，而且准备带领军队跟上去。”蔡地人聚集起来，准备抓住观从。观从解释说：“失去了贼人，组成了军队，杀我，有什么好处？”蔡地人就放了他。朝吴说：“您几位如果想为楚王而死去或者逃亡，那就应当不听蔡公的，以等待事情的成败。如果要求安定，那就应当赞成他，以成就他的愿望。而且要是违背上官，你们将到哪里去呢？”大家说：“赞成他！”就奉事蔡公，召见子干、子皙两个人而在邓地会盟，依赖陈地人和蔡地人复国的心愿达到自己的目的。楚国的公子比、公子黑肱、公子弃疾、蔓成然、蔡国的朝吴率领陈、蔡、不羹、许、叶等地的军队，依靠四族的族人，进入楚国。到达郊区，陈地人、蔡地人想要宣扬名声，所以请求筑起壁垒。蔡公知道了，说：“我们的行动必须迅速，而且役人已经很疲劳了，编成篱笆就行了。”于是就用篱笆围起军营。蔡公派须务牟和史猈先进入国都，靠着太子亲近的官杀了太子禄和公子罢敌。公子比做了楚王，公子黑肱做了令尹，驻扎在鱼陂。公子弃疾做了司马，先清除王宫，派观从到乾谿和那里的军队联系，乘机告诉他们所发生的情况，同时说：“先回去的可以恢复禄位资财，后回去的受割鼻子的重刑。”楚灵王的军队到达訾梁就溃散了。
楚灵王听到公子们的死讯，自己摔到车下，说：“别人爱他的儿子，也像我一样吗？”侍者说：“还有超过的。小人年老而没有儿子，自己知道会被挤到沟壑里去的。”楚灵王说：“我杀死别人的儿子很多了，能够不到这一步吗？”右尹子革说：“请在国都郊外等待，听从国内人们的选择。”楚灵王说：“大众的愤怒不可触犯。”子革说：“也许可以去到大的都邑，然后向诸侯请求出兵。”楚灵王说：“都背叛了。”子革说：“也许可以逃亡到诸侯那里，听从大国为君王的安排。”楚灵王说：“好运气不会再来，只是自取侮辱而已。”子革于是离开了楚灵王而回到楚国去。楚王沿汉水而下，打算到鄢地去。芋尹无宇的儿子申亥说：“我父亲再次触犯王命，君王没有诛戮，还有比这更大的恩惠吗？对国君不能忍心，恩惠不能丢弃，我还是跟着君王。”就去寻找楚灵王，在棘门前遇到楚灵王便一起回来。夏季，五月二十五日，楚灵王在芋尹申亥家上吊死了。申亥把两个女儿作为人殉而安葬了楚灵王。
观从对子干说：“如果不杀死弃疾，虽然得到国家，还会受到灾祸。”子干说：“我不忍心啊。”观从说：“别人会对您忍心的，我不忍心等待了。”于是就走了。都城里常常有人夜里惊叫说：“君王进来了！”十七日夜里，弃疾派人走遍各处喊叫说：“君王到了！”都城里的人们大为惊恐。让蔓成然跑去报告子干、子皙说：“君王到了，都城里的人杀了您的司马弃疾，就要杀来了。您如果早一点自己打主意，可以不受侮辱。众怒好像水火，没有法子可以想了。”又有喊叫着跑来的人，说：“大伙都来到了！” 子干他们两个人都自杀了。十八日，弃疾即位，改名为熊居。 把子干安葬在訾地，称之为訾敖。杀死一个囚犯，穿上国王的衣服，却让尸体在汉水中漂流，只得收尸安葬，来安定国内的人心。让子旗担任令尹。
楚军从徐国回来，吴军在豫章打败楚军，俘虏了他们的五个将领。
楚平王重建陈、蔡两国，让迁移出去的人回来，给有功之臣赏赐财物，取消苛政，赦免罪人，举拔被废弃的官员。召见观从，楚平王说：“你所要求的都可以答应。”观从说：“下臣的祖先是卜尹的助手。”于是就让他做了卜尹。楚平王派枝如子躬到郑国聘问，同时交还犫地、栎地的土田。聘问结束，并没有交还。郑国人请求说：“听道路传闻，打算把犫地、栎地赐给寡君，谨敢请命。”枝如子躬说：“下臣没有听到这样的命令。”回国复命以后，楚平王问起归还犫地、栎地的事，枝如子躬脱去上衣谢罪说：“臣有错，违背了王命，没有交还。”楚平王拉着他的手，说：“您不要归罪自己！先回去罢，我以后有事，还是会告诉您的。” 过了几年，芋尹申亥把楚灵王的棺材所在报告平王，于是就改葬灵王。
当初，楚灵王占卜说：“我希望能得到天下！”结果不吉利。灵王把龟甲扔在地上，责骂上天说：“这一点点好处都不给我，我一定要自己争取。”百姓担心灵王的欲望不能满足，所以参加动乱好像回家一样。
当初，楚共王没有嫡长子，有五个宠爱的儿子，不知道应该立谁。于是就遍祭名山大川的神明，祈祷说：“请求神灵在五个人中选择，让他主持国家。”于是就把玉璧展示给名山大川的神明，说：“正对着玉璧下拜的，是神明所立的，谁敢违背？”祭祀完毕，就和巴姬秘密地把玉璧埋在祖庙的院子里，让这五个人斋戒，然后按长幼次序下拜。康王两脚跨在玉璧上，灵王的胳臂放在玉璧上，子干、子皙都离璧很远。平王还小，由别人抱了进来，两次下拜都压在璧纽上。鬬韦龟把成然嘱托给平王，而且说：“抛弃礼义而违背天命，楚国大概危险了。”
子干回国，韩宣子向叔向询问说：“子干可能会成功吧？”叔向回答说：“很难。”韩宣子说：“人们有共同的憎恶而互相需求，好像商人一样，有什么难的？”叔向回答说：“没有人和他有共同的爱好，谁会和他有共同的憎恶？得到国家有五条难处：有了显贵的身分而没有贤人，这是第一条；有了贤人而没有内应，这是第二条；有了内应而没有谋略，这是第三条；有了谋略而没有百姓，这是第四条；有了百姓而没有德行，这是第五条。子干在晋国十三年了，晋国、楚国跟从他的人，没有听说有知名之士，可以说没有贤人。族人被消灭，亲人背叛，可以说没有内应，没有空子而轻举妄动，可以说没有谋略。在外边作客一辈子，可以说没有百姓。流亡在外没有怀念他的像征，可以说没有德行。楚王虽暴虐却不忌刻，楚国如果以子干为国君，关系到这五条难处而杀死原来的国君，谁能帮助他成功？享有楚国的，恐怕是弃疾吧！统治着陈、蔡两地，方城山以外也归属于他。烦杂和邪恶的事情没有发生，盗贼潜伏隐藏，虽然有私欲而不违背礼仪，百姓没有怨恨之心。先代神明任命他，国民相信他。羋姓发生动乱，必然就是小儿子立为国君，这是楚国的常例。得到神灵的保佑，这是一；拥有百姓，这是二；具有美德，这是三；受宠又显贵，这是四；所居地位符合常例，这是五。有五条利益来除掉五条难处，谁能够伤害他？子干的官职，不过是右尹；数他的地位，不过是庶子；论起神明所命令的，那又远离了玉璧。他的显贵丧失了，他的宠信丢掉了。百姓没有怀念他的。国内没有亲附他的，将凭什么立为国君？”韩宣子说：“齐桓公、晋文公不也是这样吗？”叔向回答说：“齐桓公，是卫姬的儿子，僖公宠爱他。有鲍叔牙、宾须无、隰朋作为辅助，有莒国、卫国作为外援，有国氏、高氏作为内应。从善好像流水一样行动迅速，不贪财货，不放纵私欲，施舍不知疲倦，求善不厌其烦。由于这样而享有国家，不也是合适的吗？至于我们的先君文公，是狐季姬的儿子，献公宠爱他。喜欢学习而专心一志，生下来十七年，得到了五个人才。有先大夫子馀，予犯作为心腹，有魏犫、贾佗作为左右手，有齐国、宋国、秦国、楚国作为外援，有栾氏、郤氏、狐氏、先氏作为内应，逃亡在外十九年，意志坚定。惠公、怀公丢弃百姓，百姓都跟着文公。献公没有别的亲人，百姓没有别的希望。上天正在保佑晋国，将会用谁来代替晋文公？这两位国君，和子干不同。共王还有受宠的儿子，国内还有高深莫测的君主。对百姓没有施予，在外边没有援助。离开晋国没有人送行，回到楚国没有人迎接，凭什么希望享有楚国？”
晋国落成了虒祁宫，诸侯前去朝见而回去的都对晋国有了二心。为了占取郠地的缘故，晋国打算带领诸侯前来讨伐。叔向说：“不能不向诸侯显示一下威力。”于是就召集全体诸侯会见，而且告诉吴国。秋季，晋昭公到良地打算会见吴王，水路不通，吴王辞谢不来，晋昭公就回去了。
七月二十九日，在邾国南部检阅军队。装载有甲士的战车四千辆。羊舌鲋代理司马，就在平丘会合诸侯。子产、子太叔辅助郑定公参加会见，子产带了帷布、幕布各九张出发，子太叔带了各四十张，不久又后悔，每住宿一次，就减少一些帷幕。等到达会见的地方，也和子产的一样了。
停驻在卫国境内，羊舌鲋向卫国索取财货，放纵手下砍柴草的人捣乱。卫国人派屠伯送给叔向羹汤和一箧锦缎，说：“诸侯事奉晋国，不敢怀有二心，何况在君王的房檐下，哪里敢有别的念头？砍柴的人和过去不大一样，谨敢请您阻止他们。”叔向接受了羹汤退回了锦缎，说：“晋国有一个羊舌鲋，贪求财货没有满足，也将要及于祸难了。为了这次的事情，您如果以君王的命令赐给他锦缎，事情就了结了。”客人照办，还没有退出去，羊舌鲋就下令禁止砍柴草人的捣乱。
晋国人要重温过去的盟约，齐国人不同意。晋昭公派叔向告诉刘献公说：“齐国人不肯结盟，怎么办？”刘献公回答说：“结盟是用来表示信用的，君王如果有信用，诸侯又没有二心，担什么心？用文辞向它报告，用武力对他监督，虽然齐国不同意，君王的功绩就很多了。天子的卿士请求带领天子的军队，‘大车十辆，在前面开路’，早晚只听凭君王决定。”叔向告诉齐国，说：“诸侯请求结盟，已经在这里了。现在君王以不结盟为有利，寡君以此作为请求。”齐国人回答说：“诸侯讨伐三心二意的国家，这才需要重温过去的盟约。如果都能听从命令，哪里需要重温旧盟？”叔向说：“国家的衰败，有了事情而没有贡赋，事情就不能正常。有了贡赋而没有礼节，正常会失去上下的次序。有了礼仪而没有威严，虽有次序也不能恭敬。有了威严而不能显著，虽有恭敬也不能昭告神明。不能昭告神明而失去了恭敬，各种事务没有结果，这就是国家败亡的原因。因此明王的制度，让诸侯每年聘问以记住自己的职责。每隔三年朝觐一次以演习礼仪，再次朝觐而诸侯会见以表现威严，再次会见而结盟以显示信义。在友好中记住自己的职责，用等级次序来演习礼仪，向百姓表现威严，向神明显示信义。从古以来，也许并没有缺失。存亡之道，常常由这里开始。晋国按照礼仪而主持结盟，惟恐不能办好，谨奉结盟的牺牲而展布于君王之前，以求得事情的良好结果。君王说‘我一定要废除它’，何必结盟呢？请君王考虑一下。寡君听到命令了。”齐国人恐惧，回答说：“小国说了话，大国加以决断，岂敢不听从？已经知道了你们的意思，我们会恭恭敬敬地前去，时间迟早听任君王的决定。”叔向说：“诸侯对晋国有嫌隙了，不能不向他们显示一下威力。”八月初四日，检阅军队，建立旌旗而不加飘带。初五日，又加上飘带。诸侯都感到畏惧。
邾人、莒人向晋国控诉说：“鲁国经常进攻我国，我国快要灭亡了。我国不能进贡财礼，是由于鲁国的缘故。”晋昭公不接见鲁昭公，派叔向前来辞谢说：“诸侯将要在初七日结盟，寡君知道不能事奉君王了，请君王不必劳驾。”子服惠伯回答说：“君王听信蛮夷的控诉，断绝兄弟国家的关系，丢弃周公的后代，也只能由得君王。你们的意见，我们已经知道了。”叔向说：“寡君有装载甲士的战车四千辆在那里，即使不按常道办事，也必然是可怕的了。何况按照常道，还有谁能抵挡？牛虽然瘦，压在小猪身上，难道怕小猪不死？对南蒯、子仲的忧虑，难道可以忘记吗？如果凭着晋国的大众，使用诸侯的军队，依靠邾国、莒国、杞国、鄫国的愤怒，来讨伐鲁国的罪过，利用你们对两个人的忧虑，什么要求得不到？”鲁国人害怕了，就听从了命令。
初七日，诸侯在平丘一起会盟，这是由于齐国顺服了。命令诸侯在中午到达盟会地点。初六日，朝见晋国完毕。子产命令外仆赶紧在盟会的地方搭起帐篷，子太叔阻拦仆人，让他们等第二天再搭。到晚上，子产听说他们还没有搭起帐篷，就派他们赶紧去，到那里已经没有地方可以搭帐篷了。
等到结盟的时候，子产争论进贡物品的轻重次序，说：“从前天子确定进贡物品的次序，轻重是根据地位排列的。地位尊贵，贡赋就重，这是周朝的制度，地位低下而贡赋重的，这是距天子附近的小国。郑伯，是男服。让我们按照公侯的贡赋标准，恐怕不能足数供应的，谨敢以此作为请求。诸侯之间应当休息甲兵，从事于友好。使者催问贡税的命令，没有一个月不来到。贡赋没有个限度，小国不能满足要求而有所缺少，这就是得罪的原因。诸侯重温旧盟，这是为了使小国得以生存。贡赋没有个限制，灭亡的日子将会马上到来。决定存亡的规定，就在今天了。”从中午开始争论，直到晚上，晋国人同意了。结盟以后，子太叔责备子产说：“诸侯如果来讨伐，难道可以轻易地对待吗？”子产说：“晋国的政事出于很多家族，他们不能一心一意，苟且偷安还来不及，哪里来得及讨伐别人？国家不和别国竞争，也就会遭到欺凌，还成个什么国家？”
鲁昭公不参加结盟。晋国人逮捕了季孙意如，用幕布遮住他，让狄人看守。司铎射怀里藏了锦，捧着用壶盛着的冰水，悄悄地爬过去。看守人阻止他，就把锦送给看守人，然后进去。晋国人带了季孙回到晋国，子服湫跟随前去。
子产回国，没有到达，听说子皮死了，号哭，说：“我完了！没有人帮我做好事了。只有他老人家了解我。”孔子认为：“子产在这次盟会中，足以成为国家的柱石了。《诗》说：‘是君子欢乐，他是国家和家族的柱石。’子产是君子中追求欢乐的人。”又说：“会合诸侯，制定贡赋的限度，这就是礼。”
鲜虞人听说晋国军队全部出动，可是并不在边境警戒，而且不修治武备。晋国的荀吴从著雍带领上军侵袭鲜虞，到达中人，驱使冲车和鲜虞人争逐，大获全胜然后回国。
楚国灭亡蔡国的时候，楚灵王把许国、胡国、沈国、道地、房地、申地的人迁到楚国国内。楚平王即位，在封了陈国、蔡国以后，就都让他们迁回去，这是合于礼的。使隐太子的儿子庐回到蔡国，这是合于礼的。使悼太子的儿子吴回到陈国，这是合于礼的。
冬季，十月，安葬蔡灵公，这是合于礼的。
鲁昭公到晋国去。荀吴对韩宣子说：“诸侯互相朝见，这是由于重温过去的友好。抓了他们的大夫而朝见他们的国君，这是不友好的，不如辞谢他。”于是就派士景伯在黄河边上辞谢昭公。
吴国灭亡州来，令尹子期请求进攻吴国。楚王不答应，说：“我没有安抚百姓，没有事奉鬼神，没有修缮防御设备，没有安定国家和家族，在这种情况下去使用百姓的力量，失败了来不及后悔。州来在吴国，就像在楚国一样。您姑且等着吧。”
季孙还在晋国，子服惠伯私下对中行穆子说：“鲁国事奉晋国，凭什么不如夷人的小国？鲁国，是兄弟，国土面积还很大，你们所规定的进贡物品都能具备。如果为了夷人而抛弃鲁国，让鲁国事奉齐国、楚国，对晋国有什么好处？亲近兄弟国家，赞助版图大的国家，奖赏能供给的国家，惩罚不供给的国家，这才是作为盟主的态度。您还是考虑一下！俗话说：‘一个臣子要有两个主人。’我们难道没有大国可以去奉事了？”穆子告诉韩宣子，而且说：“楚国灭亡陈、蔡，我们不能救援，反而为了夷人抓了亲人，这有什么用？”于是就把季孙放回去。惠伯说：“寡君不知道自己的罪过，会合诸侯而抓了他的元老。如果有罪，可以奉命而死。如果说没有罪而加恩赦免他，诸侯没有听到，这是逃避命令，这怎么算是赦免呢？请求赐给恩惠在盟会上赦免。”韩宣子担心这件事，对叔向说：“您能让季孙回去吗？”叔向回答说：“我办不到。鲋是能办得到的。”于是就让叔鱼去。叔鱼进见季孙，说：“从前鲋得罪了晋国国君，自己到了鲁国，如果不是武子的恩赐，不能到今天。即使老骨头已经回到晋国，等于您再次给了我生命，岂敢不为您尽心尽力？让您回去而您不回去，鲋听官吏说，将要在西河修造一所房子把您安置在那里，那怎么办？”说着，流下泪来。季孙害怕，就先回去了。惠伯不走，等晋国人以礼相送。', NULL, '', 'indent', 1559126764, '5cedf267d5de2b0070911b0c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643063, '左传 · 昭公 · 昭公十四年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有四年春，意如至自晋。三月，曹伯滕卒。夏四月。秋，葬曹武公。八月，莒子去疾卒。冬，莒杀其公子意恢。
【传】十四年春，意如至自晋，尊晋罪己也。尊晋、罪己，礼也。
南蒯之将叛也，盟费人。司徒老祁、虑癸伪废疾，使请于南蒯曰：「臣愿受盟而疾兴，若以君灵不死，请待间而盟。」许之。二子因民之欲叛也，请朝众而盟。遂劫南蒯曰：「群臣不忘其君，畏子以及今，三年听命矣。子若弗图，费人不忍其君，将不能畏子矣。子何所不逞欲？请送子。」请期五日。遂奔齐。侍饮酒于景公。公曰：「叛夫？」对曰：「臣欲张公室也。」子韩皙曰：「家臣而欲张公室，罪莫大焉。」司徒老祁、虑癸来归费，齐侯使鲍文子致之。
夏，楚子使然丹简上国之兵于宗丘，且抚其民。分贫，振穷；长孤幼，养老疾，收介特，救灾患，宥孤寡，赦罪戾；诘奸慝，举淹滞；礼新，叙旧；禄勋，合亲；任良，物官。使屈罢简东国之兵于召陵，亦如之。好于边疆，息民五年，而后用师，礼也。
秋八月，莒着丘公卒，郊公不戚。国人弗顺，欲立着丘公之弟庚舆。蒲余侯恶公子意恢而善于庚舆，郊公恶公子铎而善于意恢。公子铎因蒲余侯而与之谋曰：「尔杀意恢，我出君而纳庚舆。」许之。
楚令尹子旗有德于王，不知度。与养氏比，而求无厌。王患之。九月甲午，楚子杀斗成然，而灭养氏之族。使斗辛居郧，以无忘旧勋。
冬十二月，蒲余侯兹夫杀莒公子意恢，郊公奔齐。公子铎逆庚舆于齐。齐隰党、公子锄送之，有赂田。
晋邢侯与雍子争赂田，久而无成。士景伯如楚，叔鱼摄理，韩宣子命断旧狱，罪在雍子。雍子纳其女于叔鱼，叔鱼蔽罪邢侯。邢侯怒，杀叔鱼与雍子于朝。宣子问其罪于叔向。叔向曰：「三人同罪，施生戮死可也。雍子自知其罪而赂以买直，鲋也鬻狱，刑侯专杀，其罪一也。己恶而掠美为昏，贪以败官为墨，杀人不忌为贼。《夏书》曰：『昏、墨、贼，杀。』皋陶之刑也。请从之。」乃施邢侯而尸雍子与叔鱼于市。
仲尼曰：「叔向，古之遗直也。治国制刑，不隐于亲，三数叔鱼之恶，不为末减。曰义也夫，可谓直矣。平丘之会，数其贿也，以宽卫国，晋不为暴。归鲁季孙，称其诈也，以宽鲁国，晋不为虐。邢侯之狱，言其贪也，以正刑书，晋不为颇。三言而除三恶，加三利，杀亲益荣，犹义也夫！」
', '', '', '十四年春季，季孙意如从晋国回来，《春秋》这样记载，是尊重晋国而归罪于我国。尊重晋国而归罪于我国，这是合于礼的。
南蒯将要叛变的时候，和费地人结盟。司徒老祁、虑癸假装发病，派人请求南蒯说：“下臣愿意接受盟约，然而疾病发作。如果托您的福而不死，请等病稍稍好一点再和您结盟。”南蒯答应了。这两个人依靠百姓想要背叛南蒯，就要求集合百姓一起结盟。于是就劫持南蒯说：“下臣没有忘记他们的君主，但是害怕您直到现在，服从您的命令三年了。您如果不考虑，费地的人由于不能对君主狠心，将要不再害怕您了。您在哪里不能满足愿望？请让我们把您送走吧！”南蒯请求等待五天。到时就逃亡到齐国。侍奉齐景公喝酒，齐景公说“叛徒！”南蒯回答说：“下臣是为了想要公室强大。”子韩皙说：“家臣想要使公室强大，没有比这再大的罪过了。”司徒老祁、虑癸前来收回费地，齐景公也派鲍文子来送还费地。
夏季，楚平王派然丹在宗丘选拔检阅西部的军队，并且安抚当地的百姓。施舍贫贱，救济穷困，抚育年幼的孤儿，奉养有病的老人，收容单身汉，救济灾难，宽免孤儿寡妇的赋税，赦免有罪的人。禁治奸邪，提拔被埋没的贤才。以礼接待新人，交往旧人，奖赏功勋，和睦亲族，任用贤良，物色官吏。派屈罢在召陵选拔检阅东部地区的武装，也和西部一样。和四边的邻国友好，让百姓休养生息五年，然后用兵，这是合于礼的。
秋季，八月，莒国国君著丘公死了，郊公不悲哀。国内的人们不服从他，想要立著丘公的兄弟庚舆。蒲馀侯讨厌公子意恢而和庚舆要好。郊公讨厌公子铎而和意恢要好。公子铎依靠蒲馀侯并且和他商量，说：“你去杀死意恢，我赶走国君而接纳庚舆。”蒲馀侯答应了。
楚国的令尹子旗对楚平王有过功劳，但自己却不知道节制，和养氏勾结，贪得无厌。楚平王很担心。九月初三日，楚平王杀了鬬成然，灭掉养氏这一家族。让鬬辛住在郧地，以此表示不忘过去的功勋。
冬季，十二月，蒲馀侯兹夫杀死了莒国的公子意恢。郊公逃亡到齐国。公子铎在齐国迎接庚舆，齐国的隰党、公子鉏送行，莒国向齐国贿赂土田。
晋国的邢侯和雍子争夺鄐地的土田，很长时间也没有调解成功。士景伯去楚国，叔鱼代理他的职务。韩宣子命令他判处旧案，罪过在于雍子。雍子把女儿嫁给叔鱼，叔鱼宣判邢侯有罪。邢侯发怒，在朝廷上杀了叔鱼和雍子。韩宣子向叔向询问怎样治他们的罪。叔向说：“三个人罪状相同，杀了活着的人示众、暴露死者的尸体就可以了。雍子知道自己的罪过，而用他女儿作为贿赂来取得胜诉；鲋出卖法律，邢侯擅自杀人，他们的罪状相同。自己有罪恶而掠取别人的美名就是昏，贪婪而败坏职责就是不干净，杀人而没有顾忌就是贼。《夏书》说，‘昏、墨、贼，处死’，这是皋陶的刑法，请照办。”于是就杀了邢侯陈尸示众，并且把雍子和叔鱼的尸体摆在市上示众。
孔子说：“叔向，他有着古代流传下来的正直作风。治理国家大事使用刑法，不包庇亲人。三次指出叔鱼的罪恶，不给他减轻。做事合于道义啊，可以说得上正直了！平丘的盟会，责备他贪财，以宽免卫国，晋国就做到了不凶暴。让鲁国季孙回去，称道他的欺诈，以宽免鲁国，晋国就做到了不凌虐。邢侯这次案件，说明他的贪婪，以执行法律，晋国就做到了不偏颇。三次说话而除掉三次罪恶，加上三种利益。杀死了亲人而名声更加显著，这也是合乎道义的吧！”
', NULL, '', 'indent', 1559126804, '5cedf2917b968a00767d5aa3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643064, '左传 · 昭公 · 昭公十五年  ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有五年春王正月，吴子夷末卒。二月癸酉，有事于武宫。籥入，叔弓卒。去乐，卒事。夏，蔡朝吴出奔郑。六月丁巳朔，日有食之。秋，晋荀吴帅师伐鲜虞。冬，公如晋。
【传】十五年春，将禘于武公，戒百官。梓慎曰：「禘之日，其有咎乎！吾见赤黑之祲，非祭祥也，丧氛也。其在莅事乎？」二月癸酉，禘，叔弓莅事，籥入而卒。去乐，卒事，礼也。
楚费无极害朝吴之在蔡也，欲去之。乃谓之曰：「王唯信子，故处子于蔡。子亦长矣，而在下位，辱。必求之，吾助子请。」又谓其上之人曰：「王唯信吴，故处诸蔡，二三子莫之如也。而在其上，不亦难乎？弗图，必及于难。」夏，蔡人遂朝吴。朝吴出奔郑。王怒，曰：「余唯信吴，故置诸蔡。且微吴，吾不及此。女何故去之？」无极对曰：「臣岂不欲吴？然而前知其为人之异也。吴在蔡，蔡必速飞。去吴，所以剪其翼也。」
六月乙丑，王大子寿卒。
秋八月戊寅，王穆后崩。
晋荀吴帅师伐鲜虞，围鼓。鼓人或请以城叛，穆子弗许。左右曰：「师徒不勤，而可以获城，何故不为？」穆子曰：「吾闻诸叔向曰：『好恶不愆，民知所适，事无不济。』或以吾城叛，吾所甚恶也。人以城来，吾独何好焉？赏所甚恶，若所好何？若其弗赏，是失信也，何以庇民？力能则进，否则退，量力而行。吾不可以欲城而迩奸，所丧滋多。」使鼓人杀叛人而缮守备。围鼓三月，鼓人或请降，使其民见，曰：「犹有食色，姑修而城。」军吏曰：「获城而弗取，勤民而顿兵，何以事君？」穆子曰：「吾以事君也。获一邑而教民怠，将焉用邑？邑以贾怠，不如完旧，贾怠无卒，弃旧不祥。鼓人能事其君，我亦能事吾君。率义不爽，好恶不愆，城可获而民知义所，有死命而无二心，不亦可乎！」鼓人告食竭力尽，而后取之。克鼓而反，不戮一人，以鼓子鸢鞮归。
冬，公如晋，平丘之会故也。
十二月，晋荀跞如周，葬穆后，籍谈为介。既葬，除丧，以文伯宴，樽以鲁壶。王曰：「伯氏，诸侯皆有以镇抚室，晋独无有，何也？」文伯揖籍谈，对曰：「诸侯之封也，皆受明器于王室，以镇抚其社稷，故能荐彝器于王。晋居深山，戎狄之与邻，而远于王室。王灵不及，拜戎不暇，其何以献器？」王曰：「叔氏，而忘诸乎？叔父唐叔，成王之母弟也，其反无分乎？密须之鼓，与其大路，文所以大蒐也。阙巩之甲，武所以克商也。唐叔受之以处参虚，匡有戎狄。其后襄之二路，金戚钺，秬鬯，彤弓，虎贲，文公受之，以有南阳之田，抚征东夏，非分而何？夫有勋而不废，有绩而载，奉之以土田，抚之以彝器，旌之以车服，明之以文章，子孙不忘，所谓福也。福祚之不登，叔父焉在？且昔而高祖孙伯□，司晋之典籍，以为大政，故曰籍氏。及辛有之二子董之晋，于是乎有董史。女，司典之后也，何故忘之？」籍谈不能对。宾出，王曰：「籍父其无后乎！数典而忘其祖。」
籍谈归，以告叔向。叔向曰：「王其不终乎！吾闻之：『所乐必卒焉。』今王乐忧，若卒以忧，不可谓终。王一岁而有三年之丧二焉，于是乎以丧宾宴，又求彝器，乐忧甚矣，且非礼也。彝器之来，嘉功之由，非由丧也。三年之丧，虽贵遂服，礼也。王虽弗遂，宴乐以早，亦非礼也。礼，王之大经也。一动而失二礼，无大经矣。言以考典，典以志经，忘经而多言举典，将焉用之？」', '', '', '十五年春季，将要对武公举行大的祭祀，告诫百官斋戒，梓慎说：“大的祭祀那一天恐怕会有灾祸吧！我看到了红黑色的妖气，这不是祭祀的祥瑞，是丧事的气氛。恐怕会应在主持祭祀者的身上吧！”二月十五日，举行大的祭祀。叔弓主持祭祀，在奏籥的人进入时，突然死亡。撤去音乐，把祭祀进行完毕，这是合于礼的。
楚国的费无极嫉妒朝吴在蔡国，想要除去他，于是，就对朝吴说：“君王唯独相信您，所以把您安置在蔡国。您的年纪也不小了，可是地位低下，这是耻辱。一定要求得上位，我帮助您申请。”又对位在朝吴之上的人说：“君王唯独相信朝吴，所以把他安置在蔡国，您几位比不上他，而在他上面，不也很难吗？不加考虑，必然遭到祸难。”夏季，蔡国人赶走了朝吴，朝吴逃亡到郑国。楚平王发怒，说：“我唯独相信朝吴，所以把他安置在蔡国。而且如果没有朝吴，我到不了今天的地步。你为什么去掉他？”费无极回答说：“下臣难道不想要朝吴？然而早知道他有别的念头，朝吴在蔡国，蔡国必然很快飞走。去掉朝吴，这就是剪除蔡国的翅膀。”
六月初九日，王太子寿死了。
秋季，八月二十二日，王穆后去世。
晋国荀吴领兵进攻鲜虞，包围鼓国。鼓国有人请求带着城邑里面的人叛变，荀吴不答应，左右的随从说：“军人不辛劳而可以得到城邑，为什么不干？”荀吴说：“我听到叔向说：‘喜好、厌恶都不过分，百姓知道行动的方向，事情就没有不成功的。’有人带着我们的城邑叛变，这是我们所最厌恶的。别人带着城邑前来，我们为什么独独喜欢这样呢？奖赏我们所最厌恶的，对所喜欢的又怎么办？如果不加奖赏，这就是失信，又用什么保护百姓？力量达得到就进攻，否则就撤退，量力而行。我们不可以想要得到城邑而接近奸邪，这样所丧失的会更多。”于是让鼓国人杀了叛徒而修缮防御设备。包围鼓国三个月，鼓国有人请求投降。穆子让鼓国人进见，说：“看你们的脸色还好，姑且去修缮你们的城墙。”军吏说：“得到城邑而不占取，辛劳百姓而损毁武器，用什么事奉国君？”穆子说：“我用这样的做法来事奉国君。得到一个城邑而教百姓懈怠，这个城邑又哪里用得着？得到城邑而买来懈怠，不如保持一贯的勤快。买来懈怠，没有好结果。丢掉一贯的勤快，不吉祥。鼓国人能够事奉他们的国君，我也能够事奉我们的国君。合理就不出差错，喜好、厌恶都不过分，城邑可以得到而百姓懂得道义之所在，肯拼命而没有二心，不也是可以的吗？”鼓国人报告粮食吃完、力量用尽，然后占取了它。穆子攻下鼓国回国，不杀一个人，将鼓子鸢鞮带回国。
冬季，鲁昭公到晋国去，这是由于平丘那次盟会的缘故。
十二月，晋国的荀跞到成周去。安葬穆后，籍谈作为副使。安葬完毕，除去丧服。周景王和荀跞饮宴，把鲁国进贡的壶作为酒杯。周景王说：“伯父，诸侯都有礼器进贡王室，唯独晋国没有，为什么？”荀跞向籍谈作揖请他回答。籍谈回答说：“诸侯受封的时候，都从王室接受了明德之器，来镇抚国家，所以能把彝器进献给天子。晋国处在深山，戎狄和我们相邻，而远离王室，天子的威信不能达到，顺服戎人还来不及，怎么能进献彝器？”周景王说：“叔父，你忘了吧！叔父唐叔，是成王的同胞兄弟，难道反而没有分得赏赐吗？密须的名鼓和它的大辂车，是文王所用来检阅军队的。阙巩的铠甲，是武王用来攻克商朝的。唐叔接受了，用来居住在晋国的地域上，境内有着戎人和狄人。这以后襄王所赐的大辂、戎辂之车，斧钺、黑黍酿造的香酒，红色的弓、勇士，文公接受了，保有南阳的土田，安抚和征伐东边各国，这不是分得的赏赐还是什么？有了功勋而不废弃，有了功劳而记载在策书上，用土田来奉养他，用彝器来安抚他，用车服来表彰他，用旌旗来显耀他，子子孙孙不要忘记，这就是所谓福。这种福佑不记住，叔父的心哪里去了呢？而且从前你的高祖孙伯黡掌管晋国典籍，以主持国家大事，所以称为籍氏。等到辛有的第二个儿子董到了晋国，在这时就有了董氏的史官。你是司典的后氏，为什么忘了呢？”籍谈回答不出。客人退出去以后，周景王说：“籍谈的后代恐怕不能享有禄位了吧！举出了典故却忘记了祖宗。”
籍谈回国后，把这些情况告诉叔向。叔向说：“天子恐怕不得善终吧！我听说：‘喜欢什么，必然死在这上面。’现在天子把忧虑当成欢乐，如果因为忧虑致死，就不能说是善终。天子一年中有了两次三年之丧，在这个时候和吊丧的宾客饮宴，又要求彝器，把忧虑当成欢乐也太过分了，而且不合于礼。彝器的到来，由于嘉奖功勋，不是由于丧事。三年的丧礼，虽然贵为天子，服丧仍得满期，这是礼。现在天子即使不能服丧满期，饮宴奏乐也太早了，也是不合于礼的。礼，是天子奉行的重要规则。一次举动而失去了两种礼，这就没有重要规则了。言语用来考核典籍，典籍用来记载纲常。忘记了纲常而言语很多，举出了典故，又有什么用？”', NULL, '', 'indent', 1559126844, '5cedf2baba39c800689685c4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643065, '左传 · 昭公 · 昭公十六年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有六年春，齐侯伐徐。楚子诱戎蛮子杀之。夏，公至自晋。秋八月己亥，晋侯夷卒。九月，大雩。季孙意如如晋。冬十月，葬晋昭公。
【传】十六年春，王正月，公在晋，晋人止公。不书，讳之也。
齐侯伐徐。
楚子闻蛮氏之乱也，与蛮子之无质也，使然丹诱戎蛮子嘉杀之，遂取蛮氏。既而复立其子焉，礼也。
二月丙申，齐师至于蒲隧。徐人行成。徐子及郯人、莒人会齐侯，盟于蒲隧，赂以甲父之鼎。叔孙昭子曰：「诸侯之无伯，害哉！齐君之无道也，兴师而伐远方，会之，有成而还，莫之亢也，无伯也夫！《诗》曰：『宗周既灭，靡所止戾。正大夫离居，莫知我肄。』其是之谓乎！」
二月，晋韩起聘于郑，郑伯享之。子产戒曰：「苟有位于朝，无有不共恪。」孔张后至，立于客间。执政御之，适客后。又御之，适县间。客从而笑之。事毕，富子谏曰：「夫大国之人，不可不慎也，几为之笑而不陵我？我皆有礼，夫犹鄙我。国而无礼，何以求荣？孔张失位，吾子之耻也。」子产怒曰：「发命之不衷，出令之不信，刑之颇类，狱之放纷，会朝之不敬，使命之不听，取陵于大国，罢民而无功，罪及而弗知，侨之耻也。孔张，君之昆孙子孔之后也，执政之嗣也，为嗣大夫，承命以使，周于诸侯，国人所尊，诸侯所知。立于朝而祀于家，有禄于国，有赋于军，丧祭有职，受脤、归脤，其祭在庙，已有着位，在位数世，世守其业，而忘其所，侨焉得耻之？辟邪之人而皆及执政，是先王无刑罚也。子宁以他规我。」
宣子有环，有一在郑商。宣子谒诸郑伯，子产弗与，曰：「非官府之守器也，寡君不知。」子大叔、子羽谓子产曰：「韩子亦无几求，晋国亦未可以贰。晋国、韩子，不可偷也。若属有谗人交斗其间，鬼神而助之，以兴其凶怒，悔之何及？吾子何爱于一环，其以取憎于大国也，盍求而与之？」子产曰：「吾非偷晋而有二心，将终事之，是以弗与，忠信故也。侨闻君子非无贿之难，立而无令名之患。侨闻为国非不能事大字小之难，无礼以定其位之患。夫大国之人，令于小国，而皆获其求，将何以给之？一共一否，为罪滋大。大国之求，无礼以斥之，何餍之有？吾且为鄙邑，则失位矣。若韩子奉命以使，而求玉焉，贪淫甚矣，独非罪乎？出一玉以起二罪，吾又失位，韩子成贪，将焉用之？且吾以玉贾罪，不亦锐乎？」
韩子买诸贾人，既成贾矣，商人曰：「必告君大夫。」韩子请诸子产曰：「日起请夫环，执政弗义，弗敢复也。今买诸商人，商人曰，必以闻，敢以为请。」子产对曰：「昔我先君桓公，与商人皆出自周，庸次比耦，以艾杀此地，斩之蓬蒿藜藿，而共处之。世有盟誓，以相信也，曰：『尔无我叛，我无强贾，毋或丐夺。尔有利市宝贿，我勿与知。』恃此质誓，故能相保，以至于今。今吾子以好来辱，而谓敝邑强夺商人，是教弊邑背盟誓也，毋乃不可乎！吾子得玉而失诸侯，必不为也。若大国令，而共无艺，郑，鄙邑也，亦弗为也。侨若献玉，不知所成，敢私布之。」韩子辞玉，曰：「起不敏，敢求玉以徼二罪？敢辞之。」
夏四月，郑六卿饯宣子于郊。宣子曰：「二三君子请皆赋，起亦以知郑志。」子
赋《野有蔓草》。宣子曰：「孺子善哉！吾有望矣。」子产赋《郑之羔裘》。宣子曰：「起不堪也。」子大叔赋《褰裳》。宣子曰：「起在此，敢勤子至于他人乎？」子大叔拜。宣子曰：「善哉，子之言是！不有是事，其能终乎？」子游赋《风雨》，子旗赋《有女同车》，子柳赋《蘀兮》。宣子喜曰：「郑其庶乎！二三君子以君命贶起，赋不出郑志，皆昵燕好也。二三君子数世之主也，可以无惧矣。」宣子皆献马焉，而赋《我将》。子产拜，使五卿皆拜，曰：「吾子靖乱，敢不拜德？」宣子私觐于子产以玉与马，曰：「子命起舍夫玉，是赐我玉而免吾死也，敢不藉手以拜？」
公至自晋。子服昭伯语季平子曰：「晋之公室，其将遂卑矣。君幼弱，六卿强而奢傲，将因是以习，习实为常，能无卑乎？」
平子曰：「尔幼，恶识国？」
秋八月，晋昭公卒。
九月，大雩，旱也。郑大旱，使屠击、祝款、竖柎有事于桑山。斩其木，不雨。子产曰：「有事于山，蓺山林也，而斩其木，其罪大矣。」夺之官邑。
冬十月，季平子如晋葬昭公。平子曰：「子服回之言犹信，子服氏有子哉！」', '', '', '十六年春季，周王朝历法的正月，鲁昭公在晋国，晋国人扣留了昭公。《春秋》不记载这件事，这是由于隐讳。
齐景公发兵进攻徐国。
楚平王听说戎蛮部落发生动乱和蛮子没有信用，派然丹诱骗戎蛮子嘉而杀了他，就占领了戎蛮部落。不久以后又立了他的儿子，这是合于礼的。
二月十四日，齐军到达蒲隧。徐国人求和，徐子和郯人、莒人会见齐景公，在蒲隧结盟，送给齐景公甲父之鼎。叔孙昭子说：“诸侯没有领袖，对小国是个危险啊！齐国的国君无道，起兵攻打远方的国家，会见了他们，缔结了和约而回来，没有人能够抵御，这是由于没有霸主啊！《诗》说，‘宗周已经衰亡，无所安定。执政的大夫四处分居，没有人知道我的辛劳’，说的就是这个吧！”
三月，晋国的韩起到郑国聘问，郑定公设享礼招待他。子产告诫大家说：“如果在朝廷的享礼上有一个席位，不要发生不恭敬的事！”孔张后到，站在客人中间，主管典礼的人挡住他，去到客人后边，主管典礼的人又挡住他，他只好到悬挂乐器的间隙中待着。客人因此而笑他。事情结束，富子劝谏说：“对待大国的客人，是不可以不慎重的。难道说被他们笑话了，而他们会不欺负我们？我们样样都能做到有礼，那些人还会看不起我们。国家没有礼仪，凭什么求得光荣？孔张没有站到应该站的位置上，这是您的耻辱。”子产发怒说：“发布命令不恰当，命令发出后没有信用，刑罚偏颇不平，诉讼放任混乱，朝会有时失去礼仪，命令没有人听从，招致大国的欺负，使百姓疲惫而没有功劳，罪过来到还不知道，这是我的耻辱。孔张，是国君哥哥的孙子，子孔的后代，执政大夫的继承人，做了嗣大夫，他接受命令而出使，遍及诸侯各国，为国内的人们所尊敬，为诸侯所熟悉。他在朝中有官职，在家里有祖庙，接受国家的爵禄，分担战争所需的军赋，丧事、祭祀有一定的职责，接受和归还祭肉，辅助国君在宗庙里祭祀，已经有了固定的地位。他家在位已经几代，世世代代保守自己的家业，现在忘记了他应该处的地位，侨哪里能为他感到耻辱？不正派的人把一切都归罪于我这个执政的人，等于说先王没有刑罚。你最好用别的事来纠正我。”
韩宣子有一付玉环，其中一个在郑国的商人手里。韩宣子向郑定公请求得到那只玉环，子产不给，说：“这不是公家府库中保管的器物，寡君不知道。”子太叔、子羽对子产说：“韩子也没有太多的要求，对晋国也不能怀有二心。晋国和韩子都是不能轻视的。如果正好有坏人在两国中间挑拨，如果鬼神再帮着坏人，以兴起他们的凶心怒气，后悔哪里来得及？您为什么爱惜一个玉环而以此使大国来讨厌呢？为什么不去找来给他？”子产说：“我不是轻慢晋国而有二心，而是要始终事奉他们，所以才不给他，这是为了忠实和守信用的缘故。侨听说君子不是怕没有财物，而是担心没有美好的名声。侨又听说治理国家不是怕不能事奉大国、抚养小国，而是怕没有礼仪来安定他的地位。大国命令小国，如果一切要求都得到满足，将要用什么来不断地供给他们？一次给了，一次不给，所得的罪过更大。大国的要求，如果不合乎礼就驳斥，他们哪里会有满足的时候？我们如果将成为他们的边境城市，那就失去了作为一个国家的地位了。如果韩子奉命出使而求取玉环，他的贪婪邪恶就太过分了，难道不是罪过吗？拿出一只玉环而引起两种罪过，我们又失去了国家的地位，韩子成为贪婪的人，哪里用得着这样？而且我们因为玉环招来罪过，不也是太不值得了吧？”
韩宣子向商人购买玉环，已经成交了。商人说：“一定要告诉君大夫！”韩宣子向子产请求说：“前些时候我请求得到这只玉环，执政认为不合于道义，所以不敢再次请求。现在在商人那里买到了，商人说一定要把这件事情报告，谨敢以此作为请求。”子产回答说：“从前我们先君桓公和商人们都是从周朝迁居出来的，共同合作清除这块土地，砍去野草杂木，一起居住在这里。世世代代都有盟誓，互相信赖。誓辞说：‘你不要背叛我，我不要强买你的东西，不要乞求、不要掠夺。你有赚钱的买卖和宝贵的货物，我也不加过问。’仗着这个有信用的盟誓，所以能互相支持直到今天。现在你带着友好的情谊光临敝邑，而告诉我们去强夺商人的东西，这是教导敝邑背叛盟誓，未免不可以吧！如果得到玉环而失去诸侯，那您一定是不干的。如果大国有命令，要我们没原则地供应，那就是把郑国当成了边境里的城市，我们也是不干的。侨如果献上玉环，真不知道有什么道理和好处。谨敢私下向您布达。”韩宣子就把玉环退了回去，说：“我韩起虽然不聪明，岂敢求取玉环以求得两项罪过？谨请把玉环退还。”
夏季，四月，郑国的六卿为韩宣子在郊外饯行。韩宣子说：“请几位大臣都赋诗一首，起也可以了解郑国的意图。”子齹赋《野有蔓草》。韩宣子说：“孺子好啊！我有希望了。”子产赋郑国的《羔裘》。韩宣子说：“起是不敢当的。”子太叔赋《褰裳》。韩宣子说：“有起在这里，难道敢劳动您去事奉别人吗？”子太叔拜谢。韩宣子说：“好啊，您说起了这个！要不是有这回事，能从始至终地友好下去吗？”子游赋《风雨》，子旗赋《有女同车》。子柳赋《萚兮》。韩宣子很高兴，说：“郑国差不多要强盛了吧！几位大臣用国君的名义赏赐起，所赋的《诗》不出郑国之外，都是表示友好的。几位大臣都是传了几世的大夫，可以不再有所畏惧了。”韩宣子对他们都奉献马匹，而且赋了《我将》。子产拜谢，又让其他五个卿也都拜谢，说：“您安定动乱，岂敢不拜谢恩德！”韩宣子用玉和马作为礼物私下拜见子产，说：“您命令起舍弃那个玉环，这是赐给了我金玉良言而免我一死，岂敢不借此薄礼表示拜谢！”
鲁昭公从晋国回到国内，子服昭伯对季平子说：“晋国的公室的地位恐怕将要降低了。国君年幼而力量微弱，六卿强大而奢侈骄傲，将要由此而成习惯。习惯而成自然，能够不降低吗？”季平子说：“你年轻，哪里懂得国家大事？”
秋季，八月，晋昭公逝世。
九月，举行盛大的雩祭，这是由于发生了旱灾。郑国大旱，派屠击、祝款、竖柎祭祀桑山。砍去了山上的树木，不下雨。子产说：“祭祀山神，应当培育和保护山林，现在反而砍去山上的树木，他们的罪过就很大了。”于是就剥夺了他们的官爵和封邑。
冬季，十月，季平子到晋国去参加昭公的丧礼。季平子说：“子服回的话还是可以相信的，子服氏有了好儿子了！”', NULL, '', 'indent', 1559126891, '5cedf2e57b968a00767d5e1a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643066, '左传 · 昭公 · 昭公十七年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有七年春，小邾子来朝。夏六月甲戌朔，日有食之。秋，郯子来朝。八月，晋荀吴帅师灭陆浑之戎。冬，有星孛于大辰。楚人及吴战于长岸。
【传】十七年春，小邾穆公来朝，公与之燕。季平子赋《采叔》，穆公赋《菁菁者莪》。昭子曰：「不有以国，其能久乎？」
夏六月甲戌朔，日有食之。祝史请所用币。昭子曰：「日有食之，天子不举，伐鼓于社；诸侯用币于社，伐鼓于朝。礼也。」平子御之，曰：「止也。唯正月朔，慝未作，日有食之，于是乎有伐鼓用币，礼也。其馀则否。」大史曰：「在此月也。日过分而未至，三辰有灾。于是乎百官降物，君不举，辟移时，乐奏鼓，祝用币，史用辞。故《夏书》曰：『辰不集于房，瞽奏鼓，啬夫驰，庶人走。』此月朔之谓也。当夏四月，是谓孟夏。」平子弗从。昭子退曰：「夫子将有异志，不君君矣。」
秋，郯子来朝，公与之宴。昭子问焉，曰：「少皞氏鸟名官，何故也？」郯子曰：「吾祖也，我知之。昔者黄帝氏以云纪，故为云师而云名；炎帝氏以火纪，故为火师而火名；共工氏以水纪，故为水师而水名；大皞氏以龙纪，故为龙师而龙名。我高祖少皞挚之立也，凤鸟适至，故纪于鸟，为鸟师而鸟名。凤鸟氏，历正也。玄鸟氏，司分者也；伯赵氏，司至者也；青鸟氏，司启者也；丹鸟氏，司闭者也。祝鸠氏，司徒也；□鸠氏，司马也；鳲鸠氏，司空也；爽鸠氏，司寇也；鹘鸠氏，司事也。五鸠，鸠民者也。五雉，为五工正，利器用、正度量，夷民者也。九扈为九农正，扈民无淫者也。自颛顼以来，不能纪远，乃纪于近，为民师而命以民事，则不能故也。」仲尼闻之，见于郯子而学之。既而告人曰：「吾闻之：『天子失官，学在四夷』，犹信。」
晋侯使屠蒯如周，请有事于雒与三涂。苌弘谓刘子曰：「客容猛，非祭也，其伐戎乎？陆浑氏甚睦于楚，必是故也。君其备之！」乃警戎备。九月丁卯，晋荀吴帅师涉自棘津，使祭史先用牲于洛。陆浑人弗知，师从之。庚午，遂灭陆浑，数之以其贰于楚也。陆浑子奔楚，其众奔甘鹿。周大获。宣子梦文公携荀吴而授之陆浑，故使穆子帅师，献俘于文宫。
冬，有星孛于大辰，西及汉。申须曰：「彗所以除旧布新也。天事恒象，今除于火，火出必布焉。诸侯其有火灾乎？」梓慎曰：「往年吾见之，是其征也，火出而见。今兹火出而章，必火入而伏。其居火也久矣，其与不然乎？火出，于夏为三月，于商为四月，于周为五月。夏数得天。若火作，其四国当之，在宋、卫、陈、郑乎？宋，大辰之虚也；陈，大皞之虚也；郑，祝融之虚也，皆火房也。星孛天汉，汉，水祥也。卫，颛顼之虚也，故为帝丘，其星为大水，水，火之牡也。其以丙子若壬午作乎？水火所以合也。若火入而伏，必以壬午，不过其见之月。」郑裨灶言于子产曰：「宋、卫、陈、郑将同日火，若我用瓘斝玉瓒，郑必不火。」子产弗与。
吴伐楚。阳丐为令尹，卜战，不吉。司马子鱼曰：「我得上流，何故不吉。且楚故，司马令龟，我请改卜。」令曰：「鲂也，以其属死之，楚师继之，尚大克之」。吉。战于长岸，子鱼先死，楚师继之，大败吴师，获其乘舟余皇。使随人与后至者守之，环而堑之，及泉，盈其隧炭，陈以待命。吴公子光请于其众，曰：「丧先王之乘舟，岂唯光之罪，众亦有焉。请藉取之，以救死。」众许之。使长鬣者三人，潜伏于舟侧，曰：「我呼皇，则对，师夜从之。」三呼，皆迭对。楚人从而杀之，楚师乱，吴人大败之，取余皇以归。
', '', '', '十七年春季，小邾穆公来鲁国朝见，昭公和他一起饮宴。季平子赋了《采叔》，穆公赋了《菁菁者莪》。昭子说：“假若没有治理国家的人才，国家能长久吗？”
夏季，六月初一日，发生日食。掌管祭祀的官员请示所应该使用的祭品，昭子说：“发生日食，天子不进丰盛的菜肴，在土地神庙里击鼓。诸侯用祭品在土地神庙里祭祀，在朝廷上击鼓。这是礼制。”平子禁止这样做，说：“不能那样做。只有周正六月初一，阴气没有发作，发生日食，才击鼓用祭品，这是礼制。其他的时候就不这样。”太史说：“就是在这个月。太阳过了春分而没有到夏至，日、月、星有了灾殃，在这时候百官穿上素服，国君不进丰盛的菜肴，离开正寝躲过日食的时辰，乐工击鼓，祝使用祭品，史官使用辞令来祈祷消灾去祸。所以《夏书》说：‘日月交会不在正常的地位上，瞽师击鼓，啬夫驾车，百姓奔跑’，说的就是这个月初一的情况。正当夏正的四月，所以叫做孟夏。”平子不听从。昭子退出，说：“这个人将要有别的念头，他不把国君当成国君了。”
秋季，郯子来鲁国朝见，昭公和他一起饮宴。昭子询问他，说：“少皞氏用鸟名作为官名，这是什么缘故？”郯子说：“他是我的祖先，我知道。从前黄帝氏用云记事，所以设置各部门长官都用云字命名。炎帝氏用火记事，所以设置各部门长官都用火字命名。共工氏用水记事，所以设置各部门长官都用水字命名。太皞氏用龙记事，所以设置各部门长官都用龙来命名。我的高祖少皞挚即位的时候，凤鸟正好来到，所以就从鸟开始记事，设置各部门长官都用鸟来命名。凤鸟氏，就是掌管天文历法的官。玄鸟氏，就是掌管春分、秋分的官。伯赵氏，是掌管夏至、冬至的官。青鸟氏，是掌管立春、立夏的官。丹鸟氏，是掌管立秋、立冬的官。祝鸠氏，就是司徒；鴡鸠氏，就是司马；鸤鸠氏，就是司空；爽鸠氏，就是司寇；鹘鸠氏，就是司事。这五鸠，是鸠聚百姓的。五雉是五种管理手工业的官，是改善器物用具、统一尺度容量、让百姓得到平均的。九扈是九种管理农业的官，是制止百姓不让他们放纵的。自从颛顼以来，不能记述远古的事情，就从近古开始记述，做百姓的长官而用百姓的事情来命名，那已经是不能照过去办理了。”
孔子听到了这件事，进见郯子并向他学习古代官制。不久以后告诉别人说：“我听说，‘在天子那里失去了古代官制，官制的学问还保存在远方的小国’，这话还是可以相信的。”
晋顷公派屠蒯去到周朝，请求祭祀洛水和三涂山。苌弘对刘子说：“客人的脸色凶猛，不是为了祭祀，恐怕是为了进攻戎人吗！陆浑氏和楚国很友好，一定是这个缘故。您还是防备一下。”于是就对戎人加强警备。九月二十四日，晋国的荀吴领兵从棘津徒步涉水，让祭史先用牲口祭祀洛水。陆浑人不知道，部队就跟着打过去。二十七日，就灭亡了陆浑，责备他们和楚国勾结。陆浑子逃亡到楚国，他的部下逃亡到甘鹿。周朝俘虏了大批陆浑人。韩宣子梦见晋文公拉着荀吴而把陆浑交付给他，所以让他领兵，在晋文公庙里奉献俘虏。
冬季，彗星在大火星旁边出现，光芒西达银河。申须说：“彗星是用来除旧布新的，天上发生的事常常像征凶吉，现在对大火星清扫，大火星再度出现必然散布灾殃，诸侯各国恐怕会有火灾吧！”梓慎说：“去年我见到它，这就是它的征兆了。大火星出现而见到它。现在它在大火星出现时更加明亮，必然在大火星消失时潜伏。它和大火星在一起已经很久了，难道不是这样吗？大火星出现，在夏正是三月，在商正是四月，在周正是五月。夏代的历数和天像适应，如果发生火灾，恐怕有四个国家承当，在宋国、卫国、陈国、郑国吧！宋国，是大火星的分野；陈国，是太皞的分野；郑国，是祝融的分野，都是大火星所居住的地方。彗星到达银河，银河，就是水。卫国，是颛顼的分野，所以是帝丘，和它相配的星是大水。水，是火的阳姓配偶。恐怕会在丙子日或者壬午日发生火灾吧！水火会在那个时候配合的。如果大火星消失而彗星随着潜伏，一定在壬午日发生火灾，不会超过它发现的那个月。”郑国的神灶对子产说：“宋、卫、陈、郑四国将要在同一天发生火灾。如果我们用瓘斝玉瓒祭神，郑国一定不发生火灾。”子产不肯给。
吴国攻打楚国，楚国的阳匄做令尹，占卜战争的结果，不吉利。司马子鱼说：“我们地处上游，为什么不吉利？而且楚国的惯例，由司马在占卜前报告占卜的事情，我请求重新占卜。”报告说：“鲂带领部属战死，楚军跟上去，希望大获全胜。吉利。”两国军队在长岸作战，子鱼先战死，楚军跟着上去，把吴军打得大败，得到一条名叫馀皇的船，派随国人和后来到达的人看守，环绕这条船挖深沟，一直见到泉水，用炭填满，摆开阵势听候命令。吴国的公子光向大家请求说：“丢掉先王坐的船，难道只是光一人的罪过，大家也是有罪的。请求借大家的力量夺取回来以救一死。”大家答应了。派遣身高力壮的三个人偷偷地埋伏在船旁边，说：“我喊馀皇，你们就回答。”军队在夜里跟上去。喊了三次，埋伏的人都交替回答。楚国人上去把他们杀了。楚军混乱，吴军大败楚军，把馀皇号船夺回去了。', NULL, '', 'indent', 1559126931, '5cedf30f43e78c00672c4b96', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643067, '左传 · 昭公 · 昭公十八年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有八年春王三月，曹伯须卒。夏五月壬午，宋、卫、陈、郑灾。六月，邾人入鄅。秋，葬曹平公。冬，许迁于白羽。
【传】十八年春，王二月乙卯，周毛得杀毛伯过而代之。苌弘曰：「毛得必亡，是昆吾稔之日也，侈故之以。而毛得以济侈于王都，不亡何待！」
三月，曹平公卒。
夏五月，火始昏见。丙子，风。梓慎曰：「是谓融风，火之始也。七日，其火作乎！」戊寅，风甚。壬午，大甚。宋、卫、陈、郑皆火。梓慎登大庭氏之库以望之，曰：「宋、卫、陈、郑也。」数日，皆来告火。裨灶曰：「不用吾言，郑又将火。」郑人请用之，子产不可。子大叔曰：「宝，以保民也。若有火，国几亡。可以救亡，子何爱焉？」子产曰：「天道远，人道迩，非所及也，何以知之？灶焉知天道？是亦多言矣，岂不或信？」遂不与，亦不复火。
郑之未灾也，里析告子产曰：「将有大祥，民震动，国几亡。吾身泯焉，弗良及也。国迁其可乎？」子产曰：「虽可，吾不足以定迁矣。」及火，里析死矣，未葬，子产使舆三十人，迁其柩。火作，子产辞晋公子、公孙于东门。使司寇出新客，禁旧客勿出于宫。使子宽、子上巡群屏摄，至于大宫。使公孙登徙大龟。使祝史徙主祏于周庙，告于先君。使府人、库人各儆其事。商成公儆司宫，出旧宫人，置诸火所不及。司马、司寇列居火道，行火所□欣。城下之人，伍列登城。明日，使野司寇各保其征。郊人助祝史除于国北，禳火于玄冥、回禄，祈于四鄘。书焚室而宽其征，与之材。三日哭，国不市。使行人告于诸侯。宋、卫皆如是。陈不救火，许不吊灾，君子是以知陈、许之先亡也。
六月，鄅人藉稻。邾人袭鄅，鄅人将闭门。邾人羊罗摄其首焉，遂入之，尽俘以归。鄅子曰：「余无归矣。」从帑于邾，邾庄公反鄅夫人，而舍其女。秋，葬曹平公。往者见周原伯鲁焉，与之语，不说学。归以语闵子马。闵子马曰：「周其乱乎？夫必多有是说，而后及其大人。大人患失而惑，又曰：『可以无学，无学不害。』不害而不学，则苟而可。于是乎下陵上替，能无乱乎？夫学，殖也，不学将落，原氏其亡乎？」
七月，郑子产为火故，大为社祓禳于四方，振除火灾，礼也。乃简兵大蒐，将为蒐除。子大叔之庙在道南，其寝在道北，其庭小。过期三日，使除徒陈于道南庙北，曰：「子产过女而命速除，乃毁于而乡。」子产朝，过而怒之，除者南毁。子产及冲，使从者止之曰：「毁于北方。」
火之作也，子产授兵登陴。子大叔曰：「晋无乃讨乎？」子产曰：「吾闻之，小国忘守则危，况有灾乎？国之不可小，有备故也。」既，晋之边吏让郑曰：「郑国有灾，晋君、大夫不敢宁居，卜筮走望，不爱牲玉。郑之有灾，寡君之忧也。今执事手间然授兵登陴，将以谁罪？边人恐惧不敢不告。子产对曰：「若吾子之言，敝邑之灾，君之忧也。敝邑失政，天降之灾，又惧谗慝之间谋之，以启贪人，荐为弊邑不利，以重君之忧。幸而不亡，犹可说也。不幸而亡，君虽忧之，亦无及也。郑有他竟，望走在晋。既事晋矣，其敢有二心？」
楚左尹王子胜言于楚子曰：「许于郑，仇敌也，而居楚地，以不礼于郑。晋、郑方睦，郑若伐许，而晋助之，楚丧地矣。君盍迁许？许不专于楚。郑方有令政。许曰：『余旧国也。』郑曰：『余俘邑也。』叶在楚国，方城外之蔽也。土不可易，国不可小，许不可俘，仇不可启，君其图之。」楚子说。冬，楚子使王子胜迁许于析，实白羽。', '', '', '十八年春季，周王朝历法的二月十五日，周朝的毛得杀死毛伯过，取代了他。苌弘说：“毛得必然逃亡。这一天正好是昆吾恶贯满盈的日子，这是由于骄横的缘故。而毛得在天子的都城以骄横成事，不逃亡，还等待什么？”
三月，曹平公去世。
夏季，五月，大火星开始在黄昏出现。初七日，刮风。梓慎说：“这就叫做融风，是火灾的开始，七天以后，恐怕要发生火灾吧！”初九日，风刮得很大。十四日，风刮得更大。宋国、卫国、陈国、郑国都发生火灾。梓慎登上大庭氏的库房远望，说：“这是在宋国、卫国、陈国、郑国。”几天以后，四国都来报告火灾。裨灶说：“不采纳我的意见，郑国还要发生火灾。”郑国人请求采纳他的意见，子产不同意。子太叔说：“宝物是用来保护百姓的。如果有了火灾，国家差不多会灭亡。可以挽救灭亡，您爱惜它干什么？”子产说：“天道悠远，人道切近，两不相关。如何由天道而知人道？灶哪里懂得天道？这个人的话多了，难道不会偶尔也说中的？”于是就不给。后来也没有再发生火灾。
郑国还没有发生火灾以前，里析告诉子产说：“将要发生大的变异，百姓震动、国家差不多会灭亡。那时我自己已经死了，赶不上了。迁都，可以吗？”子产说：“即使可以，我一个人不能决定迁都的事。”等到发生火灾，里析已经死了，没有下葬，子产派三十个人搬走了他的棺材。火灾发生以后，子产在东门辞退了晋国的公子、公孙，派司寇把新来的客人送出去，禁止早已来的客人走出宾馆的大门。派子宽、子上巡察许多祭祀处所以至大宫。派公孙登迁走大龟，派祝史迁走宗庙里安放神主的石匣到周庙，向先君报告。派府人、库人各自戒备自己的管理范围以防火。派商成公命令司宫戒备，迁出先公的宫女，安置在火烧不到的地方。司马、司寇排列在火道上，到处救火。城下的人列队登城。第二天，派野司寇各自约束他们所征发的徒役不散开，郊区的人帮助祝史在国都北面清除地面修筑祭坛，向水神、火神祈祷，又在四城祈祷。登记被烧的房屋，减免他们的赋税，发给他们建筑材料。号哭三天，停止开放国都中的市场。派行人向诸侯报告。宋国和卫国也都这样。陈国不救火，许国不慰问火灾，君子因此而知道陈国、许国将先被灭亡。
六月，鄅国国君巡视农奴耕种，邾国军队入侵鄅国。鄅国人将要关闭城门。邾国人羊罗把关闭城门人的脑袋砍下，用手提着，就因此进入鄅国，把百姓全都俘虏回去。鄅子说：“我没有地方回去了。”跟随他的妻子儿女到了邾国。邾庄公归还了鄅君的夫人而留下了他的女儿。
秋季，安葬曹平公。去参加葬礼的人见到周朝的原伯鲁，跟他说话，发现他不爱学习。回去把情况告诉闵子马。闵子马说：“周朝恐怕要发生动乱了吧！一定是这种说法很多，然后才影响到当权的人。大夫们担心丢掉官位而不明事理，又说：‘可以不学习，不学习没有坏处。’认为没有坏处就不学习，得过且过，因此就下面驾凌上面，上面废弛，能不发生动乱吗？学习，如同种植一样，不学习就如草木一样枝叶要堕落，原氏大概要灭亡了吧！”
七月，郑国的子产因为火灾的缘故，大筑土地神庙，祭祀四方之神解除灾患，救治火灾的损失，这是合于礼的。于是精选士兵举行盛大检阅，将要进行清除场地。子太叔的家庙在路的南边，住房在路的北边，庙寝庭院不大。超过期限三天，他让清除场地的小工排列在路南庙北，说：“子产经过你们这里，下命令赶快清除，就向你们面对的方向动手拆除。”子产上朝，经过这里而发怒，清除的人就往南毁庙。子产走到十字路口，让跟随的人制止他们，说：“向北方拆除居室，不要拆庙。”
火灾发生的时候，子产登上城墙的矮墙颁发武器。子太叔说：“晋国恐怕要来讨伐吧？”子产说：“我听说，小国忘记守御就危险，何况有火灾呢？国家不能被轻视，就因为有防备。”不久，晋国的边防官吏责备郑国说：“郑国有了火灾，晋国的国君、大夫不敢安居，占卜占筮、奔走四处，遍祭名山大川，不敢爱惜牺牲玉帛。郑国有火灾，是寡君的忧虑。现在执事狠狠地颁发武器登上城墙，将要拿谁来治罪？边境上的人害怕，不敢不报告。”子产回答说：“像您所说的那样，敝邑的火灾，是君王的忧虑。敝邑的政事不顺，上天降下火灾，又害怕邪恶的人乘机打敝邑的主意，以引诱贪婪的人，再次增加敝邑的不利，以加重君王的忧虑。幸亏没有灭亡，还可以解释。如果不幸而被灭亡，君王虽然为敝邑忧虑，恐怕也是来不及了。郑国如果遭到别国的攻击，只有希望和投奔晋国，已经事奉晋国了，哪里敢有二心？”
楚国的左尹王子胜对楚平王说：“许国对于郑国，是仇敌，而住在楚国的土地上，由此对郑国无礼。晋国和郑国正在友好，郑国如果进攻许国，而晋国帮助他们，楚国就丧失土地了。君王何不把许国迁走？许国不为楚国专有，郑国正在推行好的政令。许国说：‘那里是我们原来的都城。’郑国说：‘那里是我们战胜而获得的城邑。’叶地在楚国，是方城山外边的屏障土地不能轻视，国家不能小看，许国不能俘虏，仇恨不能挑起，君王还是考虑一下！”楚王很高兴。冬季，楚平王派王子胜把许国迁移到析地，就是原来的白羽。', NULL, '', 'indent', 1559126969, '5cedf336c8959c0069f508dc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643068, '左传 · 昭公 · 昭公十九年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有九年春，宋公伐邾。夏五月戊辰，许世子止弑其君买。己卯，地震。秋，齐高发帅师伐莒。冬，葬许悼公。
【传】十九年春，楚工尹赤迁阴于下阴，令尹子瑕城郏。叔孙昭子曰：「楚不在诸侯矣！其仅自完也，以持其世而已。」
楚子之在蔡也，狊阜阳封人之女奔之，生大子建。及即位，使伍奢为之师。费无极为少师，无宠焉，欲谮诸王，曰：「建可室矣。」王为之聘于秦，无极与逆，劝王取之，正月，楚夫人嬴氏至自秦。
鄅夫人，宋向戌之女也，故向宁请师。二月，宋公伐邾，围虫。三月，取之。乃尽归鄅俘。
夏，许悼公疟。五月戊辰，饮大子止之药卒。大子奔晋。书曰：「弑其君。」君子曰：「尽心力以事君，舍药物可也。」
邾人、郳人、徐人会宋公。乙亥，同盟于虫。
楚子为舟师以伐濮。费无极言于楚子曰：「晋之伯也，迩于诸夏，而楚辟陋，故弗能与争。若大城城父而置大子焉，以通北方，王收南方，是得天下也。」王说，从之。故太子建居于城父。
令尹子瑕聘于秦，拜夫人也。
秋，齐高发帅师伐莒。莒子奔纪鄣。使孙书伐之。初，莒有妇人，莒子杀其夫，已为嫠妇。及老，托于纪鄣，纺焉以度而去之。及师至，则投诸外。或献诸子占，子占使师夜缒而登。登者六十人。缒绝。师鼓噪，城上之人亦噪。莒共公惧，启西门而出。七月丙子，齐师入纪。
是岁也，郑驷偃卒。子游娶于晋大夫，生丝，弱。其父兄立子瑕。子产憎其为人也，且以为不顺，弗许，亦弗止。驷氏耸。他日，丝以告其舅。冬，晋人使以币如郑，问驷乞之立故。驷氏惧，驷乞欲逃。子产弗遣。请龟以卜，亦弗予。大夫谋对，子产不待而对客曰：「郑国不天，寡君之二三臣，扎瘥夭昏，今又丧我先大夫偃。其子幼弱，其一二父兄惧队宗主，私族于谋而立长亲。寡君与其二三老曰：『抑天实剥乱是，吾何知焉？』谚曰：『无过乱门。』民有兵乱，犹惮过之，而况敢知天之所乱？今大夫将问其故，抑寡君实不敢知，其谁实知之？平丘之会，君寻旧盟曰：『无或失职。』若寡君之二三臣，其即世者，晋大夫而专制其位，是晋之县鄙也，何国之为？」辞客币而报其使。晋人舍之。
楚人城州来。沈尹戌曰：「楚人必败。昔吴灭州来，子旗请伐之。王曰：『吾未抚吾民。』今亦如之，而城州来以挑吴，能无败乎？」侍者曰：「王施舍不倦，息民五年，可谓抚之矣。」戌曰：「吾闻抚民者，节用于内，而树德于外，民乐其性，而无寇仇。今宫室无量，民人日骇，劳罢死转，忘寝与食，非抚之也。」
郑大水，龙斗于时门之外洧渊。国人请为
焉，子产弗许，曰：「我斗，龙不我觌也。龙斗，我独何觌焉？禳之，则彼其室也。吾无求于龙，龙亦无求于我。」乃止也。
令尹子瑕言蹶由于楚子曰：「彼何罪？谚所谓『室于怒，市于色』者，楚之谓矣。舍前之忿可也。」乃归蹶由。', '', '', '十九年春季，楚国的工尹赤把阴戎迁移到下阴，令尹子瑕在郏地筑城。叔孙昭子说：“楚国的意图不在于诸侯了！楚国仅仅是为了保持自己的完整，以维持它的世代而已。”
楚平王在蔡国的时候，郹阳封人的女儿私奔到他那里，生了太子建。等楚平王即位，派伍奢做太子的师傅，费无极做少师。费无极不受宠信，想要向楚平王诬谄太子以求得宠信，说：“建可以娶妻了。”楚平王为太子在秦国行聘，费无极参加迎娶，劝楚平王自己娶这个女子。正月，楚夫人嬴氏从秦国来到。
鄅国国君的夫人，是宋国向戌的女儿，所以向宁请求出兵。二月，宋公进攻邾国，包围虫地。三月，占取虫地，就把鄅国的俘虏全部放了回去。
夏季，许悼公得了疟疾，五月初五日，喝了太子止送的药就死了。太子逃亡到晋国。《春秋》记载说：“弑其君。”君子说：“尽心竭力以事奉国君，不进药物是可以的。”
邾人、郳人、徐人会见宋元公。五月十二日，在虫地一起结盟。
楚平王发动水军以进攻濮地。费无极对楚平王说：“晋国称霸诸侯的时候，接近中原诸国，而楚国偏僻简陋，所以不能和它争夺，如果扩大城父的城墙，而把太子安置在那里，用来和北方交通，君王收取南方，这是得到天下的好办法。”楚平王很高兴，听从了他的话，所以太子建住在城父。
令尹子瑕到秦国聘问，这是为了拜谢把夫人嫁给楚国。
秋季，齐国的高发领兵进攻莒国，莒共公逃亡到纪鄣。派孙书进攻纪鄣。当初，莒国有个女人，莒子杀了她丈夫，她就成了寡妇。等到年老，寄居在纪鄣，纺线搓绳量了城墙的高度然后收藏起来。等到齐军来到，就把绳扔出城外。有人把绳子献给孙书，孙书派部队在夜里攀绳登城，登上城的有六十个人，绳子断了。军队击鼓呐喊，城上的人也呐喊。莒共公害怕，打开西门逃跑。七月十四日，齐军进入纪鄣。
这一年，郑国的驷偃死了。驷偃在晋国的大夫那里娶妻，生了丝，年幼。他的父辈兄辈立了驷乞做继承人。子产讨厌驷乞的为人，而且认为不合继承法规，不答应，也不制止。驷氏害怕。过了几天，丝把情况告诉了他舅父。冬季，晋国的大夫派人带了财礼来到郑国，询问立驷乞的缘故。驷氏害怕，驷乞想要逃走，子产不让走；请求用龟甲占卜，也不给。大夫们商量如何回答晋国，子产不等他们商量好就回答客人说：“郑国不能得到上天保佑，寡君的几个臣下不幸夭折病死。现在又丧失了我们的先大夫偃。他的儿子年幼，他的几位父兄害怕断绝宗主，和族人商量立了年长的亲子。寡君和他的几位大夫说：‘或者上天确实搅乱了这种继承法，我能知道什么呢？’俗话说，‘不要走过动乱人家的门口’，百姓动武作乱，尚且害怕经过那里，而何况敢知道上天所降的动乱？现在大夫将要询问它的原因，寡君确实不敢知道，还有谁知道？平丘的会盟，君王重温过去的盟约说：‘不要有人失职。’如果寡君的几个臣下，其中有去世的，晋国的大夫却要专断地干涉他们的继承人，这是晋国把我们当作边境的县城了，还成什么国家？”辞谢客人的财礼而回报他的使者，晋国人对这件事不再过问了。
楚国人在州来筑城，沈尹戌说：“楚国人一定失败。过去吴国灭亡州来，子旗请求攻打吴国。君王说：‘我没有安抚好我的百姓。’现在也像当时一样，而又在州来筑城去挑动吴国，能够不失败吗？”侍者说：“君王施舍从不厌倦，让百姓休息五年，可以说安抚他们了。”沈尹戌说：“我听说安抚百姓，在国内节约开支，在国外树立德行，百姓生活安乐，而没有仇敌。现在宫室的规模没有限度，百姓时刻惊恐不安，辛劳疲乏至死还没有人收葬，忘掉了睡觉和吃饭，这不是安抚他们。”
郑国发生大水灾，有龙在时门外边的洧渊争斗，国内的人们请求举行禳灾求福的祭祀。子产不答应，说：“我们争斗，龙不看，龙争斗，我们为什么偏要去看呢？向它们祭祀祈祷，那洧渊本来是龙居住的地方，岂能使它们离开呢？我们对龙没有要求，龙对我们也没有要求。”于是就停止了祭祀。
令尹子瑕为蹶由对楚平王说：“他有什么罪？俗话所说‘在家里发怒，而在大街上给人脸色看’，说的就是楚国了。舍弃以前的怨愤可以了。”楚平王就把蹶由放回了吴国。
', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b699782772d459482102b", "shortContent": "本年《经》《左传》记宋、邾、鲁、楚、蔡、秦、鄅、许、晋、郳、徐、濮、齐、莒、郑、吴等十余国事，而详于楚、郑、齐三国。所记楚事，依次为楚求自保而不欲称霸诸侯；楚平王娶原为太子建所聘之秦女为夫人，在城父筑城安置太子建；楚释放吴王弟蹶由回国。郑事有二：其一，贵族驷氏以子游弟子瑕为宗主以及晋国的干涉。其二，子产论龙斗。齐事为齐国伐莒占领纪鄣。\n\n关于子产处理驷氏家族立宗主所引起的纠纷的记载展示了子产对待内...", "authors": ["贺圣迪", "魏自厚"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b6a2882772d45948211bd", "shortContent": "春秋后期，伍员（子胥）在吴国政治生活中、在吴楚和吴越双边关系中曾经发挥过举足轻重的作用。他原为楚国人，因父兄含冤被杀而逃亡吴国，凭着他卓越的智慧和才能，在吴国屡建功勋。他与孙武等佐吴王统领大军攻入楚国京城，鞭楚平王之尸，报父兄被杀之仇，最后官至相国，封于申。这段文字就是记述深刻影响公元前6世纪后期到公元前5世纪前期中国南方几个重要诸侯国历史进程的一系列事件的起因。\n\n楚国太子建出奔和伍子胥父兄的被...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559127011, '5cedf360ba39c80068968be8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643069, '左传 · 昭公 · 昭公二十年', NULL, 2, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十年春王正月。夏，曹公孙会自鄸出奔宋。秋，盗杀卫侯之兄絷。冬十月，宋华亥、向宁、华定出奔陈。十有一月辛卯，蔡侯卢卒。
【传】二十年春，王二月己丑，日南至。梓慎望氛曰：「今兹宋有乱，国几亡，三年而后弭。蔡有大丧。」叔孙昭子曰：「然则戴、桓也！汏侈无礼已甚，乱所在也。」
费无极言于楚子曰：「建与伍奢将以方城之外叛。自以为犹宋、郑也，齐、晋又交辅之，将以害楚。其事集矣。」王信之，问伍奢。伍奢对曰：「君一过多矣，何言于谗？」王执伍奢。使城父司马奋扬杀大子，未至，而使遣之。三月，大子建奔宋。王召奋扬，奋扬使城父人执己以至。王曰：「言出于余口，入于尔耳，谁告建也？」对曰：「臣告之。君王命臣曰：『事建如事余。』臣不佞，不能苟贰。奉初以还，不忍后命，故遣之。既而悔之，亦无及已。」王曰：「而敢来，何也？」对曰：「使而失命，召而不来，是再奸也。逃无所入。」王曰：「归。」从政如他日。
无极曰：「奢之子材，若在吴，必忧楚国，盍以免其父召之。彼仁，必来。不然，将为患。」王使召之，曰：「来，吾免而父。」棠君尚谓其弟员曰：「尔适吴，我将归死。吾知不逮，我能死，尔能报。闻免父之命，不可以莫之奔也；亲戚为戮，不可以莫之报也。奔死免父，孝也；度功而行，仁也；择任而往，知也；知死不辟，勇也。父不可弃，名不可废，尔其勉之，相从为愈。」伍尚归。奢闻员不来，曰：「楚君、大夫其旰食乎！」楚人皆杀之。
员如吴，言伐楚之利于州于。公子光曰：「是宗为戮而欲反其仇，不可从也。」员曰：「彼将有他志。余姑为之求士，而鄙以待之。」乃见鱄设诸焉，而耕于鄙。
宋元公无信多私，而恶华、向。华定、华亥与向宁谋曰：「亡愈于死，先诸？」华亥伪有疾，以诱群公子。公子问之，则执之。夏六月丙申，杀公子寅、公子御戎、公子朱、公子固、公孙援、公孙丁、拘向胜、向行于其廪。公如华氏请焉，弗许，遂劫之。癸卯，取大子栾与母弟辰、公子地以为质。公亦取华亥之子无戚、向宁之子罗、华定之子启，与华氏盟，以为质。
卫公孟絷狎齐豹，夺之司寇与鄄，有役则反之，无则取之。公孟恶北宫喜、褚师圃，欲去之。公子朝通于襄夫人宣姜，惧，而欲以作乱。故齐豹、北宫喜、褚师圃、公子朝作乱。
初，齐豹见宗鲁于公孟，为骖乘焉。将作乱，而谓之曰：「公孟之不善，子所知也。勿与乘，吾将杀之。」对曰：「吾由子事公孟，子假吾名焉，故不吾远也。虽其不善，吾亦知之。抑以利故，不能去，是吾过也。今闻难而逃，是僭子也。子行事乎，吾将死之，以周事子，而归死于公孟，其可也。」
丙辰，卫侯在平寿，公孟有事于盖获之门外，齐子氏帷于门外而伏甲焉。使祝蛙置戈于车薪以当门，使一乘从公孟以出。使华齐御公孟，宗鲁骖乘。及闳中，齐氏用戈击公孟，宗鲁以背蔽之，断肱，以中公孟之肩，皆杀之。
公闻乱，乘，驱自阅门入，庆比御公，公南楚骖乘，使华寅乘贰车。及公宫，鸿
魋驷乘于公，公载宝以出。褚师子申遇公于马路之衢，遂从。过齐氏，使华寅肉袒，执盖以当其阙。齐氏射公，中南楚之背，公遂出。寅闭郭门，逾而从公。公如死鸟，析朱锄宵从窦出，徒行从公。
齐侯使公孙青聘于卫。既出，闻卫乱，使请所聘。公曰：「犹在竟内，则卫君也。」乃将事焉。遂从诸死鸟，请将事。辞曰：「亡人不佞，失守社稷，越在草莽，吾子无所辱君命。」宾曰：「寡君命下臣于朝，曰：『阿下执事。』臣不敢贰。」主人曰：「君若惠顾先君之好，昭临敝邑，镇抚其社稷，则有宗祧在。」乃止。卫侯固请见之，不获命，以其良马见，为未致使故也。卫侯以为乘马。宾将掫，主人辞曰：「亡人之忧，不可以及吾子。草莽之中，不足以辱从者。敢辞。」宾曰：「寡君之下臣，君之牧圉也。若不获扞外役，是不有寡君也。臣惧不免于戾，请以除死。」亲执铎，终夕与于燎。
齐氏之宰渠子召北宫子。北宫氏之宰不与闻谋，杀渠子，遂伐齐氏，灭之。丁巳晦，公入，与北宫喜盟于彭水之上。秋七月戊午朔，遂盟国人。八月辛亥，公子朝、褚师圃、子玉霄、子高鲂出奔晋。闰月戊辰，杀宣姜。卫侯赐北宫喜谥曰贞子，赐析朱锄谥曰成子，而以齐氏之墓予之。
卫侯告宁于齐，且言子石。齐侯将饮酒，遍赐大夫曰：「二三子之教也。」苑何忌辞，曰：「与于青之赏，必及于其罚。在《康诰》曰：『父子兄弟，罪不相及。』况在群臣？臣敢贪君赐以干先王？」
琴张闻宗鲁死，将往吊之。仲尼曰：「齐豹之盗，而孟絷之贼，女何吊焉？君子不食奸，不受乱，不为利疚于回，不以回待人，不盖不义，不犯非礼。」
宋华、向之乱，公子城、公孙忌、乐舍、司马强、向宜、向郑、楚建、郳甲出奔郑。其徒与华氏战于鬼阎，败子城。子城适晋。华亥与其妻必盥而食所质公子者而后食。公与夫人每日必适华氏，食公子而后归。华亥患之，欲归公子。向宁曰：「唯不信，故质其子。若又归之，死无日矣。」公请于华费遂，将攻华氏。对曰：「臣不敢爱死，无乃求去忧而滋长乎！臣是以惧，敢不听命？」公曰：「子死亡有命，余不忍其呴。」冬十月，公杀华、向之质而攻之。戊辰，华、向奔陈，华登奔吴。向宁欲杀大子，华亥曰：「干君而出，又杀其子，其谁纳我？且归之有庸。」使少司寇牼以归，曰：「子之齿长矣，不能事人，以三公子为质，必免。」公子既入，华牼将自门行。公遽见之，执其手曰：「余知而无罪也，入，复而所。」
齐侯疥，遂痁，期而不瘳，诸侯之宾问疾者多在。梁丘据与裔款言于公曰：「吾事鬼神丰，于先君有加矣。今君疾病，为诸侯忧，是祝史之罪也。诸侯不知，其谓我不敬。君盍诛于祝固、史嚣以辞宾？」公说，告晏子。晏子曰：「日宋之盟，屈建问范会之德于赵武。赵武曰：『夫子之家事治，言于晋国，竭情无私。其祝史祭祀，陈信不愧。其家事无猜，其祝史不祈。』建以语康王，康王曰：『神人无怨，宜夫子之光辅五君，以为诸侯主也。』」公曰：「据与款谓寡人能事鬼神，故欲诛于祝史。子称是语，何故？」对曰：「若有德之君，外内不废，上下无怨，动无违事，其祝史荐信，无愧心矣。是以鬼神用飨，国受其福，祝史与焉。其所以蕃祉老寿者，为信君使也，其言忠信于鬼神。其适遇淫君，外内颇邪，上下怨疾，动作辟违，从欲厌私。高台深池，撞钟舞女，斩刈民力，输掠其聚，以成其违，不恤后人。暴虐淫从，肆行非度，无所还忌，不思谤讟不惮鬼神，神怒民痛，无悛于心。其祝史荐信，是言罪也。其盖失数美，是矫诬也。进退无辞，则虚以求媚。是以鬼神不飨其国以祸之，祝史与焉。所以夭昏孤疾者，为暴君使也。溲再辕稼鬼神。」公曰：「然则若之何？」对曰：「不可为也：山林之木，衡鹿守之；泽之萑蒲，舟鲛守之；薮之薪蒸，虞候守之。海之盐蜃，祈望守之。县鄙之人，入从其政。逼介之关，暴征其私。承嗣大夫，强易其贿。布常无艺，征敛无度；宫室日更，淫乐不违。内宠之妾，肆夺于市；外宠之臣，僭令于鄙。私欲养求，不给则应。民人苦病，夫妇皆诅。祝有益也，诅亦有损。聊、摄以东，姑、尤以西，其为人也多矣。虽其善祝，岂能胜亿兆人之诅？君若欲诛于祝史，修德而后可。」公说，使有司宽政，毁关，去禁，薄敛，已责。
十二月，齐侯田于沛，招虞人以弓，不进。公使执之，辞曰：「昔我先君之田也，旃以招大夫，弓以招士，皮冠以招虞人。臣不见皮冠，故不敢进。」乃舍之。仲尼曰：「守道不如守官，君子韪之。」
齐侯至自田，晏子侍于遄台，子犹驰而造焉。公曰：「唯据与我和夫！」晏子对曰：「据亦同也，焉得为和？」公曰：「和与同异乎？」对曰：「异。和如羹焉，水火醯醢盐梅以烹鱼肉，燀之以薪。宰夫和之，齐之以味，济其不及，以泄其过。君子食之，以平其心。君臣亦然。君所谓可而有否焉，臣献其否以成其可。君所谓否而有可焉，臣献其可以去其否。是以政平而不干，民无争心。故《诗》曰：『亦有和羹，既戒既平。鬷嘏无言，时靡有争。』先王之济五味，和五声也，以平其心，成其政也。声亦如味，一气，二体，三类，四物，五声，六律，七音，八风，九歌，以相成也。清浊，小大，短长，疾徐，哀乐，刚柔，迟速，高下，出入，周疏，以相济也。君子听之，以平其心。心平，德和。故《诗》曰：『德音不瑕。』今据不然。君所谓可，据亦曰可；君所谓否，据亦曰否。若以水济水，谁能食之？若琴瑟之专一，谁能听之？同之不可也如是。」
饮酒乐。公曰：「古而无死，其乐若何？」晏子对曰：「古而无死，则古之乐也，君何得焉？昔爽鸠氏始居此地，季萴因之，有逢伯陵因之，蒲姑氏因之，而后大公因之。古者无死，爽鸠氏之乐，非君所愿也。」
郑子产有疾，谓子大叔曰：「我死，子必为政。唯有德者能以宽服民，其次莫如猛。夫火烈，民望而畏之，故鲜死焉。水懦弱，民狎而玩之，则多死焉。故宽难。」疾数月而卒。大叔为政，不忍猛而宽。郑国多盗，取人于萑苻之泽。大叔悔之，曰：「吾早从夫子，不及此。」兴徒兵以攻萑苻之盗，尽杀之，盗少止。
仲尼曰：「善哉！政宽则民慢，慢则纠之以猛。猛则民残，残则施之以宽。宽以济猛，猛以济宽，政是以和。《诗》曰：『民亦劳止，汔可小康。惠此中国，以绥四方。』施之以宽也。『毋从诡随，以谨无良。式遏寇虐，惨不畏明。』纠之以猛也。『柔远能迩，以定我王。』平之以和也。又曰：『不竞不絿，不刚不柔。布政优优，百禄是遒。』和之至也。」
及子产卒，仲尼闻之，出涕曰：「古之遗爱也。」', '', '', '二十年春季，周王朝历法的二月初一日，冬至。梓慎观察云气，说：“今年宋国有动乱，国家几乎灭亡，三年以后才平定。蔡国有大的丧事。”叔孙昭子说：“这就是戴、桓两族了，他们奢侈、无礼到了极点，动乱会发生在他们那里。”
费无极对楚平王说：“太子建和伍奢将要领着方城山外的人背叛，自以为如同宋国、郑国一样，齐国、晋国又一起辅助他们，将会危害楚国，这事情快成功了。”楚平王相信了这些话，质问伍奢。伍奢回答说：“君王有一次过错已经很严重了，为什么还听信谗言？”楚平王逮捕了伍奢，派城父司马奋扬去杀太子。奋扬没有到达，派人通知太子逃走。三月，太子建逃亡到宋国。楚平王召回奋扬，奋扬让城父大夫逮捕自己回到郢都。楚平王说：“话从我的嘴里说出去，进到你的耳朵里，是谁告诉建的？”奋扬回答说：“是下臣告诉他的。君王命令我说：‘事奉建要像事奉我一样。’下臣不才，不能或有二心。奉了起初的命令去对待太子，就不忍心执行您后来的命令。所以要他逃走了。不久我后悔，也来不及了。”楚平王说：“你敢回来，为什么？”奋扬回答说：“被派遣而没有完成使命，召见我又不回来，这是再次违背命令，逃走也没有地方可去。”楚平王说：“回城父去吧！”奋扬还像过去一样做官。
费无极说：“伍奢的儿子有才能，如果在吴国，一定要使楚国担忧，何不用赦免他们父亲的办法召回他们。他们仁爱，一定回来。不这样，将要成为祸患。”楚平王派人召回他们，说：“回来，我赦免你们的父亲。”棠邑大夫伍尚对他的兄弟员说：“你去到吴国，我准备回去死。我的才智不如你，我能够死，你能够报仇。听到赦免父亲的命令，不能不奔走回去。亲人被杀戮，不能不报仇。奔走回去使父亲赦免，这是孝。估计功效而后行动，这是选择任务而前去，这是智。明知要死而不躲避，这是勇。父亲不能丢掉，名誉不能废弃，你还是努力吧！各人不必勉强为好。”伍尚回去。伍奢听说伍员不来，说：“楚国的国君、大夫恐怕不能准时吃饭了。”楚国人把他们都杀了。
伍员去到吴国，向州于说明进攻楚国的利益。公子光说：“是这个家族被杀戮而想要报私仇，不能听他的。”伍员说：“他将要有别的志向，我姑且为他寻求勇士，而在郊外等着他。”于是就推荐了鱄设诸，自己在边境上种地。
宋元公不讲信用、私心很多，而讨厌华氏、向氏。华定、华亥和向宁策划说：“逃亡比死强，先下手吗？”华亥假装有病，以引诱公子们。凡是公子去探病，就扣押起来。夏季，六月初九，杀死公子寅、公子御戎、公子朱、公子固、公孙援、公孙丁，把向胜、向行囚禁在谷仓里。宋元公到华亥氏那里去请求，华氏不答应，反而要乘机劫持元公。十六日，将太子栾和他的同母兄弟辰、公子地作为人质。元公也取得了华亥的儿子无慼，向宁的儿子罗、华定的儿子启，和华氏结盟，把他们作为人质。
卫国的公孟絷轻慢齐豹，剥夺了他的司寇官职和鄄地。有战事就让他回去，没事就占取过来。公孟絷讨厌北宫喜、褚师圃，想要去掉他们。公子朝和襄夫人宣姜私通，害怕，想乘机发动祸乱。所以齐豹、北宫喜、褚师圃、公子朝发动了叛乱。
当初，齐豹把宗鲁推荐给公孟絷，做了骖乘。齐豹将要发动叛乱，对宗鲁说：“公孟这个人不好，这是您所知道的，不要和他一起乘车，我将要杀死他。”宗鲁回答说：“我由于您而事奉公孟絷，您说我有好名声，所以公孟絷才亲近我。虽然他不好，我也知道，但是由于对自己有利，不能离去，这是我的过错。现在听到祸难而逃走，这是使您的话不可相信了。您办您的事吧！我将为此而死，用保密事奉您，回去死在公孟絷那里，也许是可以的。”
六月二十九日，卫灵公正在平寿，公孟絷在盖获之门外祭祀，齐子氏在门外设置帷帐，在里边埋伏甲士。派祝蛙把戈藏在车上的柴禾里挡着城门，派一辆车跟着公孟絷出来。派华齐驾御公孟的坐车，宗鲁做骖乘。到达曲门中，齐氏用戈敲击公孟，宗鲁用背部遮护他，折断了胳臂，戈击中公孟的肩膀。齐氏把他们一起杀死了。
卫灵公听到动乱的消息，坐上车子，驱车从阅门进入国都。庆比驾车，公南楚做骖乘。派华寅乘坐副车。到达灵公的宫室，鸿駵魋又坐上卫灵公的车子。灵公装载了宝物而出来，褚师子申在马路的十字路口遇到灵公，就跟上去。经过齐氏那里，让华寅光着上身，拿着车盖遮蔽空处。齐氏用箭射卫灵公，射中公南楚的脊背，卫灵公就逃出国都。华寅关闭城门，跳出城墙跟随卫侯。卫灵公去到死鸟。析朱鉏夜里从城墙的排水沟里逃出，徒步跟随卫灵公。
齐景公派公孙青到卫国聘问。已经走出国境，听说卫国发生了动乱，派人请示关于聘问的事情。齐景公说：“卫侯还在国境之内，就还是卫国的国君。”于是就奉命行事，跟着到了死鸟。公孙青请求按照命令行聘礼。卫灵公辞谢说：“逃亡的人没有才能，失守了国家，流亡在杂草丛中，没有地方可以让您执行君王的命令。”客人说：“寡君在朝廷上命令下臣说：‘卑微地亲附执事。’下臣不敢违命。”主人说：“君王如果照顾到先君的友好，光照敝邑，镇定安抚我们的国家，那么有宗庙在那里。”公孙青就停止了聘问。卫灵公坚决请求见他。公孙青不得已，只好用他的好马作为进见的礼物，这是由于没有行聘礼的缘故。卫灵公把公孙青馈送的马作为驾车的马。客人准备在夜里设置警戒，主人辞谢说：“逃亡人的忧虑，不能落到您身上，杂草丛中的人，不足以劳动您。谨敢辞谢。”客人说：“寡君的下臣，就是君王牧牛放马的人。如果得不到在外面警戒的差役，就是心目中没有寡君了。下臣害怕不能免于罪过，请求以此免死。”就亲自拿着大铃，整晚和卫国的夜巡人在一起。
齐氏的家臣头子渠子召则北宫喜。北宫喜的家臣头子不让他知道密谋的事，策划杀死了渠子，并乘机攻打齐氏，消灭了他们。六月三十日，卫灵公进入国都，和北宫喜在彭水盟誓。秋季，七月初一，就和国内的人们盟誓。八月二十五日，公子朝、褚师圃、子玉霄、子高鲂逃亡到晋国。闰八月十二日，杀死宣姜。卫灵公赐给北宫喜的谥号叫贞子，赐给析朱鉏的谥号叫成子，而且把齐氏的墓地给了他们。
卫灵公向齐国报告国内安定，同时述说公孙青的有礼。齐景公将要喝酒，把酒普遍赏赐给大夫们，说：“这是诸位的教导。”苑何忌辞谢不喝，说：“参与了对公孙青的赏赐，必然涉及对他的责罚。在《康诰》上说，‘父子兄弟，罪过互不相干，何况在群臣之间？下臣岂敢贪受君王的赏赐来干犯先王？”
琴张听说宗鲁死了，准备去吊唁。孔子说：“齐豹所以成为坏人，孟絷所以被害，都是由于他的缘故，你为什么要去吊唁呢？君子不吃坏人的俸禄，不接受动乱，不为了利而受到邪恶的侵扰，不用邪恶对待别人，不袒护不义的事情，不做出非礼的事情。”
宋国华氏、向氏的作乱，公子城、公孙忌、乐舍、司马彊、向宜、向郑、楚建郳申逃亡到郑国。他们的党羽和华氏在鬼阎作战，子城被打败。子城去到晋国。
华亥和他的妻子，一定要盥洗干净、伺候作为人质的公子吃完饭以后才吃饭。宋元公和夫人每天一定到华氏那里，让公子吃完以后才回去，华亥担心这种情况，想要让公子回去。向宁说：“正因为元公没有信用，所以把他的儿子作为人质。如果又让他回去，死就很快来到了。”宋元公向华费遂请求，准备攻打华氏。华费遂回答说：“下臣不敢爱惜一死，恐怕是想要去掉忧虑反而滋长忧虑吧！下臣因此害怕，怎敢不听命令？”宋元公说：“孩子们死了是命中注定，我不能忍受他们受耻辱。”冬季，十月，宋元公杀了华氏、向氏的人质而攻打这两家。十三日，华氏、向氏逃亡到陈国，华登逃亡到吴国。向宁想要杀死太子。华亥说：“触犯了国君而出逃，又杀死他的儿子，还有谁接纳我们？而且放他们回去有功劳。”派少司寇牼带着公子们回去，说：“您的年岁大了，不能再事奉别人。用三个公子作为证明，一定可以免罪。”公子们进入国都，华牼将要从公门出去。宋元公急忙接见他，拉着他的手，说：“我知道你没有罪，进来，恢复你的官职。”
齐景公患了两日一发的疟疾，后来又恶化成每天发一次，一年没有痊愈。诸侯派来问候的客人，大多在齐国。梁丘据和裔款对齐景公说：“我们事奉鬼神很丰厚，比先君已经有所增加了。现在君王病得很厉害，成为诸侯的忧虑，这是祝、史的罪过。诸侯不了解，恐怕要认为我们不敬鬼神，君王何不诛戮祝固、史嚚以辞谢客人？”齐景公很高兴，告诉晏子。晏子说：“从前在宋国的盟会，屈建向赵武询问范会的德行。赵武说：‘他老人家家族中的事务井然有序，在晋国说话，竭尽自己的心意而没有个人打算。他的祝、史祭祀，向鬼神陈说实际情况不内愧。他的家族中没有可猜疑的事情，所以他的祝、史也不向鬼神祈求。’屈建把这些话告诉康王。康王说：‘神和人都没有怨恨，他老人家所以能够辅助五位国君而作为诸侯的主人就是很相宜的了。’”齐景公说：“据和款认为寡人能够事奉鬼神，所以要诛戮祝、史，您提出这些话，是什么缘故？”晏子回答说：“如果是有德行的君主，国家和宫里的事情都没有荒废，上下没有怨恨，举动没有违背礼仪的事，他的祝、史向鬼神陈述实际情况，就没有惭愧的心了。所以鬼神享用祭品，国家受到鬼神所降的福禄，祝、史也有一份。他们所以繁衍有福、健康长寿，由于是诚实的国君的使者，他们的话忠诚信实。他们如果恰好碰上放纵的国君，里外偏颇邪恶，上下怨恨嫉妒，举动邪僻背理，放纵欲望满足私心，高台深池，奏乐歌舞，砍伐民力，掠夺百姓的积蓄，以这些行为铸成过错，而不体恤后代，暴虐放纵，随意行动没有法度，无所顾忌，不考虑怨谤，不害怕鬼神。天怒人怨，在心里还不肯改悔。他的祝、史陈说实际情况，这是报告国君的罪过。他们掩盖过错、专谈好事，这是虚诈欺骗，真假都不能陈述，只好陈述不相干的空话来向鬼神讨好，所以鬼神不享用他们国家的祭品，还让它发生祸难，祝、史也有一份。他们所以夭折患病，由于是暴虐的国君的使者，他们的话对鬼神欺诈轻侮。”齐景公说：“那末怎么办？”晏子回答说：“没法办了。山林中的树木，由守山林的人看守它。洼地里的芦苇，舟鲛看守它。草野中的柴禾，虞侯看守它。大海中的盐蛤，祈望看守它。偏僻地方的人，进来管理政事。邻近国都的关卡，横征暴敛，世袭的大夫，强买货物。发布政令没有准则，征收赋税没有节制，宫室每天轮换着住，荒淫作乐不肯离开。宫内的宠妾，在市场上肆意掠夺，外边的宠臣，在边境上假传圣旨。奉养自己、追求玩好这些私欲，下边不能满足就立即治罪。百姓痛苦困乏，丈夫妻子都在诅咒。祝祷有好处，诅咒也有害处。聊地、摄地以东，姑水、尤水以西，人口多得很呢。虽然祝史善于祝祷，难道能胜过亿兆人的诅咒？君王如果要诛戮祝，史，只有修养德行然后才可以。”齐景公很高兴，让官吏放宽政令，毁掉关卡，废除禁令，减轻赋税，免除对官府所欠的债务。
十二月，齐景公在沛地打猎，用弓招唤虞人，虞人没有来。齐景公派人扣押了他，虞人辩解说：“从前我们先君打猎的时候，用红旗招唤大夫，用弓招唤士，用皮冠招唤虞人。下臣没有见到皮冠，所以不敢进见。”齐景公于是就释放了虞人。孔子说：“遵守道义，不如遵守官制。”君子认为说得对。
齐景公从打猎的地方回来，晏子在遄台侍候，梁丘据驱车来到。齐景公说：“惟有据与我和谐啊！”晏子回答说：“据也只不过相同而已，哪里说得上和谐？”齐景公说：“和谐跟相同不一样吗？”晏子回答说：“不一样。和协好像做羹汤，用水、火、醋、酱、盐、梅来烹调鱼和肉，用柴禾烧煮，厨工加以调和，使味道适中，味道太淡就增加调料，味道太浓就加水冲淡。君子喝汤，内心平静。君臣之间也是这样。国君所认为行而其中有不行的，臣下指出它的不行的而使行的部分更加完备。国君所认为不行而其中有行的，臣下指出它的行的部分而去掉它的不行，因此政事平和而不肯违背礼仪，百姓没有争夺之心。所以《诗》说：‘有着调和的羹汤，已经告诫厨工把味道调得匀净。神灵来享而无所指责，上下也都没有争竞。’先王调匀五味、谐和五声，是用来平静他的内心，完成政事的。声音也像味道一样，是由一气、二体、三类、四物、五声、六律、七音、八风、九歌互相组成的。是由清浊、大小、短长、缓急、哀乐、刚柔、快慢、高低、出入、疏密互相调节的。君子听了，内心平静。内心平静，德行就和协。所以《诗》说‘德音没有缺失’。现在据不是这样。国君认为行的，据也认为行。国君认为不行的，据也认为不行。如同用清水去调剂清水，谁能吃它呢？如同琴瑟老弹一个音调，谁去听它呢？不应该相同的道理就像这样。”
喝酒喝得很高兴。齐景公说：“从古以来如果没有死，它的欢乐会怎么样啊！”晏子回答说：“从古以来如果没有死，现在的欢乐就是古代人的欢乐了，君王能得到什么呢？从前爽鸠氏开始居住在这里，季萴沿袭下来，有逢伯陵沿袭下来，蒲姑氏因袭下来，然后太公沿袭下来。从古以来如果没有死，那是爽鸠氏的欢乐，并不是君王所希望的啊。”
郑国的子产有病，对子太叔说：“我死以后，您必定执政。只有有德行的人能够用宽大来使百姓服从，其次就莫如严厉。火势猛烈，百姓看着就害怕，所以很少有人死于火。水性懦弱，百姓轻视并玩弄它，很多人就死在水中。所以宽大不容易。”子产病了几个月就死去了。子太叔执政，不忍心严厉却奉行宽大政策。郑国盗贼很多，聚集在芦苇塘里。太叔后悔，说：“我早点听从他老人家的话，就不至于到这一步。”发动徒兵攻打藏在芦苇丛生的湖泽里的盗贼，全部杀死他们，盗贼稍稍收敛了一些。
孔子说：“好啊！政事宽大百姓就怠慢，怠慢就用严厉来纠正。严厉百姓就受到伤害，伤害就实施宽大。用宽大调节严厉，用严厉调节宽大，因此政事调和。《诗》说，‘百姓已经很辛劳，差不多可以稍稍安康。赐恩给中原各国，用以安定四方’，这是实施宽大。‘不要放纵随声附和的人，以约束不良之人。应当制止侵夺残暴的人，他们从来不怕法度’，这是用严厉来纠正。‘安抚边远，柔服近邦，用来安定我国王’，这是用和平来安定国家。又说，‘不争强不急躁，不刚猛不柔弱。施政平和宽裕，各种福禄都聚集’，这是和谐的顶点。”
等到子产死去，孔子听到这消息，流着眼泪，说：“他的仁爱，是古人流传下来的遗风啊。”', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf4e7d0ac1145495f5f3", "shortContent": "本篇所载之事见于《左传·昭公二十七年》，文字几乎完全相同，《晏子春秋·内篇谏上》也有记载，情节略有出入，可见本篇所记乃是一件史实。吴则虞在分析《晏子春秋》原始素材的来源时，将其分为两类：一类是古书里的零星记载，一类是民间流传的故事，即司马迁《史记·管晏列传》所说的“轶事”（《晏子春秋集释》），本篇即是出于“古书”之记载者。唯其可信，则更能见出晏子之神采风貌来。当然，此事在流传过程中也有所增饰与润色...", "authors": ["马世年"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b69d1e49f46528a4328e9", "shortContent": "《左传》所记鲁昭公二十年（前522年）的历史事件相当纷繁复杂，重要的有楚平王逐太子建，杀伍奢及其子伍尚，次子伍子胥奔吴，宋卫两国内乱；晏婴劝阻齐景公杀主管祭祀、占卜的祝、史，以及论述和的观念；郑国执政子产和孔子主张治国兼用宽猛，子产的去世和孔子对他的评价。这些事件大都不相干，但通过作者对史料的处理、安排，人们仍然能够从中看到它们之间的内在联系。《左传》这些记述描绘了春秋后期诸侯国内惊心动魄的政治斗...", "authors": ["邱轶皓", "魏自厚"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559127056, '5cedf38ca673f500682d9954', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643070, '左传 · 昭公 · 昭公二十一年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有一年春王三月，葬蔡平公。夏，晋侯使士鞅来聘。宋华亥、向宁、华定自陈入于宋南里以叛。秋七月壬午朔，日有食之。八月乙亥，叔辄卒。冬，蔡侯朱出奔楚。公如晋，至河乃复。
【传】二十一年春，天王将铸无射。泠州鸠曰：「王其以心疾死乎？夫乐，天子之职也。夫音，乐之舆也。而钟，音之器也。天子省风以作乐，器以钟之，舆以行之。小者不窕，大者不□瓠，则和于物，物和则嘉成。故和声入于耳而藏于心，心亿则乐。窕则不咸，总则不容，心是以感，感实生疾。今钟□瓠矣，王心弗堪，其能久乎？」
三月，葬蔡平公。蔡大子朱失位，位在卑。大夫送葬者归，见昭子。昭子问蔡故，以告。昭子叹曰：「蔡其亡乎！若不亡，是君也必不终。《诗》曰：『不解于位，民之攸塈。』今蔡侯始即位，而适卑，身将从之。」
夏，晋士鞅来聘，叔孙为政。季孙欲恶诸晋，使有司以齐鲍国归费之礼为士鞅。士鞅怒，曰：「鲍国之位下，其国小，而使鞅从其牢礼，是卑敝邑也。将复诸寡君。」鲁人恐，加四牢焉，为十一牢。
宋华费遂生华貙、华多僚、华登。貙为少司马，多僚为御士，与貙相恶，乃谮诸公曰：「貙将纳亡人。」亟言之。公曰：「司马以吾故，亡其良子。死亡有命，吾不可以再亡之。」对曰：「君若爱司马，则如亡。死如可逃，何远之有？」公惧，使侍人召司马之侍人宜僚，饮之酒而使告司马。司马叹曰：「必多僚也。吾有谗子而弗能杀，吾又不死，抑君有命，可若何？」乃与公谋逐华貙，将使田孟诸而遣之。公饮之酒，厚酬之，赐及从者。司马亦如之。张丐尤之，曰：「必有故。」使子皮承宜僚以剑而讯之。宜僚尽以告。张丐欲杀多僚，子皮曰：「司马老矣，登之谓甚，吾又重之，不如亡也。」五月丙申，子皮将见司马而行，则遇多僚御司马而朝。张丐不胜其怒，遂与子皮、臼任、郑翩杀多僚，劫司马以叛，而召亡人。壬寅，华、向入。乐大心、丰愆、华牼御诸横。华氏居卢门，以南里叛。六月庚午，宋城旧鄘及桑林之门而守之。
秋七月壬午朔，日有食之。公问于梓慎曰：「是何物也，祸福何为？」对曰：「二至、二分，日有食之，不为灾。日月之行也，分，同道也；至，相过也。其他月则为灾，阳不克也，故常为水。」
于是叔辄哭日食。昭子曰：「子叔将死，非所哭也。」八月，叔辄卒。
冬十月，华登以吴师救华氏。齐乌枝鸣戍宋。厨人濮曰：「《军志》有之：『先人有夺人之心，后人有待其衰。』盍及其劳且未定也伐诸？若入而固，则华氏众矣，悔无及也。」从之。丙寅，齐师、宋师败吴师于鸿口，获其二帅公子苦雂、偃州员。华登帅其馀以败宋师。公欲出，厨人濮曰：「吾小人，可藉死而不能送亡，君请待之。」乃徇曰：「杨徽者，公徒也。」众从之。公自杨门见之，下而巡之，曰：「国亡君死，二三子之耻也，岂专孤之罪也？」齐乌枝鸣曰：「用少莫如齐致死，齐致死莫如去备。彼多兵矣，请皆用剑。」从之。华氏北，复即之。厨人濮以裳裹首而荷以走，曰：「得华登矣！」遂败华氏于新里。翟偻新居于新里，既战，说甲于公而归。华妵居于公里，亦如之。
十一月癸未，公子城以晋师至。曹翰胡会晋荀吴、齐苑何忌、卫公子朝救宋。丙戌，与华氏战于赭丘。郑翩愿为鹳，其御愿为鹅。子禄御公子城，庄堇为右。干犨御吕封人华豹，张丐为右。相遇，城还。华豹曰：「城也！」城怒而反之，将注，豹则关矣。曰：「平公之灵，尚辅相余。」豹射，出其间。将注，则又关矣。曰：「不狎，鄙！」押矢。城射之，殪。张丐抽殳而下，射之，折股。扶伏而击之，折轸。又射之，死。干丐请一矢，城曰：「余言汝于君。」对曰：「不死伍乘，军之大刑也。干刑而从子，君焉用之？子速诸。」乃射之，殪。大败华氏，围诸南里。华亥搏膺而呼，见华貙，曰：「吾为栾氏矣。」貙曰：「子无我迋。不幸而后亡。」使华登如楚乞师。华貙以车十五乘，徒七十人，犯师而出，食于睢上，哭而送之，乃复入。楚薳越帅师将逆华氏。大宰犯谏曰：「诸侯唯宋事其君，今又争国，释君而臣是助，无乃不可乎？」王曰：「而告我也后，既许之矣。」
蔡侯朱出奔楚。费无极取货于东国，而谓蔡人曰：「朱不用命于楚，君王将立东国。若不先从王欲，楚必围蔡。」蔡人惧，出朱而立东国。朱诉于楚，楚子将讨蔡。无极曰：「平侯与楚有盟，故封。其子有二心，故废之。灵王杀隐大子，其子与君同恶，德君必甚。又使立之，不亦可乎？且废置在君，蔡无他矣。」公如晋，及河，鼓叛晋。晋将伐鲜虞，故辞公。', '', '', '二十一年春季，周景王准备铸造无射大钟。泠州鸠说：“天子大概会由于心病而死去吧！音乐，是天子所主持的。声音，是音乐的车床，而钟，是发音的器物。天子考察风俗因而制作乐曲，用乐器来汇聚它，用声音来表达它，小的乐器发音不纤细，大的乐器发音不洪亮，那样就使一切事物和谐。一切事物和谐，美好的音乐才能完成。所以和谐的声音进入耳朵而藏在心里，心安就快乐。纤细就不能让四处都听到，洪亮就不能忍受，内心因此感到不安，不安就会生病。现在钟声粗大，天子的内心受不住，难道能够长久吗？”
三月，安葬蔡平公。蔡国的太子朱没有站在葬礼中应站的位置上，站在下面。大夫中送葬的回来，进见昭子。昭子问蔡国葬礼的事情，送葬的大夫就把当时的情况告诉昭子，昭子叹气说：“蔡国大约要灭亡了吧！如果不灭亡，这个国君一定不得好死。《诗》说：‘在他的地位上不懈怠，百姓就能够休息。’现在蔡侯刚刚即位就站到下面去，他自己也将会跟着跨下去的。”
夏季，晋国的士鞅前来聘问，叔孙主持接待。季孙存心得罪晋国，让官吏用齐国的鲍国回费地的礼节招待士鞅。士鞅发怒，说：“鲍国的地位低，他的国家小，现在让我接受招待他所用七牢的礼节，这是轻视敝邑，我将要向寡君报告。”鲁国人恐惧，增加四牢，使用了十一牢。
宋国的华费遂生了华貙、华多僚、华登。华貙做少司马，华多僚做御士，与华貙不和，就在宋公面前诬陷说：“华貙打算接纳逃亡的人。”屡次说这些话，宋元公说：“司马由于我的缘故，使他的儿子逃亡。死和逃亡都是命中注定，我不能让他的儿子再逃亡。”华多僚回答说：“君王如果爱惜司马，就应当逃亡。死如果可以逃避，哪有什么远不远？”宋元公害怕，让侍者召来司马的侍者宜僚，给他酒喝，让他告诉司马驱逐华貙。司马叹气说：“一定是多僚干的。我有一个造谣的儿子而不能杀死他，我又不死，国君有了命令，怎么办？”就和宋元公商量驱逐华貙，准备让他在孟诸打猎时打发他走。宋元公给他酒喝，厚厚地送给他礼物，还赏赐随行的人。司马也像宋元公一样，张匄感到奇怪，说：“一定有原因。”让华貙用剑架在宜僚脖子上追问他，宜僚把话全说出来，张匄想要杀死多僚，华貙说：“司马年老了，华登的逃亡已经很伤他的心，我又加重了他的伤心，不如逃亡。”五月十四日，华貙准备进见司马以后再走。在朝廷上遇见多僚为司马驾车上朝，张牼不能控制自己的愤怒，就和华貙、臼任、郑翩杀了多僚，劫持了司马叛变，召集逃亡的人。二十日，华氏、向氏回来，乐大心。丰愆、华貙在横地抵御他们。华氏住在卢门，领着南里的人叛变。六月十九日，宋国修缮旧城和桑林之门用以据守。
秋季，七月初一，发生日食。鲁昭公问梓慎说：“这是什么事？是什么样的祸福？”梓慎回答说：“冬至夏至、春分秋分，发生日食，不是灾祸。日月的运行，在春分秋分的时候，黄道和赤道交点相同；在夏至冬至的时候，相交点远。其他的月分就要发生灾祸，因为阳气不胜，所以常常发生水灾。”在那个时候叔辄因为发生日食号哭，昭子说：“叔辄快死了，因为这不是他所应该哭的事情。”八月，叔辄死了。
冬季，十月，华登率领吴军救援华氏，齐国的乌枝鸣在宋国戍守，厨邑大夫濮说：“《军志》有这样的话：‘先发制人可以摧毁敌人士气，后发制人要等到敌人士气衰竭。’何不乘他们疲劳和没有安定而进攻？如果敌人已经进来而军心安定，华氏的人就多了，我们就后悔不及了。”乌枝鸣听从了。十七日，齐军、宋军在鸿口击败吴军，俘虏了他们两个将领公子苦雂、偃州员。华登率领余部击败宋军。宋元公想要逃亡，厨邑大夫濮说：“我是小人，可以为君王死难，而不能护送君王逃亡，请君王等待一下。”于是就巡行全军说：“挥舞旗帜的，是国君的战士。”众人按他的话挥舞旗帜，宋元公在扬门上见到这种情况，下城巡视，说：“国家亡，国君死，这是各位的耻辱，岂独是我一人的罪过呢？”齐国的乌枝鸣说：“使用少量的兵力，最好是一起拼命，一起拼命，最好是撤去守备。他们的武器多得很，建议我军都用剑和他们作战。”宋公听从了。华氏败走，宋军、齐军又追上去，厨邑大夫濮用裙子包着砍下的脑袋，扛在肩上快跑，说：“杀死华登了！”于是就在新里打败了华氏，翟偻新住在新里，战斗开始以后，到宋元公那里脱下盔甲而归附。华妵住在公里，也像翟偻新一样。
十一月初四日，公子城带着晋军来到，曹国翰胡会合晋国荀吴、齐国苑何忌、卫国公子朝救援宋国，初七日，和华氏在赭丘作战，郑翩希望摆成鹳阵，他的御者希望摆成鹅阵，子禄为公子城驾御战车，庄堇作为车右，干犫为吕地封人华豹驾御战车，张匄作为车右。两车相遇，公子城退了回去，华豹大喊说：“城啊！”公子城发怒，转回来，将要装上箭，而华豹已经拉开了弓。公子城说：“平公的威灵，还在保佑我！”华豹射箭，穿过公子城和子禄之间，公子城又要装上箭，华豹又已经拉开了弓，公子城说：“不让我还手，卑鄙啊！”华豹从弓上抽下箭，公子城一箭射去，把华豹射死，张匄抽出殳下车，公子城一箭射去，射断张匄的腿，张匄爬过来用殳敲断了公子城的车轸，公子城又发了一箭，张匄死去，干犫请求给他一箭，公子城说：“我替你向国君说情。”干犫回答说：“不和战友一起战死，这是犯了军队中的大法，犯了法而跟从您，君王哪里用得着我？您快点吧！”于是公子城就射了他一箭，射死了，宋军、齐军把华氏打得大败，包围南里，华亥拍着胸脯大喊，进见华貙，说：“我们成了晋国的栾氏了。”华貙说：“您不要吓唬我，碰上倒霉才会死呢。”派华登到楚国请求出兵，华貙带领战车十五辆，步兵七十人突围而出，在睢水岸边吃饭，哭着送走华登，就再次冲进包围圈。楚国的薳越率领军队打算迎接华氏，太宰犯劝谏说：“诸侯之中惟有宋国的臣下还事奉着国君，现在又争夺国政，丢开国君而帮助臣下，恐怕不可以吧！”楚平王说：“我对你说晚了，已经答应他们了。”
蔡侯朱逃亡到楚国。费无极得到东国的财礼，对蔡国人说：“朱不听楚国的命令，君王将要立东国做国君，如果不先顺从君王的愿望，楚国一定包围蔡国。”蔡国人害怕，赶走朱而立了东国，朱向楚国控诉，楚平王准备讨伐蔡国。费无极说：“蔡平侯和楚国有盟约，所以封他，他的儿子有二心，所以废掉他。灵王杀了隐太子，隐太子的儿子和君王有共同的仇人，一定会感谢君王。现在又让他立为国君，不也是可以的吗？而且废、立的权操在君王手里，蔡国就不会有别的念头了。”
昭公去到晋国，到达黄河。鼓地背叛晋国，晋国准备进攻鲜虞，所以辞谢了昭公。', '[{"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42bcc6e67846a9227c38", "shortContent": "这篇故事中的男主角唐子畏，就是明代有名的风流才子唐寅。唐寅（1470—1523），字伯虎，一字子畏，号六如居士，吴县（今江苏苏州）人。他自称“江南第一风流才子”，是明代著名的画家和文学家，生前才华横溢，风流倜傥，身后留下了很多的逸闻趣事，这篇故事即是其中之一。故事写唐寅对华学士家的一个漂亮丫鬟一见钟情，紧追不舍，甚至不惜改名换姓，屈身为仆，终于携丫鬟逃离华府，并结为夫妇。充分表现出唐寅不拘礼法、风...", "authors": ["魏崇新"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559127112, '5cedf3c4c8959c0069f50f50', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643071, '左传 · 昭公 · 昭公二十二年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有二年春，齐侯伐莒。宋华亥、向宁、华定自宋南里出奔楚。大蒐于昌间。夏四月乙丑，天王崩。六月，叔鞅如京师，葬景王，王室乱。刘子、单子以王猛居于皇。秋，刘子、单子以王猛入于王城。冬十月，王子猛卒。十有二月癸酉朔，日有食之。
【传】二十二年春，王二月甲子，齐北郭启帅师伐莒。莒子将战，苑羊牧之谏曰：「齐帅贱，其求不多，不如下之。大国不可怒也。」弗听，败齐师于寿余。齐侯伐莒，莒子行成。司马灶如莒莅盟，莒子如齐莅盟，盟子稷门之外。莒于是乎大恶其君。
楚薳越使告于宋曰：「寡君闻君有不令之臣为君忧，无宁以为宗羞？寡君请受而戮之。」对曰：「孤不佞，不能媚于父兄，以为君忧，拜命之辱。抑君臣日战，君曰『余必臣是助』，亦唯命。人有言曰：『唯乱门之无过』。君若惠保敝邑，无亢不衷，以奖乱人，孤之望也。唯君图之！」楚人患之。诸侯之戍谋曰：「若华氏知困而致死，楚耻无功而疾战，非吾利也。不如出之，以为楚功，其亦能无为也已。救宋而除其害，又何求？」乃固请出之。宋人从之。己巳，宋华亥、向宁、华定、华貙、华登、皇奄伤、省臧，士平出奔楚。宋公使公孙忌为大司马，边卬为大司徒，乐祁为司马，仲几为左师，乐大心为右师，乐挽为大司寇，以靖国人。
王子朝、宾起有宠于景王，王与宾孟说之，欲立之。刘献公之庶子伯蚡事单穆公，恶宾孟之为人也，愿杀之。又恶王子朝之言，以为乱，愿去之。宾孟适郊，见雄鸡自断其尾。问之，侍者曰：「自惮其牺也。」遽归告王，且曰：「鸡其惮为人用乎？人异于是。牺者，实用人，人牺实难，己牺何害？」王弗应。
夏四月，王田北山，使公卿皆从，将杀单子、刘子。王有心疾，乙丑，崩于荣錡氏。戊辰，刘子挚卒，无子，单子立刘。五月庚辰，见王，遂攻宾起，杀之，盟群王子于单氏。
晋之取鼓也，既献，而反鼓子焉，又叛于鲜虞。
六月，荀吴略东阳，使师伪籴负甲以息于昔阳之门外，遂袭鼓，灭之。以鼓子鸢鞮归，使涉佗守之。
丁巳，葬景王。王子朝因旧官、百工之丧职秩者，与灵、景之族以作乱。帅郊、要、饯之甲，以逐刘子。壬戌、刘子奔扬。单子逆悼王于庄宫以归。王子还夜取王以如庄宫。癸亥，单子出。王子还与召庄公谋，曰：「不杀单旗，不捷。与之重盟，必来。背盟而克者多矣。」从之。樊顷子曰：「非言也，必不克。」遂奉王以追单子。及领，大盟而复，杀挚荒以说。刘子如刘，单子亡。乙丑，奔于平畤，群王子追之。单子杀还、姑、发、弱、鬷延、定、稠，子朝奔京。丙寅，伐之，京人奔山。刘子入于王城。辛未，巩简公败绩于京。乙亥，甘平公亦败焉。叔鞅至自京师，言王室之乱也。闵马父曰：「子朝必不克，其所与者，天所废也。」单子欲告急于晋，秋七月戊寅，以王如平畤，遂如圃车，次于皇。刘子如刘。单子使王子处守于王城，盟百工于平宫。辛卯，鄩肸伐皇，大败，获鄩肸。壬辰，焚诸王城之市。八月辛酉，司徒丑以王师败绩于前城，百工叛。己巳，伐单氏之宫，败焉。庚午，反伐之。辛未，伐东圉。冬十月丁巳，晋籍谈、荀跞帅九州之戎及焦、瑕、温、原之师，以纳王于王城。庚申，单子、刘蚡以王师败绩于郊，前城人败陆浑于社。十一月乙酉，王子猛卒，不成丧也。已丑，敬王即位，馆于子族氏。
十二月庚戌，晋籍谈、荀跞、贾辛、司马督帅师军于阴，于侯氏，于溪泉，次于社。王师军于泛，于解，次于任人。闰月，晋箕遗、乐征，右行诡济师，取前城，军其东南。王师军于京楚。辛丑，伐京，毁其西南。', '', '', '二十二年春季，周王朝历法的二月十六日，齐国的北郭启领兵进攻莒国。莒子将要迎战，苑羊牧之劝谏说：“齐国的元帅地位低下，他的要求不多，不如向他低头，大国是不能激怒的。”莒子不听，在寿馀打败了齐军。齐景公又亲自领兵进攻莒国，莒子求和。司马灶到莒国参加结盟，莒子到齐国参加结盟，在稷门外边盟誓。莒国人因此而大大地讨厌他们的国君。
楚国的薳越派人告诉宋国说：“寡君听说君王有不好的臣下使君王忧虑，恐怕成为宗庙的羞耻，寡君请求接受下来加以诛戮。”宋元公回答说：“孤没有才能，不能取得父兄的欢心，因此成为君王的忧虑，承蒙君王下达命令。君臣之间每天作战，如果君王说：‘我一定帮助臣下’，也只能唯命是听，人们有话说：‘不要经过动乱人家的门口。”君王如果赐恩保护敝邑，不去保护不忠，以奖励作乱的人，这是孤的愿望，请君王考虑一下。”楚国人担心这件事，诸侯派往宋国戌守的将领商量说：“如果华氏感到没有前途而拼命战斗，楚国由于不见功效而很快出兵作战，这于我们不利，不如让他们出去，以成就楚国的功绩，华氏也不能有所作为了，救援了宋国而除掉了他们的祸害，还有什么要求呢？”于是坚决请求放出华氏，宋国人听从了。二月二十一日，宋国的华亥、向宁、华定、华貙、华登、皇奄伤、省臧、士平逃亡楚国。宋元公派公孙忌做大司马，边卬做大司徒，乐祁做司城，仲几做左师，乐大心做右师，乐輓做大司寇，以便用来安定国内的人们。
王子朝、宾起受到周景王的宠信，景王和宾起喜爱王子朝，要立王子朝为太子。刘献公的庶子伯蚠事奉单穆公，讨厌宾起的为人，愿意杀掉他。又讨厌王子朝的话，认为违背了礼制，愿意除掉他。有一次宾起走到郊外，看到雄鸡自己弄断自己的尾巴。他问为什么，侍者说：“这是它自己害怕作牺牲。”宾起赶快回来报告景王，而且说：“鸡大概是害怕被人利用吧！人就和这不一样，牺牲，是被人使用的，被人利用确实困难，被自己利用还有什么妨碍？”景王不回答。
夏季，四月，景王在北山打猎，让公卿们都跟着，准备杀掉单子、刘子。景王有心脏病，十八日，死在荣锜氏那里。二十二日，刘子挚死了，没有嫡子，单子立了刘蚠。五月初四日，刘蚠进见周悼王，就乘势攻打宾起。杀死了他，和王子们在单氏那里结盟。
晋国占取鼓地的时候，在宗庙里进献战利品以后就让鼓子回国。鼓子回去又背叛晋国归属鲜虞。
六月，荀吴巡视东阳，派军队伪装籴米的人，背着皮甲在昔阳城门外休息，就乘机侵袭鼓国，灭亡了它，带着鼓子鸢鞮回去，派涉佗镇守鼓地。
六月十一日，安葬周景王。王子朝依仗旧官和百工中失去官职的人和灵王、景王的族人而发动叛乱。王子朝率领郊地、要地、饯地的甲士以驱逐刘子。十六日，刘子逃亡到扬地，单子在庄宫迎接悼王回到自己家里，王子还在夜里又把悼王带到庄宫。十七日，单子出奔，王子还和召庄公谋划，说：“不杀死单旗，不能算胜利。和他再次结盟，他必定会来。违背盟约而战胜敌人的事情是很多的。”召庄公听从了他的话。樊顷子说：“这不成话，必然不能战胜敌人。”于是王子还就事奉悼王追赶单子，到达崿岭，大张旗鼓地结盟后一起回去，杀死了挚荒以向单子解释，刘子到刘地去。单子逃亡，十九日，逃亡到平畤。王子们追赶他，单子杀了还、姑、发、弱、鬷、延、定、稠，王子朝逃亡到京地。二十日，单子攻打京地。京地人逃亡到山里，刘子进入王城。二十五日，巩简公在京地大败。二十九日，甘平公也在那里战败。
叔鞅从京师回来，说起王室的动乱，闵马父说：“王子朝必定不能得胜，他所亲附的人，都是上无所废弃的。”单子想要向晋国报告紧急情况。秋季，七月初三日，带着周悼王去到平畤，于是又到了圃车，住在皇地。刘子到刘地去，单子派王子处在王城守卫，和百工在平宫结盟。十六日，鄩肸攻打皇地，大败，被俘。十七日，把鄩肸在王城的市上烧死。八月十六日，司徒丑带领周天子的军队在前城大败，百工叛变。二十四日，攻打单氏的住宅，被打败。二十五日，单氏进攻。二十六日，进攻东圉。冬季，十月十三日，晋国的籍谈、荀跞率领九州的戎人和焦地、瑕地、温地、原地的军队，把周悼王送回王城。十六日，单子、刘蚠率领周天子的军队在郊地作战大败，前城人在社地打败陆浑。十一月十二日，王子猛死。《春秋》不记载“崩”，是由于没有举行天子丧葬礼的缘故。十六日，周敬王即位，住在子旅氏家里。
十二月初七日，晋国的籍谈、荀跞、贾辛、司马督领兵分别驻扎在阴地、侯氏、溪泉和住在社地。周天子的军队驻扎在汜地、解地、任人。闰十二月，晋国的箕遗、乐征、右行诡带领部队渡河占取前城，驻扎在前城的东南，周天子的军队驻扎在京楚。二十九日，攻打京地，破坏了京地的西南部。', NULL, '', 'indent', 1559127158, '5cedf3f330863b0068559499', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643072, '左传 · 昭公 · 昭公二十三年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有三年春王正月，叔孙□若如晋。癸丑，叔鞅卒。晋人执我行人叔孙□若。晋人围郊。夏六月，蔡侯东国卒于楚。秋七月，莒子庚舆来奔。戊辰，吴败顿、胡沈、蔡、陈、许之师于鸡父，胡子髡、沈子逞灭，获陈夏啮。天王居于狄泉。尹氏立王子朝。八月乙未，地震。冬，公如晋，至河，有疾，乃复。
【传】二十三年春，王正月壬寅朔，二师围郊。癸卯，郊、鄩溃。丁未，晋师在平阴，王师在泽邑。王使告间，庚戌，还。
邾人城翼，还，将自离姑。公孙锄曰：「鲁将御我。」欲自武城还，循山而南。徐锄、丘弱、茅地曰：「道下，遇雨，将不出，是不归也。」遂自离姑。武城人塞其前，断其后之木而弗殊。邾师过之，乃推而蹶之。遂取邾师，获锄、弱、地。
邾人诉于晋，晋人来讨。叔孙蹶如晋，晋人执之。书曰：「晋人执我行人叔孙□若。」言使人也。晋人使与邾大夫坐。叔孙曰：「列国之卿，当小国之君，固周制也。邾又夷也。寡君之命介子服回在，请使当之，不敢废周制故也。」乃不果坐。
韩宣子使邾人取其众，将以叔孙与之。叔孙闻之，去众与兵而朝。士弥牟谓韩宣子曰：「子弗良图，而以叔孙与其仇，叔孙必死之。鲁亡叔孙，必亡邾。邾君亡国，将焉归？子虽悔之，何及？所谓盟主，讨违命也。若皆相执，焉用盟主？」乃弗与，使各居一馆。士伯听其辞而诉诸宣子，乃皆执之。士伯御叔孙，从者四人，过邾馆以如吏。先归邾子。士伯曰：「以刍荛之难，从者之病，将馆子于都。」叔孙旦而立，期焉。乃馆诸箕。舍子服昭伯于他邑。
范献子求货于叔孙，使请冠焉。取其冠法，而与之两冠，曰：「尽矣。」为叔孙故，申丰以货如晋。叔孙曰：「见我，吾告女所行货。」见，而不出。吏人之与叔孙居于箕者，请其吠狗，弗与。及将归，杀而与之食之。叔孙所馆者，虽一日必葺其墙屋，去之如始至。
夏四月乙酉，单子取訾，刘子取墙人、直人。六月壬午，王子朝入于尹。癸未，尹圉诱刘佗杀之。丙戌，单子从阪道，刘子从尹道伐尹。单子先至而败，刘子还。己丑，召伯奂、南宫极以成周人戍尹。庚寅，单子、刘子、樊齐以王如刘。甲午，王子朝入于王城，次于左巷。秋七月戊申，鄩罗纳诸庄宫。尹辛败刘师于唐。丙辰，又败诸鄩。甲子，尹辛取西闱。丙寅，攻蒯，蒯溃。
莒子庚舆虐而好剑，苟铸剑，必试诸人。国人患之。又将叛齐。乌存帅国人以逐之。庚舆将出，闻乌存执殳而立于道左，惧将止死。苑羊牧之曰：「君过之！乌存以力闻可矣，何必以弑君成名？」遂来奔。齐人纳郊公。
吴人伐州来，楚薳越帅师及诸侯之师奔命救州来。吴人御诸钟离。子瑕卒，楚师熸薳。吴公子光曰：「诸侯从于楚者众，而皆小国也。畏楚而不获己，是以来。吾闻之曰：『作事威克其爱，虽小必济』。胡、沈之君幼而狂，陈大夫啮壮而顽，顿与许、蔡疾楚政。楚令尹死，其师熸。帅贱、多宠，政令不壹。而七国同役不同心，帅贱而不能整，无大威命，楚可败也，若分师先以犯胡、沈与陈，必先奔。三国败，诸侯之师乃摇心矣。诸侯乖乱，楚必大奔。请先者去备薄威，后者敦陈整旅。」吴子从之。戊辰晦，战于鸡父。吴子以罪人三千，先犯胡、沈与陈，三国争之。吴为三军以击于后，中军从王，光帅右，掩余帅左。吴之罪人或奔或止，三国乱。吴师击之，三国败，获胡、沈之君及陈大夫。舍胡、沈之囚，使奔许与蔡、顿，曰：「吾君死矣！」师噪而从之，三国奔，楚师大奔。书曰：「胡子髡、沈子逞灭，获陈夏啮。」君臣之辞也。不言战，楚未陈也。
八月丁酉，南宫极震。苌弘谓刘文公曰：「君其勉之！先君之力可济也。周之亡也，其三川震。今西王之大臣亦震，天弃之矣！东王必大克。」
楚大子建之母在狊阜，召吴人而启之。冬十月甲申，吴大子诸樊入狊阜，取楚夫人与其宝器以归。楚司马薳越追之，不及。将死，众曰：「请遂伐吴以徼之。」薳越曰：「再败君师，死且有罪。亡君夫人，不可以莫之死也。」乃缢于薳澨。
公为叔孙故如晋，及河，有疾而复。
楚囊瓦为令尹，城郢。沈尹戌曰：「子常必亡郢！苟不能卫，城无益也。古者，天子守在四夷；天子卑，守在诸侯。诸侯守在四邻；诸侯卑，守在四竟。慎其四竟，结其四援，民狎其野，三务成功，民无内忧，而又无外惧，国焉用城？今吴是惧而城于郢，守己小矣。卑之不获，能无亡乎？昔梁伯沟其公宫而民溃。民弃其上，不亡何待？夫正其疆场，修其土田，险其走集，亲其民人，明其伍候，信其邻国，慎其官守，守其交礼，不僭不贪，不懦不耆，完其守备，以待不虞，又何畏矣？《诗》曰：『无念尔祖，聿修厥德。』无亦监乎若敖、蚡冒至于武、文？土不过同，慎其四竟，犹不城郢。今土数圻，而郢是城，不亦难乎？」', '', '', '二十三年春季，周王朝历法的正月初一，周、晋两国的两支军队包围郊地。初二日，郊地、？地人溃散。初六日，晋国的军队在平阴，周天子的军队在泽邑。周敬王派人向晋军报告情势好转。初九日，晋军回国。
邾人在翼地筑城，回去，准备从离姑那条路上走，公孙鉏说：“鲁国将会抵御我们。”就考虑从武城折回去，沿着山路往南走。徐鉏、丘弱、茅地说：“山道一直往下，碰上雨，将会出不去，这就不能回去了。”于是就取道离姑，武城人出兵挡在前面，又把退路两旁的树木，加以砍伐又不砍断。邾军经过这里以后，武城人推到树木，于是消灭邾军，俘虏了徐鉏、丘弱、茅地。
邾人向晋国控诉，晋国人前来问罪，叔孙婼到晋国去，晋国人就把他扣押了。《春秋》记载说“晋国执我行人叔孙婼”，是说明晋人扣押了使臣。晋人让叔孙婼和邾国的大夫辩论，叔孙婼说：“各国的卿，相当于小国的国君，本来是周朝的制度，小小的邾国还是夷人呢。有寡君所任命的副使子服回在，请让他担任这件事，这是由于不敢废除周朝的制度。”于是就不去辩论。
韩宣子让邾人聚集他们的人，准备把叔孙婼交给他们，叔孙婼听说这件事，撤去随从和武器前去朝见晋君，士弥牟对韩宣子说：“您的主意不好，而把叔孙婼交给他们的仇人，叔孙婼必然为此而死，鲁国丧失了叔孙婼，必然灭亡邾国，邾君亡国，将要回到哪里去？到时您虽然后悔，哪里还来得及呢？所谓盟主，任务是讨伐违背命令的国家，如果互相抓人，哪里还用得着盟主？”于是韩宣子就没有把叔孙婼交给邾国人，让他和子服回各自住在一个宾馆里。士弥牟听了他们的辩解，告诉韩宣子，就把他们都扣押了。士弥牟为叔孙婼驾车，跟从的有四个人，经过邾人的宾馆而到官吏那里去，先让邾子回国，士弥牟说：“由于柴草供应困难，随从人员辛苦，准备让您住在别的城邑里。”叔孙婼一早晨就站着，等候命令。晋国人就让他住在箕地。让子服回住在另外的城邑里。
范献子向叔孙婼求取财货，派人去请求送给他帽子，叔孙婼拿来他帽子的样子，照样送给他两顶，说：“都在这里了。”为了叔孙婼的缘故，申丰带着财货去到晋国，叔孙婼说：“来见我，我告诉你把财货送到哪里去。”申丰进见叔孙婼，就没有出来，和叔孙婼一起住在箕地的看守人请求得到他的吠狗，叔孙婼不给，等到将要回去的时候，杀了这条狗和官吏一起吃了。叔孙婼所住过的地方，尽管只住一天，也一定修缮墙屋，离开的时候好像刚来的时候一样。
夏季，四月十四日，单子攻取了訾地，刘子攻取了墙人、直人。六月十二日，王子朝进入尹地。十三日，尹圉诱骗刘佗把他杀死了。十六日，单子从山道、刘子从大道出兵进攻尹地。单子先抵达而战败，刘子就回去了。十九日，召伯奂、南宫极带着成周的军队在尹地戍守。二十日，单子、刘子、樊齐带了周敬王去到刘地。二十四日，王子朝进入王城，住在左巷。秋季，七月初九日，鄩罗把王子朝送到庄宫，尹辛在唐地击败刘子的军队。十七日，又在鄩地击败刘军。二十五日，尹辛占取西闱。二十七日，进攻蒯地，蒯地人溃散。
莒子庚舆残暴而喜欢剑，如果铸造了剑，必定要用人来试一试，国内的人们都讨厌他。他又准备背叛齐国。乌存率领国内的人们驱逐他。庚舆将要出国，听说乌存拿着殳在路边站着，恐惧会把他留下杀死，苑羊牧之说：“君王过去吧！乌存由于勇力过人而出名就行了，何必用杀死国君来成名？”庚舆就逃亡前来，齐国人把郊公送回莒国即位。
吴人进攻州来，楚国的薳越率领楚国和诸侯的军队奉命奔赴救援州来，吴人在钟高抵御他们，令尹子瑕死，楚军丧失战斗力。吴国的公子光说：“诸侯跟从楚国的很多，而都是小国，害怕楚国而不得已，因此前来。我听说：‘做事情如果威严胜过感情，虽然弱小，必然成功。’胡国、沈国的国君年轻而浮躁，陈国的大夫齧虽然年富力强但是顽固，顿国和许国、蔡国憎恨楚国的政事，楚国的令尹死了，他们的军队失去战斗力，元帅地位低，而很受宠信，政令又不一致，七国同伙而不同心，元帅地位低而不能整齐号令，没有重大的威信，楚国是可以打败的。如果分兵先攻胡国、沈国和陈国的军队，他们必然首先奔逃，三国败退，诸侯的军队的军心就动摇了，诸侯混乱，楚军必然拼命奔逃。请让先头部队放松戒备减少军威，后继部队巩固军阵整顿师旅，以引诱敌人。”吴王听从了他的意见。七月二十九日，在鸡父作战，吴王用三千名罪犯先攻胡国、沈国和陈国，三国军队争着俘虏吴军。吴国整编了三个军紧跟在后，中军跟随吴王，公子光率领右军，公子掩馀率领左军，吴国的罪犯有的奔逃，有的停止，三国的军阵乱了阵脚，吴军进攻，三国的军队败退，俘虏了胡、沈两国的国君和陈国的大夫。吴军释放胡国、沈国的浮虏，让他们奔逃到许国和蔡国、顿国的军队里，说：“我们的国君死了！”吴军擂鼓呐喊跟上去，三国的军队败逃，楚军拼命逃跑。《春秋》记载说“胡子髡、沈子逞灭，获陈夏齧”，这是对国君和臣下所使用的不同文辞，不说交战，这是因为楚国没有摆开阵势。
八月二十七日，南宫极因为地震被压死，苌弘对刘文公说：“君王还是努力吧！先君所致力的事可以成功了，周室灭亡的时候，泾水、渭水、洛水一带发生地震，现在西王的大臣那里也发生地震，这是上天丢弃他了，东王必然大胜。”
楚国太子建的母亲住在郹地，召来吴国人，为他们打开城门。冬季，十月十六日，吴国的太子诸樊进入郹地，带了楚夫人和她的宝器回国了。楚国的司马薳越追赶他，没有追上。准备自杀，众人说：“乘机攻打吴国可能侥幸取胜。”薳越说：“再次让国君的军队打败，死了也还是有罪。丢了君王的夫人，没有谁不能为此而死。”于是薳越就在薳澨上吊死了。
昭公为叔孙的缘故到晋国去，到达黄河，有病而返回来。
楚国的囊瓦做令尹，在郢都增修城墙。沈尹戌说：“子常一定丢掉郢都，如果不能保卫，增修城墙是没有好处的。古代，天子的守卫在于四夷。天子的地位降低，守卫在于诸侯，诸侯的守卫在于四方邻国。诸侯的地位降低，守卫在于四方边境。警惕四方边境，结交四方邻国，百姓在自己土地上安居乐业，春夏秋三时的农事有所收获，百姓没有内忧，又没有外患，国都哪里用得着增修城墙？现在害怕吴国，而在郢都增修城墙，守卫的范围只在四境。地位降低以后的其他守卫都办不到，能够不亡吗？从前梁国国君在公宫旁边挖沟而百姓溃散，百姓抛弃他们上边的人，不亡，还等什么？划定疆界，修治土地，巩固边垒，亲近百姓，加强瞭望，不欺邻国，谨慎官吏的职责，保持交接的礼仪，没有过失，不贪婪，不懦弱，不强霸，修整自己的防御，以防备发生意外，又有什么可害怕呢？《诗》说：‘思念你的祖先，发扬他们的美德。’试看若敖、蚡冒到文王、武王，土地不超过百里见方，警惕四方边境，尚且不在郢都增修城墙。现在土地超过几千里见方，反而在郢都增修城墙，不也是很难了吗？”', NULL, '', 'indent', 1559127206, '5cedf41aba39c800689693c1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643073, '左传 · 昭公 · 昭公二十四年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十四年春王三月丙戌，仲孙玃卒。□若至自晋。夏五月乙未朔，日有食之。秋八月，大雩。丁酉，杞伯郁厘卒。冬，吴灭巢。葬杞平公。
【传】二十四年春，王正月辛丑，召简公、南宫嚚以甘桓公见王子朝。刘子谓苌弘曰：「甘氏又往矣。」对曰：「何害？同德度义。《大誓》曰：『纣有亿兆夷人，亦有离德。余有乱臣十人，同心同德。』此周所以兴也。君其务德，无患无人。」戊午，王子朝入于邬。
晋士弥牟逆叔孙于箕。叔孙使梁其径待于门内，曰：「余左顾而欬，乃杀之。右顾而笑，乃止。」叔孙见士伯，士伯曰：「寡君以为盟主之故，是以久子。不腆敝邑之礼，将致诸从者。使弥牟逆吾子。」叔孙受礼而归。二月，□若至自晋，尊晋也。
三月庚戌，晋侯使士景伯莅问周故，士伯立于乾祭而问于介众。晋人乃辞王子朝，不纳其使。
夏五月乙未朔，日有食之。梓慎曰：「将水。」昭子曰：「旱也。日过分而阳犹不克，克必甚，能无旱乎？阳不克莫，将积聚也。」
六月壬申，王子朝之师攻瑕及杏，皆溃。
郑伯如晋，子大叔相，见范献子。献子曰：「若王室何？」对曰：「老夫其国家不能恤，敢及王室。抑人亦有言曰：『嫠不恤其纬，而忧宗周之陨，为将及焉。』今王室实蠢蠢焉，吾小国惧矣。然大国之忧也，吾侪何知焉？吾子其早图之！《诗》曰：瓶之罄矣，惟罍之耻。』王室之不宁，晋之耻也。」献子惧，而与宣子图之。乃征会于诸侯，期以明年。
秋八月，大雩，旱也。
冬十月癸酉，王子朝用成周之宝珪于河。甲戌，津人得诸河上。阴不佞以温人南侵，拘得玉者，取其玉，将卖之，则为石。王定而献之，与之东訾。
楚子为舟师以略吴疆。沈尹戌曰：「此行也，楚必亡邑。不抚民而劳之，吴不动而速之，吴踵楚，而疆埸无备，邑能无亡乎？」
越大夫胥犴劳王于豫章之汭。越公子仓归王乘舟，仓及寿梦帅师从王，王及圉阳而还。吴人踵楚，而边人不备，遂灭巢及钟离而还。沈尹戌曰：「亡郢之始，于此在矣。王一动而亡二姓之帅，几如是而不及郢？《诗》曰：『谁生厉阶，至今为梗？』其王之谓乎？」
', '', '', '二十四年春季，周王朝历法的正月初五日，召简公、南宫嚚带着甘桓公进见王子朝。刘子对苌弘说：“甘氏又去了。”苌弘回答说：“有什么妨碍？同心同德在于合乎正义。《太誓》说：‘纣有亿兆人，离心离德，我有治世之臣十个人，同心同德。’这就是周朝所以兴起的原因，君王还是致力于德行，不要担心没有人。”二十二日，王子朝进入邬地。
晋国的士弥牟在箕地迎接叔孙，叔孙派梁其踁埋伏在门里边，说：“我向左边看并且咳嗽，就把他杀了。向右边看并且笑笑，就不要动手。”叔孙接见士弥牟，士弥牟说：“寡君由于作为盟主的缘故，因此把您久留在敝邑，不丰厚的敝邑的礼物，将要致送给您的左右随从，派弥牟来迎接您。”叔孙接受礼物回国了。二月，《春秋》记载说“婼至自晋”，这是表示尊重晋国。
三月十五日，晋顷公派士景伯到王城调查周朝发生的事故。士景伯站在乾祭门上，向大众询问，晋国人就辞谢王子朝，不接纳他的使者。
夏季，五月初一日，发生日食。梓慎说：“将要发生水灾。”昭子说：“这是旱灾，太阳过了春分而阳气尚且不胜阴气，一旦胜过阴气，能不发生旱灾吗？阳气迟迟不能战胜阴气，这是正在积聚阳气。”
六月初八日，王子朝的军队进攻瑕地和杏地，两地军队都溃散了。
郑定公到晋国去，子太叔相礼，进见范献子。范献子说：“对王室该怎么办？”子太叔回答说：“我老头子对自己的国家和家族都不能操心了，哪里敢涉及王室的事情？人们有话说：‘寡妇不操心纬线，而忧虑宗周的陨落，因为恐怕祸患也会落到她头上。’现在王室确实动荡不安，我们小国害怕了，然而大国的忧虑，我们哪里知道呢？您还是早作打算。《诗》说：‘酒瓶空空，是酒坛子的耻辱。’王室的不安宁，这是晋国的耻辱。”范献子害怕，和韩宣子谋划。于是就召集诸侯会见，时间定在明年。
秋季，八月，举行盛大的雩祭，这是由于发生了旱灾。
冬季，十月十一日，王子朝使用成周的宝圭沉到黄河里向河神祈祷。十二日，渡船的船工在黄河上得到了这块宝圭。阴不佞带着温地人往南袭击王子朝，拘捕了得到玉的人，把玉拿过来，准备卖掉它，却是一块石头。阴不佞在王室安定以后把它奉献给周敬王，周敬王把东訾赐给他。
楚平王组织水军去侵略吴国的疆土。沈尹戌说：“这一趟，楚国必然丢掉城邑。不安抚百姓而让他们疲惫，吴国没有动静而让他们加速出动，吴军紧紧追逐楚军，然而边境却没有戒备，城邑能够不丢掉吗？”
越国的大夫胥犴在豫章的江边上慰劳楚平王，越国的公子仓把一只船赠送给楚平王。公子仓和寿梦领兵跟随楚平王。楚平王到达圉阳而返回。吴军紧紧追逐楚军，但是边境的守军没有戒备，吴国人就灭掉了巢和钟离而回去。沈尹戌说：“丢掉郢都的开端就在这里，君王一个举动就失去了两个将领，照这样来几次，难道就不会兵临郢都城下？《诗》说：‘是谁制造了祸端，到今天还是灾害’，恐怕说的就是君王吧！”', NULL, '', 'indent', 1559127242, '5cedf446ba39c80068969517', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643074, '左传 · 昭公 · 昭公二十五年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十五年春，叔孙□若如宋。夏，叔诣会晋赵鞅、宋乐大心，卫北宫喜、郑游吉、曹人、邾人、滕人、薛人、小邾人于黄父。有鸲鹆来巢。秋七月上辛，大雩；季辛，又雩。九月己亥，公孙于齐，次于阳州。齐侯唁公于野井。冬十月戊辰，叔孙□若卒。十有一月己亥，宋公佐卒于曲棘。十有二月，齐侯取郓。
【传】二十五年春，叔孙□若聘于宋，桐门右师见之。语，卑宋大夫，而贱司城氏。昭子告其人曰：「右师其亡乎！君子贵其身而后能及人，是以有礼。今夫子卑其大夫而贱其宗，是贱其身也，能有礼乎？无礼必亡。」
宋公享昭子，赋《新宫》。昭子赋《车辖》。明日宴，饮酒，乐，宋公使昭子右坐，语相泣也。乐祁佐，退而告人曰：「今兹君与叔孙，其皆死乎？吾闻之：『哀乐而乐哀，皆丧心也。』心之精爽，是谓魂魄。魂魄去之，何以能久？」
季公若之姊为小邾夫人，生宋元夫人，生子以妻季平子。昭子如宋聘，且逆之。公若从，谓曹氏勿与，鲁将逐之。曹氏告公，公告乐祁。乐祁曰：「与之。如是，鲁君必出。政在季氏三世矣，鲁君丧政四公矣。无民而能逞其志者，未之有也。国君是以镇抚其民。《诗》曰：『人之云亡，心之忧矣。』鲁君失民矣，焉得逞其志？靖以待命犹可，动必忧。」
夏，会于黄父，谋王室也。赵简子令诸侯之大夫输王粟，具戍人，曰：「明年将纳王。」子大叔见赵简子，简子问揖让周旋之礼焉。对曰：「是仪也，非礼也。」简子曰：「敢问何谓礼？」对曰：「吉也闻诸先大夫子产曰：『夫礼，天之经也。地之义也，民之行也。』天地之经，而民实则之。则天之明，因地之性，生其六气，用其五行。气为五味，发为五色，章为五声，淫则昏乱，民失其性。是故为礼以奉之：为六畜、五牲、三牺，以奉五味；为九文、六采、五章，以奉五色；为九歌、八风、七音、六律，以奉五声；为君臣、上下，以则地义；为夫妇、外内，以经二物；为父子、兄弟、姑姊、甥舅、昏媾、姻亚，以象天明，为政事、庸力、行务，以从四时；为刑罚、威狱，使民畏忌，以类其震曜杀戮；为温慈、惠和，以效天之生殖长育。民有好、恶、喜、怒、哀、乐，生于六气。是故审则宜类，以制六志。哀有哭泣，乐有歌舞，喜有施舍，怒有战斗；喜生于好，怒生于恶。是故审行信令，祸福赏罚，以制死生。生，好物也；死，恶物也；好物，乐也；恶物，哀也。哀乐不失，乃能协于天地之性，是以长久。」简子曰：「甚哉，礼之大也！」对曰：「礼，上下之纪，天地之经纬也，民之所以生也，是以先王尚之。故人之能自曲直以赴礼者，谓之成人。大，不亦宜乎？」简子曰：「鞅也请终身守此言也。」宋乐大心曰：「我不输粟。我于周为客？」若之何使客？」晋士伯曰：「自践土以来，宋何役之不会，而何盟之不同？曰『同恤王室』，子焉得辟之？子奉君命，以会大事，而宋背盟，无乃不可乎？」右师不敢对，受牒而退。士伯告简子曰：「宋右师必亡。奉君命以使，而欲背盟以干盟主，无不祥大焉。」
『有鸲鹆来巢』，书所无也。师己曰：「异哉！吾闻文、武之世，童谣有之，曰：『鸲之鹆之，公出辱之。鸲鹆之羽，公在外野，往馈之马。鸲鹆跦跦，公在乾侯，征褰与襦。鸲鹆之巢，远哉遥遥。稠父丧劳，宋父以骄。鸲鹆鸲鹆，往歌来哭。』童谣有是，今鸲鹆来巢，其将及乎？」
秋，书再雩，旱甚也。
初，季公鸟娶妻于齐鲍文子，生甲。公鸟死，季公亥与公思展与公鸟之臣申夜姑相其室。及季姒与饔人檀通，而惧，乃使其妾抶己，以示秦遄之妻，曰：「公若欲使余，余不可而抶余。」又诉于公甫，曰：「展与夜姑将要余。」秦姬以告公之，公之与公甫告平子。平子拘展于卞而执夜姑，将杀之。公若泣而哀之，曰：「杀是，是杀余也。」将为之请。平子使竖勿内，日中不得请。有司逆命，公之使速杀之。故公若怨平子。
季、郤之鸡斗。季氏介其鸡，郤氏为之金距。平子怒，益宫于郤氏，且让之。故郤昭伯亦怨平子。臧昭伯之从弟会，为谗于臧氏，而逃于季氏，臧氏执旃。平子怒，拘臧氏老。将褅于襄公，万者二人，其众万于季氏。臧孙曰：「此之谓不能庸先君之庙。」大夫遂怨平子。公若献弓于公为，且与之出射于外，而谋去季氏。公为告公果、公贲。公果、公贲使侍人僚柤告公。公寝，将以戈击之，乃走。公曰：「执之。」亦无命也。惧而不出，数月不见，公不怒。又使言，公执戈惧之，乃走。又使言，公曰：「非小人之所及也。」公果自言，公以告臧孙，臧孙以难。告郤孙，郤孙以可，劝。告子家懿伯，懿伯曰：「谗人以君侥幸，事若不克，君受其名，不可为也。舍民数世，以求克事，不可必也。且政在焉，其难图也。」公退之。辞曰：「臣与闻命矣，言若泄，臣不获死。」乃馆于公。
叔孙昭子如阚，公居于长府。九月戊戌，伐季氏，杀公之于门，遂入之。平子登台而请曰：「君不察臣之罪，使有司讨臣以干戈，臣请待于沂上以察罪。」弗许。请囚于费，弗许。请以五乘亡，弗许。子家子曰：「君其许之！政自之出久矣，隐民多取食焉。为之徒者众矣，日入慝作，弗可知也。众怒不可蓄也，蓄而弗治，将温。温畜，民将生心。生心，同求将合。君必悔之。」弗听。郤孙曰：「必杀之。」公使郤孙逆孟懿子。叔孙氏之司马鬷戾言于其众曰：「若之何？」莫对。又曰：「我，家臣也，不敢知国。凡有季氏与无，于我孰利？」皆曰：「无季氏，是无叔孙氏也。」鬷戾曰：「然则救诸！」帅徒以往，陷西北隅以入。公徒释甲，执冰而踞。遂逐之。孟氏使登西北隅，以望季氏。见叔孙氏之旌，以告。孟氏执郈昭伯，杀之于南门之西，遂伐公徒。子家子曰：「诸臣伪劫君者，而负罪以出，君止。意如之事君也，不敢不改。」公曰：「余不忍也。」与臧孙如墓谋，遂行。
己亥，公孙于齐，次于阳州。齐侯将唁公于平阴，公先于野井。齐侯曰：「寡人之罪也。使有司待于平阴，为近故也。」书曰：「公孙于齐，次于阳州，齐侯唁公于野井。」礼也。将求于人，则先下之，礼之善物也。齐侯曰：「自莒疆以西，请致千社，以待君命。寡人将帅敝赋以从执事，唯命是听，君之忧，寡人之忧也。」公喜。子家子曰：「天禄不再，天若胙君，不过周公，以鲁足矣。失鲁，而以千社为臣，谁与之立」且齐君无信，不如早之晋。」弗从。臧昭伯率从者将盟，载书曰：「戮力壹心，好恶同之。信罪之有无，缱绻从公，无通外内。」以公命示子家子。子家子曰：「如此，吾不可以盟，羁也不佞，不能与二三子同心，而以为皆有罪。或欲通外内，且欲去君。二三子好亡而恶定，焉可同也？陷君于难，罪孰大焉？通外内而去君，君将速入，弗通何为？而何守焉？」乃不与盟。
昭子自阚归，见平子。平子稽颡，曰：「子若我何？」昭子曰：「人谁不死？子以逐君成名，子孙不忘，不亦伤乎！将若子何？」平子曰：「苟使意如得改事君，所谓生死而肉骨也。」昭子从公于齐，与公言。子家子命适公馆者执之。公与昭子言于幄内，曰将安众而纳公。公徒将杀昭子，伏诸道。左师展告公，公使昭子自铸归。平子有异志。冬十月辛酉，昭子齐于其寝，使祝宗祈死。戊辰，卒。左师展将以公乘马而归，公徒执之。
壬申，尹文公涉于巩，焚东訾，弗克。
十一月，宋元公将为公故如晋。梦大子栾即位于庙，己与平公服而相之。旦，召六卿。公曰：「寡人不佞，不能事父兄，以为二三子忧，寡人之罪也。若以群子之灵，获保首领以没，唯是匾柎所以藉干者，请无及先君。」仲几对曰：「君若以社稷之故，私降昵宴，群臣弗敢知。若夫宋国之法，死生之度，先君有命矣。群臣以死守之，弗敢失队。臣之失职，常刑不赦。臣不忍其死，君命只辱。」宋公遂行。己亥，卒于曲棘。
十二月庚辰，齐侯围郓。
初，臧昭伯如晋，臧会窃其宝龟偻句，以卜为信与僭，僭吉。臧氏老将如晋问，会请往。昭伯问家故，尽对。及内子与母弟叔孙，则不对。再三问，不对。归，及郊，会逆，问，又如初。至，次于外而察之，皆无之。执而戮之，逸，奔郤。郤鲂假使为贾正焉。计于季氏。臧氏使五人以戈盾伏诸桐汝之闾。会出，逐之，反奔，执诸季氏中门之外。平子怒，曰：「何故以兵入吾门？」拘臧氏老。季、臧有恶。及昭伯从公，平子立臧会。会曰：「偻句不馀欺也。」
楚子使薳射城州屈，复茄人焉。城丘皇，迁訾人焉。使熊相衣某郭巢，季然郭卷。子大叔闻之，曰：「楚王将死矣。使民不安其土，民必忧，忧将及王，弗能久矣。」', '', '', '二十五年春季，叔孙婼到宋国聘问。桐门右师接见他，谈话，右师看不起宋国的大夫，并且轻视司城氏。叔孙婼告诉他的手下人说：“右师恐怕要逃亡吧！君子尊重他自己，然后能及于别人，因此有礼。现在这个人对他们的大夫和宗族都不加尊重，这是轻视他自己，能够有礼吗？无礼必定逃亡。”
宋元公设享礼招待叔孙婼，赋《新宫》这首诗，叔孙婼赋《车辖》这首诗。第二天设宴，喝酒，很高兴，宋元公让昭子坐在右边，说着话就相对掉下了眼泪。乐祁帮着主持宴会，退下去告诉别人说：“今年国君和叔孙恐怕都要死了吧！我听说：‘该高兴的时候悲哀，而该悲哀的时候高兴，这都是心意丧失。’心的精华神明，这就叫魂魄，魂魄离去了，怎么能活得久长？”
季公若的姐姐是小邾君夫人，生了宋元公夫人，宋元公夫人生了个女儿，嫁给季平子，叔孙婼到宋国行聘，并且迎亲。季公若跟随前去，告诉宋元公夫人让她不要答应亲事，因为鲁国正在准备赶走季平子。宋元公夫人告诉宋元公，宋元公告诉乐祁，乐祁说：“给他。如果像所说的那样，鲁国国君一定要逃往国外。政权掌握在季氏手中已经三代了，鲁国国君丧失政权已经四代了。失掉民心而能满足他愿望的，还没有过。国君因此才镇抚他的百姓。《诗》说：‘人才的丧失，就是心头的忧虑。’鲁国国君已经失去了民心，哪里能实现他的愿望？安静地等待天命还可以，有所举动必定造成忧患。”
夏季，鲁国子太叔和晋国赵鞅、宋国乐大心、卫国北宫喜、郑国游吉、曹人、邾人、滕人、薛人、小邾人在黄父会见，这是为了商量安定王室。赵鞅命令诸侯的大夫向周敬王输送粮食、准备戍守的将士，说：“明年将要送天子回去。”
子太叔进见赵简子，赵简子向他询问揖让、周旋的礼节。子太叔回答说：“这是仪，不是礼。”赵简子说：“谨敢请问什么叫礼？”子太叔回答说：“吉曾经听到先大夫子产说：‘礼，是上天的规范，大地的准则，百姓行动的依据。’天地的规范，百姓就加以效法，效法上天的英明，依据大地的本性，产生了上天的六气，使用大地的五行。气是五种味道，表现为五种颜色，显示为五种声音，过了头就昏乱，百姓就失掉本性，因此制作了礼用来使它有所遵循：制定了六畜、五牲、三牺，以使五味有所遵循。制定九文、六采、五章，以使五色有所遵循。制定九歌、八风、七音、六律，以使五声有所遵循。制定君臣上下的关系，以效法大地的准则。制定夫妇内外的关系，以规范两种事物。制定父子、兄弟、姑姊、甥舅、翁婿、连襟的关系，以象征上天的英明。制定政策政令、农工管理、行动措施，以随顺四时。制定刑罚、牢狱让百姓害怕，以模仿雷电的杀伤。制定温和慈祥的措施，以效法上天的生长万物。百姓有好恶、喜怒、哀乐，它们以六气派生，所以要审慎地效法，适当地模仿，以制约六志。哀痛有哭泣，欢乐有歌舞，高兴有施舍，愤怒有战斗。高兴从爱好而来，愤怒从讨厌而来。所以要使行动审慎、使命令有信用，用祸福赏罚，来制约死生。生，是人们喜好的事情。死，是人们讨厌的事物。喜好的事物，是欢乐。讨厌的事物，是哀伤。欢乐不失于礼，就能协调天地的本性，因此能够长久。’”赵简子说：“礼的伟大达到极点！”子太叔回答说：“礼，是上下的纲纪，天地的准则，百姓所生存的依据，因此先王尊崇它，所以人们能够从不同的天性经过自我修养改造或者直接达到礼的，就叫做完美无缺的人。它的伟大，不也是适宜的吗？”赵简子说：“我赵鞅啊，请求一辈子遵循这些话。”
宋国的乐大心说：“我们不给天子送粮食，我们对周朝来说是客人，为什么要指使客人送粮食？”晋国的士伯说：“从践土结盟以来，宋国有哪一次战役不参加，又有哪一次结盟不在一起？盟辞说‘一起为王室操心’，您哪里能躲开？您奉了君王的命令，来参加这重大的事件，而宋国倒违背盟约，恐怕不可以吧！”乐大心不敢回答，接受了简札退出去。士伯告诉赵简子说：“宋国的右师必然逃亡。奉了国君的命令出使，而想要背弃盟约以触犯盟主，没有比这再大的不吉祥了。”
“有鸜鹆来巢”，这是过去所没有记载的事情。师己说：“怪呀！我听说文王、成王的时代，童谣有这样的话说：‘鸜啊鹆啊，国君出国受到羞辱。鸜鹆的羽毛，国君住在远郊，臣下去把马匹送到。鸜鹆蹦蹦跳跳，国君住在乾侯，向人要裤子短袄。鸜鹆的老巢，路远遥遥，稠父死于辛劳，宋父代立而骄，鸜鹆鸜鹆，去的时候唱歌，回来的时候号哭。’童谣有这个。现在鸜鹆前来筑巢，恐怕将要发生祸难了吧！”
秋季，《春秋》记载两次大的雩祭，这是由于旱灾严重。
当初，季公鸟在齐国鲍文子家娶了妻子，生了某甲。季公鸟死，季公亥、公思展和季公鸟的家臣申夜姑管理他的家务。等到季姒和管伙食的檀私通，季姒感到害怕，就让她的侍女打了自己一顿，跑去给秦遄的妻子看，说：“公若要让我陪他睡觉，我不答应，就打了我。”又向公甫诉苦，说：“展和夜姑准备要挟我。”秦遄的妻子把话告诉公之。公之和公甫告诉了平子，平子把公思展拘留在卞地，抓了夜姑准备杀他。季公亥哭泣着哀求说：“杀了这个人，就是杀了我。”准备为他请求。平子让小仆役不让他进来，太阳到中午没有能得到请求。官吏去接受处理夜姑的命令，公之要他快点杀了夜姑，所以季公亥怨恨平子。
季氏、郈氏斗鸡。季氏给鸡套上皮甲，郈氏给鸡安上金属爪子。季氏的鸡斗败，季平子发怒，在郈氏那里扩建自己的住宅，并且责备他们。所以郈昭伯也怨恨季平子。
臧昭伯的叔伯兄弟臧会在臧氏那里诬陷别人，逃到季氏那里，臧氏扣押了他。季平子发怒，拘留了臧氏的家臣。将要在襄公庙里举行祭祀，跳万舞的只有两个人，多数人到季氏那里跳万舞去了。臧昭伯说：“这叫做不能在先君的宗庙里酬谢先君的功劳。”大夫们于是也就怨恨季平子。
季公亥向公为献弓，并且和他外出射箭，谋划去掉季氏。公为告诉了公果、公贲。公果、公贲派随从僚柤报告昭公。昭公已经睡了，要拿起戈来打僚柤，僚柤就跑了，昭公说：“逮住他！”但也没有正式下命令。僚柤恐惧不敢出门，几个月不去朝见昭公。昭公并不发怒。后来又派僚柤去报告昭公，昭公拿起戈来吓唬他，他就跑了。又派僚柤去说，昭公说：“这不是小人管得着的。”公果自己去说了，昭公把话告诉臧孙。臧孙认为难办。告诉了郈昭伯，郈昭伯认为可行，劝昭公干。昭公告诉子家懿伯。懿伯说：“坏人们让君王侥幸行事，事情如果不成功，君王蒙受坏名声，这是不能做的。丢掉百姓已经几代了，以此要求事情成功，这是没有把握的事。而且政权在人家手里，恐怕是很难算计他的。”昭公让懿伯下去，懿伯回答说：“下臣已经听到您的命令了，话如果泄漏，下臣会不得好死的。”于是就住在公宫里。
叔孙昭子到阚地去，昭公住在长府里。九月十一日，攻打季氏，在大门口杀死公之，就攻了进去。季平子登台请求说：“君上没有调查下臣的罪过，派官吏使用武力讨伐下臣，下臣请求待在沂水边上让君王审查。”昭公不答应。请求囚禁在费地，昭公也不答应。请求带着五辆车子逃亡，昭公也不答应。子家子说：“君王还是答应他吧！政令从他那里发出已经很久了，贫困的百姓大都靠他吃饭，做他一党的人也很多了，太阳下山以后，坏人是否冒出来，还不知道呢。众人的怒气不能让它积聚，积聚起来而不妥善处理，怒气会越来越大。越来越大的怒气积聚起来，百姓将会产生叛变之心，生背叛之心，和有同样要求的人会纠合一起，君王必然要后悔的！”昭公不听从他的意见，郈昭伯说：“一定要杀了他。”
昭公派郈昭伯迎接孟懿子，叔孙氏的司马鬷戾问他的手下人说：“怎么办？”没有人回答。又说：“我是家臣，不敢考虑国家大事，有季氏和没有季氏，哪一种情况对于我有利？”大家都说：“没有季氏，就是没有叔孙氏。”鬷戾说：“那么就去救援他吧！”率领手下人前去，攻破西北角进去。昭公的亲兵正脱去皮甲拿着箭筒蹲着，鬷戾就把他们赶走了，孟氏派人登上西北角，瞭望季氏。瞭望的人看到叔孙氏的旗子，把情况报告孟氏。孟氏逮捕了郈昭伯，把他在南门的西边杀死了他，就乘势攻打昭公的亲兵，子家子说：“臣下们假装是劫持君王的人，背着罪名出国，君王留下来，意如事奉君王，就不敢不改变态度。”昭公说：“我不能忍受。”就和臧昭伯去祖坟上辞别祖宗，并且谋划逃亡的事，动身走了。
十一月十三日，昭公逃亡到齐国，住在阳州。齐景公准备在平阴慰问昭公，昭公先到达野井。齐景公说：“这是寡人的罪过。”让官吏在平阴等待，是为了就近的缘故。《春秋》记载说“公孙于齐，次于阳州，齐侯唁公于野井”，这是合于礼的。将要有求于人，就要先居于人下，这是合于礼的好事。齐景公说：“从莒国的国境以西，请奉送君王二万五千户，以等待君王的命令，寡人将要率领敝邑的军队以跟从执事，唯命是听。君王的忧虑，就是我的忧虑。”昭公很高兴，子家子说：“上天所赐的爵禄不再降给君王了，上天如果保佑君王，也不能超过周公。给君王鲁国就足够了。失去鲁国而带着二万五千户做臣下，谁还为君王复位？况且齐国的国君不讲信用，不如早点到晋国去。”昭公不听从他的意见。
臧昭伯率领跟随昭公的人将要结盟，盟书说：“合力同心，好恶一致，明确有罪无罪，坚决跟从国君，不要内外沟通。”用昭公的名义给子家子看，子家子说：“像这样，我不能盟誓，羁没有才能，不能和您几位合力同心，而是认为都有罪，我也可能与国外交谈，并且想要离开国君为国君奔走四方。您几位喜欢逃亡而不想安定君位，我哪里能和您几位好恶一致？陷国君于危难之中，还有比这再大的罪过吗？为了里外通气而离开国君，国君就能快一点回国，不通消息做什么？又能死守在哪里？”于是就不参加结盟。
昭子从阚地回国，进见季平子，平子叩头，说：“您要我怎么办？”昭子说：“人有谁不死？您由于驱逐国君成了名，子子孙孙不忘记，不也可悲吗？我能把您怎么办？”季平子说：“如果让我能改变态度事奉国君，就是所谓让死人再生、白骨长肉的事情了。”昭子到齐国去跟随昭公，向昭公报告，子家子命令把凡是到昭公宾馆去的人都抓起来，昭公和昭子在帐幕里说话，昭子说：“将要安定大众而接纳您。”昭公的亲兵准备杀死昭子，埋伏在路边。左师展报告昭公，昭公让昭子取道从铸地回国。这时季平子有了别的想法。冬季，十月初四日，昭子在正寝中斋戒，让祝宗为他求死。十一日，死去。左师展准备带着昭公坐一辆车回国，昭公的亲兵逮捕了他。
十月十五日，尹文公领兵徒步渡过洛水，放火烧了东訾，没有战胜。
十一月，宋元公准备为鲁昭公的缘故到晋国去，梦见太子栾在宗庙中即位，自己和宋平公穿着朝服辅助他。早晨，召见六卿，宋元公说：“寡人没有才能，不能事奉父辈兄辈，成为您几位的忧虑，这是寡人的罪过。如果托诸位的福气，能够保全脑袋而善终，那些用来装载我的骸骨的棺木，请不要超过先君的体制。”仲几回答说：“君王如果由于国家的缘故，自己减损饮宴声色的供奉，下臣们不敢与闻。至于宋国的法度，出生和下葬的礼制，先君早已经有了成文规定了，下臣们用生命来维护它，不敢违背。下臣失职，法律是不能赦免的。下臣不愿这样地死去，只能不听君王的命令。”宋元公就动身了。十三日，死在曲棘。
十二月十四日，齐景公包围了郓地。
当初，臧昭伯去到晋国，臧会偷了他的宝龟偻句，臧会用来占卜应该诚实还是不诚实，结果是不诚实吉利。臧氏的家臣将要到晋国问候臧昭伯，臧会请求派他前去。昭伯问起家里的事，臧会全都回答了。昭伯问到妻子和同母弟叔孙，就不回答。再三问他，还是不回答。等到昭伯回国到达郊外，臧会前去迎接。问起那件事，还像从前那样不回答。昭伯抵达国都，先住在城外而查问妻子兄弟，都没有问出什么事。昭伯就抓了臧会要杀他，臧会逃走，逃亡到郈地，郈鲂假让他做了贾正。一次臧会到季氏那里去送帐本，臧氏派五个人带着戈和楯埋伏在桐汝的里门里。臧会出来，就赶上去，臧会转身逃走，在季氏的中门之外被抓住，季氏发怒，说：“为什么带武器进我的家门？”拘留了臧氏的家臣。季氏、臧氏因此互相有了恶感，等到昭伯随从昭公，季氏立了臧会做臧氏的继承人。臧会说：“偻句没有欺骗我呀。”
楚平王派薳射在州屈筑城，让茄地人回去居住。在丘皇筑城，让訾地人迁去居住，派熊相禖在巢地筑外城，派季然在卷地筑外城。子太叔听到了这件事，说：“楚平王快要死了。让百姓不能安居在原来的土地上，百姓必然忧愁，忧愁将要延及到君王的身上，君王不能活长久了。”', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8d2e6a6b501f974b8c", "shortContent": "本篇在构思上多次娴熟地运用反常法，一反人们习惯的顺理成章，而用“逆”理成章，不落窠臼，使读者出乎意料而留下强烈、深刻的印象。\n柳、崔两人不期而遇，一见钟情。崔女不愿嫁给表兄王生，在母亲同意下与柳生迁到金城里悄悄结婚（母亲居然同意，第一反常）。崔女之大舅官居执金吾，来到崔家，崔母对他哭着说：王生没等到举行婚礼就把崔女抢走了（居然无中生有，诬赖外甥，第二反常）。崔女之舅怒，回去把儿子打了一顿。崔母死，...", "authors": ["戴逸如"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f9d0ce818559d07126a", "shortContent": "我国古代文学作品对那些仪表堂堂、气宇轩昂而虚有其表的人物，常不乏尖锐、锋利的讽刺之笔。《聊斋志异》中的《嘉平公子》即为其中构思奇巧、讽刺深刻的篇章之一。\n从表面上看，《嘉平公子》是一篇人鬼相恋的故事。然而从作品的深层含义来看，则在着力于讽刺重貌轻才的世俗陋习。嘉平公子式的世家子弟，仪容秀美，风度翩翩，门第高贵，自是少女们追慕的白马王子；遗憾的是不学无术，连写张便笺也是错别字连篇，令多情的女鬼为之感...", "authors": ["王", "征"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559127288, '5cedf474c8959c0069f516b2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643075, '左传 · 昭公 · 昭公二十六年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有六年春王正月，葬宋元公。三月，公至自齐，居于郓。夏，公围成。秋，公会齐侯、莒子、邾子、杞伯，盟于鄟陵。公至自会，居于郓。九月庚申，楚子居卒。冬十月，天王入于成周。尹氏、召伯、毛伯以王子朝奔楚。
【传】二十六年春，王正月庚申，齐侯取郓。
葬宋元公，如先君，礼也。
三月，公至自齐，处于郓，言鲁地也。
夏，齐侯将纳公，命无受鲁货。申丰从女贾，以币锦二两，缚一如瑱，适齐师。谓子犹之人高齮：「能货子犹，为高氏后，粟五千庾。」高齮以锦示子犹，子犹欲之。能货子犹，为高氏后，粟五千庚。高齮以锦示子犹，子犹欲之。齮曰：「鲁人买之，百两一布，以道之不通，先入币财。」子犹受之，言于齐侯曰：「群臣不尽力于鲁君者，非不能事君也。然据有异焉。宋元公为鲁君如晋，卒于曲棘。叔孙昭子求纳其君，无疾而死。不知天之弃鲁耶，抑鲁君有罪于鬼神，故及此也？君若待于曲棘，使群臣从鲁君以卜焉。若可，师有济也。君而继之，兹无敌矣。若其无成，君无辱焉。」齐侯从之，使公子锄帅师从公。成大夫公孙朝谓平子曰：「有都以卫国也，请我受师。」许之。请纳质，弗许，曰：「信女，足矣。」告于齐师曰：「孟氏，鲁之敝室也。用成已甚，弗能忍也，请息肩于齐。」齐师围成。成人伐齐师之饮马于淄者，曰：「将以厌众。」鲁成备而后告曰：「不胜众。」师及齐师战于炊鼻。齐子渊捷从泄声子，射之，中楯瓦。繇朐汰輈，匕入者三寸。声子射其马，斩鞅，殪。改驾，人以为鬷戾也而助之。子车曰：「齐人也。」将击子车，子车射之，殪。其御曰：「又之。」子车曰：「众可惧也，而不可怒也。」子囊带从野泄，叱之。泄曰：「军无私怒，报乃私也，将亢子。」又叱之，亦叱之。冉竖射陈武子，中手，失弓而骂。以告平子，曰：「有君子白皙，鬒须眉，甚口。」平子曰：「必子强也，无乃亢诸？」对曰：「谓之君子，何敢亢之？」林雍羞为颜鸣右，下。苑何忌取其耳，颜鸣去之。苑子之御曰：「视下顾。」苑子刜林雍，断其足。{轻金}而乘于他车以归，颜鸣三入齐师，呼曰：「林雍乘！」
四月，单子如晋告急。五月戊午，刘人败王城之师于尸氏。戊辰，王城人、刘人战于施谷，刘师败绩。
秋，盟于鄟陵，谋纳公也。
七月己巳，刘子以王出。庚午，次于渠。王城人焚刘。丙子，王宿于褚氏。丁丑，王次于萑谷。庚辰，王入于胥靡。辛巳，王次于滑。晋知跞、赵鞅帅师纳王，使汝宽守关塞。
九月，楚平王卒。令尹子常欲立子西，曰：「大子壬弱，其母非适也，王子建实聘之。子西长而好善。立长则顺，建善则治。王顺国治，可不务乎？」子西怒曰：「是乱国而恶君王也。国有外援，不可渎也。王有适嗣，不可乱也。败亲、速仇、乱嗣，不祥，我受其名。赂吾以天下，吾滋不从也。楚国何为？必杀令尹！」令尹惧，乃立昭王。
冬十月丙申，王起师于滑。辛丑，在郊，遂次于尸。十一月辛酉，晋师克巩。召伯盈逐王子朝，王子朝及召氏之族、毛伯得、尹氏固、南宫嚚奉周之典籍以奔楚。阴忌奔莒以叛。召伯逆王于尸，及刘子、单子盟。遂军圉泽，次于堤上。癸酉，王入于成周。甲戌，盟于襄宫。晋师使成公般戍周而还。十二月癸未，王入于庄宫。
王子朝使告于诸侯曰：「昔武王克殷，成王靖四方，康王息民，并建母弟，以蕃屏周。亦曰：『吾无专享文、武之功，且为后人之迷败倾覆，而溺入于难，则振救之。』至于夷王，王愆于厥身，诸侯莫不并走其望，以祈王身。至于厉王，王心戾虐，万民弗忍，居王于彘。诸侯释位，以间王政。宣王有志，而后效官。至于幽王，天不吊周，王昏不若，用愆厥位。携王奸命，诸侯替之，而建王嗣，用迁郏鄏。则是兄弟之能用力于王室也。至于惠王，天不靖周，生颓祸心，施于叔带，惠、襄辟难，越去王都。则有晋、郑，咸黜不端，以绥定王家。则是兄弟之能率先王之命也。在定王六年，秦人降妖，曰：『周其有王，亦克能修其职。诸侯服享，二世共职。王室其有间王位，诸侯不图，而受其乱灾。』至于灵王，生而有。王甚神圣，无恶于诸侯。灵王、景王，克终其世。今王室乱，单旗、刘狄，剥乱天下，壹行不若。谓：『先王何常之有？唯余心所命，其谁敢请之？』帅群不吊之人，以行乱于王室。侵欲无厌，规求无度，贯渎鬼神，慢弃刑法，倍奸齐盟，傲很威仪，矫诬先王。晋为不道，是摄是赞，思肆其罔极。兹不谷震荡播越，窜在荆蛮，未有攸厎。若我一二兄弟甥舅，奖顺天法，无助狡猾，以从先王之命，毋速天罚，赦图不谷，则所愿也。敢尽布其腹心，及先王之经，实深图之。昔先王之命曰：『王后无适，则择立长。年钧以德，德钧以卜。』王不立爱，公卿无私，古之制也。穆后及大子寿早夭即世，单、刘赞私立少，以间先王，亦唯伯仲叔季图之！」
闵马父闻子朝之辞，曰：「文辞以行礼也。子朝干景之命，远晋之大，以专其志，无礼甚矣，文辞何为？」
齐有彗星，齐侯使禳之。晏子曰：「无益也，只取诬焉。天道不谄，不贰其命，若之何禳之？且天之有彗也，以除秽也。君无秽德，又何禳焉？若德之秽，禳之何损？《诗》曰：『惟此文王，小心翼翼，昭事上帝，聿怀多福。厥德不回，以受方国。』君无违德，方国将至，何患于彗？《诗》曰：『我无所监，夏后及商。用乱之故，民卒流亡。』若德回乱，民将流亡，祝史之为，无能补也。」公说，乃止。
齐侯与晏子坐于路寝，公叹曰：「美哉室！其谁有此乎？」晏子曰：「敢问何谓也？」公曰：「吾以为在德。」对曰：「如君之言，其陈氏乎！陈氏虽无大德，而有施于民。豆区釜钟之数，其取之公也簿，其施之民也厚。公厚敛焉，陈氏厚施焉，民归之矣。《诗》曰：『虽无德与女，式歌且舞。』陈氏之施，民歌舞之矣。后世若少惰，陈氏而不亡，则国其国也已。」公曰：「善哉！是可若何？」对曰：「唯礼可以已之。在礼，家施不及国，民不迁，农不移，工贾不变，士不滥，官不滔，大夫不收公利。」公曰：「善哉！我不能矣。吾今而后知礼之可以为国也。」对曰：「礼之可以为国也久矣。与天地并。君令臣共，父慈子孝，兄爱弟敬，夫和妻柔，姑慈妇听，礼也。君令而不违，臣共而不贰，父慈而教，子孝而箴；兄爱而友，弟敬而顺；夫和而义，妻柔而正；姑慈而从，妇听而婉：礼之善物也。」公曰：「善哉！寡人今而后闻此礼之上也。」对曰：「先王所禀于天地，以为其民也，是以先王上之。」
', '', '', '', NULL, '', 'indent', 1559211175, '5cef3be2ba39c80068a4b0ba', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643076, '左传 · 昭公 · 昭公二十七年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有七年春，公如齐。公至自齐，居于郓。夏四月，吴弑其君僚。楚杀其大夫郤宛。秋，晋士鞅、宋乐祁犁、卫北宫喜、曹人、邾人、滕人会于扈。冬十月，曹伯午卒。邾快来奔。公如齐。公至自齐，居于郓。
【传】二十七年春，公如齐。公至自齐，处于郓，言在外也。
吴子欲因楚丧而伐之，使公子掩余、公子烛庸帅师围潜。使延州来季子聘于上国，遂聘于晋，以观诸侯。楚莠尹然，工尹麇帅师救潜。左司马沈尹戌帅都君子与王马之属以济师，与吴师遇于穷。令尹子常以舟师及沙汭而还。左尹郤宛、工尹寿帅师至於潜，吴师不能退。
吴公子光曰：「此时也，弗可失也。」告鱄设诸曰：「上国有言曰：『不索何获？』我，王嗣也，吾欲求之。事若克，季子虽至，不吾废也。」鱄设诸曰：「王可弑也。母老子弱，是无若我何。」光曰：「我，尔身也。」
夏四月，光伏甲于堀室而享王。王使甲坐于道，及其门。门阶户席，皆王亲也，夹之以铍。羞者献体改服于门外，执羞者坐行而入，执铍者夹承之，及体以相授也。光伪足疾，入于堀室。鱄设诸置剑于鱼中以进，抽剑剌王，铍交于胸，遂弑王。阖庐以其子为卿。
季子至，曰：「苟先君废无祀，民人无废主，社稷有奉，国家无倾，乃吾君也。吾谁敢怨？哀死事生，以待天命。非我生乱，立者从之，先人之道也。」覆命哭墓，复位而待。吴公子掩余奔徐，公子烛庸奔钟吾。楚师闻吴乱而还。
郤宛直而和，国人说之。鄢将师为右领，与费无极比而恶之。令尹子常贿而信谗，无极谮郤宛焉，谓子常曰：「子恶欲饮子酒。」又谓子恶：「令尹欲饮酒于子氏。」子恶曰：「我，贱人也，不足以辱令尹。令尹将必来辱，为惠已甚。吾无以酬之，若何？」无极曰：「令尹好甲兵，子出之，吾择焉。」取五甲五兵，曰：「置诸门，令尹至，必观之，而从以酬之。」及飨日，帷诸门左。无极谓令尹曰：「吾几祸子。子恶将为子不利，甲在门矣，子必无往。且此役也，吴可以得志，子恶取赂焉而还，又误群帅，使退其师，曰：『乘乱不祥。』吴乘我丧，我乘其乱，不亦可乎？」令尹使视郤氏，则有甲焉。不往，召鄢将师而告之。将师退，遂令攻郤氏，且爇之。子恶闻之，遂自杀也。国人弗爇，令曰：「爇郤氏，与之同罪。」或取一编菅焉，或取一秉秆焉，国人投之，遂弗也。令尹炮之，尽灭郤氏之族党，杀阳令终与其弟完及佗与晋陈及其子弟。晋陈之族呼于国曰：「鄢氏、费氏自以为王，专祸楚国，弱寡王室，蒙王与令尹以自利也。令尹尽信之矣，国将如何？」令尹病之。
秋，会于扈，令戍周，且谋纳公也。宋、卫皆利纳公，固请之。范献子取货于季孙，谓司城子梁与北宫贞子曰：「季孙未知其罪，而君伐之，请囚，请亡，于是乎不获。君又弗克，而自出也。夫{山乙}无备而能出君乎？季氏之复，天救之也。休公徒之怒，而启叔孙氏之心。不然，岂其伐人而说甲执冰以游？叔孙氏惧祸之滥，而自同于季氏，天之道也。鲁君守齐，三年而无成。季氏甚得其民，淮夷与之，有十年之备，有齐、楚之援，有天之赞，有民之助，有坚守之心，有列国之权，而弗敢宣也，事君如在国。故鞅以为难。二子皆图国者也，而欲纳鲁君，鞅之愿也，请从二子以围鲁。无成，死之。」二子惧，皆辞。乃辞小国，而以难复。
孟懿子、阳虎伐郓。郓人将战，子家子曰：「天命不慆久矣。使君亡者，必此众也。天既祸之，而自福也，不亦难乎？犹有鬼神，此必败也。乌呼！为无望也夫，其死于此乎！」公使子家子如晋，公徒败于且知。
楚郤宛之难，国言未已，进胙者莫不谤令尹。沈尹戌言于子常曰：「夫左尹与中厩尹莫知其罪，而子杀之，以兴谤讟，至于今不已。戌也惑之。仁者杀人以掩谤，犹弗为也。今吾子杀人以兴谤，而弗图，不亦异乎？夫无极，楚之谗人也，民莫不知。去朝吴，出蔡侯朱，丧太子建，杀连尹奢，屏王之耳目，使不聪明。不然，平王之温惠共俭，有过成、庄，无不及焉。所以不获诸侯，迩无极也。今又杀三不辜，以兴大谤，几及子矣。子而不图，将焉用之？夫鄢将师矫子之命，以灭三族，国之良也，而不愆位。吴新有君，疆埸日骇，楚国若有大事，子其危哉！知者除谗以自安也，今子爱谗以自危也，甚矣其惑也！」子常曰：「是瓦之罪，敢不良图。」九月己未，子常杀费无极与鄢将师，尽灭其族，以说于国。谤言乃止。
冬，公如齐，齐侯请飨之。子常子曰：「朝夕立于其朝，又何飨焉？其饮酒也。」乃饮酒，使宰献，而请安。子仲之子曰重，为齐侯夫人，曰：「请使重见。」子家子乃以君出。
十二月，晋籍秦致诸侯之戍于周，鲁人辞以难。', '', '', '', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8f0f8fda556506e480", "shortContent": "本篇写的是一个村民因埋蚕卖桑度荒而遭受杀身之祸的故事。晚唐咸通年间洛阳一带闹饥荒，谷价飞涨，民不聊生，村民王公直埋掉蚕箔，卖出桑叶，以买粮度荒，免于饿死。此举出于无奈，无可厚非，但作者为什么要写他因此落得“杖杀”的悲惨下场呢？\n原因之一是受因果报应思想的影响。唐代佛教盛行，佛教认为事物有起因必有结果，“善因”有“善果”，“恶因”有“恶果”，而不得杀生被列为佛教徒“十戒”之中的第一戒，杀生无疑被视为...", "authors": ["韩黎范"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559211152, '5cef3c0cba39c80068a4b4a2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643077, '左传 · 昭公 · 昭公二十八年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有八年春王三月，葬曹悼公。公如晋，次于乾侯。夏四月丙戌，郑伯宁卒。六月，葬郑定公。秋七月癸巳，滕子宁卒。冬，葬滕悼公。
【传】二十八年春，公如晋，将如乾侯。子家子曰：「有求于人，而即其安，人孰矜之？其造于竟。」弗听。使请逆于晋。晋人曰：「天祸鲁国，君淹恤在外。君亦不使一个辱在寡人，而即安于甥舅，其亦使逆君？」使公复于竟而后逆之。
晋祁胜与邬臧通室，祁盈将执之，访于司马叔游。叔游曰：「《郑书》有之：『恶直丑正，实蕃有徒。』无道立矣，子惧不免。《诗》曰：『民之多辟，无自立辟。』姑已，若何？」盈曰：「祁氏私有讨，国何有焉？」遂执之。祁胜赂荀跞，荀跞为之言于晋侯，晋侯执祁盈。祁盈之臣曰：「钧将皆死，憖使吾君闻胜与臧之死以为快。」乃杀之。夏六月，晋杀祁盈及杨食我。食我，祁盈之党也，而助乱，故杀之。遂灭祁氏、羊舌氏。
初，叔向欲娶于申公巫臣氏，其母欲娶其党。叔向曰：「吾母多而庶鲜，吾惩舅氏矣。」其母曰：「子灵之妻杀三夫，一君，一子，而亡一国、两卿矣。可无惩乎？吾闻之：『甚美必有甚恶，』是郑穆少妃姚子之子，子貉之妹也。子貉早死，无后，而天钟美于是，将必以是大有败也。昔有仍氏生女，鬒黑而甚美，光可以鉴，名曰玄妻。乐正后夔取之，生伯封，实有豕心，贪婪无餍，忿类无期，谓之封豕。有穷后羿灭之，夔是以不祀。且三代之亡，共子之废，皆是物也。女何以为哉？夫有尤物，足以移人，苟非德义，则必有祸。」叔向惧，不敢取。平公强使取之，生伯石。伯石始生，子容之母走谒诸姑，曰：「长叔姒生男。」姑视之，及堂，闻其声而还，曰：「是豺狼之声也。狼子野心，非是，莫丧羊舌氏矣。」遂弗视。
秋，晋韩宣子卒，魏献子为政。分祁氏之田以为七县，分羊舌氏之田以为三县。司马弥牟为邬大夫，贾辛为祁大夫，司马乌为平陵大夫，魏戊为梗阳大夫，知徐吾为涂水大夫，韩固为马首大夫，孟丙为盂大夫，乐霄为铜鞮大夫，赵朝为平阳大夫，僚安为杨氏大夫。谓贾辛、司马乌为有力于王室，故举之。谓知徐吾、赵朝、韩固、魏戊，余子之不失职，能守业者也。其四人者，皆受县而后见于魏子，以贤举也。
魏子谓成鱄：「吾与戊也县，人其以我为党乎？」对曰：「何也？戊之为人也，远不忘君，近不逼同，居利思义，在约思纯，有守心而无淫行。虽与之县，不亦可乎？昔武王克商，光有天下。」其兄弟之国者十有五人，姬姓之国者四十人，皆举亲也。夫举无他，唯善所在，亲疏一也。《诗》曰：『唯此文王，帝度其心。莫其德音，其德克明。克明克类，克长克君。王此大国，克顺克比。比于文王，其德靡悔。既受帝祉，施于孙子。』心能制义曰度，德正应和曰莫，照临四方曰明，勤施无私曰类，教诲不倦曰长，赏庆刑威曰君，慈和遍服曰顺，择善而从之曰比，经纬天地曰文。九德不愆，作事无悔，故袭天禄，子孙赖之。主之举也，近文德矣，所及其远哉！」
贾辛将适其县，见于魏子。魏子曰：「辛来！昔叔向适郑，鬲□蔑恶，欲观叔向，从使之收器者而往，立于堂下。一言而善。叔向将饮酒，闻之，曰：『必鬷明也。』下，执其手以上，曰『昔贾大夫恶，娶妻而美，三年不言不笑，御以如皋，射雉，获之。其妻始笑而言。贾大夫曰：「才之不可以已，我不能射，女遂不言不笑夫！」今子少不扬，子若无言，吾几失子矣。言不可以已也如是。』遂知故在。今女有力于王室，吾是以举女。行乎！敬之哉！毋堕乃力！」
仲尼闻魏子之举也，以为义，曰：「近不失亲，远不失举，可谓义矣。」又闻其命贾辛也，以为忠：「《诗》曰：『永言配命，自求多福』，忠也。魏子之举也义，其命也忠，其长有后于晋国乎！」
冬，梗阳人有狱，魏戊不能断，以狱上。其大宗赂以女乐，魏子将受之。魏戊谓阎没、女宽曰：「主以不贿闻于诸侯，若受梗阳人，贿莫甚焉。吾子必谏。」皆许诺。退朝，待于庭。馈入，召之。比置，三叹。既食，使坐。魏子曰：」吾闻诸伯叔，谚曰：『唯食忘忧。』吾子置食之间三叹，何也？」同辞而对曰：「或赐二小人酒，不夕食。馈之始至，恐其不足，是以叹。中置，自咎曰：『岂将军食之，而有不足？』是以再叹。及馈之毕，愿以小人之腹为君子之心，属厌而已。」献子辞梗阳人。', '', '', '二十八年春季，鲁昭公到晋国去，将要到乾侯去。子家子说：“有求于别人，而又跑去安安稳稳地住着，有谁还来同情您，还是到我国和晋国的边境上等着好。”昭公不听，派人请求晋国来人迎接。晋国人说：“上天降祸鲁国，君王淹留在外，也不派一个人来问候寡人，而是跑去安安稳稳地住在甥舅的国家里，难道还要派人到齐国迎接君王？”让昭公回到鲁国的边境上，然后派人迎接。
晋国的祁胜和邬臧互相交换妻子。祁盈准备逮捕他们，去问司马叔游。叔游说：“《郑书》有这样的话：‘嫉害正直，这样的人多的是。’无道的人在位，您恐怕不能免于祸患。《诗》说：‘百姓的邪恶很多，自己不要再陷入邪恶。’暂时不执行，怎么样？”祁盈说：“对祁氏私家的讨伐，和国家有什么关系？”于是就逮捕了他们。祁胜贿赂荀跞，荀跞为他在晋顷公面前说话。晋顷公逮捕了祁盈，祁盈的家臣说：“同样是一起被杀，宁可让我们主子听到祁胜和邬臧的死讯，我们也可以痛快一下。”就杀了这两个人。夏季，六月，晋顷公杀了祁盈和杨食我，杨食我，是祁盈的党羽，并且帮着祁盈作乱，所以杀了他，于是就灭亡了祁氏、羊舌氏。
起初，叔向想要娶申公巫臣的女儿做妻子，他的母亲要他娶她的亲族。叔向说：“我的母亲多而庶兄弟少，舅家女儿不易生子，我把这作为鉴戒了。”他的母亲说：“巫臣的妻子杀死三个丈夫，一个国君，一个儿子，灭亡一个国家，使两个卿逃亡了，能够不作为鉴戒吗？我听说：‘很美丽必然有很丑恶的一面。’那个人是郑穆公少妃姚子的女儿，子貉的妹妹，子貉早死，没有后代，而上天把美丽集中在她身上，必然是要用她来大大地败坏事情。从前有仍氏生了一个女儿，头发稠密乌黑而非常美丽，头发的光泽可以照见人影，名叫‘玄妻’。乐官之长后夔娶了她，生下伯封，心地和猪一样，贪婪没有个满足，暴躁乖戾没有限度，人们叫他大猪。有穷后羿灭了他，夔因此而不能得到祭祀。而且夏、商、周三代的被灭亡，公子申生的被废，都是由于美色为害。你娶她做什么呢？有了特别美丽的女人，就完全可以使人改变。如果不是极有道德正义的人娶她，就必然有祸。”叔向害怕，不敢娶了。晋平公强迫叔向娶了她，生了杨食我。杨食我刚生下来，子容的母亲跑去告诉婆婆，说：“大弟媳妇生了个男孩。”叔向的母亲走去看看，走到堂前，听到孩子的哭声就往回走，说：“这是豺狼的声音。豺狼似的男子，必然有野心。不是这个人，没有人会毁掉羊舌氏。”于是就不去看他。
秋季，晋国的韩宣子死了，魏献子执政。把祁氏的土田分割为七个县，把羊舌氏的土田分割为三个县。司马弥牟做邬大夫，贾辛做祁大夫，司马乌做平陵大夫，魏戊做梗阳大夫，知徐吾做涂水大夫，韩固做马首大夫，孟丙做盂大夫，乐霄做铜鞮大夫，赵朝做平阳大夫，僚安做杨氏大夫。认为贾辛、司马乌曾经给王室出过力，所以举拔他们。认为知徐吾、赵朝、韩固、魏戊，是卿的庶子中不失职、能够保守家业的人。另外四个人，都先接受县的职务然后进见魏献子，是由于贤能而加以提拔的。
魏献子对成鱄说：“我把一个县给了戊，别人会以为我是偏袒吗？”成鱄回答说：“哪里会呢？戊的为人，远不忘国君，近不逼同事，处在有利的地位上想到道义，处在困难之中想到保持纯正，有保持礼义之心而没有过度的行动，即使给了他一个县，不也是可以的吗！从前武王战胜商朝，广有天下，他的兄弟领有封国的十五人，姬姓领有封国的四十人，都是举拔自己的亲属。举拔没有别的条件，只要是善的所在，亲密、疏远都是一样的。《诗》说：‘只有这位文王，上帝审度了他的内心，认定了他的美德名声，他的德行在于是非明辨，是非明辨就能为善，就能为人师长做人君王，成为这个大国的君主，能使四方顺服。与文王一样，他的德行，从没有悔恨。既承受了上帝的福佑，还要延及到他的子子孙孙。’内心能制约于道义叫做‘度’，德行端正反应和谐叫做‘莫’，光照四方叫做‘明’，勤于施舍没有私心叫做‘类’，教导别人不知疲倦叫做‘长’，严明赏罚显示威严叫做‘君’，慈祥和顺使别人归服叫做‘顺’，选择好的而跟从叫做‘比’，用天地作经纬叫做‘文’。这九种德行不出过错，做事情就没有悔恨，所以承袭上天的福禄，以利于子子孙孙。现在您的举拔，已经接近文王的德行了，影响会很深远的啊！”
贾辛将要到他的县里去，进见魏献子。魏献子说：“辛，过来！从前叔向到郑国去，鬷蔑氏得丑，想要观察叔向，就跟着收拾器皿的人前去，而站在堂下，说了一句话，说得很好。叔向正要喝酒，听到了鬷蔑的话，说：‘一定是鬷蔑。’走下堂来，拉着他的手上堂，说：‘从前贾大夫长得丑，娶了个妻子却很美，三年不说不笑。贾大夫为她驾着车子去到沼泽地，射野鸡，射中，她才笑着说话。贾大夫说：“才能是不能没有的，我要是不能射箭，你就不说不笑了啊！”现在您的外貌不扬，您如果再不说话，我几乎错过和您见面的机会了。话不能不说，就像这一样。’两个人就像老朋友一样。现在你为王室出了力，我因此举拔你。动身吧！保持着恭敬，不要损毁了你的功劳。”
孔子听到魏献子举拔的事，认为合于道义，说：“举拔近的而不失去亲族，举拔远的而不失去应当举拔的人，可以说是合于道义了。”又听说他命令贾辛的话，认为体现了忠诚，说：“《诗》说，‘永远符合于天命，自己求取各种福禄’，这是忠诚。魏子举拔合于道义，他的命令又体现了忠城，恐怕他的后代会在晋国长享禄位吧！”
冬季，梗阳人有诉讼，魏戊不能判断，把案件上报给魏献子。诉讼一方的大宗把女乐送给魏献子，魏献子准备接受。魏戊对阎没、女宽说：“主人以不接受贿赂名闻于诸侯，如果收下梗阳人的女乐，就没有比这再大的贿赂了。您二位一定要劝谏。”两个人都答应了。退朝以后，在庭院里等待。送饭菜进来，魏献子叫他们二人吃饭。等到摆上饭菜，两个人三次叹气。吃完了，让他们坐下。魏献子说：“我从我伯父、叔父那里听说过：‘只有吃饭的时候忘记忧愁。’您二位在摆上饭菜的时候三次叹气，为什么？”两个人异口同声说：“有人把酒赐给我们两个小人，昨天没有吃晚饭。饭菜刚送到，恐怕不够吃，所以叹气。上菜上了一半，就责备自己说：‘难道将军让我们吃饭会不够吃？’所以再次叹气。等到饭菜上完，愿意把小人的肚子作为君子的内心，刚刚满足就行了。”魏献子辞谢了梗阳人的贿赂。
', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f907d0ac1145496bc6d", "shortContent": "“后妻虐遇前妻之子”，当是从古至今始终存在的社会现象，《后汉书·庞参传》、《晋书·刑法志》等史书甚至有虐遇致死的记载。封建女子未嫁时接受的种种“女诫”，想来是缺乏对这种非常情形的估计；约束已婚女子的“七出”之条虽有“妒忌”一项，却是针对在世的妻妾关系而言。有道是“清官难断家务事”，其实清官是否想得到“断”都成问题，关他的屁事。这样，维护前妻之子的生存权益，便只能是一种社会局部的行为，其措施主要是劝...", "authors": ["穆", "俦"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559211215, '5cef3c4bc8959c00690333c5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643078, '左传 · 昭公 · 昭公二十九年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二十有九年春，公至自乾侯，居于郓，齐侯使高张来唁公。公如晋，次于乾侯。夏四月庚子，叔诣卒。秋七月。冬十月，郓溃。
【传】二十九年春，公至自乾侯，处于郓。齐侯使高张来唁公，称主君。子家子曰：「齐卑君矣，君只辱焉。」公如乾侯。
三月己卯，京师杀召伯盈、尹氏固及原伯鲁之子。尹固之复也，有妇人遇之周郊，尤之，曰：「处则劝人为祸，行则数日而反，是夫也，其过三岁乎？」
夏五月庚寅，王子赵车入于鄻以叛，阴不佞败之。
平子每岁贾马，具从者之衣屦，而归之于乾侯。公执归马者，卖之，乃不归马。卫侯来献其乘马曰启服，堑而死，公将为之椟。子家子曰：「从者病矣，请以食之。」乃以帏裹之。
公赐公衍羔裘，使献龙辅于齐侯，遂入羔裘。齐侯喜，与之阳谷。公衍、公为之生也，其母偕出。公衍先生，公为之母曰：「相与偕出，请相与偕告。」三日，公为生，其母先以告，公为为兄。公私喜于阳谷而思于鲁，曰：「务人为此祸也。且后生而为兄，其诬也久矣。」乃黜之，而以公衍为大子。
秋，龙见于绛郊。魏献子问于蔡墨曰：「吾闻之，虫莫知于龙，以其不生得也。谓之知，信乎？」对曰：「人实不知，非龙实知。古者畜龙，故国有豢龙氏，有御龙氏。」献子曰：「是二氏者，吾亦闻之，而知其故，是何谓也？」对曰：「昔有飂叔安，有裔子曰董父，实甚好龙，能求其耆欲以饮食之，龙多归之。乃扰畜龙，以服事帝舜。帝赐之姓曰董，氏曰豢龙。封诸鬷川，鬷夷氏其后也。故帝舜氏世有畜龙。及有夏孔甲，扰于有帝，帝赐之乘龙，河、汉各二，各有雌雄，孔甲不能食，而未获豢龙氏。有陶唐氏既衰，其后有刘累，学扰龙于豢龙氏，以事孔甲，能饮食之。夏后嘉之，赐氏曰御龙，以更豕韦之后。龙一雌死，潜醢以食夏后。夏后飨之，既而使求之。惧而迁于鲁县，范氏其后也。」献子曰：「今何故无之？」对曰：「夫物，物有其官，官修其方，朝夕思之。一日失职，则死及之。失官不食。官宿其业，其物乃至。若泯弃之，物乃坻伏，郁湮不育。故有五行之官，是谓五官。实列受氏姓，封为上公，祀为贵神。社稷五祀，是尊是奉。木正曰句芒，火正曰祝融，金正曰蓐收，水正曰玄冥，土正曰后土。龙，水物也。水官弃矣，故龙不生得。不然，《周易》有之，在《乾》ⅰⅰ之《姤》ⅰⅳ，曰：『潜龙勿用。』其《同人》ⅰⅵ曰：『见龙在田。』其《大有》ⅵⅰ曰：『飞龙在天。』其《夬》ⅷⅰ曰：『亢龙有悔。』其《坤》ⅱⅱ曰：『见群龙无首，吉。』《坤》之《剥》ⅶⅱ曰：『龙战于野。』若不朝夕见，谁能物之？」献子曰：「社稷五祀，谁氏之五官也？」对曰：「少皞氏有四叔，曰重、曰该、曰修、曰熙，实能金、木及水。使重为句芒，该为蓐收，修及熙为玄冥，世不失职，遂济穷桑，此其三祀也。颛顼氏有子曰犁，为祝融；共工氏有子曰句龙，为后土，此其二祀也。后土为社；稷，田正也。有烈山氏之子曰柱为稷，自夏以上祀之。周弃亦为稷，自商以来祀之。」
冬，晋赵鞅、荀寅帅师城汝滨，遂赋晋国一鼓铁，以铸刑鼎，着范宣子所为刑书焉。仲尼曰：「晋其亡乎！失其度矣。夫晋国将守唐叔之所受法度，以经纬其民，卿大夫以序守之。民是以能尊其贵，贵是以能守其业。贵贱不愆，所谓度也。文公是以作执秩之官，为被庐之法，以为盟主。今弃是度也，而为刑鼎，民在鼎矣，何以尊贵？贵何业之守？贵贱无序，何以为国？且夫宣子之刑，夷之蒐也，晋国之乱制也，若之何以为法？蔡史墨曰：「范氏、中行氏其亡乎！中行寅为下卿，而干上令，擅作刑器，以为国法，是法奸也。又加范氏焉，易之，亡也。其及赵氏，赵孟与焉。然不得已，若德，可以免。」
', '', '', '二十九年春季，鲁昭公从乾侯来到，住在郓地。齐景公派高张来慰问昭公，称他为主君。子家子说：“齐国轻视君王了，君王只得自取耻辱。”昭公就到乾侯去了。
二月十三日，京城里杀了召伯盈、尹氏固和原伯鲁的儿子。尹氏固回去复位的时候，有个女人在成周郊外碰上他，责备他，说：“在国内就怂恿别人惹祸，逃亡出去了又几天就回来，这个人啊，难道能活过三年吗？”
夏季，五月二十五日，王子赵车跑到鄻地而叛变，阴不佞打败了他。
季平子每年买马，准备好随从人员的衣服鞋子，送到乾侯去，昭公逮捕了送马的人，卖掉了马。于是平子就不再送马去了。
卫灵公前来奉献他自己驾车的马，名叫启服，掉进坑里死了。昭公准备把马装进棺材埋起来，子家子说：“随从的人在生病了，请让他们把马吃了吧。”于是就用破帷幕包着马埋了。
昭公把羔羊皮赐给公衍，派他把龙纹的美玉献给齐景公，他就把羔羊皮也一起奉献，齐景公很高兴，给了他阳谷。公衍、公为出生的时候，他们的母亲一起出去住在产房里，公衍先出生。公为的母亲说：“我们一起出来，就一起去报喜。”过了三天，公为出生。公为的母亲先去报告，公为就做了哥哥。昭公心里对得到阳谷很高兴，而又想起鲁国的这段往事，说：“公为惹起了这场祸事。而且出生在后而做哥哥，这欺骗也很久了。”就废了公为，而把公衍作为太子。
秋季，龙出现在绛地郊外，魏献子问蔡墨说：“我听说，虫类没有比龙再聪明的了，因为它不能被人活捉。认为它聪明，是这样吗？”蔡墨说：“实在是人不聪明，不是龙聪明，古代养龙，所以国内有豢龙氏、御龙氏。”献子说：“这两家，我也听说过，但不知道他们的来历，这是说的什么呢？”蔡墨回答说：“过去有飂国的国君叔安，有一个后代叫董父，实在很喜欢龙，能够了解龙的嗜好要求来喂养它们，龙去他那里的很多，于是就驯服饲养龙，用来伺候帝舜。帝舜赐他姓叫董，氏叫豢龙，封他在鬷川，鬷夷氏就是他的后代。所以帝舜氏世世代代有养龙的。到了夏代国君孔甲，顺服天帝，天帝赐给他驾车的龙，黄河、汉水的各两条，各有一雌一雄。孔甲不能饲养，而又没有找到豢龙氏。有陶唐氏已经衰落，后来又有刘累，向豢龙氏学习驯龙，以此事奉孔甲，能够饲养这几条龙。孔甲嘉奖他，赐氏叫御龙，用他代替豕韦的后代。龙中一条雌的死了，刘累偷偷地剁成肉酱给孔甲吃，孔甲吃了，后来又让刘累再找来吃。刘累害怕而迁移到鲁县，范氏就是他的后代。”献子说：“现在为什么没有了？”蔡墨回答说：“事物都有管理它的官吏，官吏修治他的管理方法，早晚都考虑这些事。一旦失职，就要丢掉性命。丢了官就不能吃公家的俸禄。官员世代从事这方面的工作，生物才会来到。如果消灭丢弃它们，生物就自己潜伏，抑郁不能成长。因此有职掌五行的官员，这叫做五官，一代一代继承姓氏，封爵是上公，祭祀是贵神。在土地神、五谷神和五行之神的祭祀中，对他们尊敬崇奉。木官之长叫做句芒，火官之长叫祝融，金官之长叫蓐收，水官之长叫玄冥，土官之长叫后土。龙，是属于水生的生物，水官废弃了，所以龙不能被人活捉。如果不这样，《周易》就有《乾》卦初九《爻辞》说：‘潜伏的龙不被使用’；九二《爻辞》说，‘活着的龙在土田里’；九五《爻辞》说，‘飞舞的龙在天上’；上九《爻辞》说，‘伸直身子的龙有所悔恨’；用九《爻辞》说：‘见到群龙没有首领，吉利’；《坤》卦变成《剥》卦说，‘龙在野外交战’，如果不是早晚都见到，谁能够说出它们的状态？”献子说：“土地神、五谷神庙里的五种祭祀，是哪一代帝王的五官？”蔡墨回答说：“少皞氏有四个叔父，叫重、叫该、叫修、叫熙，能够管理金、木和水。派重做句芒，该做蓐收，修和熙做玄冥。世世代代不失职守，就帮助穷桑氏成功，这是其中的三种祭祀。颛顼氏有个儿子叫犁，做了祝融，共工氏有个儿子叫句龙，做了后土，这是其中的两种祭祀。后土做了土地神。五谷神，是管理土田的官员之长，有烈山氏的儿子叫柱，做了谷神，从夏朝以上祭祀他，周朝的弃也做了五谷神，从商朝以来祭祀他。”
冬季，晋国的赵鞅、荀寅带兵在汝水岸边筑城，于是向晋国的百姓征收了四百八十斤铁，用来铸造刑鼎，在鼎上铸着范宣子所制定的刑书。
孔子说：“晋国恐怕要灭亡了吧！失掉了法度了。晋国应该遵守唐叔传下来的法度，作为百姓的准则，卿大夫按照他们的位次来维护它，百姓才能尊敬贵人，贵人因此能保守他们的家业。贵贱的差别没有错乱，这就是所谓法度。文公因此设立执掌官职位次的官员，在被庐制定法律，以作为盟主。现在废弃这个法令，而铸造了刑鼎，百姓都能看到鼎上的条文，还用什么来尊敬贵人？贵人还有什么家业可保守？贵贱没有次序，还怎么治理国家？而且范宣子的刑书，是在夷地检阅时制定的，是违犯晋国旧礼的乱法，怎么能把它当成法律呢？”蔡史墨说：“范氏、中行氏恐怕要灭亡了吧！中行寅是下卿，但违反上面的命令，擅自铸造刑鼎，以此作为国家的法律，这是违犯法令的罪人，又加上范氏改变被庐制定的法律，这就要灭亡了。恐怕还要牵涉到赵氏，因为赵孟参与了。但赵孟出于不得已，如果修养德行，是可以避免祸患的。”
', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f7703048e64fbda9744", "shortContent": "《洞冥记》要真是郭宪所作，那么这位郭先生造出来的神仙，还不算很彻底，不算是纯而又纯的神仙。\n不彻底么？或曰不然。东方朔是史书上实有的人物，那人虽说言行有些滑稽，常能逗皇上笑，但也不曾有通天彻地的法术，究之原不过一个实实在在的古人。不料，到了郭先生手里，东方先生就大变样了。郭先生不仅给他配了一个两百岁的老子，“考证”出他大名的由来，还让他成为太白金星的后代。于是乎，只见他一会儿紫泥海里走走，一会儿到...", "authors": ["沈维藩"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559211272, '5cef3c85a673f500683ba53e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643079, '左传 · 昭公 · 昭公三十年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三十年春王正月，公在乾侯。夏六月庚辰，晋侯去疾卒。秋八月，葬晋顷公。冬十有二月，吴灭徐，徐子章羽奔楚。
【传】三十年春，王正月，公在乾侯。不先书郓与乾侯，非公，且征过也。
夏六月，晋顷公卒。秋八月，葬。郑游吉吊，且送葬，魏献子使士景伯诘之，曰：「悼公之丧，子西吊，子蟜送葬。今吾子无贰，何故？」对曰：「诸侯所以归晋君，礼也。礼也者，小事大，大字小之谓。事大在共其时命，字小在恤其所无。以敝邑居大国之间，共其职贡，与其备御不虞之患，岂忘共命？先王之制：诸侯之丧，士吊，大夫送葬；唯嘉好、聘享、三军之事，于是乎使卿。晋之丧事，敝邑之间，先君有所助执绋矣。若其不间，虽士大夫有所不获数矣。大国之惠，亦庆其加，而不讨其乏，明厎其情，取备而已，以为礼也。灵王之丧，我先君简公在楚，我先大夫印段实往，敝邑之少卿也。王吏不讨，恤所无也。今大夫曰：『女盍从旧？』旧有丰有省，不知所从。从其丰，则寡君幼弱，是以不共。从其省，则吉在此矣。唯大夫图之。」晋人不能诘。
吴子使徐人执掩余，使钟吾人执烛庸二公子奔楚，楚子大封，而定其徙。使监马尹大心逆吴公子，使居养莠尹然、左司马沈尹戌城之，取于城父与胡田以与之。将以害吴也。子西谏曰：「吴光新得国，而亲其民，视民如子，辛苦同之，将用之也。若好吴边疆，使柔服焉，犹惧其至。吾又疆其仇以重怒之，无乃不可乎！吴，周之胄裔也，而弃在海滨，不与姬通。今而始大，比于诸华。光又甚文，将自同于先王。不知天将以为虐乎，使剪丧吴国而封大异姓乎？其抑亦将卒以祚吴乎？其终不远矣。我盍姑亿吾鬼神，而宁吾族姓，以待其归。将焉用自播扬焉？」王弗听。吴子怒。冬十二月，吴子执钟吴子，遂伐徐，防山以水之。己卯，灭徐。徐子章禹断其发，携其夫人，以逆吴子。吴子唁而送之，使其迩臣从之，遂奔楚。楚沈尹戌帅师救徐，弗及，遂城夷，使徐子处之。
吴子问于伍员曰：「初而言伐楚，余知其可也，而恐其使余往也，又恶人之有馀之功也。今余将自有之矣，伐楚何如？」对曰：「楚执政众而乖，莫适任患。若为三师以肄焉，一师至，彼必皆出。彼出则归，彼归则出，楚必道敝。亟肄以罢之，多方以误之。既罢而后以三军继之，必大克之。」阖庐从之，楚于是乎始病。
', '', '', '三十年春季，周王朝历法的正月，鲁昭公在乾侯。《春秋》以前不记载“公在郓”或“在乾侯”，这是认为昭公不对，而且说明过错所在。
夏季，六月，晋顷公死了。秋季，八月，下葬。郑国的游吉前去吊唁并送葬。魏献子让士景伯质问游吉，说：“悼公的丧事，子西吊唁，子？送葬。现在您只有一个人，是什么缘故？”游吉回答说：“诸侯所以归服晋国国君，这是认为晋国有礼。礼这件事，就是说小国事奉大国，大国爱抚小国。事奉大国在于恭敬地按时执行命令，爱抚小国在于体恤小国的缺乏。由于敝邑处在大国之间，供应它所需的贡品，还要参与战备以防意外，难道能忘了恭敬地执行吊丧送葬的礼节？先王的制度：诸侯的丧事，士吊唁，大夫送葬，只有朝会、聘问、宴享、军事行动才派遣卿。晋国的丧事，当敝邑闲暇无事，先君曾经亲自来送葬。如果不得闲暇，即使是士、大夫有时也难于派遣。大国的恩惠，也会是嘉许敝邑对大国的常礼有所增加，而不责备它的缺乏，明白敝邑的忠诚，只是要求礼仪具备，就可以认为合于礼了。周灵王的丧事，我们先君简公在楚国，我们先大夫印段前去送葬，他还是敝邑的下卿。天子的官吏并没有责备我们，这是由于体恤敝邑的缺乏。现在大夫说：‘你们为什么不按照过去的礼节办？’过去的礼节有隆重有减省，不知道应该按照什么。根据隆重，那么寡君年纪小，因此不能前来。根据减省，那么吉在这里了。请大夫考虑一下！”晋国人不能再质问了。
吴王让徐国人逮捕掩馀，让钟吾人逮捕烛庸，两个公子逃亡到楚国。楚昭王大封土地给他们，并确定他们迁居的地方，派监马尹大心迎接吴国公子，让他们住在养地，派莠尹然、左司马沈尹戌在那里筑城，把城父和胡地的土田给他们，准备用他们危害吴国。子西劝谏楚昭王说：“吴光新近得到国家，亲爱他的百姓，把百姓看成像儿子一样，和百姓同甘共苦，这是准备使用他们了。如果和吴国边境上的人结好，让他们温柔亲服，还恐怕吴军的到来。现在我们又让他们的仇人强大，以加重他们的愤怒，恐怕不可以吧！吴国是周朝的后代，而被抛弃在海边，不能和姬姓各国相往来，现在才开始壮大，可以和中原各国相比，吴光又很有知识，准备使自己和先王一样。不知道上天将要使他暴虐，让他灭亡吴国而使异姓之国扩大土地呢？还是将最终要保佑吴国呢？恐怕它的结果不久可以知道。我们何不姑且安定我们的鬼神，宁静我们的百姓，以等待他的结果，哪里用得着自己辛劳呢？”楚昭王不听子西的谏言。
吴王阖庐发怒。冬季，十二月，吴王逮捕了钟吾子。于是就进攻徐国，堵住山上的水再灌入徐国。二十三日，灭亡徐国。徐国国君章禹剪断头发，带着他夫人迎接吴王。吴王加以慰问后送走了他，让他的近臣跟着，于是就逃亡到楚国。楚国的沈尹戌领兵救徐国，没有赶上。于是就在夷地筑城，让徐国国君住在那里。
吴王问伍员说：“当初你说进攻楚国，我知道能够成功，但恐怕他们派我前去，又不愿意别人占了我的功劳。现在我将要自己占有这份功劳了。进攻楚国怎么样？”伍员回答说：“楚国执政的人多而不和，没有人敢承担责任。如果组织三支部队对楚国来个突然袭击而又迅速撤退，一支部队到那里，他们必然会全军应战。他们出来，我们就退回来；他们回去，我们就出动，楚军必定在路上疲于奔命。屡次突袭快撤使他们疲劳，用各种方法使他们失误。他们疲乏以后再派三军继续进攻，必定大胜他们。”阖庐听从了他的意见，楚国从此就开始困顿疲乏了。
', NULL, '', 'indent', 1559211312, '5cef3cac43e78c00673a8ed4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643080, '左传 · 昭公 · 昭公三十一年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三十有一年春王正月，公在乾侯。季孙意如晋荀跞于适历。夏四月丁巳，薛伯谷卒。晋侯使荀跞唁公于乾侯。秋，葬薛献公。冬，黑肱以滥来奔。十有二月辛亥朔，日有食之。
【传】三十一年春，王正月，公在乾侯，言不能外内也。
晋侯将以师纳公。范献子曰：「若召季孙而不来，则信不臣矣。然后伐之，若何？」晋人召季孙，献子使私焉，曰：「子必来，我受其无咎。」季孙意如会晋荀跞于适历。荀跞曰：「寡君使跞谓吾子：『何故出君？有君不事，周有常刑，子其图之！』」季孙练冠麻衣跣行，伏而对曰：「事君，臣之所不得也，敢逃刑命？君若以臣为有罪，请囚于费，以待君之察也，亦唯君。若以先臣之故，不绝季氏，而赐之死。若弗杀弗亡，君之惠也，死且不朽。若得从君而归，则固臣之愿也。敢有异心？」
夏四月，季孙从知伯如乾侯。子家子曰：「君与之归。一惭之不忍，而终身惭乎？」公曰：「诺。」众曰：「在一言矣，君必逐之。」荀跞以晋侯之命唁公，且曰：「寡君使跞以君命讨于意如，意如不敢逃死，君其入也！」公曰：「君惠顾先君之好，施及亡人将使归粪除宗祧以事君，则不能夫人。己所能见夫人者，有如河！」荀跞掩耳而走，曰：「寡君其罪之恐，敢与知鲁国之难？臣请复于寡君。」退而谓季孙：「君怒未怠，子姑归祭。」子家子曰：「君以一乘入于鲁师，季孙必与君归。」公欲从之，众从者胁公，不得归。
薛伯谷卒，同盟，故书。
秋，吴人侵楚，伐夷，侵潜、六。楚沈尹戌帅师救潜，吴师还。楚师迁潜于南冈而还。吴师围弦。左司马戌、右司马稽帅师救弦，及豫章。吴师还。始用子胥之谋也。
冬，邾黑肱以滥来奔，贱而书名，重地故也。君子曰：「名之不可不慎也如是。夫有所名，而不如其已。以地叛，虽贱，必书地，以名其人。终为不义，弗可灭已。是故君子动则思礼，行则思义，不为利回，不为义疚。或求名而不得，或欲盖而名章，惩不义也。齐豹为卫司寇，守嗣大夫，作而不义，其书为『盗』。邾庶其、莒牟夷、邾黑肱以土地出，求食而已，不求其名，贱而必书。此二物者，所以惩肆而去贪也。若艰难其身，以险危大人，而有名章彻，攻难之士将奔走之。若窃邑叛君，以徼大利而无名，贪冒之民将置力焉。是以《春秋》书齐豹曰『盗』，三叛人名，以惩不义，数恶无礼，其善志也。故曰：《春秋》之称微而显，婉而辨。上之人能使昭明，善人劝焉，淫人惧焉，是以君子贵之。」
十二月辛亥朔，日有食之。是夜也，赵简子梦童子羸而转以歌。旦占诸史墨，曰：「吾梦如是，今而日食，何也？」对曰：「六年及此月也，吴其入郢乎！终亦弗克。入郢，必以庚辰，日月在辰尾。庚午之日，日始有谪。火胜金，故弗克。」', '', '', '', NULL, '', 'indent', 1559211444, '5cef3d18ba39c80068a4bffd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643081, '左传 · 昭公 · 昭公三十二年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三十有二年春王正月，公在乾侯。取阚。夏，吴伐越。秋七月。冬，仲孙何忌会晋韩不信、齐高张、宋仲几、卫世叔申、郑国参、曹人、莒人、薛人、杞人、小邾人城成周。十有二月己未，公薨于乾侯。
【传】三十二年春，王正月，公在乾侯。言不能外内，又不能用其人也。
夏，吴伐越，始用师于越也。史墨曰：「不及四十年，越其有吴乎！越得岁而吴伐之，必受其凶。」
秋八月，王使富辛与石张如晋，请城成周。天子曰：「天降祸于周，俾我兄弟并有乱心，以为伯父忧。我一二亲昵甥舅，不遑启处，于今十年，勤戍五年。余一人无日忘之，闵闵焉如农夫之望岁，惧以待时。伯父若肆大惠，复二文之业，驰周室之忧，徼文、武之福，以固盟主，宣昭令名，则余一人有大愿矣。昔成王合诸侯，城成周，以为东都，崇文德焉。今我欲徼福假灵于成王，修成周之城，俾戍人无勤，诸侯用宁，蝥贼远屏，晋之力也。其委诸伯父，使伯父实重图之。俾我一人无征怨于百姓，而伯父有荣施，先王庸之。」范献子谓魏献子曰：「与其戍周，不如城之。天子实云，虽有后事，晋勿与知可也。从王命以纾诸侯，晋国无忧。是之不务，而又焉从事？」魏献子曰：「善！」使伯音对曰：「天子有命，敢不奉承，以奔告于诸侯。迟速衰序，于是焉在。」
冬十一月，晋魏舒、韩不信如京师，合诸侯之大夫于狄泉，寻盟，且令城成周。魏子南面。卫彪徯曰：「魏子必有大咎。干位以令大事，非其任也。《诗》曰：『敬天之怒，不敢戏豫。敬天之渝，不敢驰驱。』况敢干位以作大事乎？」
己丑，士弥牟营成周，计丈数，揣高卑，度厚薄，仞沟恤，物土方，议远迩，量事期，计徒庸，虑材用，书餱粮，以令役于诸侯，属役赋丈，书以授帅，而效诸刘子。韩简子临之，以为成命。
十二月，公疾，遍赐大夫，大夫不受。赐子家子双琥，一环，一璧，轻服，受之。大夫皆受其赐。己未，公薨。子家子反赐于府人，曰：「吾不敢逆君命也。」大夫皆反其赐。书曰：「公薨于乾侯。」言失其所也。
赵简子问于史墨曰：「季氏出其君，而民服焉，诸侯与之，君死于外，而莫之或罪也。」对曰：「物生有两，有三，有五，有陪贰。故天有三辰，地有五行，体有左右，各有妃耦。王有公，诸侯有卿，皆有贰也。天生季氏，以贰鲁侯，为日久矣。民之服焉，不亦宜乎？鲁君世从其失，季氏世修其勤，民忘君矣。虽死于外，其谁矜之？社稷无常奉，君臣无常位，自古以然。故《诗》曰：『高岸为谷，深谷为陵。』三后之姓，于今为庶，王所知也。在《易》卦，雷乘《乾》曰《大壮》，天之道也。昔成季友，桓之季也，文姜之爱子也，始震而卜。卜人谒之，曰：『生有嘉闻，其名曰友，为公室辅。』及生，如卜人之言，有文在其手曰『友』，遂以名之。既而有大功于鲁，受费以为上卿。至于文子、武子，世增其业，不废旧绩。鲁文公薨，而东门遂杀适立庶，鲁君于是乎失国，政在季氏，于此君也，四公矣。民不知君，何以得国？是以为君，慎器与名，不可以假人。」', '', '', '', NULL, '', 'indent', 1559211476, '5cef3d5130863b006866318e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643082, '左传 · 定公 · 定公元年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】元年春王三月。晋人执宋仲几于京师。夏六月癸亥，公之丧至自乾侯。戊辰，公即位。秋七月癸巳，葬我君昭公。九月，大雩。立炀宫。冬十月，陨霜杀菽。
【传】元年春，王正月辛巳，晋魏舒合诸侯之大夫于狄泉，将以城成周。魏子莅政。卫彪傒曰：「将建天子，而易位以令，非义也。大事奸义，必有大咎。晋不失诸侯，魏子其不免乎！」是行也，魏献子属役于韩简子及原寿过，而田于大陆，焚焉，还，卒于宁。范献子去其柏椁，以其未覆命而田也。
孟懿子会城成周，庚寅，栽。宋仲几不受功，曰：「滕、薛、郳，吾役也。」薛宰曰：「宋为无道，绝我小国于周，以我适楚，故我常从宋。晋文公为践土之盟，曰：『凡我同盟，各复旧职。』若从践土，若从宋，亦唯命。」仲几曰：「践土固然。」薛宰曰：「薛之皇祖奚仲，居薛以为夏车正。奚仲迁于邳，仲虺居薛，以为汤左相。若复旧职，将承王官，何故以役诸侯？」仲几曰：「三代各异物，薛焉得有旧？为宋役，亦其职也。」士弥牟曰：「晋之从政者新，子姑受功。归，吾视诸故府。」仲几曰：「纵子忘之，山川鬼神其忘诸乎？」士伯怒，谓韩简子曰：「薛征于人，宋征于鬼，宋罪大矣。且己无辞而抑我以神，诬我也。启宠纳侮，其此之谓矣。必以仲几为戮。」乃执仲几以归。三月，归诸京师。
城三旬而毕，乃归诸侯之戌。
齐高张后，不从诸侯。晋女叔宽曰：「周苌弘、齐高张皆将不免。苌叔违天，高子违人。天之所坏，不可支也。众之所为，不可奸也。」
夏，叔孙成子逆公之丧于乾侯。季孙曰：「子家子亟言于我，未尝不中吾志也。吾欲与之从政，子必止之，且听命焉。」子家子不见叔孙，易几而哭。叔孙请见子家子，子家子辞，曰：「羁未得见，而从君以出。君不命而薨，羁不敢见。」叔孙使告之曰：「公衍、公为实使群臣不得事君。若公子宋主社稷，则群臣之愿也。凡从君出而可以入者，将唯子是听。子家氏未有后，季孙愿与子从政，此皆季孙之愿也，使不敢以告。」对曰：「若立君，则有卿士、大夫与守龟在，羁弗敢知。若从君者，则貌而出者，入可也；寇而出者，行可也。若羁也，则君知其出也，而未知其入也，羁将逃也。」
丧及坏隤，公子宋先入，从公者皆自坏隤反。
六月癸亥，公之丧至自乾侯。戊辰，公即位。季孙使役如阚公氏，将沟焉。荣驾鹅曰：「生不能事，死又离之，以自旌也。纵子忍之，后必或耻之。」乃止。季孙问于荣驾鹅曰：「吾欲为君谥，使子孙知之。」对曰：「生弗能事，死又恶之，以自信也。将焉用之？」乃止。
秋七月癸巳，葬昭公于墓道南。孔子之为司寇也，沟而合诸墓。
昭公出，故季平子祷于炀公。九月，立炀宫。
周巩简公弃其子弟，而好用远人。
', '', '', '', NULL, '', 'indent', 1559211514, '5cef3d787b968a00768b93a8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643084, '左传 · 定公 · 定公三年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三年春王正月，公如晋，至河，乃复。二月辛卯，邾子穿卒。夏四月。秋，葬邾庄公。冬，仲孙何忌及邾子盟于拔。
【传】三年春二月辛卯，邾子在门台，临廷。阍以瓶水沃廷。邾子望见之，怒。阍曰：「夷射姑旋焉。」命执之，弗得，滋怒。自投于床，废于炉炭，烂，遂卒。先葬以车五乘，殉五人。庄公卞急而好洁，故及是。
秋九月，鲜虞人败晋师于平中，获晋观虎，恃其勇也。
冬，盟于郯，修邾好也。
蔡昭侯为两佩与两裘，以如楚，献一佩一裘于昭王。昭王服之，以享蔡侯。蔡侯亦服其一。子常欲之，弗与，三年止之。唐成公如楚，有两肃爽马，子常欲之，弗与，亦三年止之。唐人或相与谋，请代先从者，许之。饮先从者酒，醉之，窃马而献之子常。子常归唐侯。自拘于司败，曰：「君以弄马之故，隐君身，弃国家，群臣请相夫人以偿马，必如之。」唐侯曰：「寡人之过也，二三子无辱。」皆赏之。蔡人闻之，固请而献佩于子常。子常朝，见蔡侯之徒，命有司曰：「蔡君之久也，官不共也。明日，礼不毕，将死。」蔡侯归，及汉，执玉而沈，曰「余所有济汉而南者，有若大川。」蔡侯如晋，以其子元与其大夫之子为质焉，而请伐楚。', '', '', '三年春季，二月二十九日，邾庄公在门楼上，下临庭院。守门人用瓶装水洒在庭院里。邾庄公远远看见了，发怒。守门人说：“夷射姑曾在这里小便。”邾庄公命令把夷射姑逮捕起来。没有抓到，更加生气，自己从床上跳下来，摔在炉子里的炭火上，皮肉溃烂，就死了，用五辆车陪葬，用五个人殉葬。邾庄公急躁而爱干净，所以才弄到这地步。
秋季，九月，鲜虞人在平中打败晋军，俘虏了晋国的观虎，这是因为他自恃勇敢。
冬季，仲孙何忌和邾子在郯地结盟，这是为重修和邾国的友好。
蔡昭侯制作了两块玉佩和两件皮衣到楚国去，把一块玉佩和一件皮衣献给楚昭王。昭王穿上皮衣带好玉佩，设享礼招待蔡侯。蔡侯也穿带了另外一件皮衣和玉佩。子常想要蔡侯的皮衣和玉佩，蔡侯不给，子常就把蔡侯扣留了三年。唐成公到楚国去，有两匹肃爽马，子常也想要，唐成公不给，子常也把唐成公扣留了三年。唐国有人互相商量，请求代替先跟成公去的人，答应了。让先跟去的人喝酒，灌醉了他们，偷了马献给子常。子常送回了唐侯。偷马的人自己囚禁到了唐国司法官那里，说：“国君由于玩马的缘故，使自身失去自由，抛弃了国家和群臣，臣下们请求帮助养马人赔偿马，一定要像以往两匹马一样的好。”唐侯说：“这是寡人的过错。您几位不要羞辱自己！”对他们全都给予赏赐。蔡国人听说了这件事，坚决请求，而把玉佩献给了子常。子常上朝，见到蔡侯的手下人，就命令官员们说：“蔡侯所以长久留在我国，都是由于你们不供给饯别的礼物。到明天礼物再不完备，就要处死你们。”蔡侯回国，到达汉水，拿起玉丢入汉水中，说：“我要是再渡汉水往南，有大河为证！”蔡侯到晋国去，以他的儿子元和大夫的儿子作为人质，请求进攻楚国。', NULL, '', 'indent', 1559211583, '5cef3dbcba39c80068a4c707', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643085, '左传 · 定公 · 定公四年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】四年春王二月癸巳，陈侯吴卒。三月，公会刘子、晋侯、宋公、蔡侯、卫侯、陈子、郑伯、许男、曹伯、莒子、邾子、顿子、胡子、滕子、薛伯、杞伯、小邾子、齐国夏于召陵，侵楚。夏四月庚辰，蔡公孙姓帅师灭沈，以沈子嘉归，杀之。五月，公及诸侯盟于皋鼬。杞伯成卒于会。六月，葬陈惠公。许迁于容城。秋七月，至自会。刘卷卒。葬杞悼公。楚人围蔡。晋士鞅、卫孔围帅师伐鲜虞。葬刘文公。冬十有一月庚午，蔡侯以吴子及楚人战于柏举，楚师败绩。楚囊瓦出奔郑。庚辰，吴入郢。
【传】四年春三月，刘文公合诸侯于召陵，谋伐楚也。
晋荀寅求货于蔡侯，弗得。言于范献子曰：「国家方危，诸侯方贰，将以袭敌，不亦难乎！水潦方降，疾疟方起，中山不服，弃盟取怨，无损于楚，而失中山，不如辞蔡侯。吾自方城以来，楚未可以得志，只取勤焉。」乃辞蔡侯。
晋人假羽旄于郑，郑人与之。明日，或旆以会。晋于是乎失诸侯。将会，卫子行敬子言于灵公曰：「会同难，啧有烦言，莫之治也。其使祝佗从！」公曰：「善。」乃使子鱼。子鱼辞，曰：「臣展四体，以率旧职，犹惧不给而烦刑书，若又共二，徼大罪也。且夫祝，社稷之常隶也。社稷不动，祝不出竟，官之制也。君以军行，祓社衅鼓，祝奉以从，于是乎出竟。若嘉好之事，君行师从，卿行旅从，臣无事焉。」公曰：「行也。」及皋鼬，将长蔡于卫。卫侯使祝佗私于苌弘曰：「闻诸道路，不知信否。若闻蔡将先卫，信乎？」苌弘曰：「信。蔡叔，康叔之兄也，先卫，不亦可乎？」子鱼曰：「以先王观之，则尚德也。昔武王克商，成王定之，选建明德，以蕃屏周。故周公相王室，以尹天下，于周为睦。分鲁公以大路，大旗，夏后氏之璜，封父之繁弱，殷民六族，条氏、徐氏、萧氏、索氏、长勺氏、尾勺氏。使帅其宗氏，辑其分族，将其类丑，以法则周公，用即命于周。是使之职事于鲁，以昭周公之明德。分之土田倍敦，祝、宗、卜、史，备物、典策，官司、彝器。因商奄之民，命以《伯禽》，而封于少皞之虚。分康叔以大路、少帛、綪茷、旃旌、大吕，殷民七族，陶氏、施氏、繁氏、錡氏、樊氏、饥氏、终葵氏；封畛土略，自武父以南，及圃田之北竟，取于有阎之土，以共王职。取于相土之东都，以会王之东蒐。聃季授土，陶叔授民，命以《康诰》，而封于殷虚。皆启以商政，疆以周索。分唐叔以大路，密须之鼓，阙巩，沽洗，怀姓九宗，职官五正。命以《唐诰》，而封于夏虚，启以夏政，疆以戎索。三者皆叔也，而有令德，故昭之以分物。不然，文、武、成康、之伯犹多，而不获是分也，唯不尚年也。管蔡启商，惎间王室。王于是乎杀管叔而蔡蔡叔，以车七乘，徒七十人。其子蔡仲，改行帅德，周公举之，以为己卿士。见诸王而命之以蔡，其命书云：『王曰：胡！无若尔考之违王命也。』若之何其使蔡先卫也？武王之母弟八人，周公为大宰，康叔为司寇，聃季为司空，五叔无官，岂尚年哉！曹，文之昭也；晋，武之穆也。曹为伯甸，非尚年也。今将尚之，是反先王也。晋文公为践土之盟，卫成公不在，夷叔，其母弟也，犹先蔡。其载书云：『王若曰，晋重、鲁申、卫武、蔡甲午、郑捷、齐潘、宋王臣、莒期。』藏在周府，可覆视也。吾子欲覆文、武之略，而不正其德，将如之何？」苌弘说，告刘子，与范献子谋之，乃长卫侯于盟。
反自召陵，郑子大叔未至而卒。晋赵简子为之临，甚哀，曰：「黄父之会，夫子语我九言，曰：『无始乱，无怙富，无恃宠，无违同，无敖礼，无骄能，无复怒，无谋非德，无犯非义。』」
沈人不会于召陵，晋人使蔡伐之。夏，蔡灭沈。
秋，楚为沈故，围蔡。伍员为吴行人以谋楚。楚之杀郤宛也，伯氏之族出。伯州犁之孙嚭为吴大宰以谋楚。楚自昭王即位，无岁不有吴师。蔡侯因之，以其子乾与其大夫之子为质于吴。
冬，蔡侯、吴子、唐侯伐楚。舍舟于淮汭，自豫章与楚夹汉。左司马戌谓子常曰：「子水公汉而与之上下，我悉方城外以毁其舟，还塞大隧、直辕、冥厄，子济汉而伐之，我自后击之，必大败之。」既谋而行。武城黑谓子常曰：「吴用木也，我用革也，不可久也。不如速战。」史皇谓子常：「楚人恶而好司马，若司马毁吴舟于淮，塞城口而入，是独克吴也。子必速战，不然不免。」乃济汉而陈，自小别至于大别。三战，子常知不可，欲奔。史皇曰：「安求其事，难而逃之，将何所入？子必死之，初罪必尽说。」
十一月庚午，二师陈于柏举。阖庐之弟夫概王，晨请于阖庐曰：「楚瓦不仁，其臣莫有死志，先伐之，其卒必奔。而后大师继之，必克。」弗许。夫概王曰：「所谓『臣义而行，不待命』者，其此之谓也。今日我死，楚可入也。」以其属五千，先击子常之卒。子常之卒奔，楚师乱，吴师大败之。子常奔郑。史皇以其乘广死。吴从楚师，及清发，将击之。夫□王曰：「困兽犹斗，况人乎？若知不免而致死，必败我。若使先济者知免，后者慕之，蔑有斗心矣。半济而后可击也。」从之。又败之。楚人为食，吴人及之，奔。食而从之，败诸雍澨五战及郢。
己卯，楚子取其妹季芈畀我以出，涉睢。针尹固与王同舟，王使执燧象以奔吴师。
庚辰，吴入郢，以班处宫。子山处令尹之宫，夫概王欲攻之，惧而去之，夫□王入之。
左司马戌及息而还，败吴师于雍澨，伤。初，司马臣阖庐，故耻为禽焉。谓其臣曰：「谁能免吾首？」吴句卑曰：「臣贱可乎？」司马曰：「我实失子，可哉！」三战皆伤，曰：「吾不用也已。」句卑布裳，刭而裹之，藏其身而以其首免。楚子涉雎，济江，入于云中。王寝，盗攻之，以戈击王。王孙由于以背受之。中肩。王奔郧，钟建负季芈以从，由于徐苏而从。郧公辛之弟怀将弑王，曰：「平王杀吾父，我杀其子，不亦可乎？」辛曰：「君讨臣，谁敢仇之？君命，天也，若死天命，将谁仇？《诗》曰：『柔亦不茹，刚亦不吐，不侮矜寡，不畏强御。』唯仁者能之。违强陵弱，非勇也。乘人之约，非仁也。灭宗废祀，非孝也。动无令名，非知也。必犯是，余将杀女。」斗辛与其弟巢以王奔随。吴人从之，谓随人曰：「周之子孙在汉川者，楚实尽之。天诱其衷，致罚于楚，而君又窜之。周室何罪？君若顾报周室，施及寡人，以奖天衷，君之惠也。汉阳之田，君实有之。」楚子在公宫之北，吴人在其南。子期似王，逃王，而己为王，曰：「以我与之，王必免。」随人卜与之，不吉。乃辞吴曰：「以随之辟小而密迩于楚，楚实存之，世有盟誓，至于今未改。若难而弃之，何以事君？执事之患，不唯一人。若鸠楚竟，敢不听命。」吴人乃退。鑢金初官于子期氏，实与随人要言。王使见，辞，曰：「不敢以约为利。」王割子期之心，以与随人盟。
初，伍员与申包胥友。其亡也，谓申包胥曰：「我必复楚国。」申包胥曰：「勉之！子能复之，我必能兴之。」及昭王在随，申包胥如秦乞师，曰：「吴为封豕、长蛇，以荐食上国，虐始于楚。寡君失守社稷，越在草莽。使下臣告急，曰：『夷德无厌，若邻于君，疆埸之患也。逮吴之未定，君其取分焉。若楚之遂亡，君之土也。若以君灵抚之，世以事君。』」秦伯使辞焉，曰：「寡人闻命矣。子姑就馆，将图而告。」对曰：「寡君越在草莽，未获所伏。下臣何敢即安？」立，依于庭墙而哭，日夜不绝声，勺饮不入口七日。秦哀公为之赋《无衣》，九顿首而坐，秦师乃出。', '', '', '', NULL, '', 'indent', 1559211615, '5cef3ddb30863b006866384c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643086, '左传 · 定公 · 定公五年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】五年春王三月辛亥朔，日有食之。夏，归粟于蔡。于越入吴。六月丙申，季孙意如卒。秋七月壬子，叔孙不敢卒。冬，晋士鞅帅师围鲜虞。
【传】五年春，王人杀子朝于楚。
夏，归粟于蔡，以周亟，矜无资。
越入吴，吴在楚也。
六月，季平子行东野，还，未至，丙申，卒于房。阳虎将以与璠敛，仲梁怀弗与，曰：「改步改玉。」阳虎欲逐之，告公山不狃。不狃曰：「彼为君也，子何怨焉？」既葬，桓子行东野，及费。子泄为费宰，逆劳于郊，桓子敬之。劳仲梁怀，仲梁怀弗敬。子泄怒，谓阳虎：「子行之乎？」
申包胥以秦师至，秦子蒲、子虎帅车五百乘以救楚。子蒲曰：「吾未知吴道。」使楚人先与吴人战，而自稷会之，大败夫□王于沂。吴人获薳射于柏举，其子帅奔徒以从子西，败吴师于军祥。秋七月，子期、子蒲灭唐。
九月，夫□王归，自立也。以与王战而败，奔楚，为堂溪氏。吴师败楚师于雍澨，秦师又败吴师。吴师居麇，子期将焚之，子西曰：「父兄亲暴骨焉，不能收，又焚之，不可。」子期曰：「国亡矣！死者若有知也，可以歆旧祀，岂惮焚之？」焚之，而又战，吴师败。又战于公婿之溪，吴师大败，吴子乃归。囚闉舆罢，闉舆罢请先，遂逃归。叶公诸梁之弟后臧从其母于吴，不待而归。叶公终不正视。
乙亥，阳虎囚季桓子及公父文伯，而逐仲梁怀。冬十月丁亥，杀公何藐。己丑，盟桓子于稷门之内。庚寅，大诅，逐公父歜及秦遄，皆奔齐。
楚子入于郢。初，斗辛闻吴人之争宫也，曰：「吾闻之：『不让则不和，不和不可以远征。』吴争于楚，必有乱。有乱则必归，焉能定楚？」王之奔随也，将涉于成臼，蓝尹亹涉其帑，不与王舟。及宁，王欲杀之。子西曰：「子常唯思旧怨以败，君何效焉？」王曰：「善。使复其所，吾以志前恶。」王赏斗辛、王孙由于、王孙圉、钟建、斗巢、申包胥、王孙贾、宋木、斗怀。子西曰：「请舍怀也。」王曰：「大德灭小怨，道也。」申包胥曰：「吾为君也，非为身也。君既定矣，又何求？且吾尤子旗，其又为诸？」遂逃赏。王将嫁季芈，季芈辞曰：「所以为女子，远丈夫也。钟建负我矣。」以妻钟建，以为乐尹。
王之在随也，子西为王舆服以保路，国于脾泄。闻王所在，而后从王。王使由于城麇，覆命，子西问高厚焉，弗知。子西曰：「不能，如辞。城不知高厚，小大何知？」对曰：「固辞不能，子使余也。人各有能有不能。王遇盗于云中，余受其戈，其所犹在。」袒而示之背，曰：「此余所能也。脾泄之事，余亦弗能也。」
晋士鞅围鲜虞，报观虎之役也。', '', '', '五年春季，成周人在楚国杀死了王子朝。
夏季，鲁国把粮食送到蔡国，用来救济急难，怜悯他们没有粮食。
越国人进入吴国，这是由于吴国人正侵入楚国。
六月，季平子巡视东野，回来，没有到达，十七日，死在房地。阳虎准备用美玉随葬，仲梁怀不给，说：“步子改变了，美玉也要跟着改变。”阳虎想要赶走他，告诉公山不狃。不狃说：“他是为着国君，您有什么怨恨的呢？”安葬以后，桓子巡视东野，到达费地。子泄做费地宰，在郊外迎接慰劳，桓子对他表示尊敬。慰劳仲梁怀，仲梁怀对他却不表示恭敬。子泄发怒，对阳虎说：“您要把他赶走吗？”
申包胥带着秦军到达，秦国的子蒲、子虎率领战车五百辆以救援楚国。子蒲说：“我不知道吴军的战术。”让楚军先和吴军作战，秦军在稷地和吴军会合，在沂地大败夫概王。吴国人在柏举俘虏了薳射，薳射的儿子率领溃逃的士兵跟随子西，在军祥地方打败了吴军。
秋季，七月，子期、子蒲灭亡唐国。九月，夫槩王回国，自立为王，因为和吴王阖庐作战，被打败，逃亡到楚国，就是后来的棠溪氏。
吴军在雍澨打败楚军，秦军又打败了吴军。吴军驻扎在麇地，子期准备用火攻打吴军，子西说：“父兄亲戚的尸骨暴露在那里，不能收敛又要烧掉，不行。”子期说：“国家将要灭亡了！死去的人如果有知觉，国家复兴他们就可以享有以往的祭祀了，哪里还怕烧掉尸骨？”楚军放火焚烧吴军，又接着进攻，吴军败退，又在公婿之溪作战，吴军大败，吴王就回国去了。吴军俘虏了闉舆罢。闉舆罢请求先行到吴国，就乘机逃回了楚国。叶公诸梁的弟弟后臧与他母亲在吴国，后来后臧抛弃了他的母亲回到楚国。叶公见后臧不仁不孝，就一直不用正眼看他。
九月二十八日，阳虎囚禁了季桓子和公父文伯，并驱逐了仲梁怀。冬季，十月初十日，杀了公何藐。十二日，与桓子在稷门里边盟誓。十三日，举行大的诅咒，驱逐了公父文伯和秦遄，两个人都逃亡到齐国。
楚昭王进入郢都。当初，鬬辛听说吴军将帅争住楚国宫室，说：“我听说：‘不谦让就会不和睦，不和睦就不能远征。’吴国人在楚国争夺，必定会发生动乱，发生动乱，就必定会撤军回国，哪里能平定楚国呢？”
楚昭王逃亡到随国的时候，要在成臼渡河，蓝尹亹用船把他妻子儿子先渡过河，不把船给楚昭王用，等到楚国安定以后，楚昭王要杀他。子西说：“当初子常就因为记挂着过去的怨恨而失败，君王为什么学他呢？”楚昭王说：“好，让蓝尹亹官复原职，我用这件事来记住以往的过失。”楚昭王赏赐鬬辛、王孙由于、王孙圉、钟建、鬬巢、申包胥、王孙贾、宋木、鬬怀。子西说：“请您不要赏赐鬬怀！”楚昭王说：“大德消除了小怨，这是合于正道的。”申包胥说：“我是为了国君，不是为了自己。国君已经安定了，我还追求什么？而且我也恨子旗，难道又要去学子旗贪得无厌吗？”于是申包胥就逃避了楚王的赏赐。楚昭王准备把季羋出嫁，季羋辞谢说：“作为女人，就是要远离男人。可是钟建已经背过我了。”楚昭王把她嫁给钟建，封钟建担任乐尹。
楚昭王在随国的时候，子西仿制了楚昭王的车子和服饰来收集和保护溃散的人，在脾泄建立了国都以此安定人心。听到了楚昭王的下落，然后赶去。楚昭王派王孙由于在麇地筑城，王孙由于回来复命。子西问起城墙的高度厚度，王孙由于不知道。子西说：“你如果干不了，就应当推辞，不知道城墙的高度、厚度和城的大小，那还知道什么？”王孙由于回答说：“我坚决推辞，说干不了，是您让我去做了。人人都有干得了的事，也有干不了的事。君王在云梦泽碰上强盗，我挡住强盗的戈，伤处还在这里！”王孙由于脱去衣服把背部给子西看，说：“这是我干得了的。像在脾泄建立楚王行都的事情，我是干不了的。”
晋国的士鞅包围鲜虞，是为了报复观虎被俘的那次战役。
', NULL, '', 'indent', 1559211657, '5cef3e047b968a00768b99a8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643087, '左传 · 定公 · 定公六年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】六年春王正月癸亥，郑游速帅师灭许，以许男斯归。二月，公侵郑。公至自侵郑。夏，季孙斯、仲孙何忌如晋。秋，晋人执宋行人乐祁犁。冬，城中城。季孙斯、仲孙忌帅师围郓。
【传】六年春，郑灭许，因楚败也。
二月，公侵郑，取匡，为晋讨郑之伐胥靡也。往不假道于卫；及还，阳虎使季、孟自南门入，出自东门，舍于豚泽。卫侯怒，使弥子瑕追之。公叔文子老矣，辇而如公，曰：「尤人而效之，非礼也。昭公之难，君将以文之舒鼎，成之昭兆，定之鞶鉴，苟可以纳之，择用一焉。公子与二三臣之子，诸侯苟忧之，将以为之质。此群臣之所闻也。今将以小忿蒙旧德，无乃不可乎！大姒之子，唯周公、康叔为相睦也。而效小人以弃之，不亦诬乎！天将多阳虎之罪以毙之，君姑待之，若何？」乃止。
夏，季桓子如晋，献郑俘也。阳虎强使孟懿子往报夫人之币。晋人兼享之。孟孙立于房外，谓范献子曰：「阳虎若不能居鲁，而息肩于晋，所不以为中军司马者，有如先君！」献子曰：「寡君有官，将使其人。鞅何知焉？」献子谓简子曰：「鲁人患阳虎矣，孟孙知其衅，以为必适晋，故强为之请，以取入焉。」
四月己丑，吴大子终累败楚舟师，获潘子臣、小惟子及大夫七人。楚国大惕，惧亡。子期又以陵师败于繁扬。令尹子西喜曰：「乃今可为矣。」于是乎迁郢于郤，而改纪其政，以定楚国。
周儋翩率王子朝之徒，因郑人将以作乱于周。郑于是乎伐冯、滑、胥靡、负黍、狐人、阙外。六月，晋阎没戍周，且城胥靡。
秋八月，宋乐祁言于景公曰：「诸侯唯我事晋，今使不往，晋其憾矣。」乐祁告其宰陈寅。陈寅曰：「必使子往。」他日，公谓乐祁曰：「唯寡人说子之言，子必往。」陈寅曰：「子立后而行，吾室亦不亡，唯君亦以我为知难而行也。」见溷而行。赵简子逆，而饮之酒于绵上，献杨楯六十于简子。陈寅曰：「昔吾主范氏，今子主赵氏，又有纳焉。以杨楯贾祸，弗可为也已。然子死晋国，子孙必得志于宋。」范献子言于晋侯曰：「以君命越疆而使，未致使而私饮酒，不敬二君，不可不讨也。」乃执乐祁。
阳虎又盟公及三桓于周社，盟国人于亳社，诅于五父之衢。
冬，十二月，天王处于姑莸，辟儋翩之乱也。', '', '', '', NULL, '', 'indent', 1559211684, '5cef3e21d5de2b00709f8108', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643088, '左传 · 定公 · 定公七年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】七年春王正月。夏四月。秋，齐侯、郑伯盟于咸。齐人执卫行人北宫结以侵卫。齐侯、卫侯盟于沙。大雩。齐国夏帅师伐我西鄙。九月，大雩。冬十月。
【传】七年春二月，周儋翩入于仪栗以叛。
齐人归郓、阳关，阳虎居之以为政。
夏四月，单武公、刘桓公败尹氏于穷谷。
秋，齐侯、郑伯盟于咸，征会于卫。卫侯欲叛晋，诸大夫不可。使北宫结如齐，而私于齐侯曰：「执结以侵我。」齐侯从之，乃盟于琐。
齐国夏伐我。阳虎御季桓子，公敛处父御孟懿子，将宵军齐师。齐师闻之，堕，伏而待之。处父曰：「虎不图祸，而必死。」苫夷曰：「虎陷二子于难，不待有司，余必杀女。」虎惧，乃还，不败。
冬十一月戊午，单子、刘子逆王于庆氏。晋籍秦送王。己巳，王入于王城，馆于公族党氏，而后朝于庄宫。', '', '', '', NULL, '', 'indent', 1559211711, '5cef3e3dc8959c0069034a35', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643089, '左传 · 定公 · 定公八年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】八年春王正月，公侵齐。公至自侵齐。二月，公侵齐。三月，公至自侵齐。曹伯露卒。夏，齐国夏帅师伐我西鄙。公会晋师于瓦。公至自瓦。秋七月戊辰，陈侯柳卒。晋士鞅帅师侵郑，遂侵卫。葬曹靖公。九月，葬陈怀公。季孙斯、仲孙何忌帅师侵卫。冬，卫侯、郑伯盟于曲濮。从祀先公。盗窃宝玉、大弓。
【传】八年春，王正月，公侵齐，门于阳州。士皆坐列，曰：「颜高之弓六钧。」皆取而传观之。阳州人出，颜高夺人弱弓，籍丘子锄击之，与一人俱毙。偃，且射子锄，中颊，殪。颜息射人中眉，退曰：「我无勇，吾志其目也。」师退，冉猛伪伤足而先。其兄会乃呼曰：「猛也殿！」
二月己丑，单子伐谷城，刘子伐仪栗。辛卯，单子伐简城，刘子伐盂，以定王室。
赵鞅言于晋侯曰：「诸侯唯宋事晋，好逆其使，犹惧不至。今又执之，是绝诸侯也。」将归乐祁。士鞅曰：「三年止之，无故而归之，宋必，叛晋。「献子私谓子梁曰：「寡君惧不得事宋君，是以止子。子姑使溷代子。」子梁以告陈寅，陈寅曰：「宋将叛晋是弃溷也，不如侍之。」乐祁归，卒于大行。士鞅曰：「宋必叛，不如止其尸以求成焉。」乃止诸州。
公侵齐，攻廪丘之郛。主人焚冲，或濡马褐以救之，遂毁之。主人出，师奔。阳虎伪不见冉猛者，曰：「猛在此，必败。」猛逐之，顾而无继，伪颠。虎曰：「尽客气也。」苫越生子，将待事而名之。阳州之役获焉，名之曰阳州。
夏，齐国夏、高张伐我西鄙。晋士鞅、赵鞅、荀寅救我。公会晋师于瓦。范献子执羔，赵简子、中行文子皆执雁。鲁于是始尚羔。
晋师将盟卫侯于鄟泽。赵简子曰：「群臣谁敢盟卫君者？」涉佗、成何曰：「我能盟之。」卫人请执牛耳。成何曰：「卫，吾温、原也，焉得视诸侯？」将歃，涉佗捘卫侯之手，及捥。卫侯怒，王孙贾趋进，曰：「盟以信礼也。有如卫君，其敢不唯礼是事，而受此盟也。」
卫侯欲叛晋，而患诸大夫。王孙贾使次于郊，大夫问故。公以晋诟语之，且曰：「寡人辱社稷，其改卜嗣，寡人从焉。」大夫曰：「是卫之祸，岂君之过也？」公曰：「又有患焉。谓寡人『必以而子与大夫之子为质。』」大夫曰：「苟有益也，公子则往。群臣之子，敢不皆负羁绁以从？」将行。王孙贾曰：「苟卫国有难，工商未尝不为患，使皆行而后可。」公以告大夫，乃皆将行之。行有日，公朝国人，使贾问焉，曰：「若卫叛晋，晋五伐我，病何如矣？」皆曰：「五伐我，犹可以能战。」贾曰：「然则如叛之，病而后质焉，何迟之有？」乃叛晋。晋人请改盟，弗许。
秋，晋士鞅会成桓公，侵郑，围虫牢，报伊阙也。遂侵卫。
九月，师侵卫，晋故也。
季寤、公锄极、公山不狃皆不得志于季氏，叔孙辄无宠于叔孙氏，叔仲志不得志于鲁。故五人因阳虎。阳虎欲去三桓，以季寤更季氏，以叔孙辄更叔孙氏，己更孟氏。冬十月，顺祀先公而祈焉。辛卯，禘于僖公。壬辰，将享季氏于蒲圃而杀之，戒都车曰：「癸巳至。」成宰公敛处父告孟孙，曰：「季氏戒都车，何故？」孟孙曰：「吾弗闻。」处父曰：「然则乱也，必及于子，先备诸？」与孟孙以壬辰为期。
阳虎前驱，林楚御桓子，虞人以铍盾夹之，阳越殿，将如蒲圃。桓子咋谓林楚曰：「而先皆季氏之良也，尔以是继之。」对曰：「臣闻命后。阳虎为政，鲁国服焉。违之，征死。死无益于主。」桓子曰：「何后之有？而能以我适孟氏乎？」对曰：「不敢爱死，惧不免主。」桓子曰：「往也。」孟氏选圉人之壮者三百人，以为公期筑室于门外。林楚怒马及衢而骋，阳越射之，不中，筑者阖门。有自门间射阳越，杀之。阳虎劫公与武叔，以伐孟氏。公敛处父帅成人，自上东门入，与阳氏战于南门之内，弗胜。又战于棘下，阳氏败。阳虎说甲如公宫，取宝玉、大弓以出，舍于五父之衢，寝而为食。其徒曰：「追其将至。」虎曰：「鲁人闻余出，喜于征死，何暇追余？」从者曰：」嘻！速驾！公敛阳在。」公敛阳请追之，孟孙弗许。阳欲杀桓子，孟孙惧而归之。子言辨舍爵于季氏之庙而出。阳虎入于欢、阳关以叛。
郑驷歂嗣子大叔为政。', '', '', '八年春季，周王朝历法的正月，鲁定公发兵入侵齐国，攻打阳州的城门。士兵们都排成行列坐着，说：“颜高的硬弓有一百八十斤呢！”大家都拿来传看。阳州人出战，颜高把别人的软弓抢过来准备射箭，籍丘子鉏击打颜高，颜高和另外一个人都被击倒在地上。颜高倒在地上，向子鉏射了一箭，射中他的脸颊，把他射死了。颜息射人射中眉毛，退下来说：“我没有本事，我本来是想射他的眼睛。”军队撤退，冉猛假装脚上受伤而走在前面，他的哥哥冉会就大喊说：“猛啊，到后面去吧！”
三月二十六日，单武公发兵进攻谷城，刘桓公发兵进攻仪栗，三月二十八日，单武公发兵进攻简城，刘桓公发兵进攻盂地，以安定王室。
赵鞅对晋定公说：“诸侯之中惟有宋国事奉晋国，好好迎接他们的使者，还恐怕不来，现在又逮捕了他们的使者，这样将会使自己继绝与诸侯的关系。”准备放回乐祁，士鞅说：“扣留了他三年，无缘无故又把他放回去，宋国必然背叛晋国。”士鞅私下对乐祁说：“寡君害怕不能事奉宋君，因此没有让您回去，您姑且让溷来代替您。”乐祁把话告诉陈寅。陈寅说：“宋国将要背叛晋国，这是丢弃溷，乐祁不如等一下。”乐祁动身回去，死在太行。士鞅说：“宋国必定背叛，不如留下他的尸体来求和。”于是就把尸体留在州地。
鲁定公入侵齐国，攻打廪丘外城。廪丘守将放火焚烧冲城的战车，有人把麻布短衣沾湿了灭火，就攻破了外城。守将出战，鲁军奔逃。阳虎假装没有看见冉猛的样子，说：“冉猛要在这里，一定能打败他们。”冉猛追逐廪丘人，看到后面没有人跟上来，就假装从车上掉下来。阳虎说：“都是言不由衷。”苫越生了儿子，准备等到有了大事再来命名。阳州这一役俘虏了敌人，就把儿子命名为阳州。
夏季，齐国的国夏、高张进攻我国西部边境。晋国的士鞅、赵鞅、荀寅救援我国。鲁国在瓦地会见晋军，士鞅手拿小羔，赵鞅、荀寅都手拿大雁作为礼物。鲁国从这时开始就以羔羊为贵重礼物。
晋军将要和卫灵公在鄟泽结盟，赵简子说：“臣下们有谁敢和卫国国君结盟？”涉佗、成何说：“我们能和他结盟。”卫国人请他们两人执牛耳。成何说：“卫国，不过和我国温地、原地差不多，哪里能和诸侯相比？”将要歃血，涉佗推开卫灵公的手，血顺着淌到手腕上。卫灵公发怒，王孙贾快步走进，说：“结盟是用来伸张礼仪的，就像卫国国君所做的那样，难道敢不奉行礼仪而接受这个盟约？”
卫灵公想要背叛晋国而又担心大夫们反对。王孙贾让卫灵公住在郊外，大夫问什么缘故，卫灵公把所受晋国人的侮辱告诉他们，而且说：“寡人对不起国家，还是改卜其他人作为继承人，寡人愿意服从。”大夫说：“这是卫国的祸患，哪里是君王的过错吗？”卫灵公说：“还有使人担心的事呢，他们对寡人说：‘一定要你的儿子和大夫的儿子作为人质。’”大夫说：“如果有好处，公子就去，臣下们的儿子岂敢不背负着马笼头和马缰绳跟随前去？”将要动身，王孙贾说：“如果卫国有了灾难，工匠商人未尝不是祸患，要让他们全都走了才行。”卫灵公把话告诉大夫，于是就要他们都走。已经定了起程日期，卫灵公让国内的人们朝见，派王孙贾向大家说：“如果卫国背叛晋国，晋国攻打我们五次，会危险到什么程度？”大家都说：“攻打我们五次，还可以有能力作战。”王孙贾说：“那么应当先背叛晋国，发生危险再送人质，还不晚吧？”于是就背叛晋国，晋国人请求重新结盟，卫国人不同意。
秋季，晋国的士鞅会合成桓公侵袭郑国，包围虫牢，以报复伊阙那次战役。于是就乘机侵袭卫国。
九月，鲁军侵袭卫国，这是为了协同于晋国作战的缘故。
季寤，公鉏极、公山不狃在季氏那里不得志，叔孙辄在叔孙氏那里不受宠信，叔孙志在鲁国不得志，所以这五个人依靠阳虎。阳虎想要去掉三桓，用季寤取代季氏，用叔孙辄取代叔孙氏，自己取代孟氏。冬季十月，依即位的先后次序祭祀先公并且祈祷。初二日，在僖公庙里举行大规模祭祀。初三日，准备在蒲圃设享礼招待季氏时而杀死他，命令都邑里的战车部队说：“初四那天都要来。”成地的宰臣公敛处父告诉孟孙说：“季氏命令战车部队，是什么缘故？”孟孙说：“我没有听说过。”处父说：“那么这就是叛乱了，必定会涉及您，是不是先准备一下？”和孟孙约定以初三作为预定日期。
阳虎驱车走在前边，林楚为桓子驾车，警卫军官手持铍、盾在两边夹护，阳越走在最后。将到蒲圃，桓子突然对林楚说：“你的先人都是季氏家里的忠良之臣，你也要以此来继承他们。”林楚说：“下臣听到这话已经迟了。阳虎执政，鲁国人都服从他，违背他就是找死，死了也对主人没有好处。”桓子说：“有什么迟？你能带我去到孟氏那里吗？”林楚回答说：“我不敢爱惜一死，怕的是不能使主人免于祸难。”桓子说：“去吧！”孟氏挑选了三百个健壮奴隶为公期在门外造房子。林楚鞭打乘马，到了大街上就飞跑而去，阳越用箭射他，没有射中，造房子的人关上大门。有人从门缝里用箭射阳越，杀死了他。阳虎劫持鲁定公和武叔以攻打孟氏。公敛处父率领成地人从上东门进入，和阳氏在南门里边作战，没有战胜。又在棘下作战，阳氏战败。阳虎脱去皮甲去到公宫，拿了宝玉、大弓出来，住在五父之衢，自己睡下而让人做饭。他的同伙说：“追赶的人恐怕快来了。”阳虎说：“鲁国人听说我出去了，正高兴可以晚点死了，哪里有空来追我？”跟随的人说：“呀，快点套上马车吧，公敛处父在那里。”公敛处父请求追赶阳虎，孟孙不答应。公敛处父想要杀死季桓子，孟孙害怕，就把季桓子送回家去。季寤在季氏的祖庙里向祖宗一一斟酒祭告然后逃走。阳虎进入讙地、阳关而叛变。
郑国的驷歂继承子太叔执政。', NULL, '', 'indent', 1559211753, '5cef3e6543e78c00673aa242', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643090, '左传 · 定公 · 定公九年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】九年春王正月。夏四月戊申，郑伯虿卒。得宝玉、大弓。六月，葬郑献公。秋，齐侯、卫侯次于五氏。秦伯卒。冬，葬秦哀公。
【传】九年春，宋公使乐大心盟于晋，且逆乐祁之尸。辞，伪有疾。乃使向巢如晋盟，且逆子梁之尸。子明谓桐门右师出，曰：「吾犹衰絰，而子击钟，何也？」右师曰：「丧不在此故也。」既而告人曰：「己衰絰而生子，余何故舍钟？」子明闻之，怒，言于公曰：「右师将不利戴氏，不肯适晋，将作乱也。不然无疾。」乃逐桐门右师。
郑驷歂杀邓析，而用其《竹刑》。君子谓子然：「于是不忠。苟有可以加于国家者，弃其邪可也。《静女》之三章，取彤管焉。《竿旄》『何以告之』，取其忠也。故用其道，不弃其人。《诗》云：『蔽芾甘棠，勿剪勿伐、召伯所茇。』思其人犹爱其树，况用其道而不恤其人乎？子然无以劝能矣。」
夏，阳虎归宝玉、大弓。书曰「得」，器用也。凡获器用曰得，得用焉曰获。
六月，伐阳关。阳虎使焚莱门。师惊，犯之而出，奔齐，请师以伐鲁，曰：「三加必取之。」齐侯将许之。鲍文子谏曰：「臣尝为隶于施氏矣，鲁未可取也。上下犹和，众庶犹睦，能事大国，而无天灾，若之何取之？阳虎欲勤齐师也，齐师罢，大臣必多死亡，己于是乎奋其诈谋。夫阳虎有宠于季氏，而将杀季孙，以不利鲁国，而求容焉。亲富不亲仁，君焉用之？君富于季氏，而大于鲁国，兹阳虎所欲倾覆也。鲁免其疾，而君又收之，无乃害乎！」齐侯执阳虎，将东之。阳虎愿东，乃囚诸西鄙。尽借邑人之车，锲其轴，麻约而归之。载葱灵，寝于其中而逃。追而得之，囚于齐。又以葱灵逃，奔晋，适赵氏。仲尼曰：「赵氏其世有乱乎！」
秋，齐侯伐晋夷仪。敝无存之父将室之，辞，以与其弟，曰：「此役也不死，反，必娶于高、国。」先登，求自门出，死于溜下。东郭书让登，犁弥从之，曰：「子让而左，我让而右，使登者绝而后下。」书左，弥先下。书与王猛息。猛曰：「我先登。」书敛甲，曰：「曩者之难，今又难焉！」猛笑曰：「吾从子如骖之靳。」
晋车千乘在中牟。卫侯将如五氏，卜过之，龟焦。卫侯曰：「可也。卫车当其半，寡人当其半，敌矣。」乃过中牟。中牟人欲伐之，卫褚师圃亡在中牟，曰：「卫虽小，其君在焉，未可胜也。齐师克城而骄，其帅又贱，遇，必败之。不如从齐。」乃伐齐师，败之。齐侯致禚、媚、杏于卫。齐侯赏犁弥，犁弥辞，曰：「有先登者，臣从之，皙帻而衣狸制。」公使视东郭书，曰：「乃夫子也，吾贶子。」公赏东郭书，辞，曰：「彼，宾旅也。」乃赏犁弥。
齐师之在夷仪也，齐侯谓夷仪人曰：「得敝无存者，以五家免。」乃得其尸。公三襚之。与之犀轩与直盖，而先归之。坐引者，以师哭之，亲推之三。', '', '', '', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f872cee9a0c24ee790c", "shortContent": "这是一篇人虎斗智的故事。\n首先是人的艺术征服了老虎。笛师避乱于终南山佛寺之中，于清宵明月之际，援笛而吹。清越嘹亮的乐音，弥漫山谷，虎头人闻声而至，亦凝神听之，居然忘记了吃人。笛师便趁其入睡之机，脱身躲上高树。\n其次是人的智慧战胜了老虎。趁虎头人酣睡而脱身，是笛师智慧的表现之一。虎行速，人行缓，若仓皇逃窜，势必为虎所追及，葬身虎口。于是攀上高树，借浓密的枝叶以遮蔽身体，是笛师智慧的表现之二。凭着人的...", "authors": ["赵山林"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42c6d635634aee3f82df", "shortContent": "这是一则流传很广的民间笑话，令人解颐又发人深省。\n古今中外的禁欲主义者的共同特点，就是极力把男女情爱渲染成十分污秽或有害的事情，让人感到羞恶或恐怖。他们一方面喋喋不休地说教，一方面严设禁令加以防范和惩戒。\n对于人类来说，男女情爱从来就不是单纯的生理问题，而是关系着政治、经济、意识形态与文化传统的复杂的社会问题。中国古代的儒家创始人，原本是不太赞同禁欲主义的，讲究“非礼勿动”的孔夫子也曾无奈地感慨：...", "authors": ["李永祥"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559211780, '5cef3e81ba39c80068a4d0c8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643091, '左传 · 定公 · 定公十年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十年春王三月，乃齐平。夏，公会齐侯于夹谷。公至自夹谷。晋赵鞅帅师围卫。齐人来归郓、欢、龟阴田。叔孙州仇、仲孙何忌帅师围郈。秋，叔孙州仇、仲孙何忌帅师围郈。宋乐大心出奔曹。宋公子地出奔陈。冬，齐侯、卫侯、郑游速会于安甫。叔孙州仇如齐。宋公之弟辰暨仲佗、石彄出奔陈。
【传】十年春，及齐平。
夏，公会齐侯于祝其，实夹谷。孔丘相。犁弥言于齐侯曰：「孔丘知礼而无勇，若使莱人以兵劫鲁侯，必得志焉。」齐侯从之。孔丘以公退，曰：「士，兵之！两君合好，而裔夷之俘以兵乱之，非齐君所以命诸侯也。裔不谋夏，夷不乱华，俘不干盟，兵不逼好。于神为不祥，于德为愆义，于人为失礼，君必不然。」齐侯闻之，遽辟之。
将盟，齐人加于载书曰：「齐师出竟，而不以甲车三百乘从我者，有如此盟。」孔丘使兹无还揖对曰：「而不反我汶阳之田，吾以共命者，亦如之。」齐侯将享公，孔丘谓梁丘据曰：「齐、鲁之故，吾子何不闻焉？事既成矣，而又享之，是勤执事也。且牺象不出门，嘉乐不野合。飨而既具，是弃礼也。若其不具，用秕稗也。用秕稗，君辱，弃礼，名恶，子盍图之？夫享，所以昭德也。不昭，不如其已也。」乃不果享。
齐人来归郓、欢、龟阴之田。
晋赵鞅围卫，报夷仪也。
初，卫侯伐邯郸午于寒氏，城其西北而守之，宵熸。及晋围卫，午以徒七十人门于卫西门，杀人于门中，曰：「请报寒氏之役。」涉佗曰：「夫子则勇矣，然我往，必不敢启门。」亦以徒七十人，旦门焉，步左右，皆至而立，如植。日中不启门，乃退。反役，晋人讨卫之叛故，曰：「由涉佗、成何。」于是执涉佗以求成于卫。卫人不许，晋人遂杀涉佗。成何奔燕。君子曰：「此之谓弃礼，必不钧。《诗》曰：『人而无礼，胡不遄死。』涉佗亦遄矣哉！」
初，叔孙成子欲立武叔，公若藐固谏曰：「不可。」成子立之而卒。公南使贼射之，不能杀。公南为马正，使公若为郈宰。武叔既定，使郈马正侯犯杀公若，不能。其圉人曰：「吾以剑过朝，公若必曰：『谁也剑也？』吾称子以告，必观之。吾伪固，而授之末，则可杀也。」使如之，公若曰：「尔欲吴王我乎？」遂杀公若。侯犯以郈叛，武叔懿子围郈，弗克。
秋，二子及齐师复围郈，弗克。叔孙谓郈工师驷赤曰：「郈非唯叔孙氏之忧，社稷之患也。将若之何？」对曰：「臣之业，在《扬水》卒章之四言矣。」叔孙稽首。驷赤谓侯犯曰：「居齐、鲁之际，而无事，必不可矣。子盍求事于齐以临民？不然，将叛。」侯犯从之。齐使至，驷赤与郈人为之宣言于郈中曰：「侯犯将以郈易于齐，齐人将迁郈民。」众凶惧。驷赤谓侯犯曰：「众言异矣。子不如易于齐，与其死也。犹是郈也，而得纾焉，何必此？齐人欲以此逼鲁，必倍与子地。且盍多舍甲于子之门，以备不虞？」侯犯曰：「诺。」乃多舍甲焉。侯犯请易于齐，齐有司观郈，将至。驷赤使周走呼曰：「齐师至矣！」郈人大骇，介侯犯之门甲，以围侯犯。驷赤将射之。侯犯止之，曰：「谋免我。」侯犯请行，许之。驷赤先如宿，侯犯殿。每出一门，郈人闭之。及郭门，止之，曰：「子以叔孙氏之甲出，有司若诛之，群臣惧死。」驷赤曰：「叔孙氏之甲有物，吾未敢以出。」犯谓驷赤曰：「子止而与之数。」驷赤止，而纳鲁人。侯犯奔齐，齐人乃致郈。
宋公子地嬖蘧富猎，十一分其室，而以其五与之。公子地有白马四。公嬖向魋，魋欲之，公取而朱其尾鬣以与之。地怒，使其徒扶魋而夺之。魋惧，将走。公闭门而泣之，目尽肿。母弟辰曰：「子分室以与猎也，而独卑魋，亦有颇焉。子为君礼，不过出竟，君必止子。」公子地奔陈，公弗止。辰为之请，弗听。辰曰：「是我迋吾兄也。吾以国人出，君谁与处？」冬，母弟辰暨仲佗、石彄出奔陈。
武叔聘于齐，齐侯享之，曰：「子叔孙！若使郈在君之他竟，寡人何知焉？属与敝邑际，故敢助君忧之。」对曰：「非寡君之望也。所以事君，封疆社稷是以。敢以家隶勤君之执事？夫不令之臣，天下之所恶也。君岂以为寡君赐？」', '', '', '十年春季，鲁国和齐国讲和。
夏季，鲁定公在祝其会见齐景公，祝其也就是夹谷。孔丘相礼。犁弥对齐景公说：“孔丘懂得礼而缺乏勇，如果派莱地人用武力劫持鲁侯，一定可以如愿以偿。”齐景公听从了。孔丘领着定公退出，说：“士兵拿起武器攻上去！两国的国君会见友好，而边远的东夷俘虏用武力来捣乱，这不是齐君所以对待诸侯的态度，边远不能图谋中原，东夷不能搅乱华人，俘虏不能侵犯盟会，武力不能逼迫友好，这些对于神明来说是大不吉祥的，对于德行来说是丧失道义的，对于人们来说是丢弃礼仪，君王必定不会这样做。”齐景公听了以后，很快就让莱地人避开。
将要盟誓，齐国人在盟书上加上一句话说：“如果齐军出境，而鲁国不派三百辆甲车跟随我们的话，有盟誓为证！”孔丘让兹无还作揖回答说：“你们不归还我们汶阳的土田，让我们用来供应齐国的需要，也有盟誓为证！”
齐景公准备设享礼招待定公。孔丘对梁丘据说：“齐国、鲁国旧有的典礼，您为什么没有听说过呢？事情已经完成了，而又设享礼，这是麻烦了执事。而且牺尊、象尊不出国门，钟磐不在野外合奏。设享礼而全部具备这些东西，这是不合礼仪的。如果不具备，那就像秕子稗子一样轻微而不郑重。像秕子稗子一样的礼节，这是君王的耻辱。不合礼仪，就名声不好，您何不考虑一下呢！享礼，是用来宣扬德行的。不能宣扬，不如不用。”于是终于没有设享礼。
齐国人前来归还郓地、讙地、龟阳的土地。
晋国的赵鞅包围卫国，这是为了报复夷仪那次战役。
当初，卫侯在寒氏进攻邯郸午，攻破城的西北角而派兵据守。到晚上邯郸午的军队溃散，等到晋国包围卫国，邯郸午带了七十个徒兵进攻卫国西门，在城门里杀了人，说：“用这来报复寒氏那次战役。”涉佗说：“这个人算得是勇敢了，然而我前去，他们一定不敢开门。”也带领士兵七十人，早晨攻打城门，走向城门左右两边，全部站定，像树木一样不动。到中午不开城门，这才退回去。
回兵以后，晋国人责问卫国背叛的原因，卫国人说：“由于涉佗、成何。”晋国人因此逮捕了涉佗，以此向卫国要求讲和。卫国人不答应，晋国人就杀了涉佗。成何逃亡到燕国。君子说：“这叫做不讲礼仪，两个人的罪过必然轻重不同，《诗》说：‘做人而不讲礼仪，为什么不快点死？’涉佗死得也算很快了。”
当初，叔孙成子想要立武叔做继承人，公若藐坚决劝谏说：“不行。”成子还是立了武叔然后死去。公南派坏人用箭暗射公若，没有成功。公南做马正，就让公若做郈地宰臣。武叔在大局已定之后，派郈地的马正侯犯谋杀公若，没有能办到。侯犯的管马人说：“我拿着剑经过朝廷，公若一定会问这剑是谁的。我告诉他是您的，公若一定要细看这剑，我假装不懂礼节而把剑尖递给他，就可以杀死他了。”侯犯就派他照办。公若说：“你要把我当吴王吗？”管马人就杀死了公若。侯犯带领郈地人叛变，武叔包围郈地，没有攻下。
秋季，武叔、公南两个人和齐军再次包围郈地，也没有攻下。武叔对郈地的工匠官驷赤说：“郈地不仅是叔孙氏的忧虑，而且是国家的祸患，将要怎么办？”驷赤说：“下臣的事情在《扬之水》这首诗最后一章的四个字上了。”叔孙向他叩头。驷赤就对侯犯说：“处在齐国、鲁国之间而不事奉哪一国，必定是不行的。您何不请求事奉齐国以统治百姓？不这样，他们将会叛变的。”侯犯听从了他的话。齐国的使者来到，驷赤和郈地人在郈地宣布说：“侯犯准备把郈地和齐国交换，齐国人准备迁走郈地的百姓。”大家都很害怕。驷赤对侯犯说：“大家的意见和您不同，您不如把郈地和齐国人交换。所得到的等于这块郈地，而且可以缓和后患，为什么非死抱着这里不放？齐国人想借此逼迫鲁国，必然加倍给您土地。而且何不多准备一些皮甲，放在门里以防意外？”侯犯说：“对。”于是就多准备些皮甲放在门里。侯犯请求在齐国换一块土地，齐国的官员要求视察郈地。将要到达，驷赤派人遍绕全城喊着说：“齐国的军队到了！”郈地人十分害怕，穿上侯犯准备好的皮甲来包围侯犯。驷赤要射这些人，侯犯阻止他，说：“想办法让我免除祸难。”侯犯请求出走，大家答应了。驷赤先去宿地，侯犯走在最后。每出一道门，郈地人就关上这道门。到了外城门，大家拦住侯犯说：“您带着叔孙氏的皮甲出去，官员们如果因此而要治罪，臣下们害怕被杀。”驷赤说：“叔孙氏的皮甲有标记，我没有敢带出去。”侯犯对驷赤说：“您留下来同他们数数。”驷赤留下，而接纳了鲁国人。侯犯逃亡到齐国。齐国人就把郈地送还给鲁国。
宋国的公子地宠信蘧富猎，把家产分成十一份，给了蘧富猎五份。公子地有四匹白马，宋公宠信向魋，向魋想要这四匹马。宋景公把马牵来，在马尾、马鬣上涂上红颜色给向魋。公子地生气，派手下人打了向魋一顿并且夺回马匹。向魋害怕，准备逃走，宋景公关上门对向魋哭泣，眼睛都哭肿了。宋景公的同母兄弟辰对公子地说：“您把家产分给猎，而惟独看不起魋，这也是不公平的。您平日对国君有礼，至多不过出国，国君必挽留您。”公子地逃亡陈国，宋景公没有挽留他。公子辰为他请求，宋景公不听。公子辰说：“这是我欺骗了我哥哥。我领着国内的人们出国，国君和谁处在一起？”冬季，宋景公同母兄弟辰和仲佗、石彄逃亡到陈国。
武叔到齐国聘问，齐景公设享礼招待他，说：“子叔孙！如果郈地在君王其他的边境上，寡人知道什么呢？这里刚好和敝邑交界，所以敢帮助您分担忧愁。”武叔回答说：“这不是寡君的愿望。我们所以事奉君王，是为了国家疆土的安全，岂敢为了家臣而劳驾君王的执事？不好的臣下，是天下所共同讨厌的，君王难道用这来作为对寡君的赏赐？”', NULL, '', 'indent', 1559211824, '5cef3ead7b968a00768ba086', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643092, '左传 · 定公 · 定公十一年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有一年春，宋公之弟辰及仲佗、石彄、公子地自陈入于萧以叛。夏四月。秋，宋乐大心自曹入于萧。冬，及郑平。叔还如郑莅盟。
【传】十一年春，宋公母弟辰暨仲佗、石彄、公子地入于萧以叛。秋，乐大心从之，大为宋患，宠向魋故也。
冬，及郑平，始叛晋也。
', '', '', '', NULL, '', 'indent', 1559211852, '5cef3ecac8959c006903517a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643093, '左传 · 定公 · 定公十二年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有二年春，薛伯定卒。夏，葬薛襄公。叔孙州仇帅师堕郈。卫公孟彄帅师伐曹。季孙斯、仲孙何忌帅师堕费。秋，大雩。冬十月癸亥，公会齐侯盟于黄。十有一月丙寅朔，日有食之。公至自黄。十有二月，公围成。公至自侯成。
【传】十二年夏，卫公孟彄伐曹，克郊。还，滑罗殿。未出，不退于列。其御曰：「殿而在列，其为无勇乎？」罗曰：「与其素厉，宁为无勇。」
仲由为季氏宰，将堕三都，于是叔孙氏堕郈。季氏将堕费，公山不狃、叔孙辄帅费人以袭鲁。公与三子入于季氏之宫，登武子之台。费人攻之，弗克。入及公侧。仲尼命申句须、乐颀下，伐之，费人北。国人追之，败诸姑蔑。二子奔齐，遂堕费。将堕成，公敛处父谓孟孙：「堕成，齐人必至于北门。且成，孟氏之保障也，无成，是无孟氏也。子伪不知，我将不堕。」
冬十二月，公围成，弗克。', '', '', '十二年夏季，卫国的公孟彄领兵攻打曹国，攻下郊地。军队回国，滑罗走在最后。没有离开曹国，滑罗并不从队伍里退到最后。他的御者说：“殿后而待在队列里，恐怕是缺乏勇气吧！”滑罗说：“与其空有勇猛之名，宁可让人说我没有勇气。”
仲由做季氏的家臣之长，准备毁掉三都，因此叔孙氏毁掉了郈邑。季氏准备毁掉费邑，公山不狃、叔孙辄率领费邑人袭击鲁国国都。鲁定公和季孙等三个人躲进季氏的宫室，登上武子之台。费邑人进攻，没有攻下。费邑人已经攻到了定公的附近。孔子命令申句须、乐颀下台反击，费邑人战败。国内的人们追上去，在姑蔑打败了他们。公山不狃、叔孙辄逃亡齐国，于是就毁掉了费邑。
将要毁掉成邑，公敛处父对孟孙说：“毁掉成邑，齐国人必定可以直抵国境北门。而且成邑是孟氏的保障，没有成邑，这就是没有孟氏。您假装不知道，我不准备毁掉。”
冬季，十二月，定公领兵包围成邑，没有攻下。', NULL, '', 'indent', 1559211895, '5cef3ef430863b006866452c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643094, '左传 · 定公 · 定公十三年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有三年春，齐侯、卫侯次于垂葭。夏，筑蛇渊囿。大蒐于比蒲。卫公孟彄帅师伐曹。晋赵鞅入于晋阳以叛。冬，晋荀寅、士吉射入于朝歌以叛。晋赵鞅归于晋。薛弑其君比。
【传】十三年春，齐侯、卫侯次于垂葭，实狊阜氏。使师伐晋，将济河。诸大夫皆曰：「不可。」邴意兹曰：「可。锐师伐河内，传必数日而后及绛。绛不三月，不能出河，则我既济水矣。」乃伐河内。齐侯皆敛诸大夫之轩，唯邴意兹乘轩。齐侯欲与卫侯乘，与之宴，而驾乘广，载甲焉。使告曰：「晋师至矣！」齐侯曰：「比君之驾也，寡人请摄。」乃介而与之乘，驱之。或告曰：「无晋师。」乃止。
晋赵鞅谓邯郸午曰：「归我卫贡五百家，吾舍诸晋阳。」午许诺。归，告其父兄，父兄皆曰：「不可。卫是以为邯郸，而置诸晋阳，绝卫之道也。不如侵齐而谋之。」乃如之，而归之于晋阳。赵孟怒，召午，而囚诸晋阳。使其从者说剑而入，涉宾不可。乃使告邯郸人曰：「吾私有讨于午也，二三子唯所欲立。」遂杀午。赵稷、涉宾以邯郸叛。夏六月，上军司马籍秦围邯郸。邯郸午，荀寅之甥也；荀寅，范吉射之姻也，而相与睦。故不与围邯郸，将作乱。董安于闻之，告赵孟，曰：「先备诸？」赵孟曰：「晋国有命，始祸者死，为后可也。」安于曰：「与其害于民，宁我独死，请以我说。」赵孟不可。秋七月，范氏、中行氏伐赵氏之宫，赵鞅奔晋阳。晋人围之。范皋夷无宠于范吉射，而欲为乱于范氏。梁婴父嬖于知文子，文子欲以为卿。韩简子与中行文子相恶，魏襄子亦与范昭子相恶。故五子谋，将逐荀寅而以梁婴父代之，逐范吉射而以范皋夷代之。荀跞言于晋侯曰：「君命大臣，始祸者死，载书在河。今三臣始祸，而独逐鞅，刑已不钧矣。请皆逐之。」
冬十一月，荀跞、韩不信、魏曼多奉公以伐范氏、中行氏，弗克。二子将伐公，齐高强曰：「三折肱知为良医。唯伐君为不可，民弗与也。我以伐君在此矣。三家未睦，可尽克也。克之，君将谁与？若先伐君，是使睦也。」弗听，遂伐公。国人助公，二子败，从而伐之。丁未，荀寅、士吉射奔朝歌。
韩、魏以赵氏为请。十二月辛未，赵鞅入于绛，盟于公宫。
初，卫公叔文子朝而请享灵公。退，见史鳅而告之。史鳅曰：「子必祸矣。子富而君贪，其及子乎！」文子曰：「然。吾不先告子，是吾罪也。君既许我矣，其若之何？」史鳅曰：「无害。子臣，可以免。富而能臣，必免于难，上下同之。戍也骄，其亡乎。富而不骄者鲜，吾唯子之见。骄而不亡者，未之有也。戍必与焉。」及文子卒，卫侯始恶于公叔戍，以其富也。公叔戍又将去夫人之党，夫人诉之曰：「戍将为乱。」', '', '', '十三年春季，齐景公、卫灵公住在垂葭，垂葭就是郹氏。派军队进攻晋国，将要渡过黄河，大夫们都说不行，邴意兹说：“可以，用精兵攻打河内，传车一定需要几天才能到达绛邑。绛邑兵马不到三个月不能到达黄河，到那时我军已经回兵渡河了。”于是就进攻河内。
齐景公把大夫们的车子都收起来，只有邴意兹可以坐车。齐景公想和卫灵公同坐一辆车，跟他一起饮宴而命令乘广套车，载上甲兵。派人报告说：“晋军到了！”齐景公说：“等到君王的车子套好，寡人就代您的御者驾车。”于是就披甲和卫灵公一起登年，驱车向前。有人报告说：“没有晋军。”这才把车停下。
晋国的赵鞅对邯郸午说：“把卫国进贡的五百家还给我，我要把他们安置到晋阳去。”邯郸午答应了。回去告诉他的父老兄长。父老兄长都说：“不行。卫国是用这五百家来帮助邯郸午的，要安置在晋阳，这就是断绝和卫国的友好之路。不如用侵袭齐国的办法来解决。”于是就照着父兄的说法办，然后把五百家迁到晋阳。赵鞅发怒，把邯郸午找来，囚禁在晋阳。赵鞅让邯郸午的随从解除佩剑再进来，涉宾不同意。赵鞅就派人告诉邯郸人说：“我私人对午进行惩罚，您几位可以按自己的愿望立继承人。”就杀了邯郸午。赵稷、涉宾领着邯郸人叛变。夏季，六月，上军司马籍秦包围邯郸。邯郸午，是荀寅的外甥；荀寅，是范吉射女婿的父亲，彼此和睦，所以不参与包围邯郸，准备发动叛乱。董安于听到了消息，报告赵鞅说：“先作好准备吗？”赵鞅说：“晋国有一条法令，开始发动祸乱的人处死。我们后发制人就行了。”董安于说：“与其危害百姓，宁可我一个人去死。请用我作为解释。”赵鞅不答应。秋季七月，范氏、中行氏进攻赵氏的宫室，赵鞅逃亡到晋阳，晋国人包围晋阳。
范皋夷不受范吉射的宠信，想要在范氏族中发动叛乱。梁婴父受到知文子的宠信，知文子想让他做卿。韩简子和荀寅互相不和，魏襄子也和范吉射互相不和，所以五个人策划，准备驱逐荀寅而用梁婴父代替他，驱逐范吉射而用范皋夷代替他。荀跞对晋定公说：“君王命令大臣，开始发动祸乱的人处死，盟书沉在黄河里。现在三个大臣开始发动祸乱，而唯独驱逐赵鞅，处罚已经不公正了。请把他们都驱逐。”
冬季，十一月，荀跞、韩不信、魏曼多事奉晋定公而攻打范氏、中行氏，没有攻下。这两个人准备进攻晋定公。齐国的高强说：“久病成良医。唯有攻打国君是不行的。百姓是不赞成的。我正是因为攻打国君才待在这里了啊。三家不和睦，可以全部战胜他们。战胜他们，国君还去倚靠谁？如果先攻打国君，这是促使他们和睦。”两个人不听，于是就攻打晋定公。国内的人们帮助晋定公，两个人战败，三家跟着就去攻打他们。
十八日，荀寅、范吉射逃亡朝歌，韩氏、魏氏替赵氏请求。十二月十二日，赵鞅进入绛邑，在公宫盟誓。
当初，卫国的公孙文子上朝请求设享礼招待卫灵公。退朝，见到史？告诉了他。史？说：“您必然招来祸患了！您富有而国君贪婪，祸患恐怕要到您身上吧！”文子说：“是这样。我没有先告诉您，这是我的罪过。国君已经答应我了，怎么办？”史？说：“没有关系。您谨守臣道，可以免祸。富有而能谨守臣道，一定能免于祸难。无论尊卑都适用这一原则的。戌骄傲，恐怕要逃亡吧！富有而不骄傲的人很少，我只见到您一个。骄傲而不逃亡的人，我还没有见过。戌必定要成为其中一个的。”等到公叔文子死了，卫灵公才开始讨厌公叔戌，因为他富有。公叔戌又准备去掉夫人的党羽，夫人向卫灵公控告说：“戌将要发动叛乱。”', NULL, '', 'indent', 1559211936, '5cef3f1cd5de2b00709f8bd3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643095, '左传 · 定公 · 定公十四年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有四年春，卫公叔戍来奔。卫赵阳出奔宋。二月辛巳，楚公子结、陈公孙佗人帅师灭顿，以顿子牂归。夏，卫北宫结来奔。五月，于越败吴于檇李。吴子光卒。公会齐侯、卫侯于牵。公至自会。秋，齐侯、宋公会于洮。天王使石尚来归脤。卫世子蒯瞶出奔宋。卫公孟彄出奔郑。宋公之弟辰自萧来奔。大蒐于比蒲。邾子来会公。城莒父及霄。
【传】十四年春，卫侯逐公叔戍与其党，故赵阳奔宋，戍来奔。
梁婴父恶董安于，谓知文子曰：「不杀安于，使终为政于赵氏，赵氏必得晋国。盍以其先发难也，讨于赵氏？」文子使告于赵孟曰：「范、中行氏虽信为乱，安于则发之，是安于与谋乱也。晋国有命，始祸者死。二子既伏其罪矣，敢以告。」赵孟患之。安于曰：「我死而晋国宁，赵氏定，将焉用生？人谁不死，吾死莫矣。」乃缢而死。赵孟尸诸市，而告于知氏曰：「主命戮罪人，安于既伏其罪矣，敢以告。」知伯从赵孟盟，而后赵氏定，祀安于于庙。
顿子牂欲事晋，背楚而绝陈好。二月，楚灭顿。
夏，卫北宫结来奔，公叔戍之故也。
吴伐越。越子句践御之，陈于檇李。句践患吴之整也，使死士再禽焉，不动。使罪人三行，属剑于颈，而辞曰：「二君有治，臣奸旗鼓，不敏于君之行前，不敢逃刑，敢归死。」遂自刭也。师属之目，越子因而伐之，大败之。灵姑浮以戈击阖庐，阖庐伤将指，取其一屦。还，卒于陉，去檇李七里。夫差使人立于庭，苟出入，必谓己曰：「夫差！而忘越王之杀而父乎？」则对曰：「唯，不敢忘！」三年，乃报越。
晋人围朝歌，公会齐侯、卫侯于脾、上梁之间，谋救范、中行氏。析成鲋、小王桃甲率狄师以袭晋，战于绛中，不克而还。士鲋奔周，小王桃甲入于朝歌。秋，齐侯、宋公会于洮，范氏故也。
卫侯为夫人南子召宋朝，会于洮。大子蒯聩献盂于齐，过宋野。野人歌之曰：「既定尔娄猪，盍归吾艾豭。」大子羞之，谓戏阳速曰：「从我而朝少君，少君见我，我顾，乃杀之。」速曰：「诺。」乃朝夫人。夫人见大子，大子三顾，速不进。夫人见其色，啼而走，曰：「蒯聩将杀余。」公执其手以登台。大子奔宋，尽逐其党。故公孟彄出奔郑，自郑奔齐。
大子告人曰：「戏阳速祸余。」戏阳速告人曰：「大子则祸余。大子无道，使余杀其母。余不许，将戕于余；若杀夫人，将以余说。余是故许而弗为，以纾余死。谚曰：『民保于信。』吾以信义也。」
冬十二月，晋人败范、中行氏之师于潞，获籍秦、高强。又败郑师及范氏之师于百泉。
', '', '', '', NULL, '', 'indent', 1559211966, '5cef3f3bc8959c00690355be', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643096, '左传 · 定公 · 定公十五年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有五年春王正月，邾子来朝。鼷鼠食郊牛，牛死，改卜牛。二月辛丑，楚子灭胡，以胡子豹归。夏五辛亥，郊。壬申，公薨于高寝。郑罕达帅师伐宋。齐侯、卫侯次于渠蒢。邾子来奔丧。秋七月壬申，姒氏卒。八月庚辰朔，日有食之。九月，滕子来会葬。丁巳，葬我君定公，雨，不克葬。戊午，日下昊，乃克葬。辛巳，葬定姒。冬，城漆。
【传】十五年春，邾隐公来朝。子贡观焉。邾子执玉高，其容仰。公受玉卑，其容俯。子贡曰：「以礼观之，二君者，皆有死亡焉。夫礼，死生存亡之体也。将左右周旋，进退俯仰，于是乎取之；朝祀丧戎，于是乎观之。今正月相朝，而皆不度，心已亡矣。嘉事不体，何以能久？高仰，骄也，卑俯，替也。骄近乱，替近疾。君为主，其先亡乎！」
吴之入楚也，胡子尽俘楚邑之近胡者。楚既定，胡子豹又不事楚，曰：「存亡有命，事楚何为？多取费焉。」二月，楚灭胡。
夏五月壬申，公薨。仲尼曰：「赐不幸言而中，是使赐多言者也。」
郑罕达败宋师于老丘。
齐侯、卫侯次于蘧挐，谋救宋也。
秋七月壬申，姒氏卒。不称夫人，不赴，且不祔也。
葬定公。雨，不克襄事，礼也。
葬定姒。不称小君，不成丧也。
冬，城漆。书，不时告也。', '', '', '', NULL, '', 'indent', 1559211991, '5cef3f54d5de2b00709f8e5c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643097, '左传 · 哀公 · 哀公元年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】元年春王正月，公即位。楚子、陈侯、随侯、许男围蔡。鼷鼠食郊牛，改卜牛。夏四月辛巳，郊。秋，齐侯，卫侯伐晋。冬，仲孙何忌帅师伐邾。
【传】元年春，楚子围蔡，报柏举也。里而栽，广丈，高倍。夫屯昼夜九日，如子西之素。蔡人男女以辨，使疆于江、汝之间而还。蔡于是乎请迁于吴。
吴王夫差败越于夫椒，报檇李也。遂入越。越子以甲楯五千，保于会稽。使大夫种因吴大宰嚭以行成，吴子将许之。伍员曰：「不可。臣闻之树德莫如滋，去疾莫如尽。昔有过浇杀斟灌以伐斟鄩，灭夏后相。后婚方娠，逃出自窦，归于有仍，生少康焉，为仍牧正。惎浇，能戒之。浇使椒求之，逃奔有虞，为之庖正，以除其害。虞思于是妻之以二姚，而邑诸纶。有田一成，有众一旅，能布其德，而兆其谋，以收夏众，抚其官职。使女艾谍浇，使季杼诱豷，遂灭过、戈，复禹之绩。祀夏配天，不失旧物。今吴不如过，而越大于少康，或将丰之，不亦难乎？句践能亲而务施，施不失人，亲不弃劳。与我同壤而世为仇雠，于是乎克而弗取，将又存之，违天而长寇仇，后虽悔之，不可食已。姬之衰也，日可俟也。介在蛮夷，而长寇仇，以是求伯，必不行矣。」弗听。退而告人曰：「越十年生聚，而十年教训，二十年之外，吴其为沼乎！」三月，越及吴平。吴入越，不书，吴不告庆，越不告败也。
夏四月，齐侯、卫侯救邯郸，围五鹿。
吴之入楚也，使召陈怀公。怀公朝国人而问焉，曰：「欲与楚者右，欲与吴者左。陈人从田，无田从党。」逢滑当公而进，曰：「臣闻国之兴也以福，其亡也以祸。今吴未有福，楚未有祸。楚未可弃，吴未可从。而晋，盟主也，若以晋辞吴，若何？」公曰：「国胜君亡，非祸而何？」对曰：「国之有是多矣，何必不复。小国犹复，况大国乎？臣闻国之兴也，视民如伤，是其福也。其亡也，以民为土芥，是其祸也。楚虽无德，亦不艾杀其民。吴日敝于兵，暴骨如莽，而未见德焉。天其或者正训楚也！祸之适吴，其何日之有？」陈侯从之。及夫差克越，乃修先君之怨。秋八月，吴侵陈，修旧怨也。
齐侯、卫侯会于乾侯，救范氏也，师及齐师、卫孔圉、鲜虞人伐晋，取棘蒲。
吴师在陈，楚大夫皆惧，曰：「阖庐惟能用其民，以败我于柏举。今闻其嗣又甚焉，将若之何？」子西曰：「二三子恤不相睦，无患吴矣。昔阖庐食不二味，居不重席，室不崇坛，器不彤镂，宫室不观，舟车不饰，衣服财用，择不取费。在国，天有灾疠，亲巡孤寡，而共其乏困。在军，熟食者分，而后敢食。其所尝者，卒乘与焉。勤恤其民而与之劳逸，是以民不罢劳，死知不旷。吾先大夫子常易之，所以败我也。今闻夫差次有台榭陂池焉，宿有妃嫱嫔御焉。一日之行，所欲必成，玩好必从。珍异是聚，观乐是务，视民如仇，而用之日新。夫先自败也已。安能败我？」
冬十一月，晋赵鞅伐朝歌。', '', '', '元年春季，楚昭王发兵包围蔡国国都，这是为了报复柏举那次战役。离城一里建筑堡垒，宽一丈，高二丈。役夫屯驻九昼夜，和子西的预定计划一样。蔡国人把男女奴隶分别排列捆绑作为礼物出降。楚昭王让蔡国迁移到长江、汝水之间就回去了。蔡国因此向吴国请求迁移到吴国去。
吴王夫差在夫椒打败越军，报复在檇李被越国打败的仇恨。接着，吴军就乘势攻打越国。越王带着披甲持盾的士兵五千人踞守在会稽山，派大夫种通过吴国太宰嚭而向吴国求和。吴王打算答应越国的请求。伍员说：“不行。下臣听说：‘建树德行最好不断增加，除去邪恶最好彻底干净。’从前有过国的国君浇杀了斟灌而攻打斟？，灭亡了夏后相，后缗正怀着孕，从城墙的小洞里逃出去，回到娘家有仍国，生了少康。少康后来在有仍做了管理畜牧的官，对浇满怀仇恨而能警惕戒备。浇派椒寻找少康，少康逃奔到有虞国，做了那里掌管庖厨的长官，才逃避了浇的杀害，虞思因此把两个女儿嫁给了他，封他在纶邑，拥有方圆十里的土田，有五百人的兵力，能广施恩德，并开始实施复国计划。他收集夏朝的余部，安抚他的官员，派遣女艾到浇那里去做间谍，派季杼去引诱浇的弟弟豷。这样就灭亡了过国、戈国，复兴了禹的事业。少康奉祀夏朝的祖先同时祭祀天帝，维护了原有的天下。现在吴国不如过国，而越国大于少康，上天也许将会使越国壮大，如果允许讲和，不也很难了吗？勾践能够亲近别人而注意施行恩惠，施舍皆各得其人。对有功劳的人从不抛弃而加以亲近。越国和我国土地相连，而又世世代代是仇敌。在这种情况下如果我们战胜越国而不灭亡它，又准备保存下去，这是违背了无意而又助长了仇敌，以后即使懊悔，也来不及消除祸患了。姬姓的衰微，为时不远了。我国介于蛮夷之间，而还去助长仇敌的发展，用这样的办法来求取霸业，必定是办不到的。”吴王夫差不听。伍员退下去告诉别人说：“越国用十年时间繁衍积聚，用十年时间教育训练，二十年以后，吴国的宫殿恐怕要成为池沼了。”三月，越国和吴国讲和。
吴国进入越国，《春秋》不加记载，这是由于吴国没有报告胜利，越国没有报告失败。
夏季，四月，齐景公、卫灵公救援邯郸，包围五鹿。
吴国进入楚国的时候，派人召见陈怀公。怀公向国内的人们征求意见，说：“想要亲附楚国的站到右边。想要亲附吴国的站到左边。陈国人有土田的，根据土田的所在而分立左右，没有土田的和亲族站在一起。”逢滑正对着怀公走上前去，说：“下臣听说，国家的兴起由于福德，它的灭亡由于祸殃，现在吴国还没有福德，楚国还没有祸殃，楚国还不能抛弃，吴国还不能跟从。晋国是盟主，如果用晋国作为借口而辞谢吴国，怎么样？”怀公说：“国家被吴国战胜，国君逃亡，这不是祸殃是什么？”逢滑回答说：“国家有这种情况的太多了，为什么一定不能恢复？小国尚且能恢复，何况大国呢？下臣听说，国家的兴起，看待百姓如同受伤者而不加惊动，这就是它的福德。国家的灭亡，把百姓作为粪土草芥，这就是它的祸殃。楚国虽然没有德行，也没有斩杀它的百姓。吴国每天在战争中凋敝，暴露尸骨多得像杂草一样，而又没有见到什么德行。上天恐怕正是在给楚国一次教训吧！吴国遭致祸殃，不会太久了。”陈怀公听从了。等到夫差攻下越国，吴国就重新清算先君时代结下的怨恨。秋季，八月，吴国侵袭陈国，这就是为了重新清算过去的怨恨。
齐景公、卫灵公在乾侯会见，这是为了救援范氏。鲁军和齐军、卫国的孔圉、鲜虞人进攻晋国，占取了棘蒲。
吴军驻在陈国，楚国的大夫们都恐惧，说：“吴王阖庐善于使用他的百姓作战，在柏举把我们打败了。现在听说他的继承人比他还要厉害，我们将对他怎么办？”子西说：“您几位只应当忧虑自己不相和睦，不用害怕吴国的侵袭。从前阖庐吃饭不吃两道菜，坐着不用两层席子，房子不造在高坛上，器用不加红漆和雕刻，宫室之中不造亭台楼阁，车船不加装饰，衣服和用具，取其实用而不尚虚华。在国内，上天降下天灾瘟疫，就亲自巡视，安抚孤寡和资助贫困的人。在军队中，煮熟的食物必须等士兵都得到了，自己才食用，他吃的山珍海味，士兵们都有一份。吴王阖庐经常抚恤百姓而和他们同甘共苦，因此百姓不疲劳，死了也知道不是白白死去。我们的先大夫子常的作法正相反，所以吴国就打败了我国。现在听说夫差住宿有楼台池沼，睡觉有嫔妃宫女，即使是一天在外头，想要的东西一定要到手，玩赏爱好的东西，一定要随身带走；积聚珍奇，享乐为务；把百姓看得如同仇人，没完没了驱使他们。这样做只不过是先自取失败而已，哪里能打败我国呢？”
冬季，十一月，晋国的赵鞅进攻朝歌。', NULL, '', 'indent', 1559212032, '5cef3f7d7b968a00768ba872', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643098, '左传 · 哀公 · 哀公二年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】二年春王二月，季孙斯、叔孙州仇、仲孙何忌帅师伐邾，取漷东田及沂西田。癸巳，叔孙州仇、仲孙何忌及邾子盟于句绎。夏四月丙子，卫侯元卒。滕子来朝。晋赵鞅帅师纳卫世子蒯聩于戚。秋八月甲戌，晋赵鞅帅师及郑罕达帅师战于铁，郑师败绩。冬十月，葬卫灵公。十有一月，蔡迁于州来。蔡杀其大夫公子驷。
【传】二年春，伐邾，将伐绞。邾人爱其土，故赂以淳阜、沂之田而受盟。
初，卫侯游于郊，子南仆。公曰：「余无子，将立女。」不对。他日，又谓之。对曰：「郢不足以辱社稷，君其改图。君夫人在堂，三揖在下。君命只辱。」
夏，卫灵公卒。夫人曰：「命公子郢为大子，君命也。」对曰：「郢异于他子。且君没于吾手，若有之，郢必闻之。且亡人之子辄在。」乃立辄。
六月乙酉，晋赵鞅纳卫大子于戚。宵迷，阳虎曰：「右河而南，必至焉。」使大子絻，八人衰絰，伪自卫逆者。告于门，哭而入，遂居之。
秋八月，齐人输范氏粟，郑子姚、子般送之。士吉射逆之，赵鞅御之，遇于戚。阳虎曰：「吾车少，以兵车之旆，与罕、驷兵车先陈。罕、驷自后随而从之，彼见吾貌，必有惧心。于是乎会之，必大败之。」从之。卜战，龟焦。乐丁曰：「《诗》曰：『爰始爰谋，爰契我龟。』谋协，以故兆询可也。」简子誓曰：「范氏、中行氏，反易天明，斩艾百姓，欲擅晋国而灭其君。寡君恃郑而保焉。今郑为不道，弃君助臣，二三子顺天明，从君命，经德义，除诟耻，在此行也。克敌者，上大夫受县，下大夫受郡，士田十万，庶人工商遂，人臣隶圉免。志父无罪，君实图之。若其有罪，绞缢以戮，桐棺三寸，不设属辟，素车朴马，无入于兆，下卿之罚也。」甲戌，将战，邮无恤御简子，卫太子为右。登铁上，望见郑师众，大子惧，自投于车下。子良授大子绥而乘之，曰：「妇人也。」简子巡列，曰：「毕万，匹夫也。七战皆获，有马百乘，死于牖下。群子勉之，死不在寇。」繁羽御赵罗，宋勇为右。罗无勇，麇之。吏诘之，御对曰：「痁作而伏。」卫大子祷曰：「会孙蒯聩敢昭告皇祖文王、烈祖康叔、文祖襄公：郑胜乱从，晋午在难，不能治乱，使鞅讨之。蒯聩不敢自佚，备持矛焉。敢告无绝筋，无折骨，无面伤，以集大事，无作三祖羞。大命不敢请，佩玉不敢爱。」
郑人击简子中肩，毙于车中，获其峰旗。大子救之以戈，郑师北，获温大夫赵罗。大子复伐之，郑师大败，获齐粟千车。赵孟喜曰：「可矣。」傅叟曰：「虽克郑，犹有知在，忧未艾也。」
初，周人与范氏田，公孙尨税焉。赵氏得而献之，吏请杀之。赵孟曰：「为其主也，何罪？」止而与之田。及铁之战，以徒五百人宵攻郑师，取峰旗于子姚之幕下，献曰：「请报主德。」
追郑师。姚、般、公孙林殿而射，前列多死。赵孟曰：「国无小。」既战，简子曰：「吾伏弢呕血，鼓音不衰，今日我上也。」大子曰：「吾救主于车，退敌于下，我，右之上也。」邮良曰：「我两靷将绝，吾能止之，我，御之上也。」驾而乘材，两靷皆绝。
吴泄庸如蔡纳聘，而稍纳师。师毕入，众知之。蔡侯告大夫，杀公子驷以说，哭而迁墓。冬，蔡迁于州来。', '', '', '二年春季，鲁军攻打邾国，准备先进攻绞地。邾国人爱惜绞地的土地，所以用漷、沂两地的土田作为贿赂，接受盟约。
当初，卫灵公在郊外游玩，公子子南为他驾车。卫灵公说：“我没有嫡子，打算立你做继承人。”子南不回答。过了些时候，卫灵公又对子南那么说，子南回答说：“郢不足以有国家，您还是改变一下主意。君夫人在堂上，卿、大夫、士在下边。您没有和他们商量，我听从了只能是有辱您的命令。”
夏季，卫灵公死了。夫人说：“命令公子郢做太子，这是国君的命令。”公子郢回答说：“郢和别的儿子不一样，而且我伺候国君到死，如果有这话，郢一定会听到。并且还有逃亡者的儿子辄在那里。”于是就立了辄。
六月十七日，晋国的赵鞅把卫国的太子送回戚地。夜里迷了路，阳虎说：“右边到黄河再渡河往南，一定就到了。”让太子脱帽，八个人穿着丧服，假装是从卫国前来迎接的样子。他们通报守门人，号哭入城，于是就住在那里。
秋季，八月，齐国人运送粮食给范氏，郑国的子姚、子般押送。士吉射迎接他们，赵鞅抵御他们，在戚地相遇。阳虎说：“我们的车子少，把大将的旗子插在车上，先与子姚、子般的战车对阵，子姚、子般从后面跟上来，他们看到我军的阵容，必定有恐惧之心。在那时候会合战斗，一定可以把他们打得大败。”赵鞅听从了。占卜战争的吉凶，龟甲烤焦了。乐丁说：“《诗》说：‘先行谋划，于是占卜。’谋划一致，相信过去的卜兆就行了。”赵鞅起誓说：“范氏、中行氏违背天命，斩杀百姓，想要在晋国专权而灭亡国君，我们国君依仗着郑国保护自己，现在郑国无道，抛弃国君帮助臣下，我们几个人顺从天命，服从君令，推行德义，消除耻辱就在这次行动了。战胜敌人的，上大夫可得到县，下大夫可得到郡，士可得到十万亩土田，庶人工商可做官，奴隶可获得自由。志父如果没有罪过，就请国君加以考虑。如果战败有罪，就用绞刑把我诛戮，死后用三寸厚的桐木棺，不要再有衬版和外椁，用没有装饰的马装运棺材，不要葬入本族的墓地中，这是按照下卿的地位所作的处罚。”
八月初七日，将要作战，邮无恤为赵鞅驾御战车，卫国的太子做车右。登上铁丘，远望郑军人数众多，卫太子害怕，自己跳到车下。邮无恤把车上的拉手带子递给太子而让他上车，说：“你像个女人。”赵鞅巡视队伍，说：“毕万是个普通人，七次战斗都俘获了敌人，后来有了四百匹马，在家里善终。诸位努力吧！未必就死在敌人手里。”繁羽为赵罗驾御战车，宋勇做车右。赵罗胆小，别人用绳子把他捆在车上。军吏询问原因，车御回答说：“疟疾发作躺下了。”卫国的太子祷告说：“远孙蒯聩谨敢报告皇祖文王，烈祖康叔，文祖襄公：郑胜搅乱常道，晋午处在危难之中，不能平定祸乱，派赵鞅前来讨伐。蒯聩不敢放纵安逸，居于持矛作战的行列里，谨敢祈祷保佑不要断筋，不要折骨，脸上不要受伤，以成就大事，不给三位祖先带来羞辱。死生的命运不敢请求，佩玉不敢爱惜。”
郑国人击中赵鞅的肩膀，赵鞅倒在车里，郑国人缴获了他的蜂旗。太子用戈救援赵鞅，郑军败逃。俘虏了温大夫赵罗。太子再次进攻，郑军大败，获得了齐国的一千车粮食。赵鞅高兴地说：“行了。”傅傁说：“虽然打败了郑国，还有知氏在那里，忧患还不能消除呢”
当初，周朝人给范氏土田，公孙尨为范氏收税，赵氏抓住了他献给赵鞅。军吏请求把他杀了。赵鞅说：“他是为了主人，有什么罪？”阻止了军吏并且给了公孙尨土田。等到铁丘这一战，公孙尨带领部下五百人夜里进攻郑军，在子姚的帐幕下取得了蜂旗，献上，说：“请允许我以此报答主人的恩德。”
追逐郑军，子姚、子般、公孙林殿后掩护退军并射击追军，前锋部队大多战死，赵鞅说：“对小国也不能轻视。”战斗结束，赵鞅说：“我伏在弓袋上吐了血，但鼓声不衰，今天我的功劳最大。”太子说：“我在车上救了您，在下边追击敌人，我是车右中功劳最大的。”邮无恤说：“我骖马的两根带子快要断了，我还能控制它，我是车御中功劳最大的。”他又驾车装上点木材，两根带子就全断了。
吴国的泄庸到蔡国去致送聘礼，逐渐把军队混进蔡国。等到吴军全部进入，大家才知道这回事。蔡侯告诉大夫，杀了公子驷来取悦吴国，号哭着把先君的坟墓迁走。冬季，蔡国迁到州来。', NULL, '', 'indent', 1559212070, '5cef3fa37b968a00768ba9cc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643099, '左传 · 哀公 · 哀公三年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】三年春，齐国夏、卫石曼姑帅师围戚。夏四月甲午，地震。五月辛卯，桓宫、僖宫灾。季孙斯、叔孙州仇帅师城启阳。宋乐髡帅师伐曹。秋七月丙子，季孙斯卒。蔡人放其大夫公孙猎于吴。冬十月癸卯，秦伯卒。叔孙州仇、仲孙何忌帅师围邾。
【传】三年春，齐、卫围戚，救援于中山。
夏五月辛卯，司铎火。火逾公宫，桓、僖灾。救火者皆曰：「顾府。」南宫敬叔至，命周人出御书，俟于宫，曰：「庀女而不在，死。」子服景伯至，命宰人出礼书，以待命：「命不共，有常刑。」校人乘马，巾车脂辖。百官官备，府库慎守，官人肃给。济濡帷幕，郁攸从之，蒙葺公屋。自大庙始，外内以悛，助所不给。有不用命，则有常刑，无赦。公父文伯至，命校人驾乘车。季桓子至，御公立于象魏之外，命救火者伤人则止，财可为也。命藏《象魏》，曰：「旧章不可亡也。」富父槐至，曰：「无备而官办者，犹拾也。」于是乎去表之蒿，道还公宫。孔子在陈，闻火，曰：「其桓、僖乎！」
刘氏、范氏世为婚姻，苌弘事刘文公，故周与范氏。赵鞅以为讨。六月癸卯，周人杀苌弘。
秋，季孙有疾，命正常曰：「无死。南孺子之子，男也，则以告而立之。女也，则肥也可。」季孙卒，康子即位。既葬，康子在朝。南氏生男，正常载以如朝，告曰：「夫子有遗言，命其圉臣曰：『南氏生男，则以告于君与大夫而立之。』今生矣，男也，敢告。」遂奔卫。康子请退。公使共刘视之，则或杀之矣，乃讨之。召正常，正常不反。
冬十月，晋赵鞅围朝歌，师于其南。荀寅伐其郛，使其徒自北门入，己犯师而出。癸丑，奔邯郸。十一月，赵鞅杀士皋夷，恶范氏也。', '', '', '三年春季，齐国、卫国包围戚地，戚地人向中山请求救援。
夏季，五月二十八日，鲁国司铎官署发生火灾。火势越过公宫，桓公庙、僖公庙都被烧毁。救火的人都说：“照顾府库财物。”南宫敬叔来到，命令周人拿出国君所看的书，让他在宫里等着，说：“交给你了，如有损失，就处死你。”子服景伯来到，命令宰人拿出礼书，让他等候命令。如果不能尽职，就要按规定处罚。校人驾上马，巾车在车轴上涂上油脂，百官坚守自己的岗位，府库加强戒备，官人认真执行供应，用透湿的帷幕覆盖火场附近的建筑物，救火的器材就放在旁边。然后又用浸湿的东西把公屋覆盖起来，从太庙开始，由外到内依次覆盖。帮助力量不足的。有不听从命令的，就按规定处罚，不加赦免。公父文伯来到，命令校人为公车套上马。季桓子来到，为哀公驾车站在象魏外边，命令救火的人受伤就停下来，因为财物是可以生产出来的。又命令把文献收藏起来，说：“旧的章典不能丢失。”富父槐来到，说：“没有准备而叫百官仓促办事，就好像拾起地上的汤水。”因此就拆去火道上的干枯易燃物品，围绕公宫四周开辟火巷隔火。
孔子正在陈国，听到发生火灾，说：“恐怕是桓公庙、僖公庙吧！”
刘氏、范氏世世代代互通婚姻，苌弘事奉刘文公，所以周朝亲近范氏。赵鞅因此而讨伐。六月十一日，周人杀死了苌弘。
秋季，季孙有病，命令正常说：“不要跟随我死！如果南孺子生下的孩子是男孩，就把我的话报告国君、大夫而立这个孩子为继承人；如果是个女孩，那么立肥就可以了。”季孙死，康子即位。安葬刚刚完毕，康子正在朝廷上。南氏生了个男孩，正常用车把男孩载着送到朝廷上，报告说：“他老人家有遗言，命令他的贱臣说：‘南氏生了男孩，就报告国君和大夫而立他为继承人。’现在继承人生下来了，是个男孩，谨此报告。”于是就逃亡到卫国去。康子请求退位，哀公派共刘去巡察，有人却已经把婴儿杀死了。于是就讨伐杀人凶手。召见正常，正常不回来。
冬季，十月，晋国的赵鞅包围朝歌，军队驻扎在朝歌南边。荀寅攻打朝歌外城，让他的部下从北门进来，自己突围出来。二十三日，荀寅逃亡到邯郸。
十一月，赵鞅杀死了士皋夷，这是由于讨厌范氏。
', NULL, '', 'indent', 1559212110, '5cef3fcb30863b0068664dcd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643100, '左传 · 哀公 · 哀公四年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】四年春王二月庚戌，盗杀蔡侯申。蔡公孙辰出奔吴。葬秦惠公。宋人执小邾子。夏，蔡杀其大夫公孙姓、公孙霍。晋人执戎蛮子赤归于楚。城西郛。六月辛丑，亳社灾。秋八月甲寅，滕子结卒。冬十有二月，葬蔡昭公。葬滕顷公。
【传】四年春，蔡昭侯将如吴，诸大夫恐其又迁也，承，公孙翩逐而射之，入于家人而卒。以两矢门之。众莫敢进。文之锴后至，曰：「如墙而进，多而杀二人。」锴执弓而先，翩射之，中肘。锴遂杀之。故逐公孙辰，而杀公孙姓、公孙盱。
夏，楚人既克夷虎，乃谋北方。左司马眅、申公寿余、叶公诸梁致蔡于负函，致方城之外于缯关，曰：「吴将水斥江入郢，将奔命焉。」为一昔之期，袭梁及霍。单浮余围蛮氏，蛮氏溃。蛮子赤奔晋阴地。司马起丰、析与狄戎，以临上雒。左师军於菟和，右师军于仓野，使谓阴地之命大夫士蔑曰：「晋、楚有盟，好恶同之。若将不废，寡君之愿也。不然，将通于少习以听命。」士蔑请诸赵孟。赵孟曰：「晋国未宁，安能恶于楚，必速与之。」士蔑乃致九州之戎。将裂田以与蛮子而城之，且将为之卜。蛮子听卜，遂执之，与其五大夫，以畀楚师于三户。司马致邑，立宗焉，以诱其遗民，而尽俘以归。
秋七月，齐陈乞、弦施、卫宁跪救范氏。庚午，围五鹿。九月，赵鞅围邯郸。冬十一月，邯郸降。荀寅奔鲜虞，赵稷奔临。十二月，弦施逆之，遂堕临。国夏伐晋，取邢、任、栾、鄗、逆畤、阴人、盂、壶口。会鲜虞，纳荀寅于柏人。', '', '', '四年春季，蔡昭公准备到吴国去。大夫们恐怕他又要迁移，跟着公孙翩追赶蔡昭公并用箭射他，蔡昭公逃进百姓家里就死了。公孙翩拿着两支箭守在门口，大家不敢进去。文之锴后到，说：“并排像一垛墙一样往前走，至多只能杀死我们两个人。”文之锴拿着弓走在前面，公孙翩射他，射中肘部。文之锴就杀死了公孙翩，并因此驱逐了公孙辰而杀死了公孙姓、公孙盱。
夏季，楚国人攻下夷虎以后，就策划向北方扩张。左司马眅、申公寿馀、叶公诸梁在负函集合蔡国人，方城山外的人在缯关集合，说：“吴国将要溯江而上进入郢都，大家都要奔走听命。”规定一晚上的期限，袭击梁地和霍地。单浮馀领兵包围蛮氏，蛮氏溃散。蛮子赤逃亡到晋国的阴地。司马征召丰地兵卒、析地人和狄戎入伍当兵，逼近上洛。左翼部队驻扎在菟和，右翼部队驻扎在仓野，派人对阴地的命大夫士蔑说：“晋国和楚国有过盟约，喜爱和厌恶彼此相共。如果这个盟约不废除，这是寡君的愿望。不这样，我们准备打通少习山再来听取你们的命令。”士蔑请示赵孟，赵孟说：“晋国没有安定，哪里能和楚国搞坏关系？一定要快点把人交给他们！”士蔑就召集九州之戎，说将要分给蛮子土田而在那里筑城，而且准备为这件事情占卜。蛮子前来听取占卜，就逮捕了他和他的五个大夫，在三户交给楚军。司马假装给蛮子城邑和建立宗主，来引诱分散的戎人，然后全部俘虏回去。
秋季，七月，齐国的陈乞、弦施、卫国的宁跪救援范氏。十四日，包围五鹿。九月，赵鞅包围邯郸。冬季，十一月，邯郸投降。荀寅逃亡到鲜虞，赵稷逃奔到临地。十二月，弦施迎接赵稷，就拆毁了临地的城墙。国夏攻打晋国，占取了邢地、任地、栾地、鄗地、逆畤、阴人、盂地、壶口，会合鲜虞，把荀寅送到柏人邑。', NULL, '', 'indent', 1559212162, '5cef3fffd5de2b00709f94f1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643101, '左传 · 哀公 · 哀公五年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】五年春，城毗。夏，齐侯伐宋。晋赵鞅帅师伐卫。秋九月癸酉，齐侯杵臼卒。冬，叔还如齐。闰月，葬齐景公。
【传】五年春，晋围柏人，荀寅、士吉射奔齐。初，范氏之臣王生恶张柳朔，言诸昭子，使为柏人。昭子曰：「夫非而仇乎？」对曰：「私仇不及公，好不废过，恶不去善，义之经也。臣敢违之？」及范氏出，张柳朔谓其子：「尔从主，勉之！我将止死，王生授我矣。吾不可以僭之。」遂死于柏人。
夏，赵鞅伐卫，范氏之故也，遂围中牟。
齐燕姬生子，不成而死，诸子鬻姒之子荼嬖。诸大夫恐其为大子也，言于公曰：「君之齿长矣，未有大子，若之何？」公曰：「二三子间于忧虞，则有疾疢。亦姑谋乐，何忧于无君？」公疾，使国惠子、高昭子立荼，置群公子于莱。秋，齐景公卒。冬十月，公子嘉、公子驹、公子黔奔卫，公子锄、公子阳生来奔。莱人歌之曰：「景公死乎不与埋，三军之事乎不与谋。师乎师乎，何党之乎？」
郑驷秦富而侈，嬖大夫也，而常陈卿之车服于其庭。郑人恶而杀之。子思曰：「《诗》曰：『不解于位，民之攸塈。』不守其位，而能久者鲜矣。《商颂》曰：『不僭不滥，不敢怠皇，命以多福。』」', '', '', '五年春季，晋国包围柏人，荀寅、士吉射逃奔到齐国。
当初，范氏的家臣王生讨厌张柳朔，向范昭子建议，让张柳朔去做柏人地方长官。昭子说：“这个人不是你的仇人吗？”王生回答说：“私仇不能危害公事，喜爱不能废弃过错，厌恶不能排除善良，这是道义的常规，我岂敢违背它？”等到范氏离开柏人，张柳朔对他儿子说：“你跟随主人，努力吧！我准备留下来死守，王生把死难的大节交给了我，我不能对他不讲信用。”于是就战死在柏人。
夏季，赵鞅进攻卫国，这是为了帮助范氏的缘故，并乘机包围中牟。
齐国的燕姬生了个儿子，未成年就死了。但是诸子鬻姒所生的儿子荼受到宠爱。大夫们恐怕荼被立为太子，就对齐景公说：“您的年纪大了，还没有太子，怎么办？”齐景公说：“您这几位如有忧虑，就会生出疾病，姑且去寻欢作乐，何必担心没有国君？”齐景公生病，让国惠子、高昭子立荼为太子，把公子们安置在莱地。秋季，齐景公死去。冬季十月，公子嘉、公子驹、公子黔逃亡到卫国，公子鉏，公子阳生逃亡到鲁国来。莱地人歌唱说：“景公死了啊不参加埋葬，三军的大事啊不参加商量，众人啊众人，又要前往何方？”
郑国的驷秦富有而奢侈，是一个下大夫，但常常把卿的车马服饰陈列在他的院子里。郑国人讨厌他而把他杀了。子思说：“《诗》说：‘努力不懈在职位上，百姓所以才得以安宁。’不安于他的职位而能够保持长久的是很少的。《商颂》说：‘不出差错不自满，不敢懈怠不偷闲，上天赐予各种福禄。’”', NULL, '', 'indent', 1559212236, '5cef4049ba39c80068a4e231', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643102, '左传 · 哀公 · 哀公六年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】六年春，城邾瑕。晋赵鞅帅师伐鲜虞。吴伐陈。夏，齐国夏及高张来奔。叔还公吴于柤。秋七月庚寅，楚子轸卒。齐阳生入齐。齐陈乞弑其君荼。冬，仲孙何忌帅师伐邾。宋向巢帅师伐曹。
【传】六年春，晋伐鲜虞，治范氏之乱也。
吴伐陈，复修旧怨也。楚子曰：「吾先君与陈有盟，不可以不救。」乃救陈，师于城父。
齐陈乞伪事高、国者，每朝必骖乘焉。所从必言诸大夫，曰：「彼皆偃蹇，将弃子之命。皆曰：『高、国得君，必逼我，盍去诸？』固将谋子，子早图之。图之，莫如尽灭之。需，事之下也。」及朝，则曰：「彼虎狼也，见我在子之侧，杀我无日矣。请就之位。」又谓诸大夫曰：「二子者祸矣！恃得君而欲谋二三子，曰：『国之多难，贵宠之由，尽去之而后君定。』既成谋矣，盍及其未作也，先诸？作而后悔，亦无及也。」大夫从之。
夏六月戊辰，陈乞、鲍牧及诸大夫，以甲入于公宫。昭子闻之，与惠子乘如公，战于庄，败。国人追之，国夏奔莒，遂及高张、晏圉、弦施来奔。
秋七月，楚子在城父，将救陈。卜战，不吉；卜退，不吉。王曰：「然则死也！再败楚师，不如死。弃盟逃仇，亦不如死。死一也，其死仇乎！」命公子申为王，不可；则命公子结，亦不可；则命公子启，五辞而后许。将战，王有疾。庚寅，昭王攻大冥，卒于城父。子闾退，曰：「君王舍其子而让，群臣敢忘君乎？从君之命，顺也。立君之子，亦顺也。二顺不可失也。」与子西、子期谋，潜师闭涂，逆越女之子章，立之而后还。
是岁也，有云如众赤鸟，夹日以飞，三日。楚子使问诸周大史。周大史曰：「其当王身乎！若禜之，可移于令尹、司马。」王曰：「除腹心之疾，而置诸股肱，何益？不谷不有大过，天其夭诸？有罪受罚，又焉移之？」遂弗禜。
初，昭王有疾。卜曰：「河为祟。」王弗祭。大夫请祭诸郊，王曰：「三代命祀，祭不越望。江、汉、雎、章，楚之望也。祸福之至，不是过也。不谷虽不德，河非所获罪也。」遂弗祭。孔子曰：「楚昭王知大道矣！其不失国也，宜哉！《夏书》曰：『惟彼陶唐，帅彼天常，有此冀方。今失其行，乱其纪纲，乃灭而亡。』又曰：『允出兹在兹。』由己率常可矣。」
八月，齐邴意兹来奔。
陈僖子使召公子阳生。阳生驾而见南郭且于，曰：「尝献马于季孙，不入于上乘，故又献此，请与子乘之。」出莱门而告之故。阚止知之，先待诸外。公子曰：「事未可知，反，与壬也处。」戒之，遂行。逮夜，至于齐，国人知之。僖子使子士之母养之，与馈者皆入。
冬十月丁卯，立之。将盟，鲍子醉而往。其臣差车鲍点曰：「此谁之命也？」陈子曰：「受命于鲍子。」遂诬鲍子曰：「子之命也。」鲍子曰：「女忘君之为孺子牛而折其齿乎？而背之也！」悼公稽首，曰：「吾子奉义而行者也。若我可，不必亡一大夫。若我不可，不必亡一公子。义则进，否则退，敢不唯子是从？废兴无以乱，则所愿也。」鲍子曰：「谁非君之子？」乃受盟。使胡姬以安孺子如赖。去鬻姒，杀王甲，拘江说，囚王豹于句窦之丘。
公使朱毛告于陈子，曰：「微子则不及此。然君异于器，不可以二。器二不匮，君二多难，敢布诸大夫。」僖子不对而泣，曰：「君举不信群臣乎？以齐国之困，困又有忧。少君不可以访，是以求长君，庶亦能容群臣乎！不然，夫孺子何罪？」毛覆命，公悔之。毛曰：「君大访于陈子，而图其小可也。」使毛迁孺子于骀，不至，杀诸野幕之下，葬诸殳冒淳。', '', '', '', '[{"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42ad911759740c9cb01d", "shortContent": "此篇采自夏庭芝所作的《青楼集》。\n王巧儿是元代大都的歌妓，后嫁给画家倪瓒的朋友陈云峤。故事叙述王巧儿容貌佳丽，能歌善舞，闻名京城。她和陈云峤相交萌生知遇的情感，愿意相从做妾。岂料鸨母从中作梗，想留住她来赚钱。幸亏她主意已定，在陈云峤的帮助下，跳出火坑，实现了自己的愿望。\n故事虽短，但情节紧凑，人物形象生动感人。王巧儿是故事着力塑造的妇女形象。她沦落风尘，虽名闻京师，内心却渴望着早日过上正常人的生活...", "authors": ["徐时仪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559212266, '5cef406730863b0068665416', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643103, '左传 · 哀公 · 哀公七年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】七年春，宋皇瑗帅师侵郑。晋魏曼多帅师侵卫。夏，公会吴于鄫。秋，公伐邾。八月己酉，入邾，以邾子益来。宋人围曹。冬，郑驷弘帅师救曹。
【传】七年春，宋师侵郑，郑叛晋故也。
晋师侵卫，卫不服也。
夏，公会吴于鄫。吴来征百牢，子服景伯对曰：「先王未之有也。」吴人曰：「宋百牢我，鲁不可以后宋。且鲁牢晋大夫过十，吴王百牢，不亦可乎？」景伯曰：「晋范鞅贪而弃礼，以大国惧敝邑，故敝邑十一牢之。君若以礼命于诸侯，则有数矣。若亦弃礼，则有淫者矣。周之王也，制礼，上物不过十二，以为天之大数也。今弃周礼，而曰必百牢，亦唯执事。」吴人弗听。景伯曰：「吴将亡矣！弃天而背本不与，必弃疾于我。」乃与之。
大宰嚭召季康子，康子使子贡辞。大宰嚭曰：「国君道长，而大夫不出门，此何礼也？」对曰：「岂以为礼？畏大国也。大国不以礼命于诸侯，苟不以礼，岂可量也？寡君既共命焉，其老岂敢弃其国？大伯端委以治周礼，仲雍嗣之，断发文身，赢以为饰，岂礼也哉？有由然也。」反自鄫，以吴为无能为也。
季康子欲伐邾，乃飨大夫以谋之。子服景伯曰：「小所以事大，信也。大所以保小，仁也。背大国，不信。伐小国，不仁。民保于城，城保于德，失二德者，危，将焉保？」孟孙曰：「二三子以为何如？恶贤而逆之？」对曰：「禹合诸侯于涂山，执玉帛者万国。今其存者，无数十焉。唯大不字小，小不事大也。知必危，何故不言？鲁德如邾，而以众加之，可乎？」不乐而出。
秋，伐邾，及范门，犹闻钟声。大夫谏，不听，茅成子请告于吴，不许，曰：「鲁击柝闻于邾，吴二千里，不三月不至，何及于我？且国内岂不足？」成子以茅叛，师遂入邾，处其公宫，众师昼掠，邾众保于绎。师宵掠，以邾子益来，献于亳社，囚诸负瑕。负瑕故有绎。邾茅夷鸿以束帛乘韦，自请救于吴，曰：「鲁弱晋而远吴，冯恃其众，而背君之盟，辟君之执事，以陵我小国。邾非敢自爱也，惧君威之不立。君威之不立，小国之忧也。若夏盟于鄫衍，秋而背之，成求而不违，四方诸侯，其何以事君？且鲁赋八百乘，君之贰也。邾赋六百乘，君之私也。以私奉贰，唯君图之。」吴子从之。
宋人围曹。郑桓子思曰：「宋人有曹，郑之患也。不可以不救。」冬，郑师救曹，侵宋。
初，曹人或梦众君子立于社宫，而谋亡曹，曹叔振铎请待公孙强，许之。旦而求之曹，无之。戒其子曰：「我死，尔闻公孙强为政，必去之。」及曹伯阳即位，好田弋。曹鄙人公孙强好弋，获白雁，献之，且言田弋之说，说之。因访政事，大说之。有宠，使为司城以听政。梦者之子乃行。强言霸说于曹伯，曹伯从之，乃背晋而奸宋。宋人伐之，晋人不救。筑五邑于其郊，曰黍丘、揖丘、大城、钟、邗。', '', '', '七年春季，宋军入侵郑国，这是因为郑国背叛晋国的缘故。
晋军入侵卫国，这是因为卫国不顺服。
夏季，鲁哀公和吴国人在鄫地会见。吴国前来要求取牛、羊、猪一百头为享宴品。子服景伯回答说：“先王没有过这样的事。”吴国人说：“宋国享我们以牛羊猪各一百头，鲁国不能落在宋国之后。而且鲁国享宴晋国大夫超过各十头，给吴王各一百头，不也是可以的吗？”子服景伯说：“晋国的范鞅贪婪而抛弃礼仪，用大国的势力来迫使敝邑恐惧，所以敝邑享他以牛羊猪各十一头。君王如果用礼仪来命令诸侯，那么就有一定的数字。如果也抛弃礼仪，那么就太过分了。周朝统一天下，制定礼仪，上等的物品数字不过十二，因为这是上天的大数。现在抛弃周礼，而说一定要太牢一百，也只好听从执事的命令。”吴国人不听，子服景伯说：“吴国快要灭亡了，抛弃上天而违背根本。如果不给，一定要加害于我们。”于是就照数给了他们。
太宰嚭召见季康子，康子让子贡去辞谢。太宰嚭说：“国君走了那么远的路程，而大夫不出门，这是什么礼仪？”子贡回答说：“岂敢把这作为礼仪，只是由于害怕大国。大国不用礼仪来命令诸侯，如果不用礼仪，其后果小国就不能估计了。寡君即已奉命前来，他的老臣岂敢丢下国家？太伯穿着玄端的衣服戴着委貌的帽子来推行周礼，仲雍继承他，把头发剪断，身上刺上花纹，作为裸体的装饰，难道合于礼吗？因为有原因所以才这样做的。”从鄫地回来，季康子认为吴国没有能力做出什么事来的。
季康子想要攻打邾国，就设享礼招待大夫们来一起商量。子服景伯说：“小国用来事奉大国的，是信；大国用来保护小国的，是仁。违背大国，这是不信，攻打小国，这是不仁。百姓由城邑来保护，城邑由德行来保护。丢掉了信和仁两种德行，就危险了，还能保护什么？”孟孙说：“各位以为怎么样？哪一种意见好我就采纳。”大夫们回答说：“大禹在涂山会合诸侯，拿着玉帛的有一万个国家。现在还存在的，没有几十个了，就是因为大国不养育小国，小国不事奉大国。明知必有危险，为什么不说？鲁国的德行和邾国一样，而要用大兵来施加压力，行吗？”不欢而散。
秋季，鲁国攻打邾国，到达范门，还能听到乐钟的声音。大夫劝谏，邾子不听。茅成子请求向吴国报告，邾子不答应，说：“鲁国敲打梆子的声音，在邾国可以听到，吴国相距二千里，没有三个月到不了，哪里能管得了我们？而且国内的力量难道就不足够？”茅成子领着茅地人叛变了，鲁国的军队就攻进了邾国国都，住在邾子的宫内，各军白天抢劫。邾国的军队在绎山守卫。鲁军在夜里抢劫，带了邾子益回来，把他奉献于亳社，囚禁在负瑕，负瑕因此而有了绎山人。
邾国的茅夷鸿带了五匹帛四张熟牛皮自己去请求吴国救援，说：“鲁国以为晋国衰弱而吴国遥远，倚仗着他们人多，而背弃了和君王订立的盟约，看不起君王的执事，来欺凌我们小国。邾国不敢自己爱惜，惧怕的是君王的威信不能建立。君王的威信不能建立，这是小国所担心的。如果夏天在鄫衍结盟，秋天就背弃它，鲁国得到了所求而没有阻力，四方的诸侯还用什么来事奉君王？而且鲁国拥有战车八百辆是君王的对手，邾国战车六百辆却是君王的部属。把部属去送给对手，请君考虑一下！”吴王听从了茅夷鸿的话。
宋国人包围曹国，郑国的桓子思说：“宋国人如果据有曹国，这是郑国的忧患，不能不救。”郑军救援曹国，入侵宋国。
当初，曹国有人梦见一伙君子站在国社墙外，商量灭亡曹国。曹叔振铎请求等待公孙彊，众君子答应了。早晨起来去寻找，曹国没有这个人。做梦的人告诫他儿子说：“我死以后，你听说公孙彊执政，一定要离开曹国。”
等到曹伯阳即位，喜欢打猎射鸟，曹国边境上的人公孙彊喜欢射鸟，得到一只白雁，献给曹伯阳，还讲述了打猎射鸟的技巧，曹伯很喜欢他。由此而向公孙彊询问国家大事，他应对得体，曹伯阳更加喜欢他，加以宠信，让他担任司城执掌国政。做梦的人的儿子这时就离开曹国。
公孙彊向曹伯讲述称霸的策略，曹伯阳听从了，就背弃晋国而侵犯宋国。宋国人攻打曹国，晋国人不去救援，公孙彊在国都郊外建造了五个城邑，名叫黍丘、揖丘、大城、钟、邘。

', NULL, '', 'indent', 1559212316, '5cef4099a673f500683bcece', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643104, '左传 · 哀公 · 哀公八年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】八年春王正月，宋公入曹，以曹伯阳归。吴伐我。夏，齐人取讙及阐。归邾子益子邾。秋七月。冬十有二月癸亥，杞伯过卒。齐人归讙及阐。
【传】八年春，宋公伐曹，将还，褚师子肥殿。曹人诟之，不行，师待之。公闻之，怒，命反之，遂灭曹。执曹伯及司城强以归，杀之。
吴为邾故，将伐鲁，问于叔孙辄。叔孙辄对曰：「鲁有名而无情，伐之，必得志焉。」退而告公山不狃。公山不狃曰：「非礼也。君子违，不适仇国。未臣而有伐之，奔命焉，死之可也。所托也则隐。且夫人之行也，不以所恶废乡。今子以小恶而欲覆宗国，不亦难乎？若使子率，子必辞，王将使我。」子张疾之。王问于子泄，对曰：「鲁虽无与立，必有与毙；诸侯将救之，未可以得志焉。晋与齐、楚辅之，是四仇也。夫鲁、齐、晋之唇，唇亡齿寒，君所知也。不救何为？」
三月，吴伐我，子泄率，故道险，从武城。初，武城人或有因于吴竟田焉，拘鄫谒之沤菅者，曰：「何故使吾水滋？」及吴师至，拘者道之，以伐武城，克之。王犯尝为之宰，澹枱子羽之父好焉。国人惧，懿子谓景伯：「若之何？」对曰：「吴师来，斯与之战，何患焉？且召之而至，又何求焉？」吴师克东阳而进，舍于五梧，明日，舍于蚕室。公宾庚、公甲叔子与战于夷，获叔子与析朱锄。献于王，王曰：「此同车，必使能，国未可望也。」明日，舍于庚宗，遂次于泗上。微虎欲宵攻王舍，私属徒七百人，三踊于幕庭，卒三百人，有若与焉，及稷门之内。或谓季孙曰：「不足以害吴，而多杀国士，不如已也。」乃止之。吴子闻之，一夕三迁。吴人行成，将盟。景伯曰：「楚人围宋，易子而食，析骸而爨，犹无城下之盟。我未及亏，而有城下之盟，是弃国也。吴轻而远，不能久，将归Ｖ请少待之。」弗从。景伯负载，造于莱门，乃请释子服何于吴，吴人许之。以王子姑曹当之，而后止。吴人盟而还。
齐悼公之来也，季康子以其妹妻之，即位而逆之。季鲂侯通焉，女言其情，弗敢与也。齐侯怒，夏五月，齐鲍牧帅师伐我，取讙及阐。
或谮胡姬于齐侯，曰：「安孺子之党也。」六月，齐侯杀胡姬。
齐侯使如吴请师，将以伐我，乃归邾子。邾子又无道，吴子使大宰子余讨之，囚诸楼台，栫之以棘。使诸大夫奉大子革以为政。
秋，及齐平。九月，臧宾如如齐莅盟，齐闾丘明来莅盟，且逆季姬以归，嬖。
鲍牧又谓群公子曰：「使女有马千乘乎？」公子愬之。公谓鲍子：「或谮子，子姑居于潞以察之。若有之，则分室以行。若无之，则反子之所。」出门，使以三分之一行。半道，使以二乘。及潞，麇之以入，遂杀之。
冬十二月，齐人归讙及阐，季姬嬖故也。', '', '', '', NULL, '', 'indent', 1559212344, '5cef40b5c8959c00690364ed', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643105, '左传 · 哀公 · 哀公九年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】九年春王二月，葬杞僖公。宋皇瑗帅师取郑师于雍丘。夏，楚人伐陈。秋，宋公伐郑。冬十月。
【传】九年春，齐侯使公孟绰辞师于吴。吴子曰：「昔岁寡人闻命。今又革之，不知所从，将进受命于君。」
郑武子剩之嬖许瑕求邑，无以与之。请外取，许之。故围宋雍丘。宋皇瑗围郑师，每日迁舍，垒合，郑师哭。子姚救之，大败。二月甲戌，宋取郑师于雍丘，使有能者无死，以郏张与郑罗归。
夏，楚人伐陈，陈即吴故也。
宋公伐郑。
秋，吴城邗，沟通江、淮。
晋赵鞅卜救郑，遇水适火，占诸史赵、史墨、史龟。史龟曰：「是谓渖阳，可以兴兵。利以伐姜，不利子商。伐齐则可，敌宋不吉。」史墨曰：「盈，水名也。子，水位也。名位敌，不可干也。炎帝为火师，姜姓其后也。水胜火，伐姜则可。」史赵曰：「是谓如川之满，不可游也。郑方有罪，不可救也。救郑则不吉，不知其他。」阳虎以《周易》筮之，遇《泰》ⅱⅰ之《需》ⅴⅰ，曰：「宋方吉，不可与也。微子启，帝乙之元子也。宋、郑，甥舅也。祉，禄也。若帝乙之元子归妹，而有吉禄，我安得吉焉？」乃止。
冬，吴子使来人敬师伐齐。
', '', '', '九年春季，齐悼公派公孟绰到吴国辞谢出兵。吴王说：“去年我听到君王的命令，现在又改变了，不知道该听从什么，我准备到贵国去接受君王的命令。”
郑国武子賸的宠臣许瑕求取封邑，没有地方可以封给他了。许瑕请求取之于外国，武子賸答应，所以包围了宋国的雍丘。宋国的皇瑗又包围郑军，每天挖沟修筑堡垒，连成一线。郑国军士都号啕大哭，武子賸前去救援，大败。二月十四日，宋军在雍丘全歼郑军，让有才能的人留下性命，带了郏张和郑罗回去。
夏季，楚国人进攻陈国，这是因为陈国投向吴国的缘故。
宋景公发兵攻打郑国。
秋季，吴国在邗地筑城，穿沟贯通长江、淮水。
晋国的赵鞅为救援郑国而占卜，得到水流向火的卦象，向史赵、史墨、史龟询问卦象的吉凶。史龟说：“这叫做阳气下沉，可以发兵，利于攻打姜氏，不利于攻打子商。攻打齐国就可以，攻打宋国就不吉利。”史墨说：“盈，是水泊名称。子，是水的方位。名称方位相当，不能触犯，炎帝是火师，姜姓是他的后代。水胜火，攻打姜姓就可以。”史赵说：“这卦叫做像河水涨满，不能游泳；郑国正有罪，不能救，救援郑国就不吉利，其他的不知道。”阳虎用《周易》占筮，得到《泰》卦变成《需》卦，说：“宋国正在吉利的时候，不能以他为敌。微子启，是帝乙的大儿子。宋国和郑国，是舅舅和外甥。福祉，是爵禄。如果帝乙的大儿子嫁女儿而又有吉利的爵禄，我们哪里能够吉利？”于是晋国就不去救援郑国。
冬季，吴王派人来鲁国通知出兵攻打齐国。', NULL, '', 'indent', 1559212383, '5cef40dcc8959c006903663b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643106, '左传 · 哀公 · 哀公十年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十年春王二月，邾子益来奔。公会吴伐齐。三月戊戌，齐侯阳生卒。夏，宋人伐郑。晋赵鞅帅师侵齐。五月，公至自伐齐。葬齐悼公。卫公孟彄自齐归于卫。薛伯夷卒。秋，葬薛惠公。冬，楚公子结帅师伐陈。吴救陈。
【传】十年春，邾隐公来奔。齐甥也，故遂奔齐。
公会吴子、邾子、郯子伐齐南鄙，师于鄎。齐人弑悼公，赴于师。吴子三日哭于军门之外。徐承帅舟师，将自海入齐，齐人败之，吴师乃还。
夏，赵鞅帅师伐齐，大夫请卜之。赵孟曰：「吾卜于此起兵，事不再令，卜不袭吉，行也。」于是乎取犁及辕，毁高唐之郭，侵及赖而还。
秋，吴子使来复人】敬师。
冬，楚子期伐陈。吴延州来季子救陈，谓子期曰：「二君不务德，而力争诸侯，民何罪焉？我请退，以为子名，务德而安民。」乃还。', '', '', '', NULL, '', 'indent', 1559212416, '5cef40feba39c80068a4e9c1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643107, '左传 · 哀公 · 哀公十一年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有一年春，齐国书帅师伐我。夏，陈辕颇出奔郑。五月，公会吴伐齐。甲戌，齐国书帅师及吴战于艾陵，齐师败绩，获齐国书。秋七月辛酉，滕子虞母卒。冬十有一月，葬滕隐公。卫世叔齐出奔宋。
【传】十一年春，齐为鄎故，国书、高无丕帅师伐我，及清。季孙谓其宰冉求曰：「齐师在清，必鲁故也。若之何？」求曰：「一子守，二子从公御诸竟。」季孙曰：「不能。」求曰：「居封疆之间。」季孙告二子，二子不可。求曰：「若不可，则君无出。一子帅师，背城而战。不属者，非鲁人也。鲁之群室，众于齐之兵车。一室敌车，优矣。子何患焉？二子之不欲战也宜，政在季氏。当子之身，齐人伐鲁而不能战，子之耻也。大不列于诸侯矣。」季孙使从于朝，俟于党氏之沟。武叔呼而问战焉，对曰：「君子有远虑，小人何知？」懿子强问之，对曰：「小人虑材而言，量力而共者也。」武叔曰：「是谓我不成丈夫也。」退而蒐乘，孟孺子泄帅右师，颜羽御，邴泄为右。冉求帅左师，管周父御，樊迟为右。季孙曰：「须也弱。」有子曰：「就用命焉。」季氏之甲七千，冉有以武城人三百为己徒卒。老幼守宫，次于雩门之外。五日，右师从之。公叔务人见保者而泣，曰：「事充政重，上不能谋，士不能死，何以治民？吾既言之矣，敢不勉乎！」
师及齐师战于郊，齐师自稷曲，师不逾沟。樊迟曰：「非不能也，不信子也。请三刻而逾之。」如之，众从之。师入齐军，右师奔，齐人从之，陈瓘、陈庄涉泗。孟之侧后入以为殿，抽矢策其马，曰：「马不进也。」林不狃之伍曰：「走乎？」不狃曰：「谁不如？」曰：「然则止乎？」不狃曰：「恶贤？」徐步而死。师获甲首八十，齐人不能师。宵，谍曰：「齐人遁。」冉有请从之三，季孙弗许。孟孺子语人曰：「我不如颜羽，而贤于邴泄。子羽锐敏，我不欲战而能默。泄曰：『驱之。』」公为与其嬖僮汪錡乘，皆死，皆殡。孔子曰：「能执干戈以卫社稷，可无殇也。」冉有用矛于齐师，故能入其军。孔子曰：「义也。」
夏，陈辕颇出奔郑。初，辕颇为司徒，赋封田以嫁公女。有馀，以为己大器。国人逐之，故出。道渴，其族辕咺进稻醴、梁糗、糗脯焉。喜曰：「何其给也？」对曰：「器成而具。」曰：「何不吾谏？」对曰：「惧先行。」
为郊战故，公会吴子伐齐。五月，克博，壬申，至于羸。中军从王，胥门巢将上军，王子姑曹将下军，展如将右军。齐国书将中军，高无丕将上军，宗楼将下军。陈僖子谓其弟书：「尔死，我必得志。」宗子阳与闾丘明相厉也。桑掩胥御国子，公孙夏曰：「二子必死。」将战，公孙夏命其徒歌《虞殡》。陈子行命其徒具含玉。公孙挥命其徒曰：「人寻约，吴发短。」东郭书曰：「三战必死，于此三矣。」使问弦多以琴，曰：「吾不复见子矣。」陈书曰：「此行也，吾闻鼓而已，不闻金矣。」
甲戌，战于艾陵，展如败高子，国子败胥门巢。王卒助之，大败齐师。获国书、公孙夏、闾丘明、陈书、东郭书，革车八百乘，甲首三千，以献于公。将战，吴子呼叔孙，曰：「而事何也？」对曰：「从司马。」王赐之甲、剑、铍，曰：「奉尔君事，敬无废命。」叔孙未能对，卫赐进，曰：「州仇奉甲从君。」而拜。公使大史固归国子之元，置之新箧，褽之以玄纁，加组带焉。置书于其上，曰：「天若不识不衷，何以使下国？」
吴将伐齐，越子率其众以朝焉，王及列士，皆有馈赂。吴人皆喜，惟子胥惧，曰：「是豢吴也夫！」谏曰：「越在我，心腹之疾也。壤地同，而有欲于我。夫其柔服，求济其欲也，不如早从事焉。得志于齐，犹获石田也，无所用之。越不为沼，吴其泯矣，使医除疾，而曰：『必遗类焉』者，未之有也。《盘庚之诰》曰：『其有颠越不共，则劓殄无遗育，无俾易种于兹邑。』是商所以兴也。今君易之，将以求大，不亦难乎？」弗听，使于齐，属其子于鲍氏，为王孙氏。反役，王闻之，使赐之属镂以死，将死，曰：「树吾墓梵檟檟可材也。吴其亡乎！三年，其始弱矣。盈必毁，天之道也。」
秋，季孙命修守备，曰：「小胜大，祸也。齐至无日矣。」
冬，卫大叔疾出奔宋。初，疾娶于宋子朝，其娣嬖。子朝出。孔文子使疾出其妻而妻之。疾使侍人诱其初妻之娣，置于犁，而为之一宫，如二妻。文子怒，欲攻之。仲尼止之。遂夺其妻。或淫于外州，外州人夺之轩以献。耻是二者，故出。卫人立遗，使室孔姞。疾臣向魋纳美珠焉，与之城锄。宋公求珠，魋不与，由是得罪。及桓氏出，城锄人攻大叔疾，卫庄公复之。使处巢，死焉。殡于郧，葬于少禘。
初，晋悼公子憖亡在卫，使其女仆而田。大叔懿子止而饮之酒，遂聘之，生悼子。悼子即位，故夏戊为大夫。悼子亡，卫人剪夏戊。孔文子之将攻大叔也，访于仲尼。仲尼曰：「胡簋之事，则尝学之矣。甲兵之事，未之闻也。」退，命驾而行，曰：「鸟则择木，木岂能择鸟？」文子遽止之，曰：「圉岂敢度其私，访卫国之难也。」将止。鲁人以币召之，乃归。
季孙欲以田赋，使冉有访诸仲尼。仲尼曰：「丘不识也。」三发，卒曰：「子为国老，待子而行，若之何子之不言也？」仲尼不对。而私于冉有曰：「君子之行也，度于礼，施取其厚，事举其中，敛从其薄。如是则以丘亦足矣。若不度于礼，而贪冒无厌，则虽以田赋，将又不足。且子季孙若欲行而法，则周公之典在。若欲苟而行，又何访焉？」弗听。', '', '', '十一年春季，齐国因为鄎地这一战的缘故，国书、高无邳带兵进攻我国，到达清地。季孙对他的家臣之长冉求说：“齐国驻扎在清地，必然是为了鲁国的缘故，怎么办？”冉求说：“您三位中间一位留守，两位跟着国君在边境抵御。”季孙说：“不行。”冉求说：“那就在境内近郊抵御。”季孙告诉了叔孙、孟孙，这两人不同意。冉求说：“如果不同意，那么国君就不要出去。您一人带领军队，背城作战，不参加战斗的就不能算是鲁国人。鲁国的卿大夫各家的总数比齐国的战车要多，即使您一家的战车也多于齐军，您担心什么？他们两位不想作战是很自然的，因为政权掌握在季氏手里。国政承担在您的肩上，齐国人攻打鲁国而不能作战，这是您的耻辱。这就完全不配和诸侯并列了。”季孙氏让冉求跟着他上朝，在党氏之沟等着，叔孙喊过冉求问他关于作战的意见。冉求回答说：“君子有着深远的考虑，小人知道什么？”孟孙硬是问他，他回答说：“小人是考虑了才干而说话，估计了力量才出力的。”叔孙说：“这是说我成不了大丈夫啊。”退回去以后就检阅部队。孟孺子泄率领右军，颜羽为他驾御战车，邴泄作为车右。冉求率领左军，管周父为他驾御战车，樊迟作为车右。季孙说：“樊迟年纪太轻了。”冉求说：“因为他能够听从命令。”季氏的甲士七千人，冉求带着三百个武城人作为自己的亲兵，老的小的守在宫里，驻扎在雩门外边。过了五天，右军才跟上来。公叔务人见到守城的人就掉眼泪说：“徭役烦、赋税多，上面不能谋划，战士不能拼命，用什么来治理百姓？我已经这么说了，怎么敢不努力呢！”
鲁军和齐军在郊外作战。齐军从稷曲攻击鲁军，鲁军不敢过沟迎战。樊迟说：“不是不能，是不相信您，请您把号令申明三次，然后带头过沟。”冉求照他的话办，众人就跟着他过沟。
鲁军攻入齐军。鲁国右军奔逃，齐国追赶。陈瓘、陈庄徒步渡过泗水。孟之侧在全军之后最后回来，他抽出箭来打他的马，说：“我走在最后是马不肯往前走。”林不狃的伙伴说：“逃跑吗？”不狃说：“我不如谁？”伙伴说：“那么停下来抵抗吗？”不狃说：“停下来抵抗就好么？”从容缓步，被杀死。
鲁军砍下甲士的脑袋八十个，齐国人不能整顿军队。晚上，侦探报告说：“齐国人逃跑了。”冉有三次请求追击，季孙没有允许。孟孺子对别人说：“我不如颜羽，但比邴泄高明。颜羽敏锐善战，我心虽不想作战，但口中不说逃走的话，邴泄却说‘赶着马逃走’。”公为和他宠爱的小僮汪锜同坐一辆战车，一起战死，都加以殡敛。孔子说：“能够拿起干戈保卫国家，可以不作为夭折来对待。”冉有使用矛攻杀齐军，所以能攻破齐军。孔子说：“这是合于道义的。”
夏季，陈国的辕颇逃亡到郑国。当初，辕颇做司徒，对封邑内的土田征收赋税为哀公的女儿出嫁之用；还有剩余的，就用来为自己铸造钟鼎。国内的人们驱逐他，所以出国。在路上口渴，他的部下辕咺奉上甜酒、小米干饭、腌肉干。辕颇高兴地说：“为什么这样丰盛？”辕咺回答说：“器物铸成就准备食物了。”辕颇说：“为什么不劝阻我？”辕咺回答说：“怕被你先赶走。”
为了在郊外作战的缘故，鲁哀公会合吴王进攻齐国。五月，攻下博地。二十五日到达嬴地，中军跟随吴王，胥门率领上军，王子姑曹率领下军，展如率领右军，齐国的国书率领中军，高无邳率领上军，宗楼率领下军。陈僖子对他的弟弟陈书说：“你要是战死，我一定能够得志。”宗子阳和闾丘明也互相勉励。桑掩胥为国书驾御战车。公孙夏说：“这两个人必然战死。”将要开始战斗，公孙夏命令他的部下唱《虞殡》，陈子行命令他的部下准备好含玉。公孙挥命令他的部下说：“每人拿一根八尺的绳子，吴国人头发短。”东郭书说：“打了三次仗，一定得战死，在这里是第三次了。”东郭书派人拿琴做礼品去问候弦多，说：“我不会再见到您了。”陈书说：“这次去，我只能听进军的鼓声，听不到退军的金声了。”
五月二十七日，两军在艾陵作战。展如打败高无邳，国书打败胥门巢。吴王率领的部队救助胥门巢，大败齐军，俘虏了国书、公孙夏、闾丘明、陈书、东郭书，革车八百辆，甲士的脑袋三千个，用来献给哀公。快要进入战斗，吴王喊叔孙说：“你担任什么职务？”叔孙说：“司马。”吴王把甲、剑、铍赐给他，说：“认真地承担你国君交给的任务，不要废弃命令。”叔孙不知该如何回答，子贡走在前面，说：“州仇敬受皮甲跟随着您。”叔孙叩头接受了赏赐。哀公派太史送回国书的头，放在新的筐里，下面垫上黑色和红色的丝绸，加上绸带，在上面放上一封信，说：“上天如果不了解你们的行为不正，怎么能让下国得胜？”
吴国将要攻打齐国，越王率领他的部下前去朝见，吴王和臣下都赠送食物财礼。吴国人都很高兴，惟独伍子胥感到忧惧，说：“这是在豢养吴国的骄气啊！”就劝谏说：“越国在我们这里，是心腹中的一个病，同处在一块土地上而对我们有所要求。他们的驯服，是为了要求达到他们的欲望，我们不如早点下手。在齐国如愿以偿，就好像得到了石头田一样，没法使用。我们不把越国变成池沼，吴国就会被灭掉了，好比让医生治病，而说‘一定要留下病根’，是从来没有的。《尚书》的《盘庚》篇告诫说，‘如果有猖狂捣乱不顺从命令的，就统统铲除不留后患，不要让他们的种族延长下去’，这就是商朝所以兴起的原因。现在您的做法相反，想要用这种办法来求得称霸的大业，不是太困难了吗？”吴王夫差不听，派伍子胥到齐国去。伍子胥把儿子托付给齐国的鲍氏，改姓王孙氏。伍子胥从齐国回来，吴王听说这件事，便派人把属镂宝剑赐给伍子胥让他自杀。伍子胥临死的时候说：“在我的坟墓上种植檟树，檟树可以成材。吴国大概就要灭亡了吧！三年以后，吴国就要开始衰弱了。骄傲自满必然失败，这是自然的道理啊。”
秋季，季孙命令整顿防务，说：“小国战胜大国，这是祸患，齐国没有几天就会来到的。”
冬季，卫国的太叔疾逃亡到宋国。当初，太叔疾娶了宋国子朝的女儿，她的妹妹受到宠爱。子朝逃亡出国，孔文子让太叔疾休弃了他的妻子，而把女儿嫁给他。太叔疾派随从引诱他前妻的妹妹，把她安置在犁地而为她造了一所房子，好像有两个妻子一样。孔文子发怒，想要攻打太叔疾，孔子加以劝阻，孔文子就夺回了女儿，太叔疾又在外州和另外一个女人通奸，外州人夺走了他的车子献给国君。太叔疾为这两件事情感到羞耻，所以逃亡出国。卫国人立了遗做继承人，让他娶了孔姞。太叔疾做了向魋的家臣，把珍珠献给向魋，向魋赠给他城鉏。宋景公索取这珍珠，向魋不给，因此得罪了宋景公。等到桓氏逃亡出国，城鉏人攻打太叔疾，卫庄公又让他回卫国去，让他待在巢地，死在那里。棺材停放在郧地，安葬在少禘。
当初，晋悼公的儿子慭逃亡在卫国，让他的女儿为他驾车打猎。太叔懿子留他喝酒，就聘他的女儿做妻子，生了悼子。悼子即位，所以夏戊做了大夫。悼子逃亡，卫国削去夏戊的官爵和封邑。
孔文子将要攻打太叔的时候，去征求孔子的意见，孔子说：“祭祀的事情，那是我曾经学过的；打仗的事情，我没有听说过。”退下去，叫人套上车子就走，说：“鸟可以选择树木，树木哪里能选择鸟？”孔文子立刻阻止他，说：“圉哪里敢自己打算，为的是防止卫国的祸患。”孔子打算留下来，鲁国人用财礼来召请他，于是就回到鲁国。
季孙想要按田亩征税，派冉有征求孔子的意见。孔子说：“丘不懂得这个。”问了三次，最后说：“您是国家的元老，等着您的意见办事，为什么您不说话呢？”孔子不作正式答复，私下对冉有说：“君子推行政事，要根据礼来衡量：施舍要力求丰厚，事情要做得适当，赋敛要尽量微薄。如果这样，那么照我看来也就够了。如果不根据礼来衡量，而贪婪没有满足，那么虽然按田亩征税，还会不够的。而且季孙如果要办事合于法度，那么周公的典章就在那里。如果要随便办事，又何必征求意见呢？”季孙不听。', NULL, '', 'indent', 1559212456, '5cef41257b968a00768bb814', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643108, '左传 · 哀公 · 哀公十二年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有二年春，用田赋。夏五月甲辰，孟子卒。公会吴于皋阜。秋，公会卫侯、宋皇瑗于郧。宋向巢帅师伐郑。冬十有二月，螽。
【传】十二年春，王正月，用田赋。
夏五月，昭夫人孟子卒。昭公娶于吴，故不书姓。死不赴，故不称夫人。不反哭，故言不葬小君。孔子与吊，适季氏。季氏不絻，放絰而拜。
公会吴于橐皋。吴子使大宰嚭请寻盟。公不欲，使子贡对曰：「盟所以周信也，故心以制之，玉帛以奉之，言以结之，明神以要之。寡君以为苟有盟焉，弗可改也已。若犹可改，日盟何益？今吾子曰：『必寻盟。』若可寻也，亦可寒也。」乃不寻盟。
吴征会于卫。初，卫人杀吴行人且姚而惧，谋于行人子羽。子羽曰：「吴方无道，无乃辱吾君，不如止也。」子木曰：「吴方无道，国无道，必弃疾于人。吴虽无道，犹足以患卫。往也。长木之毙，无不噬也。国狗之□，无不噬也。而况大国乎？」
秋，卫侯会吴于郧。公及卫侯、宋皇瑗盟，而卒辞吴盟。吴人藩卫侯之舍。子服景伯谓子贡曰：「夫诸侯之会，事既毕矣，侯伯致礼，地主归饩，以相辞也。今吴不行礼于卫，而藩其君舍以难之，子盍见大宰？」乃请束锦以行。语及卫故，大宰嚭曰：「寡君愿事卫君，卫君之来也缓，寡君惧，故将止之。」子贡曰：「卫君之来，必谋于其众。其众或欲或否，是以缓来。其欲来者，子之党也。其不欲来者，子之仇也。若执卫君，是堕党而崇仇也。夫堕子者得其志矣！且合诸侯而执卫君，谁敢不惧？堕党崇仇，而惧诸侯，或者难以霸乎！」大宰嚭说，乃舍卫侯。卫侯归，效夷言。子之尚幼，曰：「君必不免，其死于夷乎！执焉，而又说其言，从之固矣。」
冬十二月，螽。季孙问诸仲尼，仲尼曰：「丘闻之，火伏而后蜇者毕。今火犹西流，司历过也。」
宋郑之间有隙地焉，曰弥作、顷丘、玉畅、岩、戈、锡。子产与宋人为成，曰：「勿有是。」及宋平、元之族自萧奔郑，郑人为之城岩、戈、锡。九月，宋向巢伐郑，取锡，杀元公之孙，遂围岩。十二月，郑罕达救岩。丙申，围宋师。', '', '', '', NULL, '', 'indent', 1559212483, '5cef414130863b0068665d65', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643109, '左传 · 哀公 · 哀公十三年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有三年春，郑罕达帅师取宋师于岩。夏，许男成卒。公会晋侯及吴子于黄池。楚公子申帅师伐陈。于越入吴。秋，公至自会。晋魏曼多帅师侵卫。葬许元公。九月，螽。冬十有一月，有星孛于东方。盗杀陈夏区夫。十有二月，螽。
【传】十三年春，宋向魋救其师。郑子剩使徇曰：「得桓魋者有赏。」魋也逃归，遂取宋师于岩，获成讙、郜延。以六邑为虚。
夏，公会单平公、晋定公、吴夫差于黄池。
六月丙子，越子伐吴，为二隧。畴无馀、讴阳自南方，先及郊。吴大子友、王子地、王孙弥庸、寿于姚自泓上观之。弥庸见姑蔑之旗，曰：「吾父之旗也。不可以见仇而弗杀也。」大子曰：「战而不克，将亡国。请待之。」弥庸不可，属徒五千，王子地助之。乙酉，战，弥庸获畴无馀，地获讴阳。越子至，王子地守。丙戌，复战，大败吴师。获大子友、王孙弥庸、寿于姚。丁亥，入吴。吴人告败于王，王恶其闻也，自刭七人于幕下。
秋七月辛丑，盟，吴、晋争先。吴人曰：「于周室，我为长。」晋人曰：「于姬姓，我为伯。」赵鞅呼司马寅曰：「日旰矣，大事未成，二臣之罪也。建鼓整列，二臣死之，长幼必可知也。」对曰：「请姑视之。」反，曰：「肉食者无墨。今吴王有墨，国胜乎？大子死乎？且夷德轻，不忍久，请少待之。」乃先晋人。吴人将以公见晋侯，子服景伯对使者曰：「王合诸侯，则伯帅侯牧以见于王。伯合诸侯，则侯帅子男以见于伯。自王以下，朝聘玉帛不同。故敝邑之职贡于吴，有丰于晋，无不及焉，以为伯也。今诸侯会，而君将以寡君见晋君，则晋成为伯矣，敝邑将改职贡。鲁赋于吴八百乘，若为子男，则将半邾以属于吴，而如邾以事晋。且执事以伯召诸侯，而以侯终之，何利之有焉？」吴人乃止。既而悔之，将囚景伯，景伯曰：「何也立后于鲁矣。将以二乘与六人从，迟速唯命。」遂囚以还。及户牖，谓大宰曰：「鲁将以十月上辛，有事于上帝先王，季辛而毕。何世有职焉，自襄以来，未之改也。若不会，祝宗将曰：『吴实然。』且谓鲁不共，而执其贱者七人，何损焉？」大宰嚭言于王曰：「无损于鲁，而只为名，不如归之。」乃归景伯。
吴申叔仪乞粮于公孙有山氏，曰：「佩玉、忌兮，余无所系之。旨酒一盛兮，余与褐之父睨之。」对曰：「梁则无矣，粗则有之。若登首山以呼曰：『庚癸乎！』则诺。」
王欲伐宋，杀其丈夫而囚其妇人。大宰嚭曰：「可胜也，而弗能居也。」乃归。
冬，吴及越平。', '', '', '十三年春季，宋国的向魋救援他们的军队。郑国的武子魋派人通告全军说：“抓到向魋的有赏。”向魋就逃走回国。郑军就在嵒地全部歼灭宋军，俘虏了成讙郜延，把六个城邑掳掠一空，然后两国都不加管辖。
夏季，哀公在黄池会见单平公、晋定公、吴王夫差。
六月十一日，越王攻打吴国，兵分两路，越国的畴无馀、讴阳从南边走，先到达吴国国都的郊区。吴国的太子友、王子地、王孙弥庸、寿於姚在泓水上观察越军。弥庸见到姑蔑的旗帜，说：“那是我父亲的旗帜。我不能见到仇人而不杀死他们。”太子友说：“如果作战不能取胜，将会亡国，请等一等。”王孙弥庸不同意，集合部下五千人出战，王子地帮助他。二十日，两军交战，弥庸俘虏了畴无馀，王子地俘虏了讴阳。越王勾践率军到达，王子地防守。二十一日，再次交战，越军大败吴军，俘虏了太子友、王孙弥庸、寿於姚。二十二日，越军进入吴国。吴国人向吴王报告战败。吴王深恐诸侯听到这个消息，亲自把七个报信的吴人杀死在帐幕里边。
秋季，七月初六日，吴国和晋国争执歃血的先后。吴国人说：“在周王室中，我们是老大。”晋国人说：“在姬姓之中，我们为首。”赵鞅对司马寅说：“天已晚了，大事没有成功，是我们两个臣下的罪过。竖起旗帜整顿队列，我们两人战斗到死，次序先后就可以定了。”司马寅说：“请姑且到吴营那里观察一下。”回来，说：“高贵的人的脸色没有灰暗无神的。现在吴王面色灰暗，是他的国家被敌人战胜了吗？或许是太子死了吧？而且夷人轻佻不沉着，不能长久忍耐，请稍等一等。”吴国人就让晋国人先歃血。
吴国人要带领哀公进见晋定公，子服景伯对使者说：“天子会合诸侯，那么诸侯之长就率领诸侯进见天子；诸侯之长会合诸侯，那么侯就率领子、男进见诸侯领袖。从天子以下，朝聘时所用的玉帛也不相同。所以敝邑进贡给吴国的，要比晋国丰厚，而没有不如的，因为把吴国作为诸侯的领袖。现在诸侯会见，而君王准备带领寡君进见晋君，那么晋国就成为诸侯的领袖了，敝邑将会改变进贡的数量：鲁国进贡按八百辆战车给贵国，如果变成子、男，那么将会按邾国战车的一半作为贡品，而按邾国战车的数来事奉晋国。而且执事以诸侯之长的身分召集诸侯，而以一般诸侯的身分结束，这有什么好处呢？”吴国人就没有那么做。不久又后悔了，准备囚禁景伯。景伯说：“何已经在鲁国立了继承人了，打算带两辆车子和六个人跟随去，早走晚走听你们的命令。”吴国人就囚禁了景伯，带回去。到达户牖，景伯对太宰说：“鲁国将要在十月的第一个辛日祭祀天帝和先王，最后一个辛日完毕。何世世代代都在祭祀中担任一定的职务，从鲁襄公以来没有改变过。如果我不参加，祝宗将会说‘是吴国让他这样的’，而且贵国认为鲁国不恭敬，而只逮捕了他们七个卑微的人，对鲁国有什么损害呢？”太宰嚭对吴王说：“对鲁国没有损害，而只能造成坏名声，不如放他回去。”于是就放回了景伯。
吴国的申叔仪到公孙有山氏那里讨粮食，说：“佩玉垂下来啊，我没有地方系住；甜酒一杯啊，我和贫苦的老头斜视着。”公孙有山氏回答说：“细粮已经没了，粗粮还有一些。如果你登上首山喊‘下等货啊’，就答应你。”
吴王夫差想要攻打宋国，准备杀死那里的男人而囚禁妇女，太宰嚭说：“我们虽然可以战胜，但不能在那里久留。”吴王这才回国。
冬季，吴国和越国讲和。
