INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643110, '左传 · 哀公 · 哀公十四年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有四年春，西狩获麟。小邾射以句绎来奔。夏四月，齐陈心互执其君，置于舒州。庚戌，叔还卒。五月庚申朔，日有食之。陈宗竖出奔楚。宋向魋入于曹以叛。莒子狂卒。六月，宋向魋自曹出奔卫。宋向巢来奔。齐人弑其君壬于舒州。秋，晋赵鞅帅师伐卫。八月辛丑，仲孙何忌卒。冬，陈宗竖自楚复入于陈，陈人杀之。陈辕买出奔楚。有星孛。饥。
【传】十四年春，西狩于大野，叔孙氏之车子锄商获麟，以为不祥，以赐虞人。仲尼观之，曰：「麟也。」然后取之。
小邾射以句绎来奔，曰：「使季路要我，吾无盟矣。」使子路，子路辞。季康子使冉有谓之曰：「千乘之国，不信其盟，而信子之言，子何辱焉？」对曰：「鲁有事于小邾，不敢问故，死其城下可也。彼不臣而济其言，是义之也。由弗能。」
齐简公之在鲁也，阚止有宠焉。及即位，使为政。陈成子惮之，骤顾诸朝。诸御鞅言于公曰：「陈、阚不可并也，君其择焉。」弗听。子我夕，陈逆杀人，逢之，遂执以入。陈氏方睦，使疾，而遗之潘沐，备酒肉焉，飨守囚者，醉而杀之，而逃。子我盟诸陈于陈宗。
初，陈豹欲为子我臣，使公孙言己，已有丧而止。既，而言之，曰：「有陈豹者，长而上偻，望视，事君子必得志，欲为子臣。吾惮其为人也，故缓以告。」子我曰：「何害？是其在我也。」使为臣。他日，与之言政，说，遂有宠，谓之曰：「我尽逐陈氏，而立女，若何？」对曰：「我远于陈氏矣。且其违者，不过数人，何尽逐焉？」遂告陈氏。子行曰：「彼得君，弗先，必祸子。」子行舍于公宫。
夏五月壬申，成子兄弟四乘如公。子我在幄，出，逆之。遂入，闭门。侍人御之，子行杀侍人。公与妇人饮酒于檀台，成子迁诸寝。公执戈，将击之。大史子余曰：「非不利也，将除害也。」成子出舍于库，闻公犹怒，将出，曰：「何所无君？」子行抽剑，曰：「需，事之贼也。谁非陈宗？所不杀子者，有如陈宗！」乃止。子我归，属徒，攻闱与大门，皆不胜，乃出。陈氏追之，失道于弇中，适丰丘。丰丘人执之，以告，杀诸郭关。成子将杀大陆子方，陈逆请而免之。以公命取车于道，及耏，众知而东之。出雍门，陈豹与之车，弗受，曰：「逆为余请，豹与余车，余有私焉。事子我而有私于其仇，何以见鲁、卫之士？」东郭贾奔卫。
庚辰，陈恒执公于舒州。公曰：「吾早从鞅之言，不及此。」
宋桓魋之宠害于公，公使夫人骤请享焉，而将讨之。未及，魋先谋公，请以鞍易薄，公曰：「不可。薄，宗邑也。」乃益鞍七邑，而请享公焉。以日中为期，家备尽往。公知之，告皇野曰：「余长魋也，今将祸余，请即救。」司马子仲曰：「有臣不顺，神之所恶也，而况人乎？敢不承命。不得左师不可，请以君命召之。」左师每食击钟。闻钟声，公曰：「夫子将食。」既食，又奏。公曰：「可矣。」以乘车往，曰：「迹人来告曰：『逢泽有介麇焉。』公曰：『虽魋未来，得左师，吾与之田，若何？』君惮告子。野曰：『尝私焉。』君欲速，故以乘车逆子。」与之乘，至，公告之故，拜，不能起。司马曰：「君与之言。」公曰：「所难子者，上有天，下有先君。」对曰：「魋之不共，宋之祸也，敢不唯命是听。」司马请瑞焉，以命其徒攻桓氏。其父兄故臣曰：「不可。」其新臣曰：「从吾君之命。」遂攻之。子颀骋而告桓司马。司马欲入，子车止之，曰：「不能事君，而又伐国，民不与也，只取死焉。」向魋遂入于曹以叛。六月，使左师巢伐之。欲质大夫以入焉，不能。亦入于曹，取质。魋曰：「不可。既不能事君，又得罪于民，将若之何？」乃舍之。民遂叛之。向魋奔卫。向巢来奔，宋公使止之，曰：「寡人与子有言矣，不可以绝向氏之祀。」辞曰：「臣之罪大，尽灭桓氏可也。若以先臣之故，而使有后，君之惠也。若臣，则不可以入矣。」
司马牛致其邑与珪焉，而适齐。向魋出于卫地，公文氏攻之，求夏后氏之璜焉。与之他玉，而奔齐，陈成子使为次卿。司马牛又致其邑焉，而适吴。吴人恶之，而反。赵简子召之，陈成子亦召之。卒于鲁郭门之外，阬氏葬诸丘舆。
甲午，齐陈恒弑其君壬于舒州。孔丘三日齐，而请伐齐三。公曰：「鲁为齐弱久矣，子之伐之，将若之何？」对曰：「陈恒弑其君，民之不与者半。以鲁之众，加齐之半，可克也。」公曰：「子告季孙。」孔子辞。退而告人曰：「吾以从大夫之后也，故不敢不言。」
初，孟孺子泄将圉马于成。成宰公孙宿不受，曰：「孟孙为成之病，不圉马焉。」孺子怒，袭成。从者不得入，乃反。成有司使，孺子鞭之。秋八月辛丑，孟懿子卒。成人奔丧，弗内。袒免哭于衢，听共，弗许。惧，不归。
', '', '', '十四年春季，在西部的大野打猎，叔孙氏的驾车人子鉏商猎获一只麒麟，认为不吉利，赏赐给管山林的人。孔子细看后，说“这是麒麟”，然后收下它。
小邾国的射献上句绎逃亡到鲁国来，说：“派季路和我约定，可以不用盟誓了。”派子路去，子路推辞。季康子派冉有对子路说：“一千辆战车的国家，不相信盟誓，反而相信您的话，您有什么屈辱呢？”子路回答说：“鲁国如果和小邾国发生战事，我不敢询问原因曲直，战死在城下就行了。他不尽臣道，而使他的话得以实现，这是把他的不尽臣道当成正义了，我不能那么办。”
齐简公在鲁国的时候，阚止受到宠信。等到简公即位，就让阚止执政。陈成子惧怕他，在朝廷上屡次回头看他。御者鞅对齐简公说：“陈氏、阚氏不能并列，你还是选择一个。”齐简公不听。
阚止晚上朝见齐简公，陈逆杀人，阚止碰见，就把他逮捕，带进公宫。陈氏一族正好和睦团结，族人就让陈逆假装生病，并送去洗头的淘米水，备有酒肉。陈逆请看守的人吃喝，看守喝醉以后陈逆就杀了他，然后逃走，阚止和陈氏族人在陈氏宗主家里结盟。
当初，陈豹想要当阚止的家臣，让公孙推荐自己。不久陈豹有丧事，就停下来，丧事完了，公孙又对阚止谈起这件事说：“有一个叫陈豹的人，身高背驼，眼睛仰视，事奉君子一定能让人满意，想要当您的家臣。我怕他人品不好，所以没有立即告诉您。”阚止说“这有什么害处？这都在于我。”就要陈豹做了家臣。过了些日子，阚止和他谈政事，很高兴，于是就宠信他。阚止对陈豹说：“我把陈氏全部驱逐而立你做继承人，怎么样？”陈豹回答说：“我在陈氏族中是远支，而且他们不服从的不过几个人，为什么要把他们全部驱逐呢？”就把话告诉了陈氏，子行对陈成子说：“他得到国君信任，不先下手，必然要加祸于您。”子行就在公宫里住下。
夏季，五月十三日，成子兄弟四人坐车到齐简公那里去。阚止正在帐幕里，出来迎接他们，成子兄弟就走进去，把阚止关在门外。侍者抵御他们，子行杀了侍者。齐简公和女人在檀台上喝酒，成子要让他迁到寝室里去。简公拿起戈，就要击打他们。太史子馀说：“不是要对国君不利，而是要除掉有害的人。”成子搬出去住在府库里，听说简公还在生气，就准备逃亡，说：“哪个地方没有国君？”子行抽出剑，说：“迟疑软弱，反害大事。您要走了，谁不能做陈氏的宗主？您走，我要是不杀您，有历代宗主为证！”陈成子就不出走了。
阚止回去，集合部下，攻打宫墙的小门和大门，都没有得胜就逃走了。陈氏追赶他，阚止在弇中迷了路，到了丰丘。丰丘人拘捕他，报告陈成子，把他杀死在外城城关。陈成子准备杀大陆子方，陈逆请求而赦免了。子方用简公的名义在路上得到一辆车，到达耏地，大家发现了就逼他向东去。出了雍门，陈豹给他车子，他不接受，说：“逆为我请求，豹给我车子，我和他们有私交。事奉子我而和他的仇人有私交，怎么能和鲁国、卫国人士相见？”子方就逃亡到卫国。二十一日，陈成子在舒州拘捕了齐简公。简公说：“我要早听了御鞅的话，不会到这一地步。”
宋国桓魋受宠而扩充势力，发展到损害宋景公。宋景公让夫人突然邀请桓魋参加享礼，准备乘机讨伐他，还没有来得及，桓魋先打宋景公的主意，请求用鞌地交换薄地。宋景公说：“不行，薄地，是宋国殷商祖庙的所在地。”于是就把七个城邑并入鞌地，而请求设享礼答谢宋景公，以太阳正中作为期限，私家的武装全都开去了。宋景公知道了，告诉皇野说：“我把桓魋养育大了，现在他要加祸于我，请马上救我。”皇野说：“臣下不服从，这是神明都厌恶的，何况人呢？岂敢不接受命令。但不得到左师的同意是不行的，请用您的名义召见他。”左师每次吃饭，要敲打乐钟。听到钟声，宋景公说：“那一位快要吃饭了。”吃完饭以后，又奏乐。宋景公说：“行了。”皇野坐一辆车子去了，说：“猎场的人来报告说：‘逢泽有一只麋鹿。’国君说：‘即使桓魋没有来，有了左师，我和他一起打猎，怎么样？’国君难于直接告诉您，野说：‘我试着私下和他谈谈。’国君想要快一点，所以用一辆车子来接您。”左师和皇野同乘一辆车，到达，宋景公把原因告诉他，左师下拜，不能起立。皇野说：“君王和他盟誓。”宋景公说：“如果要使您遭到祸难，上有天，下有先君。”左师回答说：“魋不恭敬，这是宋国的祸患。岂敢不唯命是听。”皇野请求兵符，以命令他的部下攻打桓魋。他的父老兄长和旧臣说：“不行。”他的新臣说：“服从我们国君的命令。”皇野就进攻。子颀纵马奔告桓魋。桓魋想要往宫里攻打宋景公，子车劝阻他，说：“不能事奉国君，而又要攻打公室，百姓是不会亲附你的，只能找死。”桓魋就进入曹地叛变。六月，宋景公派左师巢攻打桓魋，左师想要得到大夫做人质而回来，没有办到，也进入曹地，取得人质。桓魋说：“不行，既不能事奉国君，又得罪了百姓，打算怎么办？”于是就释放了人质，百姓就背叛了他们。桓魋逃亡到卫国。向巢逃亡到鲁国来，宋景公派人留下他，说：“我跟您有盟誓了，不能断绝向氏的祭祀。”向巢辞谢说：“我的罪过大，君王把桓氏全部灭亡也是可以的。如果由于先臣的缘故，而让桓氏有继承人，这是君王的恩惠。像我，那就不能再回来了。”
司马牛把他的封邑和玉圭交还给宋景公，就到了齐国。桓魋逃亡到卫国，公文氏攻打他，向他索取夏后氏的玉璜。桓魋给了公文氏别的玉，就逃亡到齐国，陈成子让桓魋做次卿，司马牛又把封邑交还齐国而去到吴国，吴国人讨厌他，他就回到宋国。晋国的赵简子召唤他去，齐国的陈成子也召唤他去，在途中死在鲁国国都的外城门外，阬氏把他葬在丘舆。
六月初五，齐国的陈桓在舒州杀了他们的国君壬。孔子斋戒三天，三次请求攻打齐国。哀公说：“鲁国被齐国削弱已经很久了，您攻打他们，打算怎么办？”孔子回答说：“陈桓杀了他们的国君，百姓不亲附他的有一半。以鲁国的群众加上齐国不服从陈桓的一半，是可以战胜的。”哀公说：“您告诉季孙。”孔子辞谢，退下去告诉别人说：“我由于曾经列于大夫之末，所以不敢不说话。”
当初，孟孺子泄准备在成地养马，成地的宰臣公孙宿不接受，说：“孟孙由于成地百姓贫困，不在这里养马。”孺子发怒，侵袭成地，跟从的人们没能攻入，就回去了。成地的官员派人去，孺子鞭打了来人。秋季，八月十三日，孟懿子死了。成地的人去奔丧，孺子不接纳。成地的人脱去上衣、帽子而在大路上号哭，表示愿供驱使，孺子不答应。成地的人害怕，不敢回成地。
', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3faac6e67846a9226f1d", "shortContent": "本篇是清代志怪名篇之一。写的是康熙间的大官陈鹏年，以智慧和勇气制胜鬼魅，从而救了友人之妻的小故事。\n陈鹏年在康熙年间以清廉著称，是有名的陈青天。在贪官横行、贪赃枉法和歪风邪气比比皆是的社会里，人们自然会十分崇敬和仰慕清官，于是在民间往往会流传许多关于清官的奇闻逸事，其中不免有神化和夸大的成分，但从总体上说都是表达了对邪恶的痛恨，对正义的赞颂。《以正克邪》这个小故事正是真实地反映了当时此种普遍的社会...", "authors": ["吴惠娟"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559212556, '5cef4188a673f500683bd960', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643111, '左传 · 哀公 · 哀公十五年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有五年春王正月，成叛。夏五月，齐高无ぶ出奔北燕。郑伯伐宋。秋八月，大雩。晋赵鞅帅师伐卫。冬，晋侯伐郑。及齐平。卫公孟彄出奔齐。
【传】十五年春，成叛于齐。武伯伐成，不克，遂城输。
夏，楚子西、子期伐吴，乃桐汭。陈侯使公孙贞子吊焉，及良而卒，将以尸入。吴子使大宰嚭劳，且辞曰：「以水潦之不时，无乃廪然陨大夫之尸，以重寡君之忧。寡君敢辞。」上介芋尹盖对曰：「寡君闻楚为不道，荐伐吴国，灭厥民人。寡君使盖备使，吊君之下吏。无禄，使人逢天之戚，大命陨队，绝世于良，废日共积，一日迁次。今君命逆使人曰：『无以尸造于门。』是我寡君之命委于草莽也。且臣闻之曰：『事死如事生，礼也。』于是乎有朝聘而终，以尸将事之礼。又有朝聘而遭丧之礼。若不以尸将命，是遭丧而还也，无乃不可乎！以礼防民，犹或逾之。今大夫曰：『死而弃之』，是弃礼也。其何以为诸侯主？先民有言曰：『无秽虐士。』备使奉尸将命，苟我寡君之命达于君所，虽陨于深渊，则天命也，非君与涉人之过也。」吴人内之。
秋，齐陈瓘如楚。过卫，仲田见之，曰：「天或者以陈氏为斧斤，既斫丧公室，而他人有之，不可知也。其使终飨之，亦不可知也。若善鲁以待时，不亦可乎？何必恶焉？」子玉曰：「然，吾受命矣，子使告我弟。」
冬，及齐平。子服景伯如齐，子赣为介，见公孙成，曰：「人皆臣人，而有背人之心。况齐人虽为子役，其有不贰乎？子，周公之孙也，多飨大利，犹思不义。利不可得，而丧宗国，将焉用之？」成曰：「善哉！吾不早闻命。」
陈成子馆客，曰：「寡君使恒告曰：『寡君愿事君如事卫君。』」景伯揖子赣而进之。对曰：「寡君之愿也。昔晋人伐卫，齐为卫故，伐晋冠氏，丧车五百，因与卫地，自济以西，禚、媚、杏以南，书社五百。吴人加敝邑以乱，齐因其病，取讙与阐。寡君是以寒心。若得视卫君之事君也，则固所愿也。」成子病之，乃归成。公孙宿以其兵甲入于嬴。
卫孔圉取大子蒯聩之姊，生悝。孔氏之竖浑良夫长而美，孔文子卒，通于内。大子在戚，孔姬使之焉。大子与之言曰：「苟使我入获国，服冕乘轩，三死无与。」与之盟，为请于伯姬。
闰月，良夫与大子入，舍于孔氏之外圃。昏，二人蒙衣而乘，寺人罗御，如孔氏。孔氏之老栾宁问之，称姻妾以告。遂入，适伯姬氏。既食，孔伯姬杖戈而先，大子与五人介，舆豭从之。迫孔悝于厕，强盟之，遂劫以登台。栾宁将饮酒，炙未熟，闻乱，使告季子。召获驾乘车，行爵食炙，奉卫侯辄来奔。季子将入，遇子羔将出，曰：「门已闭矣。」季子曰：「吾姑至焉。」子羔曰：「弗及，不践其难。」季子曰：「食焉，不辟其难。」子羔遂出。子路入，及门，公孙敢门焉，曰：「无入为也。」季子曰：「是公孙，求利焉而逃其难。由不然，利其禄，必救其患。」有使者出，乃入。曰：「大子焉用孔悝？虽杀之，必或继之。」且曰：「大子无勇，若燔台，半，必舍孔叔。」大子闻之，惧，下石乞、盂□敌子路。以戈击之，断缨。子路曰：「君子死，冠不免。」结缨而死。孔子闻卫乱，曰：「柴也其来，由也死矣。」孔悝立庄公。庄公害故政，欲尽去之，先谓司徒瞒成曰：「寡人离病于外久矣，子请亦尝之。」归告褚师比，欲与之伐公，不果。', '', '', '', NULL, '', 'indent', 1559212588, '5cef41a37b968a00768bbdc7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643112, '左传 · 哀公 · 哀公十六年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【经】十有六年春王正月己卯，卫世子蒯聩自戚入于卫，卫侯辄来奔。二月，卫子还成出奔宋。夏四月己丑，孔丘卒。
【传】十六年春，瞒成、褚师比出奔宋。
卫侯使鄢武子告于周曰：「蒯聩得罪于君父君母，逋窜于晋。晋以王室之故，不弃兄弟，置诸河上。天诱其衷，获嗣守封焉。使下臣肸敢告执事。」王使单平公对曰：「肸以嘉命来告余一人。往谓叔父，余嘉乃成世，复尔禄次。敬之哉！方天之休，弗敬弗休，悔其可追？」
夏四月己丑，孔丘卒。公诔之曰：「旻天不吊，不憖遗一老。俾屏余一人以在位，茕茕余在疚。呜呼哀哉！尼父。无自律。」子赣曰：「君其不没于鲁乎！夫子之言曰：『礼失则昏，名失则愆。』失志为昏，失所为愆。生不能用，死而诔之，非礼也。称一人，非名也。君两失之。」
六月，卫侯饮孔悝酒于平阳，重酬之，大夫皆有纳焉。醉而送之，夜半而遣之。载伯姬于平阳而行，及西门，使贰车反祏于西圃。子伯季子初为孔氏臣，新登于公，请追之，遇载祏者，杀而乘其车。许公为反祏，遇之，曰：「与不仁人争明，无不胜。」必使先射，射三发，皆远许为。许为射之，殪。或以其车从，得祏于囊中。孔悝出奔宋。
楚大子建之遇谗也，自城父奔宋。又辟华氏之乱于郑，郑人甚善之。又适晋，与晋人谋袭郑，乃求复焉。郑人复之如初。晋人使谍于子木，请行而期焉。子木暴虐于其私邑，邑人诉之。郑人省之，得晋谍焉。遂杀子木。其子曰胜，在吴。子西欲召之，叶公曰：「吾闻胜也诈而乱，无乃害乎？」子西曰：「吾闻胜也信而勇，不为不利，舍诸边竟，使卫藩焉。」叶公曰：「周仁之谓信，率义之谓勇。吾闻胜也好复言，而求死士，殆有私乎？复言，非信也。期死，非勇也。子必悔之。」弗从。召之使处吴竟，为白公。请伐郑，子西曰：「楚未节也。不然，吾不忘也。」他日，又请，许之。未起师，晋人伐郑，楚救之，与之盟。胜怒，曰：「郑人在此，仇不远矣。」
胜自厉剑，子期之子平见之，曰：「王孙何自厉也？」曰：「胜以直闻，不告女，庸为直乎？将以杀尔父。」平以告子西。子西曰：「胜如卵，余翼而长之。楚国第，我死，令尹、司马，非胜而谁？」胜闻之，曰：「令尹之狂也！得死，乃非我。」子西不悛。胜谓石乞曰：「王与二卿士，皆五百人当之，则可矣。」乞曰：「不可得也。」曰：「市南有熊宜僚者，若得之，可以当五百人矣。」乃从白公而见之，与之言，说。告之故，辞。承之以剑，不动。胜曰：「不为利谄，不为威惕，不泄人言以求媚者，去之。」
吴人伐慎，白公败之。请以战备献，许之。遂作乱。秋七月，杀子西、子期于朝，而劫惠王。子西以袂掩面而死。子期曰：「昔者吾以力事君，不可以弗终。」抉豫章以杀人而后死。石乞曰：「焚库弑王，不然不济。」白公曰：「不可。弑王，不祥，焚库，无聚，将何以守矣？」乞曰：「有楚国而治其民，以敬事神，可以得祥，且有聚矣，何患？」弗从。叶公在蔡，方城之外皆曰：「可以入矣。」子高曰：「吾闻之，以险侥幸者，其求无餍，偏重必离。」闻其杀齐管修也而后入。
白公欲以子闾为王，子闾不可，遂劫以兵。子闾曰：「王孙若安靖楚国，匡正王室，而后庇焉，启之愿也，敢不听从。若将专利以倾王室，不顾楚国，有死不能。」遂杀之，而以王如高府，石乞尹门，圉公阳穴宫，负王以如昭夫人之宫。叶公亦至，及北门，或遇之，曰：「君胡不胄？国人望君如望慈父母焉。盗贼之矢若伤君，是绝民望也。若之何不胄？」乃胄而进。又遇一人曰：「君胡胄？国人望君如望岁焉，日日以几。若见君面，是得艾也。民知不死，其亦夫有奋心，犹将旌君以徇于国，而反掩面以绝民望，不亦甚乎？」乃免胄而进。遇箴尹固，帅其属将与白公。子高曰：「微二子者，楚不国矣。弃德从贼，其可保乎？」乃从叶公。使与国人以攻白公。白公奔山而缢，其徒微之。生拘石乞而问白公之死焉，对曰：「余知其死所，而长者使余勿言。」曰：「不言将烹。」乞曰：「此事克则为卿，不克则烹，固其所也，何害？」乃烹石乞。王孙燕奔黄氏。诸梁兼二事，国宁，乃使宁为令尹，使宽为司马，而老于叶。
卫侯占梦，嬖人求酒于大叔僖子，不得，与卜人比而告公曰：「君有大臣在西南隅，弗去，惧害。」乃逐大叔遗。遗奔晋。卫侯谓浑良夫曰：「吾继先君而不得其器，若之何？良夫代执火者而言，曰：「疾与亡君，皆君之子也。召之而择材焉可也，若不材，器可得也。」竖告大子。大子使五人舆豭从己，劫公而强盟之，且请杀良夫。公曰：「其盟免三死。」曰：「请三之后，有罪杀之。」公曰：「诺哉！」', '', '', '十六年春季，瞒成、褚师比逃亡到宋国。
卫庄公派鄢武子向周室报告，说：“蒯聩得罪了君父、君母，逃窜到晋国。晋国由于王室的缘故，不抛弃兄弟，把蒯聩安置在黄河边上。上天开恩，得继承保有封地，派下臣肸谨向执事报告。”周敬王派单平公回答说：“肸把消息带来告诉我，回去对叔父说：我赞许你继承先世，恢复你的禄位。要恭敬啊！这样才能得到上天赐福。不恭敬上天就不能赐福，后悔哪里来得及？”
夏季，四月十一日，孔丘死了，哀公致悼辞说：“上天不善，不肯留下这一位国老，让他捍卫我一人居于君位，使我孤零零地忧愁成病。呜呼哀哉！尼父，我失去了律己的榜样。”子赣说：“国君恐怕不能在鲁国善终吧！他老人家的话说：“礼仪丧失就要昏暗，名分丧失就有过错。’失去意志就是昏暗，失去身份是过错。活着不能任用，死了又致悼辞，这不合于礼仪，自称‘一人’，这不合于名分。国君把礼与名两样都丧失了。”
六月，卫庄公在平阳招待孔悝喝酒，重重酬谢他，对大夫都有所赠送。喝醉了送走他，半夜把他打发走。孔悝用车子装上伯姬动身离平阳，到达西门，派副车回到西圃宗庙中去取神主盒子。子伯季子当初是孔氏的家臣，近来晋升为卫庄公的大夫，请求追赶孔悝，路上碰到载神主盒子的人，就杀了他而坐上他的车子。许公为回去迎接神主盒子，遇到子伯季子，许公为说：“和不仁的人争强，没有不胜的。”就一定要让子伯季子先射，射了三箭，箭都落到离许公为很远的地方。许公为射他，只一箭就把他射死了。有人坐着子伯季子的车子跟上去，在袋子里得到了神主盒子。孔悝逃亡到宋国。
楚国太子建遭到诬陷的时候，从城父逃亡到宋国，又去郑国躲避宋国华氏之乱。郑国人待他很好。又到晋国，和晋国人策划袭击郑国，为此就要求再回到郑国去。郑国人待他像以前一样。晋国人派间谍和太子建联系，事情完了准备回晋国，同时约定入袭郑国的日期。太子建在他的封邑里大肆暴虐，封邑的人告发他。郑国人来查问，发现了晋国间谍，于是就杀死了太子建。太子建的儿子名胜，在吴国，子西想找他来。叶公说：“我听说胜这个人狡诈而好作乱，不是一个祸害吧！”子西说：“我听说胜这个人诚实而勇敢，不做没有利的事情。把他安置在边境上，让他保卫边疆。”叶公说：“符合仁爱叫做诚信，遵循道义叫做勇敢。我听说胜这个人务求实践诺言，而又遍求不怕死的人，大概是有私心吧？不管什么话都要实践，这不是诚信，不管什么事情都不怕死，这不是勇敢。您一定会后悔的。”子西不听，把胜召回来，让他住在和吴国边境的地方，号为白公。胜请求进攻郑国，子西说：“楚国一切政事还没纳入正常轨道。不是这样，我是不会忘记的。”过了些时候，胜又请求，子西同意了。还没有出兵，晋国攻打郑国，楚国却救援郑国，并和郑国结盟。白公胜发怒，说：“郑国人在这里，仇人不在远处了。”
白公胜亲自磨剑，子期的儿子平见到，说：“您为什么亲自磨剑呢？”他说：“胜是以爽直著称的，不告诉您，哪里能算得上直爽呢？我要杀死你父亲。”平把这些话报告子西。子西说：“胜就像鸟蛋，我覆翼而使他长大。在楚国，只要我死了，令尹、司马，不归于胜还归于谁？”胜听了子西的话，说：“令尹真狂妄啊！他要得到好死，我就不是我。”子西还是没有觉察。胜对石乞说：“君王和两位卿士，一共用五百个人对付，就行了。”石乞说“这五百个人是找不到的。”又说：“市场的南边有个叫熊宜僚的，如果找到他，可以抵五百个人。”石乞就跟着白公胜去见宜僚，和他谈话，很高兴。石乞就把要办的事告诉宜僚，宜僚拒绝。把剑架在宜僚脖子上，他一动不动。白公胜说：“这是不为利诱、不怕威胁、不泄漏别人的话去讨好的人，离开这里吧。”
吴国人进攻慎地，白公胜打败了他们。白公胜请求不解除军队武装奉献战利品，楚惠王同意了，白公胜就乘机发动叛乱。秋季，七月，在朝廷上杀了子西、子期，并且劫持楚惠王。子西用袖子遮着脸而死去。子期说：“过去我用勇力事奉君王，不能有始无终。”拔起一株樟树打死了敌人然后死去。石乞说：“焚烧府库，杀死君王。不这样，事情不能成功。”白公胜说：“不行，杀死君王不吉祥，烧掉府库没有积蓄，将要用什么来保有楚国？”石乞说：“有了楚国而治理百姓，用恭敬来事奉神灵，就能得到吉祥，而且还有物资，怕什么？”白公胜不肯听从。
叶公住在蔡地，方城山外边的人都说：“可以进兵国都了。”叶公说：“我听说，用冒险而侥幸成功的，他的欲望不会满足，办事不公平，百姓必然不依附。”听到白公胜杀了齐国的管修，然后才进入郢都。
白公胜想要让子闾做楚王，子闾不答应，就用武力劫持他。子闾说：“您如果安定楚国，整顿王室，然后对启加以庇护，这是启的愿望，岂敢不听从？如果要专谋私利来颠覆王室，置国家于不顾，那么启宁死不从。”白公胜就杀了子闾，带着惠王到高府。石乞守门，圉公阳在宫墙上打开一个洞，背上惠王到了昭夫人的宫中。
叶公也在这时候来到，到达北门，有人遇到他，说：“您为什么不戴上头盔？国内的人们盼望您好像盼望慈爱的父母，盗贼的箭如果射伤您，这就断绝了百姓的盼望。为什么不戴上头盔？”叶公就戴上头盔前进，又遇到一个人说：“您为什么戴上头盔？国内的人们盼望您好像盼望丰收一样，天天盼望，如果见到您的面，就能安心了。百姓知道不至于再有生命危险，人人有奋战之心，还要把您的名字写在旗帜上在都城里巡行，但是您又把脸遮起来以断绝百姓的盼望，不也太过分了吗？”叶公就脱下头盔前进。遇到箴尹固率领他的部下，准备去帮助白公胜。叶公说：“如果没有子西他们两位，楚国就不成为国家了，抛弃德行跟从盗贼，难道能够安全吗？”箴尹固就跟随叶公。叶公派他和国内的人们攻打白公胜。白公胜逃到山上自己吊死了，他的部下把尸体藏起来。叶公活捉石乞而追问白公胜的尸体。石乞回答说：“我知道他尸体所藏的地方，但是白公让我别说。”叶公说：“不说就烹了你。”石乞说：“这件事成功就是卿，不成功就被烹，这本来是应有的结果，有什么妨碍？”于是就烹了石乞。王孙燕逃亡到頯黄氏。叶公身兼令尹、司马二职，国家安定以后，就让宁做令尹，宽做司马，自己在叶地退休养老。
卫庄公占卜他做的梦，他的宠臣向太叔僖子要酒，没有得到，就和卜人勾结，而告诉卫庄公说：“您有大臣在西南角上，不去掉他，恐怕有危害。”于是就驱逐太叔遗。太叔遗逃亡到晋国。
卫庄公对浑良夫说：“我继承了先君而没有得到他的宝器，怎么办？”浑良夫让执烛的人出去，自己代他执烛然后说：“疾和逃亡在外的国君，都是您的儿子，召他来可以量才选择。如果没有才能就废掉他，宝器就可以得到了。”童仆密告太子。太子派五个人用车子装上公猪跟着自己，劫持卫庄公强迫和他盟誓，而且请求杀死浑良夫。卫庄公说：“和他的盟誓说过要赦免死罪三次。”太子说：“请在三次以后，再有罪就杀死他。”卫庄公说：“好啊！”', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f7a5914587d02f66ef2", "shortContent": "尊刘抑曹的社会风尚形成于何代何朝？我从前一直未加深思。总以为既然司马光的《资治通鉴》还以魏为正统，很可能从朱熹开始以蜀汉为正统，然后经过《三国志平话》、《三国演义》以及大量三国戏，把尊刘抑曹的思想感情广泛地散布于人民群众之中。\n南朝宋裴松之注陈寿《三国志》是一项巨大的系统工程，使我们看到了一度失传的《曹瞒传》。这篇别传，把曹操的险恶用心、奸诈莫测以及种种狼狈不堪的丑态写得淋漓尽致，为后世鞭挞曹操的...", "authors": ["蒋星煜"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f8503048e64fbda977c", "shortContent": "本篇一开头即写魏耽与女“纳凉于庭”，将其卸任还乡，与家人尽情享受天伦之乐的美满生活托了出来。这时，“忽仰视天裂”，用一个“忽”字陡然来个急转弯，风波顿起。天上裂开一条缝，缝里走出一个黑髯人，要强夺魏耽的掌上明珠。黑髯人自天而降，非神即怪，魏耽夫妻“虽甚忧迫”，却丝毫也不敢得罪，“亦具酒食而俟之”——还要强打精神去备酒弄菜。这里一个“俟”字大可玩味，忧心忡忡，痛楚万分，苦日难捱呵。作者把读者的心吊了...", "authors": ["戴逸如"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559212630, '5cef41d2c8959c0069037006', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643113, '左传 · 哀公 · 哀公十七年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【传】十七年春，卫侯为虎幄于藉圃，成，求令名者，而与之始食焉。大子请使良夫。良夫乘衷甸两牡，紫衣狐裘，至，袒袭，不释剑而食。大子使牵以退，数之以三罪而杀之。
三月，越子伐吴。吴子御之笠泽，夹水而陈。越子为左右句卒，使夜或左或右，鼓噪而进。吴师分以御之。越子以三军潜涉，当吴中军而鼓之，吴师大乱，遂败之。
晋赵鞅使告于卫曰：「君之在晋也，志父为主。请君若大子来，以免志父。不然，寡君其曰，志父之为也。」卫侯辞以难。大子又使椓之。
夏六月，赵鞅围卫。齐国观、陈瓘救卫，得晋人之致师者。子玉使服而见之，曰：「国子实执齐柄，而命瓘曰：『无辟晋师。』岂敢废命？子又何辱？」简子曰：「我卜伐卫，未卜与齐战。」乃还。
楚白公之乱，陈人恃其聚而侵楚。楚既宁，将取陈麦。楚子问帅于大师子谷与叶公诸梁，子谷曰：「右领差车与左史老，皆相令尹、司马以伐陈，其可使也。」子高曰：「率贱，民慢之，惧不用命焉。」子谷曰：「观丁父，鄀俘也，武王以为军率，是以克州、蓼，服随、唐，大启群蛮。彭仲爽，申俘也，文王以为令尹，实县申、息，朝陈、蔡，封畛于汝。唯其任也，何贱之有？」子高曰：「天命不谄。令尹有憾于陈，天若亡之，其必令尹之子是与，君盍舍焉？臣惧右领与左史有二俘之贱，而无其令德也。」王卜之，武城尹吉。使帅师取陈麦。陈人御之，败，遂围陈。秋七月己卯，楚公孙朝帅师灭陈。
王与叶公枚卜子良以为令尹。沈尹朱曰：「吉，过于其志。」叶公曰：「王子而相国，过将何为？」他日，改卜子国而使为令尹。
卫侯梦于北宫，见人登昆吾之观，被发北面而噪曰：「登此昆吾之虚，绵绵生之瓜。余为浑良夫，叫天无辜。」公亲筮之，胥弥赦占之，曰：「不害。」与之邑，置之，而逃奔宋。卫侯贞卜，其繇曰：「如鱼赬尾，衡流而方羊。裔焉大国，灭之将亡。阖门塞窦，乃自后逾。」
冬十月，晋复伐卫，入其郛。将入城，简子曰：「止。叔向有言曰：『怙乱灭国者无后。』」卫人出庄公而晋平，晋立襄公之孙般师而还。十一月，卫侯自鄄入，般师出。
初，公登城以望，见戎州。问之，以告。公曰：「我姬姓也，何戎之有焉？」剪之。公使匠久。公欲逐石圃，未及而难作。辛已，石圃因匠氏攻公，公阖门而请，弗许。逾于北方而队，折股。戎州人攻之，大子疾、公子青逾从公，戎州人杀之。公入于戎州己氏。初，公自城上见己氏之妻发美，使髡之，以为吕姜髢。既入焉，而示之璧，曰：「活我，吾与女璧。」己氏曰：「杀女，璧其焉往？」遂杀之而取其璧。卫人复公孙般师而立之。十二月，齐人伐卫，卫人请平。立公子起，执般师以归，舍诸潞。
公会齐侯，盟于蒙，孟武伯相。齐侯稽首，公拜。齐人怒，武伯曰：「非天子，寡君无所稽首。」武伯问于高柴曰：「诸侯盟，谁执牛耳？」季羔曰：「鄫衍之役，吴公子姑曹。发阳之役，卫石魋。」武伯曰：「然则彘也。」
宋皇瑗之子麇，有友曰田丙，而夺其兄劖般邑以与之。劖般愠而行，告桓司马之臣子仪克。子仪克适宋，告夫人曰：「麇将纳桓氏。」公问诸子仲。初，仲将以杞姒之子非我为子。曰：「必立伯也，是良材。」子仲怒，弗从，故对曰：「右师则老矣，不识麇也。」公执之。皇瑗奔晋，召之。', '', '', '十七年春季，卫庄公在藉圃建造了一座刻有虎兽纹的小木屋，造成了，要寻找一位有好名誉的人和他在里边吃第一顿饭。太子请求找浑良夫。浑良夫坐在两匹公马驾着的车子上，穿上紫色衣服和狐皮袍。来到以后，敞开皮袍，没有解下佩剑就吃饭。太子派人牵着他退下，举出三条罪状就杀死了他。
三月，越王发兵进攻吴国，吴王发兵在笠泽抵御，隔着一条河摆开阵势。越王将越军编成左右两支部队，让他们在夜里忽左忽右，击鼓呐喊前进。吴军分兵抵御。越王带领三军偷渡，对准吴国的中军击鼓进攻。吴军大乱，于是越军就打败了吴军。
晋国的赵鞅派人告诉卫国，说：“君王在晋国的时候，我是主人。现在请君王或者太子来一趟，以免除我的罪过。不这样，寡君恐怕会说这是我授意这样做的。”卫庄公以国内有祸难加以推辞，太子又派人在使者面前诽谤卫庄公。
夏季，六月，赵鞅包围卫国。齐国的国观、陈瓘救援卫国，俘虏了晋国单车挑战的人。陈瓘让被俘者穿上本来的服装然后接见他，说：“国子掌握齐国政权，命令我说‘不要逃避晋军’，我哪里敢废弃这个命令？哪里又用得着劳驾您呢？”赵鞅说：“我为攻打卫国占卜过，没有为和齐国作战占卜。”于是就撤兵回国。
楚国白公的那次动乱，陈国人仗着自己有积蓄而侵袭楚国。楚国安定以后，准备夺取陈国的麦子。楚国向太师子穀和叶公诸梁询问统帅的人选，子穀说：“右领差车和左史老都辅佐过令尹、司马攻打陈国，大概是可以派遣的。”子高说：“这两个人都是被俘虏过的，百姓轻慢他们，怕不会听从命令。”子穀说：“观丁父，做过鄀国俘虏，武王让他做军帅，因此战胜州国、蓼国，使随国、唐国顺服，大大地开导了各部蛮人。彭仲爽，做过申国俘虏，文王让他做令尹，使申国、息国成为我国的两县，使陈国、蔡国前来朝见，开拓封疆到达汝水。只要他们能够胜任，做过俘虏有什么关系？”子高说：“上天的意志不容怀疑。令尹对陈国有遗恨，上天如果要灭亡陈国，一定会保佑令尹儿子去完成，您何不任命他呢？我害怕右领和左史有俘虏的卑贱而没有他们的美德。”楚惠王占卜，公孙朝吉利，就派他带兵夺取陈国的麦子。陈国人抵抗，战败，公孙朝就包围了陈国。秋季，七月初八日，公孙朝领兵灭亡陈国。
楚惠王和叶公为让子良做令尹而占卜。沈尹朱说：“吉利。超过了他的期望。”叶公说：“以王子的地位而辅助国王，超过这地位将会做什么？”过了几天，改为子国占卜而让他做了令尹。
卫庄公在北宫做梦，梦见一个人登上昆吾之观，披头散发脸朝着北面叫嚷说：“登上这昆吾之墟，有绵延不断生长的大瓜小瓜。我是浑良夫，向上天呼诉无辜。”卫庄公亲自占筮，胥弥赦预测说：“没有妨碍。”封给胥弥赦城邑，他不接受而逃亡到宋国。卫庄公又占卜，繇辞说：“像一条浅色的红尾鱼，穿过急流而犹豫不安。靠近大国，消灭它，将要灭亡。关门塞洞，就越过后墙。”
冬季，十月，晋国再次攻打卫国，进入外城。将要进入内城，赵简子说：“停止！叔向说过：‘依仗着动乱而灭亡别国的没有后嗣。’”卫国人赶走了庄公而和晋国讲和。晋国人立了卫襄公的孙子般师为君然后回国。
十一月，卫庄公从鄄地回国，般师出走。当初，卫庄公登城远望，见到戎州。他问是怎么回事，有人告诉他是戎人的居邑。卫庄公说：“我是姬姓，哪里有什么戎人？”就派人毁平了戎州。卫庄公使用匠人，长久不让休息。他又想要驱逐国卿石圃，没有来得及而祸难发生了。十二日，石圃联合匠人攻打卫庄公。卫庄公关上门请求饶命，石圃不答应。卫庄公超过北墙掉下去，折断了大腿骨。戎州人攻打卫庄公，太子疾、公子青越墙跟从卫庄公，戎州人杀死了他们。卫庄公逃到戎州己氏那里。当初，卫庄公从城上看到己氏的妻子头发很漂亮，派人让她剪下来，作为自己夫人吕姜的假发。这时庄公到了己氏家里，把玉璧给己氏看，说：“救我的命，给你玉璧。”己氏说：“杀了你，玉璧会那里去？”就杀死了卫庄公并获得了他的玉璧。卫国人让公孙般师回国并立他为君。十二月，齐国人进攻卫国，卫国人请求讲和。齐国人立了公子起为卫君，拘捕了般师回去，让他住在潞地。
哀公在蒙地会见齐平公并且结盟，孟武伯相礼。齐平公叩头，哀公弯腰作揖，齐国人发怒。孟武伯说：“不是天子，寡君没法叩头。”孟武伯问高柴说：“诸侯结盟，谁执牛耳？”高柴说：“鄫衍那一次盟誓，执牛耳的是吴国公子姑曹，发阳那一次，是卫国石魋。”孟武伯说：“那么这次就是我了。”
宋国皇瑗的儿子麇有个朋友叫田丙，麇夺取了他哥哥酁般的封邑给了田丙。酁般含怒出走，告诉桓司马的家臣子仪克。子仪克去到宋国，告诉夫人说：“麇打算接纳桓氏。”宋景公询问子仲。当初，子仲打算把杞姒的儿子非我作为嫡子。麇说：“一定要立老大，这是好材料。”子仲发怒，不听从，所以回答说：“右师已经老了，不会作乱，对麇就不了解了。”宋景公抓了麇。皇瑗逃亡到晋国，宋景公又派人把他召唤回来。', NULL, '', 'indent', 1559212672, '5cef41fdba39c80068a4f385', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643114, '左传 · 哀公 · 哀公十八年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【传】十八年春，宋杀皇瑗。公闻其情，复皇氏之族，使皇缓为右师。
巴人伐楚，围。初，右司马子国之卜也，观瞻曰：「如志。」故命之。及巴师至，将卜帅。王曰：「宁如志，何卜焉？」使帅师而行。请承，王曰：「寝尹、工尹，勤先君者也。」三月，楚公孙宁、吴由于、薳固败巴师于，故封子国于析。君子曰：「惠王知志。《夏书》曰『官占，唯能蔽志，昆命于元龟。』其是之谓乎！《志》曰：『圣人不烦卜筮。』惠王其有焉！」
夏，卫石圃逐其君起，起奔齐。卫侯辄自齐复归，逐石圃，而复石魋与大叔遗。', '', '', '十八年春季，宋国杀了皇瑗。宋景公听说了他们的情况，恢复了皇氏的家族，派皇缓做了右师。
巴人进攻楚国，包围鄾地。当初，右司马子国占卜，观瞻说：“符合你的意愿。”所以就命令他做了右司马。等到巴军来到，将要占卜统帅的人选。楚惠王说：“宁已经符合意愿，还占卜什么？”派他领兵出行。请求任命副手，楚惠王说：“寝尹、工尹，都是为先君出过力的人。”三月，楚国的公孙宁、吴由于、薳固在鄾地击败巴军，所以把析地作为子国的封邑。
君子说：“惠王了解人的意愿。《夏书》说：‘占卜的官员只有能够审察判断人的意愿，然后才使用龟甲。’说的就是这个吧！《志》说，‘圣人用不着占卜占筮’，楚惠王大概就能这样。”
夏季，卫国的石圃赶走了他的国君起，起逃亡到齐国。卫出公辄从齐国重新回国，赶走了石圃，恢复了石魋和太叔遗原来的官职。', NULL, '', 'indent', 1559212712, '5cef4226a673f500683bdf5b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643115, '左传 · 哀公 · 哀公十九年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【传】十九年春，越人侵楚，以误吴也。夏，楚公子庆、公孙宽追越师，至冥，不及，乃还。
秋，楚沈诸梁伐东夷，三夷男女及楚师盟于敖。
冬，叔青如京师，敬王崩故也。', '', '', '十九年春季，越国人侵袭楚国，是为了迷惑吴国。夏季，楚国的公子庆、公孙宽追赶越军，到达冥地，没有追上，就撤兵回去了。
秋季，楚国的沈诸梁进攻东夷，三夷的男女和楚军在敖地结盟。
冬季，叔青到京师去，这是由于周敬王死了的缘故。

', NULL, '', 'indent', 1559296572, '5cf089b5ba39c80068b0d8ea', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643116, '左传 · 哀公 · 哀公二十年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【传】二十年春，齐人来征会。夏，会于廪丘。为郑故，谋伐晋。郑人辞诸子侯，秋，师还。
吴公子庆忌骤谏吴子，曰：「不改，必亡。」弗听。出居于艾，遂适楚。闻越将伐吴，冬，请归平越，遂归。欲除不忠者以说于越，吴人杀之。
十一月，越围吴。赵孟降于丧食。楚隆曰：「三年之丧，亲昵之极也。主又降之，无乃有故乎！」赵孟曰：「黄池之役，先主与吴王有质，曰：『好恶同之。』今越围吴，嗣子不废旧业而敌之，非晋之所能及也，吾是以为降。」楚隆曰：「若使吴王知之，若何？」赵孟曰：「可乎？」隆曰：「请尝之。」乃往。先造于越军，曰：「吴犯间上国多矣，闻君亲讨焉，诸夏之人莫不欣喜，唯恐君志之不从。请入视之。」许之。告于吴王曰：「寡君之老无恤，使陪臣隆敢展谢其不共。黄池之役，君之先臣志父得承齐盟，曰：『好恶同之。』今君在难，无恤不敢惮劳。非晋国之所能及也，使陪臣敢展布之。」王拜稽首曰：「寡人不佞，不能事越，以为大夫忧，拜命之辱。」与之一箪珠，使问赵孟，曰：「句践将生忧寡人，寡人死之不得矣。」王曰：「溺人必笑，吾将有问也，史黯何以得为君子？」对曰：「黯也进不见恶，退无谤言。」王曰：「宜哉。」
', '', '', '二十年春季，齐国人来鲁国征召会见。夏季，在廪丘会见，为了郑国的缘故，策划攻打晋国。郑国人向诸侯辞谢。秋季，军队回国。
吴国的公子庆忌屡次劝谏吴王说：“如果不改变政令，一定亡国。”吴王不听，庆忌离开国都住在艾地，又乘机到楚国去。庆忌听说越国准备进攻吴国，冬季，请求回国和越国讲和，于是就回国了。想要除掉不忠的人来讨越国的喜欢。吴国人杀死了庆忌。
十一月，越国军队包围了吴国，赵孟的饮食比居丧时的饮食还要降等。楚隆说：“三年的丧礼，是表示亲情关系的极点，现在您又降等，恐怕另有缘故吧！”赵孟说：“黄池那一次盟会，先主和吴王有过盟誓，说：‘同好共恶。’现在越国包围吴国，继承人想不废弃过去的誓言而帮助吴国，但又不是晋国的力量所能达到的，我因此只能用饮食降等来表示心意。”楚隆说：“如果让吴王知道，怎么样？”赵孟说：“行吗？”楚隆说：“请试一试。”于是就前去，先到越军那里，说：“吴国冒犯上国已经多次了，听说君王亲自讨伐，中原的人们莫不欢欣鼓舞，惟恐君王的意愿不能实现，请让我进去看看吴军的情况。”越王答应了。楚隆告诉吴王说：“寡君的老臣无恤派陪臣隆前来，谨敢为他前来道歉；黄池那一次结盟，君王的先臣志父得以参加盟会，盟誓说‘同好共恶’。现在君王处在危难之中，无恤不敢害怕辛劳，但又不是晋国的力量所能达到的，谨派我向君王报告。”吴王下拜叩头说：“寡人没有才能，不能事奉越国，因而让大夫忧虑，谨拜谢您的命令。”给了楚隆一小盒珍珠，让他送给赵孟，说：“勾践要让我活着不好过，我是不得好死了。”又说：“快淹死的人必然强作欢笑，我还要问你，史黯为什么能成为君子？”楚隆回答说：“史黯这个人做官没有人讨厌他，不做官没有人诽谤他。”吴王说：“真是说得恰当啊！”', NULL, '', 'indent', 1559296614, '5cf089e17b968a00769782bf', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643117, '左传 · 哀公 · 哀公二十一年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【传】二十一年夏五月，越人始来。
秋八月，公及齐侯、邾子盟于顾。齐有责稽首，因歌之曰：「鲁人之皋，数年不觉，使我高蹈。唯其儒书。以为二国忧。」
是行也，公先至于阳谷。齐闾丘息曰：「君辱举玉趾，以在寡君之军。群臣将传遽以告寡君，比其复也，君无乃勤。为仆人之未次，请除馆于舟道。」辞曰：「敢勤仆人？」
', '', '', '二十一年夏季，五月，越国人第一次来鲁国。
秋季，八月，鲁哀公和齐平公、邾隐公在顾地结盟。齐国人责备从前叩头而哀公不相应回礼那件事，因而唱歌说：“鲁人的罪过，几年还没有自己察觉，使我们发怒暴跳。正由于他们只拘泥儒家之书，造成了两国苦恼又忧愁。”
这一趟，哀公先到阳穀。齐国的闾丘息说：“劳驾君王亲自光临，来慰劳寡君的军队，臣下们将要用驿车向寡君报告。等到他们报告回来，君王未免太劳累了。由于仆人没有准备好宾馆，请在舟道暂设行馆。”哀公辞谢说：“岂敢烦劳贵国的仆人？”', NULL, '', 'indent', 1559296649, '5cf08a06d5de2b0070ab8cfd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643119, '左传 · 哀公 · 哀公二十三年 ', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【传】二十三年春，宋景曹卒。季康子使冉有吊，且送葬，曰：「敝邑有社稷之事，使肥与有职竞焉，是以不得助执绋，使求从舆人。曰：『以肥人得备弥甥也，有不腆先人之产马，使求荐诸夫人之宰，其可以称旌繁乎？』」
夏六月，晋荀瑶伐齐。高无丕帅师御之。知伯视齐师，马骇，遂驱之，曰：「齐人知余旗，其谓余畏而反也。」乃垒而还。将战，长武子请卜。知伯曰：「君告于天子，而卜之以守龟于宗祧，吉矣，吾又何卜焉？且齐人取我英丘，君命瑶，非敢耀武也，治英丘也。以辞伐罪足矣，何必卜？」
壬辰，战于犁丘。齐师败绩，知伯亲禽颜庚。
秋八月，叔青如越，始使越也。越诸鞅来聘，报叔青也。', '', '', '二十三年春季，宋国的景曹死了。季康子派冉有去吊唁，并且送葬，说：“敝邑有国家大事，使肥事务繁忙，因此不能帮着送葬，特派求前来跟随在舆人之后，说：‘由于肥忝居远房外甥，有不丰厚的先人的马匹，派求奉献给夫人的家宰，也许能和夫人的马匹相称吧！’”
夏季，六月，晋国的荀瑶攻打齐国，高无邳率军抵御。荀瑶观察齐军的虚实，马受惊，就索性驱马前进，说：“齐国人已经看到我的旗帜，如果不向前进，恐怕要说我害怕而回去了。”到达齐军的营垒以后才回去。将要作战，长武子请求占卜。荀瑶说：“国君报告了天子，在宗庙里已经用龟占卜过，卦像很吉利，我又占卜什么呢？况且齐国人占领了我们的英丘。国君命令瑶，不是敢于炫耀武力，而是为了治理英丘。用正当的理由讨伐有罪者就足够了，何必占卜？”
二十六日，在犁丘作战，齐军大败，荀瑶亲自捉住了颜庚。
秋季，八月，叔青到越国去，这是第一次出使越国。越国的诸鞅前来鲁国聘问，这是回报叔青的访问。', NULL, '', 'indent', 1559296722, '5cf08a4fd5de2b0070ab8f6c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643120, '左传 · 哀公 · 哀公二十四年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【传】二十四年夏四月，晋侯将伐齐，使来乞师，曰：「昔臧文仲以楚师伐齐，取谷。宣叔以晋师伐齐，取汶阳。寡君欲徼福于周公，愿乞灵于臧氏。」臧石帅师会之，取廪丘。军吏令缮，将进。莱章曰：「君卑政暴，往岁克敌，今又胜都。天奉多矣，又焉能进？是躗言也。役将班矣！」晋师乃还。饩臧石牛，大史谢之，曰：「以寡君之在行，牢礼不度，敢展谢之。」
邾子又无道，越人执之以归，而立公子何。何亦无道。
公子荆之母嬖，将以为夫人，使宗人衅夏献其礼。对曰：「无之。」公怒曰：「女为宗司，立夫人，国之大礼也，何故无之？」对曰：「周公及武公娶于薛，孝、惠娶于商，自桓以下娶于齐，此礼也则有。若以妾为夫人，则固无其礼也。」公卒立之，而以荆为大子。国人始恶之。
闰月，公如越，得大子适郢，将妻公，而多与之地。公孙有山使告于季孙，季孙惧，使因大宰嚭而纳赂焉，乃止。', '', '', '二十四年夏季，四月，晋出公准备发兵进攻齐国，派人来鲁国请求出兵，说：“从前臧文仲带领楚军进攻齐国，占领了穀地；宣叔带领晋军进攻齐国，占领了汶阳。寡君想要向周公求福，也愿意向臧氏求得威灵。”臧石领兵和晋军会合，占领了廪丘。军吏下令作好战前准备，将要进军。莱章说：“晋国国君地位低下而政治暴虐，去年战胜敌人，现在又攻占都邑，上天赐给他们的已经很多了，又哪里能够前进？这是在说大话。军队将要撤回去了。”晋军果真撤退回国。晋国人把活牛送给臧石，太史表示歉意说：“由于寡君出行在外，使用的牲口不合礼仪规定的标准，谨敢表示歉意。”
邾隐公还是无道，越国人把他拘捕带回去，而立了公子何为君。公子何也同样无道。
公子荆的母亲受到宠爱，哀公打算立她为夫人，派宗人釁夏献上立夫人的礼品。釁夏回答说：“没有这样的礼节。”哀公发怒说：“你做宗司，立夫人，这是国家的大礼，为什么没有？釁夏回答说：“周公和武公在薛国娶妻，孝公、惠公在宋国娶妻，从桓公以下在齐国娶妻，这样的礼节是有的。如果把妾作为夫人，那就本来没有这样的礼节。”哀公最终还是立了她为夫人，而把荆立为太子，国内的人们开始讨厌哀公。
闰月，哀公到越国去，和太子適郢关系很友好，太子適郢要把女儿嫁给哀公而且多给他们土地。公孙有山派人告诉季孙。季孙恐惧，派人走太宰嚭的关系并且送上财礼，事情才得中止。', NULL, '', 'indent', 1559296760, '5cf08a7630863b006872746b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643121, '左传 · 哀公 · 哀公二十五年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【传】二十五年夏五月庚辰，卫侯出奔宋。卫侯为灵台于藉圃，与诸大夫饮酒焉。褚师声子袜而登席，公怒，辞曰：「臣有疾，异于人。若见之，君将之，是以不敢。」公愈怒，大夫辞之，不可。褚师出，公戟其手，曰：「必断而足。」闻之，褚师与司寇亥乘，曰：「今日幸而后亡。」公之入也，夺南氏邑，而夺司寇亥政。公使侍人纳公文懿子之车于池。
初，卫人剪夏丁氏，以其帑赐彭封弥子。弥子饮公酒，纳夏戊之女，嬖，以为夫人。其弟期，大叔疾之从孙甥也，少畜于公，以为司徒。夫人宠衰，期得罪。公使三匠久。公使优狡盟拳弥，而甚近信之。故褚师比、公孙弥牟、公文要、司寇亥、司徒期因三匠与拳弥以作乱，皆执利兵，无者执斤。使拳弥入于公宫，而自大子疾之宫噪以攻公。鄄子士请御之。弥援其手，曰：「子则勇矣，将若君何？不见先君乎？君何所不逞欲？且君尝在外矣，岂必不反？当今不可，众怒难犯，休而易间也。」乃出。将适蒲，弥曰：「晋无信，不可。」将适鄄，弥曰：「齐、晋争我，不可。」将适泠，弥曰：「鲁不足与，请适城锄以钩越，越有君。」乃适城锄。弥曰：「卫盗不可知也，请速，自我始。」乃载宝以归。
公为支离之卒，因祝史挥以侵卫。卫人病之。懿子知之，见子之，请逐挥。文子曰：「无罪。」懿子曰：「彼好专利而妄。夫见君之入也，将先道焉。若逐之，必出于南门而适君所。夫越新得诸侯，将必请师焉。」挥在朝，使吏遣诸其室。挥出，信，弗内。五日，乃馆诸外里，遂有宠，使如越请师。
六月，公至自越。季康子、孟武伯逆于五梧。郭重仆，见二子，曰：「恶言多矣，君请尽之。」公宴于五梧，武伯为祝，恶郭重，曰：「何肥也！」季孙曰：「请饮彘也。以鲁国之密迩仇雠，臣是以不获从君，克免于大行，又谓重也肥。」公曰：「是食言多矣，能无肥乎？」饮酒不乐，公与大夫始有恶。', '', '', '二十五年夏季，五月二十五日，卫出公逃亡到宋国。卫出公在藉圃修造了灵台，和大夫们在那里喝酒，褚师声子穿着袜子登上席子，卫出公发怒。褚师辩解说：“我脚上生疮，和别人不一样。如果见到了，君王会作呕的，因此不敢脱去袜子。”卫出公更加生气。大夫们都为褚师辩解，卫出公不同意。褚师退出。卫出公把手叉在腰上，说：“一定要砍断你的脚！”褚师听了这话，就和司寇亥一起坐上车子说：“今天的事情能够落个逃亡就是幸运了。”
卫出公回国的时候，夺取了公孙弥牟的封邑，夺取了司寇亥的政权。卫出公又派侍者把公文懿子的车子推到池塘里。当初，卫国人灭了夏丁氏，把他的家财赐给彭封弥子。弥子请卫出公喝酒，进献夏戊的女儿，卫出公宠爱她，让她做了夫人。她的弟弟期，是太叔疾的从外孙，小时候养在卫出公的宫中，卫出公让他做司徒。夫人的宠爱衰减，期也就有了罪过。卫出公使用三种匠人久久不让休息。卫出公派优狡和拳弥盟誓，而又很亲近信任他，所以褚师比、公孙弥牟、公文要、司寇亥、司徒期利用三种匠人和拳弥来发动叛乱，都拿着锐利的武器，没有武器的人拿着斧子，派拳弥进入公宫，而从太子疾的宫里呐喊攻打卫出公。鄄子士请求抵御。拳弥拉着他的手，说：“您固然勇敢，可是打算把国君怎么办？您没有见到过先君的结局吗？君王到哪里不能满足愿望呢？而且君王曾经在外面待过，难道就一定不能回来吗？现在不能那么做，众怒难犯。叛乱平定才容易离间作乱的人。”于是卫出公就动身出走。准备到蒲地去，拳弥说：“晋国没有信用，不行。”准备到鄄地去，拳弥说：“齐国和晋国在争夺我们，不行。”准备到泠地去，拳弥说：“鲁国不足以亲附，请到城鉏去，可以联系越国。越国有能干的国君。”于是就去了城鉏。拳弥说：“卫国的盗贼是不是会来袭击您，还不能知道，请快点离开，从我开始。”于是就装上宝物回到了卫国。
卫出公把士兵加以分散部署，利用祝史挥作为内应侵袭卫国。卫国人以此为患。公文懿子知道了，进见公孙弥牟，请求驱逐祝史挥。公孙弥牟说：“挥没有罪过。”懿子说：“他专权好利而又行为不轨，要是见到国君进入，会在前面引路的。如果驱逐他，一定出南门而去国君那里，越国最近得到诸侯，一定会请求他们出兵的。”祝史挥正在朝廷上，下朝后，懿子就派官吏把他从家里遣送走了。祝史挥出了城，住了两晚，想要回城，没有被接纳。过了五天，就住在外里，于是就受到卫出公的宠信，派他到越国去请求出兵。
六月，哀公从越国回来，季康子、孟武伯到五梧迎接。郭重为哀公驾车，见到他们两位，回来对哀公说：“这两位的坏话多着呢，请君王当面一一追究。”哀公在五梧设宴，武伯祝酒，讨厌郭重，说：“你为什么那么肥胖？”季康子说：“请罚彘喝酒！由于鲁国紧挨着仇敌，臣下因此不能跟随君王，才得免于远行，可是他又认为奔波辛苦的重长得肥胖。”哀公说：“这个人吃自己的话吃多了，能不肥胖吗？”大家虽然喝酒但都不高兴，哀公和大夫从此就互相有了厌恶感。', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf702cee9a0c24edabcc", "shortContent": "先言“人之奇”。据《明史·王廷陈传》载，王廷陈“幼好弄，颖慧绝人”，“髻年缀文，不假师授”。少喜玩耍，经常遭到父亲的训斥与殴打，受打时辄大呼：“大人奈何虐海内名士耶？”正德十二年（1517）进士。选庶吉士。恃才放肆，赋《乌母谣》讽刺其师石珤，与同馆舒芬疏谏武宗南巡，受杖，改吏科给事中。出知裕州。旷达不羁，不习为吏。以打骂巡按御史喻茂坚系狱，削籍归里。居二十余年，纵酒倡乐，益放荡自废。常穿红紫窄袖衫...", "authors": ["孙福轩"], "pressName": "上海辞书出版社"}]', '', 'indent', 1559296797, '5cf08a9b7b968a0076978973', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643122, '左传 · 哀公 · 哀公二十六年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【传】二十六年夏五月，叔孙舒帅师会越皋如、后庸、宋乐茷，纳卫侯。文子欲纳之，懿子曰：「君愎而虐，少待之，必毒于民，乃睦于子矣。」师侵外州，大获。出御之，大败。掘褚师定子之墓，焚之于平庄之上。文子使王孙齐私于皋如，曰：「子将大灭卫乎，抑纳君而已乎？」皋如曰：「寡君之命无他，纳卫君而已。」文子致众而问焉，曰：「君以蛮夷伐国，国几亡矣。请纳之。」众曰：「勿纳。」曰：「弥牟亡而有益，请自北门出。」众曰：「勿出。」重赂越人，申开守陴而纳公，公不敢入。师还，立悼公，南氏相之，以城锄与越人。公曰：「期则为此。」令苟有怨于夫人者，报之。司徒期聘于越。公攻而夺之币。期告王，王命取之。期以众取之。公怒，杀期之甥之为大子者。遂卒于越。
宋景公无子，取公孙周之子得与启，畜诸公宫，未有立焉。于是皇缓为右师，皇非我为大司马，皇怀为司徒，灵不缓为左师，乐茷为司城，乐朱锄为大司寇。六卿三族降听政，因大尹以达。大尹常不告，而以其欲称君命以令。国人恶之。司城欲去大尹，左师曰：「纵之，使盈其罪。重而无基，能无敝乎？」
冬十月，公游于空泽。辛巳，卒于连中。大尹兴空泽之士千甲，奉公自空桐入，如沃宫。使召六子，曰：「闻下有师，君请六子画。」六子至，以甲劫之，曰：「君有疾病，请二三子盟。」乃盟于少寝之庭，曰：「无为公室不利。」大尹立启，奉丧殡于大宫。三日，而后国人知之。司城茷使宣言于国曰：「大尹惑蛊其君而专其利，令君无疾而死，死又匿之，是无他矣，大尹之罪也。」得梦启北首而寝于卢门之外，己为鸟而集于其上，咮加于南门，尾加于桐门。曰：「余梦美，必立。」大尹谋曰：「我不在盟，无乃逐我，复盟之乎？」使祝为载书，六子在唐盂。将盟之。祝襄以载书告皇非我，皇非我因子潞、门尹得、左师谋曰：「民与我，逐之乎？」皆归授甲，使徇于国曰：「大尹惑蛊其君，以陵虐公室。与我者，救君者也。」众曰：「与之。」大尹徇曰：「戴氏、皇氏将不利公室，与我者，无忧不富。」众曰：「无别。」戴氏、皇氏欲伐公，乐得曰：「不可。彼以陵公有罪，我伐公，则甚焉。」使国人施于大尹，大尹奉启以奔楚，乃立得。司城为上卿，盟曰：「三族共政，无相害也。」
卫出公自城锄使以弓问子赣，且曰：「吾其入乎？」子赣稽首受弓，对曰：「臣不识也。」私于使者曰：「昔成公孙于陈，宁武子、孙庄子为宛濮之盟而君入。献公孙于卫齐，子鲜、子展为夷仪之盟而君入。今君再在孙矣，内不闻献之亲，外不闻成之卿，则赐不识所由入也。《诗》曰：『无竞惟人，四方其顺之。』若得其人，四方以为主，而国于何有？」', '', '', '二十六年夏季，五月，叔孙舒带兵会合越国的皋如、后庸、宋国的乐茷送卫出公回国，公孙弥牟想要接纳。懿子说：“国君执拗又暴虐，稍等一些时候，必定残害百姓，百姓就会跟您和睦了。”联军侵袭外州，大肆劫掠。卫军出去抵御，大败。卫出公发掘褚师定子的坟墓，把棺材放在平庄之上放火烧了。
公孙弥牟派王孙齐私下去见皋如，说：“您是打算大举灭亡卫国呢，还是把国君送回来就算了呢？”皋如说：“寡君的命令没有别的，只把卫君送回来就算了。”公孙弥牟召集大家征求意见，说：“国君带着蛮夷来攻打我国家，国家差一点灭亡了，请接纳他。”大家说：“不要接纳。”公孙弥牟说：“如果我逃亡对大家有好处，请让我从北门出去。”大家说：“不要出走。”公孙弥牟重重地贿赂越国人，大开城门接纳卫出公，城上守卫甚严，卫出公不敢进城。护送卫出公的联军退兵回去，卫国立了悼公，南氏辅助他，卫国把城鉏给越国人。卫出公说：“这是期干的。”命令如果对夫人有怨的可以报复。司徒期到越国聘问，卫出公攻打他并且夺走了财礼。司徒期报告越王，越王命令取回来，司徒期带了一批人又把财礼取了回来。卫出公发怒，杀死了太子，太子是司徒期的外甥。卫出公也就死在越国。
宋景公没有儿子，要了公孙周的儿子得和启养在公宫里，还没有立继承人。当时皇缓做右师，皇非我做大司马，皇怀做司徒，灵不缓做左师，乐茷做司城，乐朱鉏做大司寇，六卿三族共同听取政事，通过大尹上达国君。大尹经常不向宋景公报告，而按照自己的意图假称君命以发号施令。国内的人们厌恶他。司城想要除掉大尹，左师说：“随他去，让他恶贯满盈。权势重而没有基础，能够不失败吗？”
冬季，十月，宋景公在空泽游玩。初四日，死在连中。大尹出动空泽的甲士一千人，奉着宋景公的尸体从空桐进入国都，到了沃宫。派人召来六卿，说：“听说下邑有战事，国君请六卿一起谋划。”六卿到达，用甲士劫持他们说：“国君有重病，请诸位盟誓。”就在小寝院子里盟誓，说：“不做对公室不利的事！”大尹立启为国君，奉着棺材停放在祖庙里。三天以后国内的人们才知道这件事。司城乐茷派人在国内宣布说：“大尹蛊惑他的国君，专权好利，现在国君没有生病就死了。死了以后又藏匿遗体，没有别的好说，就是大尹的罪过。”
得梦见启头向北睡在卢门的外边，自己变作大乌鸦栖止在他的上面，嘴巴搁在南门上，尾巴搁在北门上。醒来以后说：“我的梦很好，一定立为国君。”
大尹和别人策划说：“我没有参加盟誓，恐怕会驱逐我吧！再跟他们盟誓吧！”让太祝制作盟书。六卿正在唐盂，准备和他盟誓。太祝襄把盟书的内容告诉皇非我。皇非我依靠乐茷、门尹得、左师谋划说：“百姓亲附我们，把他赶走吧！”于是都回去把武装发给部下，让他们在国都内巡行，宣布说：“大尹蛊惑他的国君，欺压虐待公室。亲附我们的人，就是救援国君的人。”大家说：“亲附你们！”大尹也巡行，宣布说：“戴氏、皇氏准备对公室不利，亲附我的，不要担心不发财。”大家说：“你和国君没有什么两样！”戴氏、皇氏想要攻打启，乐得说：“不行，他因为欺凌国君有罪，我们要是出兵攻打，罪就更大了。”让国内的人们把罪过加在大尹身上。大尹奉事启逃亡到楚国，于是就立得为国君。司城做了上卿，盟誓说：“三族共同掌握国政，不要互相残害！”
卫出公从城鉏派人用弓问候子赣，并且说：“我能回国吗？”子赣叩头受弓，回答说：“我不知道。”私下对使者说：“从前成公流亡到陈国，宁武子、孙庄子在宛濮结盟然后国君回国。献公流亡到齐国，子鲜、子展在夷仪结盟然后国君回国。现在国君再次流亡在外，内部没有听说有像献公时代的亲信，外部没有听说有像成公时代的大臣，那么赐就不懂得根据什么能回国。《诗》说：‘最强莫过于得到人才，四方将会顺服。’如果得到这样的人，四方把他作为主人，取得国家又有什么困难呢？”', NULL, '', 'indent', 1559296836, '5cf08ac17b968a0076978b25', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643123, '左传 · 哀公 · 哀公二十七年', NULL, 0, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '【传】二十七年春，越子使后庸来聘，且言邾田，封于骀上。
二月，盟于平阳，三子皆从。康子病之，言及子赣，曰：「若在此，吾不及此夫！」武伯曰：「然。何不召？」曰：「固将召之。」文子曰：「他日请念。」
夏四月己亥，季康子卒。公吊焉，降礼。
晋荀瑶帅师伐郑，次于桐丘。郑驷弘请救于齐。齐师将兴，陈成子属孤子三日朝。设乘车两马，系五色焉。召颜涿聚之子晋，曰：「隰之役，而父死焉。以国之多难，未女恤也。今君命女以是邑也，服车而朝，毋废前劳。」乃救郑。及留舒，违谷七里，谷人不知。乃濮，雨，不涉。子思曰：「大国在敝邑之宇下，是以告急。今师不行，恐无及也。」成子衣制，杖戈，立于阪上，马不出者，助之鞭之。知伯闻之，乃还，曰：「我卜伐郑，不卜敌齐。」使谓成子曰：「大夫陈子，陈之自出。陈之不祀，郑之罪也。故寡君使瑶察陈衷焉。谓大夫其恤陈乎？若利本之颠，瑶何有焉？」成子怒曰：「多陵人者皆不在，知伯其能久乎？」中行文子告成子曰：「有自晋师告寅者，将为轻车千乘，以厌齐师之门，则可尽也。」成子曰：「寡君命恒曰：『无及寡，无畏众。』虽过千乘，敢辟之乎？将以子之命告寡君。」文子曰：「吾乃今知所以亡。君子之谋也，始衷终皆举之，而后入焉。今我三不知而入之，不亦难乎？」
公患三桓之侈也，欲以诸侯去之。三桓亦患公之妄也，故君臣多间。公游於陵阪，遇孟武伯于孟氏之衢，曰：「请有问于子，余及死乎？」对曰：「臣无由知之。」三问，卒辞不对。公欲以越伐鲁，而去三桓。秋八月甲戌，公如公孙有陉氏，因孙于邾，乃遂如越。国人施公孙有山氏。
悼之四年，晋荀瑶帅师围郑。未至，郑驷弘曰：「知伯愎而好胜，早下之，则可行也。」乃先保南里以待之。知伯入南里，门于桔柣之门。郑人俘酅魁垒，赂之以知政，闭其口而死。将门，知伯谓赵孟：「入之。」对曰：「主在此。」知伯曰：「恶而无勇，何以为子？」对曰：「以能忍耻，庶无害赵宗乎！」知怕不悛，赵襄子由是惎知伯，遂丧之。知伯贪而愎，故韩、魏反而丧之。', '', '', '二十七年春季，越王派后庸来鲁国聘问，并且商谈邾国土田的事，协议以骀上作为鲁、邾两国的边界。
二月，在平阳结盟，季康子等三位都跟随前去。季康子对结盟感到忧虑，谈到子赣，说：“如果他在这里，我不会到这地步的！”孟武伯说：“对。为什么不召他来？”季康子说：“本来是要召他的。”叔孙文子说：“过些时候请仍然记着他。”
夏季，四月二十五日，季康子死。哀公去吊丧，礼节降等。
晋国的知伯领兵进攻郑国，驻扎在桐丘。郑国的驷弘到齐国请求救援，齐军准备出发。陈成子集合为国战死者的儿子，通知他们三天内朝见国君。设置了一辆车两匹马，把册书放在五个口袋里。召见颜涿聚的儿子晋，说：“隰地那一役，你的父亲死在那里。由于国家多难，没有能抚恤你。现在国君命令把这个城邑给你，穿着朝服驾着车子去朝见，不要废弃你父亲的功劳。”于是就出兵救援郑国。到达留舒，离开穀地七里，縠地人竟没有发觉。到达濮地，天下雨军队不肯渡河。子思说：“大国的军队就在敝邑的屋檐底下，因此告急。现在军队不走，恐怕要来不及了。”陈成子披着雨衣拄着戈，站在山坡上，马不肯走出来的，就拉着它或者用鞭子抽打它。知伯听说，就收兵回去，说：“我占卜过进攻郑国，没有占卜和齐国作战。”派人对陈成子说：“大夫陈子，您这一族是从陈国分支出来的。陈国的断绝祭祀，是郑国的罪过，所以寡君派我来调查陈国被灭亡的实情，还要询问您是否为陈国忧虑。如果您对树干的倒置认为有利，那和我有什么关系？”陈成子发怒说：“经常欺压别人的人，都没有好结果，知伯难道能够长久吗？”
中行文子告诉陈成子说：“有一个从晋军中来告诉我的人说，晋军准备出动轻车一千辆，迫击齐军的营门，就可以全部歼灭齐军。”陈成子说：“寡君命令我说：‘不要追赶少数的士卒，不要害怕大批的敌人。’敌军即使超过一千辆战车，岂敢避开他们呢？我将要把您的话报告寡君。”中行文了说：“我到今天才知道自己为什么逃亡在外了。君子谋划一件事，对开始、发展、结果都要考虑到，然后向上报告。现在我对这三方面都不知道，就向上报告，不也是很难了吗？”
哀公担忧三桓的威胁，想要利用诸侯除掉他们；三桓也担忧哀公的狂妄，所以君臣之间嫌隙很多。哀公在陵坂游玩，在孟氏之衢碰上孟武伯，说：“请问您：我能得到善终吗？”孟武伯回答说：“我没法知道。”问了三次，始终辞谢不回答。哀公想要利用越国攻打鲁国而除掉三桓。秋季，八月初一日，哀公到了公孙有陉氏那里，由此又避居于邾国，后来就乘机去了越国。国内的人们拘捕了公孙有山氏。
悼公四年，晋国的知伯领兵包围郑国，还没有到达，郑国的驷弘说：“知伯刚愎而好胜，我们及早向他表示软弱无能，他就可以退走了。”于是就先守在南里以等候晋军。知伯攻进南里，又攻打桔秩之门。郑国人俘虏了酅魁垒，用卿的地位来引诱他投降，不答应，就把他的嘴塞住而杀死了他。晋军将要攻打城门，知伯对赵孟说：“攻进去！”赵孟说：“主人在这里。”知伯说：“你貌丑而缺乏勇气，为什么成了太子？”赵孟回答说：“因为我能够忍受耻辱，也许对赵氏宗族没有害处吧！”知伯不肯改悔，赵孟因此而憎恨知伯，知伯就想要灭亡赵襄子。知伯贪婪而刚愎自用，所以韩、魏反过来与赵氏合谋灭亡了他。
', NULL, '', 'indent', 1559296878, '5cf08aeaba39c80068b0e7d5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643290, '秋日诗', NULL, 1, 15, 3, 0, '孙绰', NULL, 35561, '5858fc9f8e450a006cbaf271', '晋', 'shi', '诗', '', '', '萧瑟仲秋月，飂戾风云高。
山居感时变，远客兴长谣。
疏林积凉风，虚岫结凝霄。
湛露洒庭林，密叶辞荣条。
抚菌悲先落，攀松羡后凋。
垂纶在林野，交情远市朝。
淡然古怀心，濠上岂伊遥。', '东晋士人在较为安定富足的生活环境中，没有采取鄙弃功名、追求自然的生活而是追求“心隐”，无论在朝在野，只求意而已。以优雅从容的风度，过着风流潇洒的生活，当时方内名士与方外高僧无不追求这种生活方式，而这一生活的主体，便是山水、清谈。此诗便是作者感于秋天大自然万木萧条而青松后凋的景象后，为了抒发自己逍遥林野，放情山水，淡泊宁静的情怀而创作的。
《秋日诗》就是这样一种环境下由东晋诗人孙绰创作的一首五言古诗。此诗前八句写秋景，描写万物的凋零以呈现生命的短暂；后六句写人生感悟，诗人悲悯菌的短命和羡慕松的长寿，思索人生该如何度过。此诗表达了宁可在垂纶林野中恬淡地度过一生，也不愿在市朝中冒着生命被戕害的危险去争名逐利的心境。全诗语言朴实无华，自然流畅。', '萧瑟：风吹树木的声音。
飂（biāo）戾：狂风的啸叫声。
时变：季节的变化。
虚岫（xiù）：空谷。
结：聚集。
凝霄：浓密的云雾。
湛露：浓重的露水。
荣条：茂盛的枝条。
菌：低等植物，多寄生，生命周期短。《庄子·逍遥游》：“朝菌不知晦朔。”
松：《论语·子罕篇·第二十八章》：“子曰：‘岁寒，然后知松柏之后凋也。’”
垂纶：垂钓。
交情：相互来往中建立感情。
市朝：集市和朝廷，喻争名逐利之地。
淡然：恬淡貌。
濠（háo）上：见《庄子·秋水》：“庄子与惠子游于濠梁之上。庄子曰：‘鲦鱼出游从容，是鱼之乐也。’惠子曰：‘子非鱼，安知鱼之乐？’庄子曰：‘子非我，安知我不知鱼之乐？’惠子曰：‘我非子，固不知子矣；子固非鱼也，子之不知鱼之乐全矣！’庄子曰：‘请循其本。子曰汝安知鱼乐云者，既已知吾知之而问我。我知之濠上也。’”庄子与惠子游于濠梁并辩论鱼是否知乐，即所谓“濠梁之游”，喻别有会心、心照不宣。
伊：助词，无义。', '萧条寂寥的仲秋时节，高远的天空中风起云涌，秋风呼啸。
住在山中感觉到了时节的变化，远离市朝的我吟起了歌谣。
疏落的树林里到处都是寒冷的秋风，空谷上空水汽凝结形成了云雾。
庭院中的树木上洒满了浓浓的露水，茂密的树叶纷纷飘离枝条。
看着菌类已经先凋零了，让人感到伤悲，攀着松树羡慕它的常绿不凋。
住在林野里垂钓，不再与市朝之人交往，交情也渐渐变淡了。
恬静淡泊的怀古之情油然而生，只要保持这种恬淡情怀，就距离庄子、惠子的濠上之游已经不远了。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecca734a8757d5a0ed4b9", "shortContent": "在东晋的诗坛上，曾经盛行过一种玄言诗。所谓玄言诗就是大谈老庄的玄之又玄、深微莫测的哲理诗。它们脱离了社会生活和人的感情，“理过其辞，淡乎寡味”。孙绰就是写这种诗的代表作家，像“仰观大造，俯览时物。机过患生，吉凶相拂。智以利昏，识由情屈”（《答许询诗》）之类，就很有点像歌诀和偈语。但是，他的这首《秋日诗》却又别是一番面貌，虽然旨归仍不离老庄，却并不高谈道家的玄虚哲理，而只是表明道家的人生态度，且这种...", "authors": ["谢楚发"], "pressName": "上海辞书出版社"}]', '（明末清初）王夫之《古诗评选》：序致顺，呼应切，然自以其平缓，不堕蹊径。唐人极有此种，而心力褊躁，筋骨刻露，一往无馀，但觉佣贱。', 'center', 1565615669, '5d50f5b243e78cf47e5cabae', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643522, '月令七十二候集解 · 谷雨', NULL, 5, 126, 0, 2, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '谷雨【去声】，三月中。自雨水后，土膏脉动，今又雨其谷于水也。雨读作去声，如‘雨我公田’之雨，盖谷以此时播种自上而下也。故《说文》云雨本去声，今风雨之雨在上声，雨下之雨在去声也。
萍始生。萍，水草也，与水相平，故曰萍。漂流随风，故又曰漂。《历解》曰：萍阳物，静以承阳也。
鸣鸠拂其羽。鸠，即鹰所化者，布谷也。拂，过击也；《本草》云：拂羽飞而翼拍其身，气使然也。盖当三月之时，趋农急矣，鸠乃追逐而鸣，鼓羽直刺上飞，故俗称布谷。
戴胜降于桑。戴胜一名戴鵀，《尔雅注》曰：头上有胜毛。此时恒在于桑，盖蚕将生之候矣。言降者，重之若天而下，亦气使之然也。', '', '', '', NULL, '', 'indent', 1574374995, '5db294f217b54d006c1f9b17', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643309, '茶录', NULL, 10, 425, 0, 1, '蔡襄', NULL, 10352, '57b9990d128fe10054cf2418', '宋', 'wen', '文', '', '序：
朝奉郎右正言同修起居注臣蔡襄上进：臣前因奏事，伏蒙陛下谕臣先任福建转运使日，所进上品龙茶最为精好。臣退念草木之微，首辱陛下知鉴，若处之得地，则能尽其材。昔陆羽茶经，不第建安之品；丁谓茶图，独论采造之本，至于烹试，曾未有闻。臣辄条数事，简而易明，勒成二篇，名曰茶录。伏惟清闲之宴，或赐观采，臣不胜惶惧荣幸之至。仅序。
后序：
臣皇佑中修起居注，奏事仁宗皇帝，屡承天问，以建安贡茶并所以试茶之状。臣谓论茶虽禁中语，无事于密，造茶录二篇上进。后知福州，为掌书记窃去藏稿，不复能记。知怀安县樊纪购得之，遂以刊勒行于好事者，然多舛谬。臣追念先帝顾遇之恩，揽本流涕，辄加正定，书之于石，以永其传。治平元年五月二十六日，三司使给事中臣蔡襄谨记。', '【上篇（论茶）】
色
茶色贵白。而饼茶多以珍膏油其面，故有青黄紫黑之异。善别茶者，正如相工之瞟人气色也，隐然察之于内。以肉理润者为上，既已未之，黄白者受水昏重，青白者受水鲜明，故建安人开试，以青白胜黄白。
香
茶有真香。而入贡者微以龙脑和膏，欲助其香。建安民间皆不入香，恐夺其真。若烹点之际，又杂珍果香草，其夺益甚。正当不用。
味
茶味主于甘滑。惟北苑凤凰山连属诸焙所产者味佳。隔溪诸山，虽及时加意制作，色味皆重，莫能及也。又有水泉不甘能损茶味。前世之论水品者以此。
藏茶
茶宜箬叶而畏香药，喜温燥而忌湿冷。故收藏之家，以箬叶封裹入焙中，两三日一次，用火常如人体温温，则御湿润。若火多则茶焦不可食。
炙茶
茶或经年，则香色味皆陈。于净器中以沸汤渍之，刮去膏油一两重乃止，以钤钳之，微火炙干，然后碎碾。若当年新茶，则不用此说。
碾茶
碾茶先以净纸密裹捶碎，然后熟碾。其大要，旋碾则色白，或经宿则色已昏矣。
罗茶
罗细则茶浮，粗则水浮。
候汤　
候汤最难。未熟则沫浮，过熟则茶沉，前世谓之蟹眼者，过熟汤也。沉瓶中煮之不可辩，故曰候汤最难。
熁盏
凡欲点茶。先须熁盏令热。冷则茶不浮。
点茶
茶少汤多，则云脚散；汤少茶多，则粥面聚。钞茶一钱七，先注汤调令极匀，又添注入环回击拂。汤上盏可四分则止，视其面色鲜白，著盏无水痕为绝佳。建安斗试，以水痕先者为负，耐久者为胜，故较胜负之说，曰相去一水两水。
【下篇（论茶器）】
茶焙
茶焙编竹为之裹以箬叶，盖其上，以收火也。隔其中，以有容也。纳火其下去茶尺许，常温温然，所以养茶色香味也。
茶笼
茶不入焙者，宜密封裹，以箬笼盛之，置高处，不近湿气。
砧椎
砧椎盖以砧茶；砧以木为之；椎或金或铁，取于便用。
茶钤
茶钤屈金铁为之，用以炙茶。
茶碾
茶碾以银或铁为之。黄金性柔，铜及喻石皆能生鉎，不入用。
茶罗
茶罗以绝细为佳。罗底用蜀东川鹅溪画绢之密者，投汤中揉洗以幂之。
茶盏
茶色白，宜黑盏，建安所造者绀黑，纹如兔毫，其坯微厚，熁之久热难冷，最为要用。出他处者，或薄或色紫，皆不及也。其青白盏，斗试家自不用。
茶匙
茶匙要重，击拂有力。黄金为上，人间以银铁为之。竹者轻，建茶不取。
汤瓶
瓶要小者易候汤，又点茶注汤有准。黄金为上，人间以银铁或瓷石为之。', '《茶录》，古代中国饮茶论著。共一卷，一作二卷。北宋蔡襄（1012—1067）作于北宋皇佑年间（1049—1053），是宋代重要的茶学专著。
蔡襄有感于陆羽《茶经》“不第建安之品”而特地向皇帝推荐北苑贡茶，由此写作《茶录》。
全书分为两篇。上篇论茶，分色、香、味、藏茶、炙茶、碾茶、罗茶、侯茶、熁盏、点茶十目，主要论述茶汤品质和烹饮方法。下篇论器，分茶焙、茶笼、砧椎、茶铃、茶碾、茶罗、茶盏、茶匙、汤瓶九目。是继陆羽《茶经》之后最有影响的论茶专著。', '朝奉郎、右正言、同修起居注：朝奉郎、右正言，皆为北宋官职名。起居注，是我国古代专门记录帝王言行的册籍。《隋书·经籍志》说：“起居注者，录记人君言行动止之事”。
建安：汉时县名，唐称建州，即今福建省建瓯县，其县境有建溪、凤凰山等，以产“北苑贡茶”而闻名。
丁渭茶图：丁渭（966～1037），字谓之，苏州长州（今江苏苏州）人。曾任福建漕使，督造贡茶，创制大龙凤团饼茶。著有《北苑茶录》三卷。
皇佑：宋仁宗年号，时间在公元1049～1053年间。
书之于石：宋英宗治平元年（1064），怀安令樊纪将蔡襄所书《茶录》，真楷小字，被视为书中绝品。
治平元年：治平为宋英宗年号。治平元年是公元1064年。三司使、给事中，皆为北宋时的官名。', '序：
任职朝中奉郎、右正言同修“起居注”的微臣蔡襄上书禀告皇帝陛下：前几天微臣有事向您上奏禀报，承蒙陛下指点说，微臣以前任职福建转运使的时候，向朝廷进献的贡茶中以北苑上品龙茶的品质最精良优异。微臣告退回家后，经常想连茶叶这样细微的草木品种，都有幸得到陛下的关心照顾鉴别欣赏，如果再能受到普遍重视，获得适合生长培育的环境，一定会施展它为人类之所用的一面。先朝陆羽的《茶经》，没有品第福建一带的茶；本朝丁谓的《茶图》，也只是论说了采摘、制茶的方法，至于怎样烹饮、如何鉴别茶茗的道理，从来没听人讲论过。微臣选举了几条这方面的个人见解，简明扼要地写成上下两篇，命名为《茶录》。我恭敬地祈请陛下在清闲空暇的时候，能偶然赏读一两页，或者采用一二条，微臣在万分惶恐害怕的同时，也会感到不胜荣幸之至。谨以此为序。
【上篇（论茶）】
色
茶的颜色以纯白为最好。然而饼茶大多用珍膏涂抹在饼面上，所以出现了青、黄、紫、黑各式各样的颜色。善于鉴别茶叶品质的人，就像专门看相的人不经意地看一下人的面色就会立刻看透那人的内在本质一样。茶以那些内部纹理润泽的为最好，它表面的颜色及形态都不是重要的。黄白色的饼茶煎煮后茶色昏暗浓重，青白色的饼茶煎煮后茶色鲜艳明亮，所以建安人鉴别茶，认为青白色的品质要胜过黄白色的。
香
茶本身具有天然的香味。在以前进奉朝廷的贡茶，常把龙脑掺入茶膏里，想要增加茶的香气。建溪一带的人们制茶时，都不加香料，怕它夺去了茶叶本身的香味。如果在烹煮点茶的时候，再掺杂上各种珍果香料，那对茶自身香味的侵夺就更厉害了。正确的方法是一律不加用其他香料。
味
茶味以甘甜爽口为最好。只有福建的北苑凤凰山生产焙制出的茶味道最好。由建溪隔开的其他山岭，虽然及时采摘、精细制作，但茶色、茶味都比较浓，比不上北苑凤凰山的茶品。还有，烹茶的泉水如果不轻冽甘甜，也能损害茶的味道。唐代专门研究煎茶用水的人已经谈论过。
藏茶
茶饼适合与嫩香蒲叶存放在一起而最怕沾染其他香料和药物，它适宜在温暖干燥的地方而最忌讳潮湿阴冷。因此，收藏茶饼的人家，应该把茶饼用嫩香蒲叶包裹封严放入茶焙里，每隔两三天就用类似于人体温度的小火慢慢烘烤一遍，以防止浸入潮气。如果火太大就会把茶烤焦不能喝了。
炙茶
茶饼存放超过一年，它的香、色、味就已陈旧消失。在喝之前应先放到洁净的容器里用滚开的水浇淋，刮去饼面的一二层油膏，用茶钤钳住，夹到小火上烤干，然后再碾碎茶饼。如果是当年的新茶，当然就不需要用“炙茶”这道工序。
碾茶
碾茶的时候应先用干净纸巾把茶饼包严捶碎，然后反复碾。最重要的是将它捶碎后要立刻碾，茶色才会变白，如果放置过了一个晚上，茶色就暗了。
罗茶
罗孔过密，罗出的茶末就精细，会飘浮在水面上；罗孔过粗，罗出的茶末就粗大，不易与水相溶。
候汤
掌握煎水的适宜程度最难。汤没有熟就点茶，茶末会漂浮在汤面，汤煎得过熟，茶叶会沉入水底，唐代人叫做“蟹眼”的汤就是因为过熟了。但煎水时水在瓶里有没有“鱼目”、“蟹眼”出现，煎水的人是看不见的，全凭借经验掌握的程度，所以说“候汤最难”。
熁盏
凡是点茶的时候，必须先用沸水将茶杯冲热。茶杯如果不预热，饽沫就飘浮不起来。
点茶
点茶时，茶少水多，会出现如同云脚一样散乱的形状；水少茶多，会出现如熬粥面一样的形状。正确的点茶方法是，用茶匙取一钱七分的茶末放在茶杯里，先注入一点汤调制均匀，再围着四周旋转增添注入汤水并用茶筅拍击拂动。当茶汤注入到茶杯的十分之四时就停止注水，这时候看上去茶色鲜亮纯白。挨着茶杯边沿的茶水不留痕印为最上等。建安一带人们比赛点茶，茶杯边沿先出现水痕的就算失败，长时间不出水痕的就算胜利。所以用斗茶比较谁胜谁败，也只是相差一水两水而已。
【下篇（论茶器）】
茶焙
茶焙用竹篾编织而成，表面裹上柔嫩的香蒲叶，上面用盖盖上，用来聚积火气。中间有隔层，以增加存茶的容量。焙茶时，炭火在茶焙底下，距离茶有一尺左右，要保持恒温，才能保养好茶的色、香、味。
茶笼
茶如果不存放在茶焙里，就应拿纸包裹密封严实，用嫩香蒲叶制成的茶笼装好，放在高处，防止湿气侵入。
砧椎
砧板与椎是用来捶碎茶饼的工具。砧板用木头制造，椎用黄金或者铁制造，只要方便使用就可以。
茶钤
茶钤是把黄金或者铁弯曲制成夹子形状，用来夹住茶饼在火上炙烤的器具。
茶碾
茶碾是用银或铁制造而成的。黄金生性柔软，铜和喻石都会生锈，不耐使用。
茶罗
茶罗越细密越好。罗面要使用四川东川县鹅溪所生产的细画绢中最细密的，先放到热水中将杂物揉洗干净后，再覆盖在罗底上。
茶盏
茶色力求纯白，所以适合使用黑色茶杯。建安制造的茶杯颜色黑中带红，釉表面上的白色细纹形状如同兔毫，它的坯胎略微有点厚，熁盏预热后长时间都不会冷却，是点茶比赛时选择的最好器具。其他地方出产的茶杯，有的坯胎薄，有的颜色紫红，都比不上建安造的黑釉兔毫杯。还有一种青白色的茶杯，点茶比赛的人自然不用它。
茶匙
茶匙的质量要重，这样才有力搅动汤水。以黄金制造的为上等品，民间是用银或铁制造的。竹子制造的太轻，点茶比赛时不实用。
汤瓶
煎水的瓶子要小，这样容易掌握煎水的适度，另外，在点茶加汤的时候有标准。以黄金制造的为上等品，民间是用银、铁或者用瓷石制造的。
后序：
微臣在北宋年间，曾参与恭修“起居注”，经常向先帝仁宗皇帝上奏禀告事情，多次承蒙先帝垂问，关于询问建安贡茶的鉴别烹饮状况。微臣认为，这虽然是先帝在居住地方垂问的话，但并不是重要保密的事情，因此写成《茶录》两篇，想要上奏给先帝。后来我到福州任太守，文稿被掌管书启的掌书记偷走，就再也背写不出。随后这两篇文稿被怀安县令樊纪买去，并刻石拓印流传在一些爱好茶事的人手中，但文稿错乱谬误很多。微臣追忆怀念先帝当年关心照顾知遇的大恩，禁不住抱着拓本流泪不止，于是更加详细地校正，并将书刻在石头上，以永远流传于世。治平元年（1064）五月二十六日三司使给事中微臣蔡襄谨记。', NULL, '', 'indent', 1566596747, '5d5fedfed5de2b006cf92b59', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643320, '幽兰', NULL, 6, 4, 0, 1, '陈毅', NULL, 36772, '583d94f2a22b9d006a953ae7', '当代', 'shi', '诗', '', '', '幽兰在山谷，本自无人识。
只为馨香重，求者遍山隅。', '', '山谷：一作“深谷”。', '', NULL, '', 'center', 1582062611, '5d6beefbc05a8000733f93b4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643321, '兰亭诗六首（其三）', NULL, 2, 90, 2, 0, '王羲之', NULL, 10033, '57b8fc225bbb50005b7801ea', '晋', 'shi', '诗', '', '', '三春启群品，寄畅在所因。
仰望碧天际，俯磐绿水滨。
寥朗无崖观，寓目理自陈。
大矣造化功！万殊莫不均。
群籁虽参差，适我无非新。', '', '三春：指春天的第三个月，暮春。
群品：万事万物。
寄：把思想感情、希望、理想放在某人或某物上。
畅：表达。
因：相就，趋赴。
俯：低头，面向下。
磐：盘桓，逗留。
寥朗：空阔明朗。
无崖：同“无涯”，无穷尽，无边际。
观：景象。
寓目：犹过目，观看。
陈：分布，显示，呈现。
造化：自然界的创造者，亦指自然。
万殊：各不相同，亦指各种不同的现象、事物。
群籁：即指万籁，各种声响。
参差：不齐的样子。', '暮春时节万物复兴，寄情山水心有所凭。
抬头远望澄澈天宇，俯首低徊绿水之滨。
空阔明朗无边景观，过目难忘其理自陈。
自然功绩何其伟大！千百事物没有不均。
各种声响尽管不一，对人来说全都崭新。', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecca7dbb8b379ee0a0e1a", "shortContent": "东晋穆帝永和九年（353）三月三日，王羲之、孙绰、谢安与孙统等四十一人，在会稽（今浙江绍兴）境内的兰亭举行了一次集会，按古人上巳修禊的习俗，要在三月第一个巳日临水洗濯，去除不祥，诗人们在曲水旁，将盛着酒的杯子从曲水上游放出，让它顺着流水漂下，流到谁的面前，谁就畅饮此杯，临流赋诗。今存王羲之的《兰亭诗》共有六首，这是其中之一。时人将这些诗汇集起来，成为《兰亭集诗》，王羲之为此写了一篇序文，那就是千古...", "authors": ["王镇远"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "6470a253a5f1e74f95828ebd", "shortContent": "东晋穆帝永和九年(353)三月三日，王羲之、孙绰、谢安与孙统等四十 一人，在会稽(今浙江绍兴)境内的兰亭举行了一次集会，按古人上巳修禊 的习俗，要在三月第一个巳日临水洗濯，去除不祥，诗人们在曲水旁，将盛 着酒的杯子从曲水上游放出，让它顺着流水漂下，流到谁的面前，谁就畅 饮此杯，临流赋诗。今存王羲之的《兰亭诗》共有六首，这是其中之一。时 人将这些诗汇集起来，成为《兰亭诗集》，王羲之为此写了一篇序文，...", "authors": ["王镇远"], "pressName": "上海辞书出版社"}]', '', 'center', 1567442941, '5d6cd501ba39c80067a1d2ed', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643335, '水调歌头 · 与李长源游龙门', NULL, 22, 819, 3, 0, '元好问', NULL, 10074, '57b9127ca633bd00665de11d', '金', 'ci', '词', '', '', '滩声荡高壁，秋气静云林。回头洛阳城阙，尘土一何深。前日神光牛背，今日春风马耳，因见古人心。一笑青山底，未受二毛侵。
问龙门，何所似，似山阴。平生梦想佳处，留眼更登临。我有一卮芳酒，唤取山花山鸟，伴我醉时吟。何必丝与竹，山水有清音。', '《水调歌头 · 与李长源游龙门》这首词记录了元好问游伊河龙门段的所见所感。从美景出发，由景道情，表现词人远离尘俗，洁身自好，独善其身的思想感情。', '', '', '[{"bookId": "60fc038f34bfda01e0e8f5ac", "bookTitle": "唐宋词鉴赏辞典（新一版）", "articleId": "610e751a03572034f65964a2", "shortContent": "在《遗山乐府》中，写游览踪迹者不少。由于词人所采取的笔法不同，词中所呈现的色彩也各异。或着力于写景，给人以美的感受；或景与情交替出现，又互为包容，增加了景物表现的内涵。本词则借景叙情，以烟霞泉石的真淳古淡，反衬出尘世的污浊纷攘，寄托了词人蓄之已久的“尘泥免相涴，梦寐见清颍”（《出京》诗）的思想情趣。\n词人善于以雄杰之笔，写阔大气象。首先摄入其笔底的，是“滩声”之壮，“云林”之静。龙门，又称伊阙，在...", "authors": ["赵兴勤"], "pressName": "上海辞书出版社"}, {"bookId": "60d8a564a06dc908f044e53c", "bookTitle": "宋词鉴赏辞典（新一版）", "articleId": "610ec61b5e272d4b2254e0a9", "shortContent": "在《遗山乐府》中，写游览踪迹者不少。由于词人所采取的笔法不同，词中所呈现的色彩也各异。或着力于写景，给人以美的感受；或景与情交替出现，又互为包容，增加了景物表现的内涵。本词则借景叙情，以烟霞泉石的真淳古淡，反衬出尘世的污浊纷攘，寄托了词人蓄之已久的“尘泥免相涴，梦寐见清颍”（《出京》诗）的思想情趣。\n词人善于以雄杰之笔，写阔大气象。首先摄入其笔底的，是“滩声”之壮，“云林”之静。龙门，又称伊阙，在...", "authors": ["赵兴勤"], "pressName": "上海辞书出版社"}]', '', 'indent', 1568132689, '5d775dbfc8959c0068198db1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643336, '落日前墟望赠范广州云', NULL, 0, 115, 2, 0, '何逊', NULL, 35869, '5858fcdb570c350069185ee0', '南北朝', 'shi', '诗', '', '', '缘沟绿草蔓，扶楥杂华舒。
轻烟澹柳色，重霞映日馀。
遥遥长路远，寂寂行人疏。
我心怀硕德，思欲命轻车。
高门盛游侣，谁肯进畋渔。', '古诗《落日前墟望赠范广州云》是南朝著名诗人何逊写给朋友范云的一首五言诗。全诗前半写景，后半抒情。', '', '', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610ecccb7d0ac1145495f385", "shortContent": "范云是南朝著名诗人，历仕宋、齐、梁三朝。齐初，曾任竟陵王萧子良主簿，是“竟陵八友”之一。何逊少年，英才杰出，深为范云爱重。史称：“逊八岁能赋诗，弱冠州举秀才。南乡范云见其对策，大相称赏，因结忘年交好。自是每一文一咏，云辄嗟赏。”（《梁书·何逊传》）此诗写于何逊“州举秀才”之后，其时范云任广州刺史。这位青年秀才投诗范云，对德高望重的老前辈深表仰慕之情，并希望能在仕途上得到他的援助。全诗前半写景，后半...", "authors": ["易平"], "pressName": "上海辞书出版社"}, {"bookId": "645d0d5c82c61b4ac57e9002", "bookTitle": "古诗三百首鉴赏辞典", "articleId": "6470ac0130675327e1bbf8a8", "shortContent": "范云是南朝著名诗人，历仕宋、齐、梁三朝。齐初，曾任竟陵王萧子良主 簿，是“竟陵八友”之一。何逊少年，英才杰出，深为范云爱重。史称:“逊八岁 能赋诗，弱冠州举秀才。南乡范云见其对策，大相称赏，因结忘年交好。自是 每一文一咏，云辄嗟赏。”(《梁书·何逊传》)此诗写于何逊“州举秀才”之后，其 时范云任广州刺史。这位青年秀才投诗范云，对德高望重的老前辈深表仰慕 之情，并希望能在仕途上得到他的援助。全诗前半...", "authors": ["易", "平"], "pressName": "上海辞书出版社"}]', '', 'center', 1568139076, '5d7776bfeaa375006911b921', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643371, '法书论', NULL, 7, 1, 1, 0, '蔡希综', NULL, 37055, '5d85c39cd5de2b00733fa826', '唐', 'wen', '文', '', '', '余家历世皆传儒素，尤尚书法。十九代祖东汉左中郎邕，有篆籀八体之法。六世祖陈侍中景历；五世伯祖隋蜀王府记室君知，咸能楷隶，俱为时所重。从叔父右卫率府兵曹参军有邻，继于八体之迹。第四兄缑氏主簿希逸、第七兄洛阳尉希寂，并深工章隶，颇为当代所称也。
周宣王史籀作大篆，秦始皇程邈改为隶书，东汉上谷王次仲以隶书改为楷法；仲，又以楷法变为八分。其后继迹者，伯喈得之极，元常或其亚。草圣始自楚屈原，章草兴于汉章帝，楷法则曹喜、师宜官、梁鹄、皇象、罗景、赵嗣、邯郸淳、胡昭、杜度，穷草法则崔瑗、崔寔、张芝、张昶、索靖、卫瓘、卫恒、羲、献，宋、齐之间，王僧虔、羊欣、李镇东、萧子云、萧思话、陶隐居、永禅师，唐初房乔、杜如晦、杨师道、裴行俭、高士廉、欧阳询、虞世南、陆柬之、褚遂良、薛稷，其次有琅琊王昭宗、颖川钟绍京、范阳张庭珪，亦深有意焉。父兄子弟相继其能者，东汉崔瑗及寔，弘农张芝与弟昶，河东卫瓘及子恒，颖川钟繇及子会，琅琊王羲之及子献之，西河宋令文及子之望，东海徐峤之及子浩，兰陵萧诚及弟谅，如是数公等，并遭盛明之世，得从容于笔砚。始其学也，则师资一同，及尔成功，乃菁华各擅，亦犹绿叶红花，长松翠柏，虽沾雨露，孕育于阴阳，而盘错森梢，蘴茸艳逸，各入门自媚，讵闻相下，咸自我而作古，因奇而立度，若盛传于代，以为贻家之宝。是八体之极，是归乎钟蔡；草隶之雄，是归乎张王。此四贤者，自叹百载来未之逮也。
右军《笔阵图》云：“夫三端之妙，莫先用笔。”昔李斯见周穆王书，七日兴叹，哂其无骨。蔡尚书入鸿都观碣，十旬不返，嗟其出群。近代已来，多不师古，而缘情弃道，才弃姓名。夫书匪独不调端周正，先籍其笔力。始其作也，须急向疾，不鹰视鹏游，信之自然，犹鳞之得水，羽之乘风，高下恣情，流转无碍。蔡中郎云：“欲书先适意任情，然后书之。若迫于事，虽中山之毫，不能佳也。次须正坐静虑，随意所拟，言不出口，气不再息，则无不善矣。”凡欲结构字体，未可虚发，皆须象其一物，若乌之形，若虫食木，若山若树，若云若雾，纵横有托，运用合度，可谓之书。昔钟繇与胡昭俱能为行狎书。繇初师刘德升，后传蔡邕笔法，由是学之致妙。繇临终，于囊中出授子会曰：“吾精思三十余年，行坐未尝忘此。常读佗书，未能终尽，惟学其字，每见万类悉书象。若之止息一处，则画其地，周广数步；若在寝息，则画其被，皆为之穿。”用其功如此。
右军云：“夫书之为意，取数非一。”故纸者，阵也；笔者，刀槊也；墨者，凿甲也；水砚者，城池也；本领者，将帅也；心意者，副将也；结构者，谋略也；扬笔之次，吉凶之兆也；出入者，号令也；屈折者，杀戮也。若欲书，先干研墨，凝神静虑，预想字形大小偃仰，平直振动，令筋脉相连，意在笔前，然后作字。若平直相似，状如算子，便不是书，但得其点画耳。昔宋翼常作此书。翼繇外甥也，叱之。翼遂三年不敢见繇，潜心改迹，每画一波，常三过折，每作一点，常隐锋为之，由此而成。晋太康年，有人于许下破宋公墓，遂获此法。审此而行，用笔之理明矣。
右军云：“若作点，必须悬手而为之，若作波抑而复曳。忽一点失所，若美女之眇一目，一画失所，如肚士之折一肱。”可谓难矣。每辽皆须骨气雄中，爽爽然有飞动之态，屈折之状，如钢铁为钩，牵掣之踪，若劲针直下，主客胜负，皆须姑息，先作者主也，后为者客也，既构筋力，然后装束，必须举措合则，起发相承，轻浓似云雾往来，舒卷如林花间吐。每书一纸，或有重字，亦须字字意故殊。何延之云：“右军书《兰亭》，每字皆措别体。”盖其理也，时议多之。
右军每叹曰：“夫书者，玄妙之伎，自非达人君子，不可与谈斯道。”右军之迹，流行于代众矣，就中《兰亭序》《黄庭经》《太师箴》《乐毅论》《大雅吟》《东方先生画替文》，咸偶得其精妙。故陶隐居云：“右军此数帖，皆笔力鲜媚，纸墨精新，不可复得。”右军亦自讶焉，或佗日更书，无复似者。乃叹而言曰：“此神助耳，何吾力能致。”又云：“吾少学卫夫人书，将谓大能。及过江游诸名山，见李斯、曹喜书；之许，见钟繇、梁鹄书；又之洛，见蔡邕石经；又于从兄洽处，见张昶《华岳碑》，始知学卫夫人书，徒费年月。于是遂改本师，新于众碑焉。”是知学成非一师之能致，非好奇博艺之士，不能存之。予顷尝为一《体书赋》，亦略陈梗概，今复论之，用臻其理。
夫始下笔，须藏锋转腕，前缓后急，字体形势，壮如虫蛇相钩连，意莫令断，乃须简略为尚，不贵繁冗。至如棱侧起伏，随势所立，大抵之意，圆规最妙，其有误发，不可再摩，恐失其笔势。若字有点处，须空中遥掷，下其势犹高峰坠石。又下笔意如放箭，箭不欲迟，迟则中物不入。然则思于草迹，亦须时时象其篆势。八分、章草、古隶等体，要相合杂，发人意思，若直取俗事，则不能先发于笺毫。张伯英偏工于章草，代莫过之。每与人书，下笔必为楷，则云：“匆匆不暇草书。”何者？若不以静思闲雅发于中虑，则失其妙用也。以此言之，草法尤难。仲将每见伯英书，称为草圣。卫瓘、索靖俱效于张，亦各得其妙。议者以为卫得伯英之筋，索得伯英之肉。汉魏以来，章法弥盛。晋世右军，特出不群，颖悟斯道，乃除繁就省，创立制度，谓之新草。今传《十七帖》是也。子敬以来，学者虽各擅其美，故亦抑之远矣。
迩来率府长史张旭，卓然孤立，声被寰中，意象之奇，不有不全其古制，就王之内，弥更减省。或有百字、五十字，字所未形，雄逸气象，是为天纵。又乘兴之后，方肆其笔，或施于壁，或扎于屏，则群象自形，有若飞动。议者以为张公亦小王之再出也。旭常云：“或问书之妙，何得齐古人？”曰：妙在执笔令其圆畅，勿使拘挛；其次识法须口传手授，勿使无度，所谓笔法也；其次在布置不慢不越，巧使合宜；其次变通适怀，纵合规矩；其次纸笔精佳。五者备矣，然后能齐古人。”仆尝闻褚河南用笔如印印泥，思所以，久不悟。后因阅江岛间，平沙细地，令人欲书，复偶一利锋，便取书之，崄劲明丽，天然媚好，方悟前志。此荩草正用笔，悉欲令笔锋透过纸背，用笔如画沙印泥，则成功极致自然，其迹可得齐于古人。
又崔长史云：“其为书也，推意结字，以断天下之疑；垂明示象，以纪天下之德。山川草木，反覆于寸纸之间；日月星辰，回环于尺牍之上。”汉光武以中兴之主，急在安人，乃至去上林池御之官，废骋望弋猎之事，其以手赐万国者，皆一扎十行，细书成文也。灵帝时，中郎伯喈硕学多闻，经籍去圣人久，俗求正宗六经。灵帝许之，遂令伯喈丹书于碑，使工镌刻，立于太学门外。于时晚儒后学，咸取正焉，观视摹写，车乘填溢。岂惟一台推妙，十部称贤而已哉！古之君子，夙夜强学，不宝尺璧而重寸阴，或缉柳编蒲，或聚萤映雪，寝食靡暇，冀其业广，匪直禄取一朝，故亦誉流千祀，勉旃为之。', '收录版本见南宋陈思《书苑菁华》十二，与《全唐文》三百六十五所收不同。
蔡希综《法书论》是盛唐时期重要的书法理论著作，其全文首见于南宋陈思《书苑菁华》。唐代未见著录，宋代《宣和书谱》及各种类书间有提及。《法书论》文辞雅驯，体现了蔡氏一门良好的书法素养，具有盛唐时期书法文献的鲜明特征，而行文中却又不免窜入唐代流行的伪篇，致使一些内容重出、文辞浅陋。这些窜入的部分基本集中对蔡邕、钟繇、王羲之三者笔法的解读上。囿于文献寂寥，已不能明确认定窜入的部分是来自原文的注解，抑或流传的过程故意为之。', '', '', NULL, '', 'indent', 1569077058, '5d85c59a17b54d00682716a1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643413, '论书', NULL, 39, 3406, 4, 0, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'wen', '文', '', '', '书必有神、气、骨、血、肉，五者阙一，不为成书也。
书法备于正书，溢而为行草。未能正书，而能行草，犹未尝庄语，而辄放言，无是道也。
人貌有好丑，而君子小人之态，不可掩也；言有辩讷，而君子小人之气，不可欺也；书有工拙，而君子小人之心，不可乱也。
凡世之所贵，必贵其难。真书难于飘扬，草书难于严重，大字难于结密而无间，小字难于宽绰而有余。
把笔无定法，要使虚而宽。欧阳文忠公谓余，当使指运而腕不知，此语最妙。方其运也，左右前后，却不免攲侧，及其定也，上下如引绳，此之谓笔正。柳诚悬之言良是，古人得笔法有所自，张长史以剑器，容有是理，雷太简乃云闻江声而笔法进，文与可亦言见蛇斗而草书长，此殆谬矣。
献之少时学书，逸少从后取其笔而不可，知其长大必能名世。仆以为知书不在于笔牢，浩然听笔之所之，而不失法度，乃为得之。然逸少所以重其不可取者，独以其小儿子用意精至，猝然掩之，而意未始不在笔。不然，则是天下有力者，莫不能书也。
笔成冢，墨成池，不及羲之即献之；笔秃千管，墨磨万锭，不作张芝作索靖。
书初无意于佳乃佳尔。草书虽是积学乃成，然要是出于欲速。古人云“匆匆不及草书”，此语非是。若匆匆不及，乃是平时亦有意于学，此弊之极，遂至于周越仲翼，无足怪者。吾书虽不甚佳，然自出新意，不践古人，是一快也。
王荆公书得五法之法，然不可学，无法故。仆书尽意作之似蔡君谟，稍得意似杨风子，更放似言法华。欧阳叔弼云：子书大似李北海。予亦自觉其如此。世或以为似徐书者，非也。', '《论书》见诸《东坡集》，历代翻刻本甚多，较为珍贵的是宋蜀刊大字本四十卷，十行十六字，缪荃荪有残帙，存第四、第五、第十、第十一等五卷；今有上海书画出版社的《历代书法论文选》选录本传世。', '阙：同“缺”。
庄语：《庄子》之语。
放言：大话，玄言。
辩讷：辩，善于辩解、辩论。讷，说话迟钝，不善言辞。
结密而无间：结构紧密而不散疏。宽绰而有余:结体疏朗而宽松。
虚而宽：虚空而宽松，指执笔不要僵化，要灵活自然。
欧阳文忠公：即欧阳修（1007—1072），北宋文学家、史学家。字永叔，号醉翁、六一居士。官至翰林学士、枢密副使、参知政事，谥文忠，故称文忠公。
柳诚悬：即柳公权（778—865），唐代著名书法家。字诚悬，京兆华原（今陕西耀县）人。书法骨力遒健，结构劲紧，自成面目，与颜真卿并称“颜柳”。
张长史：即张旭，唐书法家。字伯高，吴郡（今江苏苏州）人。官至金吾长史。草书最为知名，逸势奇状，连绵回绕，具有独特风格。
雷太简：即雷简夫，字太简。宋同州郃阳人。自号“山长”。宋朱长文《续书断》云：“简夫善真、行书，尝守雅州，闻江声以悟笔法，迹甚峻快，蜀中珍之”。
文与可：即文同（1018—1079），梓州永泰（今四川盐亭东）人。字与可，号笑笑先生，善诗、文、画竹，书法各体兼工。
献之：即王献之，东晋书法家。字子敬。王羲之第七子。逸少：即王羲之。东晋书法家，字逸少，琅邪（今属山东）人，官至右军将军，会稽内史，人称王右军。
笔成冢：宋朱长文《续书断》云：“释怀素字藏真，长沙人也，自云得草书三昧。始其临学勤苦，故笔颓萎，作笔冢以瘗文。”
墨成池：晋卫恒《四体书势》云：“弘农张伯英者，因而转精其巧，凡家之衣帛，必先书而后练之。临池学书，池水尽墨。”
张芝：字伯英，东汉时敦煌人，好书，善章草。
索靖：西晋书法家。字动安，敦煌人，张芝的姐孙。
匆匆不及草书：谓时间仓促来不及作草书。不及，亦作不暇。
周越：宋仁宗时人，字子发，能书，集古今人书并更体法。仲翼：宋仁宗时人。朱长文《墨池编》云：“工草、隶，颇有时誉。”
王荆公：即王安石（1021—1086）。北宋文学家、思想家、政治家。字介甫，号半山。封荆国公，世称荆公。《宣和书谱》谓荆公作行字，率多淡墨疾书，未尝经意。
言法华：释言法华，宋代僧人，工书。
欧阳叔弼：欧阳，字叔弼，宋时人，登进士乙科。知襄州。善文事，有文集。李北海：即李邕，字泰和，官至北海太守，人称李北海，唐代著名书法家。', '书法作品一定要有精神、气韵、骨力、肥瘦、浓淡，五者缺一则不成为书法。
书法要先学好正书，进而再学习行草。未能正书而写行草，就像未读过庄子之语，而动辄口出玄言，这不是真正的道家。
人的相貌有美丑之分，然君子与小人之态，无法掩饰；言语有雄辩与不善言辞之别，然君子与小人的气质，瞒不住人；书法有工有拙，然君子与小人的心性，却无法混淆。
大凡世人所贵，必贵其难。楷书难以飘洒生动，草书难以严肃持重，大字难以紧密不散，小字难以宽绰疏朗。
执笔没有定法，要使掌心虚空而放松。欧阳修对我说：应当以手指运笔而手腕不动，这句话说得真妙。运笔时，笔前后左右顺势运转，免不了会出现攲侧，当笔停止，笔管竖直，笔锋与笔管保持在一条直线上时，这就是笔正。柳公权的话有道理，他说古人笔法都有原由，张旭见公孙大娘舞剑器而得笔法，也许有一定的道理。雷太简说他闻江流水声而使笔法大进，文与可也说观蛇争斗而草书有长进，这就有点靠不住了。
王献之小时候学习书法，父亲王羲之从其后拽取毛笔而未能夺掉，便知献之长大之后必然能在书法方面名世。我认为善书者不在于执笔牢与不牢，信手写来而不失笔法，这才是懂得用笔的奥妙。然而王羲之看重献之的原因，在于他执笔稳重，精力集中，专注于笔。否则，天下有力气的人，个个都成书法家了。
废笔成堆，磨墨成池水，达不到羲之也能有献之的水平。笔用秃千管，墨磨研万锭，不成张芝也能比上索靖。
书法初始时不要刻意求佳，应放松随意，自然能达佳境。草书的学习虽然是靠积累而成但它的要点是为了书写的快速。古人说“时间仓促来不及作草书”，此语不对。如果匆匆忙忙之际来不及作草书，而是平时闲静之时用心于草书，这种错误的观点，一直影响到周越、仲翼等人，也就不足怪了。我的书法虽然不太好，然而能自出新意，不拘泥于古人，这是我最大的快乐。
王安石的书法得无法之法，正因为他自出机杼而“无法”，所以不可学。我的书法如果尽心创作，风格则如蔡襄，如果得意而作，风格则如杨凝式，如果放纵作书，风格则似言法华。欧阳说：“你的书法很像李北海。”我也感觉是这样。有人认为我的书法像徐浩，是不对的。', NULL, '', 'indent', 1569233864, '5d882b4217b54d006839b886', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643516, '月令七十二候集解 · 序', NULL, 2, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '夫七十二候，吕不韦载于《吕氏春秋》，汉儒入于《礼记·月令》，与六经同传不朽。后魏载之于历，欲民皆知，以验气序。然其禽兽草木，多出北方，盖以汉前之儒皆江北者也。故江南老师宿儒，亦难尽识。况陈澔之注，多为谬说，而康成、颖达，亦有讹处。予因是广取诸家之解，并《说文》《埤雅》等书，而又询之农牧，似得所归。然后并将二十四气什之于槀，以俟博识者鉴焉。', '旧本题“元吴澄撰”。其书以七十二候分属于二十四气，各训释其所以然。考《礼记·月令》，本无七十二候之说。《逸周书·时训解》乃以五日为一候。澄作《礼记纂言》亦引《唐月令》，分着五日一候之义，然不闻更有此书。其说以《经》文所记多指北方，非南方之所习见，乃博考《说文》、《埤雅》诸书，兼访之于农牧，着为此编。然考证名物，罕所发明。又既以蝼蝈为土狗，又载鼯鼠五技之说，自相矛盾。既以虹为日映雨气，又引虹首如驴之说，兼采杂书，亦乖解经之法。疑好事者为之，托名于澄也。（四库全书总目·经部·礼类存目）', '', '', NULL, '', 'indent', 1574374904, '5db26f3f6e9ba1006d04cd53', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643517, '月令七十二候集解 · 立春', NULL, 7, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '立春，正月节。立，建始也。五行之气往者过来者续于此。而春木之气始至，故谓之立也。立夏、秋、冬同。
东风解冻。冻结于冬，遇春风而解散；不曰春而曰东者，《吕氏春秋》曰：东方属木，木，火母也。然气温，故解冻。
 蛰虫始振。蛰，藏也；振，动也。密藏之虫，因气至，而皆苏动之矣。鲍氏曰：动而未出，至二月，乃大惊而走也。
鱼陟负冰。陟，升也。鱼当盛寒伏水底而遂暖，至正月阳气至，则上游而近冰，故曰负。', '', '', '', NULL, '', 'indent', 1574375048, '5db2703530863b006ce5bf7f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643518, '月令七十二候集解 · 雨水', NULL, 3, 126, 0, 2, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '雨【去声】水，正月中。天一生水，春始属木，然生木者，必水也，故立春后继之雨水，且东风既解冻，则散而为雨水矣。
獭祭鱼。獭，一名水狗，贼鱼者也。祭鱼，取鱼以祭天也。所谓豺獭知报本，岁始而鱼上游，则獭初取以祭。徐氏曰：獭祭圆铺，圆者，水象也；豺祭方铺，方者，金象也。
候雁北【《月令》、《汉书》作鸿雁北】。雁，知时之鸟。热归塞北，寒来江南，沙漠乃其居也。孟春阳气既达，候雁自彭蠡而北矣。
草木萌动。天地之气交而为泰，故草木萌生发动矣。', '', '', '', NULL, '', 'indent', 1574375009, '5db292fd30863b006ce6ff86', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643519, '月令七十二候集解 · 惊蛰', NULL, 6, 126, 0, 2, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '惊蛰，二月节。《夏小正》曰：正月启蛰，言发蛰也。万物出乎震，震为雷，故曰惊蛰。是蛰虫惊而出走矣。
桃始华【《吕氏春秋》作桃李华】。桃，果名，花色红，是月始开。
仓庚鸣，庚亦作鹒，黄鹂也。诗所谓‘有鸣仓庚’是也。《章龟经》曰：仓，清也；庚，新也；感春阳清新之气而初出，故名。其名最多，《诗》曰黄鸟，齐人谓之搏黍，又谓之黄袍，僧家谓之金衣公子，其色鵹黑而黄，又名鵹黄。谚曰黄栗留、黄莺莺儿，皆一种也。
鹰化为鸠。鹰，鸷鸟也，鹞鹯之属。鸠，即今之布谷，《章龟经》曰：仲春之时，林木茂盛，口啄尚柔，不能捕鸟，瞪目忍饥如痴而化，故名曰鸤鸠。《王制》曰鸠化为鹰，秋时也。此言鹰化为鸠，春时也。以生育肃杀气盛，故鸷鸟感之而变耳。孔氏曰：化者，反归旧形之谓。故鹰化为鸠，鸠复化为鹰，如田鼠化为鴽，则鴽又化为田鼠。若腐草为萤，鴙为蜃，爵为蛤，皆不言化，是不再复本形者也。', '', '', '', NULL, '', 'indent', 1574375004, '5db29353c05a800068f18fb3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643520, '月令七十二候集解 · 春分', NULL, 0, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '春分，二月中。分者，半也。此当九十日之半，故谓之分。秋同义。夏、冬不言分者，盖天地闲二气而已。方氏曰：阳生于子，终于午，至卯而中分，故春为阳中，而仲月之节为春分，正阴阳适中，故昼夜无长短云。
元鸟至。元鸟，燕也。高诱曰：春分而来，秋分而去也。
雷乃发声。阴阳相薄为雷，至此，四阳渐盛，犹有阴焉，则相薄乃发声矣。乃者，《韵会》曰：象气出之难也。注疏曰：发，犹出也。
始电。电，阳光也，四阳盛长，值气泄时而光生焉，故《历解》曰：凡声阳也，光亦阳也。《易》曰：雷电合而章。《公羊传》曰：电者，雷光是也。《徐氏》曰：雷阳阴电，非也。盖盛夏无雷之时，电亦有之，可见矣。', '', '', '', NULL, '', 'indent', 1574375001, '5db293d3a3180b00688b52be', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643521, '月令七十二候集解 · 清明', NULL, 3, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '清明，三月节。按《国语》曰：时有八风。历独指清明风为三月节，此风属巽故也。万物齐乎巽，物至此时皆以洁齐而清明矣。
桐始华。桐，木名。有三种：华而不实者曰白桐，《尔雅》所谓荣桐木是也；皮青而结实者曰梧桐，一曰青桐，《淮南子》曰梧桐断角是也；生于山冈、子大而有油者曰油桐，毛诗所谓梧桐不生山冈者是也。今始华者，乃白桐耳。按《埤雅》：桐木知日月、闰年，每一枝生十二叶，闰则十三叶，与天地合气者也。今造琴瑟者，以花桐木，是知桐为白桐也。
田鼠化为鴽【音如】。按《尔雅》注曰：鼫鼠，形大如鼠，头似兔，尾有毛，青黄色，好在田中食粟豆，谓之田鼠。《本草》《素问》曰：鴽，鹑也，似鸽而小。《尔雅 释鸟》：鴽，鴾母。郭注：䳺也，青州人呼为鴾母。鲍氏曰：鼠，阴类；鴽，阳类；阳气盛故化为鴽，盖阴为阳所化也。
虹始见【去声】。虹，虹蜺也，诗所谓螮蝀，俗读去声也。注疏曰：是阴阳交会之气，故先儒以为云薄漏日，日照雨滴则虹生焉，今以水噀日，自剑视之则晕为虹。朱子曰：日与雨交，倏然成质，阴阳不当交而交者，天地淫气也。虹为雄，色赤白，蜺为雌，色青白，然二字皆从虫。《说文》曰：似螮蝀状。诸书又云：尝见虹入溪饮水，其首如驴。恐天地闲亦有此种物也，但虹气似之借名也。', '', '', '', NULL, '', 'indent', 1574374998, '5db294836e9ba1006d06276d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643531, '月令七十二候集解 · 白露', NULL, 1, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '白露，八月节。秋属金，金色白，阴气渐重，露凝而白也。
鸿【淮南子作候】雁来。鸿大雁小，自北而来南也。不谓南乡，非其居耳。详见雨水节下。
元鸟归。元鸟，解见前，此时自南而往北也。燕乃南方之鸟，故曰归。
群鸟养羞【淮南子作群鸟翔】。三人以上为众，三兽以上为群；群，众也。《礼记注》曰：羞者，所羹之食；养羞者，藏之以备冬月之养也。', '', '', '', NULL, '', 'indent', 1574374963, '5db29c9530863b006ce75b9a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643523, '月令七十二候集解 · 立夏', NULL, 2, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '立夏，四月节。立字解见春。夏，假也。物至此时皆假大也。
蝼蝈鸣。蝼蝈，小虫，生穴土中，好夜出，今人谓之土狗是也；一名蝼蛄，一名石鼠，一名螜【音斛】，各地方言之不同也。《淮南子》曰：蝼蝈鸣，邱螾出，阴气始而二物应之。《夏小正》：三月螜则鸣是也。且有五能，不能成一技：飞不能过屋；缘不能穷木；泅不能渡谷；穴不能覆身；走不能先人。故《说文》称鼫为五技之鼠。《古今注》又以蝼名鼫，鼠可知。《埤雅》《本草》俱以为臭虫，陆德明、郑康成以为蛙，皆非也。
蚯蚓出。蚯蚓即地龙也【一名曲蟺】，《历解》曰：阴而屈者，乘阳而伸见也。
王瓜生。《图经》云：王瓜处处有之，生平野、田宅及墙垣，叶似栝楼、乌药，圆无丫缺，有毛如刺，蔓生，五月开黄花，花下结子如弹丸，生青熟赤，根似葛，细而多糁，又名土瓜，一名落鸦瓜，今药中所用也。《礼记》郑元注曰：即萆挈。《本草》作菝葜，陶隐居以辨其谬，谓菝葜自有本条，殊不知王瓜亦自有本条，先儒当时如不检书而谩言者，可笑。', '', '', '', NULL, '', 'indent', 1574374992, '5db2953117b54d006c1f9d27', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643524, '月令七十二候集解 · 小满', NULL, 8, 126, 0, 2, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '小满，四月中。小满者，物至于此小得盈满。
苦菜秀。《埤雅》以荼为苦菜，《毛诗》曰：谁谓荼苦【荼即茶也，故韵今茶注本作荼】。是也。鲍氏曰：感火之气而苦味成。《尔雅》曰：不荣而实，谓之秀，荣而不实，谓之英。此苦菜宜言英也。蔡邕《月令》以谓苦荬菜，非。
靡草死。郑康成、鲍景翔皆云靡草葶苈之属，《礼记注》曰：草之枝叶而靡细者。方氏曰：凡物感阳而生者则强而立，感阴而生者则柔而靡，谓之靡草，则至阴之所生也，故不胜至阳而死。
麦秋至。秋者，百谷成熟之期，此于时虽夏，于麦则秋，故云麦秋也。', '', '', '', NULL, '', 'indent', 1574374986, '5db29585a3180b00688b6262', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643525, '月令七十二候集解 · 芒种', NULL, 3, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '芒种【上声】，五月节。谓有芒之种谷可稼种【去声】矣。
螳螂生。螳螂，草虫也，饮风食露，感一阴之气而生，能捕蝉而食，故又名杀虫；曰天马，言其飞捷如马也；曰斧虫，以前二足如斧也，尚名不一，各随其地而称之。深秋生子于林木闲，一壳百子，至此时则破壳而出，药中桑螵蛸是也。
鵙【音局】始鸣。鵙，百劳也，《本草》作博劳；朱子《孟》注曰：博劳，恶声之鸟，盖枭类也。曹子建《恶鸟论》：百劳以五月鸣，其声鵙鵙然，故以之立名，似俗称浊温。故《埤雅》禽经注云：伯劳不能翱翔，直飞而已。《毛诗》曰：七月鸣鵙。盖周七月夏五月也。
反舌无声。诸书以为百舌鸟，以其能反复其舌故名，特注疏以为虾蟆，盖蛙属之舌尖向内，故名之。今辨其非者，以其此时正鸣，不知失者也，《易通卦验》亦名为虾蟆无声，若以五月正鸣，殊不知初旬见形后，形亦藏矣。陈氏曰：螳螂、鵙皆阴类，感微阴而或生或鸣，反舌感阳而发，遇微阴而无声也。', '', '', '', NULL, '', 'indent', 1574374983, '5db295edc05a800068f1a7a0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643526, '月令七十二候集解 · 夏至', NULL, 3, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '夏至，五月中。《韵会》曰：夏，假也；至，极也；万物于此皆假大而至极也。
鹿角解【音骇】。鹿，形小山兽也，属阳，角支向前与黄牛一同；麋，形大泽兽也，属阴，角支向后与水牛一同。夏至一阴生，感阴气而鹿角解。解，角退落也。冬至一阳生，麋感阳气而角解矣，是夏至阳之极，冬至阴之极也。
蜩【音调】始鸣【《月令》注疏作蝉始鸣】。蜩，蝉之大而黑色者，蜣螂脱壳而成，雄者能鸣，雌者无声，今俗称知了是也。按蝉乃总名，鸣于夏者曰蜩，即《庄子》云‘蟪蛄不知春秋者’是也。盖蟪蛄夏蝉，故不知春秋。鸣于秋者曰寒蜩，即楚辞所谓寒螀也。故《风土记》曰：蟪蛄鸣朝，寒螀鸣夕。今秋初夕阳之际，小而绿色声急疾者俗称都了是也。故《埤雅》各释其义，然此物生于盛阳，感阴而鸣。
半夏生。半夏，药名，居夏之半而生，故名。', '', '', '', NULL, '', 'indent', 1574374980, '5db2963c6e9ba1006d063691', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643527, '月令七十二候集解 · 小暑', NULL, 1, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '小暑，六月节。《说文》曰：暑，热也。就热之中，分为大小，月初为小，月中为大，今则热气犹小也。
温风至。至，极也，温热之风至此而极矣。
蟋【音悉】蟀【音率】居壁。一名蛩【音拱】，一名蜻蛚，即今之促织也。《礼记注》曰：生土中。此时羽翼稍成，居穴之壁，至七月则远飞而在野矣。盖肃杀之气初生则在穴，感之深则在野而斗。
鹰始击【《礼记》作鹰乃学习】。击，搏击也。应氏曰：杀气未肃，鸷猛之鸟始习于击，迎杀气也。', '', '', '', NULL, '', 'indent', 1574374977, '5db296b912215f0071c0d4a2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643528, '月令七十二候集解 · 大暑', NULL, 2, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '大暑，六月中。解见小暑。
腐草为萤。曰丹良，曰丹鸟，曰夜光，曰宵烛，皆萤之别名。离明之极，则幽阴至微之物亦化而为明也。《毛诗》曰：熠耀宵行。另一种也，形如米虫，尾亦有火，不言化者，不复原形，解见前。
土润溽【音辱】暑。溽，湿也，土之气润，故蒸郁而为湿；暑，俗称龌龊，热是也。
大雨时行。前候湿暑之气蒸郁，今候则大雨时行，以退暑也。', '', '', '', NULL, '', 'indent', 1574374973, '5db2970f17b54d006c1fb002', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643529, '月令七十二候集解 · 立秋', NULL, 1, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '立秋，七月节。立字解见春。秋，揫也。物于此而揫敛也。
凉风至【礼记作盲风至】。西方凄清之风曰凉风，温变而凉气始肃也。《周语》曰火见而清风戒寒是也。
白露降。大雨之后，清凉风来，而天气下降，茫茫而白者，尚未凝珠，故曰白露。降示秋金之白色也。
寒蝉鸣。寒蝉，《尔雅》曰寒螀，蝉小而青紫者。马氏曰：物生于暑者，其声变之矣。', '', '', '', NULL, '', 'indent', 1574374970, '5db2977a17b54d006c1fb5e1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643530, '月令七十二候集解 · 处暑', NULL, 3, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '处暑，七月中。处，止也。暑气至此而止矣。
鹰乃祭鸟，鹰，义禽也。秋令属金，五行为义，金气肃杀，鹰感其气始捕击诸鸟，然必先祭之，犹人饮食祭先代为之者也。不击有胎之禽，故谓之义。
天地始肃秋者，阴之始，故曰天地始肃。
禾乃登。禾者。谷连稿秸之总名。又，稻秫菰粱之属皆禾也。成熟曰登。', '', '', '', NULL, '', 'indent', 1574374966, '5db2985c30863b006ce734bc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643535, '月令七十二候集解 · 立冬', NULL, 0, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '立冬，十月节。立字解见前。冬，终也，万物收藏也。
水始冰。水面初凝，未至于坚也。
地始冻。土气凝寒，未至于拆。
雉入大水为蜃。雉，野鸡；郑康成、《淮南子》、高诱俱注蜃为大蛤。《玉篇》亦曰：蜃，大蛤也。《墨子》又曰：蚌，一名蜃，蚌非蛤类乎？《礼记之注》曰蛟属，《埤雅》又以蚌、蜃各释，似非蛤类。然按《本草》车螯之条曰：车螯，是大蛤，一名蜃，能吐气为楼台，又尝闻海旁蜃气成楼垣。《章龟经》曰：蜃大者为车轮岛屿，月闲吐气成楼，与蛟龙同也。则知此为蛤，明矣。况《尔雅翼》引周礼诸家，辩蜃为蛤甚明。《礼记之注》以谓雉，由于蛇化之说，故以雉子为蜃，《埤雅》既曰似蛇而大，腹下尽逆鳞，知之悉矣，然复疑之：一曰状似螭龙，有耳，有角，则亦闻而识之，不若《本草》、《章龟经》为是，即一物耳。大水，淮也，晋语曰：雉入于淮为蜃。', '', '', '', NULL, '', 'indent', 1574374948, '5db29eccba39c800738a40ad', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643536, '月令七十二候集解 · 小雪', NULL, 0, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '小雪，十月中。雨下而为寒气所薄，故凝而为雪。小者，未盛之辞。
虹藏不见。《礼记注》曰：阴阳气交而为虹，此时阴阳极乎辨，故虹伏。虹非有质，而曰藏，亦言其气之下伏耳。
天气上升，地气下降。
闭塞而成冬。天地变而各正其位，不交则不通，不通则闭塞，而时之所以为冬也。', '', '', '', NULL, '', 'indent', 1574374932, '5db29efaeaa375006cedaa53', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643537, '月令七十二候集解 · 大雪', NULL, 1, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '大雪，十一月节。大者，盛也。至此而雪盛矣。
鹖鴠不鸣。《禽经》曰：鹖，毅鸟也。似雉而大，有毛角，斗死方休，古人取为勇士，冠名可知矣，《汉书音义》亦然。《埤雅》云：黄黑色，故名为鹖。据此，本阳鸟，感六阴之极不鸣矣。若郭璞《方言》：似鸡，冬无毛，昼夜鸣，即寒号虫。陈澔与方氏亦曰求旦之鸟，皆非也。夜既鸣，何为不鸣耶？《丹铅余录》作雁，亦恐不然。《淮南子》作鳱鴠，《诗》注作渴旦。
虎始交。虎，猛兽。故《本草》曰能避恶魅，今感微阳气，益甚也，故相与而交。
荔挺出。荔，《本草》谓之蠡，实即马薤也。郑康成、蔡邕、高诱皆云马薤，况《说文》云：荔似蒲而小，根可为刷，与《本草》同。但陈澔注为香草，附和者即以为零陵香，殊不知零陵香自生于三月也。', '', '', '', NULL, '', 'indent', 1574374923, '5db29f4717b54d006c1ffc60', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643538, '月令七十二候集解 · 冬至', NULL, 0, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '冬至，十一月中。终藏之气至此而极也。
蚯蚓结。六阴寒极之时，蚯蚓交相结而如绳也。
麋角解。说见鹿角解下。
水泉动。水者，天一之阳所生，阳生而动，今一阳初生故云耳。', '', '', '', NULL, '', 'indent', 1574374917, '5db29f92ba39c800738a4750', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643539, '月令七十二候集解 · 小寒', NULL, 0, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '小寒，十二月节。月初寒尚小，故云。月半则大矣。
雁北乡【去声】。乡，向导之义。二阳之候，雁将避热而回，今则乡北飞之，至立春后皆归矣，禽鸟得气之先故也。
鹊始巢。喜鹊也，鹊巢之门每向太岁，冬至天元之始，至后二阳已得来年之节气，鹊遂可为巢，知所向也。
雉雊【音姤】。雉，文明之禽，阳鸟也；雊，雌雄之同鸣也，感于阳而后有声。', '', '', '', NULL, '', 'indent', 1574374913, '5db29fd130863b006ce778a4', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643540, '月令七十二候集解 · 大寒', NULL, 2, 126, 0, 1, '吴澄', NULL, 10797, '5858e5da570c350069179bd0', '元', 'wen', '文', '', '', '大寒，十二月中。解见前。
鸡乳。育也，马氏曰：鸡木畜，丽于阳而有形，故乳在立春节也。
征鸟厉疾。征，伐也；杀伐之鸟，乃鹰隼之属；至此而猛厉迅疾也。
水泽腹坚。陈氏曰：冰之初凝，水面而已，至此则彻，上下皆凝。故云腹坚。腹，犹内也。', '', '', '', NULL, '', 'indent', 1574374910, '5db2a066ba39c800738a4fb9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643546, '西厢记 · 第一本 · 楔子', NULL, 25, 41, 1, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[外扮老夫人上]老身姓郑，夫主姓崔，官拜前朝相国，不幸因病告殂。只生得个小女，小字莺莺，年一十九岁，针指女工，诗词书算，无不能者。老相公在日，曾许下老身之侄——乃郑尚书之长子郑恒——为妻。因俺孩儿父丧未满，未得成合。又有个小妮子，是自幼伏侍孩儿的，唤做红娘。一个小厮儿，唤做欢郎。先夫弃世之后，老身与女孩儿扶柩至博陵安葬；因路途有阻，不能得去。来到河中府，将这灵柩寄在普救寺内。这寺是先夫相国修造的，乃则天娘娘香火院，况兼法本长老又是俺相公剃度的和尚；因此俺就这西厢下一座宅子安下。一壁写书附京师去，唤郑恒来相扶回博陵去。我想先夫在日，食前方丈，从者数百，今日至亲则这三四口儿，好生伤感人也呵！
[仙吕][赏花时]夫主京师禄命终，子母孤孀途路穷；因此上旅榇在梵王宫。盼不到博陵旧家，血泪洒杜鹃红。
今日暮春天气，好生困人，不免唤红娘出来分付他。红娘何在？[俫扮红见科][夫人云]你看佛殿上没人烧香呵，和小姐散心耍一回去来。[红云]谨依严命。[夫人下][红云]小姐有请。[正旦扮莺莺上][红云]夫人着俺和姐姐佛殿上闲耍一回去来。[旦唱]
[幺篇]可正是人值残春蒲郡东，门掩重关萧寺中；花落水流红，闲愁万种，无语怨东风。[并下]', '', '', '', '[{"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42b12e6a6b501f9759f5", "shortContent": "本篇采自明何大抡辑《重刻增补燕居笔记》卷九。\n“问世间情为何物？直教人生死相许。”这部小说形象地诠释了“情”的内在意蕴。\n小说中的女主人公杜丽娘，在季春时节游园赏花，因触景生情而有“不得蚤成佳配，诚为虚度青春”之叹，乃至昼梦柳梦梅共谐欢好，梦醒后行坐不宁，若有所失。但封建社会旧式家庭模式的封闭性，窒息了她对美好生活的憧憬，她有欲不敢对人言，有情不知何处寻，即便面对的是至亲的生身母亲，她也不敢言说自...", "authors": ["曾庆雨"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572705820, '5dbd24146e9ba1006d6187b6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643547, '西厢记 · 第一本 · 第一折', NULL, 20, 41, 4, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[正末扮张生骑马引仆上开]小生姓张，名珙，字君瑞，本贯西洛人也，先人拜礼部尚书，不幸五旬之上，因病身亡。后一年丧母。小生书剑飘零，功名未遂，游于四方。即今贞元十七年二月上旬，唐德宗即位，欲往上朝取应，路经河中府过。蒲关上有一故人，姓杜名确，字君实，与小生同郡同学，当初为八拜之交。后弃文就武，遂得武举状元，官拜征西大元帅，统领十万大军，镇守着蒲关。小生就望哥哥一遭，却往京师求进。暗想小生萤窗雪案，刮垢磨光，学成满腹文章，尚在湖海飘零，何日得遂大志也呵！万金宝剑藏秋水，满马春愁压绣鞍。
[仙吕][点绛唇]游艺中原，脚跟无线、如蓬转。望眼连天，日近长安远。
[混江龙]向诗书经传，蠹鱼似不出费钻研。将棘围守暖，把铁砚磨穿。投至得云路鹏程九万里，先受了雪窗萤火二十年。才高难入俗人机，时乖不遂男儿愿。空雕虫篆刻，缀断简残编。行路之间，早到蒲津。这黄河有九曲，此正古河内之地，你看好形势也呵！
[油葫芦]九曲风涛何处显，则除是此地偏。这河带齐梁，分秦晋，隘幽燕；雪浪拍长空，天际秋云卷；竹索缆浮桥，水上苍龙偃；东西溃九州，南北串百川。归舟紧不紧如何见？却便似驽箭乍离弦。
[天下乐]只疑是银河落九天；渊泉、云外悬，入东洋不离此径穿。滋洛阳千种花，润梁园万顷田，也曾泛浮槎到日月边。话说间早到城中。这里一座店儿，琴童接下马者，店小二哥那里？[小二上云]自家是这状元店里小二哥。官人要下呵，俺这里有干净店房。[末云]头房里下，先撒和那马者！小二哥，你来，我问你：这里有甚么闲散心处？名山胜境，福地宝坊皆可。[小二云]俺这里有座寺，名日普救寺，是则天皇后香火院，盖造非俗：琉璃殿相近青霄，舍利塔直侵云汉。南来北往，三教九流，过者无不瞻仰；则除那里可以君子游玩。[末云]琴童料持下晌午饭！俺到那里走一遭便回来也。[仆云]安排下饭，撒和了马，等哥哥回家。[下][法聪上]小僧法聪，是这普救寺法本长老座下弟子。今日师父赴斋去了，着我在寺中，但有探长老的，便记着，待师父回来报知。山门下立地，看有甚么人来。[末上云]却早来到也。[见聪了，聪问云]客官从何来？[末云]小生西洛至此，闻上刹幽雅清爽，一来瞻仰佛像，二来拜谒长老。敢问长老在么？[聪云]俺师父不在寺中，贫僧弟子法聪的便是，请先生方丈拜茶。[末云]即然长老不在呵，不必吃茶；敢烦和尚相引，瞻仰一遭，幸甚！[聪云]小僧取钥匙，开了佛殿、钟楼、罗汉堂、香积厨、盘桓一会，师父敢待回来。[做看科][末云]是盖造得好也呵！
[村里迓鼓]随喜了上方佛殿，早来到下方僧院。行过厨房近西，法堂此，钟楼前面。游了洞房，登了宝塔，将回廊绕遍。数了罗汉，参了菩萨，拜了圣贤。[莺莺引红娘拈花枝上云]红娘，俺去佛殿上耍去来。[末做见科]呀！正撞着五百年前风流业冤。
[元和令]颠不刺的见了万千，似这般可喜娘的庞儿罕曾见。则着人眼花撩乱口难言，魂灵儿飞在半天。他那里尽人调戏（身单）着香肩，只将花笑拈。
[上马娇]这的是兜率宫，休猜做了离恨天。呀，谁想着寺里遇神仙！我见他宜嗔宜喜春风面，偏、宜贴翠花钿。
[胜葫芦]则见他宫样眉儿新月偃，斜侵入鬓边。[旦云]红娘，你觑:寂寂僧房人不到，满阶苔衬落花红。[末云]我死也！未语前先腼腆，樱桃红绽，玉粳白露，半晌恰方言。
[幺篇]恰便似呖呖莺声花外啭，行一步可人怜。解舞腰肢娇又软，千般袅娜，万般旖旎，似垂柳晚风前。
[红云]那壁有人，咱家去来。[旦回顾觑末下][末云]和尚，恰怎么观音现来？[聪云]休胡说，这是河中府崔相国的小姐。[末云]世间有这等女子，岂非天姿国色乎？休说那模样儿，则那一对小脚儿，价值百镒之金。[聪云]偌远地，他在那壁，你在这壁，系着长裙儿，你便怎知他脚儿？[末云]法聪，来、来、来，你问我怎便知，你觑：
[后庭花]若不是衬残红，芳径软，怎显得步香尘底样儿浅。且休题眼角儿留情处，则这脚踪儿将心事传。慢俄延，投至到栊门儿前面，刚那了上步远。刚刚的打个照面，风魔了张解元。似神仙归洞天，空馀下杨柳烟，只阙得鸟雀喧。
[柳叶儿]呀，门掩着梨花深院，粉墙儿高似青天。恨天，天不与人行方便，好着我难消遣，端的是怎留连。小姐呵，则被你兀的不引了人意马心猿？
[聪云]休惹事，河中开府的小姐去远了也。[末唱]
[寄生草]兰麝香仍在，佩环声渐远。东风摇曳垂杨线，游丝牵惹桃花片，珠帘掩映芙蓉面。你道是河中开府相公家，我道是南海水月观音现。
“十年不识君王面，始信婵娟解误人。”小生便不往京师去应举也罢。[觑聪云]敢烦和尚对长老说知：有僧房借半间，早晚温习经史，胜如旅邸内冗杂，房金依例拜纳，小生明日自来也。
[赚煞]饿眼望将穿馋口涎空咽，空着我透骨髓相思病染，怎当他临去秋波那一转！休道是小生，便是铁石人也意惹情牵。近庭轩，花柳争妍，日午当庭塔影圆。春光在眼前，争奈玉人不见，将一座梵王宫疑是武陵源。[并下]', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2815e272d4b2254d9c4", "shortContent": "《西厢记》的第一本第一折，有的明刊本另有标目，曰《佛殿奇逢》，清刊本标《惊艳》的也不少。曰奇曰惊，正好用两种不同的神态来说明当时的气氛，并突出了莺莺的形态之美。这次张生、莺莺在佛殿上的相遇，彼此都毫无思想准备，完全出乎意料的。所以对双方来说，都是一场奇遇。而莺莺的绝世姿容，又使张生更多一层惊奇之感而倍加倾倒。\n虽然这是他们的初次相遇，比较充分地写张生对莺莺的美丽无限爱慕而呈现出如痴如醉的“疯魔”表...", "authors": ["蒋星煜"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2817d0ac1145495e392", "shortContent": "王实甫的《西厢记》，故事本于唐人元稹的《会真记》，情节改编和结构处理借鉴了董解元的《西厢记诸宫调》。该剧通过描写张珙和崔莺莺自由恋爱，几经波折终于结合的过程，歌颂了自主的爱情，表现了市井细民对封建礼教的冲击。\n这两支曲子选自第一本第一折，单独看来，却是一首描写黄河的出色抒情诗。剧中人张珙旅行到黄河之滨的蒲州城（今山西永济），立马蒲津渡口，对岸便是险要的蒲津关。他面对滚滚黄流，心潮起伏，唱了两支曲子...", "authors": ["刘知渐", "鲜述文"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2805e272d4b2254d9bf", "shortContent": "《岳阳楼》杂剧为马致远早期作品。是他写过的五种“神仙道化”剧中的代表作。此剧先叙述吕洞宾成道后下山度人，然后写洞宾设置种种变故，对所度之人加以种种磨炼，终至功德完满而升仙境。这故事本身并无甚动人之处，但马致远在其中倾泄了他对现实愤懑情绪，再加上他特别富有抒情诗人气质，恃才逞气，借景遣怀，因此个中每见性情。\n〔混江龙〕曲，写吕洞宾飞至岳阳楼时，见其建筑奇伟，感发吟唱。此曲叙景，由远及近，一路写来，条...", "authors": ["刘荫柏"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec289911759740c9bc522", "shortContent": "《贬黄州》写苏轼（字子瞻）遭王安石排挤陷害，贬官黄州，受尽艰辛屈辱，后又被赦复职的故事。全剧共四折，一楔子。第一折：苏东坡受诬贬谪；第二折：马正卿雪里送炭；第三折：杨太守雪上加霜；第四折：苏东坡蒙赦复官。作者通过苏东坡这段升黜浮沉的经历，以酣畅的笔墨写出了君王寡恩，才人毁弄，仕途坎坷，世道炎凉。\n〔混江龙〕〔鹊踏枝〕是第一折中的两支曲子，一前一后抒发苏东坡得知获罪遭贬前后的心底波澜。〔混江龙〕写的...", "authors": ["郑拾风"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f4179c6e67846a92276fd", "shortContent": "（生缁衣笠帽）（小生道装挑担上）（白）大师走吓！\n白）我自吴江别了史徒出门，师弟两人，一路登山涉水，夜宿晓行。一天心事都付浮云，七尺形骸甘为行脚[2]。身作闲云野鹤，心同槁木死灰。\n（唱）但见那寒云惨雾和愁织，受不尽苦雨凄风带怨长。（生白）\n徒弟前面是那里了？（小生）是襄阳城了。（生）是襄阳城了。咳！（生\n唱）雄城壮，看江山无恙。谁识我一瓢一笠到襄阳？\n（内）走吓！（小生）后面有许多车辆兵马来了，...", "authors": ["陆", "炜"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f417c34a8757d5a0fabda", "shortContent": "（跌复起走介）颠蹶心慌乱，羊肠疾走。我石太尉，绑赴法场，亏我逃走得快，不曾受此一刀。走得气吼，那里躲一躲便好。这崎岖古道敢\n迟留？不堪再回首，不堪再回首。\n（付领众赶上）法场上走了人了，快赶上去。（赶转下）（生暗上）骇死我也！骇死我也！且喜追我不上，不免再趱上去。\n来此滩头，且喜芦苇甚密，不免钻进去。咦，好了，幸喜芦苇中有一只小船在此，不免跳上船去，撑在大洋，那怕他追兵到来。（上船）（作风浪声）（...", "authors": ["许金榜"], "pressName": "上海辞书出版社"}, {"bookId": "6277bbb9f716b7243c7bdff3", "bookTitle": "元曲鉴赏辞典", "articleId": "63126ed177683d1933015135", "shortContent": "《西厢记》全名《崔鸾莺待月西厢记》。写书生张生在蒲东普救寺遇相国之女崔鸾莺，两人一见钟情，通过侍女红娘的帮助，终于冲破封建礼教约束而结合的故事。全剧共五本，第一本是《张君瑞闹道场》；第二本是《崔莺莺夜听琴》；第三本是《张君瑞害相思》；第四本是《草桥店梦莺莺》；第五本是《张君瑞庆团》。\n《西厢记》第一本第一折，有的明刊本另有标目，曰《佛殿奇逢》，清刊本标《惊艳》的也不少。说奇说惊，正好用两种不同的神...", "authors": ["刘克勤"], "pressName": "崇文书局"}]', '', 'indent', 1572705902, '5dbd25e6c05a8000684cfe63', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643548, '西厢记 · 第一本 · 第二折', NULL, 21, 41, 3, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[夫人上白]前日长老将钱去与老相公做好事，不见来回话。道与红娘，传着我的言语去问长老：几时好与老相公做好事？就着他办下东西的当了，来回我话者。[下][净扮洁上]老僧法本，在这普救寺里做长老。此寺是则天皇后盖造的，后来崩损，又是崔相国重修的。现今崔老夫人领着家眷扶柩回博陵。因路阻暂寓本寺西厢之下，待路通回博陵迁葬。夫人处事温俭，治家有方，是是非非，人莫敢犯。夜来老僧赴斋，不知曾有人来望老僧否？[唤聪问科][聪云]夜来有一秀才自西洛而来，特谒我师，不遇而返。[洁云]山门外觑着，若再来时，报我知道。[末上]昨日见了那小姐，倒有顾盼小生之意。今日去问长老借一间僧房，早晚温习经史；倘遇那小姐出来，必当饱看一会。
[中吕][粉蝶儿]不做周方，埋怨杀你个法聪和尚！借与我半间客舍僧房，与我那可憎才居止处门儿相向。虽不能窃玉偷香，且将这盼云眼睛儿打当。
[醉春风]往常时见傅粉的委实羞，画眉的敢是谎；今日多情人一见了有情娘，着小生心儿里早痒痒。迤逗得肠荒，断送得眼乱，引惹得心忙。
[末见聪科][聪云]师父正望先生来哩，只此少待，小僧通报去。[洁出见末科][末云]是好一个和尚呵！
[迎仙客]我则见他头似雪，鬓如霜，面如童，少年得内养；貌堂堂，声朗朗，头直上只少个圆光。却便是捏塑来的僧伽像。
[洁云]请先生方丈内相见。夜来老僧不在，有失迎迓，望先生恕罪！[末云]小生久闻老和尚清誉，欲来座下听讲，何期昨日不得相遇。今能一见，是小生三生有幸矣。[洁云]先生世家何郡？敢问上姓大名，因甚至此？[末云]小生姓张，名珙，字君瑞：
[石榴花]大师一一问行藏，小生仔细诉衷肠，自来西洛是吾乡，宦游在四方。寄居咸阳。先人拜礼部尚书多名望，五旬上因病身亡。[洁云]老相公弃世，必有所遗。[末唱]平生直无偏向，止留下四海一空囊。
[斗鹌鹑]俺先人甚的是浑俗和光，衠一味风清月朗。[洁云]先生此一行必上朝取应去。[末唱]小生无意求官，有心待听进。小生特谒长老，奈路途奔驰，无以相馈。量着穷秀才人情则是纸半张，以没甚七青八黄，尽着你说短论长，一任待掂斤播两。
径禀：有白银一两，与常往公用，略表寸心，望笑留是幸！[洁云]先生客中，何故如此？[末云]物鲜不足辞，但充讲下一茶耳。
[上小楼]小生特来见访，大师何须谦让。[洁云]老僧决不敢受。[末唱]这钱也难买柴薪，不够斋粮，且备茶汤。[觑聪云]这一两未为厚礼。你若有主张，对艳妆，将言词说上，我将你众和尚死生难忘。
[洁云]先生必有所请。[末云]小生不揣有恳，因恶旅冗杂，早晚难以温习经史，欲假一室，晨昏听讲。房金按月任意多少。[洁云]敝寺颇有数间，任先生拣选。[末唱]
[幺篇]也不要香积厨，枯木堂。远有南轩，离着东墙，靠着西厢。近主廊，过耳房，都皆停当。[洁云]便不呵，就与老僧同处何如？[末笑云]要恁怎么。你是必休提着长老方丈。
[红上云]老夫人着俺问长老：几时好与老相公做好事？看得停当回话。须索走一遭去来。[见洁科]长老万福！夫人使侍妾来问：几时好与老相公做好事？着看得停当了回话。[末背云]好个女子也呵！
[脱布衫]大人家举止端详，全没那半点儿轻狂。大师行深深拜了，启朱唇语言得当。
[小梁州]可喜的庞儿浅淡妆，穿一套缟素衣裳；胡伶渌老不寻常，偷睛望，眼挫里抹张郎。
[幺篇]若共他多情小姐同鸳帐，怎舍得他叠被铺床。我将小姐央，夫人央，他不令许放，我亲自写与从良。
[洁云]二月十五日，可与老相公做好事。[红云]妾与长老同去佛殿看了，却回夫人话。[洁云]先生请少坐，老僧同小娘子看一遭便来。[末云]着小娘子先行，俺近后些。[洁云]一个有道理的秀才。[末云]小生有一句话敢道么？[洁云]便道不妨。[末唱]
[快活三]崔家女艳妆，莫不是演撒你个老洁郎？[洁云]俺出家人那有此事？[末唱]既不沙，却怎睃趁着你头上放毫光，打扮的特来晃。
[洁云]先生是何言语！早是那小娘子不听得哩，若知呵，是甚意思！[红上佛殿科][末唱]
[朝天子]过得主廊，引入洞房，好事从天降。我与你看着门儿，你进去。[洁怒云]先生，此非先王之法言，岂不得罪于圣人之门乎？老僧偌大年纪，焉肯作此等之态？[末唱]好模好样太莽撞，没则罗便罢，烦恼怎么那唐三藏？怪不得小生疑你，偌大一个宅堂，可怎生别没个儿郎，使得梅香来说勾当。[洁云]老夫人治家严肃，内外并无一个男子出入。[末背云]这秃厮巧说。你在我行、口强，硬抵着头皮撞。
[洁对红云]这斋供道场都完备了，十五日请夫人小姐拈香。[末问云]何故？[洁云]这是崔相国小姐至孝，为报父母之恩。又是老相国禫日，就脱孝服，所以做好事。[末哭科云]“哀哀父母，生我劬劳，欲报深恩，昊天罔极。”小姐是一女子，尚然有报父母之心；小生湖海飘零数年，自父母下世之后，并不曾有一陌纸钱相报。望和尚慈悲为本，小生亦备钱五千，怎生带得一分儿斋，追荐俺父母咱！便夫人知也不妨，以尽人子之心。[洁云]法聪与这先生带一分者。[末背问聪云]那小姐明日来么？[聪云]他父母的勾当，如何不来。[末背云]这五千钱使得有些下落者。
[四边静]人间天上，看莺莺强如做道场。软玉温香，休道是相亲傍；若能够汤他一汤，倒与人消灾障。
[洁云]都到方丈吃茶。[做到科][末云]小生更衣咱。[末出科云]那小娘子已定出来也，我只在这里等待问他咱。[红辞洁云]我不吃茶了，恐夫人怪来迟，去回话也。[红出科][末迎红娘祗揖科]小娘子拜揖！[红云]先生万福！[末云]小娘子莫非莺莺小姐的侍妾么？[红云]我便是，何劳先生动问？[末云]小生姓张，名珙，字君瑞，本贯西洛人也，年方二十三岁，正月十七日子时建生，并不曾娶妻——[红云]谁问你来？[末云]敢问小姐常出来么？[红怒云]先生是读书君子，孟子曰：“男女授受不亲，礼也。”君子“瓜田不纳履，李下不整冠”。道不得个“非礼勿视，非礼勿听，非礼勿言，非礼勿动”。俺夫人治家严肃，有冰霜之操。内无应门五尺之童，年至十二三者，非呼召不敢辄入中堂。向日莺莺潜出闺房，夫人窥之，召立莺莺于庭下，责之曰：“汝为女子，告而出闺门，倘遇游客小僧私视，岂不自耻。”莺莺立谢而言曰：“今当改过从新，毋敢再犯。”是他亲女，尚然如此，可况以下侍妾乎？先生习先王之道，尊周公之礼，不干已事，何故用心？早是妾身，可以容恕，若夫人知其事，决无干休。今后得问的问，不得问的休胡说！[下][末云]这相思索是害也！
[哨遍]听说罢心怀悒悒，把一天愁都撮在眉尖上。说：“夫人节操凛冰霜，不召乎，谁敢辄入中堂？”自思想，比及你心儿思畏老母亲威严，小姐呵，你不合临去也头望。待扬下教人怎扬？赤紧的情沾了肺腑，意惹了肝肠。若今生难得有情人，是前世烧了断头香。我得时节手掌儿里奇擎，心坎儿里温存，眼皮儿上供养。
[耍孩儿]当初那巫山远隔如天样，听说罢又在巫山那厢。业身躯虽是立在回廊，魂灵儿已在他行。本待要安排心事传幽客，我只怕漏泄春光与乃堂。夫人怕女孩儿春心荡，怪黄莺儿作对，怨粉蝶儿成双。
[五煞]小姐年纪小，性气刚。张郎倘得相亲傍，乍相逢厌见何郎粉，看邂逅偷将韩寿香。才到得风流况，成就了会温存的娇婿，怕甚么能拘束的亲娘。
[四煞]夫人忒虑过，小生空妄想，郎才女貌合相仿。休直待眉儿浅淡思张敞，春色飘零忆阮郎。非是咱自夸奖：他有德言工貌，小生有恭俭温良。
[三煞]想着他眉儿浅浅描，脸儿淡淡妆，粉香腻玉搓咽项。翠裙鸳绣金莲小，红袖鸾销玉笋长。不想呵其实强：你撇下半天风韵，我拾得万种思量。
却忘了辞长老。[见洁科]小生敢问长老，房舍如何？[洁云]塔院侧边西厢一间房，甚是潇洒，正可先生安下。现收拾下了，随先生早晚来。[末云]小生便回店中搬去。[洁云]吃斋了去。[末云]老僧收拾下斋，小生取行李便来。[洁云]既然如此，老僧准备下斋，先生是必便来。[下][末云]若在店中人闹，倒好消遣；搬在寺中静处，怎么捱这凄凉也呵。
[二煞]院宇深，枕簟凉，一灯孤影摇书幌。纵然酬得今生志，着甚支吾此夜长。睡不着如翻掌，少可有一万声长吁短叹，五千遍捣枕捶床。
[尾]娇羞花解语，温柔玉有香，我知他乍相逢记不真娇模样，我则索手抵着牙儿慢慢的想。[下]', '', '', '', '[{"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f417e2e6a6b501f9753e1", "shortContent": "家内官常侍便是。奉皇爷旨意，叫咱家密召蔡学士进宫议事，来此已是。有人么？（副上）什么人？（外）报去，说内侍公公要见。（副）是。\n老爹有请。（净上）内屏坐拥春罗帐，半闲堂虚讲[3]，金谷园效放[4]。\n（副）内侍公公要见。（净）道有请。公公，适才朝罢，又召何事？（外）皇爷退居长信宫，忽传一旨，着咱家来召你进宫议事，皇爷立等。（净）就行。（外）口传皇帝旨[5]，（净）不俟驾而行。（下）\n天仗霄岩建羽旄...", "authors": ["王永宽"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572705972, '5dbd262d17b54d006c7b2350', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643549, '西厢记 · 第一本 · 第三折', NULL, 9, 41, 4, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[正旦上云]老夫人着红娘问长老去了，这小贱人不来我行回话。[红上云]回夫人话了，去回小姐话去。[旦云]使你问长老：几时做好事？[红云]恰回夫人话也，正待回姐姐话：二月十五日，请夫人姐姐拈香。[红笑云]姐姐，你不知，我对你说一件好笑的的勾当。咱前日寺里见的那秀才，今日也在方丈里。他先出门儿外等着红娘，深深唱个喏道：“小生姓张，名珙，字君瑞，本贯西洛人也，年二十三岁，正月十七子时建生，并不曾娶妻。”姐姐，却是谁问他来？他又问：“那壁小娘子莫非莺莺小姐的侍妾乎？小姐常出来么？”被红娘抢白了一顿呵回来了。姐姐，我不知了想甚么哩，世上有这等傻角！[旦笑云]红娘，休对夫人说。天色晚也，安排香案，咱花园内烧香去来。[下][末上云]搬至寺中，正近西厢居址。我问和尚每来，小姐每夜花园内烧香。这个花园和俺寺中合着。比及小姐出来，我先在太湖石畔墙角儿边等待，饱看一会。两廊僧众都睡着了。夜深人静，月朗风清，是好天气也呵！正是“闲寻方丈高僧语，闷对西厢皓月吟”。
[越调][斗鹌鹑]玉宇无尘，银河泻影月色横空，花阴满庭；罗袂生寒，芳心自警。侧着耳朵儿听，蹑着脚步儿行：悄悄冥冥，潜潜等等。
[紫花儿序]等待那齐齐整整，袅袅婷婷，姐姐莺莺。一更之后，万籁无声，直至莺庭。若是回廊下没揣的见俺可憎，将他来紧紧的搂定；只问你那会少离多，有影无形。
[旦引红娘上云]开了角门儿，将香桌出来者。[末唱]
[金蕉叶]猛听得角门儿呀的一声，风过处衣香细生。踮着脚尖儿仔细定睛，比我那初见时庞儿越整。
[旦云]红娘，移香桌儿近太湖石畔放者！[末做看科云]料想春娇厌拘束，等闲飞出广寒宫。看他容分一捻，体露半襟，躭香袖以无言，垂罗裙而不语。似汀陵妃子，斜倚舜庙朱扉；如玉殿嫦娥，微现蟾宫素影。是好女子也呵！
[调笑令]我这里甫能、见娉婷，比着那月殿嫦娥也不恁般撑。遮遮掩掩穿芳径，料应来小脚儿难行。可喜娘的脸儿百媚生，兀的不引了人魂灵！
[旦云]取香来！[末云]听小姐祝告甚么？[旦云]此一柱香，愿化去先人，早生天界！此一柱香，愿中老母，身安无事！此一柱香——[做不语科][红云]姐姐不祝这一柱香，我替姐姐祝告：愿俺姐姐早寻一个姐夫，拖带红娘咱！[旦再拜云]心中无限伤心事，尽在深深两拜中。[长吁科][末云]小姐倚栏长叹，似有动情之意。
[小桃红]夜深香霭散空庭，帘幕东风静。拜罢也斜将曲栏凭，长吁了两三声。剔团圞明月如悬镜。又不见轻云薄雾，都只是香烟人气，两般儿氤氲得不分明。
我虽不如司马相如，我则看小姐颇有文君之意。我且高吟一绝，看他则甚：“月色溶溶夜，花阴寂寂春；如何临皓魄，不见月中人？”[旦云]有人墙角吟诗。[红云]这声音便是那二十三岁不曾娶妻的那傻角。[旦云]好清新之诗，我依韵做一首。[红云]你两个是好做一首。[旦念诗云]“兰闺久寂寞，无事度芳春；料得行吟者，应怜长叹人。”[末云]好应酬得快也呵！
[秃厮儿]早是那脸儿上扑堆着可憎，那堪那心儿里埋没着聪明。他把那新诗和得忒应声，一字字，诉衷情，堪听。
[圣药王]那语句清，音律轻，小名儿不枉了唤做莺莺。他若是共小生、厮觑定，隔墙儿酬和到天明。方信道“惺惺的自古惜惺惺。”
我撞出去，看他说甚么。
[麻郎儿]我拽起罗衫欲行，[旦做见科]他陪着笑脸儿相迎。[红云]姐姐，有人，咱家去来，怕夫人嗔着。[莺回顾下][末唱]不做美的红娘太浅情，便做道“谨依来命”。
[幺篇]我忽听、一声、猛惊。原来是扑刺刺宿鸟飞腾，颤巍巍花梢弄影，乱纷纷落红满径。
小姐，你去了呵，那里发付小生！
[络丝娘]空撇下碧澄澄苍苔露，明皎皎花筛月影。白日凄凉枉耽病，今夜把相思再整。
[东原乐]帘垂下，户已扃，却才个悄悄相问，他那里低低应，月朗风清恰二更，厮榽幸：他无缘，小生薄命。
[绵搭絮]恰寻归路，伫立空庭，竹梢风摆，斗柄云横。呀！今夜凄凉有四星，他不瞅人待怎生！虽然是眼角儿传情，咱两个口不言心自省。
今夜甚睡到得我眼里呵！
[拙鲁速]对着盏碧荧荧短檠灯，倚着扇泠清清旧帏屏。灯儿又不明，梦儿又不成；窗儿外淅零零的风儿透疏檑，忒楞楞的纸条儿鸣；枕头儿上孤另，被窝儿里寂静。你便是铁石人，铁石人也动情。
[幺篇]怨不能，恨不成，坐不安，睡不宁。有一日柳遮花映，雾帐云屏，夜阑人静，海誓山盟。恁时节风流嘉庆，锦片也似前程，美满恩情，咱两个画堂自生。
[尾]一天好事从今定，一首诗分明照证；再不向表琐闼梦儿中寻，则去那碧桃花树儿下等。[下]', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2802e6a6b501f966ddb", "shortContent": "《黄粱梦》故事在唐代有沈既济所著传奇小说《枕中记》，写吕翁与卢生事，至金元则附会为钟离权度脱吕洞宾，并成为全真教祖师的神圣事迹，流传甚广。据《录鬼簿》，元杂剧《黄粱梦》由马致远、李时中、“折花学士”、红字李二合撰而成。据明初贾仲明为李时中所补写的〔凌波仙〕吊词，“折花学士”系花李郎。\n第一折写吕岩上京赶考，在邯郸道遇道人钟离权。钟离权劝他抛弃功名富贵的念头，随自己出家去。吕岩想十年寒窗，好不容易学...", "authors": ["李修生", "唐葆祥"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f4167dbb8b379ee0af323", "shortContent": "小生虽不及司马相如，那小姐颇有文君之意。我且歌一绝，看他何如？（念诗介）月色溶溶夜，花阴寂寂春。如何临皓魄，不见月中人？（旦）红娘，是谁在墙角边吟诗？（贴）这声音便是二十三岁不曾娶妻的涎脸。（旦）好清新之诗，我也依韵和他一首。（贴）你两下里正好做一“首”。（旦）做一首诗。有了。（贴）面也不曾会，就有了！（旦）贱人，诗有了。（贴）我只道那话儿有了。（旦吟诗介）兰闺久寂寞，无事度芳春。料得行吟者，应怜...", "authors": ["周锡山"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f416d2cee9a0c24ee81b3", "shortContent": "方池冰影薄，曲槛鸟声娇。鸾镜红绵冷[2]，蛾眉翠黛消。朝霞，天气初晴，你卷起帘儿，一望西湖春色。（朝作卷帘风起吹落花片介）呀，忽一阵香风，吹落许多花片在妆台之上了。（旦）正是：玉貌楼前堕，冰容梦里消。妆台休浪拂，留伴可怜宵。（叹介）\n来？（旦）我笑他香魂独趁。嗳，两难凭，漫惜玉怜香，都付与多\n满园关不住，一枝红杏出墙来[7]。墙直上一枝红杏，（拈落花看介）原来不是杏花，是红梅。好动人的春色也！是红...", "authors": ["骆", "兵"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572706023, '5dbd26636e9ba1006d61a46f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643550, '西厢记 · 第一本 · 第四折', NULL, 4, 41, 1, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[洁引聪上云]今日二月十五开启，众僧动法器者。请夫人小姐拈香。比及夫人未来，先请张生拈香。怕夫人问呵，则说是贫僧亲者。[末上云]今日二月十五日，和尚请拈香，须索走一遭。
[双调][新水令]梵王宫殿月轮高，碧琉璃瑞烟笼罩。香烟云盖结，讽咒海波潮。幡影飘颻，诸檀越尽来到。
[驻马听]法鼓金铎，二月春雷响殿角；钟声佛号，半天风雨洒松梢。候门不许老僧敲，纱窗外定有红娘报。害相思的馋眼脑，见他时须看个十分饱。
[末见洁科][洁云]先生先拈香，恐夫人问呵，则说是老僧的亲。[末拈香科]
[沉醉东风]惟愿存有的人间寿高，亡化的天上逍遣。为曾、祖、父先灵，礼佛、法、僧三宝。焚名香暗中祷告：则愿得红娘休劣，夫人休焦，犬儿休恶！佛啰，早成就了幽期密约。
[夫人引旦上云]长老请拈香，小姐，咱走一遭，[末做见科][觑聪云]为你志诚呵，神仙下降也。[聪云]这生却早两遭儿也。[末唱]
[雁儿落]我则道这玉天仙离了碧霄，原来是可意中来请醮。小子多愁多病身，怎当他倾国倾城貌。
[得胜令]恰便似檀口点樱桃，粉鼻儿倚琼瑶，淡白梨花面，轻盈杨柳腰。妖娆，满面儿扑堆着俏；苗条，一团儿衠是娇。
[洁云]贫僧一句话，夫人行敢道么？老僧有个敝亲，是个饱学的秀才，父母亡后，无可相报。对我说：“央及带一分斋，追荐父母。”贫僧一时应允了，恐夫人见责。[夫人云]长老的亲便是我的亲，请来厮见咱。[末拜夫人科][众僧见旦发科][末唱]
[乔牌儿]大师年纪老，法座上也凝眺；举名的班首真呆僗，觑着法聪头作金磬敲。
[甜水令]老的小的，村的俏的，没颠没倒，胜似闹元宵。稔色人儿，可意冤家，怕人知道，看时节泪眼偷瞧。
[折桂令]着小生迷留没乱，心痒难挠。哭声儿似莺啭乔林，泪珠儿似露滴花梢。大师也难学，把一个发慈悲的脸儿来朦着。击磬的头陀懊恼，添香的行者心焦。烛影风摇，香霭云飘；贪看莺莺，烛灭香消。
[洁云]风灭灯也。[末云]小生点灯烧香。[旦与红云]那生忙了一夜。
[锦上花]外像儿风流，青春年少；内性儿聪明，冠世才学，扭捏着身子儿百般做作，来往向人前卖弄俊俏。
[红云]我猜那生——
[幺篇]黄昏这一回，白日那一觉，窗儿外那会镬铎。到晚一向书帏里比及睡着，千万声长吁怎捱到晓。[末云]那小姐好生顾盼小子。
[碧玉箫]情引眉梢，心绪你知道：愁种心苗，情思我猜着。畅懊恼！响铛铛云板敲。行者又嚎，沙弥又哨。您须不夺人之好。
[洁与众僧发科][动法器了，洁摇铃杵宣疏了，烧纸科][洁云]天明了也，请夫人小姐回宅。[末云]再做一会也好，那里发付小生也呵！
[鸳鸯煞]有心争似无心好，多情却被无情恼。劳攘了一宵，月儿沈，钟儿响，鸡儿叫。畅道是玉人归去得疾，好事收拾得早，道场毕诸人散了。酩子里各归家，葫芦提闹到晓。[并下]
[络丝娘煞尾]则为你闭月羞花相貌，少不得剪草除根大小。
题目老夫人闭春院崔莺莺烧夜香正名小红娘传好事张君瑞闹道场', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec28f03572034f65a85f3", "shortContent": "在郑光祖现存的作品中以《倩女离魂》、《王粲登楼》和《梅香》为著名。\n《梅香》的故事大体是：裴度生前将女儿小蛮许与白敏中。裴度死后，夫人悔约。婢女樊素从中撮合，使白敏中与小蛮终成眷属。这个剧本中出现的人物姓名，虽见诸有关记载，但故事却为郑光祖所撰制。历来戏曲评论家对此剧毁誉不一。王世贞、梁廷枏分别斥之为“全剽《西厢》”（《曲藻》），“照本模拟”（《曲话》）。而何良俊在《四友斋丛说》中却十分赞赏此...", "authors": ["陈美林"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572706083, '5dbd269df884af007337f3c2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643551, '西厢记 · 第二本 · 第一折', NULL, 3, 41, 0, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[孙飞虎上开]自家姓孙，名彪，字飞虎，方今天下扰攘。因主将丁文雅失政，俺分统五千人马，镇守河桥，劫掳良民财物。近知先相国崔珏之女莺莺，眉黛青颦，莲脸生春，有倾国倾城之容，西子太真之颜，现在河中府普救寺借居。我心中想来：当今用武之际，主将尚然不正，我独廉何为？大小三军，听吾号令：人尽衔枚，马皆勒口，连夜进兵河中府！掳莺莺为妻，是我平生愿足，[下][法本慌上]谁想孙飞虎将半万贼兵围住寺门，鸣锣击鼓，呐喊摇旗，欲掳莺莺小姐为妻。我今不敢违误，即索报知夫人走一遭[下][夫人慌云]如此却怎了！俺同到小姐卧房里商量去。[下][旦引红娘上去]自见了张生，神魂荡漾，情思不快，茶饭少进。早是离人伤感，况值暮春天道，好烦恼人也呵！好句有情怜夜月，落花无语怨东风。
[仙吕][八声甘州]恹恹瘦损，早是伤神，那值残春。罗衣宽褪，能消几度黄昏？风袅篆烟不卷帘，雨打梨花深闭门；无语凭阑干，目断行云。
[混江龙]落红成阵，风飘万点正愁人，池塘梦晓，阑槛辞春；蝶粉轻沾飞絮雪，燕泥香惹落花尘；系春心情短柳丝长，隔花阴人远天涯近。香消了六朝金粉，清减了三楚精神。
[红云]姐姐情思不快，我将被儿薰得香香的，睡些儿。[旦唱]
[油葫芦]翠被生寒压绣裀，休将兰麝薰；便将兰麝薰尽，则索自温存。昨宵个锦囊佳制明勾引，今日玉堂人物难亲近。这些时坐又不安，睡又不稳，我欲待登临又不快，闲行又闷。每日价情思睡昏昏。
[天下乐]红娘呵，我则索搭伏定鲛绡枕头儿上盹。但出闺门，影儿般不离身。[红云]不干红娘事，老夫人着我跟着姐姐来。[旦云]俺娘也好没意思！这些时直恁般堤防着人；小梅香伏侍得勤，老夫人拘束得紧，则怕俺女孩儿折了气分。
[红云]姐姐往常不曾如此无情无绪；自见了那张生，便觉心事不宁，却是如何？[旦唱]
[那吒令]往常但见个外人，氲的早嗔；但见个客人，厌的倒褪；从见了那人，兜的便亲。想着他昨夜诗，依前韵，酬和得清新。
[鹊踏枝]吟得句儿匀，念得字儿真，咏月新诗，煞强似织锦回文。谁肯把针儿将线引，向东邻通个殷勤。
[寄生草]想着文章士，旖旎人；他脸儿清秀身儿俊，性儿温克情儿顺，不由人口儿里作念心儿里印。学得来“一天星斗焕文章”，不枉了“十年窗下无人问”。
[飞虎领兵上围寺科][下][卒子内高叫云]寺里人听者：限你每三日内将莺莺献出来与俺将军成亲，万事干休。三日后不送出，伽蓝尽皆焚烧，僧俗寸斩，不留一个。[夫人、洁同上敲门科][红看了云]姐姐，夫人和长老都在房门前。[旦见科][夫人云]孩儿，你知道么？如今孙飞虎将半万贼兵围住寺门，道你“眉黛青颦，莲脸生春，似倾国倾城的太真”，要掳你做压寨夫人。孩儿，怎生是了也？[旦唱]
[六玄序]听说罢魂离了壳，现放着祸灭身，将袖梢儿搵不住啼痕。好教我去住无因，进退无门，可着俺那埚儿里人急偎亲？孤孀子母无投奔，赤紧的先亡过了有福之人。耳边厢金鼓连天震，征云冉冉，土雨纷纷。
[幺篇]那厮每风闻，胡云。道我“眉黛青颦，莲脸生春，恰便是倾国倾城的太真”；兀的不送了他三百僧人？半万贼军，半霎敢剪草除根？这厮每于家为国无忠信，恣情的掳掠人民。更将那天宫般盖造焚烧尽，则没那诸葛孔明，便待要博望烧屯。
[夫人云]老身年六十年，不为寿夭；奈孩儿年少，未得从夫，却如之奈何？[旦云]孩儿有一计，想来只是我与贼汉为妻，庶可免一家儿性命。[夫人哭科]俺家无犯法之男，再婚之女，怎舍得你献与贼汉，却不辱没了俺家谱！[洁云]俺同到法堂上两廊下，问僧俗有高见者，俺一同商议个长便。[同到法堂科][夫人云]小姐却是怎生？[旦云]不如将我与贼人，其便有五：
[后庭花]第一来免摧残老太君；第二来免殿堂作灰烬；第三来诸僧无事得安存；第四来先君灵柩稳；第五来欢郎虽是未成人，[欢云]俺呵，打甚么不紧。[旦唱]须是崔家后代孙。莺莺为惜己身，不行从着乱军：诸僧众污血痕，将伽蓝火内焚，先灵为细尘，断绝了爱弟亲，割开了慈母恩。
[柳叶儿]呀，将俺一家儿不留一个龆龀，待从军又怕辱没了家门。我不如白练套头儿寻个自尽，将我尸榇，献与贼人，也须得个远害全身。
[青歌儿]母亲，都做了莺莺生忿，对旁人一言难尽。母亲，休爱惜莺莺这一身。您孩儿别有一计；不拣何人，建立功勋，杀退贼军，扫荡妖氛；倒陪家门，情愿与英雄结婚姻，成秦晋。
[夫人云]此计较可。虽然不是门当户对，也强如陷于贼中。长老在法堂上高叫：“两廊僧俗，但有退兵之策的，倒陪房奁，断送莺莺与他为妻。”[洁叫了，住][末鼓掌上云]我有退兵之策，何不问我？[见夫人科][洁云]这秀才便是前日带追荐的秀才。[夫人云]计将安在？[末云]“重赏之下，必有勇夫；赏罚若明，其计必成。”[旦背云]只愿这生退了贼者。[夫人云]恰才与长老说下，但有退得贼兵的，将小姐与他为妻。[末云]即是恁的，休唬了我浑家，请入卧房里去，俺自有退兵之策。[夫人云]小姐和红娘回去者！[旦对红云]难得此生这一片好心！
[赚煞]诸僧众各逃生，从家眷偢问，这生不相识横枝儿着紧。非是书生多议论，也堤防着玉石俱焚。虽然是不关亲，可怜见命在逡巡，济不济权将秀才来尽。果若有《出师表》文吓蛮书信，张生呵，则愿你笔尖儿横扫了五千人。', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec28e7d0ac1145495e3b4", "shortContent": "孔文卿是元代著名的剧作家，以《地藏王证东窗事犯》传世。《东窗事犯》写北宋名将岳飞被奸相秦桧陷害至死，死后冤魂托梦，最终奸臣被惩的一段故事。据传，秦桧谋杀岳飞，曾事先与人在东窗下密谋过，故而称这次谋杀案为“东窗事犯”。本剧中一些曲子至今仍在昆剧中演唱，称为《扫秦》。这里所选的第一折〔混江龙〕曲写出了岳飞忠义而见疑，功高而被谤的愤懑以及世事不公、壮志难酬的悲哀。\n岳飞是宋代名将，以“精忠报国”著称于世...", "authors": ["马欣来"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572706215, '5dbd271030863b006c42a5d9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643552, '西厢记 · 第二本 · 第二折', NULL, 1, 41, 0, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[夫人、洁同末上][夫人云]此事如何？[末云]小生有一计，先用着长老。[洁云]老僧不会厮杀，请秀才别换一个。[末云]休慌，不要你厮杀。你出去与贼汉说：“夫人本待便将小姐出来，送与将军，奈有父丧在身。不争鸣金击鼓，惊死小姐，也可惜了。将军若要做女婿呵，可按甲束兵，退一射之地。限三日功德圆满，脱了孝服，换上颜色衣服，鲐陪房奁，定将小姐送与将军。不争便送来，一来父孝在身，二来于君不利。”你去说去。[洁云]三日后如何？[末云]有计在后。[洁朝鬼门道叫科]请将军打话。[飞虎引卒上云]快送莺莺出来。[洁云]将军息怒！夫人使老僧来与将军说。[说如前了][飞虎云]既然如此，限你三日后。若不送来，我着你人人皆死，个个不存。你对夫人说去，恁的这般好性儿的女婿，教他招了者。[引卒下][洁云]贼兵退了也，三日后不送出去，便都是死的，[末云]小子有一故人，姓杜名确，号为白马将军，现统十万大兵，镇守着蒲关。一封书去，此人必来救我。此间离蒲关四十五里，写了书呵，怎得人送去？[洁云]若是白马将军肯来，何虑孙飞虎。俺这里有一个徒弟，唤作惠明，则是要吃酒厮打。若使央他去，定不肯去；须将言语激他，他便去。[末唤云]有书寄与杜将军，谁敢去？谁敢去？[惠明上云]我敢去！[唱]
[正宫][端正好]不念《法华经》，不礼梁皇忏，颩了僧伽帽，袒下我这偏衫。杀人心逗起英雄胆，两只手将乌龙尾钢椽攥。
[滚绣球]非是我贪，不是我敢，知他怎生唤做打参，不踏步直杀出虎窟龙潭。非是我搀，不是我揽，这些时吃菜馒头委实口淡，五千人也不索灸煎。腔子里热血权消渴，肺腑内生心且解馋，有甚腌臢！
[叨叨令]浮沙羹、宽片粉添些杂糁，酸黄韭、烂豆腐休调啖，万余斤黑面从教暗，我将这五千人做一顿馒头馅。是必误了也么哥！休误了也么哥！包残余肉把表盐蘸。
[洁云]张秀才着你寄书去蒲关，你敢去么？[惠唱]
[倘秀才]你那里问小僧敢去也那不敢，我这里启大师用咱。你道是飞虎声名播斗南；那厮能淫欲，会贪婪，诚何以堪！
[末云]你是出家人，却怎不看经礼忏，则厮打为何？[惠唱]
[滚绣球]我经文也不会谈，逃禅也懒去参；戒刀头近新来钢蘸，铁棒上无半星儿土渍尘缄。别的都僧不僧、俗不俗，女不女、男不男，则会斋得饱也则去那僧房中胡渰，那里管焚烧了兜率也似伽蓝。则为那善文能武人千里，凭着这济因扶危书一缄，有勇无惭。
[末云]他倘若不放你过去如何？[惠云]他不放我呵，你放心！
[白鹤子]着几个小沙弥把幢幡宝盖擎，壮行者将杆棒镬叉担，你排阵脚将众僧安，我撞钉子把贼兵来探。[二]远的破开步将铁棒颩，近的顺手把戒刀钐；有小的提起来将脚尖蹍，有大的扳下来把髑髅勘。
[一]瞅一瞅古都都翻了海波，滉一滉厮琅琅震动山岩；脚踏得赤力力地轴摇，手扳得忽剌剌天关撼。
[耍孩儿]我从来驳驳劣劣，世不曾忑忑忐忐，打熬成不厌天生敢。我从来斩钉截铁常居一，不似恁惹草拈花没掂三。劣性子人皆惨，舍着命提刀仗剑，更怕甚勒马停骖。
[二]我从来欺硬怕软，吃苦不甘，你休只因亲事胡扑掩。若是杜将军不把干戈退，张解元干将风月担，我将不志诚的言词赚。倘或纰缪，倒大羞惭。
[惠云]将书来，你等回音者。
[收尾]您与我助威风擂几声鼓，仗佛力呐一声喊。绣旗下遥见英雄俺，我教那半万贼兵吓唬破胆。[下]
[末云]老夫人长老都放心，此书到日，必有佳音。咱“眼观旌节旗，耳听好消息”。你看“一封书札逡巡至，半万雄兵咫尺来。”[并下]', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2822e6a6b501f966ddd", "shortContent": "这是《西厢记》中著名的“惠明下书”一段唱词。自莺莺与张生佛殿相逢之后，撩起了双方的情思。可正当此时，镇守河桥的孙飞虎心生妄想，欲掳莺莺为妻。他出动五千兵马，围住寺院，限三日之内送出莺莺，否则放火烧杀。于是引出了张生给白马将军写信和“惠明下书”的情节。因此，“惠明下书”虽只是全剧中的一个插曲，但却是整个故事情节发展的一个不可或缺的环节；同时也借此塑造了一个性格鲜明、见义勇为的佛门侠士的形象。这三段曲...", "authors": ["孙", "逊"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec28fd635634aee3e9564", "shortContent": "《三战吕布》杂剧所写故事，主要来自民间传说。剧中以张飞为“正末”，这一点与元刊《三国志平话》以张飞为主要人物正相吻合。剧本成功地刻画了张飞刚烈勇猛、风趣幽默、襟怀坦荡、粗中有细的性格特征。\n这本戏一开始，就用不少笔墨以对白的形式表现以袁绍为首的十八路诸侯在虎牢关与吕布久战不利的形势，特别是有些将领，无勇无谋，其中的长沙太守孙坚，“不知天文，不晓地理”，“听得厮杀，帐房里推睡”，则尤为不堪。而当时身...", "authors": ["段启明"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2af911759740c9bc58c", "shortContent": "《随何赚风魔蒯通》，是元杂剧中比较成功的历史剧。它取材于汉高祖刘邦开国后杀戮功臣的史实。剧中由丞相萧何出面，诬杀了开国功臣韩信。韩信谋士蒯通避害装疯，却被辩士随何识破，赚到京中欲处死。蒯通则视死如归，仗义执言，为韩信的冤狱声辩，终于赢得了道义上的胜利。此剧深刻揭露了封建统治集团见利忘义、虚伪残酷的本质。\n历史上诱杀韩信的主谋是吕后，杂剧中改为萧何，具有更大的讽刺意义。因为正是萧何当初把韩信推荐给刘...", "authors": ["隗", "芾"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f417c911759740c9cabf6", "shortContent": "（末上）度理无情，后宾先礼，上命差遣，概不由己。自家麻府中院子便是。俺老爷职居长史[1]，家寄南昌，向蒙宁王千岁优礼相待[2]，言听计从，凡有作为，无不资其筹划。近又制造万寿珠冠一顶，献媚宫中，只待穿点完成，便索进上。这也不在话下。老爷主意，要在东庄左侧，方方起造园亭一所，名曰翡翠园，以便岁时行乐。叵耐东庄一角，碍着舒秀才住居，计欲方圆，甚难摆布。我见老爷心上焦躁就禀上说，老爷既要方圆，却又何难，...", "authors": ["王永宽"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572706299, '5dbd2775ba39c80073e5b6de', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643553, '西厢记 · 第二本 · 第三折', NULL, 0, 41, 2, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[夫人上云]今日安排下小酌，单请张生酬劳。道与红娘，疾忙去书院中请张生，着他是必便来，休推故。[下][末上云]夜来老夫人说，着红娘来请我，却怎生不见来？我打扮着等他。皂角也使过两个也，水也换了两桶也，乌纱帽擦得光挣挣的。怎么不见红娘来也呵？[红娘上云]老夫人使我请张生。我想若非张生妙计呵，俺一家儿性命难保也呵。
[中吕][粉蝶儿]半万贼兵，卷浮云片时扫净，俺一家儿死里逃生。舒心的列山灵，陈水陆，张君瑞合当钦敬。当日所望无成；谁想一缄书倒为了媒证。
[醉东风]今日个东阁玳筵开，煞强如西厢和月等。薄衾单枕有人温，早则不冷、冷。受用足宝鼎香浓，绣帘风细，绿窗人静。
可早来到也。
[脱布衫]幽僻处可有人行，点苍苔白露泠泠。隔窗儿咳嗽了一声，[红敲门科][末云]是谁来也？[红云]是我。他启朱唇急来答应。
[末云]拜揖小娘子。[红唱]
[小梁州]则见他叉手忙将礼数迎，我这里“万福，先生”。乌纱小帽耀人明，白襕净，角带傲黄程。
[幺篇]衣冠济楚庞儿俊，可知道引动俺莺莺。据相貌才性，我从来心硬，一见了也留情。
[末云]“既来之，则安之。”请书房内说话。小娘子此行为何？[红云]贱妾奉夫人严命，特请先生小酌数杯，勿却。[末云]便去，便去。敢问席上有莺莺姐姐么？[红唱]
[上小楼]“请”字儿不曾出声，“去”字儿连忙答应；可早莺莺根前，“姐姐”呼之，喏喏连声。秀才每闻道“请”，恰便似听将军严令，和他那五脏神愿随鞭镫。
[末云]今日夫人端的为甚么筵席？[红唱]
[幺篇]第一来为压惊，第二来因谢承。不请街坊，不会亲邻，不受人情。避众僧，请老兄，和莺莺匹聘。[末云]如此小生欢喜。[红唱]则见他欢天喜地，谨依来命。
[末云]小生客中无镜，敢烦小娘子看小生一看何如？[红唱]
[满庭芳]来回顾影，文魔秀士，风欠酸丁。下工夫将额颅十分挣，迟和疾擦倒苍蝇，光油油耀花人眼睛，酸溜溜螫得人牙疼。[末云]夫人办甚么请我？[红唱]茶饭已安排定，淘下陈仓米数升，碟下七八碗软蔓青。
[末云]小生想来：自寺中一见了小姐后，不想今日得成婚姻，岂不为前生分定？[红云]姻缘非力所为，天意尔。
[快活三]咱人一事精，百事精；一无成，百无成。世间草木本无情，自古云：“地生连理木，水出并头莲。”他犹有相兼并。
[朝天子]休道这生，年纪儿后生，恰学害相思病。天生聪俊，打扮素净，奈夜夜成孤另。才子多情，佳人薄幸，兀的不担阁了人性命。[末云]你姐姐果有信行？[红唱]谁无一个信行，谁无一个志诚，你两个今夜亲折证。
我嘱咐你咱！
[四边静]今宵欢庆，软弱莺莺、可曾惯经。你索款款轻轻，灯下交鸳颈。端详可憎，好煞人也无干净！
[末云]小娘子先行，小生收拾书房便来。敢问那里有甚么景致？[红唱]
[耍孩儿]俺那里有落红满地胭脂冷，休辜负了良辰美景。夫人遣妾莫消停，请先生勿得推称。俺那里准备着鸳鸯夜月销金帐，孔雀春风软玉屏。乐奏合欢令，有凤箫象板，锦瑟鸾笙。
[末云]小生书剑飘零，无以为财礼，却是怎生？[红唱]
[四煞]聘财断不争，婚姻自有成，新婚燕尔安排定。你明博得跨凤乘鸾客，我到晚来卧看牵牛织女星。休蹊幸，不要你半丝儿红线，成就了一世儿前程。
[三煞]凭着你灭寇功，举将能，两般儿功效如红定。为甚俺莺娘心下十分顺，都则为君瑞胸中百万兵。越显得文风盛，受用足珠围翠绕，结果了黄卷青灯。
[二煞]夫人只一家，老兄无伴等，为嫌繁冗寻幽静。[末云]别有甚客人？[红唱]单请你个有恩有义闲中客，且回避了无是无非窗下僧。夫人的命，道足下莫教推托，和贱妾即便随行。
[末云]小娘子先行，小生随后便来。[红唱]
[收尾]先生休作谦，夫人专意等。常言道“恭敬不如从命”，休使得梅香再来请。[下]
[末云]红娘去了，小生拽上书房门者。我比及得夫人那里，夫人道：“张生，你来了也，饮几杯酒，去卧房内和莺莺做亲去！”小生到得卧房内，和姐姐解带脱衣，颠鸾倒凤，同谐鱼水之欢，共效于飞之愿。觑他云鬟低坠，星眼微朦，被翻翡翠，袜绣鸳鸯；不知性命何如？且看下回分解。
[笑云]单羡法本好和尚也:只凭说法口，遂却读书心。[下]', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2825914587d02f58a49", "shortContent": "孙飞虎围普救寺，老夫人宣称，但有退兵之策的，倒赔房奁，将莺莺与他为妻。此时张生急修一书，请惠明下书，请来白马将军，遂解普救寺之围。这时，老夫人说一句“到明日略备草酌，着红娘来请”后，张生分外兴奋。翌日，他悉心打扮得干干净净，“皂角也使过两个也，水也换了两桶也，乌纱帽擦得光挣挣的”，心急火燎地盼望着红娘来请。终于红娘的敲门声响了。一听说红娘是“奉夫人严命，特请先生小酌数杯”，他疾忙云“便去，便去”，...", "authors": ["孙", "逊"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f4161c6e67846a9227685", "shortContent": null, "authors": ["孙崇涛", "李季箴"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572706371, '5dbd27bf12215f00711c9afb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643554, '西厢记 · 第二本 · 第三折', NULL, 0, 41, 3, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[夫人排桌子上云]红娘去请张生，如何不见来？[红见夫人云]张生着红娘先行，随后便来也。[末上见夫人施礼科][夫人云]前日若非先生，焉得有今日；我一家之命，皆先生所活也。聊备小酌，非为报礼，勿嫌轻意[末云]“一人有庆，兆民赖之。”此贼之败，皆夫人之福。万一杜将军不至，我辈皆无免死之术。此皆往事，不必挂齿。[夫人云]将酒来，先生满饮此杯。[末云]“长者赐，少者不敢辞。”[末做饮酒科][末把夫人酒了][夫人云]先生请坐！[末云]小子侍立座下，尚然越礼，焉敢与夫人对坐。[夫人云]道不得个“恭敬不如从命”。[末谢了，坐][夫人云]红娘，去唤小姐来，与先生行礼者！[红朝鬼门道唤云]老夫人后堂待客，请小姐出来哩！[旦应云]我身子不些不停当，来不得。[红云]你道请谁哩？[旦云]请谁？[红云]请张生哩？[旦云]若请张生，扶病也索走一遭。[红发科了][旦上]免除崔氏全家祸，尽在张生半纸书。
[双调][五供养]若不是张解元识人多，别一个怎退干戈。排着酒果，列着笙歌。篆烟微，花香细，散满东风帘幕。救了咱全家祸，殷勤呵正礼，钦敬呵当合。
[新水令]恰才向碧纱窗下画了双蛾，拂拭了罗衣上粉香浮涴，只将指尖儿轻轻的贴了钿窝。若不是惊觉人呵，犹压着绣衾卧。
[红云]觑俺姐姐这个脸儿吹弹得破，张生有福也呵！[旦唱]
[幺篇]没查没利谎偻儸，你道我宜梳妆的脸儿吹弹得破。[红云]俺姐姐天生的一个夫人的样儿。[旦唱]你那里休聒，不当信口开合。知他命福是如何？我做一个夫人也做得过。
[红云]往常两个都害，今日早则喜也！[旦唱]
[乔木查]我相思为他，他相思为我，从今后两下里相思都较可。酬贺间礼当酬贺，俺母亲也好心多。
[红云]敢着小姐和张生结亲呵，怎生不做大筵席，会亲戚朋友，安排小酌为何？[旦云]红娘，你不知夫人意。
[搅筝琶]他怕我是赔钱货，两当一便成合。据着他举将除贼，也消得家缘过活。费了甚一股那，便待要结丝萝；休波，省人情的奶奶忒虑过，恐怕张罗。
[末云]小子更衣咱。[做撞见旦科][旦唱]
[庆宣和]门儿外，帘儿前，将小脚那。我恰待目转秋波，谁想那识空便的灵心儿早破。唬得我倒躲，倒躲。
[末见旦科][夫人云]小姐近前拜了哥哥者！[末背云]呀，声息不好了也！[旦云]呀，俺娘变了卦也！[红云]这相思又索害也。[旦唱]
[雁儿落]荆棘剌怎动那！死没腾无回豁！措支剌不对答！软兀剌难存坐！
[得胜令]谁承望这即即世世老婆婆，着莺莺做妹妹拜哥哥。白茫茫溢起蓝桥水，不邓邓点着袄庙火。碧澄澄清波，扑剌剌将比目鱼分破；急攘攘因何，疙瘩地把双眉锁纳合。
[夫人云]红娘看热酒，小姐与哥哥把盏者！[旦唱]
[甜水令]我这里粉颈低垂，蛾眉频蹙，芳心无那，俺可甚“相见话偏多”？星眼朦胧，檀口嗟咨，攧窨不过，这席面儿畅好是乌合。
[旦把酒科][夫人央科][末云]小生量窄。[旦云]红娘接了台盏者！
[折桂令]他其实咽不下玉液金波。谁承望月底西厢，变做了梦里南柯。泪眼偷淹，酩子里搵湿香罗。他那里恨倦开软瘫做一垛；我这里手难抬称不起肩窝。病染沈疴，断然难活。则被你送了人呵，当甚么喽啰。
[夫人云]再把一盏者！[红递盏了][旦唱]
[月上海棠]一杯闷酒尊前过，低首无言自摧挫。不甚醉颜酡，却早嫌玻璃盏大。从因我，酒上心来较可。[红背与旦云]姐姐，这烦恼怎生是了！[旦唱]
[幺篇]而今烦恼犹闲可，久后思量怎奈何？有意诉衷肠，争奈母亲侧坐，成抛躲，咫尺间发如间阔。
[夫人云]红娘送小姐卧房里去者！[旦辞末出科][旦云]俺娘好口不应心也呵！
[乔牌儿]老夫人转关儿没定夺，哑谜儿怎猜破；黑阁落甜话儿将人和，请将来着人不快活。
[江水儿]佳人自来多命薄，秀才每从来懦。闷杀没头鹅，撇下陪钱货；不争你不成亲呵，下场头那答儿发付我！
[殿前欢]恰才个笑呵呵，都做了江州司马泪痕多。若不是一封书将半万贼兵破，俺一家怎得存活。他不想结姻缘想甚么？到如今难着莫。老夫人谎到天来大；当日成也是您个母亲，今日败也是您个萧何。
[离亭宴带歇指煞]从今后玉容寂寞梨花朵，胭脂浅淡樱桃颗，这相思何时是可？昏邓邓黑海来深，白茫茫陆地来厚，碧悠悠青天来阔；太行山般高仰望，东洋海般深思渴。毒害的恁么。俺娘呵，将颤巍巍双头花蕊搓，香馥馥同心缕带割，长搀搀连理琼枝挫。白头娘不负荷，青春女成担阁，将俺那锦片也似前程蹬脱。俺娘把甜句儿落空了他，虚名儿误赚了我。[下]
[末云]小生醉也，告退。夫人根前，欲一言以尽意，未知可否？前者贼寇相迫，夫人所言，能退贼者，以莺莺妻之。小生挺身而出，作书与杜将军，庶几得免夫人之祸。今日命小生赴宴，将谓有喜庆之期；不知夫人何见，以兄妹之礼相待？小生非图哺啜而来，此事果若不谐，小生即当告退。[夫人云]先生纵有活我之恩，奈小姐先相国在日，曾许下老身侄儿郑恒。即日有书赴京唤去了，未见来。如若此子至，其事将如之何？莫若以金帛相酬，先生拣豪门贵宅之女，别为之求，先生台意若何？[末云]既然夫人不与，小生何慕金帛之色？却不道“书中有女颜如玉”？则今日便索告辞。[夫人云]你且住者，今日有酒也。红娘扶哥哥去书房中歇息，到明日咱别有话说。[下][红扶末科][末念]有分只熬萧寺夜，无缘难遇洞房春。[红云]张生，少吃一盏却不好！[末云]我吃甚么来！[末跪红科]小生为小姐，昼夜忘餐废寝，魂劳梦断，常忽忽如有所失。自寺中一见，隔墙酬和，迎风待月，受无限之苦楚。甫能得成就婚姻，夫人变了卦，使小生智竭思穷，此事几时是了！小娘子怎生可怜小生，将此意申与小姐，知小生之心。就小娘子前解下腰间之带，寻个自尽。[末念]可怜刺股悬梁志，险作离乡背井魂。[红云]街上好贱柴，烧你个傻角。你休慌，妾当与君谋之。[末云]计将安在？小生当筑坛拜将。[红云]妾见先生有囊琴一张，必善于此。俺小姐深慕于琴。今夕妾与小姐同至花园内烧夜香，但听咳嗽为令，先生动操；看小姐听得时说甚么言语，却将先生之言达知。若有话说，明日妾来回报，这早晚怕夫人寻我，回去也。[下]', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec28234a8757d5a0ec5ba", "shortContent": "崔、张的爱情之舟，在获得了“白马解围”这一意外的驱动力之后，摆脱了“山重水复疑无路”的困境，驶入了“柳暗花明又一村”的新天地，婚姻的港湾已经在望。但是，书剑飘零的白衣秀士，并不符合相国家谱的择婿标准，老夫人关于“但有退兵之策的，倒陪房奁，断送莺莺与他为妻”的当众承诺，不过是生死关头的权宜之计。“虽然不是门当户对，也强如陷于贼中”，乃是她彼时彼地接受莺莺所提“五便三计”之第三计的真实思想，而今事过境...", "authors": ["高建中"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f41620f8fda556506ebc1", "shortContent": null, "authors": ["俞为民"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f417303048e64fbdaa029", "shortContent": "喜的此间有门半开且自捱身进去。\n原来一位相公。为何夤夜到此？（生）小生在难中，特来投奔，伏乞老母哀留。（老旦）你是读书人，住的高堂大屋，吃的美酒粱肉，穿带的锦绣珠玉，跟随的琴童伴读，有什么难？喘息定了，慢慢与老身说知。\n旦）想有许多行李。（生）尽书笈，和琴剑，布囊中，驴背上算来无\n否？（生）迁延犹未订姻盟，指望图归聘。（旦）官人上姓？（生）【皂罗袍】小生杨姓，直方是名，字称益友，因来帝京，生生死死...", "authors": ["杨景龙"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572706434, '5dbd27f717b54d006c7b376f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643555, '西厢记 · 第二本 · 第四折', NULL, 6, 41, 1, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[末上云]红娘之言，深有意趣。天色晚也，月儿，你早些出来么！[焚香了]呀，却早发擂也；呀，却早撞钟也。[做理琴科]琴呵，小生与足下湖海相随数年，今夜这一场大功，都在你这神品、金徽、玉轸、蛇腹、断纹、峄阳、焦尾、冰弦之上。天哪！却怎生借得一阵顺风，将小生这琴声吹入俺那小姐玉琢成、粉捏就、知音的耳朵里去者！[旦引红上，红云]小姐，烧香去来，好明月也呵！[旦云]事已无成，烧香何济！月儿，你团圆呵，咱却怎生？
[越调][斗鹌鹑]云敛晴空，冰轮乍涌；风扫残红，香阶乱拥；离恨千端，闲愁万种。夫人哪，“靡不有初，鲜克有终。”他做了影儿里的情郎，我做了画儿里的爱宠。
[紫花儿序]则落得心儿里念想，口儿里闲提，则索向梦儿里相逢。俺娘昨日个大开东阁，我则道怎生般炮凤烹龙？朦胧，可教我“翠袖殷勤捧玉钟”，却不道“主人情重”？则为那兄妹排连，因此上鱼水难同。
[红云]姐姐，你看月阑，明日敢有风也？[旦云]风月天边有，人间好事无。
[小桃红]人间看波，玉容深锁绣帏中，怕有人搬弄。想嫦娥，西没东生谁与共？怨天公，裴航不作游仙梦。这云似我罗帏数重，只恐怕嫦娥心动，因此上围住广寒宫。
[红做咳嗽科][末云]来了。[做理琴科][旦云]这甚么响？[红发科][旦唱]
[天净沙]莫不是步摇得宝髻玲珑？莫不是裙拖得环佩叮咚？莫不是铁马儿檐前骤风？莫不是金钩双控吉丁当敲响帘栊？
[调笑令]莫不是梵王宫，夜撞钟？莫不是疏潇潇曲槛中？莫不是牙尺剪刀声相送？莫不是漏声长滴响壶铜？潜身再听在墙角东，原来是近西厢理连结丝桐。
[秃厮儿]其声壮，似铁骑刀枪冗冗；其声幽，似落花流水溶溶；其声高，似风清月朗鹤唳空；其声低，似听儿女语，小窗中，喁喁。
[圣药王]他那里思不穷，我这里意已通，娇鸾雏凤失雌雄；他曲未终，我意转浓，争奈伯劳飞燕各西东：尽在不言中。
我近书窗听咱。[红云]姐姐，你这里听，我瞧夫人一会便来。[末云]窗外有人，已定是小姐，我将弦改过，弹一曲，就歌一篇，名曰《凤求凰》。昔日司马相如得此曲成事，我虽不及相如，愿小姐有文君之意。[歌曰]有美人兮，见之不忘。一日不见兮，思之如狂。凤飞翩翩兮，四海求凰。无奈佳人兮，不在东墙。张弦代语兮，欲诉衷肠。何时见许兮，慰我彷徨？愿言配德兮，携手相将！不得于飞兮，使我沦亡。[旦云]是弹得好也呵！其词哀，其意切，凄凄如鹤唳天；故使妾闻之，不觉泪下。
[麻郎儿]这的是令他人耳聪，诉自己情衷。知音者芳心自懂，感怀者断肠悲痛。
[幺篇]这一篇与本宫、始终、不同。又不是清夜闻钟，又不是黄鹤醉翁，又不是泣麟悲凤。
[络丝娘]一字字更长漏永，一声声衣宽带松。别恨离愁，变成一弄。张生呵，越教人知重。
[末云]夫人且做忘恩，小姐，你也说谎也呵！[旦云]你羞怨了我。
[东原乐]这的是俺娘的机变，非干是妾身脱空；若由得我呵，乞求得效鸾凤。俺娘无夜无明并女工；我若得些儿闲空，张生呵，怎教你无人处把妾身做诵。
[绵搭絮]疏帘风细，幽室灯清，都则是一层儿红纸，几榥儿疏檑，兀的不是隔着云山几万重，怎得个人来信息通？便做道十二巫峰，他也曾赋高唐来梦中。
[红云]夫人寻小姐哩，咱家去来。[旦唱]
[拙鲁速]则见他走来气冲冲，怎不教人恨匆匆。唬得人来怕恐。早是不曾转动，女孩儿家直凭响喉咙！紧摩弄，索将他拦纵，则恐夫人行把我来厮葬送。
[红云]姐姐则管听琴怎么？张生着我对姐姐说，他回去也。[旦云]好姐姐呵，是必再着他住一程儿！[红云[再说甚么？[旦云]你去呵，
[尾]则说道夫人时下有人唧哝，好共歹不着你落空。不问俺口不应的狠毒娘，怎肯着别离了志诚种？[并下]', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec282c6e67846a9218b10", "shortContent": "在张生、莺莺的爱情故事发展过程中，当孙飞虎兵围普救寺，要抢莺莺为压寨夫人之际，老夫人曾许下诺言：谁退脱贼兵，即将莺莺许配。孰知张生修书央白马将军平乱之后，老夫人食言而赖婚。张生于极度苦闷中，请红娘转致思念之情。红娘献计，让张生月夜操琴，以挑动之。故事到这里又进入了一个转折点。这四支曲子全是莺莺在花园中烧夜香时所唱，第一曲为尚未听到琴声时所唱，后面三曲则是听到琴声之后的一些思想活动。\n在唱〔小桃红〕...", "authors": ["蒋星煜"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2890f8fda556505ffba", "shortContent": "《张生煮海》是一出流传甚广的神话剧。从剧情来看，剧中的男女主角，书生张羽和龙女琼莲，郎才女貌，一见倾心，没有脱开中国古代戏剧爱情题材中那一类窠臼，然而自有其魅力所在，如曲辞的优美并适合舞台的演出，就是其中一个原因。\n这一折是说潮州青年书生张羽，游览海滨，寄居在石佛寺里读书。他夜里抚琴消遣，吸引了从海里出游的龙王之女琼莲，两人一见钟情，私订终身。〔那吒令〕〔鹊踏枝〕二支曲系正旦扮龙女所唱，写的是琼莲...", "authors": ["师", "飙"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f4167c6e67846a92276a1", "shortContent": "东边日出西边雨，莫道无情却有情。日间红娘说道相如将琴挑动文君之意，不免叫琴童取琴出来。琴童何在？（丑上）夜静瑶琴三五弄，悲风动处月光寒。知音弹与知音听，不是知音不与弹。琴在此。（生）琴童，你与我烧下一炉香，煎下一罐茶，你自回避。（丑应下）（生）爨下焦桐玉琢成[1]，轻勾缓剔凤凰鸣。高山流水千年调，《白雪》《阳春》万古情。松籁响，涧泉清，携来指下韵将成。文君未必能知否，月满池塘夜气清。你这琴呵，小生...", "authors": ["周锡山"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f417134a8757d5a0faba8", "shortContent": "奴家杨氏妙香是也。雅负工容[2]，颇饶风韵，不幸丈夫亡故，独守孤帏。临终遗命，待坟土干了，教奴嫁人，因此忙劫劫的把他安葬，已经两月，频来看视，土尚未干。连日苦遭风雪，不得出来，今日晴暖，不免看一遭去。呀，春暖雪消，坟土一发湿了，如何是好？雪呵，你就是我杨妙香的对头了。（想介）我想雪犹自可，如今春天的雨，是长要下的，空眼巴巴的望这块土怎生得干？不免将手中扇子，满,扇他几日，扇干了嫁了人去，后边下雨下...", "authors": ["冯俊杰"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572706475, '5dbd2828eaa375006c48f02e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643556, '西厢记 · 第三本 · 楔子', NULL, 2, 41, 0, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[旦上云]自那夜听琴后，闻说张生有病，我如今着红娘去书院里，看他说甚么。[叫红科][红上云]姐姐唤我，不知有甚事，须索走一遭。[旦云]这般身子不快呵，你怎么不来看我？[红云]你想张——[旦云]张甚么？[红云]我“张”着姐姐哩。[旦云]我有一件事央及你咱。[红云]甚么事？[旦云]你与我望张生走一遭，看他说甚么，你来回我话者。[红云]我不去，夫人知道不是耍。[旦云]好姐姐，我拜你两拜，你便与我走一遭！[红云]侍长请起，我去则便了。说道：“张生，你好生病重，则俺姐姐也不弱。”只因午夜调琴手，引起春闺爱月心。
[仙吕][赏花时]俺姐姐针线无心不待拈，脂粉香消懒去添。春恨压眉尖，若得灵犀一点，敢医可了病恹恹。[下]
[旦云]红娘去了，看他回来说甚话，我自有主意。[下]', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2b00ce818559d063674", "shortContent": "《留鞋记》是“一本烟花粉黛性质的儿女风情戏，但因为其中有包待制的出场勘断，故也可以列为公案剧之一”（严敦易《元剧勘疑》）。剧中的矛盾冲突、包公断案，特别是女主人公王月英的形象皆别具一格。王月英不是大家闺秀，也不是小家碧玉，而是一位出生于繁华都市又亲自经商的市民姑娘。她既不深居闺阁描鸾绣凤，也不抛头露面采桑拾柴，而是坐守胭脂铺，做生意赚钱。郭华多次去买脂粉，她敏锐地感觉到郭“趋前退后，待言语却又早紧...", "authors": ["李春祥", "李恒义"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f41635914587d02f67699", "shortContent": "《拜月亭》是根据关汉卿的杂剧《闺怨佳人拜月亭》改写的，《幽闺拜月》是其中最精彩的一出戏。这一出戏的矛盾冲突有两条线：一条是瑞兰与王镇的思想冲突，这是通过瑞兰的离愁、幽怨的抒写，侧面得到表现的，带有悲剧的因素；另一条是瑞兰与瑞莲的性格冲突，这是通过姊妹调笑展开的，染有喜剧色彩。由于瑞兰的爱情不是没有希望的，特别是由于瑞莲有着机智伶俐的性格，在这一出戏悲喜交融的色调中，喜剧色彩就占了主导的地位。\n这是...", "authors": ["赵山林"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f416e2e6a6b501f9753a0", "shortContent": "旦）红袖共隈依，问谁娇媚？〔诉衷情〕宝鸭香消帘半卷，梦初醒。天气好，花事又凋零。（小旦）何处小莺声？轻轻绣幕暗生尘。负春情。（旦）秋英，我今日身子困倦，睡起得迟了些，不知甚么时候了？（小旦）小姐，是日午光景了。（旦）我睡起无聊，且和你到后花园楼上耍子一回去[1]。（小旦）小姐，正是有这等一桩好笑的事。早上我到园里摘花儿，西邻的登徒大夫[2]，在门外窥望。我问他你是何人，他说要见小姐一面，又有许多胡...", "authors": ["段启明", "彭利芝"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f4185c6e67846a922772b", "shortContent": "（旦、贴上）\n儿，不想许郎听信法海言语，竟不下山。我和他争斗，奈他法力高强，险被擒拿。幸借水遁，来到临安，哎呀，不然险遭一命。（贴）娘娘，仔细想将起来，都是许宣那厮薄幸。若此番见面，断断不可轻恕！（旦）便是。（贴）如今我每往那里去藏身才好？（旦）我向闻许郎有一姐姐，嫁与李仁，在此居住。我和你且投奔到彼。（贴）只是从未识面，倘不相留，如何是好？（旦）我每到彼，再作区处。（贴）如此，娘娘请。（旦行）（...", "authors": ["郭", "梅"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572706610, '5dbd28af12215f00711ca520', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643557, '西厢记 · 第三本 · 第一折', NULL, 1, 41, 0, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[末上云]害杀小生也。自那夜听琴后，再不能够见俺那小姐。我着长老说将去，道张生好生病重，却怎生不见人来看我？却思量上来，我睡些儿咱。[红上云]奉小姐言语，着我看张生，须索走一遭。我想咱每一家，若非张生，怎存俺一家儿性命也？
[仙吕][点绛唇]相国行祠，寄居萧寺。因丧事，幼女弧儿，将欲从军死。
[混江龙]谢张生伸志，一封书到便兴师。显得文章有用，足见天地无私。若不是剪草除根半万贼，险些儿灭门绝户俺一家儿。莺莺君瑞，许配雄雌；夫人失信，推托别词；将婚姻打灭，以兄妹为之。如今都废却成亲事，一个价愁糊突了胸中锦绣，一个价泪搵了脸上胭脂。
[油葫芦]憔悴潘郎鬓有丝；杜韦娘不似旧时，带围宽清减了瘦腰肢。一个睡昏昏不待观经史，一个意悬悬懒去拈针线；一个丝桐上调弄出离恨谱，一个花笺上删抹成断肠诗；一个笔下写幽情，一个弦上传心事：两下里都一样害相思。
[天下乐]方信道才子佳人信有之，红娘看时，有些乖性儿，则怕有情人不遂心也似此。他害的有些抹媚，我遭着没三思，一纳头安排着憔悴死。
却早来到书院里，我把唾津儿润破窗纸，看他在书房里做甚么。
[村里迓鼓]我将这纸窗儿润破，悄声儿窥视。多管是和衣儿睡起，罗衫上前襟褶祬。孤眠况味，凄凉情绪，无人伏侍。觑了他涩滞气色，听了他微弱场息，看了他黄瘦脸儿。张生呵，你若不闷死多应是害死。
[元和令]金钗敲门扇儿。[末云]是谁？[红唱]我是个散相思的五瘟使。俺小姐想着风清月朗夜深时，使红娘来探尔。[末云]既然小娘子来，小姐必有言语。[红唱]俺小姐至今脂粉未曾施，念到有一千番张殿试。
[末云]小姐既有见怜之心，小生有一简，敢烦小娘子达知肺腑咱。[红云]只恐他翻了面皮。
[上马娇]他若是见了这诗，看了这词，他敢颠倒费神思。他拽起面皮来：“查得谁的言语你将来，这妮子怎敢胡行事？”他可敢嗤、嗤的扯做了纸条儿。
[末云]小生久后多以金帛拜酬小娘子。[红唱]
[胜葫芦]哎，你个馋穷酸倈没意儿，卖弄你有家私，莫不图谋你的东西来到此？先生的钱物，与红娘做赏赐，是我爱你的金资？
[幺篇]你看人似桃李春风墙外枝，卖俏倚门儿。我虽是个婆娘有志气。则说道：“可怜见小子，只身独自！”恁的呵，颠倒有个寻思。
[末云]依着姐姐，可怜见小子只身独自！[红云]兀的不是也，你写来，咱与你将去。[末写科][红云]写得好呵，读与我听咱。[末读云]珙百拜奉书芳卿可人妆次：自别颜范，鸿稀鳞绝，悲怆不胜。孰料夫人以恩成怨，变易前姻，岂得不为失信乎？使小生目视东墙，恨不得腋翅于汝台左右；患成思渴，垂命有日。因红娘至，聊奉数字，以表寸心。万一有见怜之意，书以掷下，庶几尚可保养。造次不谨，伏乞情恕！后成五言诗一首，就书录呈：相思恨转添，谩把瑶琴弄。乐事又逢春，芳心尔亦动。此情不可违，芳誉何须奉？莫负月华明，且怜花影重。[红唱]
[后庭花]我则道拂花笺打稿儿，原来他染霜毫不构思。先写下几句寒温序，后题着五言八句诗。不移时，把花笺锦字，叠做同心方胜儿。忒聪明，忒敬思，忒风流，忒浪子。虽然是假意儿，小可的难到此。
[青歌儿]颠倒写鸳鸯两字，方信道“在心为志”。[末云]姐姐将去，是必在意者！[红唱]看喜怒其间觑个意儿。放心波学士！我愿为之，并不推辞，自有言词。则说道：“昨夜弹琴的那人儿，教传示。”
这简帖儿我与你将去，先生当以功名为念，休堕了志气者！
[寄生草]你将那偷香手，准备着折桂枝。休教那淫词儿污了龙蛇字，藕丝儿缚定鵾鹏翅，黄莺儿夺了鸿鹄志；休为这悴帏锦帐一佳人，误了你“玉堂金马三学士”。
[末云]姐姐在意者！[红云]放心，放心！
[煞尾]沈约病多般，宋玉愁无二，清减了相思样子。则你那眉眼传情未了时，中心日夜藏之。怎敢因而，“有美玉于斯”，我须教有发落归着这张纸。凭着我舌尖上说词，更和这简帖儿里心事，管教那人来探你一遭儿。[下]
[末云]小娘子将简帖儿去了，不是小生说口，则是一道会亲的符篆。他明日回话，必有个次第。且放下心，须索好音来也。“且将宋玉风流策，寄与蒲东窈窕娘。”[下]', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec273911759740c9bc4e4", "shortContent": "这是一套极富喜剧性的散曲，它通过一位女子接读一封不无虚情假意的“情书”的前后情态变化，将主人公既爱又恨的心理，剖绘得淋漓尽致，颇有生活气息。\n首曲写一派暮春景象：黄莺儿金翅翩跹，在柳枝间穿梭，一忽儿又飞上高枝。这使人想到“两个黄鹂鸣翠柳”（杜甫《绝句》）的名句。它们的歌舞，是主人公寂寞孤独的反衬。红色的海棠花瓣，飘落满阶，如泪洒胭脂，是主人公怨苦的象征。这里的写景不但十分关情，而且造语尖新俏丽，“...", "authors": ["周啸天"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec27c2e6a6b501f966dcf", "shortContent": "白朴的杂剧现存仅《梧桐雨》、《墙头马上》、《东墙记》三种。有论者提出《东墙记》非白朴所作，但元代钟嗣成《录鬼簿》白朴名下有此剧著录。明初朱权《太和正音谱》著录亦作白朴作。看来，疑《东墙记》非白朴之作理由尚不充分。问题是今存《孤本元明杂剧》收录的传本，是否即白朴的原作抑或经过改动，这尚待作进一步的考证。至于传说白朴作此剧是为了与王实甫《西厢记》争胜，则更无从稽考了。\n《东墙记》写的是马文辅与董秀英的...", "authors": ["胡雪冈"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f41865914587d02f67864", "shortContent": "（末纱帽上）\n自叹劳劳役簿书，十年驰骋短辕车。丹忱未必人知道，趵突泉清定鉴余。下官吴南岱，调任济南知府。家传诗礼，惭叨甲乙榜之名；位绍龚黄[1]，勉守清白吏之志。自笑才非肆应，出纳偏握微权；深知政拙抚循，讼狱尤多发审。昨日柏署发下聊城县一案[2]，图奸未成，拒杀事主。凶犯虽已弋获，案情颇觉含糊。匆匆过堂，未及细讯。看那凶犯，是一瘦怯书生，绝不类杀人者，因此迟疑。今早遣一亲信家丁，潜往狱中察访，待他...", "authors": ["宋光祖"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572706673, '5dbd28eef884af0073380dcd', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643558, '西厢记 · 第三本 · 第二折', NULL, 1, 41, 0, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[旦上云]红娘伏侍老夫人不得空便，偌早晚敢待来也。起得早了些儿，困思上来，我再睡些儿咱。[睡科][红上云]奉小姐言语去看张生，因伏侍老夫人，未曾回小姐话去。不听得声音，敢以睡哩，我入去看一遭。
[中吕][粉蝶儿]风静帘闲，透纱窗麝兰香散，启朱扉摇响双环。绛台高，金荷小，银釭犹灿。比及将暖帐轻弹，先揭起这梅红罗软帘偷看。
[醉春风]则见他钗躭玉斜横，髻偏云乱挽。日高犹自不明眸，畅好是懒、懒。[旦做起身长叹科][红唱]半晌抬身，几回搔耳，一声长叹。
我待便将简帖儿与他，恐俺小姐有许多假处哩。我则将这简帖儿放在妆盒儿上，看他见了说甚么。[旦做照镜科，见帖看科][红唱]
[普天乐]晚妆残，乌云躭，轻匀了粉脸，乱挽起云鬟。将简帖儿拈，把妆盒儿按，开拆封皮孜孜看，颠来倒去不害心烦。[旦怒叫]红娘！[红做意云]呀，决撒了也！厌的早杚皱了黛眉。[旦云]小贱人，不来怎么！[红唱]忽的波低垂了粉颈，氲的呵改变了朱颜。
[旦云]小贱人，这东西那里将来的？我是相国的小姐，谁敢将这简帖来戏弄我，我几曾惯看这等东西？告过夫人，打下你个小贱人下截来。[红云]小姐使将我去，他着我将来。我不识字，知他写着甚么？
[快活三]分明是你过犯，没来由把我摧残；使别人颠倒恶心烦，你不惯，谁曾惯？
姐姐休闹，比及你对夫人说呵，我将这简帖儿去夫人行出首去来。[旦做揪住科]我逗你耍来。[红云]放手，看打下下截来。[旦云]张生近日如何？[红云]我则不说。[旦云]好姐姐，你说与我听咱！[红唱]
[朝天子]张生近间、面颜，瘦得来实难看。不思量茶饭，怕待动弹；晓夜将佳期盼，废寝忘餐。黄昏清旦，望东墙淹泪眼。[旦云]请个好太医看他症候咱。[红云]他证候吃药不济。病患、要安，则除是出几点风流汗。
[旦云]红娘，不看你面时，我将与老夫人看，看他有何面目见夫人？虽然我家亏他，只是兄妹之情，焉有外事。红娘，早是你口稳哩；若别人知呵，甚么模样。[红云]你哄着谁哩，你把这个饿鬼弄得他七死八活，却要怎么？
[四边静]怕人家调犯，“早共晚夫人见些破绽，你我何安。”问甚么他遭危难？撺断得上竿，掇了梯儿看。
[旦云]将描笔儿过来，我写将去回他，着他下次休是这般。[旦做写科][起身科云]红娘，你将去说：“小姐看望先生，相待兄妹之礼如此，非有他意。再一遭儿是这般呵，必告夫人知道。”和你个小贱人都有话说。[旦掷书下][红唱]
[脱布衫]小孩儿家口没遮拦，一味的将言语摧残。把似你使性子，休思量秀才，做多少好人家风范。[红做拾书科]
[小梁州]他为你梦里成双觉后单，废寝忘餐。罗衣不奈五更寒，愁无限，寂寞泪阑干。
[幺篇]似这等辰勾空把佳期盼，我将这角门儿世不曾牢拴，则愿你做夫妻无危难。我向这筵席头上整扮，做一个缝了口的撮合山。
[红云]我若不去来，道我违拗他，那生又等我回报，我须索走一遭。[下][末上云]那书倩红娘将去，未见回话。我这封书去，必定成事，这早晚敢侍来也。[红上云]须索回张生话去。小姐你性儿忒惯得娇了；有前日的心，那得今日的心来？
[石榴花]当日个晚妆楼上杏花残，犹自怯衣单，那一片听琴心清露月明间。昨日个向晚，不怕春寒，几乎险被“先生馔”，那其间岂不胡颜。为一个不酸不醋风魔汉，隔墙儿险化做了望夫山。
[斗鹌鹑]你用心儿拨雨撩云，我好意儿传书寄简。不肯搜自己狂为，则待要觅别人破绽。受艾焙权时忍这番。畅好是奸。“张生是兄妹之礼，焉敢如此！”对人前巧语花言；没人处便想张生，背地里愁眉泪眼。
[红见末科][末云]小娘子来了。擎天柱，大事如何了也？[红云]不济事了，先生休傻。[末云]小生简帖儿是一道会亲的符篆，则是小娘子不用心，故意如此。[红云]我不用心？有天理，你那简帖儿好听！
[上小楼]这的是先生命悭，须不是红娘违慢。那简帖儿倒做了你的招状，他的勾头，我的公案。若不是觑面颜，厮顾盼，担饶轻慢，先生受罪，礼之当然。贱妾何辜？争些儿把你娘拖犯。
[幺篇]从今后相会少，见面难。月暗西厢，凤去秦楼，云敛巫山。你也赸，我也赸；请先生休讪，早寻个洒阑人散。
[红云]只此再不必申诉足下肺腑，怕夫人寻，我回去也。[末云]小娘子此一遭去，再着谁与小生分剖；必索做一个道理，方可救小生一命。[末跪下揪住红科][红云]张先生是读书人，岂不知此意，其事可知矣。
[满庭芳]你休要呆里撒奸；你待要恩情美满，却教我骨肉摧残。老夫人手执着棍儿摩娑看，粗麻线得针关。直待我拄着拐帮闲钻懒，缝合唇送暖偷寒。待去呵，小姐性儿撮盐入火，消息儿踏着泛；待不去呵，[末跪哭云]小生这一个性命，都在小娘子身上。[红唱]禁不得你甜话儿热趱：好着我两下里难人做。
我没来由分说；小姐回与你的书，你自看者。[末接科，开读科]呀，有这场喜事，撮土焚香，三拜礼毕。早知小姐简至，理合远接，接待不及，勿令见罪！小娘子，和你也欢喜。[红云]怎么？[末云]小姐骂我都是假，书中之意，着我今夜花园里来，和他“哩也波哩也罗”哩。[红云]你读书我听。[末云]“待月西厢下，迎风户半开，隔墙花影动，疑是玉人来。”[红云]怎见得他着你来？你解与我听咱。[末云]“待月西厢下”，着我月上来；“迎风户半开”，他开门待我；“隔墙花影动，疑是玉人来”，着我跳过墙来。[红笑云]他着你跳过墙来，你做下来。端的有此说么？[末云]俺是个猜诗谜的社家，风流隋河，浪子陆贾，我那里有差的勾当。[红云]你看我姐姐，在我行也使这般道儿。
[耍孩儿]几曾见寄书的颠倒瞒着鱼雁，小则小心肠儿转关。写着西厢待月等得更阑，着你跳东墙“女”字边“干”。原来那诗句儿里包笼着三更枣，简帖儿里埋伏着九里山。他着紧处将人慢，您会云雨闹中取静，我寄音书忙里偷闲。
[四煞]纸光明玉板，字香喷麝兰，行儿边湮透非春汗？一缄情泪红犹湿，满纸春愁墨未干。从今后休疑难，放心波玉堂学士，稳情取金雀鸦鬟。
[三煞]他人行别样的亲，俺跟前取次看，更做道孟光接了梁鸿案。别人行甜言美语三冬暖，我跟前恶语伤人六月寒。我为头儿看：看你个离魂倩女，怎发付掷果潘安。
[末云]小生读书人，怎跳得那花园过也？[红唱]
[二煞]隔墙花又低，迎风户半拴，偷香手段今番按。怕墙高怎把龙门跳，嫌花密难将仙桂攀。放心去，休辞惮；你若不去呵，望穿他盈盈秋水，蹙损他淡淡春山。
[末云]小生曾到那花园里，已经两遭，不见那好处；这一遭知他又怎么？[红云]如今不比往常。
[煞尾]你虽是去了两遭，我敢道不如这番。你那隔墙酬和都胡侃，证果的是今番这一简。[红下]
[末云]万事自有分定，谁想小姐有此一场好处。小生是猜诗谜的社家，风流隋何，浪子陆贾，到那里搿扎帮便倒地。今日颓天百般的难得晚。天，你有万物于人，何故争此一日？疾下去波！读书继晷怕黄昏，不觉西沉强掩门；欲赴海棠花下约，太阳何苦又生根？[看天云]呀，才晌午也，再等等。[又看科]今日万般的难得下去也呵。碧天万里无云，空劳倦客身心；恨杀鲁阳贪战，不教红日西沉！呀，却早倒西也，再等一等咱。无端的三足乌，团团光烁烁；安得后羿弓，射此一轮落？谢天地！却早日下去也！呀，却早发擂也！呀，却早撞钟也！拽上书房门，到得那里，手挽着垂杨滴流扑跳过墙去。[下]', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2805e272d4b2254d9c0", "shortContent": "马丹阳，金代道士。全真教“遇仙派”创始人。任风子可能是传说人物。\n根据“杂剧十二科”的分类，此剧属于“神仙道化”，为第一科。和一般的宗教题材的戏剧作品不同，元杂剧的神仙道化剧并不劝人戒恶修善，也不普度众生。根本不遵守“混元五戒”的首戒“不得杀生”，而只度化原来就名列仙籍的下凡神仙或有“半仙”之分的俗子。《任风子》一剧可以认为是这一类作品的典型。\n全剧情节如下：任屠为孩儿满月宴请众屠；听众屠说道士马...", "authors": ["池", "吉"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec291c6e67846a9218b43", "shortContent": "周文质的杂剧作品除本剧外，尚有《春风杜韦娘》、《孙武子教女兵》、《敬新磨戏谏唐庄宗》等三种，均佚。本剧见赵景深辑《元人杂剧钩沉》，存〔越调〕一支，〔中吕宫〕〔双调〕各一套。剧本本事出于《史记》、《汉书》。叙汉武帝时苏武奉使匈奴被拘留，遣放北海（地为今苏联贝加尔湖一带）牧羊，前后达十九年，历尽艰难，威武不屈，始终坚持民族气节。至汉昭帝即位，匈汉和亲，汉求匈奴归还苏武，单于诡称已死。苏武借雁足传书汉帝...", "authors": ["徐顺平"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2b05e272d4b2254da4b", "shortContent": "本剧第二折有三曲〔滚绣球〕，这是其中的第三支。经过一番与郭华心照不宣的对话，王月英亲笔写下一首诗，命梅香送与郭华，约他元宵夜在相国寺观音殿中相会。岂料郭华竟然在约会之夜醉倒观音殿，她一直等到四更天才留下“表记”无限惆怅而归。此曲即写王月英见郭华醉卧不醒时无可奈何、“感叹伤怀”的心情。\n首句“且饶过王月英，待唤声郭秀才”，乍看似颇费解，把睡着的郭华叫醒也就罢了，为什么要先“饶过王月英”呢？王月英是怀...", "authors": ["李春祥", "李恒义"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f4169dbb8b379ee0af333", "shortContent": "终日擘桃穰，人在心儿里。两朵隔墙花，早晚成连理。自家因前晚泊舟湘潭，邂逅商女，整整看了半夜。昨日与他的船同行，争奈或前或后，又不得一处停泊。夜半坐卧不宁，今日喜得赶上。又喜他同伴那船分路去了，连那前日女伴，也不见在舵楼上。只见此女在水窗中，时窥半面，或露全躯。多应怀掷果之私[1]，定不学投梭之拒[2]。今晚恰好并船在洞庭湖畔，我的坐处正对着他们水窗。且待他开窗时节，饱看一回则个。（站开科）（旦上）...", "authors": ["董玉洪", "朱万曙"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f417434a8757d5a0fabb6", "shortContent": "这一对蝴蝶儿怎么飞得如此好，只管在奴家衣上扑来。为何的扑面\n看又回身介）\n呀，怎么又在裙儿上旋绕？欲去又飞还，将粉须儿钉住裙汊\n印儿。多只多粉腮边一点桃红绽，若为怜。倘把气儿呵着，他便飞下并香肩。\n夫妻一对，还是秦楼楚馆买笑追欢的？若是好人家，不该如此乔模乔样妆束；若是乍会的，又不该如此熟落。若不是燕燕于归[4]，怎便没分\n小姐，这画上郎君呵，\n我看这幅画，半假半真，有意无意，心中着实难解，且喜桌...", "authors": ["耿百鸣", "张", "溦"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f41847d0ac1145496c46a", "shortContent": "（小旦布衣上）\n爹在大名回来，说道因红丝姑夫作伐[2]，将我许聘钱唐顾家做妾，不日就要送去。（叹介）咳！奴家身同断梗，命比黄杨[3]，此事久已在我意中。却幸嫁得一个书生，终身有托。与为俗物之妻，宁作文人之妾。看他定情笺上，缠绵数语，料不是个薄倖儿郎。咳！姚梦兰，姚梦兰，这便是你安身立命的所在，休要等闲轻觑了也。我情一丝，今后呵，随着\n东风为定止。或者他秋来将我做齐纨视[4]，我也甘心为他憔悴\n死。...", "authors": ["艾立中"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f4185911759740c9cac1e", "shortContent": "为市隐，亦足幽栖。问皋桥之遗迹，良人雅慕伯鸾[4]；效举案之齐眉，贱妾能师孟女[5]。彼唱我随，式歌且舞，可谓极琴瑟之欢，遂于飞之愿矣[6]。但是记得别我道兄下山，自临安到此，经历多少风波，转瞬间不觉又是夏初天气，红尘中日子，真过得好疾也呵！（行介）\n（贴上）茶香飘紫笋[7]，花蔓缀金钿。呀，娘娘独自在此，官人有事，还没进来。青儿泡得绝好细茶，请娘娘先吃一盏儿。（旦）好。（坐饮介）（贴）娘娘，如此...", "authors": ["郭", "梅"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572706750, '5dbd2930f884af0073381093', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643559, '西厢记 · 第三本 · 第三折', NULL, 0, 41, 0, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[红上云]今日小姐着我寄书与张生，当面偌多般假意儿，原来诗内暗约着他来。小姐也不对我说，我也不瞧破他，则请他烧香。今夜晚妆处比每日较别，我看他到其间怎的瞒我？[红唤科]姐姐，咱烧香去来。[旦上云]花阴重叠香风细，庭院深沉淡月明。[红云]今夜月明风清，好一派景致也呵！
[双调][新水令]晚风寒峭透窗纱，控金钩绣帘不挂。门阑凝暮霭，楼角敛残霞。恰对菱花，楼上晚妆罢。
[驻马听]不近喧哗，嫩绿池溏藏睡鸭；自然幽雅，淡黄杨柳带栖鸦。金莲蹴损牡丹芽，玉簪抓住荼蘼架。夜凉苔径滑，露珠儿湿透了凌波袜。
我看那生和俺小姐巴不得到晚。
[乔牌儿]自从那日初时想月华，捱一刻似一夏；见柳梢斜日迟迟下，早道“好教贤圣打”。
[搅筝琶]打扮的身子儿诈，准备着云雨会巫峡。只为这燕侣莺俦，锁不住心猿意马。不则俺那姐姐害，那生呵！二三日来水米不粘牙。因姐姐闭月羞花，真假、这其间性儿难按纳，一地里胡拿。
姐姐这湖山下立地，我开了寺里角门儿。怕有人听俺说话，我且看一看。[做意了]偌早晚傻角却不来，赫赫赤赤，来。[末云]这其间正好去也，赫赫赤赤。[红云]那鸟来了。
[沉醉东风]我则道槐影风摇暮鸦，原来是玉人帽侧乌纱。一个潜身在曲槛边，一个背立在湖山下；那里叙寒温，并不曾打话。[红云]赫赫赤赤，那鸟来了。[末云]小姐，你来也。[搂住红科][红云]禽兽，是我，你看得好仔细着，若是夫人怎了。[末云]小生害得眼花，搂得慌了些儿，不知是谁，望乞恕罪！[红唱]便做道搂得慌呵，你好索觑咱，多管是饿得你个穷神眼花。
[末云]小姐在那里？[红云]在湖山下，我问你咱。真个着你来哩？[末云]小生猜诗谜社家，风流隋何，浪子陆贾，准定扢扎帮便倒地。[红云]你休从门里去，则道我使你来。你跳过这墙去，今夜这一弄助你两个成亲。我说与你，依着我者。
[乔牌儿]你看那淡云笼月华，似红纸护银蜡；柳丝花朵垂帘下，绿莎茵铺着绣榻。
[甜水令]良夜迢迢，闲庭寂静，花枝低亚。他是个女孩儿家，你索将性儿温存，话儿摩弄，意儿谦洽；休猜做败柳残花。
[折桂令]他是个娇滴滴美玉无瑕，粉脸生春，云鬓堆鸦。恁的般受怕担惊，又不图甚浪酒闲茶。则你那夹被儿时当奋发，指头儿告了消乏；打叠起嗟呀，毕罢了牵挂，收拾了忧愁，准备着撑达。
[末做跳墙搂旦科][旦云]是谁？[末云]是小生。[旦怒云]张生，你是何等之人！我在这里烧香，你无故至此；若夫人闻知，有何理说！[末云]呀，变了卦也！[红唱]
[锦上花]为甚媒人，心无惊怕；赤紧的夫妻每，意不争差。我这里蹑足潜踪，悄地听咱：一个羞惭，一个怒发。
[幺篇]张生无一言，呀，莺莺变了卦。一个悄悄冥冥，一个絮絮答答。却早禁住隋何，迸住陆贾，叉手躬身，妆聋做哑。
张生背地里嘴那里去了？向前搂住丢翻，告到官司，怕羞了你！
[清江引]没人处则会闲嗑牙，就里空奸诈。怎想湖山边，不记“西厢下”。香美娘处分破花木瓜。
[旦]红娘，有贼。[红云]是谁？[末云]是小生。[红云]张生，你来这里有甚么勾当？[旦云]扯到夫人那里去！[红云]到夫人那里，怕坏了他行止。我与姐姐处分他一场。张生，你过来跪着！你既读孔圣之书，必达周公之礼，夤夜来此何干？
[雁儿落]不是俺一家儿乔作衙，说几句衷肠话。我则道你文学海样深，谁知你色胆有天来大？
[红云]你知罪么？[末云]小生不知罪。[红唱]
[得胜令]谁着你夤夜入人家，非奸做贼拿。你本是个折桂客，做了偷花汉；不想去跳龙门，学骗马。姐姐，且看红娘面饶过这生者！[旦云]若不看红娘面，扯你到夫人那里去，看你有何面目见江东父老？起来！[红唱]谢小姐贤达，看我面遂情罢。若到官司详察，“你既是秀才，只合苦志于寒窗之下，谁教你夤夜辄入人家花园，做得个非奸即盗。”先生呵，准备精皮肤吃顿打。
[旦云]先生虽有活人之恩，恩则当报。既为兄妹，何生此心？万一夫人知之，先生何以自安？今后再勿如此，若更为之，与足下决无干休。[下][末朝鬼门道云]你着我来，却怎么有偌多说话！[红扳过末云]羞也，羞也，却不“风流隋何，浪子陆贾”？[末云]得罪波“社家”，今日便早则死心塌地。[红唱]
[离亭宴带歇指煞]再休题“春宵一刻千金阶”，准备着“寒窗更守十年寡”。猜诗谜的社家，拍了“迎风户半开”，山障了“隔墙花影动”，绿惨了“待月西厢下”。你将何郎粉面搽，他自把张敞眉儿画。强风情措大，晴干了尤云滞雨心，悔过了窃玉偷香胆，删抹了倚翠偎红话。[末云]小生再写一简，烦小娘子将去，以尽衷情如何？[红唱]淫词儿早则休，简帖儿从今罢。犹古自参不透风流调法。从今后悔罪也卓文君，你与我游学去波汉司马。[下]
[末云]你这小姐送了人也！此一念小生再不敢举，奈有病体日笃，将如之奈何？夜来得简方喜，今日强扶至此，又值这一场怨气，眼见得休也。只索回书房中纳闷去。桂子闲中落，槐花病里看。[下]', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2832e6a6b501f966de4", "shortContent": "《度柳翠》杂剧可说是元曲杂剧转入“案头文学化”的代表作之一。前篇介绍的第二折中〔黄钟尾〕一曲可以看出它尚文采和堆砌辞藻的趋向。剧中借月明和柳翠两个人名掉文袋、卖典故之处则比比皆是。这种类似游戏的笔墨过滥则近于无聊。例如反复颠倒地说“花与月添神”、“月与柳招魂”之类，实在没有什么意义。至于让柳翠唱两句柳永〔雨霖铃〕中的名句：“今宵酒醒何处，杨柳岸晓风残月”，再即时坐化飞升登大道等等，更显得有些轻薄。...", "authors": ["池吉"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2ab911759740c9bc582", "shortContent": "贾仲名是由元入明的杂剧作家，号云水散人，淄川（今山东淄博）人。据《录鬼簿续编》称：其“天性明敏，博究群书，善吟咏，尤精于乐章、隐语。尝侍文皇帝于燕邸，甚宠爱之，每有宴会应制之作，无不称赏”。“所作传奇、乐府极多，骈丽工巧，有非他人之所及者。一时侪辈，率多拱手敬服以事之。”并录其所作十四种杂剧之名。钟嗣成在写《录鬼簿》时，曾制《凌波仙》曲以吊前辈及同代曲家中若干已卒的知友，贾仲名读钟氏原著后，对其余...", "authors": ["邓乔彬"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572706823, '5dbd2983a3180b0068e71ae7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643560, '西厢记 · 第三本 · 第四折', NULL, 0, 41, 1, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[夫人上云]早间长老使人来，说张生病重。我着长老使人请个太医去看了。一壁道与红娘，看哥哥行问汤药去者，问太医下甚么药？证候如何？便来回话。[下][红上云]老夫人才说张生病沉重，咋晚吃我那一场气，越重了。莺莺呵，你送了他人。[下][旦上云]我写一简，则说道药方，着红娘将去与他，证候便可。[旦唤红科][红云]姐姐唤红娘怎么？[旦云]张生病重，我有一个好药方儿，与我将去咱！[红云]又来也！娘呵，休送了他人！[旦云]好姐姐，救人一命，将去咱！[红云]不是你，一世也救他不得。如今老夫人使我去哩，我就与你将去走一遭。[下][旦云]红娘去了，我绣房里等他回话。[下][末上云]自从昨夜花园中吃了这一场气，投着旧证候，眼见得休了也。老夫人说着长老唤太医来看我；我这颓证候，非是太医所治的；则除是那小姐美甘甘、香喷喷、凉渗渗、娇滴滴一点儿唾津儿咽下去，这鸟病便可。[洁引太医上，《双斗医》科范了][下][洁云]下了药了，我回夫人话去，少刻再来相望。[下][红上云]俺小姐送得人如此，又着我去动问，送药方儿去，越着他病沉了也。我索走一遭。异乡易得离愁病，妙药难医肠断人。
[越调][斗鹌鹑]则为你彩笔题诗，回文织锦；送得人卧枕着床，忘餐废寝；折倒得鬓似愁潘，腰如病沈。恨已深，病已沉，昨夜个热脸儿对面抢白，今日个冷句儿将人厮侵。
昨夜这般抢白他呵！
[紫花儿序]把似你休倚着栊门儿待月，依着韵脚儿联诗，侧着耳朵儿听琴。见了他撇假偌多话：“张生，我与你兄妹之礼，甚么勾当！”怒时节把一个书生来跌窨，欢时节“红娘，好姐姐，去望他一遭！”将一个侍妾来逼临。难禁，好着我似线脚儿般殷勤不离了针。从今后教他一任，这的是俺老夫人的不是：将人的义海恩山，都做了远水遥岑。
[红见末问云]哥哥病体若何？[末云]害杀小生也！我若是死呵，小娘子，阎王殿前，少不得你做个干连人。[红叹云]普天下害相思的不似你这个傻角。
[天沙净]心不存学海文林，梦不离柳影花阴，则去那窃玉偷香上用心。又不曾得甚，自从海棠开想到如今。因甚的便病得这般了？[末云]都因你行——怕说的谎——因小待长上来，当夜书房一气一个死。生救了人，反被害了。自古云：“痴心女子负心汉。”今日反其事了。[红唱]我这里自审，这病为邪淫；尸骨岩石鬼病侵。更做道秀才们从来恁，似这般干相思的好撒脱！功名上早则不遂心，婚姻上更返吟复吟。
[红云]老夫人着我来，看哥哥要甚么汤药。小姐再三伸敬，有一药方送来与先生。[末做慌科]在那里？[红云]用着几般儿生药，各有制度，我说与你：
[小桃红]“桂花”摇影夜深沉，酸醋“当归”浸。[末云]桂花性温，当归活血，怎生制度？[红唱]面靠着湖山背阴里窨，这方儿最难寻。一服两服令人恁。[末云]忌甚么物？[红唱]忌的是“知母”未寝，怕的是“红娘”撒沁。吃了呵，稳情取“使君子”一星儿“参”。
这药方儿小姐亲笔写的。[末看药方大笑科][末云]早知姐姐书来，只合远接。小娘子——[红云]又怎么？却早两遭也。[末云]——不知这首诗意，小姐待和小生“哩也波”哩。[红云]不少了一些儿？
[鬼三台]足下其实啉，休装（口吞）。笑你个风魔的翰林，无处问佳音，向简帖儿上计禀。得了个纸条儿恁般绵里针，若见玉天仙怎生软厮禁？俺那小姐忘恩，赤紧的偻人负心。
书上如何说？你读与我听咱。[末念云]“休将闲事苦萦怀，取次摧残天赋才。不意当时完妾命，岂防今日作君灾？仰图厚德难从礼，谨奉新诗可当谋。寄语高唐休咏赋，今宵端的雨云来。”此韵非前日之比，小姐必来。[红云]他来呵怎生？
[秃厮儿]身卧着一条布衾，头枕着三尺瑶琴；他来时怎生和你一处寝？冻得来战兢兢，说甚知音？
[圣药王]果若你有心，他有心，昨日秋千院宇深沉；花有阴，月有阴，“春宵一刻抵千金”，何须“诗对会家吟”？
[末云]小生有花银十两，有铺盖凭与小生一付。[红唱]
[东原乐]俺那鸳鸯枕，翡翠衾，便遂杀了人心，如何肯凭？至如你不脱解和衣儿更怕甚？不强如手执定指尖儿恁。倘或成亲，到大来福荫。
[末云]小生为小姐如此容色，莫不小姐为小生也减动丰韵么？[红唱]
[绵搭絮]他眉弯远山铺翠，眼横秋水无尘，体若凝酥，腰如嫩柳，俊的是庞儿俏的是心，体态温柔性格儿沉。虽不会法灸神针，更胜似救苦难观世音。
[末云]今夜成的事，小生不敢有忘。[红唱]
[幺篇]你口儿里漫沉吟，梦儿里苦追寻。往事已沉，只言目今，今夜相逢管教恁。不图你甚白壁黄金，则要你满头花，拖地锦。
[末云]怕夫人拘系，不能够出来。[红云]则怕小姐不肯，果有意呵，
[煞尾]虽然是老夫人晓夜将门禁，好共歹须教你称心。[末云]休似昨夜不肯。[红云]你挣揣咱，来时节肯不肯尽由他，见时节亲不亲在于您。[并下]
[络丝娘煞尾]因今宵传言送语，看明日携云握雨。', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec278c6e67846a9218af8", "shortContent": "以上所录六个曲牌叙王瑞兰拜月事，《拜月亭》剧名由此而得。王国维赞扬南戏《拜月》第三十二出“实为全书中之杰作”，指出它“大抵本于关剧第三折”（《宋元戏曲考》）。\n王瑞兰自从在离乱中巧遇秀才蒋世隆，到客店自主成亲。不幸被回朝的父亲撞见，恩爱夫妻就此“生扭散”，撇下个“染病的男儿”，自己被“横拖倒拽”带到汴梁新宅，从此幽居深闺。恹恹捱过残春，又是初夏困人时节。瑞兰随义妹瑞莲到园中闲行散闷，美景供愁，教人...", "authors": ["宋光祖"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec282dbb8b379ee09fce2", "shortContent": "张生乘夜逾墙赴莺莺之约会，结果讨了一场没趣，回房后就病倒了。莺莺得知此消息，亦心不自安，命红娘送书信与药方至张生处探望，实际上是重订幽会之期。张生读罢，判断此次莺莺不会爽约，肯定前来。红娘乃唱了这一曲〔圣药王〕。\n这里的“你”、“他”孰指张生，孰指莺莺，比较模糊。如对书信，药方而唱，“你”指莺莺，“他”指张生。如对张生而唱，“你”指张生，“他”指莺莺。然则张生之“有心”早已事实俱在，问题端在莺莺是...", "authors": ["蒋星煜"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec28f2e6a6b501f966e06", "shortContent": "在第二折写透了倩女的大胆追求之后，第三折，作者掉转笔锋，细致入微地铺写了生活在现实世界里的倩女之身的悲惨遭遇。她终日卧病在床，精神恍惚，备受煎熬：一会儿埋怨王生薄情，一会儿又梦见王生得官衣锦还乡，一会儿又是梦醒之后的倍觉凄清与惆怅。总之，对爱情的执著与担忧情人负心的恐惧交织扭结在一起，剪不断，理还乱，把封建社会丧失了婚姻自主权的少女的复杂心态，淋漓尽致地描绘了出来。这里所选的两支曲子，就是表现她这...", "authors": ["欧阳光"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2b0911759740c9bc591", "shortContent": "此剧当据宋人黄可道《王焕》戏文改编。元人刘一清《钱塘遗事》（卷六）记载：“至戊辰、己巳间，王焕戏文盛行于都下（按：指南宋都城临安，今杭州），始自太学，有黄可道者为之。一仓官诸妾见之，至于群奔，遂以言去。”戏文《王焕》剧本虽佚，现仅存佚曲二十二支，但《永乐大典》和徐渭《南词叙录》均有著录，分别题《风流王焕贺怜怜》、《贺怜怜烟花怨》。\n初看，此剧不过是公子哥儿的寻花问柳，是个风流烟花案，实则歌颂忠贞不...", "authors": ["吴", "戈"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f416ac6e67846a92276ac", "shortContent": "说话中间，早来到景阳冈下。行路饥渴。这里有个酒肆，酒望子上写着[6]：三碗不过冈。这怎么说？且进去少坐一回。酒保那里？（丑应上）酒，酒，酒。有，有，有。赊，赊，赊。走，走，走。客官，里面请坐。（生）且问你，怎么唤做“三碗不过冈”？（丑）客官，俺这里造得好酒。人若吃了三碗，就醉倒了，上这景阳冈不得。因此唤做“三碗不过冈”。（生笑科）待俺吃上十来碗，看过得冈过不得冈。（丑斟酒科）我这里只有一样牛肉，只...", "authors": ["王", "平", "朱万曙"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f41755e272d4b2255c98e", "shortContent": "好笑我车静芳，受人雇倩，代作会文，好不担着干系！只恐怕考得低了，不像体面。闻得哥哥去听发落，怎还不见回来？（丑袖卷上）济人须济急，为人须为彻。（连揖介）妹子多谢！（旦）考在那里？（丑）侥幸第二。（旦）也不见得高，有何可谢？（丑）妹子说那里话！若照你哥哥本领，莫说第二，就是六等也还没得考哩。方才发落的时节，何等光彩！\n么“一朵绿云”，那沈翰林古怪，就说倒像女人口气，几乎露出马脚来。那主司贼眼连忙问，...", "authors": ["包郑虹", "翁敏华"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f41835e272d4b2255c9e0", "shortContent": "不知那里说起！甚么山东巡抚公子，道俺貌美，顿起邪心，串同地棍都来德，诈为媒妁，捏告原聘在先；贪官枉法，竟欲将奴断归胡姓。父亲一时言词激烈，反触其怒，益难挽回。今早又往府中击鼓鸣冤去了，不知可能济事？好忧闷人也！\n好一个明明白白清平界！（作急叩门）（旦开见介）爹爹愁容满面，想是又不济事了。（末）不要说起，那府官呵，更糊涂不开，更糊涂不\n开，趋势更贪财，一样将情卖。（旦）怎么批词？（末）批甚么词！那\n...", "authors": ["吉明周"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f41860ce818559d071ad6", "shortContent": "（丑扮家童，提灯引小生便衣上）\n季毓英，典试福州，论文锁院[4]，虽说所取之士，俱是真才，苦的半月闱中，不遑昕夕[5]。放榜之后，即行入赘完姻，贰室馆甥，非常热闹，只因使旋复命，程限綦严，不敢久延。过了三朝[6]，移家舟次。今乃九月十五，正是生辰，恰值二十年头，俗称整寿。岳父以次，下至门生，无不制锦称觞，登舟作贺，下官只推卧病，伏在船舱。来往纷纷，自朝至暮。今夜月明如昼，照透篷窗。新夫人不在船中，...", "authors": ["王永宽"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572706921, '5dbd29e56e9ba1006d61ce14', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643561, '西厢记 · 第四本 · 楔子', NULL, 0, 41, 0, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[旦上云]昨夜红娘传简去与张生，约今夕和他相见，等红娘来做个商量。[红上云]姐姐着我传简帖儿与张生，约他今宵赴约。俺那小姐，我怕又有说谎，送了他性命，不是耍处。我见小姐去，看他说甚么。[旦云]红娘收拾卧房，我睡去。[红云]不争你要睡呵，那里发付那生？[旦云]甚么那生？[红云]姐姐，你又来也！送了人性命不是耍处。你若又翻悔，我出首与夫人，你着我将简帖儿约下他来。[旦云]这小贱人倒会放刁，羞人答答的，怎生去！[红云]有甚的羞，到那里只合着眼者。[红催莺云]去来去来，老夫人睡了也。[旦走科][红云]俺姐姐语言虽是强，脚步儿早先行也。
[仙吕][端正好]因姐姐玉精神，花模样，无倒断晓夜思量。着一片志诚心盖抹了漫天谎。出画阁，向书房；离楚岫，赴高唐；学窃玉，试偷香；巫娥女，楚襄王；楚襄王敢先在阳台上。[下]', '', '', '', '[{"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f41670f8fda556506ebd6", "shortContent": "家看酒来。（贴）先看茶后沽酒。\n不得吃了他下去，今日又做这般张志[6]。（旦）昨来邂逅，柳下停骖，\n小生就是昨日遗鞭者。（贴）相公贵处？（生）荥阳郡，是故丘[7]。（贴）上姓？（生）郑元和忝为儒者流。（贴）令尊在么？（生）老父治常州。（贴）原来是公子。令堂在么？（生）高堂有慈母。（贴）父母既在，不该远游。（生）非干远游。（贴）既非远游，到此贵干？（生）应\n何？（生）多谢。（合）重进酒，饮到月转花梢...", "authors": ["虞卓娅"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f417503572034f65b6523", "shortContent": "旦介）（旦）阿呀！秀才，你既读孔圣之书，必达周公之礼，岂可一毫有玷于行。况百年夫妇，情意久长，岂可以一宵苟合，而遗臭万年？决不可如此！（付）何妨呀，（唱）他操持贞与节，使我好羞惭，我此来差了，\n“碧天霞落，长空云敛”，夜深了，天空中皎洁的明月轻洒它的温柔，月到中秋分外圆啊！微凉的风拂过，露水打湿栏杆，深夜的花园如此宁静。而此时疾步走在长满青苔的小径上的深闺少女史碧桃，她的心却又是如此的紧张而慌乱：...", "authors": ["吴春彦"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f417c911759740c9cabf2", "shortContent": "（旦上）（小旦随上）\n奴家陈素素，偶以小词题墓，漏泄小名。承吕郎谬加赞赏，无限钟情。前日一见，使我惊喜相半，寥寥数语，遂已铭感终身。他约定三日之后，准到我家相访。今日刚刚十九，至诚君子，必不爽信。只得扶病起来，打点凝妆以待。绣烟，你可安排奁具，整顿衣饰，伏侍我梳裹则个。（小旦）呀，姐姐，你连日身子不快，茶饭也懒进，今日侵早起来，就要梳妆打扮，可不太劳碌了？（旦）丫鬟，你那里知道我的心事来！\n得今日...", "authors": ["王永宽"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572706976, '5dbd2a1d17b54d006c7b50d9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643562, '西厢记 · 第四本 · 第一折', NULL, 0, 41, 0, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[末上云]昨红娘所遗之简，约小生今夜成就。这早晚初更尽也，不见来呵，小姐休说谎咱！人间良夜静复静，天上美人来不来？
[仙吕][点绛唇]伫立闲阶，夜深香霭、横金界。潇洒书斋，闷杀读书客。
[混江龙]彩云何在，月明如月浸楼台。僧归禅室，鸦噪庭槐。风弄竹声，则道金佩响；月移花影，疑是玉人来。意悬悬业眼，急攘攘情怀，身心一片，无处安排；则索呆答孩倚定门儿待。越越的表鸾信杳，黄犬音乖。
小生一日十二时，无一刻放下小姐，你那里知道呵！
[油葫芦]情思昏昏眼倦开，单枕侧，梦魂飞入楚阳台。早知道无明夜因他害，想当初“不如不遇倾城色”。人有过，必自责，勿惮改。我却待“贤贤易色”将心戒，怎禁他兜的上心来。
[天下乐]我则索倚定门儿手托腮，好着我难猜：来也那不来？夫人行料应难离侧。望得人眼欲穿，想得人心越窄，多管是冤家不自在。
喏早晚不来，莫不又是谎么？
[那吒令]他若是肯来，早身离贵宅；他若是到来，便春生敝斋；他若是不来，似石沉大海。数着人脚步儿行，倚定窗囗儿待，寄语多才：
[鹊踏枝]恁的般恶抢白，并不曾记心怀；拨得个意转心回，夜去明来。空调眼色经今半载，这其间委实难捱。
小姐这一遭若不来呵，
[寄生草]安排着害，准备着抬。想着这异乡身强把茶汤捱，则为这可憎才熬得心肠耐，办一片志诚心留得形骸在。试着那司天台打算半年愁，端的是太平车约有十余载。
[红上云]姐姐，我过去，你在这里。[红敲门科][末问云]是谁？[红云]是你前世的娘。[末云]小姐来么？[红云]你接了衾枕者，小姐入来也。张生，你怎么谢我？[末拜云]小生一言难尽，寸心相报，惟天可表！[红云]你放轻者，休唬了他！[红推旦入云]姐姐，你入去，我在门儿外等你。[末见旦跪云]张珙有何德能，敢劳神仙下降，知他是睡里梦里？
[村里迓鼓]猛见他可憎模样，小生那里病来，早医可九分不快。先前见责，谁承望今宵欢爱！着小姐这般用心，不才张珙，合当跪拜。小生无宋玉般容，潘安般貌，子建般才；姐姐，你则是可怜见为人在客！
[元和令]绣鞋儿刚半拆，柳腰儿够一搦，羞答答不肯把头抬，只将鸳枕捱。云鬟仿佛坠金钗，偏宜鬏髻儿歪。
[上马娇]我将这钮扣儿松，把缕带儿解；兰麝散幽斋。不良会把人禁害，咍，怎不肯回过脸儿来？[胜葫芦]我这里软玉温香抱满怀。呀，阮肇到天台，春至人间花弄色。将柳腰款摆，花心轻拆，露滴牡丹开。
[幺篇]但蘸着些麻儿上来，鱼水得和谐，嫩蕊娇香蝶恣采。半推半就，又惊又爱，檀口搵香腮。
[末跪云]谢小姐不弃，张珙今夕得就枕席，异日犬马之报。[旦云]妾千金之躯，一旦弃之。此身皆托于足下，勿以他日见弃，使妾有白头之叹。[末云]小生焉敢如此？[末看手帕科]
[后庭花]春罗原莹白，早见红香点嫩色。[旦云]羞人答答的看甚么？[末]灯下偷睛觑，胸前着肉揣。畅厅哉，浑身通泰，不知春从何处来？无能的张秀才，孤身西洛客，自从逢稔色，思量的不下怀；忧愁因间隔，相思无摆划；谢芳卿不见责。
[柳叶儿]我将你做心肝儿般看待，点污了小姐清白。忘餐废寝舒心害，若不是真心耐，志诚捱，怎能够这相思苦尽甘来？
[青哥儿]成就了今宵欢爱，魂飞在九霄云外。投至得见你多情小奶奶，憔悴形骸，瘦似麻秸。今夜和谐，犹自疑猜。露滴香埃，风静闲阶，月射书斋，云锁阳台；审问明白，只疑是昨夜梦中来，愁无奈。
[旦云]我回去也，怕夫人觉来寻我。[末云]我送小姐出来。
[寄生草]多丰韵，忒稔色。乍时相见教人害，霎时不见教人怪，些儿得见教人爱。今宵同会碧纱厨，何时重解香罗带。
[红云]来拜你娘！张生，你喜也。姐姐，咱家去来。[末唱]
[煞尾]春意透酥胸，春色横眉黛，贱却人间玉帛。杏脸桃腮，乘着月色，娇滴滴琥显得红白。下香阶，懒步苍苔，动人处弓鞋凤头窄。叹鲰生不才，谢多娇错爱。若小姐不弃小生，此情一心者，你是必破工夫明夜早些来。[下]', '', '', '', '[{"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f4167d635634aee3f7c3e", "shortContent": "书当快意读易尽，客有可人期不来。小姐着红娘送来的缄帖儿，约今晚成事。这时候不见来，莫非又是说谎了？正是：人间良夜静不静，天上美人来不来？\n小生一日十二个时辰，无一刻放下小姐。你那里知道呵！\n惊了小姐，且接了衾枕进去。（生）是，不敢。（贴）张先生如何谢我？（生）小生一言难尽，惟天可表，当以犬马报之。（生见旦跪接介）张珙有何德能，敢劳神仙下降。（旦）请起来。\n手儿竟自去了。更不管红娘在门儿外待，教我无...", "authors": ["周锡山"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f416fc6e67846a92276c6", "shortContent": "待久不来，昨晚不曾睡得，不觉睡魔蚤到，且睡些咱。（作睡介）（杂扮差人上）瑞麟香暖玉芙蓉[6]，画蜡凝晖彻夜红。信道使君情意重[7]，卷帘迟客月明中[8]。小人雍丘县差人，钱爷差请赵相公看月。此间已是寓所，书房门蚤闭，不免低低唤声。赵相公，赵相公！（生惊醒）呀，小姐来了！（急出开门抱杂）小姐，小姐，想得赵汝州苦也！（杂）赵相公，小人是本县差人，不是什么小姐。（生看笑）偶然睡去，魂梦颠倒。你是谁差来的...", "authors": ["黄竹三"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f4183dbb8b379ee0af3a8", "shortContent": "（末上）主人甘隐遁，院子也清闲。自家文府中老院子是也。俺老爷吴门访婿未回，今已清明，小姐要往夫人坟上祭扫，着俺备了祭礼同来。车夫们，快些走动。（旦、贴乘车）（杂挑酒果同行上）\n（末）已到坟前，请小姐拜奠。（车夫下）（旦哭拜介）我那亲娘！\n（末叩头）（贴跪哭介）夫人那夫人，你在生时节，与小姐寸步不离，止愿他招一个好姐夫。谁知你一去呵，\n（末）安童收过祭礼[4]。（杂彻酒果下）（旦哭贴劝介）小姐休要过...", "authors": ["庞坚"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f4185d635634aee3f7cca", "shortContent": "（丑摇船随生上）\n性，似游丝空际悠扬。我许宣。今日清明佳节，往爹娘坟上，祭扫而归。你看湖光似镜，车马如云，好不可爱！为此唤小艇，慢慢地一路游玩回去。（丑摇船唱杭州歌）（诨介）（生）看雕鞍骏马，会王孙贵戚\n多欢畅。倒金樽沉醉花前，听笙歌十里画塘。（下）（贴随旦上）\n（贴）娘娘看脚下。\n游人，尽是凡夫俗子，只有方才祭扫坟墓的那生，风流俊雅，道骨非凡，若得相遂奇缘，不枉奴家来此。（贴）娘娘，看他独坐在舟...", "authors": ["郭", "梅"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572707019, '5dbd2a48c05a8000684d31b3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643563, '西厢记 · 第四本 · 第二折', NULL, 0, 41, 4, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[夫人引俫上云]这几日窃见莺莺语言恍惚，神思加倍，腰肢体态，比向日不同；莫不做下来了么？[俫云]前日晚夕，奶奶睡了，我见姐姐和红娘烧香，半晌不回来，我家去睡了。[夫人云]这桩事都在红娘身上，唤红娘来！[俫唤红科][红云]哥哥唤我怎么？[俫云]奶奶知道你和姐姐去花园里去，如今要打你哩。[红云]呀！小姐，你带累我也！小哥哥，你先去，我便来也。[红唤旦科]姐姐，事发了也，老夫人唤我哩，却怎了？[旦云]好姐姐，遮盖咱！[红云]娘呵，你做的隐秀者，我道你做下来也。[旦念]月圆便有阴云蔽，花发须教急雨催。[红唱]
[越调][斗鹌鹑]则着你夜去明来，倒有个天长地久；不争你握雨携云，常使我提心在口。你则合带月披星，谁着你停眠整宿？老夫人心数多，情性□□使不着我巧语花言，将没做有。
[紫花儿序]老夫人猜那穷酸做了新婿，小姐做了娇妻，这小贱人做了牵头。俺小姐这些时春山低翠，秋水凝眸，别样的都休，试把你裙带儿拴，纽门儿扣，比着你旧时肥瘦，出落得精神，别样的风流。
[旦云]红娘，你到那里小心回话者！[红云]我到夫人处，必问：“这小贱人，
[金蕉叶]我着你但去处行监坐守，谁着你迤逗的胡行乱走？”若问着此一节呵如何诉休？你便索与他个“知情”的犯由。
姐姐，你受责理当，我图甚么来？
[调笑令]你绣帏里效绸缪，倒凤颠鸾百事有。我在窗儿外几曾轻咳嗽，立苍苔将绣鞋儿冰透。今日个嫩皮肤倒将粗棍抽，姐姐呵，俺这通殷勤的着甚来由？
姐姐在这里等着，我过去。说过呵，休欢喜，说不过，休烦恼。[红见夫人科][夫人云]小贱人，为甚么不跪下！你知罪么？[红跪云]红娘不知罪。[夫人云]你故自口强哩。若实说呵，饶你；若不实说呵，我直打死你这个贱人！谁着你和小姐花园里去来？[红云]不曾去，谁见来？[夫人云]欢郎见你去来，尚故自推哩。[打科][红云]夫人休闪了手，且息怒停嗔，听红娘说。
[鬼三台]夜坐时停了针绣，共姐姐闲穷究，说张生哥哥病久。咱两个背着夫人，向书房问候。[夫人云]问候呵，他说甚么？[红云]他说来，道“老夫人事已休，将恩变为仇，着小生半途喜变做忧”。他道：“红娘你且先行，教小姐权时落后。”
[夫人云]他是个子孩儿家，着他落后怎么！[红唱]
[秃厮儿]我则道神针法灸，谁承望燕侣莺俦。他两个经今月余则是一处宿，何须你一一问缘由？
[圣药王]他每不识忧，不识愁，一双心意两下投。夫人得好休，便好休，这其间何必苦追求？常言道“女大不中留”。
[夫人云]这端事都是你个贱人。[红云]非是张生小姐红娘之罪，乃夫人之过也。[夫人云]这贱人倒指下我来，怎么是我之过？[红云]信者人之根本，“人而无信，不知其可也。大车无囗，小车无杌，其何以行之哉？”当日军围普救，夫人所许退军者，以女妻之。张生非慕小姐颜色，岂肯区区建退军之策？兵退身安，夫人悔却前言，岂得不为失信乎？既然不肯成就其事，只合酬之以金帛，令张生舍此而去。却不当留请张生于书院，使怨女旷夫，各相早晚窥视，所以夫人有此一端。目下老夫人若不息其事，一来辱没相国家谱；二来张生日后名重天下，施恩于人，忍令反受其辱哉？使至官司，老夫人亦得治家不严之罪。官司若推其详，亦知老夫人背义而忘恩，岂得为贤哉？红娘不敢自专，乞望夫人台鉴：莫若恕其小过，成就大事，挼之以去其污，岂不为长便乎？
[麻郎儿]秀才是文章魁首，姐姐是仕女班头；一个通彻三教九流，一个晓尽描鸾刺绣。
[幺篇]世有、便休、罢手，大恩人怎做敌头？起白马将军故友，斩飞虎叛贼草寇。
[络丝娘]不争和张解元参商卯酉，便是与崔相国出乖弄丑。到底干连着自己骨肉，夫人索穷究。
[夫人云]这小贱人也道得是。我不合养了这个不肖之女。待经官呵，玷辱家门。罢罢！俺家无犯法之男，再婚之女，与了这厮罢。红娘唤那贱人来！[红见旦云]且喜姐姐，那棍子则是滴溜溜在我身上，吃我直说过了。我也怕不得许多，夫人如今唤你来，待成合亲事。[旦云]羞人答答的，怎么见夫人？[红云]娘根前有甚么羞？
[小桃红]当日个月明才上柳梢头，却早人约黄昏后。羞得我脑背后将牙儿衬着衫儿袖。猛凝眸，看时节则见鞋底尖儿瘦。一个恣情的不休，一个哑声儿厮耨。呸！那其间可怎生不害半星儿羞？
[旦见夫人科][夫人云]莺莺，我怎生抬举你来，今日做这等的勾当；则是我的孽障，待怨谁的是！我待经官来，辱没了你父亲，这等不是俺相国人家的勾当。罢罢罢！谁似俺养女的不长进！红娘，书房里唤将那禽兽来！[红唤末科][末云]小娘子唤小生做甚么？[红云]你的事发了也，如今夫人唤你来，将小姐配与你哩。小姐先招了也，你过去。[末云]小生徨恐，如何见老夫人？当初在谁在老夫人行说来？[红云]休佯小心，过去便了。
[幺篇]既然漏怎干休？是我相投首。俺家里陪酒陪茶倒挼就。你休愁，何须约定通媒媾？我弃了部署不收，你原来“苗而不秀”。呸！你是个银样镴枪头。
[末见夫人科][夫人云]好秀才呵，岂不闻“非先王之德行不敢行”。我待送你去官司里去来，恐辱没俺家谱。我如今将莺莺与你为妻，则是俺三辈儿不招白衣女媚，你明日便上朝取应去。我与你养着媳妇，得官呵，来见我；驳落呵，休来见我。[红云]张生早则喜也。
[东原乐]相思事，一笔勾，早则展放从前眉儿皱，美爱幽欢恰动头。既能够，张生，你觑兀的般可喜娘庞儿也要人消受。
[夫人云]明日收拾行装，安排果酒，请长老一同送张生到十里长亭去。[旦念]寄语西河堤畔柳，安排青眼送行人。[同夫人下][红唱]
[收尾]来时节画堂箫鼓鸣春昼，列着一对儿鸾交凤友。那其间才受你说媒红，方吃你谢亲酒。[并下]', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2820ce818559d0635f6", "shortContent": "红娘在《西厢记》里起的作用，一是在崔莺莺和张生之间传书寄简，帮助这两个有情人自愿结合；二是挺身而出，回击老夫人和郑恒对崔、张美满婚姻的破坏。前者从二本二折到四本一折共七场戏；后者集中表现在四本二折，即后来被称作“拷红”的一场戏。这场戏写得尤其成功。\n“拷红”这场戏分三大段演进。第一大段演崔张私自结合被老夫人识破，要找红娘来拷问，红娘与莺莺商量对付的办法。包括〔斗鹌鹑〕〔紫花儿序〕〔金蕉叶〕〔调笑令...", "authors": ["王季思林建"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f4169911759740c9caba4", "shortContent": "奴家丈夫问成绞罪，秋后就要处决。昨日分付我，改嫁叶长官。（悲介）好苦！丈夫，我与你十年夫妇，尚不知我心事？我若有改嫁之心，怎见得害了你的性命！可怜古人从其治命，不从其乱命。他只因刑期将近，神思昏愦，以致言语舛错，故此奴家吞悲含怨，不与深辨罢了。为今之计，丈夫罪既该死，奴家先求个自尽，表我心事，使丈夫九泉之下亦得瞑目。只是我孩儿在怀，没有下落。意欲寻个好善人家，过继与他为子，一则全他性命，二则延王门...", "authors": ["史良昭"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f416bc6e67846a92276b3", "shortContent": "拿拿介）（生）不住的，叫拿拿。敢是地方走了贼，反了狱？既不呵，怎的响刀枪人哄马？（众扮官校持枪索上）（叫众军围住介）（贴、老旦惊走）\n甚么人？（刽）是伏事老爷的刽子手。（生怕介）吓煞俺也，看了他捧刀尖势不佳。（刽）有个一字旗儿，禀老爷插上。（生看介）是个甚么字？（众）是个“斩”字。（生）恭谢天恩了。卢生只道是千刀万剐，却只赐一个“斩”字儿，领戴，领戴。（下锣下鼓插旗介）（生）蓬席之下，酒筵为何而设...", "authors": ["李", "晓"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572707060, '5dbd2a71eaa375006c490c7c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643564, '西厢记 · 第四本 · 第三折', NULL, 23, 41, 15, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '〔正宫·端正好〕碧云天，黄花地，西风紧，北雁南飞。晓来谁染霜林醉？总是离人泪。
〔滚绣球〕恨相见得迟，怨归去得疾。柳丝长玉骢难系，恨不倩疏林挂住斜晖。马儿迍迍的行，车儿快快的随，却告了相思回避，破题儿又早别离。听得道一声“去也”，松了金钏；遥望见十里长亭，减了玉肌。此恨谁知！
〔叨叨令〕见安排着车儿、马儿，不由人熬熬煎煎的气；有甚么心情花儿、靥儿，打扮得娇娇滴滴的媚；准备着被儿、枕儿，只索昏昏沉沉的睡；从今后衫儿、袖儿，都揾做重重叠叠的泪。兀的不闷杀人也么哥！兀的不闷杀人也么哥！久已后书儿、信儿，索与我凄凄惶惶的寄。
〔脱布衫〕下西风黄叶纷飞，染寒烟衰草萋迷。酒席上斜签着坐的，蹙愁眉死临侵地。
〔小梁州〕我见他阁泪汪汪不敢垂，恐怕人知。猛然见了把头低，长吁气，推整素罗衣。
〔幺篇〕虽然久后成佳配，奈时间怎不悲啼。意似痴，心如醉，昨宵今日，清减了小腰围。
〔上小楼〕合欢未已，离愁相继。想着俺前暮私情，昨夜成亲，今日别离。我谂知这几日相思滋味，却原来比别离情更增十倍。
〔幺篇〕年少呵轻远别，情薄呵易弃掷。全不想腿儿相挨，脸儿相偎，手儿相携。你与俺崔相国做女婿，妻荣夫贵。但得一个并头莲，煞强如状元及第。
〔满庭芳〕供食太急，须臾对面，顷刻别离。若不是酒席间子母每当回避，有心待与他举案齐眉。虽然是厮守得一时半刻，也合着俺夫妻每共桌而食。眼底空留意，寻思起就里，险化做望夫石。
〔快活三〕将来的酒共食，尝着似土和泥。假若便是土和泥，也有些土气息，泥滋味。
〔朝天子〕暖溶溶玉醅，白泠泠似水，多半是相思泪。眼面前茶饭怕不待要吃，恨塞满愁肠胃。蜗角虚名，蝇头微利，拆鸳鸯在两下里。一个这壁，一个那壁，一递一声长吁气。
〔四边静〕霎时间杯盘狼籍，车儿投东，马儿向西，两意徘徊，落日山横翠。知他今宵宿在那里？有梦也难寻觅。
〔耍孩儿〕淋漓襟袖啼红泪，比司马青衫更湿。伯劳东去燕西飞，未登程先问归期。虽然眼底人千里，且尽生前酒一杯。未饮心先醉，眼中流血，心里成灰。
〔五煞〕到京师服水土，趁程途节饮食，顺时自保揣身体。荒村雨露宜眠早，野店风霜要起迟！鞍马秋风里，最难调护，最要扶持。
〔四煞〕这忧愁诉与谁？相思只自知，老天不管人憔悴。泪添九曲黄河溢，恨压三峰华岳低。到晚来闷把西楼倚，见了些夕阳古道，衰柳长堤。
〔三煞〕笑吟吟一处来，哭啼啼独自归。归家若到罗帏里，昨宵个绣衾香暖留春住，今夜个翠被生寒有梦知。留恋你别无意，见据鞍上马，阁不住泪眼愁眉。
〔二煞〕你休忧文齐福不齐，我则怕你停妻再娶妻。休要一春鱼雁无消息！我这里青鸾有信频须寄，你却休“金榜无名誓不归”。此一节君须记，若见了那异乡花草，再休似此处栖迟。
〔一煞〕青山隔送行，疏林不做美，淡烟暮霭相遮蔽。夕阳古道无人语，禾黍秋风听马嘶。我为甚么懒上车儿内，来时甚急，去后何迟？
〔收尾〕四围山色中，一鞭残照里。遍人间烦恼填胸臆，量这些大小车儿如何载得起！', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec282d635634aee3e9542", "shortContent": "通常被称作“长亭送别”的第四本第三折，是王实甫《西厢记》中最为脍炙人口的精彩片断之一。在第四本第一折“酬简”和第二折“拷红”中，莺莺终于克服了身心解放的要求与封建精神桎梏的矛盾，迈出了同张生私下结为夫妻的决定性一步。这种出于男女双方真诚相爱的自主选择，使封建礼教的维护者老夫人十分震怒，因此她拷问红娘严加追究。但红娘抓住了老夫人理亏的要害，非但拒不认罪，反而条分缕析，历数老夫人过错，使她不得不承认既...", "authors": ["高建中"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2ad2cee9a0c24ed9a07", "shortContent": "这首散曲由〔快活三〕带过〔朝天子〕〔四换头〕，共联结三个曲牌而成，以篇幅说，已相当于词中的慢调了。以结构说，正相当于诗的分三章，三章依次层层展开。〔快活三〕部分先出现人物：黄昏惹愁时分的闺中思妇。〔朝天子〕部分进一步刻画思妇的对景伤怀，离愁无限。〔四换头〕部分更深一层：思妇情知聚会无望，也希望有个音讯，于是叮嘱长空的飞雁传书。曲折写来，描画出了思妇的一片痴情。\n散曲中描写女子相思之苦的，大抵不外两...", "authors": ["何满子"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f416d2e6a6b501f975398", "shortContent": "见妾心。（相哭科）（合）销魂处江烟陇雾，都撮四眉头。\n陈与郊作《鹦鹉洲》传奇共三十六出。故事梗概是：唐代京兆万年人韦皋，乃诸葛亮之再生，族望巍巍，声名耿耿，有经天纬地之才，气薄云天之志，无奈国家州郡有藩镇作乱，京都则宦官当权，人心浮动，国势阽危，虽被授予参军，然思以自保，懒于就职。偶往楚中探望家存三朝簪笏、父为节使的友人姜荆宝。途中遇见前去拜访名诗人元稹的名妓薛涛，赠以玉指环一对。韦皋宿寺庙时，又...", "authors": ["程华平"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f41700f8fda556506ec05", "shortContent": "儿现统兵在河北，见时千万教他戮力王室，切勿以老身为念。论事亲\n域，何必顾恋乡闾。岂可藏居乡井。（合前）\n军士，你可去河边等候。待我告别老夫人就来了。（末、丑）领钧旨。正是：战士离家心独苦，将军赴镇势偏雄。（下）（生）母亲有何指教？（老旦）孩儿近前来，我分付你：\n母亲，岳母，此间就是河边了，就此告别。（老旦）孩儿，为官虽是好事，只是母子之情，一时间舍不得你就去。\n去罢。（老旦）孩儿且慢，你去端的几时...", "authors": ["鄢化志"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f417a5e272d4b2255c9af", "shortContent": "贫道青牛观中观主赵景清是也。年过半百，道行清严，一院住持，四方钦敬。所有匡胤侄儿，避难暂寓本观，不意卧病两月余矣。今喜痊可，常欲出外行走。咳，他是管闲是非的班头[2]，惹事端的太岁，贫道屡屡禁止，劝他住在房中。如今要往前村走走，不免叫老道出来，分付一番。老道那里？（丑上）老道今年八十九，背曲腰驼行路抖[3]。齿落牙尽头发光，嘴上白须像扫帚。师父叫我何干？（外）我要出去门徒人家走走，徒弟徒孙又不在家...", "authors": ["陈", "多"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f417c34a8757d5a0fabdd", "shortContent": "〔忆秦娥〕秋寂寂，碧纱窗外人横笛。人横笛，天津桥上[1]，旧曾听得。尘埋玉脸无人识，天空万籁声初息。声初息，月明江上，数峰凝碧。奴家裴玉娥，乃裴员外之女，粗知文墨，颇善弹筝。泛宅浮家，虽有看不尽的景致；孤身只影，竟无称得意的姻盟。芦叶汀舟，怕听咿呀孤雁；蓼花溪畔，愁闻凄楚啼鹃。呀，今夜月白风清，水天一色，不免取筝一弹，少展闷怀。（整筝介）\n小生黄损，对此佳景，未能假寐，不免推起篷窗，望月一回，有何...", "authors": ["许金榜"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f41832cee9a0c24ee8226", "shortContent": "（净扮知县）（吏役、门子随上）\n（白）下官昆山县知县刘清是也。前日准得蔡朱氏告他父亲谋杀丈夫一状。我想世间那有亲丈人谋害女婿之理？况看那朱茂卿，却不像个凶恶之徒。也没有个亲女儿忍告亲老子的道理，细看那朱氏，却又是个聪明伶俐的女子。这件事看来倒有些磨嘴。下官看他原被告父女的情形，还是在朱氏身上研磨追究，或者寻得个头绪出来，也不可知。他就是个哭主尸亲，也说不得要难为他些了。（老旦上）（喊冤介）青天爷爷...", "authors": ["宋光祖"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f418703048e64fbdaa082", "shortContent": "（众拥旦上）（旦唱引）\n（白）俺秋竞雄，虽属女儿之身，夙坚殉国之志。今缘皖案，无辜被拘。人皆争惜其蒙冤，己独不祈其幸免。死生祸福，一听当途便\n了。（唱）\n绍兴府知府、末扮山阴县知县）（从人喝道上）（杂扮吏役四人持刑具罗列介）（净升堂正坐末旁坐介）（众拥旦上）\n（禀介）禀大人，女匪秋瑾已经拿到，候大人发落。（净）带上来。（众）吓！（押旦带锁上）（跪介）（净看审问介）你就是秋瑾么？现在有人告发你和徐某...", "authors": ["郭", "梅"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f41862cee9a0c24ee8233", "shortContent": "（贴、小旦引旦宫装上）\n（坐介）流苏宝帐郁金香，铜漏声中罢晓妆。昨夜五更寒透梦，一庭红雨饯东皇。我坤兴公主，名唤微娖，年方三五，当今皇帝之长女，国母周皇后所产也。圣善承休，皇枝托体。陪禊期之祓水[2]，助茧馆以条桑[3]。翠沼鸳鸯，待订氤氲之牒[4]；上林桃李，早分雨露之华。只是运值坎坷，生逢患难。干戈四起，焰逼神京；鼙鼓一鸣，声闻内阙。将相失职，儿女担忧。梅未子而先酸，楝初花而已苦。时事如此，将...", "authors": ["胡雪冈"], "pressName": "上海辞书出版社"}, {"bookId": "62de2d8a3bba5677642ac2d1", "bookTitle": "元曲三百首", "articleId": "630593d2eebf5e0fdea511e5", "shortContent": "通常被称作“长亭送别”的第四本第三折，是王实甫《西厢记》中最为脍炙人口的精彩片断之一。在第四本第一折“酬简”和第二折“拷红”中，莺莺终于克服了身心解放的要求与封建精神桎梏的矛盾，迈出了同张生私下结为夫妻的决定性一步。这种出于男女双方真诚相爱的自主选择，使封建礼教的维护者老夫人十分震怒，因此她拷问红娘严加追究。但红娘抓住了老夫人理亏的要害，非但拒不认罪，反而条分缕析，历数老夫人过错，使她不得不承认既...", "authors": ["高建中"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572707106, '5dbd2a9ec05a8000684d35f0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643565, '西厢记 · 第四本 · 第四折', NULL, 2, 41, 0, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[末引仆骑马上开]离了蒲东早三十里也。兀的前面是草桥，店里宿一宵，明日赶早行。这马百般儿不肯走。行色一鞭催去马，羁愁万斛引新诗。
[双调][新水令]望蒲东萧寺暮云遮，惨离情半林黄叶。马迟人意懒，风急雁行斜。离恨重叠，破题儿第一夜。
想着昨日受用，谁知今日凄凉？
[步步娇]昨夜个翠被香浓熏兰麝，欹珊枕把身躯儿趄。脸儿厮揾者，仔细端详，可憎的别。铺云鬓玉梳斜，恰便似半吐初生月。
早到也，店小二哥那里？[小二哥上云]官人，俺这头房里下。[末云]琴童接了马者！点上灯，我诸般不要吃，则要睡些儿。[仆云]小人也辛苦，待歇息也。[在床前打铺做睡科][末云]今夜甚睡得到我眼里来也！
[落梅风]旅馆欹单枕，秋蛩鸣四野，助人愁的是纸窗儿风裂。乍孤眠被儿薄又怯，冷清清几时温热！
[末睡科][旦上云]长亭畔别了张生，好生放心不下。老夫人和梅香都睡了，我私奔出城，赶上和他同去。
[乔木查]走荒郊旷野，把不住心娇怯，喘吁吁难将两气接。疾忙赶上者，打草惊蛇。
[搅筝琶]他把我心肠扯，因此不避路途赊。瞒过俺能拘管的夫人，稳住俺厮齐攒的侍妾。想着他临上马痛伤嗟，哭得我也似痴呆。不是我心邪，自别离已后，到西日初斜，愁得来陡峻，瘦得来唓嗻。则离得半个日头，却早又宽掩过翠裙三四褶，谁曾经这般磨灭？
[锦上花]有限姻缘，方才宁贴；无奈功名，使人离缺。害不了的愁怀，恰才觉些：撇不下的相思，如今又也。
[幺篇]清霜净碧波，白露下黄叶。下下高高，道路曲折；四野风来左右乱踅。我这里奔驰，他何处困歇？
[清江引]呆答孩店房儿里没话说，闷对如年夜。暮雨催寒蛩，晓风吹残月，今宵酒醒何处也？
[旦云]在这个店儿里，不免敲门。[末云]谁敲门哩？是一个女人的声音。我且开门看咱。这早晚是谁？
[庆宣和]是人呵疾忙快分说，是鬼呵合速灭。[旦云]是我。老夫人睡了，想你去了呵，几时再得见，特来和你同去。[末唱]听说罢将香罗袖儿拽，却原来是姐姐、姐姐。
难得小姐的心勤！
[乔牌儿]你是为人须为彻，将衣袂不藉。绣鞋儿被露水泥沾惹，脚心儿管踏破也。
[旦云]我为足下呵，顾不得迢递。[旦唧唧了]
[甜水令]想着你废寝忘餐，香消玉减，花开花谢，犹自觉争些；便枕冷衾寒，凤只鸾孤，月圆云遮，寻思来有甚伤嗟。
[折桂令]想人生最苦离别，可怜见千里关山，独自跋涉。似这般割肚牵肠，倒不如义断恩绝。虽然是一时间花残月缺，休猜做瓶坠簪折。不恋豪杰，不羡骄奢；自愿的生则同衾，死则同穴。
[外净一行扮卒子上叫云]恰才见一女子渡河，不知那里去了？打起火把者。分明见他走在这店中去也，将出来！将出来！[末云]却怎了？[旦云]你近后，我自开门对他说。
[水仙子]硬围着普救寺下锹镬，强当住咽喉仗剑钺。贼心肠馋眼恼天生得劣。[卒子云]你是谁家女子，夤夜渡河？[旦唱]休言语，靠后些！杜将军你知道他是英杰，觑不觑着你为了醯酱，指一指教你化做膋血。骑着匹白马来也。
[卒子抢旦下][末惊觉云]呀，原来却是梦里。且将门儿推开看。只见一天露气，满地霜华，晓星初上，残月犹明。无端燕鹊高枝上，一枕鸳鸯梦不成！
[雁儿落]绿依依墙高柳半遮，静悄悄门掩清秋夜。疏剌剌林梢落叶风，昏惨惨云际穿窗月。
[得胜令]惊觉我的是颤巍巍竹影走龙蛇，虚飘飘庄周梦蝴蝶，絮叨叨促织儿无休歇，韵悠悠砧声儿不断绝。痛煞煞伤别，急剪剪好梦儿应难舍；冷清清的咨嗟，娇嘀嘀玉人儿何处也！
[仆云]天明也。咱早行一程儿，前面打火去。[末云]店小二哥，还你房钱，鞴了马者。
[鸳鸯煞]柳丝长咫尺情牵惹，水声幽仿佛人呜咽。斜月残灯，半明不灭。畅道是旧恨连绵，新愁郁结；别恨离愁，满肺腑难淘泻。除纸笔代喉舌，千种相思对谁说。[并下]
[络丝娘煞尾]都则为一官半职，阻隔得千山万水。', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2785e272d4b2254d9aa", "shortContent": "这是关汉卿《玉镜台》杂剧第一折中扮演温峤的“正末”演唱的三支曲辞，虽并不连贯，但在展示故事情节、人物性格的发展上，却是带有阶段标志的关键曲辞。\n本剧剧情缘自《世说新语·诡谲》中“温峤娶妇”的故事。说的是晋朝骠骑大将军温峤中年丧偶，喜其表妹姿慧，遂假借为之择婿之名，行骗娶为妻之实。妙的是这位表妹十分知趣，欣然从之，并于洞房花烛之时，“以手披纱扇，抚掌大笑，曰：‘我固疑是老奴，果如所卜。’”从而完成了...", "authors": ["黄", "克"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec280911759740c9bc50e", "shortContent": "《黄粱梦》第三折，据《元曲选》、《古名家杂剧》为马致远撰，而据《录鬼簿》、《太和正音谱》载，此折为花李郎所作。而就其辞风观之，则颇似马致远风格。\n此折写吕岩（洞宾）因贪赃卖阵，被发配充军。路上，解差放他逃生，偏偏遇上大风雪，迷纵失路。钟离权幻化成樵夫前去点化他。这几支曲就是其所唱的歌咏雪景的曲词。\n第一支〔六国朝〕头三句突兀而起，开门见山，点明所写乃大风雪：强劲的旋风，吹剪着鹅毛般的团团大雪，将海...", "authors": ["唐葆祥"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec28f03572034f65a85f2", "shortContent": "《倩女离魂》第二折写王文举走后，倩女相思成疾，一病不起。王文举能否中举？中举之后会否变心？这重重的顾虑与恐惧，像一片阴霾，浓重地笼罩着她。尽管这一切密切地关系着她的爱情幸福，但她却对此束手无策。因为封建社会妇女在婚姻上的不平等地位，决定了她只能消极等待命运的安排，而不可能有任何积极的作为。然而，《倩女离魂》没有就此却步，它通过倩女魂离躯壳，追赶王文举，跟随王文举一同上京，从而过上了幸福的爱情生活这...", "authors": ["欧阳光"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec290d635634aee3e9566", "shortContent": "曾瑞是一位善于描写妇女心理的作家，其今存的散曲里写闺情、闺怨、闺思的便有小令十四首和套曲一套。这类作品抒情意味浓郁，很受社会的欢迎，又最适宜于女艺人们演唱。从曾瑞的生平事迹来看，他未曾入仕，更不可能有宫廷生活的直接感受，因此所写的宫词实为闺怨的扩展。宫词是我国诗歌中传统题材之一，唐人对此很感兴趣；宋诗里虽有王珪、宋徽宗、杨皇后写过大量表现宫人生活的作品，但在宋词里却基本上无此题材，元曲中也很少见。...", "authors": ["谢桃坊"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2a55914587d02f58aa7", "shortContent": "这支套曲写男女送别，以女子的口吻，淋漓尽致地抒发了缠绵悱恻、千回百转的相思离别之情，读来情真意切，动人肺腑。\n〔斗鹌鹑〕曲写送别的情景。首二句写所见，远山沐浴着夕照，水边笼罩着淡烟。次二句写所闻，佛寺疏疏落落的钟鸣，戍楼断断续续的鼓声。这傍晚的景色，加重了离人的依依惜别之情。而且这些景物，又是离人所见、所闻，染上了感情色彩。四组名词并列，色调暗淡、声音沉重，奠定了整支套曲沉痛清凄的基调。而“一叶扁...", "authors": ["郭英德"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2b02e6a6b501f966e55", "shortContent": "这是一个悲剧。女主人公冯玉兰的父亲携带满门家眷去福建泉州府赴任，行至长江黄芦荡遇大风泊船。当晚遇一巡江官巡江，因同为仕宦中人，便请到舟中置酒相待。巡江官见冯母有姿色，便将冯氏全家尽皆杀死，掠冯母为妻。冯玉兰急中生智，将书匣抛入江中，凶手误以为她跳江自尽，她则躲在船尾的后舵上。待强人去远，她重又回到舟中，只身一人伴着五六具死尸，随风飘荡，船无灯火，只有凄凉的月光透进舟中，景象十分凄惨。这支曲子就是这...", "authors": ["张人和"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f41677d0ac1145496c3e9", "shortContent": "小生与小姐分手，行来又早二十里之外，前面就是草桥客店。不免安歇一宵，明日早行。我想昨夜受用，今夜凄凉，这马儿百般不肯行。正是：行色一鞭催去马，离愁万斛引新诗[3]。\n早到店中，店主何在？（净上）请官人就在里面安歇，官人吃酒饭么？（生）酒饭俱不要吃了。琴童你吃饭。（丑）我也不吃了，睡了罢。（生）今夜如何睡得着！\n不觉睡思将来，且暂歇一宵。（作睡介）（旦上）\n奴家在十里长亭，别了张生回去，好放他不下。...", "authors": ["周锡山"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f416e911759740c9cabc0", "shortContent": "春来秋去几经过，不似今秋愁奈何。心事暗流银烛泪，恨随飘泊叶声多。妙常苦守清规，已经多载。无奈尘心未尽，俗念顿生。对景添愁，强制不定，可恨人也！\n笔墨在此，不免将心事描写一词，聊寄幽情，消遣则个。（词曰）松舍清灯闪闪，云堂钟鼓沉沉。黄昏独自展孤衾，欲睡先愁不稳。\n一念静中思动，遍身欲火难禁。强将津唾咽凡心，争奈凡心转盛。（净王尼姑上）\n今日远辱到此，有何话说？（净）久失相亲，特来听讲。（旦）你平日不...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f418234a8757d5a0fabf7", "shortContent": "（场上设妆台、床、帐等物）（旦宫妆上）\n奴家自入深宫，忽经数载。身在歌楼舞院，心依裙布荆钗。虽蒙圣上恩许放归，未知何日！那梁郎自从宜春院中一番相见，此后信息杳然。料他绝意姻缘，谁敢向宫闱问信！好不伤情也呵。（停针泪介）今昔宫门深闭，秋雨濛濛，灯焰无光，庭梧乱坠。才向绣床针指，不觉睡魔到来。（欠伸介）不免解去罗衣，且向牙床歇息。（作卸妆解衣就床欲睡介）（内打一更介）（旦睡又起钩帐揩泪介）听外边风雨之...", "authors": ["徐振贵"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f418734a8757d5a0fac0f", "shortContent": "（旦淡妆带老旦、贴上）\n奴家崔莹，得放还家，严亲已殁，本是痛不欲生，只因养娘苦苦相劝，院子又述爹爹遗命[2]，因此拜辞坟墓，买舟前来，可巧仍泊在春间那个地方。已打发院子到唐六如那里去了。（叹介）咳，春间尚有爹爹同行，今日只身来此。（哭介）我那爹爹哟！\n（老旦）小姐，不要思前想后，保重玉体要紧。将来夫妻和美，老爷太太在阴间也是欢喜的。（旦）养娘，你教我怎不思想哟？爹妈如在，今日岂要奴家自主？只是院子...", "authors": ["郭", "梅"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572707162, '5dbd2ad530863b006c42d258', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643566, '西厢记 · 第五本 · 楔子', NULL, 1, 41, 0, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[末引仆人上开云]自暮秋与小姐相别，倏经半载之际。托赖祖宗之荫，一举及第，得了头名状元。如今在客馆听候圣旨御笔除授，惟恐小姐挂念，且修一封书，令琴童家去，达知夫人，便如小生得中，以安其心。琴童过来，你将文房四宝来，我写就家书一封，与我星夜到河中府去。见小姐时说：“官人怕娘子忧，特地先着小人将书来。”即忙接了回书来者。过日月好疾也呵！
[仙吕][赏花时]相见时红雨纷纷点绿苔，别离后黄叶萧萧凝暮霭。今日见梅开，别离半载。琴童，我嘱咐你的言语记着！则说道特地寄书来。[下]
[仆云]得了这书，星夜望河中府走一遭。[下]', '', '', '', NULL, '', 'indent', 1572707500, '5dbd2c2ac05a8000684d47da', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643567, '西厢记 · 第五本 · 第一折', NULL, 0, 41, 0, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[旦引红娘上开云]自张生去京师，不觉半年，杳无音信。这些时神思不快，妆镜懒抬，腰肢瘦损，茜裙宽褪，好烦恼人也呵！
[商调][集贤宾]虽离了我眼前，却在心上有；不甫能离了心上，又早眉头。忘了时依然还又，恶思量无了无休。大都来一寸眉峰，怎当他许多颦皱。新愁近来接着旧愁，厮混了难分新旧。旧愁似太行山隐隐，新愁似天堑水悠悠。
[红云]姐姐往常针尖不倒，其实不曾闲了一个绣床，如今百般的闷倦。往常也曾不快，将息便可，不似这一场清减得十他利害。[旦唱]
[逍遥乐]曾经消瘦，每遍犹闲，这番最陡。[红云]姐姐心儿闷呵，那里散心耍咱。[旦唱]何处忘忧？看时节独上妆楼，手卷帘上玉钩，空目断山明水秀；见苍烟迷时树，衰草连天，野渡横舟。
[旦云]红娘，我这衣裳这些时都不似我穿的。[红云]姐姐正是“腰细不胜衣”。[旦唱]
[挂金索]裙染榴花，睡损胭脂皱；纽结丁香，掩过芙蓉扣；线脱珍珠，泪湿香罗袖；杨柳眉颦，“人比黄花瘦”。
[仆人上云]奉相公言语，特将书来与小姐。恰才前厅上见了夫人，夫人好生欢喜，着入来见小姐。早至后堂。[咳嗽科][红问云]谁在外面？[见科][红见仆了][红笑云]你几时来？可知道“昨夜灯花报，今朝喜鹊噪。”姐姐正烦恼哩，你自来？和哥哥来？[仆云]哥哥得了官也，着我寄书来。[红云]你则在这里等着，我对俺姐姐说了呵，你进来。[红见旦笑科][[旦云]这小妮子怎么？[红云]姐姐，大喜大喜，咱姐夫得了官也。[旦云]这妮子见我闷呵，特故哄我。[红云]琴童在门首，见了夫人了，使他进来见姐姐，姐夫有书。[旦云]惭愧，我也有盼着他的日头，唤他入来。[仆入见旦科][旦云]琴童，你几时离京师？[仆云]离京一月多，我来时哥哥去吃游街棍子去了。[旦云]这禽兽不省得，状元唤做夸官，游街三日。[仆云]夫人说的便是，有书在此，[旦做接书科]
[金菊花]早是我只因他去减了风流，不争你寄得书来又与我添些儿证候。说来的话儿不应口，无语低头，书在手，泪凝眸。
[旦开书看科]
[醋葫芦]我这里开时和泪开，他那里修时和泪修，多管阁着笔尖儿未写早泪先流，寄来的书泪点儿兀自有。我将这新痕把旧痕湮透。正是一重愁翻做两重愁。
[旦念书科]“张珙百拜奉启芳卿可人妆次：自暮秋拜违，倏尔半载。上赖祖宗之荫，下托贤妻之德，举中甲第。即日于招贤馆寄迹，以伺圣旨御笔除授。惟恐夫人与贤妻忧念，特令琴童奉书驰报，庶几免虑。小生身虽遥而心常迩矣，恨不得鹣鹣比翼，邛邛并躯。重功名而薄恩爱者，诚有浅见贪饕之罪。他日面会，自当请谢不备。后成一绝，以奉清照：玉京仙府探花郎，寄语蒲东窈窕娘，指日拜恩衣昼锦，定须休作倚门妆。”
[幺篇]当日向西厢月底黄，今日向琼要宴上搊。谁承望东墙脚步占了鳌头，怎想道惜花心养成折桂手，脂粉丛里包藏着锦绣！从今后晚妆楼改做了至公楼。
[旦云]你吃饭不曾？[仆云]上告夫人知道，早晨至今，空立厅前，那有饭吃。[旦云]红娘，你快取饭与他吃。[仆云]感蒙赏赐，我每就此吃饭，夫人写书。哥哥着小人索了夫人回书，至紧，至紧！[旦云]红娘将笔砚来。[红将来科][旦云]书却写了，无可表意，只有汗衫一领，裹肚一条，袜儿一双，瑶琴一张，玉簪一枚，斑管一枝。琴童，你收拾得好者。红娘取银十两来，就与他盘缠。[红娘云]姐夫得了官，岂无这几件东西，寄与他有甚缘故？[旦云]你不知道。这汗衫儿呀，
[梧叶儿]他若是和衣卧，便是和我一处宿；但贴着他皮肉，不信不想我温柔。[红云]这裹肚要怎么？[旦唱]常则不要离了前后，守着他左右，紧紧的系在心头。[红云]这袜儿如何？[旦唱]拘管他胡行乱走。
[红云]这琴他那里自有，又将去怎么？[旦唱]
[后庭花]当日五言诗紧趁逐，后来因七弦琴成配偶。他怎肯冷落了诗中意，我则怕生疏了弦上手。[红云]玉簪呵，有甚主意？[旦唱]我须有个缘由，他如今功名成就，只怕他撇人在脑后。[红云]斑管要怎的？[旦唱]湘江两岸秋，当日娥皇因虞舜愁，今日莺莺为君瑞忧。这九嶷山下竹，共香罗衫袖口——
[青哥儿]都一般啼痕湮透。似这等泪斑宛然依旧，万古情缘一样愁。涕泪交流，怨慕难收，对学士叮咛说缘由，是必休忘旧！
[旦云]琴童，这东西收拾好者。[仆云]理会得。[旦唱]
[醋葫芦]你逐宵野店上宿，休将包袱做枕头，怕油脂腻展污了恐难酬。倘或水侵雨湿休便扭，我则怕干时节熨不开褶皱。一桩桩一件件细收留。
[金菊花]书封雁足此时修，情系人心早晚休？长安望来天际头，倚遍西楼，“人不见，水空流。”
[仆云]小人拜辞，即便去也。[旦云]琴童，你见官人对他说。[仆云]说甚么？[旦唱]
[浪里来煞]他那里为我愁，我这里因他瘦。临行时啜赚人的巧舌头，指归期约定九月九，不觉的过了小春时候。到如今“悔教夫婿觅封侯”。
[仆云]得了回书，星夜回俺哥哥话去。[并下]', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2802e6a6b501f966dda", "shortContent": "这是本折也是全剧开头部分的曲子。王昭君被毛延寿点破图形，发入冷宫，寂寞中弹琵琶遣愁。汉元帝驾幸后宫，闻声而寻，本曲便是此时所唱，它为本剧主人公汉元帝的思想性格定立基调。汉元帝在本剧中是一个软弱无能的形象，但温柔善感，谴惓多情。这并非是历史上汉元帝的真貌，不过是作者借古人衣冠塑造的“风流天子，败国之君”而已。本曲则着重刻画其多情善感的一面。\n夜深了，宫中静悄悄，内官们提着灯，陪他在宫槐下慢慢巡行。他...", "authors": ["陈西汀"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec28f03572034f65a85f1", "shortContent": "《倩女离魂》是元代后期杰出的杂剧作家郑光祖的代表作。此剧据唐代陈玄祐的传奇小说《离魂记》改编。全剧四折一楔子。第一折写主人公张倩女从小和王文举订婚。王成人后，专程来张家成亲，讵料张母却以“俺家三辈不招白衣秀士”为由，打发他往京城应举。一对热恋中的情人被拆散，不由使他们悲痛欲绝。这两支曲子，就是倩女在和情人执手临歧、忍痛泣别时的唱词。\n〔元和令〕曲写倩女对即要远行的情人的叮咛嘱托。随着别离时刻的临近...", "authors": ["欧阳光"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2900f8fda556505ffd8", "shortContent": "鲍天祐，字吉甫，杭州人，十四世纪初前后在世。“初业儒，长事吏。簿书之役，非其志也……竟止昆山州吏而卒。”（《录鬼簿》）所作杂剧，今知有八种，多已散佚，仅本剧和《史鱼尸谏卫灵公》二剧有残曲留存。\n本剧今仅存残曲二套，所以全剧的详细内容已难以尽知。但它的基本情节当和《夷坚志》、《野客丛书》、《情史》、《陔馀丛考》等书所载长沙妓事大体相同，综合各书记述，可约略勾勒如下。\n北宋著名词人秦观（少游）遭受谪迁...", "authors": ["陈", "多"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f41760ce818559d071a83", "shortContent": "奴仆，听取一言宽解。把双眉暂展舒，休得要伤悲痛忆。夫人，就\n是天道有盛衰[8]，日月有盈亏，江河有消长，山川有崩卸。你今虽遭此\n陷阱，岂无泰来时节[9]？比你做天边一轮明月，暂时掩在云端里。\n嗏，我把残躯付与伊，异日里若得夫妻相会，子母团圆，便做犬马区区当报你[13]。（夫）夫人呵，曾闻苏武牧羊时[14]，也有还家里。不须忧虑，不须忧虑。（旦）老奴呵，异日里不报冤仇，除非是咽喉绝气。\n老奴，你拿去...", "authors": ["陆", "林"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f417f03572034f65b654e", "shortContent": "我家小姐自从京里回来，那些冰人月老足不离门，把男子的才貌，说得天花乱坠。谁想走到面前，不是读死书的秀才，就是卖油腔的浪子，所以小姐甚是厌烦。如今坐在绣房里面，不肯轻易见人。但有求亲的来，只传个题目出来考试，要待文才技艺都考中了，才肯出来面相人才。今日是个结婚姻的日子，怕有说亲的来，只得在此伺候。\n（老旦）老师父，想是又来说亲么？（丑）正是。今日这头亲事是十拿九稳的，快请小姐出来。（老旦）我家小姐被...", "authors": ["盛志梅"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572707544, '5dbd2c5412215f00711cd123', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643568, '西厢记 · 第五本 · 第二折', NULL, 0, 41, 0, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[末云]“画虎未成君莫笑，安排牙爪始惊人。”本是举过便除，奉圣旨着翰林院编修国史。他每那知我的心，甚么文章做得成。使琴童递佳音，不见回来。这几日睡卧不宁，饮食少进，给假在驿亭中将息。早间太医着人来看视，下药去了。我这病卢扁也医不得。自离了小姐，无一日心闲也呵！
[中吕][粉蝶儿]从到京师，思量心旦夕如是，向心头横躺着俺那莺儿。请医师，看诊罢，一星星说是。本意待推辞，则被他察虚实不须看视。
[醉春风]他道是医杂证有方术，治相思无药饵。莺莺呵，你若是知我害相思，我甘心儿死、死。四海无家，一身客寄，半年将至。[仆上云]我则道哥哥除了，原来在驿亭中抱病，须索回书去咱。[见了科][末云]你回来了也。
[迎仙客]疑怪这噪花枝灵鹊儿，垂帘幕喜蛛儿，正应着短檠上夜来灯爆时。若不是断肠词，决定是断肠评理。[仆云]小夫人有书至此。[末接科]写时管情泪如丝，既不呵，怎生泪点儿封皮上渍。
[末读书科]“薄命妾崔氏拜覆，敬奉才郎君瑞文几：自音容去后，不觉许时，仰敬之心，未尝少怠。纵云日近长安远，何故鳞鸿之杳矣。莫因花柳之心，弃妾恩情之意？正念间，琴童至，得见翰墨，始知中科，使妾喜之如狂。郎之才望，亦不辱相国之家谱也。今因琴童回，无以奉贡，聊布瑶琴一张，玉簪一枝，斑管一枚，裹肚一条，汗衫一领，袜儿一双，权表妾之真诚。匆匆草字，伏乞情恕不备。谨依来韵，遂继一绝云：阑干倚遍盼才郎，莫恋宸京黄四娘；病里得书如中甲，窗前览镜试新妆。”那风风流流的姐姐，似这等女子，张珙死也得着了。
[上小楼]这的堪为字史，当为款识。有柳骨颜筋，张旭张颠，羲之献之。此一时，彼一时，佳人才思，俺莺莺世间无二。
[幺篇]俺做经咒般持，符（竹录）般使。高似金章，重似金帛，贵似金资。这上面若签个押字，使个令史，差个勾使，则是一张忙不及印赴期的咨示。
[末拿汗衫儿科]休道文章，只看他这针指，人间少有。
[满庭芳]怎不教张生爱尔，堪针工出色，女教为师。几千般用意针针是，可索寻思。长共短又没个样子，窄和宽想象著腰肢，好共歹无人试。想当初做时，用煞那小心儿。
小姐寄来这几件东西，都有缘故，一件件我都猜着了。
[白鹤子]这琴，他教我闭门学禁指，留意谱声诗，调养圣贤心，洗荡巢由耳。
[二煞]这玉簪，纤长如竹笋，细白似葱枝，温润有清香，莹洁无瑕眦。
[三煞]这斑管，霜枝曾栖凤凰，泪点渍胭脂，当时舜帝恸娥皇，今日淑女思君子。
[四煞]这裹肚，手中一叶绵，灯下几回丝，表出腹中愁，果称心间事。
[五煞]这鞋袜儿，针脚儿细似虮子，绢帛儿腻似鹅脂，既知礼不胡行，愿足下当如此。
琴童，你临行小夫人对你说甚么？[仆云]着哥哥休别继良姻。[末云]小姐，你尚然不知我的心哩。
[快活三]冷清清客店儿，风淅淅雨丝丝，雨儿零，风儿细，梦回时，多少伤心事。
[朝天子]四肢不能动止，急切里盼不到蒲东寺。小夫人须是你见时，别有甚闲传示？我是个浪子官人，风流学士，怎肯去带残花折旧枝。自从到此，甚的是闲街市。
[贺圣朝]少甚宰相人家，招婿的娇姿。其间或有个人儿似尔，那里取那温柔，这般才思？想莺莺意儿，怎不教人梦想眠思？
琴童，将这衣裳东西收拾好者。
[耍孩儿]则在书房中倾倒个藤箱子，向箱子里面铺几张纸。放时节须索用心思，休教藤刺儿抓住绵丝。高抬在衣架怕吹了颜色，乱裹在包袱中恐锉了褶儿。当如此，切须爱护，勿得因而。
[二煞]恰新婚，才燕尔，为功名来到此。长安忆念蒲东寺。昨宵个春风桃李花开夜，今日个秋雨梧桐叶落时。愁如是，身遥心迩，坐想行思。
[三煞]这天高地厚情，直到海枯石烂时，此时作念何时止？直到烛灰眼下才无泪，蚕老心中罢却丝。我不比游荡轻薄子，轻夫妇的琴瑟，拆鸾凤的雄雌。
[四煞]不闻黄犬音，难传红叶诗，驿长不遇梅花使，孤身去国三千里，一日归必十二时。凭栏视，听江声浩荡，看山色参差。
[尾]忧则忧我在病中，喜则喜你来到此。投至得引人魂卓氏音书至，险将这害鬼病的相如盼望死。[下]', '', '', '', NULL, '', 'indent', 1572707593, '5dbd2c86c05a8000684d4c0d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643569, '西厢记 · 第五本 · 第三折', NULL, 3, 41, 0, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[净扮郑恒上开云]自家姓郑名恒，字伯常。先人拜礼部尚书，不幸早丧。后数年，又丧母。先人在时曾定下俺姑娘的女孩儿莺莺为妻，不想姑夫亡化，莺莺孝服未满，不曾成亲。俺姑娘将着这灵榇，引着莺莺，回博陵下葬，为因路阻，不能得去。数月前写书来唤我同扶柩去；因家中无人，来得迟了。我离京师，来到河中府，打听得孙飞虎欲掳莺莺为妻，得一个张君瑞退了贼兵，俺姑娘许了他。我如今到这里，没这个消息，便好去见他；既有这个消息，我便撞将去呵，没意思。这一件事都在红娘身上，我着人去唤他。则说“哥哥从京师来，不敢来见姑娘，着红娘来下处来，有话去对姑娘行说去”。去的人好一会了，不见来。见姑娘和他有话说。[红上云]郑恒哥哥在下处，不来见夫人，却唤我说话。夫人着我来，看他说甚么。[见净科]哥哥万福！夫人道哥哥来到呵，怎么不来家里来？[净云]我有甚颜色见姑娘？我唤你来的缘故是怎生？当日姑夫在时，曾许下这门亲事；我今番到这里，姑夫孝已满了，特地央及你去夫人行说知，拣一个吉日成合了这件事，好和小姐一答里下葬去。不争不成合，一答里路上难厮见。若说得肯呵，我重重的相谢你。[红云]这一节话再也休题，莺莺已与了别人了也。[净云]道不得“一马不跨双鞍”，可怎生父在时曾许了我，父丧之后，母倒悔亲？这个道理那里有？[红云]却非如此说。当日孙飞虎将半万贼兵来时，哥哥你在那里？若不是那生呵，那里得俺一家儿来？今日太平无事，却来争亲；倘被贼人掳去呵，哥哥如何去争？[净云]与了一个富家，也不枉了，却与了这个穷酸饿醋。偏我不如他？我仁者能仁、身里出身的的根脚，又是亲上做亲，况兼他父命。[红云]他倒不如你，噤声！
[越调][斗鹌鹑]卖弄你仁者能仁，倚仗你身里出身；至如你官上加官，也不合亲上做亲。又不曾执羔雁邀媒，献币帛问肯。恰洗了尘，便待要过门；枉腌了他金屋银屏，枉污了他锦衾绣裀。
[紫花儿序]枉蠢了他梳云掠月，枉羞了他惜玉怜香，枉村了他殢雨尤云。当日三才始判，两仪初分；乾坤：清者为乾，浊者为坤，人在中间相混。君瑞是君子清贤，郑恒是小人浊民。
[净云]贼来怎地他一个人退得？都是胡说！[红云]我对你说。
[天净沙]看河桥飞虎将军，叛蒲东掳掠人民，半万贼屯合寺门，手横着霜刃，高叫道要莺莺做压寨夫人。
[净云]半万贼兵，他一个人济甚么事？[红云]贼围之甚迫，夫人慌了，和长老商议，拍手高叫：“两廊不问僧俗，如退得贼兵的，便将莺莺与他为妻。”忽有游客张生，应声而前曰：“我有退兵之策，何不问我？”夫人大喜，就问：“其计何在？”生云：“我有一故人白马将军，现统十万之众，镇守蒲关。我修书一封，着人寄去，必来救我。”不想书至兵来，其困即解。
[小桃红]洛阳才子善属文，火急修书信。白马将军到时分，灭了烟尘。夫人小姐都心顺，则为他“威而不猛”，“言而有信”，因此上“不敢慢于人”。
[净云]我自来未尝闻其名，知他会也不会。你这个小妮子，卖弄他偌多！[红云]便又骂我，
[金蕉叶]他凭着讲性理齐论鲁论，作词赋韩文柳文，他识道理为人敬人，掩家里有信行知恩报恩。
[调笑令]你值一分，他值百分，萤火焉能比月轮？高低远近都休论，我拆白道字辨与你个清浑。[净云]这小妮子省得甚么拆白道字，你拆与我听。[红唱]君端是个“肖”字这壁着个“立人”，你是个“木寸”“马户”“尸巾”。
[净云]木寸、马户、尸巾——你道我是个“村驴屌”。我祖代是相国之门，到不如你个白衣、饿夫、穷士！做官的则是做官。[红唱]
[秃厮儿]他凭师友君子务本，你倚父兄仗势欺人。囗盐日月不嫌贫，博得个姓名新、堪闻。
[圣药王]这厮乔议论，有向顺。你道是官人则合做官人，信口喷，不本分。你道穷民到老是穷民，却不道“将相出寒门”。
[净云]这桩事都是那长老秃驴弟子孩儿，我明日慢慢的和他说话。[红唱]
[麻儿郎]他出家儿慈悲为本，方便为门。横死眼不识好人，招祸口知分寸。
[净云]这是姑夫的遗留，我拣日牵羊担酒上门去，看姑娘怎么发落我。[红唱]
[幺篇]讪筋，发村，使狠，甚的是软款温存。硬打捱强为眷姻，不睹事强谐秦晋。
[净云]姑娘若不肯，着二三十个伴当，抬上轿子，到下处脱了衣裳，赶将来还你一个婆娘。[红唱]
[络丝娘]你须是郑相国嫡亲的舍人，须不是孙飞虎家生的莽军。乔嘴脸、腌躯老、死身分，少不得有家难奔。
[净云]兀的那小妮子，眼见得受了招安了也。我也不对你说，明日我要娶，我要娶。[红云]不嫁你，不嫁你。
[收尾]佳人有意郎君俊，我待不喝采其实怎忍。[净云]你喝一声我听。[红笑云]你这般颓嘴脸，只好偷韩寿下风头香，傅何郎左壁厢粉。[下]
[净脱衣科云]这妮子拟定都和那酸丁演撒，我明日自上门去，见俺姑娘，则做不知。我则道张生赘在卫尚书家，做了女婿。俺姑娘最听是非，他自小又爱我，必有话说。休说别个，则这一套衣服也冲动他。自小京师同住，惯会寻章摘句，姑夫许我成亲，谁敢将言相拒。我若放起刁来，且看莺莺那去？且将压善欺良意，权作尤云殢雨心。[下][夫人上云]夜来郑恒至，不来见我，唤红娘去问亲事。据我的心则是与孩儿是；况兼相国在时已许下了，我便是违了先夫的言语。做我一个主家的不着，这厮每做下来。拟定则与郑恒，他有言语，怪他不得也。料持下酒者，今日他敢来见我也。[净上云]来到也，不索报覆，自入去见夫人。[拜夫人哭科][夫人云]孩儿既来到这里，怎么不来见我？[净云]小孩儿有甚嘴脸来见姑娘！[夫人云]莺莺为孙飞虎一节，等你不来，无可解危，许张生也。[净云]那个张生？敢便是状元。我在京师看榜来，年纪有二十四五岁，洛阳张珙，夸官游街三日。第二日头答正来到卫尚书家门首，尚书的小姐十八岁，结着彩楼，在那御街上，则一球正打着他。我也骑着马看，险些打着我。他家粗使梅香十余人，把那张生横拖倒拽入去。他口叫道：“我自有妻，我是崔相国女婿。”那尚书有权势气象，那里听，则管拖将入去了。这个却才便是他本分，出于无奈，尚书说道：“我女奉圣旨结彩楼，你着崔小姐做次妻。他是先奸后娶的，不应娶他。”闹动京师，因此认得他。[夫人怒云]我道这秀才不中抬举，今日果然负了俺家。俺相国之家，世无与人做次妻之理。既然张生奉圣旨娶了妻，孩儿，你拣个吉日良辰，依着姑夫的言语，依旧入来做女婿者。[净云]倘或张生有言语，怎生？[夫人云]放着我哩，明日拣个吉日良辰，你便过门来。[下][净云]中了我的计策了，准备筵席、茶礼、花红，克日过门者。[下][洁上云]老僧昨日买登科记看来，张生头名状元，授着河中府尹。谁想老夫人没主张，又许了郑恒亲事。老夫人不肯去接，我将着肴馔直至十里长亭接官走一遭。[下][杜将军上云]奉圣旨，着小官主兵蒲关，提调河中府事，上马管军，下马管民。谁想君瑞兄弟一举及第，正授河中府尹，不曾接得。眼见得在老夫人宅里下，拟定乘此机会成亲。小官牵羊担洒直至老夫人宅上，一来庆贺状元，二来就主亲，与兄弟成此大事。左右那里？将马来，到河中府走一遭。[下]', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2785e272d4b2254d9a8", "shortContent": "《关大王独赴单刀会》是关汉卿以他的盖世才华和诗人的激情所谱写的一支强者的颂歌。\n关于关羽单刀赴会事，史书上只有一句简略的记载：“肃邀羽相见，各驻兵马百步上，但请将军单刀俱会。”（《三国志·吴书·鲁肃传》）而戏中绝大部分情节和人物之间的关系则几乎都是虚构的，即使作者根据的那一点史实，也被大胆地改造成为关羽一人的单刀会。从全剧的调子来看，作者的美学追求并不在于这一历史事件构成的故事情节，而是要写出一种...", "authors": ["宁宗一"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2822e6a6b501f966de0", "shortContent": "王实甫《破窑记》所写故事，原在民间广泛流传。剧中女主人公刘月娥系刘员外（仲实）之独生女，因“高门不答，低门不就”，年已十八，尚未许聘。于是，刘员外搭彩楼，命月娥抛绣球“凭天匹配”。抛球之日，众男子聚集楼下，有纨袴子弟，亦有贫困书生。当时，尚“一贫如洗”的寇凖与吕蒙正亦在其中。吕蒙正（《宋史》有传，太平兴国中擢进士第一，历任中书侍郎、户部尚书、平章事，咸平年间，授太子太师，封蔡国公）即剧中之男主人公...", "authors": ["段启明"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec28f0f8fda556505ffd1", "shortContent": "这四支曲子是《王粲登楼》第三折中王粲登上溪山风月楼之后所唱。\n《王粲登楼》写的是家道贫寒的书生王粲，“学成满腹文章”，一心仕进，但为人“矜骄傲慢”。王粲的岳父东汉丞相蔡邕，派人召他进京。王辞母赴京。蔡邕为了“涵养他那锐气”，故意冷淡王粲，甚至在席筵上羞辱他，使其一怒而去。蔡邕使学士曹植暗助资财使王投靠刘表，然而又不为刘表所用。一日，流落荆州的王粲应友人许达的邀请到溪山风月楼游赏。王粲登楼，遥望中原...", "authors": ["胡世厚"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2982e6a6b501f966e22", "shortContent": "第三折的主要关目是“让肥”。“让肥”也是在前两折的基础上，进一步写饥饿。剧中赵礼对“贼盗”马武杀人为食的行为非但未有责备，而且一无惊诧，说明饥饿已经严重到人相食且不以食人为怪的程度。这是历史的真实。王莽时期全国大起义中下江、新市、绿林、铜马等队伍中，绝大多数是“七死”所余的饥民。马武正是被作为这样的“饿贼”形象来写的。正因为如此，他才有可能被“让肥”行为感动。造反可以理解，吃人也可以理解，可见饥饿...", "authors": ["池", "吉"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2a62cee9a0c24ed99ee", "shortContent": "朱凯的《昊天塔》（《元曲选》本不题撰人，《录鬼簿续编》题朱凯作）所演为北宋杨家将的故事。剧中杨氏父子史载实有其人。杨景之父杨业，本为北汉将领，后归宋，因军功屡迁至云州观察使。雍熙三年（986），杨业率兵与契丹军战于朔州（今山西朔县）陈家谷，兵败被俘，坚贞不屈，绝食三日而死，年约六十多岁（见《宋史》本传、《续资治通鉴》、《东都纪事》等）。死后宋王朝累赠至太师、中书令，所以后来人们称之为杨令公。杨业有...", "authors": ["李昌集"], "pressName": "上海辞书出版社"}, {"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec2b10f8fda556506004d", "shortContent": "《汉钟离度脱蓝采和》是敷演传说中八仙之一蓝采和成仙得道的杂剧。据南唐沈汾《续仙传》载：蓝为唐末人。常衣破蓝衫，持三尺大板，每行歌于城市乞索。其踏歌云：“踏踏歌，蓝采和，世界能几何？”后于（氵+亳）梁间酒楼乘醉轻举，于云中冉冉而去。陆游《南唐书》谓其名陈陶，此剧则名许坚，并由其持拍板善踏歌进而衍化为戏曲艺人。仙人钟离权见他有“半仙之分”，遂下凡到洛阳梁园棚勾栏里度他出家。上面所引〔点绛唇〕等四首曲文...", "authors": ["黄菊盛"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f4169dbb8b379ee0af32d", "shortContent": "么？（净唱）道是雷门布鼓[4]。把自己女儿，（唱）比做瑶台素娥[5]。\n他看得学生一低如此，还要谦和？（丑）富豪楼阁拥西湖，岂无一女成夫妇？（净）他便是缙绅，我拚金钞，一定要与他见个手段。（丑）学生也不好相劝：公家虽富，也要惜些毛羽。（唱）那器边有鼠，屋上有乌。（白）他不肯亲事，一定令郎有些不稳当处。（唱）子须教训，玉须琢磨。（白）教令郎读起书来，中了科甲[6]，自有贵戚相扳。（唱）却\n吕天成《曲...", "authors": ["史良昭"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f4175911759740c9cabda", "shortContent": "许差了。（外）仓皇漫赋《凤求凰》[4]，较量才貌须停当。（净）才貌\n停当，是那一个？（外）就是谢兄。（丑）我不曾许，难道妹子自家许的？（外）老夫与令先尊同辈，忝在父执之列，这婚姻好事，便代主何妨？\n报可是真的？（杂出录条介）请看条子，是京里分出来的。姓名早向榜头扬，录条现刻非虚谎。（净、丑）只怕还是假的。（杂）这等真\n报，还说假的，快将录银出来！喜出非常，花红衣帽，还要求先赏。【前腔】（净、丑）信...", "authors": ["包郑虹", "翁敏华"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8423353c0ba53f7deb", "bookTitle": "明清传奇鉴赏辞典（新一版）", "articleId": "610f41825914587d02f6784d", "shortContent": "区区程道脉，胡短鼻头赤。本是光棍徒，强作斯文客。既不会诗词，又未读史册。只假道学名，要把时人吓。大袖长海青[2]，方知高一尺。拱手走方路，脚着方朱舄。正心与诚意，腐谈偏夺席。哄人来应举，卷子常曳白。抢菜如饿鬼，放屁像打麦。形状似端方，做事最狼籍。好色更贪财，暗地多诡谲。名为陈仲子[3]，实是柳盗跖。人家请我做同窗，这样良朋有何益？学生钻刺了张太史的荐书，侥幸做虞公子的同事。但他是风流才学之士，见我...", "authors": ["朱恒夫"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572707633, '5dbd2caca3180b0068e742c5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643570, '西厢记 · 第五本 · 第四折', NULL, 6, 41, 1, 1, '王实甫', NULL, 10666, '5841af6f61ff4b006b8e119e', '元', 'wen', '文', '', '', '[夫人上云]谁想张生负了俺家，去卫尚书家做女婿去，今日不负老相公遗言，还招郑恒为婿。今日好个日子，过门者，准备下筵席，郑恒敢待来也。[末上云]小官奉圣旨，正授河中府尹。今日衣锦还乡，小姐的金冠霞帔都将著，若见呵，双手索送过去。谁想有今日也呵！文章旧冠乾坤内，姓字新闻日月边。
[双调][新水令]玉鞭骄马出皇都，畅风流玉堂人物。今朝三品职，昨日一寒儒。御笔亲除，将名姓翰林注。
[驻马听]张珙如愚，酬志了三尺龙泉万卷书；莺莺有福，稳请了五花官诰七香车。身荣难忘借僧居，愁来犹记题诗处。从应举，梦魂儿不离了蒲东路。
[末云]接了马者！[见夫人科]新状元河中府尹婿张珙参见。[夫人云]休拜，休拜，你是奉圣旨的女婿，我怎消受得你拜？[末唱]
[乔牌儿]我谨躬身问起居，夫人这慈色为谁怒？我则见丫鬟使数都厮觑，莫不我身边有甚事故？
[末云]小生去时，夫人亲自饯行，喜不自胜。今日中选得官，夫人反行不悦，何也？[夫人云]你如今那里想着俺家？道不得个“靡不有初，鲜克有终”。我一个女孩儿，虽然妆残貌陋，他父为前朝相国。若非贼来，足下甚气力到得俺家？今日一旦置之度外，却于卫尚书家作婿，岂有是理？[末云]夫人听谁说？若有此事，天不盖，地不载，害老大小疔疮！
[雁儿落]若说着《丝鞭仕女图》，端的是塞满章台路。小生呵此间怀旧恩，怎肯别处寻亲去？
[得胜令]岂不闻“君子断其初”，我怎肯忘得有恩处？那一个贼畜生行嫉妒；说来的无徒，迟和疾上木驴。
[夫人云]是郑恒说来，绣球儿打着马了，做女婿也。你不信呵，唤红娘来问。[红上云]我巴不得见他，原来得官回来。惭愧，这是非对着也。[末背云]红娘，小姐好么？[红云]为你别帮了女婿，俺小姐依旧嫁了郑恒也。[末云]有这般跷蹊的事！
[庆东原]那里有粪堆上长出连枝树，淤泥中生出比目鱼？不明白殿污了姻缘簿？莺莺呵，你嫁个油炸猢狲的丈夫；红娘呵，你伏侍个烟薰猫儿的姐夫；张生呵，你撞着个水浸老鼠的姨夫。这厮坏了风俗，伤了时务。
[红唱]
[乔木查]妾前来拜覆，省可里心头怒！间别来安乐否？你那新夫人何处居？比俺姐姐是何如？
[末云]和你也葫芦提了也。小生为小姐受过的苦，诸人不知，瞒不得你。不甫能成亲，焉有是理？
[搅筝琶]小生若求了媳妇，则目下便身殂。怎肯忘得待月回廊，难撇下吹箫伴侣。受了些活地狱，下了些死工夫。不甫能得做妻夫，现将着夫人诰敕，县君名称，怎生待欢天喜地，两只手儿分付与。你划地倒把人赃诬。
[红对夫人云]我道张生不是这般人，则唤小姐出来自问他。[叫旦科]姐姐快来问张生，我不信他直恁般薄情。我见他呵，怒气冲天，实有缘故。[旦见末科][末云]小姐间别无恙？[旦云]先生万福！[红云]姐姐有的言语，和他说破。[旦长吁云]待说甚么的是！
[沉醉东风]不见时准备着千言万语，得相逢都变做短叹长吁。他急攘攘却才来，我羞答答怎生觑。将腹中愁恰待申诉，及至相逢一句也无。只道个“先生万福”。
[旦云]张生，俺家何负足下？足下见弃妾身，去卫尚书家为婿，此理安在？[末云]谁说来？[旦云]郑恒在夫人行说来。[末云]小姐如何听这厮？张珙之心，惟天可表！
[落梅风]从离了蒲东路，来到京兆府，见个佳人世不曾回顾。硬揣个卫尚书家女孩儿为了眷属，曾见他影儿的也教灭门绝户。
[末云]这一桩事都在红娘身上，我则将言语傍着他，看他说甚么。红娘，我问人来，说道你与小姐将简帖儿去唤郑恒来。[红云]痴人，我不合与你作成，你便看得我一般了。[红唱]
[甜水令]君瑞先生，不索踌躇，何须忧虑。那厮本意糊涂；俺家世清白，祖宗贤良，相国名誉。我怎肯他跟前寄简传书？
[折桂令]那吃敲才怕不口里嚼蛆，那厮待数黑论黄，恶紫夺朱。俺姐姐更做道软弱囊揣，怎嫁那不值钱人样虾朐。你个东君索与莺莺做主，怎肯将嫩枝柯折与樵夫，那厮本意嚣虚，将足下亏图，有口难言，气夯破胸脯。
[红云]张生，你若端的不曾做女婿呵，我去夫人跟前一力保存你。等那厮来，你和他两个对证。[红见夫人云]张生并不曾人家做女婿，都是郑恒谎，等他两个对证。[夫人云]既然他不曾呵，等郑恒那厮来对证了呵，再做说话。[洁上云]谁想张生不举成名，得了河中府尹，老僧一径到夫人那里庆贺。这门亲事，几时成就？当初也有老僧来，老夫人没主张，便待要与郑恒。若与了他，今日张生来却怎生？[洁见叙寒温科][对夫人云]夫人，今日却知老僧说的是，张生决不是那一等没行止的秀才。他如何敢忘了夫人，况兼杜将军是证见，如何悔得他这亲事？[旦云]张生，此一事必得杜将军来方可。
[雁儿落]他曾笑孙庞真下愚，论贾马非英物；正授着征公元帅府，兼领着陕右河中路。
[得胜令]是咱前者护身符，今日有权术。来时节定把先生助，决将贼子诛。他不识亲疏，啜赚良人妇；你不辨贤愚，无毒不丈夫。
[夫人云]着小姐去卧房里去者。[旦、红下][杜将军上云]下官离了蒲关，到普救寺。第一来庆贺兄弟咱，第二来就与兄弟成就了这亲事。[末对将军云]小弟托兄长虎威，得中一举。今者回来，本待做亲，有夫人的侄儿郑恒，来夫人行说道你兄弟在卫尚书家作赘了。夫人怒欲悔亲，依旧要将莺莺与郑恒，焉有此理？道不得个“烈女不更二夫”。[将军云]此事夫人差矣。君瑞也是礼部尚书之子，况兼又得一举。夫人世不招白衣秀士，今日反欲罢亲，莫非理上不顺？[夫人云]当初夫主在时，曾许下这厮，不想遇此一难，亏张生请将军来杀退贼众。老身不负前言，欲招他为婿；不想郑恒说道，他在卫尚书家做了女婿也，因此上我怒他，依旧许了郑恒。[将军云]他是贼心，可知道诽谤他。老夫人如何便信得他？[净上云]打扮得整整齐齐的，则等做女婿。今日好日头，牵羊担酒过门走一遭。[末云]郑恒，你来怎么？[净云]苦也！闻知状元回，特来贺喜。[将军云]你这厮怎么要诳骗良人的妻子，行不仁之事，我跟前有甚么话说？我奏闻朝廷，诛此贼子。[末唱]
[落梅风]你硬入桃源路，不言个谁是主，被东君把你个蜜蜂拦住。不信呵去那绿杨影里听杜宇，一声声道：不如归去。
[将军云]那厮若不去呵，祗候拿下。[净云]不必拿，小人自退亲事与张生罢。[夫人云]相公息怒，赶出去便罢。[净云]罢罢！要这性命怎么，不如触树身死。妻子空争不到头，风流自古恋风流；“三寸气在千般用，一日无常万事休。”[净倒科][夫人云]俺不曾逼死他，我是他亲姑娘，他又无父母，我做主葬了者。着唤莺莺出来，今日做个庆喜的茶饭，着他两口儿成合者。[旦、红上，末、旦拜科][末唱]
[沽美酒]门迎着驷马车，户列着八椒图，娶了个四德三从宰相女，平生愿足，托赖着众亲故。
[太平令]若不是在恩人拨刀相助，怎能够好夫妻似水如鱼。得意也当时题柱，正酬了今生夫妇。自古、相女、配夫，新状元花生满路。
[使臣上科][末唱]
[锦上花]四海无虞，皆称臣庶；诸国来朝，万岁山呼；行迈羲轩，德过舜禹；圣策神机，仁文义武。
[幺篇]朝中宰相贤，天下庶民富；万里河清，五谷成熟；户户安居，处处乐土；凤凰来仪，麒麟屡出。
[清江引]谢当今盛明唐主，敕赐为夫妇。永老无别离，万古常完聚，愿普天下有情人的都成了眷属。
[随尾]则因月底联诗句，成就了怨女旷夫。显得有志的状元能，无情的郑恒苦。[下]', '', '', '', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec28adbb8b379ee09fd1f", "shortContent": "这四支曲是全剧结束前龙女琼莲所唱。张羽随石佛寺长老到了东海，有情人终得团圆。龙王被迫在龙宫为张羽和琼莲举办婚礼。这时东华上仙来到龙宫，说明张羽和琼莲原是天上瑶池的金童玉女，两人私下相爱，又羡慕人间而被谪罚下界，现在了却夙愿，应该重返仙位。这一套曲便是龙女此时所唱。\n将一对青年男女说成是金童玉女，前世因缘，看来又是俗不可耐的套子，它将剧中男女青年为实现美好愿望所做的努力淡化了，似乎一切都是命中所定。...", "authors": ["师", "飙"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572707687, '5dbd2ce317b54d006c7b721e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643572, '资治通鉴 · 卷一 · 周纪一', NULL, 17, 1577, 3, 1, '司马光', NULL, 10351, '57b9c6d179bc4400639cc661', '宋', 'wen', '文', '资治通鉴', '', '起著雍摄提格，尽玄黓困敦，凡三十五年。
威烈王二十三年（戊寅，公元前四零三年）
初命晋大夫魏斯、赵籍、韩虔为诸侯。
臣光曰：臣闻天子之职莫大于礼，礼莫大于分，分莫大于名。何谓礼？纪纲是也；何谓分？君臣是也；何谓名？公、侯、卿、大夫是也。夫以四海之广，兆民之众，受制于一人，虽有绝伦之力，高世之智，莫敢不奔走而服役者，岂非以礼为之纲纪哉！是故天子统三公，三公率诸侯，诸侯制卿大夫，卿大夫治士庶人。贵以临贱，贱以承贵。上之使下，犹心腹之运手足，根本之制支叶；下之事上，犹手足之卫心腹，支叶之庇本根。然后能上下相保而国家治安。故曰：天子之职莫大于礼也。
文王序《易》，以乾坤为首。孔子系之曰：“天尊地卑，乾坤定矣，卑高以陈，贵贱位矣。”言君臣之位，犹天地之不可易也。《春秋》抑诸侯，尊周室，王人虽微，序于诸侯之上，以是见圣人于君臣之际，未尝不惓惓也。非有桀、纣之暴，汤、武之仁，人归之，天命之，君臣之分，当守节伏死而已矣。是故以微子而代纣，则成汤配天矣；以季札而君吴，则太伯血食矣。然二子宁亡国而不为者，诚以礼之大节不可乱也。故曰：礼莫大于分也。
夫礼，辨贵贱，序亲疏，裁群物，制庶事。非名不著，非器不形。名以命之，器以别之，然后上下粲然有伦，此礼之大经也。名器既亡，则礼安得独在哉？昔仲叔于奚有功于卫，辞邑而请繁缨，孔子以为不如多与之邑。惟器与名，不可以假人，君之所司也。政亡，则国家从之。卫君待孔子而为政，孔子欲先正名，以为名不正则民无所措手足。夫繁缨，小物也，而孔子惜之；正名，细务也，而孔子先之。诚以名器既乱，则上下无以相有故也。夫事未有不生于微而成于著。圣人之虑远，故能谨其微而治之；众人之识近，故必待其著而后救之。治其微，则用力寡而功多；救其著，则竭力而不能及也。《易》曰：“履霜，坚冰至”，《书》曰：“一日二日万几”，谓此类也。故曰：分莫大于名也。
呜呼！幽、厉失德，周道日衰，纲纪散坏，下陵上替，诸侯专征，大夫擅政。礼之大体，什丧七八矣。然文、武之祀犹绵绵相属者，盖以周之子孙尚能守其名分故也。何以言之？昔晋文公有大功于王室，请隧于襄王，襄王不许，曰：“王章也。未有代德而有二王，亦叔父之所恶也。不然，叔父有地而隧，又何请焉！”文公于是乎惧而不敢违。是故以周之地则不大于曹、滕，以周之民则不众于邾、莒，然历数百年，宗主天下，虽以晋、楚、齐、秦之强，不敢加者，何哉？徒以名分尚存故也。至于季氏之于鲁，田常之于齐，白公之于楚，智伯之于晋，其势皆足以逐君而自为，然而卒不敢者，岂其力不足而心不忍哉？乃畏奸名犯分而天下共诛之也。今晋大夫暴蔑其君，剖分晋国，天子既不能讨，又宠秩之，使列于诸侯，是区区之名分复不能守而并弃之也。先王之礼于斯尽矣。或者以为当是之时，周室微弱，三晋强盛，虽欲勿许，其可得乎？是大不然。夫三晋虽强，苟不顾天下之诛而犯义侵礼，则不请于天子而自立矣。不请于天子而自立，则为悖逆之臣。天下苟有桓、文之君，必奉礼义而征之。今请于天子而天子许之，是受天子之命而为诸侯也，谁得而讨之！故三晋之列于诸侯，非三晋之坏礼，乃天子自坏之也。
呜呼！君臣之礼既坏矣，则天下以智力相雄长，遂使圣贤之后为诸侯者，社稷无不泯绝，生民之害糜灭几尽，岂不哀哉！
初，智宣子将以瑶为后。智果曰：“不如宵也。瑶之贤于人者五，其不逮者一也。美鬓长大则贤，射御足力则贤，伎艺毕给则贤，巧文辩慧则贤，强毅果敢则贤，如是而甚不仁。夫以其五贤陵人，而以不仁行之，其谁能待之？若果立瑶也，智宗必灭。”弗听，智果别族于太史为辅氏。赵简子之子，长曰伯鲁，幼曰无恤。将置后，不知所立。乃书训戒之辞于二简，以授二子曰：“谨识之。”三年而问之，伯鲁不能举其辞，求其简，已失之矣。问无恤，诵其辞甚习，求其简，出诸袖中而奏之。于是简子以无恤为贤，立以为后。简子使尹鐸为晋阳。请曰：“以为茧丝乎？抑为保障乎？”简子曰：“保障哉！”尹鐸损其户数。简子谓无恤曰：“晋国有难，而无以尹鐸为少，无以晋阳为远，必以为归。”及智宣子卒，智襄子为政，与韩康子、魏桓子宴于蓝台。智伯戏康子而侮段规，智国闻之，谏曰：“主不备，难必至矣！”智伯曰：“难将由我。我不为难，谁敢兴之？”对曰：“不然。《夏书》有之曰：‘一人三失，怨岂在明，不见是图。’夫君子能勤小物，故无大患。今主一宴而耻人之君相，又弗备，曰不敢兴难，无乃不可乎！蜹、蚁、蜂、虿，皆能害人，况君相乎！”弗听。
智伯请地于韩康子，康子欲弗与。段规曰：“智伯好利而愎，不与，将伐我；不如与之。彼狃于得地，必请于他人；他人不与，必向之以兵。然则我得免于患而待事之变矣。”康子曰：“善。”使使者致万家之邑于智伯，智伯悦。又求地于魏桓子，桓子欲弗与。任章曰：“何故弗与？”桓子曰：“无故索地，故弗与。”任章曰：“无故索地，诸大夫必惧；吾与之地，智伯必骄。彼骄而轻敌，此惧而相亲。以相亲之兵待轻敌之人，智氏之命必不长矣。《周书》曰：‘将欲败之，必姑辅之；将欲取之，必姑与之。’主不如与之以骄智伯，然后可以择交而图智氏矣。奈何独以吾为智氏质乎！”桓子曰：“善。”复与之万家之邑一。智伯又求蔡、皋狼之地于赵襄子，襄子弗与。智伯怒，帅韩、魏之甲以攻赵氏。襄子将出，曰：“吾何走乎？”从者曰：“长子近，且城厚完。”襄子曰：“民罢力以完之，又毙死以守之，其谁与我！”从者曰：“邯郸之仓库实。”襄子曰：“浚民之膏泽以实之，又因而杀之，其谁与我！其晋阳乎，先主之所属也，尹鐸之所宽也，民必和矣。”乃走晋阳。
三家以国人围而灌之，城不浸者三版。沈灶产蛙，民无叛意。智伯行水，魏桓子御，韩康子骖乘。智伯曰：“吾乃今知水可以亡人国也。”桓子肘康子，康子履桓子之跗，以汾水可以灌安邑，绛水可以灌平阳也。絺疵谓智伯曰：“韩、魏必反矣。”智伯曰：“子何以知之？”絺疵曰：“以人事知之。夫从韩、魏之兵以攻赵，赵亡，难必及韩、魏矣。今约胜赵而三分其地，城不没者三版，人马相食，城降有日，而二子无喜志，有忧色，是非反而何？”明日，智伯以絺疵之言告二子，二子曰：“此夫谗臣欲为赵氏游说，使主疑于二家而懈于攻赵氏也。不然，夫二家岂不利朝夕分赵氏之田，而欲为危难不可成之事乎？”二子出，絺疵入曰：“主何以臣之言告二子也？”智伯曰：“子何以知之？”对曰：“臣见其视臣端而趋疾，知臣得其情故也。”智伯不悛。絺疵请使于齐。
赵襄子使张孟谈潜出见二子，曰：“臣闻唇亡则齿寒。今智伯帅韩、魏而攻赵，赵亡则韩、魏为之次矣。”二子曰：“我心知其然也，恐事末遂而谋泄，则祸立至矣”。张孟谈曰：“谋出二主之口，入臣之耳，何伤也？”二子乃阴与张孟谈约，为之期日而遣之。襄子夜使人杀守堤之吏，而决水灌智伯军。智伯军救水而乱，韩、魏翼而击之，襄子将卒犯其前，大败智伯之众。遂杀智伯，尽灭智氏之族。唯辅果在。
臣光曰：智伯之亡也，才胜德也。夫才与德异，而世俗莫之能辨，通谓之贤，此其所以失人也。夫聪察强毅之谓才，正直中和之谓德。才者，德之资也；德者，才之帅也。云梦之竹，天下之劲也，然而不矫揉，不羽括，则不能以入坚；棠溪之金，天下之利也，然而不熔范，不砥砺，则不能以击强。是故才德全尽谓之圣人，才德兼亡谓之愚人，德胜才谓之君子，才胜德谓之小人。凡取人之术，苟不得圣人、君子而与之，与其得小人，不若得愚人。何则？君子挟才以为善，小人挟才以为恶。挟才以为善者，善无不至矣；挟才以为恶者，恶亦无不至矣。愚者虽欲为不善，智不能周，力不能胜，譬之乳狗搏人，人得而制之。小人智足以遂其奸，勇足以决其暴，是虎而翼者也，其为害岂不多哉！夫德者人之所严，而才者人之所爱。爱者易亲，严者易疏，是以察者多蔽于才而遗于德。自古昔以来，国之乱臣，家之败子，才有馀而德不足，以至于颠覆者多矣，岂特智伯哉！故为国为家者，苟能审于才德之分而知所先后，又何失人之足患哉！
三家分智氏之田。赵襄子漆智伯之头，以为饮器。智伯之臣豫让欲为之报仇，乃诈为刑人，挟匕首，入襄子宫中涂厕。襄子如厕心动，索之，获豫让。左右欲杀之，襄子曰：“智伯死无后，而此人欲为报仇，真义士也！吾谨避之耳。”乃舍之。豫让又漆身为癞，吞炭为哑，行乞于市，其妻不识也。行见其友，其友识之，为之泣曰：“以子之才，臣事赵孟，必得近幸。子乃为所欲为，顾不易邪？何乃自苦如此！求以报仇，不亦难乎？”豫让曰：“不可！既已委质为臣，而又求杀之，是二心也。凡吾所为者，极难耳。然所以为此者，将以愧天下后世之为人臣怀二心者也。”襄子出，豫让伏于桥下。襄子至桥，马惊，索之，得豫让，遂杀之。襄子为伯鲁之不立也，有子五人，不肯置后。封伯鲁之子于代，曰代成君，早卒，立其子浣为赵氏后。襄子卒，弟桓子逐浣而自立，一年卒。赵氏之人曰：“桓子立，非襄主意。”乃共杀其子，复迎浣而立之，是为献子。献子生籍，是为烈侯。魏斯者，桓子之孙也，是为文侯。韩康子生武子，武子生虔，是为景侯。
魏文侯以卜子夏、田子方为师，每过段干木之庐必式。四方贤士多归之。文侯与群臣饮酒，乐，而天雨，命驾将适野。左右曰：“今日饮酒乐，天又雨，君将安之？”文侯曰：“吾与虞人期猎，虽乐，岂可无一会期哉！”乃往，身自罢之。韩借师于魏以伐赵。文侯曰：“寡人与赵，兄弟也，不敢闻命。”赵借师于魏以伐韩，文侯应之亦然。二国皆怒而去。已而知文侯以讲于己也，皆朝于魏。魏由是始大于三晋，诸侯莫能与之争。使乐羊伐中山，克之，以封其子击。文侯问于群臣曰：“我何如主？”皆曰：“仁君。”任座曰：“君得中山，不以封君之弟而以封君之子，何谓仁君？”文侯怒，任座趋出。次问翟璜，对曰：“仁君也。”文侯曰：“何以知之？”对曰：“臣闻君仁则臣直。向者任座之言直，臣是以知之。”文侯悦，使翟璜召任座而反之，亲下堂迎之，以为上客。文侯与田子方饮，文侯曰：“钟声不比乎？左高。”田子方笑。文侯曰：“何笑？”子方曰：“臣闻之，君明乐官，不明乐音。今君审于音，臣恐其聋于官也。”文侯曰：“善。”子击出，遭田子方于道，下车伏谒。子方不为礼。子击怒，谓子方曰：“富贵者骄人乎？贫贱者骄人乎？”子方曰：“亦贫贱者骄人耳，富贵者安敢骄人？国君而骄人则失其国，大夫而骄人则失其家。失其国者未闻有以国待之者也，失其家者未闻有以家待之者也。夫士贫贱者，言不用，行不合，则纳履而去耳，安往而不得贫贱哉！”子击乃谢之。文侯谓李克曰：“先生尝有言曰：‘家贫思良妻，国乱思良相。’今所置非成则璜，二子何如？”对曰：“卑不谋尊，疏不谋戚。臣在阙门之外，不敢当命。”文侯曰：“先生临事勿让。”克曰：“君弗察故也。居视其所亲，富视其所与，达视其所举，穷视其所不为，贫视其所不取，五者足以定之矣，何待克哉！”文侯曰：“先生就舍，吾之相定矣。”李克出，见翟璜。翟璜曰：“今者闻君召先生而卜相，果谁为之？”克曰：“魏成。”翟璜忿然作色曰：“西河守吴起，臣所进也；君内以鄴为忧，臣进西门豹；君欲伐中山，臣进乐羊；中山已拔，无使守之，臣进先生；君之子无傅，臣进屈侯鲋。以耳目之所睹记，臣何负于魏成？”李克曰：“子之言克于子之君者，岂将比周以求大官哉？君问相于克，克之对如是。所以知君之必相魏成者，魏成食禄千钟，什九在外，什一在内，是以东得卜子夏、田子方、段干木。此三人者，君皆师之；子所进五人者，君皆臣之。子恶得与魏成比也！”翟璜逡巡再拜曰：“璜，鄙人也，失对，愿卒为弟子。”
吴起者，卫人，仕于鲁。齐人伐鲁，鲁人欲以为将，起取齐女为妻，鲁人疑之，起杀妻以求将，大破齐师。或谮之鲁侯曰：“起始事曾参，母死不奔丧，曾参绝之。今又杀妻以求为君将。起，残忍薄行人也。且以鲁国区区而有胜敌之名，则诸侯图鲁矣。”起恐得罪。闻魏文侯贤，乃往归之。文侯问诸李克，李克曰：“起贪而好色，然用兵，司马穰苴弗能过也。”于是文侯以为将，击秦，拔五城。起之为将，与士卒最下者同衣食，卧不设席，行不骑乘，亲裹赢粮，与士卒分劳苦。卒有病疽者，起为吮之。卒母闻而哭之。人曰：“子，卒也，而将军自吮其疽，何哭为？”母曰：“非然也。往年吴公吮其父，其父战不还踵，遂死于敌。吴公今又吮其子，妾不知其死所矣，是以哭之。”
燕湣公薨，子僖公立。
威烈王二十四年（己卯，公元前四零二年）
王崩，子安王骄立。
盗杀楚声王，国人立其子悼王。
安王
威烈王元年（庚辰，公元前四零一年）
秦伐魏，至阳狐。
威烈王二年（辛巳，公元前四零零年）
魏、韩、赵伐楚，至桑丘。
郑围韩阳翟。
韩景侯薨，子烈侯取立。
赵烈侯薨，国人立其弟武侯。
秦简公薨，子惠公立。
威烈王三年（壬午，公元前三九九年）
王子定奔晋。
虢山崩，壅河。
威烈王四年（癸未，公元前三九八年）
楚围郑。郑人杀其相驷子阳。
威烈王五年（甲申，公元前三九七年）
日有食之。
三月，盗杀韩相侠累。侠累与濮阳严仲子有恶。仲子闻轵人聂政之勇，以黄金百镒为政母寿，欲因以报仇。政不受，曰：“老母在，政身未敢以许人也！”及母卒，仲子乃使政刺侠累。侠累方坐府上，兵卫甚众，聂政直入上阶，刺杀侠累，因自皮面抉眼，自屠出肠。韩人暴其尸于市，购问，莫能识。其姊嫈闻而往哭之，曰：“是轵深井里聂政也。以妾尚在之故，重自刑以绝从。妾奈何畏殁身之诛，终灭贤弟之名！”遂死于政尸之旁。
威烈王六年（乙酉，公元前三九六年）
郑驷子阳之党弑繻公，而立其弟乙，是为康公。
宋悼公薨，子休公田立。
威烈王八年（丁亥，公元前三九四年）
齐伐鲁，取最。韩救鲁。
郑负黍叛，复归韩。
威烈王九年（戊子，公元前三九三年）
魏伐郑。
晋烈公薨，子孝公倾立。
威烈王十一年（庚寅，公元前三九一年）
秦伐韩宜阳，取六邑。
初，田常生襄子盘，盘生庄子白，白生太公和。是岁，田和迁齐康公于海上，使食一城，以奉其先祀。
威烈王十二年（辛卯，公元前三九零年）
秦、晋战于武城。
齐伐魏，取襄阳。
鲁败齐师于平陆。
威烈王十三年（壬辰，公元前三八九年）
秦侵晋。
齐田和会魏文侯、楚人、卫人于浊泽，求为诸侯。魏文侯为之请于王及诸侯，王许之。
威烈王十五年（甲午，前三八七年）年
秦伐蜀，取南郑。
魏文侯薨，太子击立，是为武侯。
武侯浮西河而下，中流顾谓吴起曰：“美哉山河之固，此魏国之宝也！”对曰：“在德不在险。昔三苗氏，左洞庭，右彭蠡，德义不修，禹灭之；夏桀之居，左河济，右泰华，伊阙在其南，羊肠在其北，修政不仁，汤放之；商纣之国，左孟门，右太行，常山在其北，大河经其南，修政不德，武王杀之。由此观之，在德不在险。若君不修德，舟中之人皆敌国也。”武侯曰：“善。”魏置相，相田文。吴起不悦，谓田文曰：“请与子论功，可乎？”田文曰：“可。”起曰：“将三军，使士卒乐死，敌国不敢谋，子孰与起？”文曰：“不如子。”起曰：“治百官，亲万民，实府库，子孰与起？”文曰：“不如子。”起曰：“守西河而秦兵不敢东乡，韩、赵宾从，子孰与起？”文曰：“不如子。”起曰：“此三者子皆出吾下，而位加吾上，何也？”文曰：“主少国疑，大臣未附，百姓不信，方是之时，属之子乎，属之我乎？”起默然良久，曰：“属之子矣。”久之，魏相公叔尚魏公主而害吴起。公叔之仆曰：“起易去也。起为人刚劲自喜，子先言于君曰：‘吴起，贤人也，而君之国小，臣恐起之无留心也，君盍试延以女？起无留心，则必辞矣。’子因与起归而使公主辱子，起见公主之贱子也，必辞，则子之计中矣。”公叔从之，吴起果辞公主。魏武侯疑之而未信，起惧诛，遂奔楚。楚悼王素闻其贤，至则任之为相。起明法审令，捐不急之官，废公族疏远者，以抚养战斗之士，要在强兵，破游说之言从横者。于是南平百越，北却三晋，西伐秦，诸侯皆患楚之强，而楚之贵戚大臣多怨吴起者。
秦惠公薨，子出公立。
赵武侯薨，国人复立烈侯之太子章，是为敬侯。
韩烈侯薨，子文侯立。
威烈王十六年（乙未，公元前三八六年）
初命齐大夫田和为诸侯。
赵公子朝作乱，出奔魏，与魏袭邯郸，不克。
威烈王十七年（丙申，公元前三八五年）
秦庶长改逆献公于河西而立之；杀出子及其母，沉之渊旁。
齐伐鲁。
韩伐郑，取阳城；伐宋，执宋公。
齐太公薨，子桓公午立。
威烈王十九年（戊戌，公元前三八三年）
魏败赵师于兔台。
威烈王二十年（己亥，公元前三八二年）
日有食之，既。
威烈王二十一年（庚子，公元前三八一年）
楚悼王薨，贵戚大臣作乱，攻吴起，起走之王尸而伏之。击起之徒因射刺起，并中王尸。既葬，肃王即位。使令尹尽诛为乱者，坐起夷宗者七十馀家。
威烈王二十二年（辛丑，公元前三八零年）
齐伐燕，取桑丘。魏、韩、赵伐齐，至桑丘。
威烈王二十三年（壬寅，公元前三七九年）
赵袭卫，不克。
齐康公薨，无子，田氏遂并齐而有之。
是岁，齐桓公亦薨，子威王因齐立。
威烈王二十四年（癸卯，公元前三七八年）
狄败魏师于浍。
魏、韩、赵伐齐，至灵丘。
晋孝公薨，子靖公俱酒立。
威烈王二十五年（甲辰，公元前三七七年）
蜀伐楚，取兹方。
子思言苟变于卫侯曰：“其材可将五百乘。”公曰：“吾知其可将。然变也尝为吏，赋于民而食人二鸡子，故弗用也。”子思曰：“夫圣人之官人，犹匠之用木也，取其所长，弃其所短。故杞梓连抱而有数尺之朽，良工不弃。今君处战国之世，选爪牙之士，而以二卵弃干城之将，此不可使闻于邻国也。”公再拜曰：“谨受教矣。”卫侯言计非是，而群臣和者如出一口。子思曰：“以吾观卫，所谓‘君不君，臣不臣’者也。”公丘懿子曰：“何乃若是？”子思曰：“人主自臧，则众谋不进。事是而臧之，犹却众谋，况和非以长恶乎！夫不察事之是非而悦人赞己，暗莫甚焉；不度理之所在而阿谀求容，谄莫甚焉。君暗臣谄，以居百姓之上，民不与也。若引不已，国无类矣！”子思言于卫侯曰：“君之国事将日非矣！”公曰：“何故？”对曰：“有由然焉。君出言自以为是，而卿大夫莫敢矫其非；卿大夫出言亦自以为是，而士庶人莫敢矫其非。君臣既自贤矣，而群下同声贤之，贤之则顺而有福，矫之则逆而有祸，如此则善安从生！《诗》曰：‘具曰予圣，谁知乌之雌雄？’抑亦似君之君臣乎？”
鲁穆公薨，子共公奋立。
韩文侯薨，子哀侯立。
威烈王二十六年（乙巳，公元前三七六年）
王崩，子烈王喜立。魏、韩、赵共废晋靖公为家人而分其地。
烈王
威烈王元年（丙午，公元前三七五年）
日有食之。
韩灭郑，因徒都之。
赵敬侯薨，子成侯种立。
威烈王三年（戊申，公元前三七三年）
燕败齐师于林狐。
鲁伐齐，入阳关。
魏伐齐，至博陵。
燕僖公薨，子辟公立。
宋休公薨，子桓公立。
卫慎公薨，子声公训立。
威烈王四年（己酉，公元前三七二年）
赵伐卫，取都鄙七十三。
魏败赵师于北蔺。
威烈王五年（庚戌，公元前三七一年）
魏伐楚，取鲁阳。
韩严遂弑哀侯，国人立其子懿侯。初，哀侯以韩廆为相而爱严遂，二人甚相害也。严遂令人刺韩廆于朝，廆走哀侯，哀侯抱之。人刺韩廆，兼及哀侯。
魏武侯薨，不立太子，子罃与公中缓争立，国内乱。
威烈王六年（辛亥，公元前三七零年）
齐威王来朝。是时周室微弱，诸侯莫朝，而齐独朝之，天下以此益贤威王。
赵伐齐，至鄄。
魏败赵师于怀。
齐威王召即墨大夫，语之曰：“自子之居即墨也，毁言日至。然吾使人视即墨，田野辟，人民给，官无事，东方以宁。是子不事吾左右以求助也。”封之万家。召阿大夫，语之曰：“自子守阿，誉言日至。吾使人视阿，田野不辟，人民贫馁。昔日赵攻鄄，子不救；卫取薛陵，子不知。是子厚币事吾左右以求誉也。”是日，烹阿大夫及左右尝誉者。于是群臣耸惧，莫敢饰诈，务尽其情，齐国大治，强于天下。
楚肃王薨，无子，立其弟良夫，是为宣王。
宋辟公薨，子剔成立。
威烈王七年（壬子，公元前三六九年）
日有食之。
王崩，弟扁立，是为显王。
魏大夫王错出奔韩。公孙颀谓韩懿侯曰：“魏乱，可取也。”懿侯乃与赵成侯合兵伐魏，战于浊泽，大破之，遂围魏。成侯曰：“殺罃，立公中缓，割地而退，我二国之利也。”懿侯曰：“不可。杀魏君，暴也；割地而退，贪也。不如两分之。魏分为两，不强于宋、卫，则我终无魏患矣。”赵人不听。懿侯不悦，以其兵夜去。赵成侯亦去。遂杀公中缓而立，是为惠王。
太史公曰：魏惠王之所以身不死，国不分者，二国之谋不和也。若从一家之谋，魏必分矣。故曰：“君终，无适子，其国可破也。”', '', '', '周威烈王二十三年（戊寅，公元前403年）
周威烈王姬午初次分封晋国大夫魏斯、赵籍、韩虔为诸侯国君。
臣司马光曰：我知道天子的职责中最重要的是维护礼教，礼教中最重要的是区分地位，区分地位中最重要的是匡正名分。什么是礼教？就是法纪。什么是区分地位？就是君臣有别。什么是名分？就是公、侯、卿、大夫等官爵。
四海之广，亿民之众，都受制于天子一人。尽管是才能超群、智慧绝伦的人，也不能不在天子足下为他奔走服务，这难道不是以礼作为礼纪朝纲的作用吗！所以，天子统率三公，三公督率诸侯国君，诸侯国君节制卿、大夫官员，卿、大夫官员又统治士人百姓。权贵支配贱民，贱民服从权贵。上层指挥下层就好像人的心腹控制四肢行动，树木的根和干支配枝和叶；下层服侍上层就好像人的四肢卫护心腹，树木的枝和叶遮护根和干，这样才能上下层互相保护，从而使国家得到长治久安。所以说，天子的职责没有比维护礼制更重要的了。
周文王演绎排列《易经》，以乾、坤为首位。孔子解释说：“天尊贵，地卑微，阳阴于是确定。由低至高排列有序，贵贱也就各得其位。”这是说君主和臣子之间的上下关系就像天和地一样不能互易。《春秋》一书贬低诸侯，尊崇周王室，尽管周王室的官吏地位不高，在书中排列顺序仍在诸侯国君之上，由此可见孔圣人对于君臣关系的关注。如果不是夏桀、商纣那样的暴虐昏君，对手又遇上商汤、周武王这样的仁德明主，使人民归心、上天赐命的话，君臣之间的名分只能是作臣子的恪守臣节，矢死不渝。所以如果商朝立贤明的微子为国君来取代纣王，成汤创立的商朝就可以永配上天；而吴国如果以仁德的季札做君主，开国之君太伯也可以永享祭祀。然而微子、季札二人宁肯国家灭亡也不愿做君主，实在是因为礼教的大节绝不可因此破坏。所以说，礼教中最重要的就是地位高下的区分。
所谓礼教，在于分辨贵贱，排比亲疏，裁决万物，处理日常事物。没有一定的名位，就不能显扬；没有器物，就不能表现。只有用名位来分别称呼，用器物来分别标志，然后上下才能井然有序。这就是礼教的根本所在。如果名位、器物都没有了，那么礼教又怎么能单独存在呢！当年仲叔于奚为卫国建立了大功，他谢绝了赏赐的封地，却请求允许他享用贵族才应有的马饰。孔子认为不如多赏赐他一些封地，惟独名位和器物，绝不能假与他人，这是君王的职权象征；处理政事不坚持原则，国家也就会随着走向危亡。卫国国君期待孔子为他崐处理政事，孔子却先要确立名位，认为名位不正则百姓无所是从。马饰，是一种小器物，而孔子却珍惜它的价值；正名位，是一件小事情，而孔子却要先从它做起，就是因为名位、器物一紊乱，国家上下就无法相安互保。没有一件事情不是从微小之处产生而逐渐发展显著的，圣贤考虑久远，所以能够谨慎对待微小的变故及时予以处理；常人见识短浅，所以必等弊端闹大才来设法挽救。矫正初起的小错，用力小而收效大；挽救已明显的大害，往往是竭尽了全力也不能成功。《易经》说：“行于霜上而知严寒冰冻将至。”《尚书》说：“先王每天都要兢兢业业地处理成千上万件事情。”就是指这类防微杜渐的例子。所以说，区分地位高下最重要的是匡正各个等级的名分。
呜呼！周幽王、周厉王丧失君德，周朝的气数每况愈下。礼纪朝纲土崩瓦解；下欺凌、上衰败；诸侯国君恣意征讨他人；士大夫擅自干预朝政；礼教从总体上已经有十之七八沦丧了。然而周文王、周武王开创的政权还能绵绵不断地延续下来，就是因为周王朝的子孙后裔尚能守定名位。为什么这样说呢？当年晋文公为周朝建立了大功，于是向周襄王请求允许他死后享用王室的隧葬礼制，周襄王没有准许，说：“周王制度明显。没有改朝换代而有两个天子，这也是作为叔父辈的晋文公您所反对的。不然的话，叔父您有地，愿意隧葬，又何必请示我呢？”晋文公于是感到畏惧而没有敢违反礼制。因此，周王室的地盘并不比曹国、滕国大，管辖的臣民也不比邾国、莒国多，然而经过几百年，仍然是天下的宗主，即使是晋、楚、齐、秦那样的强国也还不敢凌驾于其上，这是为什么呢？只是由于周王还保有天子的名分。再看看鲁国的大夫季氏、齐国的田常、楚国的白公胜、晋国的智伯，他们的势力都大得足以驱逐国君而自立，然而他们到底不敢这样做，难道是他们力量不足或是于心不忍吗？只不过是害怕奸夺名位僭犯身分而招致天下的讨伐罢了。现在晋国的三家大夫欺凌蔑视国君，瓜分了晋国，作为天子的周王不能派兵征讨，反而对他们加封赐爵，让他们列位于诸侯国君之中，这样做就使周王朝仅有的一点名分不能再守定而全部放弃了。周朝先王的礼教到此丧失干净！
有人认为当时周王室已经衰微，而晋国三家力量强盛，就算周王不想承认他们，又怎么能做得到呢！这种说法是完全错误的。晋国三家虽然强悍，但他们如果打算不顾天下的指责而公然侵犯礼义的话，就不会来请求周天子的批准，而是去自立为君了。不向天子请封而自立为国君，那就是叛逆之臣，天下如果有像齐桓公、晋文公那样的贤德诸侯，一定会尊奉礼义对他们进行征讨。现在晋国三家向天子请封，天子又批准了。他们就是奉天子命令而成为诸侯的，谁又能对他们加以讨伐呢！所以晋国三家大夫成为诸侯，并不是晋国三家破坏了礼教，正是周天子自已破坏了周朝的礼教啊！
呜呼！君臣之间的礼纪既然崩坏，于是天下便开始以智慧、武力互相争雄，使当年受周先王分封而成为诸侯国君的圣贤后裔，江山相继沦亡，周朝先民的子孙灭亡殆尽，岂不哀伤！
当初，晋国的智宣子想以智瑶为继承人，族人智果说：“他不如智宵。智瑶有超越他人的五项长处，只有一项短处。美发高大是长处，精于骑射是长处，才艺双全是长处，能写善辩是长处，坚毅果敢是长处。虽然如此却很不仁厚。如果他以五项长处来制服别人而做不仁不义的恶事，谁能和他和睦相处？要是真的立智瑶为继承人，那么智氏宗族一定灭亡。”智宣子置之不理。智果便向太史请求脱离智族姓氏，另立为辅氏。
赵国的大夫赵简子的儿子，长子叫伯鲁，幼子叫无恤。赵简子想确定继承人，不知立哪位好，于是把他的日常训诫言词写在两块竹简上，分别交给两个儿子，嘱咐说：“好好记住！”过了三年，赵简子问起两个儿子，大儿子伯鲁说不出竹简上的话；再问他的竹简，已丢失了。又问小儿子无恤，竟然背诵竹简训词很熟习；追问竹简，他便从袖子中取出献上。于是，赵简子认为无恤十分贤德，便立他为继承人。
赵简子派尹铎去晋阳，临行前尹铎请示说：“您是打算让我去抽丝剥茧般地搜刮财富呢，还是作为保障之地？”赵简子说：“作为保障。”尹铎便少算居民户数，减轻赋税。赵简子又对儿子赵无恤说：“一旦晋国发生危难，你不要嫌尹铎地位不高，不要怕晋阳路途遥远，一定要以那里作为归宿。”
等到智宣子去世，智襄子智瑶当政，他与韩康子、魏桓子在蓝台饮宴，席间智瑶戏弄韩康子，又侮辱他的家相段规。智瑶的家臣智国听说此事，就告诫说：“主公您不提防招来灾祸，灾祸就一定会来了！”智瑶说：“人的生死灾祸都取决于我。我不给他们降临灾祸，谁还敢兴风作浪！”智国又说：“这话可不妥。《夏书》中说：‘一个人屡次三番犯错误，结下的仇怨岂能在明处，应该在它没有表现时就提防。’贤德的人能够谨慎地处理小事，所以不会招致大祸。现在主公一次宴会就开罪了人家的主君和臣相，又不戒备，说：‘不敢兴风作浪。’这种态度恐怕不行吧。蚊子、蚂蚁、蜜蜂、蝎子，都能害人，何况是国君、国相呢！”智瑶不听。
智瑶向韩康子要地，韩康子想不给。段规说：“智瑶贪财好利，又刚愎自用，如果不给，一定讨伐我们，不如姑且给他。他拿到地更加狂妄，一定又会向别人索要；别人不给，他必定向人动武用兵，这样我们就可以免于祸患而伺机行动了。”韩康子说：“好主意。”便派了使臣去送上有万户居民的领地。智瑶大喜，果然又向魏桓子提出索地要求，魏桓子想不给。家相任章问：“为崐什么不给呢？”魏桓子说：“无缘无故来要地，所以不给。”任章说：“智瑶无缘无故强索他人领地，一定会引起其他大夫官员的警惧；我们给智瑶地，他一定会骄傲。他骄傲而轻敌，我们警惧而互相亲善；用精诚团结之兵来对付狂妄轻敌的智瑶，智家的命运一定不会长久了。《周书》说：‘要打败敌人，必须暂时听从他；要夺取敌人利益，必须先给他一些好处。’主公不如先答应智瑶的要求，让他骄傲自大，然后我们可以选择盟友共同图谋，又何必单独以我们作智瑶的靶子呢！”魏桓子说：“对。”也交给智瑶一个有万户的封地。
智瑶又向赵襄子要蔡和皋狼的地方。赵襄子拒绝不给。智瑶勃然大怒，率领韩、魏两家甲兵前去攻打赵家。赵襄子准备出逃。问：“我到哪里去呢？”随从说：“长子城最近，而且城墙坚厚又完整。”赵襄子说：“百姓精疲力尽地修完城墙，又要他们舍生入死地为我守城，谁能和我同心？”随从又说：“邯郸城里仓库充实。”赵襄子说：“搜刮民脂民膏才使仓库充实，现在又因战争让他们送命，谁会和我同心。还是投奔晋阳吧，那是先主的地盘，尹铎又待百姓宽厚，人民一定能同我们和衷共济。”于是前往晋阳。
智瑶、韩康子、魏桓子三家围住晋阳，引水灌城。城墙头只差三版的地方没有被淹没，锅灶都被泡塌，青蛙孳生，人民仍是没有背叛之意。智瑶巡视水势，魏桓子为他驾车，韩康子站在右边护卫。智瑶说：“我今天才知道水可以让人亡国。”魏桓子用胳膊肘碰了一下韩康子，韩康子也踩了一下魏桓子脚。因为汾水可以灌魏国都城安邑，绛水也可以灌韩国都城平阳。智家的谋士疵对智瑶说：“韩、魏两家肯定会反叛。”智瑶问：“你何以知道？”疵说：“以人之常情而论。我们调集韩、魏两家的军队来围攻赵家，赵家覆亡，下次灾难一定是连及韩、魏两家了。现在我们约定灭掉赵家后三家分割其地，晋阳城仅差三版就被水淹没，城内宰马为食，破城已是指日可待。然而韩康子、魏桓子两人没有高兴的心情，反倒面有忧色，这不是必反又是什么？”第二天，智瑶把疵的话告诉了韩、魏二人，二人说：“这一定是离间小人想为赵家游说，让主公您怀疑我们韩、魏两家而放松对赵家的进攻。不然的话，我们两家岂不是放着早晚就分到手的赵家田土不要，而要去干那危险必不可成的事吗？”两人出去，疵进来说：“主公为什么把臣下我的话告诉他们两人呢？”智瑶惊奇地反问：“你怎么知道的？”回答说：“我见他们认真看我而匆忙离去，因为他们知道我看穿了他们的心思。”智瑶不改。于是疵请求让他出使齐国。
赵襄子派张孟谈秘密出城来见韩、魏二人，说：“我听说唇亡齿寒。现在智瑶率领韩、魏两家来围攻赵家，赵家灭亡就该轮到韩、魏了。”韩康子、魏崐桓子也说：“我们心里也知道会这样，只怕事情还未办好而计谋先泄露出去，就会马上大祸临头。”张孟谈又说：“计谋出自二位主公之口，进入我一人耳朵，有何伤害呢？”于是两人秘密地与张孟谈商议，约好起事日期后送他回城了。夜里，赵襄子派人杀掉智军守堤官吏，使大水决口反灌智瑶军营。智瑶军队为救水淹而大乱，韩、魏两家军队乘机从两翼夹击，赵襄子率士兵从正面迎头痛击，大败智家军，于是杀死智瑶，又将智家族人尽行诛灭。只有辅果得以幸免。
臣司马光曰：智瑶的灭亡，在于才胜过德。才与德是不同的两回事，而世俗之人往往分不清，一概而论之曰贤明，于是就看错了人。所谓才，是指聪明、明察、坚强、果毅；所谓德，是指正直、公道、平和待人。才，是德的辅助；德，是才的统帅。云梦地方的竹子，天下都称为刚劲，然而如果不矫正其曲，不配上羽毛，就不能作为利箭穿透坚物。棠地方出产的铜材，天下都称为精利，然而如果不经熔烧铸造，不锻打出锋，就不能作为兵器击穿硬甲。所以，德才兼备称之为圣人；无德无才称之为愚人；德胜过才称之为君子；才胜过德称之为小人。挑选人才的方法，如果找不到圣人、君子而委任，与其得到小人，不如得到愚人。原因何在？因为君子持有才干把它用到善事上；而小人持有才干用来作恶。持有才干作善事，能处处行善；而凭借才干作恶，就无恶不作了。愚人尽管想作恶，因为智慧不济，气力不胜任，好像小狗扑人，人还能制服它。而小人既有足够的阴谋诡计来发挥邪恶，又有足够的力量来逞凶施暴，就如恶虎生翼，他的危害难道不大吗！有德的人令人尊敬，有才的人使人喜爱；对喜爱的人容易宠信专任，对尊敬的人容易疏远，所以察选人才者经常被人的才干所蒙蔽而忘记了考察他的品德。自古至今，国家的乱臣奸佞，家族的败家浪子，因为才有余而德不足，导致家国覆亡的多了，又何止智瑶呢！所以治国治家者如果能审察才与德两种不同的标准，知道选择的先后，又何必担心失去人才呢！
赵、韩、魏三家瓜分智家的田土，赵襄子把智瑶的头骨涂上漆，作为饮具。智瑶的家臣豫让想为主公报仇，就化装为罪人，怀揣匕首，混到赵襄子的宫室中打扫厕所。赵襄子上厕所时，忽然心动不安，令人搜索，抓获了豫让。左右随从要将他杀死，赵襄子说：“智瑶已死无后人，而此人还要为他报仇，真是一个义士，我小心躲避他好了。”于是释放豫让。豫让用漆涂身，弄成一个癞疮病人，又吞下火炭，弄哑嗓音。在街市上乞讨，连结发妻子见面也认不出来。路上遇到朋友，朋友认出他，为他垂泪道：“以你的才干，如果投靠赵家，一定会成为亲信，那时你就为所欲为，不是易如反掌吗？何苦自残形体崐以至于此？这样来图谋报仇，不是太困难了吗！”豫让说：“我要是委身于赵家为臣，再去刺杀他，就是怀有二心。我现在这种做法，是极困难的。然而之所以还要这样做，就是为了让天下与后世做人臣子而怀有二心的人感到羞愧。”赵襄子乘车出行，豫让潜伏在桥下。赵襄子到了桥前，马突然受惊，进行搜索，捕获豫让，于是杀死他。
赵襄子因为赵简子没有立哥哥伯鲁为继承人，自己虽然有五个儿子，也不肯立为继承人。他封赵伯鲁的儿子于代国，称代成君，早逝；又立其子赵浣为赵家的继承人。赵襄子死后，弟弟赵桓子就驱逐赵浣，自立为国君，继位一年也死了。赵家的族人说：“赵桓子做国君本来就不是赵襄子的主意。”大家一起杀死了赵桓子的儿子，再迎回赵浣，拥立为国君，这就是赵献子。赵献子生子名赵籍，就是赵烈侯。魏斯，是魏桓子的孙子，就是魏文侯。韩康子生子名韩武子，武子又生韩虔，被封为韩景侯。
魏文侯魏斯以卜子夏、田子方为国师，他每次经过名士段干木的住宅，都要在车上俯首行礼。四方贤才德士很多前来归附他。
魏文侯与群臣饮酒，奏乐间，下起了大雨，魏文侯却下令备车前往山野之中。左右侍臣问：“今天饮酒正乐，外面又下着大雨，国君打算到哪里去呢？”魏文侯说：“我与山野村长约好了去打猎，虽然这里很快乐，也不能不遵守约定！”于是前去，亲自告诉停猎。
韩国邀请魏国出兵攻打赵国。魏文侯说：“我与赵国，是兄弟之邦，不敢从命。”赵国也来向魏国借兵讨伐韩国，魏文侯仍然用同样的理由拒绝了。两国使者都怒气冲冲地离去。后来两国得知魏文侯对自己的和睦态度，都前来朝拜魏国。魏国于是开始成为魏、赵、韩三国之首，各诸侯国都不能和它争雄。
魏文侯派乐羊攻打中山国，予以攻克，封给自己的儿子魏击。魏文侯问群臣：“我是什么样的君主？”大家都说：“您是仁德的君主！”只有任座说：“国君您得了中山国，不用来封您的弟弟，却封给自己的儿子，这算什么仁德君主！”魏文侯勃然大怒，任座快步离开。魏文侯又问翟璜，翟璜回答说：“您是仁德君主。”魏文侯问：“你何以知道？”回答说：“臣下我听说国君仁德，他的臣子就敢直言。刚才任座的话很耿直，于是我知道您是仁德君主。”魏文侯大喜，派翟璜去追任座回来，还亲自下殿堂去迎接，奉为上客。
魏文侯与田子方饮酒，文侯说：“编钟的乐声不协调吗？左边高。”田子方笑了，魏文侯问：“你笑什么？”田子方说：“臣下我听说，国君懂得任用乐官，不必懂得乐音。现在国君您精通音乐，我担心您会疏忽了任用官员的职责。”魏文侯说：“对。”
魏文侯的公子魏击出行，途中遇见国师田子方，下车伏拜行礼。田子方却不作回礼。魏击怒气冲冲地对田子方说：“富贵的人能对人骄傲呢，还是贫贱的人能对人骄傲？”田子方说：“当然是贫贱的人能对人骄傲啦，富贵的人哪里敢对人骄傲呢！国君对人骄傲就将亡国，大夫对人骄傲就将失去采地。失去国家的人，没有听说有以国主对待他的；失去采地的人，也没有听说有以家主对待他的。贫贱的游士呢，话不听，行为不合意，就穿上鞋子告辞了，到哪里得不到贫贱呢！”魏击于是谢罪。
魏文侯问李克：“先生曾经说过：‘家贫思良妻，国乱思良相。’现在我选相不是魏成就是翟璜，这两人怎么样？”李克回答说：“下属不参与尊长的事，外人不过问亲戚的事。臣子我在朝外任职，不敢接受命令。”魏文侯说：“先生不要临事推让！”李克说道：“国君您没有仔细观察呀！看人，平时看他所亲近的，富贵时看他所交往的，显赫时看他所推荐的，穷困时看他所不做的，贫贱时看他所不取的。仅此五条，就足以去断定人，又何必要等我指明呢！”魏文侯说：“先生请回府吧，我的国相已经选定了。”李克离去，遇到翟璜。翟璜问：“听说今天国君召您去征求宰相人选，到底定了谁呢？”李克说：“魏成。”翟璜立刻忿忿不平地变了脸色，说：“西河守令吴起，是我推荐的。国君担心内地的邺县，我推荐西门豹。国君想征伐中山国，我推荐乐羊。中山国攻克之后，没有人去镇守，我推荐了先生您。国君的公子没有老师，我推荐了屈侯鲋。凭耳闻目睹的这些事实，我哪点儿比魏成差！”李克说：“你把我介绍给你的国君，难道是为了结党以谋求高官吗？国君问我宰相的人选，我说了刚才那一番话。我所以推断国君肯定会选中魏成为相，是因为魏成享有千钟的傣禄，十分之九都用在外面，只有十分之一留作家用，所以向东得到了卜子夏、田子方、段干木。这三个人，国君都奉他们为老师；而你所举荐的五人，国君都任用为臣属。你怎么能和魏成比呢！”翟璜听罢徘徊不敢进前，一再行礼说：“我翟璜，真是个粗人，失礼了，愿终身为您的弟子！”
吴起，卫国人，在鲁国任官。齐国攻打鲁国，鲁国想任用吴起为将，但吴起娶的妻子是齐国人，鲁国猜疑吴起。于是，吴起杀死了自己的妻子，求得大将，大破齐国军队。有人在鲁国国君面前攻击他说：“吴起当初曾师事曾参，母亲死了也不回去治丧，曾参与他断绝关系。现在他又杀死妻子来求得您的大将职位。吴起，真是一个残忍缺德的人！况且，以我们小小的鲁国能有战胜齐国的名气，各个国家都要来算计鲁国了。”吴起恐怕鲁国治他的罪，又听说魏文侯贤明，于是就前去投奔。魏文侯征求李克的意见，李克说：“吴起为人贪婪而好色，然而他的用兵之道，连齐国的名将司马穰苴也超不过他。”于是魏文侯崐任命吴起为大将，攻击秦国，攻占五座城。
吴起做大将，与最下等的士兵同样穿衣吃饭，睡觉不铺席子，行军也不骑马，亲自挑上士兵的粮食，与士兵们分担疾苦。有个士兵患了毒疮，吴起为他吸吮毒汁。士兵的母亲听说后却痛哭。有人奇怪地问：“你的儿子是个士兵，而吴起将军亲自为他吸吮毒疮，你为什么哭？”士兵母亲答道：“不是这样啊！当年吴将军为孩子的父亲吸过毒疮，他父亲作战从不后退，就战死在敌阵中了。吴将军现在又为我儿子吸毒疮，我不知道他该死在哪里了，所以哭他。”
燕公薨，子僖公立。
二十四年（己卯、前402）
王崩，子安王骄立。
盗杀楚声王，国人立其子悼王。
安王元年（庚辰、前401）
秦伐魏，至阳孤。
二年（辛巳、前400）
魏、韩、赵伐楚，至桑丘。
郑围韩阳翟。
韩景侯薨，子烈侯取立。
赵烈侯薨，国人立其弟武侯。
秦简公薨，子惠公立。
三年（壬午、前399）
王子定奔晋。
虢山崩，壅河。
四年（癸未、前398）
楚围郑。郑人杀其相驷子阳。
五年（甲申、前397）
日有食之。
三月，盗匪杀死韩国国相侠累。侠累与濮阳人严仲子有仇，严仲子听说轵地人聂政很勇敢，便拿出一百镒黄金为聂政母亲祝寿，想让聂政为他报仇。聂政却不接受，说：“我的老母亲还健在，我不敢为别人去献身！”等到他的母亲去世，严仲子便派聂政去行刺侠累。侠累正端坐府中，有许多护卫兵丁，聂政一直冲上厅阶，把侠累刺死。然后划破自己的面皮，挖出双眼，割出肚肠而死。韩国人把聂政的尸体放在集市中暴尸。并悬赏查找，但无人知晓。聂政的姐姐聂听说此事前往，哭着说：“这是轵地深井里的聂政啊！他因为我还在，就自毁面容不使连累。我怎么能怕杀身之祸，最终埋没我弟弟的英名呢！”于是自尽死在聂政的尸体旁边。
六年（乙酉，公元前396年）
郑国宰相驷子阳的余党杀死国君郑公，改立他的弟弟姬乙，是为郑康公。
宋国宋悼公去世，其子宋田即位，是为宋休公。
八年（丁亥，公元前394年）
齐国攻打鲁国，攻占最地。
郑国的负黍地方反叛，复归顺韩国。
九年（戊子，公元前393年）
魏国攻打郑国。
晋国晋烈公去世，其子姬倾即位，是为晋孝公。
十一年（庚寅，公元前391年）
秦国攻打韩国宜阳地方，夺取六个村邑。
起初，齐国田常生襄子田盘，田盘生庄子田白，田白再生太公田和。这年，田和把国君齐康公流放到海边，让他保有一个城的赋税收入，以承继祖先祭祀。
十二年（辛卯，公元前390年）
秦国与晋国大战于武城。
齐国攻打魏国，夺取襄阳。
鲁国在平陆击败齐国军队。
十三年（壬辰，公元前389年）
秦国入侵晋国。
齐国田和在浊泽约会魏文侯及楚国、卫国贵族，要求作诸侯。魏文侯替他向周安王及各国诸侯申请，周安王准许。
十五年（甲午，公元前387年）
秦国攻打蜀地，夺取南郑。
魏国魏文侯去世，太子魏击即位，是为魏武侯。
魏武侯顺黄河而下，在中游对吴起说：“稳固的山河真美啊！这是魏国的宝啊！”吴起回答说：“国宝在于德政而不在于地势险要。当初三苗氏部落，左面有洞庭湖，右面有彭蠡湖，但他们不修德义，被禹消灭了。夏朝君王桀的居住之地，左边是黄河、济水，右边是泰华山，伊阙山在其南面，羊肠阪在其北面，但因朝政不仁，也被商朝汤王驱逐了。商朝纣王的都城，左边是孟门，右边是太行山，常山在其北面，黄河经过其南面，因他施政不德，被周武王杀了。由此可见，国宝在于德政而不在于地势险要。如果君主您不修德政，恐怕就是这条船上的人，也要成为您的敌人。”魏武侯听罢说道：“对。”
魏国设置国相，任命田文为相。吴起不高兴，对田文说：“我和你比较功劳如何？”田文说：“可以。”吴起便说：“统率三军，使士兵乐于战死，敌国不敢谋算，你比我吴起如何？”田文说：“我不如你。”吴起又问：“整治百官，亲善百姓，使仓库充实，你比我吴起如何？”田文说：“我不如你。”吴起再问：“镇守西河，使秦兵不敢向东侵犯，韩国、赵国依附听命，你比我吴起如何？”田文还是说：“我不如你。”吴起质问道：“这三条你都在我之下，而职位却在我之上，是什么道理？”田文说：“如今国君年幼，国多疑难，大臣们不能齐心归附，老百姓不能信服，在这个时候，是嘱托给你呢，还是嘱托给我呢？”吴起默默不语想了一会儿，说：“嘱托给你啊！”
过了很久，魏国国相公叔娶公主为妻而以吴起为忌。他的仆人献计说：“吴起容易去掉，吴起为人刚劲而沾沾自喜。您可以先对国君说：‘吴起是个杰出人才，但君主您的国家小，我担心他没有长留的心思。国君您何不试着要把女儿嫁给他，如果吴起没有久留之心，一定会辞谢的。’主人您再与吴起一起回去，让公主羞辱您，吴起看到公主如此轻视您，一定会辞谢国君的婚事，这样您的计谋就实现了。”公叔照此去做，吴起果然辞谢了与公主的婚事。魏武侯疑忌他，不敢信任，吴起害怕被诛杀，于是投奔了楚国。
楚悼王平素听说吴起是个人才，到了便任命他为国相。吴起严明法纪号令，裁减一些不重要的闲官，废除了王族中远亲疏戚，用来安抚奖励征战之士，大力增强军队、破除合纵连横游说言论。于是楚国向南平定百越，向北抵挡住韩、魏、赵三国的扩张，向西征讨秦国，各诸侯国都害怕楚国的强大，而楚国的王亲贵戚、权臣显要中却有很多人怨恨吴起。
秦国秦惠公去世，其子即位，是为秦出公。
秦国秦惠公去世，其子即位，是为秦出公。*赵武侯薨，国人复立烈侯之太子章，是为敬侯。
赵国赵武侯去世，国中贵族又拥立赵烈侯的太子赵章即位，是为赵敬侯。
韩国韩烈侯去世，其子即位，是为韩文侯。
十六年（乙未，公元前386年）
周王朝开始任命齐国大夫田和为诸侯国君。
赵国公子赵朝作乱，出奔魏国，与魏国军队一起进袭赵国邯郸，未能攻克。
十七年（丙申，公元前385年）
秦国名叫改的庶长在河西迎接秦献公，立为国君；把秦出公和他的母亲杀死，沉在河里。
齐国攻打鲁国。
韩国攻打郑国，夺取阳城。又攻打宋国，捉住宋国国君。
齐国太公田和去世，其子田午即位，是为齐桓公。
十九年（戊戌，公元前383年）
魏国在兔台击败赵国军队。
二十年（己亥，公元前382年）
出现日全食。
二十一年（庚子，公元前381年）
楚悼王去世。贵族国戚和大臣作乱，攻打吴起，吴起逃到悼王尸体边，伏在上面。攻击吴起的暴徒用箭射吴起，并射中了悼王的尸体。办完葬事，楚肃王即位，命令楚相全数翦灭作乱者，因射吴起之事而被灭族的多达七十余家。
二十二年（辛丑，公元前380年）
齐国攻打燕国，夺取桑兵。魏、韩、赵三国攻打齐国，兵至桑丘。
二十三年（壬寅，公元前379年）
赵国袭击卫国，未能攻克。
流放的齐康公去世，没有儿子。田氏家族于是把姜氏的齐国全部兼并了。
当年，齐桓公也去世，其子田因齐即位，是为齐威王。
二十四年（癸卯，公元前378年）
魏、韩、赵伐齐，至灵丘。
晋孝公薨，子靖公俱酒立。
二十五年（甲辰、前377）
蜀人攻打楚国，夺取兹方。
孔，字子思，向卫国国君提起苟变说：“他的才能可统领五百辆车。”卫侯说：“我知道他是个将才，然而苟变做官吏的时候，有次征税吃了老百姓两个鸡蛋，所以我不用他。”孔说：“圣人选人任官，就好比木匠使用木料，取其所长，弃其所短；因此一根合抱的良木，只有几尺朽烂处，高明的工匠是不会扔掉它的。现在国君您处在战国纷争之世，正要收罗锋爪利牙的人才，却因为两个鸡蛋而舍弃了一员可守一城的大将，这事可不能让邻国知道啊！”卫侯一再拜谢说：“我接受你的指教。”
卫侯提出了一项不正确的计划，而大臣们却附和如出一口。孔说：“我看卫国，真是‘君不像君，臣不像臣’呀！”公丘懿子问道：“为什么竟会这样？”孔说：“君主自以为是，大家便不提出自己的意见。即使事情处理对了没有听取众议，也是排斥了众人的意见，更何况现在众人都附和错误见解而助长邪恶之风呢！不考察事情的是非而乐于让别人赞扬，是无比的昏暗；不判断事情是否有道理而一味阿谀奉承，是无比的谄媚。君主昏暗而臣下谄媚，这样居于百姓之上，老百姓是不会同意的。长期这样不改，国家就不象国家了。”
孔对卫侯说：“你的国家将要一天不如一天了。”卫侯问：“为什么？”回答说：“事出有因。国君你说话自以为是，卿大夫等官员没有人敢改正你的错误；于是他们也说话自以为是，士人百姓也不敢改正其误。君臣都自以为贤能，下属又同声称贤，称赞贤能则和顺而有福，指出错误则忤逆而有祸，这样，怎么会有好的结果！《诗经》说：‘都称道自己是圣贤，乌鸦雌雄谁能辨？’不也像你们这些君臣吗？”
鲁国鲁穆公去世，其子姬奋即位，是为鲁共公。
韩国韩文侯去世，其子即位，是为韩哀侯。
二十六年（乙巳、前376）
周安王去世，其子姬喜即位，是为周烈王。
魏、韩、赵三国一同把晋靖公废黜为平民，瓜分了他的残余领地。
烈王元年（丙午、前375）*周烈王元年（丙午，公元前375年）
出现日食。
韩国灭掉郑国，于是把国都迁到新郑。
赵国赵敬侯去世，其子赵种即位，是为赵成侯。
三年（戊申，公元前373年）
燕国在林狐击败齐国军队。
鲁国攻打齐国，进入阳关。
魏国攻打齐国，抵达博陵。
燕国燕僖公去世，其子即位，是为燕桓公。
宋国宋休公去世，其子即位，是为宋辟公。
卫国卫慎公去世，其子卫训即位，是为卫声公。
四年（己酉，公元前372年）
赵国攻打卫国，夺取七十三个村镇。
魏国在北蔺击败赵国军队。
五年（庚戌，公元前371年）
魏国攻打楚国，夺取鲁阳。
韩国严遂杀死韩哀侯，国中贵族立哀侯之子，是为韩懿侯。当初，韩哀侯曾任命韩为国相却宠爱严遂，两人互相仇恨至深。严遂派人在朝廷行刺韩，韩逃到韩哀侯身边，韩哀侯抱住他，刺客刺韩，连带韩哀侯也被刺死。
魏国魏武侯去世，没有立太子，他的儿子魏与公中缓争位，国内大乱。
六年（辛亥，公元前370年）
齐威王朝拜周烈王。当时周王室已十分衰弱，各诸侯国都不来朝拜，唯独齐王仍来朝拜，因此天下人愈发称赞齐威王贤德。
赵国攻打齐国，直至鄄地。
魏国在怀地击败赵国军队。
齐威王召见即墨大夫，对他说：“自从你到即墨任官，每天都有指责你的话传来。然而我派人去即墨察看，却是田土开辟整治，百姓丰足，官府无事，东方因而十分安定。于是我知道这是你不巴结我的左右内臣谋求内援的缘故。”便封赐即墨大夫享用一万户的俸禄。齐威王又召见阿地大夫，对他说：“自从你到阿地镇守，每天都有称赞你的好话传来。但我派人前去察看阿地，只见田地荒芜，百姓贫困饥饿。当初赵国攻打鄄地，你不救；卫国夺取薛陵，你不知道；于是我知道你用重金来买通我的左右近臣以求替你说好话！”当天，齐威王下令烹死阿地大夫及替他说好话的左右近臣。于是臣僚们毛骨耸然，不敢再弄虚假，都尽力做实事，齐国因此大治，成为天下最强盛的国家。
楚国楚肃王去世，他没有儿子，弟弟良夫即位，是为楚宣王。
宋国宋辟公去世，其子宋剔成即位。
七年（壬子，公元前369年）
出现日食。
周烈王去世，弟弟姬扁即位，是为周显王。
魏国大夫王错逃奔韩国。公孙颀对韩懿侯说：“魏国内乱，可以乘机攻取。”韩懿侯于是与赵成侯联合出兵攻打魏国，在浊泽地方交战，大败魏军，包围了魏国都城。赵成侯说：“杀掉魏，立公中缓为魏国国君，然后割地退兵，这对我们两国是有利的作法。”韩懿侯说：“不妥。杀死魏国国君，是强暴；割地后才退兵，是贪婪。不如让两人分别治理魏国，魏国分为两半，比宋国、卫国还不如，我们就再也不用担心魏国的威胁了。”赵成侯不同意。韩懿侯不高兴，率领他的军队乘夜离去。赵成侯也只好退兵归国。魏于是杀死公中缓即位，是为魏惠王。
太史公司马迁曰：魏惠王之所以能自身不死，国家不被瓜分，是由于韩、赵两国意见不和。如果按照其中一家的办法去做，魏国一定会被瓜分。所以说：“国君死时，无继承人，国家就会被击破。”', NULL, '', 'indent', 1572785644, '5dbe5a30f884af0073434f0f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643573, '资治通鉴 · 卷二 · 周纪二', NULL, 7, 1577, 1, 1, '司马光', NULL, 10351, '57b9c6d179bc4400639cc661', '宋', 'wen', '文', '资治通鉴', '', '起昭阳赤奋若，尽上章困敦，凡四十八年。
显王元年（癸丑，公元前三六八年）
齐伐魏，取观津。
赵侵齐，取长城。
显王三年（乙卯，公元前三六六年）
魏、韩会于宅阳。
秦败魏师、韩师于洛阳。
显王四年（丙辰，公元前三六五年）
魏伐宋。
显王五年（丁巳，公元前三六四年）
秦献公败三晋之师于石门，斩首六万。王赐以黼黻之服。
显王七年（己未，前三六二年）
魏败韩师、赵师于浍。秦、魏战于少梁，魏师败绩；获魏公孙痤。
卫声公薨，子成侯速立。
燕桓公薨，子文公立。
秦献公薨，子孝公立。孝公生二十一年矣。是时河、山以东强国六，淮、泗之间小国十馀，楚、魏与秦接界。魏筑长城，自郑滨洛以北有上郡；楚自汉中，南有巴、黔中；皆以夷翟遇秦，摈斥之，不得与中国之会盟。于是孝公发愤，布德修政，欲以强秦。
显王八年（庚申，公元前三六一年）
孝公令国中曰：“昔我穆公，自岐、雍之间修德行武，东平晋乱，以河为界，西霸戎翟，广地千里，天子致伯，诸侯毕贺，为后世开业甚光美。会往者厉、躁、简公、出子之不宁，国家内忧，未遑外事。三晋攻夺我先君河西地，丑莫大焉。献公即位，镇抚边境，徙治栎阳，且欲东伐，复穆公之故地，修穆公之政令。寡人思念先君之意，常痛于心。宾客群臣有能出奇计强秦者，吾且尊官，与之分土。”于是卫公孙鞅闻是令下，乃西入秦。公孙鞅者，卫之庶孙也，好刑名之学。事魏相公叔痤，痤知其贤，未及进。会病，魏惠王往问之曰：“公叔病如有不可讳，将奈社稷何？”公叔曰：“痤之中庶子卫鞅，年虽少，有奇才，愿君举国而听之！”王嘿然。公叔曰：“君即不听用鞅，必杀之，无令出境。”王许诺而去。公叔召鞅谢曰：“吾先君而后臣，故先为君谋，后以告子。子必速行矣！”鞅曰：“君不能用子之言任臣，又安能用子之言杀臣乎？”卒不去。王出，谓左右曰：“公叔病甚，悲乎！欲令寡人以国听卫鞅也，既又劝寡人杀之，岂不悖哉！”卫鞅既至秦，因嬖臣景监以求见孝公，说以富国强兵之术。公大悦，与议国事。
显王十年（壬戌，公元前三五九年）
卫鞅欲变法，秦人不悦。卫鞅言于秦孝公曰：“夫民不可与虑始，而可与乐成。论至德者不和于俗，成大功者不谋于众。是以圣人苟可以强国，不法其故。”甘龙曰：“不然。缘法而治者，吏习而民安之。”卫鞅曰：“常人安于故俗，学者溺于所闻，以此两者，居官守法可也，非所与论于法之外也。智者作法，愚者制焉；贤者更礼，不肖者拘焉。”公曰：“善。”以卫鞅为左庶长，卒定变法之令。令民为什伍而相收司、连坐，告奸者与斩敌首同赏，不告奸者与降敌同罚。有军功者，各以率受上爵。为私斗者，各以轻重被刑大小。僇力本业，耕织致粟帛多者，复其身。事末利及怠而贫者，举以为收孥。宗室非有军功论，不得为属籍。明尊卑爵秩等级，各以差次名田宅、臣妾、衣服。有功者显荣，无功者虽富无所芬华。令既具未布，恐民之不信，乃立三丈之木于国都市南门，募民有能徙置北门者予十金。民怪之，莫敢徙。复曰：“能徙者予五十金！”有一人徙之，辄予五十金。乃下令。令行期年，秦民之国都言新令之不便者以千数。于是太子犯法。卫鞅曰：“法之不行，自上犯之。太子，君嗣也，不可施刑。刑其傅公子虔，黥其师公孙贾。”明日，秦人皆趋令。行之十年，秦国道不拾遗，山无盗贼，民勇于公战，怯于私斗，乡邑大治。秦民初言令不便者，有来言令便。卫鞅曰：“此皆乱法之民也！”尽迁之于边。其后民莫敢议令。
臣光曰：夫信者，人君之大宝也。国保于民，民保于信。非信无以使民，非民无以守国。是故古之王者不欺四海，霸者不欺四邻，善为国者不欺其民，善为家者不欺其亲。不善者反之：欺其邻国，欺其百姓，甚者欺其兄弟，欺其父子。上不信下，下不信上，上下离心，以至于败。所利不能药其所伤，所获不能补其所亡，岂不哀哉！昔齐桓公不背曹沫之盟，晋文公不贪伐原之利，魏文侯不弃虞人之期，秦孝公不废徙木之赏。此四君者，道非粹白，而商君尤称刻薄，又处战攻之世，天下趋于诈力，犹且不敢忘信以畜其民，况为四海治平之政者哉！
韩懿侯薨，子昭侯立。
显王十一年（癸亥，公元前三五八年）
秦败韩师于西山。
显王十二年（甲子，公元前三五七年）
魏、韩会于鄗。
显王十三年（乙丑，公元前三五六年）
赵、燕会于阿。
赵、齐、宋会于平陆。
显王十四年（丙寅，公元前三五五年）
齐威王、魏惠王会田于郊。惠王曰：“齐亦有宝乎？”威王曰：“无有。”惠王曰：“寡人国虽小，尚有径寸之珠，照车前后各十二乘者十枚。岂以齐大国而无宝乎？”威王曰：“寡人之所以为宝者与王异。吾臣有檀子者，使守南城，则楚人不敢为寇，泗上十二诸侯皆来朝；吾臣有盼子者，使守高唐，则赵人不敢东渔于河；吾吏有黔夫者，使守徐州，则燕人祭北门，赵人祭西门，徙而从者七千馀家；吾臣有种首者，使备盗贼，则道不拾遗。此四臣者，将照千里，岂特十二乘哉！”惠王有惭色。
秦孝公、魏惠王会于杜平。鲁共公薨，子康公毛立。
显王十五年（丁卯，公元前三五四年）
秦败魏师于元里，斩首七千级，取少梁。
魏惠王伐赵，围邯郸。楚王使景舍救赵。
显王十六年（戊辰，公元前三五三年）
齐威王使田忌救赵。初，孙膑与庞涓俱学兵法。庞涓仕魏为将军，自以能不及孙膑，乃召之。至，则以法断其两足而黥之，欲使终身废弃。齐使者至魏，孙膑以刑徒阴见，说齐使者。齐使者窃载与之齐。田忌善而客待之，进于威王。威王问兵法，遂以为师。于是威王谋救赵，以孙膑为将，辞以刑馀之人不可。乃以田忌为将而孙子为师，居辎车中，坐为计谋。
田忌欲引兵之赵。孙子曰：“夫解杂乱纷纠者不控拳，救斗者不搏撠。批亢捣虚，形格势禁，则自为解耳。今梁、赵相攻，轻兵锐卒必竭于外，老弱疲于内。子不若引兵疾走魏都，据其街路，冲其方虚，彼必释赵以自救。是我一举解赵之围而收弊于魏也。”田忌从之。十月，邯郸降魏。魏师还，与齐战于桂陵，魏师大败。
韩伐东周，取陵观、廪丘。
楚昭奚恤为相。江乙言于楚王曰：“人有爱其狗者，狗尝溺井，其邻人见，欲入言之，狗当门而噬之。今昭奚恤常恶臣之见，亦犹是也。且人有好扬人之善者，王曰：‘此君子也，’近之；好扬人之恶者，王曰：‘此小人也，’远之。然则且有子弑其父、臣弑其主者，而王终己不知也。何者？以王好闻人之美而恶闻人之恶也。”王曰：“善！寡人愿两闻之。”
显王十七年（己巳，公元前三五二年）
秦大良造卫鞅伐魏。
诸侯围魏襄陵。
显王十八年（庚午，公元前三五一年）
秦卫鞅围魏固阳，降之。
魏人归赵邯郸，与赵盟漳水上。
韩昭侯以申不害为相。申不害者，郑之贱臣也，学黄、老、刑名，以干昭侯。昭侯用为相，内修政教，外应诸侯，十五年，终申子之身，国治兵强。申子尝请仕其从兄，昭侯不许，申子有怨色。昭侯曰：“所为学于子者，欲以治国也。今将听子之谒而废子之术乎，已其行子之术而废子之请乎？子尝教寡人修功劳，视次第；今有所私求，我将奚听乎？”申子乃辟舍请罪曰：“君真其人也。”昭侯有弊袴，命藏之。侍者曰：“君亦不仁者矣。不赐左右而藏之！”昭侯曰：“吾闻明主爱一颦一笑，颦有为颦，笑有为笑。今袴岂特颦笑哉！吾必待有功者。”
显王十九年（辛未，公元前三五零年）
秦商鞅筑冀阙宫庭于咸阳，徙都之。令民父子、兄弟同室内息者为禁。并诸小乡聚集为一县，县置令、丞，凡三十一县。废井田，开阡陌，平斗、桶、权、衡、丈、尺。
秦、魏遇于彤。
赵成侯薨，公子緤与太子争立。緤败，奔韩。
显王二十一年（癸酉，公元前三四八年）
秦商鞅更为赋税法，行之。
显王二十二年（甲戌，公元前三四七年）
赵公子范袭邯郸，不胜而死。
显王二十三年（乙亥，公元前三四六年）
齐杀其大夫牟。
鲁康公薨，子景公偃立。
卫更贬号曰侯，服属三晋。
显王二十五年（丁丑，公元前三四四年）
诸侯会于京师。
显王二十六年（戊寅，公元前三四三年）
王致伯于秦，诸侯皆贺秦。秦孝公使公子少官帅师会诸侯于逢泽以朝王。
显王二十八年（庚辰，公元前三四一年）
魏庞涓伐韩。韩请救于齐。齐威王召大臣而谋曰：“蚤救孰与晚救？”成侯曰：“不如勿救。”田忌曰：“弗救则韩且折而入于魏，不如蚤救之。”孙膑曰：“夫韩、魏之兵未弊而救之，是吾代韩受魏之兵，顾反听命于韩也。且魏有破国之志，韩见亡，必东面而愬于齐矣。吾因深结韩之亲而晚承魏之弊，则可受重利而得尊名也。”王曰：“善！”乃阴许韩使而遣之。韩因恃齐，五战不胜，而东委国于齐。齐因起兵，使田忌、田婴、田盼将之，孙子为师，以救韩，直走魏都。庞涓闻之，去韩而归。魏人大发兵，以太子申为将，以御齐师。孙子谓田忌曰：“彼三晋之兵素悍勇而轻齐，齐号为怯。善战者因其势而利导之。《兵法》：‘百里而趣利者蹶上将，五十里而趣利者军半至。’”乃使齐军入魏地为十万灶，明日为五万灶，又明日为二万灶。庞涓行三日，大喜曰：“我固知齐军怯，入吾地三日，士卒亡者过半矣！”乃弃其步军，与其轻锐倍日并行逐之。孙子度其行，暮当至马陵。马陵道狭而旁多阻隘，可伏兵。乃斫大树，白而书之曰：“庞涓死此树下！”于是令齐师善射者万弩夹道而伏，期日暮见火举而俱发。庞涓果夜到斫木下，见白书，以火烛之。读未毕，万弩俱发，魏师大乱相失。庞涓自知智穷兵败，乃自刭，曰：“遂成竖子之名！”齐因乘胜大破魏师，虏太子申。
成侯邹忌恶田忌，使人操十金，卜于市，曰：“我，田忌之人也。我为将三战三胜，欲行大事，可乎？”卜者出，因使人执之。田忌不能自明，率其徒攻临淄，求成侯。不克，出奔楚。
显王二十九年（辛巳，公元前三四零年）
卫鞅言于秦孝公曰：“秦之与魏，譬若人之有腹心之疾，非魏并秦，秦即并魏。何者？魏居岭厄之西，都安邑，与秦界河，而独擅山东之利。利则西侵秦，病则东收地。今以君之贤圣，国赖以盛；而魏往年大破于齐，诸侯畔之，可因此时伐魏。魏不支秦，必东徙。然后秦据河山之固，东乡以制诸侯，此帝王之业也。”公从之，使卫鞅将兵伐魏。魏使公子卬将而御之。军既相距，卫鞅遗公子卬书曰：“吾始与公子欢，今俱为两国将，不忍相攻，可与公子面相见盟，乐饮而罢兵，以安秦、魏之民。”公子卬以为然，乃相与会。盟已，饮。而卫鞅伏甲士，袭虏公子卬，因攻魏师，大破之。魏惠王恐，使使献河西之地于秦以和。因去安邑，徙都大梁。乃叹曰：“吾恨不用公叔之言！”
秦封卫鞅商于十五邑，号曰商君。
齐、赵伐魏。
楚宣王薨，子威王商立。
显王三十一年（癸未，公元前三三八年）
秦孝公薨，子惠文王立，公子虔之徒告商君欲反，发吏捕之。商君亡之魏。魏人不受，复内之秦。商君乃与其徒之商于，发兵北击郑。秦人攻商君，杀之，车裂以徇，尽灭其家。
初，商君相秦，用法严酷，尝临渭沦囚，渭水尽赤，为相十年，人多怨之。赵良见商君，商君问曰：“子观我治秦，孰与五羖大夫贤？”赵良曰：“千人之诺诺，不如一士之谔谔。仆请终烧正言而无诛，可乎？”商君曰“诺。”赵良曰：“五羖大夫，荆之鄙人也，穆公举之牛口之下，而加之百姓之上，秦国莫敢望焉。相秦六七年而东伐郑，三置晋君，一救荆祸。其为相也，劳不坐乘，暑不张盖。行于国中，不从车乘，不操干戈。五羖大夫死，秦国男女流涕，童子不歌谣，舂者不相杵。今君之见也，因嬖人景监以为主；其从政也，凌轹公族，残伤百姓。公子虔杜门不出已八年矣。君又杀祝欢而黥公孙贾。《诗》曰：‘得人者兴，失人者崩。’此数者，非所以得人也。君之出也，后车载甲，多力而骈胁者为骖乘，持矛而操闟戟者旁车而趋。此一物不具，君固不出。《书》曰：‘恃德者昌，恃力者亡。’此数者，非恃德也。君之危若朝露，而尚贪商于之富，宠秦国之政，畜百姓之怨。秦王一旦捐宾客而不立朝，秦国之所以收君者岂其微哉！”商君弗从。居五月而难作。
显王三十二年（甲申，公元前三三七年）
韩申不害卒。
显王三十三年（乙酉，公元前三三六年）
宋太丘社亡。
邹人孟轲见魏惠王。王曰：“叟，不远千里而来，亦有以利吾国乎？”孟子曰：“君何必曰利，仁义而已矣！君曰何以利吾国，大夫曰何以利吾家，士庶人曰何以利吾身，上下交征利而国危矣。未有仁而遗其亲者也，未有义而后其君者也。”王曰：“善。”
初，孟子师子思，尝问牧民之道何先。子思曰：“先利之。”孟子曰：“君子所以教民，亦仁义而已矣，何必利？”子思曰：“仁义固所以利之也。上不仁则下不得其所，上不义则下乐为诈也。此为不利大矣。故《易》曰：‘利者，义之和也。’又曰：‘利用安身，以崇德也。’此皆利之大者也。”
臣光曰：子思、孟子之言，一也。夫唯仁者为知仁义之利，不仁者不知也。故孟子对梁王直以仁义而不及利者，所与言之人异故也。
显王三十四年（丙戌，公元前三三五年）
秦伐韩，拔宜阳。
显王三十五年（丁亥，公元前三三四年）
齐王、魏王会于徐州以相王。
韩昭侯作高门，屈宜臼曰：“君必不出此门。何也？不时。吾所谓时者，非时日也。夫人固有利、不利时。往者君尝利矣，不作高门。前年秦拔宜阳，今年旱，君不以此时恤民之急而顾益奢，此所谓时诎举赢者也。故曰不时。”
越王无疆伐齐。齐王使人说之以伐齐不如伐楚之利，越王遂伐楚。楚人大败之，乘胜尽取吴故地，东至于浙江。越以此散，诸公族争立，或为王，或为君，滨于海上，朝服于楚。
显王三十六年（戊子，公元前三三三年）
楚王伐齐，围徐州。
韩高门成，昭侯薨，子宣惠王立。
初，洛阳人苏秦说秦王以兼天下之术，秦王不用其言。苏秦乃去，说燕文公曰：“燕之所以不犯寇被甲兵者，以赵之为蔽其南也。且秦之攻燕也，战于千里之外；赵之攻燕也，战于百里之内。夫不忧百里之患而重千里之外，计无过于此者。愿大王与赵从亲，天下为一，则燕国必无患矣。”文公从之，资苏秦车马，以说赵肃侯曰：“当今之时，山东之建国莫强于赵，秦之所害亦莫如赵。然而秦不敢举兵伐赵者，畏韩、魏之议其后也。秦之攻韩、魏也，无有名山大川之限，稍蚕食之，傅国都而止。韩、魏不能支秦，必入臣于秦。秦无韩、魏之规则祸中于赵矣。臣以天下地图案之，诸侯之地五倍于秦，料度诸侯之卒十倍于秦。六国为一，并力西乡而攻秦，秦必破矣。夫衡人者皆欲割诸侯之地以与秦，秦成则其身富荣，国被秦患而不与其忧，是以衡人日夜务以秦权恐愒诸侯，以求割地。故愿大王熟计之也！窃为大王计，莫如一韩、魏、齐、楚、燕、赵为从亲以畔秦，令天下之将相会于洹水上，通质结盟，约曰：‘秦攻一国，五国各出锐师，或桡秦，或救之。有不如约者，五国共伐之！’诸侯从亲以摈秦，秦甲必不敢出于函谷以害山东矣。”肃侯大说，厚待苏秦，尊宠赐赉之，以约于诸侯。会秦使犀首伐魏，大败其师四万馀人，禽将龙贾，取雕阴，且欲东兵。苏秦恐秦兵至赵而败从约，念莫可使用于秦者，乃激怒张仪，入之于秦。
张仪者，魏人，与苏秦俱事鬼谷先生，学纵横之术，苏秦自以为不及也。仪游诸侯无所遇，困于楚，苏秦故召而辱之。仪怒，念诸侯独秦能苦越，遂入秦。苏秦阴遣其舍人赍金币资仪，仪得见秦王。秦王说之，以为客卿。舍人辞去，曰：“苏君忧秦伐赵败从约，以为非君莫能得秦柄，故激怒君，使臣阴奉给君资，尽苏君之计谋也。”张仪曰：“嗟乎！此在吾术中而不悟，吾不及苏君明矣。为吾谢苏君，苏君之时，仪何敢言！”
于是苏秦说韩宣惠王曰：“韩地方九百馀里，带甲数十万，天下之强弓、劲弩、利剑皆从韩出。韩卒超足而射，百发不暇止。以韩卒之勇，被坚甲，跖劲弩，带利剑，一人当百，不足言也。大王事秦，秦必求宜阳、成皋。今兹效之，明年又复求割地。与则无地以给之，不与则弃前功，受后祸。且大王之地有尽而秦之求无已，以有尽之地逆无已之求，此所谓市怨结祸者也。不战而地已削矣！鄙谚曰：‘宁为鸡口，无为牛后。’夫以大王之贤，挟强韩之兵，而有牛后之名，臣窃为大王羞之。”韩王从其言。苏秦说魏王曰：“大王之地方千里，地名虽小，然而田舍、庐庑之数，曾无所刍牧。人民之众，车马之多，日夜行不绝，輷訇殷殷，若有三军之众。臣窃量大王之国不下楚。今窃闻大王之卒，武士二十万，苍头二十万，奋击二十万，厮徒十万；车六百乘，骑五千匹，乃听于群臣之说，而欲臣事秦。愿大王熟察之。故敝邑赵王使臣效愚计，奉明约，以大王之诏诏之。”魏王听之。
苏秦说齐王曰：“齐四塞之国，地方二千馀里，带甲数十万，粟如丘山。三军之良，五家之兵，进如锋矢，战如雷霆，解如风雨。即有军役，未尝倍泰山，绝清河，涉渤海也。临菑之中七万户，臣窃度之，不下户三男子，不待发于远县，而临菑之卒固已二十一万矣。临菑甚富而实，其民无不斗鸡、走狗、六博、阘鞠。临菑之涂，车毂击，人肩摩，连衽成帷，挥汗成雨。夫韩、魏之所以重畏秦者，为与秦接境壤也。兵出而相当，不十日而战胜存亡之机决矣。韩、魏战而胜秦，则兵半折，四境不守；战而不胜，则国已危亡随其后。是故韩、魏之所以重与秦战而轻为之臣也。今秦之攻齐则不然。倍韩、魏之地，过卫阳晋之道，经乎亢父之险，车不得方轨，骑不得比行。百人守险，千人不敢过也。秦虽欲深入则狼顾，恐韩、魏之议其后也。是故恫疑、虚喝、骄矜而不敢进，则秦之不能害齐亦明矣。夫不深料秦之无奈齐何，而欲西面而事之，是群臣之计过也。今无臣事秦之名而有强国之宝，臣是故愿大王少留意计之。”齐王许之。乃西南说楚威王曰：“楚，天下之强国也，地方六千馀里，带甲百万，车千乘，骑万匹，粟支十年，此霸王之资也。秦之所害莫如楚，楚强则秦弱，秦强则楚弱，其势不两立。故为大王计，莫如从亲以孤秦。臣请令山东之国奉四时之献，以承大王之明诏。委社稷，奉宗庙，练士厉兵，在大王之所用之。故从亲则诸侯割地以事楚，衡合则楚割地以事秦。此两策者相去远矣，大王何居焉？”楚王亦许之。于是苏秦为从约长，并相六国，北报赵，车骑辎重拟于王者。
齐威王薨，子宣王辟疆立；知成侯卖田忌，乃召而复之。
燕文公薨，子易王立。
卫成侯薨，子平侯立。
显王三十七年（己丑，公元前三三二年）
秦惠王使犀首欺齐、魏，与共伐赵，以败从约。赵肃侯让苏秦，苏秦恐，请使燕，必报齐。苏秦去赵而从约皆解。赵人决河水以灌齐、魏之师，齐、魏之师乃去。
魏以阴晋为和于秦，实华阴。
齐王伐燕，取十城，已而复归之。
显王三十九年（辛卯，公元前三三零年）
秦伐魏，围焦、曲沃。魏入少梁、河西地于秦。
显王四十年（壬辰，公元前三二九年）
秦伐魏，渡河，取汾阴、皮氏，拔焦。
楚威王薨，子怀王槐立。
宋公剔成之弟偃袭攻剔成。剔成奔齐，偃自立为君。
显王四十一年（癸巳，公元前三二八年）
秦公子华、张仪帅师围魏蒲阳，取之。张仪言于秦王，请以蒲阳复与魏，而使公子繇质于魏。仪因说魏王曰：“秦之遇魏甚厚，魏不可以无礼于秦。”魏因尽入上郡十五县以谢焉。张仪归而相秦。
显王四十二年（甲午，公元前三二七年）
秦县义渠，以其君为臣。
秦归焦、曲沃于魏。
显王四十三年（乙未，公元前三二六年）
赵肃侯薨，子武灵王立。置博闻师三人，左、右司过三人，先问先君贵臣肥义，加其秩。
显王四十四年（丙申，公元前三二五年）
夏，四月，戊午，秦初称王。
卫平侯薨，子嗣君立。卫有胥靡亡之魏，因为魏王之后治病。嗣君闻之，使人请以五十金买之。五反，魏不与，乃以左氏易之。左右谏曰：“夫以一都买一胥靡，可乎？”嗣君曰：“非子所知也。夫治无小，乱无大。法不立，诛不必，虽有十左氏，无益也。法立，诛必，失十左氏，无害也。”魏王闻之曰：“人主之欲，不听之不祥。”因载而往，徒献之。
显王四十五年（丁酉，公元前三二四年）
秦张仪帅师伐魏，取陕。
苏秦通于燕文公之夫人，易王知之。苏秦恐，乃说易王曰：“臣居燕不能使燕重，而在齐则燕重。”易王许之。乃伪得罪于燕而奔齐，齐宣王以为客卿。苏秦说齐王高宫室，大苑囿，以明得意，欲以敝齐而为燕。
显王四十六年（戊戌，公元前三二三年）
秦张仪及齐、楚之相会啮桑。
韩、燕皆称王，赵武灵王独不肯，曰：“无其实，敢处其名乎？”令国人谓己曰君。
显王四十七年（己亥，公元前三二二年）
秦张仪自啮桑还而免相，相魏。欲令魏先事秦而诸侯效之，魏王不听。秦王伐魏，取曲沃、平周。复阴厚张仪益甚。
显王四十八年（庚子，公元前三二一年）
王崩，子慎靓王定立。
燕易王薨，子哙立。
齐王封田婴于薛，号曰靖郭君。靖郭君言于齐王曰：“五官之计，不可不日听而数览也。”王从之。已而厌之，悉以委靖郭君。靖郭君由是得专齐之权。靖郭君欲城薛，客谓靖郭君曰：“君不闻海大鱼乎？网不能止，钩不能牵，荡而失水，则蝼蚁制焉。今夫齐，亦君之水也。君长有齐，奚以薛为！苟为失齐，虽隆薛之城到于天，庸足恃乎？”乃不果城。靖郭君有子四十馀人，其贱妾之子曰文。文通傥饶智略，说靖郭君以散财养士。靖郭君使文主家待宾客，宾客争誉其美，皆请靖郭君以文为嗣。靖郭君卒，文嗣为薛公，号曰孟尝君。孟尝君招致诸侯游士及有罪亡人，皆舍业厚遇之，存救其亲戚。食客常数千人，各自以为孟尝君亲己。由是孟尝君之名重天下。
臣光曰：君子之养士，以为民也。《易》曰：“圣人养贤，以及万民。”夫贤者，其德足以敦化正俗，其才足以顿纲振纪，其明足以烛微虑远，其强足以结仁固义。大则利天下，小则利一国。是以君子丰禄以富之，隆爵以尊之。养一人而及万人者，养贤之道也。今孟尝君之养士也，不恤智愚，不择臧否，盗其君之禄，以立私党，张虚誉，上以侮其君，下以蠹其民，是奸人之雄也，乌足尚哉！《书》曰：“受为天下逋逃主、萃渊薮。”此之谓也。
孟尝君聘于楚，楚王遗之象床。登徒直送之，不欲行，谓孟尝君门人公孙戌曰：“象床之直千金，苟伤之毫发，则卖妻子不足偿也。足下能使仆无行者，有先人之宝剑，愿献之。”公孙戌许诺，入见孟尝君曰：“小国所以皆致相印于君者，以君能振达贫穷，存亡继绝，故莫不悦君之义，慕君之廉也。今始至楚而受象床，则未至之国将何以待君哉！”孟尝君曰：“善。”遂不受。公孙戌趋去，未至中闺，孟尝君召而反之，曰：“子何足之高，志之扬也？”公孙戌以实对。孟尝君乃书门版曰：“有能扬文之名，止文之过，私得宝于外者，疾入谏！”
臣光曰：孟尝君可谓能用谏矣。苟其言之善也，虽怀诈谖之心，犹将用之，况尽忠无私以事其上乎！《诗》云：“采葑采菲，无以下体。”孟尝君有焉。韩宣惠王俗两用公仲、公叔为政，问于缪留。对曰：“不可。晋用六卿而国分，齐简公用陈成子及阚止而见杀，魏用犀首、张仪而西河之外亡。今君两用之，其多力者内树党，其寡力者藉外权。群臣有内树党以骄主，有外为交以削地，君之国危矣！”', '', '', '齐国攻打魏国，夺取观津。
三年（乙卯，公元前366年）
秦国在洛阳击败魏国和韩国军队。
魏国攻打宋国。
秦献公在石门大败韩、赵、魏三国联军，斩首六万人。周王特地颁赏他绣有黑、白、青花纹的服饰。
魏国在浍地击败韩国和赵国军队。
卫国卫声公去世，其子卫速即位为卫成侯。
秦国秦献公去世，其子即位为秦孝公。孝公已经二十一岁了。这时黄河、崤山以东有六个强国，淮河、泗水流域十几个小国林立，楚国、魏国与秦国接壤。魏国筑有一道长城，从郑县沿着洛水直到上郡；楚国自汉中向南占有巴郡、黔中等地。各国都把秦国当作未开化的夷族，予以鄙视，不准参加中原各诸侯国的会议盟誓。目睹此情，秦孝公决心发愤图强，整顿国家，修明政治，让秦国强大起来。
秦孝公在国中下令说：“当年我国的国君秦穆公，立足于岐山、雍地，励精图治，向东平定了晋国之乱，以黄河划定国界；向西称霸于戎翟等族，占地广达千里；被周王赐与方伯重任，各诸侯国都来祝贺，所开辟的基业是多么光大宏伟。只是后来历代国君厉公、躁公、简公及出子造成国内动乱不息，才无力顾及外事。魏、赵、韩三国夺去了先王开创的河西领土，这是无比的耻崐辱。到献公即位时，平定安抚边境，把都城迁到栎阳，亲往治理，准备向东征讨，收复穆公时的旧地，重修穆公时的政策法令。我想到先辈的未竟之志，常常痛心疾首。现在宾客群臣中谁能献上奇计，让秦国强盛，我就封他为高官，给他封地。”卫国的公孙鞅听到这道命令，于是西行来到秦国。
十年（壬戌，公元前359年）
法令已详细制订但尚未公布，公孙鞅怕百姓难以确信，于是在国都的集市南门立下一根长三丈的木杆，下令说有人能把它拿到北门去就赏给十金。百姓们感到此事很古怪，没人动手去搬。公孙鞅又说：“能拿过去的赏五十金。”于是有一个人半信半疑地拿着木杆到了北门，立刻获得了五十金的重赏。这时，公孙鞅才下令颁布变法法令。
臣司马光曰：信誉，是君主至高无上的法宝。国家靠人民来保卫，人民靠信誉来保护；不讲信誉无法使人民服从，没有人民便无法维持国家。所以古代成就王道者不欺骗天下，建立霸业者不欺骗四方邻国，善于治国者不欺骗人民，善于治家者不欺骗亲人。只有蠢人才反其道而行之，欺骗邻国，欺骗百姓，甚至欺骗兄弟、父子。上不信下，下不信上，上下离心，以至一败涂地。靠欺骗所占的一点儿便宜救不了致命之伤，所得到的远远少于失去的，这岂不令人痛心！当年齐桓公不违背曹沫以胁迫手段订立的盟约，晋文公不贪图攻打原地而遵守信用，魏文侯不背弃与山野之人打猎的约会，秦孝公不收回对移动木杆之人的重赏，这四位君主的治国之道尚称不上完美，而公孙鞅可以说是过于刻薄了，但他们处于你攻我夺的战国乱世，天下尔虞我诈、斗智斗勇之时，尚且不敢忘记树立信誉以收服人民之心，又何况今日治理一统天下的当政者呢！
十一年（癸亥，公元前358年）
十二年（甲子，公元前357年）
十三年（乙丑，公元前356年）
赵国、齐国、宋国在平陆举行会议。
齐威王、魏惠王在效野约会狩猎。魏惠王问：“齐国也有什么宝贝吗？”齐威王说：“没有。”魏惠王说：“我的国家虽小，尚有十颗直径一寸以上、可以照亮十二乘车子的大珍珠。以齐国之大，难道能没有宝贝？”齐威王说：“我对宝贝的看法和你可不一样。我的大臣中有位檀子，派他镇守南城，楚国不敢来犯，泗水流域的十二个诸侯国都来朝贺。我的大臣中还有位盼子，使他守高唐，赵国人怕得不敢向东到黄河边来打渔。我的官吏中有位黔夫，令他守徐州，燕国人在北门、赵国人在西门望空礼拜求福，相随来投奔的多达七千余家。我的大臣中有位种首，让他防备盗贼，便出现路不拾遗的太平景象。这四位大臣，光照千里，岂止是十二乘车子呢！”魏惠王听了面色十分惭愧。
鲁国鲁共公去世，其子姬毛即位为鲁康公。
秦国在元里击败魏国军队，斩首七千余人，夺取少梁。
十六年（戊辰，公元前353年）
起初，孙膑与庞涓一起学兵法，庞涓在魏国做将军，自己估量才能不如孙膑，便召孙膑前来魏国，又设计依法砍断孙膑的双脚，在脸上刺字，想使他终身成为废人。齐国使者来到魏国，孙膑以受刑罪人身份与他暗中相见，说动了齐国使者，偷偷地把孙膑藏在车中回到齐国。齐国大臣田忌把他奉为座上客，又推荐给齐威王。威王向他请教了兵法，于是延请他为老师。这时齐威王计划出兵援救赵国，任命孙膑为大将，孙膑以自己是个残疾之人坚决辞谢，齐威王便以田忌为大将、孙膑为军师，让他坐在帘车里，出谋划策。
韩国攻打东周王朝，夺取陵观、廪丘。
十七年（己巳，公元前352年）
各诸侯国出兵围攻魏国襄陵城。
秦国公孙鞅率军围攻魏国固阳，固阳归降。
韩昭侯任用申不害为国相。
申不害曾经请求让他的堂兄做个官，韩昭侯不同意，申不害很不高兴。韩昭侯对他说：“我之所以向你请教，就是想治理好国家。现在我是批准你的私请来破坏你创设的法度呢，还是推行你的法度而拒绝你的私请呢？你曾经开导我要按功劳高低来封赏等级，现在你却有私人的请求，我该听哪种意见呢？”申不害便离开了自己正式居室，另居别处，向韩昭侯请罪说：“您真是我企望效力的贤明君主！”
十九年（辛未，公元前350年）
秦军和魏军在彤地发生遭遇战。
二十一年（癸酉，公元前348年）
二十二年（甲戌，公元前347年）
二十三年（乙亥，公元前346年）
鲁国鲁康公去世，其子姬偃即位为鲁景公。
二十五年（丁丑，公元前344年）
二十六年（戊寅，公元前343年）
二十八年（庚辰，公元前341年）
齐国这时才出兵，派田忌、田婴、田盼为将军，孙膑为军师，前去援救韩国，仍用老办法，直袭魏国都城。庞涓听说，急忙放弃韩国，回兵国中。魏国集中了全部兵力，派太子申为将军，抵御齐国军队。孙膑对田忌说：“魏、赵、韩那些地方的士兵向来骠悍勇猛，看不起齐国；齐国士兵的名声也确实不佳。善于指挥作战的将军必须因势利导，扬长避短。《孙武兵法》说：‘从一百里外去奔袭会损失上将军，从五十里外去奔袭只有一半军队能到达。’”于是便命令齐国军队进入魏国地界后，做饭修造十万个灶，第二天减为五万个灶，第三天再减为二万个灶。庞涓率兵追击齐军三天，见此情况，大笑着说：“我早就知道齐兵胆小，进入我国三天，士兵已逃散一多半了。”于是丢掉步兵，亲率轻兵精锐日夜兼程追击齐军。孙膑估计魏军的行程当晚将到达马陵。马陵这个地方道路狭窄而多险隘，可以伏下重兵，孙膑便派人刮去一棵大树的树皮，在白树干上书写六个大字：“庞涓死此树下！”再从齐国军队中挑选万名优秀射箭手夹道埋伏，约定天黑后一见有火把亮光就万箭齐发。果然，庞涓在夜里赶到那棵树下，看见白树干上隐约有字，便令人举火照看，还未读完，两边箭如飞蝗，一齐射下，魏军大乱，溃不成军。庞涓自知败势无法挽回，便拔剑自尽，临死前叹息说：“让孙膑这小子成名了！”齐军乘势大破魏军，俘虏了太子申。
二十九年（辛巳，公元前340年）
两军对垒，公孙鞅派人送信给公子，写道：“当年我与公子您交情很好，现在都成为两军大将，不忍心互相攻杀。我们可以见面互相起誓结盟，畅饮之后罢兵回国，以使秦国、魏国的百姓安心。”公子信以为真，便前来赴会。两方盟誓已毕，正饮酒时，公孙鞅事先埋伏下的甲士冲出来，俘虏了公子，又乘势攻击魏军，使其大败。
秦国封赏给公孙鞅商于地方的十五个县。于是他号称为商君。
楚国楚宣王去世，其子商继位为楚威王。
秦国秦孝公去世，其子即位为秦惠文王。因公子虔的门下人指控商君要谋反，便派官吏前去捕捉他。商君急忙逃往魏国，魏国人拒不接纳，把他送回到秦国。商君只好与他的门徒来到封地商于，起兵向北攻打郑。秦国军队向商君进攻，将他斩杀，车裂分尸，全家老小也被杀光。
三十二年（甲申，公元前337年）
三十三年（乙酉，公元前336年）
邹地人士孟轲求见魏惠王，惠王问道：“老先生，您不远千里而来，能给我的国家带来什么利益呢？”孟轲说：“君主您何必张口就要利益，有了仁义就足够了！如果君主光说为国谋利益，大夫光说为家谋利益，士民百姓所说的也是如何让自身得到利益，上上下下都追逐利益，那么国家就危险了。只有仁爱的人不会抛弃他的亲人，忠义的人不会把国君放到脑后。”魏惠王点头说：“对。”
臣司马光曰：孔、孟子的话，都是一个道理。只有仁义的人才知道仁义是最大的利，不仁义的人是不知道的。所以孟子对魏惠王直接宣扬仁义，闭口不谈利，是因为谈话的对象不同的缘故。
秦国进攻韩国，攻克宜阳。
齐王、魏王在徐州会面，互相尊称为王。
这正是古话所说的越穷越摆架子。所以我说时运不宜。”
楚王攻打齐国，围困徐州。
当初，洛阳人苏秦向秦王进献兼并天下的计划，秦王却不采纳，苏秦于是离去，又游说燕文公道：“燕国之所以不遭受侵犯和掠夺，是因为南面有赵国做挡箭牌。秦国要想攻打燕国，必须远涉千里之外，而赵国要攻打燕国，只需行军百里以内。现在您不担忧眼前的灾患，反倒顾虑千里之外，办事情没有比这更错的了。我希望大王您能与赵国结为亲密友邦，两国一体，则燕国可以无忧无虑了。”
这时秦国派犀首为大将攻打魏国，大败四万多魏军，活捉魏将龙贾，攻取雕阴，又要引兵东下。苏秦担心秦兵到赵国会挫败联合各国的计划，盘算没有别人可以到秦国去用计，于是用激将法挑动张仪，前往秦国。
于是苏秦又劝说韩宣惠王：“韩国方圆九百多里，有几十万甲士，天下的强弓、劲弩、利剑都产于韩国。韩国士兵双脚踏弩射箭，能连续百发以上。用这样勇猛的士兵，披上坚固的盔甲，张起强劲的弓弩，手持锋利宝剑，一个顶百个也不在话下。大王若是屈服秦国，秦国必定索要宜阳、成皋两城，现在满足了它，明年还会要割别的地。再给它已无地可给，不给又白费了以前的讨好，要蒙受后祸。况且大王的地有限而秦国的贪欲无止，以有限的地来迎合无穷的贪求，这正是自找苦吃，没打一仗就丢了土地。俗话说得好：‘宁为鸡口，无为牛后。’大王您这样贤明，拥有韩国的强兵，而落个尾从的名声，那时我也背地里要为您害羞了！”韩王听从了苏秦的劝说。
苏秦再游说齐王说：“齐国四面要塞，广袤二千余里，披甲士兵几十万，谷积如山。精良的三军，郊外二十县的五都之兵，进攻像离弦利箭，作战如雷霆万钧，解散似风雨扫过。有了他们，即使遇到战事，也不用到泰山、清河、渤海一带去征兵。临淄城里有七万户，以我的猜度，每户男子不下三人，不用到边远县乡去征发，仅临淄城里的人已够二十一万兵了。临淄城富庶殷实，居民都斗鸡、赛狗、下棋、踢球。临淄的道路上，车多得互相碰撞，人多得摩肩接踵，衣服连起来成了帷帐，众人挥汗如同下雨。那韩国、魏国之所以十分害崐怕秦国，是因为与秦国接壤，出兵对阵，作战用不了十天，就到了存亡的生死关头。韩国、魏国如果打败了秦国，自身也损伤过半，边境难守；如果败给秦国，那么紧接着国家就濒临危亡。所以韩国、魏国对与秦国作战十分慎重，常常表示屈服忍让。而秦国来攻齐国就不一样了，要背靠韩国、魏国的国土，经过卫国阳晋之路，再经过亢父的险隘，车辆、骑兵都难以并行。只要有一百人守住险要，一千人也不敢通过。秦国即使想驱兵深入，也要顾忌韩、魏两国在它背后的活动，所以它虽骄横，却又疑心重重，虚张声势而不敢冒进攻齐，以此而见，秦国难以危害齐国是明显的。而你们不仔细考虑秦国对齐国的无可奈何，却要向西俯首称臣，这是齐国群臣的失策。现在听我的建议，齐国可以免去屈服于秦国的卑名，而获得强国的实际利益，因此我希望大王您能留意划算一下！”齐王也应允了苏秦的建议。
于是苏秦成为主持六国联盟的纵约长，兼任六国的国相。他北归赵国复命时，车马随从之多，可与王君相比。
燕国燕文公去世，其子即位为燕易王。
三十七年（己丑，公元前332年）
魏国献出阴晋向秦国求和，阴晋实际上就是华阴。
三十九年（辛卯，公元前330年）
四十年（壬辰，公元前329年）
楚国楚威王去世，其子槐即位为楚怀王。
四十一年（癸巳，公元前328年）
四十二年（甲午，公元前327年）
秦国归还焦城、曲沃给魏国。
赵国赵肃侯去世，其子即位为赵武灵王；设置“博闻师”的官职三人，又设左、右司过的官职三人。即位后先问候先王的贵臣肥义，增加了他的俸禄。
夏季，四月，戊午（初四），秦国君首次称王。
四十五年（丁酉，公元前324年）
苏秦与已故燕文公的夫人私通，被燕易王发现。苏秦十分恐惧，于是对燕易王说：“我留在燕国不能使燕国变得重要，而我要是在齐国，可以设法增强燕国的力量。”易王同意了，苏秦便伪装得罪燕国逃奔齐国，齐宣王留他崐做客卿。苏秦鼓动齐王增高宫殿、扩大林园，显示齐王的地位，想借此来削弱齐国的财力，为燕国效劳。
秦国张仪与齐国、楚国的国相在啮桑举行会议。
四十七年（己亥，公元前322年）
四十八年（庚子，公元前321年）
燕国燕易王去世，其子姬哙即位。
靖郭君想在薛建城，一个幕客对他劝阻说：“您没有看到海里的大鱼吗？海网罩不住它，鱼钩也牵不住它，然而它一离开海水，连小小蚂蚁也可以制它于死地。今天的齐国，就是您的汪洋大海。您能长期掌握住齐国，又要薛城做什么！如果失去齐国大权，即使把薛城城墙砌到天上，也保不住自己！”靖郭君于是放弃了扩建计划。
臣司马光曰：贤德的君子收养士人，是为了百姓的利益。《易经》说：“崐圣人收养贤良人才，恩泽及于天下百姓。”士人中贤良的人，道德操守足以匡正风俗，才干足以整顿纲纪，见识足以高瞻远瞩、洞察一切，毅力足以团结仁人志士；用到大处可以有利于天下，用到小处可以有利于一国。所以贤德的君子用丰厚的俸禄来收养他们，用尊崇的地位来礼待他们。蓄养一个人就能使天下百姓都普被恩泽，这是养贤之道的真谛。然而孟尝君的养士，不分聪明愚笨，不论好人坏人，一概收留；他盗用国库的薪俸，结立自己的私党，沽名钓誉，对上欺瞒国君，对下盘剥百姓，真是一个奸雄，决不值得颂扬！《尚书》说：“商纣王是收留天下罪人的窝主、藏污纳垢的匪巢。”孟尝君也正是这种情况。
臣司马光曰：孟尝君可以算是能虚心接受意见的人了。只要提的意见对，即使是别有用心，他也予以采纳，更何况那些毫无私心的尽忠之言呢！《诗经》写道：“采集蔓菁，采集土瓜，根好根坏不要管它。”孟尝君是做到了这种兼容并包的雅度。', NULL, '', 'indent', 1572785854, '5dbe5df7c05a800068587eab', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643575, '资治通鉴 · 卷四 · 周纪四', NULL, 6, 1577, 1, 1, '司马光', NULL, 10351, '57b9c6d179bc4400639cc661', '宋', 'wen', '文', '资治通鉴', '', '起阏逢困敦，尽著雍困敦，凡二十五年。
赧王中十八年（甲子，公元前二九七年）
楚怀王亡归。秦人觉之，遮楚道。怀王从间道走赵。赵主父在代，赵人不敢受。怀王将走魏，秦人追及之，以归。
鲁平公薨，子缗王贾立。
赧王中十九年（乙丑，公元前二九六年）
楚怀王发病，薨于秦，秦人归其丧。楚人皆怜之，如悲亲戚。诸侯由是不直秦。
齐、韩、魏、赵、宋同击秦，至盐氏而还。秦与韩武遂、与魏封陵以和。
赵主父行新地，遂出代；西遇楼烦王于西河而致其兵。
魏襄王薨，子昭王立。
韩襄王薨，子釐王咎立。
赧王中二十年（丙寅，公元前二九五年）
秦尉错伐魏襄城。赵主父与齐、燕共灭中山，迁其王于肤施。归，行赏，大赦，置酒，酺五日。
赵主父封其长子章于代，号曰安阳君。安阳君素侈，心不服其弟。主父使田不礼相之。李兑谓肥义曰：“公子章强壮而志骄，党众而欲大，田不礼忍杀而骄，二人相得，必有阴谋。夫小人有欲，轻虑浅谋，徒见其利，不顾其害，难必不久矣。子任重而势大，乱之所始而祸之所集也。子奚不称疾毋出而传政于公子成，毋为祸梯，不亦可乎！”肥义曰：“昔者主父以王属义也，曰：‘毋变而度，毋易而虑，坚守一心，以殁而世。’义再拜受命而籍之。今畏不礼之难而忘吾籍，变孰大焉！谚曰：‘死者复生，生者不愧。’吾欲全吾言，安得全吾身乎！子则有赐而忠我矣。虽然，吾言已在前矣，终不敢失！”李兑曰：“诺。子勉之矣！吾见子已今年耳。”涕泣而出。李兑数见公子成以备田不礼。肥义谓信期曰：“公子章与田不礼声善而实恶，内得主而外为暴，矫令以擅一旦之命，不难为也。今吾忧之，夜而忘寐，饥而忘食，盗出入不可不备。自今以来，有召王者必见吾面，我将以身先之。无故而后王可入也。”信期曰：“善。”
主父使惠文王朝群臣而自从旁窥之，见其长子傫然也，反北面为臣。诎于其弟，心怜之，于是乃欲分赵而王公子章于代，计未决而辍。主父及王游沙丘，异宫，公子章、田不礼以其徒作乱，诈以主父令召王。肥义先入，杀之。高信即与王战。公子成与李兑自国至，乃起四邑之兵入距难，杀公子章及田不礼，灭其党。公子成为相，号安平君；李兑为司寇。是时惠文王少，成、兑专政。公子章之败也，往走主父，主父开之。成、兑因围主父宫。公子章死，成、兑谋曰：“以章故，围主父；即解兵，吾属夷矣！”乃遂围之，令：“宫中人后出者夷！”宫中人悉出。主父欲出不得，又不得食，探雀鷇而食之。三月馀，饿死沙丘宫。主父定死，乃发丧赴诸侯。主父初以长子章为太子，后得吴娃，爱之，为不出者数岁。生子何，乃废太子章而立之。吴娃死，爱驰；怜故太子，欲两王之，犹豫未决，故乱起。
秦楼缓免相，魏冉代之。
赧王中二十一年（丁卯，公元前二九四年）
秦败魏师于解。
赧王中二十二年（戊辰，公元前二九三年）
韩公孙喜、魏人伐秦。穰侯荐左更白起于秦王以代向寿将兵，败魏师、韩师于伊阙，斩首二十四万级，虏公孙喜，拔五城。秦王以白起为国尉。
秦王遗楚王书曰：“楚倍秦，秦且率诸侯伐楚，愿王之饬士卒，得一乐战！”楚王患之，乃复与秦和亲。
赧王中二十三年（己巳，公元前二九二年）
楚襄王迎妇于秦。
臣光曰：甚哉秦之无道也，杀其父而劫其子；楚之不竞也，忍其父而婚其仇！呜呼！楚之君诚得其道，臣诚得其人，秦虽强，乌得陵之哉！善乎荀卿论之曰：“夫道，善用之则百里之地可以独立，不善用之则楚六千里而为仇人役。”故人主不务得道而广有其势，是其所以危也。
秦魏冉谢病免，以客卿烛寿为丞相。
赧王中二十四年（庚午，公元前二九一年）
秦伐韩，拔宛。
秦烛寿免。魏冉复为丞相，封于穰与陶，谓之穰侯。又封公子市于宛，公子悝于邓。
赧王中二十五年（辛未，公元前二九零年）
魏入河东地四百里、韩入武遂地二百里于秦。
魏芒卯始以诈见重。
赧王中二十六年（壬申，公元前二八九年）
秦大良造白起、客卿错伐魏，至轵，取城大小六十一。
赧王中二十七年（癸酉，公元前二八八年）
冬，十月，秦王称西帝，遣使立齐王为东帝，欲约与共伐赵。苏代自燕来，齐王曰：“秦使魏冉致帝，子以为何如？”对曰：“愿王受之而勿称也。秦称之，天下安之，王乃称之，无后也。秦称之，天下恶之，王因勿称，以收天下，此大资也。且伐赵孰与伐桀宋利？今王不如释帝以收天下之望，发兵以伐桀宋，宋举则楚、赵、梁、卫皆惧矣。是我以名尊秦而令天下憎之，所谓以卑为尊也。”齐王从之，称帝二日而复归之。十二月，吕礼自齐入秦，秦王亦去帝复称王。
秦攻赵，拔杜阳。
赧王中二十八年（甲戌，公元前二八七年）
秦攻魏，拔新垣、曲阳。
赧王中二十九年（乙亥，公元前二八六年）
秦司马错击魏河内。魏献安邑以和，秦出其人归之魏。
秦败韩师于夏山。
宋有雀生湣于城之陬。史占之，曰：“吉。小而生巨，必霸天下。”宋康王喜，起兵灭滕；伐薛；东败齐，取五城；南败楚，取地三百里，西败魏军。与齐、魏为敌国，乃愈自信其霸。欲霸之亟成，故射天笞地，斩社稷而焚灭之，以示威服鬼神。为长夜之饮于室中，室中人呼万岁，则堂上之人应之，堂下之人又应之，门外之人又应之，以至于国中，无敢不呼万岁者。天下之人谓之“桀宋”。齐湣王起兵伐之，民散，城不守。宋王奔魏，死于温。
赧王中三十年（丙子，公元前二八五年）
秦王会楚王于宛，会赵王于中阳。
秦蒙武击齐，拔九城。
齐湣王既灭宋而骄，乃南侵楚，西侵三晋，欲并二周，为天子。狐咺正议，斫之檀衢，陈举直言，杀之东闾。燕昭王日夜抚循其人，益为富实，乃与乐毅谋伐齐。乐毅曰：“齐，霸国之馀业也。地大人众，未易独攻也。王必欲伐之。莫如约赵及楚、魏。”于是使乐毅约赵，别使使者连楚、魏，且令赵啖秦以伐齐之利。诸侯害齐王之骄暴，皆争合谋与燕伐齐。
赧王中三十一年（丁丑，公元前二八四年）
燕王悉起兵，以乐毅为上将军。秦尉斯离帅师与三晋之师会之。赵王以相国印授乐毅，乐毅并将秦、魏、韩、赵之兵以伐齐。齐湣王悉国中之众以拒之，战于济西，齐师大败。乐毅还秦、韩之师，分魏师以略宋地，部赵师以收河间，身率燕师，长驱逐北。剧辛曰：“齐大而燕小，赖诸侯之助以破其军，宜及时攻取其边城以自益，此长久之利也。今过而不攻，以深入为名，无损于齐，无益于燕，而结深怨，后必悔之。”乐毅曰：“齐王伐功矜能，谋不逮下，废黜贤良，信任谄谀，政令戾虐，百姓怨怼。今军皆破亡，若因而乘之，其民必叛，祸乱内作，则齐可图也。若不遂乘之，待彼悔前之非，改过恤下而抚其民，则难虑也。”遂进军深入。齐人果大乱失度，湣王出走。乐毅入临淄，取宝物、祭器，输之于燕。燕王亲至济上劳军，行赏飨士，封乐毅为昌国君，遂使留徇齐城之未下者。齐王出亡之卫，卫君辟宫舍之，称臣而共具。齐王不逊，卫人侵之。齐王去奔邹、鲁，有骄色，邹、鲁弗内，遂走莒。楚使淖齿将兵救齐，因为齐相。淖齿欲与燕分齐地，乃执湣王而数之曰：“千乘、博昌之间，方数百里，雨血沾衣，王知之乎？”曰：“知之。”“赢、博之间，地坼及泉，王知之乎？”曰：“知之。”“有人当阙而哭者，求之不得，去则闻其声，王知之乎？”曰：“知之。”淖齿曰：“天雨血沾衣者，天以告也；地坼及泉者，地以告也；有人当阙而哭者，人以告也。天、地、人皆告矣，而王不知诫焉，何得无诛！”遂弑王于鼓里。
荀子论之曰：国者，天下之利势也。得道以持之，则大安也，大荣也，积美之源也。不得道以持之，则大危也，大累也，有之不如无之。及其綦也，索为匹夫，不可得也。齐湣、宋献是也。故用国者义立而王，信立而霸，权谋立而亡。
挈国以呼礼义也，而无以害之。行一不义，杀一无罪，而得天下，仁者不为也。擽然扶持心国，且若是其固也。之所与为之者之人，则举义士也；之所以为布陈于国家刑法者，则举义法也；主之所极然，帅群臣而首向之者，则举义志也。如是，则下仰上以义矣，是綦定也。綦定而国定，国定而天下定。故曰：以国济义，一日而白，汤、武是也。是所谓义立而王也。
德虽未至也，义虽未济也，然而天下之理略奏矣，刑赏已诺信乎天下矣，臣下晓然皆知其可要也。政令已陈，虽睹利败，不欺其民；约结已定，虽睹利败，不欺其与。如是，则兵劲城固，敌国畏之；国一綦明，与国信之。虽在僻陋之国，威动天下，五伯是也。是所谓信立而而霸也。
挈国以呼功利，不务张其义，齐其信，唯利之求；内则不惮诈其民而求小利焉，外则不惮诈其与而求大利焉。内不修正其所以有，然常欲人之有，如是，则臣下百姓莫不以诈心待其上矣。上诈其下，下诈其上，则是上下析也。如是，则敌国轻之，与国疑之，权谋日行而国不免危削，綦之而亡，齐湣、薛公是也。故用强齐，非以修礼义也，非以本政教也，非以一天下也，绵绵常以结引驰外为务。故强，南足以破楚，西足以诎秦，北足以败燕，中足以举宋。及以燕、赵起而攻之，若振槁然，而身死国亡，为天下大戮，后世言恶则必稽焉。是无他故焉，唯其不由礼义而由权谋也。
三者，明主之所谨择也，仁人之所务白也。善择者制人，不善择者人制之。
乐毅闻昼邑人王蠋贤，令军中环画邑三十里无入。使人请蠋，蠋谢不往。燕人曰：“不来，吾且屠画邑！”蠋曰：“忠臣不事二君，烈女不更二夫。齐王不用吾谏，故退而耕于野。国破君亡，吾不能存，而又欲劫之以兵，吾与其不义而生，不若死！”遂经其颈于树枝，自奋绝脰而死。燕师乘胜长驱，齐城皆望风奔溃。乐毅修整燕军，禁止侵掠，求齐之逸民，显而礼之。宽其赋敛，除其暴令，修其旧政，齐民喜悦。乃遣左军渡胶东、东莱；前军循太山以东至海，略琅邪；右军循河、济，屯阿、鄄以连魏师；后军旁北海以抚千乘；中军据临淄而镇齐都。祀桓公、管仲于郊，表贤者之闾，封王蠋之墓。齐人食邑于燕者二十馀君，有爵位于蓟者百有馀人。六月之间，下齐七十馀城，皆为郡县。秦王、魏王、韩王会于京师。
赧王中三十二年（戊寅，公元前二八三年）
秦、赵会于穰。秦拔魏安城，兵至大梁而还。
齐淖齿之乱，湣王子法章变名姓为莒太史敫家佣。太史敫女奇法章状貌，以为非常人，怜而常窃衣食之，因与私通。王孙贾从湣王，失王之处，其母曰：“汝朝出而晚来，则吾倚门而望；汝暮出而不还，则吾倚闾而望。汝今事王，王走，汝不知其处，汝尚何归焉！”王孙贾乃入市中呼曰：“淖齿乱齐国，杀湣王。欲与我诛之者袒右！”市人从者四百人，与攻淖齿，杀之。于是齐亡臣相与求湣王子，欲立之。法章惧其诛己，久之乃敢自言，遂立以为齐王，保莒城以拒燕，布告国中曰：“王已立在莒矣！”
赵王得楚和氏璧，秦昭王欲之，请易以十五城。赵王欲勿与，畏秦强，欲与之，恐见欺。以问蔺相如，对曰：“秦以城求璧而王不许，曲在我矣；我与之璧而秦不与我城，则曲在秦。均之二策，宁许以负秦。臣愿奉璧而往；使秦城不入，臣请完璧而归之。”赵王遣之。相如至秦，秦王无意偿赵城。相如乃以诈绐秦王，复取璧，遣从者怀之，间行归赵，而以身待命于秦。秦王以为贤而弗诛，礼而归之。赵王以相如为上大夫。
卫嗣君薨，子怀君立。嗣君好察微隐，县令有发褥而席敝者，嗣君闻之，乃赐之席。令大惊，以君为神。又使人过关市，赂之以金，既而召关市，问有客过与汝金，汝回遣之，关市大恐。又爱泄姬，重如耳，而恐其因爱重以壅己也，乃贵薄疑以敌如耳，尊魏妃以偶泄姬，曰：“以是相参也。”
荀子论之曰：成侯、嗣君，聚敛计数之君也，未及取民也。子产，取民者也，未及为政也。管仲，为政者也，未及修礼也。故修礼者王，为政者强，取民者安，聚敛者亡。
赧王中三十三年（己卯，公元前二八二年）
秦伐赵，拔两城。
赧王中三十四年（庚辰，公元前二八一年）
秦伐赵，拔石城。
秦穰侯复为丞相。
楚欲与齐、韩共伐秦，因欲图周。王使东周武公谓楚令尹昭子曰：“周不可图也。”昭子曰：“乃图周，则无之；虽然，何不可图？”武公曰：“西周之地，绝长补短，不过百里。名为天下共主，裂其地不足以肥国，得其众不足以劲兵。虽然，攻之者名为弑君。然而犹有欲攻之者，见祭器在焉故也。夫虎肉臊而兵利身，人犹攻之；若使泽中之麋蒙虎之皮，人之攻之也必万倍矣。裂楚之地，足以肥国；诎楚之名，足以尊主。今子欲诛残天下之共主，居三代之传器，器南，则兵至矣。”于是楚计辍不行。
赧王中三十五年（辛巳，公元前二八零年）
秦白起败赵军，斩首二万，取代光狼城。又使司马错发陇西兵，因蜀攻楚黔中，拔之。楚献汉北及上庸地。
赧王中三十六年（壬午，公元前二七九年）
秦白起伐楚，取鄢、邓、西陵。
秦王使使者告赵王，愿为好会于河外渑池。赵王欲毋行，廉颇、蔺相如计曰：“王不行，示赵弱且怯也。”赵王遂行，相如从。廉颇送至境，与王诀曰：“王行，度道里会遇之礼毕，还，不过三十日。三十日不还，则请立太子，以绝秦望。”王许之。会于渑池。王与赵王饮，酒酣，秦王请赵王鼓瑟，赵王鼓之。蔺相如复请秦王击缶，秦王不肯。相如曰：“五步之内，臣请得以颈血溅大王矣！”左右欲刃相如，相如张目叱之，左右皆靡。王不怿，为一击缶。罢酒，秦终不能有加于赵。赵人亦盛为之备，秦不敢动。赵王归国，以蔺相如为上卿，位在廉颇之右。廉颇曰：“我为赵将，有攻城野战之功。蔺相如素贱人，徒以口舌而位居我上。吾羞，不忍为之下！”宣言曰：“我见相如，必辱之！”相如闻之，不肯与会；每朝，常称病，不欲争列。出而望见，辄引车避匿。其舍人皆以为耻。相如曰：“子视廉将军孰与秦王？”曰：“不若。”相如曰：“夫以秦王之威而相如廷叱之，辱其群臣。相如虽驽，独畏廉将军哉！顾吾念之，强秦之所以不敢加兵于赵者，徒以吾两人在也。今两虎共斗，其势不俱生。吾所以为此者，先国家之急而后私仇也。”廉颇闻之，肉袒负荆至门射罪，遂为刎颈之交。
初，燕人攻安平，临淄市掾田单在安平，使其宗人皆以铁笼傅车轊。及城溃，人争门而出，皆以轊折车败，为燕所禽；独田单宗人以铁笼得免，遂奔即墨。是时齐地皆属燕，独莒、即墨未下，乐毅及并右军、前军以围莒，左军、后军围即墨。即墨大夫出战而死。即墨人曰：“安平之战，田单宗人以铁笼得全，是多智习兵。”因共立以为将以拒燕。乐毅围二邑，期年不克，及令解围，各去城九里而为垒，令曰：“城中民出者勿获，困者赈之，使即旧业，以镇新民。”三年而犹未下。或谗之于燕昭王曰：“乐毅智谋过人，伐齐，呼吸之间克七十馀城。今不下者两城耳，非其力不能拔，所以三年不攻者，欲久仗兵威以服齐人，南面而王耳。今齐人已服，所以未发者，以其妻子在燕故也。且齐多美女，又将忘其妻子。愿王图之！”昭王于是置酒大会，引言者而让之曰：“先王举国以礼贤者，非贪土地以遗子孙也。遭所传德薄，不能堪命，国人不顺。齐为无道，乘孤国之乱以害先王。寡人统位，痛之入骨，故广延群臣，外招宾客，以求报仇。其有成功者，尚欲与之同共燕国。今乐君亲为寡人破齐，夷其宗庙，报塞先仇，齐国固乐君所有，非燕之所得也。乐君若能有齐，与燕并为列国，结欢同好，以抗诸侯之难，燕国之福，寡人之愿也。汝何敢言若此！”乃斩之。赐乐毅妻以后服，赐其子以公子之服；辂车乘马，后属百两，遣国相奉而致之乐毅，立乐毅为齐王。乐毅惶恐不受，拜书，以死自誓。由是齐人服其义，诸侯畏其信，莫敢复有谋者。顷之，昭王薨，惠王立。惠王自为太子时，尝不快于乐毅。田单闻之，乃纵反间于燕，宣言曰：“齐王已死，城之不拔者二耳。乐毅与燕新王有隙，畏诛而不敢归，以伐齐为名，实欲连兵南面王齐。齐人未附，故且缓攻即墨以待其事。齐人所惧，唯恐他将之来，即墨残矣。”燕王固已疑乐毅，得齐反间，乃使骑劫代将而召乐毅。乐毅知王不善代之，遂奔赵。燕将士由是愤惋不和。
田单令城中人，食必祭其先祖于庭，飞鸟皆翔舞而下城中。燕人怪之，田单因宣言曰：“当有神师下教我。”有一卒曰：“臣可以为师乎？”因反走。田单起引还，坐东乡，师事之。卒曰：“臣欺君。”田单曰：“子勿言也。”因师之，每出约束，必称神师。乃宣言曰：“吾唯惧燕军之劓所得齐卒，置之前行，即墨败矣！”燕人闻之，如其言。城中见降者尽劓，皆怒，坚守，唯恐见得。单又纵反间，言：“吾惧燕人掘吾城外冢墓，可为寒心！”燕军尽掘冢墓，烧死人。齐人从城上望见，皆涕泣，共欲出战，怒自十倍。田单知士卒之可用，乃身操版、锸，与士卒分功；妻妾编于行伍之间；尽散饮食飨士。令甲卒皆伏，使老、弱、女子乘城，遣使约降于燕，燕军皆呼万岁。田单又收民金得千镒，令即墨富豪遗燕将，曰：“即降，愿无虏掠吾族家。”燕将大喜，许之。燕军益懈。田单乃收城中，得牛千馀，为绛缯衣，画以五采龙文，束兵刃于其角，而灌脂束苇于其尾，烧其端，凿城数十穴，夜纵牛，壮士五千人随其后。牛尾热，怒而奔燕军。燕军大惊，视牛皆龙文，所触尽死伤。而城中鼓噪从之，老弱皆击铜器为声，声动天地。燕军大骇，败走。齐人杀骑劫，追亡逐北，所过城邑皆叛燕，复为齐。田单兵日益多，乘胜，燕日败亡，走至河上，而齐七十馀城皆复焉。乃迎襄王于莒。入临淄，封田单为安平君。齐王以太史敫之女为后，生太子建。太史敫曰：“女不取媒，因自嫁，非吾种也，污吾世！”终身不见君王后，君王后亦不以不见故失人子之礼。
赵王封乐毅于观津，尊宠之，以警动于燕、齐。燕惠王乃使人让乐毅，且谢之曰：“将军过听，以与寡人有隙，遂捐燕归赵。将军自为计则可矣，而亦何以报先王这所以遇将军之意乎？”乐毅报书曰：“昔伍子胥说听于阖闾而吴远迹至郢；夫差弗是也，赐之鸱夷而浮之江。吴王不寤先论之可以立功，故沈子胥而不悔；子胥不蚤见主之不同量，是以至于入江而不化。夫免自立功以明先王之迹，臣之上计也。离毁辱之诽谤，堕先王之名，臣之所大恐也。临不测之罪，以幸为利，义之所不敢出也。臣闻古之君子，交绝不出恶声，忠臣去国，不洁其名。臣虽不佞，数奉教于君子矣。唯君王之留意焉！”于是燕王复以乐毅子闲为昌国君，而乐毅往来复通燕，卒于赵，号曰望诸君。
田单相齐，过淄水，有老人涉淄而寒，出水不能行。田单解其裘而衣之。襄王恶之，曰：“田单之施于人，将欲以取我国乎？不早图，恐后之变也。”左右顾无人，岩下有贯珠者，襄王呼而问之曰：“汝闻吾言乎？”对曰：“闻之。”王曰：“汝以为何如？”对曰：“王不如因以为己善。王嘉单之善，下令曰：‘寡人忧民之饥也，单收而食之；寡人忧民之寒也，单解裘而衣之；寡人忧劳百姓，而单亦忧之，称寡人之意。’单有是善而王嘉之，单之善亦王之善也。”王曰：“善。”乃赐单牛酒。后数日，贯珠者复见王曰：“王朝日宜召田单而揖之于庭，口劳之。乃布令求百姓之饥寒者，收穀之。”乃使人听于闾里，闻大夫之相与语者曰：“田单之爱人，嗟，乃王之教也！”
田单任貂勃于王。王有所幸臣九人，欲伤安平君，相与语于王曰：“燕之伐齐之时，楚王使将军将万人而佐齐。今国已定而社稷已安矣，何不使使者谢于楚王？”王曰：“左右孰可？”九人之属曰：“貂勃可。”貂勃使楚，楚王受而觞之，数月不反。九人之属相与语于王曰：“夫一人之身而牵留万乘者，岂不以据势也哉！且安平君之与王也，君臣无异而上下无别。且其志欲为不善，内抚百姓，外怀戎翟，礼天下之贤士，其志欲有为也，愿王之察之！”异日，王曰：“召相单而来！”田单免冠、徒跣、肉袒而进，退而请死罪，五日而王曰：“子无罪于寡人。子为子之臣礼，吾为吾之王礼而已矣。”貂勃从楚来，王赐之酒。酒酣，王曰：“召相单而来！”貂勃避席稽首曰：“王上者孰与周文王？”王曰：“吾不若也。”貂勃曰：“然，臣固知王不若也。下者孰与齐桓公？”王曰：“吾不若也。”貂勃曰：“然，臣固知王不若也。然则周文王得吕尚以为太公，齐桓公得管夷吾以为仲父，今王得安平君而独曰‘单’，安得此亡国之言乎！且自天地之辟，民人之始，为人臣之功者，谁有厚于安平君者哉？王不能守王之社稷，燕人兴师而袭齐，王走而之城阳之山中，安平君以惴惴即墨三里之城，五里之郭，敝卒七千人，禽其司马而反千里之齐，安平君之功也。当是之时，舍城阳而自王，天下莫之能止。然而计之于道，归之于义，以为不可，故栈道木阁而迎王与后于城阳山中，王乃得反，子临百姓。今国已定，民已安矣，王乃曰‘单’，婴儿之计不为此也。王亟杀此九子者以谢安平君，不然，国其危矣！”乃杀九子而逐其家，益封安平君以夜邑万户。
田单将攻狄，往见鲁仲连。鲁仲连曰：“将军攻狄，不能下也。”田单曰：“臣以即墨破亡馀卒破万乘之燕，复齐之墟，今攻狄而不下，何也？”上车弗谢而去，遂攻狄，三月不克。齐小儿谣曰：“大冠若箕，修剑拄颐。攻狄不能下，垒枯骨成丘。”田单乃惧，问鲁仲连曰：“先生谓单不能下狄，请问其说。”鲁仲连曰：“将军之在即墨，坐则织蒉，立则仗锸，为士卒倡曰：‘无可往矣！宗庙亡矣！今日尚矣！归于何党矣！’当此之时，将军有死之心，士卒先无之气，闻君言莫不挥泣奋臂而欲战，此所以破燕也。当今将军东有夜邑之奉，西有淄上之娱，黄金横带而骋乎淄、渑之间，有生之乐，无死之心，所以不胜也。”田单曰：“单之有心，先生志之矣。”明日，乃厉气循城，立于矢石之所，援袍鼓之。狄人乃下。
初，齐湣王既灭宋，欲去孟尝君。孟尝君奔魏，魏昭王以为相，与诸侯共伐破齐。湣王死，襄王复国，而孟尝君中立为诸侯，无所属。襄王新立，畏孟尝君，与之连和。孟尝君卒，诸子争立，而齐、魏共灭薛，孟尝君绝嗣。
赧王中三十七年（癸未，公元前二七八年）
秦大良造白起伐楚，拔郢，烧夷陵。楚襄王兵散，遂不复战，东北徙都于陈。秦以郢为南郡，封白起为武安君。
赧王中三十八年（甲申，公元前二七七年）
秦武安君定巫、黔中，初置黔中郡。
魏昭王薨，子安釐王立。
赧王中三十九年（乙酉，公元前二七六年）
秦武安君伐魏，拔两城。
楚王收东地兵，得十馀万，复西取江南十五邑。
魏安釐王封其弟无忌为信陵君。
赧王中四十年（丙戌，公元前二七五年）
秦相国穰侯伐魏。韩暴鸢救魏，穰侯大破之，斩首四万。暴鸢走开封。魏纳八城以和。穰侯复伐魏，走芒卯，入北宅。遂围大梁，魏人割温以和。
赧王中四十一年（丁亥，公元前二七四年）
魏复与齐合从。秦穰侯伐魏，拔四城，斩首四万。
鲁缗公薨，子顷公雠立。
赧王中四十二年（戊子，公元前二七三年）
赵人、魏人伐韩华阳。韩人告急于秦，秦王弗救。韩相国谓陈筮曰：“事急矣！愿公虽病，为一宿之行。”陈筮如秦，见穰侯。穰侯曰：“事急乎？故使公来。”陈筮曰：“未急也。”穰侯怒曰：“何也？”陈筮曰：“彼韩急则将变而他从；以未急，故复来耳。”穰侯曰：“请发兵矣。”乃与武安君及客卿胡阳救韩，八日而至，败魏军于华阳之下，走芒卯，虏三将，斩首十三万。武安君又与赵将贾偃战，沈其卒二万人于河。魏段干子请割南阳予秦以和。苏代谓魏王曰：“欲玺者，段干子也；欲地者，秦也。今王使欲地者制玺，欲玺者制地，魏地尽矣！夫以地事秦，犹抱薪救火，薪不尽，火不灭。”王曰：“是则然也。虽然，事始已行，不可更矣！”对曰：“夫博之所以贵枭者，便则食，不便则止。今何王之用智不如用枭也？”魏王不听，卒以南阳为和，实修武。
韩釐王薨，子桓惠王立。
韩、魏既服于秦，秦王将使武安君与韩、魏伐楚，未行，而楚使者黄歇至，闻之，畏秦乘胜一举而灭楚也，乃上书曰：“臣闻物至则反，冬、夏是也；致至则危，累棋是也。今大国之地，遍天下有其二垂，此从生民已来，万乘之地未尝有也。先王三世不忘接地于齐，以绝从亲之要。今王使盛桥守事于韩，盛桥以其地入秦，是王不用甲，不信威，而得百里之地，王可谓能矣！王又举甲而攻魏，杜大梁之门，举河内，拔燕、酸枣、虚、桃，入邢，魏之兵云翔而不敢救，王之功亦多矣！王休甲息众，二年而后复之，又并蒲、衍、首、垣以临仁、平丘，黄、济阳婴城而魏氏服。王又割濮磨之北，注齐、秦之要，绝楚、赵之脊，天下五合六聚而不敢救，王之威亦单矣！王若能保功守威，绌攻取之心，而肥仁义之地，使无后患，三王不足四，五伯不足六也！王若负人徒之众，仗兵革之强，乘毁魏之威，而欲以力臣天下之主，臣恐其有后患也。《诗》曰：‘靡不有初，鲜克有终。’《易》曰：‘狐涉水，濡其尾。’此言始之易，终之难也。昔吴之信越也，从而伐齐，既胜齐人于艾陵，还为越禽于三江之浦。智氏之信韩、魏也，从而伐赵，攻晋阳城，胜有日矣，韩、魏叛之，杀智伯瑶于凿台之下。今王妒楚之不毁，而忘毁楚之强韩、魏也，臣为王虑而不取也。夫楚国，援也；邻国，敌也。今王信韩、魏之善王，此正吴之信越也，臣恐韩、魏卑辞除患而实欲欺大国也。何则？王无重世之德于韩、魏而有累世之怨焉。夫韩、魏父子兄弟接踵而死于秦者将十世矣，故韩、魏之不亡，秦社稷之忧也。今王资之与攻楚，不亦过乎！且攻楚将恶出兵？王将借路于仇雠之韩、魏乎？兵出之日而王忧其不反也。王若不借路于仇雠之韩、魏，必攻随水右壤，此皆广川、大水、山林、溪谷，不食之地。是王有毁楚之名而无得地之实也。且王攻楚之日，四国必悉起兵以应王。秦、楚之兵构而不离；魏氏将出而攻留、方舆、铚、湖陵、砀、萧、相，故宋必尽；齐人南面攻楚，泗上必举。此皆平原四达膏腴之地。如此，则天下之国莫强于齐、魏矣。臣为王虑，莫若善楚。秦、楚合而为一以临韩，韩必敛手而朝；王施以东山之险，带以曲河之利，韩必为关内之侯。若是而王以十万戍郑，梁氏寒心，许、鄢陵婴城而上蔡、召陵不往来也。如此，魏亦关内侯矣。王壹善楚而关内两万乘之主注地于齐，齐右壤可拱手而取也。王之地一经两海，要约天下，是燕、赵无齐、楚，齐、楚无燕、赵也。然后危动燕、赵，直摇齐、楚，此四国者不待痛而服矣。”
王从之，止武安君而谢韩、魏，使黄歇归，约亲于楚。', '', '', '周纪四周赧王十八年（甲子，公元前297年）
楚怀王逃脱看守，被秦国人发现，封锁通往楚国的道路。楚怀王从小路逃到了赵国，正逢赵主父外出在代郡，赵国官员不敢作主收留他。楚怀王又想逃奔魏国，却被秦国人追上，抓回秦国。
鲁国鲁平公去世，其子姬贾即位为鲁缗公。
十九年（乙丑，公元前296年）
楚怀王发病，死在秦国。秦国送回他的灵柩，楚国人见了都十分悲痛，像死了自己的亲人一样。各国诸侯因此也对秦国不满。
齐、韩、魏、赵、宋五国共同出兵攻打秦国，到了盐氏地方即行撤回。秦国把武遂归还韩国，把封陵归还魏国，以求和解。
赵主父视察新获取的领土，离开代郡，向西在西河会见楼烦王，接受了他的部队。
魏国魏襄王去世，其子即位为魏昭王。
韩国韩襄王去世，其子韩咎即位为韩王。
二十年（丙寅，公元前295年）
秦国国尉司马错进攻魏国襄城。
赵主父与齐国、燕国联合灭掉中山国，把中山王迁到肤施居住。赵主父回来后，论功行赏，大赦罪人，设酒庆祝，全国欢宴五天。
赵主父把长子赵章封到代，号称安阳君。
安阳君平素为人骄横，内心对弟弟立为王十分不服。赵主父派田不礼做他的国相。李兑对肥义说：“公子赵章身强力壮而怀有野心，党羽众多而贪欲极大，田不礼又残忍好杀，十分狂妄，两人互相勾结，必定会图谋不轨。小人有了野心，就要轻举妄动，他只看到想获取的利益，看不到带来的危害。一场灾难就在眼前了。你身居要职，权势很大，你将成为动乱的由头，灾祸也将集中在你身上。你何不称病不出，把朝政交给公子赵成去处理，免得被祸事牵连。这样不好吗！”肥义说：“当年赵主父把赵王嘱托给我，说：‘不要改变你的宗旨，不要改变你的心意，要坚守一心，至死效忠！’我再三拜谢承命并记录在案。现在如果怕田不礼加祸于我而忘掉当年的记录，就是莫大的背弃。俗话说崐：‘面对复生的死者，活着的人无需感到惭愧。’我要维护我的诺言，哪能光顾保全生命！你对我的建议是一片好心，但是我已有誓言在先，决不敢放弃！”李兑说：“好，你勉力而为吧！能见到你恐怕只有今年了。”说罢流泪而出。
李兑几次入见公子赵成，商议防备田不礼。肥义对信期说：“公子赵章与田不礼语言动听而本质凶恶，在内讨得主父的欢心，在外恣意施暴。他们一旦假借主父的命令来发动政变，是很容易得手的。现在我忧虑此事，已到了废寝忘食的程度。强盗在身边出入不能不防！从此以后，有人奉主父命来召见赵王必须先见我的面，我将先前往，没有变故，赵王才能去。”信期说：“好。”
赵主父让赵惠文王朝见群臣，自己在旁边窥察，只见当哥哥的赵章反而俯首称臣，无精打采地听高高在上的弟弟赵何训示，心中有些不忍，于是想把赵国一分为二，让赵章在代郡称王，但这个计划还没有最后决定就搁置起来。赵主父和赵王出游沙丘，分别住在两个行宫里。赵章、田不礼乘机率领门徒作乱，他们假称赵主父的命令召见赵王，肥义先进去，被杀死。高信便与赵王一同抵抗。公子赵成与李兑从国都邯郸赶来，发动四邑的军队入宫镇压叛乱，杀死赵章及田不礼，处死全部党羽。公子赵成担任相国，称为安平君；李兑被任命为司寇。当时赵惠文王还年幼，政权都掌握在公子赵成、李兑手中。
赵章败退的时候，逃到赵主父那里，赵主父开门接纳了他。公子赵成、李兑于是带兵包围了赵主父的行宫。杀死赵章后，公子赵成、李兑商议道：“我们为追杀赵章，竟包围了主父的行宫，如此大罪，要是撤兵回去，会被满门抄斩的！”于是又下令围住赵主父行宫，宣布：“宫中人晚出来的杀！”宫中的人听见命令全部逃出，赵主父想出来却不被准许，又得不到食物，只好捕捉幼鸟吃，三个多月后，他终于饿死在沙丘行宫中。直到赵主父确死无疑，赵国才向各国报告丧事。起初，赵主父定长子赵章为太子，后来他娶了美女吴娃，十分宠爱，曾经几年不出宫上朝。生下儿子赵何后，便废去太子赵章，立赵何为太子。吴娃死后，赵主父对赵何的偏爱也逐渐减退，又可怜起原来的太子，想立两个王。他总是犹豫不决，所以引起了内乱。
秦国罢免楼缓的丞相，由魏冉代任。
二十一年（丁卯，公元前294年）
秦国在解击败魏国军队。
二十一年（戊辰，公元前293年）
韩国派大将公孙喜联合魏国攻打秦国。秦国穰侯把任左更之职的白起推荐给秦王，代替向寿统率秦军，结果在伊阙大败韩、魏联军，杀死二十四万人，活捉公孙喜，夺取五座城。秦王便任命白起为国尉。
秦王送信给楚王，写道：“楚国背叛了秦国，秦国将率领各国来讨伐楚国，希望你整顿好军队，我们痛痛快快地打一仗！”楚王十分恐惧，只好再与秦国修好结亲。
二十三年（己巳，公元前292年）
楚襄王从秦国迎娶新娘。
臣司马光曰：秦国真是太不讲道理了，害死楚怀王又逼迫其子楚襄王；楚国也太不争气了，忍下杀父之仇而与敌人通婚！呜呼！楚国君王如果能坚持正确的治国之道，对臣下任用得人，秦国虽然强大，又怎能肆意欺凌它呢！荀况说得好：“治国之道，善于掌握则仅有百里方圆的地方也可以独立于天下，不善于掌握哪怕像楚国有六千里国土也只能被仇人所驱使。”所以君王不认真讲求治国之道，只一味制造声势，正是走向危亡的原因。
秦国魏冉因病辞去职务，以客卿烛寿为丞相。
二十四年（庚午，公元前291年）
秦国进攻韩国，攻克宛。
秦国免去烛寿职务，魏冉再度出任丞相，受封穰、陶两地，称为穰侯。秦国又把宛封给公子，把邓封给公子悝。
二十五年（辛未，公元前290年）
魏国把河东地方圆四百里、韩国把武遂地方圆二百里献给秦国。
魏国芒卯以诈术开始受到重用。
二十六年（壬申，公元前289年）
秦国派大良造白起、客卿司马错进攻魏国，抵达轵地，夺取大小城镇六十一座。
二十七年（癸酉，公元前288年）
冬季，十月，秦王自称西帝，派使者建议齐王立为东帝，想约定两国共同进攻赵国。苏代从燕国前来，齐王便问他：“秦国派魏冉来劝我帝，你的意见如何？”苏代回答说：“我建议大王先予以接受，但暂时不称帝。秦王称帝后，天下如果不表示反对，大王再称帝，也不算晚。秦王称帝如果遭到天下指责，大王就不再称帝，趁势收买天下人心，这是个大资本。况且进攻赵国与进攻有夏桀恶名的宋国，哪个有利呢？现在大王不如暂时放弃帝号以使天下归心，然后发兵讨伐‘桀宋’，征服宋国后，楚国、赵国、魏国、卫国都会恐崐惧臣服。这样，我们名义上尊重秦国而让天下去憎恨它，正是齐国反卑为尊的计策。”齐王采纳了他的建议，只称帝两天便放弃了。十二月，吕礼从齐国到秦国，秦王也去掉帝号，仍旧称王。
秦国攻打赵国，攻克杜阳。
二十八年（甲戌，公元前287年）
秦国攻打赵国，夺取新垣、曲阳。
二十九年（乙亥，公元前286年）
秦国派司马错攻击魏国河内，魏国献出安邑求和，秦国将城内人民驱赶回魏国。
秦国在夏山打败韩国军队。
宋国发生雀鸟在城边生下鹞鹰的怪事，太史卜了一卦，说：“吉利。小而生大，必霸天下。”宋康王大喜，起兵灭掉滕国，攻占薛地，向东击败齐国，夺取五座城，向南战胜楚国，占地方圆三百里，向西打垮魏军，宋国一时成为可与齐国、魏国相匹敌的国家，宋康王对成就霸业更加自信。他想早日完成霸业，便射天鞭地，砍倒神坛后烧毁，以表示自己的声威可以镇慑鬼神。他在宫室中整夜饮酒，令室中的人齐声高呼万岁，大堂上的人闻声响应，堂下的人接着响应，门外的人又继续响应，以至于国中没有人敢不呼万岁。天下的人都咒骂他是“桀宋”。齐王趁机起兵征伐宋国，人民四下逃散，弃城不守。宋王只好逃往魏国，死于温地。
三十年（丙子，公元前285年）
秦王与楚王在宛相会，与赵王在中阳相会。
秦国派蒙武攻击齐国，夺取九座城。
齐王灭掉宋国后十分骄傲，便向南侵入楚国，向西攻打赵、魏、韩国，想吞并东西二周，自立为天子。狐义正辞严地劝谏他，被斩首于檀台大路上。陈举直言不讳地劝止，被杀死在东门。
燕昭王却日夜安抚教导百姓，使燕国更加富足，于是他与乐毅商议进攻齐国。乐毅说：“齐国称霸以来，至今有余力，地广人多，我们独力攻打不易。大王一定要讨伐它，不如联合赵国及楚、魏三国。”燕王便派乐毅约定赵国，另派使者联系楚国、魏国，再让赵国用讨伐齐国的好处引诱秦国。各国苦于齐王的骄横暴虐，都争相赞成参加燕国的攻齐战争。
三十一年（丁丑，公元前284年）
燕王调动全部兵力，以乐毅为上将军。秦国尉斯离率军队与韩、赵、魏联军也前来会合。赵王把相国大印授给乐毅，乐毅统一指挥秦、魏、韩、赵大军发动进攻。齐王集中国内全部人力进行抵御，双方在济水西岸大战。齐国军队大败。乐毅便退回秦国、韩国军队，令魏国军队分兵进攻宋国旧地，布署赵国军队去收复河间。自己率领燕军，由北长驱直入齐国。剧辛劝说道：“齐国大，燕国小，依靠各国的帮助我们才打败齐军，应该及时地攻取边境城市充实燕国领土，这才是长久的利益。现在大军过城不攻，一味深入，既无损于齐国又无益于燕国，只能结下深怨，日后必定要后悔。”乐毅说：“齐王好大喜功，刚愎自用，不与下属商议，又罢黜贤良人士，专门信任谀谄小人，政令贪虐暴戾，百姓十分怨愤。现在齐国军队已溃不成军，如果我们乘胜追击，齐国百姓必然反叛，内部发生动乱，齐国就可以收拾了。如果不抓住时机，等到齐王痛改前非，体贴臣下而抚恤百姓，我们就难办了。”于是下令进军深入齐国。齐国果然大乱，失去常度，齐王出逃。乐毅率军进入齐都临淄，搜刮宝物和祭祀重器，运回燕国。燕王亲自到济水上游去慰劳军队，颁行奖赏，犒劳将士；燕王封乐为昌国君，让他留在齐国进攻其余未克的城市。
齐王出逃到卫国，卫国国君让出宫殿给他居住，向他称臣并供给日常用度。齐王却傲慢不逊，卫国人气愤地攻击他，齐王又出奔到邹、鲁国，仍旧面有骄色；邹、鲁两地闭门不纳，齐王又出奔莒地。楚国派淖齿率军前来救援齐王，被任命为齐相。淖齿却想与燕国瓜分齐国，于是抓住齐王数说他的罪过：“千乘、博昌之间的方圆几百里地，下血雨浸湿衣服，你齐王知道吗？”齐王回答：“知道。”“嬴、博之间，大地崩塌，泉水上涌，你齐王知道吗？”回答：“知道。”“有人堵着宫门哭泣，却不见人影，离开时又音响可闻，齐王你知道吗？”回答：“知道。”淖齿说：“天降血雨，是上天警告你；地崩泉涌，是大地警告你；人堵着宫门哭，是人心在警告你。天、地、人都警告，而你却不知改悔，你还想不死吗！”于是在鼓里这个地方将齐王处死。
荀况论之曰：国家，集中了天下的利益和权势。有道行的人主持，可以得到大的安乐，大的荣耀，成为幸福的源泉。无道行的人主持，却带来大的危险，大的拖累，有君王的地位还不如没有；等到形势极度恶化，他即使想当一个普通老百姓，也做不到了。齐王、宋康王便是如此。
所以治理国家的君主如果提倡礼义，就可以称王，树立信誉就可以称霸，玩弄权术则必然灭亡。
领导国家提倡礼义，就无人可以加害于他。即使做一件坏事、杀一个无辜的人便可以得到天下，仁爱的人也不会去干。君主守定意志，维护国家，坚如磐石，以此礼待他人，就可以产生众多的仁人志士。以此条陈布置国家刑事法律，就可以制定出良好的法律。君主极力如此主张，再率领群臣以身作则，就可以树立起礼义的风尚。这样，属下能够以礼义纲常尊崇上司，统治基础就稳定了，基础稳定国家便安定，国家安定则天下平定。因此说：用国家的权力推行礼义，一天就可以做到众人皆知，商汤王、周武王便是如此，即所谓的以提倡礼义而称王。
即使道德还未达到完美，礼义也没有做到完善，然而已经可以掌握治理天下的大致条理。做到赏罚分明，取得天下的信任，使臣属清楚地看到它的重要性。政令一经颁布，不管成功还是失败，都不欺骗百姓；条约已经缔结，不管有利还是无利，都不欺骗合作的邻国。这样，才能军队强劲，城池坚固，使敌对国家畏惧。国家的方针一贯而明确，友邦就予以信任。即使是偏僻的小国，也可以威震天下。春秋时期的齐、晋、宋、秦、楚五霸主便是如此，即所谓的以树立信誉而称霸。
带领国家追逐功利，不申张正义，不遵守信用，唯利是图；对内不惜为了一点小利去欺骗人民，对外为了追求大的利益不怕欺骗友邦。对内不好好治理自己已有的东西，却常常觊觎别人的成果。这样，臣下百姓就无不以奸诈之心对待上司。上欺下，下瞒上，于是上下关系分崩离析。这样，便使敌对国家轻视，友好国家不信任，权术泛滥而国家日益削弱，走向极端，终于灭亡，齐王、孟尝君便是如此。齐王要强大齐国，不去提倡礼义，不去修明政治，不去统一天下的思想，只是成年累月地骑马在外面征战。所以齐国强大的时候，向南能够打败楚国，向西能够逼迫秦国，向北可以战胜燕国，在中原能够征服宋国。然而燕国、赵国一旦群起而攻齐，便如摧枯拉朽。齐王身死国亡，成为天下共同声讨的对象，后世提起暴君总要举他为例。这不是别的原因，就是因为他不崇尚礼义而沉溺权术。
以上三种，贤明的君王必须慎重地加以抉择，仁人志士必须认真地予以辨明。善于抉择的人可以控制别人，不善于抉择的人则被别人控制。
乐毅听说昼邑人王贤良，下令围绕昼邑三十里周围不得进入军队，又派人请王，王辞谢不去。燕国人威胁说：“你要是不来，我们就在昼邑屠城！”王叹息说：“忠臣不事二君，烈女不更二夫。国破君亡，我不能使崐之保存，而自身又被燕人逼迫，我与其苟且偷生，不如一死！”于是把脖子系在树枝上，纵身一跃，自尽而死。燕国军队乘胜长驱直入，齐国大小城市望风崩溃。乐毅整肃燕军纪律，禁止侵掠，寻访齐国的隐士高人，致以荣誉礼待。还放宽人民赋税，革除苛刻的法令，恢复齐国旧的良好传统，齐国人民都十分喜悦。乐毅于是调左军在胶东东莱渡过胶水；前军沿泰山脚下向东到达渤海，进攻琅邪；右军循着黄河、济水而下，屯扎在东阿、鄄城，与魏国军队相连；后军沿北海镇抚千乘，中军占据临淄，镇守齐国国都。他还亲至城郊祭祀齐桓公、管仲，表彰齐国的贤良人才，赐封修治王的陵墓。经过收敛人心，齐国人接受燕国所封君号、领取俸禄的有二十余人；接受燕国爵位的有一百多人。六个月之内，燕军攻下齐国七十余座城，都设立郡县治理。
秦王、魏王、韩王在周朝京师相会。
三十二年（戊寅，公元前283年）
秦国、赵国在穰地举行会议。秦国攻克魏国安城，一直打到魏国首都大梁才退回。
齐国发生淖齿杀王之乱时，齐王的儿子田法章改名易姓躲到莒地太史敫家做雇工。太史敫的女儿惊奇田法章的像貌伟岸，认为不是普通人的气质，便可怜他，常常私下送给他衣服和食物，久而久之，两人已暗中结为夫妻。王孙贾是齐王的随臣，乱中找不到主子的下落，他的母亲说：“你早出晚归，我倚着大门盼望；你夜出不回，我靠着街门等待。你如今服侍君王，君王离开了，你却不知道他的下落，你还回来做什么！”王孙贾便来到集市振臂高呼：“淖齿搞乱齐国，杀害王。愿意和我一起去干掉他的就把右臂伸出来！”集市上的人有四百多人随他前去攻击淖齿，把他杀掉了。于是齐国的大臣们四下搜寻齐王的儿子，想立他为王。田法章害怕人们加害自己，过了很久才敢自己说明身份，于是大家拥立他为齐王，坚守莒城以抵抗燕军。在全国宣布：“齐王已经在莒地即位了！”
赵王得到楚国宝玉和氏璧，秦昭王想要，愿意用十五座城来交换。赵王想不给他，又畏惧秦国的强大；给他，又怕被秦王欺骗。便征求蔺相如的意见。蔺相如回答说：“秦国用城来换宝玉而大王不允许，是我们理屈。而我们给他宝玉，他不给我们城，是秦国理屈。衡量两种办法，我看宁可让秦国在道义上有负于我们。我愿护持宝玉前去，假如秦国不交出城来，我一定能完璧归赵。”赵王便派他前往。蔺相如到了秦国，看出秦王并无真意用城来换赵国的宝玉，就哄骗秦王，取回和氏璧，派随从藏在怀中，从小道潜回赵国，而他自己留下来听任秦王的处置。无奈之际，秦王只好称赞蔺相如的贤能，不但不杀他，反而以礼相待，送他回国。蔺相如回到赵国，赵王封他为上大夫。
卫国卫嗣君去世，其子即位为卫怀君。卫嗣君在位时喜好侦察别人的崐隐私。有个县令曾掀开褥子，露出下面的破席子。卫嗣君听说了，便赏赐给他一领新席。县令大惊，以为国君liào事如神。卫嗣君还曾派人经过关卡，用金钱贿赂掌关的官员。事后把掌关官员召来，指令说有客人过关时给了你金了，你快退回去。掌关官员十分惊恐。卫嗣君还宠爱泄姬，器重臣子如耳，但又怕这两人因受到宠爱器重而敢于欺瞒自己，于是提升另一个臣子薄疑来与如耳匹敌，尊崇魏妃来与泄姬分庭抗礼，说：“以此可互相参列比较。”
荀况论曰：卫成侯和卫嗣君，都是斤斤计较的小器量国君，没有做到招揽民心。郑国大臣子产，能招揽民心，但没有做到为政精明。齐国大臣管仲，能为政精明，但没有做到倡导礼义。由此而见，倡导礼义的人才能称王，治政精明的人可以使国家富强，招揽民心的人可以使国家安定，而搜刮者只能灭亡。
三十三年（己卯，公元前282年）
秦国攻打赵国，夺取两座城。
三十四年（庚辰，公元前281年）
秦国又攻打赵国，夺取石城。
秦穰侯魏冉再任丞相。
楚国想联合齐国、韩国共同进攻秦国，顺便灭掉周王朝。周王派东周的武公对楚国任令尹职的昭子说：“周朝可不能算计。”昭子说：“要说算计周朝，那是没有的事。尽管如此，我想问你，周朝为什么不能灭掉？”武公回答：“西周现在的地盘，取长补短，也不过方圆一百里。抢占这块地方并不足以使哪个国家富强，得到那里的百姓也不足以壮大军队。但西周却有天下共同拥戴的宗主名义，谁攻打它，谁就是犯上作乱。尽管如此，还是有人想去攻占它，是何原因呢？就是因为古代传下来的祭祀重器在那里。老虎的肉腥臊而又有尖牙利爪，仍有人猎取它；山林中的麋鹿没有爪牙之利，假如再给它披上一张诱人的虎皮，人们猎取它的欲望一定会增加万倍。楚国的情形正是这样，分割楚国的领土，足以使自己富庶；讨伐楚国的名义，又足以有尊崇周王室的声名。楚国要是残害了天下共同拥戴的周王朝，占有了夏、商、周三代相传的礼器，你刚把礼器运回南方，各国证讨的大兵也就到了！”令尹昭子觉得言之有理，于是放弃了楚国原来的打算。
三十五年（辛巳，公元前280年）
秦国大将白起打败赵国军队，杀死二万人，夺取代地光狼城。秦国又派司马错调动陇西军队，从蜀地进攻楚国黔中郡，予以攻占。楚国被迫献出汉水以北及上庸地方。
三十六年（壬午，公元前279年）
秦国大将白起攻打楚国，占领鄢、邓、西陵等地。
秦王派使者通知赵王，愿意在黄河外的渑池和好相会。赵王不想赴会，廉颇、蔺相如建议说：“大王若是不去，就显得赵国懦弱而又胆怯。”赵王于是决定前往，由蔺相如随行。廉颇送到边境，与赵王告别时说：“大王此行，估计加上路程时间，到会议仪式全部结束，不超过三十天就会回来，如果超过三十天您还没有回来，请允许我们立太子为赵王，以断绝秦国的要挟念头。”赵王同意。
渑池相会，秦王与赵王饮酒。酒兴之间，秦王请赵王表演鼓瑟，赵王便演奏了。蔺相如也请秦王表演敲击瓦盆的音乐，秦王却不肯。蔺相如厉色说道：“在五步之内，我就可以血溅大王！”秦王左右卫士想上前杀死蔺相如，蔺相如怒目喝斥，左右人都畏缩不敢行动。秦王只好非常不情愿地敲了一下瓦盆。直到酒宴结束，秦国始终不能对赵国加以非分之求。再加上赵国人也早有军队戒备，秦国到底没敢轻举妄动。赵王回国，加封蔺相如为上卿之职，地位在大将廉颇之上。
廉颇不满地说：“我作为赵国大将，有攻城野战之功，蔺相如原不过是下层小民，只以能说善辩而位居我之上，我实在感到羞耻，忍不下这口气！”便宣称：“我遇到蔺相如，一定要羞辱他一番！”蔺相如听说后，不愿意和他遇见。每逢上朝，常常称病，不和廉颇去争排列顺序。出门在外，远远望见廉颇的车驾，便令自己的车回避。蔺相如的门客下属都感到十分羞耻。蔺相如对他们说：“你们看廉将军的威严比得上秦王吗？”回答都说：“比不上。”蔺相如说：“面对秦王那么大的威势，我都敢在他的朝廷上叱责他，羞辱他的群臣，我虽然无能，难道单单怕廉将军吗！我是考虑到：强暴的秦国之所以还不敢大举进犯赵国，就是因为我和廉将军在。我们两虎相争，必有一伤。我所以避让，是先考虑到国家的利益而后才去想个人的私怨啊！”廉颇听说了这番话十分惭愧，便赤裸着上身到蔺相如府上来负荆请罪，两人从此结为生死之交。
当初，燕国军队攻打齐国安平时，临淄市的一个小官田单正在城中，他预先让家族人都用铁皮包上车轴头。待到城破，人们争相涌出城门，都因为车轴互相碰断，车辆损坏难行，被燕军俘虏，只有田单一族因铁皮包裹车轴得以幸免，逃到了即墨。当时齐国大部分地区都被燕军占领，仅有莒城、即墨未沦陷。乐毅于是集中右军、前军包围莒城，集中左军、后军包围即墨。即墨大夫出战身亡。即墨人士说：“安平之战，田单一族人因铁皮包轴得以保全，可见田单足智多谋，熟悉兵事。”于是共同拥立他为守将抵御燕军。乐毅围攻两城，一年未能攻克，便下令解除围攻，退至城外九里处修筑营垒，下令说：“城中的百姓出来不要抓捕他们，有困饿的还要赈济，让他们各操旧业，以安抚新占地区的人民。”过了三年，城还未攻下。有人在燕昭王面前挑拨说：“乐毅智谋过人，进攻齐国，一口气攻克七十余城。现在只剩两座城，不是他的兵力不能攻下，之所以三年不攻，就是他想倚仗兵威来收服齐国人心，自己好南面称王而已。如今齐国人心已服，他之所以还不行动，就是因为妻子、儿子在燕国。况且齐国多有美女，他早晚将忘记妻子。希望大王早些防备！”燕昭王听罢下令设置盛大酒宴，拉出说此话的人斥责道：“先王倡导全国礼待贤明人才，并不是为了多得土地留给子孙。他不幸遇到继承人缺少德行，不能完成大业，使国内人民怨愤不从，无道的齐国趁着我们国家动乱得以残害先王。我即位以后，对此痛心疾首，才广泛延请群臣，对外招揽宾客，以求报仇。谁能使我成功，我愿意和他分享燕国大权。现在乐毅先生为我大破齐国，平毁齐国宗庙，报却了旧仇，齐国本来就应归乐先生所有，不是燕国该得到的。乐先生如果能拥有齐国，与燕国成为平等国家，结为友好的邻邦，抵御各国的来犯，这正是燕国的福气、我的心愿啊！你怎么敢说这种话呢！”于是将挑拨者处死。又赏赐乐毅妻子以王后服饰，赏赐他的儿子以王子服饰，配备君王车驾乘马，及上百辆属车，派宰相侍奉送到乐毅那里，立乐毅为齐王。乐毅十分惶恐，不敢接受，一再拜谢，写下辞书，并宣誓以死效忠燕王。从此齐国人敬服燕国乐毅的德义，各国也畏惧他的信誉，没有再敢来算计的。
不久，燕昭王去世，燕惠王即位。惠王从当太子时，就与乐毅有矛盾。田单听说了，便派人去燕国用反间计，散布说：“齐王已经死了，齐国仅有两座城未被攻克。乐毅与燕国新王有矛盾，害怕加祸不敢回国，他现在以攻打齐国为名，实际想率领军队在齐国称王。齐国人没有归附，所以他暂缓进攻即墨，等待时机举行大事。齐国人所怕的，是燕王派别的大将来，那样即墨就城破受害了。”燕惠王本来就疑心乐毅，中了齐国的反间计，便派骑劫代替乐毅为大将，召他回国。乐毅知道燕王换将居心不良，于是投奔了赵国。从此，燕军将士都愤愤不平，内部不和。
这时，田单下令让城中人吃饭时，先在庭院里祭祀祖先，四处飞鸟争吃祭饭都盘旋落到城中，燕军很是惊讶，田单又让人散布说：“会有天神派军师下界来帮助我们。”有个士兵说：“我可以做神师吗？”说罢起身便走。田单急忙离座追回他，让他面东高坐，奉为神师。士兵说：“我犯上欺主了。”田单忙悄声嘱咐：“你不要说出去。”便以他为师，每当发布号令，都必称奉神师之命。田单又令人散布说：“我就怕燕军把齐国俘虏割去鼻子，作为前导，那样即墨城就完了！”燕国人听说，果然这样做了。城中守兵看到投降燕军的人都被割去鼻子，万分痛恨，决心坚守不降，唯恐被俘。田单再使出反间计，说：“我怕燕军掘毁我们的城外坟墓，那样齐国人就寒心了。”燕军又中计，把城外坟墓尽行挖毁，焚烧死尸。齐国人从城上远远望见，都痛哭流涕，争相请求出战，怒气倍增。田单知道这时军士已经可以死战，于是带头拿起版、锹和士卒一起筑城，把自己的妻妾编进军队，还分发全部食品犒劳将士。他下令让披甲士兵都潜伏在城下，只以老弱人员、女子登城守卫，又派人去燕军中约定投降，燕军都欢呼万岁。田单在城中百姓中募集到一千镒金银，让即墨城的富豪送给燕军大将，说：“我们马上就投降。请不要抢劫掠夺我们的家族！”燕国将军大喜，立刻应允。燕军戒备更加松懈。田单在城中搜罗到一千余头牛，给牛披上大红绸衣，绘上五彩天龙花纹，在牛角上绑束尖刀，而在牛尾绑上灌好油脂的苇草，然后点燃，趁着夜色，从预先凿好的几十个城墙洞中，赶牛冲出，后而紧随着五千名壮士。牛尾部被火燎烧，都惊怒地奔向燕军大营。燕军大惊失色，看到牛身上都是天龙花纹，碰到的不是死就是伤。加上城中敲锣打鼓齐声呐喊，老弱居民也敲击铜器助威，响声惊天动地。燕国军队万分恐惧，纷纷败逃。齐军趁乱杀死燕军大将骑劫，追杀逃亡的燕军，所经过的城邑都叛离燕国，再度归顺齐国。田单的军队越来越多，乘胜而入，燕军日日望风而逃，逃到黄河边，齐国失去的七十几座城都复归。田单于是前往莒城迎齐襄王回国都临淄，襄王册封田单为安平君。
齐襄王立太史敫的女儿为王后，生下太子田建。太史敫却说：“我的女儿不经过媒人，自定婚嫁，不是我家的人，她败坏了我的家风！”终身不见王后，但王后并不因他不见而失去做儿女应有的礼数。
赵王分封乐毅于观津，对他十分尊宠。以此来警戒燕国和齐国。燕惠王便派人去批评乐毅，并道歉说：“乐将军你过于听信传言，因为与我有矛盾，就抛弃燕国跑到赵国。你这样做为自己打算是可以的，然而，又怎能报答先王对你的一片恩情呢？”乐毅回信答复道：“从前伍子胥的建议被吴王阖闾采纳，吴国的势力一直扩展到郢地；而继任吴王夫差不听他的话，把伍子胥的尸体装入皮囊抛进江中。夫差不明白伍子胥对先王的建议是吴国得以成就功业的根本，所以沉下伍子胥的尸体一点儿也不后悔。伍子胥不能早日看出不同的君王有不同的器量，所以尸体虽入江而魂灵仍怨愤不化。免去自身的灾祸，立就功业，以表明先王的心迹，是我的上策。自己遭到别人的诽谤，从而使先王的英名蒙上耻辱，是我最害怕的。但因为蒙受了不白之冤，就以新的宠幸为利益，谋算燕国，也是我在道义上绝不会做的。我听说古代的君子，与人断交绝不口出恶言；忠臣被迫离开祖国，也不去辩解洗雪自己的名声。我虽然不成器，也曾多次从古代君子身上得到教益。谨请大王明鉴。”于是燕王仍封乐毅的儿子乐为昌国君，而乐毅也为修好睦邻而往来燕国，最后死于赵国，谥号望诸君。
田单出任齐国国相，有次路过淄水，见到一个老人渡淄水时冻得直哆嗦，走出水面时已不能前行。田单便解下自己的皮袍给他披上。齐襄王听说后十分厌恶，说：“田单对别人施恩，是打算夺我的国位，我不早下手，恐怕以后会有变故！”说完一看左右无人，只在殿阶下有个穿珠子的人，襄王便召他过来问道：“你听见我的话了吗？”回答：“听见了。”襄王问：“你觉得怎么样？”回答说：“大王不如把此事变成自己的善行。大王可以嘉奖田单的善心，下令说：‘我忧虑人民的饥饿，田单就收养他们，供给饮食；我忧虑人民的寒冷，田单就脱下皮袍给他们披上；我忧虑人民的操劳，田单也因此忧虑。他正符合我的心意。‘田单有善行而大王嘉奖他，那么田单的善行也就是大王的善行了。”襄王说：“好。”于是赏赐田单酒宴。过了几天，穿珠子的人又来见齐襄王说：“大王应该在群臣朝见时召见田单，在殿庭上致谢，亲自慰劳他。然后布告国内寻找百姓中饥饿者，予以收养。”襄王这样做后，派人到街头里巷去探听，听到大夫等官员互相说：“哦！田单疼爱百姓，是大王的教诲呀！”
田单向齐王推荐貂勃。齐王的九个宠幸臣子都想中伤田单。争相对齐王说：“燕国攻打齐国时，楚王曾派将军率一万军队来帮助齐国。现在齐国已经安定，社会也日趋稳固，何不派使者前去楚国道谢？”齐王问：“左右的人谁合适？”九个人都说：“貂勃可以。”貂勃出使楚国，楚王予以热情款待，几个月不放他回去。九个人又一齐对齐王说：“以貂勃一个人的地位能受到万乘车马的楚国重视，难道不是倚仗了田单的权势吗！田单与大王之间，不分君臣上下，况且他心怀不良之志，对内安抚百姓，对外关怀狄族，礼待天下的贤良人才，他的志向是想大有作为，希望大王明察！”过了几天，齐王喝道：“召国相田单来！”田单非常惊恐，摘下帽子，光着脚，赤裸上身前来，退下时请齐王治他的死罪。过了五天，齐王却说：“你没有得罪我。只不过要你行你臣子的礼节，我守我君王的礼节而已。”貂勃从楚国回来，齐王赐宴招待。饮到兴头上，齐王又喝道：“召国相田单来！”貂勃离开座位下拜说：“大王上比周文王如何？”齐王回答：“我不如。”貂勃说：“是的，我本知道大王不如崐。那么下比齐桓公如何？”齐王回答：“我也不如。”貂勃又说：“是的，我也知道大王不如。然而周文王得到吕尚，尊为太公；齐桓公得到管仲，敬为仲父。现在大王您得到安平君田单，却直呼‘田单’，怎么能说这种亡国的话呢？何况自开天辟地，有人民起，做臣子的功劳，谁能比安平君更高？当年大王不能承守祖业，在燕国起兵袭击齐国时，大王逃到城阳的山里，安平君以人心危恐的即墨方圆三五里城郭，疲惫不堪的七千名士兵，力擒敌军大将，收复齐国千里领土，这些都是安平君的功劳呀！如果当时他置城阳的大王不顾，自立为王，天下没有谁能阻止。然而他从道德礼义考虑，认为坚决不能那样做，所以修筑栈道木阁前去城阳山中迎接大王和王后，大王您才能得以回归，治理百姓子民。现在国家已经稳定，人民已经安宁，大王却‘田单、田单’地叫，小孩子也知道不该这样做。大王您赶快杀掉那九个家伙向安平君谢罪；不然，国家就危险了！”齐王听从指责，杀掉了那九个幸臣并流放其家族，加封给安平君掖邑地方的一万户俸禄收入。
田单准备攻打狄族，前去见鲁仲连，鲁仲连说：“将军您去攻狄，恐怕攻不下来。”田单说：“当年我以即墨的残兵败将击破拥有万乘战车的燕军，光复齐国沦亡土地；现在会攻不下狄族，有什么道理？”上车扬长而去。于是田单率军进攻狄族，三个月也未能攻克。齐国小孩子在歌谣中讥讽唱道：“大冠像簸箕，长剑撑面皮，攻狄不能下，枯骨垒成丘。”田单开始惊惧起来，又去问鲁仲连：“先生早日说我攻不下狄族，请让我知道原因。”鲁仲连说：“将军在即墨的时候，坐着，手编草鞋；站着，手拿铁锹；带领士兵们唱歌道：‘无可往矣！宗庙亡矣！今日有没有救，看我们有没有胆！’当时，将军有战死的决心，士兵无偷生的念头，听见您的号召无不挥泪奋臂，决一死战，所以才能打败燕军。现在将军您东面有掖邑丰厚的俸禄，西边有淄上封地的游乐，腰系黄金带，驰骋于淄水、渑水之间，有的只是生活的乐趣，而无战死之心，所以无法取胜啊！”田单说：“我田单有这样的决心，是先生您为我下的。”第二天，他振奋精神，亲临城下，站在箭雨弹雹之中，手持鼓捶，击鼓进军，于是攻克了狄族大营。
起初，齐王灭掉宋国以后，想驱逐在薛地的孟尝君，孟尝君便投奔魏国，魏昭王任用他为国相，与各国联合攻破齐国，齐王死后，齐襄王光复国土，而孟尝君独立于各国之间，无所依属。齐襄王因为新即位，害怕孟尝君，便与他和好。孟尝君死后，几个儿子争夺权力，齐国、魏国趁机共同灭掉薛地，于是孟尝君断了后代。
三十七年（癸未，公元前278年）
秦国派大良造白起进攻楚国，攻占郢城，火烧夷陵。楚襄王的军队四散，于是不再迎战，把国都向东北迁到陈地。秦国以郢城为南郡，封白起为武安君。
三十八年（甲申，公元前277年）
秦国武安君平定巫、黔中，秦国在此设置黔中郡。
魏国魏昭王去世，其子即位为魏安王。
三十九年（乙酉，公元前276年）
秦国武安君进攻魏国，攻占两城。
楚王召集东部军队，得到十余万人，又向西攻取长江以南十五邑。
魏安王封他的弟弟魏无忌为信陵君。
四十年（丙戌，公元前275年）
秦国相国穰侯魏冉进攻魏国。韩国派暴鸢率军救魏，魏冉大破韩军，杀死四万人。暴鸢逃往开封。魏国只好献出八座城求和。魏冉却继续攻打魏国，赶走魏将芒卯，进军北宅。魏国又割让温邑再行求和。
四十一年（丁亥，公元前274年）
魏国重新与齐国联合抗秦。秦国派魏冉进攻魏国，攻陷四城，杀四万人。
鲁国鲁公去世，其子姬仇即位为鲁倾公。
四十二年（戊子，公元前273年）
赵国、魏国联合进攻韩国华阳。韩国向秦国告急，秦王不救。韩国相国对陈筮说：“事情危急了！希望你能抱病连夜走一遭！”陈筮到了秦国，拜见魏冉。魏冉冷笑道：“事情危急了吧？所以让你来。”陈筮却说：“不着急。”魏冉生气地问：“为什么？”陈筮回答：“韩国要是真的逼急了，就会转而投靠别的国家。现在还不算急，所以再来秦国求救。”魏冉忙说：“我答应出兵了。”于是与武安君白起及客卿胡阳率军救韩，八天后到达，在华阳城下击败魏军，又赶跑芒卯，俘虏三员敌将，杀死十三万人。白起又与赵军大将贾偃交战，设计在黄河中淹死赵兵二万人。魏国的段干子建议割让南阳给秦国以求和。苏代对魏王说：“段干子想掌握秦国的相印，秦国想占据魏国的领土。现在大王您让想夺地的秦国控制相印，让想要相印的段干子来控制魏国土地，互相勾结，魏国的土地就会丧失干净！献地去向秦国讨好，好比抱着干柴去救火，干柴烧不完，火是不会灭的。”魏王说：“话虽是如此，但是，事情已经开始进行，无法改变了。”苏代又劝说：“下棋时之所以重视‘枭子’，是因为这个棋子方便时可以吃子，不便时可以停止。现在大王使用智谋为什么还不如下棋用‘枭子’那样灵活呢？”魏王到底没有听从苏代的劝告，割让了南阳求和。南阳，实际上就是修武。
韩国韩王去世，其子即位为韩桓惠王。
韩国、魏国已向秦国屈服，秦王便派武安君白起联合韩、魏两军进攻楚国。尚未出发，楚国已派使臣黄歇前来。黄歇听说此事，怕秦国乘胜一举消灭楚国，于是急忙上书秦王说：“我听说物极必反，冬天、夏天的交替即是如此；走极端则危险，垒棋子即是如此。现在强大的秦国的地域，遍及天下，控制西、北两端，这是自古以来，拥有万乘车马的大国从未达到的。楚国三世先王都不忘与齐国接壤，以切断联合抗秦阵线的韩、魏中段。如今大王派盛桥在韩国掌权，盛桥迫使韩国割地给秦国，大王您不动甲兵，不施威势，就得到百里土地，大王可谓能干之极！大王又出兵攻魏，封堵魏国门户，攻下河内，夺取燕、酸枣、虚、桃等地，进入邢丘，魏兵云集而不敢前救，大王可谓战功累累！大王休息军队，两年后再举用兵，又吞并蒲、衍、首、垣等地，兵临仁、平丘，使黄、济阳据城自守，魏王只好屈服。大王又占据濮磨之北，使土地互相联结于齐国和秦国的腰部，切断楚国、赵国的联系中枢，各国三番五次地联合、聚会，终于不敢来救，大王可谓威名赫赫无双！现在，大王如果能保守功业威势，收敛继续进攻的雄心，而在领地上广施仁义，消除后患，那么，大王的功业绝不止是三代圣王之后的第四个，五位霸主之后的第六个！但是大王如果倚仗军队众多，凭借武器精良，乘平毁魏国的兵威，想以武力使天下各国君王都向您俯首称臣，我担心您会引来后患。《诗经》说：‘常见善始，少见善终。’《易经》说：‘小狐渡水，尾部浸湿。’这都是指开始容易，结束困难。当年吴国听信越国，出兵攻齐，已经在艾陵战胜齐国，回来却被越王在三江之滨擒杀。智伯瑶信任韩、魏两家，联合进攻赵家，围攻晋阳时，胜利已指日可待，韩家、魏家却突然反叛，智伯瑶终于在凿台之下被杀。如今大王忌恨楚国尚未灭亡，而忘记了楚国灭亡只会使韩国、魏国强大，臣下我认为您的这种做法不可取而为您忧虑。楚国，是您的援手；其他邻国，是您的敌人。现在大王相信韩国、魏国亲善秦国，这正像当年吴国信任越国。我以为，恐怕韩国、魏崐国表面上谦语卑辞是为了免除灾祸，而实际上却是想欺骗秦国。为什么呢？因为秦王对于韩、魏两国并无再世的恩德，却有累世的积怨呀！韩国、魏国人中，父子兄弟接连死于秦国刀兵之下的，已近十代了。所以韩国、魏国只要不灭亡，终究是秦国的忧患。大王却要资助他们一起进攻楚国，这不是个大错误吗？况且，进攻楚国从何处出兵？大王是否准备向世仇魏、韩两国去借道？那样做，自秦兵出发之日大王就会担忧他们回不来。大王如果不向世仇韩、魏去借道，势必只有攻随水的西边，那里都是广川、大河、山林、深谷，不毛之地，大王徒有征服楚国的名义而没有得到土地的实际利益，而且大王进攻楚国时，四国必然全部起兵响应大王，当秦国、楚国军队打得难解难分时，魏国就会趁机出兵进攻留、方与、、湖陵、砀、萧、相等地，宋国旧地将尽入其手。齐国人也会向南攻楚，必然夺取泗上，这些都是四通八达的平原，肥沃膏腴之地。那样的话，天下的国家中将是齐国、魏国最强大了。我为大王考虑，不如与楚国亲善为好。秦国、楚国合二为一进攻韩国，韩国必然束手无策，屈服称臣，大王控制华山以东的险要，占有九曲黄河的利益，韩王必定成为您的关内之侯。这时大王再派十万大兵驻守韩都新郑，足使魏王胆战心惊，许、鄢陵两城被困后，上蔡、召陵也将与魏都大梁无法来往。那时，魏国就成了关内侯。大王一施行与楚国亲善的政策而使关内两个拥有万乘兵车的大国向齐国索要土地，齐国西部领土便垂手可得。大王的领土横贯西海、东海，扼制天下，于是燕国、赵国不能与齐国、楚国联合，齐国、楚国也不能与燕国、赵国相援助。然后大王再威逼燕国、赵国，直捣齐国、楚国，这四个国家不等到被痛击就会降服了。”秦王听从了黄歇的意见，令白起停止行动，辞谢了韩国、魏国军队，派黄歇归国，与楚国缔结亲善睦邻邦交条约。', NULL, '', 'indent', 1572786182, '5dbe5f7fba39c80073f14488', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643577, '资治通鉴 · 卷六 · 秦纪一', NULL, 17, 1577, 1, 1, '司马光', NULL, 10351, '57b9c6d179bc4400639cc661', '宋', 'wen', '文', '资治通鉴', '', '起柔兆敦牂，尽昭阳作噩，凡二十八年。
昭襄王五十二年（丙午，公元前二五五年）
河东守王稽坐与诸侯通，弃市。应侯日以不怿。王临朝而叹，应侯请其故。王曰：“今武安君死，而郑安平、王稽等皆畔，内无良将而外多敌国，吾是以忧。”应侯惧，不知所出。燕客蔡泽闻之，西入秦，先使人宣言于应侯曰：“蔡泽，天下雄辩之士。彼见王，必困君而夺君之位。”应侯怒，使人召之。蔡泽见应侯，礼又倨。应侯不快，因让之曰：“子宣言欲代我相，请闻其说。”蔡泽曰：“吁，君何见之晚也！夫四时之序，成功者去。君独不见夫秦之商君、楚之吴起、越之大夫种，何足愿与？”应侯谬曰：“何为不可？！此三子者，义之至也，忠之尽也。君子有杀身以成名，死无所恨！”蔡泽曰：“夫人立功岂不期于成全邪？身名俱全者，上也；名可法而身死者，次也；名僇辱而身全者，下也。夫商君、吴起、大夫种，其为人臣尽忠致功，则可愿矣。闳夭、周公，岂不亦忠且圣乎？！三子之可愿，孰与闳夭、周公哉？”应侯曰：“善。”蔡泽曰：“然则君之主惇厚旧故，不倍功臣，孰与孝公、楚王、越王？”曰：“未知何如。”蔡泽曰：“君之功能孰与三子？”曰：“不若。”蔡泽曰：“然则君身不退，患恐甚于三子矣。语曰：‘日中则移，月满则亏。’进退嬴缩，与时变化，圣人之道也。今君之怨已雠而德已报，意欲至矣而无变计，窃为君危之。”应侯遂延以为上客，因荐于王。王召与语，大悦，拜为客卿。应侯因谢病免。王新悦蔡泽计画，遂以为相国，泽为相数月，免。
楚春申君以荀卿为兰陵令。荀卿者，赵人，名况，尝与临武君论兵于赵孝成王之前。王曰：“请问兵要。”临武君对曰：“上得天时，下得地利，观敌之变动，后之发，先之至，此用兵之要术也。”荀卿曰：“不然。臣所闻古之道，凡用兵攻战之本，在乎一民。弓矢不调，则羿不能以中；六马不和，则造父不能以致远；士民不亲附，则汤、武不能以必胜也。故善附民者，是乃善用兵者也。故兵要在乎附民而已。”临武君曰：“不然。兵之所贵者势利也，所行者变诈也。善用兵者感忽悠闇，莫知所从出。孙吴用之，无敌于天下，岂必待附民哉！”荀卿曰：“不然。臣之所道，仁人之兵，王者之志也。君之所贵，权谋势利也。仁人之兵，不可诈也。彼可诈者，怠慢者也，露袒者也，君臣上下之间滑然有离德者也。故以桀诈桀，犹巧拙有幸焉。以桀诈尧，譬之以卵投石，以指桡沸，若赴水火，入焉焦没耳。故仁人之兵，上下一心，三军同力。臣之于君也，下之于上也，若子之事父，弟之事兄，若手臂之扞头目而覆胸腹也。诈而袭之，与先惊而后击之，一也。且仁人用十里之国则将有百里之听，用百里之国则将有千里之听，用千里之国则将有四海之听，必将聪明警戒，和傅而一。故仁人之兵，聚则成卒，散则成列，延则若莫耶之长刃，婴之者断；兑则若莫耶之利锋，当之者溃。圜居而方止，则若盘石然，触之者角摧而退耳。且夫暴国之君，将谁与至哉？彼其所与至者，必其民也。其民之亲我欢若父母，其好我芬若椒兰；彼反顾其上则若灼黥，若仇雠；人之情，虽桀、跖，岂有肯为其所恶，贼其所好者哉！是犹使人之子孙自贼其父母也。彼必将来告之，夫又何可诈也！故仁人用国日明，诸侯先顺者安，后顺者危，敌之者削，反之者亡。《诗》曰：‘武王载发，有虔秉钺，如火烈烈，则莫我敢遏，’此之谓也。”
孝成王、临武君曰：“善。请问王者之兵，设何道，何行而可？”荀卿曰：“凡君贤者其国治，君不能者其国乱；隆礼贵义者其国治，简礼贱义者其国乱。治者强，乱者弱，是强弱之本也。上足卬则下可用也，上不足卬则下不可用也。下可用则强，下不可用则弱，是强弱之常也。好士者强，不好士者弱；爱民者强，不爱民者弱；政令信者强，政令不信者弱；重用兵者强，轻用兵者弱；权出一者强，权出二者弱；是强弱之常也。齐人隆技击，其技也，得一首者则赐赎锱金，无本赏矣。是事小敌毳，则偷可用也；事大敌坚，则涣焉离耳。若飞鸟然，倾侧反覆无日，是亡国之兵也，兵莫弱是矣，是其去赁市佣而战之几矣。魏氏之武卒，以度取之；衣三属之甲，操十二石之弩，负矢五十个，置戈其上，冠胄带剑，赢二日之粮，日中而趋百里；中试则复其户，利其田宅。是其气力数年而衰，而复利未可夺也，改造则不易周也，是故地虽大，其税必寡，是危国之兵也。秦人，其生民也狭隘，其使民也酷烈，劫之以势，隐之以厄，忸之以庆赏，之以刑罚，使民所以要利于上者，非斗无由也。使以功赏相长，五甲首而隶五家，是最为众强长久之道。故四世有胜，非幸也，数也。故齐之技击不可以遇魏之武卒，魏之武卒不可以遇秦之锐士，秦之锐士不可以当桓、文之节制，桓、文之节制不可以当汤、武之仁义，有遇之者，若以焦熬投石焉。兼是数国者，皆干赏蹈利之兵也，佣徒鬻卖之道也，未有贵上安制綦节之理也。诸侯有能微妙之以节，则作而兼殆之耳。故招延募选，隆势诈，尚功利，是渐之也。礼义教化，是齐之也。故以诈遇诈，犹有巧拙焉；以诈遇齐，譬之犹以锥刀堕太山也。故汤、武之诛桀、纣也，拱挹指麾，而强暴之国莫不趋使，诛桀、纣若诛独夫。故《泰誓》曰：‘独夫纣，’此之谓也。故兵大齐则制天下，小齐则治邻敌。若夫招延募选，隆势诈，尚功利之兵，则胜不胜无常，代翕代张，代存代亡，相为雌雄耳。夫是之谓盗兵，君子不由也。”
孝成王、临武君曰：“善。请问为将。”荀卿曰：“知莫大乎弃疑，行莫大乎无过，事莫大乎无悔。事至无悔而止矣，不可必也。故制号政令，欲严以威；庆赏刑罚，欲必以信；处舍收藏，欲周以固；徙举进退，欲安以重，欲疾以速；窥敌观变，欲潜以深，欲伍以参；遇敌决战，必行吾所明，无行吾所疑；夫是之谓六术。无欲将而恶废，无怠胜而忘败，无威内而轻外，无见其利而不顾其害，凡虑事欲熟而用财欲泰，夫是之谓五权。将所以不受命于主有三，可杀而不可使处不完，可杀而不可使击不胜，可杀而不可使欺百姓，夫是之谓三至。凡受命于主而行三军，三军既定，百官得序，群物皆正，则主不能喜，敌不能怒，夫是之谓至臣。虑必先事而申之以敬，慎终如始，始终如一，夫是之谓大吉。凡百事之成也必在敬之，其败也必在慢之。故敬胜怠则吉，怠胜敬则灭；计胜欲则从，欲胜计则凶。战如守，行如战，有功如幸。敬谋无旷，敬事无旷，敬吏无旷，敬众无旷，敬敌无旷，夫是之谓五无旷。慎行此六术、五权、三至，而处之以恭敬、无旷，夫是之谓天下之将，则通于神明矣。”
临武君曰：“善。请问王者之军制。”荀卿曰：“将死鼓，御死辔，百吏死职，士大夫死行列。闻鼓声而进，闻金声而退。顺命为上，有功次之。令不进而进，犹令不退而退也，其罪惟均。不杀老弱，不猎禾稼，服者不禽，格者不赦，奔命者不获。凡诛，非诛其百姓也，诛其乱百姓者也。百姓有捍其贼，则是亦贼也。以故顺刃者生，傃刃者死，奔命者贡。微子开封于宋，曹触龙断于军，商之服民，所以养生之者无异周人，故近者歌讴而乐之，远者竭蹶而趋之，无幽闲辟陋之国，莫不趋使而安乐之，四海之内若一家，通达之属莫不从服，夫是之谓人师。《诗》曰：‘自西自东，自南自北，无思不服。’此之谓也。王者有诛而无战，城守不攻，兵格不击，敌上下相喜则庆之，不屠城，不潜军，不留众，师不越时，故乱者乐其政，不安其上，欲其至也。”临武君曰：“善。”
陈嚣问荀卿曰：“先生议兵，常以仁义为本。仁者爱人，义者循理，然则又何以兵为？凡所为有兵者，为争夺也。”荀卿曰：“非汝所知也。彼仁者爱人，爱人，故恶人之害之也；义者循理，循理，故恶人之乱之也。彼兵者，所以禁暴除害也，非争夺也。”
燕孝王薨，子喜立。
周民东亡。秦人取其宝器，迁西周公于惮狐之聚。
楚人迁鲁于莒而取其地。
昭襄王五十三年（丁未，公元前二五四年）
摎伐魏，取吴城。韩王入朝。魏举国听令。
昭襄王五十四年（戊申，公元前二五三年）
王郊见上帝于雍。
楚迁于巨阳。
昭襄王五十五年（己酉，公元前二五二年）
卫怀君朝于魏，魏人执而杀之；更立其弟，是为元君。元君，魏婿也。
昭襄王五十六年（庚戌，公元前二五一年）
秋，王薨，孝文王立。尊唐八子为唐太后，以子楚为太子。赵人奉子楚妻子归之。韩王衰绖入吊祠。
燕王喜使栗腹约欢于赵，以五百金为赵王酒。反而言于燕王曰：“赵壮者皆死长平，其孤未壮，可伐也。”王召昌国君乐闲问之，对曰：“赵四战之国，其民习兵，不可。”王曰：“吾以五而伐一。”对曰：“不可。”王怒。群臣皆以为可，乃发二千乘，栗腹将而攻鄗，卿秦攻代。将渠曰：“与人通关约交，以五百金饮人之王，使者报而攻之，不祥，师必无功。”王不听，自将偏军随之。将渠引王之绶，王以足蹙之。将渠泣曰：“臣非自为，为王也！”燕师至宋子，赵廉颇为将，逆击之，败栗腹于鄗，败卿秦、乐乘于代，追北五百馀里，遂围燕。燕人请和，赵人曰：“必令将渠处和。”燕王以将渠为相而处和，赵师乃解去。
赵平原君卒。
秦孝文王
昭襄王元年（辛亥，公元前二五零年）
冬，十月，已亥，王即位；三日薨。子楚立，是为庄襄王。尊华阳夫人为华阳太后，夏姬为夏太后。
燕将攻齐聊城，拔之。或谮之燕王，燕将保聊城，不敢归。齐田单攻之，岁馀不下，鲁仲连乃为书，约之矢以射城中，遗燕将，为陈利害曰：“为公计者，不归燕则归齐。今独守孤城，齐兵日益而燕救不至，将何为乎？”燕将见书，泣三日，犹豫不能自决，欲归燕，已有隙；欲降齐，所杀虏于齐甚众，恐已降而后见辱。喟然叹曰：“与人刃我，宁我自刃！”遂自杀。聊城乱，田单克聊城。归，言鲁仲连于齐王，欲爵之。仲连逃之海上，曰：“吾富贵而诎于人，宁贫贱而轻世肆志焉！”
魏安釐王问天下之高士于子顺，子顺曰：“世无其人也；抑可以为次，其鲁仲连乎！”王曰：“鲁仲连强作之者，非体自然也。”子顺曰：“人皆作之。作之不止，乃成君子；作之不变，习与体成；习与体成，则自然也。”
秦庄襄王
昭襄王元年（壬子，公元前二四九年）
吕不韦为相国。
东周君为诸侯谋伐秦，王使相国帅师讨灭之，迁东周君于阳人聚。周既不祀。周比亡，凡有七邑：河南、洛阳、穀城、平阴、偃师、巩、缑氏。
以河南、洛阳十万户封相国不韦为文信侯。
蒙骜伐韩，取成皋、荥阳，初置三川郡。
楚灭鲁，迁鲁顷公于卞，为家人。
昭襄王二年（癸丑，公元前二四八年）
日有食之。
蒙骜伐赵，定太原，取榆次、狼孟等三十七城。
楚春申君言于楚王曰：“淮北地边于齐，其事急，请以为郡而封于江东。”楚王许之。春申君因城吴故墟以为都邑，宫室极盛。
昭襄王三年（甲寅，公元前二四七年）
王龁攻上党诸城，悉拔之，初置太原郡。
蒙骜帅师伐魏，取高都、汲。魏师数败，魏王患之，乃使人请信陵君于赵。信陵君畏得罪，不肯还，诫门下曰：“有敢为魏使通者死！”宾客莫敢谏。毛公、薛公见信陵君曰：“公子所以重于诸侯者，徒以有魏也。今魏急而公子不恤，一旦秦人克大梁，夷先王之宗庙，公子当何面目立天下乎！”语未卒，信陵君色变，趣驾还魏。魏王持信陵君而泣，以为上将军。信陵君使人求援于诸侯。诸侯闻信陵君复为魏将，皆遣兵救魏。信陵君率五国之师败蒙骜于河外，蒙骜遁走。信陵君追至函谷关，抑之而还。安陵人缩高之子仕于秦，秦使之守管。信陵君攻之不下，使人谓安陵君曰：“君其遣缩高，吾将仕之以五大夫，使为执节尉。”安陵君曰：“安陵，小国也，不能必使其民。使者自往请之。”使吏导使者至缩高之所。使者致信陵君之命，缩高曰：“君之幸高也，将使高攻管也。夫父攻子守，人之笑也；见臣而下，是倍主也。父教子倍，亦非君之所喜。敢再拜辞！”使者以报信陵君。信陵君大怒，遣使之安陵君所曰：“安陵之地，亦犹魏也。今吾攻管而不下，则秦兵及我，社稷必危矣。愿君生束缩高而致之！若君弗致，无忌将发十万之师以造安陵之城下！”安陵君曰：“吾先君成侯受诏襄王以守此城也，手授太府之宪，宪之上篇曰：‘子弑父，臣弑君，有常不赦。国虽大赦，降城亡子不得与焉。’今缩高辞大位以全父子之义，而君曰‘必生致之’，是使我负襄王之诏而废太府之宪也，虽死，终不敢行！”缩高闻之曰：“信陵君为人，悍猛而自用，此辞反必为国祸。吾已全己，无违人臣之义矣，岂可使吾君有魏患乎！”乃之使者之舍，刎颈而死。信陵君闻之，缟素辟舍，使使者谢安陵君曰：“无忌，小人也，困于思虑，失信于君，请再拜辞罪！”
王使人行万金于魏以间信陵君，求得晋鄙客，令说魏王曰：“公子亡在外十年矣，今复为将，诸侯皆属，天下徒闻信陵君而不闻魏王矣。”王又数使人贺信陵君：“得为魏王未也？”魏王日闻其毁，不能不信，乃使人代信陵君将兵。信陵君自知再以毁废，乃谢病不朝，日夜以酒色自娱，凡四岁而卒。韩王往吊，其子荣之，以告子顺。子顺曰：“必辞之以礼。‘邻国君吊，君为之主。’今君不命子，则子无所受韩君也。”其子辞之。
五月，丙午，王薨。太子政立，生十三年矣，国事皆委于文信侯，号称仲父。
晋阳反。
秦始皇帝上
昭襄王元年（乙卯，公元前二四六年）
蒙骜击定之。
韩欲疲秦人，使无东伐，乃使水工郑国为间于秦，凿泾水自仲山为渠，并北山，东注洛。中作而觉，秦人欲杀之。郑国曰：“臣为韩延数年之命，然渠成，亦秦万世之利也。”乃使卒为之。注填阏之水溉舄卤之地四万馀顷，收皆亩一钟，关中由是益富饶。
昭襄王二年（丙辰，公元前二四五年）
麃公将卒攻卷，斩首三万。
赵以廉颇为假相国，伐魏，取繁阳。赵孝成王薨，子悼襄王立，使武襄君乐乘代廉颇。廉颇怒，攻武襄君，武襄君走，廉颇出奔魏。久之，魏不能信用。赵师数困于秦，赵王思复得廉颇，廉颇亦思复用于赵。赵王使使者视廉颇尚可用否。廉颇之仇郭开多与使者金，令毁之。廉颇见使者，一饭斗米，肉十斤，被甲上马，以示可用。使者还报曰：“廉将军虽老，尚善饭；然与臣坐，顷之三遗矢矣。”赵王以为老，遂不召。楚人阴使迎之。廉颇一为楚将，无功，曰：“我思用赵人。”卒死于寿春。
昭襄王三年（丁巳，公元前二四四年）
大饥。
蒙骜伐韩，取十二城。
赵王以李牧为将，伐燕，取武遂、方城。李牧者，赵之北边良将也，尝居代、雁门备匈奴，以便宜置吏，市租皆输入莫府，为士卒费，日击数牛飨士；习骑射，谨烽火，多间谍，为约曰：“匈奴即入盗，急入收保。有敢捕虏者斩！”匈奴每入，烽火谨，辄入收保不战。如是数岁，亦不亡失。匈奴皆以为怯，虽赵边兵亦以为吾将怯。赵王让之，李牧如故。王怒，使他人代之。岁馀，屡出战，不利，多失亡，边不得田畜。王复请李牧，李牧杜门称病不出。王强起之，李牧曰：“必用臣，臣如前，乃敢奉令。”王许之。
李牧至边，如约。匈奴数岁无所得，终以为怯。边士日得赏赐而不用，皆愿一战。于是乃具选车得千三百乘，选骑得万三千匹，百金之士五万人，彀者十万人，悉勒习战；大纵畜牧、人民满野。匈奴小入，佯北不胜，以数十人委之。单于闻之，大率众来入。李牧多为奇陈，张左、右翼击之，大破之，杀匈奴十馀万骑，灭衤詹褴，破东胡，降林胡。单于奔走，十馀岁不敢近赵边。
先是时，天下冠带之国七，而三国边于戎狄：秦自陇以西有绵诸、绲戎、翟、之戎，岐、梁、泾、漆之北有义渠、大荔、乌氏、朐衍之戎；而赵北有林胡、楼烦之戎；燕北有东胡、山戎；各分散居溪谷，自有君长，往往而聚者百有馀戎，然莫能相一。其后义渠筑城郭以自守，而秦稍蚕食之，至惠王遂拔义渠二十五城。昭王之时，宣太后诱义渠王，杀诸甘泉，遂发兵伐义渠，灭之；始于陇西、北地、上郡筑长城以拒胡。赵武灵王北破林胡、楼烦，筑长城，自代并阴山下，至高阙为塞，而置云中、雁门、代郡。其后燕将秦开为质于胡，胡甚信之；归而袭破东胡，东胡却千馀里；燕亦筑长城，自造阳至襄平，置上谷、渔阳、右北平、辽东郡以距胡。及战国之末而匈奴始大。
昭襄王四年（戊午，公元前二四三年）
春，蒙骜伐魏，取旸、有诡。三月，军罢。
秦质子归自赵；赵太子出归国。
七月，蝗，疫。令百姓纳粟千石，拜爵一级。
魏安釐王薨，子景湣王立。
昭襄王五年（己未，公元前二四二年）
蒙骜伐魏，取酸枣、燕、虚、长平、雍丘、山阳等二十城；初置东郡。
初，剧辛在赵与庞爰善，已而仕燕。燕王见赵数困于秦，廉颇去而庞爰为将，欲因其敝而攻之，问于剧辛，对曰：“庞爰易与耳。”燕王使剧辛将而伐赵。赵庞爰御之，杀剧辛，取燕师二万。
诸侯患秦攻伐无已时。
昭襄王六年（庚申，公元前二四一年）
楚、赵、魏、韩、卫合从以伐秦，楚王为从长，春申君用事，取寿陵。至函谷，秦师出，五国之师皆败走。楚王以咎春申君，春申君以此益疏。观津人朱英谓春申君曰：“人皆以楚为强，君用之而弱。其于英不然。先君时，秦善楚，二十年而不攻楚，何也？秦逾黾厄之塞而攻楚，不便；假道于两周，背韩、魏而攻楚，不可。今则不然。魏旦暮亡，不能爱许、鄢陵，魏割以与秦，秦兵去陈百六十里。臣之所观者，见秦、楚之日斗也。”楚于是去陈，徙寿春，命曰郢。春申君就封于吴，行相事。
秦拔魏朝歌，及卫濮阳。卫元君率其支属徙居野王，阻其山以保魏之河内。
昭襄王七年（辛酉，公元前二四零年）
伐魏，取汲。
夏太后薨。
蒙骜卒。
昭襄王八年（壬戌，公元前二三九年）
魏与赵鄴。
韩桓惠王薨，子安立。
昭襄王九年（癸亥，公元前二三八年）
伐魏，取垣、浦。
夏，四月，寒，民有冻死者。
王宿雍。
己酉，王冠，带剑。
杨端和伐魏，取衍氏。
初，王即位，年少，太后时时与文信侯私通。王益壮，文信侯恐事觉，祸及己，乃诈以舍人嫪毐为宦者，进于太后。太后幸之，生二子，封毐为长信侯，以太原为毐国，政事皆决于毐；客求为毐舍人者甚众。王左右有与毐争言者，告毐实非宦者，王下吏治毐。毐惧，矫王御玺发兵，欲攻蕲年宫为乱。王使相国昌平君、昌文君发卒攻毐，战咸阳，斩首数百；毐败走，获之。秋，九月，夷毐三族；党与皆车裂灭宗；舍人罪轻者徙蜀，凡四千馀家。迁太后于雍萯阳宫，杀其二子。下令曰：“敢以太后事谏者，戮而杀之，断其四支，积之阙下！”死者二十七人。齐客茅焦上谒请谏。王使谓之曰：“若不见夫积阙下者邪？”对曰：“臣闻天有二十八宿，今死者二十七人，臣之来固欲满其数耳。臣非畏死者也！”使者走入白之。茅焦邑子同食者，尽负其衣物而逃王。王大怒曰：“是人也，故来犯吾，趣召镬烹之，是安得积阙下哉！”王按剑怒而坐，口正沫出。使者召之入，茅焦徐行至前，再拜谒起，称曰：“臣闻有生者不讳死，有国者不讳亡。讳死者不可以得生，讳亡者不可以得存。死生存亡，圣主所欲急闻也，陛下欲闻之乎？”王曰：“何谓也？”茅焦曰：“陛下有狂悖之行，不自知邪？车裂假父，囊扑二弟，迁母于雍，残戮谏士，桀、纣之行不至于是矣。令天下闻之，尽瓦解，无向秦者，臣窃为陛下危之！臣言已矣！”乃解衣伏质。王下殿，手自接之曰：“先生起就衣，今愿受事！”乃爵之上卿。王自驾，虚左方，往迎太后，归于咸阳，复为母子如初。
楚考烈王无子，春申君患之，求妇人宜子者甚众，进之，卒无子。赵人李园持其妹欲进诸楚王，闻其不宜子，恐久无宠，乃求为春申君舍人。已而谒归，故失期而还。春申君问之，李园曰：“齐王使人求臣之妹，与其使者饮，故失期。”春申君曰：“聘入乎？”曰：“未也。”春申君遂纳之。既而有娠，李园使其妹说春申君曰：“楚王贵幸君，虽兄弟不如也。今君相楚二十馀年而王无子，即百岁后将更立兄弟，彼亦各贵其故所亲，君又安得常保此宠乎！非徒然也，君贵，用事久，多失礼于王之兄弟，兄弟立，祸且及身矣。今妾有娠而人莫知，妾幸君未久，诚以君之重，进妾于王，王必幸之。妾赖天而有男，则是君之子为王也。楚国尽可得，孰与身临不测之祸哉！”春申君大然之。乃出李园妹，谨舍而言诸楚王。王召入，幸之，遂生男，立为太子。
李园妹为王后，李园亦贵用事，而恐春申君泄其语，阴养死士，欲杀春申君以灭口；国人颇有知之者。楚王病，朱英谓春申君曰：“世有无望之福，亦有无望之祸。今君处无望之世，事无望之主，安可以无无望之人乎！”春申君曰：“何谓无望之福？”曰：“君相楚二十馀年矣，虽名相国，其实王也。王今病，旦暮薨，薨而君相幼主，因而当国，王长而反政，不即遂南面称孤，此所谓无望之福也。”“何谓无望之祸？”曰：“李园不治国而君之仇也，不为兵而养死士之日久矣。王薨，李园必先入，据权而杀君以灭口，此所谓无望之祸也。”“何谓无望之人？”曰：“君置臣郎中，王薨，李园先入，臣为君杀之，此所谓无望之人也。”春申君曰：“足下置之。李园，弱人也，仆又善之。且何至此！”朱英知言不用，惧而亡去。后十七日，楚王薨，李园果先入，伏死士于棘门之内。春申君入，死士侠刺之，投其首于棘门之外；于是使吏尽捕诛春申君之家。太子立，是为幽王。
扬子《法言》曰：或问：“信陵、平原、孟尝、春申益乎？”曰：“上失其政，奸臣窃国命，何其益乎！”
王以文信侯奉先王功大，不忍诛。
昭襄王十年（甲子，公元前二三七年）
冬，十月，文信侯免相，出就国。
宗室大臣议曰：“诸侯人来仕者，皆为其主游间耳，请一切逐之。”于是大索，逐客。客卿楚人李斯亦在逐中，行，且上书曰：“昔穆公求士，西取由余于戎，东得百里奚于宛，迎蹇叔于宋，求丕豹、公孙支于晋，并国二十，遂霸西戎。孝公用商鞅之法，诸侯亲服，至今治强。惠王用张仪之计，散六国之从，使之事秦。昭王得范雎，强公室，杜私门。此四君者，皆以客之功。由此观之，客何负于秦哉！夫色、乐、珠、玉不产于秦而王服御者众，取人则不然，不问可否，不论曲直，非秦者去，为客者逐。是所重者在乎色、乐、珠、玉，而所轻者在乎人民也。臣闻太山不让土壤，故能成其大；河海不择细流，故能就其深；王者不却众庶，故能明其德。此五帝、三王之所以无敌也。今乃弃黔首以资敌国，却宾客以业诸侯，所谓藉寇兵而赍盗粮者也。”王乃召李斯，复其官，除逐客之令。李斯至骊邑而还。王卒用李斯之谋，阴遣辩士赍金玉游说诸侯，诸侯名士可下以财者厚遗结之，不肯者利剑刺之，离其君臣之计，然后使良将随其后，数年之中，卒兼天下。
昭襄王十一年（乙丑，公元前二三六年）
赵人伐燕，取狸阳。兵未罢，将军王剪、桓齮、杨端和伐赵，攻鄴，取九城。王剪攻阏与、轑阳，桓齮取鄴、安阳。
赵悼襄王薨，子幽缪王迁立。其母，倡也，嬖于悼襄王，悼襄王废嫡子嘉而立之。迁素以无行闻于国。
文信侯就国岁馀，诸侯宾客使者相望于道，请之。王恐其为变，乃赐文信侯书曰：“君何功于秦，封君河南，食十万户？何亲于秦，号称仲父？其与家属徙处蜀！”文信侯自知稍侵，恐诛。
昭襄王十二年（丙寅，公元前二三五年）
文信侯饮鸩死，窃葬。其舍人临者，皆逐迁之。且曰：“自今以来，操国事不道如嫪毐、不韦者，籍其门，视此！”
扬子《法言》曰：或问：“吕不韦其智矣乎？以人易货。”曰：“谁谓不韦智者欤？以国易宗。吕不韦之盗，穿窬之雄乎！穿窬也者，吾见担石矣，未见雒阳也。”
自六月不雨，至于八月。
发四郡兵助魏伐楚。
昭襄王十三年（丁卯，公元前二三四年）
桓齮伐赵，败赵将扈輙于平阳，斩首十万，杀扈輙。赵王以李牧为大将军，复战于宜安、肥下，秦师败绩，桓齮奔还。赵封李牧为武安君。
昭襄王十四年（戊辰，公元前二三三年）
桓齮伐赵，取宜安、平阳、武城。
韩王纳地效玺，请为籓臣，使韩非来聘。韩非者，韩之诸公子也，善刑名法术之学，见韩之削弱，数以书干韩王，王不能用。于是韩非疾治国不务求人任贤，反举浮淫之蠹而加之功实之上，宽则宠名誉之人，急则用介胄之士，所养非所用，所用非所养。悲廉直不容于邪枉之臣，观往者得失之变，作《孤愤》、《五蠹》、《内、外储》、《说林》、《说难》五十六篇，十馀万言。
王闻其贤，欲见之。非为韩使于秦，因上书说王曰：“今秦地方数千里，师名百万，号令赏罚，天下不如。臣昧死愿望见大王，言所以破天下从之计。大王诚听臣说，一举而天下之从不破，赵不举，韩不亡，荆、魏不臣，齐、燕不亲，霸王之名不成，四邻诸侯不朝，大王斩臣以徇国，以戒为王谋不忠者也。”王悦之，未任用。李斯嫉之，曰：“韩非，韩之诸公子也。今欲并诸侯，非终为韩不为秦，此人情也。今王不用，又留而归之，此自遗患也。不如以法诛之。”王以为然，下吏治非。李斯使人遗非药，令早自杀。韩非欲自陈，不得见。王后悔，使赦之，非已死矣。
扬子《法言》曰：或问：“韩非作《说难》之书而卒死乎说难，敢问何反也？”曰：“《说难》盖其所以死乎！”曰：“何也？”“君子以礼动，以义止，合则进，否则退，确乎不忧其不合也。夫说人而忧其不合，则亦无所不至矣。”或曰：“非忧说之不合，非邪？”曰：“说不由道，忧也。由道而不合，非忧也。”
臣光曰：臣闻君子亲其亲以及人之亲，爱其国以及人之国，是以功大名美而享有百福也。今非为秦画谋，而首欲覆其宗国，以售其言，罪固不容于死矣，乌足愍哉！
昭襄王十五年（己巳，公元前二三二年）
王大兴师伐赵，一军抵鄴，一军抵太原，取狼孟、番吾；遇李牧而还。
初，燕太子丹尝质于赵，与王善。王即位，丹为质于秦，王不礼焉。丹怒，亡归。
昭襄王十六年（庚午，公元前二三一年）
韩献南阳地。九月，发卒受地于韩。
魏人献地。
代地震，自乐徐以西，北至平阴；台屋墙垣太半坏，地坼东西百三十步。
昭襄王十七年（辛未，公元前二三零年）
内史胜灭韩，虏韩王安，以其地置颖川郡。
华阳太后薨。
赵大饥。
卫元君薨，子角立。
昭襄王十八年（壬申，公元前二二九年）
王剪将上地兵下井陉，端和将河内兵共伐赵。赵李牧、司马尚御之。秦人多与赵王嬖臣郭开金，使毁牧及尚，言其欲反。赵王使赵葱及齐将颜聚代之。李牧不受命，赵人捕而杀之；废司马尚。
昭襄王十九年（癸酉，公元前二二八年）
王剪击赵军，大破之，杀赵葱，颜聚亡，遂克邯郸，虏赵王迁。王如邯郸，故与母家有仇怨者皆杀之。还，从太原、上郡归。
太后薨。
王剪屯中山以临燕。赵公子嘉帅其宗族百人奔代，自立为代王，赵之亡，大夫稍稍归之，与燕合兵，军上谷。
楚幽王薨，国人立其弟郝。三月，郝庶兄负刍杀之，自立。
魏景湣王薨，子假立。
燕太子丹怨王，欲报之，以问其傅鞠武。鞠武请西约三晋，南连齐、楚，北媾匈奴以图秦。太子曰：“太傅之计，旷日弥久，令人心惽然，恐不能须也。”顷之，将军樊于期得罪，亡之燕；太子受而舍之。鞠武谏曰：“夫以秦王之暴而积怒于燕，足为寒心，又况闻樊将军之所在乎！是谓委肉当饿虎之蹊也。愿太子疾遣樊将军入匈奴。”太子曰：“樊将军穷困于天下，归身于丹，是固丹命卒之时也，愿更虑之！”鞠武曰：“夫行危以求安，造祸以为福，计浅而怨深，乃连结一人之后交，不顾国家之大害，所谓资怨而助祸矣！”太子不听。
太子闻卫人荆轲之贤，卑辞厚礼而请见之。谓轲曰：“今秦已虏韩王，又举兵南伐楚，北临赵。赵不能支秦，则祸必至于燕。燕小弱，数困于兵，何足以当秦！诸侯服秦，莫敢合从。丹之私计愚，以为诚得天下之勇士使于秦，劫秦王，使悉反诸侯侵地，若曹沫之与齐桓公，则大善矣；则不可，因而刺杀之，彼大将擅兵于外而内有乱，则君臣相疑，以其间，诸侯得合从，其破秦必矣。唯荆卿留意焉！”荆轲许之。于是舍荆卿于上舍，太子日造门下，所以奉养荆轲，无所不至。及王剪灭赵，太子闻之惧，欲遣荆轲行。荆轲曰：“今行而无信，则秦未可亲也。诚得樊将军首与燕督亢之地图，奉献秦王，秦王必说见臣，臣乃有以报。”太子曰：“樊将军穷困来归丹，丹不忍也！”荆轲乃私见樊于期曰：“秦之遇将军，可谓深矣，父母宗族皆为戮没！今闻购将军首，金千斤，邑万家，将奈何？”于期太息流涕曰：“计将安出？”荆卿曰：“愿得将军之首以献秦王，秦王必喜而见臣，臣左手把其袖，右手揕其胸，则将军之仇报而燕见陵之愧除矣！”樊于期曰：“此臣之日夜切齿腐心也！”遂自刎。太子闻之，奔往伏哭，然已无奈何，遂以函盛其首。太子豫求天下之利匕首，使工以药焠之，以试人，血濡缕，人无不立死者。乃装为遣荆轲，以燕勇士秦舞阳为之副，使入秦。', '', '', '秦纪一秦昭襄王五十二年（丙午，公元前255年）
河东郡郡守王稽因犯通敌罪被判斩弃于市。应侯范睢为此闷闷不乐。昭襄王嬴稷在坐朝治事时发声长叹，范睢询问其缘故。昭襄王说：“现在武安君白起已死，郑安平、王稽等又都背叛了，国家内无良将，外却有许多敌国，我因此而忧虑！”范睢颇为恐惧，想不出用什么办法。
燕国的客卿蔡泽听说了这件事，便向西进入秦国，先让人向范睢扬言说：“蔡泽是天下能言善辩之士，他一见到秦王，就必会使您为难，进而夺取您的位置。”范睢很生气，遣人召蔡泽来见。蔡泽进见时态度傲慢不敬，使范睢大为不快，因此斥责他说：“你扬言要取代我做秦国的相国，那就让我听听你的根据。”蔡泽说：“吁，您见事何其迟啊！四个季节按春生、夏长、秋实、冬藏的次序，各完成它的功能而转换下去。您难道没有看到秦国的商鞅、楚国的吴起、越国的文种的下场吗？这有什么值得羡慕的呢？”范睢故意辩驳说：“有什么不可以的！这三个人的表现是节义的准则，忠诚的典范呀！君子可以杀身成名，并且死而无憾。”蔡泽说：“人们要建功立业，怎么会不期望着功成名就、全身而退呢！身命与功名都能保全的，是上等的愿望；功名可以为后人景仰效法而身命却已失去的，就次一等了；声名蒙受耻辱而自身得以苟全的，便是最下一等的了。商鞅、吴起、文种，他们作为臣子竭尽全力忠于君主取得了功名，这是可以为人仰慕的。但是闳夭、周公不也是既忠心耿耿又道德高尚、智慧过人吗！从君臣关系上说，那三人虽然令人仰慕，可又哪里比得上闳夭、周公啊？”范睢说：“是啊。”蔡泽说：“如此说来，您的国君在笃念旧情、不背弃有功之臣这点上能与秦孝公、楚悼王、越王哪一个相比呢？”范睢说：“我不知道能不能比。”蔡泽说：“那么您与商鞅等三人相比，谁的功绩更大呢？”范睢说：“我不如他们。”蔡泽说：“这样的话，如果您还不引退，将遇到的灾祸恐怕要比那三位更严重了。俗话说：‘太阳升到中天就要偏斜而西，月亮圆满了即会渐见亏缺。’进退伸缩，随时势的变化进行调整以求适应，是圣人的法则。现在您仇也报了，恩也报了，心愿完全得到满足却还不作变化的打算，我私下里为您担忧！”范睢于是将蔡泽奉为上宾，并把他推荐给昭襄王。秦王召见蔡泽，与他交谈，十分喜爱他，便授与他客卿的职位。范睢随即以生病为借口辞去了相国之职。昭襄王一开始就赞赏蔡泽的计策，便任命他为相国。但蔡泽任相国几个月后，即被免职。
楚国春申君黄歇任用荀卿为兰陵县令。荀卿是赵国人，名况，曾经与临武君在赵国国君孝成王赵丹面前辩论用兵之道。孝成王说：“请问什么是用兵的要旨？”临武君回答道：“上得天时，下得地利，观察敌人的变化动向，比敌人后发兵而先到达，这即是用兵的关键方略。”荀况说：“不是这样。我所听说的古人用兵的道理是，用兵攻战的根本，在于统一百姓。弓与箭不协调，就是善射的后羿也不能射中目标；六匹马不协力一致，即便善御的造父也无法将马车赶往远方；士人与百姓不和亲附国君，即是商汤、周武王也不能有必胜的把握。因此，善于使百姓归附的人，才是善于用兵的人。所以用兵的要领在于使百姓依附。”临武君说：“并非如此。用兵所重视的是形势要有利，行动要讲究诡诈多变。善用兵的人，行事疾速、隐蔽，没有人料得到他会从哪里出动。孙武、吴起采用这种战术，天下无敌，不见得一定要依靠百姓的归附啊！”荀况说：“不对。我所说的，是仁人的用兵之道和要统治天下的帝王的志向。您所看重的是权术、谋略、形势、利害。则仁人用的兵，是不能欺诈的。能够施用欺骗之术对付的，是那些骄傲轻慢的军队、疲惫衰弱的军队，以及君与臣、上级与下属之间不和相互离心离德的军队。因此用夏桀的诈术对付夏桀，还有使巧成功或使拙失败的可能。而用夏桀的骗计去对付尧，就如同拿鸡蛋掷石头，把手指伸进滚水中搅动，如同投身到水火之中，不是被烧焦，便是被淹死。故而仁人的军队，上下一条心，三军同出力；臣子对国君，下属对上级，犹如儿子侍奉父亲，弟弟侍奉哥哥，犹如用手臂保护头颅、眼睛、胸膛和腹部。这样的军队，用欺诈之术去袭击它，与先惊动了它而后才去攻击它，是一回事。况且，仁人若统治着十里的国家，他的耳目将布及百里，若统治着百里的国家，他的耳目便将布及千里，若统治着千里的国家，他的耳目就会遍及天下，这样，他必将耳聪目明、机警而有戒备，和众如一。因此仁人的军队，集结起来即为一支支百人的部队，分散开时即成战阵行列；延长伸展好似莫邪宝剑的长刃，碰上的即被斩断；短兵精锐仿佛莫邪宝剑的利锋，遇到的即被瓦解；安营扎寨稳如磐石，顶撞它的，角即遭摧折而退却。再说那暴虐国家的君主，他所依靠的是什么呢？只能是他的百姓。而他的百姓爱我就如同爱他的父母，喜欢我就如同喜欢芬芳的椒兰；反之，想起他的君主好似畏惧遭受烧灼黥刑，好似面对不共戴天的仇敌一般。人之常情，即便是夏桀、盗跖，也不会为他所厌恶的人去残害他所喜爱的人！这就犹如让人的子孙去杀害自己的父母，是根本不可能的。如此，百姓一定会前来告发君主，那又有什么诈术可施呢！所以，由仁人治理国家，国家将日益强盛，各诸侯国先来归顺的则得到安定，后来依附的即遭遇危难；相对抗的将被削弱，进行反叛的即遭灭亡。《诗经》所谓‘商汤竖起大旗，诚敬地握着斧钺，势如熊熊烈火，谁敢把我阻拦？’正是说的这种情况。”
孝成王、临武君说：“对啊。那么请问君王用兵，应该建立什么教令、如何行动才好呢？”荀况答道：“总的说来，君王贤明的，国家就太平；君王无能的，国家就混乱；推崇礼教、尊重仁义的，国家就治理得好，荒废礼教、鄙视仁义的，国家就动荡不安。秩序井然的国家便强大，纲纪紊乱的国家便衰弱，这即是强与弱的根本所在。君王的言行足以为人敬慕，百姓才可接受驱使，君王的言行不能为人景仰，百姓也就不会服从召唤。百姓可供驱使的，国家就强大，百姓不服调遣的，国家就衰弱，这即是强与弱的常理所在。齐国人重视兵家的技巧技击，施展技击之术，斩获一颗人头的，由官方赐八两金换回，不是有功同受赏。这样的军队遇到弱小的敌人，还可凑合着应付；一旦面对强大的敌军，就会涣然离散，如同天上的飞鸟，漫天穿行无拘无束，往返无常。这是亡国之军，没有比这种军队更衰弱的了，它与招募一群受雇佣的市井小人去作战相差无几。魏国按照一定的标准选拔武勇的士兵。择取时，让兵士披挂上全副铠甲，拉开十二石重的强弓，身背五十支利箭，手持戈，头戴盔，腰佩剑，携带三天的食粮，每日急行军一百里。达到这个标准的便为武勇之卒，即可被免除徭役，并分得较好的田地和住宅。但是这些士兵的气力几年后便开始衰退，而分配给他们的利益却无法再行剥夺，即使改换办法也不容易做得周全。故而，魏国的疆土虽大，税收却必定不多。这样的军队便是危害国家的军队了。秦国，百姓生计困窘，国家的刑罚却非常严酷，君王借此威势胁迫百姓出战，让他们隐蔽于险恶的地势，战胜了就给以奖赏，使他们对此习以为常，而战败了便处以刑罚，使他们为此受到箝制，这样一来，百姓要想从上面获得什么好处，除了与敌拼杀外，没有别的出路。功劳和赏赐成正比例增长，只要斩获五个甲士的头，即可役使乡里的五家，这就是秦国比其他国家强大稳固的原因。所以，秦国得以四代相沿不衰，并非侥幸，而是有其必然性的。故此齐国善技击术的军队无法抵抗魏国择勇武士兵的军队，魏国择勇武士兵的军队无法抵抗秦国精锐、进取的军队；而秦国精锐的士兵却不能抵挡齐桓公、晋文公约束有方的军队，齐桓公、晋文公约束有方的士兵又不能抵挡商汤、周武王的仁义的军队，一旦遇上了，势必如用薄脆的东西去打石头，触之即碎。况且那几个国家培养的都是争求赏赐、追逐利益的将领和士兵，他们就如同雇工靠出卖自己的力气挣钱那样，毫无敬爱国君，愿为国君拼死效力，安于制度约束，严守忠孝仁义的气节、情操。诸侯中如果有哪一个能够精尽仁义之道，便可起而兼并那几个国家，使它们陷入危急的境地。故在那几个国家中，招募或选拔士兵，推重威势和变诈，崇尚论功行赏，渐渐染成了习俗。但只有尊奉礼义教化，才能使全国上下一心，精诚团结。所以用诈术对付欺诈成俗的国家，还有巧拙之别；而若用诈术对付万众一心的国家，就犹如拿小刀去毁坏泰山了。所以商汤、周武王诛灭夏桀、商纣王时，从容指挥军队，强暴的国家却都无不臣服，甘受驱使，诛杀夏桀、商纣王，即如诛杀众叛亲离之人一般。《尚书·泰誓》崐中所说的‘独夫纣’，就是这个意思。因此军队齐心协力、众志成城，当可掌握天下；军队尚能团结合作，当可惩治临近的敌国。至于那些征召、募选士兵，推重威势诈变，崇尚论功行赏的军队，则或胜或败，变化无常；有时收缩，有时扩张，有时生存，有时灭亡，强弱不定。这样的军队可称作盗贼之兵，而君子是不会这样用兵的。”
孝成王、临武君说：“对啊。那么还请问做将领的道理。”荀况说：“谋虑最关键的是抛弃成败不明的谋划，行动最重要的是不产生过失，做事最关键的是不后悔；事情做到没有反悔就可以了，不必一定要追求尽善尽美。所以制定号令法规，要严厉、威重；赏功罚过，要坚决执行、遵守信义；营垒、辎重，要周密、严固；迁移、发动、前进、后退，要谨慎稳重，快速敏捷；探测敌情、观察敌人的变化，要行动机密，混入敌方将士之中；与敌军遭遇，进行决战，一定要打有把握的仗，不打无把握的仗。这些称为‘六术’。不要为保住自己将领的职位和权力而放弃自己取胜的策略，去迁就迎合君王的主张；不要因急于胜利而忘记还有失败的可能；不要对内威慑，而对外轻敌；不要见到利益而不顾忌它的害处；考虑问题要仔细周详而使用钱财要慷慨宽裕。这些称为‘五权’。此外，将领在三种情况下不接受君主的命令：可以杀死他，但不可令他率军进入绝境；可以杀死他，但不可令他率军攻打无法取胜的敌人；可以杀死他，但不可令他率军去欺凌百姓。这些称为‘三至’。将领接受君主命令后即调动三军，三军各自到位，百官井然有序，各项事务均安排停当、纳入正轨，此时即便君主奖之也不能使之喜悦，敌人激之也不能使之愤怒。这样的将领是最善于治军的将领。行事前必先深思熟虑，步步慎重，而且自始至终谨慎如一，这即叫作‘大吉’。总之，各项事业，如果获得成功，必定是由于严肃对待这项事业；如果造成失败，必定是由于轻视这项事业。因此，严肃胜过懈怠，便能取得胜利，懈怠胜过严肃，便将自取灭亡；谋划胜过欲望，就事事顺利，欲望胜过谋划，就会遭遇不幸。作战如同守备一样，行动如同作战一样，获得成功则看作是侥幸取得。严肃制订谋略，不可废止；严肃处理事务，不可废止；严肃对待下属，不可废止；严肃对待兵众，不可废止；严肃对待敌人，不可废止，这些称为‘五不废’。谨慎地奉行以上‘六术’、‘五权’、‘三至’，并恪守严肃不废止的原则，这样的将领便是天下无人能及的将领，便是可以上通神明的了。”
临武君说：“有道理。那么请问圣明君王的军制又该怎样。”荀况说：“崐将领建旗击鼓号令三军，至死也不弃鼓奔逃；御手驾战车，至死也不放松缰绳；百官恪守职责，至死也不离开岗位；大夫尽心效力，死于战阵行列。军队听到鼓声即前进，听到钲声即后退，服从命令是最主要的，建功还在其次。命令不准前进而前进，犹如命令禁止后退而还要后退一样，罪过是相等的。不残杀老弱，不践踏庄稼，不追捕不战而退的人，不赦免相拒顽抗的人，不俘获跑来归顺的人。该诛杀时，诛杀的不是百姓，而是祸害百姓的人。但百姓中如果有保护敌人的，那么他也就成为敌人了。所以，不战而退的人生，相拒顽抗的人死，跑来归顺的人则被献给统帅。微子启因多次规劝商纣王，后归顺周王而受封为宋国国君，专门谄谀纣王的曹触龙被处以军中重刑，归附于周天子的商朝人待遇与周朝百姓没有区别，故而近处的人唱着歌欢乐地颂扬周天子，远方的人跌跌撞撞地前来投奔周天子。此外，不论是多么边远荒僻鄙陋的国家，周天子也派人去关照，让百姓安居乐业，以至四海之内如同一家，周王朝恩威所能达到的属国，没有不服从、归顺的。这样的君王即叫作‘人师’，即为人表率的人。《诗经》说：‘自西自东，自南自北，无思不服。’就是指的这个。圣明君王的军队施行惩处而不挑起战争，固守城池而不发动进攻，与敌对阵作战而不先行出击，敌人上上下下喜悦欢欣就庆贺，并且不洗劫屠戮敌方的城镇，不偷袭无防备的敌人，不使将士们长久地滞留在外，军队出动作战不超越计划的时间，如此，便使混乱国家的百姓都喜欢这种施政方式，而不安心于受自己国君的统治，希望这种君王的军队到来。”临武君说：“你说的不错。”
陈嚣问荀况说：“您议论用兵之道，总是以仁义为根本，而仁者爱人，义者遵循情理，既然如此又怎么用兵打仗呢？一切用兵之事都是为了争夺、攻伐啊。”荀况说：“并非像你所理解的这样。所谓仁者爱人，正因为爱人，才憎恶害人的人；义者遵循情理，正因为循理，才憎恶反叛、作乱的人。所以，用兵的目的在于禁暴除害，而不是为了争夺、攻伐。”
燕国燕孝王去世，子姬喜继位。
周王朝的百姓向东逃亡。秦国人夺取了周王朝的宝鼎重器，并将西周文公姬咎迁移到狐之聚。
楚国考烈王将鲁国国君迁到莒地，夺取了鲁国的封地。
五十三年（丁未，公元前254年）
秦国将领率军讨伐魏国，攻占了吴城。韩国国君前来朝见昭襄王。魏国全国听从秦王的号令。
五十四年（戊申，公元前253年）
昭襄王在雍城南郊祭祀上帝。
楚国迁都至钜阳。
五十五年（己酉，公元前252年）
卫国卫怀君到魏国都城大梁朝见魏王，魏国人将他抓住杀了，另立他的弟弟为卫国国君，是为元君。而元君是魏王的女婿。
五十六年（庚戌，公元前251年）
秋季，秦昭襄王去世，子嬴柱继位，是为孝文王。孝文王尊奉生母唐八子为唐太后，立子嬴异人为太子。于是，赵国人便将嬴异人的妻子儿女送回秦国。韩国国君则穿着丧服来到秦国，入殡宫吊唁祭奠昭襄王。
燕国国君姬喜派使臣栗腹与赵王缔结友好盟约，并以五百金设置酒宴款待赵王。栗腹返回燕国后对燕王说：“赵国的壮年男子都死在长平之战中了，他们的孤儿还都没有长大成人，可以去进攻赵国。”燕王召见昌国君乐，询问他的意见。乐回答说：“赵国的四境都面临着强敌，需要四面抵抗，故国中百姓均已习惯于作战，不能去攻伐。”燕王说：“我可以用五个人来攻打赵国的一个人。”乐答道：“那也不行。”燕王大怒。群臣都认为可以出兵攻赵，燕王便调动两千辆战车，一路由栗腹率领，进攻城，一路由卿秦率领，进攻代地。大夫将渠说：“刚与赵国交换文件订立友好盟约，并用五百金置备酒席请赵王饮酒，而使臣一回来就发兵进攻人家，这是不吉利的，燕军队肯定无法获取战功。”燕王不听将渠的劝阻，而且还亲自率领配合主力作战的部队随大军出发。将渠一把拉住燕王腰间结系印纽的丝带，燕王气得向他猛踢一脚，将渠哭泣着说：“我不是为了我自己，而是为大王您啊！”燕国的军队抵达宋子，赵王任命廉颇为将，率军迎击燕军，在击败栗腹的部队，在代战胜卿秦、乐乘的部队，并乘胜追击燕军五百余里，顺势包围了燕国国都蓟城。燕王只得派人向赵国求和。赵国人说：“一定得让将渠前来议和才行。”于是，燕王便任命将渠为相国，前往赵国议和，赵国的军队方才退走。
这一年，赵国的平原君赵胜去世。
秦孝文王元年（辛亥，公元前250年）
冬季，十月，己亥（初四），孝文王正式登王位。但孝文王在位仅三天就去世了，他的儿子嬴异人继位，是为昭襄王。庄襄王尊奉嫡母华阳夫人为华阳太后，尊奉生母夏姬为夏太后。
燕国的一位将领率军攻克了齐国的聊城。但是有人却在燕王面前说这个将领的坏话。这位将领因此而据守聊城，不敢返回燕国。齐国相国田单率军反攻聊城，为时一年多仍然攻克不下。齐人鲁仲连便写了一封信，捆在箭上射入城中给那位燕将，向他陈述利害关系说：“替您打算，您不是回燕国就是归附齐国。而现在您独守孤城，齐国的军队一天天增多，燕国的援兵却迟迟不到，您将怎么办呢？”燕将见信后低声哭泣了好几天，但仍然犹豫不决。他想还归燕国，可是已与燕国有了嫌隙；想投降齐国，又因杀戮、俘获的齐国人太多，而害怕降齐后会遭受屈辱。于是长声叹息着说：“与其让人来杀我，宁可我自杀！”便自刎身亡。聊城城内大乱，田单趁机攻下了聊城。田单凯旋后向齐王述说鲁仲连的功绩，并要授给他爵位。鲁仲连为此逃到海边，说：“我与其因获得富贵而屈从于他人，宁可忍受贫贱而能放荡不羁、随心所欲！”
魏国国君安王魏圉向孔斌询问谁是天下高士。孔斌说：“世上没有这种人。如果说可以有次一等的，那么这个人就是鲁仲连了！”安厘王说：“鲁仲连是强求自己这样做的，而不是他本性的自然流露。”孔斌说：“人都是要强求自己去做一些事情的。假如这样不停地做下去，便会成为君子；始终不变地这样做，习惯与本性渐渐相融合，也就成为自然的了。”
昭襄王元年（壬子，公元前249年）
吕不韦任秦国的相国。
东周国国君与各诸侯国谋划着共同攻击秦国，庄襄王因此派吕不韦统帅军队讨灭了东周，将东周国君迁移到阳人聚。周王朝至此灭亡，再无人主持祭祀了。周朝至灭亡时共有七邑：河南、洛阳、城、平阴、偃师、巩、缑氏。
庄襄王封相国吕不韦为文信侯，将河南洛阳十万户作他的封地。
秦将蒙骜攻打韩国，夺取了成皋、荥阳，始设置三川郡。
楚国灭亡了鲁国，把鲁顷公迁移到，贬为平民。
二年（癸丑，公元前248年）
出现日食。
秦将蒙骜攻打赵国，夺取了榆次、狼孟等三十七城。
楚国春申君对楚考烈王说：“淮北地区与齐国接壤，防务吃紧，请在那里设置边郡，并把我封到江东。”楚王答应了他的要求。春申君便在过去吴国的旧都上筑城，作为自己的都邑。他所营造的宫室都极为华丽。
三年（甲寅，公元前247年）
秦国大将王率军进攻魏国上党郡各城，全部攻取，始设置太原郡。
秦将蒙骜率军进攻魏国，占领了高都和汲。魏军屡战屡败，魏安王为此而忧虑，便派人到赵国请信陵君魏无忌回国。信陵君惧怕归国后被判罪，不肯返回，并告诫他的门客们说：“有胆敢给魏国使者通报消息的，处死！”于是，宾客们都不敢规劝他。毛公、薛公为此拜见信陵君说：“您所以受到各国的敬重，只是因为强大的魏国还存在。现在魏国的情势危急，而您却毫不顾惜，如此，一旦秦国人攻陷了国都大梁，将先王的宗庙铲为平地，您当以何面目立在天下人的面前啊！”二人的话还未说完，信陵君已脸色大变，即刻驾车赶回魏国。魏王见到信陵君后握着他的手啜泣不止，随即便任命他为上将军。信陵君派人向各诸侯国求援，各国听说信陵君重又担任魏国的大将，都纷纷派兵援救魏国。信陵君率领五国联军在黄河以西击败蒙骜的军队，蒙骜带残部逃崐走。信陵君督师追击到函谷关，将秦军压制在关内后才领兵还魏。
魏国安陵人缩高的儿子在秦国供职，秦人让他负责守卫管城。信陵君率军攻管城不下，便派人去见安陵君说：“如果您能遣送缩高到我这里来，我将授给他五大夫的军职，并让他担任执节尉。”安陵君说：“安陵是个小国，百姓不一定都服从我的命令。还是请使者您自己前去邀请他吧。”于是就委派一个小官引导魏国的使者前往缩高的住地。使者向缩高传达了信陵君的命令，缩高听后说：“信陵君之所以看重我，是为了让我出面去进攻管城。而为父亲的攻城，作儿子的却守城，这是要被天下人耻笑的。况且我的儿子如果见到我就放弃了他的职守，那便是背叛他的国君；作父亲的若是教儿子背叛，也不是信陵君所喜欢的行为。我冒昧地再拜，不能接受信陵君的旨令。”使者回报给信陵君，信陵君勃然大怒，又派使者到安陵君那里说：“安陵国也是魏国的领地。现在我攻取不下管城，秦国的军队就会赶到这里来攻打我，这样一来，魏国肯定就危险了。希望您能将缩高活着捆送到我这里！如果您不肯这么做，我就将调动十万大军开赴安陵城下。”安陵君说：“我的先代国君成侯奉魏襄王的诏令镇守此城，并亲手把太府中所藏的国法授给了我。国法的上篇说：‘臣子杀君王，子女杀父亲，常法规定绝不赦免这类罪行。即使国家实行大赦，举城投降和临阵脱逃的人也都不能被赦免。’现在缩高推辞不受您要授与他的高位，以此成全他们的父子之义，而您却说‘一定要将缩高活着捆送到我这里来’，如此便是要让我违背襄王的诏令并废弃太府所藏的国法啊，我纵然去死，也终归不敢执行您的指示！”缩高闻听这件事后说：“信陵君这个人，性情凶暴蛮模，且刚愎自用，那些话必将给安陵国招致祸患。我已保全了自己的名声，没有违背作为臣子应尽的道义，既然如此，我又岂可让安陵君遭到来自魏国内部的危害呀！”于是便到使者居住的客舍，拔剑刎颈，自杀而死。信陵君获悉这一消息后，身着素服避住到厢房，并派使者去对安陵君道歉说：“我真是个小人啊，为要攻取管城的思虑所困扰，对您说了一些不该说的话，请让我再拜，为我的罪过向您道歉吧！”
庄襄王为了挑拨离间信陵君与魏王的关系，遣人携带万金前往魏国，寻找到被信陵君所杀的晋鄙的门客，让他去劝说魏王道：“信陵君流亡国外十年，现在重新担任了魏国的大将，各诸侯国的将领都隶属于他，致使天下的人只听说有信陵君这个人，而不知道还有魏王您了。”庄襄王又多次派人奉送礼物给信陵君表示庆贺说：“您做了魏国国君没有啊？”魏王天天都听到这类诽谤信陵君的话，不能不信，于是就令人代替信陵君统领军队。信陵君明白自己第二次因别人的诋毁而被废黜了，便以生病为由不再朝见魏王参与议事，日夜饮酒作乐，沉湎于女色中，过了四年就死去了。韩国国君桓惠王亲至魏国吊丧。信陵君的儿子颇以此为荣，便将这件事告诉了孔斌。孔斌却说：“你一定要按照崐礼制推辞掉韩王的悼念活动！礼制规定：‘邻国国君前往某国吊丧，这吊丧活动应由某国的国君来主持。’现在魏王并没有委命你代他主持吊丧仪式，因此你也就没有资格去接待韩王来进行吊丧了。”信陵君的儿子便未接受韩王的吊丧。
五月，丙午（二十六日），庄襄王去世，太子嬴政继位。嬴政这时只有十三岁，故一切国家大事都由文信侯吕不韦决定，号称他为“仲父”。
秦国属地晋阳反叛。
秦始皇帝元年（乙卯，公元前246年）
秦国大将蒙骜率军平定了晋阳的叛乱。
韩国想要消耗秦国国力，使它不发兵东征，便派遣水利家郑国赴秦，游说秦国兴修水利，从仲山起，开凿一条引泾水、沿北山东注洛河的灌溉渠。工程进行中，秦王觉察到了韩国的意图，为此要杀郑国。郑国说：“我确是为韩国延长了几年的寿命，但是这条灌溉渠如果修成了，秦国也可享万世之利啊。”秦王于是命他继续主持施工，完成了此项工程。这条水渠引淤浊而有肥效的水灌溉盐碱地四万多顷，每亩的收成都高达六斛四斗，秦国的关中一带因此更加富裕起来。
二年（丙辰，公元前245年）
秦国将领公率军进攻魏国的卷地，斩杀三万人。
赵国任命廉颇代理相国之职，率军征伐魏国，攻取了繁阳。这时，赵国国君孝成王赵丹去世，他的儿子赵偃继位，是为悼襄王。悼襄王刚执政就令武襄君乐乘取代了廉颇。廉颇因此大怒，攻击乐乘，乐乘跑开了。廉颇便逃奔到魏国的都城大梁。但他在魏很久，仍得不到信任重用。此时，赵国的军队多次遭秦军围困，赵王想重新任用廉颇，廉颇也渴望着再为赵国效力。赵王于是派使者前往大梁，观察廉颇是否还能被任用。廉颇的仇人郭开以重金贿赂那位使者，让他在赵王面前说廉颇的坏话。廉颇会见使者时，有意一餐饭吃下一斗米、十斤肉，然后披挂铠甲，跃上战马，以此显示自己还可以率军去攻城陷阵。使者回到赵国后向赵王报告说：“廉将军虽然老了，但饭量还好。只是陪我坐着的时候，不一会就去拉了三次屎。”赵王由此认为廉颇已经老了，便不再召他回国。楚王获悉了这一情况，即偷偷地派人到魏国去迎接廉颇。廉颇一担任楚国的将领后，就没有什么战功了。于是他感慨地说：“我真想指挥赵国的士兵啊！”最终死在了楚国的寿春。
三年（丁巳，公元前244年）
秦国发生大饥荒。
秦将蒙骜率军进攻韩国，夺取了十二座城池。
赵国赵悼襄王任命李牧为大将，率军攻击燕国，占领了武遂、方城。李牧是赵国防守北部边疆的优秀将领，曾经领兵驻扎在代、雁门防备匈奴。根据当时的实际需要，他可以自行任用军吏官员，而城市的税收也都直接送到李牧的帐下，充作养兵的经费。李牧令人每天宰杀好几头牛，供给将士们食用，并指挥部队练习射箭和骑马，小心谨慎地把守烽火台，多多派出侦察人员打探敌情，同时申明约束，号令说：“如果匈奴兵侵入边境进行掠夺，我军应立即收拾起人马、牛羊、物资等退入堡垒中固守，有胆敢逞强捕捉俘虏的，一律处斩！”如此，匈奴兵每次入侵，李牧的军队都严谨地点燃烽火报警，然后人马、物资退入堡垒中，只守不战。这样过了好几年，也没有什么伤亡损失。匈奴人因此全都认为李牧胆小，就连赵国的守边官兵也认为自己的将帅太胆小了。赵王为此而责备李牧，但李牧依旧维持老样子，不作变动。赵王怒不可遏，派其他人取代李牧统兵。此后一年多时间里，新任将领屡次率军迎击犯境的匈奴，可不但屡次作战失利，损失惨重，而且使边境骚扰不断，百姓无法正常地耕作和放牧。赵王不得已又派人请李牧复出，李牧以生病为由闭门不出，拒绝接见来者。可是赵王坚持着非要让他重新出马不可，李牧无奈，便说：“如果一定要用我，必须允许我仍照从前的办法行事，我才敢接受您的命令。”赵王只好答应了他的要求。李牧重返北部边境，继续实行以往的约束。匈奴人几年来侵掠都毫无所获，却终究以为李牧是畏惧他们。守边军士每天得到赏赐却不被派用去抗击匈奴，故都希望与匈奴人打一仗。李牧于是备齐精选的战车一千三百辆，精选的战马一万三千匹，曾获过百金奖赏的勇士五万人，能拉硬弓的善射的士兵十万人，将他们全部组织起来，进行作战训练，并大力组织放牧，使放牧人遍布在边境田野。匈奴人小规模地入侵，李牧指令部队假败下来，且把数十人丢弃给匈奴。匈奴的单于听到这个消息后，即率军大举来犯。李牧多设奇阵，指挥部队从左、右两翼进行包抄，大破敌兵，斩杀匈奴十多万人马，乘胜灭掉了代地以北的胡族褴，攻破东胡，使林胡部族归降。匈奴单于领残兵逃奔而去，此后十多年不敢再接近赵国边境。
在此之前，天下的文明国家有七个，其中三国的边境与戎狄部族接壤，这即是秦国，自陇以西有诸、绲戎、翟、等部族，岐、梁、泾、漆以北有义渠、大荔、乌氏、朐衍等部族；赵国北部有林胡、楼烦等部族；燕国北部有东胡、山戎等部族。这些部族各自分散居住在山谷溪涧，有自己的君长，虽往往有一百多个部族聚集在一起，却没有一个部族能将各部族统一起来。稍后，义渠部开始修筑城池以求自守，而秦国则慢慢地对它进行蚕食，到了惠王嬴驷时，攻占了它二十五座城池。及至昭襄王时，宣太后将义渠王引诱到甘泉杀了，随后即发兵进攻义渠，灭掉了该部族，始在陇西、北地、上郡等地修筑长城，崐以抵抗西北胡人的侵扰。赵国国君武灵王赵雍率军在北方击破林胡、楼烦等部族，自代经阴山下，到高阙，修筑长城，建立要塞，并设置了云中、雁门、代郡等郡。再以后，燕国的将领秦开因曾在东胡作过人质，深得东胡的信任，返回燕国后率军袭击东胡，大破东胡兵，迫使它向北退却了一千多里。燕国于是也在造阳至襄平一线筑起长城，同时设置上谷、渔阳、右北平、辽东等郡，以抵御胡人的攻掠。直到战国末期，匈奴部族才开始强大起来。
四年（戊午，公元前243年）
春季，秦将蒙骜进攻魏国，夺取了、有诡。在三月间，停止了进军。
秦国送到赵国作人质的王子回归秦国，赵国在秦国充当人质的太子赵初也返回了赵国。
七月，秦国发生蝗灾，瘟疫流行。国家下令：百姓凡缴纳粮食一千石的，即授给一级爵位。
魏国国君安王去世，子魏增继位，是为景王。
五年（己未，公元前242年）
秦将蒙骜讨伐魏国，攻克酸枣、燕、虚、长平、雍丘、山阳等三十城；始设置东郡。
当初，剧辛在赵国时与庞关系极好。不久，他到燕国做了官。燕王见到赵国的军队多次被秦军所困，廉颇离去而由庞担任赵军统帅，便想乘赵衰败之机进攻它。为此，燕王询问剧辛的意见。剧辛回答道：“庞这个人是很容易对付的！”燕王便派剧辛率兵攻打赵国。赵军统帅庞指挥军队抵抗燕军，杀了剧辛，并俘获燕兵二万人。
各诸侯国为秦国不断地进行侵略兼并而担忧不止。
六年（庚申，公元前241年）
楚、赵、魏、韩、卫结成南北合纵联盟，共同讨伐秦国。楚国楚考烈王担任纵约长，春申君执掌军务，夺取寿陵，挥师直逼函谷关。秦军出关迎战，五国的军队都大败而逃。楚王将联军的失利归罪于春申君，春申君因此渐渐被楚王疏远了。观津人朱英对春申君说：“人们都认为楚国本是一个强国，只是因为由您执掌事务才衰弱下去了。但我不这么看。先王在世时，秦国与楚国相友善，二十年间从不攻击楚国，这是为什么呢？是因为秦国要越过黾要塞来进攻楚国，十分不便；而要借道西周与东周之间，背对着韩国和魏国来征伐楚国，又为有后顾之忧不可行。但是现在不同了。魏国朝不保夕，随时都会被灭亡，根本无力顾及它的属地许、鄢陵，一旦魏国将这两地割让给秦，秦国军队距离楚国的都城陈就不过一百六十里了。我所看到的是，秦楚两国天天陷于相互争斗之中了。”楚国于是将都城由陈迁至寿春，命名为郢。春申君即去到他的封国吴地，仍行使相国的职权。
秦军攻陷魏国的朝歌和卫国的都城濮阳。卫国卫元君率领他的宗族迁移到河内郡的野王居住，倚仗山势险阻，保有魏国的河内。
七年（辛酉，公元前240年）
秦军进攻魏国，夺取了汲。
秦国夏太后去世。
秦将蒙骜去世。
八年（壬戌，公元前239年）
魏国将邺割让给赵国。
韩国国君桓惠王去世，子韩安继位。
九年（癸亥，公元前238年）
秦军征伐魏国，攻克垣、蒲两城。
夏季，四月，天气骤然酷寒，秦国百姓有被冻死的。
秦王嬴政住宿在雍城。
己酉（二十日），秦王嬴政举行成年加冠礼，同时佩带宝剑。
秦国将领杨端和率军进攻魏国，夺取了衍氏。
当初，秦王嬴政即位时年龄尚幼，太后赵姬时常与文信侯吕不韦私通。嬴政渐渐长大，吕不韦担心此事败露，给自己招致祸患，便将自己的舍人假充作宦官，进献给太后。太后非常宠幸，与他生了两个儿子，并封为长信侯，把太原作为国，国家政事都由他来决定。宾客中请求作舍人的人非常之多。嬴政身边有人曾与发生过争执，因此告发实际并不是阉割过的宦官。嬴政于是下令将交给司法官吏治罪。惊恐异常，便盗用御玺，假托秦王之命调兵遣将，企图攻击嬴政居住的蕲年宫，进行叛乱。嬴政派相国昌平君、昌文君发兵讨伐，在咸阳展开大战，斩杀叛军数百人，在兵败逃亡时被秦王的军队抓获。秋季，九月，嬴政下令诛灭父族、母族、崐妻族三族，并将氏党羽都处以车裂刑，杀灭这些党羽的宗族，舍人中因罪过较轻被放逐到蜀地的共四千多家。同时把太后迁移到雍城的阳宫囚禁起来，杀了她与所生的两个儿子。嬴政还下令说：“有敢于为太后事对我进行规劝的，一律斩首，砍断四肢，堆积在宫阙之下！”于是，有二十七人为此而死。自齐国来的客卿茅焦通名求见秦王。嬴政遣人告诉他说：“你难道没有看见那些堆积在宫阙之下的尸体吗？”茅焦回答说：“我听说天上有二十八个星宿，现在已经死了二十七个人了，我来原本就是为了凑够那二十八位数的。我可不是那种怕死的人！”使者跑回去向嬴政报告了茅焦的话。与茅焦住在一起的同乡因害怕受牵连，都背负衣物四散逃亡了。嬴政闻听使者的回报后怒发冲冠，说：“这个家伙，竟敢故意冒犯我，快取大锅来把他煮杀了，看他还如何为凑满二十八星宿而堆尸在宫阙下！”嬴政手按宝剑坐在那里，口中唾沫星乱飞，随即令使者召茅焦入见。茅焦缓缓走上前来，伏地一拜再拜后起身，声言道：“我听说有生命的人不忌讳谈人死，有国家的人不忌讳谈国亡；忌讳死的人不能维持人的生命，忌讳亡的人也不能保证国家的生存。有关生死存亡的道理，是圣明的君主急于要了解的，陛下想不想听我说一说呢？”嬴政道：“你要谈的是什么啊？”茅焦说：“陛下有狂妄背理的行为，难道自己没有意识到吗？车裂假父，把两个弟弟装进囊袋中用刑具拷打致死，将母亲迁移到雍囚禁起来，并残杀敢于进行规劝的臣子，即使是夏桀、商纣王的行为也不至于暴虐到这个地步了！如今只要天下的人听说了这些暴行，人心便全都涣散瓦解，再也不会有人向往秦国了。我为此私下里替陛下担忧！我的话都说完了！”于是便解开衣服，伏身在刑具上，等待受刑。嬴政闻言顿悟，匆忙下殿，亲自用手接扶他说：“您请起身穿好衣服，我现在愿意接受您的劝告！”随即授给他上卿的爵位。嬴政还亲自驾车，空出左边的尊位，往雍城迎接太后返回都城咸阳，母子关系和好如初。
楚国楚考烈王没有儿子，春申君为此非常忧虑，遍寻许多能生育的妇女进献给楚王，但是她们最终仍没有为楚王生下儿子。赵国人李园带来他的妹妹想要献给楚王，可听说楚王不能养儿子，便担心时间久了，自己的妹妹会失去楚王的宠幸。于是他请求服侍春申君，做春申君的舍人。不久，李园告假回赵国探亲，故意超过期限才返归春申君处。春申君问他超假的原因，他说：“齐国国君派人求娶我的妹妹，我陪那位使者饮酒，所以耽误了归期。”春申君说：“已经下聘礼订婚了吗？”李园答道：“还没有。”于是春申君便将李园的妹妹纳为妾。没过多久，李园的妹妹怀了身孕。李园即让她去劝说春申君道：“楚王非常宠信您，即便是他的亲兄弟也比不上。如今您任楚国的相国二十多年了，可楚王依旧没有得到儿子。如此，待他去世后将改立他的兄弟为国君，而新国君也必定要使他的旧亲信分别得到显贵，这样的话，您又如何能永久地保持住您的荣宠地位呀！非但如此，而且由于您受楚王宠幸，长期执掌国事，肯定对楚王的兄弟有过许多失礼的地方，一旦他们登上王位，您就要大祸临头了。现在我身怀有孕，可还无人知晓，何况我获您宠爱时间不长，倘若果真以您的尊贵身分，将我进献给楚王，一定会得到他的宠幸。如果我依赖上天的恩赐生下一个男孩儿，那么就是您的儿子要继位为王了。这样一来，楚国便全都是您的了，这与在新君主统治下身临难以预料的灾祸相比，哪一个结果更好呢？”春申君大为赞同，便将李园的妹妹送出府，安置在馆舍中居中，派人谨慎地守护，然后向楚王推荐她。楚王即把她召纳入宫中，并且很宠爱她。不久，李园的妹妹果然生了个儿子，被立为太子。
李园的妹妹成为王后后，李园也随着地位显赫，当权主事。但是他又深恐春申君将他曾指使妹妹说过的话泄漏出去，便暗中收养敢死的武士，准备让他们去杀春申君以灭口。居住在楚国都城中的人有不少知道这件事情的。不久，楚王卧病不起。朱英对春申君说：“世上有未预料到而来的洪福，也有未预料到而来的灾祸。现在您处于生死变化不定的社会之中，为喜怒无常的君王效力，身边怎么能没有您尚未预料却忽然来到的帮手呢？”春申君说：“什么叫作‘未预料到而来的洪福’呢？”朱英答道：“您担任楚国的相国二十多年了，虽然名义上是相国，实际上却已相当于国君了。如今楚王病重，随时都会死去，一旦病故，您即可辅助幼主，从而掌握国家大权，待幼主成年后再还政给他，或者干脆就面南而坐，自称为王。这便是所谓的‘未预料到而来的洪福’了”。春申君又问：“那么什么是‘未预料到而来的灾祸’呢？”朱英说：“李园不治理国事，却是您的仇敌；不管理军务统率军队，却长期以来豢养一些勇士。如此，楚王一去世，李园必定抢先入宫廷夺权，杀您灭口。这即是所谓的‘未预料到而来的灾祸。’”春申君再问道：“这样说来，‘尚未预料却忽然来到的帮手’又是怎么回事呢？”朱英回答：“您将我安置在郎中的职位上，待楚王去世，李园抢先入宫时，我替您杀了他除掉后患。这就是所谓的‘尚未预料却忽然来到的帮手’。”春申君说：“您就不必过问这些事了。李园是个软弱无能的人，况且我又对他很好，哪至于发展到这个地步呀！”朱英明白自己的建议不会被春申君采纳了，便因担心发生变故累及自己而逃亡他乡。十七天后，楚王去世，李园果然抢先进宫，把他豢养的勇士坦伏在棘门里面。春申君一进来，勇士们即两面夹击，将他刺杀，并砍下他的头颅扔到宫门外面。接着，李园又派出官吏把春申君的家人全部捕获杀了。随后，太子芈悍继位，是为幽王。
扬雄《法言》曰：“有人问，信陵君、平原君、孟尝君、春申君是否有益于国家呢？”回答的是：“国君不理政事，奸臣窃取了国家权力，他们对国家有什么益处啊！”
嬴政因吕不韦事奉先王功劳卓著，不忍心将他杀死。
十年（甲子，公元前237年）
冬季，十月，吕不韦被罢免相国之职，离开京城，到他的封国河南洛阳。
秦国的王族大臣们建议说：“各诸侯国到秦国来作官谋职的人，大都是为自己的君主来游说，以挑拨离间我们君臣上下之间的关系，因此，请大王将他们一律驱逐出境。”于是，秦王下令全国实行大搜索，驱逐外来人。客卿楚国人李斯也在被逐之列。他在临离开前还上书秦王说：“从前穆公招纳贤才，由西部戎地选得由余，东方宛城物色到百里奚，在宋国迎取了蹇叔，晋国寻求到丕豹和公孙支。如此，秦国得以兼并二十多个封国，而称霸西戎。孝公任用商鞅实行变法，使各国都亲和服从，以至今日天下大治，国势强盛。惠王采纳张仪的策略，拆散六国的合纵联盟，使它们为秦国效力。昭王得到范睢的辅佐，加强了王室的权力，遏制了贵族家族的势力。这四位君王都是依靠客卿的作用而建功立业的。如此看来，客卿有什么地方辜负了秦国啊！美色、音乐、宝珠、美玉都不产在秦国，可大王搜集来使用、享受的却很多。但对人的取舍偏不是这样，不问可不可用，不论是非曲直，凡非秦国人就一概不用，凡是客卿就一律驱逐。似此便是只看重美色、音乐、宝珠、美玉等，而轻视人才了。我听说泰山不辞让细小的泥土，故能成就其巍峨；河海不择除细流，故能成就其深广；圣贤的君王不抛弃民众，故能明示他的恩德。这便是五帝三王所以能无敌于天下的原因。现在您抛弃那些非秦国籍的平民百姓，使他们去帮助敌国，辞退那些外来的宾客，令他们去为各诸侯效力，这就是所谓的把武器借给入侵者，把粮秣送给盗匪了。”嬴政看了李斯上的这封信，即召他入见，要恢复他的官职，并撤销逐客令。此时李斯已走到了骊邑，接秦王召令后即刻回返。嬴政最终采用了李斯的计策，暗中派遣能言善辩的人携带金珠宝玉去游说各国国君。对各国有名望、有势力的人，凡是可以用钱财贿赂的，便出重金收买，结交他们，凡是不肯受贿的，便持利剑刺杀他们。挑拨各国国君与臣民之间的关系，离间他们的感情，然后派良将率兵攻打各国。这样，几年之内，秦国终于兼并了天下。
十一年（乙丑，公元前236年）
赵国人进攻燕国，夺取阳。战事还未结束，秦国的大将王剪、桓、杨端和已率军征伐赵国，攻击邺地，战领了九个城邑。其中王剪领兵攻打阏与、阳，桓率军夺取了邺、安阳。
赵国国君悼襄王去世，子赵迁继位，是为幽缪王。赵迁的母亲原是妓女，深得悼襄王的宠幸。为此，悼襄王废掉了正妻所生的长子赵嘉，将赵迁立为太子。而赵迁向来以品行不端闻名全国。
秦国文信侯吕不韦返回封国一年多了，在这期间，各诸侯国的宾客、使者纷纷前往邀请他，车马络绎不绝，在道上前后相望。嬴政为此担心吕不韦会生出什么变故，便写信给他说：“您为秦国立下了什么功劳呢？秦国封您在河南，享用十万户封地的收入？您与秦国有什么亲近关系？而要称您为‘仲父’？您还是携家属迁往蜀地居住吧！”吕不韦自知在渐渐地受到侵害逼迫，很惧怕被杀掉。
十二年（丙寅，公元前235年）
秦国的吕不韦饮毒酒自杀身亡。他的家人暗地里将他埋葬了。嬴政下令，吕不韦的舍人凡参加了哭吊的，一律驱逐、迁徙出境；并说：“从今以后崐，操持国家政事的人凡像、吕不韦一样yín乱无道的，将其家族的所有财产没收入官，照此办理！”
扬雄《法言》曰：有人问：“吕不韦他聪明吗？拿人做货物，进行交易。”回答说：“谁说吕不韦是聪明人啊！用封国换取了宗族的灭亡。吕不韦这个偷东西的人是穿墙行窃的奸雄啊！穿墙行窃的，我见过担负斗石之量，没见过窃取洛阳的。”
秦国自六月到八月，一直不降雨。
秦国调动四个郡的兵力，援助魏国进攻楚国。
十三年（丁卯，公元前234年）
秦将桓率军征伐赵国，在平阳击败赵将扈辄的军队，斩杀十万人，并杀了扈辄。赵国国君任命李牧为大将军，领兵在宜安、肥下与秦军再战，秦师大败，桓逃奔回秦国。赵王因此封李牧为武安君。
十四年（戊辰，公元前233年）
秦将桓进攻赵国，夺取了宜安、平阳、武城。
韩国国君韩安向秦国割让土地，并献出国君的大印，请求作为秦国的附庸，派遣韩非为使节往秦国拜谒问安。韩非是韩国的公子之一，精通刑名法术的学说。他看到韩国国力日益削弱，多次写信给韩王求取录用，但总得不到韩王的任用。于是，韩非深恶韩国治国不致力于访求人才，选任贤能，反而推崇虚浮、yín乱无能的蠹虫之辈，把他们安置在与实际功劳不相称的高位上；国势宽松时骄纵宠爱那些徒有虚名的学者，国势紧急时就征用那些披甲戴盔的武士；所培养的人不是所能任用的人，所能任用的人却又不是所培养的人。为廉洁正直的人遭受奸邪不正的权臣的排斥而悲伤。他考察了以往的得失变化，撰写了《孤愤》、《五蠹》、《内储》、《外储》、《说林》、《说难》等五十六篇文章，约十多万字。
秦王嬴政听说韩非是个德才兼备的人，便想约见他。韩非正好作为韩国的使者来到秦国，就趁机写信呈给嬴政，劝说道：“现今秦国的疆域方圆数千里，军队号称百万，号令森严，赏罚公平，天下没有一个国家能比得上。而我鲁莽地冒死渴求见您一面，是想说一说破坏各国合纵联盟的计略。您若真能听从我的主张，那么，您如果不能一举拆散天下的合纵联盟，战领赵国，灭亡韩国，使楚国、魏国臣服，齐国、燕国归顺，不能令秦国确立霸主的威名，使四周邻国的国君前来朝拜，就请您把我杀了在全国示众，以此告诫那些为君主出谋划策不忠诚的人。”嬴政读后，心中颇为喜悦，但一时还没有任用他。李斯很崐忌妒韩非，便对嬴政说：“韩非是韩国的一个公子，如今您想吞并各国，韩非最终还是要为韩国利益着想，而不会为秦国尽心效力的，这也是人之常情。现在您不用他，而让他在秦国长期逗留后再放他回去，这不啻是自留后患啊。还不如依法将他除掉算了。”秦王政认为李斯说得有理，便把韩非交司法官吏治罪。李斯又派人送毒药给韩非，让他及早自杀。韩非试图亲自向秦王嬴政陈述冤情，但却无法见到秦王。不久，秦王政有些后悔，就派人去赦免韩非，可是韩非已经死了。
扬雄《法言》曰：有人问：“韩非著《说难》篇议论游说之难，而他自己最终竟又死于‘说难’，那么我冒昧地请问，是什么原因使他的行动与言论相违背呢？”回答是：“游说之难就是他致死的原因啊！”那人问：“这是为什么？”答道：“君子依照礼制行动，按照道义停止，所鼓吹的学说合乎礼义就前进，不合乎礼义就后退。如此根本不用去担心自己的主张不合乎别人的意志。去劝说别人而又顾虑自己的说词不合别人的心意，那么也就会各种手段无所不用了。”有人问：“韩非正是担忧自己的主张与对方的意志不相吻合，不是吗？”答道：“游说他人却不遵照礼义准则，这是值得忧虑的。而如果遵循了礼义准则，只是主张与他人的心意不合，便不必担忧了。”
臣司马光曰：我听说君子由亲近自己的亲人而至亲近别人的亲人，由热爱自己的国家而至热爱别人的国家，因此才能功勋卓著，名声美好，从而享有百福。如今韩非为秦国出谋献策，首先就是要以灭亡他的祖国来证实他的主张，犯下此类罪过，本来就是死有余辜的，哪里还值得怜悯啊！
十五年（己巳，公元前232年）
秦王嬴政出动大军进攻赵国，一路军队抵达邺地，一路军队抵达太原，攻克了狼孟、番吾，因遇到李牧统领的赵军而撤回。
当初，燕国太子姬丹曾在赵国作人质，与生在赵国的秦王嬴政相友善。待到嬴政即位，姬丹又在秦国充当人质。但这时秦王嬴政却不以礼相待，太子丹一怒之下逃回了燕国。
十六年（庚午，公元前231年）
韩国割献南阳地给秦国。九月，秦国派军队前往韩国接收。
魏国人割献土地给秦国。
代地发生地震，自乐徐以西，北到平阴，楼台房屋墙垣大半塌毁，土地开裂一条臣缝，东西宽一百三十步。
十七年（辛未，公元前230年）
秦国的内史腾率军灭掉了韩国，俘获韩国国君韩安。秦国在韩国的土地上设置了颍川郡。
秦王政的祖母华阳太后去世。
赵国发生大饥荒。
卫国卫元君去世，子卫角继位。
十八年（壬申，公元前229年）
秦将王剪统率驻扎在上地的军队攻下井陉，杨端和率领河内驻军一同进攻赵国。赵国的大将李牧、司马尚领兵顽强抵抗秦军。于是，秦国派人用重金收买赵王的宠臣郭开，让他在赵王面前诋毁李牧和司马尚，说他们企图兴兵反叛赵国。赵王因此便派赵葱及齐国的将领颜聚取代他们。李牧不接受命令，赵国人便将他抓住杀了，并撤换了司马尚。
十九年（癸酉，公元前228年）
秦将王剪率军攻击赵军，大败赵兵，杀赵葱，颜聚逃亡。秦军于是攻陷邯郸，俘虏了赵国国君赵迁。秦王政亲自驾临邯郸，将过去与他母亲家有仇怨的人全部杀了。然后回驾，经太原、上郡返归秦都咸阳。
秦王政的母亲太后赵姬去世。
秦将王剪领兵驻扎在中山，以监视、威慑燕国。赵国的公子赵嘉统率他的宗族数百人逃往代地，自立为代王。赵国灭亡后，在逃的赵国官员们逐渐地投归代王，与燕国合兵一处，共同驻扎在上谷。
楚国国君幽王去世，国人立他的弟弟芈郝为王。三月，芈郝的庶兄负刍杀死了他，自立为楚王。
魏国国君景王去世，子魏假继位。
燕国太子姬丹怨恨秦王嬴政，想要实施报复，为此征求太傅鞠武的意见。鞠武建议太子丹西与韩、赵、魏三晋订约，南与齐、楚联合，北与匈奴媾和，赖此共同图谋秦国。太子丹说：“太傅的计略虽好，但要实现它却是旷日持久的事情，令人内心烦闷、焦躁，恐怕不能再等待了。”不久，秦国将领樊于期在本国获罪，逃到燕国。太子丹接纳了他，并让他住下。鞠武规劝太子丹说：“仅凭秦王的暴虐以及对燕国积存的愤怒、怨恨，就足以令人寒心的了，更何况他还将获悉樊将军被收留在燕国了呢！这就等于把肉弃置在饿虎往来的小道上。希望您尽快将樊将军送到匈奴去！”太子丹说：“樊将军走投无路，归附于我，这本来就是我应当舍命保护他的时候了，请您还是考虑一下其他的办法吧！”鞠武说：“做危险的事情来求取安全，制造灾祸以祈求幸福，谋略浅薄而致积怨加深，为了结交一个新的朋友，而不顾及国家将遭受大的危害，这即是所谓的积蓄怨仇并助长灾祸了！”太子丹对鞠武的劝说置之不理。
太子丹听说卫国人荆轲很贤能，便携带厚礼，以谦卑的言词求见他。太子丹对荆轲说：“现在秦国已俘虏了韩王，又乘势举兵向南进攻楚国，向北威逼赵国。赵国无力对付秦国，那么灾难就要降临到燕国头上了。燕国既小又弱，多次为战争所拖累，哪里还能够抵挡住秦国的攻势啊！各诸侯国都屈服秦国，没有哪个国家敢于再合纵抗秦了。目前，我个人的计策颇愚鲁，认为如果真能获得一位天下最大无畏的勇士，让他前往秦国胁迫秦王政，迫使他将兼并来的土地归还给各国，就像曹沫当年逼迫齐桓公归还鲁国丧失的领土一样。如此当然是最好的了。假若不行，便乘机刺杀掉秦王嬴政。秦国的大将拥兵在外，而国内发生动乱，于是君臣之间相互猜疑。趁此时机，各国如能够合纵抗秦，就一定可以击败秦军。希望您留心这件事情。”荆轲答应了充当刺客赴秦。太子丹于是安排荆轲住进上等客舍，并天天亲往舍中探望，凡能够进送、供给荆轲的东西，没有不送到的。及至秦将王剪灭亡了赵国，太子丹闻讯后惊恐不已，便想送荆轲出行。荆轲说：“我现在前往秦国，但没有令秦人信任我的理由，这就未必能接近秦王。倘若果真得到樊将军的头颅和燕国督亢的地图奉献给秦王，秦王必定很高兴召见我，那时我才能够刺杀他以回报您。”太子丹说：“樊将军在穷途末路时来投奔我，我实在不忍心杀他啊！”荆轲于是私下里会见樊于期说：“秦国对待您，可说是残酷之极，您的父母、宗族都被诛杀或没收为官奴了！现在听说秦国悬赏千斤黄金、万户封地购买您的头颅，您打算怎么办呢？”樊于期叹息地流着泪说：“那么能想出什么办法呢？”荆轲说：“希望能得到您的头颅献给秦王，秦王见此必定欢喜而召见我，那时我左手拉住他的袖子，右手持匕首刺他的胸膛。这样一来，您的大仇得报，燕国遭受欺凌的耻辱也可以消除了！”樊于期说：“这正是我日日夜夜切齿烂心地渴求实现的事情啊！”随即拔剑自刎。太子丹闻讯急奔而来，伏尸痛哭，但已经无可奈何了，就用匣子盛装起樊于期的头颅。此前，太子丹已预先求取到天下最锋利的匕首，令工匠把匕首烧红浸入毒药之中，又用这染毒的匕首试刺人，只需渗出一丝血，人就没有不立即倒毙的。于是便准备行装送荆轲出发，又派燕国的勇士秦舞阳当他的助手，二人作为使者前往秦国。', NULL, '', 'indent', 1572786800, '5dbe619d12215f0071284c3e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643583, '资治通鉴 · 卷十一  · 汉纪三', NULL, 5, 1577, 1, 1, '司马光', NULL, 10351, '57b9c6d179bc4400639cc661', '宋', 'wen', '文', '资治通鉴', '', '起屠维大渊献，尽重光赤奋若，凡三年。
太祖高皇帝中五年（己亥，公元前二零二年）
冬，十月，汉王追项羽至固陵，与齐王信、魏相国越期会击楚；信、越不至，楚击汉军，大破之。汉王复坚壁自守，谓张良曰：“诸侯不从，奈何？”对曰：“楚兵且破，二人未有分地，其不至固宜。君王能与共天下，可立致也。齐王信之立，非君王意，信亦不自坚；彭越本定梁地，始，君王以魏豹故拜越为相国，今豹死，越亦望王，而君王不早定。今能取睢阳以北至穀城皆以王彭越，从陈以东傅海与齐王信。信家在楚，其意欲复得故邑。能出捐此地以许两人，使各自为战，则楚易破也。”汉王从之。于是韩信、彭越皆引兵来。
十一月，刘贾南渡淮，围寿春，遣人诱楚大司马周殷。殷畔楚，以舒屠六，举九江兵迎黥布，并行屠城父，随刘贾皆会。
十二月，项王至垓下，兵少，食尽，与汉战不胜，入壁；汉军及诸侯兵围之数重。项王夜闻汉军四面皆楚歌，乃大惊曰：“汉皆已得楚乎？是何楚人之多也？”则夜起，饮帐中，悲歌慷慨，泣数行下；左右皆泣，莫能仰视。于是项王乘其骏马名骓，麾下壮士骑从者八百馀人，直夜，溃围南出驰走。平明，汉军乃觉之，令骑将灌婴以五千骑追之。项王渡淮，骑能属者才百馀人。至阴陵，迷失道，问一田父，田父绐曰“左”。左，乃陷大泽中，以故汉追及之。项王乃复引兵而东，至东城，乃有二十八骑。汉骑追者数千人，项王自度不得脱，谓其骑曰：“吾起兵至今，八岁矣；身七十馀战，未尝败北，遂霸有天下。然今卒困于此，此天之亡我，非战之罪也。今日固决死，愿为诸君快战，必溃围，斩将，刈旗，三胜之，令诸君知天亡我，非战之罪也。”乃分其骑以为四队，四乡。汉军围之数重。项王谓其骑曰：“吾为公取彼一将。”令四面骑驰下，期山东为三处。于是项王大呼驰下，汉军皆披靡，遂斩汉一将。是时，郎中骑杨喜追项王，项王瞋目而叱之，喜人马俱惊，辟易数里。项王与其骑会为三处，汉军不知项王所在，乃分军为三，复围之。项王乃驰，复斩汉一都尉，杀数十百人。复聚其骑，亡其两骑耳。乃谓其骑曰：“何如？”骑皆伏曰：“如大王言！”于是项王欲东渡乌江，乌江亭长舣船待，谓项王曰：“江东虽小，地方千里，众数十万人，亦足王也。愿大王急渡！今独臣有船，汉军至，无以渡。”项王笑曰：“天之亡我，我何渡为！且籍与江东子弟八千人渡江而西，今无一人还；纵江东父兄怜而王我，我何面目见之！纵彼不言，籍独不愧于心乎！”乃以所乘骓马赐亭长，令骑皆下马步行，持短兵接战。独籍所杀汉军数百人，身亦被十馀创。顾见汉骑司马吕马童，曰：“若非吾故人乎？”马童面之，指示中郎骑王翳曰：“此项王也！”项王乃曰：“吾闻汉购我头千金，邑万户，吾为若德。”乃刎而死。王翳取其头，馀骑相蹂践争项王，相杀者数十人。最其后，杨喜、吕马童及郎中吕胜、杨武各得其一体；五人共会其体，皆是，故分其户，封五人皆为列侯。楚地悉定，独鲁不下；汉王引天下兵欲屠之。至其城下，犹闻弦诵之声，为其守礼义之国，为主死节，乃持项王头以示鲁父兄，鲁乃降。汉王以鲁公礼葬项王于穀城，亲为发哀，哭之而去。诸项氏枝属皆不诛。封项伯等四人皆为列侯，赐姓刘氏；诸民略在楚者皆归之。
太史公曰：羽起陇畮之中，三年，遂将五诸侯灭秦，分裂天下而封王侯，政由羽出；位虽不终，近古以来未尝有也！及羽背关怀楚，放逐义帝而自立；怨王侯叛己，难矣！自矜功伐，奋其私智而不师古，谓霸王之业，欲以力征经营天下。五年，卒亡其国，身死东城，尚不觉寤而不自责，乃引“天亡我，非用兵之罪也，”岂不谬哉！
扬子《法言》：或问：“楚败垓下，方死，曰‘天也！’谅乎？”曰：“汉屈群策，群策屈群力；楚憞群策而自屈其力。屈人者克，自屈者负。天曷故焉！”
汉王还，至定陶，驰入齐王信壁，夺其军。
临江王共尉不降，遣卢绾、刘贾击虏之。
春，正月，更立齐王信为楚王，王淮北，都下邳。封魏相国建城侯彭越为梁王，王魏故地，都定陶。
令曰：“兵不得休八年，万民与苦甚。今天下事毕，其赦天下殊死以下。”
诸侯王皆上疏请尊汉王为皇帝。二月甲午，王即皇帝位于汜水之阳。更王后曰皇后，太子曰皇太子；追尊先媪曰昭灵夫人。诏曰：“故衡山王吴芮，从百粤之兵，佐诸侯，诛暴秦，有大功；诸侯立以为王，项羽侵夺之地，谓之番君。其以芮为长沙王。”又曰：“故粤王无诸，世奉粤祀；秦侵夺其地，使其社稷不得血食。诸侯伐秦，无诸身率闽中兵以佐灭秦，项羽废而弗立。今以为闽粤王，王闽中地。”
帝西都洛阳。
夏，五月，兵皆罢归家。
诏：“民前或相聚保山泽，不书名数。今天下已定，令各归其县，复故爵、田宅；吏以文法教训辨告，勿笞辱军吏卒；爵及七大夫以上，皆令食邑，非七大夫已下，皆复其身及户，勿事。”
帝置酒洛阳南宫，上曰：“彻侯、诸将毋敢隐朕，皆言其情。吾所以有天下者何？项氏之所以失天下者何？”高起、王陵对曰：“陛下使人攻城略地，因以与之，与天下同其利；项羽不然，有功者害之，贤者疑之，此其所以失天下也。”上曰：“公知其一，未知其二。夫运筹帷幄之中，决胜千里之外，吾不如子房；填国家，抚百姓，给饷馈，不绝粮道，吾不如萧何；连百万之众，战必胜，攻必取，吾不如韩信。三者皆人杰，吾能用之，此吾所以取天下者也。项羽有一范增而不能用，此所以为我禽也。”群臣说服。
韩信至楚，召漂母，赐千金。召辱己少年令出胯下者，以为中尉，告诸将相曰：“此壮士也。方辱我时，我宁不能杀之邪？杀之无名，故忍而就此。”
彭越既受汉封，田横惧诛，与其徒属五百馀人入海，居岛中。帝以田横兄弟本定齐地，齐贤者多附焉；今在海中，不取，后恐为乱。乃使使赦横罪，召之。横谢曰：“臣烹陛下之使郦生，今闻其弟商为汉将；臣恐惧，不敢奉诏，请为庶人，守海岛中。”使还报，帝乃诏卫尉郦商曰：“齐王田横即至，人马从者敢动摇者，致族夷！”乃复使使持节具告以诏商状，曰：“田横来，大者王，小者乃侯耳；不来，且举兵加诛焉！”横乃与其客二人乘传诣洛阳。未至三十里，至尸乡厩置。横谢使者曰：“人臣见天子，当洗沐。”因此留，谓其客曰：“横始与汉王俱南面称孤；今汉王为天子，而横乃为亡虏，北面事之，其耻固已甚矣。且吾烹人之兄，与其弟并肩而事主，纵彼畏天子之诏不敢动，我独不愧于心乎！且陛下所以欲见我者，不过欲一见吾面貌耳。今斩吾头，驰三十里间，形容尚未能败，犹可观也。”遂自刭，令客奉其头，从使者驰奏之。帝曰：“嗟乎！起自布衣，兄弟三人更王，岂不贤哉！”为之流涕，而拜其二客为都尉；发卒二千人，以王者礼葬之。既葬，二客穿其冢傍孔，皆自刭，下从之。帝闻之，大惊。以横客皆贤，馀五百人尚在海中，使使召之；至，则闻田死，亦皆自杀。
初，楚人季布为项籍将，数窘辱帝。项籍灭，帝购求布千金；敢有舍匿，罪三族。布乃髡钳为奴，自卖于朱家。朱家心知其季布也，买置田舍，身之洛阳见藤公，说曰；“季布何罪！臣各为其主用，职耳；项氏臣岂可尽诛邪？今上始得天下，而以私怨求一人，何示不广也！且以季布之贤，汉求之急，此不北走胡，南走越耳。夫忌壮士以资敌国，此伍子胥所以鞭荆平之墓也。君何不从容为上言之！”滕公待间言于上，如朱家指。上乃赦布，召拜郎中，朱家遂不复见之。布母弟丁公，亦为项羽将，逐窘帝彭城西。短兵接，帝急，顾谓丁公曰：“两贤相厄哉！”丁公引兵而还。及项王灭，丁公谒见。帝以丁公徇军中，曰：“丁公为项王臣不忠，使项王失天下者也。”遂斩之，曰：“使后为人臣无效丁公也！”
臣光曰：高祖起丰、沛以来，罔罗豪桀，招亡纳叛，亦已多矣。及即帝位，而丁公独以不忠受戮，何哉？夫进取之与守成，其势不同。当群雄角逐之际，民无定主，来者受之，固其宜也。及贵为天子，四海之内，无不为臣；苟不明礼义以示之，使为臣者，人怀贰心以徼大利，则国家其能久安乎！是故断以大义，使天下晓然皆知为臣不忠者无所自容；而怀私结恩者，虽至于活己，犹以义不与也。戮一人而千万人惧，其虑事岂不深且远哉！子孙享有天禄四百馀年，宜矣！
齐人娄敬戍陇西，过洛阳，脱輓辂，衣羊裘，因齐人虞将军求见上。虞将军欲与之鲜衣，娄敬曰：“臣衣帛，衣帛见；衣褐，衣褐见，终不敢易衣。”于是虞将军入言上，上召见，问之。娄敬曰：“陛下都洛阳，岂欲与周室比隆哉？”上曰：“然。”娄敬曰：“陛下取天下与周异。周之先，自后稷封邰，积德累善，十有馀世，至于太王、王季、文王、武王而诸侯自归之，遂灭殷为天子。及成王即位，周公相焉，乃营洛邑，以为此天下之中也，诸侯四方纳贡职，道里均矣。有德则易以王，无德则易以亡。故周之盛时，天下和洽，诸侯、四夷莫不宾服，效其贡职。及其衰也，天下莫朝，周不能制也；非唯其德薄也，形势弱也。今陛下起丰、沛，卷蜀、汉，定三秦，与项羽战荥阳、成皋之间，大战七十，小战四十；使天下之民，肝脑涂地，父子暴骨中野，不可胜数，哭泣之声未绝，伤夷者未起；而欲比隆于成、康之时，臣窃以为不侔也。且夫秦地被山带河，四塞以为固，卒然有急，百万之众可立具也。因秦之故，资甚美膏腴之地，此所谓天府者也。陛下入关而都之，山东虽乱，秦之故地可全而有也。夫与人斗，不搤其亢，拊其背，未能全其胜也。今陛下案秦之故地，此亦扼天下之亢而拊其背也。”帝问群臣，群臣皆山东人，争言：“周王数百年，秦二世即亡。洛阳东有成皋，西有殽、渑，倍河，乡伊、洛，其固亦足恃也。”上问张良。良曰：“洛阳虽有此固，其中小不过数百里，田地薄，四面受敌，此非用武之国也。关中左殽、函，右陇、蜀，沃野千里。南有巴、蜀之饶，北有胡苑之利。阻三面而守，独以一面东制诸侯；诸侯安定，河、渭漕輓天下，西给京师；诸侯有变，顺流而下，足以委输。此所谓金城千里，天府之国也。娄敬说是也。”上即日车驾西，都长安。拜娄敬为郎中，号曰奉春君，赐姓刘氏。
张良素多病，从上入关，即道引，不食穀，杜门不出，曰：“家世相韩，及韩灭，不爱万金之资，为韩报雠强秦，天下振动。今以三寸舌为帝者师，封万户侯，此布衣之极，于良足矣。愿弃人间事，欲从赤松子游耳。”
臣光曰：夫生之有死，譬犹夜旦之必然；自古及今，固未尝有超然而独存者也。以子房之明辨达理，足以知神仙之为虚诡矣；然其欲从赤松子游者，其智可知也。夫功名之际，人臣之所难处。如高帝所称者，三杰而已。淮阳诛夷，萧何系狱，非以履盛满而不止耶！故子房托于神仙，遗弃人间，等功名于外物，置荣利而不顾，所谓明哲保身者，子房有焉。
六月，壬辰，大赦天下。
秋，七月，燕王臧荼反；上自将征之。
赵景王耳、长沙文王芮皆薨。
九月，虏藏荼。壬子，立太尉长安侯卢绾为燕王。绾家与上同里闬，绾生又与上同日；上宠幸绾，群臣莫敢望，故特王之。
项羽故将利几反，上自击破之。
后九月，治长乐宫。
项王将钟离昧，素与楚王信善。项王死后，亡归信。汉王怨昧，闻其在楚，诏楚捕昧。信初之国，行县邑，陈兵出入。
太祖高皇帝中六年（庚子，公元前二零一年）
冬，十月，人有上书告楚王信反者。帝以问诸将，皆曰：“亟发兵，坑竖子耳！”帝默然。又问陈平。陈平曰：“人上书言信反，信知之乎？”曰：“不知。”陈平曰：“陛下精兵孰与楚？”上曰：“不能过。”平曰：“陛下诸将，用兵有能过韩信者乎？”上曰：“莫及也。”平曰：“今兵不如楚精而将不及，举兵攻之，是趣之战也，窃为陛下危之。”上曰：“为之奈何？”平曰：“古者天子有巡狩，会诸侯。陛下第出，伪游云梦，会诸侯于陈。陈，楚之西界；信闻天子以好出游，其势必无事而郊迎谒；谒而陛下因禽之，此特一力士之事耳。”帝以为然，乃发使告诸侯会陈，“吾将南游云梦。”上因随以行。楚王信闻之，自疑惧，不知所为。或说信曰：“斩钟离昧以谒上，上必喜，无患。”信从之。十二月，上会诸侯于陈，信持昧首谒上；上令武士缚信，载后车。信曰：“果若人言：‘狡兔死，走狗烹；飞鸟尽，良弓藏；敌国破，谋臣亡。’天下已定，我固当烹！”上曰：“人告公反。”遂械系信以归，因赦天下。
田肯贺上曰：“陛下得韩信，又治秦中。秦，形胜之国也，带河阻山，地势便利；其以下兵于诸侯，譬犹居高屋之上建瓴水也。夫齐，东有琅邪、即墨之饶，南有泰山之固，西有浊河之限，北有勃海之利；地方二千里，持戟百万，此东西秦也，非亲子弟，莫可使王齐者。”上曰：“善！”赐金五百斤。
上还，至洛阳，赦韩信，封为淮阴侯。信知汉王畏恶其能，多称病，不朝从；居常鞅鞅，羞与绛、灌等列。尝过樊将军哙，哙跪拜送迎，言称臣，曰：“大王乃肯临臣！”信出门，笑曰：“生乃与哙等为伍！”上尝从容与信言诸将能将兵多少。上问曰：“如我能将几何？”信曰：“陛下不过能将十万。”上曰：“于君何如？”曰：“臣多多而益善耳。”上笑曰：“多多益善，何为为我禽？”信曰：“陛下不能将兵而善将将，此乃信之所以为陛下禽也。且陛下，所谓天授，非人力也。”
甲申，始剖符封诸功臣为彻侯。萧何封酂侯，所食邑独多。功臣皆曰：“臣等身被坚执锐，多者百馀战，小者数十合。今萧何未尝有汗马之劳，徒持文墨议论，顾反居臣等上，何也？”帝曰：“诸君知猎乎？夫猎，追杀兽兔者，狗也；而发纵指示兽处者，人也。今诸君徒能得走兽耳，功狗也；至如萧何，发纵指示，功人也。”群臣皆不敢言。张良为谋臣，亦无战斗功；帝使自择齐三万户。良曰：“始，臣起下邳，与上会留，此天以臣授陛下。陛下用臣计，幸而时中。臣愿封留足矣，不敢当三万户。”乃封张良为留侯。封陈平为户牖侯。平辞曰：“此非臣之功也。”上曰：“吾用先生谋计，战胜克敌，非功而何？”平曰：“非魏无知，臣安得进？”上曰：“若子，可谓不背本矣！”乃复赏魏无知。帝以天下初定，子幼，昆弟少，惩秦孤立而亡，欲大封同姓以填抚天下。
春，正月，丙午，分楚王信地为二国，以淮东五十三县立从兄将军贾为荆王，以薛郡、东海、彭城三十六县立弟文信君交为楚王。壬子，以云中、雁门、代郡五十三县立兄宜信侯喜为代王；以胶东、胶西、临淄、济北、博阳、城阳郡七十三县立微时外妇之子肥为齐王，诸民能齐言者皆以与齐。
上以韩王信材武，所王北近巩、洛，南迫宛、叶，东有淮阳，皆天下劲兵处；乃以太原郡三十一县为韩国，徙韩王信王太原以北，备御胡，都晋阳。信上书曰：“国被边，匈奴数入寇；晋阳去塞远，请治马邑。”上许之。
上已封大功臣二十馀人，其馀日夜争功不决，未得行封。上在洛阳南宫，从复道望见诸将，往往相与坐沙中语。上曰：“此何语？”留侯曰：“陛下不知乎？此谋反耳！”上曰：“天下属安定，何故反乎？”留侯曰：“陛下起布衣，以此属取天下。今陛下为天子，而所封皆故人所亲爱，所诛皆平生所仇怨。今军吏计功，以天下不足遍封；此属畏陛下不能尽封，恐又见疑平生过失及诛，故即相聚谋反耳。”上乃忧曰：“为之奈何？”留侯曰：“上平生所憎、群臣所共知，谁最甚者？”上曰：“雍齿与我有故怨，数尝窘辱我；我欲杀之，为其功多，故不忍。”留侯曰：“今急先封雍齿，则群臣人人自坚矣。”于是上乃置酒，封雍齿为什方侯；而急趋丞相、御史定功行封。群臣罢酒，皆喜，曰：“雍齿尚为侯，我属无患矣！”
臣光曰：张良为高帝谋臣，委以心腹，宜其知无不言；安有闻诸将谋反，必待高帝目见偶语，然后乃言之邪？盖以高帝初得天下，数用爱憎行诛赏，或时害至公，群臣往往有觖望自危之心，故良因事纳忠以变移帝意，使上无阿私之失，下无猜惧之谋，国家无虞，利及后世。若良者，可谓善谏矣。
列侯毕已受封，诏定元功十八人位次。皆曰：“平阳侯曹参，身被七十创，攻城略地，功最多，宜第一。”谒者、关内侯鄂千秋进曰：“群臣议皆误。夫曹参虽有野战略地之功，此特一时之事耳。上与楚相距五岁，失军亡众，跳身遁者数矣，然萧何常从关中遣军补其处，非上所诏令召，而数万众会。上之乏绝者数矣。又军无见粮，萧何转漕关中，给食不乏。陛下虽数亡山东，萧何常全关中以待陛下。此万世之功也。今虽无曹参等百数，何缺于汉；汉得之，不必待以全。奈何欲以一旦之功而加万世之功哉！萧何第一，曹参次之。”上曰：“善！”于是乃赐萧何带剑履上殿，入朝不趋。上曰：“吾闻进贤受上赏。萧何功虽高，得鄂君乃益明。”于是因鄂千秋故所食邑，封为安平侯。是日，悉封何父子兄弟十馀人，皆有食邑；益封何二千户。上归栎阳。
夏，五月，丙午，尊太公为太上皇。
初，匈奴畏秦，北徙十馀年。及秦灭，匈奴复稍南渡河。单于头曼有太子曰冒顿。后有所爱阏氏，生少子，头曼欲立之。是时，东胡强而月氏盛，乃使冒顿质于月氏。既而头曼急击月氏，月氏欲杀冒顿。冒顿盗其善马骑之，亡归；头曼以为壮，令将万骑。冒顿乃作鸣镝，习勒其骑射。令曰：“鸣镝所射而不悉射者，斩之！”冒顿乃以鸣镝自射其善马，既又射其爱妻；左右或不敢射者，皆斩之。最后以鸣镝射单于善马，左右皆射之。于是冒顿知其可用。从头曼猎，以鸣镝射头曼，其左右亦皆随鸣镝而射。遂杀头曼，尽诛其后母与弟及大臣不听从者。冒顿自立为单于。东胡闻冒顿立，乃使使谓冒顿：“欲得头曼时千里马。”冒顿问群臣，群臣皆曰：“此匈奴宝马也，勿与！”冒顿日；“奈何与人邻国而爱一马乎！”遂与之。居顷之，东胡又使使谓冒顿：“欲得单于一阏氏。”冒顿复问左右，左右皆怒曰：“东胡无道，乃求阏氏！请击之！”冒顿曰：“奈何与人邻国爱一女子乎！”遂取所爱阏氏予东胡。东胡王愈益骄。东胡与匈奴中间有弃地莫居，千馀里，各居其边，为瓯脱。东胡使使谓冒顿：“此弃地，欲有之。”冒顿问群臣，群臣或曰：“此弃地，予之亦乎，勿与亦可！”于是冒顿大怒曰：“地者，国之本也，奈何予之！”诸言予之者，皆斩之。冒顿上马，令：“国中有后出者斩！”遂袭击东胡。东胡初轻冒顿，不为备；冒顿遂灭东胡。既归，又西击走月氏，南并楼烦、白羊河南王，遂侵燕、代，悉收蒙恬所夺匈奴故地与汉关故河南塞至朝那、肤施。是时，汉兵方与项羽相距，中国罢于兵革，以故冒顿得自强，控弦之士三十馀万，威服诸国。秋，匈奴围韩王信于马邑。信数使使胡，求和解。汉发兵救之。疑信数间使，有二心，使人责让信。信恐诛，九月，以马邑降匈奴。匈奴冒顿因引兵南逾句注，攻太原，至晋阳。
帝悉去秦苛仪法，为简易。群臣饮酒争功，醉，或妄呼，拔剑击柱，帝益厌之。叔孙通说上曰：“夫儒者难与进取，可与守成。臣愿征鲁诸生，与臣弟子共起朝仪。”帝曰：“得无难乎？”叔孙通曰：“五帝异乐，三王不同礼，礼者，因时世、人情为之节文者也。臣愿颇采古礼，与秦仪杂就之。”上曰：“可试为之，令易知，度吾所能行者为之。”于是叔孙通使征鲁诸生三十馀人。鲁有两生不肯行，曰：“公所事者且十主，皆面谀以得亲贵。今天下初定，死者未葬，伤者未起，又欲起礼、乐。礼、乐所由起，积德百年而后可兴也。吾不忍为公所为。公去矣，无污我！”叔孙通笑曰：“若真鄙儒也，不知时变。”遂与所微三十人西，及上左右为学者与其弟子百馀人，为绵蕞，野外习之。月馀，言于上曰：“可试观矣。”上使行礼，曰：“吾能为此。”乃令群臣习肄。
太祖高皇帝中七年（辛丑，公元前二零零年）
冬，十月，长乐宫成，诸侯群臣皆朝贺。先平明，谒者治礼，以次引入殿门，陈东、西乡。卫官侠陛及罗立廷中，皆执兵，张旗帜。于是皇帝传警，辇出房；引诸侯王以下至吏六百石以次奉贺，莫不振恐肃敬。至礼毕，复置法酒。诸侍坐殿上，皆伏，抑首；以尊卑次起上寿。觞九行，谒者言“置酒”，御史执法举不如仪者，辄引去。竟朝置酒，无敢讙哗失礼者。于是帝曰：“吾乃今日知为皇帝之贵也！”乃拜叔孙通为太常，赐金五百斤。初，秦有天下，悉内六国礼仪，采择其尊君、抑臣者存之。及通制礼，颇有所增损，大抵皆袭秦故，自天子称号下至佐僚及宫室、官名，少所变改。其书，后与律、令同录，藏于理官。法家又复不传，民臣莫有言者焉。
臣光曰：礼之为物大矣！用之于身，则动静有法而百行备焉；用之于家，则内外有别而九族睦焉；用之于乡，则长幼有伦而俗化美焉；用之于国，则君臣有叙而政治成焉；用之于天下，则诸侯顺服而纪纲正焉；岂直几席之上、户庭之间得之而不乱哉！夫以高祖之明达，闻陆贾之言而称善，睹叔孙通之仪而叹息；然所以不能比肩于三代之王者，病于不学而已。当是之时，得大儒而佐之，与之以礼为天下，其功烈岂若是而止哉！惜夫，叔孙生之为器小也！徒窃礼之糠粃，以依世、谐俗、取宠而已，遂使先王之礼沦没而不振，以迄于今，岂不痛甚矣哉！是以扬子讥之曰：“昔者鲁有大臣，史失其名，曰：‘何如其大也！’曰：‘叔孙通欲制君臣之仪，召先生于鲁，所不能致者二人。’曰：‘若是，则仲尼之开迹诸侯也非邪？”曰：‘仲尼开迹，将以自用也。如委己而从人，虽有规矩、准绳，焉得而用之！’”善乎扬子之言也！夫大儒者，恶肯毁其规矩、准绳以趋一时之功哉！
上自将击韩王信，破其军于铜鞮，斩其将王喜。信亡走匈奴；白土人曼丘臣、王黄等立赵苗裔赵利为王，复收信败散兵，与信及匈奴谋攻汉。匈奴使左、右贤王将万馀骑，与王黄等屯广武以南，至晋阳，汉兵击之，匈奴辄败走，已复屯聚，汉兵乘胜追之。会天大寒，雨雪，士卒堕指者什二三。
上居晋阳，闻冒顿居代谷，欲击之。使人觇匈奴，冒顿匿其壮士、肥牛马，但见老弱及羸畜。使者十辈来，皆言匈奴可击。上复使刘敬往使匈奴，未还；汉悉兵三十二万北逐之，逾句注。刘敬还，报曰：“两国相击，此宜夸矜，见所长。今臣往，徒见羸瘠、老弱，此必欲见短，伏奇兵以争利。愚以为匈奴不可击也。”是时，汉兵已业行，上怒，骂刘敬曰：“齐虏以口舌得官，今乃妄言沮吾军！”械系敬广武。帝先至平城，兵未尽到；冒顿纵精兵四十万骑，围帝于白登七日，汉兵中外不得相救饷。帝用陈平秘计，使使间厚遗阏氏。阏氏谓冒顿曰：“两主不相困。今得汉地，而单于终非能居之也。且汉主亦有神灵，单于察之！”冒顿与王黄、赵利期，而黄、利兵不来，疑其与汉有谋，乃解围之一角。会天大雾，汉使人往来，匈奴不觉。陈平请令强弩傅两矢，外乡，从解角直出。帝出围，欲驱；太仆滕公固徐行。至平城，汉大军亦到，胡骑遂解去。汉亦罢兵归，令樊哙止定代地。上至广武，赦刘敬，曰：“吾不用公言，以困平城；吾皆已斩前使十辈矣。”乃封敬二千户为关内侯，号为建信侯。帝南过曲逆，曰：“壮哉县！吾行天下，独见洛阳与是耳。”乃更封陈平为曲逆侯，尽食之。平从帝征伐，凡六出奇计，辄益封邑焉。
十二月，上还，过赵。赵王敖执子婿礼甚卑，上箕倨慢骂之。赵相贯高、赵午等皆怒，曰：“吾王，孱王也！”乃说王曰：“天下豪桀并起，能者先立。今王事帝甚恭，而帝无礼；请为王杀之！”张敖啮其指出血，曰：“君何言之误！先人亡国，赖帝得复，德流子孙；秋豪皆帝力也。愿君无复出口！”贯高、赵午等皆相谓曰：“乃吾等非也。吾王长者，不倍德；且吾等义不辱。今帝辱我王，故欲杀之，何洿王为！事成归王，事败独身坐耳！”
匈奴攻代。代王喜弃国自归，赦为郃阳侯。辛卯，立皇子如意为代王。
春，二月，上至长安。萧何治未央宫，上见其壮丽，甚怒，谓何曰：“天下匈匈，苦战数岁，成败未可知，是何治宫室过度也！”何曰：“天下方未定，故可因以就宫室。且夫天子以四海为家，非壮丽无以重威，且无令后世有以加也。”上说。
臣光曰：王者以仁义为丽，道德为威，未闻其以宫室填服天下也。天下未定，当克己节用以趋民之急；而顾以宫室为先，岂可谓之知所务哉！昔禹卑宫室而桀为倾宫。创业垂统之君，躬行节俭以示子孙，其末流犹入于淫靡，况示之以侈乎！乃云“无令后世有以加”，岂不谬哉！至于孝武，卒以宫室罢敝天下，未必不由酂侯启之也！
上自栎阳徙都长安。
初置宗正官，以序九族。
夏，四月，帝行如洛阳。', '', '', '汉纪三汉高帝五年（己亥，公元前202年）
冬季，十月，汉王刘邦追击项羽到达固陵，与齐王韩信、魏国的相国彭越约定日期合击楚军。但是韩信、彭越的军队没有来，楚军攻打汉军，大败了汉军。汉王于是重又坚固营垒加强防守，并对张良说：“诸侯不遵守信约，怎么办啊？”张良答道：“楚军即将被打败，而韩信、彭越二人没有分得确定的领地，因此他们不应约前来会合，原来是应当的。君王您如果能与他们一起共分天下，就可以立即把他们召来。齐王韩信的封立，并不是您的本意，韩信自己也不放心。彭越本来平定了梁地，当初您为了魏豹的缘故，封彭越为魏国相国。而今魏豹已死，彭越也想自己称王，但您却不早作决定。现在，您可以把从睢阳以北到城的地区都封给彭越，把从陈县以东到沿海地区的区域划给韩信。韩信的家乡在楚地，他的意思也是想要重新得到自己故乡的土地。您如果能拿出以上地区许给他们两人，让他们各自为自己的利益而战，那么楚国就很容易攻破了。”汉王听从了这一建议。于是韩信、彭越都率军前来。
十一月，刘邦的堂兄刘贾南渡淮河，包围了寿春，派人去诱降楚国的大司马周殷。周殷即反叛楚国，用舒地的兵力屠灭了六地，并调发九江的部队迎接黥布，一同去屠灭了城父，接着便随同刘贾等人一齐会合。
十二月，项羽到了垓下，兵少粮尽，与汉军交战未能取胜，便退入营垒固守。这时汉军和诸侯的军队将项羽的军营重重包围了起来。项羽在晚上听到汉军四面都唱起楚歌，就大惊道：“汉军已经全部得到楚国的土地了吗？是什么原因楚人这么多呀！”便连夜起身，在帐中饮酒，慷慨悲歌，泪下数行，侍从人员见状也都纷纷哭泣，全不忍心抬头观看。项羽于是骑上他的名叫骓的骏马，部下的壮士骑马相随的有八百多人，当夜即突围往南奔驰。天大亮时，汉军才发觉，便命令骑将灌婴率五千名骑士追赶。项羽渡过淮河，相随的骑兵能跟得上他的才一百多人。到达阴陵后，项羽一行人迷了路，就向一个农夫问路，农夫骗他说“往左”。但是项羽等往左走，却陷进了大沼泽地中。汉军因此便追上了他们。
项羽于是又领兵向东奔走，到达东城，相随的只有二十八个骑兵了。而这时汉军骑兵追逐前来的有好几千人。项羽自己料想是不能脱身了，便对他的骑崐兵们说：“我从起兵到现在，已经八年了，身经七十多次战斗，不曾失败过，这才霸有了天下。但是今天终于被困在这里，这是上天要灭亡我啊，并不是我用兵有什么过错！今天定要一决生死，愿为你们痛快地打一仗，一定突破重围，斩杀敌将、砍倒汉旗，接连三次取胜，让你们知道是天要亡我，而不是我用兵的过错。”随即把他的人马分为四队，向四个方向冲杀。但汉军已将他们重重包围。项羽便对他的骑兵们说：“看我为你们斩杀他一员将领！”就命令骑士们从四面奔驰而下，约定在山的东边分三处会合。接着项羽便大声呼喝着策马飞奔而下，汉军随即都溃败散乱，项羽就斩杀了一员汉将。这时，郎中骑杨喜追击项羽，项羽瞪着双眼厉声呵叱他，杨喜人马都受到惊吓，退避了好几里地。项羽便与他的骑兵们分三处相会合，汉军不知道项羽究竟在哪里，于是分兵三路，重又把他们包围了起来。项羽随即奔驰冲杀，又斩杀了汉军的一名都尉，杀掉了汉军百十来人，重新聚拢了他的骑兵，至此不过仅损失了两名骑士罢了。项羽就对他的骑兵们说：“怎么样啊？”骑兵们都敬服地说：“正像大王您所说的一样！”
这时项羽就想东渡乌江，乌江亭长把船停泊在岸边等着他，并对项羽说：“江东虽然狭小，土地方圆千里，民众几十万人，却也足够用以称王的了。望大王您火速渡江！现在只有我有船，汉军到来，无船渡江。”项羽笑着说：“上天要灭亡我，我还要渡江做什么呀！况且我与江东子弟八千人渡江西征，而今没有一个人归还，纵使江东父老怜爱我，仍然以我为王，我又有什么脸面去见他们啊！即便他们不说什么，难道我就不感到心中有愧吗！”于是就把自己所骑的骏马骓送给了亭长，命令他的骑兵都下马步行，手持短兵器与汉军交战。仅项羽一人就杀死了汉军几百人，项羽自己也身受十多处伤。这时项羽回头看见了汉军骑司马吕马童，就说：“你不是我的老朋友吗？”吕马童背过脸，指给中郎骑王翳说：“这就是项王！”项羽便说道：“我听说汉王悬赏千金买我的头颅，分给万户的封地，我就留给你一些恩德吧！”即自刎而死。王翳随即取下项羽的头颅。其余的骑兵便相互践踏着争抢项羽的躯体，互为残杀的有几十个人。到了最后，杨喜、吕马童和郎中吕胜、杨武各夺得项羽的一部分肢体。五个人把项羽的肢体会合拼凑到一起，都对得上，因此便分割原来悬赏的万户封地，将五人都封为列侯。
楚地全部平定了，唯独鲁县仍不投降。汉王刘邦率领天下的兵马，打算屠灭它。大军抵达城下，仍然能听到城中礼乐弦诵的声音，由于鲁县是信守礼义的故国，为自己的君主尽忠守节，汉军便拿出项羽的头颅给鲁县的父老看，鲁县这才投降。汉王用葬鲁公的礼仪把项羽葬在城，并亲自为项羽发丧举哀，哭了一阵后离去。对项羽的家族亲属都不加杀害，还把项伯等四人都封为列侯，赐他们姓刘，将过去被掳掠到楚国来的百姓们仍归他们统治。
太史公司马迁曰：项羽起于田野民间，才三年就率领着齐、赵、韩、魏、崐燕五诸侯国的军队灭亡了秦朝，分割天下而封授王侯，政令全由项羽发布，他的王位虽然未获终结，却也是近古以来所不曾有过的了！待到项羽背弃关中而怀恋楚国故土，放逐义帝而自立为王，这时怨恨诸侯王们背叛自己，可就很难说得通了！还自我夸耀战功，一味逞个人小聪明而不效法古人，认为霸王的功业，就是要用武力征伐来经营治理天下。结果只五年的时间，终于失掉了自己的国家，自身死在东城，却还不觉悟、不责备自己，反倒借口“上天要灭亡我，而并非我用兵的过错”，这难道不是荒谬之极吗！
扬雄《法言》曰：有人问：“楚王兵败垓下，将要死的时候说道：‘是上天亡我！’可以相信这种说法吗？”回答说：“汉王刘邦尽量发挥、利用众人的计谋，这些计谋调动了众人的力量。楚王项羽憎恶采用众人的计谋，只发挥个人的作用。而善于发挥、利用众人智谋和力量的人就能取得胜利，只凭一己的智谋和力量的人就必定失败，这与上天有什么关系啊！”
汉王回军到达定陶县，奔入齐王韩信的营垒，接管了他的部队。
临江王共尉仍不归降，汉王便派卢绾、刘贾攻打并俘获了他。
春季，正月，汉王改封齐王韩信为楚王，统辖淮河以北地区，都城设在下邳。封魏相国建城侯彭越为梁王，统辖魏国故地，都城设在定陶。
汉王下令说：“军队得不到休整已经八年了，万民饱受战乱之苦。现在夺取天下的大事已经完成，赦免天下判斩刑以下的所有罪犯。”
诸侯王一致上疏，请求推尊汉王为皇帝。二月甲午（初三），汉王便在水北面登上帝位。改称王后为皇后，王太子为皇太子；追尊先母为昭灵夫人。
颁布诏书说：“原衡山王吴芮，率领百粤部族之兵，协助诸侯军，诛灭残暴的秦王朝，建有大功，诸侯立他为王，但项羽却侵夺了他的封地，称他作番君。现在改封吴芮为长沙王。”又说：“原粤王无诸，世代供奉粤国的祖宗。秦王朝侵夺了他的土地，使粤国的社稷不能再享受祭祀。诸侯征伐秦朝，无诸亲自率领闽中的军队相协助，攻灭了秦王朝，项羽却将他废黜不予封立。现在封无诸为闽粤王，统辖闽中一带。”
高帝刘邦向西建都洛阳。
夏季，五月，士兵们都复员回家。
高帝刘邦颁布诏书：“百姓中以前有的人相聚安守在深山大泽中躲避战乱，未登记入户籍中。如今天下已经平定，诏令这些百姓各自返回他们的所在县，恢复他们过去的爵位和田地住宅；官吏应依据法律义理进行教诲，处理纠纷，不得鞭笞侮辱军中官兵；凡爵位至七大夫以上的，都让他们享用封地民户的赋税收入，非七大夫爵位及其以下的，都免除其个人及一户之内的赋税徭投，不予征收。”
高帝刘邦在洛阳南宫举行酒宴，高帝说道：“各位列侯、各位将军，不要对朕隐瞒，都来说说这个道理：我之所以能取得天下的原因是什么？项羽之所以失掉天下的原因又是什么呀？”高起、王陵回答说：“陛下派人攻城掠地，攻取了城邑、土地就分封给他，与大家同享利益；项羽却不是这样，他对有功的人嫉恨，对贤能的人猜疑，这就是他失去天下的原因。”高帝说：“你们是只知其一，不知其二啊。谈到运筹帷幄之中，决胜千里之外，我不如张良；镇守国家，安抚百姓，供给粮饷，保持运粮道路畅通无阻，我不如萧何；统率百万大军，战必胜，攻必克，我不如韩信。这三位都是人中英杰，而我能够任用他们，这就是我所以能取得天下的原因。项羽虽然有一个范增，却不能信任使用他，这便是项羽所以被我捕捉打败的原因了。”群臣都心悦诚服。
韩信到了楚地，召见曾经分给自己饭吃的那位漂洗丝绵的老妇，赐给她一千金。又召见曾经羞辱自己、叫自己从胯下爬过去的那个人，任命他为楚国的中尉；并告诉将相们说：“这是位壮士啊。当他侮辱我时，我难道就不能杀了他吗？只是杀他没有名义，所以忍了下来，才达到了今天这样的成就。”
彭越已受汉封梁王，田横怕被杀掉，与他的部下五百多人进入大海，居住在岛上。高帝刘邦认为田横兄弟几人本来曾平定了齐地，齐地贤能的人大都归附了他，今流亡在海岛中，如不加以招抚，以后恐怕会作乱。于是就派使者去赦免田横的罪过，召他前来。田横推辞说：“我曾煮杀了陛下的使臣郦食其，现在听说他的弟弟郦商是汉的将领，我很害怕，不敢奉诏前往，只请求做个平民百姓，留守在海岛中。”使者回报，高帝便诏令卫尉郦商说：“齐王田横即将到来，有敢动一动他的随从人马的人，即诛灭家族！”随即再派使者拿着符节把高帝诏令郦商的情况对田横一一讲明，并说道：“田横若能前来，高可以封王，低也是个侯哇。如果不来，便要发兵加以诛除了。”
田横便和他的两个宾客乘坐驿站的传车去到洛阳。离洛阳还有三十里，到达尸乡驿站。田横向使者道歉说：“为人臣子的人觐见天子时，应当沐浴。”随即住下来，对他的宾客说：“我起初与汉王一道面朝南称王，而今汉王做了天子，我却是作为败亡的臣虏，面北称臣伺候他，这耻辱本来已非常大了。何况我还煮死了人家的兄长，又同被煮人的弟弟并肩侍奉他们的君主呢。即便这位弟弟畏惧天子的诏令不敢动我，我难道内心就不感到惭愧吗？！况且陛下想要见我的原因，不过是想看一看我的容貌罢了。现在斩下我的头颅，奔驰三十里地送去，神态容貌还不会变坏，仍然可以看的。”于是就用刀割自己的脖子崐，并让宾客捧着他的头颅，随同使者疾驰洛阳奏报。高帝说：“唉呀！从平民百姓起家，兄弟三人相继为王，这难道不是很贤能的吗！”为田横流下了眼泪。接着授给田横的两个宾客都尉的官职，调拨士兵二千人，按葬侯王的礼仪安葬了田横。下葬以后，那两位宾客在田横的坟墓旁挖了个坑，都自刎而死，倒进坑里陪葬田横。高帝听说了这件事，大为震惊，认为田横的宾客都很贤能，余下的五百人还在海岛上，便派使者去招抚他们。使者抵达海岛，这五百人听说田横已死，也都自杀了。
当初，楚地人季布是项羽手下的将领，曾多次窘困羞辱汉王。项羽灭亡后，高帝刘邦悬赏千金捉拿季布，下令说有敢收留窝藏季布的，罪连三族。季布于是剃去头发，用铁箍卡住脖子当奴隶，把自己卖给鲁地的大侠朱家。朱家心里明白这个人是季布，就将他买下安置在田庄中。朱家随即到洛阳去进见滕公夏侯婴，劝他道：“季布有什么罪啊！臣僚各为他的君主效力，这是常理。项羽的臣下难道可以全都杀掉吗？如今皇上刚刚取得天下，便借私人的怨恨去寻捕一个人，怎么这样来显露自己胸襟的狭窄呀！况且根据季布的贤能，朝廷悬赏寻捕他如此急迫，这是逼他不向北投奔胡人，便往南投靠百越部族啊！忌恨壮士而以此资助敌国，这是伍子胥所以要掘墓鞭打楚平王尸体的缘由呀。您为什么不从容地向皇上说说这些道理呢？”滕公于是就待有机会时，按照朱家的意思向高帝进言，高帝便赦免了季布，并召见他，授任他为郎中。朱家从此也就不再见季布。
季布的舅父丁公，也是项羽手下的将领，曾经在彭城西面追困过高帝刘邦。短兵相接，高帝感觉事态危急，便回头对丁公说：“两个好汉难道要相互为难困斗吗！”丁公于是领兵撤还。等到项羽灭亡，丁公来谒见高帝。高帝随即把丁公拉到军营中示众，说道：“丁公身为项王的臣子却不忠诚，是使项王失掉天下的人啊！”就把他杀了，并说：“让后世为人臣子的人不要效法丁公！”
臣司马光曰：汉高祖刘邦从丰、沛起事以来，网罗强横有势力的人，招纳逃亡反叛的人，也已经是相当多的了。待到登上帝位，唯独丁公因为不忠诚而遭受杀戮，这是为什么啊？是由于进取与守成，形势不同的缘故呀。当群雄并起争相取胜的时候，百姓没有确定的君主，谁来投奔就接受谁，本来就该如此。待到贵为天子，四海之内无不臣服时，如果不明确礼义以显示给人，致使身为臣子的人，人人怀有二心以图求取厚利，那么国家还能长治久安吗！因此汉高祖据大义作出决断，使天下的人都清楚地知道，身为臣子却不忠诚的人没有自己可以藏身的地方，怀揣个人目的布施恩惠给人的人，尽管他甚至于救过自己的命，依照礼义仍不予宽容。似此杀一人而使千万人畏惧，考虑事情难道不是既深刻又远广吗！汉高帝的子孙享有上天赐予的禄位四百多年，应当的啊！
故齐国人娄敬去防守陇西，经过洛阳，解下绑在车前牵引的横木，穿着羊皮袄，通过齐人虞将军求见高帝刘邦。虞将军想要给他穿华丽鲜亮的衣服，娄敬说：“我若穿的是丝绸，就身着丝绸去谒见；若穿的是粗毛麻布，就身着粗毛麻布去谒见，终究不敢冒昧地更换衣服。”这时虞将军便进去向高帝报告。高帝即召见娄敬，并询问他。娄敬说：“陛下定都洛阳，难道是想与周王朝一比隆盛威势吗？”高帝道：“是啊。”娄敬说：“陛下夺取天下的途径与周朝不同。周朝的祖先，从后稷被唐尧封在邰地起，积累德政善行十多代，以至于到太王、王季、文王、武王时期，诸侯自行归附，终于灭掉殷商作了天子。到了周成王登位，周公辅佐他，才营建洛邑，因为认为这里是天下的中心，各地诸侯前往交纳土贡和赋税，所走的道路里程相等。君主有德行就容易靠此统治天下，没有德行就容易由此而亡国。所以周王朝强盛的时候，天下和睦，诸侯、四方外族没有不臣服，奉上他们的贡赋的。待到周王朝衰弱时，天下没有谁前来朝贡，周王朝也已无法驾驭制约了。这不仅是由于它的德行微薄，而且是由于形势衰弱了的缘故。如今陛下从丰、沛起兵抗秦，席卷蜀郡、汉中郡，平定秦地雍、塞、翟三国，与项羽在荥阳、成皋之间作战，经过大战七十次，小战四十次，使天下百姓肝脑涂地惨遭杀戮，老老少少的尸骨暴露在荒野之中，数都数不过来，哭泣的悲声还未断绝，伤残的人员还不能行走，就想与周成王康王时代的隆盛威势相比美，我私下里认为这是很不相称的。况且秦地依靠华山濒临黄河，四面都有险要关隘为屏障，如果突然有紧急情况发生，百万军队可以立即就调动停当。依靠秦地原有的基础，凭借那里富饶肥沃的土地，这即是所谓的天然府库的优势啊。陛下入函谷关在那里建都，崤山以东地区就算是乱了，秦国的旧地也仍然可以完整地据有。同别人争斗，不卡住他的咽喉，从后背拍击他，是不能大获全胜的。现在陛下如果能占据秦国的故地，这也即是扼住了天下的咽喉且又攻击它的后背了。”高帝询问群臣。群臣都是崤山以东地区的人，便抢着发言：“周朝统治了几百年，而秦朝经历两代就灭亡了。洛阳东有成皋，西有崤山、渑池，背靠黄河，面向伊、洛二河，它的坚固也是足可依赖的了。”高帝又问张良。张良说：“洛阳虽然有这样稳固的地势，但它的中心地区狭小，方圆不过几百里，田地贫瘠，四面受敌，因此这里不是用武之地。而关中地区东有崤山、函谷关，西有陇山、蜀地的岷山，沃野千里，南有巴、蜀的富饶资源，北有胡地草场畜牧的地利。倚仗三面险要的地形防守，只用东方一面来控制诸侯。倘若诸侯安定，即可通过黄河、渭河水路转运天下的粮食，西上供给京都；如若诸侯发生变故，也可顺流而下，足够用以转运物资。这就是所谓的坚固的城墙千里之长，富庶的天然府库之国啊。娄敬的建议是对的。”高帝当天就起驾动身向西进发，定都长安，并授任娄敬为郎中，崐称为奉春君，赐姓刘。
张良向来多病，随从高帝进入函谷关，就静居行气，不吃粮食，闭门不出，说道：“我家的人世代做韩国的宰相，及至韩国灭亡，我不吝惜万金资财，为韩国向强大的秦王朝报仇，使天下震动。如今凭借三寸之舌成为皇帝的军师，被封为万户侯，这已是一个平民所能享有的最高待遇了，对我来说足够啦。我只望抛开人间俗事，将追随仙人赤松子去云游罢了。”
臣司马光曰：大凡有生就有死，犹如黑夜过后是白天一样的必然。自古至今，原本就没有超越自然而独立存在的事物。按张良的明辨是非通晓事理而论，他是完全知道神仙不过是些虚幻奇异的东西罢了。但他却要随同赤松子远游，他的聪明智慧是可以知道的了。功勋和名位之间，正是为人臣子的人所难于长久立足之处。即如高帝刘邦所称道的，不过只三个才能出众的人罢了。但是淮阴侯韩信被诛除，相国萧何被拘禁到狱中，这不就是由于功名已达到巅峰却还不止步的缘故吗！所以张良借与神仙交游相推脱，遗弃人间凡事，视功名如同身外之物，把荣誉利禄抛在脑后，所谓“明哲保身”者，张良即是个榜样。
六月，壬辰（初三），高帝大赦天下。
秋季，七月，燕王臧荼反叛，高帝亲自率军征讨臧荼。
赵景王张耳、长沙王吴芮都去世了。
九月，高帝俘获了臧荼。壬子（二十六日），封太尉长安侯卢绾为燕王。卢绾家与高帝是同乡，卢绾又与高帝同一天出生，高帝宠幸卢绾，群臣没有敢埋怨的，因此就特立卢绾为王。
项羽过去的将领利几反叛，高帝又亲自带兵击败了他。
闰九月，高帝改修长乐宫。
项羽手下的将领钟离昧，向来跟楚王韩信友好。项羽死后，他就逃出来归附了韩信。汉王刘邦很怨恨钟离昧，听说他在楚国，就诏令楚王逮捕他。这时韩信刚到他的封国，巡视所辖县邑，出入都有成队军队护卫。
六年（庚子，公元前201年）
冬季，十月，有人上书告发楚王韩信谋反。高帝便征求将领们的意见，大家都说：“赶快发兵，把这小子活埋罢了！”高帝默然不语。接着又询问崐陈平，陈平道：“有人上书告韩信谋反，这事情韩信知道吗？”高帝说：“不知道。”陈平说：“陛下的精锐部队与楚王的相比谁更厉害呢？”高帝道：“超不过他的。”陈平说：“陛下的将领们，用兵之才有能比过韩信的吗？”高帝道：“没有赶得上他的。”陈平说：“现在军队不如楚国的精锐，将领又比不上韩信，却要举兵攻打他，这是促使他起兵反抗呀。我私下里为陛下感到危险！”高帝说：“那该怎么办呢？”陈平说：“古时候天子有时巡视诸侯镇守的地方，会见诸侯。陛下只管出来视察，假装巡游云梦，在陈地会见诸侯。而陈地在楚国的西部边界，韩信听说天子怀着友好会见诸侯的心意出游，必定是全国安稳无事，便会到郊外迎接谒见陛下。拜见时陛下就趁机捉拄他，这不过是一个力士即能办到的事罢了。”高帝认为说得不错，便派出使者去通告诸侯到陈地聚会，说：“我将南游云梦”。高帝随即起程南行。
楚王韩信闻听这个消息后，自己颇为疑心害怕，不知怎么办才好。这时有人劝韩信说：“杀了钟离昧去谒见皇上，皇上必定欢喜，如此就不会有什么祸患了。”韩信听从了他的建议。十二月，高帝在陈地会见诸侯，韩信提着钟离昧的头颅拜见高帝。高帝即命武士将韩信捆绑起来，装载到随皇帝车驾出行的副车上。韩信说：“果然如同人们所说：‘狡猾的兔子死了，奔跑的猎狗就遭煮杀；高飞的鸟儿没了，优良的弓箭就被收藏；敌对的国家攻破了，谋臣就要灭亡。’如今天下已经平定，我本来就应当被煮杀了！”高帝说：“有人告发你谋反。”随即用镣铐枷锁锁住韩信而归，接着大赦天下。
田肯前来向高帝祝贺说：“陛下拿住了韩信；又在关中建都。秦地是形势险要能够制胜的地方，以河为襟带山为屏障，地势便利，从这里向诸侯用兵，就好像在高屋脊上倾倒瓶中的水那样居高临下而势不可挡了。若说齐地，东有琅邪、即墨的富饶物产，南有泰山的峭峻坚固，西有浊河的险阻制约，北有渤海的渔盐利益，土地方圆二千里，拥有兵力百万，可以算作是东方的秦国了，因而不是陛下嫡亲的子弟，就没有可以去统治齐地的。”高帝说：“对啊！”随即便赏给田肯五百斤黄金。
高帝归还，到了洛阳，就赦免了韩信，封他为淮阴侯。韩信知道汉王刘邦害怕并厌恶他的才能，于是就多次声称有病，不参加朝见和随侍出行。平日在家总是闷闷不乐，为与绛侯周勃、将军灌婴这样的人处于同等地位感到羞耻。韩信曾去拜访将军樊哙。樊哙用跪拜的礼节送迎，口称臣子，说道：“大王竟肯光临我这里！”韩信出门后，讪笑着说：“我活着竟然要和樊哙等人为伍了！”
高帝曾与韩信谈闲，议论将领们能带多少兵。高帝问道：“像我这个样能率领多少兵呀？”韩信说：“陛下不过能带十万兵。”高帝说：“对您来说怎样呢？”韩信道：“我是越多越好啊。”高帝笑着说：“越多越好，为什么却被我捉住了呀？”韩信说：“陛下虽不能带兵却善于驾驭将领，这就是我所以被陛下逮住的原因了。何况陛下的才能，是人们所说的‘此为上天赐予的，而不是人力能够取得的’啊。”
甲申（初九），高帝开始用把表示凭证的符信剖分成两半，朝廷与功臣各执一半为证的办法来分封各功臣为彻侯。萧何封为侯，所享用的食邑户数最多。功臣们都说：“我们身披坚硬铠甲手持锐利兵器，多的身经百余战，少的也交锋了几十回合。如今萧何不曾有过汗马功劳，只是操持文墨发发议论，封赏却倒在我们之上，这是为什么啊？”高帝说：“你们知道打猎是怎么回事吗？打猎，追杀野兽兔子的是猎狗，而放开系狗绳指示野兽所在地方的是人。现在你们只不过是能捕捉到奔逃的野兽罢了，功劳就如猎狗一样；至于萧何，却是放开系狗绳指示猎取的目标，功劳和猎人相同啊。”群臣于是都不敢说三道四的了。张良身为谋臣，也没有什么战功，高帝让他自己选择齐地三万户作为封地。张良说：“当初，我在下邳起兵，与陛下在留地相会，这是上天把我授给陛下。此后陛下采用我的计策，幸好有时能获得成功。我希望封得留地就足够了，不敢承受三万户的封地。”高帝于是便封张良为留侯。封陈平为户牖侯。陈平推辞说：“我没有那么多功劳哇。”高帝道：“我采纳您的计谋，克敌制胜，这不是功劳又是什么呀？”陈平说：“如果没有魏无知的举荐，我哪里能够进见啊？”高帝道：“像您这样，可以说是不忘本了！”随即又赏赐了魏无知。
高帝由于天下刚刚平定，自己的儿子年幼，兄弟又少，便以秦王朝孤立而导致灭亡的教训为鉴戒，想要大肆分封同姓族人，借此镇抚天下。春季，正月，丙午（疑误），高帝把楚王韩信的封地分为两个王国，将淮河以东五十三个县封给堂兄将军刘贾做荆王，将薛郡、东海、彭城等地三十六个县封给弟弟文信君刘交为楚王。壬子（二十七日），把云中、雁门、代郡等地五十三个县封给哥哥宜信侯刘喜做代王，把胶东、胶西、临淄、济北、博阳、城阳郡等地七十三个县封给自己平民时与同居的妇人所生的儿子刘肥当齐王，百姓中能讲齐国话的人都分给了齐国。
高帝由于韩王信颇具雄才武略，所辖地区北面紧靠巩、洛阳，南面迫近宛、叶，东边有淮阳，都是天下可以驻扎重兵之处，令人放心不下的缘故，划出太原郡的三十一个县为韩国，调迁韩王信去管辖太原以北的新地区，防备抵御胡人，建都晋阳。韩王信上书说：“韩国北靠边界，匈奴人屡次进来骚扰，都城晋阳离边塞遥远，请求改把马邑作为国都。”高帝允准。
高帝已经封赏了大功臣二十多人，其余的人日夜争功，一时决定不下来，便没能给予封赏。高帝在洛阳南宫，从天桥上望见将领们往往三人一群两人一伙地同坐在沙地中谈论着什么。高帝说：“这是在说些什么呀？”留侯张良道：“陛下不知道吗？这是在图谋造反啊！”高帝说：“天下新近刚刚安定下来，为了什么缘故又要谋反呢？”留侯说：“陛下由平民百姓起家，依靠这班人夺取了天下。如今陛下做了天子，所封赏的都是自己亲近喜爱的老友，所诛杀的都是自己生平仇视怨恨的人。现在军吏们计算功劳，认为即使把天下的土地都划作封国也不够全部封赏的了，于是这帮人就害怕陛下对他们不能全部封赏，又恐怕因往常的过失而被猜疑以至于遭到诛杀，所以就相互聚集到一起图谋造反了。”高帝于是担忧地说：“这该怎么办呀？”留侯道：“皇上平素最憎恶、且群臣又都知道的人，是谁啊？”高帝说：“雍齿与我有旧怨，他曾经多次困辱我。我想杀掉他，但由于他功劳很多，所以不忍心下手。”留侯说：“那么现在就赶快先封赏雍齿，这样一来，群臣也就人人都对自己的能受封赏坚信不疑了。”高帝这时便置备酒宴，封雍齿为什方侯，并急速催促丞相、御史论定功劳进行封赏。群臣结束饮宴后，都欢喜异常，说道：“雍齿尚且封为侯，我们这些人也就没有什么可担优的啦！”
臣司马光曰：张良作为高帝的谋臣，被当做为心腹亲信，应该是知无不言，哪有已听说诸侯将要谋反，却一定要等到高帝眼见有人成双成对地议论，然后才述说这件事的道理啊！这是由于高帝刚刚得到天下，屡次依据自己的爱憎来诛杀封赏，有时候就会有损于公平，群臣因此往往怀有抱怨和感到自己有危险的心理。所以张良借着这件事进送忠言，以改变转移高帝的心思，使在上者无偏袒私情的过失，在下者无猜疑恐惧的念头，国家无忧患，利益延及后世。像张良这样，可以说是善于劝谏的了。
上归栎阳
夏季，五月，丙午（二十三日），高帝尊称父亲太公为太上皇。
当初，匈奴畏惧秦朝，迁徙到北方十多年。待到秦朝灭亡，匈奴又逐渐往南渡过黄河。
匈奴单于头曼有太子叫冒顿。后来，头曼续有所宠爱的阏氏，又生了个小儿子，头曼便想把他立为太子。这时东胡部族强大，西域的月氏部族也很强盛。头曼于是派冒顿到月氏去当人质。不久，头曼加紧攻击月氏，月氏就想杀掉冒顿。冒顿即偷盗月氏人的好马骑上，逃回了匈奴。头曼由此认为冒顿强壮勇武，就让他统率万名骑兵。
冒顿便制作出响箭，训练部下骑射练习，使他们习惯于听从自己的号令。下令说：“看到我的响箭射出后不一齐发射的人，斩首！”冒顿随即用响箭自射他的好马，接着又射他的爱妻，左右的人凡有不敢跟着发射的，都被斩杀了。最后冒顿又拿响箭射头曼单于的好马，左右的骑兵也都跟着放箭射单于的马。由此冒顿知道这些兵士可以使用了，便在随同头曼出猎时，用响箭射头曼，他的部众即跟着响箭同射单于。最终杀死了头曼，并把他的后母和弟弟以及大臣中不听从调遣的人全部诛杀。冒顿自立为单于。
东胡听说冒顿弑父自立，便派出使者去告诉冒顿说：“想要得到头曼在位时拥有的千里马。”冒顿询问群臣，群臣都说：“那是匈奴的一匹宝马，不能给人！”冒顿道：“怎么能与人家为友好邻国却还要吝惜区区一匹马呀！”随即把这匹马送给了东胡。过了不久，东胡又派使者来对冒顿说：“想要得到单于的一位阏氏。”冒顿再询问左右近侍，侍臣都愤怒地说：“东胡这般无礼，竟然索求阏氏！请发兵攻打它！”冒顿道：“和人家是邻国，怎么能舍不得一个女子呢！”就选取自己所宠爱的阏氏送给了东胡。东胡王于是越来越骄横放纵。东胡与匈奴之间，有被丢弃的土地无人居住，方圆一千多里，双方各居其一边，设立屯戍守望的哨所。东胡再次派使者对冒顿说：“这些无人居住的荒地，我想得到它。”冒顿依旧召问群臣，群臣中有的说：“这是块荒地，给他们也可以，不给也行。”冒顿这时却勃然大怒道：“土地是国家的根本，怎么能够给人呢！”即将那些说可以给予的臣子都杀了。冒顿接着一跃上马，下令说：“国中有晚出发的人，斩首！”随即领兵去袭击东胡。东胡起初非常轻视冒顿，不设防备，冒顿因此就灭掉了东胡。
冒顿获胜而归，又向西攻击赶跑了月氏，向南兼并了黄河以南的娄烦、白羊二王，随即侵掠燕、代地区，全部重新收复了当年被蒙恬夺走的匈奴旧地，崐并夺取了汉朝边关原河套以南诸要塞到朝那县、肤施县一带的大片土地。这个时候，汉军正与项羽相持，中原地区被战争拖累得疲惫不堪，因此冒顿得以强大起来，拥有操弓射箭的兵士三十多万，威势镇服各国。
秋季，匈奴兵在马邑将韩王信重重包围。韩王信多次派使者出使匈奴，谋求和解。汉朝发兵救援，但又猜疑韩王信频繁私派使者是对汉室怀有二心，就派人去指责韩王信。韩王信害怕被杀，便在九月，举马邑城投降了匈奴。匈奴冒顿随即乘势领兵向南越过句注山，进攻太原，抵达晋阳。
高帝全部除去秦朝烦琐的礼仪，力求礼仪规则简单易行，这时群臣们饮酒争功，喝得酩酊大醉，有的人就胡喊狂呼，拔剑乱砍殿柱，高帝渐渐对这种现象产生了反感。叔孙通于是劝高帝说：“那班儒生，很难和他们一道攻打天下，但可以与他们一起保守成业坐天下。我愿意去征召鲁地的众儒生，来同我的弟子一块儿制定臣子朝见君主的礼仪规则。”高帝说：“该不会挺烦难的吧？”叔孙通道：“五帝的乐制不一样，三王的礼制不相同。礼制，是根据时代、人情的变化对人们的言行所确定的节制规范。我想稍微采用一些古代礼制，与秦朝的仪法搀糅到一起制定出来。”高帝说：“可以试着做做，但要使这礼仪容易被人们了解，估计我所能做得到的，据此去制定它。”
于是，叔孙通就奉命作为使者，去征召了鲁地的儒生三十多人。鲁地有两个儒生不肯前往，说道：“您所事奉的将近有十个君主了，都是依靠当面阿谀逢迎来赢得亲近、尊贵。如今天下刚刚平定，死亡的人尚未安葬，伤残的人还不能行动，又想要制礼作乐。而礼乐的产生，是积累德政上百年之后才能制作兴起的。我们不能忍心去做您所要做的事情。您去吧，不要玷污了我们！”叔孙通笑着说：“你们真是浅陋迂腐的儒生啊，不懂得时势的发展变化！”随即偕同他所征召的三十人西行入关，又邀请高帝身边有学术修养的近臣和自己的弟子，共一百多人，用绳索拦出演习场所，插立茅草表示出尊卑位次，在野外演习礼仪。经过一个多月后，叔孙通告诉高帝说：“可以试看了。”高帝于是就让他们举行礼仪演练，看完演练后说道：“我能够做这些。”就命令群臣们进行练习。
七年（辛丑，公元前200年）
冬季，十月，长乐宫落成，诸侯、群臣都前来参加朝贺典礼。仪式是在天亮之前举行，谒者主持典礼，按次序将所有人员引导入大殿门，排列在东、西两方，侍卫官员有的在殿下台阶两旁站立，有的排列在廷中，都持握兵器，竖立旗帜。这时皇帝乘坐辇车出房，众官员举旗传呼警戒，引导诸侯王以下至六百石级的官员依次序朝拜皇帝，无不震恐肃敬。到典礼仪式完毕，又置备正式酒宴。众侍臣官员陪坐在殿上的，都俯伏垂首，按官位的高低次序起身给崐皇上敬酒祝福。斟酒连敬九次，谒者宣告“结束宴饮”。御史执行礼仪规则，凡遇不遵照仪式规则举手投足的人就将他领出去。由此从朝贺典礼和酒宴开始直到结束，没有出现敢大声喧哗、不合礼节的人。这时高帝便说：“我今天才知道身为皇帝的尊贵啊！”便授任叔孙通为太常，常赐黄金五百斤。
当初，秦王朝统一了天下，收集六国的全部礼仪，选择出其中尊崇君主、卑抑臣下的规则保留下来。待到叔孙通制定礼仪规则，稍微作了一些增减，大体上都是沿袭秦朝的旧制，从天子称号以下到大小官吏及宫室、官名，更改变动不多。记载此礼仪规章的文本，后来和律、令收录在一起，收藏在司法机关。由于法家对此又不再传授，所以百姓臣僚也就没有谈论它的了。
臣司马光曰：礼的功能太大了！把它用到个人身上，动与静就有了规范，所有的行为就会完备无缺；把它用到家事上，内与外就井然有别，九族之间就会和睦融洽；把它用到乡里，长幼之间就有了伦理，风俗教化就会美好清明；把它用到封国，君主与臣子就尊卑有序，政令统治就会成功稳定；把它用到天下，诸侯就归顺服从，法制纪律就会整肃严正。难道仅仅只是把它用在宴会仪式之上、门户庭院之间维持秩序的吗？！就高祖刘邦的明智通达说来，他可以聆听陆贾关于以文治巩固政权的进言而称赞极好，目睹叔孙通所定尊崇君主的礼仪而发声慨叹，但是他所以终究不能与夏、商、周三代圣明君王并列，就错在他不肯学习啊。在那个时候，如果能得到大儒来辅佐他，与大儒一道用礼制来治理天下，他的功勋业绩又怎么会在这一步便止住了呢！可惜啊，叔孙通的器度太小了！他只不过是窃取礼制中糠般微末无用的东西，借以依附时世、迎合风俗、求取宠幸罢了，这样便使先代君王所建立的礼制沦没而不振兴，以至于到了今天这个地步，难道不令人沉痛之极吗！因此扬雄对此指责说：“从前鲁地有大儒，史书中没有记载他们的名字。有人问：‘为什么说他们是大儒呀？’回答道：‘叔孙通打算制定君臣的礼仪，便到鲁地去征召儒生，请不来的有两个，堪称大儒。’有人问道：‘既然如此，那么孔子应聘的足迹遍及诸侯国也是不对的了？’回答道：‘孔子周游列国，是为了要能按照自己的意图行事。倘若放弃自己的立场来顺从迁就他人，那么即便是确定出了规矩、准绳，又怎么能够拿来应用呀！’”精彩啊，扬雄的评论！大儒，是不肯破坏自己原有的规矩、准绳去追求一时的功利的！
高帝亲自领兵出征攻打韩王信，在铜县大败韩王信的军队，斩杀了他的部将王喜。韩王信逃往匈奴，他手下的将领白土县人曼丘臣、王黄等拥立赵王的后代赵利为王，重新收拢韩王信的散兵败卒，与韩王信及匈奴一起合谋攻击汉军。匈奴派左、右贤王统率一万多名骑兵，同王黄等驻扎在广武以南，到晋阳作战，汉军攻打他们，匈奴兵立即败逃，随后又聚集起来，汉军乘胜追击他们。这时恰好碰上天气酷寒，天下大雪，汉军士兵冻掉了手指的占十分之二三。
高帝驻居晋阳，听说冒顿单于驻居在代谷，便想要去攻打他，就派人去侦察匈奴。这时冒顿把他的精壮士兵、肥壮牛马都藏了起来，只让人看见老弱残兵和瘦小的牲畜。汉军派去的使者相继回来的有十批，都报告说匈奴可以攻打。高帝于是又派刘敬出使匈奴，尚未返回，汉军就全部出动兵力三十二万向北追击匈奴，越过了句注山。刘敬回来后报告说：“两国相攻，这本该炫耀显示自己的优势。但现在我到匈奴方面去，只看见瘦弱的牲畜和老弱的士兵，这必定是想要显露自己虚弱不堪，而埋伏奇兵以争取胜利。我认为匈奴不能攻打。”这时候，汉军业已出动，高帝大为恼火，骂刘敬说：“你这个齐国的混蛋伙，不过是靠着耍嘴皮子得到了一官半职，现在竟又来胡言乱语阻挠我的军队前进！”用刑具把刘敬拘禁到广武。
高帝先期抵达平城，军队尚未全部到来。冒顿便发出精兵四十万骑，把高帝围困在白登山达七天之久。汉军这时内外无法呼应救援，高帝于是就采用陈平的秘计，派使者暗中用重金贿赂冒顿的阏氏。阏氏随即便对冒顿说：“两个君主不应彼此困窘迫害。如今即使夺得了汉朝的土地，单于您也终究不能居住在那里。况且汉朝的君主也有神灵保护，望您明察！”冒顿与王黄、赵利约定好时间会师，但王黄、赵利的军队却迟迟不来，由此就怀疑他们与汉军有什么谋划，这才解开包围圈的一角。正好遇到天降大雾，汉军便派人在白登山与平城之间往来走动，匈奴人毫无察觉。陈平这时请求高帝命令士兵们用强弩搭上两支箭，箭朝外御敌，从解围的一角直冲出去。高帝脱出包围后，想要策马疾奔，太仆滕公夏侯婴却坚持慢慢地行走。到了平城时，汉的大队人马也赶到了，匈奴的骑兵便解围而去。汉军于是也收兵返回，命樊哙留下来平定代地。
高帝回到广武，赦免了刘敬，说道：“我不采用您的意见，因此被围困在平城。我已经把先前十多批使者都杀掉了！”接着就封给刘敬二千民户，爵位为关内侯，称作建信侯。高帝回师向南经过曲逆县，说道：“好壮观的县啊！我走遍天下，只见过洛阳和这里罢了。”就改封陈平为曲逆侯，享用全县民户的赋税收入。陈平跟随高帝南征北战，共六次进献妙计，每次都增加了封邑。
十二月，高帝返回长安，途经赵国。赵王张敖对高帝行作为女婿的礼节，十分谦卑，高帝却叉开两腿坐着，态度轻慢地责骂张敖。赵国相国贯高、赵午等人都怒火中烧，说道：“我们的大王，真是个懦弱的王啊！”随即劝赵王说：“天下豪强并起，贤能的人先称王。现在您侍奉皇帝非常恭谨，而皇帝却如此无礼，请让我们替您把他杀了！”张敖咬破自己的手指流出血来，说道：“你们怎么说这种大错特错的话呀！先父亡国后，依赖皇帝才得以复国，德崐泽能流传给子孙，一丝一毫都是皇帝的力量啊。望你们不要再这么说了！”贯高、赵午等人都相互说道：“这是我们的不是了。我们的大王是忠厚的长者，不会背弃恩德。况且我们的原则是不受人侮辱，而今皇帝侮辱了我王，所以想要杀掉他，又何必连累我王呢！事情干成了，则功归我王，事情失败了，则我们独自承担罪责罢了。”
匈奴攻打代国。代王刘喜弃国，自己逃归洛阳。高帝免了他的罪，改封他为阳侯。辛卯（疑误），封皇子刘如意为王。
春季，二月，高帝抵达长安。萧何这时正主持营建未央宫，高帝见到未央宫如此壮丽，十分愤怒，对萧何说：“天下纷乱，连年受战事劳苦，如今成败尚未可知，为什么要把宫室修筑得过分豪华呢！”萧何说：“正是因为天下尚未安定，所以才可趁势营造宫室啊。何况天子以四海为家，宫殿不壮丽就不足以加重威严，而且也不能让后世宫室的建筑规模超过它呀。”高帝这才高兴起来。
臣司马光曰：圣明的君主以仁义为美丽，以道德为威，还不曾听说过有依靠宫室规模来镇服天下的。天下尚未安定，理当克制自己、节俭用度，前去解救百姓的危难，现却反倒以营建宫室为先任，这怎么可以说是明白自己所应有的职责啊！从前大禹住在简陋的宫室而夏桀仍修建奢华的倾宫。开创业绩把王位传给后代的君王，尽管身体力行于节俭为子孙作出表率，而他们的末流依旧还是沦落入骄奢淫逸之中，何况向后代子孙显示奢侈呢！萧何竟谈什么“不要让后世宫室的建筑规模超过它”，这难道不是荒谬吗！到了汉武帝时，终于因滥建宫室而致天下疲惫衰败，这种局面未必不是由侯萧开的头吧！
高帝从栎阳迁都长安。
始设置宗正官，管理皇族宗室。
夏季，四月，高帝出行到洛阳去。', '[{"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42ca5914587d02f67dc7", "shortContent": "本篇选自笔记小说集《淞滨琐话》。是集十二卷，六十八篇。其中许多篇章借奇境幻域暴露社会黑暗，以狐鬼仙妖寄托真情实意。清朝末叶，吏治腐败，官吏贪鄙成风，公开卖官鬻爵，巧取豪夺，社会异常黑暗。本篇《因循岛》所描写的社会情景正是清朝后期社会状况的缩影。\n作者以项某的奇特经历为线索，以项某的耳闻目睹揭示了因循岛官吏如豺狼恶虎般搜刮民脂民膏，大小官吏沆瀣一气，贿赂成风，人民苦不堪言的黑暗现实。作品将因循岛上几...", "authors": ["曹炳建", "刘", "蕾"], "pressName": "上海辞书出版社"}]', '', 'indent', 1572788703, '5dbe695017b54d006c873f15', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643603, '高帝求贤诏', NULL, 2, 3, 0, 1, '刘邦', NULL, 10275, '57b8f77f128fe10054c94aab', '汉', 'wen', '文', '', '', '盖闻王者莫高于周文，伯者莫高于齐桓，皆待贤人而成名。今天下贤者智能，岂特古之人乎？患在人主不交故也，士奚由进！今吾以天之灵、贤士大夫定有天下，以为一家，欲其长久，世世奉宗庙亡绝也。贤人已与我共平之矣，而不与吾共安利之，可乎？贤士大夫有肯从我游者，吾能尊显之。布告天下，使明知朕意。御史大夫昌下相国，相国酂侯下诸侯王，御史中执法下郡守，其有意称明德者，必身劝，为之驾，遣诣相国府，署行、义、年。有而弗言，觉，免。年老癃病，勿遣。', '', '', '', NULL, '', 'indent', 1576746740, '5dcff575844bb400751bcaa7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643614, '越调 · 天净沙 · 江上', NULL, NULL, 155, 1, 0, '张可久', NULL, 10298, '57b9aeef79bc4400639bd1fc', '元', 'qu', '曲', 'https://baike.baidu.com/item/%E5%A4%A9%E5%87%80%E6%B2%99%C2%B7%E6%B1%9F%E4%B8%8A/8481969', '', '嗈嗈落雁平沙，依依孤鹜残霞，隔水疏林几家。小舟如画，渔歌唱入芦花。', '这是一首写景之作。作者以凝炼的笔墨，勾画出一幅暮秋江边落日图。前三句写落雁、孤鹜、残霞、人家等，纯是自然景物；末句“小舟如画，渔歌唱入芦花”，锦上添花，一小舟、一渔歌，使画面更觉生动，平添了一片从容闲适的情趣。', '嗈嗈（yōng）：雁叫声。平沙：水边平地。
依依：轻柔的样子，描述野鸭轻飞的样子。鹜（wù）：野鸭子。此句化用王勃《滕王阁序》“落霞与孤鹜齐飞”的名句。', '一群鸣叫的大雁正悠悠地要落在水边的平地上，在落日晚霞中一只野鸭子正轻柔飞翔，河的对岸稀稀疏疏地有几户茅草人家。水面上一叶扁舟，悠悠然然，随着渔人的歌声也缓缓地落入了那苍茫的一片芦苇丛中。', '[{"bookId": "60fc3bf423353c0ba53de400", "bookTitle": "元曲鉴赏辞典（新一版）", "articleId": "610ec29c03572034f65a8614", "shortContent": "这首小令是一首即景抒情的小诗。它描写的是一幅渔翁自得图。但诗人并没有直接描写渔翁的外表和内心，只是用简洁的语言勾出了一幅深秋傍晚江上所能看到的美丽图景。从中寄寓作者与世俗隔绝、在大自然中悠然自得的感受。\n开头三句描写深秋江上傍晚景色。首句“嗈嗈（雁鸣声）落雁平沙”，是说大雁边叫边落在江边平坦的沙滩上。次句“依依孤鹜残霞”，从唐代王勃《滕王阁序》“落霞与孤鹜齐飞”一句化出，而以“依依”写鹜（野鸭子）...", "authors": ["萧善因"], "pressName": "上海辞书出版社"}, {"bookId": "62de2d8a3bba5677642ac2d1", "bookTitle": "元曲三百首", "articleId": "630593d3251899613caec96f", "shortContent": "这首小令是一首即景抒情的小诗。它描写的是一幅渔翁自得图。但诗人并没有直接描写渔翁的外表和内心，只是用简洁的语言勾出了一幅深秋傍晚江上所能看到的美丽图景。从中寄寓作者与世俗隔绝、在大自然中悠然自得的感受。\n\n开头三句描写深秋江上傍晚景色。首句“嗈嗈（雁鸣声）落雁平沙”，是说大雁边叫边落在江边平坦的沙滩上。次句“依依孤鹜残霞”，从唐代王勃《滕王阁序》“落霞与孤鹜齐飞”一句化出，而以“依依”写鹜（野鸭）...", "authors": ["萧善因"], "pressName": "上海辞书出版社"}, {"bookId": "62777f94f716b7243c7b102b", "bookTitle": "元曲三百首鉴赏辞典 ", "articleId": "63126f05e6f69b71e93f6135", "shortContent": "此曲是对友人鲁卿隐居山中的礼赞，亦是自己一片向往之情的真实流露。\n开篇三句“青苔古木萧萧，苍云秋水迢迢。红叶山斋小小”，充分展现了作者对色调运用的才华。作者采用反差强烈的色调进行描绘，互为反衬，又让读者交错地使用视觉和听觉，大大增强了对景色的主体感受。“萧萧”即风吹树木摇动的声音，如“无边落木萧萧下”（杜甫《登高》）。“迢迢”即遥远漫长的样子，如“青山隐隐水迢迢”（杜牧《寄扬州韩绰判官》）。青苔墨...", "authors": ["郭洋洋"], "pressName": "崇文书局"}]', '', 'indent', 1681031380, '5dd64f42844bb40075503665', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643619, '郑伯克段于鄢', NULL, 125, 300, 1, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '初，郑武公娶于申，曰武姜。生庄公及共叔段。庄公寤生，惊姜氏，故名曰“寤生”，遂恶之。爱共叔段，欲立之，亟请于武公，公弗许。及庄公即位，为之请制。公曰：“制，岩邑也，虢叔死焉，佗邑唯命。”请京，使居之，谓之“京城大叔”。
祭仲曰：“都城过百雉，国之害也。先王之制：大都，不过参国之一；中，五之一；小，九之一。今京不度，非制也，君将不堪。”公曰：“姜氏欲之，焉辟害？”对曰：“姜氏何厌之有？不如早为之所，无使滋蔓。蔓，难图也。蔓草犹不可除，况君之宠弟乎？”公曰：“多行不义，必自毙，子姑待之。”
既而大叔命西鄙、北鄙贰于己。公子吕曰：“国不堪贰，君将若之何？欲与大叔，臣请事之；若弗与，则请除之，无生民心。”公曰：“无庸，将自及。”大叔又收贰以为己邑，至于廪延。子封曰：“可矣。厚将得众。”公曰：“不义不暱，厚将崩。”
大叔完聚，缮甲兵，具卒乘，将袭郑。夫人将启之。公闻其期，曰：“可矣！”命子封帅车二百乘以伐京。京叛大叔段。段入于鄢。公伐诸鄢。五月辛丑，大叔出奔共。
书曰：“郑伯克段于鄢。”段不弟，故不言弟；如二君，故曰克；称郑伯，讥失教也；谓之郑志。不言出奔，难之也。
遂置姜氏于城颍，而誓之曰：“不及黄泉，无相见也。”既而悔之。
颍考叔为颍谷封人，闻之，有献于公。公赐之食。食舍肉。公问之，对曰：“小人有母，皆尝小人之食矣，未尝君之羹。请以遗之。”公曰：“尔有母遗，繄我独无！”颍考叔曰：“敢问何谓也？”公语之故，且告之悔。对曰：“君何患焉？若阙地及泉，隧而相见，其谁曰不然？”公从之。公入而赋：“大隧之中，其乐也融融！”姜出而赋：“大隧之外，其乐也洩洩！”遂为母子如初。
君子曰：“颍考叔，纯孝也。爱其母，施及庄公。《诗》曰：‘孝子不匮，永锡尔类。’其是之谓乎？”', '本文出自《左传·隐公元年》。春秋时期，周王室逐渐衰微，各诸侯国之间开始了互相兼并的战争，各国内部统治者之间争夺权势的斗争也加剧起来。隐公之年（公元前722年），郑国国君之弟共叔段，谋划夺取哥哥郑庄公的君位，庄公发现后，巧施心计，采取欲擒故纵的手段，诱使共叔段得寸进尺，愈加骄横，然后在鄢地打败了共叔段，使他“出奔”。', '初：当初，这是回述往事时的说法。
郑武公：名掘突，郑桓公的儿子，郑国第二代君主。
娶于申：从申国娶妻。申，春秋时国名，姜姓，河南省南阳市北。
曰武姜：叫武姜。武姜，郑武公之妻，“姜”是她娘家的姓，“武”是她丈夫武公的谥号。
共（gōng）叔段：郑庄公的弟弟，名段。他在兄弟之中年岁小，因此称“叔段”。
寤（wù）生：难产的一种，胎儿的脚先生出来。寤，通“啎”，逆，倒着。
惊：使动用法，使姜氏惊。
遂恶（wù）之：因此厌恶他。遂，连词，因而。恶，厌恶。
爱：喜欢，喜爱。
亟（qì）请于武公：屡次向武公请求。亟，屡次。于，介词，向。
公弗许：武公不答应她。弗，不。
及庄公即位：到了庄公做国君的时候。及，介词，到。即位，君主登上君位。
制：地名，即虎牢，河南省荥（xíng）阳县西北。
岩邑：险要的城镇。岩，险要。邑，人所聚居的地方。
虢（guó）叔死焉：东虢国的国君死在那里。虢，指东虢，古国名，为郑国所灭。焉，介词兼指示代词相当于“于是”“于此”。
佗邑唯命：别的地方，听从您的吩咐。佗，同“他”，指示代词，别的，另外的。唯命，只听从您的命令。
京：地名，河南省荥阳县东南。
谓之京城大（tài）叔：京地百姓称共叔段为京城太叔。大，同“太”。王力、朱骏声作古今字。《说文》段注：“太从大声，后世凡言大，而以为形容未尽则作太，如大宰，俗作太宰，大子，俗作太子，周大王俗作太王是也。
祭（zhài）仲：郑国的大夫。祭：特殊读音。
都城过百雉（zhì）：都邑的城墙超过了300丈。都：《左传·庄公二十八年》“凡邑有宗庙先君之主曰都”。指次于国都而高于一般邑等级的城市。雉：古代城墙长一丈，宽一丈，高一丈为一堵，三堵为一雉，即长三丈。
国之害也：国家的祸害。
先王：前代君王。郭锡良《古代汉语讲授纲要》注为周开国君主文、武王。
大都不过参（sān）国之一：大城市的城墙不超过国都城墙的三分之一，参，同“三”。
中五之一：中等城市城墙不超过国都城墙的五分之一。“五分国之一”的省略。
小九之一：小城市的城墙不超过国都城墙的九分之一。“九分国之一”的省略。
不度：不合法度。
非制也：不是先王定下的制度。
不堪：受不了，控制不住的意思。
焉辟害：哪里能逃避祸害。辟，“避”的古字。
何厌（厌）之有：有何厌。有什么满足。宾语前置何：疑问代词作宾语定语。之：代词，复指前置宾语。
为之所：给他安排个地方，双宾语，即重新安排。
无使滋蔓（zīmàn）：不要让他滋长蔓延，“无”通“毋”（wú）。
图：除掉。
犹：尚且。
况：何况。
多行不义，必自毙：多做不义的事，必定自己垮台。毙，本义倒下去、垮台。汉以后才有“死”义。
姑：姑且，暂且。
既而：固定词组，不久。
命西鄙北鄙（bǐ）贰于己：命令原属庄公的西部和北部的边境城邑同时也臣属于自己。鄙：边邑也，从邑，啚声，边境上的城邑。贰：两属。
公子吕：郑国大夫。
堪：承受。
若之何：固定结构，对它怎么办？之，指“大叔命西鄙北鄙贰于己”这件事。
欲与大（tài）叔：如果想把国家交给共叔段。与，给予。
臣请事之：那么我请求去事奉他。事，动词，事奉。
生民心：使动，使民生二心。
无庸：不用。“庸”、“用”通用，一般出现于否定式。
将自及：将自己赶上灾难，杜预注：“及之难也。及：本义追赶上。
收贰以为己：把两属的地方收为自己的领邑。贰，指原来贰属的西鄙北鄙。以为，“以之为”的省略。
廪（lǐn）延：地名，河南省延津县北。
厚将得众：势力雄厚，就能得到更多的百姓。众，指百姓。
不义，不暱（nì），厚将崩：共叔段对君不义，百姓就对他不亲，势力再雄厚，将要崩溃。暱：同昵（异体），亲近。
完聚：修治（城郭），聚集（百姓）。完，修葺（qì）。
缮甲兵：修整作战用的甲衣和兵器。缮，修理。甲，铠甲。兵，兵器。
具卒乘（shènɡ）：准备步兵和兵车。具，准备。卒，步兵。乘，四匹马拉的战车。
袭：偷袭。行军不用钟鼓。杜预注：“轻行掩其不备曰袭”。本是贬义，后逐渐转为中性词。
夫人将启之：武姜将要为共叔段作内应。夫人，指武姜。启之，给段开城门，即作内应。启，为动用法。
公闻其期：庄公听说了偷袭的日期。
帅车二百乘：率领二百辆战车。帅，率领。古代每辆战车配备甲士三人，步卒七十二人。二百乘，共甲士六百人，步卒一万四千四百人。
叛：背叛。
入：逃入。
公伐诸鄢：庄公攻打共叔段在鄢邑。诸：之于，合音词。
辛丑：干支纪日。天干：甲乙丙丁戊己庚辛壬癸。地支：子丑寅卯辰巳（sì）午未申酉戌（xū）亥。二者相配，用以纪日，汉以后亦用以纪年。即二十三日。
出奔共：出逃到共国（避难）。奔，逃亡。
不弟：不守为弟之道。与“父不父，子不子用法相同。”《春秋》记载道：“郑伯克段于鄢。”意思是说共叔段不遵守做弟弟的本分。
如二君，故曰克：兄弟俩如同两个国君一样争斗，所以用“克”字；克，战胜。
称郑伯，讥失教也：称庄公为“郑伯”，是讥讽他对弟弟失教。讥，讽剌。失教，庄公本有教弟之责而未教。
谓之郑志：赶走共叔段是出于郑庄公的本意。志，意愿。
不言出奔，难之也：不写共叔段自动出奔，是史官下笔有为难之处。
寘：“置”的通用字。放置，放逐。
誓之：为动，对她发誓。
黄泉：地下的泉水，喻墓穴，指死后。
悔之：为动，对这事后悔。
颍考叔：郑国大夫，执掌颍谷（今河南登封西）。
封人：管理边界的地方长官。封：聚土培植树木。古代国境以树（沟）为界，故为边界标志。
有献：有进献的东西。献作宾语，名词。
赐之食：赏给他吃的。双宾语。
食舍肉：吃的时候把肉放置一边不吃。舍，舍的古字。
尝：吃过。
羹：带汁的肉。《尔雅·释器》：“肉谓之羹。”
遗（wèi）之：赠送给她。
繄（yī）我独无：我却单单没有啊！繄：句首语气助词，不译。
敢问何谓也：冒昧地问问你说的是什么意思呢？敢：表敬副词，冒昧。
故：原故，原因和对姜氏的誓言。
悔：后悔的心情。
何患焉：您在这件事上忧虑什么呢？焉：于是。
阙：通“掘”，挖。
隧而相见：挖个地道，在那里见面。隧，隧道，这里用作动词，指挖隧道。
其谁曰不然：那谁能说不是这样（不是跟誓词相合）呢？其，语气助词，加强反问的语气。然，代词，代庄公对姜氏发的誓言。
赋：赋诗，孔颖达疏：“谓自作诗也。”
大隧之中，其乐也融融：走进隧道里，欢乐真无比。
大隧之外，其乐也洩洩（yì）：走出隧道外，心情多欢快。中、融：上古冬韵，今押韵。外，洩：上古月韵，今不押韵。
遂为母子如初：从此作为母亲和儿子象当初一样。
君子：道德高尚的人。
施及庄公：施，延及。延及庄公。
孝子不匮，永锡尔类：匮，尽。锡，通赐，给与。
其是之谓乎：其，表推测语气，之，结构助词，助词宾语前置。', '从前，郑武公在申国娶了一妻子，叫武姜，她生下庄公和共叔段。庄公出生时脚先出来，武姜受到惊吓，因此给他取名叫“寤生”，所以很厌恶他。武姜偏爱共叔段，想立共叔段为世子，多次向武公请求，武公都不答应。
到庄公即位的时候，武姜就替共叔段请求分封到制邑去。庄公说：“制邑是个险要的地方，从前虢叔就死在那里，若是封给其它城邑，我都可以照吩咐办。”武姜便请求封给太叔京邑，庄公答应了，让他住在那里，称他为京城太叔。大夫祭仲说：“分封的都城如果城墙超过三百方丈长，那就会成为国家的祸害。先王的制度规定，国内最大的城邑不能超过国都的三分之一，中等的不得超过它的五分之一，小的不能超过它的九分之一。京邑的城墙不合法度，非法制所许，恐怕对您有所不利。”庄公说：“姜氏想要这样，我怎能躲开这种祸害呢？”祭仲回答说：“姜氏哪有满足的时候！不如及早处置，别让祸根滋长蔓延，一滋长蔓延就难办了。蔓延开来的野草还不能铲除干净，何况是您受宠爱的弟弟呢？”庄公说：“多做不义的事情，必定会自己垮台，你姑且等着瞧吧。
过了不久，太叔段使原来属于郑国的西边和北边的边邑也背叛归为自己。公子吕说：“国家不能有两个国君，现在您打算怎么办？您如果打算把郑国交给太叔，那么我就去服待他；如果不给，那么就请除掉他，不要使百姓们产生疑虑。”庄公说：“不用除掉他，他自己将要遭到灾祸的。”太叔又把两属的边邑改为自己统辖的地方，一直扩展到廪延。公子吕说：“可以行动了！土地扩大了，他将得到老百姓的拥护。”庄公说：“对君主不义，对兄长不亲，土地虽然扩大了，他也会垮台的。”
太叔修治城廓，聚集百姓，修整盔甲武器，准备好兵马战车，将要偷袭郑国。武姜打算开城门作内应。庄公打听到共叔段偷袭的时候，说：“可以出击了！”命令子封率领车二百乘，去讨伐京邑。京邑的人民背叛共叔段，共叔段于是逃到鄢城。庄公又追到鄢城讨伐他。五月二十三日，太叔段逃到共国。
《春秋》记载道：“郑伯克段于鄢。”意思是说共叔段不遵守做弟弟的本分，所以不说他是庄公的弟弟；兄弟俩如同两个国君一样争斗，所以用“克”字；称庄公为“郑伯”，是讥讽他对弟弟失教；赶走共叔段是出于郑庄公的本意，不写共叔段自动出奔，是史官下笔有为难之处。
庄公就把武姜安置在城颍，并且发誓说：“不到黄泉（不到死后埋在地下），不再见面！”过了些时候，庄公又后悔了。有个叫颍考叔的，是颍谷管理疆界的官吏，听到这件事，就把贡品献给郑庄公。庄公赐给他饭食。颍考叔在吃饭的时候，把肉留着。庄公问他为什么这样。颍考叔答道：“小人有个老娘，我吃的东西她都尝过，只是从未尝过君王的肉羹，请让我带回去送给她吃。”庄公说：“你有个老娘可以孝敬，唉，唯独我就没有！”颍考叔说：“请问您这是什么意思？”庄公把原因告诉了他，还告诉他后悔的心情。颍考叔答道：“您有什么担心的！只要挖一条地道，挖出了泉水，从地道中相见，谁还说您违背了誓言呢？”庄公依了他的话。庄公走进地道去见武姜，赋诗道：“大隧之中相见啊，多么和乐相得啊！”武姜走出地道，赋诗道：“大隧之外相见啊，多么舒畅快乐啊！”从此，他们恢复了从前的母子关系。
君子说：“颍考叔是位真正的孝子，他不仅孝顺自己的母亲，而且把这种孝心推广到郑伯身上。《诗经·大雅·既醉》篇说：‘孝子不断地推行孝道，永远能感化你的同类。’大概就是对颍考叔这类纯孝而说的吧？”', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1ce2cee9a0c24edae20", "shortContent": "公元前722年，在郑国统治者内部发生了一件骨肉相残的事件，这就是《春秋》上所谓的“郑伯克段于鄢”。《公羊》、《穀梁》都提到这件事，发表了一些议论。但从事件的叙述、人物的刻画方面来说，《左传》的文字写得最具体精彩，历来脍炙人口。\n姜氏厌恶其子郑庄公，始于郑庄公出生时的难产。可是她对于共叔段，却又非常溺爱。屡次请求郑武公废长立幼。虽遭到武公的拒绝，但姜氏并不就此罢休，这就充分说明了这个女人不仅愚蠢而且...", "authors": ["宋", "廓"], "pressName": "上海辞书出版社"}]', '', 'indent', 1574691405, '5ddb71c8fc36ed0068a14858', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643627, '吴江垂虹亭作', NULL, 2, 330, 1, 1, '米芾', NULL, 27438, '582c66af67f35600632c242d', '宋', 'shi', '诗', '', '', '【其一】
断云一片洞庭帆，玉破鲈鱼金破柑。
好作新诗继桑苎，垂虹秋色满东南。
【其二】
泛泛五湖霜气清，漫漫不辨水天形。
何须织女支机石，且戏常娥称客星。', '这是北宋诗人米芾吟咏吴江垂虹桥的一首诗。它以富有画意的笔触形象地描绘了这座水波连天、长虹飞渡的古代名桥的宏伟景象。', '金破柑：一作“霜破柑”。', '白帆点缀于太湖，仿佛剪下了一片片飞云。肥美的鲈鱼，肉色胜过了美玉，鲜红的桔子，颜色亮过了金子。不妨作几首新诗，遥继隐士陆羽的幽情。眼前垂虹亭畔的秋色，已经浸透了东南山川。
广阔无边的湖面，充满了霜天的清气，有如轻漫飘渺的羽纱，让水天融合浑然一体。又何须，远涉河源，去取织女的支机石来？且趁着月色，悠游嬉戏作一回嫦娥的常客。', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea7162cee9a0c24ed47c5", "shortContent": "垂虹亭始建于宋仁宗庆历八年（1048），在太湖东侧的吴江（今属江苏）垂虹桥上，桥形环若半月，长若垂虹，甚为壮丽，宋代不少诗人、词人描写过。米芾此诗是以画家的心思、眼光、笔法来咏此亭。\n诗歌的末句点明，诗人要写的是“垂虹秋色”。亭临太湖，秋季的湖水最为澄澈，湖的周围地区在秋季能为人们提供大量的鲈鱼与柑橘，诗人选取了这最能代表太湖秋天特色的景物入诗。不过，他不是通过叙述把景物告诉给人，而是通过绘制画面...", "authors": ["顾之京"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646b260e30675327e1a41daa", "shortContent": "垂虹亭始建于宋仁宗庆历八年（1048），在太湖东侧的吴江（今属江苏）垂虹桥上，桥形环若半月，长若垂虹，甚为壮丽，宋代不少诗人、词人描写过。米芾此诗是以画家的心思、眼光、笔法来咏此亭。\n\n诗歌的末句点明，诗人要写的是“垂虹秋色”。亭临太湖，秋季的湖水最为澄澈，湖的周围地区在秋季能为人们提供大量的鲈鱼与柑橘，诗人选取了这最能代表太湖秋天特色的景物入诗。不过，他不是通过叙述把景物告诉给人，而是通过绘制画...", "authors": ["顾之京"], "pressName": "上海辞书出版社"}]', '', 'center', 1576363693, '5de29f38562071007685ec3b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643629, '周郑交质', NULL, 35, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '郑武公、庄公为平王卿士。王贰于虢，郑伯怨王。王曰：“无之。”故周郑交质。王子狐为质于郑，郑公子忽为质于周。
王崩，周人将畀虢公政。四月，郑祭足帅师取温之麦。秋，又取成周之禾。周郑交恶。
君子曰：“信不由中，质无益也。明恕而行，要之以礼，虽无有质，谁能间之？苟有明信，涧溪沼沚之毛，蘋蘩蕴藻之菜，筐筥錡釜之器，潢污行潦之水，可荐于鬼神，可羞于王公，而况君子结二国之信，行之以礼，又焉用质？《风》有《采蘩》、《采蘋》，《雅》有《行苇》、《泂酌》，昭忠信也。”', '本文出自《左传·隐公三年》。在自春秋起始的东周，从平王东迁立国，就天下大乱，礼崩乐坏。周王室为了防止郑庄公独揽朝政，就想分政给另一个姬姓国国君虢公。然而，郑庄公不买周平王的账，为了达成妥协，周平王和郑庄公，居然采用了交换质子这一手段。而这一手段并没有奏效。以上就是该文的背景。', '卿士：周朝执政官。
贰于虢（guó）：二心，这里有“偏重”的意思。此指平王想把政权一部分让虢执掌。虢，指西虢公，周王室卿士。
郑伯：诸侯国郑国的君主，这里是郑庄公。
交质：交换人质。
王子狐：即姬狐，是周平王的次子、姬泄父的弟弟，史称“王子狐”，在长兄“太子泄父”死后，被立为太子。
公子忽：郑庄公太子，后即位为昭公。
王崩：周平王去世。崩，君主时代称帝王死。
畀（bì）：交给。
祭（zhài）足：即祭仲，郑大（dà）夫。温，周朝小国，在今河南温县南。
成周：周地，今在河南洛阳市东。
中：同“衷”，内心。
明恕：互相体谅。
要（yāo）：约束。
间：离间。
明信：彼此了解，坦诚相待。
沼沚：沼，池塘。沚，水中小洲。
蘋（pín）：水生植物，即浮萍。蘩（fán），白蒿。蕴藻，一种聚生的藻类。菜，野菜。
筐筥（jǔ）：竹制容器，方形为筐，圆形为莒。锜（qí）釜，均为烹饪器，有足为錡，无足为釜。
潢（huáng）：积水池。污，积水。行（xínɡ）潦（lǎo），路上的积水。
荐：享祭，祭祀。
羞：同“馐”，进奉。
《采蘩》、《采苹》：均为《诗·召南》篇名，写妇女采集野菜以供祭祀。
《行苇》、《泂（jiǒng）酌》：均为《诗·大雅》篇名，前者写周祖先晏享先人仁德，歌颂忠厚。后者写汲取行潦之水供宴享。
昭：表明。', '郑武公、郑庄公是周平王的卿士。周平王分权给虢公，郑庄公怨恨周平王。周平王说：“没有的事（偏心于虢公）。”于是周王、郑国交换人质：周平王的儿子狐在郑国做人质，郑庄公的儿子忽在周王室做人质。
周平王死后，周王室准备让虢公掌政。四月，郑国的祭足帅军队收割了温邑的麦子。秋季，又收割了成周的稻谷。周和郑互相仇恨。
君子说：“信用不发自心中，盟约抵押也没用。开诚布公互相谅解地行事，用礼教约束，即使没有抵押，谁能离间他们呢？假如有真诚的信用，山涧溪流中的浮萍，蕨类水藻这样的菜，装在竹筐铁锅一类的器物里，用低洼处沟渠中的水，都可以供奉鬼神，献给王公为食，何况君子缔结两国的盟约，按礼去做，又哪里用得着人质啊？《国风》中有《采蘩》、《采苹》，《大雅》中有《行苇》、《泂酌》诗，都是昭示忠信的。”', NULL, '', 'indent', 1575281405, '5de472787796d90076beb508', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643630, '石碏谏宠州吁', NULL, 23, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '卫庄公娶于齐东宫得臣之妹，曰庄姜。美而无子，卫人所为赋《硕人》也。又娶于陈，曰厉妫。生孝伯，蚤死。其娣戴妫生桓公，庄姜以为己子。
公子州吁，嬖人之子也。有宠而好兵，公弗禁，庄姜恶之。
石碏谏曰：“臣闻爱子，教之以义方，弗纳于邪。骄奢淫佚，所自邪也。四者之来，宠禄过也。将立州吁，乃定之矣；若犹未也，阶之为祸。夫宠而不骄，骄而能降，降而不憾，憾而能眕者，鲜矣。且夫贱妨贵，少陵长，远间亲，新间旧，小加大，淫破义，所谓六逆也。君义，臣行，父慈，子孝，兄爱，弟敬，所谓六顺也。去顺效逆，所以速祸也。君人者，将祸是[通“事”]务去，而速之，无乃不可乎？”弗听。
其子厚与州吁游，禁之，不可。桓公立，乃老。', '本文出自《左传·隐公三年》。州吁是卫庄公的一个宠妾所生，卫庄公爱屋及乌，对他也格外宠爱，即使对他喜好军事这种十分犯忌的事，也不加禁止。卫国大夫石碏（què）看到了问题的严重性：于是向卫庄公进谏，劝庄公爱子应该用道义，不要让他走上邪路。但庄公听不进去，结果前719年即第三年，就发生了州吁弑桓公而自立的事件。多亏石碏用计，大义灭亲，借陈国国君之手把弑君乱国的州吁和自己的儿子——助纣为虐的石厚抓住，并派人把他们杀死。本文记述的就是前720年隐公三年，石碏劝谏卫庄公爱子应“教之以义方，弗纳于邪”的事。', '石碏（què）：卫国大夫。
卫：国名，姬姓，在今河南淇县一带。齐：国名，姜姓，在今山东北部、中部地区。东宫：太子的居所。
硕人：典出《诗经 · 卫风》中的一篇，乃歌颂庄姜美丽的诗篇。庄姜：卫庄公的夫人，“庄”是她丈夫的谥号，“姜”则是她娘家的姓，故称庄姜。
陈：国名，妫姓在今河南东部及安徽西部。
厉妫（guī）：“厉”和下文“戴妫”的“戴”均为谥号，“妫”是娘家的姓。
蚤：通”早“。
娣：妹。古时诸侯娶妻，妹可随姊同嫁。
桓公：名完，在位十六年，后为州吁所杀。
嬖（bì）人：出身低贱而受宠的人，这里指卫庄公的宠妾。
义方：为人行事的规范。
佚（yì）：这里指逸乐。
阶：阶梯，这里用作动词，指一步步引向。
眕（zhěn）：自安自重，忍耐而不轻举妄动。
鲜（xiǎn）：少见。
陵：欺侮。
去：抛弃。
速：招致。
是：通“事”
无乃：恐怕。
立：继承。
老：告老致仕。', '卫庄公娶了齐国太子得臣的妹妹，叫庄姜，容貌很漂亮，却没有儿子。卫国人做了一首名为《硕人》的诗就是描写她的美貌的。庄公又从陈国娶了一个妻子，叫厉妫，生了儿子孝伯，早死。跟她陪嫁来的妹妹戴妫，生了桓公，庄姜就把他作为自己的儿子。
公子州吁，是庄公爱妾生的儿子，卫庄公十分宠爱他，又喜欢军事，但庄公不禁止，庄姜很厌恶他。
石碏规劝庄公道：“我听说一个人爱自己的儿子，一定要以正确的礼法来教导约束他，这样才能使他不走上邪路。骄傲、奢侈、淫荡、逸乐，就是走向邪路的开端。这四个方面的产生，都是宠爱和赏赐太过的缘故。如果要立州吁做太子，就应该定下来；要是还没有，这样就会引导他造成祸害。受宠爱而不骄傲，骄傲了而能受压制，受了压制而不怨恨，有怨恨而不为非作歹的人，是很少有的呀。再说卑贱的妨害高贵的，年少的欺负年长的，疏远的离间亲近的，新的挑拨旧的，地位低的压着地位高的，淫乱的破坏有礼义的，这是人们常说的六种逆理的事。君主行事公正适宜，臣子服从命令，父亲慈爱儿子，儿子孝顺父亲，哥哥爱护弟弟，弟弟敬重哥哥，这是人们常说的六种顺礼的事。不做顺应礼义的事去做违背礼的事，就会招致祸害。做君主的应尽力除掉祸害，现在却反而招致祸害的到来，这恐怕是不可以的吧！”庄公不听。
石碏的儿子石厚和州吁交往，石碏禁止他，但是州吁不允，从而放弃。到了桓公即位，石碏于是告老还乡。', NULL, '', 'indent', 1575281822, '5de474145620710076945c6f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643631, '臧僖伯谏观鱼', NULL, 16, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '春，公将如棠观鱼者。臧僖伯谏曰：“凡物不足以讲大事，其材不足以备器用，则君不举焉。君将纳民于轨物者也。故讲事以度轨量，谓之‘轨’；取材以章物采，谓之‘物’。不轨不物，谓之乱政。乱政亟行，所以败也。故春蒐、夏苗、秋狝、冬狩，皆于农隙以讲事也。三年而治兵，入而振旅，归而饮至，以数军实。昭文章，明贵贱，辨等列，顺少长，习威仪也。鸟兽之肉不登于俎，皮革、齿牙、骨角、毛羽不登于器，则君不射，古之制也。若夫山林川泽之实，器用之资，皂隶之事，官司之守，非君所及也。”
公曰：“吾将略地焉。”遂往，陈鱼而观之。僖伯称疾不从。
书曰：“公矢鱼与棠。”非礼也，且言远地也。', '本文出自《左传·隐公五年》。这一年（前718年）的春天，鲁隐公要到棠地观看渔民怎样捕鱼。鲁国大夫臧僖伯从传统的为君之道出发，认为国君的根本责任是管好国家大事，而且任何举措都必须合乎“古制”和国君的行为规范，否则就会“乱政”，而屡屡“乱政”，国家就会败亡。正是出于这么一种认识，他从对国君和国家的责任感出发，进谏隐公，劝阻他到棠地观鱼。', '春：指鲁隐公五年（前718）春季。
公：指鲁隐公。公元前722年至公元前712年在位。按《春秋》和《左传》的编著体例，凡是鲁国国君都称公，后边《曹刿论战》等篇均如是。鲁国是姬姓国，其开国君主是周公旦之子伯禽，其地在今山东西南部。如：往。
如：往。
棠：也写作唐，鲁国邑名，在今山东鱼台县东。
鱼：通“渔”，动词，捕鱼。
臧僖伯：鲁孝公之子、鲁惠公之兄、鲁隐公之伯父，名彄（又作“驱”“弓区”）（kōu），字子臧，封于臧（今郯城县），伯为排行，僖是谥号。 丗本：孝公生僖伯彄，彄生哀伯达（臧哀伯或臧孙达），达生伯氏缾，缾生文仲辰（臧文仲），辰是臧僖伯曾孙。
讲：讲习，训练。
大事：指祭祀和军事活动等。
材：材料，原料。
器用：指祭祀所用的器具与军事物资。
举：指行动。
纳：纳入。
轨物：法度和准则。
度（duó）：计量。
量：轨则，法度。
章：通“彰”，彰明，发扬。
采：物之有华饰者又彩色也，五彩相间曰采。
亟：多次，屡次。
春蒐（sōu）：指春天打猎。蒐，搜寻，谓搜寻不产卵、未怀孕的禽兽。
夏苗：指夏天打猎，谓捕猎伤害庄稼的禽兽。
秋狝（xiǎn）：指秋天打猎。狝，杀，谓顺秋天肃杀之气，进行捕猎活动。
冬狩（shòu）：指冬天打猎。狩，围守，谓冬天各种禽兽都已长成，可以不加选择地加以围猎。按：“春蒐、夏苗、秋狝、冬狩”云云，说明我们的先民在狩猎活动中已有生态平衡意识，也同时说明大凡有组织的狩猎活动，都带有军事演习的性质，并不单单是为狩猎而狩猎。
治兵：指练兵、比武等军事演习活动。
振旅：整顿部队。
饮至：古代的一种礼仪活动。凡盟会、外交和重大军事行动结束以后，都要告于宗庙，并举行宴会予以庆贺。
军实：指军用车辆、器物和战斗中的俘获等。
昭：表明。文章：服饰、旌旗等的颜色花纹。
登：装入，陈列。
俎（zǔ）：古代举行祭祀活动时用以盛牛、羊等祭品的礼器。
射：激矢及物曰射。
山林：材木樵薪之类。
川泽：菱芡鱼龟之类。
资：材资也。
皂（zào）隶：本指奴隶，这里指做各种杂务的仆役。
略地：到外地巡视。
陈：陈设，张设也。
称疾：推说有病。（注意：古代分言“疾”和“病”，轻者为“疾”，重者为“病”。）
书：指《春秋》。
矢：通“施”，实施，陈设。这一句的意思是：隐公在棠陈列渔具。', '春天，隐公准备到棠地观看渔民捕鱼。臧僖伯进谏说：“凡是物品不能用到讲习祭祀、军事等大事上，或者所用材料不能制作礼器和兵器，那么，国君就不要亲自去接触它。国君是把民众引向社会规范和行为准则的人。所以，讲习大事以法度为准则进行衡量，叫做‘轨’，选取材料制作器物以显示它的文彩，叫做‘物’。事情不合乎轨、物，叫做乱政。屡屡乱政，这就是所以败亡的原因了。所以，春、夏、秋、冬四季的狩猎活动，都是在农闲时节进行，并（借这个机会）讲习军事。每三年演练一次，回国都要对军队进行休整。并要到宗庙进行祭告，宴饮庆贺，清点军用器物和猎获物。（在进行这些活动的时候，）要（使车马、服饰、旌旗等）文彩鲜艳，贵贱分明，等级井然，少长有序：这都是讲习大事的威仪啊！鸟兽的肉不能拿来放到祭祀用的器具里，皮革、牙齿、骨角和毛羽不能用来制作军事器物，这样的鸟兽，君主就不会去射它，这是自古以来的规矩啊！至于山林川泽的物产，一般器物的材料，这都是仆役们去忙活，有关官吏按职分去管理的事，而不是君主所应涉足的事。”
隐公说：“我准备到那里去巡视。”于是就去了（棠地），让渔民把各种渔具都摆出来捕鱼，他在那里观赏。僖伯推说有病没有随同前往。
《春秋》上说：“隐公在棠地陈设渔具。”（这是说他棠地观鱼这一行为）不合礼法啊，并且说他去的地方远离国都。', NULL, '', 'indent', 1575282102, '5de475347796d90076bed0f7', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643632, '郑庄公戒饬守臣', NULL, 13, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '秋七月，公会齐侯、郑伯伐许。庚辰，傅于许。颍考叔取郑伯之旗蝥弧以先登，子都自下射之，颠。瑕叔盈又以蝥弧登，周麾而呼曰：“君登矣！”郑师毕登。壬午，遂入许。许庄公奔卫。齐侯以许让公。公曰：“君谓许不共，故从君讨之。许既伏其罪矣。虽君有命，寡人弗敢与闻。”乃与郑人。
郑伯使许大夫百里奉许叔以居许东偏，曰：“天祸许国，鬼神实不逞于许君，而假手于我寡人，寡人唯是一二父兄不能共亿，其敢以许自为功乎？寡人有弟，不能和协，而使糊其口于四方，其况能久有许乎？吾子其奉许叔以抚柔此民也，吾将使获也佐吾子。若寡人得没于地，天其以礼悔祸于许，无宁兹许公复奉其社稷，唯我郑国之有请谒焉，如旧昏媾，其能降以相从也。无滋他族实逼处此，以与我郑国争此土也。吾子孙其覆亡之不暇，而况能禋祀许乎？寡人之使吾子处此，不惟许国之为，亦聊以固吾圉也。”乃使公孙获处许西偏，曰：“凡而器用财贿，无置于许。我死，乃亟去之！吾先君新邑于此，王室而既卑矣，周之子孙日失其序。夫许，大岳之胤也。天而既厌周德矣，吾其能与许争乎？”
君子谓郑庄公“于是乎有礼。礼，经国家，定社稷，序人民，利后嗣者也。许，无刑而伐之，服而舍之，度德而处之，量力而行之，相时而动，无累后人，可谓知礼矣。”', '本文出自《左传·隐公十一年》。', '公︰鲁隐公。齐侯︰齐僖公。郑伯︰郑庄公。
许︰国名，在今河南许昌县。
傅：同“附”，靠近。蝥弧︰旗名。
子都︰郑国大夫。子都与颍考叔有争车之怨，故射之以报怨。
瑕叔盈︰郑国大夫。
共︰同“供”。
百里︰许国大夫。
许叔︰许庄公之弟。
父兄：父老兄弟。指同姓臣子。共亿：相安无事。
吾子：二人谈话时对对方的敬称。
获︰指郑国大夫公孙获。
昏媾︰昏同“婚”，婚姻；结亲。
禋祀︰祭天神之礼。
圉︰边境。
亟：急切。
而︰代词，你；你的。
贿︰货财。金玉称货，布帛称贿。
乃︰汝；你。
序︰同“绪”，前人的功业。
大岳︰传说尧舜时的四方部落首领。
胤︰后嗣。
经︰治理。', '鲁隐公十一年秋天七月，鲁隐公会合齐侯、郑伯讨伐许国。初一这一天，三国的军队逼近许国城下。颍考叔举着郑国的蝥弧旗，首先登上了城墙，子都（郑大夫，公孙阏）从下面射他，颍考叔跌下来死了。瑕叔盈又举起蝥弧爬上城墙，挥舞旗帜并呼喊道：“我们国君登城啦！”郑国的军队全部登上城墙。初三这一天，便攻入许国。许庄公逃到卫国去了。齐侯要把许国让给鲁隐公。鲁隐公说：“您说许国不交纳贡物，又不履行诸侯的职责，所以跟随您讨伐它。现在许国已经受到应有的惩罚了，虽然您有命令，我也不敢参与这事的。”于是就把许国给了郑庄公。
郑庄公让许国大夫百里侍奉许庄公的弟弟许叔住在许国的东部边邑，对他说：“上天降祸给许国，鬼神也不满意许君，所以借我的手来惩罚他，我有少数的几个同姓臣子，尚且不能同心协力，哪里还敢拿打败许国作为自己的功劳呢？我有个弟弟（共叔段），还不能和睦相处，致使他到处流浪，在四方奔走寄食，又怎么能长久占有许国呢？你侍奉许叔安抚这里的百姓，我将派公孙获来帮助你。如果我能得到善终而长眠于地下，上天施恩，懊悔前日对许的降祸，难道许公就不能再来掌管他的国家？只是我们郑国请求时，希望相亲相近像老亲家一样，能屈尊降贵答应我们。
千万不要助长他族，使他族逼近、居住在这里，来和我郑国争夺这地方。如果那样，我的子孙连自己挽救郑国自己的危亡都无暇照顾，又怎能祭祀许国的山川呢？我之所以让你住在这里，不单是为许国着想，也借以巩固我们郑国的边防啊。”
于是又派公孙获驻扎在许国西部边境，对他说：“凡是你的器物钱财，不要放在许国。我死了，你就马上离开许国！先君是新近在这里建成都邑，眼看周王室的地位权力一天天衰微，周的子孙也一天天的失掉所继承的祖先功业。许国是太岳后代。上天既然厌弃周朝的气运了，我们是周的子孙，怎么能和许国相争呢？”
君子认为：“郑庄公在这件事上是符合礼制的。礼制，是可以治理国家，稳定政权，安抚百姓，并有利于后世子孙的。许国不守法度就去讨伐它，伏罪了就宽恕它，度量自己的德行去处理问题，估量自己的实力去行事，看清形势而后行动，不连累后人，可以说是知礼了。”', NULL, '', 'indent', 1575282656, '5de47757fc36ed006833c183', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643633, '臧哀伯谏纳郜鼎', NULL, 9, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '夏四月，取郜大鼎于宋，纳于大庙，非礼也。
臧哀伯谏曰：“君人者，将昭德塞违，以临照百官；犹惧或失之，故昭令德以示子孙。是以清庙茅屋，大路越，通括席，大羹不致，粢食不凿，昭其俭也；衮冕黻珽，带裳幅舄，衡紞纮綖，昭其度也；藻率鞞鞛，鞶厉游缨，昭其数也；火龙黼黻，昭其文也；五色比象，昭其物也；钖鸾和铃，昭其声也；三辰旂旗，昭其明也。夫德，俭而有度，登降有数。文物以纪之，声明以发之，以临照百官，百官于是乎戒惧，而不敢易纪律。今灭德立违，而置其赂器于大庙，以明示百官。百官象之，其又何诛焉？国家之败，由官邪也；官之失德，宠赂章也。郜鼎在庙，章孰甚焉？武王克商，迁九鼎于雒邑，义士犹或非之，而况将昭违乱之赂器于大庙。其若之何？”公不听。
周内史闻之，曰：“臧孙达其有后于鲁乎！君违，不忘谏之以德。”', '本文出自《左传·桓公二年》。前710年的春天，宋国太宰华父督杀死司马孔父嘉，并占有了孔父嘉“美而艳”的妻子。宋殇公为此很生气，华父督害怕，就干脆把殇公也杀了，另立宋庄公。华父督为了取得各诸侯国对此事的默认，先后对齐、陈、郑、鲁等国进行贿赂。鲁桓公接受了宋国送给的郜鼎，并把它安放在太庙里。鲁国大夫臧哀伯认为这样做“非礼”，会导致官员腐败，甚至导致国家败亡。于是对桓公进行劝谏。', '郜（ɡào）：国名，姬姓，开国国君是周文王的一个庶子，春秋时为宋国所灭，其故地在今山东成武县东南。鼎：古代的一种烹饪器物，又因常常用作旌功记绩的礼器，所以又作为传国重器，其形制一般为三足两耳。宋：国名，春秋时为十二诸侯之一，开国国君为殷纣王的庶兄微子，其地在今河南东部及山东、江苏和安徽三省之间。
大（tài）庙：即太庙，天子或诸侯国国君的祖庙。
临照：管理和监察。临，统管，治理。照，察看。
令德：美德。令，美好。
清庙：即祖庙，因其肃穆清静，故称。
大路：也作“大辂”，即大车，特指天子或诸侯国国君祭天时所乘的车子。越（yuè）席：用蒲草编织的席子。越，通“括”，结。
大（tài）羹：即太羹，也作“泰羹”，古代祭祀时所用的肉汁。不致：指不调五味，不加各种作料。
粢（zī）食：用黍稷加工品制作的饼食，祭祀用作供品。粢，黍稷，泛指谷类粮食。不凿：不舂，这里指不精细加工。
衮（ɡǔn）：古代帝王及公卿祭祀宗庙时所穿的礼服。冕（miǎn）：古代帝王、公卿、诸侯所戴的礼帽。黻（fú）：通“韨”，古代用做祭服的熟皮制蔽膝。珽（tǐnɡ）：古代君臣在朝廷上相见时所持的玉制朝板，即玉笏（hù）。
带：指束在腰间的革带，皮带。裳（chánɡ）：古代男女穿的裙式下衣。幅：古代自足至膝斜缠在小腿部的帛条或布条，犹如今天的绑腿。舄（xì）：双底鞋，着地的一层为木底，这里泛指鞋子。
衡：把冠冕稳定在发髻上的横簪。紞（dǎn）：古代垂在帽子两旁用以悬挂塞耳用的玉瑱（tián）的带子。纮（hónɡ）：古代冠冕系在颔下的带子。古人戴冠冕时，先用簪子别在发髻上，再用纮挽住，系在簪子的两端。綎（yán）：古代覆在冠冕上的一种长方形饰物，以木板为干（ɡàn），外包黑色布帛。
藻率（lǜ）：一种用来放玉的木垫儿，外包熟皮，并绘有水藻形图案。鞞（bǐnɡ）：刀剑套。鞛（běnɡ）：佩刀刀鞘的饰物。
鞶（pán）：绅带，又名“大带”，束衣用。厉：下垂的大带。或谓“鞶厉”：是一个词，指束腰革带与革带下垂的部分。游：古代旗帜上下垂的饰物。缨：套在马胸部的革带，即马鞅。数：礼数。
火龙黼（fǔ）黻：都是古代礼服上所绣的花纹，如火形者为“火”，如龙形者为“龙”，黑白色相间如斧形者为“黼”，黑青色相间如“亚”形者为“黻”。
五色：指青、赤、黄、白、黑五种颜色。比象：指比照天地万物所画出的各种图像。
钖（yánɡ）鸾和铃：都是系在车马和旗帜上的铃铛，系在马额头上的叫“钖”，系在马嚼子上的叫“鸾”，系在车前用作扶手的横木上的叫“和”，系在绘有龙形图案的旗帜竿头的叫“铃”。
三辰：指日、月、星。旂（qí）：旗面绘有龙形图案，竿头系有小铃铛的旗子。
登降：增减。登为增，降为减。有数：指有节度、节制。（注意此处的“数”字与上文“昭其数也”句的“数”字在词义上的区别。）
象：同“像”，法式，式样，这里是榜样的意思。
章：明显。与下文“章孰甚焉”句之“章”义同。
九鼎：相传为夏禹所铸，用以象征九州。夏、商、周三代都把它作为政权的象征，成为传国之宝。
雒（luò）邑：也作“洛邑”，东周都城所在，相传周武王克商后由周公姬旦营建。', '夏四月，鲁桓公从宋国取得原属郜国的传国大鼎，放进太庙，这是不符合礼仪的。
臧哀伯规劝桓公说：“作百姓君主的人，要发扬德行，堵塞违礼的行为，以便监察百官，就这样还怕有不足之处，还要显示各种美德以传示子孙。所以那清静肃穆的太庙用茅草做屋顶，祭祀天地的车子用草席做垫子，祭祀用的肉汁不用五味调和，黍稷、糕饼等祭品不用舂过的好米，这些是为了显示节俭。祭祀的礼服、礼冠，蔽膝、大圭，腰带、裙子、绑腿、靴子、冠上的横簪、冠旁的填绳、系冠的带子、冠顶的盖版，这些是为了显示等级上的差别。玉垫、刀饰、革带、带穗、旌旗上的飘带、马颈上的革带，这些是为了显示数量上的差别。礼服上火形、龙形、斧形、弓形等花纹，这些是为了显示纹彩上的差别。用五色绘出各种图象来装饰器物服饰，这是为了显示器物物色的差别。马铃、大小车铃、旗铃，是为了显示声音节奏，旌旗上画的日、月、星辰，是为了显示光明。所谓德行，就是节俭而有法度，事物的增减都有一定的数量，并用纹彩和颜色加以标志，用声音和光亮加以表现，以此来监察百官，百官这才警戒畏惧，而不敢违反法度。现在君王毁灭德行，树立违礼的坏榜样，把别国贿赂的宝器安放在太庙里，以此明白昭示百官。百官都来效法，君王又用什么去惩罚他们呢？国家的衰败，是由于官吏不走正道。官吏丧失德行，则是由于国君宠爱和贿赂风行的原故。郜鼎放在鲁国的太庙，还有比这更公开的贿赂吗？武王打败殷商，将九鼎搬到王城，义士尚有批评他的，更何况将标志违礼作乱的贿赂之器放在太庙，又该怎么样呢？”桓公不听。
周朝的内史听到这件事，说：“臧孙达的后代大概会在鲁国世代享受爵禄吧！国君违礼，他不忘用德行加以规劝。”', NULL, '', 'indent', 1575282994, '5de478af21b47e006c9d32a6', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643634, '季梁谏追楚师', NULL, 12, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '楚武王侵随，使薳章求成焉，军于瑕以待之。随人使少师董成。
斗伯比言于楚子曰：“吾不得志于汉东也，我则使然。我张吾三军而被吾甲兵，以武临之，彼则惧而协以谋我，故难间也。汉东之国，随为大。随张，必弃小国。小国离，楚之利也。少师侈，请羸师以张之。”熊率且比曰:“季梁在，何益？”斗伯比曰:“以为后图。少师得其君。”
王毁军而纳少师。少师归，请追楚师。随侯将许之。
季梁止之曰：“天方授楚。楚之羸，其诱我也，君何急焉？臣闻小之能敌大也，小道大淫。所谓道，忠于民而信于神也。上思利民，忠也；祝史正辞，信也。今民馁而君逞欲，祝史矫举以祭，臣不知其可也。”公曰：“吾牲牷肥腯，粢盛丰备，何则不信？”对曰：“夫民，神之主也。是以圣王先成民，而后致力于神。故奉牲以告曰‘博硕肥腯。’谓民力之普存也，谓其畜之硕大蕃滋也，谓其不疾瘯蠡也，谓其备腯咸有也。奉盛以告曰：‘洁粢丰盛。’谓其三时不害而民和年丰也。奉酒醴以告曰：‘嘉栗旨酒。’谓其上下皆有嘉德而无违心也。所谓馨香，无谗慝也。故务其三时，修其五教，亲其九族，以致其禋祀。于是乎民和而神降之福，故动则有成。今民各有心，而鬼神乏主，君虽独丰，其何福之有？君姑修政而亲兄弟之国，庶免于难。”
随侯惧而修政，楚不敢伐。', '本文出自《左传·桓公六年》。内容反映了春秋时代对于民和神的关系的一种新的进步主张：民是主体，神是附属。所以好的君主必须首先做好对民有利的事，然后再去致力于祭祀神祇一类的事，即“圣王先成民而后致力于神”。季梁先是忠民信神并提，然后深入论述应该以民为主，神为附。在谈到神的地方都是从民着眼，所以说服力很强，能使“随侯惧而修政”。', '楚：芈（mǐ）姓国。西周时立国于荆山一带。周成王封其首领熊绎以子男之田，为楚受封的开始。后来楚国自称王，与周处于对立地位。楚武王为楚国第十七代君。楚也称荆。随：姬姓。今湖北随县。
薳章：楚大夫。
瑕：随地。今湖北随县境。
少师：官名。董：主持。
斗伯比：楚大夫。楚子：指楚武王。因楚为子爵，故称楚子。
汉东：指汉水以东的小国。
我则使然：是我们自己造成的。
张：陈列。被：同“披”。
侈：骄傲自大。
羸：使…瘦弱。羸师：故意使军队装作衰弱。
熊率且比：楚大夫。
季梁：随国的贤臣。
授：付予。楚强盛，古人认为天意如此。
淫：淫乱，暴虐。
祝史：管理祭祀的官吏。正辞：如实说明，不欺假。
馁：饥饿。
矫：假。
牲牷：纯色而完整的牛、羊、猪。腯：肥壮。
粢盛：盛在祭器里供神用的谷物。黍、稷叫粢，装进器皿之后叫盛。
硕：大，高大。
瘯蠡：六畜所患皮肤病。
咸有：兼备而无所缺。
醴：甜酒。嘉：美好，善良。栗：敬。旨：美味。或说，栗是新收获的粮食。
谗：诬陷人的坏话。慝：邪恶。
五教：指父义、母慈、兄友、弟恭、子孝。
九族：上自高、曾、祖、父，下至子、孙、曾、玄，加上本身。另一说，父族四代，母族三代，妻族二代，合为九族。
禋祀：诚心祭祀。', '楚武王侵犯随国，派薳章去要求议和。军队扎在瑕地，等待谈判的结果。随国派少师来主持议和。
斗伯比对楚王说：“我们不能在汉水以东得志，全是我们自己造成的啊！我们扩大军队，增加装备，以武力威胁邻国。它们怕起来了，就协同对付我国，很难离间它们。汉水以东，要算随国最大。如果随国骄傲起来，必定抛弃那些小国。小国离散，咱们楚国就可从中得利了。少师这人，一向狂妄自大，请把我们的军队摆出个窝囊的样子，使他更加傲慢起来。”熊率且比说：“随国还有个季梁哩，这有什么作用？”斗伯比说：“以后会有用处的呀！少师很得国君的宠信啊。”
于是楚武王故意损毁军容，接待少师。少师回去，果然请求追击楚军。随侯将要答应他，季梁急忙阻止，说：“上天正在帮楚国，楚军的疲弱，恐怕是骗我们上当吧，君王何必急于出师呢？臣听说，小国所以能抗拒大国，是因为小国得道而大国淫暴。什么是道呢？就是忠于人民，取信于鬼神。国君经常考虑如何利民，就是忠。祝官史官老老实实向神灵祭告，就是信。现在人民在挨饿而君王纵情享乐，祝官史官却在祭神时虚报功德，臣不知道这样如何能抗拒大国！”随侯说：“我上供的牲畜毛色纯正，膘肥肉壮，祭器里的黍稷也很丰盛，怎么不能取信于鬼神呢？”季梁说：“人民才是鬼神的主人啊。圣明的君主总是先把人民的事情办好，再致力于祭祀鬼神。所以在进献牺牲时就祷告说：‘请看献上的牲畜多么硕大肥壮啊！’意思就是说：我国人民普遍都有生产的能力，请看他们的牲畜肥大而蕃盛，没有生癣生病，备用的牲畜充分得很！在奉上黍稷时就祷告说：‘请看献上的黍稷多么洁净而丰盛啊！’意思就是说：今年春夏秋三季都没有灾害，请看我国人民多么和睦、收成多么丰盛。在进献美酒甜酒时又祷告说：‘请尝尝我们用好米酿成的美酒吧！’意思是说：请看在我全国上下都有美德，不干没天良的事！由此可见，所谓馨香，就是上上下下有德性而没有谗言和邪行。所以能够忠心从事三时的农作，讲习五教，亲和九族，虔敬地祭祀鬼神。于是人民都很和睦，鬼神也就赐福，他们一举一动都有成就。如今，百姓各有自己的心事，鬼神也就缺了主人，光靠您的祭礼丰盛，怎么会得到幸福呢？您还是先整顿内政，和周围兄弟之国亲密友好，也许可以避免灾祸吧。”
随侯感到恐惧，于是整顿内政。楚国不敢侵犯它。', NULL, '', 'indent', 1575283239, '5de479a57796d90076befca5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643635, '曹刿论战', NULL, 90, 300, 1, 15, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '十年春，齐师伐我。公将战，曹刿请见。其乡人曰：“肉食者谋之，又何间焉？”刿曰：“肉食者鄙，未能远谋。”乃入见。问：“何以战？”公曰：“衣食所安，弗敢专也，必以分人。”对曰：“小惠未遍，民弗从也。”公曰：“牺牲玉帛，弗敢加也，必以信。”对曰：“小信未孚，神弗福也。”公曰：“小大之狱，虽不能察，必以情。”对曰：“忠之属也。可以一战。战则请从。”
公与之乘，战于长勺。公将鼓之。刿曰：“未可。”齐人三鼓。刿曰：“可矣。”齐师败绩。公将驰之。刿曰：“未可。”下视其辙，登轼而望之，曰：“可矣。”遂逐齐师。
既克，公问其故。对曰：“夫战，勇气也。一鼓作气，再而衰，三而竭。彼竭我盈，故克之。夫大国，难测也，惧有伏焉。吾视其辙乱，望其旗靡，故逐之。”', '本文出自《左传·庄公十年》。《曹刿论战》记载了发生在公元前684年，齐借口鲁国曾帮助公子纠争夺齐国君位，再次兴兵攻鲁，两军战于长勺。', '曹刿（guì）：春秋时鲁国大夫。著名的军事理论家。
十年：鲁庄公十年（公元前684年）。
齐师：齐国的军队。齐，在今山东省中部。师，军队。
伐：攻打。
我：指鲁国。《左传》根据鲁史而写，故称鲁国为“我”。
公：诸侯的通称，这里指鲁庄公。
肉食者：吃肉的人，指当权者。
谋：谋议。
间（jiàn）：参与。
鄙：鄙陋，目光短浅。
乃：于是，就。
何以战：就是“以何战”，凭借什么作战？以，用，凭，靠。
衣食所安，弗敢专也：衣食这类养生的东西，不敢独自享用。安：有“养”的意思。弗：不。专：独自专有，个人专有。
必以分人：省略句，省略了"之"，完整的句子是“必以之分人”。一定把它分给别人。以，把。人：指鲁庄公身边的近臣或贵族。
遍：一作“徧”，遍及，普遍。
牺牲玉帛（bó）：古代祭祀用的祭品。牺牲，祭祀用的猪、牛、羊等。玉，玉器。帛，丝织品。
加：虚报夸大。
小信未孚（fú）：（这只是）小信用，未能让神灵信服。孚，使人信服。
福：名词作动词，赐福，保佑。
狱：（诉讼）案件。
察：明察。
情：实情。
忠之属也：这是尽了职分（的事情）。忠，尽力做好分内的事。属，种类。
可以一战：就是“可以之一战”，可以凭借这个条件打一仗。可，可以。以，凭借。
战则请从：（如果）作战，请允许（我）跟从去。从：随行，跟从。
公与之乘：鲁庄公和他共坐一辆战车。之，指曹刿。
长勺：鲁国地名，今山东莱芜东北。
败绩：军队溃败。
驰：驱车追赶。
辙（zhé）：车轮碾出的痕迹。
轼：古代车厢前做扶手的横木。
遂：于是，就。
逐：追赶，这里指追击。
既克：已经战胜。既，已经。
夫战，勇气也：作战，（是靠）敢作敢为毫不畏惧的气概。夫（fú），放在句首，表示将发议论，没有实际意义。
一鼓作气：第一次击鼓能振作士气。作，振作。
再：第二次。
三：第三次。
彼竭我盈：他们的勇气已尽，我们的勇气正盛。彼，代词，指齐军方面。盈，充沛，饱满，这里指士气旺盛。
难测：难以推测。测，推测，估计。
伏：埋伏。
靡（mǐ）：倒下。', '鲁庄公十年的春天，齐国军队攻打鲁国。鲁庄公将要迎战。曹刿请求拜见鲁庄公。他的同乡说：“打仗的事当权者自会谋划，你又何必参与呢？”曹刿说：“当权者目光短浅，不能深谋远虑。”于是入朝去见鲁庄公。曹刿问：“您凭借什么作战？”鲁庄公说：“衣食这一类安身立命的东西，不敢独自享有，一定把它分给身边的大臣。”曹刿回答说：“这些小恩惠不能遍及百姓，百姓是不会听从您的。”鲁庄公说：“祭祀神灵的牛、羊、玉帛之类的用品，我（从来）不敢虚报数目，一定要做到诚实可信。”曹刿说：“这只是小信用，不能让神灵信服，神是不会保佑你的。”鲁庄公说：“大大小小的案件，虽然不能件件都了解得清楚，但一定要处理得合情合理。”曹刿回答说：“这才尽了本职一类的事，可以凭借这个条件打一仗。如果作战，请允许我跟随您一同去。”
鲁庄公和他共坐一辆战车，在长勺和齐军作战。鲁庄公将要下令击鼓进军。曹刿说：“现在不行。”等到齐军三次击鼓之后。曹刿说：“可以击鼓进军了。”齐军溃败。鲁庄公又要下令驾车马追逐齐军。曹刿说：“还不行。”说完就下了战车，查看齐军车轮碾出的痕迹，又登上战车，扶着车前横木远望齐军的队形，这才说：“可以追击了。”于是追击齐军。
战胜齐军后，鲁庄公问他这样做的原因。曹刿回答说：“作战，是靠敢作敢为毫不畏惧的气概。第一次击鼓能够振作士气。第二次击鼓士兵们的士气就开始低落了，第三次击鼓士兵们的士气就耗尽了。他们的士气已经消失而我军的士气正盛，所以才战胜了他们。像齐国这样的大国，他们的情况是难以推测的，怕他们设下埋伏。我看他们车轮碾过的痕迹散乱，望见他们的旗子倒下了，所以决定追击他们。”', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1ce5e272d4b2254f05c", "shortContent": "鲁庄公十年（前684），齐桓公由于鲁国曾经帮助过公子纠和他争夺王位，因此发动了一场攻打鲁国的战争。这就是春秋时代所谓的长勺之战。这次战役，强大的齐国反而被弱小的鲁国打败了，成为历史上有名的以弱胜强的战例。《左传》的记载，突出地说明了鲁国之所以战胜的原因，成功地塑造了一位卓越的人物，他就是曹刿。\n曹刿前人多认为就是曹沬，但说法不一。《史记·刺客列传》曾记载齐鲁两国在柯地会盟时，曹沬以匕首劫持齐桓公归...", "authors": ["宋", "廓"], "pressName": "上海辞书出版社"}, {"bookId": "645fb58f45e4710056afc7d2", "bookTitle": "中小学生必背古诗文(小学、初中)", "articleId": "647203cb82772d4594283586", "shortContent": "鲁庄公十年（前684），齐桓公由于鲁国曾经帮助过公子纠和他争夺王位，因此发动了一场攻打鲁国的战争。这就是春秋时代所谓的长勺之战。这次战役，强大的齐国反而被弱小的鲁国打败了，成为历史上有名的以弱胜强的战例。《左传》的记载，突出地说明了鲁国之所以战胜的原因，成功地塑造了一位卓越的人物，他就是曹刿。\n曹刿和庄公的对话，写得既条理分明，又错落有致。曹刿劈头先问：凭什么条件进行这场战争？从战略上来讲，这个提...", "authors": ["宋廓"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b6512b5420e2767ef2aa9", "shortContent": "春秋时代秦、晋是邻国，也都是大国，两国在相当长的历史时期内保持了一种十分奇特的关系。一方面从晋献公把女儿（即文中的穆姬）嫁给秦穆公开始，两国公室就不断通婚。政治联姻对于双方而言是两全其美的事情，增强了两国对付外部压力的能力。另一方面，在此期间两国之间不时发生战事，而韩之战则是秦晋之间第一次最大规模的战争。这次战争对于秦国来说具有重要意义，由于秦在韩之战中的胜利，秦开始将其地盘东扩，秦国因此逐步强盛...", "authors": ["何善蒙"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b6567a5f1e74f95ea0660", "shortContent": "本文论述宋楚泓之战的起因、经过及宋统治集团事后对此战役的总结。自“楚人伐宋”至“弗听”，记述战争的根本原因和直接原因。前者是宋襄公欲争霸天下，后者为楚国以伐宋实现救郑。从“冬十一月”至“门官歼焉”，叙说泓之战及其以宋国失败告终。“国人皆咎公”以下，论叙宋国在战败之后的总结。\n\n战争用以解决阶级和阶级、政治集团和政治集团、民族和民族、国家和国家之间的矛盾，是解决利益冲突的一种最高的斗争形式。战争往往...", "authors": ["贺圣迪", "魏自厚"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b6403a5f1e74f95ea000c", "shortContent": "春秋时期，各诸侯国之间为了兼并土地、争夺霸权而连年混战，给当时人民带来深重的灾难。因此人们常用“春秋无义战”来形容那个时代的特征。但是对于特定的战争应作具体的分析，如“齐鲁长勺之战”，应该说是齐国对鲁国的侵犯，是大国欺凌弱小国家。齐国的侵犯给鲁国上至国君，下至广大人民带来了一场灾难，因此必须加以反击。这篇文章就是记述鲁国人民从上到下如何同仇敌忾，打赢这场正义战争的。\n\n发生于公元前684年的齐鲁长...", "authors": ["朱锋刚", "魏薪"], "pressName": "上海辞书出版社"}]', '', 'indent', 1575283498, '5de47aa843c25700685156aa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643636, '齐桓公伐楚盟屈完', NULL, 14, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '四年春，齐侯以诸侯之师侵蔡，蔡溃，遂伐楚。
楚子使与师言曰：“君处北海，寡人处南海，唯是风马牛不相及也。不虞君之涉吾地也，何故？”管仲对曰：“昔召康公命我先君太公曰：‘五侯九伯，女实征之，以夹辅周室。’赐我先君履：东至于海，西至于河，南至于穆陵，北至于无棣。尔贡包茅不入，王祭不共，无以缩酒，寡人是征；昭王南征而不复，寡人是问。”对曰：“贡之不入，寡君之罪也，敢不共给？昭王之不复，君其问诸水滨。”师进，次于陉。
夏，楚子使屈完如师。师退，次于召陵。齐侯陈诸侯之师，与屈完乘而观之。齐侯曰：“岂不榖是为？先君之好是继，与不榖同好，何如？”对曰：“君惠徼福于敝邑之社稷，辱收寡君，寡君之愿也。”齐侯曰：“以此众战，谁能御之！以此攻城，何城不克！”对曰：“君若以德绥诸侯，谁敢不服？君若以力，楚国方城以为城，汉水以为池，虽众，无所用之！”
屈完及诸侯盟。', '本文出自《左传·僖公四年》。', '诸侯之师：指参与侵蔡的鲁、宋、陈、卫、郑、许、曹等诸侯国的军队。蔡：诸侯国名，姬姓，在今河南汝南、上蔡、新蔡一带。
楚子：指楚成王。与：介词，跟，和。
北海、南海：泛指北方、南方边远的地方，不实指大海，形容两国相距甚远。
唯是：即使。风：公畜和母畜在发情期相互追逐引诱。这句话的意思是说由于相距遥远，虽有引诱，也互不相干。
不虞：不料，没有想到。涉：淌水而过，这里的意思是进入，委婉地指入侵。
召（shào）康公：召公。周成王时的太保，“康”是谥号。先君：已故的君主，大公：太公，指姜尚，他是齐国的开国君主。
五侯：公、侯，伯、子、男五等爵位的诸侯。九伯：九州的长官。五侯九伯泛指各国诸侯。
实征之：可以征伐他们。
履：践踏。这里指齐国可以征伐的范围。
海：指渤海和黄海。河：黄河。穆陵：地名，即今山东的穆陵关。无棣：地名，齐国的北境，在今山东无棣县附近。
贡：贡物。包：裹束。茅：菁茅。入：进贡。共：同“供”，供给。
缩酒：渗滤酒渣，祭祀时的仪式之一：把酒倒在束茅上渗下去，就像神饮了一样（依郑玄说，见《周礼甸师》注）。
寡人：古代君主自称。征：责问，追问。
昭王：周成王的孙子周昭王。问：责问。
次：军队临时驻扎。陉（xíng）：山名，在今河南偃城县南。
屈完：楚国大夫。如：到，去。师：军队。
召（shào）陵：楚国地名，在今河南偃城东。
不榖（gǔ）：不善，诸侯自己的谦称。
惠：恩惠，这里作表示敬意的词。徼（yāo）：求；本义是巡查、巡逻。敝邑（yì）：对自己国家的谦称。
辱：屈辱，这里作表示敬意的词。
众：指诸侯的军队，
绥（suí）：安抚。
方城：指楚国在北境修筑的楚长城。
盟：订立盟约。', '鲁僖公四年的春天，齐桓公率领诸侯国的军队攻打蔡国。蔡国溃败，接着又去攻打楚国。
楚成王派使节跟诸侯之师说：“您住在北方，我住在南方，双方相距遥远，即使是马牛牝牡相诱也不相及。没想到您进入了我们的国土这是什么缘故？”管仲回答说：“从前召康公命令我们先君姜太公说：‘五等诸侯和九州长官，你都有权征讨他们，从而共同辅佐周王室。’召康公还给了我们先君征讨的范围：东到海边，西到黄河，南到穆陵，北到无隶。你们应当进贡的包茅没有交纳，周王室的祭祀供不上，没有用来渗滤酒渣的东西，我特来征收贡物；周昭王南巡没有返回，我特来查问这件事。”楚国使臣回答说：“贡品没有交纳，是我们国君的过错，我们怎么敢不供给呢？周昭王南巡没有返回，还是请您到水边去问一问吧！”于是齐军继续前进，临时驻扎在陉。
这年夏天，楚成王派使臣屈完到齐军中去交涉，齐军后撤，临时驻扎在召陵。齐桓公让诸侯国的军队摆开阵势，与屈完同乘一辆战车观看军容。齐桓公说：“诸侯们难道是为我而来吗？他们不过是为了继承我们先君的友好关系罢了。你们也同我们建立友好关系，怎么样？”屈完回答说：“承蒙您惠临敝国并为我们的国家求福，忍辱接纳我们国君，这正是我们国君的心愿。”齐桓公说：“我率领这些诸侯军队作战，谁能够抵挡他们？我让这些军队攻打城池，什么样的城攻不下？”屈完回答说：‘如果您用仁德来安抚诸侯，哪个敢不顺服？如果您用武力的话，那么楚国就把方城山当作城墙，把汉水当作护城河，您的兵马虽然众多，恐怕也没有用处！”
后来，屈完代表楚国与诸侯国订立了盟约。', NULL, '', 'indent', 1575283894, '5de47c342a6bfd007308b440', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643637, '宫之奇谏假道', NULL, 16, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '晋侯复假道于虞以伐虢。宫之奇谏曰：“虢，虞之表也。虢亡，虞必从之。晋不可启，寇不可玩。一之谓甚，其可再乎？谚所谓‘辅车相依，唇亡齿寒’者，其虞、虢之谓也。”
公曰：“晋，吾宗也，岂害我哉？”对曰：“大伯、虞仲，大王之昭也。大伯不从，是以不嗣。虢仲、虢叔，王季之穆也，为文王卿士，勋在王室，藏于盟府。将虢是灭，何爱于虞！且虞能亲于桓、庄乎？其爱之也，桓、庄之族何罪？而以为戮，不唯逼乎？亲以宠逼，犹尚害之，况以国乎？”
公曰：“吾享祀丰洁，神必据我。”对曰：“臣闻之，鬼神非人实亲，惟德是依。故《周书》曰：‘皇天无亲，惟德是辅。’又曰：‘黍稷非馨，明德惟馨。’又曰：‘民不易物，惟德繄物。’如是，则非德，民不和，神不享矣。神所冯依，将在德矣。若晋取虞，而明德以荐馨香，神其吐之乎？”
弗听，许晋使。宫之奇以其族行，曰：“虞不腊矣。在此行也，晋不更举矣。”
八月甲午，晋侯围上阳，问于卜偃曰：“吾其济乎？”对曰：“克之。”公曰：“何时？”对曰：“童谣曰：‘丙之晨，龙尾伏辰，均服振振，取虢之旂。鹑之贲贲，天策焞焞，火中成军，虢公其奔。’其九月、十月之交乎！丙子旦，日在尾，月在策，鹑火中，必是时也。”
冬，十二月丙子朔，晋灭虢，虢公丑奔京师。师还，馆于虞，遂袭虞，灭之，执虞公，及其大夫井伯，从媵秦穆姬。而修虞祀，且归其职贡于王，故书曰：“晋人执虞公。”罪虞公，言易也。', '本文出自《左传·僖公五年》。', '晋：国名，在今山西省翼城县东。晋侯：晋献公。复假（jiǎ）道：又借路。僖公二年晋曾向虞借道伐虢，今又借道，故用“复”。虞（yú）：国名，姬姓。周文王封予古公亶父之子虞仲后代的侯国，在今山西省平陆县东北。虢（guó）：国名，姬姓。周文王封其弟仲于今陕西宝鸡东，号西虢，后为秦所灭。本文所说的是北虢，北虢是虢仲的别支，在今山西平陆。虞在晋南，虢在虞南。
表：外表，这里指屏障、藩篱。
启：启发，这里指启发晋的贪心。
寇：凡兵作乱于内为乱，于外为寇。玩：这里是轻视、玩忽的意思。
其：反诘语气词，难道。
辅：面颊。车：牙床骨。
宗：同姓，同一宗族。晋、虞、虢都是姬姓的诸侯国，都同一祖先。
大（tài）伯、虞仲：周始祖太王（古公亶父）的长子和次子。昭：古代宗庙制度，始祖的神位居中，其下则左昭右穆。昭位之子在穆位，穆位之子在昭位。昭穆相承，所以又说昭生穆，穆生昭。大伯、虞仲、王季俱为大王之子，都是大王之昭。
不从：指不从父命。嗣：继承（王位）。大伯知道大王要传位给他的小弟弟王季，便和虞仲一起出走。宫子奇认为大伯没继承王位是不从父命的结果。
虢仲、虢叔：虢的开国祖，王季的次子和三子，文王的弟弟。王季于周为昭，昭生穆，故虢仲、虢叔为王季之穆。
卿士：执掌国政的大臣。盟府：主持盟誓、典策的宫府。
将虢是灭：将灭虢。将，意同“要”。是，复指提前的宾语“虢”。
桓庄：桓叔与庄伯，这里指桓庄之族。庄伯是桓叔之子，桓叔是献公的曾祖，庄伯是献公的祖父。晋献公曾尽杀桓叔、庄伯的后代。其：岂能，哪里能。之：指虞。
桓庄之族何罪，而以为戮：庄公25年晋献公尽诛同族群公子。以为戮：把他们当作杀戮的对象。唯：因为。逼（bì）：同“逼”，这里有威胁的意思。
亲：指献公与桓庄之族的血统关系。宠：在尊位，指桓、庄之族的高位。况以国乎：此句承上文，因此省略了“以国”下的“逼”字。
享祀：祭祀。据我：依从我，即保佑我。
实：同“是”复指提前的宾语。
皇：大。辅：辅佐，这里指保佑。所引《周书》已亡佚，这两句引见伪古文《尚书》，下同。
黍（shǔ）：黄黏米；稷（jì）：不黏的黍子，黍稷这里泛指五谷。馨（xīn）：浓郁的香气。
易物：改变祭品。繄（yī）：句中语气词。
冯（píng）：同“凭”。
明德：使德明。馨香：指黍稷。其：语气词，加强反问。吐：指不食所祭之物。
以：介词，表率领。以其族行：指率领全族离开虞。
腊：岁终祭祀。这里用作动词，指举行腊祭。
馆：为宾客们设的住处。这里用作动词，驻扎的意思。', '晋侯又向虞国借路去攻打虢国。宫之奇劝阻虞公说：“虢国，是虞国的外围，虢国灭亡了，虞国也一定跟着灭亡。晋国的这种贪心不能让它开个头。这支侵略别人的军队不可轻视。一次借路已经过分了，怎么可以有第二次呢？俗话说‘面颊和牙床骨互相依着，嘴唇没了，牙齿就会寒冷’，就如同虞、虢两国互相依存的关系啊。”
虞公说：“晋国，与我国同宗，难道会加害我们吗？”宫之奇回答说：“泰伯、虞仲是大王的长子和次子，泰伯不听从父命，因此不让他继承王位。虢仲、虢叔都是王季的第二代，是文王的执掌国政的大臣，在王室中有功劳，因功受封的典策还在主持盟会之官的手中。现在虢国都要灭掉，对虞国还爱什么呢？再说晋献公爱虞，能比桓庄之族更亲密吗？桓、庄这两个家族有什么罪过？可晋献公把他们杀害了，还不是因为近亲对自己有威胁，才这样做的吗？近亲的势力威胁到自己，还要加害于他们，更何况对一个国家呢？”
虞公说：“我的祭品丰盛清洁，神必然保佑我。”宫之奇回答说：“我听说，鬼神不是随便亲近某人的，而是依从有德行的人。所以《周书》里说：‘上天对于人没有亲疏不同，只是有德的人上天才保佑他。’又说：‘黍稷不算芳香，只有美德才芳香。’又说：‘人们拿来祭祀的东西都是相同的，但是只有有德行的人的祭品，才是真正的祭品。’如此看来，没有德行，百姓就不和，神灵也就不享用了。神灵所凭依的，就在于德行了。如果晋国消灭虞国，崇尚德行，以芳香的祭品奉献给神灵，神灵难道会吐出来吗？”
虞公不听从宫之奇的劝阻，答应了晋国使者借路的要求。宫之奇带着全族的人离开了虞国。他说：“虞国的灭亡，不要等到岁终祭祀的时候了。晋国只需这一次行动，不必再出兵了。”八月某一天，晋献公包围上阳。问卜偃说：“我能够成功吗？”卜偃回答说：“能攻下。”晋献公说：“什么时候？”卜偃回答说：“童谣说：‘丙子日的清早，龙尾星为日光所照;军服威武美好，夺取虢国的旗号。鹑火星像只大鸟，天策星没有光耀，鹑火星下整理军队，虢公将要逃跑。’这日子恐怕在九月底十月初吧！丙子日的清晨，日在尾星之上，月在天策星之上，鹑火星在日月的中间，一定是这个时候。”冬天十二月初一那天，晋灭掉虢国，虢公丑逃到东周的都城。晋军回师途中安营驻扎在虞国，乘机突然发动进攻，灭掉了虞国，捉住了虞公和他的大夫井伯，把井伯作为秦穆姬的陪嫁随从。然而仍继续祭祀虞国的祖先，并且把虞国的贡物仍归于周天子。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1ce5914587d02f59ff7", "shortContent": "春秋时鲁僖公二年（前658），晋国以宝玉、骏马为赂，向虞国借道攻打虢国。贪而愚的虞公不仅答应借道，而且还要同去攻打虢国。虞国大夫宫之奇向虞公进谏，但听不进去。这次战役晋国拿下了虢国的下阳。事过三年，即僖公五年（前655），晋献公又向虞公借道，再次去攻打虢国，昏愦的虞公又满口答应了。这件事关系到虞国的存亡，善于料事的宫之奇不得不向虞公再次进谏。宫之奇讲的话，在《左传》中被完整地保存了下来，这是很有意...", "authors": ["宋", "廓"], "pressName": "上海辞书出版社"}]', '', 'indent', 1575284615, '5de47f05562071007694ce19', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643641, '阴饴甥对秦伯', NULL, 6, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '十月，晋阴饴甥会秦伯，盟于王城。
秦伯曰：“晋国和乎？”对曰：“不和。小人耻失其君而悼丧其亲，不惮征缮以立圉也。曰：‘必报仇，宁事戎狄。’君子爱其君而知其罪，不惮征缮以待秦命。曰：‘必报德，有死无二。’以此不和。”秦伯曰：“国谓君何？”对曰：“小人戚，谓之不免；君子恕，以为必归。小人曰：‘我毒秦，秦岂归君？’君子曰：‘我知罪矣，秦必归君。贰而执之，服而舍之，德莫厚焉，刑莫威焉。服者怀德，贰者畏刑，此一役也，秦可以霸。纳而不定，废而不立，以德为怨，秦不其然。’”秦伯曰：“是吾心也。”
改馆晋侯，馈七牢焉。', '本文出自《左传·僖公十五年》。晋惠公本是秦穆公的舅老爷，他靠姐夫的帮助，回国登了君位；却以怨报德，和秦国打了一仗，结果兵败被俘。阴饴甥在这时奉命到秦国求和，实在尴尬得很。但是，他在回答秦穆公的时候，巧妙地将国人分为“君子”、“小人”两部分，一正一反，既承认晋侯不是，向秦服罪；又表明晋国的士气不可轻侮。软硬兼施，说得不亢不卑，恰到好处。因此赢得秦穆公的尊敬，决心做个顺水人情，放回晋惠公，以提高自己的威信。', '阴饴甥：名饴，甥，指他为晋侯的外甥。因封于阴（今河南陕县至陕西商县一带）·，故又称阴饴甥。晋大夫。秦伯：指秦穆公。
王城：今陕西朝邑县西南。
小人：指缺乏远见的人。君：指晋惠公。他借秦穆公的力量才做了国君，后来和秦发生矛盾，在战争中被俘。
惮：怕。征缮：征集财赋，修缮兵器，准备打仗。圉：晋惠公的太子名。
君子：指晋国的有远见的贵族。待秦命：这是委婉的说法。真正意思是：如果秦不送回我们的国君，就不惜一切，再打一仗。
必报德，有死无二：报答秦国对晋的恩德，至死没有二心。
戚：忧愁、悲哀。
毒：毒害，得罪。指晋惠公与秦为敌。以前晋国发生灾荒，秦国输送了粮食；后来秦国发生灾荒，晋国一点也不给。
贰：背叛。舍：释放。
改馆：换个住所，改用国君之礼相待。
馈：赠送。七牢：牛、羊、猪各一头，叫做一牢。七牢是当时款待诸侯的礼节。', '鲁僖公十五年十月，晋国的阴饴甥会见秦伯，两国在王城结盟。秦穆公问他：“你们晋国内部意见和协吗？”阴饴甥说“不和。小人以失去国君为耻，又因丧失亲人而悲伤，不怕多征赋税，舍得花钱添置武器盔甲，并且拥立太子姬圉继任国君。他们说：‘宁肯奉事戎狄，也得报这个仇。’君子则爱护自己的国君，但也知道他的罪过。他们也不怕多征赋税，舍得花钱添置武器盔甲，却是为了等待秦国的命令。他们说：‘宁可牺牲，一定得报答秦国的恩德。’这样，意见就不一致。”
秦穆公又问：“你们对国君的命运有什么看法？”阴饴甥说：“小人发愁，认为国君不免灾祸；君子宽心，以为国君必定回来。小人说：‘我对秦国太无情了，秦国岂肯还我国君？’君子说：‘我已认罪了，秦国必定还我国君。’他背叛了，就抓起来；他认罪了，就放回来。恩德再没有比这更厚的了，刑罚也没有比这更威严的了。内心臣服的自然感恩怀德，那怀有二心的也会畏惧刑罚。这一仗如此了结，秦国真可成就霸业了。不然的话，当初帮他回国登位，又不让他安于其位；后来废了他的君位，又不让他复位，以致原来施的恩德，反变成仇恨，秦国总不会出此下策吧！”
秦穆公说：“你讲的正合我心啊！”马上就让晋侯改住宾馆，赠送七牢，以诸侯之礼相待。', NULL, '', 'indent', 1575296985, '5de4af5643c25700685367de', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643642, '子鱼论战', NULL, 12, 300, 0, 2, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '楚人伐宋以救郑。宋公将战。大司马固谏曰：“天之弃商久矣，君将兴之，弗可赦也已。”弗听。冬十一月己巳朔，宋公及楚人战于泓。宋人既成列，楚人未既济。司马曰：“彼众我寡，及其未既济也，请击之。”公曰：“不可。”既济而未成列，又以告。公曰：“未可。”既陈而后击之，宋师败绩。公伤股，门官歼焉。
国人皆咎公。公曰：“君子不重伤，不禽二毛。古之为军也，不以阻隘也。寡人虽亡国之余，不鼓不成列。”子鱼曰：“君未知战。勍敌之人，隘而不列，天赞我也。阻而鼓之，不亦可乎？犹有惧焉！且今之勍者，皆我敌也。虽及胡耇，获则取之，何有于二毛？明耻教战，求杀敌也。伤未及死，如何勿重？若爱重伤，则如勿伤；爱其二毛，则如服焉。三军以利用也，金鼓以声气也。利而用之，阻隘可也；声盛致志，鼓儳可也。”', '本文出自《左传·僖公二十二年》。公元前638年，宋、楚两国为争夺中原霸权，在泓水边发生战争。可宋襄公死抱住迂腐教条不放，拒绝接受子鱼的正确意见，惨遭失败。子鱼的观点和宋襄公的迂执形成鲜明对比。他主张抓住战机，攻其不备，先发制人，彻底消灭敌人的有生力量，这样才能夺取战争的胜利。', '宋公：宋襄公，名兹父。前638年宋伐楚，楚救郑，这年冬天宋楚两军交战于泓。
大司马：掌管军政、军赋的官职，这里指公孙固。
泓：泓水，在今河南省柘（zhè）城县西。
既：已经。
济：渡过。
司马：统帅军队的高级长官，此指目夷，字子鱼。
告：报告。
陈：同“阵”，这里作动词，即摆好阵势。
败绩：大败。
股：大腿。
门官：国君的卫士。
咎：怪罪，归罪，指责。
重（chóng）：再次。
禽：同“擒”，俘虏。二毛：头发斑白的人，指代老人。
阻，迫也。隘，险也。言不迫人于险。
寡人：国君自称。亡国之余：亡国者的后代。宋襄公是商朝的后代，商亡于周。
鼓：击鼓，名词做动词。
勍（qíng）敌：强敌，劲敌。勍：强而有力。
隘：这里作动词，处在险隘之地。
赞：助。
成列：排成战斗行列.
胡耇（gǒu）：年纪很大的人。胡：年老。
何有于二毛：意思是还管什么头发花白的敌人。
明耻：使认识什么是耻辱.教战:教授作战的技能。
爱重伤：怜悯受伤的敌人。
服：（对敌人）屈服。
三军：春秋时，诸侯大国有三军，即上军，中军，下军。这里泛指军队。用：施用，这里指作战。
金鼓：古时作战，击鼓进兵，鸣金收兵。金：金属响器。声气：振作士气。
儳（chán）：不整齐，此指不成阵势的军队。', '楚军攻打宋国以援救郑国。宋襄公将要迎战，大司马公孙于是劝阻说，“上天已经抛弃我们很久了，主公想兴复它，违背天命，是不可饶恕的。”襄公不听。宋襄公和楚国人在泓水交战。宋军已经排成战斗的行列，楚国人没有全部渡过泓水。子鱼说：“对方人多，我方人少，趁着他们没有全部渡过泓水，请攻击他们。”宋襄公说：“不行。”楚军全部渡河，但尚未排好阵势，子鱼再次报告宋襄公。宋襄公说：“还不行。”楚军摆好阵势宋军才攻击楚军。宋军大败，宋襄公大腿受伤，国君的卫士被杀绝了。
国人都责备宋襄公。襄公说：“君子不再伤害已经受伤的人，不俘虏头发斑白的老人。古代用兵的道理，不凭借险隘的地形阻击敌人。我虽然是亡国者的后代，也不攻击没有排成阵势的敌人。”子鱼说：“主公不懂得作战。面对强大的敌人，敌人因地势险阻而未成阵势，这是上天帮助我们；阻碍并攻击他们，不也可以吗？还有什么害怕的呢？而且现在强大的，都是我们的敌人。即使是年纪很大的人，能俘虏就抓回来，还管什么头发斑白的敌人？教导士兵作战，使他们知道退缩就是耻辱来鼓舞战斗的勇气，教战士掌握战斗的方法，就是为了杀死敌人。敌人受伤却还没有死，为什么不能再杀伤他们？如果怜惜他们，不愿再去伤害受伤的敌人，不如一开始就不伤害他们；怜惜头发斑白的敌人，不如对敌人屈服。军队凭借有利的时机而行动，锣鼓用来鼓舞士兵的勇气。利用有利的时机，当敌人遇到险阻，我们可以进攻。声气充沛盛大，增强士兵的战斗意志，攻击未成列的敌人是可以的。”', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b6567a5f1e74f95ea0660", "shortContent": "本文论述宋楚泓之战的起因、经过及宋统治集团事后对此战役的总结。自“楚人伐宋”至“弗听”，记述战争的根本原因和直接原因。前者是宋襄公欲争霸天下，后者为楚国以伐宋实现救郑。从“冬十一月”至“门官歼焉”，叙说泓之战及其以宋国失败告终。“国人皆咎公”以下，论叙宋国在战败之后的总结。\n\n战争用以解决阶级和阶级、政治集团和政治集团、民族和民族、国家和国家之间的矛盾，是解决利益冲突的一种最高的斗争形式。战争往往...", "authors": ["贺圣迪", "魏自厚"], "pressName": "上海辞书出版社"}]', '', 'indent', 1575297487, '5de4b14d7796d90076c12e68', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643646, '寺人披见文公', NULL, 7, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '吕、郤畏逼，将焚公宫而弑晋侯。寺人披请见。公使让之，且辞焉，曰：“蒲城之役，君命一宿，女即至。其后余从狄君以田渭滨，女为惠公来求杀余，命女三宿，女中宿至。虽有君命何其速也？夫袪犹在，女其行乎！”对曰：“臣谓君之入也，其知之矣。若犹未也，又将及难。君命无二，古之制也。除君之恶，唯力是视。蒲人、狄人、余何有焉？即位，其无蒲、狄乎！齐桓公置射钩，而使管仲相。君若易之，何辱命焉？行者甚众，岂唯刑臣？”公见之，以难告。
晋侯潜会秦伯于王城。己丑晦，公宫火。瑕甥、郤芮不获公，乃如河上，秦伯诱而杀之。', '本文出自《左传·僖公二十四年》。', '吕、郤：吕即阴饴甥，他的采邑除阴外还有吕今山西霍县西、瑕今山西临猗附近，故又称吕甥、瑕甥。郤即郤芮。二人都是晋惠公、晋怀公的旧臣。
畏逼：害怕遭受迫害。
弑：古时子杀父，臣杀君为弑。
见：谒见。
使：派人来到某个地方。
让：斥责。
一宿：隔一夜。
女：同“汝”，你。
田：打猎。
中宿：隔两夜。
袪：衣袖。
入：回到国内。
其：在这里表示推测语气。
之：指为君之道。
及难：遭遇灾难。
唯力是视：即“唯视力”，只看自己力量多大，就尽多大力量。
余何有焉：和我有什么关系呢？
齐桓公置射钩：鲁庄公九年，管仲奉公子纠与齐桓公战于乾时，管仲曾射中齐桓公革带上的钩，后来他投奔齐桓公，齐桓公能听鲍叔牙劝说，置射钩之仇而不问，任用其为相。
潜：秘密地。
诱：诱骗。', '吕甥、郤芮害怕受到威逼，要焚烧晋文公的宫室而杀死文公。寺人披请求进见，文公令人训斥他，并且拒绝接见，说：“蒲城的战役，君王命你第二天赶到，你马上就来了。后来我逃到狄国同狄国国君到渭河边打猎，你替惠公前来谋杀我，惠公命你三天后赶到，你过了第二天就到了。虽然有君王的命令，怎么那样快呢？在蒲城被你斩断的那只袖口还在。你就走吧！”披回答说：“小臣以为君王这次返国，大概已懂得了为君之道。如果还没有懂，恐怕您又要遇到灾难。对国君的命令没有二心，这是古代的制度。除掉国君所憎恶的人，就看自己有多大的力量，尽多大的力量。您当时是蒲人或狄人，对于我又有什么关系呢？现在您即位为君，难道就不会再发生蒲、狄那样的事件吗？从前齐桓公抛弃射钩之仇，而让管仲辅佐自己，您如果改变桓公的做法，又何必辱蒙您下驱逐的命令？这样，要逃走的人就会很多了，岂只受刑的小臣我一人？”于是文公接见了披，他把即将发生的叛乱报告了文公。
晋文公暗地里和秦穆公在秦国的王城会晤商量应付的办法。三月的最后一天，晋文公的宫室果然被烧。瑕甥、郤芮没有捉到文公，于是逃跑到黄河边上，秦穆公诱他们过河把他们杀了。', NULL, '', 'indent', 1575366693, '5de5bf9e7796d90076c94df5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643647, '介之推不言禄', NULL, 8, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '晋侯赏从亡者，介之推不言禄，禄亦弗及。
推曰：“献公之子九人，唯君在矣。惠、怀无亲，外内弃之。天未绝晋，必将有主。主晋祀者，非君而谁？天实置之，而二三子以为己力，不亦诬乎？窃人之财，犹谓之盗。况贪天之功，以为己力乎？下义其罪，上赏其奸。上下相蒙，难与处矣。”
其母曰：“盍亦求之？以死谁怼？”对曰：“尤而效之，罪又甚焉！且出怨言，不食其食。”其母曰：“亦使知之，若何？”对曰：“言，身之文也。身将隐，焉用文之？是求显也。”其母曰：“能如是乎？与汝偕隐。”遂隐而死。
晋侯求之，不获，以绵上为之田。曰：“以志吾过，且旌善人。”', '本文出自《左传·僖公二十四年》。', '晋侯：指晋文公，即重耳。他逃亡在外，在秦国的帮助下回晋继承君位。
赏：赐有功也。
从亡者：从文公出亡在外之臣，如狐偃、赵衰之属。
介之推：亦从亡之臣。晋文公臣子，曾割自己腿上的肉以食文公。
献公：重耳之父晋献公。
惠、怀：惠公，怀公。惠公是文公重耳的弟弟，是怀公的父亲。
置：立。
二三子：相当于“那几个人”，指跟随文公逃亡诸臣。子是对人的美称。
诬：欺骗。
下义其罪：义，善也。言贪天之功，在人为犯法，而下反以为善也。
上赏其奸：奸，伪也。言贪天之功在国为伪，而上反以此赐也。
蒙：欺骗。
盍：何不。
怼（duì）：怨恨。
尤：罪过。
文：花纹，装饰。言人之有言，所以文饰其身。
绵上：地名，在今山西介休县南、沁源县西北的介山之下。
田：祭田。
志：记载。
旌：表彰。', '晋文公赏赐跟着他逃亡的人们，介之推不去要求禄赏，而晋文公赐禄赏时也没有考虑到他。
介之推说：“献公的儿子有九个，现在惟独国君还在人世。惠公、怀公没有亲信，国家内外都抛弃他们。天没有打算灭绝晋，所以必定会有君主。主持晋国祭祀的人，不是君王又是谁呢？上天实际已经安排好了的，而跟随文公逃亡的人却认为是自己的贡献，这不是欺骗吗？偷窃别人的钱财，都说是盗窃。更何况贪图天的功劳，将其作为自己的贡献呢？下面的臣子将罪当做道义，上面的国君对这样奸诈的人给予赏赐。上下互相欺瞒，难以和他们相处啊。”
他的母亲问：“你为什么不也去要求赏赐呢？否则这样贫穷地死去又能去埋怨谁呢？”答道：“既然斥责这种行为是罪过而又效仿它，罪更重啊！况且说出埋怨的话了，以后不应吃他的俸禄了。”母亲再问：“那让国君知道这事，可以吗？”答道：“言语，是身体的装饰。身体将要隐居了，还要装饰它吗？这样是乞求显贵啊。”母亲说：“你真能够这样做吗？那么我和你一起隐居吧。”他们便一直隐居到死去。
晋文公没有找到他，便用绵上作为他的祭田。说：“用它来记下我的过失，并且表彰善良的人。”', NULL, '', 'indent', 1575367197, '5de5c19921b47e006ca7aad5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643648, '展喜犒师', NULL, 6, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '夏，齐孝公伐我北鄙。公使展喜犒师，使受命于展禽。齐侯未入竟，展喜从之，曰：“寡君闻君亲举玉趾，将辱于敝邑，使下臣犒执事。”齐侯曰：“鲁人恐乎？”对曰：“小人恐矣，君子则否。”齐侯曰：“室如县罄，野无青草，何恃而不恐？”对曰：“恃先王之命。昔周公、大公，股肱周室，夹辅成王。成王劳之，而赐之盟，曰：‘世世子孙，无相害也！’载在盟府，太师职之。桓公是以纠合诸侯，而谋其不协，弥缝其阙，而匡救其灾，昭旧职也。及君即位，诸侯之望曰：‘其率桓之功。’我敝邑用不敢保聚、曰：‘岂其嗣世九年，而弃命废职，其若先君何？’君必不然。恃此而不恐。”齐侯乃还。', '本文出自《左传·僖公二十六年》。鲁僖公二十六年（前634），齐孝公率军攻打鲁国，齐强鲁弱，又适逢鲁国发生饥荒，根本无力抵挡，形势十分危急。鲁僖公派遣展喜迎上前去犒劳齐军。由于展喜的机智善辩，从容应对，终于取得了外交上的胜利，使齐孝公无言以对，不得不收兵还师，从而解救了国家的危难。', '齐孝公：齐桓公的儿子。鄙：边远地方。
公：指鲁僖公。犒：慰劳。
竟：同“境”。
县：同“悬”。罄：中间空虚的乐器。
周公：周文王的儿子，名旦，鲁国的始祖。大公：即吕望，姜姓，通称姜太公，齐国的始祖。大同“太”。
股：大腿。肱：胳膊由肘到肩的部分。“股肱”，意为得力的助手。这里作动词用，意为辅佐。
载：载言，指盟约。盟府：掌管盟约文书档案的官府。
职：动词，掌管。
旧职：从前的职守。即指齐始祖姜太公股肱周室的事业。
率：遵循。桓：指齐桓公。', '齐孝公攻打鲁国北部边境。僖公派展喜去慰劳齐军，并叫他到展禽那里接受犒劳齐军的外交辞令。齐孝公还没有进入鲁国国境，展喜出境迎上去进见他，说：“寡君听说您亲自出动大驾，将要光临敝邑，派遣下臣来犒劳您的左右侍从。”齐孝公说：“鲁国人害怕吗？”展喜回答说：“小人害怕了，君子就不。”齐孝公说：“你们的府库空虚得就像悬挂起来的磬，四野里连青草都没有，仗着什么而不害怕？”展喜回答说：“依仗先王的命令。从前周公、太公辅佐周室，在左右协助成王。成王犒劳他们，赐给他们盟约，说：‘世世代代的子孙，不要互相侵害。’这个盟约藏在盟府里，由太史掌管。桓公因此联合诸侯，而解决他们之间的不和谐，弥补他们的缺失，而救援他们的灾难，这都是显扬过去的职责啊。等到君侯登上君位，诸侯都给予厚望，说：‘他会继承桓公的功业吧。’我敝邑因此不敢保城聚众，说：‘难道他即位九年，就丢弃王命，废掉职责，他怎么向先君交代？他一定不会这样的。’依仗这个才不害怕。”齐孝公于是收兵回国。', NULL, '', 'indent', 1575368789, '5de5c7c5546eaa0071ebcbd1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643649, '烛之武退秦师', NULL, 336, 300, 0, 7, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '晋侯、秦伯围郑，以其无礼于晋，且贰于楚也。晋军函陵，秦军氾南。
佚之狐言于郑伯曰：“国危矣，若使烛之武见秦君，师必退。”公从之。辞曰：“臣之壮也，犹不如人；今老矣，无能为也已。”公曰：“吾不能早用子，今急而求子，是寡人之过也。然郑亡，子亦有不利焉！”许之。
夜缒而出，见秦伯，曰：“秦、晋围郑，郑既知亡矣。若亡郑而有益于君，敢以烦执事。越国以鄙远，君知其难也，焉用亡郑以陪邻？邻之厚，君之薄也。若舍郑以为东道主，行李之往来，共其乏困，君亦无所害。且君尝为晋君赐矣，许君焦、瑕，朝济而夕设版焉，君之所知也。夫晋，何厌之有？既东封郑，又欲肆其西封，若不阙秦，将焉取之？阙秦以利晋，唯君图之。”秦伯说，与郑人盟。使杞子、逢孙、杨孙戍之，乃还。
子犯请击之，公曰：“不可。微夫人之力不及此。因人之力而敝之，不仁；失其所与，不知；以乱易整，不武。吾其还也。”亦去之。', '本文出自《左传·僖公三十年》。故事背景是秦、晋围郑，发生在公元前630年（鲁僖公三十年）九月甲午时。秦、晋联合攻打郑国。郑国危在旦夕，郑文公派能言善辩的烛之武前去说服秦伯。烛之武巧妙地勾起秦穆公对秦、晋之间的矛盾的记忆，向秦伯分析了当时的形势，说明了保存郑国对秦有利、灭掉郑国对秦不利的道理，终于说服了秦伯。', '晋侯、秦伯：指晋文公和秦穆公。
以其无礼于晋：指晋文公即位前流亡国外经过郑国时，没有受到应有的礼遇。倒装句，于晋无礼。以，因为，连词。其，代词，它，指郑国。于，对于。
且贰于楚：并且从属于晋的同时又从属于楚。且，并且，表递进。贰，从属二主。于，对，介词。
晋军函陵：晋军驻扎在函陵。军，名词作动词，驻军。函陵，郑国地名，在今河南新郑北。
氾（fán）南：氾水的南面，也属郑地。（古汉语字典注，氾作水命是念作第二声。）
佚（yì）之狐：郑国大夫。
若：假如。使：派。见：拜见进见。从：听从。
辞：推辞。
臣之壮也：我壮年的时候。
犹：尚且。
无能为也已：不能干什么了。为，做。已，同“矣”，语气词，了。
用：任用。
是寡人之过也：这是我的过错。是，这。过，过错。
然：然而。
许之：答应这件事。许，答应。
缒（zhuì）：用绳子拴着人（或物）从上往下运。
既：已经。
敢以烦执事：冒昧地拿（亡郑这件事）麻烦您手下的人。这是客气的说法。敢，冒昧的。执事，执行事务的人，对对方的敬称。
越国以鄙（bǐ）远：（然而）越过别国而把远地（郑国）当做边邑。越，越过。鄙，边邑。
焉用亡郑以陪邻：为什么要灭掉郑国而给邻国增加土地呢？焉：何。用：介词，表原因。陪：增加。邻：邻国，指晋国。
邻之厚，君之薄也：邻国的势力雄厚了，您秦国的势力也就相对削弱了。之：主谓之间取消句子独立性。厚，雄厚。
若舍郑以为东道主：如果您放弃围攻郑国而把它作为东方道路上（招待过客）的主人。舍：放弃（围郑）。
行李：古今异义，出使的人。
共（gōng）其乏困：供给他们缺乏的东西。共，通“供”，供给。其：代指使者。
尝为晋君赐矣：曾经给予晋君恩惠（指秦穆公曾派兵护送晋惠公回国）。尝，曾经。为，给予。赐，恩惠。为···赐：施恩。
许君焦、瑕：（晋惠公）许诺给您焦、瑕两城。
朝济而夕设版焉：指晋惠公早上渡过黄河回国，晚上就修筑防御工事。济，渡河。设版，修筑防御工事。版，筑土墙用的夹板。朝，在早晨。
厌：通“餍”，满足。
东封郑：在东边让郑国成为晋国的边境。封，疆界。这里作用动词。
肆其西封：扩展它西边的疆界。指晋国灭郑以后，必将图谋秦国。肆，延伸，扩张。封：疆界。
阙（quē）：侵损，削减。盟：结盟。戍：守卫。还：撤军回国。[注：在古汉语词典中明确标注为“缺”音，仁者见仁智者见智。
说：“说”同“悦”，喜欢，高兴。
微夫人之力不及此：假如没有那个人的力量，我是不会到这个地步的。微：没有。夫人：远指代词，那人，指秦穆公。
因人之力而敝之，不仁：依靠别人的力量，又返回来损害他，这是不仁道的。因：依靠。敝，损害。
失其所与，不知：失掉自己的同盟者，这是不明智的。与，结交，亲附。知：通“智”。
以乱易整，不武：用混乱相攻取代联合一致，是不符合武德的。易，代替。武，指使用武力是所应遵守的道义准则。不武，不符合武德。整，指一致的步调。
吾其还也：我们还是回去吧。其，表商量或希望的语气，还是。
去之：离开郑国。之，指代郑国。', '僖公三十年晋文公和秦穆公联合围攻郑国，因为郑国曾对晋文公无礼，并且从属于晋的同时又从属于楚。晋军驻扎在函陵，秦军驻扎在氾水的南面。
佚之狐对郑文公说：“国家危险了，假如派烛之武去见秦穆公，秦国的军队一定会撤退。”郑文公同意了。烛之武推辞说：“我壮年的时候，尚且不如别人；现在老了，也不能有什么作为了。”郑文公说：“我没有及早重用您，现在由于情况危急因而求您，这是我的过错。然而郑国灭亡了，对您也不利啊！”烛之武就答应了这件事。
在夜晚有人用绳子将烛之武从城楼放下去，见到秦穆公，烛之武说：“秦、晋两国围攻郑国，郑国已经知道要灭亡了。假如灭掉郑国对您有好处，怎敢冒昧地拿这件事情来麻烦您。然而越过别国把远方的郑国作为秦国的东部边邑，您知道这是困难的，为什么要灭掉郑国而给邻国增加土地呢？邻国的势力雄厚了，您秦国的势力也就相对削弱了。如果您放弃围攻郑国而把它当作东方道路上招待过客的主人，出使的人来来往往，郑国可以随时供给他们缺乏的东西，对您也没有什么害处。而且您曾经给予晋惠公恩惠，惠公曾经答应给您焦、瑕二座城池。然而惠公早上渡过黄河回国，晚上就在那里筑城防御，这是您所知道的。晋国，怎么会有满足的时候呢？现在它已经在东边使郑国成为它的边境，又想要向西扩大边界。如果不使秦国土地亏损，它到哪里去夺取土地？削弱秦国对晋国有利，希望您还是多多考虑这件事！”秦伯非常高兴，就与郑国签订了盟约。派遣杞子、逢孙、杨孙戍守郑国，秦伯就回国了。
晋大夫子犯请求出兵攻击秦军。晋文公说：“不行！如不是秦国国君的力量，就没有我的今天。依靠别人的力量而又反过来损害他，这是不仁义的；失掉自己的同盟者，这是不明智的；用混乱相攻取代联合一致，是不符合武德的。我们还是回去吧！”晋军也就离开了郑国。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1ce5914587d02f59ff6", "shortContent": "本文写的是郑国在兵临城下的紧急气氛中一次成功的外交活动，描绘了一位有勇有谋的外交家形象。\n这件事发生在鲁僖公三十年（前630）。当时已取得霸主地位的晋国，联合西邻秦国去攻打东邻郑国。晋、秦两支大军驻扎的函陵和氾南，都是郑国的地方。\n晋国为什么要来攻打郑国呢？理由是“以其无礼于晋，且贰于楚也”。无礼于晋，指的是重耳流亡到郑国时，“郑文公亦不礼焉”（《左传·僖公二十三年》）。当年，郑文公缺乏远见，没有...", "authors": ["董扶其"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b636fb6a81d0c538d801d", "shortContent": " 本文以极其精练的文字叙述了春秋初年郑庄公执政时期一场内乱酝酿、发生和平息的过程，刻画了其中三个核心人物，最后以奉行孝道的贤臣形象说明了对待宫廷矛盾的正确态度。\n\n这场内乱的根源是郑庄公之母姜氏偏爱其小儿子共叔段，但是郑庄公却是个关键性的人物。郑庄公工于心计，心肠凶狠，比他的母亲和胞弟更善于权谋。姜氏因难产而厌恶庄公，力图把共叔段推上君位，庄公对此早有觉察，胸中已有成算。他不动声色，暗使计谋。姜氏...", "authors": ["朱锋刚"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b649ae49f46528a43150d", "shortContent": "《左传》此文记载齐桓公、管仲以尊王名义，率八国之师南下征楚，楚王两度派遣使臣，与之谈判，双方在昭陵订盟。\n\n这段历史所表明的是，管仲为齐桓公图霸业所确立的指导思想：“尊王攘夷。”僖公四年及此前的政治形势，据《春秋·公羊传》所论，是“南夷与北狄交，中国不绝若线”。北面的狄人伐邢破卫，在今河北、河南威胁着华夏族的各国，南面楚人的势力已逐渐向黄河流域拓展。华夏族面临存亡危机，管仲主张在“尊王”的旗帜下，...", "authors": ["贺圣迪"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b6635e49f46528a431c69", "shortContent": "晋在城濮之战中打败了楚国之后，成为称霸中原的盟主，抑制了秦国向东的扩张，两国之间的关系开始紧张。然而由于晋文公之妻是秦穆公之女，文公又是在穆公的支持下才登上晋国君主之位的，所以两国仍然维持着良好的关系。公元前630年，晋曾约秦共同围郑。但是在晋文公去世以后，形势发生了变化。秦穆公趁晋国新君登临大位未稳之机，偷袭郑国，企图将它一举吞并，这样，就揭开了秦晋殽之战的序幕。这一场伏击歼灭战发生于公元前62...", "authors": ["熊岳", "邱轶皓"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b665bb5420e2767ef2eef", "shortContent": " 这篇文章以夹叙夹议的方式讲述两件事。一是郑、宋两国的大棘之战，宋国惨败，主将乐吕战死，华元被俘。另一件事，即晋国统治集团内部的一场惊心动魄的政治斗争。大臣赵盾因多次批评晋灵公的胡作非为而两次遭到昏君派遣的杀手的行刺，幸免于难后外出流亡，将要出境时获悉灵公被杀，返回迎立公子黑臀为君。这篇记述对其中人物的行为表明了自己的立场，表明人们对于国家和人民应有的态度，也反映了古人在对待君主问题上的两难处境。...", "authors": ["贺圣迪", "魏自厚"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b67de30675327e125034b", "shortContent": "《左传》不仅真实、详尽地记录了无数重大历史事件，而且保存了有关哲学、文学、社会风俗的极其丰富的资料，以及许多政治、法律、外交等方面的宝贵文献。《吕相绝秦》就是其中一篇十分精彩的外交文件。它被后人誉为“檄文之祖”（韩席筹《左传分国集注》下），即千古第一檄文。尽管此文并未宣扬渗透于《左传》全书的儒家观念，甚至它的一些做法，如歪曲历史，为儒家传统所不容，但是《左传》作者在惜墨如金的时代还是把长达一千余字...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b680bc98d685fd9d8df73", "shortContent": "公元前578年，晋国在麻隧之战中战胜了秦国，一时国威大振，中原中小诸侯国大都听命于晋，惟有郑国仍然以楚为后盾，与晋对抗，因此晋处心积虑地要打败楚、郑，以进一步巩固自己的霸权。这场多国卷入的大战终于在成公十六年（前575年）于鄢陵（今河南鄢陵西南）爆发。战争以楚方的败北而告终，在此后一段相当长的时期内楚国再也无力北向争霸。\n\n《左传》作者左丘明始终把战争看成是两方综合国力的较量，尽管他有时对占卜表现...", "authors": ["贺圣迪", "魏自厚"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b696ae49f46528a4327e6", "shortContent": " 本文所记之事，并非全都发生于鲁襄公三十一年（前542年），其主旨是论述子产能治好郑国的原因。子产姓公孙，名侨，曾平定贵族内乱，郑简公十二年（前554年）为卿，二十三年（前543年）执政，实行改革，整顿贵族田地和农户编制，增加了财政税收，却减轻了普通百姓的负担。他把法律条文铸在鼎上公布，为各国效法。郑处于晋楚两大国之间，动辄得咎，但由于子产内政外交处理得当，相安无事。孔子称赞子产行惠民之政。根据本...", "authors": ["贺圣迪"], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b661130675327e124fb66", "shortContent": "晋在城濮之战打败了楚国之后开始称霸中原，为了巩固其霸主地位，公元前630年晋约秦出兵围郑，借口是文公执政前亡命过郑，郑文公不纳，以及城濮之战时郑国帮助楚国。兵临城下，郑国危在旦夕，本文就是记述春秋时杰出的外交家郑大夫烛之武在国家生死存亡的危急关头，不顾年迈体弱，只身赴敌军大营，以三寸之舌说退秦晋大军的过程，说明了巧妙地利用大国矛盾的外交艺术及外交活动在维护国家安全中的重要作用，告诉人们那种甘于寂寞...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1575369965, '5de5cc6b21b47e006ca81d01', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643650, '蹇叔哭师', NULL, 9, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '杞子自郑使告于秦曰：“郑人使我掌其北门之管，若潜师以来，国可得也。”穆公访诸蹇叔。蹇叔曰：“劳师以袭远，非所闻也。师劳力竭，远主备之，无乃不可乎？师之所为，郑必知之。勤而无所，必有悖心。且行千里，其谁不知？”公辞焉。召孟明、西乞、白乙使出师于东门之外。蹇叔哭之曰：“孟子！吾见师之出而不见其入也。”公使谓之曰：“尔何知！中寿，尔墓之木拱矣！”
蹇叔之子与师，哭而送之，曰：“晋人御师必于崤，崤有二陵焉。其南陵，夏后皋之墓也；其北陵，文王之所辟风雨也，必死是间，余收尔骨焉！”秦师遂东。', '本文出自《左传·僖公三十二年》。公元前627年，秦穆公发兵攻打郑国，他打算和安插在郑国的奸细里应外合，夺取郑国都城。秦伯向蹇叔咨询。他凭着自己漫长的阅历和丰富的政治经验，根据秦、晋、郑三方情况，将潜在的危险无不一一道出，对“劳师以袭远”的违反常识的愚蠢行径作了彻底的否定，指出袭郑必败无疑。', '杞子：秦国大夫。
掌：掌管。管，钥匙。
潜：秘密地。
国：国都。
访：询问，征求意见。
远主：指郑君。
勤：劳苦。无所：一无所得。
悖（bèi）心：违逆之心，反感。
孟明：秦国大夫，姜姓，百里氏，名视，字孟明。秦国元老百里奚之子。西乞：秦国大夫，字西乞，名术。秦国元老蹇叔之子。白乙：秦国大夫，字白乙，名丙。秦国元老蹇叔之子。这三人都是秦国将军。
中（zhōng）寿：有两种解释。1.参见中寿。2.中等年纪。不管哪种解释，就句意，均为秦穆王讽刺蹇叔现已年老昏聩，要是你蹇叔只活个差不多就去世的话，你坟上的树都有两手合抱一般粗了。
拱：两手合抱。
肴（xiáo）：同崤，山名，在今河南洛宁西北。
陵：大山。崤山有两陵，南陵和北陵，相距三十里，地势险要。
夏后皋：夏代君主，名皋，夏桀的祖父。后：国君。
尔骨：你的尸骨，焉：在那里。', '秦国大夫杞子从郑国派人向秦国报告说：“郑国人让我掌管他们国都北门的钥匙，如果悄悄派兵前来，就可以占领他们的国都。”秦穆公向秦国老臣蹇叔征求意见。蹇叔说：“让军队辛勤劳苦地偷袭远方的国家，我从没听说有过。军队辛劳精疲力竭，远方国家的君主又有防备，这样做恐怕不行吧？军队的一举一动，郑国必定会知道。军队辛勤劳苦而一无所得，一定会产生叛逆念头。再说行军千里，有谁不知道呢？”秦穆公没有听从蹇叔的意见。他召见了孟明视，西乞术和白乙丙三位将领，让他们从东门外面出兵。蹇叔哭他们说：“孟明啊，我看着大军出发，却看不见他们回来了！”秦穆公派人对蹇叔说：“你知道什么？要是你蹇叔只活个中寿就去世的话，你坟上的树都有两手合抱一般粗了。”
蹇叔的儿子跟随军队一起出征，他哭着送儿子说：“晋国人必定在崤山抗击我军，崤有两座山头。南面的山头是夏王皋的坟墓，北面的山头是周文王避过风雨的地方。你们一定会战死在这两座山之间，我到那里收拾你的尸骨吧。”于是秦国军队东行。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1ce03572034f65a9abb", "shortContent": "鲁僖公三十三年（前627），在晋国发生了著名的殽之战。使后世人们得以了解这场战争始末的，就是记事散文《秦晋殽之战》。\n提起战争，似乎就意味着厮杀；许多记述战争的文字也大都写了这些。《秦晋殽之战》不然，它没有一处从正面描述这次大战，只写了这样一些场景：\n晋文公显灵。公元前628年冬天，晋文公死了。移灵出国都绛的时候，忽然棺材里发出如牛的吼声。卜筮之官名偃的立即叫众大臣拜伏在地，说：“君命大事，将有西...", "authors": ["张", "敏"], "pressName": "上海辞书出版社"}]', '', 'indent', 1575370417, '5de5ce2f43c25700685c40aa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643651, '郑子家告赵宣子', NULL, 6, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '晋侯合诸侯于扈，平宋也。于是晋侯不见郑伯，以为贰于楚也。
郑子家使执讯而与之书，以告赵宣子曰：“寡君即位三年，召蔡侯而与之事君。九月，蔡侯入于敝邑以行，敝邑以侯宣多之难，寡君是以不得与蔡侯偕，十一月，克减侯宣多而随蔡侯以朝于执事。十二年六月，归生佐寡君之嫡夷，以请陈侯于楚而朝诸君。十四年七月寡君又朝，以蒇陈事。十五年五月，陈侯自敝邑往朝于君。往年正月，烛之武往朝夷也。八月，寡君又往朝。以陈蔡之密迩于楚，而不敢贰焉，则敝邑之故也。虽敝邑之事君，何以不免？在位之中，一朝于襄，而再见于君，夷与孤之二三臣，相及于绛。虽我小国，则蔑以过之矣。今大国曰：‘尔未逞吾志。’敝邑有亡，无以加焉。古人有言曰：‘畏首畏尾，身其余几？’又曰：‘鹿死不择音。’小国之事大国也，德，则其人也；不德，则其鹿也。铤而走险，急何能择？命之罔极，亦知亡矣。将悉敝赋以待于鯈，唯执事命之。文公二年，朝于齐；四年，为齐侵蔡，亦获成于楚。居大国之间而从于强令，岂有罪也？大国若弗图，无所逃命。”
晋巩朔行成于郑，赵穿、公婿池为质焉。', '本文出自《左传·文公十七年》。', '晋侯：指晋国国君晋灵公。
扈：郑国城邑，故地在今河南原阳县。
郑伯：指郑国国君郑穆公。
子家：郑国公子，大夫。
执讯：掌管通讯联络的官。
赵宣子：晋国卿大夫赵盾。
蔡侯：指蔡庄公。
侯宣多：郑国大夫，因立郑穆公有功，所以侍宠专权作乱。
归生：即子家，归生是其名子是字。
夷：郑国太子。
陈侯：陈国君主共公，名朔。
蒇（chǎn）：完成。
陈侯：陈灵公，名平公，即陈共公之位。
孤：指郑国国君。
绛：晋国都城，在今山西新绛县。
蔑：同“荫”。
赋：指兵，古代按田赋出兵，所以称赋。
鯈（tiáo）：晋，郑交界的地方。
成：讲和修好。
巩朔：晋大夫。
赵穿：晋国执政大夫。
池：晋灵公的女婿。', '晋灵公召集各国诸侯在郑国的扈地会合，目的是要与宋国谈和。当时晋灵公拒绝与郑穆公见面，认为郑国既服从晋国又投靠楚国。
郑国大夫子家就派一位送信的官员到晋国送了一封信，信写给赵盾，信中说：“我们君主即位的第三年，就邀请蔡庄公一起服从你们君主。这年九月，蔡庄公来到我国准备同我们国君一起去晋国，但因为我国发生了侯宣多恃宠专权的患难，我们君主因此而不能与蔡庄公一起去。这年十一月，战胜灭绝了侯宣多，我们君主就与蔡庄公相随朝见服事于你这位执政。我们君主即位后第十二年六月，归生辅佐我们君主的太子夷，为了向楚国请求他们与陈灵公讲和，特地去朝见了你们君主。十四年七月，我们君主又以完成了陈国的事情朝见你们。十五年五月，陈灵公从我国去朝见你们君主。去年正月，烛之武去，陪同太子夷去朝见你们。八月，我们君主又去。作为陈、蔡，与楚国如此亲密相近，却不敢投靠楚国，那是有我们的缘故。虽然我们如此对待贵国君主，却为何不免得到你们的责罚呢？你们在位的君主当中，我们朝见过晋襄公一次，而朝见过在位君主两次。太子夷与我们国君的一些臣僚一个接一个地去到绛都。虽则我们是小国，这样做也没有哪个国家能超过了吧。现在你作为大国说：‘你们还做得不快我们的心意。’我国要像这么被要求就只有灭亡，再不能增加什么了。古人有言说：‘头也害怕尾也害怕，留下身子还能剩余多少不害怕呢？’又说：‘鹿要死也就不管自己的声音了。’小国服侍大国，大国以仁德对待它，它就是人；不用仁德对待它，它就是一只鹿，着急了就会疾速走入险境，着急了还能选择吗？大国无准则地下命令，我们也知道要灭亡了，只能把我国的全部军资集中起来在鯈地等待了，任凭你执政命令我们吧。我们文公即位的第二年六月壬申，到齐国朝见。四年二月壬戌，因为齐国侵伐蔡国，我们也只得与楚国谈和。处在大国之间，都要求我们服从强者的命令，难道成了我们的罪过？你们大国如果不考虑这些，那我们就无处逃避性命了。”
赵盾看到信后派巩朔到郑国和谈，赵穿、公婿池也到郑国作了人质。', NULL, '', 'indent', 1575370782, '5de5cf9b844bb40071eea76e', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643652, '王孙满对楚子', NULL, 4, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '楚子伐陆浑之戎，遂至于雒，观兵于周疆。定王使王孙满劳楚子。楚子问鼎之大小轻重焉。
对曰：“在德不在鼎。昔夏之方有德也，远方图物，贡金九牧，铸鼎象物，百物而为之备，使民知神奸。故民入川泽山林，不逢不若。螭魅罔两，莫能逢之。用能协于上下，以承天休。桀有昏德，鼎迁于商，载祀六百。商纣暴虐，鼎迁于周。德之休明，虽小，重也。其奸回昏乱，虽大，轻也。天祚明德，有所底止。成王定鼎于郏鄏，卜世三十，卜年七百，天所命也。周德虽衰，天命未改。鼎之轻重，未可问也。”', '本文出自《左传·宣公三年》。', '王孙满：周大夫，周共王的玄孙。对：回答。楚子：楚庄王，公元前613年至前591年在位。
陆浑之戎：古戎人的一支。也叫允姓之戎。原在秦晋的西北，春秋时，被秦晋诱迫，迁到伊川（今河南伊河流域），周景王二十年（公元前525年）为晋所并。雒（luò）：指雒水，今作洛水。发源于陕西，经河南流入黄河。观兵：检阅军队以显示军威。疆：边境。
定王：襄王的孙子，名瑜，周朝第二十一位王，公元前606年至前586年在位。劳：慰劳。
鼎：即九鼎。相传夏禹收九牧所贡金铸成九个大鼎，象征九州，三代时奉为传国之宝，也是王权的象征。楚庄王问鼎的大小轻重，反映他对王权的觊觎。
图：画。贡：把物品进献给天子。金：指青铜。九牧：即九州。传说古代把天下分为九州，州的长官叫牧。贡金九牧，是“九牧贡金”的倒装，犹言天下贡金。铸鼎象物：用九州的贡金铸成鼎，把画下来的各种东西的图象铸在鼎上。百物；万物。备：具备神奸：鬼神怪异之物。
不逢不若：不会遇到不顺的东西。逢，遇。若，顺，顺从。
螭魅（chi mèi）：也作“魑魅”。传说山林里能害人的妖怪。罔两（wǎng liǎng）：传说中河川里的精怪。
用：因。协：和协。休：荫庇，保佑。
昏德：昏乱的行为。祀：年。与“载”同义。
德之休明：犹言德若休明。休明，美善光明。
奸回；奸恶邪僻。
祚（zuò）：赐福，保佑。明德：美德。这里指明德的人。止：限度，极限。
成王：周成王。定鼎：定都。九鼎为古代传国的重器，王都所在，即鼎之所在。郏鄏（jiá rǔ）：地名。周王城所在，在今河南洛阳市西。卜世（bǔ）：谓预卜周朝能传至几代。卜，占卜。古人用火灼龟甲，根据灼开的裂纹来预测未来吉凶。世，父子相继为一世。卜年：谓所得之年。', '楚庄王攻打陆浑之戎，于是来到雒水，在周朝的疆界内检阅军队。周定王派王孙满去慰劳楚庄王。楚庄王问起九鼎的大小轻重。
王孙满回答说：“这决定于君主的德行而不在于鼎的本身。往昔夏朝开始实行德政的时候，远方的人们把各种事物都绘制成图像，九州的长官贡献了铜，铸成九鼎，把各种奇形异状的神怪图像都铸在鼎上，万物皆备，让人民认识神物与妖怪。因此，人民进入川泽山林，就不会碰上有危害的东西。山林水泽中的妖怪，都不会遇上。因而能使上上下下的人们和睦相处，以承受上天的保佑。夏桀德行败坏昏乱，九鼎迁移到商朝，经历了六百年。商纣王暴虐无道，九鼎又迁到周朝。德行如果美好光明，鼎虽小，分量却很重；如果奸邪昏乱，鼎虽大，分量也是轻的。上天赐福给有美德的人，总有终止的日子。成王把九鼎固定在郏鄏，占卜的结果是传世三十代，享国七百年，这是天命所决定的。周朝的德行虽然衰减了，天命并没有改变。九鼎的轻重，是不能问的。”', NULL, '', 'indent', 1575372400, '5de5d5ee546eaa0071ec5f5d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643653, '齐国佐不辱命', NULL, 3, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '晋师从齐师，入自丘舆，击马陉。
齐侯使宾媚人赂以纪甗、玉磬与地。“不可，则听客之所为。”
宾媚人致赂，晋人不可，曰：“必以肖同叔子为质，而使齐之封内尽东其亩。”对曰：“肖同叔子非他，寡君之母也；若以匹敌，则亦晋君之母也。吾子布大命于诸侯，而曰必质其母以为信，其若王命何？且是以不孝令也。诗曰：‘孝子不匮，永锡尔类。’若以不孝令于诸侯，其无乃非德类也乎？先王疆理天下，物土之宜，而布其利。故诗曰：‘我疆我理，南东其亩。’今吾子疆理诸侯，而曰‘尽东其亩’而已；唯吾子戎车是利，无顾土宜，其无乃非先王之命也乎？反先王则不义，何以为盟主？其晋实有阙。四王之王也，树德而济同欲焉；五伯之霸也，勤而抚之，以役王命；今吾子求合诸侯，以逞无疆之欲。诗曰：‘布政优优，百禄是遒。’子实不优，而弃百禄，诸侯何害焉？不然，寡君之命使臣，则有辞矣。曰‘子以君师辱于敝邑，不腆敝赋，以犒从者；畏君之震，师徒桡败。吾子惠徼齐国之福，不泯其社稷，使继旧好，唯是先君之敝器、土地不敢爱。子又不许，请收合馀烬，背城借一。敝邑之幸，亦云从也；况其不幸，敢不唯命是听？’”', '本文出自《左传·成公二年》。晋齐鞌之战齐军败绩，齐国佐奉命出使求和，但面对郤克的苛刻条件，他从容不迫逐条驳斥，并且用齐顷公的口气——虽然国君已经交代有最后的底线，但并未如此明晰地表态齐国尚愿一搏——若无和解的可能，则破釜沉舟奉陪到底！这十足底气，只能源于齐国的实力。这是国佐​外交最坚实的后盾。但是他说辞的逻辑无懈可击，果然是不辱使命！', '丘舆：地名，齐国境内，在今山东益都县内。
马陉（xíng）：地名，齐邑名，在益都县的西南。
宾媚人：齐国上卿，即国佐。赂：赠送财物。甗（yǎn）：陶器，甑的一种，是一种礼器。玉磬：乐器。纪：古国名。为齐所灭。纪甗玉磬，是齐灭纪时所得到的珍宝。
肖同叔子：肖，小国名；同叔：国王的名称；子，女儿。萧君同叔的女儿，即齐顷公的母亲。
封内：国境内。尽东其亩：田地垄亩全改为东西向，道路沟渠也相应地变为东西向，因为齐、晋东西相邻，这样一改，以后晋国的兵车过入齐境便于通行。古代田亩制，一亩宽一步，长百步，有东西向和南北向的不同。
王命：先王以孝治天下的遗命。先王，已去世的君王。
疆理：指划分疆界和沟渠小路。
阙：缺点，过失。
四王：指夏禹、商汤、周文王和周武王。
济：满足的意思。同欲：共同的欲望。
五伯（bà）：五伯之称有二：有三代之五伯，有春秋之五伯。《左传·成公二年》，齐国佐曰：“五伯之霸也，勤而抚之，以役王命。”杜元凯云：“夏伯昆吾，商伯大彭、豕韦，周伯齐桓、晋文。”《孟子》：“五霸者，三王之罪人也。”赵台卿注：“齐桓、晋文、秦缪、宋襄、楚庄。”二说不同。据国佐对晋人言，其时楚庄之卒甫二年，不当遂列为五。
役王命：从事于王命。
优优：和缓宽大的样子。百禄：百福，百种福禄。遒：聚。
辞：言词，话。
腆（tiǎn）：丰厚。
桡（ráo）：弯曲，屈从
徼（yāo）：求取，招致
烬：火灰。余烬：指残余的军队。
背城借一：背靠着城，再打一仗。意即在城下决一死战。', '晋军追赶齐军，从丘舆进入齐国境内，攻打马陉。
齐顷公派宾媚人将纪国的炊器、玉磐赠送给晋国，并归还鲁、卫两国的土地。“不行，就任凭他们所为。”
宾媚人送上礼物，晋国人郤克不答应，说：“必须以萧同叔的女儿做人质，同时使齐国境内的田亩全部改为东西向。”宾媚人回答说：“萧同叔的女儿不是别人，是敝国国君的母亲。如果以对等相待，也就是晋国国君的母亲。您向诸侯颁布天子的命令，却说一定要人家的母亲做人质作为凭信，将何以对天子之命？而且这是以不孝来命令诸侯。《诗经·大雅·既醉》说：‘孝子的心从不衰竭，永远赐福于你的同类。’如果以不孝命令诸侯，恐怕不是施恩德于同类吧？先王划定天下的疆界，治理天下的道路，河流，考察土性所宜而分派它们的利益。所以《诗经·小雅·信南山》说：‘我划定疆界，治理沟垄，朝南朝东修起田埂。’现在您划分和治理诸侯的土地，却说‘全部将田垄改为东西向’就完了，只顾有利于您的战车出入，不顾土性所宜，恐怕不是先王的遗命吧？违反先王就是不义，怎么做诸侯的领袖？恐怕晋国的确有过错。四王统一天下的时候，树立德行，帮助实现大家的共同愿望。五伯称霸诸侯的时候，勤劳王事，安抚诸侯，奉行天子的命令。现在您却谋求会合诸侯，以满足无止境的贪欲。《诗经·商颂·长发》说：‘施政宽和，百福聚集。’您实在不肯宽大，从而抛弃各种福禄，这对诸侯有什么害处呢？如果您不同意，敝国国君命令使臣，已有言辞在先了，说：‘您率领贵国国君的军队光临敝国，敝国以微薄的兵赋来犒劳您的随从。由于畏惧贵国国君的威严，军队遭到了挫败。承蒙您为求取齐国的福佑，不灭绝它的社稷，使它继续同贵国保持旧日的友好关系，敝国决不敢吝惜先君这些破旧的器物和土地。您又不答应。那就请允许我们收集残余，在敝国城下决一死战。即使敝国侥幸取胜，也要服从贵国；倘若不幸战败，敢不完全听从贵国的命令？’”', NULL, '', 'indent', 1575375181, '5de5e0cb5620710076a04505', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643761, '苏武传（节选）', NULL, 50, 136, 0, 6, '班固', NULL, 18080, '5830da0e2e958a0069d595a2', '汉', 'wen', '文', '', '', '武，字子卿。少以父任，兄弟并为郎。稍迁至栘中厩监。时汉连伐胡，数通使相窥观。匈奴留汉使郭吉、路充国等前后十余辈。匈奴使来，汉亦留之以相当。天汉元年，且鞮侯单于初立，恐汉袭之，乃曰：“汉天子我丈人行也。”尽归汉使路充国等。武帝嘉其义，乃遣武以中郎将使持节送匈奴使留在汉者，因厚赂单于，答其善意。武与副中郎将张胜及假吏常惠等募士斥候百余人俱。既至匈奴，置币遗单于；单于益骄，非汉所望也。
方欲发使送武等，会缑王与长水虞常等谋反匈奴中。缑王者，昆邪王姊子也，与昆邪王俱降汉；后随浞野侯没胡中，及卫律所将降者，阴相与谋劫单于母阏氏归汉。会武等至匈奴，虞常在汉时，素与副张胜相知，私候胜曰：“闻汉天子甚怨卫律，常能为汉伏弩射杀之，吾母与弟在汉，幸蒙其赏赐。”张胜许之，以货物与常。
后月余，单于出猎，独阏氏子弟在。虞常等七十余人欲发，其一人夜亡，告之。单于子弟发兵与战。缑王等皆死，虞常生得。单于使卫律治其事，张胜闻之，恐前语发，以状语武。武曰：“事如此，此必及我，见犯乃死，重负国！”欲自杀，胜、惠共止之。虞常果引张胜。单于怒，召诸贵人议，欲杀汉使者。左伊秩訾曰：“即谋单于，何以复加？宜皆降之。”
单于使卫律召武受辞。武谓惠等：“屈节辱命，虽生，何面目以归汉！”引佩刀自刺。卫律惊，自抱持武，驰召医。凿地为坎，置煴火，覆武其上，蹈其背以出血。武气绝，半日复息。惠等哭，舆归营。单于壮其节，朝夕遣人候问武，而收系张胜。
武益愈，单于使使晓武，会论虞常，欲因此时降武。剑斩虞常已，律曰：“汉使张胜谋杀单于近臣，当死。单于募降者赦罪。”举剑欲击之，胜请降。律谓武曰：“副有罪，当相坐。”武曰：“本无谋，又非亲属，何谓相坐？”复举剑拟之，武不动。律曰：“苏君，律前负汉归匈奴，幸蒙大恩，赐号称王。拥众数万，马畜弥山，富贵如此！苏君今日降，明日复然。空以身膏草野，谁复知之！”武不应。律曰：“君因我降，与君为兄弟；今不听吾计，后虽欲复见我，尚可得乎？”武骂律曰：“汝为人臣子，不顾恩义，畔主背亲，为降虏于蛮夷，何以女为见？且单于信女，使决人死生，不平心持正，反欲斗两主，观祸败。（南越杀汉使者，屠为九郡；宛王杀汉使者，头县北阙；朝鲜杀汉使者，即时诛灭。独匈奴未耳。）若知我不降明，欲令两国相攻，匈奴之祸，从我始矣。”
律知武终不可胁，白单于。单于愈益欲降之。乃幽武置大窖中，绝不饮食。天雨雪，武卧啮雪，与旃毛并咽之，数日不死。匈奴以为神，乃徙武北海上无人处，使牧羝。羝乳乃得归。别其官属常惠等各置他所。武既至海上，廪食不至，掘野鼠去草实而食之。杖汉节牧羊，卧起操持，节旄尽落。积五六年，单于弟于靬王弋射海上。武能网纺缴，檠弓弩，于靬王爱之，给其衣食。三岁余，王病，赐武马畜、服匿、穹庐。王死后，人众徙去。其冬，丁令盗武牛羊，武复穷厄。
初，武与李陵俱为侍中。武使匈奴，明年，陵降，不敢求武。久之，单于使陵至海上，为武置酒设乐。因谓武曰：“单于闻陵与子卿素厚，故使陵来说足下，虚心欲相待。终不得归汉，空自苦亡人之地，信义安所见乎？前长君为奉车，从至雍棫阳宫，扶辇下除，触柱折辕，劾大不敬，伏剑自刎，赐钱二百万以葬。孺卿从祠河东后土，宦骑与黄门驸马争船，推堕驸马河中溺死，宦骑亡。诏使孺卿逐捕，不得，惶恐饮药而死。来时太夫人已不幸，陵送葬至阳陵。子卿妇年少，闻已更嫁矣。独有女弟二人，两女一男，今复十余年，存亡不可知。人生如朝露，何久自苦如此！陵始降时，忽忽如狂，自痛负汉，加以老母系保宫。子卿不欲降，何以过陵？且陛下春秋高，法令亡常，大臣亡罪夷灭者数十家，安危不可知，子卿尚复谁为乎？愿听陵计，勿复有云！”武曰：“武父子亡功德，皆为陛下所成就，位列将，爵通侯，兄弟亲近，常愿肝脑涂地。今得杀身自效，虽蒙斧钺汤镬，诚甘乐之。臣事君，犹子事父也。子为父死，亡所恨，愿无复再言！”
陵与武饮数日，复曰：“子卿壹听陵言！”武曰：“自分已死久矣！王必欲降武，请毕今日之<马雚>，效死于前！”陵见其至诚，喟然叹曰：“嗟呼，义士！陵与卫律之罪上通于天！”因泣下霑衿，与武决去。
（陵恶自赐武，使其妻赐武牛羊数十头。后陵复至北海上，语武：“区脱捕得云中生口，言太守以下吏民皆白服，曰：『上崩。』”武闻之，南乡号哭，欧血，旦夕临数月。）
昭帝即位，数年，匈奴与汉和亲。汉求武等。匈奴诡言武死。后汉使复至匈奴，常惠请其守者与俱，得夜见汉使，具自陈道。教使者谓单于，言：“天子射上林中，得雁，足有系帛书，言武等在某泽中。”使者大喜，如惠语以让单于。单于视左右而惊，谢汉使曰：“武等实在。”
（于是李陵置酒贺武曰：“今足下还归，扬名于匈奴，功显于汉室，虽古竹帛所载，丹青所画，何以过子卿！陵虽驽怯，令汉且贳陵罪，全其老母，使得奋大辱之积志，庶几乎曹柯之盟。此陵宿昔之所不忘也！收族陵家，为世大戮，陵尚复何顾乎？已矣！令子卿知吾心耳！异域之人，壹别长绝！”陵起舞，歌曰：“径万里兮度沙幕，为君将兮奋匈奴。路穷绝兮矢刃摧，士众灭兮名已隤，老母已死，虽欲报恩将安归？”陵泣下数行，因与武决。）
单于召会武官属，前以降及物故，凡随武还者九人。武以始元六年春至京师。（诏武奉一太牢谒武帝园庙，拜为典属国，秩中二千石，赐钱二百万，公田二顷，宅一区。常惠徐圣赵终根皆拜为中郎，赐帛各二百匹。其余六人，老归家，赐钱人十万，复终身。常惠后至右将军，封列侯，自有传。）武留匈奴凡十九岁，始以强壮出，及还，须发尽白。', '《苏武传》是《汉书》中最出色的名篇之一，它记述了苏武出使匈奴，面对威胁利诱坚守节操，历尽艰辛而不辱使命的事迹，生动刻画了一个“富贵不能淫，威武不能屈”的爱国志士的光辉形象。作者采用写人物传记经常运用的纵式结构来组织文章，以顺叙为主，适当运用插叙的方法，依时间的先后进行叙述，脉络清晰，故事完整。文章大致分为三部分。
第一部分即文章的第1、2段，介绍了苏武的身世、出使的背景及原因。文章一开始写道：“时汉连伐胡，数通使相窥观。匈奴留汉使郭吉、路充国等前后十余辈。匈奴使来，汉亦留之以相当。”苏武出使匈奴的这一背景，表明苏武出使时的严酷历史环境，同时交代了匈奴尽管“尽归汉使路充国等”却只是因为“且鞮侯单于初立，恐汉袭之”的缓兵之计，并非真心和好。所以当汉武帝派苏武护送扣留在汉朝的匈奴使者还朝，并“厚赂单于”时，“单于益骄”，这也是后来单于悍然扣留苏武一行的原因。
第二部分即文章第3~7段，重点记述了苏武留胡十九年备受艰辛而坚持民族气节的事迹。这部分也是文章着力描写的部分，以精彩的笔墨描写了苏武反抗匈奴统治者招降的种种斗争情形。具体描写到匈奴招降共有三次：第一次是卫律软硬兼施想迫使苏武投降，被苏武正气凛然的怒斥所喝退，双方矛盾斗争激烈，场面紧张。接着写匈奴企图用艰苦的生活条件来消磨苏武的斗志，把他囚禁于地窖中，使他备受饥寒，接着流放苏武到荒无人烟的北海让他牧羊。然而在极端恶劣的环境中，苏武不可磨灭的爱国精神再一次粉碎了匈奴的险恶用心。他手握汉节──国家民族的象征，在九死一生中维持着一个使者的使命。这时斗争是相对缓和的，直接表现的是苏武与自然环境做斗争。第三次是故友李陵劝降。这段描写不但表现了苏武可贵的气节，同时也刻画了叛将李陵的复杂心态。他那尚未泯灭的爱国之情、羞恶之心在苏武的崇高境界面前被唤醒了，其内心剖白真实感人。李陵在劝苏武时曾说：“陛下春秋高，法令亡常，大臣亡罪夷灭者数十家”，这是作者借李陵之口表达对汉武帝动辄杀戮大臣的残忍行为的不满，也是《汉书》中少有的表现批判统治者的进步思想倾向之处。而苏武与李陵的对答针锋相对，波澜起伏，非常精彩，人物之声气跃然纸上。此处苏武的斗争对象是交情很深而今已是敌对阵营的故友，双方的心态都比较复杂，而作者的描写也很到位，是这部分最出彩之处。
第三部分即文章最后两段，介绍了苏武被放回国的经过。课文最后一句“留匈奴凡十九岁，始以强壮出，及还，须发尽白”，看似平实记述，细细品味却包含着作者诸多感情。人生不过百年，十九年何其太长！苏武“强壮出”，出使时正当壮年，及回归故国时已是“须发尽白”，一生大好时光都在煎熬中过去了，作者的叹惋之情溢于言表，而能为信念坚执如此确实令人敬佩！幸而虽历尽磨难，终于完成了使者的任务，维护了国家尊严，保持了民族气节，且荣归故里，作者欣慰之感也显而易见。可以说这句表达的是作者与读者共同的心声。
为了表现苏武的性格、气节及始终不渝的爱国精神，文章在记“行”时又着力于环境及细节的描写。如苏武自刺一节，被置于地坎温火之上，“蹈背出血，气绝复苏”，充满悲壮色彩。而周围人的反应是“卫律惊，自抱持武”“惠等哭，舆归营”“单于壮其节”。这一惊、一哭、一壮的细节描写充分衬托出苏武的铮铮铁骨及高尚情操。文章语言千锤百炼，俭省精净，刻画人物入骨三分，将史家笔法与文学语言较好地结合起来。
自从班固的《汉书》问世以后，苏武的英名就反复出现在历代的诗词、散文、辞赋、戏曲、小说之中。他的感天地、泣鬼神的爱国主义精神，一直为人们所称道。《苏武传》附见于《汉书·李广苏建传》。《李广传》基本上照录《史记·李将军列传》，《苏建传》只有短短几行，而《苏武传》则是班固倾全力为之的。在《汉书》中，此传是最能显示班固塑造人物形象的艺术才华的优秀篇章之一。
全文共有十八个小节，外加一个赞语。按苏武一生经历的主要关节，大致可以划为三个部分。第一部分是第一、二两小节，写苏武奉命出使匈奴，以通和好。第二部分共十二小节，写苏武在匈奴遇到意外情况而被扣留及后被放回的经过。第三部分共四小节，写苏武返汉以后受尊宠的情形。赞语主要表彰苏武的崇高品质。
苏武的出使，正当汉朝与匈奴的关系有所改善、两国矛盾有所缓和的时期。匈奴方面先做出友好姿态，把以往扣留的汉朝使臣全部放回。汉武帝为了答谢匈奴方面的好意，也采取了同样的行动，派苏武护送以往扣留在汉朝的匈奴使臣回国。按常情而言，苏武是一个和平使者。他的出使应该是愉快而顺利的，但事情的发展却出乎意料。当时，匈奴恰巧发生了一次情节严重的谋反事件。谋反者的首领缑王计划绑架匈奴单于的母亲阏氏，投奔汉朝。谋反者的另一首领虞常原是汉臣，他企图刺杀叛汉降敌、当了匈奴大臣的卫律。他把这个想法告诉了副使张胜。张胜没有向苏武报告，私下支持他们的行动。从国家关系上说，张胜的做法损害了汉朝的信义，有悖于两国通好的宗旨，使汉使处于理亏的地位。虞常曾对张胜说：“闻汉天子甚怨卫律，常能为汉伏弩射杀之。吾母与弟在汉，幸蒙其赏赐。”可见其出发点并不是真正爱国。缑王原是归附汉朝的匈奴贵族，他重新陷没匈奴中是因为汉武帝派他随浞野侯赵破奴去接应左大都尉。左大都尉是匈奴贵人，他企图刺杀单于降汉。单于及时粉碎了这一阴谋，并发兵俘获了赵破奴的军队。这些不愉快的往事，本该随着两国关系的改善而不再重演，但缑王的思想没有跟上形势的发展，仍然重复上一次的冒险行动，结果兵败被杀，虞常被生擒。事态的发展，不可避免地牵涉到了汉朝的使臣。苏武遇到了一道事先没有想到的难题，而作者正是抓住了苏武在解决这道难题的过程中的表现，刻画了他的光辉形象。
首先，通过苏武以死报国的行动，刻画了他刚烈难犯、义不受辱的坚强个性。苏武是将门之子，禀性刚烈，视死如归。他知道，自己是汉朝使臣，使臣受辱，就是国家受辱，所以当他听到张胜报告以后，立即说：“事如此，此必及我。见犯乃死，重负国。”在严重关头，不是考虑个人的得失，而是立即想到如何才能不辜负国家的重托。“重负国”三字含意很深。不能预先发现和劝阻张胜所干的错事，一负国；马上要受到敌国的审讯，给国家丢脸，二负国。这是严于责己之意。对于私自种下祸胎的张胜来说，苏武的话中还包含着什么意思，心里不会不清楚，但他却像常惠一样来劝阻苏武自杀。苏武明白，这场乱子必须由他单独来收拾了，因此只好暂时不死。暂时不死，并不是贪生怕死，而是说明他在“死”的问题上还要权衡，究竟如何“死”才能对国家有利。在卫律开庭审讯的场合，苏武对常惠说：“屈节辱命，虽生，何面目以归汉？”这句话有三层意思：一是表白自己没有参与匈奴的谋反事件，而且也不赞成有人这样做；二是表明汉廷没有指使他们这样做；三是教育副使张胜不要贪生怕死。在说过这番话以后再引刀自刺，情况就不同了。他自杀的行动，大大增强了说话的分量。不仅足以为国雪耻，扭转外交上的被动局面，而且还赢得了敌国的尊敬。这从后来“单于壮其节，朝夕遣人候问武”可以看出。他把本来可能会导致国与国之间发生误解与争端的危机大大缩小了。匈奴单独“收系张胜”一事，说明匈奴方面已经明白了事情的真相。
其次，通过两次劝降，突出了苏武不受威逼利诱，对国家、民族忠贞不贰的崇高气节。按理说，汉朝方面既然没有指使苏武等人参与匈奴国中的谋反事件，预知此事的仅是副使张胜一人，这纯粹属于他个人的错误行为，匈奴方面应该单独留下张胜治罪，而把苏武等人遣送回国才是。遗憾的是匈奴违背了两国通好的宗旨，粗暴地把苏武等人一概扣留，而且要强迫他们投降，企图以此来羞辱汉朝。这时，理屈的已经不是在苏武方面，而是在匈奴方面。苏武面临着新的严峻考验：坚持民族气节，拒绝投降，就能为国争光；丧失民族气节，接受投降，必然给祖国丢脸。苏武坚定地选择了前者。为了让匈奴知道汉使的骨头有多硬，他不再考虑死，而是要千方百计地活下去。匈奴对苏武的劝降使尽了解数。第一次让卫律出面。卫律使用的方法比较拙劣。一是威吓。先将虞常斩首，造成恐怖气氛，然后胁迫张胜投降，最后硬说副使有罪，正使应该连坐，遭到苏武驳斥后，“复举剑拟之”。想把苏武一举吓软，但苏武不为所动，威吓的伎俩遂告破产。二是利诱。卫律恬不知耻地炫耀自己投降匈奴后封王赐爵、拥众数万、马畜弥山的所谓“富贵”，并说“苏君今日降，明日复然”。苏武则不屑一顾，置之不理。利诱的一招也随之失灵。三是逼迫。卫律见苏武不应，以为被说动了心，便进而逼迫说：“今不听吾计，后虽欲复见我，尚可得乎？”苏武对此人头畜鸣的叛国者的丑恶表演实在无法保持沉默，终于狠狠地骂了他一通。卫律黔驴技穷，终于认输。第二次由李陵出面。李陵使用的方法比较高明。他是以老朋友叙旧的方式进行的，着重于从感情上去软化苏武。他的谈话内容，要点有三。一是极力挑拨苏武与汉武帝之间的感情，诉说苏武的兄长苏嘉和弟弟苏贤被汉武帝逼死的经过，又说汉武帝“法令亡常”，“大臣亡罪夷灭者数十家”，即使活着回去，也“安危不可知”。言外之意是说，汉武帝对不起苏家，又年老昏庸，不值得效忠。二是把苏武母亲去世、妻子改嫁的消息告诉他，又诡称苏武在汉朝的两女一男“存亡不可知”（事实上苏武的男孩当时未亡），断绝他对妻儿家室的想念之情。三是宣扬叛徒哲学：“人生如朝露，何久自苦如此！”其时苏武久处绝域，对来自国内的消息当然是喜欢听的。李陵向他介绍国内情形和家庭状况，正好迎合了苏武的心理，加上言词娓娓动听，感情色彩很浓，因此极易摧毁一个人的意志，但苏武仍不为所动。他除了针对李陵挑拨君臣关系作了必要的义正辞严的答复之外，其余一概不理。当李陵再要饶舌的时候，苏武立即以死相拒，并称李陵为“王”（李陵当时封右校王），一下子揭去了朋友间叙旧谈心的幌子，终于使李陵羞愧交加，无法再谈。第三，通过艰苦考验的描写，表现了苏武坚韧不拔、历久不磨的爱国意志。苏武在匈奴的十九年，从生活方面说，可谓艰苦备尝。幽闭大窖时期，断绝饮食数天，苏武啮雪吞旃，顽强地活下来了。迁至北海时期，断绝粮食供应，苏武掘鼠挖草，又顽强地活下来了。从精神方面说，可谓受尽折磨。先是单独监禁，后又单身流放到无人之地，这已经是够残酷的了，何况又被判处终身流放：“使牧羝，羝乳乃得归。”但苏武仍然顽强地活下来了。从遭遇方面说，可谓步步坎坷。好不容易地受到於靬王的赏识，过了三年温饱的日子，而於靬王又偏偏短命而亡，卫律又指使人把苏武的牛羊抢劫一空。尽管如此，苏武仍然顽强地活下来了。作者特意点出苏武在最困难的时候始终“杖汉节牧羊，卧起操持，节旄尽落”。这就告诉读者，强烈的爱国心是苏武借以战胜困难的力量源泉。
坚强个性、民族气节、爱国意志三个方面是构成苏武形象的主要特征。作者在刻画这些特征时颇费艺术匠心。
首先是剪裁得法。范晔称赞班固“文赡而事详”，“详而有体”（《后汉书·班固传论》），很为中肯。本文详叙苏武出使匈奴被扣留的曲折经历而略叙回国以后的事迹，这有利于突出苏武的爱国主义精神。苏武在匈奴一共十九年，作者对这十九年的生活也没有采用编年纪的方式来描写，而是详写匈奴方面劝降、逼降和苏武的拒降。至于苏武在匈奴娶胡妇生子的事情只在文章的后半部分略提一笔。这同样有利于突出苏武的爱国主义精神。在略写的第三部分，作者也不是一味简略，对于苏武身后得以画图麒麟阁的荣宠就写得很详细。由此可见，本文不仅做到了详其所当详，略其所当略，而且详中有略，略中有详，充分显示了作者在剪裁方面的精思。
其次是对比鲜明。本文安排的对比主要有这样几处：一是与张胜对比。作者写张胜的见利忘义、丧失骨气，衬托了苏武的深明大义和富于骨气；写张胜的遇事束手无策，对国家不负责任，衬托了苏武的临事不惧、对国家高度负责。二是与卫律对比。作者暴露了卫律卖国求荣的可鄙的内心世界，这就更加突出了苏武的崇高的民族气节。三是与李陵对比。李陵善于伪装。他装出满肚子委曲的样子，极力埋怨汉武帝对待臣下太刻薄。宋代吕祖谦曾经指出：“当陵之海上说苏武，陵母固未诛也，而激切捭阖，指斥汉失，若必欲降武者，则此言岂可尽信哉！”（《汉书评林》引）尽管李陵后来又装出关心苏武生活的样子，赐以牛羊，但苏武确实没有相信他的话。李陵斤斤计较于一家一己的恩怨，置国家民族利益于不顾；而苏武则置一家一己的恩怨于不顾，一心一意为国家民族利益着想。两种思想，两种胸怀，有如天渊之别。李陵越说得委婉动听，就越显得渺小可鄙；苏武越沉默寡言，就越显得可敬可佩。事情发展到后来，连李陵自己前后的言行也构成了对比。开始时甘于充当一名无耻的说客，经与苏武多次交谈，方始认识到人间还有“羞耻”二字，不得不自讼道：“嗟乎，义士！陵与卫律之罪上通于天！”这是第一层对比。动员苏武投降时说得头头是道，及至看到苏武回国时又哭得哀哀欲绝。这是第二层对比。他终于认识到自己干了一件多么愚蠢的事情。对于变节者来说，只配忍辱偷生，悄悄地苟延残喘，但他连这点自由也没有，必须身不由己地去充当说客，结果是扮演了一个可怜虫的角色。当苏武的英名彪炳青史之时，正是他的叛国者的灵魂被公诸于世之日。在李陵饯别苏武的宴会上，苏武不会片言不发，但作者却不着苏武一语，只是淋漓尽致地刻画李陵悔恨、懊丧、羞惭的种种表现，对比的色彩异常鲜明。就苏武形象的塑造而言，这也可以说是“不着一字，尽得风流”，因为苏武的光辉形象已经栩栩如生地活现在读者的面前了。', '字注音
1.稍迁至栘（yí）中厩（jiù）监（jiàn）；
2.数（shuò）通使相窥（kuī）观；
3.汉天子，我丈人行（háng）也；
4.既至匈奴，置币遗（wèi）单（chán）于；
5.后随浞（zhuó）野侯没（mò）胡中；
6.阴相与谋，劫单于母阏（yān）氏（zhī）归汉；
7.置煴（yūn）火，覆武其上；
8.拥众数万，马畜（chù）弥山；
9.乃徙武北海上无人处，使牧羝（dī）；
10.毕今日之驩（huān）
11.天雨（yù）雪
12.缑（gōu）王者，昆（hún）邪（yé）王姊（zǐ）子也
13.佐伊秩訾（zǐ）曰
14.武卧啮（niè）雪
通假字
1.不顾恩义，畔主背亲畔：通“叛”，背叛。
2.与旃毛并咽之旃：通“毡”，毛织品。
3.掘野鼠去草实而食之去：通“弆（jǔ）”，收藏。
4.空自苦亡人之地亡：通“无”，没有。
5.信义安所见乎见：通“现”，显现。
6.法令亡常亡：通“无”，没有。
7.大臣亡罪夷灭者数十家亡：通“无”，没有。
8.武父子亡功德亡：通“无”，没有。
9.因泣下霑衿，与武决去：决：通“诀”，诀别。
10.前以降及物故以：通“已”，已经。
11.蹈其背以出血蹈：通“掏”，叩，轻轻敲打
12.毕今日之驩驩：通“欢”。
古今异义
1.汉亦留之以相当。相当：古义：抵押。今义：差不多。
2.皆为陛下所成就。成就：古义：提拔。今义：业绩。
3.我丈人行也。丈人：古义：老人，长辈。今义：岳父。
4.幸蒙其赏赐。赏赐：古义：照顾。今义：奖赏物品。
5.欲因此时降武。因此：古义：趁这时。今义：因为这个。
6.独有女弟二人。女弟：古义：妹妹。今义：姐姐（妹妹）和弟弟。
7.且陛下春秋高。春秋：古义：年纪。今义：春秋战国时期或指季节。
8.武等实在。实在：古义：确实存在。今义：诚实、老实。
9.稍迁至栘中厩监。稍：古义：渐渐。今义：稍微。
10.既至匈奴，置币遗单于。遗：古义：送给。今义：丢失、落下。
11.会缑王与长水虞常等谋反匈奴中。会：古义：正当、适逢。今义：聚会、集合。
12.此必及我。及：古义：牵连今义：常作连词“和”用
13.会论虞常。论：古义：判罪今义：常作议论
14.以货物与常。货物：古义：财物今义：指供出售的物品
15.卧起操持。操持：古义：为操和持，两个词，“拿着“的意思今义:料理，办理/筹划
16.假吏常惠等募士斥候百余人俱。假：古义：临时充任今义：虚假
17.来时太夫人已不幸。不幸：古义：对去世的委婉说法。今义：指灾祸
18.明年，陵降，不敢求武。明年：古义：第二年。今义：后一年。
词类活用
①意动用法
单于壮其节壮：以……为壮。
诚甘乐之乐：以……为乐。
②使动用法
（1）欲因此时降武降：使……投降。
（2）空以身膏草野膏：使……肥沃。
（3）反欲斗两主斗：使……争斗。
（4）单于愈益欲降之降：使……投降。
（5）何久自苦如此苦：使……受苦。
（6）王必欲降武降：，使……投降。
（7）尽归汉使路充国等归：使……归
（8）屈节辱命屈：使……屈身辱：使……受辱
（9）别其官署常惠等别：使……分开
（10）宜皆降之降：使......投降
③名词活用
（1）天雨雪雨：名词做动词，下雨。
（2）羝乳乃得归乳：名词做动词，生子。
（3）杖汉节牧羊杖：名词做动词，拄着。
（4）武能网纺缴，檠弓弩网、檠：名词做动词，结网、用檠矫正弓弩。
（5）惠等哭，舆归营舆：名词做动词，用车子。
（6）陵与卫律之罪，上通于天上：名词做状语，向上。
（7）绝不饮食饮食：名词做动词，给他吃的、喝的。
一词多义
①使
（1）数通使相窥观使：使者。
（2）乃遣武以中郎将使持节送匈奴使留汉者第一个“使”：出使。第二个“使”：使节
（3）单于使使晓武第一个“使”：派，第二个“使”：使者。
②语
（1）以状语武语：告诉。
（2）如惠语以让单于语：说的话。
③引
（1）虞常果引张胜引：招供。
（2）引佩刀自刺引：拔。
④食
（1）绝不饮食食：给他吃的。
（2）掘野鼠去草实而食之食：吃。
（3）廪食不至食：粮食。
（4）给其衣食食：食物。
⑤发
（1）方欲发使送武等发：打发。
（2）虞常等七十余人欲发发：发动。
（3）恐前语发发：被揭发。
（4）须发尽白发：头发
⑥乃
⑴见犯乃死，重负国乃：副词，才
⑵恐汉袭之，乃曰乃：副词，于是、就
⑦以
（1）武字子卿，少以父任以：因为凭借
（2）汉亦留之以相当以：来表承接
（3）张胜许之，以货物与常以：把
（4）以状语武以：把
（5）虽生，何面目以归汉！以：凭借
（6）蹈其背以出血以：来表顺承
特殊句式
①倒置句
（1）送匈奴使留在汉者。定语后置句，正常语序“送留在汉者匈奴使”。
（2）为降虏于蛮夷。状语后置句，正常语序“于蛮夷为降虏”。
（3）何以汝为见。宾语前置句和介宾倒置句，正常语序“以何见汝为”
（4）子卿尚复谁为乎。宾语前置句，正常语序“子卿尚复为谁乎”。
（5）何以复加。介宾倒置句，正常语序“以何复加”。
（6）募士、斥候百余人俱。定语后置句，正常语序“募百余人士、斥候俱”
（7）若知我不降明。状语后置句，正常语序“若明知我不降”
②判断句
（1）缑王者，昆邪王姊子也。
（2）非汉所望也。
（3）汉天子，我丈人行也。
③被动句
（1）见犯乃死，重负国
（2）大臣亡罪夷灭者数十家
（3）皆为陛下所成就
（4）缑王等皆死，虞常生得
（5）武留匈奴凡十九岁
④省略句
（1）后随浞野侯没胡中
（2）单于子弟发兵于战
（3）使牧羝
（4）会缑（gōu）王与长水虞常等谋反匈奴中。
（5）且单于信汝，使决人死生。', '苏武字子卿，年轻时凭着父亲的职位，兄弟三人都做了皇帝的侍从，并逐渐被提升为掌管皇帝鞍马鹰犬射猎工具的官。当时汉朝廷不断讨伐匈奴，多次互派使节彼此暗中侦察。匈奴扣留了汉使节郭吉、路充国等前后十余批人。匈奴使节前来，汉朝庭也扣留他们以相抵。公元前100年，且鞮刚刚立为单于，唯恐受到汉的袭击，于是说：“汉皇帝，是我的长辈。”全部送还了汉廷使节路充国等人。汉武帝赞许他这种通晓情理的做法，于是派遣苏武以中郎将的身份出使，持旄节护送扣留在汉的匈奴使者回国，顺便送给单于很丰厚的礼物，以答谢他的好意。
苏武同副中郎将张胜以及临时委派的使臣属官常惠等，加上招募来的士卒、侦察人员百多人一同前往。到了匈奴那里，摆列财物赠给单于。单于越发傲慢，不是汉所期望的那样。单于正要派使者护送苏武等人归汉，适逢缑王与长水人虞常等人在匈奴内部谋反。缑王是昆邪王姐姐的儿子，与昆邪王一起降汉，后来又跟随浞野侯赵破奴重新陷胡地，在卫律统率的那些投降者中，暗中共同策划绑架单于的母亲阏氏归汉。正好碰上苏武等人到匈奴。虞常在汉的时候，一向与副使张胜有交往，私下拜访张胜，说：“听说汉天子很怨恨卫律，我虞常能为汉廷埋伏弩弓将他射死。我的母亲与弟弟都在汉，希望受到汉廷的照顾。”张胜许诺了他，把财物送给了虞常。一个多月后，单于外出打猎，只有阏氏和单于的子弟在家。虞常等七十余人将要起事，其中一人夜晚逃走，把他们的计划报告了阏氏及其子弟。单于子弟发兵与他们交战，缑王等都战死；虞常被活捉。
单于派卫律审处这一案件。张胜听到这个消息，担心他和虞常私下所说的那些话被揭发，便把事情经过告诉了苏武。苏武说：“事情到了如此地步，这样一定会牵连到我们。受到侮辱才去死，更对不起国家！”因此想自杀。张胜、常惠一起制止了他。虞常果然供出了张胜。单于大怒，召集许多贵族前来商议，想杀掉汉使者。左伊秩訾说：“假如是谋杀单于，又用什么更严的刑法呢？应当都叫他们投降。”单于派卫律召唤苏武来受审讯。苏武对常惠说：“丧失气节、玷辱使命，即使活着，还有什么脸面回到汉廷去呢！”说着拔出佩带的刀自刎，卫律大吃一惊，自己抱住、扶好苏武，派人骑快马去找医生。医生在地上挖一个坑，在坑中点燃微火，然后把苏武脸朝下放在坑上，轻轻地敲打他的背部，让淤血流出来。苏武本来已经断了气，这样过了好半天才重新呼吸。常惠等人哭泣着，用车子把苏武拉回营帐。单于钦佩苏武的节操，早晚派人探望、询问苏武，而把张胜逮捕监禁起来。
苏武的伤势逐渐好了。单于派使者通知苏武，一起来审处虞常，想借这个机会使苏武投降。剑斩虞常后，卫律说：“汉使张胜，谋杀单于亲近的大臣，应当处死。单于招降的人，赦免他们的罪。”举剑要击杀张胜，张胜请求投降。卫律对苏武说：“副使有罪，应该连坐到你。”苏武说：“我本来就没有参予谋划，又不是他的亲属，怎么谈得上连坐？”卫律又举剑对准苏武，苏武岿然不动。卫律说：“苏君！我卫律以前背弃汉廷，归顺匈奴，幸运地受到单于的大恩，赐我爵号，让我称王；拥有奴隶数万、马和其他牲畜满山，如此富贵！苏君你今日投降，明日也是这样。白白地用身体给草地做肥料，又有谁知道你呢！”苏武毫无反应。卫律说：“你顺着我而投降，我与你结为兄弟；今天不听我的安排，以后再想见我，还能得到机会吗？”苏武痛骂卫律说：“你做人家的臣下和儿子，不顾及恩德义理，背叛皇上、抛弃亲人，在异族那里做投降的奴隶，我为什么要见你！况且单于信任你，让你决定别人的死活，而你却居心不平，不主持公道，反而想要使汉皇帝和匈奴单于二主相斗，旁观两国的灾祸和损失！南越王杀汉使者，结果九郡被平定。宛王杀汉使者，自己头颅被悬挂在宫殿的北门。朝鲜王杀汉使者，随即被讨平。唯独匈奴未受惩罚。你明知道我决不会投降，想要使汉和匈奴互相攻打。匈奴灭亡的灾祸，将从我开始了！”卫律知道苏武终究不可胁迫投降，报告了单于。单于越发想要使他投降，就把苏武囚禁起来，放在大地窖里面，不给他喝的吃的。天下雪，苏武卧着嚼雪，同毡毛一起吞下充饥，几日不死。匈奴以为神奇，就把苏武迁移到北海边没有人的地方，让他放牧公羊，说等到公羊生了小羊才得归汉。同时把他的部下及其随从人员常惠等分别安置到别的地方。
苏武迁移到北海后，粮食运不到，只能掘取野鼠所储藏的野生果实来吃。他拄着汉廷的符节牧羊，睡觉、起来都拿着，以致系在节上的牦牛尾毛全部脱尽。一共过了五、六年，单于的弟弟於靬王到北海上打猎。苏武会编结打猎的网，矫正弓弩，於靬王颇器重他，供给他衣服、食品。三年多过后，於靬王得病，赐给苏武马匹和牲畜、盛酒酪的瓦器、圆顶的毡帐篷。王死后，他的部下也都迁离。这年冬天，丁令人盗去了苏武的牛羊，苏武又陷入穷困。
当初，苏武与李陵都为侍中。苏武出使匈奴的第二年，李陵投降匈奴，不敢访求苏武。时间一久，单于派遣李陵去北海，为苏武安排了酒宴和歌舞。李陵趁机对苏武说：“单于听说我与你交情一向深厚，所以派我来劝说足下，愿谦诚地相待你。你终究不能回归本朝了，白白地在荒无人烟的地方受苦，你对汉廷的信义又怎能有所表现呢？以前你的大哥苏嘉做奉车都尉，跟随皇上到雍的棫宫，扶着皇帝的车驾下殿阶，碰到柱子，折断了车辕，被定为大不敬的罪，用剑自杀了，只不过赐钱二百万用以下葬。你弟弟孺卿跟随皇上去祭祀河东土神，骑着马的宦官与掌管车辆马匹的官争船，把掌管车辆马匹的官推下去掉到河中淹死了。宦官骑着马逃走了。皇上命令孺卿去追捕，他抓不到，因害怕而服毒自杀。我离开长安的时候，你的母亲已去世，我送葬到阳陵。你的夫人年纪还轻，听说已改嫁了，家中只有两个妹妹，两个女儿和一个男孩，如今又过了十多年，生死不知。人生像早晨的露水，何必长久地像这样折磨自己！我刚投降时，终日若有所失，几乎要发狂，自己痛心对不起汉廷，加上老母拘禁在保宫，你不想投降的心情，怎能超过当时我李陵呢！并且皇上年纪大了，法令随时变更，大臣无罪而全家被杀的有十几家，安危不可预料。你还打算为谁守节呢？希望你听从我的劝告，不要再说什么了！”
苏武说：“我苏武父子无功劳和恩德，都是皇帝栽培提拔起来的，官职升到列将，爵位封为通侯，兄弟三人都是皇帝的亲近之臣，常常愿意为朝廷牺牲一切。现在得到牺牲自己以效忠国家的机会，即使受到斧钺和汤镬这样的极刑，我也心甘情愿。大臣效忠君王，就像儿子效忠父亲，儿子为父亲而死，没有什么可遗憾的，希望你不要再说了！”李陵与苏武共饮了几天，又说：“你一定要听从我的话。”苏武说：“我料定自己已经是死去的人了！单于一定要逼迫我投降，那么就请结束今天的欢乐，让我死在你的面前！”李陵见苏武对朝廷如此真诚，慨然长叹道：“啊，义士！我李陵与卫律的罪恶，上能达天！”说着眼泪直流，浸湿了衣襟，告别苏武而去。
李陵不好意思亲自送礼物给苏武，让他的妻子赐给苏武几十头牛羊。后来李陵又到北海，对苏武说：“边界上抓住了云中郡的一个俘虏，说太守以下的官吏百姓都穿白的丧服，说是皇上死了。”苏武听到这个消息，面向南放声大哭，吐血，每天早晚哭吊达几月之久。汉昭帝登位，几年后，匈奴和汉达成和议。汉廷寻求苏武等人，匈奴撒谎说苏武已死。后来汉使者又到匈奴，常惠请求看守他的人同他一起去，在夜晚见到了汉使，原原本本地述说了几年来在匈奴的情况。告诉汉使者要他对单于说：“天子在上林苑中射猎，射得一只大雁，脚上系着帛书，上面说苏武等人在北海。”汉使者万分高兴，按照常惠所教的话去责问单于。单于看着身边的人十分惊讶，向汉使道歉说：“苏武等人的确还活着。”于是李陵安排酒筵向苏武祝贺，说：“今天你还归，在匈奴中扬名，在汉皇族中功绩显赫。即使古代史书所记载的事迹，图画所绘的人物，怎能超过你！我李陵虽然无能和胆怯，假如汉廷姑且宽恕我的罪过，不杀我的老母，使我能实现在奇耻大辱下积蓄已久的志愿，这就同曹沫在柯邑订盟可能差不多，这是以前所一直不能忘记的！逮捕杀戮我的全家，成为当世的奇耻大辱，我还再顾念什么呢？算了吧，让你了解我的心罢了！我已成异国之人，这一别就永远隔绝了！”李陵起舞，唱道：“走过万里行程啊穿过了沙漠，为君王带兵啊奋战匈奴。归路断绝啊刀箭毁坏，兵士们全部死亡啊我的名声已败坏。老母已死，虽想报恩何处归！”
李陵泪下纵横，于是同苏武永别。单于召集苏武的部下，除了以前已经投降和死亡的，总共跟随苏武回来的有九人。苏武于汉昭帝始元六年（前81年）春回到长安。昭帝下令叫苏武带一份祭品去拜谒武帝的陵墓和祠庙。任命苏武做典属国，俸禄中二千石；赐钱二百万，官田二顷，住宅一处。常惠、徐圣、赵终根都任命为皇帝的侍卫官，赐给丝绸各二百匹。其余六人，年纪大了，回家，赐钱每人十万，终身免除徭役。常惠后来做到右将军，封为列侯，他自己也有传记。苏武被扣在匈奴共十九年，当初壮年出使，等到回来，胡须头发全都白了。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d92e6a6b501f968556", "shortContent": "公元前三世纪末期，中国出现了统一的大帝国———秦，北方也形成了奴隶制国家———匈奴，南北对峙，战争不断。由于秦末农民起义，汉族统治者无暇顾及民族战争，汉初以来，匈奴领袖冒顿单于以其“控弦之士”三十余万，东败东胡，北服丁零，西逐大月氏，使“诸引弓之民，并为一家”，不断南侵。汉高祖刘邦率部亲征，却在公元前202年被围于平城，不得已只能忍辱和亲。经四朝六十多年，尤其是文景之治的休养将息之后，汉武帝凭藉雄...", "authors": ["邓乔彬"], "pressName": "上海辞书出版社"}]', '', 'indent', 1582051479, '5e4bbff5fc36ed006acd649d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643654, '楚归晋知罃', NULL, 7, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '晋人归楚公子谷臣，与连尹襄老之尸于楚，以求知罃。于是荀首佐中军矣，故楚人许之。
王送知罃，曰：“子其怨我乎？”对曰：“二国治戎，臣不才，不胜其任，以为俘馘。执事不以衅鼓，使归即戮，君之惠也。臣实不才，又谁敢怨？”王曰：“然则德我乎？”对曰：“二国图其社稷，而求纾其民，各惩其忿，以相宥也，两释累囚，以成其好。二国有好，臣不与及，其谁敢德？”王曰：“子归何以报我？”对曰：“臣不任受怨，君亦不任受德。无怨无德，不知所报。”王曰：“虽然，必告不谷。”对曰：“以君之灵，累臣得归骨于晋，寡君之以为戮，死且不朽。若从君之惠而免之，以赐君之外臣首；首其请于寡君，而以戮于宗，亦死且不朽。若不获命，而使嗣宗职，次及于事，而帅偏师以脩封疆，虽遇执事，其弗敢违。其竭力致死，无有二心，以尽臣礼。所以报也！王曰：“晋未可与争。”
重为之礼而归之。', '本文出自《左传·成公三年》。楚共王对知罃的句句逼问，知罃都巧妙回答。楚共王因此感叹“晋未可与争”，以隆重的礼仪送知罃归晋。知罃的对答也表现了他忠君爱国、对楚不卑不亢，精神难能可贵。', '归：送还。公子谷臣：楚庄王的儿子。连尹襄老：连尹是楚国官名，襄老是楚国的大臣。连尹、楚国主射之官。
求：索取。
于是：在这个时候。佐中军；担任中军副帅。
知罃（yīng）：字子羽，亦称荀罃，是晋大夫荀息的后裔，晋悼公时中军帅。
治戎：治兵，演习军队。这里的意思是交战。
馘（guó）：割下敌方战死者的左耳（用来报功）。这里与“俘”连用，指俘虏。
鼓：取血涂鼓，意思是处死。
即戮（lù）：接受杀戮。
惩：戒，克制。忿：怨恨。
宥（yòu）；宽恕，原谅。
与及：参与其中，相干。
任：担当
外臣：外邦之臣。臣子对别国君主称外臣。
宗：宗庙。
不获命：没有获得国君允许杀戮的命令。
宗职：祖宗世袭的职位。
偏师：副帅、副将所属的军队，非主力军队。
致死：献出生命。', '晋人把楚国公子谷臣和连尹襄老的尸首归还给楚国，以此要求交换知罃。当时荀首已经是中军副帅，所以楚人答应了。
楚王送别知罃，说：“您恐怕怨恨我吧！”知罃回答说：“两国兴兵，下臣没有才能，不能胜任自己的任务，所以做了俘虏。君王的左右没有用我的血来祭鼓，而让我回国去接受诛戮，这是君王的恩惠啊。下臣实在没有才能，又敢怨恨谁？”楚王说：“那么感激我吗？”知罃回答说：“两国为自己的国家打算，希望让百姓得到平安，各自抑止自己的愤怒，来互相原谅，两边都释放被俘的囚犯，以结成友好。两国友好，下臣不曾与谋，又敢感激谁？”楚王说：“您回去，用什么报答我？”知罃回答说：“下臣无所怨恨，君王也不受恩德，没有怨恨，没有恩德，就不知道该报答什么。”楚王说：“尽管这样，还是一定要把您的想法告诉我。”知罃回答说：“以君王的福佑，被囚的下臣能够带着这把骨头回到晋国，寡君如果加以诛戮，死了将很光荣。如果由于君王的恩惠而赦免下臣，把下臣赐给您的外臣荀首，荀首向寡君请求，而把下臣在自己的宗庙里诛戮，也死而不朽。如果得不到寡君诛戮的命令而让我继承宗族的世职，按次序承担晋国的政事，率领部分军队来治理边疆，即使碰到君王的文武官员，我也不会躲避，只有竭尽全力到贡献自己的生命，没有别的念头，以尽到为臣的职责，这就是我用来报答君王的。”楚共王说：“晋国是不能与之相斗争的。”
于是就对他重加礼遇而放他回去。', NULL, '', 'indent', 1575385869, '5de60a8afc36ed0068413d59', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643655, '吕相绝秦', NULL, 7, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '晋侯使吕相绝秦，曰：“昔逮我献公及穆公相好，戮力同心，申之以盟誓，重之以昏姻。天祸晋国，文公如齐，惠公如秦。无禄，献公即世。穆公不忘旧德，俾我惠公用能奉祀于晋。又不能成大勋，而为韩之师。亦悔于厥心，用集我文公。是穆之成也。
“文公躬擐甲胄，跋履山川，逾越险阻，征东之诸侯，虞、夏、商、周之胤，而朝诸秦，则亦既报旧德矣。郑人怒君之疆埸，我文公帅诸侯及秦围郑。秦大夫不询于我寡君，擅及郑盟。诸侯疾之，将致命于秦。文公恐惧，绥静诸侯，秦师克还无害，则是我有大造于西也。
“无禄，文公即世；穆为不吊，蔑死我君，寡我襄公，迭我肴地，奸绝我好，伐我保城。殄灭我费滑，散离我兄弟，挠乱我同盟，倾覆我国家。我襄公未忘君之旧勋，而惧社稷之陨，是以有淆之师。犹愿赦罪于穆公，穆公弗听，而即楚谋我。天诱其衷，成王陨命，穆公是以不克逞志于我。
“穆、襄即世，康、灵即位。康公，我之自出，又欲阙剪我公室，倾覆我社稷，帅我蝥贼，以来荡摇我边疆，我是以有令狐之役。康犹不悛，入我河曲，伐我涑川，俘我王官，剪我羁马，我是以有河曲之战。东道之不通，则是康公绝我好也。
“及君之嗣也，我君景公引领西望曰：‘庶抚我乎！’君亦不惠称盟，利吾有狄难，入我河县，焚我箕、郜，芟夷我农功，虔刘我边垂，我是以有辅氏之聚。君亦悔祸之延，而欲徼福于先君献、穆，使伯车来命我景公曰：‘吾与女同好弃恶，复脩旧德，以追念前勋。’言誓未就，景公即世，我寡君是以有令狐之会。君又不祥，背弃盟誓。白狄及君同州，君之仇雠，而我昏姻也。君来赐命曰：‘吾与女伐狄。’寡君不敢顾昏姻。畏君之威，而受命于吏。君有二心于狄，曰：‘晋将伐女。’狄应且憎，是用告我。楚人恶君之二三其德也，亦来告我曰：‘秦背令狐之盟，而来求盟于我：“昭告昊天上帝、秦三公、楚三王曰：‘余虽与晋出入，余唯利是视。’”不榖恶其无成德，是用宣之，以惩不壹。’诸侯备闻此言，斯是用痛心疾首，昵就寡人。寡人帅以听命，唯好是求。君若惠顾诸侯，矜哀寡人，而赐之盟，则寡人之愿也，其承宁诸侯以退，岂敢徼乱？君若不施大惠，寡人不佞，其不能以诸侯退矣。敢尽布之执事，俾执事实图利之。”', '本文出自《左传·成公十三年》。前580年，晋、秦为了讲和，在令狐会盟。晋侯首先到达令狐，秦伯不肯渡过黄河，派史颗在河东与晋侯结盟；晋国的郤犨到河西与秦伯结盟。结果，秦伯回国就背弃了与晋国的和约。前578年，夏四月戊午（四月初五），晋侯派吕相去断绝和秦国的邦交，即有此篇《吕相绝秦》的檄文。', '晋侯；晋厉公。吕相，晋国大夫，魏锜的儿子魏相，因食邑在吕，又称吕相。绝；绝交。
戮力：合力，并力。
申：申明。
重：加重，加深。昏姻：婚姻。秦、晋国有联姻关系。
天祸：天降灾祸，指骊姬之乱。
无禄：没有福禄。这里指不幸。
即世：去世。
俾：使。用：因为。奉祀；主持祭祀。这里指立为国君。
韩之师：韩地的战争，指秦晋韩原之战。
厥：其，指秦穆公。
用：因而。集：成全。
躬：亲身。擐：穿上。
跋履：跋涉。
胤（yìn）：后代。东方诸侯国的国君大多是虞、夏、商、周的后代。
旧德：过去的恩惠。
怒：指侵犯。疆场：边疆。
询：指商量。擅及郑盟：擅自与郑人订盟。
疾：憎恶，憎恨。
致命于秦；与秦国拼命。
绥静：安定，安抚。
大造：大功。西：指秦国。
不吊：不善。
寡：这里的意思是轻视。
迭：同“轶”，越过，指侵犯。
奸绝：断绝。我好：同我友好。
保：同“堡”，城堡。
殄（tiǎn）灭；灭绝。费（bì）：滑国的都城，在今河南偃师附近。费滑即滑国。
散离：拆散。兄弟：指兄弟国家。
挠乱；扰乱。同盟：同盟国家，指郑国和滑国。
犹愿：还是希望。
即楚：亲近楚国。谋我：谋算我晋国。
诱：开启。衷：内心。
穆、襄：秦穆公和晋襄公。
康、灵：秦康公和晋灵公。
我之自出：秦康公是穆姬所生，是晋文公的外甥，所以说“自出”。
阙剪：损害，削弱。
蟊（máo）贼：本指吃庄稼的害虫，这里指晋国公子雍。
悛（quān）：悔改。
河曲：晋国地名，在今山西永济东南。
涑（sù）川：水名，在今山西西南部。
俘：劫掠。王官：晋国地名，在今山西闻喜西。
羁马：晋国地名，在今山西永济南。
东道；晋国在秦国东边，所以称“东道”。不通：指两国断绝关系。
君；指秦桓公。
引：伸长。：脖子。
蔗：大概，或许。抚：抚恤。
称盟：举行盟会。
狄难：指晋国同狄人打仗。
河县：晋国临河的县邑。
箕：晋国地名，在今山西蒲县东北。郜（gào）：晋国地名，在今山西祁县西。
芟（shān）：割除。夷：伤害。农功：庄稼。
虔刘：杀害，屠杀。边垂：边陲，边境。
辅氏：晋国地名，在今陕西大荔东。聚：聚众抗敌。
伯车：秦桓公之子。
寡君：指晋历公。
不详：不善。
白狄：狄族的一支。及：与。同州：同在古雍州。
婚姻；指晋文公在狄娶季隗。
吏：指秦国传令的使臣。
是用：因此。
二三其德；三心二薏，反复无常。
昭：明。昊：广大。秦三公：秦国穆公、康公、共公。楚三王：楚国成王、穆王、庄王。
出入：往来。
唯利是视：一心图利，唯利是图。
不壹：不专一。
昵就：亲近。
帅以听命：（若您不肯与我重修旧好），我将率领诸侯来讨伐秦国。
承宁：安定。
不佞：不敏，不才。
图：考虑。利之：对秦国有利。', '晋历公派吕相去秦国断交，说：“从前我们先君献公与穆公相友好，同心合力，用盟誓来明确两国关系，用婚姻来加深两国关系。上天降祸晋国，文公逃亡齐国，惠公逃亡秦国。不幸献公去逝，穆公不忘从前的交情，使我们惠公因此能回晋国执政。但是秦国又没有完成大的功劳，却同我们发生了韩原之战。事后穆公心里感到了后悔，因而成全了我们文公回国为君。这都是穆公的功劳。
“文公亲自戴盔披甲，跋山涉水，经历艰难险阻，征讨东方诸候国，虞、夏、商、周的后代都来朝见秦国君王，这就已经报答了秦国过去的恩德了。郑国人侵扰君王的边疆，我们文公率诸侯和秦国一起去包围郑国。秦国大夫不和我们国君商量，擅自同郑国订立盟约。诸侯都痛恨这种做法，要同秦国拼命。文公担心秦国受损，说服了诸侯，秦国军队才得以回国而没有受到损害，这就是我们对秦国有大恩大德之处。
“不幸文公去逝，穆公不怀好意蔑视我们故去的国君，轻视我们襄公，侵扰我们的淆地，断绝同中国的友好，攻打我们的城堡，灭绝我们的滑国，离间我们兄弟国家的关系，扰乱我们的盟邦，颠覆我们的国家。我们襄公没有忘记秦君以往的功劳，却又害怕国家灭亡，所以才有淆地的战斗。我们是希望穆公宽免我们的罪过，穆公不同意，反而亲近楚国来算计我们。老天有眼，楚成王丧了命，穆公因此没有使侵犯中国的图谋得逞。
穆公和襄公去逝，康公和灵公即位。康公是我们先君献公的外甥，却又想损害我们公室，颠覆我们国家，率公子雍回国争位，让他扰乱我们的边疆，于是我们才有令狐之战。康公还不肯悔改，入侵我们的河曲，攻打我们的涑川，俘虏我王官的人民，夺走我们的羁马，因此我们才有了河曲之战。与东方贵国的联系不通的原因，正是因为康公断绝了同我们的友好关系。
“等到君王即位之后，我们景公伸长脖子望著西边说：‘恐怕要关照我们吧！’但君王还是不肯开恩同中国结为盟好，却乘我们遇上狄人祸乱之机，入侵我们临河的县邑，焚烧我们的萁、郜两地，抢割毁坏我们的庄稼，屠杀我们的边民，因此我们才有辅氏之战。君王也后悔两国战争蔓延，因而想向先君献公和穆公求福，派遣伯车来命令我们景公说：‘我们和你们相互友好，抛弃怨恨，恢复过去的友谊，以追悼从前先君的功绩。’盟誓还没有完成，景公就去逝了，因此我们国君才有了令狐的盟会。君王又产生了不善之心，背弃了盟誓。白狄和秦国同处雍州，是君王的仇敌，却是我们的姻亲。君王赐给我们命令说：‘我们和你们一起攻打狄人。’我们国君不敢顾念姻亲之好，畏惧君王的威严，接受了君王使臣攻打狄人的命令。但君王又对狄人表示友好，对狄人说：‘晋国将要攻打你们。’狄人表面上答应了你们的要求，心里却憎恨你们的做法，因此告诉了我们。楚国人同样憎恨君王反复无常，也来告诉我们说；‘秦国背叛了令狐的盟约，而来向我们要求结盟。他们向著皇天上帝、秦国的三位先公和楚国的三位先王宣誓说：‘我们虽然和晋国有来往，当我们只关注利益。’我讨厌他们反复无常，把这些事公开，以便惩戒那些用心不专一的人。’诸侯们全都听到了这些话，因此感到痛心疾首，都来和我亲近。现在我率诸侯前来听命，完全是为了请求盟好。如果君王肯开恩顾念诸侯们，哀怜寡人，赐我们缔结盟誓，这就是寡人的心愿，寡人将安抚诸侯而退走，哪里敢自求祸乱呢？如果君王不施行大恩大德，寡人不才，恐怕就不能率诸侯退走了，请向你的左右执事布置清楚，使他们权衡怎样才对秦国有利。”', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b67de30675327e125034b", "shortContent": "《左传》不仅真实、详尽地记录了无数重大历史事件，而且保存了有关哲学、文学、社会风俗的极其丰富的资料，以及许多政治、法律、外交等方面的宝贵文献。《吕相绝秦》就是其中一篇十分精彩的外交文件。它被后人誉为“檄文之祖”（韩席筹《左传分国集注》下），即千古第一檄文。尽管此文并未宣扬渗透于《左传》全书的儒家观念，甚至它的一些做法，如歪曲历史，为儒家传统所不容，但是《左传》作者在惜墨如金的时代还是把长达一千余字...", "authors": ["施忠连"], "pressName": "上海辞书出版社"}]', '', 'indent', 1575387623, '5de61149fc36ed0068419037', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643656, '驹支不屈于晋', NULL, 5, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '会于向，将执戎子驹支。范宣子亲数诸朝。曰：“来，姜戎氏。昔秦人迫逐乃祖吾离于瓜州，乃祖吾离被苫盖，蒙荆棘，以来归我先君。我先君惠公有不腆之田，与女剖分而食之。今诸侯之事我寡君不如昔者，盖言语漏泄，则职女之由。诘朝之事，尔无与焉！与，将执女。”
对曰：“昔秦人负恃其众，贪于土地，逐我诸戎。惠公蠲其大德，谓我诸戎是四岳之裔胄也，毋是剪弃。赐我南鄙之田，狐狸所居，豺狼所嗥。我诸戎除剪其荆棘，驱其狐狸豺狼，以为先君不侵不叛之臣，至于今不贰。昔文公与秦伐郑，秦人窃与郑盟而舍戍焉，于是乎有肴之师。晋御其上，戎亢其下，秦师不复，我诸戎实然。譬如捕鹿，晋人角之，诸戎掎之，与晋踣之，戎何以不免？自是以来，晋之百役，与我诸戎相继于时，以从执政，犹肴志也，岂敢离逷？今官之师旅，无乃实有所阙，以携诸侯，而罪我诸戎。我诸戎饮食衣服不与华同，贽币不通，言语不达，何恶之能为？不与于会，亦无瞢焉。”赋《青蝇》而退。
宣子辞焉，使即事于会，成恺悌也。', '本文出自《左传·襄公十四年》。这篇文章记录的就是戎子驹支以事实说话，驳倒范宣子的责难的事：范宣子仗着晋国的强大，仗着自己的先君曾有恩于羌戎，对驹支气势汹汹，把晋国霸主地位的动摇归咎于驹支。戎子驹支则据理力争，逐层辩驳。首先说晋国所赏赐的土地是荒芜不毛之地，不足以称大恩大德。其次说羌戎帮助晋国在肴地全歼秦军，可以说已经报恩了，之后更是鞍前马后，毫无二心。最后暗示晋国所以众叛亲离，乃是其自己一手造成的，与羌戎无关。全部辩辞语气委婉而正气凛然，使范宣子不得不服。', '向：吴地，在今安徽怀远县西南。
戎子驹支：姜戎族的首领，名驹支。姜戎，戎族的一个部落。
乃祖：你的祖父。瓜州：地名，在今甘肃敦煌西。
苫（shān）盖：用草编成的覆盖物。
不腆（tiǎn）：不丰厚，不多。
女：通“汝”，你。
职：主要。
诘朝：明日。
蠲（juān）：显示。
四岳：传说为尧舜时四方部落首领。裔胄：后嗣。
亢：抗。
掎：拉住，拖住。
踣：同“仆”。
犹肴志也：还是像在肴作战时那样忠心。
逷（tì）：远。
携：离，疏远。
贽币：古人见面时所赠送的礼物。贽币不通，喻没有往来。
瞢（měng）：闷，不舒畅。
青绳：《诗经·小雅》中的一篇，主旨是希望君子莫信馋言。
辞：道歉。
成：成全。恺悌：和乐平易。', '晋国和诸侯各国在向地集会，准备拘捕姜戎族的首领驹支。晋国大夫范宣子在朝会上亲自指责他，说：“过来，姜戎氏！从前秦国人把你祖父吾离从瓜州赶走，你祖父吾离披着茅草衣、戴着荆条帽前来投奔我国先君。我先君惠公当时有不多的田地，却与你们平分来养活你们。如今诸侯侍奉我们寡君不如从前，大概说话泄漏了什么机密，这主要是你造成的。明天的会议，你不要参加了！你要是参加，就把你抓起来！”
驹支回答说：“从前秦国人仗着他们人多，贪婪地掠夺土地，把我们各部落戎人从祖居地赶走。贵国君惠公显示他崇高的品德，认为我们各部戎人都是四岳的后代，不该这样抛弃灭绝。他赐给我们南部边疆的土地，那里是狐狸居住、豺狼嗥叫的地方。我们各部戎人砍除了那里的荆棘，赶走了那里的狐狸、豺狼，从此成了贵国先君既不内侵也不外叛的臣属，直到如今忠诚不二。从前文公与秦国攻打郑国，秦国人私下里同郑国人订立盟约，留下军队在那里驻守，因此而发生肴地战役。当时晋军在前面抵抗，我们戎人在后面进击，秦军全军覆没，实在是我们戎人出了大力。这就如同捕鹿，晋国人抓住它的角，戎人拖住它的后腿，和晋国人一起把它掀倒。戎人为什么不能免于罪责呢？从那时以来，晋国多次出兵征战，我戎人各部从来紧跟其后，时时追随贵国执政，还是像肴之战时那样心志如一，岂敢疏远背离？如今贵国军旅中的长官可能真是有些地方做得不够，使得诸侯叛离，你们却怪罪我们戎人！我们各部戎人服饰饮食（习俗）不与华夏相同，礼仪使者不相往来，言语不通，能做什么对贵国不利的坏事？不参加盟会的事务，我也不会惭愧。”驹支朗读了《青蝇》诗退了下去。
范宣子连忙道歉，请他参加会议事务，同时也成全了自己和蔼可亲的君子美名。', NULL, '', 'indent', 1575388296, '5de613fb43c25700685f272a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643657, '祁奚请免叔向', NULL, 6, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '栾盈出奔楚。宣子杀羊舌虎，囚叔向。
人谓叔向曰：“子离于罪，其为不知乎？”叔向曰：“与其死亡若何？诗曰：‘优哉游哉，聊以卒岁。’知也。”
乐王鲋见叔向曰：“吾为子请。”叔向弗应，出不拜。其人皆咎叔向。叔向曰：“必祁大夫。”室老闻之曰：“乐王鲋言于君无不行，求赦吾子，吾子不许；祁大夫所不能也，而曰必由之。何也？”叔向曰：“乐王鲋从君者也，何能行？祁大夫外举不弃仇，内举不失亲，其独遗我乎？诗曰：‘有觉德行，四国顺之。’夫子，觉者也。”
晋侯问叔向之罪于乐王鲋。对曰：“不弃其亲，其有焉。”
于是祁奚老矣，闻之，乘驲而见宣子，曰：“《诗》曰：‘惠我无疆，子孙保之。’《书》曰：‘圣有谟勋，明征定保。’夫谋而鲜过，惠训不倦者，叔向有焉，社稷之固也。犹将十世宥之，以劝能者。今壹不免其身，以弃社稷，不亦惑乎？鲧殛而禹兴；伊尹放大甲而相之，卒无怨色；管蔡为戮，周公右王。若之何其以虎也弃社稷？子为善，谁敢不勉，多杀何为？”宣子说，与之乘，以言诸公而免之。不见叔向而归，叔向亦不告免焉而朝。', '本文出自《左传·襄公二十一年》。叔向受弟弟的牵连，突然被捕，但他临危不惧，且有知人之明。祁奚为国家爱惜人才，事成则“不见而归”，根本不希望别人报答。叔向获救，也“不告免而朝”，因为他深知祁奚的品德。相形之下，乐王鲋的虚伪和卑鄙，真是不堪入目。', '栾盈：晋大夫，因与晋国的加一大夫范鞅不和，谋害范鞅。事败被驱逐，故出奔楚。宣子：即范鞅。羊舌虎：栾盈的同党。叔向：羊舌虎的哥哥羊舌肸（xī）。
离：同“罹”，遭遇。
知：同“智”。
优游：闲暇而快乐自得的样子。
乐王鲋（fǔ）：即东桓子，晋大夫。
祁大夫：即祁奚。
室老：古时卿大夫家中有家臣，室老是家臣之长。
不弃仇：祁奚曾经向晋君推荐过他的仇人解狐。不失亲：祁奚曾经向晋君推荐过的他的儿子祁许。
夫子：那个人，指祁奚。觉者：有正直德行的人。
驲（rì）：古代驿站的马车。
保：依赖。
谟（mó）：谋略。
十世：指远代子孙。宥：赦宥。
壹：指因羊舌虎这一件事。', '栾盈逃奔楚国，范宣子杀了羊舌虎，软禁了叔向。有人对叔向说：“你受这样的罪，未免不够明智吧？”
叔向说：“那些死了的和逃跑的，又怎么样呢？《诗经》说：‘难得清闲和逸脱啊，就这样了此一生吧！’这才是明智。”
乐王鲋见到叔向说：“我去为您求情。”叔向没有理会，乐王鲋离开时，不拜谢。旁人都埋怨叔向，叔向说：“只有祁大夫才能救我。”管家听到这话就说：“乐王鲋在君主面前说的话，没有不采纳的。请求赦免您，您不理会。我认为祁大夫无法办到的事，您却说必须由他。为什么呢？”叔向说：“乐王鲋是顺从君主的人，怎么能行？祁大夫举荐外人不遗弃有仇的人，举荐熟人不遗漏亲人，他难道会遗漏我吗？《诗》说：“有正直的德行，天下人都会顺从’。祁大夫正是这样正直的人啊！” 晋侯向乐王鲋问起叔向的罪责，乐王鲋说：“不背弃他的亲人，他有些牵涉吧！”当时祁奚已经告老还乡了，听到这事，赶紧坐上驿站的马车来见范宣子。说：“《诗》说：‘给予我恩惠无边的人，子孙后代永远保存’，《尚书》说：‘圣贤有谋略和功勋，应当明证他的功劳和加以保护。’谋划而少有过失，给人许多教益而不知疲倦，叔向就有这样的能力。叔向是国家的柱石，即使他十代的子孙犯了罪也应该宽宥，以此勉励那些有能力的人。如今因为他的弟弟犯罪一事而使他不得免罪，，这从而丢弃国家栋梁，这不是糊涂吗？鲧被诛杀，他的儿子禹却兴起；伊尹起初曾放逐太甲，后来又辅佐太甲为相，太甲始终没有怨恨伊尹；管叔、蔡叔因为造反被杀，周公却辅佐他们的侄子成王。您为什么因为羊舌虎的缘故抛弃国家的柱石呢？ 您与人为善，谁还敢不竭力为国！多杀人又何必呢？”
范宣子听了很高兴，便同他一起坐车去见晋平公而赦免了叔向。祁奚不见叔向就回家。叔向也未向祁奚致谢，径直上朝。', '[{"bookId": "60fd3df834bfda01e0eaa081", "bookTitle": "历代赋鉴赏辞典", "articleId": "610ecf4f5914587d02f59d21", "shortContent": "《对楚威王》见于《战国策·楚策一》，姚鼐《古文辞类纂》题为“莫敖子华对威王”。《战国策》乃是六国之时的策士和一些文人的书信、上书、游说辞底稿与追记稿等的汇集，是策士们用来练习游说才能的材料，并不是出于史官的记载。由《战国策》一书编集之体例看，本文当是莫敖子华的一篇奏议，或奏对追记稿，其题目应作《对楚威王》。原文文字有所错乱，今依赵逵夫先生《屈原与他的时代·莫敖子华〈对楚威王〉考校》一文予以校改。\n...", "authors": ["马世年"], "pressName": "上海辞书出版社"}]', '', 'indent', 1575388984, '5de616b15620710076a29108', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643658, '子产告范宣子轻币', NULL, 7, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '范宣子为政，诸侯之币重，郑人病之。
二月，郑伯如晋。子产寓书于子西，以告宣子，曰：“子为晋国，四邻诸侯，不闻令德而闻重币。侨也惑之。侨闻君子长国家者，非无贿之患，而无令名之难，夫诸侯之贿，聚于公室，则诸侯贰；若吾子赖之，则晋国贰。诸侯贰则晋国坏，晋国贰则子之家坏。何没没也？将焉用贿？
夫令名，德之舆也。德，国家之基也。有基无坏，无亦是务乎？有德则乐，乐则能久。诗云：‘乐只君子，邦家之基。’有令德也夫！‘上帝临女，无贰尔心。’有令名也夫！恕思以明德，则令名载而行之，是以远至迩安。毋宁使人谓子，子实生我，而谓子浚我以生乎？象有齿以焚其身，贿也。”
宣子说，乃轻币。', '本文出自《左传·襄公二十四年》。晋平公时期，晋国是各诸侯国的盟主，各国交纳的币帛负担很重。子产是郑国有才干的政治家，他就这种状况采取了寄书说理的方式，利用晋国想极力保住盟主地位和希望得到美好声誉的心理，阐明“重币”与“轻币”的关系，使晋国不得不减轻了对诸侯国的剥削。', '币：帛，古代通常用作礼物。这里指诸侯向盟主晋国进献的贡品。
病：这里作动词用，忧虑。
郑伯：郑简公。
子产：即公孙侨，一字子美。郑简公十二年（前554）为卿，二十三年（前543）执政。寓：寄，传书。子西：郑大夫。当时随从郑简公去晋国。
侨：子产自称。
贿：财物。
令名：好的名声。
公室：指晋君。
赖：恃，凭借。
没没：沉溺，贪恋。
舆：车子。
只：语助词，没有意义。
“无贰尔心”：即“尔心毋贰”。
迩：近。
浚：取。
焚身：丧身。
说：通“悦”，高兴。', '晋范宣子执政，诸侯去朝见晋国时的贡纳的财礼很重，郑国人对此感到不满。
二月，郑简公到晋国去。子产托子西带信告诉范宣子，说：“您治理晋国，四邻的诸侯没有听到您的美德，却听到您要很重的贡物，我对此感到迷惑。我听说君子执掌国家和家族政权的，不是担心没有财礼，而是害怕没有好名声。诸侯的财货，都聚集在晋国，那么诸侯就会叛离。如果您贪图这些财物，那么晋国的内部就会不团结。诸侯叛离，晋国就要受到损害；晋国内部不团结，您的家族就会受到损害。为什么那样糊涂呢！贪图得来的财货又有什么用呢？
“好名声，是装载德行远远传播的车子。德行，是国家和家族的基础。有了基础才不至于败坏，不也应该致力于这个吗？有了德行就会与人同乐，与人同乐才能在位长久。《诗经》说：‘快乐啊君子，是国家和家族的基础。’这就是说有美德啊！‘上天看顾你，不要三心二意。’这就是说有好名声啊！心存宽恕来发扬美德，那么好名声就可以四处传播，因此远方的人纷纷来到，近处的人得到安心。是宁可让人说您‘您确实养活了我’，还是说‘您榨取我来养活自己’呢？大象有了象牙而使自己丧生，这是因为象牙也是值钱的财货呀。”
范宣子听了很高兴，就减轻了诸侯进贡的财礼。', NULL, '', 'indent', 1575389639, '5de6194543c25700685f6820', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643659, '晏子不死君难', NULL, 6, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '崔武子见棠姜而美之，遂取之。庄公通焉。崔子弑之。
晏子立于崔氏之门外。其人曰：“死乎？”曰：“独吾君也乎哉，吾死也？”曰：“行乎？”曰：“吾罪也乎哉，吾亡也？”曰：“归乎？”曰：“君死，安归？君民者，岂以陵民？社稷是主。臣君者，岂为其口实？社稷是养。故君为社稷死，则死之；为社稷亡，则亡之。若为己死，而为己亡，非其私暱，谁敢任之？且人有君而弑之，吾焉得死之？而焉得亡之？将庸何归？”门启而入，枕尸股而哭。兴，三踊而出。人谓崔子：“必杀之。”崔子曰：“民之望也，舍之得民。”', '本文出自《左传·襄公二十五年》。齐庄公因私通被臣子弑杀，晏子既不为他而死，也不因他而逃亡。在他看来，无论国君和臣子，都应为国家负责。如果国君失职，臣子就不必为他尽忠。这在当时是很有进步意义的。文章三问三答，答中有反问，最后归结到“社稷”二字，波澜起伏，论旨鲜明。', '崔武子：齐卿，即崔杼。棠姜：棠公的妻子。棠公是齐国棠邑大夫。
取：同“娶”。棠公死，崔杼去吊丧，见棠姜美，就娶了她。
庄公：齐庄公。通：私通。
弑：臣杀君、子杀父为弑。
晏子：即晏婴，字平仲，齐国大夫。历仕灵公、庄公、景公三世。
其人：晏子左右的家臣。
君民者：做君主的人。
实：指俸禄。
昵：亲近。
庸何：即“何”，哪里。
兴：起立。三踊：跳跃了三下，表示哀痛。
望：为人所敬仰。
舍：释放，宽大处理。', '崔杼看见棠公的遗孀棠姜容貌妍丽，便迎娶她为妻。后来齐庄公与她私通，崔杼便杀害了齐庄公。
晏子站在崔家的门外，晏子左右的家臣问：“您打算死吗？”晏子说：“国君只是我一人的君主吗，我为何要死？”家臣说：“您打算离开齐国吗？”晏子说：“我有什么罪，我为什么要逃亡？”家臣说：“回家吗？”晏子说：“君主都已不在，还能回哪里呢？作为民众的君主，难道是凌驾于民众之上的君主？君主的职责是社稷。作为君主的臣下，难道是为了得到他的俸禄吗？臣子的职责是保护国家。国君为了社稷去死，死得其所，我们就应该与之共同赴难；如果君王为社稷而死，百姓当然可以和君主同死。如果是为自己而死或者为自己逃亡，不是他的私密昵友，谁去担这份责啊？况且他人立了君主却要将他杀死，我怎么能随他去死，随他去逃亡呢？我将回什么地方啊？”崔大夫家的门打开后晏子进入，将君主的尸体放在腿上痛哭，哭完后站起来，一再顿足离去。有人对崔杼说：“你一定会杀了他。”崔杼说：“他为百姓所敬仰，释放他反而能得到民心。”', NULL, '', 'indent', 1575390494, '5de61c8afc36ed006842173b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643660, '季札观周乐', NULL, 4, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '吴公子札来聘。请观于周乐。使工为之歌《周南》、《召南》，曰：“美哉！始基之矣，犹未也，然勤而不怨矣。为之歌《邶》、《鄘》、《卫》，曰：“美哉，渊乎！忧而不困者也。吾闻卫康叔、武公之德如是，是其《卫风》乎？”为之歌《王》曰：“美哉！思而不惧，其周之东乎！”为之歌《郑》，曰：“美哉！其细已甚，民弗堪也。是其先亡乎！”为之歌《齐》，曰：“美哉，泱泱乎！大风也哉！表东海者，其大公乎？国未可量也。”为之歌《豳》，曰：“美哉，荡乎！乐而不淫，其周公之东乎？”为之歌《秦》，曰：“此之谓夏声。夫能夏则大，大之至也，其周之旧乎！”为之歌《魏》，曰：“美哉，渢渢乎！大而婉，险而易行，以德辅此，则明主也！”为之歌《唐》，曰：“思深哉！其有陶唐氏之遗民乎？不然，何忧之远也？非令德之后，谁能若是？”为．之歌《陈》，曰：“国无主，其能久乎！”自《郐》以下无讥焉！
为之歌《小雅》，曰。“美哉！思而不贰，怨而不言，其周德之衰乎？犹有先王之遗民焉！”为之歌《大雅》，曰：“广哉！熙熙乎！曲而有直体，其文王之德乎？”
为之歌《颂》，曰：“至矣哉！直而不倨，曲而不屈；迩而不逼，远而不携；迁而不淫，复而不厌；哀而不愁，乐而不荒；用而不匮，广而不宣；施而不费，取而不贪；处而不底，行而不流。五声和，八风平；节有度，守有序。盛德之所同也！”
见舞《象箾》、《南龠》者，曰：“美哉，犹有憾！”见舞《大武》者，曰：“美哉，周之盛也，其若此乎？”见舞《韶濩》者，曰：“圣人之弘也，而犹有惭德，圣人之难也！”见舞《大夏》者，曰：“美哉！勤而不德。非禹，其谁能修之！”见舞《韶箾》者“，曰：“德至矣哉！大矣，如天之无不帱也，如地之无不载也！虽甚盛德，其蔑以加于此矣。观止矣！若有他乐，吾不敢请已！”', '本文出自《左传·襄公二十九年》。鲁襄公二十九年（公元前544年），吴国公子季札为替新任国君余祭谋求友好，奉命出使鲁国，随后又到齐、郑、卫、晋诸国。当其出访到鲁国时，季札请求演示、观赏周王室的音乐歌舞。此文即记叙了鲁国乐工演奏的顺序和季札对“周乐”的评价。', '吴公子札：即季札，吴王寿梦的小儿子。寿梦死，国人要立季札为国君，季札坚辞不受。因采邑于延陵、州来二地，所以又称延陵季子或州来季子。聘：聘问。古代诸侯与天子、诸侯与诸侯之间派使者问候。
周乐：周天子的乐舞。鲁国是周公的后裔，所以备有周乐。
《周南》《召南》：采自周、召（shào）两地的诗。周、召为周公、召公最初的封地，在今江、汉一带。
始基：起始，开端。
犹未：还没有尽善尽美。
勤：勤劳。
《邶》《鄘》《卫》：采自这三个诸侯国的乐歌。邶（bèi），故地在今河南汤阴东南。鄘（yōng），故地在今河南汲县东北。卫，在今河南北部和河北南部。
渊：深沉，深远。
忧：忧虑。
卫康叔：卫国始封君，周公之弟。武公：康叔九世孙，是卫国贤君。
《王》：采自王城一带的乐歌。王城，在今河南洛阳。
思：忧思，愁思。
周之东：周平王东迁。
《郑》：指采自郑国的诗歌。郑国故地在今河南新郑、郑州、荥阳一带。
细：琐碎。象征郑国政令苛细烦琐。
《齐》：指采自齐国的诗歌。齐地在今山东中部和东北部。
泱泱（yāng）：深广宏大的样子。
大风：大国的气魄，一说大国风范。
表：作……表率。
大公：即太公。姜太公吕尚，齐国始封君主。
《豳》：指采自豳地的乐歌。豳（bīn），在今陕西旬邑西，是周朝祖先所居之地。
荡：开朗壮阔。
淫：过分，失去节制。
《秦》：采自秦地的诗歌。秦地在今陕西、甘肃一带。
夏声：古代西方的一种乐歌。
能夏则大：能发夏声，气势自然宏大。
《魏》：采自魏国的乐歌。魏地在今山西芮（ruì）城一带。
沨沨（fēng）：形容乐声婉转抑扬。一说“沨”即“泛”字，沨沨，浮泛轻飘。
婉：委婉曲折。
险而易行：节拍急促却容易歌唱。险，迫促，狭隘。一说，险通“俭”，全句意谓朴素而流畅。
《唐》：采自唐地的乐歌。唐地，在今山西南部。
陶唐氏：即唐尧，传说中的古代帝王。
《陈》：采自陈国的民歌。陈地在今河南东南部及安徽北部。
《郐（kuài）》：采自郐地的诗歌。郐地在今河南密县东北。以下：《诗经》中《郐风》以下还有《曹风》。无讥：不加评论。
《小雅》：《诗经》的《雅》包括《小雅》《大雅》。《小雅》主要是贵族的作品，也有些是民间歌谣。大部分出于西周晚期，小部分是东周时的作品。其中颇有一些作品讽刺朝政，批评现实。
不言：不直说，不尽情吐述。
先王：指周代文、武、成、康诸王。
《大雅》：西周贵族的作品。
熙熙：和美融洽的样子。
直体：刚劲有力的风格。
《颂》：贵族用于宗庙祭祀的作品，包括《周颂》《鲁颂》《商颂》。
倨：放肆。
屈：卑下。
携：离心。
淫：过分。
荒：过度。
宣：显露，张扬。
费：减少。
处：不动，宁静。底：停滞。
流：泛滥。
五声：宫、商、角、徵（zhǐ）、羽。和：和谐。
八风：即八音，指金、石、丝、竹、匏（páo）、土、革、木八类乐器演奏的声音。平：协调。
节：节奏。
守：保持。
《象箾（shuò）》：一种武舞。执竿而舞，如战争时代以戈刺击的样子。箭，舞者所执的竿。《南籥（yuè）》以籥伴奏而舞，是一种文舞。籥，管乐器，似笛。
《大武》：周武王之乐。
《韶濩（huò）》：歌颂商汤的乐舞。
弘：伟大。
惭德：缺点。
《大夏》：歌颂夏禹的乐舞。
不德：不自以为德，不自夸功德。
修：作。
《韶箾（xiāo）》：又作《箫韶》，虞舜之乐。箾，此处同“箫”。
帱（dào）：覆盖。
蔑：无。
观止：观赏至此为止。意谓已经尽善尽美。', '吴国公子季札前来鲁国访问，请求观赏周朝的音乐舞蹈。鲁君让乐工为他演唱《周南》《召南》，他说：“美好啊！教化开始奠定基础了，虽然还不算完善，然而百姓已经勤劳而不怨恨了。”乐工为他演唱《邶风》《鄘风》和《卫风》，他说：“美好啊！深厚啊！虽然有忧思，却不至于困窘。我听说卫国的康叔、武公的德行就像这样，这恐怕就是《卫风》吧！"乐工为他演唱《王风》，他说：“美好啊！虽有忧思却没有恐惧的情绪，这恐怕是周室东迁之后的音乐吧！”乐工为他演唱《郑风》，他说：“美好啊！但它烦琐得太过分了，百姓已经不堪忍受了。这恐怕是要最先亡国的吧？”乐工为他演唱《齐风》，他说：“美好啊！宏大而深远，这是大国的音乐啊！可以成为东海诸国表率的，恐怕就是太公的国家吧？国运真是不可限量啊！”
乐工为他演唱《豳风》，他说：“美好啊！博大坦荡！欢乐却不放纵，这恐怕是周公东征时的音乐吧！”乐工为他演唱《秦风》，他说：“这就叫做‘夏声’。产生夏声就说明气势宏大，宏大到极点，大概是周朝故地的乐曲吧！”乐工为他演唱《魏风》，他说：“美好啊，轻远悠扬！粗犷而又婉转，急促而流畅，用仁德来加以辅助，就可以成为贤明的君主了。”乐工为他演唱《唐风》，他说：“思虑深远啊！恐怕有陶唐氏的遗民吧？如果不是这样，为什么忧思如此深远呢？如果不是有美德者的后代，谁能像这样呢？”乐工为他演唱《陈风》，他说：“国家没有贤明的君主，还能长久吗？”再歌唱《郐风》以下的乐曲，季札就不作评论了。
乐工为季札歌唱《小雅》，他说：“美好啊！有忧思但却没有二心，有怨恨但却不说出来，这大概是周朝的德政教化开始衰败时的音乐吧？那时还是有先王的遗民在啊！”乐工为他歌唱《大雅》，他说：“宽广啊！和美啊！抑扬曲折而本体刚劲，恐怕是文王的德行吧！”
乐工为他演唱《颂》，季札说：“达到顶点了！正直而不傲慢，屈从而不卑下，亲近而不因此产生威胁，疏远而不因此背离，变化而不过分，反复而不令人厌倦，悲伤而不愁苦，欢乐而不放纵堕落，用取而不会匮乏，宽广而不张扬，施予而不耗损，求取而不贪婪，安守而不停滞，行进而不泛滥。五声和谐，八音协调，节拍合于章法，演奏先后有序。这都是拥有大德行的人共有的品质啊！”
季札看到跳《象箾》和《南籥》两种乐舞后，说：“美好啊！但美中不足。”看到跳《大武》时说：“美好啊！周朝兴盛的时候，恐怕就是这样子吧！”看到跳《韶濩》时说：“圣人如此伟大，仍然有不足之处而自觉惭愧，做圣人不容易啊！”看到跳《大夏》时说：“美好啊！勤于民事而不以功德自居，除了禹，谁还能做到呢？”看到跳《韶箾》时说：“功德达到顶点了！伟大啊，就像苍天无所不覆盖一样，像大地无所不承载一样！再盛大的德行，恐怕也不能比这再有所增加了。观赏就到这里吧！如果还有其他乐舞，我也不敢再请求观赏了！”', NULL, '唐·孔颖达：“乐人采其诗词以为乐章，述其诗之本音，以为乐之定声。其声既定，其法可传，虽多历年世而其音不改。今此为季札歌者各依其本国歌所常用声曲也。由其各有声曲，故季札听而识之……季札所云‘美哉’者，皆美其声也。”（《春秋左传正义》卷三十九）
南宋·叶适：“季子之观乐，以音声论义理。”（《习学记言序目》卷十一）
明·魏禧：“季札所至，则必知国之治乱，必交其国之君子，与人言，必中其得失而慎其利害，岂徒以知乐为贤哉！此千古游客之师，汉郭有道其流亚欤！”（《左传经世钞》卷十五）
清·金圣叹：“每一歌，公子皆出神细听，故能深知其为何国何风。今读者于公子每一评论，亦当逐段逐字，出神细想，便亦能粗粗想见其为是国是风也。不然，杂杂读之，乃复何益？”（《天下才子必读书》卷二）
清·林云铭：“扎观乐在襄公二十九年时，夫子才九岁，则所歌之诗，未必皆在所删三百篇之内。即工当歌时，亦未与扎先言系何国之诗，故扎赞语多用‘乎’字，乃从声中想象而得也。扎为贤公子，赞叹歌诗之语，当得诸章句之外，断不是三家村中老学究死死板板取一部《诗经》，每篇细记几句注解向人前卖弄也。细玩赞《三颂》云‘五声和，八风平，节有度，守有序’四句，则知他歌中有不和、不平、无度、无序者。”（《古文析义初编》卷一）
清·吴楚材、吴调侯：“季札贤公子，其神智器识，乃是春秋第一流人物，故闻歌见舞，便能尽察其所以然。诗之者，细玩其逐层摹写，逐节推敲，必有得于声容之外者。如此奇文，非左氏其孰能传之？”（《古文观止》卷二）
清·冯李骅、陆浩：“五国交游议论，大抵相类，独鲁夹入一篇大文。盖于经书来聘，以鲁为主也。然于章法得毋有头重之患，文妙于历聘处，亦整整作提笔以配之，遂令叙文叙事裁作一色章法。此炼石补天手段，于本传尤为仅见之作。况余子焉能望其项背耶？观乐、历聘两截，都用直收，不加结束，章法最奇。观乐篇自成一番结构，作两半读：上半论歌，下半论舞。歌有风、雅、颂之别，而归重在颂。舞有四代之别，而归重在韶。于颂以‘至矣哉’起，盛德所同，煞于韶。亦以‘德至矣’起，盛德蔑加，两两相对，百长短整散，各各不同。谋篇至此，亦观止矣。”（《左绣》卷十九）', 'indent', 1575391298, '5de61fbe2a6bfd007316f741', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643661, '子产坏晋馆垣', NULL, 2, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '子产相郑伯以如晋，晋侯以我丧故，未之见也。子产使尽坏其馆之垣，而纳车马焉。
士文伯让之，曰：“敝邑以政刑之不修，寇盗充斥，无若诸侯之属辱在寡君者何，是以令吏人完客所馆，高其闬 闳，厚其墙垣，以无忧客使。今吾子坏之，虽从者能戒，其若异客何？以敝邑之为盟主，缮完葺墙，以待宾客。若皆毁之，其何以共命？寡君使丐请命。
对曰：“以敝邑褊小，介于大国，诛求无时，是以不敢宁居，悉索敝赋，以来会时事。逢执事之不闲，而未得见；又不获闻命，未知见时。不敢输币，亦不敢暴露。其输之，则君之府实也，非荐陈之，不敢输也。其暴露之，则恐燥湿之不时而朽蠹，以重敝邑之罪。侨闻文公之为盟主也，宫室卑庳，无观台榭，以崇大诸侯之馆，馆如公寝；库厩缮修，司空以时平易道路，圬人以时塓馆宫室；诸侯宾至，甸设庭燎，仆人巡宫，车马有所，宾从有代，巾车脂辖，隶人、牧、圉，各瞻其事；百官之属各展其物；公不留宾，而亦无废事；忧乐同之，事则巡之，教其不知，而恤其不足。宾至如归，无宁灾患；不畏寇盗，而亦不患燥湿。今铜鞮之宫数里，而诸侯舍于隶人，门不容车，而不可逾越；盗贼公行。而天疠不戒。宾见无时，命不可知。若又勿坏，是无所藏币以重罪也。敢请执事，将何所命之？虽君之有鲁丧，亦敝邑之忧也。若获荐币，修垣而行，君之惠也，敢惮勤劳？”文伯复命。
赵文子曰：“信。我实不德，而以隶人之垣以赢诸侯，是吾罪也。”使士文伯谢不敏焉。
晋侯见郑伯，有加礼，厚其宴好而归之。乃筑诸侯之馆。
叔向曰：“辞之不可以已也如是夫！子产有辞，诸侯赖之，若之何其释辞也？《诗》曰：‘辞之辑矣，民之协矣；辞之怿矣，民之莫矣。’其知之矣。”', '本文出自《左传·襄公三十一年》。子产陪同郑简公到晋国朝聘，晋国对郑国这个诸侯小国态度轻慢，宾馆简陋狭窄，使郑国带去纳贡的礼物无法安置。子产断然命人拆毁宾馆的墙垣，使车马得以进馆。当晋平公派士文伯来责问子产时，子产不卑不亢地申明自己的理由和态度，句句针锋相对，义正而不阿，词强而不激，使赵文子和晋平公也为之折服，向子产谢罪，对郑简公重新礼遇。子产凭自己的机敏和辩才为郑国争得了尊严，出色地完成了外交使命。', '公：指鲁襄公。薨：诸侯死去叫薨（hōng）。
相：辅佐。郑伯：指郑简公。
坏：拆毁。馆垣：宾馆的围墙。
士文伯：晋国大夫士訇。让：责备。
属：臣属，属官。在：问候。
阚闳（kàn hóng）：指馆舍的大门。
完：同“院”，指墙垣。茸：用草盖墙。
共命：供给宾客所求。
请命：请问理由。丐（gài）：古同“丐”。
诛求：责求，勒索贡物。无时：没有定时。
会：朝会。时事：随时朝贡的事。
输币：送上财物。
暴露：露天存放。
荐陈：呈献并当庭陈列。
卑庳（bì）：低小。
观：门阙。台：土筑高坛。
公寝：国君住的宫室。
司空：负责建筑的官员。平易：平整。
圬人：泥水工匠。塓（mì）：涂墙，粉刷。
甸：甸人，掌管柴火的官。庭燎：庭中照明的火炬。
巾车：管理车辆的官。脂：指加油。辖。车轴头的挡铁。
隶人：清洁工。瞻：看管。
不留宾：不让来客滞留。
菑：同“灾”。
缇（tí）之宫：晋侯的别宫，一在今山西沁县西南。
天疠（lì）：天灾。不戒：无法防备。
惮（dàn）：怕。
赵文子：晋国大夫赵武。信：确实，可信。
垣：这里指房舍。赢：接待。
加礼：礼节特别隆重。宴：宴会。好：指宴会上送给宾客的礼物。
释辞：放弃辞令。
“辞之辑矣，民之协矣；辞之怿矣，民之莫矣。”：这四句诗出自《诗·大雅·板》。辑：和顺。协：融洽。绎：同“怿’，喜悦。莫：安定。', '子产辅佐郑简公到晋国去，晋平公因为鲁国有丧事的缘故，没有接见他们。子产派人把宾馆的围墙全部拆毁，把自己的车马放进去。
晋国大夫士文伯责备子产说：“敝国由于政事和刑罚没有搞好，到处是盗贼，不知道对辱临敝国的诸侯属官怎么办，因此派了官员修缮来宾住的馆舍，馆门造得很高，围墙修得很厚，使宾客使者不会感到担心。现在您拆毁了围墙，虽然您的随从能够戒备，那么对别国的宾客怎么办呢？由于敝国是诸侯的盟主，修建馆会围墙，是用来接待宾客。如果把围墙都拆了，怎么能满足宾客的要求呢？我们国君派我来请问你们拆墙的理由。”子产回答说：“敝国国土狭小，处在大国的中间，大国责求我们交纳贡物没有一定时候，所以我们不敢安居度日，只有搜寻敝国的全部财物，以便随时前来朝见贵国。碰上您没有空，没能见到，又没有得到命令，不知道朝见的日期。我们不敢进献财物，又不敢把它们存放在露天。要是进献上，那就成了贵国君王府库中的财物，不经过陈列聘享礼物的正式仪式，那是不敢奉献的。如果把礼物放在露天里，又怕日晒雨淋而腐烂生虫，加重敝国的罪过。我听说文公从前做盟主时，宫室低小，没有门阙和台榭，”却把接待宾客的馆舍修得十分高大，宾馆像国君的寝宫一样。仓库和马棚也修得很好，司空按时平整道路，泥水工匠按时粉刷馆舍房间；诸侯的宾客来到，甸人点起庭院中的火把，仆人巡视客舍，存放车马有地方，宾客的随从有代劳的人员，管理车辆的官员给车轴加油，打扫房间的，伺养牲口的，各自照看自己份内的事；各部门的属官要检查招待宾客的物品；文公从不让宾客们多等，也没有被延误了的事；与宾客同忧共乐，出了事随即巡查，有不懂的地方就指教，有所要就加以接济。宾客到来就好像回到家里一样，哪里会有灾患啊；不怕有人抢劫偷盗，也不用担心干燥潮湿。现在晋侯的缇别宫方圆数里，却让诸侯宾客住在像奴仆住的房子里，车辆进不了大门，又不能翻墙而入；盗贼公然横行，天灾难防。接见宾客没有定时，召见命令也不知何时发布。如果还不拆毁围墙，就没有地方存放礼品，我们的罪过就要加重。斗胆请教您，您对我们有什么指示？虽然贵国遇上鲁国丧事，可这也是敝国的忧伤啊。如果能让我们早献上礼物，我们会把围墙修好了再走，这是贵君的恩惠，我们哪敢害怕辛劳？”士文伯回去报告了。
赵文子说：“的确是这样。我们实在不注重培养德行，用像奴仆住的房舍来招待诸侯，这是我们的过错啊；”于是，他派士文伯前去道歉，承认自己不明事理。
晋平公以隆重的礼节接见了郑简公，宴会和礼品也格外优厚，然后让郑简公回国。晋国接著建造了接待诸侯的宾馆。叔向说：“辞令不可废弃就是这样的啊！子产善于辞令，诸侯靠他的辞令得到了好处，为什么要放弃辞令呢？《诗.大雅.板》中说：‘言辞和顺，百姓融洽；言辞动听，百姓安宁。’子产大概懂得这个道理吧。”', NULL, '晋为霸主非一世，诸侯之馆虽狭，从来藏币亦不止郑伯一人，何至于毁垣？即毁亦不须尽毁。子产只为晋侯以鲁丧不见客，若不如此一番作用，无以致其诘责而尽其辞，使得荐币而行耳。文伯之让，全在“寇盗”上立论，侃侃而谈，似难置对。子产则闲闲叙出朝晋从不敢宁居而来，何等敬慎！晋侯未见，亦不知见期，何等傲慢！以其无所藏币，输之既恐失已，暴露又恐招尤，何等进退两难！再将文公待诸侯处细细叙述，而以铜鞮隶人等语对看，件件霄壤，以能令继霸者无处生矣。然后说出鲁丧之忧，郑以同姓与晋无异，原不必为此留宾弗见，待既见荐币之后，以所馆之垣，自坏自修，不烦晋力，而隶人之馆自若，犹可赢诸侯。文伯所让之语不过为此，今已如此，他复何说？其词之委婉处，带有许多冷刺，宜赵文子之谢罪，晋侯之加礼也。至于筑馆一节，实出子产意外，故叔向云“诸侯赖之”，言其驰词之功，所及远者。非子产以毁垣欲使晋筑馆也，此毫厘千里之辨，细读叔向赞语当自得之。（清·林云铭《古文析义初编》卷二）
“读其文连性情、心术、声音、笑貌，千载如生。”（冯李骅）', 'indent', 1575393717, '5de629307796d90076cdcbbc', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643662, '子产论尹何为邑', NULL, 3, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '子皮欲使尹何为邑。子产曰：“少，未知可否。”子皮曰：“愿，吾爱之，不吾叛也。使夫往而学焉，夫亦愈知治矣。”子产曰；“不可。人之爱人，求利之也。今吾子爱人则以政。犹未能操刀而使割也，其伤实多。子之爱人，伤之而已，其谁敢求爱于子？子于郑国，栋也。栋折榱崩，侨将厌焉，敢不尽言？子有美锦，不使人学制焉。大官大邑，身之所庇也，而使学者制焉。其为美锦，不亦多乎？侨闻学而后入政，未闻以政学者也。若果行此，必有所害。譬如田猎，射御贯，则能获禽；若未尝登车射御，则败绩厌覆是惧，何暇思获？
子皮曰：“善哉！虎不敏。吾闻君子务知大者、远者，小人务知小者、近者。我，小人也。衣服附在吾身，我知而慎之；大官、大邑，所以庇身也，我远而慢之。微子之言，吾不知也。他日我曰：‘子为郑国，我为吾家，以庇焉，其可也。’今而后知不足。自今请虽吾家，听子而行。”子产曰：“人心之不同，如其面焉。吾岂敢谓子面如吾面乎？抑心所谓危，亦以告也。”子皮以为忠，故委政焉。子产是以能为郑国。', '本文出自《左传·襄公三十一年》。文章讲述了子产说服子皮不要任命年轻家臣为邑的事情。子产通过形象生动的比喻向子皮阐明对没有管理经验的年轻人委以重任的危害，应该让年轻人尹何积累丰富的知识和经验后再去从政。全文围绕用人问题展开对话，人物形象鲜明突出，语言简练畅达，叙述线索清晰，善用比喻，层层论证，令人信服。', '子产：即公孙侨，郑国大夫。尹何：子皮的年轻家臣。为：治理。邑：封邑，采邑。
子皮：郑国大夫，名罕虎，公孙舍的儿子。
少（shào）：年轻。
愿（yuàn）：谨慎老实。不吾叛也：上古汉语用“不”等否定词的否定句，宾语如果是一个代词，一般放在动词的前面，如“吾”是动词“叛”的宾语，放在“叛”的前面。
夫：人称代词，他。下句的“夫”同。治：治理，管理。
利之：使之有利。
其：难道。用于句首，表示反问。
栋：栋梁。
榱（cuī）：屋椽。侨：子产名。厌（yā）：通“压”。下文“厌覆”的“厌”同。尽言：无保留地把话说出来。
锦：有彩色花纹的绸缎。
庇（bì）：庇护，寄托。其为美锦，不亦多乎：它比起美锦来价值不就更多吗？这是说官邑重于美锦。
入政：参加管理政务。以：靠，凭借。
田猎：打猎。射御：射箭驾车。贯：通“惯”，习惯，熟习。禽：通“擒”。也可作名词讲，指鸟兽。
尝：曾。败绩厌覆是惧：即“惧败绩厌覆”。这是为了强调宾语“败绩厌覆”，把宾语提前，在宾语后面用“是”字复指。败绩，指事情的失利。厌覆，指乘车的人被倾覆辗压。
虎：子皮名。敏：聪明。
务：致力。
远：疏远，疏忽。慢：轻视。
微：无，非。
他日：从前。家：卿大夫的采地食邑。
请：请求。听：听凭。行：做。
抑（yì）：不过，然而。表示转折的连词。
子皮以为忠：子皮以子产为忠。
是以：因此。', '子皮想让尹何治理一个采邑。子产说：“尹何年轻，不知能否胜任。”子皮说：“这个人忠厚谨慎，我喜爱他，他一定不会背叛我的。让他到那里学习一下，就会更加懂得治理政事的方法。”子产说：“不行。一个人假如真正喜爱别人，那就应该让他得到好处。现在您喜爱别人，就想让他来管理政事，这就如同让一个还不会拿刀的人去割肉一样，多半会割伤自己。您的所谓爱人，只不过是伤害人家罢了，那么以后谁还敢求得您的喜爱呢？您在郑国如同房屋的栋梁，栋梁折断了，屋椽自然要崩塌，我也会被压在屋子底下，因此怎敢不把自己的全部想法说出来呢！譬如您有一块美丽的锦缎，您一定不肯让人用它来练习剪裁衣服。担任大官、治理大邑，这些都是人们身家性命之所寄托，却让一个正在学习的人来担当。大官大邑与美丽的锦缎相比，不是更加贵重吗？我只听说过学好了然后才去管理政事，没听说过就用治理政事的方式来让他学习的。如果真这么做，一定会受到危害。比方打猎吧，射箭、驾车这一套练熟了，才能猎获禽兽；假若从来就没有登过车、射过箭和驾过车，总是为翻车发生事故而提心吊胆，那么，哪里还顾得上猎获禽兽呢？”
子皮说：“太好了！我这个人很笨。我听说过，君子总是努力使自己懂得那些重大的遥远的事情，小人总是使自己懂得那些微小的眼前的事情。我是个小人啊！衣服穿在我身上，我是知道加以爱惜的；大官、大邑，这是身家性命之所寄托，我却认为是遥远的事情而忽视它。假如没有您这番话，我是不会懂得这个道理的。从前我说过：‘您治理郑国，我治理我的封地，在您的庇荫之下，还是可以把封地治理好的。’从现在起才知道，这样做还是不够的。从今以后我请您允许，就是治理我的封地，也要听您的意见行事。”子产说：“人心的不同，就像人的面貌一样。我怎敢说您的面貌同我的一样呢？不过我心里认为危险的事情，还是要奉告的。”子皮认为子产非常忠实，所以就把郑国的政事委托给他。子产因此才能治理郑国。', NULL, '宋·叶适：“子皮才智不如子产，而子产为其所用也。用人之弘乃多于其人之自用，此理当深察也。”（《习学记言序目》卷十一）
清·金圣叹：“欲作缠绵贴肉之文，须千遍烂读此文，非责其文辞，贵其心地也。此文只是一片心地。”（《天下才子必读书》卷二）
清·林云铭：“以大官大邑关系庇身，使人学治，不但学者受伤，而且学者受害也不小。子产即其所言层层反驳，妙在四引喻中，炼成一片，绝无痕迹，宜子皮之称善而自咎也。”（《古文析义初编》卷一）
清·吴楚材、吴调侯：“‘学而后入政，未闻以政学’二语是通体结穴，前后总是发明此意。子产倾心吐露，子皮从善若流，相知之深，无过于此。全篇纯以譬喻作态，故文势宕逸不群。”（《古文观止》卷二）
清·过珙：“文莫难于设喻，此篇叠设六喻：操刀使割一喻也；栋折榱崩二喻也；制锦三喻也；田猎射御四喻也；子皮悦其言，以衣服附身为喻；子产申其说，又以子面、吾面为喻。此种文字，最是难学。”（《古文评注全集》卷二）
清·冯李骅、陆浩：“此篇只‘学而后入政’二句为大旨，若就正意发挥，亦自有一首绝大文字。却偏将正话只于中间一见，前后都用譬喻指点，语语入理，又语语入情，不作一味板腐大话头，最是生新出色处，开后人大题小做法门。左氏真无妙不臻，有奇必借者矣。”（《左绣》卷二十）
清·唐德宜：“‘爱’、‘使’、‘学’三字，层层批剥，节节引喻，极水乳交融之趣。”（《古文翼》卷二）
清·周大璋：“以年少不学之子，而使之为邑，既伤其人，又害其邑，两失之道也。才见一事，便曲曲折折，披肝露胆，具陈其可否，此之谓尽心。才闻一言，便委委婉婉，怡声下气，痛改其迷悟，此之谓虚怀。千古友谊，若此两人者，吾未多见也。他日子皮卒，子产出涕曰：‘吾无为善矣！惟夫子知我必如此，而后为知我我知岂易言哉！’”（《左传翼》卷二十四）
清·王源：“子产能言，左氏善序，故写得婉畅切挚，曲折缠绵，使读者魄动心驰。千载下，如亲炙其徽，而聆其娓娓，何其妙也！有子皮之贤，而后子产能为郑国，垂训深切著明，可为千古谋国者龟鉴。共用五喻，层叠、芊眠，点染生动，最耐看。”（《左传评》卷七）
清·姚永概：“此文是写子皮，杜注当矣。文字非常华妙，其华处全在善用譬喻。操刀，一譬也；栋榱，二譬也；制锦，三譬也；田猎，四譬也。层叠说来，五光十色，令人目眩。末段又恐冷淡不相称，乃用心、面渲染之，方不寂寞。此文家灵巧秘诀，至描画子皮好善，口角亦津津有味。”（《左传讲义》手稿本）', 'indent', 1575394182, '5de62b03844bb40071f2876c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643663, '子产却楚逆女以兵', NULL, 3, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '楚公子围聘于郑，且娶于公孙段氏。伍举为介。将入馆，郑人恶之。使行人子羽与之言，乃馆于外。
既聘，将以众逆。子产患之，使子羽辞曰：“以敝邑褊小，不足以容从者，请墠听命！”令尹使太宰伯州犁对曰：“君辱贶寡大夫围，谓围：‘将使丰氏抚有而室。’围布几筵，告于庄、共之庙而来。若野赐之，是委君贶于草莽也！是寡大夫不得列于诸卿也！不宁唯是，又使围蒙其先君，将不得为寡君老，其蔑以复矣。唯大夫图之！”子羽曰：“小国无罪，恃实其罪。将恃大国之安靖己，而无乃包藏祸心以图之。小国失恃而惩诸侯，使莫不憾者，距违君命，而有所壅塞不行是惧！不然，敝邑，馆人之属也，其敢爱丰氏之祧？”
伍举知其有备也，请垂櫜而入。许之。', '本文出自《左传·昭公元年》。内容叙述了楚国假借联姻攻打郑国的图谋，而被郑国子产瓦解的故事。', '公子围：楚康王的弟弟，当时担任令尹（楚国掌握军政大权的最高官员。
公孙段氏：郑大夫，名子石。
伍举：又称椒举，伍子胥的祖父。介：副使。
恶：讨厌、憎恨。
行人：官名。管朝觐聘问之事。类似于后世的外交官。
逆：迎。
墠（shàn）：郊外祭祀的场地。
令尹：指公子围。太宰：官名，掌管王家内外事务。伯州犁：楚人。
贶（kuàng）：赠送，赐予。寡大夫：对于他国自称本国大夫的谦词。
丰氏：即公孙段氏。公孙段食邑一丰，故称丰氏。而，通“尔”，你。“抚有而室”，就是做妻室。“将使丰氏抚有尔室”是引郑君的话。
布：设置。几筵：古时的一种祭席。
庄、共：楚庄王、共王。庄王是公子围的祖父，共王是他的父亲。
若野赐之：意谓在城外成婚礼。
蒙：欺。先君，指庄王、共王。
老：大臣。
恃：指依靠大国而自己无防备。
靖：安定。
而：同“尔”，你。包藏祸心：外表和好，心怀恶意。
惩：警戒。
距：同“拒”。壅塞：阻塞不通。
馆人：管理客馆、招待宾客的人。
祧（tiāo）：远祖的庙。
櫜（gāo）：盛弓箭的袋子。垂櫜：表示袋子里没有装弓箭之类的武器。', '楚国公子围到郑国聘问，同时迎娶公孙段家的女儿。伍举担任副使。他们正准备住进城内宾馆，郑国人怀疑他们有诈，派行人子羽同他们说了，于是住在城外的馆舍。
聘问结束以后，公子围准备带领军队前去迎亲。子产担心这件事，派子羽推辞，说：“由于敝国地方狭小，容纳不下随从的人，请允许我们在城外修整祭祀的地面听候命令。”公子围派太宰伯州犁回答说：“辱蒙君王赏赐敝国大夫围，告诉围说‘将让丰氏作你的妻室’。围摆设了祭筵，在庄王、共王的宗庙视告后才来。如果在野外赐给围，这是将君王的赏赐抛在了草丛里，这就使敝国大夫围不能置身于卿大夫们的行列了。不仅是这样，更使围欺骗自己的先君，将不能再作敝国国君的大臣，恐怕也无法向敝国国君复命了。希望大夫考虑这件事。”子羽说：“小国没有罪，依赖大国才真正是它的罪过。本来打算依赖大国安定自己，又恐怕他们包藏祸心来图谋自己。敝国唯恐小国失去依赖，致使诸侯心怀戒备，使他们莫不怨恨大国，抗拒违背君王的命令，从而使大国的命令不能贯彻，无法施行。要不是这个原因，敝国是替贵国看守馆舍的，岂敢爱惜丰氏的宗庙而不让入内？”
伍举知道郑国有了防备，就请求让军队垂下箭囊入城。郑国同意了。', NULL, '', 'indent', 1575394941, '5de62df6844bb40071f2abc5', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643664, '子革对灵王', NULL, 4, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '楚子狩于州来，次于颍尾，使荡侯、潘子、司马督、嚣尹午、陵尹喜帅师围徐以惧吴。楚子次于乾溪，以为之援。雨雪，王皮冠，秦复陶，翠被，豹舄，执鞭以出，仆析父从。
右尹子革夕，王见之。去冠被，舍鞭，与之语曰：“昔我先王熊绎与吕伋、王孙牟、燮父、禽父，并事康王，四国皆有分，我独无有。今吾使人于周，求鼎以为分，王其与我乎？”对曰：“与君王哉！昔我先王熊绎，辟在荆山，筚路蓝缕，以处草莽，跋涉山林，以事天子，唯是桃弧、棘矢，以共御王事。齐，王舅也；晋及鲁、卫，王母弟也。楚是以无分，而彼皆有。今周与四国服事君王，将唯命是从，岂其爱鼎？”王曰：“昔我皇祖伯父昆吾，旧许是宅。今郑人贪赖其田，而不我与。我若求之，其与我乎？”对曰：“与君王哉！周不爱鼎，郑敢爱田？”王曰：“昔诸侯远我而畏晋，今我大城陈、蔡、不羹，赋皆千乘，子与有劳焉。诸侯其畏我乎？”对曰：“畏君王哉！是四国者，专足畏也，又加之以楚，敢不畏君王哉？”
工尹路请曰：“君王命剥圭以为鏚柲，敢请命。”王入视之。析父谓子革：“吾子，楚国之望也！今与王言如响，国其若之何？”子革曰：“摩厉以须，王出，吾刃将斩矣。”
王出，复语。左史倚相趋过。王曰：“是良史也，子善视之。是能读《三坟》、《五典》、《八索》、《九丘》。”对曰：“臣尝问焉，昔穆王欲肆其心，周行天下，将皆必有车辙马迹焉。祭公谋父作《祈招》之诗，以止王心，王是以获没于祗宫。臣问其诗而不知也；若问远焉，其焉能知之？”王曰：“子能乎？”对曰：“能。其《诗》曰：‘祈招之愔愔，式昭德音。思我王度，式如玉，式如金。形民之力，而无醉饱之心。’”
王揖而入，馈不食，寝不寐，数日。不能自克，以及于难。
仲尼曰：“古也有志：‘克己复礼，仁也。’信善哉！楚灵王若能如是，岂其辱于乾溪？”', '本文出自《左传·昭公十二年》。', '雨雪：下雪。
皮冠：皮帽。秦复陶：秦国赠的羽衣。翠被：用翠羽装饰的披肩。舄：鞋。
仆析父：楚大夫。
右尹：官名。夕：晚上谒见。
舍：放下。
熊绎：楚国始祖。
吕伋：王孙牟、燮父、禽父：齐、卫、晋、鲁四国的始祖。康王：即周康王，周王第三代。
四国：指齐、卫、晋、鲁。
鼎：夏、商、周三代视为传国之宝。
辟：同“僻”。荆山：楚人的发祥地，今湖北南漳县西。
筚路：柴车。蓝缕：破烂的衣服。
桃弧棘矢：桃木做的弓，棘木（酸枣木）做的箭。
共：同“供”。
齐，王舅也：周成王的母亲是姜太公的女儿。
昆吾：楚的远祖，曾住在许地。许：周初分封的诸侯国。
陈、蔡：本为周武王所封的诸侯国，后来为楚所灭。不羹：地名，有东西二邑。赋：指兵车。
四国：指陈、蔡、和东西不羹。', '楚灵王到州来冬猎，驻扎在颍尾，派荡侯、潘子、司马督、嚣尹午、陵尹喜率领军队包围徐国以恐吓吴国。楚王驻扎在乾溪，作为他们的后援。天下雪，楚王戴皮帽，穿秦国羽衣，翠鸟羽毛的披肩，豹皮鞋，握鞭而出。仆析父跟随着。
子革晚上进见，楚王会见他，脱去帽子、披风，丢掉鞭子，和他谈话，说：“从前我们先王熊绎与齐国的吕伋、卫国的王孙牟、晋国的燮父、鲁国的伯禽同时事奉周康王，四国都有分赐的宝器，唯独我国没有。现在我派人到周室，要求将九鼎作为分赐绐我国的宝器，周王会给我吗？”于革回答说：“会给君王啊！从前我们先王熊绎在偏僻的荆山地方，柴车破衣，居于草野，跋涉山林，事奉天子，只有这桃木做的弓、枣木做的箭来供奉王室大事之用。齐，是周王的舅父；晋及鲁、卫，是周王的同母兄弟。楚国因此没有分赐到宝器，而他们都有。现在周室与上述四国都服侍君王，将会唯命是从，岂会吝惜九鼎？”楚王说：“从前我们的远祖伯父昆吾，住在许国旧地，现在郑国人贪图那里的田地有利，而不给我们。我们如果向他们要求，会给我们吗？”子革回答说：“会给君王啊！周室不吝惜九鼎，郑因岂敢吝惜田地？”楚王说：“从前诸侯认为我国偏远而畏惧晋国，现在我们大力修筑陈、蔡、东、西不羹四个城邑，兵赋都达到兵车一千辆，你参与其事是有功劳的，诸侯会畏惧我们吗？”子革回答说：“会畏惧君王啊！单这四大城邑，已足以使人畏惧了，再加上楚国，岂敢不畏惧君王吗！”
工尹路请示说：“君王命令破开圭玉装饰斧柄，冒昧请君王指示。”楚王进去察看。仆析父对于革说：“您，是楚国有声望的人，现在和君王说话好象回声一样应和，国家会怎么样呢？”子革说：“我磨快言语的刀刃以待时机，君王出来，我的刀刃就将砍下去了。”
楚王出来，又接着谈话。左史倚相从面前小步快速走过，楚王说：“这个人是好史官，你要好好看待他。这个人能读《三坟》、《五典》、《八索》、《九丘》这样的古书。”子革回答说：“下臣曾经问过他，从前周穆王想要随心所欲，走遍天下，要使天下都留有他的车辙马迹。祭公谋父作了《祈招》的诗篇来制止穆王的贪心，穆王因此能在祇宫寿终正寝。下臣问他诗句却不知道。如果问年代久远的事，他怎能知道？”楚王说：“你能吗？”子革回答说：“能。那首诗说：‘《祈招》的音乐和谐，表现了美德的声音。想起我们君王的气度，似玉，似金。保全百姓的力量，而没有象醉饱一样的贪心。”
楚王作了一揖就进去了，有好几天，送上饭不吃，躺下睡不着，还是不能自己克制，以致遇到祸难。
孔子说：“古时有记载说：‘克制自己，回到礼仪上来，这就是仁。’说得真好啊！楚灵王如果能象这样，岂会在乾溪受辱？”', NULL, '', 'indent', 1575475838, '5de769e65620710076adee32', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643665, '子产论政宽猛', NULL, 4, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '郑子产有疾。谓子大叔曰：“我死，子必为政。唯有德者能以宽服民，其次莫如猛。夫火烈，民望而畏之，故鲜死焉。水懦弱，民狎而玩之，则多死焉，故宽难。”疾数月而卒。
大叔为政，不忍猛而宽。郑国多盗，取人于萑苻之泽。大叔悔之，曰：“吾早从夫子，不及此。”兴徒兵以攻萑苻之盗，尽杀之，盗少止。
仲尼曰：“善哉！政宽则民慢，慢则纠之以猛。猛则民残，残则施之以宽。宽以济猛；猛以济宽，政是以和。”《诗》曰：‘民亦劳止，汔可小康；惠此中国，以绥四方。’施之以宽也。‘毋从诡随，以谨无良；式遏寇虐，惨不畏明。’纠之以猛也。‘柔远能迩，以定我王。’平之以和也。又曰：‘不竞不絿，不刚不柔，布政优优，百禄是遒。’和之至也。”
及子产卒，仲尼闻之，出涕曰：“古之遗爱也。”', '本文出自《左传·昭公二十年》。', '服：使…服从。
取：同“聚”。
萑苻（huán fú）：芦苇丛生的水泽，代指强盗出没的地方。
汔（qì）：接近，差不多。
从：同“纵”。
诡随：放肆谲诈。
絿（qiú）：急，急躁。
遒：迫近，聚集。
慢： 对上司无理。', '郑国的子产得了病。他对子大叔说：“我死以后，您必定主政。只有道德高尚的人能够用宽厚的政策使民众服从，其次的政策没有比刚猛更有效的了。比如烈火，民众望见就害怕它，所以很少死在其中的。水柔弱，民众亲近并和它嬉戏，就很多死在其中的，所以宽厚的政策难以实施。”子产病数月后死去。
大叔执政，不忍心严厉，而施行宽柔政策。郑国因此很多盗贼，他们从沼泽地招集人手。大叔后悔了，说：“我早听从子产夫子的，不会到此地步。”发步兵去攻击沼地的盗贼，将他们全部杀灭，盗贼才稍微被遏止。
孔子说：“好啊！政策宽厚民众就怠慢，民众怠慢就用刚猛的政策来纠正。政策刚猛民众就受伤害，民众受伤害了就施与他们宽厚的政策。用宽大来调和严厉；用严厉来补充宽大，政治因此而调和。《诗经》中说：‘民众也劳累了，差不多可以小小休息啦；赐予城中的民众恩惠，用来安抚四方。’这是施与民众以宽厚啊。‘不要放纵奸诈，用来防范邪恶；遏止盗贼肆虐，恶毒是不害怕美好的。’这是用刚猛来纠正啊。‘宽柔对待远方的民众能够使大家亲近，这样来稳定我们的王朝。’这是用和缓的政策来使民众平安祥和啊。还有《诗》说：‘不争斗不急躁，不刚猛不柔弱，实施政策平和，所有的福祉汇集过来。’这是和平的极致啊。”
等到子产逝世，孔子听说了，哭泣道：“他是古代圣贤继承人啊，继承了古人仁爱的遗风啊！”', NULL, '', 'indent', 1575478077, '5de772ba546eaa0071fadb2d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643666, '吴许越成', NULL, 5, 300, 0, 1, '左丘明', NULL, 10409, '58120b182f301e005c60f7d9', '周', 'wen', '文', '', '', '吴王夫差败越于夫椒，报槜李也。遂入越。越子以甲楯五千保于会稽，使大夫种因吴太宰嚭以行成。
吴子将许之。伍员曰：“不可。臣闻之：‘树德莫如滋，去疾莫如尽。’昔有过浇杀斟灌以伐斟鄩，灭夏后相。后缗方娠，逃出自窦，归于有仍，生少康焉，为仍牧正。惎浇能戒之。浇使椒求之，逃奔有虞，为之庖正，以除其害。虞思于是妻之以二姚，而邑诸纶，有田一成，有众一旅。能布其德，而兆其谋，以收夏众，抚其官职；使女艾谍浇，使季杼诱豷，遂灭过、戈，复禹之绩。祀夏配天，不失旧物。今吴不如过，而越大于少康，或将丰之，不亦难乎？勾践能亲而务施，施不失人，亲不弃劳，与我同壤而世为仇雠。于是乎克而弗取，将又存之，违天而长寇雠，后虽悔之，不可食已。姬之衰也，日可俟也。介在蛮夷，而长寇雠，以是求伯，必不行矣。”
弗听。退而告人曰：“越十年生聚，而十年教训，二十年之外，吴其为沼乎！”', '本文出自《左传·哀公元年》。', '夫差：吴国国君，吴王阖闾的儿子。夫椒：在今江苏吴县太湖中，即包山。
槜李：吴、越边界地名。今浙江嘉兴县一带。定公十四年，越曾大败吴军于此地。
越子：越王勾践。楯：盾牌。会稽：山名。在今浙江绍兴市。
种：文种，越大夫。太宰：官名。嚭：吴国大臣名，善于逢迎，深得吴王夫差宠信。
伍员：即伍子胥，吴国大夫。
滋：滋长。尽：断根。
过：夏朝国名，今山东掖县北。浇：人名。寒浞的儿子。斟灌：夏时国名，今山东寿光县东北。斟鄩：夏朝国名，今山东潍县西南。夏后相：夏朝第五代王，少康的父亲。后缗：夏后相的妻子。娠：怀孕。窦：孔穴。
有仍：国名，今山东济宁县。后缗是有仍国的女儿，所以逃归娘家。
少康：夏后相的遗腹子。牧正：主管畜牧的官。惎：憎恨。戒：警戒。
椒：浇的大臣。有虞：姚姓国，今山西永济县。庖正：掌管膳食的官。
虞思：虞国的国君。纶：地名，今河南虞城县东南。成：方十里。旅：五百人。伯：同“霸”。
女艾：少康臣。谍：暗地察看。季杼：少康的儿子。豷：浇的弟弟。戈：豷的封国。
长：助长。
不可食：吃不消。
姬：吴与周王朝同姓，姬姓国之一。
日可俟也：犹言指日可待。俟：等待。', '吴王夫差在夫椒打败越军，报了槜李之仇，趁势攻进越国。越王勾践带领披甲持盾的五千人守住会稽山，并派大夫文种，通过吴国的太宰嚭向吴王求和。吴王打算答应他。
伍员说：“万万不可！臣听说：‘树立品德，必须灌溉辛勤；扫除祸害，必须连根拔尽’。从前过国的浇，杀了斟灌又攻打斟鄩，灭了夏王相。相的妻子后缗方怀孕，从城墙的小洞里逃走，回到有仍，生了少康。少康后来做了有仍的牧正，他对浇恨极了，又能警惕戒备。浇派椒四处搜寻少康，少康逃奔有虞，在那里做了庖正，躲避祸害。虞思两个女儿嫁给他，封他在纶邑，有田一成，不过十里，有众一旅，不过五百。但他能布施德政，开始谋划，收集夏朝的余部，使其专心供职。他派女艾去浇那里刺探消息，派季舒去引诱浇的弟弟豷，终于灭亡过国和戈国，恢复夏禹的功业，祭祀夏的祖先，以配享天帝，维护了夏朝的天命。现在吴国不如过国，越国却大于少康，如果让越国强盛起来，吴国岂不就难办了吗？勾践这个人能够亲近臣民，注重施布恩惠。肯施恩惠，就不失民心；亲近臣民，就不会忽略有功之人。他与我国土地相连，世代有仇，现在我们战胜了他，不但不加以消灭，反而打算保全他，这真是违背天命而助长仇敌，将来后悔也来不及了！姬姓的衰亡，指日可待呀。我国处在蛮夷之间，而又助长仇敌，这样谋霸业，行不通啊！”
吴王不听。伍员退下来，对人说：“越国用十年时间聚集财富，再用十年时间教育和训练人民，二十年后，吴国的宫殿怕要变成池沼啊！”', NULL, '', 'indent', 1575478335, '5de773ad43c25700686b2278', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643693, '光华殿侍宴赋竞病韵', NULL, 1, 1, 2, 1, '曹景宗', NULL, 36008, '5858fcf91b69e6006cb1b190', '南北朝', 'shi', '诗', '', '', '去时儿女悲，归来笳鼓竞。
借问行路人，何如霍去病？', '', '', '', '[{"bookId": "60fc57df23353c0ba53df85e", "bookTitle": "汉魏六朝诗鉴赏辞典（新一版）", "articleId": "610eccc50f8fda5565060f28", "shortContent": "这首出自梁朝大将曹景宗之手的诗，是这位并无多少文化修养的武人留下的唯一作品，严格地说，它还不算一首诗，只是联句中的一小部分。关于其写作经过，《南史·曹景宗传》有如下记载：“景宗振旅凯入，帝于华光殿宴饮连句，令左仆射沈约赋韵。景宗不得韵，意色不平，启求赋诗。帝曰：‘卿技能甚多，人才英拔，何必止在一诗？’景宗已醉，求作不已。诏令约赋韵。时韵已尽，唯余‘竞’、‘病’二字。景宗便操笔，斯须而成，其辞曰云云...", "authors": ["鲁同群"], "pressName": "上海辞书出版社"}]', '', 'center', 1577093269, '5e00180f7796d900688e5968', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643696, '和通判弟随亨《书感》韵', NULL, 0, 71, 1, 0, '柴望', NULL, 29705, '5858f73a8e450a006cbac439', '宋', 'shi', '诗', 'https://baike.baidu.com/item/%E5%92%8C%E9%80%9A%E5%88%A4%E5%BC%9F%E9%9A%8F%E4%BA%A8%E4%B9%A6%E6%84%9F%E9%9F%B5/19835518', '', '风沙万里梦堪惊，地老天荒只此情。
世上但知王蠋义，人间惟有伯夷清。
堂前旧燕归何处，花外啼鹃月几更。
莫话凄凉当日事，剑歌泪尽血沾缨。', '这是作者在南宋亡后写的一首伤悼故国的七律。他的弟弟随亨写了一首题为“书感”（内容当亦抒写故国沦亡之痛）的诗，这是和《书感》原韵之作。通判，是州郡官吏，地位略次于州府长官。', '', '', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea74703048e64fbd96cb6", "shortContent": "这是作者在南宋亡后写的一首伤悼故国的七律。他的弟弟随亨写了一首题为“书感”（内容当亦抒写故国沦亡之痛）的诗，这是和《书感》原韵之作。通判，是州郡官吏，地位略次于州府长官。\n“风沙万里梦堪惊，地老天荒只此情。”起联以沉痛之情、隐约之词抒写亡国之恨，正点题目“书感”。风沙万里，隐指恭帝德祐二年（1276），临安沦陷，皇帝、太后、妃嫔等尽被元人俘虏北去。地老天荒，极言时间的久远。两句是说，回想当年，国破...", "authors": ["刘学锴"], "pressName": "上海辞书出版社"}]', '', 'center', 1577354221, '5e041365dd3c13006a01e631', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643736, '读书有三到', NULL, 30, 1475, 0, 3, '朱熹', NULL, 10015, '57b936ccc4c971005590f2c8', '宋', 'wen', '文', '', '', '余尝谓：读书有三到，谓心到，眼到，口到。心不在此，则眼不看仔细，心眼既不专一，却只漫浪诵读，决不能记，记亦不能久也。三到之中，心到最急。心既到矣，眼口岂不到乎？', '《训学斋规》节选。读书有三到，就是心到、眼到、口到。心思不在书本上，那么眼睛就不会看仔细，既然心思不集中，就只能随随便便地诵读，绝对记不住，即使记住了也不能长久。三到之中，心到是最重要的。', '余：我。
尝：曾经。
谓：说。
此：这里。
漫浪：随随便便。
决：一定。
急：迫切、重要。
矣：相当于“了”。
岂：难道。
乎：吗，语气词。', '我曾经说：读书讲究“三到”，即读书时要专心，要认真看，要诵读。心思不在书本上，那么眼睛就不会仔细看；心和眼既然没有专注统一，却只是随随便便地读，那么一定不会记住，就算记住了，也记不长久。这三到中，心到最重要。若心神集中了，眼和口还会不集中吗？', NULL, '朱熹是南宋时期理学大家，又是著名的教育家。他一生大部分时间都在读书和教书，提出过许多精辟的见解。他死后不久，弟子们将他的读书经验归纳为六条，称为"朱子读书法"，对于今人，仍有启示和借鉴的作用。
【循序渐进】
朱熹说："读书之法，莫贵于循守而致精。"什么是循序渐进？就是说，读书要有个先后顺序，读通一书，再读一书。就读一书而言，则要逐字逐句逐段按顺序读，先读的未弄通，就不能读后面的。这样才不会生吞活剥或杂乱无章。朱熹还进一步指出，读书要从易到难，从浅到深，从近到远，急不得，也慢不得。"所谓急不得者，功效不可急；所谓不可慢者，工夫不可慢。"这是在告诫读书人既不可急于求成，也不可松松垮垮，而要进度适当，方能见效。
【熟读精思】
他认为有些人读书收效不大，是由于在"熟"和"精"二字上下功夫不够。他还批评那种读书贪多的倾向，一再讲"读书不可贪多，且要精熟。如今日看得一板，且看半板，将那精力来更看前半板"。
【虚心涵泳】
朱熹曾批评当时普遍存在的两种毛病：一是"主私意"，就是以自己的想法去揣测书中的道理，穿凿附会，歪曲了古人本来意思。二是"旧有先人之说"，就是先前接受的观点不肯放弃，从而排斥接受新的观点。
为了纠正以上这两种不好的毛病，朱熹主张读书必须虚怀若谷，静心思虑，悉心体会作者本意。朱熹强调读书要耐心"涵泳"，就是要反复咀嚼，深刻体会行中的旨趣。
【切已体察】
朱熹主张"读书穷理，当体之于身。"什么叫"体之于身"？就是要心领神会，身体力行。从读书法的角度来看，朱熹强调读书必须联系自己，联系实际，将学到的理论转化为行动，这个观点是可取的。
【着紧用力】
"着紧用力"．包含有两个意思：一是指时间上要抓紧，要"饥忘食，渴忘饮，始得。"二是指精神上要振作．要有刚毅果决，奋发勇猛的精神。"如撑上水船，一篙不可放缓。"
【居敬持志】
所谓居敬持志，就是读书必须精神专一，全神贯注，还要有远大的志向，顽强的毅力。这也是朱熹读书之法的最基本精神。', 'indent', 1581814338, '5e482166fc36ed006aaf57e9', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643708, '陶庵梦忆 · 卷七 · 浴雪龙山', NULL, 1, 227, 0, 3, '张岱', NULL, 10007, '57ba82be165abd0066234de7', '明', 'wen', '文', '', '', '天启六年十二月，大雪深三尺许。晚霁，余登龙山，坐上城隍庙山门，李岕生、高眉生、王畹生、马小卿、潘小妃侍。万山载雪，明月薄之，月不能光，雪皆呆白。
坐久清冽，苍头送酒至，余勉强举大觥敌寒，酒气冉冉，积雪欱之，竟不得醉。马小卿唱曲，李岕生吹洞箫和之，声为寒威所慑，咽涩不得出。
三鼓归寝。马小卿、潘小妃相抱从百步街旋滚而下，直至山趾，浴雪而立。余坐一小羊头车，拖冰凌而归。', '', '霁：雨后或雪后转晴。
李岕（jiè）生：李岕生与后面五人都是当时的伶人（戏曲演员）。生，指男演员。下文的马小卿、潘小妃为女伶。
呆白：苍白。
苍头：指以青色包头巾裹头，这里指年纪大的伙计。', '天启六年的十二月，大雪有三尺多深。晚上的时候天放晴了，我登上龙山，坐在城隍庙的山门上，李岕生、高眉生、王畹生、马小卿、潘小妃这几个人陪伴伺候。
众山都被雪覆盖住了，月亮的光辉也显得稀薄了，月亮显不出光亮，雪都白花花的。坐久了觉得有点清冷，苍头送酒来了，我勉强举起大杯子抗寒，酒气上升，积雪将酒气吞噬，竟然喝不醉。
马小卿唱曲子，李岕生吹洞箫和着马小卿的曲子，声音被寒气所震慑，艰涩得出不来。三更的时候我们要回去睡觉，马小卿、潘小妃互相抱着从百步街旋转滚落，一直到山脚下，满身是雪的站着。我坐着一辆小羊头车，拖着满身的冰凌回来了。', NULL, '', 'indent', 1581206574, '5e0a1f5efc36ed006a879ba8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643730, '司马光', NULL, 47, 3, 0, 3, '脱脱', NULL, 36991, '5c1c80c39f545400706e7fc4', '元', 'wen', '文', '', '', '群儿戏于庭，一儿登瓮，足跌没水中。众皆弃去，光持石击瓮破之，水迸，儿得活。', '《宋史·司马光传》节选', '司马光：字君实，陕州夏县（现在山西）人。北宋大臣，史学家，编撰《资治通鉴》等书。
庭：庭院。
瓮：口小腹大的一种容器。
皆：全，都。
弃去：逃走。
光：指司马光。
破：打开，打破。
迸：涌出。', '司马光和一群小孩子在庭院里面玩，一个小孩站在大缸上面，失足跌落缸中被水淹没，其他的小孩子都跑掉了，只有司马光拿石头砸开了缸，水从而流出，小孩子得以活命。', NULL, '', 'indent', 1581800903, '5e47ed3e8a84ab006a1ee5fa', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643731, '守株待兔', NULL, 40, 20, 0, 3, '韩非', NULL, 36801, '589c4ae38d6d81006c808cbe', '秦', 'wen', '文', '', '', '宋人有耕者。田中有株。兔走触株，折颈而死。因释其耒而守株，冀复得兔。兔不可复得，而身为宋国笑。', '《韩非子·五蠹》节选', '株：树桩。
走：跑。
触：撞到。
折：折断。
因：于是，就。
释：放，放下。
耒（lěi）：一种农具。
冀：希望。
复：又，再。
得：得到。
身：自己。
为：被，表被动。
', '宋国有个种地的农民，他的田地中有一截树桩。一天，一只跑得飞快的野兔撞在了树桩上，折断了了脖子死了。于是，他便放下他的农具日日夜夜守在树桩子旁边，希望能再得到一只兔子。然而野兔是不可能再次得到了，而他自己也被宋国人耻笑。', NULL, '', 'indent', 1581801490, '5e47ef8e546eaa0073fd531b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643732, '精卫填海', NULL, 47, 573, 0, 3, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', '', '', '炎帝之少女，名曰女娃。女娃游于东海，溺而不返，故为精卫，常衔西山之木石，以堙于东海。', '节选自《山海经·北山经》。', '炎帝之少女：炎帝的小女儿。
溺：溺水，淹没。
故：因此。
堙：填塞。', '炎帝的小女儿，名叫女娃。有一次，女娃去东海游玩，溺水身亡，再也没有回来，因此化为精卫鸟。经常叼着西山上的树枝和石块，用来填塞东海。', NULL, '', 'indent', 1581811699, '5e48176a546eaa0073fefe5f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643733, '王戎不取道旁李', NULL, 23, 149, 0, 3, '无名氏', NULL, 10299, '57b9dcb00a2b58006cb178b9', '宋', 'wen', '文', '', '', '王戎七岁，尝与诸小儿游。看道边李树多子折枝，诸儿竞走取之，唯戎不动。人问之，答曰：“树在道边而多子，此必苦李。”取之，信然。', '《世说新语·雅量》节选', '王戎：西晋琅琊（今属山东）人，自幼聪明过人，为“竹林七贤”之一，官至尚书令，司徒。
尝：曾经。
诸：众多。
游：嬉戏玩耍。
子：李子。
折枝：压弯树枝。
竞走：争相地跑过去。
竞：争逐。
走：跑。
唯：只有。
信然：确实如此。', '', NULL, '', 'indent', 1581812497, '5e481a8e2a6bfd4d10e91aee', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643734, '囊萤夜读', NULL, 22, 377, 0, 3, '无名氏', NULL, 10156, '57b9dc73a633bd005d303896', '唐', 'wen', '文', '', '', '胤恭勤不倦，博学多通。家贫不常得油，夏月则练囊盛数十萤火以照书，以夜继日焉。', '', '囊萤：用袋子装萤火虫。
囊：文中作动词用，意思是“用袋子装”。
胤恭勤不倦：晋朝人车胤谨慎勤劳而不知疲倦。
恭：谨慎的意思。
通：通晓。
练囊：用白色绢子做袋。练：白绢，文中作动词用，意思是"用白绢做"。
以夜继日：用夜晚接着白天（学习）。', '晋朝人车胤谨慎勤劳而不知疲倦，知识广博，学问精通。他家境贫寒，不能经常得到香油。夏天的夜晚，车胤就用白绢做成透光的袋子，装几十只萤火虫照着书本，夜以继日地学习着。', NULL, '', 'indent', 1581813022, '5e481c8e21460d0077936aca', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643735, '论语三则', NULL, 20, 327, 1, 3, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '敏而好学，不耻下问。
知之为知之，不知为不知，是知也。
默而识之，学而不厌，诲人不倦。', '', '敏：聪明。
好：喜好。
耻：以……为耻。
知：同“智”，聪明，智慧。
箪（dan）:古代盛饭的圆形竹器。
陋巷：破败简陋的居住区。
堪：忍受。
《诗》：指《诗经》。
兴：抒发情志。
观：观察（社会与自然）。
群：结交朋友。
怨：讽谏怨刺（不平之事）。
迩（er）：近。
识：认识，了解，记。
厌：满足。
诲：教导。', '孔子说：“聪敏勤勉而好学，不以向地位卑下的人请教为耻。”
孔子说：“知道就是知道，不知道就是不知道，这就是一种智慧。”
孔子说：“默默地记住所学的知识，学习不觉得满足，教人不知道疲倦。”', NULL, '《论语》三则中第一则提出了学习中绝不能弄虚作假，不懂装懂，而必须坚持实事求是的正确态度。要有正确的学习态度，随时随地向别人取长补短。', 'indent', 1581813948, '5e48202543c257006aeada6d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643737, '谈读书', NULL, 21, 453, 0, 3, '曾国藩', NULL, 24361, '5858f247b123db00658ddee6', '清', 'wen', '文', '', '', '盖士人读书，第一要有志，第二要有识，第三要有恒。有志则断不甘为下流；有识则知学问无尽，不敢以一得自足，如河伯之观海，如井蛙之窥天，皆无识者也；有恒则断无不成之事。此三者缺一不可。', '', '士人：泛指知识阶层。
恒：恒心。
下流：下等，劣等。
断：副词，表示绝对、一定。', '士人读书，第一要有志向，第二要有见识，第三要有恒心。有志气则绝对不会甘心居于下等；有见识则知道学无止境，不敢稍有心得就自我满足，像河伯观海，井底之蛙观天，这都是没有见识的；有恒心则必然没有干不成的事情。有志、有识、有恒，三者缺一不可。', NULL, '', 'indent', 1581814587, '5e4822b1fc36ed006aaf5fda', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643738, '杨氏之子', NULL, 47, 43, 0, 3, '刘义庆', NULL, 10260, '57b9032cd342d3005ac73d7d', '南北朝', 'wen', '文', '', '', '梁国杨氏子九岁，甚聪惠。孔君平诣其父，父不在，乃呼儿出。为设果，果有杨梅。孔指以示儿曰：“此是君家果。”儿应声答曰：“未闻孔雀是夫子家禽。”', '《世说新语·言语》节选', '孔君平：孔坦，字君平，官至延尉。
氏：姓氏，表示家族的姓。
夫子：旧时对学者或老师的尊称。
设：摆放，摆设。
甚：非常。
诣：拜见。
未闻：没有听说过。
示：给……看。
惠：惠同“慧”，智慧的意思。
乃：就；于是。
曰：说。
未：没有。', '梁国一户姓杨的人家家里有一个九岁的儿子，非常聪明。孔君平来拜见他的父亲，恰巧他父亲不在，于是便叫他出来。他为孔君平端来水果，水果中有杨梅，孔君平指着杨梅给孩子看，并说：“这是你家的水果。”杨氏子马上回答说：“没听说孔雀是先生您家的鸟。”', NULL, '', 'indent', 1581814891, '5e4823e4546eaa0073ff587a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643740, '伯牙鼓琴', NULL, 47, 12, 0, 3, '吕不韦', NULL, 36825, '58e65ba9ac502e006c291e90', '秦', 'wen', '文', '', '', '伯牙善鼓琴，锺子期善听。伯牙鼓琴志在高山，锺子期听曰：“善哉乎鼓琴，巍巍乎若高山。”少选之间而志在流水，锺子期又曰：“善哉乎鼓琴，汤汤乎若流水。”锺子期死，伯牙破琴绝弦，终身不复鼓琴，以为世无足复为鼓琴者。', '《吕氏春秋·本味》节选。人生苦短，知音难求；云烟万里，佳话千载。纯真友谊的基础是理解。中华文化在这方面最形象最深刻的阐释，莫过于俞伯牙与钟子期的故事了。“伯牙绝弦”是交结朋友的千古楷模，他流传至今并给人历久弥新的启迪。正是这个故事，确立了中华民族高尚的人际关系与友情的标准。', '伯牙鼓琴：一说“伯牙绝弦”。
鼓：弹奏。
听：倾听。
绝：断绝。
志在高山：心中想到高山。
曰：说。
善哉：赞美之词，有夸奖的意思。即“好啊”、“妙啊”或“太棒了”。善，好；哉，语气词，表示感叹。
巍巍：高大的样子。
乎：语气词，相当于“啊”。
若：像……一样。
少选：一会儿，不久。
志在流水：心里想到河流。
汤汤乎若流水：像流水一样浩荡。
汤汤：水流大而急的样子。', '伯牙弹琴，锺子期听他弹琴。伯牙在弹琴时心里想着高山，锺子期说：“你弹得真好呀，就像那巍峨的太山。”不一会儿，伯牙心里又想到流水，锺子期又说：“你弹得真好呀，就像那奔腾不息的流水。”锺子期死了以后，伯牙摔琴断弦，终身不再弹琴，认为世上再没有值得他为之弹琴的人了。', NULL, '', 'indent', 1581860792, '5e48d6e42a6bfd4d10ed9ab8', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643741, '书戴嵩画牛', NULL, 18, 3406, 0, 3, '苏轼', NULL, 10001, '57ad1badc4c9710054676d9d', '宋', 'wen', '文', '', '', '蜀中有杜处士，好书画，所宝以百数。有戴嵩《牛》一轴，尤所爱，锦囊玉轴，常以自随。
一日曝书画，有一牧童见之，拊掌大笑，曰：“此画斗牛也。牛斗，力在角，尾搐入两股间，今乃掉尾而斗，谬矣。”处士笑而然之。古语有云：“耕当问奴，织当问婢。”不可改也。', '', '杜处士：姓杜的读书人。
宝：这里是动词，珍藏。
囊：袋子，此处指画套。用彩锦做装画的袋子，用玉石做卷画的轴子。
曝：晾、晒。
搐：抽搐，收缩。
掉：摇着尾巴。掉，摆动，摇动。
然：认为⋯⋯是对的。
所宝：所珍藏的画。
戴嵩：唐代画家。
锦襄玉轴：以玉为轴，用锦囊盛起来。
拊掌：拍手。
翘起尾巴。', '四川境内有个姓杜的隐士，爱好书画，他珍藏的书画作品有成百件，有戴嵩画的《牛》一幅，他特别喜爱，用锦囊盛起来，用玉石作画轴，经常随身携带着。
有一天晾晒书画，一个牧童看到了这幅画，拍手大笑说：“这画上画的是角斗的牛呀，牛在角斗时力量集中在角上，尾巴夹在两条后腿中间，但这幅画却画成牛摇着尾巴斗角，画错了啊！”隐士笑了，认为牧童说得对。有句古话说：“耕地应当去问种庄稼的农民，织布应当去问纺纱织布的婢女。”这句话是不可改变的。', NULL, '', 'indent', 1581860951, '5e48d7bbfc36ed006ab3af24', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643742, '孟子·告子上 · 学弈', NULL, 90, 271, 0, 4, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '弈秋，通国之善弈者也。使弈秋诲二人弈，其一人专心致志，惟弈秋之为听；一人虽听之，一心以为有鸿鹄将至，思援弓缴而射之。虽与之俱学，弗若之矣。为是其智弗若与？曰：非然也。', '本文节选自《孟子·告子上》，弈秋是第一个史上有记载的的围棋专业棋手，也是史上第一个有记载的从事教育的围棋名人。关于弈秋的姓名，清代学者焦循《孟子正义》里作有说明：古之以技传者，每称之为名，如医和、卜徒父是也。此名弈秋，故知秋为其名，因通国皆谓之善弈，故以弈加名称之。
弈秋是幸运的，春秋战国延续五百年，他是留下名字的唯一的一位围棋手，也是我们所知的第一位棋手。
围棋见于我国史籍最早的记载，是春秋时期，至今已有二千六七百年的历史了。弈秋是见于史籍记载的第一位棋手，而且是位“通国之善弈者”。关于他的记载，最早见于《孟子》。由此推测，弈秋可能是与孟子同时代的人，也可能稍早一些，由此也可以推测他大约生活在战国初期。出现弈秋这样的高手，说明当时围棋已相当普及，可以肯定，像弈秋这样的国手不只一人。
孟子称弈秋为“通国之善弈者”。所赞通国善弈，虽未明定专称，已类似后代所称国手，并成为象征性名词。后世称某高手为“当代弈秋”者，即意味着其水平与国手相当。弈秋是当时诸侯列国都知晓的国手，棋艺高超，《弈旦评》推崇他为国棋“鼻祖”。
由于弈秋棋术高明，当时就有很多年青人想拜他为师。弈秋收下了两个学生。一个学生诚心学艺，听先生讲课从不敢怠慢，十分专心。另一个学生大概只图弈秋的名气，虽拜在门下，并不下功夫。弈秋讲棋时，他心不在焉，探头探脑地朝窗外看，想着鸿鹄（天鹅）什么时候才能飞来。飞来了，好张弓搭箭射两下试试。两个学生同在学棋，同拜一个师，前者学有所成，后者未能领悟棋艺。学棋要专心，下棋也得如此，即使是弈秋这样的大师，偶然分心也不行。有一日，弈秋正在下棋，一位吹笙的人从旁边路过。悠悠的笙乐，飘飘忽忽的，如从云中撒下。弈秋一时走了神，侧着身子倾心聆听。此时，正是棋下到决定胜负的时候，笙突然不响了，吹笙人探身向弈秋请教围棋之道，弈秋竟不知如何对答。不是弈秋不明围棋奥秘，而是他的注意力此刻不在棋上。
这两则小故事都记载在史书上。人们把它记下来，大概是想告诫后人们，专心致志是下好围棋的先决条件，做事情要一心一意。', '弈：下棋。（围棋）
秋：人名，因他善于下棋，所以称为弈秋。
通国：全国。
通：全。
之：的。
善：善于，擅长。
使：让。
诲：教导。
其：其中。
惟弈秋之为听：只听弈秋（的教导）。
虽听之：虽然在听讲。
以为：认为，觉得。
鸿鹄：天鹅和大雁。
援：引，拉。
将至：将要到来。
思：想。
弓缴：弓箭。
缴：古时指带有丝绳的箭。
之：代词，这里指鸿鹄。
虽与之俱学：虽然这个人和那个专心致志的人在一起学习。
弗若之矣：成绩却不如另外一个人。
为是其智弗若与：因为他的智力比别人差吗？
曰：说。
非然也：不是这样的。
矣：了。
弗：不如。', '弈秋是全国最擅长下棋的人。让弈秋教导两个人下棋，其中一人专心致志的学习，只听弈秋的教导；另一个人虽然也在听弈秋的教导，却一心以为有大雁要飞来，想要拉弓箭将它射下来。虽然他们二人一起学习下棋，但后者的棋艺不如前者好。难道是因为他的智力比别人差吗？说：不是这样的。', NULL, '', 'indent', 1581863376, '5e48e13843c257006aefac7c', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643745, '荀巨伯探病友', NULL, 2, 43, 0, 1, '刘义庆', NULL, 10260, '57b9032cd342d3005ac73d7d', '南北朝', 'wen', '文', '', '', '荀巨伯远看友人疾，值胡贼攻郡，友人语巨伯曰：“吾今死矣，子可去。”巨伯曰：“远来相视，子令吾去，败义以求生，岂荀巨伯所行邪？”贼既至，谓巨伯曰：“大军至，一郡尽空，汝何男子，而敢独止？“巨伯曰：“友人有疾，不忍委之，宁以我身代友人命。”贼相谓曰：“我辈无义之人，而入有义之国。”遂班军而还，一郡并获全。', '', '荀巨伯：东汉颍州（今属河南）人，生平不详，汉桓帝的义士。（荀：发音：xún）。
远：从远方。
值：恰逢，赶上。
胡：中国古代泛指居住在北部和西北部的少数民族，秦汉时一般指匈奴。
语：动词，对......说，告诉。
子可去：您可以离开这里。子，第二人称代词“您”的尊称。去，离开。
令：使，让。
吾：第一人称，我。
败义以求生：败坏道义而苟且偷生。
邪：句末语气词，表疑问，相当于吗，呢。
郡：古代的行政区划，这里指城。
无义之人：不懂道义的人。
获全：得到保全。', '荀巨伯到远方看望生病的朋友，正好遇上胡人来攻城。朋友对荀巨伯说：“我如今是快死的人了，你赶快离开吧！”荀巨伯说：“我远道而来看望你，你却要我离开；败坏道义来求生，这难道是我荀巨伯做的事吗？”胡人军队已经来到，问荀巨伯说：“大军一到，整个城都空了，你是什么人，竟敢独自停留在这里？”荀巨伯回答说：“我的朋友身患重病，我不忍心舍弃他而离开，宁愿用我的性命来换取朋友的生命。”胡兵听后相互议论说到：“我们这些不懂道义的人，却要攻入这个讲究道义的国家！”于是调回外出打仗的军队，使整个城都因此获救。', NULL, '', 'indent', 1581880593, '5e49248b8a84ab006a28a201', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643749, '咏雪', NULL, 42, 43, 0, 8, '刘义庆', NULL, 10260, '57b9032cd342d3005ac73d7d', '南北朝', 'wen', '文', '', '', '谢太傅寒雪日内集，与儿女讲论文义。俄而雪骤，公欣然曰：“白雪纷纷何所似？”兄子胡儿曰：“撒盐空中差可拟。”兄女曰：“未若柳絮因风起。”公大笑乐。即公大兄无奕女，左将军王凝之妻也。', '始出于东晋谢安与其子侄辈们的一段即兴对话。言简意赅地勾勒了疾风骤雪、纷纷扬扬的下雪天，谢家子女即景赋诗咏雪的情景，展示了古代家庭文化生活轻松和谐的画面。文章通过神态描写和身份补叙，赞赏谢道韫的文学才华，并因此而流传千古，成为一段佳话。《咏雪》作为清谈名士的教科书，特别注意传达魏晋清谈家的独特的语言形象，重视人物语言的润饰，“读其语言，晋人面目气韵，恍忽生动，而简约玄澹，真致不穷，古今绝唱也。”

“谢太傅寒雪日内集，与儿女讲论文义。”文章第一句交代咏雪的背景。短短的十五个字，涵盖的内容相当多。东晋的谢氏家族是个赫赫有名的诗礼簪缨之家，为首的是谢太傅即谢安。在这样的家族里，遇到雪天无法外出，才有“讲论文义”的雅兴。召集人兼主讲人自然是谢安，听众是“儿女”们。时间、地点、人物、事件全都说到了。 接着写主要事件咏雪。其实是主讲人出题考听众。主讲人何以有此雅兴？原来是天气发生了变化：“俄而雪骤”，早先也有雪，但不大，而此刻变成了纷纷扬扬的鹅毛大雪。这使主讲人感到很高兴，于是“公欣然曰：‘白雪纷纷何所似？’兄子胡儿曰：‘撒盐空中差可拟。’兄女曰：‘未若柳絮因风起。’”答案可能不少，但作者只录下了两个：一个是谢朗说的“撒盐空中”；另一个是谢道韫说的“柳絮因风起”。主讲人对这两个答案的优劣未做评定，只是“大笑乐”而已，十分耐人寻味。作者也没有表态，却在最后补充交代了谢道韫的身份，“即公大兄无奕女，左将军王凝之妻也。”这是一个有力的暗示，表明他欣赏及赞扬谢道韫的才气，并写出了谢道韫是“咏絮才”。

为何说谢道韫作的词句更好呢？柳絮，作为春时景物，有似花非花，因风而起，飘忽无根，满天飞舞的特征。晋伍辑之《柳花赋》曾形容：“扬零花而雪飞，或风回而游薄，或雾乱而飙零，野净秽而同降，物均色而齐明。”谢道韫将此来比拟北风吹起漫天飞雪，堪称契合无间。取柳絮可比其形言其大，点明当时的“雪骤”之景，而“因风起”更指出它随风飘舞，漫无边际的自然特点。（宋代的贺铸《青玉案》词有“满城风絮”句。）由此较之，雪花柳絮，可谓是异迹而同趣了。如此再看“撒盐空中”的比方，则未免有局促见肘之诮了。比喻更讲究神似：盐在空中唰唰地撒，重重地下落，躲都来不及，何谈欣赏？无美感可言。比作柳絮，一扫滞重之感，因风而起，漫天飘飞，这才是大自然的造化。而且柳絮飘飞的季节是春暖花开之时，冬季之冷景，以春季之暖景写出，更见诗意。', '谢太傅：即谢安（.320年－385年），字安石，晋朝陈郡阳夏（现在河南太康）人。做过吴兴太守、侍 中、吏部尚书、中护军等官职。死后追赠为太傅。
内集：家庭聚会。
儿女：子侄辈。
讲论文义：讲解诗文。
俄而：不久，不一会儿。
骤：急，紧。
欣然：高兴的样子。
何所似：像什么。何，什么；似，像。
胡儿：即谢朗。谢朗，字长度，谢安哥哥的长子。做过东阳太守。
差可拟：差不多可以相比。差，大致，差不多；拟，相比。
未若：倒不如。
因：凭借。
即：是。
无奕女：指谢道韫（yùn），东晋有名的才女，以聪明有才著称。无奕，指谢奕，字无奕。
王凝之：字叔平，大书法家王羲之的第二个儿子，做过江州刺史、左将军、会稽内史等。', '谢安在寒冷的雪天举行家庭聚会，给子侄辈的人讲解诗文。不久，雪下得大了，太傅高兴地说：“这纷纷扬扬的白雪像什么呢？”他哥哥的长子谢朗说：“在空中撒盐差不多可以相比。”另一个哥哥的女儿说：“不如比作柳絮凭借着风飞舞。”太傅大笑起来。她就是谢奕的女儿谢道韫，左将军王凝之的妻子。', NULL, '', 'indent', 1581949901, '5e4a334b2a6bfd4d10f956c2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643750, '陈太丘与友期行', NULL, 29, 43, 0, 8, '刘义庆', NULL, 10260, '57b9032cd342d3005ac73d7d', '南北朝', 'wen', '文', '', '', '陈太丘与友期行，期日中。过中不至，太丘舍去，去后乃至。元方时年七岁，门外戏。客问元方：“尊君在否？”答曰：“待君久不至，已去。”友人便怒曰：“非人哉！与人期行，相委而去。”元方曰：“君与家君期日中。日中不至，则是无信；对子骂父，则是无礼。”友人惭，下车引之。元方入门而不顾。', '', '元方：即陈纪，字元方，陈寔的长子。
陈太丘：陈寔（shí），字仲弓，东汉颍川许（现在河南许昌）人，做过太丘县令。太丘：古地名。
期行：相约同行。期，约定。
期日中：约定的时间是正午。日中，正午时分。
过中：过了正午。
舍去：不再等候就走了。去，离开。舍：舍弃，抛弃。
乃至：（友人）才到。乃，才。
戏：嬉戏。
尊君在不（fǒu）：你父亲在吗？尊君，对别人父亲的一种尊称。不，通“否”
家君：谦词，对人称自己的父亲。
引：拉，要和元方握手
信：诚信，讲信用。
时年：当时的年龄。
非：不是。
相委而去：丢下我走了；相偏指一方对另一方的行为；委，丢下，舍弃。
君：对对方父亲的一种尊称。
已去：已经离开。
曰：说。
则：就是。
顾：回头看。
惭：感到惭愧。
古今异义词
去古意：离开；今意：往、到。
委古意：丢下、舍弃；今意：委屈、委托。
顾古意：回头看；今意：照顾', '陈太丘和朋友相约同行，约定的时间在正午，过了正午朋友还没有到，陈太丘不再等候他而离开了，陈太丘离开后朋友才到。元方当时年龄七岁，在门外玩耍。陈太丘的朋友问元方：“你的父亲在吗？”元方回答道：“我父亲等了您很久您却还没有到，已经离开了。”友人便生气地说道：“真不是君子啊！和别人相约同行，却丢下别人先离开了。”元方说：“您与我父亲约在正午，正午您没到，就是不讲信用；对着孩子骂父亲，就是没有礼貌。”朋友感到惭愧，下了车想去拉元方的手，元方头也不回地走进家门。', NULL, '', 'indent', 1581950040, '5e4a33d643c257006afaf98d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643751, '富贵不能淫', NULL, 41, 271, 0, 2, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '景春曰：“公孙衍、张仪岂不诚大丈夫哉？一怒而诸侯惧，安居而天下熄。”
孟子曰：“是焉得为大丈夫乎？子未学礼乎？丈夫之冠也，父命之；女子之嫁也，母命之，往送之门，戒之曰：‘往之女家，必敬必戒，无违夫子！’以顺为正者，妾妇之道也。居天下之广居，立天下之正位，行天下之大道。得志，与民由之；不得志，独行其道。富贵不能淫，贫贱不能移，威武不能屈，此之谓大丈夫。”', '', '景春：与孟子同时代的人，纵横家。
公孙衍：战国时期魏国人，纵横家。曾在秦国为相，又曾佩五国相印。
张仪：战国时期魏国人，纵横家，秦惠王时为相，游说六国连横以服从秦国。
诚：真正，确实。
大丈夫：指有大志、有作为、有气节的男子。
惧：害怕。
安居：安静。
熄：同“息”，平息，指战火熄灭，天下太平。
是：这，这个。
焉：怎么，哪里。
子：你。
未学：没有学。
之：“丈夫之冠也”及下文“女子之嫁也”中的“之”都是主谓之间取消句子独立性，不译。
丈夫之冠：男子举行加冠礼的时候。冠：古代男子到成年则举行加冠礼，叫做冠。古人二十岁既为加冠。
父命之：父亲给予训导；父亲开导他。命：教导、训诲。
母命之：母亲给予训导。
嫁：出嫁。
往：去，到。
戒：告诫。
女（rǔ）：同“汝”，你。
必敬必戒；必：一定。敬：恭敬。戒：留神，当心，谨慎。
违：违背。
乱：扰乱。
夫子：旧时称自己的丈夫。
以：把。
顺：顺从。
为：作为。
正：正理，及基本原则。
道：方法。
居天下之广居：第一个“居”：居住。第二个“居”居所，住宅。
广居、正位、大道：朱熹注释为：广居，仁也；正位，礼也；大道，义也。
立：站，站立。
正：正大。
大道：光明的大道。
得：实现。
志：志向。
由：遵循。
独行其道：独自走自己的道路。独：独自。行：这里是固守；坚持的意思。道：原则，行为准则。
淫：惑乱，迷惑。使动用法。
移：改变，动摇。使动用法。
屈：屈服。使动用法。', '景春说：“公孙衍、张仪难道不是真正的有志气、作为的大丈夫吗？他们一发怒，连诸侯都害怕，他们安静下来，天下就太平无事。”
孟子说：“这哪里能算是有志气有作为的男子呢？你没有学过礼吗？男子行加冠礼时，父亲给予训导；女子出嫁时，母亲给予训导，送她到门口，告诫她说：‘到了你的丈夫的家里，一定要恭敬，一定要谨慎，不要违背你的丈夫！’以顺从为做人原则的，是妾妇之道。居住在天下最宽广的住宅‘仁’里，站立在天下最正确的位置‘礼’上，行走在天下最宽广的道路‘义’上。能实现理想时，就同人民一起走这条正道；不能实现理想时，就独自行走在这条正道上。富贵不能使他的思想迷惑，贫贱不能使他的操守动摇，威武不能使他的意志屈服，这才叫作有志气有作为的大丈夫。”', NULL, '', 'indent', 1583158453, '5e4a4d8cfc36ed006ac08c97', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643752, '周亚夫军细柳', NULL, 9, 139, 0, 2, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', '', '', '文帝之后六年，匈奴大入边。乃以宗正刘礼为将军，军霸上；祝兹侯徐厉为将军，军棘门；以河内守亚夫为将军，军细柳：以备胡。
上自劳军。至霸上及棘门军，直驰入，将以下骑送迎。已而之细柳军，军士吏被甲，锐兵刃，彀弓弩，持满。天子先驱至，不得入。先驱曰：“天子且至！”军门都尉曰：“将军令曰：‘军中闻将军令，不闻天子之诏’。”居无何，上至，又不得入。于是上乃使使持节诏将军：“吾欲入劳军。”亚夫乃传言开壁门。壁门士吏谓从属车骑曰：“将军约，军中不得驱驰。”于是天子乃按辔徐行。至营，将军亚夫持兵揖曰：“介胄之士不拜，请以军礼见。”天子为动，改容式车。使人称谢：“皇帝敬劳将军。”成礼而去。
既出军门，群臣皆惊。文帝曰：“嗟乎，此真将军矣！曩者霸上、棘门军，若儿戏耳，其将固可袭而虏也。至于亚夫，可得而犯邪！”称善者久之。', '', '文帝之后六年：指汉文帝后元六年。
匈奴：我国古代北方民族之一。
大：大规模，大举。
入边：侵入边境。
宗正：掌管皇族事务的官员。
军霸上：驻军霸上。霸上，地名，译做“灞上”，因地处灞水西岸高原而得名，在今陕西西安东。
祝兹侯：封号。
棘门：地名，原为秦宫门，在今陕西咸阳东北。
河内守：河内郡的郡守。河内，郡名，今河南北部地区。守，郡守，是汉代郡一级的行政长官。
备：防备，戒备。
胡：胡人，古代对北方少数民族的泛称，此指匈奴。
上：特指皇帝。
劳：慰问。
军：军营
已而：不久。
之：到，往。
被：通“披”，穿着。
锐兵刃：这里指刀出鞘。
彀（gòu）：张开。
弩（nǔ）：用机械发箭的弓。
持满：把弓拉满。
先驱：先行引导的人员。
且：将要。
军门都尉：守卫军营的将官，职位低于将军。
诏（zhào）：皇帝发布的命令。
居无何：过了不久。居，经过，表示相隔一段时间。无何，不久。
持节：手持符节。节，符节，皇帝派遣使者或调动军队的凭证。
壁：营垒。
车骑：车马。
驱驰：策马疾驰。
按辔：控制住车马。辔，马缰绳。
徐：慢，缓慢。
持兵揖（yi）：手持兵器行礼。揖，拱手行礼。
介胄之士不拜：穿戴着盔甲之将不行跪拜礼。介胄，铠甲和头盔，这里用作动词，指披甲戴盔。士，将领。
为动：被感动。
改容式车：表情严肃起来，扶着车前横木俯下身子，表示敬意。式，同“轼”。这里用作动词，指扶轼。
称谢：向人致意，表示问候。
既：已经。
嗟乎：叹词，表示慨叹。
曩（nǎng）：先前。
固：必，一定。
邪（yé）：语气词，表示反问。
之：助词。在句中只起调节音节的作用，无实意。', '汉文帝后元六年，匈奴大规模侵入汉朝边境。于是，朝廷委派宗正官刘礼为将军，驻军在霸上；委派祝兹侯徐厉为将军，驻军在棘门；委派河内郡太守周亚夫为将军，驻军细柳，以防备匈奴侵扰。
皇上亲自去慰劳军队。到了霸上和棘门的军营，直接驱车而入，将军及其属下都骑着马迎送。随即来到了细柳军营，只见官兵都披戴盔甲，手持锋利的兵器，开弓搭箭，弓拉满月，戒备森严。皇上的先行卫队到了营前，不准进入。先行的卫队说：“皇上将要驾到。”镇守军营的将官回答：“将军有令：‘军中只听从将军的命令，不听从天子的命令。’”过了不久，皇上驾到，也不让入军营。于是皇上就派使者拿符节去告诉将军：“我要进营慰劳军队。”周亚夫这才传令打开军营大门。守卫营门的官兵对跟从皇上的武官说：“将军规定，军营中不准驱车奔驰。”于是皇上的车队也只好拉住缰绳，慢慢前行。到了大营前，将军周亚夫手持兵器，双手抱拳行礼说：“我是盔甲在身的将士，不便跪拜，请允许我按照军礼参见。”皇上因此而感动，脸上的神情也改变了，俯身扶着横木上，派人致意说：“皇帝敬重地慰劳将军。”劳军礼仪完毕后辞去。
出了细柳军营的大门，许多大臣都深感惊诧。文帝感叹地说：“啊！这才是真正的将军。先前的霸上、棘门的军营，简直就像儿戏一样，匈奴是完全可以通过偷袭而俘虏那里的将军，至于周亚夫，岂是能够侵犯他吗？”长时间对周亚夫赞叹不已。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d703048e64fbd9ccc9", "shortContent": "这篇文字节选自《史记·绛侯周勃世家》。周勃是汉代开国元戎，他死后由其长子周胜之袭封侯爵。后胜之因犯罪削封，汉文帝才选周勃诸子中的贤者、当时担任河内守的周亚夫作爵位的继承人。文帝后元六年（前158），匈奴入寇，亚夫奉命领军防守长安，驻军细柳。其实这次匈奴入侵，历时不过一个多月，因汉军戒备森严，以匈奴引兵退却而结束，对长安仅仅是一场虚惊。按照《史记》笔法，只须在头一段“以备胡”的后面，加上“居一月，虏...", "authors": ["赖汉屏"], "pressName": "上海辞书出版社"}]', '', 'indent', 1581969841, '5e4a812b1358aa006ad05d1f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643753, '鱼我所欲也', NULL, 54, 271, 0, 14, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '鱼，我所欲也；熊掌，亦我所欲也。二者不可得兼，舍鱼而取熊掌者也。生，亦我所欲也；义，亦我所欲也。二者不可得兼，舍生而取义者也。生亦我所欲，所欲有甚于生者，故不为苟得也；死亦我所恶，所恶有甚于死者，故患有所不辟也。如使人之所欲莫甚于生，则凡可以得生者何不用也？使人之所恶莫甚于死者，则凡可以辟患者何不为也？由是则生而有不用也，由是则可以辟患而有不为也。是故所欲有甚于生者，所恶有甚于死者。非独贤者有是心也，人皆有之，贤者能勿丧耳。
一箪食，一豆羹，得之则生，弗得则死。呼尔而与之，行道之人弗受；蹴尔而与之，乞人不屑也。万钟则不辩礼义而受之，万钟于我何加焉！为宫室之美、妻妾之奉、所识穷乏者得我与？乡为身死而不受，今为宫室之美为之；乡为身死而不受，今为妻妾之奉为之；乡为身死而不受，今为所识穷乏者得我而为之：是亦不可以已乎？此之谓失其本心。', '本文是孟子以他的性善论为依据，对人的生死观进行深入讨论的一篇代表作。他从人应如何对待自己的欲望入手，在生与死、利与义、守义与失义等方面，层层深入、正反对比地论证了义重于生，必须舍生取义。还强调指出“非独贤者有是心（舍生取义之心）也，人皆有之，贤者能勿丧耳”，人如果经不住万钟、宫室、妻妾、施恩的诱惑，必然会“失其本心（舍生取义之心）”。
《鱼我所欲也》一文用面对鱼和熊掌之间的抉择，比喻面对生命和大义之间的选择，孟子会毅然“舍生而取义者也”。这当中的“义”和文章最后的“此之谓失其本心”的“本心”都是指人的“羞恶之心”（按如今的通俗理解，可以理解为“廉耻之心”）。因为人只有拥有“羞恶之心”，才能分清哪些是道德底线可以承受的事，哪些是道德范围所不接纳的事，哪些是“所欲有甚于生”的事，这样才能不被“宫室之美”、“妻妾之奉”和“所识穷乏者得我”所诱惑，而像“不食嗟来之食”的人一样，内心有一种凛然的“义”。
《鱼我所欲也》一文本身的结构和材料所揭示的中心论点应当是：人皆有“所欲有甚于生，所恶有甚于死”的“本心”，“贤者能勿丧耳”。如果把《鱼》文分成三段来分析，是不难说明这一观点的。本文逻辑严密，析理精深，比喻、排比、对比等修辞手法的运用，使语言生动、流畅，气充词沛，颇具说服力。', '亦：也。
欲：喜爱。
得兼：两种东西都得到。
舍：舍弃。
取：选取。
甚：胜于。
于：比。
故：所以，因此。
苟得：苟且取得，这里是“苟且偷生”的意思。
恶：厌恶。
患：祸患，灾难。
辟：通“避”，躲避。
如使：假如，假使。
之：用于主谓之间，取消句子的独立性，无实意，不译。
莫：没有。
则：那么。
凡：凡是，一切。
得生：保全生命。
何不用也：什么手段不可用呢？用，采用。
为：做。
而：但是。
是故：这是因为。
非独：不只，不仅。非，不。独，仅。
贤者：有才德，有贤能的人。
是：此，这样。
心：思想
勿丧：不丧失。丧，丧失。
箪：古代盛食物的圆竹器。
豆：古代一种木制的盛食物的器具。
则：就。
弗：不。
得：得到。
呼尔：呼喝（轻蔑地，对人不尊重）。
呼尔而与之：呼喝着给他（吃喝）。尔，语气助词。《礼记·檀弓》记载，有一年齐国出现了严重的饥荒。黔敖在路边施粥，有个饥饿的人用衣袖蒙着脸走来。黔敖吆喝着让他吃粥。他说：“我正因为不吃被轻蔑所给予得来的食物，才落得这个地步！
行道之人：（饥饿的）过路的行人。
蹴：用脚踢。
而：表修饰。
不屑：因轻视而不肯接受。
万钟：这里指高位厚禄。钟，古代的一种量器，六斛四斗为一钟。
何加：有什么益处。何介词结构，后置。
宫室：住宅。
奉：侍奉。
穷乏者：穷人。
得我：感激我。得，同“德”，感激。
与：同“欤”，语气助词。
乡：同“向”，先前、从前。
已：停止。
本心：指本性，天性，良知。
通假字
故患有所不辟：“辟”通“避”，躲避。
所识穷乏者得我与：“得”通“德“，恩惠，这里指感激。
则不辩礼仪而受之：“辩”同“辨”，辨别。
所识穷乏者得我与：“与”同“欤”，语气词。
词类活用
名词作动词
得，恩惠，这里是感激的意思。例句：所识穷乏者得我与。
动词作名词
生，可以获得生存的手段。例句：由是则生而有不用也。
本文主旨
恻隐之心，人皆有之；
羞恶之心，人皆有之；
是非之心，人皆有之。', '鱼是我所想要的，熊掌也是我所想要的，如果这两种东西不能同时得到，那么我就只好放弃鱼而选取熊掌了。生命是我所想要的，道义也是我所想要的，如果这两样东西不能同时都具有的话，那么我就只好牺牲生命而选取道义了。生命是我所想要的，但我所想要的还有比生命更重要的东西，所以我不做苟且偷生的事。死亡是我所厌恶的，但我所厌恶的还有超过死亡的事，因此有灾祸我也不躲避。如果人们所想要的东西没有能比生命更重要的，那么凡是能够用来求得生存的手段，哪一样不可以采用呢？如果人们所厌恶的事情没有超过死亡的，那么凡是可以躲避祸患的办法什么不可以做呢？采用某种手段就能够活命，可是有的人却不肯采用；采用某种办法就能够躲避灾祸，可是有的人也不肯采用。由此可见，他们所想要的有比生命更宝贵的东西（那就是“义”）；他们所厌恶的，有比死亡更严重的事（那就是“不义”）。不仅贤人有这种本性，人人都有，只不过贤能的人不丧失罢了。
一碗食物，一碗汤，得到它就能活下去，得不到它就会饿死。如果盛气凌人地呼喝着给他吃，饥饿的行人也不愿接受；用脚踢给别人吃，就连乞丐也会因轻视而不肯接受。高官厚禄却不辨是否合乎礼义就接受了它。这样，高官厚禄对我有什么好处呢？是为了住宅的华丽、妻妾的侍奉和认识的穷人感激我吗？以前有人为了大义宁死也不愿接受，现在却为了住宅的华丽却接受了它；以前有人为了大义宁死也不愿接受，现在却为了妻妾的侍奉却接受了它；以前有人为了大义宁死也不愿接受，现在为了认识的穷人感激自己却接受了它。这种做法不是可以让它停止了吗？这就叫做丧失了人所固有的本性。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d1d635634aee3eab08", "shortContent": "这一段选自《孟子·告子上》，题目是根据第一句话加的。\n孟子主张性善，主要表现在《告子》篇。他主张：“恻隐之心，人皆有之；羞恶之心，人皆有之；恭敬之心，人皆有之；是非之心，人皆有之。”这就是“仁义礼智”之端。圣人有，普通人也有，区别在于能不能保持、发扬、充实这种人性固有的美德。这一段朱熹《孟子集注》说：“此章言羞恶之心，人所固有。或能决死生于危迫之际，而不免计丰约于宴安之时。是以君子不可顷刻而不省察...", "authors": ["周本淳"], "pressName": "上海辞书出版社"}]', '', 'indent', 1582034754, '5e4b7e92546eaa00731aa94b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643754, '观潮', NULL, 2, 598, 0, 4, '周密', NULL, 10222, '57c1170ea633bd005d686377', '宋', 'wen', '文', '', '', '浙江之潮，天下之伟观也。自既望以至十八日为盛。方其远出海门，仅如银线；既而渐近，则玉城雪岭际天而来，大声如雷霆，震撼激射，吞天沃日，势极雄豪。杨诚斋诗云“海涌银为郭，江横玉系腰”者是也。
每岁京尹出浙江亭教阅水军，艨艟数百，分列两岸；既而尽奔腾分合五阵之势，并有乘骑弄旗标枪舞刀于水面者，如履平地。倏尔黄烟四起，人物略不相睹，水爆轰震，声如崩山。烟消波静，则一舸无迹，仅有“敌船”为火所焚，随波而逝。
吴儿善泅者数百，皆披发文身，手持十幅大彩旗，争先鼓勇，溯迎而上，出没于鲸波万仞中，腾身百变，而旗尾略不沾湿，以此夸能。
江干上下十余里间，珠翠罗绮溢目，车马塞途，饮食百物皆倍穹常时，而僦赁看幕，虽席地不容间也。', '本篇选自《武林旧事》卷三。《武林旧事》一书系周密于宋亡之后所写，内容主要追记南宋岁时风俗、市井琐细，兼及游观之盛、娱乐之资，相当详备细致；而渗透于其中的，又是一种“恻恻兴亡”的盛衰感慨。
本篇主要描绘“钱塘观潮”的盛况。对此，另外几部杭州的风俗志（《都域纪胜》《西湖老人繁胜录》和《梦粱录》）都先已有过记述，不过都远不如此文生动形象。全文可分四层：
第一层写潮来之状。它用动态的“镜头摄像法”描写了初来之状（“仅如银线”）、既来之状（“既而渐近，则玉城雪岭”），又配之以“音响效果”（“大声如雷霆”），收到了文字尽管简约而令人视听不暇应接的艺术功效。
第二层写教阅水军的场面。其中的“场景”又多次转换：先是“艨艟数百，分列两岸”和乘骑弄旗、舞刀弄枪于水面的雄伟场面；接着写两军（假设的军事演习）交战、硝烟弥漫的场面，最后写烟消波静、“敌船”匿迹的场面。使人如同亲眼目睹这一番水战那样，感到十分真切。
第三层写“弄潮儿”的竞技，他们披发文身，手持大旗，争相逆潮而上；虽于鲸波万顷之中，却能不湿旗尾！读后使人为之咋舌鼓掌。
第四层写杭州市民和皇室的观潮情景，其中突出描写了杭州城的豪奢：请看，江岸十余里间，触处珠翠罗绮；而皇帝在“天开图画台”上观潮，远望去简直就像是在神仙台上那般。读到这里，虽然文字嘎然而止，但作者在提笔追忆往事时的那种“时移物换，忧患飘零，追想昔游，殆如梦寐”的兴亡盛衰之感，却又“言在纸外”地悄然升起矣。
总观全篇，尽管篇幅不长，而场面热闹、内容丰富，这大大得力于作者善于剪裁、善于描绘的文字功力。首先，它剪裁得当，叙写井然，给人以场面多变而层次井然的印象，其次，它语言简练，却又描绘细致，又给人以“尺幅之中层千里之势”的艺术享受。应该感谢周密，他给我们留下了这幅13世纪南宋优美的杭城风俗图画。', '浙江：就是钱塘江。
自既望以至十八日：从农历（八月）十六日到十八日。既望，农历十六日（十五日叫望）。
方其远出海门：当潮从入海口涌起的时候。方，当……时。其，代词，指潮。出，发、起。海门，浙江入海口，那里两边的山对峙着。
仅如银线：几乎像一条（横画的）银白色的线。仅，几乎，将近。
玉城雪岭：形容泛着白沫的潮水像玉砌的城墙和白雪覆盖的山岭。际天：连接着天。
沃日（wòrì）：冲荡太阳。形容波浪大。沃，用水淋洗，冲荡。
海涌银为郭，江横玉系腰这两句诗是《浙江观潮》一诗里的句子，意思是，海水涌起来，成为银子堆砌的城郭；浙江横着，潮水给系上一条白玉的腰带。“……是也”：就是指这样的景象。
每岁京尹（yǐn）出浙江亭教阅水军：每年（农历八月）京都临安府长官来到浙江亭教阅水军。岁，年。京尹，京都临安府（今浙江杭州）的长官。浙江亭，馆驿名，在城南钱塘江岸。
艨艟（méngchōng）：战船。
既而尽奔腾分合五阵之势：演习五阵的阵势，忽而疾驶，忽而腾起，忽而分，忽而合，极尽种种变化。尽，穷尽。五阵，指两、伍、专、参、偏五种阵法。
乘骑（chéngjì）弄旗标枪舞刀：乘马、舞旗、举枪、挥刀。骑，马。弄，舞动。标，树立、举。
略不相睹：彼此一点也看不见。睹，看。
水爆：水军用的一种爆炸武器。
一舸无迹（yìgěwújì）：一条船的踪影也没有了。舸，船。
敌船：指假设的敌方战船。
逝：去，往。
吴儿善泅（qiú）者数百：几百个擅于泅水的吴地健儿。吴地即今江苏、浙江一带。因春秋时为吴国之地，故称。善，善于。泅，游泳、浮水（可不翻译）。
披发文（wén）身：披散着头发，身上画着花纹。文，动词，画着文彩。
溯（sù）迎而上：逆流迎着潮水而上。溯，逆流而上。而，表修饰。
鲸波万仞（rèn）：万仞高的巨浪。鲸波，巨浪。鲸所到之处，波涛汹涌，所以称巨浪为鲸波。万仞，形容浪头极高，不是实指。
腾身百变：翻腾着身子变换尽各种姿态。
江干（gān）：江岸。
珠翠罗绮（qǐ）溢目：满眼都是华丽的服饰。珠翠罗绮，泛指妇女的首饰和游人的华丽衣服。溢目，满眼。
倍穹（qióng）：（价钱）加倍的高。穹，动词，高；倍，形容词，指很多倍。
而僦（jiù）赁（lìn）看幕：租用看棚的人（非常多）。而，表转折。僦、赁，都是租用的意思。看幕，为观潮而特意搭的帐棚。
虽席地不容间也：中间即使是一席之地的空地也不容有容。许，使。间（jiān）空间。虽，即使。席地，一席之地，仅容一个座位的地方。
一词多义
方：
方其远出海门【当……时】
方出神【正】
方七百里【面积】
观：
观潮【观看（动词）】
天下之伟观也【景象（名词）】
仅：
仅有“敌船”为火所焚【只】
仅如银线【几乎，将近。】
为：
“敌船”为火所焚【被】
海涌银为郭【成为】
自既望以至十八日为盛【算是】
以：
以此夸能【凭借】
自既望以至十八日为盛【和时间词等连用，表示时间。（助词）】
势：
势极雄豪【气势】
既而尽奔腾分合五阵之势【阵势】
能：
以此夸能【本领】
未复有能与其奇者【能够】
而：
则玉城雪岭际天而来【连词，表修饰】
而旗尾略不沾湿【连词，表转折】
而僦赁看幕，虽席地不容闲也【连词，表转折】
词类活用
①天下之伟观也（观：动词作名词，景观，景象）
②既而尽奔腾分合五阵之势。（尽：形容词作动词，穷尽。）
③皆披发文身。（文，名词作动词，画着纹身；刺着花纹。）
④并有乘骑弄旗标枪舞刀于水面者。（标：名词作动词，树立，举）
⑤饮食百物皆倍穹常时。（穹：形容词作动词，高过）
⑥.则玉城雪岭际天而来.（际:名词作动词，接近、连接）
古今异义
①方其远出海门（方古义：当……时。今义：方形等）
②则玉城雪岭际天而来（际古义：接近、连接。今义：边际）
③吞天沃日（沃古义：用水淋洗。今义：肥沃）
④既而尽奔腾分合五阵之势（奔腾古义：两个词，意为疾驶和腾起。今义：跳跃着奔跑）
⑤并有乘骑弄旗标枪舞刀于水面者（标枪古义：举枪。今义：一种体育器械）
⑥人物略不相睹（人物古义：人和物。今义：特指人）
⑦皆披发文身（文古义：画花纹。今义：文字、文章等）
⑧每岁京尹出浙江亭教阅水军（尹古义：名词，长官，官名。今义：一般作姓氏）
⑨江干上下十余里间（上下古义：上游到下游，指地域，区域，名词。今义：用来表示大约数目）
⑩海涌银为郭（郭古义：城墙。今义：指姓氏。）
句式
①浙江之潮，天下之伟观也（判断句）
②方其远出海门（省略句）
③既而渐近，则玉城雪岭际天而来（省略句）
④并有乘骑弄旗标枪舞刀于水面者（倒装句）
⑤仅有“敌船”为火所焚（被动句）
⑥出没于鲸波万仞中（倒装句）
⑦震撼激射（省略句）
⑧吴儿善泅（倒装句，也可为“善泅吴儿”）', '钱塘江的潮水，是天下雄伟的景观。从（农历）八月十六日到十八日潮水是最壮观的。当潮水远远地从钱塘江入海口涌起的时候，（远看）几乎像一条银白色的线；不久（潮水）越来越近，玉城雪岭一般的潮水连天涌来，声音大得像雷霆万钧，震撼天地，激扬喷射，吞没天空，冲荡太阳，气势极其雄伟豪壮。杨万里的诗中说的“海涌银为郭，江横玉系腰”就是指这样的景象。
每年（农历八月）京都临安府长官来到浙江亭教阅水军，几百艘战船分列两岸；不久水军的战船演习五阵的阵势，忽而疾驶，忽而腾起，忽而分，忽而合，极尽种种变化，同时有在水面上骑马、舞旗、举枪、挥刀的人，好像踩在平地上一样安稳。忽然黄色的烟雾从四面升起，人和物彼此一点儿也看不见，只听得水爆的轰鸣声，声音像山崩塌一样。（等到）烟雾消散，水波平静，就一条船的踪影也没有了，只剩下被火烧毁的“敌船”，随波而去。
几百个善于泅水的吴地健儿，披散着头发，身上画着文彩，手里拿着十幅大彩旗，争先恐后，鼓足勇气，逆流迎着潮水而上，在万仞高的巨浪中忽隐忽现，翻腾着身子变换各种姿态，但是旗尾却一点也不被水沾湿，凭借这种表演来显示他们高超的技能。
江岸上下游十多里的地方，满眼都是穿着华丽的服饰的观众，车马堵塞道路，吃喝等各种物品（的价钱）比平时要高出很多倍。租用看棚的人（非常多），中间即使是一席之地也不容有。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed2005914587d02f5a076", "shortContent": "浙江（即钱塘江）之潮，奔腾冲激，声撼地轴，叹为观止者由来已久。《庄子·外物》篇讲到任公子“蹲乎会稽，投竿东海”，“白波若山，海水震荡，声侔鬼神，惮赫千里”，指的也许就是浙江怒潮。《史记·秦始皇本纪》也有始皇三十七年“临浙江，水波恶，乃西百二十里从狭中渡”的记载。自宋以来，以浙江观潮为题材的诗文，为数不少。以笔记而言，就有周密《武林旧事》，耐得翁《都城纪胜》、《西湖老人繁胜录》和吴自牧《梦粱录》等，...", "authors": ["黄进德"], "pressName": "上海辞书出版社"}]', '', 'indent', 1582035301, '5e4b809843c257006a0636f3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643755, '夸父逐日', NULL, 9, 573, 0, 9, '无名氏', NULL, 10077, '57b902b3165abd0054bfdda0', '周', 'wen', '文', '', '', '夸父与日逐走，入日；渴，欲得饮，饮于河、渭；河、渭不足，北饮大泽。未至，道渴而死。弃其杖，化为邓林。', '黄帝王朝时代，在北方大荒中，有一座大山，拨地而起，高与天齐，故曰“成都载天”。那山削岩绝壁间云雾缭绕，松柏挺立，一派雄伟壮丽的景色。在这仙境般的大山上，居住着大神后土传下来的子孙，叫夸父族。他们个个身材高，力气大，专门喜好替人打抱不平。当南方蚩尤被黄帝打败，派人来夸父族救援时，夸父族多数觉得应该帮助弱者，于是决定出兵参加反对黄帝的战争。蚩尤族人得到了夸父族人的帮助，如虎添翼，再和黄帝作战时已经势均力敌，相持不下了。黄帝的军队的暂时败北，急的黄帝一筹莫展。于是上泰山去找各路神仙帮忙，有一个自称“玄女”的妇人前来拜见黄帝，教他兵法。接着又有人给黄帝送来了昆吾山的红铜，供他造宝剑用。这把宝剑断金切玉，削铁如泥，显示了上古青铜时代的冶炼技术。从此，黄帝籍此所学行军布阵，在涿鹿大战中，终于击败联军并杀死蚩尤，剩下的夸父族人跑回了原住地。不久，大地发生了严重的旱灾，太阳象个大火球，烤得大地龟裂，江湖涸干，一片荒凉。夸父族全体出动找水抗旱，但江湖涸干，到哪找水呀？夸父首领气急了，发誓要把太阳摘下来。太阳见夸父真发火，也有点心慌，加快速度向西落去。夸父首领拨脚就追。太阳滑行得更快了，一面向夸父射出热力，想阻止他前进。夸父尽管汗如雨注，却不肯停步。追呀追呀！夸父瞬息间已追了万里。看看快追到太阳落下的地方——禺谷，“看你往哪逃！”夸父高兴极了！太阳眼看无处可逃，冷笑几声，杀了个回马枪——将所有的热量一齐向夸父射去。夸父一阵头晕目眩，眼前金星乱迸，口干舌焦，双手不觉软垂。“不能倒下去！”夸父一面鼓励自己，一面俯身去饮黄河的水，想喝点水后再捉太阳。哪知他喝干了黄河，连渭水也喝干，还是感到口渴难忍。倔强的夸父决心去喝大泽的水，再去和太阳较量。大泽又叫瀚海，是鸟雀们孳生幼儿和更换羽毛的地方。夸父刚走到大泽边，还没俯下身来，一阵头晕，轰地一声，象座大山似的颓倒了。夸父遗憾地看着西沉的太阳，长叹一声，把手杖奋力往太阳抛去，闭上眼睛死了。第二天早晨，太阳神气活现的从东方升起，一看颓然而倒化成大山的夸父，也不由暗暗钦佩夸父的勇气。说也奇怪，经太阳光一照，夸父的手杖竟化成一片桃林，满树挂着硕大的果实。
那是这位热心公益、不辞劳苦的夸父巨人族的领袖夸父，为后人最后一次留下的好处啊！夸父追日的行为是一种大无畏的精神，虽然不切实际，却也显示出原始社会人们心灵和思维的简单。', '逐走：竞跑，赛跑。
逐：竞争。走：跑。
入日：追赶到太阳落下的地方。
欲得饮：想要喝水解渴。
河、渭：即黄河，渭水。
北饮大泽：大湖。传说纵横千里，在雁门山北。北：方位名词用作状语，向北方，向北面。
道渴而死：半路上因口渴而死。
邓林：地名，今在大别山附近河南、湖北、安徽三省交界处。邓林即“桃林”。
未至：没有赶到。
渴：感到口渴。
弃：遗弃。
为：成为。
逐日：追逐太阳。
于：到。（饮于河、渭中的于，应译为到，介词）
大泽：大湖。
足：够。（因为足的意思等同于够，所以足够：同义复合词）
词语活用
北饮大泽
北：名词作状语，向北。
道渴而死
道：名词作状语，在半路上。
古今异义
①
走：古义：跑。今义：行走。
②饮于河渭
河：古义：指黄河。今义：泛指所有河流。
一词多义
饮：
①欲得饮饮：名词，饮食，食物和水。
②饮于河、渭饮：动词，喝。', '夸父与太阳赛跑，一直追赶到太阳落下的地方；他感到口渴，想要喝水，就到黄河、渭水喝水。黄河、渭水的水不够，往北去大湖喝水。还没到大湖，在半路因口渴而死。而他丢弃的手杖，就化成桃林。', NULL, '', 'indent', 1582035948, '5e4b836a7796d9006abdcb44', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643757, '生于忧患，死于安乐', NULL, 44, 271, 0, 12, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '舜发于畎亩之中，傅说举于版筑之间，胶鬲举于鱼盐之中，管夷吾举于士，孙叔敖举于海，百里奚举于市。故天将降大任于是人也，必先苦其心志，劳其筋骨，饿其体肤，空乏其身，行拂乱其所为，所以动心忍性，曾益其所不能。
人恒过，然后能改；困于心，衡于虑，而后作；征于色，发于声，而后喻。入则无法家拂士，出则无敌国外患者，国恒亡。然后知生于忧患而死于安乐也。', '這是一篇论证严密、雄辩有力的说理散文。作者先列举六位经过贫困、挫折的磨炼而终于担当大任的人的事例，证明忧患可以激励人奋发有为，磨难可以促使人有新成就。接着，作者从一个人的发展和一个国家的兴亡两个不同的角度进一步论证忧患则生、安乐则亡的道理。最后水到渠成，得出“生于忧患，而死于安乐”的结论。全文采用列举历史事例和讲道理相结合的写法，逐层推论，使文章紧凑，论证缜密；此外，文章多用排比句和对仗句，即使语气错落有致，又造成一种势不可挡的气势，有力地增强了论辩的说服力。', '生于忧患，死于安乐：节选自《孟子·第十二卷·告子下·第十五节》。
舜：姚姓，名重华。唐尧时耕于历山（在今山东济南东南，一说在今山西永济东南），“父顽，母嚣，弟傲，能和以孝”，尧帝使其人山林川泽，遇暴风雷雨，舜行不迷，于是传以天子之位。国名虞，史称虞舜。事迹见于《尚书·尧典》及《史记·五帝本纪》等。
发：起，指任用。
畎（quǎn）亩：田亩，此处意为耕田。畎，田间水渠。
傅说（fùyuè）：殷商时为胥靡（一种刑徒），筑于傅险（又作傅岩，在今山西平陆东）。商王武丁欲兴殷，梦得圣人，名曰说，视群臣皆非，使人求于野，得傅说。见武丁，武丁曰：“是也。”与之语，果圣人，举以为相，殷国大治。遂以傅险为姓，名为傅说。事迹见于《史记·殷本纪》等。
举：被选拔。
版筑：筑墙的时候在两块夹板中间放土，用杵捣土，使它坚实。筑，捣土用的杵。
胶鬲（gé）：商纣王大臣，与微子、箕子、王子比干同称贤人。
鱼盐：此处意为在海边捕鱼晒盐。《史记》称燕在渤碣之间，有鱼盐之饶；齐带山海，多鱼盐。
管夷吾：管仲，颍上（今河南许昌）人，家贫困。辅佐齐国公子纠，公子纠未能即位，公子小白即位，是为齐桓公。齐桓公知其贤，释其囚，用以为相，尊称之为仲父。《史记·管晏列传》：“管仲既用，任政于齐，齐桓公以霸。九合诸侯，一匡天下，管仲之谋也。”
士：狱官。
孙叔敖（áo）：蒍姓，名敖，字孙叔，一字艾猎。春秋时为楚国令尹（宰相）。本为“期思之鄙人”，期思在今河南固始，偏僻之地称为鄙。
海：海滨。
百里奚（xī）：又作百里傒。本为虞国大夫。晋国灭虞国，百里奚与虞国国君一起被俘至晋国。晋国嫁女于秦，百里奚被当作媵臣陪嫁到秦国。百里奚逃往楚国，行至宛（今河南南阳），为楚国边界之鄙人所执。秦穆公闻其贤，欲重赎之，恐楚人不与，乃使人谓楚曰：“吾媵臣百里奚在焉，请以五羖羊皮赎之。”楚人于是与之。时百里奚年已七十余，至秦，秦穆公亲释其囚，与语国事三日，大悦。授以国政，号称“五羖大夫”。史称秦穆公用百里奚、蹇叔、由余为政，“开地千里，遂霸西戎”，成为“春秋五霸”之一。事迹见于《史记·秦本纪》。
市：市井。
故：所以。
任：责任，担子。
是：代词，这，这些。
是人：一作“斯人”。
也：助词，用在前半句的末尾，表示停顿一下，后半句将要加以解说。
必：一定。
苦：动词的使动用法，使……苦恼。
心志：意志。
劳：动词的使动用法，使……劳累。
饿：动词的使动用法，使……饥饿。
体肤：肌肤。
空乏：形容词的使动用法，使……穷困。
拂乱：形容词的使动用法，使……颠倒错乱。拂，违背，不顺。乱，错乱。
所为：所行。
所以：用来（通过那样的途径来……）。
动：动词的使动用法，使……惊动。
忍：形容词的使动用法，使……坚韧。
曾益：增加。曾，通“增”。
能：才干。
恒：常常，总是。
过：过错，过失。
困于心：心中有困苦。
衡于虑：思虑堵塞。衡，通“横”，梗塞，指不顺。
作：奋起，指有所作为。
征于色：面色上有征验，意为面容憔悴。征，征验，征兆。色，颜面，面色。赵岐《孟子注》：“若屈原憔悴，渔父见而怪之。”《史记·屈原贾谊列传》：“屈原至于江滨，被发行吟泽畔，颜色憔悴，形容枯槁。渔父见而问之曰：‘子非三闾大夫与？何故而至此？’屈原曰：‘举世混浊我独清，众人皆醉我独醒，是以见放。’”
发于声：言语上有抒发，意为言语愤激。赵岐《孟子注》：“若甯戚商歌，桓公异之。”甯戚，春秋时卫国人。家贫，为人挽车。至齐，喂牛于车下，齐桓公夜出迎客，甯戚见之，疾击其牛角而商歌。歌曰：“南山矸，白石烂，生不逢尧与舜禅。短布单衣适至骭，从昏饭牛薄夜半，长夜漫漫何时旦。”齐桓公召与语，悦之，以为大夫。
而后喻：然后人们才了解他。喻，知晓，明白。
入：名词活用作状语，在国内。
法家：有法度的世臣。
拂（bì）士：辅佐君主的贤士。拂，通“弼”，辅佐。
出：名词活用作状语，在国外。
敌国：实力相当、足以抗衡的国家。
外患：来自国外的祸患。
恒：常常。
亡：灭亡。
生于忧患：忧患使人生存发展。
死于安乐：享受安乐使人萎靡死亡。', '舜从田野耕作之中被起用，傅说从筑墙的劳作之中被起用，胶鬲从贩鱼卖盐中被起用，管夷吾被从狱官手里救出来并受到任用，孙叔敖从海滨隐居的地方被起用，百里奚被从奴隶市场里赎买回来并被起用。
所以上天要把重任降临在某人的身上，必定要先使他的内心痛苦，使他的筋骨劳累，使他经受饥饿之苦，以致肌肤消瘦，使他受贫困之苦，扰乱其人业已开始的行动，这样来使他的心灵受到震撼，使他的性情坚忍起来，增加他所不具备的能力。
人常常犯错，然后才能改正；内心忧困，思想阻塞，然后才能奋起；心绪显露在脸色上，表达在声音中，然后才能被人了解。一个国家，在内如果没有坚守法度的大臣和足以辅佐君王的贤士，在外没有与之匹敌的邻国和来自外国的祸患，就常常会有覆灭的危险。
这样，就知道忧愁患害足以使人生存，安逸享乐足以使人灭亡的道理了。', NULL, '', 'indent', 1582047588, '5e4bb0d57796d9006abfd280', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643758, '荆轲刺秦王', NULL, 149, 49, 0, 2, '刘向', NULL, 18105, '58540cde8e450a006c5803d4', '汉', 'wen', '文', '', '', '秦将王翦破赵，虏赵王，尽收其地，进兵北略地，至燕南界。
太子丹恐惧，乃请荆卿曰：“秦兵旦暮渡易水，则虽欲长侍足下，岂可得哉？”荆卿曰：“微太子言，臣愿得谒之，今行而无信，则秦未可亲也。夫今樊将军，秦王购之金千斤，邑万家。诚能得樊将军首，与燕督亢之地图献秦王，秦王必说见臣，臣乃得有以报太子。”太子曰：“樊将军以穷困来归丹，丹不忍以己之私，而伤长者之意，愿足下更虑之！”
荆轲知太子不忍，乃遂私见樊於期，曰：“秦之遇将军，可谓深矣。父母宗族，皆为戮没。今闻购将军之首，金千斤，邑万家，将奈何？”樊将军仰天太息流涕曰：“吾每念，常痛于骨髓，顾计不知所出耳！”轲曰：“今有一言，可以解燕国之患，而报将军之仇者，何如？”樊於期乃前曰：“为之奈何？”荆轲曰：“愿得将军之首以献秦，秦王必喜而善见臣。臣左手把其袖，而右手揕其胸，然则将军之仇报，而燕国见陵之耻除矣。将军岂有意乎？”樊於期偏袒扼腕而进曰：“此臣日夜切齿拊心也，乃今得闻教！”遂自刎。
太子闻之，驰往，伏尸而哭，极哀。既已，无可奈何，乃遂收盛樊於期之首，函封之。
于是太子预求天下之利匕首，得赵人徐夫人之匕首，取之百金，使工以药淬之。以试人，血濡缕，人无不立死者。乃为装遣荆轲。
燕国有勇士秦武阳，年十二，杀人，人不敢与忤视。乃令秦武阳为副。
荆轲有所待，欲与俱，其人居远未来，而为留待。
顷之未发，太子迟之，疑其有改悔，乃复请之曰：“日以尽矣，荆卿岂无意哉？丹请先遣秦武阳！”荆轲怒，叱太子曰：“今日往而不反者，竖子也！今提一匕首入不测之强秦，仆所以留者，待吾客与俱。今太子迟之，请辞决矣！”遂发。
太子及宾客知其事者，皆白衣冠以送之。至易水上，既祖，取道。高渐离击筑，荆轲和而歌，为变徵之声，士皆垂泪涕泣。又前而为歌曰：“风萧萧兮易水寒，壮士一去兮不复还！”复为慷慨羽声，士皆瞋目，发尽上指冠。于是荆轲遂就车而去，终已不顾。
既至秦，持千金之资币物，厚遗秦王宠臣中庶子蒙嘉。
嘉为先言于秦王曰：“燕王诚振怖大王之威，不敢兴兵以拒大王，愿举国为内臣，比诸侯之列，给贡职如郡县，而得奉守先王之宗庙。恐惧不敢自陈，谨斩樊於期头，及献燕之督亢之地图，函封，燕王拜送于庭，使使以闻大王。唯大王命之。”
秦王闻之，大喜。乃朝服，设九宾，见燕使者咸阳宫。
荆轲奉樊於期头函，而秦武阳奉地图匣，以次进。至陛下，秦武阳色变振恐，群臣怪之，荆轲顾笑武阳，前为谢曰：“北蛮夷之鄙人，未尝见天子，故振慑，愿大王少假借之，使毕使于前。”秦王谓轲曰：“起，取武阳所持图！”
轲既取图奉之，发图，图穷而匕首见。因左手把秦王之袖，而右手持匕首揕之。未至身，秦王惊，自引而起，绝袖。拔剑，剑长，操其室。时恐急，剑坚，故不可立拔。
荆轲逐秦王，秦王还柱而走。群臣惊愕，卒起不意，尽失其度。而秦法，群臣侍殿上者，不得持尺兵；诸郎中执兵，皆陈殿下，非有诏不得上。方急时，不及召下兵，以故荆轲逐秦王，而卒惶急无以击轲，而乃以手共搏之。
是时，侍医夏无且以其所奉药囊提轲。秦王方还柱走，卒惶急不知所为。左右乃曰：“王负剑！王负剑！”遂拔以击荆轲，断其左股。荆轲废，乃引其匕首提秦王，不中，中柱。秦王复击轲，被八创。
轲自知事不就，倚柱而笑，箕踞以骂曰：“事所以不成者，乃欲以生劫之，必得约契以报太子也。”
左右既前，斩荆轲。秦王目眩良久。', '', '（1）秦将王翦破赵，虏赵王：这是公元前228年的事。荆轲刺秦王是在第二年。
（2）收：占领。
（3）北：向北（名词用作状语）。
（4）略：通掠，掠夺，夺取。
（5）荆卿：燕人称荆轲为荆卿。卿，古代对人的敬称。
（6）旦暮渡易水：早晚就要渡过易水了。旦暮，早晚，极言时间短暂。易水，在河北省西部，发源于易县，在定兴县汇入南拒马河。
（7）长侍：长久侍奉。
（8）微太子言，臣愿得谒之：即使太子不说，我也要请求行动。微，假如没有。谒，拜访。
（9）今行而无信，则秦未可亲也：当下去却没有什么凭信之物，就无法接近秦王。信：凭信之物。亲：亲近，接近。
（10）樊将军：即下文的樊於（wū）期，秦国将领，因得罪秦王，逃到燕国。
（11）秦王购之金千斤，邑万家：秦王用一千斤金（当时以铜为金）和一万户人口的封地做赏格，悬赏他的头。购，重金征求。邑，封地。
（12）督亢：今河北省易县，霸县一带，是燕国土地肥沃的地方。
（13）说：同“悦”，喜欢，高兴。
（14）更虑之：再想想别的办法。更，改变。
（15）遇：对待。深，这里是刻毒的意思。
（16）戮没：杀戮和没收。重要的人杀掉，其他人等收为奴婢。
（17）顾计不知所出耳：只是想不出什么办法罢了。顾，不过，只是，表轻微转折。
（18）善：好好地。
（19）把：握，抓住。
（20）揕（zhèn）：刺。
（21）见陵之耻：被欺侮的耻辱。见，被。陵，侵犯，欺侮。
（22）偏袒扼腕而进：脱下一只衣袖，握住手腕，走近一步。这里形容激动愤怒的样子。偏袒，袒露一只臂膀。扼：握住。
（23）拊（fǔ）心：捶胸，这里形容非常心痛。
（24）盛（chéng）：装。
（25）函封之：用匣子封装起来。函，匣子。
（26）徐夫人：姓徐，名夫人。一个收藏匕首的人。
（27）工：工匠。
（28）以药淬（cuì）之：在淬火时把毒药浸到匕首上。淬，把烧红的铁器浸入水或者其他液体，急速冷却，使之硬化。
（29）濡（rú）缕：沾湿衣缕。濡，浸湿，沾湿。
（30）忤（wǔ）视：正眼看。忤，逆。意思是迎着目光看。
（31）为副：做助手。
（32）荆轲有所待，欲与俱：荆轲等待一个人，想同他一起去。
（33）迟之：嫌荆轲动身迟缓。
（34）往而不反者，竖子也：去了而不能好好回来复命的，那是没用的人。反，通“返”。竖子，对人的蔑称。
（35）不测：难以预料，表示凶险。
（36）请辞决矣：我就辞别了。请，请允许我，表示客气。辞决，辞别，告别。
（37）既祖，取道：祭过路神，就要上路。祖，临行祭路神，引申为践行和送别。
（38）高渐离：荆轲的朋友。
（39）为变徵（zhǐ）之声：发出变徵的声音。古时音乐分为宫，商，角，徵，羽，变徵，变宫七音，变徵是徵音的变调，声调悲凉。
（40）慷慨羽声：声调激愤的羽声。
（41）瞋（chēn）目：形容发怒时瞪大眼睛的样子。
（42）终已不顾：始终不曾回头。形容意志坚决。
（43）持千金之资币物：拿着价值千金的礼物。币，礼品。
（44）厚遗（wèi）秦王宠臣中庶子蒙嘉：以厚礼赠送给秦王的宠臣中庶子蒙嘉。遗：赠送。
（45）诚：确实。
（46）振怖：惧怕。振，通“震”。
（47）比：并，列。
（48）给贡职如郡县：像秦国的郡县那样贡纳赋税。给，供。
（49）奉守先王之宗庙：守住祖先的宗庙。意思是保存祖先留下的国土。
（50）使使：派遣使者。
（51）唯大王命之：意思是一切听大王的吩咐。唯，希望的意思。
（52）奉：两手捧着。
（53）以次进：按先后顺序进来。
（54）陛：殿前的台阶。
（55）顾笑武阳：回头冲武阳笑。顾，回头看。
（56）少假借之：稍微原谅他些。少：通“稍”。假借，宽容，原谅。
（57）使毕使于前：让他在大王面前完成使命。
（58）发：打开。
（59）自引而起，绝袖：自己挣着站起来，袖子断了。引，指身子向上起。绝：挣断。
（60）操其室：握住剑鞘。室，指剑鞘。
（61）剑坚：剑插得紧。
（62）还：通“环”，绕。
（63）卒（cù）起不意，尽失其度：事情突然发生，没意料到，全都失去常态。卒，通“猝”，突然。
（64）尺兵：尺寸之兵，指各种兵器。
（65）郎中：宫廷的侍卫。
（66）提（dǐ）：掷击。
（67）负剑：负剑于背。
（68）废：倒下。
（69）引：举起。
（70）被八创（chuāng）：荆轲受了八处剑伤。被，受。创，伤。
（71）箕踞：坐在地上，两脚张开，形状像箕。这是一种轻慢傲视对方的姿态。
（72）劫：强迫，威逼（其订立盟约）。', '秦国的将领王翦打败了赵国，俘虏了赵王，占领了所有赵国的土地，进军向北侵占土地，到达燕国南部的边界。燕国的太子丹很害怕，就去向荆轲询问办法，说：“秦兵早晚要渡过易水，那么虽然我想长久地侍奉您，又怎么能够做得到呢？”荆轲说：“即使是你不说，我也要请求行动。没有什么凭信之物，那就无法接近秦王。现在的樊将军，秦王用千斤的黄金，一万户的封邑。果真能够得到樊将军的首级，及燕国督亢一带的地图献给秦王，秦王一定高兴地召见我，我就有办法来报答太子了。太子说：“樊将军因为无路可走投奔我，我不忍心由于自己个人的私仇而伤害长者的心意，希望您另外考虑对策吧！荆轲知道太子不忍心，便私下里会见樊於期，对他说：“秦对你樊於期，可以说是刻毒透顶了。父亲、母亲和同族的人都被杀死或没收入官为奴。如今听说悬赏将军的头，用千斤的黄金，一万户的封邑。你打算怎么办？”樊将军仰天长叹，流着泪说：我常常想起来，常常恨入骨髓，只是想不出什么办法罢了。”荆轲说：“如今有一句话，可以用来解除燕国的忧患，可以替你樊将军报仇雪恨，怎么样？”樊於期走上前说：“到底怎么做？”荆轲说：“希望借你樊将军的头献给秦王，秦王一定高兴而又友好地接见我。我左手抓住他的衣袖，右手（用匕首）刺他的胸膛，这样，将军的仇报了，燕国被欺侮的耻辱也除掉了。将军是否有这个心意呢？”樊将军脱下一只衣袖，握住手腕走上前说：“这是让我日夜的痛心的事，今天才得到您的指教！”然后自杀。太子听说以后，连忙驱车赶到，伏在尸体上大哭，哭得非常伤心。但已经，是无可奈何的事了，便收拾好樊於期的头，用盒子装好。太子事先寻求天下最锋利的匕首，得到赵国徐夫人的匕首，用一百金把它买到，叫工匠在淬火时把毒药浸到匕首上。用人来试（那把用毒药水淬过的匕首），血沾湿衣裳，人没有不立马死亡的。接着整理行装，派遣荆轲上路。燕国有个勇士秦武阳，十二岁的时候，就杀人，人们不敢和他正视。于是叫秦武阳做助手。荆轲在等一个人，想和他一道去，可那个人住得很远没有来，因而停下等候他。过了一阵还没动身，太子嫌荆轲走晚了，怀疑他有改变初衷和后悔的念头，就又去请他动身，说：“时间跨度不早了，您难道没有动身的意思吗？请允许我先遣发秦武阳！”荆轲非常生气，怒斥太子道：“如果现在去了却不能够回来向太子复命，那是小人！现在光拿着一把匕首进入不可意料的强暴的秦国，我之所以停留下来，是因为等待我的客人好同他一起走。现在太子嫌我走晚了，那就让我现在和你们告别！”接着就出发了。太子和那些的知情的宾客，都穿着白衣，戴着白帽给他送行。到了易水上，祭过路神，就要上路了。高渐离敲着筑，荆轲和着节拍唱歌，发出悲凉的声音，众宾客都流着眼泪小声地哭。荆轲又走上前唱到：“风萧萧兮易水寒，壮士这一离去啊就永远不再回还！”又发出激愤的声音，众宾客都睁大了眼睛，头发都向上竖起顶住了帽子。于是荆轲就上车而去，始终不曾回头看一眼。到了秦国之后，带着价值千金的礼物，优厚地赠送给秦王的宠臣中庶子蒙嘉。蒙嘉事先为他对秦王说：“燕王确实非常害怕大王您的威风，不敢出兵来抗拒，愿意全国上下都做秦国的臣民，排在诸侯的行列里（意为：燕国愿意同别的诸侯一起尊秦王为天子）像秦国的郡县那样贡纳赋税，俾能守住祖先的宗庙。他们诚惶诚恐，不敢自己来陈述，恭谨地砍下樊於期的头颅，和献上燕国督亢一带的地图，用盒子装好，燕王很慎重的在朝廷将它送出，派使者来禀告大王。一切听凭大王吩咐。”秦王听了之后，非常高兴。穿上朝服，设九宾之礼，在咸阳宫接见燕国的使者。荆轲捧着装了樊於期头颅的盒子，秦武阳捧着装有地图的匣子，依次进来。到了台阶下，秦武阳害怕得变了脸色，秦国的群臣对此感到奇怪。荆轲回过头来对秦武阳笑了笑，走上前对秦王致歉说：“北方边远地区的人，没有见过天子，所以有些害怕，望大王能够稍稍原谅他，让他在大王的面前完成他的使命。”秦王对荆轲说：“起来吧，取来武阳所拿的地图！”荆轲拿来地图之后捧着，打开地图，地图全部展开后露出了匕首。随后荆轲左手抓住秦王的衣袖，右手拿着匕首刺秦王。没有刺到，秦王非常吃惊，耸身站了起来，挣断衣袖。拔剑，但剑太长，便拿起剑鞘。当时非常危急，剑插得太紧，没办法抽出来。荆轲追逐秦王，秦王绕着柱子跑秦国的君臣都惊呆了，事情突然发生，意料不到，大家都失去了常态。而按照秦国的法律，在殿上侍俸的群臣，不能带一点兵器；那些宫廷侍卫握着武器，都在殿下侍候，没有君王的命令不能上殿。正在慌急之中，而且也来不及召来侍卫，所以荆轲追逐秦王，大家仓猝间惊惶失措，没有武器用来击杀荆轲，仅仅用空手一起同荆轲搏斗。这时，秦王的御医夏无且用他手里的药袋扔向荆轲。秦王还正在绕着柱子跑，仓猝间惊惶失措，不知道怎么办。左右大臣都提醒说：大王快把剑背在背上！”大王快把剑背在背上！”秦王拔剑刺向荆轲，砍断了荆轲的左大腿。荆轲伤残倒地了，就举起匕首投向秦王，没投中，击中了柱子。秦王又砍击荆轲，荆轲受了八处剑伤。荆轲自己知道事情不能成功了，靠着柱子笑着，像撮箕一样地张开两腿坐在地上骂道：“事情之所以没有成功，是想活生生地劫持你，一定要得到约契来回报燕太子啊！”秦王的侍卫上前，斩杀了荆轲。事后，秦王还头昏眼花了好长一段时间。', NULL, '', 'indent', 1582049170, '5e4bb6fc21b47e006b0df132', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643759, '寡人之于国也', NULL, 894, 271, 0, 4, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', 'https://hanyu.baidu.com/s?wd=%E5%AF%A1%E4%BA%BA%E4%B9%8B%E4%BA%8E%E5%9B%BD%E4%B9%9F', '', '梁惠王曰：“寡人之于国也，尽心焉耳矣。河内凶，则移其民于河东，移其粟于河内；河东凶亦然。察邻国之政，无如寡人之用心者。邻国之民不加少，寡人之民不加多，何也？”
孟子对曰：“王好战，请以战喻。填然鼓之，兵刃既接，弃甲曳兵而走。或百步而后止，或五十步而后止。以五十步笑百步，则何如？”
曰：“不可，直不百步耳，是亦走也。”
曰：“王如知此，则无望民之多于邻国也。”
“不违农时，谷不可胜食也；数罟不入洿池，鱼鳖不可胜食也；斧斤以时入山林，材木不可胜用也。谷与鱼鳖不可胜食，材木不可胜用，是使民养生丧死无憾也。养生丧死无憾，王道之始也。”
“五亩之宅，树之以桑，五十者可以衣帛矣。鸡豚狗彘之畜，无失其时，七十者可以食肉矣。百亩之田，勿夺其时，数口之家，可以无饥矣；谨庠序之教，申之以孝悌之义，颁白者不负戴于道路矣。七十者衣帛食肉，黎民不饥不寒，然而不王者，未之有也。”
“狗彘食人食而不知检，涂有饿莩而不知发，人死，则曰：‘非我也，岁也。’是何异于刺人而杀之，曰：‘非我也，兵也’？王无罪岁，斯天下之民至焉。”', '', '（1）梁惠王：战国时期魏国的国君，姓魏，名罃（yīng）。魏国都城在大梁，今河南省开封市西北，所以魏惠王又称梁惠王。
（2）寡人：寡德之人．是古代国君对自己的谦称。
（3）焉耳矣：焉、耳、矣都是句末助词，重叠使用，加重语气。
（4）河内：今河南境内黄河以北的地方。古人以中原地区为中心，所以黄河以北称河内，黄河以南称河外。
（5）凶：谷物收成不好，荒年。
（6）河东：黄河以东的地方。在今山西西南部。黄河流经山西省境，自北而南，故称山西境内黄河以东的地区为河东。
（7）粟：谷子，脱壳后称为小米，也泛指谷类。
（8）亦然：也是这样。
（9）无如：没有像……。
（10）加少：更少。下文“加多”，更多。加，副词，更、再。
（11）好战：喜欢打仗。战国时期各国诸侯热衷于互相攻打和兼并。
（12）请以战喻：让我用打仗来做比喻。请，有“请允许我”的意思。
（13）填：拟声词，模拟鼓声。
（14）鼓之：敲起鼓来，发动进攻。古人击鼓进攻，鸣锣退兵。鼓，动词。之，没有实在意义的衬字。
（15）兵刃既接：两军的兵器已经接触，指战斗已开始。兵，兵器、武器。既，已经。接，接触，交锋。
（16）弃甲曳兵：抛弃铠甲，拖着兵器。曳，yè，拖着。
（17）走：跑，这里指逃跑。
（18）或：有的人。
（19）以：凭着，借口。
（20）笑：耻笑，讥笑。
（21）直：只是、不过。
（22）是：代词，这，指代上文“五十步而后止”。
（23）无：通“毋”，不要。
（24）不违农时：指农忙时不要征调百姓服役。违，违背、违反，这里指耽误。
（25）谷：粮食的统称。
（26）不可胜食：吃不完。胜，尽。
（27）数罟不入洿池：细密的渔网不放入深池里，这是为了防止破坏鱼的生长和繁殖。数（cù）:密。罟（gǔ）:网。洿（wū）:深。
（28）鳖（biē）:甲鱼或团鱼。
（29）斤：与斧相似，比斧小而刃横。
（30）时：时令季节。砍伐树木宜于在草木凋落，生长季节过后的秋冬时节进行。
（31）养生：供养活着的人。
（32）丧死：为死了的人办丧事。
（33）憾：遗憾。
（34）王道：以仁义治天下，这是儒家的政治主张。与当时诸侯奉行的以武力统一天下的“霸道”相对。
（35）五亩：先秦时五亩约合21世纪一亩二分多。
（36）树：种植。
（37）衣帛：穿上丝织品的衣服。衣，用作动词，穿。
（38）豚（tún）:小猪。
（39）彘（zhì）:猪。
（40）畜（xù）:畜养，饲养。
（41）无：通“毋”，不要。
（42）百亩之田：古代实行井田制，一个男劳动力可分得耕田一百亩。
（43）夺：失，违背。
（44）谨：谨慎，这里指认真从事。
（45）庠序：古代的乡学。《礼记？学记》：“古之教者，家有塾，党有庠，术有序，国有学。“家”，这里指“闾”，二十五户人共住一巷称为闾。塾，闾中的学校。党，五百户为党。庠，设在党中的学校。术，同“遂”，一万二千五百家为遂。序，设在遂中的学校。国，京城。学，大学。庠（xiánɡ）。
（46）教：教化。
（47）申：反复陈述。
（48）孝悌：敬爱父母和兄长。悌（tì）。
（49）义：道理。
（50）颁白：头发花白。颁，通“斑”。
（51）负戴：负，背负着东西。戴，头顶着东西。
（52）黎民：百姓。
（53）王：这里用作动词，为王，称王，也就是使天下百姓归顺。
（54）未之有：未有之。之，指代“七十者衣帛食肉，黎民不饥不寒，然而不王者”。
（55）食人食：前一个“食”，动词，吃；后一个“食”，名词，指食物。
（56）检：检点，制止、约束。
（57）涂：通“途”，道路。
（58）饿莩：饿死的人。莩（piǎo）:同“殍”，饿死的人。
（59）发：指打开粮仓，赈济百姓。
（60）岁：年岁、年成。
（61）罪：归咎，归罪。
（62）斯：则、那么。', '梁惠王说：“我对于国家，很尽心竭力的吧！河内遇到饥荒，就把那里的老百姓迁移到河东去，把粮食运到河内。河东饥荒的时候也这样。看看邻国的君主主办政事，没有像我这样尽心尽力的。邻国的百姓并不见减少，我的百姓不见增多，这是为什么呢？”
孟子回答说：‘“大王喜欢打仗，就让我用打仗来打比方吧。战鼓咚咚敲响，交战激烈了，战败的士兵丢盔弃甲拖着武器逃跑，有的跑了上百步才停下，有的跑了五十步就停了脚。凭自己只跑了五十步而耻笑别人跑了一百步，那怎么样呢？”
梁惠王说：“不行。他只不过没有逃跑到一百步罢了，可是这也同样是逃跑呀！”
孟子说：“大王如果懂得这个道理，就不必去期望您的国家的民众比邻国增多啦。
孟子说：“只要不违背农时，那粮食就吃不完；密孔的渔网不入池塘，那鱼鳖水产就吃不完；砍伐林木有定时，那木材便用不尽。粮食和鱼类吃不完，木材用无尽，这样便使老百姓能够养活家小，葬送死者而无遗憾了。老百姓养生送死没有缺憾，这正是王道的开始。”
孟子说：“在五亩大的住宅田旁，种上桑树，上了五十岁的人就可以穿着丝绸了；鸡鸭猪狗的繁殖饲养，不要错过时节，上了七十岁的人就可以经常吃到肉食了。一家一户所种百亩的田地，不误农时得到耕种，数口之家就不会闹灾荒了。注重乡校的教育，强调孝敬长辈的道理，须发花白的老人们就不再会肩挑头顶，年满七十岁的人能穿上丝绸、吃上鱼肉，老百姓不缺衣少食，做到了这些而不称王于天下的是决不会有的。”
孟子说：“现在，猪狗吃的是人吃的食物而不知道设法制止，路上出现饿死的人而不知道赈济饥民，百姓死了，就说：‘杀死人的不是我，是因为年岁不好。’这种说法与拿刀把人杀死后，说：‘杀死人的不是我，是兵器有什么不同？大王不要归罪于年成，这样，普天下的百姓便会涌向您这儿来了。”', NULL, '', 'indent', 1582050466, '5e4bbc141358aa006adb0c79', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643760, '廉颇蔺相如列传', NULL, 40, 139, 0, 4, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', '', '', '廉颇者，赵之良将也。赵惠文王十六年，廉颇为赵将，伐齐，大破之，取阳晋，拜为上卿，以勇气闻于诸侯。
蔺相如者，赵人也。为赵宦者令缪贤舍人。
赵惠文王时，得楚和氏璧。秦昭王闻之，使人遗赵王书，愿以十五城请易璧。赵王与大将军廉颇诸大臣谋：欲予秦，秦城恐不可得，徒见欺；欲勿予，即患秦兵之来。计未定，求人可使报秦者，未得。
宦者令缪贤曰：“臣舍人蔺相如可使。”王问：“何以知之？”对曰：“臣尝有罪，窃计欲亡走燕，臣舍人相如止臣曰：‘君何以知燕王？’臣语曰，臣尝从大王与燕王会境上，燕王私握臣手，‘愿结友’，以此知之，故欲往。相如谓臣曰：‘夫赵强而燕弱，而君幸于赵王，故燕王欲结于君。今君乃亡赵走燕，燕畏赵，其势必不敢留君，而束君归赵矣。君不如肉袒伏斧质请罪，则幸得脱矣。’臣从其计，大王亦幸赦臣。臣窃以为其人勇士，有智谋，宜可使。”
于是王召见，问蔺相如曰：“秦王以十五城请易寡人之璧，可予不？”相如曰：“秦强而赵弱，不可不许。”王曰：“取吾璧，不予我城，奈何？”相如曰：“秦以城求璧而赵不许，曲在赵。赵予璧而秦不予赵城，曲在秦。均之二策，宁许以负秦曲。”王曰：“谁可使者？”相如曰：“王必无人，臣愿奉璧往使。城入赵而璧留秦；城不入，臣请完璧归赵。”赵王于是遂遣相如奉璧西入秦。
秦王坐章台见相如，相如奉璧奏秦王。秦王大喜，传以示美人及左右，左右皆呼万岁。相如视秦王无意偿赵城，乃前曰：“璧有瑕，请指示王。”王授璧，相如因持璧却立，倚柱，怒发上冲冠，谓秦王曰：“大王欲得璧，使人发书至赵王，赵王悉召群臣议，皆曰‘秦贪，负其强，以空言求璧，偿城恐不可得’。议不欲予秦璧。臣以为布衣之交尚不相欺，况大国乎？且以一璧之故逆强秦之欢，不可。于是赵王乃斋戒五日，使臣奉璧，拜送书于庭。何者？严大国之威以修敬也。今臣至，大王见臣列观，礼节甚倨，得璧，传之美人，以戏弄臣。臣观大王无意偿赵王城邑，故臣复取璧。大王必欲急臣，臣头今与璧俱碎于柱矣！”
相如持其璧睨柱，欲以击柱。秦王恐其破璧，乃辞谢，固请，召有司案图，指从此以往十五都予赵。
相如度秦王特以诈佯为予赵城，实不可得，乃谓秦王曰：“和氏璧，天下所共传宝也。赵王恐，不敢不献。赵王送璧时斋戒五日。今大王亦宜斋戒五日，设九宾于廷，臣乃敢上璧。”秦王度之，终不可强夺，遂许斋五日，舍相如广成传。
相如度秦王虽斋，决负约不偿城，乃使其从者衣褐，怀其璧，从径道亡，归璧于赵。
秦王斋五日后，乃设九宾礼于廷，引赵使者蔺相如。相如至，谓秦王曰：“秦自缪公以来二十余君，未尝有坚明约束者也。臣诚恐见欺于王而负赵，故令人持璧归，间至赵矣。且秦强而赵弱，大王遣一介之使至赵，赵立奉璧来。今以秦之强而先割十五都予赵，赵岂敢留璧而得罪于大王乎？臣知欺大王之罪当诛，臣请就汤镬。唯大王与群臣孰计议之。”
秦王与群臣相视而嘻。左右或欲引相如去，秦王因曰：“今杀相如，终不能得璧也，而绝秦赵之欢。不如因而厚遇之，使归赵。赵王岂以一璧之故欺秦邪！”卒廷见相如，毕礼而归之。
相如既归，赵王以为贤大夫，使不辱于诸侯，拜相如为上大夫。
秦亦不以城予赵，赵亦终不予秦璧。
其后秦伐赵，拔石城。明年，复攻赵，杀二万人。秦王使使者告赵王，欲与王为好，会于西河外渑池。赵王畏秦，欲毋行。廉颇蔺相如计曰：“王不行，示赵弱且怯也。”赵王遂行。相如从。廉颇送至境，与王诀曰：“王行，度道里会遇之礼毕，还，不过三十日。三十日不还，则请立太子为王，以绝秦望。”王许之，遂与秦王会渑池。
秦王饮酒酣，曰：“寡人窃闻赵王好音，请奏瑟。”赵王鼓瑟。秦御史前书曰：“某年月日，秦王与赵王会饮，令赵王鼓瑟”。蔺相如前曰：“赵王窃闻秦王善为秦声，请奏盆缶秦王，以相娱乐。”秦王怒，不许。于是相如前进缶，因跪请秦王。秦王不肯击缶。相如曰：“五步之内，相如请得以颈血溅大王矣！”左右欲刃相如，相如张目叱之，左右皆靡。于是秦王不怿，为一击缶。相如顾召赵御史书曰：“某年月日，秦王为赵王击缶”。秦之群臣曰：“请以赵十五城为秦王寿。”蔺相如亦曰：“请以秦之咸阳为赵王寿。”
秦王竟酒，终不能加胜于赵。赵亦盛设兵以待秦，秦不敢动。
既罢，归国，以相如功大，拜为上卿，位在廉颇之右。
廉颇曰：“我为赵将，有攻城野战之大功，而蔺相如徒以口舌为劳，而位居我上，且相如素贱人，吾羞，不忍为之下！”宣言曰：“我见相如，必辱之。”相如闻，不肯与会。相如每朝时，常称病，不欲与廉颇争列。已而相如出，望见廉颇，相如引车避匿。
于是舍人相与谏曰：“臣所以去亲戚而事君者，徒慕君之高义也。今君与廉颇同列，廉君宣恶言，而君畏匿之，恐惧殊甚，且庸人尚羞之，况于将相乎？臣等不肖，请辞去。”蔺相如固止之，曰：“公之视廉将军孰与秦王？”曰：“不若也。”相如曰：“夫以秦王之威，而相如廷叱之，辱其群臣。相如虽驽，独畏廉将军哉？顾吾念之，强秦之所以不敢加兵于赵者，徒以吾两人在也。今两虎共斗，其势不俱生。吾所以为此者，以先国家之急而后私仇也。”
廉颇闻之，肉袒负荆，因宾客至蔺相如门谢罪，曰：“鄙贱之人，不知将军宽之至此也！”
卒相与欢，为刎颈之交。', '《廉颇蔺相如列传》生动刻画了廉颇、蔺相如、赵奢、李牧、赵惠文王等一批性格各异的人物形象，他们或耿直或忠厚，或鲁莽或机智，形象鲜明生动，令人叹服。
抓住人物特征，人物形象凸现纸上。司马迁善于抓住人物主要特征进行极力渲染。如在对事迹颇丰的蔺相如这一形象进行处理时，便抓住“智勇”这一特征为核心展开描述。正如他在本传传末所论赞的：“太史公曰：知死必勇，非死者难也，处死者难也。方蔺相如引璧睨柱，及叱秦王左右，势不过诛，然士或怯懦而不敢发。相如一奋其气，威信敌国；退而让颇，名重泰山。其处智勇，可谓兼之矣！”在对完璧归赵、渑池之会等事件进行描述时更是紧紧扣住蔺相如的机智勇敢这一特征，给读者留下深刻的印象。
层层衬染，极力蓄势，造成人物形象的张势。司马迁在文中极尽渲染之能事，层层蓄势，有如大江截流。如他在文中五次渲染相如操天下大势为己用之睿智：为国纾难，利用国际舆论，借使秦负曲之势，奉璧至秦；秦王得璧不偿城，相如以“璧有瑕，请指示王”诓得玉璧后，抓住秦王贪婪的弱点，欲以璧击柱，借“秦恐璧破”之势威胁秦王；抓住秦国二十余君“不坚明约束”之过，借理在我方之势，使人怀璧归赵；渑池之会，借“五步之内以颈血溅大王”之势，逼秦王就范，为一击缶；借“赵亦盛设兵以待秦”之势，迫使秦不敢动武。相如勇智，已是光彩照人。行文至此，司马迁笔势陡转：多谋善断、意气风发的蔺相如竟对无理取闹的廉颇一再退忍避让，连门客都感到羞愧。当门客要离开他时，才袒露他“先国家之急而后私仇也”的胸怀。相如的绝顶智慧和贤相风采凸现在读者的眼前。', '赵惠文王十六年：公元前283年。赵惠文王，赵国君主，名何。
阳晋：齐国城邑，在今山东菏泽西北。
上卿：战国时期诸侯国大臣中最高的官位。
宦者令：宦官的首领。
舍人：有职务的门客。
和氏璧：战国时著名的玉璧，是楚人卞和发现的，故名。事见《韩非子·何氏》。
秦昭王：即秦昭襄王，名则。
遗（wèi）：送。
徒见欺：白白地被欺骗。
亡走燕：逃到燕国去。
何以知燕王：根据什么知道燕王（会收留你）。
境上：指燕赵两国的边境。
幸于赵王：被赵王宠爱。幸，宠幸。
乃：却，竟然。
束君归赵：把您捆绑起来送还赵国。
肉袒伏斧质：解衣露体，伏在斧质上。袒，脱衣露体。质，同“锧”，承斧的砧板。
宜可使：可供差遣。宜，适宜。
不：同“否”。
曲：理屈，理亏。
均之二策：衡量这两个计策。均，衡量。之，这。
宁许以负秦曲：宁可答应，而让秦国承担理亏的责任。
奉：捧着。
完璧归赵：让璧完整无损地归还赵国。
章台：秦离宫中的台观名。
奏：进献。
美人：指秦王的姬妾。
偿赵城：把十五城补偿给赵国。
瑕：玉上的斑点或裂痕。
却立：倒退几步立定。
怒发上冲冠：愤怒得头发直竖，顶起了冠。形容极其愤怒。
负：倚仗。
布衣之交：平民间的交往。古代平民只穿麻衣、葛布，故称布衣。
逆：拂逆，触犯。
斋戒：古人祭祀之前，一定要沐浴更衣，节制饮食，表示虔诚，叫做斋戒。
书：指赵王的复信。
庭：同“廷”，朝堂。
严：尊重，敬畏。
修敬：致敬。
列观（guàn）：一般的台观，指章台。不在朝堂接见，说明秦对赵使的不尊重。
急：逼迫。
睨（nì）：斜视。
辞谢：婉言道歉。
固请：坚决请求（相如不要把璧撞破）。
有司：职有专司的官吏。
案图：查明地图。案，同“按”。
都：城邑。
特：只，只是。
详为：假装做。详，同“佯”，假装。
共传：等于说公认。
设九宾：一种外交上最隆重的仪式。有傧相九人依次传呼接引宾客上殿。宾，同“傧”。
舍：安置。
广成传（zhuàn）：广成，宾馆名。传，传舍，宾馆。
衣（yì）褐：穿着粗麻布短衣，指化装成平民百姓。
径道：小路。
缪公：即秦穆公。缪，同“穆”。
坚明约束：坚决明确地遵守信约。约束，信约。
间（jiàn）：抄小路，与上文“从径道亡”相应。
立：立刻。
就汤镬（huò）：指接收烹刑。汤，沸水。镬，大锅。
孰：同“熟”，仔细。
嘻：苦笑声。
因而厚遇之：趁此优厚地款待他。
卒廷见相如：终于在朝堂上接见蔺相如。
毕礼而归之：举行完廷见的外交大礼然后送他回国。
拔石城：攻取石城。石城，故址在今河南林州西南。
为好：修好。
西河外渑（miǎn）池：西河，黄河西边。渑池，今河南渑池。
欲毋行：想不去。
诀：告别。
度道里会遇之礼毕：估算前往渑池的路程和会谈完毕的时间。道里，路程。
绝秦望：断绝秦国要挟胁迫的念头。
好音：喜欢音乐。
瑟：古代乐器，形似琴而较长大。通常配有二十五根弦。
御史：官名。战国时御史专管图籍，记载国家大事。
秦声：秦国的音乐。
盆缶（fǒu）：均为瓦器。缶，同“缻”。秦人敲打盆缶作为唱歌时的节拍。
刃：刀锋。这里是杀的意思。
叱：喝骂。
靡：倒下，这里指后退。
怿（yì）：愉快。
为秦王寿：祝秦王长寿，指向秦王献礼。
竟酒：直到酒宴完毕。
盛设兵：多布置军队。
右：上。古人以右为尊。
相如素贱人：指蔺相如这个人做过太监的家臣，向来微贱。素，素来，向来。
争列：争位次的高下。
引车避匿：将车子调转躲避。
舍人：指蔺相如的门客。
相与：一起，共同。
孰与秦王：与秦王相比怎么样？孰与，与……相比。孰，谁，哪一个。
驽：愚笨，拙劣。
负荆：背着荆条，表示愿受鞭打。
因：通过。
将军：当时的上卿兼职将相，所以廉颇这样称呼蔺相如。
刎（wěn）颈之交：指能够共患难、同生死的朋友。刎颈，杀头。刎，割。', '廉颇是赵国优秀的将领。赵惠文王十六年，时为赵国将军的廉颇率领赵军征讨齐国，大败齐军，夺取了阳晋，晋升为上卿，从此他以英勇善战闻名于诸侯各国。蔺相如，赵国人，他是赵国的宦官首领缪贤家的门客。
赵惠文王的时候，得到了楚人的和氏璧。秦昭王听说了这件事，就派人给赵王送来一封书信，表示愿意用十五座城池交换和氏璧。赵王同大将军廉颇以及诸大臣们商量：如果把宝玉给了秦国，秦国的城邑恐怕不可能得到，白白地受到欺骗；如果不给他，又恐怕秦国来攻打。尚未找到合适的解决办法，寻找一个能到秦国去回复的使者，也未能找到。宦官令缪贤说：“我的门客蔺相如可以出使。”赵王问：“你是怎么知道他可以出使的？”缪贤回答说：“微臣曾犯过罪，私下打算逃亡到燕国去，我的门客相如劝阻我不要去，问我说：‘您怎么会了解燕王呢？’我对他说：‘我曾随从大王在国境上与燕王会见，燕王私下握住我的手，说“情愿跟您交个朋友”。因此了解他，所以打算投奔燕王。’相如对我说：‘赵国强，燕国弱，而您受宠于赵王，所以燕王想要和您结交。现在您是从赵国逃亡到燕国去，燕国惧怕赵国，这种形势下燕王必定不敢收留您，而且还会把您捆绑起来送回赵国。您不如脱掉上衣，露出肩背，伏在斧刃之下请求治罪，这样也许侥幸被赦免。’臣听从了他的意见，大王也开恩赦免了为臣。为臣私下认为这人是个勇士，有智谋，应该可以出使。”于是赵王立即召见，问蔺相如：“秦王用十五座城池请求交换我的和氏璧，能不能给他？”相如说：“秦国强，赵国弱，不能不答应它。”赵王说：“得了我的宝璧，不给我城邑，怎么办？”相如说：“秦国请求用城换璧，赵国如不答应，赵国理亏；赵国给了璧而秦国不给赵国城邑，秦国理亏。衡量一下两种对策，宁可答应它，使秦国来承担理亏的责任。”赵王说：“谁可以前往？”相如说：“大王如果无人可派，臣愿捧护宝璧前往出使。城邑归属赵国了，就把宝璧留给秦国；城邑不能归赵国，我一定把和氏璧完好地带回赵国。”赵王于是就派遣蔺相如带好和氏璧，西行入秦。
秦王坐在章台上接见蔺相如，相如捧璧呈献给秦王。秦王非常高兴，把宝璧传着给妻妾和左右侍从看，左右都高呼万岁。相如看出秦王没有用城邑抵偿赵国的意思，便走上前去说：“璧上有个小斑点，让我指给大王看。”秦王把璧交给他，相如于是手持璧玉退后几步靠在柱子上，怒发冲冠，对秦王说：“大王想得到宝璧，派人送信给赵王，赵王召集全体大臣商议，大家都说：‘秦国贪得无厌，倚仗它的强大，想用空话得到宝璧，说给我们城邑恐怕不可能。’商议的结果是不想把宝璧给秦国。但是我认为平民百姓之间的交往尚且互相不欺骗，更何况是大国之间呢！况且为了一块璧玉的缘故就使强大的秦国不高兴，也是不应该的。于是赵王斋戒了五天，派我捧着宝璧，在殿堂上恭敬地拜送国书。为什么要这样呢？是尊重大国的威望以表示敬意呀。如今我来到贵国，大王却在一般的台观上接见我，礼节十分傲慢；得到宝璧后，传给姬妾们观看，这样来戏弄我。我观察大王没有给赵王十五城的诚意，所以我又取回宝璧。大王如果一定要逼我，我的头今天就同宝璧一起在柱子上撞碎！”相如手持宝璧，斜视庭柱，就要向庭柱上撞去。秦王怕他把宝璧撞碎，便向他道歉，坚决请求他不要如此，并召来有司查看地图，指明从某地到某地的十五座城邑都给赵国。相如估计秦王只不过用欺诈手段假装给赵国城邑，实际上赵国根本不可能得到，于是就对秦王说：“和氏璧是天下公认的宝物，赵王惧怕贵国，不敢不奉献出来。赵王送璧之前，斋戒了五天，如今大王也应斋戒五天，在殿堂上安排九宾大典，我才敢献上宝璧。”秦王估量，毕竟不可能强力夺取，于是就答应斋戒五天，把相如安置在广成宾馆。相如估计秦王虽然答应斋戒，也必定背约不给城邑，便派他的随从穿上粗麻布衣服，怀中藏好宝璧，从小路逃出，把宝璧送回赵国。
秦王斋戒五天后，就在殿堂上安排了九宾的大典礼，宴请赵国使者蔺相如。相如来到后，对秦王说：“秦国从穆公以来的二十余位君主，从没有一个是能切实遵守信约的。我实在是害怕被大王欺骗而对不起赵王，所以派人带着宝璧回去，已从小路回到赵国了。况且秦国强大赵国弱小，大王派遣一位使臣到赵国，赵国立即就会把璧送来。如今凭着秦国的强大，先把十五座城邑割让给赵国，赵国哪里敢留下宝璧而得罪大王呢？我知道欺骗大王是应该被诛杀的，我愿意接受汤镬之刑，只希望大王和各位大臣从长计议此事！”秦王和群臣面面相觑，发出苦笑之声。侍从有人要拉相如去受刑，秦王趁机说：“如今杀了相如，终归还是得不到宝璧，反而破坏了秦赵两国的交情，不如趁此好好款待他，放他回到赵国，赵王难道会为了一块璧玉的缘故而欺骗秦国吗！”最终还是在殿堂上隆重地接见了相如，大礼完后让他回了国。
相如回国后，赵王认为他是一位有德行、有才能的贤大夫，出使诸侯国，能做到不辱使命，于是封相如为上大夫。此后秦国并没有把城邑给赵国，赵国也始终不给秦国宝璧。
此后秦国攻打赵国，夺取了石城。第二年，秦国再次攻打赵国，杀死两万人。
秦王派使者告诉赵王，想在西河外的渑池与赵王进行一次友好会见。赵王害怕秦国，打算不去。廉颇、蔺相如商量道：“大王如果不去，就显得赵国既软弱又胆小。”赵王于是前去赴会，蔺相如随行。廉颇送到边境，和赵王诀别说：“大王此行，估计路程和会谈结束，再加上返回的时间，不会超过三十天。如果三十天还没回来，就请您允许我们立太子为王，以断绝秦国要挟的妄想。”赵王答应了，便去渑池与秦王会见。秦王饮到酒兴正浓时，说：“我私下里听说赵王爱好音乐，请您奏瑟一曲！”赵王就弹起瑟来。秦国的史官上前来写道：“某年某月某日，秦王与赵王一起饮酒，令赵王弹瑟。”蔺相如上前说：“赵王私下里听说秦王擅长秦地土乐，请让我给秦王捧上盆，来相互为乐。”秦王发怒，不答应。这时蔺相如向前进献瓦缻，并跪下请秦王演奏。秦王不肯击缻，蔺相如说：“在这五步之内，如果我自杀，脖颈里的血可以溅在大王身上了！”秦王的侍从们想要杀蔺相如，蔺相如睁圆双眼大声斥骂他们，侍从们都吓得倒退。因此秦王很不高兴，也只好敲了一下缻。相如回头来招呼赵国史官写道：“某年某月某日，秦王为赵王击缻。”秦国的大臣们说：“请你们用赵国的十五座城池向秦王献礼。”蔺相如也说：“请你们用秦国的咸阳向赵王献礼。”直到酒宴结束，秦王始终也未能压倒赵王。赵国也部署了大批军队来防备秦国，因而秦国也不敢轻举妄动。
渑池会结束以后回到赵国，由于蔺相如功劳大，被封为上卿，官位在廉颇之上。廉颇说：“作为赵国的将军，我有攻战城池作战旷野的大功劳，而蔺相如只不过靠能说会道立了点功，可是他的地位却在我之上，况且蔺相如本来就出身卑贱，我感到羞耻，无法容忍在他的下面。”并且扬言说：“我遇见蔺相如，一定要羞辱他一番。”蔺相如听到这话后，不愿意和廉颇相会。每到上朝时，蔺相如常常声称有病，不愿和廉颇去争位次的先后。没过多久，蔺相如外出，远远看到廉颇，蔺相如就掉转车子回避。于是蔺相如的门客就一起来向蔺相如抗议说：“我们之所以离开亲人来侍奉您，是仰慕您高尚的节义呀。如今您与廉颇官位相同，廉颇传出坏话，而您却害怕躲避着他，胆怯得也太过分了，一般人尚且感到羞耻，更何况是身为将相的人呢！我们这些人没有出息，请让我们辞去吧！”蔺相如坚决地挽留他们，说：“诸位认为廉将军和秦王相比谁更厉害？”众人都说：“廉将军比不上秦王。”蔺相如说：“以秦王的威势，而我尚敢在朝廷上呵斥他，羞辱他的群臣，我蔺相如虽然无能，难道会害怕廉将军吗！但是我想到，强大的秦国之所以不敢对赵国用兵，就是因为有我们两人在呀。如今我们俩相斗，就如同两猛虎争斗一般，势必不能同时生存。我所以这样忍让，就是将国家的危难放在前面，而将个人的私怨搁在后面罢了！”廉颇听说了这些话，就脱去上衣，露出上身，背着荆鞭，由宾客引领，来到蔺相如的门前请罪，他说：“我这个粗野卑贱的人，想不到将军的胸怀如此宽大啊！”二人终于相互交欢和好，成了生死与共的好友。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d734a8757d5a0edb37", "shortContent": "本篇合传与附传兼备，以写廉颇、蔺相如为主，后面附有赵奢、赵括、李牧等人的事迹。通过这五人的传略，反映了赵国从赵惠文王到赵王迁七十年间的兴亡史，同时也反映出如何使用人才的问题；强调了君主善于举贤授能，知人善任，国家就强盛，君主若良莠不分，忠奸不辨，国家就败亡的主题。\n全文主要写了四个有名的故事，即“完璧归赵”、“渑池之会”、“廉蔺交欢”及“长平之战”。文章以双起法开篇，同时推出廉颇与蔺相如，而后又单...", "authors": ["安平秋", "李", "宇"], "pressName": "上海辞书出版社"}]', '', 'indent', 1582051194, '5e4bbef47796d9006ac062c3', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643763, '鸿门宴', NULL, 297, 139, 0, 5, '司马迁', NULL, 10065, '57b928e1c4c9710055907ac2', '汉', 'wen', '文', '', '', '沛公军霸上，未得与项羽相见。沛公左司马曹无伤使人言于项羽曰：“沛公欲王关中，使子婴为相，珍宝尽有之。”项羽大怒曰：“旦日飨士卒，为击破沛公军！”当是时，项羽兵四十万，在新丰鸿门；沛公兵十万，在霸上。范增说项羽曰：“沛公居山东时，贪于财货，好美姬。今入关，财物无所取，妇女无所幸，此其志不在小。吾令人望其气，皆为龙虎，成五采，此天子气也。急击勿失！”
楚左尹项伯者，项羽季父也，素善留侯张良。张良是时从沛公，项伯乃夜驰之沛公军，私见张良，具告以事，欲呼张良与俱去，曰：“毋从俱死也。”张良曰：“臣为韩王送沛公，沛公今事有急，亡去不义，不可不语。”良乃入，具告沛公。沛公大惊，曰：“为之奈何？”张良曰：“谁为大王为此计者？”曰：“鲰生说我曰：‘距关，毋内诸侯，秦地可尽王也。’故听之。”良曰：“料大王士卒足以当项王乎？”沛公默然，曰：“固不如也。且为之奈何？”张良曰：“请往谓项伯，言沛公不敢背项王也。”沛公曰：“君安与项伯有故？”张良曰：“秦时与臣游，项伯杀人，臣活之；今事有急，故幸来告良。”沛公曰：“孰与君少长？”良曰：“长于臣。”沛公曰：“君为我呼入，吾得兄事之。”张良出，要项伯。项伯即入见沛公。沛公奉卮酒为寿，约为婚姻，曰：“吾入关，秋毫不敢有所近，籍吏民封府库，而待将军。所以遣将守关者，备他盗之出入与非常也。日夜望将军至，岂敢反乎！愿伯具言臣之不敢倍德也。”项伯许诺，谓沛公曰：“旦日不可不蚤自来谢项王。”沛公曰：“诺。”于是项伯复夜去，至军中，具以沛公言报项王，因言曰：“沛公不先破关中，公岂敢入乎？今人有大功而击之，不义也。不如因善遇之。”项王许诺。
沛公旦日从百余骑来见项王，至鸿门，谢曰：“臣与将军戮力而攻秦，将军战河北，臣战河南，然不自意能先入关破秦，得复见将军于此。今者有小人之言，令将军与臣有郤。”项王曰：“此沛公左司马曹无伤言之。不然，籍何以至此？”项王即日因留沛公与饮。项王、项伯东向坐；亚父南向坐，——亚父者，范增也；沛公北向坐；张良西向侍。范增数目项王，举所佩玉玦以示之者三，项王默然不应。范增起，出，召项庄，谓曰：“君王为人不忍。若入前为寿，寿毕，请以剑舞，因击沛公于坐，杀之。不者，若属皆且为所虏！”庄则入为寿。寿毕，曰：“君王与沛公饮，军中无以为乐，请以剑舞。”项王曰：“诺。”项庄拔剑起舞。项伯亦拔剑起舞，常以身翼蔽沛公，庄不得击。
于是张良至军门见樊哙。樊哙曰：“今日之事何如？”良曰：“甚急！今者项庄拔剑舞，其意常在沛公也。”哙曰：“此迫矣！臣请入，与之同命。”哙即带剑拥盾入军门。交戟之卫士欲止不内。樊哙侧其盾以撞，卫士仆地。哙遂入，披帷西向立，瞋目视项王，头发上指，目眦尽裂。项王按剑而跽曰：“客何为者？”张良曰：“沛公之参乘樊哙者也。”项王曰：“壮士！——赐之卮酒。”则与斗卮酒。哙拜谢，起，立而饮之。项王曰：“赐之彘肩。”则与一生彘肩。樊哙覆其盾于地，加彘肩上，拔剑切而啖之。项王曰：“壮士！能复饮乎？”樊哙曰：“臣死且不避，卮酒安足辞！夫秦王有虎狼之心，杀人如不能举，刑人如恐不胜，天下皆叛之。怀王与诸将约曰：‘先破秦入咸阳者王之。’今沛公先破秦入咸阳，毫毛不敢有所近，封闭宫室，还军霸上，以待大王来。故遣将守关者，备他盗出入与非常也。劳苦而功高如此，未有封侯之赏，而听细说，欲诛有功之人。此亡秦之续耳。窃为大王不取也！”项王未有以应，曰：“坐。”樊哙从良坐。坐须臾，沛公起如厕，因招樊哙出。
沛公已出，项王使都尉陈平召沛公。沛公曰：“今者出，未辞也，为之奈何？”樊哙曰：“大行不顾细谨，大礼不辞小让。如今人方为刀俎，我为鱼肉，何辞为？”于是遂去。乃令张良留谢。良问曰：“大王来何操？”曰：“我持白璧一双，欲献项王，玉斗一双，欲与亚父。会其怒，不敢献。公为我献之。”张良曰：“谨诺。”当是时，项王军在鸿门下，沛公军在霸上，相去四十里。沛公则置车骑，脱身独骑，与樊哙、夏侯婴、靳强、纪信等四人持剑盾步走，从郦山下，道芷阳间行。沛公谓张良曰：“从此道至吾军，不过二十里耳。度我至军中，公乃入。”
沛公已去，间至军中。张良入谢，曰：“沛公不胜桮杓，不能辞。谨使臣良奉白璧一双，再拜献大王足下，玉斗一双，再拜奉大将军足下。”项王曰：“沛公安在？”良曰：“闻大王有意督过之，脱身独去，已至军矣。”项王则受璧，置之坐上。亚父受玉斗，置之地，拔剑撞而破之，曰：“唉！竖子不足与谋。夺项王天下者必沛公也。吾属今为之虏矣！”
沛公至军，立诛杀曹无伤。', '一主旨和情节
鸿门宴是项羽和刘邦在灭秦之后长达五年的斗争的开端。虽是开端，却在某种程度上预示了这场斗争的终结。这样说，是因为作者通过对这次宴会全过程（包括会前斗争和会后余波）的描写，生动地揭示了项羽的悲剧性格：他自矜功伐而有"妇人之仁"。这种性格不改变，他就必然以失败告终。而刘邦在宴会上能化险为夷，跟善于利用对方性格弱点也是分不开的。从这段史实可以看出领袖人物的性格在历史发展重要关头上所起的作用。
本文按情节的发展过程可分三部分。
第一部分（第1、2段），交代鸿门宴的由来。
文章先指出刘、项两军的驻地及双方兵力，表明项羽占有绝对优势，战争的主动权在他手中。下文所述人物活动均与这个背景有关。斗争起因是曹无伤告密。项羽听说"沛公欲王关中"，冒犯了他的尊严，当即决定进攻刘邦；他的主要谋士范增乘机揭露刘邦的野心，也力主进攻。二人认识上的差异，预示着他们对刘邦将采取不同的态度。
战争似乎已经迫在眉睫，却忽然出现了转机。项伯为报私恩夜访张良，劝他逃走，而张良反以"为韩王送沛公"为借口，将消息通知了刘邦。刘邦于是拉拢项伯，以谎言为自己辩护。项伯同意调停，并嘱咐刘邦"旦日不可不蚤自来谢项王"。由是而有鸿门宴上的斗争。
第二部分（第3、4段），写鸿门宴上的斗争。
节奏发展得快，气氛的变化也快。开始很平和，刘邦卑词"谢罪"，项羽说出告密人，可见怒气全消，有和解意，且设宴招待刘邦。但范增蓄意杀死刘邦，始而"数目项王，举所佩玉以示之者三"，继而命项庄舞剑，"因击沛公于坐，杀之"，使气氛越来越紧张。
于是张良出招樊哙。樊哙是刘邦的参乘，有保护刘邦的责任，但无与会资格。项羽得知他的身份后，知其来意，于是借赐酒缓和一下气氛。樊哙为了将众人注意力集中到自己身上来，不仅一切做得合乎礼法，而且忍辱吃了生彘肩。然后借项王"能复饮乎"之问慷慨陈词：于"王关中"一事，言虽有怀王之约，犹不敢自专，必待大王来；又就席间舞剑一事指责项王"欲诛有功之人"。故"项王未有以应"，反而赐坐。至此气氛又进一步缓和，但危机仍未解除。这是宴会斗争中的高潮。
第三部分（第5、6、7段），述会后余事，包括刘邦逃席，间道至军；张良留谢，项王受璧而范增破斗；刘邦诛杀曹无伤。
本文情节按项羽是否发动进攻、刘邦能否安然逃席两个问题逐层展开，波澜横生，矛盾迭出，扣人心弦。故事首尾相应，以曹无伤告密、项羽决定进攻始，以项羽受璧、曹无伤被诛终，虽属节选，亦有相对的完整性。
二人物形象
本文主要塑造项羽的形象，集中表现了他自矜功伐的性格。因为秦的主力被他击败，各路诸侯都听命于他，承认他的"霸主"地位，所以入关后一听说刘邦"欲王关中"，触犯了他的尊严，立即决定进攻；而在获悉刘邦"籍吏民，封府库"，等待他来处理，便放弃了进攻打算。更由于自矜功伐，他不把刘邦视为主要对手，不想在席间杀死他，而刘邦又注意维护他的尊严，使他动了"不忍"之心，所以对范增的多次暗示"默然不应"，对项庄、项伯筵间舞剑也不表态。这种"不忍"之心甚至使他对樊哙采取了格外宽容的态度：樊哙没有资格与会，本可以叱出，但他理解樊哙的心情，反而赐酒。樊哙陈词，虽有指责的话，但又把他看得比怀王更高，有"求赏"之意，都合乎他自矜功伐的心理，他内心有愧而"未有以应"，于是优礼有加，赐樊哙坐。自矜功伐而又"为人不忍"，虽一时成功，最后终不免于失败。
写项羽听了曹无伤告密之后的反应和听了项伯劝解之后的反应，形成两个极端，把项羽毫无主见，不辨忠奸，既易冲动又易受骗的性格勾画得十分鲜明。写项羽在鸿门宴上既不顾范增再三催促杀刘邦的暗示，又不制止项庄意在杀刘邦的舞剑，还把樊哙的愤激当作豪壮，对刘邦的逃席行为听之任之，处处表现他的优柔寡断。
司马迁是把项羽当作悲剧英雄来描写的，他曾这样评论道："自矜功伐，奋其私智而不师古，谓霸王之业，欲以力征经营天下，五年卒亡其国。"本文虽只写出人物的一个侧面，却未尝不能窥一斑而知全豹。
刘邦的形象也写得很生动。去鸿门"谢罪"，虽有项伯居中调停，其实是身入虎穴，命运难卜，但非此不足以平项羽之怒，仍如约而往；回到军中，"立诛杀曹无伤"，从这些事能看出他的坚决果断。他一向待人傲慢，这一回又是"先破秦入咸阳"，是"有大功"之人，但在项羽面前谦词卑礼，惟恐有所不至--在宴会上屈居下座，他安之若素，出而未辞也觉得于礼不合，这又表现了他能屈能伸的性格。至于他的狡诈多端，从骂鲰生、拉拢项伯、骂告密人等细节中，都表现得很明显。
三写作特点
1．在矛盾斗争中刻画人物。作者塑造项羽的形象主要抓住四个问题：是否对刘邦发动进攻；是否在席间杀死刘邦；对樊哙的越礼行为采取什么态度；对刘邦逃席又采取什么态度。这些，上面已有分析。这里附带说说樊哙。樊哙在危急的关头不顾卫士阻拦，闯入中军帐，表现了极大的勇敢。但入帐后的种种行动都是有礼有节的，先"披帷西向立，瞋目视项王"，以引起项羽注意；项羽赐酒，他先拜谢，然后站着喝，随后连生彘肩也吃了；他借机讥讽项王，却又替刘邦求赏，暗寓尊崇项羽之意，这又说明他粗中有细。
2．运用对照手法烘托人物形象。如：刘邦和项羽；张良和范增。', '桮杓（beishao）都是盛酒器皿，这里代指酒。桮，同“杯”。', '刘邦驻军霸上，还没有能和项羽相见，刘邦的左司马曹无伤派人对项羽说：“刘邦想要在关中称王，让子婴（ying）做丞相，珍宝全都被刘邦占有。”项羽大怒，说：“明天犒（kao）劳士兵，给我打败刘邦的军队！”这时候，项羽的军队40万，驻扎在新丰鸿门；刘邦的军队10万，驻在霸上。范增劝告项羽说：“沛公在崤山的东边的时候，对钱财货物贪恋，喜爱美女。现在进了关，不掠取财物，不迷恋女色，这说明他的志向不在小处。我叫人观望他那里的气运，都是龙虎的形状，呈现五彩的颜色，这是天子的气运呀！赶快攻打，不要失去机会。”
楚国的左尹项伯，是项羽的叔父，一向同留侯张良交好。张良这时正跟随着刘邦。项伯就连夜骑马跑到刘邦的军营，私下会见张良，把事情详细地告诉了他，想叫张良和他一起离开，说：“不要和（刘邦）他们一起死了。”张良说：“我是韩王派给沛公的人，现在沛公遇到危急的事，逃走是不守信义的，不能不告诉他。”于是张良进去，详细地告诉了刘邦。刘邦大惊，说：“这件事怎么办？”张良说：“是谁给大王出这条计策的？”刘邦说：“一个见识短浅的小子劝我说：‘守住函谷关，不要放诸侯进来，秦国的土地可以全部占领而称王。’所以就听了他的话。”张良说：“估计大王的军队足够用来抵挡项王吗？”刘邦沉默了一会儿，说：“当然不如啊。这又将怎么办呢？”张良说：“请您亲自告诉项伯，说刘邦不敢背叛项王。”刘邦说：“你怎么和项伯有交情？”张良说：“秦朝时，他和我交往，项伯杀了人，我使他活了下来；现在事情危急，幸亏他来告诉我。”刘邦说：“他和你年龄谁大谁小？”张良说：“比我大。”刘邦说：“你替我请他进来，我要像对待兄长一样对待他。”张良出去，邀请项伯。项伯就进去见刘邦。刘邦捧上一杯酒向项伯祝酒，和项伯约定结为儿女亲家，说：“我进入关中，一点东西都不敢据为己有，登记了官吏、百姓，封闭了仓库，等待将军到来。派遣将领把守函谷关，是为了防备其他盗贼进来和意外的变故。我日夜盼望将军到来，怎么敢反叛呢？希望您全部告诉项王我不敢背叛项王的恩德。”项伯答应了，告诉刘邦说：“明天早晨不能不早些亲自来向项王道歉。”刘邦说：“好。”于是项伯又连夜离去，回到军营里，把刘邦的话报告了项羽，趁机说：“沛公不先攻破关中，你怎么敢进关来呢？现在人家有了大功，却要攻打他，这是不讲信义。不如趁此好好对待他。”项王答应了。
刘邦第二天早晨带着一百多人马来见项王，到了鸿门，向项王解释说：“我和将军合力攻打秦国，将军在黄河以北作战，我在黄河以南作战，但是我自己没有料到能先进入关中，灭掉秦朝，能够在这里又见到将军。现在有小人的谣言，使您和我发生误会。”项王说：“这是沛公的左司马曹无伤说的，如果不是这样，我怎么会这么生气？”项王当天就留下刘邦，和他饮酒。项王、项伯朝东坐，亚父朝南坐。亚父就是范增。刘邦朝北坐，张良朝西陪侍。范增多次向项王使眼色，再三举起他佩戴的玉玦暗示项王，项王沉默着没有反应。范增起身，出去召来项庄，说：“君王为人心地不狠。你进去上前为他敬酒，敬酒完毕，请求舞剑，趁机把沛公杀死在座位上。否则，你们都将被他俘虏！”项庄就进去敬酒。敬完酒，说：“君王和沛公饮酒，军营里没有什么可以用来作为娱乐的，请让我舞剑。”项王说：“好。”项庄拔剑起舞，项伯也拔剑起舞，常常张开双臂像鸟儿张开翅膀那样用身体掩护刘邦，项庄无法刺杀。
于是张良到军营门口找樊哙。樊哙问：“今天的事情怎么样？”张良说：“很危急！现在项庄拔剑起舞，他的意图常在沛公身上啊！”樊哙说：“这太危急了，请让我进去，跟他同生死。”于是樊哙拿着剑，持着盾牌，冲入军门。持戟交叉守卫军门的卫士想阻止他进去，樊哙侧着盾牌撞去，卫士跌倒在地上，樊哙就进去了，掀开帷帐朝西站着，瞪着眼睛看着项王，头发直竖起来，眼角都裂开了。项王握着剑挺起身问：“客人是干什么的？”张良说：“是沛公的参乘樊哙。”项王说：“壮士！赏他一杯酒。”左右就递给他一大杯酒，樊哙拜谢后，起身，站着把酒喝了。项王又说：“赏他一条猪的前腿。”左右就给了他一条未煮熟的猪的前腿。樊哙把他的盾牌扣在地上，把猪腿放（在盾）上，拔出剑来切着吃。项王说：“壮士！还能喝酒吗？”樊哙说：“我死都不怕，一杯酒有什么可推辞的？秦王有虎狼一样的心肠，杀人惟恐不能杀尽，惩罚人惟恐不能用尽酷刑，所以天下人都背叛他。怀王曾和诸将约定：‘先打败秦军进入咸阳的人封作王。’现在沛公先打败秦军进了咸阳，一点儿东西都不敢动用，封闭了宫室，军队退回到霸上，等待大王到来。特意派遣将领把守函谷关的原因，是为了防备其他盗贼的进入和意外的变故。这样劳苦功高，没有得到封侯的赏赐，反而听信小人的谗言，想杀有功的人，这只是灭亡了的秦朝的继续罢了。我以为大王不应该采取这种做法。”项王没有话回答，说：“坐。”樊哙挨着张良坐下。坐了一会儿，刘邦起身上厕所，趁机把樊哙叫了出来。
刘邦出去后，项王派都尉陈平去叫刘邦。刘邦说：“现在出来，还没有告辞，这该怎么办？”樊哙说：“做大事不必顾及小节，讲大礼不必计较小的谦让。现在人家正好比是菜刀和砧板，我们则好比是鱼和肉，告辞干什么呢？”于是就决定离去。刘邦就让张良留下来道歉。张良问：“大王来时带了什么东西？”刘邦说：“我带了一对玉璧，想献给项王；一双玉斗，想送给亚父。正碰上他们发怒，不敢奉献。你替我把它们献上吧。”张良说：“好。”这时候，项王的军队驻在鸿门，刘邦的军队驻在霸上，相距四十里。刘邦就留下车辆和随从人马，独自骑马脱身，和樊哙、夏侯婴、靳强、纪信四人拿着剑和盾牌徒步逃跑，从郦山脚下，取道芷阳，抄小路走。刘邦对张良说：“从这条路到我们军营，不过二十里罢了，估计我回到军营里，你才进去。”
刘邦离去后，从小路回到军营里。张良进去道歉，说：“刘邦禁受不起酒力，不能当面告辞。让我奉上白璧一双，拜两拜敬献给大王；玉斗一双，拜两拜献给大将军。”项王说：“沛公在哪里？”张良说：“听说大王有意要责备他，脱身独自离开，已经回到军营了。”项王就接受了玉璧，把它放在座位上。亚父接过玉斗，放在地上，拔出剑来敲碎了它，说：“唉！这小子不值得和他共谋大事！夺项王天下的人一定是刘邦。我们都要被他俘虏了！”
刘邦回到军中，立刻杀掉了曹无伤。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d634a8757d5a0edb35", "shortContent": "《鸿门宴》是《史记·项羽本纪》中一个相对独立的片断，它标志着秦末起义军两大首领刘邦和项羽由联合破秦到互争天下的转折点。文章以刘邦赴项营请罪为核心，连同赴营以前和逃出以后为三个组成部分。在一千五百多字中，司马迁生动地记述了两家的明争暗斗。鸿门宴上，觥筹交错，刀光剑影。出场人物，个个形象鲜明，既保持了历史的真实，又“诙诡几类平话”（吕思勉《秦汉史》），无愧是两千年来脍炙人口的名篇。\n这段文字之所以脍炙...", "authors": ["赖汉屏"], "pressName": "上海辞书出版社"}]', '', 'indent', 1582056787, '5e4bd4c18a84ab006a3fed92', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643795, '催租行', NULL, 0, 2061, 1, 0, '范成大', NULL, 10207, '57bc4f938ac247006311ea81', '宋', 'shi', '诗', '', '', '输租得钞官更催，踉跄里正敲门来。
手持文书杂嗔喜，我亦来营醉归耳！
床头悭囊大如拳，扑破正有三百钱。
不堪与君成一醉，聊复偿君草鞋费。
', '', '输租：缴了租。
钞：户钞，官府发给缴租户的收据。
踉跄（liàngqiàng）：走路不稳的样子。
里正：即里长，古代乡里小吏，专管催督赋税。
文书：催租的文件。一说指上文的户钞。
杂嗔（chēn）喜：又是生气又是高兴。嗔，怒，生气。
亦：只是，不过。
营醉归：图谋一醉以归。意即勒索。营，图求。
悭（qiān）囊：悭吝者的钱袋。此处指储蓄零钱的瓦罐，即“扑满”，取钱时须把罐打破，故下文说“扑破”。
扑破：取钱时把瓦罐打破。
不堪：不够。君：指里正。
聊：姑且。君：对里正的尊称。
草鞋费：行脚僧人有所谓“草鞋钱”，此指“跑腿费”，是公差、地保等勒索小费的代名词。', '缴了租税得到收据官府还派人催，里正踉踉跄跄忽然又来敲门。
拿着收据看了看又是发怒又是笑，我来只不过是要找杯酒喝而已。
床头有个如拳头那么大的积钱罐，打破瓦罐取出攒下的三百文钱。
这点钱还不够让您喝醉一次，姑且给您算作补偿您的跑路费。
', '[{"bookId": "60d3dff0f4aeaa0de5beb1bc", "bookTitle": "宋诗鉴赏辞典（新一版）", "articleId": "610ea732c6e67846a9213b6c", "shortContent": "这首诗，只八句五十六字，却有情节、有人物，展现了一个颇有戏剧性的场面，使人既感到可笑，又感到可恨、可悲。\n第一句单刀直入，一上来就抓住了“催租”的主题。全篇只有八句，用单刀直入法是适宜的，也是一般人能够想到、也能够做到的。还有，“催租”是个老主题，用一般人能够想到、也能够做到的单刀直入法写老主题，容易流于一般化。然而一读诗，就会感到不但不一般化，而且很新颖。这新颖，首先来自作者选材的角度新。请看：...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}, {"bookId": "64605ae65fc8182fe98b6f1a", "bookTitle": "宋诗三百首鉴赏辞典", "articleId": "646b75d85e6bb82b8ce0c384", "shortContent": "这首诗，只八句五十六字，却有情节、有人物，展现了一个颇有戏剧性的场面，使人既感到可笑，又感到可恨、可悲。\n\n第一句单刀直入，一上来就抓住了“催租”的主题。全篇只有八句，用单刀直入法是适宜的，也是一般人能够想到、也能够做到的。还有，“催租”是个老主题，用一般人能够想到、也能够做到的单刀直入法写老主题，容易流于一般化。然而一读诗，就会感到不但不一般化，而且很新颖。这新颖，首先来自作者选材的角度新。请看...", "authors": ["霍松林"], "pressName": "上海辞书出版社"}]', '', 'center', 1583431553, '5e60cef81358aa006b02e55d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643823, '陶庵梦忆 · 卷一 · 木犹龙 ', NULL, 1, 227, 1, 1, '张岱', NULL, 10007, '57ba82be165abd0066234de7', '明', 'wen', '文', '', '', '木龙出辽海，为风涛漱击，形如巨浪跳蹴，遍体多著波纹，常开平王得之辽东，辇至京。开平第毁，谓木龙炭矣。及发瓦砾，见木龙埋入地数尺，火不及，惊异之，遂呼为龙。不知何缘出易于市，先君子以犀觥十七只售之，进鲁献王，误书“木龙”犯讳，峻辞之，遂留长史署中。先君子弃世，余载归，传为世宝。丁丑诗社，恳名公人赐之名，并赋小言咏之。周墨农字以“木犹龙”，倪鸿宝字以“木寓龙”，祁世培字以“海槎”，王士美字以“槎浪”，张毅儒字以“陆槎”，诗遂盈帙。木龙体肥痴，重千馀斤，自辽之京、之兖、之济，由陆。济之杭，由水。杭之江、之萧山、之山阴、之余舍，水陆错。前后费至百金，所易价不与焉。呜呼，木龙可谓遇矣！
余磨其龙脑尺木，勒铭志之，曰：“夜壑风雷，骞槎化石；海立山崩，烟云灭没；谓有龙焉，呼之或出。”又曰：“扰龙张子，尺木书铭；何以似之？秋涛夏云。”', '张岱除了景物描写清新自然之外，本篇短小精悍的小品文，也尽显他长于叙事状物之才，尤其张岱刻在木犹龙上的铭文：“夜壑风雷，骞槎化石；海立山崩，烟云灭没；谓有龙焉，呼之或出。”好像一幅惊天动地、壮阔富丽的龙出世的画面在眼前展开。', '木龙：即木犹龙，一种化石。
跳蹴：跳跃。
常开平王：常遇春，字伯仁，安徽怀远人。明代开国功臣，死后追封开平王。
京：这里指南京。
发：挖掘。
出易：出卖，交易。
先君子：已去世的父亲。
犀觥：犀牛角做的饮酒器。
鲁献王：“献”当作“宪”，即第十代，鲁王朱寿鋐，万历二十八年封，崇祯九年卒，谥号宪。
峻辞：严词拒绝。
弃世：去世。
丁丑：崇祯十年，公元1637年。
小言：简短的诗词。
周墨农：字又龙，号墨农，张岱的好友。
字：取名。
倪鸿宝：名元璐，字汝玉，号鸿宝，浙江上虞人，官至尚书，以书画名于世。
祁世培：名彪佳，字虎子，又字幼文、弘吉，号世培，别号远山堂主人，绍兴人，著名戏曲家。
王士美：名业洵，字士美，浙江余姚人。
张毅儒：张岱的族弟张弘，排行第八，善诗文。
盈帙：满卷。
与：抵得上。
遇：受到赏识，礼遇。
尺木：龙头上面的如博山形的东西。唐代段成式《酉阳杂俎·鳞介篇》：龙头上有一物，如博山形，名尺木。龙无尺木，不能升天。
骞槎：汉代张骞曾出使西域，传说寻求到了河源，后人附会说他使用了槎，槎是通往天河的工具。见宋陈元靓《岁时广记》引《荆楚岁时记》：“汉武帝令张骞使大夏，寻河源，乘槎经月而去，至一处，见城郭如官府，室内有一女织。又见一丈夫，牵牛饮河。骞问曰：‘此是何处？’答曰：‘可问严君平。’织女取支机石与骞还。后至蜀问君平，君平曰：‘某年月日，客星犯牛女。’所得支机石，为东方朔所识。”
张子：作者的自称。', '木龙出自辽海，经历了风浪的冲击，它的形状就像巨浪跳跃的样子，全身附着许多波纹，开平王常遇春在辽东得到它，并用专车把它运到京城。后来开平王府遭遇火灾，大家都认为木龙也被焚毁成为焦炭了。等到扒开瓦砾，发现木龙埋在地下几尺深，火没有烧到它，大家对此都感到非常惊奇，于是就把它称作“龙”。不知道什么缘故木龙后来被拿到集市上兜售，家父用十七只犀角酒杯买到了它，意欲进献给鲁宪王，因为进献的章表上误写了“木龙”二字，犯了忌讳，被鲁王严词拒绝，于是它就留在了父亲的长史官署中。父亲去世后，我把它运回家中，当作传世之宝。
丁丑年（1637年）朋友们起诗社，我就请诗社里的名人给它起个名字，并赋短诗来歌咏它。周墨农起名为“木犹龙”，倪元璐起名为“木寓龙”，祁彪佳起名为“海槎”，王业洵起名为“槎浪”，张弘起名为“陆槎”，为它所赋的诗甚至将近一册。木龙体积庞大，重达一千多斤，从辽东到京城，到究州，到济州，走的是陆路。再从济州到杭州，走的是水路。最后从杭州到江边，到萧山，到山阴，到我家，水路、陆路交错。除去购买时的花费，前后所有花费有一百两银子。哎呀，木龙真是际遇难得啊！
我磨平木龙头上的尺木，刻上铭文：“曲谷中风雷大作，好像张骞所乘的船化为巨石；大海波涛卷立而起，高山震满崩塌，烟云在空中翻滚；有人说有龙要出来了。”又写道：“扰龙的张岱，在龙头的尺木上刻下铭文。用什么来比拟这木龙呢？秋天的波涛，夏天的云彩。', NULL, '', 'indent', 1585418528, '5e65ba5243c2570076a1e4cb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643825, '陶庵梦忆 · 卷一 · 吴中绝技', NULL, 1, 227, 1, 1, '张岱', NULL, 10007, '57ba82be165abd0066234de7', '明', 'wen', '文', '', '', '吴中绝技：陆子冈之治玉，鲍天成之治犀，周柱之治嵌镶，赵良璧之治梳，朱碧山之治金银，马勋、荷叶李之治扇，张寄修之治琴，范昆白之治三弦子，俱可上下百年保无敌手。
但其良工苦心，亦技艺之能事。至其厚薄深浅，浓淡疏密，适与后世赏鉴家之心力、目力针芥相投，是岂工匠之所能办乎？
盖技也而进乎道矣。', '作者提到的这些各具特色的“俱可上下百年，保无敌手”的技艺大师，令现今这个多为工匠而难为大师的社会的人们心生无限向往。后文提到的能工巧匠与鉴赏家的关系，不禁让人联想到千里马与伯乐的关系，知音难觅宁断琴，高山流水无处寻。', '陆子冈：苏州琢玉名师、子冈珠宝工坊创始人，生活于明代嘉靖、万历年间，技艺高超，为文人许渭，张岱等推重，被誉为“吴中绝技”。当时皆称“良玉虽集京师，工巧则推苏郡。”张岱在《陶庵梦忆》中称陆子冈等制玉、治扇等苏州鬼工”为“吴中绝技”陆子冈，明嘉靖十八年（1539年）开设琢玉作坊。时人将子冈玉与唐伯虎仕女画共推为吴地风雅之表征。不过，他的玉作几乎为皇室专利品。', '吴中的绝技有：陆子冈的苏州玉雕；鲍天成的犀角雕刻；周柱的镶嵌；赵良壁制作的梳子；朱碧山的金银器雕刻；马勋、荷叶李做的苏州折扇；张寄修制作的琴；范昆白制作的三弦琴。这些人都可以流传百世，没有什么人可以和他们相提并论。
然而这些身怀绝技的匠人们苦心孤诣，也只能是在技艺上极力提高自己，至于东西高低优劣的评价，还要靠与后世鉴赏家心力、目力上的心神相合，而这些就不是能工巧匠所能办到的事情了。
这大概是因为鉴赏高于技艺。', NULL, '', 'indent', 1585418874, '5e65bac191db2800767e87ef', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643884, '陶庵梦忆 · 卷五 · 扬州清明', NULL, 2, 227, 1, 1, '张岱', NULL, 10007, '57ba82be165abd0066234de7', '明', 'wen', '文', '', '', '扬州清明日，城中男女毕出，家家展墓。虽家有数墓，日必展之。故轻车骏马，箫鼓画船，转折再三，不辞往复。监门小户亦携肴核纸钱，走至墓所、祭毕，则席地饮胙。自钞关南门、古渡桥、天宁寺、平山堂一带，靓妆藻野，袨服缛川。随有货郎，路旁摆设古董古玩并小儿器具。博徒持小杌坐空地，左右铺衵衫半臂，纱裙汗帨，铜炉锡注，瓷瓯漆奁，及肩彘鲜鱼、秋梨福橘之属，呼朋引类，以钱掷地，谓之“跌成”；或六或八或十，谓之“六成”“八成”“十成”焉。百十其处，人环观之。是日，四方流离及徽商西贾、曲中名妓，一切好事之徒，无不咸集。长塘丰草，走马放鹰；高阜平冈，斗鸡蹴踘；茂林清樾，劈阮弹筝。浪子相扑，童稚纸鸢，老僧因果，瞽者说书，立者林林，蹲者蛰蛰。日暮霞生，车马纷沓。宦门淑秀，车幕尽开，婢媵倦归，山花斜插，臻臻簇簇，夺门而入。余所见者，惟西湖春、秦淮夏、虎丘秋，差足比拟。然彼皆团簇一块，如画家横披；此独鱼贯雁比，舒长且三十里焉，则画家之手卷矣。南宋张择端作《清明上河图》，追摹汴京景物，有方美人之思，而余目盱盱，能无梦想！', '', '', '', NULL, '', 'indent', 1586124060, '5e6b2ba321b47e00696edd3d', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643903, '陶庵梦忆 · 卷七 · 西湖香市', NULL, 0, 227, 1, 1, '张岱', NULL, 10007, '57ba82be165abd0066234de7', '明', 'wen', '文', '', '', '西湖香市，起于花朝，尽于端午。山东进香普陀者日至，嘉湖进香天竺者日至，至则与湖之人市焉，故曰香市。然进香之人市于三天竺，市于岳王坟，市于湖心亭，市于陆宣公祠，无不市，而独凑集于昭庆寺。昭庆寺两廊故无日不市者，三代八朝之骨董，蛮夷闽貊之珍异，皆集焉。至香市，则殿中边甬道上下、池左右、山门内外，有屋则摊，无屋则厂，厂外又棚，棚外又摊，节节寸寸。凡胭脂簪珥、牙尺剪刀，以至经典木鱼、伢儿嬉具之类，无不集。此时春暖，桃柳明媚，鼓吹清和，岸无留船，寓无留客，肆无留酿。袁石公所谓“山色如娥，花光如颊，温风如酒，波纹如绫”，已画出西湖三月。而此以香客杂来，光景又别。士女闲都，不胜其村妆野妇之乔画；芳兰芗泽，不胜其合香芫荽之薰蒸；丝竹管弦，不胜其摇鼓欱笙之聒帐；鼎彝光怪，不胜其泥人竹马之行情；
宋元名画，不胜其湖景佛图之纸贵。如逃如逐，如奔如追，撩扑不开，牵挽不住。数百十万男男女女、老老少少，日簇拥于寺之前后左右者，凡四阅月方罢。恐大江以东，断无此二地矣。崇祯庚辰三月，昭庆寺火。是岁及辛巳、壬午洊饥，民强半饿死。壬午虏鲠山东，香客断绝，无有至者，市遂废。辛巳夏，余在西湖，但见城中饿殍舁出，扛挽相属。时杭州刘太守梦谦，汴梁人，乡里抽丰者多寓西湖，日以民词馈送。有轻薄子改古诗诮之曰：“山不青山楼不楼，西湖歌舞一时休。暖风吹得死人臭，还把杭州送汴州。”可作西湖实录。', '《西湖香市》是明末清初文学家张岱创作的一篇散文。文中第一段写香市的时间和来客；第二段写香市遍布西湖，尤以昭庆寺最热闹，香市的物品名目繁多，应有尽有；第三段写香市的盛况，人数多，范围大，历时久；第四段写香市的衰败，揭露了当时社会的黑暗。全文记叙层次分明，条理清晰；描绘生动细致，具体形象；语言优美，文笔清越；揭露深刻，讽刺尖锐，于写景抒情中寄寓兴亡的感慨。
据范祖述《杭俗遗闻》“天竺香市”条载，每逢二月十九观音圣诞，信徒甚重。当日去者，自城门至山门十五里中，挨肩擦背，何止万万。其盛况可见一斑。如此大的排场，自然也形成了一个极大的消费机会。梁绍壬《两般秋雨庵随笔》卷四“香市”条云，西湖昭庆寺山门前，两廊设市，卖木鱼、花篮、耍货、梳具等物，皆寺僧作以售利者也。每逢香市，此地妇女填集如云。作者历经西湖香市的兴衰，有感于此，创作了此文。', '西湖：今杭州西湖，在杭州城西。
花朝：花朝节，相传为百花生日，时在农历二月十二日，或说二月初二，或说二月十五。
普陀：山名，在浙江定海县海中，是佛教圣地。
嘉湖：今浙江嘉兴、湖州。
天竺：指杭州西湖之上、中、下三天竺寺，西湖游览胜地之一。
市：做买卖。
岳王坟：即宋岳飞墓地，在栖霞岭下，西湖游览胜地之一。
湖心亭：在西湖中央，西湖游览胜地之一。
陆宣公祠：即唐陆贽的祠庙，在孤山麓，西湖游览胜地之一。
昭庆寺：在旧城西钱塘门外，后晋天福年间，吴越王钱镠建。
三代：指夏、商、周。
八朝：指汉、魏及六朝。
骨董：即古董，指古代留传下来的器物。
蛮夷：指广东。
闽貊（mò）：指福建。
山门：佛寺的大门。佛寺多在山间，所以称寺门为山门。
厂：棚屋无壁称厂。
节节寸寸：形容处处排连有摊棚。
簪：发针。
珥（ěr）：耳环。
牙尺：象牙做的尺子。
伢儿：吴越方言，称呼儿童。
嬉具：玩具。
鼓吹清和：乐声悠扬。鼓吹，指管乐。
袁石公：即袁宏道，字中郎，号石公，湖北公安人，明代文学家。
山色如娥：形容山的颜色像女子的娥眉。
花光如颊：形容花的颜色像女子的面颊。
闲都：文雅美丽。
不胜其：比不上那些。
乔画：指妇女涂脂抹粉，修饰面容。
芗（xiāng）泽：香气。
芫（yán）荽（sui）：一种有香味的植物，俗称香菜。
颌笙：以口吹笙。
聒帐：嘈杂，吵闹。
鼎彝：泛指古代的青铜器，此指古代金属食具和祭器。
行情：价格。
佛图：佛像，佛画。
撩扑不开：挑拆不开。
阅：经历。香市要经历四个月之久才停歇。
断无此二地矣：断然没有像这样的第二个地方了。
崇祯庚辰：即明崇祯十三年（1640年）。
辛巳壬午：指崇祯十四、十五年（1641年、1642年）。
荐饥：一再发生饥荒。荐，屡次，接连。
强半：大半。
梗：阻隔。指清军入侵。
殍（piǎo）：饿死的人。
舁（yú）：抬。
扛挽相属：抬的扛的接连不断。
抽丰：亦作“秋风”。即分肥，依托官府，为官吏索取馈赠，赚人财物。俗称“打秋风”、“撞太岁”。
日以民词馈送：经常以包揽民间诉讼所得的贿赂，馈送给太守。
古诗：为宋林升《题临安邸》：“山外青山楼外楼，西湖歌舞几时休？暖风吹得游人醉，直把杭州作汴州。”
诮：讥讽。
实录：实际情形的写照。', '西湖的香客市场，于花朝节开始，到端午节结束。山东来普陀山进香的香客一天就到了，嘉兴湖州来天竺寺进香的香客也一天就到了，来的香客与西湖的人一起做买卖，所以叫香市。
凡是来进香的人，在三天竺做买卖，在岳王坟做买卖，在湖心亭做买卖，在陆宣公祠做买卖，西湖没有一个地方不做买卖，然而只有在昭庆寺做买卖最集中，所以昭庆寺的两个走廊没有一天不做买卖。三代八朝的古董，广东福建外洋的珍奇都集中到这里，到香客的市场，则殿中甬道的上下，池的左右，寺门的内外，有屋的就摆摊，没有屋的就摆场，场外又有棚，棚外又有摊，处处排连有摊棚。凡是胭脂发针耳环，牙尺剪刀，甚至经典木鱼，孩儿玩具之类，没有不汇集来的。
这个时候正值春暖，桃花杨柳艳丽可爱，乐声清脆悠扬，西湖岸边没有停留的船，店里没有停留的香客，酒肆里没有多余的美酒。袁石公所说的“山的颜色像女子的娥眉，花的颜色像女子的面颊，湖水的波纹像绫绸，温暖的春风像酒一样醉人”，这些话已描画出西湖三月的美景，然而当香客拥来的时候，风光景色又大不相同了。那士人美女的文雅美丽，比不上那些农村妇女涂脂抹粉的打扮；那芳兰的香气，比不上那些香花香草的浓香；那丝竹管弦的音乐，比不上那些手里摇鼓用口吹笙的热闹；那青铜器的光彩，比不上那些泥人竹马的价格；那宋元时的名画，比不上那些湖景佛像的纸贵。香客们像在跑像在赶，像在奔像在追，排斥不开，拉挽不住。数百十万的男男女女，老老少少，每天都拥挤在寺的前后左右，一直经历到四月才停止，恐怕长江以南，断然没有第二个像这样的地方了。
崇祯十三年的三月，昭庆寺火灾。从这年到崇祯十四、十五年的连续发生饥荒，百姓大半饿死。崇祯十五年外来交通阻隔，山东香客断绝，就没有香客来了，香市也就废了。崇祯十四年夏天，我在西湖，只见城中饿死的人被抬了出来，扛的拉的接连不断。当时杭州太守刘梦谦，是汴梁人，乡里分肥打秋风的人，多住在西湖，每天要收取民间诉讼的贿赂送给太守。有一轻薄的人改了一首古诗来讥讽他：“山不像青山楼不像楼，西湖歌舞一时休。暖风吹得死人发臭，还把杭州葬送给汴州。”这首诗可以作为西湖实况的记录。', NULL, '贵州师范学院文学院教授周复刚《中国古典文学名著分类集成——散文卷六》：本文追忆明末西湖香市的繁华场景以及后来的变迁，反映出明末城市经济文化生活的个重要场景，揭露了明亡前后杭州人民的深重苦难。还有一个易被忽略之处：当时许多人喜欢“日以民词馈送”于太守大人。这种“民间文学”也同样可以用来“观风俗、知厚薄”的，轻薄子所改宋人诗句，其实并不轻薄，倒是字字血泪，沉重悲凛。越是社会动荡不安、民怨沸腾之际，此类“民间文学”越多。古往今来，大抵如此。
北京师范大学学报原主编林邦均《陶庵梦忆注评》：文章介绍西湖香市，从香市每年的起讫日期、起因开头，重点详述昭庆寺，其内外栉比鳞次的摊位、琳琅满目的货物应有尽有。然后用一系列前后对比的排比句式，突出昭庆寺香市的人众、货物、歌乐，具有村、俗、朴、野的特色，而其人众之多、历时之长、场面之热闹，江东独有。作者之擅长夸张铺排盛大热闹场面，可见一斑。最后由于天灾人祸，香市迅速衰败。“城中饿殍舁出，扛挽相属”的惨象与上文形成盛衰的强烈反差。即便民生涂炭如此，内忧外患交集，太守大人还是每天受贿不误。结尾的打油诗不仅是实录，而且是莫大的讽刺。其因奢华贪贿而被降官，罪有应得。', 'indent', 1586127919, '5e6b2ffa2a6bfd0077ce55e2', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643935, '隆中对', NULL, 14, 66, 0, 6, '陈寿', NULL, 10399, '57ec58715bbb50005bd458f9', '晋', 'wen', '文', '', '', '亮躬耕陇亩，好为《梁父吟》。身长八尺，每自比于管仲、乐毅，时人莫之许也。惟博陵崔州平、颍川徐庶元直与亮友善，谓为信然。
时先主屯新野。徐庶见先主，先主器之，谓先主曰：“诸葛孔明者，卧龙也，将军岂愿见之乎？”先主曰：“君与俱来。”庶曰：“此人可就见，不可屈致也。将军宜枉驾顾之。”
由是先主遂诣亮，凡三往，乃见。因屏人曰：“汉室倾颓，奸臣窃命，主上蒙尘。孤不度德量力，欲信大义于天下，而智术浅短，遂用猖蹶，至于今日。然志犹未已，君谓计将安出？”
亮答曰：“自董卓已来，豪杰并起，跨州连郡者不可胜数。曹操比于袁绍，则名微而众寡，然操遂能克绍，以弱为强者，非惟天时，抑亦人谋也。今操已拥百万之众，挟天子而令诸侯，此诚不可与争锋。孙权据有江东，已历三世，国险而民附，贤能为之用，此可以为援而不可图也。荆州北据汉、沔，利尽南海，东连吴会，西通巴、蜀，此用武之国，而其主不能守，此殆天所以资将军，将军岂有意乎？益州险塞，沃野千里，天府之土，高祖因之以成帝业。刘璋暗弱，张鲁在北，民殷国富而不知存恤，智能之士思得明君。将军既帝室之胄，信义著于四海，总揽英雄，思贤如渴，若跨有荆、益，保其岩阻，西和诸戎，南抚夷越，外结好孙权，内修政理；天下有变，则命一上将将荆州之军以向宛、洛，将军身率益州之众出于秦川，百姓孰敢不箪食壶浆以迎将军者乎？诚如是，则霸业可成，汉室可兴矣。”
先主曰：“善！”于是与亮情好日密。
关羽、张飞等不悦，先主解之曰：“孤之有孔明，犹鱼之有水也。愿诸君勿复言。”羽、飞乃止。', '', '（1）隆中：地名，一说在现在湖北襄阳，一说在现在河南南阳。
（2）对：回答、应对。
（3）亮：即诸葛亮（181-234），字孔明，徐州琅琊阳都人。
（4）躬：亲自。
（5）陇亩：田地。
（6）好（hào）：喜爱。
（7）为：唱。
（8）《梁父（fǔ）吟》：又作《梁甫吟》，古歌曲名。传说诸葛亮曾经写过一首《梁父吟》歌词。
（9）管仲：名夷吾，春秋时齐桓公的国相，帮助桓公建立霸业。
（10）乐（yuè）毅：战国时燕昭王的名将，曾率领燕、赵、韩、魏、楚五国兵攻齐，连陷七十余城。
（11）莫之许：就是“莫许之”。莫，没有人。之，代词，指诸葛亮“自比于管仲、乐毅”。许，承认同意。
（12）惟：只有。
（13）友善：友好，关系好。
（14）信然：确实这样。
（15）先主：先，先帝，主，刘备。
（16）屯：驻扎。
（17）新野：现河南省新野县。
（18）器：器重、重视。
（19）谓：对，说，告诉。
（20）岂：大概，是否。
（21）之：代词，代诸葛亮。
（22）与俱来：与（之）俱来，和（他）一起来。俱。一起。
（23）就见：意思是到诸葛亮那里去拜访。就，接近、趋向。
（24）屈致：委屈（他），召（他上门）来。致，招致、引来。
（25）枉（wǎng）驾：屈尊。枉：委屈。
（26）驾：车马，借车马指刘备。
（27）顾：拜访。
（28）由是：因此。
（29）遂（suì）：于是，就。
（30）诣（yì）：去，到。这里是拜访的意思。
（31）凡：总共。
（32）乃见：才见到。
（33）因：于是，就。
（34）屏（bǐng）：这里是命人退避的意思。
（35）汉室倾颓：指汉朝统治崩溃、衰败。
（36）奸臣：指董卓、曹操等。
（37）窃命：盗用皇帝的政令。
（38）蒙尘：蒙受风尘，专指皇帝遭难出奔。东汉的京城本来在洛阳，董卓强迫汉献帝刘协迁都到陕西长安，曹操又强迫他迁都到河南许昌。
（39）孤：古代王侯的自称。这里是刘备自称。
（40）度（duó）德量力：衡量（自己的）德行（能否服人）估计（自己的）力量（能否胜人）。
（41）欲信：通“伸”，伸张。想。
（42）而：表转折。
（43）智术：智谋，才识。
（44）用：因此。
（45）猖蹶：这里是失败的意思。
（46）然：然而。
（47）犹：仍，还。
（48）已：停止，罢休。
（49）谓：认为。
（50）计：计策。
（51）安：疑问代词，怎么。
（52）出：产生。
（53）自：从。
（54）已来：已，通“以”，表时间。
（55）跨：占据。
（56）不可胜数：数也数不清。胜，尽。
（57）比于：同，相比。
（58）众寡：人少。意思是兵力薄弱。
（59）克：战胜。
（60）为：以为，变成。
（61）者：的原因。
（62）非惟：不仅。
（63）抑：而且。
（64）亦：也。
（65）谋：筹划。
（66）今：现在。
（67）挟（xié）：挟持，控制。
（68）令：号令。
（69）诸侯：这里指当时割据一方的军阀。
（70）此：这。
（71）诚：的确。
（72）争锋：争强，争胜。
（73）已历：已经经历。
（74）国险而民附：地势险要，民众归附。
（75）贤能为之用：为：被。
（76）可以为援：为：作为。援：外援。
（77）图：谋取。
（78）据：占据。
（79）利：物资。
（80）尽：全部取得。
（81）连：连接。
（82）通：到达。
（83）此用武之国：这是用兵之地，国：地方。意思是兵家必争之地。
（84）殆（dài）：大概。
（85）资：资助，给予。
（86）所以：用来。
（87）岂有意乎：可有意思吗？
（88）险塞（sài）：险峻的要塞。
（89）天府之土：指自然条件优越，物产丰饶，形势险固的地方。
（90）高祖：刘邦。
（91）因：依靠，凭。
（92）刘璋暗弱：刘璋（当时的益州牧）昏庸懦弱。
（93）殷：兴旺富裕。
（94）而：但是。
（95）存恤：爱抚、爱惜。恤：体恤、体谅。
（96）胄（zhòu）：后代。刘备是中山靖王刘胜（汉景帝刘启的儿子）的后代，所以称它“帝室之胄”。
（97）信义：信用道义。
（98）著：闻名。
（99）总揽：广泛地罗致。揽，这里有招致的意思。
（100）岩阻：险阻，指形势险要的地方。
（101）西和诸戎：向西和中国西部各族的和好。
（102）南抚夷越：向南安抚中国南部各族。
（103）内：对内。
（104）修：治理。
（105）政理：政治。
（106）将荆州之军：将：率领。
（107）宛、洛：河南南阳和洛阳这里泛指中原一带。
（108）身：亲自。
（109）川：平野。
（110）箪（dān）食壶浆：形容人民群众热情迎接和款待自己所爱戴的军队。
（111）诚如是：如果真像这样。
（112）日：一天天。
（113）悦：高兴。
（114）之：代词，代与诸葛亮关系变好这件事。
（115）之：主谓之间取消句子的独立性。
（116）犹：好像。
（117）愿：希望。', '诸葛亮亲自在田地中耕种，喜爱吟唱《梁父吟》，他身高八尺，常常把自己和管仲相比、乐毅，当时人们都不承认这件事。只有博陵的崔州平，颍川（河南禹州）的徐庶与诸葛亮关系甚好，说确实是这样。适逢先帝刘备驻扎在新野。徐庶拜见刘备，刘备很器重他，徐庶对刘备说：“诸葛孔明这个人，是人间卧伏着的龙啊，将军可愿意见他？”刘备说：“您和他一起来吧。”徐庶说：“这个人只能你去他那里拜访，不可以委屈他，将军你应该屈尊亲自去拜访他。”因此先帝就去隆中拜访诸葛亮，总共去了三次，才见到诸葛亮。于是刘备叫旁边的人退下，说：“汉室的统治崩溃，奸邪的臣子盗用政令，皇上蒙受风尘遭难出奔。我不能衡量自己的德行能否服人，估计自己的力量能否胜任，想要为天下人伸张大义，然而我才智与谋略短浅，就因此失败，弄到今天这个局面。但是我的志向到现在还没有罢休，您认为该采取怎样的办法呢？”诸葛亮回答道：“自董卓独掌大权以来，各地豪杰同时起兵，占据州、郡的人数不胜数。曹操与袁绍相比，声望少之又少，然而曹操最终之所以能打败袁绍，凭借弱小的力量战胜强大的原因，不仅依靠的是天时好，而且也是人的谋划得当。现在曹操已拥有百万大军，挟持皇帝来号令诸侯，这确实不能与他争强。孙权占据江东，已经历三世了，地势险要，民众归附，又任用了有才能的人，孙权这方面只可以把他作为外援，但是不可谋取他。荆州北靠汉水、沔水，一直到南海的物资都能得到，东面和吴郡、会稽郡相连，西边和巴郡相连、蜀郡这是大家都要争夺的地方，但是它的主人却没有能力守住它，这大概是天拿它用来资助将军的，将军你可有占领它的意思呢？益州地势险要，有广阔肥沃的土地，自然条件优越，高祖因之以成帝业。刘璋昏庸懦弱，张鲁在北面占据汉中，那里人民殷实富裕，物产丰富，刘璋却不知道爱惜，有才能的人都渴望得到贤明的君主。将军既是皇室的后代，而且声望很高，闻名天下，广泛地罗致英雄，思慕贤才，如饥似渴，如果能占据荆州、益州，守住险要的地方，和西边的各个民族和好，又安抚南边的少数民族对外联合孙权，对内革新政治；一旦天下形势发生了变化，就派一员上将率领荆州的军队直指南阳、洛阳一带，将军您亲自率领益州的军队从秦川出击，老百姓谁敢不用竹篮盛着饭食，用壶装着酒来欢迎将军您呢？如果真能这样做，那么称霸的事业就可以成功，汉室天下就可以复兴了。”刘备说：“好！”从此与诸葛亮的关系一天天亲密起来。关羽、张飞等人不高兴了，刘备劝解他们说：“我有了孔明，就像鱼得到水一样。希望你们不要再说什么了。”关羽、张飞于是不再说什么了。', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1dd2e6a6b501f968562", "shortContent": "《隆中对》选自《三国志·诸葛亮传》的开头部分，标题为后人所加。\n文章一开始简单地叙述了诸葛亮隐居隆中（在今湖北襄阳西），继而点出他“每自比于管仲、乐毅，时人莫之许也”。好的诗文都有“眼”，这一句就是本文的“眼”。管仲、乐毅是春秋、战国时有名的将相。管仲辅齐桓公成就霸业；乐毅为战国时燕昭王报齐仇，几至灭掉齐国。诸葛亮自比于管仲、乐毅，是在他“躬耕陇亩”之时。一介村夫竟如此自大，当然不被时人的舆论所赞...", "authors": ["叶晨晖"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42ad5e272d4b2255ce41", "shortContent": "《定三分隆中决策》见于《三国演义》第三十八回。\n在《三国演义》塑造的众多人物形象中，诸葛亮无疑是塑造得最为成功、影响最为深远的一个。他是全书的真正主角，是维系全书的灵魂。罗贯中满怀挚爱之情，倾注全部心血，调动各种艺术手段，将他塑造为一个光彩照人的、不朽的艺术典型，成为古代优秀知识分子的崇高典范，中华民族忠贞品格和无比智慧的化身。而在有关诸葛亮的诸多情节中，“三顾茅庐”又是最脍炙人口、最动人心弦的一...", "authors": ["沈伯俊"], "pressName": "上海辞书出版社"}]', '', 'indent', 1585074162, '5e79df6891db2800779ffd9a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643936, '惠子相梁', NULL, 2, 16, 0, 4, '庄子', NULL, 10064, '57b90297165abd0054bfdce7', '周', 'wen', '文', '', '', '惠子相梁，庄子往见之。或谓惠子曰：“庄子来，欲代子相。”于是惠子恐，搜于国中三日三夜。庄子往见之，曰：“南方有鸟，其名为鹓鶵，子知之乎？夫鹓鶵发于南海，而飞于北海，非梧桐不止，非练实不食，非醴泉不饮。于是鸱得腐鼠，鹓鶵过之，仰而视之曰：‘吓！’今子欲以子之梁国而吓我邪？”', '', '（1）惠子：即惠施，战国时宋国人，哲学家，庄子好友。
（2）相梁：在梁国当宰相。梁：魏国的都城，战国时期魏国迁都大梁。（今河南开封）后的别称。根据史实魏国都城叫大梁，所以魏也叫梁。相：辅助君主的人，相当于后代的宰相。这里用作动词，做宰相的意思。
（3）或：有人。
（4）于是：与现代意思相同，可直接翻译为“于是”。
（5）恐：害怕。
（6）国：国都。
（7）往：前往。
（8）鹓鶵（yuānchú）：鶵，古同“雏”。鹓鶵为古代传说中像凤凰一类的鸟，习性高洁。
（9）止：栖息。
（10）练实：竹实，即竹子所结的子，因为色白如洁白的绢，故称。
（11）醴（lǐ）泉：甘泉，甜美的泉水。醴：甘甜。
（12）于是：在这时。
（13）鸱（chī）：猫头鹰。
（14）吓（hè）：模仿鹞鹰发怒的声音。下文的“吓”用作动词，恐吓。
（15）夫（fú）：句首语气词，可以不译，也可以译作那那鹓鶵。
（16）三：虚指，多次。
（17）发于南海：于，从。
（18）飞于北海：于，到。
（19）子：你，指代惠子。', '惠施在梁国做国相，庄子前去见他，有人告诉惠施说：“庄子（到梁国）来，是想取代你做宰相。”于是惠施非常害怕，在国都搜捕三天三夜。庄子前去见他，说：“南方有一种鸟，它的名字叫鹓鶵，你知道它吗？那鹓鶵从南海起飞，飞到北海去，不是梧桐树不栖息，不是竹子的果实不吃，不是甜美的泉水不喝。在此时猫头鹰拾到（一只）腐臭的老鼠，鹓鶵从它面前飞过，（猫头鹰）仰头看着，发出：‘喝！’的怒斥声。现在你也想用你的梁国来吓我吗？”', NULL, '', 'indent', 1585074664, '5e79e1625620710075218018', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643937, '范进中举', NULL, 0, 190, 0, 12, '吴敬梓', NULL, 20144, '5858ee2a8e450a006cba79ea', '清', 'wen', '文', '', '', '范进进学回家，母亲、妻子俱各欢喜。正待烧锅做饭，只见他丈人胡屠户，手里拿着一副大肠和一瓶酒，走了进来。范进向他作揖，坐下。胡屠户道：“我自倒运，把个女儿嫁与你这现世宝，历年以来，不知累了我多少。如今不知因我积了甚么德，带挈你中了个相公，我所以带个酒来贺你。”范进唯唯连声，叫浑家把肠子煮了，烫起酒来，在茅草棚下坐着。母亲自和媳妇在厨下造饭。胡屠户又吩咐女婿道：“你如今既中了相公，凡事要立起个体统来。比如我这行事里，都是些正经有脸面的人，又是你的长亲，你怎敢在我们跟前装大？若是家门口这些做田的，扒粪的，不过是平头百姓，你若同他拱手作揖，平起平坐，这就是坏了学校规矩，连我脸上都无光了。你是个烂忠厚没用的人，所以这些话我不得不教导你，免得惹人笑话。”范进道：“岳父见教的是。”胡屠户又道：“亲家母也来这里坐着吃饭。老人家每日小菜饭，想也难过。我女孩儿也吃些。自从进了你家门，这十几年，不知猪油可曾吃过两三回哩！可怜！可怜！”说罢，婆媳两个都来坐着吃了饭。吃到日西时分，胡屠户吃的醺醺的。这里母子两个，千恩万谢。屠户横披了衣服，腆着肚子去了。
次日，范进少不得拜拜乡邻。魏好古又约了一班同案的朋友，彼此来往。因是乡试年，做了几个文会。不觉到了六月尽间，这些同案的人约范进去乡试。范进因没有盘费，走去同丈人商议，被胡屠户一口啐在脸上，骂了一个狗血喷头，道：“不要失了你的时了！你自己只觉得中了一个相公，就‘癞蛤蟆想吃起天鹅肉’来！我听见人说，就是中相公时，也不是你的文章，还是宗师看见你老，不过意，舍与你的。如今痴心就想中起老爷来！这些中老爷的都是天上的‘文曲星’！你不看见城里张府上那些老爷，都有万贯家私，一个个方面大耳？像你这尖嘴猴腮，也该撒抛尿自己照照！不三不四，就想天鹅屁吃！趁早收了这心，明年在我们行事里替你寻一个馆，每年寻几两银子，养活你那老不死的老娘和你老婆是正经！你问我借盘缠，我一天杀一个猪还赚不得钱把银子，都把与你去丢在水里，叫我一家老小嗑西北风！”一顿夹七夹八，骂的范进摸门不着。辞了丈人回来，自心里想：“宗师说我火候已到，自古无场外的举人，如不进去考他一考，如何甘心？”因向几个同案商议，瞒着丈人，到城里乡试。出了场，即便回家。家里已是饿了两三天。被胡屠户知道，又骂了一顿。
到出榜那日，家里没有早饭的米，母亲吩咐范进道：“我有一只生蛋的母鸡，你快拿集上去卖了，买几升米来煮餐粥吃，我已是饿的两眼都看不见了。”范进慌忙抱了鸡，走出门去。才去不到两个时候，只听得一片声的锣响，三匹马闯将来。那三个人下了马，把马拴在茅草棚上，一片声叫道：“快请范老爷出来，恭喜高中了！”母亲不知是甚事，吓得躲在屋里；听见中了，方敢伸出头来，说道：“诸位请坐，小儿方才出去了。”那些报录人道：“原来是老太太。”大家簇拥着要喜钱。正在吵闹，又是几匹马，二报、三报到了，挤了一屋的人，茅草棚地下都坐满了。邻居都来了，挤着看。老太太没奈何，只得央及一个邻居去寻他儿子。
那邻居飞奔到集上，一地里寻不见；直寻到集东头，见范进抱着鸡，手里插个草标，一步一踱的，东张西望，在那里寻人买。邻居道：“范相公，快些回去！你恭喜中了举人，报喜人挤了一屋里。”范进当是哄他，只装不听见，低着头往前走。邻居见他不理，走上来，就要夺他手里的鸡。范进道：“你夺我的鸡怎的？你又不买。”邻居道：“你中了举了，叫你家去打发报子哩。”范进道：“高邻，你晓得我今日没有米，要卖这鸡去救命，为甚么拿这话来混我？我又不同你顽，你自回去罢，莫误了我卖鸡。”邻居见他不信，劈手把鸡夺了，掼在地下，一把拉了回来。报录人见了道：“好了，新贵人回来了。”正要拥着他说话，范进三两步走进屋里来，见中间报帖已经升挂起来，上写道：“捷报贵府老爷范讳高中广东乡试第七名亚元。京报连登黄甲。”
范进不看便罢，看了一遍，又念一遍，自己把两手拍了一下，笑了一声，道：“噫！好了！我中了！”说着，往后一跤跌倒，牙关咬紧，不省人事。老太太慌了，慌将几口开水灌了过来。他爬将起来，又拍着手大笑道：“噫！好！我中了！”笑着，不由分说，就往门外飞跑，把报录人和邻居都吓了一跳。走出大门不多路，一脚踹在塘里，挣起来，头发都跌散了，两手黄泥，淋淋漓漓一身的水。众人拉他不住，拍着笑着，一直走到集上去了。众人大眼望小眼，一齐道：“原来新贵人欢喜疯了。”老太太哭道：“怎生这样苦命的事！中了一个甚么举人，就得了这个拙病！这一疯了，几时才得好？”娘子胡氏道：“早上好好出去，怎的就得了这样的病！却是如何是好？”众邻居劝道：“老太太不要心慌。我们而今且派两个人跟定了范老爷。这里众人家里拿些鸡蛋酒米，且管待了报子上的老爹们，再为商酌。”
当下众邻居有拿鸡蛋来的，有拿白酒来的，也有背了斗米来的，也有捉两只鸡来的。娘子哭哭啼啼，在厨下收拾齐了，拿在草棚下。邻居又搬些桌凳，请报录的坐着吃酒，商议他这疯了，如何是好。报录的内中有一个人道：“在下倒有一个主意，不知可以行得行不得？”众人问：“如何主意？”那人道：“范老爷平日可有最怕的人？他只因欢喜狠了，痰涌上来，迷了心窍。如今只消他怕的这个人来打他一个嘴巴，说：‘这报录的话都是哄你，你并不曾中。’他吃这一吓，把痰吐了出来，就明白了。”众邻都拍手道：“这个主意好得紧，妙得紧！范老爷怕的，莫过于肉案子上胡老爹。好了！快寻胡老爹来。他想是还不知道，在集上卖肉哩。”又一个人道：“在集上卖肉，他倒好知道了；他从五更鼓就往东头集上迎猪，还不曾回来。快些迎着去寻他。”
一个人飞奔去迎，走到半路，遇着胡屠户来，后面跟着一个烧汤的二汉，提着七八斤肉，四五千钱，正来贺喜。进门见了老太太，老太太大哭着告诉了一番。胡屠户诧异道：“难道这等没福？”外边人一片声请胡老爹说话。胡屠户把肉和钱交与女儿，走了出来。众人如此这般，同他商议。胡屠户作难道：“虽然是我女婿，如今却做了老爷，就是天上的星宿。天上的星宿是打不得的！我听得斋公们说：打了天上的星宿，阎王就要拿去打一百铁棍，发在十八层地狱，永不得翻身。我却是不敢做这样的事！”邻居内一个尖酸人说道：“罢么！胡老爹，你每日杀猪的营生，白刀子进去，红刀子出来，阎王也不知叫判官在簿子上记了你几千条铁棍；就是添上这一百棍，也打甚么要紧？只恐把铁棍子打完了，也算不到这笔帐上来。或者你救好了女婿的病，阎王叙功，从地狱里把你提上第十七层来，也不可知。”报录的人道：“不要只管讲笑话。胡老爹，这个事须是这般，你没奈何，权变一权变。”屠户被众人局不过，只得连斟两碗酒喝了，壮一壮胆，把方才这些小心收起，将平日的凶恶样子拿出来，卷一卷那油晃晃的衣袖，走上集去。众邻居五六个都跟着走。老太太赶出来叫道：“亲家，你只可吓他一吓，却不要把他打伤了！”众邻居道：“这自然，何消吩咐。”说着，一直去了。
来到集上，见范进正在一个庙门口站着，散着头发，满脸污泥，鞋都跑掉了一只，兀自拍着掌，口里叫道：“中了！中了！”胡屠户凶神似的走到跟前，说道：“该死的畜生！你中了甚么？”一个嘴巴打将去。众人和邻居见这模样，忍不住的笑。不想胡屠户虽然大着胆子打了一下，心里到底还是怕的，那手早颤起来，不敢打到第二下。范进因这一个嘴巴，却也打晕了，昏倒于地。众邻居一齐上前，替他抹胸口，捶背心，舞了半日，渐渐喘息过来，眼睛明亮，不疯了。众人扶起，借庙门口一个外科郎中的板凳上坐着。胡屠户站在一边，不觉那只手隐隐的疼将起来；自己看时，把个巴掌仰着，再也弯不过来。自己心里懊恼道：“果然天上‘文曲星’是打不得的，而今菩萨计较起来了。”想一想，更疼的狠了，连忙问郎中讨了个膏药贴着。
范进看了众人，说道：“我怎么坐在这里？”又道：“我这半日，昏昏沉沉，如在梦里一般。”众邻居道：“老爷，恭喜高中了。适才欢喜的有些引动了痰，方才吐出几口痰来，好了。快请回家去打发报录人。”范进说道：“是了。我也记得是中的第七名。”范进一面自绾了头发，一面问郎中借了一盆水洗洗脸。一个邻居早把那一只鞋寻了来，替他穿上。见丈人在跟前，恐怕又要来骂。胡屠户上前道：“贤婿老爷，方才不是我敢大胆，是你老太太的主意，央我来劝你的。”邻居内一个人道：“胡老爹方才这个嘴巴打的亲切，少顷范老爷洗脸，还要洗下半盆猪油来！”又一个道：“老爹，你这手明日杀不得猪了。”胡屠户道：“我那里还杀猪！有我这贤婿，还怕后半世靠不着也怎的？我每常说，我的这个贤婿，才学又高，品貌又好，就是城里头那张府、周府这些老爷，也没有我女婿这样一个体面的相貌。你们不知道，得罪你们说，我小老这一双眼睛，却是认得人的。想着先年，我小女在家里长到三十多岁，多少有钱的富户要和我结亲，我自己觉得女儿像有些福气的，毕竟要嫁与个老爷，今日果然不错！”说罢，哈哈大笑。众人都笑起来。看着范进洗了脸，郎中又拿茶来吃了，一同回家。范举人先走，屠户和邻居跟在后面。屠户见女婿衣裳后襟滚皱了许多，一路低着头替他扯了几十回。
到了家门，屠户高声叫道：“老爷回府了！”老太太迎着出来，见儿子不疯，喜从天降。众人问报录的，已是家里把屠户送来的几千钱打发他们去了。范进拜了母亲，也拜谢丈人。胡屠户再三不安道：“些须几个钱，不够你赏人。”范进又谢了邻居。正待坐下，早看见一个体面的管家，手里拿着一个大红全帖，飞跑了进来：“张老爷来拜新中的范老爷。”说毕，轿子已是到了门口。胡屠户忙躲进女儿房里，不敢出来。邻居各自散了。
范进迎了出去，只见那张乡绅下了轿进来，头戴纱帽，身穿葵花色圆领，金带、皂靴。他是举人出身，做过一任知县的，别号静斋，同范进让了进来，到堂屋内平磕了头，分宾主坐下。张乡绅先攀谈道：“世先生同在桑梓，一向有失亲近。”范进道：“晚生久仰老先生，只是无缘，不曾拜会。”张乡绅道：“适才看见题名录，贵房师高要县汤公，就是先祖的门生，我和你是亲切的世弟兄。”范进道：“晚生侥幸，实是有愧。却幸得出老先生门下，可为欣喜。”张乡绅四面将眼睛望了一望，说道：“世先生果是清贫。”随在跟的家人手里拿过一封银子来，说道：“弟却也无以为敬，谨具贺仪五十两，世先生权且收着。这华居其实住不得，将来当事拜往，俱不甚便。弟有空房一所，就在东门大街上，三进三间，虽不轩敞，也还干净，就送与世先生；搬到那里去住，早晚也好请教些。”范进再三推辞，张乡绅急了，道：“你我年谊世好，就如至亲骨肉一般；若要如此，就是见外了。”范进方才把银子收下，作揖谢了。又说了一会，打躬作别。胡屠户直等他上了轿，才敢走出堂屋来。
范进即将这银子交与浑家打开看，一封一封雪白的细丝锭子，即便包了两锭，叫胡屠户进来，递与他道：“方才费老爹的心，拿了五千钱来。这六两多银子，老爹拿了去。”屠户把银子攥在手里紧紧的，把拳头伸过来，道：“这个，你且收着。我原是贺你的，怎好又拿了回去？”范进道：“眼见得我这里还有这几两银子，若用完了，再来问老爹讨来用。”屠户连忙把拳头缩了回去，往腰里揣，口里说道：“也罢，你而今相与了这个张老爷，何愁没有银子用？他家里的银子，说起来比皇帝家还多些哩！他家就是我卖肉的主顾，一年就是无事，肉也要用四五千斤，银子何足为奇！”又转回头来望着女儿，说道：“我早上拿了钱来，你那该死行瘟的兄弟还不肯，我说：‘姑老爷今非昔比，少不得有人把银子送上门来给他用，只怕姑老爷还不希罕。’今日果不其然！如今拿了银子家去，骂这死砍头短命的奴才！”说了一会，千恩万谢，低着头，笑迷迷的去了。', '', '（1）进学：进了县学。
（2）现世宝：丢脸的家伙。现世，出丑，丢脸。
（3）带挈.：提携。这里的意思是“让你沾我的光，得到好运气。”
（4）相（xiàng）公：古时对秀才的称呼。
（5）唯唯连声：连连答应。唯唯，答应的声音。
（6）浑家：妻子。
（7）体统：规矩。
（8）行（háng）事：行业。
（9）脸面：面子。指“一定的社会地位”。
（10）长（zhǎng）亲：长辈。
（11）平头百姓：普通百姓。
（12）见教：指教（我）。“见”字用在动词前面表示对“我”怎么样。
（13）腆（tiǎn）着：挺着。
（14）乡试年：科举制度，每三年举行一次全省的考试，叫“乡试”，由秀才去应试。轮到乡试这一年就叫乡试年。
（15）文会：旧时读书人为了准备应试，在一起写文章、互相观摩的集会。
（16）同案：同考取秀才叫做同案。
（17）盘费：旅费。
（18）啐（cuì）：唾。
（19）狗血喷头：现形容骂得很厉害。
（20）宗师：对一省总管教育的学官的称呼。
（21）舍与：施舍给，赏给。
（22）老爷：这里是对举人的称呼。
（23）万贯家私：大量的家财。万贯：上万贯铜钱。贯：古时穿钱的绳子，既钱穿，也指一串钱，一千文为一串，称一贯。形容家产很多，非常富有。
（24）尖嘴猴腮：形容人相貌丑陋粗俗。
（25）抛：通常写作“泡”。
（26）馆：这里指教书的地方。
（27）把与：拿给。
（28）摸门不着：摸不着门路，意思是不知从何说起。
（29）火候：这里指写文章的功夫。
（30）央：恳求。
（31）一地里：一路上，到处。
（32）草标：在集市上卖东西，把一根草插在出卖的物品上或拿在手里，作为标志，这草就叫做“草标”。
（33）高邻：对邻居的尊称。
（34）顽：同“玩”。
（35）劈手：形容手的动作异常迅速。
（36）拙病：倒霉的病。
（37）商酌：反复仔细地商量。
（38）二汉：佣工，伙计。
（39）星宿：我国古代指星座，共分二十八星宿。
（40）尖酸：说话尖刻。
（41）局不过：碍于情面，虽然自己不愿意，也只好屈从。
（42）何消：哪用得着。
（43）兀自：只管。
（44）先年：先前。
（45）些须：很少。
（46）桑梓：家乡。
（47）华居：对对方住宅的客气说法。
（48）轩敞：宽敞。
（49）细丝锭（dìng）子：铸有细条纹的银块。
（50）相与：结交。
（51）该死行瘟的：该生瘟病死的。
（52）今非昔比：多指形势、自然面貌等发生了巨大的变化。
（53）果不其然：多用来强调不出所料。', '范进进学回家，母亲和妻子都很高兴。正待烧锅做饭，只见他丈人胡屠户，手里拿着一副大肠和一瓶酒，走了进来。范进向他作揖，坐下来。胡屠夫道：“我从倒运，把一个女儿嫁给你这个现世宝，多年以来，不知道累了我多少。如果现在不知道因为我积了什么德，带着你问了一个你，我能带个酒来祝贺你。“范进唯唯诺诺连声，叫浑家把肠儿子煮了，烫起酒来，在茅草棚下坐着。母亲亲自和媳妇在厨房做饭。胡屠夫又吩咐女儿女婿道：“如果你现在已经中了你，凡事要确立起一个体例来。比如我这做的事里，都是些正经有脸脸的人，又是你的长亲，你怎么敢在我们跟前面装大？如果这家门口这些做打猎的，扒粪的，不过是平头百姓，如果你同他拱手作揖，平起平坐，这就是坏了学校规矩，连我脸上都没有光了。你是个烂忠厚没用的人，之所以这些话我不能不教导你，免得惹人笑话。“范进道：“贺拔岳父被教导的是。“胡屠夫又道：“亲家母也来这边坐着吃饭。老人家每天小菜吃饭，想必也很难超过。我的女儿孩儿时吃些。自从进了你家的门，这十多少年，不知道猪油可曾吃过两三回哩！可怜！可怜！”说完，婆婆媳妇两个都来坐着吃了饭。吃到日西时分，胡屠夫吃的醉醉的。这里母子两个，千恩万谢。屠夫横披了衣服，腆着肚子子去了。
第二天，范进少不得授任乡里邻居。魏好奇又约了一班同考的朋友，彼此来往。因此乡试年，做了几个文章会。不觉到了六月全部之间，这些同桌的人约范进离乡试。范进并没有盘费用，跑去同丈夫商量，被胡屠夫一口尝在脸上，骂了一个狗血喷头，道：“不要失去了你的时候了！你自己也觉得到中了一个你，在‘只癞蛤蟆想吃天鹅肉起’来！我听见人说，在这中间你时，也就是你的文章，回到这宗老师看到你老，不过意，除了与你的。如果痴心去想中起老大爷来！这些中老爷的都是天上的‘文曲星’！你不看见城市里张府上那些老爷，都有万贯家里，一个个方大耳朵？像你这尖嘴猴~，也该撒抛尿自己照照！不三不四，就想天鹅屁吃！趁早收了这心，第二年在我们做的事情里替你找一个宾馆，每年不久几乎两银子，生活你那老不死的老娘和你老婆是经典！你问我借盘缠，我一天杀死一个猪还赚不到钱把银子，都把和你去丢在水里，叫我一家老小嗑卦西北风！”一顿在七夹八，骂的范进摸不着门。告别了老人回来，从内心里想：“宗老师说我火候已到，自古以来没有场内外的推荐人，如果不进去考一考其他，怎么甘心？”于是向几个同桌商量，瞒着丈夫，到城里乡试。出了场，马上回家。家里已经是饿了两三天。被胡屠夫知道道，又骂了一顿。
到发榜那天，家里没有早饭米，母亲吩咐范进道：“我有一只生蛋的母鸡，你快拿集上去卖了，买几升米来煮稀饭吃，我已是饥饿的两只眼睛都看不见了。“范进慌忙抱了鸡，走出门去。才离开不到两个时间，只听到一片声的响锣来聚集，三匹马闯过将来。那三个人下了马，把马拴在茅草棚上，一片声叫道：“快请范老爷出来，恭喜高中了！”母亲不知道是甚事，吓得躲在屋子里；听看中了，才敢伸出头来，解释道：“各位请坐下，小孩才出去了。”那些报录人之道：“原来是老太太。”大家簇拥着要喜欢钱。正是在吵闹，又是几匹马，二向、三向到了，挤了一屋子的人，茅草棚地上都坐满了。邻居都来了，挤着看。老太太没办法，只得到中央和一个邻居去寻他儿子。
那邻居飞奔到集上，一地里寻不见；直寻到集束头，见范进抱着鸡，手里插个草标，一步一个徘徊的，东张西望，在那里找人买。邻居道：“范你，快些回去！你恭喜中了举人，对喜欢人挤了一屋子里。“范进道是哄他，只装听不见，低着头往前走。邻居看到他不理，走上前来，就要剥夺他手里的鸡。范进道：“你夺我的鸡怎么的？你又不买。”邻居道：“你中了举了，叫你家去打发报答你呢。“范进道：“高邻，你知道我今天没有米，要卖这个鸡去挽救生命，为甚么拿这些话来混淆我？我又不能同你顽固，你自己回去罢，别误会了我卖鸡。”邻居看见他不相信，劈开手把鸡剥夺了，掼在地下，一把拉了回来。报录人见了道：“好了，新贵族回来了。”正是要拥抱着他说话，范进两三步逃进屋里来，看到中间回复帖已经升挂起来，上写道：“敏捷报贵府老爷范名进高中广东乡试第七名亚元。京报连登黄甲。”
范进不看就停止，看了一遍，再念一遍，自己把两只手拍了一下，笑了一声，道：“唉！好了！我中了！”有着，往后一交跌倒，牙关咬紧，不省人事。我太太紧张了，慌忙将几口打开水灌了过来。他爬将起来，又拍着拍手放声笑道：“唉！好！我中了！”笑着，不由分说，就往门外跑飞，把报录人和邻居都吓了一跳。走出大门不多路，一脚踹在水塘里，挣起来，头发都掉散了，两手黄泥，雨水淋漓漓一身的水。很多人拉不住他，拍着笑着，一个一直延伸到集上去了。大家大眼看小眼，一个齐道：“原来新贵族高兴疯了。”老太太哭着道：“怎么能这样辛苦命的事！中了一个甚么推荐人，就得到了这个拙病！这一疯了，什么时候才能得好？“娘子胡氏道：“早上好喜欢出去，怎的就得了这样的疾病！那是为什么是好？“众邻居劝道：“老太太不要心慌。我们现在，并且派两个人跟定了范老爷。这里大家家里拿些鸡蛋酒米，而且款待了报子上的老爹”。，再次为商饮。”
当下众邻居有拿鸡蛋来的，有拿白酒来的，也有背了一斗米来的，也有抓两只鸡来的。娘子哭哭啼啼，在厨房收拾整齐了，拿在草棚下。邻居又搬些桌子凳子，请报录的坐着喝酒，商议他的这疯了，这怎么是好。报告记录的内心中有一个做人的道理：“在下倒是有一个主意，不知道可以通过实现不能？“很多人问：“像什么主意？”那人之道：“范老爷平日可以有最可怕的人？他只因欢喜残忍了，痰涌上来，迷了心孔。现在只需要他害怕的这个人来打他一个嘴巴，说：“这个报告记录的话都是骗你，你都不曾中。’他吃这一吓，把痰吐了出来，就明白了。”很多邻居都拍手道：“这个主意好得紧，妙得紧！范老爷怕的，没有比肉桌子子上胡老爹”。好了！快找胡老爹”来。他想是还不知道道，在集上卖肉哩。”又一个人道：“在集上买肉，他倒喜欢知道了；他从五更鼓就往头集上迎接猪，还不曾回来。快些去迎接着去寻找她。”
一个人飞奔去迎接，走到一半路，遇着胡屠夫来，后面踩着一个烧开水的两汉，提着七八斤肉，四五千钱，正来贺喜。进门见到了老太太，老太太大哭着诉说了一番。胡屠夫诧异道：“难道这等人没福？“外边人一片声请胡老爹”说话。胡屠夫把肉和钱交给女儿，跑了出来。大家如此这般，同他商量。胡屠夫发难之道：“虽然这是我女婿，如今却做了老爷，在这天上的星星。天上的星宿是打不到的！我听到斋公说：打了天上的星星，阎王就要拿去打一百铁耙，发生在十八层地狱，永远不能翻身。我倒是不敢做这样的事！”邻居内一个尖酸人解释道：“算了吧！胡老爹”，你每天杀了猪的营养生长，白刀子进去，红刀子出来，阎王也不知道叫判官在簿上记了你儿子有几千条铁耙；就算是添上这一百棍，了打甚么要紧？只恐怕把铁棍子打完整了，也算不到那笔帐上吧。或者是你救好了女婿的病，阎王叙功绩，从地狱里把你提上第十七层来，也不知道。”报告记录的人的思想：“不要只顾讲笑话。胡老爹”，这个故事应该是这样，你没办法，改变一个权变权。“屠夫被众人局不超过，只得连喝了两碗酒斟，壮一壮胆，把才能这些小心收起来，将平时的凶恶模样拿出来，卷一卷那油晃晃的衣袖，走上集去。众邻居五六个都跟着跑。老太太赶出来叫道：“爱家，你只可以吓他一吓，但却要把他打伤了！“众邻居道：“这自然，如何消除吩咐。”有着，一个直接去了。
来到集上，见范进正在一个庙门口站着，散着头发，满脸污泥，刨掉了一只鞋子都，兀自拍着手掌，嘴巴里叫道：“中了！中了！“胡屠夫凶神似的走到跟以前，解释道：“该死的畜生！你中了甚么？”一个嘴巴打将去。很多人和邻居看见这模样，忍不住的微笑。没想到胡屠夫虽然大着胆子打了下一次，心里到底还是害怕的，那手早就抖起来，不敢打到第二下。范进就这一个嘴巴，但因为打晕了，昏倒在地上。众邻居一齐上前，替他抹胸口，打背心，舞了半天，渐渐地喘息过来，眼睛明亮，不疯了。许多人扶起，借庙门口一个外科郎中的板凳上坐着。胡屠夫站在一边，不觉得那只手隐隐的疼痛将起来；自己看时，把一个巴掌仰着，再也拉不过来。自己心里懊恼道：“果然是天上‘文曲星’是打不到的，而现在菩萨计较起来了。“想一想，更头疼的残忍了，连忙询问郎中讨了个膏药贴着。
范进看了很多人，解释道：“我怎么坐在这里？”又道：“我这半天，昏昏沉沉，像在梦里一样。“众邻居道：“老爷，恭喜高中了。刚才欢喜的有些带动了痰，才吐出几口痰来，好了。快请回家去打发报录人。“范进解释道：“对了。我也记得是其中的第七名。“范进一面从绾了头发，一个当面询问郎中借了一盆水洗洗脸。一个邻居早把那一只鞋寻了过来，替他穿上。看到老人在跟前面，害怕又要来骂。胡屠夫上前道：“贤婿老爷，才不这样我敢大胆，是你老太太的意思，中央我来劝你的。”邻居内一个做人的道理：“胡老爹”才有这个嘴巴打的亲切，一会儿范老爷洗脸，还要洗下半盆猪油来！又一个道”：“老爹”，你这手第二天杀死不得到猪了。“胡屠夫道：“我哪里还杀了猪！有我的贤婿，还怕以后半世代靠不着了怎的？我常常说，我的这个贤婿，才学又高，品表面又好，在这城里头那张府、周府这些老爷，也没有我女婿这样一个体面的相貌。你们不知道道，得罪你们说，我小老这一双眼睛，这是认识人的。想象着当年，我小女儿在家里长到30多岁，多少有钱的富裕户要和我团结一致，我自己感觉到女儿像有些福气的，毕竟要嫁给一个老爷，今天果然没有错！”说完，哈哈大笑。众人都笑起来。看著范进洗了脸，郎中又拿茶来吃了，一同回家。范举人先逃跑，屠夫和邻居跟在后面。屠夫看见女儿女婿衣裳后衣襟滚滚皱了许多，一路低着头替他扯了几十回。
到了家门口，屠夫高声叫道：“老爷回府了！”老太太迎接着出来，看到儿子不疯，很高兴从天降下。很多人问报告记录的，已经是家里把屠夫送来的几千钱打发他走了。。范进拜了妈妈，也感谢老人。胡屠夫再三不安道：“你需要多少个钱，不够你赏人。“范进又谢了邻居。正待坐下来，早上看到一个体面的管家，手里拿着一个大红色全帖，飞跑了进来：“张老爷来拜访新中的范老爷。”说完后，轿子已经是到了门口。胡屠夫急忙躲藏进女儿房里，不敢出来。邻居各自散了。
范进迎了出去，只见那张乡绅下了轿进来，头戴纱帽，身穿葵花色圆领，金带，黑色靴。他是举人出身，做过一任知县。，别为静斋，同范进让给了进来，到堂屋内平磕了头，分宾主坐下下。张乡绅先攀谈论：“世界先生一起在家乡，一个向有失去亲近的人。“范进道：“出生时间依赖老先生，只是无缘，不曾任会。”张乡绅道：“刚才看见题名录，贵房老师高要县汤公，就算是祖先的学生，我和你是亲切的世代兄弟。“范进道：“出生侥幸，实在是有愧。但幸亏逃出老先门下，可以为欣喜。”张乡绅四面将眼睛望了一望，解释道：“世界先生果然是清贫。“随着在跟的家人手里拿过一把银子来，解释道：“我也不认为我，认真准备贺礼五十两，代先生暂时收着。这些花在实际住不得，将来当事任去，都不很方便。我有一所房子，就在东门大街上，三升三间，虽然不宽敞，的还干净，在送与世先生；搬运到那里去住，早晚的喜欢请教些。“范进再三推辞，张乡绅急了，道：“你我年友谊世代友好，就如至亲骨肉一样；如果要这样，就是看外了。“范进才能把银子被捕，作揖谢了。又讲了一个聚会，打自己告别。胡屠夫直等他上了轿，才敢走出堂屋来。
范进就将这银子交给浑家打开看，一封一封雪白色的细丝锭子，就包了两锭，叫胡屠夫进来，递与其他方法：“才花费老爹”的心，拿了五千钱来。这六个两个多银子，老爹”拿了去。“屠夫把银子攥在手里紧紧的，把卷曲的头发舒缓过来，道：“这个，你先收着。我原是祝贺你的，怎么能又拿了回去？“范进道：“眼到我这里还有这几乎两银子，如果使用完整了，再来问老爹”讨来使用。“屠夫连忙把拳头缩了回去，去腰里估计，嘴里说：“也罢，你现在却互相了这个张老爷，何愁没有银子用？他家里的银子，说起来比皇帝家还多哩。！他家就是我卖肉的主顾，一年就是没有事，肉也要用四五千斤，银子何足为奇！”又转回头来望着女儿，解释道：“我早就上拿了钱来，你那该死行瘟的兄弟还不肯，我说：‘姑老爷今非昔比，少不得有人把银子送上门来给他用，只怕姑老爷还不稀罕。’今天果然不这样！如今拿了银子你家去，骂这死砍头短命的奴才！”说了一次，千恩万谢，低着头，笑迷迷的离开。', '[{"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42c40f8fda556506f16d", "shortContent": "本文采自《儒林外史》第三回《周学道校士拔真才胡屠户行凶闹捷报》，通常称《范进中举》。\n《儒林外史》是一部讽刺小说。作者深刻地揭示了科举制度的腐败、封建礼教与程朱理学的虚伪。在那个时代，道德价值贬值，人与人正常的伦理关系因为人们追逐名利而遭到破坏。特别是知识阶层智能低下，随意糟蹋自己的人格。既不讲究道德自守，又丧失了吃饱肚子的能力，在传统和世俗生活所形成的矛盾中漂浮。而传统的价值或信念，似乎也丧失了...", "authors": ["鲁德才"], "pressName": "上海辞书出版社"}, {"bookId": "60fd4b8d34bfda01e0eab1fe", "bookTitle": "明清小说鉴赏辞典", "articleId": "610f42cd2cee9a0c24ee872f", "shortContent": "奉皇太后懿旨[1]：婉妃张氏，妄造谣言，荧惑[2]圣听，致令皇帝受惊，圣躬不豫[3]，实属罪大恶极。张氏着革去婉妃名号，交三法司处斩。钦此。\n奉旨：权守鄂州[4]张世杰奏报大获胜仗一节，深堪嘉尚。张世杰着授为黄州、武定诸军都统制[5]，仍责令相机进兵。钦此。\n作为晚清小说史上最为重要的作家之一，吴沃尧也是于讲史最努力者。《痛史》是他创作的第一部历史小说。对于历史小说，吴沃尧有着明确的论述，一方面他...", "authors": ["涂秀虹"], "pressName": "上海辞书出版社"}]', '', 'indent', 1585080322, '5e79f7768a84ab0077821fcb', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643942, '得道多助，失道寡助', NULL, 16, 271, 0, 4, '孟子', NULL, 10278, '57b9bc355bbb500063f5fd20', '周', 'wen', '文', '', '', '天时不如地利，地利不如人和。三里之城，七里之郭，环而攻之而不胜。夫环而攻之，必有得天时者矣，然而不胜者，是天时不如地利也。城非不高也，池非不深也，兵革非不坚利也，米粟非不多也，委而去之，是地利不如人和也。故曰，域民不以封疆之界，固国不以山溪之险，威天下不以兵革之利。得道者多助，失道者寡助。寡助之至，亲戚畔之。多助之至，天下顺之。以天下之所顺，攻亲戚之所畔，故君子有不战，战必胜矣。', '', '（1）天时：包括时令、气候，乃至政治形势等非人力所能及的条件。
（2）地利：指有利于作战的地理形势。
（3）人和：指作战中的人心有所向，内部团结。
（4）三里之城：方圆三里的内城。城：内城。城非不高也：城墙并不是不高啊。
（5）郭：外城。在城外加筑的一道城墙。
（6）环：围。
（7）之：代这座城。
（8）而：连词表转折。
（9）夫：句首发语词，不译。
（10）而：连词表递进。
（11）是：这。
（12）也：表判断语气，“是”。
（13）非：不是。
（14）池：护城河。
（15）兵革：泛指武器装备。兵，武器；革，甲胄，用以护身的盔甲之类。
（16）坚利：精良。坚，坚固。利，锋利。
（17）米粟：粮食。
（18）多：充足。
（19）委：放弃。
（20）而：连词表顺承。
（21）去：离开。
（22）之：代词，代“城”。
（23）故：所以。
（24）域：这里用作动词，是限制的意思。
（25）以：凭借。
（26）封疆之界：划定的边疆界线。封，划定。疆，边疆。界，界限。
（27）固：巩固。
（28）国：国防。
（29）山溪：山河。
（30）险：险要。
（31）威：震慑，树立威望。
（32）得道者：实施“仁政”的君主。者，……的人，此处特指君主。道，正义。下同。
（33）失道者：不实施“仁政”的君主。
（34）寡：少。
（35）之至：到达极点。
（36）畔：通“叛”，背叛。
（37）顺：归顺，服从
（38）以：凭借。
（39）之：主谓间取消句子独立性。
（40）故：所以。
（41）有：要么，或者。
（42）固国不以山溪之险：巩固国防不能靠山河的险要。
（43）威天下不以兵革之利：震慑天下不能靠武力的强大。
（44）亲戚：内外亲属，包括父系亲属和母系亲属。', '有利于作战的天气、时令，比不上有利于作战的地理形势，有利于作战的地理形势，比不上作战中的人心所向、内部团结。（比如一座）方圆三里的小城，只有方圆七里的外城，四面包围起来攻打它，却不能取胜。采用四面包围的方式攻城，一定是得到有利于作战的天气、时令了，可是不能取胜，时令比不上有利于作战的地理形势呀。城墙并不是不高啊，护城河并不是不深呀，武器装备也并不是不精良，粮食供给也并不是不充足啊，但是，守城一方还是弃城而逃，这是因为作战的地理形势（再好），也比不上人心所向、内部团结啊。所以说：使百姓定居下来而不迁到其它的地方去，不能依靠划定疆域的界限，巩固国防不能靠山河的险要，震慑天下不能靠武力的强大。能行“仁政”的君王，帮助支持他的人就多，不施行“仁政”的君主，支持帮助他的人就少。支持帮助他的人少到了极点，连内外亲属也会背叛他；支持帮助他的人多到了极点，天下所有人都会归顺他。凭着天下人都归顺他的条件，去攻打那连亲属都反对背叛的君王，君子要么不战斗，（如果）战斗就一定会取得胜利。', NULL, '', 'indent', 1585129744, '5e7ab88b21460d006b6efc63', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643943, '大道之行也', NULL, 40, 65, 0, 2, '戴圣', NULL, 36788, '586e300a1b69e6006306cdc6', '汉', 'wen', '文', '', '', '大道之行也，天下为公，选贤与能，讲信修睦。故人不独亲其亲，不独子其子，使老有所终，壮有所用，幼有所长，鳏、寡、孤、独、废疾者皆有所养，男有分，女有归。货恶其弃于地也，不必藏于己；力恶其不出于身也，不必为己。是故谋闭而不兴，盗窃乱贼而不作，故外户而不闭，是谓大同。', '', '（1）选自《礼记•礼运》。《礼记》，儒家经典之一，西汉戴圣对秦汉以前各种礼仪论著加以辑录、编纂而成，共49篇。礼运，《礼记》篇名，大约是战国末年或秦汉之际儒家学者托名孔子答问的著作。大道，指古代政治上的最高理想。行施行。
（2）大道：古代指政治上的最高理想。
（3）之行：之，助词取消句子之间的独立性。行，施行
（4）为：是，表判断。
（5）选贤与（jǔ）能：把品德高尚的人、能干的人选拔出来。与，通“举”，推举，选举。
（6）讲信修睦（mù）：讲求诚信，培养和睦（气氛。）信：诚信。修：培养。
（7）独：单独。
（8）亲:意动用法，用如动词，以……为亲，抚养。下文“子其子”中的第一个“子”也是动词。
（9）亲其亲：第一个亲，名词的意动用法，以……为亲人；第二个亲，父母。
（10）终：终老，终其天年。
（11）鳏（guān）、寡、孤、独、废疾者：鳏，老而无妻的人。寡，老而无夫的人。孤，幼而无父的人。独，老而无子的人。废疾，残疾人。
（12）养：供养。
（13）有所养：得到供养。
（14）男有分（fèn）：男子有职务。分，职分，指职业、职守。
（15）女有归：意思是女子有归宿。归，指女子出嫁。
（16）货恶（wù）其弃于地也，不必藏于己：意思是，对于财货，人们憎恨把它扔在地上的行为，却不一定要自己私藏。恶（wù），憎恶。藏：私藏。于：在。货恶：宾语前置。
（17）力恶其不出于身也，不必为己：意思是，人们都愿意为公众之事竭尽全力，而不一定为自己谋私利。力恶：宾语前置。
（18）是故：即“故是”，可译为“因此”“所以”“这样一来”。谋闭而不兴：奸邪之谋不会发生。闭，杜绝。兴，发生。
（19）盗窃乱贼而不作：盗窃、造反和害人的事情不发生。乱，指造反。贼，指害人。作，兴起。
（20）故：所以。外户，泛指大门。
（21）而：连词，表并列。
（22）闭：用门闩插门。
（23）谓：是。大同，指理想社会。同，有和平的意思。', '在大道施行的时候，天下是人们所共有的，把品德高尚的人、能干的人选拔出来，讲求诚信，培养和睦（气氛）。所以人们不单奉养自己的父母，不单抚育自己的子女，要使老年人能终其天年，中年人能为社会效力，让年幼的孩子有可以健康成长的地方，让老而无妻的人、老而无夫的人、幼而无父的人、老而无子的人、残疾人都能得到社会的供养，男子有职务，女子有归宿。对于财货，人们憎恨把它扔在地上的行为，却不一定要自己私藏；人们都愿意为公众之事竭尽全力，而不一定为自己谋私利。因此奸邪之谋不会发生，盗窃、造反和害人的事情不发生。所以大门都不用关上了，这叫做理想社会。', NULL, '', 'indent', 1585130082, '5e7ab9e02a6bfd0075ff3e59', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643945, '子路、曾晳、冉有、公西华侍坐', NULL, 316, 327, 0, 5, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '子路、曾晳、冉有、公西华侍坐。子曰：“以吾一日长乎尔，毋吾以也。居则曰：‘不吾知也。’如或知尔，则何以哉？”
子路率尔而对曰：“千乘之国，摄乎大国之间，加之以师旅，因之以饥馑；由也为之，比及三年，可使有勇，且知方也。”
夫子哂之。
“求，尔何如？”
对曰：“方六七十，如五六十，求也为之，比及三年，可使足民。如其礼乐，以俟君子。”
“赤，尔何如？”
对曰：“非曰能之，愿学焉。宗庙之事，如会同，端章甫，愿为小相焉。”
“点，尔何如？”
鼓瑟希，铿尔，舍瑟而作，对曰：“异乎三子者之撰。”
子曰：“何伤乎？亦各言其志也！”
曰：“莫春者，春服既成，冠者五六人，童子六七人，浴乎沂，风乎舞雩，咏而归。”
夫子喟然叹曰：“吾与点也。”
三子者出，曾晳后。曾晳曰：“夫三子者之言何如？”
子曰：“亦各言其志也已矣！”
曰：“夫子何哂由也？”
曰：“为国以礼，其言不让，是故哂之。唯求则非邦也与？安见方六七十，如五六十而非邦也者？唯赤则非邦也与？宗庙会同，非诸侯而何？赤也为之小，孰能为之大？”', '', '侍：侍奉，本指侍立于尊者之旁；
侍坐：此处指执弟子之礼，侍奉老师而坐。
以吾一日长乎尔：以，因为；长，年长。
毋吾以也：吾，作“以”的宾语，在否定句中代词宾语前置。以，同“已”，是“止”的意思。一说这里的“以”是动词，是“用”的意思。
居则曰：居，闲居，指平日在家的时候。则，就
如或：如果有人。如：假如。或：无定代词，有人
则：连词，那么，就
何以：用什么（去实现自己的抱负）。以，动词，做。
率尔：急遽而不加考虑的样子。尔，相当于“然”
千乘之国：有一千辆兵车的诸侯国。在春秋后期，是中等国家
乘：兵车。春秋时，一辆兵车，配甲士3人，步卒72人，称一乘
摄乎大国之间：摄，夹。乎：于，在。
加之以师旅：有（别国）军队来侵略它。加，加在上面。师旅，军队，此特指侵略的军队
因之以饥馑：接连下来（国内）又有饥荒。因，接续。饥馑，饥荒
比及：等到。
且：连词，并且。
方：道，义方指是非准则。
哂（shěn）：微笑，这里略带讥讽。
方：见方，纵横。
如：连词，表选择，或者；
足：使……富足。
如：连词，表提起另一话题，作“至于”讲，
其：那。
以：把。后边省宾语“之”。
俟：等待。
能：动词，能做到。
焉：这里作指示代词兼语气词，指代下文“小相”这种工作。
如：连词，或者。
会：诸侯之间的盟会。
同：诸侯共同朝见天子。
端：古代的一种礼服。
章甫：古代的一种礼帽。这里都是名词用作动词，意思是“穿着礼服，戴着礼帽”；
愿：愿意；
相：在祭祀、会盟或朝见天子时主持赞礼和司仪的人。
焉：兼词，于是，在这些场合里。
鼓：弹。
瑟：古乐器。
希：同“稀”，稀疏，这里指鼓瑟的声音已接近尾声。
舍：放下。
作：立起来，站起身；
撰：才具，才能。
伤：妨害。
乎：语气词，呢。
莫春者，春服既成：莫春：指农历三月。莫，通“暮”。既：副词，已经。
冠：古时男子二十岁为成年，束发加冠；
冠者五六人，童子六七人：几个成人，几个孩子。五六，六七，都是虚数。
喟然：叹息的样子。
与：赞成。
后：动词，后出
夫子何哂由也：何，为什么。
为国以礼，其言不让：要用礼来治理国家，可他说话却不知道谦虚。以：介词。靠，用。让：礼让，谦逊。
唯求则非邦也与：唯，难道。邦：国家，这是指国家大事。与，同“欤”，疑问语气词', '子路、曾晳、冉有、公西华陪（孔子）坐着。孔子说：“因为我年纪比你们大一点，（你们）不要因为我（年长）就不敢说话了。（你们）平日说：‘你们是不了解我的！’假如有人了解你们，那么（你们）打算做些什么事情呢？”
子路不假思索地回答说：“一个拥有千乘兵车的中等国家，夹在大国之间，加上外国军队的侵犯，接着又遇上饥荒；如果让我治理这个国家，等到三年功夫，就可以使人有保卫国家的勇气，而且还懂得做人的道理。”
孔子对他示以微笑。
“冉有，你怎么样？”
（冉有）回答说：“一个六七十里或者五六十里见方的国家，如果让我去治理，等到三年，就可以使老百姓富足起来。至于振兴礼乐教化，那就只有等待贤人君子来推行了。"
“公西华，你怎么样？”
（公西华）回答说：“我不敢说能做到什么，但愿意学着做些东西。宗庙祭祀的工作，或者是诸侯会盟及朝见天子的时候，我愿意穿着礼服，戴着礼帽，做一个小小的司仪。”
“曾晳，你怎么样？”
（曾晳）弹瑟的声音渐渐稀疏下来，铿的一声，放下瑟直起身来，回答说：“我和他们三人为政的才能不一样。"孔子说："那有什么关系呢？不过是各自谈谈自己的志向。"（曾晳）说：“暮春时节（天气和暖），春天的衣服已经穿上了。（我和）五六个成年人，六七个少年，到沂水里游泳，在舞雩台上吹风，唱着歌回家。”
孔子长叹一声说：“我赞同曾晳的想法呀！”
子路、冉有、公西华都出去了，曾晳最后走。曾晳问（孔子）：“他们三个人的话怎么样？”
孔子说：“也不过是各自谈谈自己的志向罢了！”
（曾晳）说：“您为什么笑仲由呢？”
（孔子说）：“治国要用礼，可是他（子路）的话毫不谦让，所以我笑他。”
（曾晳说）：“难道冉有讲的不是国家大事吗？”
（孔子说）：“怎么见得纵横六七十里或五六十里（的小国的事）不是国家大事呢？”
（曾晳说）：“难道公西华讲的不是诸侯的大事吗？”
（孔子说）：“宗庙祭祀，诸侯会盟和朝见天子，不是诸侯的大事又是什么呢？公西华只能替诸侯做小相，那么，谁又能给诸侯做大相呢？”', '[{"bookId": "60fc5be223353c0ba53dfa63", "bookTitle": "古文鉴赏辞典", "articleId": "610ed1d0911759740c9bdc80", "shortContent": "本文是《论语》中较富有文学色彩的一章。它通过孔子与其弟子坐而言志的描写，表现了四位弟子不同的性格以及师生对话时融洽的气氛。\n文章一开始，交待了谈话的人物和方式：子路、曾晳、冉有、公西华，这四位弟子环坐于孔子身旁。孔子最先发话，启发大家各言其志，起到了打消顾虑、缓和紧张气氛的作用，这符合孔子作为师长的身分，表现了孔子随和的性格特征。在孔子的启发下，子路不假思索，抢先回答。“率尔而对”，反映了子路急躁...", "authors": ["周勋初", "胡传志"], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a700251899613caf301b", "shortContent": "孔子一贯主张学无常师，从来不把学习活动只限制在学校之内，也不认为只有学校的教师才有资格称老师。正因为他虚心向一切有知识的人求教，所以他“入太庙，每事问”（《八佾》），因此在战国时期有七岁童子项橐为孔子师的传说。据记载，孔子曾向鲁乐官襄子学弹琴，向鲁之附庸国君主郯子学古史知识，又曾问礼于老子。孔子如此好学，所以博学多能。“三人行，必有我师”的说法正是他总结自己成长经历所得出的宝贵的经验之谈。\n\n语录...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a700251899613caf301d", "shortContent": "彫同“凋”，表示凋零。\n\n对于孔子这句话，历来注家多解为赞美有德之士的节操，如朱熹的《四书集注》引学者之语说：“士穷见节义，世乱识忠臣。”实际上孔子这句话所包含的更深刻、更积极的意义为注家所忽略。孔子是以松柏在严酷的环境中仍然焕发勃勃生机的现象，来赞颂理想人格在极其困难艰险的处境中所表现的永不衰竭的强大精神生命力。\n\n在许多人的眼中，儒家士人不是死守陈旧道德教条的循规蹈矩之士，就是总是温和谦恭、谨...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a700251899613caf3020", "shortContent": "基督教特别强调人的原罪的危害，以促使世人警觉，改恶从善。孔子也对人性的阴暗面做了许多透彻的剖析，但是他更多地从正面教育，力图用理想人格的光辉引导世人克服人性中的黑暗，孔子的这句名言，就是基于这一理念而提出的。孔子在这里实际上是指出人们在对待人性的痼疾———妒忌的两种截然不同的态度，一种是把它从心灵中完全扫除出去，从而成人之美，这样就成就了君子人格，而另外一种则是让它完全控制了自己的心灵，从而危害别...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70030a1d3054c75734e", "shortContent": "子夏（前507—？）姓卜，名商，字子夏，是孔子的学生。他出身于寒门，青少年时期家中“甚短于财”（刘向《说苑·杂言》），后以文学见长。孔子死后，他到魏国讲学，曾做过魏文侯的老师，汉代以后学者多认为儒家大部分经典是经由他传下来的。莒（犼ǔ）父是鲁国的小城镇，在今山东省莒县境内。本文中的宰是指地方行政长官。\n\n对于子夏在莒父理政，孔子提出的唯一忠告是不要急功近利。他认为治理一个地方不能急于求成，希冀立竿...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70030a1d3054c75734f", "shortContent": "成人，即成就一种君子的人格。孔子以为，完美的人格离不开礼乐的熏陶，如有臧武仲那样的智慧、孟公绰之清心寡欲、卞庄子式的勇敢、冉求的才艺，再“文之以礼乐，亦可以为成人矣”。他还从义利之辩的角度，提出“今之成人者何必然？见利思义，见危授命，久要不忘平生之言，亦可以为成人矣”（《宪问》）。\n\n在孔子看来，君子人格的造就，并不只是局限于心性的修炼和道义的坚守，还要在实功事利的追求中，仍能遵循和信守道义的原则...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70030a1d3054c757350", "shortContent": "在平时待人接物中人们经常遇到的问题是，怎样对待怨恨自己或有恩德于自己的人，然而恰恰在这个问题上，人们很容易为自己一种盲目的感情所支配，作出不当的反应，孔子就是针对这种情况讲述自己的看法。\n\n人活在世上，难免要遭人怨恨。人与人之间总是会发生龃龉，有龃龉就会产生怨恨。因自己的错误言行而遭人怨恨，这是十分自然的事，然而自己的做法一时不为人们所理解也会招致怨恨。不仅如此，自己对他人的好没有达到对方预期的程...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a70030a1d3054c757351", "shortContent": "儒家的理想人格如同孔子被描写的那样，“温、良、恭、俭、让”（《学而》），看起来好像温顺随和，然而实际上是外柔而内刚，其灵魂深处有一股强大的力量，具有不怕牺牲的豪杰精神。这段名言就是这种精神的一种表现。\n\n孔子是个非常热爱生活、珍惜生命的人。有一次上朝回来听说马厩失火，他立即问是否伤了人，而不问马的损失如何。他从不要求为某个人甚至是君主死节。他教人“危邦不入，乱邦不居。天下有道则见，无道则隐”（《泰...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fb4bc5e6bb82b8cafcc91", "bookTitle": "中小学生必背古诗文（高中）", "articleId": "6471a48782772d459426528e", "shortContent": "本文是《论语》中较富有文学色彩的一章。它通过孔子与其弟子坐而言志的描写，表现了四位弟子不同的性格以及师生对话时融洽的气氛。\n文章一开始，交待了谈话的人物和方式：子路、曾皙、冉有、公西华，这四位弟子环坐于孔子身旁。孔子最先发话，启发大家各言其志，起到了打消顾虑、缓和紧张气氛的作用，这符合孔子作为师长的身份，表现了孔子随和的性格特征。在孔子的启发下，子路不假思索，抢先回答。“率尔而对”，反映了子路急躁...", "authors": ["周勋初", "胡传志"], "pressName": "上海辞书出版社"}]', '', 'indent', 1585182233, '5e7b859491db28006a2c13ae', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (643946, '资治通鉴·晋纪·淝水之战', NULL, 0, 1577, 0, 1, '司马光', NULL, 10351, '57b9c6d179bc4400639cc661', '宋', 'wen', '文', '', '', '太元八年，秋，七月。
秦王坚下诏大举入寇，民每十丁遣一兵；其良家子年二十已下，有材勇者，皆拜羽林郎。又曰：“其以司马昌明为尚书左仆射，谢安为吏部尚书，桓冲为侍中；势还不远，可先为起第。”良家子至者三万余骑，拜秦州主簿赵盛之为少年都统。是时，朝臣皆不欲坚行，独慕容垂、姚苌及良家子劝之。阳平公融言于坚曰：“鲜卑、羌虏，我之仇雠，常思风尘之变以逞其志，所陈策画，何可从也！良家少年皆富饶子弟，不闲军旅，苟为谄谀之言以会陛下之意耳。今陛下信而用之，轻举大事，臣恐功既不成，仍有后患，悔无及也！”坚不听。
八月，戊午，坚遣阳平公融督张蚝、慕容垂等步骑二十五万为前锋；以兖州刺史姚苌为龙骧将军，督益、梁州诸军事。坚谓苌曰：“昔朕以龙骧建业，未尝轻以授人，卿其勉之！”左将军窦冲曰：“王者无戏言，此不祥之征也！”坚默然。
诏以尚书仆射谢石为征虏将军、征讨大都督，以徐、兖二州刺史谢玄为前锋都督，与辅国将军谢琰、西中郎将桓伊等众共八万拒之；使龙骧将军胡彬以水军五千援寿阳。琰，安之子也。
慕容楷、慕容绍言于慕容垂曰：“主上骄矜已甚，叔父建中兴之业，在此行也！”垂曰：“然。非汝，谁与成之！”
甲子，坚发长安，戎卒六十余万，骑二十七万，旗鼓相望，前后千里。九月，坚至项城，凉州之兵始达咸阳，蜀、汉之兵方顺流而下，幽、冀之兵至于彭城，东西万里，水陆齐进，运漕万艘。阳平公融等兵三十万，先至颍口。
诏以尚书仆射谢石为征虏将军、征讨大都督，以徐、兖二州刺史谢玄为前锋都督，与辅国将军谢琰、西中郎将桓伊等众共八万拒之；使龙骧将军胡彬以水军五千援寿阳。琰，安之子也。
是时，秦兵既盛，都下震恐。谢玄入，问计于谢安，安夷然，答曰：“已别有旨。”既而寂然。玄不敢复言，乃令张玄重请。安遂命驾出游山墅，亲朋毕集，与围棋赌墅。安棋常劣于玄，是日，玄惧，便为敌手而又不胜。安遂游陟，至夜乃还。桓冲深以根本为忧，遣精锐三千入卫京师；谢安固却之，曰：“朝廷处分已定，兵甲无阙，西藩宜留以为防。”冲对佐吏叹曰：“谢安石有庙堂之量，不闲将略。今大敌垂至，方游谈不暇，遣诸不经事少年拒之，众又寡弱，天下事已可知，吾其左衽矣！”
冬，十月，秦阳平公融等攻寿阳。癸酉，克之，执平虏将军徐元喜等。融以其参军河南郭褒为淮南太守。慕容垂拔郧城。胡彬闻寿阳陷，退保硖石，融进攻之。秦卫将军梁成等帅众五万屯于洛涧，栅淮以遏东兵。谢石、谢玄等去洛涧二十五里而军，惮成不敢进。胡彬粮尽，潜遣使告石等曰：“今贼盛粮尽，恐不复见大军！”秦人获之，送于阳平公融。融驰使白秦王坚曰：“贼少易擒，但恐逃去，宜速赴之！”坚乃留大军于项城，引轻骑八千，兼道就融于寿阳。遣尚书朱序来说谢石等，以为：“强弱异势，不如速降。”序私谓石等曰：“若秦百万之众尽至，诚难与为敌。今乘诸军未集，宜速击之；若败其前锋，则彼已夺气，可遂破也。”
石闻坚在寿阳，甚惧，欲不战以老秦师。谢琰劝石从序言。十一月，谢玄遣广陵相刘牢之帅精兵五千人趣洛涧，未至十里，梁成阻涧为陈以待之。牢之直前渡水，击成，大破之，斩成及弋阳太守王咏，又分兵断其归津，秦步骑崩溃，争赴淮水，士卒死者万五千人。执秦扬州刺史王显等，尽收其器械军实。于是谢石等诸军，水陆继进。秦王坚与阳平公融登寿阳城望之。见晋兵部阵严整，又望八公山上草木，皆以为晋兵，顾谓融曰：“此亦勍敌，何谓弱也！”怃然始有惧色。
秦兵逼淝水而陈，晋兵不得渡。谢玄遣使谓阳平公融曰：“君悬军深入，而置陈逼水，此乃持久之计，非欲速战者也。若移陈少却，使晋兵得渡，以决胜负，不亦善乎！”秦诸将皆曰：“我众彼寡，不如遏之，使不得上，可以万全。”坚曰：“但引兵少却，使之半渡，我以铁骑蹙而杀之，蔑不胜矣！”融亦以为然，遂麾兵使却。秦兵遂退，不可复止。谢玄、谢琰、桓伊等引兵渡水击之。融驰骑略陈，欲以帅退者，马倒，为晋兵所杀，秦兵遂溃。玄等乘胜追击，至于青冈。秦兵大败，自相蹈藉而死者，蔽野塞川。其走者闻风声鹤唳，皆以为晋兵且至，昼夜不敢息，草行露宿，重以饥冻，死者什七、八。初，秦兵少却，朱序在陈后呼曰：“秦兵败矣！”众遂大奔。序因与张天锡、徐元喜皆来奔。获秦王坚所乘云母车。复取寿阳，执其淮南太守郭褒。
坚中流矢，单骑走至淮北，饥甚，民有进壶飧、豚髀者，坚食之，赐帛十匹、绵十斤。辞曰：“陛下厌苦安乐，自取危困。臣为陛下子，陛下为臣父，安有子饲[2]其父而求报乎！”弗顾而去。坚谓张夫人曰：“吾今复何面目治天下乎！”潸然流涕。
是时，诸军皆溃，惟慕容垂所将三万人独全，坚以千余骑赴之。世子宝言于垂曰：“家国倾覆，天命人心皆归至尊，但时运未至，故晦迹自藏耳。今秦主兵败，委身于我，是天借之便以复燕祚，此时不可失也，愿不以意气微恩忘社稷之重！”垂曰：“汝言是也。然彼以赤心投命于我，若之何害之！天苟弃之，何患不亡？不若保护其危以报德，徐俟其衅而图之！既不负宿心，且可以义取天下。”奋威将军慕容德曰：“秦强而并燕，秦弱而图之，此为报仇雪耻，非负宿心也；兄奈何得而不取，释数万之众以授人乎？”
垂曰：“吾昔为太傅所不容，置身无所，逃死于秦，秦主以国士遇我，恩礼备至。后复为王猛所卖，无以自明，秦主独能明之，此恩何可忘也！若氐运必穷，吾当怀集关东，以复先业耳，关西会非吾有也。”冠军行参军赵秋曰：“明公当绍复燕祚，著于图谶；今天时已至，尚复何待！若杀秦主，据邺都，鼓行而西，三秦亦非苻氏之有也”！垂亲党多劝垂杀坚，垂皆不从，悉以兵授坚。平南将军慕容暐屯郧城，闻坚败，弃其众遁去；至荥阳，慕容德复说暐起兵以复燕祚，暐不从。
谢安得驿书，知秦兵已败，时方与客围棋，摄书置床上，了无喜色，围棋如故。客问之，徐答曰：“小儿辈遂已破贼。”既罢，还内，过户限，不觉屐齿之折。', '', '（1）秦王坚：前秦王苻坚，氐族人，十六国时期前秦的皇帝。早期很有作为，曾统一中国北方，国力一度超过东晋数倍，很有机会统一全国，但是在淝水之战中惨败。鲜卑、羌等部族相继叛变，西燕慕容冲攻入长安，苻坚出逃被杀。
（2）入寇：侵入东晋。
（3）良家子：民间地主子弟
（4）羽林郎：官名，汉代所置，皇家禁卫军军官。
（5）秦州：今甘肃天水。
（6）金城：今甘肃兰州。
（7）都统：武官名，始置于十六国时期，为统兵将官。
（8）慕容垂：又名慕容霸，鲜卑族人。公元384年建立后燕，后投降前秦。淝水之战中暗中保存实力，在前秦败后叛变，姚苌：后秦武昭帝，羌族。十六国时期后秦政权的开国君主。公元357年与前秦战于三原，兵败投降，后为苻坚部将，累建战功。淝水之战后，前秦大败，姚苌趁机自立。公元385年缢杀苻坚于新平佛寺（今彬县南静光寺），称帝于长安，国号大秦。
（9）阳平公融：苻融，苻坚之弟，封阳平公。
（10）鲜卑、羌虏：即分别指慕容垂、姚苌的国家。
（11）仇雠（chóu）：仇敌。
（12）闲：同“娴”，熟悉，精通。
（13）谄（chǎn）谀：奉承拍马。
（14）会：迎合。
（15）戎卒：兵士。
（16）项城：今河南项城。
（17）凉州：今武威，地处甘肃河西走廊东端。
（18）咸阳：今陕西咸阳。
（19）幽、冀：今河北地区。
（20）彭城：今江苏徐州。
（21）颍口：今安徽颍上东南的西正阳镇。
（22）寿阳：今安徽寿县。
（23）平虏将军：东晋武官名。
（24）淮南太守：治所在安徽寿县，今安徽淮河以南地区的地方长官。
（25）郧（yún）城：今湖北安陆。
（26）硖（xiá）石：安微凤台、寿县一带。
（27）卫将军：官名，汉代设立，掌握禁兵，预闻政务。
（28）洛涧：即洛水。
（29）栅淮以遏东兵：在淮水上设立栅栏以阻挡东晋军队。栅，动词，用竹、木、铁条等做成的阻拦或防卫物。遏，阻拦，阻挡。
（30）兼道：加倍赶路。
（31）老：使得对方衰竭，疲惫。
（32）刘牢之：东晋名将。
（33）趣（qū）：趋赴，奔向。
（34）陈：同“阵”，军阵。
（35）弋（yì）阳太守：江西弋阳地区的地方官。
（36）归津：退路。
（37）器械军实：军用器械和粮饷。
（38）八公山：位于寿县城北，距城2？5公里，南临淝水，北濒淮河。
（39）怃（wǔ）然：怅然失意的样子。
（40）陈：同“阵”，布阵。
（41）蹙（cù）：逼近，逼迫。
（42）蔑：没有。
（43）麾（huī）：指挥。
（44）驰骑略陈：骑着马来回奔驰，想要压住阵脚。
（45）青冈：今安徽凤台西北。
（46）蹈藉（jì）：践踏。
（47）风声鹤唳（lì）：形容惊慌失措，或自相惊扰。唳，鹤叫声。
（48）云母车：以云母为饰的车。
（49）壶飧（sūn）：一壶水泡饭。飧，晚饭，饭食。
（50）豚（tún）髀（bì）：猪腿。
（51）潸（shān）然流涕：伤心流泪的样子。', '太元八年秋天，七月。
秦王苻坚（氐族所建前秦国的皇帝）颁布诏令大举入侵（东晋），百姓每十个年轻人中抽调一人当兵；家世清白而有一定财产的民间地主子弟，有才干而勇武的人，（朝廷）都授予他们羽林郎的职务。诏书中又说：“（胜利后）朝廷任命东晋孝武帝司马昌明任尚书左仆射，谢安任吏部尚书，桓冲任侍中；依情势看，我国出征凯旋还师，为时不远，可以事先（派定东晋皇帝和大臣归降后的官职）为他们修建府第。”民间富家子弟前来效命的有三万多人马，任命秦州主簿赵盛之担任少年都统。这时，朝廷的大臣都不希望苻坚采取这样的行动，只有慕容垂、姚苌以及民间富家子弟支持他（这样做）。阳平公苻融对苻坚说：“鲜卑（指慕容垂），羌虏（指姚苌），是我们的仇敌（此二人之国都被苻坚所灭，他们虽然臣服于秦，但心怀仇怨），总想着发生变故来实现他们复仇的志向，他们所陈述的策略，怎么可以听从呢！。良家少年都是富贵子弟，不懂军事，只是说些谄媚的话来迎合陛下的心意罢了。”如果陛下轻信并重用他们，轻率采取重大行动，我担心既不能成功，又会有后患，后悔就来不及了！”苻坚不听他的劝谏。
八月，戊午日这天，苻坚派遣阳平公苻融统领张蚝、慕容垂等的二十五万步兵骑兵为前锋；任命兖州刺史姚苌担任龙骧将军，统领益州、梁州各方面的军事。苻坚对姚苌说：“过去我担任龙骧将军而开创基业，从来不轻易把这个职位授给别人，你可要自勉啊！”左将军窦冲说：“君王说话都不是开玩笑，这是不祥的征兆啊！”苻坚沉默不语。
东晋下诏任命尚书仆射谢石（谢安之弟）担任征虏将军、征讨大都督，任命徐州、兖州的刺史谢玄（谢安侄儿）担任前锋都督，与辅国将军谢琰、西中郎将桓伊等各部总共八万人马抵御苻坚；派龙骧将军胡彬率领五千水军增援寿阳。谢琰，是谢安的儿子。
慕容楷、慕容绍（两人都是慕容垂的侄子）对慕容垂说：“苻坚骄傲自大太过分了，叔父建立复兴的大业，就在这次行动了！”慕容垂说：“对。要不是你们，我与谁一块成就大事呢！”
甲子日，苻坚从长安出兵，步兵六十余万，骑兵二十七万，旗鼓遥遥相望，前后长达千里。九月，苻坚到达项城，凉州的军队才到达咸阳，蜀、汉的军队正顺流而下，幽州、冀州的军队到达彭城，东西相连长达万里，水陆大军一齐进发，运输船只多达万艘。阳平公苻融等率兵三十万，先到达颍口。
（晋武帝）下诏以尚书仆射谢石为征虏将军、征讨大都督，以徐、兖二州刺史谢玄为前锋都督，与辅国将军谢琰、西中郎将桓伊等众人共领八万将士抵挡前秦军；派遣龙骧将军胡彬以水军五千增援寿阳。谢琰，谢安的儿子。这时，前秦兵力已经很强盛，东晋朝廷上下震惊恐慌。谢玄进来，向谢安问计，谢安神色平静，回答说：“朝廷已经另有打算。”然后就不说话了。谢玄不敢再说什么，就让张玄再次去询问。谢安于是命令车驾山林别墅去游赏，亲朋全都来了，谢安与张玄下围棋用别墅作赌注。谢安的棋艺通在张玄之下，这天，张玄（对前秦大兵犯境）有畏惧情绪，就使谢安成了他的敌手而不能取胜。谢安（下完棋后）于是登高游览，直到夜里才回来。桓冲深为京城安危而忧虑，派三千精锐士兵前来保卫京师；谢安坚决地拒绝了，说：“朝廷谋划已定，兵力和装备都不缺，你镇守的荆州是京师建康西边的屏障，应该留下这些精锐部队作为防备。”桓冲对辅佐的官吏感叹曰：“谢安石有执掌朝政的才能和度量，（但他）不懂得用兵的韬略。如今大敌就要到了，他还不停地外出游玩闲谈，派几个没有经历过大事的孩子抵御敌军，兵力又少又弱，东晋的命运已可想而知，我们这些人将臣服于前秦氐族人的统治了！”（注：古代北方游牧民族都披发左衽，而中原华夏民族则束发右衽。桓冲在这里借用典故，意指东晋将会战败。）
太元八年，冬，十月，前秦的阳平公苻融等攻打寿阳。癸酉日这天，攻下寿阳，活捉了东晋的平虏将军徐元喜等人。苻融让参军河南人郭褒担任淮南太守。慕容垂攻克了郧城。胡彬听说寿阳被攻陷，退守硖石，苻融率军进攻。前秦的卫将军梁成等人率领五万人马在洛涧驻扎，在淮水边设置栅栏来阻挡东晋的军队。谢石、谢玄等在距离洛涧二十五里的地方驻军，因害怕梁成的军队而不敢前进。胡彬粮草用尽，暗中派使者报告谢石等人说：“如今敌人强盛而我方没有粮草，恐怕再也见不到东晋的大军了！”前秦士兵抓住了这个使者，把他送交阳平公苻融。苻融派人骑马向秦王苻坚报告说：“敌人兵力少很容易擒获，只是担心他们逃跑，应该赶快前去攻打！”苻坚于是把大军留在项城，带领轻装的八千骑兵，昼夜行军在寿阳与苻融会合。苻坚派尚书朱序（东晋大臣，兵败被俘降前秦，淝水战后，复归东晋）来劝说谢石等人，认为：“强弱之势不同，不如赶快投降。”朱序私下对谢石等人说：“如果前秦的百万大军全部来到，你们实在难以与他们为敌。如今乘各路大军还没有到齐，应该尽快攻击他们；如果打败他的前锋，就削弱了他们的士气，可以就此彻底打败他们。”
谢石听说苻坚在寿阳，很害怕，想不交战而使秦军疲乏力衰。谢琰劝谢石听从朱序的建议。十一月，谢玄派广陵相刘牢之率领精兵五千人奔赴洛涧，离洛涧不到十里，梁成抢先占据洛河，布成阵势，等待刘牢之。刘牢之径直前进渡过涧水，攻击梁成，打败了他们，将梁成和弋阳太守王咏斩首，又分兵阻断他们归去的渡口，秦的步兵骑兵溃不成军，士兵争先恐后地逃进淮水，死亡的士卒有一万五千人。抓住秦的扬州刺史王显等人，全部收缴他们的器械等各种军用物资。于是谢石的各路大军，水陆两路同时进发。秦王苻坚与阳平公苻融登上寿阳城望去。只见晋兵阵容严整，又望见八公山上的草木，以为都是埋伏在那里的晋兵，回头对苻融说：“这样的军队也是劲敌，怎么能说他们弱小呢！”怅然失意，这才有了害怕的神色。
秦兵紧靠着淝水列阵，晋兵不能渡河。谢玄派使者对阳平公苻融说：“你孤军深入，却把阵势摆在淝水边，这是持久的打算，而不是想速战速决。如果把你们的阵势移动一下稍稍退却，让晋兵渡过淝水，来决一胜负，不是很好吗！”秦的众位将领都说：“我军人多他们人少，不如阻挡他们，使他们不能渡河，可以万无一失。”苻坚说：“只须带兵稍稍后退，让他们渡到一半时，我们用铁骑践踏而杀死他们，这样没有不能取胜的！”苻融也认为对，于是指挥军队稍稍退后。秦兵于是开始后退，（这一退）无法停下来。谢玄、谢琰、桓伊等率兵渡过淝水攻击秦军。苻融骑马奔驰压阵，想以此阻挡退却的士兵，但马倒地，他被晋兵杀死，秦军于是溃败。谢玄等人乘胜追击，追到青冈。秦兵大败，自相踩踏而死的士兵，躺满原野塞满河川。那些逃跑的士兵听到风吹的声音和鹤叫声，都以为晋兵就要追来，昼夜不敢停，在草丛里行军在野外住宿，再加上又冷又饿，死的人十分之七、八。刚开始，秦兵稍稍退却时，朱序在阵后大声呼叫说：“秦兵败了！”士兵们于是狂奔逃命。朱序趁机与张天锡、徐元喜都（向东晋的大军）奔来。缴获秦王苻坚乘坐的云母车。又攻下了寿阳，活捉淮南太守郭褒。
苻坚被流矢射中，单骑逃到至淮北，饿极了，有个百姓给他进献稀饭和煮熟的猪腿，苻坚吃完，赏赐他帛十匹、绵十斤。那位百姓推辞说：“陛下害怕艰苦享受安乐，自己陷入危困的局面。臣是陛下的儿子，陛下是臣的父亲，哪里有儿子给自己的父亲吃饭而求回报的呢！”（对帛、绵等）不看一眼就离开了。苻坚对张夫人（苻坚的宠姬）说：“我如今还有何面目治理天下啊！”悲伤地流下了眼泪。
这时，各路军队都溃败了，只有慕容垂率领的三万人马得以保全，苻坚率领千余人马到他那里去。世子宝（慕容垂第四子）对慕容垂说：“咱们的家国倾覆了，天命人心都归于我们的君主，但时机和运气还没有到来，所以我们晦暂时把自己的锋芒隐藏起来。如今秦主苻坚兵败，他把他自身交给我们，这是上天借给我们这个便利来恢复燕国的国运，这个时机不能失去，希望你不要因为苻坚对你的微小恩惠而忘记国家大事！”慕容垂说：“你们说的很对。但他凭一颗诚心来投奔我，怎么能害他呢！上天如果抛弃他，何必担心他不灭亡？不如保护他，在他危难时用美德报答他，慢慢等待时机再谋划这件事！（这样）既不辜负他一向对我们的好心，而且可以凭大义取得天下。”奋威将军慕容德说：“秦强大的时候吞并了燕国，秦衰弱了我们攻取他，这是为国家报仇雪耻，不是辜负他的好心；兄长为什么可以得到却不攻取，放下（兵权）把数万人马交给别人呢？”
慕容垂说：“我过去被太傅慕容评不容，无处安身，为逃命来到前秦，秦的国君把我当国士对待，恩惠礼遇都很周到。后来又被王猛出卖，无法表明自己的清白，秦主苻坚却能明察，这样的大恩怎么能够忘记呢！如果（不这样做）我们氐族命运必定更加衰弱，我一定以怀柔之策招集关东兵民，来复兴氐族先前的大业，而关西应该不是我们所有的。”冠军行参军赵秋说：“明公应当复兴燕国的国运，在图谶（古代巫师、方士制作的一种验证吉凶的图苻）上已经显示出征兆；如今天时已经来到，还等待什么呢！如果杀了秦主，占据邺都，向西进军，三秦之地也不是苻坚所有的了”！慕容垂的亲党大多劝说慕容垂杀掉苻坚，慕容垂都没有听从，把全部兵马都交给了苻坚。平南将军慕容暐屯兵郧城，听说苻坚被打败，把他的部众抛下不管自己逃跑了；到了荥阳，慕容德又劝说慕容暐起兵来复兴燕国，慕容暐不听。
谢安收到驿马送来的战报，知道秦兵已经被打败，当时他正与客人下围棋，收起书信放在坐榻上，脸上没有一点喜悦的神情，仍像原先那样下围棋。客问他，他从容地回答说：“孩儿们已经如愿把秦兵打败了。”下完棋，他回内室，过门槛时（难以控制内心的喜悦而步履不稳），不知不觉间竟折断了屐齿。
