INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (645004, '论语·为政篇', NULL, 4, 327, 0, 1, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '子曰：“为政以德，譬如北辰，居其所而众星共之。”
子曰：“《诗》三百，一言以蔽之，曰：‘思无邪’。”
子曰：“道之以政，齐之以刑，民免而无耻。道之以德，齐之以礼，有耻且格。”
子曰：“吾十有五而志于学，三十而立，四十而不惑，五十而知天命，六十而耳顺，七十而从心所欲，不逾矩。”
孟懿子问孝，子曰：“无违。”樊迟御，子告之曰：“孟孙问孝于我，我对曰‘无违’。”樊迟曰：“何谓也？”子曰：“生，事之以礼；死，葬之以礼，祭之以礼。”
孟武伯问孝。子曰：“父母唯其疾之忧。”
子游问孝。子曰：“今之孝者，是谓能养。至于犬马皆能有养；不敬，何以别乎？”
子夏问孝。子曰：“色难。有事，弟子服其劳；有酒食，先生馔，曾是以为孝乎？”
子曰：“吾与回言终日，不违，如愚。退而省其私，亦足以发，回也不愚。”
子曰：“视其所以，观其所由，察其所安，人焉廋哉？人焉廋哉？”
子曰：“温故而知新，可以为师矣。”
子曰：“君子不器。”
子贡问君子。子曰：“先行其言而后从之。”
子曰：“君子周而不比，小人比而不周。”
子曰：“学而不思则罔，思而不学则殆。”
子曰：“攻乎异端，斯害也已！”
子曰：“由，诲汝知之乎！知之为知之，不知为不知，是知也。”
子张学干禄。子曰：“多闻阙疑，慎言其余，则寡尤；多见阙殆，慎行其余，则寡悔。言寡尤，行寡悔，禄在其中矣。”
哀公问曰：“何为则民服？”孔子对曰：“举直错诸枉，则民服；举枉错诸直，则民不服。”
季康子问：“使民敬、忠以劝，如之何？”子曰：“临之以庄，则敬；孝慈，则忠；举善而教不能，则劝。”
或谓孔子曰：“子奚不为政？”子曰：“《书》云：‘孝乎惟孝，友于兄弟，施于有政。’是亦为政，奚其为为政？”
子曰：“人而无信，不知其可也。大车无輗，小车无軏，其何以行之哉？”
子张问：“十世可知也？”子曰：“殷因于夏礼，所损益，可知也；周因于殷礼，所损益，可知也。其或继周者，虽百世，可知也。”
子曰：“非其鬼而祭之，谄也；见义不为，无勇也。”', '', '', '孔子说：“（周君）以道德教化来治理政事，就会像北极星那样，自己居于一定的方位，而群星都会环绕在它的周围。”
孔子说：“《诗经》三百篇，可以用一句话来概括它，就是‘思想纯正’。”
孔子说：“用法制禁令去引导百姓，使用刑法来约束他们，老百姓只是求得免于犯罪受惩，却失去了廉耻之心；用道德教化引导百姓，使用礼制去统一百姓的言行，百姓不仅会有羞耻之心，而且也就守规矩了。”
孔子说：“我十五岁立志于学习；三十岁能够自立；四十岁能不被外界事物所迷惑；五十岁懂得了天命；六十岁能正确对待各种言论，不觉得不顺；七十岁能随心所欲而不越出规矩。”
孟懿子问什么是孝，孔子说：“孝就是不要违背礼。”后来樊迟给孔子驾车，孔子告诉他：“孟孙问我什么是孝，我回答他说不要违背礼。”樊迟说：“不要违背礼是什么意思呢？”孔子说：“父母活着的时候，要按礼侍奉他们；父母去世后，要按礼埋葬他们、祭祀他们。”
孟武伯向孔子请教孝道。孔子说：“对父母，要特别为他们的疾病担忧。（这样做就可以算是尽孝了。）”
子游问什么是孝，孔子说：“如今所谓的孝，只是说能够赡养父母便足够了。然而，就是犬马都能够得到饲养。如果不存心孝敬父母，那么赡养父母与饲养犬马又有什么区别呢？”
子夏问什么是孝，孔子说：“（当子女的要尽到孝），最不容易的就是对父母和颜悦色，仅仅是有了事情，儿女需要替父母去做，有了酒饭，让父母吃，难道能认为这样就可以算是孝了吗？”
孔子说：“我整天给颜回讲学，他从来不提反对意见和疑问，像个蠢人。等他退下之后，我考察他私下的言论，发现他对我所讲授的内容有所发挥，可见颜回其实并不蠢。”
孔子说：“（要了解一个人），应看他言行的动机，观察他所走的道路，考察他安心干什么，这样，这个人怎样能隐藏得了呢？这个人怎样能隐藏得了呢？”
孔子说：“在温习旧知识时，能有新体会、新发现、就可以当老师了。”
孔子说：“君子不像器具那样，（只有某一方面的用途）。”
子贡问怎样做一个君子。孔子说：“对于你要说的话，先实行了，再说出来，（这就够说是一个君子了）。”
孔子说：“君子合群而不与人勾结，小人与人勾结而不合群。
孔子说：“只读书学习，而不思考问题，就会罔然无知而没有收获；只空想而不读书学习，就会疑惑而不能肯定。“
孔子说：“要整理整顿那些异端，（因为）他们对天下的危害太大了！”
孔子说：“由，我教给你怎样做的话，你明白了吗？知道的就是知道，不知道就是不知道，这就是智慧啊！”
子张要学谋取官职的办法。孔子说：“要多听，有怀疑的地方先放在一旁不说，其余有把握的，也要谨慎地说出来，这样就可以少犯错误；要多看，有怀疑的地方先放在一旁不做，其余有握的，也要谨慎地去做，就能减少后悔。说话少过失，做事少后悔，官职俸禄就在这里了。”
鲁哀公问：“怎样才能使百姓服从呢？”孔子回答说：“把正直无私的人提拔起来，把邪恶不正的人置于一旁，老百姓就会服从了；把邪恶不正的人提拔起来，把正直无私的人置于一旁，老百姓就不会服从统治了。”
季康子问道：“要使老百姓对当政的人尊敬、尽忠而努力干活，该怎样去做呢？”孔子说：“你用庄重的态度对待老百姓，他们就会尊敬你；你对父母孝顺、对子弟慈祥，百姓就会尽忠于你；你选用善良的人，又教育能力差的人，百姓就会互相勉励，加倍努力了。”
有人对孔子说：“你为什么不去从事政治呢？”孔子回答说：“《尚书》上说，‘孝就是孝敬父母，友爱兄弟。’把这孝悌的道理施于政事，也就是从事政治，又要怎样才能算是为政呢？”
孔子说：“一个人不讲信用，是根本不可以的。就好像大车没有輗、小车没有軏一样，它靠什么行走呢？”
子张问孔子：“今后十世（的礼仪制度）可以预先知道吗？”孔子回答说：“商朝继承了夏朝的礼仪制度，所减少和所增加的内容是可以知道的；周朝又继承商朝的礼仪制度，所废除的和所增加的内容也是可以知道的。将来有继承周朝的，就是一百世以后的情况，也是可以预先知道的。”
孔子说：“不是你应该祭的鬼神，你却去祭它，这就是谄媚。见到应该挺身而出的事情，却袖手旁观，就是怯懦。”', '[{"bookId": "60fd4b7c23353c0ba53f7de0", "bookTitle": "古代志怪小说鉴赏辞典", "articleId": "610f3f7f5914587d02f66f0c", "shortContent": "本篇写的是东晋某孝子因杀狸受到陷害，但他坚持己见，实事求是，终于真相大白的故事。\n这位孝子没有一点儿迂腐气，他自始至终不为狸幻所迷惑。化作妇人的狸，以及后来扭住他送官府要偿命的老狸，都难以迷惑于他。\n在大千世界中，丑恶和虚伪往往是披着美丽和真诚的面纱进入人际双向活动的。大奸似忠，天使和魔鬼只是心灵的差别。所以认识世界、认识社会在某种意义上说，最难的是具有那种知人之明。识人如辨色，《老子》说：“五色...", "authors": ["盛巽昌"], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a6ff251899613caf3013", "shortContent": "这里的“共”同“拱”。孔子主张以德治国，他认为统治者的个人行为和治国的大小举措都应当合乎道德，这样，就会像北极星那样，居于一定的方位，群星都环绕在它的周围运行。\n\n与地球相对而言，北极星的位置是不变动的，但是天空无数星球却有条不紊地围绕着它运行，孔子仰望这一天象，心想人间的统治秩序如能这样就好了。他用北极星的隐喻表达一种无为而治的政治主张。他希望用北极星的隐喻，告诉统治者不要自作聪明，抛弃礼制，胡...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a6ff251899613caf3014", "shortContent": "人到老年，常常以深沉的感情回顾自己一生所走的道路，孔子这段著名的话语正是他在垂暮之年对自己一生的一个概括和总结。孔子一生经历了许多磨难，但是在他晚年时期，鲁国统治者把他视为国师，常到他府上问政咨询；他的弟子遍天下，有的已经在一些诸侯国担任要职；而在社会上，他被人们当成圣人，被公认为知识广博的学者。因此，我们在孔子回顾一生的话语中能够感受到他的欣慰之情。正像明代学者、政治家杨起元所说：“圣人履历，从...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a6ff251899613caf3015", "shortContent": "“周”是合群的意思，“比”意为勾结。这两个字都有关系好的意思，但是，“周”有周遍的含义，就是说不与一些人特别密切，而同另外一些人有意疏远。也就是没有宗派主义，不党同伐异，而“比”表示两者靠得特别紧，关系特别密切，因此在这句话中就有勾结的含义。\n\n孔子用“周”与“比”来概括君子之交与小人之交的根本区别，来规定有道德的人应当遵循的交友之道。“周”与“比”之间的不同首先表现在是以坦诚、友好、善意的态度对...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "6305a56ff6542516c6dee7a5", "bookTitle": "诸子百家名句鉴赏辞典", "articleId": "6305a6ff251899613caf3016", "shortContent": "孔子重视学是无人不知的，《论语》中我们到处可以看到学字，全书用得最多的概念就是仁、礼、学。但是，他同样也强调思维的重要性。学是了解别人的认识，思是寻求自己的认识。“君子求诸己，小人求诸人”（《卫灵公》）一句不仅是指反躬自问、依靠自己，而且也是要求在思想认识上得之于己，自我创新。他从来反对死读书，食古不化，所以提出“温故而知新”（《为政》）。从《论语》我们可以看到，他一直有意识地着力培养学生的思维能...", "authors": [], "pressName": "上海辞书出版社"}, {"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b420d30675327e12449cd", "shortContent": "孔子一生从事的实践活动，主要有两类：一是政治活动，另一是教育活动。前者的时间比较短。在他五十岁的时候，曾任鲁国的中都宰、司空，后又升迁为司寇。孔子在五十五岁时被迫离开鲁国，开始长达十四年的周游列国的活动，宣传他的政治主张，但终不见用。他从事教育活动的时间相当长，经历了他一生中的三个时期。从“三十而立”到三十五岁期间，收受了最早的一批弟子；从三十七岁到五十岁期间，他的弟子已遍及各诸侯国；其后返鲁后的...", "authors": ["夏乃儒"], "pressName": "上海辞书出版社"}]', '', 'indent', 1586641166, '5e91c888e9e30d0008c66937', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (645005, '论语·雍也篇', NULL, 0, 327, 0, 1, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '子曰：“雍也可使南面。”
仲弓问子桑伯子，子曰：“可也，简。”仲弓曰：“居敬而行简，以临其民，不亦可乎？居简而行简，无乃大简乎？”子曰：“雍之言然。”
哀公问：“弟子孰为好学？”孔子对曰：“有颜回者好学，不迁怒，不贰过，不幸短命死矣，今也则亡，未闻好学者也。”
子华使于齐，冉子为其母请粟，子曰：“与之釜。”请益，曰：“与之庾。”冉子与之粟五秉。子曰：“赤之适齐也，乘肥马，衣轻裘。吾闻之也，君子周急不继富。”
原思为之宰，与之粟九百，辞。子曰：“毋，以与尔邻里乡党乎！”
子谓仲弓曰：“犁牛之子骍且角，虽欲勿用，山川其舍诸？”
子曰：“回也，其心三月不违仁，其余则日月至焉而已矣。”
季康子问：“仲由可使从政也与？”子曰：“由也果，于从政乎何有？”曰：“赐也可使从政也与？”曰：“赐也达，于从政乎何有？”曰：“求也可使从政也与？”曰：“求也艺，于从政乎何有？”
季氏使闵子骞为费宰，闵子骞曰：“善为我辞焉。如有复我者，则吾必在汶上矣。”
伯牛有疾，子问之，自牖执其手，曰：“亡之，命矣夫！斯人也而有斯疾也！斯人也而有斯疾也！”
子曰：“贤哉回也！一箪食，一瓢饮，在陋巷，人不堪其忧，回也不改其乐。贤哉，回也！”
冉求曰：“非不说子之道，力不足也。”子曰：“力不足者，中道而废，今女画。”
子谓子夏曰：“女为君子儒，无为小人儒。”
子游为武城宰，子曰：“女得人焉尔乎？”曰：“有澹台灭明者，行不由径，非公事，未尝至于偃之室也。”
子曰：“孟之反不伐，奔而殿，将入门，策其马曰：‘非敢后也，马不进也。’”
子曰：“不有祝鮀之佞，而有宋朝之美，难乎免于今之世矣。”
子曰：“谁能出不由户？何莫由斯道也？”
子曰：“质胜文则野，文胜质则史。文质彬彬，然后君子。”
子曰：“人之生也直，罔之生也幸而免。”
子曰：“知之者不如好之者；好之者不如乐之者。”
子曰：“中人以上，可以语上也；中人以下，不可以语上也。”
樊迟问知，子曰：“务民之义，敬鬼神而远之，可谓知矣。”问仁，曰：“仁者先难而后获，可谓仁矣。”
子曰：“知者乐水，仁者乐山。知者动，仁者静。知者乐，仁者寿。”
子曰：“齐一变至于鲁，鲁一变至于道。”
子曰：“觚不觚，觚哉！觚哉！”
宰我问曰：“仁者，虽告之曰：‘井有仁焉。’其从之也？”子曰：“何为其然也？君子可逝也，不可陷也；可欺也，不可罔也。”
子曰：“君子博学于文，约之以礼，亦可以弗畔矣夫。”
子见南子，子路不说，夫子矢之曰：“予所否者，天厌之！天厌之！”
子曰：“中庸之为德也，其至矣乎！民鲜久矣。”
子贡曰：“如有博施于民而能济众，何如？可谓仁乎？”子曰：“何事于仁，必也圣乎！尧、舜其犹病诸！夫仁者，己欲立而立人，己欲达而达人。能近取譬，可谓仁之方也已。”', '', '', '孔子说：“冉雍这个人，可以让他去做官。”
仲弓问孔子：子桑伯子这个人怎么样。孔子说：“此人还可以，办事简要而不烦琐。”仲弓说：“居心恭敬严肃而行事简要，像这样来治理百姓，不是也可以吗？（但是）自己马马虎虎，又以简要的方法办事，这岂不是太简单了吗？”孔子说：“冉雍，这话你说得对。”
鲁哀公问孔子：“你的学生中谁是最好学的呢？”孔子回答说：“有一个叫颜回的学生好学，他从不迁怒于别人，也从不重犯同样的过错。不幸短命死了。现在没有那样的人了，没有听说谁是好学的。”
子华出使齐国，冉求替他的母亲向孔子请求补助一些谷米。孔子说：“给他六斗四升。”冉求请求再增加一些。孔子说：“再给他二斗四升。”冉求却给他八十斛。孔子说：“公西赤到齐国去，乘坐着肥马驾的车子，穿着又暖和又轻便的皮袍。我听说过，君子只是周济急需救济的人，而不是周济富人的人。”
原思给孔子家当总管，孔子给他俸米九百，原思推辞不要。孔子说：“不要推辞。（如果有多的，）给你的乡亲们吧。”
孔子在评论仲弓的时候说：“耕牛产下的牛犊长着红色的毛，角也长得整齐端正，人们虽想不用它做祭品，但山川之神难道会舍弃它吗？”
孔子说：“颜回这个人，他的心可以在长时间内不离开仁德，其余的学生则只能在短时间内做到仁而已。”
季康子问孔子：“仲由这个人，可以让他管理国家政事吗？”孔子说：“仲由做事果断，对于管理国家政事有什么困难呢？”季康子又问：“端木赐这个人，可以让他管理国家政事吗？”孔子说：“端木赐通达事理，对于管理政事有什么困难呢？“又问：“冉求这个人，可以让他管理国家政事吗？”孔子说：“冉求有才能，对于管理国家政事有什么困难呢？”
季氏派人请闵子骞去做费邑的长官，闵子骞（对来请他的人）说：“请你好好替我推辞吧！如果再来召我，那我一定跑到汶水那边去了。”
伯牛病了，孔子前去探望他，从窗户外面握着他的手说：“丧失了这个人，这是命里注定的吧！这样的人竟会得这样的病啊，这样的人竟会得这样的病啊！”
孔子说：“颜回的品质是多么高尚啊！一箪饭，一瓢水，住在简陋的小屋里，别人都忍受不了这种穷困清苦，颜回却没有改变他好学的乐趣。颜回的品质是多么高尚啊！”
冉求说：“我不是不喜欢老师您所讲的道，而是我的能力不够呀。”孔子说：“能力不够是到半路才停下来，现在你是自己给自己划了界限不想前进。”
孔子对子夏说：“你要做君子儒，不要做小人儒。”
子游做了武城的长官。孔子说：“你在那里是到了人才没有？”。子游回答说：“有一个叫澹台灭明的人，从来不走邪路，没有公事从不到我屋子里来。”
孔子说：“孟之反不喜欢夸耀自己。败退的时候，他留在最后掩护全军。快进城门的时候，他鞭打着自己的马说，‘不是我敢于殿后，是马跑得不快。’”
孔子说：“如果没有祝鮀那样的口才，只有宋朝的美貌，那在今天的社会上处世立足就比较艰难了。”
孔子说：“谁能不经过屋门而走出去呢？为什么没有人走（我所指出的）这条道路呢？”
孔子说：“质朴多于文采，就像个乡下人，流于粗俗：文采多于质朴，就流于虚伪、浮夸。只有质朴和文采配合恰当，才是个君子。”
孔子说：“一个人的生存是由于正直，而不正直的人也能生存，那只他侥幸地避免了灾祸。”
孔子说：“懂得它的人，不如爱好它的人；爱好它的人，又不如以它为乐的人。”
孔子说：“具有中等以上才智的人，可以给他讲授高深的学问，在中等水平以下的人，不可以给他讲高深的学问。”
樊迟问孔子怎样才算是智，孔子说：“专心致力于（提倡）老百姓应该遵从的道德，尊敬鬼神但要远离它，就可以说是智了。”樊迟又问怎样才是仁，孔子说：“仁人对难做的事，做在人前面，有收获的结果，他得在人后，这可以说是仁了。”
孔子说：“聪明人喜爱水，有仁德者喜爱山；聪明人活动，仁德者沉静。聪明人快乐，有仁德者长寿。”
孔子说：“齐国一改变，可以达到鲁国这个样子，鲁国一改变，就可以达到先王之道了。”
孔子说：“觚不像个觚了，这也算是觚吗？这也算是觚吗？”
宰我问道：“对于有仁德的人，别人告诉他井里掉下去一位仁人啦，他会跟着下去吗？”孔子说：“为什么要这样做呢？君子可以到井边去救，却不可以陷入井中；君子可能被欺骗，但不可能被迷惑。”
孔子说：“君子广泛地学习古代的文化典籍，又以礼来约束自己，也就可以不离经叛道了。”
孔子去见南子，子路不高兴。孔子发誓说：“如果我做什么不正当的事，让上天谴责我吧！让上天谴责我吧！”
孔子说：“中庸作为一种道德，该是最高的了吧！人们缺少这种道德已经为时很久了。”
子贡说：“假若有一个人，他能给老百姓很多好处又能周济大众，怎么样？可以算是仁人了吗？”孔子说：“岂止是仁人，简直是圣人了！就连尧、舜尚且难以做到呢。至于仁人，就是要想自己站得住，也要帮助人家一同站得住；要想自己过得好，也要帮助人家一同过得好。凡事能就近以自己作比，而推己及人，可以说就是实行仁的方法了。”', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b42d3b5420e2767ee8ad7", "shortContent": "本篇上半部分接上篇，继续评论弟子。不过讨论的重心开始移向对人生价值理想的探求，并一直延续到篇末。\n\n孔子开创的儒家学派，所树立的人格品德最高的典范是“圣人”。可是在孔子那里，“圣人”只是一个虚悬的理想。除了历史上的尧、舜、禹、周文王、周公之外，很难找到可称为圣人的人。当然孔子也否认自己是圣人。当子贡问到“如有博施于民而能济众”可否称为已达到了“仁”的标准了，孔子回答他这何止于仁，“必也圣乎”（第三...", "authors": ["夏乃儒"], "pressName": "上海辞书出版社"}]', '', 'indent', 1586641300, '5e91c910857cc30006c4968b', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (645006, '论语·述而篇', NULL, 0, 327, 0, 1, '孔子', NULL, 10027, '57b902900a2b58005c924bd0', '周', 'wen', '文', '', '', '子曰：“述而不作，信而好古，窃比于我老彭。”
子曰：“默而识之，学而不厌，诲人不倦，何有于我哉？”
子曰：“德之不修，学之不讲，闻义不能徙，不善不能改，是吾忧也。”
子之燕居，申申如也，夭夭如也。
子曰：“甚矣吾衰也！久矣吾不复梦见周公。”
子曰：“志于道，据于德，依于仁，游于艺。”
子曰：“自行束脩以上，吾未尝无诲焉。”
子曰：“不愤不启，不悱不发，举一隅不以三隅反，则不复也。”
子食于有丧者之侧，未尝饱也。
子于是日哭，则不歌。
子谓颜渊曰：“用之则行，舍之则藏，惟我与尔有是夫！”子路曰：“子行三军，则谁与？”子曰：“暴虎冯河，死而无悔者，吾不与也。必也临事而惧，好谋而成者也。”
子曰：“富而可求也，虽执鞭之士，吾亦为之。如不可求，从吾所好。”
子之所慎：齐，战，疾。
子在齐闻《韶》，三月不知肉味，曰：“不图为乐之至于斯也。”
冉有曰：“夫子为卫君乎？”子贡曰：“诺，吾将问之。”入，曰：“伯夷、叔齐何人也？”曰：“古之贤人也。”曰：“怨乎？”曰：“求仁而得仁，又何怨？”出，曰：“夫子不为也。”
子曰：“饭疏食饮水，曲肱而枕之，乐亦在其中矣。不义而富且贵，于我如浮云。”
子曰：“加我数年，五十以学《易》，可以无大过矣。”
子所雅言，《诗》、《书》、执礼，皆雅言也。
叶公问孔子于子路，子路不对。子曰：“女奚不曰：其为人也，发愤忘食，乐以忘忧，不知老之将至云尔。”
子曰：“我非生而知之者，好古，敏以求之者也。”
子不语怪、力、乱、神。
子曰：“三人行，必有我师焉。择其善者而从之，其不善者而改之。”
子曰：“天生德于予，桓魋其如予何？”
子曰：“二三子以我为隐乎？吾无隐乎尔！吾无行而不与二三子者，是丘也。”
子以四教：文，行，忠，信。
子曰：“圣人，吾不得而见之矣；得见君子者斯可矣。”子曰：“善人，吾不得而见之矣，得见有恒者斯可矣。亡而为有，虚而为盈，约而为泰，难乎有恒乎。”
子钓而不纲，弋不射宿。
子曰：“盖有不知而作之者，我无是也。多闻，择其善者而从之；多见而识之，知之次也。”
互乡难与言，童子见，门人惑。子曰：“与其进也，不与其退也，唯何甚？人洁己以进，与其洁也，不保其往也。”
子曰：“仁远乎哉？我欲仁，斯仁至矣。”
陈司败问：“昭公知礼乎？”孔子曰：“知礼。”孔子退，揖巫马期而进之，曰：“吾闻君子不党，君子亦党乎？君取于吴，为同姓，谓之吴孟子。君而知礼，孰不知礼？”巫马期以告，子曰：“丘也幸，苟有过，人必知之。”
子与人歌而善，必使反之，而后和之。
子曰：“文，莫吾犹人也。躬行君子，则吾未之有得。”
子曰：“若圣与仁，则吾岂敢？抑为之不厌，诲人不倦，则可谓云尔已矣。”公西华曰：“正唯弟子不能学也。”
子疾病，子路请祷。子曰：“有诸？”子路对曰：“有之。《诔》曰：‘祷尔于上下神祇。’”子曰：“丘之祷久矣。”
子曰：“奢则不孙，俭则固。与其不孙也，宁固。”
子曰：“君子坦荡荡，小人长戚戚。”
子温而厉，威而不猛，恭而安。', '', '', '孔子说：“只阐述而不创作，相信而且喜好古代的东西，我私下把自己比做老彭。”
孔子说：“默默地记住（所学的知识），学习不觉得厌烦，教人不知道疲倦，这对我能有什么因难呢？”
孔子说：“（许多人）对品德不去修养，学问不去讲求，听到义不能去做，有了不善的事不能改正，这些都是我所忧虑的事情。”
孔子闲居在家里的时候，衣冠楚楚，仪态温和舒畅，悠闲自在。
孔子说：“我衰老得很厉害了，我好久没有梦见周公了。”
孔子说：“以道为志向，以德为根据，以仁为凭藉，活动于（礼、乐等）六艺的范围之中。”
孔子说：“只要自愿拿着十余干肉为礼来见我的人，我从来没有不给他教诲的。”
孔子说：“教导学生，不到他想弄明白而不得的时候，不去开导他；不到他想出来却说不出来的时候，不去启发他。教给他一个方面的东西，他却不能由此而推知其他三个方面的东西，那就不再教他了。”
孔子在有丧事的人旁边吃饭，不曾吃饱过。
孔子在这一天为吊丧而哭泣，就不再唱歌。
孔子对颜渊说：“用我呢，我就去干；不用我，我就隐藏起来，只有我和你才能做到这样吧！”子路问孔子说：“老师您如果统帅三军，那么您和谁在一起共事呢？”孔子说：“赤手空拳和老虎搏斗，徒步涉水过河，死了都不会后悔的人，我是不会和他在一起共事的。我要找的，一定要是遇事小心谨慎，善于谋划而能完成任务的人。”
孔子说：“如果富贵合乎于道就可以去追求，虽然是给人执鞭的下等差事，我也愿意去做。如果富贵不合于道就不必去追求，那就还是按我的爱好去干事。”
孔子所谨慎小心对待的是斋戒、战争和疾病这三件事。
孔子在齐国听到了《韶》乐，有很长时间尝不出肉的滋味，他说，“想不到《韶》乐的美达到了这样迷人的地步。”
冉有（问子贡）说：“老师会帮助卫国的国君吗？”子贡说：“嗯，我去问他。”于是就进去问孔子：“伯夷、叔齐是什么样的人呢？”（孔子）说：“古代的贤人。”（子贡又）问：“他们有怨恨吗？”（孔子）说：“他们求仁而得到了仁，为什么又怨恨呢？”（子贡）出来（对冉有）说：“老师不会帮助卫君。”
孔子说：“吃粗粮，喝白水，弯着胳膊当枕头，乐趣也就在这中间了。用不正当的手段得来的富贵，对于我来讲就像是天上的浮云一样。”
孔子说：“再给我几年时间，到五十岁学习《易》，我便可以没有大的过错了。”
孔子有时讲雅言，读《诗》、念《书》、赞礼时，用的都是雅言。
叶公向子路问孔子是个什么样的人，子路不答。孔子（对子路）说：“你为什么不样说，他这个人，发愤用功，连吃饭都忘了，快乐得把一切忧虑都忘了，连自己快要老了都不知道，如此而已。”
孔子说：“我不是生来就有知识的人，而是爱好古代的东西，勤奋敏捷地去求得知识的人。”
孔子不谈论怪异、暴力、变乱、鬼神。
孔子说：“三个人一起走路，其中必定有人可以作我的老师。我选择他善的品德向他学习，看到他不善的地方就作为借鉴，改掉自己的缺点。”
孔子说：“上天把德赋予了我，桓魋能把我怎么样？”
孔子说：“学生们，你们以为我对你们有什么隐瞒的吗？我是丝毫没有隐瞒的。我没有什么事不是和你们一起干的。我孔丘就是这样的人。”
孔子以文、行、忠、信四项内容教授学生。
孔子说：“圣人我是不可能看到了，能看到君子，这就可以了。”孔子又说：“善人我不可能看到了，能见到始终如一（保持好的品德的）人，这也就可以了。没有却装作有，空虚却装作充实，穷困却装作富足，这样的人是难于有恒心（保持好的品德）的。”
孔子只用（有一个鱼钩）的钓竿钓鱼，而不用（有许多鱼钩的）大绳钓鱼。只射飞鸟，不射巢中歇宿的鸟。
孔子说：“有这样一种人，可能他什么都不懂却在那里凭空创造，我却没有这样做过。多听，选择其中好的来学习；多看，然后记在心里，这是次一等的智慧。”
（孔子认为）很难与互乡那个地方的人谈话，但互乡的一个童子却受到了孔子的接见，学生们都感到迷惑不解。孔子说：“我是肯定他的进步，不是肯定他的倒退。何必做得太过分呢？人家改正了错误以求进步，我们肯定他改正错误，不要死抓住他的过去不放。”
孔子说：“仁难道离我们很远吗？只要我想达到仁，仁就来了。”
陈司败问：“鲁昭公懂得礼吗？”孔子说：“懂得礼。”孔子出来后，陈司败向巫马其作了个揖，请他走近自己，对他说：“我听说，君子是没有偏私的，难道君子还包庇别人吗？鲁君在吴国娶了一个同姓的女子为做夫人，是国君的同姓，称她为吴孟子。如果鲁君算是知礼，还有谁不知礼呢？”巫马期把这句话告诉了孔子。孔子说：“我真是幸运。如果有错，人家一定会知道。”
孔子与别人一起唱歌，如果唱得好，一定要请他再唱一遍，然后和他一起唱。
孔子说：“就书本知识来说，大约我和别人差不多，做一个身体力行的君子，那我还没有做到。”
孔子说：“如果说到圣与仁，那我怎么敢当！不过（向圣与仁的方向）努力而不感厌烦地做，教诲别人也从不感觉疲倦，则可以这样说的。”公西华说：“这正是我们学不到的。”
孔子病情严重，子路向鬼神祈祷。孔子说：“有这回事吗？”子路说：“有的。《诔》文上说：‘为你向天地神灵祈祷。’”孔子说：“我很久以来就在祈祷了。”
孔子说：“奢侈了就会越礼，节俭了就会寒酸。与其越礼，宁可寒酸。
孔子说：“君子心胸宽广，小人经常忧愁。”
孔子温和而又严厉，威严而不凶猛，庄重而又安祥。', '[{"bookId": "645fbfe47da2f75ac7d3e5a2", "bookTitle": "四书五经鉴赏辞典（新一版）", "articleId": "647b42f6b1076d5863787306", "shortContent": "本篇有两个重点：孔子的自我评价和孔子的教育思想。关于孔子对自己的评价，在别的篇章中也有所见，但是不如本篇如此集中地记载。关于孔子的教育思想部分，可以看作是对第二篇有关部分的继续展开。\n\n历史上对孔子的评价，有时褒，有时贬。其中有不少背离了实事求是精神。其中原因很多，不过有一点是共同的——全然不顾孔子曾多次作过的自我评价，造成了评论偏颇，就毫不奇怪了。\n\n本篇中孔子对自己评价可分为五类：\n\n第一类，...", "authors": ["夏乃儒"], "pressName": "上海辞书出版社"}]', '', 'indent', 1586641357, '5e91c948b92fdd0006b2580f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (645040, '黄帝内经 · 素问 · 上古天真论', NULL, 19, 496, 2, 1, '无名氏', NULL, 10100, '57b959c18ac2470062e2a00f', '汉', 'wen', '文', '黄帝内经', '', '昔在黄帝，生而神灵，弱而能言，幼而徇齐，长而敦敏，成而登天。
乃问于天师曰：余闻上古之人，春秋皆度百岁，而动作不衰；今时之人，年半百而动作皆衰者，时世异耶？人将失之耶？
岐伯对曰：上古之人，其知道者，法于阴阳，和于术数，食饮有节，起居有常，不妄作劳，故能形与神俱，而尽终其天年，度百岁乃去。
今时之人不然也，以酒为浆，以妄为常，醉以入房，以欲竭其精，以耗散其真，不知持满，不时御神，务快其心，逆于生乐，起居无节，故半百而衰也。
夫上古圣人之教下也，皆谓之虚邪贼风，避之有时，恬惔虚无，真气从之，精神内守，病安从来。
是以志闲而少欲，心安而不惧，形劳而不倦，气从以顺，各从其欲，皆得所愿。
故美其食，任其服，乐其俗，高下不相慕，其民故曰朴。
是以嗜欲不能劳其目，淫邪不能惑其心，愚智贤不肖，不惧于物，故合于道。
所以能年皆度百岁而动作不衰者，以其德全不危也。
帝曰：人年老而无子者，材力尽邪？将天数然也？
岐伯曰：女子七岁，肾气盛，齿更发长。
二七，而天癸至，任脉通，太冲脉盛，月事以时下，故有子。
三七，肾气平均，故真牙生而长极。
四七，筋骨坚，发长极，身体盛壮。
五七，阳明脉衰，面始焦，发始堕。
六七，三阳脉衰于上，面皆焦，发始白。
七七，任脉虚，太冲脉衰少，天癸竭，地道不通，故形坏而无子也。
丈夫八岁，肾气实，发长齿更。
二八，肾气盛，天癸至，精气溢泻，阴阳和，故能有子。
三八，肾气平均，筋骨劲强，故真牙生而长极。
四八，筋骨隆盛，肌肉满壮。
五八，肾气衰，发堕齿槁。
六八，阳气衰竭于上，面焦，发鬓颁白。
七八，肝气衰，筋不能动，天癸竭，精少，肾脏衰，形体皆极。
八八，天癸竭，精少，肾脏衰，形体皆极，则齿发去。
肾者主水，受五脏六腑之精而藏之，故五脏盛，乃能泻。
今五脏皆衰，筋骨解堕，天癸尽矣，故发鬓白，身体重，行步不正，而无子耳。
帝曰：有其年已老，而有子者，何也？
岐伯曰：此其天寿过度，气脉常通，而肾气有余也。此虽有子，男子不过尽八八，女子不过尽七七，而天地之精气皆竭矣。
帝曰：夫道者年皆百岁，能有子乎？
岐伯曰：夫道者能却老而全形，身年虽寿，能生子也。
黄帝曰：余闻上古有真人者，提挈天地，把握阴阳，呼吸精气，独立守神，肌肉若一，故能寿敝天地，无有终时，此其道生。
中古之时，有至人者，淳德全道，和于阴阳，调于四时，去世离俗，积精全神，游行天地之间，视听八达之外，此盖益其寿命而强者也，亦归于真人。
其次有圣人者，处天地之和，从八风之理，适嗜欲于世俗之间，无恚嗔之心，行不欲离于世，被服章，举不欲观于俗，外不劳形于事，内无思想之患，以恬愉为务，以自得为功，形体不敝，精神不散，亦可以百数。
其次有贤人者，法则天地，象似日月，辨列星辰，逆从阴阳，分别四时，将从上古合同于道，亦可使益寿而有极时。', '', '', '', NULL, '', 'indent', 1586772249, '5e93c894c769230008e4d29a', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (645949, '将苑 · 卷一 · 将志', NULL, 0, 60, 1, 1, '诸葛亮', NULL, 10026, '57b8f8452e958a005fa50d86', '三国', 'wen', '文', '将苑', '', '兵者凶器，将者危任，是以器刚则缺，任重则危。故善将者，不恃强，不怙势，宠之而不喜，辱之而不惧，见利不贪，见美不淫，以身殉国，壹意而已。', '', '', '兵器是一种凶器，统兵为将是一种重大的责任。兵器刚硬，容易缺损，将领任务重大所以有风险。因此，真正的将帅不以自己的部队强大有威势做靠山，当他受到君主的宠爱时不得意忘形，当他受到别人的诽谤污辱时，也不惧怕、退缩，看到利益时不起贪念，见到美女时更不心生邪念，只知全心全意，保家卫国，以身殉职。', NULL, '', 'indent', 1588354438, '5eabed033ecb810007dffba1', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (645041, '黄帝内经 · 素问 · 四气调神大论', NULL, 2, 496, 2, 1, '无名氏', NULL, 10100, '57b959c18ac2470062e2a00f', '汉', 'wen', '文', '黄帝内经', '', '春三月，此为发陈。天地俱生，万物以荣，夜卧早起，广步于庭，被发缓形，以使志生，生而勿杀，予而勿夺，赏而勿罚，此春气之应，养生之道也；逆之则伤肝，夏为寒变，奉长者少。
夏三月，此为蕃秀。天地气交，万物华实，夜卧早起，无厌于日，使志勿怒，使华英成秀，使气得泄，若所爱在外，此夏气之应，养长之道也；逆之则伤心，秋为痎疟，奉收者少，冬至重病。
秋三月，此谓容平。天气以急，地气以明，早卧早起，与鸡俱兴，使志安宁，以缓秋刑，收敛神气，使秋气平，无外其志，使肺气清，此秋气之应，养收之道也；逆之则伤肺，冬为飧泄，奉藏者少。
冬三月，此为闭藏。水冰地坼，勿扰乎阳，早卧晚起，必待日光，使志若伏若匿，若有私意，若已有得，去寒就温，无泄皮肤，使气极夺。此冬气之应，养藏之道也；逆之则伤肾，春为痿厥，奉生者少。
天气清净，光明者也，藏德不止，故不下也。
天明则日月不明，邪害空窍。
阳气者闭塞，地气者冒明，云雾不精，则上应白露不下。
交通不表，万物命故不施，不施则名木多死。
恶气不发，风雨不节，白露不下，则菀不荣。
贼风数至，暴雨数起，天地四时不相保，与道相失，则未央绝灭。
唯圣人从之，故身无奇病，万物不失，生气不竭。
逆春气则少阳不生，肝气内变。
逆夏气则太阳不长，心气内洞。
逆秋气则太阴不收，肺气焦满。
逆冬气则少阴不藏，肾气独沉。
夫四时阴阳者，万物之根本也。所以圣人春夏养阳，秋冬养阴，以从其根；故与万物沉浮于生长之门。逆其根则伐其本，坏其真矣。
故阴阳四时者，万物之终始也；生死之本也；逆之则灾害生，从之则苛疾不起，是谓得道。
道者，圣人行之，愚者佩之。从阴阳则生，逆之则死；从之则治，逆之则乱。反顺为逆，是谓内格。
是故圣人不治已病，治未病；不治已乱，治未乱，此之谓也。夫病已成而后药之，乱已成而后治之，譬犹渴而穿井，斗而铸锥，不亦晚乎？', '', '', '', NULL, '', 'indent', 1586772368, '5e93c90bd9f50d00083698f0', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (645045, '黄帝内经 · 素问 · 阴阳应象大论', NULL, 25, 496, 3, 1, '无名氏', NULL, 10100, '57b959c18ac2470062e2a00f', '汉', 'wen', '文', '黄帝内经', '', '黄帝曰：阴阳者，天地之道也，万物之纲纪，变化之父母，生杀之本始，神明之府也。
治病必求于本。
故积阳为天，积阴为地。阴静阳燥，阳生阴长，阳杀阴藏，阳化气，阴成形。
寒极生热，热极生寒，寒气生浊，热气生清。清气在下，则生飧泄；浊气在上，则生（月真）胀。此阴阳反作，病之逆从也。
故清阳为天，浊阴为地；地气上为云，天气下为雨；雨出地气，云出天气。
故清阳出上窍，浊阴出下窍；清阳发腠理，浊阴走五脏；清阳实四肢，浊阴归六腑。
水为阴，火为阳；阳为气，阴为味。
味归形，形归气，气归精，精归化，精食气，形食味，化生精，气生形。
味伤形，气伤精；精化为气，气伤于味。
阴味出下窍；阳气出上窍。
味厚者为阴，薄为阴之阳。气厚者为阳，薄为阳之阴。
味厚则泄，薄则通。气薄则发泄，厚则发热。
壮火之气衰，少火之气壮。壮火食气，气食少火。壮火散气，少火生气。
气味，辛甘发散为阳，酸苦涌泄为阴。
阴胜则阳病，阳胜则阴病。阳胜则热，阴胜则寒。重寒则热，重热则寒。
寒伤形，热伤气。气伤痛，形伤肿。故先痛而后肿者，气伤形也，先肿而后痛者，形伤气也。
风胜则动，热胜则肿，燥胜则干，寒胜则浮，湿胜则濡泻。
天有四时五行，以生长收藏，以生寒暑燥湿风。人有五脏化五气，以生喜怒悲忧恐。
故喜怒伤气，寒暑伤形。
暴怒伤阴，暴喜伤阳。
厥气上行，满脉去形。
喜怒不节，寒暑过度，生乃不固。
故重阴必阳，重阳必阴。
故曰：冬伤于寒，春必温病；春伤于风，夏生飧泄；夏伤于暑，秋必痎疟；秋伤于湿，冬生咳嗽。
帝曰：余闻上古圣人，论理人形，列别脏腑，端络经脉，会通六合，各从其经，气穴所发，各有处名，溪谷属骨，皆有所起。分部逆从，各有条理。四时阴阳，尽有经纪。外内之应，皆有表里，其信然乎。
岐伯对曰：
东方生风，风生木，木生酸，酸生肝，肝生筋，筋生心，肝主目。其在天为玄，在人为道，在地为化。化生五味，道生智，玄生神，神在天为风，在地为木，在体为筋，在脏为肝。在色为苍，在音为角，在声为呼，在变动为握，在窍为目，在味为酸，在志为怒。怒伤肝，悲胜怒，风伤筋，燥胜风，酸伤筋，辛胜酸。
南方生热，热生火，火生苦，苦生心，心生血，血生脾，心主舌。其在天为热，在地为火，在体为脉，在脏为心，在色为赤，在音为征，在声为笑，在变动为忧，在窍为舌，在味为苦，在志为喜。喜伤心，恐胜喜，热伤气，寒胜热，苦伤气，咸胜苦。
中央生湿，湿生土，土生甘，甘生脾，脾生肉，肉生肺，脾主口。其在天为湿，在地为土，在体为肉，在脏为脾，在色为黄，在音为宫，在声为歌，在变动为哕，在窍为口，在味为甘，在志为思。思伤脾，怒胜思，湿伤肉，风胜湿，甘伤肉，酸胜甘。
西方生燥，燥生金，金生辛，辛生肺，肺生皮毛，皮毛在肾，肺主鼻。其在天为燥，在地为金，在体为皮毛，在脏为肺，在色为白，在音为商，在声为哭，在变动为咳，在窍为鼻，在味为辛，在志为忧。忧伤肺，喜胜忧，热伤皮毛，寒胜热，辛伤皮毛，苦胜辛。
北方生寒，寒生水，水生咸，咸生肾，肾生骨髓，髓生肝，肾主耳。其在天为寒，在地为水，在体为骨，在脏为肾，在色为黑，在音为羽，在声为呻，在变动为栗，在窍为耳，在味为咸，在志为恐。恐伤肾，思胜恐，寒伤血，燥胜寒，咸伤血，甘胜咸。
故曰：天地者，万物之上下也；阴阳者，血气之男女也；左右者，阴阳之道路也；水火者，阴阳之征兆也；阴阳者，万物之能始也。
故曰：阴在内，阳之守也，阳在外，阴之使也。
帝曰：法阴阳奈何？
岐伯曰：阳盛则身热，腠理闭，喘粗为之俯抑，汗不出而热，齿干，以烦冤腹满死，能冬不能夏。
阴胜则身寒，汗出身长清，数栗而寒，寒则厥，厥则腹满死，能夏不能冬。此阴阳更胜之变，病之形能也。
帝曰：调此二者，奈何？
岐伯曰：能知七损八益，则二者可调，不知用此，则早衰之节也。
年四十，而阴气自半也，起居衰矣。年五十，体重，耳目不聪明矣。年六十，阴痿，气大衰，九窍不利，下虚上实，涕泣俱出矣。
故曰：知之则强，不知则老，故同出而名异耳。智者察同，愚者察异，愚者不足，智者有余，有余而耳目聪明，身体强健，老者复壮，壮者益治。
是以圣人为无为之事，乐恬憺之能，从欲快志于虚无之守，故寿命无穷，与天地终，此圣人之治身也。
天不足西北，故西北方阴也，而人右耳目不如左明也。地不满东南，故东南方阳也，而人左手足不如右强也。
帝曰：何以然？
岐伯曰：东方阳也，阳者其精并于上，并于上则上明而下虚，故使耳目聪明而手足不便。西方阴也，阴者其精并于下，并于下则下盛而上虚，故其耳目不聪明而手足便也。故俱感于邪，其在上则右甚，在下则左甚，此天地阴阳所不能全也，故邪居之。
故天有精，地有形，天有八纪，地有五理，故能为万物之父母。
清阳上天，浊阴归地，是故天地之动静，神明为之纲纪，故能以生长收藏，终而复始。
惟贤人上配天以养头，下象地以养足，中傍人事以养五脏。
天地通于肺，地气通于嗌，风气通于肝，雷气通于心，谷气通于脾，雨气通于肾。
六经为川，肠胃为海，九窍为水注之气。
以天地为之阴阳，阳之汗以天地之雨名之；阳之气以天地之疾风名之。暴气象雷，逆气象阳。
故治不法天之纪，不用地之理，则灾害至矣。
故邪风之至，疾如风雨，故善治者治皮毛，其次治肌肤，其次治筋脉，其次治六腑，其次治五脏。治五脏者，半死半生也。
故天之邪气感，则害人五脏；水谷之寒热感，则害于六腑；地之湿气感，则害皮肉筋脉。
故善用针者，从阴引阳，从阳引阴，以右治左，以左治右，以我知彼，以表知里，以观过与不及之理，见微得过，用之不殆。
善诊者，察色按脉，先别阴阳，审清浊而知部分；视喘息，听音声，而知所苦；观权衡规矩，而知病所主；按尺寸，观浮沉滑涩，而知病所生。以治无过，以诊则不失矣。
故曰：病之始起也，可刺而已；其盛，可待衰而已。
故因其轻而扬之，因其重而减之，因其衰而彰之。
形不足者，温之以气；精不足者，补之以味。
其高者，因而越之；其下者，引而竭之；中满者，泻之于内。
其有邪者，渍形以为汗；其在皮者，汗而发之；其栗悍者，按而收之，其实者，散而泻之。
审其阴阳，以别柔刚。
阳病治阴，阴病治阳。
定其血气，各守其乡。
血实宜决之，气虚宜掣引之。', '', '', '', NULL, '', 'indent', 1586821357, '5e94881131060f0008c8d4ac', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (645107, '黄帝内经 · 素问 · 五运行大论', NULL, 0, 496, 1, 1, '无名氏', NULL, 10100, '57b959c18ac2470062e2a00f', '汉', 'wen', '文', '黄帝内经', '', '黄帝坐明堂，始正天纲，临观八极，考建五常。请天师而问之曰：论言天地之动静，神明为之纪；阴阳之升降，寒暑彰其兆。余闻五运之数于夫子，夫子之所言，正五气之各主岁耳，首甲定运，余因论之。鬼臾区曰：“土主甲己，金主乙庚，水主丙辛，木主丁壬，火主戊癸。子午之上，少阴主之；丑未之上，太阴主之；寅申之上，少阳主之；卯酉之上，阳明主之；辰戌之上，太阳主之；巳亥之上，厥阴主之。”不合阴阳，其故何也？
岐伯曰：是明道也。此天地之阴阳也。夫数之可数者，人中之阴阳也。然所合，数之可得者也。夫阴阳者，数之可十，推之可百，数之可千，推之可万。天地阴阳者，不以数推，以象之谓也。
帝曰：愿闻其所始也。
岐伯曰：昭乎哉问也！臣览《太始天元册》文，丹天之气经于牛女戊分，黅天之气经于心尾己分，苍天之气经于危室柳鬼，素天之气经于亢氐昴毕，玄天之气经于张翼娄胃。所谓戊己分者，奎壁角轸，则天地之门户也。夫候之所始，道之所生，不可不通也。
帝曰：善。论言，天地者万物之上下，左右者阴阳之道路，未知其所谓也。
岐伯曰：所谓上下者，岁上下见阴阳之所在也。左右者，诸上，见厥阴，左少阴，右太阳；见少阴，左太阴，右厥阴；见太阴，左少阳，右少阴；见少阳，左阳明，右太阴；见阳明，左太阳，右少阳；见太阳，左厥阴，右阳明。所谓面北而定其位，言其见也。
帝曰：何谓下？
岐伯曰：厥阴在上，则少阳在下，左阳明，右太阴；少阴在上，则阳明在下，左太阳，右少阳；太阴在上，则太阳在下，左厥阴，右阳明；少阳在上，则厥阴在下，左少阴，右太阳；阳明在上，则少阴在下，左太阴，右厥阴；太阳在上，则太阴在下，左少阳，右少阴。所谓面南而命其位，言其见也。上下相遘，寒暑相临，气相得则和，不相得则病。
帝曰：气相得而病者，何也？
岐伯曰：以下临上，不当位也。
帝曰：动静何如？
岐伯曰：上者右行，下者左行，左右周天，余而复会也。
帝曰：予闻鬼臾区曰：“应地者静。”今夫子乃言下者左行，不知其所谓也。愿闻何以生之乎？
岐伯曰：天地动静，五行迁复，虽鬼臾区其上候而已，犹不能遍明。夫变化之用，天垂象，地成形，七曜纬虚，五行丽地。地者，所以载生成之形类也。虚者，所以列应天之精气也。形精之动，犹根本之与枝叶也。仰观其象，虽远可知也。
帝曰：地之为下否乎？
岐伯曰：地为人之下，太虚之中者也。
帝曰：凭乎？
岐伯曰：大气举之也。燥以干之，暑以蒸之，风以动之，湿以润之，寒以坚之，火以温之。故风寒在下，燥热在上，湿气在中，火游行其间，寒暑六入，故令虚而化生也。故燥胜则地干，暑胜则地热，风胜则地动，湿胜则地泥，寒胜则地裂，火胜则地固矣。
帝曰：天地之气，何以候之？
岐伯曰：天地之气，胜复之作，不形于诊也。《脉法》曰：“天地之变，无以脉诊。”此之谓也。
帝曰：间气何如？
岐伯曰：随气所在，期于左右。
帝曰：期之奈何？
岐伯曰：从其气则和，逢其气则病。不当其位者病，迭移其位者病，失守其位者危，尺寸反者死，阴阳交者死。先立其年，以知其气，左右应见，然后乃可以言死生之逆顺。
帝曰：寒暑燥湿风火，在人合之奈何？其于万物何以生化？
岐伯曰：东方生风，风生木，木生酸，酸生肝，肝生筋，筋生心。其在天为玄，在人为道，在地为化。化生五味，道生智，玄生神，化生气。神在天为风，在地为木，在体为筋，在气为柔，在脏为肝。其性为暄，其德为和，其用为动，其色为苍，其化为荣，其虫毛，其政为散，其令宣发，其变摧拉，其眚为陨，其味为酸，其志为怒。怒伤肝，悲胜怒；风伤肝，燥胜风；酸伤筋，辛胜酸。
南方生热，热生火，火生苦，苦生心，心生血，血生脾。其在天为热，在地为火，在体为脉，在气为息，在脏为心。其性为暑，其德为显，其用为躁，其色为赤，其化为茂，其虫羽，其政为明，其令郁蒸，其变炎烁，其眚燔焫，其味为苦，其志为喜。喜伤心，恐胜喜；热伤气，寒胜热；苦伤气，咸胜苦。
中央生湿，湿生土，土生甘，甘生脾，脾生肉，肉生肺。其在天为湿，在地为土，在体为肉，在气为充，在脏为脾。其性静兼，其德为濡，其用为化，其色为黄，其化为盈，其虫倮，其政为谧，其令云雨，其变动注，其眚淫溃，其味为甘，其志为思。思伤脾，怒胜思；湿伤肉，风胜湿；甘伤脾，酸胜甘。
西方生燥，燥生金，金生辛，辛生肺，肺生皮毛，皮毛生肾。其在天为燥，在地为金，在体为皮毛，在气为成，在脏为肺。其性为凉，其德为清，其用为固，其色为白，其化为敛，其虫介，其政为劲，其令雾露，其变肃杀，其眚苍落，其味为辛，其志为忧。忧伤肺，喜胜忧；热伤皮毛，寒胜热；辛伤皮毛，苦胜辛。
北方生寒，寒生水，水生咸，咸生肾，肾生骨髓，髓生肝。其在天为寒，在地为水，在体为骨，在气为坚，在脏为肾。其性为凛，其德为寒，其用为脏，其色为黑，其化为肃，其虫鳞，其政为静，其令霰雪，其变凝冽，其眚冰雹，其味为咸，其志为恐。恐伤肾，思胜恐；寒伤血，燥胜寒；咸伤血，甘胜咸。
五气更立，各有所先，非其位则邪，当其位则正。
帝曰：病生之变何如？
岐伯曰：气相得则微，不相得则甚。
帝曰：主岁何如？
岐伯曰：气有余则制己所胜而侮所不胜，其不及则己所不胜侮而乘之，己所胜轻而侮之。侮反受邪，侮而受邪，寡于畏也。
帝曰：善。', '', '', '', NULL, '', 'indent', 1586875699, '5e955cad4252a10008112405', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (645165, '黄帝内经 · 灵枢 · 顺气一日分为四时', NULL, 1, 81, 1, 1, '王冰', NULL, 37089, '5e9c39693aee4f0006e29695', '唐', 'wen', '文', '黄帝内经', '', '黄帝曰：夫百病之所以生者，必起于燥湿、寒暑、风雨、阴阳、喜怒、饮食、居处，气合而有形，得脏而有名，余知其然也。夫百病者，多以旦慧昼安，夕加夜甚，何也？岐伯曰：四时之气使然。
黄帝曰：愿闻四时之气。岐伯曰：春生，夏长，秋收，冬藏，是气之常也，人亦应之，以一日分为四时，朝则为春，日中为夏，日入为秋，夜半为冬。朝则人气始生，病气衰，故旦慧；日中人气长，长则胜邪，故安；夕则人气始衰，邪气始生，故加；夜半人气入脏，邪气独居于身，故甚也。
黄帝曰：其时有反者，何也？岐伯曰：是不应四时之气，脏独主其病者，是必以脏气之所不胜时者，甚；以其所胜时者，起也。
黄帝曰：治之奈何？岐伯曰：顺天之时而病可与期，顺者为工，逆者为粗。
黄帝曰：善，余闻刺有五变，以主五输。愿闻其数。岐伯曰：人有五脏，五脏有五变。五变有五输，故五五二十五输，以应五时。
黄帝曰：愿闻五变。岐伯曰：肝为牡藏，其色青，其时春，其音角，其味酸，其日甲乙；心为牡藏，其色赤，其时夏，其日丙丁，其音征，其味苦；脾为牝藏，其色黄，其时长夏，其日戊己，其音宫，其味甘；肺为牝藏，其色白，其音商，其时秋，其日庚辛，其味辛；肾为牝藏，其色黑，其时冬，其日壬癸，其音羽，其味咸。是为五变。
黄帝曰：以主五输奈何？藏主冬，冬刺井；色主春，春刺荥；时主夏刺输；音主长夏，长夏刺经；味主秋，秋刺合。是谓五变，以主五输。
黄帝曰：诸原安和，以致六输。岐伯曰：原独不应五时，以经合之，以应其数，故六六三十六输。
黄帝曰：何谓藏主冬，时主夏，音主长夏，味主秋，色主春。愿闻其故。岐伯曰：病在藏者，取之井；病变于色者，取之荥；病时间时甚者，取之输；病变于音者，取之经；经满而血者，病在胃；及以饮食不节得病者，取之于合，故命曰味主合。是谓五变也。', '', '', '', NULL, '', 'indent', 1586896122, '5e95ac76c769230008ed875f', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (645404, '鹊踏枝', NULL, 0, 6729, 1, 0, '屈大均', NULL, 15479, '5858ea131b69e6006cb11146', '清', 'shi', '诗', '', '', '乍似榆钱飞片片。湿尽花烟，珠泪无人见。江水添将愁更满。
茫茫直与长天远。
已过清明风未转。妾处春寒，郎处春应暖。枉作金炉朱火断，水沉多日无香篆。', '', '', '', '[{"bookId": "60fc157134bfda01e0e91549", "bookTitle": "元明清词鉴赏辞典（新一版）", "articleId": "610e86562cee9a0c24ecc4b8", "shortContent": "屈大均，明亡后长期奔走南北，间关绝徼，从事地下抗清活动。他的诗词作品大多是表现抗清复明这一主题，而且自认为是屈原的苗裔，故常效法屈原，擅长以香草美人的手法，表现其爱国忠君的思想。本词从词面上看，是写思妇怀人。那是春夏之交的绵绵雨季，整个空间被烟雨笼罩着，寂寞，沉闷，更增添几多浓浓的愁思。词人发唱惊庭，首先用夸张的比喻来描写雨之滂沱，“湿尽”两字写透了雨势。而在绵绵春雨下面，独处女子无尽的相思之愁，...", "authors": ["马亚中"], "pressName": "上海辞书出版社"}, {"bookId": "6464506e7f27182da3524606", "bookTitle": "元明清词三百首鉴赏辞典", "articleId": "646af0e545e4710056dde03b", "shortContent": "屈大均，明亡后长期奔走南北，间关绝徼，从事地下抗清活动。他的诗词作品大多是表现抗清复明这一主题，而且自认为是屈原的苗裔，故常效法屈原，擅长以香草美人的手法，表现其爱国忠君的思想。本词从词面上看，是写思妇怀人。那是春夏之交的绵绵雨季，整个空间被烟雨笼罩着，寂寞，沉闷，更增添几多浓浓的愁思。词人发唱惊庭，首先用夸张的比喻来描写雨之滂沱，“湿尽”两字写透了雨势。而在绵绵春雨下面，独处女子无尽的相思之愁，...", "authors": ["马亚中"], "pressName": "上海辞书出版社"}]', '', 'center', 1587069537, '5e9851dd6fa52e0008d47a94', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (645599, '资治通鉴 · 卷二十五 · 汉纪十七', NULL, 0, 1577, 1, 1, '司马光', NULL, 10351, '57b9c6d179bc4400639cc661', '宋', 'wen', '文', '资治通鉴', '', '起阏逢摄提格，尽屠维协洽，凡六年。
中宗孝宣皇帝上之下地节三年（甲寅，公元前六七年）
春，三月，诏曰：“盖闻有功不赏，有罪不诛，虽唐、虞不能以化天下。今胶东相王成，劳来不怠，流民自占八万馀口，治有异等之效。其赐成爵关内侯，秩中二千石。”未及征用，会病卒官。后诏使丞相、御史问郡、国上计长史、守丞以政令得失。或对言：“前胶东相成伪自增加以蒙显赏。”是后俗吏多为虚名云。
夏，四月，戊申，立子奭为皇太子，以丙吉为太傅，太中大夫疏广为少傅。封太子外祖父许广汉为平恩侯。又封霍光兄孙中郎将云为冠阳侯。霍显闻立太子，怒恚不食，欧血，曰：“此乃民间时子，安得立！即后有子，反为王邪！”复教皇后令毒太子。皇后数召太子赐食，保、阿辄先尝之，后挟毒不得行。
五月，甲申，丞相贤以老病乞骸骨；赐黄金百斤、安车、驷马，罢就第。丞相致仕自贤始。
六月，壬辰，以魏相为丞相。辛丑，丙吉为御史大夫，疏广为太子太傅，广兄子受为少傅。太子外祖父平恩侯许伯，以为太子少，白使其弟中郎将舜监护太子家。上以问广，广对曰：“太子，国储副君，师友必于天下英俊，不宜独亲外家许氏。且太子自有太傅、少傅，官属已备，今复使舜护太子家，示陋，非所以广太子德于天下也。”上善其言，以语魏相，相免冠谢曰：“此非臣等所能及。”广由是见器重。
京师大雨雹，大行丞东海萧望之上疏，言大臣任政，一姓专权之所致。上素闻望之名，拜为谒者。时上博延贤俊，民多上书言便宜，辄下望之问状；高者请丞相、御史，次者中二千石试事，满岁以状闻；下者报闻，罢。所白处奏皆可。
冬，十月，诏曰：“乃者九月壬申地震，朕甚惧焉。有能箴朕过失，及贤良方正直言极谏之士，以匡朕之不逮，毋讳有司。朕既不德，不能附远，是以边境屯戍未息。今复饬兵重屯，久劳百姓，非所以绥天下也。其罢车骑将军、右将军屯兵。”又诏：“池籞未御幸者，假与贫民。郡国宫馆勿复修治。流民还归者，假公田，贷种食，且勿算事。”
霍氏骄侈纵横。太夫人显，广治第室，作乘舆辇，加画，绣絪冯，黄金涂；韦絮荐轮，侍婢以五采丝輓显游戏第中；与监奴冯子都乱。而禹、山亦并缮治第宅，走马驰逐平乐馆。云当朝请，数称病私出，多从宾客，张围猎黄山苑中，使仓头奴上朝谒，莫敢谴者。显及诸女昼夜出入长信宫殿中，亡期度。
帝自在民间，闻知霍氏尊盛日久，内不能善。既躬亲朝政，御史大夫魏相给事中。显谓禹、云、山：“女曹不务奉大将军馀业，今大夫给事中，他人壹间女，能复自救邪！”后两家奴争道，霍氏奴入御史府，欲躢大夫门；御史为叩头谢，乃去。人以谓霍氏，显等始知忧。
会魏大夫为丞相，数燕见言事；平恩侯与侍中金安上等径出入省中。时霍山领尚书，上令吏民得奏封事，不关尚书，群臣进见独往来，于是霍氏甚恶之。上颇闻霍氏毒杀许后而未察，乃徙光女婿度辽将军、未央卫尉、平陵侯范明友为光禄勋，出次婿诸吏、中郎将、羽林监任胜为安定太守。数月，复出光姊婿给事中、光禄大夫张朔为蜀郡太守，群孙婿中郎将王汉为武威太守。顷之，复徙光长女婿长乐卫尉邓广汉为少府。戊戌，更以张安世为卫将军，两宫卫尉、城门、北军兵属焉。以霍禹为大司马，冠小冠，亡印绶；罢其屯兵官属，特使禹官名与光俱大司马者。又收范明友度辽将军印绶，但为光禄勋；及光中女婿赵平为散骑、骑都尉、光禄大夫，将屯兵，又收平骑都尉印绶。诸领胡、越骑、羽林及两宫卫将屯兵，悉易以所亲信许、史子弟代之。
初，孝武之世，征发烦数，百姓贫耗，究民犯法，奸轨不胜，于是使张汤、赵禹之属，条定法令，作见知故纵、监临部主之法，缓深、故之罪，急纵、出之诛。其后奸猾巧法转相比况，禁罔浸密，律令烦苛，文书盈于几阁，典者不能遍睹。是以郡国承用者驳，或罪同而论异，奸吏因缘为市，所欲活则傅生议，所欲陷则予死比，议者咸冤伤之。
廷尉史巨鹿路温舒上书曰：“臣闻齐有无知之祸而桓公以兴，晋有骊姬之难而文公用伯。近世赵王不终，诸吕作乱，而孝文为太宗。繇是观之，祸乱之作，将以开圣人也。夫继变乱之后，必有异旧之恩，此贤圣所以昭天命也。往者昭帝即世无嗣，昌邑淫乱，乃皇天所以开至圣也。臣闻《春秋》正即位、大一统而慎始也。陛下初登至尊，与天合符，宜改前世之失，正始受命之统，涤烦文，除民疾，以应天意。臣闻秦有十失，其一尚存，治狱之吏是也。夫狱者，天下之大命也，死者不可复生，绝者不可复属。《书》曰：‘与其杀不辜，宁失不经。’今治狱吏则不然，上下相驱，以刻为明，深者获公名，平者多后患，故治狱之吏皆欲人死，非憎人也，自安之道在人之死。是以死人之血流离于市，被刑之徒，比肩而立，大辟之计，岁以万数。此仁圣之所以伤也，太平之未洽，凡以此也。夫人情，安则乐生，痛则思死，棰楚之下，何求而不得！故囚人不胜痛，则饰辞以示之；吏治者利其然，则指导以明之；上奏畏却，则锻练而周内之。盖奏当之成，虽皋陶听之，犹以为死有馀辜。何则？成练者众，文致之罪明也。故俗语曰：‘画地为狱，议不入；刻木为吏，期不对。’此皆疾吏之风，悲痛之辞也。唯陛下省法制，宽刑罚，则太平之风可兴于世。”上善其言。
十二月，诏曰：“间者吏用法巧文浸深，是朕之不德也。夫决狱不当，使有罪兴邪，不辜蒙戮，父子悲恨，朕甚伤之！今遣廷史与郡鞠狱，任轻禄薄，其为置廷尉平，秩六百石，员四人。其务平之，以称朕意！”于是每季秋后请谳时，上常幸宣室，斋居而决事，狱刑号为平矣。
涿郡太守郑昌上疏言：“今明主躬垂明听，虽不置廷平，狱将自正；若开后嗣，不若删定律令。律令一定，愚民知所避，奸吏无所弄矣。今不正其本，而置廷平以理其末，政衰听怠，则廷平将召权而为乱首矣。”
昭帝时，匈奴使四千骑田车师。及五将军击匈奴，车师田者惊去，车师复通于汉；匈奴怒，召其太子军宿，欲以为质。军宿，焉耆外孙，不欲质匈奴，亡走焉耆，车师王更立子乌贵为太子。及乌贵立为王，与匈奴结婚姻，教匈奴遮汉道通乌孙者。
是岁，侍郎会稽郑吉与校尉司马喜，将免刑罪人田渠犁，积谷，发城郭诸国兵万馀人与所将田士千五百人共击车师，破之；车师王请降。匈奴发兵攻车师；吉、喜引兵北逢之，匈奴不敢前。吉、喜即留一候与卒二十人留守王，吉等引兵归渠犁。车师王恐匈奴兵复至而见杀也，乃轻骑奔乌孙。吉即迎其妻子，传送长安。匈奴更以车师王昆弟兜莫为车师王，收其馀民东徙，不敢居故地；而郑吉始使吏卒三百人往田车师地以实之。
上自初即位，数遣使者求外家；久远，多似类而非是。是岁，求得外祖母王媪及媪男无故、武。上赐无故、武爵关内侯。旬月间，赏赐以巨万计。
中宗孝宣皇帝上之下地节四年（乙卯，公元前六六年）
春，二月，赐外祖母号为博平君；封舅无故为平昌侯，武为乐昌侯。
夏，五月，山阳、济阴雹如鸡子，深二尺五寸，杀二十馀人，飞鸟皆死。
诏：“自今子有匿父母、妻匿夫、孙匿大父母，皆勿治。”
立广川惠王孙文为广川王。
霍显及禹、山、云自见日侵削，数相对啼泣自怨。山曰：“今丞相用事，县官信之，尽变易大将军时法令，发扬大将军过失。又，诸儒生多窭人子，远客饥寒，喜妄说狂言，不避忌讳，大将军常雠之。今陛下好与诸儒生语，人人自书对事，多言我家者。尝有上书言我家昆弟骄恣，其言绝痛；山屏不奏。后上书者益黠，尽奏封事，辄使中书令出取之，不关尚书，益不信人。又闻民间讙言‘霍氏毒杀许皇后’，宁有是邪？”显恐急，即具以实告禹、山、云。禹、山、云惊曰：“如是，何不早告禹等！县官离散、斥逐诸婿，用是故也。此大事，诛罚不小，奈何？”于是始有邪谋矣。
云舅李竟民善张赦，见云家卒卒，谓竟曰：“今丞相与平恩侯用事，可令太夫人言太后，先诛此两人。移徙陛下，在太后耳。”长安男子张章告之，事下廷尉、执金吾，捕张赦等。后有诏，止勿捕。山等愈恐，相谓曰：“此县官重太后，故不竟也。然恶端已见，久之犹发，发即族矣，不如先也。”遂令诸女各归报其夫，皆曰：“安所相避！”
会李竟坐与诸侯王交通，辞语及霍氏，有诏：“云、山不宜宿卫，免就第。”山阳太守张敞上封事曰：“臣闻公子季友有功于鲁，赵衰有功于晋，田完有功于齐，皆畴其庸，延及子孙。终后田氏篡齐，赵氏分晋，季氏颛鲁。故仲尼作《春秋》，迹盛衰，讥世卿最甚。乃者大将军决大计，安宗庙，定天下，功亦不细矣。夫周公七年耳，而大将军二十岁，海内之命断于掌握。方其隆盛时，感动天地，侵迫阴阳。朝臣宜有明言曰：‘陛下褒宠故大将军以报功德足矣。间者辅臣颛政，贵戚太盛，君臣之分不明，请罢霍氏三侯皆就第；及卫将军张安世，宜赐几杖归休，归存问召见，以列侯为天子师。’明诏以恩不听，群臣以义固争而后许之，天下必以陛下为不忘功德而朝臣为知礼，霍氏世世无所患苦。今朝廷不闻直声，而令明诏自亲其文，非策之得者也。今两侯已出，人情不相远，以臣心度之，大司马及其枝属必有畏惧之心。夫近臣自危，非完计也。臣敞愿于广朝白发其端，直守远郡，其路无由。唯陛下省察。”上甚善其计，然不召也。
禹、山等家数有妖怪，举家忧愁。山曰：“丞相擅减宗庙羔、菟、蛙，可以此罪也。”谋令太后为博平君置酒，召丞相、平恩侯以下，使范明友、邓广汉承太后制引斩之，因废天子而立禹。约定，未发，云拜为玄菟太守，太中大夫任宣为代郡太守。会事发觉，秋，七月，云、山、明友自杀，显、禹、广汉等捕得；禹要斩，显及诸女昆弟皆弃市；与霍氏相连坐诛灭者数十家。太仆杜延年以霍氏旧人，亦坐免官。八月，己酉，皇后霍氏废，处昭台宫，乙丑，诏封告霍氏反谋者男子张章、期门董忠、左曹杨恽、侍中金安上、史高皆为列侯。恽，丞相敞子；安上，车骑将军日磾弟子；高，史良娣兄子也。
初，霍氏奢侈，茂陵徐生曰：“霍氏必亡。夫奢则不逊，不逊必侮上。侮上者，逆道也，在人之右，众必害之。霍氏秉权日久，害之者多矣。天下害之，而又行以逆道，不亡何待！”乃上疏言：“霍氏泰盛，陛下即爱厚之，宜以时抑制，无使至亡。”书三上，辄报闻。其后霍氏诛灭，而告霍氏者皆封，人为徐生上书曰：“臣闻客有过主人者，见其灶直突，傍有积薪，客谓主人：‘更为曲突，远徙其薪，不者且有火患。’主人嘿然不应。俄而家果失火，邻里共救之，幸而得息。于是杀牛置酒，谢其邻人，灼烂者在于上行，馀各以功次坐，而不录言曲突者。人谓主人曰：‘乡使听客之言，不费牛酒，终亡火患。今论功而请宾，曲突徙薪无恩泽，焦头烂额为上客邪？’主人乃寤而请之。今茂陵徐福，数上书言霍氏且有变，宜防绝之。乡使福说得行，则国无裂土出爵之费，臣无逆乱诛灭之败。往事既已，而福独不蒙其功，唯陛下察之，贵徙薪曲突之策，使居焦发灼烂之右。”上乃赐福帛十匹，后以为郎。
帝初立，谒见高庙，大将军光骖乘，上内严惮之，若有芒刺在背。后车骑将军张安世代光骖乘，天子从容肆体，甚安近焉。及光身死而宗族竟诛，故俗传霍氏之祸萌于骖乘。后十二岁，霍后复徙云林馆，乃自杀。
班固赞曰：霍光受襁褓之托，任汉室之寄，匡国家，安社稷，拥昭，立宣，虽周公、阿衡何以加此！然光不学亡术，闇于大理；阴妻邪谋，立女为后，湛溺盈溢之欲，以增颠覆之祸，死财三年，宗族诛夷，哀哉！
臣光曰：霍光之辅汉室，可谓忠矣；然卒不能庇其宗，何也？夫威福者，人君之器也。人臣执之，久而不归，鲜不及矣。以孝昭之明，十四而知上官桀之诈，固可以亲政矣，况孝宣十九即位，聪明刚毅，知民疾苦，而光久专大柄，不知避去，多置亲党，充塞朝廷，使人主蓄愤于上，吏民积怨于下，切齿侧目，待时而发，其得免于身幸矣，况子孙以骄侈趣之哉！虽然，向使孝宣专以禄秩赏赐富其子孙，使之食大县，奉朝请，亦足以报盛德矣；乃复任之以政，授之以兵，及事丛衅积，更加裁夺，遂至怨惧以生邪谋，岂徒霍氏之自祸哉？亦孝宣酝酿以成之也。昔椒作乱于楚，庄王灭其族而赦箴尹克黄，以为子文无后，何以劝善。夫以显、禹、云、山之罪，虽应夷灭，而光之忠勋不可不祀；遂使家无噍类，孝宣亦少恩哉！
九月，诏减天下盐贾。又令郡国岁上系囚以掠笞若瘐死者，所坐县、名、爵、里，丞相、御史课殿最以闻。
十二月，清河王年坐内乱废，迁房陵。
是岁，北海太守庐江硃邑以治行第一入为大司农，勃海太守龚遂入为水衡都尉。先是，勃海左右郡岁饥，盗贼并起，二千石不能禽制。上选能治者，丞相、御史举故昌邑郎中令龚遂，上拜为勃海太守。召见，问：“何以治勃海，息其盗贼？”对曰：“海濒遐远，不沾圣化，其民困于饥寒而吏不恤，故使陛下赤子盗弄陛下之兵于潢池中耳。今欲使臣胜之邪，将安之也？”上曰：“选用贤良，固欲安之也。”遂曰：“臣闻治乱民犹治乱绳，不可急也；唯缓之，然后可治。臣愿丞相、御史且无拘臣以文法，得一切便宜从事。”上许焉，加赐黄金赠遣。乘传至勃海界，郡闻新太守至，发兵以迎。遂皆遣还。移书敕属县：“悉罢逐捕盗贼吏，诸持锗、钩、田器者皆为良民，吏毋得问；持兵者乃为贼。”遂单车独行至府。盗贼闻遂教令，即时解散，弃其兵弩而持钩、钅且，于是悉平，民安土乐业。遂乃开仓廪假贫民，选用良吏尉安牧养焉。遂见齐俗奢侈，好末技，不田作，乃躬率以俭约，劝民务农桑，各以口率种树畜养。民有带持刀剑者，使卖剑买牛，卖刀买犊，曰：“何为带牛佩犊！”劳来循行，郡中皆有畜积，狱讼止息。
乌孙公主女为龟兹王降宾夫人。绛宾上书言：“得尚汉外孙，愿与公主女俱入朝。”
中宗孝宣皇帝上之下元康元年（丙辰，公元前六五年）
春，正月，龟兹王及其夫人来朝；皆赐印绶，夫人号称公主，赏赐甚厚。
初作杜陵。徙丞相、将军、列侯、吏二千石、訾百万者杜陵。
三月，诏以凤皇集泰山、陈留，甘露降未央宫，赦天下。有司复言悼园宜称尊号曰皇考；夏，五月，立皇考庙。
冬，置建章卫尉。
赵广汉好用世吏子孙新进年少者，专厉强壮蜂气，见事风生，无所回避，率多果敢之计，莫为持难，终以此败。广汉以私怨论杀男子荣畜，人上书言之，事下丞相、御史按验。广汉疑丞相夫人杀侍婢，欲以此胁丞相，丞相按之愈急。广汉乃将吏卒入丞相府，召其夫人跪庭下受辞，收奴婢十馀人去。丞相上书自陈，事下廷尉治，实丞相自以过谴笞傅婢，出至外第乃死，不如广汉言。帝恶之，下广汉廷尉狱。吏民守阙号泣者数万人，或言：“臣生无益县官，愿代赵京兆死，使牧养小民！”广汉竟坐要斩。广汉为京兆尹，廉明，威制豪强，小民得职，百姓追思歌之。
是岁，少府宋畴坐议“凤皇下彭城，未至京师，不足美”，贬为泗水太傅。
上迁博士、谏大夫通政事者补郡国守相，以萧望之为平原太守。望之上疏曰：“陛下哀愍百姓，恐德之不究，悉出谏官以补郡吏。朝无争臣，则不知过，所谓忧其末而忘其本者也。”上乃征望之入守少府。
东海太守河东尹翁归，以治郡高第入为右扶风。翁归为人，公廉明察，郡中吏民贤、不肖及奸邪罪名尽知之。县县各有记籍，自听其政；有急名则少缓之。吏民小解，辄披籍。取人必于秋冬课吏大会中及出行县，不以无事时。其有所取也，以一警百。吏民皆服，恐惧，改行自新。其为扶风，选用廉平疾奸吏以为右职，接待以礼，好恶与同之；其负翁归，罚亦必行。然温良谦退，不以行能骄人，故尤得名誉于朝廷。
初，乌孙公主少子万年有宠于莎车王。莎车王死而无子，时万年在汉，莎车国人计，欲自托于汉，又欲得乌孙心，上书请万年为莎车王。汉许之，遣使者奚充国送万年。万年初立，暴恶，国人不说。
上令群臣举可使西域者，前将军韩增举上党冯奉世以卫候使持节送大苑诸国客至伊循城。会故莎车王弟呼屠征与旁国共杀其王万年及汉使者奚充国，自立为王。时匈奴又发兵攻车师城，不能下而去。莎车遣使扬言“北道诸国已属匈奴矣”，于是攻劫南道，与歃盟畔汉，从鄯善以西皆绝不通。都护郑吉、校尉司马喜甏皆在北道诸国间，奉世与其副严昌计，以为不亟击之，则莎车日强，其势难制，必危西域，遂以节谕告诸国王，因发其兵，南北道合万五千人，进击莎车，攻拔其城。莎车王自杀，传其首诣长安，更立它昆弟子为莎车王。诸国悉平，威振西域，奉世乃罢兵以闻。帝召见韩增曰：“贺将军所举得其人。”
奉世遂西至大宛。大宛闻其斩莎车王，敬之异于它使，得其名马象龙而还。上甚说，议封奉世。丞相、将军皆以为可，独少府萧望之以为：“奉世奉使有指，而擅矫制违命，发诸国兵，虽有功效，不可以为后法。即封奉世，开后奉使者利以奉世为比，争逐发兵，要功万里之外，为国家生事于夷狄，渐不可长。奉世不宜受封。”上善望之议，以奉世为光禄大夫。
中宗孝宣皇帝上之下元康二年（丁巳，公元前六四年）
春，正月，赦天下。上欲立皇后，时馆陶主母华婕妤及淮阳宪王母张婕妤、楚孝王母卫婕妤爱幸。上欲立张婕妤为后；久之，惩艾霍氏欲害皇太子，乃更选后宫无子而谨慎者。二月，乙丑，立长陵王婕妤为皇后，令母养太子；封其父奉光为邛成侯。后无宠，希得进见。
五月，诏曰：“狱者，万民之命。能使生者不怨，死者不恨，则可谓文吏矣。今则不然。用法或持巧心，析律贰端，深浅不平，奏不如实，上亦亡由知，四方黎民将何仰哉！二千石各察官属，勿用此人。吏或擅兴徭役，饰厨传，称过使客，越职逾法以取名誉，譬如践薄冰以待白日，岂不殆哉！今天下颇被疾疫之灾，朕甚愍之，其令郡国被灾甚者，毋出今年租赋。”
又曰：“闻古天子之名，难知而易讳也；其更讳询。”
匈奴大臣皆以为“车师地肥美，近匈奴，使汉得之，多田积谷，必害人国，不可不争”，由是数遣兵击车师田者。郑吉将渠犁田卒七千馀人救之，为匈奴所围。吉上言：“东怀去渠犁千馀里，汉兵在渠犁者少，势不能相救，愿益田卒。”上与后将军赵充国等议，欲因匈奴衰弱，出兵击其右地，使不得复扰西域。
魏相上书谏曰：“臣闻之：救乱诛暴，谓之义兵，兵义者王；敌加于己，不得已而起者，谓之应兵，兵应者胜；争恨小故，不忍愤怒者，谓之忿兵，兵忿者败；利人土地、货宝者，谓之贪兵，兵贪者破；恃国家之大，矜民人之众，欲见威于敌者，谓之骄兵，兵骄者灭。此五者，非但人事，乃天道也。间者匈奴尝有善意，所得汉民，辄奉归之，未有犯于边境；虽争屯田车师，不足致意中。今闻诸将军欲兴兵入其地，臣愚不知此兵何名者也！今边郡困乏，父子共犬羊之裘，食草莱之实，常恐不能自存，难以动兵。‘军旅之后，必有凶年，’言民以其愁苦之气伤阴阳之和也。出兵虽胜，犹有后忧，恐灾害之变因此以生。今郡国守相多不实选，风俗尤薄，水旱不时。按今年计子弟杀父兄、妻杀夫者凡二百二十二人，臣愚以为此非小变也。今左右不忧此，乃欲发兵报纤介之忿于远夷，殆孔子所谓‘吾恐季孙之忧不在颛臾而在萧墙之内也’。”上从相言，止。遣长罗侯常惠将张掖、酒泉骑往车师，迎郑吉及其吏士还渠犁。召故车师太子军宿在焉耆者，立以为王；尽徙车师国民令居渠犁，遂以车师故地与匈奴。以郑吉为卫司马，使护善阝善以西南道。
魏相好观汉故事及便宜章奏，数条汉兴已来国家便宜行事及贤臣贾谊、晁错、董仲舒等所言，奏请施行之。相敕掾史按事郡国，及休告，从家还至府，辄白四方异闻。或有逆贼、风雨灾变，郡不上，相辄奏言之。与御史大夫丙吉同心辅政，上皆重之。
丙吉为人深厚，不伐善。自曾孙遭遇，吉绝口不道前恩，故朝廷莫能明其功也。会掖庭宫婢则令民夫上书，自陈尝有阿保之功，章下掖庭令考问，则辞引使者丙吉知状。掖庭令将则诣御史府以视吉，吉识，谓则曰：“汝尝坐养皇曾孙不谨，督笞汝，汝安得有功！独渭城胡组、淮阳郭征卿有恩耳。”分别奏组等共养劳苦状。诏吉求组、征卿；已死，有子孙，皆受厚赏。诏免则为庶人，赐钱十万。上亲见问，然后知吉有旧恩而终不言，上大贤之。
帝以萧望之经明持重，议论有馀，材任宰相，欲详试其政事，复以为左冯翊。望之从少府出为左迁，恐有不合意，即移病。上闻之，使侍中成都侯金安上谕意曰：“所用皆更治民以考功。君前为平原太守日浅，故复试之于三辅，非有所闻也。”望之即起视事。
初，掖庭令张贺数为弟车骑将军安世称皇曾孙之材美及征怪，安世辄绝止，以为少主在上，不宜称述曾孙。及帝即位而贺已死，上谓安世曰：“掖庭令平生称我，将军止之，是也。”上追思贺恩，欲封其冢为恩德侯，置守冢二百家。贺有子蚤死，子安世小男彭祖。彭祖又小与上同席研书指，欲封之，先赐爵关内侯。安世深辞贺封；又求损守冢户数，稍减至三十户。上曰：“吾自为掖庭令，非为将军也。”安世乃止，不敢复言。
上心忌故昌邑王贺，赐山阳太守张敞玺书，令谨备盗贼，察往来过客；毋下所赐书。敞于是条奏贺居处，著其废亡之效曰：“故昌邑王为人，青黑色，小目，鼻末锐卑，少须眉，身体长大，疾痿，行步不便。臣敞尝与之言，欲动观其意，即以恶鸟感之曰：‘昌邑多枭。’故王应曰：‘然。前贺西至长安，殊无枭；复来，东至济阳，乃复闻枭声。’察故王衣服、言语、跪起，清狂不惠。臣敞前言：‘哀王歌舞者张脩等十人无子，留守哀王园，请罢归。’故王闻之曰：‘中人守园，疾者当勿治，相杀伤者当勿法，欲令亟死。太守奈何而欲罢之？’其天资喜由乱亡，终不见仁义如此。”上乃知贺不足忌也。
中宗孝宣皇帝上之下元康三年（戊午，公元前六三年）
春，三月，诏封故昌邑王贺为海昏侯。
乙未，诏曰：“朕微眇时，御史大夫丙吉，中郎将史曾、史玄，长乐卫尉许舜，侍中、光禄大夫许延寿，皆与朕有旧恩，及故掖庭令张贺，辅导朕躬，修文学经术，恩惠卓异，厥功茂焉。《诗》不云乎：‘无德不报’，封贺所子弟子侍中、中郎将彭祖为阳都侯，追赐贺谥曰阳都哀侯，吉为博阳侯，曾为将陵侯，玄为平台侯，舜为博望侯，延寿为乐成侯。”贺有孤孙霸，年七岁，拜为散骑、中郎将，赐爵关内侯。故人下至郡邸狱复作尝有阿保之功者，皆受官禄、田宅、财物，各以恩深浅报之。
吉临当封，病；上忧其不起，将使人就加印绋而封之，及其生存也。太子太傅夏侯胜曰：“此未死也！臣闻有阴德者必飨其乐，以及子孙。今吉未获报而疾甚，非其死疾也。”后病果愈。
张安世自以父子封侯，在位太盛。乃辞禄，诏都内别藏张氏无名钱以百万数。安世谨慎周密，每定大政，已决，辄移病出。闻有诏令，乃惊，使吏之丞相府问焉。自朝廷大臣，莫知其与议也。尝有所荐，其人来谢，安世大恨，以为“举贤达能，岂有私谢邪！”绝弗复为通。有郎功高不调，自言安世，安世应曰：“君之功高，明主所知，人臣执事，何长短而自言乎！”绝不许。已而郎果迁。安世自见父子尊显，怀不自安，为子延寿求出补吏，上以为北地太守；岁馀，上闵安世年老，复征延寿为左曹、太仆。
夏，四月，丙子，立皇子钦为淮阳王。皇太子年十二，通《论语》、《孝经》。太傅疏广谓少傅受曰：“吾闻‘知足不辱，知止不殆。’今仕宦至二千石，官成名立，如此不去，惧有后悔。”即日，父子俱移病，上疏乞骸骨。上皆许之，加赐黄金二十斤，皇太子赠以五十斤。公卿故人设祖道供张东都门外，送者车数百两。道路观者皆曰：“贤哉二大夫！”或叹息为之下泣。
广、受归乡里，日令其家卖金共具，请族人、故旧、宾客，与相娱乐。或劝广以其金为子孙颇立产业者，广曰：“吾岂老悖不念子孙哉！顾自有旧田庐，令子孙勤力其中，足以共衣食，与凡人齐。今复增益之以为赢馀，但教子孙怠堕耳。贤而多财，则损其志；愚而多财，则益其过。且夫富者众之怨也，吾既无以教化子孙，不欲益其过而生怨。又此金者，圣主所以惠养老臣也，故乐与乡党、宗族共飨其赐，以尽吾馀日，不亦可乎！”于是族人悦服。
颍川太守黄霸使邮亭、乡官皆畜鸡、豚，以赡鳏、寡、贫、穷者；然后为条教，置父老、师帅、伍长，班行之于民间，劝以为善防奸之意，及务耕桑、节用、殖财、种树、畜养，去浮淫之费。其治，米盐靡密，初若烦碎，然霸精力能推行之。吏民见者，语次录绎，问它阴伏以相参考，聪明识事，吏悄不知所出，咸称神明，豪厘不敢有所欺。奸人去入它郡，盗贼日少。霸力行教化而后诛罚，务在成就全安长吏。许丞老，病聋，督邮白欲逐之。霸曰：“许丞廉吏，虽老，尚能拜起送迎，正颇重听何伤！且善助之，毋失贤者意！”或问其故，霸曰：“数易长吏，送故迎新之费，及奸吏因缘，绝簿书，盗财物，公私费耗甚多，皆当出于民。所易新吏又未必贤，或不如其故，徒相益为乱。凡治道，去其泰甚者耳。”霸以外宽内明，得吏民心，户口岁增，治为天下第一，征守京兆尹。顷之，坐法，连贬秩；有诏复归颍川为太守，以八百石居。
中宗孝宣皇帝上之下元康四年（己未，公元前六二年）
春，正月，诏：“年八十以上，非诬告、杀伤人，它皆勿坐。”
右扶风尹翁归卒，家无馀财。秋，八月，诏曰：“翁归廉平乡正，治民异等。其赐翁归子黄金百斤，以奉祭祀。”
上令有司求高祖功臣子孙失侯者，得槐里公乘周广汉等百三十六人，皆赐黄金二十斤，复其家，令奉祭祀，世世勿绝。
丙寅，富平敬侯张安世薨。
初，扶阳节侯韦贤薨，长子弘有罪系狱，家人矫贤令，以次子大河都尉玄成为后。玄成深知其非贤雅意，即阳为病狂，卧便利，妄笑语，昏乱。既葬，当袭爵，以狂不应召。大鸿胪奏状，章下丞相、御史案验。案事丞相史乃与玄成书曰：“古之辞让，必有文义可观，故能垂荣于后。今子独坏容貌，蒙耻辱为狂痴，光曜晻而不宣，微哉子之所托名也！仆素愚陋，过为宰相执事，愿少闻风声；不然，恐子伤高而仆为小人也。”玄成友人侍郎章亦上疏言：“圣王贵以礼让为国，宜优养玄成，勿枉其志，使得自安衡门之下。”而丞相、御史遂以玄成实不病，劾奏之，有诏勿劾，引拜；玄成不得已，受爵。帝高其节，以玄成为河南太守。
车师王乌贵之走乌孙也，乌孙留不遣。汉遣使责乌孙，乌孙送乌贵诣阙。
初，武帝开河西四郡，隔绝羌与匈奴相通之路，斥逐诸羌。不使居湟中地。及帝即位，光禄大夫义渠安国使行诸羌；先零豪言：“愿时度湟水北，逐民所不田处畜牧。”安国以闻。后将军赵充国劾安国奉使不敬。是后羌人旁缘前言，抵冒度湟水，郡县不能禁。
既而先零与诸羌种豪二百馀人解仇、交质、盟诅。上闻之，以问赵充国，对曰：“羌人所以易制者，以其种自有豪，数相攻击，势不壹也。往三十馀岁西羌反时，亦先解仇合约攻令居，与汉相距，五六年乃定。匈奴数诱羌人，欲与之共击张掖、酒泉地，使羌居之。间者匈奴困于西方，疑其更遣使至羌中与相结。臣恐羌变未止此，且复结联他种，宜及未然为之备。”后月馀，羌侯狼何果遣使至匈奴藉兵，欲击善阝善、敦煌以绝汉道。充国以为“狼何势不能独造此计，疑匈奴使已至羌中，先零、罕、幵乃解仇作约。到秋马肥，变必起矣。宜遣使者行边兵，豫为备敕，视诸羌毋令解仇，以发觉其谋。”于是两府复白遣义渠安国行视诸羌，分别善恶。是时，比年丰稔，谷石五钱。', '', '', '', NULL, '', 'indent', 1587374502, '5e9cf91d24339b0008133662', '', '', NULL, '', '', '', '', '', NULL, NULL, NULL, NULL);
INSERT INTO "works" ("id", "title", "show_order", "posts_count", "author_works_count", "quotes_count", "collections_count", "author", "author_desc", "author_id", "author_remote_id", "dynasty", "kind", "kind_cn", "baidu_wiki", "foreword", "content", "intro", "annotation", "translation", "appreciations", "master_comment", "layout", "highlighted_at", "remote_id", "title_tr", "author_tr", "author_desc_tr", "dynasty_tr", "kind_cn_tr", "foreword_tr", "content_tr", "intro_tr", "annotation_tr", "translation_tr", "master_comment_tr", "appreciations_tr") VALUES (645602, '资治通鉴 · 卷二十八 · 汉纪二十', NULL, 3, 1577, 1, 1, '司马光', NULL, 10351, '57b9c6d179bc4400639cc661', '宋', 'wen', '文', '', '', '起昭阳作噩，尽屠维单阏，凡七年。
孝元皇帝上初元元年（癸酉，公元前四八年）
春，正月，辛丑，葬孝宣皇帝于杜陵；赦天下。
三月，丙午，立皇后王氏，封后父禁为阳平候。
以三辅、太常、郡国公田及苑可省者振业贫民；赀不满千钱者，赋贷种、食。
封外祖父平恩戴侯同产弟子中常侍许嘉为平恩侯。
夏，六月，以民疾疫，令太官损膳，减乐府员，省苑马，以振困乏。
秋，九月，关东郡、国十一大水，饥，或人相食；转旁郡钱谷以相救。
上素闻琅邪王吉、贡禹皆明经洁行，遣使者征之。吉道病卒。禹至，拜为谏大夫。上数虚已问以政事，禹奏言：“古者人君节俭，什一而税，亡它赋役，故家给人足。高祖、孝文、孝景皇帝，宫女不过十馀人，厩马百馀匹。后世争为奢侈，转转益甚；臣下亦相放效。臣愚以为如太古难，宜少放古以自节焉。方今宫室已定，无可奈何矣；其馀尽可减损。故时齐三服官，输物不过十笥；方今齐三服官，作工各数千人，一岁费数巨万，厩马食粟将万匹。武帝时，又多取好女至数千人，以填后宫。及弃天下，多藏金钱、财物，鸟兽、鱼鳖凡百九十物；又皆以后宫女置于园陵。至孝宣皇帝时，陛下恶有所言，群臣亦随故事，甚可痛也！故使天下承化，取女皆大过度，诸侯妻妾或至数百人，豪富吏民畜歌者至数十人，是以内多怨女，外多旷夫。及众庶葬埋，皆虚地上以实地下。其过自上生，皆在大臣循故事之罪也。唯陛下深察古道，从其俭者。大减损乘舆服御器物，三分去二；择后宫贤者，留二十人，馀悉归之，及诸陵园女无子者，宜悉遣；厩马可无过数十匹，独舍长安城南苑地，以为田猎之囿。方今天下饥馑，可无大自损减以救之称天意乎！天生圣人，盖为万民，非独使自娱乐而已也。”天子纳善其言，下诏，令诸宫馆希御幸者勿缮治；太仆减谷食马；水衡省肉食兽。
臣光曰：忠臣之事君也，责其所难，则其易者不劳而正；补其所短，则其长者不劝而遂。孝元践位之初，虚心以问禹，禹宜先其所急，后其所缓。然则优游不断，谗佞用权，当时之大患也，而禹不以为言；恭谨节俭，孝元之素志也，而禹孜孜而言之，何哉！使禹之智足不以知，乌得为贤！知而不言，为罪愈大矣！
匈奴呼韩邪单于复上书，言民众困乏。诏云中、五原郡转谷二万斛以给之。
是岁，初置戊己校尉，使屯田车师故地。
孝元皇帝上初元二年（甲戌，公元前四七年）
春，正月，上行幸甘泉，郊泰畤。乐陵侯史高以外属领尚书事，前将军萧望之、光禄大夫周堪为之副。望之名儒，与堪皆以师傅旧恩，天子任之，数宴见，言治乱，陈王事。望之选白宗室明经有行散骑、谏大夫刘更生给事中，与侍中金敞并拾遗左右。四人同心谋议，劝导上以古制，多所欲匡正；上甚乡纳之。史高充位而已，由此与望之有隙。
中书令弘恭、仆射石显，自宣帝时久典枢机，明习文法；帝即位多疾，以显久典事，中人无外党，精专可信任，遂委以政，事无小大，因显白决，贵幸倾朝，百僚皆敬事显。显为人巧慧习事，能深得人主微指，内深贼，持诡辩，以中伤人，忤恨睚眦，辄被以危法；亦与车骑将军高为表里，议论常独持故事，不从望之等。
望之等患苦许、史放纵，又疾恭、显擅权，建白以为：“中书政本，国家枢机，宜以通明公正处之。武帝游宴后庭，故用宦者，非古制也。宜罢中书宦官，应古不近刑人之义。”由是大与高、恭、显忤。上初即位，谦让，重改作，议久不定，出刘更生为宗正。
望之、堪数荐名儒、茂材以备谏官，会稽郑朋阴欲附望之，上书言车骑将军高遣客为奸利郡国，及言许、史弟子罪过。章视周堪，堪白：“令朋待诏金马门。”朋奏记望之曰：“今将军规抚，云若管、晏而休，遂行日昃，至周、召乃留乎？若管、晏而休，则下走将归延陵之皋，没齿而已矣。如将军兴周、召之遗业，亲日昊之兼听，则下走其庶几愿竭区区奉万分之一！”望之始见朋，接待以意；后知其倾邪，绝不与通。朋，楚士，怨恨，更求入许、史，推所言许、史事，曰：“皆周堪、刘更生教我；我关东人，何以知此！”于是侍中许章白见朋。朋出，扬言曰：“我见言前将军小过五，大罪一。”待诏华龙行污秽，欲入堪等，堪等不纳，亦与朋相结。
恭、显令二人告望之等谋欲罢车骑将军，疏退许、史状，候望之出休日，令朋、龙上之。事下弘恭问状，望之对曰：“外戚在位多奢淫，欲以匡正国家，非为邪也。”恭、显奏：“望之、堪、更生朋党相称举，数谮诉大臣，毁离亲戚，欲以专擅权势。为臣不忠，诬上不道，请谒者召致廷尉。”时上初即位，不省召致廷尉为下狱也，可其奏。后上召堪、更生，曰：“系狱。”上大惊曰：“非但廷尉问邪！”以责恭、显，皆叩头谢。上曰：“令出视事。”恭、显因使史高言：“上新即位，未以德化闻于天下，而先验师傅。即下九卿、大夫狱，宜因决免。”于是制诏丞相、御史：“前将军望之，傅朕八年，无它罪过。今事久远，识忘难明，其赦望之罪，收前将军、光禄勋印绶；及堪、更生皆免为庶人。”
二月，丁巳，立弟竟为清河王。
戊午，陇西地震，败城郭、屋室，压杀人众。
三月，立广陵厉王子霸为王。
诏罢黄门乘舆狗马，水衡禁囿、宜春下苑、少府佽飞外池、严籞池田假与贫民。又诏赦天下，举茂材异等、直言极谏之士。
夏，四月，丁巳，立子骜为皇太子。待诏郑朋荐太原太守张敞，先帝名臣，宜傅辅皇太子。上以问萧望之，望之以为敞能吏，任治烦乱，材轻，非师傅之器。天子使使者征敞，欲以为左冯翊，会病卒。
诏赐萧望之爵关内侯，给事中，朝朔望。
关东饥，齐地人相食。
秋，七月，己酉，地复震。
上复征周堪、刘更生，欲以为谏大夫；弘恭、石显白，皆以为中郎。
上器重萧望之不已，欲倚以为相；恭、显及许、史子弟、侍中、诸曹皆侧目于望之等。更生乃使其外亲上变事，言“地震殆为恭等，不为三独夫动。臣愚以为宜退恭、显以章蔽善之罚，进望之等以通贤者之路。如此，则太平之门开，灾异之愿塞矣。”书奏，恭、显疑其更生所为，白请考奸诈，辞果服；遂逮更生系狱，免为庶人。
会望之子散骑、中郎亻及亦上书讼望之前事，事下有司，复奏：“望之前所坐明白，无谮诉者，而教子上书，称引亡辜之诗，失大臣体，不敬，请逮捕。”弘恭、石显等知望之素高节，不诎辱，建白：“望之前幸得不坐，复赐爵邑，不悔过服罪，深怀怨望，教子上书，归非于上，自以托师傅，终必不坐，非颇屈望之于牢狱，塞其怏怏心，则圣朝无以施恩厚。”上曰：“萧太傅素刚，安肯就吏！”显等曰：“人命至重，望之所坐，语言薄罪，必无所忧。”上乃可其奏。冬，十二月，显等封诏以付谒者，敕令召望之手付。因令太常急发执金吾车骑驰围其第。使都至，召望之。望之以问门下生鲁国硃云，云者，好节士，劝望之自裁。于是望之仰天叹曰：“吾尝备位将相，年逾六十矣，老入牢狱，苟求生活，不亦鄙乎！”字谓云曰：“游，趣和药来，无久留我死！”竟饮鸠自杀。天子闻之惊，拊手曰：“曩固疑其不就牢狱，果然杀吾贤傅！”是时，太官方上昼食，上乃却食，为之涕泣，哀动左右。于是召显等责问以议不详，皆免冠谢，良久然后已。上追念望之不忘，每岁时遣使者祠祭望之冢，终帝之世。
臣光曰：甚矣孝元之为君，易欺而难寤也！夫恭、显之谮诉望之，其邪说诡计，诚有所不能辨也。至于始疑望之不肯就狱，恭、显以为必无忧。已而果自杀，则恭、显之欺亦明矣。在中智之君，孰不感动奋发以厎邪臣之罚！孝元则不然。虽涕泣不食以伤望之，而终不能诛恭、显，才得其免冠谢而已。如此，则奸臣安所惩乎！是使恭、显得肆其邪心而无复忌惮者也。
是岁，弘恭病死，石显为中书令。
初，武帝灰南越，开置珠厓、儋耳郡，在海中洲上，吏卒皆中国人，多侵陵之。其民亦暴恶，自以阻绝，数犯吏禁，率数年壹反，杀吏；汉辄发兵击定之。二十馀年间，凡六反。至宣帝时，又再反。上即位之明年，珠厓山南县反，发兵击之。诸县更叛，连年不定。上博谋于群臣，欲大发军。待诏贾捐之曰：“臣闻尧、舜、禹之圣德，地方不过数千里，西被流沙，东渐于海，朔南暨声教，言欲与声教则治之，不欲与者不强治也。故君臣歌德，含气之物各得其宜。武丁、成王、殷、周之大仁也，然地东不过江、黄，西不过氐、羌，南不过蛮荆，北不过朔方，是以颂声并作，视听之类咸乐其生，越裳氏重九译而献，此非兵革之所能致也。以至于秦，兴兵远攻，贪外虚内而天下溃畔。孝文皇帝偃武行文，当此之时，断狱数百，赋役轻简。孝武皇帝厉兵马以攘四夷，天下断狱万数，赋烦役重，寇贼并起，军旅数发，父战死于前，子斗伤于后，女子乘亭障，孤儿号于道，老母、寡妇饮泣巷哭，是皆廓地泰大，征伐不休之故也。今关东民众久困，流离道路。人情莫亲父母，莫乐夫妇；至嫁妻卖子，法不能禁，义不能止，此社稷之忧也。今陛下不忍悁悁之忿，欲驱士众挤之大海之中，快心幽冥之地，非所以救助饥馑，保全元元也。诗云：‘蠢尔蛮荆，大邦为雠。’言圣人起则后服，中国衰则先畔，自古而患之，何况乃复其南方万里之蛮乎！骆越之人，父子同川而浴，相习以鼻饮，与禽兽无异，本不足郡县置也。颛颛独居一海之中，雾露气湿，多毒草、虫蛇、水土之害；人未见虏，战士自死。又非独珠厓有珠、犀、玳瑁也。弃之不足惜，不击不损威。其民譬犹鱼鳖，何足贪也！臣窃以往者羌军言之，暴师曾未一年，兵出不逾千里，费四十馀万万；大司农钱尽，乃以少府禁钱续之。夫一隅为不善，费尚如此，况于劳师远攻，亡士毋功乎！求之往古则不合，施之当今又不便，臣愚以为非冠带之国，《禹贡》所及，《春秋》所治，皆可且无以为。愿遂弃珠厓，专用恤关东为忧。”上以问丞相、御史。御史大夫陈万年以为当击，丞相于定国以为：“前日兴兵击之连年，护军都尉、校尉及丞凡十一人，还者二人，卒士及转输死者万人以上，费用三万万馀，尚未能尽降。今关东困乏，民难摇动，捐之议是，”上从之。捐之，贾谊曾孙也。
孝元皇帝上初元三年（乙亥，公元前四六年）
春，诏曰：“珠厓虏杀吏民，背畔为逆。今廷议者或言可击，或言可守，或欲弃之，其指各殊。朕日夜惟思议者之言，羞威不行，则欲诛之；狐疑辟难，则守屯田；通于时变，则忧万民。夫万民之饥饿与远蛮之不讨，危孰大焉？且宗庙之祭，凶年不备，况乎辟不嫌之辱哉！今关东大困，仓库空虚，无以相赡，又以动兵，非特劳民，凶年随之。其罢珠崖郡，民有慕义欲内属，便处之；不欲，勿强。”
夏，四月，乙末晦，茂陵白鹤馆灾；赦天下。
夏，旱。
立长沙炀王弟宗为王。
长信少府贡禹上言：“诸离宫及长乐宫卫，可减其太半以宽繇役。”六月，诏曰：“朕惟烝庶之饥寒，远离父母妻子，劳于非业之作，卫于不居之宫，恐非所以佐阴阳之道也。其罢甘泉、建章宫卫，令就农。百宫各省费。条奏，毋有所讳。”
是岁，上复擢周堪为光禄勋，堪弟子张猛为光禄大夫、给事中，大见信任。
孝元皇帝上初元四年（丙子，公元前四五年）
春，正月，上行幸甘泉，效泰畤。三月，行幸河东，祠后土；赦汾阴徒。
孝元皇帝上初元五年（丁丑，公元前四四年）
春，正月，以周子南君为周承休侯。三月，上行幸雍，祠五畤。
夏，四月，有星孛于参。
上用诸儒贡禹等之言，诏太官毋日杀，所具各减半；乘舆秣马，无乏正事而已。罢角抵、上林宫馆希御幸者、齐三服官、北假田官、盐铁官、常平仓。博士弟子毋置员，以广学者。令民有能通一经者。皆复。省刑罚七十馀事。
陈万年卒。六月，辛酉，长信少府贡禹为御史大夫。禹前后言得失书数十上，上嘉其质直，多采用之。
匈奴郅支单于自以道远，又怨汉拥护呼韩邪而不助己，困辱汉使者乾江乃始等；遣使奉献，因求侍子。汉议遣卫司马谷吉送之，御史大夫贡禹、博士东海匡衡以为：“郅支单于乡化末醇，所在绝远，宜令使者送其子，至塞而还。”吉上书言：“中国与夷狄有羁縻不绝之义，今既养全其子十年，德泽甚厚，空绝而不送，近从塞还，示弃捐不畜，使无乡从之心，弃前恩，立后怨，不便。议者见前江乃无应敌之数，智勇俱困，以致耻辱，即豫为臣忧。臣幸得建强汉之节，承明圣之诏，宣谕厚恩，不宜敢桀。若怀禽兽心，加无道于臣，则单于长婴大罪，必遁逃远舍，不敢近边。没一使以安百姓，国之计，臣之愿也。愿送到庭。”上许焉。既到，郅支单于怒，竟杀吉等；自知负汉，又闻呼韩邪益强，恐见袭击，欲远去。会康居王数为乌孙所困，与诸翕侯计，以为：“匈奴大国，乌孙素服属之。今郅支单于困在外，可迎置东边，使合兵取乌孙而立之，长无匈忧矣。”即使使到坚昆，通语郅支。郅支素恐，又怨乌孙，闻康居计，大说，遂与相结，引兵而西。郅支人众中寒道死，馀财三千人。到康居，康居王以女妻郅支，郅支亦以女予康居王，康居甚尊敬郅支，欲倚其威以胁诸国。郅支数借兵击乌孙，深入至谷城，杀略民人，驱畜产去。乌孙不敢追。西边空虚不居者五千里。
冬，十二月，丁末，贡禹卒。丁已，长信少府薛广德为御史大夫。
孝元皇帝上永光元年（戊寅，公元前四三年）
春，正月，上行幸甘泉，郊泰畤。视毕，因留射猎。薛广德上书曰：“窃见关东困极，人民流离。陛下日撞亡秦之钟，听郑、卫之乐，臣诚悼之。今士卒暴露，从官劳倦，愿陛下亟反宫，思与百姓同忧乐，天下幸甚！”上即日还。
二月，诏：“丞相、御史举质朴、敦厚、逊让、有行者，光禄岁以此科第郎、从官。”
三月，赦天下。
雨雪、陨霜，杀桑。秋，上酎祭宗庙，出便门，欲御楼船。薛广德当乘舆车，免冠顿首曰：“宜从桥。”诏曰：“大夫冠。”广德曰：“陛下不听臣，臣自刎，以血污车轮，陛下不得入庙矣！”上不说。先驱光禄大夫张猛进曰：“臣闻主圣臣直。乘船危，就桥安，圣主不乘危。御史大夫言可听。”上曰：“晓人不当如是邪！”乃从桥。
九月，陨霜杀稼，天下大饥。丞相于定国，大司马、车骑将军史高，御史大夫薛广德，俱以灾异乞骸骨。赐安车、驷马、黄金六十斤，罢。太子太傅韦玄成为御史大夫。广德归，县其安车，以传示子孙为荣。
帝之为太子也，从太中大夫孔霸受《尚书》。及即位，赐霸爵关内侯，号褒成君，给事中。上欲致霸相位，霸为人谦退，不好权势，常称“爵位泰过，何德以堪之！”御史大夫屡缺，上辄欲用霸；霸让位，自陈至于再三。上深知其至诚，乃弗用。以是敬之，赏赐甚厚。
戊子，侍中，卫尉王接为大司马、车骑将军。
石显惮周堪、张猛等，数谮毁之。刘更生惧其倾危，上书曰：“臣闻舜命九官，济济相让，和之至也。众臣和于朝则万物和于野，故箫《韶》九成，凤皇来仪。至周幽，厉之际，朝廷不和，转相非怨，则日月薄食，水泉沸腾，山谷易处，霜降失节。由此观之，和气致祥，乖气致异，祥多者其国安，异众者其国危。天地之常经，古今之通义也。今陛下开三代之业，招文学之士，优游宽容，使得并进。今贤不肖浑殽，白黑不分，邪正杂糅，忠谗并进；章交公车，人满北军，朝臣舛午，胶戾乖剌，更相谗诉，转相是非；所以营惑耳目，感移心意，不可胜载，分曹为党，往往群朋将同心以陷正臣。正臣进者，治之表也；正臣陷者，乱之机也；乘治乱之机，未知孰任，而灾异数见，此臣所以寒心者也。初元以来六年矣，按春秋六年之中，灾异未有稠如今者也。原其所以然者，由谗邪并进也；谗邪之所以并进者，由上多疑心，既已用贤人而行善政，如或谮之，则贤人退而善政还矣。夫执狐疑之心者，来谗贼之口；持不断之意者，开群枉之门；谗邪进则众贤退，群枉盛则正士消。故《易》有《否》、《泰》，小人道长，君子道消，则政日乱；君子道长，小人道消，则政日治。昔者鲧、共工、驩兜与舜、禹杂处尧朝，周公与管、蔡并居周位，当是时，迭进相毁，流言相谤，岂可胜道哉！帝尧、成王能贤舜、禹、周公而消共工、管、蔡，故以大治，荣华至今。孔子与季、孟偕仕于鲁，李斯与叔孙俱宦于秦，定公、始皇贤季、孟、李斯而消孔子、叔孙，故以大乱，污辱至今。故治乱荣辱之端，在所信任；信任既贤，在于坚固而不移。《诗》云：‘我心匪石，不可转也，言守善笃也。《易》曰：‘涣汗其大号’，言号令如汗，汗出而不反者也。今出善令未能逾时而反，是反汗也；用贤未能三旬而退，是转石也。《论语》曰：‘见不善如探汤。’今二府奏佞诌不当在位，历年而不去。故出令则如反汗，用贤则如转石，去佞则如拨山，如此，望阴阳之调，不亦难乎！是以群小窥见间隙，缘饰文字，巧言丑诋，流言、飞文哗于民间。故《诗》云：‘忧心悄悄，愠于群小，’小人成群，诚足愠也。昔孔子与颜渊、子贡更相称誉，不为朋党；禹、稷与皋陶传相汲引，不为比周，何则？忠于为国，无邪心也。今佞邪与贤臣并交戟之内，合党共谋，违善依恶，歙歙訿々，数设危险之言，欲以倾移主上，如忽然用之，此天地之所以先戒，灾异之所以重至者也。自古明圣未有无诛而治者也，故舜有四放之罚，孔子有两观之诛，然后圣化可得而行也。今以陛下明知，诚深思天地之心，览《否》、《泰》之卦，历周、唐之所
以为法，原秦、鲁之所消以为戒，考祥应之福。省灾异之祸，以揆当世之变，放远佞邪之党，坏散险诐之聚，杜闭群枉之门，方开众正之路，决断狐疑，分别犹豫，便是非炳然可知，则百异消灭而众祥并至，太平之基，万世之利也。”显见其书，愈与许、史比而怨更生等。
是岁，夏寒，日青无光，显及许、史皆言堪、猛用事之咎。上内重堪，又患众口之浸润，无所取信。时长安令杨兴以材能幸，常称誉堪，上欲以为助，乃见问兴：“朝臣龂龂不可光禄勋，何邪？”兴者，倾巧士，谓上疑堪，因顺指曰：“堪非独不可于朝廷，自州里亦不可也！臣见众人闻堪与刘更生等谋毁骨肉，以为当诛；故臣前书言堪不可诛伤，为国养恩也。”上曰：“然此何罪而诛？今宜奈何？”兴曰：“臣愚以为可赐爵关内侯，食邑三百户，勿令典事。明主不失师傅之恩，此最策之得者也。”上于是疑之。
司隶校尉琅邪诸葛丰始以特立刚直著名于朝，数侵犯贵戚，在位多言其短。后坐春夏系治人，徙城门校尉。丰于是上书告堪、猛罪，上不直丰，乃制诏御史：“城门校尉丰，前与光禄勋、光禄大夫猛在朝之时，数称言堪、猛之美。丰前为司隶校尉，不顺四时，修法度，专作苛暴以获虚威；朕不忍下吏，以为城门校尉。不内省诸己，而反怨堪、猛以求报举，告按无证之辞，暴扬难验之罪，毁誉恣意，不顾前言，不信之大也。朕怜丰之耆老，不忍加刑，其免为庶人！”又曰：“丰言堪、猛贞信不立，朕闵而不治，又惜其材能未有所效，其左迁堪为河东太守，猛槐里令。”
臣光曰：诸葛丰之于堪、猛，前誉而后毁，其志非为朝廷进善而去奸也，欲比周求进而已矣。斯亦郑朋、杨兴之流，乌在其为刚直哉！人君者，察美恶，辨是非，赏以劝善，罚以惩奸，所以为治也。使丰言得实，则丰不当绌；若其诬罔，则堪、猛何辜焉！今两责而俱弃之，则美恶、是非果何在哉！
贾捐之与杨兴善。捐之数短石显，以故不得官，稀复进见；兴新以材能得幸。捐之谓兴曰：“京兆尹缺，使我得见，言君兰，京兆尹可立得。”兴曰：“君房下笔，言语妙天下；使君房为尚书令，胜五鹿充宗远甚。”捐之曰：“令我得代充宗，君兰为京兆，京兆，郡国首，尚书，百官本，天下真大治，士则不隔矣！”捐之复短石显，兴曰：“显方贵，上信用之；今欲进，第从我计，且与合意，即得入矣！”捐之即与兴共为荐显奏，称誉其美，以为宜赐爵关内侯，引其兄弟以为诸曹；又共为荐兴奏，以为可试守京兆尹。石显闻知，白之上，乃下兴、捐之狱，令显治之，奏“兴，捐之怀诈伪，更相荐誉，欲得大位，罔上不道！”捐之竟坐弃市，兴髡钳为城旦。
臣光曰：君子以正攻邪，犹惧不克。况捐之以邪攻邪，其能免乎！
徙清河王竟为中山王。
匈奴呼韩邪单于民众益盛，塞下禽兽尽，单于足以自卫，不畏郅支，其大臣多劝单于北归者。久之，单于竟北归庭，民众稍稍归之，其国遂定。
孝元皇帝上永光二年（己卯，公元前四二年）
春，二月，赦天下。
丁酉，御史大夫韦玄成为丞相；右扶风郑弘为御史大夫。
三月，壬戌朔，日有食之。
夏，六月，赦天下。
上问给事中匡衡以地震日食之变，衡上疏曰：“陛下躬圣德，开太平之路，闵愚吏民触法抵禁，比年大赦，使百姓得改行自新，天下幸甚！臣窃见大赦之后，奸邪不为衰止，今日大赦，明日犯法，相随入狱，此殆导之未得其务也。今天下俗，贪财贱义，好声色，上侈靡，亲戚之恩薄，婚姻之党隆，苟合徼幸，以身设利；不改其原，虽岁赦之，刑犹难使错而不用也，臣愚以为宜壹旷然大变其俗。夫朝廷者，天下之桢幹也。朝有变色之言，则下有争斗之患；上有自专之士，则下有不让之人；上有克胜之佐，则下有伤害之心；上有好利之臣，则下有盗窃之民；此其本也。治天下者，审所上而已。教化之流，非家至而人说之也；贤者在位，能者布职，朝廷崇礼，百僚敬让，道德之行，由内及外，自近者始，然后民知所法，迁善日进而不自知也。《诗》曰：‘商邑翼翼，四方之极。’今长安，天子之都，亲承圣化，然其习俗无以异于远方，郡国来者无所法则，或见侈靡而放效之；此教化之原本，风俗之枢机，宜先正者也。臣闻天人之际，精祲有以相荡，善恶有以相推，事作乎下者象动乎上，阴变则静者动，阳蔽则明者晻，水旱之灾随类而至。陛下祗畏天戒，哀闵元元，宜省靡丽，考制度，近忠正，远巧佞，以崇至仁，匡失俗，道德弘于京师，淑问扬乎疆外，然后大化可成，礼让可兴也。”上说其言，迁衡为光禄大夫。
荀悦论曰：夫赦者，权时之宜，非常典也。汉兴，承秦兵革之后，大愚之世，比屋可刑，故设三章之法，大赦之令，荡涤秽流，与民更始，时势然也。后世承业，袭而不革，失时宜矣。若惠、文之世，无所赦之。若孝景之时，七国皆乱，异心并起，奸诈非一；及武帝末年，赋役繁兴，群盗并起，加以太子之事，巫蛊之祸，天下纷然，百姓无聊，人不自安；及光武之际，拨乱之后：如此之比，宜为赦矣。
秋，七月，陇西羌彡姐旁种反，诏召丞相韦玄成等入议。是时，岁比不登，朝廷方以为忧，而遭羌变，玄成等漠然，莫有对者。右将军冯奉世曰：“羌虏近在竟内背畔，不以时诛，无以威制远蛮，臣愿帅师讨之！”上问用兵之数，对曰：“臣闻善用兵者，役不再兴，粮不三载，故师不久暴而天诛亟决。往者数不料敌，而师至于折伤，再三发调，则旷日烦费，威武亏矣。今反虏无虑三万人，法当倍，用六万人。然羌戎，弓矛之兵耳，器不犀利，可用四万人。一月足以决。”丞相、御史、两将军皆以为：“民方收敛时未可多发，发万人屯守之，且足。”奉世曰：“不可。天下被饥馑，士马羸耗，守战之备久废不简，夷狄有轻边吏之心，而羌首难。今以万人分屯数处，虏见兵少，必不畏惧。战则挫兵病师，守则百姓不救，如此，怯弱之形见。羌人乘利，诸种并和，相扇而起，臣恐中国之役不得止于四万，非财币所能解也。故少发师而旷日，与一举而疾决，利害相万也。”固争之，不能得。有诏，益二千人。于是遣奉世将万二千人骑，以将屯为名，典属国任立、护军都尉韩昌为偏裨，到陇西，分屯三处。昌先遣两校尉与羌战，羌虏盛多，皆为所破，杀两校尉。奉世具上地形部众多少之计，愿益三万六千人，乃足以决事。书奏，天子大为发兵六万馀人。八月，拜太常弋阳侯任千秋为奋武将军以助之。冬，十月，兵毕至陇西，十一月，并进，羌虏大破，斩首数千级，馀皆走出塞。兵未决间，汉复发募士万人，拜定襄太守韩安国为建威将军，未进，闻羌破而还。诏罢吏士，颇留屯田，备要害处。
